addon.quests = {
    [783] = { -- A Threat Within
        title = { "15:821953532:1775967377", "ภัยจากภายใน" },
        objective = { "27:794143152:684494105", "ไปคุยกับ Marshal McBride" },
        description = { "46:304255366:1231548139 C 414:924444042:572395018", "หวังว่าเจ้าจะรัดเข็มขัดมาพร้อมแล้วนะ {class} รุ่นเยาว์ ที่ Northshire นี่มีงานรอเจ้าอยู่\n\nและข้าก็ไม่ได้หมายถึงงานไร่\n\nทหารยามแห่ง Stormwind ต้องออกไปประจำการในแดนไกลกันมาก ขณะที่ภัยรอบตัวก็ใกล้เข้ามาทุกที พวกเราที่เหลือแทบจะรักษาความสงบที่นี่ไม่ไหว เราจึงขอแรงทุกคนที่พร้อมปกป้องบ้านเกิดและฝ่ายสัมพันธมิตร\n\nถ้าเจ้ามาเพราะเสียงเรียกนี้ จงไปคุยกับ Marshal McBride ผู้บังคับบัญชาของข้า เขาอยู่ในอารามข้างหลังข้านี่เอง" },
        completion = { "312:1406635934:848494954 N 36:1335101904:1973646972", "อา ดีเลย อาสาสมัครอีกคนแล้ว ช่วงนี้คนอย่างเจ้ามากันเยอะทีเดียว\n\nข้าหวังว่าจะพอ\n\nดินแดนมนุษย์ถูกรุกรานจากภายนอก เราต้องส่งกำลังไปต่างแดนเป็นจำนวนมาก พวกคนโกงกับพวกนอกกฎหมายเลยฉวยโอกาสตั้งตัวอยู่ในเขตแดนของเรา\n\nเราต้องรบหลายด้าน {name} เตรียมตัวไว้ให้ดี ศึกนี้อีกยาวนาน", variants = { { "92:1771234069:546371443 R 215:522211829:75716940 N 36:1335101904:1973646972", "อา ดีเลย อาสาสมัครอีกคนแล้ว ช่วงนี้คนอย่างเจ้ามากันเยอะทีเดียว\n\nข้าหวังว่าจะพอ\n\nดินแดน{race}ถูกรุกรานจากภายนอก เราต้องส่งกำลังไปต่างแดนเป็นจำนวนมาก พวกคนโกงกับพวกนอกกฎหมายเลยฉวยโอกาสตั้งตัวอยู่ในเขตแดนของเรา\n\nเราต้องรบหลายด้าน {name} เตรียมตัวไว้ให้ดี ศึกนี้อีกยาวนาน" } } },
    },
    [7] = { -- Kobold Camp Cleanup
        title = { "19:1660152344:1407525771", "กวาดล้างค่ายโคโบลด์" },
        objective = { "54:589107737:876446293", "กำจัด Kobold Vermin 10 ตัว แล้วกลับไปหา Marshal McBride" },
        description = { "37:505739317:644548732 N 176:458359054:250215820", "งานแรกของเจ้าคือกวาดล้างพื้นที่ {name} โคโบลด์เผ่าหนึ่งเข้ามายึดป่าทางเหนือ ไปที่นั่นแล้วจัดการพวก Kobold Vermin ที่พบ ลดจำนวนพวกมันลง เพื่อว่าสักวันเราจะขับไล่พวกมันออกจาก Northshire ได้" },
        progress = { "22:1587245246:68769387 N 43:1701841452:607777933", "การล่าเป็นอย่างไรบ้าง {name} เจอพวกตัวปัญหาแล้วจัดการพวกมันได้หรือยัง?" },
        completion = { "204:546115604:2124993099", "ทำได้ดีมาก พลเมืองเอ๋ย โคโบลด์พวกนั้นทั้งขี้ขลาดทั้งขี้ขโมย แต่พอรวมกันมากเข้าก็เป็นภัยต่อเรา ชาว Stormwind มีเรื่องให้รับมือมากพอแล้ว\n\nข้าขอบใจเจ้าที่ช่วยปราบพวกมัน" },
        objectiveLabels = {
            monster = { ["Kobold Vermin slain"] = "ปราบ โคโบลด์ตัวก่อกวน" },
        },
    },
    [33] = { -- Wolves Across the Border
        title = { "24:748661539:220879967", "ฝูงหมาป่าตามแนวชายแดน" },
        objective = { "80:1560241765:598844254", "นำ Tough Wolf Meat 8 ชิ้นไปให้ Eagan Peltskinner ที่ด้านนอก Northshire Abbey" },
        description = { "267:1103241754:1696326708", "ข้าเกลียดพวก Timber Wolf นั่นจริง ๆ! แต่ถ้าพูดถึงสเต๊กเนื้อหมาป่าละก็... ของโปรดเลย เอาเนื้อหมาป่าเหนียว ๆ มาให้ข้าสิ ข้ามีของที่เจ้าน่าจะได้ใช้มาแลก\n\nเนื้อแบบนั้นหาได้จากการล่า Timber Wolf และ Young Wolfที่เดินเพ่นพ่านอยู่แถบชนบทของ Northshire" },
        progress = { "4:1228872774:163611696 N 56:468321628:492000656", "ว่าไง {name} ข้าเริ่มหิวแล้วสิ... ได้เนื้อหมาป่ามาหรือยัง?" },
        completion = { "116:919948203:1079329634", "ขยันล่าจริงนะเจ้า! ข้าชักอยากเอาเนื้อหมาป่านั่นลงกระทะแล้วสิ...\n\nข้ามีของที่เจ้าน่าจะอยากได้อยู่ตรงนี้ เลือกเอาได้เลย!" },
        required = { [750] = { "15:1282067459:1495470117", "เนื้อหมาป่าเหนียว" } },
        steps = { { "15:1282067459:1495470117", "เนื้อหมาป่าเหนียว" } },
    },
    [4641] = { -- Your Place In The World
        title = { "23:1769173590:627623901", "ที่ของเจ้าในโลกนี้", variants = { { "23:343116409:1999771303", "ที่ของเจ้าในโลกนี้" } } },
        objective = { "143:808818037:1240386569", "ไปคุยกับ Gornek เขาอยู่ในอาคารที่เรียกว่า The Den ทางตะวันตก ตามจุดที่ Kaltunk ทำเครื่องหมายไว้บนแผนที่ของเจ้า" },
        description = { "25:1276565300:867025123 N 396:464741558:1959064627 C 47:1107725654:397324871", "ในที่สุดเจ้าก็โตพอแล้ว {name}... โตพอจะรบในนามของ Horde และพิชิตศึกเพื่อเกียรติของจอมทัพ\n\nใช่แล้ว...\n\n<Kaltunk มองเจ้าตั้งแต่หัวจรดเท้า>\n\nเจ้าคงใช้ได้ทีเดียว\n\nเจ้าคงอยากออกไปหามังกรยักษ์หรือปีศาจสักตัวแล้วบีบคอมันด้วยมือเปล่าละสิ แต่ถ้าให้ดี เริ่มจากอะไรที่มัน... อันตรายน้อยกว่านั้นสักหน่อยเถอะ\n\n<Kaltunk หัวเราะ>\n\nไปรายงานตัวกับ Gornek เขาคงหางานที่เหมาะกับ {class} มือใหม่อย่างเจ้าได้ เจ้าจะพบเขาที่ The Den ทางตะวันตก" },
        completion = { "233:772139683:683677183", "คนใหม่ที่ Kaltunk ส่งมาอีกรึ?\n\nถ้านี่คือคนที่เก่งที่สุดที่ Horde หาได้ สถานการณ์เราคงแย่เอาการ ช่างเถอะ กว่าเราจะเห็นว่าเจ้าพร้อมออกจากหุบเขานี้ เจ้าก็จะเป็นนักรบที่ภาคภูมิแห่ง Horde แล้ว" },
    },
    [788] = { -- Cutting Teeth
        title = { "13:1443532338:1130569410", "ประเดิมฝีมือ" },
        objective = { "55:1305981067:1560343396", "ฆ่า Mottled Boar 10 ตัว แล้วกลับไปหา Gornek ที่ The Den" },
        description = { "291:112862969:287062467", "อย่างแรกเราต้องฝึกให้เจ้าแข็งแกร่งขึ้นสักหน่อย ข้าจะส่งเจ้าไปล่าโคโดใน Barrens ก็ได้ แต่พูดกันตรง ๆ นะ ถ้าเจ้ายังเป็น ๆ อยู่ก็มีประโยชน์กับเรามากกว่า\n\nข้าว่าหมูป่าลายด่างทางเหนือของที่นี่น่าจะเป็นคู่มือที่พอดีกับเจ้า" },
        progress = { "86:1511808613:628939857 N 49:865426645:1668300349", "หวังว่าเจ้าคงไม่ได้กลับมาเพื่อกล่อมให้ข้าเชื่อว่าเจ้าทำงานเสร็จแล้วหรอกนะ {name}? คงไม่ใช่หรอก ข้าเชื่อว่าเจ้าดีกว่านั้น" },
        completion = { "15:1379852203:1664403935 N 241:953263433:1782850445", "อืม ใช้ได้นี่ {name} แต่อย่าเพิ่งลำพองใจไป... ชีวิตนักรบของเจ้ายังต้องเจออะไรที่รับมือยากกว่าหมูป่าอีกมาก\n\nถึงอย่างนั้น เจ้าก็พิสูจน์ฝีมือตัวเองได้ดี บททดสอบต่อไปจะให้เจ้าสู้กับคู่ต่อสู้ที่อันตรายกว่านี้มาก เจ้าต้องมีของป้องกันตัวเพิ่มสักหน่อย" },
        objectiveLabels = {
            monster = { ["Mottled Boar slain"] = "ปราบ หมูป่าลายด่าง" },
        },
    },
    [179] = { -- Dwarven Outfitters
        title = { "18:1731372975:1027348717", "เครื่องแต่งกายฝีมือคนแคระ" },
        objective = { "53:1508686996:37047953", "นำ Tough Wolf Meat 8 ชิ้นไปให้ Sten Stoutarm" },
        description = { "452:663465094:44044268", "ไหนดูซิ ดูท่าเจ้าจะอยากได้อะไรมาใส่ให้มืออุ่นขึ้นหน่อย ใช่ไหม?\n\nข้ารู้ว่าอะไรช่วยได้ ถุงมืออุ่น ๆ ดี ๆ สักคู่ไงล่ะ ข้าเป็นคนใจดีอยู่แล้ว ยินดีหาคู่ที่พอดีให้เจ้า แต่มีข้อแม้อยู่อย่าง\n\nข้าอยากให้เจ้าไปหาเนื้อหมาป่ามาให้หน่อย ตกลงกันง่าย ๆ เจ้าเอาเนื้อมาให้ข้า แล้วข้าจะช่วยให้นิ้วเจ้ารอดจากความหนาว เป็นไง ตกลงไหม?" },
        progress = { "105:742613636:433525729", "พวกหมาป่าทำเจ้าลำบากอยู่หรือ? ลองหลบเขี้ยว หลบกรงเล็บ แล้วก็ส่วนอื่น ๆ ที่มันแหลมคมดูสิ ว่าไหม?" },
        completion = { "64:556020352:1170103085 N 78:1701476536:921107656", "อา ยอดเลย! เนื้อหมาป่านี่ใช้ได้ทีเดียว ไม่ต้องห่วง {name} ข้าไม่ลืมส่วนของข้าหรอก เอ้า สักคู่ในนี้น่าจะพอดีกับเจ้า" },
        required = { [750] = { "15:1282067459:1495470117", "เนื้อหมาป่าเหนียว" } },
        steps = { { "15:1282067459:1495470117", "เนื้อหมาป่าเหนียว" } },
    },
    [456] = { -- The Balance of Nature
        title = { "21:1767005025:744312648", "สมดุลแห่งธรรมชาติ" },
        objective = { "88:595703640:929689712", "ฆ่า Young Nightsaber 7 ตัว และ Young Thistle Boar 4 ตัว แล้วกลับไปหา Conservator Ilthalaine" },
        description = { "11:927657569:725753248 N 387:773252907:1333172180 C 85:158646988:1258420965", "สวัสดี {name} ข้าคือ Conservator Ilthalaine หน้าที่ของข้าใน Shadowglen คือดูแลให้ธรรมชาติคงความสมดุล\n\nฤดูใบไม้ผลิปีนี้ฝนตกหนักเป็นพิเศษ สัตว์ป่าบางชนิดจึงเพิ่มจำนวนได้ดี ขณะที่บางชนิดกลับลำบาก\n\nน่าเสียดายที่ทั้งเสือไนต์เซเบอร์และหมูป่าทิสเซิลเพิ่มจำนวนมากเกินไป อาหารใน Shadowglen มีจำกัด ออกเดินทางเถอะ {class} รุ่นเยาว์ ช่วยลดจำนวนหมูป่าและเสือลง เพื่อรักษาความสมดุลของธรรมชาติ" },
        progress = { "32:376277112:306899475 N 81:646744874:773975436", "ยังมีงานต้องทำอีก {name} เมื่อลดจำนวนเสือไนต์เซเบอร์และหมูป่าทิสเซิลได้แล้ว ค่อยกลับมาหาข้า" },
        completion = { "32:1203826912:39611566 N 1:46:46", "เจ้าทำหน้าที่ได้ดีมาก {name}" },
        objectiveLabels = {
            monster = { ["Young Thistle Boar slain"] = "ปราบ หมูป่าหนามวัยเยาว์", ["Young Nightsaber slain"] = "ปราบ ไนต์เซเบอร์วัยเยาว์" },
        },
    },
    [457] = { -- The Balance of Nature
        title = { "21:1767005025:744312648", "สมดุลแห่งธรรมชาติ" },
        objective = { "81:547144844:85679508", "Conservator Ilthalaine ขอให้เจ้ากำจัด Mangy Nightsaber 7 ตัว และ Thistle Boar 7 ตัว" },
        description = { "82:941683046:42153106 N 304:2006247543:2121274339", "การลดจำนวนสัตว์วัยอ่อนใน Shadowglen เป็นการเริ่มต้นที่ดี {name} แต่เรายังมีงานต้องทำต่อ\n\nหากปล่อยปัญหานี้ไว้ ทรัพยากรในป่าจะร่อยหรอเร็วเกินไป แม้การฆ่าสัตว์ป่าเป็นเรื่องน่าเศร้า แต่ก็จำเป็นเพื่อประโยชน์ของทุกชีวิตที่อาศัยผืนดินนี้ จงเข้าไปในป่า ล่าเสือไนต์เซเบอร์ขี้เรื้อนและหมูป่าทิสเซิล เพื่อรักษาสมดุลไว้" },
        progress = { "31:1424521815:1546325752 N 77:1425610768:81651938", "งานของเจ้ายังไม่เสร็จ {name} กำจัด Mangy Nightsaber 8 ตัว และ Thistle Boar 8 ตัวแล้วค่อยกลับมาหาข้า" },
        completion = { "48:2011190816:1836874131 N 10:463560783:358183383 C 38:1114710233:1226658291", "เจ้าพิสูจน์ให้เห็นแล้วว่าอุทิศตนให้ธรรมชาติเพียงใด {name} อนาคตของ {class} รุ่นเยาว์อย่างเจ้าช่างสดใส" },
        objectiveLabels = {
            monster = { ["Mangy Nightsaber slain"] = "ปราบ ไนต์เซเบอร์ขี้เรื้อน", ["Thistle Boar slain"] = "ปราบ หมูป่าหนาม" },
        },
    },
    [458] = { -- The Woodland Protector
        title = { "22:393064589:936387847", "ผู้พิทักษ์ผืนป่า" },
        objective = { "40:1874891608:450119299", "ออกตามหาดรายแอดที่ชื่อ Tarindrella" },
        description = { "29:846610295:2009778540 C 440:546803388:149525467", "ดีจริงที่เจ้ามา {class} วิญญาณแห่งป่ากระซิบบอกข่าวประหลาดแก่ข้า\n\nTarindrella ผู้พิทักษ์ป่าอันลึกลับกลับมายัง Shadowglen แล้ว หลายปีมานี้ไม่มีใครสัมผัสได้ถึงดรายแอดตนนี้ในป่าแห่ง Kalimdor การที่นางเดินทางกลับมา ย่อมแปลว่ามีบางอย่างผิดปกติ\n\nไปหา Tarindrella แล้วดูว่านางมาทำอะไรในป่าของเรา ทหารยามนายหนึ่งรายงานว่าเห็นนางอยู่ทางตะวันตกเฉียงใต้ของ Aldrassil" },
        completion = { "26:201969359:734864299 R 44:1356699018:1543083749", "เจ้าหาข้าพบจนได้ ชาว{race} รุ่นเยาว์เอ๋ย Melithar เป็นดรูอิดที่ปราดเปรื่องนักที่ส่งเจ้ามา", variants = { { "202:435373278:529313963", "เจ้าหาข้าพบจนได้ ไนต์เอลฟ์รุ่นเยาว์เอ๋ย Melithar เป็นดรูอิดที่ปราดเปรื่องนักที่ส่งเจ้ามา แต่เจ้ายังมีเรื่องต้องเรียนรู้อีกมาก ข้าเข้าใจว่าชนเผ่าของเจ้าชอบหนังสือ รับไปสักเล่มเพื่อเพิ่มพูนความรู้เถอะ" }, { "26:201969359:734864299 R 167:177627158:828659539", "เจ้าหาข้าพบจนได้ ชาว{race} รุ่นเยาว์เอ๋ย Melithar คิดถูกแล้วที่ส่งเจ้ามา เขาเป็นดรูอิดที่ฉลาดนัก แต่เจ้ายังมีอะไรต้องเรียนรู้อีกมาก ข้าได้ยินว่าชนเผ่าของเจ้าชอบอ่านหนังสือ รับไปสักเล่มเพื่อเรียนรู้เพิ่มเติมเถิด" } } },
    },
    [459] = { -- The Woodland Protector
        title = { "22:393064589:936387847", "ผู้พิทักษ์ผืนป่า" },
        objective = { "49:1001698278:1656695107", "เก็บ Fel Moss 8 ชิ้นไปให้ Tarindrella" },
        description = { "413:557659782:227163939 N 81:1691952579:983321754", "มีความชั่วร้ายกำลังก่อตัวในป่าแห่ง Teldrassil มองไปตามเนินเขาที่ครั้งหนึ่งพวกเฟอร์โบลก์ผู้รักสงบเคยอาศัยอยู่สิ บัดนี้พวกเขาทิ้งบ้านเรือน แล้วไปรวมตัวกันในนามเผ่า Gnarlpine\n\nมีเพียงอำนาจชั่วร้ายของ Fel Moss เท่านั้นที่ทำให้เกิดความเปลี่ยนแปลงเช่นนี้ได้ พวกเกรลล์และเกรลล์คินเข้ายึดพื้นที่ และกำลังคุกคามผู้อาศัยใน Shadowglen\n\nไปเผชิญหน้ากับพวกเกรลล์และเกรลล์คินเถอะ {name} แล้วดูว่าพวกมันตกอยู่ใต้มนตร์ของ Fel Moss จริงหรือไม่" },
        progress = { "23:418693721:1434133602 N 25:538974629:2000284632", "ช่วยไขข้อสงสัยของข้าที {name} นำ Fel Moss 8 ชิ้นมาให้ข้า" },
        completion = { "65:457681838:1532849313 N 222:802666322:721146031 C 112:889683295:688928331", "สิ่งที่เจ้าทำเพื่อเหล่าสรรพชีวิตแห่ง Shadowglen สมควรได้รับรางวัล {name}\n\nแต่เจ้าก็ได้ยืนยันสิ่งที่ข้าหวาดกลัว หากพวกเกรลล์แปดเปื้อนเพราะ Fel Moss จริง ก็ได้แต่จินตนาการว่าเกิดอะไรขึ้นกับเฟอร์โบลก์เผ่า Gnarlpine ที่เคยอยู่ที่นี่\n\nหากเจ้าเดินทางไปถึง Dolanaar เมื่อใด {class} ผู้เก่งกล้า จงไปหา Athridas Bearmantle ดรูอิดผู้รอบรู้ เขาห่วงใยผืนป่าเช่นเดียวกับเรา" },
        required = { [3297] = { "8:498029177:1626693293", "มอสเฟล" } },
        steps = { { "8:498029177:1626693293", "มอสเฟล" } },
    },
    [4495] = { -- A Good Friend
        title = { "13:873419312:1721971740", "เพื่อนรัก" },
        objective = { "38:997589780:1543840757", "ตามหา Iverron ใกล้ถ้ำทางเหนือ" },
        description = { "203:1169707709:822833026 N 211:1307407122:1145887735", "ข้ามีเพื่อนชื่อ Iverron ปกติเขาจะมาเยี่ยมข้าเวลาเดิมทุกวัน แต่วันนี้แปลกเหลือเกิน เขายังไม่แวะมาเลย ทั้งที่เลยเวลามาหลายชั่วโมงแล้ว\n\nยอมรับว่าข้าเป็นห่วง {name} เขามักจะไปอยู่แถวถ้ำทางเหนือ เจ้าคงรู้ว่าที่นั่นอันตรายแค่ไหน แมงมุมเต็มไปหมด!\n\nถ้าเจ้าบังเอิญจะไปทางนั้น ช่วยมองหาเขาให้หน่อยได้ไหม?" },
        completion = { "26:1097754218:1669250063 N 30:470756813:709380865", "ข้าดีใจเหลือเกินที่เจ้าหาข้าเจอ {name} เจ้ารู้ได้อย่างไรว่าข้าอยู่ตรงนี้?" },
    },
    [916] = { -- Webwood Venom
        title = { "13:688015469:785488125", "พิษแมงมุมเว็บวูด" },
        objective = { "65:36314449:1224725841", "นำ Webwood Venom Sac 10 ถุงไปให้ Gilshalan Windwalker ที่ Aldrassil" },
        description = { "465:1746163852:1699237291", "ข้ามาที่ Shadowglen เพื่อสังเกตแมงมุมเว็บวูดในถ้ำ Shadowthread พวกมันเป็นญาติกับแมงมุมอีกชนิดที่ตัวเล็กกว่ามาก ข้าเชื่อว่าต้นไม้โลกมีอิทธิพลต่อพวกมันอย่างมาก และอยากได้ตัวอย่างมาศึกษาเพื่อยืนยันเรื่องนี้\n\nอย่างแรก ข้าต้องการพิษของมัน เก็บถุงพิษจากแมงมุมในถ้ำ Shadowthread ทางเหนือและบริเวณรอบถ้ำมาให้ข้า ข้าจะได้นำมาเปรียบเทียบกับพิษของญาติตัวเล็กของมัน" },
        progress = { "31:1446575561:829833496 N 1:63:63", "เก็บถุงพิษมาแล้วหรือยัง {name}?" },
        completion = { "11:1191658970:1224418299 N 200:1478943211:1599369207", "ขอบใจ {name} เมื่อกลับถึง Darnassus ข้าจะเปรียบเทียบพิษในถุงเหล่านี้กับพิษของแมงมุมชนิดอื่น ข้าเชื่อว่าคุณสมบัติของมันน่าจะมีส่วนเกี่ยวข้องกับการเติบโตของต้นไม้โลกต้นใหม่ของเราในช่วงที่ผ่านมา" },
        required = { [5166] = { "17:213185830:1640737098", "ถุงพิษ Webwood" } },
        steps = { { "17:213185830:1640737098", "ถุงพิษ Webwood" } },
    },
    [917] = { -- Webwood Egg
        title = { "11:158789445:1448470446", "ไข่แมงมุมเว็บวูด" },
        objective = { "46:219484394:1415326377", "นำ Webwood Egg 1 ฟองไปให้ Gilshalan ที่ Aldrassil" },
        description = { "160:340967348:99710420 C 318:1325018801:361681628", "ตอนนี้ข้าได้พิษมาแล้ว ข้าอยากได้ตัวอย่างที่ยังมีชีวิตมาศึกษาบ้าง แต่จะให้ {class} รุ่นเยาว์อย่างเจ้าจับแมงมุมยักษ์เป็น ๆ ก็คงเกินไป ถึงจับมาได้ ตัวข้าเองก็คงรับมือมันไม่ไหว!\n\nแต่หากเจ้าได้ไข่ที่ยังไม่ฟักมา การขนตัวอย่างก็จะง่ายขึ้นมาก และข้าจะได้จัดเตรียมที่กักพวกมันไว้ก่อนฟัก\n\nลึกเข้าไปในถ้ำ Shadowthread ต้องมีรังอยู่แน่ ช่วยหาไข่สักฟองจากรังแล้วนำกลับมาให้ข้าที" },
        progress = { "44:1920466677:800208429 N 28:1157912598:365199296", "ได้เข้าไปในถ้ำ Shadowthread หรือยัง {name}? พบไข่แมงมุมไหม?" },
        completion = { "181:1621926827:484475377 N 35:1085105354:1018110013", "อา ดีมาก ข้าจะส่งไข่กับพิษนี่ไปที่ Darnassus แล้วตามกลับไปเมื่อเสร็จธุระที่นี่ ตัวอย่างเหล่านี้คงทำให้ข้าได้ค้นพบอะไรอีกมาก {name} เจ้าช่วยข้าไว้มากจริง ๆ" },
        required = { [5167] = { "11:158789445:1448470446", "ไข่แมงมุม Webwood" } },
        steps = { { "11:158789445:1448470446", "ไข่แมงมุม Webwood" } },
    },
    [920] = { -- Tenaron's Summons
        title = { "17:901909305:634358718", "เทนารอนเรียกพบ" },
        objective = { "58:348802858:2072744788", "ไปคุยกับ Tenaron Stormgrip ที่ยอด Aldrassil ใน Shadowglen" },
        description = { "N 179:1733246964:200633735", "เจ้าชื่อ {name} ใช่ไหม? ได้ยินว่า Tenaron ถามหาเจ้าอยู่ เขาอยู่ในห้องชั้นบนสุดที่ยอด Aldrassil\n\nแม้พวกเราจะมีอายุยืนยาว แต่ก็อย่าให้เขารอนานนักเลย" },
        completion = { "4:1110228981:147916455 N 114:1574121877:9606971", "อา {name} ข้าหวังอยู่พอดีว่าเจ้าจะมาตามคำเรียกโดยเร็ว ข้ามีงานสำคัญอยากให้เจ้าทำ" },
    },
    [92642] = { -- Disrupting Logistics
        title = { "20:2086684016:1033514128", "ตัดกำลังสนับสนุน" },
        objective = { "74:775082819:1299094422", "สังหาร Al'Aketh Healer 4 คน และ Al'Aketh Brawler 8 คน ใน Gustberry Lowlands" },
        description = { "472:1774151909:1034134894", "Valennia ส่งคนมาช่วยต้านการบุกเต็มกำลังแค่คนเดียว... สายลมเอ๋ย\n\nเจ้าดูไม่น่าจะสู้ไหว แต่ตอนนี้ใครช่วยได้ข้าก็รับ เราต้องสร้างความเสียหายให้มากที่สุดเพื่อหยุดพวกมันโดยเร็ว คนของข้าคงต้านได้อีกไม่นาน\n\nลงเนินไปตัดกำลังสนับสนุนของพวกมัน พวกผู้รักษาคอยช่วยให้ศัตรูบุกมาได้เรื่อย ๆ ถ้ากำจัดพวกนั้นได้ เราอาจรวบรวมกำลังตีโต้กลับไปได้ ระหว่างทางถ้าเจ้าจัดการสาวกลัทธิคนอื่นได้ ก็ช่วยเราเหมือนกัน" },
        completion = { "67:1926662318:45493564", "เจ้ายังรอดอยู่อีกหรือ? คงต้องขอบคุณสายลมสำหรับปาฏิหาริย์เล็ก ๆ นี้เสียแล้ว" },
        progress = { "36:1308642018:790058017", "พวกมันดูจะมีจำนวนไม่รู้จบเลย!" },
        objectiveLabels = {
            monster = { ["Al'Aketh Healer slain"] = "ปราบ ผู้รักษา Al'Aketh", ["Al'Aketh Brawler slain"] = "ปราบ นักสู้ Al'Aketh" },
        },
    },
    [92645] = { -- Breaking the Breaker
        title = { "20:1038437519:1641677982", "โค่นผู้ทำลาย" },
        objective = { "51:728996751:2107072512", "สังหาร Commander Belguilos ใน Gustberry Lowlands" },
        description = { "490:868428310:1522924696 C 1:46:46", "เราคงต้านการบุกครั้งนี้ได้ยากถ้ายังโค่นผู้บัญชาการของลัทธิไม่ได้ พวกมันเรียกนางว่า Belguilos ผู้ทำลาย ชื่อเสียงอันน่ากลัวนั้นนางไม่ได้มาเล่น ๆ ก่อนที่ลัทธิจะกำเริบ นางเคยเป็นผู้พิทักษ์สันติ แต่ตอนนั้นนางก็ดู... แปลกอยู่แล้ว ข้าไม่อยากคิดเลยว่าพอเข้าลัทธิแล้วจะยิ่งร้ายสักแค่ไหน\n\nข้าอาจกำลังส่งเจ้าไปตาย แต่ถ้าเราจะรอด ต้องมีใครสักคนโค่น Belguilos ให้ได้ นางอยู่ที่คฤหาสน์ตรงตีนเนิน ขอให้โชคดี {class}" },
        completion = { "41:893127330:826664465 C 52:1793204165:1070746537", "Belguilos ตายแล้วหรือ? ขอให้สายลมทั้งสี่อวยพรเจ้า {class}\n\nแบบนี้เราอาจรอดออกไปจากที่นี่กันได้จริง ๆ" },
        progress = { "136:2053813932:222168637", "Belguilos เสียสติตั้งแต่ยังอยู่กับเราแล้ว ข้าพอจะนึกออกว่านางคงเลวร้ายกว่าเดิมแค่ไหนเมื่อไม่มีใครคอยยั้งความโหดเหี้ยมของนาง" },
        objectiveLabels = {
            monster = { ["Commander Belguilos slain"] = "ปราบ ผู้บัญชาการ Belguilos" },
        },
    },
    [93318] = { -- WANTED: Vulgara the Insatiable
        title = { "30:1035879042:580471009", "ประกาศจับ Vulgara ผู้ไม่รู้จักอิ่ม" },
        objective = { "95:1111028565:46169008", "สังหาร Vulgara the Insatiable ใน Shen'dar Highlands แล้วนำหัวของมันไปให้ Danarii Bellowveil" },
        description = { "356:1013726987:443578706", "ตามคำสั่งของ Constable Aonda แห่งเหล่าผู้พิทักษ์สันติ ขอประกาศตั้งค่าหัว Vulgara ผู้ไม่รู้จักอิ่ม ภัยร้ายแห่งที่ราบสูง มีผู้พบเห็นวัลเดรนติดปีกตัวนี้เป็นครั้งสุดท้ายที่ยอดเนินเล็ก ๆ ทางตะวันตกเฉียงใต้ของหมู่บ้าน Shen'dar มันเป็นสัตว์ร้ายที่อันตรายยิ่ง\n\nนำหัวของมันไปให้ Danarii Bellowveil เพื่อรับรางวัล" },
        progress = { "51:436608024:584535693", "ข้าต้องการหัวของเจ้าตัวนั้นเป็นหลักฐานว่าเจ้าจัดการมันแล้ว" },
        completion = { "218:689322852:1273118752", "แค่พวกลัทธิกับโจรบนที่สูงก็ทำให้เรายุ่งพอแล้ว ยังต้องมีเจ้าวัลเดรนยักษ์มาข่มขวัญชาวเมืองอีก วันนี้เจ้าทำคุณให้เรามาก นี่คือรางวัลตามที่สัญญาไว้" },
        required = { [257942] = { "14:1515143212:962025845", "หัวของ Vulgara" } },
        steps = { { "14:1515143212:962025845", "หัวของ Vulgara" } },
    },
    [93736] = { -- Unwelcome Spirits
        title = { "17:1813834385:956362166", "ภูตที่ไม่มีใครต้อนรับ" },
        objective = { "74:605710859:417014023", "เก็บ Wind Hollow Essence 10 ชิ้นจาก Wind Hollow ใน Shadowgale Forest" },
        description = { "490:49866753:40439285", "สิ่งสำคัญที่สุดสำหรับเหล่า Windshaper คือการเข้าใจว่าเหตุใดเหล่าวิญญาณจึงทอดทิ้งเรา และเราจะทำอย่างไรให้พวกเขากลับมา ในป่า Shadowgale ทางเหนือ มีภูตลมประหลาดชนิดหนึ่งที่บางคนเรียกว่า ฮอลโลว์ เรารู้เรื่องพวกมันน้อยมาก ทั้งยังไม่รู้ว่ามาอยู่ที่นั่นทำไม รู้เพียงว่าพวกมันเริ่มปรากฏตัวหลังจากวิญญาณแห่งสายลมจากพวกเราไป\n\nข้าต้องการให้เจ้าไปสลายภูตเหล่านั้น เก็บสิ่งที่เหลืออยู่แล้วนำกลับมาที่นี่" },
        progress = { "179:551215222:327079260", "Shadowgale Forest เป็นพื้นที่อันตราย บางคนถึงกับว่ามีผีสิง ข้าเองคงไม่เชื่อเรื่องนั้น แต่ที่รู้แน่ ๆ คือที่นั่นไม่เหมาะกับคนขวัญอ่อนหรือคนที่ไปโดยไม่เตรียมตัว", variants = { { "177:1213989844:1279517350", "Shadowgale Forest เป็นพื้นที่อันตราย บางคนถึงกับว่ามีผีสิง ข้าเองคงไม่เชื่อเรื่องนั้น แต่ที่รู้แน่ ๆ คือที่นั่นไม่เหมาะกับคนขวัญอ่อนหรือคนที่ไปโดยไม่เตรียมตัว" } } },
        completion = { "242:736836988:1514153787", "พอสัมผัสแก่นพลังพวกนี้ ข้ารู้สึก... ไม่สบายใจอย่างบอกไม่ถูก แทบจะสัมผัสได้ถึงไออาฆาตและความเสียใจที่แผ่ออกมา ทำเอาข้าจะเป็นลม\n\n<Endaria ตัวสั่นเล็กน้อย>\n\nข้าไม่อยากศึกษาพวกมันต่อเลย" },
        required = { [262357] = { "19:1414890433:1431034600", "แก่นพลัง Wind Hollow" } },
        steps = { { "19:1414890433:1431034600", "แก่นพลัง Wind Hollow" } },
    },
    [93740] = { -- Blood for Blood
        title = { "15:1573250199:1229833713", "เลือดต้องชดใช้ด้วยเลือด" },
        objective = { "101:1750582336:809879831", "เก็บ Al'Aketh Windstone Charm 10 ชิ้นจากศพสาวกลัทธิ Al'Aketh ใน Gustberry Lowlands" },
        description = { "361:1319996979:1252625483", "เช้านี้มีคนพบศิษย์ฝึกหัด Windshaper ของเราหลายคนเป็นศพอยู่บนที่ราบสูง แม้ยังยืนยันไม่ได้ แต่มีโอกาสสูงว่าเป็นฝีมือของ Al'Aketh ชาว Windshaper ให้เลือดชดใช้เลือดเสมอ\n\nมุ่งหน้าไปทางเหนือ สังหาร Al'Aketh ทุกคนที่พบ เอาเครื่องรางหินลมที่พวกมันใช้สวดภาวนากลับมาเป็นหลักฐาน เราไม่ให้อภัย และเราจะไม่ลืม" },
        progress = { "119:1811439737:488285588", "พวก Al'Aketh คลั่งลัทธิจนก่อเหตุนองเลือดมานานเกินไปแล้ว นี่เพิ่งเริ่มต้นชำระบัญชีกับพวกมันเท่านั้น" },
        completion = { "87:1555952145:29517144 N 96:1820037972:2135159483", "<Ayessa ดูขวัญเสียและใจลอยขณะเจ้าส่งเครื่องรางศิลาสายลมให้นาง>\n\nอย่าใส่ใจข้าเลย {name} วันนี้เป็นวันที่... หนักหนาไปสักหน่อย ขอบใจที่ช่วยเหล่า Windshaper มาตลอด" },
        required = { [255658] = { "24:1773871514:1765551057", "เครื่องรางหินลมของ Al'Aketh" } },
        steps = { { "24:1773871514:1765551057", "เครื่องรางหินลมของ Al'Aketh" } },
    },
    [94485] = { -- Tears of the Lady
        title = { "17:686257088:408740912", "หยาดน้ำตาแห่งนาง" },
        objective = { "27:1412727434:1255749974", "เก็บ Lady's Tear Moss 8 ชิ้น", amount = { "8:1089852795:1107240600 W1 18:1286208259:734339696", "เก็บ Lady's Tear Moss {world1} ชิ้น" } },
        description = { "504:1763238771:1456238", "ถ้าเราจะช่วยพวกพ้องของข้าที่ Nightclaw Den ข้าต้องมีส่วนผสมสำหรับทำยาพอก อย่างแรกและสำคัญที่สุดคือมอสก้านเรียวที่เรียกว่า Lady's Tear มักขึ้นอยู่ตามโคนไม้ใน Shadowgale\n\nมอสนี้หลั่งยางเหนียวที่ช่วยฆ่าเชื้อได้ เหมาะอย่างยิ่งสำหรับปิดแผลเปิด ข้าเก็บที่เอื้อมถึงมาหมดแล้ว แต่รู้ว่าในป่านี้ยังมีอีกมาก\n\nรีบไปเถิด ถ้าคนเจ็บที่ข้าทิ้งไว้ยังมีชีวิตอยู่ เราต้องใช้มันอีกมาก" },
        progress = { "31:1124752344:518446961", "เจ้าพบ Lady's Tear แล้วหรือยัง?" },
        completion = { "80:16828601:1857903004 N 51:1737661169:1185544902", "<Elegael รับก้อนมอสเหนียวจากเจ้าพร้อมยิ้มบาง ๆ>\n\nขอบใจ {name} เจ้าทำได้ดีมาก นี่แหละสิ่งที่เราต้องการ" },
        required = { [265105] = { "16:505701633:1059458247", "มอสหยาดน้ำตาแห่งท่านหญิง" } },
        steps = { { "16:505701633:1059458247", "มอสหยาดน้ำตาแห่งท่านหญิง" } },
    },
    [94486] = { -- Feathers for Binding
        title = { "20:2007275647:594380988", "ขนนกสำหรับพันแผล" },
        objective = { "73:1616586064:1649685149", "เก็บขนนก 20 ขนจาก Shadowgale Shriekling ใน Shadowgale Forest", amount = { "8:1089852795:1107240600 W1 63:654486907:548321322", "เก็บขนนก {world1} ขนจาก Shadowgale Shriekling ใน Shadowgale Forest" } },
        description = { "508:2082597474:546185832", "ส่วนผสมอีกอย่างสำหรับยาพอกคือขนของพวก Shriekling ที่อาศัยในป่านี้ ขนของตัวที่ยังไม่โตเต็มวัยช่วยเก็บความอุ่นได้ดี เหมาะจะใช้คลุมทับมอส ช่วยให้ยางที่ใช้ฆ่าเชื้อไม่แห้งและกันลมกันฝนได้บ้าง\n\nระวังตัวด้วย ปกติพวกมันเชื่อง แต่ระยะหลังกลับดุร้ายผิดหูผิดตา ถ้าไม่ระวัง กรงเล็บใหญ่ ๆ นั่นคว้านท้องเจ้าได้ง่าย ๆ" },
        progress = { "170:1796882462:60895723", "ข้าเสียใจนักที่ต้องขอให้เจ้าไปฆ่าพวก shriekling วัยอ่อน แต่พวกมันดุร้ายขึ้นเรื่อย ๆ จึงจำเป็นต้องทำ เรารับมือกับเรื่องคับขันพร้อมกันได้แค่ไม่กี่เรื่อง" },
        completion = { "96:1651867762:1661524188", "ขอบใจที่นำขนพวกนี้มา ข้าจะใช้ทุกเส้นให้เกิดประโยชน์ ชีวิตที่เสียไปจะได้ไม่สูญเปล่า" },
        required = { [265140] = { "27:600865955:1640591925", "ขน Shriekling สภาพสมบูรณ์" } },
        steps = { { "28:1951211613:169179390", "ขน Shriekling สภาพสมบูรณ์" } },
        objectiveLabels = {
            item = { ["Pristine Shriekling Feather"] = "ขน Shriekling สภาพสมบูรณ์" },
        },
    },
    [94487] = { -- Unwanted and Unworthy
        title = { "21:919247858:1602316463", "ไม่มีใครต้องการ และไม่คู่ควร" },
        objective = { "108:1863347085:255209850", "เก็บ Bloodied Heirloom 10 ชิ้นจาก Al'Aketh Footsoldier และ Al'Aketh Stormchaser ใน Shadowgale Forest", amount = { "8:1089852795:1107240600 W1 98:898229340:315220948", "เก็บ Bloodied Heirloom {world1} ชิ้นจาก Al'Aketh Footsoldier และ Al'Aketh Stormchaser ใน Shadowgale Forest" } },
        description = { "487:218551603:1550772246", "สาวกลัทธิ Al'Aketh ซุ่มโจมตีเราโดยไม่มีวี่แวว ข้ายังไม่รู้ว่าเพื่ออะไร รู้อยู่ว่าพวกมันโง่เขลา แต่ไม่นึกเลยว่าจะใช้ความโหดเหี้ยมทำลายสมดุลอันเปราะบางของ Zephras ได้ถึงเพียงนี้ ไปปราบพวกมันให้มากที่สุด ถ้าใครสวมของตกทอดประจำตระกูลอยู่ ก็เอามาด้วย\n\n<Elegael ถ่มน้ำลาย>\n\nสาวกลัทธิต้องสาปพวกนี้ไม่สมควรได้ชื่อว่าเป็นชาว shen'dorei ปล่อยร่างพวกมันให้สัตว์ป่าไปเถอะ แม้แต่เถ้ากระดูกของมันก็ยังไม่คู่ควรกับสายลม", variants = { { "484:720660146:1280320395", "สาวกลัทธิ Al'Aketh ซุ่มโจมตีเราโดยไม่มีวี่แวว ข้ายังไม่รู้ว่าเพื่ออะไร รู้อยู่ว่าพวกมันโง่เขลา แต่ไม่นึกเลยว่าจะใช้ความโหดเหี้ยมทำลายสมดุลอันเปราะบางของ Zephras ได้ถึงเพียงนี้ ไปปราบพวกมันให้มากที่สุด ถ้าใครสวมของตกทอดประจำตระกูลอยู่ ก็เอามาด้วย\n\n<Elegael ถ่มน้ำลาย>\n\nสาวกลัทธิต้องสาปพวกนี้ไม่สมควรได้ชื่อว่าเป็นชาว shen'dorei ปล่อยร่างพวกมันให้สัตว์ป่าไปเถอะ แม้แต่เถ้ากระดูกของมันก็ยังไม่คู่ควรกับสายลม" } } },
        progress = { "43:160980096:1584930162 C 34:1181738447:1436316146", "ข้าจะให้สาวกลัทธิชดใช้ทุกหยดเลือดของเหล่า{class} ที่พวกมันทำให้หลั่งในวันนี้", variants = { { "82:1981318773:257683652", "ข้าจะให้สาวกลัทธิชดใช้ทุกหยดเลือดของเหล่าดรูอิด ที่พวกมันทำให้หลั่งในวันนี้" } } },
        completion = { "168:1632228698:567415817 C 200:787629093:219844227", "<Elegael ก้มมองของตกทอดเปื้อนเลือดเหล่านั้นด้วยใจที่หดหู่>\n\nคนหนุ่มสาวที่มีอนาคตอีกมากต้องจากไปตลอดกาล ขอบใจที่นำของเหล่านี้กลับมา {class}\n\nข้าจะเก็บไว้ให้ปลอดภัยจนกว่าจะนำไปมอบแก่ High Elder ได้ จากนั้นเราจะนำกลับเข้าคลัง รอให้คนรุ่นต่อไปเติบโตขึ้นมา บางทีพวกเขาอาจคู่ควรยิ่งกว่า", variants = { { "168:1632228698:567415817 C 201:465832971:421262837", "<Elegael ก้มมองของตกทอดเปื้อนเลือดเหล่านั้นด้วยใจที่หดหู่>\n\nคนหนุ่มสาวที่มีอนาคตอีกมากต้องจากไปตลอดกาล ขอบใจที่นำของเหล่านี้กลับมา {class}\n\nข้าจะเก็บไว้ให้ปลอดภัยจนกว่าจะนำไปมอบแก่ High Elder ได้ จากนั้นเราจะนำกลับเข้าคลัง รอให้คนรุ่นต่อไปเติบโตขึ้นมา บางทีพวกเขาอาจคู่ควรยิ่งกว่า" } } },
        required = { [265141] = { "15:179816450:844580716", "ของตกทอดเปื้อนเลือด" } },
        steps = { { "15:179816450:844580716", "ของตกทอดเปื้อนเลือด" } },
    },
    [94896] = { -- Aid For The Refugees
        title = { "20:1966642251:803339623", "ช่วยเหลือผู้ลี้ภัย" },
        objective = { "60:1880945281:1993071313", "เก็บ Abandoned Belongings 8 ชิ้นจากซากหมู่บ้าน Ban'aethal", amount = { "8:1089852795:1107240600 W1 51:182080704:23149777", "เก็บ Abandoned Belongings {world1} ชิ้นจากซากหมู่บ้าน Ban'aethal" } },
        description = { "471:1997574560:285469965", "ท่านดูเป็นนักผจญภัยที่พึ่งพาได้ บังเอิญกำลังจะไปทางป่า Shadowgale หรือเปล่า? บ้านเกิดของพวกเราทุกคนคือ Ban'aethal อยู่ลึกเข้าไปในป่า\n\n<Ealaane ผายมือไปทางผู้ลี้ภัยคนอื่น ๆ>\n\nไม่นานมานี้พวกเราต้องอพยพ เพราะ Ban'aethal เริ่มร่วงหล่นสู่ท้องฟ้า ทุกอย่างเกิดขึ้นกะทันหันกลางดึก ถ้าท่านจะไปทางนั้น ช่วยมองหาข้าวของที่พวกเราทิ้งไว้ได้ไหม? ทั้งป่าและหมู่บ้านอันตรายเกินกว่าที่เราจะกลับไปเองในตอนนี้" },
        progress = { "120:1877016626:1021572077", "พวกเราหลายคนหนีมาได้เพียงเสื้อผ้าที่สวมอยู่ หากเจ้าหาข้าวของของเรากลับมาได้สักชิ้น เราก็จะเห็นค่าอย่างยิ่ง" },
        completion = { "11:1191658970:1224418299 C 156:1231537378:796245204", "ขอบใจ {class} วันนี้เจ้ามีน้ำใจต่อพวกเราที่ต้องลี้ภัยอย่างมาก ข้าจะนำของเหล่านี้ไปคืนเจ้าของ อย่างน้อยเราก็มีอะไรติดมือให้เริ่มต้นใหม่" },
        required = { [266433] = { "20:1592398121:1611910834", "ข้าวของที่ถูกทิ้งไว้" } },
        steps = { { "20:1592398121:1611910834", "ข้าวของที่ถูกทิ้งไว้" } },
    },
    [94897] = { -- The Fate of a Loved One
        title = { "23:1160795394:1006808153", "ชะตากรรมของคนรัก" },
        objective = { "39:1036053770:1976310819", "ตามหา Resaan ในซากหมู่บ้าน Ban'aethal" },
        description = { "360:967560171:1708285998", "ถ้าท่านจะไป Ban'aethal ข้ามีเรื่องส่วนตัวอยากขอร้อง Resaan คนรักของข้า... ข้าเกรงว่าเขาอาจจากโลกนี้ไปแล้ว เขาพยายามกลับไปเอาเสบียงทั้งที่ข้าอ้อนวอนให้เขาอยู่ นี่ก็ผ่านมากว่าสัปดาห์ ข้ากลัวเหลือเกินว่าเขาจะไม่รอด\n\nได้โปรด หากพบเขา ช่วยพาเขากลับบ้านด้วย ถ้าเขาสิ้นใจแล้ว ข้าขอเพียงให้ท่านนำของสืบทอดประจำตระกูลของเขากลับมาให้ข้า", variants = { { "361:1816902273:1110456619", "ถ้าท่านจะไป Ban'aethal ข้ามีเรื่องส่วนตัวอยากขอร้อง Resaan คนรักของข้า... ข้าเกรงว่าเขาอาจจากโลกนี้ไปแล้ว เขาพยายามกลับไปเอาเสบียงทั้งที่ข้าอ้อนวอนให้เขาอยู่ นี่ก็ผ่านมากว่าสัปดาห์ ข้ากลัวเหลือเกินว่าเขาจะไม่รอด\n\nได้โปรด หากพบเขา ช่วยพาเขากลับบ้านด้วย ถ้าเขาสิ้นใจแล้ว ข้าขอเพียงให้ท่านนำของสืบทอดประจำตระกูลของเขากลับมาให้ข้า" } } },
        progress = { "37:1604891915:938597375 C 64:174956376:817064794", "เจ้าได้ข่าวของ Resaan บ้างไหม? ได้โปรดเถอะ {class} หลังจากเกิดเรื่องมามากมายเช่นนี้ ข้าแทบทนรอไม่ไหวแล้ว" },
        completion = { "166:1690983542:1616356434 C 111:426566512:330621215", "<น้ำตาคลอเบ้า Ealaane>\n\nโอ้ Resaan ที่รัก แล้วเราจะเป็นอย่างไรต่อไป? ยังมีอีกตั้งมากมาย... เหมือนเราเพิ่งเริ่มใช้ชีวิตด้วยกันเอง\n\nขอบใจ {class} โลกช่างใจร้ายที่พรากทั้งบ้านและคนรักไปจากข้า อย่างน้อยของตกทอดของเขาก็คงช่วยให้ข้าทำใจได้บ้าง" },
        required = { [266434] = { "17:945542361:614177177", "ของตกทอดของ Resaan" } },
        objectiveLabels = {
            item = { ["Resaan's Heirloom"] = "ของตกทอดของ Resaan" },
        },
    },
    [97245] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "178:2072727178:146617979", "หารังของ Kuramaa ใน Shen'dar Highlands แล้วเอาชนะภูตตนนี้ในการต่อสู้ จากนั้นนำ Kuramaa's Mask ไปให้ Olariaan Swiftburn ใน Gustberry Lowlands" },
        description = { "476:1978116470:651073634", "ผู้คนบนที่ราบสูง Shen'dar เล่าถึงภูตป่าเก่าแก่ชื่อ Kuramaa ว่ากันว่ามันอยู่ในตอไม้บิดเบี้ยวบนยอดเนิน ใกล้กับ Anchor Pylon ของที่ราบสูง\n\nไปที่ราบสูงแล้วค้นหาตอไม้นั้น ใช้กำปั้นเคาะเปลือกไม้ แล้ว Kuramaa จะปรากฏตัว เอาชนะมันในการต่อสู้ แล้วนำหน้ากากไม้ของมันมาให้ข้า\n\nระวังไว้ ภูตตนนี้ต้านทานเวทมนตร์ส่วนใหญ่ของเจ้าได้ดีมาก มีเพียงเปลวไฟเท่านั้นที่จะโค่นมันลงได้" },
        completion = { "95:665673571:137833225", "ตอนนี้เรามีสิ่งที่ต้องใช้ครบแล้ว เราจะจุดเปลวไฟนิรันดร์และสื่อสารกับวิญญาณแห่งไฟ" },
        progress = { "175:2145437478:1785798514", "วิญญาณของ Kuramaa คงอยู่ชั่วนิรันดร์ และจะปรากฏกายอีกครั้งเมื่อถึงคราวจำเป็น หน้ากากของมันเป็นแหล่งพลังอันยิ่งใหญ่ และจะมีค่าอย่างยิ่งต่อพิธีที่เราต้องทำให้สำเร็จ", variants = { { "174:2079560496:139996586", "วิญญาณของ Kuramaa คงอยู่ชั่วนิรันดร์ และจะปรากฏกายอีกครั้งเมื่อถึงคราวจำเป็น หน้ากากของมันเป็นแหล่งพลังอันยิ่งใหญ่ และจะมีค่าอย่างยิ่งต่อพิธีที่เราต้องทำให้สำเร็จ" } } },
        required = { [277269] = { "14:58684072:1771820114", "หน้ากากของ Kuramaa" } },
        steps = { { "14:58684072:1771820114", "หน้ากากของ Kuramaa" } },
    },
    [475] = { -- A Troubling Breeze
        title = { "18:915246375:681153846", "สายลมแห่งความกังวล" },
        objective = { "51:2142647473:537643353", "ไปหา Gaerolas Talvethren ใน Starbreeze Village" },
        description = { "492:1364941720:754127981", "สายลมที่พัดผ่านป่าในยามนี้ชวนให้ใจคอไม่ดี\n\nGaerolas Talvethren เป็นผู้พิทักษ์ใหญ่ คอยดูแลดรูอิดแห่งกรงเล็บที่จำศีลอยู่ใน Ban'ethil Barrow Den เขาได้รับเลือกให้ปกป้องผู้หลับใหลเหล่านั้น เพื่อให้พันธสัญญาที่พวกเขาทำกับ Ysera ยังคงดำเนินต่อไป\n\nแต่ข่าวจาก Gaerolas กลับล่าช้ากว่าที่ควร ข้าจึงเริ่มเป็นห่วง ไปทางตะวันออกยัง Starbreeze Village แล้วนำรายงานของเขากลับมาให้ข้าที ข้าจะได้สบายใจว่าพี่น้องของเรายังหลับฝันอย่างปลอดภัย" },
        completion = { "89:2064775209:629487341", "ขอบคุณวิญญาณแห่งป่าที่เจ้ามาถึง! ข้ารู้อยู่แล้วว่า Athridas จะสัมผัสได้ถึงอันตรายและส่งคนมาช่วย" },
    },
    [476] = { -- Gnarlpine Corruption
        title = { "20:1269530155:2102537756", "ความเสื่อมทรามของเผ่านาร์ลไพน์" },
        objective = { "42:1121870470:15693029", "กลับไปหา Athridas Bearmantle ใน Dolanaar" },
        description = { "413:663621606:2141459869 C 82:405279344:62294749", "เผ่า Gnarlpine ถูกความชั่วร้ายครอบงำแล้ว!\n\nพวกเฟอร์โบลก์ที่เคยรักสงบกลับหันมาเล่นงานผู้พิทักษ์ป่า พวกมันซุ่มโจมตีข้าระหว่างเดินทางไป Ban'ethil Barrow Den แล้วเข้าปล้น Starbreeze Village ต่อ Ursal the Mauler หัวหน้าเผ่าของพวกมัน ใช้อำนาจชั่วร้ายของ Fel Moss ทำให้พวกมันคลุ้มคลั่ง\n\nข้าบาดเจ็บหนักเกินกว่าจะกลับไปแจ้งข่าวร้ายนี้แก่ Athridas งานนี้จึงต้องฝากเจ้าแล้ว {class} รุ่นเยาว์ เราได้แต่หวังว่าพวก Gnarlpine ที่บ้าคลั่งจะยังไปไม่ถึง Ban'ethil!" },
        completion = { "46:116682435:317205273", "ดวงดาวเอ๋ย! ข่าวนี้น่าวิตกจริง ๆ!" },
    },
    [483] = { -- The Relics of Wakening
        title = { "22:1763419586:1943885478", "ศาสตราวัตถุแห่งการตื่น" },
        objective = { "82:907789243:570676073", "นำ Relics of Wakening กลับไปให้ Athridas Bearmantle ใน Dolanaar" },
        description = { "483:364834772:1353225885", "มีผู้พบพวก Gnarlpine กำลังบุกทำลาย Ban'ethil Barrow Den ทางตะวันตก\n\nถ้าเราไม่ช่วย ดรูอิดที่หลับใหลอยู่จะติดอยู่ใน Emerald Dream ชั่วนิรันดร์โดยไม่รู้ชะตากรรมของตน พิธีจำศีลอันละเอียดอ่อนนั้นจะยุติลงไม่ได้หากปราศจาก Relics of Wakening\n\nจงไปที่ถ้ำแล้วนำ Raven Claw Talisman, Black Feather Quill, Sapphire of Sky และ Rune of Nesting กลับมา ดรูอิดเก็บของเหล่านี้ไว้ในหีบศักดิ์สิทธิ์ นำมาให้ข้า แล้วข้าจะเตรียมพิธีปลุกพวกเขา" },
        progress = { "N 244:660795852:2066143174", "{name} หากเราเอา Relics of Wakening จาก Ban'ethil Barrow Den ทางตะวันตกกลับมาไม่ได้ ดรูอิดแห่งกรงเล็บที่ถูกจับไปก็จะติดอยู่ใน Emerald Dream ตลอดกาล\n\nทุกนาทีที่เราชักช้า ชะตากรรมของพวกเขาก็ยิ่งเข้าใกล้หายนะอันไร้สิ้นสุด" },
        completion = { "26:1255277587:89124737 C 42:1444681519:1304372770", "เจ้าทำสำเร็จแล้ว {class} รุ่นเยาว์! ดีมาก และต้องบอกว่าทันเวลาพอดีเลยทีเดียว" },
        required = { [3405] = { "19:1880800776:190572497", "เครื่องรางกรงเล็บอีกา" }, [3406] = { "19:1550062850:104268025", "ปากกาขนนกสีดำ" }, [3407] = { "15:2093522498:839266636", "ไพลินแห่งฟากฟ้า" }, [3408] = { "15:470292524:1834293115", "รูนแห่งรัง" } },
        steps = { { "19:1880800776:190572497", "เครื่องรางกรงเล็บอีกา" }, { "19:1550062850:104268025", "ปากกาขนนกสีดำ" }, { "15:2093522498:839266636", "ไพลินแห่งฟากฟ้า" }, { "15:470292524:1834293115", "รูนแห่งรัง" } },
    },
    [486] = { -- Ursal the Mauler
        title = { "16:1737395050:1851601729", "เออร์ซาลผู้ขย้ำ" },
        objective = { "68:993030272:1140505446", "ฆ่า Ursal the Mauler แล้วกลับไปหา Athridas Bearmantle ใน Dolanaar" },
        description = { "71:366604632:636163283 N 425:1008595002:355514336", "ถึงเวลาช่วยดรูอิดแห่งกรงเล็บแล้ว หากเราล้มเหลวตอนนี้ {name} พวกเขาจะสูญหายอยู่ในห้วงนิทราตลอดกาล\n\nข้าจะเตรียม Relics of Wakening และประกอบพิธี แต่เพื่อให้พิธีเกิดผล ต้องสังหารสัตว์ร้ายต้องสาปที่เป็นต้นเหตุของเรื่องทั้งหมดเสียก่อน พิธีจึงจะสมบูรณ์\n\nUrsal the Mauler เป็นผู้ขัดขวางภารกิจของพี่น้องเรา และมันต้องชดใช้เพื่อปลดปล่อยพวกเขา เดินทางไป Gnarlpine Hold ทางตะวันตกเฉียงใต้แล้วสังหารมัน" },
        progress = { "71:1762514530:2062612024 N 1:46:46", "พี่น้องของเราจะตื่นขึ้นไม่ได้จนกว่า Ursal the Mauler จะถูกสังหาร {name}" },
        completion = { "N 49:2066692165:1663569691 C 4:782961583:103969885 R 165:263495896:475991127", "{name} เจ้าพิสูจน์แล้วว่าเป็น {class} ผู้เก่งกล้าและคู่ควร ชาว{race} ที่ยึดมั่นในหนทางแห่งเกียรติอย่างเจ้าย่อมได้พบความรุ่งโรจน์ในโลกนี้\n\nขอให้วิญญาณแห่งป่าคุ้มครองเจ้า ไม่ว่าการเดินทางจะพาเจ้าไปที่ใด", variants = { { "N 50:1885845334:658384860 C 4:782961583:103969885 R 165:263495896:475991127", "{name} เจ้าพิสูจน์แล้วว่าเป็น {class} ผู้เก่งกล้าและคู่ควร ชาว{race} ที่ยึดมั่นในหนทางแห่งเกียรติอย่างเจ้าย่อมได้พบความรุ่งโรจน์ในโลกนี้\n\nขอให้วิญญาณแห่งป่าคุ้มครองเจ้า ไม่ว่าการเดินทางจะพาเจ้าไปที่ใด" } } },
        objectiveLabels = {
            monster = { ["Ursal the Mauler slain"] = "ปราบ Ursal จอมตะปบ" },
        },
    },
    [487] = { -- The Road to Darnassus
        title = { "21:1911937589:121196227", "เส้นทางสู่ดาร์นัสซัส" },
        objective = { "88:257743496:1973679049", "สังหาร Gnarlpine Ambusher 6 ตัว แล้วกลับไปหา Sentinel Amara Nightwalker ที่นอก Dolanaar" },
        description = { "373:1014347354:124544998 C 111:1730378325:640042840", "เราต้องรักษาความปลอดภัยบนถนนสู่ Darnassus ผู้เดินทางจาก Dolanaar ไปที่นั่นรายงานว่าถูกเฟอร์โบลก์เผ่า Gnarlpine ที่เสื่อมทรามโจมตีอย่างโหดเหี้ยม\n\nข่าวสารสำคัญและสินค้าต่าง ๆ เข้าออก Darnassus ผ่านถนนสายนี้ทุกวัน เราจะปล่อยให้พวกอันธพาลนอกรีตข่มขวัญผู้คนไม่ได้\n\nจงจับอาวุธในนามของป่าศักดิ์สิทธิ์ {class} รังของพวกมันอยู่ที่ใดสักแห่งใต้จุดเฝ้าระวังนี้ สังหารพวก Gnarlpine ที่ดักซุ่มอยู่ 6 ตัว แล้วกลับมารายงานข้า" },
        progress = { "28:689705557:1181484451 C 63:611212092:1708238336", "ถนนยังไม่ปลอดภัย {class} ออกไปสังหาร Gnarlpine Ambusher 6 ตัว แล้วกลับมาหาข้า" },
        completion = { "70:1965345531:1577521626 C 72:333829076:452834452", "เจ้าช่วยชาว Dolanaar และ Darnassus ได้มาก {class} ผู้กล้าหาญ ในนามสมาชิกหน่วย Sentinel แห่ง Teldrassil ข้าขอคารวะความพยายามของเจ้า" },
        objectiveLabels = {
            monster = { ["Gnarlpine Ambusher slain"] = "ปราบ นักซุ่มโจมตี Gnarlpine" },
        },
    },
    [488] = { -- Zenn's Bidding
        title = { "14:1960146799:975266903", "งานรับใช้ของเซ็นน์" },
        objective = { "121:1671695765:1283670847", "นำ Nightsaber Fang 3 ชิ้น, Strigid Owl Feather 3 ขน และ Webwood Spider Silk 3 ชิ้นไปให้ Zenn Foulhoof ที่นอก Dolanaar" },
        description = { "93:438592300:1249476776 C 33:403002508:63874897 N 343:1110739697:502644337 R 1:46:46", "ดูท่าเจ้าอยากหางานทำสินะ โชคดีแล้วล่ะ ไม่มีวันไหนที่ข้าไม่อยากได้ {class} มือใหม่มาช่วยทำตามคำสั่ง\n\nฟังนะ {name} ข้าทำให้เจ้ามีความสุขได้ และให้ของที่เจ้าไม่เคยฝันว่าจะมี แต่ก่อนอื่นเจ้าต้องหาของบางอย่างมาให้ข้า\n\nงานของข้าในป่ามักต้องใช้... วัตถุดิบบางชนิด ไปเอา Nightsaber Fang 3 ชิ้น, Strigid Owl Feather 3 ขน และ Webwood Spider Silk 3 ชิ้นมาให้ข้า\n\nเก็บเรื่องนี้เป็นความลับระหว่างเรานะ ชาว{race}" },
        progress = { "33:1469874610:884677935 N 52:1669514759:1164338819", "ขยันทำงานอยู่หรือเปล่า {name}? ข้ารอให้เจ้าเอาของที่ต้องการมาให้อยู่นะ" },
        completion = { "90:1920669150:107771923 R 144:1342615149:87239578", "ฮ่า ๆ! ทำได้ดีจริง ๆ\n\nใครจะนึกว่าข้า Zenn Foulhoof จะมีชาว{race} มาคอยรับใช้! ข้าเองก็ไม่เคยนึก แต่ก็อย่างนี้แหละ... โลกอันเป็นที่รักของเราเต็มไปด้วยเรื่องคาดไม่ถึง\n\nไชโยให้พวกซื่อจนหลอกง่าย!" },
        required = { [3409] = { "15:405099026:1129740179", "เขี้ยวไนต์เซเบอร์" }, [3411] = { "19:1635117251:544750445", "ขนนกฮูก Strigid" }, [3412] = { "19:607977223:1614971643", "ใยแมงมุม Webwood" } },
        steps = { { "15:405099026:1129740179", "เขี้ยวไนต์เซเบอร์" }, { "19:1635117251:544750445", "ขนนกฮูก Strigid" }, { "19:607977223:1614971643", "ใยแมงมุม Webwood" } },
    },
    [489] = { -- Seek Redemption!
        title = { "16:1734740311:1299951961", "จงไถ่โทษ!" },
        objective = { "71:1758615586:1786180757", "เก็บ Fel Cone 3 ลูกไปให้ Zenn Foulhoof ที่นอก Dolanaar" },
        description = { "107:1960168562:1399032140 R 390:570965156:1118693592", "สภาแห่งป่าทราบแล้วว่าเจ้าช่วย Zenn Foulhoof ซาเทียร์ตนนั้นเป็นศัตรูของป่า ในฐานะชาว{race} เจ้าควรรู้ดีว่าไม่ควรทำให้ป่าแปดเปื้อนด้วยการฆ่าสรรพชีวิตของธรรมชาติ\n\nหากเจ้ายังอยากเป็นมิตรของ Teldrassil เจ้าต้องไถ่โทษต่อหน้าสภา\n\nสั่งสอน Foulhoof สักบทเรียนแล้วเจ้าจะได้รับการอภัย Fel Cone คือเมล็ดต้องสาปที่ร่วงจากต้นไม้ มันปล่อยควันสีเขียวออกมา\n\nเอาไปให้ Foulhoof สักหน่อย เขาจะคิดว่าเจ้าหาขนมที่ไม่มีพิษภัยมาให้" },
        progress = { "25:789846518:812020936 N 27:1122945971:932206185", "มีอะไรมาให้ข้าหรือ {name}? ข้าเดาว่าคงเป็นขนมแสนอร่อยสินะ?" },
        completion = { "17:607740235:952315357 R 33:1271953527:1512123992", "อา ชาว{race} ผู้น่ารัก! ข้ารู้อยู่แล้วว่าเจ้าจะมีประโยชน์!" },
        required = { [3418] = { "8:328281948:1604211714", "ลูกสนเฟล" } },
        steps = { { "8:328281948:1604211714", "ลูกสนเฟล" } },
    },
    [490] = { -- Bounty: Gnarlpine Furbolg
        title = { "25:1724491573:1964951774", "ค่าหัวเฟอร์โบลก์เผ่านาร์ลไพน์" },
        objective = { "94:1864703774:810424249", "นำ Gnarlpine Fang 15 ชิ้นไปให้ Shayla Nightbreeze บนถนนนอก Darnassus", amount = { "75:1654538652:1118503121 W1 17:1375208701:1935288732", "นำ Gnarlpine Fang {world1} ชิ้นไปให้ Shayla Nightbreeze บนถนนนอก Darnassus" } },
        description = { "379:37783383:551914091", "ตามคำสั่งเด็ดขาดของสภา Darnassus ข้าขอประกาศตั้งค่าหัวเผ่า Gnarlpine พวกมันเป็นศัตรูของป่าแล้ว ความชั่วร้ายทำให้พวกมันไร้สติและเป็นภัยต่อผู้คนของเรา รวมถึงเหล่าสัตว์ในพงไพร\n\nตามประกาศของสภา เจ้าจะได้รับรางวัลเมื่อกำจัดภัยจากเฟอร์โบลก์ให้พ้นจาก Kalidar นำเขี้ยวของพวกมันมาเป็นหลักฐาน", variants = { { "485:1801827515:1272689659", "ตามคำสั่งเด็ดขาดของเหล่า Sentinel ข้าขอประกาศตั้งค่าหัวพวก Gnarlpine พวกมันไม่เป็นมิตรกับผืนป่าอีกแล้ว ความเสื่อมทรามทำให้พวกมันไร้สติและกลายเป็นภัยต่อผู้คนของเราและเหล่าสัตว์ในพงไพร\n\nตามประกาศ เจ้าจะได้รับรางวัลเมื่อกำจัดภัยจากเฟอร์โบลก์ให้พ้นจาก Teldrassil นำเขี้ยวของพวกมันมาให้ข้าเป็นหลักฐาน\n\nเฟอร์โบลก์ชุมนุมกันมากที่ Ban'ethil Hollow ทางตะวันตกของ Dolanaar และอยู่ทางใต้ของถนน อีกแห่งคือ Starbreeze Village ทางตะวันออก" } } },
        completion = { "22:1835164396:308651817 N 46:1034570085:319526093", "เจ้ารับใช้เราได้ดี {name} เจ้าจะได้รับรางวัลตอบแทนความช่วยเหลือ" },
        progress = { "115:314468455:2006750616", "Teldrassil จะงอกงามไม่ได้ตราบใดที่มลทินยังปนเปื้อนผืนดิน ขับไล่พวก Gnarlpine ออกจากป่านี้ให้สิ้นซากเสียที" },
        required = { [5220] = { "14:1594345836:232543902", "เขี้ยว Gnarlpine" } },
        objectiveLabels = {
            item = { ["Gnarlpine Fang"] = "เขี้ยว Gnarlpine" },
        },
    },
    [918] = { -- Timberling Seeds
        title = { "16:764230548:2013178761", "เมล็ดพันธุ์ทิมเบอร์ลิง" },
        objective = { "53:1432806187:896305433", "นำ Timberling Seed 8 เมล็ดไปให้ Denelan ที่ Lake Al'Ameth" },
        description = { "452:317816961:545763526", "ทิมเบอร์ลิงแห่ง Teldrassil เป็นวิญญาณธาตุแห่งธรรมชาติ ในบางแง่พวกมันสะท้อนความเป็นไปของพืชและสัตว์บนมหาพฤกษ์ของเรา\n\nการที่พวกมันดุร้ายขึ้นเช่นนี้จึงน่ากังวล\n\nข้าเชื่อว่าเป็นเพราะดิน ข้ากำลังทดลองวิธีบำรุงพืชหลายแบบและอยากลองกับเมล็ดทิมเบอร์ลิง เจ้าช่วยเก็บเมล็ดจากพวกทิมเบอร์ลิงรอบ Lake Al'Ameth มาให้ข้าได้ไหม?" },
        progress = { "48:1522249615:1868170535", "ได้เมล็ดมาหรือยัง? ข้าอยากลองปลูกมันเต็มทีแล้ว" },
        completion = { "199:169986732:1914925870", "ได้มาแล้วสินะ ดีเลย!\n\nข้าจะปลูกเมล็ดเหล่านี้ในดินพิเศษที่เตรียมไว้ เชื่อว่ามันจะงอกเป็นทิมเบอร์ลิงที่เชื่องขึ้นมาก วันหลังเจ้าอาจได้เห็นผลด้วยตัวเอง!" },
        required = { [5168] = { "15:1172809109:835018016", "เมล็ด Timberling" } },
        steps = { { "15:1172809109:835018016", "เมล็ด Timberling" } },
    },
    [919] = { -- Timberling Sprouts
        title = { "18:830003962:322515766", "ต้นอ่อนทิมเบอร์ลิง" },
        objective = { "56:792336637:1951635299", "นำ Timberling Sprout 12 ต้นไปให้ Denalan ที่ Lake Al'Ameth" },
        description = { "311:422929986:1380872347", "ทิมเบอร์ลิงตัวเล็ก ๆ กำลังงอกอยู่ริมน้ำของ Lake Al'Ameth ข้าเกรงว่าจะช่วยต้นอ่อนพวกนี้ไม่ทันแล้ว เราควรเก็บออกจากพื้นที่ก่อนจะโตพอสร้างปัญหา\n\nระหว่างเดินแถวทะเลสาบ ถ้าเจอต้นอ่อนทิมเบอร์ลิงก็ช่วยเก็บมาที ช่วยกันดูแลผืนดินของเราให้สะอาด!" },
        progress = { "7:989913233:66981971 N 45:93709410:2106896481", "สวัสดี {name} เจอต้นอ่อนริมน้ำบ้างหรือยัง?" },
        completion = { "145:1359840756:1125590100 N 48:1692594474:2088129981", "เยอะทีเดียว! ข้าเกรงว่าพวกมันแพร่พันธุ์เร็วเกินไปแล้ว หวังว่าข้าจะไขปริศนาได้ว่าอะไรทำให้พวกมันแปดเปื้อน\n\nขอบใจที่ช่วย {name} ความพยายามของเจ้าช่วยให้ผืนดินนี้สะอาดขึ้น" },
        required = { [5169] = { "17:1950170014:707361158", "หน่อ Timberling" } },
        steps = { { "17:1950170014:707361158", "หน่อ Timberling" } },
    },
    [922] = { -- Rellian Greenspyre
        title = { "18:1317388245:804315441", "เรลเลียน กรีนสไปร์" },
        objective = { "59:242731130:516104161", "นำ Timberling Seed 1 เมล็ดไปให้ Rellian Greenspyre ใน Darnassus" },
        description = { "N 281:1683514821:1331018953 N 184:1956781215:654529786", "{name} ช่วยเอาเมล็ดที่นำมาให้ข้าสักเมล็ดไปให้ Rellian Greenspyre เพื่อนของข้าได้ไหม? เขาเป็นดรูอิดใน Darnassus ครั้งล่าสุดที่คุยกัน เขาสนใจงานศึกษาทิมเบอร์ลิงของข้ามาก เขามีแนวคิดของตัวเองและคงยินดีที่ได้เมล็ดตัวอย่างไปทดลอง\n\nขอบใจ {name} เจ้าช่วยข้าไว้มาก หวังว่าสักวันเจ้าจะได้เห็นผลงานของข้าออกดอกออกผล\n\nปกติเจ้าจะพบ Rellian เดินอยู่ตามทางใน Cenarion Enclave ของ Darnassus", variants = { { "N 281:1683514821:1331018953 N 184:40532571:506165032", "{name} ช่วยเอาเมล็ดที่นำมาให้ข้าสักเมล็ดไปให้ Rellian Greenspyre เพื่อนของข้าได้ไหม? เขาเป็นดรูอิดใน Darnassus ครั้งล่าสุดที่คุยกัน เขาสนใจงานศึกษาทิมเบอร์ลิงของข้ามาก เขามีแนวคิดของตัวเองและคงยินดีที่ได้เมล็ดตัวอย่างไปทดลอง\n\nขอบใจ {name} เจ้าช่วยข้าไว้มาก หวังว่าสักวันเจ้าจะได้เห็นผลงานของข้าออกดอกออกผล\n\nปกติเจ้าจะพบ Rellian เดินอยู่ตามทางใน Cenarion Enclave ของ Darnassus" } } },
        progress = { "32:1385845819:2143908146", "สวัสดี...\n\nมีอะไรให้ข้าช่วยหรือ?" },
        completion = { "393:872502002:474145772", "อา เมล็ดทิมเบอร์ลิงหรือ? ข้าอยากลองปลูกมันเพื่อช่วย Denalan ศึกษาพอดี\n\nแต่ข้าเกรงว่าความชั่วร้ายได้หยั่งรากในทิมเบอร์ลิงจำนวนมากแล้ว เมล็ดจากพวกมันก็รับความแปดเปื้อนมาจากต้นกำเนิดด้วย เรื่องนี้เกินกว่าที่ข้าจะรักษาได้\n\nDenalan เชี่ยวชาญเรื่องการเจริญเติบโตของพืชมาก เขาอาจหาทางรักษาทิมเบอร์ลิงรุ่นต่อไปได้ เขาอาจเป็นความหวังเดียวของพวกมัน" },
        required = { [5168] = { "15:1172809109:835018016", "เมล็ด Timberling" } },
        objectiveLabels = {
            item = { ["Timberling Seed"] = "เมล็ด Timberling" },
        },
    },
    [927] = { -- The Moss-twined Heart
        title = { "21:199315872:1926731864", "หัวใจที่มอสพันรัด" },
        objective = { "56:20726890:815916271", "นำ Moss-twined Heart ไปให้ Denalan ที่ Lake Al'Ameth" },
        description = { "225:1087893599:549956139", "หัวใจของ Blackmoss the Fetid ปกคลุมด้วยมอสสีดำเป็นมัน อันที่จริง สิ่งเดียวที่บอกได้ว่านี่คือหัวใจคือจังหวะเต้นช้า ๆ สม่ำเสมอ... ซึ่งยังคงเต้นอยู่แม้ในยามนี้\n\nบางที Denalan อาจอยากเห็นหัวใจดวงนี้" },
        progress = { "N 28:868718247:1210572640", "{name}! มีอะไรมาให้ข้าหรือ?" },
        completion = { "104:573929917:95849209 N 93:268858681:1463515220", "...นี่อะไร? หัวใจทิมเบอร์ลิงหรือ?? มันมีมอสเน่าเหม็นขึ้นเต็มไปหมด!\n\nขอบใจที่นำมาให้ข้า {name} ข้าจะตรวจหัวใจนี้ และหากโชคดีก็คงรู้ได้ว่ามอสที่เกาะอยู่คืออะไรกันแน่" },
        required = { [5179] = { "17:919365766:2106156637", "หัวใจพันด้วยมอส" } },
        steps = { { "17:919365766:2106156637", "หัวใจพันด้วยมอส" } },
    },
    [929] = { -- Crown of the Earth
        title = { "18:1054641003:2021293941", "มงกุฎแห่งพิภพ" },
        objective = { "72:1521492697:1286997789", "เติมน้ำลงใน Jade Phial แล้วนำกลับไปให้ Corithras Moonrage ใน Dolanaar" },
        description = { "488:110357842:1021606", "ก่อนอื่น ข้าจะอธิบายงานที่เจ้าต้องทำให้ละเอียดขึ้น ดรูอิดใน Darnassus ใช้น้ำจากบ่อจันทร์ทั่ว Teldrassil และต้องเติมน้ำในบ่อของตนเป็นครั้งคราว ขวดที่ทำขึ้นเป็นพิเศษเหล่านี้ใช้เก็บน้ำจากบ่อจันทร์ได้\n\nนำภาชนะนี้ไปตักน้ำจากบ่อจันทร์ด้านนอก Starbreeze Village ทางตะวันออก แล้วกลับมาหาข้า เมื่องานเสร็จ ข้าจะเล่าเรื่องต่อจากที่ Tenaron ค้างไว้..." },
        progress = { "13:1366380142:1891123769 N 31:1029889273:681068157", "พบกันอีกแล้ว {name} ทำงานเสร็จหรือยัง?" },
        completion = { "297:1038682000:2066054195", "หลังศึก Mount Hyjal พวกเราไร้ทิศทาง Nordrassil ยังคงมีควันจากไฟที่มันปลดปล่อยออกมา และความเป็นอมตะของเรา ซึ่งเป็นแก่นแท้แห่งตัวตนของเรา ก็สูญสิ้นไป\n\nในช่วงเวลาอันยากลำบากนั้นเอง ผู้ทรยศได้รับการปล่อยตัวจากคุก และ Shan'do Stormrage ก็หายสาบสูญ เป็นยุคมืดของพวกเราทุกคน" },
        required = { [5639] = { "17:1660211274:1741437930", "ขวดหยกที่เติมแล้ว" } },
        steps = { { "17:1660211274:1741437930", "ขวดหยกที่เติมแล้ว" } },
    },
    [930] = { -- The Glowing Fruit
        title = { "17:696503474:776205125", "ผลไม้เรืองแสง" },
        objective = { "52:1176680598:441934523", "นำผลไม้เรืองแสงไปให้ Denalan ที่ Lake Al'Ameth" },
        description = { "135:1357243551:197587834", "ใต้ใบของพืชเรืองแสงต้นนี้ มีผลไม้กลมขนาดใหญ่ห้อยอยู่\n\nเจ้าแน่ใจว่า Denalan คงอยากศึกษาผลไม้นี้" },
        progress = { "N 91:665071088:931511136", "{name} ดูเหมือนเจ้ามีเรื่องจะบอกข้า มีข่าวเกี่ยวกับพวกทิมเบอร์ลิงหรือ?" },
        completion = { "270:215510425:1813130028 N 55:718583461:866957862", "เจ้าพบสิ่งนี้บน Teldrassil หรือ? น่าสนใจ... ผลไม้นี้เป็นพันธุ์ต่างถิ่น บางทีเมล็ดของมันอาจถูกนำมาจากที่ไกลแสนไกล อาจไกลถึง Azeroth เลยทีเดียว! และผลไม้นี้มีบางอย่าง... ดูเหมือนมันทำปฏิกิริยากับดินของ Teldrassil อย่างแปลกประหลาดมาก\n\nขอบใจ {name} ถ้าเช่นนั้น ข้าขอตัวไปศึกษามันต่อก่อน..." },
        required = { [5189] = { "13:959440860:821019825", "ผลไม้เรืองแสง" } },
        steps = { { "13:959440860:821019825", "ผลไม้เรืองแสง" } },
    },
    [931] = { -- The Shimmering Frond
        title = { "20:684218160:1656837286", "ใบไม้ระยิบระยับ" },
        objective = { "52:1541056209:1276738401", "นำ Shimmering Frond ไปให้ Denalan ที่ Lake Al'Ameth" },
        description = { "145:163568553:1639399691", "ใบของพืชต้นนี้ส่องประกายเมื่อกระทบแสงในป่า ราวกับมีรัศมีที่บิดพลิ้วและเต้นเป็นจังหวะ\n\nเจ้าเชื่อว่า Denalan คงอยากได้ตัวอย่างของมัน" },
        progress = { "26:1938204992:443522829", "มีอะไรมาให้ข้าหรือ?" },
        completion = { "219:680182850:296409761 N 93:973811013:947896901", "เจ้าเอามันมาจากไหน? ข้าไม่เห็นพืชแบบนี้อีกเลยนับตั้งแต่ไปพักอยู่ที่ Swamp of Sorrows... เมื่อหลายสิบปีก่อน! ไม่น่าเชื่อว่าจะมีต้นหนึ่งเดินทางมาถึง Teldrassil แถมโตขนาดนี้ด้วย!\n\nขอบใจ {name} ข้าขอพูดสั้น ๆ หน่อยนะ มีการทดลองที่อยากลองกับใบไม้นี้..." },
        required = { [5190] = { "16:946054903:2133604080", "ใบไม้แวววาว" } },
        steps = { { "16:946054903:2133604080", "ใบไม้แวววาว" } },
    },
    [932] = { -- Twisted Hatred
        title = { "14:1379174177:1434409098", "ความเกลียดชังอันบิดเบี้ยว" },
        objective = { "72:386810593:1283684878", "ฆ่า Lord Melenas แล้วนำหัวของเขาไปให้ Tallonkai Swiftroot ใน Dolanaar" },
        description = { "17:1828699078:946148113 N 409:226652904:1068962942", "ข้าต้องเตือนเจ้า {name} เรื่องนี้ต้องเก็บไว้ระหว่างเรา ลำพังซาเทียร์ก็เป็นความอัปยศของพวกเรามากพอแล้ว และตนนี้ก็อยู่ใกล้บ้านเกินไป\n\nมันเรียกตัวเองว่า Lord Melenas อาศัยอยู่ในถ้ำ Fel Rock ใกล้ ๆ และรวบรวมนักรบเกรลล์ไว้เป็นจำนวนมาก จิตใจของมันมืดดำดุจราตรี และกำลังวางแผนเรื่องชั่วร้ายอย่างยิ่ง\n\nเจ้าต้องไปหามันในถ้ำทางเหนือของที่นี่ แล้วนำหัวของมันกลับมาให้ข้า" },
        progress = { "89:138117259:542083738 N 56:1745356354:1984433429", "ฆ่า Lord Melenas แล้วหรือยัง? เราต้องจัดการมันอย่างรวดเร็วและเงียบเชียบ {name} การที่มันยังมีชีวิตอยู่เป็นความอับอายของพวกเราทุกคน" },
        completion = { "82:1205652043:744504029 N 1:46:46", "เมื่อ Lord Melenas สิ้นแล้ว ข้าก็หันไปจัดการเรื่องอื่นได้เสียที ขอบใจ {name}" },
        required = { [5221] = { "13:1139402612:1944832658", "หัวของ Melenas" } },
        steps = { { "13:1139402612:1944832658", "หัวของ Melenas" } },
    },
    [933] = { -- Crown of the Earth
        title = { "18:1054641003:2021293941", "มงกุฎแห่งพิภพ" },
        objective = { "78:1716709358:224833854", "เติมน้ำลงใน Tourmaline Phial แล้วนำกลับไปให้ Corithras Moonrage ใน Dolanaar" },
        description = { "311:1810024759:232902591", "มีบ่อจันทร์อีกแห่งอยู่ทางตะวันออกเฉียงใต้ของทางเข้า Darnassus บนชายฝั่ง Pools of Arlithrien พวก Sentinel ลาดตระเวนบริเวณนั้นได้ลำบาก เพราะเฟอร์โบลก์เผ่า Gnarlpine โจมตีผู้คนและดุร้ายขึ้นทุกที\n\nระวังตัวระหว่างตามหาบ่อ และเตรียมอาวุธให้พร้อม" },
        progress = { "211:2100606319:1210605330", "แรกทีเดียว ไม่มีใครเชื่อรายงานเรื่องเฟอร์โบลก์คลุ้มคลั่งโจมตีผู้คน ใครจะคิดว่ามนุษย์หมีผู้รักสงบจะกลายเป็นพวกบ้าคลั่งไร้สติ? นี่ก็เป็นอีกปัญหาที่รุมเร้าเราในบ้านใหม่แห่งนี้" },
        completion = { "479:1570517132:1159145871", "Shan'do Stormrage ไม่เคยกลับมา เหล่าดรูอิดจึงระส่ำระสาย แม้จนวันนี้เราก็ยังไม่รู้ว่าเกิดอะไรขึ้นกับเขา เมื่อ Malfurion หายตัวไป อัครดรูอิด Fandral Staghelm จึงขึ้นเป็นผู้นำเหล่าดรูอิด เขาโน้มน้าวสภาเหล่าผู้เก่าแก่ใน Darkshore ว่าถึงเวลาที่เผ่าพันธุ์เราต้องฟื้นฟูบ้านเมือง และทวงคืนความเป็นอมตะ\n\nเมื่อสภาเห็นชอบ Staghelm กับเหล่าดรูอิดผู้ทรงพลังก็ปลูก Teldrassil ต้นไม้โลกต้นใหม่ขึ้น" },
        required = { [5645] = { "23:277200554:124407556", "ขวดทัวร์มาลีนที่เติมแล้ว" } },
        steps = { { "23:277200554:124407556", "ขวดทัวร์มาลีนที่เติมแล้ว" } },
    },
    [934] = { -- Crown of the Earth
        title = { "18:1054641003:2021293941", "มงกุฎแห่งพิภพ" },
        objective = { "76:711720315:1258512144", "เติมน้ำลงใน Amethyst Phial แล้วนำกลับไปให้ Corithras Moonrage ใน Dolanaar" },
        description = { "476:1613966783:2105557718", "แต่ Teldrassil ก็ไม่ได้สมบูรณ์พร้อมทุกด้าน แผนที่ Staghelm วางไว้อย่างรอบคอบสำหรับต้นไม้โลกต้นใหม่สำเร็จดังใจหวัง ทว่ายังมีปัญหาเล็ก ๆ อยู่เรื่องหนึ่ง ซึ่งอาจเป็นต้นเหตุของปัญหามากมายบน Teldrassil\n\nข้ายังไม่เล่าเรื่องนั้นตอนนี้ เจ้าต้องไปบ่อจันทร์แห่งสุดท้ายที่ Oracle Glade ทางตะวันตกเฉียงเหนือ ใต้กิ่งก้านของ Oracle Tree คือบ่อแห่งแรกและทรงพลังที่สุดของเรา ตักน้ำใส่ขวดแล้วกลับมาหาข้า" },
        progress = { "188:2025468378:583122702", "Oracle Tree และอัครดรูอิดเฝ้าติดตามการเติบโตของ Teldrassil อย่างใกล้ชิดร่วมกับเหล่าดรูอิด แต่ถึงจะมีบ้านใหม่แล้ว ชีวิตอมตะของเราก็ยังไม่กลับคืนมา" },
        completion = { "496:95654127:1429069621", "การได้อยู่ต่อหน้า Oracle Tree... แทบเหมือนเห็นปัญญาอันล้ำลึกมีรูปร่างขึ้นมา ข้าจะเล่าต่อแล้วนะ...\n\nเมื่อ Teldrassil เติบโตขึ้น อัครดรูอิดก็ไปขอพรจากเหล่ามังกร เช่นที่พวกเขาเคยมอบให้ Nordrassil ในอดีต แต่ Nozdormu เจ้าแห่งกาลเวลา ปฏิเสธและตำหนิความทะนงตนของดรูอิด Alexstrasza เห็นพ้องกับ Nozdormu และปฏิเสธ Staghelm เช่นกัน เมื่อปราศจากพรของนาง Teldrassil จึงเติบโตอย่างบกพร่องและคาดเดาไม่ได้..." },
        required = { [5646] = { "21:1608273970:1618028142", "ขวดน้ำศักดิ์สิทธิ์" } },
        steps = { { "21:1608273970:1618028142", "ขวดน้ำศักดิ์สิทธิ์" } },
    },
    [935] = { -- Crown of the Earth
        title = { "18:1054641003:2021293941", "มงกุฎแห่งพิภพ" },
        objective = { "68:824304865:2143583935", "นำ Filled Vessel ไปให้ Arch Druid Fandral Staghelm ใน Darnassus" },
        description = { "493:153280873:217415244", "เมื่อไร้พรจาก Alexstrasza ผู้ผูกชีวิต และ Nozdormu ผู้เหนือกาลเวลา Teldrassil จึงเติบโตอย่างไม่สมบูรณ์ มีรายงานว่าสัตว์ประหลาดผุดขึ้นจากผืนดินบนต้นไม้ และเฟอร์โบลก์คลุ้มคลั่งโจมตีผู้เดินทาง\n\nข้าได้แต่หวังว่าอัครดรูอิดจะพบวิธีแก้โดยเร็ว ข้าจะเทน้ำทุกขวดที่เจ้าหามารวมในภาชนะนี้ ให้เจ้านำไปส่งที่ Darnassus\n\nเอาไปให้ Fandral Staghelm เจ้าจะพบเขาในสวนของดรูอิด" },
        progress = { "141:482465205:1600792655", "ข้าจำได้ว่าไม่ได้เรียกเจ้า จึงอดสงสัยไม่ได้ว่ามาหาข้าทำไม\n\nไม่ว่าเรื่องอะไร ก็ขอให้รีบพูด" },
        completion = { "362:1547981822:426091124", "อา ใช่ น้ำที่ข้าขอไว้ Tenaron กับ Corithras ส่งมาเสียช้าเชียว... บางทีอาจเลือกคนส่งสารที่ไม่น่าไว้ใจนัก... อืม\n\nถึงอย่างไร ข้าก็กลับไปทำงานได้เสียที ปัญหาของ Teldrassil ทั้งหมดหนักอยู่บนบ่าข้า เป็นภาระที่ข้าอยากปลดออกให้ได้โดยเร็ว\n\nรับนี่ไป เจ้าอาจใช้ประโยชน์จากมันได้" },
        required = { [5188] = { "13:766492932:100937312", "ภาชนะที่เติมแล้ว" } },
        steps = { { "13:766492932:100937312", "ภาชนะที่เติมแล้ว" } },
    },
    [937] = { -- The Enchanted Glade
        title = { "19:1039395336:204496382", "พงไพรต้องมนตร์" },
        objective = { "95:219274711:224899674", "นำ Bloodfeather Belt 6 เส้นไปให้ Sentinel Arynia Cloudsbreak ใน Oracle Glade" },
        description = { "442:197677769:250225401", "ข้ากับ Sentinel กลุ่มเล็ก ๆ ถูกส่งมาปกป้อง Oracle Tree จากฮาร์ปีที่ทำรังอยู่รอบพงไพร เรากำลังค่อย ๆ ผลักดันพวกมันออกไป\n\nเมื่อ Oracle Tree ส่งคนไปแจ้งข่าวที่ Darnassus ผู้ส่งสารก็ถูกฮาร์ปีกลุ่มหนึ่งโจมตีและสังหาร\n\nถ้าเจ้าคิดว่าทำไหว จงไปที่รังของพวกมัน สังหารพวกมัน แล้วนำเข็มขัดกลับมาให้ข้าเป็นหลักฐาน" },
        progress = { "93:740514567:219588309 N 55:1809897073:2076973865", "กรงเล็บคมกริบและจะงอยปากแหลมของพวกมันอาจรับมือได้ยากสำหรับเจ้า {name} แต่ข้าเชื่อว่าเจ้าจะทำงานนี้สำเร็จ" },
        completion = { "70:1105851869:52918784 N 276:1743171412:1271981761", "ข้าประทับใจที่เจ้าทำได้มากขนาดนี้ในเวลาอันสั้น {name} อยากขอให้เจ้าอยู่ช่วยงานข้าที่นี่ต่อเหลือเกิน... แต่ข้ารู้ว่าเจ้ามีภารกิจที่ยิ่งใหญ่กว่ารออยู่\n\nข้าสังเกตว่า Oracle Tree เพิ่งผลัดเปลือกออกมาชิ้นหนึ่ง มันคงมีงานอยากให้ช่วยแน่ ๆ เจ้าควรไปคุยกับมัน", variants = { { "150:1183302032:1523893595", "ขอบใจที่ช่วยมาจนถึงตอนนี้ เจ้าแบ่งเบาภาระข้าไปได้มาก ขอข้าตรวจเข็มขัดพวกนี้ก่อน เผื่อจะพบเบาะแสว่าทำไมพวกฮาร์ปีถึงก้าวร้าวขึ้น" } } },
        required = { [5204] = { "17:701460182:1230830300", "เข็มขัด Bloodfeather" } },
        steps = { { "17:701460182:1230830300", "เข็มขัด Bloodfeather" } },
    },
    [938] = { -- Mist
        title = { "4:1314008477:174920093", "มิสต์" },
        objective = { "81:1912999112:1606835204", "พา Mist ไปหา Sentinel Arynia Cloudsbreak ที่บ่อจันทร์ใกล้ Oracle Tree" },
        description = { "307:2119675790:312415829", "ขนสีเทาอันโดดเด่นของเสือเขี้ยวดาบตัวนี้กลมกลืนกับป่ารอบข้าง ขณะมองมันนอนอยู่ เจ้าก็เห็นว่ามันบาดเจ็บสาหัส มีแผลลึกตามหลังและท้อง\n\nมันยกหัวขึ้นมองเจ้า แววฉลาดฉายอยู่ในดวงตาสีฟ้า ดูเหมือนมันอยากตามเจ้าไป" },
        progress = { "98:1108567212:1908338288", "Mist... เป็นความผิดของข้าเอง! พวกแม่มดเล่นงานตอนข้าเผลอ... ข้าไม่น่าปล่อยให้พวกมันจับเจ้าไปเลย..." },
        completion = { "15:403356219:907429681 N 192:411499044:1108253207", "ขอบใจมาก {name}! ข้ากลัวว่าจะไม่ได้พบ Mist อีก ได้แต่เก็บความตายของมันไว้ในใจ และไม่มีวันได้กลับมาอยู่กับสหายผู้ซื่อสัตย์ เจ้าช่วยข้าไว้มากเกินกว่าจะบอกได้ ข้าจะขอบคุณเจ้าตลอดไป" },
        objectiveLabels = {
            event = { ["Lead Mist safely to Sentinel Arynia Cloudsbreak"] = "พา Mist ไปหา Sentinel Arynia Cloudsbreak อย่างปลอดภัย" },
        },
    },
    [940] = { -- Teldrassil
        title = { "10:1907102904:1158862771", "เทลดรัสซิล" },
        objective = { "77:544857625:1826337082", "นำรายงานของ Oracle Tree ไปให้ Arch Druid Fandral Staghelm ใน Darnassus", variants = { { "71:272196881:964216188", "นำเปลือกไม้จารึกไปให้ Arch Druid Fandral Staghelm ใน Darnassus" } } },
        description = { "44:860479475:112197396 N 347:2049792599:1593668259", "ป่ากระซิบถึงความกล้าหาญของเจ้า {name} เมื่อข้าสัมผัสได้ว่าพวกฮาร์ปีถูกขับไล่ออกจากรัง ความสงบก็แผ่คลุมป่ามากขึ้น เหล่าสัตว์รู้สึกปลอดภัยอีกครั้ง ข้าไม่กล้าส่งคนไปหาอัครดรูอิดอีก แต่ข้ารู้ว่าเจ้าจะนำสารไปถึงเขาอย่างปลอดภัย\n\nนำสิ่งนี้ไปให้เขา และจงรู้ว่าป่าจะคุ้มครองเจ้าตลอดเส้นทางสู่ป่าศิลา" },
        progress = { "67:324846970:1492877245 C 64:913836741:359527878", "อืม... วิญญาณแห่งป่าอยู่ในตัวเจ้าอย่างเข้มแข็ง {class} มีธุระอะไรกับอัครดรูอิดแห่งชาวคัลโดไรหรือ?" },
        completion = { "344:72591509:2115978646", "ข้าสงสัยอยู่แล้วว่าเหตุใด Oracle Tree จึงเงียบหายไปนาน... ดูเหมือนบางปัญหาจะบรรเทาลง ขณะที่บางปัญหากลับยิ่งน่าวิตก\n\nข้าเกรงว่างานของข้าบน Teldrassil จะไม่มีวันเสร็จ และความเป็นอมตะของเราจะไม่กลับคืนมา\n\nถึงอย่างไร เจ้าก็ทำงานของ Oracle Tree ได้ดี สมควรได้รับรางวัลสำหรับความอุตสาหะ" },
        required = { [5219] = { "14:1242266519:1056307599", "เปลือกไม้จารึก" } },
        steps = { { "14:1242266519:1056307599", "เปลือกไม้จารึก" } },
    },
    [941] = { -- Planting the Heart
        title = { "18:787512081:1294645847", "ปลูกหัวใจ" },
        objective = { "45:1237326730:1345025343", "ปลูก Tainted Heart ลงใน Denalan's Planter" },
        description = { "180:548189402:1728794002", "ข้าเอามอสเน่าเหม็นออกจากหัวใจแล้ว แต่มันยังคงแปดเปื้อนอยู่...\n\nลองวางหัวใจลงในกระถางของข้าดู ข้างในมีดินอุดมสารอาหาร ซึ่งอาจช่วยชำระและรักษาหัวใจได้" },
        progress = { "64:1052551510:1450281854", "กระถางนี้เต็มไปด้วยดินที่ Denalan เตรียมไว้เป็นพิเศษ" },
        completion = { "174:1878667097:19726638", "เจ้าวางหัวใจลงในกระถาง และมันก็มุดลงดินทันที!\n\nไม่กี่วินาทีต่อมา มันก็ดิ้นกลับขึ้นมาอย่างสะอาดบริสุทธิ์ หัวใจเต้นเบา ๆ... ราวกับเชื้อเชิญให้เจ้าหยิบไป" },
        required = { [5217] = { "13:1994586826:1617178217", "หัวใจแปดเปื้อน" } },
        steps = { { "13:1994586826:1617178217", "หัวใจแปดเปื้อน" } },
    },
    [997] = { -- Denalan's Earth
        title = { "15:85329825:319937202", "ดินของเดนาลัน" },
        objective = { "60:880280137:1652936004", "นำห่อ Rare Earth ไปให้ Denalan ที่ Lake Al'Ameth" },
        description = { "378:1384545014:84245097", "เจ้าจะไปทางใต้หรือ? ไป Lake Al'Ameth ใช่ไหม? ถ้าอย่างนั้น ข้ามีงานอยากฝากหน่อย...\n\nDenalan เพื่อนร่วมงานของข้าตั้งค่ายอยู่ทางฝั่งตะวันออกของทะเลสาบ เขากำลังศึกษาและทดลองกับพืชของ Teldrassil เขาขอดินหายากจาก Darnassus ไว้ห่อหนึ่ง แต่มันมาช้าและเพิ่งมาถึง Dolanaar เมื่อไม่นานนี้\n\nเจ้านำไปให้เขาได้ไหม?" },
        progress = { "26:1938204992:443522829", "มีอะไรมาให้ข้าหรือ?" },
        completion = { { "130:2146177891:477991049 N 12:1131667476:323107827 R 31:1990898821:279219091", "130:2146177891:477991049 N 12:1131667476:323107827 R 31:1309465929:2096413484" }, "อา มาถึงแล้ว! ข้ารอดินหายากนี่อยู่นาน หวังว่าจะยังสดอยู่...\n\nขอบใจที่นำมาให้ข้า {name} เจ้าเป็นชาว{race} ที่มีน้ำใจยอมสละเวลาให้ผู้อื่น" },
        required = { [5391] = { "10:1334737163:936032833", "ดินหายาก" } },
        steps = { { "10:1334737163:936032833", "ดินหายาก" } },
    },
    [921] = { -- Crown of the Earth
        title = { "18:1054641003:2021293941", "มงกุฎแห่งพิภพ" },
        objective = { "77:342641147:844603941", "เติมน้ำลงใน Crystal Phial แล้วนำกลับไปให้ Tenaron Stormgrip ที่ยอด Aldrassil" },
        description = { "52:1693014507:2121414828 N 435:563783250:170093663", "ถึงเวลาที่เจ้าจะออกค้นหาเส้นทางของตัวเองแล้ว {name} แต่ก่อนจะพร้อมเดินทางออกจากป่าต้องมนตร์แห่งนี้ ยังมีประวัติศาสตร์ช่วงหลังของพวกเราอีกมากที่เจ้าต้องเรียนรู้\n\nนับตั้งแต่ศึก Mount Hyjal ผู้คนของเราเปลี่ยนไปมาก Nordrassil เหลือเพียงเงาเลือนรางของความยิ่งใหญ่ในอดีต พลังของมันถูกใช้เพื่อปราบ Archimonde และขับไล่ Burning Legion...\n\nมีงานอย่างหนึ่งที่เจ้าต้องทำ ไปที่บ่อจันทร์ทางเหนือของ Aldrassil แล้วตักน้ำใส่ขวดกลับมาให้ข้า" },
        progress = { "265:1391266426:1269705375", "บ่อจันทร์กักเก็บน้ำจาก Well of Eternity แหล่งเวทมนตร์โบราณที่เคยก่อความสยดสยองให้โลกมามากมาย\n\nดรูอิดใช้คุณสมบัติของน้ำนี้ให้เป็นประโยชน์ ส่วน Sentinel เคารพบ่อเหล่านี้ในฐานะศาลบูชา Elune แต่การใช้เวทมนตร์อาคมนั้นเป็นข้อห้ามสำหรับทุกคน" },
        completion = { "228:1617234950:1843041575", "เจ้าก็ได้ฟังเรื่องราวช่วงแรกหลังศึก Mount Hyjal แล้ว ยังมีอีกมากที่ต้องเล่า งานที่เจ้าเริ่มที่นี่จะดำเนินต่อไปตลอดการเดินทางผ่าน Teldrassil จนถึง Darnassus" },
        required = { [5184] = { "20:247538304:1319571975", "ขวดผลึกที่เติมแล้ว" } },
        steps = { { "20:247538304:1319571975", "ขวดผลึกที่เติมแล้ว" } },
    },
    [928] = { -- Crown of the Earth
        title = { "18:1054641003:2021293941", "มงกุฎแห่งพิภพ" },
        objective = { "68:1921986832:2029851074", "นำ Partially Filled Vessel ไปให้ Corithras Moonrage ใน Dolanaar" },
        description = { "448:646905102:2144419230 N 52:1031529987:1009349621", "ข้ายังมีเรื่องบ่อจันทร์และ Teldrassil ที่อยากเล่าอีก แต่ต้องให้เจ้าออกเดินทางแล้ว Corithras Moonrage รอเจ้าอยู่ ข้าเทน้ำจากขวดที่เจ้านำมาใส่ภาชนะนี้แล้ว เอาไปให้เขา\n\nเจ้าจะพบ Corithras ที่บ่อจันทร์ใน Dolanaar เดินตามถนนจาก Aldrassil ลงใต้ ออกจาก Shadowglen แล้วตามถนนปูหินต่อไปเมื่อถนนเลี้ยวไปทางตะวันตก\n\nอยู่บนถนนไว้ล่ะ {name} ช่วงนี้ในป่ามีสัตว์ร้ายอันตราย" },
        progress = { "11:927657569:725753248 C 56:1441985339:1568604255", "สวัสดี {class} มีเรื่องใดทำให้ข้าได้ยินดีพบเจ้าหรือ?" },
        completion = { "161:575231917:1360963182", "อา เข้าใจแล้ว Tenaron ส่งเจ้ามา ถ้าเช่นนั้น เรามีเรื่องให้คุยอีกมาก มีงานให้ทำอีกมาก แต่เวลาน้อยเหลือเกิน\n\nข้าว่าเราเริ่มกันเลยดีกว่า" },
        required = { [5186] = { "23:199910165:2057329407", "ภาชนะที่เติมไว้บางส่วน" } },
        steps = { { "23:199910165:2057329407", "ภาชนะที่เติมไว้บางส่วน" } },
    },
    [2159] = { -- Dolanaar Delivery
        title = { "17:1102831622:1581274537", "ของส่งไปโดลานาร์" },
        objective = { "50:51672421:1680523966", "นำ Dolanaar Delivery ไปให้ Innkeeper Keldamyr" },
        description = { "17:1545238973:664863442 C 307:1670457690:1564791627", "สวัสดี {class} รุ่นเยาว์ ช่วยข้าหน่อยได้ไหม? ข้ามีห่อสมุนไพรที่ต้องส่งไปเมือง Dolanaar แต่ยังติดธุระกับดรูอิดแห่ง Shadowglen จึงออกเดินทางไม่ได้\n\nเจ้าช่วยเอาไปส่งแทนข้าที ต้องส่งให้ Innkeeper Keldamyr ที่โรงเตี๊ยม Dolanaar ซึ่งอยู่ตามถนนลงไปทางใต้" },
        progress = { "107:843841544:1487849086", "มีอะไรให้ข้ารับใช้หรือ หนุ่มสาวเอ๋ย? มาพักที่โรงเตี๊ยมหรือ? ต้องการ Hearthstone ไหม?" },
        completion = { "432:872252774:2106884716", "อา ใช่ สมุนไพรจาก Shadowglen น่าเสียดายที่ Porthannius มาเองไม่ได้ ข้ากับเขามีเรื่องให้คุยกันมาก แต่ถึงอย่างไรข้าก็ดีใจที่สมุนไพรมาถึง และดีใจที่เจ้าแวะมา\n\nเมื่อมาถึงแล้วก็พักผ่อนเสียหน่อย วีรชนต้องรักษากำลังกายและใจให้พร้อม และหาเวลาพักให้ใจสงบเมื่อมีโอกาส การละเลยความสงบทั้งกายและใจย่อมนำไปสู่ความล้มเหลว\n\nเอาล่ะ... พักเถิด" },
        required = { [7627] = { "17:1102831622:1581274537", "พัสดุส่งไป Dolanaar" } },
        steps = { { "17:1102831622:1581274537", "พัสดุส่งไป Dolanaar" } },
    },
    [2438] = { -- The Emerald Dreamcatcher
        title = { "24:601342762:860875872", "เครื่องดักฝันมรกต" },
        objective = { "66:724304506:1404383836", "นำ Emerald Dreamcatcher ไปให้ Tallonkai Swiftroot ใน Dolanaar" },
        description = { "491:827388816:199726575 C 1:63:63", "ครั้งหนึ่ง Gaerolas Talvethen ผู้ดูแลดรูอิดใน Ban'ethil Barrow Den มอบเครื่องดักฝันมรกตให้ข้า เครื่องรางทรงพลังชิ้นนี้ดึงพลังจาก Emerald Dream มานำโชคให้ผู้พกพาได้\n\nแต่น่าเสียดาย ข้ายังเอามันออกจากตู้ในบ้านที่ Starbreeze Village ไม่ได้... แม้ที่นั่นเคยสงบสุข แต่บัดนี้กลับตกอยู่ใต้อิทธิพลชั่วร้ายของพวกเฟอร์โบลก์\n\nเจ้าจะช่วยไปเอาเครื่องดักฝันคืนมาให้ข้าได้ไหม {class}?" },
        progress = { "127:1285292453:1803923447 N 1:63:63", "รีบหน่อยเถิด ข้าได้แต่หวังว่าพวกเฟอร์โบลก์จะยังไม่ทำเครื่องดักฝันมรกตเสียหาย\n\nเจ้าเอากลับมาได้หรือยัง {name}?" },
        completion = { "114:1872866677:1785847956 N 1:46:46", "เครื่องดักฝันมรกตสำคัญต่อข้ามาก น้อยคนนักที่จะได้รับของขวัญเช่นนี้ ขอบใจที่นำกลับมาคืน {name}" },
        required = { [8048] = { "20:990930114:80715516", "ตาข่ายดักฝันมรกต" } },
        steps = { { "20:990930114:80715516", "ตาข่ายดักฝันมรกต" } },
    },
    [2459] = { -- Ferocitas the Dream Eater
        title = { "25:660626809:188892971", "เฟโรซิทัสผู้กลืนกินความฝัน" },
        objective = { "97:1577208681:1300764304", "Tallonkai Swiftroot ใน Dolanaar ขอให้เจ้าฆ่า Gnarlpine Mystic 7 ตัว และตามหา Missing Jewel" },
        description = { "415:1167280626:879002346 N 75:1326297094:520038327", "มรกต... มันหายไป! เครื่องดักฝันของข้าเสียหายแล้ว!\n\nมีพวกหมอผี Gnarlpine กลุ่มหนึ่งอยู่ทางเหนือของ Starbreeze ข้าได้ยินว่าหัวหน้าของพวกมัน Ferocitas the Dream Eater สวมสร้อยคอที่เรืองแสงสีเขียวยามค่ำคืน พอเห็นเครื่องดักฝันเช่นนี้ ข้าก็แน่ใจว่ามันขโมยมรกตของข้าไป... มันคงไม่รู้เลยว่าพลังของมรกตนั้นใช้กับตัวมันไม่ได้\n\nหาอัญมณีที่หายไปให้พบ {name} ระหว่างนั้นก็ช่วยกำจัดหมอผีที่เสื่อมทรามพวกนี้เสียด้วย" },
        progress = { "135:202981680:245922380", "Ferocitas และพวกหมอผี Gnarlpine ต้องคืนของของข้า ช่วยนำมรกตกลับมา ข้าจะได้ซ่อมเครื่องดักฝันได้" },
        completion = { "45:1414793295:1347825903 N 1:46:46", "ทีนี้ข้าก็ซ่อมเครื่องดักฝันได้แล้ว ขอบใจ {name}" },
        required = { [8050] = { "17:48846696:317891087", "อัญมณีของ Tallonkai" } },
        steps = { { "17:48846696:317891087", "อัญมณีของ Tallonkai" } },
        objectiveLabels = {
            monster = { ["Gnarlpine Mystic slain"] = "ปราบ นักเวทเร้นลับ Gnarlpine" },
        },
    },
    [2498] = { -- Return to Denalan
        title = { "17:24674851:1628843633", "กลับไปหาเดนาลัน" },
        objective = { "68:2127310764:1788377364", "Rellian Greenspyre ขอให้เจ้าไปคุยกับ Denalan ที่ Lake Al'Ameth" },
        description = { "196:1848178757:2147356478 N 20:1485247439:969815305", "ข้าเพิ่งได้ข่าวว่า Denalan ที่ Lake Al'Ameth อาจพบสาเหตุของเนื้องอกที่ทำให้ทิมเบอร์ลิงเจ็บป่วยแล้ว ช่วยไปคุยกับเขาและบอกว่าข้าส่งเจ้ามา\n\nรีบไปเถอะ {name} เขาต้องการความช่วยเหลือจากเรา" },
        completion = { "116:91277357:322039041", "อา Rellian ส่งเจ้ามาช่วยข้าสินะ ดีใจที่เจ้ามาถึงได้เร็ว\n\nข้าพบบางอย่างที่น่าวิตกมาก!" },
    },
    [2499] = { -- Oakenscowl
        title = { "10:1062658723:153982141", "โอเคนสเคาล์" },
        objective = { "83:979135236:1887032153", "Denalan ที่ Lake Al'Ameth ขอให้เจ้านำ Gargantuan Tumor จาก Oakenscowl มาให้" },
        description = { "330:512404904:1278317576 N 170:104090432:993884564", "ในถ้ำริมฝั่งใต้ของทะเลสาบ มีทิมเบอร์ลิงชื่อ Oakenscowl กำลังแพร่ความชั่วร้ายสู่ทุกชีวิตที่อาศัยอยู่รอบ Lake Al'Ameth\n\nข้าไม่กล้าเข้าใกล้นัก แต่แม้มองจากไกล ๆ ก็เห็นชัดว่าเนื้องอกที่ใหญ่ที่สุดเท่าที่ข้าเคยเห็นกำลังปล่อยพิษใส่ Oakenscowl... ใหญ่จนเรียกได้ว่ามหึมาเลยทีเดียว\n\n{name} เจ้าช่วยงานข้ามามากแล้ว แต่ขอฝากอีกสักงาน ไปตามล่า Oakenscowl แล้วเอาเนื้องอกมา กำจัดต้นตอความแปดเปื้อนนี้ออกจากบ้านของข้าที" },
        progress = { "33:1203987556:1151783254 R 1:63:63", "หา Oakenscowl พบหรือยัง ชาว{race}?" },
        completion = { "380:1847577675:1668482487 N 1:46:46", "ข้ารู้อยู่แล้วว่าเจ้าสามารถกำจัดสัตว์ร้ายตัวนั้นให้พ้นจากทะเลสาบได้\n\nน่าเศร้าเหลือเกิน Oakenscowl เคยเป็นผู้นำที่ยิ่งใหญ่ในหมู่ทิมเบอร์ลิง... แต่ความชั่วร้ายไม่เลือกว่าผู้ใดต่ำต้อยหรือสูงส่ง\n\nขนาดของเนื้องอกนี้น่าวิตกมาก แต่ข้าต้องศึกษามันเพื่อเข้าใจโรคที่กำลังคุกคามพวกทิมเบอร์ลิง\n\nขอบใจ {name}" },
        required = { [8136] = { "16:285000015:1887005303", "ก้อนเนื้อขนาดมหึมา" } },
        steps = { { "16:285000015:1887005303", "ก้อนเนื้อขนาดมหึมา" } },
    },
    [2541] = { -- The Sleeping Druid
        title = { "18:810387797:1460363598", "ดรูอิดผู้หลับใหล" },
        objective = { "73:1259069729:82476843", "นำ Shaman Voodoo Charm ไปให้ Oben Rageclaw ใน Ban'ethil Barrow Den" },
        description = { "457:130185705:1838117255 N 18:1924954124:1045991320", "ชาแมน Gnarlpine ที่อยู่ที่นี่ค้นพบวิธีแยกวิญญาณของดรูอิดที่หลับใหลออกจากร่าง พวกเฟอร์โบลก์บังคับร่างกายข้าให้เคลื่อนไหวและใช้โจมตีทุกคนที่เข้ามาสำรวจ Ban'ethil Barrow Den ตอนนี้ข้าติดอยู่ใน Emerald Dream และไม่อาจหยุดพวกมันได้\n\nเจ้าต้องช่วยข้า พวกชาแมน Gnarlpine พกเครื่องรางประหลาดที่ใช้ประกอบพิธีนี้ ข้าอยากลองตรวจมัน ได้โปรด {name} นำมาให้ข้าสักชิ้น" },
        progress = { "105:438154001:238382907", "หากได้ตรวจเครื่องราง ข้าอาจรู้วิธีทำลายมนตร์นี้ เจ้าหามาได้แล้วหรือยัง?" },
        completion = { "11:1191658970:1224418299 N 114:452743329:534677392", "ขอบใจ {name}\n\nช่างเป็นเครื่องรางประหลาด... ข้าสัมผัสได้ถึงรัศมีชั่วร้ายที่แผ่ออกมา มนตร์นี้ทรงพลังมาก" },
        required = { [8363] = { "19:1659455413:673692241", "เครื่องรางวูดูของชาแมน" } },
        steps = { { "19:1659455413:673692241", "เครื่องรางวูดูของชาแมน" } },
    },
    [2561] = { -- Druid of the Claw
        title = { "17:165944660:1250017656", "ดรูอิดแห่งกรงเล็บ" },
        objective = { "81:1414544019:613348178", "Oben Rageclaw ขอให้เจ้าฆ่าร่างที่ไร้วิญญาณของเขา แล้วใช้ Voodoo Charm" },
        description = { "28:647644468:1534048975 N 466:1305837027:1986068397", "หลังจากตรวจเครื่องรางนี้ {name} ข้ารู้แล้วว่าต้องทำอย่างไร รับมันไป แล้วช่วยทำตามที่ข้าขอ\n\nเจ้าต้องสำรวจส่วนลึกที่สุดของ Ban'ethil Barrow Den ที่นั่นเจ้าจะพบร่างไร้วิญญาณของข้า... แม้ข้าเสียใจที่จะต้องพูดเช่นนี้ แต่ไม่เห็นหนทางอื่นที่จะหลุดพ้นจากการควบคุมของ Gnarlpine\n\nเพื่อให้ข้าเป็นอิสระ เจ้าต้องฆ่าร่างกายข้า จากนั้นใช้เครื่องรางวูดูบนร่างที่ล้มลง เมื่อทำเสร็จแล้ว ช่วยกลับมาหาข้าด้วย" },
        progress = { "N 91:2003591323:390858326", "{name} ระวังตอนเข้าใกล้ร่างของข้า มนตร์ที่ครอบงำมันทรงพลังทีเดียว" },
        completion = { "62:141662081:1110841696 N 107:1169278823:1879992515 C 70:1613200859:323810022", "ในที่สุดข้าก็พ้นจากการควบคุมของ Gnarlpine ขอบใจ {name}\n\nตอนนี้วิญญาณข้าจะพักอย่างสงบใน Emerald Dream ได้ตลอดกาล\n\nสักวันเราอาจพบกันอีก {class} รุ่นเยาว์ แต่ตอนนี้ รับรางวัลนี้ไว้เป็นสัญลักษณ์แทนคำขอบคุณของข้าเถิด" },
        objectiveLabels = {
            event = { ["Release Oben Rageclaw's spirit"] = "ปลดปล่อยวิญญาณของ Oben Rageclaw" },
        },
    },
    [3519] = { -- A Friend in Need
        title = { "16:1340298935:1115884333", "เพื่อนผู้ต้องการความช่วยเหลือ" },
        objective = { "43:967386658:1242736570", "ไปคุยกับ Dirania Silvershine ใน Shadowglen" },
        description = { "267:1830995278:1528641155", "อึก... ข้าโดนแมงมุมชื่อ Githyiss the Vile กัดเข้าอย่างจัง ตอนสำรวจถ้ำแมงมุมใกล้ ๆ นี้ ข้ามั่นใจว่าได้รับพิษร้ายแรง เจ้าต้องช่วยข้า\n\nช่วยบอก Dirania Silvershine ที นางช่วยข้าได้\n\nรีบเถอะ... ข้าเวียนหัวเหลือเกิน..." },
        completion = { "111:169119956:1881328947", "ตายจริง ข้ากำลังสงสัยอยู่เลยว่าทำไมวันนี้ยังไม่เห็น Iverron ทั้งที่เตือนเขาเรื่องแมงมุมพวกนั้นอยู่เสมอ..." },
    },
    [3521] = { -- Iverron's Antidote
        title = { "18:2144936828:880709892", "ยาถอนพิษของไอเวอร์รอน" },
        objective = { "107:1110731716:395372254", "เก็บ Hyacinth Mushroom 7 ดอก, Moonpetal Lily 4 ดอก และ Webwood Ichor 1 ชิ้นไปให้ Dirania Silveshine ใน Shadowglen" },
        description = { "504:1004450473:1227014268", "เราอาจช่วย Iverron ได้ ข้ารู้จักยาถอนพิษที่น่าจะใช้รักษาได้ แต่ต้องมีส่วนผสมก่อนจึงจะปรุงขึ้นมาได้\n\nข้าต้องใช้เห็ดไฮยาซินธ์ หาได้ใต้ต้นไม้ หรือเก็บจากพวกเกรลล์ทางใต้ของที่นี่ ดูเหมือนพวกมันชอบเห็ดนี้ อีกอย่างคือดอกลิลลีมูนเพทัล ซึ่งขึ้นอยู่รอบแอ่งน้ำเท่านั้น\n\nอย่างสุดท้ายน่าจะยากที่สุด ไปเก็บ Webwood Ichor จากแมงมุมชนิดเดียวกับที่ทำให้ Iverron ต้องพิษ" },
        progress = { "33:1425670392:1137062836 N 25:1108420620:697363757", "ช่วยเก็บส่วนผสมด้วยเถอะ {name} Iverron ต้องการความช่วยเหลือจากเรา" },
        completion = { "117:547641260:1293930932", "ขอบคุณ Elune ที่เจ้าเก็บส่วนผสมมาได้เร็วขนาดนี้!\n\nอีกเดี๋ยวข้าก็จะปรุงยาถอนพิษเสร็จแล้ว" },
        required = { [10639] = { "17:1328541016:887945007", "เห็ดไฮยาซินธ์" }, [10641] = { "14:596981718:1279735575", "ลิลลีกลีบจันทร์" }, [10640] = { "13:1923613250:1247357267", "น้ำเหลือง Webwood" } },
        steps = { { "17:1328541016:887945007", "เห็ดไฮยาซินธ์" }, { "14:596981718:1279735575", "ลิลลีกลีบจันทร์" }, { "13:1923613250:1247357267", "น้ำเหลือง Webwood" } },
    },
    [3522] = { -- Iverron's Antidote
        title = { "18:2144936828:880709892", "ยาถอนพิษของไอเวอร์รอน" },
        objective = { "111:127087779:346517575", "นำ Iverron's Antidote ไปให้ Iverron ก่อนหมดเวลา เขาอยู่ใกล้ถ้ำทางเหนือ" },
        description = { "23:746849494:636633417 N 189:1476449823:981056247 N 1:46:46", "ยาถอนพิษพร้อมแล้ว {name} ช่วยเอาไปให้ Iverron ดื่มด้วย\n\nมีเรื่องหนึ่งที่เจ้าต้องรู้ ยาถอนพิษนี้จะยังใช้ได้เพียง 5 นาที ต้องไปถึงเขาให้ทัน\n\nขอให้เจ้าเดินทางได้รวดเร็ว {name}" },
        progress = { "6:1782768208:1167841506 N 32:611211358:516495859", "อา... {name} ข้าดีใจเหลือเกินที่เจ้ากลับมา" },
        completion = { "14:1181177336:334331504 N 371:440218102:456910465", "นี่อะไรหรือ {name}?\n\nข้ารู้อยู่แล้วว่า Dirania ต้องช่วยข้าได้!\n\n<Iverron ดื่มยาถอนพิษ>\n\nข้ามักก่อเรื่องอยู่เรื่อย ส่วน Dirania ก็คอยช่วยข้ารอดพ้นมาได้ทุกที\n\nข้ารู้สึกดีขึ้นมาก แต่คงนั่งพักตรงนี้ต่ออีกหน่อยจนกว่าจะหายดี แล้วก็... หวังว่าเจ้าจะช่วยเปิดทางผ่านแมงมุมเว็บวูดดุร้ายพวกนั้นให้ข้าด้วย...", variants = { { "14:1181177336:334331504 N 370:259263267:1829297514", "นี่อะไรหรือ {name}?\n\nข้ารู้อยู่แล้วว่า Dirania ต้องช่วยข้าได้!\n\n<Iverron ดื่มยาถอนพิษ>\n\nข้ามักก่อเรื่องอยู่เรื่อย ส่วน Dirania ก็คอยช่วยข้ารอดพ้นมาได้ทุกที\n\nข้ารู้สึกดีขึ้นมาก แต่คงนั่งพักตรงนี้ต่ออีกหน่อยจนกว่าจะหายดี แล้วก็... หวังว่าเจ้าจะช่วยเปิดทางผ่านแมงมุมเว็บวูดดุร้ายพวกนั้นให้ข้าด้วย..." } } },
        required = { [10642] = { "18:2144936828:880709892", "ยาแก้พิษของ Iverron" } },
        objectiveLabels = {
            item = { ["Iverron's Antidote"] = "ยาแก้พิษของ Iverron" },
        },
    },
    [923] = { -- Tumors
        title = { "6:281198023:468049055", "เนื้องอก" },
        objective = { "56:395510065:421036681", "นำ Mossy Tumor 5 ชิ้นไปให้ Rellian Greenspyre ใน Darnassus" },
        description = { "428:306220186:1314475882", "ความชั่วร้ายกำลังเติบโตในตัวทิมเบอร์ลิง เราพยายามหาต้นตออยู่ แต่ก่อนจะพบ... เพื่อรักษา Teldrassil ให้ปลอดภัย เราต้องโค่นตัวที่ช่วยไม่ได้แล้ว พวกที่เดินอยู่แถว Wellspring Lake ทางเหนือของ Teldrassil แปดเปื้อนหนักที่สุด ต้องกำจัดพวกมัน!\n\nทำลายทิมเบอร์ลิงที่พบ แล้วเก็บเนื้องอกที่มีมอสขึ้นบนตัวพวกมันมาให้ข้า ข้าจะเอาไปเผาทิ้ง" },
        progress = { "34:1070750948:523994668 N 46:1300849053:889192146", "ไป Wellspring Lake มาแล้วหรือ {name}? ได้ล่าทิมเบอร์ลิงแถวนั้นบ้างไหม?" },
        completion = { "182:28738895:143431760 N 1:46:46", "ทำได้ดี! เนื้องอกเหล่านี้เป็นอาการของโรคในทิมเบอร์ลิง ข้างในเต็มไปด้วยพิษที่เราต้องชำระออกจากดินแดนใหม่ของเรา\n\nข้าจะจัดการเนื้องอกพวกนี้เอง ขอบใจ {name}" },
        required = { [5170] = { "11:91977151:144023365", "ก้อนเนื้อที่มีมอสเกาะ" } },
        steps = { { "11:91977151:144023365", "ก้อนเนื้อที่มีมอสเกาะ" } },
    },
    [3120] = { -- Verdant Sigil
        title = { "13:2113133200:1044113120", "ตราผนึกพฤกษา" },
        objective = { "91:130722520:261206832", "อ่าน Verdant Sigil แล้วคุยกับ Mardant Strongoak ในต้นไม้ Aldrassil ที่ Shadowglen" },
        description = { "181:895919822:421211216", "ผู้ส่งสารจาก Mardant ครูฝึกดรูอิดของเรา ฝากตราผนึกนี้มาให้ ดูเหมือนเขาอยากคุยกับเจ้าเมื่อมีเวลา อ่านแล้วนำไปหาเขาเถิด" },
        progress = { "10:179830513:380461342 C 229:89870938:1192011396", "อา {class} รุ่นเยาว์ ข้าเห็นว่าเจ้าอยากศึกษาต่อ ดีมาก\n\nข้าสงสัยว่าเจ้าเคยใช้เวลาอยู่ใน Emerald Dream มากหรือยัง? บางทีเจ้าอาจยังไม่พร้อม... แต่ข้าเชื่อว่าสักวันเจ้าจะพร้อม\n\nระหว่างนี้ เรามาคุยเรื่องอื่นกันก่อน" },
        completion = { "372:1418934236:34278163", "ตอนนี้ข้าจะเป็นครูและผู้ชี้ทางให้เจ้า หน้าที่ของข้าคือสอนให้เจ้าเข้าใจทั้งสิ่งที่วิญญาณสื่อสารกับเรา และความซับซ้อนกับความลับของ Emerald Dream\n\nเมื่อเจ้าเรียนรู้และมีพลังมากขึ้น เจ้าจะเข้าใจภวังค์นิทราของเรามากขึ้นด้วย ระหว่างนี้ กลับมาหาข้าได้บ่อยเท่าที่ต้องการ ข้าจะสอนวิถีของพวกเราให้เท่าที่ทำได้" },
        required = { [9580] = { "13:2113133200:1044113120", "ตราเขียวขจี" } },
        steps = { { "13:2113133200:1044113120", "ตราเขียวขจี" } },
    },
    [3117] = { -- Etched Sigil
        title = { "12:2020989976:1762045358", "ตราผนึกสลักลาย" },
        objective = { "91:1601517612:1371602794", "อ่าน Etched Sigil แล้วคุยกับ Ayanna Everstride ที่ยอด Aldrassil ใน Shadowglen" },
        description = { "180:1687770848:1747101677", "ผู้ส่งสารจาก Ayanna ครูฝึกพรานของเรา ฝากตราผนึกนี้มาให้ ดูเหมือนนางอยากคุยกับเจ้าเมื่อมีเวลา อ่านแล้วนำไปหานางเถิด" },
        progress = { "35:2056188329:1426592346 N 278:1047032021:1566592111", "เจ้ามาถึงเสียที {name} ยินดีต้อนรับสู่ Shadowglen\n\nหวังว่าเจ้าจะสบายดีทั้งกายและใจตอนที่ได้รับตราผนึกของข้านะ?\n\nอย่างที่เคยบอก ข้าอยู่ที่นี่เพื่อฝึกเจ้าให้เป็นพราน ให้ฝึกสัตว์ป่ามาช่วยรบ ใช้ธนูอย่างแม่นยำ และเคารพทั้งผืนดินที่เราเรียกว่าบ้านกับดินแดนอื่นที่อยู่ไกลออกไป", variants = { { "35:2056188329:1426592346 N 130:297943239:55196521 C 142:2005199063:835372865", "เจ้ามาถึงเสียที {name} ยินดีต้อนรับสู่ Shadowglen\n\nหวังว่าเจ้าจะสบายดีทั้งกายและใจตอนที่ได้รับตราผนึกของข้านะ?\n\nอย่างที่เคยบอก ข้าอยู่ที่นี่เพื่อฝึกเจ้าให้เป็น{class} ให้ฝึกสัตว์ป่ามาช่วยรบ ใช้ธนูอย่างแม่นยำ และเคารพทั้งผืนดินที่เราเรียกว่าบ้านกับดินแดนอื่นที่อยู่ไกลออกไป" } } },
        completion = { "192:971519671:1503425038 N 155:711112463:946314737", "ระหว่างเรียนรู้สิ่งที่ Shadowglen จะสอนเจ้า จงแวะมาหาข้า ข้าจะช่วยให้เจ้าเข้าใจหน้าที่ของพรานและความสามารถของตัวเองมากขึ้น\n\nยุคนี้เต็มไปด้วยอันตราย {name} จงเห็นคุณค่าความสามารถของสัตว์เลี้ยง โลกนี้มีสิ่งที่อันตรายเกินจินตนาการอยู่มากมาย ขอ Elune คุ้มครอง แล้วกลับมาหาข้าอีก", variants = { { "129:2040153975:1924693921 C 57:229799102:1829127126 N 155:711112463:946314737", "ระหว่างเรียนรู้สิ่งที่ Shadowglen จะสอนเจ้า จงแวะมาหาข้า ข้าจะช่วยให้เจ้าเข้าใจหน้าที่ของ{class}และความสามารถของตัวเองมากขึ้น\n\nยุคนี้เต็มไปด้วยอันตราย {name} จงเห็นคุณค่าความสามารถของสัตว์เลี้ยง โลกนี้มีสิ่งที่อันตรายเกินจินตนาการอยู่มากมาย ขอ Elune คุ้มครอง แล้วกลับมาหาข้าอีก" } } },
        required = { [9567] = { "12:2020989976:1762045358", "ตราสลัก" } },
        steps = { { "12:2020989976:1762045358", "ตราสลัก" } },
    },
    [5923] = { -- Heeding the Call
        title = { "16:1185260992:259476408", "ขานรับเสียงเรียก" },
        objective = { "68:1126811676:987074176", "ไปคุยกับ Mathrengyl Bearwalker ใน Cenarion Enclave ของ Darnassus" },
        description = { "472:1060943100:897948186", "ขอเวลาสักครู่ สหาย...\n\nข้าได้ข่าวว่า Mathrengyl Bearwalker ฝากคำมาว่าอยากพบเจ้า ดูเหมือนการฝึกดรูอิดของเจ้ากำลังจะก้าวสู่ขั้นใหม่ และเขาจะฝึกให้ด้วยตัวเอง Mathrengyl เป็นผู้ช่วยใกล้ชิดของอัครดรูอิด และเป็นหนึ่งในดรูอิดที่รอบรู้และน่าเคารพที่สุดใน Teldrassil\n\nเขาอยู่ใน Cenarion Enclave ของ Darnassus บนชั้นสองของต้นไม้ที่ Fandral Staghelm พำนัก" },
        completion = { "469:1731892601:1710263841", "ดีใจที่เจ้ามาถึงที่นี่ในวันนี้ ดรูอิดรุ่นเยาว์ ถึงเวลาที่เจ้าจะก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิม\n\nในตัวลูกหลานของ Cenarius ทุกคนมีเสียงเรียกให้รับใช้ธรรมชาติ สัตว์และพืชเป็นทั้งสหายและผู้ที่เราเฝ้าดูแล เราเลือกอุทิศชีวิตเพื่อรักษาสมดุล ทั้งเพื่อพวกเขาและตัวเราเอง ก้าวแรกของเจ้าคือเรียนรู้วิถีแห่งหมี และเข้าใจความแข็งแกร่งของกายและใจ\n\nเตรียมตัวให้พร้อม!", variants = { { "47:608153914:1342807793 C 418:1421579562:2003121929", "ดีใจที่เจ้ามาถึงที่นี่ในวันนี้ {class}รุ่นเยาว์ ถึงเวลาที่เจ้าจะก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิม\n\nในตัวลูกหลานของ Cenarius ทุกคนมีเสียงเรียกให้รับใช้ธรรมชาติ สัตว์และพืชเป็นทั้งสหายและผู้ที่เราเฝ้าดูแล เราเลือกอุทิศชีวิตเพื่อรักษาสมดุล ทั้งเพื่อพวกเขาและตัวเราเอง ก้าวแรกของเจ้าคือเรียนรู้วิถีแห่งหมี และเข้าใจความแข็งแกร่งของกายและใจ\n\nเตรียมตัวให้พร้อม!" } } },
    },
    [5921] = { -- Moonglade
        title = { "9:1802734789:1124844045", "มูนเกลด" },
        objective = { "136:1565490422:1029565360", "ใช้เวท Teleport: Moonglade เดินทางไป Moonglade แล้วคุยกับ Dendrite Starblaze ในหมู่บ้าน Nighthaven" },
        description = { "504:1995799267:1876182875", "ดรูอิดทุกคนได้รับการต้อนรับในดินแดนศักดิ์สิทธิ์ Moonglade แม้ขณะนี้ใน Cenarion Circle จะมีความตึงเครียดระหว่างอัครดรูอิด Staghelm กับ Keeper Remulos ผู้พิทักษ์ Moonglade อยู่ก็ตาม เมื่อเจ้าเริ่มเรียนรู้วิถีแห่งกรงเล็บ ข้าจะสอนเวทเคลื่อนย้ายไปที่นั่น ใช้ได้ทุกครั้งที่แสวงหาความรู้หรือความสงบจาก Moonglade\n\nสำหรับบทเรียนแรก จงไปพบ Dendrite Starblaze ใน Nighthaven แล้วคุยเรื่องเส้นทางที่เจ้ากำลังเดิน ขอให้โชคดี ดรูอิดรุ่นเยาว์" },
        completion = { "374:278323581:119063747", "“และแล้วทุกอย่างก็เริ่มขึ้น บิดา Cenarius และแล้วก็เริ่มขึ้น”\n\nDendrite ทำท่าบางอย่างอย่างรวดเร็วกลางอากาศเหนือศีรษะ แม้มองไม่เห็นสิ่งที่เขาวาด แต่รัศมีพลังบางเบาก็คลุมตัวเขา\n\n“มุมมองแรกของธรรมชาติที่เจ้าต้องเรียนรู้คือมุมมองของหมี ข้าจะพาเจ้าเข้าสู่หนทางแห่งความเข้าใจในชีวิตดรูอิดด้านนี้ แต่เจ้าต้องเป็นผู้ยอมรับและสืบทอดมันด้วยตนเอง ทั้งในวันนี้และตลอดไป!”", variants = { { "372:985667623:1093892568", "“และแล้วทุกอย่างก็เริ่มขึ้น บิดา Cenarius และแล้วก็เริ่มขึ้น”\n\nDendrite ทำท่าบางอย่างอย่างรวดเร็วกลางอากาศเหนือศีรษะ แม้มองไม่เห็นสิ่งที่เขาวาด แต่รัศมีพลังบางเบาก็คลุมตัวเขา\n\n“มุมมองแรกของธรรมชาติที่เจ้าต้องเรียนรู้คือมุมมองของหมี ข้าจะพาเจ้าเข้าสู่หนทางแห่งความเข้าใจในชีวิตดรูอิดด้านนี้ แต่เจ้าต้องเป็นผู้ยอมรับและสืบทอดมันด้วยตนเอง ทั้งในวันนี้และตลอดไป!”" } } },
    },
    [5929] = { -- Great Bear Spirit
        title = { "17:848111912:388628440", "มหาวิญญาณหมี" },
        objective = { "196:546153198:1499699183", "ไปหา Great Bear Spirit ทางตะวันตกเฉียงเหนือของ Moonglade เรียนรู้ธรรมชาติของหมี แล้วกลับไปหา Dendrite Starblaze ใน Nighthaven" },
        description = { "498:521245163:849802520", "ทางตะวันตกเฉียงเหนือของ Moonglade เป็นที่พำนักของผู้มีปัญญาและสูงส่งที่เราเรียกว่า Great Bear Spirit เขาเป็นครูและผู้ชี้ทางให้ดรูอิดทุกคนเริ่มเข้าใจธรรมชาติของหมีอย่างแท้จริง ดรูอิดทุกคนต้องไปขอปัญญาจากเขาสักครั้ง และเจ้าก็เช่นกัน\n\nจงไปหา Great Bear Spirit แล้วเรียนรู้สิ่งที่เขาสอน เมื่อเขาพอใจในตัวเจ้าแล้ว ค่อยกลับมาหาข้าที่ Nighthaven จากนั้นเราจะดูว่าเจ้าได้เข้าใจบทเรียนเหล่านั้นจริงหรือไม่" },
        progress = { "121:228743085:1207218891", "จงกลับมาเมื่อ Great Bear Spirit อนุญาตให้เจ้ากลับมาหาข้าแล้วเท่านั้น การฝึกจะดำเนินต่อไม่ได้หากปราศจากพรของเขา" },
        completion = { "405:1355561431:1814612526", "เมื่อเจ้าเข้าใกล้ Dendrite ก็ทำท่าบางอย่างกลางอากาศเหนือศีรษะอีกครั้ง รัศมีพลังอีกระลอกคลุมตัวเขา และเขายิ้มเล็กน้อย\n\n“ข้าสัมผัสได้ถึงปัญญาในตัวเจ้าที่ไม่เคยมีเมื่อแรกพบ เจ้ามองข้าด้วยความแข็งแกร่งและความมุ่งมั่นที่รู้ชัด แต่ยังไม่ได้รวมใจไว้ที่จุดหมาย ต่อจากนี้เจ้าจะเรียนรู้การควบคุมกำลัง และนำธรรมชาติแห่งหมีมาใช้ในหน้าที่ของเจ้า”", variants = { { "405:1942604598:893650814", "เมื่อเจ้าเข้าใกล้ Dendrite ก็ทำท่าบางอย่างกลางอากาศเหนือศีรษะอีกครั้ง รัศมีพลังอีกระลอกคลุมตัวเขา และเขายิ้มเล็กน้อย\n\n“ข้าสัมผัสได้ถึงปัญญาในตัวเจ้าที่ไม่เคยมีเมื่อแรกพบ เจ้ามองข้าด้วยความแข็งแกร่งและความมุ่งมั่นที่รู้ชัด แต่ยังไม่ได้รวมใจไว้ที่จุดหมาย ต่อจากนี้เจ้าจะเรียนรู้การควบคุมกำลัง และนำธรรมชาติแห่งหมีมาใช้ในหน้าที่ของเจ้า”" } } },
        objectiveLabels = {
            event = { ["Seek out the Great Bear Spirit and learn what it has to share with you about the nature of the bear."] = "ไปหา Great Bear Spirit และฟังคำสอนเกี่ยวกับธรรมชาติของหมี" },
        },
    },
    [5931] = { -- Back to Darnassus
        title = { "17:1689456407:819125074", "กลับสู่ดาร์นัสซัส" },
        objective = { "81:127132541:296852743", "กลับไปคุยกับ Mathrengyl Bearwalker ใน Cenarion Enclave ของ Darnassus" },
        description = { "414:978551989:665862769", "ถึงเวลาที่เราต้องแยกกันก่อน เด็กรุ่นเยาว์เอ๋ย การนำบทเรียนไปใช้จะพาเจ้ากลับไปหาผู้ที่ส่งเจ้ามา Mathrengyl Bearwalker ดำเนินชีวิตอย่างสมดุลกับธรรมชาติ แม้จะอาศัยอยู่ใกล้จุดที่สมดุลสั่นคลอนอย่างน่าหวาดเสียว จงฟังคำแนะนำของเขา แล้วบทเรียนแรกในฐานะผู้รักษาสมดุลของเจ้าจะสำเร็จในไม่ช้า\n\nไปเถิด เราจะได้พบกันอีก" },
        completion = { "14:1649650394:897424258 N 463:1783497088:1531243079", "ยินดีต้อนรับกลับ {name} ข้าคิดว่าการพบ Great Bear Spirit ครั้งแรกของเจ้าคงเหมือนกับดรูอิดทุกคนที่เริ่มเดินบนวิถีแห่งกรงเล็บ... ชวนให้งุนงงอยู่บ้าง แต่ก็เข้มข้นลึกซึ้ง ข้าเองก็เคยรู้สึกเช่นนั้น\n\nGreat Bear Spirit อยู่คู่กับ Azeroth มานานเท่าที่โลกนี้ดำรงอยู่ในห้วงฟ้า เราพึ่งพาปัญญาและพลังของเขาเพื่อขับเคลื่อนหน้าที่ของเรา บัดนี้ถึงเวลาทดสอบความมุ่งหมายของเจ้าเป็นครั้งแรก ฟังให้ดี...", variants = { { "14:1649650394:897424258 N 468:912094341:1711441312", "ยินดีต้อนรับกลับ {name} ข้าคิดว่าการพบ Great Bear Spirit ครั้งแรกของเจ้าคงเหมือนกับดรูอิดทุกคนที่เริ่มเดินบนวิถีแห่งกรงเล็บ... ชวนให้งุนงงอยู่บ้าง แต่ก็เข้มข้นลึกซึ้ง ข้าเองก็เคยรู้สึกเช่นนั้น\n\nGreat Bear Spirit อยู่คู่กับ Azeroth มานานเท่าที่โลกนี้ดำรงอยู่ในห้วงฟ้า เราพึ่งพาปัญญาและพลังของเขาเพื่อขับเคลื่อนหน้าที่ของเรา บัดนี้ถึงเวลาทดสอบความมุ่งหมายของเจ้าเป็นครั้งแรก ฟังให้ดี..." } } },
    },
    [6001] = { -- Body and Heart
        title = { "14:1828490291:1320258704", "กายและใจ" },
        objective = { "238:156113233:1457854414", "ใช้ Cenarion Moondust ที่ Moonkin Stone ใกล้ Auberdine เพื่อเรียก Lunaclaw เผชิญหน้ากับเขาเพื่อรับความแข็งแกร่งของกายและใจ แล้วกลับไปคุยกับ Mathrengyl Bearwalker ใน Darnassus" },
        description = { "341:1670409841:384278924 N 121:1968591758:1820740855", "ทางตะวันออกของ Auberdine มีถ้ำมูนคินอยู่หลายแห่ง ถ้ำที่ใกล้เมืองที่สุดมี Moonkin Stone อยู่ภายใน Lunaclaw ผู้พิทักษ์ศิลาจะยอมเผชิญหน้ากับเจ้าก็ต่อเมื่อใช้ Cenarion Moondust บนศิลา พลังที่อยู่ในตัวเขาคือสิ่งที่ผู้เดินบนวิถีแห่งกรงเล็บอย่างเจ้าต้องมี\n\nเจ้าคู่ควรกับสิทธิ์ใช้ Cenarion Moondust นี้แล้ว {name} ทีนี้จงพิสูจน์ว่าเจ้าคู่ควรกับความแข็งแกร่งทั้งกายและใจที่ดรูอิดต้องมี!" },
        progress = { "184:351410539:2107625378", "เมื่อเจ้าผ่านบททดสอบตรงหน้าแล้ว เจ้าจะเข้าใจความแข็งแกร่งของกายและใจอย่างสมบูรณ์ ก่อนถึงตอนนั้น ข้าช่วยเจ้าได้เพียงเท่านี้" },
        completion = { "65:1931216444:197230214 N 240:702011879:1140618870", "ในที่สุดเจ้าก็ก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิมแล้ว {name} ข้าสัมผัสได้ถึงคำสอนของ Great Bear Spirit ในตัวเจ้า และรู้ว่าเจ้าได้รับพลังที่ Lunaclaw ครอบครองแล้ว\n\nไม่มีอุปสรรคขวางเจ้าอีก... ข้าจะสอนให้เจ้ารู้ว่าการเป็นดรูอิดแห่งกรงเล็บหมายถึงอะไร!" },
        objectiveLabels = {
            event = { ["Face Lunaclaw and earn the strength of body and heart it possesses."] = "เผชิญหน้ากับ Lunaclaw และรับพลังแห่งกายและใจที่มันมี" },
        },
    },
    [6071] = { -- The Hunter's Path
        title = { "17:1808304966:1557963252", "วิถีแห่งพราน" },
        objective = { "31:696802362:1206943833", "ไปคุยกับ Dazalar ใน Dolanaar" },
        description = { "204:961423173:1296812386", "สวัสดี พรานรุ่นเยาว์ ดูท่าเจ้าจะชำนาญพอควบคุมสัตว์ป่าและฝึกมันให้เป็นสหายได้แล้ว\n\nจงไปหา Dazalar ใน Dolanaar เขาจะชี้ทางให้เจ้าได้มีสัตว์เลี้ยงเป็นของตนเอง" },
        completion = { "17:576516780:98697445 C 1:46:46", "ใช่ ถึงเวลาแล้ว {class}" },
    },
    [6063] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "117:1123849725:305534141", "ใช้ Taming Rod ฝึก Webwood Lurker ให้เชื่อง ลองฝึกใช้ทักษะ แล้วคืนไม้ฝึกให้ Dazalar ใน Dolanaar" },
        description = { "243:1554198338:944831853 N 259:1106871799:666459542", "ในฐานะพราน เจ้าต้องจดจำความรับผิดชอบที่อยู่ในมือ ธรรมชาติไม่ใช่พลังที่เราจะบังคับให้ทำตามใจ แต่เป็นสิ่งที่ต้องเคารพ และยอมรับว่ายิ่งใหญ่กว่าชีวิตของเราเอง\n\n{name} เจ้าต้องพิสูจน์ว่าเข้าใจเรื่องนี้ ก่อนจะได้ความสามารถในการฝึกสัตว์ให้เป็นสหาย\n\nงานแรกคือรับไม้ฝึกสัตว์นี้ไป มันใช้ฝึก Webwood Lurker ให้เชื่องได้ ลองฝึกมัน แล้วใช้โอกาสนี้ฝึกทักษะพรานของเจ้า", variants = { { "5:2046951385:74234560 C 232:2002635041:570081859 N 252:1012084433:1755664804 C 1:46:46", "ในฐานะ{class} เจ้าต้องจดจำความรับผิดชอบที่อยู่ในมือ ธรรมชาติไม่ใช่พลังที่เราจะบังคับให้ทำตามใจ แต่เป็นสิ่งที่ต้องเคารพ และยอมรับว่ายิ่งใหญ่กว่าชีวิตของเราเอง\n\n{name} เจ้าต้องพิสูจน์ว่าเข้าใจเรื่องนี้ ก่อนจะได้ความสามารถในการฝึกสัตว์ให้เป็นสหาย\n\nงานแรกคือรับไม้ฝึกสัตว์นี้ไป มันใช้ฝึก Webwood Lurker ให้เชื่องได้ ลองฝึกมัน แล้วใช้โอกาสนี้ฝึกทักษะ{class}ของเจ้า" } } },
        progress = { "16:2076335929:1428616939 N 41:2008989662:45948847", "เจ้าจะได้เรียนรู้ {name} และวันหนึ่งเจ้าจะเป็นพรานที่ยิ่งใหญ่", variants = { { "16:2076335929:1428616939 N 34:695575318:1494856850 C 1:46:46", "เจ้าจะได้เรียนรู้ {name} และวันหนึ่งเจ้าจะเป็น{class}ที่ยิ่งใหญ่" } } },
        completion = { "11:1614239848:1406166483 N 31:1626512607:147280484", "ยอดเยี่ยม {name}! เจ้าเรียนรู้ได้เร็วทีเดียว" },
        required = { [15921] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame a Webwood Lurker"] = "ฝึก Webwood Lurker ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
    [6101] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "121:780900103:2049208556", "ใช้ Taming Rod ฝึก Nightsaber Stalker ให้เชื่อง ลองฝึกใช้ทักษะ แล้วคืนไม้ฝึกให้ Dazalar ใน Dolanaar" },
        description = { "61:1181307053:1102141796 N 411:2097814467:2112391610", "สิ่งหนึ่งที่แน่นอนในธรรมชาติคือความหลากหลาย {name} เราคาดเดาได้เพียงว่ามันจะไม่หยุดนิ่ง เพราะธรรมชาติเปลี่ยนแปลงอยู่เสมอ\n\nงานที่ข้ามอบหมายจะช่วยให้เจ้าเห็นและชื่นชมความแตกต่างมหาศาลของสิ่งมีชีวิตที่เจ้าอาจเลือกเป็นสหาย\n\nรับไม้ฝึกนี้ไป ใช้ฝึก Nightsaber Stalker ที่อยู่ทางใต้ให้เชื่อง แล้วฝึกทักษะพรานของเจ้า เจ้าจะเริ่มเข้าใจทั้งความเหมือนและความต่างในธรรมชาติ", variants = { { "61:1181307053:1102141796 N 326:1220530253:465790913 C 79:1529627485:801827989", "สิ่งหนึ่งที่แน่นอนในธรรมชาติคือความหลากหลาย {name} เราคาดเดาได้เพียงว่ามันจะไม่หยุดนิ่ง เพราะธรรมชาติเปลี่ยนแปลงอยู่เสมอ\n\nงานที่ข้ามอบหมายจะช่วยให้เจ้าเห็นและชื่นชมความแตกต่างมหาศาลของสิ่งมีชีวิตที่เจ้าอาจเลือกเป็นสหาย\n\nรับไม้ฝึกนี้ไป ใช้ฝึก Nightsaber Stalker ที่อยู่ทางใต้ให้เชื่อง แล้วฝึกทักษะ{class}ของเจ้า เจ้าจะเริ่มเข้าใจทั้งความเหมือนและความต่างในธรรมชาติ" } } },
        progress = { "90:945914188:693624142", "การเข้าใจสมดุลระหว่างธรรมชาติกับตนเองเป็นวิถีชีวิตของไนต์เอลฟ์ทุกคน" },
        completion = { "75:863626835:274295134 N 1:46:46", "ข้าเห็นความตั้งใจของเจ้า และเห็นว่าเจ้าเข้าใจสิ่งที่ข้าสอนแล้ว {name}" },
        required = { [15922] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame a Nightsaber Stalker"] = "ฝึก Nightsaber Stalker ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
    [6102] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "120:210164117:1423272453", "ใช้ Taming Rod ฝึก Strigid Screecher ให้เชื่อง ลองฝึกใช้ทักษะ แล้วคืนไม้ฝึกให้ Dazalar ใน Dolanaar" },
        description = { "489:477803450:700326259", "เจ้าฝึกสัตว์บนพื้นดินมาแล้วสองชนิด ต่อไปต้องฝึกสัตว์ที่โผบินบนฟ้า ใช้ไม้ฝึกกับ Strigid Screecher ทางตะวันตกของที่นี่ แล้วฝึกทักษะโดยมีนกฮูกผู้ทรงพลังอยู่ข้างกาย\n\nเมื่อเจ้ากลับมา ข้าจะมอบทักษะที่ใช้ฝึกสัตว์ที่เจ้าเลือกให้เป็นสหาย มันจะเผชิญบททดสอบและเก็บประสบการณ์ไปพร้อมเจ้า ข้าจะสอนวิธีเรียกมันมาและสั่งให้กลับไปตามต้องการด้วย" },
        progress = { "36:1776805853:526011803 N 45:60183513:1443039235", "ข้าภูมิใจในผลงานของเจ้า {name} งานสุดท้ายที่ข้ามอบหมายเสร็จแล้วหรือยัง?" },
        completion = { "38:257771695:67878287 N 254:405599877:1192871725 N 152:1482074823:1132360063", "เจ้าเรียนรู้ทุกอย่างที่ข้าสอนได้แล้ว {name} ขอแนะนำอีกอย่าง จงเลือกสัตว์เลี้ยงตัวแรกอย่างรอบคอบ จะเลือกสัตว์บก สัตว์น้ำ หรือสัตว์บนฟ้าก็ตาม มันจะอยู่กับเจ้าไปอีกนานแน่นอน\n\nเอาล่ะ {name} ข้าจะมอบพลังในการฝึกสัตว์ให้เชื่อง รวมถึงเรียกมาและสั่งให้กลับไป ใช้ทักษะใหม่อย่างภาคภูมิ เจ้าพิสูจน์แล้วว่าคู่ควร" },
        required = { [15923] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame a Strigid Screecher"] = "ฝึก Strigid Screecher ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
    [6103] = { -- Training the Beast
        title = { "18:955897086:1132620325", "ฝึกฝนสหายร่วมทาง" },
        objective = { "55:627707888:1711746559", "ไปคุยกับ Jocaste ใน Cenarion Enclave ของ Darnassus" },
        description = { "403:346141021:1906146214 N 1:46:46", "เจ้าฝึกสัตว์ให้เชื่องได้แล้ว แต่ยังต้องเรียนรู้ทักษะในการฝึกสอนมันด้วย\n\nเดินทางไป Darnassus แล้วคุยกับ Jocaste หนึ่งในพรานที่พวกเราเคารพที่สุด นางจะมอบความสามารถในการฝึกสัตว์เลี้ยงตัวใหม่ รีบไปเถอะ\n\nแม้ Jocaste จะดูเคร่งขรึม แต่นางยินดีเสมอเมื่อเห็นพรานคนใหม่เติบโต จงเคารพนาง แล้วนางจะให้เกียรติเจ้าเช่นกัน ขอให้โชคดี {name}", variants = { { "307:710530293:427788894 C 90:625669080:950853307 N 1:46:46", "เจ้าฝึกสัตว์ให้เชื่องได้แล้ว แต่ยังต้องเรียนรู้ทักษะในการฝึกสอนมันด้วย\n\nเดินทางไป Darnassus แล้วคุยกับ Jocaste หนึ่งในพรานที่พวกเราเคารพที่สุด นางจะมอบความสามารถในการฝึกสัตว์เลี้ยงตัวใหม่ รีบไปเถอะ\n\nแม้ Jocaste จะดูเคร่งขรึม แต่นางยินดีเสมอเมื่อเห็น{class}คนใหม่เติบโต จงเคารพนาง แล้วนางจะให้เกียรติเจ้าเช่นกัน ขอให้โชคดี {name}" } } },
        completion = { "259:789613040:235798816 N 120:2034568094:1971249264", "พรานมือใหม่สินะ ใช่ ข้าสอนทักษะที่จำเป็นต่อการฝึกและชี้นำสัตว์เลี้ยงให้ได้ เจ้าจะสอนความสามารถใหม่ให้มันได้ รวมถึงให้อาหารและชุบชีวิตมันหากล้มลงในการต่อสู้\n\nจำไว้ {name} จงเคารพสมดุลและชื่นชมความยิ่งใหญ่ของธรรมชาติรอบตัวเสมอ ออกเดินทางเถิด แล้วเราจะได้คุยกันอีกในภายหน้า", variants = { { "12:1592496637:1532794898 C 241:2061887495:1867178833 N 120:2034568094:1971249264", "{class}มือใหม่สินะ ใช่ ข้าสอนทักษะที่จำเป็นต่อการฝึกและชี้นำสัตว์เลี้ยงให้ได้ เจ้าจะสอนความสามารถใหม่ให้มันได้ รวมถึงให้อาหารและชุบชีวิตมันหากล้มลงในการต่อสู้\n\nจำไว้ {name} จงเคารพสมดุลและชื่นชมความยิ่งใหญ่ของธรรมชาติรอบตัวเสมอ ออกเดินทางเถิด แล้วเราจะได้คุยกันอีกในภายหน้า" }, { "12:1592496637:1532794898 C 241:1427401568:704347301 N 120:2034568094:1971249264", "{class}มือใหม่สินะ ใช่ ข้าสอนทักษะที่จำเป็นต่อการฝึกและชี้นำสัตว์เลี้ยงให้ได้ เจ้าจะสอนความสามารถใหม่ให้มันได้ รวมถึงให้อาหารและชุบชีวิตมันหากล้มลงในการต่อสู้\n\nจำไว้ {name} จงเคารพสมดุลและชื่นชมความยิ่งใหญ่ของธรรมชาติรอบตัวเสมอ ออกเดินทางเถิด แล้วเราจะได้คุยกันอีกในภายหน้า" } } },
    },
    [7383] = { -- Crown of the Earth
        title = { "18:1054641003:2021293941", "มงกุฎแห่งพิภพ" },
        objective = { "76:711720315:1258512144", "เติมน้ำลงใน Amethyst Phial แล้วนำกลับไปให้ Corithras Moonrage ใน Dolanaar" },
        description = { "476:1613966783:2105557718", "แต่ Teldrassil ก็ไม่ได้สมบูรณ์พร้อมทุกด้าน แผนที่ Staghelm วางไว้อย่างรอบคอบสำหรับต้นไม้โลกต้นใหม่สำเร็จดังใจหวัง ทว่ายังมีปัญหาเล็ก ๆ อยู่เรื่องหนึ่ง ซึ่งอาจเป็นต้นเหตุของปัญหามากมายบน Teldrassil\n\nข้ายังไม่เล่าเรื่องนั้นตอนนี้ เจ้าต้องไปบ่อจันทร์แห่งสุดท้ายที่ Oracle Glade ทางตะวันตกเฉียงเหนือ ใต้กิ่งก้านของ Oracle Tree คือบ่อแห่งแรกและทรงพลังที่สุดของเรา ตักน้ำใส่ขวดแล้วกลับมาหาข้า" },
        progress = { "188:2025468378:583122702", "Oracle Tree และอัครดรูอิดเฝ้าติดตามการเติบโตของ Teldrassil อย่างใกล้ชิดร่วมกับเหล่าดรูอิด แต่ถึงจะมีบ้านใหม่แล้ว ชีวิตอมตะของเราก็ยังไม่กลับคืนมา" },
        completion = { "496:95654127:1429069621", "การได้อยู่ต่อหน้า Oracle Tree... แทบเหมือนเห็นปัญญาอันล้ำลึกมีรูปร่างขึ้นมา ข้าจะเล่าต่อแล้วนะ...\n\nเมื่อ Teldrassil เติบโตขึ้น อัครดรูอิดก็ไปขอพรจากเหล่ามังกร เช่นที่พวกเขาเคยมอบให้ Nordrassil ในอดีต แต่ Nozdormu เจ้าแห่งกาลเวลา ปฏิเสธและตำหนิความทะนงตนของดรูอิด Alexstrasza เห็นพ้องกับ Nozdormu และปฏิเสธ Staghelm เช่นกัน เมื่อปราศจากพรของนาง Teldrassil จึงเติบโตอย่างบกพร่องและคาดเดาไม่ได้..." },
        required = { [18151] = { "21:1923428760:1562869005", "ขวดแอเมทิสต์ที่เติมแล้ว" } },
        steps = { { "21:1923428760:1562869005", "ขวดแอเมทิสต์ที่เติมแล้ว" } },
    },
    [5925] = { -- Heeding the Call
        title = { "16:1185260992:259476408", "ขานรับเสียงเรียก" },
        objective = { "68:1126811676:987074176", "ไปคุยกับ Mathrengyl Bearwalker ใน Cenarion Enclave ของ Darnassus" },
        description = { "472:1060943100:897948186", "ขอเวลาสักครู่ สหาย...\n\nข้าได้ข่าวว่า Mathrengyl Bearwalker ฝากคำมาว่าอยากพบเจ้า ดูเหมือนการฝึกดรูอิดของเจ้ากำลังจะก้าวสู่ขั้นใหม่ และเขาจะฝึกให้ด้วยตัวเอง Mathrengyl เป็นผู้ช่วยใกล้ชิดของอัครดรูอิด และเป็นหนึ่งในดรูอิดที่รอบรู้และน่าเคารพที่สุดใน Teldrassil\n\nเขาอยู่ใน Cenarion Enclave ของ Darnassus บนชั้นสองของต้นไม้ที่ Fandral Staghelm พำนัก" },
        completion = { "469:1731892601:1710263841", "ดีใจที่เจ้ามาถึงที่นี่ในวันนี้ ดรูอิดรุ่นเยาว์ ถึงเวลาที่เจ้าจะก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิม\n\nในตัวลูกหลานของ Cenarius ทุกคนมีเสียงเรียกให้รับใช้ธรรมชาติ สัตว์และพืชเป็นทั้งสหายและผู้ที่เราเฝ้าดูแล เราเลือกอุทิศชีวิตเพื่อรักษาสมดุล ทั้งเพื่อพวกเขาและตัวเราเอง ก้าวแรกของเจ้าคือเรียนรู้วิถีแห่งหมี และเข้าใจความแข็งแกร่งของกายและใจ\n\nเตรียมตัวให้พร้อม!", variants = { { "47:608153914:1342807793 C 418:1421579562:2003121929", "ดีใจที่เจ้ามาถึงที่นี่ในวันนี้ {class}รุ่นเยาว์ ถึงเวลาที่เจ้าจะก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิม\n\nในตัวลูกหลานของ Cenarius ทุกคนมีเสียงเรียกให้รับใช้ธรรมชาติ สัตว์และพืชเป็นทั้งสหายและผู้ที่เราเฝ้าดูแล เราเลือกอุทิศชีวิตเพื่อรักษาสมดุล ทั้งเพื่อพวกเขาและตัวเราเอง ก้าวแรกของเจ้าคือเรียนรู้วิถีแห่งหมี และเข้าใจความแข็งแกร่งของกายและใจ\n\nเตรียมตัวให้พร้อม!" } } },
    },
    [6072] = { -- The Hunter's Path
        title = { "17:1808304966:1557963252", "วิถีแห่งพราน" },
        objective = { "31:696802362:1206943833", "ไปคุยกับ Dazalar ใน Dolanaar" },
        description = { "204:961423173:1296812386", "สวัสดี พรานรุ่นเยาว์ ดูท่าเจ้าจะชำนาญพอควบคุมสัตว์ป่าและฝึกมันให้เป็นสหายได้แล้ว\n\nจงไปหา Dazalar ใน Dolanaar เขาจะชี้ทางให้เจ้าได้มีสัตว์เลี้ยงเป็นของตนเอง" },
        completion = { "33:1216396795:2140748615", "ใช่ ข้าเชื่อว่าถึงเวลาแล้ว...", variants = { { "17:576516780:98697445 C 1:46:46", "ใช่ ถึงเวลาแล้ว {class}" } } },
    },
    [26] = { -- A Lesson to Learn
        title = { "17:2145250651:262314469", "บทเรียนที่ต้องเรียนรู้" },
        objective = { "70:1014218030:2080449173", "ไปคุยกับ Dendrite Starblaze ในหมู่บ้าน Nighthaven ที่ Moonglade" },
        description = { "N 491:1024582916:1445548440", "{name} ข้าติดตามความก้าวหน้าของเจ้าด้วยความยินดี เจ้ากำลังเติบโตเป็นผู้พิทักษ์ธรรมชาติที่มีคุณค่าอย่างแท้จริง\n\nถึงเวลาเรียนรู้ร่างสัตว์อีกแบบหนึ่งที่ Cenarius มอบพรให้เราแปลงกายได้ ร่างที่จะทำให้เจ้าควบคุมและเคลื่อนไหวในน้ำอย่างชำนาญ จงไปหมู่บ้าน Nighthaven ใน Moonglade แล้วคุยกับ Dendrite Starblaze แห่ง Cenarion Circle เขาจะชี้แนะเจ้าต่อ" },
        completion = { "496:1865085394:2074887941", "สวัสดี ดรูอิดรุ่นเยาว์ ถึงเวลาเรียนรู้ร่างสัตว์น้ำแล้ว ร่างนี้ทำให้เจ้าเคลื่อนที่ในน้ำได้อย่างอิสระโดยไม่จำกัดเวลา เป็นทั้งเครื่องมือที่มีประโยชน์และพรอันวิเศษ... แต่เจ้าต้องพิสูจน์ตนก่อนจะเชี่ยวชาญมัน\n\nเจ้าต้องผ่านบททดสอบสองอย่าง อย่างแรกทดสอบความสามารถในการทำงานใต้น้ำขณะถูกกดดัน อย่างที่สองทดสอบความมุ่งมั่นที่จะเข้าใจธรรมชาติของร่างนี้\n\nเตรียมตัวให้พร้อม เวลาแห่งบททดสอบมาถึงแล้ว" },
    },
    [29] = { -- Trial of the Lake
        title = { "17:1444350445:1544338901", "บททดสอบแห่งทะเลสาบ" },
        objective = { "223:1301896594:973178641", "หา Shrine Bauble ใน Lake Elune'ara แล้วนำไปใช้ในเขต Shrine of Remulos ทางตะวันตกเฉียงเหนือของ Moonglade จากนั้นคุยกับ Tajarri ที่ศาลเพื่อจบบททดสอบ" },
        description = { "485:2053445073:1802427861 N 1:46:46", "บททดสอบแรกคือค้นหา Shrine Bauble ใต้ Lake Elune'ara มันเสื่อมสภาพอย่างรวดเร็ว เมื่อได้มาแล้วจงรีบไป Shrine of Remulos ใช้มันที่ศาล แล้วคุยกับ Tajarri นางเป็นหนึ่งในผู้ดูแลที่ Moonglade ไว้วางใจที่สุด\n\nเจ้ามีเวลาทำงานนี้จำกัด และอาจมีดรูอิดคนอื่นค้นหาเครื่องประดับเช่นกัน ความคล่องแคล่วทั้งกายและใจจะเป็นสิ่งตัดสินความสำเร็จ\n\nขอให้โชคดี {name}" },
        progress = { "180:750634163:590115540", "เพื่อผ่านบททดสอบแห่งทะเลสาบ เจ้าต้องใช้ Shrine Bauble ภายในเขตศาลแห่งนี้ หากยังไม่ทำ บททดสอบก็ยังไม่จบ และเจ้าอาจล้มเหลวได้" },
        completion = { "491:1341538486:2107190367", "ดูเหมือนดรูอิดอีกคนจะผ่านบททดสอบแห่งทะเลสาบแล้ว! ทำได้ดี สหายรุ่นเยาว์ ทำได้ดีมาก\n\nอย่างที่บอก ข้าชื่อ Tajarri การเป็นผู้ดูแล Moonglade และโดยเฉพาะศาลนี้เป็นทั้งหน้าที่และเกียรติของข้า Keeper Remulos นำ Cenarion Circle ในการอนุรักษ์ธรรมชาติและสมดุล ศาลของเขาจึงเป็นอนุสรณ์ถาวรของหน้าที่นั้น การใช้เครื่องประดับที่นี่เป็นการแสดงความเคารพต่อความสำคัญของสถานที่แห่งนี้ในหมู่สมาชิก" },
        objectiveLabels = {
            event = { ["Complete the Trial of the Lake."] = "ผ่านบททดสอบแห่งทะเลสาบ" },
        },
    },
    [272] = { -- Trial of the Sea Lion
        title = { "21:2016805535:1729864991", "บททดสอบแห่งสิงโตทะเล" },
        objective = { "391:1574831598:1854252636", "ค้นหา Half Pendant of Aquatic Agility และ Half Pendant of Aquatic Endurance โดยถามเบาะแสจากชาว Moonglade นำสองชิ้นมารวมเป็น Pendant of the Sea Lion ใกล้ Shrine of Remulos แล้วนำไปให้ Dendrite Starblaze ใน Nighthaven" },
        description = { "498:1866390467:144435855", "บททดสอบที่สองต้องใช้ชิ้นส่วนสองซีกของ Pendant of the Sea Lion ซีกหนึ่งดึงพลังจากความคล่องแคล่วของสิงโตทะเลที่แหวกว่ายผ่านน้ำ อีกซีกดึงพลังจากความทรหดอันน่าทึ่งของมัน ดรูอิดต้องใช้คุณสมบัติทั้งสองอย่างเท่าเทียมกันจึงจะเข้าถึงธรรมชาติของร่างสัตว์น้ำ\n\nถามคนใน Moonglade ว่าชิ้นส่วนอาจอยู่ที่ใด แล้วนำทั้งคู่กลับมาประกอบที่นี่ เมื่อได้จี้สมบูรณ์แล้ว นำไปให้ Dendrite Starblaze" },
        progress = { "48:1074811042:311868420 N 199:523394531:1685234929", "ประกอบจี้ให้ข้าตรวจแล้วหรือยัง {name}? ถ้ายังหาชิ้นส่วนไม่พบ ลองถามผู้คนในพื้นที่ดู นอกจากจะได้สิ่งที่ค้นหาแล้ว ยังเป็นโอกาสให้เจ้าสำรวจพงไพรศักดิ์สิทธิ์อันงดงามแห่งนี้ด้วย" },
        completion = { "44:443600241:1178139232 N 375:1914877955:369932871", "เจ้าผ่านบททดสอบแห่งสิงโตทะเลแล้ว {name} ยินดีด้วย\n\nทุกขั้นในการหาจี้พิสูจน์ว่าความคล่องแคล่วและความทรหดต้องทำงานประสานกัน เพื่อให้เจ้าทำสิ่งที่ต้องการใต้น้ำได้ ทั้งสองอย่างขาดกันไม่ได้ และจะเกิดขึ้นไม่ได้หากเจ้าไม่ยอมรับธรรมชาติแห่งสิงโตทะเล\n\nจดจำบทเรียนเหล่านี้ให้ดี และใช้มันเมื่อเจ้าเรียนรู้ร่างสัตว์น้ำแล้ว" },
        required = { [15885] = { "23:441182989:1318666459", "จี้สิงโตทะเล" } },
        steps = { { "23:441182989:1318666459", "จี้สิงโตทะเล" } },
    },
    [5061] = { -- Aquatic Form
        title = { "12:74357176:1719203049", "ร่างสัตว์น้ำ" },
        objective = { "79:86329738:307007170", "กลับ Darnassus แล้วนำ Pendant of the Sea Lion ไปให้ Mathrengyl Bearwalker ดู" },
        description = { "382:187294312:1541535814", "เจ้าเรียนรู้บทเรียนที่ดรูอิดรุ่นเยาว์ต้องผ่านก่อนรับร่างสัตว์น้ำครบแล้ว จงกลับไปหา Mathrengyl Bearwalker ครูฝึกของเจ้าที่ Darnassus แสดงจี้ให้เขาดูเพื่อพิสูจน์ว่าเจ้าพร้อมเรียนรู้ เขาจะฝึกขั้นสุดท้ายให้เจ้ากลมกลืนเป็นหนึ่งเดียวกับสายน้ำ\n\nลาก่อน ดรูอิดรุ่นเยาว์ แล้วเราจะได้คุยกันอีก" },
        progress = { "196:727527832:1651714340", "ข่าวการกลับถึง Darnassus ของเจ้ามาถึงข้าแล้ว แต่ก่อนสอนร่างสัตว์น้ำ ข้าต้องเห็นหลักฐานว่าเจ้าเรียนรู้บทเรียนจาก Moonglade แล้ว\n\nเจ้ามี Pendant of the Sea Lion หรือไม่?" },
        completion = { "17:526312553:701486649 N 285:1289982822:474358223", "น่าประทับใจมาก {name} เจ้าพร้อมเรียนรู้ร่างสัตว์น้ำแล้ว และข้ายินดีที่จะสอนให้\n\nเพื่อเป็นเกียรติแก่ความสำเร็จในบททดสอบทั้งสอง ข้าขอมอบสิ่งนี้ให้ หวังว่ามันจะเป็นอุปกรณ์ที่มีประโยชน์ในหน้าที่ผู้พิทักษ์ธรรมชาติและผู้รักษาสมดุลของเจ้า" },
        required = { [15885] = { "23:441182989:1318666459", "จี้สิงโตทะเล" } },
        steps = { { "23:441182989:1318666459", "จี้สิงโตทะเล" } },
    },
    [6121] = { -- Lessons Anew
        title = { "12:2081127499:337025447", "บทเรียนครั้งใหม่" },
        objective = { "83:1408267309:387693120", "เดินทางไป Moonglade แล้วคุยกับ Dendrite Starblaze ในหมู่บ้าน Nighthaven" },
        description = { "80:1595874918:696828619 N 355:899515196:481742391", "เจ้าพร้อมเรียนรู้เรื่องพิษและพลังที่ดรูอิดอย่างเราใช้จัดการมันแล้ว {name} Cenarius มอบพรให้เราชำระแม้แต่พิษร้ายที่สุดได้ด้วยคาถาเพียงบทเดียว พรนี้มีคุณค่าอย่างยิ่ง... เพื่อให้เจ้าเข้าใจบทเรียนนี้ เจ้าจะต้องแก้ปัญหาพิษด้วยวิธีของคนทั่วไป\n\nเดินทางไป Moonglade แล้วคุยกับ Dendrite Starblaze เขารอเจ้าไปเริ่มบทเรียนอยู่" },
        completion = { "489:682269287:2041051973", "สวัสดี ดรูอิดรุ่นเยาว์ ดีใจที่เห็นเจ้าพร้อมและกระตือรือร้นจะเรียนรู้การถอนพิษ\n\nในอดีต ดรูอิดส่วนใหญ่ผ่านบททดสอบที่จัดเตรียมไว้ แต่ครั้งนี้ต่างออกไป มีสัตว์จำนวนมากต้องพิษใน Auberdine และชาวบ้านรักษามันไม่ได้ ตัวแทนที่นั่นจึงขอความช่วยเหลือจาก Moonglade เราจะส่งเจ้าไปช่วย งานที่เจ้าจะทำเป็นเรื่องจริง จงจำข้อนี้ไว้" },
    },
    [6122] = { -- The Principal Source
        title = { "20:1595680167:1593344382", "แหล่งต้นตอ" },
        objective = { "201:1570829297:1908982222", "ใช้ Empty Cliffspring Falls Sampler เก็บน้ำที่ปากถ้ำใกล้น้ำตก แล้วนำ Filled Cliffspring Falls Sampler ไปให้ Alanndarian Nightsong ใน Auberdine ที่ Darkshore" },
        description = { "493:200425467:816625203", "Cliffspring Falls ใน Darkshore เป็นแหล่งน้ำดื่มหลักของภูมิภาค ตอนนี้ข้าสงสัยว่ามันอาจเป็นแหล่งพิษสำคัญที่ทำร้ายสัตว์ในพื้นที่ โดยเฉพาะกวาง ใช้ภาชนะนี้เก็บน้ำตรงปากถ้ำ ระวังตัวด้วย มีนากาอันตรายอาศัยอยู่ในถ้ำข้างน้ำตก\n\nเมื่อได้ตัวอย่างแล้ว นำไปให้ Alanndarian Nightsong ใน Auberdine นางเป็นผู้ขอความช่วยเหลือ และเจ้าจะร่วมมือกับนางแก้ปัญหานี้" },
        progress = { "331:1387296042:162363744", "เจ้าคือคนที่ Cenarion Circle จาก Moonglade ส่งมาหรือ? ดีเหลือเกิน! ตอนนี้เรามีวิกฤตเรื่องกวางที่น่าสงสาร ยินดีรับความช่วยเหลือทุกอย่าง\n\nนำตัวอย่างน้ำที่ Dendrite Starblaze บอกไว้มาแล้วหรือยัง? เขาแจ้งว่าเจ้าจะเก็บมาให้เราหาทางรักษาด้วยกัน..." },
        completion = { "473:15863987:1250540953", "Elune เอ๋ย น้ำนี้น่าขยะแขยงนัก! ไม่แปลกเลยที่พวกกวางจะป่วย\n\nมีบางอย่างกำลังทำให้น้ำสกปรก และแพร่ไปถึงน้ำใต้ดินทั่ว Darkshore มีคนพบกวางป่วยทั่วทั้งพื้นที่ แม้อยู่ไกลจากแม่น้ำ น้ำนี้น่าจะเป็นต้นเหตุสำคัญของการแพร่โรค แต่ต้องมีอย่างอื่นเกี่ยวข้องด้วย\n\nเชื่อหรือไม่ น้ำนี้จะช่วยให้เราคิดสูตรยารักษาได้ ระหว่างที่ข้าศึกษาน้ำ ข้าต้องการของบางอย่างมาปรุงยา..." },
        required = { [15845] = { "32:19088166:1530035070", "ขวดตัวอย่าง Cliffspring Falls ที่เติมแล้ว" } },
        steps = { { "32:19088166:1530035070", "ขวดตัวอย่าง Cliffspring Falls ที่เติมแล้ว" } },
    },
    [6123] = { -- Gathering the Cure
        title = { "18:1683094505:839188768", "รวบรวมยารักษา" },
        objective = { "111:447578605:430868861", "นำ Earthroot 5 ชิ้น และ Lunar Fungus 12 ชิ้นไปให้ Alanndarian Nightsong ใน Auberdine เพื่อปรุงยาทารักษา" },
        description = { "472:1223472029:1671312760", "น้ำตัวอย่างจะเป็นส่วนประกอบพื้นฐานของยาทาที่ข้าจะทำให้กวาง ส่วนตัวยารักษาต้องใช้ Earthroot คนเก็บสมุนไพรรู้วิธีหามัน ถ้าเจ้าไม่ได้เป็นคนเก็บสมุนไพร เราคงต้องหาผู้เชี่ยวชาญมาช่วย\n\nสุดท้าย ข้าต้องใช้ Lunar Fungus เพื่อเพิ่มฤทธิ์ยา หาตุ่มเห็ดชนิดนี้ได้ไม่ยาก มีอยู่ตามถ้ำทางตะวันออกของที่นี่ แต่ในถ้ำมีมูนคินอาศัยอยู่ และระยะหลังพวกมันหงุดหงิดง่าย ระวังด้วย" },
        progress = { "137:892106634:183972628", "ได้ส่วนผสมสำหรับทำยาทามาแล้วหรือยัง? พวกกวางไม่หายดีเองแน่ เราควรรีบช่วยมัน!" },
        completion = { "14:328000485:1627340455 N 416:901836333:200334908", "ดีมาก {name} ปริมาณนี้น่าจะทำยาทาได้มากพอ อย่างน้อยก็พอเริ่มช่วยให้สถานการณ์ดีขึ้น\n\nการทำยาถอนพิษบางครั้งยากมาก เพราะพิษแต่ละชนิดมักต้องใช้ยาเฉพาะเพื่อต้านฤทธิ์ ลองคิดดูสิ หากรักษาพิษได้ทันทีโดยไม่ต้องกังวลว่าต้องใช้ส่วนผสมใดบ้างจะดีเพียงใด!\n\nเอาล่ะ ให้ข้าลงมือปรุงยาก่อน!" },
        required = { [2449] = { "9:595112996:364502022", "เอิร์ธรูต" }, [15851] = { "12:92226747:1633808520", "เห็ดจันทรา" } },
        steps = { { "9:595112996:364502022", "เอิร์ธรูต" }, { "12:92226747:1633808520", "เห็ดจันทรา" } },
    },
    [6124] = { -- Curing the Sick
        title = { "15:1730609246:1907616096", "รักษาผู้เจ็บป่วย" },
        objective = { "296:1593161210:414371868", "ใช้ Curative Animal Salve รักษา Sickly Deer 10 ตัวใน Darkshore พบได้ตั้งแต่ใต้ Cliffspring River ทางเหนือของ Auberdine ไปจนถึง Darkshore ตอนใต้ติดชายแดน Ashenvale" },
        description = { "90:398912448:220818122 N 409:1380864399:1803182571", "ส่วนผสมที่เจ้าหามาทำยาทาได้สิบครั้ง {name} ระหว่างที่ข้าร่วมมือกับชาวบ้านทำยาเพิ่ม อยากให้เจ้าเริ่มช่วยพวกเราไปก่อน มีกวางป่วยทั่ว Darkshore ใช้ยาทารักษาพวกมันที\n\nข้าแน่ใจว่าเมื่อเสร็จแล้ว Dendrite Starblaze ที่ Moonglade คงอยากคุยกับเจ้า ฝากคำขอบคุณจาก Auberdine ไปถึง Cenarion Circle ด้วย... และข้าขอขอบคุณเจ้าด้วยตัวเองสำหรับความช่วยเหลือครั้งนี้!" },
        progress = { "119:25130117:1114958813", "ทำงานที่ Alanndarian Nightsong แห่ง Auberdine ขอไว้เสร็จแล้วหรือ? ภารกิจของเจ้าจะสำเร็จได้ก็ต่อเมื่อทำสิ่งนั้นครบ" },
        completion = { "371:1552267326:1206360329 N 108:1380251100:861098772", "เจ้าดูแลกวางป่วยใน Darkshore ได้ดี พวกมันเป็นเหยื่อที่ไม่รู้อิโหน่อิเหน่ของความแปดเปื้อนอันใหญ่หลวงที่กำลังลามทั่วดินแดน ใน Darnassus มีทั้งคนที่ยอมรับว่าภัยนี้มีอยู่ และคนที่เมินสัญญาณที่เพิ่มขึ้น ข้าหวังว่าเจ้าจะไม่ปิดตาต่อข้อเท็จจริงตรงหน้า {name}\n\nอย่างไรก็ดี เจ้าพิสูจน์แล้วว่าเป็นมิตรที่มีค่าต่อธรรมชาติและ Cenarion Circle รับสิ่งนี้ไว้เป็นสัญลักษณ์เถิด" },
        steps = { { "17:1768732005:956240478", "รักษากวางที่ป่วย" } },
    },
    [6125] = { -- Power over Poison
        title = { "17:648035898:1845468169", "พลังเหนือพิษ" },
        objective = { "67:1667132282:1022175993", "กลับไปหา Mathrengyl Bearwalker ใน Cenarion Enclave ของ Darnassus" },
        description = { { "263:1699146139:575273023 N 161:391239422:541857185", "263:1699146139:575273023 N 160:1875963853:1095075407" }, "เจ้าได้เรียนรู้แล้วว่าการรักษาพิษโดยปราศจากพลังช่วยเหลือทางจิตวิญญาณเป็นอย่างไร เมื่อกำลังจะได้รับพลังใหม่ในการขจัดพิษ จงจดจำว่าผู้อื่นต้องอดทนเพียงใดในการต่อสู้กับมัน\n\nตอนนี้เจ้าควรกลับไปหา Mathrengyl Bearwalker ที่ Darnassus {name} เมื่อนักเรียนเข้าใจบทเรียนแล้ว เขาย่อมมีคาถาสำคัญจะสอนเจ้า\n\nลาก่อน ดรูอิดรุ่นเยาว์ แล้วเราจะคุยกันอีก", variants = { { "263:1699146139:575273023 N 160:426901304:254993420", "เจ้าได้เรียนรู้แล้วว่าการรักษาพิษโดยปราศจากพลังช่วยเหลือทางจิตวิญญาณเป็นอย่างไร เมื่อกำลังจะได้รับพลังใหม่ในการขจัดพิษ จงจดจำว่าผู้อื่นต้องอดทนเพียงใดในการต่อสู้กับมัน\n\nตอนนี้เจ้าควรกลับไปหา Mathrengyl Bearwalker ที่ Darnassus {name} เมื่อนักเรียนเข้าใจบทเรียนแล้ว เขาย่อมมีคาถาสำคัญจะสอนเจ้า\n\nลาก่อน ดรูอิดรุ่นเยาว์ แล้วเราจะคุยกันอีก" } } },
        completion = { "439:1898978152:453432734 N 16:413138634:1625678374", "ยินดีต้อนรับกลับ ข้าติดตามบทเรียนของเจ้าตั้งแต่ออกเดินทาง ยอมรับว่าประหลาดใจเมื่อทราบสถานการณ์ใน Auberdine เรื่องนี้ต้องตรวจสอบต่อ เพราะการที่พิษเช่นนี้เข้าสู่สิ่งแวดล้อมย่อมกระทบสมดุลอย่างร้ายแรง\n\nเจ้ารับมือกับความกดดันได้อย่างสง่างาม ข้าจึงนึกไม่ออกว่าจะให้รางวัลใดเหมาะไปกว่าพลังขจัดพิษที่จะอยู่กับเจ้าตลอดไป ใช้มันให้ดี {name}... ใช้ให้ดี" },
    },
    [6344] = { -- Nessa Shadowsong
        title = { "16:1638325795:351975026", "เนสซา แชโดว์ซอง" },
        objective = { "28:1157818918:491585488", "ไปคุยกับ Nessa Shadowsong" },
        description = { "315:1951230044:1915553651", "Nessa Shadowsong เพื่อนของข้าเป็นพ่อค้าขายอุปกรณ์ตกปลาใน Rut'theran Village นางต้องส่งห่อของไป Darkshore และกำลังหาคนช่วยอยู่\n\nถ้าสนใจ จงใช้ประตูมิติใน Darnassus ไป Rut'theran Village ประตูนั้นอยู่ทางตะวันตกของ Temple Gardens" },
        completion = { "85:1158832710:220993854", "ใช่ ข้าต้องการคนส่งห่อของไป Darkshore เจ้าจะช่วยข้าไหม?" },
    },
    [6341] = { -- The Bounty of Teldrassil
        title = { "24:518854333:718820541", "ความอุดมสมบูรณ์แห่งเทลดรัสซิล" },
        objective = { "39:2078041176:601816550", "นำ Nessa's Collection ไปให้ Vesprystus" },
        description = { "447:577286479:1468932761", "ชาวประมงของ Rut'theran Village จับปลาได้ดีมาก เพราะปลาที่นี่ตัวใหญ่และชุกชุม ข้าอยากเปรียบเทียบความอุดมสมบูรณ์ที่นี่กับฝั่งแผ่นดินใหญ่\n\nข้ามีตัวอย่างกระดูกและเกล็ดปลาที่อยากส่งไปให้เพื่อนร่วมงานใน Darkshore เขาชื่อ Laird เป็นพ่อค้าปลาในหมู่บ้าน Auberdine\n\nนำตัวอย่างไปให้ Vesprystus ผู้ดูแลฮิปโปกริฟฟ์ของเรา แล้วคุยกับเขาเรื่องเดินทางไป Auberdine" },
        progress = { "49:766772366:595969567", "มีอะไรให้ข้าช่วยหรือ? ต้องการเดินทางใช่ไหม?" },
        completion = { "51:182243992:112124019", "อา อยากส่งสิ่งนี้ไป Auberdine หรือ? ได้สิ..." },
        required = { [16262] = { "18:33165607:2033856066", "ของที่ Nessa รวบรวมไว้" } },
        steps = { { "18:33165607:2033856066", "ของที่ Nessa รวบรวมไว้" } },
    },
    [6342] = { -- Flight to Auberdine
        title = { "19:1913715774:1486153021", "บินสู่ออเบอร์ดีน" },
        objective = { "109:1057046399:1614653014", "ขึ้นฮิปโปกริฟฟ์จากผู้ดูแล Vesprystus ไป Auberdine แล้วนำ Nessa's Collection ไปให้ Laird" },
        description = { "482:1197513696:352929077", "จาก Rut'theran ไป Auberdine ได้สองทาง คือเรือโดยสารกับฮิปโปกริฟฟ์ ทั้งสองอย่างรวดเร็วและเชื่อถือได้ แต่หากยังไม่เคยบินไป Auberdine ด้วยฮิปโปกริฟฟ์ ข้าแนะนำให้ลอง\n\nควรคุยกับผู้ดูแลฮิปโปกริฟฟ์ในทุกเมืองที่มี เมื่อคุยแล้ว เจ้าจึงจะบินมาที่นั่นจากเมืองอื่นได้\n\nนี่ตัวอย่างของ Nessa คุยกับข้าอีกครั้งเมื่อพร้อมบินไป Auberdine แล้วนำของไปให้ Laird" },
        progress = { "65:1968636154:234286339", "มาจาก Teldrassil หรือ? เล่าให้ฟังหน่อย การจับปลาที่นั่นเป็นอย่างไร?" },
        completion = { "33:628227434:2091873562 N 276:1634832176:2062438498", "ห่อของจาก Nessa หรือ? ขอบใจ {name}! นางบอกว่าจะส่งตัวอย่างปลาที่จับได้ใกล้ Rut'theran Village มาให้ นางคิดว่ามันอาจต่างจากปลาที่นี่มาก...\n\nโอ้โห! กระดูกขากรรไกรนี้ใหญ่เกือบสองเท่าของปลาชนิดเดียวกันที่พบแถวนี้ แล้วเกล็ดก็ใหญ่เท่ากำปั้น! น่าทึ่งจริง ๆ!" },
        required = { [16262] = { "18:33165607:2033856066", "ของที่ Nessa รวบรวมไว้" } },
        steps = { { "18:33165607:2033856066", "ของที่ Nessa รวบรวมไว้" } },
    },
    [6343] = { -- Return to Nessa
        title = { "15:861961235:140101394", "กลับไปหาเนสซา" },
        objective = { "43:571553170:1288128976", "นำ Laird's Response ไปให้ Nessa Shadowsong" },
        description = { "493:637412369:1329744328", "ข้าต้องส่งคำตอบให้ Nessa นางคงสนใจว่าปลาที่นี่ต่างจากปลาตามชายฝั่ง Teldrassil เพียงใด เราทำได้แค่คาดเดาสาเหตุ แต่ข้าสงสัยว่าต้นไม้โลกกำลังส่งอิทธิพลต่อสิ่งมีชีวิตรอบตัวมัน!\n\nนำคำตอบนี้ไปให้ Nessa ที หากอยากขึ้นฮิปโปกริฟฟ์กลับ Rut'theran ให้คุยกับ Caylais Moonfeather ผู้ดูแลฮิปโปกริฟฟ์ ถ้าจะขึ้นเรือโดยสาร เรือออกจากท่าเรือทางตะวันตกเฉียงเหนือเป็นประจำ" },
        progress = { "N 55:262708283:1966908153", "{name} กลับจาก Auberdine แล้วหรือ? ได้คุยกับ Laird ไหม?" },
        completion = { "192:2113230169:1451368497 N 157:1962149426:838885471", "น่าสนใจมาก ปลาที่นี่ตัวใหญ่จริง แต่ข้าไม่คิดว่าความอุดมสมบูรณ์จะแตกต่างจากแผ่นดินใหญ่ถึงขนาดนี้ ต้องมีสาเหตุแน่...\n\nขอบใจ {name} ข้าจะเล่าข่าวที่เจ้านำมาให้ชาวบ้านฟัง บางทีสักวันเราอาจพบต้นตอของเรื่องประหลาดนี้ ระหว่างนั้นก็รับประโยชน์จากมันไปก่อน!" },
        required = { [16263] = { "16:65260837:1319469411", "คำตอบของ Laird" } },
        steps = { { "16:65260837:1319469411", "คำตอบของ Laird" } },
    },
    [953] = { -- The Fall of Ameth'Aran
        title = { "22:1052360220:1993944549", "การล่มสลายของอาเมธอารัน" },
        objective = { "113:1612283376:1081081610", "อ่านแผ่นจารึกที่เล่าเรื่อง Ameth'Aran และการล่มสลาย แล้วกลับไปหา Sentinel Tysha Moonblade ใน Darkshore" },
        description = { "504:1633642075:1880985340", "ทางตะวันออกคือซาก Ameth'Aran บัดนี้วิญญาณไฮบอร์นที่เคยอยู่ภายในกำแพงยังวนเวียนอย่างไม่สงบ แต่ครั้งหนึ่งที่นี่เคยเป็นสถานที่ที่ข้ารับใช้ Azshara ใช้เวทมนตร์ทรงพลังกันอย่างเสรี\n\nข้าถูกส่งไปสำรวจและพบแผ่นจารึกใหญ่สองแผ่น เล่าเรื่อง Ameth'Aran กับการล่มสลาย ระหว่างอ่านอักษรรูน วิญญาณก็เข้ามารบกวนจนข้าต้องหนี\n\nถ้าทำได้ โปรดเข้าไปอ่านจารึกในซากเมืองแทนข้า" },
        progress = { "145:715179341:193439032", "เมื่อเจ้าอ่านจารึกและรู้เรื่องการล่มสลายของ Ameth'Aran แล้ว ข้าจะนำความรู้นี้ไป Auberdine เพื่อแจ้งสภาเหล่าผู้เก่าแก่" },
        completion = { "223:894313449:1512317664 N 102:1985105695:654268157", "เรามีบันทึกจากช่วงสงครามบรรพกาลน้อยมาก โดยเฉพาะใกล้ช่วงที่ Well of Eternity ถูกทำลาย เมื่อคิดถึงความปั่นป่วนและมหันตภัยในเวลานั้น ก็ไม่น่าแปลกใจนัก\n\nขอบใจ {name} ความช่วยเหลือของเจ้าทำให้งานที่นี่เสร็จ ข้าจะส่งรายงานฉบับสมบูรณ์ให้สภาได้แล้ว" },
        steps = { { "26:1485744905:1454036815", "อ่านบทขับลำนำแห่ง Ameth'Aran" }, { "27:73673936:1963146319", "อ่านบันทึกการล่มสลายของ Ameth'Aran" } },
    },
    [958] = { -- Tools of the Highborne
        title = { "22:699158016:82107810", "เครื่องมือของไฮบอร์น" },
        objective = { "65:1452339115:20672089", "นำ Highborne Relic 7 ชิ้นไปให้ Thundris Windweaver ใน Auberdine" },
        description = { "C 475:634283312:911319612", "{class} ข้ามีงานอยากขอให้เจ้าช่วย\n\nเคยเห็นซาก Ameth'Aran หรือยัง? ถ้ายัง มันอยู่ด้านตะวันออกของถนนสายหลักลงไปทางใต้ ครั้งหนึ่งเคยเป็นบ้านของไฮบอร์นผู้ทรงพลังมากมาย บัดนี้เหลือเป็นเครื่องเตือนใจถึงความพินาศจากการเล่นกับเวทมนตร์ของพวกเขา\n\nSentinel บอกข้าว่าวิญญาณไฮบอร์นยังอยู่และยังใช้เครื่องมือเวทมนตร์โบราณเหล่านั้น เราต้องยึดวัตถุเหล่านั้นมาเพื่อทำลาย" },
        progress = { "212:907757287:1602099242", "หากเครื่องมือที่นำพวกเขาสู่หายนะถูกทำลายไปพร้อมมหันตภัยที่ทำลายโลกของเราเสียก็คงดี... แต่ตอนนี้เราต้องทำทุกอย่างให้มั่นใจว่าความน่าสยดสยองในอดีตจะไม่เกิดซ้ำในอนาคต" },
        completion = { "220:2067790981:690749343", "แม้คงเป็นเพียงจินตนาการ แต่ข้าแทบสัมผัสได้ถึงความแปดเปื้อนของเวทไฮบอร์นชั่วร้ายที่เกาะอยู่ ข้าจะทำลายมัน เพื่อให้ความชั่วร้ายที่หลับใหลมานานไม่มีวันถูกปล่อยออกมาอีก" },
        required = { [5360] = { "15:2053470751:282623888", "วัตถุโบราณของไฮบอร์น" } },
        steps = { { "15:2053470751:282623888", "วัตถุโบราณของไฮบอร์น" } },
    },
    [963] = { -- For Love Eternal
        title = { "16:305784406:493621618", "เพื่อรักนิรันดร์" },
        objective = { "99:165762121:2064716594", "ปลดปล่อยวิญญาณของ Anaya Dawnrunner แล้วนำจี้ของนางกลับไปให้ Cerellean Whiteclaw ใน Auberdine" },
        description = { "466:1117405194:1108112340", "หลังการต่อสู้ที่ Well of Eternity ข้าได้ข่าวว่า Ameth'Aran ถูกทำลาย ผู้คนตายหมด รวมทั้ง Anaya คนรักของข้า\n\nข้าไม่เคยคิดเลยว่าผ่านมาหลายพันปี ความทรงจำถึงนางจะยังตามหลอกหลอนในฝัน ข้าเดินอย่างเลื่อนลอยในป่า Darkshore จนมาถึงซาก Ameth'Aran... และได้เห็นวิญญาณอันทุกข์ทรมานของผู้เป็นที่รัก\n\nนางต้องได้รับการปลดปล่อย แต่ข้าทำใจลงมือไม่ไหว ต้องทำลายร่างวิญญาณของนาง" },
        progress = { "164:586091375:1753172708", "ด้วยความโศกเศร้าเต็มหัวใจ ข้าตาม Shan'do Stormrage เข้าสู่นิทรา นำความทุกข์ไปสู่ความฝัน และหลับผ่านเวลาหลายพันปี" },
        completion = { "11:1191658970:1224418299 N 200:350418706:1522094849", "ขอบใจ {name} บางทีมันคงดีกว่า... หากข้าลงมือเอง แต่แม้ผ่านมาหลายพันปี ข้าก็ยังทนยกมือทำร้ายคนรักไม่ได้\n\nขอร้อง ให้ข้าอยู่กับความเศร้าตามลำพังเถิด..." },
        required = { [5382] = { "15:720699119:1593140639", "จี้ของ Anaya" } },
        steps = { { "15:720699119:1593140639", "จี้ของ Anaya" } },
    },
    [947] = { -- Cave Mushrooms
        title = { "14:1533271033:1395916555", "เห็ดในถ้ำ" },
        objective = { "74:294048271:767542521", "นำ Scaber Stalk 5 ชิ้น และ Death Cap 1 ชิ้นไปให้ Barithras Moonshade ใน Auberdine" },
        description = { "389:115738094:1653082402 N 97:1110405950:920239039", "ข้ากำลังคิดสูตรยาที่ต้องใช้เห็ดหายาก ซึ่งขึ้นอยู่ในถ้ำแห่งหนึ่งเท่านั้น ถ้ำนั้นอยู่หลัง Cliffspring Falls ทางตะวันออกและขึ้นเหนือไปเล็กน้อยตามแนวเขา\n\nข้าจะไปเองก็ได้ แต่ Grove of the Ancients เตือนไม่ให้เข้าใกล้ พันธมิตรผู้อาวุโสของเราสัมผัสได้ว่าถ้ำนั้นเป็นที่ซ่อนของความชั่วร้ายใหม่ใน Darkshore\n\nได้โปรด {name} เก็บเห็ดมาให้ข้า ระหว่างนั้นช่วยสำรวจด้วยว่าความกังวลของเหล่าผู้เก่าแก่เป็นจริงหรือไม่" },
        progress = { "26:1205453288:166581984 N 28:30486337:1433641011", "ได้เห็ดมาแล้วหรือ {name}? ไปถ้ำมาแล้วใช่ไหม?" },
        completion = { "13:1380265947:260987756 N 213:101013381:1312133515", "ขอบใจมาก {name} เห็ดเหล่านี้เป็นตัวอย่างที่ดีทีเดียว!\n\nตอนอยู่ที่ Cliffspring Falls พบอะไรที่ยืนยันคำเตือนของเหล่าผู้เก่าแก่หรือไม่?\n\nพวกเขามีปัญญาล้ำลึก แต่ข้าก็หวังว่าครั้งนี้จะเข้าใจผิด" },
        required = { [5271] = { "12:936544934:486497674", "ก้านเห็ด Scaber" }, [5270] = { "9:1198223373:586672115", "เห็ดหมวกมรณะ" } },
        steps = { { "12:936544934:486497674", "ก้านเห็ด Scaber" }, { "9:1198223373:586672115", "เห็ดหมวกมรณะ" } },
    },
    [948] = { -- Onu
        title = { "3:5246258:1370246", "โอนู" },
        objective = { "44:1843823025:1437420414", "ไปคุยกับ Onu ที่ Grove of the Ancients" },
        description = { "218:523765166:2057111325 N 95:215500350:165610621", "Onu ผู้เก่าแก่แห่งปัญญาที่ Grove of the Ancients รู้เรื่องการไป Cliffwater Falls ของเจ้าและอยากคุยด้วย สวนอยู่ทางใต้ใกล้แนวเขา\n\nเหล่าผู้เก่าแก่อดทนและรอบรู้ {name} แต่หาก Onu ขอหารือเรื่องที่เจ้าพบที่น้ำตก ข้าเกรงว่ามันคงเร่งด่วน" },
        completion = { "N 62:1304576095:1305747514", "{name} เจ้าถึงแล้ว\n\nดี\n\nเรามีเรื่อง... ต้องคุยกัน เจ้ากับข้า" },
    },
    [944] = { -- The Master's Glaive
        title = { "19:984329784:1017541849", "คมง้าวแห่งนาย" },
        objective = { "107:1516396067:158864572", "รวบรวมข้อมูล แล้วใช้ Phial of Scrying สร้าง Scrying Bowl เพื่อคุยกับ Onu ผ่านชาม" },
        description = { "438:1069705286:536748414", "แปลกที่มีนากาอยู่ใน Darkshore แต่สิ่งที่แปลกกว่าคือ... Twilight's Hammer ลัทธินั้นบูชาเจ้าแห่งพิภพเก่าแก่ยิ่งนัก ผู้ที่ถูกโค่นไปนานแล้ว\n\nMaster's Glaive ทางใต้เป็นสถานที่ที่เจ้าเก่าแก่ตนหนึ่งล้มลง\n\nไปที่นั่นแล้วมองหาสาวกลัทธิ Twilight's Hammer เพิ่ม\n\nรับขวดทำนายนี้ไป หลังค้นทั่ว Master's Glaive แล้ว ใช้มันสร้างชามทำนาย จากนั้นคุยกับข้าผ่านชาม" },
        progress = { "21:1077985478:846289086 N 37:313483940:2016679283", "Master's Glaive {name}\n\nไปที่นั่นแล้วคุยกับข้าอีกครั้ง" },
        completion = { "225:570490030:543132229", "Twilight's Hammer อยู่ที่ Master's Glaive หรือ?\n\nน่าเสียดาย\n\nเจ้าเก่าแก่ที่ถูกง้าวเสียบตายมานานแล้ว แต่เศษเสี้ยวพลังของมันอาจยังหลงเหลือ\n\nTwilight's Hammer คงกำลังตามหาพลังนั้น" },
        objectiveLabels = {
            event = { ["Enter the Master's Glaive"] = "เข้าไปใน Master's Glaive" },
        },
    },
    [949] = { -- The Twilight Camp
        title = { "17:1254572089:1433346735", "ค่ายสนธยา" },
        objective = { "65:1807983180:999635091", "หาเบาะแสในค่าย Twilight's Hammer ที่ Master's Glaive" },
        description = { "248:2047423967:288109664", "ยังไม่รู้จุดประสงค์ของ Twilight's Hammer ที่ Master's Glaive แต่ต้องเป็นเรื่องชั่วร้ายแน่\n\nค้นค่ายของพวกมันที่นั่น... หาสิ่งที่อาจบอกเจตนาของพวกมัน\n\nเราต้องรู้เจตนาก่อนจะวางแผนได้" },
        completion = { "85:88962181:1989726191", "หนังสือเล่มนี้เขียนด้วยมือเป็นภาษาโบราณ และมีภาพประกอบฝีมือศิลปินชั้นครู" },
    },
    [950] = { -- Return to Onu
        title = { "13:1393674717:1954923612", "กลับไปหาโอนู" },
        objective = { "41:2102630631:153889373", "นำ Insane Scribbles ที่เก็บมาไปให้ Onu" },
        description = { "260:1391025712:1582722943", "การมองเข้าไปใน Twilight Tome ชวนให้เสียสติ เพียงชำเลืองครู่เดียว ตัวอักษรก็เริ่มว่ายวนและเต้นระบำ ลวดลายที่เคยงดงามบิดเป็นรูปน่าสยดสยอง\n\nเจ้าทำได้เพียงฉีกหน้าที่เต็มไปด้วยตัวขีดเขียนวิปลาสออกมาหนึ่งแผ่น ก่อนความหน้ามืดจะครอบงำ" },
        progress = { "N 13:476018989:667601518", "{name} เจ้ากลับมาแล้ว" },
        completion = { "178:144661835:86941745", "เวทมนตร์ดั้งเดิมอันสับสนปั่นป่วนห้อมล้อมแผ่นกระดาษนี้ ข้าสัมผัสได้ถึงฝีมือของเหล่าผู้เก่าแก่ในนั้น\n\nหวังว่ามันจะเผยจุดประสงค์ของ Twilight's Hammer ใน Darkshore..." },
        required = { [5272] = { "16:1761464678:242954575", "ข้อความขีดเขียนเลอะเลือน" } },
        steps = { { "16:1761464678:242954575", "ข้อความขีดเขียนเลอะเลือน" } },
    },
    [951] = { -- Mathystra Relics
        title = { "16:1552313814:1832834129", "โบราณวัตถุแห่งมาธิสตรา" },
        objective = { "61:827038372:2108888366", "นำ Mathystra Relic 6 ชิ้นไปให้ Onu ที่ Grove of the Ancients" },
        description = { "491:1967213264:607568902", "แผ่นกระดาษที่เจ้าพบใน Master's Glaive เป็นหน้าจากตำราโบราณ... ที่เขียนโดยเอลฟ์! มันถูกสาปและแปดเปื้อนด้วยพลังชั่วร้ายของ Twilight's Hammer อย่างหนัก แต่ดูเหมือนลัทธิกำลังใช้เวทเอลฟ์โบราณนำเจ้านายเก่ากลับสู่โลกเรา\n\nไปยังซาก Mathystra ทางตะวันออกเฉียงเหนือ ค้นหาโบราณวัตถุท่ามกลางหญ้าและกองหินแตก เมื่อศึกษามัน เราอาจรู้ว่าลัทธิคิดจะใช้เวทเอลฟ์อย่างไร" },
        progress = { "N 64:1078951480:1208911769", "{name} การค้นซาก Mathystra ได้ผลบ้างหรือไม่?" },
        completion = { "229:41235640:1593615741 N 1:46:46", "ขอบใจ โบราณวัตถุเหล่านี้มาจากยุครุ่งเรืองของ Mathystra ป้อมปราการเอลฟ์ที่เคยยิ่งใหญ่จางหายไปแล้ว แต่เศษเสี้ยวเวทยังอยู่ หวังว่าเราจะไขความลับของสถานที่นั้นได้ก่อนศัตรู...\n\nจงระวังตัว {name}" },
        required = { [5273] = { "15:540822051:620532277", "วัตถุโบราณแห่ง Mathystra" } },
        steps = { { "15:540822051:620532277", "วัตถุโบราณแห่ง Mathystra" } },
    },
    [982] = { -- Deep Ocean, Vast Sea
        title = { "20:61155592:945087705", "มหาสมุทรลึก ทะเลกว้าง" },
        objective = { "189:1654329901:1216402613", "นำ Silver Dawning's Lockbox และ Mist Veil's Lockbox จากซากเรือทางเหนือของหมู่บ้านไปให้ Gorbold Steelhand ใน Auberdine" },
        description = { "496:1535960690:730178161", "นอกชายฝั่ง Darkshore ทางเหนือมีซากเรือสองลำ Silver Dawning กับ Mist Veil ไม่นานมานี้ ทั้งคู่เจอพวกเมอร์ล็อกระหว่างข้ามทะเลกว้างมายัง Auberdine บัดนี้จมอยู่ก้นทะเลเป็นถ้วยรางวัลให้เจ้าพวกชั่วนั่น\n\nกัปตันทั้งสองหนีไม่รอดในคืนนั้น สมุดบันทึกและของส่วนตัวยังอยู่ในกล่องล็อกข้างล่าง อยากให้เจ้านำกลับมาให้เรา มันมีความหมายมากต่อลูกเรือที่ยังอยู่แถวนี้" },
        progress = { "196:743014206:308934525", "กัปตันเรือเหล่านั้นเป็นไนต์เอลฟ์ที่ดี สมควรได้พบชะตาที่ดีกว่านี้ บางทีการดูแลของส่วนตัวของพวกเขาคงเป็นวิธีที่ดีที่สุดให้วิญญาณสงบ" },
        completion = { { "223:800564172:870159270", "223:120952244:922226657" }, "เจ้าช่วยผู้คนใน Auberdine ได้มาก เด็กรุ่นเยาว์ เราจะดูแลของของพวกเขาอย่างเหมาะสม\n\nส่วนเจ้ารับสิ่งนี้ไว้ อย่างน้อยข้าก็ควรตอบแทนผู้กล้าที่ช่วยแก้ไขสิ่งผิดให้ถูกต้อง", variants = { { "222:790845116:418147620", "เจ้าช่วยพวกเราที่ Auberdine ไว้มาก เจ้าหนุ่ม เราจะดูแลข้าวของของพวกเขาให้ดี\n\nส่วนเจ้ารับสิ่งนี้ไว้เถอะ นี่เป็นอย่างน้อยที่ข้าจะตอบแทนความกล้าของคนที่ลงมือแก้ไขเรื่องนี้ได้" } } },
        required = { [12191] = { "24:440008881:653736007", "หีบล็อกของเรือ Silver Dawning" }, [12192] = { "19:574277098:1898456546", "หีบล็อกของเรือ Mist Veil" } },
        steps = { { "24:440008881:653736007", "หีบล็อกของเรือ Silver Dawning" }, { "19:574277098:1898456546", "หีบล็อกของเรือ Mist Veil" } },
    },
    [1138] = { -- Fruit of the Sea
        title = { "16:727256750:1848155989", "ผลผลิตแห่งท้องทะเล" },
        objective = { "57:2042076733:477499559", "เก็บ Fine Crab Chunk 6 ชิ้นให้ Gubber Blump ใน Auberdine" },
        description = { "488:1107249867:1660573482", "ข้าชอบปู ปูคือผลผลิตของทะเล! เอาไปอบ ย่าง ต้ม ปิ้งก็ได้ ทอดกระทะ ทอดน้ำมัน หรือผัดก็ได้ ยังมีสลัดปู ซุปปู สตูว์ปู ปูผัดพริก ปูมะนาว ปูรากวิปเปอร์ แล้วก็ปูเซอร์ไพรส์แห่ง Ironforge นั่น... ก็คงหมดแล้ว\n\nตอนนี้ข้าตกปลาอยู่ เลยไปหาเนื้อปูดี ๆ ไม่ได้ เจ้าหาได้จาก Reef Crawler และ Encrusted Tide Crawler เอาไปทำอาหารได้ตั้งมากมาย ทั้งอบ ย่าง ต้ม..." },
        progress = { "96:19415662:1249503043 N 60:1308705194:1933958216", "...ปูมะนาว ปูรากวิปเปอร์ แล้วก็ปูเซอร์ไพรส์แห่ง Ironforge ก็คงหมดแล้ว\n\nอ้อ สวัสดี {name} ได้เนื้อปูดี ๆ ที่ข้าบอกมาแล้วหรือยัง?" },
        completion = { "52:913588843:1276424287 N 185:400483912:1134663853", "โอ้ เนื้อปูดี ๆ แบบนี้แหละที่ข้าต้องการ ขอบใจ {name}! ข้าได้สิ่งนี้ตอนตกปลาเมื่อครู่ แต่ไม่มีประโยชน์กับข้า เจ้าอาจเอาไปใช้ได้ มันทำอาหารปูให้อร่อยไม่ได้แน่ ๆ\n\nข้าเล่าเรื่องปูให้ฟังหมดแล้วใช่ไหม?" },
        required = { [12237] = { "16:846640703:1182399575", "เนื้อปูชิ้นดี" } },
        steps = { { "16:846640703:1182399575", "เนื้อปูชิ้นดี" } },
    },
    [1141] = { -- The Family and the Fishing Pole
        title = { "31:1427157876:1450957373", "ตระกูลกับคันเบ็ด" },
        objective = { "56:1146014317:229199796", "ตก Darkshore Grouper 6 ตัวให้ Gubber Blump ใน Auberdine" },
        description = { "490:1644915351:1656499735", "ข้าชอบตกปลา ตระกูล Blump ขึ้นชื่อเรื่องตกปลา ข้าชื่อ Gubber Blump ข้าตกปลา\n\nมีปลาที่ข้าชอบตกแถวนี้ชื่อ Darkshore Grouper เคยออกเรือไปตกปลาเก๋า แต่ตั้งแต่เมอร์ล็อกใจร้ายมาอยู่ก็ไม่มีเรือออกอีกเลย พนันได้ว่าพวกมันกินปลาเก๋าไปหมดด้วย\n\nเจ้าจะช่วยตก Darkshore Grouper ให้ข้าไหม? ถ้าช่วย ข้าจะมอบคันเบ็ดตระกูล Blump ของแท้ให้! เป็นคันเบ็ดที่ใช้จับปลาได้ดีจริง ๆ" },
        progress = { "162:449087153:1264883488", "Darkshore Grouper เอาไปทำอาหารดี ๆ ได้หลายอย่าง มันอร่อยนะ แต่ข้าว่าตอนตกสนุกกว่า\n\nตกได้บ้างหรือยัง?" },
        completion = { "32:1076754947:2095197480 N 258:1523828084:352478129", "ปลาเก๋าพวกนี้ดีจริง ๆ {name}! ขอบใจที่ช่วย!\n\nเจ้าตกปลาเก่งอย่างน้อยก็พอ ๆ กับ Graun Blump ญาติข้า นางมีเคราเหมือนกัน แถมกลิ่นแปลก ๆ แต่ไม่เป็นอุปสรรคต่อการตกปลาเลย ข้าว่าเจ้าเหมาะจะใช้คันเบ็ดตระกูล Blump แล้ว" },
        required = { [12238] = { "17:2094290931:100838410", "ปลาเก๋า Darkshore" } },
        steps = { { "17:2094290931:100838410", "ปลาเก๋า Darkshore" } },
    },
    [4740] = { -- WANTED: Murkdeep!
        title = { "17:132153389:406680060", "ประกาศจับเมิร์กดีป!" },
        objective = { "206:1897650992:681361153", "ค้นหาและสังหาร Murkdeep ซึ่งคอยปกป้องกระท่อมเมอร์ล็อกริมน้ำทางใต้ของ Auberdine แล้วรายงาน Sentinel Glynda Nal'Shea ใน Auberdine" },
        description = { "498:1896742885:1349781597", "โปรดทราบ!\n\nมีรางวัลสำหรับผู้สังหารเมอร์ล็อกชื่อ Murkdeep เจ้าสัตว์ชั่วนี้ทำให้ Sentinel เสียชีวิตอย่างน้อยหนึ่งนาย และต้องสงสัยว่าจมเรือสินค้านอก Darkshore อย่างน้อยสองลำ!\n\nมีผู้พบ Murkdeep ครั้งสุดท้ายที่ค่ายกระท่อมเมอร์ล็อกทางใต้ของ Auberdine เชื่อว่ามันคอยปกป้องกระท่อมที่นั่น ติดต่อรับค่าหัวได้ที่ Sentinel Glynda Nal'Shea ใน Auberdine\n\nสภาหมู่บ้าน Auberdine" },
        progress = { "10:1724938855:1235015449 C 110:1960912815:1899257201", "สวัสดี {class} วันนี้มีอะไรให้ Sentinel ช่วยหรือ? บางทีเจ้ามาถามเรื่องค่าหัว Murkdeep?" },
        completion = { "239:938963104:222175440 N 107:275127364:700976005", "ดูเหมือนเจ้าจะมาทำมากกว่าถามเสียแล้ว! ชาวบ้านคงยินดีที่คืนนี้จะหลับได้สนิทและปลอดภัยขึ้น\n\nวันนี้เจ้าเป็นผู้ลงทัณฑ์เพื่อความยุติธรรมของ Auberdine {name} ข้าขอมอบสิ่งนี้เป็นรางวัลที่เหมาะสม... แก่วีรชนแท้จริงของผู้คนที่นี่" },
        objectiveLabels = {
            monster = { ["Murkdeep slain"] = "ปราบ Murkdeep" },
        },
    },
    [4761] = { -- Thundris Windweaver
        title = { "19:7578041:380076568", "ธันดริส วินด์วีเวอร์" },
        objective = { "44:1355971360:455089698", "ไปคุยกับ Thundris Windweaver ใน Auberdine" },
        description = { "459:874375165:958318061", "สิ่งที่เจ้าสอดแนมจากค่ายเฟอร์โบลก์เป็นข้อมูลที่ Thundris Windweaver ควรรู้ เขาทำหน้าที่ผู้อาวุโสแห่ง Auberdine ดูแลกิจการประจำวันของหมู่บ้านด้วยปัญญาและความยุติธรรม ช่วยเล่าสิ่งที่พบเกี่ยวกับสถานการณ์เฟอร์โบลก์ให้เขาฟัง\n\nข้าเชื่อว่าเขามีความคิดเกี่ยวกับสาเหตุความเสื่อมทรามของพวกมัน บางทีเจ้าอาจช่วยเขาวางแผนฟื้นฟูสมดุลธรรมชาติที่นี่!" },
        completion = { "10:1401179418:1568553899 C 325:759614844:1102809535", "ยินดีที่ได้พบ {class} ข่าวจากการสอดแนมเฟอร์โบลก์ของเจ้ามาถูกเวลาสำหรับ Auberdine พักนี้เราต้องรับมือทั้งผู้อาศัยในป่าที่เป็นศัตรูกับเราอย่างเปิดเผย และความแปดเปื้อนของป่าเอง หวังว่าเจ้าจะช่วยเราในช่วงเวลาอันน่าวิตกนี้ได้" },
    },
    [4762] = { -- The Cliffspring River
        title = { "21:943485480:1698629530", "แม่น้ำคลิฟฟ์สปริง" },
        objective = { "193:934773682:276980701", "ไปทางเหนือของ Auberdine ถึงน้ำตกแห่งแรกตาม Cliffspring River เก็บน้ำในแอ่ง แล้วนำ Cliffspring River Sample กลับไปให้ Thundris Windweaver ใน Auberdine" },
        description = { "496:1758595661:1999189755", "แม่น้ำ Cliffspring เริ่มสกปรกและแปดเปื้อน มันไหลออกที่ Mist's Edge ข้าเกรงว่ากระแสน้ำจะส่งผลถึง Auberdine ในไม่ช้า สงสัยว่าเฟอร์โบลก์ Blackwood ต้นน้ำเป็นสาเหตุ แต่พวกมันคงไม่ใช่รากเหง้าที่แท้จริง\n\nนำหลอดเก็บตัวอย่างไปปากแม่น้ำทางเหนือ แล้วตามน้ำเข้าแผ่นดินจนถึงน้ำตกแห่งแรก ตักน้ำในแอ่งที่นั่น จะเห็นสะพานอยู่เหนือศีรษะ เมื่อเก็บแล้วกลับมาหาข้าใน Auberdine" },
        progress = { "195:1075903060:1323596553", "มลพิษใน Cliffspring River เป็นเพียงจุดเริ่มต้นของสิ่งน่าวิตกใน Darkshore ตัวอย่างของเจ้าจะช่วยให้เราวางแผนได้... ข้าเริ่มสงสัยว่าอาจต้องเป็นแผนโจมตี" },
        completion = { "146:809384631:1699081975 N 262:1439738435:899943764 N 50:346935097:1306131923", "ไม่แปลกที่น้ำแปดเปื้อนขนาดนี้ แต่ดูสิ มันเน่าเสียมากขึ้นเพียงใด! ดูท่าเราต้องรีบลงมือแล้วนะ {name}?\n\nทางตะวันออกของเราคือ Felwood ต้นตอที่แท้จริงของความชั่วร้ายซึ่งข้าเคยเห็นมาแล้ว คาดว่าตัวอย่างจะยืนยันเรื่องนี้ เราอาจหาทางชำระได้ที่นี่ แต่จะลองก็ต้องมีคนช่วย เมื่อถึงเวลานั้น {name} หวังว่าเจ้าจะช่วยเราได้" },
        required = { [12349] = { "24:692389837:1036122247", "ตัวอย่างน้ำจากแม่น้ำ Cliffspring" } },
        steps = { { "24:692389837:1036122247", "ตัวอย่างน้ำจากแม่น้ำ Cliffspring" } },
    },
    [4763] = { -- The Blackwood Corrupted
        title = { "23:474275673:312440461", "แบล็กวูดที่ถูกครอบงำ" },
        objective = { "356:72268960:268537940", "เติมน้ำใน Empty Cleansing Bowl ที่ Auberdine Moonwell เก็บตัวอย่างผลไม้ ถั่ว และธัญพืชจากค่าย Blackwood ทางเหนือ ผสมแล้ววางใกล้กองไฟที่อยู่ใกล้ Cliffspring River ที่สุดในค่ายเหนือ เพื่อเรียกซาเทียร์ จากนั้นนำ Talisman of Corruption ไปให้ Thundris Windweaver ใน Auberdine" },
        description = { "497:904887787:1111958949", "เรารู้แล้วว่าซาเทียร์เป็นต้นเหตุหนึ่งที่ครอบงำเฟอร์โบลก์ พวกมันส่งเวทผ่านเครื่องราง หากจะช่วยเฟอร์โบลก์ให้รอด เราต้องล่อซาเทียร์ผู้บงการออกมาแล้วชิงเครื่องราง!\n\nเติมน้ำในชามที่บ่อจันทร์ เก็บอาหารตัวอย่างจากค่ายเฟอร์โบลก์ทางเหนือ ผสมแล้ววางใกล้กองไฟริมแม่น้ำ เฟอร์โบลก์ที่กินจะถูกชำระชั่วครู่ นานพอให้ซาเทียร์ผู้บงการออกมา... แล้วเจ้าต้องสังหารมัน!" },
        progress = { "247:167147071:962377187", "Talisman of Corruption เป็นเครื่องมือชั่วร้ายที่ทำลายสมดุลธรรมชาติ เมื่อเจ้าชิงมันจากซาเทียร์ที่ทรมานเฟอร์โบลก์แล้วนำมาให้ข้าทำลาย เราจะได้ชัยชนะครั้งใหญ่ในวันนี้!" },
        completion = { "117:838981123:1903469836 N 240:1547117412:1255376248", "สงครามชิงป่าคืนจากพลังชั่วร้ายเพิ่งเริ่ม แต่วันนี้เราชนะไปหนึ่งศึกแล้ว! {name} ชาว Auberdine เป็นหนี้บุญคุณเจ้าจนคงตอบแทนได้ยาก รับสิ่งนี้พร้อมคำขอบคุณของเรา ความรู้ที่ได้วันนี้อาจช่วยปลดปล่อยสหายเฟอร์โบลก์จากความทรมานได้ตลอดไปสักวัน" },
        required = { [12355] = { "22:1397735623:1173234703", "เครื่องรางแห่งความแปดเปื้อน" } },
        steps = { { "22:1397735623:1173234703", "เครื่องรางแห่งความแปดเปื้อน" } },
    },
    [3524] = { -- Washed Ashore
        title = { "13:2128955524:1213562000", "เกยฝั่ง" },
        objective = { "144:2083951728:2146888587", "เก็บ Sea Creature Bones จากสัตว์ทะเลที่เกยฝั่งทางใต้ของ Auberdine แล้วนำกลับไปให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        description = { "503:1726611656:1089795128", "สัตว์ทะเลอันสง่างามมักขึ้นมาเกยชายฝั่ง Darkshore แล้วติดอยู่จนตาย ระยะหลังมีจำนวนมากขึ้นเรื่อย ๆ ข้าถูกส่งมาจาก Temple of the Moon เพื่อสืบหาสาเหตุ แต่เมอร์ล็อกตามริมน้ำทำให้การศึกษาลำบาก\n\nมีสัตว์ยักษ์เกยฝั่งอยู่ทางใต้ของ Auberdine โดยมีพวกเมอร์ล็อก Greymist อันน่ารังเกียจล้อมอยู่ เจ้าไปเก็บกระดูกของมันมาให้เราศึกษาได้ไหม?" },
        progress = { "278:10192059:37794088", "สัตว์เหล่านี้เพิ่งเริ่มขึ้นมาเกยฝั่ง Darkshore มากจนน่าตกใจในช่วงหลัง ข้าอดคิดไม่ได้ว่านี่อาจเป็นลางร้าย การเก็บตัวอย่างกระดูกจากซากทางใต้จะช่วยให้พวกเราใน Darnassus ประเมินสถานการณ์ได้!" },
        completion = { "364:1008947454:1436398496", "หวังว่าพวกเมอร์ล็อกจะไม่รบกวนเจ้ามากตอนเก็บสิ่งนี้นะ! ข้าจะส่งมันขึ้นฮิปโปกริฟฟ์เที่ยวถัดไปไปยัง Darnassus ทาง Temple of the Moon มอบเงินไว้ให้ตอบแทนผู้ช่วย รับส่วนนี้พร้อมคำขอบคุณของเราเถิด\n\nความสำเร็จของเจ้าทำให้ข้ากล้าขอให้ช่วย Temple of the Moon อีกเรื่อง หากเจ้าสนใจ..." },
        required = { [12242] = { "18:1148672610:258209944", "กระดูกสัตว์ทะเล" } },
        objectiveLabels = {
            item = { ["Sea Creature Bones"] = "กระดูกสัตว์ทะเล" },
        },
    },
    [4681] = { -- Washed Ashore
        title = { "13:2128955524:1213562000", "เกยฝั่ง" },
        objective = { "153:2096424963:821157763", "เก็บ Sea Turtle Remains จาก Skeletal Sea Turtle ในน้ำทางตะวันตกของ Auberdine แล้วกลับไปคุยกับ Gwennyth Bly'Leggonde" },
        description = { "495:933558926:328328607", "สัตว์ที่เกยฝั่งตัวนั้นเป็นเพียงหนึ่งในหลายกรณีที่ Darkshore ยังมีอีกทั้งตามชายฝั่งและในน้ำ ข้าอยากให้เจ้าตรวจสอบอีกตัว มีรายงานว่ามันอยู่ในน้ำตรงทางตะวันตกของ Auberdine ใกล้เรือจม เก็บสิ่งที่เป็นประโยชน์ต่อการศึกษากลับมาให้ข้า\n\nระหว่างทางเจ้าอาจพบซากอื่นด้วย หากค้นพบสิ่งใด ช่วยแจ้งพวกเราด้วย!" },
        progress = { "316:373436867:104587934", "เมื่อเจ้าตรวจซากสัตว์ในน้ำทางตะวันตกแล้ว ข้าคงเขียนรายงานที่ครบถ้วนส่ง Temple of the Moon ใน Darnassus ได้ บางทีเราอาจเข้าใกล้คำตอบว่าทำไมสัตว์โชคร้ายเหล่านี้จึงเลือกมาจบชีวิตบนชายฝั่ง Darkshore" },
        completion = { "465:1586222022:1515374567 N 1:33:33", "วันนี้เจ้าช่วยเราได้มาก ตอนนี้เรามีโอกาสไขปริศนาแล้วว่าทำไมสัตว์เหล่านี้จึงเลือกมาเกยฝั่ง Darkshore ความคิดที่ว่าพวกมันอาจกำลังหนีจากแถบ Teldrassil ช่างน่าวิตก หากพบซากอื่นระหว่างเดินทาง โปรดบอกข้า งานศึกษาของเราเพิ่งเริ่มต้นเท่านั้น\n\nในนาม Temple of the Moon ขอให้รับสิ่งนี้เป็นคำขอบคุณสำหรับความพยายาม ขอบใจ {name}!" },
        required = { [12289] = { "18:336076730:1131874915", "ซากเต่าทะเล" } },
        steps = { { "18:336076730:1131874915", "ซากเต่าทะเล" } },
    },
    [983] = { -- Buzzbox 827
        title = { "11:713221265:692039685", "บัซบ็อกซ์ 827" },
        objective = { "53:1957874883:571277966", "เก็บ Crawler Leg 6 ชิ้น แล้วใส่ใน Buzzbox 827" },
        description = { "505:1384395468:1142943942", "เฮ้! มาช่วยข้าทดลองสิ่งประดิษฐ์ล่าสุด บัซบ็อกซ์กัน มันทำให้คุยกับคนที่อยู่ไกลได้!\n\nเจ้าอาจเห็นมาแล้ว เป็นกล่องที่มีคันโยก ปัญหาเดียวคือต้องซ่อมบำรุงตลอด\n\nแต่ละเครื่องเสียคนละอย่าง ข้าเลยคิดอย่างชาญฉลาด วางแต่ละเครื่องใกล้สัตว์ที่มีชิ้นส่วนเหมาะกับการซ่อมเครื่องนั้น ตอนนี้ Buzzbox 827 กำลังรวน อยู่ทางใต้ของ Auberdine ใกล้ ๆ นี่เอง ใช้ Crawler Leg 6 ชิ้นก็ซ่อมได้ ข้ามีค่าจ้างให้นะ..." },
        progress = { "135:1921924794:2023154405", "Buzzbox 827 เงียบสนิทชวนขนลุก ไฟกะพริบดวงเดียวบ่งบอกว่าต้องใส่ Crawler Leg 6 ชิ้นลงในช่องรับของ" },
        completion = { "420:2089846150:1061383959", "เมื่อเจ้าใส่ขาปูลงไป ก็ได้ยินเสียงเฟืองเริ่มหมุน จากเสียงกระแทกภายในบัซบ็อกซ์ เจ้าคิดว่าขาปูกำลังถูกส่งไปยังตำแหน่งที่เหมาะสม ไม่นานเครื่องก็ครางเบา ๆ และมีเสียงเล็กจิ๋วดังออกมา\n\n“ฮัลโหล? เอ่อ... ฮัลโหล! เจ้าซ่อมได้แล้ว! ข้า Wizbang เอง! ขอบใจมาก... ว่าแต่ อยากซ่อมอีกเครื่องไหม?”" },
        required = { [5385] = { "11:176179879:1732823036", "ขาปู" } },
        steps = { { "11:176179879:1732823036", "ขาปู" } },
    },
    [1001] = { -- Buzzbox 411
        title = { "11:712956806:691970904", "บัซบ็อกซ์ 411" },
        objective = { "82:2090616649:212811965", "เก็บ Thresher Eye 3 ชิ้นจาก Darkshore Thresher ในทะเลลึกใกล้ Buzzbox 411" },
        description = { "396:741740265:2120183571", "เสียงเล็กจิ๋วแทรกเสียงซ่าดังจากส่วนลึกของเครื่อง\n\n“Wizbang พูดอยู่! บัซบ็อกซ์เครื่องถัดไปอยู่ทางเหนือของ Auberdine บนหาด\n\nเครื่องนั้นหมายเลข 411 ต้องใช้ Thresher Eye 3 ชิ้นซ่อม พวกมันอยู่ไม่ไกลจากฝั่ง! พวก Darkshore Thresher น่ะ... ฮึก... โทษที...\n\nเหมือนครั้งก่อน พอเอาของใส่บัซบ็อกซ์ มันก็จะคายรางวัลออกมา ฮึก... อะไรนะ? เปล่า ข้าสบายดี!”" },
        progress = { "101:249499942:20379488", "ช่องรับของของเครื่องเปิดอยู่ ราวกับกำลังรอให้ใส่ Thresher Eye 3 ชิ้นลงไป" },
        completion = { "365:1507996497:872305818", "หลังใส่ตาของ Thresher ลงไป บัซบ็อกซ์ก็เริ่มทำงาน มีเสียงซ่าครู่หนึ่งก่อนเสียงเล็กจิ๋วที่คุ้นเคยจะดังขึ้น\n\n“ไวน์ปูนี่เด็ดจริง ๆ...” ฮึก\n\n“หืม? อ้อ ซ่อมเสร็จแล้วเหรอ? โอ้ เจ้าเร็วจัง งั้น... อยากซ่อมอีกเครื่องไหม?”\n\nเจ้าคิดว่าได้ยินเสียงเทของเหลวลงถ้วย ตามด้วยเสียงดื่มดังอึก ๆ" },
        required = { [5412] = { "12:1748778554:1639317737", "ตาของ Thresher" } },
        steps = { { "12:1748778554:1639317737", "ตาของ Thresher" } },
    },
    [1002] = { -- Buzzbox 323
        title = { "11:712891016:691953876", "บัซบ็อกซ์ 323" },
        objective = { "58:662616499:1328401973", "เก็บ Moonstalker Fang 6 ชิ้น แล้วใส่ใน Buzzbox 323" },
        description = { "359:1772296513:1361789889", "บัซบ็อกซ์ส่งเสียงซ่า ก่อนที่เจ้าจะได้ยิน Wizbang พูด\n\n“เครื่องต่อไปหมายเลข 323 อยู่เหนือ Auberdine แต่... เบียร์อยู่ไหน? หืม? อ้อ มันอยู่ริมถนน หาไม่ยากหรอก ใกล้สะพานน่ะ”\n\nWizbang พึมพำฟังไม่รู้เรื่อง ก่อนมีเสียงดื่มดังอึกใหญ่\n\n“เครื่องนี้ต้องใช้เขี้ยว Moonstalker... 6 ชิ้น”" },
        progress = { "204:177565827:300841260", "แม้เจ้ายังไม่ได้ใส่ Moonstalker Fang ทั้ง 6 ชิ้นลงไป แต่เหมือนได้ยินเสียงซ่าและคำพูดฟังไม่รู้เรื่องของโนมออกมาจากข้างใน มีใครซ่อมเครื่องไปแล้วหรือ?" },
        completion = { "235:1130291364:844055304", "บัซบ็อกซ์ทำงานขึ้นทันที เจ้าจำเสียงฟันที่ถูกบดเป็นผงจากข้างในได้ชัดเจน\n\n“อ้าว มาถึงแล้ว! เป็นข่าวที่เยี่ยมมม... งั้น... ทำไมไม่เดินต่อไปล่ะ? อ้อ! เว้นแต่ว่าเจ้าอยากได้งานอีก!”" },
        required = { [5413] = { "16:1771909042:1596089936", "เขี้ยวมูนสตอล์กเกอร์" } },
        steps = { { "16:1771909042:1596089936", "เขี้ยวมูนสตอล์กเกอร์" } },
    },
    [1003] = { -- Buzzbox 525
        title = { "11:713023116:691988200", "บัซบ็อกซ์ 525" },
        objective = { "110:113521246:407989266", "เก็บ Grizzled Scalp 4 ชิ้นจาก Grizzled Thistle Bear ทางใต้ของ Auberdine แล้วใส่ใน Buzzbox 525" },
        description = { "498:1364083582:1226456864", "ท่ามกลางเสียงเดือดและเสียงหยดน้ำจากเครื่อง เจ้าได้ยินเสียงโงนเงนของ Wizbang\n\n“เครื่องต่อไปอยู่ตามถนนลงใต้ไปไกลหน่อย หาไม่ยาก... อยู่ข้างทาง... ใกล้รั้ว ข้าว่าซ่อนมันในพุ่มไม้... พุ่มมมไม้ ฮี่ ๆ... ใช่ Buzzbox 525 ต้องใช้หนังหัวจากพวก Grizzled Thistle Bear โอ๊ย ชื่อเรียกยากจัง กริซซึล... ฮี่ ๆ...”\n\nมีเสียงดื่มอีกครั้ง แล้วเครื่องก็ดับ ทันใดนั้นมันกลับทำงานขึ้นมา\n\n“4 ชิ้น!”" },
        progress = { "317:1791407116:1889957114", "เจ้าฟังเสียงร้องเพลงจาก Buzzbox 525\n\n“ไวน์ปูหวาน เบียร์เธรชเชอร์ดี เหล้า Moonstalker ก็ยอดไป แต่ไม่มีใดล้ำค่าเท่าเบียร์หมีทิสเซิล อีกไม่นานข้าจะได้ดื่มสมใจ!”\n\nช่องรับของเปิดรอหนังหัวทั้ง 4 ชิ้น ขณะที่เพลงเดิมดังซ้ำไปมา" },
        completion = { "502:2098629011:649439338", "“เอาหนังหัวใส่แล้วเหรอ? ดีเหลือเกิน... อะไรนะ? อ้อ ใช่ เจ้าคงรู้แล้วว่าข้าคุยกับเจ้าได้โดยไม่ต้องมีของพวกนั้นในเครื่อง แต่ตอนบอกว่ามันเสีย ข้าพูดจริงนะ!\n\nคือว่า นอกจากใช้สื่อสารแล้ว บัซบ็อกซ์ยังใช้หมักและกลั่นเหล้าชั้นดีด้วย โทษทีที่หลอกนิดหน่อย แต่พวกไนต์เอลฟ์ไม่ชอบให้ข้าขายเหล้าในเมือง ข้าใส่ของพิเศษไว้ในกล่องนี้แทนคำขอบคุณสำหรับความพยายามของเจ้า รับไปใช้ให้สนุก!”" },
        required = { [5414] = { "14:311409044:58511758", "หนังหัวหมีขนหงอก" } },
        steps = { { "14:311409044:58511758", "หนังหัวหมีขนหงอก" } },
    },
    [2118] = { -- Plagued Lands
        title = { "13:1811141848:1578745664", "ผืนดินต้องโรค" },
        objective = { "194:35120438:2040716793", "จับ Rabid Thistle Bear ที่ยังมีชีวิตแล้วพากลับไปหา Tharnariun หากทำกับดักหาย ให้กลับไปขอกับดักใหม่จาก Tharnariun Treetender" },
        description = { "471:558207698:1249498744 N 1:46:46", "โรคภัยกำลังแพร่ทั่ว Darkshore ยึดทั้งจิตใจและร่างกายของทุกชีวิตที่สัมผัสมัน\n\nหมีทิสเซิลได้รับผลกระทบรุนแรงที่สุด สัตว์ที่เคยสง่างามกลับกลายเป็นเครื่องมือแห่งการทำลาย บ้าคลั่งและดุร้าย ข้าอาจมีหนทางรักษา\n\nนำกับดักนี้ไปวางบนพื้นในป่า Rabid Thistle Bear ที่เดินผ่านแสงจะเชื่องลงชั่วครู่ จากนั้นมันจะตามเจ้า พามันกลับมาที่นี่ {name}" },
        progress = { "37:44502331:74716980 N 151:1197486038:1700022626", "พาสัตว์ป่วยมาให้ข้าแล้วหรือ {name}?\n\nหากวางกับดักไม่สำเร็จ อย่าเพิ่งกังวล ความหวังของ Tharnariun ยังไม่สิ้น หากต้องการกับดักใหม่ ให้ยกเลิกภารกิจแล้วกลับมารายงานข้า" },
        completion = { "30:1219300875:1905989455 N 38:475194614:77474933", "งานของเราเพิ่งเริ่มเท่านั้น {name} พร้อมสำหรับงานต่อไปหรือยัง?" },
        steps = { { "27:1753516320:749004347", "จับ Rabid Thistle Bear" } },
    },
    [2138] = { -- Cleansing of the Infected
        title = { "25:1550651878:969720430", "กำจัดสัตว์ติดเชื้อ" },
        objective = { "94:1059827752:941557156", "กำจัด Rabid Thistle Bear 20 ตัว แล้วกลับไปหา Tharnariun Treetender ใน Darkshore" },
        description = { "223:1359138529:214953855 N 160:2081107968:647339486", "เป็นอย่างที่ข้ากลัว ยารักษาไม่ได้ผล\n\nข้าเสียใจมากที่ต้องสั่งฆ่าสัตว์ของธรรมชาติ แต่จำเป็นต้องยุติชีวิตหมีทิสเซิลที่ป่วยและแปดเปื้อน\n\nกลับเข้าไปในป่าแล้วกำจัด Rabid Thistle Bear 20 ตัว {name} มันคงหยุดโรคระบาดไม่ได้ แต่จะช่วยชะลอความเสียหายที่พวกมันทำต่อป่าและผู้อาศัยอยู่ได้ระยะหนึ่ง" },
        progress = { "22:530003294:1083844443", "ทำงานเสร็จแล้วหรือ?" },
        completion = { "41:1506638312:2015064460 N 79:267178102:616855000 N 48:1548424859:1520944988", "เจ้าช่วย Auberdine ได้มาก {name} แต่ภารกิจยังไม่จบ\n\nพักผ่อนแล้วค่อยกลับมาหาข้า\n\n...และ {name} เตรียมใจและจิตวิญญาณให้พร้อมกับการนองเลือดอีกครั้ง" },
        objectiveLabels = {
            monster = { ["Rabid Thistle Bear slain"] = "ปราบ หมีหนามคลุ้มคลั่ง" },
        },
    },
    [2139] = { -- Tharnariun's Hope
        title = { "17:1046632247:1949651463", "ความหวังของธาร์นาริอุน" },
        objective = { "29:609494912:892788706", "ค้นหาและสังหาร Den Mother" },
        description = { "65:110977476:255962638 N 329:547305357:770947359 N 81:149535046:459931742", "เพื่อให้ผู้คนและผืนดินของเรารอด บางครั้งก็ต้องจ่ายด้วยสิ่งที่น่าเศร้า {name}\n\nเจ้าหลั่งเลือดข้ารับใช้ของธรรมชาติ สัตว์ป่วยมากมายถูกเจ้าปราบลง ผู้คนแห่ง Auberdine เป็นหนี้บุญคุณเจ้า เพราะความเจ็บปวดของป่าบรรเทาลง แม้เพียงชั่วขณะ\n\nข้ามีงานสุดท้ายให้เจ้า แต่ต้องเตือนไว้ว่าเจ้าต้องฆ่าอีกครั้ง ข้าหวังว่านี่จะเป็นครั้งสุดท้ายที่ต้องรบกวน {name}\n\nDen Mother อยู่ในถ้ำทางตะวันออกเฉียงเหนือ ใกล้ Bashal'Aran จงสังหารมัน", variants = { { "65:110977476:255962638 N 328:1477535727:1473377245 N 81:149535046:459931742", "เพื่อให้ผู้คนและผืนดินของเรารอด บางครั้งก็ต้องจ่ายด้วยสิ่งที่น่าเศร้า {name}\n\nเจ้าหลั่งเลือดข้ารับใช้ของธรรมชาติ สัตว์ป่วยมากมายถูกเจ้าปราบลง ผู้คนแห่ง Auberdine เป็นหนี้บุญคุณเจ้า เพราะความเจ็บปวดของป่าบรรเทาลง แม้เพียงชั่วขณะ\n\nข้ามีงานสุดท้ายให้เจ้า แต่ต้องเตือนไว้ว่าเจ้าต้องฆ่าอีกครั้ง ข้าหวังว่านี่จะเป็นครั้งสุดท้ายที่ต้องรบกวน {name}\n\nDen Mother อยู่ในถ้ำทางตะวันออกเฉียงเหนือ ใกล้ Bashal'Aran จงสังหารมัน" } } },
        progress = { "120:1977321732:483173411 N 1:46:46", "เมื่อ Den Mother ที่ติดเชื้อถูกสังหาร หมีทิสเซิลบ้าคลั่งที่จะเข้าสู่ผืนดินของเราก็จะน้อยลง อย่าเสียเวลาเลย {name}" },
        completion = { "54:1065098642:1138657039 N 227:1157228849:1193884934 N 80:1535256558:1051866234", "เจ้าต่อสู้เพื่อ Auberdine ด้วยความกล้าหาญและเกียรติ {name} ในดินแดนที่สงครามทำลายล้าง ความตายและความสิ้นหวังเป็นเรื่องธรรมดา หลายคนไม่ยอมเผชิญความท้าทายของชีวิตในบ้านใหม่ เลือกหลบในบ้านหรือหนีไปดินแดน Alliance ที่มีกำแพงแข็งแรงกว่า\n\nขอบใจ {name} บางทีอีกไม่นาน เราอาจได้ต่อสู้เคียงข้างกันในฐานะสหายเพื่อต้านศัตรูรายใหม่" },
        objectiveLabels = {
            monster = { ["Den Mother slain"] = "ปราบ แม่หมีเจ้ารัง" },
        },
    },
    [984] = { -- How Big a Threat?
        title = { "17:938605635:1331749522", "ภัยร้ายแรงเพียงใด?" },
        objective = { "78:76702126:1369317705", "ค้นหาค่ายเฟอร์โบลก์ที่ถูกความชั่วร้ายครอบงำใน Darkshore แล้วกลับไปหา Terenthis ใน Auberdine" },
        description = { "436:317846087:1455244501", "พี่น้องของข้าบางคนได้รับการช่วยเหลือจากเฟอร์โบลก์ที่เสื่อมทรามใน Teldrassil ข้าสาบานว่าจะหยุดความโหดร้ายให้ได้ก่อนคนของเราจะบาดเจ็บ... หรือเลวร้ายกว่านั้น\n\nข้าเห็นร่องรอยความแปดเปื้อนบางอย่างใน Darkshore แล้ว แต่ยังไม่พบว่ามันแพร่กว้างเพียงใด คิดว่าควรสืบจากพวกเฟอร์โบลก์ต่อ เจ้าช่วยหาค่ายของพวกมัน แล้วกลับมาบอกหากเห็นสัญญาณความเสื่อมทรามได้ไหม?" },
        progress = { "22:1464096221:380675070 N 1:63:63", "การค้นหาเป็นอย่างไรบ้าง {name}?" },
        completion = { "30:1752786365:529146700 N 110:543104526:1144364445 N 1:46:46", "เป็นข่าวร้ายจริง ๆ {name}\n\nเมื่อพวกเฟอร์โบลก์อยู่ใกล้ Auberdine ขนาดนี้ เราคงต้องเตรียมรับสิ่งที่หลีกเลี่ยงไม่ได้\n\nขอบใจ {name}" },
        steps = { { "27:781389403:1345480373", "ตามหาค่ายเฟอร์โบลก์ที่ถูกความชั่วร้ายครอบงำ" } },
    },
    [985] = { -- How Big a Threat?
        title = { "17:938605635:1331749522", "ภัยร้ายแรงเพียงใด?" },
        objective = { "84:2025246940:1950850088", "ฆ่า Blackwood Pathfinder 8 ตัว และ Windtalker 5 ตัว แล้วกลับไปหา Terenthis ใน Auberdine" },
        description = { "51:600639580:1870090470 N 368:1105813931:1177955726", "เจ้าพิสูจน์ฝีมือการสอดแนมศัตรูแล้ว {name} เจ้าพร้อมต่อสู้กับพวกมันด้วยหรือไม่?\n\nนักผจญภัยบางคนถนัดลอบเร้นและหลบหลีกมากกว่าปะทะตรง ๆ\n\nถ้าคิดว่าทำไหว ค่ายเฟอร์โบลก์ทางใต้ของ Auberdine เป็นภัยใหญ่ที่สุดต่อผู้คนของเราตอนนี้ ที่นั่นมีสมาชิกเผ่า Blackwood อยู่ จงฆ่า Pathfinder 8 ตัว และ Windtalker 5 ตัว แล้วกลับมาหาข้า" },
        progress = { "306:1070309263:110219117", "อย่าลังเลกับสิ่งที่จำเป็นต้องทำ เด็กรุ่นเยาว์ ข้ารู้ว่าการฆ่าสัตว์แห่งป่าชวนให้ขยะแขยงเพียงใด แต่ครั้งนี้จำเป็น ยังไม่มีใครพบวิธีรักษาความแปดเปื้อนที่แพร่ในป่า เราต้องทำทุกอย่างเพื่อยับยั้งมันจนกว่าจะพบทางแก้" },
        completion = { "35:874051790:1413636089 N 191:595807768:1956726490", "ล้างเลือดออกจากเสื้อผ้า {name} และอย่าเศร้ากับสิ่งที่จำเป็นต้องทำ จงขอบคุณที่ช่วยลดภัยต่อผู้คนใน Auberdine ได้ แม้ Darkshore ยังตกอยู่ในอันตรายจาก Fel Moss ก็ตาม" },
        objectiveLabels = {
            monster = { ["Blackwood Pathfinder slain"] = "ปราบ นักเบิกทาง Blackwood", ["Blackwood Windtalker slain"] = "ปราบ ผู้สื่อสารกับสายลม Blackwood" },
        },
    },
    [4811] = { -- The Red Crystal
        title = { "15:2036720543:297408841", "ผลึกสีแดง" },
        objective = { "168:443785983:1714192962", "ไปทางตะวันออกของ Auberdine ค้นหาผลึกสีแดงขนาดใหญ่ตามแนวเขาทางตะวันออกของ Darkshore แล้วกลับไปรายงาน Sentinel Glynda Nal'Shea ใน Auberdine" },
        description = { "496:1270506076:423151873", "มูนคินดุร้ายเดินเพ่นพ่านทางตะวันออกมากขึ้นเรื่อย ๆ ครั้งหนึ่งเราเคยคิดว่าพวกมันอ่อนโยนแทบจะเป็นสัตว์ศักดิ์สิทธิ์ แม้บางคนยังเคารพพวกมัน แต่ความปลอดภัยของ Auberdine ทำให้ข้าต้องมองตามความเป็นจริง\n\nมีรายงานว่ามูนคินถูกดึงดูดไปยังผลึกสีแดงขนาดใหญ่ตามแนวเขาตะวันออกของ Darkshore ไม่มีใครรู้ว่ามันคืออะไร หรือมีอยู่จริงไหม ข้าอยากให้เจ้าไปหาแล้วกลับมารายงานสิ่งที่พบ" },
        progress = { "74:153507002:958292834", "มีอะไรจะรายงานเรื่องผลึกสีแดงบ้าง? มันมีอยู่จริงหรือเปล่า?" },
        completion = { "23:1488059925:2006226507 N 417:1890102611:1831955195", "ผลึกมีจริงสินะ {name}? น่าสนใจ... อย่างไรเจ้าก็ทำงานได้ดี เยี่ยมมาก!\n\nผลึกนี้คืออะไรกันแน่? นี่เป็นเพียงหนึ่งคำถามในคำถามอีกมากมาย แล้วทำไมมูนคินจึงถูกดึงดูดไปหามัน? ผลึกไม่มีพิษภัย หรือมีจุดประสงค์ร้ายกาจซ่อนอยู่?\n\nข้ายังมีคำถามอีกมาก แต่เราต้องตรวจผลึกอย่างใกล้ชิดจึงจะหาคำตอบได้" },
        objectiveLabels = {
            event = { ["Locate the large, red crystal on Darkshore's eastern mountain range"] = "หาผลึกสีแดงขนาดใหญ่บนแนวเขาทางตะวันออกของ Darkshore" },
        },
    },
    [4812] = { -- As Water Cascades
        title = { "17:967729261:1718279630", "เมื่อน้ำไหลริน" },
        objective = { "130:709366222:1958216360", "เติม Empty Water Tube ที่บ่อจันทร์ใน Auberdine แล้วไปตรวจผลึกสีแดงตามแนวเขาตะวันออกของ Darkshore" },
        description = { "458:280857944:1405411108", "นำหลอดเปล่านี้ไปเติมน้ำจากบ่อจันทร์ใน Auberdine เวทมนตร์ที่ทรงพลังเช่นนี้น่าจะบอกเบาะแสเกี่ยวกับเนื้อผลึกได้ เทน้ำลงบนผลึก แล้วปล่อยให้น้ำจัดการส่วนที่เหลือ\n\nแม้ข้าไม่คาดว่าจะเกิดอันตราย ก็อยากให้เจ้าระวัง เหนือขึ้นไปทางตะวันออกคือ Felwood หากผลึกเกี่ยวข้องกับสถานที่นั้นอย่างที่สงสัย มันอาจอันตรายมาก" },
        progress = { "138:1963145580:1352250486", "ผลึกดูแปลกแยกจากป่าไม้ของ Darkshore อย่างสิ้นเชิง เจ้าคิดว่าได้ยินเสียงครางเบามากจากส่วนลึกของมัน" },
        completion = { "257:963602760:476893073", "เจ้ากลับมาถึงผลึกลึกลับอีกครั้ง เมื่อเปิดจุกหลอดน้ำจากบ่อจันทร์แล้ว ก็ค่อย ๆ เทน้ำลงบนยอดผลึก ขณะที่น้ำไหลลงตามโครงผลึก ผิวทึบแสงของมันเริ่มโปร่งใส..." },
        required = { [14339] = { "19:682321803:1497067057", "หลอดน้ำจากบ่อจันทร์" } },
        steps = { { "19:682321803:1497067057", "หลอดน้ำจากบ่อจันทร์" } },
    },
    [4813] = { -- The Fragments Within
        title = { "20:342403813:838198635", "เศษชิ้นส่วนภายใน" },
        objective = { "73:457523023:951190585", "กลับไปรายงานสิ่งที่พบให้ Sentinel Glynda Nal'Shea ใน Auberdine" },
        description = { "403:1188071702:1506433119", "น้ำจากบ่อจันทร์เผยให้เห็นเศษกระดูกเล็ก ๆ หลายชิ้นและขากรรไกรครึ่งหนึ่งฝังอยู่ในผลึก ขากรรไกรนั้นดูคล้ายของสิ่งมีชีวิตรูปร่างมนุษย์ แต่ยืนยันไม่ได้หากไม่ผ่าผลึกออก ซึ่งแม้แต่เวทมนตร์ที่ทรงพลังที่สุดก็แทบทำไม่ได้\n\nเมื่อตรวจสอบเสร็จ สิ่งที่เหลือคือต้องกลับไปรายงาน Sentinel Glynda Nal'Shea ใน Auberdine" },
        completion = { "447:1654576461:1288144763 N 1:46:46", "แม้เราจะรู้เรื่องผลึกนี้มากขึ้น แต่กลับมีคำถามที่ยังไร้คำตอบเพิ่มอีก!\n\nข้าจะนำข้อมูลที่เจ้าพบไปแจ้งสภาใน Auberdine บางทีพวกเขาอาจรู้ว่าควรทำอย่างไรต่อ หากมีอะไรที่ทำได้ล่ะนะ ตอนนี้ภัยยังอยู่ไกลทางตะวันออกพอที่จะไม่เป็นอันตรายกับเรา\n\nส่วนเจ้า รับสิ่งนี้ไว้ ถือเป็นรางวัลสำหรับงานที่ทำได้ดี {name}" },
    },
    [954] = { -- Bashal'Aran
        title = { "11:2101145969:2014192125", "บาชาลอารัน" },
        objective = { "69:1871076394:1312305447", "ค้นหาต้นกำเนิดรัศมีสีฟ้าประหลาดในซาก Bashal'Aran" },
        description = { "483:1403552684:1705522166", "ซาก Bashal'Aran ทางตะวันออกถูกสมุนปีศาจยึดครอง ภูตกับซาเทียร์ที่เข้ามาอยู่ดูดกินพลังเวทของบริเวณนี้ ยิ่งสัมผัสพลังนานก็ยิ่งแข็งแกร่ง\n\nแต่ข้าสังเกตว่ามีศาลแห่งหนึ่งที่พวกมันไม่ยอมเข้าใกล้ ทางตะวันตกของซากเมือง บนชะง่อนผาเตี้ย ๆ มีรัศมีสีฟ้าประหลาดแผ่อยู่... ต้องมีเหตุผลที่พวกปีศาจหลีกเลี่ยง\n\nข้าอยากให้เจ้าไปตรวจดู" },
        completion = { "71:1931825051:1899881071 R 332:1742887321:548023813", "อา... อะไรทำให้ข้าได้รับเกียรติพิเศษถึงเพียงนี้ มีชาว{race} อย่างเจ้ามาเป็นเพื่อน ช่างบอกอะไรได้มากเกี่ยวกับเพื่อนในยามนี้ของข้า โดยมิได้ลบหลู่เจ้าบ้านอย่างเกรลล์และซาเทียร์ผู้สูงส่ง การมาของเจ้าถึงนับเป็นความเปลี่ยนแปลงที่ดีขึ้น\n\nแต่อย่าให้ลิ้นไร้มารยาทของข้าไล่เจ้าไปเสียก่อน หลายปีแล้ว... หรือหลายสิบปีทีเดียว ที่ข้าไม่ได้พบเพื่อนผู้มีอารยธรรม" },
    },
    [955] = { -- Bashal'Aran
        title = { "11:2101145969:2014192125", "บาชาลอารัน" },
        objective = { "53:216161731:1309017693", "หา Grell Earring 8 ชิ้นให้ Asterion ใน Bashal'Aran" },
        description = { "498:1768139574:776611926", "ถ้าเล่าชีวิตข้าให้ฟัง ข้าว่าความอดทนของเจ้าคงหมดเสียก่อน เอาเป็นว่าชีวิตข้ายาวนานและเจ็บปวด ร่างวิญญาณนี้อาจเป็นความทรมานที่เลวร้ายที่สุด\n\nข้าถูกเวทมนตร์กักขังที่นี่ แม้คำพูดจะดูไม่น่าเชื่อ แต่หากช่วยหาต้นเหตุของการจองจำ ข้าจะขอบคุณจนหาคำพูดไม่ได้ มีตราผนึกพันธนาการข้าอยู่ หากตรวจต่างหูของภูตและเกรลล์ ข้าอาจพบร่องรอยของมัน" },
        progress = { "274:1337224475:453319425", "เมื่อได้ต่างหู ข้าจะร่ายเวทค้นหาตราผนึกที่จองจำข้า ตลอดหลายศตวรรษ ข้าเฝ้าคิดถึงอิสรภาพที่จะได้เมื่อทำลายมัน... บางทีเวลาเหล่านั้นอาจทำร้ายจิตใจข้าเกินกว่าจะฟื้นคืนได้..." },
        completion = { "262:1665373868:1725967201", "เป็นจริงด้วย... เกรลล์แห่ง Bashal'Aran ไม่มีสิ่งที่ข้าตามหา... แต่พวกมันเพิ่งสัมผัสมันมา คำว่าเพิ่ง ข้าหมายถึงในช่วงเวลาของเจ้า สำหรับข้า อดีตอันใกล้อาจยาวนานถึงอีกยุคหนึ่ง..." },
        required = { [5336] = { "13:2073449220:965632092", "ต่างหู Grell" } },
        steps = { { "13:2073449220:965632092", "ต่างหู Grell" } },
    },
    [956] = { -- Bashal'Aran
        title = { "11:2101145969:2014192125", "บาชาลอารัน" },
        objective = { "74:859490272:1532334649", "นำ Ancient Moonstone Seal ไปให้ Asterion ใน Bashal'Aran" },
        description = { "231:893158283:684167898 N 159:811223883:500213666", "หากพวกเกรลล์เพิ่งเข้าใกล้ตราผนึกแห่งคุกนิรันดร์ของข้า ข้าคงรู้เหตุผลแล้ว มันต้องตกอยู่ในมือซาเทียร์ที่นำพวกมันอยู่แน่\n\nข้ามั่นใจเหลือเกิน {name} ซาเทียร์ตนหนึ่งต้องมีมัน หากเจ้าหามาได้ ข้าก็ใกล้จะพ้นกรงขังจนคงอดหลั่งน้ำตาไม่ได้" },
        progress = { "62:406777921:827472911 N 264:117796420:764889825", "เสาของศาลนี้เป็นดั่งซี่กรงสำหรับข้า {name} กำลังที่เหลือทำลายมันไม่ได้ เวทมนตร์ที่มีก็ไม่อาจทำลาย...\n\nข้าจ้องมองมันนานกว่าพันปี เฝ้าสงสัยว่าหากอยู่จนศิลาผุพัง ข้าจะเป็นอิสระหรือไม่? หรือจะยังมีซี่กรงที่มองไม่เห็นกักขังข้าไว้..." },
        completion = { "122:1314400195:1193851430 N 81:1522268900:1035011399", "ข้า... แทบไม่อยากเชื่อว่าสิ่งในมือนี้กักขังข้ามานานนัก อย่าเสียเวลาเลย {name} เมื่อตราผนึกถูกทำลาย ข้าอาจเดินอย่างอิสระในผืนป่าได้อีกครั้ง" },
        required = { [5338] = { "22:769529802:1265218523", "ตราผนึกหินจันทร์โบราณ" } },
        steps = { { "22:769529802:1265218523", "ตราผนึกหินจันทร์โบราณ" } },
    },
    [957] = { -- Bashal'Aran
        title = { "11:2101145969:2014192125", "บาชาลอารัน" },
        objective = { "110:477987015:1159328395", "ทำลาย Ancient Moonstone Seal ที่เปลวไฟโบราณใน Ameth'Aran แล้วกลับไปหา Asterion ใน Bashal'Aran" },
        description = { "288:528984795:385349142 N 3:3050122:795478", "ตราผนึกที่สร้างคุกของข้าเป็นฝีมือหนึ่งในไฮบอร์นผู้ทรงพลังที่สุด ใน Ameth'Aran ซากเมืองคู่แฝดทางใต้ ยังมีเปลวไฟโบราณสีฟ้าลุกอยู่จนวันนี้ ตราผนึกนี้ถูกทำลายในเปลวไฟนั้นได้\n\nระวังตัวในซากเมืองด้วย {name}..." },
        progress = { "10:1273193168:1371476494 N 167:92355821:882637999", "พูดตามตรง {name} ข้ากลัว... กลัวว่าการมาของเจ้าและทุกอย่างนี้เป็นเพียงภาพหลอนจากจิตที่วิปลาส เจ้าพอเข้าใจความทรมานนี้ไหม? ข้า... ขอร้อง รีบไปเถอะ" },
        completion = { "12:321833859:217141589 N 379:695326314:1026749573", "ข้าเป็นอิสระแล้ว {name}! ข้าจะได้เห็นความเปลี่ยนแปลงของโลกด้วยตาตนเองเสียที ที่ผ่านมาได้รู้เพียงเศษเสี้ยวเท่านั้น ครั้งสุดท้ายที่ข้าเดินอย่างอิสระ Well of Eternity ยังอยู่ และพวกไฮบอร์นยังเข้าเฝ้า Azshara ราชินีอันเป็นที่รักของเรา\n\nข้าสัมผัสได้ว่าผู้จองจำ อดีตนายของข้า Athrikus ยังมีชีวิตอยู่... ความสิ้นหวังของข้ากำลังแปรเป็นความคิดแก้แค้นแล้ว" },
        steps = { { "37:474750831:2078122780", "ทำลายตราผนึกที่เปลวไฟโบราณ" } },
    },
    [5924] = { -- Heeding the Call
        title = { "16:1185260992:259476408", "ขานรับเสียงเรียก" },
        objective = { "68:1126811676:987074176", "ไปคุยกับ Mathrengyl Bearwalker ใน Cenarion Enclave ของ Darnassus" },
        description = { "472:1060943100:897948186", "ขอเวลาสักครู่ สหาย...\n\nข้าได้ข่าวว่า Mathrengyl Bearwalker ฝากคำมาว่าอยากพบเจ้า ดูเหมือนการฝึกดรูอิดของเจ้ากำลังจะก้าวสู่ขั้นใหม่ และเขาจะฝึกให้ด้วยตัวเอง Mathrengyl เป็นผู้ช่วยใกล้ชิดของอัครดรูอิด และเป็นหนึ่งในดรูอิดที่รอบรู้และน่าเคารพที่สุดใน Teldrassil\n\nเขาอยู่ใน Cenarion Enclave ของ Darnassus บนชั้นสองของต้นไม้ที่ Fandral Staghelm พำนัก" },
        completion = { "47:608153914:1342807793 C 418:1421579562:2003121929", "ดีใจที่เจ้ามาถึงที่นี่ในวันนี้ ดรูอิดรุ่นเยาว์ ถึงเวลาที่เจ้าจะก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิม\n\nในตัวลูกหลานของ Cenarius ทุกคนมีเสียงเรียกให้รับใช้ธรรมชาติ สัตว์และพืชเป็นทั้งสหายและผู้ที่เราเฝ้าดูแล เราเลือกอุทิศชีวิตเพื่อรักษาสมดุล ทั้งเพื่อพวกเขาและตัวเราเอง ก้าวแรกของเจ้าคือเรียนรู้วิถีแห่งหมี และเข้าใจความแข็งแกร่งของกายและใจ\n\nเตรียมตัวให้พร้อม!" },
    },
    [6073] = { -- The Hunter's Path
        title = { "17:1808304966:1557963252", "วิถีแห่งพราน" },
        objective = { "31:696802362:1206943833", "ไปคุยกับ Dazalar ใน Dolanaar" },
        description = { "204:961423173:1296812386", "สวัสดี พรานรุ่นเยาว์ ดูท่าเจ้าจะชำนาญพอควบคุมสัตว์ป่าและฝึกมันให้เป็นสหายได้แล้ว\n\nจงไปหา Dazalar ใน Dolanaar เขาจะชี้ทางให้เจ้าได้มีสัตว์เลี้ยงเป็นของตนเอง" },
        completion = { "17:576516780:98697445 C 1:46:46", "ใช่ ถึงเวลาแล้ว {class}", variants = { { "31:1331418527:1474396752", "ใช่ ถึงเวลาฝึกเจ้าแล้ว..." } } },
    },
