    [729] = { -- The Absent Minded Prospector
        title = { "28:1033233583:1622671036", "นักสำรวจขี้ลืม" },
        objective = { "47:1951480523:17204545", "เดินทางลงใต้ไปตรวจดู Prospector Remtravel" },
        description = { "500:431798012:195334179", "เป็นเกียรติอย่างยิ่งที่อาจารย์ Greywhisker ให้ข้าทำงานภายใต้การชี้แนะของ Prospector Remtravel ผู้ยิ่งใหญ่ ทุกคนในสถาบันที่ Ironforge ต่างรู้ถึงการค้นพบของเขา\n\nแต่ท่านนักสำรวจค่อนข้าง... เอ่อ... ไม่ค่อยรับรู้สิ่งรอบตัว\n\nเราพบร่องรอยอารยธรรมที่ยิ่งใหญ่ แล้วโกเลมน่ากลัวก็ผุดจากพื้นเข้ายึดแหล่งขุดค้น Remtravel ดูเหมือนไม่ทันสังเกต ข้าจึงวิ่งกลับ Auberdine ขอความช่วยเหลือ\n\nช่วยลงใต้ไปดูว่าเขาปลอดภัยด้วย!" },
        completion = { "487:1897927115:677725336", "Hollee เจ้าเองหรือ? ข้าต้องการคนช่วยสกัดหิน ส่งแปรงปัดหินมาที เหมือนข้าเห็นอะไรบางอย่าง\n\nเฮ้ เจ้าไม่ใช่ Hollee นี่! เห็นแปรงข้าบ้างไหม?\n\nช่างมันก่อน! ข้าสัญญาจะส่งฟอสซิลลึกลับที่พบให้สมาคม Hollee ไปไหน?\n\nงานเยอะเหลือเกิน! แล้วฟอสซิลลึกลับอยู่ไหน... แปรงด้วย... แล้วก็ Hollee...\n\nว่าแต่เจ้าเป็นใคร... ไม่สำคัญหรอก ขอแค่มาช่วย\n\nบอกข้าเมื่อพร้อมเริ่มหา" },
    },
    [731] = { -- The Absent Minded Prospector
        title = { "28:1033233583:1622671036", "นักสำรวจขี้ลืม" },
        objective = { "120:1544466253:763564898", "คุ้มกัน Prospector Remtravel ระหว่างค้นหาฟอสซิลลึกลับ แล้วกลับไปหา Archaeologist Hollee ใน Auberdine" },
        description = { "442:1363329294:1048657634", "เอาล่ะ Hollee... อ้อ จริงสิ เจ้าไม่ใช่ Hollee แล้ว Hollee อยู่ไหน?\n\nช่างเถอะ เราต้องหาแปรงปัดหิน... หมายถึงฟอสซิลลึกลับ! ต้องหาฟอสซิลนั้นให้เจอ Explorers' League ใน Darnassus คงอยากเห็นว่าข้าทำอะไรอยู่\n\nบอกเมื่อพร้อม แล้วเราไปหาแปรง... หมายถึงฟอสซิล! เราจะหาหลักฐานเป็นลายลักษณ์อักษรให้สมาคมพอใจ\n\nพร้อมหรือยังล่ะ?" },
        progress = { "24:653592887:969103747", "ท่านนักสำรวจยังมีชีวิตอยู่ไหม?" },
        completion = { "175:2045498916:1779771047", "ขอบคุณดวงดาวที่ Prospector Remtravel ปลอดภัย! ข้าบอกแล้วว่าเขาขี้ลืม ไม่อยากเชื่อว่าเขายังยืนยันจะอยู่ที่นั่นทั้งที่มีสัตว์ประหลาดน่ากลัววนเวียนเต็มไปหมด" },
        objectiveLabels = {
            event = { ["Escort Prospector Remtravel"] = "คุ้มกัน Prospector Remtravel" },
        },
    },
    [741] = { -- The Absent Minded Prospector
        title = { "28:1033233583:1622671036", "นักสำรวจขี้ลืม" },
        objective = { "75:1760455670:591564884", "นำฟอสซิลลึกลับไปให้ Chief Archaeologist Greywhisker ใน Darnassus" },
        description = { "149:18419963:364409122 N 80:1648277286:1142409633", "ท่านนักสำรวจอยากส่งฟอสซิลลึกลับให้ Explorers' League ใน Darnassus หรือ? ข้าไม่สบายใจที่จะออกจาก Darkshore โดยไม่มีเขา\n\nนี่ {name} ช่วยนำฟอสซิลลึกลับไปให้ Chief Archaeologist Greywhisker ใน Darnassus" },
        progress = { "23:845437671:750047252 R 1:63:63", "มีอะไรให้ข้าช่วยหรือ ชาว{race}?" },
        completion = { "64:744671866:1452194054", "โอ้! ต้องยกให้ Prospector Remtravel จริง ๆ ที่ค้นพบของเช่นนี้!" },
        required = { [4654] = { "17:1075761373:1057076536", "ซากดึกดำบรรพ์ลึกลับ" } },
        steps = { { "17:1075761373:1057076536", "ซากดึกดำบรรพ์ลึกลับ" } },
    },
    [942] = { -- The Absent Minded Prospector
        title = { "28:1033233583:1622671036", "นักสำรวจขี้ลืม" },
        objective = { "73:1736328237:1215825327", "นำฟอสซิลลึกลับไปให้ Archaeologist Flagongut ใน Menethil Harbor" },
        description = { "503:529577680:423947832", "ฟอสซิลนี้คล้ายของที่ข้าเคยเห็นใน Ironforge อย่างน่าทึ่ง นักโบราณคดีชื่อ Flagongut นำมันมาในงานประชุมประจำปีของ Explorers' League เขาเชื่อว่ามันซ่อนพลังที่ปลดปล่อยได้ด้วยวิธีใดวิธีหนึ่ง\n\nข่าวล่าสุดบอกว่า Flagongut พักอยู่ใน Deepwater Tavern ที่ Menethil Harbor รอคนคุ้มกันไป Whelgar Excavation Site ไปหาแล้วให้เขาดูฟอสซิลของ Remtravel บางทีเขาอาจเผยความลับในอดีตได้\n\nเรือไป Menethil ออกจาก Auberdine" },
        progress = { "26:752848517:231651727", "มีอะไรอยู่ตรงนั้น สหาย?" },
        completion = { "85:1489556805:1651269040", "โอ้! บอกว่าของนี้มาจาก Kalimdor ดินแดนไกลโพ้นหรือ?\n\nน่าทึ่ง! น่าทึ่งจริง ๆ!" },
        required = { [4654] = { "17:1075761373:1057076536", "ซากดึกดำบรรพ์ลึกลับ" } },
        steps = { { "17:1075761373:1057076536", "ซากดึกดำบรรพ์ลึกลับ" } },
    },
    [943] = { -- The Absent Minded Prospector
        title = { "28:1033233583:1622671036", "นักสำรวจขี้ลืม" },
        objective = { "107:249450518:1589422765", "นำ Stone of Relu และ Flagongut's Fossil ไปให้ Archaeologist Flagongut ใน Menethil Harbor" },
        description = { "482:931298789:137465916", "ตอนนี้ Prospector Whelgar เก็บฟอสซิลชิ้นเดิมไว้ที่แหล่งขุดค้นใน Wetlands เมื่อข้าพบ Stone of Relu ข้าเชื่อว่ามันเป็นกุญแจไขความลับของฟอสซิล\n\nระหว่างเดินทางไปพบ Whelgar ข้าถูกแรปเตอร์โจมตีและทำวัตถุโบราณหาย ไม่รู้ตัวไหนกลืนมันไป แต่หากเจ้าหากลับมาได้ ข้าจะปลดปล่อยพลังของวัตถุเหล่านี้ได้\n\nนำทั้ง Stone of Relu และฟอสซิลชิ้นเดิมที่เขาเก็บไว้มาให้ข้า" },
        progress = { "127:1199406459:1157565745 N 1:46:46", "ด้วย Stone of Relu ข้าจะเผยความลับที่ซ่อนในฟอสซิลของข้าและฟอสซิลของ Remtravel จาก Darkshore ได้ {name}" },
        completion = { "16:959884130:63492255 N 74:886431481:790560789", "เยี่ยมที่สุด {name}!\n\nทีนี้ลองดูว่าข้าจะใช้ศิลาไขพลังของฟอสซิลได้หรือไม่" },
        required = { [5233] = { "13:680127705:884053299", "ศิลาแห่ง Relu" }, [5234] = { "18:881804790:473962527", "ซากดึกดำบรรพ์ของ Flagongut" } },
        steps = { { "13:680127705:884053299", "ศิลาแห่ง Relu" }, { "18:881804790:473962527", "ซากดึกดำบรรพ์ของ Flagongut" } },
    },
    [945] = { -- Therylune's Escape
        title = { "18:403608636:1527518070", "การหลบหนีของเธริลูน" },
        objective = { "91:140705512:1565079857", "ช่วย Therylune หลบหนี แล้วแจ้ง Therysil ที่ Shrine of Aessina ว่านางปลอดภัย" },
        description = { "270:600362638:1088686399", "ช่วยด้วย!\n\nข้าเดินเล่นแถว Master's Glaive แล้วถูกสาวกลัทธิสกปรกพวกนี้ล้อม โชคดีที่ข้าซ่อนตัวเก่ง!\n\nช่วยพาข้าออกไปที แล้วฝากบอก Therysil พี่น้องของข้าว่าข้าปลอดภัย นางอยู่ทางใต้ใน Ashenvale ที่ Shrine of Aessina" },
        completion = { "175:338998159:1364129495 N 57:362577315:577993116", "พี่น้องข้าไปอยู่ที่ไหนนะ?? Therylune ไม่กลัวเปื้อนก็จริง แต่ถึงอย่างนั้น! เดินไปไกลเหลือเกิน แถม Master's Glaive ก็เป็นสถานที่อัปมงคล...\n\nขอบใจ {name} ดีจริงที่มาบอกว่านางปลอดภัย" },
        objectiveLabels = {
            event = { ["Escort Therylune away from the Master's Glaive"] = "คุ้มกัน Therylune ออกจาก Master's Glaive" },
        },
    },
    [965] = { -- The Tower of Althalaxx
        title = { "22:1686023837:976185767", "หอคอยอัลธาแลกซ์" },
        objective = { "68:1473162516:1777350245", "ไปหา Balthule Shadowstrike ใกล้ Tower of Althalaxx ใน Darkshore" },
        description = { "12:261722808:917055563 R 399:1890528952:161360267", "สวัสดี ชาว{race} รุ่นเยาว์ ข้าคือ Elissa Starbreeze มีหน้าที่ปกป้อง Auberdine จากอันตราย\n\nข้าส่ง Balthule Shadowstrike ไปสังเกตเหตุการณ์ประหลาดรอบ Tower of Althalaxx ทางตะวันออกเฉียงเหนือ\n\nเลยเวลาที่เขาควรกลับแล้ว ข้ากังวลว่าอาจพบอันตรายที่คาดไม่ถึงในป่า จะขอบคุณมากหากเจ้าช่วยไปตามดูว่าเขาปลอดภัย" },
        completion = { "134:1352669225:970197386", "Elissa ส่งเจ้ามาหรือ? ถ้าเช่นนั้นก็นับว่าเป็นข่าวดี ข้ามีเรื่องน่ากังวลจะแจ้งนาง แต่ไม่มีหนทางส่งข่าว" },
    },
    [966] = { -- The Tower of Althalaxx
        title = { "22:1686023837:976185767", "หอคอยอัลธาแลกซ์" },
        objective = { "80:1777772128:1415748206", "เก็บ Worn Parchment 4 ชิ้นให้ Balthule Shadowstrike ใกล้ Tower of Althalaxx" },
        description = { "504:2104792017:2042162807", "มีวอร์ล็อกกลุ่มหนึ่งยึดพื้นที่ทั้งรอบและในหอคอย ข้าคงกลับ Auberdine รายงาน Elissa ไปแล้ว แต่กลัวพลาดสิ่งสำคัญระหว่างไม่อยู่\n\nDelgren สงสัยว่าพวกมันอาจมาชุมนุมที่หอคอย แต่ไม่รู้เหตุผล\n\nเศษกระดาษที่วอร์ล็อกพกบางชิ้นตกมาถึงมือข้าแล้ว แต่ต้องมีเพิ่มจึงจะปะติดปะต่อได้ ข้าขอเตือนว่าอย่าเข้าในหอคอย วอร์ล็อกข้างในแข็งแกร่งกว่ามาก!" },
        progress = { "127:1212355191:917670288", "พบม้วนเอกสารเพิ่มหรือยัง? ถ้าได้มา ข้าคงเห็นภาพรวมของลัทธิชัดขึ้น" },
        completion = { "13:1380265947:260987756 N 317:787097914:283108804", "ขอบใจมาก {name} นี่น่าจะเผยเรื่องการชุมนุมของวอร์ล็อก...\n\nอืม... ลัทธิ Dark Strand... ข้าไม่เคยได้ยินมาก่อน เมื่อไม่รู้ประวัติ ก็แทบเดาแผนการไม่ได้\n\nชักช้าไม่ได้แล้ว ต้องส่งคำเตือนให้ Delgren ทันที" },
        required = { [5348] = { "14:377268324:534753641", "แผ่นหนังเก่าคร่ำคร่า" } },
        steps = { { "14:377268324:534753641", "แผ่นหนังเก่าคร่ำคร่า" } },
    },
    [967] = { -- The Tower of Althalaxx
        title = { "22:1686023837:976185767", "หอคอยอัลธาแลกซ์" },
        objective = { "70:1090454734:379172691", "นำจดหมายของ Balthule ไปให้ Delgren the Purifier ใน Ashenvale Forest" },
        description = { "423:1691146821:609071039", "อาจารย์ของข้า Delgren the Purifier เป็นพาลาดินที่กรุณาช่วยปกป้องป่าของเราจากปีศาจและอันเดด เขาสอนข้ามากมายเรื่องแสงศักดิ์สิทธิ์และศิลปะการต่อสู้\n\nDelgren ต้องรู้เรื่องการเคลื่อนไหวของลัทธิทันที\n\nเจ้าจะพบเขาลงไปทางใต้ไกลจากที่นี่ ที่ Maestra's Post ใน Ashenvale Forest รีบไป ข้าเกรงว่าภัยจาก Dark Strand เพิ่มขึ้นทุกชั่วโมง" },
        progress = { "32:905777340:1195040726 C 1:63:63", "มีธุระอะไรกับข้าหรือ {class}?" },
        completion = { "400:715746219:1871588284", "ขอพูดหน่อยนะ เจ้าดูมีอาวุธครบมือเกินคนส่งสารอยู่สักหน่อย ว่าไหม? คงเพราะ Balthule อยากให้จดหมายมาถึงมือแน่นอน มาดูว่าเขาเขียนอะไร...\n\nเป็นข่าวน่าวิตก เมื่อพบอันเดดหรือปีศาจ ข้าจะช่วย Sentinel กำจัดมัน\n\nแรกทีเดียวข้าไม่ชินกับธรรมเนียมไนต์เอลฟ์ แต่ตอนนี้เคารพพวกเขาในฐานะพันธมิตรมาก" },
        required = { [5354] = { "17:1398404761:385437665", "จดหมายถึง Delgren" } },
        steps = { { "17:1398404761:385437665", "จดหมายถึง Delgren" } },
    },
    [968] = { -- The Powers Below
        title = { "16:896025037:1693670976", "อำนาจเบื้องล่าง" },
        objective = { "85:956305992:1316650046", "นำหนังสือ The Powers Below ไปให้ Gerrig Bonegrip ใน Forlorn Cavern ที่ Ironforge" },
        description = { "491:1416294478:2075024291", "แม้หนังสือจะสึกหรอและเป็นรอยขีดข่วนมาก แต่ยังอ่านชื่อบนปกได้ว่า\n\nอำนาจเบื้องล่าง\n\nข้างในเป็นรายชื่อนามที่อ่านออกเสียงไม่ได้ พร้อมสมญาน่าหวาดหวั่น วิธีบูชา และเครื่องสังเวยที่โปรดปราน... หลายอย่างเป็นสิ่งมีชีวิตรูปร่างมนุษย์ที่ยังมีชีวิต\n\nด้านในปกเขียนว่า “ร้านอักษรรูนและคำสาปของ Bonegrip, Forlorn Cavern, Ironforge เจ้าของ Gerrig Bonegrip”\n\nถ้าเขาขายหนังสือแบบนี้ บางทีอาจยอมรับซื้อเล่มนี้คืน" },
        progress = { { "50:926412669:974201332", "52:26740118:2024026867" }, "สวัสดี ท่านผู้มาเยือน\n\nสนใจตำราของข้าสักเล่มไหม?" },
        completion = { "435:196315340:112764821", "อา หนังสือ The Powers Below น่าสนใจทีเดียว และบางคนอาจใช้ประโยชน์ได้...\n\nแต่เล่มนี้สภาพแย่ ดูสิ! เกือบทุกหน้ามีข้อความจดข้างกระดาษ!\n\nอืม... ข้าจำเล่มนี้ได้ ขายให้ Bolgar เมื่อปีก่อน เจ้าเป็น... เพื่อนเขาหรือ? ใช่ ข้าก็คิดเช่นนั้น เจ้ามีไฟในแววตาเหมือนกัน!\n\nเพื่อนของ Bolgar ก็ถือเป็นเพื่อนข้า แล้วเราย่อมดูแลพวกเดียวกัน จริงไหม?" },
        required = { [5352] = { "22:168652481:1952368317", "หนังสือ: พลังเบื้องล่าง" } },
        steps = { { "22:168652481:1952368317", "หนังสือ: พลังเบื้องล่าง" } },
    },
    [970] = { -- The Tower of Althalaxx
        title = { "22:1686023837:976185767", "หอคอยอัลธาแลกซ์" },
        objective = { "83:1911410137:1422072568", "นำ Glowing Soul Gem กลับไปให้ Delgren the Purifier ที่ Maestra's Post" },
        description = { "352:1288522879:596966122", "จดหมายของ Balthule เป็นข่าวร้าย ลัทธิ Dark Strand เป็นหนามยอกอกที่ต้องถอน ข้าจัดการพวกมันบางส่วนทางตะวันออกเฉียงเหนือที่ Ordil'Aran อยู่ หนึ่งในนั้นมีอัญมณีวิญญาณที่ข้าเชื่อว่าเก็บความลับแห่งพลังของลัทธิ\n\nนำมาให้ข้า แล้วข้าจะไขความลับที่ซ่อนอยู่ได้" },
        progress = { "32:23006521:214900439", "ได้อัญมณีวิญญาณนั้นมาแล้วหรือ?" },
        completion = { "88:1171174720:178887497", "อืม เวทมืดบางอย่างอาบอยู่บนศิลาวิญญาณ มาดูกันว่าอะไรติดอยู่ข้างในดีไหม?" },
        required = { [5366] = { "16:987922993:2145766658", "อัญมณีวิญญาณเรืองแสง" } },
        steps = { { "16:987922993:2145766658", "อัญมณีวิญญาณเรืองแสง" } },
    },
    [973] = { -- The Tower of Althalaxx
        title = { "22:1686023837:976185767", "หอคอยอัลธาแลกซ์" },
        objective = { "72:1049705950:1406810438", "นำ Ilkrud Magthrull's Tome ไปให้ Delgren the Purifier ที่ Maestra's Post" },
        description = { "295:886733286:697882216", "Ilkrud Magthrull ข้ารู้จักเขา เป็นวอร์ล็อกออร์คทรงพลังที่พำนักใน Fire Scar Shrine สถานที่ชั่วร้ายทางตะวันตกเฉียงใต้ของ Ashenvale\n\nที่ผ่านมาเขาเป็นแค่ตัวกวนใจ ข้าจึงยังไม่ลงมือ แต่ดูเหมือนเวลาของเขาจะมาถึงแล้ว" },
        progress = { "26:973222571:2115540656 N 15:1152089262:1963575486", "เจ้าดูขวัญเสียอยู่หน่อย {name} สบายดีหรือ?" },
        completion = { "36:109325570:301124247 N 143:2085069569:772530028", "วันนี้เจ้าทำสิ่งยิ่งใหญ่ {name} ควรภูมิใจที่เผชิญวอร์ล็อกทรงพลังขนาดนั้นได้\n\nทีนี้มาดูว่าจะเรียนรู้อะไรจากบันทึกของ Ilkrud ได้บ้าง" },
        required = { [5533] = { "23:585004470:1947840700", "คัมภีร์ของ Ilkrud Magthrull" } },
        steps = { { "23:585004470:1947840700", "คัมภีร์ของ Ilkrud Magthrull" } },
    },
    [981] = { -- The Tower of Althalaxx
        title = { "22:1686023837:976185767", "หอคอยอัลธาแลกซ์" },
        objective = { "47:576118734:243025712", "ไปคุยกับ Delgren the Purifier ที่ Maestra's Post" },
        description = { "207:1698041675:1194796261", "จากงานทั้งหมดที่ทำ เจ้าสมควรได้รับรางวัลอย่างงาม กลับไปหา Delgren บอกเขาว่า Athrikus Narassin สิ้นด้วยมือเจ้าแล้ว และลัทธิ Dark Strand ถูกปราบจนแตกกระเจิง" },
        completion = { "36:1855693769:2024141186 N 119:261035702:1118082026 N 23:267436749:560622661", "ข้ารู้อยู่แล้วว่าเจ้าทำได้ {name}\n\nข้าสัมผัสได้ว่าวีรกรรมยิ่งใหญ่รอเจ้าอยู่ และเจ้าจะแก้ไขความอยุติธรรมมากมายที่คุกคามดินแดนของเรา รับพรของข้าและของขวัญนี้ไว้ {name}" },
    },
    [986] = { -- A Lost Master
        title = { "13:1154828014:1641568078", "เจ้านายที่หายไป" },
        objective = { "72:467669846:1116964155", "นำ Fine Moonstalker Pelt 5 ผืนกลับไปให้ Terenthis ใน Auberdine" },
        description = { "N 468:1555679077:922318223", "{name} ฝีมือของเจ้าช่วยงานข้ามาแล้ว ขอรบกวนอีกครั้งให้ช่วย Grimclaw กับ Volcor เจ้านายของมันได้ไหม? ข้าทำเสื้อคลุมเวทให้เจ้าเดินผ่านสัตว์ใน Darkshore โดยไม่ถูกรบกวนระหว่างตามหาเขาได้\n\nต้องใช้หนัง Moonstalker เนื้อดีห้าผืนจากตัวผู้พ่อพันธุ์หรือตัวเมียจ่าฝูงจึงจะพอทำเสื้อคลุม พบพวกเสือนี้ใกล้ Wildbend River ทางใต้ หรือไกลลงไปใกล้ Ashenvale" },
        progress = { "91:824379106:1492956390", "ข้าคงไม่สบายใจที่จะให้เจ้าตามหา Volcor ก่อนทำเสื้อคลุมให้เสร็จ" },
        completion = { "22:1465595043:356124885 N 308:1674796537:693400476", "ใช้ได้ทีเดียว {name} ข้าจะลงมือทำเสื้อคลุมทันที\n\nให้เวลาสักครู่ แล้วค่อยกลับมา\n\nอีกอย่าง หลังใช้มนตร์ของเสื้อคลุม เจ้าจะทำสิ่งต่าง ๆ กับผู้อื่นได้จำกัด ถ้าเลี่ยงได้ ให้ทำเพียงพูดคุย การทำมากกว่านั้นอาจลบภาพลวงตา" },
        required = { [5386] = { "21:1188753749:1830914425", "หนังมูนสตอล์กเกอร์ชั้นดี" } },
        steps = { { "21:1188753749:1830914425", "หนังมูนสตอล์กเกอร์ชั้นดี" } },
    },
    [993] = { -- A Lost Master
        title = { "13:1154828014:1641568078", "เจ้านายที่หายไป" },
        objective = { "70:1882348133:17411226", "ตามหา Volcor ใน Darkshore แล้วมอบ Enchanted Moonstalker Cloak ให้เขา" },
        description = { "23:1961178887:320637810 N 457:881172183:1206353044", "เสื้อคลุมเสร็จแล้ว {name} ถึงเวลาหา Volcor หวังว่าเราจะทัน\n\nเมื่อเรียกใช้ เวทจะอยู่ได้ไม่นาน อาจสักห้านาที เจ้าต้องเลือกใช้ให้ถูกเวลา ข้าแนะนำให้รอจนพบ Grimclaw\n\nถ้าสิ่งที่มันบอกเป็นจริง เจ้านายอยู่ในถ้ำทางใต้ Grimclaw จะรอริมถนน เมื่อเจอมันให้โบกมือส่งสัญญาณ แล้วมันจะชี้ทางไปหาเจ้านาย" },
        completion = { "116:496281255:465949835 N 115:57560748:1998902888", "เยี่ยม! Terenthis หาคนมาช่วยข้าแล้ว\n\nดูสิ เสื้อคลุม Moonstalker... <ไอ> โอ๊ย... เจ็บจัง ขอบใจ {name}\n\nพวกเฟอร์โบลก์ทำข้าบาดเจ็บก่อนหนีรอดมาได้ รอสักครู่ แล้วข้าคงคุยต่อไหว" },
        required = { [5387] = { "27:1142501237:868427968", "ผ้าคลุมมูนสตอล์กเกอร์ลงมนตร์" } },
        steps = { { "27:1142501237:868427968", "ผ้าคลุมมูนสตอล์กเกอร์ลงมนตร์" } },
    },
    [994] = { -- Escape Through Force
        title = { "20:290187976:8022001", "ฝ่ากำลังหลบหนี" },
        objective = { "78:188728037:828044669", "คุ้มกัน Volcor จนถึงถนน แล้วไปคุยกับ Terenthis ใน Auberdine" },
        description = { "11:1140617183:1872504242 N 279:1599260740:1341501910", "ได้เลย {name} งั้นใช้กำลัง พอเจ้าพร้อมก็ออกจากที่นี่ เราจะฝ่าไปถึงถนน Grimclaw น่าจะยังอยู่ เมื่อถึงแล้วค่อยแยกกัน\n\nTerenthis คงอยากฟังเรื่องจากเจ้าโดยเร็ว เมื่อหนีรอดแล้วให้ไป Auberdine" },
        completion = { "N 171:439388707:940756513", "{name}! ดีใจที่เจ้ากลับมาอย่างปลอดภัย ความช่วยเหลือที่มีต่อ Volcor ทำให้ข้าเชื่อว่าเราจะผ่านอุปสรรคใน Darkshore และดินแดนอื่นไปได้" },
        objectiveLabels = {
            event = { ["Help Volcor to the road"] = "ช่วย Volcor ไปให้ถึงถนน" },
        },
    },
    [995] = { -- Escape Through Stealth
        title = { "22:346879275:1069366107", "ลอบเร้นหลบหนี" },
        objective = { "56:1219362568:1366451214", "หนีจากถ้ำเฟอร์โบลก์ แล้วไปพบ Terenthis ใน Auberdine" },
        description = { "229:658592528:1742079703", "เอาล่ะ... ถ้าเจ้ามั่นใจ เราจะลอบออกไป ออกเดินทางเมื่อเจ้าพร้อม\n\nจำไว้ว่าหลังหนีได้ให้ไปหา Terenthis ใน Auberdine ข้าจะไปเอง เพราะคงเดินทางได้เร็วกว่าเจ้า" },
        progress = { "5:1287366450:669725923 N 1:63:63", "มีอะไรหรือ {name}?" },
        completion = { "N 171:439388707:940756513", "{name}! ดีใจที่เจ้ากลับมาอย่างปลอดภัย ความช่วยเหลือที่มีต่อ Volcor ทำให้ข้าเชื่อว่าเราจะผ่านอุปสรรคใน Darkshore และดินแดนอื่นไปได้" },
        objectiveLabels = {
            event = { ["Help Volcor escape the cave"] = "ช่วย Volcor หนีออกจากถ้ำ" },
        },
    },
    [1140] = { -- The Tower of Althalaxx
        title = { "22:1686023837:976185767", "หอคอยอัลธาแลกซ์" },
        objective = { "115:210656398:404692152", "ปลดปล่อยวิญญาณไฮบอร์นที่ติดอยู่ใน Night Run และ Satyrnaar แล้วกลับไปหา Delgren the Purifier ที่ Maestra's Post" },
        description = { "408:1536940394:1616987457 N 73:801132961:1240582948 C 18:807710612:960958540", "ตัวหนังสือของออร์คแทบไม่ดีกว่ารอยขีดเขียนของเด็ก หลายคนในคณะหัวเราะเยาะเมื่อข้าเลือกเรียนภาษาของพวกมัน แต่การเข้าใจศัตรูมากขึ้นมีประโยชน์\n\nจากบันทึกของ Ilkrud ดูเหมือน Athrikus ยังมีอัญมณีวิญญาณอีกสองชิ้น เก็บไว้ใน Night Run กับ Satyrnaar พื้นที่ที่ซาเทียร์ยึดอยู่ทางตะวันออกเฉียงเหนือของ Ashenvale\n\nระวังตัว {name} วิหารชุ่มเลือดของซาเทียร์ทำให้แม้แต่ {class} มากประสบการณ์อย่างเจ้าหวั่นใจได้" },
        progress = { "160:1220957028:841197506", "ข้าเคยได้ยินข่าวลือว่าประวัติซาเทียร์เกี่ยวข้องกับไนต์เอลฟ์ แต่เจ้าบ้านที่ข้าเคารพไม่ค่อยยอมพูดเรื่องนี้" },
        completion = { "293:1680133030:936324319", "บางทีเราปล่อยให้ซาเทียร์อยู่ในป่านานเกินไปแล้ว ข้าจะคุยกับ Elissa เมื่อไป Auberdine ครั้งหน้า\n\nอย่างไรก็ดี เมื่ออัญมณีวิญญาณถูกทำลาย พลัง Athrikus จะลดลงมาก เราต้องฉวยโอกาสกำจัดเขากับลัทธิ" },
        steps = { { "36:652762767:1343736084", "ปลดปล่อยดวงวิญญาณของไฮบอร์นใน Night Run" }, { "36:1575714501:1013273883", "ปลดปล่อยดวงวิญญาณของไฮบอร์นใน Satyrnaar" } },
    },
    [1143] = { -- The Tower of Althalaxx
        title = { "22:1686023837:976185767", "หอคอยอัลธาแลกซ์" },
        objective = { "95:876021391:1889329745", "ฆ่า Athrikus Narassin แล้วนำหัวไปให้ Balthule Shadowstrike ใกล้ Tower of Althalaxx" },
        description = { "233:1861329061:1630606803", "เข้าใจแล้ว ถ้าสิ่งที่เจ้าบอกเป็นจริง ก็ถึงเวลาโจมตี ข้าเชื่อว่า Athrikus อยู่ชั้นบนสุดของหอคอย ระวังด้วย รอบตัวเขามีวอร์ล็อกทรงพลังมากมาย อันตรายกว่าพวกที่เจ้าเคยสู้มาก" },
        progress = { "160:997531742:1667757726", "Athrikus Narassin เป็นวอร์ล็อกเก่าแก่และทรงพลัง บางทีควรรอ Delgren มาช่วย แต่เขาคงเชื่อมั่นในตัวเจ้ามากจึงส่งมาคนเดียว" },
        completion = { "205:697859596:1209226019", "เมื่อ Athrikus ตาย ข้าหวังว่าพลังปีศาจในบริเวณนี้จะถูกผลักออกไป มั่นใจว่าพวกมันจะรวมตัวกลับมา แต่ครั้งหน้าเราจะพร้อมรับมือยิ่งกว่าเดิม" },
        required = { [5383] = { "24:475748852:2130607592", "ศีรษะของ Athrikus Narassin" } },
        steps = { { "24:475748852:2130607592", "ศีรษะของ Athrikus Narassin" } },
    },
    [1167] = { -- The Tower of Althalaxx
        title = { "22:1686023837:976185767", "หอคอยอัลธาแลกซ์" },
        objective = { "61:982591780:2147442559", "ไปคุยกับ Balthule Shadowstrike ใกล้ Tower of Althalaxx" },
        description = { "207:602162382:1480587175", "ก่อนเผชิญ Athrikus ควรปรึกษา Balthule เสียก่อน ข้าเชื่อว่าเขาเฝ้าหอคอยอย่างใกล้ชิด และอาจมีข้อมูลความเคลื่อนไหวล่าสุด" },
        completion = { "32:1508662199:103463510 N 101:1675868349:921944146 N 274:1173254756:440752493", "อา ดีใจที่เจอกันอีก {name}! มีเรื่องประหลาดที่สุดเกิดขึ้นแถวนี้ ดีใจจริงที่เจ้ามา!\n\nแปลกมาก {name} ทุกอย่างดูปกติ อย่างน้อยก็ปกติเท่าที่นี่จะเป็นได้ แล้วทันใดนั้นมีแสงจ้าจากห้องชั้นบนของหอคอย ตามด้วยเสียงกรีดร้อง เสียงนั้นก้องกลางอากาศ สายฟ้าฟาดพื้นเป็นระยะ เกิดอะไรขึ้นกัน?" },
    },
    [2078] = { -- Gyromast's Revenge
        title = { "18:1315015393:1944935284", "การแก้แค้นของไจโรมาสต์" },
        objective = { "80:374240504:1824030543", "ค้นหา Threshwackonator 4100 ต้นหนของ Gelkak แล้วพากลับไปหา Gelkak" },
        description = { "220:703009037:78901923", "เจ้าคนบก ไปหาต้นหนให้ข้าที\n\nเอากุญแจนี่เสียบหัวเขา แล้วพากลับมารับใช้กัปตัน\n\nเมอร์ล็อกกับหัวหน้ามันคงไม่ยินดีแน่ เมื่อต้นหนข้าไปถึงตัว!" },
        progress = { "24:1186958258:1549620803 N 51:914462724:1423648513", "ต้นหนข้าอยู่ไหน {name}? ถ้าไม่รีบ เจ้าจะได้เจอโซ่ตรวนกับฉลาม!" },
        completion = { "148:8154469:831220224", "ย้าก... เจ้าพิสูจน์แล้วว่าไม่ใช่แค่ไอ้ขี้ขลาดแห่งท้องทะเล เจ้าคนบก\n\nถ้ายังทำได้แบบนี้ กัปตันอาจเลื่อนขั้นให้เป็นคนขัดดาดฟ้าท้ายเรือ..." },
        steps = { { "19:2095541920:1548137620", "ต้นเรือของ Gelkak" } },
    },
    [2098] = { -- Gyromast's Retrieval
        title = { "20:1621527548:915988618", "กู้ของให้ไจโรมาสต์" },
        objective = { "68:1518636553:1908123670", "ค้นหาชิ้นส่วน Gelkak's Key ทั้งสามชิ้น แล้วนำกลับไปให้ Gelkak Gyromast" },
        description = { "470:62372868:1000570546", "ชีวิตโจรสลัดไม่ง่ายหรอก เจ้าคนบก ไม่ได้มีแต่ปล้นกับเหล้า! เรือข้าจมนอกฝั่งก็เพราะพวก Threshadon น่ารำคาญ\n\nที่ต้องการคือต้นหนข้ากลับมาทำงานได้!\n\nตอนข้าถูกซัดขึ้นฝั่ง กุญแจของต้นหนกระแทกหินแตก แล้วสัตว์ใน Darkshore ขโมยไป หางตาข้าเห็น Raging Crawler, Ferocious Foreststrider กับเมอร์ล็อกรื้อซากเรืออยู่..." },
        progress = { "44:1889011066:1145041834", "หากุญแจแตกของข้าเจอหรือยัง เจ้าคนบก?" },
        completion = { "154:541647509:252906106", "ฟังนะ เจ้าหมาทะเลขี้เรื้อน! ทำได้แล้ว! อีกไม่นานต้นหนข้าก็กลับมาทำงาน แล้วพวกสัตว์ร้ายจะไม่รู้เลยว่าอะไรเล่นงานมัน!\n\nอืม ว่าแต่เห็นต้นหนข้าบ้างไหม?" },
        required = { [7498] = { "19:72384004:1990512182", "ส่วนบนของกุญแจ Gelkak" }, [7499] = { "22:1927567807:1955320751", "ส่วนกลางของกุญแจ Gelkak" }, [7500] = { "22:1763611114:65404726", "ส่วนล่างของกุญแจ Gelkak" } },
        steps = { { "19:72384004:1990512182", "ส่วนบนของกุญแจ Gelkak" }, { "22:1927567807:1955320751", "ส่วนกลางของกุญแจ Gelkak" }, { "22:1763611114:65404726", "ส่วนล่างของกุญแจ Gelkak" } },
    },
    [5321] = { -- The Sleeper Has Awakened
        title = { "24:1480657924:180683092", "ผู้หลับใหลตื่นแล้ว" },
        objective = { "80:677670028:1293185313", "คุ้มกัน Kerlonian Evershade ไปหา Liladris Moonriver ที่ Maestra's Post ใน Ashenvale", variants = { { "99:277616843:2062624276", "คุ้มกัน Kerlonian Evershade ไปหา Liladris Moonriver โดยเดินตามถนนลงใต้เพื่อตามหากระเป๋าของเขาใน Darkshore" } } },
        description = { "484:1820449110:1319286433", "ข้ากำลังไป Maestra's Post เพื่อพบ Liladris Moonriver แต่หยุดงีบที่นี่สักครู่ ตั้งแต่ตื่นจาก Emerald Dream ก็รู้สึกง่วงมากเหลือเกิน...\n\n<หาว>\n\nช่วยนำทางให้หน่อยได้ไหม? เข้าใจว่า Maestra's Post อยู่ตามถนนลงใต้ใน Ashenvale เส้นทางอาจอันตราย หวังว่าเจ้ามีเพื่อนร่วมเดินทาง\n\nอีกอย่าง ข้าอาจเผลอหลับ ถ้าต้องปลุก ช่วยใช้เขาของข้า อยู่ในหีบตรงนี้", variants = { { "479:1131620311:1105322690", "ข้ากำลังไป Maestra's Post เพื่อพบ Liladris Moonriver แต่หยุดงีบที่นี่สักครู่ ตั้งแต่ตื่นจาก Emerald Dream ข้าก็ง่วงเหลือเกิน...\n\n<หาว>\n\nข้าหาของไม่เจอเลย! ช่วยข้าตามหาหน่อยได้ไหม?\n\nเท่าที่ข้ารู้ Maestra's Post อยู่ทางใต้ของที่นี่ ตามถนนใน Ashenvale ข้ามาจากทางนั้น...\n\nอีกอย่าง ข้าอาจเผลอหลับ ถ้าต้องปลุกก็ใช้เขาของข้าได้เลย มันอยู่ในหีบตรงนี้" } } },
        progress = { "22:112179525:1276482319", "Kerlonian มาถึงแล้วหรือ?" },
        completion = { "140:1067208100:90362798 N 1:46:46", "ดีใจเหลือเกินที่ Kerlonian มาถึง! แล้วข้าคงพบเขานอนหลับอยู่แถวนี้ ใช่ไหม?\n\nขอบใจที่นำทางเขามา {name}", variants = { { "154:1974069683:1035769600 N 1:46:46", "ข้าดีใจเหลือเกินที่ Kerlonian ปลอดภัย! ข้าคงเจอเขานอนหลับอยู่แถวนี้แหละ จริงไหม? สักวันหนึ่งล่ะนะ...\n\nขอบใจที่นำทางเขามา {name}" } } },
        required = { [13536] = { "17:1476662991:1013076097", "แตรปลุกจากนิทรา" } },
        steps = { { "17:1476662991:1013076097", "แตรปลุกจากนิทรา" } },
        objectiveLabels = {
            event = { ["Escort Kerlonian Evershade on the road south to his bag"] = "คุ้มกัน Kerlonian Evershade ลงใต้ตามถนนไปยังกระเป๋าของเขา" },
        },
    },
    [5713] = { -- One Shot. One Kill.
        title = { "19:480038102:1871849831", "หนึ่งนัด หนึ่งชีวิต" },
        objective = { "80:1320276063:584085781", "คุ้มกัน Sentinel Aynasha แล้วไปคุยกับ Onaeya ที่ Maestra's Post ใน Ashenvale" },
        description = { "497:1640185435:1006658562", "ข้ากำลังส่งสารสำคัญไป Auberdine เมื่อเฟอร์โบลก์ Marosh กับพวกล่าสะกดรอยเข้ามาโจมตี ข้าถูกพิษจนแทบยืนไม่ไหว ปรุงยาถอนพิษได้ แต่ต้องใช้เวลากว่าจะพร้อม\n\nช่วยปกป้องจนข้าใช้ยาได้ ข้าจะยิงธนูช่วยให้ดีที่สุด\n\nถ้ารอด ข้าจะนำสารไปส่ง Auberdine ส่วนเจ้าช่วยไปแจ้ง Onaeya ที่ Maestra's Post เรื่องนี้" },
        progress = { "109:1196963216:1470141353", "เห็น Sentinel Aynasha บนถนนหรือไม่? นางออกไปทำภารกิจสำคัญ แต่ยังไม่กลับ" },
        completion = { "28:951771263:1014487636 C 172:365614525:1384805178", "ข่าวของเจ้าช่างน่ายินดี {class} ดีที่รู้ว่า Aynasha ยังปลอดภัยเพราะความช่วยเหลือของเจ้า หวังว่าเจ้าจะรับรางวัลสำหรับความกล้าหาญ ขอ Elune คุ้มครองและส่องทางให้เจ้า" },
        objectiveLabels = {
            event = { ["Protect Aynasha"] = "คุ้มกัน Aynasha" },
        },
    },
    [991] = { -- Raene's Cleansing
        title = { "17:433479699:1240385282", "การชำระล้างของเรน" },
        objective = { "26:2060351323:1640477271", "ตามหา Teronis ใน Ashenvale" },
        description = { "N 486:1921465974:1325025636 N 9:261475542:1201216930", "{name} เพื่อนเก่าแก่ของข้าคนหนึ่งช่วย Sentinel ใน Ashenvale อยู่ด้วย แต่เขายังไม่กลับมา\n\nเขามีเบาะแสของสิ่งที่จะชะลอการโจมตีของเฟอร์โบลก์ได้ เป็นคทาที่พ่อมดชั่วร้ายผู้ตายไปแล้วสร้างขึ้น\n\nก่อนออกเดินทาง เขาบอกว่าจะตามหาอัญมณีสำหรับคทา\n\nเขาว่าอัญมณีอาจซ่อนที่ศาลใน Lake Falathim ตรงเชิงเขาทางตะวันตก มันถูกเก็บไว้ที่นั่นก่อนบริเวณนั้นถูกยึด\n\nช่วยตามหาเพื่อนของข้า {name} ได้โปรด" },
        completion = { "192:1948840266:1921417638", "ร่างของ Teronis นอนบิดเบี้ยวอยู่บนเกาะ ด้วยเหตุผลบางอย่าง เมอร์ล็อกปล่อยศพเขาไว้\n\nรอยแผลลึกทั่วศพเห็นได้ชัดว่าเกิดจากอาวุธและกรงเล็บของเมอร์ล็อก" },
    },
    [1020] = { -- Orendil's Cure
        title = { "14:1469110057:897891312", "ยารักษาของโอเรนดิล" },
        objective = { "56:266714160:445686763", "นำ Orendil's Cure ไปให้ Pelturas Whitemoon ใน Astranaar" },
        description = { "N 199:495013735:1486682482", "{name} ข้าปรุงยาที่เชื่อว่าจะช่วยเด็กป่วยได้แล้ว นำไป Astranaar แล้วมอบให้ Pelturas Whitemoon พ่อของเด็ก\n\nไป Astranaar ได้โดยตามถนนลงใต้แล้วเลี้ยวไปตะวันออก" },
        progress = { "80:1063238753:182785064", "ขออภัย ข้าไม่มีเวลาคุย Relara ลูกข้าป่วยหนักใกล้ตาย!" },
        completion = { "117:561833210:1253145095", "นี่จาก Orendil หรือ?\n\nเขาเชี่ยวชาญสมุนไพรและการรักษามาก ยานี้ให้ความหวังแก่ข้า หลังจากแทบไม่เหลือเลย..." },
        required = { [5460] = { "14:1469110057:897891312", "ยารักษาของ Orendil" } },
        steps = { { "14:1469110057:897891312", "ยารักษาของ Orendil" } },
    },
    [1033] = { -- Elune's Tear
        title = { "12:2027741826:1093454289", "หยาดน้ำตาของอีลูน" },
        objective = { "44:56673674:935228315", "นำ Elune's Tear ไปให้ Pelturas ใน Astranaar" },
        description = { "397:1717078579:2089987369 N 65:272883646:1208193028", "ข้าหวังว่ายาของ Orendil จะช่วย Relara ได้ แต่เกรงว่ามันเพียงชะลอโรคที่กำลังเล่นงานลูก เราต้องหายาที่แรงกว่า! โชคดีที่ Orendil บอกวิธีรักษาอื่นไว้เผื่อยาตัวแรกไม่ได้ผล\n\nElune's Tear เป็นศิลาที่พบเพียงแห่งเดียว คือเกาะใน Iris Lake ทางตะวันออกของ Astranaar Orendil บอกว่ามันชำระความแปดเปื้อนได้ ได้โปรด {name} นำมาให้ข้า และภาวนาให้ลูกหายป่วย!" },
        progress = { "N 47:639371831:1241532867", "{name} พบ Iris Lake แล้วหรือ? ได้ศิลาหยาดน้ำตามาหรือยัง?" },
        completion = { "105:1147063930:1212094129 N 1:33:33", "โอ้ หาพบแล้ว! ข้าจะใส่ศิลาลงในน้ำต้ม และภาวนาให้รักษานางได้\n\nขอบใจ! ขอบใจ {name}!" },
        required = { [5493] = { "12:2027741826:1093454289", "หยาดน้ำตาแห่ง Elune" } },
        objectiveLabels = {
            item = { ["Elune's Tear"] = "หยาดน้ำตาแห่ง Elune" },
        },
    },
    [1008] = { -- The Zoram Strand
        title = { "16:692578291:1136856660", "ชายฝั่งโซแรม" },
        objective = { "61:1060774057:1323265250", "นำ Wrathtail Head 20 ชิ้นไปให้ Shindrell Swiftfire ใน Astranaar" },
        description = { "462:1433099249:464234287", "มีความชั่วร้ายแฝงอยู่บนชายฝั่งตะวันตกเฉียงเหนือที่เรียกว่า Zoram Strand\n\nที่นั่นเป็นที่ฝังนคร Zoram ที่ถูกทำลายและจมใต้ทะเลระหว่างมหาวิบัติ Sundering ไนต์เอลฟ์สูญเสียมันมาหลายยุค สูญหายจนแทบถูกลืม\n\nบัดนี้นากากลับมาโดยไม่ทราบเหตุผล แต่เหตุผลสำคัญน้อยกว่าการสังหารพวกมันและขับกลับสู่ใต้ทะเล!\n\nกลับมาหาข้าเมื่อภารกิจเสร็จ" },
        progress = { "47:1550665085:1047206532 N 72:52144487:2146924219", "เราจะให้นาการุกรานชายฝั่งไม่ได้ {name} เจ้าต้องไป Zoram Strand แล้วทำภารกิจให้สำเร็จ" },
        completion = { "16:2103922072:1818543247 N 273:806174945:509951668", "ทำได้ดีมาก {name} ผลงานปราบนากาที่ Zoram Strand น่าชื่นชม\n\nข้ารู้ว่าไม่ง่าย พวกไนต์เอลฟ์รู้ดีถึงกำลังและเล่ห์เหลี่ยมของนากา เพราะเรามีประวัติศาสตร์ร่วมกับพวกมัน\n\nเป็นประวัติศาสตร์ที่ข้าไม่อยากรื้อฟื้น" },
        required = { [5490] = { "14:840604607:1973963518", "หัวของ Wrathtail" } },
        steps = { { "14:840604607:1973963518", "หัวของ Wrathtail" } },
    },
    [1010] = { -- Bathran's Hair
        title = { "14:719013597:806826336", "เส้นผมแห่งบาธรัน" },
        objective = { "57:509395755:1965842979", "นำ Bathran's Hair 5 ชิ้นไปให้ Orendil Broadleaf ใน Ashenvale" },
        description = { "452:1023388372:1460439504", "มีพืชชนิดหนึ่งเคยขึ้นตามซากโบราณ Bathran's Haunt ทางเหนือ เรียกว่า Bathran's Hair เชื่อกันว่ารักษาโรคทางจิตวิญญาณได้\n\nมีเด็กป่วยในหมู่บ้าน ข้าเชื่อว่าไม่ได้ป่วยแค่ร่างกาย เจ้าไปค้น Bathran's Hair ที่นั่นได้ไหม? อาจจำเป็นต่อการรักษาให้ถูกทาง\n\nBathran's Haunt อยู่เหนือ Maestra's Post และใต้เขตแดน Darkshore เล็กน้อย" },
        progress = { "38:2146324453:363408486 N 48:1186739669:120707070", "เก็บ Bathran's Hair มาแล้วหรือ {name}? เด็กอ่อนแรงลงทุกชั่วโมง..." },
        completion = { "187:379999517:1795051230", "อา ได้มาแล้ว! ทีนี้ข้าจะปรุงยารักษาเด็กและภาวนาให้ได้ผล\n\nแล้ว... มี Forsaken อยู่ที่ Bathran's Haunt หรือ? เป็นข่าวน่าวิตกมาก น่าวิตกจริง ๆ..." },
        required = { [5437] = { "14:719013597:806826336", "เส้นผมของ Bathran" } },
        steps = { { "14:719013597:806826336", "เส้นผมของ Bathran" } },
    },
    [1023] = { -- Raene's Cleansing
        title = { "17:433479699:1240385282", "การชำระล้างของเรน" },
        objective = { "87:535929587:1009828288", "หา Glowing Gem แล้วนำกลับไปให้ Raene Wolfrunner ใน Astranaar พร้อม Teronis' Journal" },
        description = { "281:343005696:1240869464", "ขณะค้นข้าวของของ Teronis เจ้าพบสมุดบันทึกที่ยังอยู่ในสภาพดี\n\nเจ้าเก็บบันทึกไว้และปล่อยศพ Teronis ตามเดิม\n\nเหลือเพียงหาอัญมณีที่เขาตามหา Raene บอกว่าอยู่แถวนี้ บางทีพวกเมอร์ล็อกอาจเก็บไว้..." },
        progress = { "18:923397404:1667069411 N 1:46:46", "อา ยินดีต้อนรับกลับ {name}" },
        completion = { "18:1631773478:1255437676 N 338:698708305:613788773", "เรื่องนี้เลวร้ายมาก {name} Teronis ตายแล้วหรือ?!\n\nเวลาคร่ำครวญจะมาถึง แต่ตอนนี้ต้องตั้งใจทำงาน ข้าจะส่ง Sentinel ไปนำร่างเขากลับมาโดยเร็ว\n\nเจ้ามีทั้งบันทึกและอัญมณีที่เขาตามหา คิดว่าจะทำภารกิจของเขาต่อได้ไหม? ข้าคงสบายใจขึ้นมากหากรู้ว่าความตายของเขาไม่สูญเปล่า" },
        required = { [5463] = { "11:1804413476:391618345", "อัญมณีเรืองแสง" } },
        steps = { { "11:1804413476:391618345", "อัญมณีเรืองแสง" } },
    },
    [1024] = { -- Raene's Cleansing
        title = { "17:433479699:1240385282", "การชำระล้างของเรน" },
        objective = { "49:60406091:884725922", "ไปหา Shael'dryn ที่บ่อจันทร์ทางตะวันออกเฉียงเหนือ" },
        description = { "497:136461868:250950483", "เจ้าต้องค้นคว้าเอง แต่จากบันทึกของ Teronis ดูเหมือนขั้นต่อไปคือหาชิ้นส่วนคทาที่ Dartol สร้าง ข้าจะเริ่มที่บ่อจันทร์ทางตะวันออกของ Iris Lake เมื่อพร้อม เดินตามถนนแล้วเลี้ยวขึ้นเหนือเมื่อถึงที่นั่งพักเล็ก ๆ ทางซ้าย\n\nดรายแอดชื่อ Shael'dryn ที่นั่นน่าจะชี้แนะได้ดีกว่า ไปหานาง\n\nเก็บอัญมณีไว้ด้วย หากจะช่วยประกอบคทา นางต้องใช้มัน" },
        progress = { "19:766030636:550106090", "สวัสดี เป็นอย่างไรบ้าง?" },
        completion = { "72:1527324922:1153014514", "อ้อ Raene ส่งเจ้ามาหรือ? คงเป็นเรื่องสำคัญจริง ๆ มีอะไรให้ข้าช่วย?" },
        required = { [5463] = { "11:1804413476:391618345", "อัญมณีเรืองแสง" } },
        steps = { { "11:1804413476:391618345", "อัญมณีเรืองแสง" } },
    },
    [1025] = { -- An Aggressive Defense
        title = { "21:1679223987:1847309735", "ตั้งรับด้วยการรุก" },
        objective = { "131:973557698:1199611969", "ฆ่าสมาชิกเผ่า Foulweald ได้แก่ Den Watcher 1 ตัว, Ursa 2 ตัว, Totemic 10 ตัว และ Warrior 12 ตัว แล้วกลับไปหา Raene Wolfrunner ใน Astranaar" },
        description = { "490:585029988:664594042", "ก่อนไปบ่อจันทร์ ข้ามีงานอีกอย่างที่จะช่วยชาว Ashenvale หากเจ้าอยากทดสอบฝีมือ\n\nตามถนนมุ่งตะวันออกก่อนถึง Falfarren River เฟอร์โบลก์โจมตีคนเดินทาง จิตใจที่ทุกข์ทรมานของพวกมันหล่อเลี้ยงด้วยความกลัว และความหิวดับด้วยเลือดผู้บริสุทธิ์\n\nช่วย Sentinel ปกป้องผืนดิน โดยมอบความเมตตาให้สัตว์ประหลาดพวกนั้นเช่นเดียวกับที่มันมอบให้เรา\n\nข้าว่าค่ายอยู่ทางใต้ของถนน... ระวังด้วย" },
        progress = { "39:1669644203:2082844347 N 81:1603155662:1448214128", "เฟอร์โบลก์ไม่ได้เป็นศัตรูกับเรามาแต่เดิม {name} แต่กาลเวลาเปลี่ยนไป และป่ามืดแห่งนี้ไม่มีสันติอีกแล้ว" },
        completion = { "20:1921578502:569519135 N 12:513407318:1685728707", "ทำได้ดี {name} ขอบใจ" },
        objectiveLabels = {
            monster = { ["Foulweald Den Watcher slain"] = "ปราบ ผู้เฝ้ารัง Foulweald", ["Foulweald Ursa slain"] = "ปราบ เออร์ซา Foulweald", ["Foulweald Totemic slain"] = "ปราบ ผู้ใช้โทเทม Foulweald", ["Foulweald Warrior slain"] = "ปราบ นักรบ Foulweald" },
        },
    },
    [1026] = { -- Raene's Cleansing
        title = { "17:433479699:1240385282", "การชำระล้างของเรน" },
        objective = { "95:2105260561:892978143", "หา Wooden Key และชิ้นส่วน Dartol's Rod แล้วกลับไปหา Shael'dryn ที่บ่อจันทร์" },
        description = { "493:242059001:561991964", "ข้าอยากให้ข่าวที่เจ้าพามาดีกว่านี้\n\nRaene พูดถูก ข้ารู้เรื่องสิ่งที่ Dartol สร้างและเหล่าทรีแอนต์ในพื้นที่ อย่างน้อยก็เคยรู้ บัดนี้พวกมันถูกความชั่วร้ายบิดเบือนธรรมชาติ\n\nถ้าต้องการชิ้นส่วนคทาต่อไป เจ้าต้องหากุญแจเปิดหีบที่เก็บมัน\n\nทรีแอนต์ตัวหนึ่งทางตะวันออกเฉียงเหนือใกล้ Felwood มีกุญแจไม้ เมื่อได้แล้ว มองหาลานป่าเล็ก ๆ ทางตะวันตกของถนนใกล้เขต Felwood หีบน่าจะซ่อนแถวนั้น" },
        progress = { "90:1979179995:1388399106", "ข้าเสียใจเหลือเกินที่ทรีแอนต์แปดเปื้อน หวังว่าจะช่วยพวกมันได้มากกว่านี้" },
        completion = { "32:1630444232:1420916250 N 1:46:46", "ดีใจที่เจ้ากลับมา {name}" },
        required = { [5464] = { "10:511527907:1039071042", "แกนเหล็ก" } },
        steps = { { "10:511527907:1039071042", "แกนเหล็ก" } },
    },
    [1027] = { -- Raene's Cleansing
        title = { "17:433479699:1240385282", "การชำระล้างของเรน" },
        objective = { "78:97895105:1707491903", "หาชิ้นส่วนสุดท้ายของ Dartol's Rod แล้วกลับไปหา Shael'dryn ที่บ่อจันทร์" },
        description = { "484:1307750299:325604683", "ชิ้นส่วนสุดท้ายฝากให้ดรูอิดแห่ง Dor'danil เก็บรักษา ข้าไม่รู้ว่าพวกเขาซ่อนที่ไหน เสียใจที่ช่วยได้เท่านี้\n\nบอกได้เพียงให้ตามถนนไปทาง Barrens พวกดรูอิดอาศัยทางตะวันออกของถนน แต่คงช่วยเจ้าไม่ไหว พวกเขาเพิ่งถูกฆ่า... เป็นเรื่องที่ข้าไม่อยากคิดถึง\n\nเมื่อพบชิ้นส่วนสุดท้าย นำมาให้ข้า แล้วจะช่วยประกอบคทาให้" },
        progress = { "41:889227375:1044071120 N 1:63:63", "พบชิ้นส่วนคทาสุดท้ายหรือยัง {name}?" },
        completion = { "118:1251588119:330418282", "พบชิ้นส่วนสุดท้ายแล้วหรือ? ดีสำหรับเจ้า... และ Raene\n\nคงต้องดูเรื่องซ่อมมันแล้วสินะ?" },
        required = { [5519] = { "11:637557124:993596068", "หัวด้ามเหล็ก" } },
        steps = { { "11:637557124:993596068", "หัวด้ามเหล็ก" } },
    },
    [1028] = { -- Raene's Cleansing
        title = { "17:433479699:1240385282", "การชำระล้างของเรน" },
        objective = { "51:1531093902:1826581841", "ค้นหาศาลที่ซ่อนอยู่ แล้วลงมนตร์ให้ Dartol's Rod อีกครั้ง" },
        description = { "27:1825793126:589840437 N 467:959088949:1891421381", "นี่คทาที่ประกอบเสร็จ {name} ประกอบไม่ยาก... ส่วนที่ยากคือหาศาลที่เติมพลังให้มันได้\n\nถ้าตั้งใจและพยายาม คนที่ทำสำเร็จมาแล้วมากมายอย่างเจ้าคงไม่ลำบากเกินไป\n\nมุ่งตะวันออกเฉียงใต้จากที่นี่ ทางเดินมีน้อยจึงต้องระวัง และคอยมองทางเหนือ ศาลซ่อนในภูเขาที่ล้อมลานป่านี้\n\nเมื่อถึง วางคทาในศาล... ที่เหลือเป็นเรื่องของเวทมนตร์ ฮิ ๆ" },
        progress = { "207:2042883946:335114577", "เจ้าสัมผัสได้ถึงพลังบางเบาแต่ทรงอำนาจในศาลและต้นไม้รอบข้าง\n\nเมื่อเริ่มวางคทาในศาล เสียงสั่นครางเบา ๆ ดังรอบตัว ขณะที่ศาลเรืองแสง..." },
        completion = { "80:924666839:1963106751", "เมื่อแสงดับลง เจ้าพบคทาที่ได้รับมนตร์อีกครั้งอยู่ในแอ่งกลางศาล" },
        required = { [5547] = { "17:1218083501:81256023", "คทาที่ประกอบขึ้นใหม่" } },
        steps = { { "17:1218083501:81256023", "คทาที่ประกอบขึ้นใหม่" } },
    },
    [1029] = { -- Raene's Cleansing
        title = { "17:433479699:1240385282", "การชำระล้างของเรน" },
        objective = { "40:1643782956:968548646", "กลับไปหา Raene Wolfrunner ใน Astranaar" },
        description = { "128:2021063259:1703588331 N 1:46:46", "ข้าแนะนำให้ไปบอก Raene ว่าคทาเสร็จแล้ว นางคงรู้ว่าต้องทำอะไรต่อ\n\nขอให้โชคดี {name}" },
        completion = { "164:1781866041:1250059767", "เจ้าประกอบคทาที่ Teronis ออกตามหาได้แล้วหรือ? เป็นข่าวดีจริง ๆ\n\nTeronis คงภูมิใจที่ภารกิจยังดำเนินต่อ แม้เขาจากไปอย่างน่าเศร้าแล้ว" },
    },
    [1030] = { -- Raene's Cleansing
        title = { "17:433479699:1240385282", "การชำระล้างของเรน" },
        objective = { "97:1802520107:402348432", "หาเฟอร์โบลก์ที่ยังไม่ถูกครอบงำ แล้วใช้พลัง Dartol's Rod of Transformation เพื่อคุยกับเขา" },
        description = { "502:1136793577:199489087", "ข้าไม่แน่ใจเสียทีเดียวว่าเขาตั้งใจทำอะไรต่อ\n\nหากพลังคทาเป็นจริงอย่างที่บอก มันจะให้เจ้าเปลี่ยนรูปร่างได้ แต่เป็นร่างใด ข้าไม่รู้\n\nบางทีเขาอาจคิดใช้พลังเข้าใกล้เฟอร์โบลก์ที่แปดเปื้อน แต่แม้พวกที่ยังปกติก็ฆ่าเขาได้ถ้าไม่ระวัง เมื่อใช้คทาแปลงร่าง Dartol คงต้องคุยกับเฟอร์โบลก์ที่ปลอดภัยจาก Fel Moss\n\nข้าจะเริ่มค้นหาทางตะวันออกเฉียงใต้ของ Mystral Lake" },
        completion = { "500:76616695:237764910", "ใช่ ใช่... เจ้าเป็นพวกเดียวกับข้า แต่ยังสมบูรณ์ ยังสะอาด\n\nข้าไม่รู้ว่าเจ้าหนีความโหดร้ายที่ไนต์เอลฟ์ทำกับพวกเราได้อย่างไร แต่ดีใจที่รู้ว่าข้าไม่โดดเดี่ยวอีก\n\nความแปดเปื้อนไหลในเลือดพี่น้องเราแล้ว เจ้าหนุ่มสาว เป็นสิ่งที่ไนต์เอลฟ์ผู้ทะนงนำมา พวกมันทำเช่นนี้กับเรา... ข้าโทษพวกมันที่ทำให้ข้าถูกขับจากเผ่า\n\nยามค่ำ ข้ายังมองเห็นไฟค่ายลุกในความมืด" },
    },
    [1034] = { -- The Ruins of Stardust
        title = { "21:522317618:438073721", "ซากปรักแห่งละอองดาว" },
        objective = { "54:1238036262:1480558669", "นำ Handful of Stardust 5 กำไปให้ Pelturas ใน Astranaar" },
        description = { "364:2131971105:1794093645 N 31:1264721118:1779452469", "Elune's Tear ชำระโรคบางส่วนจากลูกสาวข้า ฝันร้ายของนางลดลง ข้าขอบคุณเทพธิดาสำหรับพรนั้น แต่... ไข้ยังคงรุนแรง\n\nOrendil เล่าถึงฝุ่นเย็นจัดใน Ruins of Stardust บางทีมันอาจลดไข้ Relara ได้ ช่วยเก็บแล้วกลับมาหาข้า\n\nซากแห่งนั้นอยู่ทางใต้ {name} ขอ Elune ช่วยให้เดินทางรวดเร็ว" },
        progress = { "30:1704101962:1996693971 N 1:63:63", "ได้ Stardust มาแล้วหรือยัง {name}?" },
        completion = { "116:1388060243:1257173938 N 50:1787746326:55406371", "ได้ฝุ่นมาแล้ว! ข้าจะทำยาพอกจากมัน น่าจะลดไข้ Relara ได้\n\nขอบใจอีกครั้ง {name} ถ้าไม่มีเจ้า ลูกข้าคงไม่รอดแน่" },
        required = { [5494] = { "19:1362171748:131460757", "ผงดาวหนึ่งกำมือ" } },
        steps = { { "19:1362171748:131460757", "ผงดาวหนึ่งกำมือ" } },
    },
    [1035] = { -- Fallen Sky Lake
        title = { "15:1242366323:1027376895", "ทะเลสาบฟ้าร่วง" },
        objective = { "97:389510258:1576810476", "นำ Fallen Moonstone จาก Shadethicket Oracle ไปให้ Pelturas ใน Astranaar" },
        description = { "466:1640497066:1794910081", "Relara หายไข้แล้วแต่ยังอ่อนแรงมาก ข้าไม่เชื่อว่าเวลาอย่างเดียวจะคืนกำลังที่เสียไป ต้องใช้พลังมูนสโตน\n\nเราเคยเก็บมูนสโตนที่ Fallen Sky Lake ทางตะวันออกเฉียงใต้... จนพวก Shadethicket มา\n\nหัวหน้าของมัน Shadethicket Oracle เก็บมูนสโตนที่ตกทั้งหมดไปกักตุน เจ้าต้องเอาศิลากลับจากมัน\n\nข้าเกรงว่าต้องสังหารมันเพื่อให้ได้มา" },
        progress = { "38:381283173:1250208112 N 104:531735719:485228232", "เผชิญ Shadethicket Oracle แล้วหรือ {name}? ถ้าใช่ ส่ง Fallen Moonstone ให้ข้าเถิด Relara เหลือลมหายใจอีกเพียงนิดเดียว!" },
        completion = { "4:1347873283:179389729 N 239:1039857820:121605786", "โอ้ {name} เจ้าช่วยชีวิตลูกสาวข้า! ข้ารู้ว่าพลังมูนสโตนจะคืนกำลังให้นาง!\n\nคงตอบแทนเจ้าได้ไม่หมด แต่... รับสิ่งนี้ไว้ นอกจาก Relara แล้ว มันเป็นสิ่งที่ข้ารักที่สุด" },
        required = { [5508] = { "16:808173023:1318255784", "หินจันทร์ที่ร่วงหล่น" } },
        steps = { { "16:808173023:1318255784", "หินจันทร์ที่ร่วงหล่น" } },
    },
    [1045] = { -- Raene's Cleansing
        title = { "17:433479699:1240385282", "การชำระล้างของเรน" },
        objective = { "82:1797059693:1087692495", "ฆ่า Ran Bloodtooth และ Bloodtooth Guard 4 ตัว แล้วกลับไปหา Krolg ใกล้ Lake Mystral", variants = { { "89:584106023:1373173391", "ฆ่า Bloodtooth Guard 4 ตัว แล้วนำ Ran Bloodtooth's Skull ไปให้ Krolg ใกล้ Lake Mystral" } } },
        description = { "491:1597475415:1634485545", "ไนต์เอลฟ์เก่าแก่ดุจกาลเวลา แต่ความทะนงทำลายโลกของมัน และตอนนี้ทำลายชีวิตเราด้วย แต่เรื่องนั้นควบคุมไม่ได้แล้ว...\n\nข้าโทษเอลฟ์หลายเรื่อง แต่เรายังต้องรับผิดชอบการกระทำของตน แม้ไร้ความแปดเปื้อน เราก็ทำความชั่วใหญ่หลวงได้\n\nRan Bloodtooth เป็นหนึ่งในนั้น มันกระหายอำนาจ และความแปดเปื้อนยิ่งทำให้แข็งแกร่ง ข้าเกลียดเอลฟ์ แต่ไม่อยากให้ลูกหลานพวกมันรับเคราะห์ เราจึงต้องจัดการพวกเดียวกันเอง" },
        progress = { "226:1619571567:1710388423", "สังหาร Ran แล้วหรือ สหาย?\n\nแม้ไนต์เอลฟ์ก็ไม่สมควรเผชิญความโกรธของมัน ความเกลียดชังของมันแรงกว่าข้าเสียอีก แต่สติไม่อยู่กับตัวแล้ว มันเป็นภัยต่อทุกชีวิตตามธรรมชาติในป่า" },
        completion = { "287:578095910:1724490906", "ทำได้ดี สหาย\n\nป่ายังแปดเปื้อน แต่อย่างน้อยเราได้ช่วยเล็กน้อยเพื่อคืนความรุ่งเรืองในอดีต หากกลับมาอีก ข้าจะยินดีที่ได้มีพวกเดียวกันเป็นเพื่อน\n\nจงอยู่ดี บางทีเผ่าของเราอาจพบกันอีกในยุคที่รุนแรงน้อยกว่านี้" },
        required = { [5388] = { "22:1134682479:227670196", "กะโหลกของ Ran Bloodtooth" } },
        steps = { { "22:1134682479:227670196", "กะโหลกของ Ran Bloodtooth" } },
        objectiveLabels = {
            monster = { ["Bloodtooth Guard slain"] = "ปราบ ยาม Bloodtooth" },
        },
    },
    [1054] = { -- Culling the Threat
        title = { "18:260916913:1811722425", "ตัดกำลังภัยคุกคาม" },
        objective = { "61:571153445:1464933232", "นำ Dal Bloodclaw's Skull ไปให้ Raene Wolfrunner ใน Astranaar" },
        description = { "434:1390800613:1149682239", "ทางเหนือของ Astranaar มีเฟอร์โบลก์ Thistlefur หน่วยสอดแนมรายงานว่าพวกมันเพิ่มจำนวนมากในไม่กี่เดือน หากมากเกินไป อาจกล้าโจมตี Astranaar โดยตรง\n\nฆ่าให้มากเท่าที่ทำได้ แต่นำกะโหลกหัวหน้าเผ่ามาให้ข้าเป็นหลักฐานว่าความพยายามของมันถูกสกัดไว้... อย่างน้อยในตอนนี้\n\nข้าจะรอข่าวที่ Astranaar ขอ Elune อยู่กับเจ้า" },
        progress = { "87:190965728:1426973660", "ความแปดเปื้อนของเฟอร์โบลก์ทำให้ Ashenvale เหลือความงดงามเพียงเสี้ยวของอดีต" },
        completion = { "11:534428891:784080240 N 103:2119977068:540437395", "ทำได้ดี {name}\n\nพวกเฟอร์โบลก์คุกคามเราอยู่เสมอ หวังว่านี่จะยับยั้งมันได้อีกระยะ" },
        required = { [5544] = { "21:734121311:1975440603", "กะโหลกของ Dal Bloodclaw" } },
        steps = { { "21:734121311:1975440603", "กะโหลกของ Dal Bloodclaw" } },
    },
    [1056] = { -- Journey to Stonetalon Peak
        title = { "26:1466788805:389059747", "เดินทางสู่ยอดเขาสโตนทาลอน" },
        objective = { "45:1569408614:1984037212", "เดินทางไปหา Keeper Albagorm บน Stonetalon Peak" },
        description = { "421:1799209456:81963812 R 31:387487949:1998695481", "วิญญาณแห่งป่าบอกข้าว่าเจ้ากล้าหาญและพร้อมออกเดินทาง\n\nทางใต้ไม่ไกลจาก Mystral Lake มีอุโมงค์ Talondeep Path ผ่านไปจะถึง Windshear Crag ใน Stonetalon Mountains จากนั้นไปตะวันตกเฉียงใต้ผ่าน Cragpool Lake แล้วขึ้นเหนือ ตามทางชันสู่ Stonetalon Peak\n\nKeeper Albagorm รออยู่ จงฟังคำขอของเขา ชาว{race}\n\nการเดินทางจะอันตราย" },
        completion = { "74:294740213:462712332", "ในที่สุดเจ้าก็มาถึง ดูเหมือน Faldreas ฟังวิญญาณแห่งป่าแล้ว..." },
    },
    [1057] = { -- Reclaiming the Charred Vale
        title = { "27:1861202536:1908841761", "ทวงคืนหุบเขาไหม้เกรียม" },
        objective = { "147:890823815:2013469852", "Keeper Albagorm บน Stonetalon Peak ขอให้ฆ่า Bloodfury Harpy 7 ตัว, Bloodfury Ambusher 7 ตัว, Bloodfury Slayer 7 ตัว และ Bloodfury Roguefeather 7 ตัว", variants = { { "147:1351520340:158825689", "Keeper Albagorm บน Stonetalon Peak ขอให้ฆ่า Bloodfury Harpy 6 ตัว, Bloodfury Ambusher 6 ตัว, Bloodfury Slayer 6 ตัว และ Bloodfury Roguefeather 6 ตัว" } } },
        description = { "487:237472827:13494824 N 1:33:33", "ในฐานะผู้ปกป้องวิญญาณแห่งป่า เจ้าคงเดาได้ว่าข้าตกใจเรื่องใด\n\nเจ้าข้ามภูเขามาถึงยอดนี้ ต้องเห็นความเสียหายต่อผืนดินแล้ว ความโลภทำลายเนินเขาศักดิ์สิทธิ์\n\nCharred Vale ทางใต้ถูกเผาโดยกองทัพเครื่องจักรของนักอุตสาหกรรมละโมบ ซ้ำพวก Bloodfury ที่รุกเข้ามายังขวางไม่ให้เราฟื้นฟูพืชพรรณ\n\nขับไล่ฮาร์ปีชั่วร้ายพวกนั้น {name}!" },
        progress = { "140:305337259:293310495 N 59:628288341:15177417", "ยังมีงานมากกว่าจะฟื้น Charred Vale ให้เป็นป่าเขียวชอุ่มอย่างเดิม\n\nกำจัดภัยร้ายให้พ้น {name}! แล้วเราจึงจะเริ่มทวงคืนสิ่งที่เป็นของธรรมชาติได้" },
        completion = { "115:1761026664:1336028729", "เมื่อ Bloodfury เสียกำลังไปมากเช่นนี้ บางทีงานฟื้นฟูผืนดินที่แท้จริงอาจเริ่มได้แล้ว..." },
        objectiveLabels = {
            monster = { ["Bloodfury Harpy slain"] = "ปราบ ฮาร์ปี Bloodfury", ["Bloodfury Roguefeather slain"] = "ปราบ ฮาร์ปีขนนอกคอก Bloodfury", ["Bloodfury Slayer slain"] = "ปราบ นักสังหาร Bloodfury", ["Bloodfury Ambusher slain"] = "ปราบ นักซุ่มโจมตี Bloodfury" },
        },
    },
    [1059] = { -- Reclaiming the Charred Vale
        title = { "27:1861202536:1908841761", "ทวงคืนหุบเขาไหม้เกรียม" },
        objective = { "76:926712859:901173038", "เดินทางไปหา Falfindel Waywarder ที่ชายแดน Thousand Needles กับ Feralas" },
        description = { "469:290045902:367257453", "Bloodfury ถูกปราบแล้ว แต่จะรวมตัวใหม่ในไม่ช้าหากเราไม่ทำอะไร\n\nไกลลงใต้จาก Barrens คือ Thousand Needles ไปตะวันตกจนถึงชายป่าเขียวชอุ่มของ Feralas จะพบดรูอิดชื่อ Falfindel Waywarder\n\nดรูอิดผู้ยิ่งใหญ่และรอบรู้นี้เรียกวิญญาณป่าทรงพลังมาช่วยฟื้น Charred Vale ได้\n\nส่งข่าวว่าเราต้องการความช่วยเหลือ ไปหาเขาทันที!" },
        completion = { "169:1008094722:1764199916", "Keeper Albagorm คิดถูกที่รีบส่งเจ้ามา\n\nมาดูกันว่าเราจะเรียกความช่วยเหลือจากป่ายิ่งใหญ่ให้ไป Charred Vale ได้ทันก่อนสายหรือไม่" },
    },
    [990] = { -- Trek to Ashenvale
        title = { "17:1471678949:1602335120", "เดินทางสู่อาเชนเวล" },
        objective = { "35:1626828888:1543604779", "ไปหา Raene Wolfrunner ใน Ashenvale" },
        description = { "N 301:1427718720:490880277", "{name} นายหญิงของข้า Raene Wolfrunner รออยู่ที่เมือง Astranaar ใน Ashenvale ด้วยความช่วยเหลือของเจ้า บางทีเราอาจบรรเทาความแปดเปื้อนที่ยึดพื้นที่ได้บ้าง\n\nไปทางใต้จากที่นี่แล้วอยู่ใกล้ถนน หากทำตามนี้ก็ถึงได้ไม่ยาก" },
        completion = { "6:1537380568:68647516 C 68:693811938:1967337929 N 204:667256929:1642066781", "อา {class} จาก Darkshore Selarin ทำดีที่ส่งเจ้ามาเร็ว {name} อยากให้การมาเยือนเกิดขึ้นในสถานการณ์ที่ดีกว่านี้ บางทีเจ้าจะช่วยปรับปรุงเรื่องราวได้\n\nข้าแนะนำให้เริ่มคุยกับชาว Astranaar คนอื่น บางคนคงต้องการความช่วยเหลือ" },
    },
    [976] = { -- Supplies to Auberdine
        title = { "21:1547137034:350980858", "เสบียงสู่ออเบอร์ดีน" },
        objective = { "101:591749627:2072320110", "พา Feero ผ่าน Ashenvale Forest อย่างปลอดภัย แล้วคุยกับ Delgren the Purifier ที่ Maestra's Post" },
        description = { "404:786611972:237410972", "Delgren ขอให้ข้าส่งสารและเสบียงให้ Sentinel Starbreeze ใน Auberdine แต่ข้าไม่อยากไปคนเดียว มีศัตรูอันตรายในป่า ข้าไม่อยากเสี่ยงให้เสบียงและข้อมูลตกผิดมือ\n\nหากเจ้ากับคนอื่นช่วยคุ้มกัน ข้าก็ออกเดินทางได้เลย เมื่อมีพวกเจ้าปกป้อง มั่นใจว่าส่งของถึง Auberdine อย่างปลอดภัยได้" },
        progress = { "82:1723780958:2132025695", "Sentinel ต้องการเสบียงอย่างมากเพื่อเสริมกำลังใน Darkshore" },
        completion = { "26:125921176:1174313097 C 155:766608685:224157432", "วันนี้ทำได้ดี {class} ของที่ส่งไปช่วย Auberdine จะได้ใช้ทันทีในการรับมือภัยมืดที่รุมเร้าป่า\n\nรับสิ่งเหล่านี้พร้อมคำขอบคุณจากใจข้า" },
        objectiveLabels = {
            event = { ["Protect Feero Ironhand"] = "ปกป้อง Feero Ironhand" },
        },
    },
    [1007] = { -- The Ancient Statuette
        title = { "21:2034769156:1277327012", "รูปสลักโบราณ" },
        objective = { "72:540761105:1966253122", "นำ Ancient Statuette ไปให้ Talen ที่ค่ายใกล้ Zoram Strand" },
        description = { "32:1642007513:930002205 N 298:1972978993:322917042 N 160:16859853:135638260", "ข้าอยากฝากงานให้เจ้า {name}\n\nข้าอยู่บนเรือลำเล็กเหนือซาก Zoram ใต้น้ำ เมื่อนากาพุ่งขึ้นมาโจมตีและใช้กรงเล็บฉีกข้า! ข้าหนีเอาเสบียงเท่าที่ขนได้มาตั้งค่ายเล็ก ๆ นี้\n\nแต่ตอนถึงฝั่งแล้ววิ่งหนี... ของรักของข้าหายไป\n\nได้โปรด {name} ไปยังจุดที่ข้าถูกซุ่มโจมตีตามชายฝั่งเหนือ แล้วหารูปสลักโบราณ มันคือเหตุผลที่ข้าฝ่าอันตรายมาที่ Zoram Strand" },
        progress = { "30:948997496:41347002 N 1:63:63", "พบรูปสลักหรือยัง {name}?" },
        completion = { "25:2143849172:1365458331 N 94:707542948:1992644279", "พบแล้ว! ขอบใจ {name}!\n\nนครเก่า Zoram ซ่อนความลับมากมาย รูปสลักนี้อาจเป็นกุญแจไขหลายเรื่อง" },
        required = { [5424] = { "17:607335403:1456751785", "รูปสลักโบราณขนาดเล็ก" } },
        steps = { { "17:607335403:1456751785", "รูปสลักโบราณขนาดเล็ก" } },
    },
    [1009] = { -- Ruuzel
        title = { "6:80859312:636652186", "รูเซล" },
        objective = { "55:1462333801:561571079", "นำ Ring of Zoram ไปให้ Talen ใกล้ Zoram Strand" },
        description = { "380:164965489:1364807066 N 27:1455168890:1624190408", "เกรงว่าความลับของรูปสลักจะซ่อนอยู่ตลอดไป หากเจ้าไม่พบกุญแจไขกลอนโบราณ\n\nกุญแจนั้นเป็นแหวน Ring of Zoram เคยเป็นของผู้ปกครองเมืองก่อนคลื่นมหาวิบัติ Sundering จะกลืนมัน\n\nแหวนสูญหายหลายปี แต่นากาเพิ่งพบมัน\n\nหัวหน้าของมัน Ruuzel อยู่บนเกาะตรงชายขอบเหนือของ Zoram ได้โปรด {name} นำแหวนกลับมาให้ข้า!" },
        progress = { "90:772060335:1829616250 N 1:63:63", "เล่ากันว่า Ring of Zoram ไขกลอนทุกแห่งในเมืองได้ เจ้าหามาแล้วหรือ {name}?" },
        completion = { "31:2136586331:171213161 N 95:282816844:1302868506", "พบแหวนแล้ว! ขอบใจ {name} รับสิ่งนี้เป็นค่าตอบแทน และจงรู้ว่าข้าจะจดจำสิ่งที่เจ้าทำวันนี้ตลอดไป" },
        required = { [5445] = { "13:1877367868:745363540", "แหวนแห่ง Zoram" } },
        steps = { { "13:1877367868:745363540", "แหวนแห่ง Zoram" } },
    },
    [1016] = { -- Elemental Bracers
        title = { "17:726114297:871331744", "กำไลแห่งธาตุ" },
        objective = { "164:1376443324:665539811", "เก็บ Intact Elemental Bracer 5 ชิ้นแล้วใช้ Divining Scroll จากนั้นนำ Divined Scroll ไปให้ Sentinel Velene Starstrike ที่ Silverwind Refuge" },
        description = { "496:1168855047:1157442727", "รับม้วนทำนายนี้ มันระบุผู้สร้างเหล่าวิญญาณธาตุได้ แต่ต้องใช้ชิ้นส่วนของพวกมันเป็นสื่อรวมพลังเวท กำไลของมันน่าจะเหมาะ\n\nกำไลที่ยังสมบูรณ์สักจำนวนหนึ่งน่าจะพอ ส่วนอื่นใช้กับงานนี้ไม่ได้ แต่อาจขายให้พ่อค้าได้ เมื่อได้กำไลสมบูรณ์แล้วลองใช้ม้วนทำนาย นำผลกลับมาหาข้า แล้วเราค่อยทำต่อ" },
        progress = { "289:1761035739:691617965", "เพราะต้องทำลายกำไลเพื่อฆ่าวิญญาณธาตุ คงหาชิ้นที่มีข้อมูลสำหรับม้วนทำนายได้ยาก เจ้าจะแลกกำไลกับคนอื่นเพื่อหาชิ้นที่ต้องใช้ก็ได้ หรือได้ผลทำนายมาแล้ว?" },
        completion = { "11:534428891:784080240 N 344:162424645:1584801348", "ทำได้ดี {name} นี่น่าจะให้ข้อมูลพอระบุตัวคนผิด เจ้าคิดอย่างไรกับการปราบจอมเวทที่ปล่อยวิญญาณธาตุแปดเปื้อนลงแอ่งน้ำเรา? ลำพังความเสื่อมทรามของ Ashenvale กับดินแดนรอบข้างก็ทำข้าคลื่นไส้ การมีพ่อมดจงใจทำลายเพิ่มยิ่งชวนขยะแขยง เราจะให้มันชดใช้" },
        required = { [5455] = { "14:12790354:1478413977", "ม้วนคัมภีร์จากการทำนาย" } },
        steps = { { "14:12790354:1478413977", "ม้วนคัมภีร์จากการทำนาย" } },
    },
    [1017] = { -- Mage Summoner
        title = { "13:1630293020:1436475773", "จอมเวทผู้อัญเชิญ" },
        objective = { "93:1566623154:934423991", "สังหาร Sarilus Foulborne แล้วนำหัวไปให้ Sentinel Velene Starstrike ใน Silverwind Refuge" },
        description = { "222:1826529714:17853337 N 248:1907933805:1192142382", "มีจอมเวทอันเดดใน Barrens เพียงคนเดียวที่ทำให้วิญญาณธาตุน้ำมากขนาดนี้แปดเปื้อนได้ และโง่พอจะลอง Sarilus Foulborne คงนั่งหัวเราะข้าบนยอด Dreadmist Peak อยู่\n\n{name} เจ้าต้องเข้าแดนศัตรูแล้วกำจัดเจ้าคนชั่ว ข้าทนความงี่เง่าของมันพอแล้ว ต้องให้รู้ว่าใครรบกวน Sentinel จะเจออะไร\n\nกำจัดแล้วนำหัวมา ระวังด้วย Horde อาจเฝ้าดูเจ้า" },
        progress = { "38:1897381489:1420633709", "เสร็จแล้วหรือ? Sarilus Foulborne ตายแล้วหรือ?" },
        completion = { "89:488409967:1231334998 N 117:239606854:2017372424", "ทีนี้รอยยิ้มน่ารังเกียจของมันก็หายไปตลอดกาล ทำได้ดีมาก {name} รับ Light of Elune นี้ไว้ ดื่มเมื่อหมดหวังและความตายอยู่ใกล้ หากเทพธิดาทรงประสงค์ มันอาจช่วยชีวิตเจ้า" },
        required = { [5537] = { "24:372032685:900338157", "หัวของ Sarilus Foulborne" } },
        steps = { { "24:372032685:900338157", "หัวของ Sarilus Foulborne" } },
    },
    [1070] = { -- On Guard in Stonetalon
        title = { "22:1423304293:1217431326", "เฝ้าระวังสโตนทาลอน" },
        objective = { "98:2117392731:434414805", "ไปหา Kaela Shadowspear ซึ่งเฝ้ามองหุบเขาทางเข้า Windshear Crag ใน Stonetalon Mountains" },
        description = { "7:989913233:66981971 N 485:1112360368:1029980396", "สวัสดี {name}\n\nดูท่าเจ้าเต็มไปด้วยความอยากเดินทาง เคยไป Stonetalon Mountains หรือยัง? ดินแดนที่ถูก Venture Co. และศัตรูอื่นของไนต์เอลฟ์รังควาน\n\nเมื่อไม่นาน Sentinel Wolfrunner ส่ง Kaela Shadowspear เพื่อนข้าไปสืบความเป็นไปของผืนดิน แต่ยังไม่มีข่าวกลับ ข้ายิ่งห่วงเพราะ Alliance ส่งจอมเวทโนมไปด้วย... ต้องมีปัญหาแน่\n\nเจ้าช่วยหาแล้วกลับมารายงานข้าได้ไหม?" },
        completion = { "233:288584850:421104152 N 1:46:46", "อา มาจาก Ashenvale ตามคำขอของ Tara หรือ ข้าคิดถึงนาง บ้านเกิด และเพื่อน ๆ เหลือเกิน นางคงทำงานกับ Sentinel ได้ดีจึงขอแรงนักผจญภัยช่วยงานอื่นได้ ข้าภูมิใจในตัวนาง\n\nยินดีที่ได้พบ {name}" },
    },
    [1085] = { -- On Guard in Stonetalon
        title = { "22:1423304293:1217431326", "เฝ้าระวังสโตนทาลอน" },
        objective = { "15:772567265:1301980216", "ไปคุยกับ Gaxim" },
        description = { "422:1168018608:2142072902", "สถานการณ์ใน Stonetalon หนักหนาแน่ ถึงทำให้ไนต์เอลฟ์กับโนมร่วมมือกัน\n\nVenture Co. ทำลายผืนดิน ข้าใช้เวลาส่วนใหญ่หยุดความเสียหาย\n\nอย่าด่วนตัดสิน Gaxim เขาเข้าใจความจำเป็นของการร่วมมือ\n\nถ้าอยากช่วย เริ่มจากคุยกับเขา\n\nเสียใจที่ยังส่งเจ้ากลับไปหา Tara พร้อมข่าวดีไม่ได้ หวังว่าจะได้ในไม่ช้า" },
        completion = { "378:1810888581:1392640101", "ทรยศ... อันตรายและไม่น่าไว้ใจ นั่นแหละดินแดนนี้\n\nแต่ข้ามาให้ไนต์เอลฟ์เห็นว่ามันปลอดภัยขึ้นได้ด้วยวิศวกรรมเก่าแก่ที่ดี ผสมเวทมนตร์อีกนิด\n\nการสาบานเลิกใช้เวททั้งหมดช่วยไนต์เอลฟ์ไม่ได้ พวกเขาต้องการมัน โลกต้องการมัน เพิ่มวิศวกรรมกับการเล่นแร่แปรธาตุเข้าไปก็ไปได้สวย ความเป็นไปได้ไม่มีที่สิ้นสุด" },
    },
    [1134] = { -- Pridewings of Stonetalon
        title = { "24:1759829547:429448470", "ไพรด์วิงแห่งสโตนทาลอน" },
        objective = { "66:904122655:300223050", "นำ Pridewing Venom Sac 12 ถุงไปให้ Shindrell Swiftfire ใน Astranaar" },
        description = { "451:2082824251:752664766 N 42:28182988:38020539", "เราไม่ได้ประกาศสงครามกับ Horde แต่สันติเปราะบาง มักพบสายลับของมันเคลื่อนไหวต่อต้านเราอย่างลับ ๆ\n\nแหล่งข่าวใน Theramore เผยแผนหนึ่งว่าออร์คเก็บพิษจาก Pridewing ใกล้ Mirkfallon Lake ใน Stonetalon Mountains ทางใต้ แล้วนักฆ่าออร์คนำพิษไปใช้ลอบสังหาร Alliance!\n\nหากจริง เราต้องหยุดมัน {name} ต้องตัดแหล่งพิษ" },
        progress = { "38:1161130936:2078666722 N 65:1564153647:1384887001", "ได้ถุงพิษ Pridewing แล้วหรือ {name}? เราจะให้ออร์คใช้พิษของสัตว์พวกนี้เล่นงานเราไม่ได้!" },
        completion = { "11:1191658970:1224418299 N 275:1196637565:562140164", "ขอบใจ {name} ข้าเศร้าที่ต้องสั่งฆ่าสัตว์ซึ่งอาจไม่ได้เต็มใจช่วยศัตรู แต่นี่เป็นหน้าที่\n\nใจเจ้าอาจร่ำไห้ให้ Pridewing ที่ฆ่า สหาย แต่ขอให้ใจพองโตเมื่อรู้ว่าพันธมิตรปลอดภัยจากพิษของมันแล้ว" },
        required = { [5808] = { "19:1712729268:1413797005", "ถุงพิษ Pridewing" } },
        steps = { { "19:1712729268:1413797005", "ถุงพิษ Pridewing" } },
    },
    [1031] = { -- The Branch of Cenarius
        title = { "22:1729384385:277905412", "กิ่งพฤกษาแห่งซีนาเรียส" },
        objective = { "76:387251958:1951656994", "ฆ่า Geltharis แล้วนำ Branch of Cenarius กลับไปให้ Illiyana ที่ Forest Song", variants = { { "86:1504750255:1311268043", "ฆ่า Geltharis แล้วนำ Branch of Cenarius กลับไปให้ Illiyana ที่ Shrine of Aessina" } } },
        description = { "315:381731011:1612074297", "Anilia วางมือบนไหล่แล้วดึงเจ้าเข้ามา นางหอบพลางชี้ซุ้มทางเหนือ ก่อนหลับตาและปล่อยลมหายใจเฮือกสุดท้าย “เขาเอามันไป... Geltharis...” เจ้ารู้ในใจว่าคำขอสุดท้ายของนางคือให้กิ่งพฤกษาแห่ง Cenarius กลับสู่มือดรายแอด" },
        progress = { "55:1485874034:1715249294", "พบพวกเขาหรือยัง? Anilia พูดอะไร? นางอยู่ไหน?" },
        completion = { "142:220292384:770544978", "Anilia ตายแล้วหรือ? ไม่... เป็นไปไม่ได้! เหมือนเพิ่งเมื่อวานที่เราวิ่งเล่นด้วยกันในป่า\n\nคงไม่มีวันแบบนั้นอีกแล้ว..." },
        required = { [5461] = { "18:2098613501:160230756", "กิ่งไม้ของ Cenarius" } },
        steps = { { "18:2098613501:160230756", "กิ่งไม้ของ Cenarius" } },
    },
    [1032] = { -- Satyr Slaying!
        title = { "14:2044963303:1286269826", "สังหารซาเทียร์!" },
        objective = { "48:610329740:310412945", "นำ Satyr Horn 16 ชิ้นไปให้ Illiyana ใน Forest Song", variants = { { "58:18459502:1276682273", "นำ Satyr Horn 16 ชิ้นไปให้ Illiyana ใน Shrine of Aessina" } } },
        description = { "299:1429840734:1214172196", "ไม่อยากเชื่อว่า Anilia จากไปแล้ว... เราเคยเล่นด้วยกันในป่าตลอด ข้าแทบจะรู้สึก... เศร้า\n\nรู้แล้วว่าอะไรอาจช่วยให้ดีขึ้น ช่วยฆ่าซาเทียร์ที่พราก Anilia ไปจากข้า! นำเขาของมันมาเป็นหลักฐาน แล้วข้าจะขอบคุณตลอดไป" },
        progress = { "38:1801482915:2015556409", "ช่วยข้าแก้แค้นให้ Anilia ด้วย" },
        completion = { "16:494813677:908239516 R 50:389854085:516958893", "ขอบใจ ชาว{race} ผู้ใจดี ความพยายามของเจ้าทำให้วิญญาณพี่น้องข้ายินดี" },
        required = { [5481] = { "11:1370151492:883192787", "เขาเซเทอร์" } },
        objectiveLabels = {
            item = { ["Satyr Horns"] = "เขาเซเทอร์" },
        },
    },
    [1046] = { -- Raene's Cleansing
        title = { "17:433479699:1240385282", "การชำระล้างของเรน" },
        objective = { "97:499276830:1704837928", "นำ Ran Bloodtooth's Skull และ Dartol's Rod of Transformation ไปให้ Raene Wolfrunner ใน Astranaar" },
        description = { "112:1142020667:1489118019", "กลับไปเผ่าของเจ้า บอกพวกเขาถึงชัยชนะครั้งนี้\n\nแสดงของที่ได้มา แล้วรับเกียรติยศเถิด..." },
        progress = { "69:2139033071:1077125694 R 50:298880084:65191319", "Sentinel ทำเท่าที่ทำได้ใน Ashenvale แต่เพราะชาว{race} อย่างเจ้าช่วย เราจึงได้พื้นที่คืนมาเท่านี้" },
        completion = { "111:169746821:619984934 N 230:1986539973:1813387667", "นี่กะโหลกของเฟอร์โบลก์ที่เป็นภัยร้ายแรงที่สุดใน Ashenvale หรือ?\n\nฝีมือเจ้าเกินความคาดหมาย {name} Sentinel ขอบคุณเท่าไรก็คงไม่พอ หวังว่าจะพึ่งพาให้ช่วยผู้คนได้อีก\n\nข้าจะวางกะโหลกกับคทาของ Dartol ไว้ในที่ทรงเกียรติให้ผู้อื่นเห็น\n\nTeronis คงภูมิใจ ขอบใจอีกครั้ง" },
        required = { [5388] = { "22:1134682479:227670196", "กะโหลกของ Ran Bloodtooth" }, [5462] = { "30:794869340:1250873495", "คทาแปลงร่างของ Dartol" } },
        steps = { { "22:1134682479:227670196", "กะโหลกของ Ran Bloodtooth" }, { "30:794869340:1250873495", "คทาแปลงร่างของ Dartol" } },
    },
    [1055] = { -- Raene's Cleansing
        title = { "17:433479699:1240385282", "การชำระล้างของเรน" },
        objective = { "37:2126128758:2033568806", "กลับไปหา Shael'dryn ที่บ่อจันทร์" },
        description = { "88:280381950:520549964", "คทาที่เสร็จสมบูรณ์อยู่ในมือเจ้าแล้ว Shael'dryn คงอยากรู้ถึงความสำเร็จ" },
        completion = { "16:856926774:1278399515 N 12:1438682583:370493333", "เจ้าทำสำเร็จ {name}! เยี่ยมมาก!" },
    },
    [730] = { -- Trouble In Darkshore?
        title = { "21:662066403:1412877297", "ปัญหาในดาร์กชอร์?" },
        objective = { "70:949741699:352912716", "เดินทางไป Auberdine แล้วหาร่องรอยของทีมขุดค้นคนแคระ" },
        description = { "24:2109249468:1488289577 C 464:1496679160:1326479537", "ดีจริงที่ได้เห็น {class} สนใจสิ่งมหัศจรรย์ทางโบราณคดีของโลกเรา\n\nสหายใน Alliance มักมองงานของเราเป็นแค่งานอดิเรก แต่หลายคนไม่รู้ว่าการค้นพบล่าสุดใน Khaz Modan พิสูจน์แล้วว่ามีพลังยิ่งใหญ่กำลังคุกคาม Azeroth ทั้งหมด ตั้งแต่ Lordaeron จนถึง Kalimdor\n\nข้าเป็นห่วงทีมที่ส่งไป Darkshore มาก พวกเขาไม่ส่งข่าวมาหลายสัปดาห์แล้ว\n\nไป Auberdine แล้วหาเบาะแสว่าพวกเขาอยู่ที่ใด" },
        completion = { "58:451747680:2104493277", "ดีใจเหลือเกินที่หัวหน้านักโบราณคดี Greywhisker ส่งคนมาตามหาพวกเรา..." },
    },
    [952] = { -- Grove of the Ancients
        title = { "21:767074880:1807300401", "พงไพรแห่งผู้เก่าแก่" },
        objective = { "95:1330183249:1442586129", "นำสารของ Fandral ไปให้ Onu ที่ Grove of the Ancients ใน Darkshore ทางใต้ของ Auberdine" },
        description = { "438:990677390:523899120", "ถ้าเจ้ามีเวลาวิ่งส่งสารให้ Oracle Tree ข้าก็คงใช้งานให้ส่งสารไป Grove of the Ancients ใน Darkshore ทางใต้ของ Auberdine ได้เช่นกัน\n\nเจ้าคงต้องหาฮิปโปกริฟฟ์โดยสารไป แต่ข้าเชื่อว่าจัดการเรื่องนั้นได้ นำสิ่งนี้ไปให้ Onu ผู้เก่าแก่แห่งปัญญา เขารอข่าวจากข้า เช่นเดียวกับที่ข้ารอข่าวจาก Oracle Glade" },
        progress = { "4:1110229495:147916717 C 25:2055581207:719580023", "อา {class} Onu ช่วยอะไรเจ้าได้บ้าง?", variants = { { "3:4319959:1129135 C 25:2055581207:719580023", "อา {class} Onu ช่วยอะไรเจ้าได้บ้าง?" } } },
        completion = { "15:1389078567:459919723 N 172:404814143:2065304193", "อา ขอบใจ {name} แปลกจริง อัครดรูอิดดูเร่งรีบอยู่เสมอ ป่าย่อมรู้ว่าทุกสิ่งจะเกิดขึ้นเมื่อถึงเวลา Shan'do Stormrage เข้าใจข้อนี้ดี" },
        required = { [5390] = { "17:1563595755:263067815", "สารจาก Fandral" } },
        steps = { { "17:1563595755:263067815", "สารจาก Fandral" } },
    },
    [2519] = { -- The Temple of the Moon
        title = { "22:1421659949:2082813906", "วิหารแห่งจันทรา" },
        objective = { "83:349095160:308275374", "Sister Aquinne ขอให้เจ้าไปคุยกับ Priestess A'moora ใน Temple of the Moon" },
        description = { "56:366227875:1128456645 R 179:697425890:513994422", "สัตว์แห่งป่าที่เคยยิ่งใหญ่ต้องการความช่วยเหลือ ชาว{race}\n\nมีงานที่ยากลำบากอย่างหนึ่งต้องทำ\n\nไปหา Priestess A'moora เถิด นางจะอธิบายให้ฟัง นางอยู่ทางตะวันออกเฉียงใต้ของที่นี่ ภายใน Temple of the Moon" },
        completion = { "28:1596959611:69164260", "Sister Aquinne ส่งเจ้ามาหรือ?" },
    },
    [2518] = { -- Tears of the Moon
        title = { "17:704159183:411230687", "หยาดน้ำตาแห่งจันทรา" },
        objective = { "114:1573581343:1573630912", "นำ Silvery Spinnerets ของ Lady Sathrah ไปให้ Priestess A'moora ใน Temple of the Moon ที่ Darnassus" },
        description = { "338:1304939608:2092272265 N 156:1996476890:1342316484", "Lady Sathrah เคยเป็นที่รักของ Elune แมงมุมผู้สง่างามและบริสุทธิ์ถักเส้นใยเงินผ่านแสงจันทร์เพื่อดักละอองหมอกยามค่ำ หยาดน้ำค้างสีเงินนั้นมีพลังรักษาและเก็บไว้ในวิหารแห่งนี้\n\nแต่ระยะหลัง Sathrah ตกอยู่ในความคลุ้มคลั่ง ลูกหลานรุ่นต่อไปของนางก็กำลังถูกคุกคามด้วย\n\nค้นหา Lady Sathrah แล้วจบความทุกข์ของนาง {name} นางอยู่ตามชายแดนเหนือของ Teldrassil ใกล้ Wellspring Lake เก็บอวัยวะสร้างใยสีเงินของนางกลับมาให้ข้า" },
        progress = { "241:1666766618:1613850722", "ข้าเสียใจที่ต้องขอให้เจ้าทำเช่นนี้ แต่ Lady Sathrah หมดหนทางช่วยแล้ว\n\nเราหวังจะถวายอวัยวะสร้างใยแด่ Elune เพื่อให้นางประทานพรแก่ Sathrah ให้ได้เกิดใหม่อย่างสงบ" },
        completion = { "89:2010801393:1101968908 N 1:46:46", "ผืนป่าโศกเศร้าให้ Lady Sathrah แต่เรื่องนี้จำเป็นต้องทำ\n\nขอบใจ {name}" },
        required = { [8344] = { "18:703279489:1057159993", "อวัยวะปั่นใยสีเงิน" } },
        steps = { { "18:703279489:1057159993", "อวัยวะปั่นใยสีเงิน" } },
    },
    [2520] = { -- Sathrah's Sacrifice
        title = { "19:487871604:2143191750", "ของบูชาแห่งซาธรา" },
        objective = { "129:1949092519:534296305", "Priestess A'moora ขอให้เจ้าวางอวัยวะสร้างใยสีเงินของ Lady Sathrah ที่น้ำพุในวิหาร แล้วกลับไปหานาง" },
        description = { "371:53361253:1378899455", "ตอนนี้เจ้าต้องทำงานที่ได้รับให้สำเร็จ นำอวัยวะสร้างใยไปถวาย Elune เป็นของบูชาของ Lady Sathrah เพื่อให้แมงมุมผู้ยิ่งใหญ่ได้พักอย่างสงบ\n\nค้นหาน้ำพุกลางวิหาร วางของบูชาที่นั่น น้ำศักดิ์สิทธิ์จะชำระความแปดเปื้อนที่ทำให้ Sathrah คลุ้มคลั่ง\n\nเมื่อทำเสร็จแล้ว กลับมาหาข้า" },
        progress = { "47:1655550557:27786226 N 1:63:63", "วางของบูชาที่น้ำพุแล้วหรือยัง {name}?" },
        completion = { "170:2013091024:1400752057", "การสูญเสีย Lady Sathrah น่าเศร้า แต่มีเพียงหนทางนี้ที่จะให้นางเกิดใหม่ด้วยจิตวิญญาณที่ฟื้นคืน\n\nขอให้ Elune ยอมรับของบูชาที่เจ้าถวายแด่นาง" },
        objectiveLabels = {
            event = { ["Offer the sacrifice at the fountain"] = "ถวายเครื่องบูชาที่น้ำพุ" },
        },
    },
    [4722] = { -- Beached Sea Turtle
        title = { "18:1105877754:845388667", "เต่าทะเลเกยฝั่ง" },
        objective = { "66:168817463:612270632", "นำ Sea Turtle Remains ไปให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        description = { "344:539351809:904690134", "เจ้าพบซากเต่าทะเลที่เกยชายฝั่ง Darkshore มาระยะหนึ่ง พวกเมอร์ล็อกที่ตั้งค่ายล้อมซากได้แทะกินมันไปแล้ว แต่ยังมีส่วนที่เหมาะจะเก็บเป็นตัวอย่างให้ Gwennyth Bly'Leggonde ใน Auberdine ใช้ศึกษา" },
        progress = { "6:1457790135:951305579 N 81:1373615375:1508240072", "สวัสดี {name} มีรายงานการค้นพบสัตว์เกยฝั่งหรือ?" },
        completion = { "49:555148801:917308853 N 165:504959523:1646066003", "พบอีกตัวอย่างให้เราศึกษาแล้ว ทำได้ดี {name}! เมื่อซากเหล่านี้ถึง Darnassus ก็จะถูกศึกษาอย่างละเอียด รับค่าตอบแทนเล็กน้อยนี้แลกกับตัวอย่างที่เจ้าหามาให้เราเถิด" },
        required = { [12289] = { "18:336076730:1131874915", "ซากเต่าทะเล" } },
        steps = { { "18:336076730:1131874915", "ซากเต่าทะเล" } },
    },
    [4723] = { -- Beached Sea Creature
        title = { "20:2001033954:860024615", "สัตว์ทะเลเกยฝั่ง" },
        objective = { "66:131198661:1346822578", "นำ Sea Creature Bones ไปให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        description = { "447:1741675522:1250865070", "ซาก Thresher ยักษ์ที่ใหญ่กว่าขนาดปกติใน Darkshore มากเกยอยู่บนชายฝั่ง Mist's Edge ไม่มีใครรู้ว่ามันมาถึงที่นี่ได้อย่างไร กลุ่มเมอร์ล็อกที่กินซากอยู่ดูอ่อนแอเกินกว่าจะล้มมันได้ แม้รวมกันเป็นจำนวนมากก็ตาม\n\nบางส่วนถูกกินจนเกลี้ยง แต่ยังเหลือพอเก็บตัวอย่างให้ Gwennyth Bly'Leggonde ใน Auberdine ศึกษา" },
        progress = { "182:1917878783:204085394 N 26:260286041:702288549", "สักวันเราอาจพบวิธีป้องกันสัตว์น่าสงสารเหล่านี้มาจบชีวิตโดยเปล่าประโยชน์บนชายฝั่ง Darkshore ระหว่างนั้นต้องศึกษาต่อไป!\n\nสวัสดี {name} มีข่าวอะไรมาให้หรือ?" },
        completion = { "30:993184243:349516681 N 165:504959523:1646066003", "ค้นพบอีกตัวแล้ว ทำได้ดี {name}! เมื่อซากเหล่านี้ถึง Darnassus ก็จะถูกศึกษาอย่างละเอียด รับค่าตอบแทนเล็กน้อยนี้แลกกับตัวอย่างที่เจ้าหามาให้เราเถิด" },
        required = { [12242] = { "18:1148672610:258209944", "กระดูกสัตว์ทะเล" } },
        steps = { { "18:1148672610:258209944", "กระดูกสัตว์ทะเล" } },
    },
    [4725] = { -- Beached Sea Turtle
        title = { "18:1105877754:845388667", "เต่าทะเลเกยฝั่ง" },
        objective = { "68:1548828880:1200277582", "นำ Strangely Marked Box ไปให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        description = { "489:26615875:942603380", "มีซากเต่าทะเลเกยตามชายฝั่งอีก ตัวนี้มีรถบรรทุกที่ถูกทิ้งผูกอยู่กับกระดอง บางทีมันอาจถูกใครขับขึ้นฝั่ง ต่างจากซากอื่นที่ดูเหมือนมาเกยเอง เมอร์ล็อก Greymist ยึดซากเป็นที่อยู่และกินเนื้อของมัน\n\nในรถ เจ้าพบกล่องที่มีเครื่องหมายประหลาด บางที Gwennyth Bly'Leggonde ใน Auberdine อาจเข้าใจมัน" },
        progress = { "35:2085754745:1918631995 N 245:444994728:787348035", "ยินดีที่พบกันอีก {name} เราคืบหน้าไปมากในการไขปริศนาว่าทำไมสัตว์ทะเลอันสง่างามมาเกยชายฝั่ง Darkshore แต่ดูเหมือนทุกคำตอบจะนำมาซึ่งคำถามอีกสองข้อ\n\nเจ้ามาช่วยงานศึกษาเพิ่มเติมหรือ?" },
        completion = { "443:1014480502:1371473075", "ข้าเคยได้ยินเรื่องรถแบบที่พบบนหลังเต่านั้น เชื่อว่าเป็นรถของนากา ใช้ทั้งรบและขนเสบียงขึ้นบก เครื่องหมายบนกล่องก็เป็นของนากา นี่อธิบายการรุกรานของพวกมันทางเหนือสุดของ Darkshore ได้\n\nข้าจะส่งกล่องนี้ไป Darnassus พร้อมสิ่งที่เจ้าค้นพบอื่น ๆ นี่สำหรับเจ้า ขอบใจอีกครั้งที่ช่วย" },
        required = { [12292] = { "20:567020320:1183234139", "กล่องที่มีเครื่องหมายประหลาด" } },
        steps = { { "20:567020320:1183234139", "กล่องที่มีเครื่องหมายประหลาด" } },
    },
    [4727] = { -- Beached Sea Turtle
        title = { "18:1105877754:845388667", "เต่าทะเลเกยฝั่ง" },
        objective = { "66:168817463:612270632", "นำ Sea Turtle Remains ไปให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        description = { "362:1836868412:1309057585", "โครงกระดูกเต่าทะเลนอนอยู่บนหาดทรายทางเหนือของ Darkshore พวกเมอร์ล็อก Greymist อาจยังไม่พบมัน หรือพบแล้วแต่หลีกเลี่ยงด้วยเหตุผลบางอย่าง อย่างไรก็ตาม ยังมีซากเต่าพอเก็บตัวอย่างให้ Gwennyth Bly'Leggonde ใน Auberdine นำไปศึกษาเพื่อ Temple of the Moon" },
        progress = { "17:1363563154:1706982442 N 91:136631078:1183772271", "พบกันอีกแล้ว {name} เจอสัตว์เกยฝั่งตัวอื่นที่ Temple of the Moon ควรทราบไหม?" },
        completion = { "156:1370246843:1507433471 N 91:546431080:897908006", "น่าสนใจที่แถวนั้นไม่มีเมอร์ล็อกอยู่ เราจะจำข้อนี้ไว้ตอนศึกษาซาก! ขอบใจสำหรับความพยายาม {name} Temple of the Moon ฝากให้ข้ามอบสิ่งนี้ตอบแทนเวลาของเจ้า" },
        required = { [12289] = { "18:336076730:1131874915", "ซากเต่าทะเล" } },
        steps = { { "18:336076730:1131874915", "ซากเต่าทะเล" } },
    },
    [4728] = { -- Beached Sea Creature
        title = { "20:2001033954:860024615", "สัตว์ทะเลเกยฝั่ง" },
        objective = { "66:131198661:1346822578", "นำ Sea Creature Bones ไปให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        description = { "373:2031891128:90360101", "ซากที่ดูเหมือนสัตว์เลี้ยงลูกด้วยนมในทะเลขนาดยักษ์นอนอยู่บนหาด โดยอวัยวะภายในถูกควักออกบางส่วน มีรถเข็นกับเครื่องมือต่าง ๆ ถูกทิ้งอยู่ข้างซาก คล้ายเคยมีคนพยายามศึกษามัน แม้เมอร์ล็อกกินซากไปบ้าง แต่ยังเหลือพอเก็บตัวอย่างที่เหมาะให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        progress = { "22:940931934:1505085707 N 90:843060186:1501715536", "สวัสดีอีกครั้ง {name}! อะไรพาเจ้ากลับ Auberdine? บางทีจะมารายงานการค้นพบอีกครั้ง?" },
        completion = { "374:1677945869:968165388", "อา ข้าเชื่อว่าเจ้าพบซากที่ Explorer's League เคยศึกษา พวกเขามีคนอยู่ใน Darkshore และบอกว่าเคยศึกษาซากเกยฝั่งตัวหนึ่งก่อนถูกเมอร์ล็อกไล่ไป เจ้าสำเร็จในสิ่งที่พวกเราทั้งสองฝ่ายยังทำไม่ได้ รับค่าตอบแทนนี้ในนาม Temple of the Moon เถิด" },
        required = { [12242] = { "18:1148672610:258209944", "กระดูกสัตว์ทะเล" } },
        steps = { { "18:1148672610:258209944", "กระดูกสัตว์ทะเล" } },
    },
    [4730] = { -- Beached Sea Creature
        title = { "20:2001033954:860024615", "สัตว์ทะเลเกยฝั่ง" },
        objective = { "66:131198661:1346822578", "นำ Sea Creature Bones ไปให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        description = { "329:1310773682:1499516294", "ซากที่อาจเคยเป็นสัตว์เลี้ยงลูกด้วยนมในทะเลขนาดยักษ์ถูกกินไปครึ่งหนึ่งอยู่บนหาด พวกเมอร์ล็อกที่แข็งแรงกว่าพวกใกล้ Auberdine ตั้งถิ่นฐานล้อมซากอยู่ ยังเหลือกระดูกมากพอเก็บเป็นตัวอย่างไปให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        progress = { "13:1366380142:1891123769 N 46:1804853737:2096762740", "สวัสดีอีกครั้ง {name}! มารายงานการค้นพบอีกตัวหรือ?" },
        completion = { "437:1562210751:912008807", "กระดูกนี้เป็นของสัตว์ทะเลเลี้ยงลูกด้วยนมที่อ่อนโยน พบได้ในน้ำรอบฐาน Teldrassil ไม่เคยรู้ว่ามันจะพุ่งมาเกยฝั่งอย่างรุนแรงเหมือนพวก Thresher ทำไมจึงทำเช่นนั้นนะ? บางทีการศึกษาซากอาจให้คำตอบที่เราต้องการ\n\nขอบใจอีกครั้ง รับค่าตอบแทนจาก Temple of the Moon เถิด" },
        required = { [12242] = { "18:1148672610:258209944", "กระดูกสัตว์ทะเล" } },
        objectiveLabels = {
            item = { ["Sea Creature Bones"] = "กระดูกสัตว์ทะเล" },
        },
    },
    [4731] = { -- Beached Sea Turtle
        title = { "18:1105877754:845388667", "เต่าทะเลเกยฝั่ง" },
        objective = { "68:1548828880:1200277582", "นำ Strangely Marked Box ไปให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        description = { "492:1286411097:798891702", "มีซากเต่าทะเลอีกตัวเกยชายฝั่ง รถบรรทุกที่ถูกทิ้งยังผูกติดกับกระดองเพียงครึ่งเดียว บางทีมันอาจถูกผู้ไม่ทราบฝ่ายขับขึ้นฝั่ง ต่างจากซากอื่นที่ดูเหมือนมาเกยเอง พวกเมอร์ล็อก Greymist ที่แข็งแกร่งยึดซากเป็นที่อยู่\n\nในรถ เจ้าพบกล่องที่มีเครื่องหมายประหลาด บางที Gwennyth Bly'Leggonde ใน Auberdine อาจเข้าใจมัน" },
        progress = { "13:1366380142:1891123769 N 143:1631122425:1732504493", "สวัสดีอีกครั้ง {name} งานที่เจ้าช่วย Temple of the Moon ยอดเยี่ยมมาก วันนี้เราจะได้รับความช่วยเหลือจากเจ้าอีกหรือไม่?" },
        completion = { "471:1835240317:1093676515", "ข้าเคยได้ยินเรื่องรถแบบที่พบบนหลังเต่านั้น เชื่อว่าเป็นรถของนากา ใช้ทั้งรบและขนเสบียงขึ้นบก เครื่องหมายบนกล่องก็เป็นของนากา บางทีเต่าที่เจ้าพบอาจถูกฆ่าระหว่างมุ่งลงใต้... ไป Ashenvale กระมัง?\n\nข้าจะส่งกล่องนี้ไป Darnassus พร้อมสิ่งที่เจ้าค้นพบอื่น ๆ นี่สำหรับเจ้า ขอบใจอีกครั้งที่ช่วย" },
        required = { [12292] = { "20:567020320:1183234139", "กล่องที่มีเครื่องหมายประหลาด" } },
        steps = { { "20:567020320:1183234139", "กล่องที่มีเครื่องหมายประหลาด" } },
    },
    [4732] = { -- Beached Sea Turtle
        title = { "18:1105877754:845388667", "เต่าทะเลเกยฝั่ง" },
        objective = { "66:168817463:612270632", "นำ Sea Turtle Remains ไปให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        description = { "378:366819344:1898966015", "เจ้าพบซากเต่าทะเลที่เกยชายฝั่ง Darkshore มาระยะหนึ่ง เมอร์ล็อก Greymist ที่ตั้งค่ายล้อมซากกินมันไปจนแทบเกลี้ยง แต่ยังมีส่วนเหมาะจะเก็บเป็นตัวอย่างให้ Gwennyth Bly'Leggonde ใน Auberdine ใช้ศึกษา" },
        progress = { "21:546799089:1880291739 N 72:1111971755:1462558686", "สวัสดีอีกครั้ง {name} มีการค้นพบอื่นจะรายงานให้ Temple of the Moon หรือไม่?" },
        completion = { "42:47498265:838832730 N 403:435552390:1650957464", "พบสัตว์เกยฝั่งเพิ่มอีกหรือ {name}? ก่อน Nordrassil ถูกทำลาย เต่าทะเลมักแหวกว่ายเล่นอยู่รอบฐานต้นไม้ แต่หลัง Teldrassil ถือกำเนิด พวกมันกลับลดจำนวนลงเรื่อย ๆ และอย่างที่เราพบ บางตัวมาจบชีวิตที่นี่โดยไม่ทราบสาเหตุ\n\nความช่วยเหลือของเจ้าอาจไขปริศนานี้ได้ รับสิ่งนี้แลกกับซากที่นำมาให้เราศึกษาเถิด" },
        required = { [12289] = { "18:336076730:1131874915", "ซากเต่าทะเล" } },
        objectiveLabels = {
            item = { ["Sea Turtle Remains"] = "ซากเต่าทะเล" },
        },
    },
    [4733] = { -- Beached Sea Creature
        title = { "20:2001033954:860024615", "สัตว์ทะเลเกยฝั่ง" },
        objective = { "66:131198661:1346822578", "นำ Sea Creature Bones ไปให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        description = { "431:617843090:2007629377", "ซากที่ดูเหมือน Thresher ยักษ์เกยอยู่ในเวิ้งหินของ Twilight Shore มันใหญ่กว่าตัวอื่นที่พบแถวนี้หลายเท่า ไม่ว่ามาจากไหน ก็ดูไม่ใช่สัตว์พื้นถิ่น Darkshore\n\nแม้บางส่วนถูกฉีกกินไป แต่ยังเหลือพอเก็บตัวอย่างที่เหมาะให้ Gwennyth Bly'Leggonde ใน Auberdine" },
        progress = { "54:1752504907:791515197 N 142:1609667055:2129426898", "ขอบคุณ Elune ดีใจที่ได้พบอีกครั้ง {name} งานของ Temple of the Moon เรื่องสัตว์เกยฝั่งยังดำเนินต่อใน Darkshore เจ้ามีอะไรจะช่วยเราเพิ่มเติมหรือ?" },
        completion = { "460:687630366:737876136 N 1:46:46", "ขนาดของ Thresher ที่เจ้าบอกชวนให้ตกตะลึง แม้ตัวแก่ที่สุดแถวนี้ก็โตได้เพียงเสี้ยวเดียวของมัน เคยมีตัวใหญ่กว่าพบใกล้ Teldrassil แต่จำนวนลดลงเรื่อย ๆ ข้าอดสงสัยไม่ได้ว่าการมาเกยฝั่งอาจเกี่ยวข้องกัน\n\nระหว่างที่เราวิเคราะห์กระดูกที่เจ้านำมา รับสิ่งนี้ในนาม Temple of the Moon เถิด ขอบใจ {name}" },
        required = { [12242] = { "18:1148672610:258209944", "กระดูกสัตว์ทะเล" } },
        steps = { { "18:1148672610:258209944", "กระดูกสัตว์ทะเล" } },
    },
    [27] = { -- A Lesson to Learn
        title = { "17:2145250651:262314469", "บทเรียนที่ต้องเรียนรู้" },
        objective = { "70:1014218030:2080449173", "ไปคุยกับ Dendrite Starblaze ในหมู่บ้าน Nighthaven ที่ Moonglade" },
        description = { "N 491:1024582916:1445548440", "{name} ข้าติดตามความก้าวหน้าของเจ้าด้วยความยินดี เจ้ากำลังเติบโตเป็นผู้พิทักษ์ธรรมชาติที่มีคุณค่าอย่างแท้จริง\n\nถึงเวลาเรียนรู้ร่างสัตว์อีกแบบหนึ่งที่ Cenarius มอบพรให้เราแปลงกายได้ ร่างที่จะทำให้เจ้าควบคุมและเคลื่อนไหวในน้ำอย่างชำนาญ จงไปหมู่บ้าน Nighthaven ใน Moonglade แล้วคุยกับ Dendrite Starblaze แห่ง Cenarion Circle เขาจะชี้แนะเจ้าต่อ" },
        completion = { "496:1865085394:2074887941", "สวัสดี ดรูอิดรุ่นเยาว์ ถึงเวลาเรียนรู้ร่างสัตว์น้ำแล้ว ร่างนี้ทำให้เจ้าเคลื่อนที่ในน้ำได้อย่างอิสระโดยไม่จำกัดเวลา เป็นทั้งเครื่องมือที่มีประโยชน์และพรอันวิเศษ... แต่เจ้าต้องพิสูจน์ตนก่อนจะเชี่ยวชาญมัน\n\nเจ้าต้องผ่านบททดสอบสองอย่าง อย่างแรกทดสอบความสามารถในการทำงานใต้น้ำขณะถูกกดดัน อย่างที่สองทดสอบความมุ่งมั่นที่จะเข้าใจธรรมชาติของร่างนี้\n\nเตรียมตัวให้พร้อม เวลาแห่งบททดสอบมาถึงแล้ว", variants = { { "19:570737981:242848074 C 472:1972058740:89143695", "สวัสดี {class}รุ่นเยาว์ ถึงเวลาเรียนรู้ร่างสัตว์น้ำแล้ว ร่างนี้ทำให้เจ้าเคลื่อนที่ในน้ำได้อย่างอิสระโดยไม่จำกัดเวลา เป็นทั้งเครื่องมือที่มีประโยชน์และพรอันวิเศษ... แต่เจ้าต้องพิสูจน์ตนก่อนจะเชี่ยวชาญมัน\n\nเจ้าต้องผ่านบททดสอบสองอย่าง อย่างแรกทดสอบความสามารถในการทำงานใต้น้ำขณะถูกกดดัน อย่างที่สองทดสอบความมุ่งมั่นที่จะเข้าใจธรรมชาติของร่างนี้\n\nเตรียมตัวให้พร้อม เวลาแห่งบททดสอบมาถึงแล้ว" } } },
    },
    [28] = { -- Trial of the Lake
        title = { "17:1444350445:1544338901", "บททดสอบแห่งทะเลสาบ" },
        objective = { "223:1301896594:973178641", "หา Shrine Bauble ใน Lake Elune'ara แล้วนำไปใช้ในเขต Shrine of Remulos ทางตะวันตกเฉียงเหนือของ Moonglade จากนั้นคุยกับ Tajarri ที่ศาลเพื่อจบบททดสอบ" },
        description = { "485:2053445073:1802427861 N 1:46:46", "บททดสอบแรกคือค้นหา Shrine Bauble ใต้ Lake Elune'ara มันเสื่อมสภาพอย่างรวดเร็ว เมื่อได้มาแล้วจงรีบไป Shrine of Remulos ใช้มันที่ศาล แล้วคุยกับ Tajarri นางเป็นหนึ่งในผู้ดูแลที่ Moonglade ไว้วางใจที่สุด\n\nเจ้ามีเวลาทำงานนี้จำกัด และอาจมีดรูอิดคนอื่นค้นหาเครื่องประดับเช่นกัน ความคล่องแคล่วทั้งกายและใจจะเป็นสิ่งตัดสินความสำเร็จ\n\nขอให้โชคดี {name}" },
        progress = { "180:750634163:590115540", "เพื่อผ่านบททดสอบแห่งทะเลสาบ เจ้าต้องใช้ Shrine Bauble ภายในเขตศาลแห่งนี้ หากยังไม่ทำ บททดสอบก็ยังไม่จบ และเจ้าอาจล้มเหลวได้" },
        completion = { "491:1341538486:2107190367", "ดูเหมือนดรูอิดอีกคนจะผ่านบททดสอบแห่งทะเลสาบแล้ว! ทำได้ดี สหายรุ่นเยาว์ ทำได้ดีมาก\n\nอย่างที่บอก ข้าชื่อ Tajarri การเป็นผู้ดูแล Moonglade และโดยเฉพาะศาลนี้เป็นทั้งหน้าที่และเกียรติของข้า Keeper Remulos นำ Cenarion Circle ในการอนุรักษ์ธรรมชาติและสมดุล ศาลของเขาจึงเป็นอนุสรณ์ถาวรของหน้าที่นั้น การใช้เครื่องประดับที่นี่เป็นการแสดงความเคารพต่อความสำคัญของสถานที่แห่งนี้ในหมู่สมาชิก", variants = { { "36:1332151652:6860342 C 450:1000319765:458538969", "ดูเหมือน{class}อีกคนจะผ่านบททดสอบแห่งทะเลสาบแล้ว! ทำได้ดี สหายรุ่นเยาว์ ทำได้ดีมาก\n\nอย่างที่บอก ข้าชื่อ Tajarri การเป็นผู้ดูแล Moonglade และโดยเฉพาะศาลนี้เป็นทั้งหน้าที่และเกียรติของข้า Keeper Remulos นำ Cenarion Circle ในการอนุรักษ์ธรรมชาติและสมดุล ศาลของเขาจึงเป็นอนุสรณ์ถาวรของหน้าที่นั้น การใช้เครื่องประดับที่นี่เป็นการแสดงความเคารพต่อความสำคัญของสถานที่แห่งนี้ในหมู่สมาชิก" } } },
        objectiveLabels = {
            event = { ["Complete the Trial of the Lake."] = "ผ่านบททดสอบแห่งทะเลสาบ" },
        },
    },
    [30] = { -- Trial of the Sea Lion
        title = { "21:2016805535:1729864991", "บททดสอบแห่งสิงโตทะเล" },
        objective = { "391:1574831598:1854252636", "ค้นหา Half Pendant of Aquatic Agility และ Half Pendant of Aquatic Endurance โดยถามเบาะแสจากชาว Moonglade นำสองชิ้นมารวมเป็น Pendant of the Sea Lion ใกล้ Shrine of Remulos แล้วนำไปให้ Dendrite Starblaze ใน Nighthaven" },
        description = { "498:1866390467:144435855", "บททดสอบที่สองต้องใช้ชิ้นส่วนสองซีกของ Pendant of the Sea Lion ซีกหนึ่งดึงพลังจากความคล่องแคล่วของสิงโตทะเลที่แหวกว่ายผ่านน้ำ อีกซีกดึงพลังจากความทรหดอันน่าทึ่งของมัน ดรูอิดต้องใช้คุณสมบัติทั้งสองอย่างเท่าเทียมกันจึงจะเข้าถึงธรรมชาติของร่างสัตว์น้ำ\n\nถามคนใน Moonglade ว่าชิ้นส่วนอาจอยู่ที่ใด แล้วนำทั้งคู่กลับมาประกอบที่นี่ เมื่อได้จี้สมบูรณ์แล้ว นำไปให้ Dendrite Starblaze" },
        progress = { "48:1074811042:311868420 N 199:523394531:1685234929", "ประกอบจี้ให้ข้าตรวจแล้วหรือยัง {name}? ถ้ายังหาชิ้นส่วนไม่พบ ลองถามผู้คนในพื้นที่ดู นอกจากจะได้สิ่งที่ค้นหาแล้ว ยังเป็นโอกาสให้เจ้าสำรวจพงไพรศักดิ์สิทธิ์อันงดงามแห่งนี้ด้วย" },
        completion = { "44:443600241:1178139232 N 375:1914877955:369932871", "เจ้าผ่านบททดสอบแห่งสิงโตทะเลแล้ว {name} ยินดีด้วย\n\nทุกขั้นในการหาจี้พิสูจน์ว่าความคล่องแคล่วและความทรหดต้องทำงานประสานกัน เพื่อให้เจ้าทำสิ่งที่ต้องการใต้น้ำได้ ทั้งสองอย่างขาดกันไม่ได้ และจะเกิดขึ้นไม่ได้หากเจ้าไม่ยอมรับธรรมชาติแห่งสิงโตทะเล\n\nจดจำบทเรียนเหล่านี้ให้ดี และใช้มันเมื่อเจ้าเรียนรู้ร่างสัตว์น้ำแล้ว" },
        required = { [15885] = { "23:441182989:1318666459", "จี้สิงโตทะเล" } },
        steps = { { "23:441182989:1318666459", "จี้สิงโตทะเล" } },
    },
    [31] = { -- Aquatic Form
        title = { "12:74357176:1719203049", "ร่างสัตว์น้ำ" },
        objective = { "77:1499670418:768122298", "กลับ Thunder Bluff แล้วแสดง Pendant of the Sea Lion ให้ Turak Runetotem ดู" },
        description = { "380:513679578:209280858", "เจ้าผ่านบทเรียนที่ดรูอิดรุ่นเยาว์ต้องเรียนก่อนรับร่างว่ายน้ำแล้ว กลับไปหาอาจารย์ Turak Runetotem ที่ Thunder Bluff แสดงจี้เพื่อพิสูจน์ว่าพร้อมเรียน เขาจะฝึกขั้นสุดท้ายให้เป็นหนึ่งกับสายน้ำ\n\nลาก่อน ดรูอิดรุ่นเยาว์ เราจะได้คุยอีก", variants = { { "352:1763767012:1726130041 C 23:1928622257:2131200942", "เจ้าผ่านบทเรียนที่ดรูอิดรุ่นเยาว์ต้องเรียนก่อนรับร่างว่ายน้ำแล้ว กลับไปหาอาจารย์ Turak Runetotem ที่ Thunder Bluff แสดงจี้เพื่อพิสูจน์ว่าพร้อมเรียน เขาจะฝึกขั้นสุดท้ายให้เป็นหนึ่งกับสายน้ำ\n\nลาก่อน {class}รุ่นเยาว์ เราจะได้คุยอีก" } } },
        progress = { "200:559942300:1083284445", "ข่าวการกลับ Thunder Bluff ของเจ้ามาถึงแล้ว แต่ข้าต้องการหลักฐานบทเรียน Moonglade ก่อนสอนร่างว่ายน้ำ\n\nมี Pendant of the Sea Lion หรือไม่?" },
        completion = { "17:526312553:701486649 N 336:250335155:612235945", "น่าประทับใจมาก {name} บรรพบุรุษคงพอใจความก้าวหน้า! เจ้าพร้อมเรียนร่างว่ายน้ำ ข้ายินดีสอน\n\nอีกทั้งเพื่อยกย่องความสำเร็จในการทดสอบทั้งสอง ข้าให้ของนี้ หวังว่าจะเสริมอุปกรณ์ได้ดีในฐานะผู้ปกป้องธรรมชาติและรักษาสมดุล" },
        required = { [15885] = { "23:441182989:1318666459", "จี้สิงโตทะเล" } },
        steps = { { "23:441182989:1318666459", "จี้สิงโตทะเล" } },
    },
    [97] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
