    [98] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "60:2119858074:564570095", "สังหาร Stalvan Mistmantle แล้วนำแหวนตระกูลให้ Madame Eva ดู" },
        description = { "258:447343887:1505417438 C 226:934230004:997850291", "Stalvan Mistmantle ใช้ชีวิตเสื่อมทราม เหยื่อบริสุทธิ์ตายด้วยมือเขา มีความผิดนับไม่ถ้วนแน่ ตอนนี้คนบ้าคุกคาม Darkshire แสงสว่างเท่านั้นรู้ว่าคิดทำชั่วอะไร ไปกระท่อมเหนือเมือง {class} ประหาร Stalvan ให้สิ้นเรื่อง\n\nเมื่อเสร็จ ไป Madame Eva แสดงแหวนตระกูล ลางของนางนำสู่การค้นพบสยอง แต่ Darkshire ปลอดภัยเพราะนาง" },
        progress = { "5:1287366450:669725923 N 1:63:63", "มีอะไรหรือ {name}?" },
        completion = { "8:1991795802:1981362280 N 254:808745678:125227767 C 1:46:46", "ข้ารู้ {name} ว่า Stalvan ตายแล้ว รู้สึกคลื่นความหวังผ่านป่าแปดเปื้อน Duskwood พ้นกระหายเลือดเขาเสียที แต่ความยินดีเศร้าลงเมื่อนึกถึงเหยื่อสัตว์ร้าย ถึงอย่างไร เจ้าก็เป็น{class}ผู้กล้าและหลักแหลม" },
        required = { [3629] = { "22:1489665068:1834751904", "แหวนประจำตระกูล Mistmantle" } },
        steps = { { "22:1489665068:1834751904", "แหวนประจำตระกูล Mistmantle" } },
    },
    [493] = { -- Journey to Hillsbrad Foothills
        progress = { "26:1938204992:443522829", "มีอะไรมาให้ข้าหรือ?" },
        title = { "30:1678071997:1082049901", "เดินทางสู่เชิงเขาฮิลส์แบรด" },
        objective = { "114:537078874:1496361421", "ส่งผลการศึกษาของ Apothecary Renferrel ให้ Apothecary Lydon ที่เมือง Tarren Mill ใน Hillsbrad Foothills" },
        description = { "496:1180827893:1142699023", "เลดี้แห่งความมืดเร่งรัดสมาคมนักปรุงยาหลวงอย่างหนักให้พัฒนาโรคระบาดชนิดใหม่ เราทำงานเต็มที่และคืบหน้าไปมาก เราเชื่อว่าจะสำเร็จเร็วขึ้นมากหากแบ่งปันข้อมูลกันภายในสมาคม\n\nข้าจึงอยากให้เจ้านำผลศึกษาล่าสุดของข้าไปให้นักปรุงยาไลดอนที่ทาร์เรนมิลล์ เมืองเล็ก ๆ กลางเชิงเขาฮิลส์แบรด การเดินทางครั้งนี้อีกไกล\n\nมุ่งลงใต้และเดินตามถนนไว้ คอยดูป้ายบอกทางให้ดี!" },
        completion = { "95:1393451625:1097178969", "อา ยอดเยี่ยมมาก ข้านับถือนักปรุงยาเรนเฟอร์เรลอย่างยิ่ง ข้าอยากศึกษาผลงานของเขาเต็มที" },
        required = { [3468] = { "20:1839687772:2087862977", "ผลการค้นคว้าของ Renferrel" } },
        steps = { { "20:1839687772:2087862977", "ผลการค้นคว้าของ Renferrel" } },
    },
    [1220] = { -- Captain Vimes
        title = { "13:917180932:43117750", "Captain Vimes" },
        objective = { "47:355943135:965453802", "นำ Spy's Report ไปให้ Captain Garran Vimes" },
        description = { "51:740080879:1531444469 N 186:1690788829:1618587648", "Captain Vimes ควรเห็นรายงานที่พบ {name} รู้ภาษาออร์คดีกว่าคนส่วนมาก และควรรู้ว่ามีสายลับ Horde ใกล้ Theramore!\n\nเขาอยู่ค่ายทหารตะวันออกเฉียงเหนือเกาะ Theramore" },
        progress = { "26:1938204992:443522829", "มีอะไรมาให้ข้าหรือ?" },
        completion = { "87:1685058095:376579022", "รายงานสายลับออร์ค! หาอย่างไร? ช่างเถอะ มาดูว่าเขียนอะไร..." },
        required = { [5917] = { "12:1952028509:202289053", "รายงานของสายลับ" } },
        steps = { { "12:1952028509:202289053", "รายงานของสายลับ" } },
    },
    [1238] = { -- The Lost Report
        title = { "15:935316714:888713317", "รายงานที่หายไป" },
        objective = { "66:1500781753:381765905", "นำ Spy's Report ไปให้ Nazeer Bloodpike ที่ Brackenwall Village" },
        description = { "362:1182200305:1314555097", "คุ้ยดินร่วนพบมือออร์คขาด กำกระบอกกระดูกแกะ ภายในมีแผ่นหนังเปื้อนดิน\n\nเป็นรายงานออร์คที่ใช้หลายสัปดาห์สอดแนม Theramore\n\nอ่านคร่าว ๆ ชัดว่าต้องส่งให้หัวหน้าสายลับที่ Brackenwall Village" },
        progress = { "26:1938204992:443522829", "มีอะไรมาให้ข้าหรือ?" },
        completion = { "11:354343371:1318038540 N 214:976841769:1086770927", "ทำได้ดี {name} Marg Nighteye สายลับเราอยู่รอบ Theramore เฝ้าดูเมือง\n\nนี่รายงานล่าสุด อาจสุดท้าย จากคำเจ้า ข้ากลัวว่า Marg สิ้นในบึงแล้ว..." },
        required = { [5917] = { "12:1952028509:202289053", "รายงานของสายลับ" } },
        steps = { { "12:1952028509:202289053", "รายงานของสายลับ" } },
    },
    [1265] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "51:1507175633:749381762", "ค้นหาเบาะแสของ Private Hendel ที่ Sentry Point" },
        description = { "496:1208221172:627675378", "Hendel หรือ? ใช่ ข้ารู้จัก แต่เจ้าต้องการทหารของข้าทำไม?\n\nElling ส่งเจ้ามาหาเขาหรือ? อืม ฟังดูไม่ดีเลย ถ้าเรื่องของเจ้าไม่ยุ่งยาก Elling คงไม่ให้มาหาข้าก่อน ข้าเข้าใจหากเจ้าบอกไม่ได้ว่าเรื่องอะไร แต่จงรู้ไว้ ข้ามีหน้าที่ปกป้องดินแดนนี้ หากจะก่อความวุ่นวาย ข้าแนะนำให้บอกสิ่งที่บอกได้\n\nข้าเชื่อว่า Hendel ประจำการอยู่ที่หอคอยแรกนอก Theramore ระวังตัวด้วย" },
        progress = { "5:1287366450:669725923 N 1:63:63", "มีอะไรหรือ {name}?" },
        completion = { "309:2132806086:967946649", "ชายที่เจ้าตามหา คนชื่อ Hendel ไม่ได้อยู่ที่นี่ แหล่งข่าวอื่นนำข้อมูลที่ข้าเชื่อว่าเจ้ารู้แล้วไปแจ้ง Lady Proudmoore นางขอให้ข้าตามหาเจ้าและช่วยงาน หากเจ้ายอม ข้าจะบอกว่าพบ Private Hendel ได้ที่ไหน เพื่อให้เรานำเขามาลงโทษตามกฎหมาย" },
        objectiveLabels = {
            event = { ["Sentry Point explored"] = "สำรวจ Sentry Point" },
        },
    },
    [1359] = { -- Zinge's Delivery
        title = { "16:582128285:231021461", "ของส่งถึง Zinge" },
        objective = { "66:1026535174:1912080724", "นำ Wolf Heart Samples ไปให้ Apothecary Zinge ที่ Undercity" },
        description = { "369:1680228220:902701379", "หัวใจหมาป่าที่เจ้าได้มามีคุณสมบัติไม่เคยพบในตัวอย่างคล้ายกัน มันมีพิษที่น่าจะฆ่าหมาป่าเจ้าของหัวใจที่ยังเต้นอยู่เสียเอง!\n\nเหลือเชื่อจริง ๆ เราต้องศึกษาเพิ่ม ข้าเก็บตัวอย่างหัวใจไว้บางส่วน นำไปให้ Apothecary Zinge ผู้ร่วมงานข้า นางอยู่ในสำนักงานใหญ่ของเราที่ Undercity" },
        progress = { "26:1938204992:443522829", "มีอะไรมาให้ข้าหรือ?" },
        completion = { "188:294504211:184910702", "อา ใช่ ตัวอย่างหัวใจที่ Renferrel พูดถึง ข้าอยากทดลองกับมันแล้ว... Royal Apothecary Society สนใจเสมอเมื่อพบสารพิษรูปแบบใหม่" },
        required = { [10283] = { "18:1149571693:1966842101", "ตัวอย่างหัวใจหมาป่า" } },
        steps = { { "18:1149571693:1966842101", "ตัวอย่างหัวใจหมาป่า" } },
    },
    [1423] = { -- The Lost Supplies
        title = { "17:1751230028:1184608957", "เสบียงที่หายไป" },
        objective = { "50:1717495955:423092721", "นำ Lost Supplies ไปให้ Quartermaster Lungertz" },
        description = { "172:103930274:1245788809", "ถังเล็กแข็งแรง รอยต่อปิดขี้ผึ้งเหลืองกลิ่นฉุน ใต้ถังประทับว่า\n\nQUARTERMASTER LUNGERTZ\n\nNETHERGARDE KEEP" },
        progress = { "26:1938204992:443522829", "มีอะไรมาให้ข้าหรือ?" },
        completion = { "14:1880393010:821469394 N 93:1526560875:893340882", "อา ขอบใจ {name}! เสบียงหายมากระหว่าง Darkshire กับที่นี่ ดีที่บางส่วนได้คืน" },
    },
    [1522] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "32:517214061:826527541", "ไปหา Kranal Fiss ใน Barrens" },
        description = { "363:1825060345:792910220", "ขอให้ไฟอยู่กับเจ้า สหาย ข้าเห็นว่าเจ้าเข้มแข็งในวิถีดินแล้ว คิดว่าพร้อมไปคุยกับ Kranal\n\nเขาอยู่เหนือ Crossroads ใน Barrens เชี่ยวชาญวิถีธาตุและสอนวิถีไฟให้ได้... หากเจ้าคิดว่าพร้อม\n\nหาไม่ยาก แต่อย่าไปไกลเกิน ไม่อย่างนั้นจะหลงเข้าเขตเอลฟ์" },
        completion = { "284:448258370:665111022 N 121:390560675:1748854312", "อืม Searn ส่งเจ้ามาหาข้าหรือ?\n\nถ้าอย่างนั้น Searn ไว้ใจได้เสมอ แสดงว่าเจ้าพร้อมรับ Sapta ถัดไปแล้ว นั่นคือ Sapta แห่งไฟ\n\nข้าเห็นในดวงตาแล้ว ทั้งเปลวเพลิงและความปรารถนา เจ้าได้ลิ้มรสพลังและพร้อมรับเพิ่ม จงอดทน {name} จำสิ่งที่ดินสอนไว้ พลังและการทำลายมาได้ง่าย แต่ยังต้องรู้ว่าเมื่อใดควรยั้งมือ" },
    },
    [1523] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "32:517214061:826527541", "ไปหา Kranal Fiss ใน Barrens" },
        description = { "45:400966455:117256069 N 416:271062082:2109658973", "นานแล้วนับจากบททดสอบครั้งก่อน {name} เจ้าศึกษาอย่างอดทน แต่ถึงเวลาเรียนรู้เพิ่ม ถึงเวลาเรียนรู้การทำลาย... และความโกลาหล หากพร้อมจ่ายราคา เจ้าก็จะเข้าใจธาตุไฟได้\n\nไปหา Kranal Fiss ใน Barrens เขาอยู่บ้านเล็กทางเหนือของ Crossroads ระวัง หากไปถึงดินแดนไนต์เอลฟ์ แสดงว่าเลยไปแล้ว" },
        completion = { "282:1270030632:262102302 N 121:390560675:1748854312", "อืม Narm ส่งเจ้ามาหาข้าหรือ?\n\nถ้าอย่างนั้น Narm ไว้ใจได้เสมอ แสดงว่าเจ้าพร้อมรับ Sapta ถัดไปแล้ว นั่นคือ Sapta แห่งไฟ\n\nข้าเห็นในดวงตาแล้ว ทั้งเปลวเพลิงและความปรารถนา เจ้าได้ลิ้มรสพลังและพร้อมรับเพิ่ม จงอดทน {name} จำสิ่งที่ดินสอนไว้ พลังและการทำลายมาได้ง่าย แต่ยังต้องรู้ว่าเมื่อใดควรยั้งมือ" },
    },
    [1524] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "63:1163277357:686487800", "นำ Torch of the Dormant Flame ไปให้ Telf Joolam ใน Durotar" },
        description = { "504:1068740303:1714577191", "เจ้ามีพลังพอใช้โทเทมไฟ แต่ไม่ได้แปลว่าพร้อมแล้ว\n\nริม Southfury River ใน Durotar ก่อนถึง Great Sea มีทางลับขึ้นยอดเขาที่สูงที่สุดแห่งหนึ่ง หาทางขึ้นไปจะพบศาลศักดิ์สิทธิ์ที่ Telf Joolam ดูแล นั่นคือ Shrine of the Dormant Flame\n\nนำคบเพลิงนี้ไปให้เขา เป็นเครื่องหมายว่าเจ้ามาลองสยบไฟ จุดมันกับกระถางไฟที่ศาลแล้วนำกลับมา ข้าจะจัดให้เจ้าได้รับโทเทมไฟ" },
        progress = { "11:1988767264:581875424 N 388:872099827:1493055298", "สวัสดี {name} เจ้ามาถึง Shrine of the Dormant Flame แล้ว มีเพียงผู้รู้ศาสตร์ชาแมนมากพอจึงเรียนรู้ความลับและพลังของที่นี่ได้ ข้าเสียใจที่เจ้าต้องเดินทางมาไกลแล้วถูกส่งกลับ ทั้งที่ทางขึ้นไม่ปลอดภัยเลย แต่ข้าเป็นผู้ดูแลศาล จะปล่อยให้ใครก็ได้เดินเล่นแถวนี้ไม่ได้" },
        completion = { "16:151171927:1675369575 N 301:378603922:248614864 N 96:694335121:650781501", "อา ข้าเข้าใจผิด ขอโทษด้วย {name} ไม่ทันรู้ว่าเจ้ามีคบเพลิง ยินดีที่ได้รู้จัก\n\nนักผจญภัยมากมายมาถึงนี่เพื่อตามหาสมบัติสูญหายหรือหวังฆ่าสัตว์วิเศษ แล้วก็ถูกไล่กลับจากศาลที่ดูว่างเปล่า แต่เรารู้ความจริง ใช่ไหม {name}?\n\nศาลนี้เก็บความลับที่ยิ่งใหญ่กว่าสิ่งที่สมาชิก Horde ทั่วไปมองเห็น สำหรับพวกเรา มันศักดิ์สิทธิ์" },
        required = { [6653] = { "26:917262829:1125779937", "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" } },
        steps = { { "26:917262829:1125779937", "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" } },
    },
    [1525] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "63:495735078:1180040133", "นำ Fire Tar 1 ชิ้นและ Reagent Pouch 1 ถุงไปให้ Telf Joolam ใน Durotar" },
        description = { "502:198220211:952106215", "แต่เจ้าไม่ได้มาเรียนประวัติศาสตร์ใช่ไหม? เจ้ามาหา Eternal Flame และโทเทมไฟ\n\nขั้นแรกคือปรุง Sapta เพื่อผูกเจ้ากับเปลวเพลิง\n\nข้าปรุง Fire Sapta ให้ได้ หากนำของสองอย่างมา อย่างแรกคือ Fire Tar ของธรรมดาที่ผู้ใช้เวท Razormane ใน Barrens ตะวันออกมักพก\n\nอย่างที่สองอันตรายกว่า เป็น Reagent Pouch จากสาวก Burning Blade พบพวกมันได้ในถ้ำเหนือหุบผาทางตะวันออกเฉียงเหนือของ Razor Hill" },
        progress = { "464:1844805294:64376734", "หากเจ้าหา Reagent Pouch กับ Fire Tar มาได้ ข้าก็มีส่วนผสมพอปรุง Sapta แห่งไฟ พวกคลั่ง Burning Blade ใส่วัตถุดิบคาถาส่วนใหญ่ไว้ในถุง มักมีของที่ข้าต้องการพอแล้ว เราจึงไม่ต้องตามหาอะไรอื่นไกลนัก\n\nSapta ปรุงจากวัตถุดิบที่ผูกพันใกล้ชิดกับธาตุของมันเสมอ ความสัมพันธ์ของวอร์ล็อกกับไฟทำให้งานเราง่ายขึ้น" },
        completion = { "22:1465595043:356124885 N 432:1470013480:227832243", "ของพวกนี้ใช้ได้ดี {name}\n\nไฟเป็นมากกว่าความโกลาหลและการทำลาย จำให้ดี มันหมายถึงชีวิตและการสร้างด้วย ทุกสิ่งเชื่อมกันเช่นนี้ พลังต่าง ๆ ต่อต้านกัน แต่ก็อยู่ไม่ได้หากขาดอีกฝ่าย ทั้งดับกันและให้ความหมายแก่กัน จงจำไว้เสมอ\n\nการใช้เวทต่างประเภทประสานกันไม่เพียงแสดงฝีมือแท้จริง แต่ยังแสดงปัญญาอันยิ่งใหญ่" },
        required = { [5026] = { "8:304876206:1308605072", "น้ำมันดินติดไฟ" }, [6652] = { "13:1447175775:111746688", "ถุงใส่วัตถุดิบ" } },
        steps = { { "8:304876206:1308605072", "น้ำมันดินติดไฟ" }, { "13:1447175775:111746688", "ถุงใส่วัตถุดิบ" } },
    },
    [1526] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "116:2039297308:1420536102", "ปราบ Minor Manifestation of Fire แล้ววาง Glowing Ember ในกระถางไฟบน Shrine of Eternal Flame" },
        description = { "280:2121388865:2106066425 N 152:1279558213:1260757639", "Fire Sapta เสร็จแล้ว ถึงเวลาเผชิญเปลวเพลิง ใช้ Sapta ที่ศาลแล้วขึ้นยอดเขาไปพบร่างสำแดง มันจะไม่โจมตีจนกว่าเจ้าพร้อม แต่จะรู้ว่าเจ้ามองเห็นมัน\n\nโค่นมันให้รวดเร็ว {name} เพราะยิ่งฆ่าช้า มันยิ่งแข็งแกร่ง เมื่อปราบแล้ว วางถ่านคุในกระถางไฟและจุดคบเพลิง" },
        progress = { "232:114141131:1768313054", "กระถางไฟสูงราวหนึ่งในสามของตัวเจ้า ดูธรรมดานอกจากอักขระบนราวโลหะเรียบ โลหะไม่มีรอยสึกจากอากาศ และชามด้านบนเย็นเมื่อสัมผัส" },
        completion = { "275:203254496:356261061", "เมื่อวางถ่านคุลงในชาม เปลวไฟร้อนขาวก็ลุกขึ้น เจ้ารู้สึกถึงเวทของ Sapta ไหลผ่านร่าง เปลวเพลิงเต้นเป็นจังหวะเบื้องหน้า\n\nเจ้าสอดปลายคบเพลิงลงในอ่าง มันติดไฟทันที" },
        required = { [6653] = { "26:917262829:1125779937", "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" }, [6655] = { "13:805808827:514952864", "ถ่านคุเรืองแสง" } },
        steps = { { "26:917262829:1125779937", "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" }, { "13:805808827:514952864", "ถ่านคุเรืองแสง" } },
    },
    [1527] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "63:2142408754:587390885", "นำ Torch of Eternal Flame ไปให้ Kranal Fiss ใน Barrens" },
        description = { "261:2147347494:1307499340", "เจ้ากำคบเพลิงแน่น หันจากกระถางไฟไปมองทั่ว Durotar ความตื่นเต้นดึงรั้งจิตใจเมื่อลมแรงขึ้นและพัดเปลวไฟให้เต้นรุนแรง\n\nเจ้าเริ่มลงตามทางกลับ Barrens เพื่อตามหา Kranal Fiss" },
        progress = { "5:1287366450:669725923 N 25:2015429522:298869124", "ว่าอย่างไร {name}? ในมือเจ้าคืออะไร?" },
        completion = { "58:1943442682:1909906781 N 244:618919080:1571594177", "จิตวิญญาณเจ้าลุกโชนสว่างกว่าคบเพลิงใดที่ข้าเคยเห็น {name} เจ้าควรภูมิใจ\n\nหากเดินเส้นทางนี้ต่อ เจ้าจะบัญชาธาตุได้ และพี่น้องเราจะมาขอคำชี้ทางกับปัญญาจากเจ้า ข้าขอเป็นคนแรกที่แสดงความยินดีและมอบโทเทมชิ้นใหม่ให้" },
        required = { [6654] = { "26:425046618:568461893", "คบเพลิงแห่งเปลวไฟนิรันดร์" } },
        objectiveLabels = {
            item = { ["Torch of the Eternal Flame"] = "คบเพลิงแห่งเปลวไฟนิรันดร์" },
        },
    },
    [2983] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "32:517214061:826527541", "ไปหา Kranal Fiss ใน Barrens" },
        description = { "48:1740638867:1740192215 N 376:1706732873:1993693459", "ผ่านมาพักหนึ่งแล้วนับจากบททดสอบก่อน {name} เจ้าเรียนอย่างอดทน แต่ถึงเวลารู้จักพลังที่ยิ่งกว่า... ถึงเวลาเรียนรู้พลังแท้จริง หากพร้อมจ่ายราคา ธาตุไฟจะเป็นของเจ้า\n\nไปหา Kranal Fiss ใน Barrens เขาอยู่บ้านเล็กเหนือ Crossroads ระวัง หากไปถึงดินแดนไนต์เอลฟ์น่าชัง แสดงว่าเลยไปไกลมากแล้ว" },
        completion = { "284:1664139189:1922790533 N 121:390560675:1748854312", "อืม Swart ส่งเจ้ามาหาข้าหรือ?\n\nถ้าอย่างนั้น Swart ไว้ใจได้เสมอ แสดงว่าเจ้าพร้อมรับ Sapta ถัดไปแล้ว นั่นคือ Sapta แห่งไฟ\n\nข้าเห็นในดวงตาแล้ว ทั้งเปลวเพลิงและความปรารถนา เจ้าได้ลิ้มรสพลังและพร้อมรับเพิ่ม จงอดทน {name} จำสิ่งที่ดินสอนไว้ พลังและการทำลายมาได้ง่าย แต่ยังต้องรู้ว่าเมื่อใดควรยั้งมือ" },
    },
    [2984] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "32:517214061:826527541", "ไปหา Kranal Fiss ใน Barrens" },
        description = { "45:400966455:117256069 N 416:271062082:2109658973", "นานแล้วนับจากบททดสอบครั้งก่อน {name} เจ้าศึกษาอย่างอดทน แต่ถึงเวลาเรียนรู้เพิ่ม ถึงเวลาเรียนรู้การทำลาย... และความโกลาหล หากพร้อมจ่ายราคา เจ้าก็จะเข้าใจธาตุไฟได้\n\nไปหา Kranal Fiss ใน Barrens เขาอยู่บ้านเล็กทางเหนือของ Crossroads ระวัง หากไปถึงดินแดนไนต์เอลฟ์ แสดงว่าเลยไปแล้ว" },
        completion = { "282:1270030632:262102302 N 121:390560675:1748854312", "อืม Narm ส่งเจ้ามาหาข้าหรือ?\n\nถ้าอย่างนั้น Narm ไว้ใจได้เสมอ แสดงว่าเจ้าพร้อมรับ Sapta ถัดไปแล้ว นั่นคือ Sapta แห่งไฟ\n\nข้าเห็นในดวงตาแล้ว ทั้งเปลวเพลิงและความปรารถนา เจ้าได้ลิ้มรสพลังและพร้อมรับเพิ่ม จงอดทน {name} จำสิ่งที่ดินสอนไว้ พลังและการทำลายมาได้ง่าย แต่ยังต้องรู้ว่าเมื่อใดควรยั้งมือ" },
    },
    [5922] = { -- Moonglade
        title = { "9:1802734789:1124844045", "มูนเกลด" },
        objective = { "136:1565490422:1029565360", "ใช้เวท Teleport: Moonglade เดินทางไป Moonglade แล้วคุยกับ Dendrite Starblaze ในหมู่บ้าน Nighthaven" },
        description = { "493:1435082555:70586482", "ดรูอิดทุกคนได้รับการต้อนรับสู่ Moonglade อันศักดิ์สิทธิ์ ทั้งทอเรนและไนต์เอลฟ์ Keeper Remulos ผู้พิทักษ์ของเราเฝ้าดูแลดรูอิดที่จำศีลอยู่ เมื่อเจ้าเรียนวิถีแห่งกงเล็บ ข้าจะสอนเวทที่พาตัวเจ้าไปที่นั่น ใช้มันเมื่อแสวงหาความรู้หรือความสงบใจจาก Moonglade\n\nสำหรับบทเรียนแรก จงไปคุยกับ Dendrite Starblaze ที่ Nighthaven เรื่องหนทางใหม่ของเจ้า โชคดี ดรูอิดรุ่นเยาว์" },
        completion = { "374:278323581:119063747", "“และแล้วทุกอย่างก็เริ่มขึ้น บิดา Cenarius และแล้วก็เริ่มขึ้น”\n\nDendrite ทำท่าบางอย่างอย่างรวดเร็วกลางอากาศเหนือศีรษะ แม้มองไม่เห็นสิ่งที่เขาวาด แต่รัศมีพลังบางเบาก็คลุมตัวเขา\n\n“มุมมองแรกของธรรมชาติที่เจ้าต้องเรียนรู้คือมุมมองของหมี ข้าจะพาเจ้าเข้าสู่หนทางแห่งความเข้าใจในชีวิตดรูอิดด้านนี้ แต่เจ้าต้องเป็นผู้ยอมรับและสืบทอดมันด้วยตนเอง ทั้งในวันนี้และตลอดไป!”", variants = { { "372:985667623:1093892568", "และแล้วก็เริ่มขึ้น บิดา Cenarius และแล้วก็เริ่มขึ้น\n\n<Dendrite ทำท่าบางอย่างรวดเร็วกลางอากาศเหนือศีรษะ แม้มองไม่เห็นสิ่งที่เขาวาด แต่รัศมีพลังบางเบาก็คลุมตัวเขา>\n\nมุมมองแรกของธรรมชาติที่เจ้าต้องปรับตัวให้เข้ากับมันคือมุมมองของหมี ข้าจะพาเจ้าเข้าสู่หนทางแห่งความเข้าใจชีวิตดรูอิดในด้านนี้ แต่เจ้าต้องเป็นผู้ยอมรับและสืบทอดด้วยตนเอง ทั้งบัดนี้และตลอดไป!" } } },
    },
    [5926] = { -- Heeding the Call
        title = { "16:1185260992:259476408", "ขานรับเสียงเรียก" },
        objective = { "62:1264616527:404812951", "คุยกับ Turak Runetotem บน Elder Rise ใน Thunder Bluff" },
        description = { "437:917478735:1061288461", "ขออภัย สหาย...\n\nข้าทราบว่า Turak Runetotem ส่งข่าวอยากคุย ดูการฝึกดรูอิดกำลังเริ่มช่วงใหม่ เขาจะสอนเอง Turak เป็นผู้ช่วย Arch Druid คนหนึ่ง รอบรู้และอดทน คงสอนได้ดี\n\nเขาอยู่ในกระโจมหลัก Cenarion Circle บน Elder Rise ใน Thunder Bluff" },
        completion = { "470:968059591:1117137740", "ดีใจที่เจ้าหาทางมาถึงที่นี่ในวันนี้ ดรูอิดรุ่นเยาว์ ถึงเวลาแล้วที่เจ้าจะก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิม\n\nในตัวลูกหลานของ Cenarius ทุกคนมีเสียงเรียกให้รับใช้ธรรมชาติ สัตว์และพืชเป็นทั้งสหายและผู้ที่เราเฝ้าดูแล เราเลือกอุทิศชีวิตเพื่อรักษาสมดุล ทั้งเพื่อพวกเขาและตัวเราเอง ก้าวแรกของเจ้าคือเรียนรู้วิถีของหมี และพลังแห่งกายกับใจ\n\nเตรียมตัวให้พร้อม!", variants = { { "47:608153914:1342807793 C 418:1421579562:2003121929", "ดีใจที่เจ้าหาทางมาถึงที่นี่ในวันนี้ {class}รุ่นเยาว์ ถึงเวลาแล้วที่เจ้าจะก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิม\n\nในตัวลูกหลานของ Cenarius ทุกคนมีเสียงเรียกให้รับใช้ธรรมชาติ สัตว์และพืชเป็นทั้งสหายและผู้ที่เราเฝ้าดูแล เราเลือกอุทิศชีวิตเพื่อรักษาสมดุล ทั้งเพื่อพวกเขาและตัวเราเอง ก้าวแรกของเจ้าคือเรียนรู้วิถีของหมี และพลังแห่งกายกับใจ\n\nเตรียมตัวให้พร้อม!" } } },
    },
    [5927] = { -- Heeding the Call
        title = { "16:1185260992:259476408", "ขานรับเสียงเรียก" },
