        completion = { "47:608153914:1342807793 C 418:1421579562:2003121929", "ดีใจที่เจ้ามาถึงที่นี่ในวันนี้ ดรูอิดรุ่นเยาว์ ถึงเวลาที่เจ้าจะก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิม\n\nในตัวลูกหลานของ Cenarius ทุกคนมีเสียงเรียกให้รับใช้ธรรมชาติ สัตว์และพืชเป็นทั้งสหายและผู้ที่เราเฝ้าดูแล เราเลือกอุทิศชีวิตเพื่อรักษาสมดุล ทั้งเพื่อพวกเขาและตัวเราเอง ก้าวแรกของเจ้าคือเรียนรู้วิถีแห่งหมี และเข้าใจความแข็งแกร่งของกายและใจ\n\nเตรียมตัวให้พร้อม!", variants = { { "47:1509510827:1619745797 C 418:1421579562:2003121929", "ดีใจที่เจ้ามาถึงที่นี่ในวันนี้ {class}รุ่นเยาว์ ถึงเวลาที่เจ้าจะก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิม\n\nในตัวลูกหลานของ Cenarius ทุกคนมีเสียงเรียกให้รับใช้ธรรมชาติ สัตว์และพืชเป็นทั้งสหายและผู้ที่เราเฝ้าดูแล เราเลือกอุทิศชีวิตเพื่อรักษาสมดุล ทั้งเพื่อพวกเขาและตัวเราเอง ก้าวแรกของเจ้าคือเรียนรู้วิถีแห่งหมี และเข้าใจความแข็งแกร่งของกายและใจ\n\nเตรียมตัวให้พร้อม!" } } },
    },
    [5928] = { -- Heeding the Call
