        completion = { "47:608153914:1342807793 C 418:1421579562:2003121929", "ดีใจที่เจ้ามาถึงที่นี่ในวันนี้ ดรูอิดรุ่นเยาว์ ถึงเวลาที่เจ้าจะก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิม\n\nในตัวลูกหลานของ Cenarius ทุกคนมีเสียงเรียกให้รับใช้ธรรมชาติ สัตว์และพืชเป็นทั้งสหายและผู้ที่เราเฝ้าดูแล เราเลือกอุทิศชีวิตเพื่อรักษาสมดุล ทั้งเพื่อพวกเขาและตัวเราเอง ก้าวแรกของเจ้าคือเรียนรู้วิถีแห่งหมี และเข้าใจความแข็งแกร่งของกายและใจ\n\nเตรียมตัวให้พร้อม!", variants = { { "47:1509510827:1619745797 C 418:1421579562:2003121929", "ดีใจที่เจ้ามาถึงที่นี่ในวันนี้ {class}รุ่นเยาว์ ถึงเวลาที่เจ้าจะก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิม\n\nในตัวลูกหลานของ Cenarius ทุกคนมีเสียงเรียกให้รับใช้ธรรมชาติ สัตว์และพืชเป็นทั้งสหายและผู้ที่เราเฝ้าดูแล เราเลือกอุทิศชีวิตเพื่อรักษาสมดุล ทั้งเพื่อพวกเขาและตัวเราเอง ก้าวแรกของเจ้าคือเรียนรู้วิถีแห่งหมี และเข้าใจความแข็งแกร่งของกายและใจ\n\nเตรียมตัวให้พร้อม!" } } },
    },
    [5930] = { -- Great Bear Spirit
        title = { "17:848111912:388628440", "มหาวิญญาณหมี" },
        objective = { "196:546153198:1499699183", "ไปหา Great Bear Spirit ทางตะวันตกเฉียงเหนือของ Moonglade เรียนรู้ธรรมชาติของหมี แล้วกลับไปหา Dendrite Starblaze ใน Nighthaven" },
        description = { "498:521245163:849802520", "ทางตะวันตกเฉียงเหนือของ Moonglade เป็นที่พำนักของผู้มีปัญญาและสูงส่งที่เราเรียกว่า Great Bear Spirit เขาเป็นครูและผู้ชี้ทางให้ดรูอิดทุกคนเริ่มเข้าใจธรรมชาติของหมีอย่างแท้จริง ดรูอิดทุกคนต้องไปขอปัญญาจากเขาสักครั้ง และเจ้าก็เช่นกัน\n\nจงไปหา Great Bear Spirit แล้วเรียนรู้สิ่งที่เขาสอน เมื่อเขาพอใจในตัวเจ้าแล้ว ค่อยกลับมาหาข้าที่ Nighthaven จากนั้นเราจะดูว่าเจ้าได้เข้าใจบทเรียนเหล่านั้นจริงหรือไม่" },
        progress = { "121:228743085:1207218891", "จงกลับมาเมื่อ Great Bear Spirit อนุญาตให้เจ้ากลับมาหาข้าแล้วเท่านั้น การฝึกจะดำเนินต่อไม่ได้หากปราศจากพรของเขา" },
        completion = { "405:1355561431:1814612526", "เมื่อเจ้าเข้าใกล้ Dendrite ก็ทำท่าบางอย่างกลางอากาศเหนือศีรษะอีกครั้ง รัศมีพลังอีกระลอกคลุมตัวเขา และเขายิ้มเล็กน้อย\n\n“ข้าสัมผัสได้ถึงปัญญาในตัวเจ้าที่ไม่เคยมีเมื่อแรกพบ เจ้ามองข้าด้วยความแข็งแกร่งและความมุ่งมั่นที่รู้ชัด แต่ยังไม่ได้รวมใจไว้ที่จุดหมาย ต่อจากนี้เจ้าจะเรียนรู้การควบคุมกำลัง และนำธรรมชาติแห่งหมีมาใช้ในหน้าที่ของเจ้า”", variants = { { "405:1942604598:893650814", "<เมื่อเจ้าเข้าใกล้ Dendrite ก็ทำท่าบางอย่างกลางอากาศเหนือศีรษะอีกครั้งโดยมองไม่เห็นสิ่งที่เขาวาด รัศมีพลังอีกระลอกคลุมตัวเขา และเขายิ้มเล็กน้อย>\n\nข้าสัมผัสได้ถึงปัญญาในตัวเจ้า เยาวชนเอ๋ย ปัญญาที่ไม่เคยมีเมื่อแรกพบ เจ้ามองข้าด้วยความแข็งแกร่งและความมุ่งมั่นที่รู้ชัด แต่ความมุ่งมั่นนั้นยังไร้จุดหมาย ต่อจากนี้เจ้าจะได้เรียนรู้วิธีรวบรวมกำลัง และนำธรรมชาติของหมีมาใช้ในหน้าที่ของเจ้า" } } },
        objectiveLabels = {
            event = { ["Seek out the Great Bear Spirit and learn what it has to share with you about the nature of the bear."] = "ไปหา Great Bear Spirit และฟังคำสอนเกี่ยวกับธรรมชาติของหมี" },
        },
    },
    [6002] = { -- Body and Heart
        title = { "14:1828490291:1320258704", "กายและใจ" },
        objective = { "256:520868668:1221656249", "ใช้ Cenarion Lunardust กับ Moonkin Stone ระหว่าง Mulgore และ Barrens เพื่อเรียก Lunaclaw แล้วเผชิญหน้าเพื่อให้ได้พลังแห่งกายและใจที่มันมี\n\nเสร็จแล้วคุยกับ Turak Runetotem ที่ Thunder Bluff" },
        description = { "380:1890747243:241505602 N 121:1968591758:1820740855", "ทางตะวันตกของ Taurajo ใน Barrens ก่อนเข้าสู่ Mulgore มี Moonkin Stone อยู่ มูนคินเป็นสัตว์พิเศษที่ไม่ได้มีถิ่นกำเนิดแถวนั้น Lunaclaw ผู้พิทักษ์ศิลาจะปรากฏตัวเมื่อเจ้าใช้ Cenarion Lunardust มันมีพลังที่ผู้เดินวิถีแห่งกงเล็บต้องเรียนรู้\n\nเจ้าได้สิทธิ์ใช้ผงนี้แล้ว {name}... จงแสดงว่าเจ้าคู่ควรกับพลังแห่งกายและใจที่ดรูอิดต้องมี!" },
        progress = { "184:351410539:2107625378", "เมื่อเจ้าผ่านบททดสอบตรงหน้าแล้ว เจ้าจะเข้าใจความแข็งแกร่งของกายและใจอย่างสมบูรณ์ ก่อนถึงตอนนั้น ข้าช่วยเจ้าได้เพียงเท่านี้" },
        completion = { "65:1931216444:197230214 N 240:702011879:1140618870", "ในที่สุดเจ้าก็ก้าวครั้งสำคัญสู่โลกที่กว้างใหญ่กว่าเดิมแล้ว {name} ข้าสัมผัสได้ถึงคำสอนของ Great Bear Spirit ในตัวเจ้า และรู้ว่าเจ้าได้รับพลังที่ Lunaclaw ครอบครองแล้ว\n\nไม่มีอุปสรรคขวางเจ้าอีก... ข้าจะสอนให้เจ้ารู้ว่าการเป็นดรูอิดแห่งกรงเล็บหมายถึงอะไร!" },
        objectiveLabels = {
            event = { ["Face Lunaclaw and earn the strength of body and heart it possesses."] = "เผชิญหน้ากับ Lunaclaw และรับพลังแห่งกายและใจที่มันมี" },
        },
    },
    [6061] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "137:930636230:1713122438", "ใช้ Taming Rod ฝึก Adult Plainstrider ให้เชื่อง ฝึกทักษะแล้วคืน Taming Rod ให้ Yaw Sharpmane ที่ Bloodhoof Village" },
        description = { "500:1876942099:327660450", "ในฐานะทอเรน เราต้องทำตามประเพณีบรรพบุรุษด้วยการต่อสู้กับสัตว์ที่ทรงพลัง เมื่อชนะ เราจะรับวิญญาณของมันและเข้าใกล้ Earthmother ยิ่งขึ้น\n\nเช่นเดียวกัน การฝึกสัตว์ให้ร่วมรบจะช่วยให้เจ้าเป็นหนึ่งกับธรรมชาติรอบตัว ในที่สุดเจ้าจะฝึกสัตว์ที่เลือกเองได้ แต่ต้องอาศัยการฝึกฝน เจ้ายังต้องเรียนรู้อีกมาก เริ่มจากรับ Taming Rod นี้ไปฝึก Adult Plainstrider ให้เชื่อง" },
        progress = { "22:2096779047:1608594192 N 30:2076639223:2130346880", "ฝึกทักษะ {name} ฝึก Adult Plainstrider ให้เชื่อง" },
        completion = { "67:849012994:632121885", "Earthmother ส่งสัญญาณแก่ข้า เจ้าทำได้ดี" },
        required = { [15914] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame an Adult Plainstrider"] = "ฝึก Adult Plainstrider ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
    [6062] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "121:799305643:117244117", "ใช้ Taming Rod ฝึก Dire Mottled Boar ให้เชื่อง ฝึกทักษะแล้วคืน Taming Rod ให้ Thotar ที่ Razor Hill" },
        description = { "495:2134103575:1595820063", "การควบคุมพลังธรรมชาติเป็นทักษะที่น่าชื่นชม พรานต้องตั้งใจเรียนรู้ที่จะใช้กำลังและพลังของสิ่งมีชีวิตที่ตนเลือก\n\nการควบคุมสัตว์ไม่ใช่เรื่องง่าย ต้องใช้ความมุ่งมั่นอย่างมาก\n\nสำหรับงานแรก จงนำ Taming Rod นี้ไปฝึก Dire Mottled Boar ให้เชื่อง หาได้ใกล้ Razor Hill ลองต่อสู้โดยมีหมูป่าข้างกายแล้วกลับมา", variants = { { "70:1251533292:52799588 C 419:146607608:220201714", "การควบคุมพลังธรรมชาติเป็นทักษะที่น่าชื่นชม {class}ต้องตั้งใจเรียนรู้ที่จะใช้กำลังและพลังของสิ่งมีชีวิตที่ตนเลือก\n\nการควบคุมสัตว์ไม่ใช่เรื่องง่าย ต้องใช้ความมุ่งมั่นอย่างมาก\n\nสำหรับงานแรก จงนำ Taming Rod นี้ไปฝึก Dire Mottled Boar ให้เชื่อง หาได้ใกล้ Razor Hill ลองต่อสู้โดยมีหมูป่าข้างกายแล้วกลับมา" } } },
        progress = { "24:386159516:431526124", "โชคดี พรานรุ่นเยาว์" },
        completion = { "20:1921578502:569519135 N 45:123680934:579565083", "ทำได้ดี {name} ข้าเชื่อว่าพร้อมงานต่อไป" },
        required = { [15917] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame a Dire Mottled Boar"] = "ฝึก Dire Mottled Boar ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
    [6064] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "125:1966524697:1772041377", "ใช้ Taming Rod ฝึก Large Crag Boar ให้เชื่อง ฝึกทักษะแล้วคืน Taming Rod ให้ Grif Wildheart ที่ Kharanos" },
        description = { { "483:143464828:810338037", "484:1693925019:2085572814" }, "สวัสดีเจ้าหนู! อยากรู้วิธีมีสัตว์เลี้ยงของตนหรือ?\n\nมาเริ่ม ไม่มีอะไรสำคัญกว่าอุปกรณ์เมื่อล่า แต่ไว้คุยเรื่อง Shrapnel Blaster ใหม่ของข้าคราวหลัง ตอนนี้สนใจสิ่งที่เจ้าคงอยากรู้ สัตว์เลี้ยง!\n\nดีที่สุดคือลองสัตว์หลายชนิดร่วมทางแล้วดูว่าชอบอะไร หา Large Crag Boar ใช้ Taming Rod ฝึกให้เชื่อง" },
        progress = { "84:1061513543:1167505584", "อย่าห่วง สาวน้อย! จะได้ลองหลายชนิดก่อนเลือกเพียงหนึ่ง", variants = { { "83:466068888:1984161105", "อย่ากังวลไป เจ้าหนุ่ม! เจ้ายังได้ลองฝึกกับสัตว์อีกสองสามชนิด ก่อนจะต้องตัดสินใจเลือกสักตัว" } } },
        completion = { "57:1951443053:1020311852", "ข้ารู้ ข้ารู้ เจ้าอยากรู้ว่าต่อไปอะไรใช่ไหม?!" },
        required = { [15911] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame a Large Crag Boar"] = "ฝึก Large Crag Boar ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
