    [6081] = { -- Training the Beast
        title = { "18:955897086:1132620325", "ฝึกฝนสหายร่วมทาง" },
        objective = { "39:1801721448:1504249285", "คุยกับ Ormak Grimshot ที่ Orgrimmar" },
        description = { "288:1221642555:776408000 N 1:46:46", "ตอนนี้ฝึกสัตว์ให้เชื่องได้ แต่ต้องมีทักษะสอนมันด้วย\n\nไป Orgrimmar คุย Ormak Grimshot พรานที่เราเคารพที่สุดคนหนึ่ง เขาจะให้ความสามารถฝึกสัตว์ใหม่ พบใกล้ Hall of the Brave\n\nโชคดี {name}" },
        completion = { "294:80737536:1146114809", "พรานรุ่นเยาว์สินะ ใช่ ข้าจะให้ทักษะฝึกและชี้นำสัตว์ ไม่เพียงสอนความสามารถใหม่ แต่ให้อาหารและชุบชีวิตได้หากมันล้มในศึก\n\nไปเถิด พราน เราจะคุยอีกวันหน้า", variants = { { "8:1681554422:196453020 C 235:34175139:16274646 C 39:2105966707:279003156", "{class}รุ่นเยาว์สินะ ใช่ ข้าจะให้ทักษะฝึกและชี้นำสัตว์ ไม่เพียงสอนความสามารถใหม่ แต่ให้อาหารและชุบชีวิตได้หากมันล้มในศึก\n\nไปเถิด {class} เราจะคุยอีกวันหน้า" } } },
    },
    [6082] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "105:1895193674:1715775717", "ใช้ Taming Rod ฝึก Armored Scorpid ให้เชื่อง ฝึกทักษะแล้วกลับไปหา Thotar ที่ Razor Hill" },
        description = { "457:590915927:100283756", "สัตว์ตัวสุดท้ายที่เจ้าต้องฝึกคือตัวที่เจ้าควรเรียนรู้จากมัน Armored Scorpid โจมตีอย่างรวดเร็วและเด็ดขาด การควบคุมพลังเช่นนี้คือชะตาของพราน\n\nเมื่อเจ้ากลับมา ข้าจะให้ทักษะฝึกสัตว์ที่เจ้าเลือกเอง มันจะอยู่ใต้บัญชาและได้รับประสบการณ์เคียงข้างเจ้า ข้าจะสอนวิธีเรียกและเก็บสัตว์เลี้ยงตามต้องการด้วย", variants = { { "180:1679799985:1943766330 C 271:407917010:2055992486", "สัตว์ตัวสุดท้ายที่เจ้าต้องฝึกคือตัวที่เจ้าควรเรียนรู้จากมัน Armored Scorpid โจมตีอย่างรวดเร็วและเด็ดขาด การควบคุมพลังเช่นนี้คือชะตาของ{class}\n\nเมื่อเจ้ากลับมา ข้าจะให้ทักษะฝึกสัตว์ที่เจ้าเลือกเอง มันจะอยู่ใต้บัญชาและได้รับประสบการณ์เคียงข้างเจ้า ข้าจะสอนวิธีเรียกและเก็บสัตว์เลี้ยงตามต้องการด้วย" } } },
        progress = { "34:641642720:1719945390", "ฝึกแมงป่องได้หรือยัง?" },
        completion = { "38:257771695:67878287 N 100:1470654320:779121826 N 152:1482074823:1132360063", "เรียนครบที่ข้าสอนได้แล้ว {name} ถึงเวลานำไปเลือกสัตว์ของตน\n\nนี่ {name} ข้าจะให้พลังฝึก เรียก และเก็บสัตว์ตามต้องการ ใช้ทักษะใหม่อย่างภูมิใจ เจ้าคู่ควรแล้ว" },
        required = { [15920] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame an Armored Scorpid"] = "ฝึก Armored Scorpid ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
    [6083] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "116:1040315264:379291700", "ใช้ Taming Rod ฝึก Surf Crawler ให้เชื่อง ฝึกทักษะแล้วคืน Taming Rod ให้ Thotar ที่ Razor Hill" },
        description = { "67:370777090:850985527 N 399:1927503897:1951063491", "ประโยชน์ของสัตว์เลี้ยงนั้นเห็นได้ชัด {name} การควบคุมอีกชีวิตหนึ่งคือการเพิ่มพลังของตน สัตว์ต้องเป็นเสมือนส่วนหนึ่งของเจ้า\n\nงานต่อไปต้องออกไปนอกแผ่นดิน เจ้าจะพบสัตว์ในน้ำนอกชายฝั่ง ตรงข้าม Sen'jin Village ใกล้ Echo Isles จงหาปู Surf Crawler ที่กระฉับกระเฉง ใช้ Taming Rod ฝึกมันให้เชื่องแล้วฝึกทักษะของเจ้า" },
        progress = { "121:1052988321:1761979747", "ต้องฝึกจึงมีทักษะควบคุมสัตว์อย่างได้ผล ฝึก Surf Crawler แล้วหรือ?" },
        completion = { "25:1083894232:337976322 N 21:2110361937:401282256", "เรียนเร็ว {name} ทำได้ดี" },
        required = { [15919] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame a Surf Crawler"] = "ฝึก Surf Crawler ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
    [6084] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "107:2030783699:1896108614", "ใช้ Taming Rod ฝึก Snow Leopard ให้เชื่อง ฝึกทักษะแล้วกลับไปหา Grif Wildheart ที่ Kharanos" },
        description = { "463:485896771:1852299248", "หมูป่า Crag ตัวหนาล่ำ บางทีเจ้าอาจอยากได้สัตว์ที่สง่างามกว่านี้หน่อย? ข้ารู้จักตัวที่เหมาะ ทางใต้และตะวันออกมีเสือขาวตัวใหญ่ชื่อ Snow Leopard เช่นเดียวกับปืนแกะสลักงดงาม ภายใต้รูปลักษณ์อันสวยงามคือนักสู้ทรงพลังที่สร้างความเสียหายได้มาก มันรวดเร็วและปราดเปรียวกว่าหมูป่าที่เจ้าฝึกมาก\n\nนำ Taming Rod ไปลองดูว่าเจ้าชอบ Snow Leopard หรือไม่" },
        progress = { "39:49354794:1959719347 N 1:63:63", "คิดอย่างไรกับ Snow Leopard {name}?" },
        completion = { "97:2041728329:1006460307", "เมื่อเห็นว่าเรียนพอ ข้าจะให้ความสามารถเลือกสัตว์เลี้ยงที่ชอบ" },
        required = { [15913] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame a Snow Leopard"] = "ฝึก Snow Leopard ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
    [6085] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "124:1352973389:1317800343", "ใช้ Taming Rod ฝึก Ice Claw Bear ให้เชื่อง ฝึกทักษะแล้วคืน Taming Rod ให้ Grif Wildheart ที่ Kharanos" },
        description = { "504:1506795038:603589454", "บางทีอยากได้สัตว์ที่มีแต่พละกำลังดิบ Ice Claw Bear เป็นเพื่อนชั้นยอดสำหรับพรานใหม่เช่นเจ้า พบทางตะวันออก Kharanos นี่ Taming Rod ลองเป็นสัตว์เลี้ยงดูว่าชอบไหม!\n\nเมื่อกลับ ข้าจะให้ทักษะฝึกสัตว์ที่เลือก มันจะเผชิญความท้าทายและได้ประสบการณ์เคียงเจ้า อีกทั้งสอนเรียกและเก็บตามใจ" },
        progress = { "37:118052583:1116828696", "ฝึก Ice Claw Bear แล้วหรือยัง?" },
        completion = { "14:510644690:581245021 N 148:691984143:290712694", "นี่ {name} ข้าจะให้พลังฝึกสัตว์ รวมทั้งเรียกและเก็บตามต้องการ\n\nหาสัตว์ดีซื่อสัตย์ แล้วสนุกกับการล่า!" },
        required = { [15908] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame an Ice Claw Bear"] = "ฝึก Ice Claw Bear ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
    [6086] = { -- Training the Beast
        title = { "18:955897086:1132620325", "ฝึกฝนสหายร่วมทาง" },
        objective = { "45:1924126570:551624509", "คุยกับ Belia Thundergranite ที่ Ironforge" },
        description = { { "N 374:1247153472:1315380596 N 1:46:46", "N 375:2004398276:1529421001 N 1:46:46" }, "{name} ตอนนี้ฝึกสัตว์ให้เชื่องได้ แต่ต้องมีทักษะสอนมันด้วย\n\nไป Hall of Arms ใน Ironforge คุย Belia Thundergranite ครูฝึกสัตว์ที่เราเคารพที่สุดคนหนึ่ง นางจะให้พลังฝึกสัตว์ใหม่ รีบไปเจ้าหนู!\n\nBelia เป็นมิตร คงได้รับการยอมรับไม่ยาก โชคดี {name}" },
        completion = { "58:1915126415:121667869 C 376:914161092:2053668677", "ทหารใหม่หรือ? เห็นว่าเจ้ากำลังเป็น{class}ผู้ยิ่งใหญ่\n\nใช่ ข้าให้ทักษะฝึกและชี้นำสัตว์ได้ ไม่เพียงสอนความสามารถใหม่ แต่ให้อาหารและชุบชีวิตได้หากล้มในศึก\n\nจำว่าเคล็ดลับให้สัตว์ใหม่เก่งที่สุดคือเคารพและดูแลดี แล้วมันจะเป็นเพื่อนซื่อสัตย์ที่สุด" },
    },
    [6087] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "133:1616839442:1944118013", "ใช้ Taming Rod ฝึก Prairie Stalker ให้เชื่อง ฝึกทักษะแล้วคืน Taming Rod ให้ Yaw Sharpmane ที่ Bloodhoof Village" },
        description = { "413:323955304:2036846805 N 50:1393702229:1138350871", "เจ้ามีจิตใจร้อนแรง พราน และกำลังรอความท้าทายต่อไปอย่างกระตือรือร้น\n\nงานต่อไปคือผูกมิตรกับหมาป่า Prairie Stalker มันรวดเร็วและไม่หวาดกลัว เมื่อรับมันเป็นสัตว์เลี้ยง เจ้าก็ต้องมีคุณสมบัติเช่นเดียวกัน\n\nในศึก เจ้าจะเรียนรู้ที่จะทำงานเป็นทีม ในที่สุดทั้งคู่ต้องเคลื่อนไหวประสานกันเป็นหนึ่งเดียว\n\nนี่คือ Taming Rod {name} จงฝึก Prairie Stalker ให้เชื่องแล้วฝึกทักษะของเจ้า" },
        progress = { "33:513613890:1355373865", "พบ Prairie Stalker หรือยัง?" },
        completion = { "71:1108040947:229013209", "ใช่... Earthmother เชื่อว่าพร้อมบทเรียนต่อไป" },
        required = { [15915] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame a Prairie Stalker"] = "ฝึก Prairie Stalker ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
    [6088] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "123:197813634:1467107598", "ใช้ Taming Rod ฝึก Swoop ให้เชื่อง ฝึกทักษะแล้วคืน Taming Rod ให้ Yaw Sharpmane ที่ Bloodhoof Village" },
        description = { "506:724741218:66657619", "งานสุดท้ายต้องฝึกสัตว์แห่งฟ้า Swoop เป็นคู่ต่อสู้ยาก แต่เมื่อเป็นพันธมิตร เจ้าจะได้การโจมตีเฉียบคมและท่วงท่าคุกคาม\n\nด้วยเจตนา Earthmother เมื่อกลับ ข้าจะให้ทักษะฝึกสัตว์ที่เลือกเป็นเพื่อน มันจะเผชิญความท้าทายและได้ประสบการณ์เคียงเจ้า อีกทั้งสอนเรียกและเก็บตามต้องการ" },
        progress = { "24:1923554347:1623622786 N 1:46:46", "อีกไม่นานเจ้าจะพร้อม {name}" },
        completion = { "38:257771695:67878287 N 82:367530422:267526487 N 156:2099937817:412303845", "เรียนครบที่ข้าสอนได้แล้ว {name} ขอพร Earthmother นำทางเลือกสัตว์เลี้ยง\n\nนี่ {name} ข้าจะให้พลังฝึก เรียก และเก็บสัตว์ตามต้องการ ใช้ทักษะอย่างภูมิใจและให้เกียรติ Earthmother" },
        required = { [15916] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame a Swoop"] = "ฝึก Swoop ให้เชื่อง" },
            item = { ["Taming Rod"] = "ไม้ฝึกสัตว์" },
        },
    },
    [6089] = { -- Training the Beast
        title = { "18:955897086:1132620325", "ฝึกฝนสหายร่วมทาง" },
        objective = { "60:1333545595:1725655484", "คุยกับ Holt Thunderhorn บน Hunter Rise ใน Thunder Bluff" },
        description = { "456:1351997075:2136220895 N 1:46:46", "ตอนนี้ฝึกสัตว์ให้เชื่องได้ แต่ต้องมีทักษะสอนมันด้วย\n\nไป Thunder Bluff คุย Holt Thunderhorn พรานที่เราเคารพที่สุดคนหนึ่ง หากเห็นว่าคู่ควร เขาจะให้ความสามารถฝึกสัตว์ใหม่\n\nHolt เคยชนะสัตว์แกร่งน่ากลัวที่สุดของ Azeroth และบัญชาหลายตัวแข็งแกร่ง สายใยเขากับ Earthmother แน่นแฟ้น เจ้าเรียนได้มาก โชคดี {name}" },
        completion = { "8:1681554422:196453020 C 328:1744682436:600754285", "{class}รุ่นเยาว์สินะ ใช่ ข้าให้ทักษะฝึกและชี้นำสัตว์ได้ ไม่เพียงสอนความสามารถใหม่ แต่ให้อาหารและชุบชีวิตได้หากล้มในศึก\n\nไปเถิด ขอ Earthmother นำทาง เราจะคุยอีกวันหน้า" },
    },
    [6126] = { -- Lessons Anew
        title = { "12:2081127499:337025447", "บทเรียนครั้งใหม่" },
        objective = { "83:1408267309:387693120", "เดินทางไป Moonglade แล้วคุยกับ Dendrite Starblaze ในหมู่บ้าน Nighthaven" },
        description = { "80:1595874918:696828619 N 355:899515196:481742391", "เจ้าพร้อมเรียนรู้เรื่องพิษและพลังที่ดรูอิดอย่างเราใช้จัดการมันแล้ว {name} Cenarius มอบพรให้เราชำระแม้แต่พิษร้ายที่สุดได้ด้วยคาถาเพียงบทเดียว พรนี้มีคุณค่าอย่างยิ่ง... เพื่อให้เจ้าเข้าใจบทเรียนนี้ เจ้าจะต้องแก้ปัญหาพิษด้วยวิธีของคนทั่วไป\n\nเดินทางไป Moonglade แล้วคุยกับ Dendrite Starblaze เขารอเจ้าไปเริ่มบทเรียนอยู่" },
        completion = { "487:1008639390:43155062", "สวัสดี ดรูอิดรุ่นเยาว์ ข้าดีใจที่เจ้าพร้อมและกระตือรือร้นจะเรียนรู้การรักษาพิษ\n\nแม้ดรูอิดรุ่นก่อนส่วนใหญ่จะผ่านบททดสอบที่จัดเตรียมไว้ แต่งานของเจ้าแตกต่างออกไป มีสัตว์ถูกพิษจำนวนมากใกล้ Crossroads ใน Barrens จนควบคุมไม่อยู่ ผู้คนที่นั่นขอความช่วยเหลือจาก Moonglade เราจึงจะส่งเจ้าไป นี่ไม่ใช่การฝึกซ้อม แต่เป็นงานจริง จงจำไว้", variants = { { "16:1291325135:1178530138 C 466:425184164:1646899363", "สวัสดี {class}รุ่นเยาว์ ข้าดีใจที่เจ้าพร้อมและกระตือรือร้นจะเรียนรู้การรักษาพิษ\n\nแม้ดรูอิดรุ่นก่อนส่วนใหญ่จะผ่านบททดสอบที่จัดเตรียมไว้ แต่งานของเจ้าแตกต่างออกไป มีสัตว์ถูกพิษจำนวนมากใกล้ Crossroads ใน Barrens จนควบคุมไม่อยู่ ผู้คนที่นั่นขอความช่วยเหลือจาก Moonglade เราจึงจะส่งเจ้าไป นี่ไม่ใช่การฝึกซ้อม แต่เป็นงานจริง จงจำไว้" } } },
    },
    [6127] = { -- The Principal Source
        title = { "20:1595680167:1593344382", "แหล่งต้นตอ" },
        objective = { "187:864500883:753972222", "ใช้ Empty Dreadmist Peak Sampler เก็บน้ำจากบ่อบนยอดเขา\n\nส่ง Filled Dreadmist Peak Sampler ให้ Tonga Runetotem ที่ Crossroads ใน Barrens" },
        description = { "502:1242738588:1883215221", "Dreadmist Peak ทางตะวันตกเฉียงเหนือของ Crossroads น่าจะเป็นต้นตอสำคัญของการแพร่พิษ บนยอดเขามีบ่อน้ำที่ส่งผลต่ออากาศ ข้าสงสัยว่าพวก Burning Blade ผู้บูชาปีศาจเป็นคนทำให้มันแปดเปื้อน\n\nใช้ภาชนะนี้เก็บน้ำจากบ่อบนยอดสูงสุด เมื่อเติมแล้วให้นำไปส่ง Tonga Runetotem ที่ Crossroads เขาเป็นคนขอความช่วยเหลือมา เจ้าจะร่วมมือกับเขาแก้โรคภัยครั้งนี้" },
        progress = { "387:626799823:389213977", "เจ้าคือผู้ที่ Cenarion Circle ใน Moonglade ส่งมาใช่ไหม? โชคดีมาก! เราติดขัดการคืนสมดุลให้ละมั่งป่วยใน Barrens เหนือ ยินดีรับทุกความช่วยเหลือ\n\nมีตัวอย่างน้ำที่ Dendrite Starblaze บอกหรือยัง? เขาแจ้งว่าเจ้าจะเก็บเพื่อให้ร่วมคิดยารักษา..." },
        completion = { "495:291857299:637366885", "ขอให้บรรพบุรุษเป็นพยาน น้ำนี้ชวนขยะแขยงจริง ๆ! ไม่แปลกเลยที่เหล่าละมั่งล้มป่วย\n\nมีบางสิ่งปนเปื้อนน้ำและทำให้ระบบนิเวศของ Barrens ตอนเหนือเสียหาย เจ้าจะพบละมั่งป่วยทั่วบริเวณเหนือถนนสายตะวันออก–ตะวันตกของที่นี่ แม้น้ำจะเป็นแหล่งแพร่โรคสำคัญ แต่ยังมีสิ่งอื่นเกี่ยวข้องด้วย\n\nเชื่อหรือไม่ น้ำนี้จะช่วยให้ข้าคิดยารักษาได้ ระหว่างที่ข้าศึกษา ต้องขอให้เจ้าหาของบางอย่างมาทำยา..." },
        required = { [15843] = { "29:70316727:460198944", "ขวดตัวอย่าง Dreadmist Peak ที่เติมแล้ว" } },
        steps = { { "29:70316727:460198944", "ขวดตัวอย่าง Dreadmist Peak ที่เติมแล้ว" } },
    },
    [6128] = { -- Gathering the Cure
        title = { "18:1683094505:839188768", "รวบรวมยารักษา" },
        objective = { "104:1588232014:676640704", "นำ Earthroot 5 ชิ้นและ Kodo Horn 5 ชิ้นไปให้ Tonga Runetotem ที่ Crossroads เพื่อทำยาทารักษา" },
        description = { "447:1865776060:440206853 N 29:418687973:2124598027", "น้ำเป็นฐานยาทาที่ข้าจะทำให้ละมั่ง ต้องใช้ Earthroot เพื่อฤทธิ์รักษา นักเก็บสมุนไพรรู้ที่หา หากไม่มีทักษะต้องหาคนช่วย\n\nสุดท้ายเพื่อความแรง ต้องใช้ Kodo Horn เศษแตกใช้ไม่ได้ โคโดที่เจ้ารับมือไหวเดินตอนเหนือ Barrens สังหารบางตัวเพื่อประโยชน์ใหญ่ของสมดุล {name} แล้วนำเขามา" },
        progress = { "154:775770530:636928405", "มีสารที่ต้องใช้ทำยาหรือยัง? ละมั่งไม่ดีขึ้นเอง เราอย่าชักช้าในการช่วย!" },
        completion = { "14:328000485:1627340455 N 416:901836333:200334908", "ดีมาก {name} ปริมาณนี้น่าจะทำยาทาได้มากพอ อย่างน้อยก็พอเริ่มช่วยให้สถานการณ์ดีขึ้น\n\nการทำยาถอนพิษบางครั้งยากมาก เพราะพิษแต่ละชนิดมักต้องใช้ยาเฉพาะเพื่อต้านฤทธิ์ ลองคิดดูสิ หากรักษาพิษได้ทันทีโดยไม่ต้องกังวลว่าต้องใช้ส่วนผสมใดบ้างจะดีเพียงใด!\n\nเอาล่ะ ให้ข้าลงมือปรุงยาก่อน!" },
        required = { [2449] = { "9:595112996:364502022", "เอิร์ธรูต" }, [15852] = { "9:1175420032:170054757", "เขาโคโด" } },
        steps = { { "9:595112996:364502022", "เอิร์ธรูต" }, { "9:1175420032:170054757", "เขาโคโด" } },
    },
    [6129] = { -- Curing the Sick
        title = { "15:1730609246:1907616096", "รักษาผู้เจ็บป่วย" },
        objective = { "237:1856567523:647033548", "ใช้ Curative Animal Salve กับ Sickly Gazelle 10 ตัวทั่วตอนเหนือ Barrens เพื่อรักษา มีรายงานพบเหนือถนนตะวันออก–ตะวันตกที่ผ่าน Crossroads" },
        description = { "57:1941101198:1856298355 N 422:2137404355:1678736202", "ข้าทำยาได้พอใช้สิบครั้ง {name} ระหว่างที่ข้าร่วมมือกับผู้ดูแลในพื้นที่เพื่อทำเพิ่ม อยากให้เจ้าช่วยเริ่มก่อน มีละมั่งป่วยอยู่ทั่ว Barrens ตอนเหนือ จงใช้ยารักษาพวกมัน\n\nข้ามั่นใจว่า Dendrite Starblaze ที่ Moonglade คงอยากคุยกับเจ้าเมื่อเสร็จแล้ว ฝากขอบคุณ Cenarion Circle ด้วย และข้าขอขอบใจเจ้าตรงนี้สำหรับทุกอย่าง!" },
        progress = { "118:1618628286:1785019811", "ทำสิ่งที่ Tonga Runetotem ที่ Crossroads ขอครบหรือยัง? หากยัง งานก็ยังไม่เสร็จ" },
        completion = { "352:137011634:594993183 N 97:461114960:137914468", "เจ้าดูแลละมั่งป่วยใน Barrens ได้ดีมาก พวกมันเป็นเหยื่อผู้ไม่รู้อิโหน่อิเหน่ของความแปดเปื้อนครั้งใหญ่ที่แพร่ไปทั่วแผ่นดิน พวกเจ้าทอเรนกระตือรือร้นที่จะเข้าใจ Cenarius เจ้าและผู้อาวุโสแห่ง Thunder Bluff พิสูจน์แล้วว่าความจำเป็นในการรักษาสมดุลอยู่เหนือกำแพงเผ่าพันธุ์ที่เราสร้างขึ้นเอง\n\n{name} เจ้าพิสูจน์คุณค่าของตนในฐานะสหายแห่งธรรมชาติและ Circle แล้ว จงรับสิ่งนี้เป็นสัญลักษณ์เถิด" },
        steps = { { "20:268892023:1782351426", "รักษาละมั่งที่ป่วย" } },
    },
    [6130] = { -- Power over Poison
        title = { "17:648035898:1845468169", "พลังเหนือพิษ" },
        objective = { "59:804694277:1226233650", "กลับไปหา Turak Runetotem บน Elder Rise ใน Thunder Bluff" },
        description = { { "261:576246021:868087556 N 161:391239422:541857185", "261:576246021:868087556 N 160:1875963853:1095075407" }, "เจ้าได้เรียนรู้ความหมายของการรักษาพิษโดยปราศจากความช่วยเหลือของวิญญาณแล้ว จงจดจำความยากลำบากที่ผู้อื่นเผชิญเมื่อต่อสู้กับพิษ ขณะที่เจ้ากำลังจะได้รับพลังใหม่เหนือพิษนั้น\n\nเจ้าควรกลับไปหา Turak Runetotem ที่ Thunder Bluff {name} แน่นอนว่าเขามีเวทสำคัญจะสอน เมื่อนักเรียนเข้าใจบทเรียนแล้ว\n\nลาก่อน ดรูอิดรุ่นเยาว์ เราจะได้คุยกันอีก", variants = { { "261:576246021:868087556 N 132:615864052:842965079 C 23:1928622257:2131200942", "เจ้าได้เรียนรู้ความหมายของการรักษาพิษโดยปราศจากความช่วยเหลือของวิญญาณแล้ว จงจดจำความยากลำบากที่ผู้อื่นเผชิญเมื่อต่อสู้กับพิษ ขณะที่เจ้ากำลังจะได้รับพลังใหม่เหนือพิษนั้น\n\nเจ้าควรกลับไปหา Turak Runetotem ที่ Thunder Bluff {name} แน่นอนว่าเขามีเวทสำคัญจะสอน เมื่อนักเรียนเข้าใจบทเรียนแล้ว\n\nลาก่อน {class}รุ่นเยาว์ เราจะได้คุยกันอีก" } } },
        completion = { "444:1364496323:1500913676 N 16:413138634:1625678374", "ยินดีต้อนรับกลับ ข้าติดตามความก้าวหน้าตั้งแต่ไป ยอมรับว่าตกใจข่าว Crossroads ต้องสอบสวนต่อ การปล่อยพิษสู่สภาพแวดล้อมกระทบสมดุลอย่างยิ่ง\n\nเจ้ารับแรงกดดันอย่างสง่างาม จึงไม่มีรางวัลดีกว่าพลังถาวรเหนือพิษ ใช้ให้ดี {name}... ใช้ให้ดี" },
    },
    [94007] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "41:1847062982:1953098387", "ไปรายงานตัวกับ Quel'ana Quickgale ที่ Valanaar" },
        description = { "276:849408364:259344324", "ตอนนี้เจ้าคุ้นเคยกับแดนป่าบนที่ราบสูงพอสมควรแล้ว ข้าเชื่อว่าถึงเวลาที่เจ้าจะออกหาสัตว์คู่ใจของตนเอง\n\nจงไปที่ท่าเรือ Valanaar ทางตะวันออกเฉียงใต้ แล้วคุยกับ Quel'ana Quickgale ที่นั่น เขาจะสอนศิลปะการฝึกสัตว์ให้เชื่องแก่เจ้า" },
        completion = { "49:325195834:1992363099", "ข้าดีใจยิ่งที่เจ้ามา มาเถิด เรามาเริ่มกันเลย" },
    },
    [94013] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "153:325825911:1986509123", "ใช้ Taming Rod ฝึก Vuldren Alpha ใน Gustberry Lowlands ให้เชื่อง ฝึกฝนทักษะของเจ้า แล้วนำ Taming Rod กลับไปคืน Quel'ana Quickgale ที่ Valanaar" },
        description = { "336:915863583:1598754324", "เจ้ากลับมาพร้อมชัยชนะจากการฝึกสัตว์สองชนิดให้เชื่อง บัดนี้ถึงเวลาของบททดสอบสุดท้าย สายลมแห่ง Zephras กระซิบถึงความท้าทายที่ยิ่งใหญ่กว่าซึ่งรออยู่เบื้องหน้า\n\nนำ Taming Rod นี้เดินทางไปยัง Gustberry Lowlands ฝึก Vuldren Alpha ที่นั่นให้เชื่อง แล้วพิสูจน์ความเชี่ยวชาญของเจ้า\n\nเมื่อผ่านบทเรียนนี้ เจ้าจะพร้อมเรียนรู้วิถีแห่งพรานให้ลึกซึ้งยิ่งขึ้น", variants = { { "336:657378618:336507069", "เจ้ากลับมาพร้อมชัยชนะจากการฝึกสัตว์สองชนิดให้เชื่อง บัดนี้ถึงเวลาของบททดสอบสุดท้าย สายลมแห่ง Zephras กระซิบถึงความท้าทายที่ยิ่งใหญ่กว่าซึ่งรออยู่เบื้องหน้า\n\nนำ Taming Rod นี้เดินทางไปยัง Gustberry Lowlands ฝึก Vuldren Alpha ที่นั่นให้เชื่อง แล้วพิสูจน์ความเชี่ยวชาญของเจ้า\n\nเมื่อผ่านบทเรียนนี้ เจ้าจะพร้อมเรียนรู้วิถีแห่งพรานให้ลึกซึ้งยิ่งขึ้น" } } },
        progress = { { "67:824183224:1444322635", "16:2076335929:1428616939 N 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 N 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 N 34:695575318:1494856850 R 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 R 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 R 1:46:46" }, "เจ้าจะได้เรียนรู้ สหาย และสักวันเจ้าจะกลายเป็นนักผจญภัยผู้ยิ่งใหญ่" },
        completion = { { "236:666010928:2071451936", "11:1614239848:1406166483 N 174:969134449:1542917222 N 35:744659343:519186625", "11:1614239848:1406166483 N 174:969134449:1542917222 C 35:744659343:519186625", "11:1614239848:1406166483 N 174:969134449:1542917222 R 35:744659343:519186625", "11:1614239848:1406166483 C 174:969134449:1542917222 N 35:744659343:519186625", "11:1614239848:1406166483 C 174:969134449:1542917222 C 35:744659343:519186625", "11:1614239848:1406166483 C 174:969134449:1542917222 R 35:744659343:519186625", "11:1614239848:1406166483 R 174:969134449:1542917222 N 35:744659343:519186625", "11:1614239848:1406166483 R 174:969134449:1542917222 C 35:744659343:519186625", "11:1614239848:1406166483 R 174:969134449:1542917222 R 35:744659343:519186625" }, "ยอดเยี่ยม สหาย! เจ้าเรียนรู้ได้เร็วมาก เมื่อเจ้ารู้พื้นฐานแล้ว ข้าก็สอนวิธีสร้างสายสัมพันธ์อันยั่งยืนกับสัตว์คู่ใจให้เจ้าได้\n\nจงนำความรู้นี้ติดตัวไปและเติบโตต่อไป เป็นนักผจญภัยที่ Zephras Isle ต้องการให้เจ้าเป็น", variants = { { "11:1614239848:1406166483 N 174:969134449:1542917222 C 35:744659343:519186625", "ยอดเยี่ยม {name}! เจ้าเรียนรู้ไวทีเดียว ตอนนี้เจ้ารู้พื้นฐานแล้ว ข้าจะสอนให้เจ้าสร้างสายสัมพันธ์ที่ยืนยาวกับสัตว์คู่ใจ\n\nจงนำความรู้นี้ไปใช้และเติบโตเป็น {class} ที่ Zephras Isle ต้องการ" } } },
        required = { [264163] = { "10:1974699204:422787886", "ไม้เท้าฝึกสัตว์" } },
