    [94050] = { -- Training the Beast
        title = { "18:955897086:1132620325", "ฝึกฝนสหายร่วมทาง" },
        objective = { "41:1358590424:1388696613", "ไปคุยกับ Quel'dora Quickgale ที่ Valanaar" },
        description = { "221:1345313900:1157285116 C 1:46:46", "บัดนี้เจ้ามีพลังที่จะฝึกสัตว์ให้เชื่องแล้ว แต่ยังต้องเรียนรู้ทักษะในการฝึกฝนมันด้วย ในเรื่องนี้ไม่มีใครเก่งไปกว่า Quel'dora พี่น้องของข้า นางจะสอนทักษะที่ใช้ฝึกสัตว์คู่ใจตัวใหม่ให้เจ้า\n\nจงไปกับสายลมเถิด {class} รุ่นเยาว์" },
        completion = { { "389:530098549:1451952264", "12:1592496637:1532794898 N 241:1427401568:704347301 N 120:2034568094:1971249264", "12:1592496637:1532794898 N 241:1427401568:704347301 C 120:2034568094:1971249264", "12:1592496637:1532794898 N 241:1427401568:704347301 R 120:2034568094:1971249264", "12:1592496637:1532794898 C 241:1427401568:704347301 N 120:2034568094:1971249264", "12:1592496637:1532794898 C 241:1427401568:704347301 C 120:2034568094:1971249264", "12:1592496637:1532794898 C 241:1427401568:704347301 R 120:2034568094:1971249264", "12:1592496637:1532794898 R 241:1427401568:704347301 N 120:2034568094:1971249264", "12:1592496637:1532794898 R 241:1427401568:704347301 C 120:2034568094:1971249264", "12:1592496637:1532794898 R 241:1427401568:704347301 R 120:2034568094:1971249264" }, "ดูท่าจะเป็นนักผจญภัยหน้าใหม่นะ ใช่แล้ว ข้าสอนทักษะที่จำเป็นในการฝึกฝนและชี้นำสัตว์คู่ใจให้เจ้าได้ นอกจากสอนความสามารถใหม่ ๆ ให้มันแล้ว เจ้าจะให้อาหารและชุบชีวิตมันได้ด้วย หากมันล้มลงในการต่อสู้\n\nจำไว้นะ สหาย จงเคารพความสมดุลและชื่นชมความยิ่งใหญ่ของธรรมชาติรอบตัวเสมอ ไปเถิด แล้วเราค่อยคุยกันใหม่ในวันหน้า" },
    },
    [94449] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "37:332931033:1670281489", "ไปหา Bruegs Kindleborn ใน Dun Morogh" },
        description = { "42:800061749:860316814 N 298:2029569213:1234504581", "นานแล้วนับจากบททดสอบก่อน {name} เจ้าพิสูจน์ความอดทน แต่ถึงเวลาเรียนรู้ความโกลาหล... การทำลาย เสียงไฟเรียกดังลั่น หากพร้อมจ่ายราคา มันจะพูดกับเจ้า\n\nไปหา Bruegs Kindleborn ทางตะวันออกไกลในภูเขา เขาอยู่ถ้ำเหนือ South Gate Outpost เขาจะรู้ว่าเจ้าพร้อมจริงหรือไม่" },
        completion = { "39:877291907:1993328227 C 216:2109026311:195439412 N 104:633659511:1479661368", "อืม... ผู้อาวุโสคนนั้นส่งเจ้ามาหรือ? คำพูดของ {class} เชื่อถือได้ ข้าจึงจะไม่โต้แย้ง แสดงว่าเจ้าพร้อมรับ Sapta ขั้นต่อไปแล้ว Sapta แห่งไฟนั่นละ ข้าเห็นจากแววตาเจ้าแล้ว ทั้งไฟที่ลุกโชนและความกระหาย เจ้าได้ลิ้มรสพลังแล้ว และบัดนี้ต้องการมากขึ้น แต่ระวังตัวให้ดี {name} จำสิ่งที่หินสอนเจ้าไว้ ใช้ไฟน่ะง่าย แต่จะควบคุมให้เชี่ยวชาญนั้นยากกว่า จงรู้ว่าเมื่อไรควรยั้งมือ" },
    },
    [94465] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "72:845751707:1909139009", "นำ Torch of the Dormant Flame ไปให้ Braldir Ashmantle ใน Loch Modan" },
        description = { "390:1283178603:1303934923", "เจ้ามีกำลังพอแบกโทเทมไฟ เจ้าหนุ่ม แต่กำลังอย่างเดียวไม่ได้ทำให้พร้อม\n\nเลย Valley of Kings ท่ามกลางผาหิน Loch Modan มีทางลับสู่ยอดเขาศักดิ์สิทธิ์แห่งหนึ่ง Braldir Ashmantle เฝ้า Shrine of the Dormant Flame ที่นั่น\n\nนำคบเพลิงนี้ไป เป็นเครื่องหมายเจตนา จุดมันกับกระถางไฟของศาลแล้วนำกลับมา ข้าจะให้เจ้าได้รับโทเทมอย่างสมควร" },
        progress = { { "344:642676709:607051991", "11:1988767264:581875424 N 99:1835308045:193370945 N 218:620755024:1567181957", "11:1988767264:581875424 N 99:1835308045:193370945 C 218:620755024:1567181957", "11:1988767264:581875424 N 99:1835308045:193370945 R 218:620755024:1567181957", "11:1988767264:581875424 C 99:1835308045:193370945 N 218:620755024:1567181957", "11:1988767264:581875424 C 99:1835308045:193370945 C 218:620755024:1567181957", "11:1988767264:581875424 C 99:1835308045:193370945 R 218:620755024:1567181957", "11:1988767264:581875424 R 99:1835308045:193370945 N 218:620755024:1567181957", "11:1988767264:581875424 R 99:1835308045:193370945 C 218:620755024:1567181957", "11:1988767264:581875424 R 99:1835308045:193370945 R 218:620755024:1567181957" }, "สวัสดี สหาย เจ้ามาถึง Shrine of the Dormant Flame หรือ? มีไม่กี่คนทำได้ ผู้เชี่ยวชาญเส้นทางนักผจญภัยเท่านั้นจึงเข้าใจความลับที่นี่\n\nน่าเสียดายที่มาไกลแล้วต้องกลับ การปีนขึ้นไม่เหมือนเดินเล่นใน Dun Morogh แต่ข้าเป็นผู้ดูแลศาล จะไม่ให้ใครก็ได้ย่ำเข้ามา", variants = { { "11:1988767264:581875424 N 99:1835308045:193370945 C 218:620755024:1567181957", "สวัสดี {name} เจ้าขึ้นมาถึง Shrine of the Dormant Flame ได้แล้วรึ? มีไม่กี่คนหรอกที่มาถึง มีแต่ผู้ที่เข้าใจวิถีของ {class} อย่างลึกซึ้งเท่านั้นที่หยั่งถึงความลับของที่นี่\n\nน่าเสียดายที่เจ้ามาไกลขนาดนี้แล้วต้องกลับ การปีนขึ้นมานี่ไม่เหมือนเดินเล่นใน Dun Morogh แต่ข้าเป็นผู้ดูแลศาล และจะไม่ปล่อยให้ใครเดินเพ่นพ่านแถวนี้ตามใจชอบ" } } },
        completion = { { "363:2110139432:1195080865", "18:718163759:1286816796 N 212:98661141:1338679664 N 121:1387157880:1863891527", "18:718163759:1286816796 N 212:98661141:1338679664 C 121:1387157880:1863891527", "18:718163759:1286816796 N 212:98661141:1338679664 R 121:1387157880:1863891527", "18:718163759:1286816796 C 212:98661141:1338679664 N 121:1387157880:1863891527", "18:718163759:1286816796 C 212:98661141:1338679664 C 121:1387157880:1863891527", "18:718163759:1286816796 C 212:98661141:1338679664 R 121:1387157880:1863891527", "18:718163759:1286816796 R 212:98661141:1338679664 N 121:1387157880:1863891527", "18:718163759:1286816796 R 212:98661141:1338679664 C 121:1387157880:1863891527", "18:718163759:1286816796 R 212:98661141:1338679664 R 121:1387157880:1863891527" }, "อา ขอโทษด้วย สหาย ไม่เห็นคบเพลิงในมือ เป็นเกียรติที่ได้รู้จัก\n\nผู้พเนจรมากมายขึ้นมาตามเรื่องสมบัติหรือสัตว์ร้าย แล้วพบเพียงหินกับความเงียบ แต่เรารู้ดีกว่านั้น ใช่ไหม สหาย?\n\nศาลนี้มีความจริงลึกเกินกว่า Alliance จะเข้าใจ สำหรับเรา มันคือเปลวไฟศักดิ์สิทธิ์ที่รอการปลุกให้ตื่น" },
        required = { [6653] = { "26:917262829:1125779937", "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" } },
        objectiveLabels = {
            item = { ["Torch of the Dormant Flame"] = "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" },
        },
    },
    [94466] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "72:1831588487:808926937", "นำ Fire Tar 1 ชิ้นและ Reagent Pouch 1 ถุงไปให้ Braldir Ashmantle ใน Loch Modan" },
        description = { "52:387744788:165191784 N 331:938741513:1305608959", "เจ้าไม่ได้เดินมาไกลเพื่อฟังเรื่องเล่าใช่ไหม {name}? เจ้าแสวงหา Eternal Flame และโทเทมไฟ\n\nก่อนอื่นต้องมี Sapta ผูกจิตของเจ้ากับเปลวเพลิง\n\nข้าจะปรุงให้ แต่ต้องใช้สองอย่าง Fire Tar จาก Tunnel Rat Geomancer ในถ้ำโคบอลด์ทางเหนือ และ Reagent Pouch จาก Stonesplinter Seer ที่ซุ่มในเนินใต้ อันตราย แต่คู่ควรกับไฟ" },
        progress = { { "363:1949619312:1727364034", "46:558246030:1335808995 N 311:61065120:1989442582", "46:558246030:1335808995 C 311:61065120:1989442582", "46:558246030:1335808995 R 311:61065120:1989442582" }, "ข้าเกือบมีทุกอย่างสำหรับ Fire Sapta แล้ว สหาย ขาดเพียง Fire Tar กับถุงของผู้หยั่งรู้ Tunnel Rat Geomancer ในถ้ำโคบอลด์ทางเหนือพกยางไฟ ส่วนถุงต้องชิงจาก Stonesplinter Seer ในเนินใต้ วัตถุดิบเหล่านี้ผูกกับไฟ ดังที่ Sapta แท้ทุกชนิดต้องเป็น ความสัมพันธ์กับธาตุทำให้งานเราทรงพลัง" },
        completion = { { "365:294845543:486502922", "18:1652832627:191151498 N 341:1144502553:358700856", "18:1652832627:191151498 C 341:1144502553:358700856", "18:1652832627:191151498 R 341:1144502553:358700856" }, "ของพวกนี้ใช้ได้ดี สหาย\n\nไฟไม่ใช่แค่โทสะและหายนะ จำไว้ มันคือชีวิต เตาหลอม และลมหายใจแห่งการสร้าง ทุกสิ่งผูกกันอย่างสมดุล พลังหนึ่งปรับอีกพลังและให้ความหมาย หากไร้เงา แสงก็แค่พร่าตา หากไร้ไฟ หินก็เป็นเพียงความทรงจำเย็นเยียบ\n\nเชี่ยวชาญเวทคือรู้ว่าเมื่อใดควรผสาน ไม่ใช่เผาอย่างเดียว นั่นคือปัญญาแท้ เจ้าหนุ่ม" },
        required = { [5026] = { "8:304876206:1308605072", "น้ำมันดินติดไฟ" }, [6652] = { "13:1447175775:111746688", "ถุงใส่วัตถุดิบ" } },
        steps = { { "8:304876206:1308605072", "น้ำมันดินติดไฟ" }, { "13:1447175775:111746688", "ถุงใส่วัตถุดิบ" } },
    },
    [94467] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "116:2039297308:1420536102", "ปราบ Minor Manifestation of Fire แล้ววาง Glowing Ember ในกระถางไฟบน Shrine of Eternal Flame" },
        description = { "24:586722007:732254737 N 328:1174606386:268173834", "Fire Sapta พร้อมแล้ว {name} ถึงเวลาเผชิญเปลวเพลิง ใช้ที่ศาลแล้วขึ้นยอดเขา จะเห็นวิญญาณ มันไม่ลงมือจนกว่าเจ้าจะโจมตี แต่จะรู้ว่าเจ้ามองเห็น\n\nโจมตีให้ไว เจ้าหนุ่ม ยิ่งรอนานมันยิ่งลุกโชนแรง เมื่อปราบแล้ว นำถ่านคุใส่กระถางไฟ จุดคบเพลิงเพื่อรับความโปรดปรานจากไฟ" },
        progress = { "303:298144369:780775167", "กระถางไฟสูงราวหนึ่งในสามของตัวเจ้า มีอักขระไหม้ดำบนราวโลหะเรียบ โลหะไม่มีรอยสึกจากอากาศ และชามด้านบนเย็นเมื่อสัมผัส\n\nBlackrock Mountain ตั้งตระหง่านไกลออกไป มองเห็นชัดจากสถานที่ศักดิ์สิทธิ์นี้เพื่อรำลึกถึงมัน", variants = { { "303:1901525920:1768749086", "กระถางไฟสูงราวหนึ่งในสามของตัวเจ้า มีอักขระไหม้ดำบนราวโลหะเรียบ โลหะไม่มีรอยสึกจากอากาศ และชามด้านบนเย็นเมื่อสัมผัส\n\nBlackrock Mountain ตั้งตระหง่านไกลออกไป มองเห็นชัดจากสถานที่ศักดิ์สิทธิ์นี้เพื่อรำลึกถึงมัน" } } },
        completion = { "342:859935439:1847171884", "เมื่อวางถ่านคุลงในชาม เปลวไฟร้อนขาวก็ลุกขึ้น เจ้ารู้สึกถึงเวทของ Sapta ไหลผ่านร่าง เปลวเพลิงเต้นเป็นจังหวะเบื้องหน้า\n\nเจ้าสอดปลายคบเพลิงลงในอ่าง มันติดไฟทันที ควันดูจะลอยไปทางยอดเขาที่ตั้งตระหง่าน", variants = { { "335:1733772722:1975564616", "เมื่อเจ้าวางถ่านคุลงในชาม เปลวไฟสีขาวร้อนจัดก็ลุกขึ้น เจ้ารู้สึกถึงพลังเวทของ Sapta ไหลไปทั่วร่าง ขณะที่เปลวไฟไหวเป็นจังหวะอยู่เบื้องหน้า\n\nเจ้าจุ่มปลายคบเพลิงลงในอ่าง คบเพลิงติดไฟทันที ควันดูเหมือนจะลอยไปทางภูเขา Blackrock" } } },
        required = { [6653] = { "26:917262829:1125779937", "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" }, [6655] = { "13:805808827:514952864", "ถ่านคุเรืองแสง" } },
        steps = { { "26:917262829:1125779937", "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" }, { "13:805808827:514952864", "ถ่านคุเรืองแสง" } },
    },
    [94468] = { -- Call of Fire
