        description = { "269:1428936312:1124722599", "เจ้ากำคบเพลิงแน่น หันจากกระถางไฟไปมองทั่ว Loch Modan ความตื่นเต้นดึงรั้งจิตใจเมื่อลมแรงขึ้นและพัดเปลวไฟให้เต้นรุนแรง\n\nเจ้าเริ่มลงตามทางกลับ Dun Morogh เพื่อตามหา Bruegs Kindleborn" },
        progress = { { "35:1490138839:1985582568", "5:5859056:88900272 N 24:1472876467:1063706572", "5:5859056:88900272 C 24:1472876467:1063706572", "5:5859056:88900272 R 24:1472876467:1063706572" }, "ว่าอย่างไร สหาย? ในมือเจ้าคืออะไร?" },
        completion = { { "360:2038145165:385217040", "80:993859381:2044910658 N 274:1892111226:825621809", "80:993859381:2044910658 C 274:1892111226:825621809", "80:993859381:2044910658 R 274:1892111226:825621809" }, "ด้วยเคราของ Madoran จิตเจ้าสว่างกว่าคบเพลิงใดที่ข้าเคยเห็น สหาย นั่นควรค่าแก่ความภูมิใจ\n\nเดินทางนี้ต่อ แล้วธาตุจะคล้อยตามเจตนา ญาติพี่น้องจะมาขอปัญญาและคำชี้ทาง ข้าขอเป็นคนแรกที่แสดงความยินดีอย่างยิ่ง และมอบโทเทมชิ้นใหม่ เจ้าได้มันมาอย่างสมควร ผู้เกิดจากเปลวไฟ" },
        required = { [6654] = { "26:425046618:568461893", "คบเพลิงแห่งเปลวไฟนิรันดร์" } },
        objectiveLabels = {
            item = { ["Torch of the Eternal Flame"] = "คบเพลิงแห่งเปลวไฟนิรันดร์" },
        },
    },
    [94792] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "113:1468589419:157876878", "ใช้ Taming Rod ฝึก Rockhide Boar ให้เชื่อง ฝึกฝนทักษะของเจ้า แล้วนำ Taming Rod กลับไปคืน Josephine Carson" },
        description = { "485:331735684:869924987", "พรานหลายคนนิยมเดินทางกับสัตว์คู่ใจ เมื่อมีสัตว์อยู่เคียงข้าง เจ้าจะพบว่าตนเองเอาตัวรอดได้แม้ในสถานการณ์อันตรายที่สุด อย่างที่เขาว่ากัน ทุกอย่างง่ายขึ้นเมื่อมีสหาย แต่การหาสัตว์มาเป็นคู่ใจนั้นต้องทำด้วยความระมัดระวัง ความสมดุลของธรรมชาติเปราะบาง และเราต้องเคารพมันเสมอ\n\nนำ Taming Rod นี้ติดตัวเข้าไปในป่า เจ้าจะใช้มันฝึก Rockhide Boar ให้เชื่อง และฝึกฝนทักษะการเป็นพรานของเจ้าได้" },
        progress = { { "67:824183224:1444322635", "16:2076335929:1428616939 N 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 N 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 N 34:695575318:1494856850 R 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 R 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 R 1:46:46" }, "เจ้าจะได้เรียนรู้ สหาย และสักวันเจ้าจะกลายเป็นนักผจญภัยผู้ยิ่งใหญ่", variants = { { "16:2076335929:1428616939 N 34:695575318:1494856850 C 1:46:46", "เจ้าจะเรียนรู้ได้แน่ {name} สักวันเจ้าจะเป็น {class} ผู้เก่งกาจ" } } },
