    [94978] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "157:383867819:122000823", "ใช้ Taming Rod ฝึก Windsong Crawler ที่พบใกล้แหล่งน้ำให้เชื่อง\nฝึกฝนทักษะของเจ้า แล้วนำ Taming Rod กลับไปคืน Quel'ana Quickgale ที่ Valanaar" },
        description = { "345:235700430:172444031", "พรานทุกคนเริ่มต้นด้วยการเรียนรู้สายสัมพันธ์ระหว่างสัตว์กับผู้ฝึก นี่คือบททดสอบแรกของเจ้า ในภายหน้าเจ้าจะฝึกสัตว์จากทุกมุมโลกให้เชื่อง แต่ตอนนี้ให้เริ่มจากแม่น้ำและทะเลสาบของพวกเราบน Zephras ก่อน\n\nนำ Taming Rod นี้ไปตามหา Windsong Crawler\n\nแสดงให้เห็นว่าเจ้าได้รับความไว้วางใจจากมัน แล้วเริ่มต้นเส้นทางสู่ความเชี่ยวชาญที่แท้จริง" },
        progress = { { "67:824183224:1444322635", "16:2076335929:1428616939 N 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 N 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 N 34:695575318:1494856850 R 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 R 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 R 1:46:46" }, "เจ้าจะได้เรียนรู้ สหาย และสักวันเจ้าจะกลายเป็นนักผจญภัยผู้ยิ่งใหญ่" },
        completion = { { "51:220898976:1736563075", "12:726585299:1656521471 N 33:1688046541:933139199", "12:726585299:1656521471 C 33:1688046541:933139199", "12:726585299:1656521471 R 33:1688046541:933139199" }, "ฝึกได้ดี สหาย! เจ้าเริ่มชำนาญแล้ว", variants = { { "12:726585299:1656521471 N 33:1688046541:933139199", "ฝึกสัตว์ได้ดีมาก {name}! เจ้าชักชำนาญแล้วนี่" } } },
        required = { [267272] = { "10:1974699204:422787886", "ไม้ฝึกสัตว์" } },
        objectiveLabels = {
            event = { ["Tame a Windsong Crawler"] = "ฝึก Windsong Crawler ให้เชื่อง" },
