    [94979] = { -- Taming the Beast
        title = { "16:1883088725:1556504953", "ฝึกสัตว์ป่าให้เชื่อง" },
        objective = { "159:12091829:722473332", "ใช้ Taming Rod ฝึก Ornery Galestrider ใน Gustberry Lowlands ให้เชื่อง\nฝึกฝนทักษะของเจ้า แล้วนำ Taming Rod กลับไปคืน Quel'ana Quickgale ที่ Valanaar" },
        description = { "334:1828563851:207136113", "เจ้าพิสูจน์แล้วว่าฝึก crawler แห่งสายน้ำให้เชื่องได้ บัดนี้ถึงเวลาทดสอบฝีมือในที่โล่ง ที่ราบแห่ง Zephras ก้องด้วยเสียงร้องของ galestrider นักล่ามีปีกผู้สง่างามที่วิ่งเร็วราวสายลม\n\nนำ Taming Rod นี้ไปตามหามัน เดินทางไปยังที่ราบลุ่มและเอาชนะใจมัน\n\nแสดงให้เห็นว่าเจ้าพร้อมเผชิญบททดสอบที่รออยู่ข้างหน้า", variants = { { "334:1922504552:1326346487", "เจ้าพิสูจน์แล้วว่าฝึก crawler แห่งสายน้ำให้เชื่องได้ บัดนี้ถึงเวลาทดสอบฝีมือในที่โล่ง ที่ราบแห่ง Zephras ก้องด้วยเสียงร้องของ Galestrider นักล่ามีปีกผู้สง่างามที่วิ่งเร็วราวสายลม\n\nนำ Taming Rod นี้ไปตามหามัน เดินทางไปยังที่ราบลุ่มและเอาชนะใจมัน\n\nแสดงให้เห็นว่าเจ้าพร้อมเผชิญบททดสอบที่รออยู่ข้างหน้า" } } },
        progress = { { "67:824183224:1444322635", "16:2076335929:1428616939 N 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 N 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 N 34:695575318:1494856850 R 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 C 34:695575318:1494856850 R 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 N 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 C 1:46:46", "16:2076335929:1428616939 R 34:695575318:1494856850 R 1:46:46" }, "เจ้าจะได้เรียนรู้ สหาย และสักวันเจ้าจะกลายเป็นนักผจญภัยผู้ยิ่งใหญ่" },
        completion = { { "46:1278665323:816465407", "39:317169835:1176073367 N 1:33:33", "39:317169835:1176073367 C 1:33:33", "39:317169835:1176073367 R 1:33:33" }, "เจ้ากลับมาแล้วหรือ! รวดเร็วเหลือเกิน สหาย!", variants = { { "39:317169835:1176073367 N 1:33:33", "กลับมาแล้วหรือ! เร็วจนน่าทึ่งเลย {name}!" } } },
