    [97243] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "105:775813038:1500159627", "นำ Torch of Dormant Flame ไปให้ Olariaan Swiftburn ที่ Shrine of Flames ใน Gustberry Lowlands" },
        description = { "418:9929174:199680786", "แม้อยู่ในอาณาจักร Skywall ที่นี่ก็ยังเป็นแดนธาตุ วิญญาณธาตุทั้งสี่พูดกับเราหากยอมฟัง Windshaper คนหนึ่งประสานกับไฟได้เป็นพิเศษ เป็น Shen'dorei ชื่อ Olariaan Swiftburn\n\nนำสิ่งนี้ไปให้เขาที่ Shrine of Flames ใน Gustberry Lowlands ศาลซ่อนริมเกาะทางตะวันตกของ Valanaar", variants = { { "418:868464787:211418357", "แม้อยู่ในอาณาจักร Skywall ที่นี่ก็ยังเป็นแดนธาตุ วิญญาณธาตุทั้งสี่พูดกับเราหากยอมฟัง Windshaper คนหนึ่งประสานกับไฟได้เป็นพิเศษ เป็น Shen'dorei ชื่อ Olariaan Swiftburn\n\nนำสิ่งนี้ไปให้เขาที่ Shrine of Flames ใน Gustberry Lowlands ศาลซ่อนริมเกาะทางตะวันตกของ Valanaar" } } },
        progress = { { "36:1560540211:1899575061", "5:1287366450:669725923 N 25:2015429522:298869124", "5:1287366450:669725923 C 25:2015429522:298869124", "5:1287366450:669725923 R 25:2015429522:298869124" }, "ว่าอย่างไร สหาย? ในมือเจ้าคืออะไร?" },
        completion = { { "165:461917973:1310562186", "40:1982480584:110903250 N 115:1024577549:830639772", "40:1982480584:110903250 C 115:1024577549:830639772", "40:1982480584:110903250 R 115:1024577549:830639772" }, "เจ้านำคบเพลิงมาแล้ว ใช่ นักผจญภัยน้อย ข้าสอนให้ฟังเสียงเรียกแห่งไฟได้ มันไม่ง่าย แต่สิ่งที่เราทำในอาณาจักรนี้ก็ไม่เคยง่าย" },
        required = { [6653] = { "26:917262829:1125779937", "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" } },
        steps = { { "26:917262829:1125779937", "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" } },
    },
    [97244] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "79:1711097642:1079002340", "สังหาร Skypriest Faladiel ใน Gustberry Lowlands แล้วเก็บ Faladiel's Heart" },
        description = { "478:1320173324:623098967", "มี Al'Aketh Skypriest ชื่อ Faladiel ครั้งหนึ่งเขาเคยเรียกไฟและเป็น Windshaper ผู้แน่วแน่ เช่นเดียวกับ Al'Aketh มากมาย เขาจำนำความภักดีเพื่อพลัง บัดนี้มือเปื้อนเลือดอดีตพี่น้อง\n\nเจ้าจะพบ Skypriest Faladiel ที่ไร่ทางตะวันออกเฉียงเหนือ เลย Valanaar ไป ทางใต้ของ Shrine of Akir ฆ่าคนทรยศแล้วนำหัวใจมา เป็นงานน่าสยดสยอง แต่จำเป็นต่อพิธีที่เราจะทำ" },
        progress = { "137:146617002:1742444968", "หัวใจคนทรยศเป็นวัตถุดิบทรงพลัง เปลวเพลิงจะยินดีรับเครื่องบูชาเช่นนี้ และลุกโชนเข้มขึ้นขณะเผาผลาญมัน" },
        completion = { "282:121440595:1631783385", "Windshaper ไม่ลืม เลือดต้องชดใช้ด้วยเลือด ข้ายินดีที่เจ้าส่งคำเตือนสุดท้ายอันเจ็บปวดถึงหลักยึดของเราให้คนทรยศนี้ได้\n\nแต่วันนี้หัวใจนี้ไม่ใช่สิ่งเดียวที่จะเลี้ยงเปลวเพลิง ยังมีอีกงานต้องทำ", variants = { { "279:1353965661:1427235584", "Windshaper ไม่ลืม เลือดต้องชดใช้ด้วยเลือด ข้ายินดีที่เจ้าส่งคำเตือนสุดท้ายอันเจ็บปวดถึงหลักยึดของเราให้คนทรยศนี้ได้\n\nแต่วันนี้หัวใจนี้ไม่ใช่สิ่งเดียวที่จะเลี้ยงเปลวเพลิง ยังมีอีกงานต้องทำ" } } },
        required = { [277267] = { "16:75767201:1246780378", "หัวใจของ Faladiel" } },
        steps = { { "16:75767201:1246780378", "หัวใจของ Faladiel" } },
    },
    [97257] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "167:1659899055:1776484817", "รอ Olariaan เริ่มพิธีที่ Brazier of Offering แล้วทำตามคำสั่ง\n\nต้องนำ Eternal Flame ไปถึง Valanaar ก่อนหมดเวลา" },
        description = { "419:788273596:2008300771", "ตอนนี้เราจะทำพิธี\n\nข้าจะวางวัตถุดิบบนแท่นและเรียกวิญญาณไฟ หากรับเครื่องบูชา พวกมันจะปรากฏและจุด Eternal Flame จากนั้นยื่นคบเพลิงรับเปลวไฟ\n\nนำคบเพลิงที่ติดแล้วไป Valanaar วางใน Brazier of Eternal Flames ต้องรีบ เพราะเปลวไฟแห่ง Firelands สลายรวดเร็วใน Skywall" },
        progress = { { "74:2122718671:1221185034", "67:1926295319:786893579 N 1:46:46", "67:1926295319:786893579 C 1:46:46", "67:1926295319:786893579 R 1:46:46" }, "เจ้าทำดีมากที่มาไกลถึงนี่ เจ้าสร้างเกียรติให้ Windshaper สหาย" },
        completion = { { "304:693199809:1114650337", "171:280837943:1860651503 N 127:841588788:1375827886", "171:280837943:1860651503 C 127:841588788:1375827886", "171:280837943:1860651503 R 127:841588788:1375827886" }, "สำเร็จแล้ว Eternal Flame ลุกโชนอีกครั้ง\n\nบททดสอบจบสมบูรณ์ ข้ายินดีมอบ Fire Totem จงใช้สัญลักษณ์พลังนี้ให้ดีในการเดินทาง สหาย\n\nจำไว้ พลังแดนธาตุรับใช้ผู้เคารพ และเผาผลาญผู้ไม่เคารพ นี่คือวิถีเรา" },
        required = { [277329] = { "22:1083005121:400667334", "คบเพลิงแห่งเปลวไฟนิรันดร์" } },
        steps = { { "33:210130537:1339789099", "ประกอบพิธีร่วมกับ Olariaan ให้เสร็จ" }, { "34:1007953351:1722655342", "จุดไฟในกระถางเปลวเพลิงนิรันดร์" }, { "22:1083005121:400667334", "คบเพลิงแห่งเปลวไฟนิรันดร์" } },
    },
    [98046] = { -- Crown of the Earth
        title = { "18:1054641003:2021293941", "มงกุฎแห่งผืนดิน" },
        objective = { "74:1385591811:1801002467", "นำ Drained Vessel ไปให้ Lariia ที่ Temple of the Moon ใน Darnassus" },
        progress = { "18:1289510651:1267609563", "ข้าช่วยอะไรเจ้าได้บ้าง?" },
        completion = { { "173:1164686399:692244145", "28:1937759236:1974097317 N 139:445295451:886579420", "28:1937759236:1974097317 C 139:445295451:886579420", "28:1937759236:1974097317 R 139:445295451:886579420" }, "อย่าถือสาท่านอัครดรูอิดเลย สหาย เขาต้องแบกรับภาระมากมายในยามที่ Malfurion ไม่อยู่\n\nเดี๋ยวก่อน! ยังมีน้ำเหลืออยู่ในขวดไม่กี่หยด! บางทีนี่อาจเป็นเหตุที่คาถาของเขาไม่สำเร็จ?" },
        description = { "105:233185929:1724705242 C 262:1530088818:736946381", "<อัครดรูอิด Fandral Staghelm หรี่ตามอง>\n\nเจ้ายังอยู่อีกหรือ?\n\nเอาขวดไปแล้วไปให้พ้นตา {class} ชัดเจนว่าคำตอบข้าไม่อยู่ในน้ำ เช่นเดียวกับครั้งก่อน\n\nบางทีนักบวชหญิงที่ Temple of the Moon ทางใต้อาจกำจัดมันให้\n\n<Fandral เบือนหน้า ไม่พูดกับเจ้าอีก>\n\nข้าต้องมองหาที่อื่น หากจะทำให้สำเร็จ..." },
        required = { [279291] = { "14:999527631:87043424", "ภาชนะที่เทจนหมด" } },
        steps = { { "14:999527631:87043424", "ภาชนะที่เทจนหมด" } },
    },
    [98065] = { -- Crown of the Earth
        title = { "18:1054641003:2021293941", "มงกุฎแห่งผืนดิน" },
        objective = { "90:200269775:1411528658", "นำ Moonwell Remnants ไปให้ Tyrande Whisperwind ที่ Temple of the Moon ใน Darnassus" },
        description = { "324:704566596:1405568367", "เจ้าต้องนำสิ่งนี้ไปให้ Tyrande ทันที! ข้าจะย้ายมันลงภาชนะที่เหมาะกับพิธีการมากกว่านี้ให้\n\nอย่ากลัวเลย มหาปุโรหิตแห่ง Elune เข้มงวดแต่เมตตา นางปกป้องทุกคนที่เข้าสู่ Darnassus และนำแสงของเทพีมาสู่ทุกผู้คน\n\nนางจะยินดีรับน้ำศักดิ์สิทธิ์นี้ เจ้าจะพบนางอยู่ชั้นบนเหนือเรานี่เอง" },
        progress = { "71:2099806281:1574400537", "กรุณาบอกธุระมา ข้ามีทั้งเมืองที่ต้องดูแลและประชาชนที่ต้องนำทาง" },
        completion = { "498:1498603629:240237919", "Staghelm ทำสิ่งต่าง ๆ ไว้มากมายในช่วงที่คนรักของข้าไม่อยู่ แต่เขาไม่ใช่ Malfurion และเขาไม่ได้ปกครอง Darnassus ภาระนั้นเป็นของข้าแต่ผู้เดียว\n\n<สีหน้าของ Tyrande สงบลง>\n\nข้าต้องขออภัย อย่างที่เจ้าคงเห็น เรามีเรื่องต้องฝ่าฟันอีกมาก\n\nเวลานี้ Fandral ดำรงตำแหน่งอัครดรูอิด ข้าขอให้เจ้าเคารพตำแหน่งของเขา แต่กิจของเขาเกี่ยวกับวิถีดรูอิด ส่วนหน้าที่ของข้านอกจากรับใช้ Elune ยังต้องนำพาชนของเราตามพระประสงค์ของพระนาง\n\nน้ำนี้ทุกหยดได้รับพรจากพระเทวีของเรา ข้าขอบใจที่เจ้าช่วยรักษามันไว้" },
        required = { [279331] = { "17:79729727:842308749", "สิ่งที่หลงเหลือจากบ่อจันทร์" } },
        steps = { { "17:79729727:842308749", "สิ่งที่หลงเหลือจากบ่อจันทร์" } },
    },
    [98340] = { -- The Great Cat Spirit
        title = { "20:334676701:195687234", "วิญญาณแมวผู้ยิ่งใหญ่" },
        objective = { "70:1014218030:2080449173", "ไปคุยกับ Dendrite Starblaze ในหมู่บ้าน Nighthaven ที่ Moonglade" },
        description = { "389:1822311638:1223924265", "ดูเหมือนเจ้าจะพร้อมก้าวไปอีกขั้นบนเส้นทางของเจ้าแล้ว ดรูอิดรุ่นเยาว์ Dendrite Starblaze เรียกหาเจ้า และต้องการให้เจ้าไปพบเขาที่ Moonglade อีกครั้ง\n\nเจ้าเรียนรู้เวทที่พาตัวเองไปยัง Moonglade แล้ว จึงออกเดินทางได้ทันทีหากต้องการ ข้าแนะนำให้รีบไป หากเจ้าปรารถนาจะฝึกฝนวิถีดรูอิดต่อ" },
        completion = { "160:417727022:701271809 N 227:1349142753:53930782", "และแล้ววิถีนี้ก็ดำเนินต่อไป ท่านบิดา Cenarius\n\n<Dendrite ทำท่าทางสั้น ๆ กับอากาศว่างเหนือศีรษะ ออร่าพลังจาง ๆ ปกคลุมร่างเขา>\n\nสวัสดีอีกครั้ง {name} ถึงเวลาที่เจ้าจะเรียนรู้อีกด้านหนึ่งของธรรมชาติ นั่นคือแมว ข้าจะชี้หนทางให้เจ้าเข้าใจวิถีดรูอิดด้านนี้ แต่เช่นเดียวกับร่างหมี เจ้าเองต้องเป็นผู้เปิดรับบทเรียนและถ่ายทอดต่อไป" },
    },
    [98393] = { -- The Great Cat Spirit
        title = { "20:334676701:195687234", "วิญญาณแมวผู้ยิ่งใหญ่" },
        objective = { "70:1014218030:2080449173", "คุยกับ Dendrite Starblaze ที่หมู่บ้าน Nighthaven ใน Moonglade" },
        description = { "394:1909727270:1620013035", "ดูเหมือนเจ้าจะพร้อมก้าวไปอีกขั้นบนเส้นทางของเจ้าแล้ว นักผจญภัยรุ่นเยาว์ Dendrite Starblaze เรียกหาเจ้า และต้องการให้เจ้าไปพบเขาที่ Moonglade อีกครั้ง\n\nเจ้าเรียนรู้วิธีเรียกใช้เวทมนตร์พาตัวเองไปยัง Moonglade แล้ว จึงออกเดินทางได้ทันทีหากต้องการ ข้าแนะนำให้รีบไป หากเจ้าปรารถนาจะฝึกฝนวิถีดรูอิดต่อ", variants = { { "389:1822311638:1223924265", "ดูเหมือนเจ้าจะพร้อมก้าวไปอีกขั้นบนเส้นทางของเจ้าแล้ว ดรูอิดรุ่นเยาว์ Dendrite Starblaze เรียกหาเจ้า และต้องการให้เจ้าไปพบเขาที่ Moonglade อีกครั้ง\n\nเจ้าเรียนรู้วิธีเรียกใช้เวทมนตร์พาตัวเองไปยัง Moonglade แล้ว จึงออกเดินทางได้ทันทีหากต้องการ ข้าแนะนำให้รีบไป หากเจ้าปรารถนาจะฝึกฝนวิถีดรูอิดต่อ" } } },
        completion = { { "391:1578186012:437765854", "158:1322536916:1408400164 N 227:1349142753:53930782", "158:1322536916:1408400164 C 227:1349142753:53930782", "158:1322536916:1408400164 R 227:1349142753:53930782" }, "และวิถีนี้ก็ยังคงดำเนินต่อไป บิดา Cenarius\n\nDendrite วาดมืออย่างรวดเร็วในอากาศเหนือศีรษะ เป็นท่วงท่าที่มองไม่เห็น ออร่าแห่งพลังจาง ๆ แผ่คลุมร่างเขา\n\nยินดีที่ได้พบเจ้าอีกครั้ง สหาย ถึงเวลาเรียนรู้ธรรมชาติจากอีกมุมมองหนึ่งแล้ว นั่นคือแมว ข้าจะชี้ทางให้เจ้าเข้าใจชีวิตดรูอิดในแง่มุมนี้ แต่เช่นเดียวกับหมี เจ้าต้องเป็นผู้รับเอาความรู้นั้นไว้และเผยแพร่มันด้วยตนเอง", variants = { { "160:417727022:701271809 N 227:1349142753:53930782", "และวิถีนี้ก็ยังคงดำเนินต่อไป บิดา Cenarius\n\n<Dendrite วาดมืออย่างรวดเร็วในอากาศเหนือศีรษะ เป็นท่วงท่าที่มองไม่เห็น ออร่าแห่งพลังจาง ๆ แผ่คลุมร่างเขา>\n\nยินดีที่ได้พบเจ้าอีกครั้ง {name} ถึงเวลาเรียนรู้ธรรมชาติจากอีกมุมมองหนึ่งแล้ว นั่นคือแมว ข้าจะชี้ทางให้เจ้าเข้าใจชีวิตดรูอิดในแง่มุมนี้ แต่เช่นเดียวกับหมี เจ้าต้องเป็นผู้รับเอาความรู้นั้นไว้และเผยแพร่มันด้วยตนเอง" } } },
    },
    [98397] = { -- To Darnassus
        title = { "12:1457206771:456191317", "สู่ Darnassus" },
        objective = { "81:127132541:296852743", "กลับไปที่ Darnassus แล้วคุยกับ Mathrengyl Bearwalker ใน Cenarion Enclave" },
        description = { "424:1004395086:1030508372", "ถึงเวลาที่เราต้องแยกจากกันอีกครั้งแล้ว เจ้าผู้เยาว์วัย การนำบทเรียนไปใช้จะพาเจ้ากลับไปหาผู้ที่ส่งเจ้ามาพบข้า ดูเหมือนอาจารย์ของเจ้า Mathrengyl Bearwalker จะพบศิษย์ที่คู่ควรในตัวเจ้า ข้าเองก็เห็นเช่นนั้น จงใส่ใจคำสอนของเขา แล้วอีกไม่นานเจ้าจะสามารถเรียกพลังจากวิญญาณแมวผู้ยิ่งใหญ่เพื่อแปลงเป็นร่างของมันได้\n\nกลับไปยังที่ที่เจ้าจากมาเถิด เมื่อถึงเวลา เราจะได้พบกันอีก", variants = { { "426:944018429:1621863395", "ถึงเวลาที่เราต้องแยกจากกันอีกครั้งแล้ว เจ้าผู้เยาว์วัย การนำบทเรียนไปใช้จะพาเจ้ากลับไปหาผู้ที่ส่งเจ้ามาพบข้า ดูเหมือนอาจารย์ของเจ้า Mathrengyl Bearwalker จะพบศิษย์ที่คู่ควรในตัวเจ้า ข้าเองก็เห็นเช่นนั้น จงใส่ใจคำสอนของเขา แล้วอีกไม่นานเจ้าจะสามารถเรียกพลังจากวิญญาณแมวผู้ยิ่งใหญ่เพื่อแปลงเป็นร่างของมันได้\n\nกลับไปยังที่ที่เจ้าจากมาเถิด เมื่อถึงเวลา เราจะได้พบกันอีก" } } },
        completion = { { "467:756783593:844482123", "14:1649650394:897424258 N 447:691830771:132493576", "14:1649650394:897424258 C 447:691830771:132493576", "14:1649650394:897424258 R 447:691830771:132493576" }, "ยินดีต้อนรับกลับ สหาย ข้าสัมผัสได้ว่าเจ้าได้พบวิญญาณแมวผู้ยิ่งใหญ่และผ่านบททดสอบแล้ว ดรูอิดทุกคนต้องผ่านบททดสอบจากวิญญาณตนนี้ แม้บททดสอบจะแตกต่างกันไปในแต่ละรุ่น ข้าภูมิใจที่เจ้าผ่านมันและรับฟังภูมิปัญญาของวิญญาณแมวผู้ยิ่งใหญ่ มันเป็นวิญญาณโบราณที่อันตรายไม่แพ้ความขี้เล่น แต่ข้าสัมผัสได้ว่าเจ้าเข้าใจธรรมชาติของมันแล้ว\n\nบัดนี้ข้าจะสอนวิธีแปลงเป็นร่างแมวให้เจ้า" },
    },
    [98403] = { -- Twisted Hatred
        title = { "14:1379174177:1434409098", "ความเกลียดชังอันบิดเบี้ยว" },
        objective = { "107:1272086719:155718270", "ฆ่า Befouled Webwood 8 ตัว แล้วนำ Mature Fel Moss ของ Xethorr the Wicked ไปให้ Tallonkai Swiftroot ที่ Dolanaar", amount = { "5:409775429:850574908 W1 101:1673132504:363555062", "ฆ่า Befouled Webwood {world1} ตัว แล้วนำ Mature Fel Moss ของ Xethorr the Wicked ไปให้ Tallonkai Swiftroot ที่ Dolanaar" } },
        description = { "482:1523880996:1012947774", "Lord Melenas ไม่ได้ทำงานลำพัง เขาทำตามคำสั่งของผู้อื่น คนที่เจ้าต้องตามหาคือ Xethorr the Wicked ดูเหมือนมันจะบิดเบือนแมงมุมซึ่งอาศัยอยู่ใน Teldrassil และตั้งใจใช้พิษของพวกมันในแผนชั่วบางอย่าง\n\nมันอาศัยอยู่ลึกเข้าไปในป่า บริเวณทางตะวันตกเฉียงเหนือที่เรียกว่า Cleft จงระวังและพาพันธมิตรไปด้วย Xethorr ไม่ใช่คู่ต่อสู้ที่ควรประมาท\n\nกำจัดลูกสมุนของมัน แล้วนำสิ่งที่อาจบอกเราได้มากขึ้นเกี่ยวกับงานของเซเทอร์ที่นี่กลับมา" },
        completion = { "489:1150220694:1692141203", "ข้าน่าจะรู้ว่าสิ่งนี้ถูกใช้บิดเบือนแมงมุมในดินแดนนี้\n\nข้าได้ยินข่าวลือว่าสารนี้เป็นต้นเหตุของความเสื่อมทรามมากมายที่คุกคามพวกเรา แม้จะไม่ใช่ตัวอย่างดั้งเดิม แต่ก็เก่ากว่าที่เราเคยได้มา และอาจให้ข้อมูลมากกว่าเดิม\n\nปกติข้าคงให้เจ้าส่งมันไป Darnassus เพื่อศึกษาเพิ่มเติม แต่ตอนนี้ควรเก็บเรื่องนี้เงียบไว้ก่อน ไม่เช่นนั้น Dolanaar คงไม่มีวันกู้ชื่อเสียงคืนได้\n\nข้าเชื่อว่าเจ้าจะเก็บเรื่องนี้เป็นความลับเช่นกัน", variants = { { "489:661726317:1204075524", "ข้าน่าจะรู้ว่าสิ่งนี้ถูกใช้บิดเบือนแมงมุมในดินแดนนี้\n\nข้าได้ยินข่าวลือว่าสารนี้เป็นต้นเหตุของความเสื่อมทรามมากมายที่คุกคามพวกเรา แม้จะไม่ใช่ตัวอย่างดั้งเดิม แต่ก็เก่ากว่าที่เราเคยได้มา และอาจให้ข้อมูลมากกว่าเดิม\n\nปกติข้าคงให้เจ้าส่งมันไป Darnassus เพื่อศึกษาเพิ่มเติม แต่ตอนนี้ควรเก็บเรื่องนี้เงียบไว้ก่อน ไม่เช่นนั้น Dolanaar คงไม่มีวันกู้ชื่อเสียงคืนได้\n\nข้าเชื่อว่าเจ้าจะเก็บเรื่องนี้เป็นความลับเช่นกัน" } } },
        progress = { "61:569023322:631681750", "<Tallonkai ลดเสียงลง>\n\nXethorr ยังลอยนวลอยู่หรือ?" },
        required = { [281023] = { "15:1096402778:1991796622", "มอสเฟลที่โตเต็มที่" } },
        steps = { { "15:1096402778:1991796622", "มอสเฟลที่โตเต็มที่" } },
        objectiveLabels = {
            monster = { ["Befouled Webwood slain"] = "ปราบ แมงมุม Webwood ที่แปดเปื้อน" },
        },
    },
    [98517] = { -- Call of Fire
        title = { "12:1751187920:819557024", "เสียงเรียกแห่งไฟ" },
        objective = { "231:1617670044:1990479054", "รายงานตัวต่อ Sessaria Skystride หรือ Aarnor Galestrike บน Zephras Isle เพื่อฝึก Shaman ต่อ กลับ Zephras ได้ด้วยเรือเหาะ Skycutter ซึ่งเทียบท่าใน Mulgore ที่ Skywatcher Plateau ทางตะวันตกเฉียงเหนือของ Thunder Bluff" },
        description = { "281:1014442729:6189214", "สวัสดี Skyborne น้อย วิญญาณกล่าวถึงเจ้าและบอกว่าพร้อมฟังเสียงเรียกแห่งไฟแล้ว แต่ข้าจะไม่ใช่ผู้เริ่มเส้นทางนี้ให้ กลับบ้านในแดนธาตุ ไปหาครูที่นั่น พวกเขาจะบอกว่าต้องทำอะไร" },
        completion = { "68:1651695985:1541329153 N 17:1370131888:1585693863", "ข้าดีใจที่เจ้ากลับมาร่วมพิธีสำคัญนี้ {name} เราเริ่มกันเลยดีไหม?" },
        required = { [6653] = { "26:917262829:1125779937", "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" } },
        objectiveLabels = {
            item = { ["Torch of the Dormant Flame"] = "คบเพลิงแห่งเปลวไฟที่สงบนิ่ง" },
        },
    },
    [1071] = { -- A Gnome's Respite
        title = { "17:318989809:310954148", "เวลาพักของโนม" },
        objective = { "105:540569017:1002269453", "ฆ่า Venture Co. Logger 10 คน และ Venture Co. Deforester 10 คน แล้วกลับไปหา Gaxim Rustfizzle ใน Stonetalon" },
        description = { "9:1643668887:5171483 N 490:997506534:938689999", "ฟังนะ {name} ข้าเป็นสมาชิกสมัชชาผู้รู้แจ้งด้านศาสตร์อาคม การเล่นแร่แปรธาตุ และวิศวกรรม เป้าหมายของข้า... ไม่สิ หน้าที่! คือแสดงให้ไนต์เอลฟ์เห็นว่าเวทมนตร์ ยาผสม และกลไกรวมกันช่วยกู้ป่าได้\n\nแต่ศึกนี้ยากนัก กอบลินดูแพร่พันธุ์เหมือนกระต่าย ข้าไม่มีเวลาสร้างสิ่งประดิษฐ์ใหม่ด้วยซ้ำ!\n\nต้องการเวลาวางแผนและจัดงาน ช่วยกันพวกกอบลินใน Windshear Crag ทางตะวันออกไว้ก่อน..." },
        progress = { "33:1630715038:1589391197 N 1:63:63", "ทางเจ้าเป็นอย่างไรบ้างในสนามรบ {name}?" },
        completion = { "30:1410047895:1376094197 N 398:619072553:796033293", "ขอบใจมาก {name} กลับมาทันเวลาพอดี\n\nข้าว่ามีแผนสมบูรณ์แบบ... ระเบิด! นั่นไม่ใช่แผนทั้งหมด แต่เป็นส่วนหนึ่ง\n\nข้าใช้วัตถุระเบิดแรงสูงไล่กอบลินให้ถอย อย่ากังวล มันไม่อันตรายอย่างที่ทุกคนคิด ระเบิดตามแนวเขาตรงจุดสำคัญก็ต้อนพวกมันได้ แต่เสบียงข้าขาดมาหลายวันแล้ว..." },
        objectiveLabels = {
            monster = { ["Venture Co. Logger slain"] = "ปราบ คนตัดไม้ของ Venture Co.", ["Venture Co. Deforester slain"] = "ปราบ คนถางป่าของ Venture Co." },
        },
    },
    [1072] = { -- An Old Colleague
        title = { "16:202248644:558566531", "เพื่อนร่วมงานเก่า" },
        objective = { "38:175313416:1467516630", "ไปคุยกับ Lomac Gearstrip ใน Ironforge" },
        description = { "473:139340511:1921659164", "อุปกรณ์ที่คิดไว้เป็นรุ่นก้าวหน้าที่สุดของข้า แต่ต้องใช้ยาพิเศษจึงทำงานได้ งานนี้อาจเป็นภารกิจสุดท้ายของเจ้า ใช้ของดีไปเลยดีกว่า\n\nเราต้องการวัตถุระเบิดทรงพลัง Nitromirglyceronium\n\nคนเดียวที่ทำ NG-5 ได้คือ Lomac Gearstrip เพื่อนเก่าข้า ไปหาใน Tinker Town\n\nเจ้ากล่อมให้เขาทำ NG-5 ส่วนข้าจะคิดตำแหน่งวางอุปกรณ์" },
        completion = { "81:797603268:1997066266", "อา... Gaxim ส่งเจ้ามาสินะ? ข้าจะรู้ได้อย่างไรว่าเจ้าไม่ได้โกหก?! หืม? หืม...?" },
    },
    [1073] = { -- Ineptitude + Chemicals = Fun
        title = { "28:334652824:614841225", "ความไร้ฝีมือ + สารเคมี = ความสนุก" },
        objective = { "92:1263907817:126594859", "นำ Minor Mana Potion 4 ขวด และ Elixir of Minor Fortitude 2 ขวดไปให้ Lomac Gearstrip ใน Ironforge" },
        description = { "466:87356013:368978589", "ฮ่า ๆ... เจ้าต้องการ Nitromirglyceronium ไปหยุดกอบลินทำลายป่าหรือ?!\n\nจะรู้จัก Gaxim หรือไม่ก็ช่าง ข้ายอมให้ของแค่เพื่อดูเจ้าหรือพวกมันระเบิดเป็นชิ้นเล็กชิ้นน้อย\n\nแต่มีปัญหา ของหมด\n\nเอาอย่างนี้ เอายาที่ถูกต้องมา ข้าจะทำให้ทันที\n\nอย่างน้อยก็ควรพิสูจน์ว่ารู้จักการเล่นแร่แปรธาตุบ้าง ก่อนข้าให้ตัวอย่างสิ่งประดิษฐ์ชั้นยอด" },
        progress = { "98:1369412608:1625356813", "ไม่มีน้ำยาก็ทำ Nitromirglyceronium ไม่ได้ มันสำคัญต่อการสร้างนะ..." },
        completion = { "165:326149071:1295225271", "ใช้ได้ทีเดียว\n\nถ้าไม่รู้อย่างอื่น ข้าคงคิดว่าเจ้าเข้าใจการเล่นแร่แปรธาตุอยู่บ้าง คนแปลกหน้า ดี ดี... โลกไม่ได้มีแค่ดาบกับเวทมนตร์หรอกนะ" },
        required = { [2455] = { "17:389178522:1496298864", "ยามานาขนาดเล็ก" }, [2458] = { "25:81977411:874413227", "ยาเสริมความทรหดขั้นต้น" } },
        objectiveLabels = {
            item = { ["Minor Mana Potion"] = "ยามานาขนาดเล็ก", ["Elixir of Minor Fortitude"] = "ยาเสริมความทรหดขั้นต้น" },
        },
    },
    [1074] = { -- Ineptitude + Chemicals = Fun
        title = { "28:334652824:614841225", "ความไร้ฝีมือ + สารเคมี = ความสนุก" },
        objective = { "69:1325931625:1420103041", "นำ Nitromirglyceronium กลับไปให้ Gaxim Rustfizzle ใน Stonetalon" },
        description = { "185:629854130:462303107", "นี่ คนแปลกหน้า ระวังด้วย... ของนี้ระเบิดง่าย\n\nถ้าเป็นเพื่อน Gaxim จริง ฝากทักทายเขา ถ้าไม่ใช่ ก็ขอให้สนุกกับการระเบิดตัวเอง" },
        progress = { "31:706820904:1606453605", "อา ดี ดี กลับมาแล้ว" },
        completion = { "36:97456850:496461589 N 183:785150757:1547112264", "ทำงานได้ไร้ที่ติ {name}\n\nNG-5 คือส่วนประกอบสำคัญยิ่งในสูตรจุดชนวนรถบรรทุกไดนาไมต์\n\nอะไรนะ? ใช่ ไดนาไมต์... เป็นคันรถเลย เป็นตัวเบี่ยงเบนความสนใจที่สมบูรณ์แบบ บอกแล้ว รอดูเถอะ" },
        required = { [5732] = { "4:1328719351:176575477", "NG-5" } },
        steps = { { "4:1328719351:176575477", "NG-5" } },
    },
    [1075] = { -- A Scroll from Mauren
        title = { "20:1869221044:116324451", "ม้วนคาถาจากเมาเรน" },
        objective = { "32:1659584310:1935911571", "ไปหา Collin Mauren ใน Stormwind" },
        description = { "495:795648279:1532963277", "เอาล่ะ มาถึงส่วนจุดระเบิดระยะไกล... อ้อ ข้ายังไม่ได้อธิบายสินะ?\n\nสรุปคือใช้เวทนิดหน่อยทำให้ระเบิดได้ตอนเจ้าอยู่ไกล ข้ากำลังประกอบเครื่องที่กดปุ่มเดียวก็ให้ NG-5 ระเบิดเมื่อพร้อม\n\nแต่ต้องใช้คาถาจาก Collin Mauren เพื่อนใน Stormwind เขาอยู่ Mage Quarter เป็นมนุษย์ คงหาไม่ยาก" },
        completion = { "94:1330289120:1210393986", "คาถาที่เจ้าต้องการ ให้จุดระเบิดจากระยะไกลได้... อืม" },
    },
    [1076] = { -- Devils in Westfall
        title = { "18:1348396293:1919947628", "ปีศาจในเวสต์ฟอลล์" },
        objective = { "54:1207154760:1362251154", "นำ Dust Devil Debris ไปให้ Collin Mauren ใน Stormwind" },
        description = { "471:1174032173:750533925", "อา คิดออกแล้ว คาถาส่งสาร... น่าจะให้ผลอย่างที่เขาต้องการ\n\nข้าต้องสร้างม้วนที่ประทับคาถาไว้ ต้องใช้เศษจาก Dust Devil\n\nระหว่างรวบรวมส่วนประกอบอื่น เจ้าลองไป Westfall แล้วหาสัตว์ร้ายนั่นที มันอันตราย แต่หากกล้ายอมเป็นส่วนหนึ่งในการทดลองของ Gaxim ก็น่าจะรับมือไหว\n\nข้าจะรออยู่ที่นี่" },
        progress = { "7:989913233:66981971 N 38:1672939128:1127195018", "สวัสดี {name} พบส่วนประกอบที่ข้าต้องการหรือยัง?" },
        completion = { "71:1639554524:563527731", "ขอเวลาอีกนิด แล้วม้วนคาถาจะพร้อมให้เจ้า" },
        required = { [5669] = { "17:1813280334:1312251485", "เศษซากของภูตพายุฝุ่น" } },
        steps = { { "17:1813280334:1312251485", "เศษซากของภูตพายุฝุ่น" } },
    },
    [1077] = { -- Special Delivery for Gaxim
        title = { "26:237769795:1361317969", "ของส่งพิเศษถึงแก็กซิม" },
        objective = { "64:1040711578:2013440303", "นำ Scroll of Messaging ไปให้ Gaxim Rustfizzle ใน Stonetalon" },
        description = { "14:510644690:581245021 N 166:861940788:913241585", "นี่ {name} น่าจะใช้ได้ดี\n\nฝากความระลึกถึง Gaxim ด้วยเมื่อพบเขาอีก ข้ารอฟังเรื่องการผจญภัยเมื่อเสร็จสิ้นแล้ว\n\nขอให้เดินทางปลอดภัย" },
        progress = { "57:2025995320:1707345803", "ฮ่า! กลับมาแล้ว! ได้มาหรือ? ได้คาถาหรือเปล่า?" },
        completion = { "17:1552185832:722447846 N 274:305143627:926223573", "สมบูรณ์แบบ {name}! เยี่ยมมาก\n\nคาถานี้ผสมกับ NG-5 จะเป็นระเบิดควบคุมระยะไกลที่สมบูรณ์แบบ\n\nเราจะเบี่ยงเบนความสนใจให้เจ้าแอบเข้าไปขโมยจดหมายและแบบวิศวกรรม Venture Co.\n\nมันจะชะลอการทำลายป่าของพวกนั้นแน่" },
        required = { [5731] = { "19:728362390:306660838", "ม้วนคาถาส่งข้อความ" } },
        steps = { { "19:728362390:306660838", "ม้วนคาถาส่งข้อความ" } },
    },
    [1078] = { -- Retrieval for Mauren
        title = { "20:2120418312:959022833", "หาของให้เมาเรน" },
        objective = { "57:732622664:1283360951", "นำ Crystalized Scale 8 ชิ้นไปให้ Collin Mauren ใน Stormwind" },
        description = { "501:1656808793:1659689756", "คนเดินทางถามเรื่อง Stonetalon Mountains อยู่เรื่อย ดูเป็นสถานที่ผจญภัยยอดนิยม ไม่ว่าจะหาไวเวิร์น วิญญาณธาตุ หรือมีธุระกับ Venture Co.\n\nใน Charred Vale ลึกเข้า Stonetalon เคยมีบาซิลิสก์ชนิดหนึ่ง เกล็ดบดเป็นผงใช้เป็นส่วนประกอบชั้นเยี่ยมสำหรับคาถาที่ข้าสร้าง\n\nถ้ายังมีอยู่ อยากได้เกล็ดสักจำนวนหนึ่ง\n\nค่อย ๆ ทำ ไม่รีบ แต่ข้าจ่ายงาม" },
        progress = { "13:1366380142:1891123769 N 74:1921660753:586585069", "สวัสดีอีกครั้ง {name}\n\nกลับจากหุบเขาใน Stonetalon พร้อมเกล็ดแล้วหรือ?" },
        completion = { "17:1552185832:722447846 N 98:613247490:1938093652", "ยอดเยี่ยม {name} ขอบใจมาก\n\nสักวันข้างหน้า ข้าอาจช่วยเจ้าได้เหมือนที่เจ้าช่วยข้า" },
        required = { [5675] = { "18:360814228:1139421110", "เกล็ดที่ตกผลึก" } },
        steps = { { "18:360814228:1139421110", "เกล็ดที่ตกผลึก" } },
    },
    [1079] = { -- Covert Ops - Alpha
        title = { "18:1981530873:1108443424", "ปฏิบัติการลับ อัลฟา" },
        objective = { "84:840684999:1911176046", "ขโมย Venture Co.'s Engineering Plans จากโรงเลื่อยใน Windshear Crag" },
        description = { "12:1878497415:924553300 N 401:1974922882:1464136964", "ถึงเวลาแล้ว {name} ฟังให้ดี อุปกรณ์เสร็จพร้อมใช้\n\nรับเอกสารนี้ไป มันอธิบายตัวจุดชนวน วัตถุระเบิด และจุดที่ควรวาง\n\nจำไว้ว่าภารกิจสำเร็จไม่ได้วัดจากความเสียหายที่ก่อ แผนอัลฟาสำเร็จเมื่อเจ้านำแบบวิศวกรรม Venture Co. จากในโรงเลื่อยทางใต้ของ Cragpool Lake กลับมา" },
        progress = { "23:1330724811:1234839415 N 1:63:63", "ได้แบบมาแล้วหรือ {name}?" },
        completion = { "196:293390445:916959873", "น่าทึ่งจริง! นี่เป็นความเสียหายครั้งใหญ่ของ Venture Co.\n\nเราจะหาจุดอ่อนเครื่องจักร และนำแบบของมันมาพัฒนาสิ่งประดิษฐ์ของเราได้ เป็นวันที่วิเศษจริง ๆ" },
        required = { [5718] = { "29:495565413:1199868020", "แบบแปลนวิศวกรรมของบริษัท Venture" } },
        steps = { { "29:495565413:1199868020", "แบบแปลนวิศวกรรมของบริษัท Venture" } },
    },
    [1080] = { -- Covert Ops - Beta
        title = { "17:2096503447:1699069375", "ปฏิบัติการลับ เบตา" },
        objective = { "87:1013499061:1396103922", "ขโมย Venture Co. Letters จาก Windshear Mine ทางตะวันออกสุดของ Windshear Crag" },
        description = { "34:830685033:414571456 N 239:718753504:1989177138", "แผนเบตาเหมือนแผนอัลฟา {name}\n\nเราเบี่ยงเบนความสนใจ แล้วขโมยจดหมายล้ำค่าของมัน\n\nหัวใจสำคัญคือจดหมาย จำไว้\n\nเอกสารที่ให้ไปบอกจุดวางระเบิดแล้ว ขอแค่กลับมามีชีวิตพร้อมจดหมาย..." },
        progress = { "13:611156612:568477480 N 1:63:63", "เป็นอย่างไรบ้าง {name}?" },
        completion = { "12:1896001069:549194618 N 96:1352757834:1431553009", "เหลือเชื่อ {name}! Kaela กับ Sentinel ต้องดีใจมาก ฝีมือเจ้ากับสิ่งประดิษฐ์ข้ารวมกัน ไม่มีใครหยุดได้" },
        required = { [5717] = { "19:1596757623:590768535", "จดหมายของบริษัท Venture" } },
        steps = { { "19:1596757623:590768535", "จดหมายของบริษัท Venture" } },
    },
    [1081] = { -- Reception from Tyrande
        title = { "22:520164388:1175182170", "เข้าพบไทแรนดา" },
        objective = { "38:2058052059:493317295", "ไปหา Tyrande Whisperwind ใน Darnassus" },
        description = { "N 346:1398778303:827271110", "{name} ข้ามั่นใจว่า Tyrande Whisperwind อยากขอบคุณด้วยตัวเองที่เจ้าร่วมภารกิจ\n\nอาจดูไม่ชัด แต่สิ่งที่เจ้าช่วยเริ่มอาจเสริมฐานของเราใน Stonetalon Mountains ได้มาก\n\nหากถือว่าเป็นพันธมิตรต่อต้านความโหดร้ายนี้ จงไปหา Tyrande ใน Temple of the Moon ที่ Darnassus" },
        completion = { "7:989913233:66981971 N 219:600777215:11025120", "สวัสดี {name} ข้าเคยได้ยินชื่อเจ้า แม้ยังเยาว์วัย แต่ยินดีที่เห็นหนทางที่เลือกเดิน\n\nจะเป็นเกียรติแก่ข้ามากหากยอมรับสิ่งนี้เป็นของขวัญแทนความซาบซึ้ง" },
    },
    [1082] = { -- Update for Sentinel Thenysil
        title = { "28:359749328:1059366737", "แจ้งข่าวแก่เซนทิเนลเธนิซิล" },
        objective = { "41:638454052:797820636", "กลับไปหา Sentinel Thenysil ใน Ashenvale" },
        description = { "N 325:1451593858:696950942", "{name} เจ้าได้ทำความดีครั้งใหญ่ที่ช่วยที่นี่\n\nSentinel แห่ง Ashenvale จะตอบแทนงามหากรู้ว่า Gaxim กับข้ายังมีชีวิต บอกว่าเราคืบหน้าไปมากในการหยุด Venture Co. และเยียวยาผืนดิน\n\nไปหา Tara Thenysil ใน Astranaar นางจะยินดีที่เจ้ากลับพร้อมข่าวดี" },
        completion = { "11:1191658970:1224418299 N 132:1226743713:1949034930", "ขอบใจ {name} เจ้าช่วยเหล่า Sentinel ไว้\n\nดีใจที่ Kaela... และแม้แต่ Gaxim ยังสบายดี\n\nเจ้าสมควรได้รับความขอบคุณของเรา" },
    },
    [1083] = { -- Enraged Spirits
        title = { "15:1259346558:738418775", "วิญญาณเกรี้ยวกราด" },
        objective = { "113:808970035:431613914", "เก็บ Smoldering Ember 8 ชิ้นจากวิญญาณธาตุไฟใน Charred Vale แล้วนำไปให้ Kaela Shadowspear ใน Stonetalon" },
        description = { "485:1249104032:2032531189", "ข้าไม่แน่ใจว่า Venture Co. ทำอะไรกับหุบเขา แต่เห็นชัดว่าพวกเขาถูกสิ่งมีชีวิตที่นั่นเล่นงานจนต้องถอย\n\nพวกเขาเผาป่า ใช้สิ่งประดิษฐ์ทำลายล้างหุบเขาให้มากที่สุด\n\nแต่ความไม่รู้ยังปล่อยสิ่งอื่นออกมา วิญญาณลุกไหม้ ธาตุแห่งไฟ ศิลา และโทสะ\n\nผืนดินจะไม่ได้รับรอยยิ้มของ Elune ขณะที่พวกนี้ยังเพ่นพ่าน\n\nนำถ่านคุจากพวกมันมาให้ข้าเป็นหลักฐานว่าลดจำนวนลงแล้ว" },
        progress = { "53:2003026177:1846615422 N 1:46:46", "ครั้งแรกที่เห็น Charred Vale ข้าแทบร้องไห้ {name}" },
        completion = { "58:581521651:1953385277 N 12:513407318:1685728707", "ซากศัตรูของเรา... กำลังเจ้าช่วยได้มาก {name} ขอบใจ" },
        required = { [5659] = { "17:1864617071:797414315", "ถ่านคุกรุ่น" } },
        steps = { { "17:1864617071:797414315", "ถ่านคุกรุ่น" } },
    },
    [1084] = { -- Wounded Ancients
        title = { "16:1949835788:1832067963", "ผู้พิทักษ์โบราณที่บาดเจ็บ" },
        objective = { "70:637111308:59321137", "นำ Corroded Shrapnel ไปให้ Kaela Shadowspear ใน Stonetalon" },
        description = { "484:702814797:674105422", "ข้าว่าผู้พิทักษ์หุบเขาอย่างทรีแอนต์มีส่วนผลัก Venture Co. ให้ถอย แต่น่าเศร้าที่แม้ผู้พิทักษ์ผู้ยิ่งใหญ่เหล่านั้นก็ถูกความแปดเปื้อนแล้ว\n\nGaxim คิดว่ามันเกี่ยวกับอาวุธที่กอบลินใช้ระหว่างล่าถอย\n\nข้าบอกว่าจะเก็บตัวอย่างจากทรีแอนต์บาดเจ็บให้ศึกษาว่าจริงหรือไม่\n\nนำสะเก็ดอาวุธมาให้ข้า โนมจะได้อธิบายเพิ่ม..." },
        progress = { "114:2091882121:612854840", "รู้สึกว่า Gaxim คงหาประโยชน์จากสะเก็ดอาวุธได้ ไม่ว่า Venture Co. จะเคยใช้มันอย่างไร" },
        completion = { "11:1191658970:1224418299 N 130:1662991992:1626778092", "ขอบใจ {name}\n\nนี่น่าจะมากพอให้ Gaxim รู้ว่าทรีแอนต์แปดเปื้อนอย่างไร ข้าจะเอาไปให้ทันที" },
        required = { [5664] = { "17:376749305:1356715318", "เศษสะเก็ดโลหะที่ผุกร่อน" } },
        steps = { { "17:376749305:1356715318", "เศษสะเก็ดโลหะที่ผุกร่อน" } },
    },
    [1090] = { -- Gerenzo's Orders
        title = { "16:1052009950:781843405", "คำสั่งของเจเรนโซ" },
        objective = { "63:1369971406:193764883", "รับแร่ลึกลับจาก Piznik หลังเขาขุดเสร็จ" },
        description = { "507:184457102:1862934841", "รู้ไหม ข้าเคยสำคัญเป็นอันดับสองของแหล่งงานนี้ ทุกอย่างเปลี่ยนเมื่อ Gerenzo เข้ามา เขาไล่ Ziz Fizziks นายข้าออกแล้วส่งข้าลงเหมือง แต่ Ziz บอกให้อยู่สืบข้อมูลต่อ นายใหม่ของเขาจะจ่ายงามหากรู้แผน Gerenzo\n\nเท่าที่รู้ Gerenzo สั่งขุดแร่สีเขียวทองจำนวนมาก ข้าเก็บตัวอย่างให้เอาไปหา Ziz ได้ แต่เจ้าต้องระวังหน่วยลาดตระเวนระหว่างข้าขุด" },
        completion = { "8:1268007095:436687658 N 220:1332462386:11914420", "ขอบใจ {name} เมื่อครู่เกือบแย่แล้ว คงดึงความสนใจมากเกินไป\n\nแต่สำคัญคือได้ตัวอย่างแร่ เราควรส่งให้ Ziz โดยเร็ว" },
        progress = { "112:2064696929:977788277", "ระวังนะ แถวนี้มีทั้งหน่วยลาดตระเวนกับคนงานเดินผ่านอยู่ตลอด ถ้าถูกจับได้ เราอาจเดือดร้อนเอาได้" },
        objectiveLabels = {
            event = { ["Keep Piznik safe while he mines the mysterious ore"] = "คุ้มกัน Piznik ขณะเขาขุดแร่ปริศนา" },
        },
    },
    [1091] = { -- Kaela's Update
        title = { "14:1726085021:1515829302", "แจ้งข่าวแก่เคลา" },
        objective = { "51:1922219832:213535271", "นำ Venture Co. Letters ไปให้ Kaela Shadowspear" },
        description = { "N 213:1339161676:992293976", "{name} นำจดหมายนี้ไปให้ Kaela นางคงอยากรู้ หรืออย่างน้อย Sentinel ก็อยากรู้\n\nอย่าลืมบอกว่าเราสำเร็จเพียงใด และคงทำไม่ได้หากไม่มีเวทมนตร์นิดหน่อย" },
        progress = { "5:1287366450:669725923 N 24:785078181:1637541725", "มีอะไรหรือ {name}? ให้ข้าช่วยอะไร?" },
        completion = { "63:634397000:2018597131 N 12:513407318:1685728707", "น่าสนใจจริง ๆ\n\nเจ้ากับ Gaxim ทำได้ดีมาก {name} ขอบใจ" },
        required = { [5717] = { "19:1596757623:590768535", "จดหมายของบริษัท Venture" } },
        steps = { { "19:1596757623:590768535", "จดหมายของบริษัท Venture" } },
    },
    [1092] = { -- Gerenzo's Orders
        title = { "16:1052009950:781843405", "คำสั่งของเจเรนโซ" },
        objective = { "72:2073382586:1830617577", "นำ Unidentified Ore ไปให้ Ziz Fizziks ใน Stonetalon Mountains" },
        description = { "470:272480280:429672546", "ข้าคงต้องคิดออกจากที่นี่ด้วย อีกไม่นานเรื่องจะถึงผู้ใหญ่ พวกเขาคงไม่ยินดีพบข้าอีก\n\nข้าจะลอบไปหา Ziz หวังว่าเขาหางานใหม่ให้ได้!\n\nจะลองเก็บกวาดแถวนี้หน่อย แต่เจ้าควรเอาแร่ไปหา Ziz ทันที เขาบอกว่าตั้งค่ายฝั่งตะวันตกของ Windshear Crag ขอให้โชคดี" },
        progress = { "30:23520830:2063270366", "มีอะไรให้ข้าช่วยหรือ?" },
        completion = { "254:1707597937:901474674", "อา รู้อยู่แล้วว่าคิดถูกที่ให้ Piznik อยู่ต่อ วิศวกรใน Undermine ต้องอยากดูสิ่งนี้มากแน่...\n\nแน่นอนว่าข้าอยากเก็บส่วนเล็ก ๆ ไว้เอง แต่สิ่งที่พวกเขาไม่รู้ก็ไม่ทำให้เจ็บ จริงไหม?" },
        required = { [5733] = { "16:160378578:2085628175", "แร่ไม่ทราบชนิด" } },
        steps = { { "16:160378578:2085628175", "แร่ไม่ทราบชนิด" } },
    },
    [1093] = { -- Super Reaper 6000
        title = { "17:1255768142:278707085", "ซูเปอร์รีปเปอร์ 6000" },
        objective = { "81:1030709594:1810672954", "หา Super Reaper 6000 Blueprints ให้ Ziz Fizziks ใน Stonetalon Mountains" },
        description = { "474:618269593:704232754", "Venture Company ทำเรื่องแย่ที่นี่ ว่าไหม? คิดอะไรอยู่ บริษัทกอบลินไปจ้างโนม!\n\nโชคดีที่ Sputtervalve มองอัจฉริยะออก เขาจ้างข้าทันทีหลังถูกไล่!\n\nเขาบอกว่าบริษัทสร้างเครื่องตัดไม้ยักษ์ และอยากให้ขโมยแบบ แต่ Gerenzo เจ้าโนมบ้า สั่งฆ่าข้าทันทีที่พบ... เจ้าขโมยแทนได้ไหม? น่าจะอยู่กับคนควบคุมเครื่องสักคน" },
        progress = { "239:1101582175:1901622204", "พบแบบหรือยัง? ข้าอยากให้นายใหม่ประทับใจ หวังว่าเมื่อมั่นใจในความภักดี เท่าที่จะมั่นใจได้ตามเกียรติกอบลิน เขาจะกล้าใช้อัจฉริยภาพอันโดดเด่นของข้า" },
        completion = { "256:1223170900:1370154235", "เฮ้ นั่นใช่สิ่งที่ข้าคิดไหม? เยี่ยม!\n\nมาดูสิ อึ๋ย... จะเข้าใจได้อย่างไร... คิดแบบโนมไม่ออก บอกเลย แปลกใจที่พวกมันประดิษฐ์ล้อได้ ยังไม่ต้องพูดถึงเครื่องบินที่ชอบนัก" },
        required = { [5734] = { "28:1744412348:573012380", "แบบพิมพ์เขียว Super Reaper 6000" } },
        steps = { { "28:1744412348:573012380", "แบบพิมพ์เขียว Super Reaper 6000" } },
    },
    [1094] = { -- Further Instructions
        title = { "20:988064079:1250147571", "คำสั่งเพิ่มเติม" },
        objective = { "59:1779560253:1618299766", "นำ Sealed Envelope ไปให้ Sputtervalve ใน Barrens" },
        description = { "346:652052001:797288082", "ซองนี้มีข้อมูลทั้งหมดที่ฉวยได้ตอนถูกเตะออกมา เอกสารภายใน Venture Company คู่มือ เทคนิคต่าง ๆ... อ้อ แล้วก็แบบ Super Reaper 6000 แน่นอน\n\nSputtervalve อยู่ Ratchet ใน Barrens หาไม่ยาก เป็นเจ้าตัวเขียวเล็ก ๆ" },
        progress = { "32:1463415174:1782470929", "สวัสดี! ให้ข้าช่วยอะไร?" },
        completion = { "277:7430443:523744292", "Fizziks หรือ? บอกไม่ได้ว่าไว้ใจ แต่ข้อมูลดูดีพอ ข้าอยากให้ Venture Company พ้นหูพ้นตาเหลือเกิน\n\nแต่พวกนั้นก็คิดเครื่องจักรดี ๆ ได้... ปฏิเสธไม่ได้ว่าเรามีประโยชน์จากเทคนิคที่พวกมันพัฒนา" },
        required = { [5735] = { "15:1158788066:678914075", "ซองจดหมายปิดผนึก" } },
        steps = { { "15:1158788066:678914075", "ซองจดหมายปิดผนึก" } },
    },
    [1095] = { -- Further Instructions
        title = { "20:988064079:1250147571", "คำสั่งเพิ่มเติม" },
        objective = { "64:1012534533:570503212", "นำคำสั่งใหม่ไปให้ Ziz Fizziks ใน Stonetalon Mountains" },
        description = { "498:2091281909:98943915", "เรื่องโนมที่ Venture Company จ้างทำให้ Undermine ฮือฮา เหล่าเจ้าการค้าไม่เห็นชอบที่ Razdunk คบหากับ Gerenzo\n\nRiddlevox ขอให้ข้าจัดการปัญหา มั่นใจว่าเจ้าการค้าอย่างน้อยคนหนึ่งสั่งเขามาอีกที แน่นอน ท่านผู้อำนวยการไม่ได้บอก เอาเป็นว่าข้าสังหรณ์\n\nอย่างไรก็ตาม ต้องกำจัด Gerenzo ให้ Fizziks จัดการคงเป็นบททดสอบที่เหมาะ" },
        completion = { "433:1498271591:1245228600", "กำจัด Gerenzo หรือ? โอกาสแบบนี้ไม่มีข้อคัดค้าน\n\nลำพังโนมก็แย่พอ แต่สิ่งที่รู้เกี่ยวกับเขายิ่งแย่ ดูเหมือนเคยเป็นหัวหน้าวิศวกรคนหนึ่งใน Gnomeregan ทำโครงการลับที่สายเราเจาะ Dun Morogh ไม่ถึงรายละเอียด มันล้มเหลว รายงานบอกว่าไม่ว่าสิ่งนั้นคืออะไร มันระเบิดใส่หน้าพวกเขาจริง ๆ" },
    },
    [1096] = { -- Gerenzo Wrenchwhistle
        title = { "21:1269776117:1268331845", "เจเรนโซ เรนช์วิสเซิล" },
        objective = { "88:1174061984:1031182207", "นำ Mechanical Arm ของ Gerenzo Wrenchwhistle ไปให้ Ziz Fizziks ใน Stonetalon Mountains" },
        description = { "502:731192318:2115294234", "ข้าเคยพบ Gerenzo ครั้งหนึ่ง บอกเลยว่าไม่น่ามอง เนื้อเหมือนเน่าและมีโลหะกับเฟืองฝังตามตัว แขนขาบางส่วนเปลี่ยนเป็นกลไก\n\nทางตะวันออกเฉียงเหนือสูงเหนือ Cragpool Lake ใกล้กังหันน้ำ คือจุดที่เขาดูแลทั้งพื้นที่ ข้าคงสู้ขึ้นไปไม่ได้ ยิ่งสู้ Gerenzo ไม่ต้องพูดถึง... แต่เจ้าดูอาจทำไหว\n\nถ้าฆ่าแทนข้า จะตอบแทนให้คุ้ม!" },
        progress = { "107:1995757299:2066116059", "Sputtervalve ต้องอยากได้หลักฐานว่า Gerenzo ตาย แขนกลของเขาน่าจะพอ" },
        completion = { "403:1628691990:704498151", "ดูนั่นสิ... ต้องเป็นโนมถึงคิดของแบบนี้ ไม่เข้าใจว่าทำไมตัดแขนแทนด้วยของนั่น ทั้งที่เก็บสองแขนแล้วเพิ่มแขนที่สามได้!\n\nพวกโนมนี่จริง ๆ...\n\nอย่างน้อย Gerenzo ก็หยุดทำงานแล้ว หวังว่าหลักฐานจะพอให้ Sputtervalve ย้ายข้าไปโรงงานสหภาพช่างใน Gadgetzan หรืออาจถึง Undermine" },
        required = { [5736] = { "24:1087723215:1905558349", "แขนกลของ Gerenzo" } },
        steps = { { "24:1087723215:1905558349", "แขนกลของ Gerenzo" } },
    },
    [1047] = { -- The New Frontier
        title = { "16:1969382953:1771254860", "พรมแดนใหม่" },
        objective = { "146:1770419865:2011158472", "ไปคุยกับ Arch Druid Fandral Staghelm ใน Cenarion Enclave ของ Darnassus เรื่องคำเชิญของ Cenarion Circle ให้สำรวจพรมแดน Kalimdor" },
        description = { "453:829915230:349507449", "วีรชน โปรดฟัง!\n\nCenarion Circle ต้องการคนแข็งแรงมาช่วยสำรวจพรมแดนใหม่อันกว้างใหญ่ของ Kalimdor! ดินแดนรกร้างต้องห้ามที่เต็มไปด้วยอันตรายเกินจินตนาการอยู่ไกลไปทางตะวันตกของ Tanaris และ Gadgetzan ทางสภาต้องการผู้แทนที่สมัครใจและมีเกียรติไปทำหน้าที่\n\nผู้สนใจโปรดเข้าพบ Cenarion Circle คุยกับอัครดรูอิด Fandral Staghelm ใน Darnassus เพื่อทราบรายละเอียด!" },
        completion = { "64:1143222221:2095580571 C 349:1478702586:12269107", "อะไรทำให้คิดว่าข้าอยากถูกรบกวนโดยคนอย่างเจ้า {class}? เดี๋ยวนะ ข้าจะหยุดหน้าที่สำคัญประจำวันเพื่อช่วยเจ้าหาของกระจุกกระจิกสักแห่ง แน่นอน ความเป็นอยู่ของ Darnassus ไม่สิ ของ Teldrassil ทั้งหมด ควรสำคัญรองจากของสะสมชิ้นใหม่ของเจ้า\n\nเจ้าพวกโง่ใน Moonglade ส่งคำขอให้เสียเวลา แล้วยังต้องมาทนเรื่องนี้อีกหรือ?" },
    },
    [3763] = { -- Assisting Arch Druid Staghelm
        title = { "29:1148956102:1438083021", "ช่วยอัครดรูอิดสแต็กเฮล์ม" },
        objective = { "52:397099142:1481761258", "ไปคุยกับ Arch Druid Fandral Staghelm ใน Darnassus" },
        description = { "10:1827992962:185023149 C 423:424570723:1618639736", "ขอรบกวนเวลาสักครู่ได้ไหม {class}\n\nCenarion Circle ใน Darnassus กำลังหานักผจญภัยมากประสบการณ์อย่างเจ้าช่วยงานวิจัยสำคัญ แม้ไม่รู้รายละเอียด แต่บอกได้ว่าอัครดรูอิด Fandral Staghelm เป็นผู้นำงานด้วยตัวเอง\n\nหากสนใจ โปรดคุยกับเขาโดยตรงที่ Cenarion Enclave ภายใน Darnassus" },
        completion = { "10:1638626602:1885586213 C 234:1479284934:925420808", "เอาล่ะ {class}... เมื่อรู้ว่าข้าเป็นผู้นำงานเอง ก็คงรีบมาสุดกำลังสินะ\n\nในเมื่อมาถึงแล้ว ตั้งใจฟังรายละเอียดครั้งแรกให้ดี ข้าไม่อยากพูดซ้ำ" },
    },
    [3764] = { -- Un'Goro Soil
        title = { "12:1017872992:588641980", "ดินจากอันโกโร" },
        objective = { "76:270410088:115730867", "นำตัวอย่าง Un'Goro Soil 20 ชิ้นไปให้ Jenal ที่ Cenarion Enclave ใน Darnassus" },
        description = { "499:1040236208:943843425", "มีรายงานว่าดิน Un'Goro Crater อุดมด้วยคุณสมบัติเวทมนตร์ทรงพลัง ข้าต้องการแยกจริงจากเท็จ จงเข้าป่า Un'Goro เก็บตัวอย่างคุณภาพให้พอศึกษาต่อ\n\nถ้าคิดว่างานเก็บของต่ำต้อย เจตคตินั้นไม่ทำให้ข้าหรือ Cenarion Circle ชื่นชม เอาไปให้ Jenal เขาคงเสียเวลาอยู่ข้างนอกหลังต้นไม้นี้ มองหากองดินก็พอ เขาจะจัดการเรื่องขนส่งเอง ข้าไม่ทำ" },
        progress = { "153:1518478398:2021788828", "อา ใช่ ดิน อัครดรูอิดต้องการยี่สิบส่วนต่อนักผจญภัย และเขาต้องได้ยี่สิบส่วน ให้ผู้สมคบคิดต่อต้านเราหลีกทาง!" },
        completion = { "39:1442820018:240720853 C 215:1682382814:488388282 N 167:642404919:329635798", "วางของล้ำค่าตรงนี้ {class} ผู้สูงส่ง คงเป็นภาระหนัก... เช่นภาระของข้าผู้มีวิสัยทัศน์ นี่ค่าตอบแทนตามคำสั่งอัครดรูอิด\n\nStaghelm อยากคุยอีก {name} งานต่อไปจะง่ายขึ้นหากเจ้ารู้ Herbalism ระดับ Journeyman ถึงไม่รู้ก็ยังช่วยสภาได้!" },
        required = { [11018] = { "12:1017872992:588641980", "ดินจาก Un'Goro" } },
        objectiveLabels = {
            item = { ["Un'Goro Soil"] = "ดินจาก Un'Goro" },
        },
    },
    [3781] = { -- Morrowgrain Research
        title = { "20:2056345083:630742892", "วิจัยมอร์โรว์เกรน" },
        objective = { "97:865156471:112013435", "นำ Arch Druid's Seed Voucher ไปให้ Mathrengyl Bearwalker ที่ Cenarion Enclave ใน Darnassus" },
        description = { "416:1640110960:812337552", "เราใช้ Evergreen Pouch เพาะเมล็ด Tharlendris ในดินจาก Un'Goro Crater มันงอกเป็นสมุนไพรทรงพลังหลายชนิดแบบสุ่ม หนึ่งในนั้นคือ Morrowgrain สมุนไพรลึกลับที่รู้จักน้อย ข้าตั้งใจไขปริศนา\n\nนำสิ่งนี้ไปให้ Mathrengyl ชั้นล่าง เขาจะให้เมล็ดเริ่มงาน หากหมด ต้องซื้อเพิ่มจากเขา" },
        progress = { "95:1869929465:1935756851", "ขอความสงบสุขจงมีแก่เจ้า สหาย มาทำธุระตามคำขออัครดรูอิดใช่ไหม?" },
        completion = { "411:1795553152:1178381991", "ใช่ ใบนี้แลกเมล็ดได้ยี่สิบห่อ หากหมดก็มีเพิ่ม แต่น่าเสียดาย การผลิตเมล็ด Tharlendris จำนวนมากมีต้นทุนสูง Cenarion Circle จึงขอให้ผู้ร่วมงานช่วยออกค่าใช้จ่ายบางส่วน\n\nผู้ที่นำ Morrowgrain กลับมาจะพบว่ารางวัลอัครดรูอิดคุ้มต้นทุนมาก" },
    },
    [3785] = { -- Morrowgrain Research
        title = { "20:2056345083:630742892", "วิจัยมอร์โรว์เกรน" },
        objective = { "190:268525323:271930536", "ใช้ Evergreen Pouch กับ Packet of Tharlendis Seeds และ Un'Goro Soil สองชิ้นเพื่อเพาะ Morrowgrain แล้วนำ Morrowgrain 10 ชิ้นไปให้ Mathrengyl Bearwalker ใน Darnassus" },
        description = { "476:519674584:1830352034", "นี่ Evergreen Pouch สำหรับใช้กับเมล็ด Tharlendis ต้องมีตัวอย่างดิน Un'Goro เป็นปุ๋ยด้วย เมื่อมีครบก็ใช้ถุง ที่เหลือมันจะจัดการเอง\n\nเมื่อได้ Morrowgrain พอแล้ว นำมาให้ข้าที่เขตสภา อย่าไปรบกวนอัครดรูอิด เขายุ่งมาก ไม่จำเป็นต้องมีคนรบกวนทุกครั้งที่ได้ Morrowgrain อีกชุด!" },
        progress = { "4:1517439313:201828457 N 181:1635886437:1328373195", "ว่าไง {name} เพาะ Morrowgrain สำหรับงานวิจัยสำคัญของอัครดรูอิดแล้วหรือ? งานที่ทำให้ Cenarion Circle สำคัญมาก และความช่วยเหลือของเจ้าย่อมได้รับการเห็นค่า!" },
        completion = { "10:963015740:1087923650 N 324:479198315:1250266604", "ทำได้ดี {name} ข้าจะส่งให้อัครดรูอิดด้วยตัวเองเมื่อเขาต้องใช้ ระหว่างนั้นรับสิ่งนี้เป็นเครื่องหมายขอบคุณจาก Cenarion Circle\n\nเราต้องใช้ Morrowgrain ต่อเนื่อง หากอยากช่วยอีก จงกลับมาเมื่อเพาะได้เพิ่ม" },
        required = { [11040] = { "11:35561619:35128800", "มอร์โรว์เกรน" } },
        objectiveLabels = {
            item = { ["Morrowgrain"] = "มอร์โรว์เกรน" },
        },
    },
    [4493] = { -- March of the Silithid
        title = { "21:489507381:1905385308", "การรุกคืบของซิลิธิด" },
        objective = { "43:1838359856:2051515723", "ไปคุยกับ Alchemist Pestlezugg ใน Gadgetzan" },
        description = { "502:828893:1199699322", "ดูเหมือนเจตนา ไม่สิ เหตุแห่งการดำรงอยู่ของซิลิธิด คือกินทุกสิ่งที่ไม่ใช่ระบบนิเวศของมัน พวกมันมุ่งเป้าเดียว จึงเป็นภัยร้ายต่อชีวิตทั้งหมดบน Azeroth\n\nสิ่งที่เห็นเป็นเพียงระยะแรก ข้าสงสัยว่ากำลังมาจากส่วนลึกของ Kalimdor คือ Un'Goro Crater ไป Gadgetzan ในทะเลทราย Tanaris แล้วคุยกับ Alchemist Pestlezugg บอกทฤษฎีข้า เขาจะช่วยเราต่อสู้แน่" },
        completion = { "388:982345435:1814096270", "ใช่ ข้าเดาว่า Gracina ส่งมา ประสบการณ์สู้สัตว์พวกนี้ล้ำค่า เท่าที่รู้ยังไม่มีใครรับมือชนิดนี้มาก่อน ส่วนความคิดว่า Un'Goro Crater เป็นใจกลาง... อาจจริง Un'Goro เป็นป่าลึกลับอันตรายทางตะวันตก บางทีอาจพาเราใกล้คำตอบเรื่องซิลิธิดอีกขั้น" },
    },
    [4510] = { -- Calm Before the Storm
        title = { "21:1334673301:1302430267", "ความสงบก่อนพายุ" },
        objective = { "59:448005532:1824145442", "นำ Bank Voucher ไปให้ Idriana ในธนาคาร Darnassus" },
        description = { "N 487:684141606:2042477147 C 1:46:46", "{name} ความช่วยเหลือเจ้าประเมินค่าไม่ได้ สักวันข้าคงต้องขอแรงต้านซิลิธิดอีก เราต้องทบทวนสิ่งที่รู้จาก Un'Goro เกรงว่าสมมติฐานว่ามันกำเนิดที่นั่นจะผิด... อาจมีพลังยิ่งใหญ่กว่าที่อื่น\n\nนำบันทึกนี้ไปให้ Idriana ที่ธนาคาร นางจะมอบของจากคลังข้าเป็นเครื่องหมายขอบคุณ ขอบใจที่ช่วย {class} ผู้กล้า" },
        progress = { "13:285430642:1344636655 C 30:1957802472:1453745660", "Elune'adore {class} วันนี้ให้ข้ารับใช้อะไร?" },
        completion = { "160:683160314:348818809", "ใบนี้อนุญาตให้ข้าถอนของจากบัญชี Gracina Spiritmight มามอบให้เจ้า เห็นทีต้องแสดงความยินดี!" },
        required = { [11843] = { "12:1890069706:2001934597", "ใบรับรองจากธนาคาร" } },
        steps = { { "12:1890069706:2001934597", "ใบรับรองจากธนาคาร" } },
    },
    [5091] = { -- A Call to Arms: The Plaguelands!
        title = { "32:667387596:1841318316", "เรียกระดมพลสู่เพลกแลนด์!" },
        objective = { "112:1220981070:1070122399", "ไปหา Commander Ashlam Valorfist ที่ฐาน Chillwind Camp ทางเหนือของ Alterac Mountains" },
        description = { "475:1676709664:39234003", "โปรดฟัง! ขอวีรชนทุกคนตั้งใจรับคำ!\n\nอาณาจักร Stormwind ประกาศเรียกระดมพล ขอผู้แข็งแรงทุกคนจับอาวุธต้านภัยมืดแห่ง Scourge ในตอนเหนือของ Eastern Kingdoms! มีข่าวลือว่าภัยใหม่ผุดจากซาก Plaguelands!\n\nวีรชนแห่งอาณาจักร จงไปหา Commander Ashlam Valorfist ผู้ตั้งฐานที่ Chillwind Camp ทางเหนือของ Alterac Mountains!" },
        completion = { "417:1538964552:1999270426", "ยินดีต้อนรับสู่ Plaguelands วีรชน นี่เป็นหนึ่งในชายแดนอันตรายที่สุดของ Azeroth โดยเฉพาะภัย Scourge ทางเหนือและตะวันออกเฉียงเหนือ ข้ายินดีที่คำเรียกแห่งหน้าที่และประโยชน์ส่วนรวมส่งถึงเจ้า!\n\nหากพร้อมลงมือจริง ที่ชายขอบ Plaguelands มีงานมากมายให้วีรชนผู้พร้อมและสมัครใจทำ" },
    },
    [6761] = { -- The New Frontier
        title = { "16:1969382953:1771254860", "พรมแดนใหม่" },
        objective = { "70:256144317:120026323", "ไปคุยกับ Mathrengyl Bearwalker ที่ Cenarion Enclave ใน Darnassus" },
        description = { "473:328587263:1937269095", "ข้ามอบให้ Mathrengyl Bearwalker รองของข้าจัดการคำขอ Moonglade แล้ว คุยเรื่องนี้กับเขา ไม่ใช่ข้า\n\nขอแนะนำอย่าง... เป็นมิตร... ข้าเองที่พาเผ่าพันธุ์พ้นความมืดเมื่อสูญทุกอย่าง ไม่ใช่ Cenarion Circle ใน Moonglade Teldrassil ให้ชีวิตใหม่แก่เรา! พวกนั้นอยากให้เชื่ออย่างอื่น แต่เชื่อคำโฆษณานั้นก็เป็นคนโง่\n\nให้เจ้าตัดสินเองว่าเป็นคนโง่หรือไม่" },
        completion = { "4:1517439313:201828457 C 435:1860765981:908252509", "ใช่ {class} ขอบใจที่มา ขออภัยเรื่องเข้าใจผิด... ความไม่ไว้ใจระหว่างอัครดรูอิดที่นี่กับ Keeper Remulos ใน Moonglade หนาแน่น ทั้งคู่สงสัยเล่ห์เหลี่ยมของอีกฝ่าย และความแปดเปื้อนประหลาดใน Teldrassil ก็ยังไม่ลดลง ยิ่งไม่ช่วยคลายความระแวง\n\nถึงอย่างไร หน้าที่ต่อ Cenarion Circle ยังอยู่... แม้ผู้นำอาจเห็นต่างกัน" },
    },
    [6762] = { -- Rabine Saturna
        title = { "14:567986005:673434895", "ราบีน ซาเทอร์นา" },
        objective = { "164:1485202294:963899916", "ไปคุยกับ Rabine Saturna ในหมู่บ้าน Nighthaven ที่ Moonglade ซึ่งอยู่ระหว่าง Felwood กับ Winterspring เข้าถึงได้ผ่านทางออกจาก Timbermaw Hold" },
        description = { "441:1312517259:975166287", "งานนี้ Rabine Saturna ผู้ดูแลของ Keeper Remulos ใน Moonglade ขอความช่วยเหลือสำรวจแดนรกร้างกว้างไกลทางตะวันตกของ Tanaris... และเลย Un'Goro ไปอีก เจ้าควรพบเขาใน Nighthaven หมู่บ้านหลักของ Moonglade\n\nแม้งานจะเป็นประโยชน์มากต่อทุกคน ก็ขอให้เดินอย่างระมัดระวัง Darnassus กับ Moonglade มีความตึงเครียด... ที่อาจเพิ่มตามเวลา" },
        completion = { "450:2050336333:227207256 N 1:46:46", "ข้าคือ Rabine Saturna ขอต้อนรับในนาม Keeper Remulos และผู้อาศัยทุกชีวิตในพงไพรศักดิ์สิทธิ์นี้\n\nซาบซึ้งที่สนใจและกระตือรือร้นช่วย Cenarion Circle รู้ด้วยว่าอัครดรูอิดแห่ง Darnassus แสดงความไม่พอใจที่เจ้ามาช่วยเรา วางใจเถิด นี่เพื่อประโยชน์ส่วนรวม และเจ้าจะปลอดภัยจากผลกระทบอันไร้เหตุผลที่อาจพุ่งมาหา\n\nที่นี่เจ้ามีแต่สหาย {name}" },
    },
    [1011] = { -- Forsaken Diseases
        title = { "17:848879792:665969605", "โรคร้ายของฟอร์เซเคน" },
        objective = { "62:1695641664:1319479910", "นำ Bottle of Disease ไปให้ Kayneth Stillwind ใน Forest Song" },
        description = { "472:360952110:716763641", "Forsaken กองกำลังอันเดดของ Horde ลอบเข้ามาใน Ashenvale ซ่อนอยู่ตามซากเมืองและสุสาน เราเชื่อว่าพวกมันต้องการแพร่โรคทั่วดินแดนไนต์เอลฟ์ ต้องพิสูจน์ให้แน่ชัด!\n\nพวกมันตั้งค่ายทางใต้ใกล้ Dor'Danil Barrow Den คอยสร้างพิษกับโรคแล้วบรรจุขวด จงฝ่าเข้าไปขโมยขวดโรคร้ายกลับมา ข้าจะตรวจว่ามันมีไว้ทำอะไร" },
        progress = { "23:2214545:2026922866 N 34:919300080:628847874", "พบค่ายแล้วหรือ {name}? ได้ขวดโรคร้ายมาหรือยัง?" },
        completion = { "11:1776810664:1873330125 N 92:990696755:513125239", "ดีมาก {name} ทีนี้... เมื่อตรวจสิ่งในขวด เราก็จะรู้เป้าหมายของ Forsaken!" },
        required = { [5440] = { "17:1749657454:1232554863", "ขวดบรรจุเชื้อโรค" } },
        objectiveLabels = {
            item = { ["Bottle of Disease"] = "ขวดบรรจุเชื้อโรค" },
        },
    },
    [1012] = { -- Insane Druids
        title = { "13:438856916:566503286", "ดรูอิดคลุ้มคลั่ง" },
        objective = { "119:716701621:1274945996", "ฆ่า Taneel Darkwood, Uthil Mooncall และ Mavoris Cloudsbreak แล้วกลับไปหา Kayneth Stillwind ใน Forest Song" },
        description = { "441:733067834:85008913", "ขณะต่อสู้กับพิษของ Forsaken ข้าเห็นนิมิต เห็นดรูอิดแห่ง Dor'danil Barrow Den ถูกวางยา... ถูกอันเดดฆ่า! บัดนี้พวกเขาเป็นวิญญาณหลงทาง ถูกแยกจากร่างจนคลุ้มคลั่ง\n\nเพื่อให้วิญญาณดรูอิดได้พบความสงบในสักวัน เจ้าต้องเข้าไปทำลายอดีตผู้นำผู้ยิ่งใหญ่ Taneel Darkwood, Uthil Mooncall และ Mavoris Cloudsbreak ใน Dor'danil Barrow Den\n\nทำแล้วกลับมาหาข้า" },
        progress = { "59:915778722:1754321971 N 33:1169396292:1124554287", "ความทรมานของดรูอิดแห่ง Dor'danil ยังตามหลอกหลอนในฝันข้า {name} เจ้าต้องทำลายผู้นำของพวกเขา!" },
        completion = { "116:130178734:1734793399 N 154:1212009652:413260717", "ข้าสัมผัสได้ว่าความทุกข์ในสุสาน Dor'danil ลดลง จึงรู้ว่าเจ้าทำสำเร็จ\n\nเป็นงานเศร้าหมอง {name} วิญญาณที่เจ้าทำลายเป็นเพียงเหยื่อความชั่วของ Forsaken แต่หวังว่าการสิ้นไปของพวกเขาจะให้วิญญาณคลุ้มคลั่งอื่นพบความสงบ" },
        objectiveLabels = {
            monster = { ["Taneel Darkwood slain"] = "ปราบ Taneel Darkwood", ["Uthil Mooncall slain"] = "ปราบ Uthil Mooncall", ["Mavoris Cloudsbreak slain"] = "ปราบ Mavoris Cloudsbreak" },
        },
    },
    [1021] = { -- Vile Satyr! Dryads in Danger!
        title = { "29:2089838295:1496315037", "ซาเทียร์ชั่วร้าย! ดรายแอดตกอยู่ในอันตราย!" },
        objective = { "22:256791880:1693754652", "ตามหา Anilia ใน Xavian" },
        description = { "185:776056213:553312317 N 187:775601507:1385810615", "ฟังนะ ข้าไม่รู้ว่าเจ้าเป็นใคร แต่ต้องการความช่วยเหลือ พี่น้องของข้าไปเอา Branch of Cenarius คืนจากซาเทียร์ บอกว่าจะกลับเร็ว ๆ แต่ผ่านมาสองวันเต็มแล้ว!\n\n{name} เจ้าต้องหาพวกนาง! พวกนางตามหาซากวิหารไนต์เอลฟ์ใน Xavian ทางตะวันออกเฉียงเหนือ ข้าไม่รู้จะคิดอย่างไร ตามหา Anilia นางนำพวกพี่น้องออกค้นหา" },
        completion = { "73:592304272:1947231348", "จากแผลเหวอะที่สีข้าง เห็นได้ว่า Anilia ใกล้สิ้นใจแล้ว" },
    },
    [1022] = { -- The Howling Vale
        title = { "16:634149803:1681251221", "หุบเขาเสียงหอน" },
        objective = { "118:548727395:707868383", "ไป Howling Vale อ่าน Tome of Mel'Thandris แล้วกลับไปหา Sentinel Melyria Frostshadow ที่ Forest Song", variants = { { "128:931165057:988567984", "ไป Howling Vale อ่าน Tome of Mel'Thandris แล้วกลับไปหา Sentinel Melyria Frostshadow ที่ Shrine of Aessina" } } },
        description = { "499:1851207653:2116752505", "เราทุ่มทรัพยากรและความพยายามขับปีศาจที่เหลือจาก Felwood ทางเหนือ แต่สำเร็จเพียงเล็กน้อย อย่างน้อยก็กันปีศาจส่วนใหญ่ไม่ให้เข้า Ashenvale ได้\n\nทางเหนือใกล้เขต Felwood ศาล Mel'Thandris ที่พังทลายถูกมนุษย์หมาป่าลึกลับยึด เสียงหอนชวนขนลุกทำให้แถบนั้นได้ชื่อ Howling Vale ตำรา Tome of Mel'Thandris ที่ศาลอาจเผยเหตุผลที่พวกมันมา" },
        progress = { "269:1670730225:490767960", "ตำราของศาลลึกลับนัก มันต่างจากหนังสือทั่วไป แผ่นหน้าตำราได้รับพรจาก Mel'Thandris เอง และบันทึกเหตุการณ์สำคัญไว้\n\nข้าอธิบายยาก หากไปศาล เจ้าจะเข้าใจ" },
        completion = { "259:742188873:504454816", "Tome of Mel'Thandris ทำงานแปลกประหลาด ทั้งเหตุการณ์ที่บันทึกและสิ่งที่แสดง... ไม่มีใครรู้แน่ว่าทำไมจึงเป็นเช่นนั้น\n\nแต่สิ่งที่ Priestess Starsong ได้รับ ซึ่งคือ Scythe of Elune ต้องสืบต่ออย่างแน่นอน" },
        steps = { { "29:1517003802:108510227", "ตรวจดูคัมภีร์แห่ง Mel'Thandris" } },
    },
    [1037] = { -- Velinde Starsong
        title = { "16:911622741:1619345373", "เวอลินด์ สตาร์ซอง" },
        objective = { "70:148963186:1648813966", "ไปคุยกับ Thyn'tel Bladeweaver ที่ Warrior's Terrace ใน Darnassus" },
        description = { "494:1564292703:1970305666", "Velinde Starsong เป็นผู้ทำหน้าที่ก่อนข้าใน Ashenvale Forest แรกทีเดียวดูเหมือนนางควบคุมสถานการณ์ Felwood ได้ แต่ความพยายามค่อย ๆ สะดุด แล้ววันหนึ่งก็หายตัวไป\n\nข้าถูกส่งมาสานต่องาน ทว่าแทบไม่รู้เรื่องนักบวชหญิงผู้นี้เลย บางที Thyn'tel Bladeweaver ผู้บัญชาการ Sentinel คนหนึ่งอาจรู้รายละเอียดการหายตัวที่ข้าไม่ทราบ\n\nนางย่อมเข้าใจความสำคัญของข้อมูลเช่นนี้" },
        completion = { "234:109456609:91487889", "Velinde Starsong หรือ? ทุกคนคงรู้ว่านักบวชหญิงหายตัวไปพักหนึ่งแล้ว ส่วนรายละเอียดรอบการจากไป... ข้าต้องมีเหตุผลที่ดีพอจึงจะเปิดเผย" },
    },
    [1038] = { -- Velinde's Effects
        title = { "17:1214847701:540334602", "ข้าวของของเวอลินด์" },
        objective = { "119:1748802744:1233987639", "ค้นสมุดบันทึกในหีบของ Velinde แล้วนำกลับไปให้ Thyn'tel Bladeweaver ใน Darnassus พร้อมกุญแจ" },
        description = { "499:2074108181:737663931", "Tome of Mel'Thandris แสดงเรื่องนี้ให้เจ้าดูหรือ? ให้เจ้าตรวจข้าวของนางคงไม่เสียหาย กุญแจนี้เปิดหีบที่เก็บของไว้ในเรือนพัก Sentinel ได้ นางจดหน้าที่ไว้ในสมุด หากจะรู้อะไรก็คงจากมัน\n\nควรบอกไว้ว่า Sentinel เชื่อว่านางมีเหตุผลส่วนตัวที่จากไป และคาดว่าอาจกลับเมื่อใดก็ได้ สิ่งที่นางทำในอดีตทำให้พวกเราไว้วางใจ" },
        progress = { "20:633089029:1788096523", "พบอะไรบ้าง?" },
        completion = { "210:1527058543:1469385208 N 89:1608550803:443357377", "ดูเหมือนการหายตัวของ Velinde น่าวิตกกว่าที่คิด ถึงอย่างนั้นข้าก็ไม่เชื่อว่านางพบจุดจบเลวร้าย บางทีเราควรติดต่อหานาง\n\n{name} ในเมื่อเจ้าสนใจเรื่องนี้จริง ข้าอยากขอความช่วยเหลือ" },
        required = { [5520] = { "17:1352997632:141195540", "สมุดบันทึกของ Velinde" }, [5521] = { "13:467845167:685411172", "กุญแจของ Velinde" } },
        steps = { { "17:1352997632:141195540", "สมุดบันทึกของ Velinde" }, { "13:467845167:685411172", "กุญแจของ Velinde" } },
    },
    [1039] = { -- The Barrens Port
        title = { "16:1439956427:24223901", "ท่าเรือแห่งแบร์เรนส์" },
        objective = { "43:1434611322:1696775005", "ไปคุยกับ Wharfmaster Dizzywig ใน Ratchet" },
        description = { "405:1750337345:290260460 N 78:1238830054:1451315628", "Ratchet เป็นท่าเรือแห่งเดียวใน Barrens Velinde คงหาเรือพาณิชย์ที่นั่นเพื่อไป Blackwater Cove ใน Azeroth เราติดต่อกอบลินผู้ดูแลท่าเรือไม่มากนัก แต่หัวหน้าท่าน่าจะมีข้อมูลผู้โดยสารเข้าออก\n\nตามถนนตะวันออกเฉียงใต้ผ่าน Ashenvale จะถึง Barrens ระวังฝีเท้า {name} นักรบ Horde ลาดตระเวนอยู่ แต่เจ้าจะปลอดภัยในท่าเรือ" },
        completion = { "R 224:175021931:728946708", "ชาว{race} หรือ? ต้องยอมรับว่าไม่ค่อยเจอพวกเจ้าแถวนี้ กำลังหาใครอยู่สินะ? รอครู่ ข้าคงจดในบัญชีสักเล่ม\n\nคนผ่านที่นี่เยอะ ขอเวลาหน่อย" },
    },
    [1040] = { -- Passage to Booty Bay
        title = { "20:852064909:459583287", "โดยสารสู่บูตตีเบย์" },
        objective = { "59:569857244:1616962967", "ขึ้นเรือไป Booty Bay แล้วคุยกับ Caravaneer Ruzzgot" },
        description = { "499:157947025:866027447", "อา พบเสียที น่าจะบอกว่านางผ่านมานานขนาดนั้นแล้ว ไหนดู\n\nVelinde จองเรือ Black Osprey ไป Booty Bay ไม่มีบันทึกอื่น ก็คงถึงอย่างปลอดภัย\n\nช่วยต่อได้ไม่มาก แต่นางถามเรื่องเดินทางทางบกฝั่งนั้น ข้าบอกชื่อ Ruzzgot คนขับคาราวานที่ Booty Bay บางทีนางอาจไปกับเขา\n\nไปได้แล้ว ข้าไม่มีเวลาทั้งวัน" },
        completion = { "238:157391922:1883589311", "มีอะไร? ดูเจ้าไม่เหมือนคนมีสินค้าต้องขน ถ้าไม่มาหางานกับคาราวาน ซึ่งตอนนี้ไม่มีงานให้ ก็คงคุยผิดกอบลิน\n\nตกลงเป็นอย่างไหน?" },
    },
    [1041] = { -- The Caravan Road
        title = { "16:193441825:516375565", "เส้นทางคาราวาน" },
        objective = { "37:1418123761:1160592391", "ไปคุยกับ Clerk Daltry ใน Darkshire" },
        description = { "494:1063670943:1943921333", "ดูเหมือนข้าจะมองเจ้าผิด ซึ่งไม่ได้เกิดทุกวัน\n\nบังเอิญจำ Velinde ที่ตามหาได้ ไม่บ่อยหรอกที่นักบวชหญิงไนต์เอลฟ์อยากโดยสารคาราวานเก่าโทรม แต่ขนสินค้าได้ยอดเยี่ยมอย่างข้า!\n\nเราแยกกันระหว่างขึ้นเหนือ นางไป Darkshire เจ้าหน้าที่ทะเบียนที่นั่นเก็บบันทึกทุกอย่าง อาจรู้อะไรมีประโยชน์\n\nระวังในป่าดงดิบ แม้ยามปกติก็อันตรายถึงชีวิต" },
        completion = { "261:1520989928:2041182189", "หลายปีนี้มีเรื่องประหลาดมาก ข้าจึงบันทึกคนแปลกหน้าให้ดีที่สุด ไม่รู้เมื่อใดจะมีประโยชน์... แม้มักเป็นเรื่องไม่น่ายินดีเมื่อจำเป็นต้องใช้ ข้าไม่ได้หมายความอะไรถึง Velinde ที่เจ้าตามหาหรอก" },
    },
    [1042] = { -- The Carevin Family
        title = { "18:275156385:1897624537", "ตระกูลแคร์วิน" },
        objective = { "41:1981573080:2046748208", "ไปคุยกับ Jonathan Carevin ใน Darkshire" },
        description = { "485:784997763:399962329", "ไม่มีบันทึกว่า Velinde Starsong พักใน Darkshire... แต่ขอพูดหน่อย ข้านึกภาพนักบวชหญิงไนต์เอลฟ์เช่าห้องโรงเตี๊ยมไม่ค่อยออก ถ้าเข้าใจว่าข้าหมายถึงอะไรนะ\n\nส่วนมนุษย์หมาป่าที่บอก ข้าเคยได้ยิน วันก่อน Calor เข้าเมืองพร้อมหัวของมันเป็นพวง เขาทำงานกับตระกูล Carevin นักล่าปีศาจ อันเดด และอสูรอื่น ไปคุยกับ Jonathan หัวหน้าครอบครัว" },
        completion = { "268:413416389:2082660991", "นี่คือยุคมืด ข่าวร้ายกระซิบจากทุกกิ่งที่ไหว ความชั่วซ่อนใต้หินทุกก้อน\n\nแล้วในยามเช่นนี้ คนแปลกหน้าที่ไม่รู้จักก็มาถึงบ้านถามเรื่องวอร์เกน... ข้าจะไม่ขออภัยที่สงสัย ข้าต้องการคำตอบ\n\nและข้าจะได้คำตอบ" },
    },
    [1043] = { -- The Scythe of Elune
        title = { "19:137039014:1699412441", "เคียวแห่งอีลูน" },
        objective = { "83:1545019699:538677270", "หาร่องรอย Scythe of Elune แล้วกลับไปหา Jonathan Carevin ใน Darkshire" },
        description = { "505:1046220874:1162018740", "เรื่องของเจ้าฟังดูจริง... ข้าไม่เข้าใจเจตนาทั้งหมด แต่ถ้าธุระใน Duskwood ช่วยกำจัดวอร์เกนได้สักจำนวน ก็ยอมเอาผลลัพธ์มาก่อนความเข้าใจ\n\nมีเหมืองทางใต้ถูกวอร์เกนยึด พวกมันปรากฏอย่างไร้ที่มา แต่เท่าที่รู้ ที่นั่นคือจุดแรกที่พบ\n\nไปทำธุระเถิด แต่หากพบสิ่งสำคัญช่วยบอกด้วย เรารับความช่วยเหลือทุกอย่างในการรบกับความชั่ว" },
        progress = { "164:1205238234:53621762", "ป่าอันตรายกับผู้ไม่เตรียมพร้อม เก็บอาวุธใกล้มือและตั้งสติให้ใกล้กว่านั้น มิฉะนั้นครั้งหน้าในป่าหลอนอาจเป็นการเดินทางสุดท้าย" },
        completion = { "37:931076370:929282110 N 272:1914433310:653804067", "เรื่องที่เล่าน่าสนใจ {name} แม้อำนาจตระกูล Carevin ไม่มากพอหารากเหง้าและยุติปัญหาตลอดไป แต่จะทำเท่าที่ได้เพื่อควบคุมจำนวนวอร์เกนใน Duskwood\n\nข้าสั่ง Calor ให้ถือเรื่องนี้สำคัญที่สุดแล้ว" },
        steps = { { "36:689058399:1578650419", "ค้นหาหลักฐานเกี่ยวกับเคียวแห่ง Elune" } },
    },
    [1044] = { -- Answered Questions
        title = { "18:108791619:866213258", "คำถามที่ได้รับคำตอบ" },
        objective = { "44:1632413024:1877520224", "กลับไปหา Thyn'tel Bladeweaver ใน Darnassus" },
        description = { "215:519918331:1002027075 N 161:791746007:1645418962", "ไม่ต้องห่วง เราจะคุมปัญหาวอร์เกน ความชั่วที่เพื่อนเจ้านำเข้าป่าจะถูกยับยั้ง ข้าไม่โกรธนาง เรื่องประหลาดเกิดขึ้นมากในยุคนี้ {name} และความมืดไม่เคยพัก\n\nข้าไม่รั้งเจ้าแล้ว คงมีคนอื่นควรได้รู้สิ่งที่เจ้าพบในเหมือง Duskwood" },
        completion = { "410:805580488:1226942346", "นี่คือชะตาของ Velinde สินะ? มหานักบวชหญิงคงผิดหวังเมื่อได้ข่าว พวกนางเป็นเพื่อนสนิทก่อนหายตัว ถึงอย่างนั้น Scythe of Elune ย่อมเป็นพรที่เทพธิดาประทานให้ น่ากังวลที่มันหลุดจากมือผู้รับใช้\n\nแต่เรื่องนั้นไว้คราวอื่น ข้าเป็นหนี้คำขอบคุณไม่น้อยสำหรับสิ่งที่เจ้าทำ" },
    },
    [4581] = { -- Kayneth Stillwind
        title = { "17:411786809:1122412073", "เคย์เนธ สติลวินด์" },
        objective = { "58:861071486:1802028090", "นำ Shindrell's Note ไปให้ Kayneth Stillwind ใน Forest Song" },
        description = { "336:490865356:1604795917", "ดรูอิด Kayneth Stillwind ส่งข่าวมาขอรายงานชายฝั่งและป่ารอบ Astranaar เขาเกรงว่าความแปดเปื้อนกำลังลามผ่าน Ashenvale... และอาจคิดถูก\n\nนี่ นำรายงานไปให้เขา จะพบที่ศาล Forest Song ใน Nightsong Woods ทางตะวันออก" },
        progress = { "29:1641490094:1833668358", "มีอะไรมาให้ข้าหรือ?" },
        completion = { "37:204175863:984739032 N 126:2134401600:1834529981", "อา รายงานของ Shindrell! ขอบใจมาก {name} นางเป็น Sentinel ที่ดี กล้าหาญและหลักแหลม ข้าต้องอ่านหาเบาะแสความชั่วที่เกรงว่ากำลังลามทั่ว Ashenvale" },
        required = { [12060] = { "16:733289293:1854753276", "บันทึกของ Shindrell" } },
        steps = { { "16:733289293:1854753276", "บันทึกของ Shindrell" } },
    },
    [1000] = { -- The New Frontier
        title = { "16:1969382953:1771254860", "พรมแดนใหม่" },
        objective = { "144:808196288:106599670", "คุยกับ Arch Druid Hamuul Runetotem บน Elder Rise ใน Thunder Bluff เรื่องคำเชิญของ Cenarion Circle ให้ออกสำรวจชายแดน Kalimdor" },
        description = { "475:1865427547:1634326920", "เหล่าวีรบุรุษจงฟัง!\n\nCenarion Circle ต้องการผู้แข็งแรงมาช่วยสำรวจชายแดนใหม่อันกว้างใหญ่ของ Kalimdor! ไกลออกไปทางตะวันตกของ Tanaris และ Gadgetzan มีดินแดนรกร้างต้องห้ามที่อันตรายเกินจินตนาการ สมาคมต้องการตัวแทนผู้ยินดีและมีเกียรติไปทำหน้าที่แทน\n\nผู้สนใจจงไปพบ Cenarion Circle คุยกับ Arch Druid Hamuul Runetotem บน Elder's Rise ใน Thunder Bluff เพื่อรับข้อมูลเพิ่มเติม!" },
        completion = { "11:927657569:725753248 C 435:158146379:727126176", "สวัสดี {class}\n\nข้าดีใจที่คนอย่างเจ้าสนใจความเป็นอยู่ของธรรมชาติ เรื่องวีรกรรมยิ่งใหญ่ของเจ้ามาถึงก่อนแล้ว และที่นี่ยินดีต้อนรับ การเห็นเจ้าอยู่ตรงหน้าทำให้มั่นใจว่า Cenarion Circle จะได้ความช่วยเหลือที่เหมาะสม\n\nสายสัมพันธ์ของเรากับ Cenarion Circle ใน Moonglade อยู่เหนือเส้นแบ่งเผ่าพันธุ์และการเมือง จำไว้เมื่อทำงานให้สมาคม แล้วเจ้าจะทำได้ดี" },
    },
    [1004] = { -- The New Frontier
        title = { "16:1969382953:1771254860", "พรมแดนใหม่" },
        objective = { "144:808196288:106599670", "คุยกับ Arch Druid Hamuul Runetotem บน Elder Rise ใน Thunder Bluff เรื่องคำเชิญของ Cenarion Circle ให้ออกสำรวจชายแดน Kalimdor" },
        description = { "475:1865427547:1634326920", "เหล่าวีรบุรุษจงฟัง!\n\nCenarion Circle ต้องการผู้แข็งแรงมาช่วยสำรวจชายแดนใหม่อันกว้างใหญ่ของ Kalimdor! ไกลออกไปทางตะวันตกของ Tanaris และ Gadgetzan มีดินแดนรกร้างต้องห้ามที่อันตรายเกินจินตนาการ สมาคมต้องการตัวแทนผู้ยินดีและมีเกียรติไปทำหน้าที่แทน\n\nผู้สนใจจงไปพบ Cenarion Circle คุยกับ Arch Druid Hamuul Runetotem บน Elder's Rise ใน Thunder Bluff เพื่อรับข้อมูลเพิ่มเติม!" },
        completion = { "11:927657569:725753248 C 435:158146379:727126176", "สวัสดี {class}\n\nข้าดีใจที่คนอย่างเจ้าสนใจความเป็นอยู่ของธรรมชาติ เรื่องวีรกรรมยิ่งใหญ่ของเจ้ามาถึงก่อนแล้ว และที่นี่ยินดีต้อนรับ การเห็นเจ้าอยู่ตรงหน้าทำให้มั่นใจว่า Cenarion Circle จะได้ความช่วยเหลือที่เหมาะสม\n\nสายสัมพันธ์ของเรากับ Cenarion Circle ใน Moonglade อยู่เหนือเส้นแบ่งเผ่าพันธุ์และการเมือง จำไว้เมื่อทำงานให้สมาคม แล้วเจ้าจะทำได้ดี" },
    },
    [1015] = { -- The New Frontier
        title = { "16:1969382953:1771254860", "พรมแดนใหม่" },
        objective = { "146:1770419865:2011158472", "ไปคุยกับ Arch Druid Fandral Staghelm ใน Cenarion Enclave ของ Darnassus เรื่องคำเชิญของ Cenarion Circle ให้สำรวจพรมแดน Kalimdor" },
        description = { "453:829915230:349507449", "วีรชน โปรดฟัง!\n\nCenarion Circle ต้องการคนแข็งแรงมาช่วยสำรวจพรมแดนใหม่อันกว้างใหญ่ของ Kalimdor! ดินแดนรกร้างต้องห้ามที่เต็มไปด้วยอันตรายเกินจินตนาการอยู่ไกลไปทางตะวันตกของ Tanaris และ Gadgetzan ทางสภาต้องการผู้แทนที่สมัครใจและมีเกียรติไปทำหน้าที่\n\nผู้สนใจโปรดเข้าพบ Cenarion Circle คุยกับอัครดรูอิด Fandral Staghelm ใน Darnassus เพื่อทราบรายละเอียด!" },
        completion = { "64:1143222221:2095580571 C 349:1478702586:12269107", "อะไรทำให้คิดว่าข้าอยากถูกรบกวนโดยคนอย่างเจ้า {class}? เดี๋ยวนะ ข้าจะหยุดหน้าที่สำคัญประจำวันเพื่อช่วยเจ้าหาของกระจุกกระจิกสักแห่ง แน่นอน ความเป็นอยู่ของ Darnassus ไม่สิ ของ Teldrassil ทั้งหมด ควรสำคัญรองจากของสะสมชิ้นใหม่ของเจ้า\n\nเจ้าพวกโง่ใน Moonglade ส่งคำขอให้เสียเวลา แล้วยังต้องมาทนเรื่องนี้อีกหรือ?" },
    },
    [1018] = { -- The New Frontier
        title = { "16:1969382953:1771254860", "พรมแดนใหม่" },
        objective = { "144:808196288:106599670", "คุยกับ Arch Druid Hamuul Runetotem บน Elder Rise ใน Thunder Bluff เรื่องคำเชิญของ Cenarion Circle ให้ออกสำรวจชายแดน Kalimdor" },
        description = { "475:1865427547:1634326920", "เหล่าวีรบุรุษจงฟัง!\n\nCenarion Circle ต้องการผู้แข็งแรงมาช่วยสำรวจชายแดนใหม่อันกว้างใหญ่ของ Kalimdor! ไกลออกไปทางตะวันตกของ Tanaris และ Gadgetzan มีดินแดนรกร้างต้องห้ามที่อันตรายเกินจินตนาการ สมาคมต้องการตัวแทนผู้ยินดีและมีเกียรติไปทำหน้าที่แทน\n\nผู้สนใจจงไปพบ Cenarion Circle คุยกับ Arch Druid Hamuul Runetotem บน Elder's Rise ใน Thunder Bluff เพื่อรับข้อมูลเพิ่มเติม!" },
        completion = { "11:927657569:725753248 C 435:158146379:727126176", "สวัสดี {class}\n\nข้าดีใจที่คนอย่างเจ้าสนใจความเป็นอยู่ของธรรมชาติ เรื่องวีรกรรมยิ่งใหญ่ของเจ้ามาถึงก่อนแล้ว และที่นี่ยินดีต้อนรับ การเห็นเจ้าอยู่ตรงหน้าทำให้มั่นใจว่า Cenarion Circle จะได้ความช่วยเหลือที่เหมาะสม\n\nสายสัมพันธ์ของเรากับ Cenarion Circle ใน Moonglade อยู่เหนือเส้นแบ่งเผ่าพันธุ์และการเมือง จำไว้เมื่อทำงานให้สมาคม แล้วเจ้าจะทำได้ดี" },
    },
    [1019] = { -- The New Frontier
        title = { "16:1969382953:1771254860", "พรมแดนใหม่" },
        objective = { "146:1770419865:2011158472", "ไปคุยกับ Arch Druid Fandral Staghelm ใน Cenarion Enclave ของ Darnassus เรื่องคำเชิญของ Cenarion Circle ให้สำรวจพรมแดน Kalimdor" },
        description = { "453:829915230:349507449", "วีรชน โปรดฟัง!\n\nCenarion Circle ต้องการคนแข็งแรงมาช่วยสำรวจพรมแดนใหม่อันกว้างใหญ่ของ Kalimdor! ดินแดนรกร้างต้องห้ามที่เต็มไปด้วยอันตรายเกินจินตนาการอยู่ไกลไปทางตะวันตกของ Tanaris และ Gadgetzan ทางสภาต้องการผู้แทนที่สมัครใจและมีเกียรติไปทำหน้าที่\n\nผู้สนใจโปรดเข้าพบ Cenarion Circle คุยกับอัครดรูอิด Fandral Staghelm ใน Darnassus เพื่อทราบรายละเอียด!" },
        completion = { "64:1143222221:2095580571 C 349:1478702586:12269107", "อะไรทำให้คิดว่าข้าอยากถูกรบกวนโดยคนอย่างเจ้า {class}? เดี๋ยวนะ ข้าจะหยุดหน้าที่สำคัญประจำวันเพื่อช่วยเจ้าหาของกระจุกกระจิกสักแห่ง แน่นอน ความเป็นอยู่ของ Darnassus ไม่สิ ของ Teldrassil ทั้งหมด ควรสำคัญรองจากของสะสมชิ้นใหม่ของเจ้า\n\nเจ้าพวกโง่ใน Moonglade ส่งคำขอให้เสียเวลา แล้วยังต้องมาทนเรื่องนี้อีกหรือ?" },
    },
    [1123] = { -- Rabine Saturna
        title = { "14:567986005:673434895", "ราบีน ซาเทอร์นา" },
        objective = { "164:1485202294:963899916", "ไปคุยกับ Rabine Saturna ในหมู่บ้าน Nighthaven ที่ Moonglade ซึ่งอยู่ระหว่าง Felwood กับ Winterspring เข้าถึงได้ผ่านทางออกจาก Timbermaw Hold" },
        description = { "482:497328362:60825756 N 12:511881424:1378130220", "งานนี้ Rabine Saturna ผู้ดูแลใหญ่ของ Keeper Remulos ใน Moonglade ต้องการคนช่วยสำรวจดินแดนรกร้างกว้างใหญ่ไกลทางตะวันตกของ Tanaris และ Un'Goro เขาอยู่ที่ Nighthaven หมู่บ้านหลักของ Moonglade\n\nข้าอยากให้เจ้ารู้ว่าการไปมีความสำคัญ ความตึงเครียดระหว่างไนต์เอลฟ์ Darnassus กับ Cenarion Circle ใน Moonglade กำลังเพิ่มขึ้น จงมองข้ามเส้นแบ่งเผ่าและใช้ปัญญาบรรพชนเมื่อติดต่อสมาคม {name} โชคดี" },
        completion = { "425:1055283761:176050143 N 1:46:46", "ข้าคือ Rabine Saturna ในนาม Keeper Remulos และผู้พำนักทุกคนในดงศักดิ์สิทธิ์นี้ ขอต้อนรับเจ้า\n\nข้าซาบซึ้งที่สนใจและกระตือรือร้นช่วย Cenarion Circle ทอเรนแสดงความใกล้ชิดกับหลักคำสอน Cenarius อย่างยิ่ง และผ่านพวกเขา Horde ก็ได้รับการต้อนรับในความปลอดภัยของดงนี้ การปกปัก Azeroth คือเป้าหมายร่วมของเรา\n\nที่นี่เจ้ามีมิตร {name}" },
    },
    [3761] = { -- Un'Goro Soil
        title = { "12:1017872992:588641980", "ดินจากอันโกโร" },
        objective = { "74:1266644882:983439256", "นำ Un'Goro Soil 20 ตัวอย่าง ไปให้ Ghede บน Elder Rise ใน Thunder Bluff" },
        description = { "496:1736303935:1627431766", "มีรายงานว่าดินใน Un'Goro Crater เปี่ยมคุณสมบัติเวทมนตร์ Cenarion Circle อยากศึกษาปริมาณมาก จงเข้าสู่ป่า Un'Goro แล้วเก็บให้พอสำหรับวิจัยต่อ\n\nบางครั้งดินอุดมจะกองโผล่ขึ้นมา และสัตว์บางตัวอาจมีตัวอย่างใช้ได้ติดตัว นำทั้งหมดไปให้ Ghede ด้านนอก มองหากองดินกับทอเรนที่ตะโกนสั่ง เขาหวังดี แค่อย่าทำให้โมโหก็พอ!" },
        progress = { "102:925144143:648448263", "ตามสบาย พลทหาร ถ้ามาขนดินจาก Un'Goro ลง ก็ยอดเยี่ยม! ถ้าไม่ใช่ ก็หายไปเสีย" },
        completion = { "24:1843800860:650913277 N 378:2105915594:2134285256", "อ้อ ใช่ พลทหาร {name} ไม่ต้องพยายามช่วยขนดินขึ้นกองเลยนะ! ถ้ามหาวิญญาณต้องการให้มันขึ้นไป ก็คงเนรมิตให้เองแล้วใช่ไหม?!\n\nArch Druid Runetotem อยากคุยอีกครั้ง แต่งานต่อไปจะง่ายขึ้นหากเข้าใจ Herbalism ระดับ Journeyman ถึงไม่รู้ เขาก็ยังหางานให้เจ้าทำได้" },
        required = { [11018] = { "12:1017872992:588641980", "ดินจาก Un'Goro" } },
        objectiveLabels = {
            item = { ["Un'Goro Soil"] = "ดินจาก Un'Goro" },
        },
    },
    [3782] = { -- Morrowgrain Research
        title = { "20:2056345083:630742892", "วิจัยมอร์โรว์เกรน" },
        objective = { "60:763932484:442372392", "นำ Seed Voucher ไปให้ Bashana Runetotem ที่ Thunder Bluff" },
        description = { "456:1953321723:1495329192", "ด้วยสิ่งที่เรียกว่า Evergreen Pouch เราเพาะเมล็ด Tharlendris ในดินจาก Un'Goro Crater เมล็ดเหล่านี้งอกเป็นสมุนไพรทรงพลังหลายชนิดแบบสุ่ม ผลอย่างหนึ่งคือ morrowgrain สมุนไพรลึกลับที่เรารู้น้อย ข้าหวังไขปริศนานี้ให้สมาคม\n\nนำใบแลกนี้ไปให้ Bashana ลูกสาวข้า นางจะให้เมล็ดเพื่อให้เจ้าช่วยเราได้ หากหมด ต้องซื้อเพิ่มจากนาง" },
        progress = { "82:1742992428:1823584362", "ขอสันติจงมีแก่เจ้า สหาย มาทำธุระจากอัครดรูอิดเองใช่ไหม?" },
        completion = { "140:61891678:1428583054 N 285:1731750739:222386837", "ใช่ ใบแลกนี้ใช้รับเมล็ดได้ยี่สิบห่อ หากใช้หมด ข้ามีขายเพิ่ม\n\nน่าเสียดาย {name} การผลิตเมล็ด Tharlendris จำนวนมากมีต้นทุนสูง Cenarion Circle จึงขอให้ผู้ช่วยร่วมรับภาระบางส่วน ผู้ที่นำ morrowgrain กลับมาจะพบว่ารางวัลจากอัครดรูอิดคุ้มต้นทุนมาก" },
        required = { [11103] = { "12:1807499826:1566206848", "คูปองแลกเมล็ดพันธุ์" } },
        objectiveLabels = {
            item = { ["Seed Voucher"] = "คูปองแลกเมล็ดพันธุ์" },
        },
    },
    [3786] = { -- Morrowgrain Research
        title = { "20:2056345083:630742892", "วิจัยมอร์โรว์เกรน" },
        objective = { "190:893257246:1319126515", "ใช้ Evergreen Pouch พร้อม Packet of Tharlendis Seeds และ Un'Goro Soil สองตัวอย่าง เพื่อลองเพาะ Morrowgrain\n\nนำ Morrowgrain 10 ชิ้น ไปให้ Bashana Runetotem ที่ Thunder Bluff" },
        description = { "438:2097202784:988917162", "นี่ Evergreen Pouch ที่ต้องใช้กับเมล็ด Tharlendis เจ้าต้องมีดิน Un'Goro ติดตัวเป็นปุ๋ยด้วย เมื่อมีครบก็ใช้ถุง มันจะจัดการที่เหลือเอง\n\nเมื่อมี morrowgrain พอ นำมาให้ข้าที่ Elder Rise อย่าไปรบกวนอัครดรูอิด เขายุ่งกับงานวิจัยและเรื่องที่ต้องกังวลอีกมาก!" },
        progress = { "4:1517439313:201828457 N 194:1096366255:165730250", "ว่าอย่างไร {name} ปลูก morrowgrain ให้งานวิจัยสำคัญของอัครดรูอิดได้บ้างหรือยัง? คุณสมบัติลึกลับของ Un'Goro Crater กระจ่างขึ้นทุกวัน เพราะความช่วยเหลือของเจ้า" },
        completion = { "10:963015740:1087923650 N 301:1029498726:1249552666", "ทำได้ดี {name} ข้าจะนำไปให้อัครดรูอิดเองเมื่อท่านต้องใช้ ระหว่างนี้โปรดรับสิ่งนี้แทนความขอบคุณจาก Cenarion Circle\n\nตอนนี้เรายังต้องการ morrowgrain ต่อเนื่อง หากอยากช่วยอีก กลับมาเมื่อเพาะได้เพิ่ม" },
        required = { [11040] = { "11:35561619:35128800", "มอร์โรว์เกรน" } },
        objectiveLabels = {
            item = { ["Morrowgrain"] = "มอร์โรว์เกรน" },
        },
    },
    [3789] = { -- Assisting Arch Druid Staghelm
        title = { "29:1148956102:1438083021", "ช่วยอัครดรูอิดสแต็กเฮล์ม" },
        objective = { "52:397099142:1481761258", "ไปคุยกับ Arch Druid Fandral Staghelm ใน Darnassus" },
        description = { "10:1827992962:185023149 C 423:424570723:1618639736", "ขอรบกวนเวลาสักครู่ได้ไหม {class}\n\nCenarion Circle ใน Darnassus กำลังหานักผจญภัยมากประสบการณ์อย่างเจ้าช่วยงานวิจัยสำคัญ แม้ไม่รู้รายละเอียด แต่บอกได้ว่าอัครดรูอิด Fandral Staghelm เป็นผู้นำงานด้วยตัวเอง\n\nหากสนใจ โปรดคุยกับเขาโดยตรงที่ Cenarion Enclave ภายใน Darnassus" },
        completion = { "10:1638626602:1885586213 C 234:1479284934:925420808", "เอาล่ะ {class}... เมื่อรู้ว่าข้าเป็นผู้นำงานเอง ก็คงรีบมาสุดกำลังสินะ\n\nในเมื่อมาถึงแล้ว ตั้งใจฟังรายละเอียดครั้งแรกให้ดี ข้าไม่อยากพูดซ้ำ" },
    },
    [3790] = { -- Assisting Arch Druid Staghelm
        title = { "29:1148956102:1438083021", "ช่วยอัครดรูอิดสแต็กเฮล์ม" },
        objective = { "52:397099142:1481761258", "ไปคุยกับ Arch Druid Fandral Staghelm ใน Darnassus" },
        description = { "10:1827992962:185023149 C 423:424570723:1618639736", "ขอรบกวนเวลาสักครู่ได้ไหม {class}\n\nCenarion Circle ใน Darnassus กำลังหานักผจญภัยมากประสบการณ์อย่างเจ้าช่วยงานวิจัยสำคัญ แม้ไม่รู้รายละเอียด แต่บอกได้ว่าอัครดรูอิด Fandral Staghelm เป็นผู้นำงานด้วยตัวเอง\n\nหากสนใจ โปรดคุยกับเขาโดยตรงที่ Cenarion Enclave ภายใน Darnassus" },
        completion = { "10:1638626602:1885586213 C 234:1479284934:925420808", "เอาล่ะ {class}... เมื่อรู้ว่าข้าเป็นผู้นำงานเอง ก็คงรีบมาสุดกำลังสินะ\n\nในเมื่อมาถึงแล้ว ตั้งใจฟังรายละเอียดครั้งแรกให้ดี ข้าไม่อยากพูดซ้ำ" },
    },
    [4494] = { -- March of the Silithid
        title = { "21:489507381:1905385308", "การรุกคืบของซิลิธิด" },
        objective = { "43:1838359856:2051515723", "ไปคุยกับ Alchemist Pestlezugg ใน Gadgetzan" },
        description = { "502:828893:1199699322", "ดูเหมือนเจตนา ไม่สิ เหตุแห่งการดำรงอยู่ของซิลิธิด คือกินทุกสิ่งที่ไม่ใช่ระบบนิเวศของมัน พวกมันมุ่งเป้าเดียว จึงเป็นภัยร้ายต่อชีวิตทั้งหมดบน Azeroth\n\nสิ่งที่เห็นเป็นเพียงระยะแรก ข้าสงสัยว่ากำลังมาจากส่วนลึกของ Kalimdor คือ Un'Goro Crater ไป Gadgetzan ในทะเลทราย Tanaris แล้วคุยกับ Alchemist Pestlezugg บอกทฤษฎีข้า เขาจะช่วยเราต่อสู้แน่" },
        completion = { "385:271454609:1233647651", "ใช่ ข้ารู้แล้วว่า Zilzibin ส่งเจ้ามา ประสบการณ์ต่อสู้สัตว์พวกนี้ประเมินค่าไม่ได้ เท่าที่รู้ ยังไม่มีใครจัดการพวกมันมาก่อน ส่วนที่ Zil คิดว่า Un'Goro Crater เป็นศูนย์กลาง... ก็อาจใช่ Un'Goro เป็นป่าลึกลับอันตรายทางตะวันตก บางทีอาจเป็นอีกก้าวที่ทำให้เข้าใจว่าซิลิธิดเป็นอะไรกันแน่" },
    },
    [4508] = { -- Calm Before the Storm
        title = { "21:1334673301:1302430267", "ความสงบก่อนพายุ" },
        objective = { "70:1686303692:1355808987", "นำ Pestlezugg's Un'Goro Report ไปให้ Gracina Spiritmight ที่ Darnassus" },
        description = { "393:1064772628:1050600329 N 47:782960723:831603402", "ผลการค้นพบล่าสุดและความรู้ที่เราได้ในวันนี้ต้องไปถึงมือผู้ที่อาจจัดการเรื่องนี้ได้ แม้พวกเราที่ Gadgetzan จะมีไหวพริบและทรัพยากรเพียงใด เราก็ทำตามลำพังไม่ได้\n\nนำรายงานล่าสุดของข้ากลับไปให้ Gracina Spiritmight ที่ Darnassus นางยังอยู่ที่ Temple of the Moon ใช่ไหม? นางรู้จักพวกคนใหญ่คนโตของ Alliance หากเราดึงพวกเขาเข้ามาร่วมได้ {name} บางทีพวกเราก็อาจรอดชีวิตจากเรื่องนี้" },
        progress = { "16:1789592041:1053291588 N 322:513836674:833670778", "พวกเขาโง่เขลา {name}! ไม่คิดแม้แต่จะมองรอบตัวเพื่อหาภัยที่ยิ่งใหญ่กว่า ความเกลียดชัง Horde อย่างไร้เหตุผลของพวกเขาจะนำจุดจบมาสู่พวกเราทั้งหมด ข้าไม่รู้ว่าจะต้องแสดงหลักฐานภัยซิลิธิดอีกสักเท่าไร นอกจากจับพวกเขาโยนลงรังสักแห่งให้เห็นกับตาตนเอง!\n\nขอโทษด้วย เจ้ามีข่าวมาแจ้งข้าหรือ?" },
        completion = { "439:1812791570:147611691 N 53:1107965988:1149390542", "แม้ข้าจะซาบซึ้งในสิ่งนี้จริง ๆ แต่ก็ไม่แน่ใจว่าจะช่วยอะไรเราได้ Alliance เพิกเฉยต่อภัยคุกคามจากทุกแหล่งที่ไม่ใช่ Horde และแม้แต่ผู้นำของเราที่ Darnassus ก็ยังตกลงกันไม่ได้ว่าภัยนี้คืออะไรกันแน่ คนเขลาอย่าง Fandral Staghelm ตั้งทฤษฎีว่าซิลิธิดไม่ใช่ภัยจากอดีตกาลอย่างที่ข้ากล่าว ความไม่รู้ของเขามีเพียงความเย่อหยิ่งของตัวเองเท่านั้นที่เหนือกว่า\n\nเจ้าเห็นภัยนี้ด้วยตัวเองแล้ว {name} เราต้องมุ่งมั่นกำจัดซิลิธิดต่อไป!" },
        required = { [11844] = { "27:808382586:926934847", "รายงานเรื่อง Un'Goro ของ Pestlezugg" } },
        steps = { { "27:808382586:926934847", "รายงานเรื่อง Un'Goro ของ Pestlezugg" } },
    },
    [4509] = { -- Calm Before the Storm
        title = { "21:1334673301:1302430267", "ความสงบก่อนพายุ" },
        objective = { "68:2026715772:770253330", "นำ Pestlezugg's Un'Goro Report ไปให้ Zilzibin Drumlore ที่ Orgrimmar" },
        description = { "410:1202771959:1913216707 N 47:782960723:831603402", "ผลการค้นพบล่าสุดและความรู้ที่เราได้ในวันนี้ต้องไปถึงมือผู้ที่อาจจัดการเรื่องนี้ได้ แม้พวกเราที่ Gadgetzan จะมีไหวพริบและทรัพยากรเพียงใด เราก็ทำตามลำพังไม่ได้ นำรายงานล่าสุดของข้ากลับไปให้ Zilzibin Drumlore ที่ Orgrimmar เขายังอยู่ที่บ้านทางส่วนบนของ The Drag ใช่ไหม? เขารู้จักคนระดับสูงของ Horde หากเราดึงพวกเขาเข้ามาร่วมได้ {name} บางทีพวกเราก็อาจรอดชีวิตจากเรื่องนี้" },
        progress = { "16:1789592041:1053291588 N 319:1509261811:1408890673", "พวกเขาโง่เขลา {name}! ไม่คิดแม้แต่จะมองรอบตัวเพื่อหาภัยที่ยิ่งใหญ่กว่า ความเกลียดชัง Alliance อย่างไร้เหตุผลของพวกเขาจะนำหายนะมาสู่เรา ข้าไม่รู้ว่าจะต้องแสดงหลักฐานภัยซิลิธิดอีกสักเท่าไร นอกจากจับพวกเขาโยนลงรังสักแห่งให้เห็นกับตาตนเอง! ขอโทษด้วย เจ้ามีข่าวมาแจ้งข้าหรือ?" },
        completion = { "409:1165709033:1074573844 N 53:1107965988:1149390542", "แม้ข้าจะซาบซึ้งในสิ่งนี้จริง ๆ แต่ก็ไม่แน่ใจว่าจะช่วยอะไรเราได้ Horde เพิกเฉยต่อภัยคุกคามจากทุกแหล่งที่ไม่ใช่ Alliance แม้ Thrall อาจลงมือหากได้เห็นข้อเท็จจริง แต่เขาก็ถูกคำแนะนำที่ขัดแย้งกันรุมเร้าจากทุกด้าน คนเขลาเหล่านี้พร้อมจะให้เราไล่จับหางในจินตนาการของตัวเอง หากคิดว่ามันจะทำให้ Alliance ไม่ทันตั้งตัว! เจ้าเห็นภัยนี้ด้วยตัวเองแล้ว {name} เราต้องมุ่งมั่นกำจัดซิลิธิดต่อไป!" },
    },
    [4511] = { -- Calm Before the Storm
        title = { "21:1334673301:1302430267", "ความสงบก่อนพายุ" },
        objective = { "57:1761390118:1044923867", "นำ Bank Voucher ไปให้ Karus ที่ธนาคารใน Orgrimmar" },
        description = { "N 498:482126520:2053313730 C 1:46:46", "{name} หากไม่มีเจ้า เราคงมาไม่ถึงตรงนี้ อีกไม่นานข้าคงขอความช่วยเหลือเรื่องซิลิธิดอีก เราต้องทบทวนสิ่งที่รู้จาก Un'Goro ข้าเกรงว่าข้อสันนิษฐานว่าซิลิธิดกำเนิดที่นั่นคงผิด... ที่จริงคงมีแหล่งกำลังใหญ่กว่ามากอยู่ที่ใดสักแห่ง\n\nนำจดหมายนี้ไปให้ Karus ที่ธนาคาร เขาจะให้ของจากคลังข้า เป็นสิ่งแทนความซาบซึ้ง ขอบใจที่ช่วย {class} ผู้ทรงพลัง" },
        progress = { "41:535115939:327809055 C 1:63:63", "ซุกซุก! วันนี้ให้ช่วยอะไร {class}?" },
        completion = { "158:2109709613:1212348326", "ใบเบิกธนาคารอนุญาตให้ข้าถอนไอเทมจากบัญชี Zilzibin Drumlore มามอบให้เจ้า เห็นทีต้องแสดงความยินดีด้วย!" },
    },
    [4902] = { -- Wildkin of Elune
        title = { "16:1849571705:289869", "ไวลด์คินแห่ง Elune" },
        objective = { "52:397099142:1481761258", "ไปคุยกับ Arch Druid Fandral Staghelm ใน Darnassus" },
        description = { "344:2136957276:747176668 N 1:33:33", "น่าทึ่งมาก! ข้าสงสัยเรื่องความจริงนี้มาตลอด... เจ้าต้องนำความรู้นี้ไปบอกต่อแน่นอน! ไปหา Arch Druid Fandral Staghelm ทันที เขาอยู่ที่ Cenarion Circle ใน Darnassus เล่าเหตุการณ์ให้เขาฟังเหมือนที่เล่าให้ข้า ข้ามั่นใจว่าเขาจะสนใจเช่นกัน! นี่เป็นข้อมูลสำคัญนะ {name}!" },
        completion = { "461:858320291:1186115147", "อย่าลังเล บอกมาว่าเจ้ามาทำไม อ้อ อย่างนั้นหรือ? อืม เอาละ ขอบใจที่นำเรื่องมาบอกข้าโดยตรง การเข้าหาผู้มีอำนาจสูงสุดย่อมดีที่สุดเสมอ... แต่... ใช่ เหล่าดรูอิดแห่ง Cenarion Circle รู้เรื่องไวลด์คินมาพักใหญ่แล้ว ว่าพวกมันเป็นสัตว์ของ Elune และได้รับเลือกให้เฝ้าสถานที่ศักดิ์สิทธิ์ที่สุด ดังนั้น แม้นี่จะไม่ใช่ข่าวใหม่ ข้าก็ขอชมเชยความพยายามของเจ้า รับสิ่งนี้ไป ดูจะเหมาะกับสิ่งที่เจ้าทำ" },
    },
    [5066] = { -- A Call to Arms: The Plaguelands!
        title = { "32:667387596:1841318316", "เรียกระดมพลสู่เพลกแลนด์!" },
        objective = { "112:1220981070:1070122399", "ไปหา Commander Ashlam Valorfist ที่ฐาน Chillwind Camp ทางเหนือของ Alterac Mountains" },
        description = { "475:1676709664:39234003", "โปรดฟัง! ขอวีรชนทุกคนตั้งใจรับคำ!\n\nอาณาจักร Stormwind ประกาศเรียกระดมพล ขอผู้แข็งแรงทุกคนจับอาวุธต้านภัยมืดแห่ง Scourge ในตอนเหนือของ Eastern Kingdoms! มีข่าวลือว่าภัยใหม่ผุดจากซาก Plaguelands!\n\nวีรชนแห่งอาณาจักร จงไปหา Commander Ashlam Valorfist ผู้ตั้งฐานที่ Chillwind Camp ทางเหนือของ Alterac Mountains!" },
        completion = { "413:1233777570:246431073", "ขอต้อนรับสู่ Plaguelands วีรบุรุษ นี่เป็นหนึ่งในแนวชายแดนที่อันตรายที่สุดของ Azeroth โดยเฉพาะภัยจาก Scourge ที่คืบคลานอยู่ทางเหนือและตะวันออกเฉียงเหนือ ข้าดีใจที่เสียงเรียกให้ทำหน้าที่และรับใช้ส่วนรวมไม่ได้สูญเปล่าเมื่อมาถึงเจ้า!\n\nหากพร้อมลงแรง ที่ชายขอบ Plaguelands นี้ก็มีงานมากมายให้วีรบุรุษที่มีใจและความสามารถทำ" },
    },
    [5090] = { -- A Call to Arms: The Plaguelands!
        title = { "32:667387596:1841318316", "เรียกระดมพลสู่เพลกแลนด์!" },
        objective = { "112:1220981070:1070122399", "ไปหา Commander Ashlam Valorfist ที่ฐาน Chillwind Camp ทางเหนือของ Alterac Mountains" },
        description = { "475:1676709664:39234003", "โปรดฟัง! ขอวีรชนทุกคนตั้งใจรับคำ!\n\nอาณาจักร Stormwind ประกาศเรียกระดมพล ขอผู้แข็งแรงทุกคนจับอาวุธต้านภัยมืดแห่ง Scourge ในตอนเหนือของ Eastern Kingdoms! มีข่าวลือว่าภัยใหม่ผุดจากซาก Plaguelands!\n\nวีรชนแห่งอาณาจักร จงไปหา Commander Ashlam Valorfist ผู้ตั้งฐานที่ Chillwind Camp ทางเหนือของ Alterac Mountains!" },
        completion = { "417:1538964552:1999270426", "ยินดีต้อนรับสู่ Plaguelands วีรชน นี่เป็นหนึ่งในชายแดนอันตรายที่สุดของ Azeroth โดยเฉพาะภัย Scourge ทางเหนือและตะวันออกเฉียงเหนือ ข้ายินดีที่คำเรียกแห่งหน้าที่และประโยชน์ส่วนรวมส่งถึงเจ้า!\n\nหากพร้อมลงมือจริง ที่ชายขอบ Plaguelands มีงานมากมายให้วีรชนผู้พร้อมและสมัครใจทำ" },
    },
    [5093] = { -- A Call to Arms: The Plaguelands!
        title = { "32:667387596:1841318316", "เรียกระดมพลสู่เพลกแลนด์!" },
        objective = { "117:1078838967:831033310", "ตามหา High Executor Derrington ค่ายหลักของเขาอยู่ที่ Bulwark ทางตะวันออกของ Tirisfal Glade และ Undercity" },
        description = { "479:1652471950:269807084", "วีรชนทั้งหลาย ฟังข้า Horde เรียกให้เจ้าลงมือโดยเร็ว!\n\nมีคำสั่งระดมพลผู้พร้อมรบทุกคนให้จับอาวุธต่อต้าน Scourge! ข่าวลือกล่าวถึงภัยใหม่ที่ผุดจากซาก Eastern Kingdoms มันคุกคามอยู่ทางตะวันออกของ Undercity ในเขตเหนือของดินแดนที่บัดนี้เรียก Plaguelands!\n\nวีรชนทั้งหลาย จงตามหา High Executor Derrington ผู้ตั้งค่ายหลักที่ Bulwark ทางตะวันออกของ Tirisfal Glade!" },
        completion = { "425:1931029971:1835535959", "ยินดีต้อนรับสู่ Plaguelands วีรชน ที่นี่เป็นหนึ่งในแนวชายแดนอันตรายที่สุดของ Azeroth ภัยจาก Scourge คุกคามทางตะวันออก และไกลไปทางตะวันออกยิ่งกว่านั้น ข้าดีใจที่คำเรียกแห่งหน้าที่และการรับใช้ Horde ไม่สูญเปล่าสำหรับเจ้า!\n\nหากพร้อมลงแรงจริงจัง ก็มีงานมากมายสำหรับวีรชนผู้เต็มใจและสามารถอยู่ที่ขอบ Plaguelands แห่งนี้" },
    },
    [5094] = { -- A Call to Arms: The Plaguelands!
        title = { "32:667387596:1841318316", "เรียกระดมพลสู่เพลกแลนด์!" },
        objective = { "117:1078838967:831033310", "ตามหา High Executor Derrington ค่ายหลักของเขาอยู่ที่ Bulwark ทางตะวันออกของ Tirisfal Glade และ Undercity" },
        description = { "479:1652471950:269807084", "วีรชนทั้งหลาย ฟังข้า Horde เรียกให้เจ้าลงมือโดยเร็ว!\n\nมีคำสั่งระดมพลผู้พร้อมรบทุกคนให้จับอาวุธต่อต้าน Scourge! ข่าวลือกล่าวถึงภัยใหม่ที่ผุดจากซาก Eastern Kingdoms มันคุกคามอยู่ทางตะวันออกของ Undercity ในเขตเหนือของดินแดนที่บัดนี้เรียก Plaguelands!\n\nวีรชนทั้งหลาย จงตามหา High Executor Derrington ผู้ตั้งค่ายหลักที่ Bulwark ทางตะวันออกของ Tirisfal Glade!" },
        completion = { "425:1931029971:1835535959", "ยินดีต้อนรับสู่ Plaguelands วีรชน ที่นี่เป็นหนึ่งในแนวชายแดนอันตรายที่สุดของ Azeroth ภัยจาก Scourge คุกคามทางตะวันออก และไกลไปทางตะวันออกยิ่งกว่านั้น ข้าดีใจที่คำเรียกแห่งหน้าที่และการรับใช้ Horde ไม่สูญเปล่าสำหรับเจ้า!\n\nหากพร้อมลงแรงจริงจัง ก็มีงานมากมายสำหรับวีรชนผู้เต็มใจและสามารถอยู่ที่ขอบ Plaguelands แห่งนี้" },
    },
    [5095] = { -- A Call to Arms: The Plaguelands!
        title = { "32:667387596:1841318316", "เรียกระดมพลสู่เพลกแลนด์!" },
        objective = { "118:713407217:1867103209", "ตามหา High Executor Derrington ค่ายหลักของเขาอยู่ที่ Bulwark ทางตะวันออกของ Tirisfal Glades และ Undercity" },
        description = { "480:1631033798:985000715", "วีรชนทั้งหลาย ฟังข้า Horde เรียกให้เจ้าลงมือโดยเร็ว!\n\nมีคำสั่งระดมพลผู้พร้อมรบทุกคนให้จับอาวุธต่อต้าน Scourge! ข่าวลือกล่าวถึงภัยใหม่ที่ผุดจากซาก Eastern Kingdoms มันคุกคามอยู่ทางตะวันออกของ Undercity ในเขตเหนือของดินแดนที่บัดนี้เรียก Plaguelands!\n\nวีรชนทั้งหลาย จงตามหา High Executor Derrington ผู้ตั้งค่ายหลักที่ Bulwark ทางตะวันออกของ Tirisfal Glades!" },
        completion = { "425:1931029971:1835535959", "ยินดีต้อนรับสู่ Plaguelands วีรชน ที่นี่เป็นหนึ่งในแนวชายแดนอันตรายที่สุดของ Azeroth ภัยจาก Scourge คุกคามทางตะวันออก และไกลไปทางตะวันออกยิ่งกว่านั้น ข้าดีใจที่คำเรียกแห่งหน้าที่และการรับใช้ Horde ไม่สูญเปล่าสำหรับเจ้า!\n\nหากพร้อมลงแรงจริงจัง ก็มีงานมากมายสำหรับวีรชนผู้เต็มใจและสามารถอยู่ที่ขอบ Plaguelands แห่งนี้" },
    },
    [9024] = { -- Aristan's Hunch
        title = { "15:134546128:1769080668", "ลางสังหรณ์ของอาริสตัน" },
        objective = { "96:1279095380:1694995259", "นำ Cologne Bottle 1 ขวดและ Perfume Bottle 1 ขวดไปให้ Morgan Pestle ใน Trade District ของ Stormwind" },
        description = { "417:398867730:1750840336", "ข้ารู้แล้ว! เจ้าได้กลิ่นหอมใหม่ที่ลอยมาตามลมไหม? โคโลญกับน้ำหอมแบบใหม่ที่กำลังเป็นที่นิยมนั่นไง ทหารยามของเราคงไม่ละเลยหน้าที่กันง่าย ๆ\n\nเว้นแต่ว่าความคิดของพวกเขาจะถูกการเล่นแร่แปรธาตุชั่วร้ายทำให้มัวหมอง\n\nมีวิธีเดียวที่จะรู้แน่ นำโคโลญกับน้ำหอมอย่างละขวดไปให้มอร์แกน เพสเซิล และบอกข้อสงสัยของข้ากับเขา เมื่อเจ้ากลับมา ข้าจะคืนเงินค่าซื้อของให้" },
        progress = { "30:23520830:2063270366", "มีอะไรให้ข้าช่วยหรือ?" },
        completion = { "244:162164040:1247967371", "ข้าเข้าใจความกังวลของอาริสตัน แต่คิดจริง ๆ ว่าเขาตื่นตูมเกินไป ปล่อยให้หนุ่มสาวทำตามใจเถอะ ข้าคิดว่าอาริสตันลืมไปแล้วว่าการเป็นหนุ่มและมีความรักเป็นอย่างไร\n\nแต่คงดีกว่าถ้าไม่บอกเขาเช่นนั้น เราจะตามใจเขาแล้วกัน" },
        required = { [21833] = { "14:718714730:1761811256", "ขวดโคโลญ" }, [21829] = { "14:691313061:434016561", "ขวดน้ำหอม" } },
        objectiveLabels = {
            item = { ["Cologne Bottle"] = "ขวดโคโลญ", ["Perfume Bottle"] = "ขวดน้ำหอม" },
        },
    },
    [971] = { -- Knowledge in the Deeps
        title = { "22:782600478:1715380751", "ความรู้ใต้ห้วงลึก" },
        objective = { "84:246361768:181183719", "นำ Lorgalis Manuscript ไปให้ Gerrig Bonegrip ที่ Forlorn Cavern ใน Ironforge" },
        description = { "470:905591792:252316365", "อย่างที่เจ้าอาจรู้ ข้ารวบรวมความรู้โบราณ ความรู้เก่าแก่ ทรงพลัง ความรู้ที่เปิดประตูสู่ดินแดนอื่น และปลุกเหล่าผู้หลับใหลให้ตื่นขึ้นได้\n\nมีข่าวลือว่าตำราเก่าแก่เล่มหนึ่ง คือ Lorgalis Manuscript อยู่ก้น Blackfathom Deeps ใน Ashenvale ที่นั่นเคยเป็นถิ่นอาศัยของเอลฟ์ซึ่งตายไปนานแล้ว เอลฟ์ผู้ครอบครองความรู้อันยิ่งใหญ่ก่อนเมืองของพวกเขาจะล่มสลาย\n\nจงค้นหาต้นฉบับนั้นใน Blackfathom Deeps หากเจ้าทำได้ ข้าจะไม่ลืม แม้หลังจาก... วันสิ้นโลก" },
        progress = { "95:1211004805:1545751146 N 34:230314720:1270616317", "การเดินทางไป Ashenvale ยาวไกล และงานของเจ้าก็ไม่ง่าย แต่ถ้าเจ้าหาต้นฉบับมาให้ข้าได้ {name}... รางวัลของเจ้าจะยิ่งใหญ่นัก" },
        completion = { "220:571382672:1744105082 N 76:1908008585:1589450876", "เจ้าพบต้นฉบับแล้ว! ช่างเป็นวันที่น่ายินดี! เราจะคัดลอกและแจกจ่ายมัน ในที่สุดพี่น้องของข้าจะได้รู้จักความรู้โบราณของ Lorgalis!\n\nสิ่งที่เจ้าทำให้พวกเรามีความหมายมากกว่าที่เจ้ารู้ {name} ข้าหวังว่าของขวัญชิ้นนี้จะแสดงให้เห็นถึงความขอบคุณที่เรามีต่อพันธมิตร" },
        required = { [5359] = { "19:1513037968:1813460113", "ต้นฉบับลายมือของ Lorgalis" } },
        steps = { { "19:1513037968:1813460113", "ต้นฉบับลายมือของ Lorgalis" } },
    },
    [1198] = { -- In Search of Thaelrid
        title = { "21:2012644827:1388067713", "ตามหา Thaelrid" },
        objective = { "52:1753810184:1585804623", "ตามหา Argent Guard Thaelrid ใน Blackfathom Deeps" },
        description = { "484:22115239:413639780 N 1:46:46", "ช่วงนี้มีข่าวลือมากมายเรื่องการร่วมมือกันของลัทธิ Twilight's Hammer กับพวกนากาใน Blackfathom Deeps ริมชายฝั่ง Ashenvale\n\nหน้าที่ของข้าใน Argent Dawn คือรวบรวมข้อมูลให้มากที่สุด เพื่อให้เรารู้ว่าที่ใดต้องการความช่วยเหลือและเมื่อใด\n\nหลายสัปดาห์แล้วนับจากข้าส่งผู้สอดแนมไปตรวจความเคลื่อนไหวที่ Blackfathom Deeps แต่ Argent Guard Thaelrid ยังไม่กลับมารายงาน\n\nผู้สอดแนมคนอื่นของข้าต่างติดภารกิจเร่งด่วน\n\nช่วยตามหาและช่วยเหลือ Thaelrid ให้ข้าที {name}" },
        completion = { "107:906151742:1759736928", "ดีแล้วที่ Dawnwatcher Shaedlass ส่งเจ้ามา ที่แห่งนี้ซึ่งถูกความเสื่อมทรามครอบงำกำลังมีแผนชั่วร้ายเกิดขึ้นจริง ๆ" },
    },
    [1199] = { -- Twilight Falls
        title = { "14:1507837327:1249103568", "โค่นลัทธิสนธยา" },
        objective = { "64:1221704724:698331829", "นำ Twilight Pendant 10 ชิ้นไปให้ Argent Guard Manados ใน Darnassus" },
        description = { "496:1513368532:1925922048", "ด้วยพลังจากพิธีกรรมโบราณของเหล่าเทพโบราณผู้วุ่นวาย สมาชิก Twilight's Hammer พยายามนำผู้อุปถัมภ์แห่งความมืดของตนกลับมา และแผ่ความตายกับความหวาดกลัวไปทั่วโลก\n\nเราเชื่อว่า Twilight's Hammer ร่วมมือกับพวกนากา และกำลังรวมกำลังที่ Blackfathom Deeps ริมชายฝั่ง Ashenvale\n\nไม่ว่าแผนชั่วใดกำลังก่อตัวอยู่ในส่วนลึกของวิหารเก่า เราต้องหยุดมัน\n\nจงต่อสู้กับลัทธิและนำหลักฐานการกระทำของเจ้ากลับมา เจ้าจะได้รับรางวัลอย่างงาม" },
        progress = { "225:2130242073:761676577", "Blackfathom Deeps เคยเป็นวิหารโบราณของไนต์เอลฟ์ ภายในเคยมีบ่อน้ำจันทร์ที่ทรงพลังยิ่ง ใครจะรู้ว่าตอนนี้ Twilight's Hammer กำลังก่อความชั่วร้ายอะไรอยู่ที่นั่น\n\nเจ้ากำจัดพวกมันไปได้บ้างหรือยัง?" },
        completion = { "43:605450003:320792486 N 61:1975962974:2040806298", "เจ้ามีจิตใจกล้าหาญและสูงส่งอย่างไม่ต้องสงสัย {name} Argent Dawn ขอชื่นชมความพยายามของเจ้าในการต่อกรกับความชั่วร้าย" },
        required = { [5879] = { "16:1336911080:206321752", "จี้ทไวไลต์" } },
        steps = { { "16:1336911080:206321752", "จี้ทไวไลต์" } },
    },
    [1200] = { -- Blackfathom Villainy
        title = { "20:1876793028:731548355", "ความชั่วร้ายแห่ง Blackfathom" },
        objective = { "75:296615917:926052049", "นำหัวของ Twilight Lord Kelris ไปให้ Dawnwatcher Selgorm ใน Darnassus" },
        description = { "483:1571148521:9158693 N 9:261475542:1201216930", "ข้าไม่เหลือเรี่ยวแรงแล้ว ต้องอาศัยความช่วยเหลือจากเจ้า!\n\nนานมาแล้ว ที่นี่เคยเป็นวิหารอันยิ่งใหญ่ของ Elune แต่ความวิบัตินำมันสู่หายนะ เมื่อความเสื่อมทรามจากเทพโบราณองค์หนึ่งซึมขึ้นมาจากใต้ดิน ทำให้บ่อน้ำจันทร์ศักดิ์สิทธิ์แปดเปื้อน\n\nAku'Mai ผู้รับใช้ของเทพโบราณผุดขึ้นมาจากน้ำ\n\nพวกลัทธิ Twilight's Hammer ร่วมมือกับนากายึดครองที่นี่ Kelris เป็นผู้นำลัทธิซึ่งสังเวยผู้บริสุทธิ์ให้ Aku'Mai เพื่อแลกพลัง\n\nขอร้องล่ะ {name} ฆ่า Kelris แล้วนำหัวของมันไปให้ Selgorm ที่ Darnassus" },
        progress = { "30:126534509:1308087489 C 181:1868044929:1234488366", "เวลามีค่านัก {class}\n\nหน้าที่ของข้าที่ Darnassus คือดูแลให้ Argent Dawn เติบโต และขัดขวางกองกำลังชั่วร้ายที่รุกคืบเข้ามาใน Kalimdor\n\nรีบบอกธุระของเจ้ามา หรือไม่ก็ไปเสีย" },
        completion = { "428:353764898:2095502633 N 44:94494053:600963471", "Kelris หลบเลี่ยงพวกเรามาได้นานทีเดียว\n\nดูเหมือนทุกครั้งที่ความชั่วร้ายปรากฏแถวนี้ Kelris จะมีส่วนเกี่ยวข้องอยู่เสมอ ช่วงหนึ่งเราคิดว่ามันตายหรือหายตัวไปแล้ว\n\nแต่ตอนนี้ทุกอย่างกระจ่างแล้ว การยุติอำนาจของมันช่วยชีวิตผู้บริสุทธิ์ไว้มากมาย\n\nด้วยแสงสว่าง! การสังเวยผู้อื่นให้ผู้รับใช้ของเทพโบราณเพื่อประโยชน์ส่วนตนช่างน่าประณามเกินจะกล่าว!\n\nเจ้าทำคุณความดีครั้งใหญ่ {name} ข้าขอคารวะเจ้าในนาม Argent Dawn" },
        required = { [5881] = { "14:1374333252:250531135", "ศีรษะของ Kelris" } },
        objectiveLabels = {
            item = { ["Head of Kelris"] = "ศีรษะของ Kelris" },
        },
    },
    [1275] = { -- Researching the Corruption
        title = { "26:1827266470:1800964251", "ศึกษาความเสื่อมทราม" },
        objective = { "63:1128618792:1829807930", "Gershala Nightwhisper ที่ Auberdine ต้องการ Corrupt Brain stem 8 ชิ้น" },
        description = { "482:76409143:1164409716 N 1:46:46", "พวกบลัดเอลฟ์โง่เขลามัวหมกมุ่นกับเวทมนตร์ปีศาจ พวกเขาไม่เห็นหรือว่าเกิดอะไรขึ้นกับนากาและเซเทอร์แห่ง Kalimdor?\n\nข้ากลัวว่าบลัดเอลฟ์จะกลายสภาพเช่นเดียวกัน Azeroth ไม่อาจปล่อยให้เผ่าพันธุ์อสูรร้ายถือกำเนิดขึ้นอีก\n\nข้าต้องการศึกษาก้านสมองของเซเทอร์และนากา เพื่อวิเคราะห์ว่าพวกเอลฟ์กำลังมุ่งไปสู่ชะตากรรมใด เจ้าจะพบทั้งเซเทอร์และนากาใน Blackfathom Deeps ริมชายฝั่ง Ashenvale\n\nเป็นการเดินทางที่ยาวไกลนะ {name}" },
        progress = { "305:1397997177:1943617415", "เมื่อมีตัวอย่างให้ศึกษามากพอ งานที่แท้จริงของข้าจึงจะเริ่มได้ ก้านสมองที่แปดเปื้อนของเซเทอร์และนากาแห่ง Blackfathom Deeps จะช่วยให้ข้าลองหาความสัมพันธ์ระหว่างการกลายสภาพของทั้งสองเผ่าพันธุ์\n\nความรู้ที่ได้อาจช่วยเรายับยั้งบลัดเอลฟ์ ไม่ให้จมลึกลงสู่ความผิดรูปและความชั่วร้าย" },
        completion = { "171:1203139895:967056737 N 80:1905598115:1364317550", "เจ้าเดินทางมาไกล และต้องเผชิญอันตรายมากมายแน่นอน\n\nเจ้าลงมือโดยไม่เห็นแก่ตัว การช่วยงานวิจัยของข้าเป็นประโยชน์ต่อ Azeroth ทั้งหมด ข้าขอบคุณสำหรับทุกสิ่งที่เจ้าทำ {name}\n\nข้าขอตัวก่อน ยังมีงานอีกมากที่ต้องทำ..." },
        required = { [5952] = { "20:955508716:609939980", "ก้านสมองที่แปดเปื้อน" } },
        steps = { { "20:955508716:609939980", "ก้านสมองที่แปดเปื้อน" } },
    },
    [275] = { -- Blisters on The Land
        title = { "20:647267133:1146937206", "แผลพุพองของผืนดิน", variants = { { "20:1257942054:1010896400", "แผลพุพองของผืนดิน" } } },
        objective = { "77:1236877885:1038898009", "ฆ่า Fen Creeper 12 ตน แล้วกลับไปหา Rethiel the Greenwarden ใน Wetlands" },
        description = { "294:1879034102:520397290", "ข้าไม่รู้ว่าเพราะเหตุใด แต่ความเน่าเปื่อยกำลังเติบโตใน Wetlands พวก Fen Creeper ลุกขึ้นมา พวกมันคือแผลพุพองอันเจ็บป่วยและร้อนรุ่มของผืนดิน หากจะให้ไข้ทุเลา เราต้องกำจัดพวกมันและปล่อยให้คืนสู่หนองบึง\n\nFen Creeper เดินโซเซอยู่ตามลำน้ำใน Wetlands" },
        progress = { "94:964584093:1101970637", "Wetlands ยังคงร่ำไห้ และ Fen Creeper ยังคงอาละวาด จงกลับมาหาข้าเมื่องานของเจ้าเสร็จแล้ว" },
        completion = { "75:765796454:634622682", "ความพยายามของเจ้าช่วยบรรเทาความเจ็บปวดให้ผืนดิน ข้าจะมอบพรตอบแทน" },
        objectiveLabels = {
            monster = { ["Fen Creeper slain"] = "ปราบ ตัวคืบคลานแห่งบึง" },
        },
    },
    [276] = { -- Tramping Paws
        title = { "13:722881160:768667616", "อุ้งเท้าที่เหยียบย่ำ" },
        objective = { "105:912949939:2003866216", "ฆ่า Mosshide Gnoll 15 ตัว และ Mosshide Mongrel 10 ตัว แล้วกลับไปหา Rethiel the Greenwarden ใน Wetlands" },
        description = { "450:747965661:1110667669", "พวกโนลล์ Mosshide อาศัยอยู่ใน Wetlands อย่างสงบมาหลายปี แต่บัดนี้มีจำนวนมากขึ้น เท้าของพวกมันเหยียบพุ่มไม้และดอกไม้ในบึงจนราบ ขวานชั่วร้ายตัดไม้ไปก่อไฟมากเกินไป\n\nพวกมันไม่สมดุลกับผืนดินอีกแล้ว หาก Wetlands จะอยู่รอด เราต้องลดจำนวนโนลล์ลง\n\nฆ่า Mosshide Gnoll 15 ตัว และ Mosshide Mongrel 10 ตัว ล่าพวกมันทางใต้ ใกล้ประตู Algaz ของคนแคระ แล้วกลับมาหาข้า" },
        progress = { "34:1746381820:755690911 C 1:46:46", "ภารกิจของเจ้ายังรออยู่ {class} รุ่นเยาว์" },
        completion = { "140:1724039895:314060884 R 25:409615866:1715700339", "การลดจำนวนโนลล์ช่วยดูแลสุขภาพของ Wetlands แม้ศรัทธาที่ข้ามีต่อเผ่าพันธุ์ของเจ้าจะถูกทดสอบมาแล้ว {race} แต่บางทีข้าอาจกลับมาเชื่อมั่นได้อีก", variants = { { "141:494548607:1019438293 R 25:409615866:1715700339", "พอเจ้าช่วยลดจำนวนโนลล์ลง Wetlands ก็ฟื้นตัวได้ แม้ที่ผ่านมาเผ่าของเจ้าจะทำให้ข้าคลางแคลงใจ {race} แต่ข้าอาจกลับมาเชื่อใจพวกเจ้าได้อีก" } } },
        objectiveLabels = {
            monster = { ["Mosshide Gnoll slain"] = "ปราบ โนลล์ Mosshide", ["Mosshide Mongrel slain"] = "ปราบ โนลล์พันธุ์ผสม Mosshide" },
        },
    },
    [277] = { -- Fire Taboo
        title = { "10:1960827676:735072215", "ห้ามก่อไฟ" },
        objective = { "45:1489305069:2049625108", "นำ Crude Flint 9 ชิ้นไปให้ Rethiel the Greenwarden" },
        description = { "310:473584995:786425004", "พวก Mosshide กำลังตัดต้นไม้ของ Wetlands ใช้เนื้อไม้ก่อไฟให้ตัวเองอบอุ่น ข้าจะไม่ทนรับความเจ็บปวดนี้อีก!\n\nยึดหินเหล็กไฟหยาบ ๆ ซึ่งพวก Mosshide ใช้ก่อไฟมา พวก Mosshide ทุกชนิดพกหินนี้ ยกเว้น Mosshide Gnoll กับ Mosshide Mongrel ตัวเล็ก ๆ" },
        progress = { "39:1494257868:979339332", "เจ้าได้เครื่องมือก่อไฟของพวกโนลล์มาหรือยัง?" },
        completion = { "126:254099490:408495711", "... ขอบใจ ข้าจะทุบหินเหล็กไฟเหล่านี้ให้แตกแล้วโยนลงทะเล มันจะได้ไม่ถูกนำมาเผาไม้ที่ยังมีชีวิตอีก" },
        required = { [2611] = { "11:1246437343:1451182124", "หินเหล็กไฟหยาบ" } },
        steps = { { "11:1246437343:1451182124", "หินเหล็กไฟหยาบ" } },
    },
    [279] = { -- Claws from the Deep
        title = { "19:1523553368:540259535", "กรงเล็บจากห้วงลึก" },
        objective = { "112:1716919645:2050662964", "ฆ่า Bluegill Murloc 12 ตัว\n\nฆ่า Gobbler แล้วตัดหัวของมัน\n\nนำ Gobbler's Head ไปให้ Karl Boran ที่ Menethil Harbor" },
        description = { "483:1120545336:1980930720", "พวกเมอร์ล็อกคลานขึ้นจากน้ำลึกมาสร้างหมู่บ้านตามชายฝั่ง มันคุกคามชาวประมงและพ่อค้าของเรา ต้องหยุดพวกมัน\n\nเมอร์ล็อกตัวหนึ่งชื่อ Gobbler หลบซ่อนอยู่กับ Bluegill Murloc คอยก่อกวนพ่อค้าตามถนน แล้วหนีกลับไปยังกระท่อมเมอร์ล็อกใกล้ ๆ พ่อค้าของเรากำลังมีภัย และเรายินดีจ่ายเพื่อให้พวกเขาปลอดภัย\n\nGobbler เพ่นพ่านอยู่แถวปากแม่น้ำทางเหนือของที่นี่ จงหามัน ฆ่าพวกพ้องของมัน แล้วนำหัวมันมาให้ข้า" },
        progress = { "77:1917887376:891152382", "พ่อค้าของเราจะยังไม่ปลอดภัย จนกว่าเราจะกำจัด Gobbler และพวกเมอร์ล็อกเหล่านั้น" },
        completion = { "14:1953039402:1129575126 N 84:505018569:1976611695", "อา ทำได้ดี {name}\n\nรับเงินนี้เป็นค่าตอบแทนที่เจ้าทำตามสัญญากับ Merchant Marines" },
        required = { [3618] = { "14:2006592957:383534128", "ศีรษะของ Gobbler" } },
        steps = { { "14:2006592957:383534128", "ศีรษะของ Gobbler" } },
        objectiveLabels = {
            monster = { ["Bluegill Murloc slain"] = "ปราบ เมอร์ล็อก Bluegill" },
        },
    },
    [281] = { -- Reclaiming Goods
        title = { "16:588978913:1630172237", "ทวงคืนสินค้า" },
        objective = { "58:1970503025:1670987981", "ค้นลังและถังที่ค่ายเมอร์ล็อกตามชายฝั่ง" },
        description = { "393:568299253:1528449657", "ไม่นานมานี้ เรือสินค้า Blind Princess ถูกเมอร์ล็อกบุกปล้น แม้เรือจะหนีมาได้โดยไม่เสียหาย แต่พวกมันลากสินค้าจำนวนมากตกทะเลไป รวมถึงรูปปั้นขนาดเล็กอันมีค่าของ Terenas Menethil เราต้องการรูปปั้นนั้นคืน\n\nค้นกระท่อมเมอร์ล็อกตามชายฝั่ง มองหาลัง ถัง และร่องรอยของสินค้าที่หายไป หา Menethil Statuette แล้วนำกลับมาให้ข้า" },
        completion = { "251:699766027:1386044176", "ลังนี้เต็มไปด้วยรอยกรงเล็บและร่องรอยความเสียหายจากน้ำ เมื่อแงะเปิดออก คุณพบฟางเปียกเน่า ราวกับเคยใช้รองของมีค่า คุณคุ้ยดูในฟาง...\n\n...แล้วพบขวดสีแดงเต็มอ้อมแขน" },
    },
    [284] = { -- The Search Continues
        title = { "20:87968286:518199288", "ค้นหาต่อไป" },
        objective = { "34:1896422889:331182225", "ค้นหา Menethil Statuette" },
        description = { "183:616589995:1683843454", "คุณค้นกระท่อมเมอร์ล็อกกลุ่มนี้อย่างละเอียด แต่ไม่พบร่องรอยของ Menethil Statuette\n\nบางทีกระท่อมอีกสองหลังใกล้ ๆ ทางเหนือและตะวันออกเฉียงเหนืออาจมีเบาะแสเพิ่มเติม" },
        completion = { "139:672784026:996251215", "ถังนี้แทบไม่ถูกแตะต้อง เมื่อแงะเปิด...\n\n...กลิ่นชีสฉุนจัดก็พุ่งเข้าใส่ แม้จะเปียกไปหน่อย แต่ก็ยังอร่อย!" },
    },
    [285] = { -- Search More Hovels
        title = { "18:994213347:711455397", "ค้นกระท่อมเพิ่ม" },
        objective = { "64:1161931641:508708116", "ค้นกระท่อมเมอร์ล็อกต่อไปเพื่อหา Menethil Statuette" },
        description = { "210:359862320:1867689881", "เมื่อตรวจดูกระท่อมเมอร์ล็อกกลุ่มนี้อย่างละเอียด คุณก็ไม่พบอะไร\n\n...แต่คุณมั่นใจว่าเบาะแสถัดไปจะต้องนำไปสู่คำตอบ\n\nMenethil Statuette ต้องอยู่ในกระท่อมสักหลังทางเหนือแน่!" },
        completion = { "58:591268541:503109128", "ถังนี้จมอยู่ครึ่งหนึ่งท่ามกลางโคลนและหญ้า..." },
    },
    [286] = { -- Return the Statuette
        title = { "20:679554031:662369552", "นำรูปปั้นกลับคืน" },
        objective = { "40:1038536228:1121866307", "นำ Menethil Statuette ไปให้ Karl Boran" },
        description = { "265:199098746:1188220744", "เมื่อลากถังออกจากโคลนแล้วเปิด คุณพบรูปปั้นสีเงินห่ออยู่ในฟางอย่างดี มันเป็นรูปพาลาดินหนุ่มผมยาวกำลังชูค้อน\n\nนี่ต้องเป็น Menethil Statuette! คุณต้องนำมันกลับไปให้ Karl Boran ที่ Menethil Harbor" },
        progress = { "26:1789021956:136094024", "เจ้าได้รูปปั้นมาหรือยัง?" },
        completion = { "241:825496403:2073059795", "กัปตันเรือ Blind Princess คงโล่งใจเมื่อรู้ว่าได้สินค้ามีค่าชิ้นนี้คืน เจ้าสมควรได้รับค่าตอบแทนนี้สำหรับงานที่ทำ\n\nดีที่ยังมีคนไว้ใจได้อย่างเจ้า โดยเฉพาะในยามยากเช่นนี้" },
        required = { [2625] = { "18:1305917549:656121578", "รูปปั้นเล็ก Menethil" } },
        steps = { { "18:1305917549:656121578", "รูปปั้นเล็ก Menethil" } },
    },
    [288] = { -- The Third Fleet
        title = { "15:2098042686:445299450", "กองเรือที่สาม" },
        objective = { "44:2075223811:339736451", "ซื้อ Flagon of Mead ให้ First Mate Fitzsimmons" },
        description = { "480:393982787:525813149", "ข้าเคยเป็นต้นเรือ Wave Mistress เรือรบในกองเรือที่สามของ Kul Tiras กองเรืออับโชค อับโชคเพราะในการเดินทางครั้งสุดท้าย พวกเราถูกมังกรแดงโจมตี มังกรที่ออร์คควบคุม!\n\nเราไม่มีทางสู้เปลวไฟของมังกรได้เลย... กองเรือของเราถูกเผาและจมลงนอกชายฝั่งนี้ ข้าเป็นผู้รอดชีวิตเพียงคนเดียวจากเรือที่น่าสงสารเหล่านั้น...\n\n...โอ๊ย หัวข้าปวดตุบ ๆ! ข้าต้องดื่มอีกสักแก้วเพื่อแก้อาการเมาค้าง แล้วจะเล่าต่อได้" },
        progress = { "76:1144730062:545969980", "โอ้ ข้ากระหายน้ำเหลือเกิน! เจ้าไม่คิดจะซื้อเหล้าให้คนโง่น่าสมเพชผู้นี้สักแก้วหรือ?" },
        completion = { "61:2001008177:1843755792", "อ้า! ชื่นใจจริง ๆ ลิ้นเริ่มคล่องแล้ว ขอบใจ สหาย!" },
        required = { [2594] = { "27:1253754066:749535017", "เหล้าน้ำผึ้งคนแคระหนึ่งเหยือก" } },
        steps = { { "27:1253754066:749535017", "เหล้าน้ำผึ้งคนแคระหนึ่งเหยือก" } },
    },
    [289] = { -- The Cursed Crew
        title = { "15:414224076:335792587", "ลูกเรือต้องสาป" },
        objective = { "135:821061514:1637030692", "ฆ่า Cursed Sailor 13 ตน, Cursed Marine 5 ตน และ First Mate Snellig นำ Snellig's Snuffbox ไปให้ First Mate Fitzsimmons ที่ Menethil Harbor" },
        description = { "499:1415679101:920779996", "<เมื่อมีกำลังใจขึ้น Fitzsimmons ก็เล่าต่อ...>\n\nข้าเป็นผู้รอดชีวิตเพียงคนเดียวของกองเรือที่สามแห่ง Kul Tiras ที่อับปางนอกชายฝั่งทางเหนือ แต่แม้ข้าจะเป็นคนเดียวที่ยังหายใจอยู่ ข้าก็ไม่ใช่คนเดียวที่ยังเดินไปมา! มีสมบัติอันยิ่งใหญ่และน่าสะพรึงกลัวซ่อนอยู่บนเรือลำหนึ่ง พลังลึกลับของมันกักวิญญาณพี่น้องของข้าไว้ในตัวเรือที่ผุพัง\n\nหากเจ้าช่วยปลดปล่อยพี่น้องของข้าได้บ้าง บางทีเจ้าอาจทำลายคำสาปของพวกเขาได้" },
        progress = { { "133:2100449327:1122337689", "135:1523466175:1737719696" }, "บางครั้งในฝัน ข้าได้ยินเสียงคร่ำครวญอันสิ้นหวังของพี่น้อง! ขอร้องเถิดท่านผู้ใจดี ปลดพันธนาการให้พวกเขาและทำให้เสียงร่ำไห้สงบลง" },
        completion = { "18:979705708:1794378923 N 62:242245288:1657804758", "ข้าขอบคุณเจ้า {name} และพี่น้องต้องสาปของข้าก็ขอบคุณเจ้าเช่นกัน" },
        required = { [3619] = { "18:519194851:1606647750", "กล่องยานัตถุ์ของ Snellig" } },
        steps = { { "18:519194851:1606647750", "กล่องยานัตถุ์ของ Snellig" } },
        objectiveLabels = {
            monster = { ["Cursed Sailor slain"] = "ปราบ กะลาสีต้องสาป", ["Cursed Marine slain"] = "ปราบ นาวิกโยธินต้องสาป" },
        },
    },
    [290] = { -- Lifting the Curse
        title = { "17:1559293807:284260837", "ถอนคำสาป" },
        objective = { "106:1782867311:573451790", "เอา Intrepid Strongbox Key จาก Captain Halyndor\n\nใช้กุญแจเปิด Intrepid's Locked Strongbox" },
        description = { "479:874645484:2106295706", "เพื่อทำลายคำสาปและปลดปล่อยพี่น้องของข้าทุกคน ต้องนำ... สิ่งนั้น... ที่เก็บอยู่บนเรือข้าออกมาชำระล้าง! ข้าไม่รู้ว่ามันคืออะไร แต่รู้ว่ามันถูกเก็บไว้อย่างแน่นหนาในหีบนิรภัยของเรือ ซึ่ง Captain Halyndor คอยดูแลหวงแหน\n\nกัปตันคนเก่ายังปรากฏในฝันข้า ข้ารู้ว่าเขายังเดินอยู่บนเรืออับโชค Intrepid จงเอากุญแจจากเขา แล้วใช้เปิดหีบนิรภัยบนเรือ Intrepid\n\nเมื่อได้สิ่งต้องสาปนั้นแล้ว ให้นำไปหานักบวช Glorin Steelbrow ในเมือง" },
        progress = { "30:999867645:917640428", "หีบนี้ล็อกไว้อย่างแน่นหนา" },
        completion = { "46:133525113:1925041068", "กุญแจขึ้นสนิม แต่ไขเข้ากับแม่กุญแจได้พอดี" },
        required = { [2629] = { "22:1022674196:866893135", "กุญแจหีบนิรภัยของเรือ Intrepid" } },
        steps = { { "22:1022674196:866893135", "กุญแจหีบนิรภัยของเรือ Intrepid" } },
    },
    [292] = { -- The Eye of Paleth
        title = { "17:1108014170:1477809486", "ดวงตาแห่ง Paleth" },
        objective = { "51:1702349551:1514741124", "นำ Cursed Eye of Paleth ไปให้ Glorin Steelbrow" },
        description = { "271:370430251:1388602589", "เมื่อเปิดหีบ คุณพบลูกแก้วสีดำคล้ำที่เต้นเรืองแสงอย่างน่าขนลุก มันคือสมบัติที่ Fitzsimmons พูดถึง: Cursed Eye of Paleth\n\nนำ Cursed Eye of Paleth ไปหานักบวชคนแคระ Glorin Steelbrow ที่ Menethil Harbor ถามเขาว่าจะถอนคำสาปจากดวงตานี้ได้อย่างไร" },
        progress = { "135:172549182:2025625273", "ไอ้ขี้เมา Fitzsimmons ส่งเจ้ามาหาข้าหรือ? บอกเขาได้เลยว่าข้าไม่มีเอลเหลือให้ เขาต้องไปขอทานจากคนอื่นแล้ว!" },
        completion = { "287:604077774:1272321329", "Eye of Paleth หรือ? มหัศจรรย์! อืม... ชิ้นนี้มีบางอย่างผิดปกติ เจ้าพบมันบนซากเรือลำหนึ่งหรือ? อ้อ อย่างนี้นี่เอง! แต่... ข้าไม่รู้มาก่อนว่ากองเรือที่สามมีดวงตาเช่นนี้อยู่...\n\nมิน่าเล่า Fitzsimmons ถึงได้หวาดผวา Cursed Eye of Paleth ไม่ใช่เรื่องน่าหัวเราะเลย" },
        required = { [2944] = { "20:998825320:1966160468", "ดวงตาต้องสาปแห่ง Paleth" } },
        steps = { { "20:998825320:1966160468", "ดวงตาต้องสาปแห่ง Paleth" } },
    },
    [293] = { -- Cleansing the Eye
        title = { "17:1209949850:1637348052", "ชำระดวงตา" },
        objective = { "120:1475568367:498120226", "นำ Cursed Eye of Paleth ไปให้ Archbishop Benedictus ที่ Cathedral of Light ในเมือง Stormwind" },
        description = { "275:317851725:167675612", "ข้าถอนคำสาปจาก Eye of Paleth ไม่ได้ นักบวชมนุษย์เป็นผู้สร้างดวงตาเหล่านี้ เจ้าต้องไป Stormwind เพื่อหาคนช่วย คุยกับ Archbishop Benedictus เขาเป็นผู้นำ Cathedral of Light ใน Stormwind เขาช่วยได้\n\nข้าหวังเช่นนั้น เพื่อประโยชน์ของเจ้าเอง" },
        progress = { "45:1172252586:320728071", "ลูกแก้วที่เจ้าถือมาคืออะไร? มันดู... แปดเปื้อน" },
        completion = { "240:523818471:742248057", "Eye of Paleth แต่ชิ้นนี้ผ่านความเศร้ามามาก... มันต้องเคยเห็นโศกนาฏกรรมที่เลวร้ายอย่างยิ่ง\n\nให้ข้าชำระมันเถิด ดวงตาเหล่านี้ถูกสร้างมาให้ส่องสว่าง พลังของมันอาจเป็นอันตรายมากเมื่อแปดเปื้อนเช่นชิ้นนี้" },
        required = { [2944] = { "20:998825320:1966160468", "ดวงตาต้องสาปแห่ง Paleth" } },
        steps = { { "20:998825320:1966160468", "ดวงตาต้องสาปแห่ง Paleth" } },
    },
    [294] = { -- Ormer's Revenge
        title = { "15:1919278809:313095887", "การแก้แค้นของ Ormer" },
        objective = { "110:603851229:1814459129", "Ormer Ironbraid ที่ Whelgar Excavation Site ต้องการให้คุณฆ่า Mottled Screecher 10 ตัว และ Mottled Raptor 10 ตัว" },
        description = { "241:1969658497:1216947517 N 171:1114059399:1851519628", "สถานการณ์เลวร้ายแน่นอน เมื่อเราขุดพบกระดูกเหล่านี้ ก็ล่อพวกแรปเตอร์มา สัตว์โสโครกพวกนั้นฆ่าพี่น้องข้า และทำให้ข้า Merrin กับนักสำรวจผู้น่าสงสารติดอยู่บนนี้\n\nช่วยกำจัดแรปเตอร์พวกนี้ออกจาก Wetlands ที {name} Mottled Raptor และ Mottled Screecher อยู่ทางตะวันตกของหน้าผานั่น ถ้าไหวก็ฆ่าอย่างละ 10 ตัว\n\nนั่นจะเป็นจุดเริ่มต้นที่ดีสำหรับการแก้แค้นที่ข้าวางแผนไว้" },
        progress = { "51:1300554850:1361262850 N 97:276180985:1047358966", "ฆ่า Mottled Raptor 10 ตัว และ Mottled Screecher 10 ตัว {name} เพื่อนร่วมงานข้าไม่สมควรพบชะตาเช่นนั้น ถึงเวลาทวงคืนแล้ว" },
        completion = { "56:2019539494:28679157 N 119:1498204035:775531871", "การฆ่าเป็นงานเปื้อนเลือด แต่เจ้าทำได้ดี {name} ถ้าข้าไม่ต้องอยู่ดูแลนักสำรวจกับ Merrin ข้าคงลงไปหลั่งเลือดเคียงข้างเจ้าแล้ว" },
        objectiveLabels = {
            monster = { ["Mottled Raptor slain"] = "ปราบ แรปเตอร์ลายด่าง", ["Mottled Screecher slain"] = "ปราบ แรปเตอร์ลายด่างเสียงแหลม" },
        },
    },
    [295] = { -- Ormer's Revenge
        title = { "15:1919278809:313095887", "การแก้แค้นของ Ormer" },
        objective = { "146:1542632172:721294094", "Ormer Ironbraid ต้องการให้คุณฆ่าแรปเตอร์ Mottled Scytheclaw 10 ตัว และ Mottled Razormaw 10 ตัว แล้วกลับไปหาเขาที่ Whelgar Excavation Site", variants = { { "147:1630093623:991163514", "Ormer Ironbraid ต้องการให้คุณฆ่าแรปเตอร์ Mottled Scytheclaw 10 ตัว และ Mottled Razormaw 10 ตัว แล้วกลับไปหาเขาที่ Whelgar Excavation Site" } } },
        description = { "211:815682392:1495344334", "ถึงเวลาทำให้แรปเตอร์น่ากลัวพวกนั้นเสียใจที่กระหายเลือด ด้านล่างมี Mottled Scytheclaw และ Mottled Razormaw อยู่มากมาย ฆ่าอย่างละ 10 ตัว ให้สัตว์ชั่วพวกนั้นชดใช้!" },
        progress = { "117:1071153223:1294871695", "ข้าต้องการให้ Mottled Scytheclaw กับ Mottled Razormaw ชดใช้สิ่งที่ทำไป เจ้าฆ่าพวกมันอย่างละ 10 ตัวแล้วหรือยัง?" },
        completion = { "53:1772322968:746268344 N 1:33:33", "เจ้าจัดการพวกแรปเตอร์ได้ยอดเยี่ยม {name}!", variants = { { "53:1949471434:104791790 N 1:33:33", "เจ้าจัดการพวกแรปเตอร์ได้ยอดเยี่ยม {name}!" } } },
        objectiveLabels = {
            monster = { ["Mottled Scytheclaw slain"] = "ปราบ แรปเตอร์ลายด่างกรงเล็บเคียว", ["Mottled Razormaw slain"] = "ปราบ แรปเตอร์ลายด่างเขี้ยวคม" },
        },
    },
    [296] = { -- Ormer's Revenge
        title = { "15:1919278809:313095887", "การแก้แค้นของ Ormer" },
        objective = { "143:1346687376:1542805812", "Ormer Ironbraid ที่ Whelgar Excavation Site ต้องการให้คุณฆ่า Sarltooth แล้วนำเล็บของมันกลับไปให้เขาเป็นหลักฐาน" },
        description = { "247:2117793509:222279028 N 176:1831311747:86901461", "ระหว่างเจ้าลงไปข้างล่าง ข้าสังเกตเห็นสัตว์ตัวหนึ่งโดดเด่นกว่าตัวอื่น มันใหญ่กว่าและดูอันตรายกว่า ข้าพนันว่ามันเป็นตัวนำพวกที่เหลือมาสร้างความวุ่นวายให้แหล่งขุดค้น\n\nข้าขอร้องอีกงานเป็นครั้งสุดท้าย {name} จงนำความยุติธรรมมาสู่ Sarltooth ด้วยความร้ายแรงของสิ่งที่มันทำ ความยุติธรรมในกรณีนี้หมายถึงความตาย! นำเล็บของมันมาให้ข้าสักอันเป็นหลักฐานว่ามันตายแล้ว" },
        progress = { "62:1875750398:250232793", "Sarltooth ตายแล้วหรือ? เจ้าได้ทวงความเป็นธรรมให้ผู้ล่วงลับแล้วหรือยัง?" },
        completion = { "11:1191658970:1224418299 N 240:1664124408:179610014", "ขอบใจ {name} เราจะไม่ลืมสิ่งที่เจ้าทำที่นี่ คนแคระผู้บริสุทธิ์มากมายตายที่แหล่งขุดค้นนี้ ทั้งที่เพียงทำงานของตน การแก้แค้นที่เจ้ามอบให้สัตว์ชั่วเหล่านั้นน่าจะทำให้มันคิดให้ดีก่อนโจมตีราษฎรของกษัตริย์ Magni อีก" },
        required = { [3638] = { "17:642307378:1942674644", "กรงเล็บของ Sarltooth" } },
        steps = { { "17:642307378:1942674644", "กรงเล็บของ Sarltooth" } },
    },
    [299] = { -- Uncovering the Past
        title = { "19:1923837355:1343702483", "ขุดค้นอดีต" },
        objective = { "129:1241570787:142997509", "Prospector Whelgar ต้องการให้คุณค้นแหล่งขุดค้นเพื่อหาชิ้นส่วนแผ่นจารึกที่หายไป 4 ชิ้น: Ados, Modr, Golm และ Neru" },
        description = { "498:1929397247:70552603", "ก่อนถูกบุกโจมตี ข้าเพิ่งขุดพบแผ่นจารึกขนาดใหญ่ชื่อ Goaz Stone ข้อความที่แปลขาดไป 4 แห่ง จารึกกล่าวถึง \"แผนการแห่งทวยเทพ\" และ \"คำพยากรณ์แห่งหายนะ\"\n\nข้ากลัวว่าเวลาเราจะเหลือน้อยแล้ว ข้าแก่เกินจะลงไปเผชิญสัตว์ร้าย แต่เจ้ายังแข็งแรง\n\nจงค้นแหล่งขุดค้นเพื่อหาชิ้นส่วนแผ่นจารึกที่หายไป 4 ชิ้น: Ados, Modr, Golm และ Neru มองหาในโบราณวัตถุหรือตรงดินร่วน แล้วนำมาให้ข้าเริ่มไขปริศนา!" },
        progress = { "43:1873389011:1542630575 N 30:284278692:279765351", "พบชิ้นส่วนทั้งสี่แล้วหรือยัง {name}? Ados, Modr, Golm และ Neru..." },
        completion = { "42:1773798122:1859003170 N 228:1200151734:703437436", "อา Goaz Stone ครบแล้ว! ทำได้ดี {name} ดีมากจริง ๆ ตอนนี้ข้าแปลอักษรไททันอันละเอียดซับซ้อนนี้ต่อได้แล้ว ข้าเริ่มอ่านคำใหม่ ๆ ออก! อืม... ตรงนี้เขียนว่า \"เทพโบราณ... ถูกล่ามไว้ใต้ผืนดิน\" นี่คือจุดเริ่มต้นของเรื่องราวอันยิ่งใหญ่", variants = { { "42:1773798122:1859003170 N 225:76747222:895367604", "อา Goaz Stone ครบแล้ว! ทำได้ดี {name} ดีมากจริง ๆ ตอนนี้ข้าแปลอักษรไททันอันละเอียดซับซ้อนนี้ต่อได้แล้ว ข้าเริ่มอ่านคำใหม่ ๆ ออก! อืม... ตรงนี้เขียนว่า \"เทพโบราณ... ถูกล่ามไว้ใต้ผืนดิน\" นี่คือจุดเริ่มต้นของเรื่องราวอันยิ่งใหญ่" } } },
        required = { [2658] = { "13:502400643:1027457663", "ชิ้นส่วน Ados" }, [2659] = { "13:1989774027:2060537084", "ชิ้นส่วน Modr" }, [2660] = { "13:436956374:1741175157", "ชิ้นส่วน Golm" }, [2661] = { "13:1361935374:2033670258", "ชิ้นส่วน Neru" } },
        steps = { { "13:502400643:1027457663", "ชิ้นส่วน Ados" }, { "13:1989774027:2060537084", "ชิ้นส่วน Modr" }, { "13:436956374:1741175157", "ชิ้นส่วน Golm" }, { "13:1361935374:2033670258", "ชิ้นส่วน Neru" } },
    },
    [305] = { -- In Search of The Excavation Team
        title = { "32:1724873704:74468505", "ตามหาทีมขุดค้น", variants = { { "32:293906581:1017109326", "ตามหาทีมขุดค้น" } } },
        objective = { "91:1126340267:1073294939", "Tarrel Rockweaver ต้องการให้คุณไปที่แหล่งขุดค้นและติดต่อ Merrin Rockweaver" },
        description = { "444:44006034:1110620464 N 49:1378563116:116890813", "โอ้ เจ้าต้องเป็นผู้สอดแนมที่ Longbraid บอกว่าจะส่งมาแน่! เจ้านึกไม่ออกหรอกว่าข้ากังวลแค่ไหน\n\nMerrin ภรรยาข้าส่งจดหมายมาทุกสัปดาห์ตลอดเดือนที่ผ่านมา นางเป็นสมาชิกทีมขุดค้น Whelgar แต่เกือบสองสัปดาห์แล้วที่ไม่มีจดหมายจากนาง ต้องมีอะไรผิดปกติแน่!\n\nLongbraid บอกว่าจะส่งผู้สอดแนมไปดู หากเราไม่ได้ข่าวจากทีมในเร็ว ๆ นี้ ข้าคิดว่าคนนั้นคือเจ้า {name} ไปหา Merrin ที่แหล่งขุดค้นทางตะวันออกที!", variants = { { "385:1034727669:519005597 N 49:1378563116:116890813", "เจ้านึกไม่ออกหรอกว่าข้ากังวลแค่ไหน\n\nMerrin ภรรยาข้าส่งจดหมายมาทุกสัปดาห์ตลอดเดือนที่ผ่านมา นางเป็นสมาชิกทีมขุดค้น Whelgar แต่เกือบสองสัปดาห์แล้วที่ไม่มีจดหมายจากนาง ต้องมีอะไรผิดปกติแน่!\n\nLongbraid บอกว่าจะส่งผู้สอดแนมไปดูหากเราไม่ได้ข่าวจากทีมในเร็ว ๆ นี้ ข้าคิดว่าคนนั้นคือเจ้า {name} ไปหา Merrin ที่แหล่งขุดค้นทางตะวันออกที!" } } },
        completion = { "35:998124316:2115401328", "โอ้ ขอบคุณสวรรค์ที่เจ้ามา!" },
    },
    [306] = { -- In Search of The Excavation Team
        title = { "32:1724873704:74468505", "ตามหาทีมขุดค้น", variants = { { "32:293906581:1017109326", "ตามหาทีมขุดค้น" } } },
        objective = { "47:539178707:1566768417", "นำจดหมายของ Merrin กลับไปให้ Tarrel Rockweaver" },
        description = { "433:112367632:1258423549", "มันเลวร้ายเหลือเกิน! เรากำลังขุดโบราณวัตถุหายาก แล้วเริ่มพบกระดูกขนาดใหญ่เหล่านี้\n\nยังไม่ทันรู้ว่าเกิดอะไรขึ้น Mottled Raptor ก็กรูเข้ายึดแหล่งขุดค้น หลายคนเสียชีวิต\n\nOrmer ผู้นี้กล้าหาญมาก เขาช่วยข้ากับนักสำรวจไว้ คอยป้องกันขณะเราวิ่งหาที่หลบภัย ตอนนี้เราติดอยู่ที่นี่ และผลงานที่ทุ่มเทมาทั้งหมดก็พังพินาศ\n\nนี่ นำจดหมายนี้กลับไปให้ Tarrel ที่รักของข้า มันจะอธิบายสถานการณ์ให้เขาฟัง" },
        progress = { "48:1319467600:591695132", "เจ้าพบ Merrin แล้วหรือ? นางฝากข่าวมาหรือไม่?" },
        completion = { "148:1032633103:32800907", "เป็นข่าวร้ายเหลือเกิน! อย่างน้อยก็มีคนรอดชีวิต 3 คน แต่การฆ่าฟันจะจบลงเมื่อไร? ข้ารอคอยวันที่ราษฎรของกษัตริย์ Magni จะอยู่ได้โดยไม่ต้องหวาดกลัว" },
        required = { [2639] = { "15:363325430:1593663480", "จดหมายของ Merrin" } },
        steps = { { "15:363325430:1593663480", "จดหมายของ Merrin" } },
    },
    [463] = { -- The Greenwarden
        title = { "15:1573777234:2050836492", "ผู้พิทักษ์พงไพร" },
        objective = { "21:681032561:1466878861", "ตามหา Greenwarden" },
        description = { { "466:779744802:806061994", "466:900327531:543684224" }, "เจ้าเคยได้ยินเรื่อง Greenwarden หรือ? คงไม่ได้กำลังตามหาเขาใช่ไหม? ถ้าใช่ข้าว่าเจ้าบ้าแล้ว แต่ข้าจะเป็นใครไปห้ามคนโง่ที่อยากตาย?\n\nถ้าเจ้าจะหาสัตว์ประหลาดนั่นจริง ๆ ข้าได้ยินว่าเขาอยู่ในบึง ทางตะวันออกของถนนตรงแยกไป Dun Modr เขาซุ่มอยู่ท่ามกลางจระเข้... และสิ่งที่ร้ายกว่านั้น!\n\nทิ้งเงินไว้ที่นี่ด้วย ที่ที่เจ้าจะไปคงไม่ต้องใช้... แล้วเจ้าคงไม่อยากให้ทองของเจ้าบิ่นฟันตา Greenie ตอนเขากัดเจ้าขาดสองท่อนใช่ไหม?" },
        completion = { "232:1438343099:1839691270", "รากไม้และเฟิร์นกล่าวถึงเจ้าด้วยดี เจ้าตัวเล็ก แม้ข้าจะมีหลายชื่อ แต่ข้าตอบรับเพียงไม่กี่ชื่อ เจ้าจะเรียกข้าว่า Rethiel ก็ได้\n\nจงฟังให้ดี... ผืนดินเหล่านี้ร่ำไห้จากบาดแผลเน่าเปื่อย และข้าจะมอบหมายให้เจ้ารักษามัน" },
    },
    [470] = { -- Digging Through the Ooze
        title = { "24:1544190771:590296557", "คุ้ยหาในเมือก" },
        objective = { "109:944704575:679078798", "ตัวเมือกตัวหนึ่งที่ Ironbeard's Tomb มีถุงของ Sida อยู่ จงเอามันคืนแล้วนำกลับไปให้นางที่ Menethil Harbor" },
        description = { "448:801981562:794769438", "ตอนข้าไปเยี่ยม Ironbeard's Tomb ประจำสัปดาห์ ก็ถูกตัวเมือกน่ากลัวที่มีเมือกหยดติ๋ง ๆ โจมตี! แน่นอนว่าข้าตกใจมาก\n\nข้าโยนถุงใส่มันตัวหนึ่ง แต่ไม่ได้ผลเลย! มันดูดถุงเข้าไปเฉย ๆ... ยังดีที่ทำให้ข้ามีเวลาหนี\n\nข่าวร้ายคือข้าจำเป็นต้องได้ของในถุงคืนจริง ๆ!\n\nข้าไม่รู้ว่าโยนถุงใส่ตัวไหน พวกมันหน้าตาเหมือนกันหมด! Ironbeard's Tomb อยู่ทางตะวันออกเฉียงเหนือ ใกล้ Dun Modr ขอบคุณมากนะ!" },
        progress = { "20:1142585351:677632199", "เจ้าพบถุงของข้าหรือยัง?" },
        completion = { "15:403356219:907429681 N 241:970426176:696418486", "โอ้ ขอบคุณ {name}! ข้ากลัวว่าจะไม่มีวันได้คืนแล้ว!\n\n<นางรีบเทของจากถุงที่เปื้อนเมือกลงพื้น แล้วโกยเก็บขึ้นมา>\n\nอืม ข้าไม่ค่อยได้ใช้สิ่งนี้แล้ว แต่ล้างมันเสียหน่อย เจ้าคงใช้ประโยชน์ได้แน่" },
        required = { [3349] = { "10:339017899:1237777304", "กระเป๋าของ Sida" } },
        steps = { { "10:339017899:1237777304", "กระเป๋าของ Sida" } },
    },
    [471] = { -- Apprentice's Duties
        title = { "19:449146122:1908466292", "หน้าที่ของเด็กฝึกงาน" },
        objective = { "84:1866916764:1397782509", "รวบรวม Giant Crocolisk Skin 6 ผืน แล้วนำไปให้ James Halloran ที่ Menethil Harbor" },
        description = { "431:759205647:1967526956", "ข้าส่งเด็กฝึกงานเข้าไปในบึงเพื่อถลกหนังจระเข้ยักษ์ชื่อดังของ Wetlands พอเขาไม่กลับมา ข้าก็ออกตามหา... เอาเป็นว่าภาพที่เห็นไม่น่าดูเลย\n\nหมอตำแยบอกว่าเขาอาจรอด แต่ระหว่างนี้ข้ายังต้องการหนังอยู่!\n\n...ถ้าเจ้าอยากฆ่าสัตว์ดุร้ายพวกนั้นเพิ่มอีกสักหน่อย ข้าก็ไม่ขัด หลังจากสิ่งที่มันทำ เจอพวกมันได้ทางเหนือตามชายฝั่ง เลยกระท่อมเมอร์ล็อกไป" },
        progress = { "105:1685392197:838071015 N 36:733012706:700628307", "เด็กฝึกงานเป็นเหมือนลูกชายข้า ชีวิตที่เหลือขาเพียงข้างเดียวคงลำบากมาก\n\nอา {name} เป็นอย่างไรบ้าง? ได้หนังมาให้ข้าหรือยัง?" },
        completion = { "325:1833176479:2096101269", "อืม... เจ้าไม่สนใจมาเป็นเด็กฝึกงานของข้าบ้างหรือ?\n\nฮ่า! ล้อเล่นน่า อย่างแรกเจ้าก็แก่เกินไปแล้ว อีกอย่าง ดูจากท่าทาง เจ้าคงมีความมุ่งหมายอื่นในชีวิต แต่หนังที่เจ้าหามานี่คุณภาพดีทีเดียว ข้าจะใช้มันให้คุ้มค่า" },
        required = { [3348] = { "20:1818286325:1576248286", "หนังครอโคลิสก์ยักษ์" } },
        steps = { { "20:1818286325:1576248286", "หนังครอโคลิสก์ยักษ์" } },
    },
    [484] = { -- Young Crocolisk Skins
        title = { "21:1683286849:2093344788", "หนังลูกจระเข้" },
        objective = { "69:1257862894:1074046366", "หา Young Crocolisk Skin 4 ผืนให้ James Halloran ที่ Menethil Harbor", amount = { "7:1046708115:223027223 W1 61:1102191637:381917496", "หา Young Crocolisk Skin {world1} ผืนให้ James Halloran ที่ Menethil Harbor" } },
        description = { "420:1302872870:419309146", "ข้าคือ James Halloran ช่างฟอกหนัง หนังจระเข้ฟอกของข้าเป็นที่ต้องการไปทั่ว มีเรือขนส่งจากที่นี่ไปท่าเรือทั่วโลก\n\nพบ Einar แล้วหรือ? เขาเป็นพรานคนหนึ่งที่นำหนังจระเข้มาให้ข้า\n\nตอนนี้ข้าขาดหนังนุ่ม ๆ จากพวกลูกจระเข้อยู่หน่อย\n\nเพราะหนังใกล้หมด ข้ายินดีจ่ายราคางามสำหรับหนังสักกอง เจ้าพบลูกจระเข้ได้ในบึงนอกเมืองนี่เอง", variants = { { "419:194469498:588617279", "ข้าคือ James Halloran ช่างฟอกหนัง หนังจระเข้ฟอกของข้าเป็นที่ต้องการไปทั่ว มีเรือขนส่งจากที่นี่ไปท่าเรือทั่วโลก\n\nพบ Einar แล้วหรือ? เขาเป็นพรานคนหนึ่งที่นำหนังจระเข้มาให้ข้า\n\nตอนนี้ข้าขาดหนังนุ่ม ๆ จากพวกลูกจระเข้อยู่หน่อย\n\nเพราะหนังใกล้หมด ข้ายินดีจ่ายราคางามสำหรับหนังสักกอง เจ้าพบลูกจระเข้ได้ในแหล่งน้ำนอกเมืองนี่เอง" } } },
        progress = { "N 30:1161229193:834257415", "{name} ใช่ไหม? ได้หนังมาให้ข้าหรือยัง?" },
        completion = { "28:299448053:1320023263 N 220:1519613689:880555041", "ทำได้ดี {name} หนังเหล่านี้คุณภาพยอดเยี่ยม ข้าต้องเริ่มฟอกให้เร็วที่สุด อ้อ แต่ก่อนจะลงมือ ยังมีงานอีกอย่างที่ข้าคิดว่าเจ้าจัดการให้ได้" },
        required = { [3397] = { "20:1418708261:786450956", "หนังครอโคลิสก์วัยอ่อน" } },
        steps = { { "20:1418708261:786450956", "หนังครอโคลิสก์วัยอ่อน" } },
    },
    [87288] = { -- Soft Saber Pelts
        title = { "16:2006379544:265401182", "หนังเสือเขี้ยวดาบเนื้อนุ่ม" },
        objective = { "40:1586989350:1470458873", "นำ Soft Nightsaber Pelt 6 ผืนไปให้ Aldria", amount = { "6:1273960851:929420321 W1 33:1319600365:1296154383", "นำ Soft Nightsaber Pelt {world1} ผืนไปให้ Aldria" } },
        description = { "474:1150305655:823139975", "สวัสดี นักเดินทาง! หวังว่าเจ้าจะชอบหมู่บ้านของเรา ข้าชอบ Dolanaar เพราะเป็นหมู่บ้านเล็ก ๆ เรียบง่าย และทุกคนเป็นมิตร\n\nข้าเป็นพ่อค้าในท้องถิ่น นำเครื่องมือและของกระจุกกระจิกสารพัดมาขาย ซึ่งอาจมีประโยชน์ต่อการเดินทางของเจ้า ถ้าสนใจแลกเปลี่ยนกัน ตอนนี้ข้าต้องการหนังเสือไนต์เซเบอร์อยู่ แม้สัตว์สง่างามเหล่านี้จะงดงาม แต่พวกที่อยู่แถวนี้ค่อนข้างดุร้าย จึงอย่ารู้สึกผิดนักหากต้องป้องกันตัว" },
        progress = { "51:1494570414:990806306", "ดีใจที่ได้พบเจ้าอีกครั้ง! มาค้าขายกันหรือ?" },
        completion = { "267:1638284781:1234664550", "โอ้ หนังพวกนี้ดีมาก น่าเสียดายที่ต้องใช้ความรุนแรงกับสัตว์สง่างามเช่นนั้น แต่การรักษาถนนให้ปลอดภัยก็สำคัญ และหนังเหล่านี้จะทำผ้าห่มกับผ้าคลุมไหล่ที่สวยงามได้\n\nนี่ ให้ข้ามอบของไว้เป็นที่ระลึกถึงพวกมัน ทั้งนุ่มและทนทานทีเดียว" },
        required = { [280087] = { "20:1400642909:687823488", "หนังไนต์เซเบอร์เนื้อนุ่ม" } },
        steps = { { "20:1400642909:687823488", "หนังไนต์เซเบอร์เนื้อนุ่ม" } },
    },
    [97236] = { -- Fang of Githyiss
        title = { "16:1445981060:544292129", "เขี้ยวของ Githyiss" },
        objective = { "88:1205646404:1390098328", "นำ Fang of Githyiss ไปให้คนที่สนใจศึกษาแมงมุมใน Aldrassil" },
        description = { "156:1651671522:910880293", "ตัวอย่างสดจากสัตว์ร้ายขนาดนี้เป็นของหายากทีเดียว บางทีคนใน Aldrassil ที่ศึกษาเรื่องแมงมุมอาจสนใจเขี้ยวนี้" },
        completion = { "91:740858732:298520824", "โอ้ โอ้ ข้าชอบเรื่องประหลาดใจเช่นนี้เหลือเกิน สหาย\n\nตัวอย่างนี้จะช่วยให้งานศึกษาของข้าก้าวหน้าได้แน่", variants = { { "33:1110077053:743305580 N 52:1923400644:487294852", "โอ้โฮ ข้าชอบเรื่องประหลาดใจแบบนี้จริง ๆ {name}\n\nตัวอย่างนี้จะช่วยให้งานศึกษาของข้าก้าวหน้าได้แน่" } } },
    },
    [97894] = { -- Business in Auberdine
        title = { "21:1709571604:568179233", "ธุระที่ Auberdine" },
        objective = { "148:1900762739:805085650", "ไปเยี่ยม Gorbold Steelhand ที่ Auberdine ใน Darkshore\n\nBorgus บอกว่ามีเรือที่ท่าใต้สุดของ Stormwind Harbor ซึ่งพาคุณไปที่นั่นได้", variants = { { "54:807053796:1385151936", "นั่งเรือไป Auberdine แล้วตามหา Gorbold Steelhand" } } },
        description = { "491:1098587993:1754974851", "ยินดีที่ได้รู้จัก! ข้าชื่อ Borgus จากตระกูล Steelhand อันเลื่องชื่อ เจ้าพึ่งคนตระกูล Steelhand ให้ค้าขายอย่างยุติธรรมได้เสมอ!\n\nไม่กี่สัปดาห์ก่อน Gorbold พี่น้องข้าไปทำงานกับร้านค้าที่ Auberdine ขอบอกเลยว่าขายเสบียงให้เรือที่นั่นได้เงินดีนัก! เจ้าหมอนั่นโชคดีจริง ๆ\n\nข้าไม่ได้ข่าวจากเขาตั้งแต่นั้น ถ้าเจ้าจะไปทางนั้น ช่วยแวะดูเขาทีได้ไหม?\n\nมีเรือลำใหม่ในท่า พาเจ้าไปถึงที่นั่นได้ตรง ๆ ไปที่ท่าใต้สุด หาเจอแน่นอน!" },
        completion = { "202:1853486201:1884777843", "ตา Borgy ส่งเจ้ามาหรือ? คอยเป็นห่วงข้าอยู่เรื่อย\n\nแถวนี้ต้องการคนช่วยเพิ่มจริง ๆ หลังโศกนาฏกรรมเมื่อไม่นานมานี้ ธุรกิจแทบหยุดชะงัก ข้าว่าเจ้าช่วยให้ทุกอย่างกลับมาเข้าที่ได้" },
        objectiveLabels = {
            event = { ["Take the boat to Auberdine and find Gorbold Steelhand."] = "ขึ้นเรือไป Auberdine แล้วไปหา Gorbold Steelhand" },
        },
    },
    [97926] = { -- Making Do
        title = { "9:2011814372:1951966797", "ทำเท่าที่ทำได้" },
        objective = { "72:1138580153:626960712", "นำ Alexston's Reply ไปให้ Thundris Windweaver ที่ Auberdine ใน Darkshore" },
        description = { "354:1692809734:1771959491", "ข้าก็อยากให้ช่วยได้ง่ายเช่นนั้น นักผจญภัย อยากจริง ๆ\n\nหากเจ้าเลือกอยู่ในดินแดนของเรานานขึ้น เจ้าจะพบว่ามีผู้คนขาดแคลนมากมาย ท้องพระคลัง Stormwind ไม่มั่งคั่งเหมือนก่อน และส่วนที่เหลือก็ต้องแบ่งไปจนแทบไม่พอ\n\nเมื่อพบผู้อาวุโสอีกครั้ง ฝากคำตอบนี้ให้เขาด้วย มันคงไม่ใช่สิ่งที่เขาหวัง แต่ตอนนี้ข้าให้ได้เพียงเท่านี้", variants = { { "33:1751296992:657004958 C 311:4719496:346082840", "ข้าก็อยากให้ช่วยได้ง่ายเช่นนั้น {class} อยากจริง ๆ\n\nหากเจ้าเลือกอยู่ในดินแดนของเรานานขึ้น เจ้าจะพบว่ามีผู้คนขาดแคลนมากมาย ท้องพระคลัง Stormwind ไม่มั่งคั่งเหมือนก่อน และส่วนที่เหลือก็ต้องแบ่งไปจนแทบไม่พอ\n\nเมื่อพบผู้อาวุโสอีกครั้ง ฝากคำตอบนี้ให้เขาด้วย มันคงไม่ใช่สิ่งที่เขาหวัง แต่ตอนนี้ข้าให้ได้เพียงเท่านี้" } } },
        progress = { "50:1266829815:274066206", "เจ้ากลับมาแล้ว มีข่าวอะไรจาก Stormwind บ้าง?" },
        completion = { "167:1092826271:526157794", "เป็นข่าวเศร้าจริง ๆ ถึงอย่างนั้น ข้าก็ขอบคุณที่เจ้าเดินทางไปให้\n\nเมื่อทั้ง Stormwind และ Darnassus ไม่มาช่วยเรา ดูเหมือนชะตาของ Auberdine จะอยู่ในมือพวกเราเอง" },
        required = { [279048] = { "16:1182582456:143252647", "คำตอบของ Alexston" } },
        steps = { { "16:1182582456:143252647", "คำตอบของ Alexston" } },
    },
    [97977] = { -- Nature's Call
        title = { "13:1453708513:298859626", "เสียงเรียกของธรรมชาติ" },
        objective = { "57:1362843711:1675774685", "รวบรวม Gnarlpine Totem 4 ชิ้น แล้วนำไปให้ Tarindrella", amount = { "8:1089852795:1107240600 W1 48:2001832076:179089314", "รวบรวม Gnarlpine Totem {world1} ชิ้น แล้วนำไปให้ Tarindrella" } },
        description = { "374:1285240564:1884995593", "พวกเฟอร์โบลก์ Gnarlpine ไม่น่าหันมาต่อต้านพันธมิตรเก่าแก่ได้ง่าย ๆ เช่นนี้ เราต้องรู้ให้มากขึ้นว่าพวกเขาประสบอะไร\n\nค้นหาโทเท็มในบ้านที่ถูกทิ้งร้าง หากยังมีชิ้นใดรอดจากความโกลาหลตอนอพยพ รอยสลักอาจบอกเราได้ว่าเกิดอะไรขึ้นที่นี่\n\nค่ายของพวกเขาอยู่ตามขอบตะวันตกของหุบป่า แต่พวกเกรลล์กับเกรลล์คินอาจทำโทเท็มกระจัดกระจายออกไป" },
        progress = { "120:1458414293:694009797", "ไม่ต้องสนใจโทเท็มขนาดใหญ่ที่อาจพบหรอก ต่อให้เจ้าหาทางขนมันมาได้ ข้าก็ไม่รู้จะเอาไปทำอะไร!" },
        completion = { { "406:1931509212:256214235", "399:882945286:1768298460 N 1:46:46", "399:882945286:1768298460 C 1:46:46", "399:882945286:1768298460 R 1:46:46" }, "โอ้ แย่กว่าที่ข้าคิดเสียอีก\n\nรอยสลักเหล่านี้บอกว่าพวก Gnarlpine เริ่มฝันร้ายว่าถูกเงามหึมาบางอย่างกวาดล้าง ไม่นานความกลัวก็กลายเป็นความโกรธ และเงานั้นก็กลายเป็นสหายเอลฟ์ที่เคยคบหา การรับรู้ว่าจิตใจของตนกำลังหลุดลอยไปช่าง...\n\nความหวังเดียวของเราคือสิ่งนี้อาจช่วยให้เข้าใจสิ่งที่เกิดขึ้นบน Teldrassil มากขึ้น ขอบคุณที่ช่วยเหลือ สหาย" },
        required = { [279082] = { "15:760586964:258088079", "โทเท็ม Gnarlpine" } },
        steps = { { "15:760586964:258088079", "โทเท็ม Gnarlpine" } },
    },
    [98013] = { -- Swelling Forces
        title = { "15:410511697:1255888233", "กำลังพลที่เพิ่มพูน" },
        objective = { "126:376085620:1912314319", "กำจัด Stormscale Myrmidon 12 ตน, Stormscale Sorceress 8 ตน และ Stormscale Warrior 6 ตนให้ Arbal ที่ Grove of the Ancients", amount = { "10:1223070807:902181099 W1 23:2099017419:716658601 W2 29:100843472:2130705637 W3 60:900315623:1204692106", "กำจัด Stormscale Myrmidon {world1} ตน, Stormscale Sorceress {world2} ตน และ Stormscale Warrior {world3} ตนให้ Arbal ที่ Grove of the Ancients" } },
        description = { "435:532514890:343714778", "เตรียมใจให้พร้อมก่อนเข้าไปในซากเมือง เจ้าผู้เยาว์วัย... พวกมันจะไม่ปล่อยให้เจ้าผ่านไปง่าย ๆ\n\nไฮบอร์นต้องสาปมากมาย ซึ่งบัดนี้เรียกกันว่านากา เพ่นพ่านอยู่ในเมืองที่เคยยิ่งใหญ่ จงไปทางตะวันออกเฉียงเหนือและกำจัดพวกมันออกจากดินแดนนี้\n\nสิ่งที่พวกมันเคยเป็น... ไม่เหลืออีกแล้ว หากช่วย Twilight's Hammer พวกมันก็มีแต่จะนำความเจ็บปวดมาให้ผืนป่าที่เคยคุ้มครองตน\n\nพวกมันต้องการสงคราม นักผจญภัย และสงคราม... คือสิ่งที่เราจะมอบให้", variants = { { "394:629524522:65140052 C 31:660595931:1293896422", "เตรียมใจให้พร้อมก่อนเข้าไปในซากเมือง เจ้าผู้เยาว์วัย... พวกมันจะไม่ปล่อยให้เจ้าผ่านไปง่าย ๆ\n\nไฮบอร์นต้องสาปมากมาย ซึ่งบัดนี้เรียกกันว่านากา เพ่นพ่านอยู่ในเมืองที่เคยยิ่งใหญ่ จงไปทางตะวันออกเฉียงเหนือและกำจัดพวกมันออกจากดินแดนนี้\n\nสิ่งที่พวกมันเคยเป็น... ไม่เหลืออีกแล้ว หากช่วย Twilight's Hammer พวกมันก็มีแต่จะนำความเจ็บปวดมาให้ผืนป่าที่เคยคุ้มครองตน\n\nพวกมันต้องการสงคราม {class} และสงคราม... คือสิ่งที่เราจะมอบให้" } } },
        completion = { "93:348460652:1617939196", "อย่ากังวลไป เจ้าผู้เยาว์วัย การปล้นทำลายบ้านของตัวเองเพื่อเจ้านายแห่งความมืดบางตน...\n\nเป็นสิ่งที่ให้อภัยไม่ได้" },
        progress = { "83:1595813085:1387329667", "ผืนดินแห่งนี้เก่าแก่จนยากจะนับอายุ และผ่านความขัดแย้งมามากแล้ว สกายบอร์นเอ๋ย", variants = { { "84:398385704:861141070", "ผืนดินแห่งนี้เก่าแก่จนยากจะนับอายุ และผ่านความขัดแย้งมามากแล้ว ไนต์เอลฟ์เอ๋ย" }, { "78:517875173:716638416", "ผืนดินแห่งนี้เก่าแก่จนยากจะนับอายุ และผ่านความขัดแย้งมามากแล้ว เอลฟ์เอ๋ย" } } },
        objectiveLabels = {
            monster = { ["Stormscale Myrmidon slain"] = "ปราบ ทหารชั้นยอด Stormscale", ["Stormscale Sorceress slain"] = "ปราบ แม่มด Stormscale", ["Stormscale Warrior slain"] = "ปราบ นักรบ Stormscale" },
        },
    },
    [98025] = { -- WANTED: Jai'vhanel
        title = { "18:89347881:1526640442", "ประกาศจับ: Jai'vhanel" },
        objective = { "226:1232227334:1230048259", "ค้นหาและฆ่านกฮูกชื่อ Jai'vhanel แล้วเก็บขนของมันมา ข้อมูลล่าสุดพบนกฮูกสีดำตัวนี้ทางเหนือของซาก Ameth'Aran ใกล้เชิงเขา รายงานการตายของ Jai'vhanel ให้ Sentinel Glynda Nal'Shea ที่ Auberdine" },
        description = { "486:1391582377:1355582315", "ประกาศ!\n\nมีรางวัลสำหรับผู้สังหารนกฮูก \"Jai'vhanel\" หรือที่รู้จักในชื่อ \"Swordfeather\"\n\nน่าเสียดายที่นกฮูกตัวนี้เสียสติและเริ่มโจมตีนักเดินทางบนถนนใกล้ Auberdine\n\nข้อมูลล่าสุดพบ Jai'vhanel ทางเหนือของซาก Ameth'Aran ใกล้เชิงเขา นำขนสีดำสนิทของมันกลับมาเป็นหลักฐานว่ามันตายแล้ว\n\nขอรับรางวัลค่าหัวได้จาก Sentinel Glynda Nal'Shea ที่ Auberdine\n\nสภาหมู่บ้าน Auberdine", variants = { { "485:946866903:1456655691", "ประกาศ!\n\nมีรางวัลสำหรับผู้สังหารนกฮูก \"Jai'vhanel\" หรือที่รู้จักในชื่อ \"Swordfeather\"\n\nน่าเสียดายที่นกฮูกตัวนี้เสียสติและเริ่มโจมตีนักเดินทางบนถนนใกล้ Auberdine\n\nข้อมูลล่าสุดพบ Jai'vhanel ทางเหนือของซาก Ameth'Aran ใกล้เชิงเขา นำขนสีดำสนิทของมันกลับมาเป็นหลักฐานว่ามันตายแล้ว\n\nขอรับรางวัลค่าหัวได้จาก Sentinel Glynda Nal'Shea ที่ Auberdine\n\nสภาหมู่บ้าน Auberdine" } } },
        progress = { { "133:1166543826:424460361", "11:927657569:725753248 N 112:1851706252:1352479256", "11:927657569:725753248 C 112:1851706252:1352479256", "11:927657569:725753248 R 112:1851706252:1352479256" }, "สวัสดี นักผจญภัย วันนี้เหล่า Sentinel ช่วยอะไรเจ้าได้บ้าง? หรือเจ้ามาสอบถามเรื่องค่าหัว Jai'vhanel?", variants = { { "10:1724938855:1235015449 C 112:1851706252:1352479256", "สวัสดี {class} วันนี้เหล่า Sentinel ช่วยอะไรเจ้าได้บ้าง? หรือเจ้ามาสอบถามเรื่องค่าหัว Jai'vhanel?" } } },
        completion = { { "364:1191464818:1846698812", "298:247871301:1123444704 N 56:1522982129:559653854", "298:247871301:1123444704 C 56:1522982129:559653854", "298:247871301:1123444704 R 56:1522982129:559653854" }, "ดีที่รู้ว่าจัดการปัญหานั้นแล้ว แต่ข้าเสียใจที่เราหาทางอื่นไม่ได้ Jai'vhanel เป็นเหมือนผู้พิทักษ์บริเวณนี้มานาน ข้าไม่แน่ใจว่าอะไรทำให้มันเสียสติ\n\nอย่างไรก็ตาม ขอบคุณที่ช่วยในวันนี้ นักผจญภัย ถนนสู่ Auberdine ปลอดภัยสำหรับการเดินทางอีกครั้งแล้ว", variants = { { "297:348136685:675634143 C 56:1522982129:559653854", "ดีที่รู้ว่าจัดการปัญหานั้นแล้ว แต่ข้าเสียใจที่เราหาทางอื่นไม่ได้ Jai'vhanel เป็นเหมือนผู้พิทักษ์บริเวณนี้มานาน ข้าไม่แน่ใจว่าอะไรทำให้มันเสียสติ\n\nอย่างไรก็ตาม ขอบคุณที่ช่วยในวันนี้ {class} ถนนสู่ Auberdine ปลอดภัยสำหรับการเดินทางอีกครั้งแล้ว" } } },
        required = { [281038] = { "21:1170736663:1503605619", "ขนนกของ Jai'vhanel" } },
        steps = { { "21:1170736663:1503605619", "ขนนกของ Jai'vhanel" } },
    },
    [98042] = { -- It's All Fun and Games Until...
        title = { "31:1607012476:1396858375", "สนุกกันอยู่ดี ๆ จนกระทั่ง..." },
        objective = { "147:1973862244:279331426", "หา Peerless Eye จาก Twilight Disciple หรือ Twilight Thug ที่ Master's Glaive ใน Darkshore แล้วหาคนใน Auberdine ที่ยอมรับมันไป" },
        description = { "181:1688238952:1066503429", "ขณะคุณฉีกหน้ากระดาษออกจาก Twilight Tome เสียงอันเป็นลางร้ายก็หลั่งไหลเข้ามาในใจโดยไม่ได้รับเชิญ\n\nพวกเขาล้มเหลวแล้ว\n\nเจ้าจะถูกลืม\n\nพวกเขาจะสูญเสียดวงตาที่ได้มา", variants = { { "183:1002230822:1533250387", "<ขณะคุณฉีกหน้ากระดาษออกจาก Twilight Tome เสียงอันเป็นลางร้ายก็หลั่งไหลเข้ามาในใจโดยไม่ได้รับเชิญ>\n\nพวกเขาล้มเหลวแล้ว\n\nเจ้าจะถูกลืม\n\nพวกเขาจะสูญเสียดวงตาที่ได้มา" } } },
        progress = { "34:1541634007:1822013531", "เจ้าดูไม่สบายใจ ข้าฟังอยู่" },
        completion = { "81:1939731466:165801724 C 82:929267710:365054873", "<Thundris เงียบไปพักใหญ่>\n\nสิ่งนี้มีร่องรอยของความชั่วร้ายโบราณ {class} ข้าจะส่งมันไป Darnassus ทันทีเพื่อตรวจสอบให้ละเอียดขึ้น\n\nAnde'thoras-ethil." },
        required = { [279279] = { "12:754060126:1183922745", "ดวงตาไร้เทียมทาน" } },
        steps = { { "12:754060126:1183922745", "ดวงตาไร้เทียมทาน" } },
    },
    [98067] = { -- Eyes of the Sentinels
        title = { "21:941326414:1743997364", "ดวงตาของเหล่า Sentinel" },
        objective = { "199:978569694:2071537319", "วาง Sentinel Owl ที่ทางเข้าส่วนลึกของ Cenarion Hold, Darnassus Bank, โรงแรม Craftsman's Terrace และประตูเมือง ให้ Sentinel Dalia Sunblade ที่ Temple of the Moon ใน Darnassus" },
        description = { "487:1847231971:792646844", "นายพล Feathermoon ดูแลให้ Sentinel ทุกคนมีเวลาสวดอ้อนวอนต่อ Elune นักล่าที่แท้จริงไม่ได้ใช้เพียงคมดาบ แต่ใช้พรจากเทพีเพื่อเอาชนะศัตรูด้วย\n\nเจ้าช่วยงานประจำวันของข้าได้ วางยามเฝ้ารอบเมือง เริ่มจากอุโมงค์ที่นำลงไปใต้ Cenarion Hold ทางเหนือ ธนาคารกลางเมือง โรงแรมใน Craftsman's Terrace ทางตะวันออกเฉียงเหนือ และประตูเมือง ถามยามได้ พวกเขาช่วยบอกทางได้\n\nมีบางอย่างผิดปกติใน Teldrassil เราต้องเฝ้าระวังอยู่เสมอ" },
        completion = { "115:1242630687:1557862815", "ขอบคุณที่ช่วย แม้พิธีประจำวันจะทำให้ข้าสงบใจ แต่การมีเวลาหยุดไตร่ตรองบ้างก็ดีเหมือนกัน" },
        progress = { "91:58717393:1764062426", "เราต้องเฝ้าระวังไว้เสมอ แม้ Darnassus จะมีการคุ้มกันแน่นหนา แต่ศัตรูของเรามีอยู่ทุกหนแห่ง" },
        steps = { { "29:1186090736:1894100860", "ทางเข้าสู่ส่วนลึกของ Cenarion Hold" }, { "14:1099583467:179849096", "ธนาคาร Darnassus" }, { "23:1219464295:1208116879", "โรงเตี๊ยมใน Craftsman's Terrace" }, { "9:1224530835:594593421", "ประตูเมือง" } },
    },
    [98391] = { -- The Sisterhood of Elune
        title = { "23:817688828:307488822", "ภคินีแห่ง Elune" },
        objective = { "37:1333628987:1926161369", "คุยกับ Sister Aquinne ใน Darnassus" },
        description = { "440:407537481:1657495679", "ขอพรจงมีแด่เจ้า นักผจญภัย ภคินีแห่ง Elune เป็นเสาหลักของสังคมคัลโดไรมาหลายพันปี\n\nตั้งแต่ก่อนมหาแผ่นดินแยก ก่อนสงครามแห่งบรรพกาล และตลอดการเฝ้าระวังอันยาวนาน เราชี้นำและเยียวยาประชาชนผ่านความมืดมิด นี่คือหน้าที่ของเรา และเป็นพระประสงค์ของพระแม่จันทราผู้ไร้เทียมทาน\n\nบัดนี้เราต้องการความช่วยเหลือจากเจ้าในเรื่องสำคัญยิ่ง Sister Aquinne กำลังรอเจ้าที่ Darnassus", variants = { { "18:1850507810:673804469 C 412:1222540361:1643772946", "ขอพรจงมีแด่เจ้า {class} ภคินีแห่ง Elune เป็นเสาหลักของสังคมคัลโดไรมาหลายพันปี\n\nตั้งแต่ก่อนมหาแผ่นดินแยก ก่อนสงครามแห่งบรรพกาล และตลอดการเฝ้าระวังอันยาวนาน เราชี้นำและเยียวยาประชาชนผ่านความมืดมิด นี่คือหน้าที่ของเรา และเป็นพระประสงค์ของพระแม่จันทราผู้ไร้เทียมทาน\n\nบัดนี้เราต้องการความช่วยเหลือจากเจ้าในเรื่องสำคัญยิ่ง Sister Aquinne กำลังรอเจ้าที่ Darnassus" }, { "436:1358566780:1195651536", "ขอพรจงมีแด่เจ้า ภคินี ภคินีแห่ง Elune ของเราเป็นเสาหลักของสังคมคัลโดไรมาหลายพันปี\n\nตั้งแต่ก่อนมหาแผ่นดินแยก ก่อนสงครามแห่งบรรพกาล และตลอดการเฝ้าระวังอันยาวนาน เราชี้นำและเยียวยาประชาชนผ่านความมืดมิด นี่คือหน้าที่ของเรา และเป็นพระประสงค์ของพระแม่จันทราผู้ไร้เทียมทาน\n\nบัดนี้เราต้องการความช่วยเหลือจากเจ้าในเรื่องสำคัญยิ่ง Sister Aquinne กำลังรอเจ้าที่ Darnassus", variants = { { "443:1192985595:1587138524", "ขอพรจงมีแด่เจ้า เพื่อนนักบวช ภคินีแห่ง Elune ของเราเป็นเสาหลักของสังคมคัลโดไรมาหลายพันปี\n\nตั้งแต่ก่อนมหาแผ่นดินแยก ก่อนสงครามแห่งบรรพกาล และตลอดการเฝ้าระวังอันยาวนาน เราชี้นำและเยียวยาประชาชนผ่านความมืดมิด นี่คือหน้าที่ของเรา และเป็นพระประสงค์ของพระแม่จันทราผู้ไร้เทียมทาน\n\nบัดนี้เราต้องการความช่วยเหลือจากเจ้าในเรื่องสำคัญยิ่ง Sister Aquinne กำลังรอเจ้าที่ Darnassus" } } } } },
        completion = { "67:1874711290:1145016933", "ข้าดีใจที่เจ้ามาถึงเร็ว ภคินีต้องการความช่วยเหลือจากเจ้า" },
    },
    [98392] = { -- Darkness in the Glade
        title = { "21:1576536633:2020279236", "ความมืดในหุบป่า" },
        objective = { "144:1261264806:399653240", "รวบรวม Hatescreech's Amulet, Windmistress Gaedress' Amulet และ Witchmother Arysa's Amulet ให้ Sentinel Arynia Cloudsbreak ที่ Oracle Glade" },
        description = { "343:536683091:1955346313", "เข็มขัดพวกนี้... มองหนังให้ดี สหาย เจ้าเห็นความแปดเปื้อนที่แทรกอยู่ตามเส้นใยไหม?\n\nข้าสงสัยว่ามันมาจากไหน แต่เราต้องมีหลักฐานเพิ่มจึงจะแน่ใจ\n\nกลับไปยังรังฮาร์ปีทางตะวันตกและกำจัดผู้นำของพวกมัน หากสร้อยของพวกมันมีความมืดเช่นเดียวกับเข็มขัดเหล่านี้ เราก็จะได้คำตอบ", variants = { { "44:593791181:1124552988 N 293:1831870082:633834042", "เข็มขัดพวกนี้... มองหนังให้ดี {name} เจ้าเห็นความแปดเปื้อนที่แทรกอยู่ตามเส้นใยไหม?\n\nข้าสงสัยว่ามันมาจากไหน แต่เราต้องมีหลักฐานเพิ่มจึงจะแน่ใจ\n\nกลับไปยังรังฮาร์ปีทางตะวันตกและกำจัดผู้นำของพวกมัน หากสร้อยของพวกมันมีความมืดเช่นเดียวกับเข็มขัดเหล่านี้ เราก็จะได้คำตอบ" } } },
        progress = { "55:1407675904:1871540078", "เจ้าแย่งเครื่องรางจากผู้นำฮาร์ปีมาได้แล้วหรือยัง?" },
        completion = { "298:1384517083:1001990493", "<Arynia ตรวจดูเครื่องราง>\n\nเห็นริ้วสีเขียวชวนสะอิดสะเอียนที่หมุนวนอยู่ในอัญมณีไหม? นี่เป็นผลจากมลทินของมอสเฟลจริง ๆ\n\nข้าได้ยินรายงานคล้ายกันจาก Shadowglen และที่อื่นตามกิ่งก้านของมหาพฤกษา ว่าสารนี้กำลังทำให้ถิ่นอาศัยของเราหันมาทำร้ายเราเอง\n\nข้าจะแจ้งผู้บังคับบัญชาทันที" },
        required = { [280831] = { "20:1886793262:2146482573", "เครื่องรางของ Hatescreech" }, [280832] = { "29:1440184113:34689372", "เครื่องรางของ Windmistress Gaedress" }, [280834] = { "26:1124815762:1667581702", "เครื่องรางของ Witchmother Arysa" } },
        steps = { { "20:1886793262:2146482573", "เครื่องรางของ Hatescreech" }, { "29:1440184113:34689372", "เครื่องรางของ Windmistress Gaedress" }, { "26:1124815762:1667581702", "เครื่องรางของ Witchmother Arysa" } },
    },
    [98398] = { -- The Oracle Tree
        title = { "15:1078273912:1479779824", "ต้นไม้พยากรณ์" },
        objective = { "56:2110446790:1311534957", "หา Oracle Tree Bark ที่อยู่ใกล้ ๆ เพื่อรับสารจากต้นไม้" },
        description = { "352:1113967559:588849197", "ข้าประทับใจสิ่งที่เจ้าทำได้มากมายในเวลาสั้น ๆ สหาย ข้าอยากขอให้เจ้าอยู่ช่วยงานที่นี่ต่อ... แต่ในใจข้ารู้ว่ามีภารกิจที่ยิ่งใหญ่กว่ารอเจ้าอยู่\n\nข้าสังเกตว่าต้นไม้พยากรณ์เพิ่งผลัดเปลือกออกมาชิ้นหนึ่ง ไม่ต้องสงสัยเลยว่ามันมีงานที่ต้องการให้ทำ เจ้าควรไปพูดกับมัน", variants = { { "70:1105851869:52918784 N 276:1743171412:1271981761", "ข้าประทับใจสิ่งที่เจ้าทำได้มากมายในเวลาสั้น ๆ {name} ข้าอยากขอให้เจ้าอยู่ช่วยงานที่นี่ต่อ... แต่ในใจข้ารู้ว่ามีภารกิจที่ยิ่งใหญ่กว่ารอเจ้าอยู่\n\nข้าสังเกตว่าต้นไม้พยากรณ์เพิ่งผลัดเปลือกออกมาชิ้นหนึ่ง ไม่ต้องสงสัยเลยว่ามันมีงานที่ต้องการให้ทำ เจ้าควรไปพูดกับมัน" } } },
        completion = { "141:850390779:1183412498", "ขณะคุณสำรวจเปลือกไม้ที่ร่วงอยู่ เสียงหนึ่งก็เข้ามาในใจ เสียงนั้นสงบและอ่อนโยน โอบผ่านคุณราวสายลมแผ่วเบาที่พัดผ่านใบไม้" },
    },
    [99046] = { -- The Lost Runner
        title = { "15:1981347848:1301229747", "ผู้ส่งสารที่หายไป" },
        objective = { "78:177328372:324994543", "ตามหา Sentinel Eralya Leafshadow บนถนนที่มุ่งสู่ Oracle Glade" },
        description = { "499:2103652502:1623099554", "สภาแห่งพงไพรส่ง Sentinel กลุ่มเล็ก ๆ ไปยังต้นไม้พยากรณ์เมื่อระยะหนึ่งมาแล้ว ต้นไม้ส่งสารถึงเหล่าผู้อาวุโส และเป็นหน้าที่ของเราที่ต้องนำสารไป Darnassus อย่างปลอดภัย\n\nข้าได้ข่าวว่าผู้ส่งสารคนล่าสุดยังไปไม่ถึง แม้ต้นไม้จะส่งสารไม่สม่ำเสมอ แต่ครั้งนี้นานผิดปกติ\n\nโปรดเดินตามถนนทางตะวันตกไปยัง Oracle Glade แล้วดูว่านางเป็นอย่างไร เวรนี้น่าจะเป็นของ Eralya Leafshadow ซึ่งยังอยู่ระหว่างฝึกฝน ขอ Elune นำทางเจ้า" },
        completion = { "44:2066415195:1118076854", "พระเมตตาแห่ง Elune... ข้าจะไม่ตาย... อย่างเดียวดาย...", variants = { { "44:529606469:982036048", "พระเมตตาแห่ง Elune... ข้าจะไม่ตาย... อย่างเดียวดาย..." } } },
    },
    [99047] = { -- Not Dead Yet
        title = { "12:332223981:430916432", "ยังไม่สิ้นลม" },
        objective = { "65:1650618050:813882816", "ขอความช่วยเหลือจาก Byancie ที่ Dolanaar ให้ Sentinel Eralya Leafshadow", variants = { { "65:1355639419:929201586", "ขอความช่วยเหลือจาก Byancie ที่ Dolanaar ให้ Sentinel Eralya Leafshadow" } } },
        description = { "228:1847340551:740839322", "พี่น้องข้ากับข้า... ถูกส่งไป... ต้นไม้พยากรณ์...\n\nต้นไม้... สาร ข้า... ฮาร์ปี... เต็มไปหมด...\n\n<Eralya ไอเป็นเลือด หน้าบิดเบี้ยวด้วยความเจ็บปวด>\n\nข้าอาจเหลือเวลาไม่มาก... ไม่มีใครมา ได้โปรด... Byancie... ที่ Dolanaar..." },
        completion = { "209:1540676999:179579403", "พวกฮาร์ปีติดความชั่วร้ายแบบเดียวกับที่ปรากฏไปทั่วป่า ข้ามั่นใจว่าสิ่งนั้นทำให้ Sentinel Eralya เจ็บป่วยเช่นกัน\n\nเราต้องรีบ อีกไม่นานนางคงทนพิษบาดแผลไม่ไหว" },
    },
    [99050] = { -- The Great Tree Provides
        title = { "23:855226555:1469017438", "ต้นไม้ใหญ่คอยเกื้อกูล" },
        objective = { "99:154203800:2073818689", "รวบรวม Dewy Lasher Frond 6 ชิ้น, Empty Vial และ Refreshing Spring Water ให้ Byancie ที่ Dolanaar", amount = { "8:1089852795:1107240600 W1 90:837971284:1047139897", "รวบรวม Dewy Lasher Frond {world1} ชิ้น, Empty Vial และ Refreshing Spring Water ให้ Byancie ที่ Dolanaar" } },
        description = { "493:1745189147:845710744", "ข้าต้องให้เจ้าช่วยหาส่วนผสม เพื่อหยุดอาการป่วยไว้ให้นานพอที่ Eralya จะกลับมารักษาต่อที่นี่ได้\n\nยังดีที่บ้านอันมีชีวิตของเรายังอุดมสมบูรณ์ และจะมอบสิ่งที่จำเป็นในยามขัดสน\n\nส่วนผสมหลักคือใบ Dewy Lasher พบได้รอบ Lake Al'Ameth ทางใต้ของที่นี่ หรือแถว Wellspring Lake และแม่น้ำทางตะวันตกเฉียงเหนือ\n\nนอกจากนี้ ข้าต้องการขวดเปล่ากับน้ำพุ ทั้งสองอย่างซื้อหรือแลกได้ในหมู่บ้าน" },
        progress = { "61:1981398444:714913005", "ได้ส่วนผสมมาหรือยัง? ข้ากลัวว่า Eralya จะเหลือเวลาไม่มาก" },
        completion = { "144:1416698935:1287867492", "ขอบคุณที่ช่วย โปรดรับเงินนี้ไว้ช่วยออกค่าขวดกับน้ำ\n\nเอาล่ะ ข้าจะปรุงยาแล้ว คงใช้เวลาไม่นาน" },
        required = { [159] = { "23:710293457:1691572125", "น้ำจากตาน้ำชื่นใจ" }, [286017] = { "17:480200427:1283055030", "ใบ Lasher ชุ่มน้ำค้าง" }, [3371] = { "10:2101862828:290474430", "ขวดเปล่า" } },
        steps = { { "23:710293457:1691572125", "น้ำจากตาน้ำชื่นใจ" }, { "17:480200427:1283055030", "ใบ Lasher ชุ่มน้ำค้าง" }, { "10:2101862828:290474430", "ขวดเปล่า" } },
    },
    [99053] = { -- Escaping Ban'ethil
        title = { "18:457010926:1901150926", "หนีจาก Ban'ethil" },
        objective = { "123:571603838:1581709987", "ช่วย Sentinel Lynessa Duskblossom หนีออกจาก Ban'ethil Barrow Den แล้วรายงานว่านางปลอดภัยให้ Sentinel Kyra Starsong ที่ Dolanaar", variants = { { "126:79172299:1649747212", "ช่วย Sentinel Lynessa Duskblossom หนีออกจาก Ban'ethil Barrow Den แล้วรายงานว่านางปลอดภัยให้ Sentinel Kyra Starsong ที่ Dolanaar" } } },
        description = { "409:1649514117:701788218", "คำอธิษฐานของข้าเป็นจริงแล้ว! ข้าขอบคุณที่เจ้าฝ่าศัตรูลงมาถึงนี่\n\nต้นไม้พยากรณ์ส่งข้ามาส่งสารให้เหล่าดรูอิดที่หลับใหลอยู่ แต่กลับพบว่าที่นี่ถูกเฟอร์โบลก์ยึดครองจนหมด! พวกมันซุ่มโจมตีก่อนข้าจะหันกลับ และลากข้าลงมาข้างล่าง... ข้ากลัวว่าจะกลายเป็นอาหารมื้อต่อไปของมัน\n\nข้าไม่รู้ว่าเจ้าคิดอย่างไร แต่ข้าเกลียดที่นี่ ใต้ดินไม่ใช่ที่ของชาวคัลโดไร" },
        completion = { "208:1152722066:904421717", "ขอบคุณ Elune ที่เจ้ามาช่วย Lynessa ให้รอดจากชะตาอันมืดมนกับพวก Gnarlpine นางเป็นคนเก่งที่สุดคนหนึ่งของเรา และเป็นเพื่อนของข้าด้วย\n\nโปรดรับสิ่งนี้แทนคำขอบคุณ หวังว่ามันจะช่วยให้เจ้าปกป้องชาวคัลโดไรได้ดี" },
        objectiveLabels = {
            event = { ["Escort Lynessa Duskblossom out of Ban'ethil"] = "คุ้มกัน Lynessa Duskblossom ออกจาก Ban'ethil" },
        },
    },
    [99073] = { -- Easing Suffering
        title = { "16:164716799:548678522", "บรรเทาความทุกข์ทรมาน" },
        objective = { "86:2072773479:462254035", "นำ Lashwater Salve ไปให้ Sentinel Eralya Leafshadow บนถนนสู่ Oracle Tree" },
        description = { "231:204745626:1261724380", "ยาพร้อมแล้ว รีบนำไปให้ Eralya\n\nข้าไม่รู้ว่ามันจะรักษานางได้จริงหรือไม่ ความเน่าเปื่อยลุกลามรวดเร็ว และรุนแรงขึ้นยิ่งแพร่กระจาย\n\nอย่างน้อยมันก็ช่วยบรรเทาความทุกข์ทรมานของนางได้ เพียงเท่านี้ก็คุ้มค่าที่เจ้าจะรีบไปแล้ว" },
        progress = { "82:1341952022:2078350528", "Eralya ไม่ตอบด้วยคำพูดอีกแล้ว มีเพียงลมหายใจออกแผ่วเบาครืดคราดที่ยืนยันว่านางยังมีชีวิต", variants = { { "84:1390335349:989956358", "<Eralya ไม่ตอบเป็นคำพูดอีกแล้ว มีเพียงเสียงหายใจออกแผ่วเบาและครืดคราดที่ยืนยันว่านางยังมีชีวิต>" } } },
        completion = { "110:357035940:7505270", "ลมหายใจของ Eralya สงบลงอย่างรวดเร็วเมื่อคุณช่วยให้นางกินยา แม้นางอาจไม่รอด แต่ก็สงบขึ้นบ้างแล้ว", variants = { { "112:885436906:1419150312", "<ลมหายใจของ Eralya สงบลงอย่างรวดเร็วเมื่อเจ้าช่วยให้นางกลืนยา นางอาจไม่รอด แต่อย่างน้อยก็สงบลงบ้าง>" } } },
        required = { [286069] = { "15:1614649335:673650931", "ยาทา Lashwater" } },
        steps = { { "15:1614649335:673650931", "ยาทา Lashwater" } },
    },
    [6161] = { -- Claim Rackmore's Treasure!
        title = { "26:59202540:1011799964", "รับสมบัติของ Rackmore!" },
        objective = { "87:63948122:828793577", "หา Rackmore's Silver Key หา Rackmore's Golden Key แล้วค้นหาและเปิด Rackmore's Chest" },
        description = { "350:2015167322:2014456752", "บันทึก Rackmore เล่าว่าเรือกำลังแล่นไป Feathermoon Stronghold เมื่อถูกสัตว์ทะเลโจมตี เพื่อไม่ให้สมบัติตกอยู่ในมือศัตรู เขาซ่อนหีบไว้ที่ Ranazjar Isle\n\nการเปิดหีบต้องใช้กุญแจสองดอก สีเงินกับสีทอง กุญแจหายไปแล้ว แต่หากพบทั้งกุญแจและหีบ สมบัติก็รออยู่!" },
        progress = { "30:999867645:917640428", "หีบนี้ล็อกไว้อย่างแน่นหนา" },
        completion = { "42:1582352852:307193160", "หีบเปิดออก เผยให้เห็นสมบัติของ Rackmore!" },
        required = { [15878] = { "21:330699567:2006576680", "กุญแจเงินของ Rackmore" }, [15881] = { "21:1925781184:1541911516", "กุญแจทองของ Rackmore" } },
        objectiveLabels = {
            item = { ["Rackmore's Silver Key"] = "กุญแจเงินของ Rackmore", ["Rackmore's Golden Key"] = "กุญแจทองของ Rackmore" },
        },
    },
    [6561] = { -- Blackfathom Villainy
        title = { "20:1876793028:731548355", "ความชั่วร้ายแห่ง Blackfathom" },
        objective = { "77:1720357392:1737104041", "นำศีรษะ Twilight Lord Kelris ไปให้ Bashana Runetotem ใน Thunder Bluff" },
        description = { "487:1640363818:1825066067 N 9:261475542:1201216930", "ข้าไม่เหลือเรี่ยวแรงแล้ว ต้องการความช่วยเหลือจากเจ้า!\n\nนานมาแล้ว ที่นี่เคยเป็นวิหารอันยิ่งใหญ่ของ Elune แต่โชคร้ายนำไปสู่ความพินาศ เมื่อความแปดเปื้อนของ Old God ซึมขึ้นจากใต้ดินและทำให้บ่อน้ำจันทราศักดิ์สิทธิ์เป็นมลทิน\n\nAku'Mai ข้ารับใช้ของ Old God ผุดขึ้นจากสายน้ำ\n\nสาวกลัทธิ Twilight's Hammer ร่วมมือกับนากาเข้ายึดพื้นที่ สาวกที่ Kelris นำอยู่สังเวยผู้บริสุทธิ์ให้ Aku'Mai เพื่อแลกพลัง\n\nได้โปรด สังหาร Kelris แล้วนำศีรษะไปให้ Bashana ใน Thunder Bluff {name}" },
        progress = { "33:1323301644:1521188231 N 142:884544608:1418364113", "ขอพระแม่ธรณีสถิตกับเจ้า {name}\n\nสันติระหว่างผืนดินกับผู้คนทั้งหมดควรเป็นเป้าหมายของเรา นางมีแผนยิ่งใหญ่สำหรับธรรมชาติ และเราทุกคนมีบทบาทในแผนนั้น" },
        completion = { "171:672382009:1511580204 N 294:1862804685:1762237801 N 1:46:46", "Kelris หลบเลี่ยง Argent Dawn มาระยะหนึ่งแล้ว\n\nอยู่ช่วงหนึ่งพวกเขาคิดว่าเขาตายหรือหายตัวไป\n\nการจบอำนาจของเขาช่วยชีวิตผู้บริสุทธิ์มากมาย {name}\n\nสรรเสริญพระแม่ธรณี! การสังเวยผู้อื่นแก่ข้ารับใช้ของ Old God เพื่อประโยชน์ตน ช่างน่ารังเกียจเกินบรรยาย!\n\nวันนี้เจ้าทำสิ่งยิ่งใหญ่ Kelris เป็นผู้ชั่วร้ายที่ต้องการนำโลกกลับสู่ยุคโกลาหล ด้วยการบูชาสิ่งอย่าง Old Gods ขอบใจ {name}" },
        required = { [5881] = { "14:1374333252:250531135", "ศีรษะของ Kelris" } },
        steps = { { "14:1374333252:250531135", "ศีรษะของ Kelris" } },
    },
    [98189] = { -- Return the Statuette
        title = { "20:679554031:662369552", "นำรูปปั้นกลับคืน" },
        objective = { "67:1847883231:1277763516", "นำ Menethil Statuette ไปให้ Captain Stoutfist ใน Menethil Keep" },
        description = { "271:1023686528:1514933245", "โอ้ มัน... งามจริง!\n\nBlind Princess ต้องส่งให้ Menethil Harbor ก่อนโศกนาฏกรรม ใกล้เพียงนั้น!\n\nเชื่อว่าผู้รับลงชื่อคือ Captain Stoutfist ใน Menethil Keep หลังเรา ช่วยส่งงานให้เสร็จได้ไหม?" },
        progress = { "49:1076287910:83502549", "เจ้าเอาอะไรมา? ขอข้าดูหน่อย" },
        completion = { "106:2057747627:1519147419", "เจ้าชิงมันคืนจากพวกสัตว์ประหลาดนั่นได้! เดี๋ยวนี้โบราณวัตถุของกษัตริย์ผู้ล่วงลับเหลืออยู่ไม่มากแล้ว" },
        required = { [279589] = { "18:1305917549:656121578", "รูปปั้นเล็ก Menethil" } },
        steps = { { "18:1305917549:656121578", "รูปปั้นเล็ก Menethil" } },
    },
    [98342] = { -- The Great Cat Spirit
        title = { "20:334676701:195687234", "วิญญาณแมวผู้ยิ่งใหญ่" },
        objective = { "152:181428818:1133579354", "เก็บ Relic of the Fang, Relic of the Claw และ Relic of the Silent Shadow จาก Stormrage Barrow Den แล้วนำกลับไปให้ Great Cat Spirit" },
        description = { "504:921486809:2145847475", "หากจะอาศัยพลังวิญญาณข้า เจ้าต้องมีมากกว่าเพียงคำพูด หากจะเข้าใจและเคารพร่างของข้า เจ้าต้องพิสูจน์ว่าเปี่ยมด้วยไหวพริบ การลอบเร้น และความดุร้ายเมื่อถูกต้อนจนมุม\n\nใน Barrow Dens ทางตะวันออกใกล้ ๆ มีวัตถุที่ข้าโปรดปรานสามชิ้นที่เจ้าต้องนำมา วิญญาณโกรธเกรี้ยวทรงพลังเฝ้าอยู่ และจะโจมตีทันทีที่เห็นเจ้า รูปปั้นตรงทางเข้าจะให้พรลอบเร้นชั่วคราวเพื่อผ่านพวกมัน\n\nนำวัตถุเหล่านี้กลับมา เราจะได้รู้ว่าเจ้าพร้อมรับร่างของข้าหรือยัง" },
        progress = { "70:994848386:46857145", "อา กลับมาแล้ว หวังว่านำวัตถุเหล่านั้นมาด้วย?" },
        completion = { "196:1363483895:174664057 C 1:46:46", "ยอดเยี่ยม เจ้าแสดงให้เห็นว่าเข้าใจธรรมชาติที่แท้จริงของแมว และสามารถเป็นหนึ่งเดียวกับไหวพริบ การลอบเร้น และความดุร้ายที่จำเป็นต่อการรับร่างของข้า\n\nบัดนี้ข้าเห็นว่าเจ้าคู่ควรกับพรของข้าแล้ว {class}รุ่นเยาว์" },
        required = { [280502] = { "17:1049052398:1423587939", "วัตถุโบราณแห่งเขี้ยว" }, [280679] = { "17:998851833:1417030750", "วัตถุโบราณแห่งกรงเล็บ" }, [280680] = { "26:98044169:1098094958", "วัตถุโบราณแห่งเงาเงียบ" } },
        objectiveLabels = {
            item = { ["Relic of the Fang"] = "วัตถุโบราณแห่งเขี้ยว", ["Relic of the Claw"] = "วัตถุโบราณแห่งกรงเล็บ", ["Relic of the Silent Shadow"] = "วัตถุโบราณแห่งเงาเงียบ" },
        },
    },
    [98362] = { -- To Thunder Bluff
        title = { "16:1634743835:2000134126", "ไป Thunder Bluff" },
        objective = { "73:525856024:654813708", "กลับ Thunder Bluff แล้วคุยกับ Turak Runetotem บน Elder Rise" },
        description = { "420:1674526562:1897749728", "ถึงเวลาที่เราต้องแยกจากกันอีกครั้งแล้ว เจ้าผู้เยาว์วัย การนำบทเรียนไปใช้จะพาเจ้ากลับไปหาผู้ที่ส่งเจ้ามาพบข้า ดูเหมือนอาจารย์ของเจ้า Turak Runetotem จะพบศิษย์ที่คู่ควรในตัวเจ้า ข้าเองก็เห็นเช่นนั้น จงใส่ใจคำสอนของเขา แล้วอีกไม่นานเจ้าจะสามารถเรียกพลังจาก Great Cat Spirit เพื่อแปลงเป็นร่างของมันได้\n\nกลับไปยังที่ที่เจ้าจากมาเถิด เมื่อถึงเวลา เราจะได้พบกันอีก", variants = { { "418:1798060845:1266048467", "ถึงเวลาที่เราต้องแยกจากกันอีกครั้งแล้ว เจ้าผู้เยาว์วัย การนำบทเรียนไปใช้จะพาเจ้ากลับไปหาผู้ที่ส่งเจ้ามาพบข้า ดูเหมือนอาจารย์ของเจ้า Turak Runetotem จะพบศิษย์ที่คู่ควรในตัวเจ้า ข้าเองก็เห็นเช่นนั้น จงใส่ใจคำสอนของเขา แล้วอีกไม่นานเจ้าจะสามารถเรียกพลังจาก Great Cat Spirit เพื่อแปลงเป็นร่างของมันได้\n\nกลับไปยังที่ที่เจ้าจากมาเถิด เมื่อถึงเวลา เราจะได้พบกันอีก" } } },
        completion = { "467:756783593:844482123", "ยินดีต้อนรับกลับ สหาย ข้าสัมผัสได้ว่าเจ้าได้พบวิญญาณแมวผู้ยิ่งใหญ่และผ่านบททดสอบแล้ว ดรูอิดทุกคนต้องผ่านบททดสอบจากวิญญาณตนนี้ แม้บททดสอบจะแตกต่างกันไปในแต่ละรุ่น ข้าภูมิใจที่เจ้าผ่านมันและรับฟังภูมิปัญญาของวิญญาณแมวผู้ยิ่งใหญ่ มันเป็นวิญญาณโบราณที่อันตรายไม่แพ้ความขี้เล่น แต่ข้าสัมผัสได้ว่าเจ้าเข้าใจธรรมชาติของมันแล้ว\n\nบัดนี้ข้าจะสอนวิธีแปลงเป็นร่างแมวให้เจ้า", variants = { { "14:1649650394:897424258 N 447:691830771:132493576", "ยินดีต้อนรับกลับ {name} ข้าสัมผัสได้ว่าเจ้าได้พบ Great Cat Spirit และผ่านบททดสอบแล้ว ดรูอิดทุกคนต้องผ่านการทดสอบจากวิญญาณตนนี้ แม้บททดสอบจะแตกต่างกันไปในแต่ละรุ่น ข้าภูมิใจที่เจ้าผ่านและใส่ใจภูมิปัญญาของ Great Cat Spirit วิญญาณโบราณตนนี้มีทั้งความอันตรายและความขี้เล่นพอกัน แต่ข้าสัมผัสได้ว่าเจ้าเข้าใจธรรมชาติของเขาแล้ว\n\nบัดนี้ข้าจะสอนวิธีแปลงร่างเป็นแมวให้เจ้า" } } },
    },
    [98394] = { -- The Great Cat Spirit
        title = { "20:334676701:195687234", "วิญญาณแมวผู้ยิ่งใหญ่" },
        objective = { "125:816538644:457472023", "ตามหา Great Cat Spirit ทางใต้ของ Moonglade และเรียนรู้สิ่งที่มันจะถ่ายทอดเกี่ยวกับธรรมชาติของแมว" },
        description = { "427:1856797226:591128627", "ทางใต้ของ Moonglade บนเนินที่มองลงไปเห็นสะพาน มีผู้เฉลียวฉลาดและเจ้าเล่ห์ที่เราเรียกว่า Great Cat Spirit อาศัยอยู่\n\nเช่นเดียวกับ Great Bear Spirit วิญญาณตนนี้เป็นครูและผู้ชี้นำแก่ดรูอิดที่ปรารถนาร่างแมว ดรูอิดทุกคนย่อมมาขอภูมิปัญญาของมันในที่สุด หากเจ้าอยากแปลงเป็นแมว ก็ต้องมาเช่นกัน\n\nไปพบ Great Cat Spirit และเรียนรู้สิ่งที่มันจะสอนเจ้า" },
        completion = { "104:926715801:2003201300", "เจ้ามาเรียนรู้วิธีเรียกพลังจากวิญญาณข้าสินะ ดี เรามาดูกันว่าเจ้าพร้อมจะแปลงเป็นร่างของข้าหรือยัง" },
    },
    [98396] = { -- The Great Cat Spirit
        title = { "20:334676701:195687234", "วิญญาณแมวผู้ยิ่งใหญ่" },
        objective = { "152:181428818:1133579354", "เก็บ Relic of the Fang, Relic of the Claw และ Relic of the Silent Shadow จาก Stormrage Barrow Den แล้วนำกลับไปให้ Great Cat Spirit" },
        description = { "504:921486809:2145847475", "หากจะอาศัยพลังวิญญาณข้า เจ้าต้องมีมากกว่าเพียงคำพูด หากจะเข้าใจและเคารพร่างของข้า เจ้าต้องพิสูจน์ว่าเปี่ยมด้วยไหวพริบ การลอบเร้น และความดุร้ายเมื่อถูกต้อนจนมุม\n\nใน Barrow Dens ทางตะวันออกใกล้ ๆ มีวัตถุที่ข้าโปรดปรานสามชิ้นที่เจ้าต้องนำมา วิญญาณโกรธเกรี้ยวทรงพลังเฝ้าอยู่ และจะโจมตีทันทีที่เห็นเจ้า รูปปั้นตรงทางเข้าจะให้พรลอบเร้นชั่วคราวเพื่อผ่านพวกมัน\n\nนำวัตถุเหล่านี้กลับมา เราจะได้รู้ว่าเจ้าพร้อมรับร่างของข้าหรือยัง" },
        progress = { "70:994848386:46857145", "อา กลับมาแล้ว หวังว่านำวัตถุเหล่านั้นมาด้วย?" },
        completion = { "196:1363483895:174664057 C 1:46:46", "ยอดเยี่ยม เจ้าแสดงให้เห็นว่าเข้าใจธรรมชาติที่แท้จริงของแมว และสามารถเป็นหนึ่งเดียวกับไหวพริบ การลอบเร้น และความดุร้ายที่จำเป็นต่อการรับร่างของข้า\n\nบัดนี้ข้าเห็นว่าเจ้าคู่ควรกับพรของข้าแล้ว {class}รุ่นเยาว์" },
        required = { [280502] = { "17:1049052398:1423587939", "วัตถุโบราณแห่งเขี้ยว" }, [280679] = { "17:998851833:1417030750", "วัตถุโบราณแห่งกรงเล็บ" }, [280680] = { "26:98044169:1098094958", "วัตถุโบราณแห่งเงาเงียบ" } },
        steps = { { "17:1049052398:1423587939", "วัตถุโบราณแห่งเขี้ยว" }, { "17:998851833:1417030750", "วัตถุโบราณแห่งกรงเล็บ" }, { "26:98044169:1098094958", "วัตถุโบราณแห่งเงาเงียบ" } },
    },
    [98405] = { -- The Great Cat Spirit
        title = { "20:334676701:195687234", "วิญญาณแมวผู้ยิ่งใหญ่" },
