        description = { "427:1856797226:591128627", "ทางใต้ของ Moonglade บนเนินที่มองลงไปเห็นสะพาน มีผู้เฉลียวฉลาดและเจ้าเล่ห์ที่เราเรียกว่า Great Cat Spirit อาศัยอยู่\n\nเช่นเดียวกับ Great Bear Spirit วิญญาณตนนี้เป็นครูและผู้ชี้นำแก่ดรูอิดที่ปรารถนาร่างแมว ดรูอิดทุกคนย่อมมาขอภูมิปัญญาของมันในที่สุด หากเจ้าอยากแปลงเป็นแมว ก็ต้องมาเช่นกัน\n\nไปพบ Great Cat Spirit และเรียนรู้สิ่งที่มันจะสอนเจ้า" },
        completion = { "104:926715801:2003201300", "เจ้ามาเรียนรู้วิธีเรียกพลังจากวิญญาณข้าสินะ ดี เรามาดูกันว่าเจ้าพร้อมจะแปลงเป็นร่างของข้าหรือยัง" },
    },
    [5842] = { -- Welcome!
        title = { "8:1157429440:1900744790", "ยินดีต้อนรับ!" },
        objective = { "58:1962952128:894803257", "นำ Shadowglen Gift Voucher ไปให้ Orenthil Whisperwind" },
        description = { "333:1110247392:494598796", "ยินดีต้อนรับสู่ World of Warcraft!\n\nเพื่อขอบคุณเป็นพิเศษที่ซื้อ World of Warcraft Collector's Edition ให้นำบัตรของขวัญนี้ไปให้ Orenthil Whisperwind ใน Shadowglen แล้วคุณจะได้รับของขวัญ เป็นเพื่อนตัวน้อยที่จะร่วมเดินทางแสวงหาการผจญภัยและความรุ่งโรจน์\n\nขอบคุณอีกครั้ง และขอให้สนุกกับการอยู่ใน World of Warcraft!" },
        progress = { "132:1057634608:967750197", "สวัสดี! ยินดีที่ได้รู้จัก!\n\nข้าเห็นว่าเจ้ามีบัตรพิเศษ มอบให้ข้า แล้วข้าจะมีสิ่งของให้แลกเปลี่ยน" },
        completion = { "31:844644996:1050364761 N 82:1617086532:2042110772", "เจ้าเป็นวีรชนคนพิเศษจริง ๆ {name} เรายินดีต้อนรับเจ้าสู่โลก Azeroth และขอมอบของขวัญพิเศษเหล่านี้ให้เลือก!" },
        required = { [14648] = { "23:1019612465:630256209", "บัตรแลกของขวัญ Shadowglen" } },
        steps = { { "23:1019612465:630256209", "บัตรแลกของขวัญ Shadowglen" } },
    },
    [960] = { -- Onu is meditating
        title = { "17:2008582697:216239517", "Onu กำลังทำสมาธิ" },
        completion = { "30:1016429309:1361341836 N 236:1199404884:945680440", "ข้ากำลังทำสมาธิเพื่อใคร่ครวญภารกิจของเจ้า {name} ใคร่ครวญว่าเหตุใด Twilight's Hammer และพวกนากาจึงมาอยู่ที่นี่\n\nเมื่อพร้อมแล้ว ใช้ขวดยาพยากรณ์สร้างอ่างพยากรณ์ แล้วติดต่อข้าผ่านอ่างนั้น\n\nหากเจ้าทำขวดยาพยากรณ์หาย นี่ ข้ามีให้อีกขวด" },
    },
    [961] = { -- Onu is meditating
        title = { "17:2008582697:216239517", "Onu กำลังทำสมาธิ", variants = { { "17:1578583522:497806560", "Onu กำลังทำสมาธิ" } } },
        completion = { "247:1863025415:1160931532", "การพบพวกลัทธิ Twilight's Hammer น่ากังวลนัก ข้าต้องทำสมาธิใคร่ครวญเจตนาของพวกมัน...\n\nเมื่อมีข้อมูลเพิ่ม จงพูดกับข้าผ่านอ่างพยากรณ์ หากเจ้าต้องการขวดยาพยากรณ์ไว้สร้างอ่างละก็... นี่ ข้ามีให้อีกขวด" },
    },
    [2399] = { -- The Sprouted Fronds
        title = { "19:633908311:1425308306", "ใบอ่อนที่ผลิขึ้น" },
        completion = { "106:751096944:1066124509", "ต้นพืชที่ Denalan ปลูกไว้ในสวนแตกหน่อและเติบโตแล้ว ใบของมันสั่นไหว ราวกับรอให้ใครมาเก็บ..." },
    },
    [3803] = { -- Morrowgrain to Darnassus
        title = { "24:190652549:138782446", "ส่ง Morrowgrain สู่ Darnassus" },
        progress = { "266:1393489780:583737122", "ท่านอัครดรูอิดต้องการ Morrowgrain เพิ่มอยู่เสมอสำหรับงานวิจัยต่อเนื่องของ Cenarion Circle เรารับครั้งละสิบชิ้น และมอบเสบียงที่น่าจะมีประโยชน์ให้เป็นรางวัล เมื่อเจ้ามีครบสิบชิ้น จงบอกข้า แล้วข้าจะมอบรางวัลให้" },
        completion = { "263:167092668:1669234162 N 60:2019879359:1717107802", "ยอดเยี่ยม Morrowgrain เหล่านี้ต้องทำให้ท่านอัครดรูอิดพอใจแน่ แต่ข้าต้องยอมรับว่า... แค่อยู่ใกล้มันก็ทำให้ข้าไม่สบายใจเล็กน้อย นึกไม่ออกเลยว่าท่านอัครดรูอิดต้องอดทนเพียงใดเมื่ออยู่ใกล้มันจำนวนมาก!\n\nนี่สำหรับเจ้า {name} Cenarion Circle ขอบคุณที่เจ้าคอยสนับสนุนเรา" },
        description = { "266:1393489780:583737122", "ท่านอัครดรูอิดต้องการ Morrowgrain เพิ่มอยู่เสมอสำหรับงานวิจัยต่อเนื่องของ Cenarion Circle เรารับครั้งละสิบชิ้น และมอบเสบียงที่น่าจะมีประโยชน์ให้เป็นรางวัล เมื่อเจ้ามีครบสิบชิ้น จงบอกข้า แล้วข้าจะมอบรางวัลให้" },
        required = { [11040] = { "11:35561619:35128800", "มอร์โรว์เกรน" } },
        objectiveLabels = {
            item = { ["Morrowgrain"] = "มอร์โรว์เกรน" },
        },
    },
