    [7792] = { -- A Donation of Wool
        title = { "18:1119336907:2147062072", "บริจาคผ้าขนสัตว์" },
        progress = { "443:1612547131:2072196870", "ขณะนี้เรารับบริจาค Wool Cloth การบริจาคผ้าหกสิบชิ้นจะทำให้ Darnassus ยกย่องความเอื้อเฟื้อของเจ้าอย่างเต็มที่ เราต้องการจากเจ้าเพียงหกสิบชิ้นเท่านั้น ผ้าจากคนอื่น ๆ ในอาณาจักรน่าจะช่วยให้เรารวบรวมได้พอสำหรับโครงการ\n\nหากเจ้ามี Wool Cloth หกสิบชิ้นและพร้อมบริจาค ข้ารับไว้ได้ทันที" },
        completion = { "52:1271369293:1555941987 N 1:33:33", "ยอดเยี่ยม! เราขอบคุณสำหรับการบริจาคอันเอื้อเฟื้อของเจ้า {name}!" },
        description = { "443:1612547131:2072196870", "ขณะนี้เรารับบริจาค Wool Cloth การบริจาคผ้าหกสิบชิ้นจะทำให้ Darnassus ยกย่องความเอื้อเฟื้อของเจ้าอย่างเต็มที่ เราต้องการจากเจ้าเพียงหกสิบชิ้นเท่านั้น ผ้าจากคนอื่น ๆ ในอาณาจักรน่าจะช่วยให้เรารวบรวมได้พอสำหรับโครงการ\n\nหากเจ้ามี Wool Cloth หกสิบชิ้นและพร้อมบริจาค ข้ารับไว้ได้ทันที" },
        required = { [2592] = { "10:1951285682:678944537", "ผ้าขนสัตว์" } },
        steps = { { "10:1951285682:678944537", "ผ้าขนสัตว์" } },
    },
    [7798] = { -- A Donation of Silk
        title = { "18:1051041469:2137966348", "บริจาคผ้าไหม" },
        progress = { "435:1011791943:1214420941", "เช่นเดียวกับผ้าชนิดอื่น ๆ ตอนนี้ผ้าไหมของเราเหลือน้อยที่สุดเท่าที่เคยมี เราต้องการจากเจ้าเพียงหกสิบชิ้นเท่านั้น และน่าจะบรรลุเป้าหมายได้ด้วยการสนับสนุนของคนอื่น\n\nข้าขอบอกว่าของบริจาคที่เอื้อเฟื้อเช่นผ้าไหม จะทำให้ชื่อเสียงของเจ้าในชุมชนดีขึ้นแน่นอน! หากเจ้ามี Silk Cloth หกสิบชิ้นและพร้อมบริจาค ข้ารับไว้ได้ทันที" },
        completion = { "52:1271369293:1555941987 N 1:33:33", "ยอดเยี่ยม! เราขอบคุณสำหรับการบริจาคอันเอื้อเฟื้อของเจ้า {name}!" },
        description = { "435:1011791943:1214420941", "เช่นเดียวกับผ้าชนิดอื่น ๆ ตอนนี้ผ้าไหมของเราเหลือน้อยที่สุดเท่าที่เคยมี เราต้องการจากเจ้าเพียงหกสิบชิ้นเท่านั้น และน่าจะบรรลุเป้าหมายได้ด้วยการสนับสนุนของคนอื่น\n\nข้าขอบอกว่าของบริจาคที่เอื้อเฟื้อเช่นผ้าไหม จะทำให้ชื่อเสียงของเจ้าในชุมชนดีขึ้นแน่นอน! หากเจ้ามี Silk Cloth หกสิบชิ้นและพร้อมบริจาค ข้ารับไว้ได้ทันที" },
        required = { [4306] = { "10:1269080011:1976271755", "ผ้าไหม" } },
        steps = { { "10:1269080011:1976271755", "ผ้าไหม" } },
    },
    [7799] = { -- A Donation of Mageweave
        title = { "23:477706609:1703816279", "บริจาคผ้า Mageweave" },
        progress = { "409:1645571407:2107766787", "Mageweave ใกล้หมดแล้ว เราต้องการให้เจ้าช่วยเติมคลัง! หากชุมชนร่วมแรงกัน เราต้องการ Mageweave Cloth จากเจ้าเพียง 60 ชิ้นก็จะถึงเป้าหมาย ข้ารับรองว่า Darnassus จะไม่มองข้ามความเอื้อเฟื้อนี้!\n\nหากเจ้ามี Mageweave Cloth หกสิบชิ้นและพร้อมบริจาค ข้ารับไว้ได้ทันที" },
        completion = { "52:1271369293:1555941987 N 1:33:33", "ยอดเยี่ยม! เราขอบคุณสำหรับการบริจาคอันเอื้อเฟื้อของเจ้า {name}!" },
        description = { "409:1645571407:2107766787", "Mageweave ใกล้หมดแล้ว เราต้องการให้เจ้าช่วยเติมคลัง! หากชุมชนร่วมแรงกัน เราต้องการ Mageweave Cloth จากเจ้าเพียง 60 ชิ้นก็จะถึงเป้าหมาย ข้ารับรองว่า Darnassus จะไม่มองข้ามความเอื้อเฟื้อนี้!\n\nหากเจ้ามี Mageweave Cloth หกสิบชิ้นและพร้อมบริจาค ข้ารับไว้ได้ทันที" },
        required = { [4338] = { "15:1283357618:289024293", "ผ้า Mageweave" } },
        steps = { { "15:1283357618:289024293", "ผ้า Mageweave" } },
    },
    [7800] = { -- A Donation of Runecloth
        title = { "23:805424014:894170896", "บริจาคผ้า Runecloth" },
        progress = { "N 410:720308826:879718219", "{name} เจ้ามีส่วนช่วยโครงการรวบรวมผ้าของเราอย่างมาก ระหว่างที่เราพยายามเติมเสบียงสำรอง ยังมีผ้าชนิดหนึ่งขาดแคลนอย่างหนัก นั่นคือ Runecloth เราจำเป็นต้องใช้มันอย่างเร่งด่วน และหวังว่าเจ้าจะช่วยได้เช่นที่ผ่านมา!\n\nหากเต็มใจ โปรดนำ Runecloth ที่แบ่งให้ได้มาให้ข้า ในตอนแรกเราจะรับบริจาคหนึ่งครั้งจำนวนหกสิบชิ้น แล้วค่อยดูกันต่อไป" },
        completion = { "363:1453542902:756496047", "ยอดเยี่ยม ข้ารับรองว่าเราจะนำไปใช้ทันที ขอบคุณอีกครั้งสำหรับความช่วยเหลือ! ถ้าไม่มีเจ้า เราคงลำบากแน่\n\nจากที่เจ้าบริจาคมาทั้งหมด ข้ายินดีรับ Runecloth เพิ่มหากเจ้าต้องการบริจาคในภายหน้า แวะมาหาข้าได้เลย ข้าจะดูแลเองให้แน่ใจว่าความดีของเจ้าจะไม่ถูกมองข้าม!" },
        description = { "N 410:720308826:879718219", "{name} เจ้าช่วยโครงการรับบริจาคผ้าของเราไว้มาก ระหว่างที่เราพยายามเติมของเข้าคลัง ยังมีผ้าชนิดหนึ่งที่ขาดแคลนหนัก นั่นคือ Runecloth เราต้องการมันอย่างเร่งด่วน และหวังว่าเจ้าจะช่วยเราได้อย่างที่ผ่านมา!\n\nหากเจ้ายินดีช่วย เอา Runecloth ที่พอแบ่งได้มาให้ข้า เราจะเริ่มจากรับบริจาคครั้งเดียวหกสิบชิ้น แล้วค่อยว่ากันต่อ" },
        required = { [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        steps = { { "9:897047003:553648234", "ผ้ารูน" } },
    },
    [7801] = { -- Additional Runecloth
        title = { "20:549296932:999816626", "บริจาค Runecloth เพิ่ม" },
        progress = { "73:687057549:1578393754", "เมื่อเจ้าพร้อมส่ง Runecloth กองนั้นมา ข้าจะรับไว้", variants = { { "22:940931934:1505085707 N 330:124923882:1106569876", "ยินดีที่ได้พบอีกครั้ง {name}! เราต้องใช้ Runecloth อยู่เสมอ ถ้าเจ้าพอจะแบ่งให้ได้ เราก็ยินดีรับเพิ่ม หากเจ้านำ Runecloth มาบริจาคเพิ่มอีกกองละยี่สิบชิ้น ข้าจะดูแลให้ Darnassus ยกย่องที่เจ้ายังช่วยเหลือพวกเรา\n\nเมื่อพร้อมส่ง Runecloth กองนั้นมาให้ข้า ข้าก็พร้อมรับไว้" } } },
        completion = { "N 116:2094394438:1847393952", "{name} หากไม่มีวีรชนเช่นเจ้าคอยทำงานเพื่อชนเผ่า เราคงทุกข์ยากแน่ ขอบคุณที่เจ้ายังทุ่มเทช่วยเหลือ!" },
        description = { "22:940931934:1505085707 N 330:124923882:1106569876", "ยินดีที่ได้พบอีกครั้ง {name}! เราต้องใช้ Runecloth อยู่เสมอ ถ้าเจ้าพอจะแบ่งให้ได้ เราก็ยินดีรับเพิ่ม หากเจ้านำ Runecloth มาบริจาคเพิ่มอีกกองละยี่สิบชิ้น ข้าจะดูแลให้ Darnassus ยกย่องที่เจ้ายังช่วยเหลือพวกเรา\n\nเมื่อพร้อมส่ง Runecloth กองนั้นมาให้ข้า ข้าก็พร้อมรับไว้" },
        required = { [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        objectiveLabels = {
            item = { ["Runecloth"] = "ผ้ารูน" },
        },
    },
    [8734] = { -- Tyrande and Remulos
        title = { "19:2083779381:612602383", "Tyrande และ Remulos" },
        objective = { "52:638017426:32001052", "เดินทางไป Moonglade แล้วคุยกับ Keeper Remulos" },
        description = { "244:932830941:295550218", "Tyrande จะได้รับแจ้ง เจ้าผู้มีอายุขัย Shan'do Stormrage เตรียมข้าไว้รับสถานการณ์เช่นนี้แล้ว\n\nบัดนี้เจ้าต้องเดินทางไป Moonglade เพื่อพูดกับ Remulos เขาจะสั่งการต่อเกี่ยวกับการอัญเชิญ Eranikus\n\nพวกเราทุกคนขอให้เจ้าโชคดีอย่างยิ่ง" },
        completion = { "361:212165815:2027685436", "หาก Eranikus ไม่ยินยอม เราย่อมดึงเขาออกจากความฝันไม่ได้ แต่เจตนาของเขาทำให้จำเป็นต้องมายังโลกของเรา เขาต้องการทำลายร่างปรากฏที่มีชีวิตของ Malfurion หากทำสำเร็จ ก็เท่ากับกำจัดพันธมิตรผู้ทรงพลังที่สุดคนหนึ่งของความฝัน หาก Malfurion ล้มลง ฝันร้ายจะกลืนกินทุกสิ่งที่เหลืออยู่จนหมด..." },
    },
    [86757] = { -- Slowing the Orc Advance
        title = { "23:1430707455:1470578781", "ชะลอการรุกของออร์ค" },
        objective = { "64:142233213:236805092", "นำ Jagged Orc Sword 6 เล่ม และ Curved Orc Dagger 4 เล่มไปให้ Shandrina", amount = { "6:1273960851:929420321 W1 23:744069188:285089535 W2 33:1350012593:1365584546", "นำ Jagged Orc Sword {world1} เล่ม และ Curved Orc Dagger {world2} เล่มไปให้ Shandrina" } },
        description = { "488:875121668:169449092", "ออร์คยึดป่าตะวันออกไปแล้ว พวกสอดแนมและทหารของมันซุ่มอยู่ทั่วป่า! ไม่ปลอดภัยที่ชาวเราจะเดินทางใน Ashenvale อีกต่อไป\n\nเราต้องผลักออร์คกลับและรักษาป่าไว้ พวกเราจัดการทหารกับผู้สอดแนมบางส่วนได้ด้วยการลอบอยู่ตามขอบค่ายอย่างระวัง\n\nต่อสู้กับออร์คแล้วนำดาบหยักกับมีดโค้งที่มันใช้มาให้ข้า ข้าจะดูแลให้อาวุธถูกนำกลับมาใช้ประโยชน์ใหม่ ไม่ให้สูญเปล่า" },
        completion = { "16:1549935302:71513149 N 248:1489581485:997365538", "ทำได้ยอดเยี่ยม {name}\n\nข้ารังเกียจที่สถานการณ์บีบให้เราต้องใช้ความรุนแรงเช่นนี้ แต่หากไม่หยุดพวกออร์ค พวกมันจะบุก Astranaar แล้วโค่นต้นไม้ทั้งป่า อย่างน้อยเราก็เอาโลหะจากอาวุธหยาบ ๆ ของมันมาทำเครื่องป้องกันของเราเองได้" },
        progress = { "104:420511542:173330378", "ข้ากลัวว่าบ้านเราจะเป็นอย่างไรต่อไป หากออร์คยังรุกลึกเข้าไปในป่าเรื่อย ๆ" },
        required = { [279505] = { "19:1910583637:1598624078", "ดาบออร์คคมบิ่น" }, [279507] = { "20:623916775:1046850334", "กริชออร์คใบโค้ง" } },
        steps = { { "19:1910583637:1598624078", "ดาบออร์คคมบิ่น" }, { "20:623916775:1046850334", "กริชออร์คใบโค้ง" } },
    },
    [87760] = { -- Holy Diver
        title = { "10:1522727794:56347449", "นักดำดิ่งศักดิ์สิทธิ์" },
        objective = { "83:1868916050:1547019467", "ค้นหาและฆ่า Stormscale Beastmistress แล้วนำ Rod of Deep Dominion ของนางกลับมา" },
        description = { "42:1552020468:1253223065 N 454:556129047:16414626", "ข้าได้รับข่าวตอบจาก Darnassus แล้ว {name}!\n\nจากตัวอย่างสัตว์ เรารู้ว่านากาสะกดสัตว์ทะเลเหล่านี้ให้เป็นพาหนะกับสัตว์บรรทุกโดยไม่เต็มใจ ส่วนตัวที่ดื้อเกินไป แก่เกินไป หรือเจ็บหนัก พวกมันก็ไล่ออกมาเพื่อความสนุก ช่างโหดร้าย!\n\nหน้าที่ศักดิ์สิทธิ์ของเราคือหยุดเรื่องนี้!\n\nนากามีกำลังที่ Ruins of Mathystra คงจับ Thresher จากนอกชายฝั่ง ตามหานายหญิงผู้ควบคุมสัตว์ สังหารนาง แล้วนำเครื่องมือครอบงำกลับมา!" },
        progress = { "89:2102888273:531341934", "ในที่สุดเราก็จะไขปริศนานี้ได้ และพวกสัตว์จะได้อยู่อย่างสงบเสียที!" },
        completion = { "30:378391754:1149953159 N 327:733941248:1495030956", "เราเดินทางกันมาไกล {name} แต่ก็คุ้มค่า\n\nในที่สุดเจ้าก็ชิงคทาที่พวกนากาใช้บังคับสัตว์ทะเลให้รับใช้มาได้ ข้าจะดูให้แน่ใจว่ามันถูกทำลาย แล้วฉลามหางยาวกับเต่าทะเลจะได้อยู่กันอย่างสงบเสียที\n\nขอบใจอีกครั้ง ความมุ่งมั่นของเจ้าให้ผลแล้ว และข้าเองก็ซาบซึ้งใจจริง ๆ" },
        required = { [280686] = { "20:1281777134:660134556", "คทาควบคุมห้วงลึก" } },
        steps = { { "20:1281777134:660134556", "คทาควบคุมห้วงลึก" } },
    },
    [98027] = { -- Gleaming Crescent Necklace
        title = { "26:779615647:1410616232", "สร้อยจันทร์เสี้ยวเรืองรอง" },
        objective = { "54:763177233:714988105", "นำ Crescent Necklace ไปให้ Maliynn ที่ Astranaar" },
        description = { "289:689789148:224624442", "<สร้อยเงินในมือเรืองประกายอ่อนเมื่อสำรวจ รูปจันทร์เสี้ยวเล็กดูคล้ายสัญลักษณ์ไนต์เอลฟ์อื่นที่เคยเห็น\n\nเมื่อพลิกสร้อย พบจารึกเล็กว่า \"Alor'lormah, Maliynn\" บางทีอาจเป็นของ Maliynn ที่ Astranaar?>", variants = { { "265:1739640920:574941037", "<สร้อยเงินในมือเรืองประกายอ่อนเมื่อเจ้าพินิจดู จันทร์เสี้ยวดวงเล็กชวนให้นึกถึงพระแม่จันทรา\n\nเมื่อพลิกสร้อย เจ้าพบข้อความสลักเล็ก ๆ ว่า “พวกเรารักเจ้า Maliynn” บางทีอาจเป็นของ Maliynn ที่ Astranaar?>" } } },
        completion = { "325:1425986493:898505197", "โอ้ ตายจริง! ไม่อยากเชื่อเลยว่าเจ้าหาเจอ ข้านึกว่าหาจนทั่วแล้ว!\n\nข้าทำมันหายตอนไปส่งเสบียงให้ด่านหน้าของเราแห่งหนึ่ง พอเดินหาตามทางแล้วไม่เจอก็ถอดใจไปแล้ว\n\nขอบใจที่เอากลับมาให้ข้า นี่เป็นของขวัญจากพ่อแม่ผู้ล่วงลับ ข้าบอกเป็นคำพูดไม่ได้เลยว่าการได้มันคืนมามีความหมายกับข้าเพียงใด" },
    },
    [98028] = { -- Baron Marinous
        title = { "14:1100095604:2003281175", "บารอน Marinous" },
        objective = { "79:409910363:1470686202", "นำ Clouded Water Globe ไปให้ Onu ที่ Grove of the Ancients ใน Darkshore" },
        description = { "441:1205438971:1866983217", "สิ่งเดียวที่เหลือจากธาตุทรงพลังคือทรงกลมที่ดูเป็นน้ำบริสุทธิ์ แต่ขุ่นด้วยสสารไม่รู้ชนิด ขอบดูใสจนกระทั่งหมุนมัน ราวกับความขุ่นนั้นจงใจกีดกันไม่ให้มองข้างใน\n\nสิ่งที่เกิดกับมันและซากเมืองที่เฝ้าอยู่ยังดำเนินต่อในบางรูปแบบ\n\nคงมีเพียง Onu ผู้โบราณแห่งภูมิปัญญาที่ Grove of the Ancients ไกลทางใต้ ซึ่งอาจรู้มากกว่านี้" },
        progress = { "57:1506533540:121132202 R 29:982244124:1641739108", "ข้าสัมผัสได้ว่ามีบางสิ่งที่เก่าแก่กว่าเจ้ามากอยู่ใกล้ ๆ เจ้า{race}... เจ้านำอะไรมาให้ข้าหรือ?" },
        completion = { "363:2099741075:2100916987", "<Onu ดูประหลาดใจ เท่าที่ผู้โบราณจะดูประหลาดใจได้>\n\nมีบันไดทอดลงไปใน Mathystra หรือ? หรือว่าจะเป็นอย่างที่ข้าคิด?\n\n<Onu ส่ายหน้า>\nข้าต้องหารือเรื่องนี้กับคนอื่น ๆ ก่อน ดีแล้วที่เจ้าค้นพบเรื่องนี้ก่อนพวกนากา... หรือพวกลัทธิที่เป็นพันธมิตรของมัน\n\nโปรดรับสิ่งนี้แทนคำขอบคุณ การโค่นผู้พิทักษ์ธาตุลงได้เป็นเรื่องใหญ่ทีเดียว", variants = { { "371:381327056:881605756", "<Onu ดูประหลาดใจ เท่าที่ผู้โบราณจะดูประหลาดใจได้>\n\nมีบันไดทอดลงไปใน Mathystra หรือ? หรือว่าจะเป็นอย่างที่ข้าคิด?\n\n<Onu ส่ายหน้า>\nข้าต้องหารือเรื่องนี้กับคนอื่น ๆ ก่อน ดีแล้วที่เจ้าค้นพบเรื่องนี้ก่อนพวกนากา... หรือพวกลัทธิที่เป็นพันธมิตรของมัน\n\nโปรดรับสิ่งนี้แทนคำขอบคุณ การโค่นผู้พิทักษ์ธาตุลงได้เป็นเรื่องใหญ่ทีเดียว" } } },
        required = { [279275] = { "19:111107856:648055419", "ลูกแก้วน้ำขุ่น" } },
        steps = { { "19:111107856:648055419", "ลูกแก้วน้ำขุ่น" } },
    },
    [98417] = { -- Vengeful Trail
        title = { "14:749082973:561308309", "รอยทางแห่งการแก้แค้น" },
        objective = { "148:117065674:2113288323", "Maseara Autumnmoon ต้องการให้คุณค้นหาทางตะวันตกของ Forest Song ท่ามกลางปีศาจที่ Satyrnaar แล้วกลับไปรายงานร่องรอยของ Kurothel สามีของนางที่พบ" },
        description = { "408:1211564416:864489566", "ยามที่โชคชะตาทำให้เราเปราะบางที่สุด โศกนาฏกรรมก็มาเยือนหมู่บ้าน เซเทอร์ทำให้วิหารแปดเปื้อน สัมผัสโสมมเปื้อนกิ่งก้านศักดิ์สิทธิ์ และฆ่าผู้บริสุทธิ์อย่างไร้เมตตา\n\nKurothel ถูกความโกรธกลืนกิน ดรูอิดกำลังต่อสู้กับเซเทอร์ และเขาตามไป\n\nสายสัมพันธ์เรายังอยู่ ข้าสัมผัสสามีได้ทางตะวันตกในป่านี้ โปรดนำข่าวชะตาของเขากลับมา" },
        completion = { "186:1973853005:2009330655", "โอ้ ไม่นะ... ได้ยินอย่างนี้ข้าก็สบายใจไม่ลง Kurothel คงไม่ได้แค่อาศัยอยู่ในป่า เขากำลังใช้ชีวิตเหมือนสัตว์ป่าขึ้นทุกคืน\n\nข้ากลัวว่าเสียงกระซิบพวกนั้นจะเป็นความจริง" },
        progress = { "51:1354281179:174288764", "เจ้าพบอะไรตามเนินเขาในป่าของเราบ้าง?" },
        required = { [281014] = { "19:1243999560:514571931", "ม้วนสารพันเถาวัลย์" } },
        steps = { { "29:2136146700:1721918436", "พบข้าวของของ Kurothel" }, { "18:1511399980:2029124894", "ติดต่อ Kurothel" } },
        objectiveLabels = {
            item = { ["Vine-Wrapped Scroll"] = "ม้วนสารพันเถาวัลย์" },
        },
    },
    [98418] = { -- Shared Fury
        title = { "11:342734650:735701309", "ความโกรธแค้นร่วมกัน" },
        objective = { "121:1368344325:90929883", "ฆ่า Xavian Rogue 5 ตน, Felsworn 5 ตน, Betrayer 5 ตน และ Hellcaller 5 ตน\nจากนั้นกลับไปหา Maseara Autumnmoon ที่ Forest Song", amount = { "5:409775429:850574908 W1 16:1595369268:465687631 W2 11:802763514:1670699704 W3 16:892723020:564167527 W4 69:1309166032:34466343", "ฆ่า Xavian Rogue {world1} ตน, Felsworn {world2} ตน, Betrayer {world3} ตน และ Hellcaller {world4} ตน\nจากนั้นกลับไปหา Maseara Autumnmoon ที่ Forest Song" } },
        description = { "502:161178038:161605528 N 1:46:46", "Kurothel กล่าวถึงการพบสิ่งที่เรียกว่ามนุษย์หมาป่า สมาชิกฝูงกำลังซ่อนตัวในป่าเรามากขึ้น ครั้งสุดท้ายที่พูดกัน ดรูอิดกำลังพยายามสื่อสารกับเหล่าผู้มีหัวใจแห่งสัตว์ป่า ที่แสดงว่าควบคุมสัญชาตญาณตนได้\n\nถ้อยคำที่เขาเขียนเผยการต่อสู้ที่มืดมนกว่า หากมีอะไรช่วยให้เราได้เห็นตัวเขาจริง ๆ อีกครั้ง การปราบปีศาจที่ผลักเขาสู่การเปลี่ยนร่างอันร้อนรุ่มนี้ คงช่วยวิญญาณที่ทรมานได้\n\nสังหารพวก Xavian เถิด {name}" },
        completion = { "425:987656328:748073153 N 62:425691085:1664221738", "แสงของ... Elune เอ่อล้นอยู่ในตัวข้าและรอบกาย ข้ารู้สึกว่า Kurothel ได้เห็นเจ้าลงสู้ในสงครามที่โหมกระหน่ำทั้งในดินแดนและในใจของเรา\n\nข้าหวังว่าเมื่อเวลาผ่านไป ความพยายามของเหล่า Sentinels และดรูอิดผู้หลงทางของเราจะกำจัดภัยปีศาจได้ตลอดกาล บางทีเมื่อถึงตอนนั้น แรงกระหายการล้างแค้นที่สืบทอดในสายเลือดของเราจึงจะมอดดับลง\n\nขอบใจ {name} เจ้าเป็นพันธมิตรของผืนป่า และเป็นมิตรของชาวคัลโดไร" },
        progress = { "151:749963073:1512972259", "เหล่าปีศาจทำให้วัฒนธรรมเก่าแก่ของเรามัวหมอง พวกมันบีบให้สัญชาตญาณป้องกันตัวของเราเผยด้านดิบเถื่อนที่สุดออกมา เราจะสูญเสียตัวตนไปท่ามกลางการต่อสู้นี้หรือไม่?" },
        objectiveLabels = {
            monster = { ["Xavian Felsworn slain"] = "ปราบ ซาเทอร์ Xavian ผู้สาบานตนต่อเฟล", ["Xavian Rogue slain"] = "ปราบ โจร Xavian", ["Xavian Betrayer slain"] = "ปราบ ผู้ทรยศ Xavian", ["Xavian Hellcaller slain"] = "ปราบ ผู้เรียกอสูร Xavian" },
        },
    },
    [98731] = { -- Blessings of the Great Cat Spirit
        title = { "33:1941080999:1770977738", "พรแห่งวิญญาณแมวผู้ยิ่งใหญ่" },
        objective = { "18:408344685:1120416534", "คุยกับ Dendrite" },
        description = { "212:149194168:1478145185", "เมื่อได้รับพรของข้าแล้ว จงกลับไปหา Dendrite เขาจะแนะนำต่อ ข้าหวังจริง ๆ ว่าวันหนึ่งเราจะได้พบกันอีก\n\nขอเงามืดซ่อนเจ้าเสมอ และขอศัตรูตกเป็นเหยื่อกรงเล็บได้โดยง่าย สหายรุ่นเยาว์" },
        completion = { "470:843412361:319393642", "<เมื่อเจ้าเข้าใกล้ Dendrite ขยับมืออีกครั้งในอากาศเหนือศีรษะ ราวกับวาดสัญลักษณ์ที่มองไม่เห็น รัศมีพลังอีกระลอกแผ่มาคลุมร่างเขา และเขายิ้มเพียงเล็กน้อย>\n\nข้าสัมผัสได้ถึงไหวพริบและความดุร้ายของแมวในตัวเจ้า สิ่งที่ยังไม่มีตอนข้าส่งเจ้าไปพบ Great Cat Spirit แววตาเจ้าบอกว่าตอนนี้เข้าใจแล้วว่าต้องอาศัยความเงียบเชียบและความว่องไวเพียงใดจึงจะรับเอาธรรมชาตินี้มาได้\n\nตอนนี้เจ้าเรียนรู้ที่จะใช้ไหวพริบอย่างมีสมาธิ รับเอาธรรมชาติแท้จริงของแมว และเรียกพลังจากวิญญาณของมันได้แล้ว" },
    },
    [8151] = { -- The Hunter's Charm
        title = { "18:117938018:564121539", "เครื่องรางของพราน" },
        objective = { "27:1131045975:225740656", "คุยกับ Ogtinc ใน Azshara" },
        description = { "389:1066106610:525078632", "Ogtinc แห่ง Azshara เรียกหาพรานมากประสบการณ์เช่นเจ้า เขาเป็นพรานเฟอร์โบลก์ที่จากชนเผ่ามาช่วย Cenarion Circle คำสอนของเขามุ่งเพิ่มพูนปัญญาแก่ผู้ร่วมวิถี และชี้นำให้รักษาสมดุล เจ้าควรไปพูดกับเขา\n\nOgtinc อาศัยอยู่บนหน้าผาใน Azshara ทางตะวันออกเฉียงเหนือของ Ruins of Eldarath" },
        completion = { "297:1241220575:715840379", "บัดนี้จุดมุ่งหมายของข้าไม่ใช่การล่า แต่เป็นการสอนพราน นั่นคือสิ่งที่ชะตากรรมมอบให้ข้า\n\nมาสร้างเครื่องรางของพรานร่วมกับข้า เป็นสิ่งที่รวบรวมของจากเหยื่อที่ล้มตายไว้ เพื่อเตือนใจถึงบททดสอบและชัยชนะที่ผ่านมา ท้ายที่สุดข้าจะเก็บเครื่องรางไว้ แต่มอบสิ่งอื่นเป็นรางวัลให้เจ้า" },
    },
    [8153] = { -- Courser Antlers
        title = { "15:645060177:894538823", "เขาของ Courser" },
        objective = { "128:2035403612:1635706376", "นำ Perfect Courser Antlers หนึ่งคู่ไปให้ Ogtinc ใน Azshara เขาอยู่บนหน้าผาทางตะวันออกเฉียงเหนือของ Ruins of Eldarath" },
        description = { "372:1333813411:317350163", "Courser มีเขาทรงพลังที่สุดในดินแดนที่เรารู้จัก มันใช้เขาป้องกันตัวและขวิดผู้จู่โจม จึงมักทำให้ปลายเขาเสียหาย เขาธรรมชาติที่สมบูรณ์แบบเป็นสัญญาณของจิตวิญญาณสัตว์ที่มั่นใจอย่างยิ่ง\n\nการได้ถือเขาเช่นนั้นจะมอบความมั่นใจเดียวกันแก่เจ้า\n\nจงล่า Mosshoof Courser หาเขาที่สมบูรณ์แบบ แล้วนำมาให้ข้า" },
        progress = { "27:1460383693:1526991413", "เจ้าได้เขามาหรือยัง?" },
        completion = { "81:1664006888:1801002171", "เจ้าต้องมีสายตาเฉียบคมและความอดทนสูงจึงได้สิ่งนี้มา ทำได้ดี" },
        required = { [20017] = { "22:1337422092:382214224", "เขาคูร์เซอร์สมบูรณ์" } },
        objectiveLabels = {
            item = { ["Perfect Courser Antler"] = "เขาคูร์เซอร์สมบูรณ์" },
        },
    },
    [8231] = { -- Wavethrashing
        title = { "13:1714824235:986818977", "ล่า Wavethrasher" },
        objective = { "113:1594495439:466398726", "นำ Wavethrasher Scale 6 ชิ้นไปให้ Ogtinc ใน Azshara เขาอยู่บนหน้าผาทางตะวันออกเฉียงเหนือของ Ruins of Eldarath" },
        description = { "269:1746327982:196943528", "Wavethrasher เป็นสัตว์สะเทินน้ำสะเทินบกที่อาศัยอยู่เฉพาะใน Azshara พวกมันแข็งแรงและทรหด\n\nเกล็ดแข็งเป็นเงาของ Wavethrasher สะท้อนความแข็งแกร่งของพราน\n\nจงตามรอยและล่า Wavethrasher ตามชายฝั่ง Azshara แล้วนำเกล็ดมาให้ข้า" },
        progress = { "26:26410076:1817494715", "เจ้าทำสำเร็จหรือยัง?" },
        completion = { "143:2140170691:1675599846", "Wavethrasher ไม่ใช่สัตว์ที่เอาชนะได้ง่าย โดยเฉพาะเมื่ออยู่ในน้ำ\n\nเจ้าพิสูจน์แล้วว่าพร้อมล่าเหยื่อที่อันตรายยิ่งกว่า" },
        required = { [20087] = { "19:379490849:1025643994", "เกล็ด Wavethrasher" } },
        objectiveLabels = {
            item = { ["Wavethrasher Scales"] = "เกล็ด Wavethrasher" },
        },
    },
    [8232] = { -- The Green Drake
        title = { "15:2142508592:54051454", "มังกรเขียว" },
        objective = { "112:1133725605:834098792", "นำ Tooth of Morphaz ไปให้ Ogtinc ใน Azshara เขาอยู่บนหน้าผาทางตะวันออกเฉียงเหนือของ Ruins of Eldarath" },
        description = { "440:920698607:533742759", "คราวนี้ข้าจะส่งเจ้าไปล่าอย่างเสี่ยงอันตราย จงสังหารมังกรเขียว Morphaz แล้วนำฟันของมันมาให้ข้า Morphaz อาศัยอยู่ลึกใน Temple of Atal'Hakkar ทางเข้าวิหารอยู่ใน Swamp of Sorrows\n\nหากจะเอาชนะมัน เจ้าต้องไม่ไปลำพัง มังกรตนนี้มีศัตรูมากมาย จงหาคนอื่นที่ต้องการทำลายมัน\n\nฟันของมังกรเป็นสัญลักษณ์ของพลังที่พรานจะได้รับเมื่อร่วมมือกับผู้อื่น นำมันมาให้ข้า แล้วเจ้าจะได้เรียนรู้มากมาย" },
        progress = { "27:21164308:1490831959 N 22:1230336579:1688375527", "ข้าเห็นปัญญาในดวงตาเจ้า {name} การล่าจบลงแล้วหรือ?" },
        completion = { "31:193970162:1570951364 N 52:490711387:280972850 C 1:46:46", "เจ้าเรียนรู้วิถีเก่าแก่แล้ว {name} ข้าจึงขอมอบของขวัญจากสมัยที่ข้ายังเป็น {class}" },
        required = { [20019] = { "16:905763191:2111630440", "ฟันของ Morphaz" } },
        objectiveLabels = {
            item = { ["Tooth of Morphaz"] = "ฟันของ Morphaz" },
        },
    },
    [9051] = { -- Toxic Test
        title = { "10:728471253:2007972658", "ทดสอบพิษ" },
        objective = { "121:390205261:1093162758", "ใช้ Devilsaur Barb แทง Devilsaur แล้วกลับไปหา Torwa Pathfinder ที่ Un'Goro Crater เมื่อทำสำเร็จ" },
        description = { "404:1510052376:311900890", "พิษที่เจ้าช่วยข้าปรุงมีไว้เพื่อจุดประสงค์พิเศษ Devilsaur ตัวมหึมาในปล่องภูเขาไฟทำให้การล่าอันตราย และข้าเอาชีวิตรอดได้ยาก แม้ข้าจะแข็งแรงพอฆ่ามัน ตัวอื่นก็เพียงเข้ามายึดอาณาเขตแทน\n\nนำเงี่ยงอาบพิษนี้ไปแทงลึกเข้าไปในตัว Devilsaur ที่ยังมีชีวิต พิษน่าจะทำให้มันสงบลง แม้ข้าจะไม่รู้ว่าต้องใช้เวลานานเท่าไร..." },
        progress = { "40:387746926:422332893", "เจ้าทำให้สัตว์ร้ายยักษ์สงบลงได้หรือไม่?" },
        completion = { "11:1191658970:1224418299 N 76:1625348548:1211902355", "ขอบใจ {name} เจ้าทั้งกล้าหาญและฉลาด\n\nบอกข้าที Devilsaur มีปฏิกิริยาต่อพิษอย่างไร?" },
    },
    [9052] = { -- Bloodpetal Poison
        title = { "17:887247566:715878178", "พิษจาก Bloodpetal" },
        objective = { "90:1871608916:1453633141", "รวบรวม Bloodcap 8 ชิ้น และ Gorishi Sting 8 ชิ้น แล้วกลับไปหา Torwa Pathfinder ที่ Un'Goro Crater" },
        description = { "152:1225077375:754548920 C 264:521138365:648997166", "ข้าอยากให้เจ้าช่วยปรุงพิษชนิดหนึ่ง เพื่อทำให้สัตว์ร้ายยักษ์ที่อยู่ในปล่องภูเขาไฟสงบลง พิษนี้ไม่ถึงตาย และต้องอาศัยสายตาเฉียบคมของ {class} จึงจะหาส่วนผสมได้\n\nเห็ด Bloodcap งอกอยู่ในหน่อ Bloodpetal ทั่วปล่องภูเขาไฟ ส่วน Gorishi Sting ได้จากตัวต่อบินได้ขนาดยักษ์ ภายในและรอบ Slithering Scar ทางใต้ของปล่องภูเขาไฟ" },
        progress = { "26:26410076:1817494715", "เจ้าทำสำเร็จหรือยัง?" },
        completion = { "97:1770900292:925652862", "ในที่สุดก็ได้ส่วนผสม!\n\nเมื่อใช้ดิน Un'Goro ที่ข้ารวบรวมไว้ ก็ปรุงพิษได้ไม่ยาก..." },
        required = { [22435] = { "13:2037207286:1557650128", "เหล็กใน Gorishi" }, [22434] = { "8:147618109:1396299749", "เห็ดหมวกโลหิต" } },
        objectiveLabels = {
            item = { ["Gorishi Sting"] = "เหล็กใน Gorishi", ["Bloodcap"] = "เห็ดหมวกโลหิต" },
        },
    },
    [9053] = { -- A Better Ingredient
        title = { "19:1727468489:1316495311", "ส่วนผสมที่ดีกว่า" },
        objective = { "107:1816392590:1295718106", "เก็บ Putrid Vine จากผู้พิทักษ์ที่ก้น Sunken Temple แล้วกลับไปหา Torwa Pathfinder" },
        description = { "375:425362984:725592818", "เป็นอย่างที่ข้ากลัว พิษอ่อนเกินไปสำหรับสัตว์ที่ทรงพลังเช่นนั้น\n\nหากจะปรุงพิษให้แรงพอ เจ้าต้องลงไปก้น Temple of Atal'Hakkar ไขความลับของแท่นบูชา แล้วเก็บเถาวัลย์เน่าเปื่อยจากผู้พิทักษ์ที่นั่น วิหารอันตราย เจ้าควรพาเพื่อนไปด้วย\n\nกลับมาหาข้าเมื่อทำสำเร็จ" },
        progress = { "28:1650604814:1682167500", "เจ้าได้เถาวัลย์มาหรือยัง?" },
        completion = { "204:1505658856:298372326 N 1:46:46", "ในที่สุดก็ปรุงพิษได้สมบูรณ์แล้ว ข้าไม่กล้าขอให้เจ้าไปใช้กับสัตว์ตนนั้นอีก เพราะขอมากเกินไปแล้ว\n\nข้าขอบคุณและนับถือเจ้า ขอให้เดินทางโดยสวัสดิภาพ {name}" },
        required = { [22444] = { "11:201262362:2036365851", "เถาวัลย์เน่าเหม็น" } },
        objectiveLabels = {
            item = { ["Putrid Vine"] = "เถาวัลย์เน่าเหม็น" },
        },
    },
    [9063] = { -- Torwa Pathfinder
        title = { "16:328570135:1797802153", "Torwa Pathfinder" },
        objective = { "46:1160144206:1549173549", "คุยกับ Torwa Pathfinder ที่ Un'Goro Crater" },
        description = { "300:1453048495:1435250189", "พรานชื่อ Torwa Pathfinder ขอความช่วยเหลือจากดรูอิด เขาบอกว่ามีเพียงพวกเราที่มีทั้งทักษะที่จำเป็นและความเคารพธรรมชาติมากพอจะช่วยได้\n\nมีถนนเชื่อม Un'Goro Crater กับทะเลทราย Tanaris ตรงที่ถนนเข้าสู่ปล่องภูเขาไฟ เจ้าจะพบ Torwa อยู่ใกล้ ๆ" },
        completion = { "39:1231894803:1988208581 C 28:1970738653:308876566", "เจ้าเดินทางมาไกลเพื่อพบข้า {class} และมาได้ทันเวลาพอดี" },
    },
    [7503] = { -- The Greatest Race of Hunters
        title = { "28:1502392187:206362071", "เผ่าพันธุ์พรานผู้ยิ่งใหญ่ที่สุด" },
