    [7632] = { -- The Ancient Leaf
        title = { "16:1068873476:908144066", "ใบไม้โบราณ" },
        objective = { "82:1237583364:1266692883", "ตามหาเจ้าของ Ancient Petrified Leaf ขอให้โชคดี {name} โลกนี้กว้างใหญ่นัก" },
        description = { "266:1995073021:644811227", "ผิวใบไม้เรืองแสงสีเขียวสด พื้นผิวขรุขระเป็นร่องมาก เผยให้เห็นเส้นใบและรอยย่นหลายแห่ง\n\nหากต้องคาดเดา คุณคงคิดว่าใบไม้นี้มาจากสิ่งที่เก่าแก่และทรงพลัง\n\nบางทีคุณควรตามหาเจ้าของเดิมของใบไม้นี้?" },
        progress = { "17:1277335212:870807501", "<Vartrus คราง>" },
        completion = { "108:1224060020:1558578718 C 54:261900400:1720871020", "แน่นอนว่าข้าจำใบไม้ของตัวเองได้ ดูสิ! ยังอยู่ในสภาพสมบูรณ์\n\nดีจริงที่เจ้านำมันมาคืน {class}\n\nบางทีเจ้าอาจช่วยพวกเราได้ และพวกเราก็ช่วยเจ้าได้เช่นกัน" },
    },
    [7634] = { -- Ancient Sinew Wrapped Lamina
        title = { "28:1857497122:1864389682", "ใบไม้พันเอ็นมังกรโบราณ" },
        objective = { "135:1224485538:676030510", "Hastat the Ancient ขอให้คุณนำ Mature Blue Dragon Sinew มาให้ หากได้เอ็นนี้แล้ว ให้นำกลับไปให้ Hastat ที่ Felwood" },
        description = { "11:927657569:725753248 C 342:414103261:530191669", "สวัสดี {class} ข้าคือ Hastat ผู้โบราณแห่งภูมิปัญญา ข้าครอบครองความรู้ที่สูญหายไปเนิ่นนาน\n\nหากยึดให้ถูกวิธี ใบไม้ของข้าใบหนึ่งจะใช้เป็นกระบอกลูกธนูชนิดที่ไม่มีใครได้เห็นมาหนึ่งหมื่นปี เมื่อใช้ร่วมกับธนูของเหล่าผู้โบราณ มันอาจมอบพลังมหาศาลเกินบรรยาย\n\nกลับมาพร้อมเอ็นของมังกรน้ำเงินโตเต็มวัย แล้วกระบอกลูกธนูนี้จะเป็นของเจ้า" },
        progress = { "20:775022872:199677403 C 1:46:46", "ยินดีต้อนรับกลับ {class} รุ่นเยาว์" },
        completion = { "125:1096381839:311963474", "ขอให้ใบไม้ของข้าปกป้องลูกธนูของเจ้าจากอันตราย ขอให้ลูกธนูพุ่งตรงสู่เป้าหมาย และขอให้ศัตรูของโลกเราถูกโค่นลง" },
        required = { [18704] = { "24:1891249159:1393571187", "เอ็นมังกรสีน้ำเงินโตเต็มวัย" } },
        objectiveLabels = {
            item = { ["Mature Blue Dragon Sinew"] = "เอ็นมังกรสีน้ำเงินโตเต็มวัย" },
        },
    },
    [7635] = { -- A Proper String
        title = { "15:22868512:1087820043", "สายธนูที่คู่ควร" },
        objective = { "134:351049221:1709983545", "Stoma the Ancient ขอให้คุณนำ Mature Black Dragon Sinew มาให้ หากได้เอ็นนี้แล้ว ให้นำกลับไปให้ Stoma ที่ Felwood" },
        description = { "317:354523697:1948221689", "Vartrus อาจมอบคันธนูให้เจ้าสร้างธนูของเหล่าผู้โบราณ แต่มีเพียงข้าที่ลงอาคมให้สายธนูซึ่งจำเป็นต่อการสร้างให้สมบูรณ์ได้\n\nเป็นงานง่าย ๆ เจ้าตัวจ้อย ฆ่ามังกรดำโตเต็มวัยแล้วเลาะเอ็นจากกระดูกของมัน นำเอ็นนั้นกลับมาให้ข้า ข้าจะลงอาคมให้กลายเป็นสายธนูที่แทบทำลายไม่ได้" },
        progress = { "89:1168554077:2123527473 N 41:212982905:1646913885", "ข้ามั่นใจว่าเจ้าไม่น่าลำบากในการหามังกรดำและสังหารมัน {name} อย่าทำให้ข้าเสียเวลากับการพูดคุยไร้สาระ" },
        completion = { "146:1376634540:1200974932", "มังกรตนนี้ชั่วร้ายยิ่งนัก เอ็นของมันส่งกลิ่นแห่งความชั่ว\n\nให้เวลาข้าชำระความโสมมจากเนื้อนี้ และลงอาคมที่เหมาะสมสักครู่" },
        required = { [18705] = { "25:727670819:1994290394", "เอ็นมังกรสีดำโตเต็มวัย" } },
        objectiveLabels = {
            item = { ["Mature Black Dragon Sinew"] = "เอ็นมังกรสีดำโตเต็มวัย" },
        },
    },
    [7636] = { -- Stave of the Ancients
        title = { "21:1370328653:2007801941", "คันธนูแห่งเหล่าผู้โบราณ" },
        objective = { "355:1203998176:1277715742", "คุณต้องตามหาและทำลายปีศาจผู้แผ่ความเสื่อมทรามทั้งสี่:\n\nSimone the Seductress\n\nKlinfran the Crazed\n\nSolenor the Slayer\n\nArtorius the Doombringer\n\nกำจัดพวกมัน แล้วนำหัวกลับไปให้ Vartrus the Ancient ที่ Felwood\n\nอ่านเบาะแสที่อยู่ของเป้าหมายจาก Petrified Bark ในกระเป๋า\n\nคุณต้องทำภารกิจนี้เพียงลำพัง" },
        description = { "60:2074755979:1291066946 C 149:1003730410:1835038715 N 286:217586226:1324786119", "สมุน Burning Legion ยังเคลื่อนไหวอยู่ในโลกของเรา {class} พวกมันทำให้ทุกสิ่งที่สัมผัสเสื่อมทราม ธรรมชาติเหี่ยวเฉาและร่ำไห้เมื่อพวกมันปรากฏ\n\nเจ้าต้องตามล่าปีศาจผู้แผ่ความเสื่อมทรามเหล่านี้แล้วทำลายมัน {name} ระวังไว้ เจ้าต้องเข้าต่อสู้เพียงลำพัง ไม่เช่นนั้นมันจะหนี ตราบใดที่เจ้าอยู่คนเดียว พวกมันจะพยายามทำลายเจ้า จงโจมตีให้ความหยิ่งผยองกลับกลายเป็นความทุกข์ของมัน\n\nข้ามอบเปลือกไม้ชิ้นหนึ่งให้เจ้า รอยจารึกจะนำทางไปสู่เป้าหมาย จงนำหัวของพวกมันกลับมา" },
        progress = { "36:1752417808:514520343", "อย่าหลงกลรูปลักษณ์ปลอมของพวกมัน!" },
        completion = { "25:1299577151:97058099 N 128:1685958348:1962990", "เจ้าช่วยพวกเราได้ดี {name}! นำคันธนูนี้ไปรวมกับสายที่ Stoma สร้างได้ ทั้งสองจะกลายเป็นอาวุธที่ทรงพลังยิ่ง" },
        required = { [18952] = { "13:126706485:1309211157", "ศีรษะของ Simone" }, [18953] = { "15:1679605589:2048865902", "ศีรษะของ Klinfran" }, [18954] = { "14:257080672:60377954", "ศีรษะของ Solenor" }, [18955] = { "15:119625684:1127932347", "ศีรษะของ Artorius" } },
        objectiveLabels = {
            item = { ["Simone's Head"] = "ศีรษะของ Simone", ["Klinfran's Head"] = "ศีรษะของ Klinfran", ["Solenor's Head"] = "ศีรษะของ Solenor", ["Artorius's Head"] = "ศีรษะของ Artorius" },
        },
    },
    [303] = { -- The Dark Iron War
        title = { "17:975548412:476993461", "สงครามกับ Dark Iron" },
        objective = { "144:1194647503:206809651", "Motley Garmason ที่ Dun Modr ต้องการให้คุณฆ่า Dark Iron Dwarf 10 คน, Dark Iron Tunneler 5 คน, Dark Iron Saboteur 5 คน และ Dark Iron Demolitionist 5 คน", variants = { { "144:707295258:1912547109", "Motley Garmason ที่ Dun Modr ต้องการให้คุณฆ่า Dark Iron Dwarf 15 คน, Dark Iron Tunneler 5 คน, Dark Iron Saboteur 5 คน และ Dark Iron Demolitionist 5 คน" } } },
        description = { "469:1175631977:1780263973", "สงครามโหมกระหน่ำทั้งในบ้านเกิดและต่างแดน ขณะที่ทหารคนแคระผู้แข็งแกร่งสละชีวิตในดินแดนห่างไกลเพื่อนามแห่ง Alliance บ้านของเรากลับตกเป็นเหยื่อความชั่วร้ายของคนแคระ Dark Iron พวกมันทำลาย Thandol Span จนย่อยยับ และ Dun Modr ก็แตกในเวลาไม่นาน\n\nเราต้องการให้เจ้ารวบรวมกำลังแล้วผลักแนวรบกลับ หากฆ่า Dark Iron Dwarf 15 คน, Tunneler 5 คน, Saboteur 5 คน และ Demolitionist 5 คนได้ กำลังสำรองอาจมาทันไล่พวกมันให้สิ้น\n\nรีบลงมือ!" },
        progress = { "110:1121712425:400524446 C 59:51343230:1037195398", "Roggo ติดต่อกำลังสำรองไม่ได้ เราต้องกดดันค่าย Dark Iron ด้วยการโจมตี {class} กลับออกไปทำหน้าที่เพื่อกษัตริย์ Magni เดี๋ยวนี้!" },
        completion = { "29:126509805:970139277 C 278:27538481:1529018636", "เจ้าปฏิบัติตามคำสั่งได้ดี {class} พิสูจน์แล้วว่าเป็นทหารกล้าและผู้รับใช้ที่ภักดีต่อกษัตริย์ Magni ข้าขอคารวะ! การที่เจ้ากดดันค่าย Dark Iron ทำให้เรามีโอกาสขับไล่พวกมันออกจากดินแดนอย่างถาวร... ขอเพียงกำลังสำรองเจ้ากรรมจะมาถึงเสียที..." },
        objectiveLabels = {
            monster = { ["Dark Iron Dwarf slain"] = "ปราบ คนแคระ Dark Iron", ["Dark Iron Tunneler slain"] = "ปราบ คนขุดอุโมงค์ Dark Iron", ["Dark Iron Saboteur slain"] = "ปราบ นักก่อวินาศกรรม Dark Iron", ["Dark Iron Demolitionist slain"] = "ปราบ มือระเบิด Dark Iron" },
        },
    },
    [304] = { -- A Grim Task
        title = { "11:1774324521:430533531", "ภารกิจอันหม่นหมอง" },
        objective = { "83:617892780:429163233", "ฆ่า Balgaras the Foul แล้วนำหูของเขาไปให้ Longbraid the Grim ที่นอก Dun Modr" },
        description = { "498:543902304:1534947071 C 1:46:46", "ทหารของข้าตายมากมายในศึก Dun Modr พี่น้องของข้าเองก็สิ้นชีวิตเมื่อสะพานตะวันตกของ Thandol Span ถูกทำลาย ใช่ คนแคระ Dark Iron เป็นพวกชั่วร้าย จากข้อมูลที่ Roggo รวบรวมได้ หัวหน้าพวกอันธพาลใน Wetlands เป็นวอร์ล็อกชื่อ Balgaras the Foul แต่มันขี้ขลาดนัก ส่งทหารไปทำตามคำสั่ง ส่วนตัวเองคอยหลบหลีกอันตราย\n\nถ้าเจ้าหาตัวไอ้ขี้ขลาดนั่นพบ จงฆ่าแล้วนำหูมันมาให้ข้า ข้าจะให้รางวัล {class}" },
        progress = { "47:287055782:1031198582 C 45:1263780380:174772555", "เจ้าเจอ Balgaras the Foul แล้วหรือยัง {class}? มันหลบเลี่ยงพวกเรามานานทีเดียว" },
        completion = { "364:1095151610:883270832 C 1:46:46", "ในที่สุด Balgaras the Foul ก็ตาย แม้ความตายของมันจะไม่อาจนำคนแคระผู้บริสุทธิ์ที่ถูกฆ่าอย่างไร้เหตุผลกลับมา แต่ก็จะช่วยให้ผู้รอดชีวิตสงบใจขึ้น เมื่อ Balgaras ตาย พวก Dark Iron ที่เหลือน่าจะจัดการได้ง่าย เราต้องกวาดล้างพวกมันก่อนมีหัวหน้าคนใหม่ถูกส่งมา\n\nเจ้าทำได้ดี {class}" },
        required = { [3639] = { "15:823248297:696601844", "หูของ Balgaras" } },
        steps = { { "15:823248297:696601844", "หูของ Balgaras" } },
    },
    [455] = { -- The Algaz Gauntlet
        title = { "18:1169262228:2146568767", "ฝ่าด่าน Algaz" },
        objective = { "113:1958450071:733852603", "เดินทางผ่าน Dun Algaz\n\nฆ่า Dragonmaw Scout 8 คน และ Dragonmaw Grunt 6 คน\n\nรายงานต่อ Valstag Ironjaw ที่ Menethil Harbor" },
        description = { "471:1029224643:418980729 N 14:1156631296:1336435094", "ออร์คเผ่า Dragonmaw มีที่หลบภัยใน Wetlands และตอนนี้ขยายเข้ามาถึง Dun Algaz แล้ว! เราปล่อยให้พวกมันตั้งหลักที่นี่ไม่ได้ ไม่เช่นนั้น Loch Modan จะถูกตัดขาดจาก Menethil Harbor ท่าเรือและฐานที่มั่นของเราใน Wetlands\n\nฝ่า Dun Algaz ไปยัง Wetlands ที่อยู่อีกฟาก ฆ่าออร์คเสียบ้างด้วย แล้วรายงานต่อ Valstag Ironjaw ที่ Menethil Harbor\n\nทางไป Menethil คือผ่าน Dun Algaz ตามถนนขึ้นเหนือ แล้วเลี้ยวตะวันตกตรงทางแยก\n\nเราฝากความหวังไว้กับเจ้า {name} อย่าล้มเหลว" },
        progress = { "70:1199456432:2034635017", "เจ้ามาจาก Loch Modan หรือ? สถานการณ์ออร์คที่ Algaz Gate เป็นอย่างไรบ้าง?" },
        completion = { "207:719488692:708648681 N 60:1027824684:1896853127", "รายงานของเจ้ามีแต่ข่าวร้าย!\n\nข้าเห็นแล้วว่า Dragonmaw กำลังรุกเข้า Algaz อย่างหนัก ปกติพวกมันเพียงซ่อนตัวบนเนินเขา เหตุใดจึงยกกำลังเข้า Algaz ยังเป็นปริศนา...\n\nขอบใจ {name} และเราคงต้องการให้เจ้าช่วยจัดการออร์คเหล่านี้" },
        objectiveLabels = {
            event = { ["Traverse Dun Algaz"] = "เดินทางผ่าน Dun Algaz" },
            monster = { ["Dragonmaw Scout slain"] = "ปราบ หน่วยสอดแนม Dragonmaw", ["Dragonmaw Grunt slain"] = "ปราบ ทหารราบ Dragonmaw" },
        },
    },
    [464] = { -- War Banners
        title = { "11:1615813673:1486970923", "ธงศึก" },
        objective = { "51:185398394:634082764", "นำ Dragonmaw War Banner 8 ผืนไปให้ Captain Stoutfist" },
        description = { "470:111023409:245627533", "ออร์คเผ่า Dragonmaw เกือบถูกทำลายหมดเมื่อสิ้นสงครามครั้งที่สอง หลังสูญเสียการควบคุมมังกรแดงที่เลี้ยงไว้ มังกรไม่พอใจนายเก่าอย่างยิ่ง จึงตามล่า Dragonmaw อย่างดุเดือด ผู้รอดชีวิตไม่กี่คนหนีจาก Grim Batol ไปยังภูเขาทางตะวันออกของแหล่งขุดค้น Whelgar\n\nตอนนี้พวกมันฟื้นกำลังแล้ว และตั้งค่ายทางตะวันออกเฉียงเหนือของ Menethil\n\nเราต้องการให้เจ้าโจมตีค่ายนั้น เก็บธงศึกของพวกมันกลับมาให้ข้าเป็นหลักฐาน" },
        progress = { "43:2026423674:2021208511", "เจ้าโจมตีค่าย Dragonmaw แล้วหรือยัง?" },
        completion = { "13:1741805518:1537947876 N 416:1686735983:615271393", "ต่อสู้ได้ดี {name} Dragonmaw ไม่ใช่ภัยระดับเดียวกับตอนมีมังกรแล้ว แต่ยังเป็นคู่ต่อสู้ที่ดุร้าย\n\nหัวหน้าของพวกมันคือ Nek'rosh บุตร Nekros ผู้เคยนำ Dragonmaw เมื่อหลายปีก่อน Nekros ใช้เวทมนตร์ทรงพลังควบคุมมังกรแดง แต่เมื่อเวทมนตร์ล้มเหลว... พวกมังกรก็ไม่พอใจเลย\n\nNekros ถูกฆ่า และบุตรของเขาสาบานจะแก้แค้นมังกรที่สังหารบิดา" },
        required = { [3337] = { "20:1349463975:1251872094", "ธงศึก Dragonmaw" } },
        objectiveLabels = {
            item = { ["Dragonmaw War Banner"] = "ธงศึก Dragonmaw" },
        },
    },
    [465] = { -- Nek'rosh's Gambit
        title = { "17:1537781574:1888855839", "แผนเสี่ยงของ Nek'rosh" },
        objective = { "32:491692432:1755707693", "ทำลายเครื่องยิงหินของ Dragonmaw" },
        description = { "492:148827868:685622331", "ระหว่างเจ้าสู้กับ Dragonmaw เราพบข้อมูลแผนของพวกมันเพิ่ม\n\nNek'rosh สร้างเครื่องยิงหินและตั้งใจปิดล้อม Menethil! ยิ่งมีการสู้รบใน Dun Algaz ก็เท่ากับเราถูกตัดขาดจากกำลังเสริม!\n\nเจ้าต้องทำลายเครื่องยิงหินพวกนั้น มันอยู่ในค่าย Dragonmaw\n\nนี่ เอาเชื้อไฟนี้ไป ฝ่าศัตรูไปถึงเครื่องยิงหินแล้วจุดเผามัน\n\nเมื่อเสร็จแล้ว จงตามหาและฆ่า Nek'rosh เราต้องโค่นสัตว์ร้าย Dragonmaw ตนนี้... ด้วยการตัดหัวมัน", variants = { { "490:1126414169:1633407959", "พวก Dragonmaw ใกล้จะลงมือตามแผนโจมตีแล้ว เราคาดว่าจะมีเวลามากกว่านี้\n\nNek'rosh สร้างเครื่องยิงหินและตั้งใจปิดล้อม Menethil! ยิ่งมีการสู้รบใน Dun Algaz ก็เท่ากับเราถูกตัดขาดจากกำลังเสริม!\n\nเจ้าต้องทำลายเครื่องยิงหินพวกนั้น มันอยู่ในค่าย Dragonmaw\n\nนี่ เอาเชื้อไฟนี้ไป ฝ่าศัตรูไปถึงเครื่องยิงหินแล้วจุดเผามัน\n\nเมื่อเสร็จแล้ว จงตามหาและฆ่า Nek'rosh เราต้องโค่นสัตว์ร้าย Dragonmaw ตนนี้... ด้วยการตัดหัวมัน" } } },
        progress = { "57:1188149070:742695542", "เครื่องยิงหินเครื่องแรกอยู่ตรงหน้า คุณจะจุดไฟเผามันหรือไม่?" },
        completion = { "107:1441506642:1150796911", "คุณวางเชื้อไฟส่วนหนึ่งบนเครื่องยิงหิน แล้วตีสะเก็ดไฟใส่\n\nเปลวไฟลุกและลามอย่างรวดเร็ว!" },
        required = { [3339] = { "14:462212420:1867354286", "เชื้อจุดไฟแบบคนแคระ" } },
        steps = { { "14:462212420:1867354286", "เชื้อจุดไฟแบบคนแคระ" } },
    },
    [468] = { -- Report to Mountaineer Rockgar
        title = { "29:1695326642:1824852892", "รายงานต่อ Mountaineer Rockgar" },
        objective = { "31:223555134:852198126", "คุยกับ Mountaineer Rockgar" },
        description = { "263:473465565:1616517609", "Mountaineer Rockgar กำลังหาอาสาสมัครทำภารกิจผ่าน Dun Algaz เข้าสู่ Wetlands\n\nถ้าเจ้าอยากให้รองเท้าเปียกในดินแดนชุ่มน้ำทางเหนือ ก็ไปคุยกับ Rockgar ที่ Dun Algaz ตามถนนขึ้นเหนือเลยหอคอยยามไปก็ถึง Dun Algaz" },
        completion = { "7:989913233:66981971 C 171:886380942:1074586020", "สวัสดี {class}! เจ้ามาทำภารกิจสอดแนมหรือ? ดีมาก!\n\nหวังว่าอุปกรณ์ของเจ้าจะพร้อม เพราะภารกิจ \"สอดแนม\" นี้เปลี่ยนเป็นงานที่เลอะเทอะกว่าเดิมแล้ว..." },
    },
    [469] = { -- Daily Delivery
        title = { "14:1713141596:426570601", "ส่งของประจำวัน" },
        objective = { "88:2082823767:91931533", "นำ Bundle of Crocolisk Skins ไปให้ James Halloran ช่างฟอกหนังที่ Menethil Harbor" },
        description = { "486:1231571574:1568680675", "สวัสดี นักเดินทาง!\n\nเจ้าจะไปทาง Menethil หรือเปล่า? ถ้าไม่ได้ไป ข้าก็แนะนำให้แวะ ที่นั่นเหมาะซื้อของ หรือดื่มสักแก้วพักผ่อนด้วย\n\nแต่ถ้าเจ้าบังเอิญจะไปทางนั้น ช่วยนำหนังจระเข้มัดนี้ไปให้ James Halloran ช่างฟอกหนังทีได้ไหม?\n\nข้าคงไปเองแล้ว แต่ช่วงนี้ภรรยาอารมณ์ไม่ค่อยดี ข้าเลยอยากเลื่อนการกลับไปเจอนางให้นานที่สุด" },
        progress = { "13:1911146197:485773127 C 74:1258246102:252387096", "สวัสดี {class} สนใจรองเท้าสักคู่ไหม? หรือหนังที่เพิ่งฟอกใหม่?" },
        completion = { "198:57661436:927479535", "อืม ของจาก Einar ใช่ไหม? เขาไม่ได้มาส่งหนังด้วยตัวเองเกือบสัปดาห์แล้ว ต้องมีเรื่องไม่ลงรอยกับภรรยาแน่!\n\nบางทีข้าคงต้องให้ภรรยาข้าไปคุยกับ Sida สักหน่อย..." },
        required = { [3347] = { "25:940745501:1909450994", "มัดหนังครอโคลิสก์" } },
        steps = { { "25:940745501:1909450994", "มัดหนังครอโคลิสก์" } },
    },
    [472] = { -- Fall of Dun Modr
        title = { "16:56304340:1158570515", "การล่มสลายของ Dun Modr" },
        objective = { "47:1601392164:1828184889", "ตามหา Longbraid ใกล้เมือง Dun Modr" },
        description = { "67:1348087971:935302451 C 405:83998063:656524584 R 1:33:33", "Dun Modr ตกอยู่ในมือคนแคระ Dark Iron แล้ว!\n\nข้าบาดเจ็บสาหัส {class} ทหารส่วนใหญ่ในกองถูกฆ่า! พวกอันธพาล Dark Iron โจมตีก่อนที่เราจะรวมกำลังได้หลังถูกซุ่มโจมตีที่ Thandol Span\n\nLongbraid ผู้นำของเราเป่าแตรถอย ระหว่างออกจากเมือง ข้าถูกขวานหลงฟันเข้าที่หลัง แล้วทุกอย่างก็มืดไป\n\nข้าฟื้นขึ้นที่ Menethil แต่ยังหวาดหวั่นแทนเพื่อนทหาร ในใจข้ายังมีความหวัง บางที Longbraid อาจมีชีวิตอยู่! ลองตามหาเขาใกล้ Dun Modr ที {race}!" },
        completion = { "11:1856137578:1345206049 C 30:1743136205:1805813035 N 372:481148147:1133466156", "{class} ผู้กล้าคนใดนำข่าวมาจาก Menethil? อา เจ้ามีชื่อว่า {name}\n\nเจ้านำความหวังมาสู่สถานการณ์สิ้นหวัง ดีจริงที่หนุ่ม Harlo รอดชีวิต ระหว่างหนีเขาบาดเจ็บสาหัส เรามีเวลาเพียงน้อยนิดที่จะส่งเขาขึ้นม้าตัวเดียวที่รอดในกองแล้วปล่อยไป\n\nแต่ตอนนี้เรายังเผชิญอันตราย Dun Modr แตกแล้ว และพวกเราเป็นเพียงเงาของกองทหารอันยิ่งใหญ่ที่เคยเป็น" },
    },
    [473] = { -- Report to Captain Stoutfist
        title = { "27:2033239321:573718384", "รายงานต่อ Captain Stoutfist" },
        objective = { "29:23153817:337441977", "คุยกับ Captain Stoutfist" },
        description = { "N 202:1528103910:755504486", "{name} ออร์คเผ่า Dragonmaw ไม่ได้แสดงกำลังอยู่แค่ Algaz เท่านั้น Captain Stoutfist ต้องการพูดกับผู้ยินดีช่วยต่อสู้กับออร์คเหล่านี้ เขาอยู่ในห้องวางแผนศึกภายในป้อม" },
        completion = { "N 89:2006533178:1092089998 R 37:637644544:1214798786", "{name} Valstag รายงานความสำเร็จของเจ้าในการจัดการออร์ค Dragonmaw ที่ Dun Algaz ให้ข้ารู้แล้ว เจ้าเป็น {race} ที่มีคุณค่า\n\nและข้ามีงานให้เจ้าทำ" },
    },
    [474] = { -- Defeat Nek'rosh
        title = { "15:182177578:370657953", "โค่น Nek'rosh" },
        objective = { "67:107554189:1717878261", "ฆ่า Chieftain Nek'rosh\n\nนำ Nek'rosh's Head ไปให้ Captain Stoutfist", variants = { { "68:440784914:821245751", "ฆ่า Chieftain Nek'rosh\n\nนำ Nek'rosh's Head ไปให้ Captain Stoutfist" } } },
        description = { "74:1334324264:1548941321", "เมื่อเผาเครื่องยิงหินแล้ว จงตามหาและฆ่า Chieftain Nek'rosh" },
        progress = { "25:65213376:1425310572", "เจ้าฆ่า Nek'rosh แล้วหรือยัง?" },
        completion = { "14:1603366731:354050798 N 163:1849635254:351293396 R 72:2098503235:1814600765", "ทำได้หนักแน่นดี {name} เจ้าสร้างความเสียหายอย่างใหญ่หลวงแก่เผ่าออร์ค Dragonmaw พวกมันอาจไม่มีวันฟื้น และการทำลายเครื่องยิงหินก็ทำให้ Menethil Harbor ปลอดภัย\n\nเจ้าเป็น {race} ผู้มีความชอบ และอาณาจักร Ironforge ย่อมตอบแทนผู้รับใช้ที่ทำหน้าที่ได้ดี" },
        required = { [3625] = { "15:1161018618:217411355", "หัวของ Nek'rosh" } },
        objectiveLabels = {
            item = { ["Nek'rosh's Head"] = "หัวของ Nek'rosh" },
        },
    },
    [631] = { -- The Thandol Span
        title = { "16:1840767632:2121659253", "สะพาน Thandol Span" },
        objective = { "48:1717103236:425712770", "Rhag Garmason ต้องการให้คุณตามหา Ol' Rustlocke" },
        description = { "484:650959863:52757613", "เสียงระเบิดมหึมาดังก้องผ่านเนินเขา ข้าขอบอกว่ามันน่ากลัวเหลือเกิน!\n\nทหารดี ๆ ตายขณะป้องกัน Thandol Span Longbraid บอกว่าก่อนเรื่องนี้จบ เราต้องแก้แค้น Dark Iron\n\nแต่เราลำบากหนัก และไม่มีวี่แววกำลังเสริม Longbraid ส่ง Ol' Rustlocke ไปสอดแนมสะพานตะวันออก ดูว่าจะรักษามันไว้ได้ไหม\n\nนั่นก็หลายวันแล้ว เมื่อ Dun Modr ถูกปิดล้อม เราไม่มีกำลังคนพอออกตามหาเขา\n\nบางทีเจ้าอาจหาเขาพบ..." },
        completion = { "103:1972256781:68747071", "คุณค้นศพคนแคระร่างเล็ก บนหมวกมีชื่อสลักไว้อ่านได้ชัดเจน: Ebenezer Rustlocke" },
    },
    [632] = { -- The Thandol Span
        title = { "16:1840767632:2121659253", "สะพาน Thandol Span" },
        objective = { "88:806213235:268829615", "กลับไปรายงาน Rhag Garmason และให้เขาดูแผ่นหนังที่พบกับศพ Rustlocke" },
        description = { "183:1699210276:1566848143", "ดูเหมือน Ol' Rustlocke ผู้น่าสงสารจะถูก Dark Iron ซุ่มโจมตี คุณสังเกตเห็นแผ่นหนังข้างกำปั้นที่กำแน่น\n\nกลับไปรายงานข่าวร้ายให้ Rhag Garmason และให้เขาดูสิ่งที่พบ" },
        progress = { "27:1522845380:1179428003 N 1:63:63", "มีร่องรอยของ Ol' Rustlocke บ้างไหม {name}?" },
        completion = { "28:920520395:1810315352", "โอ้ เป็นข่าวร้ายเหลือเกิน..." },
        required = { [4429] = { "17:2074628094:139388962", "คำสั่งของ Deepfury" } },
        steps = { { "17:2074628094:139388962", "คำสั่งของ Deepfury" } },
    },
    [633] = { -- The Thandol Span
        title = { "16:1840767632:2121659253", "สะพาน Thandol Span" },
        objective = { "32:1723869003:1677875527", "ทำลายคลังวัตถุระเบิด" },
        description = { "423:685816086:343335945 N 67:1056177614:163586623", "สวรรค์ ไม่จริง! Rustlocke ผู้น่าสงสาร ช่างเป็นโศกนาฏกรรม\n\nเราจะปล่อยให้เขาตายเปล่าไม่ได้ แผ่นหนังที่เจ้าพบบอกว่า Kam Deepfury ผู้วางแผนโจมตีครั้งแรก จัดให้ซ่อนคลังวัตถุระเบิดไว้ใน Arathi Highlands อีกฟากของ Thandol Span\n\nหากระเบิดเหล่านั้นถูกส่งถึงสะพาน เส้นทางส่งเสบียงหลักขึ้นเหนือของเราจะถูกตัดขาด! ต้องทำลายคลังนั้น {name}! กลับมาหาข้าเมื่อภารกิจสำเร็จ\n\nเจ้าเป็นความหวังเดียวของเรา" },
        progress = { "42:1816513150:1677999377", "ต้องทำลายคลังวัตถุระเบิด!" },
        completion = { "174:2035341363:1347735185", "สะพานที่เหลือรอดแล้ว! เจ้าทำคุณประโยชน์อย่างใหญ่หลวงต่อกษัตริย์ Magni และประชาชน Khaz Modan\n\nตอนนี้ขอเพียงเราจะยืนหยัดได้นานพอจนกำลังเสริมมาถึง..." },
        steps = { { "29:901637596:749747898", "ทำลายคลังวัตถุระเบิด" } },
    },
    [634] = { -- Plea To The Alliance
        title = { "20:575023144:1974025238", "คำวิงวอนถึง Alliance", variants = { { "20:944482685:2142446721", "คำวิงวอนถึง Alliance" } } },
        objective = { "40:765557088:142506654", "ตามหา Captain Nials ที่ Refuge Pointe" },
        description = { "35:459895825:19368341 C 289:766841721:1798276514", "ข้าขอให้เจ้าช่วยอีกเรื่องเล็กน้อย {class} เรากำลังรอกำลังสำรองจาก Ironforge แต่ Roggo รู้ว่ามีค่าย Alliance อยู่ทางเหนือใน Arathi Highlands ที่ Refuge Pointe\n\nเดินทางไปหา Captain Nials ที่นั่น ถามกัปตันว่า Alliance จะส่งทหารมาช่วยเรายึด Dun Modr และ Thandol Span คืนได้บ้างหรือไม่" },
        completion = { "440:2030766247:1179973538", "ข้าขอแสดงความเสียใจต่อ Longbraid และทหารกล้าของเขา ข่าวโศกนาฏกรรมที่ Thandol Span กับการล่มสลายของ Dun Modr ทำให้ข้าหนักใจ\n\nแต่ Stromgarde ก็แตกแล้ว! เราจึงมาอยู่ที่ Refuge Pointe และกำลังเผชิญภารกิจยึดเมืองอันยิ่งใหญ่ของเราคืนเช่นกัน\n\nเกียรติและหน้าที่ไม่ยอมให้เราจาก Highlands จนกว่า Stromgarde จะชูธงอันยิ่งใหญ่ของกษัตริย์อีกครั้ง ข้าจะส่งข่าวให้ Longbraid รู้ว่าเขาต้องพึ่งตนเอง..." },
    },
    [647] = { -- MacKreel's Moonshine
        title = { "20:425153039:632652108", "เหล้าเถื่อนของ MacKreel" },
        objective = { "62:24247688:1546311116", "นำ MacKreel's Moonshine ไปให้ Brewmeister Bilger ที่ Southshore" },
        description = { "473:955416888:1003406023", "เมื่อคืนข้าดื่มเหล้าเถื่อนไปเยอะทีเดียว! ถ้า Longbraid รู้ว่าข้าสลบระหว่างเข้าเวร คงตัดหัวข้าแน่\n\nปวดหัวเหลือเกิน รู้สึกเหมือนเครื่องล้อมเมืองทั้งกองวิ่งผ่านหัว เสียงครืนลั่นไปหมด\n\nโอ้ ดูเวลาสิ! ข้าสัญญากับ Brewmeister Bilger ที่ Southshore ว่าจะส่งเหล้าเถื่อนไปใช้หนี้\n\nแต่เหลือแค่ 15 นาทีก็จะเลยกำหนดแล้ว! ช่วยนำเหล้าชุดนี้ไปให้เขาที และรีบด้วย!" },
        progress = { "22:2123693112:1482298200 R 1:63:63", "มีข่าวดีอะไรหรือ {race}?" },
        completion = { "199:138982707:1155975126", "อา ไม่มีอะไรทำให้อุ่นใจในวันลมหนาวได้เท่าเหล้าเถื่อนของ Foggy MacKreel! ข้ากำลังคิดว่าเจ้าตัวแสบจะจ่ายหนี้ช้าอีกแล้ว ขอบใจ สหาย! ขอบใจมากจริง ๆ!" },
        required = { [4441] = { "20:425153039:632652108", "เหล้าเถื่อนของ MacKreel" } },
        steps = { { "20:425153039:632652108", "เหล้าเถื่อนของ MacKreel" } },
    },
    [1132] = { -- Fiora Longears
        title = { "14:1702713811:201351698", "Fiora Longears" },
        objective = { "72:380467228:1571838938", "คุยกับ Fiora Longears ที่ท่าเรือ Theramore ใน Dustwallow Marsh", variants = { { "39:209077459:1137191117", "คุยกับ Fiora Longears ใน Theramore" } } },
        description = { "159:169533428:643853210 C 327:1944774947:2033947604", "โอ้ อยากกลับไปอยู่กลางทะเลอีกครั้ง! สัมผัสจุมพิตของสายลม และให้คลื่นไกวข้าดั่งมารดาผู้เป็นที่รักเมื่อครั้งกระโน้น!\n\nข้าอยากมีโชคเช่นเจ้า {class} ผู้ใจดี เพราะข้ามองเห็นทะเลรอเจ้าอยู่เบื้องหน้า!\n\nงานของข้าคือบอกเหล่าผู้กระตือรือร้นถึงดินแดน Kalimdor ดินแดนแห่งโอกาส! หากเจ้าอยากลองเสี่ยงโชคข้ามทะเล ก็นั่งเรือจากที่นี่ไปยังท่าเรืองดงาม Theramore คุยกับเอลฟ์ Fiora Longears ผู้ร่วมงานของข้าที่นั่น\n\nนางจะเริ่มการผจญภัยใน Kalimdor ให้เจ้า!" },
        completion = { "177:350050783:1810159872", "สวัสดี! คุณ Flint ที่ Menethil Harbor ส่งเจ้ามาหรือ? เขาดูคนเก่งนัก หากส่งเจ้ามา ก็ไม่ต้องสงสัยเลยว่าเจ้าคู่ควรกับ Kalimdor!" },
    },
    [1302] = { -- James Hyal
        title = { "10:1116968347:72543511", "James Hyal" },
        objective = { "57:1764929330:1834810191", "คุยกับ Clerk Lendry ที่ Foothold Citadel ใน Theramore", variants = { { "37:1539930758:1220277182", "คุยกับ Clerk Lendry ใน Theramore" } } },
        description = { "384:30684972:1636025084", "James พี่น้องของข้าข้ามทะเลไปกับ Lady Proudmoore ข่าวล่าสุดที่ได้ยินคือการสู้รบที่นั่นสงบลง และ James กำลังเปิดโรงแรมที่ไหนสักแห่งบนทวีปนั้น ไม่ว่าจะอยู่ที่ไหน ข้ามั่นใจว่าธุรกิจเขาต้องดี เขาทำอาหารเก่งเหลือเกิน\n\nข้าไม่ได้ข่าวจากเขาพักหนึ่งแล้ว พนันได้ว่าคงยุ่งกับโรงแรม แต่เสมียนที่ Theramore น่าจะบอกได้ว่าเขาอยู่ไหน" },
        completion = { "246:1019206313:1842419216", "James Hyal, James Hyal... ทำไมชื่อนี้ฟังคุ้นนัก?\n\nอ้อ เหตุการณ์ที่ Shady Rest Inn นั่นเอง หากเจ้ามีข้อมูลว่าเกิดอะไรขึ้นที่นั่น ข้าขอให้ไปคุยกับ Captain Vimes เขาเป็นคนรับผิดชอบการสืบสวน" },
    },
    [1301] = { -- James Hyal
        title = { "10:1116968347:72543511", "James Hyal" },
        objective = { "43:2095130510:1075052686", "คุยกับ Vincent Hyal ที่ Menethil Harbor" },
        description = { "432:1243644947:1769747612", "ก่อนทำ Blue Recluse ข้าเรียนกับยอดพ่อครัวและเจ้าของโรงเตี๊ยมคนหนึ่ง James Hyal ทุกสิ่งที่มีและไปถึงในชีวิต ขอบคุณเขา\n\nสงสัยว่าเป็นอย่างไร เขากับ Vincent พี่น้องไปทำร้านใน Menethil Harbor แต่ไม่ได้ข่าวระยะนี้\n\nหากไปทางนั้น ฝากสวัสดีแทนข้าได้ไหม?" },
        completion = { "226:886708840:513751612", "James หรือ? ไปนานแล้ว\n\nคงรู้สึกรักชาติขึ้นอีกหน ไม่แปลก จากความบ้าใน Lordaeron คนมากร่วม Jaina Proudmoore ข้ามทะเล" },
    },
    [5805] = { -- Welcome!
        title = { "8:1157429440:1900744790", "ยินดีต้อนรับ!" },
        progress = { "132:1057634608:967750197", "สวัสดี! ยินดีที่ได้รู้จัก!\n\nข้าเห็นว่าเจ้ามีบัตรพิเศษ มอบให้ข้า แล้วข้าจะมีสิ่งของให้แลกเปลี่ยน" },
        completion = { "31:844644996:1050364761 N 82:1617086532:2042110772", "เจ้าเป็นวีรชนคนพิเศษจริง ๆ {name} เรายินดีต้อนรับเจ้าสู่โลก Azeroth และขอมอบของขวัญพิเศษเหล่านี้ให้เลือก!" },
        objective = { "54:205517065:717901614", "นำ Northshire Gift Voucher ไปให้ Merissa Stilwell" },
        description = { "336:465457358:1548323827", "ยินดีต้อนรับสู่ World of Warcraft!\n\nเพื่อขอบคุณเป็นพิเศษที่ซื้อ World of Warcraft Collector's Edition ให้นำบัตรของขวัญนี้ไปส่งให้ Merissa Stilwell ใน Northshire Valley แล้วท่านจะได้รับของขวัญเป็นเพื่อนตัวน้อยที่จะร่วมเดินทางไปผจญภัยและแสวงหาเกียรติยศกับท่าน\n\nขอบคุณอีกครั้ง ขอให้สนุกกับเวลาของท่านใน World of Warcraft!" },
        required = { [14646] = { "23:1723014170:832463623", "บัตรแลกของขวัญ Northshire" } },
        steps = { { "23:1723014170:832463623", "บัตรแลกของขวัญ Northshire" } },
    },
    [5841] = { -- Welcome!
        title = { "8:1157429440:1900744790", "ยินดีต้อนรับ!" },
        objective = { "58:1145367259:1589727456", "นำ Coldridge Valley Gift Voucher ไปให้ Yori Crackhelm" },
        description = { "333:1463318331:78155714", "ยินดีต้อนรับ World of Warcraft!\n\nเพื่อขอบคุณที่ซื้อ World of Warcraft Collector's Edition นำใบรับของขวัญนี้ไปให้ Yori Crackhelm ใน Coldridge Valley แล้วจะได้ของขวัญ สหายตัวน้อยร่วมแสวงการผจญภัยและเกียรติยศ\n\nขอบใจอีกครั้ง ขอให้สนุกใน World of Warcraft!" },
        progress = { "128:624572785:1035059730", "สวัสดี! ยินดีพบเจ้า!\n\nเห็นว่ามีใบรับของขวัญพิเศษ ส่งมา ข้าจะให้ของแลก" },
        completion = { "31:844644996:1050364761 N 82:1617086532:2042110772", "เจ้าเป็นวีรชนคนพิเศษจริง ๆ {name} เรายินดีต้อนรับเจ้าสู่โลก Azeroth และขอมอบของขวัญพิเศษเหล่านี้ให้เลือก!" },
        required = { [14647] = { "29:234136279:1012038891", "บัตรแลกของขวัญ Coldridge Valley" } },
        steps = { { "29:234136279:1012038891", "บัตรแลกของขวัญ Coldridge Valley" } },
    },
    [5843] = { -- Welcome!
        title = { "8:1157429440:1900744790", "ยินดีต้อนรับ!" },
        completion = { "31:844644996:1050364761 N 82:1617086532:2042110772", "เจ้าเป็นวีรชนคนพิเศษจริง ๆ {name} เรายินดีต้อนรับเจ้าสู่โลก Azeroth และขอมอบของขวัญพิเศษเหล่านี้ให้เลือก!" },
        progress = { "128:624572785:1035059730", "สวัสดี! ยินดีพบเจ้า!\n\nเห็นว่ามีใบรับของขวัญพิเศษ ส่งมา ข้าจะให้ของแลก" },
        objective = { "49:1472407182:75396544", "นำ Valley of Trials Gift Voucher ไปให้ Magga" },
        description = { "328:1554017383:9493854", "ยินดีต้อนรับสู่ World of Warcraft!\n\nเพื่อขอบคุณเป็นพิเศษที่ซื้อ World of Warcraft Collector's Edition ให้นำบัตรของขวัญนี้ไปส่งให้ Magga ใน Valley of Trials แล้วท่านจะได้รับของขวัญเป็นเพื่อนตัวน้อยที่จะร่วมเดินทางไปผจญภัยและแสวงหาเกียรติยศกับท่าน\n\nขอบคุณอีกครั้ง ขอให้สนุกกับเวลาของท่านใน World of Warcraft!" },
        required = { [14649] = { "29:676717137:1248566177", "บัตรแลกของขวัญ Valley of Trials" } },
        steps = { { "29:676717137:1248566177", "บัตรแลกของขวัญ Valley of Trials" } },
    },
    [5844] = { -- Welcome!
        title = { "8:1157429440:1900744790", "ยินดีต้อนรับ!" },
        progress = { "132:1057634608:967750197", "สวัสดี! ยินดีที่ได้รู้จัก!\n\nข้าเห็นว่าเจ้ามีบัตรพิเศษ มอบให้ข้า แล้วข้าจะมีสิ่งของให้แลกเปลี่ยน" },
        completion = { "31:844644996:1050364761 N 82:1617086532:2042110772", "เจ้าเป็นวีรชนคนพิเศษจริง ๆ {name} เรายินดีต้อนรับเจ้าสู่โลก Azeroth และขอมอบของขวัญพิเศษเหล่านี้ให้เลือก!" },
        objective = { "52:1200756940:318853254", "นำ Camp Narache Gift Voucher ไปให้ Vorn Skyseer" },
        description = { "327:577758899:41591664", "ยินดีต้อนรับสู่ World of Warcraft!\n\nเพื่อขอบคุณเป็นพิเศษที่ซื้อ World of Warcraft Collector's Edition ให้นำบัตรของขวัญนี้ไปส่งให้ Vorn Skyseer ใน Camp Narache แล้วท่านจะได้รับของขวัญเป็นเพื่อนตัวน้อยที่จะร่วมเดินทางไปผจญภัยและแสวงหาเกียรติยศกับท่าน\n\nขอบคุณอีกครั้ง ขอให้สนุกกับเวลาของท่านใน World of Warcraft!" },
        required = { [14650] = { "25:685915766:1128890020", "บัตรแลกของขวัญ Camp Narache" } },
        steps = { { "25:685915766:1128890020", "บัตรแลกของขวัญ Camp Narache" } },
    },
    [5847] = { -- Welcome!
        title = { "8:1157429440:1900744790", "ยินดีต้อนรับ!" },
        progress = { "132:1057634608:967750197", "สวัสดี! ยินดีที่ได้รู้จัก!\n\nข้าเห็นว่าเจ้ามีบัตรพิเศษ มอบให้ข้า แล้วข้าจะมีสิ่งของให้แลกเปลี่ยน" },
        completion = { "31:844644996:1050364761 N 82:1617086532:2042110772", "เจ้าเป็นวีรชนคนพิเศษจริง ๆ {name} เรายินดีต้อนรับเจ้าสู่โลก Azeroth และขอมอบของขวัญพิเศษเหล่านี้ให้เลือก!" },
        objective = { "67:1937737834:799616435", "นำ Deathknell Gift Voucher ไปให้ Claire Willower ที่ Deathknell" },
        description = { "328:772792288:159969765", "ยินดีต้อนรับสู่ World of Warcraft!\n\nเพื่อขอบคุณเป็นพิเศษที่ซื้อ World of Warcraft Collector's Edition ให้นำบัตรของขวัญนี้ไปส่งให้ Claire Willower ใน Deathknell แล้วท่านจะได้รับของขวัญเป็นเพื่อนตัวน้อยที่จะร่วมเดินทางไปผจญภัยและแสวงหาเกียรติยศกับท่าน\n\nขอบคุณอีกครั้ง ขอให้สนุกกับเวลาของท่านใน World of Warcraft!" },
        required = { [14651] = { "23:537424389:415413781", "บัตรแลกของขวัญ Deathknell" } },
        steps = { { "23:537424389:415413781", "บัตรแลกของขวัญ Deathknell" } },
    },
