        required = { [2592] = { "10:1951285682:678944537", "ผ้าขนสัตว์" } },
        steps = { { "10:1951285682:678944537", "ผ้าขนสัตว์" } },
    },
    [7793] = { -- A Donation of Silk
        title = { "18:1051041469:2137966348", "บริจาคผ้าไหม" },
        progress = { "435:1011791943:1214420941", "เช่นเดียวกับผ้าชนิดอื่น ๆ ตอนนี้ผ้าไหมของเราเหลือน้อยที่สุดเท่าที่เคยมี เราต้องการจากเจ้าเพียงหกสิบชิ้นเท่านั้น และน่าจะบรรลุเป้าหมายได้ด้วยการสนับสนุนของคนอื่น\n\nข้าขอบอกว่าของบริจาคที่เอื้อเฟื้อเช่นผ้าไหม จะทำให้ชื่อเสียงของเจ้าในชุมชนดีขึ้นแน่นอน! หากเจ้ามี Silk Cloth หกสิบชิ้นและพร้อมบริจาค ข้ารับไว้ได้ทันที" },
        completion = { "52:1271369293:1555941987 N 1:33:33", "ยอดเยี่ยม! เราขอบคุณสำหรับการบริจาคอันเอื้อเฟื้อของเจ้า {name}!" },
        description = { "435:1011791943:1214420941", "เช่นเดียวกับผ้าชนิดอื่น ๆ ตอนนี้ผ้าไหมของเราเหลือน้อยที่สุดเท่าที่เคยมี เราต้องการจากเจ้าเพียงหกสิบชิ้นเท่านั้น และน่าจะบรรลุเป้าหมายได้ด้วยการสนับสนุนของคนอื่น\n\nข้าขอบอกว่าของบริจาคที่เอื้อเฟื้อเช่นผ้าไหม จะทำให้ชื่อเสียงของเจ้าในชุมชนดีขึ้นแน่นอน! หากเจ้ามี Silk Cloth หกสิบชิ้นและพร้อมบริจาค ข้ารับไว้ได้ทันที" },
        required = { [4306] = { "10:1269080011:1976271755", "ผ้าไหม" } },
        steps = { { "10:1269080011:1976271755", "ผ้าไหม" } },
    },
    [7794] = { -- A Donation of Mageweave
        title = { "23:477706609:1703816279", "บริจาคผ้า Mageweave" },
        progress = { "409:1458506586:712990962", "Mageweave ใกล้หมด เราต้องการความช่วยเหลือเติมคลัง! เมื่ออาศัยความร่วมมือจากคนทั้งชุมชน เราต้องการผ้า mageweave จากเจ้าเพียง 60 ผืนก็จะช่วยให้ถึงเป้าหมายได้ ข้ารับรองว่า Stormwind จะไม่มองข้ามน้ำใจเช่นนี้!\n\nหากมีผ้า mageweave 60 ผืนและพร้อมบริจาค ข้ารับไว้ได้เลย" },
        completion = { "52:1271369293:1555941987 N 1:33:33", "ยอดเยี่ยม! เราขอบคุณสำหรับการบริจาคอันเอื้อเฟื้อของเจ้า {name}!" },
        description = { "409:1458506586:712990962", "Mageweave ใกล้หมด เราต้องการความช่วยเหลือเติมคลัง! เมื่ออาศัยความร่วมมือจากคนทั้งชุมชน เราต้องการผ้า mageweave จากเจ้าเพียง 60 ผืนก็จะช่วยให้ถึงเป้าหมายได้ ข้ารับรองว่า Stormwind จะไม่มองข้ามน้ำใจเช่นนี้!\n\nหากมีผ้า mageweave 60 ผืนและพร้อมบริจาค ข้ารับไว้ได้เลย" },
        required = { [4338] = { "15:1283357618:289024293", "ผ้า Mageweave" } },
        steps = { { "15:1283357618:289024293", "ผ้า Mageweave" } },
