    [7795] = { -- A Donation of Runecloth
        title = { "23:805424014:894170896", "บริจาคผ้า Runecloth" },
        progress = { "N 410:720308826:879718219", "{name} เจ้ามีส่วนช่วยโครงการรวบรวมผ้าของเราอย่างมาก ระหว่างที่เราพยายามเติมเสบียงสำรอง ยังมีผ้าชนิดหนึ่งขาดแคลนอย่างหนัก นั่นคือ Runecloth เราจำเป็นต้องใช้มันอย่างเร่งด่วน และหวังว่าเจ้าจะช่วยได้เช่นที่ผ่านมา!\n\nหากเต็มใจ โปรดนำ Runecloth ที่แบ่งให้ได้มาให้ข้า ในตอนแรกเราจะรับบริจาคหนึ่งครั้งจำนวนหกสิบชิ้น แล้วค่อยดูกันต่อไป" },
        completion = { "363:1453542902:756496047", "ยอดเยี่ยม ข้ารับรองว่าเราจะนำไปใช้ทันที ขอบคุณอีกครั้งสำหรับความช่วยเหลือ! ถ้าไม่มีเจ้า เราคงลำบากแน่\n\nจากที่เจ้าบริจาคมาทั้งหมด ข้ายินดีรับ Runecloth เพิ่มหากเจ้าต้องการบริจาคในภายหน้า แวะมาหาข้าได้เลย ข้าจะดูแลเองให้แน่ใจว่าความดีของเจ้าจะไม่ถูกมองข้าม!" },
        description = { "N 410:720308826:879718219", "{name} เจ้ามีส่วนช่วยโครงการรวบรวมผ้าของเราอย่างมาก ระหว่างที่เราพยายามเติมเสบียงสำรอง ยังมีผ้าชนิดหนึ่งขาดแคลนอย่างหนัก นั่นคือ Runecloth เราจำเป็นต้องใช้มันอย่างเร่งด่วน และหวังว่าเจ้าจะช่วยได้เช่นที่ผ่านมา!\n\nหากเต็มใจ โปรดนำ Runecloth ที่แบ่งให้ได้มาให้ข้า ในตอนแรกเราจะรับบริจาคหนึ่งครั้งจำนวนหกสิบชิ้น แล้วค่อยดูกันต่อไป" },
        required = { [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        steps = { { "9:897047003:553648234", "ผ้ารูน" } },
    },
    [7796] = { -- Additional Runecloth
        title = { "20:549296932:999816626", "บริจาค Runecloth เพิ่ม" },
        progress = { "73:687057549:1578393754", "เมื่อเจ้าพร้อมส่ง Runecloth กองนั้นมา ข้าจะรับไว้", variants = { { "22:940931934:1505085707 N 330:160513973:990914980", "สวัสดีอีกครั้ง {name}! เราต้องใช้ Runecloth อยู่เรื่อย ๆ ถ้าเจ้ายอมแบ่งมาเพิ่ม เราก็รับได้เสมอ หากบริจาค Runecloth เพิ่มอีกหนึ่งกอง กองละยี่สิบผืน ข้าจะให้ Stormwind รับรู้ถึงความช่วยเหลือที่เจ้ามอบให้อย่างต่อเนื่อง\n\nเมื่อพร้อมส่ง Runecloth กองนั้น ข้าจะรับไว้" } } },
        completion = { "N 116:2094394438:1847393952", "{name} หากไม่มีวีรชนเช่นเจ้าคอยทำงานเพื่อชนเผ่า เราคงทุกข์ยากแน่ ขอบคุณที่เจ้ายังทุ่มเทช่วยเหลือ!", variants = { { "N 116:824219672:1729620005", "{name} หากไม่มีวีรชนเช่นเจ้าคอยทำงานเพื่อStormwind พวกเราคงลำบากแน่ ขอบคุณที่เจ้ายังทุ่มเทช่วยเหลือ!" } } },
        description = { "22:940931934:1505085707 N 330:160513973:990914980", "สวัสดีอีกครั้ง {name}! เราต้องใช้ Runecloth อยู่เรื่อย ๆ ถ้าเจ้ายอมแบ่งมาเพิ่ม เราก็รับได้เสมอ หากบริจาค Runecloth เพิ่มอีกหนึ่งกอง กองละยี่สิบผืน ข้าจะให้ Stormwind รับรู้ถึงความช่วยเหลือที่เจ้ามอบให้อย่างต่อเนื่อง\n\nเมื่อพร้อมส่ง Runecloth กองนั้น ข้าจะรับไว้" },
        required = { [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        objectiveLabels = {
            item = { ["Runecloth"] = "ผ้ารูน" },
        },
    },
    [7802] = { -- A Donation of Wool
        title = { "18:1119336907:2147062072", "บริจาคผ้าขนสัตว์" },
        progress = { "443:347943640:1179249272", "ตอนนี้เรารับบริจาคผ้าขนสัตว์ การบริจาค 60 ผืนจะทำให้ Ironforge ยอมรับความเอื้อเฟื้อของเจ้าอย่างเต็มที่ จากสภาพคลังผ้าขนสัตว์ เราต้องการจากเจ้ารวมเพียง 60 ผืน ก็น่าจะหาเพิ่มเติมจากคนอื่นในอาณาจักรได้พอสำหรับโครงการ\n\nหากมีผ้าขนสัตว์ 60 ผืนและพร้อมบริจาค ข้ารับไว้ได้เลย" },
        completion = { "52:1271369293:1555941987 N 1:33:33", "ยอดเยี่ยม! เราขอบคุณสำหรับการบริจาคอันเอื้อเฟื้อของเจ้า {name}!" },
        description = { "443:347943640:1179249272", "ตอนนี้เรารับบริจาคผ้าขนสัตว์ การบริจาค 60 ผืนจะทำให้ Ironforge ยอมรับความเอื้อเฟื้อของเจ้าอย่างเต็มที่ จากสภาพคลังผ้าขนสัตว์ เราต้องการจากเจ้ารวมเพียง 60 ผืน ก็น่าจะหาเพิ่มเติมจากคนอื่นในอาณาจักรได้พอสำหรับโครงการ\n\nหากมีผ้าขนสัตว์ 60 ผืนและพร้อมบริจาค ข้ารับไว้ได้เลย" },
        required = { [2592] = { "10:1951285682:678944537", "ผ้าขนสัตว์" } },
        steps = { { "10:1951285682:678944537", "ผ้าขนสัตว์" } },
    },
    [7803] = { -- A Donation of Silk
        title = { "18:1051041469:2137966348", "บริจาคผ้าไหม" },
        progress = { "435:1011791943:1214420941", "เช่นเดียวกับผ้าชนิดอื่น ๆ ตอนนี้ผ้าไหมของเราเหลือน้อยที่สุดเท่าที่เคยมี เราต้องการจากเจ้าเพียงหกสิบชิ้นเท่านั้น และน่าจะบรรลุเป้าหมายได้ด้วยการสนับสนุนของคนอื่น\n\nข้าขอบอกว่าของบริจาคที่เอื้อเฟื้อเช่นผ้าไหม จะทำให้ชื่อเสียงของเจ้าในชุมชนดีขึ้นแน่นอน! หากเจ้ามี Silk Cloth หกสิบชิ้นและพร้อมบริจาค ข้ารับไว้ได้ทันที" },
        completion = { "52:1271369293:1555941987 N 1:33:33", "ยอดเยี่ยม! เราขอบคุณสำหรับการบริจาคอันเอื้อเฟื้อของเจ้า {name}!" },
        description = { "435:1011791943:1214420941", "เช่นเดียวกับผ้าชนิดอื่น ๆ ตอนนี้ผ้าไหมของเราเหลือน้อยที่สุดเท่าที่เคยมี เราต้องการจากเจ้าเพียงหกสิบชิ้นเท่านั้น และน่าจะบรรลุเป้าหมายได้ด้วยการสนับสนุนของคนอื่น\n\nข้าขอบอกว่าของบริจาคที่เอื้อเฟื้อเช่นผ้าไหม จะทำให้ชื่อเสียงของเจ้าในชุมชนดีขึ้นแน่นอน! หากเจ้ามี Silk Cloth หกสิบชิ้นและพร้อมบริจาค ข้ารับไว้ได้ทันที" },
        required = { [4306] = { "10:1269080011:1976271755", "ผ้าไหม" } },
        steps = { { "10:1269080011:1976271755", "ผ้าไหม" } },
    },
    [7804] = { -- A Donation of Mageweave
        title = { "23:477706609:1703816279", "บริจาคผ้า Mageweave" },
        progress = { "409:748459641:1243277806", "Mageweave ใกล้หมด เราต้องการความช่วยเหลือเติมคลัง! เมื่ออาศัยความร่วมมือจากคนทั้งชุมชน เราต้องการผ้า mageweave จากเจ้าเพียง 60 ผืนก็จะช่วยให้ถึงเป้าหมายได้ ข้ารับรองว่า Ironforge จะไม่มองข้ามน้ำใจเช่นนี้!\n\nหากมีผ้า mageweave 60 ผืนและพร้อมบริจาค ข้ารับไว้ได้เลย" },
        completion = { "52:1271369293:1555941987 N 1:33:33", "ยอดเยี่ยม! เราขอบคุณสำหรับการบริจาคอันเอื้อเฟื้อของเจ้า {name}!" },
        description = { "409:748459641:1243277806", "Mageweave ใกล้หมด เราต้องการความช่วยเหลือเติมคลัง! เมื่ออาศัยความร่วมมือจากคนทั้งชุมชน เราต้องการผ้า mageweave จากเจ้าเพียง 60 ผืนก็จะช่วยให้ถึงเป้าหมายได้ ข้ารับรองว่า Ironforge จะไม่มองข้ามน้ำใจเช่นนี้!\n\nหากมีผ้า mageweave 60 ผืนและพร้อมบริจาค ข้ารับไว้ได้เลย" },
        required = { [4338] = { "15:1283357618:289024293", "ผ้า Mageweave" } },
        steps = { { "15:1283357618:289024293", "ผ้า Mageweave" } },
    },
