    [7809] = { -- A Donation of Mageweave
        title = { "23:477706609:1703816279", "บริจาคผ้า Mageweave" },
        progress = { "421:1867070972:1106663698", "Mageweave ใกล้หมด เราต้องการความช่วยเหลือเติมคลัง! เมื่ออาศัยความร่วมมือจากคนทั้งชุมชน เราต้องการผ้า mageweave จากเจ้าเพียง 60 ผืนก็จะช่วยให้ถึงเป้าหมายได้ ข้ารับรองว่าเหล่าโนมแห่ง Gnomeregan จะไม่มองข้ามน้ำใจเช่นนี้!\n\nหากมีผ้า mageweave 60 ผืนและพร้อมบริจาค ข้ารับไว้ได้เลย", variants = { { "421:974565287:798660794", "Mageweave ใกล้หมดแล้ว เราต้องการให้เจ้าช่วยเติมคลัง! ด้วยความร่วมมือจากคนทั้งชุมชน เราจึงต้องการผ้า Mageweave จากเจ้าเพียง 60 ผืนเพื่อช่วยให้ถึงเป้าหมาย ข้ารับรองว่าเหล่าผู้ลี้ภัยแห่ง Gnomeregan จะไม่มองข้ามน้ำใจเช่นนี้!\n\nหากเจ้ามีผ้า Mageweave ครบหกสิบผืนและพร้อมบริจาค ข้ารับไว้ได้เลย" } } },
        completion = { "52:1271369293:1555941987 N 1:33:33", "ยอดเยี่ยม! เราขอบคุณสำหรับการบริจาคอันเอื้อเฟื้อของเจ้า {name}!" },
        description = { "421:974565287:798660794", "Mageweave ใกล้หมด เราต้องการความช่วยเหลือเติมคลัง! เมื่ออาศัยความร่วมมือจากทั้งชุมชน เราต้องการผ้า Mageweave จากเจ้าเพียง 60 ผืนก็จะช่วยให้ถึงเป้าหมายได้ ข้ารับรองว่า Gnomeregan Exiles จะไม่มองข้ามน้ำใจเช่นนี้!\n\nหากมีผ้า Mageweave หกสิบผืนและพร้อมบริจาค ข้ารับไว้ได้เลย" },
        required = { [4338] = { "15:1283357618:289024293", "ผ้า Mageweave" } },
        objectiveLabels = {
            item = { ["Mageweave Cloth"] = "ผ้า Mageweave" },
        },
    },
    [7811] = { -- A Donation of Runecloth
        title = { "23:805424014:894170896", "บริจาคผ้า Runecloth" },
        progress = { "N 410:720308826:879718219", "{name} เจ้ามีส่วนช่วยโครงการรวบรวมผ้าของเราอย่างมาก ระหว่างที่เราพยายามเติมเสบียงสำรอง ยังมีผ้าชนิดหนึ่งขาดแคลนอย่างหนัก นั่นคือ Runecloth เราจำเป็นต้องใช้มันอย่างเร่งด่วน และหวังว่าเจ้าจะช่วยได้เช่นที่ผ่านมา!\n\nหากเต็มใจ โปรดนำ Runecloth ที่แบ่งให้ได้มาให้ข้า ในตอนแรกเราจะรับบริจาคหนึ่งครั้งจำนวนหกสิบชิ้น แล้วค่อยดูกันต่อไป" },
        completion = { "363:1453542902:756496047", "ยอดเยี่ยม ข้ารับรองว่าเราจะนำไปใช้ทันที ขอบคุณอีกครั้งสำหรับความช่วยเหลือ! ถ้าไม่มีเจ้า เราคงลำบากแน่\n\nจากที่เจ้าบริจาคมาทั้งหมด ข้ายินดีรับ Runecloth เพิ่มหากเจ้าต้องการบริจาคในภายหน้า แวะมาหาข้าได้เลย ข้าจะดูแลเองให้แน่ใจว่าความดีของเจ้าจะไม่ถูกมองข้าม!" },
        description = { "N 410:720308826:879718219", "{name} เจ้ามีส่วนช่วยโครงการรวบรวมผ้าของเราอย่างมาก ระหว่างที่เราพยายามเติมเสบียงสำรอง ยังมีผ้าชนิดหนึ่งขาดแคลนอย่างหนัก นั่นคือ Runecloth เราจำเป็นต้องใช้มันอย่างเร่งด่วน และหวังว่าเจ้าจะช่วยได้เช่นที่ผ่านมา!\n\nหากเต็มใจ โปรดนำ Runecloth ที่แบ่งให้ได้มาให้ข้า ในตอนแรกเราจะรับบริจาคหนึ่งครั้งจำนวนหกสิบชิ้น แล้วค่อยดูกันต่อไป" },
        required = { [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        steps = { { "9:897047003:553648234", "ผ้ารูน" } },
    },
    [7812] = { -- Additional Runecloth
        title = { "20:549296932:999816626", "บริจาค Runecloth เพิ่ม" },
        progress = { "73:687057549:1578393754", "เมื่อเจ้าพร้อมส่ง Runecloth กองนั้นมา ข้าจะรับไว้", variants = { { "22:940931934:1505085707 N 342:1822893016:413657406", "สวัสดีอีกครั้ง {name}! เราต้องใช้ Runecloth อยู่เรื่อย ๆ และยินดีรับเพิ่มเสมอหากเจ้าเต็มใจแบ่งมาให้ หากบริจาค Runecloth เพิ่มอีกหนึ่งกอง กองละยี่สิบผืน ข้าจะให้เหล่าผู้ลี้ภัยแห่ง Gnomeregan รับรู้ถึงความช่วยเหลือที่เจ้ามอบให้อย่างต่อเนื่อง\n\nเมื่อเจ้าพร้อมส่ง Runecloth กองนั้นมา ข้าจะรับไว้" } } },
        completion = { "N 116:2094394438:1847393952", "{name} หากไม่มีวีรชนเช่นเจ้าคอยทำงานเพื่อชนเผ่า เราคงทุกข์ยากแน่ ขอบคุณที่เจ้ายังทุ่มเทช่วยเหลือ!", variants = { { "N 116:1475510964:883811507", "{name} หากไม่มีวีรชนเช่นเจ้าคอยทำงานเพื่อชาวโนมอย่างพวกเรา พวกเราคงลำบากแน่ ขอบคุณที่เจ้ายังทุ่มเทช่วยเหลือ!" } } },
        description = { "22:940931934:1505085707 N 342:1822893016:413657406", "สวัสดีอีกครั้ง {name}! เราต้องใช้ Runecloth อยู่เรื่อย ๆ ถ้าเจ้ายอมแบ่งมาเพิ่ม เราก็รับได้เสมอ หากบริจาค Runecloth เพิ่มอีกหนึ่งกอง กองละยี่สิบผืน ข้าจะให้ Gnomeregan Exiles รับรู้ถึงความช่วยเหลือที่เจ้ามอบให้อย่างต่อเนื่อง\n\nเมื่อพร้อมส่ง Runecloth กองนั้น ข้าจะรับไว้" },
        required = { [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        objectiveLabels = {
            item = { ["Runecloth"] = "ผ้ารูน" },
        },
    },
