    [7832] = { -- Additional Runecloth
        title = { "20:549296932:999816626", "บริจาค Runecloth เพิ่ม" },
        progress = { "73:687057549:1578393754", "เมื่อเจ้าพร้อมส่ง Runecloth กองนั้นมา ข้าจะรับไว้", variants = { { "22:940931934:1505085707 N 330:161588458:1183013230", "สวัสดีอีกครั้ง {name}! เราต้องใช้ Runecloth อยู่เรื่อย ๆ ถ้าเจ้ายอมแบ่งมาเพิ่ม เราก็รับได้เสมอ หากบริจาค Runecloth เพิ่มอีกหนึ่งกอง กองละยี่สิบผืน ข้าจะให้ Orgrimmar รับรู้ถึงความช่วยเหลือที่เจ้ามอบให้อย่างต่อเนื่อง\n\nเมื่อพร้อมส่ง Runecloth กองนั้น ข้าจะรับไว้" } } },
        completion = { "N 116:2094394438:1847393952", "{name} หากไม่มีวีรชนเช่นเจ้าคอยทำงานเพื่อชนเผ่า เราคงทุกข์ยากแน่ ขอบคุณที่เจ้ายังทุ่มเทช่วยเหลือ!", variants = { { "N 116:2071388058:1389359558", "{name} หากไม่มีวีรชนเช่นเจ้าคอยทำงานเพื่อOrgrimmar พวกเราคงลำบากแน่ ขอบคุณที่เจ้ายังทุ่มเทช่วยเหลือ!" } } },
        description = { "22:940931934:1505085707 N 330:161588458:1183013230", "สวัสดีอีกครั้ง {name}! เราต้องใช้ Runecloth อยู่เรื่อย ๆ ถ้าเจ้ายอมแบ่งมาเพิ่ม เราก็รับได้เสมอ หากบริจาค Runecloth เพิ่มอีกหนึ่งกอง กองละยี่สิบผืน ข้าจะให้ Orgrimmar รับรู้ถึงความช่วยเหลือที่เจ้ามอบให้อย่างต่อเนื่อง\n\nเมื่อพร้อมส่ง Runecloth กองนั้น ข้าจะรับไว้" },
