    [98739] = { -- Blessings of the Great Cat Spirit
        title = { "33:1941080999:1770977738", "พรแห่งวิญญาณแมวผู้ยิ่งใหญ่" },
        objective = { "18:408344685:1120416534", "คุยกับ Dendrite" },
        description = { "212:149194168:1478145185", "เมื่อได้รับพรของข้าแล้ว จงกลับไปหา Dendrite เขาจะแนะนำต่อ ข้าหวังจริง ๆ ว่าวันหนึ่งเราจะได้พบกันอีก\n\nขอเงามืดซ่อนเจ้าเสมอ และขอศัตรูตกเป็นเหยื่อกรงเล็บได้โดยง่าย สหายรุ่นเยาว์" },
        completion = { "470:843412361:319393642", "<เมื่อเจ้าเข้าใกล้ Dendrite ขยับมืออีกครั้งในอากาศเหนือศีรษะ ราวกับวาดสัญลักษณ์ที่มองไม่เห็น รัศมีพลังอีกระลอกแผ่มาคลุมร่างเขา และเขายิ้มเพียงเล็กน้อย>\n\nข้าสัมผัสได้ถึงไหวพริบและความดุร้ายของแมวในตัวเจ้า สิ่งที่ยังไม่มีตอนข้าส่งเจ้าไปพบ Great Cat Spirit แววตาเจ้าบอกว่าตอนนี้เข้าใจแล้วว่าต้องอาศัยความเงียบเชียบและความว่องไวเพียงใดจึงจะรับเอาธรรมชาตินี้มาได้\n\nตอนนี้เจ้าเรียนรู้ที่จะใช้ไหวพริบอย่างมีสมาธิ รับเอาธรรมชาติแท้จริงของแมว และเรียกพลังจากวิญญาณของมันได้แล้ว" },
    },
    [99191] = { -- A Donation of Wool
        title = { "18:1119336907:2147062072", "บริจาคผ้าขนสัตว์" },
        progress = { "392:1172963016:774530283", "ตอนนี้ High Order กำลังรับบริจาคผ้าขนสัตว์\n\nถ้าบริจาคผ้าขนสัตว์หกสิบชิ้น High Order จะยกย่องความเอื้อเฟื้อของเจ้าอย่างเต็มที่ ผ้าขนสัตว์หกสิบชิ้นน่าจะพอกับที่ High Order ต้องใช้ในตอนนี้\n\nหากเจ้าพกผ้าขนสัตว์หกสิบชิ้นมาด้วยและพร้อมบริจาค ข้ารับไว้ให้ได้เดี๋ยวนี้" },
        completion = { "52:1271369293:1555941987 N 1:33:33", "ยอดเยี่ยม!\n\nขอบคุณที่บริจาคให้อย่างใจกว้างนะ {name}!" },
        description = { "392:1172963016:774530283", "ตอนนี้ High Order กำลังรับบริจาคผ้าขนสัตว์\n\nถ้าบริจาคผ้าขนสัตว์หกสิบชิ้น High Order จะยกย่องความเอื้อเฟื้อของเจ้าอย่างเต็มที่ ผ้าขนสัตว์หกสิบชิ้นน่าจะพอกับที่ High Order ต้องใช้ในตอนนี้\n\nหากเจ้าพกผ้าขนสัตว์หกสิบชิ้นมาด้วยและพร้อมบริจาค ข้ารับไว้ให้ได้เดี๋ยวนี้" },
        required = { [2592] = { "10:1951285682:678944537", "ผ้าขนสัตว์" } },
        steps = { { "10:1951285682:678944537", "ผ้าขนสัตว์" } },
    },
    [99192] = { -- A Donation of Silk
        title = { "18:1051041469:2137966348", "บริจาคผ้าไหม" },
        description = { "393:696865875:823588869", "เราใช้ผ้าไหมไปกับการจัดเครื่องแต่งกายที่เหมาะสมให้เหล่านักเวทจนเสบียงผ้าไหมร่อยหรอ หากเจ้าแบ่งผ้าไหมให้เราสักหกสิบผืน เมื่อรวมกับความช่วยเหลือของคนอื่น เราก็น่าจะได้ครบตามที่ต้องการ\n\nของขวัญล้ำค่าอย่างผ้าไหมย่อมช่วยให้เจ้าเป็นที่ยอมรับในคณะของเรามากขึ้น! หากมี Silk Cloth หกสิบผืนติดตัวและพร้อมบริจาค ข้ารับไว้ได้เดี๋ยวนี้" },
        progress = { "393:696865875:823588869", "เราใช้ผ้าไหมจากคลังไปมากเพื่อจัดหาอุปกรณ์ที่เหมาะสมให้เหล่าจอมเวท หากเจ้าพอจะแบ่งผ้าไหมให้เราหกสิบผืน เมื่อรวมกับที่คนอื่นช่วยบริจาค เราก็น่าจะได้ครบตามที่ต้องการ\n\nของบริจาคอย่างผ้าไหมย่อมช่วยเพิ่มชื่อเสียงของเจ้ากับภาคีของเรา หากเจ้ามีผ้าไหมหกสิบผืนติดตัวและพร้อมบริจาค ข้ารับไว้ได้เลย" },
        required = { [4306] = { "10:1269080011:1976271755", "ผ้าไหม" } },
        steps = { { "10:1269080011:1976271755", "ผ้าไหม" } },
        completion = { "52:1271369293:1555941987 N 1:33:33", "ยอดเยี่ยม! เราขอขอบคุณสำหรับการบริจาคอย่างใจกว้างของเจ้า {name}!" },
    },
    [99196] = { -- A Donation of Wool
        title = { "18:1119336907:2147062072", "บริจาคผ้าขนสัตว์" },
        progress = { "292:796338311:1665810635", "ชาววินด์เชปเปอร์กำลังรับบริจาคผ้าขนสัตว์\n\nหากบริจาคผ้าขนสัตว์หกสิบชิ้น ชาววินด์เชปเปอร์จะรับรู้ถึงความเอื้อเฟื้อของเจ้าอย่างเต็มที่\n\nถ้าเจ้าพกผ้าขนสัตว์หกสิบชิ้นมาด้วยและพร้อมบริจาค ข้ารับจากเจ้าได้ตอนนี้เลย" },
        completion = { "67:2078174991:1954751451", "ขอบใจที่บริจาคอย่างเอื้อเฟื้อ!\n\nขอให้สายลมอยู่เคียงข้างเจ้า สหาย" },
        description = { "292:796338311:1665810635", "ชาววินด์เชปเปอร์กำลังรับบริจาคผ้าขนสัตว์\n\nหากบริจาคผ้าขนสัตว์หกสิบชิ้น ชาววินด์เชปเปอร์จะรับรู้ถึงความเอื้อเฟื้อของเจ้าอย่างเต็มที่\n\nถ้าเจ้าพกผ้าขนสัตว์หกสิบชิ้นมาด้วยและพร้อมบริจาค ข้ารับจากเจ้าได้ตอนนี้เลย" },
        required = { [2592] = { "10:1951285682:678944537", "ผ้าขนสัตว์" } },
        steps = { { "10:1951285682:678944537", "ผ้าขนสัตว์" } },
    },
    [99197] = { -- A Donation of Silk
        title = { "18:1051041469:2137966348", "บริจาคผ้าไหม" },
        progress = { "385:1052098764:60787756", "ตอนนี้ชาววินด์เชปเปอร์ต้องการผ้าไหม หากเจ้าแบ่งให้เราได้หกสิบชิ้น พอมีคนอื่นช่วยสมทบ เราก็น่าจะได้ครบตามที่ต้องการ\n\nของบริจาคชั้นดีอย่างผ้าไหมจะทำให้ชาววินด์เชปเปอร์ยกย่องและนับถือเจ้ามากขึ้นแน่นอน!\n\nถ้าเจ้าพกผ้าไหมหกสิบชิ้นมาด้วยและพร้อมบริจาค ข้ารับจากเจ้าได้ตอนนี้เลย" },
        description = { "385:1052098764:60787756", "ตอนนี้ชาววินด์เชปเปอร์ต้องการผ้าไหม หากเจ้าแบ่งให้เราได้หกสิบชิ้น พอมีคนอื่นช่วยสมทบ เราก็น่าจะได้ครบตามที่ต้องการ\n\nของบริจาคชั้นดีอย่างผ้าไหมจะทำให้ชาววินด์เชปเปอร์ยกย่องและนับถือเจ้ามากขึ้นแน่นอน!\n\nถ้าเจ้าพกผ้าไหมหกสิบชิ้นมาด้วยและพร้อมบริจาค ข้ารับจากเจ้าได้ตอนนี้เลย" },
        required = { [4306] = { "10:1269080011:1976271755", "ผ้าไหม" } },
        objectiveLabels = {
            item = { ["Silk Cloth"] = "ผ้าไหม" },
        },
    },
    [261] = { -- Down the Scarlet Path
        title = { "21:73375596:1675311146", "ตามเส้นทางสีชาด" },
        objective = { "74:834998852:423090762", "กำจัด Undead Ravager 30 ตน แล้วกลับไปหา Brother Anton ที่ Nijel's Point" },
        description = { "456:484126807:1606242188", "ข้าจะพูดตรง ๆ เรากำลังทำสงครามกับ Scourge มันคือความชั่วร้ายที่ทำให้ผู้คนของเราเสื่อมทรามและแผ่นดินติดเชื้อ ต้องหยุดมันก่อนจะท่วมท้นพวกเราและลากโลกลงสู่เงามืด พวกเราแห่ง Scarlet Crusade สาบานว่าจะต่อสู้กับ Scourge ทั้งกายและใจ\n\nหากเจ้าอยู่ข้างเรา จงรวบรวมความกล้าและพิสูจน์ความภักดี กำจัด Undead Ravager ของ Desolace ที่ Valley of Bones ทางใต้\n\nทำเช่นนี้ แล้วกลุ่มของเราจะอ้าแขนรับเจ้า" },
        progress = { "110:279955323:344392551", "Scourge แข็งแกร่งขึ้นทุกวันที่ผ่านไป หากเจ้าต้องการหยุดการรุกคืบของมันจริง ก็แสดงให้ข้าเห็น" },
        completion = { "150:1248685113:1427801819", "เจ้าพิสูจน์ความมุ่งมั่นแล้ว Scarlet Crusade ขอชื่นชมเจ้า\n\nหากเจ้าไม่หวั่นต่อการสังหารเพื่อความชอบธรรม บางทีเส้นทางของเจ้าอาจอยู่กับพวกเรา..." },
        objectiveLabels = {
            monster = { ["Undead Ravager slain"] = "ปราบ อันเดดจอมฉีกกระชาก" },
        },
    },
    [1052] = { -- Down the Scarlet Path
        title = { "21:73375596:1675311146", "ตามเส้นทางสีชาด" },
        objective = { "80:36092652:837102739", "นำ Brother Anton's Letter of Commendation ไปให้ Raleigh the Devout ที่ Southshore" },
        description = { "493:365703642:1053521692", "พวกเราแห่ง Scarlet Crusade ครอบครองฐานที่มั่นตั้งแต่ Hearthglen ไปจนถึง Tirisfal Glades เราภูมิใจในป้อมแห่งการชำระล้างทั่ว Lordaeron\n\nเจ้าพิสูจน์ฝีมือกับอันเดดใน Desolace แล้ว แต่ภัยแท้จริงของโรคระบาดอยู่ใน Lordaeron\n\nเดินทางไปเมือง Southshore ใน Eastern Kingdoms ตามหานักรบครูเสดชื่อ Raleigh the Devout มอบจดหมายรับรองที่ประทับตราของข้านี้ให้เขา แล้วเขาจะพาเจ้าไปสู่ตำแหน่งอันทรงเกียรติใน Scarlet Monastery ของเรา" },
        progress = { "41:1271653435:1585081525", "ใครมาที่นั่น? เจ้าต้องการอะไรจากข้า?" },
        completion = { "70:1223013443:635733711", "Brother Anton ยังเผยแพร่คำสอนของ Scarlet Crusade อยู่หรือ? โอ้..." },
        required = { [5539] = { "22:302547195:32033761", "จดหมายยกย่อง" } },
        steps = { { "22:302547195:32033761", "จดหมายยกย่อง" } },
    },
    [1369] = { -- Broken Tears
        title = { "12:1559591010:1834076827", "น้ำตาที่แตกสลาย" },
        objective = { "98:653669193:863271892", "รักษาชื่อเสียงกับ Magram และนำ Broken Tear 3 ชิ้นไปให้ Warug ที่ Magram Village" },
        description = { "337:972935562:1292215999", "พวก Gelkis คิดว่า Theradras มารดาของเซนทอร์ปกป้องพวกเรา พวกมันโง่ ไม่มีใครปกป้องเซนทอร์ Magram ไม่ต้องการการปกป้อง! พวกเราแข็งแกร่งที่สุด!\n\nแสดงให้ Gelkis เห็นว่ามันโง่ ไปถ้ำในหมู่บ้านของพวกมัน มันเก็บผลึกไว้ในถ้ำนั้น เป็นน้ำตาของ Theradras ทำลายน้ำตาแล้วนำเศษมาให้ข้า!" },
        progress = { "54:1563712853:250927304", "ถ้าเจ้าไม่ใช่ศัตรู ก็จงทำตามที่ข้าขอ!" },
        completion = { "164:1972771169:1819211403 N 23:1420106383:1998136341", "เจ้าได้น้ำตามาแล้ว! คราวนี้ Gelkis จะรู้ว่า Theradras ไม่ช่วยมัน นางจะไม่ร้องไห้เมื่อเราบดขยี้พวกมัน! Magram จะปกครอง!\n\nเจ้าฉลาดที่ช่วยเรา {name} พวกเราแข็งแกร่งที่สุด" },
        required = { [6083] = { "12:1559591010:1834076827", "หยาดน้ำตาที่แตกสลาย" } },
        steps = { { "12:1559591010:1834076827", "หยาดน้ำตาที่แตกสลาย" } },
        objectiveLabels = {
            reputation = { ["Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
        },
    },
    [1370] = { -- Stealing Supplies
        title = { "17:1077556310:967253228", "ขโมยเสบียง" },
        objective = { "75:864715470:1260733637", "นำ Crudely Dried Meat 6 ถุงไปให้ Uthek the Wise ที่ Gelkis Village" },
        description = { "306:1987723251:1288510283", "เมื่อไม่ได้ทำสงคราม เราล่าเนื้อ เนื้อทำให้แข็งแรง คนท้องอิ่มสู้ได้หนักกว่าคนท้องว่าง\n\nMagram ก็เช่นกัน มันเก็บเนื้อสำรองไว้เพื่อสู้ได้นานขึ้นระหว่างออกล่า หากเจ้าบุกหมู่บ้านทางตะวันออกแล้วเอาเนื้อมา กำลังของพวกมันจะถดถอย" },
        progress = { "56:1478232543:1166386178", "กลับมาเมื่อเจ้าพิสูจน์คุณค่าต่อ Gelkis เพิ่มแล้ว!" },
        completion = { "199:708431418:270643409 N 1:46:46", "ดี ข้าได้ยินเสียงท้อง Magram ร้องดังมาจากหมู่บ้านไกล ๆ เลย!\n\nข้าจะให้เนื้อนี้แก่ Gelkis แล้วเราจะต่อสู้ได้หลายวันโดยไม่พัก\n\nสิ่งที่เจ้าทำเป็นประโยชน์ต่อ Gelkis {name}" },
        required = { [6069] = { "18:237629672:1883053271", "เนื้อที่ตากแห้งอย่างหยาบ ๆ" } },
        steps = { { "18:237629672:1883053271", "เนื้อที่ตากแห้งอย่างหยาบ ๆ" } },
        objectiveLabels = {
