    [1371] = { -- Gizmo for Warug
        title = { "15:351524772:19313345", "ของเล่นกลไกให้ Warug" },
        objective = { "120:106544479:1599461526", "รักษาชื่อเสียงกับ Magram และนำ Advanced Target Dummy ไปให้ Warug ที่ Magram Village ใน Desolace" },
        description = { "406:1399471063:2096929829", "นานมาแล้ว โนมตัวเล็กมา Desolace เขามีม้ากับเกวียน เกวียนบรรทุกของแปลก ของตลก ของที่เผาแล้วเป็นไฟหลายสี ของที่ขยับได้แต่ไม่มีชีวิต ข้าฆ่าโนมตัวเล็กนั่น แต่ก่อนหน้านั้น... เขาทำให้ข้าหัวเราะ\n\nข้าเก็บของที่ชอบที่สุดจากเกวียนไว้ เป็นมนุษย์ทำจากไม้ มันโบกมือให้จนข้าตีมันพัง\n\nข้าอยากได้ตัวใหม่ ไปเอาตัวใหม่มาให้ข้า!" },
        progress = { "54:1563712853:250927304", "ถ้าเจ้าไม่ใช่ศัตรู ก็จงทำตามที่ข้าขอ!" },
        completion = { "70:2120798152:2050152395", "ใช่ นี่แหละของที่ข้าเคยมี! ข้าจะทำให้มันขยับอีก มันทำให้ข้าหัวเราะ!" },
        required = { [4392] = { "21:768240110:1010460574", "หุ่นเป้าฝึกขั้นสูง" } },
        steps = { { "21:768240110:1010460574", "หุ่นเป้าฝึกขั้นสูง" } },
        objectiveLabels = {
