    [1373] = { -- Ongeku
        title = { "6:1011503461:916450521", "Ongeku" },
        objective = { "124:415500092:1705132708", "รักษาชื่อเสียงกับ Gelkis และนำ Draenethyst Shard ไปให้ Uthek the Wise ที่ Gelkis Village ใน Desolace" },
        description = { "479:127124801:1638590404", "เจ้ายังต้องพิสูจน์ตัวอีก และงานต่อไปจะพาเจ้าไปไกล ระหว่างนี้ Gelkis จะสู้กับ Magram โดยไม่มีเจ้า\n\nผืนดินกระซิบความลับมากมายแก่ผู้รับฟัง ความลับหนึ่งที่ข้าได้ยินคือเรื่องผลึกสีแดง ชื่อ Draenethyst มันเป็นสิ่งใหม่สำหรับโลกเรา มาจากสถานที่ที่ภูเขาลอยได้และปีศาจปกครอง\n\nนำเศษ Draenethyst มาให้ข้า มันจะทำให้เวทมนตร์ของข้าแข็งแกร่ง! เศษผลึกอยู่ในสถานที่ชื่อ Swamp of Sorrows มีLost One ชื่อ Ongeku ครอบครองอยู่" },
        progress = { "40:864735321:675585868 N 1:46:46", "แสดงให้ข้าเห็นว่าเจ้าเป็นมิตรกับ Gelkis {name}" },
        completion = { "177:1322557510:286832860 N 38:1543503383:2031143270", "ใช่ นี่คือเศษผลึกที่ผืนดินกระซิบบอก ข้าสัมผัสเวทมนตร์ทรงพลังในนั้นได้! ข้าจะใช้มันต่อกรศัตรูของ Gelkis\n\nเจ้าทำงานให้เราอีกอย่างแล้ว {name} บางทีอีกไม่นานเราจะเรียกเจ้าว่าสหาย" },
        required = { [6190] = { "17:1820025495:166118002", "เศษผลึก Draenethyst" } },
        steps = { { "17:1820025495:166118002", "เศษผลึก Draenethyst" } },
        objectiveLabels = {
            reputation = { ["Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
