    [1375] = { -- Khan Shaka
        title = { "10:2094923139:1684106194", "ข่าน Shaka" },
        objective = { "118:292578773:198412531", "รักษาชื่อเสียงกับ Magram และนำ Head of Khan Shaka ไปให้ Warug ที่ Magram Village ใน Desolace" },
        description = { "155:1273073713:689787558", "เจ้าช่วย Magram ข้าจึงชอบเจ้า คราวนี้จงฆ่าข่านของ Gelkis! มันชื่อข่าน Shaka ข้าต้องการหัวมัน! ข้าอยากจ้องหัวมันแล้วหัวเราะใส่!" },
        progress = { "45:1395503353:2128866184", "ทำงานให้ Magram แล้วข้าจะช่วยเจ้า" },
        completion = { "117:1192542050:290502305", "ข่าน Shaka ตายแล้ว! ข้าจะเสียบหัวมันบนหอก เก็บไว้กับตัวเพื่อให้ Shaka ได้เห็นความแข็งแกร่งของ Magram!" },
        required = { [6073] = { "17:911561711:666344956", "ศีรษะของ Khan Shaka" } },
        objectiveLabels = {
            item = { ["Khan Shaka's Head"] = "ศีรษะของ Khan Shaka" },
        },
    },
    [1380] = { -- Khan Hratha
        title = { "11:347239827:1052141052", "ข่าน Hratha" },
        objective = { "119:873107423:2119030581", "รักษาชื่อเสียงกับ Gelkis และนำ Maraudine Key Fragment ไปให้ Uthek the Wise ที่ Gelkis Village" },
        description = { "N 453:2143726191:1627956510", "{name} เจ้าช่วยเราต่อกร Magram แล้ว ตอนนี้ช่วยเราเอาชนะ Maraudine! ฆ่าหัวหน้าเผ่า ข่าน Hratha!\n\nหากจะเผชิญหน้ามัน จงเป่า Maraudine War Horn บนหน้าผาสูงใน Valley of Spears\n\nแต่จะเป่าเขานั้นได้ ต้องมีปากเป่าเขาศึกก่อน ของนี้หายาก มีเฉพาะเซนทอร์ Maraudine ที่ได้รับความไว้วางใจพกไว้\n\nเมื่อเป่าเขาแล้ว เซนทอร์จะมา ฆ่าพวกมันจน Hratha ปรากฏ\n\nข่าน Hratha มีชิ้นส่วนของ... กุญแจ นำมาให้ข้า..." },
        progress = { "50:955336214:1462199077", "ข่าน Hratha ตายหรือยัง? เจ้าได้ชิ้นส่วนกุญแจมาไหม?" },
        completion = { "98:1747874023:638524740 N 86:266211238:1118806753", "มันตายแล้ว! ข่าน Hratha ตายแล้ว! คราวนี้ Maraudine จะล่มสลาย! เมื่อ Gelkis ปกครองดินแดนนี้ เราจะจดจำเจ้า {name} และวิญญาณแห่งผืนดินจะขับขานนามเจ้าตลอดกาล" },
        required = { [6077] = { "22:619606957:328144269", "เศษกุญแจ Maraudine" } },
        objectiveLabels = {
            item = { ["Maraudine Key Fragment"] = "เศษกุญแจ Maraudine" },
        },
    },
    [1381] = { -- Khan Hratha
        title = { "11:347239827:1052141052", "ข่าน Hratha" },
        objective = { "113:155179833:1441478414", "รักษาชื่อเสียงกับ Magram และนำ Maraudine Key Fragment ไปให้ Warug ที่ Magram Village ใน Desolace" },
        description = { "461:1933350767:1295092512", "ข่าน Gelkis ตายแล้ว คราวนี้ Maraudine จะล่มสลาย! ฆ่า Hratha ข่านแห่ง Maraudine!\n\nหากจะเผชิญหน้ามัน จงเป่าเขาบนหน้าผาสูงใน Valley of Spears แต่ต้องมีปากเป่าก่อน ฆ่าเซนทอร์ Maraudine ไปเรื่อย ๆ จนพบปากเป่า แล้วจึงเป่าเขา\n\nเมื่อทำเช่นนี้ เซนทอร์ Maraudine จะมาที่หอคอย ฆ่าพวกมันจนข่าน Hratha ปรากฏ Hratha มีชิ้นส่วนกุญแจอยู่ มอบชิ้นส่วนนั้นให้ข้า..." },
        progress = { "62:2068423106:1133944638", "ทำตามที่ข้าขอ พิสูจน์ว่าเจ้าเป็นพันธมิตรของ Magram!" },
        completion = { "138:1244193010:1011751096 N 65:1911484402:1532413647", "ข่าน Hratha ตายแล้ว! ตอนนี้ Magram แข็งแกร่งที่สุดในหมู่เซนทอร์! เราจะบดขยี้เผ่าอื่นและปกครอง Desolace!\n\nเราจะจำเจ้าไว้ {name} เมื่อคนอื่นถูกเหยียบย่ำ เจ้าจะรอดจากกีบเท้าของเรา" },
        required = { [6077] = { "22:619606957:328144269", "เศษกุญแจ Maraudine" } },
        objectiveLabels = {
            item = { ["Maraudine Key Fragment"] = "เศษกุญแจ Maraudine" },
        },
    },
    [1382] = { -- Strange Alliance
        title = { "16:306019406:1800155944", "พันธมิตรที่คาดไม่ถึง" },
        objective = { "75:2111247167:109617727", "เพิ่มชื่อเสียงกับ Gelkis ถึงระดับ Friendly แล้วคุยกับ Uthek the Wise" },
        description = { "497:1235662055:618852604", "เราโชคดีที่เผ่าเซนทอร์รบกันเอง หากรวมเป็นกองกำลังเดียว คงไม่มีใครหยุดได้ ใช่ เราโชคดีและควรฉวยความได้เปรียบนี้\n\nเผ่า Gelkis กำลังทำสงครามดุเดือดกับเผ่า Magram หากเราโจมตี Magram บางทีอาจตั้งพันธมิตรกับ Gelkis ได้\n\nคุยกับ Uthek the Wise บริเวณรอบนอกค่าย Gelkis ทางตะวันตกเฉียงใต้ของ Desolace เราอาจสร้างพันธมิตรกับ Gelkis ผ่านนางได้" },
        progress = { "119:1470831136:777319340", "ไปเสีย! Gelkis ไม่ต้องการเจ้า ออกไปเดี๋ยวนี้!!\n\nฆ่า Magram ให้มากแล้วค่อยกลับมา ข้าจึงจะพูดด้วย" },
        completion = { "200:1854406636:641330713", "ชื่อเจ้าถูกกระซิบกันในหมู่ Gelkis มือเจ้าเปื้อนเลือด Magram มากมาย นี่เป็นเรื่องดี\n\nบางทีการที่เราพูดกันก็คงดีเช่นกัน พูดถึงสิ่งที่เจ้าทำให้ Gelkis ได้ และสิ่งที่เราทำให้เจ้าได้" },
        objectiveLabels = {
            reputation = { ["Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
        },
    },
    [1384] = { -- Raid on the Kolkar
        title = { "18:1777276974:1649500751", "บุกปล้น Kolkar" },
        objective = { "120:1324160233:1264421915", "รักษาชื่อเสียงกับ Gelkis และนำ Crude Charm 10 ชิ้นไปให้ Uthek the Wise ที่ Gelkis Village ใน Desolace" },
        description = { "287:179373633:1196412115", "เซนทอร์ Kolkar คิดว่าเวทมนตร์ของมันแข็งแกร่ง พวกมันไม่รู้จักเวทมนตร์ด้วยซ้ำ! ต่อให้เวทมนตร์กัด มันก็ยังไม่รู้จัก!\n\nเจ้าจะแสดงให้เห็นว่าเวทมนตร์ของมันอ่อนแอ ไปฆ่า Kolkar ทางตะวันออกเฉียงเหนือ เอาเครื่องรางมาให้ข้า ข้าจะโยนใส่ไฟแล้วหัวเราะ!" },
        progress = { "57:1374411631:305994126", "เจ้าได้เครื่องรางมาไหม? แสดงให้ Kolkar เห็นแล้วหรือว่ามันอ่อนแอ?" },
        completion = { "226:1570008052:1294242058", "เจ้าทำสิ่งที่ดีให้ Gelkis พวก Kolkar อ่อนแอและจะตาย เวทมนตร์น่าสมเพชช่วยมันไม่ได้ เจ้าแสดงให้เห็นแล้ว ความกลัวจะทำให้มันอ่อนแอกว่าเดิม!\n\nและในดินแดนของเรา ผู้อ่อนแอจะตายในไม่ช้า" },
        required = { [6079] = { "11:975502279:558553226", "เครื่องรางแบบหยาบ" } },
        steps = { { "11:975502279:558553226", "เครื่องรางแบบหยาบ" } },
        objectiveLabels = {
            reputation = { ["Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
        },
    },
    [1385] = { -- Brutal Politics
        title = { "15:208887324:1473548027", "การเมืองอันโหดเหี้ยม" },
        objective = { "66:2024496448:676264577", "เพิ่มชื่อเสียงกับ Magram ถึงระดับ Friendly แล้วคุยกับ Warug" },
        description = { "473:202083229:1402569731", "Desolace เป็นดินแดนแห่งสงคราม เซนทอร์รบกันเอง และเราเชื่อว่าผู้ชนะจะยกกำลังออกมาคุกคามฐานที่มั่นของเรา เราปล่อยให้เป็นเช่นนั้นไม่ได้\n\nเราต้องเรียนรู้วิธีเอาชนะเซนทอร์ และเพื่อทำเช่นนั้น... ต้องเป็นพันธมิตรกับเผ่าหนึ่ง Magram รบกับ Gelkis หากเจ้าต่อสู้กับ Gelkis บางที Magram อาจพิจารณาเป็นพันธมิตร\n\nสร้างความชอบกับ Magram แล้วคุยกับ Warug ที่หมู่บ้าน Magram ทางตะวันออกเฉียงใต้ของ Desolace" },
        progress = { "86:871139927:1894952667", "ไปเสียเดี๋ยวนี้ ไม่เช่นนั้น Magram จะบดขยี้เจ้า! หากอยากเป็นมิตร ต้องฆ่า Gelkis" },
        completion = { "115:1570936377:713300480", "Gelkis มากมายล้มตายด้วยมือเจ้า ข้าชอบ บางทีเจ้าอาจทำสิ่งที่ข้าชอบได้อีก บางทีเจ้ากับ Magram อาจเป็นมิตรกันได้" },
        objectiveLabels = {
            reputation = { ["Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
        },
    },
    [1386] = { -- Assault on the Kolkar
        title = { "21:842170257:2137716416", "โจมตี Kolkar" },
        objective = { "161:1035256529:628431293", "รักษาชื่อเสียงกับ Magram ฆ่า Kolkar Centaur 12 ตน, Kolkar Scout 12 ตน และ Kolkar Mauler 6 ตน แล้วกลับไปหา Warug ที่ Magram Village ใน Desolace" },
        description = { "171:2024809063:876666714", "Kolkar คิดว่ามันแข็งแกร่ง แต่เราหัวเราะใส่! เราหัวเราะแล้วฆ่ามัน! เจ้าก็ฆ่าด้วย แสดงให้เห็นว่าเจ้าฆ่า Kolkar ได้อย่างพวกเรา ไปทางเหนือแล้วฆ่าให้หมด!" },
        progress = { "129:1051382443:1405515040", "เจ้ากลัว Kolkar หรือ? ทำไมไม่ฆ่ามัน? บางทีเจ้าคงลืมวิธีฆ่า รีบฆ่า Kolkar ก่อนพวกมันตาย!" },
        completion = { "135:440111875:935112410", "ตอนนี้ Kolkar กลัวเจ้าแล้ว! หวังว่าเจ้าจะหัวเราะตอนฆ่ามัน หัวเราะไปฆ่าไปดีกว่า ศัตรูจะได้รู้ว่าตัวเองอ่อนแอ" },
        objectiveLabels = {
            reputation = { ["Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
            monster = { ["Kolkar Centaur slain"] = "ปราบ เซนทอร์ Kolkar", ["Kolkar Scout slain"] = "ปราบ หน่วยสอดแนม Kolkar", ["Kolkar Mauler slain"] = "ปราบ นักขย้ำ Kolkar" },
        },
    },
    [1387] = { -- Centaur Bounty
        title = { "14:1105463176:1262241555", "ค่าหัวเซนทอร์" },
        objective = { "71:1330487844:1926796288", "นำ Centaur Ear 15 ชิ้นไปให้ Corporal Melkins ที่ Nijel's Point ใน Desolace" },
        description = { "359:774306272:396603624 N 46:245535546:1430898300", "เผ่าเซนทอร์มีหลายเผ่า แต่ละเผ่ามีผู้นำและจุดหมายของตนเอง ทว่าทุกเผ่ามีสิ่งหนึ่งร่วมกัน นั่นคือความโหดร้าย\n\nหากเราจะมีสันติสุข ต้องกำจัดเซนทอร์ ข้าจึงมอบงานนี้ให้เจ้า\n\nระหว่างเดินทางใน Desolace จงล่าเซนทอร์และเก็บหู นำหูมาให้ข้ามาก ๆ\n\nทำเพื่อ Alliance เถิด {name} แล้วเราจะเข้าใกล้จุดจบสงครามอีกก้าว" },
        progress = { "22:1995813465:31713298 N 1:63:63", "เจ้ามีรายงานหรือไม่ {name}?" },
        completion = { "71:678624614:391295742 N 73:1092001045:708093345", "อา หูพวกนั้น ทำได้ดี\n\nการรับใช้ Alliance ของเจ้าไม่มีข้อกังขา {name} เลือดที่เจ้าหลั่งใน Desolace จะช่วยชีวิตอีกนับไม่ถ้วนอย่างแน่นอน" },
        required = { [6067] = { "11:349497811:132324303", "หูเซนทอร์" } },
        steps = { { "11:349497811:132324303", "หูเซนทอร์" } },
    },
    [1437] = { -- Vahlarriel's Search
        title = { "19:1128352940:1047339633", "การค้นหาของ Vahlarriel" },
        objective = { "62:1185585006:108828759", "ค้นหาและสำรวจเกวียนของ Tyranis กับ Dalinda Malem ใน Desolace" },
        description = { "17:938667301:1623817016 N 453:1871613496:1708432508", "ข้าคือ Vahlarriel {name} ข้ามาที่นี่เพื่อตามหาขุนนางสองคนที่หายไปจากตระกูลพ่อค้าของ Darnassus ตระกูล Malem ผู้เป็นบิดาหวาดกลัวสิ่งเลวร้ายที่สุด ข้าจึงต้องทำทุกอย่างเพื่อตามหาบุตรที่หายไปของเขา ข้ายังไม่ได้เริ่มค้นหา Tyranis หรือ Dalinda แต่หวังว่าจะไม่ต้องอยู่ที่นี่นาน\n\nข่าวล่าสุดบอกว่าพวกเขาผ่าน Stonetalon Mountains เมื่อไม่กี่สัปดาห์ก่อน\n\nหากเจ้าเจอเกวียน โปรดกลับมาหาข้าทันที" },
        completion = { "266:387668359:1443010539", "เมื่อคุณค้นซากเกวียน ก็เห็นชัดว่ามันถูกโจมตีทั้งด้วยเวทมนตร์และอาวุธ การต่อสู้ดูเหมือนจะจบรวดเร็วและฝ่ายหนึ่งเสียเปรียบอย่างมาก ไม่พบเลือดหรือซากศพใด ๆ\n\nผู้โจมตีเกวียนลงมือได้อย่างรวดเร็วและมีประสิทธิภาพ" },
    },
    [1438] = { -- Vahlarriel's Search
        title = { "19:1128352940:1047339633", "การค้นหาของ Vahlarriel" },
        objective = { "31:1028174781:931407887", "ตามหา Dalinda Malem ใน Desolace" },
        description = { "203:1914165391:1625859027 N 265:1910288456:57113115", "ตามหาทั้ง Dalinda และ Tyranis หากทำได้ แล้วกลับมารายงาน เริ่มค้นหาที่ป้อมนี้ ข้าจะติดต่อผู้บังคับบัญชาที่ Darnassus ทันทีเพื่อแจ้งสถานการณ์\n\n{name} ยังมีอีกเรื่องที่ข้าอยากย้ำ ผู้บังคับบัญชากังวลเรื่อง Tyranis และเจตนาที่มาที่นี่ พวกเขาให้ความสำคัญกับการพบ Dalinda และพากลับอย่างปลอดภัยมากกว่า ส่วน Tyranis ต้องได้รับการ... ประเมินก่อนพากลับบ้าน" },
        completion = { "54:1630119635:567630865 C 420:1187300856:1533526929", "ขอบคุณ Elune ในที่สุดก็มีคนมาช่วย โปรดเถิด {class} ข้าต้องการความช่วยเหลือ Tyranis พี่น้องข้ากับข้าถูก Burning Blade จับมาที่นี่ ข้าคิดว่าพวกมันจะสังเวยข้าให้เจ้านายปีศาจ!\n\nข้ารู้ว่าการมา Desolace เป็นความผิดพลาด แต่พักหลัง Tyranis กระหายความรู้ทุกอย่างด้านอาคม แม้ขัดต่อเจตจำนงของชาวเรา เขาตัดสินใจเดินทางมาทั้งที่ได้ยินว่าดินแดนนี้เต็มไปด้วยปีศาจ\n\nข้ากลัวว่าจะเกิดเรื่องเลวร้ายที่สุดกับเขา" },
    },
    [1439] = { -- Search for Tyranis
        title = { "18:84438545:1289882593", "ตามหา Tyranis" },
        objective = { "31:401876300:1345922830", "ตามหา Tyranis Malem ใน Desolace" },
        description = { "471:1621681289:832221816", "เราถูกพามาที่นี่หลังออร์คฆ่ายามกับคนรับใช้ทั้งหมด โอ้ สิ่งที่พวกมันทำช่างเลวร้าย! ข้าคิดว่ามันจะฆ่าเราตรงนั้นด้วย แต่เห็นได้ชัดว่ามันมีแผนอื่น\n\nTyranis พยายามพูดกับพวกมัน ข้าคิดว่าเขาอยากอวดความรู้อาคมให้มันประทับใจ... ไม่รู้ว่าเพราะอะไร\n\nขอร้องล่ะ ข้าจะไปจากที่นี่ไม่ได้จนกว่าจะรู้ว่าเกิดอะไรกับพี่น้องของข้า ตามหาเขา แล้วกลับมารับข้าเมื่อรู้ชะตาของเขาแล้ว" },
        progress = { "463:678530888:1385151741", "ข้ากลัวว่า Tyranis จะพยายามเรียนรู้ความลับของ Burning Blade และเข้าร่วมกับพวกมันหากได้รับอนุญาต เขาหลงใหลพลังที่เวทมนตร์มอบให้ผู้ลุ่มหลงมันเสมอ\n\nข้าไม่แน่ใจว่าจะทนกลับบ้านไปบอกครอบครัวได้ไหมว่าจิตใจ Tyranis กำลังเสี่ยงกับอันตรายเช่นนั้น สำหรับเผ่าพันธุ์ของข้า แค่แสวงหาสิ่งเหล่านี้ก็เป็นความผิดร้ายแรงแล้ว แต่การกลายเป็นสิ่งที่เราพยายามป้องกันตัวเองจากมัน... น่ากังวลอย่างยิ่ง" },
        completion = { "445:518238229:1061973691", "ช่างเลวร้าย! แต่ข้าคิดว่าคงจำเป็น หากไม่ตายด้วยมือเจ้า ก็คงตายด้วยมือชาวข้า ข้าคงควรขอบคุณ โปรดยกโทษหากฟังดูไม่จริงใจ ข้าไม่ได้ตั้งใจล่วงเกิน\n\nเมื่อรู้ชะตาของพี่น้องแล้ว ก็คงถึงเวลาหนี หากเจ้ายังยินดี ข้าขอรับความช่วยเหลือให้ออกจากสถานที่น่ากลัวนี้\n\nเมื่อพร้อม เราจะเดินทางไปสู่ความปลอดภัย" },
        required = { [6767] = { "16:1804462178:185351953", "จี้ของ Tyranis" } },
        steps = { { "16:1804462178:185351953", "จี้ของ Tyranis" } },
    },
    [1440] = { -- Return to Vahlarriel
        title = { "20:1373279175:105211964", "กลับไปหา Vahlarriel" },
        objective = { "101:897447644:1928082490", "คุ้มกัน Dalinda Malem ออกจาก Thunder Axe Fortress แล้วกลับไปหา Vahlarriel Demonslayer ใน Desolace" },
        description = { "278:1405613365:1850320930", "ถึงเวลาแล้วสินะ? ข้าขอบคุณความพยายามของเจ้า หากสถานการณ์ไม่เปิดโอกาสภายหลัง ก็ขอขอบคุณตอนนี้สำหรับทุกสิ่งที่ทำให้ข้ากับครอบครัว หากพร้อมแล้ว ที่นี่ก็ไม่มีอะไรให้ข้าอีก เราออกเดินทางได้เมื่อเจ้าเห็นว่าเหมาะ" },
        completion = { "11:1191658970:1224418299 N 400:1773941913:1235321", "ขอบใจ {name} Dalinda กลับมาที่ Nijel's Point อย่างปลอดภัย และสภาพดีกว่าที่ข้าหวังไว้มาก การที่นางมาถึงด้วยกำลังของตนเองเป็นสัญญาณที่ดี หวังว่าเจ้าจะสบายดีนะ?\n\nข้าเจ็บปวดที่รู้ว่า Tyranis กับ Dalinda ไม่ได้กลับมาทั้งสองคน แต่ความอับอายจากการตัดสินใจของ Tyranis เป็นสิ่งที่นางต้องแบกรับ นางต้องจัดการเรื่องนี้เมื่อกลับไป Darnassus" },
        objectiveLabels = {
            event = { ["Rescue Dalinda Malem"] = "ช่วย Dalinda Malem" },
        },
    },
    [1454] = { -- The Karnitol Shipwreck
        title = { "22:2145572850:1473736478", "ซากเรือของ Karnitol" },
        objective = { "34:1102657585:1217245208", "ค้นหา Karnitol's Chest ใน Desolace" },
        description = { "453:1744135018:1464514143", "งานแรกของข้าคือธุระให้จอมเวท Karnitol ขุนนางคนหนึ่งใน Stormwind ดูเหมือนเรือของเขาถูกยักษ์ทะเลโจมตีนอกชายฝั่งตะวันตกเฉียงเหนือของ Desolace เขากับคนรับใช้พยายามนำหีบมีค่าที่สุดใบหนึ่งขึ้นฝั่ง แต่เมื่อยักษ์ทะเลกรูกันมา เขาเลือกทิ้งหีบแล้วเคลื่อนย้ายตนเองกับคนรับใช้ไปที่ปลอดภัย\n\nเขาต้องการให้เราหาหีบกับของข้างใน แล้วนำไปคืนที่ Stormwind" },
        completion = { "263:961624822:386377417", "คุณสังเกตว่าหีบดูไม่เสียหายจากน้ำ\n\nสิ่งต่อมาที่เห็นคือฝาถูกงัดเปิด และกับดักเวทมนตร์ที่ป้องกันหีบถูกกระตุ้นไปนานแล้ว รอยไหม้ตามขอบบอกเรื่องนี้ได้อย่างชัดเจน" },
    },
    [1455] = { -- The Karnitol Shipwreck
        title = { "22:2145572850:1473736478", "ซากเรือของ Karnitol" },
        objective = { "36:1922957941:1027743291", "กลับไปหา Kreldig Ungor ใน Desolace" },
        description = { "452:1908372306:1171745247", "คุณใช้เวลาครู่หนึ่งหาว่าอะไรแงะหีบเปิดออก รอยขีดยาวลึกตามด้านข้างและฝาหีบบอกว่ามีสิ่งอื่นนอกจากมนุษย์หรือยักษ์สนใจหีบนี้ รอยดูไม่เหมือนเกิดจากมีดสั้นหรือดาบ\n\nเมื่อค้นดูข้างใน คุณพบว่าหีบว่างเปล่า\n\nเมื่อไม่รู้จะทำอย่างไรต่อ คุณจึงปิดหีบและเตรียมจากไป Kreldig คงผิดหวัง" },
        completion = { "31:1486333460:515110681 N 154:1288387470:589805067", "ยินดีต้อนรับกลับ Nijel's Point {name} บอกข้าสิว่าเจ้าพบอะไร\n\nอะไรนะ!? ไม่มีเลยหรือ? เกรงว่าหีบเปล่าจะไม่ทำให้เราได้เงิน\n\nเล่าเรื่องรอยที่เจ้าเห็นให้ฟังอีกหน่อย... รอยข่วนพวกนั้น" },
    },
    [1456] = { -- The Karnitol Shipwreck
        title = { "22:2145572850:1473736478", "ซากเรือของ Karnitol" },
        objective = { "67:772180002:886698423", "ค้นหา Karnitol's Satchel แล้วนำกลับไปให้ Kreldig Ungor ใน Desolace" },
        description = { "455:1392975118:524040775", "น่าสนใจ\n\nเอาล่ะ บางทีเราอาจยังไม่สิ้นหวัง\n\nตามชายฝั่งเดียวกัน แต่ขึ้นเหนือใกล้ Ranazjar Isle มีซากเมืองไนต์เอลฟ์อยู่ก้นทะเล นากาเผ่า Slitherblade ใช้เป็นที่อยู่ ข้าคิดว่านั่นเป็นเบาะแสที่ดีที่สุด\n\nหากหน่วยสอดแนมไปไกลถึงทางใต้ขนาดนั้น พวกมันต้องแข็งแกร่งทีเดียว หากจะหาข้าวของ Karnitol ข้าจะเริ่มจากนากาที่แข็งแกร่งกว่า เช่น Tidehunter หรือ Sea Witch" },
        progress = { "124:1640452088:1307798969 N 1:46:46", "ไม่ได้ตั้งใจล่วงเกินคนชื่อ Nijel หรอกนะ แต่ค่ายนี้ไม่ใช่ที่พักค้างคืนที่สบายที่สุดที่ข้าเคยเจอ ถ้าเจ้าเข้าใจที่ข้าหมายถึง {name}" },
        completion = { "15:328354176:1699534292 N 216:562893855:2136201365", "ยอดเยี่ยม {name}! เจ้าพบข้าวของ Karnitol แล้ว!\n\nนากาเจ้ากรรมพวกนั้นก่อเรื่องเสมอ ข้าว่ายอมทำสงครามกับ Horde ตลอดชีวิตยังดีกว่าต้องต่อกรกับพวกมัน เจ้าทำคุณประโยชน์อย่างยิ่งให้ Reclaimers" },
        required = { [6245] = { "18:215951582:576105223", "กระเป๋าสะพายของ Karnitol" } },
        steps = { { "18:215951582:576105223", "กระเป๋าสะพายของ Karnitol" } },
    },
    [1457] = { -- The Karnitol Shipwreck
        title = { "22:2145572850:1473736478", "ซากเรือของ Karnitol" },
        objective = { "61:1639641065:2027751420", "นำ Karnitol's Satchel ไปให้ Roetten Stonehammer ที่ Ironforge" },
        description = { "212:1207134084:235256446 N 139:1850441981:1586795341", "นำข้าวของ Karnitol กลับไปให้ Roetten ที่ Ironforge เขาจะจ่ายค่าตอบแทนสำหรับงานที่เจ้าทำได้ดี\n\nฮ่า ๆ ถ้าไม่ระวัง เขาอาจพอใจจนชวนเจ้าทำงานกับเราเต็มตัว\n\nอีกครั้งนะ ทำได้ยอดเยี่ยม {name}\n\nระวังตัวระหว่างกลับและอย่าชักช้านัก Karnitol ไม่ใช่คนอดทนที่สุด แต่เขาใจกว้างมากอยู่ดี" },
        progress = { "21:641603147:218607672 N 237:1454917017:1383128622", "ธุรกิจกำลังรุ่ง {name} ข้าไม่มีเวลาตอบคำถามมากนัก หากมีธุระกับ Reclaimers ก็ว่ามา ถ้าไม่มี คงต้องขอให้ไปคุยกับลูกน้องข้า พวกเขาเก่งพอจะดูแลงานแถวนี้" },
        completion = { "396:1125032937:1453013292 N 35:1910959153:1802688020", "อา งาน Karnitol ที่ Desolace ยอดเยี่ยม!\n\nหีบถูกทำลาย แต่ของอยู่ครบสินะ? ให้เจ้าตัวตัดสินเองแล้วกัน ข้อดีอย่างหนึ่งของธุรกิจนี้คือ ถ้าลูกค้าไม่พอใจ ข้าก็บอกให้ไปไกล ๆ ได้! เขาจ้างเราหาของ ไม่ใช่รับประกันว่าจะกลับไปสวยงามและสภาพดี\n\nทำได้ดี {name} มาดูกันว่าจะจ่ายค่าจ้างเจ้าอย่างไร" },
        required = { [6245] = { "18:215951582:576105223", "กระเป๋าสะพายของ Karnitol" } },
        steps = { { "18:215951582:576105223", "กระเป๋าสะพายของ Karnitol" } },
    },
    [1458] = { -- Reagents for Reclaimers Inc.
        title = { "28:1994818247:619312403", "ส่วนผสมให้ Reclaimers Inc." },
        objective = { "76:359006714:1491569533", "นำ Hatefury Claw 10 ชิ้น และ Hatefury Horn 10 ชิ้นไปให้ Kreldig Ungor ใน Desolace" },
        description = { "497:334826460:1256444136", "งานหนึ่งของข้าที่นี่คือหาส่วนผสมให้ Leftwitch จอมเวทโนมที่ Kharanos Roetten คิดว่าเป็นเงินหาง่ายเพราะเรามาที่นี่อยู่แล้ว เขาไม่สนเลยว่าเราแทบไม่มีคนพอทำงาน\n\nของสองสามอย่างแรกในรายชื่อน่าจะหาไม่ยาก และคนที่ช่วยข้าก็จะได้ค่าจ้างก้อนงาม\n\nข้าต้องการเขากับกรงเล็บของเซเทอร์ Hatefury ทางตะวันออก นำกลับมาให้ข้า แล้วเราค่อยเริ่มหาของที่เหลือ" },
        progress = { "288:1745759675:434678717", "พวกเซเทอร์น่ารังเกียจ ว่ากันว่ามีความเกี่ยวข้องกับไนต์เอลฟ์บางอย่าง แต่ข้าไม่แน่ใจว่าจะเชื่อดีไหม\n\nข้าว่าที่พูดกันคงเพราะเอลฟ์คนนั้นที่นำพวกมันเข้าสงครามเมื่อหลายปีก่อน โลกไม่เหมือนเดิมอีกเลย อันตรายและน่ากลัวขึ้นมาก" },
        completion = { "11:1903055375:367141247 N 223:134838434:178793688", "ดี ดี {name} ไม่รู้ว่าของพวกนี้คุณภาพดีไหม แต่ถ้า Leftwitch ต้องการชนิดเจาะจง เขาควรบอกก่อนส่ง Reclaimers มาที่นี่\n\nว่าอย่างไร ไปหาของชิ้นต่อไปในรายชื่อกันไหม?" },
        required = { [6246] = { "13:2048120484:1981439245", "กรงเล็บ Hatefury" }, [6247] = { "13:2133195956:1992733401", "เขา Hatefury" } },
        objectiveLabels = {
            item = { ["Hatefury Claw"] = "กรงเล็บ Hatefury", ["Hatefury Horn"] = "เขา Hatefury" },
        },
    },
    [1459] = { -- Reagents for Reclaimers Inc.
        title = { "28:1994818247:619312403", "ส่วนผสมให้ Reclaimers Inc." },
        objective = { "84:1697223779:1043865133", "นำ Scorpashi Venom 7 ขวด และ Aged Kodo Hide 3 ผืนไปให้ Kreldig Ungor ใน Desolace" },
        description = { "426:904436356:1788920292", "ของต่อไปในรายชื่อ Leftwitch คือ... ขอดูหน่อย... อืม อ้อ อยู่นี่\n\nง่ายดี แต่คำสั่งค่อนข้างเจาะจง เขาต้องการพิษ Scorpashi กับหนังโคโด ตัวหนังสือเล็กบอกว่าทั้งสองอย่างต้องมาจากสัตว์เฉพาะ พิษมาจาก Scorpashi ตัวไหนก็ได้ แต่หนังต้องจาก Aged Kodo ไม่ใช่ Dying หรือ Ancient\n\nพวกจอมเวทนะ ข้าบอกเลย ของบางอย่างที่ต้องการ... ประหลาดจริง ๆ" },
        progress = { "142:1521253350:887357403", "ขอโทษที่บอกไม่ได้ว่าจะหาโคโดหรือ Scorpashi ที่ไหน ข้าไม่ค่อยคุ้นพื้นที่ และยังไม่มีเวลาไปสำรวจ" },
        completion = { "25:1470041808:1265083902 N 295:2010161709:1524687476", "ความช่วยเหลือของเจ้ามีค่ามาก {name} เจ้าย่นเวลาที่ข้าต้องอยู่ Desolace ลงอย่างน้อยครึ่งหนึ่ง อีกไม่นานข้าจะได้กลับไปอุ่นเท้าที่ Ironforge เพราะเจ้า\n\nเมื่อจัดการรายชื่อนี้เสร็จและข้ากลับบ้านแล้ว มาหาสิ ข้าจะเลี้ยงเอลเจ้าแน่นอน\n\nแต่ก่อนถึงตอนนั้น มารวบรวมส่วนผสมที่เหลือให้ครบ" },
        required = { [6248] = { "15:539668281:1055303209", "พิษของ Scorpashi" }, [6249] = { "14:1399936408:657296508", "หนังโคโดวัยชรา" } },
        steps = { { "15:539668281:1055303209", "พิษของ Scorpashi" }, { "14:1399936408:657296508", "หนังโคโดวัยชรา" } },
    },
    [1465] = { -- Vahlarriel's Search
        title = { "19:1128352940:1047339633", "การค้นหาของ Vahlarriel" },
        objective = { "63:1218498425:623903790", "นำ Malem Pendant กลับไปให้ Vahlarriel Demonslayer ใน Desolace" },
        description = { "465:1495847557:1689581603", "ขณะค้นเกวียนต่อ คุณพบทั้งจี้และรอยเท้าที่มุ่งไปทางใต้ ไกลออกไปมีควันลอยจากป้อมใหญ่ ควันมาจากกองไฟที่มีคนดูแล ไม่ใช่อาคารที่กำลังไหม้ สัญชาตญาณบอกว่าหากสองพี่น้อง Malem ยังมีชีวิต พวกเขาคงถูกพาไปทางนั้น\n\nคุณคิดว่า Vahlarriel ที่ Nijel's Point ควรได้เห็นจี้ และรู้ถึงร่องรอยผู้คนทางใต้ด้วย" },
        completion = { "491:1881668124:2080249748", "น่าโมโห! เรื่องวุ่นวายทั้งหมดนี่!\n\nทั้งสองคนถูกเตือนแล้วว่ามาที่นี่อันตรายเพียงใด ตอนนี้กลับหายไป... หรืออาจเลวร้ายกว่านั้น\n\nเจ้าบอกว่าเห็นรอยมุ่งไปป้อมใกล้ ๆ หรือ? นั่นอาจเป็นเบาะแสที่ดีที่สุด\n\nคนท้องถิ่นบอกว่าป้อมเต็มไปด้วย Burning Blade ออร์คที่อุทิศตนให้ปีศาจ แม้ไม่ใช่ตัวแทนความเชื่อของ Horde ส่วนใหญ่ แต่พวกมันชั่วร้ายและจะฆ่าเจ้าทันทีหากถูกจับได้ว่าสอดแนม" },
        required = { [6479] = { "13:265656217:151645157", "จี้ Malem" } },
        objectiveLabels = {
            item = { ["Malem Pendant"] = "จี้ Malem" },
        },
    },
    [1466] = { -- Reagents for Reclaimers Inc.
        title = { "28:1994818247:619312403", "ส่วนผสมให้ Reclaimers Inc." },
        objective = { "105:923549476:343101832", "นำ Felhound Brain 10 ชิ้น, Nether Wing 10 ชิ้น และ Doomwarder Blood 10 ขวดไปให้ Kreldig Ungor ใน Desolace" },
        description = { "496:2140548682:1433415065", "นี่คือของชุดสุดท้าย ข้าไม่โกหกหรอก มันไม่สวยงามนัก และคงใช้เวลานานกว่าของชุดอื่น\n\nเอาล่ะ เตือนพอแล้ว มาเริ่มกัน Leftwitch ต้องการสมองสิบชิ้นจาก Mana Eater, Mage Hunter หรือ Ley Hunter ปีก Nether สิบชิ้นจาก Nether Maiden, Sister หรือ Sorceress และ... เลือด Doomwarder สิบขวดจาก Doomwarder Captain หรือ Lord\n\nง่ายดีใช่ไหม? เฮ้อ... ถ้าเจ้าอยากข้ามงานนี้ ข้าก็เข้าใจ" },
        progress = { "199:556432918:685984950", "ข้าไม่รู้ด้วยซ้ำว่าปีศาจพวกนี้อยู่ใน Desolace ข้อมูลล่าสุดที่อ่านบอกว่าเซนทอร์แทบยึดครองทั้งดินแดน หลังไนต์เอลฟ์เก็บของจากไปหลายปีก่อน\n\nสงสัยจริงว่าปีศาจมาอยู่ที่นี่ทำไม และมาได้อย่างไร" },
        completion = { "54:1351519865:2054912489 N 167:1491511554:1194846549", "จริงหรือ? ข้าไม่นึกเลย เจ้าสุดยอด {name} ต่อกรปีศาจเพื่อการทดลองของจอมเวท แถมกลับมาครบทุกส่วน ทำได้ดีมาก!\n\nข้าจะเล่าเรื่องเจ้าให้ Roetten ฟังด้วยตัวเองเมื่อกลับ Ironforge" },
        required = { [6250] = { "14:4842861:657136586", "สมองเฟลฮาวนด์" }, [6251] = { "11:896219799:608648646", "ปีกเนเธอร์" }, [6252] = { "16:1349408903:1831571469", "เลือด Doomwarder" } },
        steps = { { "14:4842861:657136586", "สมองเฟลฮาวนด์" }, { "11:896219799:608648646", "ปีกเนเธอร์" }, { "16:1349408903:1831571469", "เลือด Doomwarder" } },
    },
    [1467] = { -- Reagents for Reclaimers Inc.
        title = { "28:1994818247:619312403", "ส่วนผสมให้ Reclaimers Inc." },
        objective = { "67:1374418097:1148004325", "นำ Leftwitch's Package กลับไปให้ Roetten Stonehammer ที่ Ironforge" },
        description = { "329:264426252:1311689432", "หากจะรับเงิน เจ้าต้องกลับ Ironforge ไปคุยกับ Roetten เอง เขาคงดีใจที่ปิดงานพัสดุของ Leftwitch ได้ มอบของนี้ให้เขาก็น่าจะพอรับค่าจ้างแล้ว\n\nไม่ต้องห่วง ข้ายังจะพูดชมเจ้าเมื่อกลับไป ข้าคงอยู่ Desolace อีกไม่นาน" },
        progress = { "10:1401179418:1568553899 N 209:368648377:1718746336", "ยินดีที่ได้พบ {name} ธุรกิจกำลังรุ่ง เสียงค้อนทั่งดังก้องทั่ว Ironforge เครื่องสูบลมโหมไฟให้ร้อน และภรรยาจะทำพายให้ข้ากินหลังอาหารเย็นคืนนี้ ชีวิตจะมีอะไรดีไปกว่านี้อีก?" },
        completion = { "99:2007318780:137971143 C 171:1514487995:677580246", "อา พัสดุ Leftwitch จาก Desolace ยอดเยี่ยม ข้าขอบคุณที่ทำงานและส่งได้ตรงเวลา {class} ดีใจที่มีเจ้าร่วมงานแม้เพียงงานเล็กน้อยนี้\n\nค่าจ้างอยู่นี่ ให้รู้กันไปว่า Reclaimers Inc. จ่ายดีเสมอสำหรับการทำงานหนักตลอดสัปดาห์" },
        required = { [6253] = { "19:1413001661:281377408", "หีบห่อของ Leftwitch" } },
        objectiveLabels = {
            item = { ["Leftwitch's Package"] = "หีบห่อของ Leftwitch" },
        },
    },
    [5501] = { -- Bone Collector
        title = { "14:1808511169:462382279", "นักสะสมกระดูก" },
        objective = { "82:1816425196:1373915733", "นำ Kodo Bone 10 ชิ้นจาก Kodo Graveyard ไปให้ Bibbly F'utzbuckle ที่ Kormek's Hut" },
        description = { "428:1161444178:1918564796", "ข้าบอกเลยว่าเรากำลังนั่งทับเหมืองทอง เหมืองทองชัด ๆ! กระดูกโคโดจะเปลี่ยนโลกตลอดกาล... ลูกค้าข้าใช้ทำทั้งเครื่องเรือน เครื่องดนตรี แม้แต่ดินระเบิด\n\nมีกองคาราวานผ่านมาเอากระดูกโคโดของข้าไปขายที่ Shadowprey Village ถ้าเจ้าไปสุสานโคโดทางใต้แล้วนำกระดูกมาให้สิบชิ้น ข้าจะมีของตอบแทน ตกลงไหม?" },
        progress = { "142:1839298092:1163041225", "ได้กระดูกหรือยัง? คาราวานจะมาถึงเมื่อไรก็ได้ ข้าต้องการกระดูกโคโดอีกแค่สิบชิ้นก็จะทำสถิติสูงสุดในชีวิตการงาน สูงสุดในชีวิตเลยนะ!" },
        completion = { "223:862000606:1660254078", "อา ดีเลย! กระดูกของข้า!\n\nข้ารอให้พวกที่บ้านเห็นหน้าข้าบนปก Goblin'preneur ไม่ไหวแล้ว ข้าจะเป็นกอบลินรวยที่สุดในโลก... แล้วครูพละยังเคยบอกว่าข้าไม่มีวันได้ดี" },
        required = { [13703] = { "9:1073571437:156565678", "กระดูกโคโด" } },
        steps = { { "9:1073571437:156565678", "กระดูกโคโด" } },
    },
    [5561] = { -- Kodo Roundup
        title = { "12:1068810500:375066275", "ต้อนฝูงโคโด" },
        objective = { "101:1833720151:1611132577", "นำ Tamed Kodo ห้าตัวและ Kodo Kombobulator กลับไปให้ Smeed Scrabblescrew ที่ Scrabblescrew's Camp" },
        description = { "497:394902011:611185471", "Bibbly คิดว่าตัวเองเป็นกอบลินคนเดียวใน Desolace ที่รู้จักหาเงิน แต่กองคาราวานเดียวที่กล้าเดินทางแถวนี้ต้องพึ่งข้า ตั้งแต่ข้าเรียนรู้วิธีฟื้นกำลังและควบคุมโคโดแก่กับโคโดใกล้ตายด้วย Kodo Kombobulator ข้า Cork เจ้าของคาราวาน และ Rigger ก็ร่วมเป็นหุ้นส่วนกัน\n\nนำเครื่องไปใช้กับ Ancient Kodo, Aged Kodo หรือ Dying Kodo มันจะกระตุ้นให้สัตว์กลายเป็น Tamed Kodo และบังคับให้เดินตามเจ้า เมื่อทำให้เชื่องแล้ว ให้นำกลับมาหาข้า" },
        progress = { "88:2063595582:1049154970", "คาราวานใกล้มาถึงแล้ว เจ้ามีโคโดเชื่องใหม่ห้าตัวที่ข้าขอหรือยัง?" },
        completion = { "250:1901719328:1612847464", "<Smeed Scrabblescrew เริ่มนับ>\n\nสาม สี่ และห้า... ยอดเยี่ยม ข้าขอโคโดเชื่องห้าตัวก็ได้ห้าตัว... ข้าจะรวย... ใช่ รวยมาก! อยากเห็นสีหน้าเขียว ๆ ของ Bibbly ตอนรู้ความสำเร็จของข้าจริง ๆ!" },
        required = { [13892] = { "17:911206565:648944977", "เครื่องฝึกโคโด Kombobulator" } },
        steps = { { "11:1403688059:1712063415", "ฝึกโคโดให้เชื่อง" }, { "17:911206565:648944977", "เครื่องฝึกโคโด Kombobulator" } },
    },
    [5741] = { -- Sceptre of Light
        title = { "16:322113732:266492056", "คทาแห่งแสงสว่าง" },
        objective = { "91:1363657904:1761830977", "หา Sceptre of Light แล้วนำกลับไปให้ Azore Aldamort ที่หอคอยใน Ethel Rethor" },
        description = { "419:310588495:218934176", "มีข่าวลือว่า Burning Blade ที่ Thunder Axe Fortress ทางตะวันออกได้ Sceptre of Light มาจากนากา ตำนานกล่าวว่าคทาจมเมืองทั้งเมืองลงใต้มหาสมุทรได้ เราปล่อยให้ Burning Blade ครอบครองพลังเช่นนี้ไม่ได้\n\nด้วยเหตุนี้ เจ้าต้องไปเอาคทากลับมา! ผู้หยั่งรู้ของ Burning Blade คนหนึ่งถือมันไว้และศึกษามันบนหอคอยยามของ Thunder Axe" },
        progress = { "33:1016606189:1565966972", "เจ้าได้ Sceptre of Light มาหรือยัง?" },
        completion = { "105:352755810:1831793374 C 12:982035510:2123286806", "Sceptre of Light ที่ตามหากันมานาน! การที่เจ้าได้มันมาขจัดภัยร้ายแรงต่อโลก ทำได้ดี {class} ทำได้ดี" },
        required = { [15750] = { "16:322113732:266492056", "คทาแห่งแสง" } },
        objectiveLabels = {
            item = { ["Sceptre of Light"] = "คทาแห่งแสง" },
        },
    },
    [5821] = { -- Bodyguard for Hire
        title = { "18:2056803798:1986243122", "รับจ้างคุ้มกัน" },
        objective = { "117:831639757:2111280673", "คุ้มกัน Gizelton Caravan ผ่านหมู่บ้านเซนทอร์ Kolkar แล้วคุยกับ Smeed ที่ Scrabblescrew's Camp เพื่อรับรางวัล" },
        description = { "226:911559100:1631891882 C 269:1437527357:2145174022", "ตามปกติข้ากับ Rigger จะนำโคโดผ่านพวกเซนทอร์ Kolkar แต่บางครั้งได้ยินกลองศึกเซนทอร์เมื่อไรเราก็หยุด ตายไปไม่ดีต่อธุรกิจหรอก!\n\nเอาอย่างนี้ {class} หากเจ้าคุ้มกันเราผ่านหมู่บ้าน Kolkar เราจะจ่ายให้คุ้ม\n\nระยะทางสั้น ๆ เท่านั้น แค่รักษาคาราวานให้ปลอดภัย แล้วไปรับรางวัลจาก Smeed Scrabblescrew เขาอยู่ตามถนนไปอีกหน่อย เราทำธุรกิจร่วมกันเล็กน้อย" },
        progress = { "130:1870991417:2142141343", "ทำไมข้าต้องคอยคาราวานเจ้ากรรมนั่นด้วย?\n\n<Smeed ทำท่านึกขึ้นได้>\n\nอ้อ ใช่ พวกเขาจ่ายเงินนี่นา เจ้าเห็นพวกเขาไหม?" },
        completion = { "94:1903230907:1716752373 C 175:247445070:1641480810", "ข้าว่าการจ่ายเงินให้คนอย่างเจ้าคุ้มกัน Gizelton Caravan ไม่เห็นจะทำกำไรเลย {class} ถ้าข้าสูงอีกหน่อยก็คงรับงานเพิ่ม นั่งห้อยขาทั้งคู่ไปด้านเดียวบนหลังโคโดพร้อมปืนกระบอกใหญ่ที่สุดที่ถือไหว... แล้วให้เซนทอร์เจ้ากรรมนั่นรู้ว่าใครแน่กว่า" },
        objectiveLabels = {
            event = { ["Escort Gizelton Caravan past Kolkar Centaur Village"] = "คุ้มกันกองคาราวาน Gizelton ผ่านหมู่บ้านเซนทอร์ Kolkar" },
        },
    },
    [5943] = { -- Gizelton Caravan
        title = { "16:126262238:180634133", "คาราวาน Gizelton" },
        objective = { "108:1553554929:130718324", "คุ้มกัน Gizelton Caravan ผ่าน Mannoroc Coven แล้วคุยกับ Smeed ที่ Scrabblescrew's Camp เพื่อรับรางวัล" },
        description = { "24:1259926123:698813382 R 428:1907866979:378201346", "เจ้าดูเป็น {race} ที่มีฝีมือ กำลังหาเงินอยู่หรือเปล่า? ข้ากับ Cork เริ่มคาราวานนี้เพื่อทำเงินก้อนโต ไม่รู้เลยว่าการหาเงินอันตรายขนาดไหน!\n\nข้างหน้าคือ Mannoroc Coven ปกติปีศาจไม่สนใจเรา แต่คราวนี้มีบางอย่างทำให้โคโดตื่นกลัว ข้าจะจ่ายให้เจ้าคุ้มกันคาราวานผ่านไป เมื่อปลอดภัยแล้ว ไปรับรางวัลจาก Smeed หุ้นส่วนที่ Scrabblescrew's Camp ได้เลย" },
        progress = { "181:1044369798:1584718535", "รู้ไหม ถ้าคาราวานหายไป ข้าคงหมดตัว! เจ้าคงไม่ได้นำข่าวร้ายเรื่องคาราวานมาใช่ไหม?\n\n<Smeed เช็ดหน้าผาก>\n\nขอบคุณเทพีแห่งความโลภ!" },
        completion = { "237:2024734349:973003193", "ไม่แน่ใจว่าการจ่ายเงินมากขนาดนี้คุ้มกัน Gizelton Caravan เป็นข้อเสนอที่ทำกำไรจริงไหม Cork กับ Rigger หาได้แค่สัปดาห์ละหนึ่งเหรียญทอง แต่ตราบใดที่ยังจ่ายค่าโคโดให้ข้า ข้าก็ไม่สนว่าจะทำธุรกิจกันอย่างไร" },
        objectiveLabels = {
            event = { ["Escort Gizelton Caravan past Mannoroc Coven"] = "คุ้มกันกองคาราวาน Gizelton ผ่าน Mannoroc Coven" },
        },
    },
    [6027] = { -- Book of the Ancients
        title = { "20:1924476913:1640720766", "ตำราแห่งเหล่าผู้โบราณ" },
        objective = { "90:1984623915:2036637070", "หา Book of the Ancients แล้วนำกลับไปให้ Azore Aldamort ที่หอคอยใน Ethel Rethor" },
        description = { "N 366:1573189671:1682515803", "{name} ข้าฝาก Gem of the Serpent ไว้กับเจ้า วางอัญมณีบนมือ Serpent Statue ที่ Ranazjar Isle เกาะเล็กทางตะวันตกเฉียงเหนือของที่นี่ เมื่อวางแล้วจะอัญเชิญผู้ปกป้อง Book of the Ancients ตำรานี้บันทึกความลับนากาที่เก็บไว้มาหลายศตวรรษ นำมาให้ข้า แล้วเราจะรู้จักศัตรูมีเกล็ดของเรามากขึ้น!" },
        progress = { "4:1110228981:147916455 N 67:1913830652:532987220", "อา {name}! ดีใจที่พบอีกครั้ง เจ้าได้ Book of the Ancients มาหรือยัง?" },
        completion = { "184:971968343:2054874362", "Book of the Ancients ที่สูญหายไปนาน! ข้าจะดูแลให้ตำราถึงมือสภาสูง วันนี้เจ้าทำได้ดี และควรได้รับคำขอบคุณ... อย่างที่วีรชนสมควรได้รับ!" },
        required = { [15803] = { "20:1924476913:1640720766", "ตำราแห่งเหล่าผู้โบราณ" }, [15766] = { "18:2012263776:495868747", "อัญมณีแห่งอสรพิษ" } },
        steps = { { "20:1924476913:1640720766", "ตำราแห่งเหล่าผู้โบราณ" }, { "18:2012263776:495868747", "อัญมณีแห่งอสรพิษ" } },
    },
    [6132] = { -- Get Me Out of Here!
        title = { "19:1733765977:996764301", "พาข้าออกไปที!" },
        objective = { "96:867118652:1361603358", "คุ้มกัน Melizza Brimbuzzle แล้วคุยกับ Hornizz Brimbuzzle ที่ Kodo Graveyard ใน Desolace" },
        description = { "322:1747812634:793760579 N 91:416201314:1321974168", "พาข้าออกไปที!\n\nข้ามา Valley of Spears เพื่อคุยกับ Maraudine คิดว่าจะค้าขายกันได้สักหน่อย... แต่มันไม่อยากคุย! ข้าคิดว่ามันอยากกินข้า!\n\nพาข้าออกไป แล้ว Hornizz พี่น้องข้าจะจ่ายอย่างงาม! เขาอยู่ที่ค่ายข้างสุสานโคโดทางตะวันออก\n\nรีบเถิด {name} ยังไม่ถึงสองนาทีก่อน ข้าได้ยินเซนทอร์คุยกันว่าจะไปหาฟืนมาต้มหม้อ..." },
        progress = { "98:197892534:1095531678", "เจ้าเห็น Melizza พี่น้องของข้าไหม? นางชอบตะลอนไปทั่ว จนเจอปัญหาอยู่เสมอ" },
        completion = { "164:2007680639:1400337728", "Melizza พี่น้องของข้าบอกว่าเจ้าจะมา ขอบคุณมากที่ช่วยนางออกจากปัญหา เสียดายที่ป่านนี้คงไปก่อเรื่องใหม่แล้ว!" },
    },
    [6134] = { -- Ghost-o-plasm Round Up
        title = { "22:1895711703:1684513453", "รวบรวม Ghost-o-plasm" },
        objective = { "88:824390301:1822833677", "นำ Ghost-o-plasm 8 ชิ้นและ Crate of Ghost Magnets ไปให้ Hornizz Brimbuzzle ใน Desolace" },
        description = { "498:1463542245:417172552", "ทางตะวันออกเฉียงใต้มีหุบเขาชื่อ Valley of Bones ผี Magram หลอกหลอนอยู่ ฟังดูน่ากลัวใช่ไหม? ลองคิดว่าพวก Magram จะกลัวแค่ไหน! หากจับพลังผีจากที่นั่นได้ ข้าพนันว่าเซนทอร์ต้องยอมจ่ายแพง\n\nนี่ เอาลังแม่เหล็กผีไป หากวางชิ้นหนึ่งระหว่างโครงกระดูกใหญ่สองโครงในหุบเขาที่เรียกว่า Dead Goliaths ผีจะเดินเข้าหา ถอยให้ห่าง กำจัดผีแล้วเก็บ Ghost-o-plasm นั่นคือสิ่งที่เราจะขายให้ Magram", variants = { { "470:631046547:1778284052", "ทางตะวันออกเฉียงใต้มีหุบเขาชื่อ Valley of Bones ที่มีผีเซนทอร์หลอกหลอน ฟังดูน่ากลัวใช่ไหม? ลองคิดดูสิว่าพวกเซนทอร์จะกลัวแค่ไหน!\n\nนี่ เอาลังแม่เหล็กผีไป ถ้าวางชิ้นหนึ่งไว้ระหว่างโครงกระดูกใหญ่สองโครงในหุบเขาที่เรียกว่า Dead Goliaths ผีจะเดินเข้าหามัน ถอยให้ห่าง กำจัดผี แล้วเก็บ Ghost-o-plasm ของพวกมันมา\n\nข้าสงสัยว่าพวก Magram สนใจของเหนียว ๆ นี่เอามาก ๆ ข้าว่าจะขายให้พวกนั้น" } } },
        progress = { "26:265661183:1587144992 N 1:63:63", "Ghost-o-plasm ของข้าอยู่ไหน {name}?" },
        completion = { "113:1888155040:526973440 N 82:1981520786:881386515", "อยู่นั่นไง! ดูเหมือนจะติดตัวเจ้ามาด้วย ลื่น ๆ หน่อยใช่ไหม?\n\nขอบใจที่ลำบากให้ {name} ของนี้จะมีค่ามหาศาล... หากข้าอธิบายให้เซนทอร์เชื่อได้ว่ามันคืออะไร!" },
        required = { [15848] = { "22:1422716285:1354915736", "ลังแม่เหล็กล่อผี" }, [15849] = { "13:897625774:1662717995", "สารวิญญาณ Ghost-o-plasm" } },
        steps = { { "22:1422716285:1354915736", "ลังแม่เหล็กล่อผี" }, { "13:897625774:1662717995", "สารวิญญาณ Ghost-o-plasm" } },
    },
    [6141] = { -- Brother Anton
        title = { "13:1076026186:2066981124", "Brother Anton" },
        objective = { "37:1406686688:727972673", "คุยกับ Brother Anton ใน Desolace" },
        description = { "378:31046919:229933294", "Brother Anton สหายร่วมรบของข้าได้ยินข่าวลือว่าอันเดดแพร่ระบาดใน Kalimdor อันไกลโพ้น ดินแดนที่เรียก Desolace เขารีบจองเรือไปเพื่อตามหาและทำลายภัยอันเดดทันที!\n\nเขากำลังหาผู้กล้าหาญและมุ่งมั่นช่วยงาน หากใจเจ้าเที่ยงตรง จงคุยกับ Anton เขาอยู่ที่ Nijel's Point เมือง Alliance ใน Desolace" },
        completion = { "173:735075514:519922719", "ข้าได้ข่าวว่าความช่วยเหลือกำลังมาจากตะวันออก เจ้าคือต้นทางข่าวลือนั้นหรือ? มาช่วยภราดรสีชาดทำสงครามครูเสดหรือ?\n\nถ้าเช่นนั้น จงฟังให้ดี..." },
    },
    [79974] = { -- Wet Job
        title = { "7:992421264:481593566", "งานเปียกปอน" },
        objective = { "100:1003514985:509869321", "เมื่อปัดฝุ่นถุงส่งสารที่โผล่จากดิน คุณพบแผ่นหนังซุกอยู่ท่ามกลางเสบียง" },
        description = { "250:1166713141:1960547623", "\"ข้าชอบซ่อนเสบียงสำรองไว้ใกล้ ๆ เสมอ เผื่อต้องรีบหนี\n\nหน้าผาภูเขานี้งดงามจนเจ้าอาจบอกว่ามันสลักขึ้นจากน้ำตกแห่งกาลเวลา\n\nนั่นคือรังอินทรี นั่นแหละสิ่งที่เจ้ากำลังหา\"" },
        completion = { "37:1944415414:1944480880", "วิศวกรรมคนแคระ น่าอัศจรรย์เสมอ" },
    },
    [79980] = { -- Scramble
        title = { "8:980229343:1788796103", "ตะเกียกตะกาย" },
        objective = { "21:650534862:322147306", "ค้นหาสิ่งที่รอคุณอยู่" },
        description = { "211:2003298422:599573254", "\"ไม่เลวเลยใช่ไหม? ถ้าเจ้าอ่านนี่อยู่ แปลว่าที่ซ่อนเสบียงของข้ายังอยู่ เดินตรงขึ้นเหนือหนึ่งร้อยก้าว และอย่าให้ข้อเท้าหักตอนลงหน้าผาสูงชัน น่าจะมีเสบียงพอให้เจ้าไปต่อได้\"" },
        completion = { "94:251448626:818317424", "คุณดึงถุงส่งสารขึ้นจากพื้น แผ่นหนังสกปรกแผ่นหนึ่งถูกยัดรวมกับเสบียง" },
    },
    [86574] = { -- Stonetalon Supply Run
        title = { "21:317578034:686062820", "ขนเสบียง Stonetalon" },
        objective = { "91:2075940811:1186385769", "เก็บ Stonetalon Supplies 6 ชิ้นจาก Pridewing Wyvern แล้วนำไปให้ Innkeeper Faralia", variants = { { "8:1089852795:1107240600 W1 82:923691969:1065489348", "เก็บ Stonetalon Supplies {world1} ชิ้นจาก Pridewing Wyvern แล้วนำไปให้ Innkeeper Faralia" } }, amount = { "8:1089852795:1107240600 W1 82:923691969:1065489348", "เก็บ Stonetalon Supplies {world1} ชิ้นจาก Pridewing Wyvern แล้วนำไปให้ Innkeeper Faralia" } },
        description = { "375:1517473821:1264466776", "<ศพผู้เคราะห์ร้ายมีรอยโจมตีมากมายจากไวเวิร์น Pridewing กระเป๋าใกล้ ๆ ยับยู่และถูกทิ้ง ของข้างในหายไป เหลือเพียงบันทึกเล็กที่กำในมือผู้ส่งสาร บอกว่าสิ่งที่หายคือเสบียงสำหรับ Innkeeper Faralia ที่ Stonetalon Peak>\n\n<ไวเวิร์นคงคาบห่อเสบียงไปบุรัง>" },
        progress = { "34:1340015299:87095106", "หวังว่าของที่ส่งมาจะมาถึงเร็ว ๆ นี้..." },
        completion = { "201:1426949552:919824601", "เจ้าพบเสบียงที่หายไปแล้วหรือ\n\nอ้อ ข้าไม่รู้เลยว่าคนส่งของไปไม่ถึงที่หมาย ช่างเป็น... เรื่องน่าเศร้าจริง ๆ\n\nข้าจะใช้เสบียงนี้ให้เกิดประโยชน์ ความสูญเสียของนางจะได้ไม่เปล่าประโยชน์", variants = { { "201:217319954:2019968805", "เจ้าพบเสบียงที่หายไปแล้วหรือ\n\nอ้อ ข้าไม่รู้เลยว่าคนส่งของไปไม่ถึงที่หมาย ช่างเป็น... เรื่องน่าเศร้าจริง ๆ\n\nข้าจะใช้เสบียงนี้ให้เกิดประโยชน์ ความสูญเสียของนางจะได้ไม่เปล่าประโยชน์" } } },
        required = { [277917] = { "24:33649:1523975389", "ห่อเสบียง Stonetalon" }, [277915] = { "25:603629854:1044734897", "กระเป๋าเสบียง Stonetalon" } },
        objectiveLabels = {
            item = { ["Stonetalon Supply Bundle"] = "ห่อเสบียง Stonetalon", ["Stonetalon Supply Satchel"] = "กระเป๋าเสบียง Stonetalon" },
        },
    },
    [92743] = { -- A Conqueror's Crown
        title = { "19:2034249736:635153959", "มงกุฎผู้พิชิต" },
        objective = { "118:852469090:294699621", "รักษาชื่อเสียงกับ Magram และนำ Conqueror's Crown จาก Badlands ไปให้ Warug ที่ Magram Village" },
        description = { "418:430722696:1427968769", "เราเป็นเผ่าเซนทอร์แข็งแกร่งที่สุดในดินแดน สมควรมีอาวุธยุทโธปกรณ์ดุดันสมกำลัง!\n\nWarug ต้องการที่สุด หมวกเกราะ... ไม่สิ มงกุฎ! มงกุฎผู้พิชิต! ข้าได้ยินตำนานผู้พิชิตน่าเกรงขามข้ามทะเล ไปดินแดนที่เรียก Badlands ตามหาสุสานใต้ดิน กลับมาเมื่อพบมงกุฎเท่านั้น\n\nทำให้ข้า แล้วข้าจะเผยความแข็งแกร่งที่สุดของ Magram" },
        completion = { "169:86318733:697252497", "ดูนี่สิ! ดูให้ดี! มงกุฎช่างงาม! เหมาะกับข่าน... แต่ Warug จะเป็นคนสวม ข้าพอใจมาก\n\nเจ้าพร้อมเรียนรู้เรื่องอาวุธล่าสุดที่ Magram จะใช้รับมือศัตรูหรือยัง" },
        progress = { "18:252551699:2012056404", "ไม่มีมงกุฎ ก็ไม่ต้องคุย!" },
        required = { [254392] = { "16:684100840:1518716400", "หมวกเกราะของผู้พิชิต" } },
        steps = { { "16:684100840:1518716400", "หมวกเกราะของผู้พิชิต" } },
        objectiveLabels = {
            reputation = { ["Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
        },
    },
    [92754] = { -- A New Need for Shadow Protection
        title = { "32:1349849839:1708159264", "ความต้องการใหม่ในการป้องกันเงามืด" },
        objective = { "131:476821145:664871699", "รักษาชื่อเสียงกับ Magram และนำ Greater Shadow Protection Potion 3 ขวดไปให้ Mirda ที่ Magram Village ใน Desolace", variants = { { "52:1491736042:485491818 W1 78:1137501411:1635868431", "รักษาชื่อเสียงกับ Magram และนำ Greater Shadow Protection Potion {world1} ขวดไปให้ Mirda ที่ Magram Village ใน Desolace" } }, amount = { "52:1491736042:485491818 W1 78:1137501411:1635868431", "รักษาชื่อเสียงกับ Magram และนำ Greater Shadow Protection Potion {world1} ขวดไปให้ Mirda ที่ Magram Village ใน Desolace" } },
        description = { "412:1417916684:592766388", "คนในเผ่ายังคงเดินทางลงใต้ ไปถึงและเลย Valley of Bones ต้องสาป\n\nแม้เจ้าจะมีชื่อเสียงกับเผ่า ข้าก็ยังไม่ไว้ใจพอจะบอกรายละเอียดการเดินทาง คงน่าเบื่อสำหรับเจ้าด้วยซ้ำ คนนอก\n\nสิ่งที่เจ้าต้องรู้คือเราต้องการ Greater Shadow Protection Potion จำนวนมากเพื่อให้พวกเขารอดต่อไป นำมาให้ข้า แล้วข้าจะพูดชมเจ้าให้" },
        required = { [13459] = { "32:120334530:1656858663", "ยาป้องกันพลังเงาระดับสูง" } },
        steps = { { "32:120334530:1656858663", "ยาป้องกันพลังเงาระดับสูง" } },
        objectiveLabels = {
            reputation = { ["Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
