    [92755] = { -- Mysterious Mysticism
        title = { "20:1538429639:1405146480", "ศาสตร์ลี้ลับอันน่าพิศวง" },
        objective = { "121:1729536959:1094319427", "รักษาชื่อเสียงกับ Gelkis และนำ Greater Mystic Essence 3 ชิ้นไปให้ Halea ที่ Gelkis Village ใน Desolace", variants = { { "52:796760103:801070908 W1 68:1244970208:282692476", "รักษาชื่อเสียงกับ Gelkis และนำ Greater Mystic Essence {world1} ชิ้นไปให้ Halea ที่ Gelkis Village ใน Desolace" } }, amount = { "52:796760103:801070908 W1 68:1244970208:282692476", "รักษาชื่อเสียงกับ Gelkis และนำ Greater Mystic Essence {world1} ชิ้นไปให้ Halea ที่ Gelkis Village ใน Desolace" } },
        description = { "454:237763541:408036559", "ทุกวัน ผู้เก็บกู้ของเรากลับมาพร้อมอาวุธยุทโธปกรณ์จากนักผจญภัยที่ตายน้อยลงเรื่อย ๆ\n\nแม้ใช้ตรง ๆ ไม่ได้ เราก็แยกเป็นเศษวัสดุ ของที่มีเวทมนตร์สูงสุดมาถึงข้า เพราะข้าสลายอาคมและใช้ส่วนตกค้างลึกลับลงอาคมอาวุธเราได้ โดยเฉพาะของเหล่า Windchaser\n\nข้าต้องการ Greater Mystic Essence เพื่อจัดอุปกรณ์ที่มีค่าให้หน่วยจู่โจมต่อไป" },
        completion = { "318:602557299:1310423212", "ความมีน้ำใจของเจ้าช่างแปลกนัก แทบไม่เคยพบเห็นในดินแดนแถบนี้\nการสลายมนตร์จากอุปกรณ์ยังเป็นเรื่องใหม่สำหรับข้า และข้ามักรู้สึกว่าดึงพลังจากของเก่าพวกนี้ออกมาได้ไม่เต็มที่ แก่นพลังที่เจ้านำมาช่วยชดเชยส่วนที่เสียไปได้บ้าง\nเผ่า Gelkis โดยเฉพาะเหล่าผู้ใช้มนตราของเรา ขอขอบใจเจ้า" },
        progress = { "288:2074815447:709406189", "เผ่าของเราดึงพลังส่วนใหญ่มาจาก Tears of Theradras เจ้าอาจเคยเห็นผลึกพวกนี้อยู่ตามผนังถ้ำของข่าน แต่เมื่อเวลาผ่านไป บางชิ้นก็สูญหาย ถูกทำลาย หรือใช้พลังจนหมด\nวัตถุดิบพวกนี้เป็นของใหม่สำหรับข้า ส่วนมนตร์เสริมพลังนั้นข้าคุ้นเคยดี" },
        required = { [11135] = { "22:1286331229:1743228910", "แก่นพลังลี้ลับระดับสูง" } },
        steps = { { "22:1286331229:1743228910", "แก่นพลังลี้ลับระดับสูง" } },
        objectiveLabels = {
            reputation = { ["Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
        },
    },
    [92811] = { -- Economic Warfare
        title = { "16:853937619:1206083235", "สงครามเศรษฐกิจ" },
        description = { "456:1927699671:1518416968", "สงครามสอนเราอยู่อย่างหนึ่ง เงินคืออำนาจ\n\nเซนทอร์ทุกเผ่าใน Desolace ตกลงกันว่าจะใช้ไม้แกะสลักลวดลายประณีตแลกเปลี่ยนสิ่งของ ลวดลายเหล่านั้นบอกเล่าเกียรติยศและชัยชนะของเซนทอร์ผู้เป็นเจ้าของ นี่เป็นช่วงพักจากการสู้รบเพียงอย่างเดียว และมีเพียงผู้ที่สุขุมที่สุดเท่านั้นที่ได้รับอนุญาตให้ติดต่อกับเผ่าอื่น\n\nข้าเคยเห็นพวกเจ้าใช้ทองกับเงินค้าขาย ของพวกนั้นไร้ค่าสำหรับเรา เช่นเดียวกับที่โทเท็มของเราไร้ค่าสำหรับเจ้า นำโทเท็มมาให้ข้าสักหน่อย แล้วเผ่า Magram จะพอใจ" },
        progress = { "456:1927699671:1518416968", "สงครามสอนเราข้อหนึ่ง เงินคืออำนาจ\n\nเหล่าเซนทอร์ทั่ว Desolace ตกลงกันว่าจะใช้ไม้แกะสลักลวดลายประณีตแลกเปลี่ยนสินค้า ลายเหล่านั้นบอกเล่าเกียรติยศและชัยชนะของเซนทอร์แต่ละตน การค้านี่แหละเป็นช่วงเดียวที่เราพักจากการรบ และมีเพียงผู้สุขุมที่สุดที่ได้รับอนุญาตให้ติดต่อกับเผ่าอื่น\n\nข้าเห็นพวกเจ้าใช้ทองกับเงินค้าขาย ของพวกนั้นไร้ค่าสำหรับเรา พอ ๆ กับที่โทเท็มของเราไร้ค่าสำหรับเจ้า หามาให้ข้าสักหน่อย เผ่า Magram จะพอใจ" },
        completion = { "65:411539279:501362861", "ตัดสินใจได้ฉลาดดี คนนอก พวกเราจะจดจำความเอื้อเฟื้อของเจ้าไว้" },
    },
    [92814] = { -- I Need a Tailor
        title = { "15:182281179:1858808476", "ข้าต้องการช่างตัดเย็บ" },
        objective = { "116:1317943585:2126402090", "รักษาชื่อเสียงกับ Gelkis และนำ White Bandit Mask ไปให้ Molkar ที่ Gelkis Village ใน Desolace" },
        description = { "496:1789689961:1228974680", "Halea คู่ของข้ารับหน้าที่ทำให้อาวุธยุทโธปกรณ์เสริมพลังเวทมนตร์อย่างเหมาะสม\n\nข้าไม่เข้าใจการลงอาคมเลย แต่ในฐานะเซนทอร์ที่จัดหาเสบียงและอุปกรณ์ให้หมู่บ้าน ข้ารู้ว่างาน Halea มักล่าช้า โดยไม่ใช่ความผิดนาง\n\nข้าอยากให้เสื้อผ้าธรรมดาเป็นของขวัญไว้ฝึก ข้าเห็นนักผจญภัยเดินฝ่าพายุทรายด้วยหน้ากากเรียบง่าย เจ้าหามาให้ข้าบ้างได้ไหม?" },
        completion = { "200:1149809787:1285702206", "ของพวกนี้ดูเก่าไปหน่อย ตะเข็บก็ลุ่ยอยู่บ้าง แต่ฝีมือยังดีมาก ดีกว่าอุปกรณ์ขาดวิ่น บุบพัง และเปื้อนเลือดที่นางได้รับทุกวันเสียอีก\nขอบใจเจ้ามาก" },
        progress = { "144:1062794052:235590265", "ถ้าเจ้าช่วยเรื่องนี้ ก็เหมือนเสียบพวก Magram สองตัวด้วยหอกเล่มเดียว! เจ้าได้ช่วยเผ่า Gelkis ทำศึก และช่วยให้ Halea ฝึกฝีมือไปด้วย" },
        required = { [10008] = { "17:1391432135:1068420033", "หน้ากากโจรสีขาว" } },
        steps = { { "17:1391432135:1068420033", "หน้ากากโจรสีขาว" } },
        objectiveLabels = {
            reputation = { ["Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
        },
    },
    [92817] = { -- Leather Technique
        title = { "17:1232592897:910203202", "เทคนิคเครื่องหนัง" },
        objective = { "114:1843006353:1882468448", "รักษาชื่อเสียงกับ Gelkis และนำ Barbaric Harness ไปให้ Talra ที่ Gelkis Village ใน Desolace" },
        description = { "466:1035055370:1848465356", "การกล่อมคนใน Gelkis ให้สวมเกราะแทบเป็นไปไม่ได้ แม้จะสูญเสียมากจากคมดาบหรือลูกธนูหน้าไม้ทะลุอก\n\nข้าได้รับหน้าที่ออกแบบเสื้อที่ป้องกันได้พอควร โดยไม่ทำให้ 'คัน' อย่างที่พวกเขาบ่น วัสดุมีน้อย ไม่กล้าทิ้งหนังมีค่าไปกับของไร้ประโยชน์\n\nคนนอก นำเครื่องหนังสวมลำตัวที่เหมาะกับเซนทอร์ร่างบึกบึนมาให้ได้ไหม? ข้าอยากเรียนรู้เทคนิคของเจ้า" },
        completion = { "230:129449724:2134192269", "อืม ข้าคงบอกไม่ชัดพอว่าต้องการอะไร บางทีลองศึกษาสิ่งนี้ดูอาจได้ความรู้อะไรอยู่บ้าง\nอย่างไรก็ดี เจ้ายังคอยช่วยเหลือเผ่า Gelkis ข้าจะบอกคนอื่น ๆ ให้รู้ถึงความช่วยเหลือของเจ้า" },
        progress = { "118:1261437393:1836108988", "เจ้าคงมีเวลาเหลือเฟือ คนต่างถิ่น แต่เผ่าของข้ากำลังทำสงครามอยู่ ถ้าคิดจะช่วยก็รีบหน่อย" },
        required = { [5739] = { "16:1660380396:1804621080", "เครื่องรัดกายแบบชนเผ่า" } },
        steps = { { "16:1660380396:1804621080", "เครื่องรัดกายแบบชนเผ่า" } },
        objectiveLabels = {
            reputation = { ["Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
        },
    },
    [92818] = { -- Big, No, MASSIVE Iron Axes
        title = { "26:1313719673:1646576055", "ขวานเหล็กใหญ่ ไม่สิ มหึมา!" },
        objective = { "117:1868510214:822520913", "รักษาชื่อเสียงกับ Magram และนำ Massive Iron Axe 2 เล่มไปให้ Grolkar ที่ Magram Village ใน Desolace", variants = { { "52:1491736042:485491818 W1 64:586145416:477434783", "รักษาชื่อเสียงกับ Magram และนำ Massive Iron Axe {world1} เล่มไปให้ Grolkar ที่ Magram Village ใน Desolace" } }, amount = { "52:1491736042:485491818 W1 64:586145416:477434783", "รักษาชื่อเสียงกับ Magram และนำ Massive Iron Axe {world1} เล่มไปให้ Grolkar ที่ Magram Village ใน Desolace" } },
        description = { "178:1353158250:1643685043", "เราต้องการอาวุธเพิ่ม!\n\nอาวุธ เพิ่มอีก!\n\nไม่อย่างนั้น Magram จะบดขยี้ Gelkis ตัวจ้อยได้อย่างไร?\n\nข้าอยากเห็นว่าเจ้าสร้างอะไรได้ คนนอก นำขวานมา ใหญ่ ไม่สิ มหึมา!\n\nรีบเข้า!" },
        required = { [3855] = { "16:1022735601:1035782688", "ขวานเหล็กขนาดมหึมา" } },
        steps = { { "16:1022735601:1035782688", "ขวานเหล็กขนาดมหึมา" } },
        objectiveLabels = {
            reputation = { ["Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
        },
    },
    [93044] = { -- A Cleansing Cry
        title = { "15:509673040:1169502516", "เสียงร่ำไห้แห่งการชำระล้าง" },
        objective = { "112:462114555:1797629017", "รักษาชื่อเสียงกับ Gelkis และนำ Tears of Theradras กลับไปให้ Uthek the Wise ที่ Gelkis Village" },
        description = { "343:2023078911:888016757", "เมื่อกลับไปหา Nerlokh ที่ Valley of Bones เจ้าจะไม่กลับมือเปล่า\n\nเข้าถ้ำใจกลางหมู่บ้านเราแล้วหา Mulara ขอน้ำตา Theradras ในนามข้า ของเหลือน้อย แต่มันเป็นความหวังดีที่สุดต่อศาสตร์ปลุกคนตายอันชั่วร้ายของ Magram!\n\nข้าจะเตรียมพิธี เราจะสร้างอาวุธขัดขวางคาถาของมัน" },
        completion = { "201:498068743:839124954", "ข้าดีใจที่ Mulara มาช่วยเราได้ ข้ารู้ว่านางจะพยายามช่วย แต่เกรงว่าจะไม่มีผลึกเหลือให้เรา\n\nพักให้ใจสงบสักครู่ อีกเดี๋ยวข้าจะอธิบายแผนให้ฟัง" },
        progress = { "7:2044825444:644190917 N 48:128412175:1585686218", "รีบหน่อย {name} เราปล่อยให้ Nerlokh อยู่โดยไม่มีคนคุ้มกันนานนักไม่ได้" },
        required = { [255878] = { "17:1052923541:1265925536", "หยาดน้ำตาแห่ง Theradras" } },
        steps = { { "17:893124432:2039258153", "คุยกับ Mulara" }, { "17:1052923541:1265925536", "หยาดน้ำตาแห่ง Theradras" } },
        objectiveLabels = {
            reputation = { ["Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [93128] = { -- Khan Jehn
        title = { "9:2111294994:713864601", "ข่าน Jehn" },
        objective = { "160:1139300869:1645883100", "รักษาชื่อเสียงกับ Gelkis และฆ่า Khan Jhen ที่ Magram Village เมื่อสำเร็จแล้ว รายงานต่อ Uthek the Wise ที่ Gelkis Village ใน Desolace" },
        description = { "349:1987691469:849759156 N 145:23967414:1266627582", "แม้อยากให้ Uthek หรือข่าน Shaka ออกคำสั่ง ข้ากลัวว่าโอกาสมีสั้นเกินไป สั้นเกินกลับไปปรึกษาคนที่ Gelkis Village\n\nจากสถานการณ์ที่ Valley of Bones ข้าเชื่อว่า Magram เหลือคนคุ้มกันข่าน Jehn น้อยมาก หากมีเวลาใดควรโจมตีข่านอีกเผ่า ก็ตอนนี้\n\nแต่ {name} ข่านไม่ใช่คู่ต่อสู้ให้ประมาท โดยเฉพาะ Jehn ถ้ากล้าลงมือ ต้องรวดเร็วแต่อย่าดูถูกเขา" },
        completion = { "456:1463886579:1010423392", "Khan Jehn ถูกสังหารแล้วหรือ!?\n\nข้าไม่เชื่อ ข้าไม่อยากเชื่อเลย บ้าบิ่น! โง่เขลา! Nerlokh ไม่มีอำนาจเสนอให้โจมตีเช่นนั้น!\n\nแต่ถ้าเจ้าพูดจริง ข้าก็ปฏิเสธไม่ได้ว่าความพ่ายแพ้ของ Jehn เป็นลางดีสำหรับอนาคตของเผ่าเรา อีกไม่นานจะมีข่านคนใหม่ขึ้นแทน แต่เรายังมีเวลาเตรียมก้าวต่อไป\n\nข้าจะคุยกับข่านของเรา ตอนนี้งานของเจ้าที่นี่จบแล้ว ชื่นชมชัยชนะวันนี้เสีย แต่อย่าลองดีกับชะตาไปมากกว่านี้" },
        objectiveLabels = {
            reputation = { ["Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
            monster = { ["Khan Jehn slain"] = "ปราบ ข่าน Jehn" },
        },
    },
    [93196] = { -- Khan Jehn
        title = { "9:2111294994:713864601", "ข่าน Jehn" },
        objective = { "174:656129401:65848362", "รักษาชื่อเสียงกับ Magram และทำพิธีปลุกคนตายเพื่อคืนชีพ Khan Jehn จุดทำพิธีอยู่ในเต็นท์บริเวณทะเลสาบกลาง Magram Village" },
        description = { "460:1662543120:1454684760", "ผู้นำเผ่าเรา ข่าน Jehn ถูกกลุ่มคนนอกเช่นเจ้าฆ่า พวกนั้นทำงานให้ Gelkis\n\nหยุดแกล้งแปลกใจได้แล้ว การบุก Magram Village ขณะที่เราสนใจที่อื่นเป็นกลศึกคาดเดาได้ โดยเฉพาะสำหรับ Gelkis\n\nรู้ไหมทำไมข้าไม่โกรธหรือเสียใจ คนนอก?\n\n<Orgrul มอบอาวุธคุ้นตาให้ แต่พลังมากกว่าครั้งสุดท้ายที่เจ้าถือมัน>\n\nเพราะสิ่งนี้" },
        completion = { "134:780149122:424248785 N 277:268049374:1129604991", "พวก Gelkis เกณฑ์คนนอกมาทำกลศึกสกปรกที่เผ่าเราคงส่งพวกเขาไปตายเสียมากกว่า\n\nแต่เจ้าก็ยืนอยู่ตรงนี้ {name} คนนอกที่แสดงความภักดีต่อเผ่า Magram อย่างแรงกล้า แม้พวกเราจะไม่ต้อนรับเจ้าเลย\n\nข้าไม่รู้แรงจูงใจของเจ้า แต่ข้าเห็นศักยภาพของเจ้าด้วยตาตนเอง เจ้าจงรับคำขอบใจจากข้าและเผ่าของเรา\n\nสำหรับเรา เจ้าพ้นจากการเป็นคนนอกแล้ว เจ้าเป็น Magram" },
        steps = { { "21:787354062:1066183358", "ชุบชีวิต Khan Jehn" } },
        objectiveLabels = {
            reputation = { ["Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [93224] = { -- Carved Centaur Totems
        title = { "21:1177682493:1777840503", "โทเท็มเซนทอร์แกะสลัก" },
        objective = { "139:1762810074:1031640717", "เก็บ Carved Centaur Totem 5 ชิ้นโดยฆ่าเซนทอร์เผ่าใดก็ได้ทั่ว Desolace แล้วนำกลับไปให้ Captain Pentigast ที่ Nijel's Point", variants = { { "8:1617296333:1647798940 W1 130:1339780510:49452096", "เก็บ Carved Centaur Totem {world1} ชิ้นโดยฆ่าเซนทอร์เผ่าใดก็ได้ทั่ว Desolace แล้วนำกลับไปให้ Captain Pentigast ที่ Nijel's Point" } }, amount = { "8:1617296333:1647798940 W1 130:1339780510:49452096", "เก็บ Carved Centaur Totem {world1} ชิ้นโดยฆ่าเซนทอร์เผ่าใดก็ได้ทั่ว Desolace แล้วนำกลับไปให้ Captain Pentigast ที่ Nijel's Point" } },
        description = { "486:203978962:1205913935", "เจ้าคงไม่แปลกใจที่เซนทอร์ทั้งสองเผ่าลังเลรับความช่วยเหลือจากคนนอก โดยเฉพาะพวกเจ้าและข้า ที่ไม่ใช่เซนทอร์\n\nสิ่งที่เราทุกคนเข้าใจร่วมกันคือเงินคืออำนาจ และเรารู้ว่าเซนทอร์ท้องถิ่นใช้ไม้แกะสลักแลกเปลี่ยน หากนำตัวอย่างลายมาให้สักหน่อย ข้าสั่งทำรอยสลักคล้ายกันอย่างเร่งด่วนได้ บางทีเราจะซื้อความได้เปรียบให้ตัวเอง" },
        progress = { "34:2104145445:631943986", "เจ้ากลับมาพร้อมโทเท็มแล้วหรือ" },
        completion = { "320:109174392:1798539277", "ข้าไม่ใช่เซนทอร์ แต่ดูแล้วโทเท็มมัดนี้น่าจะพอ ถ้าข้าเป็นพวกเขา ข้าคงยินดีที่ได้ของขวัญเช่นนี้ ระหว่างที่เจ้าออกไป ข้าหาเพิ่มมาได้อีกสองสามชิ้นด้วย\n\nมาคุยกับข้าเมื่อเจ้าพร้อมเอาไปส่ง ข้าเชื่อว่าเจ้าจะเลือกเผ่าที่เราควรเข้าข้างได้ถูก" },
        required = { [254432] = { "20:881959009:1390583704", "โทเทมเซนทอร์แกะสลัก" } },
        steps = { { "20:881959009:1390583704", "โทเทมเซนทอร์แกะสลัก" } },
    },
    [93226] = { -- Buying Friendship: Magram
        title = { "25:586504531:1702826072", "ซื้อมิตรภาพ: Magram" },
        objective = { "211:666287137:1791185050", "นำ Totem Tote ไปให้ Magram Quartermaster ที่ Magram Village ใน Desolace เพื่อเพิ่มชื่อเสียงกับเผ่านั้นอย่างมาก คุณต้องมีชื่อเสียงกับ Magram Clan Centaur อย่างน้อยระดับ Neutral" },
        description = { "501:192645293:1472153907", "ถ้าเป็นข้า จะเลือกเข้าข้าง Magram ไม่ต้องสงสัยว่าตอนนี้พวกเขามีอำนาจเหนือกว่า แม้เคยลำบากมาก่อน ได้ยินรายงานว่าเป็นศัตรูกับ Gelkis อย่างโหดเหี้ยม\n\nข้าเห็นใจทั้งสองเผ่าที่รบกัน โดยเฉพาะ Gelkis แต่นี่เป็นสงครามของพวกเขา ไม่ใช่เรา ควรเข้ากับฝ่ายที่เสี่ยงต่อเป้าหมายเราน้อยที่สุด ข้าเชื่อว่าคือ Magram\n\nนำสิ่งนี้ไปให้ผู้ดูแลเสบียงที่ Magram Village ทางตะวันออกเฉียงใต้" },
        progress = { "48:1737800561:287717478", "คนนอกมีธุระอะไรกับ Gorhak" },
        completion = { "436:1855100960:117792491", "<Gorhak เบิกตากว้างเมื่อเจ้ายื่นถุงโทเท็มแกะสลักให้ แต่พอเงยหน้ามองเจ้าอีกครั้ง เขาก็ขมวดคิ้ว>\n\nข้าไม่ใช่คนโง่ คนนอก เจ้าไม่ได้ให้ของพวกนี้โดยไม่มีเหตุผล เจ้าต้องการอะไรสักอย่างจากข้าหรือเผ่าของเรา ข้าไม่รู้ว่าคืออะไร\n\n<นายพลาธิการคว้าถุงไปในพริบตา>\n\nแต่วันนี้ข้าไม่สนว่าเจ้ามีเจตนาแอบแฝงอะไร\n\nยินดีต้อนรับสู่ Magram Village คนนอก" },
        required = { [257685] = { "10:722003110:420686335", "กระเป๋าใส่โทเทม" } },
        steps = { { "10:722003110:420686335", "กระเป๋าใส่โทเทม" } },
        objectiveLabels = {
            reputation = { ["Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง", ["Hated / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / เป็นกลาง", ["Hostile / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / เป็นกลาง", ["Unfriendly / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / เป็นกลาง", ["Neutral / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / เป็นกลาง", ["Friendly / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / เป็นกลาง", ["Honored / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / เป็นกลาง", ["Revered / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / เป็นกลาง", ["Exalted / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นกลาง" },
        },
    },
    [93227] = { -- Buying Friendship: Gelkis
        title = { "25:2077837352:1195757535", "ซื้อมิตรภาพ: Gelkis" },
        objective = { "211:1266697015:1677770913", "นำ Totem Tote ไปให้ Gelkis Quartermaster ที่ Gelkis Village ใน Desolace เพื่อเพิ่มชื่อเสียงกับเผ่านั้นอย่างมาก คุณต้องมีชื่อเสียงกับ Gelkis Clan Centaur อย่างน้อยระดับ Neutral" },
        description = { "484:1154886704:589395878", "มองครั้งแรก ข้าพนันว่า Gelkis กำลังลำบาก มีจำนวนน้อยกว่า Magram มาก และผู้สอดแนมไม่ค่อยรายงานว่าพวกเขาเดินย่ำไปทั่ว\n\nถึงอย่างนั้น พวกเขาก็เป็นหนึ่งในเผ่าหลักของ Desolace และรอดมาจนวันนี้ ต้องมีอะไรที่ทำได้ถูกต้อง\n\nหากอยากเป็นมิตรกับ Gelkis นำถุงโทเท็มนี้ไป Gelkis Village ไกลทางตะวันตกเฉียงใต้ แม้ดูล้าหลัง พวกเขาคงมีคนดูแลทรัพย์สินสักประเภท" },
        completion = { "426:1371157901:1880029011", "<Molkar แอบชะโงกดูในถุง มุมปากยกเป็นรอยยิ้มเจ้าเล่ห์ ก่อนชะงักครู่หนึ่งเมื่อเห็นโทเท็มที่ดูออกว่าเป็นของปลอม เขาแสร้งทำเป็นมองไม่เห็น>\n\nข้าไม่รู้ว่าอะไรดลใจให้คนนอกเอาของขวัญเช่นนี้มาให้เผ่าของเรา แต่มันช่วยชนของเราได้มาก ช่วงนี้พวก Magram โหดเหี้ยมผิดปกติ\n\nต่อไปเจ้าเดินในหมู่บ้านเราได้สบายใจ ข้าจะบอก Uthek ให้ไปคุยกับข่าน" },
        progress = { "68:1445797240:1457448022", "คนนอกเข้ามาลึกถึงกลางหมู่บ้านเลยหรือ? หวังว่าเจ้าจะมาทำธุระนะ" },
        required = { [257685] = { "10:722003110:420686335", "กระเป๋าใส่โทเทม" } },
        steps = { { "10:722003110:420686335", "กระเป๋าใส่โทเทม" } },
        objectiveLabels = {
            reputation = { ["Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง", ["Hated / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / เป็นกลาง", ["Hostile / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / เป็นกลาง", ["Unfriendly / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / เป็นกลาง", ["Neutral / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / เป็นกลาง", ["Friendly / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / เป็นกลาง", ["Honored / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / เป็นกลาง", ["Revered / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / เป็นกลาง", ["Exalted / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นกลาง" },
        },
    },
    [93465] = { -- Notes on Draenethyst
        title = { "20:1492365899:1337588839", "บันทึกเรื่อง Draenethyst" },
        objective = { "75:1293154539:323274855", "นำบันทึก Draenethyst ของ Gimashi กลับไปให้ Azore Aldamort" },
        description = { "504:1593865859:1736378029", "คงถูกต้องกว่าถ้าบอกว่าข้ารู้จักคนที่พอรู้เรื่อง Draenethyst\n\nพวกวอร์ล็อก Burning Blade กำลังศึกษามัน เป็นสสารจากอีกฟาก Dark Portal จึงไม่น่าแปลกที่ผู้เกี่ยวข้องกับศาสตร์มืดอยากใช้เพื่อจุดหมายตน เราปล่อยไม่ได้แน่นอน\n\nวอร์ล็อกที่เจ้าต้องตามหาชื่อ Gimashi อยู่ยอดหอคอยในหุบแคบทางตะวันออกเฉียงใต้ บันทึกนางจะมีคำตอบที่ต้องการ" },
        progress = { "39:1763514505:3796688 N 98:896764106:576983680", "ผลประโยชน์ของเราตรงกันพอดี {name} เมื่อเจ้าสังหาร Gimashi เจ้าก็จะได้คำตอบ ส่วนข้าก็จะมีคนชั่วให้กังวลน้อยลงหนึ่งคน" },
        completion = { "136:1324843258:827802769", "ทำได้ดีมาก! ทีนี้ขอเวลาข้าสักครู่ จะได้เรียบเรียงบันทึกพวกนี้ให้เจ้าและชาวบึงตัวน้อยน่ารักพวกนั้นอ่านเข้าใจ" },
        required = { [258774] = { "18:1311290623:1183612062", "ผลการค้นคว้าของ Gimashi" } },
        steps = { { "18:1311290623:1183612062", "ผลการค้นคว้าของ Gimashi" } },
    },
    [93678] = { -- Abridged Notes on Draenethyst
        title = { "29:562007586:1265419905", "บันทึกย่อเรื่อง Draenethyst" },
        objective = { "84:1080892529:41981081", "นำบันทึกที่ Azore คัดลอกกลับไปให้ Magtoor ที่ Harborage ใน Swamp of Sorrows" },
        description = { "502:1535024053:317178228", "ข้าคัดลอกบันทึก Draenethyst ของ Gimashi แล้ว ดูเหมือนเศษผลึกมีพลังระดับหนึ่ง แต่ทรงกลมบริสุทธิ์ของสสารนี้ทรงพลังกว่ามาก นั่นคงเป็นสิ่งที่ Burning Blade ต้องการ\n\nบันทึก Gimashi หลายส่วนพาดพิงประตูมิติกับพิธีอัญเชิญปีศาจ จะเปิดไปไหนหรืออัญเชิญปีศาจตนใด ข้าบอกแน่ไม่ได้\n\nแม้คำตอบยังไม่เด็ดขาด โปรดนำบันทึกนี้กลับหนองบึงด้วย หวังว่าเจ้าจะเข้าใจหากข้าไม่ไปด้วย" },
        completion = { "503:978233534:746850095", "<Magtoor เริ่มอ่านบันทึกอย่างละเอียด>\nได้ความรู้มากทีเดียว แต่ทรงกลม Draenethyst ที่บันทึกพูดถึงนี่ ข้าไม่เคยเห็นกับตาเลย ในที่อย่างนี้คงหาไม่ได้อยู่แล้วด้วย ขนาดเศษผลึกยังช่วยเราได้มาก ข้าล่ะอยากรู้ว่าเราจะทำอะไรได้บ้างถ้ามีวัตถุที่ทรงพลังกว่านี้มาก บางทีถ้าเจอทรงกลมนั่น เราอาจพบทางรอดด้วย\nยังมีเรื่องให้ศึกษาและขบคิดอีกมาก อาจต้องใช้เวลาสักพักกว่าเราจะได้คุยกันอีก ระหว่างนี้ข้าขอขอบใจเจ้าจากใจจริง" },
        progress = { "56:1076036115:1504202791", "เจ้าได้คุยกับนักเวทแล้วหรือ? เขาให้คำตอบว่าอย่างไรบ้าง?" },
        required = { [260518] = { "21:18936640:843686164", "สำเนาที่ Azore คัดไว้" } },
        steps = { { "21:18936640:843686164", "สำเนาที่ Azore คัดไว้" } },
    },
    [97284] = { -- Vahlarriel's Vengeance
        title = { "22:176595814:147708932", "การแก้แค้นของ Vahlarriel" },
        objective = { "120:2124801877:1892934333", "ฆ่าออร์ค Burning Blade ที่ Thunder Axe Fortress ใน Desolace แล้วกลับไปหา Vahlarriel Demonslayer ที่ Nijel's Point" },
        description = { "465:2005302215:258362123", "หาก Malem ยังมีชีวิต ข้าว่าออร์ค Burning Blade คงคาดว่าจะมีคนตามหานางเร็ว ๆ นี้ มันต้องพร้อมสู้แน่นอน\n\nข้าอยากให้เจ้าซ่อนตัวและหลีกทางมัน แต่ความจริงที่เป็นไปได้กว่าคือ พวกมันจะหาจังหวะประดาบกับเจ้าทุกโอกาส สมชื่อลัทธิ Burning Blade\n\nงั้นเราตั้งใจนับผลงานตั้งแต่ต้นเลยดีกว่า ฆ่าให้มากที่สุด แล้วข้าจะตอบแทนให้คุ้มเวลา" },
        completion = { "237:962584918:1702451584", "ทำได้ดี หลังจากที่เจ้าจัดการพวกโง่ที่ Thunder Axe เสียขนาดนั้น พวกมันคงต้องคิดให้ดีก่อนปล้นขบวนคาราวานที่ผ่านทางอีก\n\nถ้าโชคดี พวกมันคงหลบอยู่หลังประตูป้อมจนตายกันไปเอง" },
        objectiveLabels = {
            monster = { ["Burning Blade Augur slain"] = "ปราบ ผู้ทำนาย Burning Blade", ["Burning Blade Reaver slain"] = "ปราบ นักปล้น Burning Blade", ["Burning Blade Adept slain"] = "ปราบ ผู้ชำนาญเวท Burning Blade", ["Burning Blade Felsworn slain"] = "ปราบ ผู้สาบานตนต่อเฟล Burning Blade" },
        },
    },
    [1366] = { -- Centaur Bounty
        title = { "14:1105463176:1262241555", "ค่าหัวเซนทอร์" },
        objective = { "52:1857032190:2077723894", "นำ Centaur Ears 15 ชิ้น ไปให้ Felgur Twocuts ใน Desolace" },
        description = { "285:2098644212:1309018509 N 1:46:46", "เมื่อทำให้เผ่าเซนทอร์หวาดกลัวแล้ว ก็ถึงเวลาทำให้พวกมันเสียเลือด ระหว่างเดินทางใน Desolace จงล่าเซนทอร์ ข้าไม่สนว่าเผ่าไหน แค่เก็บหูมา หูมากมาย\n\nการลดจำนวนจะบั่นทอนขวัญ และดับความคิดขยายอาณาเขตของพวกมัน\n\nขอให้ล่าได้ดี {name}" },
        progress = { "32:1490821430:258560913 N 8:449612638:1875716323", "เก็บหูไปถึงไหนแล้ว {name}? ได้มากหรือยัง?" },
        completion = { "187:1117726762:2045365582", "ถึงตอนนี้เซนทอร์ต้องรู้จักชื่อเจ้าแล้ว ข้ามั่นใจว่าพวกมันรู้จัก เคารพ และหวาดกลัวชื่อนั้น และเมื่อรู้จักเจ้า ก็ย่อมรู้ว่าเจ้ารบอยู่ใต้ธงใด\n\nธงแห่ง Horde" },
        required = { [6067] = { "11:349497811:132324303", "หูเซนทอร์" } },
        steps = { { "11:349497811:132324303", "หูเซนทอร์" } },
    },
    [1367] = { -- Magram Alliance
        title = { "15:1863258376:773707179", "ผูกมิตรกับ Magram" },
        objective = { "66:2024496448:676264577", "เพิ่มชื่อเสียงกับ Magram ถึงระดับ Friendly แล้วคุยกับ Warug" },
        description = { "400:1919874012:1891914519", "หากจะเอาชนะเซนทอร์ เราต้องใช้ความเกลียดชังของพวกมันย้อนทำร้ายพวกมันเอง เราจะผูกมิตรกับเผ่าหนึ่ง และอาศัยเผ่านั้นเรียนรู้วิธีเอาชนะทุกเผ่า\n\nหากเจ้าเลือกเป็นพันธมิตรกับ Magram จงฆ่าศัตรูของพวกเขาคือ Gelkis เพื่อให้ Magram ยอมรับ เมื่อได้รับการยอมรับเพียงพอแล้ว ไปพบ Warug ตัวแทนของ Magram ที่ชายขอบ Magram Village ทางตะวันออกเฉียงใต้ของ Desolace" },
        progress = { "153:29351716:323259059", "ไปให้พ้น! Magram ไม่คุยกับผู้อ่อนแอ เราฆ่ามัน!\n\nหากอยากคุยกับข้า จงแสดงความแข็งแกร่ง กลับมาหลังจากฆ่า Gelkis ได้มากแล้ว" },
        completion = { "41:483412762:1291311985 N 128:1413630032:539084341", "Gelkis ร้องไห้เมื่อได้ยินชื่อเจ้า {name} พวกมันกลัวและเกลียดเจ้า เกลียดเจ้าเหมือนที่เกลียด Magram!\n\nบางทีเจ้าอาจแข็งแกร่งเหมือน Magram เราจะได้เห็นกัน..." },
        objectiveLabels = {
            reputation = { ["Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
        },
    },
    [1368] = { -- Gelkis Alliance
        title = { "15:1161452455:1563144987", "ผูกมิตรกับ Gelkis" },
        objective = { "75:2111247167:109617727", "เพิ่มชื่อเสียงกับ Gelkis ถึงระดับ Friendly แล้วคุยกับ Uthek the Wise" },
        description = { "388:1099922470:656885059", "หากจะเอาชนะเซนทอร์ เราต้องใช้ความเกลียดชังของพวกมันย้อนทำร้ายพวกมันเอง เราจะผูกมิตรกับเผ่าหนึ่ง และอาศัยเผ่านั้นเรียนรู้วิธีเอาชนะทุกเผ่า\n\nหากเลือกเป็นพันธมิตรกับ Gelkis จงฆ่าคู่แค้นของพวกเขาคือ Magram เมื่อได้รับการยอมรับจาก Gelkis แล้ว ไปพบชามาน Uthek the Wise ที่ชายขอบ Gelkis Village ทางตะวันตกเฉียงใต้ของ Desolace" },
        progress = { "174:2089719418:1664370476", "เท้าทั้งสองของเจ้าเหยียบผืนดิน Gelkis เจ้าไม่เป็นที่ต้อนรับ!\n\nพิสูจน์ว่าอยากเป็นมิตรกับ Gelkis ฆ่าเซนทอร์ Magram กลับมาเมื่อผืนดินเปียกชุ่มด้วยเลือด Magram" },
        completion = { "153:867873067:265293251", "ผืนดินบอกข้าว่าเจ้าฆ่า Magram ไปมาก ดีแล้ว\n\nหากเจ้าเป็นมิตรของ Gelkis จงฟัง ข้ามีงานให้ทำอีก" },
        objectiveLabels = {
            reputation = { ["Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร", ["Hated / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / เป็นมิตร", ["Hostile / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / เป็นมิตร", ["Unfriendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / เป็นมิตร", ["Neutral / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / เป็นมิตร", ["Friendly / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / เป็นมิตร", ["Honored / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / เป็นมิตร", ["Revered / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / เป็นมิตร", ["Exalted / Friendly Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นมิตร" },
        },
    },
    [92812] = { -- Economic Warfare
        title = { "16:853937619:1206083235", "สงครามเศรษฐกิจ" },
        description = { "486:1229472988:1763205076", "นานมาแล้ว เซนทอร์ทุกเผ่าใน Desolace ตกลงกันว่าจะใช้เรื่องเล่าเป็นสิ่งแลกเปลี่ยน โดยแกะสลักโทเท็มให้เป็นตัวแทนความสำเร็จอันยิ่งใหญ่ของคนผู้หนึ่งหรือของทั้งเผ่า แม้การสู้รบจะไม่มีวันจบ ทุกเผ่าก็ยังรักษาธรรมเนียมนี้ไว้ แม้จะมีโอกาสค้าขายกันนาน ๆ ครั้งก็ตาม\n\nหากเจ้าเก็บโทเท็มมาได้ เช่น จากเซนทอร์เผ่าอื่นที่ล้มตาย ก็นำมาให้ข้า เผ่า Gelkis จะได้มีอำนาจต่อรองในการแลกเปลี่ยนเพิ่มขึ้น แล้วข้าจะเรียนข่านถึงความช่วยเหลือของเจ้า" },
        completion = { "152:1136695445:889183618", "ข้าจะเอาของพวกนี้ไปรวมกับที่เราสะสมไว้ พลังของเราเพิ่มขึ้นเพราะสิ่งที่เจ้ามอบให้ แต่ยังอีกไกลกว่าจะเอาชนะเผ่า Magram ได้" },
        progress = { "486:1229472988:1763205076", "นานมาแล้ว เซนทอร์ทุกเผ่าใน Desolace ตกลงกันว่าจะใช้เรื่องเล่าเป็นสิ่งแลกเปลี่ยน โดยแกะสลักโทเท็มให้เป็นตัวแทนความสำเร็จอันยิ่งใหญ่ของคนผู้หนึ่งหรือของทั้งเผ่า แม้การสู้รบจะไม่มีวันจบ ทุกเผ่าก็ยังรักษาธรรมเนียมนี้ไว้ แม้จะมีโอกาสค้าขายกันนาน ๆ ครั้งก็ตาม\n\nหากเจ้าเก็บโทเท็มมาได้ เช่น จากเซนทอร์เผ่าอื่นที่ล้มตาย ก็นำมาให้ข้า เผ่า Gelkis จะได้มีอำนาจต่อรองในการแลกเปลี่ยนเพิ่มขึ้น แล้วข้าจะเรียนข่านถึงความช่วยเหลือของเจ้า" },
    },
    [93225] = { -- Carved Centaur Totems
        title = { "21:1177682493:1777840503", "โทเท็มเซนทอร์แกะสลัก" },
        objective = { "140:787842073:1229303676", "ฆ่าเซนทอร์เผ่าใดก็ได้ทั่ว Desolace เพื่อเก็บ Carved Centaur Totems 5 ชิ้น แล้วนำไปให้ Gurda Wildmane ที่ Ghost Walker Post", amount = { "8:1617296333:1647798940 W1 131:1590910122:1411612065", "ฆ่าเซนทอร์เผ่าใดก็ได้ทั่ว Desolace เพื่อเก็บ Carved Centaur Totems {world1} ชิ้น แล้วนำไปให้ Gurda Wildmane ที่ Ghost Walker Post" } },
        description = { "490:1299947993:375693493", "ข้าสังเกตว่าเซนทอร์ต่างเผ่าบางครั้งรวมตัวห่างจากถิ่นฐานเพื่อค้าขาย เห็นมาหลายคืน และดูจะเกิดกับทุกเผ่า ที่สำคัญ ข้าเห็นสิ่งที่พวกมันใช้แทนเงิน นั่นคือโทเท็มแกะสลัก\n\nข้าเชื่อว่าเราทำให้ Gelkis หรือ Magram หันมาสนับสนุนได้ หากส่งโทเท็มห่อใหญ่ให้ถึงมือ ข้าเริ่มแกะเองบ้างแล้ว แต่หากไม่มีของจริงปนสักหน่อย คงหลอกพวกมันไม่ง่าย" },
        completion = { "484:1358892156:514478961", "ของพวกนี้งามจริง ข้าประเมินความคิดสร้างสรรค์ของเซนทอร์ต่ำไป ไม่เคยนึกเลยว่าชนเผ่าที่เต็มไปด้วยความโหดเหี้ยมและทารุณ จะเห็นคุณค่าของเรื่องราวที่เล่าผ่านงานแกะสลัก\n\nว่าไปแล้ว การชื่นชมก็ใช้แรงน้อยกว่าการแกะสลักเยอะ ขอพูดใหม่ ข้าไม่เคยนึกว่าเซนทอร์จะอดทนแกะเรื่องราวลงบนไม้ได้มากขนาดนี้ พวกเขาเอาไม้มาจากไหนกัน\n\nเอาเถอะ มาคุยกับข้าเมื่อเจ้าพร้อมเอาของไปส่ง" },
        progress = { "34:2104145445:631943986", "เจ้าเอาโทเทมกลับมาด้วยหรือเปล่า?" },
        required = { [254432] = { "20:881959009:1390583704", "โทเทมเซนทอร์แกะสลัก" } },
        steps = { { "20:881959009:1390583704", "โทเทมเซนทอร์แกะสลัก" } },
    },
    [94872] = { -- Buying Friendship: Magram
        title = { "25:586504531:1702826072", "ซื้อมิตรภาพ: Magram" },
        objective = { "211:666287137:1791185050", "นำ Totem Tote ไปให้ Magram Quartermaster ที่ Magram Village ใน Desolace เพื่อเพิ่มชื่อเสียงกับเผ่านั้นอย่างมาก คุณต้องมีชื่อเสียงกับ Magram Clan Centaur อย่างน้อยระดับ Neutral" },
        description = { "483:945538077:39004129", "Magram ที่ดุร้ายกำลังชนะสงครามแย่งดินแดนอย่างไม่ต้องสงสัย แม้เราควรขอบคุณที่การปะทะยังไม่เกิดบ่อยทั่วทะเลทราย แต่ทุกวันหมู่บ้านทางตะวันออกของพวกมันก็โตขึ้น ทหารก็กล้ามากขึ้น\n\nข้ากังวลอย่างยิ่งหากปล่อยเผ่า Magram โดยไร้ผู้คานอำนาจ แต่ก็ปฏิเสธไม่ได้ว่าพวกมันมีศักยภาพเป็นพันธมิตร\n\nหากอยากได้รับความไว้ใจ นำถุงโทเท็มนี้ไปมอบให้พลาธิการของพวกมัน แต่จงระวัง" },
        completion = { "436:1855100960:117792491", "<Gorhak เบิกตากว้างเมื่อเจ้ายื่นถุงโทเท็มแกะสลักให้ แต่พอเงยหน้ามองเจ้าอีกครั้ง เขาก็ขมวดคิ้ว>\n\nข้าไม่ใช่คนโง่ คนนอก เจ้าไม่ได้ให้ของพวกนี้โดยไม่มีเหตุผล เจ้าต้องการอะไรสักอย่างจากข้าหรือเผ่าของเรา ข้าไม่รู้ว่าคืออะไร\n\n<นายพลาธิการคว้าถุงไปในพริบตา>\n\nแต่วันนี้ข้าไม่สนว่าเจ้ามีเจตนาแอบแฝงอะไร\n\nยินดีต้อนรับสู่ Magram Village คนนอก" },
        progress = { "48:1737800561:287717478", "คนนอกมีธุระอะไรกับ Gorhak?" },
        required = { [257685] = { "10:722003110:420686335", "กระเป๋าใส่โทเทม" } },
        steps = { { "10:722003110:420686335", "กระเป๋าใส่โทเทม" } },
        objectiveLabels = {
            reputation = { ["Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง", ["Hated / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / เป็นกลาง", ["Hostile / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / เป็นกลาง", ["Unfriendly / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / เป็นกลาง", ["Neutral / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / เป็นกลาง", ["Friendly / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / เป็นกลาง", ["Honored / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / เป็นกลาง", ["Revered / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / เป็นกลาง", ["Exalted / Neutral Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นกลาง" },
        },
    },
    [94873] = { -- Buying Friendship: Gelkis
        title = { "25:2077837352:1195757535", "ซื้อมิตรภาพ: Gelkis" },
        objective = { "211:1266697015:1677770913", "นำ Totem Tote ไปให้ Gelkis Quartermaster ที่ Gelkis Village ใน Desolace เพื่อเพิ่มชื่อเสียงกับเผ่านั้นอย่างมาก คุณต้องมีชื่อเสียงกับ Gelkis Clan Centaur อย่างน้อยระดับ Neutral" },
        description = { "488:831240490:1272497615", "เผ่าเซนทอร์ใหญ่ทั้งสองน่าจะเป็นพันธมิตรที่ดีได้ แต่ข้าต้องเตือนเรื่อง Gelkis สักหน่อย\n\nข้ามีข่าวที่เชื่อถือได้ว่าในศึกระหว่าง Magram กับ Gelkis ฝ่ายหลังเป็นฝ่ายเสียเปรียบอย่างหนัก เรื่องนี้อาจเป็นประโยชน์ต่อเรา ความสิ้นหวังอาจทำให้เผ่าที่โดดเดี่ยวยอมรับความช่วยเหลือภายนอก\n\nข้าเตรียมถุงโทเท็มให้เจ้านำไปหาพลาธิการของพวกเขา หากมีอยู่ ที่ Gelkis Village บางทีอาจเข้าทางเรา" },
        completion = { "422:1750083015:435321269", "<Molkar แอบชะโงกดูในถุง มุมปากยกเป็นรอยยิ้มเจ้าเล่ห์ ก่อนชะงักครู่หนึ่งเมื่อเห็นโทเท็มที่ดูออกว่าเป็นของปลอม เขาแสร้งทำเป็นมองไม่เห็น>\n\nข้าไม่รู้ว่าอะไรดลใจให้คนนอกเอาของขวัญเช่นนี้มาให้เผ่าของเรา แต่มันช่วยชนของเราได้มาก ช่วงนี้พวก Magram โหดเหี้ยมผิดปกติ\n\nต่อไปเจ้าเดินในหมู่บ้านเราได้สบายใจ ข้าจะบอก Uthek ให้ไปคุยกับข่าน" },
        progress = { "68:1445797240:1457448022", "คนนอกเข้ามาลึกถึงกลางหมู่บ้านเลยหรือ? หวังว่าเจ้าจะมาทำธุระนะ" },
        required = { [257685] = { "10:722003110:420686335", "กระเป๋าใส่โทเทม" } },
        steps = { { "10:722003110:420686335", "กระเป๋าใส่โทเทม" } },
        objectiveLabels = {
            reputation = { ["Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง", ["Hated / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / เป็นกลาง", ["Hostile / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / เป็นกลาง", ["Unfriendly / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / เป็นกลาง", ["Neutral / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / เป็นกลาง", ["Friendly / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / เป็นกลาง", ["Honored / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / เป็นกลาง", ["Revered / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / เป็นกลาง", ["Exalted / Neutral Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / เป็นกลาง" },
        },
    },
    [96222] = { -- Khan Hratha
        title = { "11:347239827:1052141052", "ข่าน Hratha" },
        objective = { "59:375622229:579353157", "นำ Maraudine Key Fragment ไปให้ Umarak ใน Desolace" },
        description = { "495:136715182:1795072481", "ระหว่างที่สงครามโหมทั่วภูมิภาค เซนทอร์ Maraudine กลับอยู่ใน Valley of Spears โดยไม่มีใครท้าทาย ข้าห่วงว่าพวกมันจะยิ่งไม่เกรงใจและก่อความวุ่นวาย หากเผ่าอื่นยังเมินการมีอยู่ของมัน\n\nKhan Hratha ครอบครอง Maraudine Key Fragment ข้าอยากได้ไว้ต่อรอง หา War Horn Mouthpiece จากเซนทอร์ที่นั่น แล้วใช้ท้าทายเขาบนยอดเขาสูงที่สุด\n\nนำกุญแจมา แล้วข้าจะมีข้อเสนอให้เจ้า" },
        completion = { "451:86773310:1131981064", "เมื่อ Khan Hratha ถูกสังหารและชิ้นส่วนกุญแจถูกนำออกจาก Valley of Spears เจ้าก็บั่นทอนกำลังเผ่านั้นลงได้มาก โดยไม่ดึงความสนใจไปจากสงครามที่เร่งด่วนกว่า\nข้าว่าพวก Maraudine คงออกตามหาสิ่งนี้ในไม่ช้า แต่การตายของข่านน่าจะถ่วงเวลาที่พวกมันจะเริ่มลงมือได้สักระยะ\nข้ามีข้าวของที่เก็บมาให้เจ้าเลือก และมีโทเท็มแกะสลักไว้ช่วยเจ้าในการเจรจา" },
        progress = { "50:955336214:1462199077", "Khan Hratha ตายแล้วหรือยัง? เจ้าได้ชิ้นส่วนกุญแจมาหรือเปล่า?" },
        required = { [6077] = { "22:619606957:328144269", "เศษกุญแจ Maraudine" } },
        steps = { { "22:619606957:328144269", "เศษกุญแจ Maraudine" } },
    },
    [2766] = { -- Find OOX-22/FE!
        title = { "15:1351721054:1439914905", "ตามหา OOX-22/FE!" },
        objective = { "85:310242855:8021792", "นำสัญญาณขอความช่วยเหลือไปให้หุ่นยนต์นำทางของ Oglethorpe ในถ้ำใกล้ Feral Scar Vale" },
        description = { "486:361267913:155486550", "คุณพบอุปกรณ์โลหะประหลาดรูปไข่ เมื่อหมุนปุ่มหนึ่ง มันก็ทำงานและเปิดออกเป็นกลไกหุ่นยนต์โนม! เสียงจากไข่หุ่นยนต์ดังขึ้นอย่างติดขัด\n\n\"ข้าชื่อ Oglethorpe Obnoticus หุ่นยนต์นำทางของข้าตก! ข้าจะให้รางวัลหากเจ้ากู้มันได้ โปรดนำสัญญาณนี้ไปให้หุ่นยนต์!\"\n\n\"ข้าคำนวณพิกัดให้แล้ว มันอยู่ในถ้ำใกล้ Feral Scar Vale!\"" },
        progress = { "366:1910194723:1680827046", "ดูเหมือนคุณจะพบซาก... ไก่หุ่นยนต์? เสียงจากไข่ดังขึ้นอีกครั้ง\n\n\"ใช่ ทำได้ดี! นี่คือหุ่นยนต์นำทางของข้าจริง แต่เซนเซอร์บอกว่ามันต้องได้รับพลังงานกระตุ้นก่อนจะบินกลับ Booty Bay ไปซ่อมได้ วางสัญญาณลงในตัวหุ่นได้เลย มันจะจัดการที่เหลือเอง!\"" },
        completion = { "428:2083164713:192799809", "คุณวางไข่... สัญญาณขอความช่วยเหลือ... ลงในไก่... หุ่นยนต์นำทาง\n\nเสียงหึ่งและเสียงกลไกดังจากภายใน ขณะหุ่นพยายามลุกขึ้น เมื่อมันทำงาน เสียง Oglethorpe ก็ดังขึ้นอีกครั้ง คราวนี้มาจากตัวหุ่น\n\n\"อย่างน้อย OOX-22/FE ก็ทำงานแล้ว แต่ต้องซ่อมใหญ่! มันหนักเกินเจ้าจะแบก... แต่ข้าว่ามีความคิดหนึ่ง เจ้าพร้อมดูแลมันต่ออีกหน่อยไหม?\"" },
        required = { [8705] = { "25:1726640002:1049165942", "เครื่องส่งสัญญาณขอความช่วยเหลือ OOX-22/FE" } },
        steps = { { "25:1726640002:1049165942", "เครื่องส่งสัญญาณขอความช่วยเหลือ OOX-22/FE" } },
    },
    [2767] = { -- Rescue OOX-22/FE!
        title = { "17:1197808780:122465485", "ช่วย OOX-22/FE!" },
        objective = { "105:2133010840:561293968", "คุ้มกัน OOX-22/FE ไปยังท่าเรือริม Forgotten Coast แล้วรายงานต่อ Oglethorpe Obnoticus ที่ Booty Bay" },
        description = { "495:680173751:1140348256", "เสียงโนมดังติดขัดจากหุ่นยนต์อีกครั้ง\n\n\"ข้าต้องย้าย OOX-22/FE ไปที่โล่งปลอดภัย เพื่อเริ่มขั้นตอนบินขึ้นที่ใช้เวลานาน มันมีระบบพรางตัวในตัว แต่ข้าต้องใช้เวลาจัดการทางนี้ให้ระบบกลับมาทำงาน คุ้มกันจากที่นี่ไป... เอาเป็นท่าเรือริม Forgotten Coast! นั่นน่าจะเหมาะ และให้เวลาพอเปิดระบบ!\"\n\n\"คุ้มกันถึงท่าเรืออย่างปลอดภัย แล้วมาคุยกับข้าที่ Booty Bay! Oglethorpe Obnoticus จบการติดต่อ!\"" },
        progress = { "112:396700074:727874630", "ใช่ ข้าคือ Oglethorpe Obnoticus ยอดนักประดิษฐ์ ยินดีรับใช้! มีอะไรให้ช่วยหรือ?" },
        completion = { "374:485690683:46626822 N 35:1508532347:1119755817", "โอ้ เจ้าคือผู้ช่วยชีวิต OOX-22/FE! ข้าไม่รู้จะเริ่มขอบคุณอย่างไร! หุ่นยนต์นำทางรุ่นนี้ยังต้องพัฒนาอีก แต่การกู้คืนช่วยข้าประหยัดเวลาสร้างใหม่ไปมหาศาล และลดต้นทุนผลิตหลายเหรียญทอง!\n\nโปรดเลือกสิ่งของเหล่านี้ชิ้นหนึ่ง ขอบคุณอีกครั้งสำหรับความช่วยเหลืออันเอื้อเฟื้อ {name} ข้ากับหุ่นยนต์เป็นหนี้บุญคุณเจ้า!" },
    },
    [2821] = { -- The Mark of Quality
        title = { "19:367753818:1609792767", "เครื่องหมายแห่งคุณภาพ" },
        objective = { "71:1641877232:1247428607", "นำ Thick Yeti Hide 10 ผืนไปให้ Pratt McGrubben ที่ Feathermoon Stronghold" },
        description = { "493:1851833952:405020028", "หลักการทำเครื่องหนังของข้าคือต้องมีคุณภาพดีที่สุดเท่าที่ทำได้ ไม่มีการยอมลดคุณภาพ ใครบอกว่าคุณภาพไม่สำคัญ ก็คงกำลังหลอกขายที่ดินติดทะเลใน Dun Morogh ให้เจ้า!\n\nในการหาวัตถุดิบคุณภาพสูงครั้งล่าสุด ข้าพบหนังเยติหนา เยติเป็นสัตว์พื้นถิ่น Feralas พบมากใน Feral Scar Vale ข้าต้องการหนัง และจะให้เจ้าเลือกเครื่องหนังของข้าชิ้นหนึ่งแลกกับหนังสิบผืน ถ้าคิดว่ายุติธรรม เราก็ค้าขายกันได้" },
        progress = { "288:1659682624:1945901826", "หนังเยติหนาสิบผืนแลกของที่ข้าประดิษฐ์ได้หนึ่งชิ้น เพราะข้าใส่ใจคุณภาพ จึงมั่นใจได้ว่าเจ้าจะได้ของดี!\n\nถ้าหาเยติไม่เจอ ข้ารู้ว่ามันอาจอยู่ที่ไหน ลองเข้าไปในแผ่นดินจาก Forgotten Coast แถว Feral Scar Vale" },
        completion = { "396:1765923685:1780655231", "เจ้าลองตรวจเนื้อหนังพวกนี้ไหม? หากผ่านกรรมวิธีที่ถูกต้อง มันอาจแข็งแรงกว่าเหล็ก มีคนรู้จักหนังเหล่านี้ไม่มาก และเมื่อรวมกับน้ำยาฟอกสารพัดที่ข้ารู้จัก ก็อาจทำให้ข้าสร้างของที่มีเครื่องหมายแห่งคุณภาพอย่างแท้จริง... แน่นอนว่าต้องขอบคุณเจ้า!\n\nเอาล่ะ โปรดเลือกรางวัลจากของที่ข้ามอบให้ได้!" },
        required = { [8973] = { "15:1952602579:2067607003", "หนังเยติหนา" } },
        steps = { { "15:1952602579:2067607003", "หนังเยติหนา" } },
    },
    [2844] = { -- The Giant Guardian
        title = { "18:1327389983:1146400997", "ผู้พิทักษ์ร่างยักษ์" },
        objective = { "31:955093278:1431343801", "ตามหาเด็กหญิงไนต์เอลฟ์ที่หลงทาง" },
        description = { "14:726531721:2027010973 N 362:1529375482:1547569784 N 98:355204947:833555524", "ข้ามันไม่ได้เรื่อง {name} ควรดูแล Shay เพื่อนตัวน้อย แต่ไม่รู้ว่านางหลุดไปได้อย่างไร ข้าไม่แน่ใจจริง ๆ ว่าเกิดอะไร ครั้งสุดท้ายที่เห็น เราเดินอยู่ในซากเมืองทางเหนือใกล้ ๆ\n\nทุกอย่างก็ดีอยู่ แต่พอข้าหันกลับ... นางก็หายไปแล้ว\n\nข้านึกไม่ออกว่าจะทำอย่างไร มีความคิดไหม {name}? ข้าเป็นห่วงมาก\n\nนี่ เจ้าไปตามหา Shay ได้ไหม? ขาของเจ้าเดินทางได้เร็วกว่าข้ามาก" },
        completion = { "97:540877283:374552637", "โอ้ ดีใจเหลือเกินที่เจ้าพบข้า! ยอมรับว่าข้าหลงทางนิดหน่อย... แต่ที่นี่สวยใช่ไหมล่ะ?" },
    },
    [2845] = { -- Wandering Shay
        title = { "14:1407149785:239555833", "Shay ผู้ชอบเที่ยวเตร่" },
        objective = { "79:1716730808:1549342290", "หยิบ Shay's Bell จากหีบ\n\nคุ้มกัน Shay Leafrunner ไปยังค่าย Rockbiter" },
        description = { "484:1176794773:724470047", "ช่วยพาข้ากลับไปหา Rockbiter เพื่อนได้ไหม? เขาควรคอยดูแลข้า... แต่ข้าก็ชอบเดินเตร่ออกมาบางครั้ง มีสิ่งให้ดูมากมายจนเผลอวอกแวก\n\nแต่มีสิ่งหนึ่งที่เรียกความสนใจข้าได้เสมอ\n\nในหีบนี้มีกระดิ่งที่ข้ารักมาก ข้าชอบเสียงมันเหลือเกิน ข้าสัญญาว่าหากเดินเตร่ออกไป เจ้าเพียงสั่นกระดิ่ง ข้าจะวิ่งกลับมา" },
        progress = { "74:188677669:808328235 N 1:46:46", "ข้าเริ่มเป็นห่วงเจ้าแล้ว! ขอบคุณมากที่พา Shay กลับบ้าน {name}" },
        completion = { "117:1078954553:1570985081 N 1:46:46", "อะไรนะ? บอกว่ากระดิ่งนี้ใช้เรียก Shay ตอนวิ่งหนีได้หรือ? วิเศษไปเลย!\n\nเจ้าช่วยข้ามามาก นี่ รับไปเถิด {name}" },
        required = { [9189] = { "11:1320936480:1792728346", "กระดิ่งของ Shay" } },
        steps = { { "11:1320936480:1792728346", "กระดิ่งของ Shay" } },
        objectiveLabels = {
            event = { ["Take Shay Leafrunner to Rockbiter's camp"] = "พา Shay Leafrunner ไปยังค่ายของ Rockbiter" },
        },
    },
    [2866] = { -- The Ruins of Solarsal
        title = { "21:1929163214:952231194", "ซากเมือง Solarsal" },
        objective = { "77:247399690:1101300081", "สำรวจ Ruins of Solarsal และสืบเรื่องนากาที่ปรากฏตัวที่นั่น" },
        description = { "493:1753946529:466481257 N 1:46:46", "ทางใต้ของเราคือ Ruins of Solarsal พื้นที่เก่าแก่กว่ายุคปัจจุบันมาก ครั้งแรกเราสำรวจแล้วไม่พบอะไรสำคัญ จึงปล่อยไว้อย่างสงบ\n\nไม่นานมานี้ นากา Hatecrest เข้ายึดครองซากเมืองจำนวนมากจนน่ากังวล ตอนแรกคิดว่าเป็นการเตรียมโจมตี แม้ยังเป็นไปได้ แต่เราเชื่อว่าอาจมีเรื่องอื่นเกิดขึ้นด้วย\n\nจงไปสำรวจซากเมือง มองหาสิ่งที่สะดุดตา ขอให้โชคดี {name}" },
        completion = { "493:400343680:1846829514", "เมื่อตรวจศาลา คุณพบสิ่งน่าสนใจที่ต่างจากซากเมืองรอบข้าง\n\nอย่างแรก ศาลาสร้างทีหลังสิ่งอื่นในซากเมืองอย่างชัดเจน อย่างที่สอง ด้านข้างมีชุดอักขระสลักเป็นลวดลายซ้ำ ๆ แต่ไม่ทราบที่มาหรือความหมาย อย่างที่สาม หินของศาลาอุ่นเมื่อสัมผัส\n\nนี่นับว่าเป็นสิ่งที่ \"สะดุดตา\" ระหว่างค้นซากเมืองอย่างแน่นอน!" },
    },
    [2867] = { -- Return to Feathermoon Stronghold
        title = { "32:864920912:905735246", "กลับ Feathermoon Stronghold" },
        objective = { "86:1225035172:1473590321", "กลับไปหา Shandris Feathermoon ที่ Feathermoon Stronghold และรายงานสิ่งที่พบ" },
        description = { "207:1805774366:1241408380", "เมื่อพบศาลาประหลาดใจกลาง Ruins of Solarsal ก็ถึงเวลากลับ Feathermoon Stronghold ไปรายงานนายพล Shandris Feathermoon ถึงสิ่งที่ค้นพบ" },
        completion = { "14:1649650394:897424258 N 436:485146629:1766677944", "ยินดีต้อนรับกลับ {name} รายงานเรื่องศาลานี้ช่าง... น่ากังวล ดูเหมือนแม้นากาจะไม่ได้วางแผนโจมตี การที่พวกมันยังอยู่ก็เป็นลางร้ายต่อการรุกเข้าสู่ Feralas อย่างไรก็ตาม นี่คือค่าตอบแทนการสำรวจ\n\nดูเหมือน Feathermoon Stronghold ต้องการความช่วยเหลือเร่งด่วนเรื่องนากา Hatecrest ข้าอยากมอบงานให้หากเจ้ายินดี ยังมีสิ่งต้องทำมากมาย" },
    },
    [2869] = { -- Against the Hatecrest
        title = { "21:1793767818:797422445", "ต่อกร Hatecrest" },
        objective = { "81:533395592:12518381", "นำ Hatecrest Naga Scale 10 ชิ้นไปให้ Latronicus Moonspear ที่ Feathermoon Stronghold" },
        description = { "503:1339485676:463492473", "ตอนนี้ทางที่ดีที่สุดคือถือว่า ไม่ว่านากากำลังทำอะไร สุดท้ายมันจะพยายามยึดเกาะเป็นของตน เราต้องลงมืออย่างจริงจังเพื่อตอบโต้ก่อนสายไป\n\nนำเกล็ด Hatecrest สภาพดีสิบชิ้นมาให้ข้า เจ้าน่าจะรู้ว่าหาจากไหน เจ้าจะได้ประสบการณ์ต่อสู้นากาครั้งแรก และกำลังนากาบน Sardor Isle จะอ่อนลง ทั้งสองอย่างเป็นประโยชน์ต่อเรา" },
        progress = { "N 446:719352751:869339477", "{name} หากมาทวนคำสั่งก็ดี ข้าต้องการเกล็ด Hatecrest สิบชิ้น หากมาคุยเล่น ตอนนี้ข้าไม่มีเวลาสำหรับเรื่องเล็กน้อย\n\nจงรู้ไว้ ไนต์เอลฟ์ไม่ได้กระหายสงคราม เผ่าพันธุ์เราทุ่มเทรักษาสันติและความกลมกลืน แต่ไม่ได้หมายความว่าเราจะไม่ลงมือปกป้องผลประโยชน์ตน นี่คือหน้าที่ข้าต่อนายพล Feathermoon และฐานที่มั่น" },
        completion = { "395:316975222:1541718900", "ใช่ ใช่ เกล็ดเหล่านี้ดีเกินคาด ข้าว่าจะส่งให้ Pratt ดู บางทีเขาอาจประดิษฐ์ของมีประโยชน์ได้\n\nส่วนเจ้า ข้ามีภารกิจใหม่ให้ แต่ก่อนอื่น รับค่าหัวสำหรับเกล็ดไป ความช่วยเหลือต่อนายพลและ Feathermoon Stronghold ของเจ้าเป็นพรในยามลำบาก" },
        required = { [9247] = { "20:1702815882:1961340009", "เกล็ดนากา Hatecrest" } },
        steps = { { "20:1702815882:1961340009", "เกล็ดนากา Hatecrest" } },
    },
    [2870] = { -- Against Lord Shalzaru
        title = { "21:1086875059:593780057", "ต่อกร Lord Shalzaru" },
        objective = { "124:1388612874:1206616468", "กำจัด Lord Shalzaru แล้วนำ Mysterious Relic ที่เขาขุดพบไปให้ Latronicus Moonspear ที่ Feathermoon Stronghold" },
        description = { "N 494:1385107469:1602469637", "{name} รายงานสอดแนมใหม่ช่วยให้เราเห็นสายบังคับบัญชานากาชัดขึ้น มีเชื้อพระวงศ์อยู่ในกอง และพวกนั้นเป็นผู้สั่งการทั้งหมด\n\nเราเจาะจงได้ว่าหนึ่งในเชื้อพระวงศ์ที่โหดร้ายกว่าคนอื่นคือ Lord Shalzaru ผู้สอดแนมบอกว่าเขาขุดพบวัตถุประหลาดด้วยตนเอง ระหว่างขุดค้นถ้ำทางใต้ของซากเมืองหลัก ข้ามน้ำไปบน Isle of Dread\n\nหยุดเรื่องนี้ด้วยการกำจัดเขา แล้วนำวัตถุมาให้เราศึกษา" },
        progress = { "202:1813090145:1194348595 N 1:63:63", "การโค่น Lord Shalzaru จะทำให้แผนนากาล่าช้าหลายสัปดาห์ หรืออาจหลายเดือน ยิ่งไปกว่านั้น วัตถุที่เขาพบเป็นสิ่งที่เราสนใจแน่นอน\n\nเจ้าทำภารกิจที่ได้รับแล้วหรือยัง {name}?" },
        completion = { "13:461971584:4088015 N 395:1201072634:1091006108 N 19:1797807256:44905317", "ทำได้ดี {name}! การตายของ Lord Shalzaru จะทำให้นากาวุ่นวายไปพักใหญ่ หากไม่ใช่ตลอดไป ตอนนี้เราควบคุมภัยของมันได้มากกว่าที่เคย ต้องขอบคุณเจ้า\n\nนี่คือค่าหัวเพิ่มจากคลังฐานที่มั่น เจ้าสมควรได้รับทุกเหรียญทองแดง เจ้าและพวกพ้องเป็นที่ต้อนรับใน Feathermoon Stronghold เสมอ สหาย\n\nก่อนจากไป ข้ามีอีกเรื่อง {name}... หากเจ้าช่วยได้..." },
        required = { [9248] = { "16:635656309:191686010", "โบราณวัตถุปริศนา" } },
        steps = { { "16:635656309:191686010", "โบราณวัตถุปริศนา" } },
    },
    [2871] = { -- Delivering the Relic
        title = { "20:1966294474:1963011412", "ส่งมอบวัตถุโบราณ" },
        objective = { "75:1134929273:1021682208", "นำ Mysterious Relic ไปให้ Vestia Moonspear ที่ Feathermoon Stronghold" },
        description = { "443:917344852:1282661380 N 1:46:46", "หากเจ้าช่วยนำวัตถุไปให้ Vestia ภรรยาข้า จะขอบคุณมาก นางไม่เพียงเป็นนักบวชหญิงที่ดีของชุมชน แต่ยังเป็นผู้รู้รอบด้านที่สุดคนหนึ่ง ข้าดูอุปกรณ์นี้ไม่ออกเลย ต่อให้มีพนันก็เถอะ แต่ถ้าใครจะรู้ว่ามันคืออะไร ภรรยาข้าน่าจะทำได้... และเราต้องรู้!\n\nนางอยู่ถัดมุมไปนิดเดียว ไม่ต้องสงสัยว่ากำลังศึกษาอยู่ ขอบใจ {name}" },
        progress = { "43:423416160:1297314504 C 265:529242132:1581288948", "ข้าช่วยอะไรได้ไหม?\n\nเดี๋ยวก่อน เจ้าเป็น {class} ที่ช่วยนายพล Feathermoon กับ Latro จัดการภัยนากาใช่ไหม? ข้าคือ Vestia ภรรยา Latro... เอ่อ Latronicus ยินดีที่ได้รู้จัก!\n\nขอโทษด้วย เจ้ามาทำธุระนี่นา มีของให้ข้าหรือ? จากเขาหรือเปล่า?" },
        completion = { "465:910671991:1380423968", "น่าสนใจ... บอกว่ามาจาก Ruins of Solarsal หรือ? Latro พูดถูกที่ให้ข้าดู แวบแรกมันดูไม่ใช่ของดั้งเดิมในซากเมือง และก็ไม่ใช่แบบที่นากาออกแบบ ของแปลกแยกขนาดนี้ไม่น่าใช่\n\nคงต้องใช้เวลาวิจัย เมื่อศึกษาเสร็จแล้ว บางทีข้าจะขอใช้ความสามารถของเจ้าหากยังอยู่แถวนี้\n\nนี่ เลือกของที่เรามีเกินชิ้นหนึ่ง หวังว่าเจ้าจะใช้ประโยชน์ได้!" },
        required = { [9248] = { "16:635656309:191686010", "โบราณวัตถุปริศนา" } },
        steps = { { "16:635656309:191686010", "โบราณวัตถุปริศนา" } },
    },
    [2879] = { -- The Stave of Equinex
        title = { "20:593221564:39469126", "ไม้เท้าแห่ง Equinex" },
        objective = { "53:2071284470:589509140", "เติมพลังให้ Troyas' Stave และค้นหา Equinex Monolith" },
        description = { "505:652923454:287860998", "ไม้เท้านี้อาจเป็น Stave of Equinex! จริง ๆ แล้วมันคือกุญแจสำหรับเปิด Equinex Monolith ที่ Ruins of Ravenwind บนแผ่นดินใหญ่ทางตะวันตกของ Dream Bough\n\nค้นหาเปลวไฟทั้งสี่ที่ยังลุกในซากเมือง: Samha, Imbel, Byltan และ Lahassa เก็บแก่นพลัง แล้วขณะยืนใกล้ Equinex Monolith ให้ใช้แก่นพลังเติมพลังไม้เท้า หากเป็น Stave of Equinex จริง เจ้าจะเปิดแท่งศิลาและนำโบราณวัตถุศักดิ์สิทธิ์ออกมาได้" },
        progress = { "79:594238912:2094807664", "Equinex Monolith ตั้งเงียบอยู่กลางซากเมือง ข้างในจะมีอะไร?" },
        completion = { "280:800619757:926029843", "ไม้เท้าที่มีพลังแทบถือไว้ไม่ไหว พลังสั่นสะเทือนผ่านร่างคุณ\n\nคุณยื่นมือไปยังผิวเย็นของ Equinex Monolith...\n\nประตูเล็กเปิดให้เอื้อมหยิบโบราณวัตถุข้างใน\n\nลำแสงส่องเต็มพื้นที่รอบ Equinex Monolith" },
        required = { [9306] = { "16:855058307:516235920", "ไม้คทา Equinex" } },
        steps = { { "16:855058307:516235920", "ไม้คทา Equinex" } },
    },
    [2939] = { -- In Search of Knowledge
        title = { "22:47094571:921331808", "แสวงหาความรู้" },
        objective = { "46:167412770:2109495855", "คุยกับ Daryn Lightwind ที่ Rut'theran Village" },
        description = { "445:1869237801:264406686 N 58:886374965:882472500", "แม้ซากเมือง Feralas จะอันตราย แต่บอกเล่าสิ่งที่เกิดขึ้นที่นี่ได้มาก\n\nไม่กี่วันก่อน ข้าค้นกองซากทางใต้แล้วพบสิ่งที่ดูเหมือนไม้เท้าธรรมดา แต่สลัดความรู้สึกว่ามันมีอะไรมากกว่านั้นไม่ได้ Angelas กับข้าค้นตำรามากมายแต่ไม่พบข้อมูล\n\nข้ามีเพื่อนร่วมงานที่ Darnassus ซึ่งอาจบอกได้ว่ามันคืออะไร {name} ลองไปคุยดูว่านางช่วยได้ไหม?" },
        completion = { "132:1061033373:881152258 N 324:380999441:986536443", "อ้อ Troyas Moonbreeze ส่งเจ้ามาหรือ?\n\n<พึมพำ> ...กวนข้าอยู่เรื่อยด้วยความคิดเพ้อฝันว่าเจอของสำคัญ...\n\nฟังนะ {name} ข้าจะพูดตรง ๆ Troyas คิดเสมอว่าเจอของสำคัญในซากเมือง ที่จริง ของมีค่าจริง ๆ คงถูกโอเกอร์หรือฮาร์ปีที่อาศัยอยู่ที่นั่นเก็บไปนานแล้ว\n\nเจ้าลองดูรอบ ๆ ได้ แต่ข้าไม่รู้ว่าจะมีตำราเล่มไหนช่วยได้" },
    },
    [2940] = { -- Feralas: A History
        title = { "18:937737654:1429560560", "Feralas: ประวัติศาสตร์" },
        objective = { "47:1265622531:1544469366", "ถาม Daryn Lightwind ว่าขอยืมหนังสือของนางได้หรือไม่" },
        description = { "274:736688219:1065382198", "หนังสือเล่มนี้ดูไม่มีใครเปิดมานาน ปกสึกมากและหน้ากระดาษเหลือง แต่เมื่อสำรวจ คุณเห็นว่ามันอาจเป็นสิ่งที่ Troyas กำลังหา\n\nคุณหยิบขึ้นมา แต่คิดว่าควรขอก่อนยืม" },
        completion = { "99:1013325404:916041430 N 44:1626550777:1013385586", "อยากยืม Feralas: A History หรือ?\n\nให้ข้าคิดก่อน...\n\nข้าจะให้ยืม {name} แต่ต้องทำบางอย่างให้ข้าก่อน" },
    },
    [2941] = { -- The Borrower
        title = { "12:913040513:480618070", "ผู้ขอยืม" },
        objective = { "48:490760506:737725607", "นำจดหมายไปให้ Curgle Cranklehop ที่ Tanaris" },
        description = { "466:922928530:342722385", "ข้าศึกษาหลายเรื่องมาตลอด ช่วงนี้สนใจเต่า Snapjaw ตามชายหาด Hinterlands เป็นพิเศษ มีตัวหนึ่งที่อยากเห็น คือเต่ายักษ์ Gammerita ข้าอยากไปเอง แต่งานวิจัยทำให้ต้องอยู่ที่นี่ รูปของมันคงเป็นทางเลือกที่ดีรองลงมา\n\nนำจดหมายนี้ไปให้ Curgle Cranklehop ที่ Tanaris นางสร้างสิ่งประดิษฐ์ให้ข้าซึ่งบันทึกภาพได้ ข้าว่านางเรียกภาพนั้นว่า \"ภาพถ่าย\"..." },
        progress = { "19:980926583:2134276101", "จดหมาย... ถึงข้าหรือ?" },
        completion = { "79:976456147:1025864103 N 121:648034775:108594162", "เจ้าเป็นเด็กฝึกงานอีกคนของ Daryn หรือ? นางเป็นนักประวัติศาสตร์ผู้รอบรู้มาก {name} เจ้าควรยินดีที่ได้ศึกษาภายใต้การดูแลของนาง\n\nเอาล่ะ ให้ข้าหา Super Snapper FX ก่อน เจ้าต้องชอบแน่!" },
        required = { [9329] = { "12:1545192075:1902663509", "ข้อความสั้น" } },
        steps = { { "12:1545192075:1902663509", "ข้อความสั้น" } },
    },
    [2942] = { -- The Morrow Stone
        title = { "16:1125630161:281407421", "ศิลา Morrow Stone" },
        objective = { "99:639357224:257715846", "นำ Sparkling Stone และ Stave of Equinex กลับไปให้ Troyas Moonbreeze ที่ Feathermoon Stronghold" },
        description = { "112:1557443728:1395691888", "ทันทีที่นำโบราณวัตถุออกจากแท่งศิลา คุณรู้สึกว่าพลังใน Stave of Equinex เริ่มจางลง" },
        progress = { "29:1030616964:375584387 N 38:1571412843:1055518899", "ดีใจที่เจ้ากลับมา {name} ข้าอยากฟังสิ่งที่เจ้าพบ" },
        completion = { "36:389738137:937160299 N 316:1412774756:1158690134 N 30:1041914630:1044000657", "ข้าอ่านตำรามาตั้งแต่เจ้าจากไป {name} ศิลาที่เจ้าพบเรียกว่า Morrow Stone แม้ยังไม่แน่ใจว่าใช้ทำอะไร แต่การที่ถูกซ่อนไว้ใน Equinex Monolith เช่นนั้นย่อมแสดงว่ามีความสำคัญอย่างยิ่ง\n\nข้าจะศึกษาต่อ และหวังว่าจะพึ่งเจ้าได้อีกในอนาคต {name} ขอบคุณสำหรับความช่วยเหลือทั้งหมด" },
        required = { [9307] = { "17:1422835586:1247529299", "หินเปล่งประกาย" }, [9306] = { "16:855058307:516235920", "ไม้คทา Equinex" } },
        steps = { { "17:1422835586:1247529299", "หินเปล่งประกาย" }, { "16:855058307:516235920", "ไม้คทา Equinex" } },
    },
    [2943] = { -- Return to Troyas
        title = { "16:6352473:246761988", "กลับไปหา Troyas" },
        objective = { "64:182175129:190866503", "นำหนังสือไปให้ Troyas Moonbreeze ที่ Feathermoon Stronghold" },
        description = { "12:1055357314:800872003 N 91:458132053:1769067412", "นี่ {name} โปรดดูแลหนังสือข้าด้วย\n\nรีบไปเถิด ข้ามั่นใจว่า Troyas รอเจ้ากลับมาอยู่" },
        progress = { "7:989913233:66981971 N 29:1149277521:1655834892", "สวัสดี {name} เจ้าไป Darnassus มาหรือยัง?" },
        completion = { "41:149441604:120892716", "เจ้าหอบหนังสือมาด้วย ยอดเยี่ยม!" },
        required = { [9331] = { "18:937737654:1429560560", "Feralas ฉบับประวัติศาสตร์" } },
        objectiveLabels = {
            item = { ["Feralas: A History"] = "Feralas ฉบับประวัติศาสตร์" },
        },
    },
    [2944] = { -- The Super Snapper FX
        title = { "20:1380494602:2086899437", "กล้อง Super Snapper FX" },
        objective = { "111:753761548:1345090294", "ใช้ Super Snapper FX ถ่ายภาพ Gammerita แล้วกลับไปหา Daryn Lightwind ที่ Rut'theran Village" },
        description = { "41:1431430158:972444024 N 326:1714472124:1028648902", "ชมสิ่งประดิษฐ์ใหม่ข้าเป็นคนแรก {name} แค่เลือกเป้าหมายที่อยากถ่ายแล้วกดปุ่ม\n\nสัตว์จาก Hinterlands ที่เจ้าพูดถึงชื่ออะไรนะ? Gammerita หรือ? ขอให้โชคดีในการตามหา ข้ามั่นใจว่า Daryn ต้องพอใจภาพที่เจ้าถ่ายกลับไป\n\nเอาเถอะ นี่คือ Super Snapper สนุกให้เต็มที่!" },
        progress = { "31:1457912767:134391962 N 73:2077590402:142567956", "ในที่สุดเจ้าก็กลับมา {name} และนำสิ่งประดิษฐ์ที่ Curgle สร้างให้ข้ามาด้วย เยี่ยมมาก" },
        completion = { "124:784085233:187969083 N 37:1222364153:14370411", "อืม! สิ่งประดิษฐ์ของ Curgle ทำได้ตามคาด\n\nอย่าเพิ่งดีใจเกินไป แต่รู้ไว้เถอะว่าข้าพอใจผลงานเจ้า {name}\n\nเอ แล้วข้าวางหนังสือไว้ไหนนะ..." },
        required = { [9330] = { "21:1712829510:221260821", "ภาพถ่ายของ Gammerita" }, [9328] = { "16:1642331345:416182602", "กล้องถ่ายภาพ Super Snapper FX" } },
        steps = { { "21:1712829510:221260821", "ภาพถ่ายของ Gammerita" }, { "16:1642331345:416182602", "กล้องถ่ายภาพ Super Snapper FX" } },
    },
    [2969] = { -- Freedom for All Creatures
        title = { "25:2107700252:924968245", "อิสรภาพแด่ทุกชีวิต" },
        objective = { "235:1634539653:612514801", "ใช้ Bamboo Cage Key ปล่อย Sprite Darter จากคอกในค่าย Grimtotem ต้องมี Sprite Darter อย่างน้อย 6 ตัวและ Kindal Moonweaver รอดชีวิต\n\nคุณมีเวลา 6 นาที ก่อน Kindal จะตัดสินใจถอยและภารกิจล้มเหลว" },
        description = { "56:811732525:346035609 N 431:262859490:1532761997", "เผ่า Grimtotem โสโครกกำลังจับมังกรภูต {name} Jer'kai กับข้าไม่รู้ว่ามันจะทำอะไร แต่คงไม่ใช่เรื่องดี\n\nเราไม่แข็งแกร่งพอฝ่าเข้าไปปล่อยมังกร แต่บางทีหากเจ้าช่วย...\n\nหากยินดีและมีเพื่อนที่แข็งแกร่ง ใช้กุญแจนี้เปิดกรงและดูแลให้พวกมันหนีรอด ข้าจะอยู่เคียงข้างตลอด ส่วน Jer'kai จะอยู่ที่นี่" },
        progress = { "110:1072171448:1705880148", "เราปล่อยให้ Grimtotem ทำลายสัตว์งดงามเหล่านี้ไม่ได้ ต้องปลดปล่อยพวกมัน!" },
        completion = { "13:753156707:758377448 N 385:970189273:697923043", "ขอบคุณ Elune {name}! เจ้าเป็นพรยิ่งใหญ่แก่เราและมังกรที่ช่วยไว้ Jer'kai กับข้าไม่มีวันช่วยเองได้ เราจะจดจำการที่เจ้าเข้าขัดขวาง Grimtotem\n\nไปคุยกับ Jer'kai เถิด ข้าต้องเตรียมตอบโต้ แค่มังกรภูตเป็นอิสระ ไม่ได้หมายความว่าจะยังเป็นอิสระต่อไป ตอนนี้ข้ากับ Jer'kai จะเป็นฝ่ายรุก" },
        objectiveLabels = {
            event = { ["Save at least 6 Sprite Darters from capture"] = "ช่วย Sprite Darter อย่างน้อย 6 ตัวให้รอดจากการถูกจับ" },
        },
    },
    [2970] = { -- Doling Justice
        title = { "14:666376837:462781481", "ทวงคืนความยุติธรรม" },
        objective = { "127:1325511171:1401603297", "ฆ่า Grimtotem Naturalist 12 คน, Grimtotem Raider 10 คน และ Grimtotem Shaman 6 คน แล้วกลับไปหา Jer'kai Moonweaver ใน Feralas" },
        description = { "461:502642917:238540920", "อย่างที่ Kindal บอก ข้ากับนางจะเป็นฝ่ายรุกเข้าใส่ Grimtotem หากร่วมมือกัน เราน่าจะจัดการทอเรนบางส่วนได้โดยไม่เสี่ยงมากนัก แต่ถ้าเจ้ายังไหวและยินดี เราก็อยากให้ช่วย\n\nเจ้าเห็นค่ายด้านล่างแล้ว แต่ทางตะวันออกยังมีอีก ใช้กลยุทธ์ของเจ้าสร้างความเสียหายให้มากที่สุด เราค่อยมาพบกันที่นี่หลังพวกมันรู้รสลูกธนู Kindal และอาวุธของเจ้า" },
        progress = { "327:1743719273:1399493578", "Kindal ต้องใช้เวลาเตรียมตัว แต่เราฆ่าไปหลายสิบแล้ว Grimtotem รู้ดีว่าเราอยู่แถวนี้ และตามหาเราราวอสรพิษ\n\nมันจะทำทุกอย่างเพื่อตัดหัวเรา ระวังตัวด้วย... ตอนนี้เจ้าขัดขวางมันแล้ว พวกมันจะตามล่าเจ้าเช่นกัน" },
        completion = { "28:437893383:2084868411 N 383:731493363:1373320646", "Kindal มองเจ้าไม่ผิด {name} เจ้ามีพรสวรรค์ด้านนี้จริง เป็นนักผจญภัยมากประสบการณ์กว่าเราทั้งคู่ ข้าขอบคุณ\n\nGrimtotem ก้าวร้าวกว่าทอเรนส่วนใหญ่ ข้าสงสัยว่าพวกเดียวกันเองไม่พอใจการกระทำของมันไหม ถ้าใช่ก็ไม่น่าแปลก อย่างที่เจ้าคงรู้ หลายเผ่าพันธุ์ใน Azeroth มีสายสัมพันธ์กับพวกเดียวกันที่ไม่เป็นมิตรนัก\n\nแต่นั่นเป็นเรื่องคุยกันวันอื่น" },
        objectiveLabels = {
            monster = { ["Grimtotem Naturalist slain"] = "ปราบ นักธรรมชาติวิทยา Grimtotem", ["Grimtotem Raider slain"] = "ปราบ ผู้จู่โจม Grimtotem", ["Grimtotem Shaman slain"] = "ปราบ ชาแมน Grimtotem" },
        },
    },
    [2972] = { -- Doling Justice
        title = { "14:666376837:462781481", "ทวงคืนความยุติธรรม" },
        objective = { "78:369096200:1086327448", "นำ Jer'kai's Signet Ring ไปให้ High Priestess Tyrande Whisperwind ที่ Darnassus" },
        description = { "410:2056003441:914265743 N 1:46:46", "ในถิ่นทุรกันดารนี้ Kindal กับข้ามีสิ่งตอบแทนเจ้าไม่มาก แต่ไม่อยากให้รู้สึกว่าเราไม่เห็นค่า รับแหวนตราของข้าไว้ หากไปยังกิ่งก้าน Teldrassil จงเข้า Temple of the Moon ใจกลาง Darnassus ที่นั่นมีมหาปุโรหิต Tyrande Whisperwind ของข้า แหวนจะบอกนางว่าเราปลอดภัย และทำให้เรื่องของเจ้าน่าเชื่อถือ\n\nเราทั้งคู่ขอบคุณ {name}" },
        progress = { "385:2105404696:1396214637", "สวัสดี ลูกเอ๋ย เรายินดีที่มีนักผจญภัยผู้ทรงพลังในวิหาร หากมีเวลา เจ้าจะเล่าเรื่องให้เหล่านักผจญภัยรุ่นเยาว์ฟังสักเรื่องสองเรื่องได้ไหม? ปัญญาของเจ้าคงช่วยหลายคนได้\n\nขอโทษด้วย ข้าเสียมารยาทเสียจริง เจ้ามาวิหารเพื่อขอความช่วยเหลือ แต่ข้ากลับรบกวน โปรดยกโทษ บอกมาว่าผู้รับใช้แสงสว่างช่วยอะไรได้" },
        completion = { "25:844643537:875693802 N 377:185073529:497142149", "เรื่องน่าทึ่งมาก {name} เราดีใจที่เจ้าไม่เพียงช่วยมังกร แต่ยังช่วยนักบวชหญิงคนหนึ่งของเรา Jer'kai ส่งเจ้ามาหาข้าได้ถูกแล้ว ข้าจะส่งแหวนคืนให้นาง อีกไม่นานผู้สอดแนมจะมุ่งไป Feralas เรื่องนี้จะเป็นอีกสิ่งให้พวกเขาตรวจระหว่างภารกิจ\n\nขอบคุณอีกครั้ง โปรดพักผ่อนให้สบายเสมือนบ้านของเจ้า" },
        required = { [9368] = { "21:1057186964:425811740", "แหวนตราของ Jer'kai" } },
        steps = { { "21:1057186964:425811740", "แหวนตราของ Jer'kai" } },
    },
    [2982] = { -- The High Wilderness
        title = { "19:1340036138:405855588", "แดนป่าสูง" },
        objective = { "99:1096420825:1040230527", "Angelas Moonbreeze ต้องการให้คุณฆ่า Gordunni Warlock 8 คน, Gordunni Shaman 8 คน และ Gordunni Brute 8 คน" },
        description = { "501:1836297059:1500548345", "แม้อันตราย Troyas กับข้าก็ศึกษาซากเมืองที่กระจายทั่วป่า Feralas\n\nแต่พักหลัง Troyas ไป High Wilderness คนเดียว ข้าเป็นห่วงมาก โอเกอร์ Gordunni ยึดพื้นที่นั้น และไม่เป็นมิตรกับผู้บุกรุกอาณาเขต\n\nข้าหวังว่าเจ้าจะยินดีไปซากเมืองทางตะวันออกเฉียงใต้และกำจัดโอเกอร์บางส่วน ทำให้ปลอดภัยขึ้นสำหรับ Troyas ของข้า ข้าจะขอบคุณมาก" },
        progress = { "33:57057766:1079995136 N 66:1135582260:2070010324", "ระวัง Gordunni ด้วย {name} เวทมนตร์ของมันดูเหมือนทำลายแม้แต่ผืนดินที่ยืนอยู่" },
        completion = { "109:1982399689:2065411508", "ข้าขอบคุณมากที่เจ้าทำให้ได้\n\nทีนี้ โปรดอย่าบอก Troyas เรื่องนี้แม้แต่คำเดียว..." },
        objectiveLabels = {
            monster = { ["Gordunni Warlock slain"] = "ปราบ วอร์ล็อก Gordunni", ["Gordunni Shaman slain"] = "ปราบ ชาแมน Gordunni", ["Gordunni Brute slain"] = "ปราบ อ็อกเกอร์จอมโหด Gordunni" },
        },
    },
    [3130] = { -- Against the Hatecrest
        title = { "21:1793767818:797422445", "ต่อกร Hatecrest" },
        objective = { "57:1484655399:1567254298", "รายงานต่อ Latronicus Moonspear ที่ Feathermoon Stronghold" },
        description = { "395:1252268718:1207938780 N 31:1459158175:518432876", "ตอนนี้ข้าจะส่งเจ้าไปหารองของข้า Latronicus เขาจับตากำลังนากามาตลอด ข้าจะประเมินภาพรวมที่นี่ แม้อยากส่งกำลังทั้งหมดเข้าจัดการ แต่การเปิดฐานให้ Horde หรือสิ่งที่ร้ายกว่าโจมตีตรง ๆ คงไม่ใช่ทางเลือกที่ดี\n\nเอาเถอะ Latronicus รออยู่ ที่ผ่านมาเจ้าทำได้ดี {name} รักษาฝีมือไว้\n\nไปได้" },
        completion = { "11:1614239848:1406166483 N 390:489535855:1910139151", "ยอดเยี่ยม {name} ข้าเห็นคุณค่าคนร่วมงานที่มีทัศนคติว่า \"ทำได้\"\n\nนายพล Feathermoon มอบหมายให้ข้าจัดการนากาโดยตรง แผนมีสองส่วน หนึ่ง ลดทั้งจำนวนกำลังและผู้นำของมัน สอง ค้นให้รู้ว่าทำอะไรในซากเมือง หากเจ้าช่วย เราจะรับมือนากาได้โดยไม่ลดความปลอดภัยโดยรวมของฐาน" },
    },
    [3445] = { -- The Sunken Temple
        title = { "17:895383639:1283129457", "วิหารจมดิน" },
        objective = { "35:1083849611:1571432929", "ตามหา Marvon Rivetseeker ใน Tanaris" },
        description = { "455:1443062845:596583154", "ข้าได้ยินเรื่องสถานที่ลึกใต้ผิวโลก ถูกขับลงไปด้วยพลังยิ่งใหญ่กว่าที่ข้าเคยเห็น\n\nหากอยากรู้เรื่อง Sunken Temple มากขึ้น จงตามหากอบลิน Marvon Rivetseeker เขาศึกษาสถานที่โบราณมากมายเช่นเดียวกับ Troyas และข้า ข่าวล่าสุดคือจากบ้านที่ Ratchet ไปศึกษาซากเมืองโทรลล์ใน Tanaris\n\nขอให้โชคดีในการตามหา ไม่มีใครได้ข่าวเขามาพักใหญ่แล้ว" },
        completion = { "190:1609324863:502143654", "ใช่ Sunken Temple ข้าบอกได้ว่าเห็นกับตาตัวเองแล้ว อยากฟังต่อไหม?\n\nเจ้าดูเป็นพวกชอบผจญภัย ข้ารู้เรื่องที่อาจทำให้สนใจ..." },
    },
    [3841] = { -- An Orphan Looking For a Home
        title = { "28:2145529880:860067585", "ลูกกำพร้าตามหาบ้าน" },
        objective = { "37:97475656:513440191", "คุยกับ Quentin ที่ Thousand Needles" },
        description = { { "11:750834850:1066141596 N 475:170818658:302685658", "11:750834850:1066141596 N 475:1681800766:451798087" }, "โอ้ สวัสดี {name} ดีใจที่พบอีกครั้ง ไป Darnassus มาเป็นอย่างไร?\n\nเจ้าคงยินดีที่รู้ว่าระหว่างไม่อยู่ เราคืบหน้าไปมาก ถึงกับช่วยไข่ได้ทั้งรัง แต่น่าเสียดายที่แม่ตายก่อนเราไปถึง\n\nว่าแต่ อยากรับตัวหนึ่งเป็นสัตว์เลี้ยงไหม? ไข่ดูใกล้ฟักแล้ว จึงต้องมีผู้เลี้ยงดูที่ดี ว่าอย่างไร?\n\nถ้าสนใจจริง นำไข่ใบหนึ่งไปหา Quentin ที่สนามแข่งใน Shimmering Flats เขาจะบอกเพิ่มเติม" },
        progress = { "11:1021475657:99162037 C 485:876290439:1262497836", "สวัสดี {class}\n\nอย่าให้สถานที่หลอกตา ข้าไม่ได้มาเพื่อดูแข่งจริง ๆ... แม้มันจะสนุกก็ตาม\n\nข้ามา Thousand Needles เพื่อสืบว่าดินแดนนี้ยังฟื้นฟูได้แค่ไหน การนำดินอุดมสมบูรณ์ใหม่มาเติมและฟื้นพื้นที่แทบเป็นภารกิจชีวิตของข้า บางทีอาจพบแหล่งน้ำใกล้ ๆ\n\nอย่าบอกว่าเจ้าไม่สังเกตว่ารอยต่อระหว่าง Feralas กับ Thousand Needles แปลกเพียงใด ตอนเกิดการเปลี่ยนแปลงนั้นต้องมีเวทมนตร์ประหลาดเกี่ยวข้อง" },
        completion = { "388:1322756135:1856489462", "อา ไข่ Sprite Darter และถ้าไม่ผิดก็ดูใกล้ฟัก น่าทึ่งที่พบได้ แถมสภาพดีขนาดนี้ ทุกวันนี้แทบไม่พบใน Feralas ข้าได้ยินว่ามีนักลักลอบหลายกลุ่มพยายามจับและฆ่าด้วยเหตุผลสารพัด น่าเสียดาย... โตเต็มวัยแล้วงดงามเหลือเกิน\n\nเจ้าได้ของหายากเช่นนี้มาอย่างไร?" },
    },
    [3842] = { -- A Short Incubation
        title = { "18:297970377:1236429345", "บ่มฟักอีกเล็กน้อย" },
        objective = { "60:14339128:2092385828", "นำ Elixir of Fortitude 2 ขวดไปให้ Quentin ที่ Thousand Needles", variants = { { "6:1273960851:929420321 W1 60:952835008:1546178324", "นำ Elixir of Lesser Fortitude {world1} ขวดไปให้ Quentin ที่ Thousand Needles" } } },
        description = { "504:456246792:536007028", "พวก Moonweaver หรือ? น่าสนใจมาก ข้าหวังว่า Sprite Darter จะเข้าใจจริง ๆ ว่าการมีสองคนนั้นดูแลมีค่าเพียงใด ทั้งคู่มีฝีมือมาก\n\nพวกเขามอบไข่เป็นของขวัญให้สินะ ถ้าอย่างนั้นเจ้าควรรับผิดชอบตราบเท่าที่ต้องการ ดูเกือบพร้อมฟักแล้ว แต่เราควรตรวจให้แน่ใจว่าสมบูรณ์และไม่เสียหาย\n\nข้าต้องการ Elixir of Fortitude เพียงสองขวดสำหรับคาถาเล็กน้อยเพื่อปกป้องไข่ ส่วนผสมอื่นมีแล้ว", variants = { { "477:1265408241:744355240", "พวก Moonweaver หรือ? น่าสนใจจริง ๆ ข้าอยากให้เหล่า Sprite Darter เข้าใจว่าการได้สองคนนั้นคอยดูแลมีค่าขนาดไหน ทั้งคู่มีฝีมือมาก\n\nพวกเขาให้ไข่เป็นของขวัญแก่เจ้าสินะ ถ้าอย่างนั้นเจ้าก็รับผิดชอบดูแลมันได้นานเท่าที่ต้องการ ดูเหมือนมันใกล้ฟักแล้ว แต่เราควรตรวจให้แน่ใจว่ามันแข็งแรง\n\nข้าขอ Elixir of Lesser Fortitude แค่สองขวดสำหรับร่ายเวทเล็ก ๆ ปกป้องไข่ ส่วนของอย่างอื่นข้ามีอยู่ที่นี่แล้ว" } } },
        progress = { "73:595052807:1697156628 N 187:1971308311:83991901", "ยิ่งอยู่ที่นี่นาน ข้าก็ยิ่งอยากเข้าร่วมแข่ง {name} ชวนพิศวงจริง ๆ...\n\nได้ยามาหรือยัง? เมื่อข้าตรวจได้ว่าไข่จะสมบูรณ์ไหม ก็จะคืนให้เจ้าถือไว้จนพร้อมฟัก\n\nได้แล้วบอกข้าด้วย" },
        completion = { "130:394417794:1522261567", "ยอดเยี่ยม ใช้ได้ดีทีเดียว ให้เวลาข้าผสมส่วนประกอบสักครู่ แล้วเราจะรู้ว่าไข่นี้เป็นอย่างไร" },
        required = { [3825] = { "26:1672872988:640372489", "ยาเสริมความทรหดระดับต่ำ" } },
        objectiveLabels = {
            item = { ["Elixir of Lesser Fortitude"] = "ยาเสริมความทรหดระดับต่ำ" },
        },
    },
    [3843] = { -- The Newest Member of the Family
        title = { "31:186757267:623713808", "สมาชิกใหม่ที่สุดของครอบครัว" },
        objective = { "170:1068851008:2111595696", "นำ Fragile Sprite Darter Egg ไป Hinterlands แล้วคุยกับ Agnar Beastamer ต้องรีบ คุณมีเวลาเพียง 1 ชั่วโมงก่อนลูกสัตว์ในไข่จะตาย" },
        description = { "24:623621288:1722932095 N 356:116442455:1625577153 N 65:1929519373:1153728784", "เป็นตัวอย่างที่ยอดเยี่ยม {name} หากรอดช่วงฟัก ก็จะเป็นสัตว์เลี้ยงแข็งแรงแน่!\n\nหากเจ้าจะทำต่อ ข้าแนะนำอีกอย่าง ไป Aerie Peak ที่ Hinterlands คุยกับคนแคระ Agnar Beastamer เขาเป็นผู้เชี่ยวชาญดูแลสัตว์ น่าจะแนะนำขั้นสุดท้ายของการฟักได้\n\nแต่รีบหน่อย {name} ไข่เปราะบางและอยู่ได้ไม่นานหากขาดการดูแลที่ถูกต้อง" },
        progress = { "11:1988767264:581875424 N 32:438735333:1816910394", "สวัสดี {name} ข้าช่วยอะไรได้บ้าง?" },
        completion = { "318:277138360:1244788233", "อืม อืม... ไม่ได้เห็นแบบนี้มานานเท่าอายุมังกรแล้ว ถ้าข้าไม่ผิด มันคือมังกรภูต... ดูเป็นพวก Sprite Darter ยอดเยี่ยมจริง ๆ\n\nถ้าเจ้าตัวน้อยจะฟักและเติบโตแข็งแรง เราควรหาอาหารให้ ดีที่เจ้าพามาทัน" },
    },
    [4124] = { -- The Missing Courier
        title = { "19:1072758065:62877647", "ผู้ส่งสารที่หายไป" },
        objective = { "56:20624821:1794135939", "คุยกับ Ginro Hearthkindle ที่ Feathermoon Stronghold" },
        description = { "463:2103655129:939811530", "Ginro Hearthkindle เพื่อนร่วมงานข้ากำลังหาคนช่วยตามหาผู้ส่งสารกับพัสดุที่ขนไป เขาหายราวหนึ่งสัปดาห์แล้ว การค้นหาของเราไม่พบอะไรและถึงทางตัน น่าเสียดายที่ข้าต้องประกาศว่าเขาสูญหายระหว่างปฏิบัติหน้าที่\n\nหากมีเวลาและทรัพยากรพอ โปรดคุยกับ Ginro เขาน่าจะอยู่ในฐาน อาจอยู่ในห้องพัก" },
        completion = { "380:1320180892:160069963", "ข้าเดาว่า Latro ส่งเจ้ามา แม้ตอนนี้คิดว่าคงไร้หวัง แต่ข้ารับความช่วยเหลือทุกอย่าง ยอมรับว่า... คงดีใจเมื่อวางใจเรื่องนี้ได้ ทุกวันข้าออกป่า Feralas หาร่องรอย Raschal และทุกคืนกลับมาได้เพียงฟันโนลล์กับความผิดหวัง" },
    },
    [4125] = { -- The Missing Courier
        title = { "19:1072758065:62877647", "ผู้ส่งสารที่หายไป" },
        objective = { "63:855059634:650882540", "ค้นหาเรือของผู้ส่งสารที่ใดสักแห่งตามชายฝั่ง Feralas" },
        description = { "484:1991913237:846557799", "ราวหนึ่งสัปดาห์แล้วที่ Raschal ผู้ส่งสารออกไป Thalanaar เขารู้จัก Feralas ดี อยู่กับเราตั้งแต่นายพล Feathermoon นำกองกำลังสำรวจมาที่นี่ ข้ารู้ว่าเขาวางแผนพายเรือลงชายฝั่ง แล้วข้ามตอนใต้ของ Feralas เพื่อหลีกค่าย Horde\n\nข้าหาเรือไม่พบ แต่บางทีเจ้าทำได้ มันอาจถูกซ่อนหรือจม อย่างไรก็อาจมีเบาะแสว่าเขาอยู่ไหน หากพบอะไรโปรดบอก" },
        completion = { "418:279860808:387410436", "คุณพบสิ่งที่ดูเป็นซากเรือพาย ในน้ำขุ่นเล็กน้อยเห็นรูใหญ่หลายรูตามกราบซ้าย เรือแทบถูกฉีกจนเหลือโครงไม้ สิ่งที่ทำคงพยายามหักเรือเป็นสองท่อน กราบขวามีตรา Feathermoon Stronghold เล็ก ๆ\n\nในโคลนใต้เรือ แสงสะท้อนจากโลหะบางอย่างสะดุดตา..." },
    },
    [4127] = { -- Boat Wreckage
        title = { "13:235500060:846297563", "ซากเรือ" },
        objective = { "96:59767349:807625270", "กลับ Feathermoon Stronghold แล้วให้ Ginro Hearthkindle ดู Discarded Knife ที่คุณพบ" },
        description = { "480:411787599:1634231641", "เมื่อไล่มือไปตามโคลน นิ้วคุณสัมผัสด้ามมีด มันดูได้รับการดูแลดี จึงน่าจะเป็นของคนบนเรือที่ทำหล่น บางทีเรือส่วนใหญ่ที่หายไปอาจเกี่ยวข้องกับการเสียมีด\n\nคุณหยิบมีด นึกได้ว่า Ginro Hearthkindle ที่ Feathermoon Stronghold สั่งให้กลับไปเมื่อพบเบาะแส แต่รู้สึกว่าคุณอาจไม่ได้อยู่ในน้ำเพียงลำพัง..." },
        progress = { "17:1649718571:1619240179 N 105:613358488:1971914744", "อา ยินดีต้อนรับกลับ {name} หวังว่าเจ้าจะพบเบาะแสชะตาสุดท้ายของ Raschal แม้อาจเป็นเรื่องเศร้าก็ตาม" },
        completion = { "342:445148198:498640681", "น่าสนใจ... ข้าว่านี่คือมีด Raschal เจ้าบอกว่าพบใต้น้ำพร้อมเรือหรือ? แค่พบมีดอาจยังโยงกับการหายตัวไม่ได้ แต่เรามีทางเลือกนอกแบบเพื่อหาข้อมูลเพิ่ม\n\nเจ้าเคยได้ยินการอ่านอดีตจากสัมผัสไหม?" },
        required = { [11462] = { "15:532635772:1403504063", "มีดที่ถูกทิ้ง" } },
        steps = { { "15:532635772:1403504063", "มีดที่ถูกทิ้ง" } },
    },
    [4129] = { -- The Knife Revealed
        title = { "18:1664498678:546408037", "ความลับจากมีด" },
        objective = { "72:251432877:1640280454", "นำ Discarded Knife ไปให้ Quintis Jonespyre ที่ Feathermoon Stronghold" },
        description = { "495:1996239276:2013915149", "Quintis Jonespyre ดรูอิดประจำฐานมีทักษะ... แปลก ๆ หนึ่งในนั้นคือการอ่านอดีตของสิ่งของด้วยการสัมผัส อย่าถามว่าทำอย่างไร ข้าถือเป็นเวทมนตร์ที่ไม่เข้าใจและเลือกไม่ทำความเข้าใจ แต่รู้สองอย่าง หนึ่ง ข้าเคยเห็นมันได้ผล สอง เจ้าหมอนั่นติดหนี้ข้า\n\nนำมีดไปหา Quint บนบ้านต้นไม้เล็ก ๆ แล้วฝากบอกว่าหนี้ไพ่ Kalimdor Hold 'Em จะหมด หากเขาใช้มนตร์กับมีดนั้น" },
        progress = { "407:858876596:1573518762", "Ginro ส่งเจ้ามาหรือ?\n\nการอ่านอดีตจากสัมผัสเปลืองพลังจิตมาก... แต่การเสียไพ่ Kalimdor Hold 'Em ก็เหมือนกัน ที่นี่เรียกข้าว่า \"ราชาแห่งการแพ้พลิกล็อก\" อับโชคเรื่องไพ่... แต่คงโชคดีเรื่องเข้าใจความลับธรรมชาติ\n\nแน่นอน ข้าจะทำ นี่อาจเป็นจุดเปลี่ยนให้รู้ชะตา Raschal หากมอบมีดมา เราก็เริ่มได้" },
        completion = { "11:1191658970:1224418299 N 384:990936631:150125574", "ขอบใจ {name}\n\nแม้การอ่านอดีตจากสัมผัสไม่ใช่ศาสตร์แม่นยำ แต่ข้าเคยใช้เปิดมุมมองในสถานการณ์ที่คนอื่นตัดสินว่าไร้หวัง ข้าว่ามีดที่เจ้าพบจะทำให้เห็นสิ่งที่เกิดกับ Raschal\n\nใช้เวลาไม่นาน แต่ไม่ใช่งานสบายสำหรับผู้ร่าย โปรดอดทนหน่อย" },
        required = { [11462] = { "15:532635772:1403504063", "มีดที่ถูกทิ้ง" } },
        steps = { { "15:532635772:1403504063", "มีดที่ถูกทิ้ง" } },
    },
    [4130] = { -- Psychometric Reading
        title = { "20:335338108:768357687", "อ่านอดีตจากสัมผัส" },
        objective = { "56:20624821:1794135939", "คุยกับ Ginro Hearthkindle ที่ Feathermoon Stronghold" },
        description = { "448:1208011781:670652189 N 44:1739136506:1273799683", "ข้ายังมึนอยู่บ้าง ขอโทษ อย่างไรก็ตาม ได้เห็นภาพที่มีประโยชน์\n\nRaschal เอากระเป๋าหนังใหญ่สองใบจากเรือแล้วเข้าแผ่นดิน แต่กลับมาเรืออีก ข้าเห็นหนังศีรษะโนลล์... เขาพบโนลล์บางพวก คิดว่าชื่อ Woodpaw เขากังวลมาก แทบหวาดผวากับอะไรบางอย่าง จนไม่ทันสังเกตธาตุน้ำที่ก่อตัวด้านหลัง ภาพ... หยุดตรงนั้น\n\nข้าต้องพัก ขอโทษ {name} บอก Gin ว่าข้าเห็นอะไร เขาต้องรู้" },
        completion = { "48:2064186151:364804973 N 295:10334847:939344161", "ขอบใจที่ส่งต่อภาพของ Quint {name} คราวหน้าเล่นไพ่ ข้าจะพยายามจำไว้ว่าควรเบามือกับเขาหน่อย\n\nRaschal สู้เอาตัวรอดได้ และโนลล์ไม่น่าทำให้กังวล ไม่สิ หวาดผวา อย่างไรก็ตาม บางทีเจ้ากับพวกพ้องอาจใช้ข้อมูลใหม่นี้หาจุดเปลี่ยนที่เราต้องการอย่างยิ่ง" },
    },
    [4131] = { -- The Woodpaw Gnolls
        title = { "18:127471194:664284659", "โนลล์ Woodpaw" },
        objective = { "115:1270971488:1321825590", "ค้นค่ายโนลล์ Woodpaw ทางใต้ของ Feralas เพื่อหาหลักฐานข้าวของผู้ส่งสารหรือตัวเขาเอง" },
        description = { "497:2034715020:863061844", "\"สหาย\" Woodpaw อาจจับ Raschal ไปท้ายที่สุด แต่บางอย่างบอกข้าว่าไม่ใช่ ถึงอย่างนั้นก็เป็นจุดเริ่มค้นหาที่ดีที่สุด\n\nข้าอยากรู้ชัดกว่านี้ว่าต้องทำอะไร แต่ตอนนี้มีแค่ 'ไปค้นค่าย Woodpaw' ข้ารู้ว่าโนลล์เก็บของที่คุ้ยพบและแย่งกัน บางทีมันเจอกระเป๋าที่ Quint พูดถึง ก่อนหน้านี้ข้าไม่เสี่ยงสู้ซึ่งหน้า แต่เมื่อมีภาพของ Quint คราวนี้ข้าว่าบุกจัดการมันเลย" },
        completion = { "145:239474450:1532212247", "กระเป๋าหนังใหญ่สองใบถูกตรึงไว้บนต้นไม้ใกล้ ๆ ด้านหน้าแต่ละใบมีตรา Feathermoon Stronghold เล็ก ๆ..." },
    },
    [4135] = { -- The Writhing Deep
        title = { "17:849218967:1070505013", "ห้วงลึกอันดิ้นพล่าน" },
        objective = { "207:710001572:408999843", "เมื่อพบเบาะแสสถานที่สุดท้ายของ Raschal แล้ว จงตามหาเขาหรือร่างที่เหลือต่อใน Writhing Deep บันทึกบอกว่าอยู่ทางใต้ของค่ายโนลล์ Woodpaw" },
        description = { "500:441753215:1517407931", "ในกระเป๋ามีสองสิ่ง หนึ่งคือพัสดุสินค้าสำหรับ Thalanaar สองคือบันทึกที่รีบเขียนถึงผู้อ่านไม่ทราบชื่อ\n\nบันทึกกล่าวถึงสัตว์คล้ายแมลงอันชั่วร้ายที่พบทางใต้ของค่ายโนลล์ในสถานที่ชื่อ Writhing Deep ผู้เขียนคิดว่าต้องตรวจด้วยตนเอง ราวกับเป็นภัยร้ายแรงต่อ Feralas ทั้งหมด ลงชื่อว่า \"Raschal แห่ง Feathermoon\"\n\nดูเหมือนคุณจะรู้แล้วว่า Raschal ไปที่ไหนท้ายที่สุด" },
        completion = { "365:161661234:771894587", "คุณพบกระเปาะใหญ่รูปร่างประหลาด ผิวดูเป็นเมือก แต่มีส่วนแข็งยื่นจากหลายจุด มันสูงและกว้างพอหุ้มร่างคล้ายมนุษย์ได้สบาย... และจากเงาร่างจาง ๆ ที่เห็นผ่านผิว คุณคาดว่ามีร่างเช่นนั้นอยู่ข้างในจริง" },
    },
    [4265] = { -- Freed from the Hive
        title = { "19:1262374779:746920903", "ปลดปล่อยจากรังแมลง" },
        objective = { "140:846082245:2002647423", "ปล่อย Raschal จากรัง Zukk'ash\n\nกลับไปหา Ginro Hearthkindle ที่ Feathermoon Stronghold บอกว่า Raschal ยังมีชีวิตและปลอดภัย" },
        description = { "429:409583757:1392409682", "กระเปาะแยกเล็กน้อยเมื่อสัมผัส เผยไนต์เอลฟ์ชายที่ยังมีชีวิตอย่างน่าประหลาด เขาดูสุขภาพดีแต่ช็อกมาก เมื่อคุณช่วยลงมา เขาก็เริ่มรู้สึกตัว\n\n\"ขอบคุณ Elune เจ้าช่วยข้า สหาย! ข้า... ข้าคือ Raschal ตื่นขึ้นมาก็เป็นอัมพาตในกระเปาะหลังถูกแมลงพวกนี้รุม ฐานส่งเจ้ามาหรือ?\"\n\nดูเหมือนคุณจะพบผู้ส่งสารที่หายไปแล้ว!" },
        progress = { "30:1999183480:986876721 N 1:63:63", "มีรายงานอะไรหรือ {name}?" },
        completion = { "14:1627135819:296539812 N 393:1610757207:1298581269", "ยินดีต้อนรับกลับบ้าน {name} Raschal มารายงานเมื่อครู่นี้และเล่าเรื่องแล้ว\n\nข้า... ไม่สิ ทั้งฐานไม่รู้จะเริ่มขอบคุณอย่างไร หากเจ้าไม่ช่วยทัน Raschal คงตาย และเจ้ายังช่วยโดยไม่เอ่ยค่าจ้างทหารรับจ้างแม้แต่น้อย เจ้ามีคุณสมบัติวีรชนแท้ จงรู้ว่า Ginro Hearthkindle จะเป็นสหายของเจ้าเสมอ" },
        objectiveLabels = {
            event = { ["Free Raschal."] = "ปลดปล่อย Raschal" },
        },
    },
    [4266] = { -- A Hero's Welcome
        title = { "16:611557870:942575765", "ต้อนรับวีรชน" },
        objective = { "58:1827732499:1612712523", "คุยกับ Shandris Feathermoon ที่ Feathermoon Stronghold" },
        description = { "N 400:1334347304:1843028664", "{name} นายพล Shandris Feathermoon ต้องการพบเจ้าด้วยตนเอง ไม่ต้องสงสัยว่านางอยากขอบคุณที่ช่วยฐาน แต่ข้ารู้ว่านางยังต้องการคุยเรื่องแมลงที่เจ้ากับ Raschal เผชิญทางใต้ของ Feralas รายงานเกี่ยวกับ Zukk'ash เหล่านั้นช่าง... น่ากลัว หากพูดให้น้อยที่สุดแล้ว\n\nนายพลรออยู่ในอาคารหลัก" },
        completion = { "N 407:680107813:264729771", "{name} ข้าขอบคุณจากใจสำหรับความช่วยเหลือ ความกล้าหาญต่ออุปสรรคเหนือกำลังสมควรได้รับรางวัลยิ่งกว่านี้พันเท่า ถึงอย่างนั้น หวังว่าเจ้าจะรับสิ่งนี้ในนามทั้งฐาน\n\nทีนี้ หากไม่ขัดข้อง... ข้าอยากขอให้ช่วยอีกครั้ง เมื่อพบรัง Zukk'ash ใน Feralas ข้าคิดว่าเจ้าเหมาะที่สุดกับภารกิจนี้" },
    },
    [4267] = { -- Rise of the Silithid
        title = { "20:2024841036:1647432614", "การผงาดของซิลิธิด" },
        objective = { "59:1909868017:1436544347", "นำ Raschal's Report ไปให้ Gracina Spiritmight ที่ Darnassus" },
        description = { "458:432555164:1320010975 N 30:1734698298:926824037", "ข้าฝากสำเนารายงานของ Raschal เกี่ยวกับการระบาดทางตะวันออกเฉียงใต้ของ Feralas ไว้กับเจ้า ระหว่างยื่นรายงานหลักที่ Darnassus ข้าต้องการให้สำเนานี้แก่ผู้ร่วมงานของฝ่ายพิทักษ์ นางชื่อ Gracina Spiritmight เป็นนักบวชหญิงที่ Temple of the Moon ใน Darnassus มีความรู้กว้างขวางเรื่องสัตว์ชนิดนี้ การที่นางได้รับรายงานจะเป็นประโยชน์ต่อเราทุกคน\n\nไปได้ ขอให้โชคดี {name} ขอ Elune คุ้มครองเราทั้งหมด" },
        progress = { "174:1968946087:1818166360", "ยินดีต้อนรับสู่วิหารอันเป็นมงคล สหาย ข้าได้รับคำพยากรณ์แล้วว่าเจ้าจะมาจาก Feathermoon Stronghold มีรายงานที่ Shandris Feathermoon ให้เจ้าพามาหรือไม่?" },
        completion = { "471:1006939914:1350950625", "ไนต์เอลฟ์รู้จักภัยน่าสะพรึงในรายงานนี้ Shandris ฉลาดที่ส่งทั้งรายงานและเจ้ามาหาข้า\n\nสิ่งเหล่านี้จะกลืนกิน Feralas อย่างรวดเร็ว เป็นภัยคุกคามร้ายแรงที่สุดอย่างหนึ่งที่เราจะเผชิญ แมลงที่เจ้ากับผู้ส่งสารพบเรียกว่าซิลิธิด มันเป็นเพียงเครื่องมือของหนึ่งในภัยยิ่งใหญ่ที่สุดที่ทั้ง Horde และ Alliance จะต้องเผชิญ\n\nข้าอธิษฐานให้เรามีความมุ่งมั่นเอาชนะ ก่อนมันทำลายเรา" },
        required = { [11466] = { "16:1042397690:1994148091", "รายงานของ Raschal" } },
        steps = { { "16:1042397690:1994148091", "รายงานของ Raschal" } },
    },
    [4281] = { -- Thalanaar Delivery
        title = { "18:890808931:1253539723", "ส่งของสู่ Thalanaar" },
        objective = { "65:354136066:1912083553", "นำ Undelivered Parcel ไปให้ Falfindel Waywarder ที่ Thalanaar" },
        description = { "411:1972688858:1829292214", "พัสดุที่คุณพบในค่ายโนลล์ Woodpaw ควรส่งไปจุดพักเล็ก ๆ Thalanaar ทางตะวันออกเฉียงใต้ของ Feralas ไม่ว่าผู้ส่งสารที่หายไปจะพบชะตาใด งานส่งพัสดุก็ยังไม่สำเร็จ\n\nเมื่อตรวจห่ออย่างละเอียด พบชื่อเขียนมือ \"Falfindel Waywarder\" อยู่ด้านนอก บางทีนี่อาจเป็นผู้รับปลายทาง" },
        progress = { "22:2058428197:84684919 C 38:344979046:440326921", "ยินดีต้อนรับสู่ Thalanaar {class} ต้องการความช่วยเหลืออะไรหรือ?" },
        completion = { "451:119612910:515002611", "สรรเสริญ Elune ในที่สุดของจาก Feathermoon Stronghold ก็มาถึง!\n\nการที่เจ้ามาอาจบอกว่า Raschal ผู้ส่งสารประจำของเราพบเรื่องร้าย หวังว่าทุกอย่างจะลงเอยดี ข้ารู้ว่าพักหลัง Woodpaw ตื่นตระหนกมากจากบางอย่างทางใต้ บางทีเขาอาจประสบภัยในป่านั้น ระวังด้วย สหาย\n\nอย่างไรก็ตาม ขอบคุณอีกครั้ง นี่คือค่าส่งพัสดุ" },
        required = { [11463] = { "18:1200310743:1933312803", "พัสดุที่ยังไม่ได้ส่ง" } },
        objectiveLabels = {
            item = { ["Undelivered Parcel"] = "พัสดุที่ยังไม่ได้ส่ง" },
        },
    },
    [4297] = { -- Food for Baby
        title = { "13:1501337406:210706536", "อาหารสำหรับเจ้าตัวน้อย" },
        objective = { "68:980226474:334409855", "นำ Silvermane Stalker Flank 5 ชิ้นไปให้ Agnar Beastamer ที่ Hinterlands" },
        description = { "502:29570014:802001615", "Sprite Darter กินได้ทั้งพืชและเนื้อ ถ้าไข่จะฟัก เราควรเตรียมพร้อม เชื่อหรือไม่ อาหารที่ดีคือเนื้อส่วนสีข้างดิบชุ่มฉ่ำ ข้าไม่เคยรู้ว่าทำไม แต่เกี่ยวกับแผนของ Elune ต่อเอลฟ์... บางทีพวกมันอาจถูกสร้างให้เป็นผู้พิทักษ์หรืออะไรสักอย่าง ข้าไม่รู้\n\nข้าจะดูแลไข่ก่อน เจ้าไปหาเนื้อสีข้าง Silvermane Stalker ดี ๆ มาให้มันกินหลังฟักเถิด" },
        progress = { "20:1481418011:1935508750 N 197:607099464:1700614585 N 99:354185746:615213880", "ได้เนื้อหรือยัง {name}? ไข่เจ้าตัวน้อยใกล้ฟักแล้ว ถ้ามื้อแรกไม่ดีพอ อาจอยู่ไม่พ้นสัปดาห์แรก ข้าไม่อยากให้เกิดเช่นนั้น\n\nไม่โกหกหรอก {name} ข้าอิจฉาที่เจ้าได้ไข่นี้ตั้งแต่แรก อย่าทำให้เสียใจที่ช่วยเช่นนี้" },
        completion = { { "218:135585979:283781779", "218:503742034:394632575" }, "ใช้ได้ดี และถ้าไม่ผิด ไข่เจ้าตัวน้อยใกล้ฟักแล้ว รู้สึกอย่างไรล่ะที่กำลังจะได้เป็นพ่อแม่ให้มัน? ฮ่า ๆ ไม่คิดว่าจะต้องรับผิดชอบแบบนี้ใช่ไหม?" },
        required = { [11472] = { "24:2137758811:738784552", "เนื้อสีข้างของ Silvermane Stalker" } },
        objectiveLabels = {
            item = { ["Silvermane Stalker Flank"] = "เนื้อสีข้างของ Silvermane Stalker" },
        },
    },
    [4298] = { -- Becoming a Parent
        title = { "17:1163001269:734153174", "ก้าวสู่บทบาทผู้เลี้ยงดู" },
        objective = { "44:515598486:1063674337", "คุยกับ Agnar Beastamer ที่ Hinterlands" },
        description = { "47:1343479440:1386975046", "โอ้ พร้อมฟักกว่าที่ข้าคิดมากเลย..." },
        completion = { { "104:2024092109:3429703 N 27:80234818:1766635998", "104:398993233:1174478518 N 27:80234818:1766635998" }, "นี่ รับไข่ไป... เจ้าเก็บไว้ดีกว่า มันจะได้ผูกพันและเห็นเจ้าเป็นพ่อแม่\n\nยินดีด้วย {name} เจ้าเป็นผู้ปกครองแล้ว... ก็ประมาณนั้น" },
    },
    [7003] = { -- Zapped Giants
        title = { "13:39135428:1021549614", "ยิงย่อส่วนยักษ์" },
        objective = { "243:1456783776:1505464660", "ใช้ Zorbin's Ultra-Shrinker ยิงยักษ์ชนิดใดก็ได้ใน Feralas ให้มีขนาดจัดการง่ายขึ้น เก็บ Miniaturization Residue 15 ชิ้นจากยักษ์ที่ถูกย่อแล้วไปให้ Zorbin Fandazzle ที่ท่าเรือ Forgotten Coast ใน Feralas" },
        description = { "477:938164451:1444579377", "ถ้าข้าจะอยู่ที่นี่ ต้องทำอะไรกับยักษ์พวกนั้น! มันไม่ดีต่อธุรกิจเลยใช่ไหม?\n\nข้าพัฒนารังสีย่อส่วนโนมแบบดัดแปลง แต่ใช้เทคโนโลยีกอบลินที่เหนือกว่าในการสร้าง! เพื่อหลีกเลี่ยงความไม่สะดวกแก่ตัวเอง เช่นความตาย ข้าอยากให้เจ้าลองกับยักษ์ชนิดใดก็ได้ใน Feralas หลังย่อแล้วน่าจะพบกากย่อส่วน นำมาให้ข้าบ้าง!" },
        progress = { "284:130457832:529617812", "ข้ารับรองว่ากากย่อส่วนเป็นของมีค่าในงานวิศวกรรม! มีค่าตรงที่ช่วยให้ข้าแน่ใจว่าเครื่องจะไม่ทำสิ่งชวนผิดหวัง เช่นระเบิดใส่ผู้ใช้\n\nอ้อ หมายถึงเครื่องอื่นที่ไม่ใช่อันที่ให้เจ้า แน่นอน!" },
        completion = { "256:2097704930:156813246 N 91:1289376088:1684456564", "วิเศษสุดยอด! ไม่เพียงดีใจที่เจ้านำกากกลับมา แต่แขนขาส่วนสำคัญยังครบด้วย! คือว่า... การใช้ Ultra-Shrinker ไม่เคยอันตรายเลยนี่ ใช่ไหม!\n\nข้าขอบคุณที่เจ้าช่วย {name} เจ้าเป็นมิตรกับกอบลินทุกแห่งจริง ๆ รับสิ่งนี้แทนคำขอบคุณ!" },
        required = { [18956] = { "23:168979928:1399809183", "เศษตกค้างจากการย่อส่วน" } },
        steps = { { "23:168979928:1399809183", "เศษตกค้างจากการย่อส่วน" } },
    },
    [7721] = { -- Fuel for the Zapping
        title = { "20:1221778028:766845505", "เชื้อเพลิงสำหรับเครื่องยิง" },
        objective = { "177:327408026:261206456", "เก็บ Water Elemental Core 10 ชิ้นจาก Sea Elemental และ Sea Spray ตาม Forgotten Coast ใน Feralas แล้วนำกลับไปให้ Zorbin Fandazzle ใกล้ท่าเรือ" },
        description = { "457:1908398906:536700534", "ถ้าข้าฝืนสัญชาตญาณตนเองแล้วตั้งร้านวิศวกรรมริม Forgotten Coast ก็ต้องจัดการธาตุจอมกวนพวกนี้ ข้าขอสาปพลังธาตุที่ไร้การควบคุม!\n\nโชคดีสำหรับข้าและเจ้าผู้หวังว่าจะเป็นตัวป่วนให้ ธาตุเหล่านี้เป็นแหล่งพลังดิบเหมาะที่สุดสำหรับปรับปรุง Ultra-Shrinker ไปจัดการมันเลย! แต่ระหว่างทำ อย่าลืมเก็บแก่นธาตุน้ำให้ข้า!" },
        progress = { "231:2037993879:1010340737", "แทนที่จะทำให้เจ้าเบื่อด้วยรายละเอียดเทคนิคของแก่นธาตุ ข้าจะล่อใจให้ทำงานสำคัญนี้ให้เสร็จด้วยเงินและรางวัลมีค่า เอาล่ะ ทำเสร็จหรือยัง?" },
        completion = { "273:2050873209:479621574 N 164:2125780115:742510594", "สุดแสนวิเศษ! แก่นเหล่านี้ทำให้ข้าทำงานต่อได้พักใหญ่ เมื่อรวมกับธาตุตามชายฝั่งที่ลดลง บางทีข้าจะไม่ต้องร้องไห้ก่อนนอนเพราะคิดว่าตั้งร้านในที่แย่ที่สุดเท่าที่นึกออกอีก!\n\nขอบใจที่ช่วย {name} แม้มันทำให้การเงินข้าตึงมือ ก็ขอแสดงความขอบคุณด้วยสิ่งที่เจ้าคงเข้าใจและเห็นค่า... ของรางวัล!" },
        required = { [18958] = { "20:387219607:1745910112", "แกนธาตุน้ำ" } },
        steps = { { "20:387219607:1745910112", "แกนธาตุน้ำ" } },
    },
    [7725] = { -- Again With the Zapped Giants
        title = { "28:2021284307:579329272", "ยิงย่อส่วนยักษ์อีกครั้ง" },
        objective = { "243:1132417173:575948491", "ใช้ Zorbin's Ultra-Shrinker ยิงยักษ์ชนิดใดก็ได้ใน Feralas ให้มีขนาดจัดการง่ายขึ้น เก็บ Miniaturization Residue 10 ชิ้นจากยักษ์ที่ถูกย่อแล้วไปให้ Zorbin Fandazzle ที่ท่าเรือ Forgotten Coast ใน Feralas" },
        description = { { "403:317942518:1385108036", "405:1496284542:49309652" }, "ข้ารู้ว่าเจ้าเก็บกากให้แล้ว... แต่ถ้าอยากแสดงกิจกรรมสนุกนี้ซ้ำ ข้าก็ต้องการกากเพิ่มเสมอ\n\nแม้จ่ายค่าตอบแทนได้ไม่มากเท่าเดิม ข้ายินดีบอกความดีของเจ้าแก่สหายกอบลินทุกคนที่มีหู\n\nเชื่อข้าเถิดท่านผู้มีเกียรติ เมื่อข้าบอกว่ากอบลินพวกนี้มีหูใหญ่มาก" },
        progress = { "153:1136849844:739485905", "อา ผลของการวิจัยและประยุกต์ใช้ ในรูปกากหวานแสนหวาน คือข้าไม่ได้ชิมมันตอนศึกษาหรอกนะ\n\nไม่มากนัก" },
        completion = { "27:1553199723:566557155 N 339:2036281333:1935595636", "ยอดเยี่ยมเกินจินตนาการ {name}! เจ้าช่วยได้อีกแล้ว ข้าจึงขอบคุณ\n\nขอบคุณ!\n\nแม้เงินอาจน้อยกว่าที่คุ้นเคย จงมั่นใจว่าความดีของเจ้าเพื่อชาวกอบลินก้องไปถึงผู้มีอำนาจใน Steamwheedle Cartel หากต้องการงานเพิ่มก็มาคุยได้เลย!" },
        required = { [18956] = { "23:168979928:1399809183", "เศษตกค้างจากการย่อส่วน" } },
        objectiveLabels = {
            item = { ["Miniaturization Residue"] = "เศษตกค้างจากการย่อส่วน" },
        },
    },
    [7726] = { -- Refuel for the Zapping
        title = { "22:1802098257:1328605677", "เติมเชื้อเพลิงเครื่องยิงอีกครั้ง" },
        objective = { "176:1660836920:1967102852", "เก็บ Water Elemental Core 6 ชิ้นจาก Sea Elemental และ Sea Spray ตาม Forgotten Coast ใน Feralas แล้วนำกลับไปให้ Zorbin Fandazzle ใกล้ท่าเรือ" },
        description = { "487:1852532687:1934477171", "บอกว่าอยากทำงานเพิ่มหรือ? ภารกิจวีรชนเก็บเศษเมือกในร่างธาตุยังไม่ดับความกระหายผจญภัยหรือ? บางทีงานแบบเดิมอาจพยายามเติมบ่อภารกิจไร้ก้นของเจ้าอย่างไร้ผล...\n\nเอาล่ะ เลิกเล่นใหญ่ ข้าต้องการแก่นธาตุน้ำอีก กำลังดิ้นรนตั้งร้านที่นี่ รางวัลจึงไม่มากเท่าเดิม... แต่สัญญาว่าจะบอกทุกคนที่ได้ยินว่าเจ้าช่วยอย่างไร เชื่อเถอะ ข้ารู้จักคนใน Cartel!" },
        progress = { "52:466065305:1293505992", "หาแก่นธาตุที่ข้าต้องการได้หรือยัง?" },
        completion = { "11:836282937:1974526434 N 287:456558336:180868900", "ยอดเยี่ยม {name} ยอดเยี่ยม! แม้เงินที่ให้จะไม่มากที่สุดที่เคยได้จากงานเช่นนี้ แต่รับรองว่าสหายใน Steamwheedle Cartel จะรู้ความพยายามของเจ้า!\n\nหากอยากทำอย่างอื่นก็บอก ข้าต้องการแก่นธาตุและของทำนองนี้เพิ่มเสมอ" },
        required = { [18958] = { "20:387219607:1745910112", "แกนธาตุน้ำ" } },
        objectiveLabels = {
            item = { ["Water Elemental Core"] = "แกนธาตุน้ำ" },
        },
    },
    [7733] = { -- Improved Quality
        title = { "16:2065668035:1647491378", "คุณภาพที่ดียิ่งขึ้น" },
        objective = { "84:647727433:359462622", "นำ Rage Scar Yeti Hide 10 ผืนไปให้ Pratt McGrubben ที่ Feathermoon Stronghold ใน Feralas" },
        description = { "421:1382447473:1180940700", "ข้าได้เบาะแสแหล่งหนังที่ดีกว่าเดิมอีก หากเจ้าเชื่อได้! ทางเหนือของ Feralas ลึกใน Rage Scar Hold มีเยติอีกฝูง มันแข็งแกร่งกว่าที่เจ้าเคยจัดการมาก ถ้าพร้อมความท้าทายที่ใหญ่ขึ้นก็ควรระวังตัว!\n\nข้าจะให้รางวัลอย่างงามสำหรับหนังสิบผืน นำมาที่นี่แล้วเราจะปิดการค้า" },
        progress = { "166:160460122:1551127175", "หากหนังเยติ Rage Scar มีคุณภาพเหมือนพวก Feral Scar มันอาจทนทานเท่าธอเรียม!\n\nลองคิดดูสิ!" },
        completion = { "172:987609338:1586366330 N 48:436296411:1211070843", "ยอดเยี่ยม ยอดเยี่ยม! หนังเหล่านี้ใช้ได้ดีเหลือเชื่อ ข้ารู้เลยว่าถ้าฟอกถูกวิธีจะแข็งขึ้นอีกมาก\n\nขอบคุณอีกครั้ง {name} นี่ เลือกผลงานล่าสุดของข้าชิ้นหนึ่ง" },
        required = { [18947] = { "19:381715489:522803012", "หนังเยติ Rage Scar" } },
        steps = { { "19:381715489:522803012", "หนังเยติ Rage Scar" } },
    },
    [7735] = { -- Pristine Yeti Hide
        title = { "18:1615603688:1944960934", "หนังเยติสมบูรณ์แบบ" },
        objective = { "87:411007045:256362425", "นำ Pristine Yeti Hide ไปให้ Pratt McGrubben ที่ Feathermoon Stronghold ใน Feralas" },
        description = { "299:1416316660:649831303", "คุณพบหนังเยติสมบูรณ์แบบ หนาและเหนียวเป็นพิเศษ ยิ่งกว่าหนังจากเยติ Rage Scar ที่เคยเห็น\n\nเมื่อ Pratt McGrubben ที่ Feathermoon Stronghold ต้องการซื้อหนังเยติอยู่ ผืนนี้อาจทำให้เขาสนใจมาก" },
        progress = { "13:735579249:564635156 N 39:1144905198:1684527512", "อะไรหรือ {name} มีของพิเศษให้ข้าหรือ?" },
        completion = { "258:1595292367:887325621 N 1:33:33", "เหลือเชื่อ! นี่อาจเป็นสุดยอดแห่งหนังเยติทั้งหมด!\n\nเชื่อได้เลยว่าข้าจะจ่าย ปกติไม่ให้มากขนาดนี้สำหรับหนังผืนเดียว แต่ค่อนข้างมั่นใจว่าจะทำของพิเศษได้ ขอบคุณที่นึกถึงข้า {name}!" },
    },
    [3567] = { -- To the Top
        title = { "10:1462887269:796613135", "สู่ยอดเขา" },
        completion = { "85:412390593:1106411635 R 73:1969599190:870539789", "อยากชมวิวบนยอด Twin Colossals สักลูกไหม? ข้าส่งเจ้าไปได้ {race}\n\nแต่คิดด้วยว่าจะลงอย่างไร นี่เป็นการเดินทางขาเดียวเท่านั้น" },
    },
    [4041] = { -- The Videre Elixir
        title = { "17:121527342:1946426048", "ยา Videre Elixir" },
        progress = { "258:755933872:733596440", "นำ Evoroot มาให้ข้า แล้วแน่นอน ข้าทำ Videre Elixir ให้ได้\n\nข้ารู้เรื่องสมุนไพรกับเล่นแร่แปรธาตุสารพัด... จะเล่าให้ฟังว่าครั้งหนึ่งแปรธาตุทองจากชีสที่กำลังจะกินกลางวันอย่างไร... เฮ้... จะไปไหน?" },
        completion = { "44:191119189:984951536", "หลอกตาเฒ่า Miblon ได้แล้วสินะ?" },
        description = { "258:755933872:733596440", "นำ Evoroot มาให้ข้า แล้วแน่นอน ข้าทำ Videre Elixir ให้ได้\n\nข้ารู้เรื่องสมุนไพรกับเล่นแร่แปรธาตุสารพัด... จะเล่าให้ฟังว่าครั้งหนึ่งแปรธาตุทองจากชีสที่กำลังจะกินกลางวันอย่างไร... เฮ้... จะไปไหน?" },
        required = { [11242] = { "7:1000113046:1327784260", "รากเอโว" } },
        objectiveLabels = {
            item = { ["Evoroot"] = "รากเอโว" },
        },
    },
    [32] = { -- Rise of the Silithid
        title = { "20:2024841036:1647432614", "การผงาดของซิลิธิด" },
        objective = { "50:1767543140:797468844", "นำรายงานไปให้ Zilzibin Drumlore ที่ Orgrimmar" },
        description = { "496:150427323:1644713942", "นี่คือรายงานของเจ้า ข้าขอให้นำไปหาคนที่อาจมีความรู้เรื่องแบบนี้จริง ๆ ข้ารู้จักนักวิชาการโทรลล์ชื่อ Zilzibin Drumlore เขาศึกษาสิ่งมีชีวิตที่เป็นเอกลักษณ์ของระบบนิเวศ Azeroth มานานมาก แถมยังเป็นนักประวัติศาสตร์ด้วย! หากอยากได้คนช่วยหาคำตอบว่าภัยนี้คืออะไรกันแน่และจะหยุดได้อย่างไร ก็นำรายงานไปให้เขา เราต้องการความช่วยเหลือทุกทางที่หาได้ Zil อาศัยในบ้านบนชั้นสองของ The Drag ใน Orgrimmar" },
        progress = { "160:1479292236:1920994243", "ขอโทษด้วย ข้าไม่รู้จักเจ้า... แต่ดูท่าว่าอย่างน้อยเจ้าคงเคยได้ยินเรื่องของข้ามาบ้าง เอาล่ะ มีอะไรให้ข้าช่วย? เจ้ามีอะไรมาให้ข้าหรือ?" },
        completion = { "275:348134611:1548335463 N 198:552456524:258974970", "รายงานฉบับนี้... ข้าเคยรับมือสัตว์พวกนี้มาก่อน Fizzledowser คิดถูกแล้วที่ส่งทั้งรายงานและเจ้ามาหาข้า สิ่งมีชีวิตเหล่านี้จะกลืนกินทะเลทราย Tanaris อย่างรวดเร็ว พวกมันคือหนึ่งในภัยร้ายแรงที่สุดที่พวกเราทุกคนจะต้องเผชิญ จงจำชื่อนี้ไว้ให้ดี {name}: ซิลิธิด แมลงที่กล่าวถึงคือซิลิธิด และพวกมันเป็นเครื่องมือของหนึ่งในมหันตภัยที่ทั้ง Horde และ Alliance ต้องเผชิญ หากเพียงเราฉลาดพอจะมองเห็นเรื่องนี้ตั้งแต่ก่อนหน้านี้" },
    },
    [162] = { -- Rise of the Silithid
        title = { "20:2024841036:1647432614", "การผงาดของซิลิธิด" },
        objective = { "68:1721258591:2038773304", "นำ Insect Analysis Report ไปให้ Gracina Spiritmight ที่ Darnassus" },
        description = { "490:352022629:1013036295", "ข้าขอให้เจ้านำรายงานนี้ไปหาคนที่มีความรู้เกี่ยวกับเรื่องแบบนี้จริง ๆ\n\nข้ารู้จักนักวิชาการไนต์เอลฟ์ชื่อ Gracina Spiritmight นางศึกษาสิ่งมีชีวิตที่เป็นเอกลักษณ์ของระบบนิเวศ Azeroth มานานมาก แถมยังเป็นนักประวัติศาสตร์ด้วย! หากเจ้าอยากได้คนช่วยหาคำตอบว่าภัยนี้คืออะไรกันแน่ และที่สำคัญกว่านั้น เราจะหยุดมันได้อย่างไร ก็นำรายงานไปให้นาง เราต้องการความช่วยเหลือ\n\nครั้งสุดท้ายที่ได้ข่าว นางพักอยู่ที่ Temple of the Moon ใน Darnassus" },
        progress = { "82:1701114724:890914311", "ขอความสงบและความร่มเย็นจงอยู่กับเจ้า คนแปลกหน้า วันนี้เจ้ามาหาข้าด้วยเหตุใด?" },
        completion = { "288:1181575398:781315083 N 198:552456524:258974970", "รายงานฉบับนี้... พวกเราไนต์เอลฟ์รู้จักความสยดสยองที่กล่าวถึงอยู่ Fizzledowser คิดถูกแล้วที่ส่งทั้งรายงานและเจ้ามาหาข้า\n\nสิ่งมีชีวิตเหล่านี้จะกลืนกินทะเลทราย Tanaris อย่างรวดเร็ว พวกมันคือหนึ่งในภัยร้ายแรงที่สุดที่พวกเราทุกคนจะต้องเผชิญ จงจำชื่อนี้ไว้ให้ดี {name}: ซิลิธิด แมลงที่กล่าวถึงในรายงานคือซิลิธิด และพวกมันเป็นเครื่องมือของหนึ่งในมหันตภัยที่ทั้ง Horde และ Alliance ต้องเผชิญ\n\nหากเพียงเราฉลาดพอจะมองเห็นเรื่องนี้ตั้งแต่ก่อนหน้านี้" },
        required = { [8594] = { "22:1022044375:1634291193", "รายงานวิเคราะห์แมลง" } },
        objectiveLabels = {
            item = { ["Insect Analysis Report"] = "รายงานวิเคราะห์แมลง" },
        },
    },
    [485] = { -- Find OOX-09/HL!
        title = { "15:1487518054:1504397304", "ตามหา OOX-09/HL!" },
        objective = { "115:717816128:2084813704", "นำ distress beacon ไปให้หุ่นยนต์กลับฐานของ Oglethorpe ที่ต้นแม่น้ำใน Hinterlands ใกล้ Skulk Rock" },
        description = { "501:1967502968:55857139", "เจ้าพบอุปกรณ์โลหะแปลกรูปไข่ หมุนปุ่มหนึ่งแล้วมันตื่น เปิดเป็นกลไกหุ่นยนต์โนม! เสียงจากไข่ดังแตกพร่า\n\n“ข้าชื่อ Oglethorpe Obnoticus หุ่นยนต์กลับฐานข้าตก! จะตอบแทนการกู้ นำสัญญาณนี้ไปให้หุ่น!”\n\n“คำนวณตำแหน่งให้แล้ว ตกที่ต้นแม่น้ำใกล้ Skulk Rock!”" },
        progress = { "366:1910194723:1680827046", "ดูเหมือนคุณจะพบซาก... ไก่หุ่นยนต์? เสียงจากไข่ดังขึ้นอีกครั้ง\n\n\"ใช่ ทำได้ดี! นี่คือหุ่นยนต์นำทางของข้าจริง แต่เซนเซอร์บอกว่ามันต้องได้รับพลังงานกระตุ้นก่อนจะบินกลับ Booty Bay ไปซ่อมได้ วางสัญญาณลงในตัวหุ่นได้เลย มันจะจัดการที่เหลือเอง!\"" },
        completion = { "428:267948321:1758833213", "เจ้าวางไข่...เครื่องส่งสัญญาณ...ในไก่...หุ่นยนต์กลับฐาน\n\nเสียงครางและหมุนดังภายในขณะพยายามยืน เมื่อตื่น เสียง Oglethorpe ดังจากตัวหุ่น\n\n“อย่างน้อย OOX-09/HL ทำงาน แต่ต้องซ่อมใหญ่! หนักเกินเจ้าถือ...คิดออกแล้ว อยากคอยดูแลอีกหน่อยไหม?”" },
        required = { [8704] = { "25:1108786478:808217279", "เครื่องส่งสัญญาณขอความช่วยเหลือ OOX-09/HL" } },
        steps = { { "25:1108786478:808217279", "เครื่องส่งสัญญาณขอความช่วยเหลือ OOX-09/HL" } },
    },
    [2822] = { -- The Mark of Quality
        title = { "19:367753818:1609792767", "เครื่องหมายแห่งคุณภาพ" },
        objective = { "66:1923321497:1111223688", "นำ Thick Yeti Hides 10 ผืน ไปให้ Jangdor Swiftstrider ที่ Camp Mojache" },
        description = { "474:552509576:1439017931", "ข้าภูมิใจในงานหนัง และคิดว่าผลงานแสดงให้เห็น คุณภาพไม่ควรถูกลดทอน คนที่บอกว่าคุณภาพไม่สำคัญก็คงบอกว่าผืนดินไม่มีความลับ!\n\nระหว่างหาวัสดุคุณภาพสูงล่าสุด ข้าพบหนังเยติหนา เยติเป็นสัตว์พื้นเมือง Feralas มักพบใน Feral Scar Vale ทางตะวันตก หากได้หนังสิบผืน ข้าจะให้เลือกงานหนังชิ้นหนึ่ง หากตกลงก็ตามนั้น!" },
        progress = { "302:1007043698:508102168", "หา Thick Yeti Hides สิบผืนได้หรือยัง? งานหนังข้าไม่เป็นรองใคร และจะให้ชิ้นหนึ่งหากมีหนังมา\n\nหากหาเยติไม่พบ ลองทางตะวันตกจากที่นี่ บนฝั่งถัดจาก Forgotten Coast บริเวณ Feral Scar Vale" },
        completion = { "258:1369712967:2043278649 N 105:1997206451:411506492", "อา เยี่ยม! หนังพวกนี้หากผ่านกรรมวิธีพิเศษ จะทนทานดุจเหล็ก ข้าต้องทดลองหลายครั้งเพื่อหาส่วนผสมฟอกหนังที่เหมาะ แต่มั่นใจว่าจะยกระดับคุณภาพงานข้าได้\n\nส่วนเจ้า {name}... ความช่วยเหลือมีค่าเหลือเกิน โปรดเลือกไอเทมที่ข้าประดิษฐ์ไว้" },
        required = { [8973] = { "15:1952602579:2067607003", "หนังเยติหนา" } },
        steps = { { "15:1952602579:2067607003", "หนังเยติหนา" } },
    },
    [3380] = { -- The Sunken Temple
        title = { "17:895383639:1283129457", "วิหารจมดิน" },
        objective = { "35:1083849611:1571432929", "ตามหา Marvon Rivetseeker ใน Tanaris" },
        description = { "42:1877330169:1805504541 N 460:1673366209:1504029177", "โลกนี้มีวิญญาณที่ไม่สงบ {name} มีวิญญาณที่แปดเปื้อนเพราะความโดดเดี่ยว ถูกพันธนาการกับความชั่วร้ายโบราณ...\n\nข้าได้ยินเรื่องสถานที่ลึกใต้ผิวดิน ถูกพลังที่ยิ่งใหญ่เกินกว่าที่ข้าเคยพบเนรเทศลงไป\n\nหากอยากรู้เรื่อง Sunken Temple แห่งนี้เพิ่ม จงหาก็อบลินชื่อ Marvon Rivetseeker เขาศึกษาสถานที่โบราณมาหลายแห่ง ข่าวล่าสุดคือออกจากบ้านที่ Ratchet ไปศึกษาซากอารยธรรมโทรลล์ใน Tanaris" },
        completion = { "190:1609324863:502143654", "ใช่ Sunken Temple ข้าบอกได้ว่าเห็นกับตาตัวเองแล้ว อยากฟังต่อไหม?\n\nเจ้าดูเป็นพวกชอบผจญภัย ข้ารู้เรื่องที่อาจทำให้สนใจ..." },
    },
    [3909] = { -- The Videre Elixir
        title = { "17:121527342:1946426048", "ยา Videre Elixir" },
        objective = { "149:722235897:10446669", "ตามหา Gregan Brewspewer ทางเหนือของ Feralas เรียนรู้จากเขาว่าจะหา Videre Elixir ได้อย่างไร แล้วกลับไปหา Donova Snowden ที่ Winterspring" },
        description = { "493:117661792:1990011454", "ทีนี้ ว่าอย่างไรนะ? Linken... ลืมหรือ? อ้อ เข้าใจแล้ว... สูญเสียความทรงจำ... เอาล่ะ นี่คือดาบของเขา แต่มันยังไม่เสร็จสมบูรณ์ ข้ารู้จักคนที่ทำให้เสร็จได้ แต่... การพูดคุยกับเขาอาจลำบากหน่อย ฟังนะ ข้ารู้จักคนที่จะช่วยเจ้าได้ ตอนนี้มีเรื่องต้องอธิบายมากเกินไป แต่เจ้าต้องหาวิธีเอา Videre Elixir มา คนเดียวที่ข้ารู้ว่าช่วยเรื่องนี้ได้คือ Gregan Brewspewer ตามตัวเขายาก แต่ครั้งสุดท้ายที่รู้ เขาตั้งค่ายอยู่ในป่าของ Feralas" },
        progress = { "13:1270733455:2113900819", "กลับมาแล้วหรือ?" },
        completion = { "90:240770629:103135595", "ข้าต้องใช้ขวดหนึ่งเพื่อให้แน่ใจว่านี่คือน้ำยาจริง... ใช่... นี่แหละ" },
        required = { [11243] = { "13:384464728:1991240748", "ยา Videre" } },
        objectiveLabels = {
            item = { ["Videre Elixir"] = "ยา Videre" },
        },
    },
    [7734] = { -- Improved Quality
        title = { "16:2065668035:1647491378", "คุณภาพที่ดียิ่งขึ้น" },
        objective = { "79:1328850746:1210434913", "นำ Rage Scar Yeti Hides 10 ผืน ไปให้ Jangdor Swiftstrider ที่ Camp Mojache ใน Feralas" },
        description = { "421:1382447473:1180940700", "ข้าได้เบาะแสแหล่งหนังที่ดีกว่าเดิมอีก หากเจ้าเชื่อได้! ทางเหนือของ Feralas ลึกใน Rage Scar Hold มีเยติอีกฝูง มันแข็งแกร่งกว่าที่เจ้าเคยจัดการมาก ถ้าพร้อมความท้าทายที่ใหญ่ขึ้นก็ควรระวังตัว!\n\nข้าจะให้รางวัลอย่างงามสำหรับหนังสิบผืน นำมาที่นี่แล้วเราจะปิดการค้า" },
        progress = { "166:160460122:1551127175", "หากหนังเยติ Rage Scar มีคุณภาพเหมือนพวก Feral Scar มันอาจทนทานเท่าธอเรียม!\n\nลองคิดดูสิ!" },
        completion = { "172:582440093:1681196680 N 48:436296411:1211070843", "เยี่ยม เยี่ยม! หนังเหล่านี้จะใช้ได้ดีเหลือเชื่อ ข้ามองออกแล้วว่าหากฟอกถูกวิธีจะแข็งแกร่งกว่ามาก\n\nขอบใจอีกครั้ง {name} นี่ โปรดรับผลงานล่าสุดชิ้นหนึ่ง" },
        required = { [18947] = { "19:381715489:522803012", "หนังเยติ Rage Scar" } },
        steps = { { "19:381715489:522803012", "หนังเยติ Rage Scar" } },
    },
    [7738] = { -- Perfect Yeti Hide
        title = { "17:1762852984:1434493752", "หนังเยติสมบูรณ์แบบ" },
        objective = { "77:1458054451:368049335", "นำ Perfect Yeti Hide ไปให้ Jangdor Swiftstrider ที่ Camp Mojache ใน Feralas" },
        description = { "331:433774125:1807238935", "เจ้าพบสิ่งที่อาจเป็นหนังเยติสมบูรณ์แบบ เห็นชัดว่าหนาและแข็งแรงเป็นพิเศษ ยิ่งกว่าหนังจากเยติ Rage Scar ที่เคยเห็น\n\nเมื่อ Jangdor Swiftstrider ที่ Camp Mojache กำลังรับซื้อหนังเยติ ผืนนี้อาจทำให้เขาสนใจมาก" },
        progress = { "13:735579249:564635156 N 39:1144905198:1684527512", "อะไรหรือ {name} มีของพิเศษให้ข้าหรือ?" },
        completion = { "294:2022460222:629199380 N 1:33:33", "ค้นพบยอดเยี่ยม! ข้าเชื่อว่านี่เป็นตัวอย่างหนังเยติดีที่สุดที่เคยเห็น!\n\nสมควรได้ค่าตอบแทนเหมาะสม ปกติข้าไม่จ่ายมากเช่นนี้เพื่อหนังผืนเดียว แต่มั่นใจว่าทำของพิเศษได้ ขอบใจที่คิดถึงข้า {name}!" },
    },
    [1100] = { -- Lonebrow's Journal
        title = { "18:1655772283:1241944480", "บันทึกของ Lonebrow" },
        objective = { "31:2135741480:753930772", "อ่าน Henrig Lonebrow's Journal" },
        description = { "60:1384042832:1801538718", "คุณค่อย ๆ เปิดบันทึกเก่าคร่ำคร่าของ Henrig Lonebrow..." },
        progress = { "65:1675546563:203109429", "ดูจากสีหน้ากังวล ข้าก็บอกได้ว่ามีบางอย่างผิดปกติ..." },
        completion = { "95:1669192677:1603615260", "เจ้าบอกว่าพบบันทึกนี้กับศพคนแคระหรือ? ให้ข้าอ่านสักครู่..." },
        required = { [5790] = { "18:1655772283:1241944480", "บันทึกของ Lonebrow" } },
        steps = { { "18:1655772283:1241944480", "บันทึกของ Lonebrow" } },
    },
    [1104] = { -- Salt Flat Venom
        title = { "15:1973418536:978739023", "พิษแห่งที่ราบเกลือ" },
        objective = { "74:997593640:826241010", "นำ Salty Scorpid Venom 6 ชิ้นไปให้ Fizzle Brassbolts ที่ Shimmering Flats" },
        description = { "413:278334231:1050886377", "ข้ามีแบบรถจรวดมากมาย! มากมายจริง ๆ! และต้องลองให้ครบ!!\n\nกำลังทำเชื้อเพลิงใหม่ แบบที่เผาไหม้ร้อน ร้อน ร้อนสุด ๆ!! ยังผสมไม่ลงตัว แต่คิดว่ารู้แล้วว่าขาดอะไร...\n\nสกอร์พิดที่เดินตาม Shimmering Flats มีพิษที่เกลือเยอะมาก ๆ มันพิเศษจริง! และเป็นสิ่งที่ข้าต้องการพอดี!\n\nนำพิษมา แล้วเชื่อข้า รถเราจะบินได้!!" },
        progress = { "34:1746288292:539708662", "สวัสดี สวัสดี สวัสดี! ได้พิษมาหรือยัง??" },
        completion = { "54:32466073:163378945 N 111:479094975:327853075", "เยี่ยม! พิษนี้จะได้ผลดีมาก ขอบใจ {name}!\n\nทีนี้แค่ต้มให้เข้มข้น ใช้ Skipper-otomer เติม Nega-catalyst แล้ว... บ้าจริง! บันทึกข้าอยู่ไหน!?" },
        required = { [5794] = { "19:1555902678:417523080", "พิษแมงป่องรสเค็ม" } },
        steps = { { "19:1555902678:417523080", "พิษแมงป่องรสเค็ม" } },
    },
    [1105] = { -- Hardened Shells
        title = { "15:1463108374:447654121", "กระดองแข็งแกร่ง" },
        objective = { "78:799328493:801742181", "นำ Hardened Tortoise Shell 9 ชิ้นไปให้ Wizzle Brassbolts ที่ Shimmering Flats" },
        description = { "471:228234185:896700802", "พี่น้องของข้ากำลังทำเชื้อเพลิงใหม่สำหรับรถจรวด เขาฉลาดมากจริง ๆ ฉลาดจน... ข้าว่าเชื้อเพลิงที่ออกแบบอาจแรงพอกัดทะลุโครงรถ!\n\nข้าอยากเสริมถังเชื้อเพลิงก่อนเกิดเรื่องนั้น\n\nเต่าตามที่ราบมีกระดองแข็งมาก ข้าอยากใช้ทำถังใหม่ให้รถจรวด ถังที่ทนเชื้อเพลิงใหม่ของเขาได้\n\nเจ้าดูมีความรับผิดชอบพอ จะหากระดองให้ข้าไหม?" },
        progress = { "153:561149778:969175324 N 31:138745267:1774450282", "พี่น้องของข้าคืบหน้าในการทำเชื้อเพลิงใหม่ นั่นทำให้ข้ากังวล ต้องรีบเริ่มทำถังจากกระดองเต่า!\n\n{name} ได้กระดองมาหรือยัง?" },
        completion = { "22:122276881:865506933 N 119:1726066601:1908574033", "ได้มาแล้ว! ขอบใจ {name}!\n\nโอ้ กระดองแข็งกว่าที่คิด! เฮอะ ตอนทำงานกับมัน เครื่องมือข้าคงงอทั้งกล่อง!" },
        required = { [5795] = { "23:580050613:1337991967", "กระดองเต่าแข็ง" } },
        steps = { { "23:580050613:1337991967", "กระดองเต่าแข็ง" } },
    },
    [1106] = { -- Martek the Exiled
        title = { "17:457388958:1660368421", "Martek ผู้ถูกเนรเทศ" },
        objective = { "59:575218706:637794056", "นำ Fizzle's Letter ไปให้ Martek the Exiled ที่ Badlands" },
        description = { "491:1601487036:1360222906", "ข้ากำลังพัฒนาเครื่องยนต์ให้รถเร็วมาก! เร็วพอบินได้ ข้ารู้! ต้องทำลูกสูบที่ทนแรงกดดันมหาศาล แต่การทดลองล้มเหลวหมดเพราะทำให้แข็งพอไม่ได้!\n\nทว่ามีคนหนึ่งอาจรู้วิธี\n\nเขาชื่อ Martek the Exiled เป็นช่างตีเหล็กยอดเยี่ยม รู้เรื่องโลหะมากกว่าใคร นำจดหมายนี้ไปให้ ข้ารู้ว่าเขาช่วยได้!\n\nแต่เขาอยู่ไกลมาก ใน Azeroth ที่ Badlands ในค่าย อยู่กับกอบลิน!\n\nหาเขาให้พบ!" },
        progress = { "227:1534981295:804149460", "เจ้าพบข้าแล้ว ดีใจด้วย\n\nมาเรื่องขวานที่ข้าทำให้ Gath'Ilzogg หรือมาทวงเกียรติของ Duchess Pamay?\n\nที่จริงข้าไม่สนว่าเรื่องไหน ถ้ามาสู้ก็ให้มันจบ ๆ..." },
        completion = { "312:1697243068:203612325", "Fizzle ส่งเจ้ามาหรือ? อย่างนั้นต่างออกไป! แน่นอน ข้าจะช่วย เขากับพี่น้องเป็นคนไม่กี่คนที่ไม่อยากให้ข้าตาย!\n\nFizzle อยากทำลูกสูบสินะ? ลูกสูบที่ทนแรงทุกแบบที่คิดไว้ ถ้าข้ารู้จักเขาดี รถใหม่คันนี้ก็เป็นภูเขาไฟติดล้อ!" },
        required = { [5827] = { "25:664027234:1027345697", "จดหมายของ Fizzle Brassbolts" } },
        steps = { { "25:664027234:1027345697", "จดหมายของ Fizzle Brassbolts" } },
    },
    [1107] = { -- Encrusted Tail Fins
        title = { "19:332806899:1276109136", "ครีบหางเกรอะกรัง" },
        objective = { "74:1467381067:2082300179", "นำ Encrusted Tail Fin 10 ชิ้นไปให้ Wizzle Brassbolts ที่ Shimmering Flats" },
        description = { "354:850813018:782700988 N 135:1348034582:661447418", "รถจรวดเราเร็วที่สุดบนที่ราบ! เร็วจน... ข้ากลัวว่าแรงเสียดทานจะฉีกมันพัง!\n\nเพื่อป้องกัน ข้าต้องทำวัสดุผสมเคลือบส่วนเคลื่อนไหว ต้องแข็งแต่ไม่เปราะ และทนการกัดกร่อนจากเกลือ ไม่เช่นนั้นเวลาบน Shimmering Flats จะกัดมันจนหมด\n\nเคยได้ยิน Vile Reef ไหม {name}? อยู่นอกชายฝั่ง Stranglethorn Vale เมอร์ล็อก Saltscale อยู่ที่นั่น ครีบหางมันเป็นส่วนผสมสำคัญ" },
        progress = { "113:1009207398:661928011", "ได้ครีบหางไหม? ถ้าข้าปกป้องรถจากความเร็วของมันเองไม่ได้ ก็คงอยู่แข่งได้ไม่นาน" },
        completion = { "11:1191658970:1224418299 N 200:1479513384:1533479881", "ขอบใจ {name}! หลังบดแล้วผสมกับส่วนประกอบอื่นอีกหน่อย วัสดุผสมก็พร้อม จากนั้นรถจะปลอดภัยจากความเร็วตัวเอง\n\nปลอดภัย ตราบใดที่ไม่ชนอะไร..." },
        required = { [5796] = { "18:134990448:1763792804", "ครีบหางที่มีคราบเกาะ" } },
        steps = { { "18:134990448:1763792804", "ครีบหางที่มีคราบเกาะ" } },
    },
    [1108] = { -- Indurium
        title = { "8:1825245995:526330729", "อินดูเรียม" },
        objective = { "62:1639319349:1687552593", "นำ Indurium Flake 10 ชิ้นไปให้ Martek the Exiled ที่ Badlands" },
        description = { "92:1885221184:65102167 N 401:1639703391:497042197", "ข้าไม่ได้มาอยู่ที่นี่เพียงเพื่อหลบผู้คน ใน Badlands มีโลหะล้ำค่ามากมาย {name} หากเจ้ากล้าพอไปเอา\n\nโลหะนั้นชื่ออินดูเรียม โชคดีที่มีข่าวลือว่าทนความร้อนกับแรงกดดันสูง อาจใช้กับรถ Fizzle ได้\n\nแต่ต้องให้แน่ใจ นำตัวอย่างมา ข้าจะทดสอบคุณสมบัติ\n\nสินแร่อินดูเรียมแท้อยู่ลึกใน Uldaman แต่โทรกก์ Stonevault ใน Badlands บางครั้งมีเกล็ดโลหะติดตัว นำเกล็ดเหล่านั้นมาให้ข้า" },
        progress = { "34:1627678660:1660413554 N 51:2006056444:1136575798", "พบเกล็ดอินดูเรียมบ้างไหม {name}? ข้าเผาเตาพร้อมทดสอบแล้ว" },
        completion = { "84:1449468950:201008830", "อา ใช้ได้ดี ทีนี้ลองใส่ความร้อนแล้วดูว่าจะเป็นอย่างไร..." },
        required = { [5797] = { "14:1725303078:609595508", "เกล็ดแร่ Indurium" } },
        steps = { { "14:1725303078:609595508", "เกล็ดแร่ Indurium" } },
    },
    [1110] = { -- Rocket Car Parts
        title = { "16:1566979936:127678424", "ชิ้นส่วนรถจรวด" },
        objective = { "70:876612655:419828952", "นำ Rocket Car Part 30 ชิ้นไปให้ Kravel Koalbeard ที่ Shimmering Flats" },
        description = { "439:77775730:2124655249", "เฮอะ ๆ แข่งกันมากขนาดนี้ ไม่แปลกที่จะมีอุบัติเหตุบ้าง มองรอบ Shimmering Flats ก็เห็นร่องรอยการชนเก่า เศษชิ้นส่วนรถจรวดเกลื่อนทุกแห่ง!\n\nของพวกนั้นมีราคาสำหรับโนมกับกอบลิน มันหากลไกมาติดรถเพิ่มเสมอ\n\nออกไปเก็บชิ้นส่วน นำมาให้เป็นกองแล้วข้าจะจ่ายงาม ๆ" },
        progress = { "N 83:1349765159:830289810", "{name} ออกไปบนที่ราบหรือยัง? หอบชิ้นส่วนที่ข้าต้องการกลับมาไหม?" },
        completion = { "245:1015825890:1550939330 N 139:519779658:1871119761", "โอ้ ดูนั่นสิ! กองขยะนี้มีของดี ข้าว่าขายได้ราคางามแน่\n\nแล้ว... นั่นหูที่ถูกอัดระหว่างแผ่นโลหะสองแผ่นหรือ?? โอ๊ย! เฮอะ ข้าไม่อยากเป็นคนขับคนนั้นเลย!\n\nขอบใจ {name} นี่ค่าจ้าง และคำแนะนำฟรี...\n\nหากมองให้ดี เจ้าจะหากำไรจากโศกนาฏกรรมของผู้อื่นได้เสมอ" },
        required = { [5798] = { "16:1566979936:127678424", "ชิ้นส่วนรถจรวด" } },
        steps = { { "16:1566979936:127678424", "ชิ้นส่วนรถจรวด" } },
    },
    [1111] = { -- Wharfmaster Dizzywig
        title = { "20:2008507047:308867970", "นายท่า Dizzywig" },
        objective = { "62:865086361:1706066028", "นำ Kravel's Parts Order ไปให้ Wharfmaster Dizzywig ที่ Ratchet" },
        description = { "423:270619039:63092199", "ข้ามีหน้าที่หาสิ่งที่คนต้องการ และโนมพวกนั้นต้องการชิ้นส่วนตามใบสั่ง ของส่งถึง Ratchet เมื่อสัปดาห์ก่อน แต่ข้ายังไปไม่ได้\n\nพร้อมรับงานเดินทางไหม? ไป Ratchet นำใบสั่งนี้ให้ Wharfmaster Dizzywig เขาคงอยู่ท่าเรือ\n\nทำให้ข้าแล้วจะมีงานอีก\n\nงานที่มีโอกาสทำกำไรจริงจัง สหาย..." },
        progress = { "54:2007153772:2069876483", "พูดมา! จะส่งของหรือรับของ?" },
        completion = { "127:82366437:1383660367", "อ้อ ใช่ ชิ้นส่วน Kravel ดีใจที่เจ้ามา ของพวกนี้กองไว้หลายวัน ข้ากลัวจะขึ้นสนิม!" },
        required = { [5799] = { "20:306874234:1458493454", "ใบสั่งชิ้นส่วนของ Kravel" } },
        steps = { { "20:306874234:1458493454", "ใบสั่งชิ้นส่วนของ Kravel" } },
    },
    [1112] = { -- Parts for Kravel
        title = { "16:1253797335:484201494", "ชิ้นส่วนให้ Kravel" },
        objective = { "65:719488283:1247213891", "นำ Kravel's Parts ไปให้ Kravel Koalbeard ที่ Shimmering Flats" },
        description = { "25:705373751:10747288 N 103:1248144342:731964357", "นี่พัสดุ Kravel {name} ตอนส่ง ฝากบอกด้วยว่า... ถ้าอยากสั่งของพิเศษเพิ่ม ต้องจ่ายหนี้เก่าก่อน!" },
        progress = { "47:1116490010:2050776289", "ไป Ratchet รับชิ้นส่วนมาแล้วหรือ?" },
        completion = { "105:1277848699:375018062", "เยี่ยม ได้มาแล้ว! ทีนี้ต้องส่งให้โนม แต่ก่อนอื่น...\n\nขอหยิบของเล็ก ๆ ออกชิ้นหนึ่ง..." },
        required = { [5800] = { "14:1741016932:493214108", "ชิ้นส่วนของ Kravel" } },
        steps = { { "14:1741016932:493214108", "ชิ้นส่วนของ Kravel" } },
    },
    [1114] = { -- Delivery to the Gnomes
        title = { "22:1662722681:177655735", "ส่งของให้เหล่าโนม" },
        objective = { "70:1588868772:1457420155", "นำ Delicate Car Parts ไปให้ Fizzle Brassbolts ที่ Shimmering Flats" },
        description = { "259:243089007:749007225", "เมื่อข้าได้สิ่งที่ต้องการแล้ว จงนำชิ้นส่วนไปให้ Fizzle Brassbolts เขารอมานาน ข้ามั่นใจว่าไม่คิดถึงของเล็ก ๆ ที่ข้าหยิบออกหรอก...\n\nไม่ต้องพูดถึงกับเขาด้วย ของมันเล็กและไม่มีค่า\n\nเชื่อข้า" },
        progress = { "54:589775758:1391931400", "มีของให้ข้าหรือ? เยี่ยมเลย! ดูหน่อย!" },
        completion = { "89:1713390601:1702921584", "อยู่นี่แล้ว! Hydro Ratchet กับ Repeater Bolt ของข้า! ใช้ได้ดี ขอบคุณ!" },
        required = { [5802] = { "18:353292150:554991726", "ชิ้นส่วนรถที่บอบบาง" } },
        objectiveLabels = {
            item = { ["Delicate Car Parts"] = "ชิ้นส่วนรถที่บอบบาง" },
        },
    },
    [1115] = { -- The Rumormonger
        title = { "15:379771708:1303213840", "ผู้ค้าข่าวลือ" },
        objective = { "28:1207759788:988591782", "คุยกับ Krazek ที่ Booty Bay" },
        description = { "496:370926109:1056391818", "เมื่อช่วยโนมแล้ว ก็ถึงเวลาทำประโยชน์ให้กอบลิน!\n\nได้ยินว่าคนขับรถแข่งกอบลิน Nazz Steamboil ไม่ได้ใช้ชื่อนี้มาตลอด สงสัยว่าทำไมเปลี่ยนชื่อ มันเป็นความลับไหม และ... เขาให้ค่าความลับนั้นแค่ไหน\n\nหากใครรู้ คงเป็น Krazek ที่ Booty Bay ปลายใต้ Stranglethorn ไปถามเรื่องคนขับกอบลินของเรา\n\nถ้าได้ข้อมูลมีประโยชน์ บางทีเราจะทำกำไรจากมัน" },
        completion = { "194:1001511200:262093402", "อยากรู้เรื่อง Nazz Steamboil หรือ? คนขับรถแข่งที่ Shimmering Flats ใช่ไหม?\n\nใช่ ข้าอาจหาอะไรเกี่ยวกับเขาได้... แต่ไม่ง่าย ไม่เร็ว\n\nและไม่ถูก" },
    },
    [1117] = { -- Rumors for Kravel
        title = { "17:1795901543:687932692", "ข่าวลือให้ Kravel" },
        objective = { "68:1387303909:1813447115", "นำ Goblin Rumors ไปให้ Kravel Koalbeard ที่ Shimmering Flats" },
        description = { "337:249854184:284495223", "ข้าต้องใช้บุญคุณบางส่วน ยกไวน์เอลฟ์หายากให้คนอื่น และลงมืออนุมานหนักทีเดียว! แต่หาข้อมูลที่ต้องการได้แล้ว\n\nนี่ ข้าเขียนจดหมายมีเรื่องน่าสนใจของ Nazz Steamboil สหายเรา จะทำอะไรก็ตามใจ อันตรายเกินข้าจะใช้\n\nแค่อย่าบอกใครว่าได้จากไหน!" },
        progress = { "81:1220250729:858353820", "ได้เรื่อง Nazz Steamboil บ้างไหม? เรื่องที่เขาอยากเก็บเป็นความลับน่ะ??" },
        completion = { "145:790988247:133635266 N 72:1754969559:433363313", "อืม! น่าสนใจ... มากทีเดียว เฮอะ คราวหน้าเจอคนขับกอบลิน บางทีข้าควรคำนับ\n\nของนี้มีค่ามาก {name} ข้าว่า Nazz ยอมจ่ายก้อนโตเพื่อให้ความลับ... ยังเป็นความลับ" },
        required = { [5804] = { "13:2092749913:294744855", "ข่าวลือของก็อบลิน" } },
        steps = { { "13:2092749913:294744855", "ข่าวลือของก็อบลิน" } },
    },
    [1118] = { -- Back to Booty Bay
        title = { "17:1751430261:281505538", "กลับ Booty Bay" },
        objective = { "54:1070192861:1369651828", "นำ Kravel's Scheme ไปให้ Crank Fizzlebub ที่ Booty Bay" },
        description = { "N 11:2032088083:961332753 C 293:1306811706:554865980 N 181:2125494651:639659565", "{name} เจ้าเป็น {class} ที่ข้าไว้ใจ ทั้งทำงานสำเร็จและปิดปากขณะทำ\n\nข้าคิดแผนใหม่อยู่ เสี่ยง แต่ถ้าได้ผลเราทั้งคู่อาจได้เงินก้อนใหญ่! และข้าว่าเจ้าเหมาะเป็นคนลงมือ\n\nเริ่มจากกลับ Booty Bay ขอโทษด้วย {name} งานก่อนก็พาเจ้าไปที่นั่น แต่คราวนี้คุยกับ Crank Fizzlebub\n\nมอบจดหมายให้ หากเขาต้องการความช่วยเหลือก็ทำให้เต็มที่ มันจะคุ้มแรง" },
        progress = { "37:661333756:1892366100 R 31:1916092737:175750077", "สวัสดี สวัสดี อะไรพา {race} ผู้สูงส่งเช่นเจ้าลงมา Booty Bay?" },
        completion = { "220:1890924265:342238298", "เข้าใจแล้ว Kravel มีแผนใหญ่ จิตใจเขาชั่วร้าย ข้าชอบตรงนี้\n\nต้องการของทำให้มึนงงสินะ? ของแรง ๆ...\n\nสงสัยว่าส่วนผสมที่ Zanzil ให้ซอมบีกินจะใช้ได้ไหม..." },
        required = { [5826] = { "15:1234309025:527153097", "แผนการของ Kravel" } },
        steps = { { "15:1234309025:527153097", "แผนการของ Kravel" } },
    },
    [1119] = { -- Zanzil's Mixture and a Fool's Stout
        title = { "35:1960656065:1899173664", "ส่วนผสม Zanzil กับเหล้า Fool's Stout" },
        objective = { "62:1193038463:791180781", "นำ Fool's Stout กลับไปให้ Kravel ที่ Shimmering Flats" },
        description = { "188:1558326812:281033990 N 167:483792332:1347624738", "ข้าหาวิธีใช้ส่วนผสม Zanzil กับเหล้าสตาวต์ทำเป็นเครื่องดื่มแรงได้แล้ว Fool's Stout ข้าว่าเหมาะกับสิ่งที่ Kravel ต้องการ แต่ลองแล้วบอกด้วยว่าได้ผลอย่างไร\n\nแล้วก็ {name} อย่าเก็บไว้นานโดยไม่ใช้ ส่วนผสม Zanzil ทำให้ยีสต์ในสตาวต์ทำงานเร็วอย่างประหลาด จึงไม่สดอยู่ตลอดไป" },
        progress = { "7:989913233:66981971 N 32:347009952:885573013", "สวัสดี {name} Fizzlebub ช่วยเราได้ไหม?" },
        completion = { "90:175822498:1935150408 N 81:989665600:1575064121", "ยอดเยี่ยม! Fizzlebub ทำได้! ข้าจะจำไว้ตอนเจอคราวหน้า\n\nขอบใจด้วย {name} เจ้าทำได้ดี เราทั้งคู่มีโอกาสทำเงินมากจากเรื่องนี้..." },
        required = { [5806] = { "12:1557610516:753682013", "เบียร์ดำ Fool's Stout" } },
        steps = { { "12:1557610516:753682013", "เบียร์ดำ Fool's Stout" } },
    },
    [1120] = { -- Get the Gnomes Drunk
        title = { "20:1096718472:1374683109", "มอมเหล่าช่างโนม" },
        objective = { "45:206414883:2081958617", "นำ Fool's Stout ไปให้ Gnome Pit Boss" },
        description = { "216:1754727494:2108024180", "ต้องลอง Fool's Stout กับช่างทีมใดทีมหนึ่ง หากอยากลองกับโนม นี่ เอาไปให้หัวหน้าทีมช่างโนม\n\nอย่ารอนาน เหล้านี้จะเสียในที่สุด" },
        progress = { "30:1477155151:1662975455", "สวัสดี! มีอะไรให้ข้าหรือ?" },
        completion = { "176:1477514009:144395751", "เหล้าสตาวต์หรือ? ช่างมีน้ำใจ! ขอบคุณ!\n\nใกล้แข่งแล้วเราไม่ควรดื่ม แต่... ลูกทีมข้าคงจิบสักหน่อยได้ อีกอย่างคงไม่แรงนักหรอก ใช่ไหม?" },
        required = { [5806] = { "12:1557610516:753682013", "เบียร์ดำ Fool's Stout" } },
        steps = { { "12:1557610516:753682013", "เบียร์ดำ Fool's Stout" } },
    },
    [1121] = { -- Get the Goblins Drunk
        title = { "21:669744322:1399148785", "มอมเหล่าช่างกอบลิน" },
        objective = { "46:1362738456:147253678", "นำ Fool's Stout ไปให้ Goblin Pit Boss" },
        description = { "218:2027421448:1303987955", "ต้องลอง Fool's Stout กับช่างทีมใดทีมหนึ่ง หากอยากลองกับกอบลิน นี่ เอาไปให้หัวหน้าทีมช่างกอบลิน\n\nอย่ารอนาน เหล้านี้จะเสียในที่สุด" },
        progress = { "24:874232172:2118079239", "มองอะไรอยู่?" },
        completion = { "79:313964007:1463804621", "มีอะไรนี่? เหล้าหรือ?\n\nถ้าเพียงนิดหน่อย ข้าก็ไม่ขัด..." },
    },
    [1122] = { -- Report Back to Fizzlebub
        title = { "24:2079159452:681256736", "กลับไปรายงาน Fizzlebub" },
        objective = { "62:493946622:1562791819", "นำรายงาน Fool's Stout ไปให้ Crank Fizzlebub ที่ Booty Bay" },
        description = { "335:913888156:1174680150", "Fool's Stout ได้ผลดีมาก! ข้าวางเดิมพันการแข่งครั้งหน้าแล้ว และ... หวังว่าทีมที่เจ้ามอมจะทำรถตัวเองพัง!\n\nเหลืองานเดียว นำบันทึกกลับไปให้ Crank Fizzlebub ที่ Booty Bay เขาคงอยากรู้ว่าทดลองสำเร็จ\n\nหวังว่าเราจะหา Fool's Stout เพิ่มสำหรับการแข่งครั้งต่อไปได้!" },
        progress = { "6:1457790135:951305579 N 57:646005670:757084281", "สวัสดี {name} เหล้าได้ผลอย่างไร? ของแรงใช่ไหม?" },
        completion = { "171:124594068:1590843498", "ในนี้บอกว่า Fool's Stout สำเร็จ ข่าวดี!\n\nถ้าต้องการเพิ่มก็บอก ข้าจะให้ไปรวบรวม Zanzil's Mixture อีก" },
        required = { [5807] = { "19:1981551892:1344691922", "รายงานเรื่องเบียร์ Fool's Stout" } },
        steps = { { "19:1981551892:1344691922", "รายงานเรื่องเบียร์ Fool's Stout" } },
    },
    [1137] = { -- News for Fizzle
        title = { "15:954299824:1740475353", "ข่าวให้ Fizzle" },
        objective = { "53:2080362279:500970009", "คุยกับ Fizzle Brassbolts ที่ Shimmering Flats" },
        description = { "359:1158583523:1656086057 N 127:408004016:1909024281", "อินดูเรียมทนความร้อนได้มหัศจรรย์! ข้ามั่นใจว่าใช้กับลูกสูบ Fizzle ได้ แต่ต้องเป็นสินแร่แท้ ไม่ใช่เพียงเกล็ด\n\nต้องขุดสินแร่จากส่วนลึก Uldaman ริมเหนือ Badlands นั่นคือแหล่งแท้จริง\n\nฝากความคิดถึงถึง Fizzle Brassbolts และบอกสิ่งที่ข้าเล่า\n\nเดินทางปลอดภัย {name} คงไม่น่าแปลกถ้าได้พบกันอีก เมื่อ Fizzle รู้เรื่องอินดูเรียม คงส่งเจ้าไป Uldaman หาแน่!" },
        completion = { "N 111:1626171469:1062873725", "{name} กลับมาแล้ว! พบ Martek หรือ? คุยกับเขาไหม? ว่าอย่างไร? ช่วยได้ไหม??\n\nบอกข้า บอกข้า บอกข้า!!" },
    },
    [1175] = { -- A Bump in the Road
        title = { "18:72875879:553529729", "สิ่งกีดขวางบนทางแข่ง" },
        objective = { "125:1786795156:1922563064", "ฆ่า Saltstone Basilisk 10 ตัว, Saltstone Crystalhide 10 ตัว และ Saltstone Gazer 6 ตัวให้ Trackmaster Zherin ที่ Shimmering Flats" },
        description = { "417:784743510:2043851988", "หลังรถแข่ง Red Thunder ของกอบลินชนบาซิลิสก์ครั้งใหญ่ Kronkrider จ้างข้าดูแลสนาม ไม่รู้ว่าสัตว์บนที่ราบกินอะไรถึงโตนัก แต่ต้องลดจำนวนอย่างระวัง ไม่ให้เดินเข้าสนามระหว่างแข่ง\n\nเอาอย่างนี้ ถ้าอยากหาเงินสักหน่อย ก็ออกไปกำจัดบาซิลิสก์แถวนี้" },
        progress = { "117:659733079:1288803928", "แค่เก็บซากรถก็แย่พอแล้ว ไม่อยากต้องคุ้ยออกจากชิ้นส่วนสัตว์ไหม้ด้วย" },
        completion = { "187:163545386:1440004348", "หวังว่าเจ้าไม่ได้ฆ่าบาซิลิสก์บนสนาม! ซากใช้เวลานานกว่าจะสลายกลางแดด ข้าไม่อยากแบกพลั่วไปเก็บกวาด" },
        objectiveLabels = {
            monster = { ["Saltstone Basilisk slain"] = "ปราบ บาซิลิสก์ Saltstone", ["Saltstone Crystalhide slain"] = "ปราบ บาซิลิสก์หนังผลึก Saltstone", ["Saltstone Gazer slain"] = "ปราบ บาซิลิสก์จ้องตรึง Saltstone" },
        },
    },
    [1176] = { -- Load Lightening
        title = { "15:535795170:752200626", "ลดน้ำหนักบรรทุก" },
        objective = { "63:1174307130:1565470650", "หา Hollow Vulture Bone 10 ชิ้นให้ Pozzik ที่ Shimmering Flats" },
        description = { "500:127205668:877877240", "ในการแข่ง ทุกรายละเอียดสำคัญ! จะปรับกำลังเล็กน้อย คลายขดลวดรับแรงสักนิด หรือลดน้ำหนักโครง ก็ต้องคิดทั้งหมด\n\nเราใช้กระดูกแร้งปรับโครงสร้างรถเล็ก ๆ น้อย ๆ หลายจุด มันสมดุลระหว่างความแข็งแรงกับน้ำหนักได้พอดี และหาเพิ่มง่าย เพราะที่ราบเกลือเต็มไปด้วยแร้ง\n\nนำมาให้ข้า จะจ่ายราคาดี" },
        progress = { "159:1062719298:1632235540", "มีกระดูกให้ข้าไหม? กำลังจะเริ่มลดน้ำหนักชุดบังคับเลี้ยว แต่ไม่อยากแกะโดยไม่มีชิ้นส่วนครบ" },
        completion = { "62:83853536:1469640365 N 1:33:33", "เยี่ยม! ให้ทีมลงมือได้ทันที ขอบใจ {name}!" },
        required = { [5848] = { "19:189443544:1909474129", "กระดูกแร้งกลวง" } },
        steps = { { "19:189443544:1909474129", "กระดูกแร้งกลวง" } },
    },
    [1178] = { -- Goblin Sponsorship
        title = { "18:1172578709:1435696058", "ผู้สนับสนุนทีมกอบลิน" },
        objective = { "28:1908057649:2138584235", "คุยกับ Gazlowe ที่ Ratchet" },
        description = { "503:1023713497:972183474", "ทีมแข่งเราเป็นความภูมิใจของกอบลินทุกแห่ง เจ้าอาจแปลกใจว่ามีใครบ้างช่วยทีมไม่ทางใดก็ทางหนึ่ง\n\nรู้จัก Gazlowe ไหม? เขาตามหาชิ้นส่วนทั่วโลกให้ ถึงกับเคยมาช่วยทำรถคันหนึ่ง!\n\nไม่กี่สัปดาห์ก่อนบอกจะส่งต้นแบบตัวควบคุมเชื้อเพลิงใหม่ แต่ยังไม่มา ปกติเขาตรงเวลามาก... เจ้าไป Ratchet ถามให้หน่อยได้ไหม? ข้าไม่อยากเร่งหรอก แต่พวกโนมกำลังไล่ทัน!" },
        completion = { "369:1658793223:1148673201", "Pozzik ส่งมาหรือ? รู้ไหม ก่อนเกษียณไปทำรถแข่ง เขาเป็นช่างประดิษฐ์ที่ได้รับความเคารพมากที่สุดคนหนึ่งใน Undermine\n\nสิ่งแรกเมื่อเข้าทีมคือพัฒนารถแข่งสองเครื่องยนต์ ธุรกิจอาจเสียประโยชน์ที่เขาไม่ทำงานกับ Tinkers' Union แล้ว แต่ใครสนล่ะ? ไม่มีอะไรเหมือนการแข่ง!" },
    },
    [1179] = { -- The Brassbolts Brothers
        title = { "23:116094753:289692342", "พี่น้อง Brassbolts" },
        objective = { "78:1623180355:1636420999", "นำลังหมวกนิรภัยไปให้ Wizzle Brassbolts ที่ Shimmering Flats" },
        description = { "497:1629346477:2009421827", "เคยได้ยิน Shimmering Flats ไหม? ที่ราบเกลือไกลใน Kalimdor อยู่ใต้หุบผา Thousand Needles เหมาะแข่งมาก เพราะ... มันราบเรียบ!\n\nสหายโนมสองพี่น้องอยู่ที่นั่น กำลังลองรถจรวดใหม่ ได้ยินว่าเร็วมาก! เฮอะ เร็วจนคนขับชนกันเรื่อย ทำตัวเองสมองกระทบกระเทือน\n\nพวกเขาจึงขอหมวก Siege Engine จากข้า แต่มีหน้าที่ที่นี่ เดินทางไปไม่ได้!\n\nเจ้าล่ะ ไปได้ไหม?" },
        progress = { "138:1691323151:410589752", "ระวังเดิน! ระวัง ระวัง ระวัง!! ของพวกนี้ละเอียดอ่อน ถ้าจะชนะทุกอย่างต้องทำงานสมบูรณ์!" },
        completion = { "108:1891190349:1256953809", "อา! Longbeard ส่งเจ้ามาพร้อมหมวกเต็มลัง! เย่!\n\nคราวนี้อาจกล่อมคนขับให้ยอมขับรถเราได้..." },
        required = { [5849] = { "22:1978998616:1062207893", "ลังหมวกกันกระแทก" } },
        objectiveLabels = {
            item = { ["Crate of Crash Helmets"] = "ลังหมวกกันกระแทก" },
        },
    },
    [1180] = { -- Goblin Sponsorship
        title = { "18:1172578709:1435696058", "ผู้สนับสนุนทีมกอบลิน" },
        objective = { "43:1853264246:1455714843", "คุยกับ Wharfmaster Lozgil ที่ Booty Bay" },
        description = { "462:1915809015:1592848729", "กลับมาเรื่องธุระของเจ้า ข้ารู้ว่าสัญญากับ Pozzik จะส่งตัวควบคุมเชื้อเพลิงใหม่ แต่ข้าเองยังไม่ได้รับ Revilgaz ที่ Booty Bay บอกจะส่งมา บางทีมันอาจตกหล่นไป\n\nถ้าจริง เราทำอะไรไม่มาก แต่อย่างน้อยตรวจได้ว่าส่งออกจาก Booty Bay แล้วหรือยัง\n\nไปหา Wharfmaster Lozgil ที่นั่น เขาน่าจะตรวจบันทึกสินค้าได้" },
        completion = { "240:2109140610:2115619384", "ของส่ง Ratchet หรือ? ขอเช็กสมุด...\n\nไม่ ของล่าสุดที่บันทึกว่าส่งไปคือรองเท้า Drizzlik นอกนั้นมีเพียงวัสดุก่อสร้างกับเครื่องมือ ไม่มีชิ้นส่วนแข่งแน่นอน" },
    },
    [1181] = { -- Goblin Sponsorship
        title = { "18:1172578709:1435696058", "ผู้สนับสนุนทีมกอบลิน" },
        objective = { "39:1598442710:1375199002", "คุยกับ Baron Revilgaz ที่ Booty Bay" },
        description = { "48:782908350:2062413419 N 209:1947038673:1054154358", "เกรงว่าข้าช่วยได้เท่านี้ {name} ถ้าจะตามต่อ แนะนำไปหาบารอนเอง หากใครรู้ธุรกิจ Revilgaz ก็คงเป็นเจ้าตัว\n\nเขาอยู่ชั้นบนสุดของโรงเหล้าฝั่งตรงข้ามท่าเรือ" },
        completion = { "199:1700872226:138209052", "โอ้ แน่นอน ข้ารู้ว่าพูดเรื่องอะไร แต่ช่วยไม่ได้ ลูกน้องควรไปเอาแบบตัวควบคุมเชื้อเพลิง แต่กลับมามือเปล่า" },
    },
    [1182] = { -- Goblin Sponsorship
        title = { "18:1172578709:1435696058", "ผู้สนับสนุนทีมกอบลิน" },
        objective = { "67:452970934:1901877914", "นำ Fuel Regulator Blueprints ไปให้ Baron Revilgaz ที่ Booty Bay" },
        description = { "495:1734033922:277103873", "เครื่องจักร Shredder ของ Venture Company แถว Lake Nazferiti ทางเหนือของ Stranglethorn ติดตัวควบคุมเชื้อเพลิงรุ่นใหม่ ข้าว่า Pozzik ใช้ประโยชน์ได้ถ้ามีรายละเอียด แต่น่าเสียดาย Cozzle หัวหน้าคนงานดูฉลาดกว่าที่ข้าประเมิน\n\nเจ้าดูอาจมีโชคหาพิมพ์เขียวมากกว่า ข้ารู้ว่าเก็บในบ้าน แต่แทบแน่นอนว่าล็อกไว้" },
        progress = { "118:1785102724:386836213", "แม้ไม่อยากยอมรับ ทีมโนมที่นั่นเก่งทีเดียว ทีมเราต้องการความได้เปรียบทุกอย่าง" },
        completion = { "180:614752358:109896135", "ให้ข้าคัดลอกพิมพ์เขียวเก็บก่อน แล้วเจ้าค่อยนำไปให้ Pozzik ไม่อยากให้คิดว่าผู้สนับสนุนทอดทิ้งเขา" },
        required = { [5852] = { "25:1966670246:98835266", "แบบพิมพ์เขียวตัวควบคุมเชื้อเพลิง" } },
        steps = { { "25:1966670246:98835266", "แบบพิมพ์เขียวตัวควบคุมเชื้อเพลิง" } },
    },
    [1183] = { -- Goblin Sponsorship
        title = { "18:1172578709:1435696058", "ผู้สนับสนุนทีมกอบลิน" },
        objective = { "72:659557636:710516323", "นำ Fuel Regulator Blueprints ไปให้ Pozzik ที่ Shimmering Flats" },
        description = { "187:170287692:877469128", "พร้อมเดินทางแล้ว ฝากความคิดถึงให้ Pozzik บอกด้วยว่าหากต้องการอะไรอย่าลังเล ข้าจะรอฟังข่าวเขาทำลายสถิติสนามในเร็ววัน!" },
        progress = { "N 50:778896609:171148940", "{name}! ตามหาตัวควบคุมเชื้อเพลิงได้ไหม?" },
        completion = { "147:16800806:1326876392 N 103:736336064:605898211", "ข้าหวังว่าจะประกอบมาแล้ว แต่แบบนี้ก็เปิดโอกาสพิเศษให้ปรับปรุงตั้งแต่ต้น ขอบใจ {name} ข้าจะร่างแบบดีขึ้น สร้างและติดตั้งได้ในไม่ช้า" },
        required = { [5852] = { "25:1966670246:98835266", "แบบพิมพ์เขียวตัวควบคุมเชื้อเพลิง" } },
        steps = { { "25:1966670246:98835266", "แบบพิมพ์เขียวตัวควบคุมเชื้อเพลิง" } },
    },
    [1186] = { -- The Eighteenth Pilot
        title = { "20:220492369:3793864", "คนขับคนที่สิบแปด" },
        objective = { "44:69580481:468180593", "คุยกับ Razzeric ที่ Shimmering Flats" },
        description = { "354:1693331503:1186568290", "ข้าจะยุ่งกับการรวมตัวควบคุมเชื้อเพลิงใหม่เข้ากับแบบรถ แต่ถ้าอยากช่วยทีมอีก ไปคุยกับ Razzeric เขาเป็นคนขับเรา... คนที่สิบแปด หากพูดให้ตรง และชอบดัดแปลงรถเองเล็กน้อย\n\nเขาสติไม่ค่อยดีนัก พยายามอย่าทำหน้าแปลกใจเกินไป" },
        completion = { "11:1539529000:164995864 R 210:1944724253:893435039", "เจ้าเป็น {race} ที่ช่วย Pozzik อยู่ใช่ไหม? ข้าเคยเหมือนเจ้า วิ่งรอบเขตช่าง ช่วยทุกงานที่เขายอมให้ทำ\n\nดูตอนนี้สิ! ยอดคนขับทีมแข่งกอบลิน!" },
    },
    [1187] = { -- Razzeric's Tweaking
        title = { "19:1057460470:2013356850", "การแต่งรถของ Razzeric" },
        objective = { "68:1548220902:2121922837", "เก็บ Seaforium Booster ให้ Razzeric ที่ Shimmering Flats" },
        description = { "474:338443950:1549024307 N 1:33:33", "ข้ารู้ว่า Pozzik เป็นช่างเก่ง แต่เขากลัวเพิ่มพลังเต็มที่แล้วเกาะรถพุ่งไป ข้าไม่กลัว\n\nหลังเขาทำรถเสร็จ ข้าใช้เวลาปรับเอง คลายชุดควบคุม ถอดโครงบางส่วน และเพิ่มพลัง!\n\nข้าสั่ง Seaforium Booster จาก Shreev ที่ Gizmorium ใน Gadgetzan แต่ดูเหมือนเรือเหาะที่ส่งมันตกใน Dustwallow Marsh! ข้าต้องได้มัน {name}!" },
        progress = { "123:182120678:862909139", "ไม่มีแรงส่งเพิ่มแล้วข้าจะเอาหน้าไปไว้ที่สนามได้อย่างไร? ข้าบอกเลยว่าน่าอดสู" },
        completion = { "187:760119876:864050470", "ดูของงามนี่สิ! พลังซีฟอเรียมเต็ม ๆ สิบห้าปอนด์! เมื่อติดข้างรถ ข้าจะวิ่งรอบสนามเร็วพอชนะโนมสองครั้ง!" },
        required = { [5862] = { "17:737532192:1141275897", "เครื่องเร่งกำลัง Seaforium" } },
        steps = { { "17:737532192:1141275897", "เครื่องเร่งกำลัง Seaforium" } },
    },
    [1188] = { -- Safety First
        title = { "12:1196164164:1269159343", "ปลอดภัยไว้ก่อน" },
        objective = { "51:1530023023:2113459241", "นำ Seaforium Booster ไปให้ Shreev ที่ Gadgetzan" },
        description = { "271:1669414837:1898001721", "เดี๋ยว นี่อะไร? Shreev เปิดระบบนิรภัยไว้ มันจะจำกัดพลังที่ข้าดึงจากเครื่องเร่งได้ ข้าบอกให้ถอดออก! แบบนี้ไม่ได้\n\nนำไป Gadgetzan Gizmorium ในทะเลทราย Tanaris ให้ Shreev ถอดออก" },
        progress = { "96:45237531:450825150", "อย่างที่เจ้าคงรู้ Gizmorium ดูแลงานประดิษฐ์ทุกอย่างที่ต้องการได้! มีอะไรให้ช่วย?" },
        completion = { "291:1887578477:1303506875", "มีแต่ Razzeric ที่เห็นของนี้แล้วบอกว่าข้าใส่ตัวล็อกนิรภัย มันเกือบทั้งก้อนเป็นระเบิดซีฟอเรียม ข้าปรับให้ปล่อยพลังส่วนใหญ่ขึ้นเมื่อใช้แล้ว แต่เขาไม่พอใจจนกว่าจะเร่งเกินขีดสุด!" },
        required = { [5862] = { "17:737532192:1141275897", "เครื่องเร่งกำลัง Seaforium" } },
        steps = { { "17:737532192:1141275897", "เครื่องเร่งกำลัง Seaforium" } },
    },
    [1189] = { -- Safety First
        title = { "12:1196164164:1269159343", "ปลอดภัยไว้ก่อน" },
        objective = { "74:1890187847:108710393", "นำ Modified Seaforium Booster กลับไปให้ Razzeric ที่ Shimmering Flats" },
        description = { "284:504732725:1981621741", "เรียบร้อย ข้าทำตาม Razzeric ต้องการแล้ว ฝากเตือนให้ระวังตอนจุด หากพลาดแม้แต่น้อย เขาจะไม่ได้พุ่งไปข้างหน้า แต่เหลือเป็นรอยไหม้บนสนาม\n\nถ้าเกิดขึ้นก็น่าเสียดาย ใครรู้ว่าคนขับคนที่สิบเก้าจะเก่งไหม?" },
        progress = { "137:458458690:639078366", "เชื่อไหมว่า Pozzik ใส่ถังทรายไว้บนรถ? จะทำความเร็วสูงสุดได้อย่างไรถ้ามีถังทรายใต้เบาะ?" },
        completion = { "166:1043158603:389770307", "แบบนี้สิ! อยากเห็นแววตาโนมตอนข้าจุดเจ้านี่จริง ๆ\n\nเสียดายที่คงยุ่งกับการทำสถิติสนามใหม่!" },
        required = { [5865] = { "26:1094202181:1185145170", "เครื่องเร่งกำลัง Seaforium ดัดแปลง" } },
        steps = { { "26:1094202181:1185145170", "เครื่องเร่งกำลัง Seaforium ดัดแปลง" } },
    },
    [1190] = { -- Keeping Pace
        title = { "12:111710534:1955888309", "ไล่ตามให้ทัน" },
        objective = { "92:723297900:634355583", "ให้ Zamek ล่อความสนใจ แล้วขโมยแบบของ Rizzle ให้ Pozzik ที่ Shimmering Flats" },
        description = { "446:1327598290:514460753", "พี่น้อง Brassbolts ค้นพบวัสดุก่อสร้างใหม่ นั่นเป็นคำอธิบายเดียวที่สมเหตุผล รถเร็วขึ้น แต่แบบกับข้อมูลอื่นที่เก็บจากการวิ่งเหมือนเดิมหมด\n\nสิ่งที่รู้คือ Rizzle Brassbolts หมกมุ่นกับแบบการค้นพบใหม่แทบตลอด\n\nZamek ล่อความสนใจให้เจ้าได้ เพื่อขโมยแบบมา" },
        completion = { "106:455286476:155979810", "ม้วนบันทึกและแบบที่เขียนอย่างเร่งรีบ เกี่ยวกับการถลุงวัตถุดิบบางอย่าง" },
    },
    [1194] = { -- Rizzle's Schematics
        title = { "19:1654583141:1749907743", "แบบแปลนของ Rizzle" },
        objective = { "67:1466640144:2094152805", "นำ Sample of Indurium Ore ไปให้ Pozzik ที่ Shimmering Flats" },
        description = { "362:2042195200:832478139", "แบบแปลน Rizzle อธิบายกระบวนการถลุงสินแร่อินดูเรียม จากลายมือหวัด เห็นได้ว่าสินแร่มาจากแหล่งขุดค้นคนแคระ Uldaman ใน Badlands\n\nบันทึกอื่นส่วนมากเกี่ยวกับคุณสมบัติทนความร้อน\n\nก้อนที่ดูเป็นสินแร่อินดูเรียมยังไม่ถลุงถูกใช้ทับกระดาษแบบไว้" },
        completion = { "330:54374645:1435416702", "อินดูเรียมหรือ? น่าสนใจ... ถ้าทนความร้อนได้อย่างที่ว่า ก็คงอธิบายว่าทำไมโนมถึงทำความเร็วได้ดีขึ้นพักหลัง\n\nตัวอย่างนี้มีค่ามาก ข้าทดสอบบางอย่างได้ แต่ต้องมีเพิ่มจึงจะใช้ประโยชน์ได้จริง" },
    },
    [2769] = { -- The Brassbolts Brothers
        title = { "23:116094753:289692342", "พี่น้อง Brassbolts" },
        objective = { "53:1000151303:1536343523", "คุยกับ Wizzle Brassbolts ที่ Shimmering Flats" },
        description = { "488:1643179920:1115254792", "พบพี่น้อง Brassbolts หรือยัง? พวกเขาอยู่ Shimmering Flats ใน Kalimdor แข่งรถจรวดกับกอบลิน ปกติชนะ ซึ่งไม่น่าแปลก รถกอบลินระเบิดบ่อยจนแทบไม่เข้าเส้นชัย!\n\nแต่ถึงอย่างนั้น พี่น้อง Brassbolts ก็หาทางทำรถให้เร็วขึ้นเสมอ Wizzle บอกว่าต้องการส่วนประกอบหายากมากสำหรับการทดลองต่อไป\n\nเขาคงต้องให้ช่วยหา ไปคุยดูสิ" },
        completion = { "107:895948804:1562985033 C 28:199590047:481246828", "อา อยากช่วยข้าหรือ? เยี่ยม!\n\nข้าต้องการชิ้นส่วนสำหรับการทดลอง และต้องให้ {class} ผู้กล้าเช่นเจ้าช่วยหา!" },
    },
    [5762] = { -- Hemet Nesingwary
        title = { "16:1664245397:85429362", "Hemet Nesingwary" },
        objective = { "57:617769950:106113138", "นำ Kravel's Crate ไปให้ Hemet Nesingwary ที่ Stranglethorn" },
        description = { "463:2133367951:1666101180", "ข้ามีพัสดุสำหรับลูกค้าเก่า คนแคระ Hemet Nesingwary ของใช้เวลาหลายสัปดาห์กว่าจะมา ตอนนี้เขาไปนานแล้ว บอกจะไป Stranglethorn ล่าสัตว์ แต่ฝากเงินให้ส่งของเมื่อทำได้\n\nHemet ร่ำรวย ควรรักษาสัมพันธ์กับคนรวยใช่ไหม? งั้น... อยากส่งให้ข้าไหม?\n\nได้ยินว่าเขามีค่ายใน Stranglethorn ทางเหนือ Grom'gol" },
        progress = { "152:855254758:466612353", "นั่นฝุ่นทะเลทรายบนคอเสื้อหรือ?\n\nอืม... ถ้าจมูกข้าไม่ผิด ไม่ใช่ฝุ่น แต่เป็นเกลือทะเลทราย! ไป Shimmering Flats มาสินะ?" },
        completion = { "44:1745205106:1418345904 N 187:997074510:1086157038", "เยี่ยม พัสดุจาก Koalbeard! ขอบใจ {name} ลังนี้มีกระสุนขนาดพิเศษ ใช้ได้ดีในป่า!\n\nนี่ค่าจ้าง แล้วตาเฒ่า Kravel พักนี้เป็นอย่างไร? พนันว่ายังวางแผนชั่วอยู่..." },
        required = { [14542] = { "14:1150921775:997608189", "ลังของ Kravel" } },
        steps = { { "14:1150921775:997608189", "ลังของ Kravel" } },
    },
    [98155] = { -- Pristine Pesterhide Pelts
        title = { "25:533126076:520655986", "หนัง Pesterhide สมบูรณ์แบบ" },
        objective = { "50:1112146209:873676932", "นำ Pristine Pesterhide Pelt 5 ผืนไปให้ Kristy Grant", amount = { "6:1273960851:929420321 W1 43:1591470776:585497746", "นำ Pristine Pesterhide Pelt {world1} ผืนไปให้ Kristy Grant" } },
        description = { "404:1622912896:1214051736", "ไฮยีนา Pesterhide ใน Thousand Needles มีขนงดงามที่สุด ข้าไม่เคยเห็นสีขนสดเช่นนั้นตลอดการเดินทาง!\n\nข้าอยากส่งหนังกลับไปให้พี่น้องของข้าที่ Stormwind รู้ว่าพวกนางต้องทำของเหลือเชื่อได้\n\nข้าไม่มีประสบการณ์ต่อสู้ จึงจะขอบคุณมากหากเจ้าช่วยเก็บหนัง Pesterhide แทน" },
        completion = { "11:1191658970:1224418299 N 128:372998129:511704652", "ขอบใจ {name}! หนังพวกนี้สภาพสมบูรณ์ทีเดียว คงไม่ง่ายเลยที่จะหาได้มากขนาดนี้ แต่ข้าซาบซึ้งในความพยายามของเจ้ามาก" },
        progress = { "144:1004216371:1306679293", "เจ้าเก็บหนังสัตว์มาได้ไหม? Rendow รับปากว่าจะช่วยข้าทำความสะอาดและฟอกหนังเพื่อส่งกลับบ้าน พวกพี่สาวน้องสาวของข้าต้องตื่นเต้นแน่ ๆ" },
        required = { [279472] = { "24:353025055:1102305794", "หนัง Pesterhide สภาพสมบูรณ์" } },
        steps = { { "24:353025055:1102305794", "หนัง Pesterhide สภาพสมบูรณ์" } },
    },
    [1191] = { -- Zamek's Distraction
        title = { "19:1043724085:778164659", "การล่อความสนใจของ Zamek" },
        completion = { "9:783675545:1561106228", "ไปกันเลย!" },
    },
    [1192] = { -- Indurium Ore
        title = { "12:95138830:1307251334", "สินแร่อินดูเรียม" },
        progress = { "333:1016943276:1415440324", "ข้าอยากใช้อินดูเรียมในส่วนต่าง ๆ ของรถแข่ง แต่ต้องใช้สินแร่ดิบมากเพื่อทำชิ้นส่วน\n\nหาสินแร่อินดูเรียมได้ในแหล่งขุดค้น Uldaman ที่ Badlands ข้ามทะเลไป Khaz Modan\n\nโนมมีแหล่งจัดหาของตนแล้ว เราจึงต้องมีของเราเพื่อไล่ให้ทัน" },
        completion = { "90:1795094516:624044851", "ยอดเยี่ยม! ข้าจะให้ทีมเริ่มทำชิ้นส่วนสำหรับการแข่งครั้งหน้าทันที" },
        description = { "333:1016943276:1415440324", "ข้าอยากใช้อินดูเรียมในส่วนต่าง ๆ ของรถแข่ง แต่ต้องใช้สินแร่ดิบมากเพื่อทำชิ้นส่วน\n\nหาสินแร่อินดูเรียมได้ในแหล่งขุดค้น Uldaman ที่ Badlands ข้ามทะเลไป Khaz Modan\n\nโนมมีแหล่งจัดหาของตนแล้ว เราจึงต้องมีของเราเพื่อไล่ให้ทัน" },
        required = { [5833] = { "12:95138830:1307251334", "แร่อินดูเรียม" } },
        objectiveLabels = {
            item = { ["Indurium Ore"] = "แร่อินดูเรียม" },
        },
    },
    [98156] = { -- Packaged Pristine Pelts
        title = { "23:1989618510:2010873995", "ห่อหนังสมบูรณ์แบบ" },
        objective = { "54:211506761:244632397", "นำ Package of Pristine Pelts ไปให้ Kimberly Grant" },
        description = { "N 399:1335159495:517645550", "{name} เจ้าช่วยข้ามามาก จนไม่อยากรบกวนอีก คงอีกพักกว่าจะกลับบ้าน Stormwind ได้ ไม่ทราบว่าจะช่วยนำหนังเหล่านี้ไปให้พี่น้องแทนข้าได้ไหม?\n\nข้ามั่นใจว่าเจ้ามีโอกาสกลับก่อน โปรดนำหนังไปให้ Kelly กับ Kimberly พี่น้องของข้าที่ Stormwind ปกติพบได้ที่ Park" },
        completion = { "302:1835117807:1006172996", "นี่มาจากพี่น้องของเราหรือ? เราไม่ได้ข่าวนางมาพักหนึ่งแล้ว หวังว่านางจะสบายดี\n\nโอ้โฮ ขนของหนังพวกนี้สีสวยจริง ๆ! ข้ากับ Kelly จะใช้ให้เกิดประโยชน์แน่นอน\n\nขอบใจที่เดินทางมาไกล ดีใจที่ได้รู้ว่า Kristy ยังสบายดีและคิดถึงพวกเรา" },
    },
    [616] = { -- The Haunted Isle
        title = { "16:1808608863:995959837", "เกาะผีสิง" },
        objective = { "39:1598442710:1375199002", "คุยกับ Baron Revilgaz ที่ Booty Bay" },
        description = { "379:1926104912:1564817843", "Baron Revilgaz ให้ข้าคอยฟังข่าวลือเรื่องแปลกผิดที่ผิดทางใน Booty Bay และ Stranglethorn ปกติข้าไม่เชื่อเรื่องผีนัก แต่ได้ยินกะลาสีในโรงเหล้าพูดถึงเกาะผีสิงนอกชายฝั่ง ว่ามีธาตุน้ำกับผีก็อบลินคลุ้มคลั่ง\n\nหากเจ้าจะไปคุยกับ Revilgaz ช่วยเล่าเรื่องนี้ให้เขาฟังได้ไหม?" },
        completion = { "262:1001016149:1617490558", "น่าสนใจ จำได้ว่าเคยอ่านหนังสือเมื่อนานมาแล้ว บอกว่า...\n\nอา ใช่ ตำนานโทรลล์ หากข่าว Krazek เป็นจริง ข้าอาจได้เพิ่ม Stone of the Tides ในชุดสะสมวัตถุโบราณและโบราณวัตถุเร็ว ๆ นี้" },
    },
    [1492] = { -- Wharfmaster Dizzywig
        title = { "20:2008507047:308867970", "นายท่า Dizzywig" },
        objective = { "58:492811459:174877894", "นำ Secure Crate ไปให้ Wharfmaster Dizzywig ใน Ratchet" },
        description = { "328:661612701:266629914", "ข้าต้องส่งลังบรรจุน้ำยา วัตถุดิบปรุงยา และของอื่นให้ผู้ร่วมงานในโลกเก่า ข้าแทบไม่มีเวลาพาไปถึงท่าเรือ Ratchet ด้วยตนเอง และคาราวานขบวนสุดท้ายก็ออกไปแล้ว\n\nถ้าไหว ช่วยนำไปให้ Wharfmaster Dizzywig ที เขาจะดูแลให้มันได้ขึ้นเรือลำต่อไปที่มุ่งสู่ Blackwater Cove" },
        progress = { "80:1703983382:1078801776", "จะโดยสารเรือลำหน้า หรือมีของอยากส่งขึ้นเรือหรือ?" },
        completion = { "225:1211990914:135926047 C 1:46:46", "ลังไม่ใหญ่นัก ใช่ ข้าน่าจะหาที่บนเรือให้ได้ เรือจะออกตามน้ำขึ้นครั้งหน้า หวังว่าทันใจนะ? ดีมาก ให้ข้าลงสมุดบัญชีก่อน\n\nเรียบร้อยแล้ว! ขอให้เป็นวันที่ดี {class}" },
        required = { [6462] = { "12:1055211849:38830540", "ลังที่ปิดแน่น" } },
        steps = { { "12:1055211849:38830540", "ลังที่ปิดแน่น" } },
    },
    [98738] = { -- Blessings of the Great Windborne Cat Spirit
        title = { "43:756711255:1354635826", "พรแห่งวิญญาณแมวล่องลมผู้ยิ่งใหญ่" },
        objective = { "18:408344685:1120416534", "คุยกับ Dendrite" },
        description = { "359:998793065:1256485949", "เมื่อเจ้ารับพรของข้าแล้ว จงกลับไปหา Dendrite เขาจะชี้นำเจ้าต่อไป\n\nน่าเสียดายที่ตอนนี้ข้ายังมีสิ่งให้สอนเจ้าไม่มากนัก หวังว่าสักวันเจ้าจะแวะมาหาข้าที่ Zephras อีก ข้าสัมผัสได้ถึงแววความสามารถในตัวเจ้า ชาว shen'dorei รุ่นเยาว์\n\nขอให้เงาซ่อนตัวเจ้าเสมอ ให้ศัตรูตกเป็นเหยื่อกงเล็บของเจ้าโดยง่าย และให้สายลมนำทางทุกก้าว" },
        completion = { "468:890423382:569112156", "เมื่อเจ้าเข้าใกล้ Dendrite ทำท่าทางกับอากาศว่างเหนือศีรษะอีกครั้ง ออร่าพลังอีกสายปกคลุมร่างเขา และเขายิ้มเล็กน้อย\n\nข้าสัมผัสได้ถึงไหวพริบและความดุร้ายของแมวในตัวเจ้า ซึ่งยังไม่มีตอนข้าส่งเจ้าไปพบ Great Cat Spirit จากดวงตาของเจ้า ข้าเห็นว่าบัดนี้เจ้าเข้าใจการลอบเร้นและความรวดเร็วที่จำเป็นต่อการรับธรรมชาตินี้แล้ว\n\nตอนนี้เจ้าสามารถเรียนรู้ที่จะรวบรวมไหวพริบ รับธรรมชาติที่แท้จริงของแมว และเรียกพลังจากวิญญาณของมันได้แล้ว", variants = { { "470:843412361:319393642", "<เมื่อเจ้าเข้าใกล้ Dendrite ทำท่าทางกับอากาศว่างเหนือศีรษะอีกครั้ง ออร่าพลังอีกสายปกคลุมร่างเขา และเขายิ้มเล็กน้อย>\n\nข้าสัมผัสได้ถึงไหวพริบและความดุร้ายของแมวในตัวเจ้า ซึ่งยังไม่มีตอนข้าส่งเจ้าไปพบ Great Cat Spirit จากดวงตาของเจ้า ข้าเห็นว่าบัดนี้เจ้าเข้าใจการลอบเร้นและความรวดเร็วที่จำเป็นต่อการรับธรรมชาตินี้แล้ว\n\nตอนนี้เจ้าสามารถเรียนรู้ที่จะรวบรวมไหวพริบ รับธรรมชาติที่แท้จริงของแมว และเรียกพลังจากวิญญาณของมันได้แล้ว" } } },
    },
    [92482] = { -- The Way of the Hunter
        title = { "21:1267977165:884801850", "วิถีแห่งพราน" },
        objective = { "78:1858100710:1024290054", "อ่าน Scribbled Note แล้วไปคุยกับ Tai'ree Farsight ที่ Thendal Grove" },
        description = { "223:1580025222:29680551", "ระหว่างที่เจ้าออกไปจัดการปัญหาพวก vuldren ครูฝึกพรานประจำหมู่บ้านของเรา Tai'ree Farsight ได้ฝากจดหมายฉบับนี้ไว้ให้เจ้า นางอยู่ตรงโน้น ใกล้ใจกลางหมู่บ้าน อ่านจดหมายแล้วไปหานางเถิด" },
        completion = { { "363:1069748051:459259558", "15:1452235458:858098057 N 338:865206237:1626503406", "15:1452235458:858098057 C 338:865206237:1626503406", "15:1452235458:858098057 R 338:865206237:1626503406" }, "เส้นทางของนักผจญภัยเต็มไปด้วยอันตราย ผู้ที่จะเอาตัวรอดในแดนป่าได้ต้องมีประสาทสัมผัสเฉียบคมและไหวพริบฉับไวที่สุด เมื่อมองเจ้า ข้าก็นึกถึงตัวเองในวันที่ยืนอยู่ต่อหน้าอาจารย์เมื่อหลายปีก่อน ข้าเชื่อว่าเจ้ามีคุณสมบัติพร้อม แต่ท้ายที่สุด ทุกอย่างขึ้นอยู่กับตัวเจ้าเอง\n\nหากพร้อมจะก้าวต่อไป ก็มาคุยกับข้าอีกครั้ง", variants = { { "359:711481146:430056203", "เส้นทางของพรานเต็มไปด้วยอันตราย ผู้ที่จะอยู่รอดในแดนป่าได้ต้องมีประสาทสัมผัสเฉียบคมและตอบสนองได้ฉับไว เมื่อมองเจ้า ข้าก็นึกถึงตัวเองในวันที่ยืนอยู่ต่อหน้าอาจารย์เมื่อหลายปีก่อน ข้าเชื่อว่าเจ้ามีคุณสมบัติพร้อม แต่ท้ายที่สุด ทุกอย่างขึ้นอยู่กับตัวเจ้าเอง\n\nหากอยากก้าวต่อไป ก็มาคุยกับข้าอีกครั้ง" } } },
        progress = { "29:1807670663:179832060", "<Tai'ree พยักหน้าให้เจ้าสั้น ๆ>" },
        required = { [282421] = { "14:1831237112:101819917", "บันทึกเขียนหวัด" } },
        steps = { { "14:1831237112:101819917", "บันทึกเขียนหวัด" } },
    },
    [92485] = { -- A Student of Nature
        title = { "19:1083444501:327978203", "ศิษย์แห่งธรรมชาติ" },
        objective = { "76:1788497624:1969066587", "อ่าน Folded Parchment แล้วไปคุยกับ Xyton Silverwind ที่ Thendal Grove" },
        description = { "290:1637485034:1920799970", "ระหว่างที่เจ้าออกไปจัดการปัญหาพวก vuldren ครูฝึกดรูอิดประจำหมู่บ้านของเรา Xyton Silverwind ได้ฝากจดหมายฉบับนี้ไว้ให้เจ้า อ่านโดยเร็วที่สุด แล้วไปหา Silverwind ที่ชั้นล่างของต้นไม้ใหญ่ด้านหลังข้า\n\nจงตั้งใจฟังคำพูดและคำแนะนำของเขา เขาสอนเจ้าได้อีกมาก" },
        progress = { "57:88661843:44658437", "ยินดีต้อนรับ ข้าคือ Xyton Silverwind ผู้รักษาภูมิปัญญาดรูอิด" },
        completion = { "436:770031962:951057394", "พืชพรรณและสรรพสัตว์บน Zephras Isle ประกอบกันเป็นสายใยแห่งชีวิตอันอุดมสมบูรณ์ ระบบนิเวศต้องอาศัยความสมดุลอยู่เสมอเพื่อรักษาความกลมกลืนของธรรมชาติ และพวกเราดรูอิดคือผู้ดูแลความสมดุลนั้น ข้าเห็นศักยภาพในตัวเจ้ามากมาย แต่เส้นทางนี้ไม่ง่าย เจ้าจะต้องมีผู้ชี้แนะระหว่างเติบโตในฐานะศิษย์แห่งเขี้ยว กรงเล็บ ขนนก และกิ่งไม้\n\nหากพร้อมจะก้าวต่อไป ก็มาคุยกับข้าอีกครั้ง" },
        required = { [282420] = { "16:1749780039:405030047", "แผ่นหนังพับ" } },
        steps = { { "16:1749780039:405030047", "แผ่นหนังพับ" } },
    },
    [94006] = { -- The Great Ursera Spirit
        title = { "23:1158166174:2106338304", "มหาวิญญาณ Ursera" },
        objective = { "59:89789752:537844158", "ไปคุยกับ Urs'endris ใกล้น้ำตกทางตะวันออกเฉียงเหนือของ Valanaar" },
        description = { "11:927657569:725753248 N 490:808374877:905720302", "สวัสดี {name} การศึกษาวิถีดรูอิดของเจ้าก้าวหน้ามากพอแล้ว ข้าคิดว่าถึงเวลาที่เจ้าจะได้พบหนึ่งในมหาวิญญาณซึ่งอาศัยอยู่บน Zephras แห่งนี้ Urs'endris เป็นวิญญาณที่ทรงปัญญาและสูงส่ง เขาสอนดรูอิดให้แปลงเป็นร่าง ursera มาหลายชั่วอายุคนแล้ว น่าเสียดายที่ดินแดนของเขาเริ่มเสื่อมสลายและร่วงหล่นลงสู่ท้องฟ้า เช่นเดียวกับอีกหลายพื้นที่ของ Zephras\n\nหากจะไปพบเขา ให้เดินทางไปทางตะวันออกเฉียงเหนือ ใกล้น้ำตกใต้เงาของ Shrine of Akir เขาน่าจะให้คำแนะนำเจ้าเพิ่มเติมได้" },
        completion = { "76:1920119534:579709902", "เจ้าปรารถนาจะเดินตามวิถีแห่งกรงเล็บหรือ เด็กน้อย? ดี เรามาคุยกันเถอะ" },
    },
    [94638] = { -- Strength and Mercy
        title = { "18:1888682521:566374672", "พละกำลังและความเมตตา" },
        objective = { "49:386518122:315372969", "ตามหาและสังหาร Ur'endra ใน Shen'dar Highlands" },
        description = { "502:1707130413:2087954529", "เจ้ามาหาข้าด้วยความหวังจะเรียนรู้การแปลงเป็นร่างที่ทรงพลัง ข้ามีภารกิจให้เจ้าทำ แม้มันจะทำให้ข้าหนักใจก็ตาม\n\nUr'endra คู่ของข้าเสียสติไปแล้ว และเริ่มทำร้ายพวกเดียวกันเอง เมื่อขาดเวทมนตร์แห่งสายลม สิ่งมีชีวิตมากมายก็เริ่มสูญเสียตัวตน... รวมถึง Ur'endra ด้วย นางทำรังอยู่ในถ้ำทางตะวันตกของที่นี่ ในแนวหน้าผาตามเขตแดนระหว่าง Shen'dar Highlands กับ Gustberry Lowlands\n\nจงยุติความทุกข์ทรมานของนาง แล้วข้าจะมอบพรแก่เจ้า" },
        completion = { "196:2122622147:1912485539 C 203:1308834783:343080040", "การสูญเสียนางทำให้ข้าเจ็บปวดเหลือคณา แต่เพื่อรักษาสมดุล จำต้องเป็นเช่นนี้ เจ้าได้แสดงให้เห็นว่ามุ่งมั่นจะเดินหน้าต่อ แม้ต้องแลกด้วยการสูญเสียอันแสนสาหัส\n\nเจ้าทำได้ดี {class} ข้าจะมอบพรให้เจ้าแปลงเป็นร่างของเผ่าพันธุ์ข้า จงเป็นแสงนำทางแก่ผู้ที่หมดแรงจะสู้ต่อ และคุ้มครองผู้ที่ต้องการความช่วยเหลือ\n\nไปเถิด เด็กน้อย จงเดินตามวิถีแห่งกรงเล็บ" },
        progress = { "101:1560102535:322077778", "สิ่งที่ข้าขอให้เจ้าทำนั้นยากนัก จงรวบรวมความกล้า แล้วกลับมาหาข้าเมื่อทำสำเร็จ" },
        objectiveLabels = {
            monster = { ["Ur'endra slain"] = "ปราบ Ur'endra" },
        },
    },
    [94911] = { -- Child of Nature
        title = { "15:1945999327:2129349648", "บุตรแห่งธรรมชาติ" },
        objective = { "44:2087419694:1066591252", "ไปคุยกับ Turak Runetotem ที่ Thunder Bluff" },
        description = { "17:1545238973:664863442 R 462:1365708842:717111600", "สวัสดี {race} รุ่นเยาว์ ข้าเห็นว่าเจ้ามีแววในศาสตร์แห่งดรูอิด มีผู้หนึ่งในเมือง Thunder Bluff ที่เจ้าน่าจะไปพูดคุยด้วย เขาชื่อ Turak Runetotem เขาจะสอนวิธีเดินทางไปยัง Moonglade ฐานที่มั่นของ Cenarion Circle บน Kalimdor\n\nที่นั่นจะต้อนรับเจ้า และเหล่าดรูอิดแห่งคณะจะถ่ายทอดความรู้ให้เจ้า\n\nดังที่ชนชาติของเจ้ากล่าวกัน จงไปพร้อมพรแห่งสายลมเถิด ผู้เยาว์ ข้าขอให้เจ้าโชคดีในการผจญภัย", variants = { { "487:979965031:834437978", "สวัสดี สกายบอร์น รุ่นเยาว์ ข้าเห็นว่าเจ้ามีแววในศาสตร์แห่งดรูอิด มีผู้หนึ่งในเมือง Thunder Bluff ที่เจ้าน่าจะไปพูดคุยด้วย เขาชื่อ Turak Runetotem เขาจะสอนวิธีเดินทางไปยัง Moonglade ฐานที่มั่นของ Cenarion Circle บน Kalimdor\n\nที่นั่นจะต้อนรับเจ้า และเหล่าดรูอิดแห่งคณะจะถ่ายทอดความรู้ให้เจ้า\n\nดังที่ชนชาติของเจ้ากล่าวกัน จงไปพร้อมพรแห่งสายลมเถิด ผู้เยาว์ ข้าขอให้เจ้าโชคดีในการผจญภัย" } } },
        completion = { "268:455532187:1594694892", "ไฮเอลฟ์มาคุยกับข้า... ถึง Thunder Bluff เลยหรือ? มีเรื่องให้ประหลาดใจได้ไม่หยุดจริง ๆ\n\nเอาละ ผู้ปั้นสายลม ข้าขอร่วมกับพี่น้องแห่ง Earthen Ring ต้อนรับเจ้าสู่ Azeroth เหล่าดรูอิดแห่ง Cenarion Circle ของเรามีภูมิปัญญาอีกมากจะถ่ายทอดให้เจ้า เด็กน้อยแห่งธรรมชาติ" },
    },
    [94912] = { -- Child of Nature
        title = { "15:1945999327:2129349648", "บุตรแห่งธรรมชาติ" },
        objective = { "42:50134352:474182209", "ไปคุยกับ Sheldras Moontree ที่ Stormwind" },
        description = { "17:1545238973:664863442 C 409:602841747:1492220475", "สวัสดี {class} รุ่นเยาว์\n\nเจ้าเคยได้ยินเรื่อง Cenarion Circle หรือไม่? ข้าคิดว่าคงยัง พวกเขาเป็นคณะเก่าแก่ของผู้ศึกษาธรรมชาติและผู้ฝึกศาสตร์แห่งดรูอิด เช่นเดียวกับเจ้า ในเมือง Stormwind เจ้าจะพบไนต์เอลฟ์นามว่า Sheldras Moontree เขาจะสอนวิธีเดินทางไปยังฐานที่มั่นของ Cenarion Circle บน Kalimdor สถานที่ซึ่งเรียกว่า Moonglade\n\nไปเถิด เจ้ายังต้องเรียนรู้อีกมากหากต้องการกอบกู้บ้านเกิด" },
        completion = { "18:1857541656:1823288723 C 33:1108597361:1120762147 C 199:153955913:1527930793", "สวัสดี สหาย {class} ข้ายินดีที่ได้พบเพื่อนร่วมวิชาชีพ {class} จากหมู่ชาว Skyborne และได้เป็นคนแรก ๆ ที่ต้อนรับเจ้าสู่ Azeroth\n\nข้าคิดว่าเหล่าดรูอิดแห่ง Cenarion Circle จะมีปัญญาอีกมากให้ถ่ายทอดแก่เจ้า บุตรแห่งธรรมชาติ", variants = { { "18:1857541656:1823288723 C 33:1108597361:1120762147 C 16:816410595:840257038 R 175:1702597245:1587470332", "สวัสดี สหาย {class} ข้ายินดีที่ได้พบเพื่อนร่วมวิชาชีพ {class} จากหมู่ชาว {race} และได้เป็นคนแรก ๆ ที่ต้อนรับเจ้าสู่ Azeroth\n\nข้าคิดว่าเหล่าดรูอิดแห่ง Cenarion Circle จะมีปัญญาอีกมากให้ถ่ายทอดแก่เจ้า บุตรแห่งธรรมชาติ" } } },
    },
    [10] = { -- The Scrimshank Redemption
        title = { "25:1382619862:1117255261", "ตามรอย Scrimshank" },
        objective = { "142:1861999384:609748873", "สืบหาชะตากรรมของ Junior Surveyor Scrimshank แล้วพาเขาหรือนำอุปกรณ์สำรวจของเขาไปให้ Senior Surveyor Fizzledowser ที่ Gadgetzan" },
        description = { "495:1368087307:934558285", "โอ้ แย่จริง ๆ! ข้าส่งผู้ช่วยมือหนึ่ง Junior Surveyor Scrimshank ออกไปในทะเลทรายทางตะวันออกเฉียงใต้ของที่นี่ แถวนั้นเราเรียกว่า Gaping Chasm ตอนนี้เขาหายตัวไปแล้ว และรายงานฉบับสุดท้ายของเขาบอกว่ามีแมลงประหลาดพวกนั้นเพิ่มขึ้นในบริเวณที่เขาอยู่ หรือว่าตอนนี้พวกมันจะเข้ายึดพื้นที่สำคัญของทะเลทรายไปถึงสองแห่งแล้ว?\n\nข้าต้องการให้เจ้าไปที่ Gaping Chasm แล้วตามหา Scrimshank ขอร้องล่ะ! ถ้าไม่พบเขา... อย่างน้อยก็หาอุปกรณ์สำรวจของเขามา ข้าเกรงว่าคงเหลืออยู่เพียงเท่านั้นแล้วสำหรับเจ้าคนโชคร้าย" },
        progress = { "97:1589277565:1622150245", "เป็นอย่างไรบ้าง เจ้าได้ข่าวอะไรมาหรือ? ดูเหมือนเจ้าจะผ่านการต่อสู้หนักมา... Scrimshank ยังมีชีวิตอยู่ไหม?" },
        completion = { "488:794218924:666046338", "Scrimshank เป็นก็อบลินหนุ่มที่ดีคนหนึ่ง หวังว่าสิ่งที่เขาบันทึกด้วยอุปกรณ์สำรวจจะช่วยให้ความตายของเขาไม่สูญเปล่า\n\nดูเหมือนว่าแมลงพวกนี้กำลังสร้างปัญหาใหญ่ให้เรา พวกมันฉลาดเป็นกรด และงานวิจัยที่เราทำมาจนถึงตอนนี้ก็เริ่มชี้ว่าพวกมันอาจถูกบางสิ่งจากภายนอกควบคุมอยู่! หากเป็นเช่นนั้น นี่เป็นลางร้ายต่อทั้ง Gadgetzan และทะเลทรายทั้งหมด!" },
        required = { [8593] = { "27:977236455:1480909022", "อุปกรณ์สำรวจของ Scrimshank" } },
        steps = { { "27:977236455:1480909022", "อุปกรณ์สำรวจของ Scrimshank" } },
    },
    [82] = { -- Noxious Lair Investigation
        title = { "26:1414085318:1592841001", "สืบเรื่อง Noxious Lair" },
        objective = { "93:1270261639:697547527", "นำชิ้นส่วนแมลง Centipaar จาก Noxious Lair จำนวนห้าชิ้นไปให้ Alchemist Pestlezugg ที่ Gadgetzan" },
        description = { "463:1016682506:31086503", "เอาล่ะ เรื่องรายงานแมลงพวกนี้... สิ่งที่เรารู้คือพวกมันกำลังดูดน้ำจากแอ่งที่เคยอยู่ตรง Noxious Lair ส่วนที่เราไม่รู้น่ะหรือ ก็ทุกอย่างที่เหลือนั่นแหละ\n\nเรามาหาคำตอบกันก่อนว่าศัตรูคืออะไรกันแน่! ข้าอยากให้เจ้าเข้าไปใน Noxious Lair แล้วเก็บชิ้นส่วนของสัตว์พวกนั้นมา เอาจาก Centipaar ที่นั่นมาห้าชิ้น แล้วนำไปให้ Alchemist Pestlezugg ทดลองดู หากเขาช่วยสืบเรื่องนี้ เราต้องรู้แน่ว่าพวกมันเป็นอะไร!" },
        progress = { "23:458690420:645709724 N 118:62000286:321214375", "เจ้าคือ Junior Surveyor {name} ใช่ไหม? เร็วเข้า ตอนนี้สถานการณ์ร้ายแรงมาก! เจ้ามีชิ้นส่วนแมลงที่ Fizzledowser บอกว่าจะนำมาให้หรือยัง?!" },
        completion = { "438:628658693:2130149503", "ทำได้ดี ข้าจะเริ่มวิเคราะห์เดี๋ยวนี้! แต่ข้าบอกได้ตั้งแต่ตอนนี้เลยว่า... พวกมันไม่เหมือนแมลงชนิดใดที่ข้าเคยเห็น ราวกับว่ามันกำลังถูกพลังจากภายนอกควบคุมอยู่หรืออะไรทำนองนั้น\n\nเจ้าต้องรีบไปคุยกับ Fizzledowser ดูเหมือนมีเหตุฉุกเฉินที่เขาต้องการให้เจ้าช่วยโดยด่วน! ข้าไม่แน่ใจ แต่คิดว่าคงเกี่ยวกับแมลงในทะเลทราย Tanaris ที่เพิ่มขึ้นอีก!" },
        required = { [8587] = { "22:1259970131:189649899", "ชิ้นส่วนแมลง Centipaar" } },
        steps = { { "22:1259970131:189649899", "ชิ้นส่วนแมลง Centipaar" } },
    },
    [110] = { -- Insect Part Analysis
        title = { "20:962299080:1117383244", "วิเคราะห์ชิ้นส่วนแมลง" },
        objective = { "81:1893191650:207279658", "ไปหา Alchemist Pestlezugg ที่ Gadgetzan เพื่อสอบถามผลวิเคราะห์ชิ้นส่วนแมลง" },
        description = { "396:1279571396:1773653863", "ข้าจะใช้เวลาสักหน่อยตรวจอุปกรณ์สำรวจของ Scrimshank... และจัดการข้าวของส่วนตัวของเขาให้เรียบร้อยด้วย ข้ามีลางสังหรณ์ตงิด ๆ ว่านี่คงไม่ใช่ความสูญเสียครั้งสุดท้ายที่เราจะเผชิญจากแมลงพวกนี้\n\nข้าอยากให้เจ้าไปถาม Alchemist Pestlezugg ว่าเขาตรวจชิ้นส่วนแมลงที่เราส่งให้เสร็จหรือยัง ถ้าเสร็จแล้วก็นำผลมาให้ข้า" },
        completion = { "380:714873482:1599479127", "ใช่ ข้ามีผลวิเคราะห์อยู่ตรงนี้แล้ว จะบอกแค่ว่าน่าเป็นห่วงก็คงน้อยไป\n\nเราเชื่อว่าข้อสงสัยแรกของเราถูกต้อง แมลงพวกนี้ถูกพลังจากภายนอกควบคุมอยู่ หากเป็นเช่นนั้น เราก็ไม่ได้กำลังเผชิญเพียงพลังลึกลับอันมหาศาลเท่านั้น แต่ยังเป็นพลังชั่วร้ายด้วย แมลงเหล่านี้ถูกเปลี่ยนให้เป็นผู้ทำลายล้างโดยแท้ ข้าไม่เคยเห็นอะไรเช่นนี้มาก่อน" },
    },
    [113] = { -- Insect Part Analysis
        title = { "20:962299080:1117383244", "วิเคราะห์ชิ้นส่วนแมลง" },
        objective = { "146:2111002922:869332492", "นำรายงานไปให้ Senior Surveyor Fizzledowser ที่ Gadgetzan และให้เขาทำสำเนารายงานให้เจ้าตามที่ Alchemist Pestlezugg ขอไว้" },
        description = { "496:354591718:2071118013", "Senior Surveyor Fizzledowser ต้องเห็นรายงานฉบับนี้ทันที ที่จริง... ทุกคนที่อ่านหนังสือออกควรได้เห็นมัน เรากำลังเผชิญภัยคุกคามร้ายแรง ไม่ใช่แค่ต่อ Tanaris และ Gadgetzan เท่านั้น แต่หากปล่อยไว้ มันจะลามไปทั่วตอนใต้ของ Kalimdor เผลอ ๆ อาจทั่วทั้ง Azeroth ด้วย เพราะยังไม่มีวี่แววว่าเรื่องนี้จะบรรเทาลง\n\nให้ Fizzledowser ทำสำเนารายงานให้เจ้า แล้วนำไปเผยแพร่แก่ฝ่ายของเจ้าได้อย่างอิสระ ทุกคนต้องรู้ถึงภัยนี้!" },
        progress = { "21:116452975:1927112667 N 47:807471873:2077559839", "เป็นอย่างไรบ้าง Junior Surveyor {name} ตาแก่ Pestlezugg ทำรายงานเสร็จหรือยัง?" },
        completion = { "53:610703356:86141457 N 372:1296044964:1139764217", "ขอบคุณที่นำรายงานมาส่ง Junior Surveyor {name} นี่คือค่าจ้างสำหรับการทำงานอย่างขยันขันแข็งให้บริษัทน้ำ Gadgetzan\n\nปกติข้าไม่ค่อยยินดีนักที่จะยกข้อมูลอันมีค่าของเราให้ใครฟรี ๆ ทั้งที่พวกเขาน่าจะจ่ายเงินงาม ๆ เพื่อซื้อมัน แต่ข้ารู้จัก Pestlezugg มาหลายปีแล้ว หากเขาแนะนำให้ทุกคนรับรู้เรื่องนี้ ก็เอาตามนั้น รอสักครู่ ข้าจะทำสำเนาให้เจ้า" },
        required = { [8594] = { "22:1022044375:1634291193", "รายงานวิเคราะห์แมลง" } },
        steps = { { "22:1022044375:1634291193", "รายงานวิเคราะห์แมลง" } },
    },
    [351] = { -- Find OOX-17/TN!
        title = { "15:1521734265:840387985", "ตามหา OOX-17/TN!" },
        objective = { "55:569188851:1221088782", "นำเครื่องส่งสัญญาณขอความช่วยเหลือไปยังหุ่นยนต์นำทางกลับบ้านของ Oglethorpe" },
        description = { "485:954554744:450220935", "เจ้าพบอุปกรณ์โลหะประหลาดรูปร่างคล้ายไข่ เมื่อหมุนปุ่มปุ่มหนึ่ง ไข่ก็เริ่มทำงานและกางออกเป็นกลไกหุ่นยนต์แบบโนม! เสียงหนึ่งดังแทรกคลื่นซ่าออกมาจากภายในไข่หุ่นยนต์\n\n\"ข้าชื่อ Oglethorpe หุ่นยนต์นำทางกลับบ้านของข้าหายไป! ข้าจะให้รางวัลหากเจ้าหามันเจอ! โปรดนำเครื่องส่งสัญญาณนี้ไปหามัน เยี่ยมเลย ตอนนี้ข้าคำนวณพิกัดให้เจ้าได้แล้ว! มันตกใกล้ Gaping Chasm ใน Tanaris!\"" },
        progress = { "365:1190993790:728454488", "ดูเหมือนเจ้าจะพบซากของ... ไก่หุ่นยนต์หรือ? เสียงจากภายในไข่ดังแทรกคลื่นซ่าขึ้นมาอีกครั้ง\n\n\"ใช่แล้ว ทำได้ดีมาก! นี่คือหุ่นยนต์นำทางกลับบ้านของข้าจริง ๆ แต่เซนเซอร์บอกว่าต้องกระตุ้นให้มันเริ่มทำงานเสียก่อน มันจึงจะบินกลับ Booty Bay เพื่อซ่อมแซมได้ เอาเลย ใส่เครื่องส่งสัญญาณลงในตัวหุ่น เครื่องส่งสัญญาณจะจัดการที่เหลือเอง!\"" },
        completion = { "428:447638066:1078374289", "เจ้าใส่ไข่... เครื่องส่งสัญญาณขอความช่วยเหลือ... ลงในไก่... หุ่นยนต์นำทางกลับบ้าน\n\nเสียงครางและเสียงกลไกหมุนดังจากภายใน ขณะที่หุ่นพยายามลุกยืน เมื่อหุ่นเริ่มทำงาน ก็ได้ยินเสียง Oglethorpe อีกครั้ง แต่คราวนี้ดังมาจากตัวหุ่นยนต์\n\n\"อย่างน้อย OOX-17/TN ก็ทำงานแล้ว แต่ต้องซ่อมใหญ่! มันหนักเกินกว่าที่เจ้าจะแบกไหว... แต่ข้าว่าข้ามีแผนแล้ว เจ้าจะช่วยดูแลมันต่ออีกหน่อยได้ไหม?\"" },
        required = { [8623] = { "25:1603383603:1250094578", "เครื่องส่งสัญญาณขอความช่วยเหลือ OOX-17/TN" } },
        steps = { { "25:1603383603:1250094578", "เครื่องส่งสัญญาณขอความช่วยเหลือ OOX-17/TN" } },
    },
    [648] = { -- Rescue OOX-17/TN!
        title = { "17:1367821991:1670422194", "ช่วยเหลือ OOX-17/TN!" },
        objective = { "88:1140288206:780934203", "คุ้มกัน OOX-17/TN ไปยัง Steamwheedle Port แล้วไปรายงาน Oglethorpe Obnoticus ที่ Booty Bay" },
        description = { "493:1141874030:1633677824", "เสียงของโนมดังแทรกคลื่นซ่าออกมาจากหุ่นยนต์อีกครั้ง\n\n\"ข้าต้องย้าย OOX-17/TN ไปยังที่โล่งและปลอดภัย เพื่อเริ่มขั้นตอนเตรียมบินขึ้นซึ่งกินเวลานาน มันมีระบบพรางตัวในตัว แต่ข้าต้องใช้เวลาทางฝั่งนี้เพื่อทำให้ระบบกลับมาใช้งานได้ ข้าต้องการให้เจ้าคุ้มกันหุ่นจากจุดที่มันอยู่ไปยัง... เอาเป็น Steamwheedle Port! ที่นั่นน่าจะเหมาะที่สุด และระยะทางก็นานพอให้ระบบกลับมาทำงาน!\"\n\n\"คุ้มกันมันไปถึงท่าเรืออย่างปลอดภัย แล้วมาคุยกับข้าที่ Booty Bay! Oglethorpe Obnoticus จบการติดต่อ!\"" },
        completion = { "449:405872343:572251743", "โอ้ เจ้าคือผู้ช่วยชีวิต OOX-17/TN ผู้ยิ่งใหญ่นั่นเอง! ข้าไม่รู้จะเริ่มขอบคุณสำหรับความช่วยเหลือของเจ้าอย่างไรดี! หุ่นยนต์นำทางกลับบ้านรุ่นนี้ยังต้องพัฒนาอีกมาก แต่การกู้หุ่นของเจ้าช่วยประหยัดเวลาสร้างใหม่ให้ข้านับไม่ถ้วน รวมทั้งเงินทองอีกมากในการเชื่อมระบบกลับเข้าด้วยกัน!\n\nโปรดเลือกของชิ้นใดชิ้นหนึ่งจากที่ข้ามี หวังว่าเจ้าจะนำมันไปใช้ประโยชน์ได้ ขอบคุณอีกครั้งสำหรับน้ำใจของเจ้า ทั้งข้าและหุ่นยนต์เป็นหนี้บุญคุณเจ้า!" },
        objectiveLabels = {
            event = { ["Escort OOX-17/TN to Steamwheedle Port"] = "คุ้มกัน OOX-17/TN ไปยัง Steamwheedle Port" },
        },
    },
    [992] = { -- Gadgetzan Water Survey
        title = { "22:210359058:650052924", "สำรวจแหล่งน้ำให้ Gadgetzan" },
        objective = { "190:2040792150:2029437902", "ใช้ Untapped Dowsing Widget ใกล้แอ่งน้ำแถว Sandsorrow Watch เมื่อเก็บตัวอย่างแล้ว ให้นำ Tapped Dowsing Widget กลับไปให้ Senior Surveyor Fizzledowser ที่ Gadgetzan" },
        description = { "487:1569367188:1549182831", "บริษัทน้ำ Gadgetzan มีตำแหน่งผู้ช่วยสำรวจชั่วคราวว่างอยู่ หากเจ้าสนใจ!\n\nพวกเร่ร่อนยึดบ่อน้ำของเราไปหมดแล้ว เราจึงต้องหาแหล่งน้ำที่ยังไม่มีใครจับจองมาใช้เพิ่ม! ในทะเลทรายมีน้ำอยู่ แต่มีไว้ให้เฉพาะคนที่ฉลาดพอจะออกสำรวจก่อนเท่านั้น\n\nนำอุปกรณ์สำรวจน้ำนี้ไปเก็บตัวอย่างจากแอ่งน้ำใกล้ Sandsorrow Watch มันอยู่ในสายตาพวกโทรลล์แถวนั้นเลย เสร็จแล้วนำอุปกรณ์ที่เก็บตัวอย่างแล้วกลับมาให้ข้า!" },
        progress = { "30:1987222988:1486764145 N 41:803264064:2104607687", "ยินดีต้อนรับกลับ Junior Surveyor {name}! เจ้าเสร็จภารกิจแล้วหรือยัง?" },
        completion = { "453:1671631104:2145242488", "ว่าอย่างไรนะ? เจ้าโดนเจ้าสัตว์ยั้วเยี้ยที่มีอำนาจชั่วร้ายบางอย่างซุ่มโจมตีหรือ? โอ้ นี่ไม่เป็นผลดีต่อบริษัทน้ำ Gadgetzan เลย ไม่ดีแน่ ๆ...\n\nข้าคงควรบอกเจ้าเรื่องรายงานที่เข้ามาว่า มีสัตว์แมลงประหลาดกำลังดูดน้ำทั่วทะเลทราย ตอนแรกข้าคิดว่าเป็นเรื่องเหลวไหล แค่พวกเร่ร่อนเราก็มีปัญหามากพอแล้ว ข้าจึงนึกว่าเป็นลูกไม้อะไรของพวกมันอีก อย่างน้อยตอนนี้เราก็รู้แล้ว!" },
        required = { [8585] = { "21:787397447:1372371276", "เครื่องสำรวจที่เก็บตัวอย่างน้ำแล้ว" } },
        steps = { { "21:787397447:1372371276", "เครื่องสำรวจที่เก็บตัวอย่างน้ำแล้ว" } },
    },
    [1560] = { -- Tooga's Quest
        title = { "13:992197517:627379571", "ภารกิจของ Tooga" },
        objective = { "43:869436822:761148639", "นำทาง Tooga กลับไปหา Torta ภรรยาของเขา" },
        description = { "207:938622226:1480508297", "ข้าหลงทางจนไปไหนไม่ถูกแล้ว!\n\nTorta ภรรยาของข้าส่งข้าออกไปหาอาหารเย็น และข้าคงเลี้ยวผิดตรงไหนสักแห่ง\n\nเจ้าช่วยนำทางข้ากลับไปหา Torta ได้ไหม? นางรออยู่ทางใต้ของ Steamwheedle Port ไม่ไกลนัก" },
        progress = { "15:2071574281:1219224799", "Tooga อยู่ที่ไหน?" },
        completion = { "111:899529169:1978960155", "ตกลงว่าเขาหาทางกลับมาเองไม่ได้สินะ? ก็ว่าอยู่แล้ว\n\nเอาเถอะ ข้าว่าเจ้าสมควรได้อะไรตอบแทนที่ต้องลำบาก..." },
        objectiveLabels = {
            event = { ["Lead Tooga to Torta"] = "พา Tooga ไปหา Torta" },
        },
    },
    [1690] = { -- Wastewander Justice
        title = { "19:643678081:1873435592", "ลงทัณฑ์พวก Wastewander" },
        objective = { "112:1067766215:657048556", "กำจัด Wastewander Bandit กับ Wastewander Thief อย่างละ 10 คน ทางตะวันออกของ Gadgetzan แล้วกลับไปรายงาน Chief Engineer Bilgewhizzle" },
        description = { "490:696468827:1093423309", "เจ้าน่ะ! ถึงเวลามาช่วยงานใหญ่ให้บริษัทน้ำ Gadgetzan แล้ว\n\nพวกเร่ร่อน Wastewander ในทะเลทราย Tanaris ยึดบ่อน้ำไปเกือบทั้งหมด! หากเราเข้าไปใช้ไม่ได้ น้ำของเราจะหมดในเวลาไม่นาน ถ้าเจ้าอยากให้พวกเราชื่นชม ก็ช่วยนำความยุติธรรมไปถึงพวกเร่ร่อนนั่น!\n\nมุ่งไปทางตะวันออก กำจัด Wastewander Bandit กับ Wastewander Thief อย่างละสิบคน แล้วรีบกลับมารายงานข้า ความยุติธรรมไม่คอยมนุษย์คนใด... ก็อบลินคนใด... ช่างเถอะ รีบไปจัดการเสีย!" },
        progress = { "131:1070035942:266687527", "กลับมาเร็วเสียจริง! หวังว่าเจ้าจะมอบความยุติธรรมแบบก็อบลินให้ Wastewander Bandit กับ Wastewander Thief ตามที่ข้าขอแล้วนะ!" },
        completion = { "316:871992581:1204295728", "นี่สิที่ข้าเรียกว่าประสิทธิภาพ! เจ้าได้ลดจำนวนพวกเร่ร่อนลงมากพอให้เราเริ่มคิดหาวิธีชิงบ่อน้ำกลับคืนแล้ว\n\nบริษัทน้ำ Gadgetzan ขอบคุณสำหรับความช่วยเหลือของเจ้า แต่เรายังจัดการกับพวกเร่ร่อนชั่วนั่นไม่จบ ฟังให้ดี นี่คือสิ่งที่เราต้องทำต่อ..." },
        objectiveLabels = {
            monster = { ["Wastewander Bandit slain"] = "ปราบ โจร Wastewander", ["Wastewander Thief slain"] = "ปราบ หัวขโมย Wastewander" },
        },
    },
    [1691] = { -- More Wastewander Justice
        title = { "24:410345600:146350399", "ลงทัณฑ์พวก Wastewander ต่อ" },
        objective = { "134:1813759631:1933612788", "กำจัด Wastewander Shadow Mage 10 คน, Wastewander Rogue 8 คน และ Wastewander Assassin 6 คน ให้ Chief Engineer Bilgewhizzle ที่ Gadgetzan" },
        description = { "488:640519251:163685835", "คราวนี้เราต้องการให้เจ้าไปจัดการพวกเร่ร่อน Wastewander ระดับที่แข็งแกร่งขึ้น เจ้าทำได้ดีมาตลอด แต่หากเราจะชิงบ่อน้ำคืน ก็ควรเหลือพวกเร่ร่อนให้ต้องต่อสู้น้อยที่สุดเท่าที่จะทำได้!\n\nครั้งนี้เราต้องการให้เจ้ากำจัดพวกโจร นักลอบสังหาร และจอมเวทเงาของมัน เจ้าจะพบพวกมันทางตะวันออกและตะวันออกเฉียงใต้ของที่นี่\n\nข้าจะไม่โกหกเจ้า พวกมันร้ายกาจทีเดียว แต่ถ้าเจ้าช่วยทำเรื่องนี้ เราก็จะใกล้ชิงสิ่งที่เป็นของเราโดยชอบธรรมกลับคืนได้แล้ว!" },
        progress = { "160:1598235374:2099891407", "เป็นอย่างไร เจ้าจัดการพวกเร่ร่อนตามที่ข้าขอได้หรือยัง? บริษัทน้ำ Gadgetzan กำลังวางแผนโดยอาศัยความสำเร็จของเจ้าอยู่นะ อย่าทำให้เราผิดหวังล่ะ..." },
        completion = { "16:538203699:1485421695 N 298:1411305711:175120445", "เยี่ยมยอดจริง ๆ {name}... เยี่ยมยอด! เจ้าได้ลดจำนวนพวกเร่ร่อนลงจนเราบุกเข้าไปสู้กับมันได้แล้ว!\n\nหากยังไม่ได้คุย ก็ไปหา Spigot Operator Luglunket ที่นี่ เขาจ่ายค่าหัวให้ถุงน้ำ Wastewander ที่เจ้าอาจเก็บได้ระหว่างนำความยุติธรรมไปถึงพวกเร่ร่อนนั่น!" },
        objectiveLabels = {
            monster = { ["Wastewander Rogue slain"] = "ปราบ โจรลอบเร้น Wastewander", ["Wastewander Assassin slain"] = "ปราบ นักฆ่า Wastewander", ["Wastewander Shadow Mage slain"] = "ปราบ จอมเวทเงา Wastewander" },
        },
    },
    [1707] = { -- Water Pouch Bounty
        title = { "18:225525763:284143897", "รางวัลแลกถุงน้ำ" },
        objective = { "76:1599776753:1440930378", "นำ Wastewander Water Pouch 5 ถุงไปให้ Spigot Operator Luglunket ที่ Gadgetzan" },
        description = { "10:1724938855:1235015449 N 447:1089235320:1557190740", "สวัสดี {name} ข้าชื่อ Luglunket เรามีงานสำคัญให้เจ้าทำ หากเจ้าพร้อม! ไชโย!\n\nสำหรับผู้ดูแลก๊อกน้ำมากประสบการณ์อย่างข้า ไม่มีอะไรน่ายินดีไปกว่าการรับถุงน้ำ Wastewander ที่เจ้าเก็บได้จากทะเลทราย นั่นเป็นน้ำของพวกเราอยู่แล้ว พวกเร่ร่อนแค่ขโมยไปเท่านั้น! บริษัทน้ำ Gadgetzan จะมอบชุดเสบียงอย่างเป็นทางการให้ทุกครั้งที่เจ้าส่งมอบถุงน้ำห้าถุง แต่สิ่งสำคัญที่สุดคือ เจ้ากำลังช่วยให้ Gadgetzan พึ่งพาตนเองได้!" },
        progress = { "134:1451077080:1125949502", "เจ้าได้ถุงน้ำ Wastewander ห้าถุงที่เราต้องการหรือยัง? ถ้าได้แล้ว ชุดเสบียงบริษัทน้ำ Gadgetzan รุ่น 103-XB จะเป็นของเจ้า!" },
        completion = { "196:1549204028:1805910425", "ยอดเยี่ยม ยิ่งเราได้ถุงน้ำกลับคืนมากเท่าไร พวกเราก็ยิ่งห่างไกลจากหายนะมากเท่านั้น! นำมาเรื่อย ๆ ข้าจะให้รางวัลทุกครั้งที่เจ้านำถุงน้ำมาให้ห้าถุง" },
        required = { [8483] = { "23:1472142363:1396764540", "ถุงน้ำของ Wastewander" } },
        steps = { { "23:1472142363:1396764540", "ถุงน้ำของ Wastewander" } },
    },
    [2605] = { -- The Thirsty Goblin
        title = { "18:1887262312:1129344012", "ก็อบลินผู้กระหายน้ำ" },
        objective = { "74:220726772:1218189972", "เก็บ Laden Dew Gland แล้วนำไปให้ Marin Noggenfogger ที่ Gadgetzan" },
        description = { "311:3982677:1498130914 N 30:1458807736:1919572700 N 46:2103979441:568782396", "ข้ามีความคิดหนึ่ง ฟังนะ ข้าได้ยินว่ามีสัตว์ประหลาดที่เรียกว่านักเก็บน้ำค้างอาศัยอยู่ทางตะวันตกเฉียงใต้... และพวกมันเก็บน้ำไว้ในต่อมพิเศษได้\n\nข้าคิดว่าถ้าได้ต่อมแบบนั้นมาสักอัน ข้าคงทำเครื่องดื่มที่ดับความกระหายอันร้ายกาจนี้ได้! เจ้าจะช่วยข้าได้ไหม {name}?\n\nมองหาสวนกระบองเพชรนะ {name} เจ้าจะพบนักเก็บน้ำค้างที่นั่น" },
        progress = { "45:1514238271:445507117", "ได้โปรด บอกทีว่าเจ้าพบนักเก็บน้ำค้างแล้ว?" },
        completion = { "47:439032589:305875352", "โอ้ วิเศษ! ส่งมาเลย ให้ข้าดื่มมันที!" },
        required = { [8428] = { "15:1068477498:1055990868", "ต่อมที่เก็บน้ำค้างไว้เต็ม" } },
        steps = { { "15:1068477498:1055990868", "ต่อมที่เก็บน้ำค้างไว้เต็ม" } },
    },
    [2606] = { -- In Good Taste
        title = { "13:1988078403:98389267", "ปรับรสให้กลมกล่อม" },
        objective = { "65:157001149:585192077", "Marin Noggenfogger ต้องการให้เจ้าไปคุยกับ Sprinkle ที่ Gadgetzan" },
        description = { "457:30565891:1887296159", "แหวะ! นี่มันรสชาติแย่มาก! ความคิดนั้นคงไปไม่รอดแล้ว...\n\nเดี๋ยวก่อน ว่าอย่างไรนะ? อ้อ ข้ารู้แล้ว เจ้าคิดว่าข้าไม่ควรยอมแพ้กับของนี่สินะ เอาล่ะ ก็ได้\n\nเอ่อ... ข้ามีความคิดแล้ว! ยอดเยี่ยม! นำน้ำค้างนี้ไปให้ Sprinkle สหายของข้า นางเป็นแม่ครัวชั้นเยี่ยม บอกนางว่าเรากำลังทำอะไร และอยากให้มันดื่มได้คล่องคอสักหน่อย\n\nข้าหมายถึง ถ้ามันจะรสชาติแย่ขนาดนั้น อย่างน้อยก็ควรมีฤทธิ์อะไรบ้าง... แต่ข้าไม่รู้สึกเลย..." },
        progress = { "68:1109427562:339978308", "ตกลงว่าตาเฒ่า Marin เอาอีกแล้วสินะ? ของผสมขวดนี้ทำจากอะไรล่ะ?" },
        completion = { "121:939416717:202371155", "Marin เป็นคนดีนะ อย่าเข้าใจข้าผิด ข้าแค่อยากบอกว่าเขาออกจะ... แปลกอยู่สักหน่อย\n\nและแน่นอน เขาต้องให้ข้าช่วยอีกแล้ว" },
        required = { [8603] = { "16:228304671:163919116", "น้ำค้างจาก Thistleshrub" } },
        steps = { { "16:228304671:163919116", "น้ำค้างจาก Thistleshrub" } },
    },
    [2641] = { -- Sprinkle's Secret Ingredient
        title = { "28:857081385:1346533727", "ส่วนผสมลับของ Sprinkle" },
        objective = { "80:237957239:1286179841", "Sprinkle ที่ Gadgetzan ต้องการให้เจ้าเก็บ Violet Tragan แล้วนำกลับไปให้นาง" },
        description = { "496:1828808428:1446071502", "เมื่อข้ายังเด็ก พี่น้องของข้าคนหนึ่งเป็นคนทำอาหารทั้งหมด ฝีมือนางแย่เหลือเกิน! บางเมนูข้าแทบกลืนไม่ลง จนกระทั่งข้าพบสิ่งที่ชอบเรียกว่า \"ส่วนผสมลับ\"! ใส่มันลงในอะไรก็ได้ แล้ว... ว้าว! อร่อยขึ้นมาทันที!\n\nเจ้าถามว่ามันคืออะไรหรือ? มันเป็นเห็ดที่เรียกว่า Violet Tragan หากอยากให้ข้าช่วยเปลี่ยนของรสชาติแย่นี่ให้กินได้ จงไปที่ Hinterlands แล้วมองหาทะเลสาบเล็ก ๆ ที่นั่น\n\nอ้อ จำไว้ด้วยว่า Violet Tragan พบได้เฉพาะใต้น้ำเท่านั้น" },
        progress = { "131:967650771:2145263211", "ใต้น้ำในทะเลสาบนั้น เป็นที่เดียวที่จะพบ Violet Tragan หวังว่าเจ้าจะกลั้นหายใจเก่งนะ!" },
        completion = { "18:36461711:868694945 N 49:480721234:878058954", "ใช่เลย {name}!\n\nมันดูน่ากินจนข้าอาจจะ... ฮ่า ๆ หลอกได้แล้ว!" },
        required = { [8526] = { "13:337357206:1878809678", "เห็ด Tragan สีม่วง" } },
        steps = { { "13:337357206:1878809678", "เห็ด Tragan สีม่วง" } },
    },
    [2661] = { -- Delivery for Marin
        title = { "18:1047395095:1233530391", "ของส่งถึง Marin" },
        objective = { "80:580842357:811930256", "Sprinkle ต้องการให้เจ้านำ Violet Powder ไปให้ Marin Noggenfogger ที่ Gadgetzan" },
        description = { "26:1706495626:2130831540 N 51:2070661609:982547510", "นี่คือ Violet Powder {name} นำไปให้ Marin แล้วบอกเขาด้วยว่าเขาติดหนี้บุญคุณข้า!" },
        progress = { "4:1347873283:179389729 N 45:801366340:430521445", "โอ้ {name} ในที่สุดเจ้าก็กลับมา เจ้าเอาอะไรมาให้?" },
        completion = { "94:443380785:354894109", "Violet Powder หรือ? ลองดูก็แล้วกัน อย่างน้อยมันคงทำให้แย่ไปกว่านี้ไม่ได้แล้วล่ะ!" },
        required = { [8528] = { "13:1981858171:1345579646", "ผงสีม่วง" } },
        steps = { { "13:1981858171:1345579646", "ผงสีม่วง" } },
    },
    [2662] = { -- Noggenfogger Elixir
        title = { "19:1116262623:858819585", "น้ำยา Noggenfogger" },
        objective = { "79:1720854555:1681141441", "Marin Noggenfogger ต้องการให้เจ้ากลับมาคุยกับเขาอีกครั้ง หลังจากเขาทำน้ำยาเสร็จแล้ว" },
        description = { "137:1082604017:56676198", "เอาล่ะ ผสมผงนี้ลงในน้ำค้าง\n\nกลับมาคุยกับข้าอีกสักครู่... หลังจากข้าปรุงน้ำยา Noggenfogger อันยอดเยี่ยมจนสมบูรณ์แบบแล้ว!" },
        completion = { "83:879503338:418761582 N 248:334992191:1598969483", "ดื่มนี่สิ! วิเศษที่สุดเลย!!!\n\nข้ารู้อยู่แล้วว่าข้าทำได้... โอ้ ขอบใจอีกครั้งที่ช่วยนะ {name} แต่ช่วยขยับไปด้านข้างสักนิดได้ไหม? เจ้าบังหน้าร้านข้าอยู่! ข้าจะทำเงินเป็นล้านจากน้ำยา Noggenfogger อันยอดเยี่ยมนี้ เป็นล้านเลย!\n\nว่าอย่างไรนะ? Sprinkle บอกว่าข้าติดหนี้บุญคุณนางหรือ? โธ่ Sprinkle นั่นชอบล้อเล่นจริง ๆ!" },
    },
    [2781] = { -- WANTED: Caliph Scorpidsting
        title = { "27:1469471092:1312398073", "ประกาศจับ: Caliph Scorpidsting" },
        objective = { "82:24287067:609843552", "นำศีรษะของ Caliph Scorpidsting ไปให้ Chief Engineer Bilgewhizzle ที่ Gadgetzan" },
        description = { "419:843723280:825031820", "ประกาศจับ: Caliph Scorpidsting!\n\nบริษัทน้ำ Gadgetzan แห่ง Gadgetzan ใน Tanaris จะจ่ายค่าหัวจำนวนมากสำหรับศีรษะของ Caliph Scorpidsting หัวหน้ากลุ่มอาชญากร Wastewander ความผิดของเขารวมถึง:\n\n1. ฆ่าพนักงานบริษัทน้ำ Gadgetzan!\n2. ขโมยทรัพยากรของบริษัทน้ำ Gadgetzan!\n3. ยึดทรัพย์สินของบริษัทน้ำ Gadgetzan!\n\nนำหลักฐานการตายของ Caliph Scorpidsting มาให้ Chief Engineer Bilgewhizzle เพื่อรับรางวัลทันที!" },
        progress = { "4:1517439313:201828457 C 78:1670205434:1888971288", "ใช่แล้ว {class} ข้าเป็นเจ้าหน้าที่ของบริษัทน้ำ Gadgetzan มีอะไรให้ช่วยหรือ?" },
        completion = { "332:980226362:1657221291", "ในที่สุด ความยุติธรรมก็มาถึง! เจ้าสร้างความเสียหายอย่างหนักให้พวกเร่ร่อนชั่วนั่น! เมื่อ Scorpidsting ตายแล้ว นี่อาจเป็นสิ่งที่ทำให้เราขับไล่พวกยึดครองบ่อน้ำของ Gadgetzan ออกไปได้เสียที!\n\nด้วยอำนาจของบริษัทน้ำ Gadgetzan ข้ายินดีมอบค่าหัวนี้ให้เจ้า เจ้าช่วยพวกเราทุกคนไว้มาก" },
        required = { [8723] = { "26:135291058:1816605587", "ศีรษะของกาหลิบ Scorpidsting" } },
        steps = { { "26:135291058:1816605587", "ศีรษะของกาหลิบ Scorpidsting" } },
    },
    [2872] = { -- Stoley's Debt
        title = { "13:666306833:1352362556", "หนี้ของ Stoley" },
        objective = { "39:1263735046:1522185449", "ไปคุยกับ Stoley ที่ Steamwheedle Port" },
        description = { "503:1051308656:1226671594", "Stoley สหายเก่าของข้าติดค้างเหล้ารัมขวดพิเศษกับข้า เขาดูแลบาร์อยู่ที่ Steamwheedle Port ใน Tanaris บน Kalimdor และรับปากว่าเหล้ารัมที่นั่นแรงกว่าอะไรก็ตามที่เราหาได้ใน Booty Bay เขามั่นใจถึงขนาดบอกว่า หากข้าลองแล้วไม่เห็นด้วย เขาจะเพิ่มเงินที่ติดหนี้ข้าเป็นสองเท่า!\n\nแต่ข้าคิดว่าเขาคงไม่มั่นใจเท่าตอนที่เราคุยกันครั้งก่อนแล้ว และตอนนี้คงกลัวที่จะให้เหล้ารัมข้า แต่ข้าไม่ถอยจากเดิมพันหรอก เจ้าลองไปคุยกับเขาแทนข้าหน่อยสิ..." },
        completion = { "175:2040690710:1546918962", "อา เจ้าไปคุยกับ MacKinley มาสินะ?\n\nไม่ใช่อย่างที่เขาคิด! ข้าไม่ได้กลัวที่จะให้เขาดื่ม Steamwheedle Bilge Rum หรอก...\n\nข้าแค่ไม่มีเหล้ารัมจะให้เขา!" },
    },
    [2873] = { -- Stoley's Shipment
        title = { "17:1561243855:456186175", "สินค้าของ Stoley" },
        objective = { "55:439149863:514914151", "นำ Stoley's Shipment ไปให้ Stoley ที่ Steamwheedle Port" },
        description = { "332:1999533704:1518732305", "ข้าติดค้างเหล้ารัมกับ \"Sea Wolf\" MacKinley ที่ Booty Bay เพื่อสะสางเดิมพัน แต่เหล้ารัมข้าหมดแล้ว! Captain Cuergo ขโมยสินค้างวดล่าสุดของข้าไป และเก็บไว้ในเมืองโจรสลัดที่มีกำแพงล้อมทางใต้\n\nหากเจ้าหาเหล้ารัมงวดนั้นเจอแล้วนำกลับมาให้ข้า ข้าก็จะพิสูจน์ให้ MacKinley เห็นว่าเหล้าของ Kalimdor เหนือกว่าของ Booty Bay แบบเทียบกันไม่ติด!" },
        progress = { "33:1973045732:1320830625 N 1:63:63", "เจ้าพบเหล้ารัมของข้าหรือยัง {name}?" },
        completion = { "81:239604121:799208306", "เยี่ยม ขอบใจที่เอาสินค้ากลับมา! ทีนี้ข้ากับ MacKinley ก็สะสางเดิมพันกันได้เสียที" },
        required = { [9244] = { "17:1561243855:456186175", "สินค้าของ Stoley" } },
        steps = { { "17:1561243855:456186175", "สินค้าของ Stoley" } },
    },
    [2874] = { -- Deliver to MacKinley
        title = { "20:579354373:358685519", "ส่งของให้ MacKinley" },
        objective = { "59:763164546:451156094", "นำ Stoley's Bottle ไปให้ \"Sea Wolf\" MacKinley ที่ Booty Bay" },
        description = { "28:353591247:439109310 N 137:2023495731:171512696", "ขอบใจอีกครั้งที่ช่วยนะ {name} นี่คือ Steamwheedle Bilge Rum หนึ่งขวด นำไปให้ MacKinley แล้วเขาจะได้เลิกเชื่ออะไรเพี้ยน ๆ เกี่ยวกับเหล้าของ Booty Bay เสียที" },
        progress = { "29:1619010550:1536618647", "Stoley ยอมส่งเหล้าของข้ามาหรือยัง?" },
        completion = { "239:1684954014:194913758", "อืม ลองนี่หน่อย...\n\nไม่อยากจะเชื่อ! ของนี่มัน... แย่สุด ๆ! เยี่ยมไปเลย!\n\nเอาเถอะ ข้าว่า Stoley เก็บเงินที่ติดหนี้ข้าไว้ได้เลย เขาพูดจริงเรื่อง Steamwheedle Bilge Rum มันข้นเป็นกรวดและแผดเผาราวลาวา!" },
        required = { [9245] = { "15:1161377801:1026671723", "ขวดของ Stoley" } },
        steps = { { "15:1161377801:1026671723", "ขวดของ Stoley" } },
    },
    [2875] = { -- WANTED: Andre Firebeard
        title = { "23:1334763182:1980577753", "ประกาศจับ: Andre Firebeard" },
        objective = { "71:1560319844:759425887", "นำ Andre's Head ไปให้ Security Chief Bilgewhizzle ที่ Steamwheedle Port" },
        description = { "469:1496854445:1771246839", "โจรสลัดชั่ว Andre Firebeard เป็นผู้ต้องหาคดีอาชญากรรมต่อ Steamwheedle และ Gadgetzan\n\nตามคำสั่งสภาผู้ปกครอง ผู้ใดอ่านข้อความนี้ถือว่าได้รับอนุญาตให้ใช้กำลังถึงชีวิตในการจับกุม Andre และผู้สนับสนุนของเขา\n\nมีคำสั่งเพิ่มเติมว่า หาก Andre เสียชีวิตหรือไม่อาจเข้าร่วมการพิจารณาคดีได้ด้วยเหตุอื่น ให้ใช้ศีรษะของเขาเป็นตัวแทนได้ และการส่งมอบศีรษะดังกล่าวแก่ Security Chief Bilgewhizzle ให้ถือเป็นสัญญาที่มีผลผูกพันและใช้ขอรับค่าตอบแทนได้" },
        progress = { "67:1708334443:449977723", "เจ้าดูมึน ๆ นะ ไปอ่านเอกสารกฎหมายของพวกเรามาหรือ?" },
        completion = { "79:969661788:783304138 N 208:188007621:1587986030", "อา ศีรษะของ Andre ตกลงว่าเขาจะมาขึ้นศาลได้เสียทีสินะ!\n\nขอบใจมาก {name} ตอนนี้แค่ลงชื่อให้ข้าตรงนี้ ข้าก็จ่ายค่าจ้างสำหรับงานที่เจ้าทำได้แล้ว\n\nไม่ต้องห่วงตัวหนังสือเล็ก ๆ นั่น ไม่มีพิษภัยอะไรหรอก และ... ข้าว่าคงไม่มีแว่นขยายไหนอ่านตัวเล็กขนาดนั้นได้อยู่แล้ว" },
        required = { [9246] = { "16:308093011:784640497", "ศีรษะของ Firebeard" } },
        steps = { { "16:308093011:784640497", "ศีรษะของ Firebeard" } },
    },
    [2876] = { -- Ship Schedules
        title = { "14:1725939397:1063185811", "ตารางเดินเรือ" },
        objective = { "63:362790960:630928233", "นำเรื่อง Ship Schedules ไปรายงานเจ้าหน้าที่ที่ Steamwheedle Port" },
        description = { "331:291325358:1221778879", "ม้วนเอกสารนี้บันทึกกำหนดการขนส่งสินค้าระหว่าง Steamwheedle Port กับ Booty Bay มีทั้งเที่ยวเรือในอดีตและอนาคต พร้อมชื่อเรือ บางเที่ยวมีเครื่องหมาย X ขนาดใหญ่กำกับอยู่ ส่วนบางเที่ยวมีหมายเหตุอย่าง \"ของปล้นชั้นดี\" และ \"สู้ยาก\" เขียนไว้ข้าง ๆ\n\nคงมีใครบางคนที่ Steamwheedle Port อยากเห็นเอกสารฉบับนี้" },
        progress = { "54:926714677:651703809", "เจ้าดูหอบเชียว มีอะไรจะบอกข้าหรือ?" },
        completion = { "278:831600573:802895123 N 82:321593193:1510605382", "โอ้ นี่ดูเหมือนรายการเรือเข้าออก พร้อมวันเวลาและรายละเอียดที่ถูกต้องครบถ้วน! หากกัปตันเรือโจรสลัดได้มันไป คงปล้นกันสนุกมือ!\n\nเจ้าบอกว่าได้มาจากโจรสลัดหรือ? นั่นเป็นข่าวน่ากังวลทีเดียว...\n\nขอบใจ {name} ข้าดีใจที่เจ้าชิงมันมาจากเขาได้ และดีใจที่โจรสลัดคนนั้นลงไปนอนกินฝุ่นแล้ว!" },
        required = { [9250] = { "13:223970872:614657099", "ตารางเดินเรือ" } },
        steps = { { "13:223970872:614657099", "ตารางเดินเรือ" } },
    },
    [2882] = { -- Cuergo's Gold
        title = { "13:1254212288:2070503418", "ทองของ Cuergo" },
        objective = { "19:1511783387:1845734801", "ตามหาทองของ Cuergo!" },
        description = { "297:503181554:906433933", "แผนที่นี้แสดงแนวชายหาดที่หันสู่ทิศใต้ ด้านล่างมีข้อความเขียนไว้อย่างประณีต...\n\nใต้ Wheedle ลงไป\nทางใต้ของบ้าน\nหาเสากระโดง ธง และกระดูก\nจงขุดตรงนั้น หากใจเจ้ากล้า\nขุดแล้วคว้าทองของ Cuergo!\nเจ้าต้องใช้กุญแจ และเจ้าจะพบกุญแจนั้น\nผู้ที่เจ้าเผชิญเรียกเลือดเป็นค่าผ่าน" },
        progress = { "21:817456172:342879804", "หีบนี้ล็อกอยู่!" },
        completion = { "40:583591897:2052598890", "สมบัติที่ Captain Cuergo ซ่อนไว้กำลังรออยู่!" },
        required = { [9275] = { "12:289244737:1737138220", "กุญแจของ Cuergo" } },
        objectiveLabels = {
            item = { ["Cuergo's Key"] = "กุญแจของ Cuergo" },
        },
    },
    [2954] = { -- The Stone Watcher
        title = { "17:1749122708:476645314", "ผู้เฝ้าศิลา" },
        objective = { "117:511787556:1889480617", "เรียนรู้หน้าที่ของ Stone Watcher of Norgannon แล้วใช้งาน Uldum Pedestal ในทะเลทราย Tanaris" },
        description = { "429:321588441:1532227397", "\"ขอต้อนรับ ข้าคือผู้พิทักษ์ทางเข้า ข้าจะไม่อนุญาตให้เข้าสู่เขต Uldum เว้นแต่เจ้าจะรวม Plates of Uldum เข้ากับชุดแผ่นบันทึกของเจ้าแล้ว\"\n\nการปรากฏตัวของ Stone Watcher of Norgannon คงเป็นปฏิกิริยาที่คาดหวังไว้ตอนส่งเจ้าพร้อมแผ่นบันทึกแพลทินัมมายังทะเลทราย Tanaris ตามคำแนะนำที่ได้รับ เจ้าต้องสืบให้รู้เรื่องราวของผู้เฝ้าศิลาก่อนจะดำเนินการต่อ" },
        progress = { "72:238226879:1468091442", "ต้องเรียนรู้หน้าที่ของผู้เฝ้าศิลาก่อนจะดำเนินการต่อ..." },
        completion = { "254:644845525:152077145", "เสียงของผู้เฝ้าศิลาก้องกังวานด้วยพลังและอำนาจ\n\n\"เจ้าจะได้รับแผ่นบันทึกคืนเมื่อเข้าใช้งานแท่น เมื่อเจ้าได้ Plates of Uldum มาและรวมเข้ากับชุดแผ่นบันทึกที่มีอยู่แล้ว เจ้าจึงจะเข้าสู่สถานที่แห่งนี้ได้\"" },
        objectiveLabels = {
            event = { ["Learn the purpose of the Stone Watcher of Norgannon"] = "หาคำตอบว่าผู้เฝ้าศิลาแห่ง Norgannon มีหน้าที่อะไร" },
        },
    },
    [3022] = { -- Handle With Care
        title = { "16:1484505349:47347254", "โปรดขนย้ายด้วยความระมัดระวัง" },
        objective = { "74:1787072912:2028109201", "นำ Carefully-packed Crate ไปให้ Erelas Ambersky ที่ Rut'theran Village" },
        description = { "N 338:326261788:288397128", "{name} ข้าเห็นว่าเจ้าปรารถนาจะอุทิศตนให้ภารกิจอันทรงคุณค่าของข้า ใช่แล้ว แน่นอน เจ้าช่วยงานข้าได้!\n\nนำลังไข่นี้ไปให้ Erelas Ambersky เขาเป็นดรูอิดที่คอยดูแลไข่เหล่านี้ ช่วยให้ฟักเป็นตัว แล้วฝึกเหล่าฮิปโปกริฟน้อย เจ้าจะพบเขาที่ Teldrassil ในหมู่บ้านเล็ก ๆ ทางใต้ที่เรียกว่า Rut'theran" },
        progress = { "39:536347353:471443437", "ข้าว่าคงเป็นสินค้าจาก Curgle อีกงวดสินะ?" },
        completion = { "25:328543501:1621241081 N 297:1434130811:859781189 N 1:46:46", "ขอบคุณที่ช่วยนะ {name} หากไม่มีพวกเรา จำนวนฮิปโปกริฟคงไม่เพิ่มพูนได้เช่นนี้ อา แต่ข้ามั่นใจว่าเจ้าเข้าใจดีอยู่แล้ว เพราะเจ้าเดินทางไป Feralas ด้วยตัวเอง และเห็นความเสียหายที่พวก Gordunni ก่อไว้ที่นั่น\n\nเอาล่ะ อย่างที่เห็น ข้ากำลังทำงานอย่างหนัก เจ้าควรออกเดินทางต่อได้แล้ว\n\nขอบใจอีกครั้ง {name}" },
        required = { [9507] = { "24:1577927982:420572422", "ลังที่บรรจุอย่างระมัดระวัง" } },
        steps = { { "24:1577927982:420572422", "ลังที่บรรจุอย่างระมัดระวัง" } },
    },
    [3161] = { -- Gahz'ridian
        title = { "11:1821673236:80738592", "Gahz'ridian" },
        objective = { "76:334744326:583042661", "Marvon Rivetseeker ใน Tanaris ต้องการให้เจ้าเก็บ Gahz'ridian Ornament 30 ชิ้น" },
        description = { "N 499:1141620338:1217876070", "{name} ข้าเป็นนักวิทยาศาสตร์ แต่ในใจก็เป็นนักล่าสมบัติด้วย!\n\nนานมาแล้ว เมื่อเหล่าโทรลล์ยังอาศัยอยู่ในดินแดนนี้ พวกมันสร้างเครื่องประดับมากมายตามรูปลักษณ์ของ Gahz'rilla ไฮดราที่พวกมันบูชาเป็นเทพ เครื่องประดับเหล่านี้แกะสลักจากธาตุที่ข้าเรียกว่า \"Gahz'ridian\" ตามชื่อเทพไฮดราตนนั้น\n\nข้าพบมาบ้างแล้ว แต่อยากได้เพิ่มไว้ศึกษา บางทีเจ้าอาจหาได้?\n\nข้าถึงกับประดิษฐ์เครื่องตรวจหาที่ทำให้ค้นหา Gahz'ridian ได้ง่ายดาย! แค่สวมมัน แล้วเริ่มค้นหาได้เลย!" },
        progress = { "85:1084795298:524113646 N 18:554213775:23771739", "เจ้ามีปัญหาอะไรหรือ?\n\nเจ้าพบ Gahz'ridian ได้แทบทุกแห่งใน Tanaris นะ {name} ค้นหาต่อไป!" },
        completion = { "82:1141856534:1073801683 N 31:788147219:866908793", "สมบูรณ์แบบ เครื่องประดับเหล่านี้เหมาะกับการศึกษาของข้าที่สุด ขอบใจมากที่ช่วยนะ {name}\n\nอ้อ ข้าขอหมวกคืนได้ไหม?" },
        required = { [8443] = { "20:1639811676:1425027781", "เครื่องประดับ Gahz'ridian" }, [9978] = { "20:111262730:748455439", "เครื่องตรวจจับ Gahz'ridian" } },
        steps = { { "20:1639811676:1425027781", "เครื่องประดับ Gahz'ridian" }, { "20:111262730:748455439", "เครื่องตรวจจับ Gahz'ridian" } },
    },
    [3362] = { -- Thistleshrub Valley
        title = { "19:250747231:786378020", "หุบเขา Thistleshrub" },
        objective = { "95:1481897547:1773869001", "Tran'rek ที่ Gadgetzan ต้องการให้เจ้ากำจัด Gnarled Thistleshrub 8 ตัว และ Thistleshrub Rootshaper 8 ตัว" },
        description = { "71:698316430:1140537903 N 398:767391247:1242049185 N 14:1066042330:1185892014", "เจ้าเคยเห็น Thistleshrub Valley หรือไม่? ที่นั่นอันตรายมากนะ {name}\n\nสัตว์ประหลาดที่อยู่แถวนั้น ข้าไม่ไว้ใจมันแม้แต่น้อย! Gnarled Thistleshrub กับ Thistleshrub Rootshaper ข้าคิดว่าพวกมันเรียกกันอย่างนั้น...\n\nอย่างไรก็เถอะ ข้าอยากเข้าไปในหุบเขา แต่ตราบใดที่ยังมีพวก thistleshrub มากขนาดนั้น ข้าไม่มีทางกลับไปแน่ แต่ตรงนี้แหละที่เจ้าช่วยได้ ถ้าเจ้ากำจัดพวกมันออกไปบ้าง ข้าก็อาจคิดเรื่องกลับไปดู เจ้าคิดว่าอย่างไร {name}? ช่วยข้าหน่อยได้ไหม?" },
        progress = { "105:2019104258:2104488124", "ข้าอยากเข้าไปดูกระบองเพชรในหุบเขานั้นใกล้ ๆ... ดังนั้นเหลือบางส่วนไว้ในสภาพสมบูรณ์ด้วยนะ?" },
        completion = { "124:1975563479:1524979663", "พวกมันตัวใหญ่ขนาดนั้นเลยหรือ? ข้าอาจต้องทบทวนแผนใหม่...\n\nแต่เจ้าทำตามข้อตกลงแล้ว นี่คือสิ่งที่ข้าสัญญาไว้" },
        objectiveLabels = {
            monster = { ["Gnarled Thistleshrub slain"] = "ปราบ พุ่มหนามบิดปม Thistleshrub", ["Thistleshrub Rootshaper slain"] = "ปราบ ผู้ดัดราก Thistleshrub" },
        },
    },
    [3444] = { -- The Stone Circle
        title = { "16:1397483619:1957867086", "ศิลาวงกลม" },
        objective = { "72:25026301:1398973608", "ไปนำ Stone Circle จากโรงช่างของ Marvon Rivetseeker ที่ Ratchet" },
        description = { "502:1402734663:1848087994", "ข้าเคยเข้าไปในห้องอันน่าพรั่นพรึงของ Sunken Temple ความชั่วร้ายในนั้นแทรกซึมทุกผู้ที่ย่างกรายเข้าไป ข้าแทบหาทางออกมาไม่รอด ต้องลุยผ่านเมือกที่ตอนนี้ปกคลุมพื้น สิ่งเดียวที่จำได้คือข้าสะดุดเดินผ่านห้องวงกลมขนาดใหญ่ที่เต็มไปด้วยรูปปั้นอสรพิษ...\n\nเมื่อไม่นานมานี้ ข้าพบศิลาทรงกลมที่ดูเหมือนมีสัญลักษณ์อสรพิษแบบเดียวกันประทับอยู่ ข้าให้คนบรรจุและส่งไปยังโรงช่างของข้าที่ Ratchet ไปนำมันมา แล้วข้าอาจบอกเจ้าได้มากกว่านี้" },
        progress = { "30:790722339:1574192331 N 34:734089785:830711784", "Ratchet อยู่ไม่ไกลจากที่นี่นะ {name} การเดินทางไม่น่าจะนานนัก" },
        completion = { "58:2114674821:1116424915 N 3:3050122:795478", "ใช่... นี่คือศิลาก้อนนั้น\n\nข้าเริ่มจำทุกอย่างได้แล้ว {name}..." },
        required = { [10556] = { "12:2125475894:384480722", "วงศิลา" } },
        steps = { { "12:2125475894:384480722", "วงศิลา" } },
    },
    [3520] = { -- Screecher Spirits
        title = { "17:634835229:542386762", "วิญญาณ Screecher" },
        objective = { "94:2050081574:29822490", "เก็บวิญญาณของ screecher ใน Feralas จำนวน 3 ดวง แล้วกลับไปหา Yeh'kinya ที่ Steamwheedle Port" },
        description = { "492:1757882961:1903850537", "ข้าแสวงหาวิญญาณของ vale screecher แห่ง Feralas พวกมันเป็นเครือญาติของเทพเก่าแก่ตนหนึ่ง และวิญญาณของมันผูกพันกับเทพตนนั้น\n\nนำไม้หนามวิเศษนี้ไปที่ Feralas ตามหาและปราบ vale screecher ทางตอนใต้และตอนกลางของ Feralas แล้วโบกไม้หนามของข้าเหนือร่างที่ล้มลง วิธีนี้จะชักนำให้วิญญาณเผยตัวออกมา จงสัมผัสวิญญาณแล้วเก็บแก่นพลังของมัน\n\nนำไม้หนามและแก่นพลังที่เก็บได้กลับมาให้ข้า แล้วข้าจะเล่าเรื่องเทพเก่าแก่ที่กล่าวถึงให้ฟังเพิ่มเติม" },
        progress = { "57:463906332:1091322375 N 1:63:63", "เจ้าเก็บแก่นพลังของวิญญาณ screecher ได้แล้วหรือยัง {name}?" },
        completion = { "20:1921578502:569519135 N 449:446491672:1241243864", "เจ้าทำได้ดี {name} บางทีอาจถึงเวลาเผยเรื่องราวเพิ่มเติมแล้ว...\n\nในหมู่โทรลล์มีคำพยากรณ์โบราณว่า สักวันเทพที่ตายไปแล้ว Hakkar ผู้ถลกวิญญาณ จะกลับมายังโลกนี้ บ้างกล่าวว่าการมาถึงของ Hakkar จะนำความยินดีและเกียรติยศมาสู่เผ่าโทรลล์ แต่บางคนเชื่อว่าการคืนชีพของเขาคือจุดจบของสรรพสิ่ง\n\nข้าไม่เชื่อตำนานนี้ แต่ข้ารู้ว่าแก่นพลังของ Hakkar มีอำนาจมหาศาล และพลังนี้ควรอยู่ให้พ้นมือผู้ที่จะนำมันไปใช้ในทางที่ผิด..." },
        required = { [10699] = { "19:1421810518:482151697", "กิ่งหนามของ Yeh'kinya" } },
        steps = { { "27:1575883240:505598871", "รวบรวมวิญญาณ Screecher" }, { "19:1421810518:482151697", "กิ่งหนามของ Yeh'kinya" } },
    },
    [4496] = { -- Bungle in the Jungle
        title = { "20:2063911660:2121441304", "วุ่นวายกลางป่า" },
        objective = { "92:2001836517:1134605067", "นำ Gorishi Scent Gland และตัวอย่าง Un'Goro Soil 5 กองไปให้ Alchemist Pestlezugg ที่ Gadgetzan" },
        description = { "478:64683165:1928655574", "งานวิจัยทำให้ข้าพบว่าซิลิธิดก็เหมือนผึ้ง หากทำลายราชินีแห่งรัง ที่เหลือก็น่าจะระส่ำระสาย ข้าจะปรุงเหยื่อล่อให้เราใช้เรียกราชินีออกมา เมื่อมันปรากฏตัว เจ้าก็จัดการมัน\n\nแต่ก่อนอื่น เราต้องมีวัตถุดิบบางอย่าง เราคงไม่อยากให้เจ้าบุกป่าอย่างสะเปะสะปะโดยไม่เตรียมตัว ไปทางตะวันตก หารังซิลิธิดใน Un'Goro Crater แล้วเอาต่อมกลิ่นจากแมลงตัวหนึ่งมา ข้าต้องการตัวอย่างดินพื้นถิ่น Un'Goro ด้วย" },
        progress = { "262:1997896737:150353829", "การหาต่อมกลิ่นที่ใช้ได้อาจต้องใช้เวลาหน่อย ต่อมต้องไม่เสียหาย แต่ขั้นตอนเอามันมาก็ไม่ได้ช่วยให้คงสภาพดีนัก ส่วนดิน ข้าคิดว่าคงหาได้ไม่ยาก\n\nเอาล่ะ เจ้าหาของที่ข้าต้องใช้ทำเหยื่อล่อมาได้หรือยัง?" },
        completion = { "236:1885648436:1319747303 N 151:1287725856:1203692946", "ต่อมกลิ่น อา ใช่ เยื่อหุ้มยังสมบูรณ์ เยี่ยมมาก ส่วนดิน ใช่ น่าจะใช้ได้ดีทีเดียว เมื่อเติมส่วนผสมพิเศษของข้า ก็น่าจะบดทั้งหมดให้เป็นเหยื่อล่อที่สมบูรณ์แบบได้\n\nขอเวลาข้าทำเหยื่อล่อสักครู่ {name} เมื่อพร้อมแล้ว เราจะเริ่มขั้นต่อไป ซึ่งหวังว่าจะหยุดซิลิธิดได้ก่อนที่มันจะยึด Gadgetzan... และส่วนที่เหลือของ Kalimdor" },
        required = { [11837] = { "19:1439641864:1874683621", "ต่อมกลิ่นของ Gorishi" }, [11018] = { "12:1017872992:588641980", "ดินจาก Un'Goro" } },
        steps = { { "19:1439641864:1874683621", "ต่อมกลิ่นของ Gorishi" }, { "12:1017872992:588641980", "ดินจาก Un'Goro" } },
    },
    [4504] = { -- Super Sticky
        title = { "12:552413970:1363980838", "เหนียวสุดขีด" },
        objective = { "65:1271847031:488554174", "เก็บตัวอย่าง Super Sticky Tar 12 ชิ้นให้ Tran'rek ที่ Gadgetzan" },
        description = { "51:1824357096:1031316313 N 436:1049983686:1252332705", "ข้ามองหาวิธีหาเงินเร็ว ๆ อยู่เสมอ {name} หากเจ้าช่วยทำตามความคิดล่าสุดของข้า ข้าจะแบ่งกำไรให้เล็กน้อย ฟังดูเป็นอย่างไร?\n\nข้าก็คิดแล้วว่าเจ้าต้องชอบ!\n\nไปที่บ่อน้ำมันดินทางเหนือของ Un'Goro Crater แล้วเก็บน้ำมันดินมาให้ข้า แต่ไม่ใช่น้ำมันดินธรรมดานะ เจ้าต้องเอาจากสัตว์ที่อาศัยรอบบ่อ น้ำมันดินทั่วไปเหนียวไม่พอ\n\nสิ่งมีชีวิตคล้ายพืชพวกนั้นมีคลอโรฟิลล์อยู่ในผิว เมื่อผสมกับน้ำมันดิน มันจะเหนียวสุด ๆ!" },
        progress = { "72:1075011997:675685994", "Tran'rek ทำสำเร็จอีกแล้ว กาวสุดเหนียวนี่จะต้องฮิตไปทั่วแน่!" },
        completion = { "208:328217593:1508470039", "ใช่ น้ำมันดินนี่แหละที่ต้องการ...\n\nเฮ้ เดี๋ยวก่อน มือข้า... ดูเหมือนข้าจะแยกมันออกจากกันไม่ได้...\n\nบางทีนี่อาจไม่ใช่ความคิดที่ดีนัก อ้อ แต่เดี๋ยวก่อน! น้ำยาขจัดน้ำมันดินสุดเหนียว! นั่นแหละแหล่งเงินตัวจริง!" },
        required = { [11834] = { "16:60696828:1024392056", "น้ำมันดินที่เหนียวเป็นพิเศษ" } },
        steps = { { "16:60696828:1024392056", "น้ำมันดินที่เหนียวเป็นพิเศษ" } },
    },
    [4507] = { -- Pawn Captures Queen
        title = { "19:998794534:1824894998", "เบี้ยพิชิตราชินี" },
        objective = { "121:1762082251:1593124294", "ปราบ Gorishi Hive Queen เมื่ออัญเชิญออกมาแล้ว\n\nนำ Gorishi Queen's Brain ไปให้ Alchemist Pestlezugg ที่ Gadgetzan" },
        description = { "471:1914929240:1440886158 N 1:33:33", "นี่คือเหยื่อล่อ ภายในเครือข่ายรังน่าจะมีผลึกบางชนิดอยู่ เราคิดว่าซิลิธิดใช้ผลึกเป็นอุปกรณ์เชื่อมประสานกันทั่วทั้งรัง หากถามว่าผลึกอยู่ที่ใด ข้าว่าลองหาในห้องฟักไข่ภายในรังดู\n\nใช้เหยื่อล่อกับผลึกน่าจะเรียกราชินีออกมาได้ แต่ระวังด้วย มันคงมีองครักษ์หลายตัวคุ้มกัน จัดการราชินีแล้วนำสมองของมันออกมา แม้จะฟังดูน่าขยะแขยง แต่เราจำเป็นต้องศึกษามันอย่างยิ่ง ขอให้โชคดี {name}!" },
        progress = { "269:992748116:1396206521 N 1:46:46", "การนำสมองราชินีมาใช้วิจัยเป็นสิ่งจำเป็นอย่างที่สุด จากสิ่งที่เราเรียนรู้ เราเชื่อว่าซิลิธิดเหล่านี้มีความเป็นไปได้มากที่จะถูกสติปัญญาชั่วร้ายบางอย่างควบคุมอยู่ แค่คิดว่าอะไรจะควบคุมสิ่งที่ร้ายกาจอย่างซิลิธิดได้ ข้าก็หนาวสะท้านแล้ว {name}" },
        completion = { "11:488120878:499255695 N 317:1391731223:1410804682", "ยอดเยี่ยม {name}! วันนี้เราคว้าชัยชนะครั้งสำคัญได้แล้ว ต้องใช้เวลาอีกหน่อยกว่าจะเข้าใจสิ่งที่เราได้มาอย่างถ่องแท้ แต่เราจะใช้มันให้คุ้มค่า เจ้าไม่ต้องห่วงเรื่องนั้น\n\nส่วนซิลิธิด ข้าสงสัยจริง ๆ ว่าสิ่งที่เราพบจะเป็นทั้งหมดที่มีอยู่ เรื่องนี้จบลงง่ายเกินไป ข้าเสียใจที่ต้องพูดเช่นนั้น" },
        required = { [11835] = { "19:870080376:1993511071", "สมองราชินี Gorishi" } },
        steps = { { "19:870080376:1993511071", "สมองราชินี Gorishi" } },
    },
    [5801] = { -- Fire Plume Forged
        title = { "17:6167297:162211471", "หลอมที่ Fire Plume" },
        objective = { "274:632223385:675675898", "นำ Skeleton Key Mold และ Thorium Bar 2 แท่งไปยังยอด Fire Plume Ridge ใน Un'Goro Crater ใช้ Skeleton Key Mold ข้างทะเลสาบลาวาเพื่อหลอม Unfinished Skeleton Key\n\nนำ Unfinished Skeleton Key ไปให้ Alchemist Arbington ที่ Chillwind Point ใน Western Plaguelands" },
        description = { "498:22863707:1471618299", "เจ้าต้องใช้ธอเรียมสองแท่งกับแหล่งความร้อนอันรุนแรงเพื่อหลอมแกนกุญแจ เรื่องธอเรียมเจ้าต้องหาเอง แต่เรื่องความร้อนข้าช่วยได้\n\nทางตะวันตกของเราใน Un'Goro Crater คือ Fire Plume Ridge ภูเขาไฟที่ยังคุกรุ่น ทะเลสาบลาวาบนยอดร้อนพอจะหลอมธอเรียมเข้ากับกระดูกได้ เงินของเจ้าซื้อแม่พิมพ์ที่เพียงนำไปจุ่มในทะเลสาบบนยอด ลาวาจะจัดการที่เหลือเอง\n\nส่วนของข้าจบเท่านี้ หากจะทำกุญแจให้เสร็จ เจ้าต้องกลับไปคุยกับ Arbington อีกครั้ง" },
        progress = { "424:2086592926:559864429", "เจ้าทำแกนกุญแจเสร็จแล้วหรือ? ข้าเสียใจที่เจ้าต้องรับภาระค่าซื้อแม่พิมพ์ แต่เราทุกคนต้องทำหน้าที่ของตนเพื่อต่อต้าน Scourge เมื่อเจ้าส่งกุญแจที่ยังไม่เสร็จมาให้ข้า เจ้าจะพร้อมสำหรับของชิ้นสุดท้ายที่ต้องใช้สร้างมันให้สมบูรณ์\n\nมันจะไม่ง่ายเลย แต่งานที่เจ้าทำมาเพื่อเตรียมบุก Andorhal กำลังจะเริ่มให้ผลตอบแทน เจ้าจะได้เห็น" },
        completion = { "56:656105994:1786244628 N 379:1397542408:310512894", "กุญแจดอกนี้ช่างราคาแพงจริง ๆ ว่าไหม {name}? แต่ก็ยังไม่เสร็จ ถึงเวลาหาจุดรวมพลังให้กับสิ่งที่เราสร้าง เพื่อการนั้น เจ้าต้องเผชิญศัตรูตัวฉกาจที่เราเตรียมรับมือมาตลอดใน Andorhal... สิ่งชั่วร้ายที่บงการทุกอย่างภายในกำแพงเมืองร้าง\n\nข้าหมายถึง Araj the Summoner ลิชผู้เป็นหนึ่งในสิ่งมีชีวิตที่ทรงพลังที่สุดของ Scourge" },
        required = { [14645] = { "23:325777604:865141534", "กุญแจโครงกระดูกที่ยังทำไม่เสร็จ" } },
        objectiveLabels = {
            item = { ["Unfinished Skeleton Key"] = "กุญแจโครงกระดูกที่ยังทำไม่เสร็จ" },
        },
    },
    [5863] = { -- The Dunemaul Compound
        title = { "21:390520958:1652008783", "ฐานที่มั่น Dunemaul" },
        objective = { "146:717241005:113312790", "Andi Lynn ที่ Gadgetzan ต้องการให้เจ้าทำลาย Dunemaul Compound โดยกำจัด Dunemaul Brute 10 ตัว, Dunemaul Enforcer 10 ตัว และ Gor'marok the Ravager" },
        description = { "498:1453081275:200226413", "เมื่อไม่นานมานี้ มีกลุ่มโอเกอร์เร่ร่อนขนาดใหญ่มาถึง Tanaris พวกมันยึดพื้นที่ทะเลทรายขนาดใหญ่ทางใต้ของที่นี่แล้วตั้งฐานขึ้น กลุ่มย่อยอีกหลายกลุ่มกำลังตระเวนไปทั่วทะเลทราย บางส่วนบุกเข้าไปในซากเมืองโทรลล์เก่าแล้ว\n\nต้องทำลาย Dunemaul Compound! เราจะปล่อยให้โอเกอร์เหล่านี้สะสมกำลังไม่ได้\n\nหัวหน้าของพวกมันชื่อ Gor'marok the Ravager ข้าเชื่อว่าการยุติการนำของมันจะเป็นจุดเริ่มต้นของจุดจบสำหรับเหล่าโอเกอร์" },
        progress = { "34:264978764:620835868", "ข้ากังวลเหลือเกิน! โปรดระวังตัวด้วย!" },
        completion = { "45:712841002:2082889234 N 23:1588710736:267386107", "ข้าดีใจมากที่เจ้าทำเรื่องนี้ให้ข้าได้ {name}! ขอบคุณที่ช่วย!" },
        objectiveLabels = {
            monster = { ["Dunemaul Brute slain"] = "ปราบ จอมโหด Dunemaul", ["Dunemaul Enforcer slain"] = "ปราบ มือคุมกฎ Dunemaul", ["Gor'marok the Ravager slain"] = "ปราบ Gor'marok จอมทำลายล้าง" },
        },
    },
    [8182] = { -- The Hand of Rastakhan
        title = { "21:73303320:298106207", "หัตถ์ของ Rastakhan" },
        objective = { "36:1195942759:1162929127", "ไปคุยกับ Molthor ใน Stranglethorn" },
        description = { "N 486:1277738481:1799319928", "{name} สิ่งที่เราหวาดกลัวที่สุดเกิดขึ้นแล้ว ตำนานกล่าวถึงผู้ถลกวิญญาณที่ปกครองโลกของโทรลล์ในอดีตด้วยความชั่วร้ายและความหวาดกลัว อำนาจของเขาเด็ดขาดไร้ผู้ต้านทาน หากหยุดเขาไม่ได้ในตอนนี้ การครองอำนาจครั้งใหม่ของเขาอาจแผ่ไปทั่ว Azeroth!\n\nมีโทรลล์ Zandalarian กลุ่มหนึ่งที่อาจช่วยเราสกัดคลื่นความมืดนี้ได้ พวกเขาตั้งค่ายอยู่บน Yojamba Isle นอกชายฝั่ง Stranglethorn ทางตะวันตกของซาก Zul'Kunda ไปคุยกับ Molthor ผู้นำของพวกเขา และภาวนาให้เขารู้วิธีปราบ Hakkar" },
        completion = { "248:807562702:1227416466 N 45:1689734731:892104496", "นักสำรวจแร่ Ironboot ส่งเจ้ามาหรือ? ชนเผ่าของเขามีปัญญา และฉลาดยิ่งกว่าที่พาเจ้ามาหาข้า เพราะข้ากับเหล่าโทรลล์ Zandalarian อาจรู้วิธีปราบผู้ถลกวิญญาณ\n\nจงพูดคุยกับเหล่าโทรลล์บนเกาะนี้ ตั้งใจฟังคำของพวกเขา และเตรียมตัวให้พร้อม {name} เพราะภารกิจเบื้องหน้าเจ้าชุ่มโชกด้วยเลือด" },
    },
    [8365] = { -- Pirate Hats Ahoy!
        title = { "17:1218273832:655525939", "หมวกโจรสลัดมาแล้ว!" },
        objective = { "116:946841509:2013335864", "Haughty Modiste ต้องการให้เจ้าเก็บ Southsea Pirate Hat 20 ใบ แล้วนำกลับไปให้นางที่ Steamwheedle Port ใน Tanaris" },
        description = { "71:1792618968:1269513585 C 419:244060591:223771672", "เจ้าคือผู้ช่วยที่ Cartel ส่งมาหรือ? ข้าว่าคงพอใช้ได้ ฟังให้ดีนะ {class} อย่างที่เจ้ารู้ ข้าจัดหาเครื่องแต่งกายทันสมัยให้ชนชั้นสูงของสังคม Azeroth ทั้งราชา ราชินี วอร์ชีฟ และ... พวก Horde จะเรียกราชินีของพวกเขาว่าอะไรก็ตาม ทุกคนสวมสิ่งที่ข้าตัดสินว่าอยู่ในสมัย และพวกเขาจ่ายแพงหูฉี่เพื่อมัน ซึ่งเป็นส่วนที่ดีที่สุด\n\nเอาล่ะ สิ่งที่จะเกิดขึ้นคือ เจ้าจะลงไปที่ Lost Rigger Cove แล้วหาหมวกโจรสลัดมาให้มาก ๆ จะใช้วิธีไหนก็ได้ เจ้าคิดว่าทำไหวไหม?" },
        progress = { "100:650576492:110914794", "เจ้ามีหมวกครบ 20 ใบหรือยัง? ข้าไม่เชื่อ ขอดูหน่อย มันควรจะอยู่ในสภาพสมบูรณ์ไร้ที่ตินะ!" },
        completion = { "329:1980368381:1942661785", "โอ้ เจ้าน่ารักจริง ๆ แม้จะใช้เวลานานกว่าที่ข้าคุ้นเคยก็ตาม สินค้างวดนี้น่าจะทำเงินให้ข้าได้มาก เมื่อข้าทำความสะอาดและปรับแต่งหมวกเหล่านี้แล้ว และเพราะข้ายินดีตอบแทนงานที่ทำได้ดีเสมอ นี่คือของเล็กน้อยสำหรับเจ้า ข้าแนะนำให้แบ่งไปจ่ายค่าอาบน้ำบ้างนะ ที่รัก" },
        required = { [20519] = { "19:476948651:1665252465", "หมวกโจรสลัด Southsea" } },
        steps = { { "19:476948651:1665252465", "หมวกโจรสลัด Southsea" } },
    },
    [8366] = { -- Southsea Shakedown
        title = { "18:1716193949:775404230", "จัดระเบียบโจรสลัด Southsea" },
        objective = { "179:1325775330:461008609", "Security Chief Bilgewhizzle แห่ง Steamwheedle Port ใน Tanaris ต้องการให้เจ้ากำจัด Southsea Pirate 10 คน, Southsea Freebooter 10 คน, Southsea Dock Worker 10 คน และ Southsea Swashbuckler 10 คน" },
        description = { "470:380322467:1426771536 N 19:1797496881:1000022303", "อ๊าก! พวกเขาอยากให้ข้าทำเรื่องเป็นไปไม่ได้!\n\nSteamwheedle Cartel ต้องการให้ข้าสั่งสอนโจรสลัด Southsea ปัญหาคือข้าอยู่สองที่พร้อมกันไม่ได้ ข้าต้องอยู่ที่นี่เพื่อรักษาความสงบ\n\nระยะหลังพวกโจรสลัดไม่สนใจเงินค่าคุ้มครองที่ Cartel จ่ายให้อย่างสม่ำเสมอ ข้าจึงอยากแต่งตั้งเจ้าเป็นผู้ช่วยเจ้าหน้าที่ชั่วคราว ให้ลงไปแสดงให้พวกมันรู้ว่าใครเป็นใคร\n\nเจ้าจะพบพวกมันที่ Lost Rigger Cove ซึ่งอยู่ทางใต้ไม่ไกลนัก ขอบใจ {name} ข้าจะติดหนี้เจ้า!" },
        progress = { "88:1672165730:1249388896", "กลับมาเร็วเสียจริง? หวังว่าเจ้าจะสั่งสอนพวกอันธพาล Southsea ให้จำไปอีกนานแล้วนะ" },
        completion = { { "N 231:2093312299:67829751", "N 233:497352140:1157392931" }, "{name}! เจ้ามันสุดยอดจริง ๆ!!!\n\nข้ามั่นใจว่า Cartel จะเลิกกดดันข้าบ้างแล้ว หลังจากเจ้าจัดการพวกสวะ Southsea ไป ไหนดูซิ ข้าจะให้อะไรเป็นรางวัลได้บ้าง? เอาเป็นเงินเล็กน้อย แล้วเจ้าเลือกของพวกนี้สักชิ้นตอบแทนความเหนื่อยยากดีไหม?" },
        objectiveLabels = {
            monster = { ["Southsea Pirate slain"] = "ปราบ โจรสลัด Southsea", ["Southsea Freebooter slain"] = "ปราบ นักปล้นเรือ Southsea", ["Southsea Dock Worker slain"] = "ปราบ คนงานท่าเรือ Southsea", ["Southsea Swashbuckler slain"] = "ปราบ โจรสลัดนักดาบ Southsea" },
        },
    },
    [8577] = { -- Stewvul, Ex-B.F.F.
        title = { "18:1833241445:1361495048", "Stewvul อดีตเพื่อนรักตลอดกาล" },
        objective = { "141:546123605:1289516559", "Narain Soothfancy ต้องการให้เจ้าตามหา Stewvul อดีตเพื่อนรักตลอดกาลของเขา แล้วเอา Scrying Goggles ที่ Stewvul ขโมยไปกลับคืนมา" },
        description = { "502:1342083651:1835340392 N 1:33:33", "หากข้าจะต้องแปลอะไร ข้าก็ต้องมีแว่นพยากรณ์ แต่น่าเสียดาย มันถูก Stewvul อดีตเพื่อนรักตลอดกาลของข้าขโมยไปนานพอสมควรแล้ว เขาทำหัวใจข้าแตกเป็นห้าเสี่ยง แล้วทิ้งข้าให้อยู่ที่นี่อย่างหมดอาลัยตายอยาก\n\nด้วยความช่วยเหลือของลูกแก้วคู่ใจ ข้าระบุตำแหน่งของเขาได้ว่าอยู่ที่ Greymane Wall ใน Silverpine หรือไม่ก็ที่ซึ่งดูเหมือนโลกอีกฟากประตูมิติใน Outland ซึ่งกำลังถูก Burning Legion บุกยึด เจ้าต้องตามหาเขาแล้วเอาแว่นของข้ากลับมา {name}!" },
        completion = { "119:1423976913:1921727194 R 90:824921665:815381860", "ข้าไม่อยากเชื่อว่าเขาหาข้าเจอ ข้าคิดแน่แล้วว่าสลัดเขาหลุดตั้งแต่ตอนอยู่ใน Outland ข้าไม่กลับไปที่นั่นหรอก {race}! ไม่มีวัน ไม่ว่าทางไหน! ข้าเลิกเป็นเพื่อนรักตลอดกาลแบบไม่เต็มเวลาและทาสเต็มเวลาของเขาแล้ว" },
    },
    [8584] = { -- Never Ask Me About My Business
        title = { "30:1380601242:2059383954", "อย่าถามเรื่องงานของข้าเด็ดขาด" },
        objective = { "83:1234278305:1236285753", "Narain Soothfancy ใน Tanaris ต้องการให้เจ้าไปคุยกับ Dirge Quikcleave ที่ Gadgetzan" },
        description = { "491:1943098910:312827212", "หากมีเรื่องหนึ่งที่เจ้าควรรู้เกี่ยวกับข้า ก็คือ อย่าถามเรื่องงานของข้าเด็ดขาด! ข้าทำงานกับสิ่งที่เจ้าไม่มีทางเข้าใจ ยกตัวอย่าง เจ้ารู้ไหมว่า psychotronic muzzledorf คืออะไร? แน่นอนว่าไม่รู้! เพราะอย่างนั้นจึงปล่อยให้ข้าวางแผน ส่วนเจ้าไปหาของ\n\nอย่างที่ข้าบอกไป หากจะทำให้เรื่องนี้สำเร็จ เราต้องใช้ไก่หนัก 500 ปอนด์\n\nไปที่ Gadgetzan แล้วคุยกับ Dirge Quikcleave เขาจะช่วยให้เจ้าเริ่มหาตัวที่เหมาะสมได้" },
        completion = { "303:591251883:285757791", "<Dirge เกาศีรษะ>\n\nไก่หนัก 500 ปอนด์หรือ? ไม่มีของแบบนั้นหรอก! อย่างน้อยตอนนี้ก็ไม่มีแล้ว ข้าเคยรู้จักไก่แบบนั้น... ไก่ดำแห่งความตาย...\n\n<เสียงของ Dirge ค่อย ๆ เงียบลง>\n\nแต่ใช่ ไม่เคยมีใครเห็นไก่ตัวนั้นแล้วรอดมาเล่าเรื่องได้ ข้ามีความคิดที่จะเป็นประโยชน์ต่อเราทั้งคู่ เจ้าหนู" },
    },
    [8585] = { -- The Isle of Dread!
        title = { "18:1105896892:941286686", "เกาะแห่งความหวาดผวา!" },
        objective = { "89:1750591252:1384922177", "นำ Lakmaeran's Carcass และ Chimaerok Tenderloin 20 ชิ้นมาให้ Dirge Quikcleave ใน Tanaris" },
        description = { "500:1740349369:1546038908", "ตำนานเล่าว่าไคมีร็อกแห่ง Isle of Dread ใน Feralas มีเนื้อนุ่มฉ่ำอร่อยที่สุดเท่าที่มีอยู่! ทีนี้พวกไคมีร็อกยังมีตัวพ่ออยู่ด้วย ซึ่งหากเตรียมดี ๆ ก็อาจจะดูเหมือนไก่หนัก 500 ปอนด์... หรืออาจไม่เหมือนก็ได้\n\nไปที่ Isle of Dread สังหาร Lord Lakmaeran แล้วนำซากสด ๆ ของมันมาให้ข้า นั่นน่าจะทำให้เจ้าโนมพอใจ ส่วนหากจะให้ข้าพอใจ เจ้าต้องหาเนื้อสันในไคมีร็อกมาด้วย\n\nทำเรื่องนี้แล้วเจ้าจะได้ไก่หนัก 500 ปอนด์ พร้อมอะไรพิเศษอีกเล็กน้อย" },
        progress = { "21:1310847368:324319490", "อืมมม... ไคมีร็อก..." },
        completion = { "155:1741562939:1783518247", "ดูไขมันที่แทรกอยู่ในเนื้อสันในพวกนั้นสิ! ยอดเยี่ยม!\n\nทีนี้เรื่องไก่ตัวนั้น... อืม ขอข้าคิดหน่อย ต้องใช้เวลาสักสองสามนาทีวางสูตรอาหาร" },
        required = { [21027] = { "19:305906424:1316539311", "ซากของลักมาเอรัน" }, [21024] = { "20:2138422698:818357397", "เนื้อสันในไคมีร็อก" } },
        objectiveLabels = {
            item = { ["Lakmaeran's Carcass"] = "ซากของลักมาเอรัน", ["Chimaerok Tenderloin"] = "เนื้อสันในไคมีร็อก" },
        },
    },
    [8586] = { -- Dirge's Kickin' Chimaerok Chops
        title = { "31:1589629462:289012383", "ไคมีร็อกชอปส์รสเด็ดของ Dirge" },
        objective = { "96:1157975743:1341565338", "Dirge Quikcleave ที่ Gadgetzan ต้องการให้เจ้านำ Goblin Rocket Fuel 20 ชิ้น และ Deeprock Salt 20 ชิ้นไปให้เขา" },
        description = { "245:779331979:1727935765", "สูตรของข้าเสร็จแล้ว! ตอนนี้สิ่งที่ต้องการจากเจ้าคือเชื้อเพลิงจรวดกับเกลือ Deeprock ข้าจะจัดการเครื่องเทศเอง และเนื้อที่เจ้านำมาก็พอสำหรับส่วนที่เหลือ\n\nเมื่อเจ้านำของที่ขอมาให้ ไก่ก็จะพร้อมนำกลับไปให้ Narain" },
        progress = { "52:389472249:1884176577", "รีบหน่อย เจ้าหนู เราคงไม่อยากให้เนื้อนี่เสียหรอกนะ" },
        completion = { "83:107130643:1548136400", "พร้อมแล้ว! ข้าขอเสนอผลงานชิ้นเอกของข้า: ไคมีร็อกชอปส์รสเด็ดของ Dirge!" },
        required = { [9061] = { "18:230431697:1413838426", "เชื้อเพลิงจรวดก็อบลิน" }, [8150] = { "13:1356996729:236971052", "เกลือจากหินลึก" } },
        objectiveLabels = {
            item = { ["Goblin Rocket Fuel"] = "เชื้อเพลิงจรวดก็อบลิน", ["Deeprock Salt"] = "เกลือจากหินลึก" },
        },
    },
    [8587] = { -- Return to Narain
        title = { "16:45048017:2140341696", "กลับไปหา Narain" },
        objective = { "62:255037009:787547224", "นำ 500 Pound Chicken ไปให้ Narain Soothfancy ใน Tanaris" },
        description = { "210:69753053:53028004", "ข้าเป็นก็อบลินที่รักษาคำพูด เจ้าหนู นี่คือไก่หนัก 500 ปอนด์ของเจ้า\n\nโนมจะเอาไก่หนัก 500 ปอนด์ไปทำอะไร ข้าคงไม่มีวันรู้...\n\n<Dirge บ่นพึมพำฟังไม่ได้ศัพท์>\n\nคงเอาไปนอนข้างใน... พวกโนมสกปรก..." },
        progress = { "31:1738391783:503282304", "กลิ่นหอมยั่วน้ำลายนั่นคืออะไร?" },
        completion = { "161:2125033107:1052172031", "<Narain ใช้กำปั้นทั้งสองจ้วงเข้าไปในไก่ยักษ์ แล้วยัดอาหารเลิศรสของ Dirge เข้าปากจนเต็ม>\n\nอืมมม... เหลือเชื่อ! ไก่ที่อร่อยที่สุดที่ข้าเคยกิน!" },
    },
    [8597] = { -- Draconic for Dummies
        title = { "20:1259540426:1851709562", "ภาษามังกรสำหรับมือใหม่" },
        objective = { "69:2038004452:237133491", "ตามหาหนังสือของ Narain Soothfancy ที่ฝังไว้บนเกาะแห่งหนึ่งใน South Seas" },
        description = { "499:1816457277:277141409", "ข้ารู้อยู่แล้วว่าสักวันหนังสือเล่มนั้นต้องมีประโยชน์! โชคดีที่ข้ามีไหวพริบและมองการณ์ไกลพอจะเก็บมันไว้ในที่ปลอดภัย\n\nไม่ต้องห่วง มันอยู่ในที่ซึ่งไม่มีใครหวังจะหาเจอได้! ครั้งแรกข้าถึงกับต้องใช้ไจโรคอปเตอร์ไปที่นั่น แต่น่าเสียดายที่ข้าทำมันตกบนชายหาดตอนขากลับ อุบัติเหตุครั้งนั้นเองที่ทำให้ข้าได้พลังจิตเหนือโนมทั่วไป!\n\nมองหาซากไจโรคอปเตอร์ของข้าสักแห่งบน Land's End Beach แล้วว่ายน้ำลงใต้จากตรงนั้น! เจ้าจะรู้ว่าถึงจุดนั้นเมื่อได้เห็นเอง!" },
        completion = { "53:395943931:1958253196", "หนังสือหายไปแล้ว! บนกองดินมีจดหมายวางอยู่" },
    },
    [8598] = { -- rAnS0m
        title = { "6:1839024402:79210996", "จดหมายเรียกค่าไถ่" },
        objective = { "57:1121348319:271044561", "นำ Ransom Letter กลับไปให้ Narain Soothfancy ใน Tanaris" },
        description = { "285:1243433362:970340495", "<ข้อความบนจดหมายนี้ประกอบจากตัวอักษรหลากรูปแบบที่ติดกาวลงบนแผ่นหนัง>\n\nพวกเรามีหนังสือสุดหวงของเจ้าแล้ว เจ้าโนม หากอยากเห็นมันอีกครั้ง เจ้าต้องทำตามที่เราสั่งทุกอย่าง\n\n<มีรายการคำสั่งอย่างละเอียดกินพื้นที่ 3 หน้า>\n\nนำเงินมา และมาคนเดียว!" },
        progress = { "23:1546361627:899862697", "ว่าแต่ เกิดอะไรขึ้นหรือ?" },
        completion = { "127:1032285149:1616967849", "<ใบหน้าของ Narain แดงจัด>\n\nบังอาจลักพา... หนังสือของข้างั้นหรือ!? ข้าจะสอนให้รู้ว่าการหาเรื่องโนมพลังจิตหมายถึงอะไร!" },
    },
    [8599] = { -- Love Song for Narain
        title = { "20:2044767302:241069098", "บทเพลงรักถึง Narain" },
        objective = { "60:1578726473:1812126298", "นำ Meridith's Love Letter ไปให้ Narain Soothfancy ใน Tanaris" },
        description = { "502:647267385:1097471263", "ข้าไม่ค่อยมีแขกมาเยือน ที่จริง ครั้งสุดท้ายที่มีใครมาหาก็คือตอนที่ข้าช่วยโนมผู้น่ารักคนนั้นออกมาจากซากเครื่องบินที่ตก\n\n<Meridith เหม่อมองความว่างเปล่า จมอยู่ในความทรงจำ>\n\nเจ้ารู้จักเขาหรือไม่? Narain? Narain Soothfancy? โอ้ หากมีใครนำข้อความไปให้เขาแทนข้าได้ คงมีความหมายกับข้ามาก ข้าต้องบอกให้เขารู้ว่าข้ารู้สึกอย่างไร! ข้ารู้ว่านี่คือความรัก! ข้ารู้จริง ๆ!\n\nเจ้าช่วยส่งข้อความให้ Narain ได้ไหม? ข้าจะเป็นหนี้บุญคุณเจ้าตลอดไป!" },
        progress = { "20:2085501287:93558470", "เจ้ามีกลิ่นเหมือนปลา!" },
        completion = { "149:422043078:408000071", "อะไรนะ!?\n\n<Narain เริ่มกระสับกระส่าย>\n\nเอ่อ... แล้วเจ้าจะให้ข้าทำอย่างไร??? นางเป็นปลา! ปลานะ ข้าบอกเจ้าแล้ว! ส่วนข้าเป็นโนม มันไม่มีทางไปกันรอดหรอก" },
    },
    [8606] = { -- Decoy!
        title = { "6:631502224:1231988238", "ตัวล่อ!" },
        objective = { "143:221688993:1674572129", "Narain Soothfancy ใน Tanaris ต้องการให้เจ้าเดินทางไป Winterspring แล้ววาง Bag of Gold ที่จุดส่งมอบตามที่พวกลักพาหนังสือระบุไว้" },
        description = { "495:654646263:1945611206", "ข้าคิดออกแล้ว! เราจะทำแบบนี้ ข้าจะใส่ก้อนหินจนเต็มถุง แล้วเจ้าเป็นคนนำไปส่ง ข้ารู้ว่าพวกมันสั่งให้ข้าไปส่งเอง และข้าก็จะไป... ในบางความหมาย\n\n<Narain มองเจ้าตั้งแต่หัวจรดเท้า>\n\nใช่ เจ้าใช้ได้พอดี นำผ้าโพกหัว เสื้อคลุม และถุงก้อนหินนี้ไปยังจุดส่งมอบที่ Winterspring\n\nข้ารวมทุกอย่างที่เจ้าต้องใช้ไว้ในชุดพิเศษนี้แล้ว เมื่อพวกมันมารับของ จัดการให้สิ้นซาก! พวกมันจะได้รู้ว่าอย่ามาหาเรื่อง Narain!" },
        completion = { "53:1199195486:1435508788", "ข้าว่าเราอาจประเมินพวกลักพาหนังสือเหล่านี้ต่ำไป" },
    },
    [8620] = { -- The Only Prescription
        title = { "21:1717380012:964561472", "ทางแก้เพียงหนึ่งเดียว" },
        objective = { "196:1773801441:1763838858", "ตามหา Draconic for Dummies ทั้ง 8 บทที่หายไป แล้วใช้ Magical Book Binding รวมเข้าด้วยกัน นำ Draconic for Dummies: Volume II ฉบับสมบูรณ์กลับไปให้ Narain Soothfancy ใน Tanaris" },
        description = { "468:120376719:258511094", "ข้าควรรู้อยู่แล้ว Doctor Weavil ศัตรูคู่อาฆาตของข้า กลับมาใช้ลูกไม้เดิม! และเพราะความล้มเหลวของเจ้าที่ Winterspring ตอนนี้ Doctor Weavil ทำลายหนังสือของข้าไปแล้ว! คราวนี้เจ้าจะกอบกู้โลกอย่างไรล่ะ ผู้กล้า?\n\nจดหมายที่ข้าได้รับบอกว่า \"Draconic for Dummies: Volume II\" ฉบับเดียวที่รู้ว่ามีอยู่ ถูกฉีกเป็น 8 ส่วนแล้วกระจัดกระจายไปตามลม! หากเจ้าหาบทที่หายไปเหล่านั้นพบได้ จงใช้ปกเย็บเล่มวิเศษนี้ประกอบมันกลับเข้าด้วยกัน แล้วกลับมาหาข้า" },
        progress = { "126:645776108:822142736", "ข้าก็สวมกางเกงเหมือนเจ้า ทีละขา แต่ต่างกันตรงที่พอข้าสวมกางเกงแล้ว ข้าสร้างทุ่นอาร์เคไนต์ ทุ่นอาร์เคไนต์เชียวนะ!" },
        completion = { "218:1412864481:802342064", "ยอดเยี่ยม! ไม่อยากเชื่อว่าเจ้าจะยอมลำบากขนาดนั้น! เจ้าเป็นเครื่องจักรหรืออย่างไร? หากเป็นข้า คงปล่อยให้โลกล่มสลายไปแล้ว\n\nข้าขอยกผ้าโพกหัวคำนับท่าน และความดีไม่ควรไร้สิ่งตอบแทน" },
        required = { [21111] = { "31:830133668:2124057288", "ภาษามังกรสำหรับมือใหม่ เล่ม 2" } },
        objectiveLabels = {
            item = { ["Draconic For Dummies: Volume II"] = "ภาษามังกรสำหรับมือใหม่ เล่ม 2" },
        },
    },
    [8728] = { -- The Good News and The Bad News
        title = { "30:866570019:1160031627", "ข่าวดีและข่าวร้าย" },
        objective = { "135:1414351711:557317231", "Narain Soothfancy ใน Tanaris ต้องการให้เจ้านำ Arcanite Bar 20 แท่ง, Elementium Ore 10 ก้อน, Azerothian Diamond 10 เม็ด และ Blue Sapphire 10 เม็ดไปให้เขา" },
        description = { "484:2061361605:468230549", "เอาล่ะ ใช้เวลานานกว่าที่คิดนิดหน่อย ไหนข้าดูซิว่าบัญชีเล่มนี้เขียนว่าอย่างไร\n\n<Narain อ่านบัญชีเงียบ ๆ และพึมพำเป็นระยะ>\n\nข่าวดีคือ ข้ามั่นใจ 99% ว่าข้าสามารถสร้างทุ่นอาร์เคไนต์ที่ทำงานได้ตามข้อกำหนดของเจ้า แน่นอนว่าทั้งหมดนี้ขึ้นอยู่กับข่าวร้าย\n\nข่าวร้ายคือ ข้าต้องใช้อาร์เคไนต์ แร่เอลิเมนเทียม และอัญมณีหายากจำนวนมาก\n\nนำสิ่งที่ข้าต้องการมา แล้วข้าจะสร้างทุ่นให้" },
        progress = { "43:1235094634:412412481 N 39:1683223883:1978903920", "ทุ่นอาร์เคไนต์ไม่ได้สร้างตัวเองได้นะ {name} และไม่ เจ้ายืมเงินไม่ได้" },
        completion = { "75:212698250:85482772 N 67:699622274:1478667338", "ตกลงกันแล้วก็ต้องตามนั้น ข้าหวังจริง ๆ ว่าเจ้ารู้ว่าตัวเองกำลังเข้าไปยุ่งกับอะไร {name} นี่มันยุ่งยากเหลือเกินสำหรับการออกไปตกปลา" },
        required = { [12360] = { "12:582063918:1116898133", "แท่งอาร์คาไนต์" }, [18562] = { "14:840460621:1776270284", "แร่เอเลเมนเทียม" }, [12800] = { "18:1398536143:412119698", "เพชรแห่ง Azeroth" }, [12361] = { "13:366433083:1620162146", "ไพลินสีน้ำเงิน" } },
        objectiveLabels = {
            item = { ["Arcanite Bar"] = "แท่งอาร์คาไนต์", ["Elementium Ore"] = "แร่เอเลเมนเทียม", ["Azerothian Diamond"] = "เพชรแห่ง Azeroth", ["Blue Sapphire"] = "ไพลินสีน้ำเงิน" },
        },
    },
    [8921] = { -- The Ectoplasmic Distiller
        title = { "25:468515885:892306390", "เครื่องกลั่นสารวิญญาณ" },
        objective = { "151:1302380430:571887240", "กลับไปหา Mux Manascrambler ที่ Gadgetzan พร้อม Delicate Arcanite Converter 1 ชิ้น, Greater Eternal Essence 4 ชิ้น, Stonescale Oil 10 ขวด, Volcanic Ash 25 กอง และเงิน 40 โกลด์" },
        description = { "296:94732341:749239215 N 195:832810139:1967960649", "อา เจ้าต้องการผลงานล่าสุดของข้า... เครื่องเผยวิญญาณต่างมิติ! แต่น่าเสียดายที่ข้าหมดทั้งทุนและกำลังคนแล้ว\n\nเจ้ายินดีช่วยหรือ? ยอดเยี่ยม! งานแรกของเราคือสร้างอุปกรณ์ที่เก็บเนื้อสารแห่งความตายได้! การสร้างเครื่องกลั่นสารวิญญาณไม่ใช่งานง่ายนะ {name}\n\nข้าต้องการให้เจ้านำตัวแปลงอาร์เคไนต์ แก่นพลัง Eternal ระดับสูง และน้ำมัน Stonescale มาให้ ข้ายังต้องใช้เถ้าภูเขาไฟจากแอ่งลาวาใน Burning Steppes เพื่อสร้างตัวกรองด้วย" },
        progress = { "107:320359954:628575000", "ข้ารู้ว่าวัตถุดิบแพงอยู่สักหน่อย... แต่ข้ารับรองว่าทุกชิ้นจำเป็นทั้งนั้น!" },
        completion = { "62:359665090:650912397 N 125:578759803:427913936", "นี่คือวัตถุดิบที่ข้าต้องการพอดี ทันเวลาทีเดียว {name}!\n\nอีกเพียงครู่เดียว เครื่องกลั่นของเจ้าก็จะพร้อมใช้งาน! ระหว่างนี้ รับนี่ไปเป็นรางวัลที่ช่วยโครงการของข้า" },
        required = { [16006] = { "27:1548045084:1187126036", "ตัวแปลงอาร์คาไนต์ชนิดละเอียด" }, [16203] = { "23:250631498:389644982", "แก่นพลังนิรันดร์ขั้นสูง" }, [13423] = { "14:90014186:918690539", "น้ำมันปลาไหลเกล็ดหิน" }, [22338] = { "12:1499799259:425172098", "เถ้าภูเขาไฟ" } },
        objectiveLabels = {
            item = { ["Delicate Arcanite Converter"] = "ตัวแปลงอาร์คาไนต์ชนิดละเอียด", ["Greater Eternal Essence"] = "แก่นพลังนิรันดร์ขั้นสูง", ["Stonescale Oil"] = "น้ำมันปลาไหลเกล็ดหิน", ["Volcanic Ash"] = "เถ้าภูเขาไฟ" },
        },
    },
    [8922] = { -- A Supernatural Device
        title = { "21:1452885910:1981229342", "อุปกรณ์เหนือธรรมชาติ" },
        objective = { "82:930147135:1165819987", "นำ Sealed Blood Container ไปให้ Mux Manascrambler ภายใน Gadgetzan ใน Tanaris" },
        description = { "335:1708832260:1123027407", "ข้าต้องหาวิธีพูดคุยกับ Anthion Harmon... หรือจะให้ชัดก็คือ วิญญาณของเขา!\n\nข้ารู้จักวิศวกรที่สนใจเรื่องเหนือธรรมชาติอย่างแปลก ๆ เขาอ้างว่าสร้างเครื่องจักรที่ทำให้ตนพูดกับผู้ตายได้!\n\nเลือดที่เจ้าเก็บมานั้นตั้งใจจะนำไปให้เขา จงเดินทางไป Gadgetzan แล้วนำมันไปให้เป็นค่าจ้างสำหรับงานของเขา!" },
        progress = { "24:1256598569:1961088590", "เจ้ามีอะไรมาให้ข้าหรือ?" },
        completion = { "63:759110828:1047053830", "ยอดเยี่ยม! ข้ากำลังจะหมดพอดี!\n\nเจ้าบอกว่า Deliana ส่งมาหรือ?" },
    },
    [8924] = { -- Hunting for Ectoplasm
        title = { "21:1911957618:1972196512", "ล่าสารวิญญาณ" },
        objective = { "278:1928653247:2144661168", "ใช้ Ectoplasmic Distiller ใกล้อันเดดที่ไม่มีร่างกาย เพื่อเก็บ Scorched Ectoplasm 12 หน่วยใน Silithus, Frozen Ectoplasm 12 หน่วยใน Winterspring และ Stable Ectoplasm 12 หน่วยใน Eastern Plaguelands นำทั้งหมดพร้อม Ectoplasmic Distiller กลับไปให้ Mux Manascrambler ที่ Gadgetzan" },
        description = { "499:746354237:184459336", "ขอชมตัวเองสักหน่อย นี่เป็นผลงานวิศวกรรมชั้นเยี่ยม! ข้าเกรงว่าเจ้าต้องเดินทางบ้าง เพื่อหาอันเดดไร้ร่างที่เราต้องการ\n\nสภาพอากาศที่ต่างกันทำให้เนื้อสารแห่งวิญญาณของผู้ตายมีลักษณะต่างกัน เหล่าไนต์เอลฟ์ผู้ทุกข์ทรมานใน Silithus วิญญาณไฮบอร์นจาก Winterspring และภูตผีกับแบนชีแห่ง Eastern Plaguelands น่าจะให้สารวิญญาณต่างชนิดตามที่เราต้องการ อย่าลืมวางเครื่องกลั่นไว้ใกล้ ๆ ก่อนเก็บพวกมัน!" },
        progress = { "37:284561874:1978676773 R 1:63:63", "เจ้าเก็บสารวิญญาณมาแล้วหรือยัง {race}?" },
        completion = { "184:1795091158:1153843815", "ใช่ พวกนี้ใช้ได้ดีแน่!\n\nเมื่อดึงพลังต่างภพที่อยู่ในสารเหล่านี้มาใช้ เราจะติดต่อผู้ที่ดวงวิญญาณยังไม่จากโลกนี้ไปอย่างสิ้นเชิงได้!" },
        required = { [21937] = { "18:1492276024:1489503393", "สารวิญญาณไหม้เกรียม" }, [21936] = { "16:149813635:1481857239", "สารวิญญาณแช่แข็ง" }, [21935] = { "16:840754322:1611900491", "สารวิญญาณคงตัว" } },
        objectiveLabels = {
            item = { ["Scorched Ectoplasm"] = "สารวิญญาณไหม้เกรียม", ["Frozen Ectoplasm"] = "สารวิญญาณแช่แข็ง", ["Stable Ectoplasm"] = "สารวิญญาณคงตัว" },
        },
    },
    [8925] = { -- A Portable Power Source
        title = { "23:1311655138:284245098", "แหล่งพลังงานพกพา" },
        objective = { "114:642951556:1419157991", "ตามหา Magma Lord Bokk ใน Burning Steppes เอา Magma Core ของมันมา แล้วนำไปให้ Mux Manascrambler ที่ Gadgetzan" },
        description = { "409:1913672918:409061569", "ต่อไปเราต้องหาแหล่งพลังงานที่เสถียรและพกพาได้ เพื่อคงสภาพสารวิญญาณให้ทำงานต่อ ข้าได้ยินข่าวลือถึงภูตธาตุทรงพลังนามว่า Magma Lord Bokk ซึ่งมีหัวใจเป็นแกนแมกม่าอันทรงพลัง แหล่งความร้อนที่ไม่มีวันหมด!\n\nว่ากันว่าพบมันได้ที่ Burning Steppes ทางใต้ของ Blackrock Mountain นำแกนแมกม่ามาให้ข้า แล้วเราจะมีพลังงานมากพอเดินเครื่องเผยวิญญาณต่างมิติ!" },
        progress = { "31:309669517:352665640 N 1:63:63", "เจ้าพบ Magma Lord แล้วหรือยัง {name}?" },
        completion = { "107:791362532:1524169058", "เจ้าทำสำเร็จแล้ว! นี่จะให้พลังงานมากพอเปิดเครื่องเผยวิญญาณต่างมิติได้แน่นอน!" },
        required = { [21938] = { "10:551718019:1575235506", "แกนแมกมา" } },
        objectiveLabels = {
            item = { ["Magma Core"] = "แกนแมกมา" },
        },
    },
    [8928] = { -- A Shifty Merchant
        title = { "17:1937982903:1528901308", "พ่อค้าเจ้าเล่ห์" },
        objective = { "169:627237979:2030843922", "ตามหาอิมพ์ในถ้ำตรงทางเข้า Darkwhisper Gorge ทางใต้ของ Winterspring ซื้อ Fel Elemental Rod แล้วกลับไปหา Mux Manascrambler ที่ Gadgetzan" },
        description = { "494:2107023060:167867877", "แกนนี้ให้พลังงานพอเดินอุปกรณ์ของเราแล้ว ตอนนี้เหลือเพียงสร้างคทาที่ถ่ายเทพลังงานนั้นได้โดยไม่หลอมละลาย\n\nข้าเคยพบอิมพ์ที่ Winterspring ซึ่งขายของแปลกสารพัด มันมีคทาธาตุที่ใช้ได้เหมาะเจาะ ข้ากำลังโทษตัวเองอยู่เลยที่ตอนนั้นไม่ได้ซื้อมา\n\nมันอาศัยในถ้ำตรงทางเข้า Darkwhisper Gorge ลอบเข้าไปแล้วลองตามหามัน\n\nอย่าให้มันคิดเงินเกินสี่สิบโกลด์นะ นั่นคือราคาที่มันบอกข้าไว้!" },
        progress = { "59:891740547:1326565725", "เจ้าหาอิมพ์ใน Darkwhisper Gorge เจอบ้างหรือยัง?" },
        completion = { "69:1997596731:13243299", "เจ้าทำได้แล้ว! คทานี้เหมาะที่สุด ทีนี้ก็ประกอบทุกอย่างเข้าด้วยกัน..." },
        required = { [21939] = { "17:1901222463:1204764616", "คทาธาตุเฟล" } },
        objectiveLabels = {
            item = { ["Fel Elemental Rod"] = "คทาธาตุเฟล" },
        },
    },
    [1878] = { -- Water Pouch Bounty
        title = { "18:225525763:284143897", "รางวัลแลกถุงน้ำ" },
        progress = { "12:1977868436:1919340288 N 99:1875470694:1952199134", "กลับมาอีกแล้วหรือ {name}? หากเจ้ามีถุงน้ำ Wastewander อีกห้าถุง ข้าก็มีชุดเสบียงเตรียมไว้ให้เจ้า!" },
