        description = { "12:1977868436:1919340288 N 99:1875470694:1952199134", "กลับมาอีกแล้วหรือ {name}? หากเจ้ามีถุงน้ำ Wastewander อีกห้าถุง ข้าก็มีชุดเสบียงเตรียมไว้ให้เจ้า!" },
        required = { [8483] = { "23:1472142363:1396764540", "ถุงน้ำของ Wastewander" } },
        objectiveLabels = {
