    [8555] = { -- The Charge of the Dragonflights
        title = { "31:2122537410:1075556169", "พันธกิจแห่งเหล่ามังกร" },
        completion = { "447:2051575585:1961044678 R 33:772781652:1396739803", "Eranikus, Vaelastrasz และ Azuregos... ข้าไม่สงสัยเลยว่าเจ้ารู้จักมังกรเหล่านี้ ผู้เป็นมรรตัย ดังนั้นจึงไม่ใช่เรื่องบังเอิญที่พวกเขามีบทบาทสำคัญยิ่งในฐานะผู้เฝ้าดูโลกของเรา น่าเสียดาย และความไร้เดียงสาของข้าเองก็มีส่วนผิด ไม่ว่าจะเพราะตัวแทนของเหล่าเทพโบราณ หรือการทรยศจากผู้ที่อ้างตนเป็นสหาย ผู้พิทักษ์แต่ละคนล้วนประสบโศกนาฏกรรม เหตุการณ์เหล่านั้นทำให้ข้ายิ่งไม่ไว้วางใจพวกเจ้า จงไปตามหาพวกเขา... และ {race} จงเตรียมพร้อมสำหรับสิ่งเลวร้ายที่สุด" },
    },
    [8576] = { -- Translating the Ledger
        title = { "22:159228975:868297417", "แปลสมุดบัญชี" },
        completion = { "20:581877837:958427021 N 402:1840443705:1220870337", "ทำเรื่องแรกก่อน {name}! เราต้องหาคำตอบว่า Azuregos เขียนอะไรไว้ในบัญชีเล่มนี้ เจ้าบอกว่าเขาให้สร้างทุ่นอาร์เคไนต์ และนี่คือแบบแปลนหรือ? แปลกที่เขาเขียนเป็นภาษามังกร ตาแก่นั่นก็รู้ว่าข้าอ่านเรื่องพวกนี้ไม่ออก หากจะทำให้สำเร็จ ข้าต้องใช้แว่นพยากรณ์ ไก่หนักห้าร้อยปอนด์ และเล่ม II ของ \"Draconic for Dummies\" ไม่จำเป็นต้องหาตามลำดับนี้หรอก" },
    },
    [8742] = { -- The Might of Kalimdor
        title = { "21:802203622:1925954729", "แสนยานุภาพแห่ง Kalimdor" },
        progress = { "144:1946646875:1027332317 N 242:140013028:1997756196", "หนึ่งพันปีผ่านไปแล้ว และผู้หนึ่งก็ยืนอยู่ตรงหน้าข้าตามชะตากำหนด ผู้ที่จะนำผู้คนของตนสู่ยุคใหม่ เทพโบราณสั่นกลัว {name} โอ้ ใช่ มันหวาดกลัวศรัทธาของเจ้า จงทำลายคำพยากรณ์ของ C'Thun มันรู้ว่าเจ้ากำลังมา ผู้กล้า และแสนยานุภาพแห่ง Kalimdor ก็มาพร้อมเจ้า เพียงบอกข้าเมื่อพร้อม แล้วข้าจะมอบ Scepter of the Shifting Sands ให้" },
        completion = { "54:420981936:1800709730 N 212:1876702301:1699060175", "Scepter of the Shifting Sands กลับมาสมบูรณ์อีกครั้งแล้ว {name} ต้องเป็นเจ้าที่ใช้คทานี้ ต้องเป็นเจ้าที่ประกาศยุคถัดไปของผู้คนของเจ้า เจ้าต้องรอให้กองทัพ Horde และ Alliance มาถึง Silithus ก่อน จึงจะตี Scarab Gong ได้", variants = { { "144:1946646875:1027332317 N 242:140013028:1997756196", "หนึ่งพันปีผ่านไปแล้ว และผู้หนึ่งก็ยืนอยู่ตรงหน้าข้าตามชะตากำหนด ผู้ที่จะนำผู้คนของตนสู่ยุคใหม่\n\nเทพโบราณกำลังสั่นกลัว {name} โอ้ ใช่ มันหวาดกลัวศรัทธาของเจ้า จงทำลายคำพยากรณ์ของ C'Thun\n\nมันรู้ว่าเจ้ากำลังมา ผู้กล้า และแสนยานุภาพแห่ง Kalimdor ก็มาพร้อมกับเจ้า เพียงบอกข้าเมื่อเจ้าพร้อม แล้วข้าจะมอบ Scepter of the Shifting Sands ให้" } } },
        description = { "144:1946646875:1027332317 N 242:1183796889:2077376551", "หนึ่งพันปีผ่านไปแล้ว และผู้หนึ่งก็ยืนอยู่ตรงหน้าข้าตามชะตากำหนด ผู้ที่จะนำผู้คนของตนสู่ยุคใหม่ เทพโบราณสั่นกลัว {name} โอ้ ใช่ มันหวาดกลัวศรัทธาของเจ้า จงทำลายคำพยากรณ์ของ C'Thun มันรู้ว่าเจ้ากำลังมา ผู้กล้า และแสนยานุภาพแห่ง Kalimdor ก็มาพร้อมเจ้า เพียงบอกข้าเมื่อพร้อม แล้วข้าจะมอบ Scepter of the Shifting Sands ให้" },
    },
    [8747] = { -- The Path of the Protector
        title = { "25:1177350616:1891783423", "วิถีผู้พิทักษ์" },
        completion = { "313:304216918:722179965", "น่าประทับใจ ผู้เยาว์ เจ้าผ่านความยากลำบากมามากเพื่อได้รับความโปรดปรานจากฝูงมังกรบรอนซ์ ความทุ่มเทของเจ้าได้รับการยอมรับแล้ว แหวนตราผู้พิทักษ์จะให้การป้องกันที่เหนือกว่าต่อกองกำลังชั่วร้าย จงระวัง เมื่อเลือกวิถีแล้ว เจ้าจะไม่มีทางย้อนกลับหากเปลี่ยนใจ" },
    },
    [8748] = { -- The Path of the Protector
