        progress = { "132:1647824105:1129416687", "การปกป้องเหล่าบุตรแห่ง Kalimdor อย่างต่อเนื่องของเจ้าได้รับการยอมรับแล้ว ส่งแหวนตรามาให้ข้า เพื่อให้ข้าเพิ่มพลังของมัน" },
        completion = { "60:1166097150:586885450 N 53:383746386:1097396299", "การไต่ระดับของเจ้าในหมู่ฝูงมังกรช่างน่าประทับใจ {name} ขอเจ้าอย่าได้หลงออกจากวิถีผู้พิทักษ์!" },
