    [8751] = { -- The Protector of Kalimdor
        title = { "25:1337571377:162399000", "ผู้พิทักษ์แห่ง Kalimdor" },
        progress = { "201:1939564803:229526966", "ข้าไม่เคยเห็นความมุ่งมั่นเช่นนี้! ฝูงมังกรบรอนซ์จะมอบมนตร์เสริมพลังครั้งสุดท้ายให้เจ้า ผู้ไร้กาลเวลาเป็นผู้ร้องขอด้วยตนเอง! ส่งแหวนตรามาให้ข้า เพื่อให้ข้าปรับแต่งตามที่จำเป็น" },
        completion = { "52:835028134:1350837988", "จงลุกขึ้น ผู้พิทักษ์แห่ง Kalimdor! ลุกขึ้นให้ทุกคนประจักษ์!" },
        description = { "201:1939564803:229526966", "ข้าไม่เคยเห็นความมุ่งมั่นเช่นนี้! ฝูงมังกรบรอนซ์จะมอบมนตร์เสริมพลังครั้งสุดท้ายให้เจ้า ผู้ไร้กาลเวลาเป็นผู้ร้องขอด้วยตนเอง! ส่งแหวนตรามาให้ข้า เพื่อให้ข้าปรับแต่งตามที่จำเป็น" },
        required = { [21199] = { "38:1026943139:285988640", "แหวนตราแห่งฝูงมังกรสำริด" } },
        objectiveLabels = {
            item = { ["Signet Ring of the Bronze Dragonflight"] = "แหวนตราแห่งฝูงมังกรสำริด" },
        },
