        title = { "17:1171036956:1963926358", "ดับความกระหาย" },
        objective = { "78:614709159:114849441", "นำ Wastewander Water Pouch 5 ถุงไปให้ Chief Engineer Bilgewhizzle ที่ Gadgetzan" },
        description = { "364:625502049:1543851307", "เจ้าอยากได้แหล่งพลังงาน ข้าช่วยได้ รู้ไหมว่าข้าอยากได้อะไร? ข้าอยากดื่มอะไรสักหน่อย! นำถุงน้ำ Wastewander ห้าถุงมา แล้วข้าจะให้ 4711-FTZ ทีนี้... ลองเดาซิว่าจะหาถุงน้ำ Wastewander ได้จากไหน! ทำไมไม่เดินไปหาพวกเร่ร่อน Wastewander สักคนทางตะวันออก แล้วขอถุงน้ำจากพวกเขาดูล่ะ ได้ผลอย่างไรบอกข้าด้วยนะ" },
        progress = { "64:268177441:1252651308", "เป็นอย่างไร พวกเร่ร่อน \"สมัครใจ\" ยกถุงน้ำให้เจ้าหรือเปล่า?" },
        completion = { "502:1663562216:446797041", "ยอดเยี่ยม แหล่งพลังงานเป็นของเจ้าแล้ว ทีนี้มันไม่ได้ออกแบบมาใช้กับชุดวิทยาศาสตร์แบบนั้นโดยตรง เจ้าจึงมีเวลาจำกัดก่อนที่ข้อมูลทั้งหมดจะระเบิดหายไป! เมื่อเก็บทุกอย่างที่ต้องการสำหรับงานอะไรก็ตามของเจ้าแล้ว นำมาให้ข้า และข้าจะปิดมันอย่างถูกวิธี เจ้าจะมีเวลาอย่างมากสองชั่วโมงเพื่อทำสิ่งที่ต้องทำให้เสร็จ หากทำไม่ทัน ข้าขายแหล่งพลังงานอีกตัวให้ลองใหม่ได้เสมอ เจ้าได้ยินถูกแล้ว ขาย!" },
        required = { [8483] = { "23:1472142363:1396764540", "ถุงน้ำของ Wastewander" } },
        steps = { { "23:1472142363:1396764540", "ถุงน้ำของ Wastewander" } },
    },
    [654] = { -- Tanaris Field Sampling
        title = { "22:1799952865:390019340", "เก็บตัวอย่างภาคสนามใน Tanaris" },
        objective = { "175:400869209:1694732539", "เก็บตัวอย่างที่ผ่านเกณฑ์จากบาซิลิสก์ 8 ตัว ไฮยีนา 8 ตัว และแมงป่อง 8 ตัว นำชุดทดสอบกลับไปให้ Chief Engineer Bilgewhizzle ที่ Gadgetzan ก่อนแหล่งพลังงานจะหมด" },
        description = { "412:628903171:1998851414", "เมื่อเปิดแหล่งพลังงาน ชุดทดสอบภาคสนามก็เริ่มเรืองแสงและสั่น ดูเหมือนจะทำงานตามแผน Chief Engineer Bilgewhizzle บอกว่าตอนนี้เจ้ามีเวลาสองชั่วโมงเก็บข้อมูลที่ต้องการในทะเลทราย Tanaris หากเก็บไม่ทันภายในสองชั่วโมง ข้อมูลทั้งหมดจะสูญหาย และต้องซื้อแหล่งพลังงานอีกตัวจากเขา กลับไปหาเขาเมื่อทำงานเสร็จแล้ว" },
        progress = { "366:1628755203:1886166113", "เป็นอย่างไร เจ้าได้ทุกอย่างที่ต้องการแล้วหรือยัง? หากยังไม่ได้แล้วพลังงานหมด ทุกอย่างข้างในจะพังและเจ้าต้องเริ่มใหม่ เฮ้ อย่ามาหวังความเห็นใจจากข้า ข้าสนใจแต่ทำกำไรให้บริษัทน้ำ Gadgetzan และถ้านั่นหมายถึงการขายแหล่งพลังงานให้เจ้า จนเรามีเงินนำเข้าน้ำจากตาน้ำเย็นจัดแห่ง Dun Morogh ได้ ก็เอาตามนั้น!" },
        completion = { "180:48904069:1074935487", "เอาล่ะ ข้าใช้เวลาเพียงครู่เดียวถอดแหล่งพลังงานออก หลังจากนั้นเจ้าจะทำอย่างไรกับชุดทดสอบก็ได้ โดยไม่ต้องกังวลว่าข้อมูลข้างในจะหาย" },
        required = { [9440] = { "26:1737390303:920258657", "ตัวอย่างบาซิลิสก์ที่ใช้ได้" }, [9441] = { "23:880869187:2132037137", "ตัวอย่างไฮยีนาที่ใช้ได้" }, [9438] = { "25:1693509258:521159835", "ตัวอย่างแมงป่องที่ใช้ได้" }, [8523] = { "17:874435004:1884063455", "ชุดทดสอบภาคสนาม" } },
        steps = { { "26:1737390303:920258657", "ตัวอย่างบาซิลิสก์ที่ใช้ได้" }, { "23:880869187:2132037137", "ตัวอย่างไฮยีนาที่ใช้ได้" }, { "25:1693509258:521159835", "ตัวอย่างแมงป่องที่ใช้ได้" }, { "17:874435004:1884063455", "ชุดทดสอบภาคสนาม" } },
    },
    [841] = { -- Another Power Source?
        title = { "21:1070628318:891492386", "แหล่งพลังงานอีกตัวหรือ?" },
        objective = { "116:1969091766:1681331421", "นำ Wastewander Water Pouch 10 ถุงไปให้ Chief Engineer Bilgewhizzle ที่ Gadgetzan เพื่อแลกแหล่งพลังงานอีกตัว" },
        description = { "337:1234933342:1055558838 N 110:1537380488:676485959", "ขอเดานะ เจ้าไปทำเรื่องชั่วร้ายที่จะทำให้โลกล่มสลายไม่ทันเวลา ไม่สิ รู้แล้ว... เจ้าทำมันหล่นในทราย! เอาเถอะ ไม่ว่าเหตุผลใด ข้ามีแหล่งพลังงานเพิ่มขายให้เจ้า แต่คราวนี้ต้องใช้ถุงน้ำ Wastewander สิบถุง ใช่ สิบถุง! ทุกคนต่างลำบาก {name} และแหล่งพลังงานไม่ได้งอกบนต้นไม้! อืม แต่ถ้ามันงอกได้ล่ะ บางทีเราอาจสร้างต้นแหล่งพลังงานได้..." },
        progress = { "41:68837675:1993638384", "เป็นอย่างไร เจ้าได้ถุงน้ำสิบถุงแล้วหรือยัง?" },
        completion = { "171:1843908900:1587789990", "ดีมาก นี่คือแหล่งพลังงานอีกตัว ข้าแนะนำอย่างยิ่งให้เจ้าใช้มันให้ถูกต้องในคราวนี้ เว้นแต่จะอยากเสียถุงน้ำอีกสิบถุงเพื่อซื้อแหล่งพลังงานอีกตัว" },
        required = { [8483] = { "23:1472142363:1396764540", "ถุงน้ำของ Wastewander" } },
        objectiveLabels = {
            item = { ["Wastewander Water Pouch"] = "ถุงน้ำของ Wastewander" },
        },
    },
    [5802] = { -- Fire Plume Forged
        title = { "17:6167297:162211471", "หลอมที่ Fire Plume" },
        objective = { "269:665410803:1112093051", "นำ Skeleton Key Mold และ Thorium Bar 2 แท่งไปยังยอด Fire Plume Ridge ใน Un'Goro Crater ใช้ Skeleton Key Mold ข้างทะเลสาบลาวาเพื่อหลอม Unfinished Skeleton Key นำ Unfinished Skeleton Key ไปให้ Apothecary Dithers ที่ The Bulwark ใน Western Plaguelands" },
        description = { "496:604688112:1137829118", "เจ้าต้องใช้ธอเรียมสองแท่งกับแหล่งความร้อนอันรุนแรงเพื่อหลอมแกนกุญแจ เรื่องธอเรียมเจ้าต้องหาเอง แต่เรื่องความร้อนข้าช่วยได้ ทางตะวันตกของเราใน Un'Goro Crater คือ Fire Plume Ridge ภูเขาไฟที่ยังคุกรุ่น ทะเลสาบลาวาบนยอดร้อนพอจะหลอมธอเรียมเข้ากับกระดูกได้ เงินของเจ้าซื้อแม่พิมพ์ที่เพียงนำไปจุ่มในทะเลสาบบนยอด ลาวาจะจัดการที่เหลือเอง ส่วนของข้าจบเท่านี้ หากจะทำกุญแจให้เสร็จ เจ้าต้องกลับไปคุยกับ Dithers อีกครั้ง" },
        progress = { "430:1773769583:1134896824", "เจ้าทำแกนกุญแจเสร็จแล้วหรือ? ข้าเสียใจจริง ๆ ที่เจ้าต้องรับภาระค่าซื้อแม่พิมพ์ แต่เราทุกคนต้องทำหน้าที่ของตนเพื่อต่อต้าน Scourge เมื่อเจ้าส่งกุญแจที่ยังไม่เสร็จมาให้ข้า เจ้าจะพร้อมสำหรับของชิ้นสุดท้ายที่ต้องใช้สร้างมันให้สมบูรณ์ มันจะไม่ง่ายเลย แต่งานที่เจ้าทำมาเพื่อเตรียมบุก Andorhal กำลังจะเริ่มให้ผลตอบแทน เจ้าจะได้เห็น" },
        completion = { "56:656105994:1786244628 N 369:632458948:1532319665", "กุญแจดอกนี้ช่างราคาแพงจริง ๆ ว่าไหม {name}? แต่ก็ยังไม่เสร็จ ถึงเวลาหาจุดรวมพลังให้กับสิ่งที่เราสร้าง เพื่อการนั้น เจ้าต้องเผชิญศัตรูตัวฉกาจที่เราเตรียมรับมือมาตลอดใน Andorhal... สิ่งมีชีวิตที่บงการทุกอย่างภายในกำแพงเมืองร้าง ข้าหมายถึง Araj the Summoner ลิชผู้เป็นหนึ่งในสิ่งมีชีวิตที่ทรงพลังที่สุดของ Scourge" },
        required = { [14645] = { "23:325777604:865141534", "กุญแจโครงกระดูกที่ยังทำไม่เสร็จ" } },
        objectiveLabels = {
            item = { ["Unfinished Skeleton Key"] = "กุญแจโครงกระดูกที่ยังทำไม่เสร็จ" },
        },
    },
    [8923] = { -- A Supernatural Device
        title = { "21:1452885910:1981229342", "อุปกรณ์เหนือธรรมชาติ" },
        objective = { "66:1650517199:125255239", "นำ Sealed Venom Container ไปให้ Mux Manascrambler ที่ Gadgetzan" },
        description = { "501:1175237474:1928305750", "เจ้าต้องกล้ามากทีเดียวที่ยังอยู่ต่อหลังจากเรื่องนั้น หรือไม่ก็ชุดเกราะชิ้นที่ข้าให้ทำให้เจ้าสนใจ ยังมีของจากที่เดียวกันอีก หากเจ้ายังอยากช่วยข้า ตัวอย่างพิษที่เจ้าเก็บมาเป็นของสำหรับคนรู้จักของข้า Mux Manascrambler วิศวกรผู้สนใจเรื่องเหนือธรรมชาติ โครงการล่าสุดของเขาคืออุปกรณ์ที่ทำให้เจ้าติดต่อผู้ตายได้! ความหวังสุดท้ายของข้าคือติดต่อ Anthion แล้วหาคำตอบเพิ่มเติมเกี่ยวกับสถานการณ์ของตน" },
        progress = { "24:1232962866:1656493369", "เจ้าอยากคุยกับข้าหรือ?" },
        completion = { "62:1356085917:709732774", "ยอดเยี่ยม! ข้ากำลังจะหมดพอดี! เจ้าบอกว่า Mokvar ส่งมาหรือ?" },
    },
    [8417] = { -- A Troubled Spirit
        title = { "17:390213816:371646326", "วิญญาณทุกข์ร้อน" },
        objective = { "77:522782855:1078972668", "คุยกับ Fallen Hero of the Horde ที่ทางเข้า Blasted Lands" },
        description = { "181:1618713845:1456442706", "ใน Blasted Lands มีวิญญาณทุกข์ร้อนที่ครั้งหนึ่งเป็นวีรชนยิ่งใหญ่แห่ง Horde เกียรติของนักรบไม่ตายตามกาย การไปคุยกับเขาจะเป็นประโยชน์ต่อเจ้า" },
        progress = { "29:1619010550:1536618647", "Stoley ยอมส่งเหล้าของข้ามาหรือยัง?" },
        completion = { "108:523116705:706569633", "เจ้ามาเพื่อบรรเทาความเจ็บปวดข้า ข้าหวังว่าเจ้าจะเพียงฟาดฟันให้ข้าดับสูญได้ แต่ไม่ง่ายเช่นนั้น..." },
    },
    [974] = { -- Finding the Source
        title = { "18:1597529010:1591445177", "ตามหาต้นกำเนิด" },
        objective = { "209:668316949:1048550195", "Krakle ใน Un'Goro Crater ต้องการให้เจ้าหาบริเวณที่ร้อนที่สุดของ Fire Plume Ridge เมื่อพบจุดร้อน ให้คลิกขวาเครื่องวัดอุณหภูมิเพื่อตรวจค่า ค้นหาต่อไปจนพบจุดที่ร้อนที่สุด" },
        description = { "466:1069266891:665510534", "น้ำพุร้อนที่นี่เป็นปริศนาสำหรับข้า ความร้อนมาจากไหน? เมื่อดูว่าแอ่งน้ำอยู่ใกล้ Fire Plume Ridge เพียงใด ข้าก็สงสัยจริง ๆ ว่าภูเขาไฟอาจเกี่ยวข้อง ข้าสร้างเครื่องวัดอุณหภูมิไว้ตรวจค่าต่าง ๆ ที่ภูเขาไฟ และอยากหาส่วนที่ร้อนที่สุด มันวัดเป็นองศา Kraklenheit! นี่ รับไป แล้วตรวจอุณหภูมิตามแนวสันเขาทุกครั้งที่เห็นจุดร้อน!" },
        progress = { "77:617117603:1006586031", "ข้าคงไปเองแล้ว แต่... ข้ากลัวภูตไฟที่นั่นอยู่นิดหน่อย!" },
        completion = { "238:117978693:1146631817", "ใช่ ข้าเห็นความสัมพันธ์ระหว่างอุณหภูมิภูเขาไฟกับน้ำพุร้อนอย่างชัดเจนแล้ว ข้าต้องตรวจสมการซ้ำเพื่อความแม่นยำ แต่ดูเหมือนระยะทางกับอัตราการถ่ายเทความร้อน... อืม..." },
    },
    [980] = { -- The New Springs
        title = { "15:922548418:1842017506", "น้ำพุร้อนแห่งใหม่" },
        objective = { "53:1295195564:14866925", "เดินทางไป Winterspring แล้วคุยกับ Donova Snowden" },
        description = { "429:1453959996:499401512", "ทีนี้ ข้าได้ยินเรื่องน้ำพุร้อนแห่งอื่นในสถานที่ที่เรียกว่า Winterspring ไกลออกไปทางเหนือ สิ่งที่แปลกคือ ไม่มีภูเขาไฟอยู่ใกล้เลย น่าสนใจใช่ไหมล่ะ หากเจ้าอยากรู้เพิ่มเติม ก็ควรไป Winterspring แล้วคุยกับสหายของข้า นางชื่อ Donova Snowden และตอนนี้พักอยู่ใกล้น้ำพุร้อนที่นั่น ขอบใจอีกครั้งที่ช่วยทดสอบเครื่องวัดอุณหภูมิของข้า! แล้วพบกัน!" },
        completion = { "10:513960754:1207103972 N 38:1193256618:62728843", "สวัสดี {name} ใช่แล้ว สิ่งที่ Krakle บอกเจ้าเป็นความจริง..." },
    },
    [3844] = { -- It's a Secret to Everybody
        title = { "26:1717948097:782939729", "ความลับที่ไม่มีใครรู้" },
        objective = { "77:12606536:477213934", "สำรวจรอบ ๆ ในสระน้ำเพื่อหาเบาะแสว่าแพที่พังนี้อาจเป็นของใคร" },
        description = { "277:681524332:1510511042", "แพที่พังยับเยินลำหนึ่งเกยอยู่ริมฝั่ง เมื่อพิจารณาว่านี่เป็นเพียงสระเล็ก ๆ ก็ไม่ชัดเจนว่ามันมาอยู่ที่นี่ได้อย่างไร แต่เมื่อมองต้นไม้ ก็เห็นว่าระดับน้ำอาจไม่คงที่ บางทีการสำรวจบริเวณนี้สักหน่อยอาจเผยเบาะแสเพิ่มเติม..." },
        completion = { "52:740589077:1662862698", "กระเป๋าที่เปียกชุ่มน้ำวางอยู่ก้นสระ" },
    },
    [3845] = { -- It's a Secret to Everybody
        title = { "26:1717948097:782939729", "ความลับที่ไม่มีใครรู้" },
        objective = { "64:233351779:1914587988", "ตรวจดูสิ่งของในกระเป๋า แล้วนำไปคืนเจ้าของ" },
        description = { "245:1263283961:657627346", "เจ้าคว้ากระเป๋าแล้วลากกลับขึ้นฝั่ง บางทีเมื่อตรวจดูของข้างใน เจ้าอาจรู้เพิ่มเติมว่ามันเป็นของใคร มีนักเดินทางหลงมาพักอยู่ที่ Marshal's Refuge ไม่กี่คน บางทีเจ้าอาจหาคำตอบได้มากขึ้นที่นั่น" },
        progress = { "44:645723070:453625560", "สวัสดี ข้าเคยเห็นเจ้ามาก่อน... ใช่ไหม?" },
        completion = { "60:112921931:1514386227", "โอ้... ใช่ ของพวกนี้ดูคุ้นตาอยู่... ก็ประมาณนั้น..." },
        required = { [11104] = { "13:619690413:1075483819", "เข็มทิศขนาดใหญ่" }, [11105] = { "20:731713729:1461009487", "แผ่นหนังแผนที่ม้วนงอ" }, [11106] = { "15:1416489215:1422113580", "กุญแจหัวสิงโต" } },
        objectiveLabels = {
            item = { ["Large Compass"] = "เข็มทิศขนาดใหญ่", ["Curled Map Parchment"] = "แผ่นหนังแผนที่ม้วนงอ", ["Lion-headed Key"] = "กุญแจหัวสิงโต" },
        },
    },
    [3881] = { -- Expedition Salvation
        title = { "20:1401587757:1408724680", "กู้วิกฤตคณะสำรวจ" },
        objective = { "89:419291089:1710667354", "นำ Crate of Foodstuffs และ Research Equipment ไปให้ Williden Marshal ใน Un'Goro Crater" },
        description = { "495:700190977:391045202", "ข้าไม่รู้ว่าเจ้ามาถึงที่นี่ได้อย่างไร แต่เห็นเจ้าแล้วชื่นใจจริง ๆ! ข้าคือ Williden Marshal ผู้นำคณะสำรวจที่ไม่ขึ้นกับฝ่ายใด การเดินทางครั้งล่าสุดและยิ่งใหญ่ที่สุดของเราเจอหายนะนับไม่ถ้วน เรื่องร้ายแรงที่สุดคือเราประเมินความดุร้ายของ Un'Goro Crater ต่ำไป! ตอนหนีจากค่ายฐานทางตะวันตกเฉียงใต้และตะวันออกเฉียงเหนือของปล่องภูเขาไฟ เราทิ้งเสบียงสำคัญไว้ เจ้าดูมีความสามารถพอ จะช่วยนำมันกลับมาให้เราได้ไหม?" },
        progress = { "202:1287083512:1209600704", "หากเราจะมีโอกาสรอดออกจากที่นี่ ก็ต้องมีลังเสบียงอาหารใบใหญ่ของเรา และหากได้อุปกรณ์วิจัยกลับมาอย่างน้อยบางส่วน ก็คงเป็นพรท่ามกลางทะเลแห่งความทุกข์นี้" },
        completion = { "363:183375799:1436428935 N 46:1650284700:893338030", "เจ้านำทั้งอาหารและอุปกรณ์วิจัยกลับมาได้! เจ้าไม่ได้ช่วยเพียงคณะสำรวจ แต่ช่วยชีวิตพวกเราด้วย ข้ากับทุกคนในทีมขอบคุณเจ้าเท่าไรก็ไม่พอ เพราะเจ้า ตอนนี้เราอาจอยู่รอดที่นี่ต่อได้อีกพัก แม้เรามีไม่มาก แต่ข้าจะไม่ปล่อยเจ้าให้มือเปล่าสำหรับความช่วยเหลืออันประเมินค่าไม่ได้ ขอบใจ {name} เจ้ามีสหายอยู่ในคณะสำรวจ Marshal แล้ว!" },
        required = { [11113] = { "19:1889948802:1202088142", "ลังเสบียงอาหาร" }, [11112] = { "18:785028823:1933476555", "อุปกรณ์วิจัย" } },
        steps = { { "19:1889948802:1202088142", "ลังเสบียงอาหาร" }, { "18:785028823:1933476555", "อุปกรณ์วิจัย" } },
    },
    [3882] = { -- Roll the Bones
        title = { "14:518787304:1485221433", "เสี่ยงตายหากระดูก" },
        objective = { "59:1646858038:1366677307", "นำ Dinosaur Bone 8 ชิ้นไปให้ Spark Nilminer ใน Un'Goro Crater" },
        description = { "496:515026662:1274724365", "เจ้าคงคิดว่าการเป็นหัวหน้าคนขุดของคณะสำรวจ Marshal หมายความว่าข้าชอบขุด ในโลกนี้อาจมีงานที่แย่กว่านี้... แต่ข้านึกไม่ออกจริง ๆ เราควรจะขุดหา stegodon กับ diemetradon ที่ตายแล้วใน Terror Run ช่างเป็นชื่อที่วิเศษจริง ๆ ว่าไหม แต่ที่นั่นก็มีตัวเป็น ๆ อยู่เพียบด้วย! Wil กับ Hol ยังมุ่งมั่นจะศึกษากับดักมรณะนี่ เราจึงต้องใช้กระดูกไดโนเสาร์เหล่านั้น แต่บอกกันตามตรง เอามาจากตัวเป็น ๆ ก็ใช้ได้เหมือนกัน" },
        progress = { "285:160859289:1216539658", "เจ้าจะคิดอย่างไรกับข้าก็เชิญ แต่พวกเขาไม่สนหรอกว่ากระดูกที่ได้ไปวิจัยมาจาก stegodon กับ diemetradon โบราณ หรือมาจากพวกที่แทบจะเขมือบเราทั้งกลุ่มตอนตั้งค่าย ข้าขอแค่ได้ออกจากที่นี่อย่างมีชีวิตก็พอ..." },
        completion = { "373:1111940716:890179638", "ยอดเยี่ยม พวกนี้น่าจะใช้ได้ ทีนี้ ขออนุญาตนะ... ขอบใจที่ขุดกระดูกทั้งหมดนี้ขึ้นจากพื้นให้เรา โดยไม่ทำร้ายสัตว์พื้นถิ่นแม้แต่น้อย ไม่ว่าเจ้าจะทำเช่นนั้นจริงหรือไม่ ข้าก็ไม่อยากรู้ ปล่อยให้เป็นเช่นนั้นต่อไปดีไหม? นี่ บางทีของนี่อาจช่วยให้เจ้าปิดปากเรื่องทั้งหมดได้ ข้าว่าทำอะไรก็ได้ให้รอดออกไปก็พอ!" },
        required = { [11114] = { "13:1332735849:1486914831", "กระดูกไดโนเสาร์" } },
        steps = { { "13:1332735849:1486914831", "กระดูกไดโนเสาร์" } },
    },
    [3883] = { -- Alien Ecology
        title = { "13:1251681401:185685450", "นิเวศวิทยาต่างถิ่น" },
        objective = { "231:797876430:1598493579", "ใช้ Scraping Vial เก็บ Hive Wall Sample จากห้องฟักตัวอ่อนแห่งหนึ่งในรัง Gorishi ที่ Un'Goro Crater มองหาห้องที่มีตัวอ่อนห้อยอยู่ แล้วนำ Hive Wall Sample ไปให้ Hol'anyee Marshal ใน Un'Goro Crater" },
        description = { "490:706380885:944687096", "แค่เราเจออุปสรรค ไม่ได้หมายความว่าต้องหยุดวิจัย! ก่อนจะมาลงเอยที่นี่ เรากำลังศึกษาแมลง Gorishi ทางใต้ของปล่องภูเขาไฟ พวกมันแปลกปลอมต่อระบบนิเวศ Un'Goro และเราอยากรู้ว่าเพราะอะไร ภายในเครือข่ายรังต้องมีห้องฟักตัวอ่อน เจ้าสังเกตได้จากตัวอ่อนที่ห้อยอยู่ ใช้ขวดนี้เก็บตัวอย่างผนังรังใกล้ห้องฟักแห่งใดก็ได้ แล้วนำกลับมาให้ข้าศึกษา แต่ระวังด้วย!" },
        progress = { "60:1066615553:320557093 N 1:63:63", "เจ้ามีตัวอย่างรัง Gorishi มาให้ข้าศึกษาแล้วหรือยัง {name}?" },
        completion = { "291:468872009:1370682611", "ใช่ นี่ใช้ได้ดี เจ้าช่วยไว้มาก... ข้าอยากให้อะไรเจ้ามากกว่านี้ แต่การติดอยู่กลางแดนเถื่อนแทบไปไหนไม่ได้ ก็จำกัดสิ่งที่ข้าจะให้ได้เหมือนกัน แต่จงมั่นใจเถิด งานวิจัยที่นี่คงเกิดขึ้นไม่ได้หากปราศจากความช่วยเหลือของเจ้า!" },
        required = { [11131] = { "16:465970579:386435414", "ตัวอย่างผนังรัง" } },
        objectiveLabels = {
            item = { ["Hive Wall Sample"] = "ตัวอย่างผนังรัง" },
        },
    },
    [3884] = { -- Williden's Journal
        title = { "18:1508290373:2047998659", "บันทึกของ Williden" },
        objective = { "67:786746217:843373283", "นำบันทึกไปคืน Williden Marshal ที่อยู่สักแห่งใน Un'Goro Crater" },
        description = { "378:1868654908:1570082962", "เจ้าพบบันทึกที่ฉีกขาดยับเยิน บางส่วนยังอ่านได้ โดยมีชื่อ Williden Marshal ระบุว่าเป็นเจ้าของเนื้อหาข้างใน หากบันทึกถูกต้อง อาจพบ Williden ได้ทางตอนเหนือของปล่องภูเขาไฟ ตามที่เขียนไว้ เขากับเพื่อนร่วมทางหาที่สูงหลบหนีสัตว์ดุร้าย หลังจากค่ายฐานถูกบุกยึด" },
        progress = { "150:1509749237:858204368", "สวัสดี! ข้ากับเพื่อนร่วมทางดีใจที่ได้เห็นสิ่งมีชีวิตอื่นที่ไม่ใช่สัตว์ยักษ์ดุร้ายบ้าง! อะไรพาเจ้ามายัง Un'Goro Crater?" },
        completion = { "157:2140118792:702570345", "ดูนี่สิ บันทึกของข้า! ข้านึกว่าหายไปแล้ว เช่นเดียวกับข้าวของแทบทุกอย่างที่เรานำเข้ามาใน Un'Goro ขอบคุณมากที่นำมาคืน!" },
    },
    [3908] = { -- It's a Secret to Everybody
        title = { "26:1717948097:782939729", "ความลับที่ไม่มีใครรู้" },
        objective = { "54:992230489:1091223871", "นำ Linken's Sword ไปให้ Donova Snowden ที่ Winterspring" },
        description = { "497:1655056489:223658455", "คืออย่างนี้ ข้าไม่รู้เลยว่ามาอยู่ที่นี่ได้อย่างไร ไม่มีใครรู้จริง ๆ มันเป็นความลับสำหรับทุกคน! ข้าดูเหมือนจะจำอะไรไม่ได้เลย... แต่ของที่เจ้านำมาให้... ข้าเริ่มนึกอะไรออก ดาบของข้า ข้าควรจะหาวิธีเพิ่มพลังให้มัน แต่ไม่แน่ใจจริง ๆ ว่าเพราะอะไร ขอโทษที่บอกไม่ได้มากกว่านี้ ข้าจำไม่ได้! อย่างไรก็ตาม ข้ารู้ว่าเจ้านำมันไปหาใครได้ Donova Snowden ที่ Winterspring เจ้าจะพบนางใกล้น้ำพุร้อน นางชุบดาบด้วยแอ่งน้ำที่นั่นได้" },
        progress = { "67:1535793758:1524898358", "อ้าว... ในที่สุด Linken ก็ส่งดาบของเขามาให้ข้าเสียที" },
        completion = { "160:1989339714:38347171", "แน่นอน ข้าชุบดาบเล่มนี้ได้ ระหว่างข้าทำงาน เจ้าก็อธิบายได้ว่าทำไม Linken ถึงใช้เวลานานนักกว่าจะส่งมา ปกติเขาไม่ใช่คนขี้ลืม..." },
        required = { [11133] = { "23:1077624891:1572103485", "ดาบฝึกของ Linken" } },
        steps = { { "23:1077624891:1572103485", "ดาบฝึกของ Linken" } },
    },
    [3912] = { -- Meet at the Grave
        title = { "17:1823976872:133760539", "นัดพบที่สุสาน" },
        objective = { "124:1530935317:1920915536", "ไปยังสุสานนอก Gadgetzan แล้วใช้ Videre Elixir ทำตามคำแนะนำที่เหลือของ Donova เพื่อหา Gaeriyan" },
        description = { "498:1300624675:1508013910", "น้ำยานี้จะทำให้เจ้าพูดคุยกับผู้ที่ปกติแล้วเจ้ามองไม่เห็นด้วยซ้ำ... นำ Videre Elixir พร้อมดาบของ Linken ไปยังสุสานนอก Gadgetzan ใน Tanaris เมื่อไปถึง ให้ดื่มน้ำยา ผลที่เกิดขึ้นอาจทำให้เจ้าประหลาดใจ แต่อย่าตกใจ ใน \"อีกร่าง\" ของเจ้า ให้มุ่งตรงไปทางเหนือจนถึงภูเขา เจ้าจะพบผู้ที่ต้องพูดคุยด้วยในซอกหินแห่งหนึ่ง เขาชื่อ Gaeriyan จำไว้ว่าเขาจะพูดกับเจ้าเฉพาะตอนอยู่ในร่างนั้น..." },
        completion = { "55:1562301748:1961684875", "นานแล้วที่ไม่มีใครมาพูดคุยกับข้า..." },
    },
    [3913] = { -- A Grave Situation
        title = { "17:653268138:40410933", "เรื่องร้ายที่สุสาน" },
        objective = { "71:576490171:1676012904", "คืนชีพ แล้วมองหาป้ายหลุมศพที่ Gaeriyan บอกให้เจ้าตามหา" },
        description = { "32:1395131550:1229928420 N 184:888841388:1359971259", "หากเจ้ากลับไปยังสุสาน {name} จะพบป้ายหลุมศพอยู่ที่นั่น... ไม่ใช่ป้ายธรรมดา ป้ายนี้จะดูต่างจากที่เหลือ มีความลับซ่อนอยู่ภายใน ผลักแผ่นหิน แล้วเจ้าจะได้รู้ความลับเหล่านั้น..." },
        progress = { "54:1882497200:1278980947", "นี่ต้องเป็นป้ายหลุมศพที่ Gaeriyan พูดถึง..." },
        completion = { "175:697279025:1372350733", "เจ้าผลักแผ่นหินอย่างแรง มันเลื่อนออก เผยให้เห็นช่องตื้นเล็ก ๆ ใต้แผ่นหิน เมื่อวาง Linken's Sword ลงในช่อง เจ้าก็พบว่ามันพอดีอย่างสมบูรณ์..." },
    },
    [3914] = { -- Linken's Sword
        title = { "14:1124662535:1111948986", "ดาบของ Linken" },
        objective = { "60:1930465019:1748182791", "นำ Linken's Superior Sword ไปให้ Linken ใน Un'Goro Crater" },
        description = { "96:1540139114:2051009236", "หลังแสงจ้าแลบขึ้น เจ้าก็หยิบดาบได้อีกครั้ง มันเปลี่ยนไปแล้ว!" },
        progress = { "49:315830081:323426078", "โอ้! ข้าจำเจ้าได้! เจ้าคือ... ไม่ อย่าเพิ่งบอกข้า!" },
        completion = { "122:817902474:1150627754", "ดาบของข้า... มันเสร็จแล้ว! ทีนี้ ถ้าเพียงข้าจำได้ว่าต้องใช้มันทำไม... นี่ อย่างน้อยให้ข้าจ่ายค่าจ้างสำหรับงานของเจ้าก่อน" },
        required = { [11162] = { "23:1518758037:1727232698", "ดาบชั้นดีของ Linken" } },
        steps = { { "23:1518758037:1727232698", "ดาบชั้นดีของ Linken" } },
    },
    [3941] = { -- A Gnome's Assistance
        title = { "20:528456122:1364791553", "ความช่วยเหลือจากโนม" },
        objective = { "49:1034389890:868040728", "ตามหา J.D. Collie ในถ้ำที่ Marshal's Refuge" },
        description = { "86:471274674:1298936273 N 368:1467638724:915380672", "คิดสิ... คิด... ข้ารู้ว่ามาที่นี่เพื่อเรื่องสำคัญบางอย่าง... ข้ามีความคิดหนึ่ง {name} ในถ้ำตรงโน้นมีโนมชื่อ J.D. นางใจดีกับข้ามากเมื่อข้ามาถึงใหม่ ๆ บางทีตอนที่ข้าสับสน ข้าอาจพูดอะไรให้นางฟัง ทำไมเจ้าไม่ลองไปถามว่านางรู้อะไรบ้าง? อ้อ แต่ระวังด้วย นางชอบทดลองกับผลึกเรืองแสงประหลาดที่ข้าเห็นในปล่องภูเขาไฟ ข้าไม่แน่ใจนักว่านางกำลังทำอะไรในนั้น!" },
        completion = { "89:623889706:169558872", "อยู่ตรงนั้นสักครู่นะ... ข้ากำลังทดสอบการผสมผลึกแบบใหม่..." },
    },
    [3942] = { -- Linken's Memory
        title = { "15:1163170966:1224631019", "ความทรงจำของ Linken" },
        objective = { "41:1284456298:288055526", "ตามหา Eridan Bluewind ทางใต้ของ Felwood" },
        description = { "460:899321155:1366361416", "โอ้... Linken หรือ? ใช่ เขาเป็นคนพิลึก ตอนมาถึงใหม่ ๆ เขาพึมพำเรื่องประหลาดสารพัด ข้าว่าคงโดนกระแทกศีรษะแรงทีเดียว แต่มีเรื่องหนึ่งที่เขาพูดแล้วข้าจำได้ เขากำลังทำโทเท็มบางอย่าง และบอกว่าต้องไปคุยกับคนชื่อ Eridan Bluewind... ในที่ที่เรียกว่า Felwood ข้าคิดว่าอย่างนั้นนะ? แต่ตอนนี้ข้าสงสัยว่าเขาคงบอกอะไรเจ้าได้ไม่มาก หากอยากรู้เพิ่ม บางทีเจ้าควรไปหา Eridan ด้วยตัวเอง?" },
        completion = { "7:989913233:66981971 C 41:1772161049:498280892", "สวัสดี {class} มีอะไรให้ข้าช่วยหรือ?" },
    },
    [3961] = { -- Linken's Adventure
        title = { "18:1238131749:1365691582", "การผจญภัยของ Linken" },
        objective = { "66:1892023596:1859804839", "นำ Silver Totem of Aquementas ไปให้ Linken ที่ Marshal's Refuge" },
        description = { "344:732876024:1994749109", "คิดดูสิ ตลอดเวลานี้ เหตุที่ Linken มาที่นี่คือเพื่อกำจัด Blazerunner ให้เรา... เขาดูเป็นคนธรรมดาเหลือเกิน แต่ข้าสังเกตว่าเขาไม่สนใจการทดลองหรือเครื่องมือของข้าเลย ต่างจากโนมส่วนใหญ่ เขาต้องมีหัวใจของนักรบที่แท้จริงแน่ นำโทเท็มไปให้เขา ดูว่าจะช่วยให้จำได้หรือไม่ว่ามาที่นี่ทำไม" },
        progress = { "11:1023148120:882326855 N 1:33:33", "สวัสดีอีกครั้ง {name}!" },
        completion = { "25:972289058:741647694", "J.D. ช่วยอะไรเจ้าได้บ้างไหม?" },
    },
    [3962] = { -- It's Dangerous to Go Alone
        title = { "26:1981223501:1043707990", "ไปคนเดียวมันอันตราย" },
        objective = { "187:905732846:722527031", "เดินทางไป Fire Plume Ridge ทางใต้ของ Marshal's Refuge ตามหา Blazerunner แล้วใช้โทเท็มลบออราป้องกันของมัน เมื่อปราบได้แล้ว ให้ไปนำ Golden Flame จากในถ้ำ" },
        description = { "N 495:1221029694:1096992756", "{name} ในที่สุดข้าก็จำได้แล้ว... ข้ามาที่นี่เพื่อต่อสู้กับ Blazerunner จริง ๆ ข้าอยู่ระหว่างการเดินทาง และนี่ควรเป็นขั้นสุดท้าย แต่ข้าไม่ใช่ผู้กล้าคนนั้นอีกแล้ว... เจ้าต่างหาก จากทุกสิ่งที่ทำมา เจ้าต้องเป็นผู้ทำให้เรื่องนี้จบลง ไม่ใช่ข้า Blazerunner เฝ้าวัตถุทรงพลังที่เรียกว่า Golden Flame มันให้พลังมหาศาลเกินกว่าสิ่งใดที่ข้าเคยรู้จัก และเป็นอันตรายหากตกอยู่ในมือผู้มีใจชั่ว เจ้าควรพาคนอื่นไปด้วย ไปคนเดียวมันอันตราย ถือว่านี่เป็นคำแนะนำของข้า" },
        progress = { "164:939510174:1297788570", "Blazerunner แทบไม่มีใครทำอันตรายได้เมื่ออยู่หลังออราที่สร้างขึ้นด้วย Golden Flame มีเพียงเจ้าที่มีพลังลบมันด้วย Silver Totem of Aquementas" },
        completion = { "11:1191658970:1224418299 N 261:1774865258:139390432", "ขอบใจ {name} ตอนนี้ Golden Flame จะถูกนำกลับบ้านเกิดของข้า เพื่อเก็บรักษาไว้และไม่ให้ถูกใช้ทำความชั่วอีก หากไม่มีเจ้า ข้าคงยังไม่รู้ว่าตัวเองเป็นใคร! เจ้าทำเพื่อข้ามามาก ข้าจึงอยากให้ของพิเศษ... เลือกชิ้นไหนก็ได้ตามต้องการ!" },
        required = { [11179] = { "12:1653344676:1263504617", "เปลวไฟสีทอง" } },
        objectiveLabels = {
            item = { ["Golden Flame"] = "เปลวไฟสีทอง" },
        },
    },
    [4005] = { -- Aquementas
        title = { "10:1838129265:1930743108", "Aquementas" },
        objective = { "201:1218051595:634843261", "นำ Book of Aquor, Silvery Claws และ Irontree Heart ไป Tanaris ใช้ Book of Aquor อัญเชิญ Aquementas เมื่อได้โทเท็มที่สมบูรณ์แล้ว ให้นำไปให้ J.D. Collie ที่ Marshal's Refuge" },
        description = { "425:1724865645:1374291863", "นำถุงอุปกรณ์นี้ติดตัวไป Tanaris เดินทางไป Lost Rigger Cove แล้วมองหาวงหิน แหลมที่อยู่ทางตะวันออกสุดคือความลับ... ให้อ่าน Book of Aquor จากภายในวงหินนี้เท่านั้น อัญเชิญสิ่งมีชีวิตเพียงตนเดียวที่เปลี่ยนของซึ่งเจ้าเก็บมาเป็นโทเท็มไว้สู้ Blazerunner ได้ Aquementas จะไม่พอใจที่ถูกปลุก แต่จำไว้ว่าเจ้าต้องอยู่ในวงหินเพื่อให้เขาเปลี่ยนสิ่งของเหล่านั้น" },
        progress = { "55:1164370877:180874853 N 1:46:46", "กลับมาแล้วสินะ? อืม... ให้ข้าดูหน่อย {name}" },
        completion = { "300:1133720063:1084405797", "เจ้าบอกว่า Blazerunner หรือ... ใช่ ข้ารู้ว่ามีภูตธาตุทรงพลังอาศัยอยู่ใจกลางปล่องภูเขาไฟที่ไหม้เกรียม พวกเราต่างอยู่ห่าง ๆ ไม่มีใครฝ่าออราทรงพลังที่ล้อมรอบมันได้ หลายคนถูกผลักจากทางหินลงสู่พื้นด้านล่างขณะพยายามเผชิญหน้ากับมัน" },
        required = { [11522] = { "26:1909213849:468214799", "โทเท็มเงินของอาเควเมนทัส" } },
        objectiveLabels = {
            item = { ["Silver Totem of Aquementas"] = "โทเท็มเงินของอาเควเมนทัส" },
        },
    },
    [4084] = { -- Silver Heart
        title = { "12:1524046979:201449790", "หัวใจสีเงิน" },
        objective = { "77:882258438:572684966", "เก็บ Silvery Claw 11 ชิ้น และ Irontree Heart 1 ชิ้นให้ Eridan Bluewind ใน Felwood" },
        description = { "36:1183699812:1480076569 N 347:763391444:1462018623 N 111:172456773:1241549320", "ข้าไม่รู้จักคนที่เจ้าพูดถึง {name} แต่อย่ากังวล หากสหายของเจ้าอยู่ระหว่างเดินทางมาหาข้า ข้าก็รู้ว่าเขาต้องการอะไร ณ ใจกลาง Un'Goro Crater มีความชั่วร้ายอันบริสุทธิ์สถิตอยู่ มันอยู่ในร่างภูตธาตุนามว่า Blazerunner... ได้รับการป้องกันด้วยออราที่ไม่มีใครลบได้... ไม่มีใคร... นอกจากผู้มีพลังมากพอ ข้าสอนเรื่องพลังนี้ให้เจ้าได้ {name} ก่อนอื่น ทำตามที่ข้าขอ เก็บ Silvery Claw 11 ชิ้น และ Irontree Heart 1 ชิ้นจากสิ่งมีชีวิตใน Felwood แล้วกลับมา" },
        progress = { "116:1696034887:193369999", "ข้าบอกเรื่องพลังที่ต้องใช้ปราบ Blazerunner ให้เจ้าได้มากกว่านี้ แต่ก่อนอื่น เจ้าต้องรวบรวมของที่ข้าต้องการ" },
        completion = { "11:1598769728:2013240452 N 54:695797026:1727379974", "ดีมาก {name} ข้าเห็นแล้วว่าเจ้าจริงจังกับการช่วยสหาย" },
        required = { [11172] = { "13:479546716:1463933199", "กรงเล็บสีเงิน" }, [11173] = { "14:840380798:1957717672", "หัวใจต้นเหล็ก" } },
        objectiveLabels = {
            item = { ["Silvery Claws"] = "กรงเล็บสีเงิน", ["Irontree Heart"] = "หัวใจต้นเหล็ก" },
        },
    },
    [4141] = { -- Muigin and Larion
        title = { "17:247222832:1397073552", "Muigin กับ Larion" },
        objective = { "44:853420189:1750459953", "เก็บ Bloodpetal 15 ชิ้นแล้วกลับไปหา Muigin" },
        description = { "499:93427368:1294853371", "เห็น Larion ตรงโน้นไหม? ที่เรามาอยู่ที่นี่เป็นความผิดของเขา! ข้าบอกแล้วว่าเรามาผิดทาง แต่เขายอมฟังไหมล่ะ? แล้วเชื่อไหมว่าเขากลับเป็นฝ่ายไม่ยอมพูดกับข้า? เอาเถอะ จนกว่าเขาจะเปลี่ยนใจ เรามาแกล้งเขาให้สนุกสักหน่อยดีกว่า เจ้าสังเกตสิ่งมีชีวิตคล้ายพืชประหลาดรอบ ๆ นี้ไหม? พวกมันสร้างแต่ปัญหา แต่ข้าคิดว่าหากฝึกอย่างถูกวิธี ก็ทำให้เชื่อฟังคำสั่งได้ ก่อนอื่น ข้าต้องใช้ตัวอย่างมาศึกษา เจ้าช่วยเก็บให้หน่อยได้ไหม?" },
        progress = { "47:344164322:1435975846", "Larion จะต้องเจอดีแน่ เรื่องนั้นข้ารับรอง!" },
        completion = { "46:130517900:2033937561 N 133:1040000455:300328661", "หวังว่ามันไม่ได้สร้างปัญหาให้เจ้ามากนัก {name} ข้าพยายามหลีกให้พ้น พวกมันดุร้าย! ข้าเคยลองกระโดดข้ามตัวหนึ่ง... แล้วก็ถูกโจมตี! พืชไม่ควรทำตัวแบบนั้นเลย!" },
        required = { [11316] = { "10:1398451957:1967749374", "ดอก Bloodpetal" } },
        steps = { { "10:1398451957:1967749374", "ดอก Bloodpetal" } },
    },
    [4142] = { -- A Visit to Gregan
        title = { "17:930485810:2142364315", "ไปเยี่ยม Gregan" },
        objective = { "50:1137209489:1432190406", "นำ Bloodpetal ไปให้ Gregan Brewspewer ใน Feralas" },
        description = { "41:885705559:1341769821 N 351:1431104278:4689123", "ข้ายังไม่แน่ใจว่าจะเข้าใจเรื่องนี้อย่างไร {name} พืชพวกนี้... ดูเหมือนมีสติปัญญาอยู่บ้าง แต่ข้าไม่ใช่ผู้เชี่ยวชาญ ทว่าข้ารู้จักคนที่เชี่ยวชาญ! ไปทางเหนือของ Feralas แล้วตามหา Gregan Brewspewer สหายของข้า เขารู้เรื่องแบบนี้ดี ข้ามั่นใจว่า Gregan ช่วยเราได้ เจ้าจะพบเขาในป่า เขาไม่ใช่คนที่จะอยู่ในเมืองใหญ่" },
        progress = { "152:1361828053:1513391245", "ข้าอยู่ในป่านี่... สงบดี อย่างน้อยข้าก็เคยคิดว่าจะเป็นอย่างนั้น ข้ามีแขกมาหาที่นี่มากกว่าตอนอยู่ Ironforge เสียอีก!" },
        completion = { "112:1646006142:1243705727", "Bloodpetal หรือ? อืม... เจ้าควรอธิบายแผนก่อน แล้วข้าจะบอกว่าช่วยได้หรือไม่" },
    },
    [4143] = { -- Haze of Evil
        title = { "12:1164180140:1149297012", "หมอกแห่งความชั่วร้าย" },
        objective = { "75:816052124:1869920684", "เก็บตัวอย่าง Atal'ai Haze 5 ชิ้น แล้วกลับไปหา Muigin ใน Un'Goro Crater" },
        description = { "23:422266726:307902830 N 452:770383586:1105375937 N 1:33:33", "บอกตามตรง {name} ตลอดการเดินทางข้าไม่เคยเห็นพืชแบบนี้เลย บางทีข้าควรไปเยือนปล่องภูเขาไฟแห่งนี้บ้าง... อย่างไรก็ตาม ข้าคิดว่ารู้ว่า Muigin ต้องการอะไร มันคือ Atal'ai Haze ของน่ากลัวและเก็บยาก แต่เป็นสิ่งที่เขาต้องใช้ควบคุมเจ้าสัตว์ประหลาดน้อยพวกนั้น เจ้าต้องไปยังวิหาร Atal'Hakkar ใน Swamp of Sorrows เก็บ Atal'ai Haze ได้จาก Deep Lurker, Murk Worm หรือพวก Ooze ที่นั่น ขอให้โชคดี {name}!" },
        progress = { "70:412588352:539133279", "Larion ยังไม่ยอมพูดกับข้า! เขาผูกใจเจ็บเก่งจริง ๆ" },
        completion = { "49:2131890232:1842692201 N 67:34792382:1007892866", "ข้ายอมรับว่าลังเลที่จะจับของนั่นอยู่หน่อย {name}! แต่หาก Gregan บอกว่าใช้ได้ ข้าก็ยินดีลอง!" },
        required = { [11318] = { "12:262552364:1425542646", "หมอก Atal'ai" } },
        objectiveLabels = {
            item = { ["Atal'ai Haze"] = "หมอก Atal'ai" },
        },
    },
    [4144] = { -- Bloodpetal Sprouts
        title = { "18:2107803958:214685237", "ต้นอ่อน Bloodpetal" },
        progress = { "17:2048586586:1456362005 N 411:1845502580:976125906", "แผนเป็นอย่างนี้ {name}: ออกไปเก็บต้นอ่อน Bloodpetal พวกพืชที่ยังเติบโตไม่เต็มที่ แล้วนำมาที่นี่ จากนั้นข้าจะดูว่า Atal'ai Haze ทำอะไรได้ เจ้าคงคิดว่าข้าอาฆาต... ที่จริงเจ้าคิดถูกแล้ว! ความจริงคือข้ารู้ทางออกจากที่นี่ แต่จนกว่า Larion จะยอมรับว่าข้าถูก ข้าจะอยู่ตรงนี้! ไปเถอะ หาต้นอ่อน Bloodpetal มา แล้วเรามาสนุกกัน!" },
        completion = { "19:1907871636:1958315161 N 35:961378227:629850942", "เอาล่ะ ลองดูสักตั้ง {name}! นี่ต้องทำให้ Larion สนใจแน่!" },
        description = { "17:2048586586:1456362005 N 411:1845502580:976125906", "แผนเป็นอย่างนี้ {name}: ออกไปเก็บต้นอ่อน Bloodpetal พวกพืชที่ยังเติบโตไม่เต็มที่ แล้วนำมาที่นี่ จากนั้นข้าจะดูว่า Atal'ai Haze ทำอะไรได้ เจ้าคงคิดว่าข้าอาฆาต... ที่จริงเจ้าคิดถูกแล้ว! ความจริงคือข้ารู้ทางออกจากที่นี่ แต่จนกว่า Larion จะยอมรับว่าข้าถูก ข้าจะอยู่ตรงนี้! ไปเถอะ หาต้นอ่อน Bloodpetal มา แล้วเรามาสนุกกัน!" },
        required = { [11315] = { "17:1612547331:804896053", "ต้นอ่อน Bloodpetal" } },
        objectiveLabels = {
            item = { ["Bloodpetal Sprout"] = "ต้นอ่อน Bloodpetal" },
        },
    },
    [4145] = { -- Larion and Muigin
        title = { "17:904329732:244772432", "Larion กับ Muigin" },
        objective = { "129:1159741957:2010580715", "ล่า Bloodpetal Lasher 5 ตัว, Bloodpetal Thresher 5 ตัว, Bloodpetal Flayer 5 ตัว และ Bloodpetal Trapper 5 ตัวให้ Larion ที่ Marshal's Refuge" },
        description = { "429:698398563:108313843", "เห็น Muigin ตรงโน้นไหม? ที่เราหลงทางเป็นความผิดของเขา! ข้าต่างหากที่รู้ทาง แต่เขายืนกรานว่ารู้ทางลัด สุดท้ายเราก็มาอยู่ที่นี่! ที่แย่กว่านั้น ตอนนี้เขาส่งเจ้าพืชประหลาดมารบกวนข้าไม่หยุด ข้าโกรธจนไม่คิดจะพูดกับเขาเร็ว ๆ นี้ แต่พวกพืชก่อกวนนี่รับมือไม่ไหวจริง ๆ ก่อนอื่น เรามาลดจำนวนที่เขาจะใช้ได้ดีกว่า ออกไปล่า Bloodpetal แล้วกลับมาหาข้า" },
        progress = { "62:1350296341:152158715", "Muigin ต้องขอโทษก่อน ข้าจึงจะยอมพูดกับเขาอีก!" },
        completion = { "22:806981533:1350350998 N 40:1016901135:321138315", "ขอบคุณที่ช่วยนะ {name} แต่ข้าเกรงว่าจะมีข่าวร้าย..." },
    },
    [4146] = { -- Zapper Fuel
        title = { "11:787327559:241797799", "เชื้อเพลิงเครื่องช็อต" },
        objective = { "88:2038998983:790476644", "นำ Unloaded Zapper และตัวอย่าง Atal'ai Haze 5 ชิ้นไปให้ Larion ที่ Marshal's Refuge" },
        description = { "16:1820299210:213147586 N 478:1112411595:700470968", "เจ้าโชคดีแล้ว {name}! ระหว่างที่ Marvon ไม่อยู่ ข้าทำการทดลองของตัวเองอยู่บ้าง และหนึ่งในนั้นคือเครื่องช็อตแมลงระยะใกล้ แค่ปรับนิดหน่อย ก็น่าจะใช้กำจัดพวก Bloodpetal ก่อกวนได้ดี ข้าให้เครื่องช็อตต้นแบบแก่เจ้าได้ตัวหนึ่ง แต่เจ้ายังต้องไปหาเชื้อเพลิงเอง หา Atal'ai Haze ที่เครื่องต้องใช้ได้ในวิหาร Atal'Hakkar เจ้าต้องเก็บจาก Deep Lurker, Murk Worm หรือพวก Ooze" },
        progress = { "20:513026268:2017628722 N 41:909605470:2056629491", "เหนื่อยเหลือเกิน {name} เจ้าพวกนั้นไม่ยอมปล่อยให้ข้าอยู่ตามลำพังเลย!" },
        completion = { "61:1729219907:471847803", "ตกลงว่า Marvon ไม่อยู่หรือ? เอาเถอะ ไหนแสดงให้ข้าดูว่าเจ้าได้อะไรมา" },
        required = { [11319] = { "15:136878477:973980151", "เครื่องช็อตที่ยังไม่ได้เติมเชื้อเพลิง" }, [11318] = { "12:262552364:1425542646", "หมอก Atal'ai" } },
        objectiveLabels = {
            item = { ["Unloaded Zapper"] = "เครื่องช็อตที่ยังไม่ได้เติมเชื้อเพลิง", ["Atal'ai Haze"] = "หมอก Atal'ai" },
        },
    },
    [4147] = { -- Marvon's Workshop
        title = { "17:1602493855:971007564", "โรงช่างของ Marvon" },
        objective = { "51:683371322:1522040643", "เดินทางไปโรงช่างของ Marvon Rivetseeker ที่ Ratchet" },
        description = { "361:1887672992:474304205", "ข้าแอบดูจนรู้ว่า Muigin ทำอะไร เขากำลังปลูกเจ้าพวกบ้านั่นอยู่ตรงโน้นจริง ๆ! ข้าคิดว่าทางออกเดียวคือ... ไม่ ไม่ใช่ไปคุยกับเขา... เจ้าคิดอะไรอยู่? ทางออกคือต้องสู้กลับ! เราต้องให้ Marvon สหายของข้าช่วย เขามีโรงช่างที่ Ratchet ข้ามั่นใจว่าเขาสร้างเครื่องมือบางอย่างมาช่วยเราได้" },
        completion = { "42:1003559272:1084610654 N 109:1666608066:1842845784", "Marvon ออกไปนานแล้ว {name} เขาไป Tanaris เพื่อศึกษาซากเมืองโทรลล์โบราณ ทีนี้ เจ้าบอกว่าต้องการอะไรนะ?" },
    },
    [4148] = { -- Bloodpetal Zapper
        title = { "17:1745118736:151373680", "เครื่องช็อต Bloodpetal" },
        progress = { "343:1952210761:1884768980", "หากจะให้เครื่องช็อตทำงาน มันต้องมีตัวอย่างสิ่งมีชีวิตเป้าหมาย ออกไปในปล่องภูเขาไฟแล้วเก็บต้นอ่อน Bloodpetal จากนั้นข้าจะปรับเครื่องให้ใช้กับสหายตัวน้อยของ Muigin ได้... หากเขาไม่ดื้อขนาดนั้น เราคงเดินทางกลับบ้านไปแล้ว... แต่จนกว่าจะถึงตอนนั้น ข้าต้องแสดงให้เห็นว่าการแกล้งเล็ก ๆ ของเขาไม่รบกวนข้าสักนิด!" },
        completion = { "44:848607933:1952552455 N 88:1776568402:1613645612", "ดูเหมือนจะใช้ได้สมบูรณ์แบบ {name} ทีนี้จำไว้ หากเห็นพวกก่อกวนแถวนี้ ก็ใช้เครื่องช็อตได้เลย ไม่ต้องลังเล!" },
        description = { "343:1952210761:1884768980", "หากจะให้เครื่องช็อตทำงาน มันต้องมีตัวอย่างสิ่งมีชีวิตเป้าหมาย ออกไปในปล่องภูเขาไฟแล้วเก็บต้นอ่อน Bloodpetal จากนั้นข้าจะปรับเครื่องให้ใช้กับสหายตัวน้อยของ Muigin ได้... หากเขาไม่ดื้อขนาดนั้น เราคงเดินทางกลับบ้านไปแล้ว... แต่จนกว่าจะถึงตอนนั้น ข้าต้องแสดงให้เห็นว่าการแกล้งเล็ก ๆ ของเขาไม่รบกวนข้าสักนิด!" },
        required = { [11315] = { "17:1612547331:804896053", "ต้นอ่อน Bloodpetal" } },
        objectiveLabels = {
            item = { ["Bloodpetal Sprout"] = "ต้นอ่อน Bloodpetal" },
        },
    },
    [4243] = { -- Chasing A-Me 01
        title = { "15:1863273805:591082664", "ตามหา A-Me 01" },
        objective = { "31:1402309337:1274096509", "ตามหา A-Me 01 ใน Un'Goro Crater" },
        description = { "503:461913024:230699581", "น่าเสียดายที่มีบางอย่างเกิดกับหนึ่งในสิ่งประดิษฐ์ชิ้นเอกของข้า เจ้าเคยเห็นกระรอกกลใช่ไหม? เพื่อเข้าใกล้เหล่าลิงใหญ่แห่ง Un'Goro Crater ข้าจึงสร้างลิงกลให้กลมกลืนกับพวกมัน ข้าเรียกนางว่า A-Me 01 นางใช้อัญมณีส่องภาพเป็นดวงตา เพื่อให้ข้าเห็นทุกอย่างที่นางเห็น นางไปถึง Fungal Rock รังของเหล่าลิงใหญ่ทางตะวันออกของที่นี่ แล้วข้าก็ขาดการติดต่อ ภาพสุดท้ายที่เห็นคือหนึ่งในตัวผู้จ่าฝูงกำลังพุ่งเข้ามาทักทายนาง! เจ้าช่วยข้าตามหานางได้ไหม?" },
        completion = { "271:1515410341:2102528018", "เมื่อเจ้าตรวจดู A-Me 01 ก็พบรอยบุบใหญ่สองแห่งที่ทำให้ผลงานวิศวกรรมซึ่ง Karna เห็นว่าประณีตนี้เสียโฉม รอยหนึ่งอยู่ที่ไหล่ อีกแห่งอยู่บนศีรษะ เมื่อตรวจต่อ ก็ไม่พบว่ามีพลังงานไหลผ่านชิ้นส่วนของนางเลย" },
    },
    [4244] = { -- Chasing A-Me 01
        title = { "15:1863273805:591082664", "ตามหา A-Me 01" },
        objective = { "62:2123307056:843965680", "หา Mithril Casing แล้วนำกลับไปให้ A-Me 01 ใน Un'Goro Crater" },
        description = { "341:1653227912:1213269576", "เมื่อตรวจต่ออีกหน่อย เจ้าพบแผงที่เลื่อนเปิดได้ เหนือสายไฟมีข้อความเขียนชัดเจนว่า \"เปลี่ยน Mithril Casing แล้วปิดเครื่องก่อนเปิดใหม่\" เจ้าปิดแผงกลับเข้าที่ พลางสงสัยว่าจะซ่อม A-Me 01 และพานางกลับไปหา Karna Remtravel ใกล้ Marshal's Refuge ได้ง่ายเพียงนั้นหรือ มีแต่ลองเท่านั้นจึงจะรู้" },
        progress = { "99:1119105785:1279900866", "แผงที่ใส่ Mithril Casing ยังคงปิดสนิท ส่วนที่เหลือของ A-Me 01 ก็ยังไม่ทำงาน" },
        completion = { "315:1123943395:1221143508", "เจ้าเปิดแผงด้านหลัง A-Me 01 อีกครั้ง แล้วค่อย ๆ นำ Mithril Casing เก่าที่ดูเหมือนไหม้เสียแล้วออก ชิ้นใหม่เลื่อนเข้าที่ได้ง่าย เหลือเพียงโยกสวิตช์ไปที่ \"Off\" แล้วกลับมาที่ \"On\" หากปัญหาเกิดจาก Mithril Casing จริง" },
        required = { [10561] = { "14:2100540912:871191584", "ปลอกมิธริล" } },
        objectiveLabels = {
            item = { ["Mithril Casing"] = "ปลอกมิธริล" },
        },
    },
    [4245] = { -- Chasing A-Me 01
        title = { "15:1863273805:591082664", "ตามหา A-Me 01" },
        objective = { "57:866185497:710374726", "คุ้มกัน A-Me 01 กลับไปหา Karna Remtravel ใน Un'Goro Crater" },
        description = { "343:414190276:111228397", "เมื่อเตรียมพร้อมจะนำ A-Me 01 กลับไปหา Karna Remtravel เจ้าโยกสวิตช์ไปที่ \"Off\" เจ้ากวาดตามองรอบตัวอีกครั้งให้แน่ใจว่าไม่มีกอริลล่ากำลังมา แล้วเตรียมดูว่าจะเกิดอะไรขึ้นเมื่อเปิดสวิตช์กลับไปที่ \"On\" นี่เป็นโอกาสสุดท้าย... เจ้าแน่ใจหรือว่าต้องการทำเช่นนี้?" },
        progress = { "192:735567547:814070808", "เจ้าช่วย A-Me ได้หรือยัง? Mithril Casing ที่เจ้าบอกว่าพังน่าจะเป็นสาเหตุที่คาดได้ถูกแล้ว ข้ามั่นใจว่าหากเปลี่ยนมัน นางจะกลับมาทำงานและกลับบ้านได้" },
        completion = { "42:1084838692:1421118315 N 127:1602924717:1088625996 N 25:1951440920:268840883", "โอ้ เจ้าทำได้แล้ว! วิเศษ! ขอบใจ {name} โอ้ A-Me ผู้น่าสงสารของข้า ดูรอยบุบทั้งหมดนั่นสิ เราจะซ่อมให้นางกลับมาทำงานสมบูรณ์ได้อีกไม่นาน ขอบใจอีกครั้ง {name} ข้าซาบซึ้งจริง ๆ" },
    },
    [4284] = { -- Crystals of Power
        title = { "17:1159246722:1484931168", "ผลึกแห่งพลัง" },
        objective = { "116:1345104276:1104019156", "เก็บ Power Crystal สีละ 7 ชิ้น ได้แก่สีแดง น้ำเงิน เหลือง และเขียว แล้วนำไปให้ J.D. Collie ที่ Marshal's Refuge" },
        description = { "29:634498124:1649594515 N 443:1057216461:79574854", "ข้ามั่นใจว่าเจ้าสังเกตเห็นแล้ว {name} มันอยู่ทุกแห่ง! ข้าพูดถึงอะไรหรือ? ก็ผลึกไง! ผลึกพวกนั้น... มีอยู่ทั่วปล่องภูเขาไฟ คนส่วนใหญ่ไม่สนใจ แต่ข้ารู้สึกประหลาดว่ามันมีพลังซ่อนอยู่ ข้าทดลองกับมันที่นี่มาพักหนึ่งแล้ว แต่ยังไม่พบอะไร อย่างน้อยก็ตอนนี้ ว่าแต่ผลึกที่ข้ามีเริ่มเหลือน้อย เจ้าคิดว่าจะช่วยเก็บมาเพิ่มได้ไหม?" },
        progress = { "37:1217919173:228910136 N 1:33:33", "ข้ารู้ว่ากำลังจะพบอะไรบางอย่าง {name}!" },
        completion = { "47:719856813:1131277710 N 1:46:46", "ทีนี้ข้าก็ทดลองต่อได้แล้ว! ขอบใจ {name}" },
        required = { [11186] = { "17:348985127:2018572382", "ผลึกพลังสีแดง" }, [11188] = { "20:1249594339:112433194", "ผลึกพลังสีเหลือง" }, [11185] = { "19:734537454:1156748847", "ผลึกพลังสีเขียว" }, [11184] = { "18:930612469:654596139", "ผลึกพลังสีน้ำเงิน" } },
        steps = { { "17:348985127:2018572382", "ผลึกพลังสีแดง" }, { "20:1249594339:112433194", "ผลึกพลังสีเหลือง" }, { "19:734537454:1156748847", "ผลึกพลังสีเขียว" }, { "18:930612469:654596139", "ผลึกพลังสีน้ำเงิน" } },
    },
    [4285] = { -- The Northern Pylon
        title = { "18:1040674785:1236685014", "เสาผลึกทางเหนือ" },
        objective = { "70:110544134:2064427055", "ค้นหาตำแหน่ง Northern Crystal Pylon ใน Un'Goro Crater" },
        description = { "344:1247493383:1271509984 N 25:297687248:574085031", "มันมีไว้ทำอะไรกัน? ข้าสลัดความคิดนี้ออกจากหัวไม่ได้! ข้าแทบจะคลั่ง หากข่าวลือเรื่องเสาผลึกที่ได้ยินเป็นจริงทั้งหมด เรียกข้าว่าเชื่อคนง่ายก็ได้ แต่ปกติข้าเชื่อแทบทุกอย่างที่คนบอก เอาเถอะ ข้าได้ยินว่ามีเสาผลึกแห่งหนึ่งอยู่ใกล้พอสมควร สักแห่งทางเหนือ... ช่วยหามันที {name} ข้ารู้ว่ามันมีอยู่จริง" },
        progress = { "28:125019818:546541241 N 1:63:63", "เจ้าไปเยือนเสาผลึกแล้วหรือยัง {name}?" },
        completion = { "29:449023179:1291853839 N 1:46:46", "ข้ารู้ว่าเรื่องเล่าเป็นจริง {name}" },
    },
    [4287] = { -- The Eastern Pylon
        title = { "17:1429580058:775488143", "เสาผลึกทางตะวันออก" },
        objective = { "69:263975440:798694345", "ค้นหาตำแหน่ง Eastern Crystal Pylon ใน Un'Goro Crater" },
        description = { "119:4846784:44075483 N 368:1530575215:547680872", "ระหว่างพักอยู่ที่นี่ ข้าได้ยินข่าวลือแปลก ๆ เรื่องเสาลึกลับกลางป่าของปล่องภูเขาไฟ {name} ข้าคิดว่ามันคงใหญ่ทีเดียว และมีผลึกเรียงอยู่ด้านใน แม้ไม่เคยเห็นเอง ข้าก็อดคิดไม่ได้ว่าข่าวลือเป็นจริง และเสาพวกนั้นเกี่ยวข้องกับผลึกทั้งหมดที่เราพบ ทำไมเจ้าไม่ช่วยคลายความสงสัยให้ข้าล่ะ? ว่ากันว่ามีเสาอยู่ทางตะวันออกของปล่องภูเขาไฟ เจ้าคิดว่าหาพบได้ไหม?" },
        progress = { "28:125019818:546541241 N 1:63:63", "เจ้าไปเยือนเสาผลึกแล้วหรือยัง {name}?" },
        completion = { "33:295098697:704812107 N 82:450658792:1363522753", "Un'Goro เป็นสถานที่ประหลาดจริง ๆ {name} เมื่อก้าวเข้ามาในปล่องภูเขาไฟ ก็ราวกับเจ้าอยู่อีกโลกโดยสิ้นเชิง..." },
    },
    [4288] = { -- The Western Pylon
        title = { "17:722908244:692865087", "เสาผลึกทางตะวันตก" },
        objective = { "51:676363537:1731611747", "ค้นหาตำแหน่ง Western Crystal Pylon" },
        description = { "61:63747597:1289314356 N 211:1265941591:363448166 N 86:1730499415:1785866186", "การทดลองของข้ายังไม่ให้ผลที่ดีเลย {name} ข้าอดหวังไม่ได้ว่าเจ้าจะพบคำตอบด้วยการตามหาเสาที่ได้ยินว่ามีอยู่ บางทีหากเราผสมสีบางสีที่เสาเหล่านั้น... แต่ข้าคิดไปไกลแล้ว หามันก่อนเถอะ! {name} สำรวจทางตะวันตกของปล่องภูเขาไฟ ว่ากันว่าเสาอยู่สักแห่งในบริเวณนั้น" },
        progress = { "28:125019818:546541241 N 1:63:63", "เจ้าไปเยือนเสาผลึกแล้วหรือยัง {name}?" },
        completion = { "136:1884532712:2061472057 N 1:46:46", "ปล่องภูเขาไฟมีพื้นที่ลับตามขอบอยู่มาก หากนึกไม่ออกว่าจะหาที่ไหน ลองสำรวจทางคดเคี้ยวดูนะ {name}" },
    },
    [4289] = { -- The Apes of Un'Goro
        title = { "19:1711451471:484302163", "เหล่าวานรแห่ง Un'Goro" },
        objective = { "140:1632604205:268944728", "นำ Un'Goro Gorilla Pelt 2 ผืน, Un'Goro Stomper Pelt 2 ผืน และ Un'Goro Thunderer Pelt 2 ผืนไปให้ Torwa Pathfinder ที่ทางเข้า Un'Goro Crater" },
        description = { "498:1345066387:695358643", "ปล่องภูเขาไฟนี้มีสิ่งมีชีวิตประหลาดมากมาย ราวกับเป็นรูปแบบที่สูงส่งกว่าสิ่งมีชีวิตชนิดเดียวกันทั่วบ้านเกิดของข้าและดินแดนอื่น ข้าอธิบายไม่ได้ แต่สถานที่นี้ประกาศถึงพระแม่ธรณี ข้าแสดงความเคารพต่อนางทุกครั้งที่ติดตามสิ่งมีชีวิตงดงามของนางผ่านแอ่งนี้ หากเจ้าปรารถนาจะสัมผัสความรู้แจ้งที่มาพร้อมความสำเร็จเช่นนั้น จงมุ่งเหนือ ที่นั่นเจ้าจะพบวานรใหญ่ซึ่งทดสอบกำลังของผู้เป็นมรรตัยได้ทุกคน นำหนังของพวกมันมาให้ข้า... พิสูจน์ความแข็งแกร่งของเจ้า" },
        progress = { "44:359624895:573251235 N 119:1629254334:1987604771", "สิ่งมีชีวิตที่นี่เอาชนะเจ้าแล้วหรือ {name}? อย่าท้อถอยง่ายนัก การตามรอยและปราบวานรแห่ง Un'Goro ไม่ใช่งานง่าย แม้แต่สำหรับพรานผู้ยิ่งใหญ่" },
        completion = { "457:2126049523:2103290492", "เจ้าพิสูจน์แล้วว่าแข็งแกร่งพอจะปราบวานรใหญ่แห่ง Un'Goro ดีแล้ว ความท้าทายนี้ยังเล็กน้อยเมื่อเทียบกับ Lar'korwi แต่ข้าจะไม่ลดทอนชัยชนะยิ่งใหญ่ของเจ้า หนังเหล่านี้จะใช้ทำเครื่องแต่งกายชั้นดีให้เผ่าของข้า เจ้าช่วยข้าและพิสูจน์คุณค่าของตนแล้ว ก่อนออกทำภารกิจต่อ เรามาสรรเสริญพระแม่ธรณีและขอบคุณวิญญาณวานรที่เจ้าสังหาร พวกมันต้องรู้ว่าความตายจะไม่สูญเปล่า" },
        required = { [11478] = { "20:201895184:728937030", "หนังกอริลลา Un'Goro" }, [11479] = { "20:655453940:1335441955", "หนัง Stomper แห่ง Un'Goro" }, [11480] = { "22:1960250939:885633285", "หนัง Thunderer แห่ง Un'Goro" } },
        steps = { { "20:201895184:728937030", "หนังกอริลลา Un'Goro" }, { "20:655453940:1335441955", "หนัง Stomper แห่ง Un'Goro" }, { "22:1960250939:885633285", "หนัง Thunderer แห่ง Un'Goro" } },
    },
    [4290] = { -- The Fare of Lar'korwi
        title = { "21:1660409112:3814444", "มื้ออาหารของ Lar'korwi" },
        objective = { "141:1906407112:967592626", "ตามหาซากเหยื่อที่ Lar'korwi เพิ่งล่าได้ ขโมย Piece of Threshadon Carcass แล้วกลับไปหา Torwa Pathfinder ใน Un'Goro Crater" },
        description = { "481:15297723:716380135", "นานมาแล้ว พี่น้องคนหนึ่งของข้าเอาเนื้อจากเหยื่อของ Lar'korwi ไป เขาไม่รู้ตัว แต่ Lar'korwi เห็นเขาจากในป่า มันตามเขาอยู่หลายวัน ทำลายทุกสิ่งที่เขาสัมผัส ด้วยความกลัว ในที่สุดเขาตัดสินใจหนีจากปล่องภูเขาไฟ ทิ้ง Lar'korwi ไว้เบื้องหลัง แต่มันฆ่าเขาไม่ไกลจากตรงนี้ หากเจ้าต้องการยั่ว Lar'korwi จงหาเหยื่อใหม่ของมันแล้วเอาเนื้อมาบางส่วน จากนั้นกลับมาหาข้า" },
        progress = { "30:1565070476:179135283 N 169:539598152:336770020", "อย่าดูเบาคำของข้า {name} หากเจ้าปรารถนาจะเผชิญสิ่งมีชีวิตนี้จริง ก็ต้องระวัง... และฉลาด ต้องใช้ทั้งกำลังและความเข้าใจอย่างมากเพื่อล่อ Lar'korwi ออกมาและปราบมัน" },
        completion = { "21:1129349402:1903439022 N 332:1460598195:769068707", "นี่ใช้ได้ดี {name} ดูเหมือนช่วงนี้ Lar'korwi กินดีทีเดียว แต่ข้าสงสัยว่ามันหา threshadon จากไหนในบริเวณนี้ แปลก ไม่ว่าอย่างไร ข้าจะเก็บนี่ไว้จนกว่าเจ้าพร้อมเผชิญสัตว์ร้าย ไม่ต้องห่วงความปลอดภัยของข้า ข้ามั่นใจว่าเจ้าทำให้ Lar'korwi โกรธพอที่จะไม่ฆ่าข้าก่อนลิ้มรสเนื้อเจ้า" },
        required = { [11504] = { "27:1370718709:320437947", "ชิ้นส่วนซาก Threshadon" } },
        objectiveLabels = {
            item = { ["Piece of Threshadon Carcass"] = "ชิ้นส่วนซาก Threshadon" },
        },
    },
    [4291] = { -- The Scent of Lar'korwi
        title = { "22:2732821:38033436", "กลิ่นของ Lar'korwi" },
        objective = { "90:43662396:70683643", "นำ Ravasaur Pheromone Gland 2 ชิ้นไปให้ Torwa Pathfinder ใกล้ทางเข้า Un'Goro Crater" },
        description = { "52:1277540396:1100260156 N 450:1988734202:1935538405", "ข้าแปลกใจจริง ๆ ที่มันยังไม่มาหาเจ้า {name} แต่ไม่เป็นไร เพราะข้ามีแผนสุดท้ายที่จะพาสัตว์ร้ายนั่นมาถึงเรา ในฐานะตัวผู้จ่าฝูง Lar'korwi มีสิทธิ์ผสมพันธุ์กับตัวเมียที่เลือก และมันเลือกไว้มาก เจ้าจะพบไข่ ravasaur จำนวนมากทางตะวันตก เข้าไปใกล้แล้วน่าจะยั่วให้คู่ของมันเข้าโจมตี ตัวเมียปล่อยกลิ่นรุนแรงจากต่อมบนศีรษะ เพื่อบอกตัวผู้ว่าพร้อมผสมพันธุ์แล้ว นำต่อมแบบนั้นมาให้ข้าสองชิ้น" },
        progress = { "12:540083121:839830800 N 320:1193470465:536647874", "ระวังตัว {name} การเข้าใกล้รังไข่ย่อมยั่วให้พวกแม่โจมตี แม้เจ้าจะเก็บต่อมจากตัวหนึ่งมาแล้วก็ตาม เมื่อต่อสู้เพื่อปกป้องลูก พวกแม่อันตรายได้พอ ๆ กับ Lar'korwi แต่หากเจ้าทำสำเร็จ เราก็จะมีวิธีแน่นอนที่จะเรียกมันออกจากที่ซ่อน" },
        completion = { "20:1720152535:150313909 N 266:612637002:1989968936", "อา ตัวอย่างชั้นดี {name} สองชิ้นที่เจ้าได้มาน่าจะเหมาะที่สุดสำหรับล่อ Lar'korwi ออกสู่ที่โล่ง ข้าแทบรอเห็นผลการต่อสู้ของเจ้ากับสัตว์ร้ายไม่ไหว มันตัวมหึมาและมีกรงเล็บคมดุจดาบชั้นยอด เมื่อมองตาของมัน เจ้าจะได้รู้จักความตาย" },
        required = { [11509] = { "24:913733275:45600787", "ต่อมฟีโรโมนของราวาซอร์" } },
        objectiveLabels = {
            item = { ["Ravasaur Pheromone Gland"] = "ต่อมฟีโรโมนของราวาซอร์" },
        },
    },
    [4292] = { -- The Bait for Lar'korwi
        title = { "22:1319304167:1681158137", "เหยื่อล่อ Lar'korwi" },
        objective = { "154:478237039:1550435649", "ใช้ของใน Torwa's Pouch ล่อ Lar'korwi ออกมาแล้วปราบมัน จากนั้นนำ Lar'korwi's Head ไปให้ Torwa Pathfinder ใกล้ทางเข้า Un'Goro Crater" },
        description = { "493:1260125068:869014208", "นี่จะเป็นส่วนที่ยากที่สุด เพราะแผนค่อนข้างซับซ้อน ทางเหนือของที่นี่เจ้าจะพบทางเล็ก ๆ เข้าสู่ภูเขา ข้าเห็น Lar'korwi ครั้งสุดท้ายที่นั่น เจ้าจะรู้ว่ามาถูกที่จากกระดูกมากมายของสัตว์มหึมาที่เคยเดินอยู่ใกล้ ๆ นำเนื้อที่เก็บมาไปวาง แล้วทาส่วนผสมที่ข้าทำขึ้นบนเนื้อนั้น หากเหยื่อล่อทั้งสองอย่างรวมกันยังเรียก Lar'korwi มาไม่ได้ ข้าก็ไม่รู้ว่าจะใช้อะไรอีก" },
        progress = { "31:670040874:920219410 N 165:1730979310:2109037854", "อย่าปล่อยให้ความกลัวครอบงำ {name} ความกลัวคือผู้ทรยศอันยิ่งใหญ่... เจ้าต้องเข้มแข็งไว้! นำเนื้อไปวางในหุบเขาเล็ก ๆ แล้วใช้ต่อมกับมัน เมื่อนั้นความตายจึงจะมาหาเจ้า" },
        completion = { "63:1719068964:386249982 N 269:652826622:1531155075", "สรรเสริญพระแม่ธรณี! เจ้าทำสำเร็จ! สมควรได้รับคำชม {name} เจ้าพิสูจน์ว่าตนเป็นพรานผู้ยิ่งใหญ่ด้วยฝีมือตัวเอง วิญญาณเจ้าแข็งแกร่ง ความกล้าหาญไร้ผู้เทียบ และพละกำลังกล้าแกร่งขึ้น ข้าขอคำนับฝีมือเจ้า มีเพียงบรรพบุรุษผู้ยิ่งใหญ่ที่สุดของข้าที่ทำสิ่งน่าเหลือเชื่อเช่นนี้ได้ ขอแสดงความยินดี" },
        required = { [11510] = { "16:1434452301:2088018290", "ศีรษะของลาร์คอร์วี" } },
        objectiveLabels = {
            item = { ["Lar'korwi's Head"] = "ศีรษะของลาร์คอร์วี" },
        },
    },
    [4301] = { -- The Mighty U'cha
        title = { "16:1406840519:2074110669", "U'cha ผู้ทรงพลัง" },
        objective = { "73:1151474224:1463527489", "นำ U'cha's Pelt ไปให้ Torwa Pathfinder ที่ทางเข้า Un'Goro Crater" },
        description = { "502:1880672695:9838391", "ระหว่างที่เจ้าสำรวจ Un'Goro ข้าเห็นสิ่งอื่นที่พรานทรงพลังเช่นเจ้าคงยินดีเผชิญ หนึ่งในนั้นคือวานรมหึมาท่ามกลางกอริลล่าทางเหนือ เจ้าเคยไปถ้ำนั้นแล้ว แต่คราวนี้ข้าสงสัยว่าเจ้าจะรอดจากการเผชิญหน้าหรือไม่ หากยอมรับงาน ข้าเรียกมันว่า U'cha และมันคือหนึ่งในบุตรผู้ยิ่งใหญ่ที่สุดของพระแม่ธรณี เชื่อได้เลย ปราบ U'cha แล้วนำหนังมาให้ข้า ทำได้แล้วข้าจะรับรองสิทธิ์ที่เจ้าจะเรียกตนว่าพรานผู้ยิ่งใหญ่" },
        progress = { "306:828578503:1820529500", "U'cha... สัตว์ร้ายตัวนั้นช่างสง่างาม ใหญ่โตและมีสีแดง ฟันขนาดเท่ามีดสั้น แขนหนาดุจลำต้นไม้ และเร็วพอ ๆ กับสิงโตภูเขาทุกตัวที่ข้าเคยเห็น เจ้าควรนับว่าตนโชคดีที่พบบททดสอบความกล้าเช่นนี้ ผู้คนของข้าอาจผ่านไปหลายชั่วคนโดยไม่เห็นสิ่งมีชีวิตแบบนี้เลย" },
        completion = { "11:534428891:784080240 N 281:1178775653:223102834", "ทำได้ดี {name} ข้ายินดี เจ้าทำสิ่งยิ่งใหญ่ในวันนี้ U'cha เป็นหนึ่งในวานรที่ยิ่งใหญ่ที่สุดที่ข้าเคยเห็น การที่เจ้าเอาชนะกำลังของมันได้ บอกถึงความแข็งแกร่ง... และความกล้าของเจ้าอย่างดี สมควรแล้วที่ข้าจะมอบสิ่งนี้เป็นเครื่องหมายแห่งความเคารพ เจ้าได้รับมันด้วยฝีมือตนเอง" },
        required = { [11476] = { "12:823664853:1188866762", "หนังของอูชา" } },
        objectiveLabels = {
            item = { ["U'cha's Pelt"] = "หนังของอูชา" },
        },
    },
    [4321] = { -- Making Sense of It
        title = { "18:1052884182:1104148810", "ไขความหมายของผลึก" },
        objective = { "35:2039493396:157535420", "รอสักครู่แล้วคุยกับ J.D. Collie" },
        description = { "116:89904777:881337948 N 101:1694659086:1515739002", "ข้อมูลเกี่ยวกับเสาผลึกที่เจ้าให้มาน่าสนใจมาก... ขอข้าคำนวณสักครู่ {name} กลับมาคุยอีกครั้งในไม่ช้า ข้าน่าจะให้คำตอบที่เราตามหาได้" },
        completion = { "9:505169621:1042608785 N 201:1451733746:1505033544 N 1:46:46", "เอาล่ะ {name} น่าทึ่งจริง ๆ... ข้าหวังเพียงว่าแผนภาพจะถูกต้อง! ข้ารวบรวมทุกอย่างไว้ในคู่มือนี้ เจ้าเอาไปได้ ตอนนี้ข้าเชื่อว่าตอบคำถามเรื่องผลึกที่เจ้าสงสัยได้แล้ว {name}" },
    },
    [4381] = { -- Crystal Restore
        title = { "15:771474959:509195872", "ผลึกฟื้นฟู" },
        progress = { "176:1747483354:1803982680", "แท่นของเสาผลึกให้เจ้าผสมผลึกพลังสีเขียวกับสีเหลือง ตามคู่มือของ J.D. ผลที่ได้ใช้รักษาตัวเองหรือพันธมิตรได้" },
        completion = { "191:1717103911:118958921", "เจ้าจัดผลึกบนแท่น ค่อย ๆ เรียงสีให้ตรงกัน เมื่อดันชิ้นสุดท้ายเข้าที่ แสงก็วาบขึ้นหลอมผลึกเข้าด้วยกัน ผลลัพธ์จากการผสมเป็นของเจ้าแล้ว" },
        description = { "176:1747483354:1803982680", "แท่นของเสาผลึกให้เจ้าผสมผลึกพลังสีเขียวกับสีเหลือง ตามคู่มือของ J.D. ผลที่ได้ใช้รักษาตัวเองหรือพันธมิตรได้" },
