    [4491] = { -- A Little Help From My Friends
        title = { "29:547431693:684993899", "ความช่วยเหลือเล็กน้อยจากสหาย" },
        objective = { "104:934625903:1489272667", "นำทาง Ringo ไปหา Spraggle Frock ที่ Marshal's Refuge หาก Ringo เป็นลม ให้ใช้ Spraggle's Canteen ทำให้เขาฟื้น" },
        description = { "407:1697216175:730763994", "อึก... ร้อนเหลือเกิน... ข้ากำลังสำรวจบริเวณนี้ แล้วจู่ ๆ ความร้อนก็รุนแรงจนทนไม่ไหว ข้าคงอ่อนเพลียจากความร้อน ได้โปรด ช่วยพาข้ากลับไปหาสหายชื่อ Spraggle ที่ Marshal's Refuge ข้าคิดว่ายังพอเดินตามเจ้าไปได้ ข้ารู้สึกมึน ๆ หากเป็นลมอีก ก็สาดน้ำจากกระติกของ Spraggle ใส่ข้าสักหน่อย น่าจะได้ผล ข้าหวังว่าอย่างนั้น..." },
        progress = { "35:2055289368:322279274", "ข้าเป็นห่วง Ringo มาก..." },
        completion = { "31:895232937:1161658831 N 73:1472950449:1552192275", "อาการของ Ringo ยังไม่ดีนัก {name} แต่ข้าดีใจที่เขากลับมาอย่างปลอดภัย! ขอบคุณที่ตามหาเขา" },
    },
    [4492] = { -- Lost!
        title = { "5:579590494:1158684551", "หายตัวไป!" },
        objective = { "31:776010327:789413754", "ตามหา Ringo ที่ Fire Plume Ridge" },
        description = { "23:1465131034:1382188801 N 263:2020366126:853125030", "เจ้าต้องช่วยข้านะ {name}! Ringo สหายของข้าออกไปสำรวจภูเขาไฟทางใต้ก่อนหน้านี้ แล้วหายไปนานเกินไป ข้าเป็นห่วงเขามาก เจ้าคิดว่าจะหาเขาพบไหม? เอากระติกน้ำของข้าติดตัวไปด้วยสิ หากพบ Ringo ข้ามั่นใจว่าเขาต้องใช้มัน!" },
        progress = { "12:1355258082:1099410896", "อะ... อะไรนะ?" },
        completion = { "37:672377510:817875828", "โอ้... ข้าดีใจเหลือเกินที่มีคนมาพบ..." },
        required = { [15722] = { "18:3837971:588657908", "กระติกน้ำของ Spraggle" } },
        objectiveLabels = {
            item = { ["Spraggle's Canteen"] = "กระติกน้ำของ Spraggle" },
        },
    },
    [4501] = { -- Beware of Pterrordax
        title = { "20:985751738:2016963901", "ระวัง Pterrordax" },
        objective = { "96:333686697:836961997", "กำจัด Pterrordax 10 ตัว และ Frenzied Pterrordax 15 ตัว แล้วคุยกับ Spraggle Frock ที่ Marshal's Refuge" },
        description = { "327:970406491:970124522", "ต้องการนักสู้มีฝีมือมาจัดการภัยจาก Pterrordax ที่อาศัยใน Un'Goro Crater พวกมันเพิ่มจำนวนและเริ่มเป็นอันตรายต่อนักเดินทางในบริเวณนี้ ลดจำนวนด้วยการกำจัด Pterrordax 10 ตัว และ Frenzied Pterrordax 15 ตัว เสร็จแล้วคุยกับ Spraggle Frock เพื่อรับรางวัล" },
        progress = { "246:2092982781:1464588194", "บอกตามตรง ข้าไม่ได้กังวลกับสิ่งมีชีวิตประหลาดพวกนั้นมากนัก... จนวันที่เห็นข้อความเขียนบนด้านข้างของหินใหญ่ ระวัง Pterrordax ใครเป็นคนเขียน? ข้าไม่รู้ แต่มันชวนขนลุกเกินกว่าจะมองข้าม!" },
        completion = { "90:1564887364:321232857 N 66:81889325:1937621801", "ข้ากลัว Pterrordax ที่นี่เหลือเกิน! ขอบคุณที่ช่วยลดจำนวนมัน {name} ตอนนี้ข้าอาจรู้สึกปลอดภัยพอจะออกจาก Marshal's Refuge บ้าง" },
        objectiveLabels = {
            monster = { ["Pterrordax slain"] = "ปราบ เทอร์โรแด็กซ์", ["Frenzied Pterrordax slain"] = "ปราบ เทอร์โรแด็กซ์คลุ้มคลั่ง" },
        },
    },
    [4502] = { -- Volcanic Activity
        title = { "17:980269377:1114987204", "ความเคลื่อนไหวของภูเขาไฟ" },
        objective = { "140:2055069367:560769038", "เก็บตัวอย่าง Un'Goro Ash 9 กองจากภูตไฟรอบภูเขาไฟใน Un'Goro Crater แล้วนำกลับไปให้ Liv Rizzlefix ที่ Ratchet" },
        description = { "470:1328148893:58589438", "ในฐานะศิษย์ของ Marvon Rivetseeker ข้าได้เรียนรู้มากมาย แต่เขาออกไปนานแล้ว ข้าจึงคิดจะทดลองอะไรของตัวเองบ้าง ช่วงนี้ข้าอ่านเรื่อง Un'Goro Crater และความเคลื่อนไหวแปลก ๆ ของภูเขาไฟกลางปล่อง ข้าคิดว่าคงเรียนรู้ได้มาก หากได้เถ้าบางส่วนจากภูตธาตุที่นั่น หากเจ้าจะไปทางนั้น ช่วยเก็บให้ข้าสักหน่อยได้ไหม?" },
        progress = { "111:2038576629:1867779046 N 1:46:46", "จริงหรือที่ภูเขาไฟใน Un'Goro ยังมีพลังอยู่? ข้ามั่นใจว่าเรียนรู้ได้มากจากเถ้าของภูเขาไฟนะ {name}" },
        completion = { "57:1821045244:918352742 N 67:1820111062:1196420896", "ตัวอย่างเหล่านี้เหมาะที่สุดกับการศึกษาของข้า! ขอบคุณ {name}! ข้าสัญญาว่าเจ้าจะเป็นคนแรกที่รู้ผลการค้นพบ" },
        required = { [11829] = { "11:1632186402:2102489689", "เถ้าจาก Un'Goro" } },
        steps = { { "11:1632186402:2102489689", "เถ้าจาก Un'Goro" } },
    },
    [4503] = { -- Shizzle's Flyer
        title = { "15:711284420:1649888651", "เครื่องบินของ Shizzle" },
        objective = { "99:1251355952:1805998767", "เก็บ Webbed Diemetradon Scale 8 ชิ้น และ Webbed Pterrordax Scale 8 ชิ้นให้ Shizzle ที่ Marshal's Refuge" },
        description = { "464:496758085:1757354312", "ข้ากำลังสร้างเครื่องบิน! ข้าติดอยู่ที่นี่และหาทางไปไหนไม่เก่งเอาเสียเลย ข้าคงนั่งกริฟฟอนหรือวินด์ไรเดอร์กลับ Gadgetzan แล้ว แต่สัตว์พวกนั้นทำข้ากลัวแทบตาย เจ้าจะช่วยไหม? เหลือเพียงปีกที่ยังไม่ได้สร้าง ข้าคิดว่าเกล็ดเป็นพังผืดจาก pterrordax กับ diemetradon น่าจะเหมาะที่สุด ข้าไม่มีทางไปสู้กับพวกมันแน่ แต่เจ้าดูแข็งแกร่ง ลองดูหน่อยเป็นไร?" },
        progress = { "72:72263772:184622557", "พาหนะยิ่งใหญ่ทุกคันต้องมีชื่อ... ข้าคิดว่าจะเรียกมันว่า... Pwned!" },
        completion = { "116:1782741655:1829800785", "ใช่ เกล็ดพวกนี้สมบูรณ์แบบ ต้องใช้มันทำให้เครื่องบินของข้าทะยานจากพื้นได้แน่นอน! ขอบใจ!" },
        required = { [11830] = { "24:1175842231:1467577539", "เกล็ดมีพังผืดของ Diemetradon" }, [11831] = { "23:276233675:1267763481", "เกล็ดมีพังผืดของ Pterrordax" } },
        steps = { { "24:1175842231:1467577539", "เกล็ดมีพังผืดของ Diemetradon" }, { "23:276233675:1267763481", "เกล็ดมีพังผืดของ Pterrordax" } },
    },
    [5150] = { -- Dadanga is Hungry!
        title = { "18:1199464060:625274324", "Dadanga หิวแล้ว!" },
        progress = { "299:1211746042:1224333867", "Dadanga เงยหน้ามองเมื่อเจ้าเข้าใกล้ ดูเหมือนนางหวังอะไรบางอย่าง... คงหิวอยู่แน่! ต้องมีพืชที่ขึ้นในปล่องภูเขาไฟซึ่งเหมาะเป็นของว่างให้สัตว์กินพืชตัวใหญ่ Dadanga ตัวโต ไม่ว่าเจ้าจะนำอะไรมา ก็ต้องใช้มากทีเดียว!" },
        completion = { "140:1942026136:1684443103", "เมื่อเจ้าวางต้นอ่อนตรงหน้า Dadanga ดูพอใจ นางดันห่อของสีน้ำตาลเล็ก ๆ มาให้เจ้าเพื่อแลกกับของกิน!" },
        description = { "299:1211746042:1224333867", "Dadanga เงยหน้ามองเมื่อเจ้าเข้าใกล้ ดูเหมือนนางหวังอะไรบางอย่าง... คงหิวอยู่แน่! ต้องมีพืชที่ขึ้นในปล่องภูเขาไฟซึ่งเหมาะเป็นของว่างให้สัตว์กินพืชตัวใหญ่ Dadanga ตัวโต ไม่ว่าเจ้าจะนำอะไรมา ก็ต้องใช้มากทีเดียว!" },
        required = { [11315] = { "17:1612547331:804896053", "ต้นอ่อน Bloodpetal" } },
        objectiveLabels = {
            item = { ["Bloodpetal Sprout"] = "ต้นอ่อน Bloodpetal" },
        },
    },
    [939] = { -- Flute of Xavaric
        title = { "16:1715355207:505934194", "ขลุ่ยของ Xavaric" },
        objective = { "97:2048622651:206915940", "นำ Flute of Xavaric และตัวอย่าง Jadefire Felbind 5 ชิ้นไปให้ Eridan Bluewind ทางใต้ของ Felwood" },
        description = { "479:1801264146:396110555", "เจ้าพิจารณาขลุ่ยไม้เรียบง่ายที่เก็บมาหลังปราบ Xavaric เนื้อไม้มีปมให้ความรู้สึกแน่นหนา แต่เมื่อลองพลิกในมือ ลายวนและลวดลายบนผิวก็ดูราวกับเริ่มหมุนเคลื่อนไหว จู่ ๆ เจ้ารู้สึกถึงความหวาดกลัว... เจ้าส่ายศีรษะ มั่นใจว่าเป็นเพียงความคิดที่หลอกตนเอง เป็นไปได้ว่าเซเทียร์ตนอื่นมีเบาะแสเกี่ยวกับสิ่งที่พบ นำสิ่งที่ค้นพบไปให้ดรูอิด Eridan Bluewind ซึ่งอาศัยทางใต้ของ Felwood" },
        progress = { "12:351164566:2103200252 C 21:571800051:1051078688", "มีอะไรหรือ {class}? เจ้าดูกังวล" },
        completion = { "39:1361254441:1315652892 N 47:1373296410:115422168", "ข้าสัมผัสความทุกข์ของเหล่าแอนเชียนต์ได้ {name}... การถือสิ่งเหล่านี้แทบทนไม่ไหว..." },
        required = { [11668] = { "16:1715355207:505934194", "ขลุ่ยของ Xavaric" }, [11674] = { "16:1267722154:1789038225", "เครื่องพันธนาการเฟลของ Jadefire" } },
        steps = { { "16:1715355207:505934194", "ขลุ่ยของ Xavaric" }, { "16:1267722154:1789038225", "เครื่องพันธนาการเฟลของ Jadefire" } },
