    [4105] = { -- Salve via Gathering
        title = { "19:1415421911:768227474", "ยาทาจากการเก็บสมุนไพร" },
        progress = { "453:213335821:142151917", "Cenarion Beacon ทำให้นักเก็บสมุนไพรที่มีประสบการณ์มองเห็น Fel Creep อันร้ายกาจ ผลพวงชั่วร้ายของความเสื่อมทรามใน Felwood งานที่นี่สอนให้ข้ารู้วิธีชำระ Fel Creep เป็นวัตถุดิบล้างมลทิน... ซึ่งใช้ทำสิ่งที่เราเรียกว่ายาทาพืช Cenarion ตราบใดที่มี Beacon เจ้าควรพบ Fel Creep ขณะเก็บสมุนไพรใน Felwood หากนำมาให้ ข้าจะให้ยาทาพืช Cenarion ที่ทำเสร็จแล้วเป็นการแลกเปลี่ยน" },
        completion = { "15:164794247:1541488341 N 205:1440391206:2001718507 R 1:33:33", "ทำได้ดี {name} ทุกส่วนที่ชำระแล้วจะช่วยเราทวง Felwood คืน นี่ รับยาทาพืช Cenarion ไปแล้วมุ่งเข้าป่า การทวงแผ่นดินจากความเสื่อมทรามไม่รอ {race} คนใด!" },
        description = { "453:213335821:142151917", "Cenarion Beacon ทำให้นักเก็บสมุนไพรที่มีประสบการณ์มองเห็น Fel Creep อันร้ายกาจ ผลพวงชั่วร้ายของความเสื่อมทรามใน Felwood งานที่นี่สอนให้ข้ารู้วิธีชำระ Fel Creep เป็นวัตถุดิบล้างมลทิน... ซึ่งใช้ทำสิ่งที่เราเรียกว่ายาทาพืช Cenarion ตราบใดที่มี Beacon เจ้าควรพบ Fel Creep ขณะเก็บสมุนไพรใน Felwood หากนำมาให้ ข้าจะให้ยาทาพืช Cenarion ที่ทำเสร็จแล้วเป็นการแลกเปลี่ยน" },
        required = { [11514] = { "9:666927853:1852412457", "เฟลครีป" } },
        objectiveLabels = {
            item = { ["Fel Creep"] = "เฟลครีป" },
        },
    },
    [4106] = { -- Salve via Skinning
        title = { "18:328384737:390754916", "ยาทาจากการถลกหนัง" },
        progress = { "436:1574232873:656416797", "Cenarion Beacon ช่วยให้ผู้ถลกหนังที่ชำนาญมองเห็น Patch of Tainted Skin จากสัตว์ที่ล่าใน Felwood ข้าเปลี่ยนเศษหนังแปดเปื้อนที่ดูไร้ประโยชน์เหล่านี้เป็นเนื้อยาข้น ใช้เป็นตัวเร่งสำหรับยาทาพืช Cenarion เวลาถลกหนังสัตว์ที่เจ้าสังหารที่นี่ อย่าลืมมี Beacon ติดตัว! เมื่อเก็บชิ้นหนังแปดเปื้อนได้ นำมาให้ข้า แล้วข้าจะมอบยาทาพืช Cenarion ที่ทำไว้แล้วให้" },
        completion = { "132:2027665186:364307009 N 1:33:33", "นี่คือสิ่งที่ข้าต้องการพอดี รับยาทาพืชเหล่านี้ไป แล้วใช้ทวง Felwood คืนจากความเสื่อมทราม เราต้องไม่ย่อท้อ {name}!" },
        description = { "436:1574232873:656416797", "Cenarion Beacon ช่วยให้ผู้ถลกหนังที่ชำนาญมองเห็น Patch of Tainted Skin จากสัตว์ที่ล่าใน Felwood ข้าเปลี่ยนเศษหนังแปดเปื้อนที่ดูไร้ประโยชน์เหล่านี้เป็นเนื้อยาข้น ใช้เป็นตัวเร่งสำหรับยาทาพืช Cenarion เวลาถลกหนังสัตว์ที่เจ้าสังหารที่นี่ อย่าลืมมี Beacon ติดตัว! เมื่อเก็บชิ้นหนังแปดเปื้อนได้ นำมาให้ข้า แล้วข้าจะมอบยาทาพืช Cenarion ที่ทำไว้แล้วให้" },
        required = { [11512] = { "21:1803362651:867294880", "เศษหนังแปดเปื้อน" } },
        objectiveLabels = {
            item = { ["Patch of Tainted Skin"] = "เศษหนังแปดเปื้อน" },
        },
    },
    [4107] = { -- Salve via Disenchanting
        title = { "23:1690998074:1717195322", "ยาทาจากการสลายมนตร์" },
        progress = { "479:2014698740:989243902", "พลังของไอเทมเวทมนตร์ที่ถูกสลายยังสัมผัสได้จากแก่นพลังที่มันสร้าง ข้าคิดวิธีเปลี่ยนแก่นพลังดิบที่นักเสริมมนตร์ใช้ ให้เป็นวัตถุดิบสำหรับยาทาพืช Cenarion ได้ วิธีนี้ไม่ต้องมี Cenarion Beacon ไอเทมใดที่สลายแล้วได้ Lesser Nether Essence ก็ใช้ได้ ข้าต้องการเพียงหนึ่งชิ้น แลกกับยาทาพืช Cenarion แก่นพลังนี้ทรงอานุภาพมาก ใช้เพียงนิดก็ให้ผลมากทีเดียว!" },
        completion = { "86:311525522:1669327732 N 145:795620262:475416705", "นี่คือยาทาพืช Cenarion ข้าต้องการ Lesser Nether Essence เพียงหนึ่งชิ้นสำหรับงานนี้ {name} แก่นพลังเป็นของทรงอานุภาพที่สุดที่ข้าใช้เปลี่ยนเครื่องมือทำลายล้างให้หล่อเลี้ยงชีวิตได้ หากจะเปรียบเช่นนั้น หากต้องการยาเพิ่ม ก็มาหาข้าที่นี่!" },
        description = { "479:2014698740:989243902", "พลังของไอเทมเวทมนตร์ที่ถูกสลายยังสัมผัสได้จากแก่นพลังที่มันสร้าง ข้าคิดวิธีเปลี่ยนแก่นพลังดิบที่นักเสริมมนตร์ใช้ ให้เป็นวัตถุดิบสำหรับยาทาพืช Cenarion ได้ วิธีนี้ไม่ต้องมี Cenarion Beacon ไอเทมใดที่สลายแล้วได้ Lesser Nether Essence ก็ใช้ได้ ข้าต้องการเพียงหนึ่งชิ้น แลกกับยาทาพืช Cenarion แก่นพลังนี้ทรงอานุภาพมาก ใช้เพียงนิดก็ให้ผลมากทีเดียว!" },
        required = { [11174] = { "21:65819799:666435846", "แก่นเนเธอร์ระดับต่ำ" } },
        objectiveLabels = {
            item = { ["Lesser Nether Essence"] = "แก่นเนเธอร์ระดับต่ำ" },
        },
    },
    [4108] = { -- Salve via Hunting
        title = { "17:1521375278:2092582707", "ยาทาจากการล่า" },
        progress = { "385:1539532824:1397921024", "การมี Cenarion Beacon ทำให้มองเห็น Corrupted Soul Shard บนสัตว์แปดเปื้อนที่ถูกกำจัดเพื่อประโยชน์ส่วนรวม ข้าบดเศษเหล่านี้เป็นวัตถุดิบสำหรับทำยาทาพืช Cenarion เราจะใช้ยาเปลี่ยนพืชเสื่อมทรามให้กลับแข็งแรง หากเจ้านำเศษเหล่านี้มาแลก ข้าจะให้ยาทาพืช Cenarion ที่เตรียมไว้แล้ว" },
        completion = { "89:1314801438:1651187321 N 67:1503815693:883581745", "ดีมาก นี่คือยาทาพืช Cenarion ของเจ้า จงค้นหาพืชเสื่อมทรามทั่ว Felwood {name}! พบที่ใดก็ใช้ยาที่ข้าให้ชำระล้างพวกมัน" },
        description = { "385:1539532824:1397921024", "การมี Cenarion Beacon ทำให้มองเห็น Corrupted Soul Shard บนสัตว์แปดเปื้อนที่ถูกกำจัดเพื่อประโยชน์ส่วนรวม ข้าบดเศษเหล่านี้เป็นวัตถุดิบสำหรับทำยาทาพืช Cenarion เราจะใช้ยาเปลี่ยนพืชเสื่อมทรามให้กลับแข็งแรง หากเจ้านำเศษเหล่านี้มาแลก ข้าจะให้ยาทาพืช Cenarion ที่เตรียมไว้แล้ว" },
        required = { [11515] = { "20:1071122349:465958943", "เศษวิญญาณแปดเปื้อน" } },
        objectiveLabels = {
            item = { ["Corrupted Soul Shard"] = "เศษวิญญาณแปดเปื้อน" },
        },
    },
    [4109] = { -- Salve via Mining
        title = { "16:1165359430:318710617", "ยาทาจากการขุดแร่" },
        progress = { "423:1755659678:1357236024", "หากเจ้ามี Cenarion Beacon ขณะขุดแร่ใน Felwood ก็จะมองเห็น Tainted Vitriol ที่ปนเปื้อนสายแร่ ข้ารู้วิธีชำระล้างมันให้เป็นวัตถุดิบทำยาทาพืช Cenarion แล้วเจ้าจะใช้ยากับพืชตามป่าที่ต้องการความช่วยเหลือ หากเก็บ Tainted Vitriol มาได้ ข้าจะมอบยาทาพืช Cenarion ที่เตรียมไว้ให้" },
        completion = { "198:1833067123:1123774900", "ดีมาก นี่คือยาทาพืช Cenarion หากพบ Vitriol เพิ่มขณะขุดแร่ใน Felwood ก็จำไว้ว่าให้เก็บมาให้ข้า! เจ้ายิ่งพบมาก ข้าก็ยิ่งทำยาได้มาก" },
        description = { "423:1755659678:1357236024", "หากเจ้ามี Cenarion Beacon ขณะขุดแร่ใน Felwood ก็จะมองเห็น Tainted Vitriol ที่ปนเปื้อนสายแร่ ข้ารู้วิธีชำระล้างมันให้เป็นวัตถุดิบทำยาทาพืช Cenarion แล้วเจ้าจะใช้ยากับพืชตามป่าที่ต้องการความช่วยเหลือ หากเก็บ Tainted Vitriol มาได้ ข้าจะมอบยาทาพืช Cenarion ที่เตรียมไว้ให้" },
        required = { [11513] = { "15:1159872086:957350447", "ไวทริออลปนเปื้อน" } },
        objectiveLabels = {
            item = { ["Tainted Vitriol"] = "ไวทริออลปนเปื้อน" },
        },
    },
