    [4261] = { -- Ancient Spirit
        title = { "14:412908568:383606122", "วิญญาณโบราณ" },
        objective = { "94:29548413:459802811", "คุ้มกัน Arei ไปยังที่ปลอดภัย แล้วคุยกับ Kayneth Stillwind ที่ Forest Song ทางตะวันออกของ Ashenvale" },
        description = { "319:2022179917:1377400388 N 177:991918586:686486745", "Felwood เคยเป็นดินแดนสงบและร่มเย็น... จนกระทั่ง Legion เข้ายึดครอง เหล่าอินเฟอร์นัล การทำลายล้าง ความโกลาหล... กะโหลกของ Gul'dan ทำให้ไม่มีผู้ใดรอดพ้น ทุกสิ่งตกสู่ความเสื่อมทราม แม้ตอนนี้เป็นวิญญาณ ข้าก็ยังติดอยู่ แบกรับความทุกข์ของดินแดน ช่วยข้าหาทางกลับบ้านเถิด ได้โปรด {name} บอกทีว่าเจ้าจะนำวิญญาณโบราณออกจากที่นี่ ไปยังที่ซึ่งข้าจะได้พักสงบเสียที เมื่อข้าเป็นอิสระ จงตามหา Kayneth Stillwind ดรูอิดที่อาศัยใน Forest Song ทางตะวันออก" },
        progress = { "42:367752503:460652123", "เจ้าเห็นอะไรในดินแดนเสื่อมทรามแห่งนี้บ้าง?" },
        completion = { "5:1287366450:669725923 N 162:702017089:1242267239", "ใช่ {name} Felwood ผ่านความยากลำบากมามาก ขอบคุณสำหรับสิ่งที่เจ้าทำ สักวันเราอาจทวง Felwood คืนจากความเสื่อมทรามได้ ความดีทุกอย่างล้วนช่วยทั้งนั้น" },
    },
