        progress = { "233:1266691614:1680626214", "เจ้าพบสิ่งที่ดูเหมือนต้น Windblossom ซึ่งป่วยและเสื่อมทราม ผลเบอร์รีที่ห้อยอยู่ดูเน่าเสียและมีพิษ มันต้องการการดูแลอย่างเร่งด่วนจึงจะกลับเป็นปกติได้" },
        completion = { "150:1814206706:1910637361", "เจ้าใช้ยาทาพืช Cenarion สองชุดกับ Windblossom มันเริ่มสลัดร่างเสื่อมทรามทันที แล้วเบ่งบานเป็นพืชที่แข็งแรงและมีชีวิตชีวา" },
        description = { "233:1266691614:1680626214", "เจ้าพบสิ่งที่ดูเหมือนต้น Windblossom ซึ่งป่วยและเสื่อมทราม ผลเบอร์รีที่ห้อยอยู่ดูเน่าเสียและมีพิษ มันต้องการการดูแลอย่างเร่งด่วนจึงจะกลับเป็นปกติได้" },
