    [4421] = { -- The Corruption of the Jadefire
        title = { "30:1828516562:99054590", "ความเสื่อมทรามของ Jadefire" },
        objective = { "159:114431030:481233646", "กำจัด Jadefire Felsworn 11 ตัว, Jadefire Shadowstalker 9 ตัว, Jadefire Rogue 9 ตัว และ Xavathras เสร็จแล้วกลับไปหา Eridan Bluewind ใน Felwood" },
        description = { "502:209947596:138206122", "มีไม่กี่คนแสวงหาการผจญภัยที่นี่... ความเสื่อมทรามของ Felwood แผ่กว้างโดยไม่เลือกผู้ใด ในฐานะสมาชิก Emerald Circle ข้ามุ่งเยียวยาดินแดน แต่บางพวกกลับอยากให้มันเน่าเฟะ ข้าหมายถึงเซเทียร์ Jadefire ที่ Ruins of Constellas ทางตะวันตกเฉียงเหนือ พวกมันนำโดยเซเทียร์โหดร้ายนาม Xavathras และยังแพร่โรคสู่สิ่งมีชีวิตทุกอย่างที่พบ เราต้องปกป้องดินแดนที่ครั้งหนึ่งเป็นของเรา ปราบ Xavathras และทำลายสมุนของมัน" },
        progress = { "56:729312518:243500155", "ความเสื่อมทรามที่นี่ผลักให้สิ่งมีชีวิตเสียสติ..." },
        completion = { "263:1764871907:1007337981", "การกำจัด Xavathras จาก Felwood เป็นเพียงก้าวแรกในกระบวนการอันยาวนาน ต้องทำงานอีกมากเพื่อซ่อมแซมความเสียหาย ข้าสัมผัสว่ามีบางสิ่งที่ใหญ่โตกว่าแค่เหล่าเซเทียร์กำลังเคลื่อนไหวที่นี่ แต่คงต้องรอเวลาจึงจะรู้ความจริง..." },
        objectiveLabels = {
            monster = { ["Jadefire Felsworn slain"] = "ปราบ ผู้สาบานตนต่อเฟลแห่ง Jadefire", ["Jadefire Shadowstalker slain"] = "ปราบ นักสะกดรอยในเงา Jadefire", ["Jadefire Rogue slain"] = "ปราบ โจร Jadefire", ["Xavathras slain"] = "ปราบ Xavathras" },
        },
    },
    [4441] = { -- Felbound Ancients
        title = { "17:799937843:1548347396", "แอนเชียนต์ที่ถูกพันธนาการด้วยเฟล" },
        objective = { "144:823646679:613957331", "เดินทางไป Darnassus ใช้ Eridan's Vial เก็บ Vial of Blessed Water จาก Temple of the Moon แล้วนำขวดที่เติมแล้วกลับไปให้ Eridan" },
        description = { "436:64060927:1547128393 N 66:548127159:1672291951", "ขลุ่ยที่เจ้าพบถูกแกะจากผู้พิทักษ์โบราณ พันธมิตรทรีแอนต์ที่ปกป้องไนต์เอลฟ์อย่างซื่อสัตย์ เซเทียร์ทำให้ทุกสิ่งที่สัมผัสเสื่อมทรามได้ รวมถึงเหล่าแอนเชียนต์ที่มี Felwood เป็นบ้าน พลังเฟลพันธนาการและทรมานวิญญาณแอนเชียนต์ ไม่ยอมปลดปล่อยอย่างสมบูรณ์ Felbind ที่เจ้าพบย่อมเกี่ยวข้องแน่ เราต้องพยายามชำระขลุ่ย {name} นำน้ำศักดิ์สิทธิ์จาก Temple of the Moon ใน Darnassus มาให้ข้า" },
        progress = { "88:1611532092:1922946147", "หวังว่าน้ำจะปลดปล่อยวิญญาณแอนเชียนต์ และทำให้ได้พักสงบ" },
        completion = { "11:1191658970:1224418299 N 69:909296793:1810080528", "ขอบคุณ {name} ตอนนี้เราต้องภาวนาให้แก้ไขความเสียหายที่เกิดขึ้นได้..." },
        required = { [5646] = { "21:1608273970:1618028142", "ขวดน้ำศักดิ์สิทธิ์" } },
        steps = { { "21:1608273970:1618028142", "ขวดน้ำศักดิ์สิทธิ์" } },
    },
    [4442] = { -- Purified!
        title = { "9:641346566:142717812", "ชำระล้างแล้ว!" },
        objective = { "34:1941848804:842123669", "รอสักครู่แล้วคุยกับ Eridan อีกครั้ง" },
        description = { "160:1142490818:1205287862", "ข้าจะลองใช้น้ำแห่ง Elune ชำระขลุ่ย เราต้องยุติความทุกข์นี้... ขอ Elune ชี้นำมือและหัวใจของข้า กลับมาคุยอีกครั้งในไม่ช้า" },
        completion = { "417:1079032867:1128790668", "ด้วยน้ำศักดิ์สิทธิ์ ข้าตัดสายสัมพันธ์ระหว่างขลุ่ยกับวิญญาณแอนเชียนต์ได้แล้ว แต่ข้าเชื่อว่าหากเจ้าใช้ขลุ่ยในสถานที่ศักดิ์สิทธิ์ อาจอัญเชิญวิญญาณแอนเชียนต์ได้ บางทีเจ้าควรลองที่ซากเมืองทางใต้ของ Irontree Woods ครั้งหนึ่งทรีแอนต์เสื่อมทรามอาศัยอยู่มากในบริเวณนี้ เป็นไปได้ว่าพวกเขายังคงอยู่ แม้ในร่างวิญญาณ" },
    },
