    [4505] = { -- Well of Corruption
        title = { "18:1578076099:1336280276", "บ่อน้ำแห่งความเสื่อมทราม" },
        objective = { "120:865793725:1132114100", "เก็บตัวอย่างน้ำเสื่อมทรามจากบ่อน้ำจันทราของเซเทียร์ Jadefire แล้วนำไปให้ Winna Hazzard ที่ Bloodvenom Post" },
        description = { "413:1528780162:144262805 N 73:925664824:661399987", "บางคนอาจว่าข้าโหดร้ายเป็นพิเศษ... แต่ที่จริง ก็เพียงปรารถนาอย่างแรงกล้าให้ Horde ได้เปรียบ Alliance ไม่ว่าด้วยวิธีใด สิ่งที่ข้าสนใจล่าสุดคือบ่อน้ำจันทราที่ Ruins of Constellas ทางใต้ เซเทียร์ Jadefire ดูแลมันอยู่ บ่อซึ่งครั้งหนึ่งเป็นสัญลักษณ์แห่งการฟื้นฟูของพวกไนต์เอลฟ์น่ารำคาญ บัดนี้เสื่อมทรามและถูกใช้เรียกเซเทียร์เพิ่ม ข้ามีความคิดหนึ่ง {name} และอยากได้ตัวอย่างน้ำ... สำหรับสหายแมวน้อยของข้าตรงนี้" },
        progress = { "50:651161968:2016461104", "นี่เป็นเรื่องสำคัญที่สุด ออกเดินทางได้แล้ว" },
        completion = { "75:772327662:338654586", "ดีมาก เราต้องหาวิธีใช้ความเสื่อมทรามนี้ต่อกรศัตรู..." },
        required = { [12567] = { "14:440373751:1838672374", "ขวดน้ำที่เติมเต็มแล้ว" } },
        objectiveLabels = {
            item = { ["Filled Flasket"] = "ขวดน้ำที่เติมเต็มแล้ว" },
        },
    },
    [4506] = { -- Corrupted Sabers
        title = { "16:1797027539:274592565", "เสือเขี้ยวดาบเสื่อมทราม" },
        objective = { "161:1103122192:237975467", "นำลูกแมวของ Winna ไปยังบ่อน้ำจันทราเสื่อมทราม ปล่อยมันออก แล้วพากลับมาหา Winna เมื่อกลับถึง ให้คลิกที่แมวเพื่อปล่อยมันคืนแก่ Winna", variants = { { "162:918625637:694099736", "นำลูกแมวของ Winna ไปยังบ่อน้ำจันทราเสื่อมทราม ปล่อยมันออก แล้วพากลับมาหา Winna เมื่อกลับถึง ให้คลิกที่แมวเพื่อปล่อยมันคืนแก่ Winna" } } },
        description = { "51:1303734888:455421321 N 142:1236140281:635362178 N 227:1173163128:1747839216", "น้ำเสื่อมทรามนี้ใช้ให้เป็นประโยชน์แก่เราได้ {name} แค่น้ำเล็กน้อย ลูกแมวของข้าก็ตัวโตเป็นสองเท่า และดูแข็งแรงขึ้น... อย่างน่าประหลาด แมวพวกนี้อาจมีประโยชน์... นี่ {name} นำกรงแมวไป แล้วปล่อยลูกแมวข้างในใกล้บ่อน้ำจันทราที่ Ruins of Constellas ฮึ ๆ... ข้ามั่นใจว่าเจ้าจะพอใจผลลัพธ์! นำแมวกลับมา แล้วข้าจะตอบแทนให้คุ้มเวลาแน่" },
        progress = { "54:267456140:168291029", "อย่าบอกว่าเจ้ากลับไปที่นั่นไม่ได้! รีบไป!" },
        completion = { "162:128246579:1632139612", "ยอดเยี่ยม! เหล่า Forsaken จะใช้ทุกวิธีที่จำเป็นเพื่อบดขยี้ Alliance! น้ำเสื่อมทรามนี้จะมีประโยชน์ต่อความพยายามในอนาคตแน่..." },
    },
    [4521] = { -- Wild Guardians
        title = { "14:1540168570:2764417", "ผู้พิทักษ์พงไพร" },
        objective = { "88:1757856204:664855235", "Trull Failbane ใน Felwood ต้องการให้เจ้ากำจัด Raging Owlbeast 15 ตัว และ Ragged Owlbeast 15 ตัว" },
        description = { "495:1676054482:1138177655", "Winterspring อยู่ถัดจาก Timbermaw ไปทางตะวันออกเฉียงเหนือของ Felwood เจ้าเคยไปไหม? ข้าได้ยินว่าที่นั่นมีสิ่งมีชีวิตที่เรียกว่า wildkin มากมาย ว่ากันว่าพวกมันเฝ้าความลับของไนต์เอลฟ์ เราต้องหาคำตอบว่า Winterspring ซ่อนอะไรอยู่ ข้าได้ยินว่า Ragged Owlbeast อยู่ทางใต้ของถนน ส่วน Raging Owlbeast พบได้กลาง Winterspring กำจัดพวกมัน แล้วเปิดทางเข้าสู่ดินแดน" },
        progress = { "63:209257262:237533819", "กลับมารายงานเมื่อทำงานที่ข้ามอบหมายสำเร็จแล้ว" },
        completion = { "24:304287222:712208172 N 112:1797110065:1185116656", "ข่าวดีมาก {name} เมื่อสัตว์พวกนี้พ้นทาง เราก็เริ่มสำรวจลึกเข้าไปใน Winterspring ได้ พร้อมสำหรับงานต่อหรือยัง?" },
    },
    [4721] = { -- Wild Guardians
        title = { "14:1540168570:2764417", "ผู้พิทักษ์พงไพร" },
        objective = { "81:664301907:1768659224", "Trull Failbane ใน Felwood ต้องการให้เจ้าล่า Berserk Owlbeast 10 ตัวใน Winterspring" },
        description = { "378:1391535967:300854652 N 98:2107626476:1823768668", "ผู้ส่งสารกลับจาก Winterspring พร้อมรายงานว่ามีถ้ำเล็กหลายแห่งทางใต้ของดินแดน ดูเหมือนมี wildkin อยู่รอบถ้ำเหล่านั้น หากพวกมันเฝ้าสิ่งมีค่า ข้าเชื่อว่าเราจะพบที่นี่ พวกนี้จะท้าทายกว่าชนิดก่อนนะ {name} พวกมันดูเหมือนเสียสติจากการสัมผัสสิ่งที่ตนพยายามปกป้อง" },
        progress = { "22:1192957043:607725971 N 1:46:46", "เจ้ารู้คำสั่งแล้ว {name}" },
        completion = { "49:227052767:1625395475 N 58:2117214415:822233954", "ข้าเคารพการทำงานหนักอย่างยิ่ง {name} ทีนี้เราก็เดินหน้าแผนสำหรับ Winterspring ได้แล้ว" },
    },
    [4741] = { -- Wild Guardians
        title = { "14:1540168570:2764417", "ผู้พิทักษ์พงไพร" },
        objective = { "69:178986378:354313713", "Trull Failbane ใน Felwood ต้องการให้เจ้าล่า Moontouched Owlbeast 13 ตัว" },
        description = { "333:774703151:2116005830", "ทางตอนเหนือของ Winterspring พวก wildkin ดุร้ายยิ่งขึ้น เราต้องดำเนินมาตรการต่อที่นั่น ล่า Moontouched Owlbeast ใน Winterspring แล้วสำรวจบริเวณที่มันอาศัย พื้นที่นี้อันตราย แต่ข้ารู้ว่าเจ้ารับมือความท้าทายได้ กลับมาหาข้าเมื่อสังหาร wildkin เหล่านั้นได้ 13 ตัว" },
        progress = { "48:2710944:731510205", "อย่าบอกว่าเจ้ากลัวเกินไป! รีบไป!" },
        completion = { "87:1900274016:176295063", "ข้ารู้สึกว่าเจ้าสนุกกับงาน และเชื่อว่าเรากำลังจะพบอะไรบางอย่างที่นี่" },
    },
    [4906] = { -- Further Corruption
        title = { "18:379140021:2111457202", "ความเสื่อมทรามที่ลุกลาม" },
        objective = { "171:1604829267:1295481050", "Eridan Bluewind ใน Felwood ต้องการให้เจ้ากำจัด Jadefire Hellcaller 8 ตัว, Jadefire Betrayer 8 ตัว, Jadefire Trickster 8 ตัว และ Xavaric เสร็จแล้วกลับไปหา Eridan" },
        description = { "392:1602028938:577511225 N 39:257818599:1858024035", "ค่ายเซเทียร์แห่งที่สองคุกคาม Felwood ทางเหนือ นำโดย Xavaric ผู้โหดร้าย พวกทรยศและเจ้าเล่ห์เหล่านี้เลี้ยงตนด้วยความเสื่อมทรามของสิ่งมีชีวิตพื้นถิ่น Xavathras กับสมุนเป็นเพียงส่วนหนึ่งของแผนใหญ่ เพื่อบ่มเพาะบ่อน้ำจันทราเสื่อมทราม แล้วส่งผลประโยชน์ให้ Xavaric เมื่อ Xavathras พ้นทางแล้ว จงทำงานนี้ให้จบ {name} มุ่งเหนือแล้วปราบ Xavaric" },
        progress = { "60:1670889584:854881549", "ได้โปรด ยุติความทุกข์ของสิ่งมีชีวิตแห่ง Felwood" },
        completion = { "33:1237636579:480382133 N 56:985754127:1716505381", "ขอบคุณสำหรับทุกสิ่งที่เจ้าทำ {name} ขอ Elune คุ้มครองและชี้นำเจ้าบนเส้นทางข้างหน้า" },
    },
    [5155] = { -- Forces of Jaedenar
        title = { "18:598254300:525882109", "กองกำลัง Jaedenar" },
        objective = { "154:1663170949:661362374", "เข้า Jaedenar กำจัด Jaedenar Hound 4 ตัว, Jaedenar Guardian 4 คน, Jaedenar Adept 6 คน และ Jaedenar Cultist 6 คน แล้วกลับไปหา Greta Mosshoof ใน Felwood" },
        description = { "494:488709326:2076352681", "หากข้าจะไว้ใจเจ้าเรื่องนี้ เจ้าต้องพิสูจน์ตนก่อน ข้าต้องรู้ว่าเจ้าเป็นศัตรูของ Shadow Council พวกที่รับผิดชอบความชั่วร้ายมากมายทั้งที่นี่และดินแดนอื่น เดินทางลึกเข้าไปใน Felwood ทางตะวันตกเจ้าจะเห็นทางสู่ Jaedenar ที่นั่นสภาวางแผนร่วมกับ Burning Legion เข้าไปในส่วนลึกของ Barrow Den เสื่อมทรามแห่งหนึ่งที่พวกมันอาศัย แล้วสังหารพวกมัน เสร็จแล้วกลับมาหาข้า เมื่อนั้นข้าจะรู้ว่าเจ้าต้องการช่วยเราอย่างแท้จริง" },
        progress = { "21:107172476:1542551936 N 285:1410706874:386130070", "การต่อสู้เป็นอย่างไร {name}? ข้ารู้ว่าการหลั่งเลือดเพื่อพิสูจน์เกียรติอาจน่ารังเกียจสำหรับบางคน แต่ต้องเข้าใจว่ามันบรรลุสองเป้าหมาย เจ้าแบ่งเบางานข้าด้วยการลดกำลังพวกมัน และเราต่างได้รับความเคารพต่อกัน ซึ่งจะทำให้แข็งแกร่งขึ้นในวันข้างหน้า หวังว่าเจ้าจะเข้าใจ" },
        completion = { "6:2014770050:1830635039 N 333:910285037:1445350874", "ดีมาก {name}! เมื่อกำลังพวกมันอ่อนลง เราก็กดดันต่อได้ เจ้าได้สัมผัสพลังของมันครั้งแรกแล้วเป็นอย่างไร? แข็งแกร่งอย่างที่คิดไหม? มากกว่านั้นหรือ? หรือบางทีมันอาจไม่เป็นความท้าทายเลย ช่างน่าทึ่งหากเป็นเช่นนั้น เราคุยรายละเอียดวีรกรรมของเจ้าทีหลังได้ ตอนนี้มีเรื่องอื่นต้องมุ่งจัดการ" },
    },
    [5156] = { -- Verifying the Corruption
        title = { "24:1115890802:2100101774", "ตรวจสอบความเสื่อมทราม" },
        objective = { "220:1439086558:992288981", "ตามหาและกำจัด Entropic Beast 2 ตัว กับ Entropic Horror 2 ตัว ระหว่างสำรวจ Shatter Scar Vale ตรวจว่าแอ่งหลุมยังเต็มไปด้วยน้ำเฟลเสื่อมทรามหรือไม่ แล้วกลับไปหา Taronn Redfeather ใน Felwood" },
        description = { "435:1199025434:1869911874 N 66:2111699077:570921239", "ทางเหนือ ด้านตะวันออกของถนนในบริเวณ Shatter Scar Vale คือพื้นที่ที่อินเฟอร์นัลถูกเรียกลงมาระหว่างมหาสงครามครั้งก่อน แอ่งหลุมยังเป็นแผลบนผืนดิน เช่นเดียวกับเหล่าอินเฟอร์นัล ข้าสงสัยสองเรื่อง อย่างแรก ยังมีภูตธาตุเสื่อมสลายเดินเตร่หรือไม่? อย่างที่สอง แอ่งหลุมยังเต็มไปด้วยน้ำเสื่อมทรามเน่าเหม็นที่สะสมเมื่อหลายปีก่อนหรือไม่? เจ้าช่วยไปตรวจให้ข้าได้ไหม {name}? แต่ระวังด้วย อินเฟอร์นัลทำลายทุกสิ่งที่ขวางทาง" },
        progress = { "30:1943649679:1737446219 N 206:459077144:2080818992", "หวังว่าการค้นหาจะราบรื่น {name} ข้ายังไม่ได้เดินขึ้นเหนือไปไกลขนาดนั้น แต่ยอมรับว่าแค่คิดจะขวางทางอินเฟอร์นัลเมื่อไรก็ทำให้กลัวอยู่นิดหน่อย มันไร้สมอง แต่ยังน่าเกรงขามมาก" },
        completion = { "24:1557357199:1906972317 N 432:1427361974:1154286746", "ดีที่เจ้ายังมีชีวิต {name} แต่แย่ที่น้ำยังคงอยู่ ข้าหวังว่าจะพบแหล่งน้ำบริสุทธิ์อย่างน้อยแห่งหนึ่งใน Felwood ดูเหมือนการค้นหาจะล้มเหลว หากมีน้ำสะอาด กระบวนการเยียวยาดินแดนคงง่ายขึ้นมาก ข้าต้องหันมาช่วยสิ่งมีชีวิตในป่าเท่าที่ทำได้ และกำจัดพวกที่เสื่อมทรามจนเป็นอันตรายทั้งต่อตนเองและนักเดินทางผ่านป่าที่เคยยิ่งใหญ่แห่งนี้" },
        objectiveLabels = {
            event = { ["Explore the craters in Shatter Scar Vale"] = "สำรวจหลุมอุกกาบาตใน Shatter Scar Vale" },
            monster = { ["Entropic Beast slain"] = "ปราบ อสูรแห่งความเสื่อมสลาย", ["Entropic Horror slain"] = "ปราบ ตัวสยองแห่งความเสื่อมสลาย" },
        },
    },
    [5157] = { -- Collection of the Corrupt Water
        title = { "31:1705796938:2064171193", "เก็บน้ำเสื่อมทราม" },
        objective = { "124:1800762740:1287798983", "นำ Empty Canteen ไปเติมน้ำจาก Moon Well กลาง Jaedenar แล้วกลับไปหา Greta Mosshoof ใน Felwood" },
        description = { "483:770076531:270930720", "ลึกเข้าไปใน Jaedenar คือ Shadow Hold ป้อมหลักแห่งความเสื่อมทรามและความชั่วร้าย Shadow Council มีเวทปกป้องรังในรูปของกระถางไฟ หากข้าจะใช้เวทสอดส่องหาข้อมูลศัตรูเพิ่ม ก็ต้องดับกระถางไฟเหล่านั้น เมื่อนั้นข้าน่าจะสอดแนมสภาและรู้ว่าใครเป็นผู้นำได้ หากเจ้าทำได้ นำกระติกนี้ไปเติมที่ Moon Well กลาง Jaedenar แล้วกลับมาหาข้า" },
        progress = { "282:926528872:166492301", "เมื่อได้น้ำจาก Moon Well เราจะชำระให้บริสุทธิ์ แล้วใช้ดับกระถางไฟปกป้องภายใน Shadow Hold น่าจะให้เวลาข้ามากพอจะมองลึกเข้าไปในห้องต่าง ๆ และแยกแยะว่าใครนำ... ลัทธินี้กันแน่ ข้าภาวนาให้พระแม่ธรณีอยู่กับเรา" },
        completion = { "21:1129349402:1903439022 N 192:1678575382:274343799", "นี่ใช้ได้ดี {name} นอกจากนำน้ำไปใช้กับกระถางไฟแล้ว ที่เหลือก็เพียงทำให้บริสุทธิ์ เรื่องนั้นไม่น่ายาก คงต้องเดินทางเล็กน้อย หวังว่าเราจะทำได้รวดเร็ว" },
        required = { [12907] = { "22:2094992062:662680541", "น้ำจากบ่อจันทร์ที่แปดเปื้อน" } },
        objectiveLabels = {
            item = { ["Corrupt Moonwell Water"] = "น้ำจากบ่อจันทร์ที่แปดเปื้อน" },
        },
    },
    [5158] = { -- Seeking Spiritual Aid
        title = { "21:522295732:1013748471", "ขอความช่วยเหลือจากวิญญาณ" },
        objective = { "67:305430410:1111604131", "นำ Corrupt Moon Well Water ไปให้ Islen Waterseer ใน Barrens" },
        description = { "39:1105645411:1835832380 N 392:1356508565:1980423225 N 69:1247350442:1671707216", "นำน้ำเสื่อมทรามไป Barrens {name} ทางใต้ของ Ratchet ริมฝั่งที่ซ่อนตัวอยู่ มีสหายเก่าของข้า ชาแมนชื่อ Islen Waterseer นางทรงพลังและจะช่วยเรา สายสัมพันธ์กับเหล่าวิญญาณแห่งน้ำของนางแข็งแกร่งเสมอ ภารกิจอันสูงส่งของเราน่าจะโน้มน้าวให้นางกับวิญญาณช่วยได้ เจ้าควรพบนางที่ค่ายเล็ก ๆ ริมน้ำ และ {name} ไม่ต้องสนใจพวกโจรสลัด มันแค่ก่อกวน ไม่เป็นภัยต่อเจ้า" },
        progress = { "138:298753322:206880991", "ข้าสัมผัสว่าเจ้าไม่ใช่เพียงนักเดินทางที่หาทางไป Ratchet มาเถิด นั่งพักที่ค่ายของเรา พร้อมแล้วค่อยมาคุยกับข้า" },
        completion = { "368:1895842980:1377204534", "อา เจ้าต้องการชำระน้ำจากบ่อน้ำจันทรานี้ การหยุดพลังชั่วร้ายใน Felwood ดูสูงส่งพอ แต่ไม่ใช่ข้าจะตัดสินว่าน้ำจะได้รับการชำระหรือไม่ ข้าจะถามวิญญาณแห่งน้ำ ให้พวกเขาตัดสินว่าจุดมุ่งหมายนั้นชอบธรรมหรือไม่ รอสักครู่ ข้าจะบอกคำขอของเจ้า หวังว่าพวกเขาจะเห็นใจภารกิจเช่นเดียวกับข้า" },
        required = { [12907] = { "22:2094992062:662680541", "น้ำจากบ่อจันทร์ที่แปดเปื้อน" } },
        steps = { { "22:2094992062:662680541", "น้ำจากบ่อจันทร์ที่แปดเปื้อน" } },
    },
    [5159] = { -- Cleansed Water Returns to Felwood
        title = { "33:1504585698:1593580538", "น้ำบริสุทธิ์กลับสู่ Felwood" },
        objective = { "63:2143710470:2126860611", "นำ Purified Moon Well Water ไปให้ Greta Mosshoof ใน Felwood" },
        description = { "19:1965978848:1460703650 N 290:1643059903:1308404196 N 60:1793730753:1329786920", "ขอบคุณเหล่าวิญญาณเถิด {name} พวกเขาต่างหากที่มาช่วย ไม่ใช่ข้า ข้ามอบน้ำบริสุทธิ์ให้เจ้าตอนนี้ ฝากความระลึกถึงและความปรารถนาดีไปให้ Greta ด้วย นางกำลังรับมือสิ่งที่ใหญ่กว่าที่พวกเราหลายคนเผชิญ... ซึ่งข้ามั่นใจว่านางจะรู้ในไม่ช้า Shadow Council ไม่ใช่กำลังที่จะดูเบาได้ {name} จงจำไว้ ไปเถอะ นำน้ำกลับไปหา Greta" },
        progress = { "27:1617822979:677886798 N 101:1345604214:915679746", "อา เจ้ากลับมาแล้ว {name} ดี เจ้าพบ Islen ใน Barrens หรือไม่? หรือเราต้องหาวิธีอื่นเพื่อบรรลุเป้าหมาย?" },
        completion = { "345:1115549257:1715385333", "น้ำนี้น่าจะเกินพอสำหรับจุดมุ่งหมายของเรา ข้าดีใจที่ Islen ช่วยได้ นางมีสายสัมพันธ์อันแข็งแกร่งกับวิญญาณแห่งน้ำเสมอ นางยังเปี่ยมปัญญา และน้อยครั้งที่วิญญาณจะไม่เห็นด้วยกับจุดมุ่งหมาย การที่ทั้งนางและเหล่าวิญญาณอวยพรภารกิจ ทำให้ข้าหวังว่าเรามาถูกทาง" },
        required = { [12906] = { "23:1316280379:88449219", "น้ำจากบ่อจันทราที่ชำระแล้ว" } },
        objectiveLabels = {
            item = { ["Purified Moonwell Water"] = "น้ำจากบ่อจันทราที่ชำระแล้ว" },
        },
    },
    [5165] = { -- Dousing the Flames of Protection
        title = { "32:1443252449:1307266875", "ดับเปลวเพลิงแห่งการปกป้อง" },
        objective = { "174:1357990634:2088437878", "ใช้ Purified Moon Well Water ดับเปลวไฟของกระถางไฟแห่งการปกป้องทั้งสี่ภายใน Shadow Hold ใน Felwood แล้วกลับไปหา Greta Mosshoof ที่ Emerald Sanctuary" },
        description = { "415:994514895:1267163929", "ตอนนี้เจ้าต้องกลับไป Jaedenar กระถางไฟน่าจะกระจายอยู่ทั่ว Shadow Hold ดับเปลวไฟของแต่ละกระถาง แล้วเวทป้องกันของสภาจะล่มลงอย่างน้อยชั่วครู่ ข้าจะเฝ้ารอ เมื่อเป็นเช่นนั้น ข้าจะมองลึกเข้าไปในป้อม และพยายามรู้ให้ได้ว่าใครเป็นหัวของอสูรร้ายนี้ เมื่อนั้นเท่านั้น เราจึงจะคิดเรื่องบุกโจมตีโดยตรง" },
        progress = { "352:782187341:1116618385", "ต้องดับกระถางไฟ หากเราจะมีหวังเตรียมพร้อมรับศึกใหญ่กว่าเดิม การเข้าถ้ำมังกรโดยไม่รู้อะไรเป็นเรื่องของคนเขลา และนี่เลวร้ายยิ่งกว่ามังกร Shadow Council ต้องรับผิดชอบอาชญากรรมและความโหดร้ายมากมาย เราต้องทำงานรวดเร็วหากจะหยุดพวกมัน" },
        completion = { "91:492657496:716392275 N 186:1557998651:1731075405", "ทันทีที่เปลวไฟกระถางสุดท้ายดับ ข้าก็มองเห็นเจ้าด้วยเวทได้ ทำได้ดี {name} ข้ารู้อะไรบางอย่างก่อนวอร์ล็อกของ Shadow Council จะร่ายเวทใหม่ หวังว่าจะมากพอ ตอนนี้พักก่อน อีกสักครู่ข้าจะบอกสิ่งที่ได้รู้" },
        steps = { { "30:1966547343:340743059", "ดับไฟในกระถางแห่งความเจ็บปวด" }, { "32:1777367415:126032283", "ดับไฟในกระถางแห่งเจตนาร้าย" }, { "35:929814777:1539843355", "ดับไฟในกระถางแห่งความทุกข์ทรมาน" }, { "32:1071612498:520250076", "ดับไฟในกระถางแห่งความเกลียดชัง" } },
    },
    [5202] = { -- A Strange Red Key
        title = { "17:200497325:607946226", "กุญแจสีแดงประหลาด" },
        objective = { "71:864778458:1956999203", "สำรวจ Jaedenar เพื่อค้นหาว่า Blood Red Key ใช้ทำอะไร" },
        description = { "251:1256824114:1889549836", "กุญแจสีแดงเล็ก ๆ ดูเหมือนทำจากวัสดุกระดูกบางชนิด มันหนักในมือ แต่ดูเปราะบางมาก ทำไมสมาชิก Shadow Council จึงมีของเช่นนี้? บางทีอาจมีบางอย่างใน Jaedenar ที่กุญแจประหลาดนี้ไขได้" },
        progress = { "147:768249724:1676583069", "ข้าเริ่มสงสัยว่าจะได้หนีจากกรงนี้หรือไม่ คงอีกไม่นานพวกมันจะสังเวยข้าให้ปีศาจที่บูชา พวกสัตว์นรก!" },
        completion = { "73:814316701:1228172088", "กุญแจ เจ้าพบแล้ว! ได้โปรด ส่งให้ข้า แล้วในที่สุดข้าจะหนีได้!" },
        required = { [13140] = { "13:1989031183:1236685411", "กุญแจสีแดงเลือด" } },
        steps = { { "13:1989031183:1236685411", "กุญแจสีแดงเลือด" } },
    },
    [5203] = { -- Rescue From Jaedenar
        title = { "20:1391982243:857251365", "ช่วยเชลยจาก Jaedenar" },
        objective = { "214:866882240:368514206", "คุ้มกัน Arko'narin ไปยังที่เก็บดาบ Lightforge และอุปกรณ์ของนาง แล้วปกป้องนางขณะหนี Shadow Hold หลังจากนั้นตามหา Jessir Moonbow ใน Felwood เพื่อเล่าเรื่องที่เกิดกับสหายของนาง" },
        description = { "196:647029689:1502601968 N 277:1110515477:447281382 N 24:650552951:656027485", "แต่แม้จะเจ็บปวดเพียงใด มีสิ่งหนึ่งที่ต้องทำก่อน ข้าต้องหาดาบ Lightforge ของ Trey แล้วหนี Shadow Hold เพื่อบอกผู้บังคับบัญชาว่าเกิดอะไรขึ้น เจ้าช่วยได้ไหม {name}? อุปกรณ์ของเราอยู่ไม่ไกล และเจ้าพิสูจน์แล้วว่ารอดตามทางขึ้นไปได้ หลังหนี ข้าจะมุ่ง Darnassus หากเจ้าตามหา Jessir สหายของข้าใกล้เขต Ashenvale ได้ นางควรมาพบเราที่ค่าย Emerald Circle ใกล้ ๆ ว่าอย่างไร {name}? จะช่วยข้าอีกครั้งได้ไหม?" },
        progress = { "17:486624236:368725629 N 43:455954913:1327767484", "เจ้าดูหอบนะ {name} เป็นอะไรหรือเปล่า หรือมีเรื่องผิดปกติ?" },
        completion = { "474:117668206:1304306076", "เจ้าคือคนที่ช่วย Arko หนีหรือ? ข้าดีใจมากที่เจ้าพบข้า นางเพิ่งผ่านไปไม่นานระหว่างเดินทางสู่ Darnassus นางนำ Lightforge ไปด้วย และไม่ยอมเสียเวลาคุยกับดรูอิดเพื่อรักษาตัว บอกว่าเรื่องเร่งด่วนเกินไป แต่นางเล่าเรื่องที่เจ้าพบวิญญาณ Trey ให้ข้าฟัง ช่างเป็นชะตากรรมโหดร้ายสำหรับอัศวินแห่ง Silver Hand นางไม่แสดงออก แต่ข้ารู้ว่าความคิดที่ต้องเสียสหายคนสนิทไปกำลังฉีกหัวใจนางอยู่" },
        objectiveLabels = {
            event = { ["Protect Arko'narin out of Shadow Hold"] = "คุ้มกัน Arko'narin ออกจาก Shadow Hold" },
        },
    },
    [5204] = { -- Retribution of the Light
        title = { "24:2085341642:940732189", "การลงทัณฑ์แห่งแสงสว่าง" },
        objective = { "95:889341919:159867387", "กลับไป Jaedenar สังหารซัคคิวบัส Rakaiah ก่อนตามหา Remains of Trey Lightforge" },
        description = { "332:650684294:1780094533 N 172:985250410:1000448180", "นางอยากทำเหมือนไม่เป็นอะไร อยากให้ข้าคิดว่าเข้มแข็งพอจะรับทุกอย่างด้วยตนเอง แต่ข้ารู้ความจริง การตายของ Trey และเรื่องทรมานที่เขาเผชิญจะตามหลอกหลอนนางอีกนาน เราหยุดเรื่องนั้นไม่ได้ แต่ทำให้นางสงบใจได้บ้าง! {name} กลับไป Shadow Hold ฆ่าผู้ทรมาน Trey แล้วหาร่างที่เหลือของเขา ไม่มีเหตุผลที่เราจะสะสางเรื่องค้างคาเหล่านี้ไม่ได้ ขณะที่ Arko'narin ไว้อาลัยเป็นการส่วนตัว" },
        progress = { "454:1765393959:451286752", "เจ้าตรวจดูร่าง และไม่สงสัยเลยว่านี่คือร่างที่เหลือของอัศวินแห่ง Silver Hand นาม Trey Lightforge ชั่วครู่หนึ่ง เจ้านึกถึง Arko'narin และถามตนเองว่ามีใครในชีวิตสำคัญเท่าที่ชายคนนี้สำคัญต่อเชลยไนต์เอลฟ์ซึ่งเจ้าเพิ่งช่วยหนี Shadow Hold หรือไม่ หลังรวบรวมความคิดอีกครู่ เจ้ารู้ว่าไม่อาจนำร่างพาลาดินกลับไปให้ Jessir โดยไม่ฆ่าผู้ทรมานเขาเสียก่อน" },
        completion = { "175:1607575748:700741643", "เจ้ารวบรวมร่างที่เหลือของพาลาดินอย่างระมัดระวังที่สุด พลางนึกว่าอย่างน้อยวิญญาณของเขาก็ได้รับอิสระจากความเจ็บปวดหรือทุกข์ทรมานที่อาจถูกบังคับให้เผชิญแล้ว" },
        objectiveLabels = {
            monster = { ["Rakaiah slain"] = "ปราบ Rakaiah" },
        },
    },
    [5242] = { -- A Final Blow
        title = { "12:1464330924:1570894713", "ปิดฉากศัตรู" },
        objective = { "88:1227634100:862756185", "กำจัด Moora และ Salia แล้วนำ Shadow Lord Fel'dan's Head ไปให้ Greta Mosshoof ใน Felwood" },
        description = { "509:1217973684:2140445626", "น่าเสียดาย ข้าเห็นเพียงวิธีเดียวที่จะหยุดภัยต่อ Felwood คือบุกตรงเข้าไป ไม่มีทางอื่นเข้าสู่ Shadow Hold และข้าไม่มีวิธีส่งเจ้าเข้าไปด้วยเวท เส้นทางตรงลงสู่ก้นป้อมคือทางเดียว... และข้ารู้แล้วว่าควรตามหาใคร เขาชื่อ Fel'dan... Shadow Lord Fel'dan เขาคือผู้เป็นมรรตัยที่กุมอำนาจเบื้องล่าง เป็นหัวของอสรพิษ จงฆ่าเขาและซัคคิวบัสรับใช้สองตน แล้วกลับมาหาข้า Fel'dan คือผู้ทำพันธสัญญากับ Legion เขาต้องถูกหยุด" },
        progress = { "239:1534118289:2034308266", "เมื่อไม่มี Fel'dan หวังว่า Shadow Council จะเสียจุดมุ่งหมายแล้วเริ่มสู้กันเอง พวกมันจะแย่งอำนาจและกักทรัพยากรเพื่อแผนในอนาคต นั่นจะเป็นโอกาสเหมาะที่จะทำลายพวกมันกับทาสปีศาจให้ย่อยยับ" },
        completion = { "24:1291056162:1561117996 N 206:431116988:189192884", "สรรเสริญพระแม่ธรณี {name}! ขอบคุณ! วันนี้ยิ่งใหญ่จริง ๆ! การโจมตีลำดับผู้นำครั้งนี้ทำให้ Shadow Council ยากจะกลับไปมีอำนาจระดับเดิม เจ้าทำสิ่งยิ่งใหญ่ในวันนี้!" },
        required = { [13207] = { "26:492924314:853394541", "ศีรษะของเจ้าแห่งเงา Fel'dan" } },
        steps = { { "26:492924314:853394541", "ศีรษะของเจ้าแห่งเงา Fel'dan" } },
        objectiveLabels = {
            monster = { ["Moora slain"] = "ปราบ Moora", ["Salia slain"] = "ปราบ Salia" },
        },
    },
    [5249] = { -- To Winterspring!
        title = { "16:1483003059:1786431925", "สู่ Winterspring!" },
        objective = { "70:1229905141:2066135806", "ตามหา Starfall Village ใน Winterspring แล้วคุยกับ Wynd Nightchaser" },
        description = { "410:1211298648:903188123", "ใน Winterspring ทางเหนือของที่นี่ มีซากเมืองเอลฟ์โบราณมากมาย ดินแดนนั้นโหดร้าย แต่มีความลับและสถานที่ให้สำรวจมาก งานทั้งหมดใน Felwood ทำให้ข้ายังไม่มีโอกาสเดินทางไป แต่ไม่มีเหตุผลที่เจ้าจะไม่ไป! เมื่อไปถึง ตามหา Wynd Nightchaser เขาใช้เวลาส่วนใหญ่อยู่ที่ Starfall Village และรู้เรื่องบริเวณนั้นมาก" },
        completion = { "46:2123000372:233776574 N 1:46:46", "สหายของ Ivy Leafrunner หรือ? ยินดีที่ได้รู้จัก {name}" },
    },
    [5385] = { -- The Remains of Trey Lightforge
        title = { "30:1035499242:1929471948", "ร่างที่เหลือของ Trey Lightforge" },
        objective = { "67:100362666:820005455", "นำ Remains of Trey Lightforge กลับไปให้ Jessir Moonbow ใน Felwood" },
        description = { "228:656194505:2095122378", "เจ้าค่อย ๆ ยกถุงแล้วเตรียมกลับไปหา Jessir Moonbow ที่เขตแดน Felwood กับ Ashenvale หวังว่าพาลาดินจะได้รับการแสดงความเคารพอย่างเหมาะสม เมื่อส่งร่างที่เหลือให้เหล่าสหายแล้ว" },
        progress = { "31:767830397:975198887 N 1:63:63", "เรื่องที่ Jaedenar เป็นอย่างไรบ้าง {name}?" },
        completion = { "69:403939675:561772089 N 262:1831011794:1736239860", "เจ้าทำสำเร็จ! สรรเสริญ Elune และพลังใดก็ตามที่เจ้าบูชา {name} วันนี้เจ้าทำสิ่งสูงส่งและเปี่ยมเกียรติ ข้ามั่นใจว่า Arko'narin จะยินดีที่เจ้าไม่เพียงช่วยนาง แต่ยังสังหารสิ่งมีชีวิตที่ทรมานหนึ่งในสหายที่ดีที่สุดด้วย ข้าอยากทำเพื่อตอบแทนมากกว่านี้ แต่โปรดรับนี่ไว้" },
    },
    [5882] = { -- Salve via Hunting
        title = { "17:1521375278:2092582707", "ยาทาจากการล่า" },
        progress = { "385:1539532824:1397921024", "การมี Cenarion Beacon ทำให้มองเห็น Corrupted Soul Shard บนสัตว์แปดเปื้อนที่ถูกกำจัดเพื่อประโยชน์ส่วนรวม ข้าบดเศษเหล่านี้เป็นวัตถุดิบสำหรับทำยาทาพืช Cenarion เราจะใช้ยาเปลี่ยนพืชเสื่อมทรามให้กลับแข็งแรง หากเจ้านำเศษเหล่านี้มาแลก ข้าจะให้ยาทาพืช Cenarion ที่เตรียมไว้แล้ว" },
        completion = { "89:1314801438:1651187321 N 67:1503815693:883581745", "ดีมาก นี่คือยาทาพืช Cenarion ของเจ้า จงค้นหาพืชเสื่อมทรามทั่ว Felwood {name}! พบที่ใดก็ใช้ยาที่ข้าให้ชำระล้างพวกมัน" },
        description = { "385:1539532824:1397921024", "การมี Cenarion Beacon ทำให้มองเห็น Corrupted Soul Shard บนสัตว์แปดเปื้อนที่ถูกกำจัดเพื่อประโยชน์ส่วนรวม ข้าบดเศษเหล่านี้เป็นวัตถุดิบสำหรับทำยาทาพืช Cenarion เราจะใช้ยาเปลี่ยนพืชเสื่อมทรามให้กลับแข็งแรง หากเจ้านำเศษเหล่านี้มาแลก ข้าจะให้ยาทาพืช Cenarion ที่เตรียมไว้แล้ว" },
        required = { [11515] = { "20:1071122349:465958943", "เศษวิญญาณแปดเปื้อน" } },
        objectiveLabels = {
            item = { ["Corrupted Soul Shard"] = "เศษวิญญาณแปดเปื้อน" },
        },
    },
    [5883] = { -- Salve via Mining
        title = { "16:1165359430:318710617", "ยาทาจากการขุดแร่" },
        progress = { "423:1755659678:1357236024", "หากเจ้ามี Cenarion Beacon ขณะขุดแร่ใน Felwood ก็จะมองเห็น Tainted Vitriol ที่ปนเปื้อนสายแร่ ข้ารู้วิธีชำระล้างมันให้เป็นวัตถุดิบทำยาทาพืช Cenarion แล้วเจ้าจะใช้ยากับพืชตามป่าที่ต้องการความช่วยเหลือ หากเก็บ Tainted Vitriol มาได้ ข้าจะมอบยาทาพืช Cenarion ที่เตรียมไว้ให้" },
        completion = { "198:1833067123:1123774900", "ดีมาก นี่คือยาทาพืช Cenarion หากพบ Vitriol เพิ่มขณะขุดแร่ใน Felwood ก็จำไว้ว่าให้เก็บมาให้ข้า! เจ้ายิ่งพบมาก ข้าก็ยิ่งทำยาได้มาก" },
        description = { "423:1755659678:1357236024", "หากเจ้ามี Cenarion Beacon ขณะขุดแร่ใน Felwood ก็จะมองเห็น Tainted Vitriol ที่ปนเปื้อนสายแร่ ข้ารู้วิธีชำระล้างมันให้เป็นวัตถุดิบทำยาทาพืช Cenarion แล้วเจ้าจะใช้ยากับพืชตามป่าที่ต้องการความช่วยเหลือ หากเก็บ Tainted Vitriol มาได้ ข้าจะมอบยาทาพืช Cenarion ที่เตรียมไว้ให้" },
        required = { [11513] = { "15:1159872086:957350447", "ไวทริออลปนเปื้อน" } },
        objectiveLabels = {
            item = { ["Tainted Vitriol"] = "ไวทริออลปนเปื้อน" },
        },
    },
    [5884] = { -- Salve via Gathering
        title = { "19:1415421911:768227474", "ยาทาจากการเก็บสมุนไพร" },
        progress = { "453:213335821:142151917", "Cenarion Beacon ทำให้นักเก็บสมุนไพรที่มีประสบการณ์มองเห็น Fel Creep อันร้ายกาจ ผลพวงชั่วร้ายของความเสื่อมทรามใน Felwood งานที่นี่สอนให้ข้ารู้วิธีชำระ Fel Creep เป็นวัตถุดิบล้างมลทิน... ซึ่งใช้ทำสิ่งที่เราเรียกว่ายาทาพืช Cenarion ตราบใดที่มี Beacon เจ้าควรพบ Fel Creep ขณะเก็บสมุนไพรใน Felwood หากนำมาให้ ข้าจะให้ยาทาพืช Cenarion ที่ทำเสร็จแล้วเป็นการแลกเปลี่ยน" },
        completion = { "15:164794247:1541488341 N 205:1440391206:2001718507 R 1:33:33", "ทำได้ดี {name} ทุกส่วนที่ชำระแล้วจะช่วยเราทวง Felwood คืน นี่ รับยาทาพืช Cenarion ไปแล้วมุ่งเข้าป่า การทวงแผ่นดินจากความเสื่อมทรามไม่รอ {race} คนใด!" },
        description = { "453:213335821:142151917", "Cenarion Beacon ทำให้นักเก็บสมุนไพรที่มีประสบการณ์มองเห็น Fel Creep อันร้ายกาจ ผลพวงชั่วร้ายของความเสื่อมทรามใน Felwood งานที่นี่สอนให้ข้ารู้วิธีชำระ Fel Creep เป็นวัตถุดิบล้างมลทิน... ซึ่งใช้ทำสิ่งที่เราเรียกว่ายาทาพืช Cenarion ตราบใดที่มี Beacon เจ้าควรพบ Fel Creep ขณะเก็บสมุนไพรใน Felwood หากนำมาให้ ข้าจะให้ยาทาพืช Cenarion ที่ทำเสร็จแล้วเป็นการแลกเปลี่ยน" },
        required = { [11514] = { "9:666927853:1852412457", "เฟลครีป" } },
        objectiveLabels = {
            item = { ["Fel Creep"] = "เฟลครีป" },
        },
    },
    [5885] = { -- Salve via Skinning
        title = { "18:328384737:390754916", "ยาทาจากการถลกหนัง" },
        progress = { "436:1574232873:656416797", "Cenarion Beacon ช่วยให้ผู้ถลกหนังที่ชำนาญมองเห็น Patch of Tainted Skin จากสัตว์ที่ล่าใน Felwood ข้าเปลี่ยนเศษหนังแปดเปื้อนที่ดูไร้ประโยชน์เหล่านี้เป็นเนื้อยาข้น ใช้เป็นตัวเร่งสำหรับยาทาพืช Cenarion เวลาถลกหนังสัตว์ที่เจ้าสังหารที่นี่ อย่าลืมมี Beacon ติดตัว! เมื่อเก็บชิ้นหนังแปดเปื้อนได้ นำมาให้ข้า แล้วข้าจะมอบยาทาพืช Cenarion ที่ทำไว้แล้วให้" },
        completion = { "132:2027665186:364307009 N 1:33:33", "นี่คือสิ่งที่ข้าต้องการพอดี รับยาทาพืชเหล่านี้ไป แล้วใช้ทวง Felwood คืนจากความเสื่อมทราม เราต้องไม่ย่อท้อ {name}!" },
        description = { "436:1574232873:656416797", "Cenarion Beacon ช่วยให้ผู้ถลกหนังที่ชำนาญมองเห็น Patch of Tainted Skin จากสัตว์ที่ล่าใน Felwood ข้าเปลี่ยนเศษหนังแปดเปื้อนที่ดูไร้ประโยชน์เหล่านี้เป็นเนื้อยาข้น ใช้เป็นตัวเร่งสำหรับยาทาพืช Cenarion เวลาถลกหนังสัตว์ที่เจ้าสังหารที่นี่ อย่าลืมมี Beacon ติดตัว! เมื่อเก็บชิ้นหนังแปดเปื้อนได้ นำมาให้ข้า แล้วข้าจะมอบยาทาพืช Cenarion ที่ทำไว้แล้วให้" },
        required = { [11512] = { "21:1803362651:867294880", "เศษหนังแปดเปื้อน" } },
        objectiveLabels = {
            item = { ["Patch of Tainted Skin"] = "เศษหนังแปดเปื้อน" },
        },
    },
    [5886] = { -- Salve via Disenchanting
        title = { "23:1690998074:1717195322", "ยาทาจากการสลายมนตร์" },
        progress = { "479:2014698740:989243902", "พลังของไอเทมเวทมนตร์ที่ถูกสลายยังสัมผัสได้จากแก่นพลังที่มันสร้าง ข้าคิดวิธีเปลี่ยนแก่นพลังดิบที่นักเสริมมนตร์ใช้ ให้เป็นวัตถุดิบสำหรับยาทาพืช Cenarion ได้ วิธีนี้ไม่ต้องมี Cenarion Beacon ไอเทมใดที่สลายแล้วได้ Lesser Nether Essence ก็ใช้ได้ ข้าต้องการเพียงหนึ่งชิ้น แลกกับยาทาพืช Cenarion แก่นพลังนี้ทรงอานุภาพมาก ใช้เพียงนิดก็ให้ผลมากทีเดียว!" },
        completion = { "86:311525522:1669327732 N 145:795620262:475416705", "นี่คือยาทาพืช Cenarion ข้าต้องการ Lesser Nether Essence เพียงหนึ่งชิ้นสำหรับงานนี้ {name} แก่นพลังเป็นของทรงอานุภาพที่สุดที่ข้าใช้เปลี่ยนเครื่องมือทำลายล้างให้หล่อเลี้ยงชีวิตได้ หากจะเปรียบเช่นนั้น หากต้องการยาเพิ่ม ก็มาหาข้าที่นี่!" },
        description = { "479:2014698740:989243902", "พลังของไอเทมเวทมนตร์ที่ถูกสลายยังสัมผัสได้จากแก่นพลังที่มันสร้าง ข้าคิดวิธีเปลี่ยนแก่นพลังดิบที่นักเสริมมนตร์ใช้ ให้เป็นวัตถุดิบสำหรับยาทาพืช Cenarion ได้ วิธีนี้ไม่ต้องมี Cenarion Beacon ไอเทมใดที่สลายแล้วได้ Lesser Nether Essence ก็ใช้ได้ ข้าต้องการเพียงหนึ่งชิ้น แลกกับยาทาพืช Cenarion แก่นพลังนี้ทรงอานุภาพมาก ใช้เพียงนิดก็ให้ผลมากทีเดียว!" },
        required = { [11174] = { "21:65819799:666435846", "แก่นเนเธอร์ระดับต่ำ" } },
        objectiveLabels = {
            item = { ["Lesser Nether Essence"] = "แก่นเนเธอร์ระดับต่ำ" },
        },
    },
    [5887] = { -- Salve via Hunting
        title = { "17:1521375278:2092582707", "ยาทาจากการล่า" },
        progress = { "385:1539532824:1397921024", "การมี Cenarion Beacon ทำให้มองเห็น Corrupted Soul Shard บนสัตว์แปดเปื้อนที่ถูกกำจัดเพื่อประโยชน์ส่วนรวม ข้าบดเศษเหล่านี้เป็นวัตถุดิบสำหรับทำยาทาพืช Cenarion เราจะใช้ยาเปลี่ยนพืชเสื่อมทรามให้กลับแข็งแรง หากเจ้านำเศษเหล่านี้มาแลก ข้าจะให้ยาทาพืช Cenarion ที่เตรียมไว้แล้ว" },
        completion = { "89:1314801438:1651187321 N 67:1503815693:883581745", "ดีมาก นี่คือยาทาพืช Cenarion ของเจ้า จงค้นหาพืชเสื่อมทรามทั่ว Felwood {name}! พบที่ใดก็ใช้ยาที่ข้าให้ชำระล้างพวกมัน" },
        description = { "385:1539532824:1397921024", "การมี Cenarion Beacon ทำให้มองเห็น Corrupted Soul Shard บนสัตว์แปดเปื้อนที่ถูกกำจัดเพื่อประโยชน์ส่วนรวม ข้าบดเศษเหล่านี้เป็นวัตถุดิบสำหรับทำยาทาพืช Cenarion เราจะใช้ยาเปลี่ยนพืชเสื่อมทรามให้กลับแข็งแรง หากเจ้านำเศษเหล่านี้มาแลก ข้าจะให้ยาทาพืช Cenarion ที่เตรียมไว้แล้ว" },
        required = { [11515] = { "20:1071122349:465958943", "เศษวิญญาณแปดเปื้อน" } },
        objectiveLabels = {
            item = { ["Corrupted Soul Shard"] = "เศษวิญญาณแปดเปื้อน" },
        },
    },
    [5888] = { -- Salve via Mining
        title = { "16:1165359430:318710617", "ยาทาจากการขุดแร่" },
        progress = { "423:1755659678:1357236024", "หากเจ้ามี Cenarion Beacon ขณะขุดแร่ใน Felwood ก็จะมองเห็น Tainted Vitriol ที่ปนเปื้อนสายแร่ ข้ารู้วิธีชำระล้างมันให้เป็นวัตถุดิบทำยาทาพืช Cenarion แล้วเจ้าจะใช้ยากับพืชตามป่าที่ต้องการความช่วยเหลือ หากเก็บ Tainted Vitriol มาได้ ข้าจะมอบยาทาพืช Cenarion ที่เตรียมไว้ให้" },
        completion = { "198:1833067123:1123774900", "ดีมาก นี่คือยาทาพืช Cenarion หากพบ Vitriol เพิ่มขณะขุดแร่ใน Felwood ก็จำไว้ว่าให้เก็บมาให้ข้า! เจ้ายิ่งพบมาก ข้าก็ยิ่งทำยาได้มาก" },
        description = { "423:1755659678:1357236024", "หากเจ้ามี Cenarion Beacon ขณะขุดแร่ใน Felwood ก็จะมองเห็น Tainted Vitriol ที่ปนเปื้อนสายแร่ ข้ารู้วิธีชำระล้างมันให้เป็นวัตถุดิบทำยาทาพืช Cenarion แล้วเจ้าจะใช้ยากับพืชตามป่าที่ต้องการความช่วยเหลือ หากเก็บ Tainted Vitriol มาได้ ข้าจะมอบยาทาพืช Cenarion ที่เตรียมไว้ให้" },
        required = { [11513] = { "15:1159872086:957350447", "ไวทริออลปนเปื้อน" } },
        objectiveLabels = {
            item = { ["Tainted Vitriol"] = "ไวทริออลปนเปื้อน" },
        },
    },
    [5889] = { -- Salve via Gathering
        title = { "19:1415421911:768227474", "ยาทาจากการเก็บสมุนไพร" },
        progress = { "453:213335821:142151917", "Cenarion Beacon ทำให้นักเก็บสมุนไพรที่มีประสบการณ์มองเห็น Fel Creep อันร้ายกาจ ผลพวงชั่วร้ายของความเสื่อมทรามใน Felwood งานที่นี่สอนให้ข้ารู้วิธีชำระ Fel Creep เป็นวัตถุดิบล้างมลทิน... ซึ่งใช้ทำสิ่งที่เราเรียกว่ายาทาพืช Cenarion ตราบใดที่มี Beacon เจ้าควรพบ Fel Creep ขณะเก็บสมุนไพรใน Felwood หากนำมาให้ ข้าจะให้ยาทาพืช Cenarion ที่ทำเสร็จแล้วเป็นการแลกเปลี่ยน" },
        completion = { "15:164794247:1541488341 N 205:1440391206:2001718507 R 1:33:33", "ทำได้ดี {name} ทุกส่วนที่ชำระแล้วจะช่วยเราทวง Felwood คืน นี่ รับยาทาพืช Cenarion ไปแล้วมุ่งเข้าป่า การทวงแผ่นดินจากความเสื่อมทรามไม่รอ {race} คนใด!" },
        description = { "453:213335821:142151917", "Cenarion Beacon ทำให้นักเก็บสมุนไพรที่มีประสบการณ์มองเห็น Fel Creep อันร้ายกาจ ผลพวงชั่วร้ายของความเสื่อมทรามใน Felwood งานที่นี่สอนให้ข้ารู้วิธีชำระ Fel Creep เป็นวัตถุดิบล้างมลทิน... ซึ่งใช้ทำสิ่งที่เราเรียกว่ายาทาพืช Cenarion ตราบใดที่มี Beacon เจ้าควรพบ Fel Creep ขณะเก็บสมุนไพรใน Felwood หากนำมาให้ ข้าจะให้ยาทาพืช Cenarion ที่ทำเสร็จแล้วเป็นการแลกเปลี่ยน" },
        required = { [11514] = { "9:666927853:1852412457", "เฟลครีป" } },
        objectiveLabels = {
            item = { ["Fel Creep"] = "เฟลครีป" },
        },
    },
    [5890] = { -- Salve via Skinning
        title = { "18:328384737:390754916", "ยาทาจากการถลกหนัง" },
        progress = { "436:1574232873:656416797", "Cenarion Beacon ช่วยให้ผู้ถลกหนังที่ชำนาญมองเห็น Patch of Tainted Skin จากสัตว์ที่ล่าใน Felwood ข้าเปลี่ยนเศษหนังแปดเปื้อนที่ดูไร้ประโยชน์เหล่านี้เป็นเนื้อยาข้น ใช้เป็นตัวเร่งสำหรับยาทาพืช Cenarion เวลาถลกหนังสัตว์ที่เจ้าสังหารที่นี่ อย่าลืมมี Beacon ติดตัว! เมื่อเก็บชิ้นหนังแปดเปื้อนได้ นำมาให้ข้า แล้วข้าจะมอบยาทาพืช Cenarion ที่ทำไว้แล้วให้" },
        completion = { "132:2027665186:364307009 N 1:33:33", "นี่คือสิ่งที่ข้าต้องการพอดี รับยาทาพืชเหล่านี้ไป แล้วใช้ทวง Felwood คืนจากความเสื่อมทราม เราต้องไม่ย่อท้อ {name}!" },
        description = { "436:1574232873:656416797", "Cenarion Beacon ช่วยให้ผู้ถลกหนังที่ชำนาญมองเห็น Patch of Tainted Skin จากสัตว์ที่ล่าใน Felwood ข้าเปลี่ยนเศษหนังแปดเปื้อนที่ดูไร้ประโยชน์เหล่านี้เป็นเนื้อยาข้น ใช้เป็นตัวเร่งสำหรับยาทาพืช Cenarion เวลาถลกหนังสัตว์ที่เจ้าสังหารที่นี่ อย่าลืมมี Beacon ติดตัว! เมื่อเก็บชิ้นหนังแปดเปื้อนได้ นำมาให้ข้า แล้วข้าจะมอบยาทาพืช Cenarion ที่ทำไว้แล้วให้" },
        required = { [11512] = { "21:1803362651:867294880", "เศษหนังแปดเปื้อน" } },
        objectiveLabels = {
            item = { ["Patch of Tainted Skin"] = "เศษหนังแปดเปื้อน" },
        },
    },
    [5891] = { -- Salve via Disenchanting
        title = { "23:1690998074:1717195322", "ยาทาจากการสลายมนตร์" },
        progress = { "479:2014698740:989243902", "พลังของไอเทมเวทมนตร์ที่ถูกสลายยังสัมผัสได้จากแก่นพลังที่มันสร้าง ข้าคิดวิธีเปลี่ยนแก่นพลังดิบที่นักเสริมมนตร์ใช้ ให้เป็นวัตถุดิบสำหรับยาทาพืช Cenarion ได้ วิธีนี้ไม่ต้องมี Cenarion Beacon ไอเทมใดที่สลายแล้วได้ Lesser Nether Essence ก็ใช้ได้ ข้าต้องการเพียงหนึ่งชิ้น แลกกับยาทาพืช Cenarion แก่นพลังนี้ทรงอานุภาพมาก ใช้เพียงนิดก็ให้ผลมากทีเดียว!" },
        completion = { "86:311525522:1669327732 N 145:795620262:475416705", "นี่คือยาทาพืช Cenarion ข้าต้องการ Lesser Nether Essence เพียงหนึ่งชิ้นสำหรับงานนี้ {name} แก่นพลังเป็นของทรงอานุภาพที่สุดที่ข้าใช้เปลี่ยนเครื่องมือทำลายล้างให้หล่อเลี้ยงชีวิตได้ หากจะเปรียบเช่นนั้น หากต้องการยาเพิ่ม ก็มาหาข้าที่นี่!" },
        description = { "479:2014698740:989243902", "พลังของไอเทมเวทมนตร์ที่ถูกสลายยังสัมผัสได้จากแก่นพลังที่มันสร้าง ข้าคิดวิธีเปลี่ยนแก่นพลังดิบที่นักเสริมมนตร์ใช้ ให้เป็นวัตถุดิบสำหรับยาทาพืช Cenarion ได้ วิธีนี้ไม่ต้องมี Cenarion Beacon ไอเทมใดที่สลายแล้วได้ Lesser Nether Essence ก็ใช้ได้ ข้าต้องการเพียงหนึ่งชิ้น แลกกับยาทาพืช Cenarion แก่นพลังนี้ทรงอานุภาพมาก ใช้เพียงนิดก็ให้ผลมากทีเดียว!" },
        required = { [11174] = { "21:65819799:666435846", "แก่นเนเธอร์ระดับต่ำ" } },
        objectiveLabels = {
            item = { ["Lesser Nether Essence"] = "แก่นเนเธอร์ระดับต่ำ" },
        },
    },
    [6162] = { -- A Husband's Last Battle
        title = { "23:451477652:623280967", "ศึกสุดท้ายของสามี" },
        objective = { "81:861091800:874955969", "สังหาร Overlord Ror แล้วนำกรงเล็บของมันกลับไปให้ Dreka'Sur ที่ Bloodvenom Post ใน Felwood" },
        description = { "353:1222772672:532785663 N 111:1019583528:1014439824", "สามีของข้าเดินทางใน Felwood เพื่อเกียรติของเผ่า ต่อสู้กับ Shadow Council และสิ่งชั่วร้ายเสื่อมทรามอื่น! หลังรอดตายหลายครั้ง ข้าได้รับจดหมายว่า ดรูอิดคนหนึ่งขอให้เขาช่วยปราบเฟอร์โบลกแปดเปื้อนทรงพลังชื่อ Overlord Ror แล้วก็ไม่ได้ข่าวจากทั้งคู่อีกเลย ข้าต้องการมือที่มีกรงเล็บของ Ror {name} ข้าอยากให้มันชดใช้ที่ทำให้ข้าเป็นม่าย! ข้าเชื่อว่าสัตว์ร้ายอยู่ทางใต้... ใกล้เขต Ashenvale" },
        progress = { "34:1541277549:325570053 N 180:1348832556:1294876079", "เจ้าได้กรงเล็บสัตว์ร้ายนั่นแล้วหรือยัง {name}? มันจะต้องชดใช้อาชญากรรม ข้าไม่สนว่ามันเสื่อมทรามหรือแค่โกรธที่อยู่ในป่าหม่นหมอง เฟอร์โบลกที่ทำร้ายครอบครัวข้าเช่นนี้ไม่มีวันอยู่ได้นาน!" },
        completion = { "258:1302921597:1722036346 N 1:46:46", "เจ้าทำตามคำพูดและนำเกียรติมาให้ข้า สามีของข้าตายในสนามรบ เขาคงภูมิใจในเรื่องนั้น แต่ข้าจะสงบใจไม่ได้ จนรู้ว่าสัตว์ร้ายที่บังคับให้ต้องใช้ชีวิตลำพังได้ชดใช้แล้ว ขอบคุณอีกครั้ง {name}" },
        required = { [15879] = { "19:454575745:1476497943", "กรงเล็บของจอมทัพรอร์" } },
        objectiveLabels = {
            item = { ["Overlord Ror's Claw"] = "กรงเล็บของจอมทัพรอร์" },
        },
    },
    [8460] = { -- Timbermaw Ally
        title = { "14:282996485:1724574680", "พันธมิตรของ Timbermaw" },
        objective = { "196:1723519564:891807261", "Grazle ต้องการให้เจ้าพิสูจน์ตนด้วยการกำจัด Deadwood Warrior 6 ตัว, Deadwood Pathfinder 6 ตัว และ Deadwood Gardener 6 ตัว เสร็จแล้วกลับไปหาเขาทางใต้ของ Felwood ใกล้ Emerald Sanctuary" },
        description = { "446:864666753:1605451229", "Timbermaw เป็นเฟอร์โบลกเผ่าเดียวที่รอดจากความเสื่อมทราม แต่ตอนนี้ชนเผ่าพันธุ์อื่นมากมายฆ่าเฟอร์โบลกอย่างไม่แยกแยะ โดยไม่ดูว่าเป็นมิตรหรือศัตรู เพราะเหตุนี้ พวกเราจึงไว้ใจคนน้อยมาก เจ้าสนใจพิสูจน์ตนหรือไม่? ขับไล่เผ่า Deadwood เสื่อมทรามแห่ง Felwood แล้วสักวันเราอาจนับเจ้าเป็นพันธมิตร เจ้าจะพบ Deadwood กลุ่มแรก ทั้งนักรบ ผู้เบิกทาง และคนสวน ทางตะวันตกของข้า" },
        progress = { "12:111291805:1796178249 N 70:935808714:1489239883", "ทำต่อไป {name} หากจะได้ความไว้ใจ เจ้าต้องพิสูจน์ตนต่อเรา" },
        completion = { "180:2101676826:809602138", "เราทุกข์ทรมานมากจากเหตุการณ์ในอดีต ขอบคุณที่ช่วยปกป้อง Timbermaw โปรดรับของเล็กน้อยนี้เป็นเครื่องหมายของมิตรภาพที่กำลังเติบโต" },
        objectiveLabels = {
            monster = { ["Deadwood Warrior slain"] = "ปราบ นักรบ Deadwood", ["Deadwood Pathfinder slain"] = "ปราบ นักเบิกทาง Deadwood", ["Deadwood Gardener slain"] = "ปราบ คนสวน Deadwood" },
        },
    },
    [8462] = { -- Speak to Nafien
        title = { "15:1646027860:735003897", "คุยกับ Nafien" },
        objective = { "140:1124492676:732313755", "เดินทางขึ้นเหนือไปตามถนนหลักใน Felwood แล้วคุยกับเฟอร์โบลกชื่อ Nafien ผู้เฝ้าทางเข้า Timbermaw Hold" },
        description = { "387:266931954:225409434", "บางทีเจ้าอาจรับมือภัยที่ใหญ่กว่าซึ่งพวกเรา Timbermaw เผชิญ เจ้าแสดงฝีมือที่นี่แล้ว... เฟอร์โบลกอีกตนเฝ้าทางเข้า Timbermaw Hold อยู่ตามถนนนี้ไกลขึ้นไปทางเหนือ เขาชื่อ Nafien แม้ดูเป็นสัตว์ป่าดุร้ายไม่น่าคบ ก็อย่ากลัว เขาเพียงต้องการความช่วยเหลือต่อสู้กับพลังชั่วร้ายที่คุกคามบ้านเรา" },
        completion = { "457:1176879929:146864749", "อา... ข้าได้ยินข่าวตามสายลมเรื่องคนนอกเผ่าที่ต้องการเป็นพันธมิตรกับเฟอร์โบลก Timbermaw ข้าต้อนรับเจ้า แต่ต้องเตือนว่าเผ่าข้าไม่เป็นมิตรกับคนแปลกหน้า นี่เป็นช่วงเวลายากลำบาก เราไว้ใจได้เพียงผู้ที่ร่วมต่อสู้ความเสื่อมทรามของดินแดน... และพิสูจน์ตนแล้ว ผู้ที่ยังไม่ทำเช่นนั้นจะพบความเป็นศัตรูอย่างเปิดเผยหากเข้าที่มั่น" },
    },
    [8465] = { -- Speak to Salfa
        title = { "14:1363743866:68414477", "คุยกับ Salfa" },
        objective = { "132:1640610951:266418630", "เดินทางผ่าน Timbermaw Hold แล้วออกสู่ Winterspring คุยกับ Salfa ผู้เฝ้าทางเข้า Timbermaw Hold" },
        description = { "502:187663652:1350345266", "ภัยความเสื่อมทรามไม่ได้มาจากเฟอร์โบลก Deadwood ทางใต้เท่านั้น แต่ยังมาจากตะวันออกและเฟอร์โบลก Winterfall แห่ง Winterspring หากอยากช่วยต่อ ให้คุยกับ Salfa อีกฟากของที่มั่น ใกล้ทางเข้า Winterspring ไปตามทางซ้ายจะถึง แต่ระวัง หากพวกข้าด้านในเห็นว่าเจ้าอยู่ระดับ Hostile หรือ Hated พวกเขาจะโจมตี เดินทางให้เร็วและหลีกเลี่ยงการปะทะ การฆ่า Timbermaw แม้ป้องกันตัว จะยิ่งทำให้พวกเราไม่ไว้ใจเจ้า" },
        completion = { "11:927657569:725753248 C 329:563680551:900711956", "สวัสดี {class} ข้าเฝ้าที่นี่ในฐานะทั้งผู้แทน Timbermaw ใน Winterspring และผู้ปกป้องเผ่า พี่น้อง Winterfall ในดินแดนหนาวจัดตกอยู่ใต้อำนาจเสื่อมทรามเดียวกับเฟอร์โบลกแห่ง Felwood หากเจ้ามาช่วยเผ่า Timbermaw เราก็พร้อมรับข้อเสนอ" },
    },
    [8466] = { -- Feathers for Grazle
        title = { "19:1998662162:1561604734", "ขนนกสำหรับ Grazle" },
        progress = { "449:1492416143:1554533724", "แม้เจ้าพิสูจน์ตนต่อข้าแล้ว ก็อาจต้องทำต่อเพื่อให้พี่น้องร่วมเผ่าผู้ระแวงยอมรับ ข้าอาจช่วยเรื่องนี้ต่อได้ เฟอร์โบลก Deadwood บางตนสวมเครื่องประดับศีรษะเฉพาะแบบ ซึ่งใช้เป็นหลักฐานว่าลดจำนวนพวกมันได้ นำขนนกจากเครื่องประดับที่ได้มาให้ข้า ทุกชุดละห้าชิ้นจะทำให้เจ้าได้รับการยอมรับในหมู่ Timbermaw" },
        completion = { "11:534428891:784080240 N 168:37903315:1969841090", "ทำได้ดี {name}! ข้าจะให้เผ่าพันธุ์ของข้ารู้ถึงผลงานเจ้า อย่าลืมนำขนนกที่พบมาให้ ข้าจะรับต่อไปตราบเท่าที่จำเป็น" },
        description = { "449:1492416143:1554533724", "แม้เจ้าพิสูจน์ตนต่อข้าแล้ว ก็อาจต้องทำต่อเพื่อให้พี่น้องร่วมเผ่าผู้ระแวงยอมรับ ข้าอาจช่วยเรื่องนี้ต่อได้ เฟอร์โบลก Deadwood บางตนสวมเครื่องประดับศีรษะเฉพาะแบบ ซึ่งใช้เป็นหลักฐานว่าลดจำนวนพวกมันได้ นำขนนกจากเครื่องประดับที่ได้มาให้ข้า ทุกชุดละห้าชิ้นจะทำให้เจ้าได้รับการยอมรับในหมู่ Timbermaw" },
        objective = { "260:1728754368:1226817164", "เฟอร์โบลกเผ่า Deadwood บางตัวสวมเครื่องประดับศีรษะที่มีลักษณะเฉพาะ ใช้เป็นหลักฐานได้ว่าเจ้าช่วยลดจำนวนพวกมันลง หากได้เครื่องประดับศีรษะมา ให้นำขนนกจากเครื่องประดับนั้นมาให้ข้า ทุกครั้งที่เจ้าส่งขนนกครบห้าอัน ชื่อเสียงของเจ้าในหมู่ Timbermaw จะเพิ่มขึ้น" },
        required = { [21377] = { "26:210872493:795613171", "ขนนกจากเครื่องประดับศีรษะเดดวูด" } },
        objectiveLabels = {
            item = { ["Deadwood Headdress Feather"] = "ขนนกจากเครื่องประดับศีรษะเดดวูด" },
        },
    },
    [8467] = { -- Feathers for Nafien
