    [8469] = { -- Beads for Salfa
        title = { "15:234933176:861139777", "ลูกปัดสำหรับ Salfa" },
        progress = { "34:2111931593:1287341799 N 457:1094571462:1008250945", "เจ้าได้ความไว้ใจจากข้าแล้วแน่นอน {name} แต่ยังอาจต้องสร้างความไว้ใจกับเผ่าที่ระแวงของข้าต่อ มีสิ่งหนึ่งที่ทำได้ พวก Winterfall พกลูกปัดวิญญาณเพื่อกันวิญญาณชั่วร้าย เห็นชัดว่าลูกปัดทำหน้าที่ไม่สำเร็จ เพราะ Winterfall เองกลายเป็นตัวแทนความเสื่อมทราม นำลูกปัดวิญญาณจากเฟอร์โบลก Winterfall ที่ล้มลงมาให้ข้า ทุกชุดละห้าชิ้นจะทำให้เจ้าได้รับการยอมรับในหมู่ Timbermaw" },
        completion = { "247:769790815:118893213", "เจ้าพิสูจน์เกียรติต่อเราอีกครั้ง! ข้าจะให้เผ่าพันธุ์ของข้ารู้ถึงผลงานเจ้า อย่าลืมนำลูกปัด Winterfall ที่พบมาให้ ทุกชุดที่เจ้าส่งต่อไป ข้าจะพูดรับรองเจ้าต่อเผ่า" },
        description = { "34:2111931593:1287341799 N 457:1094571462:1008250945", "เจ้าได้ความไว้ใจจากข้าแล้วแน่นอน {name} แต่ยังอาจต้องสร้างความไว้ใจกับเผ่าที่ระแวงของข้าต่อ มีสิ่งหนึ่งที่ทำได้ พวก Winterfall พกลูกปัดวิญญาณเพื่อกันวิญญาณชั่วร้าย เห็นชัดว่าลูกปัดทำหน้าที่ไม่สำเร็จ เพราะ Winterfall เองกลายเป็นตัวแทนความเสื่อมทราม นำลูกปัดวิญญาณจากเฟอร์โบลก Winterfall ที่ล้มลงมาให้ข้า ทุกชุดละห้าชิ้นจะทำให้เจ้าได้รับการยอมรับในหมู่ Timbermaw" },
        objective = { "334:595440959:98865257", "เผ่า Winterfall ขึ้นชื่อว่าพกลูกปัดวิญญาณไว้ป้องกันภูตผีร้าย เห็นได้ชัดว่าลูกปัดพวกนี้ใช้ไม่ได้ผล เพราะพวก Winterfall กลับเป็นผู้แพร่ความเสื่อมทรามเสียเอง นำลูกปัดวิญญาณจากเฟอร์โบลกเผ่า Winterfall ที่ล้มลงมาให้ข้า ทุกครั้งที่เจ้าส่งลูกปัดครบห้าเม็ด ชื่อเสียงของเจ้าในหมู่ Timbermaw จะเพิ่มขึ้น" },
        required = { [21383] = { "23:2065480007:1735378291", "ลูกปัดวิญญาณวินเทอร์ฟอลล์" } },
        objectiveLabels = {
            item = { ["Winterfall Spirit Beads"] = "ลูกปัดวิญญาณวินเทอร์ฟอลล์" },
        },
    },
    [8470] = { -- Deadwood Ritual Totem
        title = { "21:1004137184:1018421825", "โทเท็มพิธีกรรม Deadwood" },
        objective = { "216:751063139:1338469707", "นำ Deadwood Ritual Totem เข้า Timbermaw Hold แล้วดูว่าเฟอร์โบลกตนใดใช้ประโยชน์ได้ พวก Timbermaw จะไม่พูดกับเจ้า เว้นแต่มีชื่อเสียงระดับ Neutral หรือสูงกว่ากับพวกเขา" },
        description = { "446:359689587:1139936291", "เจ้าพบโทเท็มพิธีกรรมของเฟอร์โบลก Deadwood รูปลักษณ์ธรรมดา แต่มีความสิ้นหวังที่สัมผัสได้แผ่ออกมา หากมีวัตถุที่เป็นตัวแทนชัดที่สุดของความเสื่อมทรามซึ่ง Deadwood ต้องทน ก็คงเป็นสิ่งนี้ เฟอร์โบลกตนหนึ่งใน Timbermaw Hold อาจใช้ประโยชน์จากมัน... หากเจ้าสร้างความไว้ใจพอให้พวกเขาพูดด้วยแล้ว" },
        progress = { "4:1517439313:201828457 C 146:135791918:2133809403", "ว่าอย่างไร {class} มีอะไรให้ช่วย? เจ้าเดินท่ามกลางพวกเราอย่างสงบ แต่มีบางอย่างผิดปกติแน่นอน ข้าสัมผัสได้... บางสิ่งที่น่ากังวล..." },
        completion = { "219:510293759:1204897921 N 179:1369851081:129300572", "โทเท็มนี้... ข้าจำได้ว่าเป็นของ Deadwood แต่มันอบอวลด้วยกลิ่นเสื่อมสลาย สิ่งชั่วร้ายที่ทำให้พี่น้องหันมาเป็นศัตรูเรา ย่อมอยู่ในวัตถุนี้แน่ เจ้าคิดถูกที่นำมาให้ {name} บางทีผ่านการศึกษาและพิธีกรรม เราจะพบว่าอะไรทำให้จิตใจพี่น้องมัวหมอง ขอบใจ สหาย โปรดรับของเหล่านี้แลกกับสิ่งที่พบ" },
        required = { [20741] = { "21:1004137184:1018421825", "โทเทมพิธีกรรมของ Deadwood" } },
        steps = { { "21:1004137184:1018421825", "โทเทมพิธีกรรมของ Deadwood" } },
        objectiveLabels = {
