    [969] = { -- Luck Be With You
        title = { "16:1095768758:380411721", "ขอโชคจงอยู่กับเจ้า" },
        objective = { "64:827859495:1075137693", "เก็บ Frostmaul Shard 4 ชิ้นให้ Witch Doctor Mau'ari ที่ Everlook", variants = { { "65:1421497970:2042416678", "เก็บ Frostmaul Shard 10 ชิ้นให้ Witch Doctor Mau'ari ที่ Everlook" } } },
        description = { "376:318850790:2122801187", "อา แค่มองข้าก็รู้แล้ว เจ้าอยากทำเครื่องรางนำโชค Mau'ari รู้เสมอ! ทางใต้มีหุบผาและยักษ์ที่ทำจากน้ำแข็งล้วน บางครั้งพวกยักษ์ก็มีเศษผลึกติดตัว แต่เจ้าเก็บเองจากหุบผาได้เช่นกัน เศษเหล่านี้สะท้อนพลังได้อย่างทรงอานุภาพ นำ Frostmaul Shard กลับมา 10 ชิ้น แล้วเครื่องรางของข้าจะเป็นของเจ้า\n\nหมายเหตุผู้แปล: ต้นฉบับเป้าหมายระบุ 4 ชิ้น แต่เนื้อเรื่องระบุ 10 ชิ้น ให้ตรวจจำนวนที่ตัวนับเควสในเกมต้องการ" },
        progress = { "48:2022163172:910634129", "นำเศษผลึกกลับมา แล้วข้าจะบอกเพิ่มเติม!" },
        completion = { "59:1460779627:1035396357", "อา ใช่... ข้าจะทำเครื่องรางให้แล้ว รอสักหน่อย!" },
        required = { [12334] = { "16:1655293447:1292179675", "เศษผลึก Frostmaul" } },
        objectiveLabels = {
            item = { ["Frostmaul Shards"] = "เศษผลึก Frostmaul" },
        },
    },
    [975] = { -- Cache of Mau'ari
        title = { "16:1444291021:1209290884", "เครื่องราง Cache of Mau'ari" },
        objective = { "75:2025372297:118387838", "รอสักครู่แล้วคุยกับ Witch Doctor Mau'ari อีกครั้งเพื่อรับเครื่องรางนำโชค" },
        description = { "416:1100580857:178087883", "ก่อนให้เครื่องราง ข้าควรอธิบายวิธีใช้ หากพกติดตัว เจ้าจะพบของบางอย่างจากสิ่งมีชีวิตที่ต่อสู้ด้วย หากไม่พก ก็จะไม่พบ เข้าใจไหม? เจ้าจะรู้จักของพิเศษเหล่านี้จากชื่อ E'ko หากพบก็นำมาให้ Mau'ari แล้วข้าจะช่วยเจ้า รอที่นี่ระหว่างข้าจัดการเครื่องราง" },
        completion = { "12:1055357314:800872003 N 111:946285151:887608924", "นี่ไง {name} จำไว้ว่าต้องพกติดตัว ทำไมไม่กลับไปในป่า แล้วดูว่าจะพบอะไรบ้าง?" },
    },
    [977] = { -- Are We There, Yeti?
        title = { "19:291631770:237017730", "ถึงไหนแล้ว เยติ?" },
        objective = { "64:811794126:764694135", "เก็บ Pristine Yeti Horn 2 ชิ้นให้ Umi Rumplesnicker ที่ Everlook" },
        description = { "444:1498382469:320460713", "ตอนนี้ข้ามีของคลุมชิ้นส่วนกลไกแล้ว เหลืออีกอย่างเดียว ที่จริงก็สอง สองเขา! Ice Thistle Patriarch กับ Matriarch มีเขาใหญ่ที่สุด แน่นอนว่าข้าต้องการพวกนั้น เยติชนิดนี้อยู่ในถ้ำทางตะวันออกเฉียงใต้ มีมากมาย หาพบไม่ยาก จำไว้ว่าข้าต้องการแต่เขาสวยที่สุด ไม่เอาเขาบิ่นหรือหักนะ!" },
        progress = { "44:2006073076:1856556019 N 38:2032987204:1696148302", "ข้าติดขนใกล้เสร็จแล้ว {name} รีบนำเขาพวกนั้นกลับมาที!" },
        completion = { "89:574846536:2066361669", "ข้าแทบรออวดสหายไม่ไหว! รอแป๊บ ข้าจะติดของพวกนี้... สมบูรณ์แบบ!" },
        required = { [12367] = { "18:1616003589:1945065743", "เขาเยติสภาพสมบูรณ์" } },
        objectiveLabels = {
            item = { ["Pristine Yeti Horn"] = "เขาเยติสภาพสมบูรณ์" },
        },
    },
    [3783] = { -- Are We There, Yeti?
        title = { "19:291631770:237017730", "ถึงไหนแล้ว เยติ?" },
        objective = { "61:1855668103:270831150", "เก็บ Thick Yeti Fur 10 ผืนให้ Umi Rumplesnicker ที่ Everlook" },
        description = { "485:1361155729:991384746", "สหายของข้าคิดอะไรเจ๋ง ๆ ได้เสมอ ข้าไม่เคยรู้สึกว่าสู้ได้... จนวันนี้! ข้าเพิ่งวาดแผนสิ่งประดิษฐ์สุดยอด หากสัญญาว่าจะไม่บอกใคร ข้าจะเผยความลับ... ข้าจะสร้างเยติกล! สหายต้องตกใจเมื่อเห็น และพอหายตกใจ ข้ารู้ว่าพวกเขาจะประทับใจ! ก่อนอื่นต้องใช้ขนหนาจากเยติ Ice Thistle เจ้าจะช่วยไหม? พบพวกมันได้ทางตะวันออกเฉียงใต้" },
        progress = { "82:173164234:1597564564", "ข้ามีงานต้องเริ่มมากมาย ช่วยนำขนมาให้เร็วที่สุดนะ!" },
        completion = { "24:1560497212:988119808 N 34:1849193370:1396903773", "ขนพวกนี้สมบูรณ์แบบ {name} เราเริ่มต้นได้ยอดเยี่ยมแล้ว!" },
        required = { [12366] = { "14:57604480:81322542", "ขนเยติหนา" } },
        objectiveLabels = {
            item = { ["Thick Yeti Fur"] = "ขนเยติหนา" },
        },
    },
