    [5222] = { -- Target: Writhing Haunt
        title = { "22:129020258:1542855808", "เป้าหมาย: Writhing Haunt" },
        objective = { "264:402056479:854340219", "ไป Writhing Haunt ใน Western Plaguelands ตามหาและปราบ Cauldron Lord แล้วใช้กุญแจของมันเปิดหม้อต้ม เจ้าต้องมี Empty Writhing Haunt Bottle ติดตัวเพื่อเก็บตัวอย่างพิษจากในหม้อ" },
        description = { "497:382967783:1722187703 N 1:33:33", "เราเปิดหม้อสำเร็จสองใบแล้ว แม้เจ้าจะใช้มันได้ต่อไปไม่สิ้นสุด เราก็ยังอยากเปิดอีกสองใบที่เหลือ จะได้มีทางปล่อยสารต้านมากขึ้น!\n\nคราวนี้ไปหม้อที่ Writhing Haunt เกือบตรงไปทางตะวันออกจาก Andorhal ค่อนข้างใกล้ซากกำแพงเมือง เช่นเดิม กำจัด Cauldron Lord เพื่อเอากุญแจ แล้วใช้ขวดนี้เก็บตัวอย่างจากหม้อ\n\nขอให้ล่าได้สำเร็จ {name}!" },
        progress = { "110:99130789:1896070640", "ฝาช่องเข้าหม้อต้มยังปิดแน่น เจ้าต้องหากุญแจจึงจะเปิดได้" },
        completion = { "396:1335310582:1075588912", "กุญแจ Cauldron Lord ไขฝาช่องหม้อนี้แล้วหายไป เช่นเดียวกับกุญแจหม้อสองใบก่อนหน้า สารเหม็นเน่าปั่นป่วนรุนแรงอยู่ใต้แท่นหม้อ\n\nมีก๊อกเล็กที่วางขวดรองได้พอดี ให้เจ้าเก็บตัวอย่างไปให้ High Priestess MacDonnell ที่ Chillwind Point" },
        required = { [13197] = { "27:716762057:2019899902", "กุญแจหม้อปรุงยาของ Writhing Haunt" }, [13188] = { "27:1110774360:1991701303", "ขวดเปล่าของ Writhing Haunt" } },
        steps = { { "27:716762057:2019899902", "กุญแจหม้อปรุงยาของ Writhing Haunt" }, { "27:1110774360:1991701303", "ขวดเปล่าของ Writhing Haunt" } },
    },
    [5223] = { -- Return to Chillwind Camp
        title = { "24:1708617325:191023314", "กลับไป Chillwind Camp" },
        objective = { "107:2127663635:634962470", "นำ Filled Writhing Haunt Bottle ไปให้ High Priestess MacDonnell ที่ Chillwind Camp ใน Western Plaguelands" },
        description = { "297:2034661958:487937436", "เจ้าค่อย ๆ เติมขวดจนเต็ม ตัวอย่างสารเหม็นที่ปั่นป่วนใต้แท่นหม้อไหลเยิ้มไปมาในภาชนะแก้วเปราะบาง\n\nเมื่อมีพิษในมือ ก็ถึงเวลากลับไปหา High Priestess MacDonnell ที่ Chillwind Camp เพื่อจบภารกิจ" },
        progress = { "177:1040423526:260942347", "เมื่อวิเคราะห์ตัวอย่างจากหม้อ Writhing Haunt สำเร็จ เราจะมีช่องทางที่สามในการส่งสารต้านอันรุนแรงไปเล่นงาน Scourge!" },
        completion = { "33:1616724390:524830576 N 463:1511432489:100136823", "อีกภารกิจที่สำเร็จอย่างดี {name}! ตอนนี้เรามีหม้อสามใบให้ใช้ต้าน Scourge หากอำนาจปลุกชีพของ Kel'Thuzad เหนือแผ่นดินนี้ไม่แข็งแกร่งเช่นปัจจุบัน ข้ากล้าพูดว่าเจ้าคงปิดมันไปแล้ว!\n\nAlchemist Arbington จะรายงานว่าหม้อนี้กับหม้ออื่นที่เรายึดใช้ต้องการอะไรเพื่อส่งสารต้านโรคระบาด บัดนี้ถึงเวลานำหม้อสุดท้ายทางตะวันตกมาอยู่ใต้อิทธิพลเรา!" },
    },
    [5224] = { -- Writhing Haunt Cauldron
        title = { "23:1838331181:545781236", "หม้อต้มที่ Writhing Haunt" },
        progress = { "342:293140144:65777099", "หม้อโรคระบาดของ Scourge ตั้งอยู่ตรงหน้า พ่นพิษมหาศาลสู่อากาศ ที่ฐานแท่นขนาดใหญ่มีฝาช่องเล็ก ๆ ธรรมดาอยู่\n\nเมื่อปราบ Cauldron Lord และได้กุญแจแล้ว เจ้าก็ใส่สารที่เหมาะสมลงหม้อเพื่อสร้างสารต้านโรคระบาดได้" },
        completion = { "239:1756304359:528278843", "เมื่อใส่สารลงส่วนผสมในหม้อ สีและลักษณะของกลุ่มควันที่พ่นออกเริ่มเปลี่ยนไป Scourge ที่อยู่แม้เพียงแถวใกล้หม้อดูจะผงะจากส่วนประกอบใหม่ที่ถูกปล่อยสู่สภาพแวดล้อม" },
        description = { "342:293140144:65777099", "หม้อโรคระบาดของ Scourge ตั้งอยู่ตรงหน้า พ่นพิษมหาศาลสู่อากาศ ที่ฐานแท่นขนาดใหญ่มีฝาช่องเล็ก ๆ ธรรมดาอยู่\n\nเมื่อปราบ Cauldron Lord และได้กุญแจแล้ว เจ้าก็ใส่สารที่เหมาะสมลงหม้อเพื่อสร้างสารต้านโรคระบาดได้" },
        required = { [13320] = { "16:1932639929:1817866691", "สารเร่งอาร์เคน" }, [13356] = { "19:1822802756:1375033073", "สารเสริมฤทธิ์ทางกาย" }, [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        objectiveLabels = {
            item = { ["Arcane Quickener"] = "สารเร่งอาร์เคน", ["Somatic Intensifier"] = "สารเสริมฤทธิ์ทางกาย", ["Runecloth"] = "ผ้ารูน" },
        },
    },
    [5225] = { -- Target: Gahrron's Withering
        title = { "27:251277066:261482398", "เป้าหมาย: Gahrron's Withering" },
        objective = { "270:670765261:2038534429", "ไป Gahrron's Withering ใน Western Plaguelands ตามหาและปราบ Cauldron Lord แล้วใช้กุญแจของมันเปิดหม้อต้ม เจ้าต้องมี Empty Gahrron's Withering Bottle ติดตัวเพื่อเก็บตัวอย่างพิษจากในหม้อ" },
        description = { "208:1250668857:1610614592 N 279:1707236586:291013920 C 1:46:46", "หม้อสุดท้ายอยู่ในไร่ที่บัดนี้เรียก Gahrron's Withering มีลูกสมุน Scourge ที่แข็งแกร่งกว่าเฝ้า โดยเฉพาะเรธกับภูตผี อย่าได้ประมาท {name}\n\nGahrron's Withering อยู่ทางตะวันออกเฉียงเหนือจากเราตรงนี้ ใกล้ต้นเขต Eastern Plaguelands เช่นเดิม กำจัด Cauldron Lord เอากุญแจ นี่คือขวดตัวอย่างเปล่า นำกลับมาให้ข้าเมื่อเติมแล้ว ขอแสงสว่างคุ้มครองในภารกิจอันตรายนี้ {class}" },
        progress = { "110:99130789:1896070640", "ฝาช่องเข้าหม้อต้มยังปิดแน่น เจ้าต้องหากุญแจจึงจะเปิดได้" },
        completion = { "412:1196897113:830534812", "กุญแจ Cauldron Lord Soulwrath สลายเมื่อแตะแม่กุญแจฝาช่องที่ฐานแท่นหม้อ มีเสียงโลหะกระทบเบา ๆ ข้างใน ก่อนฝาเปิดเผยพิษเหนียวข้นอีกมากในโครงหม้อ\n\nมีก๊อกเล็กที่วางขวดรองได้พอดี ให้เจ้าเก็บตัวอย่างไปให้ High Priestess MacDonnell ที่ Chillwind Point" },
        required = { [13196] = { "32:1632664038:705125592", "กุญแจหม้อต้มแห่ง Gahrron's Withering" }, [13189] = { "32:1244347700:1841982117", "ขวดเปล่าสำหรับ Gahrron's Withering" } },
        objectiveLabels = {
            item = { ["Gahrron's Withering Cauldron Key"] = "กุญแจหม้อต้มแห่ง Gahrron's Withering", ["Empty Gahrron's Withering Bottle"] = "ขวดเปล่าสำหรับ Gahrron's Withering" },
        },
    },
    [5226] = { -- Return to Chillwind Camp
        title = { "24:1708617325:191023314", "กลับไป Chillwind Camp" },
        objective = { "112:1305064292:1350933981", "นำ Filled Gahrron's Withering Bottle ไปให้ High Priestess MacDonnell ที่ Chillwind Camp ใน Western Plaguelands" },
        description = { "236:1695100920:474693054", "เจ้าค่อย ๆ ปิดก๊อกในแผงควบคุม มองของเหลวเหม็นเน่าจากหม้อหยดลงขวดเปล่า\n\nเมื่อมีพิษในมือ ก็ถึงเวลากลับไปหา High Priestess MacDonnell ที่ Chillwind Camp เพื่อจบภารกิจ" },
        progress = { "339:612279388:1539267346", "Gahrron's Withering มีหม้อใบสุดท้ายทางตะวันตกที่เราต้องเข้าถึง เมื่อได้ตัวอย่างโรคระบาดที่มันพ่น เราจะปล่อยสารของเราสู่สภาพแวดล้อมผ่านภาชนะสี่ใบแยกกัน! Scourge จะกีดกันเราจากทั้งสี่ได้ยาก แม้มีพลัง Kel'Thuzad หนุนหลัง" },
        completion = { "16:13216479:885815632 N 364:886563792:87904000", "ยินดีด้วย {name} เจ้าเปิดหม้อสุดท้ายให้เราแล้ว! อีกไม่นาน Alchemist Arbington จะรู้ว่าต้องใช้สารอะไรผสมในหม้อนี้\n\nส่วนเจ้า ข้ามั่นใจว่า Commander Valorfist อยากขอบคุณเป็นการส่วนตัว หากไม่มีเจ้า การต่อสู้ Scourge คงแทบเป็นไปไม่ได้ ขอบใจ วีรชน!" },
    },
    [5227] = { -- Gahrron's Withering Cauldron
