        description = { "342:293140144:65777099", "หม้อโรคระบาดของ Scourge ตั้งอยู่ตรงหน้า พ่นพิษมหาศาลสู่อากาศ ที่ฐานแท่นขนาดใหญ่มีฝาช่องเล็ก ๆ ธรรมดาอยู่\n\nเมื่อปราบ Cauldron Lord และได้กุญแจแล้ว เจ้าก็ใส่สารที่เหมาะสมลงหม้อเพื่อสร้างสารต้านโรคระบาดได้" },
        required = { [13320] = { "16:1932639929:1817866691", "สารเร่งอาร์เคน" }, [13354] = { "21:581694123:1451812436", "ตัวสั่นพ้องเอ็กโทพลาสซึม" }, [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        objectiveLabels = {
            item = { ["Arcane Quickener"] = "สารเร่งอาร์เคน", ["Ectoplasmic Resonator"] = "ตัวสั่นพ้องเอ็กโทพลาสซึม", ["Runecloth"] = "ผ้ารูน" },
        },
    },
    [5228] = { -- The Scourge Cauldrons
        title = { "21:1458255116:1970083300", "หม้อต้มของ Scourge" },
        objective = { "71:481597972:1570789630", "คุยกับ Shadow Priestess Vandis ที่ Bulwark ใน Western Plaguelands" },
        description = { "488:2061589850:1203096020", "ในดินแดนที่เคยเป็น Lordaeron มีหม้อต้มแปดใบ สี่ใบอยู่ทางตะวันตก อีกสี่ใบตั้งมั่นอยู่ทางตะวันออก หม้อพ่นพิษสู่อากาศเพื่อแพร่โรคระบาดทั่วแผ่นดินให้ Scourge\n\nพลังปลุกชีพของ Kel'Thuzad แรงเกินกว่าจะปิดหม้อตรง ๆ แต่เราคิดว่าอาจพลิกมันมาใช้ประโยชน์ได้ รองของข้า Shadow Priestess Vandis จะเป็นผู้ประสานงานภารกิจนี้ นางจะชี้แจงต่อจากข้า" },
        completion = { { "26:1987978644:1543164060 R 439:199158573:2078207115", "25:1643932216:1045444244 R 439:199158573:2078207115" }, "ข้าทักทายเจ้าจากเงามืด สหายชาว{race} ข้าจะประสานแผนบ่อนทำลายหม้อต้ม Scourge\n\nเป้าหมายคือเปลี่ยนส่วนผสมโรคระบาดที่หม้อสร้าง ให้เป็นสิ่งที่ส่งผลเสียต่อ Scourge เจ้าต้องเข้าถึงหม้อทั้งสี่ใน Western Plaguelands ให้ได้ก่อนจึงจะเปลี่ยนแปลงเช่นนี้ได้\n\nถึงเวลาที่เจ้าจะนำการบุกต้าน Scourge แล้ว วีรชน" },
    },
    [5229] = { -- Target: Felstone Field
        title = { "22:1958929233:2068624480", "เป้าหมาย: Felstone Field" },
        objective = { "270:65676439:220840865", "ไป Felstone Field ใน Western Plaguelands ตามหาและปราบ Cauldron Lord ที่นั่น มันอาจมีกุญแจเปิดหม้อต้ม เจ้าต้องมี Empty Felstone Field Bottle ติดตัวเพื่อเก็บตัวอย่างพิษจากในหม้อ" },
        description = { "494:400074402:658672231", "ในหม้อต้มทั้งสี่ของ Western Plaguelands หม้อที่ Felstone Field อาจเข้าถึงง่ายที่สุด Scourge วางทหารอ่อนประสบการณ์ไว้ที่นี่ แต่ก็อย่าประมาท\n\nไป Felstone Field ทางตะวันออกจากที่นี่ และตะวันตกเฉียงเหนือของ Andorhal แล้วสู้กับ Cauldron Lord มันมีกุญแจเปิดทางเข้าหม้อ เมื่อเปิดแล้ว ใช้ขวดนี้เก็บตัวอย่างพิษในหม้อ เราต้องศึกษาเพื่อพัฒนาสารต้าน" },
        progress = { "110:99130789:1896070640", "ฝาช่องเข้าหม้อต้มยังปิดแน่น เจ้าต้องหากุญแจจึงจะเปิดได้" },
        completion = { "446:1232057717:1541290331", "กุญแจจาก Cauldron Lord Bilemaw ไขฝาช่องได้พอดี แม้จะหายไปหลังใช้ แต่เจ้าคิดว่าน่าจะเปิดฝาได้โดยไม่ต้องใช้กุญแจแล้ว กลิ่นเหม็นรุนแรงออกจากช่องที่เปิด ขณะสารเข้มข้นไม่ทราบชนิดหมุนวนในหม้อ\n\nมีก๊อกเล็กที่วางขวดรองได้พอดี ให้เจ้าเก็บตัวอย่างไปให้ Shadow Priestess Vandis ที่ Bulwark" },
        required = { [13194] = { "27:1564808021:288047179", "กุญแจหม้อต้ม Felstone Field" } },
        objectiveLabels = {
            item = { ["Felstone Field Cauldron Key"] = "กุญแจหม้อต้ม Felstone Field" },
        },
    },
    [5230] = { -- Return to the Bulwark
        title = { "21:601865731:687067931", "กลับไป Bulwark" },
        objective = { "102:537855144:1962947990", "นำ Filled Felstone Field Bottle ไปให้ Shadow Priestess Vandis ที่ Bulwark ใน Western Plaguelands" },
        description = { "220:1306100884:1010793383", "เจ้ารองสารพิษผสมจากหม้อต้มลงขวดจนได้ปริมาณเหมาะสำหรับศึกษา\n\nเมื่อมีพิษในมือ ก็ถึงเวลากลับไปหา Shadow Priestess Vandis ที่ Bulwark เพื่อจบภารกิจ" },
        progress = { "52:884062845:638159610 N 55:447285361:1489798322", "ยินดีต้อนรับกลับสู่ความปลอดภัยพอประมาณของ Bulwark {name} มีความคืบหน้าเรื่องหม้อต้มอย่างไรบ้าง?" },
        completion = { "10:963015740:1087923650 N 473:1441719856:776283088", "ทำได้ดี {name} Apothecary Dithers น่าจะวิเคราะห์และคิดสารต้านสำหรับใส่ในหม้อได้ไม่นาน หากปล่อยสู่อากาศได้มากพอ เราอาจทำให้ Scourge ทั้งหมดที่นี่อ่อนแอ\n\nงานนี้ต้องทำต่อเนื่องแน่นอน เราต้องกลับไปที่หม้อและใส่ส่วนผสมของเราซ้ำเรื่อย ๆ แต่หากทำได้ต่อเนื่อง เราจะได้เปรียบ Scourge อย่างมากเมื่อถึงเวลารบ!" },
    },
    [5231] = { -- Target: Dalson's Tears
        title = { "22:1781007359:73533846", "เป้าหมาย: Dalson's Tears" },
        objective = { "260:1717014269:1528248897", "ไป Dalson's Tears ใน Western Plaguelands ตามหาและปราบ Cauldron Lord แล้วใช้กุญแจของมันเปิดหม้อต้ม เจ้าต้องมี Empty Dalson's Tears Bottle ติดตัวเพื่อเก็บตัวอย่างพิษจากในหม้อ" },
        description = { "141:300110731:392802784 C 355:57905292:1170361759", "หม้อโรคระบาดใบหนึ่งอยู่ในไร่ของบ้านเก่าที่บัดนี้เรียก Dalson's Tears วันนี้จะไม่มีผู้เสียน้ำตา {class} เราต้องโจมตีหม้อและเข้าถึงมันให้ได้!\n\nไป Dalson's Tears เกือบตรงไปทางเหนือจาก Andorhal แล้วกำจัด Cauldron Lord ที่นั่น มันน่าจะมีกุญแจเหมือนตัวก่อน ให้เจ้าเข้าถึงภายในหม้อ ใช้ขวดนี้เก็บตัวอย่างข้างใน แต่ละหม้อใช้พิษผสมเฉพาะของมัน" },
        progress = { "110:99130789:1896070640", "ฝาช่องเข้าหม้อต้มยังปิดแน่น เจ้าต้องหากุญแจจึงจะเปิดได้" },
        completion = { "361:1941564238:1732381262", "กุญแจโครงกระดูกจาก Cauldron Lord เลื่อนเข้ารูกุญแจอย่างง่ายดายแล้วหายไป เปิดทางให้เจ้าใช้หม้อนี้ได้ถาวร ของเหลวข้นหยาบไหลเป็นจังหวะผ่านท่อคดใต้หม้อ\n\nมีก๊อกเล็กที่วางขวดรองได้พอดี ให้เจ้าเก็บตัวอย่างไปให้ Shadow Priestess Vandis ที่ Bulwark" },
        required = { [13195] = { "27:1467578213:1596677029", "กุญแจหม้อต้ม Dalson's Tears" } },
        objectiveLabels = {
            item = { ["Dalson's Tears Cauldron Key"] = "กุญแจหม้อต้ม Dalson's Tears" },
        },
    },
