    [5461] = { -- The Human, Ras Frostwhisper
        title = { "27:1080041313:1689318450", "Ras Frostwhisper เมื่อเป็นมนุษย์" },
        objective = { "172:2074031847:995921312", "เดินทางไปซาก Stromgarde ใน Arathi Highlands ค้นหา Keepsake of Remembrance ในเมือง หากพบให้นำกลับไปให้ Magistrate Marduke" },
        description = { "459:1432650240:1189888697 N 1:46:46", "อันเดดกลัวชีวิต เช่นเดียวกับผู้มีชีวิตกลัวความตาย จึงไม่แปลกที่อันเดดซึ่งยังมีสติจะทำลายทุกสิ่งที่เหลือจากชีวิตเดิมหลังกลายร่าง\n\nโชคร้ายที่หากจะสร้างวัตถุซึ่งเปลี่ยน Ras Frostwhisper กลับเป็นผู้มีอายุขัย เราต้องมีของที่ระลึกจากช่วงที่เขายังมีชีวิต\n\nเจ้าต้องไปซากเมือง Stromgarde บ้านของ Frostwhisper แล้วค้นหาของเช่นนั้น ขอให้โชคดี {name}" },
        progress = { "42:673889836:1144697827 N 1:46:46", "Keepsake of Remembrance หาได้ยาก {name}" },
        completion = { "152:569154665:789705775 N 74:2098906427:1514958381", "ข้าเคยสงสัยว่าจะยังมีของเช่นนี้หลงเหลือหรือไม่ นี่เปิดโอกาสอันเหลือเชื่อ ซึ่งเราต้องไม่ปล่อยให้สูญเปล่า\n\nเตรียมตัว {name} เพราะสิ่งที่ข้าจะขอจะพาเจ้าเข้าสู่ขุมนรก" },
        required = { [13585] = { "23:663180502:918534907", "ของที่ระลึกแทนความทรงจำ" } },
        objectiveLabels = {
            item = { ["Keepsake of Remembrance"] = "ของที่ระลึกแทนความทรงจำ" },
        },
    },
    [5462] = { -- The Dying, Ras Frostwhisper
        title = { "27:387013069:1494324648", "Ras Frostwhisper เมื่อใกล้ตาย" },
        objective = { "170:2009984959:1168501380", "ไป Light's Hope ใน Eastern Plaguelands ตามหา Leonid Barthalomew the Revered แสดง Keepsake of Remembrance ให้เขาดูและเล่าทุกสิ่งที่ค้นพบ" },
        description = { "474:1902696242:1914179585 N 1:46:46", "ต้องปรับพลังของที่ระลึกบนผืนดินแปดเปื้อน\n\nเล่ากันว่า Frostwhisper ยอมจำนนต่อ Lich King ที่ Stratholme บนผืนดินเปื้อนเลือดนั้นเขาสละชีวิตอย่างเต็มใจและมีจุดมุ่งหมาย เพื่อเป็นหนึ่งในผู้ไม่ตาย\n\nเราต้องหาผืนดินนั้น\n\nมีอันเดดผู้หนึ่งต่อต้าน Scourge ได้รับการปลดปล่อยจาก Banshee Queen แต่ภักดีต่อ Argent Dawn จงตามหา Leonid Barthalomew the Revered เขาอาจรู้มากกว่านี้ ไป Light's Hope {name}" },
        progress = { "54:1284348743:1017495027", "อย่าถามในสิ่งที่เจ้าไม่อยากรู้คำตอบ" },
        completion = { "105:1430432929:147228156", "<Leonid สำรวจของที่ระลึก>\n\nปัญหาของเจ้าปลุกความทรงจำที่ข้าเคยหวังว่าจะไม่หวนกลับมา" },
    },
    [5465] = { -- Soulbound Keepsake
        title = { "18:492289932:1098183276", "ของที่ระลึกผูกวิญญาณ" },
        objective = { "77:2039321142:1952542034", "กลับไปหา Magistrate Marduke ที่ Caer Darrow แล้วแสดง Soulbound Keepsake ให้เขาดู" },
        description = { "37:1075959579:1509205309 N 34:1550535105:1181955042", "นำของที่ระลึกกลับไปให้ Marduke {name} เขาจะสอนวิธีใช้" },
        progress = { "29:1643499218:874818182", "เจ้าทำสิ่งเป็นไปไม่ได้สำเร็จหรือ?" },
        completion = { "69:1052353768:408055109", "ข้ามั่นใจเสียอีกว่าเจ้าจะมาร่วมกับข้า เป็นวิญญาณอับโชคอีกตน" },
        required = { [13624] = { "18:492289932:1098183276", "ของที่ระลึกผูกวิญญาณ" } },
        objectiveLabels = {
            item = { ["Soulbound Keepsake"] = "ของที่ระลึกผูกวิญญาณ" },
        },
    },
    [5504] = { -- Mantles of the Dawn
        title = { "19:890204051:704136693", "อาคม Mantle of the Dawn" },
        objective = { "94:43275904:1598595142", "นำ Argent Dawn Valor Token 10 เหรียญไปให้ Quartermaster Hasana ที่ Bulwark ใน Western Plaguelands" },
        description = { "52:1585587579:1709486144 N 439:1660267951:1682093213", "การรับใช้ Argent Dawn ของเจ้าน่าชื่นชม {name} เจ้าได้รับความเคารพยิ่งในหมู่เรา ข้าได้รับอนุญาตให้เปิดขายของมีค่าที่สุดอย่างหนึ่งของ Dawn แก่เจ้า นั่นคืออาคมเสริมความต้านทานเวทสำหรับไหล่\n\nใช้ Mantle กับเกราะไหล่ที่มีอยู่จะเพิ่มความต้านทานพลังเวทหนึ่งในห้าแบบ เพื่อแสดงการอุทิศตนต่ออุดมการณ์อย่างต่อเนื่อง ข้าขอ Valor Token ไม่น้อยกว่าสิบเหรียญ แลกสิทธิ์เข้าถึงอาคมเหล่านี้" },
        progress = { "10:151941728:1165085410 C 142:398922806:1844437349", "อา {class} ผู้สูงส่ง! นำ Valor Token ที่ขอมาแล้วหรือ? เมื่อส่งให้ข้า จะเปิดขายอาคมเสริมไหล่แบบต่าง ๆ ให้เจ้า" },
        completion = { "54:1263746445:523545867 N 258:1345546225:2000426297", "ยอดเยี่ยม เรารับรู้การอุทิศให้ Dawn ของเจ้าแล้ว {name} เมื่อสำเร็จ ข้ายินดีเปิดขายอาคมเสริมไหล่ให้ ตราบใดที่รักษาสถานะปัจจุบันกับเรา เจ้าจะซื้อได้จากเจ้าหน้าที่เสบียง Argent Dawn ที่ได้รับอนุญาตทุกคน\n\nเพื่อ Dawn พี่น้องของข้า!" },
        required = { [12844] = { "23:326836260:219752080", "เหรียญกล้าหาญ Argent Dawn" } },
        objectiveLabels = {
            item = { ["Argent Dawn Valor Token"] = "เหรียญกล้าหาญ Argent Dawn" },
        },
    },
    [5505] = { -- The Key to Scholomance
        title = { "22:840681398:306408748", "กุญแจสู่ Scholomance" },
        completion = { "19:722495815:233721250 N 299:1643441710:682573653", "เอาละ นี่ {name} Skeleton Key ที่เสร็จสมบูรณ์ ข้ามั่นใจที่สุดเท่าที่จะทำได้ว่ามันจะพาเข้า Scholomance แต่มีทางเดียวที่จะรู้แน่ว่าใช้ได้ อย่าเสียเวลา รีบไปลองเลย\n\nโชคดี วีรชนผู้ยิ่งใหญ่ ขอให้เจ้านำแสงสว่างสู่ความมืดต่อไป!" },
    },
    [5507] = { -- Mantles of the Dawn
        title = { "19:890204051:704136693", "อาคม Mantle of the Dawn" },
        objective = { "101:1139255822:252617397", "นำ Argent Dawn Valor Token 10 เหรียญไปให้ Quartermaster Lightspark ที่ Chillwind Camp ใน Western Plaguelands" },
        description = { "52:1585587579:1709486144 N 439:1660267951:1682093213", "การรับใช้ Argent Dawn ของเจ้าน่าชื่นชม {name} เจ้าได้รับความเคารพยิ่งในหมู่เรา ข้าได้รับอนุญาตให้เปิดขายของมีค่าที่สุดอย่างหนึ่งของ Dawn แก่เจ้า นั่นคืออาคมเสริมความต้านทานเวทสำหรับไหล่\n\nใช้ Mantle กับเกราะไหล่ที่มีอยู่จะเพิ่มความต้านทานพลังเวทหนึ่งในห้าแบบ เพื่อแสดงการอุทิศตนต่ออุดมการณ์อย่างต่อเนื่อง ข้าขอ Valor Token ไม่น้อยกว่าสิบเหรียญ แลกสิทธิ์เข้าถึงอาคมเหล่านี้" },
        progress = { "10:151941728:1165085410 C 142:398922806:1844437349", "อา {class} ผู้สูงส่ง! นำ Valor Token ที่ขอมาแล้วหรือ? เมื่อส่งให้ข้า จะเปิดขายอาคมเสริมไหล่แบบต่าง ๆ ให้เจ้า" },
        completion = { "54:1263746445:523545867 N 258:1345546225:2000426297", "ยอดเยี่ยม เรารับรู้การอุทิศให้ Dawn ของเจ้าแล้ว {name} เมื่อสำเร็จ ข้ายินดีเปิดขายอาคมเสริมไหล่ให้ ตราบใดที่รักษาสถานะปัจจุบันกับเรา เจ้าจะซื้อได้จากเจ้าหน้าที่เสบียง Argent Dawn ที่ได้รับอนุญาตทุกคน\n\nเพื่อ Dawn พี่น้องของข้า!" },
        required = { [12844] = { "23:326836260:219752080", "เหรียญกล้าหาญ Argent Dawn" } },
        objectiveLabels = {
            item = { ["Argent Dawn Valor Token"] = "เหรียญกล้าหาญ Argent Dawn" },
        },
    },
    [5511] = { -- The Key to Scholomance
        title = { "22:840681398:306408748", "กุญแจสู่ Scholomance" },
        completion = { "19:722495815:233721250 N 337:448950281:1139685223", "เอาละ นี่ {name} Skeleton Key ที่เสร็จสมบูรณ์ ข้ามั่นใจที่สุดเท่าที่จะทำได้ว่ามันจะพาเข้า Scholomance แต่มีทางเดียวที่จะรู้แน่ว่าใช้ได้ อย่าเสียเวลา รีบไปลองเลย\n\nโชคดี วีรชนผู้ยิ่งใหญ่ ขอชัยชนะนำชื่อเสียงและอำนาจมาให้ต่อไป ขณะเจ้าทำลาย Scholomance!" },
    },
    [5514] = { -- Mold Rhymes With...
        title = { "19:1264728918:169573242", "แม่พิมพ์คล้องจองกับ..." },
        objective = { "88:2075046850:419260791", "นำ Imbued Skeletal Fragments และเงิน 15 เหรียญทองไปให้ Krinkle Goodsteel ที่ Gadgetzan" },
        description = { "490:897372684:1987647681", "ก็อบลินที่เจ้าต้องคุยด้วยคือ Krinkle Goodsteel เขาขายฝีมือให้ผู้จ่ายสูงสุดที่ Gadgetzan ในทะเลทราย Tanaris คงมีเขาคนเดียวที่ทำแม่พิมพ์ที่ต้องการได้ และค่าจ้างไม่ถูก ตอนนี้เราต้องขอให้เจ้าควักเงินจ่ายไม่ว่าเขาจะเรียกเท่าใด\n\nข้าเป็นเภสัชกร ไม่ใช่นายธนาคาร หากมีทองเหลือใช้คงไม่มาอยู่ที่นี่\n\nสงสัยข้าเผลอพูดสิ่งที่ควรเก็บไว้ในใจอีกแล้ว อุ๊บ\n\nGadgetzan รอเจ้าอยู่! โชคดี!" },
        progress = { "493:1366940599:841218633", "ใช่ ข้ารู้ว่าเจ้าเป็นใครและมาทำไม Dithers ส่งข่าวมาก่อนเจ้ามาถึง เข้าเรื่องซื้อขายกันเลยดีไหม?\n\nข้ามีแม่พิมพ์ที่ใช้ทำ Skeleton Key ได้ แต่ต้องจ่าย สิบห้าเหรียญทอง ล่วงหน้า ไม่ต่อรอง ข้าจะอัดเศษกระดูกลงแม่พิมพ์ให้ และสอนวิธีตีแกนกุญแจโดยไม่ต้องรู้วิชา Blacksmithing ทั้งหมดนั้นไม่คิดเพิ่ม\n\nใครว่าคนรับจ้างไม่เสนอข้อตกลงคุ้มค่า!" },
        completion = { "242:355067360:1113166270", "Dithers บอกว่าเจ้าจะนำของมา และเจ้าก็นำมาจริง! ตกลงแล้วก็ตามนั้น ให้ข้าอัดเศษกระดูกลงแม่พิมพ์ให้\n\nDithers ลงอาคมแล้วใช่ไหม? ดีมาก... ไม่เช่นนั้นเจ้าคงต้องเดินทางไกลกลับ Bulwark" },
    },
    [5521] = { -- Chromatic Mantle of the Dawn
        title = { "28:184385588:493989774", "อาคม Chromatic Mantle of the Dawn" },
        objective = { "101:2064345277:837714416", "นำ Argent Dawn Valor Token 25 เหรียญไปให้ Quartermaster Lightspark ที่ Chillwind Camp ใน Western Plaguelands" },
        description = { { "8:425663182:1740368764 N 457:1605391891:1179918743", "7:1679633005:833840561 N 457:1605391891:1179918743" }, "สหาย {name} ผลงานที่เจ้าทำในนาม Argent Dawn มากจนเล่าได้ไม่หมดง่าย ๆ เพื่อเป็นเกียรติอย่างเหมาะสม ข้าจะมอบ Chromatic Mantle of the Dawn พิเศษ แบบที่คุ้มครองผู้สวมจากเวททุกประเภทที่ต้านทานได้พร้อมกัน อาคมนี้สงวนให้วีรชนทรงพลังที่สุดของ Dawn เท่านั้น!\n\nนำ Valor Token ยี่สิบห้าเหรียญมาสมทบ แล้วข้าจะมอบอาคมเสริมไหล่ที่ดีที่สุดให้เจ้า" },
        progress = { "20:996681758:338287104 C 133:1757071013:863504299", "สวัสดี {class} ผู้ทรงพลัง! นำ Valor Token ที่ขอมาแล้วหรือ? เมื่อส่งให้ข้า จะมอบ Chromatic Mantle of the Dawn ให้เจ้าเอง" },
        completion = { "17:227795612:681635069 N 255:1081434388:1306604357", "น่าประทับใจมาก {name} บัดนี้ Chromatic Mantle of the Dawn เป็นของเจ้าแล้ว!\n\nตราบใดที่รักษาชื่อเสียงระดับ Exalted กับ Argent Dawn เจ้าจะซื้ออาคม Chromatic เพิ่มได้ โดยจะมีขายให้ทันทีจากเจ้าหน้าที่เสบียง Dawn ทุกคน" },
        required = { [12844] = { "23:326836260:219752080", "เหรียญกล้าหาญ Argent Dawn" } },
        objectiveLabels = {
            item = { ["Argent Dawn Valor Token"] = "เหรียญกล้าหาญ Argent Dawn" },
        },
    },
    [5524] = { -- Chromatic Mantle of the Dawn
        title = { "28:184385588:493989774", "อาคม Chromatic Mantle of the Dawn" },
        objective = { "94:662369206:418270897", "นำ Argent Dawn Valor Token 25 เหรียญไปให้ Quartermaster Hasana ที่ Bulwark ใน Western Plaguelands" },
        description = { { "8:425663182:1740368764 N 457:1605391891:1179918743", "7:1679633005:833840561 N 457:1605391891:1179918743" }, "สหาย {name} ผลงานที่เจ้าทำในนาม Argent Dawn มากจนเล่าได้ไม่หมดง่าย ๆ เพื่อเป็นเกียรติอย่างเหมาะสม ข้าจะมอบ Chromatic Mantle of the Dawn พิเศษ แบบที่คุ้มครองผู้สวมจากเวททุกประเภทที่ต้านทานได้พร้อมกัน อาคมนี้สงวนให้วีรชนทรงพลังที่สุดของ Dawn เท่านั้น!\n\nนำ Valor Token ยี่สิบห้าเหรียญมาสมทบ แล้วข้าจะมอบอาคมเสริมไหล่ที่ดีที่สุดให้เจ้า" },
        progress = { "20:996681758:338287104 C 133:1757071013:863504299", "สวัสดี {class} ผู้ทรงพลัง! นำ Valor Token ที่ขอมาแล้วหรือ? เมื่อส่งให้ข้า จะมอบ Chromatic Mantle of the Dawn ให้เจ้าเอง" },
        completion = { "17:227795612:681635069 N 255:1081434388:1306604357", "น่าประทับใจมาก {name} บัดนี้ Chromatic Mantle of the Dawn เป็นของเจ้าแล้ว!\n\nตราบใดที่รักษาชื่อเสียงระดับ Exalted กับ Argent Dawn เจ้าจะซื้ออาคม Chromatic เพิ่มได้ โดยจะมีขายให้ทันทีจากเจ้าหน้าที่เสบียง Dawn ทุกคน" },
        required = { [12844] = { "23:326836260:219752080", "เหรียญกล้าหาญ Argent Dawn" } },
        objectiveLabels = {
            item = { ["Argent Dawn Valor Token"] = "เหรียญกล้าหาญ Argent Dawn" },
        },
    },
    [5533] = { -- Scholomance
        title = { "11:1532064226:363932357", "Scholomance" },
        objective = { "71:1013258053:550574787", "คุยกับ Alchemist Arbington ที่ Chillwind Point ใน Western Plaguelands" },
        description = { "491:1165114429:565031251", "บนเกาะ Caer Darrow มี Scholomance ศูนย์กลางชั่วร้ายของเวทปลุกชีพ Scourge ศัตรูของเราอยู่ข้างใน กระทำความเลวทรามเกินบรรยายต่อเหยื่อที่ไม่รู้ตัว... อย่างน้อยเราก็คาดว่าเช่นนั้น มีประตูขวางทาง ต่อให้พยายามเพียงใดก็เข้าไม่ได้หากไม่มีกุญแจที่ถูกต้อง\n\nAlchemist Arbington รู้เรื่อง Scholomance ดี และมีความคิดว่าจะหากุญแจได้อย่างไร เจ้าพิสูจน์คุณค่าต่อข้าแล้ว ข้าจึงมอบหมายงานนี้ ไปคุยเรื่องนี้กับเขา" },
        completion = { "10:1401179418:1568553899 C 240:350485982:342300601 N 54:470397646:180329439", "ยินดีที่ได้พบ {class} ช่วงนี้ข้าใช้เวลาศึกษา Scholomance อยู่มาก และเชื่อว่ารู้วิธีให้เจ้าได้กุญแจ... ที่ใช้ผ่านประตูหน้า\n\nข้าได้แต่จินตนาการว่าข้างในจะมีภาพสยดสยองเพียงใด {name} บางครั้งก็ไม่เข้าใจว่าพวกวีรชนอย่างเจ้าทำได้อย่างไร..." },
    },
    [5537] = { -- Skeletal Fragments
        title = { "18:481429528:613726318", "เศษกระดูก Skeletal Fragment" },
        objective = { "91:2112725001:1144204874", "นำ Skeletal Fragment 15 ชิ้นไปให้ Alchemist Arbington ที่ Chillwind Point ใน Western Plaguelands" },
        description = { "335:2004349940:2026126958 N 154:673776761:2110005108", "กุญแจเข้า Scholomance ชื่อ Skeleton Key ต้องตีจากซากโครงกระดูก ที่จริงต้องใช้หลายโครงด้วย แล้วเสริมความแข็งด้วยโลหะที่แกร่งที่สุดในแม่พิมพ์ที่เหมาะสม ตราผนึกพลังจากผู้ที่เปิดทางเข้า Scholomance ได้ด้วยตัวเองจะทำให้กุญแจใช้งานได้ในที่สุด\n\nแต่เอาทีละขั้นนะ {name} เราต้องหาเศษกระดูกมาตีกุญแจก่อน โครงกระดูกใน Andorhal น่าจะให้สิ่งที่ต้องการได้ พวกนอกกำแพงก็อาจใช้ได้เช่นกัน" },
        progress = { "177:1775223831:529753710", "แม้ฟังน่าขนลุก เราต้องใช้เศษกระดูกที่เหมาะสมจำนวนหนึ่งทำชั้นนอกของกุญแจ มันไม่ได้ชื่อ Skeleton Key โดยไร้เหตุผลหรอกนะ" },
        completion = { "14:1440727889:1211197052 N 376:1628617612:1431911416", "พวกนี้ใช้ได้ {name}! ถึงตาข้าแล้ว ข้าจะปรับคุณสมบัติให้ทนกระบวนการตีอันร้อนแรงที่จะต้องผ่านในท้ายที่สุด\n\nขั้นต่อไปต้องหาแม่พิมพ์กุญแจที่เหมาะสม ข้ารู้จักช่างตีเหล็กก็อบลินใน Tanaris ที่เคยทำแม่พิมพ์ของน่าสยองคล้ายกัน เขารับงานให้คนแบบที่ก็อบลินมักรับงานให้ นั่นคือผู้จ่ายแพงที่สุด" },
        required = { [14619] = { "18:481429528:613726318", "เศษกระดูก" } },
        objectiveLabels = {
            item = { ["Skeletal Fragments"] = "เศษกระดูก" },
        },
    },
    [5538] = { -- Mold Rhymes With...
        title = { "19:1264728918:169573242", "แม่พิมพ์คล้องจองกับ..." },
        objective = { "88:2075046850:419260791", "นำ Imbued Skeletal Fragments และเงิน 15 เหรียญทองไปให้ Krinkle Goodsteel ที่ Gadgetzan" },
        description = { "489:1719623239:243236840", "ก็อบลินที่เจ้าต้องคุยด้วยคือ Krinkle Goodsteel เขาขายฝีมือให้ผู้จ่ายสูงสุดที่ Gadgetzan ในทะเลทราย Tanaris คงมีเขาคนเดียวที่ทำแม่พิมพ์ที่ต้องการได้ และค่าจ้างไม่ถูก ตอนนี้เราต้องขอให้เจ้าควักเงินจ่ายไม่ว่าเขาจะเรียกเท่าใด\n\nข้าเป็นนักเล่นแร่แปรธาตุ ไม่ใช่นายธนาคาร หากมีทองเหลือใช้คงไม่มาอยู่ที่นี่\n\nสงสัยข้าเผลอพูดสิ่งที่ควรเก็บไว้ในใจอีกแล้ว อุ๊บ\n\nGadgetzan รอเจ้าอยู่! โชคดี!" },
        progress = { "495:1658591386:235505088", "ใช่ ข้ารู้ว่าเจ้าเป็นใครและมาทำไม Arbington ส่งข่าวมาก่อนเจ้ามาถึง เข้าเรื่องซื้อขายกันเลยดีไหม?\n\nข้ามีแม่พิมพ์ที่ใช้ทำ Skeleton Key ได้ แต่ต้องจ่าย สิบห้าเหรียญทอง ล่วงหน้า ไม่ต่อรอง ข้าจะอัดเศษกระดูกลงแม่พิมพ์ให้ และสอนวิธีตีแกนกุญแจโดยไม่ต้องรู้วิชา Blacksmithing ทั้งหมดนั้นไม่คิดเพิ่ม\n\nใครว่าคนรับจ้างไม่เสนอข้อตกลงคุ้มค่า!" },
        completion = { "250:1805256915:131105173", "Arbington บอกว่าเจ้าจะนำของมา และเจ้าก็นำมาจริง! ตกลงแล้วก็ตามนั้น ให้ข้าอัดเศษกระดูกลงแม่พิมพ์ให้\n\nArbington ลงอาคมแล้วใช่ไหม? ดีมาก... ไม่เช่นนั้นเจ้าคงต้องเดินทางไกลกลับ Chillwind Point" },
    },
    [5803] = { -- Araj's Scarab
        title = { "13:1249201829:1981210934", "ตราแมลง Araj's Scarab" },
        objective = { "113:981357718:1311937715", "ทำลาย Araj the Summoner แล้วนำ Araj's Scarab ไปให้ Alchemist Arbington ที่ Chillwind Point ใน Western Plaguelands" },
        description = { "454:578657329:1610854939 N 1:33:33", "Araj the Summoner ปกครอง Andorhal จากใจกลางซากเมือง เรารู้ว่ามันเคยเป็นผู้นำ Scholomance ก่อนยึดเมืองเป็นของตัวเอง การทำกุญแจให้เสร็จต้องนำตราของมันที่เรียก Scarab มาติดเป็นหัวกุญแจ\n\nเข้าใจกลาง Andorhal แล้วทำลายการครอบงำเมือง ขณะที่มันออกมาในที่เปิด เมื่อทำลายมันแล้ว ยึด Scarab จากภาชนะผนึกวิญญาณที่ตกอยู่!\n\nกุญแจสู่ Scholomance รอเจ้าอยู่ {name}!" },
        progress = { "21:1073267509:103012915 N 224:531669256:1660776834", "เจ้ามาไกลถึงเพียงนี้แล้ว {name} ต้องทำลายร่างกายของ Araj the Summoner เท่านั้น จึงจะได้สิ่งที่ใช้ทำกุญแจให้เสร็จ เอา Scarab ของ Araj มาให้ได้ไม่ว่าด้วยวิธีใด แล้วนำมาให้ข้า ข้าจะเชื่อมเป็นหัวกุญแจ" },
        completion = { "425:891493973:1739764451", "ใช่ นี่แหละ! ข้า... อีกครั้ง ข้าทึ่งในวีรกรรมของเจ้าจริง ๆ ยากจะเชื่อว่าเจ้ายินดีไปไกลเพียงใดเพื่อเอาชนะพลังมืด\n\nทีนี้ขอทำส่วนเล็กน้อยของข้าบ้าง ข้าเตรียมตัวทำละลายพิเศษไว้ น่าจะช่วยยึด Scarab เป็นหัวกุญแจ เติมพลังให้มันผ่านประตูที่ล็อกของ Scholomance\n\nเอาละ ลองกันเลย..." },
        required = { [14610] = { "13:1249201829:1981210934", "แมลงปีกแข็งของ Araj" } },
        objectiveLabels = {
            item = { ["Araj's Scarab"] = "แมลงปีกแข็งของ Araj" },
        },
    },
    [5804] = { -- Araj's Scarab
        title = { "13:1249201829:1981210934", "ตราแมลง Araj's Scarab" },
        objective = { "108:848547182:1236467795", "ทำลาย Araj the Summoner แล้วนำ Araj's Scarab ไปให้ Apothecary Dithers ที่ Bulwark ใน Western Plaguelands" },
        description = { "454:578657329:1610854939 N 1:33:33", "Araj the Summoner ปกครอง Andorhal จากใจกลางซากเมือง เรารู้ว่ามันเคยเป็นผู้นำ Scholomance ก่อนยึดเมืองเป็นของตัวเอง การทำกุญแจให้เสร็จต้องนำตราของมันที่เรียก Scarab มาติดเป็นหัวกุญแจ\n\nเข้าใจกลาง Andorhal แล้วทำลายการครอบงำเมือง ขณะที่มันออกมาในที่เปิด เมื่อทำลายมันแล้ว ยึด Scarab จากภาชนะผนึกวิญญาณที่ตกอยู่!\n\nกุญแจสู่ Scholomance รอเจ้าอยู่ {name}!" },
        progress = { "21:1073267509:103012915 N 218:1987614719:1396193593", "เจ้ามาไกลถึงเพียงนี้แล้ว {name} ต้องทำลายร่างกายของ Araj the Summoner เท่านั้น จึงจะได้สิ่งที่ใช้ทำกุญแจให้เสร็จ เอา Scarab ของ Araj มา ไม่ด้วยเล่ห์ก็ด้วยกล แล้วนำมาให้ข้า ข้าจะเชื่อมเป็นหัวกุญแจ" },
        completion = { "428:1738095583:1943784748", "ใช่ นี่แหละ! ข้า... อีกครั้ง ข้าทึ่งในไหวพริบและความกล้าของเจ้าจริง ๆ ยากจะเชื่อว่าเจ้ายินดีไปไกลเพียงใดเพื่อชัยชนะ\n\nทีนี้ขอทำส่วนเล็กน้อยของข้าบ้าง ข้าเตรียมตัวทำละลายพิเศษไว้ น่าจะช่วยยึด Scarab เป็นหัวกุญแจ เติมพลังให้มันผ่านประตูที่ล็อกของ Scholomance\n\nคงใช้เวลาเพียงครู่เดียว..." },
        required = { [14610] = { "13:1249201829:1981210934", "แมลงปีกแข็งของ Araj" } },
        objectiveLabels = {
            item = { ["Araj's Scarab"] = "แมลงปีกแข็งของ Araj" },
        },
    },
    [5861] = { -- Find Myranda
        title = { "12:1792606379:352318748", "ตามหา Myranda" },
        objective = { "96:917909829:1177757730", "เดินทางไป Uther's Tomb ทางตอนใต้ของ Plaguelands แล้วแสดง Tirion's Gift ให้ Myranda the Hag ดู" },
        description = { "N 490:914396408:394108346", "{name} เจ้าทำทุกสิ่งที่ข้าขอจนถึงตอนนี้แล้ว เหลืออีกขั้นเดียวในการเดินทางเพื่อชดเชยความผิด\n\nเจ้าต้องนำของที่รวบรวมไปส่ง Taelan แต่น่าเสียดาย Taelan กับทหาร Scarlet Crusade จะโจมตีทันทีที่เห็นเจ้า\n\nมีทางเดียวที่จะส่งสารข้าได้ คือใช้การปลอมตัวหลอกลวง\n\nทางใต้มีสุสาน Uther สหายเก่าแก่ที่ข้าไว้ใจชื่อ Myranda อาศัยอยู่ที่นั่น ไปหาและแสดงของให้นางดู นางจะช่วยเจ้า" },
        progress = { "27:2116760124:358212636", "ข้ารู้ว่าวันนี้ต้องมาถึง" },
        completion = { "251:1130154895:545851791 R 62:965232415:1237641369", "ข้าเป็นที่ปรึกษาที่ Tirion ไว้ใจที่สุดเมื่อเขาเป็น Lord of Mardenholde ข้าคัดค้านคำตัดสินของ Order of the Silver Hand อย่างเปิดเผย จึงถูกเนรเทศเพราะความบังอาจ\n\nเขาผ่านความเจ็บปวดและผิดหวังมากมายในชีวิต ชาว{race} เจ้าพร้อมแก้ความอยุติธรรมที่เกิดกับตระกูล Fordring หรือไม่?" },
    },
    [5862] = { -- Scarlet Subterfuge
        title = { "18:1351244251:878448935", "แผนลวง Scarlet" },
        objective = { "228:853545360:1009781887", "คุยกับ Myranda เพื่อรับ Scarlet Illusion เดินทางไป Hearthglen ขณะมี Scarlet Illusion แล้วส่ง Tirion's Gift ให้ Highlord Taelan Fordring\n\nHearthglen อยู่ทางเหนือ Taelan น่าจะอยู่ใน Mardenholde Keep" },
        description = { "419:1481491612:1011019635", "ข้าเป็นผู้ที่เจ้าเรียกว่านักสร้างภาพลวง แม้สร้างภาพช่วยให้เข้า Hearthglen ได้ แต่ระวัง พลังข้ามีขีดจำกัด\n\nหากออกห่างจากดินแดนนี้มากเกินไป ภาพลวงจะหมดฤทธิ์ เวทนี้ใช้สมาธิและพลังข้ามาก จึงรักษาผลไว้ได้เพียงช่วงสั้น\n\nคุยกับข้าอีกครั้งเมื่อพร้อม" },
        progress = { "43:1955740383:705850805", "เจ้าเป็นกองหนุนจาก Tyr's Hand หรือ?" },
        completion = { "251:2099273593:1043661171", "นี่อะไร ทหาร?\n\n<Taelan เปิดกล่องและเริ่มสำรวจของข้างใน>\n\nนี่... ไม่อาจเป็นจริง แต่ทุกสิ่งที่เจ้าแสดงให้ข้า...\n\n<Taelan ทรุดลงคุกเข่าข้างหนึ่ง หัวใจเต้นเร็ว โทสะที่สั่งสมมายาวนานกำลังจะระเบิดใส่เมืองนี้>" },
    },
    [5903] = { -- A Plague Upon Thee
        title = { "18:565323269:87247023", "ขอภัยพิบัติจงเยือนเจ้า" },
        objective = { "186:988503988:45709008", "ใช้ Empty Termite Jar กับ Termite Mound ใน Eastern Plaguelands เมื่อรวบรวม Plagueland Termite ครบ 100 ตัว กลับไปหา Nathaniel Dumah ที่ Chillwind Camp ใน Western Plaguelands" },
        description = { "497:1437083862:1980884060", "ข้าลองใช้กำลังขับไล่ Scarlet Crusade หลายครั้งแล้วแต่ไม่สำเร็จ จึงตัดสินใจเปลี่ยนมาทำให้ชีวิตพวกมันลำบากขึ้น\n\nหากเต็มใจช่วย ข้าอยากให้โรงเลื่อยนั่นถูกปลวกชนิดร้ายกาจที่สุดเข้ากัดกิน\n\nใน Plaguewood ใกล้ Stratholme ที่เคยรุ่งเรือง มีปลวกพันธุ์ที่รอดทั้งโรคระบาดและ Scourge หาจอมปลวกแล้วจับใส่โหลให้เต็ม เราจะเตรียมปล่อยมันใส่ Crusade" },
        progress = { "33:629464752:8475 N 42:2097144404:1794444332", "พบจอมปลวกหรือยัง {name}? ข้าได้ยินว่ามีทั่ว Plaguewood" },
        completion = { "22:1465595043:356124885 N 162:465026227:161727194", "พวกนี้เหมาะมาก {name} ขอบใจ ดูสิ... เบียดกันเต็มไปหมด ข้าแทบสงสาร Crusade แต่คิดอีกที โรงเลื่อยนั่นก็ไม่ใช่ของที่พวกมันมีสิทธิ์ยึด จริงไหม?" },
        required = { [15042] = { "17:108132544:2076361064", "ขวดจับปลวกเปล่า" }, [15043] = { "19:2061130933:1887296360", "ปลวกแห่ง Plaguelands" } },
        steps = { { "17:108132544:2076361064", "ขวดจับปลวกเปล่า" }, { "19:2061130933:1887296360", "ปลวกแห่ง Plaguelands" } },
    },
    [5904] = { -- A Plague Upon Thee
        title = { "18:565323269:87247023", "ขอภัยพิบัติจงเยือนเจ้า" },
        objective = { "134:452469727:1945603153", "หาจุดเหมาะสมตรงกลาง Northridge Lumber Mill ใน Western Plaguelands เพื่อวาง Barrel of Plagueland Termites" },
        description = { "394:81438230:1654679416", "เมื่อมีปลวกแล้ว นำถังเสริมเหล็กนี้ไป Northridge Lumber Mill ทางใต้ของ Hearthglen อยู่ตะวันตกของถนนที่ขึ้นไปยังเมือง\n\nเมื่อถึง วางถังกลางโรงเลื่อย หาที่เหมาะเช่นบนลังแล้วเปิดฝา จากนั้นปลวกจะทำงานเองจนโรงเลื่อยใช้การไม่ได้สำหรับ Crusade" },
        completion = { "88:291968726:1751797152", "ขณะวางถังบนลัง เห็นชัดว่าปลวกเริ่มกระสับกระส่าย" },
    },
    [5944] = { -- In Dreams
        title = { "9:1933695482:1764903172", "ในห้วงฝัน" },
        objective = { "41:520921093:1754458078", "คุ้มกัน Taelan Fordring ออกจาก Hearthglen" },
        description = { "502:1157381699:376306005", "ข้าเป็นหุ่นเชิด Grand Crusader มานาน อะไรคือเหตุผลให้สู้ต้านสิ่งที่ Scarlet Crusade กลายเป็น? เวลาผ่านหลายทศวรรษ แต่ความทรงจำล้ำค่าถึงพ่อคือสิ่งที่ทำให้ข้ายังมีชีวิต\n\nข้ามีความฝัน คนแปลกหน้า ในฝันพ่ออยู่กับข้า ยืนข้างข้าอย่างภูมิใจเมื่อข้าเข้าร่วมคณะ เราสู้กับกองทัพ Scourge เคียงบ่าเคียงไหล่ นำเกียรติมาสู่ Alliance และ Lordaeron\n\nข้าไม่อยากได้เพียงฝันอีกแล้ว\n\nพาข้าไปหาเขา" },
        progress = { "31:420168641:1143725060", "<Tirion สงบจิตใจได้อีกครั้ง>" },
        completion = { "492:527685181:1694237006", "ความตายของลูกข้าด้วยมืออสุรกายเหล่านี้จะไม่ผ่านไปโดยไร้ผลตามมา จงปลอบใจได้ว่าคณะได้ถือกำเนิดใหม่แล้ว\n\nบัดนี้ข้ารับตำแหน่ง Highlord แห่ง Order of the Silver Hand ใหม่\n\nของจากอดีตเหล่านี้คือทั้งหมดที่มีมอบตอบแทนสิ่งที่เจ้าทำ โปรดรับไว้เป็นสัญลักษณ์ความขอบคุณ ทุกชิ้นรับใช้ข้าอย่างดีมาตลอดหลายปี\n\nหวังว่าเราจะพบกันอีกในยามที่ดีกว่า แล้วรำลึกวันวาน... ศึกที่ต่อสู้อย่างยากเย็น... ความฝันที่เป็นจริง" },
    },
    [6004] = { -- Unfinished Business
        title = { "19:1343239514:752893687", "ธุระที่ยังค้างคา" },
        objective = { "140:1630073717:1582860821", "สังหาร Scarlet Medic 2 คน, Scarlet Hunter 2 คน, Scarlet Mage 2 คน และ Scarlet Knight 2 คน ก่อนกลับไปหา Kirsta Deepshadow ที่ Western Plaguelands" },
        description = { "489:478908905:674395687", "ข้าถูกส่งมาเป็นหน่วยสอดแนมเพื่อสร้างความเสียหายและประเมินแนวป้องกัน Hearthglen บางคนใน Alliance เห็นว่าเมืองเล็กนี้สำคัญกว่าคุณค่าทางประวัติศาสตร์ ข้าไม่มีหน้าที่ถามว่าสำคัญอย่างไร แต่ตอนนี้สภาพข้าทำต่อไม่ไหวจนกว่าจะได้พัก\n\nหากเต็มใจ ข้าจะจ่ายงาม ๆ ให้ช่วย เริ่มทางใต้จากที่นี่ ที่ค่ายใกล้แนวกั้นเล็กซึ่งพวกมันตั้งไว้ หากพิสูจน์ว่าแข็งแกร่งพอ บางทีข้าอาจให้ช่วยเป้าหมายหลักด้วย" },
        progress = { "17:367204205:1697962181 N 183:1809930877:662227447", "เป็นอย่างไร {name}? พวกมันแข็งแกร่งกว่าที่คิดไหม? หวังว่าไม่ หากจะทำงานที่นี่ให้สำเร็จ ต้องใช้กำลังมากกว่าสิ่งที่ข้าเพิ่งขอให้เจ้าทำอีกมาก" },
        completion = { "11:534428891:784080240 N 304:971639044:1835182266", "ทำได้ดี {name} ข้าทึ่งที่เจ้าจัดการพวกมันเร็วเพียงนี้ ขอบใจ\n\nข้ายังไม่เคยพบใครเห็นด้วยกับ Scarlet Crusade และวิธีของมัน ข้าเชื่อในแสงสว่างไม่แพ้ใครใน Stormwind แต่พวกมันแสดงให้เห็นว่าแค่อยากฆ่าทุกคนที่ไม่ภักดีต่อขบวนการ... แม้แต่ผู้บริสุทธิ์" },
    },
    [6023] = { -- Unfinished Business
        title = { "19:1343239514:752893687", "ธุระที่ยังค้างคา" },
        objective = { "102:1702840507:640521371", "สังหาร Huntsman Radley และ Cavalier Durgen ก่อนกลับไปหา Kirsta Deepshadow ที่ Western Plaguelands" },
        description = { "209:286812800:1474739042 N 290:815436996:1581094421", "ภารกิจจริงของข้าคือทำให้กองกำลังรอบนอก Scarlet Crusade อ่อนแอ แล้วแทรกซึม Hearthglen เพื่อประเมินจำนวน ข้ายังทำเองไม่ไหว ขอให้เจ้าช่วยอีกครั้งได้ไหม {name}? ข้อมูลที่เก็บก่อนถูกพบตัวบอกว่า Crusade มีสมาชิกสำคัญสองคนเป็นแกนหลักของกำลังนอกเมือง คือ Huntsman Radley กับ Cavalier Durgen สังหารพวกมันแล้วงานจะคืบหน้า ทั้งคู่น่าจะอยู่ตาม Hearthglen Pass นอกเขตเมือง" },
        progress = { "25:1969982042:676191056 N 181:1160726060:1162832125", "พบพวกมันหรือยัง {name}? เมื่อจัดการทั้งสองได้ ข้าจะเข้า Hearthglen เพื่อดูการจัดกำลังใกล้ ๆ ได้ ข้าทำไม่ได้หากไม่มีเจ้าช่วย ได้โปรด หา Radley กับ Durgen ให้ข้า" },
        completion = { "11:1191658970:1224418299 N 403:416998219:1032161932", "ขอบใจ {name} เจ้าช่วยมากกว่าที่ข้าหวังเสียอีก อากาศที่นี่เหมือนดูดความตั้งใจข้าไป ข้าเหนื่อย และรู้ว่าต่อให้อยู่ต่อก็ไม่ดีขึ้น\n\nข้ายังไม่แน่ใจว่าจะเข้า Hearthglen เพื่อรายงานกำลัง Scarlet Crusade ได้อย่างไร\n\nแต่นั่นอีกเรื่อง ก่อนเจ้าไป รับสิ่งนี้... เป็นค่าตอบแทน ขอบใจอีกครั้ง" },
        objectiveLabels = {
            monster = { ["Huntsman Radley slain"] = "ปราบ นายพราน Radley", ["Cavalier Durgen slain"] = "ปราบ อัศวินม้า Durgen" },
        },
    },
    [6025] = { -- Unfinished Business
        title = { "19:1343239514:752893687", "ธุระที่ยังค้างคา" },
        objective = { "175:1171686564:2122948075", "เข้า Hearthglen หาจุดสูงที่เห็นเมืองเพื่อประเมินกองกำลัง Scarlet Crusade แล้วกลับไปหา Kirsta Deepshadow ที่ Western Plaguelands" },
        description = { "77:673442295:1347641407 N 85:2083253782:389529952 N 335:534607221:940202941", "อะไรนะ? จริงหรือ? เจ้าอยากรู้เพิ่ม? แต่เจ้าช่วยข้ามากแล้ว {name} ข้าคงขอให้เข้า Hearthglen แทนไม่ได้\n\nแน่ใจหรือ {name}? Hearthglen อันตรายกว่าทางผ่านมาก ข้าคุ้มครองไม่ได้ แม้แต่ข้อมูลสิ่งที่เจ้าจะพบก็ไม่มี\n\nเอาละ หากเต็มใจช่วยจริง จงเข้าเมืองแล้วหาที่สูงซึ่งมองเห็นเมืองได้ชัด ประเมินจำนวนจากตรงนั้นแล้วกลับมารายงาน แต่ระวังด้วย..." },
        progress = { "23:1786045740:1497431905 N 22:1495067978:1735279259", "งานนี้อันตราย {name} ข้าอิจฉาความกล้าของเจ้า" },
        completion = { "16:856926774:1278399515 N 160:1476597510:879561735 N 26:1560000072:632915111", "เจ้าทำได้ {name}! ขอบใจ!\n\nข้าจะกลับไปหา Elling... หมายถึงกลับ Stormwind โดยเร็วที่สุด รับเงินนี่เถอะ อย่างน้อยข้าก็ควรตอบแทน เจ้าสร้างชื่อให้ชนชาติของตน {name} ขอบใจและโชคดี" },
        objectiveLabels = {
            event = { ["Overlook Hearthglen from a high vantage point"] = "มองลงไปยัง Hearthglen จากจุดสูง" },
        },
    },
    [6184] = { -- Flint Shadowmore
        title = { "16:1018149838:1689005553", "Flint Shadowmore" },
        objective = { "100:1534868282:1627601746", "เดินทางไป Chillwind Camp ใน Western Plaguelands แล้วพบผู้ติดต่อของเจ้า Flint Shadowmore" },
        description = { "426:117140677:1180515418 N 1:46:46", "ข้อมูลเดียวที่มีตอนนี้คือ Nathanos Marris อาจถูก Blightcaller สังหาร เราคาดว่า Blightcaller เป็นปีศาจตนเดียวกับที่กำจัดสายลับของข้า\n\nFlint Shadowmore เจ้าหน้าที่ SI:7 อีกคนประจำอยู่ค่าย Alliance ที่ Chillwind Point ใน Western Plaguelands ไปหาเขา เขาจะสรุปสถานการณ์ปัจจุบันใน Plaguelands และมอบหมายงาน\n\nโชคดี {name}" },
        completion = { "39:1006343014:1994445067 N 35:1921616106:1257042877", "ภารกิจแรกตรงไปตรงมา {name} เข้าไปแล้วกลับออกมา ลาดตระเวน..." },
    },
    [6389] = { -- A Plague Upon Thee
        title = { "18:565323269:87247023", "ขอภัยพิบัติจงเยือนเจ้า" },
        objective = { "174:35373735:1619959884", "ปล่อย Plagueland Termite ใน Northridge Lumber Mill แล้วนำ Barrel of Plagueland Termites กลับไปให้ Nathaniel Dumah ที่ Chillwind Camp ใน Western Plaguelands" },
        description = { "238:1493243381:551088633", "เจ้ามองหาของเหมาะจะเปิดถังรอบโรงเลื่อย แล้วพบชะแลงที่ดูน่าจะใช้ได้\n\nเจ้าตั้งหลัก ภาวนาให้หนีออกจากโรงเลื่อยได้ก่อนปลวกจะมาถึงตัว" },
        progress = { "18:1368783564:1270355331 N 253:1623004378:175517924", "ทำสำเร็จหรือยัง {name}? ปล่อยปลวกแล้วหรือ? ขอแสงสว่างช่วยเราหาก Scarlet Crusade ยังยึดได้ทั้งโรงเลื่อยและ Hearthglen มันไม่ควรได้สักแห่ง พวกมันแค่หาประโยชน์จากเหยื่อสงครามครั้งก่อน และควรถูกกำจัดดุจสัตว์คลั่ง!" },
        completion = { "17:1040512704:2131583955 N 148:1375945985:733904988", "ฮ่าฮ่า! ขอบใจ {name}! เจ้าทำได้! วิญญาณพ่อข้าพักได้แล้ว และข้าจะอยู่ได้อย่างสงบ\n\nขอบใจอีกครั้ง หากมีอะไรให้ข้าช่วยก็บอกมาได้เลย" },
        required = { [15044] = { "29:66425063:2137837342", "ถังปลวกจาก Plaguelands" } },
        objectiveLabels = {
            item = { ["Barrel of Plagueland Termites"] = "ถังปลวกจาก Plaguelands" },
        },
    },
    [6390] = { -- A Plague Upon Thee
        title = { "18:565323269:87247023", "ขอภัยพิบัติจงเยือนเจ้า" },
        objective = { "165:805472221:215306872", "ปล่อย Plagueland Termite ใน Northridge Lumber Mill แล้วนำ Barrel of Plagueland Termites กลับไปให้ Mickey Levine ที่ Bulwark ใน Tirisfal Glades" },
        description = { "238:1493243381:551088633", "เจ้ามองหาของเหมาะจะเปิดถังรอบโรงเลื่อย แล้วพบชะแลงที่ดูน่าจะใช้ได้\n\nเจ้าตั้งหลัก ภาวนาให้หนีออกจากโรงเลื่อยได้ก่อนปลวกจะมาถึงตัว" },
        progress = { "18:1368783564:1270355331 N 227:508778182:1926500105", "ทำสำเร็จหรือยัง {name}? ปล่อยปลวกในโรงเลื่อยแล้วหรือ?\n\nครอบครัวข้าสูญทั้งงานและชีวิตก็เลวร้ายพอแล้ว แต่ยังต้องเห็นสถานที่ที่ข้าเติบโตถูกพวกน่ารังเกียจซึ่งอ้างตนว่าศักดิ์สิทธิ์ยึดอีก... ถุย!!" },
        completion = { "11:1191658970:1224418299 N 123:1656080047:1328189285", "ขอบใจ {name} รับเงินนี่ไป ข้าเสียใจที่ให้ไม่ได้มากกว่านี้ แต่ขอให้ยินดีที่ได้ช่วยทำลายความพยายามของ Scarlet Crusade!" },
    },
    [1013] = { -- The Book of Ur
        title = { "14:1044228469:1510188616", "ตำราแห่ง Ur" },
        objective = { "78:1379033974:1733916859", "นำ Book of Ur ไปให้ Keeper Bel'dugur ที่ Apothecarium ใน Undercity" },
        description = { "N 354:1629815447:1696046787", "{name} ใน Shadowfang Keep มีตำราเล่มหนึ่งชื่อ Book of Ur ซึ่งจะมีค่ายิ่งในคลังสะสมข้า Ur เคยเป็นจอมเวทผู้ยิ่งใหญ่แห่ง Dalaran ก่อน Scourge มาเยือน งานศึกษาต่างโลกของเขามีค่ามากต่อ... คนบางกลุ่มในหมู่ Forsaken\n\nเข้า Shadowfang Keep แล้วหาตำรานั้น นำมาให้ข้า แล้วข้าจะรายงานความดีความชอบของเจ้าต่อ Dark Lady ของเรา..." },
        progress = { "23:812447661:1934580550 N 1:63:63", "พบหนังสือหรือยัง {name}?" },
        completion = { "313:1187805419:832233315", "ดีมาก ตำรานี้จะเติมเต็มคลังผลงานของ Ur ที่ข้าสะสมได้อย่างดี ความรู้ของเขายิ่งใหญ่ แต่มโนธรรมกลับขวางไม่ให้เขาเข้าถึงพลังที่แท้จริง ดังนั้นเมื่อ Scourge มาและพลังของเขาถูกทดสอบ มันจึงพ่ายแพ้\n\nพวกเรา Forsaken ยอมให้อ่อนแอเช่นนั้นไม่ได้ หากต้องการอยู่รอด...\n\n...หากต้องการพิชิต" },
        required = { [6283] = { "14:1044228469:1510188616", "คัมภีร์แห่ง Ur" } },
        steps = { { "14:1044228469:1510188616", "คัมภีร์แห่ง Ur" } },
    },
    [5503] = { -- Argent Dawn Commission
        title = { "22:1601023212:2121280306", "ตรา Argent Dawn Commission" },
        completion = { "462:1655373869:1493750249 C 22:1857728076:1582659761", "ผู้ต่อสู้ความชั่วในนาม Argent Dawn ทุกคนต้องสวม Argent Dawn Commission การสวมมันทำให้เจ้ามีสิทธิ์รับรางวัลที่เจ้าหน้าที่เสบียงเสนอ\n\nขณะสวมตรา เจ้าจะเก็บ Scourgestone จาก Scourge ที่สังหารได้ มันคือตราแสดงสังกัดที่บางตัวมีติดตัว รวบรวมแล้วนำมาให้ข้า แต่ละชุดที่ส่งจะได้เครื่องหมายวีรกรรม Argent Dawn Valor Token\n\nจงทำชะตาให้สำเร็จ {class} เข้าร่วมการต่อสู้วันนี้!", variants = { { "462:1655373869:1493750249 C 24:1684271726:497531035", "ผู้ต่อสู้ความชั่วในนาม Argent Dawn ทุกคนต้องสวม Argent Dawn Commission การสวมมันทำให้เจ้ามีสิทธิ์รับรางวัลที่เจ้าหน้าที่เสบียงเสนอ\n\nขณะสวมตรา เจ้าจะเก็บ Scourgestone จาก Scourge ที่สังหารได้ มันคือตราแสดงสังกัดที่บางตัวมีติดตัว รวบรวมแล้วนำมาให้ข้า แต่ละชุดที่ส่งจะได้เครื่องหมายวีรกรรม Argent Dawn Valor Token\n\nจงทำชะตาให้สำเร็จ {class} เข้าร่วมการต่อสู้วันนี้!" } } },
    },
    [5508] = { -- Corruptor's Scourgestones
        title = { "25:2080589194:1626592158", "Corruptor's Scourgestone" },
        progress = { "415:1467610935:195933090 N 51:1550821243:926720368", "Corruptor's Scourgestone คือตราของผู้บงการ Scourge ผู้ทรงพลังที่มีอำนาจบัญชาการ Scourge จะมีติดตัวเสมอ การสังหารตัวชั่วร้ายเช่นนั้นย่อมช่วยอุดมการณ์ Argent Dawn และความดีทุกประการ!\n\nในนาม Argent Dawn ข้าจะให้ Valor Token แลกกับตรานี้เพียงชิ้นเดียว ระวังขณะไปหา {name} อย่าประมาทผู้ทรงพลังเช่นนั้น" },
        completion = { { "17:1249154572:77733430 N 331:526242088:1174033292", "17:1249154572:77733430 N 329:198230639:1120077614" }, "ยินดีด้วย {name} ข้ายินดีมอบ Argent Dawn Valor Token ให้เจ้า!\n\nการได้เหรียญด้วยวิธีนี้แสดงว่าเจ้าเป็นวีรชนแท้ของฝ่ายธรรมะ เราเห็นคุณค่าความพยายามทุกอย่างที่ใช้ต้าน Scourge แต่การโค่นผู้นำของมันคือการมอบความพ่ายแพ้อย่างยับเยิน!\n\nเพื่อ Dawn สหายของข้า!", variants = { { "17:1249154572:77733430 N 330:1957344030:582717255", "ยินดีด้วย {name} ข้ายินดีมอบ Argent Dawn Valor Token ให้เจ้า!\n\nการได้เหรียญด้วยวิธีนี้แสดงว่าเจ้าเป็นวีรชนแท้ของฝ่ายธรรมะ เราเห็นคุณค่าความพยายามทุกอย่างที่ใช้ต้าน Scourge แต่การโค่นผู้นำของมันคือการมอบความพ่ายแพ้อย่างยับเยิน!\n\nเพื่อ Dawn สหายของข้า!" } } },
        description = { "415:1467610935:195933090 N 51:1550821243:926720368", "Corruptor's Scourgestone คือตราของผู้บงการ Scourge ผู้ทรงพลังที่มีอำนาจบัญชาการ Scourge จะมีติดตัวเสมอ การสังหารตัวชั่วร้ายเช่นนั้นย่อมช่วยอุดมการณ์ Argent Dawn และความดีทุกประการ!\n\nในนาม Argent Dawn ข้าจะให้ Valor Token แลกกับตรานี้เพียงชิ้นเดียว ระวังขณะไปหา {name} อย่าประมาทผู้ทรงพลังเช่นนั้น" },
        required = { [12843] = { "24:1512169827:520599882", "ศิลา Scourge ของผู้บงการ" } },
        objectiveLabels = {
            item = { ["Corruptor's Scourgestone"] = "ศิลา Scourge ของผู้บงการ" },
        },
    },
    [5509] = { -- Invader's Scourgestones
        title = { "23:251906273:510863554", "Invader's Scourgestone" },
        progress = { "434:492061747:1834116084", "Invader's Scourgestone คือตราของทหารชั้นยอด Scourge บางครั้งพบกับทหารที่แข็งแกร่งกว่าใน Plaguelands การสังหารพวกนี้ท้าทายจริง แต่ผู้รับหน้าที่ปราบความชั่วย่อมควรยินดีเผชิญมัน\n\nตอนนี้ Argent Dawn ให้ Valor Token แลกกับตราเหล่านี้สิบชิ้น นำมาให้ข้าที่นี่ แล้วข้าจะให้รางวัลที่เจ้าคู่ควร" },
        completion = { "17:1249154572:77733430 N 453:1652352900:443140678", "ยินดีด้วย {name} ข้ายินดีมอบ Argent Dawn Valor Token ให้เจ้า!\n\nทุกเหรียญที่มอบแก่ผู้คู่ควรคือสัญญาณว่ากระแสศึกเริ่มพลิกต้าน Scourge เมื่อวีรชนมากขึ้นเข้าต่อสู้ในดินแดนศัตรู Argent Dawn จะอยู่แนวหน้าแน่นอนเมื่อถึงเวลาทำสงครามกับความชั่วสูงสุดของ Scourge ข้าหวังว่าความกล้าที่ทำให้เจ้าได้เหรียญนี้ จะพาไปสู่ชัยชนะในวันนั้นด้วย!" },
        description = { "434:492061747:1834116084", "Invader's Scourgestone คือตราของทหารชั้นยอด Scourge บางครั้งพบกับทหารที่แข็งแกร่งกว่าใน Plaguelands การสังหารพวกนี้ท้าทายจริง แต่ผู้รับหน้าที่ปราบความชั่วย่อมควรยินดีเผชิญมัน\n\nตอนนี้ Argent Dawn ให้ Valor Token แลกกับตราเหล่านี้สิบชิ้น นำมาให้ข้าที่นี่ แล้วข้าจะให้รางวัลที่เจ้าคู่ควร" },
        required = { [12841] = { "22:443846457:987480009", "ศิลา Scourge ของผู้รุกราน" } },
        objectiveLabels = {
            item = { ["Invader's Scourgestone"] = "ศิลา Scourge ของผู้รุกราน" },
        },
    },
    [5510] = { -- Minion's Scourgestones
        title = { "22:534774924:1326674804", "Minion's Scourgestone" },
        progress = { "460:1701560694:1206010386", "Minion's Scourgestone คือตราของทหารทั่วไปใน Scourge บางครั้งพบกับทหารที่อ่อนแอกว่าใน Plaguelands แต่คำว่าอ่อนแอกว่านั้นต้องดูบริบท ไม่ว่า Scourge อยู่ที่ใดก็อย่าประมาท\n\nตอนนี้ Argent Dawn ให้ Valor Token แลกกับตราเหล่านี้ยี่สิบชิ้น ข้ายินดีแลกให้ หากเจ้าหา Scourgestone มาได้พอ!" },
        completion = { "17:1249154572:77733430 N 453:1676088404:1172865147", "ยินดีด้วย {name} ข้ายินดีมอบ Argent Dawn Valor Token ให้เจ้า!\n\nเหรียญนี้ใช้ได้สองอย่าง หนึ่ง ใช้เพิ่มชื่อเสียงกับ Argent Dawn เพื่อเข้าถึงทางเลือกและรางวัลที่สงวนให้พันธมิตรระดับ Honored และ Revered สอง นำไปจ่ายพร้อมเงินแก่เจ้าหน้าที่เสบียง เพื่อซื้อของมีค่าบางชนิดของ Dawn\n\nไม่ว่าจะเลือกแบบใด จงรู้ว่าเจ้าปฏิบัติหน้าที่สมกับตราที่ได้รับ ทำได้ดี!" },
        description = { "460:1701560694:1206010386", "Minion's Scourgestone คือตราของทหารทั่วไปใน Scourge บางครั้งพบกับทหารที่อ่อนแอกว่าใน Plaguelands แต่คำว่าอ่อนแอกว่านั้นต้องดูบริบท ไม่ว่า Scourge อยู่ที่ใดก็อย่าประมาท\n\nตอนนี้ Argent Dawn ให้ Valor Token แลกกับตราเหล่านี้ยี่สิบชิ้น ข้ายินดีแลกให้ หากเจ้าหา Scourgestone มาได้พอ!" },
        required = { [12840] = { "21:1430951278:1059279595", "ศิลา Scourge ของสมุน" } },
        objectiveLabels = {
            item = { ["Minion's Scourgestone"] = "ศิลา Scourge ของสมุน" },
        },
    },
    [5513] = { -- Mantles of the Dawn
        title = { "19:890204051:704136693", "อาคม Mantle of the Dawn" },
        objective = { "106:1755860690:1951588855", "นำ Argent Dawn Valor Token 10 เหรียญไปให้ Quartermaster Breechlock ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { "52:1585587579:1709486144 N 439:1660267951:1682093213", "การรับใช้ Argent Dawn ของเจ้าน่าชื่นชม {name} เจ้าได้รับความเคารพยิ่งในหมู่เรา ข้าได้รับอนุญาตให้เปิดขายของมีค่าที่สุดอย่างหนึ่งของ Dawn แก่เจ้า นั่นคืออาคมเสริมความต้านทานเวทสำหรับไหล่\n\nใช้ Mantle กับเกราะไหล่ที่มีอยู่จะเพิ่มความต้านทานพลังเวทหนึ่งในห้าแบบ เพื่อแสดงการอุทิศตนต่ออุดมการณ์อย่างต่อเนื่อง ข้าขอ Valor Token ไม่น้อยกว่าสิบเหรียญ แลกสิทธิ์เข้าถึงอาคมเหล่านี้" },
        progress = { "10:151941728:1165085410 C 142:398922806:1844437349", "อา {class} ผู้สูงส่ง! นำ Valor Token ที่ขอมาแล้วหรือ? เมื่อส่งให้ข้า จะเปิดขายอาคมเสริมไหล่แบบต่าง ๆ ให้เจ้า" },
        completion = { "54:1263746445:523545867 N 258:1345546225:2000426297", "ยอดเยี่ยม เรารับรู้การอุทิศให้ Dawn ของเจ้าแล้ว {name} เมื่อสำเร็จ ข้ายินดีเปิดขายอาคมเสริมไหล่ให้ ตราบใดที่รักษาสถานะปัจจุบันกับเรา เจ้าจะซื้อได้จากเจ้าหน้าที่เสบียง Argent Dawn ที่ได้รับอนุญาตทุกคน\n\nเพื่อ Dawn พี่น้องของข้า!" },
        required = { [12844] = { "23:326836260:219752080", "เหรียญกล้าหาญ Argent Dawn" } },
        objectiveLabels = {
            item = { ["Argent Dawn Valor Token"] = "เหรียญกล้าหาญ Argent Dawn" },
        },
    },
    [5517] = { -- Chromatic Mantle of the Dawn
        title = { "28:184385588:493989774", "อาคม Chromatic Mantle of the Dawn" },
        objective = { "106:244409873:680879008", "นำ Argent Dawn Valor Token 25 เหรียญไปให้ Quartermaster Breechlock ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { { "8:425663182:1740368764 N 457:1605391891:1179918743", "7:1679633005:833840561 N 457:1605391891:1179918743" }, "สหาย {name} ผลงานที่เจ้าทำในนาม Argent Dawn มากจนเล่าได้ไม่หมดง่าย ๆ เพื่อเป็นเกียรติอย่างเหมาะสม ข้าจะมอบ Chromatic Mantle of the Dawn พิเศษ แบบที่คุ้มครองผู้สวมจากเวททุกประเภทที่ต้านทานได้พร้อมกัน อาคมนี้สงวนให้วีรชนทรงพลังที่สุดของ Dawn เท่านั้น!\n\nนำ Valor Token ยี่สิบห้าเหรียญมาสมทบ แล้วข้าจะมอบอาคมเสริมไหล่ที่ดีที่สุดให้เจ้า" },
        progress = { "159:51272587:2016948802", "สวัสดี นักบวชผู้ทรงพลัง! นำ Valor Token ที่ขอมาแล้วหรือ? เมื่อส่งให้ข้า จะมอบ Chromatic Mantle of the Dawn ให้เจ้าเอง" },
        completion = { "17:227795612:681635069 N 255:1081434388:1306604357", "น่าประทับใจมาก {name} บัดนี้ Chromatic Mantle of the Dawn เป็นของเจ้าแล้ว!\n\nตราบใดที่รักษาชื่อเสียงระดับ Exalted กับ Argent Dawn เจ้าจะซื้ออาคม Chromatic เพิ่มได้ โดยจะมีขายให้ทันทีจากเจ้าหน้าที่เสบียง Dawn ทุกคน" },
        required = { [12844] = { "23:326836260:219752080", "เหรียญกล้าหาญ Argent Dawn" } },
        objectiveLabels = {
            item = { ["Argent Dawn Valor Token"] = "เหรียญกล้าหาญ Argent Dawn" },
        },
    },
    [5901] = { -- A Plague Upon Thee
        title = { "18:565323269:87247023", "ขอภัยพิบัติจงเยือนเจ้า" },
        objective = { "177:523838046:1328072825", "ใช้ Empty Termite Jar กับ Termite Mound ใน Eastern Plaguelands เมื่อเก็บ Plagueland Termite ครบ 100 ตัว ให้กลับไปหา Mickey Levine ที่ Bulwark ใน Tirisfal Glades" },
        description = { "258:2137384038:751677027 N 173:1144522807:1809469424", "ทีนี้ เพื่อสร้างความเดือดร้อนให้สการ์เล็ตครูเสด ข้าคิดจะพรากโรงเลื่อยหวงแหนไปจากพวกมัน ข้ามั่นใจว่าถ้าเสียทรัพยากรนี้ไป พวกมันจะลำบากมากในการป้องกันและสร้างเมืองขึ้นใหม่เพื่อจุดประสงค์ของตัวเอง เจ้าจะช่วยข้าไหม {name}?\n\nเริ่มจากเอาขวดนี้ไปเพลกวูดในเพลกแลนด์สตะวันออก เก็บปลวกที่พบตามจอมปลวกทั่วป่าใส่ขวด เมื่อได้พอก็กลับมา" },
        progress = { "30:747009385:99140618 N 37:1202443756:1792599117 C 103:1081071051:833669203", "ได้ปลวกแล้วหรือยัง {name}? {class} ฉลาดอย่างเจ้าคงเดาได้แล้ว\n\nเมื่อได้ปลวกพอ เราจะทำให้ไม่มีใครใช้โรงเลื่อยได้อีก!" },
        completion = { "22:1465595043:356124885 N 63:1583816842:783741025", "ใช้ได้ดีเลย {name} ขอบใจ\n\nหากพร้อมแล้ว เราไปขั้นต่อไปกัน" },
        required = { [15043] = { "19:2061130933:1887296360", "ปลวกแห่ง Plaguelands" } },
        objectiveLabels = {
            item = { ["Plagueland Termites"] = "ปลวกแห่ง Plaguelands" },
        },
    },
    [5902] = { -- A Plague Upon Thee
        title = { "18:565323269:87247023", "ขอภัยพิบัติจงเยือนเจ้า" },
        objective = { "134:452469727:1945603153", "หาจุดเหมาะสมตรงกลาง Northridge Lumber Mill ใน Western Plaguelands เพื่อวาง Barrel of Plagueland Termites" },
        completion = { "88:291968726:1751797152", "ขณะวางถังบนลัง เห็นชัดว่าปลวกเริ่มกระสับกระส่าย" },
        description = { "412:1640606969:504577891", "ตอนนี้เรามีปลวกมากพอแล้ว เอาถังเสริมเหล็กนี้ไปโรงเลื่อยนอร์ทริดจ์ทางใต้ของฮาร์ธเกลน มันอยู่ทางตะวันตกของถนนที่ขึ้นไปเมือง\n\nเมื่อถึง ให้วางถังกลางโรงเลื่อยในที่สูงหน่อย เช่นบนลัง\n\nพอเปิดถัง ที่เหลือก็จะจัดการตัวเอง กลับมาที่นี่แล้วข้าจะตอบแทนที่เจ้าช่วย" },
    },
    [5065] = { -- The Lost Tablets of Mosh'aru
        title = { "28:1704264994:493430562", "แผ่นจารึก Mosh'aru ที่สูญหาย" },
        objective = { "78:1358439575:1645265555", "นำ Third Mosh'aru Tablet และ Fourth Mosh'aru Tablet ไปให้ Prospector Ironboot ที่ Tanaris" },
        description = { "461:1994685426:700820108", "โทรลที่เจ้าคุยด้วยไม่ได้พูดความจริง แผ่นจารึกสองแผ่นที่หาให้เขากล่าวถึงการกักเก็บแก่นพลัง Hakkar แต่ตำนานยังมีมากกว่านั้น ข้าศึกษามานาน และพบว่าแผ่นจารึก Mosh'aru มีหกแผ่น ไม่ใช่สอง! หกแผ่น!\n\nข้ากลัวว่าเราคงไม่ชอบความลับที่แผ่นอื่นเก็บไว้...\n\nตามหาแผ่นที่สามและสี่ของ Mosh'aru อยู่กับโทรล Mossflayer ใน Eastern Plaguelands หาพบแล้วนำมาให้ข้า" },
        progress = { "84:1054334822:2044816288", "มีแผ่นจารึกหรือยัง? ข้ากลัวว่าข้อความจะเผยภัยใหญ่หลวงต่อโลกเรา" },
        completion = { "34:1333292009:602309379 N 93:1942000932:1809476015", "เจ้าพบแล้ว! เยี่ยม!\n\nขอบใจ {name} ข้าจะศึกษาข้อความและถอดความหมายอย่างละเอียด\n\nส่วนเจ้ามีงานอีกอย่าง..." },
        required = { [12411] = { "21:1800179987:1598800787", "แผ่นจารึก Mosh'aru แผ่นที่สาม" }, [12412] = { "22:438322061:1355743614", "แผ่นจารึก Mosh'aru แผ่นที่สี่" } },
        objectiveLabels = {
            item = { ["Third Mosh'aru Tablet"] = "แผ่นจารึก Mosh'aru แผ่นที่สาม", ["Fourth Mosh'aru Tablet"] = "แผ่นจารึก Mosh'aru แผ่นที่สี่" },
        },
    },
    [5142] = { -- Little Pamela
        title = { "13:1259724537:2071327435", "Pamela ตัวน้อย" },
        objective = { "20:90015169:1403538301", "ตามหา Pamela Redpath" },
        description = { "251:1409776155:1970249949 C 95:117529266:312823272", "พวกเราตายมากมายในศึก Darrowshire ตายมากมาย... และพบชะตาเลวร้ายกว่าตาย\n\nเมื่อศึกเริ่ม ข้าซ่อน Pamela หลานสาวไว้ และไม่รู้ว่าเกิดอะไรขึ้นกับนาง ข้าเป็นเพียงวิญญาณเร่ร่อน แต่ใจยังโหยหารู้ชะตา Pamela\n\nได้โปรด {class} ผู้มีน้ำใจ ไป Darrowshire เพื่อตามหานางได้ไหม? อยู่ทางตะวันออก เลย Gahrron's Withering ไป" },
        completion = { "36:556315755:1408061100", "สวัสดี หนูชื่อ Pamela เธอชื่ออะไร?" },
    },
    [5149] = { -- Pamela's Doll
        title = { "13:1754526246:1042533200", "ตุ๊กตาของ Pamela" },
        objective = { "19:1243451786:325621254", "ตามหาตุ๊กตาของ Pamela" },
        description = { "433:476545053:1224024476", "ป้า Marlene บอกให้หนูรอในบ้าน เพราะพ่อต้องไปสู้ พ่อหนูกล้าหาญที่สุดในโลกเลย!\n\nแต่หนูรอที่นี่นานแล้ว พ่อยังไม่มารับ บางครั้งคนไม่ดีมากระซิบกับหนู หนูอยากให้พ่อไล่พวกเขาไป แต่พ่อไม่อยู่!\n\nบางทีพอมืดหนูก็อยากเล่นตุ๊กตา แต่เล่นไม่ได้เพราะทิ้งไว้ในเมือง\n\nช่วยหาตุ๊กตาให้หนูได้ไหม?" },
        progress = { "21:1959651604:1343554159", "เจอตุ๊กตาหนูหรือยัง?" },
        completion = { "47:139467340:195926108", "เจอแล้ว! เธอเจอตุ๊กตาหนูแล้ว! ขอบคุณนะ!" },
        required = { [12885] = { "13:1754526246:1042533200", "ตุ๊กตาของ Pamela" } },
        objectiveLabels = {
            item = { ["Pamela's Doll"] = "ตุ๊กตาของ Pamela" },
        },
    },
    [5152] = { -- Auntie Marlene
        title = { "14:655921661:1173155223", "ป้า Marlene" },
        objective = { "51:1081798934:1849573157", "คุยกับ Marlene ทางใต้ของ Ruins of Andorhal" },
        description = { "301:639609592:1376340180 N 58:2087184121:2039943879", "หนูเหงาจัง! ครอบครัวอยู่ไหน? ป้า Marlene บอกให้รอที่นี่ แต่ป้าจากไปแล้วไม่กลับมา! ส่วนพ่อ... เธอเห็นพ่อไหม?\n\nบางทีป้า Marlene อาจรู้ว่าพ่ออยู่ไหน ป้าอยู่ใกล้ Andorhal ในบ้านทางใต้ หนูว่าบนเนิน... ป้าบอกว่าอยู่บนเนิน\n\nได้โปรด {name} เธอเป็นเพื่อนใหม่ของหนู! ช่วยไปคุยกับป้าให้ได้ไหม?" },
        completion = { "299:486362467:1217319638", "เจ้าพบ Pamela หรือ? นางเป็นอย่างไร? ยังมีชีวิตไหม?? โธ่ ไม่! Pamela ผู้น่าสงสาร! นางยังเด็ก เป็นเด็กที่มีความสุขเหลือเกิน...\n\nนางไม่รู้ว่าเกิดอะไรกับพ่อใช่ไหม? Joseph พี่น้องของข้า?\n\nไม่... นางคงไม่เข้าใจสิ่งที่เกิดกับ Joseph และต่อให้เข้าใจ ข้าก็ทำใจบอกไม่ได้..." },
    },
    [5153] = { -- A Strange Historian
        title = { "19:583807712:1337060324", "นักประวัติศาสตร์ประหลาด" },
        objective = { "39:1509149999:1343802807", "นำ Joseph's Wedding Ring ไปให้ Chromie" },
        description = { "489:1197462946:941409681", "ข้าหวังให้ Joseph กลับไปอยู่กับลูกสาว แต่เป็นไปไม่ได้ Scourge บิดเบือนวิญญาณเขาจนเป็นอสุรกาย โธ่ เขาถูกสาปแล้ว!\n\nแต่บางทีเราอาจเปลี่ยนชะตาได้\n\nค้นสุสานข้างนอกหาอนุสรณ์ Joseph ร่างเขาไม่อยู่ ถูกเหยียบย่ำทำลายไปหลายปีก่อน แต่ใต้อนุสรณ์มีแหวนแต่งงาน นำไปให้ Chromie โนมแปลกที่มีพลังแปลกมาก\n\nChromie พักในโรงแรมปรักหักพังมุมตะวันตกเฉียงเหนือของ Andorhal" },
        progress = { "80:1216286205:1057950668", "การมาเยือนของเจ้าดูเหมาะกับเวลา เจ้าคงไม่ได้มาจากอนาคตใช่ไหม?" },
        completion = { "240:1125651039:756460436", "นี่อะไร? แหวนแต่งงานหรือ? ขอข้าดู...\n\nอา แหวนนี้เคยอยู่บนนิ้วผู้ยิ่งใหญ่ แต่อดีตเขาเต็มโศกนาฏกรรม\n\nเจ้ามาช่วยเขาหรือ? ตอนนี้สายเกินไปมากแล้ว... แต่บางทีเราอาจช่วยเขาในอดีตได้!" },
        required = { [12894] = { "21:548423704:1923438914", "แหวนแต่งงานของ Joseph" } },
        objectiveLabels = {
            item = { ["Joseph's Wedding Ring"] = "แหวนแต่งงานของ Joseph" },
        },
    },
    [5168] = { -- Heroes of Darrowshire
        title = { "21:1195891627:420767715", "วีรชนแห่ง Darrowshire" },
        objective = { "60:1828632376:856533913", "นำ Davil's Libram และ Redpath's Shield ไปให้ Carlin Redpath" },
        description = { "454:1650303463:1361844783 N 38:954763928:1892995454", "วีรชน Darrowshire อยู่ในใจข้า และหนังสือ Annals of Darrowshire ที่เจ้านำมาเล่าเรื่องพวกเขา\n\nเล่าถึงพาลาดิน Davil Lightfire และการที่ Crusade นำคัมภีร์เขาไปศาลากลาง Hearthglen\n\nยังกล่าวถึง Captain Redpath พี่น้องของข้า หลังทรยศ โล่เขาแตกร้าวถูกทิ้ง บัดนี้อยู่ในที่ไม่น่าเป็นไปได้ คือใกล้โรงนาของ Gahrron's Withering\n\nรวบรวมของเหล่านี้ {name} เพราะชะตาและโศกนาฏกรรมแวดล้อมมันอยู่" },
        progress = { "24:140817740:1112789370 N 1:63:63", "มีของที่ระลึกหรือยัง {name}?" },
        completion = { "156:818967032:1276771337", "เจ้ามีคัมภีร์กับโล่แล้ว!\n\nประวัติของมันผูกกับ Darrowshire และข้ารู้สึกว่าชะตาจะนำมันมารวมกันอีกครั้ง" },
        required = { [12954] = { "14:219593243:1800405012", "คัมภีร์ของ Davil" }, [12955] = { "16:60932068:541301761", "โล่ของ Redpath" } },
        objectiveLabels = {
            item = { ["Davil's Libram"] = "คัมภีร์ของ Davil", ["Redpath's Shield"] = "โล่ของ Redpath" },
        },
    },
    [5181] = { -- Villains of Darrowshire
        title = { "23:177840475:2001856955", "เหล่าผู้ร้ายแห่ง Darrowshire" },
        objective = { "101:1789369863:982516483", "นำ Skull of Horgus และ Shattered Sword of Marduk ไปให้ Carlin Redpath ที่ Light's Hope Chapel" },
        description = { "419:1710914042:1755209821 N 60:1856070429:1142985930", "Annals of Darrowshire เล่าถึงผู้ร้ายในศึก กูลผู้เป็นนาย Horgus the Ravager ถูกกองกำลัง Alliance ทำลาย ร่างถูกโยนลงทะเลสาบทางตะวันตกเฉียงเหนือของ Corin's Crossing กะโหลกยังอยู่ที่นั่น\n\nMarduk the Black ไม่เคยถูกปราบ แต่ดาบเลื่องชื่อแตกและสูญหาย อยู่ก้นช่องเขาทางตะวันตกของ Corin's Crossing\n\nไปนำของเหล่านี้มา {name} ข้าไม่รู้ว่าทำไม แต่มั่นใจว่าชะตาของมันผูกกับเจ้า" },
        progress = { "38:1155043892:791537012 N 1:63:63", "พบกะโหลกกับดาบหรือยัง {name}?" },
        completion = { "27:702211435:1318163765 N 203:88363793:1938443259", "เจ้าพบแล้ว! ทำได้ดี {name}! ของเหล่านี้มีพลังที่ข้ายังไม่เข้าใจทั้งหมด พลังที่เจ้าจะควบคุมสักวัน\n\nมันยังปลุกความทรงจำมืดมน ความตาย การทรยศ และคืนสุดท้ายของ Darrowshire..." },
        required = { [12956] = { "15:517734236:1917550282", "กะโหลกของ Horgus" }, [12957] = { "25:910486788:1118926530", "ดาบที่แตกหักของ Marduk" } },
        objectiveLabels = {
            item = { ["Skull of Horgus"] = "กะโหลกของ Horgus", ["Shattered Sword of Marduk"] = "ดาบที่แตกหักของ Marduk" },
        },
    },
    [5206] = { -- Marauders of Darrowshire
        title = { "24:1242372032:1070605601", "ผู้ปล้นทำลาย Darrowshire" },
        objective = { "90:414838347:2130382094", "นำ Resonating Skull 5 ชิ้นและ Mystic Crystal ไปให้ Carlin Redpath ที่ Eastern Plaguelands" },
        description = { "395:385134353:459199998 N 98:1992021161:500467078", "Chromie บอกว่าของที่เจ้ารวบรวมเป็นส่วนประกอบเวททรงพลัง ยังขาดอีกอย่าง กะโหลกของ Scourge ที่ร่วมศึก Darrowshire\n\nนำผลึกนี้ไปล่า Scourge Champion เอากะโหลก ผลึกลงอาคมไว้ หากตัวนั้นร่วมศึก เมื่อใช้ผลึกผ่านกะโหลก มันจะสั่นพ้อง นำกะโหลกสั่นพ้องเหล่านั้นมาให้ข้า\n\nไปเถิด {name} พบ Scourge Champion ได้ที่ Noxious Glade ทางเหนือ และ Fungal Vale ทางตะวันตก" },
        progress = { "133:2098519082:362253614", "มีกะโหลกหรือยัง? Chromie บอกว่าสำคัญต่อเวทของนางอย่างยิ่ง เวทนั้นจะให้โอกาสเราช่วย Darrowshire" },
        completion = { "180:884220864:185668137", "เจ้าพบแล้ว! วิเศษ!\n\nแม้ข้าไม่เข้าใจทั้งหมดว่าจะช่วยอย่างไร ข้าสัมผัสพลังได้ และรู้ลึกถึงกระดูกว่ามันผูกกับหมู่บ้าน Darrowshire บ้านข้า" },
        required = { [13155] = { "16:1766251585:1059214714", "กะโหลกก้องสะท้อน" } },
        objectiveLabels = {
            item = { ["Resonating Skull"] = "กะโหลกก้องสะท้อน" },
        },
    },
    [5210] = { -- Brother Carlin
        title = { "14:1085992733:503078723", "Carlin พี่น้องของข้า" },
        objective = { "82:618254824:1113481075", "นำ Extended Annals of Darrowshire ไปให้ Carlin Redpath ที่ Eastern Plaguelands" },
        description = { "322:2034695132:143176423", "เวทข้าเพิ่มหน้าท้าย Annals of Darrowshire ให้เล่าประวัติต่อจากศึก ข้อความใหม่กล่าวถึง Redpath อีกคนชื่อ Carlin ผู้รอดการทรยศของ Joseph ตอนนี้อยู่ Light's Hope Chapel ใน Plaguelands ทางตะวันออก\n\nนำหนังสือไปคุยกับเขา" },
        progress = { "135:1379666899:760741199", "เจ้ามาจากตะวันตกหรือ? ส่วนอื่นของ Lordaeron เป็นอย่างไร? ข้ารู้ว่า Andorhal เสียไปแล้ว แต่ Scourge ไปถึง Tirisfal อันงดงามหรือยัง?" },
        completion = { "354:1854372680:1005334443", "หนังสืออะไร? Annals of Darrowshire หรือ? นั่นคือบ้านข้าก่อนสงคราม... ก่อนศึกที่ทำลายมัน! ทำไมนำเล่มนี้มาให้?\n\nแต่ดูนี่! หน้าท้ายเล่าเหตุการณ์หลังศึก! มีเรื่องข้า! และเรื่อง Joseph พี่น้องของข้า! หนังสือนี้เล่าความจริงหรือ?\n\nเราต้องค้นให้รู้!" },
        required = { [13202] = { "30:487806507:1895735831", "พงศาวดาร Darrowshire ฉบับขยาย" } },
        objectiveLabels = {
            item = { ["Extended Annals of Darrowshire"] = "พงศาวดาร Darrowshire ฉบับขยาย" },
        },
    },
    [5211] = { -- Defenders of Darrowshire
        title = { "24:1236520026:1333715817", "ผู้พิทักษ์แห่ง Darrowshire" },
        objective = { "57:486520115:322614509", "ปลดปล่อย Darrowshire Spirit 15 ดวง แล้วกลับไปหา Carlin Redpath" },
        description = { "451:880836564:1552154373", "ผู้พิทักษ์มากมายล้มตายในศึก Darrowshire และหลายคนกลับมาเร่ร่อนเป็นข้ารับใช้สยองของ Scourge! ตามหาวิญญาณน่าสงสารเหล่านี้แล้วจบความทุกข์!\n\nล่า Cannibal Ghoul, Gibbering Ghoul และ Diseased Flayer อสูรหลายตัวเคยเป็นคนดีแห่ง Darrowshire ทำลายร่างแล้วจะปลดปล่อยวิญญาณได้\n\nพบได้ใน Plaguewood, Corin's Crossing และฐาน Scourge อื่นใน Eastern Plaguelands" },
        progress = { "62:864475673:1258318087 N 21:1648984896:1245966904", "ผู้พิทักษ์ Darrowshire ผู้น่าสงสารร้องเรียกข้าในฝัน {name} เจ้าต้องปลดปล่อยพวกเขา!" },
        completion = { "215:955032149:1393925269", "ดีที่ได้ยินว่าเจ้าพบและปลดปล่อยวิญญาณพี่น้องที่ถูกทรมาน ใจข้าจะร้องไห้น้อยลง เมื่อรู้อย่างน้อยผู้พิทักษ์ Darrowshire บางคนไม่ต้องจมในสภาพทาสชั่วร้ายของ Scourge อีก" },
    },
    [5241] = { -- Uncle Carlin
        title = { "12:2067774119:2129149619", "ลุง Carlin" },
        objective = { "20:1548780045:1720905505", "ตามหา Carlin Redpath" },
        description = { "141:675171195:388837281 N 207:2068209789:1260730689", "บางคืนหนูได้ยินลุง Carlin ร้องไห้ เสียงเหมือนอยู่ไกลไปทางตะวันออก\n\nหวังว่าลุงไม่ได้ร้องไห้เพราะหนู! {name} ช่วยหาลุงแล้วบอกว่าหนูไม่เป็นไรได้ไหม?\n\nถ้าพบ บอกว่าหนูรอ อยากฟังเรื่องที่ลุงเคยเล่า... เรื่องกระต่ายกับแยมผลไม้! เรื่องนั้นตลกมากเลย!" },
        completion = { "304:2137968793:718211420 N 53:194214876:1885697224", "เจ้าพบ Pamela หรือ? นางยังมีชีวิต?\n\nนางตายแล้วหรือ? ไม่! โธ่ Pamela! ทำไมวิญญาณเจ้ายังทุกข์ในโลกนี้ ทำไมเจ้าตายแต่โชคยังรักษาชีวิตข้า? ข้ายอมสลับที่ทันที แล้วเร่ร่อนคนเดียวเป็นผีใน Darrowshire ที่ตายแล้ว!\n\nแต่ข่าวนี้เปลี่ยนชะตาไม่ได้ ขอบใจ {name} บัดนี้หน้าที่แก้แค้นของข้าลุกโชนไม่แพ้เดิม" },
    },
    [5246] = { -- Fragments of the Past
        title = { "21:686668420:1335905274", "เศษเสี้ยวอดีต" },
        objective = { "157:1316892819:446993366", "ตามหา Sacred Highborne Writings ใน Temple of Zin-Malor ที่ Azshara แล้วนำไปให้ Aurora Skycaller ใกล้ Northpass Tower ใน Eastern Plaguelands" },
        description = { "47:843629223:840944026 C 450:274772726:1873405229", "ข้าไม่รู้มาก่อน... ยกโทษให้คำพูดเย็นชาของข้า {class}\n\nข้าไม่อยากจมกับความผิดของบรรพบุรุษ แต่หากคำขอจริงใจ ข้าจะช่วย\n\n<Aurora สำรวจชิ้นส่วน>\n\nข้าเชื่อว่านี่คือ Crystal of Zin-Malor วัตถุที่กักเก็บและควบคุมพลังอาร์เคนรุนแรงได้ มันอาจใช้ทำความดี แต่เจตนาร้ายของผู้ขโมยทำให้แตก\n\nไป Temple of Zin-Malor ที่ Azshara ข้าได้แต่หวังว่าหนังสือยังอยู่" },
        progress = { "110:1159880974:1068560853", "มีเพียงเนื้อหาในตำราศักดิ์สิทธิ์ที่จะทำให้ข้ารู้ว่าช่วยเจ้าได้หรือไม่..." },
        completion = { "52:533132893:1215221008", "หน้ากระดาษเหล่านี้ไม่ถูกแตะต้องมานานหลายปีเหลือเกิน..." },
        required = { [13313] = { "25:46976393:576573077", "บันทึกศักดิ์สิทธิ์ของไฮบอร์น" } },
        objectiveLabels = {
            item = { ["Sacred Highborne Writings"] = "บันทึกศักดิ์สิทธิ์ของไฮบอร์น" },
        },
    },
    [5247] = { -- Fragments of the Past
        title = { "21:686668420:1335905274", "เศษเสี้ยวอดีต" },
        objective = { "144:78850286:807127522", "นำ Enchanted Thorium Bar, Crystal Restore 5 ชิ้น และ Vial of Dire Water ไปให้ Aurora Skycaller ใกล้ Northpass Tower ใน Eastern Plaguelands" },
        description = { "505:58436346:996024331", "ข้าช่วยได้ หากการสร้างวัตถุโบราณขึ้นใหม่เป็นความปรารถนาจริงของเจ้า\n\nเพื่อผนึกชิ้นส่วน ต้องใช้ของที่มีพลังเวทแรง Enchanted Thorium Bar และ Crystal Restore ห้าชิ้น... ยังต้องเก็บน้ำจากที่ที่อาจคาดไม่ถึง หาบ่อน้ำ Dire Pool ตาม Eldreth Row ใน Dire Maul ที่ Feralas แล้วเติมขวดนี้\n\nระหว่างเจ้าจากไป ข้าจะพยายามเรียนรู้จากตำราเพื่อซ่อมความเสียหายของวัตถุโบราณ" },
        progress = { "97:1065719654:367023655", "วัตถุโบราณต้องอยู่ในมือผู้ไว้ใจได้ที่สุดเท่านั้น จะถูกขโมยอีกไม่ได้..." },
        completion = { "92:238822511:1604023620", "ใช้สิ่งเหล่านี้ ข้าจะเชื่อมชิ้นส่วน... หวังว่าจะกลับเป็นเช่นเดิม" },
        required = { [11562] = { "15:771474959:509195872", "ผลึกฟื้นฟู" }, [12655] = { "21:1382506115:797319270", "แท่งทอเรียมลงมนตร์" }, [16973] = { "18:375551788:1546544516", "ขวดน้ำจาก Dire Maul" } },
        objectiveLabels = {
            item = { ["Crystal Restore"] = "ผลึกฟื้นฟู", ["Enchanted Thorium Bar"] = "แท่งทอเรียมลงมนตร์", ["Vial of Dire Water"] = "ขวดน้ำจาก Dire Maul" },
        },
    },
    [5248] = { -- Tormented By the Past
        title = { "21:1945039400:1439204436", "อดีตที่ทรมานใจ" },
        objective = { "116:2047537249:545875192", "นำ Crystal of Zin-Malor ไป Lake Kel'Theril ใน Winterspring แล้วหาวิญญาณไฮบอร์นที่ยอมคุยด้วย" },
        description = { "N 282:816689831:3207907 N 206:222634212:448537326", "{name} ข้าร่ำไห้ต่อสิ่งที่เกิดในอดีต เผ่าพันธุ์เอลฟ์แตกสลายเช่นผลึกนี้ ไม่รู้ว่าชิ้นส่วนจะกลับรวมเป็นหนึ่งได้หรือไม่ แต่ความเศร้าบรรเทาลงเมื่อได้ช่วยงานเล็กนี้\n\nเราต้องไม่ลืมอดีต {name}...\n\nโปรดนำ Crystal of Zin-Malor กลับ Lake Kel'Theril หาวิญญาณไฮบอร์นที่ตระหนักถึงความผิดเมื่อนานมาแล้ว แสดงให้เห็นว่าเราแก้ไขให้ถูกต้องอีกครั้ง" },
        progress = { "30:2111435405:1081422542", "ต้องสาป... ชั่วนิรันดร์..." },
        completion = { "28:1749087018:374935101", "ได้โปรด... ปล่อยข้าไว้..." },
    },
    [5264] = { -- Lord Maxwell Tyrosus
        title = { "20:1172272967:1478952035", "Lord Maxwell Tyrosus" },
        objective = { "57:1671673700:553629765", "คุยกับ Lord Maxwell Tyrosus เขาอยู่ในโบสถ์" },
        description = { "45:1092675866:1662937785 N 139:2053306599:470414846", "ข้ากำลังจะมอบเกียรติยิ่งใหญ่แก่เจ้า {name}\n\nLord Maxwell ต้องการให้รางวัลการรับใช้ Argent Dawn!\n\nหลายปีแล้วที่ Maxwell ไม่เปิดให้คนนอกเข้าพบ" },
        completion = { "23:161825400:259535979 N 57:1109945291:33496916", "เจ้าคือพันธมิตรคู่ควร {name} จงรับรางวัลแห่งความทุ่มเทแน่วแน่" },
    },
    [5265] = { -- The Argent Hold
        title = { "15:626219846:2129469845", "หีบ Argent Hold" },
        objective = { "43:1329648256:1223241641", "เปิด Argent Hold แล้วรับรางวัล" },
        description = { "190:1116505135:1770552780 N 1:46:46", "ตลอดหลายปี Argent Hold ปิดล็อก ไม่มีใครคู่ควรจะหยิบพลัง Argent Dawn จากข้างใน จนวันนี้\n\nบัดนี้ Argent Hold เปิดให้เจ้าแล้ว {name}" },
        completion = { "7:114192467:1076567417", "โห..." },
    },
    [5281] = { -- The Restless Souls
        title = { "18:290267522:22652026", "วิญญาณที่ไม่สงบ" },
        objective = { "65:1394291946:1048416574", "ตามหา Egan เจ้ารู้เพียงว่ามีผู้พบเขาครั้งสุดท้ายแถว Stratholme" },
        description = { "281:608240579:1871350794 N 180:558725816:1398485518", "หลายคนตายอย่างน่าเศร้าเมื่อ Stratholme ล่มสลาย หลายคนเลือกจบชีวิต กระโจนสู่เปลวเพลิงทั่วเมืองที่คุกรุ่น แทนกลายเป็น Scourge\n\nบัดนี้เดินตามถนน Stratholme เป็นวิญญาณไม่สงบ\n\nเราต้องช่วย {name}!\n\nข้ามีคนรู้จักชื่อ Egan ผู้สร้างผลงานมหัศจรรย์กับภูตผีและวิญญาณ ตามหาเขา เขาตระเวนใน Eastern Plaguelands ใกล้ Stratholme เพื่อทดสอบสิ่งประดิษฐ์" },
        completion = { "48:1685309727:1677142238", "Alen หาคนกล้าพอได้เสียทีสินะ?" },
    },
    [5464] = { -- Menethil's Gift
        title = { "15:140076803:1879332542", "ของขวัญแห่ง Menethil" },
        objective = { "73:2094977293:246985371", "นำ Soulbound Keepsake ไปให้ Leonid Barthalomew ที่ Eastern Plaguelands" },
        description = { "169:515455320:1325853049", "วิญญาณผู้ล่วงลับยึดเกาะสิ่งแทนชีวิตเดิม เปลี่ยนมันเป็นของที่ระลึกผูกวิญญาณ เจ้าหยิบขึ้นใส่กระเป๋า" },
        progress = { "18:1258545588:299603420", "<Leonid สะท้าน>" },
        completion = { "94:774249994:1652255009", "เช่นเดียวกับที่วิญญาณเกาะของที่ระลึก มันจะเกาะร่างกาย Ras Frostwhisper" },
    },
    [5542] = { -- Demon Dogs
        title = { "10:1232712467:1603309948", "สุนัขปีศาจ" },
        objective = { "123:1198128661:628358892", "สังหาร Plaguehound Runt 20 ตัว, Plaguehound 5 ตัว และ Frenzied Plaguehound 5 ตัว เสร็จแล้วกลับไปหา Tirion Fordring" },
        description = { "286:1672193818:1866293846", "หากจะอยู่ที่นี่ ข้าขอเพียงช่วยทำงานตอบแทน เรามีตัวก่อกวนมากที่ควรถูกสั่งสอน\n\nเริ่มจาก Plaguehound และพวกลูกของมันก็ได้\n\nข้าให้ตอบแทนไม่ได้มาก แต่รับรองว่าเจ้าจะได้อาหารอุ่น ๆ กับเพื่อนคุยเมื่อสำเร็จ" },
        progress = { "28:165404232:1632012546 R 24:785875776:106641906", "อย่าสงสารสุนัขปีศาจ ชาว{race} พวกมันคืออสูรผิดธรรมชาติ!" },
        completion = { "11:534428891:784080240 N 52:2088398456:284701938", "ทำได้ดี {name} มาเถอะ พัก กินแล้วคุยถึงวันวานกัน!" },
    },
    [5543] = { -- Blood Tinged Skies
        title = { "18:1961554140:961620406", "ท้องฟ้าแต้มเลือด" },
        objective = { "49:812487397:230904884", "สังหาร Plaguebat 30 ตัว แล้วกลับไปหา Tirion Fordring" },
        description = { "454:1211334884:1730328075", "วิบัติแก่ผู้โง่เขลาที่เดินหลงเข้า Plaguelands ป่านี้มีความชั่วทุกรูปแบบ ตั้งแต่ Scarlet Crusade ผู้คลั่งที่จะฆ่าทุกคนไร้ตรา Crusade ไปจน Scourge กระหายฆ่าที่หวังเพิ่มอันเดดในกองทัพ\n\nแม้สัตว์ป่าก็กลายเป็นสัตว์ร้ายกินคน ข้าขอให้ทำลายพวกที่โจมตีจากฟ้า Plaguebat" },
        progress = { "40:822310950:379645161 R 51:32173353:1870804330", "อย่าประมาทสัตว์บินรบกวน ชาว{race} โรคระบาดให้พลังเหนือธรรมชาติแก่มัน" },
        completion = { "38:1938943121:1547886736 R 115:1298026662:316327597", "เจ้าเป็นแบบอย่างความดีอันเจิดจ้า ชาว{race}! นานแล้วที่ข้าไม่รู้สึกถึงเลือดวีรชนสูบฉีดในกาย ความกล้าของเจ้าชุบชูใจ!" },
        objectiveLabels = {
            monster = { ["Plaguebat slain"] = "ปราบ ค้างคาวโรคระบาด" },
        },
    },
    [5544] = { -- Carrion Grubbage
        title = { "16:1206472574:1537961401", "อาหารจากหนอนซากศพ" },
        objective = { "169:1027184613:27566942", "ตามหา Carrion Grub และ Carrion Devourer ในแถบนี้ สังหารแล้วเก็บเนื้อ เมื่อได้ Slab of Carrion Worm Meat 15 ชิ้น กลับไปหา Tirion Fordring" },
        description = { "34:1398585726:1477699487 R 389:1710412904:2089891274", "เสบียงข้าใกล้หมด ชาว{race} ข้าอายที่ต้องยอมรับว่าอาจมีไม่พอแบ่งให้เจ้า\n\nช่วยคนแก่ทำงานง่าย ๆ ได้ไหม? แถวนี้มีเพียงหนอนกินซากที่ไม่ได้รับผลจากโรคระบาด แม้รสจืด แต่เนื้อเก็บรักษาให้กินได้หลายเดือน ข้าต้องใช้หลายร้อยปอนด์เพื่อเติมเสบียงรับฤดูหนาว!" },
        progress = { "37:1371950895:307195102 R 1:46:46", "เจ้าจะค่อย ๆ ทนรสได้เอง ชาว{race}" },
        completion = { "51:1150541482:514364241", "ขอแสงสว่างคุ้มครอง! ขอพรจงมีแด่เจ้าผู้เยาว์วัย" },
        required = { [13853] = { "25:1152897209:1892017472", "เนื้อหนอนกินซากชิ้นใหญ่" } },
        objectiveLabels = {
            item = { ["Slab of Carrion Worm Meat"] = "เนื้อหนอนกินซากชิ้นใหญ่" },
        },
    },
    [5601] = { -- Sister Pamela
        title = { "13:696970524:1352180857", "น้องสาว Pamela" },
        objective = { "35:19310542:1520906872", "ตามหา Pamela Redpath ที่ Darrowshire" },
        description = { "491:764179325:279936920", "ข้าหนี Lordaeron ระหว่างมหาสงคราม โชคดีที่ออกทันก่อน Scourge กวาดบ้านเกิดให้เป็นฝันร้ายแห่งโรคระบาด! ข้าโชคดี แต่ครอบครัวไม่ ข้ากลัวว่าทุกคนตายในศึก Darrowshire\n\nDarrowshire เป็นหมู่บ้านใน Eastern Kingdoms อยู่ท่ามกลางเนินทางใต้ของดินแดนที่บัดนี้คือ Eastern Plaguelands ช่วยไปหาครอบครัวให้ที ข้าคิดถึงมาก โดยเฉพาะน้องสาวตัวน้อย Pamela\n\nได้โปรด หานางให้ข้า!" },
        completion = { "462:203516159:459388777", "พี่ Jessica อยู่ไหน? พี่ไปนานแล้ว ตั้งแต่หนูยังตัวเล็ก พี่ร้องไห้มากตอนไป หนูไม่รู้ว่าทำไม! บางทีพี่อาจหกล้มนิ้วเท้ากระแทก\n\nตอน Jessica อยู่ เราเล่นเกม เต้นรำ และเก็บดอกไม้สวยรอบบ้าน บางครั้งเห็นพ่อกลับมาก็ซ่อน แล้วกระโดดออกให้พ่อตกใจ!\n\nกลับมานะ Jessica! ถ้าพี่กลับ บางทีพ่อก็จะกลับ แล้วเราจะได้เล่นด้วยกันอีก..." },
    },
    [5721] = { -- The Battle of Darrowshire
        title = { "25:1822711861:506746826", "ศึกแห่ง Darrowshire" },
        objective = { "324:1353088608:1290636204", "วาง Relic Bundle ที่ลานกลางเมือง Darrowshire\n\nรักษาชีวิต Davil Lightfire จน Horgus ตาย\n\nรักษาชีวิต Captain Redpath จน Redpath the Corrupted ปรากฏ\n\nปราบ Redpath the Corrupted\n\nคุยกับวิญญาณ Joseph Redpath เมื่อเขาปรากฏที่ลานกลางเมือง แล้วคุยกับ Pamela ที่บ้านนาง" },
        description = { "5:714842399:1747743604 N 464:1013512579:217863345", "บัดนี้ {name} เจ้าจะร่วมศึก Darrowshire และช่วย Joseph Redpath\n\nวางห่อวัตถุที่ลานกลางเมือง แล้ววิญญาณ Darrowshire จะปรากฏ เข้าร่วมรบและทำให้สองเงื่อนไขสำเร็จ: Davil ต้องรอดจนหลัง Horgus ตาย และ Redpath ต้องรอดจนถูกครอบงำ แล้วจึงถูกปราบ\n\nเมื่อปราบ Redpath ที่ถูกครอบงำ วิญญาณเขาจะรอด คุยกับเขาแล้วกลับไปหา Pamela ลูกสาว" },
        progress = { "66:420450814:74603319", "หนูว่าได้ยินผีข้างนอก พวกเขากระซิบเรื่องน่ากลัว..." },
        completion = { "234:2143507293:1687944882", "สู้กันจบแล้ว! หนูได้ยินพ่อกระซิบ พ่อไล่ผีหมดแล้วบอกว่าจะกลับบ้าน! หนูดีใจมาก!\n\nพ่อยังบอกให้ต้อนรับเธอถ้ามาที่บ้าน หนูเลยชงชาไว้!\n\nหวังว่าเธอชอบน้ำตาลเยอะ ๆ นะ!" },
    },
    [5742] = { -- Redemption
        title = { "10:774542926:1655799250", "การไถ่คืนเกียรติ" },
        objective = { "42:1067689384:960988722", "ฟังสิ่งที่ Tirion Fordring จะเล่า" },
        description = { "94:1179463771:663288158", "เจ้าทำงานหนักแล้ว สหาย พักกายที่เหนื่อยล้า ให้ข้าแนะนำตัวอย่างเหมาะสม" },
        progress = { "37:908724331:118070507", "ได้โปรด สหาย นั่งฟังเรื่องข้า" },
        completion = { "67:853045872:798942933", "การกู้เกียรติตระกูล Fordring จะยากลำบาก เจ้าพร้อมหรือไม่?" },
    },
    [5781] = { -- Of Forgotten Memories
        title = { "21:246352288:1270790444", "ว่าด้วยความทรงจำที่ถูกลืม" },
        objective = { "173:324975989:531770022", "เดินทางไป Undercroft ทางใต้สุดของ Eastern Plaguelands เพื่อนำ Taelan's Hammer กลับมา เสร็จแล้วกลับไปหา Tirion Fordring" },
        description = { "484:63959962:1156169010", "เพื่อช่วย Taelan ทวงคืนสิ่งที่เสียไป เจ้าต้องรวบรวมของจากอดีตเขา\n\nชิ้นแรกคือของเล่นที่ข้าให้วันเกิดครบ 7 ปี ของรักที่สุดของเขา ค้อนศึกจิ๋วจำลองของข้าทุกประการ\n\nหลังข้าถูกเนรเทศข้อหาทรยศ แม่บอกเขาว่าข้าตายแล้ว พาไปหลุมศพปลอมที่ Undercroft เขาฝังค้อนพร้อมความทรงจำถึงข้าไว้ตลอดกาล\n\nเจ้าต้องไป Undercroft แล้วนำค้อน Taelan กลับมา" },
        progress = { "20:963310288:1588478482", "เขาต้องได้คืนเกียรติ" },
        completion = { "65:89079631:1305758456 N 41:1520099601:214297791", "<Tirion กะพริบตากลั้นน้ำตา>\n\nชะตานำเรามาพบ {name} ความเมตตาของเจ้าคือพรแก่ข้า" },
        required = { [14613] = { "15:1326417603:1420488030", "ค้อนของ Taelan" } },
        objectiveLabels = {
            item = { ["Taelan's Hammer"] = "ค้อนของ Taelan" },
        },
    },
    [5845] = { -- Of Lost Honor
        title = { "13:1294318744:1320051125", "ว่าด้วยเกียรติที่สูญหาย" },
        objective = { "174:1722004457:266012224", "เดินทางไป Northdale ทางตะวันออกเฉียงเหนือของ Eastern Plaguelands เพื่อนำ Symbol of Lost Honor กลับมา เสร็จแล้วกลับไปหา Tirion Fordring" },
        description = { "486:1813518059:1998564642", "Order of the Silver Hand ถูกทำลายยับเยินเมื่อ Uther ถูกสังหาร\n\nลูกข้ายืนหยัดนานที่สุดเท่าที่ทำได้ ถูกต้อนถึงหมู่บ้าน Northdale ที่ยับเยินจากสงคราม และสู้เป็นครั้งสุดท้ายที่นั่น\n\nเขาคิดว่ายังมีใครในคณะรอดหรือไม่ และมันสำคัญอีกหรือ?\n\nด้วยความคิดนั้น Taelan โยนธงคณะลง ละทิ้งทุกสิ่งที่เคยรู้ เกียรติเขาถูกทิ้งบนผืนดินชุ่มเลือดของ Northdale\n\nเจ้าต้องไป Northdale แล้วนำสัญลักษณ์เกียรติที่สูญหายกลับมา" },
        progress = { "25:811765534:42273138 N 28:2053538896:1241033500", "ศรัทธาข้าจะนำทาง {name} แสงสว่างไร้ขอบเขต" },
        completion = { "161:492076616:473811214", "แม้ขาดรุ่งริ่ง ก็ยังรุ่งโรจน์เช่นวันที่ข้าเห็นมันและกล่าวสัตย์ภักดี\n\nการคืนเกียรติเขาใกล้เข้ามา บางทีของข้าก็ด้วย..." },
        required = { [14625] = { "20:518223561:915866367", "สัญลักษณ์แห่งเกียรติที่สูญหาย" } },
        objectiveLabels = {
            item = { ["Symbol of Lost Honor"] = "สัญลักษณ์แห่งเกียรติที่สูญหาย" },
        },
    },
    [5846] = { -- Of Love and Family
        title = { "18:1233142555:731539431", "ว่าด้วยรักและครอบครัว" },
        objective = { "142:196568337:762387109", "เดินทางไปเกาะ Caer Darrow ทางตอนกลางค่อนไปใต้ของ Plaguelands แล้วหาเบาะแสที่อยู่ของภาพวาด" },
        description = { "502:1387013912:738722805", "เมื่อ Taelan เป็นเด็ก เรามักเที่ยว Caer Darrow ทั้งครอบครัว ครั้งสุดท้ายศิลปินชื่อ Renfray วาดภาพเรายืนริมชายหาด เป็นความทรงจำที่ข้ารักที่สุดถึง Taelan กับ Karandra เพราะช่วงนั้น เมื่อกอดภรรยาและลูก ข้ารู้สึกถึงสายใยรักและครอบครัวที่ไม่ได้สัมผัสอีกเลย\n\nหากภาพยังอยู่ เจ้าต้องหาให้พบ\n\nไปเกาะ Caer Darrow ที่พังทลาย ดูว่าภาพหรือศิลปินยังอยู่หรือไม่" },
        completion = { "322:236903204:266542823", "ข้าจะลืมได้อย่างไร? วิญญาณมากมายบนเกาะนี้ถูกสาปให้ย้อนอยู่ในความทรงจำสุขครั้งสุดท้ายก่อนพบจุดจบน่าเศร้า\n\nข้าก็ถูกสาป แต่ต่างจากพวกเขา ข้าเป็นคนส่วนน้อยที่จำได้ทั้งหมด...\n\nบางทีสิ่งที่เจ้าถามคือเหตุที่ข้าหลอกหลอนซากนี้ บางทีคำตอบที่บอกอาจปลดปล่อยข้า" },
    },
    [5941] = { -- Return to Chromie
        title = { "17:701024575:1728522534", "กลับไปหา Chromie" },
        objective = { "49:900861130:1743127819", "นำ Bundle of Relics ไปให้ Chromie ที่ Andorhal" },
        description = { "432:730610167:64997800", "เจ้ารวบรวมของจากศึก Darrowshire มากมาย ทุกครั้งที่กลับมาพร้อมของเพิ่ม ใจข้ายิ่งโหยหาหมู่บ้าน... อยากปกป้องจากชะตา\n\nข้ารู้ว่าเป็นไปไม่ได้ แต่ Chromie โนมแปลกใน Andorhal บอกว่าเป็นไปได้ นางบอกว่าเจ้าช่วย Darrowshire ได้!\n\nนางขอให้ข้ารวมของแล้วให้เจ้านำไปให้ นางรอที่โรงแรมปรักหักพังใน Andorhal" },
        progress = { "220:498326667:498538457 N 37:1394266793:869823346", "ข้าติดต่อกับ Carlin สหายเจ้า เขาเจ็บปวดต่อชะตาหมู่บ้านมาก แต่ชื่นชมเจ้าอย่างยิ่งและรู้ว่าเจ้าแก้ทุกอย่างได้\n\nอ้อ ข้านอกเรื่องแล้ว... {name} มีของที่ขอหรือยัง?" },
        completion = { "178:778904270:2062063329", "อา ใช่ ครบแล้ว เมื่อรวมกันจะทอเป็นเวททรงพลังที่ปลุกวิญญาณ Darrowshire\n\nด้วยเวทนั้นและโชคอีกนิด เราจะช่วย Joseph Redpath ได้!" },
    },
    [5942] = { -- Hidden Treasures
        title = { "16:1196073582:1151363344", "สมบัติที่ซ่อนอยู่" },
        objective = { "37:174894060:197342849", "นำ Joseph's Key ไปที่ Joseph's Chest" },
        description = { { "219:2006383649:1754764028 N 36:420390132:287043541", "219:2006383649:1754764028 N 37:597940626:800822208" }, "พ่อบอกให้มอบกุญแจนี้ให้เธอ มันเปิดหีบข้างหลังบ้านได้\n\nพ่อยังให้ขอบคุณด้วย เธอช่วยพ่อหรือ? บอกพ่อหรือยังว่าหาตุ๊กตาหนูเจอ?\n\nนี่กุญแจ ขอบคุณนะ {name} ขอบคุณ! เธอเป็นคนใจดีมาก!" },
        progress = { "39:607613763:671249979", "หีบนี้เก่าและเต็มคราบสกปรก" },
        completion = { "45:1475273799:1338873160", "กุญแจเข้ากับแม่กุญแจ หีบเปิดออก..." },
    },
    [6021] = { -- Zaeldarr the Outcast
        title = { "20:215035588:104870629", "Zaeldarr ผู้ถูกขับไล่" },
        objective = { "63:387941547:1677273140", "นำ Zaeldarr's Head ไปให้ Caretaker Alen ที่ Light's Hope Chapel" },
        description = { "453:1808684437:1703934833 N 36:1512431644:1977998199", "เชื่อไหม หลังปัญหาสารพัดใน Plaguelands เรายังต้องห่วงขโมย? ไม่ใช่ขโมยธรรมดา แต่ขโมยโทรล\n\nและไม่ใช่โทรลธรรมดา โทรลตายแล้ว!\n\nหัวหน้าคือโทรลตายตัวใหญ่ชื่อ Zaeldarr the Outcast กลางคืนพวกมันมาขโมยศพจากหลุมข้างล่าง แล้วนำกลับรังโทรลตายชั่วร้าย Undercroft ทางตะวันตก\n\nไปกำจัด Zaeldarr {name} ข้าเบื่อการก่อกวนแทบตาย!" },
        progress = { "26:703911762:641489074 N 32:2090538239:1868865579", "พบรังหรือยัง {name}? จัดการ Zaeldarr แล้วหรือ?" },
        completion = { "64:1313060995:430392149", "เยี่ยม เจ้าจัดการมันแล้ว! หวังว่าจะสั่งสอนพรรคพวกด้วย!" },
        required = { [15785] = { "15:687580749:1032948439", "ศีรษะของ Zaeldarr" } },
        objectiveLabels = {
            item = { ["Zaeldarr's Head"] = "ศีรษะของ Zaeldarr" },
        },
    },
    [6022] = { -- To Kill With Purpose
        title = { "20:1877993792:1631658414", "ฆ่าอย่างมีจุดหมาย" },
        objective = { "210:177511563:672222324", "เดินทางไป Corin's Crossing ทางตะวันออก สังหาร Scourge ในเมือง เก็บ Living Rot 7 ชิ้นภายในเวลาไม่ถึง 10 นาที ใช้ Mortar and Pestle บด Living Rot ให้เป็น Coagulated Rot" },
        description = { "499:1795095801:1818453230", "ระหว่างอยู่ไร่ข้า เจ้าต้องฆ่าอย่างมีจุดหมาย\n\nงานแรกคือหาอาหารให้สุนัขข้า\n\nนำครกกับสากนี้ไป Corin's Crossing ที่นั่นมี Scourge มากให้ฆ่า ข้าต้องการ Living Rot จากซากสด บดมันในครกแล้วปล่อยให้จับตัว นำ Coagulated Rot กลับมา\n\nแล้วก็ เจ้าโง่ จำไว้ว่า Living Rot จากอันเดดไม่ได้มีชีวิตอยู่นาน เจ้าต้องฆ่าให้เร็ว!" },
        progress = { "204:1943201476:1626407795", "ร้องไห้หรือ? หากงานน่าเบื่อนี้เกินรับไหว เจ้าผู้เป็นวีรชน ข้าแนะนำให้กลับหา Dark Lady แล้วรายงานความทารุณสยดสยองที่เจ้าได้รับในไร่ข้า\n\nไปให้พ้นหน้าได้แล้ว!" },
        completion = { "138:483949242:1434234432", "น่าผิดหวัง ข้าหวังว่าจะได้เอาเจ้าให้สุนัขกินเสียอีก\n\n<Nathanos ถอนหายใจ>\n\nอย่างน้อยพวกมันก็มีอะไรกิน" },
        required = { [15448] = { "14:1921962326:721206829", "ซากเน่าที่จับตัวเป็นก้อน" } },
        objectiveLabels = {
            item = { ["Coagulated Rot"] = "ซากเน่าที่จับตัวเป็นก้อน" },
        },
    },
    [6024] = { -- Hameya's Plea
        title = { "13:2090953461:2105754605", "คำวิงวอนของ Hameya" },
        objective = { "80:392086681:192360991", "สังหาร Infiltrator Hameya แล้วใช้กุญแจของเขากับ Mound of Dirt หลัง Undercroft" },
        description = { "483:1689815002:1048794791", "ฆ่าข้า ก่อนสายเกินไป\n\nข้าคือ Hameya ระหว่างไป Zul'Mashar ข้ากับพี่น้องกินเนื้อเสีย... แล้วเปลี่ยนไป เราติดเชื้อ\n\nตอนนี้สัมผัสคำของลิชที่เร่งให้ข้าไป Zul'Mashar เพื่อแพร่เชื้อแก่คนของข้าเพิ่ม ต้านไม่ได้ จึงเขียนม้วนนี้ก่อนสูญเจตจำนง\n\nข้าฝังหีบข้างเกวียนหลังสุสานนี้ มีเพียงกุญแจข้าที่เปิดได้ กุญแจอยู่กับตัว หากอยากได้สมบัติ จงหาข้า\n\nฆ่าข้า ก่อนสายเกินไป" },
        progress = { "42:877925153:1725386003", "หีบที่ฝังอยู่นี้ล็อกแน่น" },
        completion = { "26:1025392128:2101871048", "หีบ Hameya เปิดแล้ว!!" },
        required = { [15767] = { "12:1328046846:1163498096", "กุญแจของ Hameya" } },
        objectiveLabels = {
            item = { ["Hameya's Key"] = "กุญแจของ Hameya" },
        },
    },
    [6026] = { -- That's Asking A Lot
        title = { "19:612712675:871697500", "ขอมากไปหน่อยแล้ว" },
        objective = { "174:77882356:2080904481", "Smokey LaRue ต้องการ Thorium Bar 2 แท่ง, Golden Rod 1 แท่ง, Hi-Explosive Bomb 8 ลูก และ Unstable Trigger 8 ชิ้น\n\nเจ้าต้องหาช่างตีเหล็กกับวิศวกรเพื่อให้ได้ของเหล่านี้" },
        description = { "501:519906932:103269495", "พวก Argent Dawn จ้าง Smokey คนนี้มารื้อทำลายเล็กน้อย แม่ไม่ได้เลี้ยง Smokey ให้โง่ เมื่อเหรียญทองวางบนโต๊ะ Smokey ก็พร้อมรับงาน นั่นคติข้า!\n\nข้ายอมแบ่งค่าจ้าง หากเจ้าช่วยวิ่งงาน ข้อตกลงคือข้าจะไป Plaguewood ทำเครื่องหมายอาคารที่ต้องพัง เจ้ารวบรวมส่วนประกอบระเบิด มีครบแล้วพบกันที่นี่ ตกลงไหม?" },
        progress = { "18:212245035:893399934 R 97:2016229904:1915310334", "เชื่อ Smokey เถอะ ชาว{race} รางวัลคุ้มค่า Argent Dawn พวกนี้ไม่เล่นตลกเรื่องค่าจ้าง" },
        completion = { "58:1177752637:1634143957", "ข้าจ่ายล่วงหน้าได้ครึ่งหนึ่ง อีกครึ่งเมื่องานเสร็จ" },
        required = { [12359] = { "11:2096858940:1132233669", "แท่งทอเรียม" }, [11128] = { "10:742386124:390333358", "คทาทองคำ" }, [10562] = { "17:482905871:1645677927", "ระเบิดแรงสูง" }, [10560] = { "16:76992451:1847837549", "ตัวจุดชนวนไม่เสถียร" } },
        objectiveLabels = {
            item = { ["Thorium Bar"] = "แท่งทอเรียม", ["Golden Rod"] = "คทาทองคำ", ["Hi-Explosive Bomb"] = "ระเบิดแรงสูง", ["Unstable Trigger"] = "ตัวจุดชนวนไม่เสถียร" },
        },
    },
    [6041] = { -- When Smokey Sings, I Get Violent
        title = { "32:451812480:808357671", "เมื่อ Smokey ร้องเพลง ข้าก็พร้อมถล่ม" },
        objective = { "360:943540671:85737081", "ไป Plaguewood ทางตะวันตกเฉียงเหนือของ Light's Hope ทำลายสิ่งปลูกสร้าง Scourge 8 หลัง โดยใช้ Smokey's Special Compound ที่ Mark of Detonation ภายในแต่ละหลัง Smokey ทำเครื่องหมาย Ziggurat กับ Slaughterhouse ไว้แล้ว\n\nวางระเบิดแล้วออกจากอาคาร มองผลงานของเจ้าได้เลย\n\nอีกอย่าง Smokey's Special Compound ค่อนข้าง... ไม่เสถียร" },
        description = { "375:1780351667:1361530069", "ระหว่างเจ้าเก็บของ ข้าให้คนไปทำเครื่องหมายอาคาร Scourge ที่ต้องพังแล้ว\n\nแผนคือข้าจะให้สารผสมพิเศษสิบแท่ง เจ้านำไป Plaguewood วางในสิ่งปลูกสร้าง Scourge ที่ข้าทำเครื่องหมายระเบิดไว้\n\n<Smokey ดีดนิ้ว>\n\nปิ๊ง! ง่ายเท่านี้เอง" },
        progress = { "118:2026407246:1708342886", "ข้ามีของเหลือทำสารผสมพิเศษเพิ่มอีกไม่กี่แท่ง ต้องการเพิ่มก็บอก Smokey คนนี้" },
        completion = { "254:1959399382:1273658320", "เจ้าดำกว่าที่ข้าจำได้มาก ได้ลุคใหม่เลย ลุคที่บอกว่า ข้าโดนระเบิดแรงสูงเผามา\n\n<Smokey หัวเราะ>\n\nเอาเถอะ! นี่ส่วนแบ่ง ข้าเพิ่มของเล็กน้อยช่วยปลอบแผลไหม้ให้ด้วย" },
    },
    [6042] = { -- Un-Life's Little Annoyances
        title = { "27:1889767995:453408221", "เรื่องกวนใจเล็ก ๆ ของชีวิตหลังตาย" },
        objective = { "110:42795883:1144168302", "สังหาร Noxious Plaguebat 20 ตัว และ Monstrous Plaguebat 10 ตัว เสร็จแล้วกลับไปหา Nathanos Blightcaller" },
        description = { "491:1668979344:43321202", "ออกจากไร่ไม่ถึงสองก้าวก็เจอค้างคาวน่ารำคาญ ข้าอยากพาสุนัขออกฆ่า Scourge โดยไม่ถูกค้างคาวสกปรกบัดซบรบกวน เห็นชัดว่าข้ามีงานดีกว่าฆ่าค้างคาวไร้คิดทุกวัน แต่เจ้าไม่มี\n\nอะไรนะ? การฝึกของเจ้าหรือ? นี่แหละการฝึก! ไปให้พ้นหน้า อย่ากลับจนกว่าจะฆ่าปีศาจมีปีกพวกนั้นได้มากพอ อย่าทำให้ผิดหวัง" },
        progress = { "159:1544470970:625943647", "แย่กว่านี้ก็ได้ ข้าอาจให้เจ้าเก็บมูลค้างคาว\n\n<Nathanos จ้องเจ้าอย่างครุ่นคิด>\n\nอืม... เฮ้! เดี๋ยวก่อน จะไปไหน?" },
        completion = { "66:1199936218:1617425720", "เหลือเชื่อว่าความโกรธและโทสะเพียงนิดทำอะไรได้มากขนาดนี้" },
    },
    [6133] = { -- The Ranger Lord's Behest
        title = { "24:1637715143:1123148162", "บัญชาของ Ranger Lord" },
        objective = { "206:329924656:1754746785", "เดินทางไปชายแดนเหนือของ Eastern Plaguelands เพื่อนำ Quel'Thalas Registry กลับมา ของอยู่ที่ใดสักแห่งใน Quel'Lithien Lodge\n\nเจ้าต้องสังหาร Ranger 8 คน, Pathstrider 8 คน และ Woodsman 8 คนด้วย" },
        description = { "81:1226664404:1060161549 C 274:139294455:2117867105", "ไฮเอลฟ์ที่ Quel'Lithien Lodge มีของของข้า {class} เอกสารรายละเอียดชีวิตเมื่อยังเป็นผู้มีอายุขัย\n\nก่อนจะถาม ไม่ เจ้าไม่มีสิทธิ์รู้เรื่องนั้นแน่นอน ทำตามที่บอก เจ้าหนอน เอาทะเบียนกลับมา\n\nแล้วก็ เจ้าโง่ จงทิ้งความทุกข์และขัดแย้งไว้ให้มากที่สุด ปล่อยให้พวกมันทรมาน..." },
        progress = { "25:1538263962:284100049 C 1:46:46", "อย่าให้ข้ารอ {class}" },
        completion = { "86:121546539:2134082807", "ข้าเชื่อว่าเจ้าไม่ได้อ่านทะเบียน แม้แต่เจ้าก็คงไม่ทำเรื่องโง่เช่นนั้น..." },
        required = { [15847] = { "20:664406372:497877979", "ทะเบียนแห่ง Quel'Thalas" } },
        objectiveLabels = {
            item = { ["Quel'Thalas Registry"] = "ทะเบียนแห่ง Quel'Thalas" },
        },
    },
    [6135] = { -- Duskwing, Oh How I Hate Thee...
        title = { "31:94256136:1294841104", "Duskwing ข้าเกลียดเจ้าเหลือเกิน..." },
        objective = { "195:154196754:236100673", "ตามหาและสังหาร Duskwing เก็บ Patch of Duskwing's Fur จากศพกลับไปให้ Nathanos Blightcaller\n\nเล่ากันว่า Duskwing ตระเวนในชนบททางเหนือของ Marris Stead" },
        description = { "414:300328960:981362094", "จนถึงตอนนี้เจ้าทำภารกิจที่ข้ามอบหมายสำเร็จ แม้ไม่รวดเร็วนัก\n\nข้าเดาว่าเจ้าคิดว่าพร้อมรับความท้าทาย ใช่... ใช่ เจ้าโง่ บางทีเจ้าพร้อมทำงานซับซ้อนขึ้นแล้ว\n\nค้างคาวปีศาจเผือก Duskwing ตระเวนทางเหนือจากที่นี่ ตามรอยแล้วทำลายมัน นำขนสีขาวชิ้นหนึ่งกลับมาแล้วจะได้รางวัล" },
        progress = { "61:79221603:830516878 C 1:46:46", "ข้าไม่แนะนำให้รับความท้าทายนี้คนเดียว {class}" },
        completion = { "78:1931441224:1650105154", "ทำได้ยอดเยี่ยม เจ้าโง่ ข้าจะทำขนนี้เป็นของให้เจ้าใช้" },
        required = { [15850] = { "23:1119185856:1182405567", "กระจุกขนของ Duskwing" } },
        objectiveLabels = {
            item = { ["Patch of Duskwing's Fur"] = "กระจุกขนของ Duskwing" },
        },
    },
    [6136] = { -- The Corpulent One
        title = { "17:886867213:20838157", "อสูรพุงพลุ้ย" },
        objective = { "139:259643775:1477799137", "ตามหาและทำลาย Borelgore ในแดนรกร้างทางเหนือของ Eastern Plaguelands ภารกิจเสร็จแล้วกลับไปหา Nathanos Blightcaller" },
        description = { "499:1320298964:945497056", "เลยค่าย Argent Dawn ที่ Light's Hope ไป ทางตะวันตกของ Northdale เจ้าจะพบอสูรหนอนพุงพลุ้ย Borelgore\n\nข้าเสียทหารทั้งกองให้มัน ขนาดมันไร้ขอบเขต! ยิ่งกินก็ยิ่งอ้วน...\n\nแม้ข้าไม่เสียใจหากมันกินเจ้า แต่ก็อยากให้เจ้าชนะ แนะนำให้ขอคนอื่นช่วยงานนี้ เคยมีข่าวว่า Borelgore กลืนกองทหารเล็กที่โง่พอโจมตีมันทั้งกอง" },
        progress = { "39:238098533:1329442245", "ช่วงนี้ข้าบอกหรือยังว่าเกลียดเจ้า?" },
        completion = { "90:858787881:697627530", "ทำเช่นนี้ต่อไป ข้าอาจต้องเลื่อนตำแหน่งเจ้าจากคนโง่เป็นผู้สมองบกพร่องชั้นหนึ่ง" },
    },
    [6144] = { -- The Call to Command
        title = { "19:1845211813:1015592701", "คำเรียกจากผู้บัญชาการ" },
        objective = { "51:608302159:632347946", "เดินทางไป Undercity แล้วคุยกับ Varimathras" },
        description = { "25:267816334:1195346579 C 383:1129514230:532571703 C 1:33:33", "คำสั่งมาแล้ว {class} Varimathras ขอเองให้ส่งสายลับที่มีความสามารถที่สุดกลับ Undercity เพื่อปฏิบัติการยุทธวิธีอ่อนไหวอย่างยิ่ง\n\nโชคร้าย สายลับเก่งที่สุดของข้าถูกฆ่าเกินสามปีก่อน ที่เหลือเป็นแค่พวกกระจอกสมองตาย\n\n<Nathanos มองเจ้าเย็นชา>\n\nไป Undercity ทันทีแล้วรายงาน Varimathras อย่าทำให้ข้าอาย {class}!" },
        completion = { "291:1316688713:1366689336", "Grand Crusader นั่งปลอดภัยใน Scarlet Bastion ขณะกองกำลังทะลักเข้าดินแดนเจ้า ลบหลู่สิ่งปลูกสร้างกับอนุสรณ์ และฆ่าคนของเจ้า\n\nDark Lady สั่งให้ข้าจัดการแมลงตัวนี้ให้สิ้นซาก เจ้าจะเป็นเครื่องมือชำระแค้นของ Forsaken" },
    },
    [6145] = { -- The Crimson Courier
        title = { "19:1401617752:1628491230", "ผู้ส่งสาร Crimson Courier" },
        objective = { "191:119286144:1825795829", "กลับ Eastern Plaguelands ตามหาและสังหาร Crimson Courier เพื่อนำ Grand Crusader's Command กลับมา\n\nนำคำสั่งไปให้ Nathanos Blightcaller เพื่อรับคำแนะนำต่อ" },
        description = { "427:1583764517:1937252871 R 74:1058530417:2069856948", "เช่นเดียวกับร่างอยู่ไม่ได้โดยไร้ศีรษะ ศีรษะก็อยู่ไม่ได้โดยไร้ร่าง แนวป้องกันกองบัญชาการ Scarlet Crusade ใน Stratholme แทบฝ่าไม่ได้ เราจึงต้องตัดร่างออกจากศีรษะแทน\n\nDeathstalker ของข้าเก็บข้อมูลกิจกรรม Crusade นอก Stratholme ทุกวันมีรายงานจากบัญชาการกลางถึง Tyr's Hand รายงานนั้นคือกุญแจ ชาว{race}! หา Crimson Courier เอารายงานกลับไปให้ Nathanos" },
        progress = { "56:1115128338:1879628645 C 1:46:46", "สำเร็จคราวนี้ เจ้าจะเกือบได้รับความเคารพจากข้าแล้ว {class}" },
        completion = { "84:162544717:546574500", "<Nathanos หัวเราะ>\n\nยอดเยี่ยม! ในที่สุด! โอกาสทำลาย Scarlet Oracle!" },
        required = { [15868] = { "28:1647854087:1090050534", "คำสั่งของมหาครูเสด" } },
        objectiveLabels = {
            item = { ["The Grand Crusader's Command"] = "คำสั่งของมหาครูเสด" },
        },
    },
    [6146] = { -- Nathanos' Ruse
        title = { "14:1511879699:652175697", "กลลวงของ Nathanos" },
        objective = { "208:1115640332:1010254176", "เดินทางไป Tyr's Hand ทางตะวันออกเฉียงใต้ของ Marris Stead เมื่อถึงให้กัด Rotten Apple ขณะปลอมเป็น Scarlet Crusade ให้นำ Grand Crusader's Command ไปส่ง Crusader Lord Valdelmar" },
        description = { "151:377005180:1931380931 C 342:1345433002:295678267", "ข้าแก้คำสั่งนี้เล็กน้อย หากกลลวงได้ผล พวกมันจะเผยตัว Scarlet Oracle แล้วเราจะโจมตี!\n\nตั้งใจฟัง {class} เจ้าต้องส่งคำสั่งให้ Crusader Lord Valdelmar\n\nอย่างไรหรือ? ยื่นให้เขา เจ้าโง่\n\nนำคำสั่งกับแอปเปิลเน่านี้ไป Tyr's Hand เมื่อเข้าเมือง ให้กินแอปเปิล เจ้าจะเปลี่ยนเป็นสิ่งที่มนุษย์ยอมรับได้มากกว่า นำคำสั่งยื่นให้ Crusader Lord Valdelmar" },
        progress = { "30:1279337710:3700438", "ยอมรับไม่ได้ ทหาร!" },
        completion = { "65:2125192963:427583222", "เจ้าไปไหนมา? เราคิดว่า Scourge จับตัวไปแล้ว" },
        required = { [13852] = { "28:1647854087:1090050534", "คำสั่งของมหาครูเสด" } },
        objectiveLabels = {
            item = { ["The Grand Crusader's Command"] = "คำสั่งของมหาครูเสด" },
        },
    },
    [6147] = { -- Return to Nathanos
        title = { "18:1785236031:1736952673", "กลับไปหา Nathanos" },
        objective = { "57:85964241:1846473675", "กลับไปหา Nathanos Blightcaller พร้อมข้อมูลใหม่" },
        description = { "259:1169322140:1656563521", "Grand Crusader ขอเรื่องผิดปกติ อืม อย่างไรก็ตาม... จะทำตามคำขอ กลับ Scarlet Bastion แจ้งว่าอีกไม่นาน Oracle จะออกเดินทาง\n\nเราจะระวังทุกทางให้นางถึง Stratholme โดยปลอดภัย" },
        completion = { "58:1008332101:1145971734 C 35:1117827771:880746110", "พวกโง่! ไม่รู้ตัวว่าถูกข้าหลอก! เตรียมตัว {class} เราต้องโจมตีด้วยเล่ห์เหลี่ยมเยือกเย็น!" },
    },
    [6148] = { -- The Scarlet Oracle, Demetria
        title = { "28:1245750759:499635528", "Demetria ผู้พยากรณ์ Scarlet" },
        objective = { "225:900606550:1030375219", "Scarlet Crusade กำลังเคลื่อนพล บนถนนจาก Tyr's Hand ไป Stratholme เจ้าจะพบ Oracle Demetria กับผู้ติดตาม ตามล่าและสังหารนาง สำเร็จแล้วกลับไปหา Nathanos Blightcaller" },
        description = { "502:1995741667:1195171049", "Demetria เป็นหัวหน้าที่ปรึกษา Grand Crusader ได้ชื่อ Oracle เพราะประสาทสัมผัสเหนือโลก นางช่วย Crusade ชนะ Scourge หลายครั้ง\n\nแม้กลลวงเผยตัวนางได้ แต่หากมีพลังจิตจริง ย่อมคาดถึงปัญหา เจ้าจะเป็นคนสร้างปัญหานั้น\n\nตามรอย Oracle แล้วกำจัด น่าจะกำลังออกจาก Tyr's Hand ขณะที่เราคุย ทำให้ข้าภูมิใจ เจ้าหนอน" },
        progress = { "21:1209621533:480140575 N 1:63:63", "สถานการณ์เป็นอย่างไร {name}?" },
        completion = { "58:596387784:1132447740 N 59:259242446:63027451", "พวกมันจะเสียหลักจากการโจมตีนี้ไปหลายปี! ทำได้ดี {name}! เจ้าได้ทั้งความเคารพจากข้าและรางวัลนี้" },
    },
    [6164] = { -- Augustus' Receipt Book
        title = { "22:750150693:1460433690", "สมุดใบเสร็จของ Augustus" },
        objective = { "67:1308612557:991141313", "นำ Augustus' Receipt Book ไปให้ Augustus the Touched ที่ Terrordale" },
        description = { "380:1969995294:1944448348", "ข้าพร้อมค้าขาย! เจ้าอยากได้อะไร?\n\nเดี๋ยว... เปิดร้านไม่ได้ถ้าไม่มีสมุดใบเสร็จ จะติดตามของได้อย่างไรถ้าไม่มีมัน?\n\nข้าคงทิ้งไว้สักที่ในเมือง เคยมีห้องที่โรงแรม... หนังสือต้องอยู่ที่นั่น\n\nนำมาให้ข้า ได้โปรด! นำมาแล้วจะเห็น! ข้าจะเปิดร้าน แล้วเจ้าจะเห็นว่าราคาข้าบ้าคลั่ง!" },
        progress = { "66:302076383:627677953", "มีสมุดใบเสร็จหรือยัง? ข้าแทบรอกลับไปค้าขายไม่ไหว!" },
        completion = { "74:1948185215:168275017 N 35:215340049:1846866455", "นี่ไง! โอ้ ข้าลืมว่าเขียนเต็มเพียงนี้!\n\nวันอันรุ่งโรจน์ {name}! มหัศจรรย์! ดีอย่างบ้าคลั่งเลย!" },
        required = { [15884] = { "22:750150693:1460433690", "สมุดใบเสร็จของ Augustus" } },
        objectiveLabels = {
            item = { ["Augustus' Receipt Book"] = "สมุดใบเสร็จของ Augustus" },
        },
    },
    [6185] = { -- The Eastern Plagues
        title = { "19:852319488:63910076", "โรคระบาดแห่งตะวันออก" },
        objective = { "176:96645873:479028619", "สำรวจ Eastern Plaguelands หาเบาะแส Blightcaller และเจ้าหน้าที่ SI:7 ที่หายไป หากพบ SI:7 Insignia ให้นำกลับไปให้ Flint Shadowmore ที่ Chillwind Camp" },
        description = { "71:1659465658:2041039222 N 399:1056066726:1773990989", "อย่างที่บอก งานแรกคือลาดตระเวน ไม่มีอะไรซับซ้อน {name} ไป Eastern Plaguelands หาเบาะแส Blightcaller\n\nมองหาข้อมูลเจ้าหน้าที่ที่หายไป เราต้องถือว่าพวกเขาตายแล้ว หากตาย ย่อมมีศพ... ที่ไหนสักแห่ง\n\n<Flint กลืนน้ำลายอย่างฝืดคอ>\n\nเจ้าหน้าที่ SI:7 ทุกคนพกตรานี้\n\n<Flint แสดงตรา SI:7 ของเขา>\n\nหากพบตราใด นำกลับมาให้ข้า" },
        progress = { "16:1527747440:736822112", "พะ... พบอะไรบ้างไหม??" },
        completion = { "170:1339188573:209245496", "Rutger Fredo Turyen ตาย... หมด...\n\n<Flint กำตราแน่น>\n\nอยู่ที่ไหน? พบข้อมูลอะไรเพิ่มเกี่ยวกับไอ้สารเลว Blightcaller หรือไม่?" },
        required = { [16003] = { "22:75328936:476524621", "ตรา SI:7 ของ Rutger" }, [16001] = { "21:1992259978:1988900856", "ตรา SI:7 ของ Fredo" }, [16002] = { "22:919190510:1696320381", "ตรา SI:7 ของ Turyen" } },
        objectiveLabels = {
            event = { ["The Blightcaller Uncovered"] = "เปิดโปง Blightcaller" },
            item = { ["SI:7 Insignia (Rutger)"] = "ตรา SI:7 ของ Rutger", ["SI:7 Insignia (Fredo)"] = "ตรา SI:7 ของ Fredo", ["SI:7 Insignia (Turyen)"] = "ตรา SI:7 ของ Turyen" },
        },
    },
    [6187] = { -- Order Must Be Restored
        title = { "22:1631487017:1202317331", "ต้องคืนความสงบเรียบร้อย" },
        objective = { "250:784137132:1041960829", "รวบรวมกองทัพเดินทางไป Eastern Plaguelands บุกโจมตี Nathanos Blightcaller เต็มกำลัง รวมทั้งพวกโสโครก Horde ที่พยายามปกป้องมัน\n\nจงระวังตัว <Name> Horde จะปกป้อง Ranger Lord ด้วยชีวิต", variants = { { "182:957976375:729492795 N 62:1042326903:1987339596", "รวบรวมกองทัพเดินทางไป Eastern Plaguelands บุกโจมตี Nathanos Blightcaller เต็มกำลัง รวมทั้งพวกโสโครก Horde ที่พยายามปกป้องมัน\n\nจงระวังตัว {name} Horde จะปกป้อง Ranger Lord ด้วยชีวิต" } } },
        description = { "341:2108750677:1443719803 N 86:309429261:1518843660 N 42:105276281:692235260", "รู้ไหมว่าโลกนี้มี Ranger Lord กี่คน? เคยมี Ranger Lord ที่เป็นมนุษย์กี่คน?\n\nผลงาน Nathanos ไม่เคยมีผู้ใดทำได้ เขาคืออัจฉริยะยุทธวิธี ผู้ทำให้ Alliance ชนะตลอดความขัดแย้งนับสิบปี\n\nแต่บัดนี้... กลายเป็นยอดนักรบ Forsaken\n\nไม่ ยอมไม่ได้ ต้องคืนความสงบเรียบร้อย\n\nรวบรวมกองทัพ {name} กลับ Plaguelands แล้วทำลาย Blightcaller\n\nขอให้โชคดี {name} จริง ๆ เจ้าต้องใช้โชคในศึกนี้" },
        progress = { "47:2110920317:1378330472", "<Highlord Bolvar Fordragon จมในความคิด>" },
        completion = { "63:822857795:458509535 N 137:67484115:1675040314 N 59:568147471:1660776510", "โศกนาฏกรรมชัด ๆ ข้าคิด... เชื่อว่าเผ่าพันธุ์เราถูกสาป {name} ถูกสาปให้เสียนักรบยิ่งใหญ่ที่สุด วีรชนสูงส่งที่สุด นักปราชญ์มีพรสวรรค์ที่สุด\n\nเราติดหนี้เจ้า ข้ารับรอง {name} ไม่ว่า Nathanos Marris อยู่ที่ใด เขากำลังยิ้มให้เจ้า" },
    },
    [8929] = { -- In Search of Anthion
        title = { "20:2138508739:1493150021", "ตามหา Anthion" },
        objective = { "114:1416544318:1461658032", "ใช้ Extra-Dimensional Ghost Revealer ที่ทางเข้า Stratholme แล้วคุยกับวิญญาณ Anthion Harmon" },
        description = { "238:48355200:1571998619", "เอาละ เหลือเพียงลองสิ่งประดิษฐ์ก็อบลิน ได้ยินว่า Anthion ถูกกองทัพอันเดด Stratholme สังหารขณะพยายามเข้าประตู\n\nลองใช้อุปกรณ์ที่นั่น แล้วค้นหาความรู้ที่ Anthion มี" },
        completion = { "99:1354875478:2120265758", "Deliana ให้เจ้าติดต่อข้าหรือ? ข้าจะพยายามช่วยที่สุด แต่ก่อนอื่นต้องขอความช่วยเหลือครั้งใหญ่" },
    },
    [8930] = { -- In Search of Anthion
        title = { "20:2138508739:1493150021", "ตามหา Anthion" },
        objective = { "114:1416544318:1461658032", "ใช้ Extra-Dimensional Ghost Revealer ที่ทางเข้า Stratholme แล้วคุยกับวิญญาณ Anthion Harmon" },
        description = { "11:1598769728:2013240452 N 243:2091681328:444327378", "ดีมาก {name} เหลือเพียงทดสอบสิ่งประดิษฐ์ก็อบลิน ได้ยินว่า Anthion ถูกกองทัพอันเดด Stratholme สังหารขณะพยายามเข้าประตู\n\nลองใช้อุปกรณ์ที่นั่น ดูว่าเจ้าคุยกับคนตายได้จริงหรือไม่!" },
        completion = { "98:1214985769:1159724556", "Mokvar ให้เจ้าติดต่อข้าหรือ? ข้าจะพยายามช่วยที่สุด แต่ก่อนอื่นต้องขอความช่วยเหลือครั้งใหญ่" },
    },
    [8946] = { -- Proof of Life
        title = { "13:938682369:480851919", "หลักฐานว่ายังมีชีวิต" },
        objective = { "62:1981257508:1688580733", "นำ Ysida's Locket ไปให้ Anthion Harmon ที่ Eastern Plaguelands" },
        description = { "274:2022476512:155793241 N 33:1216355359:429415638", "ชะตาโหดร้ายที่สุดที่คนรักข้าตายขณะพยายามช่วย แต่เจ้าบอกว่าคุยกับเขาได้\n\nนำจี้นี้ไปเป็นหลักฐานว่าข้าปลอดภัย เขาต้องไม่ติดค้างในโลกนี้ ใจข้าคงทนไม่ไหว\n\nลาก่อน {name} ข้าจะเป็นหนี้บุญคุณเสมอ" },
        progress = { "22:1576371133:1280491364", "Ysida... นางยังมีชีวิตหรือ?" },
        completion = { "113:424567436:1606549523 N 52:1031076432:1147649753", "จี้นั่น... เจ้าพบนางแล้ว! ในที่สุดข้าพักสงบได้\n\nข้าจะตอบทุกคำถาม {name} แต่รีบเถอะ เวลาในโลกนี้เหลือไม่มาก" },
    },
    [8947] = { -- Anthion's Strange Request
        title = { "25:743014213:189801360", "คำขอประหลาดของ Anthion" },
        objective = { "128:1526439848:782745152", "นำ Dark Iron Bar 3 แท่ง, Enchanted Leather 20 ผืน, Mooncloth 3 ผืน และ Cured Rugged Hide 4 ผืนไปให้ Anthion Harmon ใน Eastern Plaguelands" },
        description = { "497:714356127:1690057018", "เราไม่รู้ความสำคัญเหรียญ Valthalak จึงแบ่งพร้อมของที่ได้มา ส่วนแรกอยู่กับคนแคระ Theldren ข้าพยายามขอคืนแต่ถูกซ้อมเกือบตาย เจ้าต้องใช้กำลังชิงชิ้นส่วน\n\nครั้งสุดท้ายได้ยินว่าเขาเป็นนักสู้สนามประลองให้คนแคระ Dark Iron แต่การให้เขายอมสู้กับเจ้าจะท้าทายพอควร\n\nรวบรวมวัสดุต่อไปนี้ให้ข้า เจ้าต้องใช้มัน" },
        progress = { "42:58905826:812442635 N 1:63:63", "ได้วัสดุที่ขอหรือยัง {name}?" },
        completion = { "77:167524809:1024513932", "ยอดเยี่ยม ข้าจะแปรธาตุให้เหมาะกับสิ่งที่ต้องใช้มากขึ้น" },
        required = { [11371] = { "13:1237098769:521447780", "แท่งเหล็กดำ" }, [12810] = { "17:1761497862:1241989432", "หนังลงมนตร์" }, [14342] = { "9:1533651162:2094570343", "ผ้าแสงจันทร์" }, [15407] = { "17:1544083521:956369053", "หนังหนาฟอกแล้ว" } },
        objectiveLabels = {
            item = { ["Dark Iron Bar"] = "แท่งเหล็กดำ", ["Enchanted Leather"] = "หนังลงมนตร์", ["Mooncloth"] = "ผ้าแสงจันทร์", ["Cured Rugged Hide"] = "หนังหนาฟอกแล้ว" },
        },
    },
    [9121] = { -- The Dread Citadel - Naxxramas
        title = { "29:1302484447:1243204016", "ป้อมปราการสยอง Naxxramas" },
        objective = { "200:748828646:1521129568", "Archmage Angela Dosantos ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการ Arcane Crystal 5 ชิ้น, Nexus Crystal 2 ชิ้น, Righteous Orb 1 ลูก และเงิน 60 เหรียญทอง เจ้าต้องมีชื่อเสียงระดับ Honored กับ Argent Dawn ด้วย" },
        description = { "395:1578365279:196826297 N 110:230157359:65789243", "ลึกใน Plaguewood คือทางเข้าป้อมสยอง Naxxramas ก่อนนี้การเข้าทุกครั้งถูกเวทคุ้มกันบนประตูรูนขัดขวาง จนบัดนี้\n\nเราคิดวิธีเข้าด้วยอาภรณ์อำพรางอาร์เคน จากคาถาเก่า Kirin Tor ที่ข้าปรับเองเล็กน้อย เพราะความทุ่มเทต่อ Dawn ของเจ้ายังไม่มาก {name} ราคาจึงสูง เจ้าปฏิเสธแล้วกลับเมื่อมีชื่อเสียง Revered หรือ Exalted เพื่อรับส่วนลดได้" },
        progress = { "55:1451556485:1017364965", "ยังไม่มีใครเข้า Naxxramas แล้วรอดมาเล่าเรื่อง" },
        completion = { "31:1050155274:872046962 N 135:893206141:1857462247", "เจ้าจะรู้สึกซ่าเล็กน้อย {name} นั่นหมายถึงได้ผล เมื่อเสร็จ เจ้าจะเข้า Naxxramas ได้โดยก้าวขึ้นประตูรูนใน Plaguewood" },
        required = { [12363] = { "14:1218805090:570821046", "ผลึกอาร์เคน" }, [20725] = { "13:108518413:119122757", "ผลึกเน็กซัส" }, [12811] = { "13:245108348:1953668933", "ลูกแก้วแห่งความเที่ยงธรรม" } },
        objectiveLabels = {
            item = { ["Arcane Crystal"] = "ผลึกอาร์เคน", ["Nexus Crystal"] = "ผลึกเน็กซัส", ["Righteous Orb"] = "ลูกแก้วแห่งความเที่ยงธรรม" },
        },
    },
    [9122] = { -- The Dread Citadel - Naxxramas
        title = { "29:1302484447:1243204016", "ป้อมปราการสยอง Naxxramas" },
        objective = { "182:763354521:1492868731", "Archmage Angela Dosantos ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการ Arcane Crystal 2 ชิ้น, Nexus Crystal 1 ชิ้น และเงิน 30 เหรียญทอง เจ้าต้องมีชื่อเสียงระดับ Revered กับ Argent Dawn ด้วย" },
        description = { "493:1912722908:1886467568", "ลึกใน Plaguewood คือทางเข้าป้อมสยอง Naxxramas ก่อนนี้การเข้าทุกครั้งถูกเวทคุ้มกันบนประตูรูนขัดขวาง จนบัดนี้\n\nเราคิดวิธีเข้าด้วยการอำพรางอาร์เคนถาวรแบบหนึ่ง จากคาถาเก่า Kirin Tor ที่ข้าปรับเองเล็กน้อย แต่มันมีต้นทุนสูง เพราะความทุ่มเทต่อ Dawn ของเจ้าน่าชื่นชม เรายินดีออกบางส่วนให้" },
        progress = { "55:1451556485:1017364965", "ยังไม่มีใครเข้า Naxxramas แล้วรอดมาเล่าเรื่อง" },
        completion = { "31:1050155274:872046962 N 135:893206141:1857462247", "เจ้าจะรู้สึกซ่าเล็กน้อย {name} นั่นหมายถึงได้ผล เมื่อเสร็จ เจ้าจะเข้า Naxxramas ได้โดยก้าวขึ้นประตูรูนใน Plaguewood" },
        required = { [12363] = { "14:1218805090:570821046", "ผลึกอาร์เคน" }, [20725] = { "13:108518413:119122757", "ผลึกเน็กซัส" } },
        objectiveLabels = {
            item = { ["Arcane Crystal"] = "ผลึกอาร์เคน", ["Nexus Crystal"] = "ผลึกเน็กซัส" },
        },
    },
    [9123] = { -- The Dread Citadel - Naxxramas
        title = { "29:1302484447:1243204016", "ป้อมปราการสยอง Naxxramas" },
        objective = { "159:471360541:996545378", "Archmage Angela Dosantos ที่ Light's Hope Chapel ใน Eastern Plaguelands จะมอบ Arcane Cloaking ให้โดยไม่คิดค่าใช้จ่าย เจ้าต้องมีชื่อเสียงระดับ Exalted กับ Argent Dawn" },
        description = { "489:459236868:1332933921", "ลึกใน Plaguewood คือทางเข้าป้อมสยอง Naxxramas ก่อนนี้การเข้าทุกครั้งถูกเวทคุ้มกันบนประตูรูนขัดขวาง จนบัดนี้\n\nเราคิดวิธีเข้าด้วยการอำพรางอาร์เคนถาวรแบบหนึ่ง จากคาถาเก่า Kirin Tor ที่ข้าปรับเองเล็กน้อย แม้มีต้นทุนสูง แต่ความทุ่มเทต่อ Dawn ของเจ้าไม่สั่นคลอน! เราจะยกเว้นค่าใช้จ่ายทั้งหมด" },
        progress = { "55:1451556485:1017364965", "ยังไม่มีใครเข้า Naxxramas แล้วรอดมาเล่าเรื่อง" },
        completion = { "31:1050155274:872046962 N 135:893206141:1857462247", "เจ้าจะรู้สึกซ่าเล็กน้อย {name} นั่นหมายถึงได้ผล เมื่อเสร็จ เจ้าจะเข้า Naxxramas ได้โดยก้าวขึ้นประตูรูนใน Plaguewood" },
    },
    [9124] = { -- Cryptstalker Armor Doesn't Make Itself...
        title = { "41:1851228691:1017188006", "เกราะ Cryptstalker ไม่ได้สร้างตัวเอง..." },
        objective = { "94:584733414:1320317499", "Huntsman Leopold ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการ Crypt Fiend Parts 30 ชิ้น" },
        description = { "175:1049532748:1349437843 N 297:1905900019:1770591031", "อยากได้เหรียญเงาวับอย่างนี้สักเหรียญไหม?\n\n<Leopold ยก Insignia of the Crusade>\n\nข้ามีปัญหาเล็กที่เจ้าอาจช่วยได้ {name} ข้าทำเกราะ Cryptstalker ให้คนบ้าพอเข้า Naxxramas แม้พวกเขาจัดวัสดุหลักมาให้ ข้ากลับขาดชิ้นส่วน Crypt Fiend เสมอ นำมาหนึ่งชุดแล้วข้าจะจ่ายด้วยตราที่ใช้กับเจ้าหน้าที่เสบียงได้" },
        progress = { "18:754312450:778203395", "การล่าเป็นอย่างไร?" },
        completion = { "23:2008387541:1617484252 N 109:2146364321:1711591116", "อา ใช้ได้ดี {name} จำไว้ว่าข้ารับชิ้นส่วนเพิ่มเสมอ ทุกชุดที่นำมาจะได้ตราเป็นรางวัล" },
        required = { [22525] = { "17:533065086:933845475", "ชิ้นส่วนอสูรสุสาน" } },
        objectiveLabels = {
            item = { ["Crypt Fiend Parts"] = "ชิ้นส่วนอสูรสุสาน" },
        },
    },
    [9125] = { -- Crypt Fiend Parts
        title = { "17:533065086:933845475", "ชิ้นส่วน Crypt Fiend" },
        progress = { "46:1986505963:644370811 N 117:1424827367:280898090", "ชุดแรกเจ้าทำได้เป็นแบบอย่าง {name} หากมีเพิ่มข้ารับเลย ทุกชุดที่ส่งจะได้ตราอีกอัน" },
        completion = { "16:959884130:63492255 N 41:722897065:983246745", "ยอดเยี่ยมที่สุด {name}! ของพวกนี้จะได้ใช้ประโยชน์แน่นอน" },
        description = { "46:1986505963:644370811 N 117:1424827367:280898090", "ชุดแรกเจ้าทำได้เป็นแบบอย่าง {name} หากมีเพิ่มข้ารับเลย ทุกชุดที่ส่งจะได้ตราอีกอัน" },
        required = { [22525] = { "17:533065086:933845475", "ชิ้นส่วนอสูรสุสาน" } },
        objectiveLabels = {
            item = { ["Crypt Fiend Parts"] = "ชิ้นส่วนอสูรสุสาน" },
        },
    },
    [9126] = { -- Bonescythe Digs
        title = { "15:265903226:802667004", "งานเกราะ Bonescythe" },
        objective = { "93:2113956891:600028122", "Rohan the Assassin ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการ Bone Fragment 30 ชิ้น" },
        description = { "387:1001766430:1821447760", "แบบเกราะ Bonescythe ของ Don Julio ต้องใช้เศษกระดูก มากมายทีเดียว แม้คนบ้าพอเข้า Naxxramas จะนำวัสดุหลักมาให้พอ ข้ายังหาเศษกระดูก Scourge เพิ่มเสมอ\n\nคิดอย่างไร? อยากมือเปื้อนพร้อมทำลาย Scourge ไหม? ได้ประโยชน์ทั้งสองฝ่าย" },
        progress = { "47:748660131:1949184965 C 1:46:46", "ข้าชี้บริเวณที่มีโครงกระดูกชุกชุมให้ได้ {class}" },
        completion = { "15:17032318:2135300340 N 145:1548886334:292673694", "เจ้าทำงานเร็ว {name} เร็วดั่งสุนัขจิ้งจอก... นี่ เคยเล่าไหมว่าข้าเคยอยู่วงร้องประสานเสียงสี่คนสไตล์บาร์เบอร์ช็อป?\n\nเตือนให้เล่าสักวันด้วย" },
        required = { [22526] = { "14:1198842584:916336639", "เศษกระดูก" } },
        objectiveLabels = {
            item = { ["Bone Fragments"] = "เศษกระดูก" },
        },
    },
    [9127] = { -- Bone Fragments
        title = { "14:1198842584:916336639", "เศษกระดูก Bone Fragment" },
        progress = { "65:251697632:1115284033 N 103:191786939:1264182783", "คนทำงานสายข้าไม่มีวันมีเศษกระดูกมากเกินไป {name} มีเหลือเมื่อไรนำมา ข้าจะให้ตราอีกอัน" },
        completion = { "115:2117916018:1576105807 N 1:46:46", "ฝันที่จะเป็นนักเต้นเต็มเวลาที่ดิสโก้ Gadgetzan ใกล้จริงแล้ว! ทำดีเช่นนี้ต่อไป {name}" },
        description = { "65:251697632:1115284033 N 103:191786939:1264182783", "คนทำงานสายข้าไม่มีวันมีเศษกระดูกมากเกินไป {name} มีเหลือเมื่อไรนำมา ข้าจะให้ตราอีกอัน" },
        required = { [22526] = { "14:1198842584:916336639", "เศษกระดูก" } },
