    [9131] = { -- Binding the Dreadnaught
        title = { "23:1639748318:1743489566", "ประสานเกราะ Dreadnaught" },
        objective = { "83:368809017:379289876", "Korfax ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการ Dark Iron Scraps 30 ชิ้น" },
        description = { { "38:1181474120:2105176641 C 383:354626292:1089492284", "38:1181474120:2105176641 C 384:1262336865:1951070029" }, "เคยเห็นเกราะ Dreadnaught ไหม {class}? ไม่ แน่นอนว่าไม่ เจ้ายังเด็ก เด็กน้อย ให้ข้าบอก มันรุ่งโรจน์มาก\n\nเจ้าคงถามว่าเกี่ยวอะไรกับตน ใช่ไหม? ฟังนะ เจ้ามือใหม่ ข้าต้องการเศษ Dark Iron และยอมจ่ายเพื่อได้มากที่สุด\n\nต้องใช้ประกอบชุด Dreadnaught ให้ยอดนักรบเรา นำเศษมาแล้วรับเงิน" },
        progress = { "76:412649625:465872931", "<Korfax คำรามใส่เจ้า>\n\nต้องการอะไร? บอกทางหรือ? ข้าบอกได้..." },
        completion = { "66:504202955:592896028", "ตอนนี้พอใช้ หากได้เพิ่มก็รู้ว่าจะพบข้าที่ไหน" },
        required = { [22528] = { "16:662748288:1599736815", "เศษเหล็กดำ" } },
        objectiveLabels = {
            item = { ["Dark Iron Scraps"] = "เศษเหล็กดำ" },
        },
    },
    [9132] = { -- Dark Iron Scraps
        title = { "16:662748288:1599736815", "เศษ Dark Iron" },
        progress = { "131:534949854:779795734", "เศษเหล็กทุกอ้อมแขนที่นำมาจะได้ตราหนึ่งอัน ยิ่งมากยิ่งดี ไปให้พ้นก่อนข้าผ่าเจ้าเป็นสองซีก!" },
        completion = { "80:785063320:1529366613", "นำมาแค่นี้หรือ? บางทีเจ้าไม่ได้ยินครั้งแรก ข้าต้องการอีกมาก!" },
        description = { "131:534949854:779795734", "เศษเหล็กทุกอ้อมแขนที่นำมาจะได้ตราหนึ่งอัน ยิ่งมากยิ่งดี ไปให้พ้นก่อนข้าผ่าเจ้าเป็นสองซีก!" },
        required = { [22528] = { "16:662748288:1599736815", "เศษเหล็กดำ" } },
        objectiveLabels = {
