    [9136] = { -- Savage Flora
        title = { "12:28433152:901301487", "พฤกษาดุร้าย" },
        objective = { "79:667289091:705941867", "Rayne ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการ Savage Frond 30 ชิ้น" },
        description = { "477:98250305:1390055771", "ข้าสร้างเกราะพิเศษชื่อ Dreamwalker ให้วีรชนกล้าเข้า Naxxramas พวกเขานำวัสดุส่วนใหญ่มาได้ แต่ข้ายังหาคนเก็บ Savage Frond จากพืชทั่วโลกเสมอ\n\nเจ้าอาจคิดว่างานต่ำต้อย แต่ไม่มีใบพวกนี้ก็สร้างเกราะไม่ได้\n\nข้ายังจ่ายด้วยตราที่เจ้าเลือกได้ เพราะทั้ง Dawn และ Crusade ให้เงินทุนแก่ข้า" },
        progress = { "78:557142144:1724495632", "ข้ารู้เรื่องพืชในโลกอย่างละเอียด ต้องการให้ชี้ทางไหม?" },
        completion = { "19:1047177499:1987806695 N 66:2144930522:2087168234", "ข้าซาบซึ้งมาก {name}\n\n<Rayne คำนับ>\n\nจำไว้ว่าข้ารับใบพืชเพิ่มเสมอ" },
        required = { [22529] = { "12:130279685:914789512", "ใบเฟิร์นป่า" } },
        objectiveLabels = {
            item = { ["Savage Frond"] = "ใบเฟิร์นป่า" },
        },
    },
    [9137] = { -- Savage Fronds
        title = { "13:1269624455:1725826592", "ใบ Savage Frond" },
        progress = { "194:1767412025:962661507", "ทุกชุดใบพืชที่ส่ง ข้าจะจ่ายด้วย Insignia of the Dawn หรือ Insignia of the Crusade ตามที่เลือก\n\nนำตราแลกรางวัลต่าง ๆ ที่เจ้าหน้าที่เสบียงได้" },
        completion = { "11:1191658970:1224418299 N 72:2102700875:1852608748", "ขอบใจ {name} งานเจ้าสำคัญยิ่งต่อชัยชนะของการรณรงค์ต้าน Scourge" },
        description = { "194:1767412025:962661507", "ทุกชุดใบพืชที่ส่ง ข้าจะจ่ายด้วย Insignia of the Dawn หรือ Insignia of the Crusade ตามที่เลือก\n\nนำตราแลกรางวัลต่าง ๆ ที่เจ้าหน้าที่เสบียงได้" },
