    [9141] = { -- They Call Me "The Rooster"
        title = { "26:930352248:350726044", "พวกเขาเรียกข้าว่า The Rooster" },
        objective = { "107:112194177:1801011608", "Dispatch Commander Metz ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการ Argent Dawn Valor Token" },
        description = { "416:943346738:782026863", "อยากได้ใบสั่งงานหรือ? อะไรนะ? หวังให้ข้ายื่นงานที่คนแย่งกันเพียงเพราะโผล่มาหรือ? ไม่หรอก เจ้ามือใหม่ ช่างจากทั่วโลกประมูลงานแนวหน้าที่นี่\n\nหากต้องการใบสั่งงาน ต้องแสดงว่ายอมหลั่งเลือดเพื่ออุดมการณ์ นำ Valor Token มาแล้วค่อยคุย\n\nมีทางเดียวให้มือเล็กสกปรกของเจ้าได้มัน ไปฆ่าเสีย" },
        progress = { "64:1291298893:845475706", "<Commander Metz เคี้ยวซิการ์>\n\nอะไร? ข้ามีงานยุ่ง" },
        completion = { "218:816856164:51226879", "เอาละ วิธีคือทุก Valor Token ที่ส่ง ข้าจะให้ใบสั่งงานอีกใบ ทำตามรายการแล้วส่งให้ Packmaster Stonebruiser เข้าใจไหม? ดี ไปได้แล้ว" },
        required = { [12844] = { "23:326836260:219752080", "เหรียญกล้าหาญ Argent Dawn" } },
        objectiveLabels = {
            item = { ["Argent Dawn Valor Token"] = "เหรียญกล้าหาญ Argent Dawn" },
        },
    },
    [9142] = { -- Craftsman's Writ
        title = { "16:1563284758:1623051060", "ใบสั่งงาน Craftsman's Writ" },
        progress = { "69:1191231360:1163088032", "รู้อยู่แล้ว เจ้าหนู Valor Token หนึ่งเหรียญแลก Craftsman's Writ หนึ่งใบ" },
        completion = { "82:1045530773:429585743", "เจ้าคู่ควรกับสิ่งนี้ มือใหม่ อย่าร้องไห้กับคำสั่ง ทำให้ครบหรือทำลายใบทิ้ง" },
