    [9165] = { -- Writ of Safe Passage
        title = { "20:1123957789:1970064269", "หนังสือรับรองการผ่านทางปลอดภัย" },
        objective = { "117:819579171:1404140986", "ส่ง Writ of Safe Passage ที่ลงนามแล้วให้ Dispatch Commander Metz ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { "347:1367632771:1178498495 N 146:1716145260:1063061000", "หากไม่มีนักผจญภัยช่วย คาราวานข้ามาไม่ถึงแน่! Scourge โผล่ทุกทิศพยายามขวางไม่ให้มาถึง\n\n<Guard Didier เช็ดหน้าผาก>\n\nทีนี้ต้องรอ Field Marshal Chambers เขาจะลงนาม Writ of Safe Passage ให้เจ้ากลับไปส่ง Dispatch Commander Metz ที่ Light's Hope Chapel\n\nแล้วก็ {name} ระวังคำพูดใกล้ Chambers เขาเป็นคนประเภทกัดหัวแล้วถุยลงคอ ต่างตรงที่เขาทำจริงได้..." },
        progress = { "29:1501712854:1993266121", "ชื่อ ยศ และหมายเลขประจำตัว!" },
        completion = { "71:1935122861:1472829862 N 85:122818203:697463098", "<Dispatch Commander Metz รับหนังสือแล้วลงนาม>\n\nงานยอดเยี่ยม {name} โดดเด่นด้วยซ้ำ! รับเหรียญนี้เป็นเครื่องหมายขอบคุณ ไม่ได้ตั้งใจเล่นคำ เจ้ามือใหม่" },
    },
