    [9211] = { -- The Ice Guard
        title = { "13:2146076500:2139873546", "อาคมป้องกันน้ำแข็ง Ice Guard" },
        objective = { "118:1939072186:711318068", "Mataus the Wrathcaster ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการ Insignia of the Crusade 10 อัน และเงิน 30 เหรียญทอง" },
        description = { "367:700295438:365860774", "อา Ice Guard คือชั้นเวทคุ้มกันบางที่คลุมอุปกรณ์บางชิ้น ผู้ต่อสู้สัตว์น้ำแข็งและความเย็นจะป้องกันการโจมตีได้มากขึ้นเมื่อใช้\n\nเช่นเดียวกับทุกสิ่งที่ Wrathcaster สร้าง มันมีราคา ราคาที่ข้าไม่ลด ไม่ว่าเจ้าคร่ำครวญเพียงใด สนใจไหม?" },
        progress = { "82:378220754:181088119", "หากไม่มียาม Argent Dawn พวกนี้ เจ้าคงเป็นรอยเปื้อนบนพื้นไปแล้ว" },
        completion = { "51:471833874:7250174 R 43:1913052224:693902142", "<Mataus เก็บทองเข้ากระเป๋า>\n\nขอให้สนุกกับค่าซ่อม ชาว{race} Naxxramas ไม่ใจดีกับมือใหม่" },
        required = { [22524] = { "23:307791352:257686436", "ตราแห่งครูเสด" } },
        objectiveLabels = {
            item = { ["Insignia of the Crusade"] = "ตราแห่งครูเสด" },
        },
    },
    [9213] = { -- The Shadow Guard
        title = { "16:1455108609:391363935", "อาคมป้องกันเงา Shadow Guard" },
        objective = { "118:1939072186:711318068", "Mataus the Wrathcaster ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการ Insignia of the Crusade 10 อัน และเงิน 30 เหรียญทอง" },
        description = { "302:739042769:1394169232", "ผลงานอัจฉริยะ! Shadow Guard ใช้ชั้นเวทคุ้มกันบางคลุมอุปกรณ์บางชิ้นเช่น Ice Guard และเหมือน Ice Guard เจ้าต้องจ่ายไม่น้อย\n\n<Mataus ยื่นมือถูนิ้วเข้าหากัน>\n\nสนใจไหม?" },
        progress = { "64:1476607800:804831061", "<Mataus หาว>\n\nไปให้พ้น เจ้าแมลง เว้นแต่นำอะไรมาให้ข้า" },
