        description = { "330:1740784018:1810172688", "สวัสดี สหาย มี Insignia of the Dawn หรือ Insignia of the Crusade ที่อยากแลกของทรงพลังยิ่งไหม?\n\nขอเตือน การซื้อเมื่อมีชื่อเสียง Honored กับ Dawn มีค่าบริการเพิ่มสูงมาก แนะนำให้เพิ่มชื่อเสียงก่อนดำเนินแผน" },
        progress = { "39:1006946297:209403626", "เลือกให้ดี ไม่มีคืนของ" },
        completion = { "10:10763625:219111161 N 44:1252516473:1097966051", "ขอให้เป็นวันที่ดี {name} ยินดีที่ได้ค้าขายด้วย" },
        required = { [22523] = { "20:1408751547:556028060", "ตราแห่งรุ่งอรุณ" }, [22524] = { "23:307791352:257686436", "ตราแห่งครูเสด" } },
        objectiveLabels = {
            item = { ["Insignia of the Dawn"] = "ตราแห่งรุ่งอรุณ", ["Insignia of the Crusade"] = "ตราแห่งครูเสด" },
        },
    },
    [9225] = { -- Epic Armaments of Battle - Revered Amongst the Dawn
        title = { "51:1827516080:1167786681", "ยุทโธปกรณ์ระดับ Epic — ระดับ Revered กับ Dawn" },
        objective = { "122:1099214633:1811109018", "ใช้ Insignia of the Dawn 45 อันและ Insignia of the Crusade 45 อัน เพื่อเลือกของหนึ่งชิ้นจากคลังสมบัติ Argent Dawn" },
        description = { "322:637148630:1013737307", "สวัสดี สหาย มี Insignia of the Dawn หรือ Insignia of the Crusade ที่อยากแลกของทรงพลังยิ่งไหม?\n\nขอเตือน ของระดับ Epic เมื่อมีชื่อเสียง Revered กับ Dawn ยังแพงพอควร แนะนำให้เพิ่มชื่อเสียงก่อนดำเนินแผน" },
        progress = { "39:1006946297:209403626", "เลือกให้ดี ไม่มีคืนของ" },
        completion = { "10:10763625:219111161 N 44:1252516473:1097966051", "ขอให้เป็นวันที่ดี {name} ยินดีที่ได้ค้าขายด้วย" },
        required = { [22523] = { "20:1408751547:556028060", "ตราแห่งรุ่งอรุณ" }, [22524] = { "23:307791352:257686436", "ตราแห่งครูเสด" } },
        objectiveLabels = {
            item = { ["Insignia of the Dawn"] = "ตราแห่งรุ่งอรุณ", ["Insignia of the Crusade"] = "ตราแห่งครูเสด" },
