    [9226] = { -- Superior Armaments of Battle - Revered Amongst the Dawn
        title = { "55:444546038:1585422978", "ยุทโธปกรณ์ชั้นเยี่ยม — ระดับ Revered กับ Dawn" },
        objective = { "120:762620652:1268353849", "ใช้ Insignia of the Dawn 7 อันและ Insignia of the Crusade 7 อัน เพื่อเลือกของหนึ่งชิ้นจากคลังสมบัติ Argent Dawn" },
        description = { "227:548780028:1808885783", "สวัสดี สหาย มี Insignia of the Dawn หรือ Insignia of the Crusade ที่อยากแลกของทรงพลังไหม?\n\nของที่เสนอแก่ผู้มีชื่อเสียง Revered กับ Dawn ราคาสมเหตุผลทีเดียว ข้าแนะนำให้ซื้อ!" },
