    [9228] = { -- Epic Armaments of Battle - Exalted Amongst the Dawn
        title = { "51:1924159114:1384526366", "ยุทโธปกรณ์ระดับ Epic — ระดับ Exalted กับ Dawn" },
        objective = { "122:901918847:1153053244", "ใช้ Insignia of the Dawn 27 อันและ Insignia of the Crusade 27 อัน เพื่อเลือกของหนึ่งชิ้นจากคลังสมบัติ Argent Dawn" },
        description = { "219:46158720:767514114", "สวัสดี สหาย มี Insignia of the Dawn หรือ Insignia of the Crusade ที่อยากแลกของทรงพลังยิ่งไหม?\n\nผู้มีชื่อเสียง Exalted กับ Dawn ได้ส่วนลดสูงสุดของเรา! ข้าแนะนำให้ซื้อ" },
        progress = { "39:1006946297:209403626", "เลือกให้ดี ไม่มีคืนของ" },
        completion = { "10:10763625:219111161 N 44:1252516473:1097966051", "ขอให้เป็นวันที่ดี {name} ยินดีที่ได้ค้าขายด้วย" },
        required = { [22523] = { "20:1408751547:556028060", "ตราแห่งรุ่งอรุณ" }, [22524] = { "23:307791352:257686436", "ตราแห่งครูเสด" } },
        objectiveLabels = {
            item = { ["Insignia of the Dawn"] = "ตราแห่งรุ่งอรุณ", ["Insignia of the Crusade"] = "ตราแห่งครูเสด" },
        },
    },
    [9378] = { -- DND FLAG The Dread Citadel - Naxxramas
        title = { "38:1687537987:635019266", "[DND FLAG] ป้อมปราการสยอง Naxxramas" },
        objective = { "159:471360541:996545378", "Archmage Angela Dosantos ที่ Light's Hope Chapel ใน Eastern Plaguelands จะมอบ Arcane Cloaking ให้โดยไม่คิดค่าใช้จ่าย เจ้าต้องมีชื่อเสียงระดับ Exalted กับ Argent Dawn" },
        description = { "489:459236868:1332933921", "ลึกใน Plaguewood คือทางเข้าป้อมสยอง Naxxramas ก่อนนี้การเข้าทุกครั้งถูกเวทคุ้มกันบนประตูรูนขัดขวาง จนบัดนี้\n\nเราคิดวิธีเข้าด้วยการอำพรางอาร์เคนถาวรแบบหนึ่ง จากคาถาเก่า Kirin Tor ที่ข้าปรับเองเล็กน้อย แม้มีต้นทุนสูง แต่ความทุ่มเทต่อ Dawn ของเจ้าไม่สั่นคลอน! เราจะยกเว้นค่าใช้จ่ายทั้งหมด" },
    },
    [9664] = { -- Establishing New Outposts
        title = { "25:1748453242:1662749444", "ตั้งด่านใหม่" },
        objective = { "166:1623775104:1663846980", "ยึด Crown Guard Tower, Eastwall Tower, Northpass Tower และ Plaguewood Tower ใน Eastern Plaguelands แล้วกลับไปหา Emmisary Whitebeard ที่ Light's Hope Chapel" },
        description = { "28:190598339:659619673 N 395:1576772458:905710932", "ยินดีต้อนรับสู่ Plaguelands {name} อย่างที่รู้ Forsaken กับพันธมิตรยึดแผ่นดินทางตะวันตกไว้แม้เราพยายามเต็มที่ ผู้บัญชาการ Alliance ตัดสินใจสร้างป้อมใหม่ทางตะวันออก เพื่อบีบวงล้อมศัตรู\n\nเราจะยึดและสร้างหอคอยที่ร้างนับแต่ยุค Lordaeron ขึ้นใหม่เพื่อการนี้ ดินแดนอันตราย เราต้องการความช่วยเหลือ" },
        progress = { "151:573216187:1606223889", "เมื่อควบคุมหอคอย อีกไม่นานเราจะล้อม Forsaken ได้ จากนั้นแค่รอเวลาบดขยี้" },
        completion = { "11:1776810664:1873330125 N 174:832944718:1764415169", "ดีมาก {name} เราต้องรักษาหอคอยจากการโจมตีในอนาคต อาจต้องให้เจ้าช่วยจนกองหนุนมาถึงและคุมพื้นที่ได้" },
    },
    [9665] = { -- Bolstering Our Defenses
        title = { "23:210716347:930925482", "เสริมแนวป้องกัน" },
        objective = { "162:847548104:74579965", "ยึด Crown Guard Tower, Eastwall Tower, Northpass Tower และ Plaguewood Tower ใน Eastern Plaguelands แล้วกลับไปหา Emmisary Gormok ที่ Light's Hope Chapel" },
        description = { "453:584635166:224239168", "สายลับ Forsaken พบแผน Alliance จะตั้งฐานใหม่ใน Eastern Plaguelands ตามหอคอยร้างทั่วพื้นที่\n\nเราต้องไม่ให้พวกมันตั้งกำลังสำคัญบนชายแดนตะวันออก จึงต้องต้านการรุก Alliance แผนปัจจุบันคือไล่ออกจากหอที่อาจยึดแล้ว และรักษาหอของเราเพื่อต้านการโจมตีต่อไป" },
        progress = { "184:999166781:2055398098", "พวกมันคงโง่ที่คิดว่าเราจะยอมให้ตั้งฐานใกล้เมืองหลวงแห่งหนึ่งเพียงนี้\n\nเราจะลดกำลังจนพวกมันต้องหันหลังหนีกลับใต้" },
        completion = { "19:960426253:1618103263 N 184:1315658629:1294241826", "ข่าวดี {name} เราต้องสู้ต่อเนื่องใน Plaguelands จนกว่าจะผลักกองกำลัง Alliance กลับไปหมด\n\nจนถึงวันนั้น หวังว่าเจ้าจะช่วยเราต่อไป" },
    },
    [183] = { -- The Boar Hunter
        title = { "15:253502783:930353857", "นักล่าหมูป่า" },
        objective = { "57:67469883:1311480381", "Talin Keeneye ต้องการให้เจ้าฆ่า Small Crag Boars 12 ตัว" },
        description = { "407:871435275:1599323051", "ไม่มีอะไรดีเท่าออกล่าหมูป่าทั้งวันใช่ไหม?\n\nแต่ใน Coldridge Valley มีมากจนแทบไม่สนุก ไม่ต้องยั่วให้พุ่ง มันโกรธพร้อมอยู่แล้ว พักนี้มากจนการล่าประจำวันอันตราย\n\nสรุปสั้น ๆ หากช่วยฆ่าบางส่วน ข้าจะขอบคุณ" },
        progress = { "18:754312450:778203395", "การล่าเป็นอย่างไร?" },
        completion = { "71:536520915:627140880 N 1:46:46", "เยี่ยม! ข้ากลับไปล่าแบบ... สบาย ๆ... ได้แล้ว ขอบใจ {name}" },
        objectiveLabels = {
            monster = { ["Small Crag Boar slain"] = "ปราบ หมูป่าผาหินตัวเล็ก" },
        },
    },
    [5282] = { -- The Restless Souls
        title = { "18:290267522:22652026", "วิญญาณที่ไม่สงบ" },
        objective = { "223:1444528514:254582820", "ใช้ Egan's Blaster กับพลเมืองผีและวิญญาณแห่ง Stratholme เมื่อ Restless Soul หลุดจากเปลือกผี ให้ยิงซ้ำอีกครั้ง แล้วพวกเขาจะเป็นอิสระ!\n\nปลดปล่อย Restless Soul 15 ตน แล้วกลับไปหา Egan" },
        description = { "460:1432124174:1524483099", "ข้าดึงพลังและเจตจำนงที่จะมีชีวิตหายใจต่อจากความเกลียด Scourge กับสิ่งที่พวกมันทำอย่างที่สุด แต่ข้าไม่ใช่คนคลั่งศรัทธา มีพวกอย่าง Scarlet Crusade ที่เลือกทำลายอันเดดบริสุทธิ์มากกว่ามอบความเมตตาแม้เพียงน้อย\n\nจึงมาถึงสิ่งนี้ เครื่องยิงของข้า มันจะปลดพันธนาการวิญญาณที่ถูกทรมานใน Stratholme\n\nใช้กับผีที่หลอกหลอนถนนในเมืองที่ถูกปล้นสะดม ปลดปล่อยวิญญาณพวกเขา" },
        progress = { "50:1195640505:2122567773 N 18:245559461:2137177907", "ความเมตตาทำให้เราต่างจากสัตว์ {name} จงจำไว้..." },
        completion = { "57:886025040:1493914274 N 78:1417416633:1024160447", "<Egan เช็ดน้ำตา>\n\nเจ้าเห็นแม่ข้าหรือไม่ {name}? ปลดปล่อยนางหรือยัง?\n\nเจ้าเป็นแบบอย่างอันดีงาม เพื่อชดเชยความเหนื่อยยาก..." },
        steps = { { "11:1500336141:962695302", "ปลดปล่อยวิญญาณ" } },
    },
    [5463] = { -- Menethil's Gift
        title = { "15:140076803:1879332542", "ของขวัญแห่ง Menethil" },
        objective = { "104:801989000:2093658627", "เดินทางไป Stratholme แล้วหา Menethil's Gift วาง Keepsake of Remembrance บนพื้นอัปมงคลนั้น" },
        description = { "381:1385402039:949388637 R 119:1052107501:135750920", "ข้าเห็นมนุษย์ Ras Frostwhisper ถวายวิญญาณอมตะแก่ Lich King เขาชักมีดปลิดชีพตนพร้อมรอยยิ้ม ร่างล้มลงในขอบดาวห้าแฉก Lich King ยืนเหนือจอมเวทที่ล้มลง ขยับเพียงครั้งเดียว ลิช Ras Frostwhisper ก็ถือกำเนิด\n\n<Leonid มองพื้นแล้วเงยขึ้นหาเจ้า>\n\nใช่ ชาว{race} ข้าจำได้ สิ่งที่เจ้าแสวงหามีชื่อ Menethil's Gift พื้นดินที่ Lich King อวยพร เป็นแดนศักดิ์สิทธิ์ของ Scourge" },
        progress = { "54:965846595:742303775", "บริเวณรอบ Menethil's Gift เย็นจัดผิดปกติ" },
        completion = { "43:913673020:949623441", "เจ้าวางของที่ระลึกบนดินแปดเปื้อน" },
        required = { [13585] = { "23:663180502:918534907", "ของที่ระลึกแทนความทรงจำ" } },
        objectiveLabels = {
            item = { ["Keepsake of Remembrance"] = "ของที่ระลึกแทนความทรงจำ" },
        },
    },
    [5848] = { -- Of Love and Family
        title = { "18:1233142555:731539431", "ว่าด้วยรักและครอบครัว" },
        objective = { "255:1942717127:1116092088", "เดินทางไป Stratholme ทางเหนือของ Plaguelands ใน Scarlet Bastion มีภาพ “Of Love and Family” ซ่อนหลังภาพที่วาดดวงจันทร์คู่ของโลกเรา\n\nนำภาพกลับไปให้ Tirion Fordring" },
        description = { "476:1306875311:1408869296", "ภาพนั้น... แขวนบนผนังห้องทำงานข้าในค่ายทหารของ Order มาหลายปี\n\nหลังการพิจารณาคดี Tirion จบ ข้ารู้ว่าเก็บให้เห็นต่อไม่ได้ จึงซ่อนในที่ที่พวกเขาคาดไม่ถึง\n\nไป Stratholme เข้าลึกถึงส่วนที่ตอนนี้เป็น Scarlet Bastion หาภาพดวงจันทร์คู่ ค่อย ๆ แซะสีออกจนพบผลงานชิ้นเอก “Of Love and Family”\n\nขอแสงสว่างนำทางการกระทำเจ้า" },
        progress = { "14:257730236:427352168 N 27:2071072424:2010653291", "ภาพวาด {name} เจ้ามีภาพหรือยัง?" },
        completion = { "101:617821837:945832176", "<Tirion แทบทรุดเมื่อเห็นภาพ>\n\n<เขาเริ่มสะอื้นอย่างหนักจนแทบควบคุมไม่ได้>" },
        required = { [14679] = { "18:1233142555:731539431", "ว่าด้วยความรักและครอบครัว" } },
        objectiveLabels = {
            item = { ["Of Love and Family"] = "ว่าด้วยความรักและครอบครัว" },
        },
    },
    [7815] = { -- Snapjaws, Mon!
        title = { "14:253683330:84413348", "Snapjaws สหาย!" },
        objective = { "154:1801948558:1061247783", "Katoom the Angler ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้าฆ่าเต่า Saltwater Snapjaw 15 ตัว เสร็จแล้วกลับไปหา" },
        description = { "292:175486203:1184840519", "อย่าให้ตาโตหลอก สหาย! เต่า snapjaw เป็นภัย ข้าตกปลาไม่ถึงห้านาที สายก็ขาดเพราะเครื่องดูดปลาใหญ่พวกนี้ขโมยเหยื่อ\n\nช่วยข้ากับ Revantusk ฆ่ามัน\n\nฆ่าให้หมด!" },
        progress = { "18:754312450:778203395", "การล่าเป็นอย่างไร?" },
        completion = { "102:1290924977:676043004", "โอ้ สหาย ขอบคุณไม่พอ! หวังเบ็ดนี้ตอบแทนงานได้" },
        objectiveLabels = {
            monster = { ["Saltwater Snapjaw slain"] = "ปราบ เต่ากรามงับน้ำเค็ม" },
        },
    },
    [95494] = { -- Bruised Pride and Lion Hides
        title = { "28:273948225:1663984188", "ศักดิ์ศรีบอบช้ำกับหนังสิงโต" },
        objective = { "98:928880745:544588999", "รวบรวม Savannah Lion Hides 6 ผืน จาก Savannah Matriarchs และ Savannah Patriarchs ใน Barrens" },
        description = { "367:1848006967:1432665865", "ข้าต้องการคนแขนดาบแข็งแรงที่พอมีเวลา มาช่วยรวบรวมหนังสิงโต การขอคนแปลกหน้าช่วยทำให้ศักดิ์ศรีข้าเจ็บแปลบ แต่ไม่นานมานี้ข้าบาดเจ็บที่ขา ยังออกล่าเองไม่ไหวจนกว่าจะหาย แต่ข้ายังมีหน้าที่ต้องทำให้ครบ\n\nโดยทั่วไปตัวใหญ่แถวนี้ให้หนังดีที่สุด เริ่มจากพวกนั้นก่อน" },
        progress = { "18:754312450:778203395", "การล่าเป็นอย่างไร?" },
        completion = { "298:1445716676:228896071", "ใช่ พวกนี้น่าจะใช้ได้ดี ข้าตกลงกับช่างฟอกหนังในพื้นที่ว่าจะส่งหนังดิบให้ แลกกับเครื่องหนังสำเร็จรูปหลายชนิดที่ใช้ทำมาค้าขาย\n\nข้าไม่เคยส่งของขาดตามข้อตกลง และถึงบาดเจ็บก็ไม่คิดจะเริ่มผิดคำพูดตอนนี้" },
        required = { [269715] = { "18:1627894255:1142885723", "หนังสิงโตทุ่งหญ้าสะวันนา" } },
        steps = { { "18:1627894255:1142885723", "หนังสิงโตทุ่งหญ้าสะวันนา" } },
    },
    [1125] = { -- The Spirits of Southwind
        title = { "24:45654070:2117965070", "วิญญาณแห่ง Southwind" },
        objective = { "162:1074007359:1071099838", "ปลดปล่อยวิญญาณ Tortured Druid 8 ดวงและ Tortured Sentinel 8 ดวงใน Southwind Village แล้วกลับไปหา Layo Starstrike ที่สุสาน Valor's Rest ใน Silithus" },
        description = { "107:1893370490:2006266498 N 386:577868653:1218771227", "ทางตะวันตกเฉียงใต้คือสถานที่น่าเศร้า ซาก Southwind Village เราควรเริ่มงานที่นั่น {name}\n\nเท่าที่รู้ หมู่บ้านเคยเป็นฐานไนต์เอลฟ์ใน Silithus แต่ถูกรังซิลิธิดที่ระบาดในแดนร้างยึดไปนานแล้ว ข้าได้แต่จินตนาการความสยองเมื่อหมู่บ้านถูกทำลายครั้งแรก...\n\nวิญญาณดรูอิดและเซนทิเนลที่ล้มตายเร่ร่อนทุกข์ทรมานไร้จุดหมาย สำรวจซากและปลดปล่อยวิญญาณผู้เคราะห์ร้ายตามจำเป็น" },
        progress = { "158:1353162033:496975246 N 1:46:46", "Alliance หรือ Horde ไม่สำคัญ ไม่มีใครควรติดค้างในโลกเป็นวิญญาณทุกข์ทรมาน การปลดปล่อยจะทำให้ถูกต้อง {name}" },
        completion = { "425:1449656608:1878582825", "ข้าคิดว่ารังใหญ่ที่มีฝูงแมลงวนใกล้ซากหมู่บ้านอาจเกี่ยวกับการล่มสลาย งานเจ้าดูพิสูจน์ว่าจริง รังที่อยู่ใกล้คุกคามงานในอนาคตของเรา\n\nขอบใจความเมตตาที่ปลดปล่อยผู้ล่วงลับ ข้ารู้ว่างานเช่นนี้ไม่ง่าย แต่เมื่อพร้อม ข้าอยากขอให้ช่วยอีกครั้ง..." },
    },
    [1126] = { -- Hive in the Tower
        title = { "17:1927042764:1893044948", "รังในหอคอย" },
        objective = { "216:2096418268:913132509", "ปีนขึ้นหอคอยที่ Southwind Village แล้วหาวิธีกระตุ้นให้รังซิลิธิดเคลื่อนไหว หากพบสิ่งผิดปกติระหว่างทำ ให้นำกลับไปให้ Layo Starstrike ที่สุสาน Valor's Rest ใน Silithus" },
        description = { "493:1902718329:1122972206", "เราต้องจัดการรังที่ Southwind Village ข้าคิดว่ารู้วิธีเข้าถึง จากประสบการณ์ รังซิลิธิดไวต่อสภาพแวดล้อมมาก จึงอธิบายว่าทำไมมันโจมตีเมื่อได้ยินวิญญาณร้องครวญ\n\nซิลิธิดหนาแน่นที่สุดในหอคอยที่มีตัวต่อบินวน ขึ้นไปกวนรังให้เคลื่อนไหว แล้วรายงานสิ่งที่เรียนรู้ ระวังด้วย! หากพบของอาจมีประโยชน์ นำมาให้ข้า" },
        progress = { "88:314828934:1219956761", "ได้ผลไหม? เจ้ายังครบชิ้น นั่นข่าวดี พบอะไรหรือไม่?" },
        completion = { "239:299268969:1191737628 N 157:332882225:978997779", "อะไร... นี่อะไร?\n\nรูปร่างเหมือน... กล่องกระมัง? ถูกหุ้มหนาน่าดู เดี๋ยว ตรงนี้โผล่ออกมา... ใต้คราบทั้งหมดคือหนังสือหรือ?\n\nข้าว่าเจ้าพบของสำคัญ {name} อย่างน้อยก็หวังเช่นนั้น อาจเป็นสมุดบันทึกโบราณที่เปลือกเก็บรักษาไว้\n\nข้าคิดว่ารู้วิธีหาคำตอบ" },
        required = { [17346] = { "25:22333547:676668319", "วัตถุซิลิธิดที่มีคราบเกาะ" } },
        objectiveLabels = {
            item = { ["Encrusted Silithid Object"] = "วัตถุซิลิธิดที่มีคราบเกาะ" },
        },
    },
    [6844] = { -- Umber, Archivist
        title = { "16:443151903:1282297486", "Umber ผู้ดูแลหอจดหมายเหตุ" },
        objective = { "120:1345833682:1994941692", "นำ Encrusted Silithid Object ไปให้ Umber ผู้ดูแลหอจดหมายเหตุ Cenarion Circle ที่ Nighthaven ใน Moonglade" },
        description = { "495:372223671:404686479", "ที่นี่ยังมีงานมาก แต่ข้าว่านำสิ่งนี้กลับ Circle เพื่อวิเคราะห์สำคัญกว่า เชื่อเถอะ เสร็จแล้วงานที่นี่ก็ยังอยู่ หากในเปลือกไคตินเหนียวเป็นสมุดบันทึก Circle จะมีหน้าต่างสู่อดีตเสียที!\n\nนำไปให้ผู้ดูแลหอจดหมายเหตุที่ Nighthaven เขาชื่อ Umber ฉลาดเป็นกรด เพี้ยนสักหน่อย แต่ฉลาดจริง! เขากู้ตำราสภาพแย่กว่านี้มาแล้ว หากช่วยได้ เขาทำได้แน่" },
        progress = { "385:1454104514:1966383758", "อ้าว สวัสดี! อืม...\n\nขอพูดตรงนิด สหาย... เจ้ากลิ่นแรงทีเดียว จะว่าเหม็นก็ได้ ไม่ได้โจมตีตัวตนเจ้า แค่บอกว่า... คราวหน้ากลับจากสนามอาจชำระตัวหน่อย จะทำให้ความประทับใจแรกดีขึ้น!\n\nเอาเถอะ... มีอะไรให้ช่วย?" },
        completion = { "437:742772051:918828696", "โอ้ คางคกลิงเอ๋ย! เอาอะไรมา? รูปร่างคล้ายหนังสือกระมัง... ข้าจะลองกะเทาะเปลือก\n\nLayo ส่งจาก Silithus หรือ? ข้าได้ยินเพียงข่าวซุบซิบเบา ๆ ซึ่งคิดดูแล้วก็ไม่เบานัก ถึงความสยองที่นั่น ผสมกับความไม่ชอบแมลงของข้า ก็ได้เหตุผลให้ข้าอยู่กับหนังสือที่นี่!" },
    },
    [8277] = { -- Deadly Desert Venom
        title = { "19:176423055:484517194", "พิษทะเลทรายมรณะ" },
        objective = { "173:841958317:360503168", "เก็บเหล็กในแมงป่องสโตนแลช 8 อันและเขี้ยวตัววิ่งทราย 8 ซี่ให้ Beetix Ficklespragg ที่ Cenarion Hold ใน Silithus เมื่อได้ครบแล้วกลับไปหานาง" },
        description = { "501:2143388929:1095993710", "Beetix Ficklespragg ยินดีรับใช้! Noggle ญาติข้าหากินด้วยเก็บสมุนไพรหายากให้นักเล่นแร่แปรธาตุ Cenarion Hold อย่างน้อยก็เคยทำ เขากลับคราวล่าสุดพร้อมพิษรุนแรงในเลือด\n\nข้าชะลอพิษได้ แต่หากจะถอนหมด ต้องได้ตัวอย่างจากสิ่งที่ต่อยเขา\n\nNoggle มาจากเหนือ ข้าพนันเสื้อได้เลยว่าต้องเป็น Stonelash Scorpid หรือ Sand Skitterer นำเหล็กในกับเขี้ยวมา ข้าจะลองทำยาถอนพิษ" },
        progress = { "75:2120414601:1611019854", "เก็บตัวอย่างเสร็จหรือยัง? เราอาจเสีย Noggle เมื่อไรก็ได้!" },
        completion = { "64:1667555723:60815476", "ภาวนาให้โชคดี สหาย! หวังว่าเราจะช่วย Noggle ได้!" },
        required = { [20373] = { "25:782862072:1502602623", "เหล็กในแมงป่องสโตนแลช" }, [20376] = { "19:1659711256:708803065", "เขี้ยวตัววิ่งทราย" } },
        objectiveLabels = {
            item = { ["Stonelash Scorpid Stinger"] = "เหล็กในแมงป่องสโตนแลช", ["Sand Skitterer Fang"] = "เขี้ยวตัววิ่งทราย" },
        },
    },
    [8278] = { -- Noggle's Last Hope
        title = { "18:1200544755:5043822", "ความหวังสุดท้ายของ Noggle" },
        objective = { "151:1288835136:1998206361", "เก็บเหล็กในแมงป่องก้ามโตสโตนแลช 3 อัน เหล็กในแมงป่องนักฉีกสโตนแลช 3 อัน และเขี้ยวตัวซุ่มโขดหิน 3 ซี่ให้ Beetix Ficklespragg ที่ Cenarion Hold ใน Silithus" },
        description = { "176:1343414358:561100406 N 220:220121379:575080193", "บ้าจริง! ยาถอนพิษไม่ได้ผล Noggle ต้องถูกสัตว์ที่แข็งแกร่งกว่าในแดนใต้ไกลต่อยมา\n\nข้าต้องให้เจ้าไปเก็บตัวอย่างเพิ่ม {name} ข่าวดีคือพิษแรงกว่า จึงใช้จำนวนน้อยลง ข่าวร้ายคือสัตว์มีพิษทางใต้มีหลายชนิด ต้องเก็บจากหลายแหล่ง" },
        progress = { "46:1369423277:1761410719", "โอกาสสุดท้ายช่วย Noggle แล้ว! เร็วเข้า!" },
        completion = { "69:2000764109:297153737", "ใช่! ดูได้ผล Noggle กำลังฟื้น เราเป็นหนี้เจ้าครั้งใหญ่!" },
        required = { [20375] = { "24:992535806:1992151881", "เหล็กในแมงป่องนักฉีกสโตนแลช" }, [20374] = { "24:1155003577:955155514", "เหล็กในแมงป่องก้ามโตสโตนแลช" }, [20377] = { "17:647837904:1570893620", "เขี้ยวตัวซุ่มโขดหิน" } },
        objectiveLabels = {
            item = { ["Stonelash Flayer Stinger"] = "เหล็กในแมงป่องนักฉีกสโตนแลช", ["Stonelash Pincer Stinger"] = "เหล็กในแมงป่องก้ามโตสโตนแลช", ["Rock Stalker Fang"] = "เขี้ยวตัวซุ่มโขดหิน" },
        },
    },
    [8279] = { -- The Twilight Lexicon
        title = { "20:488458437:1296651723", "พจนานุกรม Twilight Lexicon" },
        objective = { "78:1151706898:1485498703", "นำพจนานุกรมสนธยาทั้งสามบทไปให้ Hermit Ortell ใน Silithus" },
        description = { "495:8931615:862126169", "Twilight's Hammer ไม่ปรานีคนออกจากกลุ่ม ยังล่าข้าถึงวันนี้ราวสัตว์! ไม่ต้องบอกก็รู้ ศัตรูมันคือสหายข้า!\n\nเพื่อถอดจารึก ข้าต้องใช้หนังสือที่อาลักษณ์ใช้เข้ารหัสสารลับ Twilight Lexicon มันสำคัญจนเก็บสามบทแยกที่! ผู้ดูแลหนังสือเรียก Twilight Keeper ตามหาในค่าย Twilight's Hammer" },
        progress = { "72:1072310803:916619957", "ใครน่ะ? อ้อ เจ้าเอง! พบ Lexicon ทุกบทหรือยัง?" },
        completion = { "62:914044658:664698892 N 157:1924520530:1552303782", "ใช่! นี่ส่วนต่าง ๆ ของหนังสือ! เริ่มกัน {name}\n\nสลับทุกคำที่สามกับคำจากบทสอง... แล้วสลับคำเว้นคำกับบทแรก... เดี๋ยว ข้าสลับลำดับหรือเปล่า?" },
        required = { [20394] = { "28:237572116:1254463564", "พจนานุกรมสนธยา บทที่หนึ่ง" }, [20395] = { "28:237572117:1254463565", "พจนานุกรมสนธยา บทที่สอง" }, [20396] = { "28:237572118:1254463566", "พจนานุกรมสนธยา บทที่สาม" } },
        objectiveLabels = {
            item = { ["Twilight Lexicon - Chapter 1"] = "พจนานุกรมสนธยา บทที่หนึ่ง", ["Twilight Lexicon - Chapter 2"] = "พจนานุกรมสนธยา บทที่สอง", ["Twilight Lexicon - Chapter 3"] = "พจนานุกรมสนธยา บทที่สาม" },
        },
    },
    [8280] = { -- Securing the Supply Lines
        title = { "25:1147429667:746600457", "รักษาเส้นทางส่งเสบียง" },
        objective = { "87:148644106:905149654", "Windcaller Proudhorn ที่ Cenarion Hold ใน Silithus ต้องการให้เจ้าสังหาร Dredge Striker 15 ตัว" },
        description = { "473:2098942169:1364215701", "Cenarion Hold สำคัญทางยุทธศาสตร์อย่างยิ่ง ข้ามั่นใจว่าตราบใดที่ยึดไว้ เราจะชนะซิลิธิด หากรักษาการส่งเสบียงได้ละนะ\n\nหนอนทะเลทรายเป็นภัยต่อคาราวานยิ่งกว่าซิลิธิด เช้านี้เอง Dredge Striker ทำลาย Morrowgrain ล็อตใหญ่ ข้าต้องให้ลดจำนวนมัน เพื่อไม่ให้เสบียงเสี่ยงอีก" },
        progress = { "72:256162931:156611167", "Dredge Striker เป็นภัยร้ายแรง ต้องจัดการเร็ว!" },
        completion = { "93:771425348:1547218245", "ข้าขอบใจจากใจ ความช่วยเหลือ Cenarion Hold แสดงความกล้าแท้จริง" },
    },
    [8281] = { -- Stepping Up Security
        title = { "20:1260683067:704263447", "ยกระดับความปลอดภัย" },
        objective = { "87:1278093424:3807834", "Windcaller Proudhorn ที่ Cenarion Hold ใน Silithus ต้องการให้เจ้าสังหาร Dredge Crusher 20 ตัว" },
        description = { "50:1447094704:788429361 N 306:1555114551:1441435748", "ผลงานเจ้าจนบัดนี้เป็นแบบอย่าง {name} แต่เส้นทางเสบียงยังไม่ปลอดภัยหมด เมื่อ Dredge Striker หาย ญาติตัวใหญ่ทางใต้ย่อมมาแทนในเหนือ\n\nต้องฆ่า Dredge Crusher ไม่น้อยเพื่อกันไว้ เราปล่อยความปลอดภัยเสบียงให้เป็นเรื่องโชคไม่ได้" },
        progress = { "72:851973011:169823168", "Dredge Crusher เป็นภัยร้ายแรง ต้องจัดการทันที!" },
        completion = { "93:759895296:795609823", "ยอดเยี่ยม! เจ้าพิสูจน์ว่าเป็นพันธมิตรมีค่าในการเตรียมรบซิลิธิด" },
    },
    [8282] = { -- Noggle's Lost Satchel
        title = { "21:603689910:1845472446", "กระเป๋าที่หายของ Noggle" },
        objective = { "108:1776093348:429727645", "ตามหากระเป๋าของน็อกเกิลในเทือกเขาทางใต้ของ Silithus แล้วนำไปคืนเขาที่ Cenarion Hold" },
        description = { "500:603222888:844595450", "ข้าอยู่ไหน? กระเป๋าอยู่ไหน? *หอบ* ต้องทำหายขณะหนี Deathclasp แมงป่องยักษ์ ระหว่างรีบหนี ข้าเดินเข้ารัง Stonelash Flayer\n\nกระเป๋ามีสารหายากทุกชนิด หากไม่มี ข้ากับ Beetix ทำยาที่ Cenarion Hold ต้องใช้ไม่ได้ ข้ายังอ่อนแรงลุกไม่ไหว แต่จะตอบแทนคุ้มค่าหากนำสารกลับมา\n\nข้าพบ Deathclasp ในเทือกเขาใต้ หลังค่าย Bronzebeard" },
        progress = { "100:910158106:1804644483", "ยังไม่พบกระเป๋าหรือ? ข้าควรนับว่าโชคดี อย่างน้อยพิษก็ถูกถอนแล้ว" },
        completion = { "106:1960738508:1933972215", "ใช่! เจ้านำกระเป๋ากลับมา สารหายากอยู่ครบ! ข้าจะเป็นหนี้เจ้าอีกนาน" },
        required = { [20379] = { "16:995199968:1062640354", "กระเป๋าของน็อกเกิล" } },
        objectiveLabels = {
            item = { ["Noggle's Satchel"] = "กระเป๋าของน็อกเกิล" },
        },
    },
    [8283] = { -- Wanted - Deathclasp, Terror of the Sands
        title = { "40:232428859:41150645", "ประกาศจับ — Deathclasp ภัยแห่งผืนทราย", variants = { { "39:1953025852:1884966942", "ประกาศจับ — Deathclasp ภัยแห่งผืนทราย" } } },
        objective = { "62:1252272466:1289259738", "นำก้ามของเดธแคลสป์ไปให้ Vish Kozus ผู้บัญชาการกองรักษาการณ์" },
        description = { "396:685075157:603413608", "เชื่อว่าแมงป่องน่าสะพรึง Deathclasp ถอยไปเทือกเขาใต้เพราะซิลิธิดเคลื่อนไหวมากขึ้น นางเป็นภัยใหญ่ต่อหน่วยลาดตระเวนและคณะสำรวจทางใต้ ผู้ร่วมกำจัดจะได้ค่าตอบแทนงาม สอบถามรางวัลกับ Captain Vish Kozus บนยอดหอเฝ้าระวัง Cenarion Hold" },
        progress = { "75:1340180985:983351241", "ข้าต้องใช้ก้ามมันเป็นหลักฐาน ไม่มีก้าม ก็ไม่มีรางวัล" },
        completion = { "165:1524704841:1380542929", "ยอดเยี่ยม! เมื่อ Deathclasp ไม่อยู่ เราใช้เทือกเขาใต้เป็นทางยุทธศาสตร์อ้อมรังซิลิธิดได้ ขอบใจผลงานอย่างยิ่ง" },
        required = { [20385] = { "19:1204043785:287074033", "ก้ามของเดธแคลสป์" } },
        objectiveLabels = {
            item = { ["Deathclasp's Pincer"] = "ก้ามของเดธแคลสป์" },
        },
    },
    [8284] = { -- The Twilight Mystery
        title = { "20:1895562189:1376251298", "ปริศนาแห่ง Twilight" },
        objective = { "98:1606042800:2067567379", "รวบรวมเศษแผ่นจารึกสนธยา 8 ชิ้นให้ Geologist Larksbane ที่ Cenarion Hold ใน Silithus" },
        description = { "492:1625257812:2068649970", "ค่ายสาวก Twilight's Hammer เคยรุ่งเรืองทางตะวันตกเฉียงเหนือจากที่นี่ หากไปตอนนี้ จะพบธาตุเต็มพื้นที่ เหลือเพียงเศษไม้กับผ้าใบกระจายให้รู้ว่าค่ายเคยอยู่ตรงไหน\n\nข้าเก็บเศษจารึกดินเหนียวมาได้บ้าง แต่มีน้อยเกินประกอบเป็นประโยชน์ ลองหาเศษที่เหลือ เพื่อให้เข้าใจเหตุที่ Twilight's Hammer อยู่ใน Silithus" },
        progress = { "91:1054479018:935313928", "ค่ายที่พังอยู่ทางตะวันตกเฉียงเหนือจากที่นี่ กลับเมื่อได้เศษครบ" },
        completion = { "285:1413395079:2004021334", "ตรงที่สงสัย ข้าถอดคำบนจารึกทีละคำได้ แต่ดูไร้เหตุผลหรือความหมาย นิกาย Twilight's Hammer ใช้รหัสซ่อนความหมายกันอยู่แล้ว เราต้องหาผู้รู้เรื่องนี้มากกว่า" },
        required = { [20378] = { "24:1790496032:1290880332", "เศษแผ่นจารึกสนธยา" } },
        objectiveLabels = {
            item = { ["Twilight Tablet Fragment"] = "เศษแผ่นจารึกสนธยา" },
        },
    },
    [8285] = { -- The Deserter
        title = { "12:281634748:349907546", "ผู้แปรพักตร์" },
        objective = { "54:1842970239:1351847148", "นำจารึกที่ซ่อมแล้วไปให้ Hermit Ortell ที่ Silithus" },
        description = { "292:1552161049:1629634086", "มีข่าวว่าสมาชิก Twilight's Hammer ชื่อ Ortell หนีจากนิกายไป ซ่อนในภูเขาทางใต้ของ Southwind Village ใช้ชีวิตฤๅษี บางทีเจ้าขอให้ช่วยถอดจารึกได้\n\nนำจารึกที่ซ่อมแล้วไปตามหา Ortell" },
        progress = { "77:73340087:974944439", "เจ้า! หาข้าพบได้อย่างไร? เป็นใคร? ไม่มีคนตามมาใช่ไหม? พูด!" },
        completion = { "174:927140112:330280634", "ดูเหมือนเจ้ารู้จักองค์กรเก่าข้า คงมาจาก Cenarion Hold\n\nต้องการข้อมูลใช้ต้านพวกมันหรือ? เข้ามาใกล้ บางทีเราช่วยกันได้" },
    },
    [8286] = { -- What Tomorrow Brings
        title = { "20:391619081:1490077476", "สิ่งที่วันพรุ่งนำมา" },
        objective = { "81:532046038:754944253", "เดินทางไป Caverns of Time ที่ Tanaris ตามหา Anachronos ผู้สืบเชื้อสาย Nozdormu" },
        description = { "490:548559970:437044493", "ความตายแทบโอบคลุมข้าจนหมดเมื่อเขาเข้าช่วย เขาพ่นลมหายใจใส่กายพิการข้าเพียงครั้ง แล้วอดทนรอให้ทรายแห่งกาลเวลาชำระบาดแผล\n\nเขาบอกว่า หากจำเป็นเจ้าจะอยู่ตลอดกาล ด้วยถ้อยคำนั้นข้าจึงถูกผูกเป็นผู้เฝ้ามอง\n\nจงมองทะเลทราย บัดนี้สงครามครั้งที่สองมาถึง ต้องตามหาที่พักของฝูงมังกรสีบรอนซ์ ไป Caverns of Time ดูว่านายท่านกลับหรือยัง ข้าต้องแน่ใจก่อนดำเนินต่อ" },
        progress = { "24:1915048092:1493922370", "Anachronos กลับหรือยัง?" },
        completion = { "76:1281064070:1351034611", "เป็นเช่นที่ควร ผู้ยิ่งใหญ่ตื่นแล้ว การเฝ้าของข้าสิ้นสุด..." },
    },
    [8287] = { -- A Terrible Purpose
        title = { "18:1269530357:1707575684", "จุดหมายอันเลวร้าย" },
        objective = { "57:931117707:1506562435", "นำ Decoded Tablet Parchment ไปให้ Commander Mar'alith" },
        description = { "349:56597513:403824787", "เอาละ เรียบร้อย... ต้องบอกว่าเป็นข้อมูลมีค่ามาก! ข้าเห็นกองกำลัง Cenarion Circle มาถึง Silithus พวกเขาวางแผนขับ Twilight's Hammer ใช่ไหม? นี่ช่วยได้\n\nนำกระดาษนี้ไปให้ผู้นำ Commander Mar'alith อีกไม่นาน Twilight's Hammer จะถูกปราบ ข้าจะพ้นเงื้อมมือตลอดไป!" },
        progress = { "30:2111709139:1461491119 N 1:63:63", "นำอะไรมาให้ข้า {name}?" },
        completion = { "45:1427078317:488537528 N 178:669225551:1299674793 C 1:46:46", "ข้อมูลน่าสนใจมากจริง ๆ {name} ช่วยอธิบายเหตุที่ Twilight's Hammer อยู่ใน Silithus และช่วยเราต่อสู้แน่นอน ความพยายามเจ้าจะได้รางวัลคุ้มค่า {class}" },
    },
    [8301] = { -- The Path of the Righteous
        title = { "25:770932781:1617523689", "หนทางแห่งผู้เที่ยงธรรม" },
        objective = { "65:155590065:212334936", "รวบรวมเศษกระดองซิลิธิด 200 ชิ้น แล้วกลับไปหา Baristolth" },
        description = { "457:822719817:70766474", "Brood of Nozdormu ไม่ไว้ใจเผ่าพันธุ์ชั้นรองเป็นธรรมชาติ แม้เจ้าพิสูจน์ต่อข้าว่ามีแววเป็นวีรชน แต่ถึงเวลาพิสูจน์ต่อนายท่าน\n\nHive'Ashi, Hive'Zora, Hive'Regal ล้วนเคลื่อนไหวคึกคักและคุกคามการดำรงอยู่เรา สังหารซิลิธิดในรังแล้วเก็บเศษกระดอง เมื่อถือไม่ไหวอีก กลับมาหาข้า ข้าจะเสริมความมุ่งมั่นเจ้า" },
        progress = { "150:1581944479:1377155383", "มีประวัติมากมายฝังรากในความไม่ไว้ใจเผ่าพันธุ์ผู้มีอายุขัย แต่นั่นเป็นเรื่องที่ควรให้ฝูงมังกรเล่าเมื่อถึงเวลา" },
        completion = { "200:1089782202:474605219", "เจ้าไม่ได้อยู่ลำพัง วีรชน ข้าจะให้ความสามารถแต่งตั้งผู้ช่วยเพื่อร่วมภารกิจ หากจะเป็นยอดนักรบของชนชาติ เจ้าต้องมีคนช่วยงานและหน้าที่" },
        required = { [20384] = { "26:1152104473:1048360544", "เศษกระดองซิลิธิด" } },
        objectiveLabels = {
            item = { ["Silithid Carapace Fragment"] = "เศษกระดองซิลิธิด" },
        },
    },
    [8302] = { -- The Hand of the Righteous
        title = { "25:1413398153:1198854680", "มือแห่งผู้เที่ยงธรรม" },
        objective = { "65:155590065:212334936", "รวบรวมเศษกระดองซิลิธิด 200 ชิ้น แล้วกลับไปหา Baristolth" },
        description = { "199:1591083416:1779364027", "เลือกผู้ช่วยให้ดี ผู้มีอายุขัย ทุกครั้งที่กลับพร้อมงานสำเร็จ เจ้าจะเลือกผู้ช่วยใหม่ได้\n\nกล่าวแล้ว ข้าต้องการเศษกระดองเพิ่ม อย่าเสียเวลา!" },
        progress = { "78:1165215101:1089321873", "บางทีสักวัน Cenarion Hold ทั้งหมดอาจทำงานใต้บัญชาเจ้า" },
        completion = { "91:1375356045:508326233", "ทำได้ดี วีรชน เจ้าจะได้รับความสามารถแต่งตั้ง Agent of Nozdormu เพิ่มอีกคน" },
        required = { [20384] = { "26:1152104473:1048360544", "เศษกระดองซิลิธิด" } },
        objectiveLabels = {
            item = { ["Silithid Carapace Fragment"] = "เศษกระดองซิลิธิด" },
        },
    },
    [8303] = { -- Anachronos
        title = { "10:147410662:1427293121", "Anachronos" },
        objective = { "54:1434521281:892459465", "ตามหา Anachronos ที่ Caverns of Time ใน Tanaris" },
        description = { "12:376119921:82606574 N 189:82411724:51014496", "ถึงเวลาแล้ว {name}\n\nข้าต้องขอโทษที่ปิดบังมาก ศัตรูมีทุกที่ แม้ใต้จมูกเรา โปรดอ่านตำรานี้แล้วเรียนรู้ นำความรู้ที่ข้าให้ไปตามหานายท่าน" },
        completion = { "30:1027017557:1170947367 N 1:46:46", "เจ้าคือความหวัง Kalimdor {name}" },
    },
    [8304] = { -- Dearest Natalia
        title = { "15:233802214:1027251607", "Natalia ผู้เป็นที่รัก" },
        objective = { "259:331050567:993362667", "Commander Mar'alith ที่ Cenarion Hold ใน Silithus ต้องการให้เจ้าสอบถามคนใน Bronzebeard's Encampment ค่ายอยู่ทางใต้ของ Cenarion Hold\n\nเมื่อได้ข้อมูลที่ขอ กลับไปหา Commander Mar'alith" },
        description = { "397:1702953796:605842475 N 68:1518952337:1928579611", "Natalia ที่รักของข้าหายไป\n\nพูดตรง ๆ นางทำตัวแปลกหลายสัปดาห์ก่อนหาย ข้าพบพูดคนเดียวในที่ลับหลายครั้ง นางยืนยันว่าปกติทุกอย่าง และต้องได้วิจัยต่อ\n\nมีคนเห็นครั้งสุดท้ายมุ่งไปค่าย Bronzebeard ทางใต้\n\nทหารข้ากระจายจนกำลังไม่พอ {name} ต้องให้เจ้าไปถามคนแคระในค่าย" },
        progress = { "15:125506103:1820579572 N 1:33:33", "อย่าเสียเวลา {name}!" },
        completion = { "200:1475212606:63642910 N 1:63:63", "<Commander Mar'alith ก้มหน้าครุ่นคิด>\n\nไม่ว่านางเป็นหรือตาย ข้าต้องทำสิ่งถูกต้อง ต้องหาพบ แต่หน้าที่ผูกข้ากับด่านนี้ เจ้าจะช่วยอีกครั้งไหม {name}?" },
    },
    [8305] = { -- Long Forgotten Memories
        title = { "23:1018726742:1237443665", "ความทรงจำที่ถูกลืมเนิ่นนาน" },
        objective = { "65:718527179:797891256", "ตามหา Crystalline Tear ใน Silithus แล้วจ้องลึกเข้าไป" },
        description = { "260:1914058135:1034192052", "ในทะเลทรายใต้ของ Silithus ใกล้ม่านศักดิ์สิทธิ์ มีหยาดผลึกหนึ่งหยด เป็นสัญลักษณ์ความสูญเสียใหญ่ใน War of the Shifting Sands ตามหาแล้วจ้องลึกเพื่อรู้แจ้ง" },
        completion = { "142:510560479:305567425", "เจ้าสัมผัสความเศร้ามหาศาลรอบผลึก พลังแรงจนเหมือนจะทรุดและตายเพราะโศกเศร้า" },
    },
    [8306] = { -- Into The Maw of Madness
        title = { "23:4171475:940048288", "สู่ปากเหวแห่งความคลั่ง" },
        objective = { "435:920327843:1765591552", "Commander Mar'alith ที่ Cenarion Hold ใน Silithus ต้องการให้ตามหา Natalia ที่รัก ข้อมูลที่ได้ชี้ไป Hive'Regal ทางใต้ ซึ่งอาจพบ Mistress Natalia Mar'alith\n\nอย่าลืมไปหาคนแคระที่ค่าย Bronzebeard ก่อนเข้ารัง พวกเขาอาจมีงานและคำแนะนำเพิ่ม\n\nและ <Name> จงจำคำผู้บัญชาการ: ทำสิ่งที่เจ้าจำเป็นต้องทำ...", variants = { { "374:59357278:726391386 N 55:885587868:397528874", "Commander Mar'alith ที่ Cenarion Hold ใน Silithus ต้องการให้ตามหา Natalia ที่รัก ข้อมูลที่ได้ชี้ไป Hive'Regal ทางใต้ ซึ่งอาจพบ Mistress Natalia Mar'alith\n\nอย่าลืมไปหาคนแคระที่ค่าย Bronzebeard ก่อนเข้ารัง พวกเขาอาจมีงานและคำแนะนำเพิ่ม\n\nและ {name} จงจำคำผู้บัญชาการ: ทำสิ่งที่เจ้าจำเป็นต้องทำ..." } } },
        description = { "82:1365763782:952489851 N 301:654411599:413886678 N 100:1178668638:1870702761", "ข้าต้องให้เจ้าเข้า Hive'Regal ดูว่าเกิดอะไรกับ Natalia ที่รัก {name} งานนี้ไม่ง่ายหากลำพัง แนะนำให้พาเพื่อนไป ก่อนพุ่งสู่ปากเหวแห่งความคลั่ง กลับไปคุยกับคนแคระก่อน พวกเขาอาจแนะนำวิธีรับมือซิลิธิดในรัง\n\nและ {name} หากนางคลั่งจริงอย่างที่ว่า... ทำสิ่งที่จำเป็น\n\n<Commander Mar'alith หันหนี>" },
        progress = { "8:1806897191:560249840", "Natalia?" },
        completion = { "188:2091662068:1502560204", "<Commander Mar'alith กุมหน้าอก>\n\nC'Thun? ทั้งหมดหมายความว่าอะไร? C'Thun คืออะไร? อสูรนี่เปลี่ยน Natalia อ่อนหวานของข้าเป็นสิ่งที่เจ้าเล่าได้อย่างไร?" },
    },
    [8308] = { -- Brann Bronzebeard's Lost Letter
        title = { "31:949735841:1158710320", "จดหมายที่หายของ Brann Bronzebeard" },
        objective = { "81:1899924346:1774785273", "นำ Brann Bronzebeard's Letter ไป Bronzebeard's Encampment ทางใต้ของ Silithus" },
        description = { "477:230405806:1734444680", "ถึงผู้ที่เกี่ยวข้อง:\n\nหากอ่านอยู่ ข้าอาจตายหรือใกล้ตาย บอกยาก อย่างไรก็ดีลูกเรือส่วนใหญ่ตายแล้ว\n\nพบข้อมูลไททัน ศึกใหญ่กับ Old God ใช่ Old God จริง พบอุโมงค์โบราณสู่ Ahn'Qiraj กำลังเข้าไป\n\nนำจดหมายไปค่ายเก่า ดูให้ลิงข้าได้อาหาร น้ำ และกอดเพียงพอ\n\n-Brann Bronzebeard นักสำรวจสุดขั้ว\n\nป.ล. ระวังไนต์เอลฟ์คลั่งบูชา Old God" },
        progress = { "8:1459120288:911780184", "โอ้ แย่แล้ว" },
        completion = { "150:314865108:1198017426", "นี่อธิบายได้มาก หากพบทางเข้า Ahn'Qiraj จงมองหา Brann ด้วย ข้ากลัวว่าไม่มีลิงเขาจะหมดพลัง" },
    },
    [8309] = { -- Glyph Chasing
        title = { "13:1727245107:1419186513", "ตามรอยอักขระ" },
        objective = { "338:1922935292:1162531987", "Rutgar Glyphshaper ที่ Bronzebeard's Encampment ใน Silithus ต้องการให้เจ้าเข้าไปใน Hive'Ashi, Hive'Zora และ Hive'Regal เพื่อทำสำเนาถูอักขระจากผลึกจารึกของแต่ละรัง\n\nใช้ชุดถอดจารึกของนักธรณีวิทยาทำสำเนาอักขระโบราณให้ใกล้เคียงต้นฉบับ แล้วกลับไปหา Rutgar Glyphshaper" },
        description = { "413:741380853:463931963 N 60:1318733119:1681845502", "หลังเราเข้ารังครั้งแรกและ Mistress Mar'alith คลั่งตามมา รังทั้งสามก็ปล่อยแมลงออกไม่หยุด! ความเคลื่อนไหวอาจเกี่ยวกับอักขระบนผลึกแปลก\n\nต้องทำสำเนาถูอักขระจากผลึกทั้งสามรัง หากมี เราอาจเข้าใจความคลั่งนี้\n\nนำชุดคัดลอกกับเพื่อนไปรังเหล่านั้น {name} อย่ากลับจนได้สำเนาจากแต่ละรัง" },
        progress = { "105:551614255:975478625", "หากพบสาวไนต์เอลฟ์คลั่งในรัง ช่วยเตะก้นให้นางแทนเราด้วย" },
        completion = { "138:116330728:525966409", "ข้าอ่านอักขระไม่รู้เรื่อง ไม่เคยเห็นเช่นนี้! หวังว่างานวิจัย Frankal จะอธิบายความยุ่งเหยิงนี้ได้" },
        required = { [20455] = { "17:1252507331:904116083", "สำเนาถูอักขระจากรังอาชิ" }, [20454] = { "17:1510079169:1657372766", "สำเนาถูอักขระจากรังโซรา" }, [20456] = { "18:1388307544:2078328830", "สำเนาถูอักขระจากรังรีกัล" } },
        objectiveLabels = {
            item = { ["Hive'Ashi Rubbing"] = "สำเนาถูอักขระจากรังอาชิ", ["Hive'Zora Rubbing"] = "สำเนาถูอักขระจากรังโซรา", ["Hive'Regal Rubbing"] = "สำเนาถูอักขระจากรังรีกัล" },
        },
    },
    [8310] = { -- Breaking the Code
        title = { "17:1210864871:1753794693", "ไขรหัส" },
        objective = { "220:882729119:1805845705", "เก็บสมองซิลิธิดจากรังโซรา รังอาชิ และรังรีกัลให้ Frankal Stonebridge ที่ Bronzebeard's Encampment ใน Silithus เมื่อได้ครบแล้วกลับไปหา Frankal" },
        description = { "310:243661615:731522507", "ข้าว่าทำยาให้เราเข้าใจอักขระกับภาษาซิลิธิดและ Qiraji ได้ง่ายขึ้น! ต้องการอะไรหรือ? ดีที่ถาม! สมอง! เจาะจงคือสมองจากซิลิธิดแต่ละชนิดในรัง นำมาแล้วงาน Rutgar อาจไม่สูญเปล่า" },
        progress = { "57:1293537702:1547358755", "ไปเล่นกับลิงเถอะ เจ้าหนู ข้าไม่มีเวลาสำหรับเรื่องนี้" },
        completion = { "93:701570093:973933689", "ยอดเยี่ยม! อย่าไปไกล เจ้าหนู เราอาจให้งานอีกสักอย่างสองอย่าง" },
        required = { [20457] = { "24:476386234:1518204640", "สมองซิลิธิดจากรังอาชิ" }, [20458] = { "24:303407897:413314444", "สมองซิลิธิดจากรังโซรา" }, [20459] = { "25:687946146:1530663474", "สมองซิลิธิดจากรังรีกัล" } },
        objectiveLabels = {
            item = { ["Hive'Ashi Silithid Brain"] = "สมองซิลิธิดจากรังอาชิ", ["Hive'Zora Silithid Brain"] = "สมองซิลิธิดจากรังโซรา", ["Hive'Regal Silithid Brain"] = "สมองซิลิธิดจากรังรีกัล" },
        },
    },
    [8314] = { -- Unraveling the Mystery
        title = { "22:1398851670:656665197", "คลี่คลายปริศนา" },
        objective = { "150:1742866254:937425226", "Rutgar Glyphshaper ที่ Bronzebeard's Encampment ต้องการให้ส่ง Glyphed Crystal Prism ไปให้ Geologist Larksbane ที่ Cenarion Hold ใน Silithus" },
        description = { "38:1894141001:1514137438 N 444:494420667:539471379", "เราใกล้ค้นพบครั้งใหญ่ {name}! สำเนาที่เจ้านำมาช่วยให้สร้างอักขระบนปริซึมนี้ใหม่ ดูเป็นวิธีที่ Qiraji กับสิ่งไม่ทราบชนิดสื่อสารสารต่าง ๆ ไปยังซิลิธิด\n\nเสียดายที่อ่านได้เท่านี้ ต้องหาวิธีปลดข้อความที่ซ่อนในผลึก\n\nนำ Glyphed Crystal Prism ไป Geologist Larksbane ที่ Cenarion Hold นางอาจช่วยได้" },
        progress = { "31:1044885854:328423872 N 1:63:63", "โอ้! เอาอะไรมา {name}?" },
        completion = { "441:1627853965:912567178", "คนแคระถอดอักขระไม่ได้ เพราะไม่มีอะไรให้ถอด ชั้นนอกปริซึมที่เลื่อนได้ต้องตรงกับรอยผลึกข้างใน จึงส่งข้อความได้ ฉลาด...\n\nแม้น่าจะแปลข้อมูลได้ แต่ต้องไขรหัสก่อน มีเบาะแสเดียวบนผิว หากคัดลอกสำเนาถูก และมันดูเลวร้าย" },
    },
    [8315] = { -- The Calling
        title = { "11:1243481772:602872392", "เสียงเรียก" },
        objective = { "435:1989073604:1493113250", "Geologist Larksbane ที่ Cenarion Hold ใน Silithus ต้องการให้เจ้านำกลไกปลดล็อกผลึกมาจากทูตคิราจี\n\nนำอักขระอัญเชิญไปที่ Bones of Grakkarond ทางใต้ของ Cenarion Hold แล้ววาดอักขระลงบนทราย หากทูตคิราจีปรากฏตัว ให้สังหารมันและนำกลไกปลดล็อกผลึกกลับไปหา Geologist Larksbane\n\nจงรวบรวมกองทัพสำหรับงานนี้ {name}!" },
        description = { "507:1973768833:1770767665", "อักขระแสดงทูต Qiraji พบซิลิธิดสามตัวที่กระดูกมังกรใหญ่ ด้านบนมีสิ่งที่ข้าคิดว่าเป็นรหัส อาจเป็นกุญแจอัญเชิญทูต\n\nข้าจะคัดรหัสให้เจ้าใช้บนทรายที่ Bones of Grakkarond หากคิดถูก พวก Overlord จะมาเพราะคิดว่ามีข้อมูลใหม่พร้อมส่ง โค่นมันแล้วเผชิญทูต เขาถือกุญแจผลึก..." },
        progress = { "63:585617241:735724799", "ต้องฉวยโอกาสเมื่อมาถึงแล้วโจมตี!" },
        completion = { "44:50883659:856752567 N 1:33:33", "ข้าถือประวัติศาสตร์ 20,000 ปีในมือ {name}!" },
        required = { [20465] = { "27:1811240754:702304547", "กลไกปลดล็อกผลึก" } },
        objectiveLabels = {
            item = { ["Crystal Unlocking Mechanism"] = "กลไกปลดล็อกผลึก" },
        },
    },
    [8316] = { -- Armaments of War
        title = { "16:438605517:1549743200", "ยุทโธปกรณ์สงคราม" },
        completion = { "11:1979435825:1379615665 N 313:1806025045:815826898", "สงครามมาแล้ว {name} พร้อมความสยองเกินบอก เจ้าทำทุกอย่างที่ขอได้ สมควรรับรางวัล\n\nหาก... หากคำทำนายเป็นจริง...\n\n<Geologist Larksbane หน้าซีด>\n\nอนาคตเราทั้งหมดอาจสิ้นสุด\n\nยุทโธปกรณ์เหล่านี้จะมีค่ายิ่งต่อการรณรงค์ในทะเลทราย" },
    },
    [8318] = { -- Secret Communication
        title = { "20:1532133740:482065243", "การสื่อสารลับ" },
        objective = { "67:72265123:1862321924", "นำ Encrypted Twilight Text 10 ชิ้นไปให้ Bor Wildmane ที่ Cenarion Hold" },
        description = { "138:350172770:815130163 C 212:641939095:1432522588", "สาวก Twilight's Hammer บางคนพกกระดาษเขียนคำไร้สาระ ข้าอยากให้เจ้ารวบรวมมา {class}\n\nข้าอ่านไม่รู้เรื่อง แต่ไม่ใช่ประเด็น! กระดาษนี้ใช้สื่อสารลับระหว่างกลุ่ม ยิ่งเราเก็บออกมากเท่าไร พวกมันยิ่งสื่อสารได้น้อย!" },
        progress = { "28:1578601603:647249000", "นำข้อความมาบ้างหรือยัง?" },
        completion = { "64:681641348:1559292314", "ยอดเยี่ยม! ข้าจะเก็บไว้ บางทีมีประโยชน์ภายหลัง" },
        required = { [20404] = { "23:380383127:782918379", "ข้อความเข้ารหัสของ Twilight" } },
        objectiveLabels = {
            item = { ["Encrypted Twilight Text"] = "ข้อความเข้ารหัสของ Twilight" },
        },
    },
    [8319] = { -- Encrypted Twilight Texts
        title = { "24:1121699639:1630577201", "เอกสารเข้ารหัส Encrypted Twilight Text" },
        progress = { "79:2073796957:2100135102", "นำเอกสารมาเรื่อย ๆ อีกไม่นานเราจะขับ Twilight's Hammer จาก Silithus" },
        completion = { "48:1531842043:281619117", "งานยอดเยี่ยม! ข้าจะพูดถึงเจ้าในทางดี" },
