    [8320] = { -- Twilight Geolords
        title = { "17:1770003358:521923358", "เหล่า Twilight Geolord" },
        objective = { "73:1502648275:1466893745", "สังหาร Twilight Geolord 10 คน แล้วกลับไปหา Huum Wildmane ที่ Cenarion Hold" },
        description = { "468:1019821139:1304790643", "Twilight's Hammer ลัทธิคลั่งมุ่งทำลาย ตั้งค่ายใน Silithus และทำพิธีทั้งวันคืน ยังไม่รู้แผน แต่คิดว่าเกี่ยวกับผลึกแดงเต้นเป็นจังหวะทั่วทะเลทราย\n\nแม้สักวันอาจไขปริศนาได้ ตอนนี้ต้องจัดการภัยเฉพาะหน้า ไปค่ายทางตะวันตกหา Twilight Geolord พวกมันคือหัวงู นั่นคือจุดที่ต้องโจมตี!" },
        progress = { "49:119672886:199828105 N 36:316547867:1617123613", "เข้าไปทะเลทรายหา Twilight Geolord {name} สังหารแล้วกลับมาหาข้า" },
        completion = { "32:917898140:1624969807 N 122:913231697:1898664367", "งานสำเร็จดี {name} การฆ่า Twilight Geolord ต้องสร้างความเสียหายหนักต่อลัทธิ หวังว่าแผนมันจะช้าลง..." },
        objectiveLabels = {
            monster = { ["Twilight Geolord slain"] = "ปราบ จ้าวพิภพ Twilight" },
        },
    },
    [8321] = { -- Vyral the Vile
        title = { "14:1692218231:654001248", "Vyral ผู้ชั่วร้าย" },
        objective = { "60:1643225839:1011275076", "นำแหวนตราของไวรัลไปให้ Huum Wildmane ที่ Cenarion Hold" },
        description = { "326:183428694:1184605207 N 54:1730213086:1159731424", "เราพบฐาน Twilight's Hammer อีกแห่ง ชื่อ Twilight's Run เป็นถ้ำซ่อนในมุมตะวันออกเฉียงเหนือ Silithus ผู้นำท้องถิ่น Vyral the Vile อยู่ในถ้ำนั้น เขาคือเป้าหมายต่อไป ปราบแล้วนำแหวนตรากลับมา\n\nขอให้โชคดี {name} ความสยองใน Twilight's Run น่ากลัวจริง ๆ" },
        progress = { "N 68:1008976597:80677759", "{name} ปราบ Vyral the Vile แล้วหรือ? มีแหวนตราไหม?" },
        completion = { "238:1080003997:1335151010", "ทำได้แล้ว! Vyral ตาย! งาน Twilight's Hammer ใน Silithus ต้องตกต่ำแน่ แม้ยังมีพวกมันวิ่งวุ่น แต่ความเสียหายที่เจ้าสร้างวันนี้ฟื้นตัวไม่ง่าย" },
        required = { [20466] = { "19:1638523293:1939315199", "แหวนตราของไวรัล" } },
        objectiveLabels = {
            item = { ["Vyral's Signet Ring"] = "แหวนตราของไวรัล" },
        },
    },
    [8323] = { -- True Believers
        title = { "14:1587321550:554460302", "ผู้ศรัทธาแท้จริง" },
        objective = { "64:1725204251:864137294", "Hermit Ortell ต้องการ Encrypted Twilight Text 10 ชิ้น" },
        description = { "498:453696753:25493694", "เมื่อข้ามี Twilight Lexicon แล้ว อยากขอให้ช่วยเล็กน้อย\n\nองค์กรเก่ามีจดหมายข่าวลับเข้ารหัสเวียนทุกเดือน\n\nหากตามหาข้าคืบหน้า หรือเลิกค้น ข่าวจะอยู่ใน True Believer\n\nแน่นอนว่ามีค่าต่อข้า แต่ยังมีข้อมูลอื่นที่แบ่งปันได้ นำเอกสารเข้ารหัสที่พบจากสมาชิก Twilight's Hammer มาให้ข้า" },
        progress = { "87:497144923:262944684", "พบเอกสารเข้ารหัสไหม? ข้าอยากอ่าน True Believer เดือนนี้มาก" },
        completion = { "141:718476108:694947161", "ยอดเยี่ยม! ข้าจะถอดรหัสโดยเร็ว หากพบสิ่งน่าสนใจ จะหาทางส่งข้อมูลให้เจ้า" },
        required = { [20404] = { "23:380383127:782918379", "ข้อความเข้ารหัสของ Twilight" } },
        objectiveLabels = {
            item = { ["Encrypted Twilight Text"] = "ข้อความเข้ารหัสของ Twilight" },
        },
    },
    [8324] = { -- Still Believing
        title = { "15:2061491645:1766770746", "ยังคงศรัทธา" },
        progress = { "97:1892977806:368753098", "พบเอกสารเข้ารหัสเพิ่มไหม? นำมาชุดใหญ่หน่อย การถอดต้องใช้เวลา" },
        completion = { "105:1034814148:316552184", "ยอดเยี่ยม! แทบรออ่านไม่ไหว หากพบอีกก็นำมาที่นี่เรื่อย ๆ" },
        description = { "97:1892977806:368753098", "พบเอกสารเข้ารหัสเพิ่มไหม? นำมาชุดใหญ่หน่อย การถอดต้องใช้เวลา" },
        required = { [20404] = { "23:380383127:782918379", "ข้อความเข้ารหัสของ Twilight" } },
        objectiveLabels = {
            item = { ["Encrypted Twilight Text"] = "ข้อความเข้ารหัสของ Twilight" },
        },
    },
    [8331] = { -- Aurel Goldleaf
        title = { "14:1474865863:1127870280", "Aurel Goldleaf" },
        objective = { "43:817932023:1192647998", "คุยกับ Aurel Goldleaf ที่ Cenarion Hold" },
        description = { "N 328:368081962:852454842 N 167:478510051:367686813", "{name} แม้หวังว่างาน Twilight's Hammer ใน Silithus ช้าลง แต่น่าเสียดายที่เราคิดผิด การบุกต่อเนื่องเผยว่ามีพลังมืดยิ่งกว่า Abyssal Council คุมพวกมันผ่าน Wind Stone อาร์เคนตามค่าย งานต่อไปของเจ้า {name} คือต้านสภานี้\n\nคุยกับช่าง Aurel Goldleaf ทางตะวันออกของ Cenarion Hold ต้องใช้ฝีมือนางในแผนต่อไป" },
        completion = { "N 128:769436062:1826698340", "{name} สวัสดี ได้ยินว่าเจ้าจะสู้ Abyssal Council หรือ? หากจริง ฟังคำต่อไปให้ดี..." },
    },
    [8332] = { -- Dukes of the Council
        title = { "20:444321929:2102442931", "เหล่าดยุกแห่งสภา" },
        objective = { "86:702545522:1482266324", "นำเศษผลึกเจิดจ้าขนาดใหญ่ 1 ชิ้นและตราประจำตนแห่งห้วงลึก 3 อันไปให้ Aurel Goldleaf ที่ Cenarion Hold" },
        description = { "448:544500076:108083610", "เราคิดว่าใช้ Wind Stone ล่อ Duke แห่ง Abyssal Council มาโจมตีได้ แต่ต้องสื่อสารผ่านหินให้สภาเชื่อว่าเจ้าเป็นผู้นำระดับกลางของ Twilight's Hammer\n\nต้องมีเหรียญตำแหน่งเลียนแบบของลัทธิ ข้าสร้างได้ แต่ต้องใช้ Large Brilliant Shard กับตรา Crest ที่ Abyssal Templar สวม\n\nนำมาแล้วข้าจะจัดการที่เหลือ" },
        progress = { "38:1649313223:820268978 N 71:832562184:747170861", "มีชิ้นผลึกกับ Crest หรือยัง {name}? ข้าต้องใช้ทำเหรียญตำแหน่งสาวก Twilight" },
        completion = { "160:1606130883:1168541008 N 221:559158468:1363901446", "อา ดีมาก ข้าทำเหรียญไว้แล้ว มีส่วนประกอบสุดท้ายนี้ อีกครู่ก็เสร็จ...\n\nเรียบร้อย นี่เหรียญ {name}\n\nต้องสวมเมื่อเปิดใช้ Wind Stone ของ Twilight's Hammer สวมพร้อมเครื่องแต่งกาย Twilight ที่เหลือ แล้ว Abyssal Council จะเห็นเจ้าเป็นสาวกรับใช้คนหนึ่ง" },
        required = { [14344] = { "21:390863609:542366453", "เศษผลึกเจิดจ้าขนาดใหญ่" }, [20513] = { "13:196102275:883020759", "ตราประจำตนแห่งห้วงลึก" } },
        objectiveLabels = {
            item = { ["Large Brilliant Shard"] = "เศษผลึกเจิดจ้าขนาดใหญ่", ["Abyssal Crest"] = "ตราประจำตนแห่งห้วงลึก" },
        },
    },
    [8333] = { -- Medallion of Station
        title = { "20:1246858084:814820952", "เหรียญ Medallion of Station" },
        progress = { "160:8290223:1687949295", "หากต้องการเหรียญตำแหน่งสาวก Twilight อีก ข้ายินดีทำให้ แต่ต้องใช้ชิ้นผลึกเจิดจ้าอีกชิ้นและ Abyssal Crest บางส่วน..." },
        completion = { "14:510644690:581245021 N 103:404751068:1765723296", "นี่ {name} Twilight Medallion of Station อีกอัน ใช้ให้ดี ขอให้โชคดีต่อกร Abyssal Council!" },
        description = { "160:8290223:1687949295", "หากต้องการเหรียญตำแหน่งสาวก Twilight อีก ข้ายินดีทำให้ แต่ต้องใช้ชิ้นผลึกเจิดจ้าอีกชิ้นและ Abyssal Crest บางส่วน..." },
        required = { [14344] = { "21:390863609:542366453", "เศษผลึกเจิดจ้าขนาดใหญ่" }, [20513] = { "13:196102275:883020759", "ตราประจำตนแห่งห้วงลึก" } },
        objectiveLabels = {
            item = { ["Large Brilliant Shard"] = "เศษผลึกเจิดจ้าขนาดใหญ่", ["Abyssal Crest"] = "ตราประจำตนแห่งห้วงลึก" },
        },
    },
    [8341] = { -- Lords of the Council
        title = { "20:1004137831:141990925", "เหล่าลอร์ดแห่งสภา" },
        objective = { "88:715731301:1129149240", "นำเศษผลึกเจิดจ้าขนาดใหญ่ 5 ชิ้นและตราประทับแห่งห้วงลึก 3 อันไปให้ Aurel Goldleaf ที่ Cenarion Hold" },
        description = { "417:1122985261:2056368333", "Lord แห่ง Abyssal Council อัญเชิญได้ผ่าน Greater Wind Stone เท่านั้น และมีแต่ผู้นำสูงสุดของสภา Twilight ที่คุยได้ แต่... ข้าพบวิธียกระดับการปลอมตัวหลอก Abyssal Lord!\n\nต้องใช้ Ring of Lordship ที่สมาชิกสูงสุดสวม ข้าจะทำให้หากนำ Large Brilliant Shard กับ Abyssal Signet มา" },
        progress = { "40:1397434561:1408023860 N 50:543051008:451317095", "มีชิ้นผลึกกับ Signet หรือยัง {name}? ข้าต้องใช้สร้าง Ring of Lordship" },
        completion = { "354:2080229299:88591681", "ขอบใจ รอครู่เดียวแหวนก็พร้อม...\n\nนี่ไง เจ้าพร้อมแล้ว\n\nต้องสวมแหวนพร้อม Medallion of Station และเครื่องแต่งกาย Twilight ที่เหลือเมื่อเปิด Greater Wind Stone ทำเช่นนั้น Abyssal Council จะคิดว่าเจ้าเป็นข้ารับใช้ แล้วบางทีเจ้าล่อหนึ่งในนั้นมาซุ่มโจมตีได้!" },
        required = { [14344] = { "21:390863609:542366453", "เศษผลึกเจิดจ้าขนาดใหญ่" }, [20514] = { "14:979633554:157029224", "ตราประทับแห่งห้วงลึก" } },
        objectiveLabels = {
            item = { ["Large Brilliant Shard"] = "เศษผลึกเจิดจ้าขนาดใหญ่", ["Abyssal Signet"] = "ตราประทับแห่งห้วงลึก" },
        },
    },
    [8342] = { -- Twilight Ring of Lordship
        title = { "25:657038884:361181786", "แหวน Twilight Ring of Lordship" },
        progress = { "N 169:371191742:1805406645", "{name} หากจะไล่ล่า Abyssal High Council อีก ต้องใช้ Twilight Ring of Lordship อีกวง นำชิ้นผลึกกับ Signet เพิ่ม ข้าจะทำให้", variants = { { "N 169:1872503584:149315992", "{name} หากจะไล่ล่า Abyssal High Council อีก ต้องใช้ Twilight Ring of Lordship อีกวง นำชิ้นผลึกกับ Signet เพิ่ม ข้าจะทำให้" } } },
        completion = { "100:1678709323:465619987 N 46:1391367920:1962663258", "อา เจ้ามีความตั้งใจแน่วแน่ น้อยคนจะเผชิญสภาอสูรนั้น!\n\nนี่แหวน {name} ขอเจตจำนงและโชคยืนหยัด" },
        description = { "N 169:1872503584:149315992", "{name} หากจะไล่ล่า Abyssal High Council อีก ต้องใช้ Twilight Ring of Lordship อีกวง นำชิ้นผลึกกับ Signet เพิ่มมาให้ข้า แล้วข้าจะทำให้" },
        required = { [20514] = { "14:979633554:157029224", "ตราประทับแห่งห้วงลึก" }, [14344] = { "21:390863609:542366453", "เศษผลึกเจิดจ้าขนาดใหญ่" } },
        objectiveLabels = {
            item = { ["Abyssal Signet"] = "ตราประทับแห่งห้วงลึก", ["Large Brilliant Shard"] = "เศษผลึกเจิดจ้าขนาดใหญ่" },
        },
    },
    [8343] = { -- Goldleaf's Discovery
        title = { "20:1091226543:65772180", "การค้นพบของ Goldleaf" },
        objective = { "43:817932023:1192647998", "คุยกับ Aurel Goldleaf ที่ Cenarion Hold" },
        description = { "N 265:135332884:1671619556 N 38:924250824:1997303776", "{name} Aurel Goldleaf คิดว่าพบวิธีอัญเชิญและปราบสมาชิกผู้ปกครอง Abyssal Council! อันตรายแน่ แต่เจ้าสร้างความเคารพมากใน Cenarion Circle เรารู้ว่าหากมีใครทำได้ ก็คือเจ้า\n\nขอให้โชคอยู่ด้วย {name} คุยกับ Aurel เมื่อพร้อม" },
        completion = { "118:1033365451:1382771644", "Huum พูดจริง ข้าเชื่อว่ารู้วิธีอัญเชิญ Lord แห่ง Abyssal Council! ฟังต่อแล้วข้าจะอธิบาย..." },
    },
    [8348] = { -- Signet of the Dukes
        title = { "19:537797911:955000771", "ตราของเหล่าดยุก" },
        objective = { "58:32802562:1150778517", "นำตราประทับแห่งห้วงลึกไปให้ Bor Wildmane ที่ Cenarion Hold" },
        description = { "314:1193188864:1989393896", "Huum บอกว่าเจ้ารู้วิธีอัญเชิญ Abyssal Duke แล้ว! ความสำเร็จใหญ่ทีเดียว\n\nรู้อะไรจะยิ่งใหญ่ด้วยไหม? อัดหนึ่งในนั้นให้เละ จะทำให้ลูกสมุนจำฝังใจ เข้าใจนะ นำ Signet เป็นหลักฐานกลับมา" },
        progress = { "53:17946886:1454554840", "กับ Abyssal Duke เป็นอย่างไร? มันตีหนักไหม?" },
        completion = { "24:1508570121:1049317596 C 58:1348764041:915927334", "ข้ารู้ว่าเจ้าเป็น{class}แข็งแกร่งตั้งแต่เห็นเดินเข้า Cenarion Hold ทำต่อไป!" },
        required = { [20514] = { "14:979633554:157029224", "ตราประทับแห่งห้วงลึก" } },
        objectiveLabels = {
            item = { ["Abyssal Signet"] = "ตราประทับแห่งห้วงลึก" },
        },
    },
    [8349] = { -- Bor Wildmane
        title = { "12:474488319:1152983946", "Bor Wildmane" },
        objective = { "41:1213960777:10646107", "คุยกับ Bor Wildmane ที่ Cenarion Hold" },
        description = { "153:616806762:1364865747 N 53:695951737:1815522965", "เมื่อมีเหรียญและอัญเชิญ Abyssal Duke ได้แล้ว ไปคุย Bor Wildmane เขาจะมอบงานต้าน Abyssal Council\n\nโชคดี {name} หากต้องการเหรียญเพิ่ม กลับมาหาข้า" },
        completion = { "23:140679440:2097538806 C 78:1505588392:482380177", "ดีใจที่พบอีก {class}! ให้ทำเหรียญแล้วหรือ? ดี ต้องใช้ในภารกิจต่อไป..." },
    },
    [8351] = { -- Bor Wishes to Speak
        title = { "19:369551224:2130281041", "Bor ต้องการคุยด้วย" },
        objective = { "41:1213960777:10646107", "คุยกับ Bor Wildmane ที่ Cenarion Hold" },
        description = { "198:803121461:639793952", "เมื่อปลอมเป็นสมาชิกปกครองสภา Twilight ได้ ข้ามั่นใจ Bor Wildmane จะอยากคุย ไปพบแล้วเตรียมรับภารกิจยากมาก..." },
        completion = { "19:569046679:1506043024 N 35:159792196:1978339105", "ใช่แล้ว {name} ข้ามีงานยากรออยู่..." },
    },
    [8352] = { -- Scepter of the Council
        title = { "22:2008495673:1534174092", "คทาแห่งสภา" },
        objective = { "58:7365715:1420248942", "นำคทาแห่งห้วงลึกไปให้ Bor Wildmane ที่ Cenarion Hold" },
        description = { "450:290250246:317852770", "Huum กับข้าเพิ่งคุยถึงเจ้า เขาบอกว่าเกือบพร้อมลองสู้ Abyssal Lord แล้ว!\n\nต้องบอกว่างานนี้อันตรายมาก ควรมีกำลังหนุน ไม่ใช่เพื่อนหนึ่งหรือสองคน แต่กองกำลังชั้นยอดพร้อมรบ หากเพื่อนเก่งเช่นเจ้า อาจปราบได้!\n\nหากทำได้ ข้าต้องการหลักฐานเช่นเคย แล้วจะให้รางวัลใหญ่จริง ๆ" },
        progress = { "93:1747265532:1839624982", "เป็นอย่างไร? ข้ายอมทำทุกอย่างเพื่อทิ้งหน้าที่ไปปล้ำสิ่งนั้นเอง!" },
        completion = { "31:199202629:1625160318 N 115:559897877:548593530", "เจ้า... ทำได้! ทำได้แล้ว {name}! นี่! รับไป หีบใหญ่สุดที่เรามี ข้าใส่ของดีที่สุดบางส่วนที่พบไว้เต็ม" },
        required = { [20515] = { "15:1547074354:1110521613", "คทาแห่งห้วงลึก" } },
        objectiveLabels = {
            item = { ["Abyssal Scepter"] = "คทาแห่งห้วงลึก" },
        },
    },
    [8361] = { -- Abyssal Contacts
        title = { "16:142772156:1995824317", "ติดต่อเหล่า Abyssal" },
        objective = { "134:1522002303:199581268", "Bor Wildmane ที่ Cenarion Hold ใน Silithus ต้องการให้เจ้ากำจัด Abyssal Templar แล้วนำตราประจำตนแห่งห้วงลึกมาให้เขาเป็นหลักฐาน" },
        description = { "489:841887587:1290262084", "เราเห็นสาวก Twilight's Hammer ทำพิธีอัญเชิญขุนนางธาตุทรงพลัง ไม่รู้ว่าเป็นสิ่งที่บูชาหรือคนกลางสู่พลังยิ่งกว่า แน่อย่างหนึ่ง สาวกรับคำสั่งจากธาตุเหล่านี้\n\nข้าอยากให้หาวิธีติดต่อ Abyssal Templar แล้วอัดให้เต็มที่! ไม่มีอะไรทำทหารระส่ำเท่าตัดสายบัญชา อย่าลืมนำหลักฐานกลับ" },
        progress = { "23:1106813771:1974939902", "ทำงานเสร็จหรือยัง?" },
        completion = { "17:1208888390:571281440 N 45:1730935229:1524280088", "ฮ่า! ทำได้แล้ว {name}! อีกไม่นาน Twilight's Hammer จะถูกบดขยี้!" },
        required = { [20513] = { "13:196102275:883020759", "ตราประจำตนแห่งห้วงลึก" } },
        objectiveLabels = {
            item = { ["Abyssal Crest"] = "ตราประจำตนแห่งห้วงลึก" },
        },
    },
    [8362] = { -- Abyssal Crests
        title = { "14:1006160909:1859087207", "ตรา Abyssal Crest" },
        progress = { "50:1141048170:1005781053 N 163:764467170:1572834187", "เจ้าพิสูจน์ว่าต่อสู้ดูแลตัวเองได้ {name} กดดัน Twilight's Hammer ต่อ ไปสู้ Abyssal Templar เพิ่ม ข้าจะให้ของบางส่วนที่ Huum กับข้าพบในศึก" },
        completion = { "75:382090916:2116531121 N 49:313632113:298707658", "ทำได้ดี! Templar ที่ต้องห่วงน้อยลงแล้ว\n\nนี่ {name} หวังว่าข้างในมีของใช้ประโยชน์ได้" },
