    [8507] = { -- Field Duty
        title = { "10:1522187184:1115698288", "หน้าที่ภาคสนาม" },
        objective = { "326:1884416859:1460426735", "ไปรายงานตัวที่ด่าน Ironforge Brigade ใกล้ Hive'Zora เตรียมเอกสารหน้าที่ภาคสนามที่ยังไม่ได้ลงนาม รับเอกสารหน้าที่ภาคสนามที่ลงนามแล้วจาก Captain Blackanvil แล้วกลับไปหา Windcaller Kaldon ที่ Cenarion Hold ใน Silithus\n\nหมายเหตุ: หากรักษาหรือร่ายเวทช่วยเหลือใส่สมาชิก Ironforge Brigade เจ้าจะติดสถานะ PvP" },
        description = { "11:927657569:725753248 N 463:881795667:1661599889", "สวัสดี {name} ก่อนมอบงานสงครามซับซ้อนขึ้น เจ้าต้องทำหน้าที่ภาคสนามส่วนของตนก่อน\n\nพบ Ironforge Brigade ของ Captain Blackanvil นอก Hive'Zora\n\nรายงานเขาหรือรอง Janela Stouthammer แล้วกลับมา ข้าจะเตรียมงานก้าวหน้ากว่าไว้ให้\n\nและช่วยอยู่ห่าง Orgrimmar Legion ด้วย เราจำต้องแยกสองกองไกลกันเพราะเกลียดชังกัน" },
        progress = { "134:935461459:119892670", "กองกำลัง Captain Blackanvil อยู่ด้านนอก Hive'Zora หากไม่พบเขา คุยกับรอง Janela Stouthammer" },
        completion = { "11:1598769728:2013240452 N 254:214463294:974436211", "ดีมาก {name} ข้าเตรียมงานชุดที่น่าจะใช้ฝีมือเจ้าได้คุ้มที่สุด\n\nด้วยความพยายามต่อเนื่องของเจ้าและคนเช่นเจ้า อีกไม่นานศัตรูจะถูกปราบสิ้น!\n\nหากต้องการเอกสารชี้แจงใหม่ กลับไป Captain Blackanvil" },
        required = { [20810] = { "24:567143645:1458251977", "เอกสารหน้าที่ภาคสนามที่ลงนามแล้ว" } },
        objectiveLabels = {
            item = { ["Signed Field Duty Papers"] = "เอกสารหน้าที่ภาคสนามที่ลงนามแล้ว" },
        },
    },
    [8508] = { -- Field Duty Papers
        title = { "17:945632330:1904348284", "เอกสารหน้าที่ภาคสนาม" },
        progress = { { "44:562759334:1247430964", "45:748748651:204964770" }, "ข้าเดาว่าอยากให้ลงนามเอกสาร เจ้าหนู?" },
        completion = { "164:96166039:1194505710", "ได้ ข้าว่าศึกเล็กนั่นคงนับเป็นหน้าที่ภาคสนามสมัยนี้ นำกลับ Cenarion Hold แน่ใจว่ามีงานสบายเตรียมให้\n\nไปได้!" },
        description = { "44:562759334:1247430964", "ข้าเดาว่าเจ้าอยากให้ลงนามในเอกสารพวกนั้นสินะ พ่อหนุ่ม?" },
        required = { [23024] = { "26:601220136:509243241", "เอกสารหน้าที่ภาคสนามที่เตรียมไว้" } },
        objectiveLabels = {
