    [8519] = { -- A Pawn on the Eternal Board
        title = { "27:1870266905:814126069", "เบี้ยบนกระดานนิรันดร์" },
        objective = { "97:683008111:991221903", "เรียนรู้อดีตให้มากที่สุด แล้วคุยกับ Anachronos ที่ Caverns of Time ใน Tanaris" },
        description = { "203:36984943:868527809", "เมื่อสงบใจและเพ่งมอง เจ้าสังเกตว่ามีบางสิ่งขยับในผลึก ดูใกล้แล้วจึงรู้ว่ากำลังมองอดีต... ความทรงจำ... ที่ถูกลืมเนิ่นนาน" },
        completion = { "489:1324672648:1465904376", "หลัง Staghelm ทรยศ ข้ารวบรวมเศษ Scepter of the Shifting Sands แล้วกลับมานี่ ตั้งใจปกป้องคทาจากผู้หวังใช้ทำร้ายโลก หน้าที่ของฝูงมังกรจึงเกิด\n\nคทาที่แบ่งในหมู่มหามังกร Aspect ทั้งสี่แทบเป็นไปไม่ได้ให้ผู้ใฝ่ความวุ่นวายประกอบใหม่... ข้าเคยคิดเช่นนั้น โง่จริง แม้บัดนี้ยังถูกฝูงมังกรต้องสาปนั้นล่า" },
    },
    [8534] = { -- Hive'Zora Scout Report
        title = { "22:498687460:1387773483", "รายงานสอดแนม Hive'Zora" },
        objective = { "205:729947105:783171795", "ติดต่อ Cenarion Scout Azenel ใน Hive'Zora แล้วนำรายงานสอดแนมรังโซรากลับไปให้ Windcaller Proudhorn ที่ Cenarion Hold เจ้าต้องนำใบมอบหมายภารกิจยุทธวิธีฉบับ VI ไปด้วยจึงจะส่งเควสได้" },
        description = { "274:426663192:1067034526 N 1:46:46", "เราส่งหน่วยสอดแนมดีที่สุดลึกในรังซิลิธิดเพื่อเก็บข่าว Scout Azenel เฝ้าความเคลื่อนไหว Hive'Zora หลายวันแล้ว หานางและรับรายงานเขียน เราต้องลงมือจากข้อมูลโดยเร็ว {name}" },
        progress = { "50:1287572269:383349083 N 25:1007486133:59243374", "พบ Scout Azenel ได้ใน Hive'Zora รีบเถอะ {name}! เวลาเป็นสิ่งสำคัญ" },
        completion = { "38:288197329:1648958787 N 89:921126291:1399167016", "ขอบใจความพยายามอย่างยิ่ง {name} ข้าจะอ่านรายงานสอดแนมทันที เจ้าดูงานถัดไปได้เลย" },
        required = { [21158] = { "22:498687460:1387773483", "รายงานสอดแนมรังโซรา" } },
        objectiveLabels = {
            item = { ["Hive'Zora Scout Report"] = "รายงานสอดแนมรังโซรา" },
        },
    },
