        objective = { "227:921609348:413969494", "นำเหรียญการรบเซนาเรียน 5 เหรียญ เหรียญเสบียงเซนาเรียน 3 เหรียญ และเหรียญยุทธวิธีเซนาเรียน 7 เหรียญไปให้ Vargus ที่ Cenarion Hold ใน Silithus เจ้าต้องมีชื่อเสียงระดับ Friendly กับ Cenarion Circle จึงจะส่งเควสได้" },
        description = { "129:17702108:859681124 N 178:1078650777:1126176583", "ตราที่เจ้าสะสมจากงานรบ ส่งกำลังบำรุง และยุทธวิธีให้ Cenarion Hold ไม่ได้มีไว้โชว์ {name}\n\nควรเก็บไว้ เมื่อพิสูจน์ความภักดี ข้าจะเสนออุปกรณ์ที่สงวนให้พันธมิตรใกล้ชิดแลกตราเหล่านั้น" },
        progress = { "69:1941955198:1086923902 N 1:46:46", "การให้พันธมิตรภักดีที่สุดมีอุปกรณ์ดีเป็นผลประโยชน์ของเรา {name}" },
        completion = { "12:567290253:1686048517 N 90:109391752:1773931150", "ผลงานดีมาก {name} รับสิ่งนี้ในนาม Cenarion Circle เจ้าคู่ควรแน่นอน สหาย!" },
        required = { [20802] = { "21:817631533:1522745785", "เหรียญการรบเซนาเรียน" }, [20800] = { "24:595735767:905161656", "เหรียญเสบียงเซนาเรียน" }, [20801] = { "23:1811765340:223722906", "เหรียญยุทธวิธีเซนาเรียน" } },
