    [8574] = { -- Stalwart's Battlegear
        title = { "21:580711370:1116738897", "ยุทโธปกรณ์ผู้ยืนหยัด" },
        objective = { "248:1230260990:585598657", "นำเหรียญการรบเซนาเรียน 15 เหรียญ เหรียญเสบียงเซนาเรียน 20 เหรียญ เหรียญยุทธวิธีเซนาเรียน 17 เหรียญ และเครื่องหมายแห่งเรมูลอส 1 อันไปให้ Vargus ที่ Cenarion Hold ใน Silithus เจ้าต้องมีชื่อเสียงระดับ Revered กับ Cenarion Circle จึงจะส่งเควสได้" },
        description = { "136:1081870896:961461801 N 178:1078650777:1126176583", "ตราที่เจ้าสะสมจากงานรบ ส่งกำลังบำรุง และยุทธวิธีให้ Windcaller Proudhorn ไม่ได้มีไว้โชว์ {name}\n\nควรเก็บไว้ เมื่อพิสูจน์ความภักดี ข้าจะเสนออุปกรณ์ที่สงวนให้พันธมิตรใกล้ชิดแลกตราเหล่านั้น" },
        progress = { "69:1941955198:1086923902 N 1:46:46", "การให้พันธมิตรภักดีที่สุดมีอุปกรณ์ดีเป็นผลประโยชน์ของเรา {name}" },
        completion = { "12:567290253:1686048517 N 90:109391752:1773931150", "ผลงานดีมาก {name} รับสิ่งนี้ในนาม Cenarion Circle เจ้าคู่ควรแน่นอน สหาย!" },
        required = { [20802] = { "21:817631533:1522745785", "เหรียญการรบเซนาเรียน" }, [20800] = { "24:595735767:905161656", "เหรียญเสบียงเซนาเรียน" }, [20801] = { "23:1811765340:223722906", "เหรียญยุทธวิธีเซนาเรียน" }, [21515] = { "15:1171191470:1075168071", "เครื่องหมายแห่งเรมูลอส" } },
