    },
    [8731] = { -- Field Duty
        title = { "10:1522187184:1115698288", "หน้าที่ภาคสนาม" },
        objective = { "307:1598751242:928197874", "ไปรายงานตัวกับ Krug Skullsplit ที่ด่าน Orgrimmar Legion หน้า Hive'Regal เตรียมเอกสารหน้าที่ภาคสนามที่ยังไม่ได้ลงนาม รับเอกสารหน้าที่ภาคสนามที่ลงนามแล้ว จากนั้นนำไปให้ Windcaller Kaldon ที่ Cenarion Hold\n\nหมายเหตุ: หากรักษาหรือร่ายเวทช่วยเหลือใส่สมาชิก Orgrimmar Legion เจ้าจะติดสถานะ PvP" },
        description = { "11:927657569:725753248 N 419:1062703870:1229590442", "สวัสดี {name} ก่อนมอบงานสงครามซับซ้อนขึ้น เจ้าต้องทำหน้าที่ภาคสนามส่วนของตนก่อน\n\nพบ Orgrimmar Legion ของ Captain Skullsplit นอก Hive'Regal\n\nรายงานเขาแล้วกลับพร้อมหลักฐาน ข้าจะเตรียมงานก้าวหน้ากว่า\n\nและช่วยอยู่ห่าง Ironforge Brigade ให้มาก ความตึงเครียดระหว่างอาสาสมัคร Alliance กับ Horde สูงมาก" },
        progress = { "34:1639710685:1957776843 N 56:20555035:1561453018", "ทำหน้าที่ภาคสนามแล้วหรือ {name}? พบ Captain Skullsplit นอก Hive'Regal" },
        completion = { "96:462221319:1383612263 N 77:857042704:2002368952 C 88:1374430316:293059945", "ดูออกเลยว่า Krug ไม่ชอบเอกสาร เขาลงนามด้วยเลือดซิลิธิด!\n\nดีมาก {name} ข้าเตรียมงานชุดที่ใช้ฝีมือ{class}ของเจ้าได้ดี\n\nด้วยความพยายามต่อเนื่องของเจ้าและคนเช่นเจ้า อีกไม่นานศัตรูจะถูกบดขยี้!" },
        required = { [20810] = { "24:567143645:1458251977", "เอกสารหน้าที่ภาคสนามที่ลงนามแล้ว" } },
        objectiveLabels = {
            item = { ["Signed Field Duty Papers"] = "เอกสารหน้าที่ภาคสนามที่ลงนามแล้ว" },
        },
    },
    [8732] = { -- Field Duty Papers
        title = { "17:945632330:1904348284", "เอกสารหน้าที่ภาคสนาม" },
        progress = { { "44:393943487:1225193059", "45:546962012:897915444" }, "ข้าเดาว่าอยากให้ลงนามเอกสาร เจ้าหนู?", variants = { { "52:1908776419:840185115 N 1:63:63", "เอกสารปฏิบัติหน้าที่ภาคสนามหรือ? เรื่องเหลวไหลอะไรกันนี่ {name}?" } } },
        completion = { "164:1958644006:1154121772", "ใช่ ข้าว่าศึกเล็กนั่นคงนับเป็นหน้าที่ภาคสนามสมัยนี้ นำกลับ Cenarion Hold แน่ใจว่ามีงานสบายเตรียมให้\n\nไปได้!", variants = { { "260:1319710078:1792872226", "เมื่อก่อนข้าคงใช้เลือดของสัตว์ร้ายป้ายหน้าผากเจ้า เพื่อเป็นเครื่องหมายว่าเจ้าทำภารกิจนี้สำเร็จ แต่ Thrall ยืนกรานให้เราทำตามคำขอของเหล่าดรูอิด\n\nเอ้า รับเอกสารพวกนี้แล้วกลับไปที่ Cenarion Hold ข้าแน่ใจว่าพวกเขาคงมีงานที่เหมาะกับเจ้าให้ทำ" } } },
        description = { "52:1908776419:840185115 N 1:63:63", "เอกสารปฏิบัติหน้าที่ภาคสนามหรือ? เรื่องเหลวไหลอะไรกันนี่ {name}?" },
        required = { [23024] = { "26:601220136:509243241", "เอกสารหน้าที่ภาคสนามที่เตรียมไว้" } },
        objectiveLabels = {
            item = { ["Prepared Field Duty Papers"] = "เอกสารหน้าที่ภาคสนามที่เตรียมไว้" },
        },
    },
