    [8740] = { -- Twilight Marauders
        title = { "18:1590272280:1811833537", "ผู้ปล้นโจมตี Twilight Marauder" },
        objective = { "192:1834825423:584493426", "สังหาร Twilight Marauder Morna และ Twilight Marauder 5 คน เสร็จแล้วรายงาน Windcaller Proudhorn ต้องนำ Tactical Task Briefing IX มาด้วยจึงจะส่งเควสนี้ได้" },
        description = { "327:1576222033:1878474456", "พบกลุ่มสาวก Twilight's Hammer ขี่พาหนะอยู่นอกระยะกองกำลัง Cenarion Hold คอยกำจัดหน่วยลาดตระเวนเล็กกับคาราวาน\n\nตามหาปราบ Twilight Marauder พร้อมผู้นำ นักรบน่ากลัวชื่อ Morna เสร็จแล้วรายงาน Windcaller Proudhorn" },
