        completion = { "11:534428891:784080240 N 122:1974735037:1067377288", "ทำได้ดี {name} Twilight Marauder สร้างความสูญเสียต่อหน่วยลาดตระเวนเกินรับไหว นี่งานถัดไป" },
    },
    [8743] = { -- Bang a Gong!
        title = { "12:1712283303:1545704196", "ลั่นฆ้อง!" },
        progress = { "60:1125740557:2100469739 N 167:360367108:1254754268", "Scarab Gong ตั้งตระหง่านเป็นลางตรงหน้า ทำใจให้มั่น {name} เมื่อฆ้องดัง ประตู Ahn'Qiraj จะเปิด\n\nจากปากอสูรที่อ้า ย่อมมีเพียงความวุ่นวายและทำลาย จงปกป้องคนของเจ้า!", variants = { { "60:1125740557:2100469739 N 167:2084038715:1623883180", "Scarab Gong ตั้งตระหง่านเป็นลางตรงหน้า ทำใจให้มั่น {name} เมื่อฆ้องดัง ประตู Ahn'Qiraj จะเปิด\n\nจากปากอสูรที่อ้า ย่อมมีเพียงความวุ่นวายและทำลาย จงปกป้องคนของเจ้า!" } } },
        completion = { "86:813302768:344129275", "ผลึกพิเศษผุดจากพื้นใกล้ฆ้อง บางทีเป็นความโปรดปรานจากฝูงมังกร" },
        description = { "60:1125740557:2100469739 N 167:360367108:1254754268", "Scarab Gong ตั้งตระหง่านเป็นลางตรงหน้า ทำใจให้มั่น {name} เมื่อฆ้องดัง ประตู Ahn'Qiraj จะเปิด\n\nจากปากอสูรที่อ้า ย่อมมีเพียงความวุ่นวายและทำลาย จงปกป้องคนของเจ้า!" },
        required = { [21175] = { "33:956009393:1879219662", "คทาแห่งผืนทรายเคลื่อน" } },
        objectiveLabels = {
            item = { ["The Scepter of the Shifting Sands"] = "คทาแห่งผืนทรายเคลื่อน" },
