    [8745] = { -- Treasure of the Timeless One
        title = { "28:267560615:1353857235", "สมบัติแห่งผู้ไร้กาลเวลา" },
        completion = { "272:162845911:1894143775", "สวัสดี ยอดนักรบ ข้าคือ Jonathan ผู้รักษาฆ้องศักดิ์สิทธิ์และผู้เฝ้าชั่วนิรันดร์แห่งฝูงมังกรสีบรอนซ์\n\nTimeless One มอบอำนาจให้ข้ามอบของที่เจ้าเลือกจากคลังสมบัติไร้กาลเวลา ขอให้ช่วยเจ้าในศึกกับ C'Thun" },
