        objective = { "211:1587062824:1187687972", "นำหนังแห่งเงาหนึ่งชิ้น ตะเข็บลุ่ยของ Abomination 3 ชิ้น และเสื้อคลุมสาวกสนธยา 1 ตัวไปให้ Aurel Goldleaf ที่ Cenarion Hold ใน Silithus เจ้าต้องนำใบมอบหมายภารกิจส่งกำลังบำรุงฉบับ XI ไปด้วยจึงจะส่งเควสได้" },
        description = { "495:219021443:916344479 N 1:46:46", "Twilight's Hammer ทำงานผ่านความลับและหลอกลวงหลายชั้น แม้ลงมือในโลกเรา แต่แผนถูกวางในที่ที่เรายังเข้าไม่ถึง\n\nเราเชื่อว่าหินที่ใช้เรียกผู้บังคับบัญชาให้เดินทางสองทางได้ หากจะลองใช้ ต้องเลียนแบบเสื้อคลุมทูต Twilight ทุกรายละเอียด\n\nรวบรวมวัสดุจำเป็นส่ง Aurel Goldleaf {name}" },
        progress = { "26:1938204992:443522829", "มีของมาส่งข้าหรือ?" },
        completion = { "328:1655427474:642531337 N 1:46:46", "ใช่ ข้าเชื่อว่าของพวกนี้น่าจะเพียงพอ ข้าจะใช้มันตัดเย็บชุดให้เหมือนที่ทูตของ Twilight Hammer สวมใส่ ข้าภาวนาต่อ Elune ขอให้ฝีมือของข้าหลอกศัตรูได้อีกครั้ง\n\nแต่เจ้าไม่ต้องกังวลเรื่องนั้น เจ้าทำหน้าที่ของตนแล้ว และจะได้รับรางวัลที่เหมาะสมตอบแทน เจ้าเป็นพันธมิตรที่ภักดีและคู่ควร {name}" },
        required = { [12753] = { "14:1540196183:2053091107", "หนังแห่งเงา" }, [12735] = { "28:1981933659:1764292030", "ตะเข็บลุ่ยของ Abomination" }, [20407] = { "21:1055347165:569741363", "เสื้อคลุมสาวกสนธยา" } },
        objectiveLabels = {
