        description = { "315:975783701:1107747053", "ทหารใหม่ถึง Cenarion Hold พร้อมปัญหาว่าจะรักษาชีวิตในทะเลทรายอย่างไร การขาดน้ำและสัตว์มีพิษมากมายเป็นภัยจริงต่ออาสาสมัครไร้ประสบการณ์ รวบรวมของสำหรับชุดเอาชีวิตรอดส่ง Calandrath ที่ Cenarion Hold\n\nหมายเหตุผู้แปล: ข้อความเป้าหมายต้นฉบับระบุ Baked Salmon แต่รายการไอเทมในคลังระบุ Smoked Desert Dumplings ยังยืนยันไม่ได้ว่าฝั่งใดตรงกับเซิร์ฟเวอร์ปัจจุบัน ให้ตรวจชื่อในตัวนับเควสจริง" },
        required = { [7079] = { "14:1693715973:1569041085", "ลูกแก้วแห่งน้ำ" }, [19440] = { "19:265179557:2019690845", "ยาแก้พิษฤทธิ์แรง" } },
        objectiveLabels = {
            item = { ["Globe of Water"] = "ลูกแก้วแห่งน้ำ", ["Powerful Anti-Venom"] = "ยาแก้พิษฤทธิ์แรง" },
        },
    },
    [8857] = { -- Secrets of the Colossus - Ashi
        title = { "30:528487824:311726657", "ความลับ Colossus — Ashi" },
        objective = { "70:1020653667:1513401743", "นำ Colossus of Ashi's Husk ไปให้ Oglethorpe Obnoticus ที่ Booty Bay" },
        description = { "305:1870882166:501298", "ข้าหานักผจญภัยผ่านศึกที่พร้อมนำตัวอย่างเปลือกสดจาก Colossus of Ashi ที่ล้มไปให้ Oglethorpe ใน Booty Bay ไม่ ไม่อยากให้เข้าใกล้ซากนั่น แค่รับตัวอย่างข้าแล้วรีบ ของเน่าไม่มีประโยชน์กับเขา!" },
        progress = { "29:963689584:258060422", "ว่าอย่างไร? ถืออะไรนั่น?" },
        completion = { { "72:951866031:1186648137", "73:51659151:143501820" }, "โอ้ ไก่ที่ข้าจะสร้างจากเปลือกวิเศษนี้! ทำดีมาก เจ้าหนู!" },
    },
    [8858] = { -- Secrets of the Colossus - Regal
        title = { "31:1439741527:714043140", "ความลับ Colossus — Regal" },
        objective = { "71:666778477:1761877982", "นำ Colossus of Regal's Husk ไปให้ Overseer Oilfist ที่ Searing Gorge" },
        description = { "287:1396479514:1348883462 C 67:1301445793:942115966", "ไม่มีอะไรอยากทำกว่ายัดเปลือกแมลงใส่หน้าอ้วน Oilfist... ยกเว้นว่าข้าติดเก็บตัวอย่างจากแมลงสาบโตเกินขนาดนี่ ด้วยตัวมัน ข้าคงอยู่ถึงเช้ามืด\n\nนำตัวอย่างไปให้ Oilfist แทนและรีบ {class} เขาจ่ายหนัก!\n\nใช่ Thorium Point อยู่ Searing Gorge" },
        progress = { "7:270049213:1908373055", "อืม..." },
        completion = { "119:653740551:1585004950", "ยอดเยี่ยม เราคงคิดเกราะทรงพลังเหลือเชื่อจากไคตินนี้ได้ นี่ทรัพย์ตามสัญญา" },
    },
    [8859] = { -- Secrets of the Colossus - Zora
        title = { "30:952591015:367861590", "ความลับ Colossus — Zora" },
        objective = { "107:619470464:1551036043", "นำ Colossus of Zora's Husk ไปให้ Lord Maxwell Tyrosus ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { "346:1340318183:1737916217", "คนรับใช้ข้าเกือบตายเพื่อเก็บตัวอย่างนี้ เจ้าต้องรีบ! Lord Maxwell Tyrosus รอตัวอย่างเปลือกสดอย่างใจจดใจจ่อ เขาเชื่อความลับ Colossus อาจช่วยศึก Scourge!\n\nยังอยู่ทำไม!? ไป Light's Hope! ใช่ เจ้าจะได้รางวัลคุ้มค่า..." },
        progress = { "42:1474128644:1371671943", "ดูท่าเท้าเจ้าหนักนะ สหาย" },
        completion = { { "37:1127385383:706512770", "38:1976243247:211643323" }, "ยอดเยี่ยมและทันเวลา! ทำได้ดี เจ้าหนู" },
    },
    [9023] = { -- The Perfect Poison
        title = { "18:2076844624:71234684", "พิษที่สมบูรณ์แบบ" },
        objective = { "103:1949402903:1883713512", "Dirk Thunderwood ที่ Cenarion Hold ต้องการ Venoxis's Venom Sac และ Kurinnaxx's Venom Sac" },
        description = { "387:1316268080:669693113 C 96:1018036399:1973840813", "ข้ากับพี่น้องชายดูแลงานพิษจากคฤหาสน์ Ravenholdt\n\nLord Ravenholdt มอบหมายให้ข้าหาสูตรพิษใหม่ประสิทธิภาพสูง ที่ทำจากถุงพิษของสิ่งมีชีวิต Zul'Gurub กับ Ruins of Ahn'Qiraj\n\nมีสัตว์พิษร้ายสองตัวในซากพวกนั้นที่น่าจะมีสิ่งที่หา {class} นำถุงพิษจาก Kurinnaxx กับ Venoxis มา เราจะซาบซึ้งตลอดไป" },
        progress = { "34:1145634679:577559087 N 37:1556818152:1065565357", "นี่ไม่ใช่งานบุกฉวยแล้วหนี {name} เจ้าต้องพาเพื่อนมา" },
        completion = { "44:1538702274:1398823694", "Ravenholdt ขอบใจ วีรชน! เลือกได้เลย!" },
        required = { [22216] = { "19:1865337217:1032037448", "ถุงพิษของ Venoxis" }, [22217] = { "21:1414241923:912977892", "ถุงพิษของ Kurinnaxx" } },
        objectiveLabels = {
            item = { ["Venoxis's Venom Sac"] = "ถุงพิษของ Venoxis", ["Kurinnaxx's Venom Sac"] = "ถุงพิษของ Kurinnaxx" },
        },
    },
    [9248] = { -- A Humble Offering
        title = { "17:637041144:2103691108", "ของกำนัลเล็กน้อย" },
        objective = { "136:164094576:45456751", "Aurel Goldleaf ที่ Cenarion Hold ใน Silithus ต้องการให้เจ้านำคทาแห่งห้วงลึก 1 อันมาให้ เจ้าต้องมีชื่อเสียงระดับ Honored กับ Cenarion Circle ด้วย" },
        description = { "12:1077666014:1455039712 R 154:894238687:1814801711", "Ishnu-alah ชาว{race} แสดงหลักฐานการตาย Lord แห่ง Abyssal Council แล้วข้าจะให้ของช่วยศึกกับ Qiraji" },
        progress = { "34:846181741:1624141848 N 48:1127012501:980821661", "Fandu-dath-belore? โอ้ ขออภัย {name} ข้าจำไม่ได้ มีคทาหรือยัง?" },
        completion = { "127:1131283774:1598743686 N 1:46:46", "Ande'thoras-ethil ภาษาข้าหมายถึง ขอปัญหาของเจ้าจงลดน้อย\n\nสวมแหวนอย่างภูมิใจและสุขภาพดี {name}" },
        required = { [20515] = { "15:1547074354:1110521613", "คทาแห่งห้วงลึก" } },
        objectiveLabels = {
            item = { ["Abyssal Scepter"] = "คทาแห่งห้วงลึก" },
        },
    },
    [9338] = { -- Allegiance to Cenarion Circle
        title = { "29:1174182983:769160724", "ความภักดีต่อ Cenarion Circle" },
        progress = { "231:59572634:738027681", "แม้ไม่ต้องการสิ่งของรางวัล ตราเหล่านี้ยังแสดงความไว้ใจและมิตรภาพร่วมกัน\n\nนำมาให้ข้า ข้าจะบันทึกการรับใช้ หากผลงานเหนือหน้าที่" },
        completion = { "14:973440827:1580881631 N 61:1408662974:1579225497", "เจ้าให้เกียรติเรา {name} ด้วยความพยายามต่อเนื่อง เราจะชนะทุกอุปสรรค" },
        description = { "231:59572634:738027681", "แม้ไม่ต้องการสิ่งของรางวัล ตราเหล่านี้ยังแสดงความไว้ใจและมิตรภาพร่วมกัน\n\nนำมาให้ข้า ข้าจะบันทึกการรับใช้ หากผลงานเหนือหน้าที่" },
        required = { [20802] = { "21:817631533:1522745785", "เหรียญการรบเซนาเรียน" }, [20800] = { "24:595735767:905161656", "เหรียญเสบียงเซนาเรียน" }, [20801] = { "23:1811765340:223722906", "เหรียญยุทธวิธีเซนาเรียน" } },
        objectiveLabels = {
            item = { ["Cenarion Combat Badge"] = "เหรียญการรบเซนาเรียน", ["Cenarion Logistics Badge"] = "เหรียญเสบียงเซนาเรียน", ["Cenarion Tactical Badge"] = "เหรียญยุทธวิธีเซนาเรียน" },
        },
    },
    [9415] = { -- Report to Marshal Bluewall
        title = { "26:499562705:77724320", "รายงาน Marshal Bluewall" },
        objective = { "70:581307631:366494399", "คุยกับ Marshal Bluewall ที่ค่าย Alliance ใกล้ Hive'Zora" },
        description = { "202:2033717959:538960709", "เจ้าเป็นทหารใหม่ Marshal Bluewall หรือ? แน่นอนอยู่แล้ว\n\nรออะไร? ทหารดีกำลังตายในทะเลทราย ไม่ตื่นเต้นที่จะร่วมกับพวกเขาหรือ?\n\nไปได้แล้ว อย่าแห้งตายระหว่างทาง" },
        completion = { "226:1992349416:1504234646", "Alliance ต้องการคนพร้อมรบทุกคน Horde ได้กองหนุนต่อเนื่องจากตอนเหนือทวีป เราต้องดิ้นรนตามให้ทัน\n\nขออธิบายสถานการณ์" },
    },
    [9416] = { -- Report to General Kirika
        title = { "24:262248723:1118705271", "รายงาน General Kirika" },
        objective = { "66:364747416:1067501020", "คุยกับ General Kirika ที่ค่าย Horde ใกล้ Hive'Regal" },
        description = { "333:774106666:1089227548", "เจ้าคงเป็นทหารใหม่ General Kirika ถึงเวลาโผล่มาเสียที กายในทะเลทรายสึกกร่อนเร็ว\n\nคนแคระได้กองหนุนทุกวัน เราเสียพื้นที่ในการแย่งทรัพยากร Silithus ไม่ได้\n\nรับคำสั่งจาก General หน้าที่ข้าไม่ใช่ฝึก แค่หาเจ้า" },
        completion = { "145:139926752:1278434796", "ดีที่มา แต่ไม่มีเวลาเสียกับคุยเล่น ต้องรับคำสั่งแล้วออกไป\n\nฟังให้ดี" },
    },
    [9419] = { -- Scouring the Desert
        title = { "19:1086825382:1966131925", "กวาดหาทรัพยากรทะเลทราย" },
        objective = { "130:272118270:597687587", "หา Silithyst ส่ง Silithyst Extractor แล้วคุยกับ Marshal Bluewall ที่ค่าย Alliance ใกล้ Hive'Zora" },
        description = { "406:1450193349:366504230", "เพิ่งรู้ว่า Horde คุ้ยหาทรัพยากรในทะเลทราย Silithus แต่เราไม่ใส่ใจนัก คิดว่าคงไม่คุ้มส่งคนมากมาทะเลทรายร้อนอบอ้าว\n\nแต่เมื่อพบความสำคัญทรัพยากร บัดนี้เราจึงเร่งตาม\n\nหากช่วย ต้องเข้าทะเลทรายเก็บ Silithyst กลับที่นี่" },
        progress = { "65:1771679131:523279891", "ระวังข้างนอก แต่ต้องเร็วด้วย ไม่มีเวลาให้เสีย" },
        completion = { "199:981587179:649799154", "ขอบคุณแสงสว่างที่เจ้าสำเร็จ\n\nหากเริ่มเร็วกว่านี้ ความต้องการคงไม่เร่งด่วน เราต้องกันทรัพย์ทะเลทรายไม่ให้ถึงมือ Horde" },
        steps = { { "16:394606116:149441673", "นำ Silithyst กลับไปส่ง" } },
    },
    [9422] = { -- Scouring the Desert
        title = { "19:1086825382:1966131925", "กวาดหาทรัพยากรทะเลทราย" },
        objective = { "125:1265036103:1826868258", "หา Silithyst ส่ง Silithyst Extractor แล้วคุยกับ General Kirika ที่ค่าย Horde ใกล้ Hive'Regal" },
        description = { "441:403800079:1888889787", "เราขุดใช้ผลึกทะเลทราย Silithus มาพักหนึ่ง ภัยมีเพียงสัตว์เจ้าถิ่น ทราย ฝุ่น และร้อนหนัก\n\nแต่ตอนนี้ Alliance เหมือนรู้สิ่งที่พบ กลายเป็นการแข่งยึดทรัพยากรธรรมชาติและกันอีกฝ่าย\n\nข้าต้องการทุกมือที่ช่วยได้ หวังว่าจะมีมือเจ้า" },
        progress = { "38:132150286:39616869 N 70:1652180774:33639483", "ระวังภัยทะเลทราย {name} เมื่อ Alliance ซุ่มในเนินทราย ทุกก้าวอาจเป็นก้าวสุดท้าย" },
        completion = { "18:366880880:1038443585 N 101:864081294:1852289420", "ทำได้ดี {name} ทรัพยากรจะเข้าคลัง ทุกส่วนคือผลได้ของเราและความสูญเสียศัตรู" },
        steps = { { "17:170557017:1849450672", "ส่ง Silithyst" } },
    },
    [7907] = { -- Darkmoon Beast Deck
        progress = { "8:1459120288:911780184", "โอ้ แย่แล้ว" },
        title = { "19:1726695558:417602431", "สำรับไพ่อสูรแห่งดาร์กมูน" },
        objective = { "66:1187436645:1065909171", "นำ สำรับไพ่อสูร ไปส่งที่ Darkmoon Faire เมื่อคณะมาถึงเมือง" },
        description = { "377:1285751764:1294125176", "เมื่อท่านรวบรวมไพ่อสูรครบสำรับ ไพ่ใบที่เก้าก็ปรากฏขึ้นอย่างลึกลับ ด้านหลังเหมือนกับแปดใบแรก บนไพ่เขียนว่า ‘นำไพ่เหล่านี้ไปส่งที่ Darkmoon Faire แล้วจะได้รับรางวัล’ ท่านเคยได้ยินว่าคณะนี้สลับกันแวะ Mulgore กับ Goldshire ทุก ๆ สองสามเดือน จึงต้องรอจนคณะแวะมาที่นี่อีกครั้ง" },
        completion = { "258:1235928096:843935818", "ท่านรวบรวมไพ่อสูรได้ครบสำรับแล้วสินะ การนำไพ่มาคืนให้เราจะผูกไมตรีระหว่างท่านกับ Darkmoon ไว้อีกนาน โปรดรับไพ่ Darkmoon ชั้นสูงหนึ่งใบแทนคำขอบคุณเล็ก ๆ น้อย ๆ จากเรา" },
        required = { [19228] = { "11:492837964:1612547034", "สำรับไพ่อสูร" } },
        objectiveLabels = {
            item = { ["Beasts Deck"] = "สำรับไพ่อสูร" },
        },
    },
    [1124] = { -- Wasteland
        title = { "9:994575697:259043448", "แดนรกร้าง" },
        objective = { "100:67648230:1247819922", "คุยกับ Layo Starstrike ใกล้สุสาน Valor's Rest ใน Silithus แล้วแสดง Rabine's Letter ให้เขาดู" },
        description = { "479:882902157:559231988", "ทางตะวันตกของ Un'Goro Crater เมื่อข้ามสันเขาทางตะวันตกเฉียงเหนือไป จะพบ Silithus ดินแดนรกร้างอันโหดร้าย มีน้อยคนที่รู้ว่าไนต์เอลฟ์เคยต่อสู้กับพลังชั่วร้ายจากต่างถิ่นที่นั่น ความชั่วร้ายนั้นถูกผนึกไว้ แต่บัดนี้เราสงสัยว่ามีกองกำลังพยายามปลุกมันขึ้นมา... เป็นความสยดสยองเกินกว่าจะเอ่ยถึง\n\nจงไปหา Layo Starstrike สายลับคนหนึ่งของเราที่ Valor's Rest สถานพักสุดท้ายของผู้ที่ล้มตายในแดนร้าง มอบจดหมายนี้ให้เขา แล้วเขาจะรู้ว่าไว้ใจเจ้าได้" },
        progress = { "42:1433094367:1957996381 C 44:1012247783:1909500445", "ดินแดนนี้อันตรายเกินกว่าจะเดินทอดน่องตามสบายเช่นนี้ {class} อะไรพาเจ้ามาถึงแดนร้าง Silithus?" },
        completion = { "432:137797017:1475542778", "Rabine ส่งมาหรือ? ถือว่ายินดีต้อนรับ... เท่าที่แผ่นดินเปลี่ยวร้างถูกทอดทิ้งจะต้อนรับได้\n\nข้าไม่ทันมีชีวิตในยุคมหาภัยที่นี่ แต่บางส่วนของทะเลทรายเหมือนภาพน่าขนลุกจากอดีตที่ถูกลืม ด้วยเจ้า Cenarion Circle อาจปิดฉากภัยที่ควรตายไปหลายชั่วคนได้" },
    },
    [1185] = { -- Under the Chitin Was...
        title = { "23:393446159:1790177024", "ใต้เปลือกไคตินคือ..." },
        completion = { "62:1687178973:1250274154 N 389:1704747720:1347608617", "เฮ้ เจ้าอีกแล้ว! หมายถึงเจ้าที่ชื่อ {name} นั่นแหละ! ใช่ คนนั้น!\n\nขอเริ่มใหม่นะ!\n\nสิ่งที่เจ้าพบใน Silithus เป็นหนังสือจริง ๆ เป็นสมุดบันทึกที่เขียนด้วยสำเนียงเก่าแก่มากของภาษาที่ปัจจุบันเราเรียกว่า Darnassian ข้าต้องใช้เวลา แต่จะศึกษาอย่างละเอียด เจ้าควรรู้ว่าสิ่งที่พบนั้นมีคุณค่ามหาศาลต่อ Circle\n\nผู้ดูแลค่ายของเราตื่นเต้นใหญ่แล้ว!" },
    },
    [3082] = { -- Etched Tablet
        title = { "13:1394592871:752272412", "แผ่นจารึกสลักอักษร" },
        objective = { "42:1317021939:332072651", "คุยกับ Jen'shan ที่ Valley of Trials" },
        description = { "47:542172104:1998871674 N 141:2134291724:1334312211", "อา ระหว่างเจ้าไม่อยู่ มีแผ่นจารึกมาถึง {name}\n\nอ่านเมื่อมีเวลา หากจำไม่ผิด มาจากครูฝึกพราน Jen'shan นางอยากคุยเมื่อเจ้าพร้อม" },
        progress = { "385:1236119254:138752728", "Jen'shan เห็นพรานทรงพลัง และเหล่าวิญญาณเห็นชอบ\n\nวิถีพรานเป็นวิถีเก่าแก่ที่สุดอย่างหนึ่ง เมื่อ Horde ดิ้นรนเอาชีวิตรอดใน Azeroth พวกเขาหาเรา ขอให้สอนและเผยความลับมากมาย เดิมก็แกร่งในวิถีชาแมนและนักรบ แต่วิถีพรานยังไม่ใช่ทางของพวกเขา... ในตอนนั้น", variants = { { "22:664008067:1624639486 C 50:552463194:1450728427 C 263:888351329:535242126 C 32:1752078036:1146450991", "Jen'shan เห็น{class}ทรงพลัง และเหล่าวิญญาณเห็นชอบ\n\nวิถี{class}เป็นวิถีเก่าแก่ที่สุดอย่างหนึ่ง เมื่อ Horde ดิ้นรนเอาชีวิตรอดใน Azeroth พวกเขาหาเรา ขอให้สอนและเผยความลับมากมาย เดิมก็แกร่งในวิถีชาแมนและนักรบ แต่วิถี{class}ยังไม่ใช่ทางของพวกเขา... ในตอนนั้น" } } },
        completion = { "476:541195037:125754553", "ตอนนี้เราสอนสิ่งเหล่านั้น พวกเขาสอนอย่างอื่น เราแทบรวมเป็นเผ่าพันธุ์เดียว... แทบเท่านั้น เป็นพันธมิตรมานาน จงจำให้ช่วยพวกเขา แล้ว Jen'shan จะจำให้ช่วยเจ้า\n\nJen'shan จะสอนวิถีพรานอย่างดี อย่าลืมว่าเผ่าเคารพพรานมาก เจ้าจะมีบทบาทใหญ่ในอนาคต... อย่าลืม\n\nเมื่อต้องการมาหา Jen'shan นางจะสอนเต็มที่เมื่อเห็นว่าพร้อม", variants = { { "219:1305087526:886466936 C 36:1984691472:586108851 C 209:470570796:193416829", "ตอนนี้เราสอนสิ่งเหล่านั้น พวกเขาสอนอย่างอื่น เราแทบรวมเป็นเผ่าพันธุ์เดียว... แทบเท่านั้น เป็นพันธมิตรมานาน จงจำให้ช่วยพวกเขา แล้ว Jen'shan จะจำให้ช่วยเจ้า\n\nJen'shan จะสอนวิถี{class}อย่างดี อย่าลืมว่าเผ่าเคารพ{class}มาก เจ้าจะมีบทบาทใหญ่ในอนาคต... อย่าลืม\n\nเมื่อต้องการมาหา Jen'shan นางจะสอนเต็มที่เมื่อเห็นว่าพร้อม" } } },
        required = { [9564] = { "13:1394592871:752272412", "แผ่นจารึกสลักลาย" } },
        steps = { { "13:1394592871:752272412", "แผ่นจารึกสลักลาย" } },
    },
    [3087] = { -- Etched Parchment
        title = { "16:1244292675:1472897672", "แผ่นหนังสลักอักษร" },
        objective = { "72:1589085819:1185482091", "อ่าน Etched Parchment แล้วคุยกับ Jen'shan ที่ Valley of Trials" },
        description = { "50:504738005:547472890 N 141:2134291724:1334312211", "อา ระหว่างเจ้าไม่อยู่ มีแผ่นหนังมาถึง {name}\n\nอ่านเมื่อมีเวลา หากจำไม่ผิด มาจากครูฝึกพราน Jen'shan นางอยากคุยเมื่อเจ้าพร้อม" },
        progress = { "361:40099487:1066163669", "อา มาเสียที ดี Jen'shan รออยู่\n\nหลายคนคิดว่าทางง่าย แต่ Jen'shan บอกว่าไม่จริง ฝึกสัตว์ Durotar และที่ไกลออกไปให้เชื่อง ใช้ฝีมือไม่แพ้ศาสตร์อาร์เคนหรือสื่อสารบรรพบุรุษ\n\nยิงธนูหรือปืนอาจไม่อันตรายต่อตัวเท่าร่ายเวท แต่ต่อศัตรูอันตรายไม่แพ้กัน" },
        completion = { "371:485266494:1701197150", "คุยเสร็จแล้วควรคุยกับคนอื่นใน Valley พวกเขาจะขอให้ทำงาน ทดสอบฝีมือและสอนภัยบางอย่างของแผ่นดิน\n\nเมื่อประสบการณ์และปัญญาเพิ่ม เจ้าต้องให้ Jen'shan สอนเทคนิคกับทักษะดีขึ้น กลับบ่อย ๆ ข้าจะบอกว่าสอนอะไรได้" },
        required = { [9553] = { "16:1244292675:1472897672", "แผ่นหนังสลัก" } },
        steps = { { "16:1244292675:1472897672", "แผ่นหนังสลัก" } },
    },
    [3092] = { -- Etched Note
        title = { "11:1235277337:1084253254", "บันทึกสลักอักษร" },
        objective = { "66:2073631297:281145242", "อ่าน Etched Note แล้วคุยกับ Lanka Farshot ที่ Red Cloud Mesa" },
        description = { "51:1119716052:1206024959 N 128:1928910553:216664420", "เมื่อครู่มีผู้ส่งสารหาเจ้า {name} เชื่อว่าครูฝึกพราน Lanka ส่งมา หากบันทึกนี้มาจาก Lanka ข้าจะไม่รออ่านนานนัก" },
        progress = { "25:118728552:721717597 N 322:1053643811:846063540", "ยินดีต้อนรับสู่ Camp Narache {name} ข้าได้ยินเรื่องดี ๆ ของเจ้า สายเลือดของเจ้าเข้มแข็ง ผู้อาวุโสหลายคนเห็นว่าเจ้ามีฝีมือแล้ว แต่เราจะทดสอบดู\n\nที่ราบ Mulgore จะเป็นบ้านของเจ้าไปอีกพักใหญ่ จงเรียนรู้ให้ดี วันหนึ่งเจ้าจะต้องเดินทางสู่ดินแดนที่ไม่คุ้นเคยเพื่อฝึกทักษะขั้นสูงขึ้น เจ้าต้องเตรียมพร้อม", variants = { { "25:118728552:721717597 N 323:839083463:109731372", "ยินดีต้อนรับสู่ Camp Narache {name} ข้าได้ยินเรื่องดี ๆ ของเจ้า สายเลือดของเจ้าเข้มแข็ง ผู้อาวุโสหลายคนเห็นว่าเจ้ามีฝีมือแล้ว แต่เราจะทดสอบดู\n\nที่ราบ Mulgore จะเป็นบ้านของเจ้าไปอีกพักใหญ่ จงเรียนรู้ให้ดี วันหนึ่งเจ้าจะต้องเดินทางสู่ดินแดนที่ไม่คุ้นเคยเพื่อฝึกทักษะขั้นสูงขึ้น เจ้าต้องเตรียมพร้อม" } } },
        completion = { "245:1665650894:266987431 N 131:673987807:286368815", "หน้าที่ข้าคือเตรียมเจ้าด้วยพื้นฐานอาชีพ วิธีฝึกสัตว์เลี้ยง ยิงปืน และทักษะจำเป็นอื่น\n\nพรานเป็นส่วนสำคัญของธรรมเนียมและประวัติเรา {name} จำไว้ว่าสำคัญต่อเผ่าเพียงใด หากรับใช้คนเราดี เจ้าจะได้รับความเคารพยกย่อง" },
        required = { [9565] = { "11:1235277337:1084253254", "บันทึกสลัก" } },
        objectiveLabels = {
            item = { ["Etched Note"] = "บันทึกสลัก" },
        },
    },
    [3094] = { -- Verdant Note
        title = { "12:1001668781:685340740", "บันทึกแห่งพงไพร" },
        objective = { "67:268407479:1377823460", "อ่าน Verdant Note แล้วคุยกับ Gart Mistrunner ที่ Camp Narache" },
        description = { "51:1119716052:1206024959 N 124:578654903:1407944886", "เมื่อครู่มีผู้ส่งสารหาเจ้า {name} เชื่อว่าครูฝึกดรูอิด Gart ส่งมา หากบันทึกนี้มาจาก Gart ข้าจะไม่รออ่านนานนัก" },
        progress = { "243:1299620611:1591011493", "เจ้ามาถึงแล้ว ดี วิญญาณบรรพบุรุษทั่ว Mulgore และดินแดนที่ไกลออกไปกำลังกระสับกระส่าย แต่ข้ายังไม่ทราบสาเหตุ การเรียนรู้ที่จะฟังวิญญาณแห่งธรรมชาติและเป็นตัวแทนของพวกเขาคือหน้าที่ตลอดชีวิตของเรา จงจำไว้" },
        completion = { "300:638057571:148992624 N 97:1260968296:1771065161", "แม้มีสายสัมพันธ์ร่วม อย่าหวังไนต์เอลฟ์ต้อนรับนัก ความหยิ่งยังจำกัดสายตา แต่ไม่ใช่เรื่องเรา สิ่งที่ต้องใส่ใจคือคำสอน Earthmother ข้าจะสอนสิ่งที่รู้เมื่อปัญญาเจ้าเพิ่ม\n\nกลับบ่อย ๆ {name} จะพบว่า Earthmother มอบพลังเหลือเชื่อแก่ผู้ทุ่มเทที่สุด" },
        required = { [9581] = { "12:1001668781:685340740", "บันทึกเขียวขจี" } },
        steps = { { "12:1001668781:685340740", "บันทึกเขียวขจี" } },
    },
    [3108] = { -- Etched Rune
        title = { "11:1303570461:1093347798", "รูนสลักอักษร" },
        objective = { "70:493438081:455583669", "อ่าน Etched Rune แล้วคุยกับ Thorgas Grimson ที่ Coldridge Valley" },
        description = { "253:1533771652:1727865806", "ระหว่างช่วยข้า มีคนฝากรูนให้ส่งเจ้า หาเวลาอ่านเมื่อว่าง คิดว่ามาจากครูฝึกพราน Thorgas อ่านแล้วไปหาเขาใน Anvilmar เมื่อมีโอกาส" },
        progress = { "136:892592691:675392598 N 179:1348757432:421853942", "มาถึงแล้วสินะ! ดีใจที่ได้พบ! พนันว่าเจ้าไม่ต้องตามรอยข้าก็หาที่นี่เจอ ฮ่า!\n\nอาชีพของเราหยั่งรากอยู่ในประเพณี {name} การเรียนรู้วิถีของแผ่นดิน การตามรอยหมีบนภูเขา หรือเพียงเอาชีวิตรอดด้วยไหวพริบ ล้วนต้องใช้ทั้งความกล้าและเล่ห์เหลี่ยม เจ้าคิดว่าทำได้ไหม?" },
        completion = { "413:1607113762:597654255", "เจ้าต้องเคารพโลกที่เราอาศัยอยู่เสมอ สัตว์ที่เลือกมาร่วมรบ ประกายของอาวุธ น้ำหนักกระสุน ลมหนาวที่กัดผิว ทุกสิ่งล้วนเป็นเรื่องที่เจ้าต้องรู้ให้ลึกซึ้ง\n\nข้าจะช่วยเท่าที่ทำได้ แต่งานส่วนใหญ่ขึ้นอยู่กับเจ้า เมื่อคิดว่าพร้อมก็กลับมาคุยกัน ข้าจะฝึกให้เท่าที่ข้าทำได้" },
        required = { [9566] = { "11:1303570461:1093347798", "รูนสลัก" } },
        steps = { { "11:1303570461:1093347798", "รูนสลัก" } },
    },
    [3141] = { -- Loramus
        title = { "7:2091559965:298764828", "Loramus" },
