    },
    [3382] = { -- A Crew Under Fire
        title = { "17:49094801:249220206", "ลูกเรือท่ามกลางการโจมตี" },
        objective = { "136:403537699:683857215", "ปกป้อง Captain Vanessa Beltis ลูกเรือ และผู้โดยสาร Horizon Scout จากนากาที่โจมตี Captain Vanessa Beltis ต้องรอดชีวิต" },
        description = { "415:615009272:170177934 N 69:2115767420:674554259", "เราอยู่ไม่ไกลจากชายฝั่ง กำลังหาที่ปลอดภัยทอดสมอ พระอาทิตย์เพิ่งตกไปไม่ถึงชั่วโมง พวกมันก็โจมตี... นากาบัดซบ!\n\nข้าไม่รู้ว่าพวกมันหาอะไร แต่ชัดว่ายังไม่พบ เพราะพวกมันย้อนกลับมาแล้วครั้งหนึ่ง หน่วยสอดแนมสองคนของข้าเฝ้าปากหุบเขาอยู่ เพื่อเตือนล่วงหน้าเมื่อมันกลับมาอีก\n\nข้าเสียใจที่เจ้ามาถึงในเวลาเช่นนี้ {name} แต่ข้าคงทำอะไรไม่ได้\n\nพร้อมจะสู้ศึกใหญ่ที่สุดในชีวิตหรือยัง?" },
        progress = { "37:1115679609:215255077", "ศึกนี้จะหนัก..." },
        completion = { "397:1150613600:854337540", "เราทำได้แล้ว! ขอบใจ! นี่คงเป็นหนึ่งในศึกที่โหดที่สุดที่ข้าเคยร่วม ข้าขอบคุณเจ้าเท่าไรก็ไม่พอ\n\nข้าเพียงหวังว่าจะมีลูกเรือรอดจากเหตุการณ์นี้มากกว่านี้\n\nลองคุยกับผู้โดยสาร Horizon Scout ที่รอดชีวิตเถิด บางคนมีธุระแถวนี้ หากเจ้าเต็มใจ พวกเขาอาจมีเรื่องให้ช่วย ขอบใจอีกครั้งสำหรับทุกอย่าง" },
        objectiveLabels = {
            event = { ["Protect Captain Vanessa Beltis from the naga attack"] = "ปกป้อง Captain Vanessa Beltis จากการโจมตีของนากา" },
        },
    },
    [3421] = { -- Return Trip
        title = { "11:424099864:886038058", "เที่ยวเดินทางกลับ" },
        completion = { "155:159338867:42122508", "ข้าจะส่งกลับค่าย Sanath\n\nอย่าใส่ใจมารยาทแย่ เขาหยาบคายกับทุกคนยกเว้นนายท่าน บางทีสักวันจะได้บทเรียน" },
    },
    [3503] = { -- Meeting with the Master
        title = { "23:1970022347:1410862931", "พบกับนายท่าน" },
        completion = { "398:2049334975:1137130598", "ครั้งหนึ่งข้าเคยเรียกสิ่งตอบแทนอะไรก็ได้จากผู้ที่มาขอพบนายท่าน แต่ตอนนี้เพียงเจ้าเอ่ยปาก ข้าก็ต้องส่งเจ้าไป\n\nข้าไม่พอใจนัก แต่ก็ไม่คิดตั้งคำถามกับคำสั่ง ทำได้เพียงล้อชุดไร้สาระหรือสีหน้าน่าสมเพชของเจ้า แม้แต่เรื่องนั้นก็ชวนเบื่อ...\n\nกระทั่งคำบ่นนี้ยังน่าเบื่อเลย! ตกลงเจ้าอยากพบนายท่านหรือไม่?" },
    },
    [3508] = { -- Breaking the Ward
        title = { "17:1549435642:1798518092", "ทำลายเวทคุ้มกัน" },
        objective = { "53:2049691376:1367924492", "รอ Loramus ทำเวทรู้แจ้งให้เสร็จ" },
        description = { "19:1442556170:1029827009 N 432:1882697349:1121018884", "เจ้าช่างบ้าบิ่น {name} เป็นคุณสมบัติที่น่าชื่นชมของพวกเจ้า บุกเข้าสู่ศึกทั้งที่แทบไม่มีโอกาสสำเร็จ ข้าจะช่วยเจ้า แม้เพียงเพื่อได้เห็นลูกสมุนของ Razelikh ล้มลงสักตนก็ตาม\n\nการทำลายเวทคุ้มกันของผู้ใต้บัญชา Razelikh ต้องใช้ทั้งเวลาและวัตถุหายาก\n\nอยู่นิ่ง ๆ ก่อนอื่นข้าต้องทำพิธีรู้แจ้ง ข้อมูลที่ได้จะช่วยให้ข้าตีอาวุธอันทรงพลังได้" },
        completion = { "36:545560964:9063810", "ต้องค้นพบชื่อของอสูร" },
    },
    [3509] = { -- The Name of the Beast
        title = { "21:1576261672:2014144340", "นามแห่งอสูร" },
        objective = { "105:205822609:158120439", "คุยกับ Lord Arkkoroc ที่ Azshara เริ่มหาตามริมน้ำเพื่อพบ Temple of Arkkoran" },
        description = { "421:1160876980:89043139", "มีเพียงทางเดียวที่จะทำร้ายจ้าวปีศาจและลูกสมุนของมันได้ เราต้องตีอาวุธทรงพลังที่มีนามแท้ของมันกำกับอยู่\n\nเมื่ออาวุธเสร็จ ทั้งปีศาจและผู้ใต้บัญชาจะไม่คงกระพันอีกต่อไป\n\nเทพชั้นรอง Lord Arkkoroc อยู่ใน Azshara เจ้าต้องไปหาเขา แต่ระวัง หากถูกพบ ลูกสมุนของปีศาจจะทำทุกอย่างเพื่อทำลายเจ้า\n\nแน่นอนว่าข้อมูลนี้ย่อมมีสิ่งที่เจ้าต้องจ่ายแลก" },
        completion = { "127:955748672:26883195", "จ้าวปีศาจหรือ?\n\n<Lord Arkkoroc หัวเราะ>\n\nบางทีข้าอาจช่วยเรื่องข้อมูลนี้ได้ แต่ก่อนอื่นเจ้าต้องช่วยข้า" },
    },
    [3510] = { -- The Name of the Beast
        title = { "21:1576261672:2014144340", "นามแห่งอสูร" },
        objective = { "120:364533952:783642721", "สังหาร Hetaera แล้วนำ Hetaera's Bloodied Head, Hetaera's Beaten Head และ Hetaera's Bruised Head กลับไปให้ Lord Arkkoroc" },
        description = { "333:911050507:205530898", "นางสังหารลูก ๆ ของข้า ผู้มีอายุขัย นางอ้างสิทธิ์ปกครองมหาสมุทรแห่งนี้ ทั้งที่เป็นเพียงเทพจอมปลอม จงบดขยี้นางแล้วนำหัวทั้งหมดกลับมา\n\nเพื่อแลกเปลี่ยน ข้าจะบอกนามที่เจ้าแสวงหา พร้อมอีกสิ่งหนึ่งที่สำคัญไม่แพ้กัน\n\nนางตระเวนอยู่แถวแหล่งวางไข่... ชื่อของนางคือ Hetaera\n\n<Lord Arkkoroc ชี้ไปทางตะวันตกเฉียงใต้>\n\nไปได้!" },
        progress = { "58:1936924495:1029958955", "<Lord Arkkoroc ก้มตรวจดูเจ้า>\n\nอยู่ไหน?" },
        completion = { "46:1345471404:1534922373", "ในที่สุด ผู้คู่ควรปัญญา Arkkoroc!" },
        required = { [10599] = { "21:385890949:336324396", "หัวที่ถูกทุบของเฮเทรา" }, [10598] = { "23:597402378:1135053407", "หัวเปื้อนเลือดของเฮเทรา" }, [10600] = { "22:1531222101:1121685312", "หัวฟกช้ำของเฮเทรา" } },
        objectiveLabels = {
            item = { ["Hetaera's Beaten Head"] = "หัวที่ถูกทุบของเฮเทรา", ["Hetaera's Bloodied Head"] = "หัวเปื้อนเลือดของเฮเทรา", ["Hetaera's Bruised Head"] = "หัวฟกช้ำของเฮเทรา" },
        },
    },
    [3511] = { -- The Name of the Beast
        title = { "21:1576261672:2014144340", "นามแห่งอสูร" },
        objective = { "43:2141966087:874746030", "นำสารชุบโลหะกลับไปให้ Loramus Thalipedes" },
        description = { "432:649708646:1813730058", "ตามสัญญา ข้าจะเผยนามของจ้าวปีศาจ Razelikh the Defiler แต่ก่อนอื่นต้องเตรียมสิ่งที่สำคัญที่สุดต่อการเดินทางของเจ้า\n\nอาวุธที่จะสร้างต้องใช้สารชุบโลหะ จงรอให้ข้ารีดเลือดจากหัวเหล่านี้\n\n<Lord Arkkoroc บีบหัวเหล่านั้นระหว่างกำปั้นยักษ์ รีดเลือดออกมา>\n\nนำสารชุบโลหะกลับไปให้ Loramus พร้อมนามของอสูร... Rakh'likh" },
        progress = { "24:560177159:162272189 R 33:1683578558:683783645", "กลับแล้ว! น่าทึ่ง ชาว{race} พบนามแท้หรือไม่?" },
        completion = { "130:1293493609:1791558212", "สารชุบโลหะจะเติมฤทธิ์กัดกร่อนที่จำเป็นต่อการตีอาวุธ เหลืออีกขั้นเดียวในการสร้าง" },
    },
    [3517] = { -- Stealing Knowledge
        title = { "18:1643934425:792346787", "ขโมยความรู้" },
        objective = { "142:609989459:1106492378", "ตามหา Tablet of Beth'Amara, Tablet of Jin'yael, Tablet of Markri และ Tablet of Sael'hai แล้วกลับไปหา Jediga ที่ Azshara", variants = { { "127:535017110:973464289", "ตามหา Tablet of Beth'Amara, Tablet of Jin'yael, Tablet of Markri และ Tablet of Sael'hai ให้ Jediga ที่ Valormok" } } },
        description = { "9:1814048257:1741626066 N 477:539750688:1081015337", "ยอมรับว่า {name} ข้าฉวยประโยชน์จากสถานการณ์ใน Azshara ได้เต็มที่ การลงโทษ Belgrom ก็มีข้อดี\n\nก่อนมา ข้าศึกษาแล้ว เจ้าคงแปลกใจว่ามีของมีค่าวางทิ้งมากเพียงใด\n\nข้าจะเล่าข้อตกลงเพิ่ม และแบ่งกำไรหากช่วยรวบรวม\n\nมีแผ่นจารึกที่ต้องการทั่ว Ruins of Eldarath ทางตะวันออก ทั้งสี่ตั้งชื่อตามจอมเวทไฮบอร์น หามาแล้วค่อยคุยต่อ", variants = { { "9:1814048257:1741626066 N 366:1029702465:621329082", "ยอมรับว่า {name} ข้าฉวยประโยชน์จากสถานการณ์ใน Azshara ได้เต็มที่ การลงโทษ Belgrom ก็มีข้อดี\n\nก่อนมา ข้าศึกษาแล้ว เจ้าคงแปลกใจว่ามีของมีค่าวางทิ้งมากเพียงใด\n\nมีแผ่นจารึกที่ต้องการทั่ว Ruins of Eldarath ทางตะวันออก ทั้งสี่ตั้งชื่อตามจอมเวทไฮบอร์น หามาแล้วค่อยคุยต่อ" } } },
        progress = { "336:817432641:1539073166", "แผ่นจารึกที่ให้หาน่าจะขายได้ไม่น้อยกับคนที่เหมาะ พบแล้วจะบอกว่าต้องส่งใคร แต่ข้าไม่โง่... เจ้าจะได้ส่วนแบ่งเมื่อมีหลักฐานส่งแล้ว\n\nไปเถอะ ไม่มีเวลาทั้งวัน ข้าอาจต้องหาคนอื่นช่วย" },
        completion = { "9:736088637:128646839 N 179:2069559826:1998883558", "สมบูรณ์แบบ {name} สภาพดีด้วย น่าจะได้ราคาดีจากผู้เกี่ยวข้องทุกฝ่าย\n\nอย่าเสียเวลาที่นี่เกินจำเป็น เรามีเงินต้องหา" },
        required = { [10538] = { "20:231398850:1069070715", "แผ่นจารึก Beth'Amara" }, [10539] = { "18:116808346:1937573171", "แผ่นจารึก Jin'yael" }, [10540] = { "16:317789043:1963856072", "แผ่นจารึก Markri" }, [10541] = { "18:486501949:1546340153", "แผ่นจารึก Sael'hai" } },
        objectiveLabels = {
            item = { ["Tablet of Beth'Amara"] = "แผ่นจารึก Beth'Amara", ["Tablet of Jin'yael"] = "แผ่นจารึก Jin'yael", ["Tablet of Markri"] = "แผ่นจารึก Markri", ["Tablet of Sael'hai"] = "แผ่นจารึก Sael'hai" },
        },
    },
    [3518] = { -- Delivery to Magatha
        title = { "19:824084828:1442926695", "ส่งของให้ Magatha", variants = { { "29:1842726059:1206308165", "นำของไปส่งให้ Magatha Grimtotem" } } },
        objective = { "59:1002977766:1634801399", "นำ Tablet of Beth'Amara ไปให้ Magatha ที่ Thunder Bluff", variants = { { "69:80865390:315685043", "นำ Tablet of Beth'Amara ไปให้ Magatha Grimtotem ที่ Thunder Bluff" } } },
        description = { "446:1156680015:1309128388", "จารึกแรกให้ทอเรนหญิงชื่อ Magatha ผู้อาวุโส Thunder Bluff ผู้สนับสนุนพันธมิตรทอเรนกับ Forsaken นางเชื่อยิ่งกว่าผู้อาวุโสอื่นว่าวิถีทอเรนช่วย Forsaken หาทางกลับเป็นมนุษย์\n\nนำ Tablet of Beth'Amara ไป มันอาจเป็นสิ่งเชื่อมที่นางต้องใช้ช่วย Forsaken... อย่างน้อยนางอ้างเช่นนั้น", variants = { { "450:946298066:1693467609", "จารึกแผ่นแรกต้องนำไปให้ทอเรนชื่อ Magatha Grimtotem นางเป็นหนึ่งในผู้อาวุโสแห่ง Thunder Bluff และเป็นผู้สนับสนุนพันธมิตรระหว่างทอเรนกับ Forsaken ในบรรดาผู้อาวุโส นางเชื่อมั่นยิ่งกว่าใครว่าทอเรนและวิถีของพวกเขาจะช่วยให้ Forsaken หาทางกลับมาเป็นมนุษย์ได้\n\nนำ Tablet of Beth'Amara ไปให้นาง จารึกนี้อาจเป็นเบาะแสที่นางต้องใช้หาวิธีช่วย Forsaken... หรืออย่างน้อยนางก็อ้างเช่นนั้น" } } },
        progress = { "5:1287366450:669725923 N 83:796287257:420193582", "ว่าอย่างไร {name} ให้ช่วยอะไร? ข้ามีหลายเรื่องต้องจัดการ โปรดเร็วหน่อย" },
        completion = { "330:426377200:663939170", "อา ในที่สุด Tablet of Beth'Amara ข้าสงสัยว่าร่วมมือ Jediga ล้มเหลว หรือออร์คน่าสงสารตายใน Azshara ดีใจที่สำเร็จ\n\nBeth'Amara เป็นนักเล่นแร่แปรธาตุทรงอิทธิพลที่สุดคนหนึ่งของไฮบอร์น ว่ากันว่าจอมเวทผู้นี้เชี่ยวชาญแปรธาตุโลหะและศาสตร์อื่นด้วยตนเอง" },
    },
    [3541] = { -- Delivery to Jes'rimon
        title = { "21:1453835165:1109696853", "ส่งของให้ Jes'rimon" },
        objective = { "55:997215862:704725162", "นำ Tablet of Jin'yael ไปให้ Jes'rimon ที่ Orgrimmar" },
        description = { "500:2136768632:467107366", "ข้ามีคนรับซื้อของโจรใน Orgrimmar อยู่ The Drag หาตัวยากหากไม่รู้ที่ แต่ลองอาคารสูงที่สุดแห่งหนึ่งก็พบไม่ยาก\n\nช่วยอย่าง อย่าตะโกนบอกทั้ง Kalimdor ว่าเขาอยู่ไหนทำธุรกิจอะไร ไม่ดีต่อเราทั้งคู่\n\nเขาจะจ่ายเกินราคายุติธรรมให้ Tablet of Jin'yael ไม่รู้ทำไม แต่ควรได้เห็นความตื่นเต้นเมื่อรู้ที่อยู่มัน" },
        progress = { "160:541528293:1819660160", "ว่าอย่างไร ต้องการอะไรสหาย? วันนี้ข้ามีเรื่องดูแลมาก และเจ้าไม่อยู่ในตาราง ถ้ารบกวน ข้าจะทำให้เปลี่ยนแน่" },
        completion = { "239:1195713639:1702250231 N 1:46:46", "อา Jediga ส่งห่อจาก Azshara มาแล้ว ดี ข้ารออยู่\n\nJediga หญิงที่ดี... ร้ายกาจด้วย มีอะไรดีกว่านี้?\n\nดูสิ จารึกสมบูรณ์แบบ เจ้าเป็นผู้ส่งสารที่ดี {name}" },
        required = { [10539] = { "18:116808346:1937573171", "แผ่นจารึก Jin'yael" } },
        objectiveLabels = {
            item = { ["Tablet of Jin'yael"] = "แผ่นจารึก Jin'yael" },
        },
    },
    [3542] = { -- Delivery to Andron Gant
        title = { "23:1886940217:76223146", "ส่งของให้ Andron Gant" },
        objective = { "55:2048033782:1983792900", "นำ Tablet of Markri ไปให้ Andron Gant ที่ Undercity" },
        description = { "488:1684812289:1448411558", "ผู้ติดต่อถัดไปคือ Andron Gant มักเก็บตัวใน Undercity ใกล้ Apothecarium\n\nเขาพูดมากกว่าหน่อยเรื่องอยากใช้จารึกอะไร ดูเหมือนจอมเวท Undercity บางคนอยากศึกษาเวทอาร์เคนไฮบอร์น คิดว่าจารึกจะช่วย Markri เชี่ยวชาญเรียกสิ่งมีชีวิต โดยเฉพาะธาตุ\n\nนำ Tablet of Markri ไปส่ง แล้วกลับมารับส่วนแบ่ง" },
        progress = { "100:1197862526:868814678", "อืม... <สะอึก>... ประหลาดใจจริง นักผจญภัยยย... <สะอึก>!\n\nให้ช่วยอะไร... <สะอึก>?" },
        completion = { "143:1352970749:1871921506", "นี่ รับเงิน... ไปหา... <สะอึก>... เกราะใหม่หรืออะไร...\n\nของนี่ขายได้ทองเงาวับสักเหรียญสองเหรียญกับคนที่... <สะอึก> เหมาะสม" },
    },
    [3561] = { -- Delivery to Archmage Xylem
        title = { "26:1750731387:633169740", "ส่งของให้ Archmage Xylem" },
        objective = { "58:2012710347:84255026", "นำ Tablet of Sael'hai ไปให้ Archmage Xylem ที่ Azshara" },
        description = { "50:772311115:1023722271 N 447:1204671186:1837586176", "จารึกสุดท้ายให้คนอันตรายมาก {name} ฟังให้ดี ข้าไว้ใจคนนี้น้อยกว่าทุกคนที่ให้ไปพบ\n\nArchmage Xylem มีหอในเนินเขามองลง Azshara เป็นมนุษย์แต่ไม่เหมือนคนที่เคยพบ... หรือฆ่า เขาแผ่พลัง ข้าไม่กล้าถามว่าจะใช้จารึกทำอะไร\n\nเขามาหาข้าเอง บอกว่า Sanath องครักษ์จะช่วยขึ้นหอเมื่อพร้อมพบ มองหา Sanath ทางเหนือ" },
        progress = { "26:1922809977:158908455 N 1:63:63", "ให้ช่วยอะไร {name}?" },
        completion = { "75:1211456586:752577231 N 102:633196638:397352373", "อา Tablet of Sael'hai... ข้าอยากศึกษามานาน\n\nขอบใจ {name} บอก Jediga ว่าทำดี คุ้มค่าจ้างที่ขอแน่นอน" },
    },
    [3562] = { -- Magatha's Payment to Jediga
        title = { "27:1014154959:4935518", "ค่าตอบแทนจาก Magatha ถึง Jediga" },
        objective = { "44:1939259698:1017392859", "ส่ง Magatha's Note ให้ Jediga ที่ Azshara" },
        description = { "139:1277554998:807659814 N 47:417634485:1232023747", "นำบันทึกนี้ไป Jediga บอกว่าค่าจ้างรอเมื่อกลับ และข้าพอใจงาน\n\nรีบไป {name} บอกนายของเจ้าว่าข้ารอที่นี่" },
        progress = { "76:1737693250:545560703", "Magatha ว่าอย่างไร? ยายแก่... พนันว่าไม่ค่อยสุภาพ" },
        completion = { "250:983359224:129406430", "อา ดี นางมีเหตุผลกว่าคาด อย่างน้อยต่อเจ้า ข้าคิดไว้ครึ่งหนึ่งว่าจะลงโทษเจ้าแทนความบังอาจที่ข้าส่งคนอื่นไป ต้องอยากได้จารึกมาก น่าสนใจ\n\nเรื่องให้คิดวันหลัง" },
        required = { [10678] = { "14:1123075112:404456814", "จดหมายของ Magatha" } },
        objectiveLabels = {
            item = { ["Magatha's Note"] = "จดหมายของ Magatha" },
        },
    },
    [3563] = { -- Jes'rimon's Payment to Jediga
        title = { "29:326267783:679916841", "ค่าตอบแทนจาก Jes'rimon ถึง Jediga" },
        objective = { "46:265522831:864934748", "ส่ง Jes'rimon's Note ให้ Jediga ที่ Azshara" },
        description = { "277:1852472941:696137221 N 1:46:46", "นำจดหมายไป Jediga บอกว่าข้อตกลงมีประโยชน์ และข้าพอใจงาน\n\nบอกให้กลับ Orgrimmar เร็ว Jes'rimon จะดูแลนางดี\n\nบอกเช่นนั้น บางทีอนาคตข้าจะใช้บริการอีก {name}" },
        progress = { "222:249016342:464193312", "คุยกับ Jes'rimon แล้วหรือ?\n\nเขาเป็นหมูป่าในหมู่โทรล แต่ข้อมูลมักแม่นและค่าจ้างดี\n\nหากทนท่าทีไหว ก็หาเงินได้ดีจากธุรกิจเขา" },
        completion = { "298:1022465554:1716443299", "ดูบันทึกก็รู้ว่าพอใจเกินพอ... เกินไปนิด\n\nบางทีสักวันข้าจะหาเวลาให้รู้ว่าซาบซึ้งการเกี้ยวพาราสีแค่ไหน อย่างน้อยก็มีเหตุหนึ่งให้อยากอยู่ Azshara นานขึ้น\n\nนี่ส่วนแบ่งค่าจ้าง" },
        required = { [10680] = { "16:755622758:1855459474", "จดหมายของ Jes'rimon" } },
        objectiveLabels = {
            item = { ["Jes'rimon's Note"] = "จดหมายของ Jes'rimon" },
        },
    },
    [3564] = { -- Andron's Payment to Jediga
        title = { "26:1602568421:613954819", "ค่าตอบแทนจาก Andron ถึง Jediga" },
        objective = { "43:1808834324:515722425", "ส่ง Andron's Note ให้ Jediga ที่ Azshara" },
        description = { "54:799164060:1712568812", "นี่... เอา... <สะอึก> ไปให้ Jediga โชคดี!" },
        progress = { "104:743193752:611546753", "พบ Andron หรือยัง? แทบไม่ออก Undercity คงหาตัวไม่ยาก" },
        completion = { "83:241694582:1814388253 N 164:1370461623:597492904", "สมบูรณ์แบบ... เดี๋ยวนะ\n\nฮ่าฮ่า! เจ้าเล่าอะไรตอนส่งจารึก {name}? เขาจ่ายเกินมาก! ไม่ใช่บ่นนะ บอกว่าข้อตกลงเปลี่ยนหรือ? หรือเมาอีก?\n\nไม่สำคัญ... นี่ รับส่วนแบ่งเพิ่มด้วย" },
    },
    [3565] = { -- Xylem's Payment to Jediga
        title = { "25:1881318830:2012158051", "ค่าตอบแทนจาก Xylem ถึง Jediga" },
        objective = { "42:1733389889:618178745", "ส่ง Xylem's Note ให้ Jediga ที่ Azshara" },
        description = { "136:1548581348:175400575", "อะไรนะ? อ้อ ค่าจ้าง แน่นอน\n\nรับนี่แล้วไป ข้าแน่ใจว่า Jediga รอเจ้ากลับอย่างอดทนเหลือเกิน" },
        progress = { "125:1588716657:1994742991", "Xylem ว่าอย่างไร? ไม่ได้ทำอะไรเจ้าใช่ไหม? ร่ายเวทใส่? หลอกให้ทำงาน?" },
        completion = { "265:56494980:1288384546", "ไม่มีปัญหา? เลยหรือ? นั่นน่าคิด... ข้าคาดว่าจะลังเลหรืออย่างน้อยผิดข้อตกลง อืม บางทีไว้ใจได้จริง\n\nไม่ต้องคิดมาก นี่ส่วนแบ่ง ขอบใจที่ช่วย" },
    },
    [3601] = { -- Kim'jael Indeed!
        title = { "16:342527503:1502386092", "Kim'jael อย่างนั้นหรือ!" },
        objective = { "132:260898601:245391952", "ค้น Thalassian Base Camp หา Kim'jael's Compass, Scope, Stuffed Chicken และ Wizzlegoober แล้วนำกลับไปคืนเขาที่ Azshara" },
        description = { "70:883202476:1199386433 N 429:1749304679:577768001", "Kim'jael อย่างนั้นหรือ!! รู้ไหมคำนี้หมายถึงอะไรสำหรับบลัดเอลฟ์ {name}? หนูตัวเล็ก... หรือทำนองนั้น พวกอันธพาล!\n\nจ้างให้ช่วยสำรวจหาสมบัติหาย พอได้ยินสมบัติกับจำนวนเงิน ข้าก็ตกลง แต่แล้วหันมาเล่นงานจะฆ่าข้า... ข้าเนี่ยนะ!\n\nแสดงว่าไว้ใจบลัดเอลฟ์ไม่ได้\n\nปัญหาคือยังมีอุปกรณ์ข้า และเอาคืนเองไม่ได้ ช่วยทีได้ไหม?" },
        progress = { "193:442568192:2100443335", "บลัดเอลฟ์เหม็นนั่น หากข้าแกร่งเช่นเจ้า จะลงไปสั่งสอนเอง! แต่ต้องยอมจ่ายให้เจ้าจัดการแทน" },
        completion = { "309:1734768117:459597636", "ฮ่าฮ่า! จัดการหนักเลยใช่ไหม?!\n\nเยี่ยม! สั่งสอนบลัดเอลฟ์ให้รู้ว่าอย่าทรยศคู่ค้า โดยเฉพาะผู้ภักดีเช่นพ่อค้าก็อบลิน! ฮึ บลัดเอลฟ์...!\n\nอย่างน้อยต้องจ่ายเวลาของเจ้าตามพูด\n\nนี่... น่ามีประโยชน์" },
        required = { [10717] = { "18:1085071791:595198002", "เข็มทิศของคิมแจล" }, [10715] = { "16:1833732850:3198426", "กล้องเล็งของคิมแจล" }, [10722] = { "26:1091342031:407942498", "ไก่ยัดไส้ของคิมแจล" }, [10718] = { "23:1188880899:2015254121", "วิซเซิลกูเบอร์ของคิมแจล" } },
        objectiveLabels = {
            item = { ["Kim'Jael's Compass"] = "เข็มทิศของคิมแจล", ["Kim'Jael's Scope"] = "กล้องเล็งของคิมแจล", ["Kim'Jael's Stuffed Chicken"] = "ไก่ยัดไส้ของคิมแจล", ["Kim'Jael's Wizzlegoober"] = "วิซเซิลกูเบอร์ของคิมแจล" },
        },
    },
    [3602] = { -- Azsharite
        title = { "9:570375241:466209415", "Azsharite" },
        objective = { "204:780327439:429285682", "เก็บ Crystallized Azsharite ยี่สิบชิ้นจาก Azshara ตอนใต้ อาจใช้ Felhound ช่วยดมหาแหล่งที่ซ่อนอย่างแนบเนียน\n\nเสร็จแล้วกลับไปหา Loramus" },
        description = { "497:1678640722:839229093", "ยักษ์หน้าผาโบราณทางใต้ของ Azshara กินหินและสิ่งปลูกสร้างเป็นอาหาร มูลของมันกลายเป็นผลึกที่ขึ้นรูปได้ง่ายและแข็งแกร่งมาก เรียกว่า Azsharite\n\nมีแหล่งผลึกอยู่ทั่วแนวโค้งทางใต้ แต่เก็บกลับมาได้น้อย เพราะยักษ์เหล่านี้ดุร้ายมาก\n\nเจ้าต้องลงใต้ไปเก็บให้พอสร้างตัวอาวุธ Felhound ของข้าจะช่วยค้นหาให้" },
        progress = { "111:441757879:384277643", "ความชั่วไม่หลับ เจ้าโง่ มีเวลาพักเมื่อตายแล้ว นำผลึกมาเดี๋ยวนี้" },
        completion = { "122:414698361:2021724180", "งาน Azshara เสร็จแล้ว ผู้มีอายุขัย ข้าต้องตีส่วนประกอบสำหรับขั้นต่อไปในการผจญภัย" },
        required = { [10714] = { "22:561718602:1953721447", "แอซชาริตตกผลึก" } },
        objectiveLabels = {
            item = { ["Crystallized Azsharite"] = "แอซชาริตตกผลึก" },
        },
    },
    [3621] = { -- The Formation of Felbane
        title = { "24:1444916465:351379120", "การสร้าง Felbane" },
        objective = { "62:1975448211:1759515639", "นำ Shipment ไปให้ Galvan the Ancient ที่ Stranglethorn Vale" },
        description = { "469:2049506734:635251231", "วัสดุสำหรับตีอาวุธพร้อมแล้ว เจ้าต้องนำ Azsharite ที่ผ่านการชุบไปให้ช่างที่ควบคุมพลังเฟลได้\n\nมีช่างเช่นนั้นอยู่ใน Stranglethorn Vale เขาคือ Galvan the Ancient ผู้นำ Mithril Order เขาจะสร้างอาวุธตามข้อกำหนดของข้าได้ ค่ายของเขาอยู่ระหว่าง Zul'Gurub กับเนินโอเกอร์ Mosh'Ogg\n\nขอให้ความมุ่งมั่นและศรัทธาพาเจ้าผ่านพ้นไป หากเจ้าล้มเหลว จงรู้ว่าเหล่าเทพของเจ้ายิ้มให้เจ้าอยู่ ผู้มีอายุขัย" },
        progress = { "65:1577837489:700879428", "Loramus หรือ? ไม่ได้ยินชื่อนี้หลายปีแล้ว" },
        completion = { "168:589043272:1398604454", "โอ้ ข้าได้แต่คิดว่าเจ้าผ่านอะไรมาหาวัสดุ น้อยคนเข้า Azshara แล้วรอด ยิ่งผู้เผชิญกึ่งเทพกับยักษ์ยิ่งน้อย!" },
    },
    [5526] = { -- Shards of the Felvine
        title = { "21:2135155714:174601044", "เศษแห่ง Felvine" },
        objective = { "268:594600770:1141746816", "หา Felvine ใน Dire Maul แล้วเก็บเศษจากมัน น่าจะทำได้เมื่อ Alzzin the Wildshaper ตาย ใช้ Reliquary of Purity ผนึกเศษอย่างปลอดภัย แล้วนำกลับไปให้ Rabine Saturna ที่ Nighthaven ใน Moonglade" },
        description = { "81:1678778121:246661450 N 398:1407524071:259902589", "ถึงเวลานำความรู้เรื่อง Eldre'Thalas หรือ Dire Maul ใน Feralas มาใช้แล้ว {name} ทางตะวันออกของเมืองปรักหักพังเป็นเขตที่ Alzzin the Wildshaper ครอบงำด้วยความเสื่อมทราม จงรีบไปและฝ่าความท้าทายที่รออยู่\n\nFruit of Fertility ซึ่งบัดนี้แปดเปื้อนจนกลายเป็น Felvine น่าจะอยู่ใกล้ Alzzin เมื่อเขาล้มลง จงเก็บแก่นพลังให้ได้เท่าที่ทำได้ ผนึกใน Reliquary แล้วนำกลับมา\n\nโชคดี ขอพลังแห่ง Cenarion เร่งฝีเท้าเจ้า" },
        progress = { "323:1581783255:1732645269", "เมื่อมี Sealed Reliquary of Purity เราไม่เพียงกำจัดภัยแปดเปื้อนจากโลก แต่ศึกษาภายใต้การเฝ้ารอบคอบได้ อาจคิดวิธีใหม่ต้านความเสื่อมทรามที่คุกคาม Azeroth ไม่หยุด\n\nข้ารู้ว่า Milli คงไม่ต้องการแบบอื่น..." },
        completion = { "18:1831426748:1070901071 C 305:1938825359:1441266567 N 12:513407318:1685728707", "สำเร็จแล้ว {class} ผู้กล้า Cenarion Circle จึงติดหนี้เจ้า แม้สงครามยังไกลจบ แต่ชนะศึกใหญ่ต่อผู้หวังนำหายนะ\n\nรับสิ่งนี้แทนความขอบคุณยั่งยืน จงรู้ว่าที่นี่ต้อนรับเจ้าเป็นวีรชน Cenarion Circle เพราะผลงาน {name} ขอบใจ" },
        required = { [18540] = { "26:1944402535:823657024", "ผอบแห่งความบริสุทธิ์ที่ผนึกแล้ว" } },
        objectiveLabels = {
            item = { ["Sealed Reliquary of Purity"] = "ผอบแห่งความบริสุทธิ์ที่ผนึกแล้ว" },
        },
    },
    [5527] = { -- A Reliquary of Purity
        title = { "21:849539804:805867978", "ภาชนะ Reliquary of Purity" },
        objective = { "181:1170810194:1922067671", "เดินทางไป Silithus ค้นหา Reliquary of Purity ในซาก Southwind Village หากพบให้นำกลับไปให้ Rabine Saturna ที่ Nighthaven ใน Moonglade" },
        description = { "486:142329376:1953402857", "ขั้นแรกเราต้องหาภาชนะที่เก็บสารอันเสื่อมทรามร้ายแรงได้โดยไม่ทำอันตรายผู้ถือ ข้ารู้จักเพียงชนิดเดียวที่อาจกักสิ่งชั่วร้ายอย่าง Felvine ไว้ได้ นั่นคือ Reliquary of Purity\n\nลึกเข้าไปใน Silithus มีซากหมู่บ้านไนต์เอลฟ์ชื่อ Southwind ข้ารู้ว่าเคยมีภาชนะนี้อยู่ที่นั่นเมื่อหลายปีก่อน หากเราจะทำสำเร็จ เจ้าต้องค้นซากหมู่บ้านและหวังว่าจะนำมันกลับมาได้" },
        progress = { "466:1633856211:181629", "Reliquary of Purity เป็นวัตถุโบราณในตัว สร้างน้อย และแทบทั้งหมดเชื่อว่าสูญตามเวลา\n\nยอมรับว่ารู้เรื่องอันที่ Southwind มาพักหนึ่ง พูดตรง ๆ เมื่อ Silithus วุ่นวายขึ้น ข้าคิดเก็บความลับไว้ การแหย่ค้นมีแต่ทำศัตรูสงสัย\n\nแต่เวลานิ่งเฉยจบแล้ว โดยเฉพาะสถานการณ์ Eldre'Thalas" },
        completion = { "308:2020074152:1106648871", "เจ้าหาวิธีได้เก่งตามคำร่ำลือจริง Cenarion Circle โชคดีที่มีเจ้าทำงานแทน\n\nเมื่อ Reliquary กลับในมือ ใจก็สงบ ข้าขอให้เจ้าทั้งเผชิญปีศาจชั่ว และนำของอันตรายกลับมาได้สบายใจขึ้น..." },
        required = { [22201] = { "19:1228770689:675489138", "ผอบแห่งความบริสุทธิ์" } },
        objectiveLabels = {
            item = { ["Reliquary of Purity"] = "ผอบแห่งความบริสุทธิ์" },
        },
    },
    [5534] = { -- Kim'jael's "Missing" Equipment
        title = { "30:1846376148:1569561349", "อุปกรณ์ที่ “หาย” ของ Kim'jael" },
        objective = { "116:2024432887:1083318564", "หา Some Rune ที่นากาครอบครองใน Ruins of Eldarath แล้วนำกลับไปให้ Kim'jael ที่ Azshara" },
        description = { "475:1995780728:1900169266", "อะไร?! อะไร?!\n\nยังไม่ดีพอหรือ? รู้ไหมวัตถุระเบิดแพงแค่ไหน ขายได้... ช่างเถอะ อยากได้เงินจริงหรือ? ธุรกิจเป็นแบบนี้ พิสูจน์ว่าเป็นลูกจ้างมีค่า อดทนหน่อยแล้วได้รางวัลเหมาะสม\n\nหากมีค่าจริง ไป Ruins of Eldarath หารูนที่บลัดเอลฟ์มองหา ดูเหมือนนากามีอยู่" },
        progress = { "6:1836729114:1970545366 N 270:1151860204:1369809884", "ว่าอย่างไร {name}? รูนอยู่ไหน? เจ้าเป็นลูกจ้างดีใช่ไหม? มาช่วยใช่ไหม?\n\nอย่าให้คิดใหม่เรื่องค่าจ้างที่ตกลง อะไร? ยังไม่ได้ตกลงหรือ? โอ้ ดี... งั้นตามสบาย แต่รู้ไว้ว่าช้ามากก็ได้น้อยมาก" },
        completion = { "225:106679823:95983231 N 95:1670803621:894134445", "ฮ่าฮ่า! วิเศษ!\n\nข้าจะหาว่ามันใช้ทำไม และ Magus Rimtori ยายตัวดีที่จ้างข้าอยากได้ทำไม ฮ่า! คราวนี้จับไต๋ได้ บลัดเอลฟ์เหม็น! Kim'jael! ฮ่า! จะสอนว่าใครเป็นหนู!\n\nทำได้ดี {name} ขอบใจมาก นี่เงิน ไปได้ ข้ามีเรื่องต้องคิด" },
        required = { [13815] = { "9:1661780921:1225720166", "อักขระบางอย่าง" } },
        objectiveLabels = {
            item = { ["Some Rune"] = "อักขระบางอย่าง" },
        },
    },
    [5535] = { -- Spiritual Unrest
        title = { "16:1238092898:571898181", "วิญญาณไม่สงบ" },
        objective = { "97:1279061128:1906557707", "ทำลาย Highborne Apparition 6 ตน และ Highborne Lichling 6 ตน แล้วกลับไปหา Loh'atu ที่ Azshara" },
        description = { "490:1908765116:1171449604", "นานมาแล้ว ไฮบอร์นเป็นหนึ่งในกลุ่มผู้ศึกษาศาสตร์อาร์เคนที่ทรงพลังที่สุดของไนต์เอลฟ์ ความเสื่อมทรามที่มากับศาสตร์นั้นสร้างความเสียหายใหญ่หลวงต่อสังคมไนต์เอลฟ์และ Azeroth ซึ่งเจ้าคงรู้ดี\n\nข้าสัญญากับเหล่าเซนทิเนลว่าจะปลดปล่อยวิญญาณจากพันธะของโลกนี้เมื่อพบ หากเจ้าช่วยด้วย ข้าก็ให้รางวัลได้\n\nพวกเขาหลอกหลอนอยู่ที่ Shadowsong Shrine ทางตะวันออกเฉียงเหนือจากที่นี่" },
        progress = { "48:2110248243:1502201650 C 282:420335789:545606419", "หาวิญญาณไฮบอร์นเป็นอย่างไร {class}?\n\nหลายเหตุการณ์ทำทุกเผ่า Azeroth ทุกข์หนัก แต่ไม่รู้ทำไมวิญญาณเหล่านี้ดูเป็นภัยทุกคน อาจเพราะยังปรารถนาเวทอาร์เคน ความอยากเช่นนั้นเป็นลาง Burning Legion เรารู้ว่าจะนำสู่อะไร" },
        completion = { "11:534428891:784080240 C 226:1883642241:156628721", "ทำได้ดี {class} ขอบใจที่ช่วย วิญญาณสงบ ภัยที่ความอยากอาร์เคนชักนำลดลง\n\nมั่นใจว่าทั้งสองฝ่ายในความขัดแย้งที่ฉีก Azeroth จะเห็นว่าเจ้าอยู่เหนือเรื่องนั้น" },
    },
    [5536] = { -- A Land Filled with Hatred
        title = { "25:1589653495:1307451826", "แผ่นดินเปี่ยมความเกลียดชัง" },
        objective = { "117:656834767:2021477842", "สังหาร Haldarr Satyr 6 ตน, Haldarr Trickster 2 ตน และ Haldarr Felsworn 2 ตน แล้วกลับไปหา Loh'atu ที่ชายแดน Ashenvale" },
        description = { "504:110503512:499020597", "เหล่าเซเทียร์คือไนต์เอลฟ์ที่กลายสภาพเป็นสิ่งชั่วร้ายอัปลักษณ์ บัดนี้พวกมันแปดเปื้อนดินแดนศักดิ์สิทธิ์ที่ Cenarius เคยย่างเท้า ข้าพูดแทนไนต์เอลฟ์ถึงความโหดร้ายทั้งหมดของปีศาจเหล่านั้นไม่ได้ แต่ข้าสาบานต่อ Earthmother ว่าจะช่วยเหล่าเอลฟ์ขจัดภัยนี้\n\nข้าเชื่อว่าเจ้าจะพิสูจน์ตนได้ด้วยการช่วยชำระดินแดน\n\nทางตะวันออกเฉียงเหนือมีพวก Haldarr อยู่ จงทดสอบพลังกับพวกมันแล้วกลับมาหาข้า" },
        progress = { "40:1423936523:2139095398 C 94:1562202618:1820787938", "ศึกเซเทียร์เป็นอย่างไร {class}?\n\nแกร่งตามที่คิดไหม? มากกว่า? หรือไม่มีค่าเทียบพลังเจ้า?" },
        completion = { "11:534428891:784080240 C 400:891173179:1073998426", "ทำได้ดี {class} เห็นว่าเจ้าไม่เพียงมีฝีมือ แต่ไหวพริบ การปราบพวกมันพิสูจน์ความภักดีหลัก Earthmother แม้ไม่ยอมรับนางเป็นเทพตน นางอยู่ในทุกสิ่งบนดาวนี้และไกลออกไป ดวงตาหนึ่งมืดหนึ่งสว่างเดินทางข้ามฟ้า เฝ้ามองเราเสมอ\n\nรับเงินเล็กน้อยแทนความขอบคุณเถอะ" },
    },
    [5932] = { -- Back to Thunder Bluff
        title = { "21:295941854:140277298", "กลับ Thunder Bluff" },
        objective = { "73:525856024:654813708", "กลับ Thunder Bluff แล้วคุยกับ Turak Runetotem บน Elder Rise" },
        description = { "418:514511282:1927904656", "ถึงเวลาที่เราต้องแยกจากกันแล้ว เจ้าผู้เยาว์วัย การนำบทเรียนไปใช้จะพาเจ้ากลับไปหาผู้ที่ส่งเจ้ามาพบข้า แม้ทอเรนจะถูกมองว่ายังใหม่ต่อวิถีของ Cenarius แต่ Turak Runetotem ก็ดำเนินชีวิตอย่างสมดุลกับธรรมชาติ จงฟังคำแนะนำของเขา แล้วเจ้าจะเรียนบทแรกแห่งผู้รักษาสมดุลจบในไม่ช้า\n\nไปเถิด เราจะได้พบกันอีก" },
        completion = { "14:1649650394:897424258 N 477:317373951:1047605683", "ยินดีต้อนรับกลับ {name} ข้าสัมผัสได้ว่าการพบ Great Bear Spirit ครั้งแรกของเจ้าเป็นเช่นเดียวกับดรูอิดทุกคนที่เริ่มวิถีแห่งกงเล็บ ชวนสับสนเล็กน้อย แต่ลึกซึ้งยิ่งนัก ข้าเองก็เคยรู้สึกเช่นนั้น\n\nGreat Bear Spirit อยู่คู่ Azeroth มานานเท่าที่ดาวดวงนี้อยู่บนฟ้า ทอเรนตั้งใจฟังวิญญาณเช่นนั้น และเติบโตด้วยการเรียนรู้จุดมุ่งหมายของพวกเขา บัดนี้ถึงบททดสอบแรกแห่งจุดมุ่งหมายของเจ้าแล้ว ฟังให้ดี..." },
    },
    [6804] = { -- Poisoned Water
        title = { "14:342342095:1384222171", "น้ำปนพิษ" },
        objective = { "157:1966444376:1607810025", "ใช้ Aspect of Neptulon กับธาตุติดพิษใน Eastern Plaguelands แล้วนำ Discordant Bracer 12 ชิ้นกับ Aspect of Neptulon ไปให้ Duke Hydraxis ที่ Azshara" },
        description = { "480:693252893:1143130275", "หน่วยสอดแนมธาตุของเราถูกส่งไปยัง Plaguelands ทางตะวันออกของ Lordaeron โรคระบาดที่นั่นบิดเบือนและทำให้พวกเขาติดเชื้อ เหล่า Waterlord จะยอมให้ความบริสุทธิ์ถูกลบหลู่เช่นนี้ไม่ได้!\n\nรับขวดนี้ไป ข้างในมีพลังส่วนหนึ่งของ Neptulon หากใช้กับธาตุที่ติดโรค มันจะต่อสู้กับพิษในร่างและรักษาพวกเขา! แต่การปะทะกันภายในจะทำให้พวกเขาคลุ้มคลั่งและปั่นป่วน\n\nจงปราบ Discordant Surge แล้วนำกำไลพันธนาการกลับมา" },
        progress = { "24:914518599:1002401008", "มีกำไลหรือยัง?" },
        completion = { "20:1921578502:569519135 C 177:658675773:1910610870", "ทำได้ดี {class} ธาตุแปดเปื้อนที่เจ้ารักษาคือความอัปยศต่อสายน้ำทั้งปวง พลังเราอยู่ในความบริสุทธิ์ หากจะชนะศึกธาตุอื่น ต้องเข้มแข็งต่อไป" },
        required = { [17309] = { "18:677778847:533978555", "ปลอกแขนแห่งความบาดหมาง" } },
        objectiveLabels = {
            item = { ["Discordant Bracers"] = "ปลอกแขนแห่งความบาดหมาง" },
        },
    },
    [6805] = { -- Stormers and Rumblers
        title = { "21:197664513:624903511", "เหล่า Stormer และ Rumbler" },
        objective = { "89:383636619:907778548", "สังหาร Dust Stormer 15 ตนและ Desert Rumbler 15 ตน แล้วกลับไปหา Duke Hydraxis ที่ Azshara" },
        description = { "495:1393243153:302612566", "พวกเราธาตุน้ำกำลังทำสงครามกับธาตุที่ด้อยกว่า หากเจ้าเป็นพันธมิตรที่แท้จริง จงแสดงความตั้งใจ!\n\nไกลลงไปทางใต้ ในทะเลทราย Silithus เหล่าข้ารับใช้แห่งลมและดินเดินพล่านอยู่ท่ามกลางโขดหินของ Crystal Vale พวกมันปกป้องวัตถุทรงพลังจากสิ่งมีชีวิตที่ด้อยกว่าอย่างเจ้าผู้มีอายุขัย แม้ข้าไม่รู้เหตุผล แต่ข้าต้องการขัดขวางพวกมัน\n\nไปที่ Crystal Vale ใน Silithus ปราบศัตรูของเราแล้วกลับมา" },
        progress = { "44:1098463133:255238019 C 40:1256832170:1518895217", "ความขี้ขลาดไม่ใช่สิ่งที่เราเคารพ {class} ไป Silithus พิสูจน์ความกล้า" },
        completion = { "142:1531659006:1225066099", "พิสูจน์ความกล้าและคุณค่าแล้ว บางทีข้าอาจมีงานอนาคตที่เหมาะพันธมิตรมีค่าของ Waterlord ยิ่งกว่า" },
    },
    [6821] = { -- Eye of the Emberseer
        title = { "20:389115428:2111153504", "ดวงตาแห่ง Emberseer" },
        objective = { "59:1141689074:1998723652", "นำ Eye of the Emberseer ไปให้ Duke Hydraxis ที่ Azshara" },
        description = { "457:821442084:1635640732", "เจ้าแสดงให้เห็นแล้วว่าสามารถปราบศัตรูและทำงานที่เป็นประโยชน์ต่อเหล่า Waterlord ได้ แต่จนถึงตอนนี้ เจ้าเผชิญเพียงศัตรูชั้นรอง หากพบศัตรูที่ทรงพลังกว่านั้น เจ้าจะชนะหรือไม่?\n\nนั่นคืองานใหม่ของเจ้า\n\nบน Blackrock Spire พวกออร์คจับข้ารับใช้แห่งไฟ Pyroguard Emberseer ไว้ จงหาที่คุมขัง สังหารผู้คุมแล้วสังหาร Emberseer นำดวงตาของมันมาให้ข้าเห็นคุณค่าของเจ้า" },
        progress = { "21:2048364956:97764307 C 52:932884782:92464576", "มีดวงตาหรือยัง {class}? มีพลังเข้า Blackrock Spire หรือไม่?" },
        completion = { "141:1770467151:1155665537 N 42:521470946:460191240", "อา มีพลังจริง และไหวพริบด้วย เพราะกำลังดิบอย่างเดียวไม่พอ Blackrock Spire\n\nจริง ๆ {name} เจ้าอาจเป็นพันธมิตรมีค่า..." },
        required = { [17322] = { "20:389115428:2111153504", "ดวงตาของเอ็มเบอร์เซียร์" } },
        objectiveLabels = {
            item = { ["Eye of the Emberseer"] = "ดวงตาของเอ็มเบอร์เซียร์" },
        },
    },
    [6822] = { -- The Molten Core
        title = { "15:1708374233:708003249", "Molten Core" },
        objective = { "114:950950646:132051520", "สังหาร Fire Lord 1 ตน, Molten Giant 1 ตน, Ancient Core Hound 1 ตัว และ Lava Surger 1 ตน แล้วกลับไปหา Duke Hydraxis ที่ Azshara" },
        description = { "N 244:1245888359:592541138 N 203:628040668:1553224746", "{name} บางทีอาจถึงเวลาทดสอบอย่างแท้จริงแล้ว เจ้าพร้อมหรือไม่?\n\nที่ส่วนลึกที่สุดของ Blackrock Depths มีทางเข้าสู่ Molten Core ฐานที่มั่นของศัตรูซึ่งเหล่าข้ารับใช้แห่งไฟที่แข็งแกร่งที่สุดบนโลกยึดครองอยู่\n\nจงไป Molten Core {name} แสดงพลังและความกล้าด้วยการปราบสิ่งที่พบ\n\nหากเจ้ามีพันธมิตร จงรวบรวมพวกเขา ต้องมีกำลังไม่น้อยกว่ากองทัพจึงจะหวังเข้าไปแล้วรอดกลับมาได้" },
        progress = { "40:1653733062:646473908 N 1:46:46", "ความสำเร็จ Molten Core รออยู่ {name}" },
        completion = { "271:2102832144:435654530", "เจ้าทำสิ่งที่ชนชาติส่วนใหญ่คิดว่าเป็นไปไม่ได้ เผชิญผู้อยู่ Molten Core และชนะ!\n\nสำหรับสิ่งมีชีวิตเล็กเพียงนี้ เจ้าแสดงไหวพริบมาก\n\nบางทีวันหนึ่งเราจะผูกพันธมิตรแท้จริงระหว่างพวกเจ้ากับ Waterlord" },
    },
    [6823] = { -- Agent of Hydraxis
        title = { "17:77719335:895429810", "ตัวแทน Hydraxis" },
        objective = { "93:2081581912:1442229207", "เพิ่มชื่อเสียงกับ Hydraxian Waterlords ถึง Honored แล้วคุยกับ Duke Hydraxis ที่ Azshara" },
        description = { "323:206529403:396122200", "หากต้องการพันธมิตรจริง ข้าเชิญให้รบศัตรู ข้ารับใช้ลม ดิน และไฟ ทุกความพ่ายแพ้ลดฐานที่มั่นมันและพิสูจน์การยึดถืออุดมการณ์เรา\n\nการรณรงค์จะยาว แต่หากยืนหยัด ความรุ่งโรจน์และเกียรติจะยิ่งใหญ่" },
        progress = { "31:2122912318:1415310740 N 145:1496059527:728764075", "การรณรงค์ยังไม่จบ {name} ออกปราบศัตรู ข้ารับใช้ลม ดิน และไฟ บางทีวันหนึ่งจะได้ที่ในห้องโถง Waterlord" },
        completion = { "79:1676365346:1509522981 N 172:1388578712:656299834", "วีรกรรมที่เจ้าต่อกรกับศัตรูของเราดังก้องไปทั่วห้องโถงของเหล่า Waterlord {name} บางคนเคยคิดว่าร่างกายของเจ้าเล็กและเปราะบางเกินกว่าจะร่วมสงครามนี้ แต่เจ้ากลับก้าวหน้าอย่างมากและได้รับความเคารพ ความสำเร็จของเจ้าช่างเหลือเชื่อ" },
    },
    [6824] = { -- Hands of the Enemy
        title = { "18:1794405590:1772549704", "มือของศัตรู" },
        objective = { "89:1901658728:204305637", "นำ Hands of Lucifron, Sulfuron, Gehennas และ Shazzrah ไปให้ Duke Hydraxis ที่ Azshara" },
        description = { "N 420:51651791:755525273 N 68:315563825:542841021", "{name} การรับใช้ของเจ้ามีคุณค่ามาก เราจึงลังเลที่จะมอบงานสุดท้ายให้ เพราะไม่อยากสูญเสียตัวแทนที่มีประโยชน์\n\nแต่หากสำเร็จ งานนี้จะช่วยสงครามของเรามหาศาล และ... ด้วยเหตุนี้ เราจึงเห็นว่าคุ้มที่จะให้เจ้าเสี่ยง\n\nเราต้องการกำจัดผู้นำของ Molten Core ได้แก่ Lucifron, Sulfuron, Gehennas และ Shazzrah จงสังหารแล้วนำมือของพวกมันมา!\n\nงานนี้ต้องใช้ทุกสิ่งที่เจ้ามี {name} แต่หากทำได้ Firelord จะเสียหายอย่างหนัก" },
        progress = { "43:1299659364:88040528 N 37:392381915:650529108", "ปราบ Lucifron กับพวกแล้วหรือ {name}? มีมือศัตรูไหม?" },
        completion = { "139:1584538593:474026546 N 161:1989677501:107266932 N 32:1470714782:79079061", "เจ้ามีมือแล้ว! ปราบผู้นำไฟแล้ว! หากไม่รู้จักเจ้าและความสามารถ ข้าคงไม่เชื่อว่าเป็นไปได้\n\n{name} วีรกรรมมากนับไม่ถ้วน แต่เรื่องล่าสุดจะสะเทือนหมู่ Waterlord สักวันชื่อเจ้าอาจเป็นตำนาน\n\nคุยกับข้าอีก {name} อาจยังมีงาน..." },
        required = { [17332] = { "16:1031587070:461278507", "มือของชาซราห์" }, [17329] = { "16:2044064642:1280368827", "มือของลูซิฟรอน" }, [17331] = { "16:692252754:1322291552", "มือของเกเฮนนัส" }, [17330] = { "16:1531030751:931850005", "มือของซัลฟูรอน" } },
        objectiveLabels = {
            item = { ["Hand of Shazzrah"] = "มือของชาซราห์", ["Hand of Lucifron"] = "มือของลูซิฟรอน", ["Hand of Gehennas"] = "มือของเกเฮนนัส", ["Hand of Sulfuron"] = "มือของซัลฟูรอน" },
        },
    },
    [6845] = { -- Uncovering Past Secrets
        title = { "23:539306079:607214299", "ค้นความลับอดีต" },
        objective = { "66:1131727344:1888740282", "คุยกับ Rabine Saturna ที่ Nighthaven ใน Moonglade" },
        description = { "398:1087089989:1471761908 N 76:571073933:1155399770", "อย่างไรก็ควรกลับมาหาข้าเร็ว ๆ หากเจ้าอยากรู้ว่าข้างในมีอะไร ทันทีที่ข้ารู้ว่ามันคืออะไร และหากมันเป็นหนังสือจริง ข้ายินดีแบ่งปันข้อมูล\n\nระหว่างนี้ไปหาผู้ดูแลค่ายหมีน้อยของเรา Rabine เถิด เขาคงอยากรู้ว่าเจ้าไปก่อเรื่องบ้า ๆ อะไรมา อย่าปล่อยให้ผู้ดูแลค่ายรอนาน {name}... เว้นแต่ว่าเจ้าอยากถูกน้ำผึ้งราด\n\nเคยเกิดเรื่องแบบนั้นมาแล้ว เชื่อข้าสิ" },
        completion = { "4:1110228981:147916455 N 452:607739964:651599661 C 1:46:46", "อา {name} ข้าหวังว่าเจ้าจะแวะมา ดีใจที่เจ้าปลอดภัย\n\nข้าได้รับข่าวว่าเจ้าจะกลับจากภาคสนาม จึงอยากขอบคุณเป็นการส่วนตัวในนาม Cenarion Circle สำหรับความช่วยเหลือที่ผ่านมา ยังมีความลับใน Silithus อีกแน่ สิ่งที่เจ้าส่งให้ Umber คงน่าสนใจเมื่อเปิดเผยออกมา โปรดรับสิ่งนี้แทนความซาบซึ้งที่เรามีต่อเจ้าเสมอ\n\nขอบใจ {class} ผู้มีน้ำใจ" },
    },
    [7486] = { -- A Hero's Reward
        title = { "15:265978599:1735802041", "รางวัลวีรชน" },
        objective = { "40:1657330501:1860892220", "รับรางวัลจาก Hydraxis' Coffer" },
        description = { "N 344:2025237176:929560271 N 20:828768447:1910552832", "{name} การรับใช้เหล่า Waterlord ของเจ้าเหนือกว่าทุกสิ่งที่เราคาดจากสิ่งมีชีวิตบนโลกนี้\n\nเราไม่เข้าใจแนวคิดเรื่องการขอบคุณหรือให้รางวัลความดีของพวกเจ้านัก แต่ในกรณีนี้... บางทีก็สมควร\n\nใต้คลื่นบริเวณฐานด้านใต้ของเกาะ มีหีบอยู่ ในนั้นคือ... รางวัลของเจ้า\n\nไปเถิด {name} ไปรับรางวัลของเจ้า" },
        completion = { "88:868623246:904348794 N 57:630923279:2120170867", "เสียง Hydraxis ลงมาจากผิวน้ำ...\n\n\"เลือกสิ่งเหมาะที่สุด {name} ขอให้ปกป้องจากศัตรู Waterlord\"" },
    },
    [7633] = { -- An Introduction
        title = { "15:1608436584:1761191096", "แนะนำตัว" },
        completion = { "45:1681517388:1433567366 C 415:857184133:590151341", "เรารับรู้ถึงความขยันและความซื่อตรงของเจ้า {class}\n\nพวกเราคือ Ancient ผู้พิทักษ์ผืนป่าที่ครั้งหนึ่งเคยยิ่งใหญ่ ร่างกายของเราถูกทำลายเมื่อ 10,000 ปีก่อน ตอน Archimonde และ Burning Legion เดินทัพสู่ Hyjal แต่วิญญาณของเรายังสมบูรณ์\n\nเรามีงานให้เจ้าทำ หากสำเร็จ เราจะเปิดเผยความลับของเหล่า Ancient\n\nจงรู้ว่าเมื่อทำครบแล้ว เพียงกลับมาที่ศิลานี้ เราจะตอบรับเสียงเรียกของเจ้า" },
    },
    [8575] = { -- Azuregos's Magical Ledger
        title = { "25:1192644958:1566191107", "บัญชีเวทของ Azuregos" },
        objective = { "66:1085000287:478316305", "ส่ง Azuregos's Magical Ledger ให้ Narain Soothfancy ที่ Tanaris" },
        description = { "103:927297031:1323972744", "เจ้าอ่านบัญชีนี้ไม่ออกสักคำ ไม่รู้ด้วยซ้ำว่าเขียนภาษาอะไร!" },
        progress = { "38:623210996:31676028", "โอ้! ของเต้นตุบมีเวท! ให้ข้าหรือ?" },
        completion = { "51:1223746102:1258406660 R 46:1039158764:1535596181", "<Narain ตรวจจดหมายอย่างกระตือรือร้น>\n\nยอดเยี่ยม ชาว{race}! มันคืออะไร? ข้าอ่าน Draconic ไม่ออกสักนิด" },
    },
    [8729] = { -- The Wrath of Neptulon
        title = { "21:1300821522:1200325959", "โทสะของ Neptulon" },
        objective = { "80:1396792850:541905080", "ใช้ Arcanite Buoy ที่ Swirling Maelstrom ใน Bay of Storms แห่ง Azshara" },
        description = { "470:1869548536:1090717589", "ข้าบอกข่าวร้ายไปหรือยัง? มันชื่อ Maws เป็นความตายและการทำลายล้างที่ยาวถึง 100 ฟุต ข้าคงลืมรายละเอียดเล็กน้อยนั้นไป\n\nจากญาณทิพย์อันเหนือชั้นของข้า จุดที่เหมาะที่สุดสำหรับปล่อยทุ่นอยู่ใน Bay of Storms นอกชายฝั่ง Azshara\n\nมองหาน้ำวนที่หมุนเชี่ยว น่าจะมีซากเกลื่อนอยู่\n\nอีกอย่าง หวังว่าเจ้าจะมีเพื่อนมาด้วย\n\nหากเกิดปาฏิหาริย์แล้วเจ้าทำสำเร็จ จงนำเศษคทาไปให้ Anachronos" },
        progress = { "30:1373479720:213971271", "เวลาใกล้หมด ยอดนักรบ" },
        completion = { "11:534428891:784080240 N 66:1892969467:319747043", "ทำได้ดี {name} อีกไม่นานข้าจะประกอบ Scepter of the Shifting Sands ใหม่ได้" },
        required = { [21137] = { "18:731355089:2064675144", "ชิ้นส่วนคทาสีน้ำเงิน" } },
        objectiveLabels = {
            item = { ["Blue Scepter Shard"] = "ชิ้นส่วนคทาสีน้ำเงิน" },
        },
    },
    [8735] = { -- The Nightmare's Corruption
        title = { "26:1695459280:1316391442", "ความแปดเปื้อนแห่งฝันร้าย" },
        objective = { "192:1017371513:1339348397", "เดินทางไปประตู Emerald Dream ทั้งสี่ใน Azeroth เก็บ Fragment of the Nightmare's Corruption จากแต่ละแห่ง ครบแล้วกลับไปหา Keeper Remulos ที่ Moonglade" },
        description = { "237:1655311112:40753343", "เจ้าต้องไปยังประตูแห่งฝันทั้งสี่ใน Azeroth แล้วเก็บเศษความแปดเปื้อนแห่งฝันร้ายจากแต่ละแห่ง เหล่าดรากอนคินที่อาศัยอยู่บริเวณนั้นมีเศษเหล่านี้ เมื่อได้ครบแล้วจงกลับมาหาข้า" },
        progress = { "34:1302061906:639834582", "<Remulos จมในความคิดลึก>" },
        completion = { "140:1937888668:807447370", "เจ้าพร้อมหรือ? โลกพร้อมรับสิ่งที่เรากำลังจะเรียกมาหรือ? ข้าไม่รู้... หน้าที่ที่ข้ามีต่อ Malfurion ผูกมัดข้าไว้ หน้าที่และเกียรติ..." },
        required = { [21147] = { "38:410332928:1436406552", "เศษเสี้ยวความเสื่อมทรามแห่งฝันร้าย" }, [21149] = { "38:410332928:1436406552", "เศษเสี้ยวความเสื่อมทรามแห่งฝันร้าย" }, [21148] = { "38:410332928:1436406552", "เศษเสี้ยวความเสื่อมทรามแห่งฝันร้าย" }, [21146] = { "38:410332928:1436406552", "เศษเสี้ยวความเสื่อมทรามแห่งฝันร้าย" } },
        objectiveLabels = {
            item = { ["Fragment of the Nightmare's Corruption"] = "เศษเสี้ยวความเสื่อมทรามแห่งฝันร้าย" },
        },
    },
    [8736] = { -- The Nightmare Manifests
        title = { "23:1186451895:2138634426", "ฝันร้ายปรากฏกาย" },
        objective = { "120:677647489:768837857", "ปกป้อง Nighthaven จาก Eranikus อย่าให้ Keeper Remulos ตาย ห้ามสังหาร Eranikus ป้องกันตัวและรอ Tyrande" },
        description = { "265:1852745249:2123451126", "เราต้องยั้งมือต่อ Eranikus เป้าหมายของเราคือไถ่คืนเขา ไม่ใช่ทำลายเขา\n\nTyrande กำลังเดินทางมาช่วย เราต้องทนต่อการโจมตีของมังกรและรักษา Nighthaven ไว้จากการทำลายล้างที่แน่นอน\n\nจงระวัง! เจ้าและพันธมิตรคือความหวังเพียงหนึ่งเดียวของเรา" },
        completion = { "16:1261351344:202080615 N 159:1067995314:89839208 N 105:1180995335:1400716500", "เขาได้รับการปลดปล่อยแล้ว {name} เขากลับสู่ Dream เพื่อแก้ไขความผิดที่ตนก่อ Eranikus จะเป็นพันธมิตรที่ทรงพลังของ Malfurion และบิดาข้า\n\nยุทโธปกรณ์ชิ้นนี้เป็นของเจ้า {name} Ysera มอบให้ข้าด้วยตนเอง จงใช้มันให้ดีในศึกกับเหล่า Qiraji" },
    },
    [8741] = { -- The Champion Returns
        title = { "20:436261112:1219312213", "ยอดนักรบกลับมา" },
        objective = { "77:1237483266:1547483134", "นำ Green Scepter Shard ไปให้ Anachronos ที่ Caverns of Time ใน Tanaris" },
        description = { "31:682202960:1752542371 N 68:914683018:90899653", "ผู้พิทักษ์รอการกลับมาของเจ้าอยู่ {name} จงนำเศษคทาสีเขียวไปให้ Anachronos ที่ Caverns of Time" },
        completion = { "176:591244374:1645072239 N 1:46:46", "วีรกรรมของเจ้าจะเป็นที่เลื่องลือ ยอดนักรบ ผู้คนจะขับขานสรรเสริญเจ้าตั้งแต่ออร์กริมมาร์ไปจนสุดทะเลใต้ ทุกคนจะได้รู้จักยอดนักรบแห่งฝูงมังกรสำริด {name}" },
        progress = { "18:194568927:470818295", "<Anachronos พยักหน้า>" },
    },
    [98341] = { -- The Great Windborne Cat Spirit
        title = { "30:1654202241:750900719", "วิญญาณแมวล่องลมผู้ยิ่งใหญ่" },
        objective = { "143:1204046938:1578681544", "ตามหา Avatar of Saeyleenan ทางตอนใต้ของ Moonglade แล้วเรียนรู้สิ่งที่จะแบ่งปันเกี่ยวกับธรรมชาติแมวล่องลม", variants = { { "139:912870268:424730885", "ตามหา Avatar of Saeyleenan ทางตอนใต้ของ Moonglade แล้วเรียนรู้สิ่งที่จะแบ่งปันเกี่ยวกับธรรมชาติแมวล่องลม" } } },
        description = { "502:1471553997:587508807", "วิญญาณจากบ้านเกิดของเจ้าเพิ่งปรากฏตัวที่นี่ และขอให้ข้านำทางเจ้าไปพบ วิญญาณแมวล่องลมตนนี้มาเป็นครูชี้นำ เพื่อให้เจ้ารับร่างแมวของวิญญาณบน Zephras ได้\n\nดรูอิดทุกคนย่อมแสวงหาภูมิปัญญานี้ในที่สุด แต่ดูเหมือนบ้านเกิดของเจ้าจะมีร่างที่ต่างจากวิถีดั้งเดิมของเราเล็กน้อย หากต้องการรับร่างแมวนี้ เจ้าต้องผ่านบททดสอบ\n\nเจ้าจะพบวิญญาณได้ทางใต้ของ Moonglade ใต้สะพานคู่" },
        completion = { "391:1874195235:237312964", "สวัสดี ชาว shen'dorei รุ่นเยาว์ ข้ามาเพราะสัมผัสได้ว่าเจ้าพร้อมรับการทดสอบ เพื่อดูว่าเจ้าเข้าใจธรรมชาติแห่งวิญญาณของข้าหรือไม่\n\nข้าจะให้เจ้าผ่านบททดสอบของ Great Cat Spirit แห่ง Azeroth แต่เพราะเจ้ามาจาก Zephras ข้าจึงต้องการเฝ้าดูความก้าวหน้าด้วยตนเอง เพราะร่างที่เจ้าจะรับเป็นของข้า มิใช่ของวิญญาณแมวแห่ง Azeroth\n\nมาเริ่มกันเถอะ" },
    },
    [98404] = { -- The Great Windborne Cat Spirit
        title = { "30:1654202241:750900719", "วิญญาณแมวล่องลมผู้ยิ่งใหญ่" },
        objective = { "156:1134345460:338844620", "เก็บ Relic of the Fang, Relic of the Claw และ Relic of the Silent Shadow จาก Stormrage Barrow Den แล้วนำกลับไปให้ Avatar of Saeyleenan" },
        description = { "492:655005440:1581999678", "หากเจ้าจะเรียกพลังจากวิญญาณของข้า เจ้าต้องผ่านการทดสอบ เพื่อเข้าใจและเคารพร่างนี้ เจ้าต้องพิสูจน์ว่าเป็นหนึ่งเดียวกับไหวพริบ การลอบเร้น และความดุร้ายเมื่อจนมุม\n\nใน Barrow Den ทางตะวันออกใกล้ ๆ มีวัตถุสามชิ้นที่เจ้าต้องเก็บ วิญญาณคลั่งอันทรงพลังเฝ้าอยู่ และจะโจมตีทันทีที่เห็นเจ้า รูปสลักตรงทางเข้าจะมอบพลังลอบเร้นชั่วคราวให้เจ้าผ่านไปได้\n\nจงนำวัตถุกลับมา เพื่อผ่านบททดสอบดรูอิดแห่งดินแดนนี้" },
        progress = { "70:994848386:46857145", "อา กลับมาแล้ว หวังว่านำวัตถุเหล่านั้นมาด้วย?" },
        completion = { "207:688917450:2025984418", "ยอดเยี่ยม เจ้าแสดงให้เห็นว่าเข้าใจธรรมชาติที่แท้จริงของแมว และสามารถเป็นหนึ่งเดียวกับไหวพริบ การลอบเร้น และความดุร้ายที่จำเป็นต่อการรับร่างของข้า\n\nบัดนี้ข้าเห็นว่าเจ้าคู่ควรกับพรของข้าแล้ว นักผจญภัยรุ่นเยาว์", variants = { { "196:1363483895:174664057 C 1:46:46", "ยอดเยี่ยม เจ้าแสดงให้เห็นว่าเข้าใจธรรมชาติที่แท้จริงของแมว และสามารถเป็นหนึ่งเดียวกับไหวพริบ การลอบเร้น และความดุร้ายที่จำเป็นต่อการรับร่างของข้า\n\nบัดนี้ข้าเห็นว่าเจ้าคู่ควรกับพรของข้าแล้ว {class}รุ่นเยาว์" } } },
        required = { [280502] = { "17:1049052398:1423587939", "วัตถุโบราณแห่งเขี้ยว" }, [280679] = { "17:998851833:1417030750", "วัตถุโบราณแห่งกรงเล็บ" }, [280680] = { "26:98044169:1098094958", "วัตถุโบราณแห่งเงาเงียบ" } },
        steps = { { "17:1049052398:1423587939", "วัตถุโบราณแห่งเขี้ยว" }, { "17:998851833:1417030750", "วัตถุโบราณแห่งกรงเล็บ" }, { "26:98044169:1098094958", "วัตถุโบราณแห่งเงาเงียบ" } },
    },
    [3181] = { -- The Horn of the Beast
        title = { "21:842770320:67214089", "เขาของอสูร" },
        objective = { "55:937593620:593598998", "นำ Margol's Gigantic Horn ไปให้ Mountaineer Pebblebitty" },
        description = { "365:960410759:1621844594", "เขาขนาดมหึมามีรอยขีดข่วนและรอยแตกมากมาย วัตถุโลหะประหลาดชิ้นหนึ่งฝังอยู่บนพื้นผิวขรุขระ\n\nเมื่อตรวจดูใกล้ ๆ เจ้าพบว่ามันคือหัวขวานที่หัก บนโลหะสลักข้อความไว้ว่า:\n\nทรัพย์สินของ Mountaineer Pebblebitty\n\nเมื่อเจ้าพยายามดึงหัวขวานออก มันก็แตกเป็นเสี่ยง ๆ\n\nอ้าว!" },
        progress = { "29:139159155:347543276", "ไม่ ข้าจะไม่เปิดประตู" },
        completion = { { "184:1877608444:829400118 N 95:441100750:1456193361", "184:1877608444:829400118 N 97:612353337:53953278" }, "เจ้าถืออะไรอยู่นั่น? ของปลอมแน่นอน!\n\nข้าเคยเผชิญหน้ากับ Margol มาแล้ว และรู้ดีว่าเขาของนางใหญ่กว่าสิ่งที่เจ้าถืออยู่อย่างน้อยแปดเท่า {name} เจ้าคงเอามาจาก Stormsnout ใน Barrens มากกว่า ไม่ เจ้าไม่มีวันหลอก Pebblebitty ได้!" },
        required = { [10005] = { "22:1067145585:1052356037", "เขาขนาดมหึมาของ Margol" } },
        objectiveLabels = {
            item = { ["Margol's Gigantic Horn"] = "เขาขนาดมหึมาของ Margol" },
        },
    },
    [3367] = { -- Suntara Stones
        title = { "14:2000212362:375760346", "ศิลา Suntara" },
        objective = { "34:463851398:2080808848", "ช่วย Dorius กลับไปยัง Ironforge" },
        description = { "36:342010856:435929523 R 107:1307423033:1192700242 N 1:46:46", "<Dorius ครางด้วยความเจ็บปวด>\n\nข้าบาดเจ็บหนัก ชาว{race} รู้สึก... หน้ามืด... โลกหมุน... เลือดออก... ข้างใน\n\nข้าต้องกลับไป Ironforge ช่วยข้าด้วย {name}" },
        progress = { "27:309326872:1805364449", "ข้าคงไม่รอด..." },
        completion = { "51:1211750217:1263604447", "Dorius ทำจดหมายฉบับนี้ตกตอนถูกยิง" },
        objectiveLabels = {
            event = { ["Dorius Escort"] = "คุ้มกัน Dorius" },
        },
    },
    [3368] = { -- Suntara Stones
        title = { "14:2000212362:375760346", "ศิลา Suntara" },
        objective = { "79:110718231:589138389", "นำ Singed Letter ไปให้ Thorius ที่ Hall of Explorers ใน Ironforge" },
        description = { "491:1339829167:1835451714", "พี่น้องของข้า\n\nหากเจ้าได้อ่านจดหมายฉบับนี้ แสดงว่าข้าไม่อยู่แล้ว ข้าไม่รู้ว่ามันมาถึงเจ้าได้อย่างไร แต่จงขอบคุณและให้รางวัลแก่ผู้ที่นำไปส่ง\n\nเรื่องศิลานั้น มันมีอยู่จริง และพวกดาร์กไอรอนครอบครองมันอยู่ ผู้นำของพวกมัน Lathoric the Black ใช้พลังของศิลาจับคณะขุดค้นของข้าเป็นทาส พวกเขาถูกพาไปยัง Cauldron จิตใจถูกบิดเบือน ต้องทำงานทั้งวันทั้งคืนเพื่อสร้างสิ่งที่เรียกว่า Obsidion ให้เสร็จ\n\nช่วยพวกเขาด้วย พี่น้อง นี่คือคำขอสุดท้ายของคนตาย\n\n— Dorius" },
        progress = { "15:1376725055:433508149", "<Thorius สะอื้น>" },
        completion = { "90:2124154577:1376445958", "<Thorius เช็ดน้ำตาบนใบหน้า>\n\nในนามแห่งแสงสว่าง ความปรารถนาของเขาจะเป็นจริง ข้าขอสาบาน" },
        required = { [10443] = { "13:152369582:1804944458", "จดหมายไหม้เกรียม" } },
        steps = { { "13:152369582:1804944458", "จดหมายไหม้เกรียม" } },
    },
    [3372] = { -- Release Them
        title = { "12:653672865:123233191", "ปลดปล่อยพวกเขา" },
        objective = { "178:1679186557:330887684", "หา Mysterious Artifact ที่เหล่า Twilight's Hammer Idolater เฝ้าอยู่ในเขตตะวันตกเฉียงเหนือของ Searing Gorge แล้วนำไปยัง Altar of Suntara ใน Slag Pit", variants = { { "125:381501139:1259522686", "หา Mysterious Artifact ที่เหล่า Twilight's Hammer Idolater เฝ้าอยู่ในเขตตะวันตกเฉียงเหนือของ Searing Gorge" } } },
        description = { "14:375119832:1421487768 R 295:1801988711:2116973180", "ปลดปล่อยพวกเขาเถิด ชาว{race} แม้ร่างกายจะทนไม่ไหวแล้ว พลัง Suntara ก็ยังบังคับให้พวกเขาทำงานต่อจนเสร็จ\n\nแท่นบูชา Suntara คือกุญแจ จงไปทางตะวันตกเฉียงเหนือ บนเนินเหนือถ้ำ... พวก Twilight's Hammer เฝ้าวัตถุโบราณชิ้นหนึ่งอยู่ นำมันมาวางบนแท่นบูชา Suntara\n\n<นักโบราณคดีผู้ใกล้ตายทรุดลง>" },
        progress = { "19:885576055:355718565", "แท่นบูชาว่างเปล่า" },
        completion = { "58:1383414368:1738966438", "เจ้าวางวัตถุโบราณลึกลับลงบนแท่นบูชา Suntara" },
        required = { [10442] = { "19:802910154:1013926035", "วัตถุโบราณลึกลับ" } },
        objectiveLabels = {
            item = { ["Mysterious Artifact"] = "วัตถุโบราณลึกลับ" },
        },
    },
    [3377] = { -- Prayer to Elune
        title = { "15:55239348:1952342376", "คำอธิษฐานถึง Elune" },
        objective = { "26:1164759356:2062324574", "ฟัง Zamael เล่าเรื่องราวของเขา" },
        description = { "41:1585565319:1206213623", "เจ้าจะช่วยข้าหรือไม่ ผู้มีอายุขัย? จงฟังเรื่องราวของข้า" },
        progress = { "28:1084209905:480699330", "ขอให้ข้าเล่าเรื่องให้จบก่อน" },
        completion = { "72:1525566107:400642541", "ข้ายอมรับชะตากรรมในกรงนี้แล้ว แต่ต้องหาคำอธิษฐานนั้นให้พบ" },
        objectiveLabels = {
            event = { ["Zamael Story"] = "เรื่องเล่าของ Zamael" },
        },
    },
    [3378] = { -- Prayer to Elune
        title = { "15:55239348:1952342376", "คำอธิษฐานถึง Elune" },
        objective = { "72:325242435:382774677", "หา Prayer to Elune แล้วนำไปให้ Astarii Starseeker ที่ Darnassus" },
        description = { "479:731438725:2023186387", "เจ้าจะช่วยข้าหรือไม่ ผู้มีอายุขัย? เจ้าจะตามหาคำอธิษฐานถึง Elune ให้ข้าหรือไม่?\n\nอย่างที่ข้าบอก คำอธิษฐานนั้นสลักอยู่บนแผ่นจารึกทอง พวกคนชั่วที่บูชารูปเคารพแถวนี้สักคนต้องพกมันอยู่แน่\n\nหากเจ้าหาคำอธิษฐานของข้าพบ จงนำไปให้ Astarii Starseeker ที่ Darnassus ศรัทธาที่กลับมาลุกโชนของข้าคงมีความหมายเพียงน้อยนิด หลังจากความชั่วร้ายนับไม่ถ้วนที่ข้าก่อกับโลกนี้และผู้ที่อาศัยอยู่ แต่คำอธิษฐานของข้าต้องได้รับการรับฟัง การอภัยบาปเป็นสิ่งสุดท้ายที่ข้าจะกล้าหวัง" },
        progress = { "43:589207271:745678069 N 1:63:63", "อะไรพาเจ้ามายัง Temple of the Moon {name}?" },
        completion = { "32:1008872303:1212331940 N 87:618073875:1450058096", "ค่ำคืนนี้ Elune ยิ้มให้เจ้า {name} เจ้านำวิญญาณที่หลงทางกลับคืนสู่นางแล้ว โปรดรับสิ่งนี้แทนความขอบคุณของเรา" },
        required = { [10458] = { "15:55239348:1952342376", "บทสวดถึง Elune" } },
        steps = { { "15:55239348:1952342376", "บทสวดถึง Elune" } },
    },
    [3441] = { -- Divine Retribution
        title = { "18:1295330948:532815835", "ทัณฑ์จากสวรรค์" },
        objective = { "44:832936802:1240168084", "ฟัง Kalaran Windblade เล่าเรื่องราวของเขา", variants = { { "44:2016928881:1623274949", "ฟัง Velarok Windblade เล่าเรื่องราวของเขา" } } },
        description = { "25:1362440793:766630838", "จงฟังเรื่องราวของข้า นักผจญภัย" },
        progress = { "25:730305608:1259250779 R 1:46:46", "ขอข้าเล่าให้จบก่อน... ชาว{race}" },
