    [3442] = { -- The Flawless Flame
        title = { "18:567330318:136344017", "เปลวไฟอันไร้ที่ติ" },
        objective = { "94:864668672:841092151", "เก็บ Heart of Flame 4 ชิ้นและ Golem Oil 4 ชิ้น แล้วนำกลับไปให้ Kalaran Windblade", variants = { { "94:383547464:377150402", "เก็บ Heart of Flame 4 ชิ้นและ Golem Oil 4 ชิ้น แล้วนำกลับไปให้ Velarok Windblade" } } },
        description = { "34:487615121:930937268 N 431:67320634:797335331", "เจ้าตัดสินใจถูกแล้ว {name}\n\nเราต้องโจมตีจุดที่จะสร้างความเสียหายได้มากที่สุด นั่นคือหอยามทั้งสี่\n\nเมื่อหอทั้งสี่ลุกเป็นไฟ เราจะเริ่มบุกได้ก่อนที่พวกมันจะทันตั้งตัว\n\nเจ้าต้องมีเครื่องมือที่เหมาะสมเพื่อเผาหอ การสร้างเครื่องมือต้องใช้วัสดุบางอย่าง\n\nนำ Heart of Flame สี่ชิ้นและ Golem Oil สี่ชิ้นมาให้ข้า แล้วข้าจะสร้างคบเพลิงแห่งเปลวไฟอันไร้ที่ติ\n\nพวกโกเลมและธาตุในดินแดนนี้ควรเป็นเป้าหมายแรกของเจ้า" },
        progress = { "33:331987840:538219173", "เจ้าเก็บวัสดุมาแล้วหรือยัง?" },
        completion = { "11:534428891:784080240 N 22:1036582645:621127453", "ทำได้ดี {name} เราเกือบพร้อมแล้ว" },
        required = { [10509] = { "14:1532107594:247571192", "หัวใจแห่งเปลวไฟ" }, [10511] = { "9:1847089242:60096219", "น้ำมันของโกเลม" } },
        steps = { { "14:1532107594:247571192", "หัวใจแห่งเปลวไฟ" }, { "9:1847089242:60096219", "น้ำมันของโกเลม" } },
    },
    [3443] = { -- Forging the Shaft
        title = { "17:97132748:932384353", "ตีด้ามคบเพลิง" },
        objective = { "52:1878239608:820968523", "นำ Thorium Plated Dagger 8 เล่มไปให้ Kalaran Windblade", variants = { { "52:1397118400:357026774", "นำ Thorium Plated Dagger 8 เล่มไปให้ Velarok Windblade" } } },
        description = { "309:1777925074:1024972520", "เราต้องมีทั้งด้ามและปลอกเพื่อรองรับเปลวไฟอันไร้ที่ติ ก่อนอื่นเจ้าต้องหาวัสดุที่เหมาะสำหรับทำด้าม\n\nพวก Dark Iron Taskmaster และ Slaver ใน Cauldron ใช้อาวุธที่ทำจากทอเรียมลงอาคม โลหะผสมที่แข็งแกร่งอย่างยิ่ง หากเจ้านำ Thorium Plated Dagger แปดเล่มมา ข้าจะหลอมโลหะผสมแล้วตีเป็นด้ามใหม่ได้" },
        progress = { "7:248557650:2074668278 N 15:659950441:1442572907", "แปดเล่ม {name} ข้าต้องการแปดเล่ม!" },
        completion = { "31:909033100:469098491 N 278:2015324485:1941485032", "เจ้าเป็นคนทำงานที่ยอดเยี่ยม {name} เคยคิดเปลี่ยนอาชีพบ้างไหม? เป็นนักสืบ? คนเก็บของเก่า? อ้อ ข้ารู้แล้ว เป็นอย่างพวกโนมจอมเพี้ยนที่เดินไต่หาดทั่ว Azeroth พร้อมเครื่องตรวจจับโลหะเพื่อหาสมบัติที่สูญหาย ใช่ นั่นคงเหมาะกับเจ้าที่สุด" },
        required = { [10551] = { "21:1989295906:1717973080", "มีดสั้นหุ้มทอเรียม" } },
        steps = { { "21:1989295906:1717973080", "มีดสั้นหุ้มทอเรียม" } },
    },
    [3452] = { -- The Flame's Casing
        title = { "18:49166613:281368952", "ปลอกรองเปลวไฟ" },
        objective = { "58:576246583:96709376", "หา Symbol of Ragnaros แล้วนำกลับไปให้ Kalaran Windblade", variants = { { "58:95125375:1780251256", "หา Symbol of Ragnaros แล้วนำกลับไปให้ Velarok Windblade" } } },
        description = { "403:458123250:702506187", "เราต้องการชิ้นส่วนสุดท้ายอีกชิ้นเพื่อประกอบคบเพลิง\n\nในภูเขาทางตะวันตกเฉียงเหนือ เจ้าจะพบค่ายขนาดใหญ่ของ Twilight's Hammer ว่ากันว่าพวกมันพกสัญลักษณ์และรูปเคารพเพื่อบูชาเทพของตน ของเหล่านั้นอาจมีอาคมมากพอสำหรับสร้างปลอกเวทมนตร์ นำ Symbol of Ragnaros มาหนึ่งชิ้น แล้วข้าจะลองดึงเวทออกมาสร้างปลอก" },
        progress = { "89:2045267507:738968368", "หากไม่มีแหล่งพลังอาร์เคนที่เหมาะสม เราก็สร้างคบเพลิงแห่งการทัณฑ์ให้เสร็จไม่ได้" },
        completion = { "62:1199921262:1839527265", "สัญลักษณ์นี้แผ่เวทอันชั่วร้ายออกมา เหมาะกับงานของเราอย่างยิ่ง" },
        required = { [10552] = { "18:2127802462:594059554", "สัญลักษณ์แห่ง Ragnaros" } },
        steps = { { "18:2127802462:594059554", "สัญลักษณ์แห่ง Ragnaros" } },
    },
