        title = { "20:1832566700:1078170405", "คัมภีร์แห่งการครุ่นคิด" },
        progress = { "112:1019644788:1652815867", "ส่งส่วนประกอบมา ผู้มีอายุขัย\n\nข้าต้องการค่าจัดทำอีกสามสิบเหรียญทองด้วย" },
        completion = { "48:1272174826:1914160427", "เอาของกระจุกกระจิกของเจ้าไป เจ้าโง่ ปล่อยให้ข้าศึกษาต่อ!" },
