    [4481] = { -- Libram of Constitution
        title = { "22:2096041055:1422358180", "คัมภีร์แห่งพลังกาย" },
        progress = { "244:2018057130:2091954281", "ทุกสิ่งในโลกล้วนมีราคา สิ่งที่เจ้าแสวงหานี้มีราคาสามสิบเหรียญทอง\n\nแน่นอนว่าข้าจะเก็บส่วนประกอบที่เจ้ารวบรวมมาส่วนใหญ่ไว้ แต่ไม่ต้องห่วง เจ้าจะได้ของกระจุกกระจิกของเจ้า" },
        completion = { "122:387014696:1180364626", "ช่างเสื่อมเสียต่อความทรงจำของเขา... ผู้มีอายุขัยอย่างเจ้ากลับเป็นคนทำงานทั้งชีวิตของเขาให้เสร็จ\n\nเอาของที่ผสมขึ้นนี้ไปแล้วไสหัวเสีย!" },
        description = { "244:2018057130:2091954281", "ทุกสิ่งในโลกล้วนมีราคา สิ่งที่เจ้าแสวงหานี้มีราคาสามสิบเหรียญทอง\n\nแน่นอนว่าข้าจะเก็บส่วนประกอบที่เจ้ารวบรวมมาส่วนใหญ่ไว้ แต่ไม่ต้องห่วง เจ้าจะได้ของกระจุกกระจิกของเจ้า" },
        required = { [8411] = { "19:852216143:1443462176", "ค็อกเทลน้ำคั้นจากปอด" }, [11733] = { "22:2096041055:1422358180", "คัมภีร์แห่งพลังกาย" }, [11754] = { "13:514843967:997517316", "เพชรดำ" }, [11952] = { "21:882197475:2110055167", "ลมหายใจของ Night Dragon" } },
