            item = { ["Lung Juice Cocktail"] = "ค็อกเทลน้ำคั้นจากปอด", ["Libram of Constitution"] = "คัมภีร์แห่งพลังกาย", ["Black Diamond"] = "เพชรดำ", ["Night Dragon's Breath"] = "ลมหายใจของ Night Dragon" },
        },
    },
    [4482] = { -- Libram of Tenacity
        title = { "18:1448400884:1891040092", "คัมภีร์แห่งความทรหด" },
        progress = { "13:808536804:1125383443 R 42:327621646:1154764748", "สามสิบเหรียญทอง ชาว{race} สามสิบเหรียญทองกับส่วนประกอบที่ต้องใช้" },
        completion = { "104:1102213132:1221136760 R 254:1636140939:445689501", "Kariel ใช้เวลายาวนานหลายช่วงชีวิตของพวกเจ้าเพื่อทำคัมภีร์ที่เจ้าถืออยู่นี้ให้เสร็จ ชาว{race} ทั้งหมดเพื่ออะไร? เพื่อให้ศิษย์ของเขามายืนอยู่ใน Burning Steppes แล้วบิดเบือนงานวิจัยของเขาเพื่อสนองความกระหายอาร์เคนที่ไม่สิ้นสุด... ขอให้การเสพติดอันน่ารังเกียจนี้ถูกสาป\n\nข้ารังเกียจความไร้เมตตาและความโลภที่ไม่รู้จักพอของเจ้า ไปให้พ้น!" },
        description = { "13:808536804:1125383443 R 42:327621646:1154764748", "สามสิบเหรียญทอง ชาว{race} สามสิบเหรียญทองกับส่วนประกอบที่ต้องใช้" },
        required = { [11564] = { "12:1147682460:1509556148", "ผลึกพิทักษ์" }, [11734] = { "18:1448400884:1891040092", "คัมภีร์แห่งความทรหด" }, [11753] = { "12:1589558297:735751269", "ดวงตาของ Kajal" }, [11754] = { "13:514843967:997517316", "เพชรดำ" } },
        objectiveLabels = {
            item = { ["Crystal Ward"] = "ผลึกพิทักษ์", ["Libram of Tenacity"] = "คัมภีร์แห่งความทรหด", ["Eye of Kajal"] = "ดวงตาของ Kajal", ["Black Diamond"] = "เพชรดำ" },
        },
    },
