        completion = { "120:854959126:1195252178", "หัวข้าปวดตุบ... พลังจากห้วงอันไพศาลที่ประกอบเป็นจักรวาลของเรา... อ๊าก!\n\nเอาสิ่งที่เจ้าต้องการแล้วไปเสีย!", variants = { { "146:173445951:1643580425", "หัวข้าปวดตุบ... พลังจากห้วงอันไพศาลที่ประกอบเป็นจักรวาลของเรา... อ๊าก!\n\n<Mathredis แสดงสีหน้าเจ็บปวด>\n\nเอาสิ่งที่เจ้าต้องการแล้วไปเสีย!" } } },
        description = { "22:247548530:1113281944 R 57:2069788069:1948919728", "อย่าเสียเวลาข้า ชาว{race} ส่งสิ่งที่ข้าต้องการมา สามสิบเหรียญทองและส่วนประกอบ" },
