    [4726] = { -- Broodling Essence
        title = { "17:715871731:827310223", "แก่นพลังลูกมังกร" },
        objective = { "120:1971476434:2010282656", "นำ Broodling Essence 8 ชิ้นและ Draco-Incarcinatrix 900 ไปให้ Tinkee Steamboil ที่ Flame Crest ใน Burning Steppes" },
        description = { "494:1092092290:48310557", "ข้าศึกษาดรากอนคินแห่ง Burning Steppes มาหลายสัปดาห์ และคิดว่าในที่สุดก็ค้นพบครั้งสำคัญแล้ว! ข้าสร้างเครื่องมือขึ้นมา เรียกว่า Draco Incarcinatrix 900 มันจับแก่นพลังของลูกมังกรได้!\n\nหรืออย่างน้อยข้าก็คิดว่าทำได้\n\nนี่ รับเครื่องไปยิงใส่ลูกมังกรใน Burning Steppes ขณะที่มันยังได้รับผลจากเครื่อง จงปราบมัน แล้วแก่นพลังน่าจะถูกปล่อยออกมา\n\nถ้าเป็นเช่นนั้นก็เยี่ยมเลย! นำตัวอย่างกลับมาให้ข้าศึกษาด้วย!" },
        progress = { "35:72927845:853330127 N 107:1895551180:119792303", "เจ้าได้แก่นพลังลูกมังกรหรือยัง {name}? ข้าแทบรอศึกษามันไม่ไหว\n\nนอกจากนั้น... ผู้อุปถัมภ์ของข้าก็ไม่ใช่คนที่เจ้าควรทำให้ผิดหวัง" },
        completion = { "43:20455796:172257019 N 343:1719591869:877174082", "ได้ผล! เจ้าได้แก่นพลังมาแล้ว! ทำได้ดี {name}! ทำได้ดี!\n\nแก่นพลังนี้มีค่ามหาศาลต่องานวิจัยของข้า ข้าหวังว่าสักวันจะเรียนรู้วิธีจับลูกมังกรเป็น ๆ หรืออาจเก็บไข่ของมัน หากหาวิธีได้ นักวิชาการเรื่องมังกรทั่วโลกคงอิจฉาข้า!\n\nนายจ้างของข้าก็คงพอใจด้วย และอย่างที่บอก เขาเป็นคนที่เจ้าควรทำให้พอใจไว้..." },
        required = { [12283] = { "17:715871731:827310223", "แก่นพลังลูกมังกร" }, [12284] = { "23:1759182078:1326109527", "เครื่อง Draco-Incarcinatrix 900" } },
        steps = { { "17:715871731:827310223", "แก่นพลังลูกมังกร" }, { "23:1759182078:1326109527", "เครื่อง Draco-Incarcinatrix 900" } },
    },
    [4808] = { -- Felnok Steelspring
        title = { "18:1614081163:954927768", "Felnok Steelspring" },
        objective = { "43:172196347:1360843013", "ส่ง Tinkee's Letter ให้ Felnok Steelspring" },
        description = { "414:1982394220:1642390621", "ข้ามีเรื่องอยากขอให้เจ้าช่วยอีกอย่าง\n\nผลศึกษาเบื้องต้นของแก่นพลังที่เจ้าเก็บมาแสดงว่าเราอาจแช่แข็งไข่ลูกมังกรเพื่อเก็บรักษาไว้ได้! ข้าอยากทดสอบทฤษฎีนี้ แต่ก่อนอื่นต้องมีชิ้นส่วนวิศวกรรมที่ทำขึ้นโดยเฉพาะ Felnok Steelspring เพื่อนร่วมงานของข้าสร้างมันได้\n\nนี่ นำจดหมายนี้ไปให้ Felnok มันบอกสิ่งที่ข้าต้องการ เจ้าจะพบเขาในเมือง Everlook ที่ Winterspring" },
        progress = { "51:1116243488:591004926", "ที่นี่หนาวมาก! หวังว่าเจ้าจะเอาผ้าห่มมาให้ข้านะ!" },
        completion = { "314:1795555477:2029956783", "นี่ไม่ใช่ผ้าห่ม! แต่เรามีอะไรอยู่นี่? จดหมายจาก Tinkee หรือ? อยากรู้จังว่านางจะว่าอย่างไร...\n\nอา นางกำลังศึกษาอยู่ใน Burning Steppes สมเหตุสมผล ที่นั่นเป็นแหล่งดรากอนคินชั้นดี โอ้ ดูสิ! จดหมายบอกว่านางต้องการชิ้นส่วนสำหรับเครื่องที่จะสร้าง ข้าว่าคงถึงตาข้าช่วยแล้วสินะ?" },
        required = { [12438] = { "15:1553228584:1000666398", "จดหมายของ Tinkee" } },
        steps = { { "15:1553228584:1000666398", "จดหมายของ Tinkee" } },
    },
    [5522] = { -- Leonid Barthalomew
        title = { "18:946370267:1588234792", "Leonid Barthalomew" },
        objective = { "71:741246953:1887987694", "นำ Frozen Eggs ไปให้ Leonid Barthalomew ที่ Eastern Plaguelands" },
        description = { "498:203040130:1371361319", "ข้าได้รับข้อความจากนายท่าน Vectus เอาเถอะ ที่จริงไม่ได้มาจาก Vectus หรอก... แต่มาจากคนชื่อ Leonid Barthalomew ข้าไม่รู้จัก Leonid แต่เขารู้จักนายท่าน และไม่มีใครรู้จักนายท่านได้หากท่านไม่อนุญาต\n\nLeonid บอกว่า Vectus ต้องการไข่มังกร เขาอยากให้เจ้านำไปส่งที่ Light's Hope Chapel ใน Eastern Plaguelands\n\nเจ็บใจนัก! ทำไมต้องเป็นเจ้า? Vectus ไม่ไว้ใจข้าหรือ? โอ้ ช่างเถอะ... เอาไข่ไป แล้วบอก Leonid ว่าข้าทำตามคำสั่งของนายท่านแล้ว" },
        progress = { "85:1354679502:1542850402", "เจ้าคือคนที่ไปก่อเรื่องใน Blackrock Spire ใช่ไหม? มีสิ่งที่ข้าขอหรือเปล่า?" },
        completion = { "456:2119652761:1229553587", "อา ดีมาก เจ้าไม่รู้ว่าตนเหนื่อยยากให้กับอำนาจชั่วร้ายใด แต่ตอนนี้เจ้าจะรู้ความจริง และอย่ากลัว ข้าไม่ใช่ข้ารับใช้ของนายผู้นั้น ข้าคือ Leonid Barthalomew ผู้ที่พี่น้องใน Argent Dawn เรียกว่า “ผู้เป็นที่เคารพ”\n\nข้าหลอก Tinkee ให้ส่งเจ้ากับไข่มังกรมาหาข้า ดีแล้วที่แผนสำเร็จ เพราะหากไข่เหล่านี้ไปถึงปลายทางที่เดิมตั้งใจไว้ อำนาจอันยิ่งใหญ่จะตกอยู่ในมือศัตรู" },
    },
    [7701] = { -- WANTED: Overseer Maltorius
        title = { "26:1852026857:731126876", "ประกาศจับ: Overseer Maltorius" },
        objective = { "267:25333301:1362727545", "ลึกเข้าไปใน Slag Pit แห่ง Cauldron ที่ Searing Gorge เจ้าจะพบคนแคระดาร์กไอรอนผู้ทรยศชื่อ Overseer Maltorius\n\nสังหาร Overseer Maltorius แล้วตัดหัว นำหัวไปให้ Lookout Captain Lolo Longstriker ที่ Searing Gorge เพื่อรับรางวัล" },
        description = { "302:2678157:875157254", "ตามคำสั่งของท่าน Overseer Oilfist ให้สังหาร Overseer Maltorius อดีตเจ้าหน้าที่ Thorium Brotherhood ผู้แปรพักตร์ ซึ่งเพิ่งได้รับตำแหน่งผู้บัญชาการคนงานดาร์กไอรอนใน Slag Pit แห่ง Cauldron แล้วนำหัวกลับมาเป็นหลักฐาน\n\nติดต่อ Lookout Captain Lolo Longstriker เพื่อรับรางวัลค่าหัวนี้" },
        progress = { "62:243473092:60020806", "ไม่เห็นหรือว่าข้ายุ่งอยู่? <สะอึก> เจ้าอยากได้อะไร? <สะอึก>" },
        completion = { "141:175413725:1939494034 R 1:46:46", "ข้าไม่คิดเลยว่าจะได้เห็นหน้าอัปลักษณ์นี่อีก!\n\nที่จริงมันดูดีกว่าตอนมีร่างส่วนอื่นติดอยู่เสียอีก\n\nนี่รางวัลของเจ้า <สะอึก> ชาว{race}" },
        required = { [18946] = { "26:831577618:1205010919", "ศีรษะของผู้คุม Maltorius" } },
        steps = { { "26:831577618:1205010919", "ศีรษะของผู้คุม Maltorius" } },
    },
    [7704] = { -- Look at the Size of It!
        title = { "23:1378910355:790119067", "ดูขนาดมันสิ!" },
        objective = { "83:1473925986:1755361347", "นำ Chambermaid Pillaclencher's Pillow ไปให้ Evonice Sootsmoker ที่ Searing Gorge" },
        description = { "271:1879673496:1375953688", "แหม แหม... ช่างน่าแปลกใจ แม่บ้านมีหมอนประดับขนาดมหึมา และตอนนี้มันเป็นของเจ้าแล้ว Evonice Sootsmoker ต้องอยากเอามือเล็ก ๆ ที่มอมแมมของนางมาจับของชิ้นนี้แน่ นำไปให้ดูสิว่านางจะมีของดีอะไรตอบแทนความเหนื่อยยากของเจ้าหรือไม่" },
    },
    [7722] = { -- What the Flux?
        title = { "14:1628686837:1376887626", "ฟลักซ์อะไรกัน?" },
        objective = { "196:323038168:133284303", "หา Secret Plans: Fiery Flux ที่ Overseer Maltorius ขโมยไป ซึ่งอยู่ใน Slag Pit แห่ง Cauldron แล้วนำกลับไปให้ Master Smith Burninate ที่ Searing Gorge" },
        description = { "281:1772187640:833582280 N 70:32766129:1567418943", "ตอน Maltorius ไอ้สารเลวนั่นทิ้งเผ่าเราไป มันเอาของที่มีค่ากว่าผลึกอาร์เคนไร้ตำหนิไปด้วย นั่นคือสูตร Fiery Flux ของเรา! ข้าพนันได้เลยว่าสูตรนี้เป็นส่วนหนึ่งของข้อตกลงที่ทำให้มันได้ตำแหน่งใหม่ในหมู่ดาร์กไอรอน\n\nข้าอยากให้เจ้าเอาแผนลับของเราคืนมา {name} ข้ามั่นใจว่ามันอยู่ใกล้ Maltorius ลึกเข้าไปใน Slag Pit" },
        progress = { "23:583037338:2114132563", "เจ้าพบแผนแล้วหรือยัง?" },
        completion = { "36:1040523243:1142119233 N 66:884107372:1126078374", "หวังว่าเจ้าจะเตะฟันมันร่วงด้วย {name} Ragnaros ย่อมรู้ว่ามันสมควรโดน\n\nตอนนี้เราลงมือทำธุรกิจกันได้แล้ว" },
        required = { [18922] = { "24:566211104:1451731627", "แบบแปลนลับของสารประสานโลหะเพลิง" } },
        steps = { { "24:566211104:1451731627", "แบบแปลนลับของสารประสานโลหะเพลิง" } },
    },
    [7723] = { -- Curse These Fat Fingers
        title = { "23:573731987:389542144", "นิ้วอ้วนบัดซบพวกนี้" },
        objective = { "203:1893716569:472183664", "Hansel Heavyhands ต้องการให้เจ้าสังหาร Heavy War Golem 20 ตน\n\nพวกมันเดินอยู่รอบ Cauldron ใน Searing Gorge เมื่อสังหารครบแล้วให้กลับไปหา Hansel ที่ Searing Gorge" },
        description = { "423:1183065570:823728164", "น่าเสียดายที่ข้าทุบตีใครหนัก ๆ เหมือนแต่ก่อนไม่ได้ เพราะปัญหานิ้วอ้วนพวกนี้ อากาศที่นี่รวมกับความกดอากาศต่ำทำให้นิ้วข้าบวม มันเหมือนไส้กรอกเลือด Thelsamar ยักษ์เลย...\n\nเจ้าจึงต้องช่วยจัดการธุระตามคำสั่งของข้า\n\nงานแรกในรายการคือทุบ Heavy War Golem ใน Gorge ให้ยับ ลงมือได้" },
        progress = { "17:2056958953:1869161429", "เจ้าทุบพวกมันแล้วหรือยัง?" },
        completion = { { "67:696709406:1322494496", "68:777399175:306084142" }, "เจ้าเป็นเด็กดีจริง ๆ ข้ามีของขวัญเล็กน้อยตอบแทนที่ช่วยเหนื่อย" },
        objectiveLabels = {
            monster = { ["Heavy War Golem slain"] = "ปราบ โกเลมสงครามหนัก" },
        },
    },
    [7724] = { -- Fiery Menace!
        title = { "13:1851949708:888432333", "ภัยเปลวไฟ!" },
        objective = { "267:1133851300:507431001", "Hansel Heavyhands ต้องการให้เจ้าสังหาร Greater Lava Spider 20 ตัวใน Searing Gorge พบพวกมันได้บนที่ราบสูงและบริเวณบ่อลาวาของ Searing Gorge\n\nเมื่อสังหารครบแล้วให้กลับไปหา Hansel Heavyhands ที่ Searing Gorge", amount = { "36:2041187353:852947924 W1 229:2139842466:47148191", "Hansel Heavyhands ต้องการให้เจ้าสังหาร Searing Lava Spider {world1} ตัวใน Searing Gorge เจ้าจะพบพวกมันบนที่ราบสูงและบริเวณบ่อลาวาของ Searing Gorge\n\nเมื่อสังหารครบแล้ว ให้กลับไปหา Hansel Heavyhands ที่ Searing Gorge" } },
        description = { "431:196753189:272725119", "เชื่อไหม ทุกครั้งที่ Hansel คนนี้อยากพักสักครู่แล้วทบทวนชีวิต พวกผู้ใหญ่ก็ส่งงานใหม่มาให้อีก\n\nข้าก็ต้องใช้ความคิดนะ ให้ตายเถอะ! เข้าใจที่ข้าพูดไหม? ให้ตายสิ\n\nเอาละ พวก Greater Lava Spider กำลังก่อเรื่องอะไรสักอย่าง Oilfist บอกว่ามันยิงไฟออกมาจาก... เอ่อ เอาเถอะ อย่างไรเรื่องแบบนี้ก็ทำให้เด็ก ๆ ตกใจ\n\nข้าว่าเราคงต้องฆ่ามัน พูดให้ถูกคือเจ้าต้องไปฆ่า", variants = { { "431:787788643:1370070326", "เชื่อไหม ทุกครั้งที่ Hansel คนนี้อยากพักสักครู่แล้วทบทวนชีวิต พวกผู้ใหญ่ก็ส่งงานใหม่มาให้อีก\n\nข้าก็ต้องใช้ความคิดนะ ให้ตายเถอะ! เข้าใจที่ข้าพูดไหม? ให้ตายสิ\n\nเอาละ พวก Searing Lava Spider กำลังก่อเรื่องอะไรสักอย่าง Oilfist บอกว่ามันยิงไฟออกมาจาก... เอ่อ เอาเถอะ อย่างไรเรื่องแบบนี้ก็ทำให้เด็ก ๆ ตกใจ\n\nข้าว่าเราคงต้องฆ่ามัน พูดให้ถูกคือเจ้าต้องไปฆ่า" } } },
        progress = { "43:2138225116:2100760775", "เขาพูดถูกไหม? มันออกมาจากก้นของพวกมันจริงหรือ?" },
        completion = { "71:92779292:154828397", "<Hansel จาม>\n\nข้าว่ากำลังเป็นหวัด อากาศเย็นจัดบัดซบ!" },
        objectiveLabels = {
            monster = { ["Searing Lava Spider slain"] = "ปราบ แมงมุมลาวาแผดเผา" },
        },
    },
    [7727] = { -- Incendosaurs? Whateverosaur is More Like It
        title = { "43:2112684482:1099054643", "Incendosaur หรือ? จะไดโนเสาร์อะไรก็ช่างเถอะ" },
        objective = { "280:1381767107:1642004611", "Hansel Heavyhands ต้องการให้เจ้าสังหาร Incendosaur 20 ตัว\n\nพบพวกมันได้ตามบ่อลาวาภายใน Slag Pit ซึ่งอยู่ใน Cauldron แห่ง Searing Gorge\n\nเมื่อสังหารครบแล้วให้กลับไปหา Hansel Heavyhands ที่ Searing Gorge" },
        description = { { "464:1254537396:97333901", "465:776912092:1804534195" }, "ปุ่มบวมที่เท้าน่ะ เจ้าหนู ปุ่มบวมของข้ายังมีปุ่มบวมอีกที ข้าจะไปฆ่าอะไรได้อย่างไร ในเมื่อเท้าอยู่ในสภาพนี้? เจ้าจึงต้องช่วย\n\nScrange กับ Burninate สั่งให้ข้าฆ่าสัตว์พวกนี้ เพื่อส่งคณะสำรวจลงไปยังบ่อลาวาใน Slag Pit ว่ากันว่ามี Incendosaur หรืออะไรไร้สาระทำนองนั้นก่อปัญหาสารพัดอยู่ข้างล่าง ไปได้แล้ว และอย่ากลับมาจนกว่าประชากร Incendosaur จะสูญพันธุ์" },
        progress = { "234:560919251:1663806139", "<Hansel ง่วนกับการนวดปุ่มบวมที่เท้า>\n\nอย่ายืนเฉย หาน้ำมันกับใยบวบมา แล้วช่วยขัดปุ่มพวกนี้ที\n\nเจ้าไม่มีใยบวบหรือ? อ้อ! บางทีถึงเวลาส่งเจ้าออกไปหาใยบวบแล้วสินะ?\n\nเฮ้ เจ้าจะไปไหน?" },
        completion = { "61:444110963:1590996504", "โอ้ เท้าข้าปวดเหลือเกิน\n\nข้าคิดว่าในเมื่อเจ้าไม่มีใยบวบ..." },
        objectiveLabels = {
            monster = { ["Incendosaur slain"] = "ปราบ อินเซนโดซอร์" },
        },
    },
    [7728] = { -- STOLEN: Smithing Tuyere and Lookout's Spyglass
        title = { "46:1998331457:990249387", "ของถูกขโมย: Smithing Tuyere และ Lookout's Spyglass" },
        objective = { "355:1194576710:1314155683", "หา Smithing Tuyere และ Lookout's Spyglass แล้วนำกลับไปให้ Taskmaster Scrange ที่ Searing Gorge\n\nข้อมูลเดียวที่เจ้ามีคือ พวกคนแคระดาร์กไอรอนขโมยมันไปแน่นอน Smithing Tuyere เป็นเครื่องมือช่างตีเหล็ก ส่วน Lookout's Spyglass เป็นเครื่องมือเฝ้าระวังที่มีค่ามากสำหรับหน่วยสังเกตการณ์" },
        description = { "484:1490887189:170421817", "สิ่งของต่อไปนี้ถูกขโมย:\n\n• Dark Iron Tuyere หนึ่งชิ้น\n\n• Lookout's Spyglass หนึ่งอัน\n\nมีรางวัลสำหรับผู้ที่พบและนำของที่ถูกขโมยกลับมาคืน\n\nThorium Brotherhood มั่นใจว่าคนแคระดาร์กไอรอนผู้ไร้ยางอายและขี้อิจฉาที่อาศัยใน Searing Gorge เป็นคนขโมย\n\nกล้องส่องทางไกลนั้นเป็นเครื่องมือชั้นเยี่ยมของหน่วยสังเกตการณ์ ส่วนหัวเป่าลมเตาหลอมเป็นเครื่องมือตีเหล็กที่ทดแทนไม่ได้\n\nหากพบสิ่งของที่หายไป จงนำกลับไปให้ Scrange" },
        progress = { "77:698291860:938705021", "หากเจ้ามารับรางวัล ก็ต้องเอาของที่ถูกขโมยมาให้ข้า" },
        completion = { "36:930187233:1823959956", "ผลงานยอดเยี่ยม! ทีนี้มารับรางวัลของเจ้า" },
        required = { [18959] = { "15:344710287:546494818", "หัวเป่าลมเตาตีเหล็ก" }, [18960] = { "18:1273566976:1835503389", "กล้องส่องทางไกลของยามเฝ้าดู" } },
        steps = { { "15:344710287:546494818", "หัวเป่าลมเตาตีเหล็ก" }, { "18:1273566976:1835503389", "กล้องส่องทางไกลของยามเฝ้าดู" } },
    },
    [7729] = { -- JOB OPPORTUNITY: Culling the Competition
        title = { "40:162117054:178340780", "รับสมัครงาน: กำจัดคู่แข่ง" },
        objective = { "143:985671312:566690761", "สังหาร Dark Iron Taskmaster 15 ตนและ Dark Iron Slaver 15 ตน แล้วกลับไปหา Taskmaster Scrange ที่ Searing Gorge" },
        description = { "381:1392065858:744714514", "Taskmaster Scrange กำลังหาผู้มีฝีมือมาช่วย “กำจัดคู่แข่ง” ใน Searing Gorge\n\nหากสนใจตำแหน่งนี้ จงออกไปใน Searing Gorge แล้วสังหาร Dark Iron Taskmaster และ Dark Iron Slaver ทุกตนที่เห็น\n\nกลับไปหา Taskmaster Scrange เมื่อเสื้อผ้าของเจ้าเปื้อนเลือดมากพอ\n\nเจ้าจะรู้เองว่าเมื่อไรถึงจะพอ ไม่ต้องถาม" },
        progress = { "66:1909965748:1233342827", "เราคงต้องชั่งน้ำหนักเจ้าทั้งตอนสวมเสื้อผ้าและถอดเสื้อผ้าจึงจะแน่ใจได้" },
        completion = { "92:1588533852:757170514 C 1:33:33", "15.9 ปอนด์! นี่อาจเป็นสถิติใหม่น้ำหนักเลือดและเครื่องในบนเสื้อผ้า! ยินดีด้วย {class}!" },
        objectiveLabels = {
            monster = { ["Dark Iron Taskmaster slain"] = "ปราบ ผู้คุมแรงงาน Dark Iron", ["Dark Iron Slaver slain"] = "ปราบ พ่อค้าทาส Dark Iron" },
        },
    },
    [7736] = { -- Restoring Fiery Flux Supplies via Kingsblood
        title = { "44:1049979108:1572730769", "เติมเสบียง Fiery Flux ด้วย Kingsblood" },
        progress = { "61:184577274:1227873886 R 260:1733901145:175918540", "อย่าเสียเวลาอันมีค่าของข้าไปกับการพูดเรื่อยเปื่อยอีกเลย ชาว{race} ถึงเวลามุ่งเติม Fiery Flux ที่ร่อยหรอแล้ว\n\nสิ่งที่ข้าต้องการจากเจ้ามีดังนี้:\n\n• Incendosaur Scale\n\n• Kingsblood\n\n• Coal\n\nข้ารับทั้งหมดที่เจ้าให้ได้!\n\nและหากอยากเข้ากับ Brotherhood ได้ดี เจ้าก็ควรรีบทำ" },
        completion = { "93:1331642702:332437177", "เรามีที่รับ Fiery Flux เพิ่มได้เสมอ เจ้าหนู ส่งมาเรื่อย ๆ... จนกว่าข้าจะบอกให้หยุด" },
        description = { "61:184577274:1227873886 R 260:1733901145:175918540", "อย่าเสียเวลาอันมีค่าของข้าไปกับการพูดเรื่อยเปื่อยอีกเลย ชาว{race} ถึงเวลามุ่งเติม Fiery Flux ที่ร่อยหรอแล้ว\n\nสิ่งที่ข้าต้องการจากเจ้ามีดังนี้:\n\n• Incendosaur Scale\n\n• Kingsblood\n\n• Coal\n\nข้ารับทั้งหมดที่เจ้าให้ได้!\n\nและหากอยากเข้ากับ Brotherhood ได้ดี เจ้าก็ควรรีบทำ" },
        objective = { "82:1400345513:350675125", "นำ Incendosaur Scales 2 ชิ้น, Kingsblood 4 ชิ้น และ Coal หนึ่งชิ้นไปให้ Master Smith Burninate" },
        required = { [18944] = { "17:643963634:2079666318", "เกล็ดอินเซนโดซอร์" }, [3356] = { "10:490285240:1656531642", "หญ้าเลือดราชัน" }, [3857] = { "4:1144654207:152539783", "ถ่านหิน" } },
        objectiveLabels = {
            item = { ["Incendosaur Scale"] = "เกล็ดอินเซนโดซอร์", ["Kingsblood"] = "หญ้าเลือดราชัน", ["Coal"] = "ถ่านหิน" },
        },
    },
    [7737] = { -- Gaining Acceptance
        title = { "18:1460534311:1747995902", "ได้รับการยอมรับ" },
        progress = { "73:1128139669:1088473669 R 284:1600716066:1474769597", "เจ้าค่อย ๆ ไต่ลำดับชั้นของ Brotherhood ขึ้นมาแล้ว ชาว{race} เราเริ่มมองเจ้าในแง่ดี นับเป็นความสำเร็จทีเดียว!\n\nหากสนใจทำงานเพิ่มและได้รับความเคารพจากเรามากขึ้น จงฟังให้ดี\n\nเราทำให้ Fiery Flux บริสุทธิ์ขึ้นได้ด้วยการผสม Dark Iron Residue ธรรมดาลงไป พบกากแร่ชนิดนี้ได้ใน Blackrock Depths", variants = { { "73:1128139669:1088473669 R 329:180558868:1210516444", "เจ้าค่อย ๆ ไต่ลำดับชั้นของ Brotherhood ขึ้นมาแล้ว ชาว{race} เราเริ่มมองเจ้าในแง่ดี นับเป็นความสำเร็จทีเดียว!\n\nหากสนใจทำงานเพิ่มและได้รับความเคารพจากเรามากขึ้น จงฟังให้ดี\n\nเราทำให้ Fiery Flux บริสุทธิ์ขึ้นได้ด้วยการผสม Dark Iron Residue ธรรมดาลงไป พบกากแร่ชนิดนี้ได้ใน Blackrock Depths\n\nนำกากแร่ Dark Iron ที่เจ้าพบทั้งหมดมาให้ข้า!" } } },
        completion = { "28:322019268:856132164", "ส่งกากแร่มาเรื่อย ๆ!" },
        description = { "73:1128139669:1088473669 R 329:180558868:1210516444", "เจ้าค่อย ๆ ไต่ลำดับชั้นของ Brotherhood ขึ้นมาแล้ว ชาว{race} เราเริ่มมองเจ้าในแง่ดี นับเป็นความสำเร็จทีเดียว!\n\nหากสนใจทำงานเพิ่มและได้รับความเคารพจากเรามากขึ้น จงฟังให้ดี\n\nเราทำให้ Fiery Flux บริสุทธิ์ขึ้นได้ด้วยการผสม Dark Iron Residue ธรรมดาลงไป พบกากแร่ชนิดนี้ได้ใน Blackrock Depths\n\nนำ Dark Iron Residue ทั้งหมดที่หาได้มาให้ข้า!" },
        required = { [18945] = { "17:877805356:537293246", "เศษตกค้างจากเหล็กดำ" } },
        objectiveLabels = {
            item = { ["Dark Iron Residue"] = "เศษตกค้างจากเหล็กดำ" },
        },
    },
    [8241] = { -- Restoring Fiery Flux Supplies via Iron
        title = { "38:1744963073:162330513", "เติมเสบียง Fiery Flux ด้วยเหล็ก" },
        progress = { "61:184577274:1227873886 R 259:728585895:1363716311", "อย่าเสียเวลาอันมีค่าของข้าไปกับการพูดเรื่อยเปื่อยอีกเลย ชาว{race} ถึงเวลามุ่งเติม Fiery Flux ที่ร่อยหรอแล้ว\n\nสิ่งที่ข้าต้องการจากเจ้ามีดังนี้:\n\n• Incendosaur Scale\n\n• Iron Bar\n\n• Coal\n\nข้ารับทั้งหมดที่เจ้าให้ได้!\n\nและหากอยากเข้ากับ Brotherhood ได้ดี เจ้าก็ควรรีบทำ" },
