        description = { "61:184577274:1227873886 R 259:728585895:1363716311", "อย่าเสียเวลาอันมีค่าของข้าไปกับการพูดเรื่อยเปื่อยอีกเลย ชาว{race} ถึงเวลามุ่งเติม Fiery Flux ที่ร่อยหรอแล้ว\n\nสิ่งที่ข้าต้องการจากเจ้ามีดังนี้:\n\n• Incendosaur Scale\n\n• Iron Bar\n\n• Coal\n\nข้ารับทั้งหมดที่เจ้าให้ได้!\n\nและหากอยากเข้ากับ Brotherhood ได้ดี เจ้าก็ควรรีบทำ" },
        required = { [18944] = { "17:643963634:2079666318", "เกล็ดอินเซนโดซอร์" }, [3575] = { "8:1010117764:989104521", "แท่งเหล็ก" }, [3857] = { "4:1144654207:152539783", "ถ่านหิน" } },
        objectiveLabels = {
            item = { ["Incendosaur Scale"] = "เกล็ดอินเซนโดซอร์", ["Iron Bar"] = "แท่งเหล็ก", ["Coal"] = "ถ่านหิน" },
        },
    },
    [8242] = { -- Restoring Fiery Flux Supplies via Heavy Leather
