        },
    },
    [4024] = { -- A Taste of Flame
        title = { "16:205208153:1644899036", "ลิ้มรสเปลวไฟ" },
        objective = { "267:1256215525:1801222076", "เดินทางไป Blackrock Depths แล้วสังหาร Bael'Gar\n\nเจ้ารู้เพียงว่ายักษ์ตนนี้อยู่ใน Blackrock Depths อย่าลืมใช้ Altered Black Dragonflight Molt กับซากของ Bael'Gar เพื่อเก็บ Fiery Essence\n\nนำ Encased Fiery Essence กลับไปให้ Cyrus Therepentous" },
        description = { "447:112960044:658261671", "ข้าอยากลิ้มรสเปลวไฟแผดเผาแห่งภูเขาไฟ ปล่อยให้ไฟหลอมเหลวของ Blackrock ไหลผ่านทั่วร่าง แก่นพลังและความร้อนแผดเผานั่นคือสิ่งที่ข้าโหยหา\n\nBael'Gar อยู่ในส่วนลึกของ Blackrock มันเป็นสิ่งมีชีวิตแห่งเปลวไฟบริสุทธิ์ ถือกำเนิดจากไฟของ Ragnaros จงสังหารมัน แล้วนำเปลวไฟภายในส่วนหนึ่งจากซากที่ยังคุกรุ่นมาให้ข้า\n\nใช้คราบที่ลอกกับซากเพื่อดึงเปลวไฟออกมาอย่างปลอดภัย\n\nทำสำเร็จแล้วจะได้รางวัล" },
        progress = { "26:600059664:1249891889", "ยักษ์ล้มลงแล้วหรือยัง?" },
        completion = { "109:2142499974:21400526", "<Cyrus คว้าแก่นเปลวไฟจากมือเจ้า>\n\nใช่เลย!\n\nเอารางวัลของเจ้าแล้วไปเสีย ไปให้พ้นตาข้าทันที!" },
        required = { [11230] = { "21:1301840300:111100833", "แก่นเพลิงที่ผนึกไว้" } },
        steps = { { "21:1301840300:111100833", "แก่นเพลิงที่ผนึกไว้" } },
    },
    [4062] = { -- The Rise of the Machines
        title = { "24:2023811246:837866862", "การผงาดของจักรกล" },
        objective = { "127:1360819881:2069893601", "นำ Elemental Shard Sample ไปให้ Lotwil Veriatus\n\nเจ้าจำว่า Theodora บอกว่า Lotwil อยู่ค่ายทางตะวันออก" },
        description = { "404:1685407968:1025089979", "G.L.A.\n\nคืออักษรย่อบนเศษธาตุ ใต้ลงไปมีเครื่องหมายยศ เครื่องจักรที่ทำลายใน Burning Steppes เป็น “Rank IV” ข้าเดาว่าเป็นยศต่ำ\n\nนำตัวอย่างให้ Lotwil Veriatus ในค่ายตะวันออก เขาเป็นนักปราชญ์มีชื่อด้านศาสตร์ธาตุ อาจช่วยค้นได้" },
        progress = { "25:1918645140:1241363237 R 1:63:63", "มีอะไรนั่น {race}?" },
        completion = { "56:1551553967:1564733549", "<หน้า Lotwil ซีดขาว>\n\nข้า...ข้ารู้จักเครื่องหมาย" },
    },
    [4063] = { -- The Rise of the Machines
        title = { "24:2023811246:837866862", "การผงาดของจักรกล" },
        objective = { "232:966147068:1198857327", "หา Golem Lord Argelmach แล้วสังหาร นำหัวกลับไปให้ Lotwil เจ้าต้องเก็บ Intact Elemental Core 10 ชิ้นจาก Ragereaver Golem และ Warbringer Construct ที่คุ้มกัน Argelmach ด้วย เจ้ารู้เรื่องนี้เพราะมีญาณทิพย์" },
        description = { "485:621296892:469973318", "ต้องไม่ใช่ Argelmach! เขาตายไปเมื่อสิบปีก่อนแล้ว ข้าแน่ใจได้อย่างไรหรือ? เพราะข้าเป็นคนฆ่าเขาเอง\n\nเขาเป็นคนแคระน่ารังเกียจ มุ่งบิดเบือนงานทั้งชีวิตของข้าเพื่อสนองจุดประสงค์ชั่วร้าย ดูเหมือนคนชั่วจะหาทางหนีความยุติธรรมได้เสมอ\n\nหากนี่เป็นฝีมือ Argelmach เขาต้องถูกทำลาย ข้าต้องการตัวอย่างสิ่งสร้างล่าสุดของเขา หากได้ตัวอย่างที่เหมาะสม ข้าอาจหยุดการลุกฮือนี้ได้ สิ่งสร้างเหล่านั้นคุ้มกัน Argelmach อยู่ใน Blackrock Depths" },
        progress = { "32:402918143:87756922", "เป็นเขาหรือ? เขายังมีชีวิตจริงหรือ?" },
        completion = { "234:1562699361:35178069", "นี่มันอะไร?!? หัวนี้ไม่ใช่เนื้อหนัง แต่เป็นสิ่งสร้างดาร์กไอรอนบางอย่าง เงาของ Argelmach เป็นจักรกลอีกตัว! ข้าสงสัยว่าการทำลาย Argelmach ครั้งนี้จะให้ผลไม่นาน เพราะอีกตัวคงผุดขึ้นมาแทนมันในไม่ช้า" },
        required = { [11268] = { "17:23031029:1482707139", "ศีรษะของ Argelmach" }, [11269] = { "21:1414221028:1319882742", "แกนธาตุสมบูรณ์" } },
        objectiveLabels = {
            item = { ["Head of Argelmach"] = "ศีรษะของ Argelmach", ["Intact Elemental Core"] = "แกนธาตุสมบูรณ์" },
        },
    },
    [3801] = { -- Dark Iron Legacy
        title = { "16:1579509030:543032027", "มรดกดาร์กไอรอน" },
        objective = { "92:228991678:1322369477", "คุยกับ Franclorn Forgewright หากสนใจรับกุญแจเข้าสู่ตัวเมือง" },
        description = { "11:927657569:725753248 N 463:272037537:1818722699", "สวัสดี {name} ข้าคือ Franclorn Forgewright ใช่ Franclorn Forgewright ผู้คิดค้นสถาปัตยกรรมแบบ Stonewrought นั่นเอง ระหว่างผจญภัยในโลกที่บอบช้ำจากสงครามนี้ เจ้าคงเคยเดินผ่านหรือยืนบนผลงานของข้ามาบ้างแน่\n\nเจ้าคงสงสัยว่าทำไมข้าจึงอยู่ที่นี่ และต้องการอะไรจากเจ้า ทั้งสองคำถามสมเหตุสมผล\n\nแน่นอนว่าข้าต้องการความช่วยเหลือ เพื่อแลกเปลี่ยน ข้าจะมอบกุญแจเข้าสู่ส่วนลึกของเมืองต้องสาปของข้าให้เจ้า" },
        completion = { "133:1809297155:474190284", "ไม่ว่าความโลภหรือความเสียสละจะพาเจ้ามาที่นี่ สิ่งที่เจ้ากำลังจะทำก็เป็นประโยชน์ต่อพวกเราทุกคน" },
    },
    [3802] = { -- Dark Iron Legacy
        title = { "16:1579509030:543032027", "มรดกดาร์กไอรอน" },
        objective = { "154:973656610:1846178709", "สังหาร Fineous Darkvire แล้วนำค้อนใหญ่ Ironfel คืนมา นำไปยัง Shrine of Thaurissan แล้ววางบนรูปปั้น Franclorn Forgewright" },
        description = { "499:1428181439:286797507", "เจ้าจะพบ Fineous Darkvire ใน Hall of Crafting เลย Ring of Law ไป สังหารเจ้าสุนัขชั่วนั่นแล้วนำ Ironfel คืนมา\n\nนำ Ironfel ไปยัง Shrine of Thaurissan แล้ววางค้อนในที่ที่มันสมควรอยู่ นั่นคือในมือรูปปั้นที่สร้างเพื่อเป็นเกียรติแก่ข้า\n\nเมื่อทำแล้ว ช่องที่ข้าเก็บกุญแจหลักไว้จะเปิดออก ที่สำคัญกว่านั้น Ironfel จะอยู่ในกำมือข้าตลอดไป หากพวกมันพยายามนำค้อนออก ทั้งรูปปั้นและค้อนจะแตกสลาย สูญหายไปตลอดกาล" },
        progress = { "37:545103528:1074919349", "รูปปั้นตั้งตระหง่านอย่างน่าเกรงขามเหนือเจ้า" },
        completion = { "159:1019381640:553891188", "ค้อนเลื่อนเข้าที่อย่างมั่นคงในมือของอนุสาวรีย์ดาร์กไอรอนขนาดมหึมา ช่องเล็ก ๆ ที่ฐานรูปปั้นเปิดออก ข้างในเจ้าพบ..." },
        required = { [10999] = { "7:1604552647:861192531", "ค้อน Ironfel" } },
        steps = { { "7:1604552647:861192531", "ค้อน Ironfel" } },
    },
    [3906] = { -- Disharmony of Flame
        title = { "19:1608897473:834127509", "เปลวไฟที่เสียสมดุล" },
        objective = { "133:612152615:861161906", "เดินทางไปเหมืองหินใน Blackrock Mountain แล้วสังหาร Overmaster Pyron เมื่อเสร็จให้กลับไปหา Thunderheart" },
        description = { "409:514495456:235746164", "เหล่าผู้อาวุโสสัมผัสได้ถึงความปั่นป่วนในหมู่ธาตุ คนแคระดาร์กไอรอนเรียกวิญญาณชั่วร้ายมาสู่โลกของเรา คุกคามดินแดนด้วยความแห้งแล้งชั่วกาล เราต้องสืบสวนเปลวไฟที่เสียสมดุลนี้\n\nจงเดินทางไป Blackrock Mountain ผ่าน Chasm of Flame เข้าสู่เหมืองหิน ที่นั่นเจ้าจะพบจ้าวแห่งไฟ Overmaster Pyron\n\nยุติความปั่นป่วนแล้วกลับมาหาข้า" },
        progress = { "36:538808488:1778930020 N 1:46:46", "เหล่าธาตุยังปั่นป่วนอยู่ {name}" },
        completion = { "162:1267732296:1879299581", "เป็นไปไม่ได้... ต้องไม่ใช่เช่นนี้ การทำลาย Pyron เพียงเปิดม่านให้เห็นสิ่งที่ซ่อนอยู่ ในส่วนลึกของ Blackrock มีต้นตอความเสื่อมทรามที่ร้ายกาจกว่านั้นมาก" },
        objectiveLabels = {
            monster = { ["Overmaster Pyron slain"] = "ปราบ จอมบัญชาการ Pyron" },
        },
    },
    [3907] = { -- Disharmony of Fire
        title = { "18:256745540:71890140", "อัคคีที่เสียสมดุล" },
        objective = { "129:1170487138:423046931", "เข้า Blackrock Depths แล้วตามหา Lord Incendius สังหารเขาและนำแหล่งข้อมูลใดก็ตามที่พบกลับไปให้ Thunderheart" },
        description = { "56:5496210:476303463 N 313:1663479674:1786518793", "ข้าสัมผัสความชั่วร้ายในอากาศรอบตัวเจ้าได้ {name} ยังมีอีกตนซ่อนอยู่ในส่วนลึกของ Blackrock เป็นผู้ควบคุมความชั่วนี้\n\nลมและดินร่ำร้องนามของเขา Lord Incendius... แต่มีใครบางคน... หรือบางสิ่ง... บัญชาเขาอยู่อีกที เขาเป็นเพียงทูต\n\nตามหาเขาและสืบว่านายของเขาซ่อนอยู่ที่ใด เมื่อได้ข้อมูลแล้วจงกลับมาหาข้า" },
        progress = { "55:1259597739:1363680872 N 1:33:33", "อีกไม่นานเปลวไฟจะกลืนดินแดนนี้ รีบเข้า {name}!" },
        completion = { "374:107785981:798209897 N 91:154921114:284582963", "<Thunderheart กำ Tablet of Kurniya แน่น>\n\nRagnaros... อยู่ที่นี่...\n\nเหล่าผู้อาวุโสคิดถูกที่หวาดกลัวความเสื่อมทรามจาก Blackrock Mountain แม่ทัพของเหล่า Old God! อยู่ในโลกของเรา! เราต้องทบทวนจุดยืนที่ Kargath จะอยู่ต่อสู้ หรือหนีเพราะกลัวมหาวิบัติครั้งใหม่\n\nจงระวังหากจะสำรวจ Blackrock Mountain ต่อ {name} ในส่วนลึกอันร้อนระอุนั้นมีความชั่วร้ายที่ยิ่งกว่าสิ่งใดในโลกนี้อาศัยอยู่" },
        required = { [11126] = { "17:665515683:596025319", "แผ่นจารึก Kurniya" } },
        objectiveLabels = {
            item = { ["Tablet of Kurniya"] = "แผ่นจารึก Kurniya" },
            monster = { ["Lord Incendius slain"] = "ปราบ ลอร์ด Incendius" },
        },
    },
    [3981] = { -- Commander Gor'shak
        title = { "18:788209256:2035674354", "ผู้บัญชาการ Gor'shak" },
        objective = { "189:327723612:1675499962", "หา Commander Gor'shak ใน Blackrock Depths\n\nเจ้าจำได้ว่าภาพออร์คที่วาดอย่างหยาบ ๆ มีซี่กรงทับอยู่ บางทีควรค้นหาคุกสักแห่ง" },
        description = { "479:1728733743:56510272", "Gargal ผู้น่าสงสาร... ไม่ทันเห็นด้วยซ้ำ ผัวะ! ลูกศรปักกลางกระหม่อมพอดี ก่อนหน้านี้ก็ไม่ได้ฉลาดอะไร แต่ตอนนี้...\n\n<Galamav ทำหน้าบิดเบี้ยว>\n\nเมื่อดึงลูกศรออก เราพบกระดาษม้วนติดอยู่กับก้าน บนนั้นมีภาพออร์คหลังซี่กรงที่วาดอย่างหยาบ ๆ พร้อมลายเซ็น Commander Gor'shak\n\nหากเขายังมีชีวิตใน Depths เจ้าต้องหาเขาให้พบ\n\nเจ้าว่ามันเป็นกับดักหรือ? ก็แน่นอนสิ เจ้ากีบทึ่ม! เพราะอย่างนั้นถึงต้องเป็นเจ้าไป!" },
        completion = { "44:1571008400:966773718 R 63:825588518:1499190557", "เรามีเวลาไม่มาก ฟังให้ดี ชาว{race} สิ่งที่ข้าจะบอกเป็นความลับ ให้เจ้ารู้เพียงคนเดียว" },
    },
    [3982] = { -- What Is Going On?
        title = { "17:1594666138:1228549921", "เกิดอะไรขึ้นกันแน่?" },
        objective = { "16:416091055:2038934917", "ปกป้อง Gor'shak" },
        description = { "440:1100078552:111601844", "ข้าถูกส่งมาที่นี่ภายใต้การสนับสนุนของ Thrall เจ้าคิดจริง ๆ หรือว่าพวกโง่นั่นจับข้าได้? ข้ายอมให้จับเพื่อรวบรวมข่าวกรอง\n\n<Gor'shak กระซิบ>\n\nองค์หญิงแห่ง Ironforge ถูกจักรพรรดิ Thaurissan ลักพาตัว องค์หญิง Bronzebeard อยู่ในเมืองนี้เอง! พนันว่า Magni เฒ่าคงแทบหัวใจหยุดเต้นเมื่อรู้ข่าว\n\n<Gor'shak หัวเราะ>\n\nชู่ว์! ได้ยินไหม? ยามกำลังมา! ป้องกันตัว!" },
        progress = { "22:1129981643:1381039552", "ป้องกันตัวสิ เจ้าโง่!" },
        completion = { "88:1515347317:1923686280", "เกือบไปแล้ว พวกมันรู้แล้วว่าเจ้าอยู่ที่นี่... ต้องมีมาอีกแน่" },
    },
    [4001] = { -- What Is Going On?
        title = { "17:1594666138:1228549921", "เกิดอะไรขึ้นกันแน่?" },
        objective = { "220:688012663:222932786", "คุยกับ Kharan Mighthammer เพื่อรวบรวมข้อมูลการลักพาตัว Princess Moira Bronzebeard แล้วนำข้อมูลไปให้ Thrall ที่ Orgrimmar\n\nเจ้าจำได้ว่า Gor'shak บอกว่า Kharan ถูกขังในห้องใกล้ ๆ" },
        description = { "495:1495886616:819077773", "จนถึงตอนนี้ข้าคุยกับคนแคระ Kharan ในห้องขังฝั่งตรงข้ามได้ไม่มากนัก แต่ก็ทำให้เขาเชื่อแล้วว่าข้า หรือพูดให้ถูก พวกเรา ไม่คิดทำร้ายเขา\n\nไปคุยกับเขา รวบรวมข้อมูลเรื่ององค์หญิงและผู้ลักพาตัวให้มากที่สุด แล้วนำกลับไปให้ผู้นำสงคราม\n\nThrall ไม่ต้องการให้องค์หญิงได้รับอันตราย แต่มีแผนใหญ่ที่รวมถึงการพานางกลับ Ironforge อย่างปลอดภัย Kharan รู้เรื่องทั้งหมดนี้แล้ว... ไปได้!" },
        progress = { "42:594359040:182906171", "อะไรพาเจ้ามายังสถานที่อันทรงเกียรติแห่งนี้?" },
        completion = { "112:905701439:459766735 N 43:122128438:1588124795", "นี่คือโอกาสที่ Horde จะเปลี่ยนการเมืองของโลกที่บอบช้ำจากสงครามไปตลอดกาล ฟังให้ดี {name}\n\nภารกิจนี้จะล้มเหลวไม่ได้" },
    },
    [4002] = { -- The Eastern Kingdom
        title = { "19:1687619933:1844423038", "อาณาจักรตะวันออก", variants = { { "20:2074109849:1101251645", "อาณาจักรตะวันออก" } } },
        objective = { "76:1128193636:1973279620", "คุยกับ Thrall หากพร้อมรับภารกิจที่เขาวางแผนไว้" },
        description = { "33:1934247258:1600057302 N 388:1210352101:852328294", "เจ้านำข้อมูลยอดเยี่ยมมา {name}\n\nในฐานะผู้นำสงคราม ข้ามีหน้าที่ทำสิ่งที่ดีที่สุดเพื่อ Horde เพื่อให้คนรุ่นหลังไม่ต้องถูกบังคับให้มีชีวิตอย่างสิ้นหวัง\n\nโอกาสกำหนดพันธมิตรในอนาคตตกมาอยู่ในมือเราแล้ว การช่วยคนแคระอาจเสริมความสัมพันธ์ของเราใน Eastern Kingdoms ได้อย่างมาก นี่จึงเป็นเหตุผลที่เจ้าจะล้มเหลวไม่ได้!\n\nพร้อมหรือยัง?" },
        completion = { "42:1995403972:332443605 N 1:46:46", "จากจุดนี้จะถอยกลับไม่ได้แล้ว {name}" },
    },
    [4003] = { -- The Royal Rescue
        title = { "16:4490994:1269274098", "ช่วยเหลือองค์หญิง" },
        objective = { "87:533980825:506048670", "สังหาร Emperor Dagran Thaurissan แล้วปลดปล่อย Princess Moira Bronzebeard จากเวทชั่วร้ายของเขา" },
        description = { "364:754045202:2136293466", "หากการโจมตีคนแคระดาร์กไอรอนครั้งนี้สำเร็จ แรงสะเทือนจะกระจายไปทั่วอาณาจักรของพวกมัน\n\nองค์หญิง Bronzebeard อยู่ภายใต้การควบคุมของจักรพรรดิ Thaurissan เจ้าต้องสังหารจักรพรรดิเพื่อปลดปล่อยนาง ระวังไว้ งานนี้อันตรายเป็นสองเท่า เพราะขณะถูกควบคุม นางจะโจมตีเจ้าโดยไม่ลังเล\n\nห้ามทำร้ายนางเด็ดขาด!" },
        progress = { "32:410971793:548931440", "<องค์หญิง Moira หดตัวด้วยความกลัว>" },
        completion = { "19:2139298048:880358679", "เจ้าทำอะไรลงไป!" },
        objectiveLabels = {
            monster = { ["Emperor Dagran Thaurissan slain"] = "ปราบ จักรพรรดิ Dagran Thaurissan" },
        },
    },
    [4004] = { -- The Princess Saved?
        title = { "19:655258785:605982113", "องค์หญิงปลอดภัยแล้วหรือ?" },
        objective = { "17:1891619840:1695456169", "กลับไปหา Thrall!" },
        description = { "27:943435660:2147460601 R 370:1105031099:1244506509 R 79:1345169205:1566989278", "เจ้าสังหารสามีข้า ชาว{race}! ลูกของข้าจะเกิดมาโดยไม่มีพ่อ\n\n<องค์หญิง Moira ชี้ตรงมาที่เจ้า>\n\nข้ารับรองว่าเด็กคนนี้จะเป็นผู้ปกครอง Ironforge คนต่อไป เจ้าและเผ่าพันธุ์ของเจ้าจะถูกตามล่าจนวันสิ้นโลกเพราะความผิดครั้งนี้\n\n<เจ้าคิดว่าองค์หญิง Moira อาจยังได้รับผลตกค้างจากเวทของ Thaurissan>\n\nปล่อยข้าไว้ ชาว{race} ข้าแน่ใจว่าผู้นำสงครามของเจ้าคงอยากฟังผลการแทรกแซงของเขา" },
        completion = { "313:685351847:724480072 N 41:1772435348:1374539020", "<Thrall ตกตะลึงกับข้อมูลที่เจ้านำมาบอก>\n\nภัยใหม่ปรากฏขึ้นแล้ว เมื่ออายุขัยของ Magni ใกล้สิ้นสุด ทางก็จะเปิดให้เด็กดาร์กไอรอนที่ยังไม่เกิดคนนี้ขึ้นปกครอง Ironforge\n\nเจ้าทำตามที่ข้าขอสำเร็จ และจะได้รับรางวัล\n\nทีนี้ปล่อยข้าไว้ {name}! ข้าต้องหารือกับ Sylvanas และ Cairne" },
    },
    [4081] = { -- KILL ON SIGHT: Dark Iron Dwarves
        title = { "32:1575391317:1079776724", "พบแล้วสังหาร: คนแคระดาร์กไอรอน" },
        objective = { "208:1114571076:2131659038", "บุก Blackrock Depths แล้วทำลายผู้รุกรานอันชั่วร้าย!\n\nWarlord Goretooth ต้องการให้สังหาร Anvilrage Guardsman 15 ตน, Anvilrage Warden 10 ตน และ Anvilrage Footman 5 ตน เมื่อเสร็จแล้วให้กลับไปหาเขา" },
        description = { "485:435120223:1946859577", "ตามคำสั่ง Warlord Goretooth ผู้บัญชาการกองสำรวจ Kargath:\n\nกองกำลังทั้งหมดของ General Angerforge ภายใน Blackrock Depths ต้องถูกกวาดล้าง\n\nทหารของ Angerforge เป็นนักฆ่าโหดเหี้ยม ผู้สังหารหมู่กองพลที่ 109 ของกองสำรวจ Kargath ขอเตือนเหล่าวีรชนให้ระมัดระวังอย่างยิ่งเมื่อเผชิญหน้าพวกมัน\n\nผู้ทำลายแนวหน้าแห่งกองกำลัง General Angerforge ใน Blackrock Depths จะได้รับรางวัลตอบแทน" },
        progress = { "12:351164566:2103200252 R 44:251102601:137182552", "มีอะไร ชาว{race}? ไม่เห็นหรือว่าข้ามีหมวดทหารต้องบัญชาการ?" },
        completion = { "183:1343635369:480817419", "การโจมตีแรกนี้คงทำให้ Angerforge หนาว ๆ ร้อน ๆ ทีนี้ไปได้ ทหาร ข้ายังมีงานต้องทำ ศึกต้องวางแผน และศัตรูต้องบดขยี้!\n\nดูป้ายประกาศจับหากอยากได้งานเพิ่ม" },
        objectiveLabels = {
            monster = { ["Anvilrage Guardsman slain"] = "ปราบ ทหารรักษาการณ์ Anvilrage", ["Anvilrage Warden slain"] = "ปราบ ผู้คุม Anvilrage", ["Anvilrage Footman slain"] = "ปราบ ทหารราบ Anvilrage" },
        },
    },
    [4082] = { -- KILL ON SIGHT: High Ranking Dark Iron Officials
        title = { "47:668771540:1690106834", "พบแล้วสังหาร: เจ้าหน้าที่ดาร์กไอรอนระดับสูง" },
        objective = { "208:502951626:475726997", "บุก Blackrock Depths แล้วทำลายผู้รุกรานอันชั่วร้าย!\n\nWarlord Goretooth ต้องการให้สังหาร Anvilrage Medic 10 ตน, Anvilrage Soldier 10 ตน และ Anvilrage Officer 10 ตน เมื่อเสร็จแล้วให้กลับไปหาเขา" },
        description = { "413:1815292901:125864859", "ตามคำสั่ง Warlord Goretooth ผู้บัญชาการกองสำรวจ Kargath:\n\nGrandmaster Lexlort หัวหน้าหน่วยลาดตระเวนของกองสำรวจ Kargath กลับมาพร้อมข่าวที่อยู่ของเจ้าหน้าที่ดาร์กไอรอนระดับสูง หลังประตูที่ล็อกไว้ใกล้ใจกลางเมือง พวกมันกำลังฝึกกำลังพลเพื่อสังหารทหารของเรา จงไป Blackrock Depths แล้วทำลายพวกมัน!\n\nผู้ทำภารกิจสำเร็จจะได้รับรางวัลตอบแทน" },
        progress = { "37:759802361:1267810672 N 20:2032912446:1518921629", "เจ้าอีกแล้วหรือ? ต้องยอมรับเลย {name} เจ้าช่างไม่ยอมแพ้" },
        completion = { "235:875212219:800729155", "Angerforge คง... โกรธแน่นอน กลับมาหาข้าเมื่อได้รับรางวัลครั้งที่สาม แล้วเราจะดำเนินปฏิบัติการ: สังหาร Angerforge ข้าเปิดเผยรายละเอียดไม่ได้ แต่รับรองว่าต้องมีใครสักคนตาย" },
        objectiveLabels = {
            monster = { ["Anvilrage Medic slain"] = "ปราบ แพทย์สนาม Anvilrage", ["Anvilrage Soldier slain"] = "ปราบ ทหาร Anvilrage", ["Anvilrage Officer slain"] = "ปราบ นายทหาร Anvilrage" },
        },
    },
    [4083] = { -- The Spectral Chalice
        title = { "20:72157652:74393089", "จอกวิญญาณ" },
        progress = { "105:722670125:1739017967", "จอกวิญญาณลอยอยู่กลางอากาศ ขยับขึ้นลงช้า ๆ... ราวกับตามจังหวะหัวใจที่ใกล้สิ้นลม" },
        completion = { "65:601652662:1698082822", "อัญมณีตกลงสู่ส่วนลึกของจอกโดยไร้เสียง..." },
        description = { "105:722670125:1739017967", "จอกวิญญาณลอยอยู่กลางอากาศ ขยับขึ้นลงช้า ๆ... ราวกับตามจังหวะหัวใจที่ใกล้สิ้นลม" },
        required = { [7910] = { "9:779235392:1830488727", "ทับทิมสาแหรก" }, [3577] = { "8:1868650072:189161854", "แท่งทองคำ" }, [6037] = { "14:999689902:1924659795", "แท่งเงินทรูซิลเวอร์" } },
        objectiveLabels = {
            item = { ["Star Ruby"] = "ทับทิมสาแหรก", ["Gold Bar"] = "แท่งทองคำ", ["Truesilver Bar"] = "แท่งเงินทรูซิลเวอร์" },
        },
    },
    [4121] = { -- Precarious Predicament
        title = { "22:1104453021:1282655950", "สถานการณ์คับขัน" },
        objective = { "297:649422069:438487028", "คุมตัวนักโทษ Grark Lorkrub ผ่าน Burning Steppes และ Blackrock Mountain ไปยัง Searing Gorge\n\nเจ้าจำได้ว่า Lexlort บอกว่าจะให้คนรออยู่อีกฝั่งเพื่อรับ Grark ไปควบคุมตัว\n\nเจ้าต้องส่ง Thorium Shackles คืนให้ Lexlort ด้วย" },
        description = { "275:1017150492:1293334097", "เจ้าเชื่อจริง ๆ หรือว่าจะพาข้าไปถึงจุดนัดพบได้? คิดว่าจะบุกป้อม Blackrock ที่แน่นหนา จับคนสำคัญของพวกมัน แล้วไม่มีใครหรือสิ่งใดรู้ตัวเลยหรือ?\n\nเจ้าจะถูกทำลาย!" },
        progress = { "35:834891815:1884980603 N 1:46:46", "ข้าจะรับตัวสวะผู้ทรยศนี่ไว้เอง {name}" },
        completion = { "39:1414359856:1851118227 N 100:901468717:1206582096", "ความกล้าของเจ้าจะไม่ถูกมองข้าม {name} เจ้าคู่ควรกับรางวัลนี้แล้ว ตอนนี้ Warlord จะคุยเรื่องภารกิจสุดท้ายกับเจ้า" },
        required = { [11286] = { "16:1036861025:1755082703", "ตรวนทอเรียม" } },
        objectiveLabels = {
            item = { ["Thorium Shackles"] = "ตรวนทอเรียม" },
        },
    },
    [4122] = { -- Grark Lorkrub
        title = { "13:1252739914:1268859904", "Grark Lorkrub" },
        objective = { "356:601507869:2013892667", "เดินทางไป Burning Steppes แล้วหา Grark Lorkrub เจ้าจำได้ว่า Lexlort บอกว่ามีคนเห็นเขาครั้งสุดท้ายในป้อม Blackrock ขนาดใหญ่\n\nเมื่อพบ ให้ใช้ Thorium Shackles พันธนาการเขา แล้วคุมตัวผ่าน Blackrock Mountain กลับไป Searing Gorge คนของ Lexlort จะรอรับตัว Grark อยู่อีกฝั่ง" },
        description = { "341:268760035:1332295501 N 112:1314009472:1866024439", "ข้าตามรอยเขาข้าม Searing Gorge ผ่านภูเขาไปถึง Burning Steppes จับได้คาหนังคาเขาว่าคนทรยศนั่นส่งข้อมูลสำคัญเกี่ยวกับการปฏิบัติงานประจำวันของเราให้ออร์ค Blackrock ข้าพูดถึง Grark Lorkrub\n\nตอนนี้เขาอยู่ใน Burning Steppes อย่างปลอดภัยภายใต้การคุ้มครองของพวกมัน หรืออย่างน้อยเขาก็คิดเช่นนั้น\n\nรับโซ่ตรวนนี้ไป {name} หา Grark ใส่ตรวนให้เขา แล้วคุมตัวผ่าน Blackrock Mountain ทำสำเร็จแล้วรางวัลเป็นของเจ้า" },
        completion = { "69:1144431175:808194396", "เจ้าไม่เห็นหรือว่าเราจะได้พลังเพียงใดจากการเข้าร่วมกองทัพ Blackrock?" },
    },
    [4123] = { -- The Heart of the Mountain
        title = { "25:2060958710:988918904", "หัวใจแห่งภูเขา" },
        objective = { "76:1853385736:1765985632", "นำ Heart of the Mountain ไปให้ Maxwort Uberglint ที่ Burning Steppes" },
        description = { "467:1984958694:1260995431", "ข้าตามหาอัญมณีชิ้นหนึ่งมาหลายปี มันชื่อ Heart of the Mountain ใหญ่เท่ากำปั้นเจ้า! คนแคระดาร์กไอรอนล็อกมันไว้ในห้องนิรภัย ไม่ว่าข้าจะพยายามเพียงใด พวกมันก็ไม่ยอมขาย\n\nข้าจึงต้องใช้กำลัง\n\nฝ่าไปยัง Lower Vault ของ Blackrock Depths เปิดตู้นิรภัยลับแล้วนำอัญมณีมา การจะทำเช่นนั้น เจ้าต้องปราบ Watchman Doomgrip ซึ่งจะไม่ปรากฏจนกว่าเจ้าจะเปิดหีบวัตถุโบราณทุกใบในห้องนิรภัย!\n\nโชคดี" },
        progress = { "73:312693912:2024264430", "เจ้ามี Heart of the Mountain หรือยัง? สำหรับข้า มันมีค่าจนประเมินไม่ได้" },
        completion = { "80:882515049:318867321 N 23:397160124:838604043", "เจ้าได้หัวใจมาแล้ว! น่าทึ่ง! มันงดงามยิ่งกว่าที่ข้าคิดไว้!\n\nโปรดรับสิ่งนี้เป็นค่าตอบแทน {name}!" },
        required = { [11309] = { "25:2060958710:988918904", "หัวใจแห่งภูผา" } },
        steps = { { "25:2060958710:988918904", "หัวใจแห่งภูผา" } },
    },
    [4126] = { -- Hurley Blackbreath
        title = { "18:137458920:1461505120", "Hurley Blackbreath" },
        objective = { "68:1307914210:404118793", "นำ Lost Thunderbrew Recipe ไปให้ Ragnar Thunderbrew ที่ Kharanos" },
        description = { "177:1976303627:734807467 N 272:806592822:1217546519", "คนแคระดาร์กไอรอนที่มีเจ้าวายร้าย Hurley Blackbreath นำ ขโมยสูตรชั้นยอดของ Thunderbrew ไป นั่นคือ Thunderbrew Lager พวกชั่ว! มันไม่คู่ควรกับเบียร์ดี ๆ เช่นนี้!\n\n{name} ข้ามีงานยากให้เจ้า ไปยัง Blackrock Depths ใน Burning Steppes ทำลายถัง Thunderbrew Lager ทุกใบที่พบ แล้วนำสูตรของเรากลับมา!\n\nขอร้อง เอาสูตรนั้นคืนมา แม้เจ้าจะต้องพลิก Blackrock Depths ทั้งแห่งเพื่อหามันก็ตาม!" },
        progress = { "24:992182503:1818715338 N 79:376829120:2012608484", "เจ้ามีสูตรแล้วหรือยัง {name}? ข้าทนคิดถึงพวกดาร์กไอรอนดื่มเบียร์ของตระกูลข้าไม่ได้!" },
        completion = { "142:1758608558:1461504419 N 27:282235490:1883380053", "เจ้าพบแล้ว! ทำได้ดี! หวังว่าจะทุบพวกดาร์กไอรอนกับ Hurley Blackbreath เสียหนักเลยนะ!\n\nตระกูล Thunderbrew ยินดีรับใช้เจ้า {name} เจ้าเป็นวีรชนเหนือวีรชน!" },
        required = { [11312] = { "23:1936203382:1220030590", "สูตร Thunderbrew ที่สูญหาย" } },
        objectiveLabels = {
            item = { ["Lost Thunderbrew Recipe"] = "สูตร Thunderbrew ที่สูญหาย" },
        },
    },
    [4128] = { -- Ragnar Thunderbrew
        title = { "18:165792927:164852522", "Ragnar Thunderbrew" },
        objective = { "30:202239968:1570103707", "คุยกับ Ragnar Thunderbrew" },
        description = { "4:1229513475:163773219 N 247:178711441:1281439833", "โฮ่ {name} ข้าได้ยินว่า Ragnar Thunderbrew โกรธเป็นฟืนเป็นไฟที่มีคนขโมยเบียร์ เขากำลังหานักผจญภัยใจเด็ด และยินดีจ่ายอย่างงาม\n\nหากสนใจ ไปคุยกับ Ragnar เขาอยู่ที่ Thunderbrew Distillery ใน Kharanos แห่ง Dun Morogh" },
        completion = { "189:116957744:1993739654", "ถูกแล้ว ข้าโกรธ! ข้าถูกปล้น! ถูกขโมยสูตรของตระกูลไปสูตรหนึ่ง! มันกล้าดีอย่างไร! ราวกับข้ายังมีเหตุเกลียดดาร์กไอรอนไม่พออย่างนั้นแหละ! ทีนี้ โอ้... ทีนี้พวกมันเจอดีแน่!" },
    },
    [4132] = { -- Operation: Death to Angerforge
        title = { "30:2049691716:1945523521", "ปฏิบัติการ: สังหาร Angerforge" },
        objective = { "110:875655377:416803574", "เดินทางไป Blackrock Depths แล้วสังหาร General Angerforge! เมื่อเสร็จให้กลับไปหา Warlord Goretooth" },
        description = { "32:1826523429:379126006 N 332:51088775:126486024", "เจ้าทำงานได้เป็นแบบอย่าง {name} ถึงเวลาส่งเจ้าไปภารกิจสุดท้ายแล้ว\n\nGeneral Angerforge ดาร์กไอรอนผู้ประสานการโจมตีกองพลที่ 109 ของกองสำรวจ Kargath และสังหารหมู่กำลังพลของเรา ต้องได้รับโทษอย่างยุติธรรม\n\nนี่จะเป็นภารกิจที่หนักหนาที่สุดของเจ้าแน่นอน แต่หากสำเร็จ เจ้าจะได้รับรางวัลอย่างงาม" },
        progress = { "46:1593501741:666600528", "กำจัดเพชฌฆาตแห่ง Blackrock แล้วหรือยัง?" },
        completion = { "79:1012142442:958133245 N 89:1645272100:1671314268", "ในที่สุด! เจ้าชั่วได้รับโทษแล้ว! เจ้าช่างยอดเยี่ยม {name} จงสวมเหรียญนี้เป็นสัญลักษณ์แห่งความทุ่มเทอันมั่นคงต่อ Horde และกองสำรวจ Kargath" },
    },
    [4133] = { -- Vivian Lagrave
        title = { "14:1815851225:623758967", "Vivian Lagrave" },
        objective = { "50:1028770356:470384719", "คุยกับ Shadowmaster Vivian Lagrave ที่ Kargath" },
        description = { "234:1976582151:497620415", "Shadowmaster Vivian Lagrave ต้องการความช่วยเหลือของเจ้า นางอยู่ในด่านออร์ค Kargath แห่ง Badlands กำลังตามข่าวลือเรื่องเครื่องดื่มชนิดหนึ่งที่คนแคระดาร์กไอรอนแห่ง Blackrock Depths ผลิต\n\nไปคุยกับ Vivian นางรอเจ้าอยู่" },
        completion = { "22:1981452371:190998932 N 138:1779859597:1293647208", "ขอบใจที่มา {name} ที่นี่ก็มีเสน่ห์แบบแห้งแล้งอยู่บ้าง แต่ขาดความสะดวกสบายของ Apothecarium\n\nพอเรื่องทักทาย เราคุยธุระกันดีไหม?" },
    },
    [4134] = { -- Lost Thunderbrew Recipe
        title = { "23:1936203382:1220030590", "สูตร Thunderbrew ที่สูญหาย" },
        objective = { "63:1034757318:776344282", "นำ Lost Thunderbrew Recipe ไปให้ Vivian Lagrave ที่ Kargath" },
        description = { "498:1536809403:1402169114", "มีข่าวลือว่าดาร์กไอรอนชื่อ Hurley Blackbreath ขโมยสูตรเบียร์ไป เบียร์นี้ชื่อ Thunderbrew Lager ว่ากันว่ามอบพละกำลังและความกล้ามหาศาลแก่ผู้ดื่ม เราต้องการศึกษามัน บางทีอาจประยุกต์คุณสมบัติของมันไปใช้ในทางอื่น... ทางที่สอดคล้องกับเป้าหมายของ Forsaken มากกว่า\n\nเข้าไปใน Blackrock Depths หา Hurley ชิงสูตร Thunderbrew Lager แล้วนำมาให้ข้า\n\nหากจะหาเขา เจ้าคงต้องล่อด้วยการคุกคามเบียร์อันล้ำค่าของเขา" },
        progress = { "50:1610001635:315289192 N 1:63:63", "เจ้ามีสูตร Thunderbrew Lager หรือยัง {name}?" },
        completion = { "299:1954042899:215598265", "ดีมาก ข้าจะส่งสูตรไปให้ Apothecarium ศึกษา แล้วเราจะไขความลับของมันได้ในที่สุด วันหนึ่งคนแคระแห่ง Alliance อาจพบว่าคุณสมบัติของเครื่องดื่มนี้ถูกใช้ต่อกรกับพวกเขาเอง!\n\nข้าว่ามันน่าขันเหลือเกิน บางทีความตายอาจเปลี่ยนอารมณ์ขันของคนเรา... เจ้าคิดว่าอย่างไร?" },
        required = { [11312] = { "23:1936203382:1220030590", "สูตร Thunderbrew ที่สูญหาย" } },
        steps = { { "23:1936203382:1220030590", "สูตร Thunderbrew ที่สูญหาย" } },
    },
    [4136] = { -- Ribbly Screwspigot
        title = { "18:489124464:2068987380", "Ribbly Screwspigot" },
        objective = { "63:210054649:1506347280", "นำ Ribbly's Head ไปให้ Yuka Screwspigot ที่ Burning Steppes" },
        description = { "495:1743250571:665374615", "น้องชายข้า Ribbly เป็นภาระของครอบครัวมาตลอด เอาเงินเราไปผลาญกับแผนหาเงินครั้งแล้วครั้งเล่า\n\nแผนล่าสุดคงแย่ที่สุด เพราะ Baron Revilgaz แห่ง Booty Bay เพิ่งตั้งค่าหัว Ribbly ผู้น่าสงสาร บอกไม่ถูกเลยว่าตระกูล Screwspigot ดีใจเพียงใด! ในที่สุด Ribbly ตัวน้อยของเราก็มีค่าขึ้นมาแล้ว!\n\nแต่ตอนนี้เขาซ่อนอยู่ลึกใน Blackrock Depths ช่วยหาแล้วพาตัวมาให้ข้าที!\n\nหรือหากเขาไม่ยอมมา ก็ไม่เป็นไร... เอาแค่หัวมาก็พอ" },
        progress = { "47:1445305414:1769510712", "เจ้าได้ตัว Ribbly มาไหม? หรืออย่างน้อยสักส่วนหนึ่งของเขา?" },
        completion = { "215:92316188:588732989 N 89:923693511:1663932813", "อาฮ่า! เจ้าพบเขาแล้ว! และ... ดูเหมือนน้องชายข้าไม่ยอมมาดี ๆ น่าเสียดาย ข้าอยากเห็นหน้าเขาตอนบอกแผนว่าจะส่งตัวให้ Revilgaz\n\nขอบใจ {name} เจ้าทำให้ครอบครัวข้ามีความสุขมาก และ Ribbly ก็ไม่เคยดูสงบเท่าตอนนี้เลย" },
        required = { [11313] = { "13:376449091:311780585", "ศีรษะของ Ribbly" } },
        steps = { { "13:376449091:311780585", "ศีรษะของ Ribbly" } },
    },
    [4201] = { -- The Love Potion
        title = { "15:2077977198:1043873579", "ยาเสน่ห์" },
        objective = { "108:133237813:1718326728", "นำ Gromsblood 4 ชิ้น, Giant Silver Vein 10 ชิ้น และ Nagmara's Filled Vial ไปให้ Mistress Nagmara ใน Blackrock Depths" },
        description = { "431:324795289:1683967527 N 46:1628905970:2001252259", "โอ้ ความรักช่างเจ็บปวด! Private Rocknot ที่รักของข้าไม่หวั่นไหวต่อเสน่ห์เลย ข้าถูกปฏิเสธ! ชวนคลั่งนัก!\n\nเจ้าต้องช่วยข้า! พวกซัคคิวบัสรู้เรื่องรักดี ข้าทำยาทลายกำแพงเหล็กรอบหัวใจ Rocknot ได้ แต่ต้องมีสมุนไพร Gromsblood, Giant Silver Vein จากยักษ์หน้าผาใน Azshara และน้ำจากแอ่ง Golakka Springs ใน Un'Goro เจ้าตักน้ำใส่ขวดนี้ได้\n\nขอร้อง {name} ช่วยผู้เคราะห์ร้ายคนนี้ตามหาความสุขที!" },
        progress = { "74:1774601968:1304769548", "เจ้ามีส่วนผสมหรือยัง? ช่องว่างในหัวใจกำลังจะกลืนข้าแล้ว!" },
        completion = { "122:325134109:2123289163 N 29:1426764712:895062065", "โอ้ เจ้าทำได้แล้ว! ทีนี้ข้าก็ทำยาไปใช้กับ Rocknot ได้ ในที่สุดเขาจะตกเป็นเหยื่อเสน่ห์ของข้า!\n\nขอบใจ {name} เจ้าเป็นยอดนักรบแห่งความรัก!" },
        required = { [8846] = { "10:1384569679:638036997", "สมุนไพร Gromsblood" }, [11405] = { "17:700952900:1323663453", "เส้นเลือดเงินของยักษ์" }, [11413] = { "21:359532954:886867007", "ขวดของ Nagmara ที่บรรจุน้ำแล้ว" } },
        objectiveLabels = {
            item = { ["Gromsblood"] = "สมุนไพร Gromsblood", ["Giant Silver Vein"] = "เส้นเลือดเงินของยักษ์", ["Nagmara's Filled Vial"] = "ขวดของ Nagmara ที่บรรจุน้ำแล้ว" },
        },
    },
    [4241] = { -- Marshal Windsor
        title = { "15:814435656:409591270", "จอมพล Windsor" },
        objective = { "190:371781648:247504356", "เดินทางไป Blackrock Mountain ทางตะวันตกเฉียงเหนือแล้วเข้า Blackrock Depths สืบว่าเกิดอะไรขึ้นกับ Marshal Windsor\n\nเจ้าจำได้ว่า Ragged John บอกว่า Windsor ถูกลากไปคุก" },
        description = { "261:1285084031:1362549126", "เจ้าขี้ขลาดไร้ประโยชน์นั่นบอกว่า Windsor ยังมีชีวิตหรือ?\n\nเตรียมตัว ผู้แทน เจ้าจะเข้าไปหาเขา หาก Windsor ยังอยู่ จงพากลับมา หากตายแล้ว ข้าต้องการหลักฐาน\n\n<Maxwell หัวเราะ>\n\nพนันว่าเจ้าเริ่มเบื่อคำนี้แล้วใช่ไหม?" },
        completion = { "29:1013480132:90891501", "เขาอยู่ไหน! ข้าจะฆ่าเขา!" },
    },
    [4242] = { -- Abandoned Hope
        title = { "14:1844292344:940264054", "ความหวังที่ถูกทอดทิ้ง" },
        objective = { "34:221259971:1113738360", "แจ้งข่าวร้ายให้ Marshal Maxwell ทราบ" },
        description = { "381:2140615023:1596716119 N 1:46:46", "Bolvar เป็นคนโง่ ข้ากำลังรวบรวม “หลักฐาน” อันล้ำค่าของเขา เพื่อเอาไปยัดลงคอเขา\n\nเขาเป็นตัวตลกตาบอด หลักฐานยืนห่างแค่สองฟุตแต่กลับมองไม่เห็น\n\nส่วนข้อมูลของข้า มันหายไปแล้ว สูญไป เอาคืนไม่ได้\n\nหากข้าพบ Ironfoe และออกจากเขาวงกตนี้ได้ ที่แรกที่จะไปคือ Stormwind เพื่อเอาค้อนฟาดระหว่างตาเจ้าสัตว์เลื้อยคลานนั่น\n\nปล่อยข้าไว้ {name}" },
        completion = { "246:2014741569:1689989271 N 1:46:46", "ดูเหมือนเขาจะบ้าไปแล้ว\n\n<Maxwell ก้มหน้าไว้อาลัย>\n\nน่าเสียดายที่นักรบผู้เคยสง่างามและมีเกียรติกลับกลายเป็นคนเสียสติพูดจาไม่รู้เรื่อง ข้าว่าเราคงมาถึงทางตันแล้ว...\n\nข้าต้องตอบแทนความพยายามของเจ้าจนถึงตอนนี้ {name}" },
    },
    [4262] = { -- Overmaster Pyron
        title = { "16:790915443:998873647", "Overmaster Pyron" },
        objective = { "143:1623925967:1563388591", "สังหาร Overmaster Pyron แล้วกลับไปหา Jalinda Sprig\n\nเจ้าจำได้ว่า Jalinda บอกว่า Pyron เฝ้าเหมืองหินอยู่ บางทีควรไปหาที่นั่น" },
        description = { "463:1762430725:582120491", "จอมเวทห้าคนล่าสุดที่ข้าส่งไปสอดแนม Blackrock Mountain กลับมาไหม้เกรียม พร้อมผมทรงฟูแบบโนมสีส้มติดถาวร หรือเลวร้ายกว่านั้น\n\n<Jalinda หยิบเถ้าจากพื้นแล้วปล่อยลอยไปในอากาศ>\n\nตัวร้ายที่ชื่อ Overmaster Pyron ดูจะก่อปัญหามากเป็นพิเศษ เราต้องกำจัดธาตุตนนั้นเพื่อให้คณะสำรวจเข้า Blackrock Depths ได้!\n\nมันเฝ้าทางเข้าที่ Blackrock Quarry" },
        progress = { "45:1813189087:634121383", "<ดูเหมือน Jalinda กำลังจ้องศีรษะเจ้า>" },
        completion = { "21:516791915:342524245", "Incendius หรือ? โอ้ ไม่นะ..." },
        objectiveLabels = {
            monster = { ["Overmaster Pyron slain"] = "ปราบ จอมบัญชาการ Pyron" },
        },
    },
    [4263] = { -- Incendius!
        title = { "10:1601640591:2018729298", "Incendius!" },
        objective = { "56:178559835:2000329639", "หา Lord Incendius ใน Blackrock Depths แล้วทำลายเขา!" },
        description = { "252:1559275876:941488485 N 131:429397709:1243225384", "แน่ใจหรือว่า Pyron พูดว่า “Incendius” ตอนตาย?\n\n<Jalinda กลืนน้ำลายอย่างฝืดคอ>\n\nว่ากันว่า Lord Incendius เป็นลูกสมุนของ Ragnaros! โอ้ ตายละ... เราจะทำอย่างไรดี?\n\nเจ้าคิดว่ารับภารกิจอีกอย่างไหวไหม? ข้าไม่มีใครให้ส่งไปแล้ว {name}!\n\nเราคงส่งทีมเข้าไปไม่ได้ ตราบใดที่ Incendius ยังปลุก Pyron ขึ้นจากเถ้าถ่านเรื่อย ๆ\n\nเจ้าต้องหา Lord Incendius แล้วทำลายเขา!" },
        progress = { "19:2029876216:222389376", "เจ้าปีศาจนั่นตายแล้วหรือยัง??" },
        completion = { "136:1546799388:1097460509", "โอ้ ไม่นะ! แน่ใจหรือว่า Incendius พูดว่า “Ragnaros”?\n\n<Jalinda ส่งของบางอย่างให้เจ้า ตบข้อมือเจ้าเบา ๆ แล้วจมลงในความคิด>" },
        objectiveLabels = {
            monster = { ["Lord Incendius slain"] = "ปราบ ลอร์ด Incendius" },
        },
    },
    [4264] = { -- A Crumpled Up Note
        title = { "18:1032275408:1814462046", "บันทึกยับยู่ยี่" },
        objective = { "124:542336065:141802412", "เจ้าอาจเพิ่งพบสิ่งที่ Marshal Windsor สนใจอยากเห็น บางทีอาจยังมีความหวังอยู่" },
        description = { "433:1600263188:1747387654", "บันทึกมีคราบเปื้อนทั่วพื้นผิว แทบอ่านไม่ออก แต่เจ้าจับความได้ดังนี้:\n\n...ช่างย้อนแย้งอย่างน่าสะใจ...\n\n...การล่มสลายของ Alliance ที่แตกร้าว...\n\n...หากไม่ใช่ความขยันของ General Angerforge เราอาจไม่มีวันพบรูปแบบการเข้ารหัส...\n\n...Argelmach เกือบถอดรหัสบันทึกของ Windsor เสร็จแล้ว\n\nนายของเราจะผงาดจากส่วนลึก แล้วบดขยี้ทุกผู้ที่ยังเหลืออยู่...\n\n— Emperor Dagran Thaurissan" },
        progress = { "70:2126441024:1529645611 N 1:63:63", "<Marshal Windsor มองบันทึกในมือเจ้า>\n\nเจ้ามีอะไรอยู่นั่น {name}?" },
        completion = { "52:226203893:103200300", "<Marshal Windsor รับบันทึกแล้วเริ่มอ่าน>" },
    },
    [4282] = { -- A Shred of Hope
        title = { "15:193591258:822092688", "เศษเสี้ยวแห่งความหวัง" },
        objective = { "150:2138644868:103928512", "นำข้อมูลที่สูญหายของ Marshal Windsor กลับมา\n\nMarshal Windsor เชื่อว่าข้อมูลอยู่กับ Golem Lord Argelmach และ General Angerforge" },
        description = { "77:2114413788:1392086549 N 361:2117066442:1567780327", "<Marshal Windsor เขย่าบันทึกอย่างตื่นเต้น>\n\nรู้ไหมว่านี่หมายความว่าอย่างไร {name}?\n\nบางทีเราอาจยังไม่สูญสิ้นทุกอย่าง! เท่าที่ข้าดูออก ข้อมูลอยู่กับคนแคระดาร์กไอรอนสองคน General Angerforge และจ้าวโกเลม Argelmach ข้ารู้สึกว่าต่อให้ขอดี ๆ พวกมันก็คงไม่ยอมส่งให้\n\nหวังว่าเจ้าพร้อมสู้\n\nจงออกไปหาตัวร้ายทั้งสอง! ทำลายพวกมันแล้วนำข้อมูลที่สูญหายของข้ากลับมา" },
        progress = { "40:622654937:501694625", "อีกไม่นานแผนลวงครั้งใหญ่นี้จะสิ้นสุด" },
        completion = { "87:1399410267:1316674148", "<Marshal Windsor คว้าแผ่นจารึกทั้งสองจากมือเจ้า>\n\nเราต้องออกไปจากที่นี่!" },
        required = { [11464] = { "34:619155097:1387845880", "ข้อมูลที่สูญหายของ Marshal Windsor" }, [11465] = { "34:619155097:1387845880", "ข้อมูลที่สูญหายของ Marshal Windsor" } },
        objectiveLabels = {
            item = { ["Marshal Windsor's Lost Information"] = "ข้อมูลที่สูญหายของ Marshal Windsor" },
        },
    },
    [4286] = { -- The Good Stuff
        title = { "14:1604244057:687072715", "ของดี" },
        objective = { "218:544562274:836122489", "เดินทางไป Blackrock Depths แล้วเก็บ Dark Iron Fanny Pack 20 ใบ เมื่อเสร็จให้กลับไปหา Oralius เจ้าคาดว่าคนแคระดาร์กไอรอนใน Blackrock Depths พกสิ่งประดิษฐ์ที่เรียกว่า “กระเป๋าคาดเอว” เหล่านี้อยู่" },
        description = { "317:532623618:1309623825", "Captain Winky บอกว่าดาร์กไอรอนใน Depths มีของดีทั้งนั้น ใช่ไหม Winky?\n\n<Oralius พยายามเลียนแบบโจรสลัดอย่างเต็มที่>\n\nอาร์รร สหาย! ถูกต้องแล้ว!\n\nเข้าใจที่ข้าพูดไหม? เจ้าต้องเข้าไปเอาตัวอย่างของดีกลับมาให้ข้า\n\nเข้าไปส่ายสะโพกหาเงินได้เลย!" },
        progress = { "31:1965540178:1309395350 N 39:737875724:376853590", "ตอนนี้ข้าไม่มีเวลาถูกรบกวน {name} ข้ากับ Winky มีประชุมต้องเข้าร่วม" },
        completion = { "212:684710068:1423646374 N 30:1449557720:517720471", "<Oralius เริ่มคุ้ยกระเป๋าคาดเอวที่กองเป็นภูเขา>\n\nโอ้ วิเศษ!\n\n<Oralius ยื่นจมูกใหญ่ลงในกองแล้วสูดกลิ่น>\n\nน่าอร่อย! ดูของดีพวกนี้สิ!\n\nหยิบไปให้ตัวเองสักใบ {name} มีพอแบ่งกันทั่วถึง" },
        required = { [11468] = { "20:749392169:115968491", "กระเป๋าคาดเอว Dark Iron" } },
        steps = { { "20:749392169:115968491", "กระเป๋าคาดเอว Dark Iron" } },
    },
    [4295] = { -- Rocknot's Ale
        title = { "13:1515837722:167898298", "เบียร์ของ Rocknot" },
        progress = { "155:1941183681:136880325 R 18:1823746292:236552846", "โอ้ เบียร์! ข้ายอมฆ่าเพื่อ Dark Iron Ale สักหน่อยเลย!! เร็วเข้า ข้ากำลังสร่างเมา! รู้ได้เพราะความสร่างทำให้ตามัว... และเจ้าเริ่มดูเหมือนชาว{race}ที่ข้าฆ่าเมื่อสัปดาห์ก่อน!" },
        completion = { { "123:92862134:1564108890", "127:2095688709:1442370578" }, "นี่อะไร? อา! กลิ่นเหมือน Dark Iron Ale! เหล้าทำให้ข้ามองพร่า แต่ข้าดูออกว่าเจ้าเป็นเพื่อนแท้!" },
        description = { "155:1941183681:136880325 R 18:1823746292:236552846", "โอ้ เบียร์! ข้ายอมฆ่าเพื่อ Dark Iron Ale สักหน่อยเลย!! เร็วเข้า ข้ากำลังสร่างเมา! รู้ได้เพราะความสร่างทำให้ตามัว... และเจ้าเริ่มดูเหมือนชาว{race}ที่ข้าฆ่าเมื่อสัปดาห์ก่อน!" },
        required = { [11325] = { "17:590281439:19822824", "แก้วเบียร์ Dark Iron" } },
        objectiveLabels = {
            item = { ["Dark Iron Ale Mug"] = "แก้วเบียร์ Dark Iron" },
        },
    },
    [4322] = { -- Jail Break!
        title = { "11:559555255:292791641", "แหกคุก!" },
        objective = { "102:2113721125:556761261", "ช่วย Marshal Windsor เอาอุปกรณ์คืนและปล่อยเพื่อนของเขา หากสำเร็จให้กลับไปหา Marshal Maxwell" },
        description = { "28:178072821:192783397 N 202:1061960553:925502766", "เราต้องออกไปจากที่นี่ {name} ช่วยข้าเอาอุปกรณ์คืนจากเขตเสบียงและปล่อยเพื่อน ๆ หากเราออกไปได้ เจ้าต้องไป Morgan's Vigil แล้วคุยกับ Marshal Maxwell เขาจะให้คำแนะนำต่อไป" },
        progress = { "20:1307526127:521767498 N 55:515248988:346844347", "เจ้าดูเหนื่อยมาก {name} บางทีควรนั่งพักข้างกองไฟให้สบายใจเสียหน่อย" },
        completion = { "9:651738054:229314926 N 224:478134786:2093111296", "น่าทึ่ง {name} น่าทึ่งจริง ๆ Windsor เพิ่งพรวดผ่านที่นี่ไปไม่ถึงห้านาที เขากล่าวเรื่องใหญ่โต แต่ยืนยันว่ามีหลักฐานรองรับ ตอนนี้กำลังไป Stormwind เพื่อเผชิญหน้า Bolvar และ... Lady Prestor" },
    },
    [4324] = { -- Yuka Screwspigot
        title = { "16:1404495663:1640625216", "Yuka Screwspigot" },
        objective = { "51:2006332797:33047370", "คุยกับ Yuka Screwspigot ที่ Burning Steppes" },
        description = { "465:909709802:1030086706", "แม้น้องชายข้า Ribbly จะไร้ค่ามาทั้งชีวิต แต่ในที่สุดข้าว่าเขาก็มีค่าเสียที! ทว่า... เราอาจต้องขอให้เจ้าช่วยเปลี่ยนมูลค่าใหม่นี้เป็นเงิน\n\nYuka พี่น้องหญิงของข้าตามหาเขามาหลายสัปดาห์ และตามรอยไปถึง Burning Steppes นางส่งข่าวมาขอคนรับจ้างช่วย\n\nว่าอย่างไร อยากช่วยไหม? หากสนใจ ไปคุยกับนาง เจ้าจะพบ Yuka อยู่ใน Flame Crest ถ้ำทางตะวันตกเฉียงเหนือของ Dreadmaul Rock" },
        completion = { "148:1010125596:1027616115", "ใช่ ข้ากำลังหาพี่น้องของข้า เราต้องหาแล้วพาตัวกลับมา ขอให้เขาได้รับพร\n\nแต่ถ้าพามาทั้งตัวไม่ได้... แค่หัวก็พอ" },
    },
    [4341] = { -- Kharan Mighthammer
        title = { "18:576064298:71864513", "Kharan Mighthammer" },
        objective = { "163:309602247:627978117", "เดินทางไป Blackrock Depths แล้วหา Kharan Mighthammer\n\nพระราชาตรัสว่า Kharan ถูกขังอยู่ที่นั่น บางทีควรมองหาคุก" },
        description = { "216:1019298886:509485938 N 259:1777229192:1218657895", "เจ้าเคยไปซาก Thaurissan ที่ยังคุกรุ่นมาแล้วหรือ? บังเอิญพบคนไร้ค่าชื่อ Kharan Mighthammer บ้างไหม? คนแคระที่ควรจะเฝ้าดูแลลูกสาวตัวน้อยของข้า!\n\n<พระราชาสะอื้น>\n\nตอนนี้นางหายไปแล้ว {name}!\n\nข้าสั่งคนให้พลิก Steppes ค้นทุกแห่ง เบาะแสเดียวที่มีคือนางอาจอยู่ใน Depths ป่านนี้นางอาจตายไปแล้วก็ได้!\n\nว่ากันว่า Kharan ถูกขังอยู่ที่นั่น... หาเขาให้พบ! ข้าต้องการคำตอบ!" },
        completion = { "23:1524237615:708710016", "ขอร้อง ให้ข้าอธิบายก่อน" },
    },
    [4342] = { -- Kharan's Tale
        title = { "13:814738115:424778242", "เรื่องเล่าของ Kharan" },
        objective = { "45:964868256:422698956", "ฟัง Kharan Mighthammer เล่าเรื่องราวของเขา" },
        description = { "45:1182975392:80457678", "ขอร้อง ฟังข้าให้จบก่อนตัดสิน!" },
        progress = { "36:847037143:254553111", "ขอให้ข้าเล่าเรื่องให้จบก่อน" },
        completion = { "52:1214014639:1560188216", "อย่างที่เห็น ข้าทำอะไรไม่ได้เลย" },
    },
    [4361] = { -- The Bearer of Bad News
        title = { "22:628495308:741670222", "ผู้แจ้งข่าวร้าย" },
        objective = { "71:1128836471:339782641", "กลับ Ironforge แล้วแจ้งข่าวร้ายให้ King Magni Bronzebeard ทราบ" },
        description = { "51:936029324:1340779426 N 26:812092546:470814812", "เจ้าต้องนำข้อมูลนี้กลับไปให้ King Magni {name} พระองค์จะรู้ว่าต้องทำอย่างไร!" },
        completion = { "42:1405039081:931695652", "<King Magni ทุบกำปั้นลงด้วยความโกรธ>" },
    },
    [4362] = { -- The Fate of the Kingdom
        title = { "23:229131295:2081039874", "ชะตากรรมแห่งอาณาจักร" },
        objective = { "117:1763571071:1320143993", "กลับไป Blackrock Depths แล้วช่วย Princess Moira Bronzebeard จากเงื้อมมือชั่วร้ายของ Emperor Dagran Thaurissan" },
        description = { "132:1664532638:700636901 N 147:1509360906:1078862707 N 137:193725945:1209859593", "ดูเหมือนศัตรูเก่าของข้า Dagran Thaurissan จะกุมชะตาทั้งข้าและอาณาจักร Ironforge ไว้แล้ว\n\nเจ้าอาจเป็นความหวังสุดท้าย {name} เจ้าต้องช่วย Moira ลูกสาวที่รักของข้า!\n\nมีทางเดียวที่จะทำให้แน่ใจว่าเวทที่ Thaurissan ร่ายใส่นางจะสลาย นั่นคือสังหารเขา\n\nและ {name} ห้ามทำร้ายนาง! จำไว้ว่านางถูก Thaurissan ควบคุม สิ่งที่นางทำหรือพูดล้วนเป็นผลจากเวทชั่วร้ายของเขา!" },
        completion = { "79:1123773221:995107611", "<องค์หญิง Bronzebeard ร้องไห้กับการสูญเสียจักรพรรดิ Dagran Thaurissan>\n\nทำไม???" },
        objectiveLabels = {
            monster = { ["Emperor Dagran Thaurissan slain"] = "ปราบ จักรพรรดิ Dagran Thaurissan" },
        },
    },
    [4363] = { -- The Princess's Surprise
        title = { "23:63255130:1340770039", "ข่าวไม่คาดคิดขององค์หญิง" },
        objective = { "58:254521521:1686840732", "กลับ Ironforge แล้วคุยกับ King Magni Bronzebeard" },
        description = { "354:586841698:100019238", "Thaurissan เป็นคนแคระที่ยิ่งใหญ่และมีเกียรติ เจ้าทำลายชีวิตข้าและลูกที่ยังไม่เกิด!\n\n<เจ้าคิดว่าองค์หญิง Bronzebeard อาจยังได้รับผลตกค้างจากเวทของจักรพรรดิ>\n\nกลับไป Ironforge แล้วบอกพ่อข้าว่า ทายาทแห่งอาณาจักร Ironforge จะเป็นคนแคระดาร์กไอรอน\n\nไม่ว่าพระองค์จะเห็นชอบหรือไม่ เรื่องก็จะเป็นเช่นนั้น" },
        completion = { "111:1635841582:961065202 N 154:509234669:1077097830", "<King Magni Bronzebeard ดูเสียพระทัยอย่างเห็นได้ชัด>\n\nดูเหมือนแม้ตายไปแล้ว Thaurissan ก็ยังชนะ\n\nเจ้าไปได้ {name} ก่อนจากไป จงเลือกรางวัลจากคลังหลวง\n\n<King Bronzebeard ทรุดลงบนบัลลังก์เพื่อครุ่นคิดถึงเหตุการณ์ที่พลิกผันอย่างประหลาด>" },
    },
    [7201] = { -- The Last Element
        title = { "16:1088110154:2000851402", "ธาตุสุดท้าย" },
        objective = { "202:2066834927:228508662", "เดินทางไป Blackrock Depths แล้วเก็บ Essence of the Elements 10 ชิ้น เจ้าคิดว่าจะเริ่มค้นจากโกเลมและผู้สร้างโกเลม และจำได้ว่า Vivian Lagrave พึมพำอะไรบางอย่างเกี่ยวกับเหล่าธาตุด้วย" },
        description = { "61:1289345932:306027675 N 439:1904444464:1003409032", "มีงานสำหรับผู้ที่เข้าไปใน Depths {name}\n\nดาร์กไอรอนเชี่ยวชาญการสร้างโกเลมที่ทรงพลังอย่างยิ่ง\n\nรายงานเบื้องต้นจากสายลับระบุว่าคนแคระใช้แหล่งพลังพิเศษ มอบอำนาจสังหารที่ไร้เทียมทานให้สิ่งสร้างของพวกมัน\n\nลองคิดดูว่าเราจะทำอะไรกับ Abomination ได้ หากได้ Essence of the Elements มา! จะพลิกทั้งเมืองก็ได้ แต่อย่ากลับมาจนกว่าจะพบแก่นพลัง ค่าจ้างจะคุ้มความเสี่ยง" },
        progress = { "16:319643476:2097524957", "เอามาให้ข้าดู!" },
        completion = { "148:753231226:1969201399", "วิเศษ! ข้าจะให้ผู้ส่งสารนำไป Undercity ทันที!\n\nส่วนเจ้า นี่ค่าจ้างตามสัญญา ไม่ต้องทอน เจ้าสัตว์โสโครก!" },
        required = { [11129] = { "23:89703305:1571491226", "แก่นพลังแห่งเหล่าธาตุ" } },
        objectiveLabels = {
            item = { ["Essence of the Elements"] = "แก่นพลังแห่งเหล่าธาตุ" },
        },
    },
    [7604] = { -- A Binding Contract
        title = { "18:1089630508:554907375", "สัญญาผูกพัน" },
        objective = { "118:371972728:503216103", "ส่ง Thorium Brotherhood Contract ให้ Lokhtos Darkbargainer หากต้องการรับแบบแปลน Sulfuron" },
        description = { { "449:1344355039:1945479354", "449:805281604:1008606855" }, "ผู้ลงนามขอรับรองว่า Sulfuron Ingot ที่นำส่งให้ Thorium Brotherhood (TB Ltd.) เป็นของแท้ มิใช่ของเลียนแบบ ผู้ลงนามยังรับทราบว่าอันตรายใด ๆ ที่เกิดแก่ตนอันเนื่องจากการพยายามประกอบ ตีขึ้น ค้นหา สร้าง ขาย หรือกิน Sulfuras ไม่อยู่ในความรับผิดชอบหรือเป็นความผิดของ TB Ltd.\n\nการลงนามในสัญญานี้หมายถึงเจ้ายอมรับเงื่อนไขทั้งหมดที่ระบุไว้\n\n_________________\n\nลายเซ็น" },
        progress = { "18:397811752:1287431657", "เราตกลงกันได้หรือไม่?" },
        completion = { "48:908381382:752727013 N 68:1997722153:837915994", "ยินดีที่ได้ทำธุรกิจกับเจ้า {name}!\n\nในนาม TB Ltd. ข้าขอให้เจ้าโชคดีในการตามหา Sulfuras!" },
        required = { [17203] = { "14:1652964226:1259038201", "แท่งซัลฟูรอน" } },
        objectiveLabels = {
            item = { ["Sulfuron Ingot"] = "แท่งซัลฟูรอน" },
        },
    },
    [8960] = { -- Bodley's Unfortunate Fate
        title = { "25:186559907:461927010", "ชะตาอาภัพของ Bodley" },
        objective = { "110:1025254565:1399219530", "เดินทางไป Blackrock Mountain แล้วใช้ Extra-Dimensional Ghost Revealer หา Bodley ใกล้ Blackrock Spire" },
        description = { "299:1054644298:858428630", "เราต้องเอาส่วนที่เหลือของเครื่องรางคืนมาสินะ? การหา Bodley คงชวนปวดหัวหน่อย เขากลับไป Blackrock Mountain เพื่อพยายามเข้า Blackrock Spire อีกครั้ง แล้วไม่กลับมาเลย\n\nข้าแนะนำให้เอาเครื่องเผยวิญญาณของก็อบลินไปด้วย เพราะกลัวว่าเรื่องร้ายที่สุดอาจเกิดขึ้นแล้ว" },
        completion = { "80:1057837480:603827214 N 334:1179509420:1956806943", "ข้าดีใจมากที่เจ้ามองเห็น ในที่สุดก็มีคนให้คุยด้วย!\n\nเจ้าจะช่วยเราหรือไม่ {name}? ช่วยแก้ความผิดที่เราเคยก่อให้สิ่งต่าง ๆ กลับถูกต้อง? หากเจ้ามี Top Piece of Lord Valthalak's Amulet แล้วจริง ข้าคงชี้ทางให้ไปหาอีกสองส่วน นำมารวมกัน แล้วจบเรื่องทั้งหมดนี้ได้\n\nอ้อ จริงสิ สวัสดี ข้าชื่อ Bodley ยินดีที่ได้รู้จัก!" },
    },
    [8961] = { -- Three Kings of Flame
        title = { "20:875797094:1287788882", "สามราชาแห่งเปลวไฟ" },
        objective = { "170:540233557:1918076084", "รวบรวม Incendicite of Incendius, Ember of Emberseer, Cinder of Cynders และ Hallowed Brazier แล้วนำกลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "504:929826929:628300304", "หากจะเรียก Lord Valthalak ก่อนอื่นเราต้องรวบรวมเครื่องรางอีกสองในสามส่วนที่เหลือ การจะทำเช่นนั้นต้องมีกระถางไฟและถ่านพิเศษสำหรับเผา\n\nจ้าวแห่งไฟสามตนมีสิ่งที่เราต้องการ ได้แก่ Lord Incendius ใน Blackrock Depths, Pyroguard Emberseer ใน Blackrock Spire และ The Duke of Cynders ใน Silithus เก็บชิ้นส่วนซากจากแต่ละตน แล้วกลับมาพร้อม Hallowed Brazier ซึ่งซื้อจาก Argent Dawn ได้เมื่อมีชื่อเสียงกับพวกเขาระดับ Honored" },
        progress = { "356:727761632:13363667 N 89:1888704891:1304710789", "เป็นความโง่ของเรา... เป็นชะตาหายนะที่รับงานสุดท้ายนั้น หากเราไม่ได้ขโมยวิญญาณ Lord Valthalak ซึ่งบรรจุในเครื่องรางไปโดยไม่ตั้งใจ หากคนในกลุ่มทหารรับจ้างไม่โลภจนแบ่งมันกัน ข้าก็คงยังมีชีวิต อาจกำลังยกเบียร์ดื่ม หรืออุ้มลูกคนใดคนหนึ่งโยนเล่นในอากาศ\n\n{name} อย่าให้ความโลภของคนไร้เกียรติในกองทหารรับจ้างเก่าของเรากลายเป็นหายนะของเจ้าด้วย" },
        completion = { "15:606303062:1160220795 C 242:1550472489:2141712726", "ข้าประทับใจ {class} แต่เราไม่มีเวลาให้เสีย ข้าจะมอบงานต่อไป เพราะยังต้องหาส่วนประกอบสำคัญอีกเล็กน้อยก่อนดำเนินการต่อ\n\nคุยกับข้าอีกครั้งเมื่อรู้สึกว่าพร้อมรับความท้าทายเบื้องหน้าแล้ว" },
        required = { [21987] = { "24:2053671760:380993883", "แร่อินเซนดิไซต์ของอินเซนเดียส" }, [21988] = { "18:2016083544:1574740660", "ถ่านคุของเอ็มเบอร์เซียร์" }, [21989] = { "17:1640101687:333108069", "เถ้าถ่านของซินเดอร์ส" }, [22014] = { "16:524720583:1358857468", "กระถางไฟศักดิ์สิทธิ์" } },
        objectiveLabels = {
            item = { ["Incendicite of Incendius"] = "แร่อินเซนดิไซต์ของอินเซนเดียส", ["Ember of Emberseer"] = "ถ่านคุของเอ็มเบอร์เซียร์", ["Cinder of Cynders"] = "เถ้าถ่านของซินเดอร์ส", ["Hallowed Brazier"] = "กระถางไฟศักดิ์สิทธิ์" },
        },
    },
    [8962] = { -- Components of Importance
        title = { "24:32380735:1037405587", "ส่วนประกอบสำคัญ" },
        objective = { "78:505246936:1415214741", "หา Druidical Remains แล้วนำกลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "C 494:1868990027:2079531645", "{class} ฟังให้ดี ตอนนี้เรามีกระถางไฟและสิ่งที่จะจุดมันแล้ว แต่ยังต้องมีส่วนประกอบอีกอย่างสำหรับเติมพลัง สิ่งที่จะเป็นสื่อรวมพลังได้มากพอล่อวิญญาณสหายเก่าที่ล่วงลับของข้า\n\nMor Grayhoof ดรูอิดคนสำคัญที่สุดของเรา มีเพื่อนสนิทหลายคนใน Cenarion Circle บางคนตายเพราะซิลิธิด ข้าต้องการให้เจ้านำ Druidical Remains มาจากซิลิธิดที่อยู่รอบ Hive'Regal ทางตะวันออกเฉียงใต้ของ Silithus" },
        progress = { "32:2136956107:273784060 C 37:2066262811:876630285", "เจ้ากลับมาพร้อมสิ่งที่ข้าส่งไปหาแล้วหรือ {class}?" },
        completion = { "17:2049170433:170140679 N 340:1693982167:77797519", "ทำได้ดี {name} ข้าจะใส่แก่นพลังของซากเหล่านี้ลงในกระถางไฟ\n\nจากนี้เพียงไปยังส่วนล่างของ Blackrock Spire ที่ห้องของ War Master Voone ใน Tazz'Alaor แล้วใช้กระถางไฟเรียกวิญญาณแปดเปื้อนของ Mor Grayhoof สหายเก่าข้า เขาจะพักสงบไม่ได้จนกว่าเจ้าจะเอาชิ้นส่วนเครื่องรางไปจากเขา" },
        required = { [22226] = { "17:1912951577:1779874780", "ซากของดรูอิด" } },
        objectiveLabels = {
            item = { ["Druidical Remains"] = "ซากของดรูอิด" },
        },
    },
    [8963] = { -- Components of Importance
        title = { "24:32380735:1037405587", "ส่วนประกอบสำคัญ" },
        objective = { "85:163804240:1970685150", "หา Starbreeze Village Relic แล้วนำกลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "C 480:951716722:754194738", "{class} ฟังให้ดี ตอนนี้เรามีกระถางไฟและสิ่งที่จะจุดมันแล้ว แต่ยังต้องมีส่วนประกอบอีกอย่างสำหรับเติมพลัง สิ่งที่จะเป็นสื่อรวมพลังได้มากพอล่อวิญญาณสหายเก่าที่ล่วงลับของข้า\n\nIsalien นักบวชหญิงของเรา เติบโตที่ Starbreeze Village ใน Winterspring ข้าต้องการให้เจ้าเก็บ Starbreeze Village Relic จากยักษ์ Frostmaul ใน Frostwhisper Gorge ทางใต้ของ Winterspring พวกมันขึ้นไปปล้นทางเหนือเป็นครั้งคราว" },
        progress = { "32:2136956107:273784060 C 37:2066262811:876630285", "เจ้ากลับมาพร้อมสิ่งที่ข้าส่งไปหาแล้วหรือ {class}?" },
        completion = { "17:2049170433:170140679 N 346:1099379605:1712799794", "ทำได้ดี {name} ข้าจะใส่แก่นพลังของวัตถุโบราณลงในกระถางไฟ\n\nจากนี้เพียงไป Shrine of Eldretharr ในปีกตะวันออกของ Dire Maul แล้วใช้กระถางไฟเรียกวิญญาณ Isalien สหายเก่าข้า วิญญาณนางแปดเปื้อนเพราะครอบครองชิ้นส่วนเครื่องรางของ Valthalak และเศษวิญญาณของเขาที่อยู่ภายใน" },
        required = { [22227] = { "24:339067847:490469461", "โบราณวัตถุจาก Starbreeze Village" } },
        objectiveLabels = {
            item = { ["Starbreeze Village Relic"] = "โบราณวัตถุจาก Starbreeze Village" },
        },
    },
    [8964] = { -- Components of Importance
        title = { "24:32380735:1037405587", "ส่วนประกอบสำคัญ" },
        objective = { "89:1366745277:1566384848", "นำ Brilliant Sword of Zealotry กลับมาให้ Bodley ภายใน Blackrock Mountain" },
        description = { "C 483:1525061100:1471329043", "{class} ฟังให้ดี ตอนนี้เรามีกระถางไฟและสิ่งที่จะจุดมันแล้ว แต่ยังต้องมีส่วนประกอบอีกอย่างสำหรับเติมพลัง สิ่งที่จะเป็นสื่อรวมพลังได้มากพอเรียกซากสหายเก่าที่ล่วงลับของข้า\n\nสองพี่น้อง Jarien กับ Sothos ศรัทธาในวิถี Scarlet Crusade และปรารถนาจะเป็นอัศวินในองค์กรชั่วนั้น ไป Tyr's Hand ใน Eastern Plaguelands แล้วนำ Brilliant Sword of Zealotry มาจากพวก Praetorian ที่นั่น" },
        progress = { "32:2136956107:273784060 C 37:2066262811:876630285", "เจ้ากลับมาพร้อมสิ่งที่ข้าส่งไปหาแล้วหรือ {class}?" },
        completion = { "17:2049170433:170140679 N 352:1132247427:1467743544", "ทำได้ดี {name} ข้าจะใส่แก่นพลังของดาบลงในกระถางไฟ\n\nจากนี้เพียงเข้าไป The Crimson Throne ภายใน The Scarlet Bastion ที่ Stratholme แล้วใช้กระถางไฟเรียกซากของ Jarien กับ Sothos สหายเก่าข้า วิญญาณของพวกเขาบิดเบือนยิ่งขึ้นเพราะครอบครองชิ้นส่วนเครื่องรางของ Valthalak และวิญญาณของเขาที่อยู่ภายใน" },
        required = { [22228] = { "27:1726613691:1184990399", "ดาบเรืองรองแห่งความศรัทธาแรงกล้า" } },
        objectiveLabels = {
            item = { ["Brilliant Sword of Zealotry"] = "ดาบเรืองรองแห่งความศรัทธาแรงกล้า" },
        },
    },
    [8965] = { -- Components of Importance
        title = { "24:32380735:1037405587", "ส่วนประกอบสำคัญ" },
        objective = { "86:1719510836:696359267", "หา Soul Ashes of the Banished แล้วนำกลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "C 481:393458495:1708098212", "{class} ฟังให้ดี ตอนนี้เรามีกระถางไฟและสิ่งที่จะจุดมันแล้ว แต่ยังต้องมีส่วนประกอบอีกอย่างสำหรับเติมพลัง สิ่งที่จะเป็นสื่อรวมพลังได้มากพอล่อวิญญาณสหายเก่าที่ล่วงลับของข้า\n\nKormok โอเกอร์ผู้ใช้ศาสตร์ปลุกศพที่ร่วมทางกับเรา ชื่นชอบการเรียกวิญญาณผู้ตายที่ถูกเนรเทศแห่ง Purgation Isle นอกชายฝั่งใต้ของ Hillsbrad Foothills จงไปที่นั่นแล้วเก็บ Soul Ashes of the Banished จากซากของพวกเขา" },
        progress = { "32:2136956107:273784060 C 37:2066262811:876630285", "เจ้ากลับมาพร้อมสิ่งที่ข้าส่งไปหาแล้วหรือ {class}?" },
        completion = { "17:2049170433:170140679 N 352:534473422:1432388379", "ทำได้ดี {name} ข้าจะใส่แก่นพลังของเถ้าลงในกระถางไฟ\n\nจากนี้เพียงเข้า Scholomance ไปยังห้องของ Ras Frostwhisper แล้วใช้กระถางไฟเรียกวิญญาณ Kormok สหายเก่าข้า ชิ้นส่วนเครื่องรางกับวิญญาณ Valthalak ภายในทำให้เขาแปดเปื้อนยิ่งขึ้น และเขาจะพักสงบไม่ได้จนกว่าเจ้าจะชิงมันมา" },
        required = { [22229] = { "26:1617132057:753613235", "เถ้าวิญญาณของผู้ถูกเนรเทศ" } },
        objectiveLabels = {
            item = { ["Soul Ashes of the Banished"] = "เถ้าวิญญาณของผู้ถูกเนรเทศ" },
        },
    },
    [8985] = { -- More Components of Importance
        title = { "29:1295498460:267082145", "ส่วนประกอบสำคัญเพิ่มเติม" },
        objective = { "85:163804240:1970685150", "หา Starbreeze Village Relic แล้วนำกลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "C 488:393184495:1271954617", "{class} ฟังให้ดี ตอนนี้เรารู้ที่อยู่ของเครื่องรางชิ้นสุดท้ายแล้ว แต่ยังต้องมีส่วนประกอบอีกอย่างสำหรับเติมพลังให้กระถางไฟ สิ่งที่จะเป็นสื่อรวมพลังได้มากพอล่อวิญญาณสหายเก่าที่ล่วงลับของข้า\n\nIsalien นักบวชหญิงของเรา เติบโตที่ Starbreeze Village ใน Winterspring ข้าต้องการให้เจ้าเก็บ Starbreeze Village Relic จากยักษ์ Frostmaul ใน Frostwhisper Gorge ทางใต้ของ Winterspring พวกมันขึ้นไปปล้นทางเหนือเป็นครั้งคราว" },
        progress = { "32:2136956107:273784060 C 37:2066262811:876630285", "เจ้ากลับมาพร้อมสิ่งที่ข้าส่งไปหาแล้วหรือ {class}?" },
        completion = { "17:2049170433:170140679 N 478:2069905495:168139411", "ทำได้ดี {name} ข้าจะใส่แก่นพลังของวัตถุโบราณลงในกระถางไฟ\n\nจากนี้เพียงไป Shrine of Eldretharr ในปีกตะวันออกของ Dire Maul แล้วใช้กระถางไฟเรียกวิญญาณ Isalien สหายเก่าข้า วิญญาณนางแปดเปื้อนเพราะครอบครองชิ้นส่วนเครื่องรางของ Valthalak และเศษวิญญาณของเขาที่อยู่ภายใน\n\nอ้อ ข้ามี Bloodkelp เหลือจากที่เจ้าไป Alcaz Isle จึงนำมาทำยาให้ เลือกได้เลย!" },
        required = { [22227] = { "24:339067847:490469461", "โบราณวัตถุจาก Starbreeze Village" } },
        objectiveLabels = {
            item = { ["Starbreeze Village Relic"] = "โบราณวัตถุจาก Starbreeze Village" },
        },
    },
    [8986] = { -- More Components of Importance
        title = { "29:1295498460:267082145", "ส่วนประกอบสำคัญเพิ่มเติม" },
        objective = { "78:505246936:1415214741", "หา Druidical Remains แล้วนำกลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "C 502:1658721408:237871760", "{class} ฟังให้ดี ตอนนี้เรารู้ที่อยู่ของเครื่องรางชิ้นสุดท้ายแล้ว แต่ยังต้องมีส่วนประกอบอีกอย่างสำหรับเติมพลังให้กระถางไฟ สิ่งที่จะเป็นสื่อรวมพลังได้มากพอล่อวิญญาณสหายเก่าที่ล่วงลับของข้า\n\nMor Grayhoof ดรูอิดคนสำคัญที่สุดของเรา มีเพื่อนสนิทหลายคนใน Cenarion Circle บางคนตายเพราะซิลิธิด ข้าต้องการให้เจ้านำ Druidical Remains มาจากซิลิธิดที่อยู่รอบ Hive'Regal ทางตะวันออกเฉียงใต้ของ Silithus" },
        progress = { "32:2136956107:273784060 C 37:2066262811:876630285", "เจ้ากลับมาพร้อมสิ่งที่ข้าส่งไปหาแล้วหรือ {class}?" },
        completion = { "17:2049170433:170140679 N 472:119158901:1267561241", "ทำได้ดี {name} ข้าจะใส่แก่นพลังของซากเหล่านี้ลงในกระถางไฟ\n\nจากนี้เพียงไปยังส่วนล่างของ Blackrock Spire ที่ห้องของ War Master Voone ใน Tazz'Alaor แล้วใช้กระถางไฟเรียกวิญญาณแปดเปื้อนของ Mor Grayhoof สหายเก่าข้า เขาจะพักสงบไม่ได้จนกว่าเจ้าจะเอาชิ้นส่วนเครื่องรางไปจากเขา\n\nอ้อ ข้ามี Bloodkelp เหลือจากที่เจ้าไป Alcaz Isle จึงนำมาทำยาให้ เลือกได้เลย!" },
        required = { [22226] = { "17:1912951577:1779874780", "ซากของดรูอิด" } },
        objectiveLabels = {
            item = { ["Druidical Remains"] = "ซากของดรูอิด" },
        },
    },
    [8987] = { -- More Components of Importance
        title = { "29:1295498460:267082145", "ส่วนประกอบสำคัญเพิ่มเติม" },
        objective = { "89:1366745277:1566384848", "นำ Brilliant Sword of Zealotry กลับมาให้ Bodley ภายใน Blackrock Mountain" },
        description = { "C 491:1128016085:161330339", "{class} ฟังให้ดี ตอนนี้เรารู้ที่อยู่ของเครื่องรางชิ้นสุดท้ายแล้ว แต่ยังต้องมีส่วนประกอบอีกอย่างสำหรับเติมพลังให้กระถางไฟ สิ่งที่จะเป็นสื่อรวมพลังได้มากพอเรียกซากสหายเก่าที่ล่วงลับของข้า\n\nสองพี่น้อง Jarien กับ Sothos ศรัทธาในวิถี Scarlet Crusade และปรารถนาจะเป็นอัศวินในองค์กรชั่วนั้น ไป Tyr's Hand ใน Eastern Plaguelands แล้วนำ Brilliant Sword of Zealotry มาจากพวก Praetorian ที่นั่น" },
        progress = { "32:2136956107:273784060 C 37:2066262811:876630285", "เจ้ากลับมาพร้อมสิ่งที่ข้าส่งไปหาแล้วหรือ {class}?" },
        completion = { "17:2049170433:170140679 N 484:777592085:1687867958", "ทำได้ดี {name} ข้าจะใส่แก่นพลังของดาบลงในกระถางไฟ\n\nจากนี้เพียงเข้าไป The Crimson Throne ภายใน The Scarlet Bastion ที่ Stratholme แล้วใช้กระถางไฟเรียกซากของ Jarien กับ Sothos สหายเก่าข้า วิญญาณของพวกเขาบิดเบือนยิ่งขึ้นเพราะครอบครองชิ้นส่วนเครื่องรางของ Valthalak และวิญญาณของเขาที่อยู่ภายใน\n\nอ้อ ข้ามี Bloodkelp เหลือจากที่เจ้าไป Alcaz Isle จึงนำมาทำยาให้ เลือกได้เลย!" },
        required = { [22228] = { "27:1726613691:1184990399", "ดาบเรืองรองแห่งความศรัทธาแรงกล้า" } },
        objectiveLabels = {
            item = { ["Brilliant Sword of Zealotry"] = "ดาบเรืองรองแห่งความศรัทธาแรงกล้า" },
        },
    },
    [8988] = { -- More Components of Importance
        title = { "29:1295498460:267082145", "ส่วนประกอบสำคัญเพิ่มเติม" },
        objective = { "86:1719510836:696359267", "หา Soul Ashes of the Banished แล้วนำกลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "C 489:732080505:815166233", "{class} ฟังให้ดี ตอนนี้เรารู้ที่อยู่ของเครื่องรางชิ้นสุดท้ายแล้ว แต่ยังต้องมีส่วนประกอบอีกอย่างสำหรับเติมพลังให้กระถางไฟ สิ่งที่จะเป็นสื่อรวมพลังได้มากพอล่อวิญญาณสหายเก่าที่ล่วงลับของข้า\n\nKormok โอเกอร์ผู้ใช้ศาสตร์ปลุกศพที่ร่วมทางกับเรา ชื่นชอบการเรียกวิญญาณผู้ตายที่ถูกเนรเทศแห่ง Purgation Isle นอกชายฝั่งใต้ของ Hillsbrad Foothills จงไปที่นั่นแล้วเก็บ Soul Ashes of the Banished จากซากของพวกเขา" },
        progress = { "32:2136956107:273784060 C 37:2066262811:876630285", "เจ้ากลับมาพร้อมสิ่งที่ข้าส่งไปหาแล้วหรือ {class}?" },
        completion = { "17:2049170433:170140679 N 484:882062218:940675798", "ทำได้ดี {name} ข้าจะใส่แก่นพลังของเถ้าลงในกระถางไฟ\n\nจากนี้เพียงเข้า Scholomance ไปยังห้องของ Ras Frostwhisper แล้วใช้กระถางไฟเรียกวิญญาณ Kormok สหายเก่าข้า ชิ้นส่วนเครื่องรางกับวิญญาณ Valthalak ภายในทำให้เขาแปดเปื้อนยิ่งขึ้น และเขาจะพักสงบไม่ได้จนกว่าเจ้าจะชิงมันมา\n\nอ้อ ข้ามี Bloodkelp เหลือจากที่เจ้าไป Alcaz Isle จึงนำมาทำยาให้ เลือกได้เลย!" },
        required = { [22229] = { "26:1617132057:753613235", "เถ้าวิญญาณของผู้ถูกเนรเทศ" } },
        objectiveLabels = {
            item = { ["Soul Ashes of the Banished"] = "เถ้าวิญญาณของผู้ถูกเนรเทศ" },
        },
    },
    [8994] = { -- Final Preparations
        title = { "18:1108621819:1687332937", "เตรียมการขั้นสุดท้าย" },
        objective = { "114:1608090952:1264466848", "รวบรวม Blackrock Bracer 40 ชิ้นและหา Flask of Supreme Power แล้วนำกลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "20:1385054232:1068613487 C 456:862091432:1083342055 N 1:33:33", "เราเกือบถึงแล้ว {class} เหลือเพียงส่วนประกอบอีกเล็กน้อยให้ข้าปรับกระถางไฟจนเรียก Lord Valthalak ได้\n\nก่อนอื่นข้าต้องขอให้เจ้าเข้า Blackrock Spire แล้วสังหารออร์คข้างใน พวกมันสวมปลอกรัดแขนที่มีโลหะซึ่งข้าต้องการอยู่เล็กน้อย จึงต้องใช้หลายชิ้นเพื่อสกัดให้ได้ปริมาณที่พอ จากนั้นนำ Flask of Supreme Power มาให้ข้า เพื่อเติมพลังให้กระบวนการเสร็จสมบูรณ์\n\nโชคดี {name}!" },
        progress = { "23:1678071704:483825909 N 235:1147455333:641748915", "เรามาไกลแล้ว {name} ข้าเพียงอยากบอกว่าไม่ว่าจะเกิดอะไรขึ้น ขอบใจ! เจ้าเสี่ยงชีวิตเพื่อช่วยสมาชิกที่ยังรอดของกองทหารรับจ้าง The Veiled Blade ของเรา สำหรับข้า ตอนนี้เจ้าคือพวกเดียวกับเราแล้ว" },
        completion = { "238:457222753:261015448 N 44:849062978:284115153", "เท่านี้ก็ครบ ข้าจะสกัดโลหะจากปลอกรัดแขน แล้วเติมพลังให้กระถางไฟด้วยส่วนประกอบสุดท้ายเหล่านี้ จากนั้นมันจะพร้อมให้เจ้าเรียก Lord Valthalak และคืนเครื่องรางวิญญาณให้เขาเสียที\n\nเจ้ามาไกลมากแล้ว {name} อย่าสะดุดตอนที่มองเห็นจุดจบอยู่ตรงหน้า!" },
        required = { [22138] = { "16:1554661467:1499102746", "ปลอกแขนแบล็กร็อก" }, [13512] = { "22:901279055:1850197730", "ยาพลังสูงสุด" } },
        objectiveLabels = {
            item = { ["Blackrock Bracer"] = "ปลอกแขนแบล็กร็อก", ["Flask of Supreme Power"] = "ยาพลังสูงสุด" },
        },
    },
    [8996] = { -- Return to Bodley
        title = { "16:879504506:692192739", "กลับไปหา Bodley" },
        objective = { "81:1541186634:376745647", "กลับไปหา Bodley ภายใน Blackrock Mountain แล้วส่ง Brazier of Beckoning ให้เขา" },
        description = { "43:1747458165:1691766242 C 127:487509567:226577843 R 213:1458761065:1364237086", "ครั้งนี้ข้าจะมองข้ามความโอหังของเจ้า {class} เพราะวันนี้เจ้าทำสิ่งมีเกียรติ คืนส่วนที่เหลือของวิญญาณที่ถูกขโมยไปให้ข้า แม้ธรรมชาติของเจ้าจะอ่อนแออย่างเห็นได้ชัด ชาว{race} แต่เจ้ากลับกล้าในสิ่งที่ผู้ขโมยของข้าไม่กล้า และคงไม่มีวันกล้า!\n\nกลับไปหาพวกเขา ก่อนข้าเปลี่ยนใจฆ่าเจ้าตรงนี้ กลับไปบอกว่าพวกเขาปลอดภัยแล้ว... สำหรับตอนนี้" },
        progress = { "N 113:1346045658:694131536", "{name} เจ้ากลับมาและยังมีชีวิต! อย่างน้อยในพวกเราก็ยังมีอยู่คนหนึ่ง\n\nเจ้าต้องเล่าให้ข้าฟังทั้งหมดเลย!" },
        completion = { "210:532193432:170186123 N 283:40575706:84790120", "เขาพูดเช่นนั้นจริงหรือ? ว้าว ไม่อยากเชื่อว่าเขาจะเรียกนักฆ่าและผู้ล่าวิญญาณกลับ แม้จะแย้มว่าจะทำร้ายสหายที่ยังมีชีวิตของข้าอีกในอนาคตก็ตาม\n\nวันนี้เป็นวันยิ่งใหญ่ {name}! เจ้าทำสิ่งที่น้อยคนจะทำได้ และช่วยชำระบาปในอดีตให้เรา อย่างน้อยก็บางส่วน\n\nขอบใจ! ข้าอยากให้สิ่งนี้แทนความซาบซึ้ง เจ้าจะใช้เรียกวิญญาณได้ตามสถานที่ผีสิงเดิมที่เคยไป และอีกไม่กี่แห่งด้วย" },
        required = { [22056] = { "20:549784120:1675170794", "กระถางไฟเรียกขาน" } },
        objectiveLabels = {
            item = { ["Brazier of Beckoning"] = "กระถางไฟเรียกขาน" },
        },
    },
    [9015] = { -- The Challenge
        title = { "13:923856000:222712702", "คำท้าประลอง" },
        objective = { "285:310746448:1474395805", "เดินทางไป Ring of the Law ใน Blackrock Depths แล้ววาง Banner of Provocation ตรงกลางขณะที่ High Justice Grimstone ตัดสินโทษเจ้า สังหาร Theldren กับเหล่านักสู้ แล้วนำเครื่องราง Lord Valthalak ชิ้นแรกกลับไปให้ Anthion Harmon ที่ Eastern Plaguelands" },
        description = { "14:1507824617:323984842 N 400:1232709320:1072136915", "ฟังให้ดี {name} หากจะให้ธงทำงานตามต้องการ เจ้าต้องเข้า Ring of the Law ใน Blackrock Depths ยอมให้ High Justice Grimstone ตัดสินโทษ แล้วปักธงลงบนพื้นให้มั่นเพื่อแสดงการท้าทาย\n\nเป้าหมายของเจ้าจะอดใจไม่ได้ และเข้าร่วมการต่อสู้ด้วยความกระหายอยากสู้กับเจ้า เมื่อได้สิ่งที่ตามหาแล้ว จงกลับไปหา Anthion" },
        progress = { "13:1761969110:399778402 N 1:33:33", "เจ้ากลับมาแล้ว {name}!" },
        completion = { "40:1582721763:371355210 N 1:63:63", "เจ้าเอาชิ้นส่วนเครื่องรางคืนมาได้แล้วหรือ {name}?" },
        required = { [22047] = { "36:555940444:1498556492", "ชิ้นส่วนบนของเครื่องรางลอร์ดวัลธาลัก" } },
        objectiveLabels = {
            item = { ["Top Piece of Lord Valthalak's Amulet"] = "ชิ้นส่วนบนของเครื่องรางลอร์ดวัลธาลัก" },
        },
    },
    [9032] = { -- Bodley's Unfortunate Fate
        title = { "25:186559907:461927010", "ชะตาอาภัพของ Bodley" },
        objective = { "110:1025254565:1399219530", "เดินทางไป Blackrock Mountain แล้วใช้ Extra-Dimensional Ghost Revealer หา Bodley ใกล้ Blackrock Spire" },
        description = { "397:1481754901:1414159057", "เครื่องรางบรรจุวิญญาณ Valthalak อยู่หรือ? ไม่แปลกเลยที่มีคำสาปทรงพลังคุ้มครอง\n\nการหา Bodley คงมีปัญหาหน่อย ครั้งสุดท้ายที่ได้ข่าว เขาเตรียมกลับไป Blackrock Spire แล้วไม่มีใครได้ข่าวอีกเลย\n\nตามหาเขาที่ Blackrock Mountain เถิด แม้ข้าจะเกรงว่าตอนนี้เขาคงตายแล้ว ข้าแนะนำให้เอาเครื่องของก็อบลินไปด้วย สหาย" },
        completion = { "80:1057837480:603827214 N 332:1912957682:898497361", "ข้าดีใจมากที่เจ้ามองเห็น ในที่สุดก็มีคนให้คุยด้วย!\n\nเจ้าจะช่วยเราหรือไม่ {name}? ช่วยแก้ความผิดที่เราเคยก่อให้สิ่งต่าง ๆ กลับถูกต้อง? หากเจ้ามี Top Piece of Lord Valthalak's Amulet แล้วจริง ข้าคงชี้ทางให้ไปหาอีกสองส่วน นำมารวมกัน แล้วจบเรื่องทั้งหมดนี้ได้\n\nอ้อ จริงสิ สวัสดี ข้าชื่อ Bodley ยินดีที่ได้รู้จัก!" },
    },
    [4701] = { -- Put Her Down
        title = { "12:1660962500:183491920", "ปลิดชีพนาง" },
        objective = { "171:1567883273:2100996350", "เดินทางไป Blackrock Spire แล้วทำลายต้นตอภัยจากวอร์ก ตอนเจ้าจากมา Helendis ตะโกนชื่อ Halycon ซึ่งเป็นชื่อที่ออร์คใช้เรียกเกี่ยวกับวอร์ก" },
        description = { "394:2129008616:1886911443 N 29:2137568905:571148760", "เจ้าคงเคยเห็นวอร์กที่ออร์ค Blackrock ควบคุม\n\nน่าแปลก ไม่ว่าเราจะกำจัดมากเท่าไร จำนวนก็ไม่ลด หน่วยสอดแนมรายงานว่าพวกมันถูกเพาะพันธุ์ ฝึก และส่งออกจาก Blackrock Spire เมืองหลวงของออร์ค Blackrock เจ้าต้องไปค้นหาต้นตอภัยนี้ ค้นหา... แล้วทำลาย\n\nโชคดี {name} ขอ Cenarius คุ้มครองเจ้า..." },
        progress = { "65:24119298:572888070", "เจ้าพบและจัดการต้นตอภัยจากวอร์กแล้วหรือยัง?" },
        completion = { "33:1381854680:471525829 N 120:194938410:290917761", "อย่ามัวคิดถึงความทุกข์ของนาง {name} สัตว์ตนนั้นแปดเปื้อน เป็นผลจากเวทมืด เจ้าทำประโยชน์ยิ่งใหญ่ให้ Alliance และจะได้รับรางวัล" },
        objectiveLabels = {
            monster = { ["Halycon slain"] = "ปราบ Halycon" },
        },
    },
    [4724] = { -- The Pack Mistress
        title = { "17:811281828:1176356392", "จ่าฝูงวอร์ก" },
        objective = { "49:1180804231:558205009", "สังหาร Halycon จ่าฝูงวอร์ก Bloodaxe" },
        description = { "485:1951355528:1322741489 N 18:384507026:1575684809", "บางคนว่าวอร์กที่ออร์ค Blackrock ควบคุมเป็นสิ่งสร้างจากพลังเหนือธรรมชาติ บางคนว่ามันไม่ใช่วอร์กแท้ แต่เป็นสุนัขปีศาจที่ Pit Lord ผู้ตกต่ำมอบให้ออร์ค\n\nความจริงซับซ้อนน้อยกว่านั้น แต่น่ากลัวไม่แพ้กัน วอร์กแห่ง Blackrock มาจาก Halycon และคู่ของนาง Halycon คือแม่พันธุ์วอร์กขนาดยักษ์ ส่วนคู่ของนางหรือ? ยังไม่มีใครรอดมาเล่าเรื่องตนนั้นได้\n\nจงโจมตีหัวใจของฝูง ทำลาย Halycon... และ {name} ระวังข้างหลังด้วย" },
        progress = { "133:414819127:811725979", "เมื่อจ่าฝูงตาย เราจะเริ่มลดจำนวนวอร์กยามของ Spire แล้วค่อยรุกเข้าเมืองได้" },
        completion = { "99:1213982822:996926755", "ลูกวอร์กคลั่ง? Gizrul the Slavener? แล้วเจ้ายังรอดมาเล่าได้หรือ?! เหลือเชื่อ! เจ้าคู่ควรกับรางวัลจริง ๆ!" },
        objectiveLabels = {
            monster = { ["Halycon slain"] = "ปราบ Halycon" },
        },
    },
    [4729] = { -- Kibler's Exotic Pets
        title = { "20:774768653:468932008", "สัตว์เลี้ยงหายากของ Kibler" },
        objective = { "144:746781722:401262337", "เดินทางไป Blackrock Spire แล้วหา Bloodaxe Worg Pup ใช้กรงนำสัตว์ตัวน้อยดุร้ายกลับมา ส่ง Caged Worg Pup ให้ Kibler" },
        description = { "446:666192964:787583566", "เจ้าคงสงสัยว่าข้าทำอะไรอยู่ที่นี่ ดูกรงพวกนี้สิ! ยังไม่ชัดอีกหรือ?\n\nเหนือสิ่งอื่นใด ข้ารักสัตว์ แต่ค้าขายเป็นอาชีพ ข้าตามหาสัตว์หายากให้คนรวยและคนดัง แล้วฝึกให้เชื่องเหมาะเป็นสัตว์เลี้ยง\n\nทีนี้เจ้าคงสงสัยว่า “มีอะไรให้ข้าช่วย Kibler?” คำตอบง่ายมาก เอากรงนี้ไปหาลูกวอร์กมาให้ข้า แล้วข้าจะฝึกวอร์กให้เจ้าตัวหนึ่ง!" },
        progress = { "35:494003571:1364873327", "<Kibler ง่วนกับการโต้เถียงกับ Opus>" },
        completion = { "33:1874986128:1517642705 N 113:821272108:1465393655", "เจ้าจับมาได้ถูกเวลา {name} ช้ากว่านี้คงฝึกไม่ได้แล้ว! ขอเวลาสักครู่ ข้าจะเตรียมเจ้าตัวน้อยให้พร้อมกลับบ้านกับเจ้า" },
        required = { [12263] = { "14:964511934:290407588", "ลูกวอร์กในกรง" } },
        steps = { { "14:964511934:290407588", "ลูกวอร์กในกรง" } },
    },
    [4734] = { -- Egg Freezing
        title = { "12:1543261023:816628596", "แช่แข็งไข่" },
        objective = { "58:753673602:2049927136", "ใช้ Eggscilloscope Prototype กับไข่ใน Rookery" },
        description = { "N 482:211229069:224254124", "{name} ข้าทุ่มเทสร้างเครื่องใหม่ Eggscilloscope! มันยิงพลังความเย็นใส่ไข่มังกรดำ... จนแข็งเป็นน้ำแข็ง! เจ้าช่วยทดสอบให้ได้ไหม?\n\nข้าได้ยินว่าบน Blackrock Spire พวกมังกรมี Rookery สำหรับฟักไข่ เจ้าต้องไปทดสอบเครื่องที่นั่น แล้วกลับมาบอกผล!\n\nไม่ต้องห่วง ไข่มังกรที่แช่แข็งแล้วน่าจะไม่มีอันตราย ที่ต้องระวังคือไข่ที่ยังไม่แข็งต่างหาก!" },
        progress = { "N 34:1433110387:556812427", "{name} เจ้าทดสอบ Eggscilloscope แล้วหรือยัง?" },
        completion = { "208:1800771714:1998135289", "ได้ผลหรือ? วิเศษ! ข้ารู้อยู่แล้วว่าต้องได้ผล!\n\nระหว่างเจ้าไม่อยู่ ข้าทำ Eggscilloscope รุ่นใหม่ รุ่นนี้ยิงได้ไกลกว่าเดิมมาก\n\nนี่ เอาไปสักเครื่อง เผื่อเจ้ากลับไป Blackrock Spire" },
    },
    [4735] = { -- Egg Collection
        title = { "14:471460964:321355369", "เก็บไข่" },
        objective = { "116:1772134027:838033771", "นำ Collected Dragon Egg 8 ฟองและ Collectronic Module ไปให้ Tinkee Steamboil ที่ Flame Crest ใน Burning Steppes" },
        description = { "N 349:1869128934:2047056447", "{name} ในที่สุดข้าก็พร้อมรับตัวอย่างไข่มังกรจริงแล้ว! นี่ เอา Collectronic Module ไป มันออกแบบมาเพื่อนำไข่ออกและเตรียมสำหรับขนส่ง กลับไป Rookery แล้วใช้เครื่องเก็บไข่\n\nอย่าลืมแช่แข็งก่อน ไม่อย่างนั้นมันอาจฟักก่อนเก็บทัน!\n\nเมื่อได้ไข่พอแล้ว นำมาให้ข้า!" },
        progress = { "22:214657074:809973126 N 94:1374210630:1787455369", "เจ้ามีไข่หรือยัง {name}? ผู้อุปถัมภ์ได้ข่าวว่าเจ้ากำลังเก็บให้ข้า และอยากได้มันอย่างมาก!" },
        completion = { "76:852913968:723849287 N 53:929932235:2102854999", "ว้าว เจ้าได้มาแล้ว! Collectronic Module ได้ผล! ข้านี่อัจฉริยะจริง ๆ!\n\nขอบใจ {name} ผู้อุปถัมภ์คงพอใจมากที่ได้ไข่เหล่านี้..." },
    },
    [4742] = { -- Seal of Ascension
        title = { "17:527066717:1223127292", "ตราแห่งการผงาด" },
        objective = { "342:676363711:200082871", "หาอัญมณีแห่งบัญชาทั้งสาม ได้แก่ Gemstone of Smolderthorn, Gemstone of Spirestone และ Gemstone of Bloodaxe แล้วนำกลับไปให้ Vaelan พร้อม Unadorned Seal of Ascension\n\nแม่ทัพที่ Vaelan บอกคือ War Master Voone แห่ง Smolderthorn, Highlord Omokk แห่ง Spirestone และ Overlord Wyrmthalak แห่ง Bloodaxe" },
        description = { "464:2036898748:1383842596", "อย่างที่เห็น ตราที่ยังไม่ประดับมีช่องว่างสามช่อง แต่ละช่องต้องใส่อัญมณีที่แทนอำนาจบัญชาการของผู้นำ สุดท้าย Overlord Wyrmthalak นายแห่งป้อมส่วนล่างต้องตีตราด้วยเปลวไฟของฝูงมังกรดำ\n\nจงเข้าใจ ผู้มีอายุขัย โอกาสที่แม่ทัพคนใดในสามคนจะพกอัญมณีในแต่ละครั้งมีน้อย เจ้าต้องไม่ย่อท้อในการตามหา จงมุ่งมั่นไว้!" },
        progress = { "37:1064864653:1695545070 N 1:33:33", "ความกล้าและความอดทนสำคัญเหนือสิ่งอื่นใด {name}!" },
        completion = { "166:358415381:274688654", "<ภาพของ Vaelan พร่ามัวชั่วขณะ>\n\n<ชิ้นส่วนที่เจ้ารวบรวมมาหายไป>\n\nUnforged Seal of Ascension พร้อมแล้ว ถึงขั้นสุดท้ายเสียที" },
        required = { [12336] = { "22:613859072:877260699", "อัญมณีแห่ง Spirestone" }, [12335] = { "24:173226226:618092101", "อัญมณีแห่ง Smolderthorn" }, [12337] = { "20:1030965707:5661889", "อัญมณีแห่ง Bloodaxe" }, [12219] = { "27:1106711999:1690560297", "ตราแห่งการเลื่อนขั้นที่ยังไม่ประดับ" } },
        objectiveLabels = {
            item = { ["Gemstone of Spirestone"] = "อัญมณีแห่ง Spirestone", ["Gemstone of Smolderthorn"] = "อัญมณีแห่ง Smolderthorn", ["Gemstone of Bloodaxe"] = "อัญมณีแห่ง Bloodaxe", ["Unadorned Seal of Ascension"] = "ตราแห่งการเลื่อนขั้นที่ยังไม่ประดับ" },
        },
    },
    [4743] = { -- Seal of Ascension
        title = { "17:527066717:1223127292", "ตราแห่งการผงาด" },
        objective = { "454:1688702201:1500767600", "เดินทางไป Wyrmbog ใน Dustwallow Marsh หาเดรกโบราณ Emberstrife แล้วโจมตีอย่างไม่ปรานีจนเจตจำนงแตกสลาย\n\nจังหวะนั้นเจ้าต้องวาง Unforged Seal of Ascension ต่อหน้าอสูรใหญ่ แล้วรีบใช้ Orb of Draconic Energy กับร่างที่อ่อนแอเพื่อยึดการควบคุมจิตใจ บัญชาให้มันพ่น Flames of the Black Dragonflight ใส่ Unforged Seal of Ascension!" },
        description = { "343:25172386:995418887 N 142:1823379710:449089043", "นอกจากดรากอนคินในป้อมส่วนบนแล้ว มีมังกรดำไม่กี่ตนที่ตีตรานี้ด้วยลมหายใจไฟได้ Wyrmthalak เป็นหนึ่งในนั้น แต่เจตจำนงของเขาไม่อาจทำลาย\n\nเจ้าต้องไป Wyrmbog ใน Dustwallow Marsh ที่นั่นมีเดรกโบราณชื่อ Emberstrife จงทำให้เจตจำนงเขาแตกสลาย {name} แล้วใช้ลูกแก้วนี้กับร่างที่อ่อนแอ เจ้าจะมีเวลาเพียงไม่กี่วินาทีควบคุมจิตใจและพ่นไฟเพื่อตีตรา" },
        progress = { "15:125506103:1820579572 N 63:2122981130:1818956346", "อย่าเสียเวลา {name} Nefarian กำลังเร่งปล่อยความชั่วร้ายลงสู่โลกของเรา" },
        completion = { "322:782287631:2096080507", "ยืนนิ่ง ๆ ขณะข้าร่ายคำอัญเชิญคุ้มครองขั้นสุดท้าย\n\n<ดวงตาของ Vaelan กลายเป็นดวงไฟคู่>\n\nSeal of Ascension สมบูรณ์แล้ว...\n\nจงรู้ว่าข้าใส่เวทคุ้มครองทรงพลังลงในวัตถุนี้ ในชั่วโมงมืดมนที่สุด เมื่อดูเหมือนสูญสิ้นทุกอย่าง พลังของฝูงมังกรแดงจะอยู่พร้อมช่วยเจ้า" },
        required = { [12324] = { "24:151994953:582834092", "ตราแห่งการเลื่อนขั้นที่ตีขึ้นรูปแล้ว" } },
        objectiveLabels = {
            item = { ["Forged Seal of Ascension"] = "ตราแห่งการเลื่อนขั้นที่ตีขึ้นรูปแล้ว" },
        },
    },
    [4764] = { -- Doomrigger's Clasp
        title = { "18:926863629:1193000654", "เครื่องประดับของ Doomrigger" },
        objective = { "69:451537014:573379310", "นำ Doomrigger's Clasp ไปให้ Mayara Brightwing ที่ Burning Steppes" },
        description = { "481:465028192:1218000594 N 15:695862631:1339973419", "บน Blackrock Spire มีห้องที่ครั้งหนึ่งเรียกว่า Hall of Fortune ที่ซึ่งคนแคระดาร์กไอรอนเก็บวัตถุโบราณ ถ้วยรางวัล และงานศิลป์\n\nนั่นนานมาแล้ว ว่ากันว่าห้องพังลงและตอนนี้ใช้ทำงานที่... ไม่น่ารื่นรมย์นัก แต่ข้าเชื่อว่ายังมีวัตถุคนแคระเก่าบางชิ้นอยู่\n\nหนึ่งในนั้นคือ Doomrigger's Clasp พื้นผิวประดับอัญมณีหายากแน่นจนว่ากันว่าคนแคระใดเห็นก็ต้องหลั่งน้ำตา\n\nเครื่องประดับนั้นคือเป้าหมายของเจ้า {name}" },
        progress = { "23:1248073122:1264509126 N 44:1957537179:1936638416", "เจ้ามีเครื่องประดับหรือยัง {name}? ผู้อุปถัมภ์จะจ่ายอย่างงามเพื่อมัน" },
        completion = { "50:1077279033:1528042913 N 102:954839947:407176573", "เจ้าพบแล้ว! ข่าวลือเป็นจริงด้วย!\n\nขอบใจ {name} ผู้อุปถัมภ์ของข้า Count Remington Ridgewell คงพอใจมากที่ได้เพิ่มมันเข้าชุดสะสม" },
        required = { [12352] = { "18:926863629:1193000654", "ตะขอเกี่ยวของดูมริกเกอร์" } },
        objectiveLabels = {
            item = { ["Doomrigger's Clasp"] = "ตะขอเกี่ยวของดูมริกเกอร์" },
        },
    },
    [4765] = { -- Delivery to Ridgewell
        title = { "21:1563288338:1070584825", "ส่งของให้ Ridgewell" },
        objective = { "60:406198564:1692873255", "นำ Ridgewell's Crate ไปให้ Remington Ridgewell ที่ Stormwind" },
        description = { "84:483199468:330100581 N 224:2141308449:2091341179", "ข้าบรรจุ Doomrigger's Clasp ลงลังพร้อมส่งไป Stormwind แล้ว {name} เจ้าช่วยมากเหลือเกิน ขอรบกวนอีกอย่างสุดท้ายได้ไหม?\n\nนำลังไปให้ Count Remington Ridgewell ที่ Stormwind Keep ข้ามั่นใจว่าเขาคงพอใจมากเมื่อเห็นของที่เจ้านำไป" },
        progress = { { "84:1839452328:1618902047", "85:479774455:1647558040" }, "ข้าได้รับแจ้งว่าจะมีผู้ส่งสารมาพร้อมของขวัญจาก Blackrock Spire\n\nคือเจ้าหรือ?" },
        completion = { { "39:798510934:636068348 N 120:2103289355:1458696569", "40:2127427555:2029074870 N 120:2103289355:1458696569" }, "อา เป็นเจ้าจริงด้วย! ขอบใจ {name} และ... หากยังไม่รู้... ความซาบซึ้งจากขุนนางตระกูล Ridgewell มีค่าเกือบเท่าค่าไถ่พระราชาเลยทีเดียว" },
    },
    [4766] = { -- Mayara Brightwing
        title = { "17:1458011067:198160074", "Mayara Brightwing" },
        objective = { "52:896203995:222786216", "คุยกับ Mayara Brightwing ที่ Burning Steppes" },
        description = { "487:355325401:936248836", "Mayara Brightwing เจ้าหน้าที่ของข้าถูกส่งไป Burning Steppes เพื่อสำรวจซากเมือง Thaurissan เมืองดาร์กไอรอนที่ถูกทำลายนั้นอาจซ่อนของมีค่า... ของที่เหมาะกับพิพิธภัณฑ์ครอบครัวเรา\n\nMayara บอกว่าพบบางอย่างและต้องการคนช่วยนำกลับ แต่ของไม่ได้อยู่ใน Thaurissan ต้องบุกเข้า Blackrock Spire แทน\n\nข้าไม่รู้รายละเอียด หากสนใจก็ไปคุยกับ Mayara ที่ Burning Steppes" },
        completion = { "172:348055985:632560115", "เจ้ามาจาก Stormwind หรือ? วิเศษ ข้ารู้จักงานศิลป์ชิ้นหนึ่งที่ Remington อยากได้เข้าพิพิธภัณฑ์จนยอมทำทุกอย่าง แต่เอากลับมาไม่ง่าย\n\nนั่นคือส่วนที่เจ้าต้องช่วย" },
    },
    [4768] = { -- The Darkstone Tablet
        title = { "20:2014285576:591983085", "แผ่นจารึก Darkstone" },
        objective = { "68:1832726419:157931194", "นำ Darkstone Tablet ไปให้ Shadow Mage Vivian Lagrave ที่ Kargath" },
        description = { "501:534930128:316363551", "Darkstone Tablet บรรจุงานเขียนของ Urheld Darkstone คนแคระผู้ล่วงลับมานาน เขาเป็นนักเล่นแร่แปรธาตุฝีมือเยี่ยม แต่คนร่วมยุคคิดว่าบ้า จึงไม่แบ่งปันงานวิจัย\n\nทว่าเขาสลักมันลงบนแผ่นจารึก และข้าเชื่อว่าชิ้นหนึ่งอยู่ใน Blackrock Spire ในห้องที่เคยชื่อ Hall of Fortune ข้าไม่รู้ว่าตอนนี้เรียกอะไร เพราะน้อยคนที่เข้า Blackrock แล้วกลับมา\n\nหากเจ้ากล้าเผชิญอันตรายและนำแผ่นจารึกกลับมา รางวัลจะงามนัก" },
        progress = { "27:984711534:1776781851 N 36:686775121:730963120", "เจ้าพบแผ่นจารึกหรือยัง {name}? ข้าอยากศึกษาเจาะลึกความลับของมัน" },
        completion = { "146:1116745236:1922132249 N 33:163602574:437087701", "ยอดเยี่ยม สูตรที่สลักบนแผ่นนี้ต้องใช้เวลาวิจัยหลายวัน แต่ข้ามั่นใจว่าจะให้ผลอันหอมหวาน\n\nขอบใจ {name} เจ้าช่วยเราได้อย่างประเมินค่าไม่ได้" },
        required = { [12358] = { "16:128638672:1068749879", "แผ่นจารึก Darkstone" } },
        objectiveLabels = {
            item = { ["Darkstone Tablet"] = "แผ่นจารึก Darkstone" },
        },
    },
    [4769] = { -- Vivian Lagrave and the Darkstone Tablet
        title = { "39:1847083637:1814961337", "Vivian Lagrave กับแผ่นจารึก Darkstone" },
        objective = { "37:870356159:1366953412", "คุยกับ Shadowmage Vivian Lagrave" },
        description = { "312:1981938421:880248266", "Vivian Lagrave ส่งข่าวจาก Kargath ใน Badlands จากการศึกษานางเชื่อว่ามีข้อความโบราณใน Blackrock Spire ที่จะเป็นประโยชน์ต่องานวิจัยเรา เพื่อยืนยัน นางต้องการคนไปนำออกมา ไม่ใช่งานง่าย\n\nหากสนใจ ไปคุยกับ Vivian ที่ Kargath" },
        completion = { "236:867896047:564583060", "เป็นความจริง ข้าเชื่อว่ามีแผ่นจารึกใน Blackrock Spire ที่บรรจุสูตรเล่นแร่แปรธาตุเก่า ดีใจที่เจ้ามา เพราะข้าต้องการคนช่วยนำมันกลับ\n\nทำตัวตามสบาย แล้วข้าจะอธิบายต่อ" },
    },
    [4788] = { -- The Final Tablets
        title = { "17:1082757610:1108357192", "แผ่นจารึกชุดสุดท้าย" },
        objective = { "77:40236529:1947060753", "นำ Fifth Mosh'aru Tablet และ Sixth Mosh'aru Tablet ไปให้ Prospector Ironboot ที่ Tanaris" },
        description = { "284:567528884:1090902526 N 48:2076693628:1747011919", "ระหว่างข้าตรวจแผ่นจารึก Mosh'aru ชิ้นที่สามกับสี่ เจ้าต้องหาชิ้นที่ห้ากับหก! ไม่ง่ายแน่ เพราะอยู่กับโทรล Smolderthorn ใน Blackrock Spire ภูเขาไฟมืดระหว่าง Burning Steppes กับ Searing Gorge\n\nโชคดี {name} Blackrock Spire ไม่ใช่ที่สำหรับคนดี..." },
        progress = { "28:197978910:1059386281 N 41:376778886:121344076", "เจ้าไป Spire มาแล้วหรือ {name}? มีแผ่นจารึกชิ้นที่ห้ากับหกหรือยัง?" },
        completion = { "52:1620554207:655880979 N 163:729276314:1324212184", "เหลือเชื่อ! เจ้าพบมันแล้ว! เจ้าเป็นวีรชนแท้จริง {name}!\n\nดีแล้ว เพราะข้าอ่านแผ่นจารึกที่เจ้านำมาก่อนหน้า และเท่าที่จับความได้... เราต้องมีวีรชนเพื่อหยุดสิ่งที่กำลังจะมา..." },
        required = { [12740] = { "21:224981837:1475958680", "แผ่นจารึก Mosh'aru แผ่นที่ห้า" }, [12741] = { "21:1411564876:393685866", "แผ่นจารึก Mosh'aru แผ่นที่หก" } },
        objectiveLabels = {
            item = { ["Fifth Mosh'aru Tablet"] = "แผ่นจารึก Mosh'aru แผ่นที่ห้า", ["Sixth Mosh'aru Tablet"] = "แผ่นจารึก Mosh'aru แผ่นที่หก" },
        },
    },
    [4862] = { -- En-Ay-Es-Tee-Why
        title = { "16:988114215:607111019", "เอ็น-เอ-เอส-ที-วาย — น่าขยะแขยง" },
        objective = { "130:1083590381:8085493", "เดินทางไป Blackrock Spire แล้วเก็บ Spire Spider Egg 15 ฟองให้ Kibler\n\nฟังดูแล้ว น่าจะหาไข่เหล่านี้ได้ใกล้แมงมุม" },
        description = { "269:151380208:865151238 N 170:486778541:676006245", "เชื่อหรือไม่ มีคนยอมจ่ายเงินซื้อแม้แต่สัตว์เลี้ยงที่น่ารังเกียจที่สุด!\n\nข้าส่ง Bijou เข้า Spire ไปเก็บไข่แมงมุม แต่ไม่ได้ข่าวนางมาหลายสัปดาห์แล้ว บางทีเจ้าอาจช่วยได้?\n\nเอาอย่างนี้ {name} ไป Blackrock Spire แล้วเก็บ Spire Spider Egg กลับมา ข้าจะไม่เพียงให้เงินเล็กน้อย แต่ฝึกให้เจ้าตัวหนึ่งด้วย!" },
        progress = { "67:1680711495:849739385", "นั่นไข่แมงมุมในกระเป๋าเจ้า หรือแค่ดีใจที่ได้พบข้า?" },
        completion = { "147:645832879:133996951", "เยอะจริง! หมายถึงดูไข่พวกนั้นสิ! คงทำเงินได้หลายเหรียญทอง\n\nตามสัญญา นี่สัตว์ตัวน้อยของเจ้า ระวังถูกกัดล่ะ!" },
        required = { [12530] = { "16:932925473:436092923", "ไข่แมงมุมแห่ง Spire" } },
        steps = { { "16:932925473:436092923", "ไข่แมงมุมแห่ง Spire" } },
    },
    [4866] = { -- Mother's Milk
        title = { "13:1787272023:593751229", "น้ำนมแม่" },
        objective = { "230:1346144697:672567340", "ใจกลาง Blackrock Spire มี Mother Smolderweb จงเข้าต่อสู้ให้นางทำให้เจ้าติดพิษ มีโอกาสมากที่จะต้องสังหารนางด้วย กลับไปหา Ragged John ขณะที่ยังติดพิษ เพื่อให้เขา “รีดน้ำนม” จากเจ้า" },
        description = { "59:1756911480:2087963036 R 438:865083246:1658673382", "มันคงเป็นหนึ่งในพิษที่ร้ายแรงที่สุดในโลก ชาว{race}!\n\nตอนเข้า Spire ข้าได้ยินพวก Blackrock พูดถึงอานุภาพสังหารของมัน เรียกว่า “Mother's Milk” ตามชื่อ Mother Smolderweb แมงมุมยักษ์น่าขยะแขยงในถ้ำ Skitterweb\n\nสิ่งที่ข้าต้องการคือตัวอย่างพิษที่ยังออกฤทธิ์ ไหลอยู่ในเส้นเลือดของเจ้า แค่ต่อมพิษไม่พอ! ให้นางทำให้เจ้าติดพิษแล้วกลับมาหาข้า!\n\nจากนั้น... ข้าก็จะได้รีดน้ำนมเจ้า!\n\n<ถูมืออย่างตั้งตารอ>" },
        progress = { "26:2132744745:232007444", "<Ragged John หยิกเจ้า>" },
        completion = { "121:295047029:1626980103", "นี่จะทำเบียร์ที่ดีที่สุดเท่าที่เคยมีมา!\n\nหืม เจ้าคิดว่าข้าจะเอาไปทำอะไร? ยาพิษหรืออะไรทำนองนั้นหรือ??\n\nเด็กบ้าพวกนี้..." },
        objectiveLabels = {
            event = { ["Milked"] = "รีดพิษออกแล้ว" },
        },
    },
    [4867] = { -- Urok Doomhowl
        title = { "13:970420656:1962870228", "Urok Doomhowl" },
        objective = { "52:1405041844:1244353842", "อ่าน Warosh's Scroll แล้วนำ Warosh's Mojo ไปให้ Warosh" },
        description = { "55:160874908:111868387", "อ๊าก! พูดยากเหลือเกิน!\n\nเอาบันทึกนี้ไป! เอา Mojo ของข้าคืนมา!" },
        progress = { "24:1699074657:1495408969", "อา! เจ้ามี Mojo ของข้าหรือยัง?" },
        completion = { "112:620328999:997176846 N 218:1114797528:1575391438", "อาฮ่า! ข้าสัมผัสได้แล้วว่าพลังกำลังกลับมา จิตใจก็ไม่ถูกคำสาป Urok ทรมานอีก\n\nขอบใจ {name}! ความถ่อมตนไม่คู่ควรกับข้า แต่ก็ต้องยอมรับความช่วยเหลือของเจ้า\n\nขอให้โชคดีระหว่างเดินทางใน Blackrock Spire เจ้าช่างโง่ที่คิดว่าจะฝ่าถึงยอดได้ แต่ความกล้านั้นไม่มีใครสงสัย" },
        required = { [12712] = { "13:16578843:332257894", "โมโจของ Warosh" } },
        objectiveLabels = {
            item = { ["Warosh's Mojo"] = "โมโจของ Warosh" },
        },
    },
    [4903] = { -- Warlord's Command
        title = { "17:2116744763:1832993649", "คำสั่งผู้นำสงคราม" },
        objective = { "181:2069856545:1286247242", "สังหาร Highlord Omokk, War Master Voone และ Overlord Wyrmthalak นำ Important Blackrock Documents คืนมา แล้วกลับไปหา Warlord Goretooth ที่ Kargath" },
        description = { "355:1661239230:1605622681", "ตามคำสั่ง Warlord Goretooth ผู้อาศัยใน Blackrock Spire ต่อไปนี้ต้องถูกทำลาย:\n\nภัยตัวอ้วน Highlord Omokk\n\nโทรลผู้โหดเหี้ยมไร้ปรานี War Master Voone\n\nOverlord Wyrmthalak ผู้ควบคุมเมืองส่วนล่าง\n\nเจ้าต้องนำเอกสารสำคัญใด ๆ ที่พบกลับมาด้วย\n\nสำเร็จแล้วจะได้รับเกียรติ\n\nล้มเหลวแล้วจะถูกลืม" },
        progress = { "28:2106036749:614218734", "<Warlord Goretooth ทำความเคารพ>" },
        completion = { "77:851962948:739607033", "<ผิวสีเขียวหม่นของ Warlord Goretooth ซีดขาวชั่วขณะ>" },
        required = { [12562] = { "29:1162869771:1431131430", "เอกสารสำคัญของ Blackrock" } },
        objectiveLabels = {
            item = { ["Important Blackrock Documents"] = "เอกสารสำคัญของ Blackrock" },
            monster = { ["Overlord Wyrmthalak slain"] = "ปราบ จอมทัพ Wyrmthalak", ["Highlord Omokk slain"] = "ปราบ ขุนศึก Omokk", ["War Master Voone slain"] = "ปราบ จอมสงคราม Voone" },
        },
    },
    [4907] = { -- Tinkee Steamboil
        title = { "16:1803927624:271754897", "Tinkee Steamboil" },
        objective = { "28:767816031:720166734", "คุยกับ Tinkee Steamboil" },
        description = { "4:1229117181:163670253 N 269:395807381:839940626", "สวัสดี {name} จำ Tinkee Steamboil ได้ไหม? นางจำเจ้าได้! ส่งข่าวให้ข้าคอยมองหา เพราะ... นางต้องการความช่วยเหลืออีก ข้าว่าคงเกี่ยวกับการศึกษาเรื่องมังกร\n\nเจ้าควรไปคุยกับนางที่ Flame Crest ใน Burning Steppes" },
        completion = { "112:672917272:1451653325", "Felnok พูดถูก! ข้าต้องการให้เจ้าช่วยอีก และครั้งนี้... อันตรายมากจริง ๆ\n\nพร้อมหรือยัง??" },
    },
    [4974] = { -- For The Horde!
        title = { "14:1564662994:816764832", "เพื่อ Horde!" },
        objective = { "98:751400670:678620096", "เดินทางไป Blackrock Spire แล้วสังหาร Warchief Rend Blackhand นำหัวกลับไป Orgrimmar" },
        description = { "101:349383486:607710513 N 363:1183737497:758503983", "Rend กล้าอ้างตนอย่างใหญ่โตเพราะมีฝูงมังกรดำคุ้มครอง\n\nเจ้า {name} ต้องหาทางผ่าน Halls of Ascension แล้วตามหา “ผู้นำสงคราม” Rend Blackhand และทำลายมัน เพื่อ Horde!\n\n<Thrall ทุบกำปั้นลงบนบัลลังก์>\n\nเมื่อกลับมาห้องข้าอีกครั้ง เจ้าต้องชูหัวมันอย่างผู้ชนะ แล้วมอบให้ผู้นำสงครามของเจ้า ทำเช่นนี้แล้วจะได้รับเกียรติในฐานะวีรชน Horde" },
        progress = { "16:1258948351:909473981", "<Thrall แค่นเสียง>" },
        completion = { "60:22603894:2065269578 N 161:21505097:312126518", "เจ้าโจมตีกองกำลัง Blackrock จนเสียหายหนัก {name} เมื่อผู้นำสงครามตาย กองทัพ Blackrock ก็ถูกโยนสู่ความโกลาหลอีกครั้ง\n\nเพื่อเป็นเกียรติแก่ความกล้าของเจ้า ประชาชน Kalimdor จะได้รับรางวัล!" },
        required = { [12630] = { "22:1487131201:670351465", "ศีรษะของเรนด์ แบล็กแฮนด์" } },
        objectiveLabels = {
            item = { ["Head of Rend Blackhand"] = "ศีรษะของเรนด์ แบล็กแฮนด์" },
        },
    },
    [4981] = { -- Operative Bijou
        title = { "15:1056364933:1652055583", "เจ้าหน้าที่ Bijou" },
        objective = { "62:1686940829:549533523", "เดินทางไป Blackrock Spire แล้วสืบว่าเกิดอะไรขึ้นกับ Bijou" },
        description = { "52:1759739155:311301509 N 363:489125043:37592522 N 32:1252026314:1497016894", "อย่าไว้ใจก็อบลิน สรุปได้แค่นั้น {name}\n\nนางชื่อ Bijou เป็นหนึ่งในเจ้าหน้าที่ที่ลื่นไหลที่สุดของเรา ข้ารู้ว่านางทำงานให้พ่อค้าสัตว์หายากไม่น่าไว้ใจใน Burning Steppes ชื่อ Kibler เท่ากับรับงานซ้อนเรา ร้ายกว่านั้น ยังใช้ทุน Horde ทำงานของตน\n\nข้าต้องการให้นำตัวนางกลับมาเป็น ๆ\n\nมีคนเห็นนางครั้งสุดท้ายเข้า Blackrock Spire หาแล้วพากลับมา\n\nและ {name} อย่าให้นางใช้คำหวานหลอกเจ้า" },
        completion = { "20:694285467:1249622044 R 447:204385639:88347555", "ข้าไม่โกหก ชาว{race} ข้าต้องการเงิน! Kibler จ่ายดีมาก ดีกว่าที่กองสำรวจ Kargath จะจ่ายได้มากนัก\n\nแต่อย่าสงสัยความภักดีข้า! คิดว่าข้ามาทำอะไรที่นี่? เก็บไข่สัตว์หายากให้ก็อบลินบ้านั่นหรือทำอะไรไร้สาระพอกันหรือ? ไม่ มีแต่คนโง่จริง ๆ ที่จะมา Blackrock Spire เพื่อเก็บสัตว์เลี้ยง ใช่ ข้าว่าคนแบบนั้นในโลกมีไม่มาก\n\n<Bijou หัวเราะ>\n\nสิ่งสุดท้ายที่เราต้องการคือให้คนแบบนั้นขยายพันธุ์" },
    },
    [4982] = { -- Bijou's Belongings
        title = { "18:546879614:155620446", "ข้าวของของ Bijou" },
        objective = { "128:179508004:2131969364", "หา Bijou's Belongings แล้วนำกลับไปให้นาง เจ้าจำได้ว่านางบอกว่าซ่อนไว้ที่ชั้นล่างสุดของเมือง" },
        description = { "496:814165853:172578654", "กลางคืนตอนยามบางตา ข้าย่องสำรวจเมือง จดทุกสิ่งที่อาจมีคุณค่าทางยุทธศาสตร์ต่อกองสำรวจ Kargath\n\nแต่เมื่อคืนเกิดเรื่องเลวร้าย ข้าสะดุดลวดกับดักทำให้สัญญาณเตือนดัง จึงซ่อนอุปกรณ์สอดแนมแล้ววิ่งหาที่กำบัง! โชคร้ายที่กลับไปเอาไม่ได้ พวกมันเพิ่มลาดตระเวนเป็นสองเท่าสามเท่า ข้อมูลทั้งหมดจึงหายไป\n\nนำข้าวของข้าคืนมา แล้วข้าจะกลับกองสำรวจ Kargath โดยดี" },
        progress = { "9:959610494:1062111033", "ได้ผลบ้างไหม?" },
        completion = { "109:95165663:1099584089 N 17:1654410732:866008095", "เจ้าทำได้แล้ว! เมื่อ Lexlort ได้แผนเหล่านี้ คงลืมเรื่องร้าย ๆ ที่อยากทำกับข้าหมด\n\n{name} เจ้าเป็นวีรชนของข้า!" },
        required = { [12345] = { "18:546879614:155620446", "ข้าวของของ Bijou" } },
        objectiveLabels = {
            item = { ["Bijou's Belongings"] = "ข้าวของของ Bijou" },
        },
    },
    [4983] = { -- Bijou's Reconnaissance Report
        title = { "29:547527583:2030724414", "รายงานลาดตระเวนของ Bijou" },
        objective = { "74:409740947:1799058826", "นำ Bijou's Reconnaissance Report กลับไปให้ Grandmaster Lexlort ที่ Kargath" },
        description = { "248:1302743736:1183424166", "นำรายงานนี้กลับไปให้ Lexlort มันจะกู้ชื่อเสียงข้า และช่วยให้กองสำรวจ Kargath ได้เปรียบทางยุทธศาสตร์ต่อออร์คเหล่านี้แน่\n\nให้ข้าไปด้วยหรือ? ข้ามีงานมากเกินไป ไปได้แล้ว พวกเขาต้องการรายงานโดยเร็วที่สุด!" },
        progress = { "21:395831813:18636122", "ก็อบลินอยู่ไหน???" },
        completion = { "227:96145487:2131337609", "ต้องยอมรับเลย นางหาทางหลุดจากสถานการณ์ลำบากได้อีกแล้ว! รายงานเหล่านี้จะมีค่ามหาศาลในการรับมือออร์ค Blackrock\n\nแน่นอนว่าเจ้าจะได้รับรางวัลตอบแทนความเหนื่อยยาก" },
    },
    [5001] = { -- Bijou's Belongings
        title = { "18:546879614:155620446", "ข้าวของของ Bijou" },
        objective = { "58:385371941:2017626224", "หา Bijou's Belongings แล้วนำกลับไปให้นาง โชคดี!" },
        description = { "29:855649633:805126324 R 459:723280034:2139272060", "ปกติข้าไม่ทำธุรกิจกับชาว{race} แต่ตอนนี้ตกที่นั่งลำบากเหมือนติดระหว่างโทรลกับกำแพง ภารกิจข้าที่นี่สำคัญอย่างยิ่งต่อ Horde ทว่าข้อมูลที่พบเกี่ยวกับความปลอดภัยของ Alliance ด้วย เชื่อเถอะ ข้าไม่ได้เข้าข้าง Alliance แต่ภัย Blackrock ใหญ่กว่าออร์คแค่กลุ่มหนึ่ง\n\nเจ้าช่วยหาข้าวของให้ข้า แล้วข้าจะให้ข้อมูลที่อาจเป็นประโยชน์ต่อพวกเจ้า\n\nตกลงไหม?" },
        progress = { "9:959610494:1062111033", "ได้ผลบ้างไหม?" },
        completion = { "31:645257196:283906366", "ให้ตายสิ! ของอยู่ไหนหรือ??" },
        required = { [12345] = { "18:546879614:155620446", "ข้าวของของ Bijou" } },
        objectiveLabels = {
            item = { ["Bijou's Belongings"] = "ข้าวของของ Bijou" },
        },
    },
    [5002] = { -- Message to Maxwell
        title = { "18:1954273781:1984080329", "ข้อความถึง Maxwell" },
        objective = { "78:545954934:1257021711", "เดินทางไป Burning Steppes แล้วส่ง Bijou's Information ให้ Marshal Maxwell" },
        description = { "25:879702431:1004308288 R 399:2029639278:1680475145", "ข้าเป็นก็อบลินรักษาคำพูด ชาว{race} ฟังให้ดี:\n\nออร์คเหล่านี้ถูกใช้เป็นแรงงานกับทหารสละชีพให้ฝูงมังกรดำเป็นหลัก!\n\nผู้นำที่แท้จริงคือ Nefarian ลูกของ Deathwing ข้ายังพบที่อยู่ของผู้ใต้บัญชา Nefarian ในป้อมส่วนนี้ด้วย\n\nนำแผนที่นี้ไปให้ Marshal Maxwell ที่ Burning Steppes ข้าทำเครื่องหมายที่อยู่ของตัวร้ายเหล่านี้ให้ดูง่ายแล้ว" },
        progress = { "4:1110228981:147916455 N 26:915887027:2021835954", "อา {name} นานแล้วสินะ" },
        completion = { "194:1007027492:1347373104", "ข้อมูลนี้ตรงกับหลายอย่างที่เรารู้อยู่แล้ว แต่ก็น่าสนใจและน่าเสียดายนัก\n\nเครื่องหมายบนแผนที่จะช่วยลดภัยจาก Blackrock ได้มาก" },
    },
    [5047] = { -- Pip Quickwit, At Your Service!
        title = { "30:1356575712:992442985", "Pip Quickwit ยินดีรับใช้!" },
        objective = { "40:483402389:1515404398", "คุยกับ Malyfous Darkhammer ที่ Everlook" },
        description = { { "45:1697920997:350552346 C 387:373699537:1639239472", "45:1697920997:350552346 C 386:1081730346:49119287" }, "เจ้าจะพบ Malyfous Darkhammer ที่ Everlook {class} บอกเขาว่า “Finkle สบายดีทุกอย่าง” และชุดใช้ได้สมบูรณ์\n\nแล้วมอบสิ่งนี้ให้:\n\n<Finkle ส่งชิ้นเนื้อเรืองแสงให้เจ้า>\n\nข้าฉวยมาจากเครื่องในอสูรระหว่าง “พักร้อน”\n\nพนันว่า Malyfous คงประเมินได้ค่อนข้างแม่นว่าใช้ชิ้นส่วนสัตว์ประหลาดแบบนี้ทำอะไรได้บ้าง!\n\nอ้อ เจ้าคงไม่รู้ว่า Everlook อยู่ไหนใช่ไหม? ไป Winterspring เลย!", variants = { { "45:1697920997:350552346 C 381:1567244351:1669109736", "เจ้าจะพบ Malyfous Darkhammer ที่ Everlook {class} บอกเขาว่า “Pip สบายดี” และชุดใช้งานได้ดีทุกอย่าง\n\nแล้วเอานี่ไปให้เขา\n\n<Pip ยื่นชิ้นเนื้อเรืองแสงให้เจ้า>\n\nข้าฉวยมาจากเครื่องในของอสูรระหว่างที่ไป “พักร้อน”\n\nข้าพนันว่า Malyfous คงประเมินได้ค่อนข้างแม่นว่าเอาชิ้นส่วนของสัตว์ประหลาดแบบนี้ไปทำอะไรได้บ้าง!\n\nอ้อ เจ้าคงไม่รู้ว่า Everlook อยู่ที่ไหนสินะ? มุ่งหน้าไป Winterspring เลย พ่อหนุ่ม!", variants = { { "45:1697920997:350552346 C 380:2139226394:1311608674", "เจ้าจะพบ Malyfous Darkhammer ที่ Everlook {class} บอกเขาว่า “Pip สบายดี” และชุดใช้งานได้ดีทุกอย่าง\n\nแล้วเอานี่ไปให้เขา\n\n<Pip ยื่นชิ้นเนื้อเรืองแสงให้เจ้า>\n\nข้าฉวยมาจากเครื่องในของอสูรระหว่างที่ไป “พักร้อน”\n\nข้าพนันว่า Malyfous คงประเมินได้ค่อนข้างแม่นว่าเอาชิ้นส่วนของสัตว์ประหลาดแบบนี้ไปทำอะไรได้บ้าง!\n\nอ้อ เจ้าคงไม่รู้ว่า Everlook อยู่ที่ไหนสินะ? มุ่งหน้าไป Winterspring เลย แม่สาว!" } } } } },
        progress = { "4:1517434718:201826130", "ว่าอย่างไร?" },
        completion = { "45:44997529:1635309581", "ยังมีชีวิต? ชุดใช้ได้? แล้วนี่มีอะไรมาให้ข้า?" },
        required = { [12710] = { "33:2061620554:412027513", "ก้อนเนื้อเรืองแสงของ The Beast" } },
        objectiveLabels = {
            item = { ["Glowing Hunk of the Beast's Flesh"] = "ก้อนเนื้อเรืองแสงของ The Beast" },
        },
    },
    [5081] = { -- Maxwell's Mission
        title = { "17:81596087:1217615978", "ภารกิจของ Maxwell" },
        objective = { "144:1310921914:1351531131", "เดินทางไป Blackrock Spire แล้วทำลาย War Master Voone, Highlord Omokk และ Overlord Wyrmthalak เมื่องานเสร็จให้กลับไปหา Marshal Maxwell" },
        description = { "125:1507944801:1567694965 N 372:460385367:1834838690", "ข้อมูลนี้เติมช่องว่างในข่าวกรอง Blackrock Spire ที่เกือบสมบูรณ์ของเรา\n\nการโจมตีต้องเด็ดขาด {name}\n\nก่อนอื่นต้องทำลายจ้าวสงคราม โทรล Voone หากไร้แผนรบของเขา ออร์ค Blackrock จะตกอยู่ในความโกลาหล\n\nจากนั้นกำจัดจ้าวโอเกอร์ Omokk พวกโอเกอร์ขี้ขลาดแห่ง Blackrock ไร้พลังหากไม่มีเขานำ\n\nสุดท้ายคือนายแห่งป้อม Wyrmthalak เมื่อเขาตาย หน่วยบัญชาการกลางก็ไร้ผู้เชื่อมคำสั่ง" },
        progress = { "7:170873057:1148195227", "สถานการณ์เป็นอย่างไร?" },
        completion = { "16:1549935302:71513149 N 76:1172654407:923869458", "ผลงานยอดเยี่ยม {name} อย่างน้อยเจ้าก็ซื้อเวลาให้เราเพิ่ม เวลาที่ล้ำค่าเหลือเกิน" },
    },
    [5089] = { -- General Drakkisath's Command
        title = { "28:1112329876:952828625", "คำสั่งของ General Drakkisath" },
        objective = { "72:30395936:1182133571", "นำ General Drakkisath's Command ไปให้ Marshal Maxwell ที่ Burning Steppes" },
        description = { "234:1309878616:1841168292", "จากศพอสรพิษที่พ่ายแพ้ เจ้าพบบันทึกที่ดูสำคัญ เป็นจดหมายเรื่องระเบียบปฏิบัติจากผู้บังคับบัญชา General Drakkisath\n\nสัญชาตญาณบอกว่าเจ้าควรนำไปให้ Marshal Maxwell" },
        progress = { "25:1918645140:1241363237 N 1:63:63", "เจ้ามีอะไรอยู่นั่น {name}?" },
        completion = { "20:363853325:920666112", "เรื่องยิ่งซับซ้อนขึ้นแล้ว..." },
    },
    [5102] = { -- General Drakkisath's Demise
        title = { "27:1319067720:1380317611", "จุดจบของ General Drakkisath" },
        objective = { "105:1336675354:1984187507", "เดินทางไป Blackrock Spire แล้วทำลาย General Drakkisath เมื่องานเสร็จให้กลับไปหา Marshal Maxwell" },
        description = { "203:77452826:155469064 N 237:1497081888:1464776852", "เรารบกับอสูรเหล่านี้สองแนว จากเมืองหลวง Stormwind เราสู้พวกมันจากภายใน ส่วนที่ Burning Steppes เราบุกถึงหน้าประตูมัน เราต้องไม่ประมาท {name} ไม่มีตนใดควรรอดโทสะเรา เช่นเดียวกับที่คนของเราไม่ถูกละเว้นเมื่อพวกมันโจมตีบ้านและครอบครัว\n\nหา General Drakkisath แล้วทำลายเขา!\n\nงานนี้ไม่ง่ายแน่ แต่รางวัลจะยิ่งใหญ่นัก" },
        progress = { "11:1082766384:663732441", "เสร็จแล้วหรือ?" },
        completion = { "116:305422239:1938927889", "ต่อไปเราคงได้โจมตีจ้าวมังกรของพวกมัน ทำได้ดี ทหารกล้าแห่ง Alliance! ทำได้ดีจริง ๆ" },
    },
    [5127] = { -- The Demon Forge
        title = { "15:115137478:919090487", "เตาหลอมปีศาจ" },
        objective = { "341:1300674803:1902101061", "เดินทางไป Blackrock Spire แล้วหา Goraluk Anvilcrack สังหารแล้วใช้ Blood Stained Pike กับศพ เมื่อดูดวิญญาณแล้ว หอกจะกลายเป็น Soul Stained Pike\n\nเจ้าต้องหา Unforged Rune Covered Breastplate ด้วย\n\nนำทั้ง Soul Stained Pike และ Unforged Rune Covered Breastplate กลับไปให้ Lorax ที่ Winterspring" },
        description = { "420:378215851:2023146855", "Lorax เป็นผู้เสนอข้อตกลง ไม่ใช่รับจากผู้มีอายุขัยไร้ความสำคัญ\n\nแต่ข้าจะทำข้อตกลงกับเจ้า... รับหอกนี้ไป มันเปี่ยมพลังเฟลอันทรงอำนาจ เมื่อพบ Goraluk Anvilcrack จงสังหารแล้วแทงผ่านหัวใจที่กำลังสิ้นลม วิญญาณที่เขาใช้ต่อรอง ข้าจะต้องได้ นำหอกกับเกราะอกที่เจ้าหัวขโมยเอาไปกลับมา แล้วข้าจะสอนสิ่งที่เขาควรได้เรียนแก่เจ้า" },
        progress = { "12:1507492695:1222146838", "อย่าได้ลองดี..." },
        completion = { "73:2034960934:887114522", "เจ้าไม่ผิดสัญญา ข้าได้วิญญาณมา แล้วจะมอบรางวัลให้เจ้า" },
        required = { [12847] = { "17:2111413129:1715851176", "หอกเปื้อนวิญญาณ" }, [12806] = { "33:878771953:17412081", "เกราะอกจารึกรูนที่ยังตีไม่เสร็จ" } },
        objectiveLabels = {
            item = { ["Soul Stained Pike"] = "หอกเปื้อนวิญญาณ", ["Unforged Rune Covered Breastplate"] = "เกราะอกจารึกรูนที่ยังตีไม่เสร็จ" },
        },
    },
    [5160] = { -- The Matron Protectorate
        title = { "23:1947679276:901628416", "มารดาผู้พิทักษ์" },
        objective = { "62:290529553:601161056", "เดินทางไป Winterspring แล้วหา Haleh มอบ Awbee's Scale ให้นาง" },
        description = { "20:960283922:604097009 R 395:83242814:661584240", "จงไป Kalimdor ชาว{race} ฝูงมังกรเราตั้งบ้านในภูมิประเทศหนาวจัดของ Winterspring เมื่อถึงแล้วให้หาถ้ำ Mazthoril\n\nบนพื้นน้ำแข็งใน Mazthoril มีอักขระสีน้ำเงินโคบอลต์ ถือเกล็ดของข้าแล้วยืนบนอักขระ เจ้าจะถูกส่งไปหา Haleh มารดาผู้พิทักษ์ของเรา\n\nมอบเกล็ดให้นางเพื่อให้นางมองเห็นสิ่งที่ข้าเห็นและรู้สึกในสถานที่ถึงคราวพินาศนี้" },
        progress = { "23:1863591080:469987604 N 1:46:46", "ดีใจที่ได้พบเจ้า {name}" },
        completion = { "194:1753375838:1087906389", "เหล่า Aspect ยืนยันให้เราอยู่ห่างเรื่องของผู้มีอายุขัย แต่ในโลกนี้ก็ทำไม่ได้เสมอไป โดยเฉพาะเมื่อพวกเราเองมีผู้เหยียดหยามคำสั่งนั้น" },
        required = { [12923] = { "13:712878862:2048585132", "เกล็ดของ Awbee" } },
        objectiveLabels = {
            item = { ["Awbee's Scale"] = "เกล็ดของ Awbee" },
        },
    },
    [6402] = { -- Stormwind Rendezvous
        title = { "20:1308150208:1219798667", "นัดพบที่ Stormwind" },
        objective = { "141:1813343047:1610903187", "เดินทางไปประตูเมือง Stormwind คุยกับ Squire Rowe เพื่อให้เขาแจ้ง Marshal Windsor ว่าเจ้ามาถึงแล้ว" },
        description = { "174:1118697506:2003977523 N 59:850489291:1201365639", "เจ้าต้องพบ Windsor ที่ประตู Stormwind\n\nสิ่งที่เขากำลังจะเปิดเผยจะสั่นคลอนรากฐานของอาณาจักร!\n\nอย่าคิดไปลำพัง {name} เจ้าต้องรวบรวมกองกำลัง! เรียกสหายมารวมตัว จับอาวุธ!" },
        completion = { "82:1658150419:1172760092", "ก่อนเริ่ม ข้าขอให้เจ้ารวบรวมกองกำลังก่อน อย่างไรเราก็กำลังเผชิญมังกร!" },
        steps = { { "22:1125422625:687677536", "คุยกับ Squire Rowe" } },
    },
    [6403] = { -- The Great Masquerade
        title = { "20:441805315:991062262", "มหาหน้ากากลวง" },
        objective = { "65:2138767298:208770349", "ติดตาม Reginald Windsor ไปทั่ว Stormwind ปกป้องเขาจากอันตราย!", variants = { { "133:573745938:688458827", "ติดตาม Reginald Windsor ไปทั่ว Stormwind ปกป้องเขาจากอันตราย!\n\nหากต้องการติดต่อ Reginald Windsor อีกครั้ง ให้คุยกับ Squire Rowe" } } },
        description = { "477:148121773:1103905853", "เป็นการผจญภัยที่ยาวนานทีเดียว สหาย ข้าติดหนี้บุญคุณเจ้ามาก บางทีเมื่อทุกอย่างจบลง...\n\nอย่างที่เจ้าคงรู้แล้ว Lady Prestor คือ Onyxia ลูกของ Deathwing และฝาแฝดของ Nefarian จอมเผด็จการแห่ง Spire\n\nนางสะกดอาณาจักรเราไว้นานเกินไป แม้ Highlord ยังถูกกลอุบายควบคุมเป็นหุ่นเชิด ทุกอย่างจะจบวันนี้... เวทสะกดจะสลาย\n\nอย่าห่วง เมื่อร่วมมือกันเราจะชนะ!\n\nพร้อมหรือยัง?" },
        progress = { "26:1008497541:1270064335", "ข้า... ข้า... ไม่อาจทำอะไรได้เลย" },
        completion = { "398:224371946:1936966833", "<Bolvar ถือเครื่องรางที่แตกหัก>\n\nต้องปลุกเวทภายในให้ลุกขึ้นอีกครั้ง ต้องปรับพลังดวงตามังกร\n\nการเสียสละของ Windsor ปลดปล่อยอาณาจักรเราแล้ว แต่ภัย Onyxia กับพวกยังคุกคามไม่หยุด\n\nเครื่องรางนี้จองจำทั้งกายและใจข้า และเป็นสิ่งที่เปิดทางให้ข้าเข้าถึงจิตใจ Onyxia กับความลับของนาง แม้ตอนนี้ภาพจะพร่าเลือน แต่ข้ายังจำบางเรื่องได้" },
    },
    [6501] = { -- The Dragon's Eye
        title = { "16:1870949076:2075232546", "ดวงตามังกร" },
        objective = { "177:1732834441:1653903690", "ค้นทั่วโลกหาผู้ที่คืนพลังให้ Fragment of the Dragon's Eye ได้ ข้อมูลเดียวที่เจ้ามีคือผู้เช่นนั้นมีอยู่จริง" },
        description = { "264:792208798:101375381 N 189:1585625950:204980180", "ข้ามอบให้ได้เพียงเศษเครื่องรางที่แตกหัก\n\nเจ้าต้องหาผู้มีสายเลือดมังกรอีกตนที่ยินดีช่วยตีขึ้นเป็นกุญแจใหม่ เมื่อได้แล้ว จงไป Wyrmbog ใน Dustwallow Marsh ที่นั่นคือรังของนาง {name}\n\nจะหามังกรฝูงอื่นที่ยอมช่วยได้ที่ใด? น่าเศร้าที่ข้าไม่รู้... ว่ากันว่ามีอยู่ บางตนอาจใช้ชีวิตและทำงานท่ามกลางเรา โดยปลอมเป็นเผ่ามนุษย์รูปแบบต่าง ๆ ขอให้เจ้าโชคดี" },
        progress = { "44:1723609405:174748680 R 46:1252495216:203474967", "ข้าสัมผัสออร่าชั่วร้ายจากตัวเจ้า ชาว{race} เจ้าถืออะไรที่แผ่ออร่าเช่นนั้นออกมา?" },
        completion = { "88:353716517:786776425", "ข้าควรรู้อยู่แล้ว ชิ้นส่วนของ Onyxia แม่พันธุ์มังกรดำ น่าขยะแขยง..." },
    },
    [6502] = { -- Drakefire Amulet
        title = { "16:586706104:1057688615", "เครื่องรางเพลิงมังกร" },
        objective = { "174:1308543373:330162655", "นำ Blood of the Black Dragon Champion มาจาก General Drakkisath เขาอยู่ในห้องบัลลังก์หลัง Halls of Ascension ใน Blackrock Spire" },
        description = { "399:305386086:1715009396 R 94:309155148:717195892", "นี่คือส่วนหนึ่งของมังกร เป็นเกล็ดที่ถูกลงอาคมและแปรสภาพ เมื่อสมบูรณ์ มันพาเข้ารังอสูรได้ แต่เมื่อแตกแล้วก็ไร้ประโยชน์\n\nซ่อมได้ แต่ต้องใช้เลือดยอดนักรบมังกรดำ มีอยู่ตนหนึ่ง... General Drakkisath ผู้บัญชาการกองทัพดรากอนสปอว์นของ Nefarian บางทีเจ้าเคยได้ยินชื่อ?\n\nกลับมาพร้อมเลือดของเขา ชาว{race} แล้วข้าจะลงอาคมเศษนี้ให้เป็นสิ่งที่พาเจ้าเข้ารัง Onyxia ได้" },
        progress = { "40:872844461:564574473 R 77:1866411366:2129895099", "กาลเวลาไม่หยุดหรือช้าลง ชาว{race} ชีวิตข้าเป็นนิรันดร์ แต่ของเจ้าไม่ใช่ อย่าเสียเวลาที่มี..." },
        completion = { "215:1762912348:1515400922 N 1:46:46", "เครื่องรางนี้จะเปิดทางที่เจ้าแสวงหา รัง Onyxia อยู่ใน Dustwallow Marsh ตราบใดที่เจ้าพกมัน เวทคุ้มกันของนางก็ขวางการเข้าไปไม่ได้\n\nฝูงมังกรน้ำเงินขอให้เจ้าโชคดี {name}" },
        required = { [16663] = { "34:734828809:184013933", "โลหิตของยอดนักรบมังกรดำ" } },
        objectiveLabels = {
            item = { ["Blood of the Black Dragon Champion"] = "โลหิตของยอดนักรบมังกรดำ" },
        },
    },
    [6569] = { -- Oculus Illusions
        title = { "16:2086335573:1163591372", "ดวงตาแห่งภาพลวง" },
        objective = { "117:210802737:379004796", "เดินทางไป Blackrock Spire แล้วเก็บ Black Dragonspawn Eye 20 ชิ้น เมื่อครบให้กลับไปหา Myranda the Hag" },
        description = { "7:1382613162:1708906420 R 476:468392326:343382744", "ชาว{race}อยากเป็นหนึ่งในฝูงมังกรดำสินะ?\n\nการสร้างภาพลวงที่เจ้าต้องการง่ายมาก แต่วัตถุดิบสำหรับเวทหายากทีเดียว Rexxar กับผู้นำสงครามไว้ใจให้เจ้าทำภารกิจนี้ Myranda จึงต้องถือว่าเจ้ามีฝีมือ\n\nไปป้อมส่วนบนของ Blackrock Spire สังหารดรากอนสปอว์นดำให้มากพอใส่ดวงตาจนเต็มกระเป๋า\n\nเมื่อรวบรวมพอแล้ว กลับมาหา Myranda" },
        progress = { "91:808474290:1035443469 N 105:247322018:95965879", "ดวงตาของสิ่งที่เราต้องการเลียนแบบเป็นส่วนผสมสำคัญที่สุดของภาพลวงทุกชนิด {name}\n\n<Myranda ชี้ถุงที่ดวงตาแทบล้นออกมา ป้ายเขียนว่า “Scarlet Crusade”>\n\n<Myranda หัวเราะ>" },
        completion = { "25:1699069384:1391112976 R 176:126942258:585685598", "ให้ Myranda ดูหน่อย ชาว{race}\n\nโอ้ ใช่ ใช้ได้ดีเลย\n\nด้วยวัตถุดิบเหล่านี้ Myranda จะสร้างเครื่องรางมอบภาพลวงที่หลอกผู้เฝ้าประตูของฝูงมังกรดำได้" },
        required = { [16786] = { "21:1075377448:2072148736", "ดวงตาของดรากอนสปอว์นดำ" } },
        objectiveLabels = {
            item = { ["Black Dragonspawn Eye"] = "ดวงตาของดรากอนสปอว์นดำ" },
        },
    },
    [6602] = { -- Blood of the Black Dragon Champion
        title = { "34:734828809:184013933", "เลือดยอดนักรบแห่งมังกรดำ" },
        objective = { "96:2091276170:1557800187", "เดินทางไป Blackrock Spire สังหาร General Drakkisath แล้วนำเลือดกลับไปให้ Rexxar" },
        description = { "408:1915457315:2118933112", "เจ้าจะไปเยือนนายพลจริง แต่ไม่ได้ไปในฐานะมังกรดำ\n\nสำหรับฝูงมังกรดำ พิธีก็เป็นอีกคำหนึ่งของการหลั่งเลือด\n\nเครื่องรางที่ยังหลับใหลต้องการเพียงเลือดนายพลเพื่อปลุกพลัง เป็นระบบป้องกันความผิดพลาดหยาบ ๆ ของพวกมันอย่างหนึ่ง\n\nกลับไป Blackrock Spire แล้วทำลาย Drakkisath นำเลือดกลับมาที่นี่ ข้าจะปลุกกุญแจเข้ารัง Onyxia ให้" },
        progress = { "129:377491371:407826496", "คงไม่ต้องบอกว่า Drakkisath ไม่ใช่ศัตรูที่ควรประมาท\n\nให้ผู้ตายนับพันด้วยมือเขาเป็นคนบอกแทนข้าเถอะ" },
        completion = { "50:1591392339:1087843008 N 98:1012807779:597725700", "ชัยชนะที่จะถูกจดจำไปอีกหลายปี {name} Drakefire Amulet จะเปิดรัง Onyxia จงรวบรวมพันธมิตรแล้วนำชัยชนะมาสู่ Horde" },
        required = { [16663] = { "34:734828809:184013933", "โลหิตของยอดนักรบมังกรดำ" } },
        objectiveLabels = {
            item = { ["Blood of the Black Dragon Champion"] = "โลหิตของยอดนักรบมังกรดำ" },
        },
    },
    [6642] = { -- Favor Amongst the Brotherhood, Dark Iron Ore
        title = { "44:1516641335:1102320410", "ไมตรีแห่ง Brotherhood: Dark Iron Ore" },
        progress = { "246:362289790:1384331119", "แม้มีมากใน Depths แต่ Dark Iron ยังมีค่าสำหรับ Brotherhood อาวุธและยุทโธปกรณ์ศักดิ์สิทธิ์ของ Ragnaros นิยมใช้มัน\n\nทุกครั้งที่เสนอ Dark Iron Ore 10 ชิ้น เจ้าจะได้รับไมตรีจาก Brotherhood" },
        completion = { "119:1432415604:73346471", "เรารับของเสนอแล้ว เจ้าได้รับไมตรี จงทำต่อ แล้วจะได้เข้าถึงวิชาช่างโบราณ" },
