    [6643] = { -- Favor Amongst the Brotherhood, Fiery Core
        title = { "41:1522214194:2131140076", "ไมตรีแห่ง Brotherhood: Fiery Core" },
        progress = { "259:1887294337:717012589", "ผู้ท้าทายโชคชะตาใน Molten Core ย่อมทุกข์ ความตายมาอย่างรวดเร็ว ลงโทษไร้ปรานี\n\nสมาชิก Brotherhood หลายคนสูญสิ้นระหว่างหา Fiery Core\n\nเสนอ Fiery Core 1 ชิ้น แล้วเจ้าจะได้รับไมตรีจาก Brotherhood" },
        completion = { "119:1432415604:73346471", "เรารับของเสนอแล้ว เจ้าได้รับไมตรี จงทำต่อ แล้วจะได้เข้าถึงวิชาช่างโบราณ" },
