    [6644] = { -- Favor Amongst the Brotherhood, Lava Core
        title = { "40:2049494646:1823273883", "ไมตรีแห่ง Brotherhood: Lava Core" },
        progress = { "54:77254004:145789986 R 126:171877000:1869655679", "Thorium Brotherhood เห็นใจความลำบากของเจ้า ชาว{race} Lokhtos จึงได้รับอำนาจให้ต่อรอง\n\nเสนอ Lava Core 1 ชิ้น แล้วเจ้าจะได้รับไมตรีจาก Brotherhood" },
        completion = { "119:1432415604:73346471", "เรารับของเสนอแล้ว เจ้าได้รับไมตรี จงทำต่อ แล้วจะได้เข้าถึงวิชาช่างโบราณ" },
