    [6645] = { -- Favor Amongst the Brotherhood, Core Leather
        title = { "43:555039425:1061692164", "ไมตรีแห่ง Brotherhood: Core Leather" },
        progress = { "223:495070274:1643795701", "สูตรศักดิ์สิทธิ์หลายอย่างต้องใช้หนังสัตว์เลี้ยงที่ Ragnaros เลือก\n\nเสนอ Core Leather 2 ชิ้นที่ถลกจากซากคุกรุ่นของ Core Hound ใน Molten Core แล้วเจ้าจะได้รับไมตรีจาก Brotherhood" },
        completion = { "119:1432415604:73346471", "เรารับของเสนอแล้ว เจ้าได้รับไมตรี จงทำต่อ แล้วจะได้เข้าถึงวิชาช่างโบราณ" },
        required = { [17012] = { "12:1347771981:122858468", "หนังจาก Molten Core" } },
        objectiveLabels = {
            item = { ["Core Leather"] = "หนังจาก Molten Core" },
        },
    },
    [6646] = { -- Favor Amongst the Brotherhood, Blood of the Mountain
        title = { "52:1115064519:543345538", "ไมตรีแห่ง Brotherhood: Blood of the Mountain" },
        progress = { "136:1394987327:599518243", "น้ำตาของ Fire Lord หายากจริง ๆ\n\nเสนอ Blood of the Mountain 1 ชิ้น แล้วเจ้าจะได้รับไมตรีจาก Brotherhood" },
        completion = { "119:1432415604:73346471", "เรารับของเสนอแล้ว เจ้าได้รับไมตรี จงทำต่อ แล้วจะได้เข้าถึงวิชาช่างโบราณ" },
        required = { [11382] = { "21:1545367964:1932107437", "โลหิตแห่งขุนเขา" } },
        objectiveLabels = {
            item = { ["Blood of the Mountain"] = "โลหิตแห่งขุนเขา" },
        },
    },
    [7495] = { -- Victory for the Alliance
        title = { "24:1771957665:1832768083", "ชัยชนะเพื่อ Alliance" },
        objective = { "66:1703056610:556711050", "นำ Head of Onyxia ไปให้ Highlord Bolvar Fordragon ที่ Stormwind" },
        description = { "150:1782958375:1851981165", "เจ้าทำสิ่งที่เป็นไปไม่ได้สำเร็จ แม่พันธุ์มังกรดำนอนตายแทบเท้า จงนำหัวนางไปมอบให้ Highlord" },
        progress = { "17:1813046257:547597863", "เคราของ Uther เป็นพยาน!" },
        completion = { "166:673856426:840445084", "ข้าถูกสายตาสะกดของนางควบคุมมาหลายปี ในที่สุดก็ได้เห็นความยุติธรรมและเกียรติของ Stormwind กลับคืน! วันนี้เราจะฉลองชัยชนะอันรุ่งโรจน์!" },
    },
    [7496] = { -- Celebrating Good Times
        title = { "22:841714285:1301672951", "ฉลองช่วงเวลาแห่งความสุข" },
        objective = { "49:47808647:278964777", "ไปหา Major Mattingly ที่ Valley of Heroes" },
        description = { "50:1549403562:37163864 N 29:61668887:428923129", "ไปหา Major Mattingly ที่ Valley of Heroes {name} เขาจะรอเจ้าอยู่..." },
        completion = { "35:499053713:1111483458 N 66:290866170:261697607", "น้อยคนจะได้รับเกียรติในพิธีเช่นนี้ {name} โปรดเลือกรางวัล เพื่อเราจะได้เริ่มฉลอง" },
    },
    [7497] = { -- The Journey Has Just Begun
        title = { "26:373266038:808416650", "การเดินทางเพิ่งเริ่มต้น" },
        completion = { "402:1922501275:1967302971", "ทั้งผู้สังหารมังกรและช่างหนังผู้ชำนาญหรือ? เจ้าไม่เคยหยุดทำให้ข้าทึ่ง วีรชน ข้าขอน้อมยอมรับ\n\nโปรดรับสิ่งที่ข้ากำลังจะสอน ความรู้นี้จะมีค่ามหาศาลหากเจ้าจะทำลายฝูงมังกรดำที่ยังเหลือ\n\nสร้างผ้าคลุมจากเกล็ดแม่พันธุ์ มันจะปกป้องเจ้าและพันธมิตรจากลมหายใจเพลิงของนายแห่ง Blackrock... Nefarian" },
    },
    [7509] = { -- The Forging of Quel'Serrar
        title = { "26:1613588223:44880644", "การตีดาบ Quel'Serrar" },
        objective = { "362:1426965937:523032054", "ให้ Onyxia พ่นไฟใส่ Unfired Ancient Blade แล้วเก็บดาบที่กลายเป็น Heated Ancient Blade ระวัง ดาบจะไม่ร้อนตลอดไป เวลาจึงสำคัญยิ่ง\n\nขั้นสุดท้ายก่อนกลับมาหาข้า คือสังหารอสูรแล้วแทง Heated Ancient Blade ลงในศพนาง\n\nทำเช่นนี้แล้ว Quel'Serrar จะเป็นของเจ้า" },
        description = { "499:369762536:317021479", "นำ Unfired Ancient Blade ไปยังรัง Onyxia แล้วเข้าต่อสู้\n\nการเผาดาบต้องใช้กลอุบาย ระหว่างสู้ นางย่อมพยายามเผาเจ้าด้วยลมหายใจไฟ จงปักดาบไว้ใกล้ ๆ แล้วหวังว่าไฟจะทำให้ร้อน หากรอดมาได้ เก็บ Heated Ancient Blade แล้วจัดการมังกรให้สิ้น\n\nแทงดาบที่ร้อนลงในศพคุกรุ่นเพื่อให้กลายเป็นดาบโบราณที่ผ่านกระบวนการแล้ว" },
        progress = { "56:1402227338:811117964", "บางทีสักวัน จะมีอีกคนถือดาบประกายรุ้ง" },
        completion = { "56:1988811401:1728978168 C 27:752236370:420823859", "<Lydros พึมพำบางอย่างที่ฟังไม่รู้เรื่อง>\n\nตามสัญญา {class} ดาบ Quel'Serrar" },
        required = { [18492] = { "21:691364112:2102809923", "ใบดาบโบราณที่ผ่านการชุบ" } },
        objectiveLabels = {
            item = { ["Treated Ancient Blade"] = "ใบดาบโบราณที่ผ่านการชุบ" },
        },
    },
    [7761] = { -- Blackhand's Command
        title = { "19:1924290728:437405083", "คำสั่งของ Blackhand" },
        objective = { "239:1029034865:980331833", "ออร์คตนนี้โง่จริง ๆ ดูเหมือนเจ้าต้องหาเหล็กตรานี้แล้วรับ Mark of Drakkisath เพื่อใช้ Orb of Command\n\nจดหมายระบุว่า General Drakkisath เฝ้าเหล็กตราอยู่ บางทีควรไปสืบดู" },
        description = { "498:1426505356:1872260601", "เจ้าโง่\n\nข้าแทบไม่เชื่อความสามารถเจ้าที่จะกันคนนอกไม่ให้เข้ารังนายท่าน หากเจ้าตาย ซึ่งมีโอกาสสูง ลูกแก้วนี้ก็มีระบบป้องกันในตัวไม่ให้คนนอกเทเลพอร์ตเข้า Blackwing โดยตรง\n\nมีเพียงผู้ที่ได้รับ Mark of Drakkisath ประทับบนมือจึงใช้ลูกแก้วได้ โชคดีที่ Drakkisath ไม่ได้ไร้ความสามารถเท่าเจ้า เจ้าพลาธิการ เขาเฝ้าเหล็กตราด้วยตัวเอง!\n\n— Warchief Rend Blackhand\n\nป.ล. ทำลายจดหมายนี้เสีย เจ้าโง่" },
        completion = { "158:83756862:1801510484", "เจ้าไม่สะดุ้งแม้เหล็กตราคุกรุ่นถูกกดลงบนเนื้อ ช่างแกร่งจริง ๆ!\n\nตอนนี้เจ้ามี Mark of Drakkisath ขอให้สนุกกับการบุกปราสาท" },
    },
    [7848] = { -- Attunement to the Core
        title = { "22:211700460:2017269968", "ปรับพลังสู่ Core" },
        objective = { "180:845374165:1541910096", "ไปยังประตูเข้า Molten Core ใน Blackrock Depths แล้วนำ Core Fragment คืนมา เมื่อได้แล้วให้กลับไปหา Lothos Riftwaker ที่ Blackrock Mountain" },
        description = { "46:579083181:600024226 R 454:1714797191:1565644299", "รอยแยกปั่นป่วน ฉีกออก และยุบตัวรอบเรา ชาว{race} ห่างจากที่ข้ายืนไม่ถึงสองก้าว มีรอยฉีกนำผ่านส่วนลึกของ Blackrock Mountain เข้าสู่ปากเหว Firelord\n\nแปลกใจหรือ? น่าสงสาร... เผ่าผู้มีอายุขัยไม่อาจเข้าใจสิ่งที่มองไม่เห็น สัมผัสไม่ได้ หรือไม่รู้สึก\n\nข้ารับรองว่าประตูอยู่ตรงนั้นและเข้าไปได้\n\nสนใจแล้วหรือ? ปรับพลังไม่ยาก เข้า Blackrock Depths แล้วนำ Core Fragment กลับมา ข้าจะปรับแก่นพลังเจ้าให้เชื่อมกับประตู" },
        progress = { "72:1692823261:1740426097", "เจ้าต้องปรับวิญญาณให้เชื่อมกับ Molten Core ก่อน จึงจะเข้าไปได้" },
        completion = { "76:554006324:544639479", "ตอนนี้ข้าพาเจ้าไป Molten Core ได้แล้ว เพียงเอ่ยปาก ข้าก็จะทำให้" },
        required = { [18412] = { "13:478103333:979842647", "เศษแก่นพลัง" } },
        objectiveLabels = {
            item = { ["Core Fragment"] = "เศษแก่นพลัง" },
        },
    },
    [8288] = { -- Only One May Rise
        title = { "17:1807042343:193298164", "มีเพียงหนึ่งเดียวที่ผงาด" },
        objective = { "108:1849248731:1067914374", "นำ Head of the Broodlord Lashlayer กลับไปให้ Baristolth of the Shifting Sands ที่ Cenarion Hold ใน Silithus" },
        description = { "496:729319209:2069518282", "ไม่มีเวลาให้เสีย! ต้องหาวีรชนให้พบ! งานที่ข้ามอบต้องใช้กองทัพ แต่มีเพียงหนึ่งเดียวในหมู่ผู้หวังเป็นยอดนักรบที่จะก้าวขึ้นรับภาระและความรับผิดชอบในฐานะพันธมิตรของ Brood\n\nในรังนายแห่ง Blackrock มีอสูรโหดร้าย Broodlord Lashlayer เฝ้า Halls of Strife ขวางทางสู่วิหารชั้นในของ Nefarian จงสังหารสิ่งอัปลักษณ์แล้วนำหัวกลับมา ทำสำเร็จจึงจะเริ่มก้าวถัดไปของการเดินทางได้" },
        progress = { "60:388535320:460933817", "เจ้าต้องได้รับไมตรีจาก Brood of Nozdormu" },
        completion = { "81:1940272595:548978902", "เจ้าจะเป็นคนแรกในรอบพันปีที่ได้รับไมตรีจากฝูงมังกรสำริดหรือไม่?" },
        required = { [20383] = { "31:1049886838:2131513442", "ศีรษะของ Lashlayer ผู้บัญชาการฝูงมังกร" } },
        objectiveLabels = {
            item = { ["Head of the Broodlord Lashlayer"] = "ศีรษะของ Lashlayer ผู้บัญชาการฝูงมังกร" },
        },
    },
    [8578] = { -- Scrying Goggles? No Problem!
        title = { "28:722054211:122286109", "แว่นญาณทิพย์หรือ? ไม่มีปัญหา!" },
        objective = { "78:177287598:862830415", "หา Narain's Scrying Goggles แล้วนำกลับไปให้ Narain Soothfancy ที่ Tanaris" },
        description = { "418:869651266:96494048", "<เจ้าได้ยินเสียงถอนหายใจโล่งอกจากลัง>\n\nเจ้าแค่ต้องการแว่นญาณทิพย์ของเขาหรือ? เยี่ยม! ไม่มีปัญหา... ขอเวลาข้านิดเพื่อ... เฮ้! มันอยู่ไหน... บัดซบ!\n\nเอาละ มีข่าวร้ายกับข่าวร้ายกว่า ข่าวร้ายคือข้าทำแว่นหาย ข่าวร้ายกว่าคือหายตอนข้าสอดแนมใน Molten Core เมื่อเดือนก่อน ใช่ Molten Core... ข้าว่าธุระเราจบแล้ว! ลาก่อน!" },
        progress = { "62:1731977434:722212780", "Molten Core หรือ? หวังว่าแว่นข้าจะยังอยู่ครบชิ้นนะ!" },
        completion = { "156:389226474:1701882690", "ยอดเยี่ยม! ทีนี้ข้าเอาไก่หนัก 500 ปอนด์กับ “Draconic For Dummies” เล่ม II ไปไว้ไหนนะ??? อ้อ นี่ของเล็กน้อยตอบแทนความเหนื่อยยากทั้งหมด!" },
        required = { [20951] = { "24:1728326256:1345609718", "แว่นส่องนิมิตของ Narain" } },
        objectiveLabels = {
            item = { ["Narain's Scrying Goggles"] = "แว่นส่องนิมิตของ Narain" },
        },
    },
    [8730] = { -- Nefarius's Corruption
        title = { "21:983217808:871725507", "ความแปดเปื้อนของ Nefarius" },
        objective = { "166:1719932021:146732159", "สังหาร Nefarian แล้วนำ Red Scepter Shard คืนมา ส่งให้ Anachronos ที่ Caverns of Time ใน Tanaris เจ้าต้องทำภายใน 5 ชั่วโมง" },
        description = { "347:1064962422:1748754941", "ยอดนักรบ เป็นเจ้าหรือ? พันปีแล้วตั้งแต่ข้าได้รับหน้าที่ดูแลเศษคทา กลับมีผู้มารับช่วงในชั่วโมงมืดมนที่สุด... แต่โศกนาฏกรรมจะเป็นอย่างไรหากปราศจากความโหดร้าย?\n\n<Vaelastrasz ไออย่างอ่อนแรง>\n\nเน... Nefarius ถือเศษคทาอยู่ตอนนี้\n\nเวลาสำคัญยิ่ง Nefarius วางแผนทำลายเศษคทา เจ้าต้องรีบ!" },
        progress = { "102:268696911:1080130814", "วีรชนของเราอีกคนสูญเสียให้ลูกของ Deathwing เราคงถูกสาปให้ทุกข์เช่นนี้ตลอดไป..." },
        completion = { "216:1338197900:1411325214", "วิญญาณ Vaelastrasz สงบแล้ว ยอดนักรบ เหล่า Aspect ต่างติดตามความก้าวหน้าเจ้าอย่างสนใจ จงรู้ว่าเจ้ามีพันธมิตรทรงพลัง\n\nข้าได้รับคำสั่งให้มอบสิ่งช่วยเจ้าในการต่อสู้นี้ จงใช้ให้ดี..." },
        required = { [21138] = { "17:149727747:1281167758", "ชิ้นส่วนคทาสีแดง" } },
        objectiveLabels = {
            item = { ["Red Scepter Shard"] = "ชิ้นส่วนคทาสีแดง" },
        },
    },
    [8966] = { -- The Left Piece of Lord Valthalak's Amulet
        title = { "41:1733779189:1997736237", "เครื่องราง Lord Valthalak ชิ้นซ้าย" },
        objective = { "205:709574007:1170232896", "ใช้ Brazier of Beckoning เรียกวิญญาณ Mor Grayhoof แล้วสังหารเขา นำ Left Piece of Lord Valthalak's Amulet กับ Brazier of Beckoning กลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "508:1824488132:963785876", "Mor Grayhoof สหายของข้าเป็นคนแรกที่ตกเป็นเหยื่อการถือชิ้นส่วนเครื่องราง Lord Valthalak กับเศษวิญญาณแปดเปื้อนภายใน หลังขโมยตำราเวทและเครื่องราง เราหนีตายจากส่วนบนของ Blackrock Spire ระหว่างทาง Mor ตกลงไปส่วนล่าง\n\nภายหลังเรารู้ว่าเขารอดจากการตก แต่ถูก War Master Voone จับทรมาน นักฆ่าวิญญาณไม่กี่ตนลอบเข้าไปสังหารเขาต่อหน้า Voone" },
        progress = { "147:1928189379:2099728495", "เสร็จแล้วหรือ? เจ้าเอาเครื่องราง Lord Valthalak ชิ้นซ้ายคืนมา และให้วิญญาณ Mor Grayhoof สหายเก่าข้าพักสงบได้แล้วหรือ?" },
        completion = { "29:1046002443:319788529 N 385:349718859:1515169097", "เจ้าทำสิ่งยิ่งใหญ่ {name} วิญญาณหนึ่งสงบแล้ว แต่ยังมีงานอีกมากก่อนจะปล่อยเรื่องทั้งหมดเป็นอดีต\n\nโชคร้ายที่ข้าไม่รู้ว่าผู้ตายพร้อมชิ้นขวาของเครื่องรางอยู่ที่ไหน แต่อย่ากลัว สมัยมีชีวิตข้าเคยศึกษาการทำนายอยู่บ้าง จึงมีงานอีกอย่างให้เจ้าช่วยสืบหาชิ้นสุดท้าย" },
        required = { [21984] = { "37:1555460149:973538341", "ชิ้นส่วนซ้ายของเครื่องรางลอร์ดวัลธาลัก" } },
        objectiveLabels = {
            item = { ["Left Piece of Lord Valthalak's Amulet"] = "ชิ้นส่วนซ้ายของเครื่องรางลอร์ดวัลธาลัก" },
        },
    },
    [8989] = { -- The Right Piece of Lord Valthalak's Amulet
        title = { "42:323489937:78375914", "เครื่องราง Lord Valthalak ชิ้นขวา" },
        objective = { "202:1603277592:2066254702", "ใช้ Brazier of Beckoning เรียกวิญญาณ Mor Grayhoof แล้วสังหารเขา นำ Lord Valthalak's Amulet ที่ประกอบแล้วกับ Brazier of Beckoning กลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "508:1824488132:963785876", "Mor Grayhoof สหายของข้าเป็นคนแรกที่ตกเป็นเหยื่อการถือชิ้นส่วนเครื่องราง Lord Valthalak กับเศษวิญญาณแปดเปื้อนภายใน หลังขโมยตำราเวทและเครื่องราง เราหนีตายจากส่วนบนของ Blackrock Spire ระหว่างทาง Mor ตกลงไปส่วนล่าง\n\nภายหลังเรารู้ว่าเขารอดจากการตก แต่ถูก War Master Voone จับทรมาน นักฆ่าวิญญาณไม่กี่ตนลอบเข้าไปสังหารเขาต่อหน้า Voone" },
        progress = { "187:1908950240:354101066", "เสร็จแล้วหรือ? เจ้าเอาเครื่องราง Lord Valthalak ชิ้นขวาคืนมา ประกอบเครื่องรางครบ และให้วิญญาณ Mor Grayhoof สหายเก่าข้าพักสงบได้แล้วหรือ?" },
        completion = { "36:353234572:1273391510 N 273:1673765691:913077664", "ขอบใจที่ช่วย Mor Grayhoof {name} อีกวิญญาณสงบแล้ว และตอนนี้เรามีเครื่องรางที่ประกอบครบ! แต่บททดสอบยากที่สุดยังอยู่ข้างหน้า\n\nหากจะปรับกระถางไฟให้เรียก Lord Valthalak ได้ ยังมีของอีกเล็กน้อยที่ต้องเก็บกลับมาให้ข้าที่นี่" },
        required = { [22048] = { "23:1604992178:1028050503", "เครื่องรางของลอร์ดวัลธาลัก" } },
        objectiveLabels = {
            item = { ["Lord Valthalak's Amulet"] = "เครื่องรางของลอร์ดวัลธาลัก" },
        },
    },
    [8995] = { -- Mea Culpa, Lord Valthalak
        title = { "25:2072818205:1265502861", "ข้าขอรับผิด Lord Valthalak" },
        objective = { "185:1782323601:1901305797", "ใช้ Brazier of Beckoning เรียก Lord Valthalak ปราบเขา แล้วใช้ Lord Valthalak's Amulet กับศพ จากนั้นคืน Lord Valthalak's Amulet ให้ Spirit of Lord Valthalak" },
        description = { "18:117827525:1883469627 N 479:1567946434:2053365049", "ทุกอย่างพร้อมแล้ว {name}\n\nตอนมีชีวิต Lord Valthalak เคยอยู่ในห้องที่ตอนนี้เป็นของ The Beast จงไปใช้ Brazier of Beckoning เรียกเขาที่นั่น เขาจะกลับมีร่างกาย จึงต้องถูกสังหารอีกครั้ง ข้าคงจัดการ The Beast ก่อน และพาเพื่อนไปให้พอรอดจากส่วนบนของ Blackrock Spire\n\nเมื่อปราบ Valthalak แล้ว ใช้เครื่องรางกับศพ พอวิญญาณรวมเป็นหนึ่ง เขาคงอยากได้เครื่องรางคืนด้วย\n\nโชคดี!" },
        progress = { "C 27:1495605522:1430696487", "{class} เจ้ากล้ารบกวนการพักผ่อนของข้า!" },
        completion = { "160:256056428:2004492144", "เจ้าโชคดีที่ข้ารู้ว่าไม่ได้อยู่ในกลุ่มเดิมที่ขโมยของข้า\n\nทีนี้ข้าจะเอาสิ่งของของข้าคืน ผู้มีอายุขัย! ส่งเครื่องรางมา!" },
        required = { [22048] = { "23:1604992178:1028050503", "เครื่องรางของลอร์ดวัลธาลัก" } },
        objectiveLabels = {
            item = { ["Lord Valthalak's Amulet"] = "เครื่องรางของลอร์ดวัลธาลัก" },
        },
    },
    [5262] = { -- The Truth Comes Crashing Down
        title = { "29:1022957444:607360866", "ความจริงถล่มลงมา" },
        objective = { "82:1688865332:1382019758", "นำ Head of Balnazzar ไปให้ Duke Nicholas Zverenhoff ที่ Eastern Plaguelands" },
        description = { "486:60552466:1226154608", "เจ้าพยายามรวบรวมความคิดขณะฝุ่นสงบในห้อง ทบทวนสิ่งที่เพิ่งเกิดแต่ยังไม่อาจเข้าใจความร้ายแรง\n\nGrand Crusader แห่ง Scarlet Crusade เป็นปีศาจหรือ? ไม่ใช่ปีศาจธรรมดา แต่เป็นพี่น้องกับ Varimathras จ้าวใหญ่แห่ง Undercity?\n\nเจ้าเก็บหัวเดรดลอร์ดใส่กระเป๋าอย่างระวัง แน่นอนว่าหากไร้หลักฐาน คงไม่มีใครเชื่อเรื่องที่เล่า\n\nต้องแจ้ง Duke Nicholas Zverenhoff ทันที!" },
        progress = { "25:1918645140:1241363237 N 1:63:63", "เจ้ามีอะไรอยู่นั่น {name}?" },
        completion = { "161:1406887013:1386293454", "นี่จะหมายถึงอะไรต่อ Crusade? เป็นไปได้หรือว่าพวกเขาถูกปีศาจนี้ควบคุม เป็นเบี้ยรับใช้ความชั่วที่ใหญ่กว่าโดยไม่รู้ตัว?" },
        required = { [13250] = { "17:1913349334:1263666320", "ศีรษะของ Balnazzar" } },
        objectiveLabels = {
            item = { ["Head of Balnazzar"] = "ศีรษะของ Balnazzar" },
        },
    },
    [7493] = { -- The Journey Has Just Begun
        title = { "26:373266038:808416650", "การเดินทางเพิ่งเริ่มต้น" },
        completion = { "402:1922501275:1967302971", "ทั้งผู้สังหารมังกรและช่างหนังผู้ชำนาญหรือ? เจ้าไม่เคยหยุดทำให้ข้าทึ่ง วีรชน ข้าขอน้อมยอมรับ\n\nโปรดรับสิ่งที่ข้ากำลังจะสอน ความรู้นี้จะมีค่ามหาศาลหากเจ้าจะทำลายฝูงมังกรดำที่ยังเหลือ\n\nสร้างผ้าคลุมจากเกล็ดแม่พันธุ์ มันจะปกป้องเจ้าและพันธมิตรจากลมหายใจเพลิงของนายแห่ง Blackrock... Nefarian" },
    },
    [7508] = { -- The Forging of Quel'Serrar
        title = { "26:1613588223:44880644", "การตีดาบ Quel'Serrar" },
        objective = { "56:1172794085:1908260503", "มอบ Dull and Flat Elven Blade ให้ Lorekeeper Lydros" },
        description = { "69:1857489548:985878556", "หากอยากรับงานนี้ จงมอบดาบทื่อให้ Lydros" },
        progress = { "26:1233229527:614939698", "ดีมาก มาเริ่มกัน..." },
        completion = { "161:644841123:904053464", "หากเจ้าเข้ารังมังกร เผาดาบใต้ลมหายใจไฟ แล้วชุบด้วยเลือดนางได้ ข้าจะผูกดาบไว้ให้เจ้าใช้" },
    },
    [8967] = { -- The Left Piece of Lord Valthalak's Amulet
        title = { "41:1733779189:1997736237", "เครื่องราง Lord Valthalak ชิ้นซ้าย" },
        objective = { "200:1085202274:881185378", "ใช้ Brazier of Beckoning เรียกวิญญาณ Isalien แล้วสังหารนาง นำ Left Piece of Lord Valthalak's Amulet กับ Brazier of Beckoning กลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "508:33315910:1565372668", "ภายหลังระหว่างพยายามเอาชีวิตรอด เรารู้ว่า Isalien นักบวชหญิงไนต์เอลฟ์ในกอง ไปยังเมืองบรรพบุรุษไนต์เอลฟ์ที่ตอนนี้เรียก Dire Maul เท่าที่ทราบ นางไปทั้งเพราะเหตุส่วนตัวและเพื่อไขความลับชิ้นส่วนเครื่องรางที่ถือ\n\nแต่นางไปไม่ถึงเป้าหมาย ข่าวกลับมาว่า Alzzin the Wildshaper กับกองกำลังซุ่มโจมตีที่ Shrine of Eldretharr" },
        progress = { "136:2078830633:1746144883 N 1:63:63", "คงไม่ใช่ว่าเจ้าช่วยวิญญาณ Isalien และเอาเครื่องราง Lord Valthalak ชิ้นซ้ายคืนมาได้แล้วใช่ไหม {name}?" },
        completion = { "11:1191658970:1224418299 N 483:1335285885:921786494", "ขอบใจ {name} ที่ให้วิญญาณ Isalien พักสงบ บางทีนางจะได้พักสงบกับเทพีของนางเสียที แต่ยังมีงานมากหากจะพ้นสถานการณ์ลำบากนี้\n\nโชคร้ายที่ข้าไม่รู้ว่าผู้ตายพร้อมชิ้นขวาของเครื่องรางอยู่ที่ไหน แต่อย่ากลัว สมัยมีชีวิตข้าเคยศึกษาการทำนาย จึงมีงานอีกอย่างช่วยสืบหาชิ้นสุดท้าย" },
        required = { [21984] = { "37:1555460149:973538341", "ชิ้นส่วนซ้ายของเครื่องรางลอร์ดวัลธาลัก" } },
        objectiveLabels = {
            item = { ["Left Piece of Lord Valthalak's Amulet"] = "ชิ้นส่วนซ้ายของเครื่องรางลอร์ดวัลธาลัก" },
        },
    },
    [8968] = { -- The Left Piece of Lord Valthalak's Amulet
        title = { "41:1733779189:1997736237", "เครื่องราง Lord Valthalak ชิ้นซ้าย" },
        objective = { "197:1167269537:942467095", "ใช้ Brazier of Beckoning เรียก Jarien กับ Sothos แล้วสังหารทั้งสอง นำ Left Piece of Lord Valthalak's Amulet กับ Brazier of Beckoning กลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "486:1657385635:1322693197", "สองพี่น้อง Jarien กับ Sothos ตัดสินใจเข้า Scarlet Crusade หลังเรายุบกองทหารรับจ้าง พวกเขาเอาเครื่องราง Lord Valthalak ชิ้นซ้ายไปด้วย ไปให้พ้นเสียก็ดี แต่เราต้องเอาชิ้นนั้นคืน\n\nเท่าที่สืบได้ Grand Crusader Dathrohan ฆ่าพวกเขาเอง เพราะไม่ผ่านพิธีรับเข้าในห้องของเขาที่ Scarlet Bastion\n\nอย่างไรเรา... หมายถึงเจ้า ยังต้องเอาชิ้นนั้นคืน" },
        progress = { "21:1430156175:369766492 C 119:1118305068:113030474", "หมายความว่าเจ้าให้วิญญาณสองคนโง่พักสงบ และเอาเครื่องราง Lord Valthalak ชิ้นซ้ายคืนมาแล้วหรือ {class}?" },
        completion = { "490:1455165371:2109359127", "ข้าว่าคงดีที่สุดแล้วที่วิญญาณทั้งสองพักสงบ แม้ข้าไม่ชอบตอนมีชีวิต อย่างไรเราได้สิ่งที่ตามหา นั่นดีแน่นอน!\n\nโชคร้ายที่ข้าไม่รู้ว่าผู้ตายพร้อมชิ้นขวาของเครื่องรางอยู่ที่ไหน แต่อย่ากลัว สมัยมีชีวิตข้าเคยศึกษาการทำนาย จึงมีงานอีกอย่างช่วยสืบหาชิ้นสุดท้าย" },
        required = { [21984] = { "37:1555460149:973538341", "ชิ้นส่วนซ้ายของเครื่องรางลอร์ดวัลธาลัก" } },
        objectiveLabels = {
            item = { ["Left Piece of Lord Valthalak's Amulet"] = "ชิ้นส่วนซ้ายของเครื่องรางลอร์ดวัลธาลัก" },
        },
    },
    [8969] = { -- The Left Piece of Lord Valthalak's Amulet
        title = { "41:1733779189:1997736237", "เครื่องราง Lord Valthalak ชิ้นซ้าย" },
        objective = { "199:228765146:766768677", "ใช้ Brazier of Beckoning เรียกวิญญาณ Kormok แล้วสังหารเขา นำ Left Piece of Lord Valthalak's Amulet กับ Brazier of Beckoning กลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "477:948178689:1598317748", "ตอนนี้มีของที่ต้องใช้แล้ว ถึงเวลาคุยว่าเจ้าจะเรียกใคร\n\nKormok ก็นับว่าใช้ได้สำหรับโอเกอร์ จนหันไปศาสตร์ปลุกศพ หลังจากนั้นแทบทุกคนในกองก็ขนลุก จึงไม่แปลกเมื่อเขาเอาชิ้นเครื่องรางกลับบ้านใหม่ Scholomance\n\nแต่แม้ที่นั่น หรืออาจโดยเฉพาะที่นั่น เขาไม่ปลอดภัยจากนักฆ่าวิญญาณ พวกมันฆ่าต่อหน้านาย Ras Frostwhisper" },
        progress = { "15:421406717:488920675 N 143:1179274496:914952940", "ข้าชื่นชมเจ้า {name} หากนำชิ้นซ้ายกลับมาแล้ว ถ้ายัง โปรดจัดการ ไม่มีเวลาให้เสีย ข้ารับรอง!" },
        completion = { "11:354343371:1318038540 N 438:1558969492:649527156", "ทำได้ดี {name}! Kormok ไม่ได้แย่นักสำหรับโอเกอร์ อย่างน้อยตอนยังมีชีวิต หวังว่าจะได้พักอย่างสมควร แต่ยังมีงานต่อ\n\nโชคร้ายที่ข้าไม่รู้ว่าผู้ตายพร้อมชิ้นขวาของเครื่องรางอยู่ที่ไหน แต่อย่ากลัว สมัยมีชีวิตข้าเคยศึกษาการทำนาย จึงมีงานอีกอย่างช่วยสืบหาชิ้นสุดท้าย" },
        required = { [21984] = { "37:1555460149:973538341", "ชิ้นส่วนซ้ายของเครื่องรางลอร์ดวัลธาลัก" } },
        objectiveLabels = {
            item = { ["Left Piece of Lord Valthalak's Amulet"] = "ชิ้นส่วนซ้ายของเครื่องรางลอร์ดวัลธาลัก" },
        },
    },
    [8990] = { -- The Right Piece of Lord Valthalak's Amulet
        title = { "42:323489937:78375914", "เครื่องราง Lord Valthalak ชิ้นขวา" },
        objective = { "197:2008791582:1656181089", "ใช้ Brazier of Beckoning เรียกวิญญาณ Isalien แล้วสังหารนาง นำ Lord Valthalak's Amulet ที่ประกอบแล้วกับ Brazier of Beckoning กลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "508:33315910:1565372668", "ภายหลังระหว่างพยายามเอาชีวิตรอด เรารู้ว่า Isalien นักบวชหญิงไนต์เอลฟ์ในกอง ไปยังเมืองบรรพบุรุษไนต์เอลฟ์ที่ตอนนี้เรียก Dire Maul เท่าที่ทราบ นางไปทั้งเพราะเหตุส่วนตัวและเพื่อไขความลับชิ้นส่วนเครื่องรางที่ถือ\n\nแต่นางไปไม่ถึงเป้าหมาย ข่าวกลับมาว่า Alzzin the Wildshaper กับกองกำลังซุ่มโจมตีที่ Shrine of Eldretharr" },
        progress = { "137:1757026455:1702029417 N 72:2077296970:1679096746", "คงไม่ใช่ว่าเจ้าช่วยวิญญาณ Isalien และเอาเครื่องราง Lord Valthalak ชิ้นขวาคืนมาได้แล้วใช่ไหม {name}? อย่าลืมประกอบชิ้นส่วนก่อนส่งให้ข้า" },
        completion = { "11:1191658970:1224418299 N 338:1869585862:830595779", "ขอบใจ {name} ที่ให้วิญญาณ Isalien พักสงบ บางทีนางจะได้พักสงบกับเทพีของนางเสียที และเราก็มีเครื่องรางประกอบครบแล้ว! แต่บททดสอบยากที่สุดยังอยู่ข้างหน้า\n\nหากจะปรับกระถางไฟให้เรียก Lord Valthalak ได้ ยังมีของอีกเล็กน้อยที่ต้องเก็บกลับมาให้ข้าที่นี่" },
        required = { [22048] = { "23:1604992178:1028050503", "เครื่องรางของลอร์ดวัลธาลัก" } },
        objectiveLabels = {
            item = { ["Lord Valthalak's Amulet"] = "เครื่องรางของลอร์ดวัลธาลัก" },
        },
    },
    [8991] = { -- The Right Piece of Lord Valthalak's Amulet
        title = { "42:323489937:78375914", "เครื่องราง Lord Valthalak ชิ้นขวา" },
        objective = { "194:1691841715:25536135", "ใช้ Brazier of Beckoning เรียก Jarien กับ Sothos แล้วสังหารทั้งสอง นำ Lord Valthalak's Amulet ที่ประกอบแล้วกับ Brazier of Beckoning กลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "487:1135740587:20956156", "สองพี่น้อง Jarien กับ Sothos ตัดสินใจเข้า Scarlet Crusade หลังเรายุบกองทหารรับจ้าง พวกเขาเอาเครื่องราง Lord Valthalak ชิ้นขวาไปด้วย ไปให้พ้นเสียก็ดี แต่เราต้องเอาชิ้นนั้นคืน\n\nเท่าที่สืบได้ Grand Crusader Dathrohan ฆ่าพวกเขาเอง เพราะไม่ผ่านพิธีรับเข้าในห้องของเขาที่ Scarlet Bastion\n\nอย่างไรเรา... หมายถึงเจ้า ยังต้องเอาชิ้นนั้นคืน" },
        progress = { "21:1430156175:369766492 C 116:822837274:1730198581", "หมายความว่าเจ้าให้วิญญาณสองคนโง่พักสงบ และประกอบเครื่องราง Lord Valthalak แล้วหรือ {class}?" },
        completion = { "413:1196852290:1844451760", "ข้าว่าคงดีที่สุดแล้วที่วิญญาณทั้งสองพักสงบ แม้ข้าไม่ชอบตอนมีชีวิต อย่างไรเราได้สิ่งที่ตามหา และเครื่องรางประกอบครบแล้ว! แต่บททดสอบยากที่สุดยังอยู่ข้างหน้า\n\nหากจะปรับกระถางไฟให้เรียก Lord Valthalak ได้ ยังมีของอีกเล็กน้อยที่ต้องเก็บกลับมาให้ข้าที่นี่" },
        required = { [22048] = { "23:1604992178:1028050503", "เครื่องรางของลอร์ดวัลธาลัก" } },
        objectiveLabels = {
            item = { ["Lord Valthalak's Amulet"] = "เครื่องรางของลอร์ดวัลธาลัก" },
        },
    },
    [8992] = { -- The Right Piece of Lord Valthalak's Amulet
        title = { "42:323489937:78375914", "เครื่องราง Lord Valthalak ชิ้นขวา" },
        objective = { "196:764650607:1156714524", "ใช้ Brazier of Beckoning เรียกวิญญาณ Kormok แล้วสังหารเขา นำ Lord Valthalak's Amulet ที่ประกอบแล้วกับ Brazier of Beckoning กลับไปให้ Bodley ภายใน Blackrock Mountain" },
        description = { "482:677333840:770503966", "ตอนนี้มีของที่ต้องใช้แล้ว ถึงเวลาคุยว่าเจ้าจะเรียกใครต่อไป\n\nKormok ก็นับว่าใช้ได้สำหรับโอเกอร์ จนหันไปศาสตร์ปลุกศพ หลังจากนั้นแทบทุกคนในกองก็ขนลุก จึงไม่แปลกเมื่อเขาเอาชิ้นเครื่องรางกลับบ้านใหม่ Scholomance\n\nแต่แม้ที่นั่น หรืออาจโดยเฉพาะที่นั่น เขาไม่ปลอดภัยจากนักฆ่าวิญญาณ พวกมันฆ่าต่อหน้านาย Ras Frostwhisper" },
        progress = { "15:421406717:488920675 N 135:2146474924:1667903294", "ข้าชื่นชมเจ้า {name} หากนำเครื่องรางที่สมบูรณ์กลับมาแล้ว ถ้ายัง โปรดจัดการ ไม่มีเวลาให้เสีย ข้ารับรอง!" },
        completion = { "11:354343371:1318038540 N 364:706663107:799440173", "ทำได้ดี {name}! Kormok ไม่ได้แย่นักสำหรับโอเกอร์ อย่างน้อยตอนยังมีชีวิต หวังว่าจะได้พักอย่างสมควร และตอนนี้เครื่องรางสมบูรณ์แล้ว! แต่บททดสอบยากที่สุดยังอยู่ข้างหน้า\n\nหากจะปรับกระถางไฟให้เรียก Lord Valthalak ได้ ยังมีของอีกเล็กน้อยที่ต้องเก็บกลับมาให้ข้าที่นี่" },
        required = { [22048] = { "23:1604992178:1028050503", "เครื่องรางของลอร์ดวัลธาลัก" } },
        objectiveLabels = {
            item = { ["Lord Valthalak's Amulet"] = "เครื่องรางของลอร์ดวัลธาลัก" },
        },
    },
    [1193] = { -- A Broken Trap
        title = { "13:407137502:295527602", "กับดักชำรุด" },
        progress = { "438:193202700:184183914", "กับดักใหญ่ที่พังอยู่ตรงหน้า ดูเหมือนโอเกอร์พยายามซ่อมแล้วแต่ไม่สำเร็จ ข้าง ๆ มีบันทึกเขียนลวก ๆ ประหลาดที่ระบุของสำหรับซ่อมไว้อย่างชัดเจน ได้แก่ Thorium Widget กับ Frost Oil หากซ่อมได้ โอเกอร์ที่ผ่านใกล้ ๆ อาจติดกับ ทำให้เลี่ยงการเผชิญหน้าได้\n\nเห็นชัดว่าโชคดีที่โอเกอร์อ่านหนังสือเป็นกันน้อย\n\nชัดเจนจริง ๆ" },
        completion = { "248:668996152:37923010", "Thorium Widget เลื่อนเข้าที่อย่างง่ายดาย กลายเป็นช่องให้เท Frost Oil ลงไป เมื่อหยดสุดท้ายหมด กับดักก็งับเข้าตำแหน่ง\n\nโอเกอร์ประมาทที่บังเอิญเดินผ่านมา จงระวังให้ดี!" },
        description = { "438:193202700:184183914", "กับดักใหญ่ที่พังอยู่ตรงหน้า ดูเหมือนโอเกอร์พยายามซ่อมแล้วแต่ไม่สำเร็จ ข้าง ๆ มีบันทึกเขียนลวก ๆ ประหลาดที่ระบุของสำหรับซ่อมไว้อย่างชัดเจน ได้แก่ Thorium Widget กับ Frost Oil หากซ่อมได้ โอเกอร์ที่ผ่านใกล้ ๆ อาจติดกับ ทำให้เลี่ยงการเผชิญหน้าได้\n\nเห็นชัดว่าโชคดีที่โอเกอร์อ่านหนังสือเป็นกันน้อย\n\nชัดเจนจริง ๆ" },
        required = { [15994] = { "14:662888785:2114623579", "ชิ้นส่วนกลไกทอเรียม" }, [3829] = { "9:2048338092:2117751599", "น้ำมันเยือกแข็ง" } },
        objectiveLabels = {
            item = { ["Thorium Widget"] = "ชิ้นส่วนกลไกทอเรียม", ["Frost Oil"] = "น้ำมันเยือกแข็ง" },
        },
    },
    [1318] = { -- Unfinished Gordok Business
        title = { "26:1986565997:963335821", "ธุระ Gordok ที่ยังค้าง" },
        objective = { "236:1913615788:1922789776", "หา Gauntlet of Gordok Might แล้วนำกลับไปให้ Captain Kromcrush ใน Dire Maul\n\nตามที่ Kromcrush เล่า “เรื่องสมัยเก่า” บอกว่า Tortheldrin เอลฟ์ “น่าขนลุก” ที่เรียกตัวเองว่าเจ้าชาย ขโมยมันจากราชา Gordok คนหนึ่ง" },
        description = { "492:1024054476:370701568", "ตอนนี้เจ้าเป็นราชา บางทีเอาสมบัติล้ำค่า Gordok คืนจากเอลฟ์น่าขนลุกที่เรียกตัวเองว่าเจ้าชายได้! ราชาก่อนหน้าล้มเหลว เหมือนทุกคนตั้งแต่ Tortheldrin เจ้าเอลฟ์น่าขนลุก ขโมยมันจากราชา Gordok สมัยเก่า!\n\nของเรียกว่า Gauntlet of Gordok Might เรื่องสมัยเก่าว่ามีแต่ราชาแท้จริงของ Gordok ที่เอาคืนได้ ยังว่าเอลฟ์น่าขนลุกอยู่แถวนี้ หาให้พบ แล้วมันจะเป็นถุงมือทรงพลังที่เจ้าสวมตลอดไป! ยาร์ ข้าจะให้ดู!" },
        required = { [18336] = { "24:1195804790:533061007", "ถุงมือเกราะพลังแห่ง Gordok" } },
        objectiveLabels = {
            item = { ["Gauntlet of Gordok Might"] = "ถุงมือเกราะพลังแห่ง Gordok" },
        },
    },
    [4771] = { -- Dawn's Gambit
        title = { "13:1579029130:185103338", "กลศึกแห่งรุ่งอรุณ" },
        objective = { "108:686170939:1412793712", "วาง Dawn's Gambit ใน Viewing Room ของ Scholomance ปราบ Vectus แล้วกลับไปหา Betina Bigglezink" },
        description = { "419:1438513206:1519877154", "ข้าใส่ Dawn's Gambit ในภาชนะที่เจ้านำมา อันที่เคยบรรจุไข่มังกร งานเจ้าคือนำลึกเข้าไปใน Scholomance\n\nจอมเวทอันเดด Vectus นำกลุ่มนักวิชาการ Scourge จงวาง Dawn's Gambit ในห้องของพวกมันที่เรียกว่า “Viewing Room” มันจะทำปฏิกิริยากับอันเดดที่นั่น และหากโชคดีหน่อยก็ทำลายพวกมัน!\n\nหลังจากนั้น ปราบ Vectus คงไม่ยาก ใช่ไหม?" },
        progress = { "10:888060686:547970825 N 48:557835991:1245887981", "จำไว้ {name} เราต้องอดกลั้นต่อผู้อื่น แต่ยึดมั่นในความเชื่อ!" },
        completion = { "183:2119413353:1189942867 N 68:836771262:971695420", "เจ้าทำได้แล้ว! Vectus พ่ายแพ้! แล้ว Dawn's Gambit... ได้ผลไหม?\n\nอืม... เครื่องข้าอาจไม่สำเร็จอย่างที่หวัง แต่ก็ดีใจที่เจ้ารับมือได้ ทำได้ดี {name}!\n\nArgent Dawn และผู้คนดีแห่ง Azeroth ติดหนี้เจ้าแล้ว" },
    },
    [5122] = { -- The Medallion of Faith
        title = { "22:795121432:801649582", "เครื่องรางแห่งศรัทธา" },
        progress = { "236:902661775:216920891 N 167:943739989:1000029228", "พลังของโบสถ์นี้ทำให้ข้าต้านความแปดเปื้อนในใจได้ หากออกไปจะกลายเป็นเดธไนต์ แต่มีเครื่องรางแห่งศรัทธาที่มอบพลังให้ข้าออกไปได้\n\nขอร้อง {name} นำเครื่องรางกลับมา Malor the Zealous สมาชิกคลุ้มคลั่งของ Scarlet Brotherhood เฝ้ามันอยู่ลึกใน Scarlet Bastion ทางตะวันตกของ Stratholme" },
        completion = { "198:730008106:2058404659", "เจ้านำเครื่องรางกลับมาแล้ว! ตอนนี้ข้าจะออกจากโบสถ์ไปทำหน้าที่ได้\n\nหน้าที่นั้นคือสังหารอสูรผู้ช่วยทำให้ข้ากับพี่น้องอีกมากแปดเปื้อน Baron Rivendare!" },
        description = { "236:902661775:216920891 N 167:943739989:1000029228", "พลังของโบสถ์นี้ทำให้ข้าต้านความแปดเปื้อนในใจได้ หากออกไปจะกลายเป็นเดธไนต์ แต่มีเครื่องรางแห่งศรัทธาที่มอบพลังให้ข้าออกไปได้\n\nขอร้อง {name} นำเครื่องรางกลับมา Malor the Zealous สมาชิกคลุ้มคลั่งของ Scarlet Brotherhood เฝ้ามันอยู่ลึกใน Scarlet Bastion ทางตะวันตกของ Stratholme" },
        required = { [12845] = { "18:1164350548:683974926", "เครื่องรางแห่งศรัทธา" } },
        objectiveLabels = {
            item = { ["Medallion of Faith"] = "เครื่องรางแห่งศรัทธา" },
        },
    },
    [5125] = { -- Aurius' Reckoning
        title = { "17:250118975:9689390", "การชำระบัญชีของ Aurius" },
        completion = { "N 124:542237778:1326361529 C 1:33:33", "{name} ข้ากำลังตาย... แต่วิญญาณได้รับการช่วยแล้ว ข้าติดหนี้เจ้ามากกว่าคำใดจะบอกได้ โปรดรับสิ่งนี้... แล้วสู้ต่อไป {class}ผู้กล้า!" },
    },
    [5212] = { -- The Flesh Does Not Lie
        title = { "22:1313266103:74292817", "เนื้อหนังไม่โกหก" },
        objective = { "160:1898004721:906920431", "เก็บ Plagued Flesh Sample 10 ชิ้นจาก Stratholme แล้วนำกลับไปให้ Betina Bigglezink เจ้าคาดว่าสิ่งมีชีวิตใดในเมืองก็น่าจะมีตัวอย่างเนื้อเช่นนี้", variants = { { "160:310542178:1841403670", "เก็บ Plagued Flesh Sample 20 ชิ้นจาก Stratholme แล้วนำกลับไปให้ Betina Bigglezink เจ้าคาดว่าสิ่งมีชีวิตตัวไหนใน Stratholme ก็น่าจะมีตัวอย่างเนื้อเช่นนี้" } } },
        description = { "133:1613744582:1272084095 R 346:253910201:306127637 N 1:46:46", "นักปรุงยา Forsaken ไม่ใช่พวกเดียวในโลกที่เรียนวิทยาศาสตร์\n\nข้าศึกษาโรคระบาดมาหลายปี ชาว{race} ก่อนนี้เราคิดว่าฤทธิ์โรคกำลังลด แต่สิ่งที่ข้าพบใน Plaguelands น่าตกใจ มันดูจะรุนแรงขึ้น!\n\nข้าต้องทดสอบเพิ่ม! แหล่งโรคที่รุนแรงที่สุดคือเนื้อแปดเปื้อนของผู้เพิ่งติดเชื้อ จงไป Stratholme แล้วนำตัวอย่างมา {name}" },
        progress = { "68:1153022363:2037040638", "บางคนว่าข้ากังวลมากไป ข้าตอบว่า “พวกเจ้าต่างหากที่กังวลไม่พอ!”" },
        completion = { "115:555707813:1063607265", "โครงสร้างเคมีของสารออกฤทธิ์ในโรคระบาดเปลี่ยนไปบางอย่าง ต้องมีข้อมูลเพิ่ม" },
        required = { [13174] = { "20:1828683283:34294957", "ตัวอย่างเนื้อติดโรคระบาด" } },
        steps = { { "20:1828683283:34294957", "ตัวอย่างเนื้อติดโรคระบาด" } },
    },
    [5213] = { -- The Active Agent
        title = { "16:882815219:970120334", "สารออกฤทธิ์" },
        objective = { "101:83387448:1991759032", "เดินทางไป Stratholme แล้วค้นซิกกูแรต หา Scourge Data ใหม่กลับไปให้ Betina Bigglezink" },
        description = { "47:1075621854:27390766 N 195:1786367280:1424124578", "เจ้าต้องเข้า Stratholme ให้ลึกกว่าเดิม {name}\n\nหลังประตูแรกมีเหล่าซิกกูแรต เรารู้ว่า Scourge ดึงพลังมหาศาลจากสิ่งก่อสร้างนี้ จงค้นแล้วนำข้อมูลใดก็ตามที่พบกลับมา" },
        progress = { "76:1832825587:92220110", "เราใกล้ค้นพบแล้วว่าสารออกฤทธิ์ใหม่ของโรคนี้คืออะไร!" },
        completion = { "104:1412628596:1424396327 N 279:1611095070:29138214", "น่าทึ่ง! ต้องใช้เวลาหลายเดือนแยกและวิเคราะห์ Argent Dawn ขอบคุณความพยายามของเจ้า {name}\n\nพร้อมพรของเรา จงเลือกระหว่าง Seal of the Dawn กับ Rune of the Dawn ใช้อย่างใดอย่างหนึ่งแทน Argent Dawn Commission ทั่วไปเพื่อเก็บ Scourgestone ให้เราได้ หากทำหาย มาคุยแล้วข้าจะหาอันใหม่ให้" },
        required = { [13176] = { "12:1716278730:888361421", "ข้อมูลเกี่ยวกับ Scourge" } },
        steps = { { "12:1716278730:888361421", "ข้อมูลเกี่ยวกับ Scourge" } },
    },
    [5214] = { -- The Great Ezra Grimm
        title = { "20:267900415:1961556109", "Ezra Grimm ผู้ยิ่งใหญ่" },
        objective = { "133:734947444:335542759", "หาร้านยาสูบของ Ezra Grimm ใน Stratholme แล้วนำ Grimm's Premium Tobacco กลับมาหนึ่งกล่อง เมื่อเสร็จให้กลับไปหา Smokey LaRue" },
        description = { "469:1222626153:719363241 N 28:1785818929:1395708201", "เรื่องเลวร้าย... ที่เกิดกับ Fras ตอนเมืองถูกบุก เขาไม่ยอมทิ้งสินค้าล้ำค่า คำสุดท้ายที่ข้าจำได้คือ “ข้าจะเผาทุกใบก่อนให้มือสกปรกบัดซบของพวกมันแตะ!”\n\nข้าอาจชอบซิการ์ดี ๆ แต่ไม่โง่ วันนั้นจึงทิ้ง Fras กับร้านน่ารักของเขามา ข้าคิดว่าเขาคงตายในเปลวไฟ แต่หากมีโอกาสที่ยาสูบชื่อดังเหลือสมบูรณ์แม้กล่องเดียว...\n\nว่าอย่างไร {name}? หากล่องหนึ่งให้ Smokey คนนี้ได้ไหม?", variants = { { "469:93269889:1818935028 N 28:1785818929:1395708201", "เรื่องเลวร้าย... ที่เกิดกับ Ezra ตอนเมืองถูกบุก เขาไม่ยอมทิ้งสินค้าล้ำค่า คำสุดท้ายที่ข้าจำได้คือ “ข้าจะเผาทุกใบก่อนให้มือสกปรกบัดซบของพวกมันแตะ!”\n\nข้าอาจชอบซิการ์ดี ๆ แต่ไม่โง่ วันนั้นจึงทิ้ง Ezra กับร้านน่ารักของเขามา ข้าคิดว่าเขาคงตายในเปลวไฟ แต่หากมีโอกาสที่ยาสูบชื่อดังเหลือสมบูรณ์แม้กล่องเดียว...\n\nว่าอย่างไร {name}? หากล่องหนึ่งให้ Smokey คนนี้ได้ไหม?" } } },
        progress = { "17:1650692092:1055968868 N 31:1150702461:1063878419", "ข้าทนไม่ไหว {name}! ต้องช่วยข้า! ข้ากำลังจะตาย!" },
        completion = { "48:2084115136:847709786", "โอ้ ซิการ์แสนหวาน ข้าคิดถึงเจ้าเหลือเกิน..." },
        required = { [13172] = { "23:88581059:6907861", "ยาสูบชั้นดีของ Grimm" } },
        steps = { { "23:88581059:6907861", "ยาสูบชั้นดีของ Grimm" } },
    },
    [5243] = { -- Houses of the Holy
        title = { "18:1431609491:336691484", "เคหะแห่งความศักดิ์สิทธิ์" },
        objective = { "212:1145951472:18264644", "เดินทางไป Stratholme ทางเหนือ ค้นลังเสบียงที่กระจายทั่วเมืองแล้วเก็บ Stratholme Holy Water 5 ขวด เมื่อได้ครบให้กลับไปหา Leonid Barthalomew the Revered" },
        description = { "34:1739620312:1621420653 R 453:1600772356:1081854903", "ข้ามองภาวะอันเดดเป็นโรคอย่างหนึ่ง ชาว{race} ความเจ็บป่วยที่ต้องรักษาเท่านั้น แต่ก็เป็นพรใหญ่หลวงต่อ Argent Dawn จะมีร่างใดเหมาะลงทัณฑ์พวกนอกรีต Scourge ไปกว่าอันเดดเอง?\n\nเพื่อนร่วมงานยกย่องข้าเพราะสิ่งที่เสียสละ แต่คำสรรเสริญไร้ความหมายสำหรับข้า\n\nหากสนใจช่วย Argent Dawn ข้ามีงานให้\n\nจงไป Stratholme เอาน้ำมนต์สำรองของเราคืนมา ค้นตามลังเสบียง" },
        progress = { "179:921487533:1073770686", "ระวัง ลังเสบียงไม่ได้รอดจากเมืองถูกทำลายทุกใบ Scourge ไม่กล้าแตะน้ำ แต่น้ำมนต์คงกันสัตว์รังควานมาทำรังไม่ได้แน่" },
        completion = { "11:534428891:784080240 R 119:193229203:1234019349", "ทำได้ดี ชาว{race} เจ้าพิสูจน์แล้วว่าแม้อดกลั้นต่อผู้อื่น ก็ไม่ยอมหยุดจนกว่าจะทำลายลูกสมุน Kel'Thuzad" },
        required = { [13180] = { "21:1808788802:870975348", "น้ำศักดิ์สิทธิ์แห่ง Stratholme" } },
        steps = { { "21:1808788802:870975348", "น้ำศักดิ์สิทธิ์แห่ง Stratholme" } },
    },
    [5251] = { -- The Archivist
        title = { "13:517871958:1980989880", "ผู้ดูแลหอจดหมายเหตุ" },
        objective = { "118:1288483321:2082193771", "เดินทางไป Stratholme หา Archivist Galford แห่ง Scarlet Crusade ทำลายเขาและเผา Scarlet Archive" },
        description = { "56:186883569:1451798091 N 423:966421780:675017250", "สิ่งใดที่เลยเถิดย่อมเป็นภัยต่อโลก {name} ดู Scarlet Crusade สิ เจ้าเชื่อหรือว่าความคลั่งศรัทธาอย่างมืดบอดของพวกเขารับใช้สิ่งดีงามที่ยิ่งใหญ่กว่า? พวกมันทำลายผู้บริสุทธิ์ในนามแสงสว่างไปเท่าไรแล้ว?\n\nพวกลบหลู่ศาสนาทั้งนั้น!\n\nแต่มีคนหนึ่งที่ข้าสนใจ Archivist Galford แห่ง Stratholme ผู้ดูแลเอกสารมีค่าที่สุดของ Crusade จงทำลายเขาและเผาหอจดหมายเหตุ! หากสำเร็จ กลับมารับรางวัล" },
        progress = { "10:888060686:547970825 N 48:557835991:1245887981", "จำไว้ {name} เราต้องอดกลั้นต่อผู้อื่น แต่ยึดมั่นในความเชื่อ!" },
        completion = { "13:1029592715:2013062331 N 98:1570397145:1782454640", "ยอดเยี่ยม {name}! ข่าวกรองที่สะสมมาหลายปีสูญสิ้น! Scarlet Crusade จะรู้สึกถึงการโจมตีนี้ในสัปดาห์ข้างหน้าแน่" },
        steps = { { "14:1011278766:1514090771", "เผาคลังเอกสาร" } },
        objectiveLabels = {
            monster = { ["Archivist Galford slain"] = "ปราบ เจ้าหน้าที่หอจดหมายเหตุ Galford" },
        },
    },
    [5263] = { -- Above and Beyond
        title = { "16:1294128139:1616503613", "เหนือกว่าหน้าที่" },
        objective = { "104:1666916016:1741114269", "เข้า Stratholme แล้วทำลาย Baron Rivendare นำหัวกลับไปให้ Duke Nicholas Zverenhoff" },
        description = { "401:772826479:472147988", "เจ้ามีพรสวรรค์ในการทำลายและทำตามคำสั่งได้ น้อยคนจะมีทั้งสองอย่าง ข้าเริ่มคิดว่าเจ้าคงเป็นเครื่องมือแห่งความยุติธรรมศักดิ์สิทธิ์ที่ดี\n\n<Zverenhoff ประสานมือไว้หน้าใบหน้า>\n\nเด็กส่งสารของ Kel'Thuzad ปกครอง Stratholme จงพิสูจน์ว่าเป็นยอดนักรบ ยอดนักรบของข้า ทำลาย Baron Rivendare แล้วนำหัวกลับมา" },
        progress = { "80:502101296:153856052", "Baron สังหารคนมากกว่าที่เจ้าน่าจะเคยพบตลอดชีวิตเสียอีก" },
        completion = { "139:1768265407:639391922", "หลายปีแล้วที่ข้าไม่ได้ต้อนรับยอดนักรบเข้าร่วม เจ้าเป็นคนแรกในรอบหลายปีที่ได้เข้าพบ Lord Maxwell" },
        required = { [13251] = { "23:1995809935:1491847963", "ศีรษะของบารอน Rivendare" } },
        objectiveLabels = {
            item = { ["Head of Baron Rivendare"] = "ศีรษะของบารอน Rivendare" },
        },
    },
    [5341] = { -- Barov Family Fortune
        title = { "20:1567472260:1112044157", "สมบัติตระกูล Barov" },
        objective = { "251:1714941026:681165379", "เข้า Scholomance แล้วนำสมบัติตระกูล Barov กลับมา สมบัติคือโฉนดสี่ฉบับ ได้แก่ Deed to Caer Darrow, Deed to Brill, Deed to Tarren Mill และ Deed to Southshore เมื่อครบแล้วกลับไปหา Alexi Barov" },
        description = { "440:1754038623:538722965", "สมบัติตระกูล Barov อยู่ใน Scholomance ข้า Alexi Barov เป็นหนึ่งในทายาทสองคนสุดท้าย อีกคนคือ Weldon พี่น้องข้า\n\nเจ้าขี้ขลาด Weldon หนีตอนสงคราม จึงคงชีวิตมนุษย์ไร้ค่าไว้ได้\n\nตอนนี้เขาหาโฉนดเพื่อยึดสมบัติไว้คนเดียว จงนำโฉนดคืนมาก่อนเขา แล้วข้าจะทำให้เจ้ารวยเกินฝัน!" },
        progress = { "30:2113795081:1857746639 R 60:561630354:858147720", "ก้มหน้าต่อหน้าข้า ชาว{race} อย่างไรข้าก็เป็นขุนนาง ส่วนเจ้าเป็นชาวนาไม่มีแม้เหรียญทองแดง" },
        completion = { "16:1549935302:71513149 R 33:2013406335:1386701442", "ผลงานยอดเยี่ยม ชาว{race} ทีนี้ก็ทำให้มรดกข้ามั่นคง..." },
        required = { [13471] = { "17:508142134:202750051", "โฉนดที่ดิน Brill" }, [13448] = { "23:1208839953:420326484", "โฉนดที่ดิน Caer Darrow" }, [13450] = { "22:1142550570:1873542114", "โฉนดที่ดิน Southshore" }, [13451] = { "23:1591804356:329344187", "โฉนดที่ดิน Tarren Mill" } },
        objectiveLabels = {
            item = { ["The Deed to Brill"] = "โฉนดที่ดิน Brill", ["The Deed to Caer Darrow"] = "โฉนดที่ดิน Caer Darrow", ["The Deed to Southshore"] = "โฉนดที่ดิน Southshore", ["The Deed to Tarren Mill"] = "โฉนดที่ดิน Tarren Mill" },
        },
    },
    [5343] = { -- Barov Family Fortune
        title = { "20:1567472260:1112044157", "สมบัติตระกูล Barov" },
        objective = { "252:604671317:839084217", "เข้า Scholomance แล้วนำสมบัติตระกูล Barov กลับมา สมบัติคือโฉนดสี่ฉบับ ได้แก่ Deed to Caer Darrow, Deed to Brill, Deed to Tarren Mill และ Deed to Southshore เมื่อครบแล้วกลับไปหา Weldon Barov" },
        description = { "384:1071724074:592378763", "Alexi พี่น้องที่รัก ข้าช่างโง่ที่ไว้ชีวิต มองหน้าศัตรู อันเดดตนหนึ่ง แล้วปล่อยให้รอด\n\n<Weldon ถ่มน้ำลาย>\n\nตอนนี้เขาหามรดกของข้า ยอมไม่ได้เด็ดขาด\n\nหาโฉนดตระกูลข้าก่อนเจ้าชั่วเอามือกระดูกแตะ แล้วจะตอบแทนด้วยทรัพย์มหาศาล มันอยู่ในซาก Scholomance รีบไป!" },
        progress = { "42:229237676:786040559", "ทำให้อนาคตข้ามั่นคง แล้วข้าจะทำเช่นเดียวกันให้เจ้า" },
        completion = { "51:1000072196:1882981204 N 1:46:46", "ยังมีงานอีกเพียงอย่างที่ต้องขอให้เจ้าช่วย {name}" },
        required = { [13471] = { "17:508142134:202750051", "โฉนดที่ดิน Brill" }, [13448] = { "23:1208839953:420326484", "โฉนดที่ดิน Caer Darrow" }, [13450] = { "22:1142550570:1873542114", "โฉนดที่ดิน Southshore" }, [13451] = { "23:1591804356:329344187", "โฉนดที่ดิน Tarren Mill" } },
        steps = { { "17:508142134:202750051", "โฉนดที่ดิน Brill" }, { "23:1208839953:420326484", "โฉนดที่ดิน Caer Darrow" }, { "22:1142550570:1873542114", "โฉนดที่ดิน Southshore" }, { "23:1591804356:329344187", "โฉนดที่ดิน Tarren Mill" } },
    },
    [5382] = { -- Doctor Theolen Krastinov, the Butcher
        title = { "37:493590413:969111425", "Doctor Theolen Krastinov จอมเชือด" },
        objective = { "190:887066208:664654634", "หา Doctor Theolen Krastinov ใน Scholomance ทำลายเขา แล้วเผา Remains of Eva Sarkhoff กับ Remains of Lucien Sarkhoff เมื่อเสร็จให้กลับไปหา Eva Sarkhoff" },
        description = { "243:1420696673:328230664 N 1:46:46", "Krastinov ทำให้ผู้คนนับพันตาย เขาต้องถูกลงโทษ ต้องมีความยุติธรรม\n\nหาเขาแล้วตอบแทนความทรมานที่มอบแก่ผู้บริสุทธิ์นับไม่ถ้วน เมื่อทำลายเขาแล้ว เผาซากของเราให้เป็นเถ้า {name}" },
        progress = { "28:1797219780:603414678", "ต้องหยุดจอมเชือด!" },
        completion = { "30:1835607416:610261045 N 92:1272613528:1725290401", "ข้าสัมผัสได้ว่าวิญญาณกำลังฟื้นฟู {name} เจ้าช่วยข้ากับสามีอย่างมาก แต่ข้ามั่นใจว่ายังมีเรื่องต้องทำต่อ" },
        steps = { { "30:236696080:428734275", "เผาร่างของ Eva Sarkhoff" }, { "33:416005044:969505984", "เผาร่างของ Lucien Sarkhoff" } },
        objectiveLabels = {
            monster = { ["Doctor Theolen Krastinov slain"] = "ปราบ หมอ Theolen Krastinov" },
        },
    },
    [5384] = { -- Kirtonos the Herald
        title = { "19:943767919:808392076", "Kirtonos ผู้ประกาศ" },
        objective = { "245:938848521:2084835963", "กลับไป Scholomance พร้อม Blood of Innocents หาระเบียงแล้วใส่เลือดในกระถางไฟ Kirtonos จะมาเสพวิญญาณเจ้า\n\nจงสู้กล้าหาญ อย่าถอยแม้แต่นิ้ว! ทำลาย Kirtonos แล้วกลับไปหา Eva Sarkhoff" },
        description = { "12:1878497415:924553300 N 478:871588245:1478693687", "นี่แหละ {name}\n\n<Eva ชี้ขวดในถุง>\n\nเลือดผู้บริสุทธิ์ เลือดสะอาดที่สุด ใช้เอาใจนายของ Krastinov\n\nเลือดนี้เรียก Kirtonos ได้ และด้วยเลือดนี้เอง Kirtonos ต้องถูกทำลาย\n\nนำไปที่ระเบียง ใส่ในกระถางไฟ เขาจะมา อดใจไม่ได้ เมื่อปรากฏ จงระบายโทสะของผู้บริสุทธิ์นับพันที่ตายใส่เขา\n\nหากสำเร็จ เจ้าจะได้มากกว่าความขอบคุณของเรา" },
        progress = { "40:1338611911:324570614", "ระวัง Kirtonos ช่ำชองการต่อสู้" },
        completion = { "185:1959244929:1949901766 N 110:109513789:175553081", "เมื่อ Kirtonos ตาย เรื่องสยองของ Scholomance ก็ปิดลงบทหนึ่ง แต่ยังมีงานต่อ ผู้อื่นที่นี่รู้ความกล้าเจ้าแล้ว รับสิ่งนี้ {name} มันเป็นส่วนหนึ่งของแก่นพลังเรา ช่วยให้เจ้าสื่อสารกับวิญญาณหลงทางอื่นใน Caer Darrow ได้" },
        objectiveLabels = {
            monster = { ["Kirtonos the Herald slain"] = "ปราบ Kirtonos ผู้ส่งสาร" },
        },
    },
    [5466] = { -- The Lich, Ras Frostwhisper
        title = { "26:160785545:2132484969", "ลิช Ras Frostwhisper" },
        objective = { "270:623623972:1724619683", "หา Ras Frostwhisper ใน Scholomance แล้วใช้ Soulbound Keepsake กับร่างอันเดด หากทำให้เขากลับเป็นมนุษย์ได้ จงสังหารแล้วนำ Human Head of Ras Frostwhisper กลับไปให้ Magistrate Marduke" },
        description = { "33:211303767:1129995664 N 379:506665790:1754762348", "เหลืองานเดียว {name} เผชิญลิช Ras Frostwhisper ในรัง\n\nใช้พลังของที่ระลึกกับอสูร อย่าย่อท้อ! ทนการโจมตีที่มันดิ้นรนฟาดใส่ อย่ายอมแพ้ต่อความเจ็บปวด!\n\nเมื่อพิธีเสร็จ Ras จะกลับเป็นมนุษย์อีกครั้ง ต้องสังหารตอนนั้น แล้วนำหัวมนุษย์ของเขามา" },
        progress = { "53:1376656708:1251052697 N 1:46:46", "เจ้าแบกภาระวิญญาณไม่สงบหมื่นดวง {name}" },
        completion = { "38:1623058715:178423678 N 65:995163373:1650458125", "วิญญาณหมื่นดวงร้องเป็นเสียงเดียว {name}! เจ้าโจมตี Scourge กับนายของพวกมันอย่างร้ายแรงแล้ว" },
        required = { [13626] = { "30:807705499:2130697603", "ศีรษะมนุษย์ของ Ras Frostwhisper" } },
        objectiveLabels = {
            item = { ["Human Head of Ras Frostwhisper"] = "ศีรษะมนุษย์ของ Ras Frostwhisper" },
        },
    },
    [5515] = { -- Krastinov's Bag of Horrors
        title = { "26:1527705856:1674333906", "ถุงสยองของ Krastinov" },
        objective = { "140:652593593:1946142244", "หา Jandice Barov ใน Scholomance แล้วทำลายนาง เก็บ Krastinov's Bag of Horrors จากศพ แล้วนำถุงกลับไปให้ Eva Sarkhoff" },
        description = { "48:2049544909:2082489459 N 372:1960180308:1210965599", "ภาระใหญ่หลุดจากใจเราแล้ว {name} แต่งานเจ้ายังไม่จบ นายของ Krastinov คือ Kirtonos ยังมีชีวิต\n\nก่อนเผชิญเขา เจ้าต้องหาวิธีเรียกตัวมา\n\nว่ากันว่า Jandice Barov ดูแลการส่งเลือดผู้บริสุทธิ์จาก Krastinov ไป Kirtonos\n\nหานางในสุสานใต้ดินที่จมลงของ Scholomance สังหารแล้วนำเบาะแสใดก็ตามกลับมา" },
        progress = { "32:363938873:2720062", "<ร่าง Eva พร่ามัวและชัดขึ้นสลับกัน>" },
        completion = { "19:157532822:1569162752", "ถุงสยองนั่นเอง!" },
        required = { [13725] = { "26:1527705856:1674333906", "ถุงสยองขวัญของ Krastinov" } },
        objectiveLabels = {
            item = { ["Krastinov's Bag of Horrors"] = "ถุงสยองขวัญของ Krastinov" },
        },
    },
    [5518] = { -- The Gordok Ogre Suit
        title = { "20:1480466055:547185307", "ชุดโอเกอร์ Gordok" },
        objective = { "159:1002842722:1380599084", "นำ Bolt of Runecloth 4 ม้วน, Rugged Leather 8 ชิ้น, Rune Thread 2 เส้น และ Ogre Tannin ไปให้ Knot Thimblejack ผู้ถูกล่ามในปีก Gordok ของ Dire Maul" },
        description = { "488:2114355745:1774246082", "หากจะสู้ราชาที่นี่ ซึ่งข้าคิดว่าเจ้าคงทำแน่ เจ้าต้องผ่าน Captain Kromcrush ฆ่าเขาก็ผ่านได้ แต่เจ้าอาจอยากปล่อยให้มีชีวิต\n\nทำอย่างไรหรือ? อยู่มานาน ข้าคิดว่าทำชุดโอเกอร์ที่หลอกพวกทึ่มได้นานพอแล้ว ปัญหาคือความทน ใช้ได้สูงสุดสิบนาที เอาของที่ต้องใช้มาแล้วจะทำให้ ข้าไปไหนไม่ได้อยู่แล้ว..." },
        progress = { "348:254178078:1467291380", "Ogre Tannin คงหายากที่สุดในของที่ใช้ทำชุด ข้าว่ามีอยู่ข้างบนหรือเปล่า? บอกยาก เพราะลูกตุ้มกับโซ่นี้ทำให้เดินไม่สะดวก...\n\nอย่างไรเอาของมาให้ แล้วข้าจะทำชุดโอเกอร์หลอก Captain Kromcrush ว่าเจ้าเป็นคนของเขา" },
        completion = { "487:1252530104:1986744676", "ใช่ ใช้ได้เลย ตัดตรงนี้ พับตรงนี้... เฮ่ แบบนี้ต้องได้ผล! <ก็อบลินที่ถูกล่ามยิ้มกว้าง>\n\nนี่ พร้อมแล้ว จำไว้ว่านี่ไม่ใช่ของเย็บแน่นหนาที่สุด ใช้ได้สิบนาทีก่อนพัง แล้วจะหลอกใครไม่ได้อีก! ลองใช้ก่อนเข้าใกล้เขา และจำว่า... มันทำให้คิดว่าเจ้าเป็นพันธมิตรเพียงคนเดียว ไม่ใช่เพื่อนร่วมกลุ่ม!" },
        required = { [14048] = { "17:547033709:449099771", "ม้วนผ้ารูน" }, [8170] = { "14:1892667065:7828173", "หนังเหนียวทนทาน" }, [14341] = { "11:795594266:1319381041", "ด้ายรูน" }, [18240] = { "11:1607765871:1609190318", "สารฟอกหนังของโอเกอร์" } },
        objectiveLabels = {
            item = { ["Bolt of Runecloth"] = "ม้วนผ้ารูน", ["Rugged Leather"] = "หนังเหนียวทนทาน", ["Rune Thread"] = "ด้ายรูน", ["Ogre Tannin"] = "สารฟอกหนังของโอเกอร์" },
        },
    },
    [5519] = { -- The Gordok Ogre Suit
        title = { "20:1480466055:547185307", "ชุดโอเกอร์ Gordok" },
        progress = { "157:1719645121:201510888", "อยากได้อีกชุดหรือ? ดูเหมือนข้ายังไปไหนไม่ได้เร็ว ๆ นี้ เอาของอย่างเดิมมาแล้วจะทำชุดโอเกอร์ให้อีก" },
        completion = { "11:1708742308:764304647 N 163:1691634698:816099889", "นี่ {name} สวมแล้วเจ้ามีเวลาสิบนาทีทำธุระ โชคดี!\n\nอ้อ หากพบกุญแจปล่อยข้า ไม่ว่าอย่างไรต้องบอกนะ!!!" },
        description = { "157:1719645121:201510888", "อยากได้อีกชุดหรือ? ดูเหมือนข้ายังไปไหนไม่ได้เร็ว ๆ นี้ เอาของอย่างเดิมมาแล้วจะทำชุดโอเกอร์ให้อีก" },
        required = { [8170] = { "14:1892667065:7828173", "หนังเหนียวทนทาน" }, [14048] = { "17:547033709:449099771", "ม้วนผ้ารูน" }, [14341] = { "11:795594266:1319381041", "ด้ายรูน" }, [18240] = { "11:1607765871:1609190318", "สารฟอกหนังของโอเกอร์" } },
        objectiveLabels = {
            item = { ["Rugged Leather"] = "หนังเหนียวทนทาน", ["Bolt of Runecloth"] = "ม้วนผ้ารูน", ["Rune Thread"] = "ด้ายรูน", ["Ogre Tannin"] = "สารฟอกหนังของโอเกอร์" },
        },
    },
    [5525] = { -- Free Knot!
        title = { "10:101497170:2015404880", "ปลดปล่อย Knot!" },
        progress = { "307:1277229836:1723031862", "มันชื่อ Gordok Shackle Key อย่างน้อยพวก “สนุกหนักเป็นตัน” เรียกกันเช่นนั้น ข้าว่าโอเกอร์ตนใดก็อาจมี แต่ไม่แน่ใจว่าตนไหนโดยเฉพาะ บางทีพวกยามมีโอกาสพกมากกว่า...\n\nข้าพูดอะไรอยู่ เจ้ามีแล้วใช่ไหม?! นั่นหรือ??!" },
        completion = { "178:2144591646:918802769", "เจ้าอันดับหนึ่ง คนอื่นอันดับสองหรือต่ำกว่า โอ้ ขอบใจที่ปล่อยข้า!\n\nข้ารู้อยู่แล้วว่าชีวิตมีชะตามากกว่าเป็นแค่อาหารเรียกน้ำย่อยให้โอเกอร์!" },
        description = { "307:1277229836:1723031862", "มันชื่อ Gordok Shackle Key อย่างน้อยพวก “สนุกหนักเป็นตัน” เรียกกันเช่นนั้น ข้าว่าโอเกอร์ตนใดก็อาจมี แต่ไม่แน่ใจว่าตนไหนโดยเฉพาะ บางทีพวกยามมีโอกาสพกมากกว่า...\n\nข้าพูดอะไรอยู่ เจ้ามีแล้วใช่ไหม?! นั่นหรือ??!" },
        required = { [18250] = { "18:115485290:43210499", "กุญแจปลดตรวน Gordok" } },
        objectiveLabels = {
            item = { ["Gordok Shackle Key"] = "กุญแจปลดตรวน Gordok" },
        },
    },
    [5528] = { -- The Gordok Taste Test
        title = { "21:211809348:106316213", "ทดสอบรสชาติ Gordok" },
        completion = { "179:1129427460:773155929", "เจ้าเป็นนายใหญ่แล้ว ได้ชิมเบียร์ชั้นดีของข้าฟรี! เครื่องดื่มพวกนี้เสริมพลังและทำให้กรึ่มกำลังดี! ของดีนะ หัวหน้า... ลองแล้วบอก Kreeg เอง!" },
    },
    [5529] = { -- Plagued Hatchlings
        title = { "18:495476585:2022180511", "ลูกมังกรติดโรค" },
        objective = { "88:355261947:1852515481", "สังหาร Plagued Hatchling 20 ตัว แล้วกลับไปหา Betina Bigglezink ที่ Light's Hope Chapel" },
        description = { "388:1430544832:993546552", "Argent Dawn เพิ่งรู้ว่า Scourge กำลังสร้างฝูงมังกรติดโรคของตน! ต้องหยุดมัน หากได้กองทัพมังกร พวกมันจะกวาด Azeroth โดยไร้ผู้ขวาง!\n\nผู้ใช้ศาสตร์ปลุกศพกำลังเพาะมังกรติดโรคที่ Scholomance กลาง Darrowmere Lake\n\nไปสังหารลูกมังกรให้มากที่สุด... ก่อนโตไปกว่านี้!" },
        progress = { "24:973404023:1904324472 N 53:731484172:376142098", "ไป Scholomance {name} กำจัดลูกมังกรติดโรคก่อนโต!" },
        completion = { "11:534428891:784080240 N 99:2027607300:1533378471", "ทำได้ดี {name}! กว่าพวกมันจะเพาะมังกรชุดใหม่คงอีกนาน\n\n...อย่างน้อยข้าก็หวังเช่นนั้น!" },
        objectiveLabels = {
            monster = { ["Plagued Hatchling slain"] = "ปราบ ลูกมังกรติดโรคระบาด" },
        },
    },
    [5531] = { -- Betina Bigglezink
        title = { "17:1180985411:949018423", "Betina Bigglezink" },
        objective = { "43:1393458831:377848841", "นำ Frozen Eggs ไปให้ Betina Bigglezink" },
        description = { "463:1817204330:2019136855", "ไข่ที่เจ้านำมานั้นเดิมจะใช้ในการทดลอง Scourge เพื่อสร้างฝูงมังกรติดโรค ไข่มังกรดำแช่แข็งมีค่ามหาศาลต่องานศึกษา และคงเร่งกำหนดการแน่นอน\n\nตอนนี้ถึงเวลาหยุดงานวิจัย\n\nนำไข่ไปให้ Betina Bigglezink ข้างนอก นางเชี่ยวชาญวิทยาศาสตร์กับการเล่นแร่แปรธาตุ และสร้างอาวุธใช้ต่อกร Scourge แล้ว ด้วยเจ้าช่วย เราจะโจมตีมันอย่างหนัก" },
        progress = { "7:989913233:66981971 N 68:2134159106:1209582012", "สวัสดี {name}! ได้ยินว่ามาพร้อมไข่มังกรหรือ? เอามาดูสิ!" },
        completion = { "490:1845024912:609975747", "อยู่นี่เอง! ภาชนะก็ดีมาก ขนาดพอดี!\n\nเราจะเก็บไข่ไว้ปลอดภัยเพื่อศึกษาภายหลัง แต่ตอนนี้ต้องใช้ภาชนะที่เจ้าใส่มา\n\nข้าสร้างเครื่องที่มีงานเฉพาะ คือทำลายนักวิชาการอันเดดแห่ง Scholomance พวกมันศึกษามังกรเพื่อสร้างฝูงติดโรค เราต้องหยุดความก้าวหน้า\n\nข้าเรียกมัน Dawn's Gambit เพราะ... ยังไม่แน่ใจว่าได้ผล!\n\nเจ้าจะช่วยทดสอบให้เราไหม?" },
    },
    [5582] = { -- Healthy Dragon Scale
        title = { "20:1081944416:1571423878", "เกล็ดมังกรสุขภาพดี" },
        objective = { "102:1320709830:231320398", "นำ Healthy Dragon Scale ไปให้ Betina Bigglezink ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { "213:1653822470:1051728099", "นี่คือเกล็ดที่หลุดจากลูกมังกรติดโรค แต่ต่างจากเกล็ดอื่นที่เป็นหลุมและมีของเหลวซึม เกล็ดหายากชิ้นนี้สมบูรณ์ไร้ตำหนิ\n\nBetina Bigglezink คงอยากได้ตัวอย่างไปศึกษา" },
        progress = { "N 35:1944886849:2024581379", "{name} มีอะไรให้ข้าดูหรือ?" },
        completion = { "106:888874971:1272954891 N 63:1690350049:1518267602", "ยอดเยี่ยม! มีค่ามหาศาลต่อการศึกษากลอุบายของ Scourge ต่อไป ขอบใจ {name} หากพบเกล็ดอีก โปรดนำมาให้ข้า!" },
    },
    [6163] = { -- Ramstein
        title = { "8:175768681:1556832028", "Ramstein" },
        objective = { "92:299294135:1762539592", "เดินทางไป Stratholme แล้วสังหาร Ramstein the Gorger นำหัวไปเป็นของที่ระลึกให้ Nathanos" },
        description = { "498:1828016889:520089274", "ข้าต้านไม่ไหว ข้ายืนตรงไร่นานี้... ยืนหยัดป้องกัน Lordaeron ฟาร์มและทุกชีวิตถูก Scourge คลื่นมหึมาจู่โจม\n\nเจ้าชั่ว โสโครกนั่น มันอยู่เหนือร่างข้า เครื่องในห้อยจากช่องอกที่อ้า\n\nข้าตื่นเป็น Scourge ไร้หนทางอยู่นาน จิตใจหลอมรวมกับ Lich King\n\nนางมาหาข้า... ที่ใดสักแห่ง อย่างใดสักทาง ข้ารู้ว่านางจะมา อิสระ\n\nตอนนี้ข้าต้องแก้แค้น สิ่งที่พรากชีวิตข้าไป จงทำลายมัน" },
        progress = { "127:917177966:493077362", "หลัง Sylvanas ปลดปล่อยข้า ข้าล่าอสูรข้ามแดนร้างหลายเดือน มันหนีไปปลอดภัยใน Stratholme เจ้าสารเลว..." },
        completion = { "177:531214484:1229602556 N 21:1798477352:819116446", "ข้าสงสัย... มันขอความเมตตาหรือไม่? จะรู้จักความเมตตาหรือเปล่า?\n\n<Nathanos ถ่มน้ำลาย>\n\nข้าจะแขวนหัวอสูรบนผนัง\n\nเจ้าได้ที่ในหมู่ยอดนักรบของข้าแล้ว {name}\n\n<Nathanos ทำความเคารพ>" },
        required = { [15880] = { "27:130666433:1341603055", "ศีรษะของ Ramstein จอมตะกละ" } },
        objectiveLabels = {
            item = { ["Head of Ramstein the Gorger"] = "ศีรษะของ Ramstein จอมตะกละ" },
        },
    },
    [7429] = { -- Free Knot!
        title = { "10:101497170:2015404880", "ปลดปล่อย Knot!" },
        progress = { "307:1277229836:1723031862", "มันชื่อ Gordok Shackle Key อย่างน้อยพวก “สนุกหนักเป็นตัน” เรียกกันเช่นนั้น ข้าว่าโอเกอร์ตนใดก็อาจมี แต่ไม่แน่ใจว่าตนไหนโดยเฉพาะ บางทีพวกยามมีโอกาสพกมากกว่า...\n\nข้าพูดอะไรอยู่ เจ้ามีแล้วใช่ไหม?! นั่นหรือ??!" },
        completion = { "178:1157039075:683313966", "โอ้ ขอบใจที่ปล่อยข้า! เจ้าอันดับหนึ่ง คนอื่นอันดับสองหรือต่ำกว่า\n\nข้ารู้อยู่แล้วว่าชีวิตมีชะตามากกว่าเป็นแค่อาหารเรียกน้ำย่อยให้โอเกอร์!" },
        description = { "307:1277229836:1723031862", "มันชื่อ Gordok Shackle Key อย่างน้อยพวก “สนุกหนักเป็นตัน” เรียกกันเช่นนั้น ข้าว่าโอเกอร์ตนใดก็อาจมี แต่ไม่แน่ใจว่าตนไหนโดยเฉพาะ บางทีพวกยามมีโอกาสพกมากกว่า...\n\nข้าพูดอะไรอยู่ เจ้ามีแล้วใช่ไหม?! นั่นหรือ??!" },
        required = { [18250] = { "18:115485290:43210499", "กุญแจปลดตรวน Gordok" } },
        objectiveLabels = {
            item = { ["Gordok Shackle Key"] = "กุญแจปลดตรวน Gordok" },
        },
    },
    [7441] = { -- Pusillin and the Elder Azj'Tordin
        title = { "33:2054010743:1758385640", "Pusillin กับผู้อาวุโส Azj'Tordin" },
        objective = { "242:1929454866:350822657", "เดินทางไป Dire Maul หาอิมป์ Pusillin ทำทุกวิถีทางให้นำ Azj'Tordin's Book of Incantations มาคืน\n\nหากได้หนังสือแล้ว กลับไปหา Azj'Tordin ที่ Lariss Pavilion ใน Feralas" },
        description = { "478:2098252961:2117155853", "ข้าเผลอเพียงชั่วขณะ คนแปลกหน้า ระหว่างรีบหนีอำนาจเจ้าชายผู้ตกต่ำ ข้าถูกปล้น ปีศาจชั่วที่สุด อิมป์ Pusillin ขโมยตำราอาคมกับกุญแจห้องโถง Eldre'Thalas ที่เคยยิ่งใหญ่ไป\n\nข้าไม่สนกุญแจแล้ว เพราะแลกความเป็นอมตะกับอิสรภาพ แต่ต้องการตำราอย่างยิ่ง\n\nหาอิมป์ Pusillin แล้วเอาหนังสือคืน\n\nค้นหาเขาใน Warpwood Quarter ของ Dire Maul" },
        progress = { "177:1445588307:570166461", "ข้าไม่เสียใจเลย คนแปลกหน้า ราชินีจากไปนานแล้ว ผลงาน Shen'Dralar ถูกความบ้าของเจ้าชาย Tortheldrin ทำลาย ข้าเพียงแสวงหาอิสรภาพ... ทางหนี..." },
        completion = { "143:1436948278:108602146", "เจ้าพบแล้ว! ขอให้อิมป์น่าสมเพชถูกสาป อนิจจา ข้ามีทรัพย์สินน้อยเต็มที จงเลือกจากสิ่งที่พอให้ได้" },
        required = { [18261] = { "20:1104289564:588322332", "ตำราบทมนตร์" } },
        objectiveLabels = {
            item = { ["Book of Incantations"] = "ตำราบทมนตร์" },
        },
    },
    [7461] = { -- The Madness Within
        title = { "18:1387621927:319822667", "ความบ้าคลั่งภายใน" },
        objective = { "408:710880575:931922298", "ทำลายผู้พิทักษ์รอบ Pylon ทั้ง 5 ที่ส่งพลังให้ Prison of Immol'thar เมื่อเสาพลังดับ สนามพลังรอบ Immol'thar จะสลาย\n\nเข้าคุกแล้วกำจัดปีศาจชั่วที่อยู่ใจกลาง สุดท้ายเผชิญ Prince Tortheldrin ใน Athenaeum\n\nเมื่อเสร็จให้กลับไปหา Shen'dralar Ancient ในลาน" },
        description = { { "350:1617418886:1536643468", "352:669085630:1968714926" }, "ฟังพอแล้วหรือ? เจ้าเป็นคนพร้อมลงมือหรือไม่?\n\nความบ้านี้ต้องจบ ยุคอมตะผ่านไปนานแล้ว ทำลายผู้พิทักษ์รอบเสาเพื่อลดสนามพลัง จากนั้นทำลาย Immol'thar เมื่อพลังเจ้าชายลดฮวบ จงโจมตีจบชีวิตเขา ให้วิญญาณเมืองนี้พักสงบ นักผจญภัย" },
        progress = { "49:1991281592:565540881", "ระวัง นักผจญภัย เจ้าชายช่าง... โน้มน้าวเก่ง" },
        completion = { "19:1970779173:1511100661", "เราขอบคุณเจ้า วีรชน" },
    },
    [7462] = { -- The Treasure of the Shen'dralar
        title = { "31:483065421:1449319002", "สมบัติ Shen'dralar" },
        objective = { "84:1494892264:1869399238", "กลับ Athenaeum แล้วหา Treasure of the Shen'dralar ไปรับรางวัลของเจ้า!" },
        description = { "122:389395894:2016975610", "ในห้องสมุด Athenaeum มีหีบโบราณซ่อนใต้บันได จงหยิบสิ่งที่ต้องการจากมัน" },
        completion = { "29:1166232921:2100134704", "เจ้าเปิดหีบแล้วพบ..." },
    },
    [7481] = { -- Elven Legends
        title = { "13:905746096:2043988756", "ตำนานเอลฟ์" },
        objective = { "131:798592571:718376365", "ค้นหา Telmius Dreamseeker ใน Dire Maul แล้วนำข้อมูลใดก็ตามกลับไปรายงาน Sage Korolusk ที่ Camp Mojache" },
        description = { "495:590805702:2106590353", "หลายปีก่อน ปรมาจารย์เอลฟ์ผู้โดดเดี่ยวชื่อ Kariel Winthalus หนีความพินาศของบ้านเกิดพร้อมวัตถุเอลฟ์โบราณหลายชิ้น\n\nการตามหานำเราจากซาก Quel'Thalas ผ่าน Burning Steppes ข้ามทะเลกว้างสู่ Feralas\n\nเราสงสัยว่าเขาขอที่พักพิงในห้องโถง Eldre'Thalas ที่ตอนนี้เรียก Dire Maul\n\nเจ้าต้องหาเขาให้พบ นักผจญภัย จะเป็นหรือตาย ความรู้ที่นำไปต้องได้คืน!\n\nหมายเหตุผู้แปล: เป้าหมายต้นฉบับระบุ Telmius Dreamseeker แต่เนื้อเรื่องระบุ Kariel Winthalus ยังยืนยันไม่ได้ว่าข้อความใดตรงกับเกมปัจจุบัน ให้ตรวจชื่อในเควสจริง", variants = { { "498:2074545170:1516853784", "หลายปีก่อน ปรมาจารย์เอลฟ์ผู้เดินทางลำพังนาม Telmius Dreamseeker หนีจากบ้านเกิดที่ถูกทำลาย พร้อมนำโบราณวัตถุของเอลฟ์ติดตัวไปหลายชิ้น\n\nเราตามหาปรมาจารย์ที่หายไปจากซาก Quel'Thalas ผ่าน Burning Steppes ข้ามทะเลกว้างไปจนถึง Feralas\n\nเราคิดว่าเอลฟ์ผู้นั้นอาจหลบภัยในโถงแห่ง Eldre'Thalas ซึ่งปัจจุบันเรียกว่า Dire Maul\n\nเจ้าต้องหาเขาให้พบ นักผจญภัย ไม่ว่าเขาจะเป็นหรือตาย เราต้องกู้ความรู้ที่เขานำติดตัวไปกลับคืนมา!" } } },
        progress = { "87:1626538668:1005964843", "ผู้ร่วมงานของข้า Runethorn นักวิชาการไนต์เอลฟ์ กำลังรวบรวมพันธมิตรเพื่อภารกิจนี้" },
        completion = { "70:667209100:1116524938", "น่าเสียดาย... เป็นโศกนาฏกรรม ของหายไปแล้วหรือ? ไม่มีร่องรอยเขาเลยสินะ?" },
        objectiveLabels = {
            event = { ["Master Telmius Dreamseeker Found"] = "พบ Master Telmius Dreamseeker" },
        },
    },
    [7482] = { -- Elven Legends
        title = { "13:905746096:2043988756", "ตำนานเอลฟ์" },
        objective = { "134:979836477:433635806", "ค้นหา Telmius Dreamseeker ใน Dire Maul แล้วนำข้อมูลใดก็ตามกลับไปรายงาน Scholar Runethorn ที่ Feathermoon" },
        description = { "495:590805702:2106590353", "หลายปีก่อน ปรมาจารย์เอลฟ์ผู้โดดเดี่ยวชื่อ Kariel Winthalus หนีความพินาศของบ้านเกิดพร้อมวัตถุเอลฟ์โบราณหลายชิ้น\n\nการตามหานำเราจากซาก Quel'Thalas ผ่าน Burning Steppes ข้ามทะเลกว้างสู่ Feralas\n\nเราสงสัยว่าเขาขอที่พักพิงในห้องโถง Eldre'Thalas ที่ตอนนี้เรียก Dire Maul\n\nเจ้าต้องหาเขาให้พบ นักผจญภัย จะเป็นหรือตาย ความรู้ที่นำไปต้องได้คืน!\n\nหมายเหตุผู้แปล: เป้าหมายต้นฉบับระบุ Telmius Dreamseeker แต่เนื้อเรื่องระบุ Kariel Winthalus ยังยืนยันไม่ได้ว่าข้อความใดตรงกับเกมปัจจุบัน ให้ตรวจชื่อในเควสจริง", variants = { { "498:2074545170:1516853784", "หลายปีก่อน ปรมาจารย์เอลฟ์ผู้เดินทางลำพังนาม Telmius Dreamseeker หนีจากบ้านเกิดที่ถูกทำลาย พร้อมนำโบราณวัตถุของเอลฟ์ติดตัวไปหลายชิ้น\n\nเราตามหาปรมาจารย์ที่หายไปจากซาก Quel'Thalas ผ่าน Burning Steppes ข้ามทะเลกว้างไปจนถึง Feralas\n\nเราคิดว่าเอลฟ์ผู้นั้นอาจหลบภัยในโถงแห่ง Eldre'Thalas ซึ่งปัจจุบันเรียกว่า Dire Maul\n\nเจ้าต้องหาเขาให้พบ นักผจญภัย ไม่ว่าเขาจะเป็นหรือตาย เราต้องกู้ความรู้ที่เขานำติดตัวไปกลับคืนมา!" } } },
        progress = { "80:1101807312:1677346904", "ผู้ร่วมงานของข้า Korolusk ปราชญ์ทอเรน กำลังรวบรวมพันธมิตรเพื่อภารกิจนี้" },
        completion = { "70:667209100:1116524938", "น่าเสียดาย... เป็นโศกนาฏกรรม ของหายไปแล้วหรือ? ไม่มีร่องรอยเขาเลยสินะ?" },
        objectiveLabels = {
            event = { ["Master Telmius Dreamseeker Found"] = "พบ Master Telmius Dreamseeker" },
        },
    },
    [7483] = { -- Libram of Rapidity
        title = { "18:1896963608:839133237", "คัมภีร์แห่งความรวดเร็ว" },
        objective = { "170:819435255:1439445869", "นำ Libram of Rapidity, Pristine Black Diamond 1 ชิ้น, Large Brilliant Shard 2 ชิ้น และ Blood of Heroes 2 ชิ้นไปให้ Lorekeeper Lydros ใน Dire Maul เพื่อรับ Arcanum of Rapidity" },
        description = { "412:818333438:2055824627", "อาจารย์ Winthalus ทำ Libram of Rapidity หายในปีกตะวันออก คัมภีร์ทำให้ลงคาถาเร่งความเร็วเล็กน้อยบนอุปกรณ์ได้ กลกระจอกจริง ๆ...\n\nอย่างไร หากสนใจ เจ้าต้องนำคัมภีร์กับวัตถุดิบพื้นฐานมา\n\nอืม... ข้าว่าต้องมี Blood of Heroes, Pristine Black Diamond และ Large Brilliant Shard ด้วย อาจจำผิดก็ได้!\n\n<Lydros ยักไหล่>" },
        progress = { "42:2046228395:1503371422", "มีอะไร? ข้ายังมีงานจัดหมวดหมู่อีกมาก!" },
        completion = { "106:1474995579:712441447", "<Lydros หาว>\n\nตามสัญญา Arcanum of Rapidity อย่าใช้หมดในที่เดียวล่ะ\n\n<Lydros หัวเราะคิกคัก>" },
        required = { [12938] = { "15:1367295593:1665173685", "โลหิตวีรชน" }, [14344] = { "21:390863609:542366453", "เศษผลึกเจิดจ้าขนาดใหญ่" }, [18332] = { "18:1896963608:839133237", "คัมภีร์แห่งความรวดเร็ว" }, [18335] = { "22:140138788:1102101996", "เพชรดำไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Blood of Heroes"] = "โลหิตวีรชน", ["Large Brilliant Shard"] = "เศษผลึกเจิดจ้าขนาดใหญ่", ["Libram of Rapidity"] = "คัมภีร์แห่งความรวดเร็ว", ["Pristine Black Diamond"] = "เพชรดำไร้ตำหนิ" },
        },
    },
    [7484] = { -- Libram of Focus
        title = { "15:1090654478:1992848183", "คัมภีร์แห่งสมาธิ" },
        objective = { "163:903362007:1511305664", "นำ Libram of Focus, Pristine Black Diamond 1 ชิ้น, Large Brilliant Shard 4 ชิ้น และ Skin of Shadow 2 ชิ้นไปให้ Lorekeeper Lydros ใน Dire Maul เพื่อรับ Arcanum of Focus" },
        description = { "459:802382679:470324592", "คัมภีร์นี้แทบทำให้สัตว์รับใช้ของ Lorekeeper หนุ่มคนหนึ่งสนใจได้ เจ้าตัวน่าสงสารเพิ่งอายุไม่กี่สัปดาห์\n\nผู้ที่ถนัดเวทมนตร์ในหมู่เจ้าอาจสนใจของนี้\n\nLibram of Focus หายในปีกนี้ ข้าเดาได้เพียงว่าวิญญาณไฮบอร์นตนหนึ่งถืออยู่\n\nนำคัมภีร์พร้อม Large Brilliant Shard, Skin of Shadow และ Pristine Black Diamond มา แล้วข้าจะเสก Arcanum ให้" },
        progress = { "44:772580563:123399103", "เจ้าอีกแล้วหรือ? ทีนี้อยากได้อะไรอีก?" },
        completion = { "51:969492038:1631937444 R 1:46:46", "อย่าทำตัวเจ็บตอนลงอาคมล่ะ ชาว{race}" },
        required = { [12753] = { "14:1540196183:2053091107", "หนังแห่งเงา" }, [14344] = { "21:390863609:542366453", "เศษผลึกเจิดจ้าขนาดใหญ่" }, [18333] = { "15:1090654478:1992848183", "คัมภีร์แห่งสมาธิ" }, [18335] = { "22:140138788:1102101996", "เพชรดำไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Skin of Shadow"] = "หนังแห่งเงา", ["Large Brilliant Shard"] = "เศษผลึกเจิดจ้าขนาดใหญ่", ["Libram of Focus"] = "คัมภีร์แห่งสมาธิ", ["Pristine Black Diamond"] = "เพชรดำไร้ตำหนิ" },
        },
    },
    [7485] = { -- Libram of Protection
        title = { "20:794244155:1938615549", "คัมภีร์แห่งการคุ้มครอง" },
        objective = { "187:323423991:1661208373", "นำ Libram of Protection, Pristine Black Diamond 1 ชิ้น, Large Brilliant Shard 2 ชิ้น และ Frayed Abomination Stitching 1 ชิ้นไปให้ Lorekeeper Lydros ใน Dire Maul เพื่อรับ Arcanum of Protection" },
        description = { "504:164333654:1383180851", "เขาร้องไห้เหมือนทารกเมื่อคัมภีร์นี้หาย ข้าเองเคยร้องไห้เพื่อตำรา ไม่มีการสูญเสียใดใหญ่กว่าความรู้และประวัติศาสตร์ แต่ร้องเพราะคาถาปะปนแทบไร้ประโยชน์นี้หรือ? เหลวไหล! ข้าเลยคิดว่าเจ้าชายอาจช่วยเขาแล้วด้วยการถลกเนื้อจากกระดูก\n\nนำคัมภีร์กับ Pristine Black Diamond, Large Brilliant Shard และ Frayed Abomination Stitching มา ข้าจะสร้าง Arcanum ให้ใหม่\n\nอ้อ ลองดูปีกเหนือ" },
        progress = { "36:1485905218:642993340", "ความอดทนของข้าช่วยกันความทุกข์ให้เจ้าอยู่" },
        completion = { "61:415066550:1310518056", "ใช่ ใช่... สงบสติ ตามสัญญา นี่ Arcanum ของเจ้า" },
        required = { [12735] = { "28:1981933659:1764292030", "ตะเข็บลุ่ยของ Abomination" }, [14344] = { "21:390863609:542366453", "เศษผลึกเจิดจ้าขนาดใหญ่" }, [18334] = { "20:794244155:1938615549", "คัมภีร์แห่งการคุ้มครอง" }, [18335] = { "22:140138788:1102101996", "เพชรดำไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Frayed Abomination Stitching"] = "ตะเข็บลุ่ยของ Abomination", ["Large Brilliant Shard"] = "เศษผลึกเจิดจ้าขนาดใหญ่", ["Libram of Protection"] = "คัมภีร์แห่งการคุ้มครอง", ["Pristine Black Diamond"] = "เพชรดำไร้ตำหนิ" },
        },
    },
    [7488] = { -- Lethtendris's Web
        title = { "17:1055254887:830888355", "ตาข่ายของ Lethtendris" },
        objective = { "88:110677924:2060268806", "นำ Lethtendris' Web ไปให้ Latronicus Moonspear ที่ Feathermoon Stronghold ใน Feralas" },
        description = { "307:421416074:1880044794 N 180:1259116161:1334077148", "จอมเวท Lethtendris บลัดเอลฟ์ผู้โหดร้ายพอ ๆ กับการติดเวทอย่างวิปริต หนีเข้า Dire Maul นางสร้างตาข่ายดักพลังเวทของที่นั่น เรากลัวว่าหากไม่หยุด จะสร้างความเสียหายต่อโลกที่แก้คืนไม่ได้!\n\nหยุดนาง {name} หาแล้วนำตาข่ายมา นางคงอยู่ใกล้เซเทียร์ใน Warpwood Quarter ของ Dire Maul นำมาให้ข้าเพื่อปล่อยพลังคืนธรรมชาติอย่างปลอดภัย..." },
        progress = { "21:788863005:1892845280 N 53:1878581477:1812778200", "เจ้ามีตาข่ายหรือยัง {name}? ต้องกระจายพลังเวทเข้มข้นของมัน!" },
        completion = { "34:809261880:1404754038 N 271:1361239717:1753700082 N 136:904279557:1020313720", "เจ้านำตาข่ายมาแล้ว! ทำได้ดี {name}! Lethtendris เหมือนเอลฟ์พวกเดียวกันหลายคน มองไม่เห็นภัยจากการใช้เวทผิด พวกเขาคิดเป็นนายเวท แต่ไม่รู้ว่าเป็นทาสการเสพติด ข้าเสียใจกับความตายนาง ทว่าจำเป็น\n\nขอบใจ {name} ข้าจะปล่อยพลังในตาข่ายอย่างปลอดภัยให้กระจายกว้าง แล้วทำลายมันเพื่อกันการใช้เวทผิดอีก" },
        required = { [18426] = { "17:1055254887:830888355", "ใยของ Lethtendris" } },
        objectiveLabels = {
            item = { ["Lethtendris's Web"] = "ใยของ Lethtendris" },
        },
    },
    [7489] = { -- Lethtendris's Web
        title = { "17:1055254887:830888355", "ตาข่ายของ Lethtendris" },
        objective = { "69:1126065199:2062322556", "นำ Lethtendris's Web ไปให้ Talo Thornhoof ที่ Camp Mojache ใน Feralas" },
        description = { "501:1165390608:960812746", "บลัดเอลฟ์ Lethtendris ล้ำเส้นแล้ว นางหิวอำนาจเวทจนฝืนพวกเดียวกัน สร้างตาข่ายร้ายกาจเพื่อดูดพลังแปดเปื้อนของ Dire Maul แม้ตอนนี้ก็ยังเก็บพลัง เตรียมปล่อยใส่ศัตรู\n\nต้องหยุดนาง หาใน Warpwood Quarter ของ Dire Maul ปราบแล้วนำตาข่ายมาให้ข้า เพื่อส่งให้บลัดเอลฟ์ที่สุขุมกว่านี้ศึกษา" },
        progress = { "N 32:836312724:40351142", "{name} เจ้ามี Lethtendris's Web หรือยัง?" },
        completion = { "20:1921578502:569519135 N 281:37314575:1401885595 N 120:1508305189:1061182429", "ทำได้ดี {name} ตาข่ายเก็บพลังมหาศาลจาก Dire Maul ข้ากลัวความเสียหายหากคนไร้ความรับผิดชอบอย่าง Lethtendris ควบคุมมัน ข้าเสียใจที่นางตาย แต่รู้ว่าคงไม่ยอมพรากตาข่ายขณะมีชีวิต\n\nขอบใจ {name} ข้าจะส่งให้ผู้ศึกษาเวทที่รับผิดชอบกว่า พวกเขาจะเป็นผู้ดูแลพลังคนใหม่" },
        required = { [18426] = { "17:1055254887:830888355", "ใยของ Lethtendris" } },
        objectiveLabels = {
            item = { ["Lethtendris's Web"] = "ใยของ Lethtendris" },
        },
    },
    [7492] = { -- Camp Mojache
        title = { "12:463350117:1979040859", "Camp Mojache" },
        objective = { "53:1957164061:1203086455", "คุยกับ Talo Thornhoof ที่ Camp Mojache ใน Feralas" },
        description = { "185:1237357261:1049553872 N 52:1042597593:204877038", "Talo Thornhoof ผู้อาวุโสทอเรนใน Feralas ขอความช่วยเหลือ เขาให้รายละเอียดน้อย แต่บอกว่าต้องการเจ้าหน้าที่ในเรื่องละเอียดอ่อน... และร้ายแรง\n\nรับใช้ Horde เถิด {name} ไป Camp Mojache ใน Feralas แล้วคุยกับ Talo" },
        completion = { "24:1151404437:1722185038 C 48:91203321:1922366561 N 77:1355362049:448484722", "อา ดีใจที่{class}มาตามคำเรียก ข้าต้องการความช่วยเหลือ {name} และเกรงว่าจะพาเจ้าลงเส้นทางอันตราย...\n\nเส้นทางสู่ Dire Maul" },
    },
    [7494] = { -- Feathermoon Stronghold
        title = { "22:2131093851:1273480478", "ป้อมปราการ Feathermoon" },
        objective = { "73:19271776:1326101038", "คุยกับ Latronicus Moonspear ที่ Feathermoon Stronghold ใน Feralas" },
        description = { "N 395:1075874511:2070274493", "{name}! Feralas ต้องการให้เจ้าช่วย!\n\nจอมเวทนอกกฎหมาย Lethtendris หนีไปซากเอลฟ์โบราณ Eldre'thalas ที่ตอนนี้เรียก Dire Maul เชื่อว่านางมีวัตถุพลังเวทอันตรายที่ต้องนำคืนมา\n\nLatronicus Moonspear ต้องการคนเข้า Dire Maul เพื่อนำวัตถุจากนาง\n\nรับใช้ Alliance! ไปหา Latronicus ที่ Feathermoon Stronghold ใน Feralas", variants = { { "N 395:997562025:956880324", "{name}! Feralas ต้องการให้เจ้าช่วย!\n\nจอมเวทนอกกฎหมาย Lethtendris หนีไปซากเอลฟ์โบราณ Eldre'thalas ที่ตอนนี้เรียก Dire Maul เชื่อว่านางมีวัตถุพลังเวทอันตรายที่ต้องนำคืนมา\n\nLatronicus Moonspear ต้องการคนเข้า Dire Maul เพื่อนำวัตถุจากนาง\n\nรับใช้ Alliance! ไปหา Latronicus ที่ Feathermoon Stronghold ใน Feralas" } } },
        completion = { "6:1136836709:1914036474 N 142:36294621:1414459604", "สวัสดี {name} ข้าดีใจที่พบ แต่เสียใจที่เราไม่ได้พบกันในสถานการณ์น่ารื่นรมย์กว่านี้\n\nฟังให้ดี ข้ามีงานสำคัญให้เจ้า..." },
    },
    [7507] = { -- Nostro's Compendium
        title = { "19:28013738:888756859", "ประมวลความรู้ของ Nostro" },
        objective = { "62:1705304157:1898388802", "นำ Nostro's Compendium of Dragon Slaying กลับไปยัง Athenaeum" },
        description = { "229:536188757:58470403", "เจ้าพบสิ่งสำคัญยิ่ง หนังสือนี้ต่างจากทุกเล่มที่เคยเห็น\n\nดูเหมือนใครหรือบางสิ่งทำลายตราผนึก Athenaeum ข้อความภายในยุ่งเหยิงแทบอ่านไม่ได้" },
        progress = { "73:1056527837:1203607446", "อา หนึ่งในประมวลความรู้ชั้นยอดของเรา เล่มนี้หายไปนานนัก" },
        completion = { "77:1946443756:1608022052 N 307:693744290:1296093510", "เจ้าขายหนังสือนี้ในตลาดมืดได้ทองมากทีเดียว {name} โดยเฉพาะเมื่อตราคุ้มครองแตก ความลับสังหารมังกรจึงเปิดแก่ทุกคนที่มีปัญญาพอรับความรู้ในหน้าศักดิ์สิทธิ์\n\nบางทีควรมีรางวัลใหญ่... เอาละ รางวัลที่ต้องใช้ความพยายามมหาศาลจึงจะได้มา\n\n<Lydros ยิ้มกว้าง>" },
    },
    [7703] = { -- Unfinished Gordok Business
        title = { "26:1986565997:963335821", "ธุระ Gordok ที่ยังค้าง" },
        objective = { "236:1913615788:1922789776", "หา Gauntlet of Gordok Might แล้วนำกลับไปให้ Captain Kromcrush ใน Dire Maul\n\nตามที่ Kromcrush เล่า “เรื่องสมัยเก่า” บอกว่า Tortheldrin เอลฟ์ “น่าขนลุก” ที่เรียกตัวเองว่าเจ้าชาย ขโมยมันจากราชา Gordok คนหนึ่ง" },
        description = { "492:1024054476:370701568", "ตอนนี้เจ้าเป็นราชา บางทีเอาสมบัติล้ำค่า Gordok คืนจากเอลฟ์น่าขนลุกที่เรียกตัวเองว่าเจ้าชายได้! ราชาก่อนหน้าล้มเหลว เหมือนทุกคนตั้งแต่ Tortheldrin เจ้าเอลฟ์น่าขนลุก ขโมยมันจากราชา Gordok สมัยเก่า!\n\nของเรียกว่า Gauntlet of Gordok Might เรื่องสมัยเก่าว่ามีแต่ราชาแท้จริงของ Gordok ที่เอาคืนได้ ยังว่าเอลฟ์น่าขนลุกอยู่แถวนี้ หาให้พบ แล้วมันจะเป็นถุงมือทรงพลังที่เจ้าสวมตลอดไป! ยาร์ ข้าจะให้ดู!" },
        progress = { "130:437009304:1204771921", "ฮ่า หาไม่พบใช่ไหม นายใหญ่? บางทีเรื่องสมัยเก่าไม่ดี... เชื่อยากว่าเอลฟ์น่าขนลุกขโมยของราชา Gordok ได้!" },
        completion = { { "484:747230491:1441467793", "485:728482494:1786419120", "485:1765381627:1391888749", "486:400319512:1734015243" }, "ว้าว... เจ้าเป็นผู้ปกครองแท้จริง! ข้าไม่คิดว่าจะได้เห็นถุงมือนี้ในชีวิต! ดูเหมือนไม่มี Mojo แล้ว... บางทีเอลฟ์น่าขนลุกพยายามทำลาย ข้าขอหัวเราะเยาะมันเลย!\n\nดูสิ ตราบนถุงมือเป็นตราเวทเก่าเก่าเก่ามาก ว่ากันว่าเก่ากว่า Gordok ในฐานะกัปตัน Gordok เราเรียนเรื่องหนึ่งซ้ำแล้วซ้ำอีก วิธีปลุกตราให้มีชีวิต คืนพลังแก่ถุงมือ!\n\nข้าจะทำให้ ท่านผู้ปกครอง! รับไปแล้วปกครองตลอดกาล!" },
        required = { [18336] = { "24:1195804790:533061007", "ถุงมือเกราะพลังแห่ง Gordok" } },
        objectiveLabels = {
            item = { ["Gauntlet of Gordok Might"] = "ถุงมือเกราะพลังแห่ง Gordok" },
        },
    },
    [7877] = { -- The Treasure of the Shen'dralar
        title = { "31:483065421:1449319002", "สมบัติ Shen'dralar" },
        objective = { "84:1494892264:1869399238", "กลับ Athenaeum แล้วหา Treasure of the Shen'dralar ไปรับรางวัลของเจ้า!" },
        description = { "122:389395894:2016975610", "ในห้องสมุด Athenaeum มีหีบโบราณซ่อนใต้บันได จงหยิบสิ่งที่ต้องการจากมัน" },
        completion = { "29:1166232921:2100134704", "เจ้าเปิดหีบแล้วพบ..." },
    },
    [8945] = { -- Dead Man's Plea
        title = { "15:1739712087:862126714", "คำวิงวอนของคนตาย" },
        objective = { "64:1107884312:1689499266", "เข้า Stratholme แล้วช่วย Ysida Harmon จาก Baron Rivendare" },
        description = { "46:1519628841:577493601 N 310:585289686:178216951", "ข้าจะให้ข้อมูลที่เจ้าขอ {name} แต่ตอนนี้มีเรื่องเร่งด่วนกว่า\n\nภรรยาที่รักถูกพวกอันเดดสวะของ Rivendare จับ\n\nข้าค้านอย่างยิ่งที่นางเข้าร่วมสงครามบ้าของ Argent Dawn แต่ไม่สำคัญแล้ว เจ้าต้องทำสิ่งที่ข้าพยายามให้สำเร็จ ช่วย Ysida จากเงื้อมมือ Baron!" },
        progress = { "24:226948358:1865875002", "บอกข้า Ysida ยังมีชีวิตหรือไม่?" },
        completion = { "138:1217551456:1063161945", "ขอบใจที่ช่วย... ข้ากลัวว่าจะไม่รอด โปรดรับสิ่งนี้แทนความซาบซึ้งเล็กน้อย\n\nAnthion เขา... ไม่... เป็นไปไม่ได้..." },
    },
    [8948] = { -- Anthion's Old Friend
        title = { "20:403177245:1596851968", "สหายเก่าของ Anthion" },
        objective = { "91:1192954709:222820644", "นำ Banner of Provocation ที่ยังไม่สมบูรณ์ไปให้ Falrin Treeshaper ในห้องสมุด Dire Maul" },
        description = { "387:954679020:2065938624", "Theldren ไม่ยอมร่วมการต่อสู้ยุติธรรมง่าย ๆ ข้าจัดธงให้แสดงสีประจำตระกูลเขา\n\nเติมเวทอีกหน่อย ธงนี้จะยั่วจนเขาอดใจไม่ได้\n\nคนรู้จักเก่าชื่อ Falrin รู้วิธีแน่ชัด เขามีวิธี... ทำให้คนโกรธเป็นพิเศษ เจ้าจะพบในห้องสมุด Dire Maul" },
        progress = { "42:488341745:702810425", "พูดมา คนแปลกหน้า ไม่เห็นหรือว่าข้ายุ่ง?" },
        completion = { "160:1167003831:1002658074", "เจ้าว่า Anthion ส่งมาหรือ? ข้าคิดว่าเขาตายแล้ว คงเคยได้ยินเรื่องแปลกกว่านี้มาบ้าง\n\nเอาเถอะ อยากให้ข้าทำอะไรกับธง?" },
    },
    [8949] = { -- Falrin's Vendetta
        title = { "17:1463393542:1200026391", "แค้นของ Falrin" },
        objective = { "138:963697978:1964764031", "เก็บ Ogre Warbead 25 ชิ้นจากโอเกอร์ใน Dire Maul หรือ Blackrock Spire แล้วกลับไปหา Falrin Treeshaper ใน Athenaeum ของ Dire Maul" },
        description = { "70:2093835949:293592311 C 424:1288088628:1737169998", "จริง ข้ารู้อาคมที่เจ้าต้องการ {class} แต่ไม่ให้ความช่วยเหลือฟรี แม้สหายเก่าจะส่งมาก็ตาม\n\nข้ามีแต่ความเกลียดและดูถูกเพื่อนบ้านโอเกอร์ป่าเถื่อน ไม่เฉพาะที่นี่ ข้าเกลียดผู้ติดตาม Omokk พอ ๆ กับพวก King Gordok\n\nข้าอยากให้เจ้าฆ่า ฆ่าให้มาก! นำลูกปัดที่มันคล้องคอมาเป็นหลักฐาน แล้วค่อยคุยเรื่องคำขอเจ้า" },
        progress = { "45:1310214037:1911560411 N 1:63:63", "เจ้าช่วยตามที่ข้าขอแล้วหรือ {name}?" },
        completion = { "176:2108167394:1323993335", "อืม... น่าแปลก ข้าไม่รู้สึกดีขึ้นเลยกับการที่พี่น้องข้าตายด้วยมือพวกป่าเถื่อน\n\nอย่างไรเจ้าก็ทำตามข้อตกลง มาดูว่าข้าช่วยอะไรได้บ้าง" },
        required = { [21982] = { "13:2073292091:858558161", "ลูกปัดสงครามของโอเกอร์" } },
        objectiveLabels = {
            item = { ["Ogre Warbeads"] = "ลูกปัดสงครามของโอเกอร์" },
        },
    },
    [8950] = { -- The Instigator's Enchantment
        title = { "28:1336502421:242545409", "อาคมแห่งผู้ยั่วยุ" },
        objective = { "130:827666264:1982411503", "นำ Jeering Spectre's Essence 1 ชิ้น, Dark Rune 4 ชิ้น และ Large Brilliant Shard 8 ชิ้นไปให้ Falrin Treeshaper ใน Dire Maul" },
        description = { "68:492121491:39281149 N 324:1526511998:939262339", "ข้าลงอาคมบนธงให้ได้ง่าย {name} แต่ไม่มีวัสดุ เพราะน้อยคนขอมนตร์แบบนี้\n\nต้องใช้แก่นพลังผี Eldreth ที่หลอกหลอนห้องโถงเหล่านี้ รูนมืดจาก Scholomance กำมือหนึ่ง และ Large Brilliant Shard นำวัตถุดิบมาแล้วข้าจะทำให้" },
        progress = { "43:1087103523:78655811 N 1:63:63", "เก็บวัสดุที่ข้าต้องการแล้วหรือ {name}?" },
        completion = { "131:862170755:623438033", "ใช่ ใช้ได้ดี เมื่อข้าทำเสร็จ ไม่มีพลังใดในโลกหยุดเป้าหมายเจ้าจากการรับคำท้าได้" },
        required = { [22224] = { "25:1964455346:31857321", "แก่นพลังของวิญญาณเย้ยหยัน" }, [20520] = { "9:1052673578:52535548", "รูนมืด" }, [14344] = { "21:390863609:542366453", "เศษผลึกเจิดจ้าขนาดใหญ่" } },
        objectiveLabels = {
            item = { ["Jeering Spectre's Essence"] = "แก่นพลังของวิญญาณเย้ยหยัน", ["Dark Rune"] = "รูนมืด", ["Large Brilliant Shard"] = "เศษผลึกเจิดจ้าขนาดใหญ่" },
        },
    },
    [978] = { -- Moontouched Wildkin
        title = { "19:2145624253:103674784", "ไวลด์คินผู้รับแสงจันทร์" },
        objective = { "104:488369905:544453221", "เก็บ Moontouched Feather 10 ชิ้นจาก Winterspring แล้วกลับไปหา Erelas Ambersky ที่ Rut'theran Village" },
        description = { "413:1983657327:1328178455 N 92:21804659:1785428491", "ขนไวลด์คินจาก Hinterlands ดูเหมือนจะมีร่องรอยคุณสมบัติเวทมนตร์ พวกมันไม่ได้ใช้พลังนี้โดยตรง... ดูจะเป็นสิ่งที่ติดตัวเผ่าพันธุ์ เป็นส่วนหนึ่งของแก่นแท้ของพวกมันมากกว่า\n\nระหว่างศึกษาข้าได้ยินว่ามีไวลด์คินจำนวนมากอยู่ในแดนหิมะ Winterspring พวกมันจะมีพลังเดียวกันหรือไม่? ช่วยข้าหาคำตอบด้วย {name} ไป Winterspring เก็บขนที่ตกอยู่บนพื้น แล้วนำกลับมาให้ข้า" },
        progress = { "101:1566773087:1525126353 N 1:46:46", "พลังเหล่านี้มาจากไหนกัน? ข้าว่าเรากำลังมาถูกทางที่จะพบคำตอบแล้ว {name}" },
        completion = { "46:1741390889:2106541305", "ทีนี้ข้าก็เปรียบเทียบขนได้แล้ว... มาดูกัน..." },
        required = { [12383] = { "19:1719945835:1497499303", "ขนนกอาบแสงจันทร์" } },
        objectiveLabels = {
            item = { ["Moontouched Feather"] = "ขนนกอาบแสงจันทร์" },
        },
    },
    [979] = { -- Find Ranshalla
        title = { "14:1429111359:1426874370", "ตามหา Ranshalla" },
        objective = { "39:13569252:1203342092", "หา Ranshalla ทางตะวันออกของ Winterspring" },
        description = { "185:887403604:1000623540 N 169:286028999:1802527674", "ใช่แล้ว ขนเหล่านี้ดูจะมีมนตร์แบบเดียวกับที่ข้าเคยสังเกต... แม้ยังไม่แน่ใจว่าจะพบอะไร ข้าก็อยากให้เจ้าหาคำตอบต่อไป {name}\n\nเพื่อนร่วมงานคนหนึ่งของข้าเพิ่งไป Winterspring เพื่อสังเกตไวลด์คินในถิ่นอาศัยของพวกมัน ลองตามไปพบดูสิว่านางค้นพบอะไรบ้าง" },
        completion = { "108:117976592:823541187", "สวัสดี! Erelas ส่งเจ้ามาหรือ? ดีเลย ข้ากำลังเตรียมเดินทางขึ้นถ้ำพอดี มีเพื่อนไปด้วยก็ดีเหมือนกัน" },
    },
    [1048] = { -- Into The Scarlet Monastery
        title = { "26:1476474200:1517159934", "บุก Scarlet Monastery" },
        objective = { "164:464969750:1081363914", "สังหาร High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion และ Houndmaster Loksey แล้วรายงาน Varimathras ที่ Undercity" },
        description = { "391:104077274:168330767 C 69:422132916:1161027045", "ขณะที่ Dark Lady รับมือเรื่องเร่งด่วนอย่างการรุกคืบของ Lich King ทางเหนือ ข้าก็ดูแลให้ปัญหาใกล้บ้านได้รับการจัดการอย่างเหมาะสม\n\nแน่นอนว่าเจ้าพวกมนุษย์น่ารำคาญที่เรียกตนว่า Scarlet Crusade เป็นหนามตำใจที่แหลมคมที่สุดในบ้านเรา มดแดงตัวน้อยพวกนี้ยั้วเยี้ยเต็ม Tirisfal Glades\n\nไปอารามเถิด {class} กำจัด High Inquisitor Whitemane กับเหล่านายทหารคนสำคัญของนางเสีย" },
        progress = { "41:728533505:114781337 C 274:850495810:1981122713", "บางทีคำสั่งข้าอาจยังไม่ชัดพอ {class} ข้าต้องการให้ High Inquisitor Whitemane ตายเสียที และระหว่างนั้นก็กำจัดเหล่านายทหารระดับสูงของนางด้วย\n\nฆ่าเจ้าคลั่ง Scarlet Commander Mograine ทำลาย Herod, the Scarlet Champion และสังหาร Houndmaster Loksey กับฝูงหมาโสโครกของมันด้วย\n\nไปได้แล้ว!" },
        completion = { "36:50806148:907582612 C 130:1708128222:5996692", "เจ้ารับใช้ Dark Lady ได้ดี {class} งานที่ข้าขอให้ทำไม่ใช่เรื่องเล็ก\n\nความภักดีของเจ้าต่อ Forsaken ได้รับการจดจำแล้ว และความทรหดในการต่อสู้ของเจ้าก็จะไม่ถูกลืม" },
        objectiveLabels = {
            monster = { ["Scarlet Commander Mograine slain"] = "ปราบ ผู้บัญชาการ Mograine แห่ง Scarlet", ["High Inquisitor Whitemane slain"] = "ปราบ มหาตุลาการ Whitemane", ["Herod slain"] = "ปราบ Herod", ["Houndmaster Loksey slain"] = "ปราบ Loksey นายกองสุนัขล่าเนื้อ" },
        },
    },
    [1049] = { -- Compendium of the Fallen
        title = { "24:2043928390:964499364", "บันทึกผู้ล่วงลับ" },
        objective = { "124:1661502699:1256761221", "นำ Compendium of the Fallen จากอารามใน Tirisfal Glades กลับไปให้ Sage Truthseeker ที่ Thunder Bluff" },
        description = { "504:1719962651:1002591773", "Earthen Ring มีเจตนาบริสุทธิ์ต่อพี่น้องผู้ประสบโรคระบาดของเรา แต่ใครเล่าจะรู้เจตนาของผู้ที่คอยกระซิบข้างหูสภาผู้อาวุโส?\n\nForsaken ที่เราเป็นพันธมิตรด้วยมีอดีตเต็มไปด้วยการหลอกลวง เรารีบทำข้อตกลงเกินไป บางที Cairne น่าจะฟังคำเตือนจาก Orgrimmar\n\nลึกเข้าไปใน Scarlet Monastery มี Compendium of the Fallen อยู่ภายใต้การคุ้มกันของมนุษย์คลั่งศรัทธา วิธีการของพวกเขาเกิดจากความวิปลาส แต่งานค้นคว้าอาจมีประโยชน์" },
        progress = { "398:1064497226:966482201", "Cairne เป็นผู้นำที่กล้าหาญและสูงศักดิ์ ข้าฝากชีวิตไว้กับเขาได้ แต่ในสถานการณ์การเมืองเช่นนี้ ข้าไม่ไว้ใจคนอื่น\n\nเมื่อมีโอกาสรวบรวมความรู้ทั้งหมดที่หาได้ ข้าจะให้คำปรึกษาที่รอบคอบแก่หัวหน้าเผ่าได้\n\nเจ้าได้ไป Tirisfal Glades หรือยัง? ไป Scarlet Monastery หรือยัง? Compendium of the Fallen เป็นเพียงส่วนหนึ่งของปริศนาซับซ้อนนี้..." },
        completion = { "132:2137637485:1704016353 N 41:2116146618:1075492311", "Compendium of the Fallen! ข้าเริ่มสงสัยแล้วว่าหนังสือเล่มนี้มีอยู่จริงหรือไม่!\n\nเจ้าทำคุณให้ทอเรนแห่ง Thunder Bluff ได้ดี {name} ความทุ่มเทของเจ้าจะไม่ถูกลืม" },
        required = { [5535] = { "24:2043928390:964499364", "สารานุกรมว่าด้วยผู้ล่วงลับ" } },
        steps = { { "24:2043928390:964499364", "สารานุกรมว่าด้วยผู้ล่วงลับ" } },
    },
    [1050] = { -- Mythology of the Titans
        title = { "23:555260424:1057849534", "ตำนานแห่งไททัน" },
        objective = { "104:1975401003:515318678", "นำ Mythology of the Titans จากอารามไปให้ Librarian Mae Paledust ที่ Ironforge" },
        description = { "488:1213941325:1109462908", "อนาคตเป็นสิ่งหลีกเลี่ยงไม่ได้! เราพุ่งเข้าหามันเหมือนหยาดฝนที่ตกสู่ Great Sea\n\nแต่การศึกษาอดีตอาจทำให้เรารู้ว่าจะพบอะไร และเตรียมรับสิ่งที่ยังไม่รู้ได้ดีขึ้น\n\nก่อนภัยร้ายจะถาโถมใส่ Lordaeron เคยมีแหล่งความรู้ซ่อนอยู่ใน Tirisfal Glades เล่ากันว่าหนังสือ Mythology of the Titans อยู่ในห้องสมุดของอารามเก่า\n\nนำมาให้ข้า แล้วบางทีเราจะร่วมกันไขความลับแห่งอดีตได้!" },
        progress = { "476:1634482683:813129696", "อารามเคยเป็นสถานศึกษาของผู้ฝึกเป็นพาลาดิน จากที่มั่นแห่งแสงสว่างกลับตกไปอยู่ในมือพวกคลั่งศรัทธาของ Scarlet Crusade\n\nพวกเขาเชื่อว่าเป้าหมายตนสูงส่ง คือชำระแผ่นดินจากโรคระบาดอันเดด แต่ความวิปลาสทำให้ภารกิจแปดเปื้อน จนบัดนี้กลายเป็นศัตรูกับทุกฝ่าย\n\nนำ Mythology of the Titans มาให้ข้าศึกษาและเก็บรักษาที่ Ironforge\n\nห้องโถงอารามที่เสื่อมทรามไม่คู่ควรกับสมบัติทางประวัติศาสตร์เช่นนี้" },
        completion = { "185:1361250172:29467272 N 37:1367641776:1308573712", "เจ้าช่วยตำราศักดิ์สิทธิ์ไว้ได้แล้ว!\n\nการเดินทางยาวไกล และการได้หนังสือมาก็คงไม่ง่าย แต่เหล่าคนแคระแห่ง Ironforge จะได้ประโยชน์จากความสำเร็จของเจ้า\n\nในนาม Explorers' League ข้าขอบใจเจ้า {name}" },
        required = { [5536] = { "23:555260424:1057849534", "เทวตำนานแห่งไททัน" } },
        steps = { { "23:555260424:1057849534", "เทวตำนานแห่งไททัน" } },
    },
    [1051] = { -- Vorrel's Revenge
        title = { "16:1588892006:1490295170", "การล้างแค้นของ Vorrel" },
        objective = { "70:1745067783:997233035", "คืนแหวนแต่งงานของ Vorrel Sengutz ให้ Monika Sengutz ที่ Tarren Mill" },
        description = { "488:675714562:969400244", "แม้เจตจำนงของข้าจะเป็นอิสระ แต่ข้าไม่อาจรับใช้ Dark Lady ต่อไปแล้ว ข้ารู้สึกว่าเวลาของข้าบน Azeroth สิ้นสุดลง พลังชีวิตข้าแตกสลาย\n\nInterrogator Vishas ทำกับข้าเช่นนี้! ทรมานข้าอยู่หลายสัปดาห์! มันเอาแหวนแต่งงานของข้าไปให้ภรรยาของมัน เจ้าสารเลว!\n\nล้างแค้น... ข้าต้องการล้างแค้น!\n\nเจ้าโง่หยิ่งผยองนั่นคุยโวถึง Nancy ภรรยาสุดรักที่อาศัยริม Lake Lordamere ตามหานาง ฆ่านาง แล้วนำแหวนแต่งงานของข้ากลับไปให้ Monika ภรรยาข้าที่ Tarren Mill\n\nทำตามคำขอสุดท้ายของข้าด้วย..." },
        progress = { "27:436083576:106409603", "เจ้าต้องการอะไร คนแปลกหน้า?" },
        completion = { "253:1405202547:561049017", "Vorrel มีชีวิตที่ทุกข์ยากเหลือเกิน ทั้งที่เขาเป็นคู่ชีวิตที่ดีแท้ ๆ...\n\nขอสาปแช่งมนุษย์โสโครกพวกนั้น!\n\nVorrel จากไปแล้ว ไม่มีวันได้ใช้ชีวิตอันเดดอีก อย่างน้อยข้าก็ยังปลอบใจตนได้ว่าเจ้าล้างแค้นในนามเขาแล้ว ขอบใจสำหรับเรื่องนั้น\n\nทีนี้ปล่อยให้ข้าไว้ทุกข์เถิด..." },
        required = { [5538] = { "21:1685411968:862744346", "แหวนแต่งงานของ Vorrel" } },
        steps = { { "21:1685411968:862744346", "แหวนแต่งงานของ Vorrel" } },
    },
    [1053] = { -- In the Name of the Light
        title = { "24:2053741098:1026195426", "ในนามแห่งแสงสว่าง" },
        objective = { "168:1620379354:1265025458", "สังหาร High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion และ Houndmaster Loksey แล้วรายงาน Raleigh the Devout ที่ Southshore" },
        description = { "467:1750541252:2066209800 N 35:2097297194:455860140", "ข้าเคยรับใช้ Scarlet Crusade ด้วยเกียรติ ความภักดี และความภาคภูมิใจ เชื่อว่าพวกเขามีอุดมการณ์สูงส่งในการกำจัดอันเดดจาก Azeroth\n\nแต่เมื่ออยู่ที่อารามใน Tirisfal Glades ข้าก็ตระหนักว่าพวกเขากำลังหลุดจากความเป็นจริง บัดนี้คิดว่าทุกคนที่ไม่สวมเสื้อคลุมสัญลักษณ์ Crusade ติดโรคระบาด ชายหญิงบริสุทธิ์ถูกทรมานเพียงเพราะถูกกล่าวหาว่าติดโรค\n\nต้องบดขยี้ Scarlet Crusade ในนามแห่งแสงสว่าง {name} เจ้าต้องทำลายระบอบบ้าคลั่งนี้" },
        progress = { "417:1596590718:1381842353", "ความเสื่อมทรามในอารามจะไม่จบจนกว่าจะกำจัดผู้บังคับบัญชาระดับสูงสุด\n\nในนามแห่งแสงสว่าง จงสังหาร High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion และ Houndmaster Loksey เมื่อพวกเขาล้มลง บางทีอุดมการณ์แท้จริงอาจฟื้นขึ้นมาได้ ก่อนถึงวันนั้น ทุกคนที่ขวางทาง Crusade ยังตกอยู่ในอันตราย\n\nออกเดินทางจาก Southshore แล้วจัดการให้สำเร็จ!" },
        completion = { "248:1605771683:667802080 N 25:1689874688:1511986318", "สาวกแห่งแสงสว่างไม่เคยยินดีกับการสูญเสียชีวิต แต่เราต้องยอมรับว่าบางครั้งการเสียสละเช่นนี้จำเป็นต่อประโยชน์ที่ยิ่งใหญ่กว่าของอาณาจักรและโลก\n\nสิ่งที่เจ้าทำในอารามช่วยชีวิตผู้บริสุทธิ์ไว้มากมาย {name} ข้ายกย่องความทรหดของเจ้า" },
        objectiveLabels = {
            monster = { ["Scarlet Commander Mograine slain"] = "ปราบ ผู้บัญชาการ Mograine แห่ง Scarlet", ["High Inquisitor Whitemane slain"] = "ปราบ มหาตุลาการ Whitemane", ["Herod slain"] = "ปราบ Herod", ["Houndmaster Loksey slain"] = "ปราบ Loksey นายกองสุนัขล่าเนื้อ" },
        },
    },
    [1113] = { -- Hearts of Zeal
        title = { "14:555334422:312698573", "หัวใจผู้คลั่งศรัทธา" },
        objective = { "68:364790103:844461992", "Master Apothecary Faranell ที่ Undercity ต้องการ Heart of Zeal 20 ชิ้น" },
        description = { "486:568465781:703225902", "เจ้าอาจสงสัยว่าข้าต้องการมูลสัตว์ชนิดหายากไปทำไม สำหรับการทดลองนี้ข้าอยากเห็นผลของสารเคมีที่มีคุณสมบัติตรงข้ามกันสุดขั้ว โดยเฉพาะเมื่อผสมกับสารพิษที่คงความเป็นพิษเสมอ เพื่อรับประกันผลลัพธ์ที่... สยดสยองที่สุด\n\nScarlet Monastery อยู่บนยอดเขาทางตะวันออกเฉียงเหนือของ Tirisfal Glades เหล่าสาวกบ้าคลั่งแห่ง Scarlet Crusade รวมตัวกันที่นั่น ฆ่าพวกเขาแล้วนำหัวใจอันคลั่งศรัทธามาให้ข้า\n\nสารผสมของเราจะชั่วร้ายที่สุด!" },
        progress = { "196:1571709095:373793855", "กลับจาก Scarlet Monastery แล้วหรือ? ข้าต้องใช้หัวใจมากมายในการทดลองแสนสนุกนี้!\n\nแน่นอนว่า Varimathras และ Dark Lady ก็คงยินดีที่พ้นจากพวกสวะ Scarlet เช่นกัน..." },
        completion = { "50:1780608579:985190109 N 40:1303949839:2116575087", "ดูสิ เจ้าขนเลือดเนื้อมาให้มากมายเพียงใด {name}! เจ้าทำได้ยอดเยี่ยมจริง ๆ!" },
        required = { [5805] = { "13:1439622766:1587673999", "หัวใจแห่งความศรัทธา" } },
        steps = { { "13:1439622766:1587673999", "หัวใจแห่งความศรัทธา" } },
    },
    [1160] = { -- Test of Lore
        title = { "12:1934682095:1969211033", "บททดสอบความรู้" },
        objective = { "90:1377567816:1495053459", "หา The Beginnings of the Undead Threat แล้วนำกลับไปให้ Parqual Fintallas ที่ Undercity" },
        description = { "485:586476274:1267369229", "ข้าจะบอกว่าต้องหาอะไร และจะถามคำถามเจ้าด้วย แต่ไม่ใช่เพราะเจ้าอยากพิสูจน์ตน ความรู้สำคัญกว่าพละกำลังมาก แม้คนอื่นจะดูเก่งกาจแซงหน้าเจ้า ความรู้เรื่องโลกของเจ้าก็จะมีค่ากว่า\n\nไปอารามทางเหนือของ Tirisfal Glades ในห้องสมุดมีหนังสือ Beginnings of the Undead Threat เหล่าพาลาดินที่บัดนี้เสื่อมทรามเคยใช้ฝึกต่อสู้กับเผ่าพันธุ์ของข้า\n\nนำมาให้ข้า" },
        progress = { "481:502064960:414147681", "หวังว่าเจ้าจะทำให้ Scarlet Crusade เจ็บปวดสักหน่อยก่อนขโมยหนังสือมา\n\nความเห็นของข้าต่อพวกเขาไม่ได้ไร้เหตุผล ครั้งหนึ่ง Crusade อาจเคยติดตามแสงสว่าง แต่ตอนนี้กลับพยายามทำลายสิ่งมีชีวิตทุกชนิดที่ไม่เข้าร่วมศาสนาตน พวกเขาเชื่อว่าต้องชำระล้างอันเดดทั้งหมด ไม่ว่า Forsaken หรือพวกอื่น และใครที่เดินทางในแดนของอันเดดก็ต้องบ้าหรือถูกเวทมนตร์ทรงพลังครอบงำ โง่เง่า โง่เขลากันทั้งนั้น" },
        completion = { "328:1479390779:1203884369", "นี่คือหนังสือที่ข้าส่งเจ้าไปหา\n\n<Parqual ค่อย ๆ ลูบปกหนังสือขณะก้มมองมัน>\n\nทีนี้เจ้าก็ต้องการคำถามเพื่อพิสูจน์ว่าปัญญาแข็งแกร่งเท่ากายและใจ หากศึกษาหนังสือมานานพอแล้ว ข้าจะถามคำถาม แล้วเจ้าจะได้จบบททดสอบเสียที!" },
        required = { [5861] = { "31:74082166:570872810", "จุดเริ่มต้นของภัยอันเดด" } },
        steps = { { "31:74082166:570872810", "จุดเริ่มต้นของภัยอันเดด" } },
    },
    [1445] = { -- The Temple of Atal'Hakkar
        title = { "25:305882153:1040444986", "วิหาร Atal'Hakkar" },
        objective = { "69:941161625:1118200202", "รวบรวม Fetish of Hakkar 20 ชิ้น แล้วนำไปให้ Fel'Zerul ที่ Stonard" },
        description = { "484:435657469:1259971686", "เขาพูดถึงคำทำนายของ Jammal'an หรือ?\n\nผู้นำทางจิตวิญญาณของ Atal'ai เชื่อว่าเมื่อ Hakkar กลับสู่ Azeroth จาก Nether เทพเจ้าจะประทานความเป็นอมตะให้เผ่า Atal'ai\n\nข้าว่าเป็นอุบายโง่เขลาที่จะเร่งวันสิ้นโลกให้มาถึงก่อนเวลา\n\nแต่เจ้าบอกว่าผู้ถูกเนรเทศพูดถึงเครื่องรางลงมนตร์หรือ? เรื่องนี้ทำให้ข้ากังวลมาก หากมันเป็นกุญแจของพิธี Atal'ai ที่ก่อเรื่องวุ่นวายนี้จริง เราต้องเข้าใจพลังที่อยู่ภายใน\n\nบุกวิหารแล้วชิงเครื่องรางมา!" },
        progress = { "154:1374655395:280666578", "หากเครื่องราง Atal'ai มีพลังเรียก Hakkar และทำให้คำทำนาย Jammal'an เป็นจริง เราต้องยึดมันมา Horde ต้องเข้าใจพลังเช่นนี้!" },
        completion = { "6:1138691985:911572619 C 133:120082717:1099272851", "{class}ผู้กล้า เจ้าพิสูจน์แล้วว่าเป็นยอดผู้พิทักษ์แห่ง Horde\n\nทีนี้ต้องจัดการเครื่องราง Hakkar เหล่านี้ทันที!" },
        required = { [6181] = { "16:321586380:1553990456", "เครื่องรางของ Hakkar" } },
        objectiveLabels = {
            item = { ["Fetish of Hakkar"] = "เครื่องรางของ Hakkar" },
        },
    },
    [1446] = { -- Jammal'an the Prophet
        title = { "21:757940759:667924972", "Jammal'an ผู้เผยคำทำนาย" },
        objective = { "65:687452303:779482309", "Atal'ai Exile ที่ The Hinterlands ต้องการ Head of Jammal'an" },
        description = { "499:1256413959:1476215864", "สหาย Witherbark ของข้าไม่ชอบคนแปลกหน้าที่เข้ามาแถวบ้าน\n\nข้าหรือ? ข้าไม่มีบ้านอีกแล้ว ข้าถูกเนรเทศจากพวกพ้อง เผ่า Atal'ai อันยิ่งใหญ่แห่ง Swamp of Sorrows\n\nJammal'an ผู้นำทางจิตวิญญาณของเราอ้างว่ามีคำทำนาย เขาเชื่อว่าการเรียกเทพ Hakkar จะทำให้ Atal'ai เป็นอมตะ\n\nแต่ข้าเตือนให้ระวัง หากคำทำนายเป็นเพียงการชักใยเล่า?\n\nข้าต้องการล้างแค้นที่ถูกเนรเทศ นำศีรษะ Jammal'an มาให้ข้า บางทีพวกพ้องข้าจะเป็นอิสระเสียที" },
        progress = { "156:2018749974:1980777190", "เมื่อกำจัด Jammal'an แล้ว ข้าก็มีโอกาสกลับไปหาพวกพ้อง\n\nหากยังมีเขาเป็นผู้นำทางจิตวิญญาณ Atal'ai จะต้องพินาศแน่นอน" },
        completion = { "94:581629560:1320226571 C 76:2140176261:835855747", "ความเชื่ออย่างประมาทของ Jammal'an ในภาพนิมิตเท็จนำพวกพ้องข้าไปสู่หายนะชั่วนิรันดร์\n\nขอบใจ {class} ที่ล้างแค้นแทนข้าที่ถูกเนรเทศ ข้าโศกเศร้าให้พวกพ้อง ข้าไม่เหลือบ้านให้กลับไปแล้ว" },
        required = { [6212] = { "17:809002002:956038641", "ศีรษะของ Jammal'an" } },
        steps = { { "17:809002002:956038641", "ศีรษะของ Jammal'an" } },
    },
    [1475] = { -- Into The Temple of Atal'Hakkar
        title = { "30:411182384:669417876", "เข้าสู่วิหาร Atal'Hakkar" },
        objective = { "61:1588676066:110556103", "รวบรวม Atal'ai Tablet 10 แผ่นให้ Brohann Caskbelly ที่ Stormwind" },
        description = { "349:1414545304:301025457 N 150:761238197:705527659", "ตำนานเล่าว่า Temple of Atal'Hakkar เป็นศาสนสถานบูชา Hakkar the Soulflayer เทพโบราณ วิหารอยู่ในการดูแลของโทรลล์ดุร้ายเผ่า Atal'ai และว่ากันว่าไม่มีใครบุกเข้าไปได้\n\nบัดนี้วิหารจมอยู่ใต้ Pool of Tears การนำโบราณวัตถุออกมายิ่งยากกว่าเดิม แต่นั่นคืองานที่ข้าต้องการให้เจ้าทำ {name}\n\nช่วยรวบรวม Atal'ai Tablet ที่ยังสมบูรณ์มาให้ข้า แล้วข้าจะกลับ Explorers' Guild อย่างวีรบุรุษ เราจะแบ่งปันเกียรติยศร่วมกัน" },
        progress = { "54:1037120969:2064010316 N 326:1415074876:191303089 N 83:2007221755:97457484", "เมื่อชีวิตการงานของข้าใกล้ล่วงเข้าสนธยา ข้าจึงหันมาพึ่งเจ้า {name} ให้ช่วยภารกิจสุดท้ายของข้าเพื่อ Explorers' League หากกระดูกแก่ ๆ นี้ยังมีแรงฝ่า Swamp of Sorrows กับวิหารจมน้ำ ข้าคงไปต่อสู้เคียงข้างเจ้าแล้ว\n\nศักดิ์ศรีทำให้ข้าขอความช่วยเหลือในการเก็บ Atal'ai Tablet ได้ยาก แต่ความชราทำให้เลี่ยงไม่ได้\n\nช่วยข้าด้วย {name} ข้าอยากเกษียณจาก Explorers' League หลังทำคำขอสุดท้ายให้สำเร็จ" },
        completion = { "32:846859102:744735393 N 193:1121791019:757164125", "Atal'ai Tablet! ขอบใจเจ้า {name}!\n\nเมื่อข้านำไปส่ง Explorers' League ชื่อเราจะถูกจารึกในประวัติศาสตร์ร่วมกัน เจ้าช่วยคนแคระแก่ทำหน้าที่สุดท้ายในชีวิตสำเร็จ ข้าจะซาบซึ้งตลอดไป" },
        required = { [6288] = { "14:2004890371:794921305", "แผ่นจารึก Atal'ai" } },
        steps = { { "14:2004890371:794921305", "แผ่นจารึก Atal'ai" } },
    },
    [2768] = { -- Divino-matic Rod
        title = { "16:1788506043:1590856545", "คทา Divino-matic" },
        objective = { "71:1215895814:1123248714", "นำ Divino-matic Rod ไปให้ Chief Engineer Bilgewhizzle ที่ Gadgetzan" },
        description = { "446:141724038:736938423", "Sergeant Bly ขโมยของข้า! เขาบอกว่าแค่ยืม แต่กลับขโมยคทา Divino-matic สุดรักของข้าไป!! ไม่มีคทาแล้วข้าจะรู้ได้อย่างไรว่าควรขุดบ่อน้ำใหม่ตรงไหน??\n\nตามหา Bly แล้วเอาคทากลับมา! ได้ยินว่าเขานำพวกนักผจญภัยชื่อเสียไปล่าสมบัติใน Zul'Farrak ทางตะวันตก ข้าว่าเจ้าจะพบเขาที่นั่น\n\nหวังว่าโทรลล์จะจัดการเขาไปแล้ว เพราะหากต้องสู้กับเขาเพื่อชิงคทา เจ้าจะเจอศึกหนักแน่" },
        progress = { "59:746477448:268383589", "พบ Sergeant Bly หรือยัง? ได้คทา Divino-matic ของข้ามาหรือไม่?" },
        completion = { "25:1486619093:925120272 N 91:2135856826:845920611", "เจอแล้ว! ทำได้ดี {name}! ต้องสู้กับ Bly เพื่อชิงมาหรือเปล่า? หวังว่าเจ้าจะอัดเขากับพวกให้น่วมไปเลย!" },
        required = { [8548] = { "16:1788506043:1590856545", "คทา Divino-matic" } },
        steps = { { "16:1788506043:1590856545", "คทา Divino-matic" } },
    },
    [2770] = { -- Gahz'rilla
        title = { "10:1210876705:1181050351", "Gahz'rilla" },
        objective = { "82:692222985:1437098953", "นำ Gahz'rilla's Electrified Scale ไปให้ Wizzle Brassbolts ที่ Shimmering Flats" },
        description = { "409:1284159410:745771479", "ลึกเข้าไปใน Zul'Farrak เมืองโทรลล์ทรายแห่ง Tanaris มีสระศักดิ์สิทธิ์ พวกโทรลล์เรียกสัตว์มหึมาออกมาจากสระนั้น! Gahz'rilla! มันดุร้ายจนแม้แต่เกล็ดยังมีพลังงานแล่นเปรี๊ยะ ข้าอยากนำพลังงานนั้นมาใช้กับรถ!\n\nนำเกล็ดอาบพลังไฟฟ้าของ Gahz'rilla มาให้ข้า!\n\nแต่การเรียก Gahz'rilla เป็นความลับที่โทรลล์ปิดบังไว้อย่างดี หากจะเผชิญหน้ามัน เจ้าต้องชิงความลับนั้นมาก่อน" },
        progress = { "80:1247367785:1496800446", "ได้เกล็ดมาหรือยัง? ข้าอดใจไม่ไหวแล้วที่จะลองวิธีต่าง ๆ ในการนำพลังงานมาใช้!" },
        completion = { "32:320746957:121777234 N 95:1966838419:478950832", "โอ้โฮ ได้เกล็ดมาแล้ว! ขอบใจ {name} ข้าแทบอดใจเริ่มลงมือไม่ไหว!\n\nแล้วเจ้าเห็น Gahz'rilla ด้วยหรือ? มันใหญ่เท่าที่เล่ากันไหม??" },
        required = { [8707] = { "30:976975461:1707839056", "เกล็ดอาบประจุไฟฟ้าของ Gahz'rilla" } },
        steps = { { "30:976975461:1707839056", "เกล็ดอาบประจุไฟฟ้าของ Gahz'rilla" } },
    },
    [2846] = { -- Tiara of the Deep
        title = { "17:1346532930:1380037672", "มงกุฎแห่งห้วงลึก" },
        objective = { "59:1719476412:1231724390", "นำ Tiara of the Deep ไปให้ Tabetha ที่ Dustwallow Marsh" },
        description = { "471:1909566295:389123445", "นานมาแล้วข้ามีเครื่องประดับงดงามชิ้นหนึ่ง Tiara of the Deep มันไม่ได้มีดีแค่ความสวย แต่ยังมีพลังยิ่งใหญ่สำหรับผู้รู้วิธีใช้\n\nเมื่อ Hydromancer Velratha ได้ยินเรื่องมงกุฎ นางก็อยากครอบครอง ส่งคนมาบ้านข้าแล้วขโมยไปตอนข้าไม่อยู่ พวกหัวขโมย!\n\nข้าต้องการมงกุฎคืน! ไป Zul'Farrak เมืองโทรลล์ใน Tanaris หา Velratha แล้วชิงมงกุฎมา คืนให้ข้าแล้วเจ้าจะได้รับความเอ็นดูจากข้า" },
        progress = { "23:5641091:1486074378 N 48:492587797:1956291463", "ได้มงกุฎมาหรือยัง {name}? Velratha รู้แล้วหรือยังว่าการเป็นศัตรูกับข้าต้องชดใช้อย่างไร?" },
        completion = { "93:1621831723:1787790760 N 158:951985387:2087283910", "ยอดเยี่ยม! เจ้าเจอมันแล้ว! และที่สำคัญไม่แพ้กันคือ Velratha ไม่มีมันอีก! ขอบใจ {name} ข้าจะติดหนี้บุญคุณเจ้าตลอดไป!\n\nถ้าก่อนหน้านี้ข้าดู... ใจร้ายไปหน่อย ก็อย่าใส่ใจเลย เจ้าจะพบว่าข้าเป็นมิตรกว่านี้มากกับคนที่ไม่ได้ขโมยของข้า" },
        required = { [9234] = { "17:1346532930:1380037672", "มงกุฎเล็กแห่งห้วงลึก" } },
        steps = { { "17:1346532930:1380037672", "มงกุฎเล็กแห่งห้วงลึก" } },
    },
    [2861] = { -- Tabetha's Task
        title = { "14:1561829953:531720523", "งานของ Tabetha" },
        objective = { "39:1157139981:1032079746", "คุยกับ Tabetha ที่ Dustwallow Marsh" },
        description = { "218:5551656:1674649456 N 169:1995418392:1832735222", "มีข่าวว่า Tabetha เพื่อนจอมเวทที่อยู่ลึกเข้าไปใน Dustwallow Marsh มีเรื่องค้างคาใจกับโทรลล์ทรายตนหนึ่งใน Zul'Farrak หากไปคุย นางจะเล่าให้ฟังเอง\n\nพาเพื่อนไปด้วยนะ {name} หาก Tabetha ส่งเจ้าเข้า Zul'Farrak เจ้าคงไม่อยากไปคนเดียว\n\nกระท่อมของ Tabetha อยู่ทางตะวันตกของ Theramore เหนือ Stonemaul Ruin ขึ้นไปนิดเดียว" },
        completion = { "97:1974465142:1357033726", "ใช่ ข้ามีเรื่องต้องสะสางกับโทรลล์ตนหนึ่ง ต้องจัดการมันให้กระดูกลั่นสักหน่อย ไม่สิ ให้ลั่นทุกชิ้นเลย!\n\nอยากช่วยข้าไหม?" },
    },
    [2864] = { -- Tran'rek
        title = { "8:1332830509:535525775", "Tran'rek" },
        objective = { "33:748459591:1022247506", "คุยกับ Tran'rek ที่ Gadgetzan" },
        description = { "365:751262708:191750321", "Tran'rek ลูกพี่ลูกน้องข้ากำลังลำบาก เขาสัญญาว่าจะส่งเปลือกแมลงปีกแข็งมาให้ตั้งหลายสัปดาห์แล้ว แต่ยังไม่ส่งสักที เขาเป็นญาติ ข้าจึงไม่อยากส่งใครไป Gadgetzan เพื่อหักอะไรบนตัวเขา\n\nช่วยไปคุยกับ Tran'rek แทนข้าได้ไหม? บอกให้รีบจัดของส่งมาก่อนข้าจะทำอะไรบุ่มบ่าม\n\nGadgetzan อยู่ทางเหนือของ Tanaris ใน Kalimdor" },
        completion = { "152:1710691464:1283348168", "สวัสดี!\n\nอ้อ เจ้าได้คุยกับ Krazek ญาติข้าหรือ? เขาเป็นอย่างไรบ้าง? หวังว่าอยู่ Booty Bay แล้วจะไปได้สวย...\n\nเจ้าว่าเปลือกแมลงหรือ? เอ่อ... ให้ข้าเล่าเรื่องหนึ่งก่อน..." },
    },
    [2865] = { -- Scarab Shells
        title = { "13:929872338:620939598", "เปลือกแมลงปีกแข็ง" },
        objective = { "57:804392612:1913127334", "นำ Uncracked Scarab Shell 5 ชิ้นไปให้ Tran'rek ที่ Gadgetzan" },
        description = { "492:819820308:339510913", "แมลงปีกแข็งแห่ง Tanaris มีเปลือกแข็งมาก! แข็งจนใช้สร้างอะไรได้สารพัด สารพัดจริง ๆ!\n\nความจริงเปลือกมีประโยชน์เสียจน... พวกมันถูกล่าจนเกือบสูญพันธุ์!\n\nข้ารู้ว่าที่ไหนยังมีอีก หากสัญญาว่าจะเอาเปลือกมาให้ ข้าจะบอกว่าพวกมันอยู่ไหน สัญญาไหม?\n\nตกลง พวกมันมีรังอยู่ใน Zul'Farrak ข้าว่าโทรลล์คงไม่ล่าพวกมันเอาเปลือก\n\nแต่เจ้าล่าได้! ไป Zul'Farrak แล้วนำเปลือกที่ไม่แตกร้าวมาให้ข้า!" },
        progress = { "105:1068771358:130749759", "ได้เปลือกมาหรือยัง? ญาติข้าที่ Booty Bay รอของอยู่ และเขากำลังหมดความอดทน!" },
        completion = { "33:1048998920:181020333 N 26:1269737775:1856683176", "โอ้ ดีเลย! ได้มาแล้ว!\n\nขอบใจ {name} เจ้าช่วยชีวิตข้าไว้จริง ๆ!" },
        required = { [9238] = { "22:1283691257:1318164010", "กระดองแมลงสคารับที่ไม่แตกร้าว" } },
        steps = { { "22:1283691257:1318164010", "กระดองแมลงสคารับที่ไม่แตกร้าว" } },
    },
    [2936] = { -- The Spider God
        title = { "14:2130685880:1249927245", "เทพแมงมุม" },
        objective = { "107:87539091:1784749059", "อ่าน Tablet of Theka เพื่อเรียนรู้ชื่อเทพแมงมุมของ Witherbark แล้วกลับไปหา Master Gadrin" },
        description = { "416:1822884016:482588369", "Witherbark บูชาเทพแมงมุม และเก็บพิษที่ร้ายแรงที่สุดจากนาง หากต้องการพิษ เจ้าต้องเรียกเทพของพวกเขาออกมา!\n\nแต่ต้องรู้ชื่อแท้จริงของนางก่อน ชื่อนั้นอยู่บนแผ่นจารึกที่ฝังในสุสานแห่งเมืองโทรลล์ Zul'Farrak ใน Tanaris โดยมี Theka the Martyr เฝ้าอยู่\n\nปราบ Theka หาแผ่นจารึกของเขาแล้วอ่านเพื่อรู้ชื่อเทพแมงมุม เมื่อรู้แล้วกลับมาหาข้า" },
        progress = { "34:1651925338:373296375", "รู้ชื่อเทพแมงมุมแล้วหรือ?" },
        completion = { "195:1560383471:1587437380", "อา Elortha no Shadra... จงกล่าวชื่อนี้เพียงเสียงกระซิบ เพราะการเอ่ยชื่อนั้นมีน้ำหนักมากในโลกวิญญาณ\n\nข้าจะเขียนลงบนแผ่นหนังและสร้างคาถาเรียกให้เจ้า..." },
        objectiveLabels = {
            event = { ["Find the Spider God's Name"] = "ค้นหาชื่อของเทพแมงมุม" },
        },
    },
    [2991] = { -- Nekrum's Medallion
        title = { "18:925858810:1855727454", "เหรียญของ Nekrum" },
        objective = { "67:42355380:1962562338", "นำ Nekrum's Medallion ไปให้ Thadius Grimshade ที่ Blasted Lands" },
        description = { "323:1308774314:178741561", "ข้าจะหาว่ากริฟฟอนของเจ้าอยู่ไหน แต่ก่อนอื่นเจ้าต้องทำอะไรให้ข้า มีโทรลล์ใน Zul'Farrak ชื่อ Nekrum Gutchewer ครอบครองเหรียญที่ข้าอยากศึกษาอย่างยิ่ง นำเหรียญนั้นมา แล้วข้าจะใช้พลังตามหา Sharpbeak\n\nZul'Farrak อยู่ข้ามทะเลไปทางตะวันตก ในทะเลทราย Tanaris" },
        progress = { "32:185117049:1640362843 N 64:1834289010:2039753878", "ได้ Nekrum's Medallion มาหรือยัง {name}? ภายในมีพลังซ่อนอยู่ที่ข้าร้อนใจอยากค้นพบ" },
        completion = { "236:1136934932:1410797276 N 43:463752948:309024561", "อา เหรียญของ Nekrum เล่ากันว่ามันทำให้โทรลล์มีอายุยืนผิดธรรมชาติ แต่ต้องแลกบางอย่าง ข้าหวังว่าจะหาวิธีใช้พลังเหรียญโดยเลี่ยง... ผลข้างเคียงอันไม่น่าพึงใจได้\n\nเจ้าช่วยข้าแล้ว {name} ทีนี้ข้าจะทำตามสัญญาในส่วนของข้า" },
        required = { [9471] = { "18:925858810:1855727454", "เหรียญตราของ Nekrum" } },
        objectiveLabels = {
            item = { ["Nekrum's Medallion"] = "เหรียญตราของ Nekrum" },
        },
    },
    [3042] = { -- Troll Temper
        title = { "12:1961046844:1369127451", "สารชุบแข็งของโทรลล์" },
        objective = { "67:1232915686:366691456", "นำ Vial of Troll Temper 20 ขวดไปให้ Trenton Lighthammer ที่ Gadgetzan" },
        description = { "293:46861582:67037269", "โทรลล์ Sandfury แห่ง Zul'Farrak ทำสารชุบแข็งจากหินทราย ข้านำมาใช้ชุบแข็งของที่สร้างได้ ใช่ ทำได้แน่! ผู้รู้ชื่นชอบมันมาก หากเจ้าหามาให้มากพอ ข้าจะตอบแทนอย่างงาม\n\nZul'Farrak อยู่ทางตะวันตกเฉียงเหนือของ Gadgetzan โชคดีล่ะ" },
        progress = { "29:269910893:924075810 N 1:63:63", "นำสารชุบแข็งมาให้ข้าหรือยัง {name}?" },
        completion = { "113:999010724:10743877 N 31:107405839:1227986523", "อา นี่เป็นสารชุบแข็งชั้นดีจริง ๆ! และมากมายเสียด้วย! คงต้องทำงานอีกหลายวันกว่าจะใช้หมด!\n\nขอบใจ {name} โปรดรับนี่เป็นค่าตอบแทน" },
        required = { [9523] = { "12:1961046844:1369127451", "น้ำยาชุบแข็งของโทรลล์" } },
        steps = { { "12:1961046844:1369127451", "น้ำยาชุบแข็งของโทรลล์" } },
    },
    [3373] = { -- The Essence of Eranikus
        title = { "23:1559561630:1184439515", "แก่นพลังของ Eranikus" },
        objective = { "92:1918519411:1237331171", "วาง Essence of Eranikus ลงใน Essence Font ที่อยู่ในรังแห่งนี้ภายใน Sunken Temple" },
        description = { "502:1587749633:1333228000", "เมื่อเจ้าแตะอัญมณี เสียงทุ้มลึกก้องขึ้นในจิต\n\n“ผู้เป็นมรรตัย จงฟังคำวิงวอน ข้าคือ Eranikus แห่ง Green Dragonflight ผู้ดูแลวิหารต้องสาปนี้ หน้าที่ของข้าที่ต้องกันไม่ให้โทรลล์เรียกเทพอัปลักษณ์ของตนกลับมาได้ล้มเหลวในเวลานี้ ขณะบรรจุแก่นพลังส่วนหนึ่งลงในอัญมณี ข้ารู้สึกว่าสายสัมพันธ์กับความฝันกำลังบิดเบี้ยวสู่ความโกลาหล โปรดวางอัญมณีในบ่อแก่นพลังที่รังของข้า ให้เวทมนตร์ที่นั่นชำระมลทินจากจิตข้า เพื่อข้าจะได้พักสงบ”" },
        progress = { "454:1374140726:1087576762", "เมื่อเจ้าเข้าใกล้บ่อแก่นพลังที่ Eranikus กล่าวถึง เสียงของเขาสัมผัสจิตเจ้าอีกครั้ง\n\n“ใช่ ผู้เป็นมรรตัย บ่อนี้จะกอบกู้ส่วนที่ยังไม่แปดเปื้อนของจิตข้าซึ่งอยู่ในอัญมณี วางอัญมณีลงในบ่อ ให้เวทมนตร์ของ Green Dragonflight ชำระความเสื่อมทรามและมลทินจากตัวข้า เมื่อนั้นเท่านั้นข้าจึงจะหลุดพ้นอย่างแท้จริง และฝูงมังกรจึงจะกลับมาดูแลควบคุม Atal'ai ได้อีก”" },
        completion = { "481:567109897:1863743642", "เจ้าวางอัญมณีลงในบ่อแก่นพลัง\n\n“ขอบใจ ผู้เป็นมรรตัย เจ้าได้... ไม่... นี่เป็นไปไม่ได้! ไม่! ความเสื่อมทรามของเทพต้องสาปตนนี้แปดเปื้อนแม้แต่บ่อแก่นพลังศักดิ์สิทธิ์ของ Green Dragonflight! ไม่นะ ได้โปรด ข้ารู้สึกว่าแก่นพลังถูกฉีกออกจากตัว! เจ็บเหลือเกิน! ฝันร้ายนิรันดร์กำลังยึดกุมข้า...”\n\n“ผู้เป็นมรรตัย ข้าวิงวอน! หาใครสักตนจาก Green Dragonflight ให้หยุดเรื่องนี้... ช่วยข้า... ข้าถูกล่ามในความมืด... ทรมานชั่วกาล... โปรดอย่าทรมาน...”" },
        required = { [10454] = { "19:1962163974:801444982", "แก่นพลังของ Eranikus" } },
        objectiveLabels = {
            item = { ["Essence of Eranikus"] = "แก่นพลังของ Eranikus" },
        },
    },
    [3446] = { -- Into the Depths
        title = { "15:1593647810:946038786", "สู่ห้วงลึก" },
        objective = { "66:2013662512:1273425068", "หา Altar of Hakkar ใน Sunken Temple ที่ Swamp of Sorrows" },
        description = { "489:2027945986:1815765938", "ในวิหาร ข้าพบห้องวงกลมมีระเบียงหกแห่ง แต่ละแห่งมีรูปปั้นงูอยู่ริมขอบ ด้วยความสงสัยข้าจึงผลักรูปปั้นหนึ่งดู แต่กลับเป็นกับดัก! แรงระเบิดเกือบทำให้ข้าตกลงไปตาย ขณะนอนอยู่บนชะง่อน ข้ามองลงไปเห็นรูปปั้นอีกองค์ที่ฐานห้อง คล้ายแท่นบูชา... ข้าคิดว่าชื่อ Hakkar\n\nข้าว่าแท่นนี้คือความลับ เจ้าต้องนำเหรียญนี้ไปยังแท่นบูชาใน Sunken Temple" },
        progress = { "114:980161989:1082571460", "เมื่อสำรวจรูปปั้น เจ้าพบรอยเว้าด้านข้าง ขนาดพอดีกับเหรียญที่ Marvon ให้มา..." },
        completion = { "206:834336470:621730850", "เจ้าผลักแผ่นหินกลมเข้าไปในช่อง แล้วได้ยินเสียงมันล็อกเข้าที่\n\nเมื่อหินเข้าที่แล้ว เจ้าก็ไปต่อได้... แต่ควรทำอะไรต่อ?\n\nบางทีควรสำรวจแท่นบูชานี้ให้ละเอียดขึ้น..." },
        required = { [10466] = { "20:1951115098:1640542275", "วงศิลา Atal'ai" } },
        steps = { { "20:1951115098:1640542275", "วงศิลา Atal'ai" } },
    },
    [3447] = { -- Secret of the Circle
        title = { "20:2006408558:716010998", "ความลับแห่งวงรูปปั้น" },
        objective = { "86:1290806595:2030984775", "เข้า Sunken Temple และค้นหาความลับที่ซ่อนอยู่ในวงรูปปั้น" },
        description = { "398:1654506206:1654865578 N 96:2088606526:1857150442", "ความทรงจำข้าเลือนราง แต่จะเล่าเท่าที่จำได้ วงรูปปั้นใน Sunken Temple แม้จะอันตราย ข้าก็เชื่อว่ามันซ่อนความลับที่จะเปิดไปสู่สมบัติยิ่งใหญ่กว่า\n\nจากแท่นบูชาหลัก ข้าทำให้แสงชุดหนึ่งสว่างขึ้นมาได้ หากเจ้าหาความหมายของแสงเหล่านี้ได้ บางทีอาจไขความลับที่ซ่อนอยู่ในห้องนี้\n\nแต่ข้าเตือนไว้ก่อน {name} ในวิหารมีความชั่วร้ายใหญ่หลวง สิ่งมีค่าคงถูกเฝ้าอย่างหวงแหน..." },
        completion = { "241:1324033852:1170528382", "ดวงตาของเทวรูปส่องประกายแม้ในวิหารสลัว ความใสของมันเผยให้เห็นบางสิ่งแวววาวด้านหลัง เจ้าเลื่อนมันไปข้าง ๆ สอดมือเข้าไปคว้าสิ่งที่อยู่ภายใน\n\nสมบัติ Atal'ai เป็นของเจ้าแล้ว" },
    },
    [3527] = { -- The Prophecy of Mosh'aru
        title = { "24:926702879:462140785", "คำทำนายแห่ง Mosh'aru" },
        objective = { "68:719143424:521756639", "นำ First Mosh'aru Tablet และ Second Mosh'aru Tablet ไปให้ Yeh'kinya ที่ Tanaris" },
        description = { "496:2140352591:1315437819", "คำทำนายโบราณแห่ง Mosh'aru กล่าวถึงวิธีกักเก็บแก่นพลังของเทพ Hakkar มันถูกเขียนไว้บนแผ่นจารึกสองแผ่น แล้วนำไปยังเมืองโทรลล์ Zul'Farrak ทางตะวันตกของ Gadgetzan\n\nนำแผ่นจารึก Mosh'aru มาให้ข้า!\n\nแผ่นแรกอยู่กับ Theka the Martyr โทรลล์ที่ตายไปนานแล้ว เล่ากันว่าผู้ที่เคยข่มเหงเขาถูกสาปเป็นแมลงปีกแข็งและยังวิ่งอยู่รอบศาลของเขา\n\nแผ่นที่สองอยู่กับ Hydromancer Velratha ใกล้สระศักดิ์สิทธิ์ของ Gahz'rilla\n\nเมื่อได้แผ่นจารึกแล้วนำมาให้ข้า" },
        progress = { "53:1778456552:697607862 N 93:788820411:8712988", "ได้แผ่นจารึกคำทำนาย Mosh'aru มาหรือยัง {name}?\n\nเมื่อได้มา ข้าจะศึกษาและเรียนรู้วิธีกักเก็บแก่นพลัง Hakkar!" },
        completion = { "120:135113674:2121240164 N 33:1228318800:1628531152", "อา ดีเลย ข้าจะเชื่อมแผ่นจารึกโบราณเข้าด้วยกัน แล้วศึกษาความลับที่ซ่อนอยู่\n\nข้าติดหนี้เจ้าเพิ่มขึ้นอีกแล้ว {name} และยังจะเพิ่มขึ้นอีก" },
        required = { [10660] = { "21:1188426126:1856661551", "แผ่นจารึก Mosh'aru แผ่นที่ 1" }, [10661] = { "22:1226735234:405702172", "แผ่นจารึก Mosh'aru แผ่นที่ 2" } },
        steps = { { "21:1188426126:1856661551", "แผ่นจารึก Mosh'aru แผ่นที่ 1" }, { "22:1226735234:405702172", "แผ่นจารึก Mosh'aru แผ่นที่ 2" } },
    },
    [3528] = { -- The God Hakkar
        title = { "14:861077980:1163020110", "เทพ Hakkar" },
        objective = { "55:223053408:1649057562", "นำ Filled Egg of Hakkar ไปให้ Yeh'kinya ที่ Tanaris" },
        description = { "493:166414649:1117747876", "ถึงเวลากักเก็บแก่นพลังของร่างอวตาร Hakkar แล้ว\n\nนำ Egg of Hakkar ไป Sanctum of the Fallen God ใน Sunken Temple แห่ง Azeroth เรียกพลังไข่เพื่อปลุกเทพที่ตายไปแล้ว\n\nมันจะส่งสมุนมาโจมตีเจ้า ปราบพวกดูดเลือดแล้วเอา Hakkari Blood มา ใช้เลือดดับเปลวไฟนิรันดร์ที่กักวิญญาณ Hakkar เมื่อไฟดับหมด ร่างอวตาร Hakkar จะเข้าสู่โลกเรา\n\nปราบมัน แล้วบรรจุแก่นพลังลงใน Egg of Hakkar" },
        progress = { "40:982560973:1184490618 N 51:997373376:1115929293", "ปราบร่างอวตาร Hakkar แล้วหรือ {name}? แก่นพลังของมันเติมพลังให้ไข่ที่ข้ามอบแล้วหรือยัง?" },
        completion = { "299:1629657906:671468884 N 87:784192099:146637790", "เก็บแก่นพลัง Hakkar ได้แล้ว! แม้ตอนนี้ไข่ยังขยับราวมีชีวิต! หรือตำนาน Hakkar จะจริง?\n\nต้องไม่เป็นเช่นนั้นสิ เพราะข้ากลัวสิ่งที่ Hakkar จะทำหากเกิดใหม่ ข้าจะเก็บไข่ไว้อย่างปลอดภัย ไม่ให้ตกในมือผู้ชั่วร้าย\n\nงานที่เจ้าทำร่วมกับข้าจบแล้ว {name} เจ้าได้สัมผัสตำนาน และสักวันการกระทำของเจ้าอาจเปลี่ยนโฉมหน้าโลกของเรา" },
        required = { [10662] = { "20:957412753:2000554036", "ไข่ของ Hakkar ที่เติมแล้ว" } },
        steps = { { "20:957412753:2000554036", "ไข่ของ Hakkar ที่เติมแล้ว" } },
    },
    [3661] = { -- Favored of Elune?
        title = { "17:2100049766:1040738507", "ผู้ได้รับความโปรดปรานจาก Elune?" },
        objective = { "91:1608269314:2073709311", "รวบรวม Wildkin Feather 15 ชิ้นจาก Hinterlands ให้ Erelas Ambersky ที่ Rut'theran Village" },
        description = { "43:1377973354:328145558 N 453:76554586:122127655", "ไวลด์คินเป็นสิ่งมีชีวิตที่คาดเดาได้ยาก {name} พวกมันอ่อนโยนได้อย่างยิ่ง แต่จะดุร้ายสุดขีดเมื่อสิ่งที่เห็นว่าสำคัญถูกคุกคาม\n\nเล่ากันว่า Elune สร้างพวกมันขึ้น ข้าสนใจอยากรู้ว่าเป็นเรื่องจริงหรือไม่\n\nไม่นานมานี้ข้าได้ยินว่ามีไวลด์คินอยู่ใน Hinterlands ได้แก่ Vicious Owlbeast, Primitive Owlbeast และ Savage Owlbeast พบได้ในหมู่สัตว์ป่าที่นั่น เจ้าจะช่วยเก็บขนไวลด์คินให้ข้าไหม?" },
        progress = { "30:701018646:527989351 N 71:1591328996:1532216301", "พยายามหลีกเลี่ยงพวกมันหากทำได้ {name} ไวลด์คินอาจเข้าใจความสนใจของเจ้าผิดว่าเป็นเจตนาทำร้าย..." },
        completion = { "36:1240599596:190169863 N 266:1364573654:1221770019", "ขอบใจที่นำมาให้ข้า {name}\n\nเจ้าเรียนรู้อะไรเกี่ยวกับไวลด์คินบ้าง?\n\nบางทีขนเหล่านี้จะบอกเราได้มากขึ้น เป็นอสูรดุร้ายหรือเพียงสัตว์เลี้ยงที่หลงผิด? สักวันข้าอยากรู้ความจริง...\n\nข้าจะค้นคว้าต่อ โปรดกลับมาคุยอีกเมื่อเวลาผ่านไปสักพัก" },
        required = { [10819] = { "15:537724825:580256413", "ขนของ Wildkin" } },
        steps = { { "15:537724825:580256413", "ขนของ Wildkin" } },
    },
    [3788] = { -- Jonespyre's Request
        title = { "19:1422667886:237074412", "คำขอของ Jonespyre" },
        objective = { "55:2083273900:48785798", "คุยกับ Quintis Jonespyre ที่ Feathermoon Stronghold" },
        description = { "466:2115210249:1259926164", "ขอรบกวนหน่อย สหาย...\n\nเพื่อนร่วมงานของข้าอยากคุยกับเจ้าเกี่ยวกับงานวิจัยที่เจ้าทำร่วมกับ Cenarion Circle เขาเป็นดรูอิดชื่อ Quintis Jonespyre อยู่ที่ Feathermoon Stronghold นี่เอง เขาอยากปรึกษาเรื่อง Morrowgrain... และอยากอย่างยิ่งให้เจ้าเก็บเรื่องสนทนาของเราให้พ้นหู Arch Druid\n\nหากสนใจก็ไปคุยกับเขา แล้วทุกอย่างคงกระจ่างเอง" },
        completion = { "486:930292661:867955524", "ขอบใจที่มา นักเดินทางผู้เหนื่อยล้า! ขอแนะนำตัว ข้าคือ Quintis Jonespyre ดรูอิดและผู้รับใช้อันถ่อมตนของ Malfurion กับ Cenarion Circle ข้ากับเพื่อนร่วมงาน ได้แก่ General Shandris Feathermoon และ Protectorate ซึ่งเจ้าอาจเคยได้ยินชื่อ อยากคุยเรื่องงานที่เจ้าทำให้ Fandral Staghelm ใน Darnassus\n\nก่อนคุยต่อ ข้าขอให้เรื่องนี้อยู่ระหว่างเราเท่านั้น หากเจ้าไม่ขัดข้อง เราก็เริ่มได้" },
    },
    [3791] = { -- The Mystery of Morrowgrain
        title = { "26:1159163198:1136770490", "ปริศนาแห่ง Morrowgrain" },
        objective = { "68:1473052733:1971503684", "นำ Morrowgrain 10 ชิ้นไปให้ Quintis Jonespyre ที่ Feathermoon Stronghold" },
        description = { "29:1627431860:1651956706 N 457:1644175452:1600300595", "ข้าขอพูดตรง ๆ {name} ข้าสนใจ... ไม่สิ กังวลต่างหาก ว่าเหตุใด Arch Druid ใน Darnassus จึงใช้ทั้งนามและทรัพยากรของ Cenarion Circle เพื่อจัดหา Morrowgrain จำนวนมหาศาล ข้าเป็นนักวิจัย เชี่ยวชาญเรื่องคำสาป ได้ยินว่าในสภาวะเหมาะสม Morrowgrain จะแสดงคุณสมบัติคล้ายสมุนไพรที่ใช้ในคำสาปดั้งเดิม\n\nข้าอยากรู้ให้มากขึ้น จึงขอให้เจ้าช่วย นำ Morrowgrain สิบชิ้นมา แล้วข้าจะดูแลตอบแทนเจ้าแน่นอน" },
        progress = { "194:1165503722:1711875303", "ข้าต้องการ Morrowgrain สิบชิ้น อย่างน้อยก็น่าจะพอเริ่มงานวิจัย คงใช้เสียไปมากจากการลองผิดทาง แต่นั่นคือธรรมชาติของงานวิจัย" },
        completion = { "453:278595292:254972120", "อึ๋ย Morrowgrain ทำให้ข้ารู้สึก... แปลก ๆ ในนาม Elune เจ้า Staghelm คิดทำอะไรกับของพวกนี้กัน?\n\nอย่างไรก็ขอบใจที่ช่วยอีกครั้ง นี่ของตอบแทนเล็กน้อย... สำหรับความพยายาม งานวิจัย Morrowgrain คงใช้เวลาพักใหญ่ และข้าต้องการอีกแน่นอน ระหว่างนั้นอาจหาเวลาตรวจด้วยว่ามันมีประโยชน์ทางเล่นแร่แปรธาตุที่เกี่ยวข้องหรือไม่ แต่แม้อยู่ใกล้มันข้าก็ยังรู้สึกไม่สบายใจ" },
        required = { [11040] = { "11:35561619:35128800", "มอร์โรว์เกรน" } },
        objectiveLabels = {
            item = { ["Morrowgrain"] = "มอร์โรว์เกรน" },
        },
    },
    [3792] = { -- Morrowgrain to Feathermoon Stronghold
        title = { "37:2109942815:1066292603", "Morrowgrain สู่ Feathermoon Stronghold" },
        progress = { "13:1366380142:1891123769 N 291:669977018:2029076139", "สวัสดีอีกครั้ง {name} งานวิจัยคืบหน้าค่อนข้างดี หากมี Morrowgrain อีกห้าชิ้น ข้าก็ยินดีรับไว้ เอ่อ... คำว่ายินดีในที่นี้เป็นเพียงคำเปรียบ ยิ่งอยู่ใกล้ก็ยิ่งไม่สบายใจ แต่การวิจัยทำให้ข้าต้องตั้งใจอดทนทำให้ผ่านไป" },
        completion = { "7:531359820:773804707 N 417:1768205398:317694122", "ขอบใจ {name} ข้าจะเก็บไว้ให้พ้นทางก่อน แม้ไม่มีทรัพยากรเท่า Staghelm ข้าก็พอมีของเล็กน้อยตอบแทนความลำบากของเจ้า ใครจะรู้ว่าจะเกิดอะไรขึ้นหาก Staghelm ได้ Morrowgrain เพิ่มไปเรื่อย ๆ จำคำข้าไว้ มีอะไรไม่ชอบมาพากลแน่\n\nจำไว้ว่าข้าต้องการ Morrowgrain เพิ่มเสมอ ข้ารับครั้งละห้าชิ้น" },
        description = { "13:1366380142:1891123769 N 291:669977018:2029076139", "สวัสดีอีกครั้ง {name} งานวิจัยคืบหน้าค่อนข้างดี หากมี Morrowgrain อีกห้าชิ้น ข้าก็ยินดีรับไว้ เอ่อ... คำว่ายินดีในที่นี้เป็นเพียงคำเปรียบ ยิ่งอยู่ใกล้ก็ยิ่งไม่สบายใจ แต่การวิจัยทำให้ข้าต้องตั้งใจอดทนทำให้ผ่านไป" },
        required = { [11040] = { "11:35561619:35128800", "มอร์โรว์เกรน" } },
        objectiveLabels = {
            item = { ["Morrowgrain"] = "มอร์โรว์เกรน" },
        },
    },
    [5250] = { -- Starfall
        title = { "8:573900391:1614180234", "Starfall" },
        objective = { "62:518788792:433139421", "หา Starfall ใน Winterspring แล้วคุยกับ Wynd Nightchaser" },
        description = { "492:821680107:1887811562", "Winterspring ทางเหนือของ Felwood มีซากอารยธรรมเอลฟ์โบราณมากมาย แม้เป็นแดนทุรกันดาร แต่ก็มีความลับและสถานที่ให้สำรวจมาก\n\nการศึกษาที่นี่ทำให้ข้ายุ่งจนไม่ได้เดินทางไป Winterspring มาพักหนึ่งแล้ว แต่เจ้าก็เดินทางไปศึกษาซากเหล่านั้นได้\n\nระหว่างอยู่ที่นั่น จงหา Wynd Nightchaser เขาใช้เวลาส่วนใหญ่ใน Starfall และรู้จักพื้นที่ดี\n\nบอกเขาว่าเจ้าเป็นศิษย์ของข้า...", variants = { { "496:1008535396:480548526", "Winterspring ทางตะวันออกเฉียงเหนือของ Felwood มีซากอารยธรรมเอลฟ์โบราณมากมาย แม้เป็นแดนทุรกันดาร แต่ก็มีความลับและสถานที่ให้สำรวจมาก\n\nการศึกษาที่นี่ทำให้ข้ายุ่งจนไม่ได้เดินทางไป Winterspring มาพักหนึ่งแล้ว แต่เจ้าก็เดินทางไปศึกษาซากเหล่านั้นได้\n\nระหว่างอยู่ที่นั่น จงหา Wynd Nightchaser เขาใช้เวลาส่วนใหญ่ใน Starfall และรู้จักพื้นที่ดี\n\nบอกเขาว่าเจ้าเป็นศิษย์ของข้า..." } } },
        completion = { "48:309681994:1180061011 N 1:46:46", "ศิษย์ของ Daryn Lightwind หรือ? ยินดีที่ได้รู้จัก {name}" },
    },
    [7028] = { -- Twisted Evils
        title = { "13:576393876:1239988897", "ความชั่วร้ายอันบิดเบี้ยว" },
        objective = { "61:1270483822:341592307", "เก็บ Theradric Crystal Carving 15 ชิ้นให้ Willow ที่ Desolace", variants = { { "61:2117284730:1332693175", "เก็บ Theradric Crystal Carving 25 ชิ้นให้ Willow ที่ Desolace" } } },
        description = { "163:708628429:2095875557 C 338:1116394403:1082103049", "ถ้ำผลึก Terramok อยู่ทางตะวันตก ลึกเข้าไปใน Maraudon... เป็นสถานที่เก่าแก่ที่มีประวัติศาสตร์มากมาย และข้าก็อยากได้มันมาบางส่วน {class} วัตถุของเหล่าเทพโบราณซ่อนอยู่หลังประตูมหึมา\n\nหากกล้าฝ่าความชั่วร้ายบิดเบี้ยวใน Maraudon ข้าเชื่อว่าจะทำให้คุ้มเวลาเจ้าได้ เก็บ Theradric Crystal Carving ที่พบแล้วนำกลับมาให้ข้า\n\nเมื่อได้ชิ้นแกะสลัก ข้าก็จะ... ศึกษามันได้ พลังเหล่านี้พักสงบมานานเกินไปแล้ว..." },
        progress = { "41:292666409:1243031018", "อย่าถามอะไร!\n\nเจ้ารู้คำขอของข้าแล้ว" },
        completion = { "129:507118820:360854423", "ฮ่าฮ่าฮ่า! รู้อยู่แล้วว่าเจ้าจะกลับมา\n\n<Willow พึมพำ>\n\n...หลอกง่ายเหลือเกิน\n\n...ยอมทำทุกอย่างถ้าราคาถูกใจ หึหึหึ..." },
        required = { [17684] = { "25:1891773615:734269308", "ผลึกแกะสลัก Theradric" } },
        steps = { { "25:1891773615:734269308", "ผลึกแกะสลัก Theradric" } },
    },
    [7029] = { -- Vyletongue Corruption
        title = { "21:1262336171:1508996940", "ความเสื่อมทรามของ Vyletongue" },
        objective = { "270:499482142:349897885", "เติม Coated Cerulean Vial ที่สระผลึกสีส้มใน Maraudon\n\nใช้ Filled Cerulean Vial กับ Vylestem Vine เพื่อบังคับให้ Noxxious Scion ที่แปดเปื้อนออกมา\n\nรักษาพืช 8 ต้นโดยสังหาร Noxxious Scion เหล่านี้ แล้วกลับไปหา Vark Battlescar ที่ Shadowprey Village" },
        description = { "133:1690006603:1784480014 N 362:1199197502:913744139", "ซาเทอร์ชื่อ Vyletongue ทำให้ถ้ำ Maraudon แปดเปื้อน จนพืชมากมายข้างในหยุดเติบโต\n\nรับขวดนี้ไป {name} เติมน้ำจากสระผลึกสีส้มในถ้ำ สารเคลือบด้านในจะต้านพิษและเปลี่ยนน้ำเป็นยารักษา\n\nหาเถาวัลย์ Vylestem ในถ้ำสีส้ม แล้วใช้ของเหลวบริสุทธิ์กับมัน ความแปดเปื้อนจะถูกชำระจากพืช แต่จำไว้ว่า Vyletongue ยังควบคุมมันอยู่ เขาอาจใช้มันโจมตีเจ้า..." },
        progress = { "88:779749723:1502046013 N 3:3050122:795478", "หากเจ้ารักษาพืชได้ มันจะเริ่มเติบโตอีกครั้ง เราต้องทำเท่าที่ทำได้ {name}..." },
        completion = { "30:327796258:1183328242 N 227:1847716629:29515314", "ขอบใจที่นำกลับมา {name} ของเหลวที่เหลือจะช่วยให้ข้าศึกษาต่อได้\n\nแม้ยังมีงานอีกมาก เจ้าก็ช่วยเยียวยาความเสื่อมทรามบางส่วนที่ Vyletongue แพร่ใน Maraudon แล้ว โปรดรับนี่พร้อมคำขอบคุณของข้า" },
        required = { [17696] = { "20:1194294734:334584475", "ขวดสีฟ้าที่เติมแล้ว" } },
        steps = { { "21:1109045467:763159608", "รักษาเถาวัลย์ Vylestem" }, { "20:1194294734:334584475", "ขวดสีฟ้าที่เติมแล้ว" } },
    },
    [7041] = { -- Vyletongue Corruption
        title = { "21:1262336171:1508996940", "ความเสื่อมทรามของ Vyletongue" },
        objective = { "259:1013980099:1916782338", "เติม Coated Cerulean Vial ที่สระผลึกสีส้มใน Maraudon\n\nใช้ Filled Cerulean Vial กับ Vylestem Vine เพื่อบังคับให้ Noxxious Scion ที่แปดเปื้อนออกมา\n\nรักษาพืช 8 ต้นโดยสังหาร Noxxious Scion เหล่านี้ แล้วกลับไปหา Talendria ที่ Nijel's Point" },
        description = { "133:1690006603:1784480014 N 364:86863151:2113728796", "ซาเทอร์ชื่อ Vyletongue ทำให้ถ้ำ Maraudon แปดเปื้อน จนพืชมากมายข้างในหยุดเติบโต\n\nรับขวดนี้ไป {name} เติมน้ำจากสระสีส้มที่แปดเปื้อนในถ้ำ สารเคลือบด้านในจะต้านพิษและเปลี่ยนน้ำเป็นยารักษา\n\nหาเถาวัลย์ Vylestem ในถ้ำสีส้ม แล้วใช้ของเหลวบริสุทธิ์กับมัน ความแปดเปื้อนจะถูกชำระจากพืช แต่จำไว้ว่า Vyletongue ยังควบคุมมันอยู่ เขาอาจใช้มันโจมตีเจ้า..." },
        progress = { "88:779749723:1502046013 N 3:3050122:795478", "หากเจ้ารักษาพืชได้ มันจะเริ่มเติบโตอีกครั้ง เราต้องทำเท่าที่ทำได้ {name}..." },
        completion = { "30:327796258:1183328242 N 227:1847716629:29515314", "ขอบใจที่นำกลับมา {name} ของเหลวที่เหลือจะช่วยให้ข้าศึกษาต่อได้\n\nแม้ยังมีงานอีกมาก เจ้าก็ช่วยเยียวยาความเสื่อมทรามบางส่วนที่ Vyletongue แพร่ใน Maraudon แล้ว โปรดรับนี่พร้อมคำขอบคุณของข้า" },
        required = { [17696] = { "20:1194294734:334584475", "ขวดสีฟ้าที่เติมแล้ว" } },
        steps = { { "21:1109045467:763159608", "รักษาเถาวัลย์ Vylestem" }, { "20:1194294734:334584475", "ขวดสีฟ้าที่เติมแล้ว" } },
    },
    [7044] = { -- Legends of Maraudon
        title = { "19:645639244:114371289", "ตำนานแห่ง Maraudon" },
        objective = { "129:484125287:1935973860", "นำชิ้นส่วนทั้งสองของ Scepter of Celebras กลับมา ได้แก่ Celebrian Rod และ Celebrian Diamond\n\nหาทางพูดคุยกับ Celebras" },
        description = { "485:893286502:825750433", "ซาเทอร์มืดชื่อ Lord Vyletongue แพร่ความชั่วร้ายทั่วถ้ำคดเคี้ยวนี้ วางพิษจิตใจทุกชีวิตข้างใน เขายังอยู่เลยผลึกสีม่วงไป\n\nVyletongue ยังสร้างตัวแทนความเสื่อมทรามที่มีชีวิตชื่อ Noxxion อยู่เลยผลึกสีส้ม ทั้งสองขโมยชิ้นส่วนคทาของพี่น้องข้าไป Celebras พี่น้องข้า... หลงเดินอยู่ข้างใน ถูกคำสาปแห่งความเสื่อมทรามครอบงำ\n\nเจ้าต้องช่วยเขา! หาชิ้นส่วนแล้วหาทางพูดคุยกับเขาให้ได้..." },
        progress = { "64:354507561:489208252", "ข้าตื่นจากฝันร้ายที่ดูเหมือนไม่มีวันจบแล้ว..." },
        completion = { "125:1508519739:1343760784", "เมื่อเจ้านำคทาทั้งสองส่วนกลับมา ข้าก็มีหวังว่าสักวัน Maraudon จะพ้นจากความเสื่อมทรามของ Vyle" },
        required = { [17703] = { "17:1641507520:1119148921", "เพชร Celebrian" }, [17702] = { "13:951707000:89710634", "คทา Celebrian" } },
        steps = { { "17:1641507520:1119148921", "เพชร Celebrian" }, { "13:951707000:89710634", "คทา Celebrian" } },
    },
    [7046] = { -- The Scepter of Celebras
        title = { "23:1751194768:2147170772", "คทาแห่ง Celebras" },
        objective = { "114:1448382561:1128963572", "ช่วย Celebras the Redeemed ขณะที่เขาสร้าง Scepter of Celebras\n\nคุยกับเขาเมื่อพิธีเสร็จสิ้น" },
        description = { "492:524404553:1705408547", "คทาเคยเป็นความหวังของข้า พลังของมันทำให้เดินทางผ่านถ้ำเหล่านี้ได้อย่างรวดเร็วและอิสระ ข้าเคยหวังจะช่วยให้วิญญาณของอาข้าพักสงบ... บัดนี้ข้ามอบหน้าที่นั้นต่อให้เจ้า\n\nเพื่อให้ชิ้นส่วนทั้งสองกลับเป็นหนึ่ง ข้าต้องการให้เจ้าช่วยทำพิธี โปรดตามมาและฟังคำสั่ง ขณะข้ารวมพลังเพื่อประสานแกนคทากับเพชร\n\nเราจะร่วมกันสร้าง Scepter of Celebras ขึ้นอีกครั้ง!" },
        progress = { "95:406898462:1250295997", "หากต้องการเริ่มพิธีใหม่ โปรดยกเลิกความพยายามครั้งแรกของเรา แล้วคุยกับข้าอีกครั้ง" },
        completion = { "206:1827500046:1562240452 N 44:396874167:1552397402", "รับนี่ไป และรู้ไว้ว่าพลังที่ได้รับต้องใช้เพื่อความดี เดินทางผ่านถ้ำต่อไป หวังว่าเจ้าจะพบซากของอาข้า อันตรายมากมายรอเจ้าอยู่ {name}\n\nคุยกับข้าอีกหากจำเป็น" },
        objectiveLabels = {
            event = { ["Create the Scepter of Celebras"] = "สร้าง Scepter of Celebras" },
        },
    },
    [7064] = { -- Corruption of Earth and Seed
        title = { "28:968491130:419064903", "ความเสื่อมทรามแห่งดินและเชื้อสาย" },
        objective = { "83:1756252526:940812069", "สังหาร Princess Theradras แล้วกลับไปหา Selendra ใกล้ Shadowprey Village ใน Desolace" },
        description = { "498:1799404851:1803072793", "ลึกใน Maraudon มีสิ่งมีชีวิตชั่วร้ายแห่งความโกลาหล Princess Theradras เป็นพลังธาตุดินที่เกี่ยวข้องกับ Old Gods นานมาแล้ว นางกับ Zaetar บุตรคนแรกของ Cenarius มีความสัมพันธ์กัน ลูกหลานของทั้งสองเป็นที่รู้จักใน Kalimdor ว่าเซนทอร์ เหล่าเซนทอร์ผู้แสนรู้คุณกลับฆ่า Zaetar และครอบครองซากของเขาอยู่ตอนนี้ ภารกิจของข้าคือหาผู้มีพลังพอจะสังหาร Theradras เพื่อให้เรานำซาก Zaetar กลับมาก่อนกลับ Stonetalon" },
        progress = { "451:1400426800:259200646", "ข้าอยากให้เราสู้ศึกนี้เอง แต่ไม่มีทางเลือกแล้ว เราต้องการผู้แข็งแกร่งกว่า และเผ่าพันธุ์แห่ง Azeroth พิสูจน์ชัดว่าร่วมมือกันแล้วเอาชนะสิ่งเช่นนี้ได้ เราจึงมาขอให้เจ้าช่วย\n\nข้าได้แต่หวังว่าจะเพียงพอ\n\nZaetar พี่น้องของ Remulos นำความทุกข์มาสู่โลกมากมาย จนสุดท้ายทำให้ตนต้องตาย ข้าเพียงหวังว่าการขอให้เจ้าช่วยจะไม่ก่อความตายเพิ่ม" },
        completion = { "29:911472460:2040275958 N 321:1346321949:10298311", "ข่าวดีเหลือเกิน {name}! ขอบใจ!\n\nข้าจะคุยกับ Marandis ขอคำแนะนำเรื่องซาก Zaetar แต่อย่างน้อยเจ้าก็ผ่านงานที่ยากที่สุดแล้ว\n\nข้าได้รับอนุญาตว่าหากภารกิจสำเร็จ จะตอบแทนผู้ช่วยเหลือได้ สิ่งของเหล่านี้เป็นของแทนใจจากพวกเรา เจ้าจะเลือกชิ้นหนึ่งก็ได้" },
        objectiveLabels = {
            monster = { ["Princess Theradras slain"] = "ปราบ เจ้าหญิง Theradras" },
        },
    },
    [7065] = { -- Corruption of Earth and Seed
        title = { "28:968491130:419064903", "ความเสื่อมทรามแห่งดินและเชื้อสาย" },
        objective = { "83:1778006864:420570330", "สังหาร Princess Theradras แล้วกลับไปหา Keeper Marandis ที่ Nijel's Point ใน Desolace" },
        description = { "62:1778823292:1589782098 N 443:1712374860:1940375654", "ลึกใน Maraudon มีสิ่งมีชีวิตแห่งความโกลาหลและความชั่วร้าย {name} Princess Theradras เป็นพลังธาตุดินที่เกี่ยวข้องกับ Old Gods บางอย่าง นานมาแล้ว Zaetar บุตรคนแรกของ Cenarius ไปหานาง ลูกหลานจาก... ความสัมพันธ์ของทั้งสองคือสิ่งมีชีวิตที่เรียกว่าเซนทอร์ เหล่าเซนทอร์ผู้แสนรู้คุณกลับฆ่า Zaetar และบัดนี้ Theradras เก็บซากเขาไว้ ภารกิจของข้าคือหาผู้มีพลังพอจะสังหาร Theradras เพื่อให้เรานำซาก Zaetar กลับมาก่อนกลับ Stonetalon" },
        progress = { "432:1299288717:903231208", "ข้าหนักใจที่ต้องรบกวนเผ่าพันธุ์ผู้เป็นมรรตัยด้วยคำวิงวอน แต่เราไม่มีทางเลือก เผ่าพันธุ์แห่ง Azeroth พิสูจน์ชัดว่าร่วมมือกันแล้วเอาชนะสิ่งเช่นนี้ได้ ข้าจึงขอความช่วยเหลือ\n\nข้าได้แต่หวังว่าจะเพียงพอ\n\nZaetar พี่น้องของ Remulos นำความทุกข์มาสู่โลกมากมาย จนสุดท้ายทำให้ตนต้องตาย มีบทเรียนอยู่ในเรื่องนี้สำหรับเราทุกคน หากเราฉลาดพอจะมองเห็น" },
        completion = { "29:911472460:2040275958 N 374:79757546:519579685", "ข่าวดีเหลือเกิน {name}! ขอบใจ!\n\nแม้ข้ากังวลที่เจ้าไม่ได้นำซาก Zaetar กลับมา แต่ข้าเป็นใครเล่าจึงจะตั้งคำถามต่อเจตจำนงของบุตรคนแรกแห่ง Cenarius บางทีตอนนี้จิตใจเซนทอร์อาจอ่อนลงและกระหายเลือดน้อยลง เราทำได้เพียงหวัง\n\nข้าได้รับของเหล่านี้มาเพื่อตอบแทนผู้ช่วยเหลือหากภารกิจสำเร็จ เจ้าจะเลือกชิ้นหนึ่งเป็นสินน้ำใจก็ได้" },
        objectiveLabels = {
            monster = { ["Princess Theradras slain"] = "ปราบ เจ้าหญิง Theradras" },
        },
    },
    [7066] = { -- Seed of Life
        title = { "12:432615606:1410580517", "เมล็ดแห่งชีวิต" },
        objective = { "60:301719022:1205040", "หา Remulos ที่ Moonglade แล้วมอบ Seed of Life ให้เขา" },
        description = { "488:2121914459:1166405477", "เซนทอร์ผู้เกิดมาบิดเบี้ยว... ลูกชายลูกสาวของข้า... ยังต้องการพ่อ\n\nมองรอบตัวสิ ที่นี่เปี่ยมด้วยความหวังและทุกสิ่งที่ Cenarius บิดาข้าสั่งสอน มันงอกงามมาจากข้า! ข้าจึงพรากสิ่งนี้จากลูก ๆ ไม่ได้... แม้พวกเขาจะทำผิดต่อข้าก็ตาม\n\nแต่ข้ามีคำขอหนึ่งเพื่อให้พี่น้องข้าสบายใจ รับนี่ไป... นี่คือเมล็ดแรกที่ร่วงจากชีวิตซึ่งซากข้าหล่อเลี้ยง บอกเขาว่าวิญญาณข้ายังอยู่ที่นี่ และข้ายังคงดำรงอยู่ ข้าแน่ใจว่าเขาจะเข้าใจ" },
        progress = { "41:1389296604:2129736569 N 274:1204435473:1823585446", "เจ้ามีกลิ่นอายความเสื่อมทรามติดตัว {name}... เช่นเดียวกับนักผจญภัยมากมายในวันนี้ แต่บางอย่างในตัวเจ้าต่างออกไป มีเรื่องใดมาพูดกับข้าหรือ? ออร่ารอบตัวเจ้าดูคุ้นเคย แต่ข้านึกไม่ออก\n\nข้าขอร้อง โปรดบอกว่าทำไมจึงมาขอพบข้า" },
        completion = { "304:1712728336:54466592 N 189:765109180:245558376", "ในที่สุดพี่น้องข้าก็พบความสงบแล้วหรือ? ข้าภูมิใจที่มีชีวิตมาถึงวันนี้ ท่ามกลางความหยิ่งทะนงและโทสะ ข้าคิดว่าเขาจากเราไปแล้วจริง ๆ แต่สิ่งนี้... สัญลักษณ์แห่งการเสียสละพิสูจน์ว่าเขาไม่ได้สูญหาย เพียงเกิดใหม่ เขารับที่ทางในธรรมชาติตามหน้าที่ของตน\n\nขอบใจ {name} การนำสิ่งนี้มาให้ข้ารักษาความหวังเล็กน้อยที่เคยคิดว่าสูญไปแล้ว สักวันเมล็ดนี้จะสำคัญต่อผู้คนในดินแดนที่สงครามทำลาย ข้าสัมผัสได้" },
        required = { [17760] = { "12:432615606:1410580517", "เมล็ดพันธุ์แห่งชีวิต" } },
        steps = { { "12:432615606:1410580517", "เมล็ดพันธุ์แห่งชีวิต" } },
    },
    [7067] = { -- The Pariah's Instructions
        title = { "25:1651972342:1086870435", "คำชี้แนะของผู้ถูกขับไล่" },
        objective = { "142:1488877033:1929748659", "อ่าน Pariah's Instructions จากนั้นหา Amulet of Union จาก Maraudon แล้วนำกลับไปให้ Centaur Pariah ทางใต้ของ Desolace" },
        description = { "463:1132533168:1469098839", "แม้ถูกเนรเทศในฐานะคนนอกรีต ความเชื่อของข้าก็ยังเป็นจริง สิ่งนั้นเพียงอย่างเดียวผลักดันข้าไปต่อ แต่เพื่อให้ชะตาสำเร็จ ข้าต้องการความช่วยเหลือจากคนนอก... ผู้ที่ไม่ใช่เซนทอร์เผ่าใด\n\nงานนี้ต้องมีคนเข้าโถงศักดิ์สิทธิ์ของ Maraudon สุสานที่พวกข้าปกป้องและยอมให้เฉพาะผู้ศรัทธาแรงกล้าที่สุดเข้า\n\nหากตกลงช่วย เพียงพยักหน้า ข้าจะให้แผ่นหนังพร้อมคำชี้แนะ อ่านแล้วไตร่ตรองคำข้า" },
        progress = { "21:555587403:1267437605 N 94:807918294:1300039451", "ตัดสินใจอย่างไร {name}? จะช่วยข้าไหม? จะเหยียบแดนศักดิ์สิทธิ์เพื่อช่วยข้าหลอมรวมเซนทอร์ให้เป็นเผ่าใหญ่หนึ่งเดียวหรือไม่!?" },
        completion = { "12:1878497415:924553300 R 176:852757106:69104266", "ใช่แล้ว {race}! นี่เอง! ทีนี้ข้าก็เริ่มภารกิจยิ่งใหญ่ในการรวมเผ่าได้ ขอบใจ\n\nโปรดรับนี่ตอบแทนความพยายาม หวังว่าคราวหน้าที่พบกัน สถานการณ์ของเราจะต่างไปมาก" },
        required = { [17758] = { "15:1715688484:1794551839", "เครื่องรางแห่งการผนึกเข้าด้วยกัน" } },
        steps = { { "15:1715688484:1794551839", "เครื่องรางแห่งการผนึกเข้าด้วยกัน" } },
    },
    [7068] = { -- Shadowshard Fragments
        title = { "21:825286690:1129918376", "ชิ้นส่วนผลึก Shadowshard" },
        objective = { "89:403617368:864945223", "เก็บ Shadowshard Fragment 10 ชิ้นจาก Maraudon แล้วนำกลับไปให้ Uthel'nay ที่ Orgrimmar" },
        description = { "427:875298379:1355881414", "ในแดนศักดิ์สิทธิ์ของเซนทอร์... Maraudon นั่น มีเวทมนตร์ทรงพลังอยู่ พวกเซนทอร์ Desolace ปกป้องมันด้วยชีวิต แต่หยุดเราเอาของที่ต้องการไม่ได้หรอก\n\nเจ้าไป Maraudon หาสิ่งมีชีวิตหินที่ทำจาก Shadowshard นำผลึกม่วงมาให้ แล้ว Uthel'nay จะทำอะไรตอบแทนเวลาเจ้า\n\nที่นั่นอันตราย อาจพาเพื่อนไปด้วยนะ" },
        progress = { "138:417647673:1512489155", "พบผลึกหรือยัง? พิธีทรงพลัง คาถาแข็งแกร่ง... Shadowshard อาจมีประโยชน์มากกับเวทอาร์เคนสารพัดแบบ" },
        completion = { "122:1955423838:1576037411", "อา เหมาะกับเวทข้าพอดี รับเครื่องรางชิ้นหนึ่งไปแล้วเดินทางต่อเถอะ... ข้ามีเรื่องต้องศึกษาอีกมาก" },
        required = { [17756] = { "20:1331810064:1762676844", "เศษผลึก Shadowshard" } },
        steps = { { "20:1331810064:1762676844", "เศษผลึก Shadowshard" } },
    },
    [7070] = { -- Shadowshard Fragments
        title = { "21:825286690:1129918376", "ชิ้นส่วนผลึก Shadowshard" },
        objective = { "129:1401402131:1447208257", "เก็บ Shadowshard Fragment 10 ชิ้นจาก Maraudon แล้วนำกลับไปให้ Archmage Tervosh ที่ Theramore บนชายฝั่ง Dustwallow Marsh" },
        description = { "441:1324511856:233882471", "ไม่นานมานี้ข้าเริ่มทดสอบผลึกชนิดต่าง ๆ กับคุณสมบัติอาร์เคน Lady Proudmoore อนุญาตให้ข้าขอให้นักเดินทางที่ไป Desolace ตามหาสถานที่ชื่อ Maraudon ในวิหารที่พังทลายนั้นมีสิ่งมีชีวิตธาตุขนาดใหญ่ประกอบจากหินสีม่วงที่ข้าตั้งชื่อว่า Shadowshard\n\nหากเจ้าไปทางนั้นแล้วพบผลึก ข้าจะขอบใจมาก หากต้องการ ข้าอาจทำเครื่องรางจากมันให้เจ้าได้ด้วย" },
        progress = { "122:621957878:1267452103", "ได้เดินทางไปหรือยัง? ข้ารู้ว่าคงอันตรายไม่น้อย แต่หากสำเร็จก็คุ้มค่าอย่างยิ่ง" },
        completion = { "19:554587191:437047549 N 199:1643493995:1671215691", "สมบูรณ์แบบ {name} ความจริงมีนักผจญภัยอื่นกลับมาจากที่นั่นด้วย ข้าจึงนำของที่พวกเขาให้มาทำสิ่งเหล่านี้... โปรดเลือกชิ้นหนึ่งตอบแทนความเหนื่อยยาก และขอบใจอีกครั้งสำหรับตัวอย่างให้ศึกษาต่อ" },
        required = { [17756] = { "20:1331810064:1762676844", "เศษผลึก Shadowshard" } },
        steps = { { "20:1331810064:1762676844", "เศษผลึก Shadowshard" } },
    },
    [8733] = { -- Eranikus, Tyrant of the Dream
        title = { "29:1624316746:985937625", "Eranikus ทรราชแห่งความฝัน" },
        objective = { "106:1266413801:1439789801", "เดินทางสู่ Teldrassil แล้วหาตัวแทนของ Malfurion ที่อยู่แถวด้านนอกกำแพง Darnassus" },
        description = { "493:2133445762:231083077", "นี่คือเส้นทางแห่งการไถ่บาป วีรชน หากข้าถูกสังหารวันนี้ ข้าก็จะตายเพื่ออุดมการณ์ที่ถูกต้องและชอบธรรม เจ้าต้องนำเศษคทาสีเขียวกลับมา ต้องชำระมลทินที่ Old Gods ทำไว้กับ Eranikus\n\nไป Darnassus ด้านนอกกำแพงเมืองเจ้าจะพบตัวแทนคนหนึ่งของข้า เขาจะเริ่มแผนของเราและแจ้ง Tyrande โดยไม่ให้ Staghelm รู้ตัว\n\n<Malfurion ถอนใจ>\n\nการตกต่ำจากคุณความดีที่ค่อย ๆ ก่อตัวมานับพันปี..." },
        completion = { "117:1109986116:579495406", "วิสป์เงียบงัน มีเพียงเสียงครางฮัมเบา ๆ น่าแปลกที่มันสื่อสารกับเจ้าได้ผ่านความคิด" },
    },
    [8970] = { -- I See Alcaz Island In Your Future...
        title = { "36:435791081:750417990", "ข้าเห็นเกาะ Alcaz ในอนาคตเจ้า..." },
        objective = { "95:1153863105:152984753", "รวบรวม Bloodkelp 20 ชิ้นจากนากา Strashaz แล้วกลับไปหา Bodley ภายใน Blackrock Mountain" },
        description = { "17:2133024668:1515061248 C 353:1236590675:871423614 N 130:1412530511:1702027793", "อย่างที่บอก {class} ตอนยังมีชีวิตข้าเคยลองเป็นนักพยากรณ์ แต่กำไรไม่มากอย่างที่คิด เพราะอันตรายและวัตถุดิบหายากราคาแพง อย่างไรก็ดี ข้ารู้มากพอจะชี้ตำแหน่งเครื่องรางชิ้นสุดท้ายพร้อมวิญญาณอดีตสหายผู้ถือมัน\n\nตรงนี้เองที่ต้องพึ่งเจ้า {name} ไป Alcaz Island นอกชายฝั่ง Dustwallow Marsh แล้วเก็บ Bloodkelp จากนากา Strashaz ที่อยู่บนนั้น" },
        progress = { "11:1942898507:435475204 N 211:371255352:337335247", "Bloodkelp {name} ข้าต้องใช้กองใหญ่เพื่อขับพลังคาถาพยากรณ์ เจ้าคงต้องพาเพื่อนไป Alcaz Island อย่างน้อยสักสองคนเพื่อช่วยเก็บ... พวก Strashaz ร้ายกาจนัก!" },
        completion = { "14:1076374178:1095834509 N 245:1802312037:1935495439", "พูดตรง ๆ {name} ข้าแปลกใจที่เจ้ากลับมาอย่างปลอดภัย แต่คิดอีกที ตอนนี้ Alcaz Island ก็คงเป็นเรื่องเล็กที่สุดที่เจ้าต้องกังวล\n\nเอาล่ะ ขอเวลาสักครู่... การพยากรณ์ไม่ใช่ดีดนิ้วแล้วจะได้คำตอบแม่นยำทันที" },
        required = { [22094] = { "9:1566692038:397211614", "สาหร่ายโลหิต" } },
        objectiveLabels = {
            item = { ["Bloodkelp"] = "สาหร่ายโลหิต" },
        },
    },
    [96800] = { -- Past Due
        title = { "8:727162285:1487571533", "เกินกำหนดคืน" },
        objective = { "79:1689775580:592478469", "นำหนังสือ The Lost Magic of the Runemasters กลับมาจาก Scarlet Monastery" },
        description = { "11:832768296:1518065480 C 476:517190137:1729897284", "เจ้าน่ะ {class} ข้ามีเรื่องอยากให้ช่วย\n\nข้ากำลังเขียนวิทยานิพนธ์เรื่องจ้าวอักขระโบราณชาว Wildhammer แห่ง Grim Batol และต้องใช้ตำราเล่มหนึ่งเพื่อให้งานวิจัยสมบูรณ์ ตามบัญชีของเรา จอมเวทชื่อ Doan ยืมหนังสือจากห้องสมุด Dalaran เก่าไปก่อนสงครามครั้งที่สาม แล้วไม่เคยคืนเลย!\n\nตอนนี้ Arcanist Doan กบดานใน Scarlet Monastery ที่ Tirisfal Glades นำหนังสือกลับมาให้ข้า แล้วจะได้รางวัลอย่างงาม" },
        completion = { "406:690262354:713456044", "โอ้ เจ้าต้องฆ่า Doan ถึงจะได้หนังสือคืนหรือ แย่แล้ว...\n\n...เอาเถอะ เรื่องจบด้วยดีก็ดีแล้ว! ขอบใจที่เอาหนังสือกลับมาคืนที่และช่วยให้ข้าทำวิทยานิพนธ์เสร็จ ข้ามั่นใจว่าเราฟื้นศาสตร์เวทรูนที่คนแคระเคยสูญเสียไปได้ และข้าจะพิสูจน์ให้เห็น!\n\nถ้าข้าเข้าไปใน Grim Batol แล้วตรวจดูรูนโบราณที่สลักไว้ด้วยตาตัวเองได้ก็คงดี...\n\nบางทีสักวันหนึ่ง" },
        progress = { "44:1763254360:494701799", "บางทีข้าก็รู้สึกว่าวิทยานิพนธ์เล่มนี้ต้องคำสาป" },
        required = { [273169] = { "33:456270155:1840264927", "เวทมนตร์ที่สาบสูญของปรมาจารย์รูน" } },
        steps = { { "33:456270155:1840264927", "เวทมนตร์ที่สาบสูญของปรมาจารย์รูน" } },
    },
    [97979] = { -- The Goddess Provides
        title = { "20:1183703745:1055339822", "พรที่เทพีประทาน" },
        objective = { "34:184876619:2093234351", "ใช้ Elune's Light และ Shadowmeld" },
        description = { "499:96618939:2115145340", "เจ้าเกิดเป็นคัลโดไร บุตรแห่งดวงดาว และสืบทอดสิทธิ์โดยกำเนิดที่ไม่เหมือนผู้ใดในโลก พระกรุณาแห่ง Elune อาจส่องเสริมพลังให้เราโจมตีได้แม่นยำ หรือช่วยซ่อนเรา เช่นจันทร์ที่บดบังดวงอาทิตย์\n\nการเฝ้าระวังอันยาวนานหลังปกป้อง Mount Hyjal จบลงแล้ว เราได้เข้าร่วม Alliance กับชนเผ่าอื่น ซึ่งเจ้าจะได้พบเมื่อถึงเวลา แต่ตอนนี้เจ้ายังอยู่ในอ้อมกิ่งก้านแห่ง Teldrassil\n\nแสดงของขวัญจากมารดาจันทรา แล้วรับพรของนางเถิด", variants = { { "488:2073463858:1431341000", "เจ้าเกิดเป็นคัลโดไร บุตรแห่งดวงดาว และจะเป็นนักบวชหญิงผู้ยิ่งใหญ่ของเทพี Elune พระกรุณาของนางอาจส่องเสริมพลังให้เราโจมตีได้แม่นยำ หรือช่วยซ่อนเรา เช่นจันทร์ที่บดบังดวงอาทิตย์\n\nการเฝ้าระวังอันยาวนานหลังปกป้อง Mount Hyjal จบลงแล้ว เราได้เข้าร่วม Alliance กับชนเผ่าอื่น ซึ่งเจ้าจะได้พบเมื่อถึงเวลา แต่ตอนนี้เจ้ายังอยู่ในอ้อมกิ่งก้านแห่ง Teldrassil\n\nแสดงของขวัญจากมารดาจันทรา แล้วรับพรของนางเถิด" } } },
        completion = { "85:703094361:1094678509", "เจ้าเห็นแล้วว่าเทพีของเราประทานสิ่งใด จงใช้ให้ดี แล้วนางจะไม่ทอดทิ้งเจ้า" },
        progress = { "62:1233946636:1099379900", "มีความสุขไม่กี่อย่างที่เทียบได้กับการอาบแสงของพระแม่จันทรา" },
        steps = { { "18:858474575:1223628341", "ร่าย Elune's Light" }, { "15:1569630988:1406082846", "ใช้ Shadowmeld" } },
    },
    [1152] = { -- Test of Lore
        title = { "12:1934682095:1969211033", "บททดสอบความรู้" },
        objective = { "81:2038425764:1063008008", "หา Braug Dimspirit ใกล้ทางเข้า Talondeep Path ใน Stonetalon Mountains" },
        description = { "316:1041141165:1711683935 N 134:1792005741:1700623156 N 47:367515000:99642190", "เวลาที่อยู่กับข้าใกล้จบแล้ว แม้ข้ารอบรู้ แต่บททดสอบความรู้ไม่ใช่หน้าที่ข้า มีบทเรียนและสถานที่ของผู้อื่นที่เจ้าต้องไป\n\nหากพร้อม จงหา Braug Dimspirit ชามานผู้เปี่ยมปัญญา เขาจะทดสอบเจ้าต่อ จงฟังคำของเขา {name}\n\nเมื่อพร้อม หาอุโมงค์เชื่อม Stonetalon Mountains กับ Ashenvale Braug อยู่ใกล้ที่นั่น และระวังด้วย {name} ไนต์เอลฟ์อาจอยากขัดขวางบททดสอบ" },
        completion = { "453:304764881:1786409931", "วันคืนทั่วโลกหนาวเย็นขึ้น เมื่อก็อบลินย่ำยีผืนดิน และไนต์เอลฟ์กล่าวโทษเผ่าที่อ่อนวัยกว่า Forsaken กับออร์คไม่ได้เป็นผู้ผิดเพียงพวกเดียวต่อความทุกข์ทั่ว Kalimdor และ Lordaeron เผ่าทรงปัญญามากมายมีส่วนสร้างความเจ็บปวดให้โลก Dorn รู้ และส่งเจ้ามาเพราะเจ้าแสดงคุณสมบัติที่จะเข้าใจเรื่องนี้เช่นกัน\n\nตอนนี้เจ้ายืนอยู่ต่อหน้า Braug" },
    },
    [1154] = { -- Test of Lore
        title = { "12:1934682095:1969211033", "บททดสอบความรู้" },
        objective = { "124:898679589:39801833", "หา Legacy of the Aspects แล้วนำกลับไปให้ Braug Dimspirit ใกล้ทางเข้า Talondeep Path ใน Stonetalon Mountains" },
        description = { "480:1760228895:533218333", "เจ้าผ่านบททดสอบ Dorn และหวังผ่านด่านถัดไป ดีมาก แต่ที่ผ่านมายังเป็นเรื่องเด็ก ๆ ทดสอบร่างกายง่าย ทดสอบจิตใจต่างกันสิ้นเชิง\n\nอธิบายง่าย ๆ คือหาหนังสือที่ข้าบอก อ่านให้เข้าใจ แล้วตอบคำถามเกี่ยวกับเนื้อหา\n\nหนังสืออะไรน่ะหรือ? Legacy of the Aspects อยู่ส่วนล่างสุดของ Dor'danil ทางใต้ของ Ashenvale มีดรูอิดผู้ตายและผู้สังหารพวกเขาเฝ้าไว้" },
        progress = { "115:1017494520:2103261430", "นำหนังสือมาเมื่ออ่านศึกษาแล้ว ข้าจะไม่ถามจนกว่าเจ้ามอบหนังสือให้" },
        completion = { "208:240444178:274441080", "นี่คือหนังสือที่ข้าบอก เช่นนั้นก็หวังว่าเจ้าจะตอบถูก... เว้นแต่ลืมอ่านเนื้อหา\n\nเมื่อพร้อม คุยกับข้าอีกครั้ง แล้วข้าจะถาม" },
        required = { [5860] = { "21:447731924:1151224453", "มรดกแห่งเหล่ามังกรผู้พิทักษ์" } },
        steps = { { "21:447731924:1151224453", "มรดกแห่งเหล่ามังกรผู้พิทักษ์" } },
    },
    [1159] = { -- Test of Lore
        title = { "12:1934682095:1969211033", "บททดสอบความรู้" },
        objective = { "36:1915705748:1627982865", "หา Parqual Fintallas ใน Undercity" },
        description = { "11:534428891:784080240 N 481:365032070:72647631", "ทำได้ดี {name} เจ้าผ่านส่วนแรกของบททดสอบความรู้ แต่ยังมีอีกคำถาม ซึ่งไม่ใช่หน้าที่ข้าถาม\n\nหา Parqual Fintallas ใน Lordaeron City ก่อนโรคระบาดครอบงำ เขาเคยเป็นนักประวัติศาสตร์ผู้ยิ่งใหญ่ของมนุษย์ ตอนนี้ยังแสวงหาปัญญาต่อ แต่ในลักษณะต่างออกไป\n\nเขาจะขอให้เจ้าทำบางอย่างก่อนถาม แต่เจ้าทำได้ดีมากมาถึงตรงนี้ ข้ามั่นใจว่าจะผ่านอุปสรรคของเขาได้" },
        completion = { "295:2129498765:210893436 C 1:46:46", "Braug ส่งเจ้ามา? เป็นไปไม่ได้\n\n<Parqual มองเจ้าตั้งแต่หัวจรดเท้า>\n\nฝ่า Dor'Danil กระโดดด้วยศรัทธา ต่อสู้และโค่นธาตุทรงพลัง? ชิ! คงเป็นของปลอม นักผจญภัยที่แอบฟังคนคุยในโรงเหล้า แล้วคิดว่าตนมีดีพอผ่านบททดสอบข้า เอาสิ... {class}" },
    },
    [3374] = { -- The Essence of Eranikus
        title = { "23:1559561630:1184439515", "แก่นพลังของ Eranikus" },
        objective = { "195:1566944154:1993712224", "นำ Oathstone of Ysera's Dragonflight และ Chained Essence of Eranikus ไปให้ Itharius ที่ Swamp of Sorrows ที่นั่นเจ้าจะเลือกว่าจะช่วย Ysera's Dragonflight หรือไม่" },
        description = { "424:1768047728:782866430 N 67:2100424980:1964794352", "เจ้าใช้ Oathstone แล้ว Itharius พูดตรงสู่ใจผ่านศิลา\n\n“รับหน้าที่ในศิลานี้ คือยอมช่วยจุดหมายข้าและฝูงมังกร Ysera เพื่อไถ่กู้วิญญาณ Eranikus ที่เสื่อมทราม การสละแรก ในอีกหลายอย่างที่เราคงต้องทำ คือมอบอัญมณีที่ล่ามส่วนจิตมีเจตจำนงเสรีที่เหลือของเขาให้ข้า”\n\n“ทำเช่นนี้ {name} เราจะร่วมไถ่กู้วิญญาณที่คู่ควร”" },
        progress = { "12:958868672:1404524288 N 103:773714873:1514967766", "ถึงทางแยกอีกแล้ว {name} เวลาเลือกอีกครั้ง เจ้าจะเลือกสิ่งใด ผู้ไม่เป็นอมตะ?" },
        completion = { "201:1860860274:1086302285", "เจ้าเลือกแล้ว จึงเริ่มต้น ถึงวันนี้ข้าถือว่าเลือกถูก การกระทำต่อจากนี้จะบอกว่าจะยังเป็นเช่นนั้นไหม" },
        required = { [10455] = { "27:55643330:1529172789", "แก่นพลังของ Eranikus ที่ถูกพันธนาการ" } },
        objectiveLabels = {
            item = { ["Chained Essence of Eranikus"] = "แก่นพลังของ Eranikus ที่ถูกพันธนาการ" },
        },
    },
    [3787] = { -- Jonespyre's Request
        title = { "19:1422667886:237074412", "คำขอของ Jonespyre" },
        objective = { "55:2083273900:48785798", "คุยกับ Quintis Jonespyre ที่ Feathermoon Stronghold" },
        description = { "470:229046137:2038469381", "ขอโทษนะสหาย...\n\nเพื่อนร่วมงานของข้าอยากคุยเรื่องงานวิจัยที่เจ้าทำร่วมกับ Cenarion Circle เขาเป็นดรูอิดชื่อ Quintis Jonespyre อยู่ที่ Feathermoon Stronghold ใน Feralas เขาอยากหารือเรื่อง morrowgrain... และอยากให้เจ้าเก็บการพูดคุยของเราอย่าให้ถึงหูอัครดรูอิด\n\nถ้าสนใจก็ไปคุยกับเขา แล้วทุกอย่างคงกระจ่าง" },
        completion = { "486:930292661:867955524", "ขอบใจที่มา นักเดินทางผู้เหนื่อยล้า! ขอแนะนำตัว ข้าคือ Quintis Jonespyre ดรูอิดและผู้รับใช้อันถ่อมตนของ Malfurion กับ Cenarion Circle ข้ากับเพื่อนร่วมงาน ได้แก่ General Shandris Feathermoon และ Protectorate ซึ่งเจ้าอาจเคยได้ยินชื่อ อยากคุยเรื่องงานที่เจ้าทำให้ Fandral Staghelm ใน Darnassus\n\nก่อนคุยต่อ ข้าขอให้เรื่องนี้อยู่ระหว่างเราเท่านั้น หากเจ้าไม่ขัดข้อง เราก็เริ่มได้" },
    },
    [6627] = { -- Test of Lore
        title = { "12:1934682095:1969211033", "บททดสอบความรู้" },
        objective = { "134:228720626:1125001459", "ตอบคำถาม Braug Dimspirit ให้ถูก แล้วคุยกับเขาอีกครั้ง เขาจะอยู่ใน Stonetalon Mountains เมื่อเจ้าพร้อม" },
        description = { "105:871645140:49005665 C 71:2000963081:1032952605", "นำหนังสือมาแล้ว ถึงเวลาตอบคำถาม พร้อมหรือยัง?\n\nเวลาไม่ใช่ปัญหา {class} อย่ากดดัน จะใช้เวลาตอบนานเพียงใดก็ได้" },
        progress = { "27:1726297980:70339357 C 130:1103754880:2010539392", "ชีวิตเต็มไปด้วยคำถาม {class} เจ้าไม่มีวันตอบหมด แต่ด้วยเวลาและการศึกษา บางทีจะรู้มากขึ้นสักนิด" },
        completion = { "11:534428891:784080240 C 89:2023895145:2018187081", "ทำได้ดี {class} เจ้าอ่านสิ่งที่ข้าขอ และผ่านบททดสอบอีกขั้นแล้ว" },
        objectiveLabels = {
            event = { ["Answer Braug Dimspirit's question correctly"] = "ตอบคำถามของ Braug Dimspirit ให้ถูกต้อง" },
        },
    },
    [6628] = { -- Test of Lore
        title = { "12:1934682095:1969211033", "บททดสอบความรู้" },
        objective = { "129:782883295:253119578", "ตอบคำถาม Parqual Fintallas ให้ถูก แล้วคุยกับเขาอีกครั้ง เขาจะอยู่ใน Undercity จนกว่าเจ้าพร้อม" },
        description = { "218:117068111:970544197 N 41:1002205304:98943007", "ถึงเวลาอีกครั้ง ในฐานะผู้ศึกษาความรู้ เจ้าแสดงความมุ่งมั่นด้วยการรับงานข้า\n\nตอนนี้ข้าจะถาม หากพร้อม คุยอีกครั้ง ใช้เวลาเท่าที่ต้องการ {name} ไม่จำเป็นต้องรีบตอบ" },
        progress = { "213:1375391769:796447366 R 10:491007437:253413171", "มีกฎเดียวที่ต้องรู้หากอยากอยู่รอดในโลก ยิ่งรู้มาก ยิ่งมองเห็นมาก\n\nหากศึกษาและสังเกต เจ้าจะเริ่มเห็นสิ่งที่{race}คนอื่นไม่เห็น" },
        completion = { "11:534428891:784080240 N 92:280977403:1850779096", "ทำได้ดี {name} ข้าเคยสงสัยว่าอ่านสิ่งที่ขอให้ไปเอาหรือไม่ แต่เจ้าตอบถูกแล้ว" },
        objectiveLabels = {
            event = { ["Answer Parqual Fintallas' question correctly"] = "ตอบคำถามของ Parqual Fintallas ให้ถูกต้อง" },
        },
    },
    [17] = { -- Uldaman Reagent Run
        title = { "19:489206682:2133046280", "เก็บวัตถุดิบจาก Uldaman" },
        objective = { "60:1928883617:49609980", "นำ Magenta Fungus Cap 12 ชิ้นไปให้ Ghak Healtouch ที่ Thelsamar" },
        description = { "490:415026418:2107494929", "ข้าได้ยินเรื่องพืชที่เพิ่งค้นพบชื่อ Magenta Fungus Cap มันขึ้นเป็นกลุ่มลึกในแหล่งขุดค้น Uldaman อาจมีที่อื่นด้วย แต่ตอนนี้ข้ารู้แค่ที่นั่น ข้าอยากศึกษาประโยชน์ในการเล่นแร่แปรธาตุ จึงต้องพึ่งเจ้า\n\nหากลุ่มเห็ดสีม่วงแดงแล้วนำดอกมาสิบสองดอก ระวังด้วย หากกระทบกระเทือนมันอาจพ่นสปอร์พิษ\n\nทำให้ข้า แล้วข้าจะปรุงยาอายุวัฒนะฟื้นกำลังอันเลื่องชื่อให้ชุดหนึ่ง!", variants = { { "487:492761830:1154831270", "ข้าได้ยินเรื่องพืชที่เพิ่งค้นพบชื่อ Magenta Fungus Cap มันขึ้นเป็นกลุ่มลึกในแหล่งขุดค้น Uldaman อาจมีที่อื่นด้วย แต่ตอนนี้ข้ารู้แค่ที่นั่น ข้าอยากศึกษาประโยชน์ในการเล่นแร่แปรธาตุ จึงต้องพึ่งเจ้า\n\nหากลุ่มเห็ดสีม่วงแดงแล้วนำดอกมาสิบสองดอก ระวังด้วย หากกระทบกระเทือนมันอาจพ่นสปอร์พิษ\n\nทำให้ข้า แล้วข้าจะปรุงGreater Mender's Potion สูตรขึ้นชื่อของข้าให้ชุดหนึ่ง!" } } },
        progress = { "93:1102159570:242740663", "ได้ดอกเห็ดสีม่วงแดงที่ข้าต้องใช้ในงานเล่นแร่แปรธาตุหรือยัง? ไม่มีเห็ดก็ไม่มีรางวัล!" },
        completion = { "10:963015740:1087923650 N 335:2117260009:1191129418", "ทำได้ดี {name} เจ้าพิสูจน์คุณค่าของตนอีกครั้งแล้ว! ดอกเห็ดน่าศึกษาจริง ๆ แน่นอนเลย!\n\nตามสัญญา ลองลิ้มยาฟื้นกำลังฤทธิ์แรงจากคลังส่วนตัวข้าสิ...\n\nหากเชี่ยวชาญเล่นแร่แปรธาตุ เราอาจมีธุระอื่นร่วมกันได้อีก ไม่ว่าอย่างไร ขอบใจที่ช่วย!" },
        required = { [8047] = { "18:1620538754:1643817321", "หมวกเห็ดสีม่วงแดง" } },
        steps = { { "18:1620538754:1643817321", "หมวกเห็ดสีม่วงแดง" } },
    },
    [166] = { -- The Defias Brotherhood
        title = { "22:1184404334:2044032401", "ภราดรภาพ Defias" },
        objective = { "60:2067346899:297755926", "สังหาร Edwin VanCleef แล้วนำศีรษะไปให้ Gryan Stoutmantle" },
        description = { "296:1368686321:1142528693", "เหลืองานสุดท้ายให้เจ้าทำ ต้องลอบสังหาร Edwin VanCleef แม้ข้าเสียใจที่ตัดสินให้ผู้ใดต้องตาย แต่เพื่อประโยชน์ของชาว Westfall ต้องให้ VanCleef จบชีวิตเสียที เมื่อทำสำเร็จจงนำศีรษะวายร้ายมาให้ข้า" },
        progress = { "37:1376788301:1684518352", "การตามล่า Edwin VanCleef เป็นอย่างไรบ้าง?" },
        completion = { { "N 291:1680680555:1118299694", "N 291:1071460249:1186070553" }, "{name} ความกล้าหาญของเจ้าน่าชื่นชม People's Militia ขอบใจที่รับใช้ชาว Westfall การตายของ VanCleef คือจุดเริ่มต้นแห่งจุดจบของ Defias Brotherhood หวังว่าอีกไม่นานสันติจะกลับสู่ทุ่งราบงดงามนี้\n\nข้าขอคารวะท่าน!", variants = { { "N 290:1836496496:1795374163", "{name} ความกล้าหาญของเจ้าน่าชื่นชม People's Militia ขอบใจที่รับใช้ชาว Westfall การตายของ VanCleef คือจุดเริ่มต้นแห่งจุดจบของ Defias Brotherhood หวังว่าอีกไม่นานสันติจะกลับสู่ทุ่งราบอันงดงามแห่งนี้\n\nข้าขอคารวะท่าน!" } } },
        required = { [3637] = { "16:1924485180:384704863", "ศีรษะของ VanCleef" } },
        steps = { { "16:1924485180:384704863", "ศีรษะของ VanCleef" } },
    },
    [167] = { -- Oh Brother. . .
        title = { "15:975965675:656262574", "โอ้ พี่น้องข้า...", variants = { { "13:1038336748:326398522", "โอ้ พี่น้องข้า..." } } },
        objective = { "91:879209957:251534796", "นำ Explorers' League Badge ของ Foreman Thistlenettle ไปให้ Wilder Thistlenettle ที่ Stormwind" },
        description = { "470:783159852:2122624290", "เราอยู่ลึกในเหมืองใหญ่แห่ง Westfall ซ่อนใต้ยุ้งฉางใน Moonbrook ไม่รู้เลยว่าเจ้าพวกโจรเหม็น ๆ มาจากไหน แล้วอุโมงค์เหมืองก็ถล่มใส่เรา ข้าหนีออกมาได้ แต่คนอื่น... เอ่อ... ไม่มีข่าวอีกเลย\n\nเจ้าดูอาจมีโชคดีกว่าเมื่อเข้าไป หากช่วยหาพี่น้องข้าก็จะขอบใจมาก เขาพก Explorers' League Badge เสมอ หากหาเขาไม่พบ อย่างน้อยตรานั้นคงทำให้ข้าพอสงบใจได้" },
        progress = { "75:1920495800:1931500779", "พบร่องรอยของพี่น้องข้าหรือไม่? ผ่านมานานเช่นนี้ยังมีหวังไหม?" },
        completion = { "142:520642174:1195350097", "ข้าสงสัยไว้ถูกแล้ว พี่น้องผู้น่าสงสาร... ขอบใจที่ช่วยให้เรื่องนี้มีข้อยุติ แม้ข้อยุติจะเศร้าร้ายก็ตาม" },
        required = { [1875] = { "21:1412183262:379658541", "ตราของ Thistlenettle" } },
        objectiveLabels = {
            item = { ["Thistlenettle's Badge"] = "ตราของ Thistlenettle" },
        },
    },
    [168] = { -- Collecting Memories
        title = { "19:393509454:2035815398", "รวบรวมความทรงจำ" },
        objective = { "84:1291563504:2036220045", "นำ Miners' Union Card 4 ใบกลับไปให้ Wilder Thistlenettle ที่ Stormwind" },
        description = { "377:1621588064:744859778", "เพื่อนข้าหลายคนตายในวันเลวร้ายที่อุโมงค์ถล่ม หากการผจญภัยพาเจ้าไปเหมืองส่วนนั้นใน Moonbrook โปรดมองหาร่องรอยที่ระบุตัวพวกเขาได้ หากพบ Miners' Union Card ของใคร นำมาให้ข้า แล้วข้าจะช่วยให้ครอบครัวพวกเขาได้รู้ข้อยุติของอุบัติเหตุสยดสยองนี้" },
        progress = { "72:362449527:1771932227", "นำ Miners' Union Card ของเพื่อนร่วมงานเก่าข้ากลับมาได้บ้างหรือไม่?" },
        completion = { "32:294302171:1158996985 N 126:1982961421:231012349", "ขอบใจที่รวบรวมมา {name} ความพยายามของเจ้าจะช่วยให้ผู้ตายจากโศกนาฏกรรมนี้พักสงบ ข้าจะจัดการแจ้งครอบครัวให้ทราบ" },
        required = { [1894] = { "18:383200187:397641029", "บัตรสมาชิกสหภาพคนงานเหมือง" } },
        objectiveLabels = {
            item = { ["Miners' Union Card"] = "บัตรสมาชิกสหภาพคนงานเหมือง" },
        },
    },
    [214] = { -- Red Silk Bandanas
        title = { "17:195410939:363831181", "ผ้าโพกหัวไหมแดง" },
        objective = { "83:588612118:2020607201", "Scout Riell ที่หอคอย Sentinel Hill ต้องการ Red Silk Bandana 10 ผืน" },
        description = { "455:119479018:1907433695 N 1:46:46", "ใคร ๆ ก็รู้ว่าผ้าโพกหัวแดงคือสัญลักษณ์แก๊ง Defias แต่เราเพิ่งรู้ว่าวัสดุที่ใช้ทำบ่งบอกยศของสมาชิก\n\nข้าจึงอยากให้เจ้ากำจัดสมาชิก Defias ระดับสูงให้มากที่สุด พวกยศสูงสุดคงอยู่ในที่ซ่อนลับของ VanCleef เมื่อเสร็จให้นำ Red Silk Bandana 10 ผืนเป็นหลักฐานการตาย แล้วข้าจะให้รางวัล โชคดี {name}" },
        progress = { "100:1537309302:1693882713", "ได้ชิงแผ่นดินเราคืนจากแก๊ง Defias หรือยัง? ถ้าใช่ แสดง Red Silk Bandana 10 ผืนเป็นหลักฐาน" },
        completion = { "11:534428891:784080240 N 147:1768235222:1873313586", "ทำได้ดี {name}! ในนาม People's Militia ข้าคารวะความพยายามเจ้า ด้วยความช่วยเหลือจากผู้กล้าเช่นเจ้า เราจะคืนแผ่นดินแก่ประชาชนได้ในไม่ช้า" },
        required = { [915] = { "16:1722089658:199493394", "ผ้าคาดหัวไหมสีแดง" } },
        steps = { { "16:1722089658:199493394", "ผ้าคาดหัวไหมสีแดง" } },
    },
    [377] = { -- Crime and Punishment
        title = { "20:471574881:753571864", "อาชญากรรมและบทลงโทษ" },
        objective = { "82:747360353:782138381", "Councilman Millstipe ที่ Darkshire ต้องการให้เจ้านำมือของ Dextren Ward มาให้" },
        description = { "484:1953103879:1386362651", "แค่ละเลยชาว Duskwood ก็เลวร้ายพอแล้ว แต่ House of Nobles ยังหยามสภา Darkshire ด้วยการขัง Dextren Ward ใน Stormwind แทนการประหารตามคำตัดสินของ Lord Ebonlocke\n\nWard ถูกจับได้ว่าขายศพจากสุสานให้ Morbent Fel อาชญากรรมที่มีโทษถึงตาย แต่ Stormwind กลับอ้างสิทธิ์ว่าเขาเป็นนักโทษของตน\n\nลอบสังหาร Ward ใน Stormwind Stockade นำมือเขามา แล้วข้าจะตอบแทน" },
        progress = { "335:1174168781:1321826522", "ตราบใดที่ผู้ลบหลู่ศพเช่น Dextren Ward ยังได้รับอนุญาตให้มีชีวิต ความยุติธรรมก็ถูกทรยศ กลับมาเมื่อทำตามโทษประหารของ Lord Ebonlocke ต่อเจ้า Ward ผู้แปดเปื้อนแล้ว เราจะให้ครอบครัวผู้ตายได้ข้อยุติที่สมควร และยิ่งกว่านั้นคือส่งสารชัดเจนถึง House of Nobles ใน Stormwind" },
        completion = { "387:1071983890:148984943", "ในที่สุด Dextren Ward ก็ชดใช้ความผิดต่อมนุษยชาติแล้วหรือ? พ้นจากสวะเสียได้ก็ดี ข้าขอฉลองให้เจ้า สหาย! เจ้าไม่เพียงคืนความสงบใจที่ครอบครัวผู้ตายสมควรได้รับ แต่ยังส่งสารสะเทือนใจถึงขุนนางทุจริตใน House of Nobles Stormwind ต้องตอบสนองความต้องการชาว Duskwood ไม่เช่นนั้นเราจะปลดตนจากการกดขี่ของพวกเขา" },
        required = { [3628] = { "20:644195883:507133995", "มือของ Dextren Ward" } },
        objectiveLabels = {
            item = { ["Hand of Dextren Ward"] = "มือของ Dextren Ward" },
        },
    },
    [378] = { -- The Fury Runs Deep
        title = { "18:710470186:378682595", "โทสะที่ฝังลึก" },
        objective = { "69:1958105307:883931692", "Motley Garmason ที่ Dun Modr ต้องการศีรษะ Kam Deepfury" },
        description = { "44:1798411277:1068787636 C 416:23387754:1954696101 N 35:1726197893:1824457437", "เจ้าพิสูจน์ความภักดีต่อ King Magni แล้ว {class} และเกลียดพวกสวะ Dark Iron ไม่แพ้ข้า\n\nมีงานที่ข้าอยากทำเอง แต่เกียรติผูกมัดให้ต้องอยู่กับ Longbraid ส่วน Roggo ได้ข่าวที่ยืนยันว่า Kam Deepfury ร่วมวางแผนโจมตี Thandol Span แผนของ Deepfury ทำให้ Longbraid เสียญาติ\n\nDeepfury ถูกขังด้วยเหตุผลทางการเมืองใน Stormwind Stockade ข้าต้องการให้มันตาย {name} เพื่อ Longbraid! นำศีรษะมันมา!" },
        progress = { "70:1125966867:1327201928 N 265:537543537:1574384114", "ข้าไม่ยอมให้ระบบราชการโง่เง่าของมนุษย์ยุ่งเรื่องคนแคระ {name} พิสูจน์แล้วว่า Kam Deepfury ร่วมวางแผนโจมตี Thandol Span ประชาชนผู้ดีงามของ King Magni ตายเพราะเล่ห์ของมัน มนุษย์อาจพอใจที่ปล่อยมันเน่าใน Stockade แต่ข้านอนไม่สงบจนกว่า Deepfury จะตาย" },
        completion = { "157:117559706:223190875 C 232:1637302124:42782528", "ในที่สุด Kam Deepfury ก็รู้รสการเป็นฝ่ายถูกความตายเล่นงานหรือ? ดี สมน้ำหน้าพวกสวะ Dark Iron ขี้ขลาด เจ้าทำได้ดี {class} ผู้ตายจากการโจมตี Thandol Span เป็นเพียงเหยื่อในโลกที่สงครามและความวุ่นวายฉีกทึ้ง ครอบครัวจะสงบใจเมื่อรู้ว่า Deepfury รับโทษสมควรแล้ว เราล้างแค้นให้พี่น้องของ Longbraid ได้แล้ว" },
        required = { [3640] = { "16:2066919940:1002680450", "ศีรษะของ Deepfury" } },
        steps = { { "16:2066919940:1002680450", "ศีรษะของ Deepfury" } },
    },
    [386] = { -- What Comes Around...
        title = { "20:1374019964:67158861", "กรรมใดใครก่อ..." },
        objective = { "65:425289981:1154140146", "นำศีรษะ Targorr the Dread ไปให้ Guard Berton ที่ Lakeshire" },
        description = { "416:1244847235:1524505835 N 67:7138555:513831698", "Targorr the Dread เป็นหัวหน้าเพชฌฆาตใต้บัญชา Gath'Ilzogg วิธีของมันโหดเหี้ยมแม้ตามมาตรฐานออร์คสกปรก มันทรมานผู้กล้าปกป้องอาณาจักรตามอำเภอใจ ตอนนี้ถูกขังใน Stormwind Stockade และตัดสินประหาร แต่มีเรื่องผิดปกติ ขุนนางคนหนึ่งสั่งชะลอการประหาร ข้าแน่ใจว่ามีเล่ห์สกปรก\n\nจบชีวิต Targorr the Dread เสีย {name} ไป Stockade แล้วตัดศีรษะมันก่อนเล่ห์ร้ายจะเล่นงานเรา" },
        progress = { "192:1978726770:1829320263 N 51:1374514995:592214984", "ได้ไป Stockade ที่ Stormwind หรือยัง? ข้ากลัวว่าเล่ห์ที่ทำให้ Targorr the Dread รอดถึงตอนนี้จะช่วยให้มันเป็นอิสระในที่สุด มันถูกตัดสินให้ตาย {name} ไม่ใช่เป็นหมากการเมืองตามใจขุนนาง" },
        completion = { "179:1435185097:566438938 N 113:304321973:1598738427", "ในที่สุด Targorr the Dread ก็พบชะตาตน ข้ายินดีที่เจ้าสัตว์ร้ายรู้รสการถูกเงื้อมมือความตายอันไร้เมตตาจับแล้ว เจ้าทำได้ดี {name} บางครั้งความยุติธรรมแท้จริงก็หาได้เพียงนอกศาลและพ้นสายตาที่การเมืองบดบัง" },
        required = { [3630] = { "15:1443788626:2018113088", "ศีรษะของ Targorr" } },
        steps = { { "15:1443788626:2018113088", "ศีรษะของ Targorr" } },
    },
    [387] = { -- Quell The Uprising
        title = { "18:785953841:169460607", "ปราบการลุกฮือ", variants = { { "18:1330231841:35600934", "ปราบการลุกฮือ" } } },
        objective = { "128:1158461034:752820727", "Warden Thelwater แห่ง Stormwind ต้องการให้เจ้าสังหาร Defias Prisoner 10 คน, Defias Convict 8 คน และ Defias Insurgent 8 คนใน Stockade" },
        description = { "374:241619883:1711800326", "ต้องปราบการลุกฮือนี้! ข้าต้องให้เจ้าช่วย หากข่าวหลุดว่าคุกถูกยึด ข้าตกงานแน่ เรื่องนี้ต้องมีแผนร้ายอยู่เบื้องหลัง แต่สิ่งสำคัญตอนนี้คือบังคับให้นักโทษยอมจำนนเพื่อความปลอดภัยของ Stormwind\n\nโทษของการก่อกบฏคือตาย กำจัดพวกนอกลู่นอกทางเสียบ้าง! คงช่วยให้ควบคุมสถานการณ์ได้" },
        progress = { "149:649352716:197392631", "Stockade ยังถูกยึดอยู่! ต้องทำให้หนู Defias พวกนี้เห็นว่าเราจะไม่ยอมรับการกระทำของมัน กลับลงไปแสดงกำลังเดี๋ยวนี้!" },
        completion = { "43:174156282:391664589 N 114:1460744257:930562075", "เจ้าแสดงความกล้าหาญใน Stockade {name} เห็นชัดว่าปัญหานี้ใหญ่เกินเราสองคน แต่เจ้าทำได้ดี ข้าจึงขอบใจ" },
        objectiveLabels = {
            monster = { ["Defias Prisoner slain"] = "ปราบ นักโทษ Defias", ["Defias Convict slain"] = "ปราบ นักโทษเด็ดขาด Defias", ["Defias Insurgent slain"] = "ปราบ ผู้ก่อกบฏ Defias" },
        },
    },
    [388] = { -- The Color of Blood
        title = { "18:2141995904:510879206", "สีแห่งเลือด" },
        objective = { "69:1962171102:854449920", "Nikova Raskol แห่ง Stormwind ต้องการ Red Wool Bandana 10 ผืน" },
        description = { "497:1205807950:135093829", "ความขมขื่นไหลในเส้นเลือดข้าดั่งธารเย็น Mac หลานชายเป็นเด็กดี อายุเพียง 14 เมื่อกองทัพถูกส่งแนวหน้า Mac จับอาวุธปกป้องเมือง เป็นยามใน Stockade ที่ขังแก๊ง Defias เขาตักเตือนนักโทษที่ฉีกผ้าห่มขนสัตว์ทำผ้าพันคอสัญลักษณ์แก๊ง เพราะเรื่องนั้น Mac จึงถูกแทงข้างหลัง\n\nข้าต้องการล้างแค้น นำ Wool Bandana อันหวงแหนของมันมา 10 ผืน มันมีสีเดียวกับเลือด" },
        progress = { "20:168162824:875123572 C 85:1389537340:2080902681", "กลับมาแล้วหรือ {class} เก็บ Red Wool Bandana 10 ผืนจากสวะ Defias ใน Stockade ได้หรือยัง?" },
        completion = { "173:662347410:1272233790 N 61:1771338466:262776870", "ผ้าเหล่านี้... สัญลักษณ์โสโครกแห่งความเสื่อมทราม... คือเหตุให้ Mac ของข้าต้องตายหรือ? สูญเปล่านัก เป็นการเสียสละที่เศร้าสลด\n\nแต่ข้าย้อนอดีตไม่ได้ เพียงรู้ไว้ {name} ว่าสิ่งที่เจ้าทำให้ความยุติธรรมแก่ครอบครัวข้าแล้ว" },
        required = { [2909] = { "16:75088536:1877370768", "ผ้าคาดหัวขนสัตว์สีแดง" } },
        steps = { { "16:75088536:1877370768", "ผ้าคาดหัวขนสัตว์สีแดง" } },
    },
    [391] = { -- The Stockade Riots
        title = { "18:1277973499:1451407098", "เหตุจลาจลใน Stockade" },
        objective = { "78:2058405623:579128422", "สังหาร Bazil Thredd แล้วนำศีรษะกลับไปให้ Warden Thelwater ที่ Stockade" },
        description = { "30:1604422205:354225017 N 384:985708788:779614671", "ให้เข้าใจตรงกันก่อน {name} ข้าไม่ไว้ใจเจ้า แต่สถานการณ์เช่นนี้ เจ้าคงเปลี่ยนอะไรไม่ได้มาก\n\nเอาเช่นนี้ ลงไปคุยกับ Thredd หากอยู่ฝ่ายเราจริง ก็ฆ่าเขาแล้วนำศีรษะมา หากอยู่ฝ่ายมันแล้วไม่กลับออกมา... เมื่อเราพบเจ้า เจ้าจะตายพร้อมหนอนพวกนั้น" },
        progress = { "67:276060959:1299186366 N 1:63:63", "ไม่เจ้าก็นำศีรษะ Thredd มาให้ข้า หรือข้าจะเอาศีรษะเจ้า เข้าใจไหม {name}?" },
        completion = { "344:956505254:40909269", "ไม่มี Thredd นำแล้ว หวังว่าจะคุมจลาจลได้ง่ายขึ้น ต้องรอดู\n\nต้องบอกว่าผ่านไปครึ่งชั่วโมง ข้าแทบไม่คิดว่าเจ้าจะกลับออกมา ดูเหมือนข้าตัดสินเจ้าผิด\n\nข้าเดาว่าเจ้าไม่ได้ข้อมูลมีประโยชน์จากเขานักใช่ไหม? แต่ข้ารู้เรื่องกิจกรรมของ Thredd บางอย่างที่เจ้าอาจสนใจ" },
        required = { [2926] = { "20:1825103441:80662439", "ศีรษะของ Bazil Thredd" } },
        steps = { { "20:1825103441:80662439", "ศีรษะของ Bazil Thredd" } },
    },
    [704] = { -- Agmond's Fate
        title = { "13:210123809:1114721469", "ชะตากรรมของ Agmond" },
        objective = { "63:378246422:1728710835", "นำ Carved Stone Urn 4 ใบไปให้ Prospector Ironband ที่ Loch Modan" },
        description = { "373:1541596490:1119195206", "รายงานสุดท้ายจาก Agmond ทำให้ข้ากังวล ยิ่งตอนนี้เขาตายแล้ว! เขาบอกว่าคนงานพบ “โกศโบราณ” ที่แหล่งขุดนอก Uldaman ข้ากลัวว่าโกศพวกนั้นปลุกปั่นโทรกก์เช่นเดียวกับเทวรูปที่ข้าพบที่นี่\n\nข้าต้องใช้โกศศึกษา ไปแหล่ง Uldaman รวบรวมโกศแล้วกลับมา" },
        progress = { "25:1863650114:655909119 N 52:1962904443:1587615965", "พบโกศหรือยัง {name}? เราต้องหาความเชื่อมโยงระหว่างมันกับโทรกก์!" },
        completion = { "166:761515171:751949848 N 62:581000115:229354317", "ทำได้ดี! หากมีโชคและเพียรพอ เราจะพบความเชื่อมโยงระหว่างโทรกก์กับวัตถุโบราณเหล่านี้\n\nเจ้าทำคุณแก่เหล่านักสำรวจอย่างยิ่ง {name} ความพยายามเจ้าจะไม่ถูกลืม และ Agmond ก็เช่นกัน" },
        required = { [4610] = { "16:974884562:1735043960", "โถหินแกะสลัก" } },
        objectiveLabels = {
            item = { ["Carved Stone Urn"] = "โถหินแกะสลัก" },
        },
    },
    [709] = { -- Solution to Doom
        title = { "16:1590080782:166641423", "หนทางเลี่ยงหายนะ" },
        objective = { "50:799836258:549468596", "นำ Tablet of Ryun'eh ไปให้ Theldurin the Lost" },
        description = { "484:1851896045:975894981", "โอ้! โอ้! หายนะกำลังมา จำคำข้า! หายนะ!\n\nไม่ ข้าพูดไม่ได้... เอ่ยชื่อพวกมันไม่ได้ ไม่เช่นนั้นอาจได้ยินข้า! แต่หากเรารู้ ใช่ รู้เรื่องพวกมันมากขึ้น... บางทีจะหาวิธีขัดขวางได้!\n\nบางทีนะ\n\nเข้า Uldaman ไม่! ข้าพูดไปแล้ว! เจ้าต้องหา... แผ่นจารึกของ... Ryun'eh ใช่ หาให้เจอ! อย่าให้ข้าพูดชื่อนั้นอีก!\n\nมันอยู่ลึกในที่นั้น ในหีบโบราณ มันซ่อนอยู่ตรงนั้น... ในหีบที่สร้างก่อนผลงานของคนแคระทั้งปวง" },
        progress = { "66:723553292:549023284", "พบแผ่นจารึกหรือยัง? มันต้องมีความลับ! ความลับที่จะช่วยเรา!" },
        completion = { "55:972049230:786476774", "โอ้ โชคเข้าข้างเรา! ขอบใจ! เรายังอาจรอดได้!" },
        required = { [4631] = { "17:1746535779:924232980", "แผ่นจารึกของ Ryun'eh" } },
        steps = { { "17:1746535779:924232980", "แผ่นจารึกของ Ryun'eh" } },
    },
    [721] = { -- A Sign of Hope
        title = { "14:1016816697:1614185711", "ร่องรอยแห่งความหวัง" },
        objective = { "31:993163934:493607826", "หา Hammertoe Grez ใน Uldaman" },
        description = { "N 480:165809046:626101793", "{name} จะหาเขาได้ไหม? หา Hammertoe ใน Uldaman ได้ไหม?\n\nหากพวก Shadowforge สกปรกจับเขาเป็นตัวประกันเพื่อรีดความรู้เรื่องแหล่งขุดไททัน Ironforge ทั้งเมืองอาจเดือดร้อนหนัก\n\nDark Iron ตามหาเวทมนตร์เพื่อสร้างโกเลมให้แข็งแกร่งขึ้นมานาน แน่นอนว่า Hammertoe ก็ทำเช่นกัน แต่เพื่อหยุดพวกมันเท่านั้น\n\nมันคงไว้ชีวิตเขาจนกว่าจะได้ความรู้ เจ้าต้องรีบหากจะช่วยเขา!" },
        completion = { "61:295159566:1810256731 C 99:716930474:1000383877", "ว่าอย่างไร? ขอโทษ... <ไอ> อ่อนแรงเหลือเกิน เข้ามาใกล้หน่อยได้ไหม {class}?\n\nRyedol ส่งมาหรือ? สรรเสริญ Muradin เด็กนั่นไม่ได้หัวช้าอย่างที่ข้าเคยคิด <ไอ>" },
    },
    [722] = { -- Amulet of Secrets
        title = { "17:695229041:684569008", "เครื่องรางแห่งความลับ" },
        objective = { "56:368101240:1254139410", "หา Hammertoe's Amulet แล้วนำกลับไปให้เขาใน Uldaman" },
        description = { "55:1749409811:1663350421 C 285:725799721:313074502 N 149:1579001880:1846716526", "เจ้ากล้าหาญ... <ไอ>... ที่เข้า Uldaman เพื่อข้า {class}\n\nหากมาช่วย... Hammertoe แก่ ๆ จริง... <ไอ>... เจ้าต้องหา... เครื่องรางข้า\n\nDeepshadow เอาไป... Magregan Deepshadow เขาอยู่แถวนี้... ในซากปรักแน่ เครื่องรางจะนำพวกมัน... <ไอ>... ไปถึงม้วนคัมภีร์หากไม่หยุดเขา อยู่ที่เจ้าแล้ว {name} ได้โปรด... เอาเครื่องรางมา\n\nม้วนคัมภีร์จะช่วย Dark Iron สร้างโกเลมแข็งแกร่งกว่าเดิมแน่ ข้ารู้สึกได้ถึงกระดูก" },
        progress = { "91:1965315278:252497029", "เผ่า Shadowforge... <ไอ> อันตราย ระวังด้วย <ไอ> เจ้าต้องหาเครื่องราง" },
        completion = { "48:348132444:582814759 N 28:568027075:1273678501 N 9:1859723130:2069336537", "ฮ่า! <ไอ ไอ>\n\nรู้อยู่แล้วว่าเจ้าจะหาเครื่องรางพบ {name}\n\n<หายใจครืดคราด> ทำได้ดีจริง ๆ {name} <ไอ>" },
        required = { [4635] = { "18:260398429:841444850", "เครื่องรางของ Hammertoe" } },
        steps = { { "18:260398429:841444850", "เครื่องรางของ Hammertoe" } },
    },
    [1139] = { -- The Lost Tablets of Will
        title = { "24:1409686672:900061345", "แผ่นจารึกเจตจำนงที่สาบสูญ" },
        objective = { "73:552365607:950019791", "หา Tablet of Will แล้วนำกลับไปให้ Advisor Belgrum ที่ Ironforge" },
        description = { "489:2115776749:1186787547", "เราตัด Shadowforge จาก Blackrock Spire จนชะลอพวกมันได้ แต่ภารกิจ Hammertoe ยังไม่สำเร็จ การตายเขาต้องไม่สูญเปล่า เขาฝันจะพบ Tablet of Will เศษหินที่ไททันจารึกเวทเองเพื่อมอบชีวิตแก่สิ่งที่สร้าง ให้มีเจตจำนงเป็นของตน หรืออย่างน้อยตำนานก็ว่าเช่นนั้น\n\nเรายังต้องนำแผ่นจารึกกลับมาก่อน Shadowforge พบ\n\nกลับ Uldaman หาแผ่นจารึก แล้วกลับมาที่นี่ทันที" },
        progress = { "38:984628720:1317844905 N 231:709207875:328584547", "ต้องทำภารกิจ Hammertoe ให้เป็นจริง {name} ข้าติดค้างเขาอย่างน้อยเท่านั้น\n\nการกลับ Uldaman ของเจ้าจำเป็นทั้งต่อเป้าหมายนั้นและความปลอดภัยของคนแคระทั้งเผ่าพันธุ์ หากแผ่นจารึกตกในมือ Dark Iron ใครจะรู้ว่ากองทัพโกเลมจะแข็งแกร่งเพียงใด" },
        completion = { "80:1185497917:1744516875 N 267:180154891:1369086456", "<Advisor Belgrum ส่ายหน้าอย่างไม่อยากเชื่อเมื่อเจ้าส่งเศษหินให้>\n\n{name} น่าทึ่งมาก ข้าจะส่งให้จอมเวทของกษัตริย์โดยเร็วที่สุด พวกเขาคงอยากศึกษาว่าตำนานจริงหรือไม่ แต่นั่นค่อยคุยกันวันหลัง เจ้าช่วยพวกเรามากเกินคาด ขอบใจ" },
        required = { [5824] = { "14:760755124:635529899", "แผ่นจารึกแห่งเจตจำนง" } },
        steps = { { "14:760755124:635529899", "แผ่นจารึกแห่งเจตจำนง" } },
    },
    [1360] = { -- Reclaimed Treasures
        title = { "19:1521505515:495652856", "ทวงคืนสมบัติ" },
        objective = { "126:1877440336:486568746", "นำของรักของ Krom Stoutarm จากหีบใน North Common Hall ของ Uldaman ไปให้เขาที่ Ironforge" },
        description = { "496:1474643318:2028438518", "ข้าเคยมีงานดีเป็นคนขุดที่ Uldaman ใน Badlands... จนโทรกก์บัดซบโผล่มา ข้าหนีแทบเอาชีวิตไม่รอด ไม่เหลืออะไรติดตัว ท่ามกลางความโกลาหลข้าทิ้งของรักที่สุดไว้ ในหีบย่อมปลอดภัยจากโทรกก์ แต่หีบอยู่กลางดงพวกมัน\n\nหากเอามาให้ ข้าจะติดหนี้ทั้งเกียรติและเงินทอง! หีบมีชื่อข้าอยู่ปลาย North Common Hall นั่นแหละใบที่ต้องเปิด" },
        progress = { "110:1336441457:963711608", "ว่าไง จัดการโทรกก์จนมีเวลาพอเปิดหีบหยิบสมบัติข้ามาหรือไม่?" },
        completion = { "213:166170690:1723804757", "อา ข้ารู้สึกครบถ้วนอีกครั้ง ขอบใจมาก\n\nคนแคระบางคนรักประกายโลหะ บางคนรักแสงอัญมณี... แต่ Stoutarm ที่ไม่มีเหยือกเบียร์คู่ใจในมือแทบเรียก Stoutarm ไม่ได้!" },
        required = { [8027] = { "24:1101959325:1077134628", "สมบัติของ Krom Stoutarm" } },
        steps = { { "24:1101959325:1077134628", "สมบัติของ Krom Stoutarm" } },
    },
    [2040] = { -- Underground Assault
        title = { "19:1791887081:136246724", "บุกจากใต้ดิน" },
        objective = { "103:1568090474:114903807", "นำ Gnoam Sprecklesprocket จาก Deadmines กลับไปให้ Shoni the Shilent ที่ Stormwind" },
        description = { "116:890486184:1196383162 N 317:1890777328:811959116", "Gnomeregan ตกอยู่ใต้การควบคุมโทรกก์ชั่วช้าแล้ว! สถานการณ์ร้ายแรง แต่บางทีเจ้าช่วยได้ {name}\n\nลึกใน Deadmines มีเครื่องกลตัดไม้ก็อบลินที่ยังทำงาน หาเครื่องนั้นแล้วนำแหล่งจ่ายพลังงานที่สมบูรณ์กลับมา เราจะใช้พลังมันขับเครื่องขุด Gyrodrillmatic ให้เจาะแนวหินใต้ดินของ Gnomeregan เปิดทางให้กองโนมบุก!" },
        progress = { "43:1803452609:273250172 N 1:63:63", "พบ Gnoam Sprecklesprocket หรือยัง {name}?" },
        completion = { "11:534428891:784080240 N 72:1569661526:100080154", "ทำได้ดี {name} เพราะเจ้า วันปลดปล่อย Gnomeregan จึงใกล้ขึ้นอีกก้าว!" },
        required = { [7365] = { "22:1454414698:2084538641", "ชิ้นส่วน Gnoam Sprecklesprocket" } },
        steps = { { "22:1454414698:2084538641", "ชิ้นส่วน Gnoam Sprecklesprocket" } },
    },
    [2198] = { -- The Shattered Necklace
        title = { "22:1687408745:1407912400", "สร้อยคอแตกหัก" },
        objective = { "90:1307354587:1062493927", "หาผู้สร้างสร้อยคอแตกหักคนเดิม เพื่อเรียนรู้ว่ามันอาจมีมูลค่าเพียงใด" },
        description = { "468:1616928616:124502826", "เจ้าพบสร้อยคอหมองมัว แต่ใต้คราบนั้นเป็นฝีมือประณีตเปี่ยมเวท สร้อยแตกหักและตัวเรือนดูเหมือนขาดอัญมณีสามเม็ด ด้านใต้มีรอยตราเมือง Ironforge จาง ๆ ใต้ตรามีอักษรเล็กสามตัวสลักว่า “TdK”\n\nหากอยากรู้อะไรจากสร้อย ต้องสืบที่มา ตราและอักษรย่ออาจเป็นจุดเริ่มต้น..." },
        progress = { "156:920036857:1923080754", "ผิดโนมแล้ว สหาย! ข้าไม่เคยไปที่นั่น! เจ้าพิสูจน์อะไรไม่ได้!\n\nเดี๋ยวก่อน... เจ้าเป็นใคร? อะไรกัน... ไปพบสร้อยนี้ที่ไหน?" },
        completion = { "225:1082437507:1573265124", "ใช่... ข้าคือช่างอัญมณีผู้ทำสร้อยนี้ และข้าไม่ได้แจกข้อมูลฟรี ข้อมูลไม่เคยฟรี สหาย หากจะให้ข้าช่วย เจ้าต้องช่วยข้าก่อน" },
        required = { [7666] = { "18:2056637861:1290237744", "สร้อยคอที่แตกเป็นชิ้น" } },
        steps = { { "18:2056637861:1290237744", "สร้อยคอที่แตกเป็นชิ้น" } },
    },
    [2199] = { -- Lore for a Price
        title = { "16:492344267:725911466", "ความรู้มีราคา" },
        objective = { "58:339443151:170651894", "นำ Silver Bar ห้าแท่งไปให้ Talvash del Kissel ที่ Ironforge" },
        description = { "489:1448446503:1690785128", "ข้าเป็นช่างอัญมณีชื่อดังใน Ironforge! เอ่อ เคยดังน่ะ... ตอนนี้ลำบากเพราะกลโกงคู่แข่ง! ชื่อเสียในวงการนี้คือหายนะทางการเงิน ชื่ออันดีที่ปัจจุบันด่างพร้อยทำให้ข้าไม่มีแม้แต่เหรียญทองแดง\n\nข้าอยากให้หา Silver Bar ห้าแท่ง เพื่อทำคำสั่งซื้อที่เพิ่งได้ ครั้งแรกในเวลาราวชั่วนิรันดร์\n\nนำห้าแท่งมา แล้วข้าจะตอบคำถามเรื่องสร้อย" },
        progress = { "199:1022912760:530829186", "ได้ Silver Bar ห้าแท่งที่ขอหรือยัง? ข้าจะเล่าความทุกข์เศร้าเกี่ยวกับสร้อยที่เจ้ามี... แต่ต้องได้แท่งเงินก่อน! ช่วยโนมสักคนเถอะนะ?" },
        completion = { "495:1107051530:280792729", "ข้าว่าเจ้าใช้ได้ ไม่สนหรอกว่าคนอื่นพูดอย่างไร... ล้อเล่น! ขอบใจจริง ๆ สหาย\n\nสร้อยที่เจ้ามีเป็นผลงานดีที่สุดชิ้นหนึ่งของข้า แต่ขาดอัญมณีสามเม็ดที่ผูกพลังเวทไว้ ข้าทำให้พาลาดินคนหนึ่งก่อนหน้านี้ เขาตั้งภารกิจเองว่าจะล้าง “มลทินชั่วร้าย” ที่แหล่งขุด Uldaman ใน Badlands\n\nเอ่อ... พาลาดินตายใน Uldaman และนั่นเพิ่งเป็นจุดเริ่มต้นความทุกข์ของข้า" },
        required = { [2842] = { "10:1293727786:854722126", "แท่งเงิน" } },
        steps = { { "10:1293727786:854722126", "แท่งเงิน" } },
    },
    [2200] = { -- Back to Uldaman
        title = { "15:1312134159:881016884", "กลับสู่ Uldaman" },
        objective = { "147:223646048:443461742", "ค้นหาเบาะแสสภาพปัจจุบันของสร้อย Talvash ใน Uldaman พาลาดินที่ตายซึ่งเขาพูดถึงคือผู้ครอบครองคนสุดท้าย", variants = { { "147:1029187937:378586054", "ค้นหาเบาะแสสภาพปัจจุบันของสร้อย Talvash ใน Uldaman พาลาดินที่ตายซึ่งเขาพูดถึงคือผู้ครอบครองคนสุดท้าย" } } },
        description = { "140:959593025:1287937897 N 351:310084047:2037338310", "คู่แข่งปล่อยข่าวว่าสร้อยข้าสาปพาลาดิน แน่นอนว่าไม่มีใครอยากซื้อของต้องคำสาปจากช่างอัญมณี\n\n{name} มาตกลงกัน หาอัญมณีแล้วข้าจะประกอบสร้อยใหม่ ขอเพียงเจ้าประกาศว่าข้าไม่ได้ทำของต้องคำสาป!\n\nลองหาเบาะแสใน Uldaman อาจพบศพพาลาดิน เพราะเรารู้ว่าเขามีสร้อยเป็นคนสุดท้าย เมื่อพบอัญมณีให้ใช้สิ่งนี้ มันจะติดต่อข้าที่ Ironforge ได้" },
        completion = { "424:1675569772:101423572", "ซากพาลาดิน: อ่านบันทึกแล้วพบว่าหลังพยายามมากมาย พาลาดินระบุตำแหน่งอัญมณีที่หายทั้งสามได้แล้ว\n\nคนแคระ Shadowforge ซ่อนทับทิมในเขตกีดขวางของตน ขณะสู้โทรกก์เพื่อครอง Uldaman\n\nโทรกก์ซ่อนโทแพซในโกศใกล้ผู้พักอาศัยแปลกตาของ Uldaman นั่นคือคนแคระ Alliance!\n\nสุดท้าย ผู้อาวุโสโทรกก์เอาไพลินเป็นของตน" },
    },
    [2201] = { -- Find the Gems
        title = { "13:1737896783:1027857032", "ตามหาอัญมณี" },
        objective = { "425:276265689:1158320309", "หาทับทิม ไพลิน และโทแพซที่กระจายอยู่ใน Uldaman เมื่อครบให้ติดต่อ Talvash del Kissel จากระยะไกลด้วย Phial of Scrying ที่เขาเคยให้\n\nจากบันทึก เจ้ารู้ว่า...\n• ทับทิมซ่อนในเขต Shadowforge ที่กั้นแนวป้องกัน\n• โทแพซซ่อนในโกศบริเวณโทรกก์ ใกล้คนแคระ Alliance\n\n• ไพลินถูก Grimlok ผู้นำโทรกก์ยึดไว้" },
        description = { "475:1844398989:1405998879", "บันทึกพาลาดินอาจเป็นเบาะแสเดียวใน Uldaman ที่บอกตำแหน่งอัญมณีสร้อย หากที่เขาเขียนยังถูกต้อง เจ้าต้องรับมือคนแคระ Shadowforge กับโทรกก์ที่แย่งแหล่งขุดกัน\n\nเมื่อรู้เช่นนี้ การค้นหาอัญมณีจึงเริ่มจริงจัง เมื่อรวบรวมครบควรแจ้ง Talvash ที่ Ironforge ผ่าน Phial of Scrying ตามคำสั่งเขา" },
        progress = { "327:894289278:396373836", "ภาพ Talvash ชัดขึ้นจากน้ำในชามทำนาย\n\n“โอ้ ยังมีชีวิต! หาอัญมณีพบหรือยัง? เจ้าคือผู้กอบกู้ชื่อเสียงที่ข้าหวังจริงไหม? อย่าบอกว่าใช้พลังขวดไปเพียงเพื่อคุยเล่น ของพวกนี้ไม่ถูก และข้าก็ย่ำแย่ทางการเงินอยู่แล้ว”" },
        completion = { "150:60062680:1393710494 C 181:1868918270:979168685", "ใช่ นั่นคืออัญมณีสามเม็ดจริง ทำได้ดี! น่าเสียดายงานเจ้ายังไม่จบ\n\nไม่ ข้าไม่ได้เล่นตุกติก {class}เจ้าทึ่ม นี่คือการทำเครื่องประดับเวท ระดับคุณภาพ Talvash del Kissel! ต้องมีแหล่งพลังงานเข้มแข็งเพิ่มแรงให้มัน แต่สร้อยนี้ไม่มีแรงเหลือแล้ว" },
        required = { [7669] = { "23:894200734:662948309", "ทับทิมจากสร้อยคอที่แตก" }, [7670] = { "27:918299256:1937795311", "ไพลินจากสร้อยคอที่แตก" }, [7671] = { "24:62915705:1522631847", "บุษราคัมจากสร้อยคอที่แตก" } },
        steps = { { "23:894200734:662948309", "ทับทิมจากสร้อยคอที่แตก" }, { "27:918299256:1937795311", "ไพลินจากสร้อยคอที่แตก" }, { "24:62915705:1522631847", "บุษราคัมจากสร้อยคอที่แตก" } },
    },
    [2202] = { -- Uldaman Reagent Run
        title = { "19:489206682:2133046280", "เก็บวัตถุดิบจาก Uldaman" },
        objective = { "59:136703315:1641156943", "นำ Magenta Fungus Cap 12 ชิ้นไปให้ Jarkal Mossmeld ที่ Kargath" },
        description = { "490:415026418:2107494929", "ข้าได้ยินเรื่องพืชที่เพิ่งค้นพบชื่อ Magenta Fungus Cap มันขึ้นเป็นกลุ่มลึกในแหล่งขุดค้น Uldaman อาจมีที่อื่นด้วย แต่ตอนนี้ข้ารู้แค่ที่นั่น ข้าอยากศึกษาประโยชน์ในการเล่นแร่แปรธาตุ จึงต้องพึ่งเจ้า\n\nหากลุ่มเห็ดสีม่วงแดงแล้วนำดอกมาสิบสองดอก ระวังด้วย หากกระทบกระเทือนมันอาจพ่นสปอร์พิษ\n\nทำให้ข้า แล้วข้าจะปรุงยาอายุวัฒนะฟื้นกำลังอันเลื่องชื่อให้ชุดหนึ่ง!", variants = { { "480:741239426:568814440", "ข้าได้ยินเรื่องพืชที่เพิ่งค้นพบชื่อ Magenta Fungus Cap มันขึ้นเป็นกลุ่มลึกในแหล่งขุดค้น Uldaman อาจมีที่อื่นด้วย แต่ตอนนี้ข้ารู้แค่ที่นั่น ข้าอยากศึกษาประโยชน์ในการเล่นแร่แปรธาตุ จึงต้องพึ่งเจ้า\n\nหากลุ่มเห็ดสีม่วงแดงแล้วนำดอกมาสิบสองดอก ระวังด้วย หากกระทบกระเทือนมันอาจพ่นสปอร์พิษ\n\nทำให้ข้า แล้วข้าจะปรุงGreater Mender's Potionให้ชุดหนึ่ง!" } } },
        progress = { "93:1102159570:242740663", "ได้ดอกเห็ดสีม่วงแดงที่ข้าต้องใช้ในงานเล่นแร่แปรธาตุหรือยัง? ไม่มีเห็ดก็ไม่มีรางวัล!" },
        completion = { "10:963015740:1087923650 N 335:1630700758:1631202709", "ทำได้ดี {name} เจ้าพิสูจน์คุณค่าของตนอีกครั้งแล้ว! ดอกเห็ดน่าศึกษาแน่นอน\n\nตามสัญญา ลองลิ้มยาฟื้นกำลังฤทธิ์แรงจากคลังส่วนตัวข้าสิ...\n\nหากเชี่ยวชาญเล่นแร่แปรธาตุ เราอาจมีธุระอื่นร่วมกันได้อีก ไม่ว่าอย่างไร ขอบใจที่ช่วย!" },
        required = { [8047] = { "18:1620538754:1643817321", "หมวกเห็ดสีม่วงแดง" } },
        steps = { { "18:1620538754:1643817321", "หมวกเห็ดสีม่วงแดง" } },
    },
    [2204] = { -- Restoring the Necklace
        title = { "22:1231277358:441044830", "ฟื้นฟูสร้อยคอ" },
        objective = { "130:1983038210:1193045125", "หาแหล่งพลังงานจากสิ่งสร้างที่แข็งแกร่งที่สุดที่พบใน Uldaman แล้วส่งให้ Talvash del Kissel ที่ Ironforge" },
        description = { "490:2087138846:187324536", "เจ้าต้องหา “แรง” ให้สร้อย และความจริง Uldaman น่าจะเหมาะที่สุด ในนั้นคงมีสิ่งสร้างวิ่งเพ่นพ่านมากใช่ไหม? จัดการตัวใหญ่ที่สุด ร้ายกาจที่สุด แล้วเอาแหล่งพลังงานมา! ข้าค่อนข้างมั่นใจว่าประสานมันเข้ากับสร้อยได้\n\nไม่มีแหล่งพลังงานก็ซ่อมสร้อยไม่ได้ เมื่อได้แล้วกลับมาหาข้าที่ Ironforge เราจะซ่อมให้เรียบร้อย!" },
        progress = { "270:731009173:1937801708", "ออก Uldaman แล้วเจ้าไม่หยุดจัดตัวให้เรียบร้อยเลยใช่ไหม ตรงมานี่ทั้งที่กลิ่นดันเจียนยังติด หวังว่าการมาครั้งนี้จะแค่เหม็น ไม่ใช่ไร้ประโยชน์ด้วย\n\nมีแหล่งพลังงานสร้อยหรือยัง?" },
        completion = { "355:1408532449:2034897329", "โอ้ ข้าดีใจที่เห็นทั้งเจ้ากับแหล่งพลังงานกลับมาปลอดภัย เมื่ออัญมณีกลับเข้าที่แล้ว ข้าต้องใช้เวลาสักครู่ประสานแหล่งพลังงานกับสร้อยด้วยเวท เมื่อเสร็จสร้อยจะเป็นของเจ้า!\n\nตื่นเต้นใช่ไหม? ลุ้นจนใจสั่นเลยหรือ? ข้าเอาสื่อเวทไปวางไหนนะ..." },
        required = { [7672] = { "31:475357063:1859431998", "แหล่งพลังงานของสร้อยคอที่แตก" } },
        steps = { { "31:475357063:1859431998", "แหล่งพลังงานของสร้อยคอที่แตก" } },
    },
    [2240] = { -- The Hidden Chamber
        title = { "18:285194717:1757572862", "ห้องลับ" },
        objective = { "87:706424474:1821242347", "อ่าน Baelog's Journal สำรวจห้องลับ แล้วรายงาน Prospector Stormpike" },
        description = { "313:1541530675:1946583172 N 156:79931383:857968435", "มาว่ากันเรื่องงาน\n\nมีห้องลับ Chamber of Khaz'mul ที่ต้องสำรวจ ปัญหาคืออยู่หลังประตูใหญ่ที่ล็อก! โชคดีข้ารู้วิธีเปิด\n\nข้าอธิบายทุกอย่างในบันทึกบนโต๊ะนี่ ข้ากับพวกติดอยู่ที่นี่ตอนนี้... ดังนั้นเจ้า {name} ต้องหาห้อง Khaz'mul แทนเรา!\n\nอ่านบันทึก สำรวจห้อง แล้วรายงาน Prospector Stormpike ที่ Explorers' League ใน Ironforge" },
        progress = { "32:846830708:438008355", "มีอะไรจะรายงานหรือ?" },
        completion = { "126:2127771989:597616 N 197:21962551:1334423286", "เจ้าเห็น Chamber of Khaz'mul แล้วหรือ? น่าทึ่ง! Baelog มั่นใจว่ามีจริง แต่ยอมรับว่าข้าสงสัย\n\nขอบใจ {name} หวังว่าการค้นพบจะกระตุ้นผู้นำให้กลับมาทุ่มเทยึด Uldaman หากมันกลับอยู่ใต้ Ironforge ความลับ Chamber of Khaz'mul จะเป็นของเรา!" },
        objectiveLabels = {
            event = { ["Explore the Hidden Chamber"] = "สำรวจห้องลับ" },
        },
    },
    [2278] = { -- The Platinum Discs
        title = { "18:39549661:953126646", "แผ่นแพลทินัม" },
        objective = { "144:1286801443:1519143103", "คุยกับผู้เฝ้าศิลาและเรียนรู้ความรู้โบราณที่มันเก็บไว้ เมื่อเรียนรู้แล้วให้เปิดใช้ Discs of Norgannon" },
        description = { "476:495573672:1930554315", "ใจกลางห้องสมบัติมีแผ่นแพลทินัมมหึมาสี่แผ่น แต่ละแผ่นประดับอักขระมากมายไม่ทราบที่มา เมื่อแตะ มือเจ้ารู้สึกซ่า แล้วภาพผู้เฝ้าศิลาขนาดใหญ่ก็ปรากฏ\n\n“สวัสดี ข้าคือผู้เก็บรักษาความรู้ การสังเคราะห์ Earthen โดยเหล่าผู้สร้างถูกบันทึกและเก็บไว้สำหรับโลกนี้ ใน Discs of Norgannon”\n\nเจ้าพบขุมความรู้เรื่องโลกที่ยังไม่เคยถูกค้นพบ!" },
        progress = { "357:1267746977:1484927073", "เสียงผู้เฝ้าศิลาดูจะก้องลึกถึงตัวตนภายในเจ้า\n\n“เจ้าต้องผ่านเงื่อนไขการรับข้อมูลของ Discs of Norgannon ก่อน เมื่อครบแล้วจึงจะได้รับอนุญาตให้เอาข้อมูลฉบับพกพาไป โปรดสำรวจข้อมูลในคลังนี้ให้ครบถ้วนก่อน”" },
        completion = { "374:563828382:2139211632", "ตามคำแนะนำผู้เฝ้าศิลา เจ้าเปิด Discs of Norgannon อีกครั้ง หลังเรียนรู้ประวัติ Earthen โทรกก์ และคนแคระแล้ว มีเสียงฮัมแผ่วสั้นจากแผ่น จากนั้นผู้เฝ้าศิลากล่าว\n\n“สังเคราะห์แผ่นเรียบร้อยแล้ว เปิด Discs of Norgannon อีกครั้งเพื่อรับสำเนาส่วนตัว”" },
        objectiveLabels = {
            event = { ["Learn what lore that the stone watcher has to offer"] = "เรียนรู้เรื่องราวที่ผู้เฝ้าศิลาจะเล่าให้ฟัง" },
        },
    },
    [2279] = { -- The Platinum Discs
        title = { "18:39549661:953126646", "แผ่นแพลทินัม" },
        objective = { "91:1893653207:1848385848", "นำ Discs of Norgannon ฉบับย่อส่วนไปให้ Explorers' League ที่ Ironforge" },
        description = { "487:1479429694:829790721", "แตะ Discs of Norgannon อีกครั้ง มือเจ้าซ่าเช่นเคย แต่คราวนี้มีเสียงบดแปลก ๆ จากข้างใน\n\nกระเป๋าเจ้าน้ำหนักเพิ่มกะทันหัน เมื่อเปิดพบแผ่นฉบับย่อส่วน!\n\nของเช่นนี้คงล้ำค่าสำหรับผู้สนใจประวัติศาสตร์โบราณ Azeroth กลุ่ม Explorers' League ใน Ironforge เป็นที่รู้จักทั่ว Alliance บางทีพวกเขาใช้ประโยชน์ได้ดี" },
        progress = { "157:439067527:1828103144", "ว่าอย่างไร มีอะไรให้ช่วย? ข้าบอกได้ว่าตอนนี้ยุ่งมาก แต่หากสำคัญยิ่งต่อ Explorers' League ข้าก็พร้อมฟัง!" },
        completion = { "118:1276970189:1661443683 C 315:1037387733:1174005899", "เจ้ามีอะไรนั่น... โอ้ พบที่ไหนนะ?\n\nจริงหรือ?\n\nคุยกับใครเรื่องอะไรนะ?\n\nจริงหรือเนี่ย?!\n\n{class}ผู้ยอดเยี่ยม เจ้าอาจค้นพบโบราณคดีแห่งปี! ในนามทวยเทพ ข้าพูดอะไรไป ต้องแห่งศตวรรษต่างหาก! หากแผ่นเป็นอย่างที่คิด นี่อาจคือกุญแจที่ตามหา! อาจพิสูจน์ได้เด็ดขาดว่าคนแคระถูกสร้างด้วยเวทมนตร์จริง!" },
        required = { [6064] = { "24:500077704:355707172", "แผ่นแพลทินัมขนาดย่อม" } },
        steps = { { "24:500077704:355707172", "แผ่นแพลทินัมขนาดย่อม" } },
    },
    [2280] = { -- The Platinum Discs
        title = { "18:39549661:953126646", "แผ่นแพลทินัม" },
        objective = { "94:1087373131:857020808", "นำ Discs of Norgannon ฉบับย่อส่วนไปให้ปราชญ์คนหนึ่งที่ Thunder Bluff" },
        description = { "480:1589416011:484128392", "แตะ Discs of Norgannon อีกครั้ง มือเจ้าซ่าเช่นเคย แต่คราวนี้มีเสียงบดแปลก ๆ จากข้างใน\n\nกระเป๋าเจ้าน้ำหนักเพิ่มกะทันหัน เมื่อเปิดพบแผ่นฉบับย่อส่วน!\n\nของเช่นนี้คงล้ำค่าสำหรับผู้สนใจประวัติศาสตร์โบราณ Azeroth เหล่าปราชญ์ Thunder Bluff เป็นนักประวัติศาสตร์ที่รู้จักทั่ว Horde บางทีพวกเขาใช้ประโยชน์ได้ดี" },
        progress = { "244:1345962176:503749482", "ว่าไง เจ้าผู้เยาว์ ข้าเห็นเจ้าเดินเข้าเต็นท์อย่างมุ่งมั่น... ตั้งใจแน่วแน่ มีเรื่องสำคัญต่อ Horde มาขอคำแนะนำหรือ? หรือปรารถนาให้ข้าเผยความลับจักรวาล?" },
        completion = { "184:1600196982:696211875", "ของพวกนี้คืออะไร?\n\nน่าประทับใจ เจ้าผู้เยาว์! ข้าสัมผัสความลับที่แผ่นดินเก็บแน่นมาหลายปีในแผ่นเหล่านี้ เจ้าฉลาดมากที่นำมาหาข้า" },
        required = { [6064] = { "24:500077704:355707172", "แผ่นแพลทินัมขนาดย่อม" } },
        steps = { { "24:500077704:355707172", "แผ่นแพลทินัมขนาดย่อม" } },
    },
    [2283] = { -- Necklace Recovery
        title = { "17:1915110094:472049597", "กู้สร้อยคอ" },
        objective = { "134:829376170:83815123", "หาสร้อยคอมีค่าในแหล่งขุด Uldaman แล้วนำกลับไปให้ Dran Droffers ที่ Orgrimmar สร้อยอาจเสียหาย" },
        description = { "470:694081579:1286139668", "เรามีงานให้ หากเจ้ากล้าพอ!\n\nลึกใน Badlands มีแหล่งขุด Uldaman ได้ยินเรื่องพาลาดินโง่คนหนึ่งเพิ่งตายที่นั่น เราสนใจเพราะเขามีสร้อยค่ามาก ว่ากันว่ามีอัญมณีใหญ่สามเม็ด ทับทิม ไพลิน และโทแพซ\n\nสรุปคือเราต้องการ และจ่ายเหรียญเงินอย่างงามเพื่อให้ได้มา มันอาจเสียหาย แต่ไม่สำคัญ เราซ่อมรอยขีดข่วนเองได้" },
        progress = { "95:676455085:1145536815", "มีสร้อยหรือยัง? หากไม่มี อย่าหวังแม้แต่เหรียญทองแดงจากเรา!" },
        completion = { "380:1075395367:914796408", "อืม ของกู้มา! ข้าได้กลิ่นสร้อยจากตรงนี้ มาดูของงามกัน...\n\nเฮ้ คิดทำอะไร? สร้อยไม่มีอัญมณี! คิดว่าเราไม่เห็นหรือ? แม้แต่ Malton ยังรู้ว่ามันหาย\n\nเอาล่ะ บางทีเจ้าไม่ได้ขโมย... แต่ไร้อัญมณีสร้อยก็ไร้ค่า! งานเจ้ายังไม่จบ อีกไกลด้วย!" },
        required = { [7666] = { "18:2056637861:1290237744", "สร้อยคอที่แตกเป็นชิ้น" } },
        steps = { { "18:2056637861:1290237744", "สร้อยคอที่แตกเป็นชิ้น" } },
    },
    [2284] = { -- Necklace Recovery, Take 2
        title = { "25:1434320372:1807262877", "กู้สร้อยคอ ครั้งที่สอง" },
        objective = { "65:1779594834:1561277833", "หาเบาะแสตำแหน่งอัญมณีในส่วนลึกของ Uldaman" },
        description = { "475:124440922:1893425337", "แน่นอนพอ ๆ กับที่ Malton โง่ อัญมณียังอยู่ที่ไหนสักแห่งใน Uldaman เจ้าต้องกลับไปหา\n\nอย่างที่บอก หากข้อมูลถูกต้อง สร้อยต้องมีทับทิม ไพลิน และโทแพซ หาแล้วใส่กลับสร้อย\n\nอยู่ไหนใครจะรู้? บางทีอาจโชคดีพบศพพาลาดิน หากยังไม่ถูกปล้นจนเกลี้ยง อัญมณีอาจยังติดตัวเขา" },
        completion = { "442:620267967:895645239", "ดูเหมือนเจ้าพบซากพาลาดินที่ Dran กล่าวถึง ค้นแล้วพบสิ่งที่ดูเป็นบันทึก หนังสือสภาพย่ำแย่ เลือดแห้งเปื้อนเนื้อหาส่วนใหญ่ ส่วนที่พออ่านได้ก็ไม่รู้เรื่อง เท่าที่รู้ มันเขียนด้วยภาษาพื้นเมืองของมนุษย์\n\nเจ้าต้องให้คนแปลหนังสือก่อน จึงจะรู้ข้อมูลข้างใน" },
    },
    [2318] = { -- Translating the Journal
        title = { "23:318004245:293738451", "แปลบันทึก" },
        objective = { "127:1191852641:1792024664", "หาผู้แปลบันทึกพาลาดิน สถานที่ใกล้ที่สุดที่อาจมีคนช่วยคือ Kargath ใน Badlands" },
        description = { "320:496268070:1699487882", "เมื่อพบทางตัน เจ้ารู้ว่าต้องแปลหนังสือเป็นภาษาที่เข้าใจ โลกนี้มีคนทำได้มากมาย แต่ที่ใกล้ที่สุดที่อาจพบผู้แปลคือด่าน Kargath ใน Badlands บางทีควรเริ่มที่นั่น" },
        completion = { "7:794398360:558065801 C 485:325116325:706089913", "{class}ผู้ทรงพลัง ข้ารู้ว่าเจ้ามาทำอะไรใน Badlands รู้ว่าต้องการพรด้านภาษาของข้า เจ้าตามหาชิ้นส่วนสร้อยจาก Uldaman\n\nแปลกใจหรือ? อย่าเลย การรู้เรื่องเช่นนี้คืองานข้า มาคุยดีกว่าว่าจะทำอะไรแลกกับบันทึกแปล เชื่อเถอะ ข้าคือคนเดียวที่เจ้าจะพบว่าแปลได้\n\nยิ่งกว่านั้น ข้าจะให้ข้อเสนอที่ดีกว่า Dran Droffers และเจ้ายังทำข้อตกลงกับเขาจบได้ ทีนี้สนใจแล้วใช่ไหม?" },
    },
    [2338] = { -- Translating the Journal
        title = { "23:318004245:293738451", "แปลบันทึก" },
        objective = { "83:2146970085:760242498", "ให้ Jarkal ยืมสร้อยคอ แล้วเขาจะแปลบันทึกให้เป็นการแลกเปลี่ยน" },
        description = { "471:1475819853:802094126", "Droffers and Son Salvage ฉลาดไม่พอฟื้นเวทสร้อย แต่ข้าทำได้ ข้าเพียงอยากศึกษาสร้อยเพื่อเรียนรู้วิธีทำเอง จึงต้องมีสร้อยเจ้า ให้ข้ายืม ข้าจะแปลบันทึกแลกกับเวลาศึกษา ระหว่างเจ้าไปหาอัญมณี ข้าคงมีเวลารู้สิ่งที่ต้องการพอ\n\nข้อตกลงง่าย ๆ ไม่มีใครรู้ทัน เจ้าจะเอาอย่างไร?" },
        progress = { "45:68142582:1424274699 C 134:756957490:593831762", "คิดแล้วใช่ไหม? หากรับข้อเสนอนี้ เจ้าก็เป็น{class}ที่ฉลาด เราสองคนได้สิ่งที่ต้องการ ส่วน Droffers and Son Salvage จะคิดว่าพวกเขาก็ได้เช่นกัน" },
        completion = { "288:1548493700:537226626", "เจ้าเห็นข้อเสนอดีก็รู้ทันที ข้ารู้อยู่แล้วว่าพึ่งได้\n\nขอเวลาสักครู่ร่ายเวทแปลภาษามนุษย์เป็นรูปแบบที่เจ้าเข้าใจ ข้าเป็นโทรลล์รักษาคำพูด ถามใครใน Horde เรื่อง Jarkal Mossmeld ก็ได้ เอาล่ะ เริ่มกัน..." },
        required = { [7886] = { "20:1047818021:617539053", "บันทึกที่ยังไม่ได้แปล" } },
        steps = { { "20:1047818021:617539053", "บันทึกที่ยังไม่ได้แปล" } },
    },
    [2339] = { -- Find the Gems and Power Source
        title = { "30:1542066363:762773201", "หาอัญมณีและแหล่งพลังงาน" },
        objective = { "463:1756059812:690291", "หาอัญมณีทั้งสามและแหล่งพลังงานสร้อยจาก Uldaman แล้วนำไปให้ Jarkal Mossmeld ที่ Kargath เขาเชื่อว่าแหล่งพลังงานอาจอยู่กับสิ่งสร้างที่แข็งแกร่งที่สุดใน Uldaman\n\nจากบันทึก เจ้ารู้ว่า...\n• ทับทิมซ่อนในเขต Shadowforge ที่กั้นแนวป้องกัน\n• โทแพซซ่อนในโกศบริเวณโทรกก์ ใกล้คนแคระ Alliance\n• ไพลินถูก Grimlok ผู้นำโทรกก์ยึดไว้" },
        description = { "492:1563764328:1813107681", "นี่บันทึกแปลให้เจ้าอ่านเอง ใจความคือคนแคระซ่อนทับทิม โทรกก์ซ่อนโทแพซ และโทรกก์ชื่อ Grimlok มีไพลิน\n\nฟังนะ ต้องมีแหล่งพลังงานให้สร้อยทำงานอีกครั้ง Dran Droffers ไม่รู้เรื่องนี้ หากจะหา ข้าจะลง Uldaman ให้ลึกที่สุดแล้วฆ่าสิ่งสร้างที่แข็งแกร่งที่สุด มันคงมีของนั้นแน่\n\nเมื่อรวบรวมครบกลับมาที่นี่!" },
        progress = { "366:176710124:1250763271", "หากยังไม่มีอัญมณีและแหล่งพลังงานที่ส่งเวทกลับเข้าทำงานในสร้อยได้ เจ้าก็ต้องลงส่วนลึก Uldaman อีก\n\nเจ้าจะได้อัญมณีคืนเพื่อส่งให้พวกโง่ที่ Orgrimmar ส่วนข้าเก็บแหล่งพลังงาน เพราะมันคือสิ่งที่ทำให้สร้อยใช้การได้ตั้งแต่ต้น..." },
        completion = { "16:2103922072:1818543247 C 368:695435454:130607598", "ทำได้ดีมาก {class} ทีนี้แผนเบี่ยงทางเราจะให้ผลตอบแทนงาม ข้าศึกษาตัวสร้อยเสร็จแล้วและมั่นใจว่าทำซ้ำได้แน่นอน\n\nแต่ก่อนอื่น ข้าจะใช้คาถาเตรียมพิเศษวิเคราะห์อัญมณีอย่างรวดเร็ว ก่อนเจ้านำมันกับสร้อยกลับ Orgrimmar ใช้เวลาแค่ครู่เดียว" },
        required = { [7669] = { "23:894200734:662948309", "ทับทิมจากสร้อยคอที่แตก" }, [7670] = { "27:918299256:1937795311", "ไพลินจากสร้อยคอที่แตก" }, [7671] = { "24:62915705:1522631847", "บุษราคัมจากสร้อยคอที่แตก" }, [7672] = { "31:475357063:1859431998", "แหล่งพลังงานของสร้อยคอที่แตก" } },
        steps = { { "23:894200734:662948309", "ทับทิมจากสร้อยคอที่แตก" }, { "27:918299256:1937795311", "ไพลินจากสร้อยคอที่แตก" }, { "24:62915705:1522631847", "บุษราคัมจากสร้อยคอที่แตก" }, { "31:475357063:1859431998", "แหล่งพลังงานของสร้อยคอที่แตก" } },
    },
    [2340] = { -- Deliver the Gems
        title = { "16:594739328:1666849201", "ส่งอัญมณี" },
        objective = { "67:2130454654:1692557083", "ส่ง Necklace and Gem Salvage ให้ Dran Droffers ที่ Orgrimmar" },
        description = { "469:1510304516:1179983898", "ตัวเรือนสร้อยกับอัญมณีชนิดใดก็ใช้ได้ ขอเพียงวัสดุเหมือนกัน แต่แหล่งพลังงานนี้จะคืนเวทให้สร้อย... ข้าหวังเช่นนั้น\n\nข้ายินดีจัดอัญมณีให้สร้อยของเจ้า หากแหล่งพลังงานใช้ได้จริง\n\nไป Orgrimmar ทำสัญญากับ Droffers and Son Salvage ให้ครบ อย่าปริปากเรื่องข้อตกลงเรา เมื่อกลับมาอาจมีสิ่งประหลาดใจยอดเยี่ยมรออยู่" },
        progress = { "236:1471191408:1249952061", "ดูสิ ใครมา! กว่าจะมาถึงก็อ้อยอิ่งเสียจริง หวังว่าจะไม่เสียเวลาข้า! เจ้าจะไม่ได้เงินจนกว่าจะมีทุกอย่างที่ขอ และเชื่อเถอะ เราจะตรวจซ้ำสองรอบสามรอบ!" },
        completion = { "371:1399914357:2118370396", "ใช่ ครบแล้ว ว่าแต่ขอถุงด้วยได้ไหม? ไม่ขัดหรือ? ขอบใจนะ! ฮ่า!\n\nสร้อยนี้จะเป็นของที่ดีที่สุดที่เราเคยได้! ไม่ต้องเสียใจนัก ข้ามั่นใจว่าสร้อยคงไม่พอดีกับเจ้าอยู่แล้ว ฮ่าอีกที!\n\nสัญญาเป็นสัญญา นี่ค่าจ้างกู้ของ ธุระจบแล้วตอนนี้ กลับมาดูทีหลังว่ามีงานเพิ่มไหม ระหว่างนี้ไปได้!" },
    },
    [2341] = { -- Necklace Recovery, Take 3
        title = { "25:1434320373:1807262878", "กู้สร้อยคอ ครั้งที่สาม" },
        objective = { "61:1699878286:2066171497", "ไปพบ Jarkal Mossmeld ที่ Kargath ดูว่าเขาทำสำเร็จหรือไม่" },
        description = { "244:115168819:323823330", "ขณะ Dran กับ Malton Droffers ทะเลาะเรื่องของใหม่ ข้อตกลงครึ่งหนึ่งก็จบแล้ว ทีนี้ต้องกลับ Badlands ให้เรื่องเสร็จ เพราะ Jarkal Mossmeld ที่ Kargath อาจมีรางวัลพิเศษรอเจ้า" },
        completion = { "362:526223796:174243884", "แหล่งพลังงานที่ให้ดีเกินคาดทุกอย่าง ข้าทำสร้อยได้ทั้งให้เจ้าและข้า ยังเหลือพอทำอีกอย่างน้อยสามเส้น คงขายได้งามโดย Droffers and Son Salvage ไม่รู้ทัน\n\nนี่ สหาย ข้าขอบใจสำหรับงานยอดเยี่ยม... และมอบของพิเศษตอบแทนความลำบาก" },
    },
    [2342] = { -- Reclaimed Treasures
        title = { "19:1521505515:495652856", "ทวงคืนสมบัติ" },
        objective = { "136:897843388:2103234805", "นำสมบัติตระกูล Patrick Garrett จากหีบตระกูลใน South Common Hall ของ Uldaman ไปให้เขาที่ Undercity" },
        description = { "493:261870667:1218813306", "กวาดคอกค้างคาวด้วยไม้กวาดนี้ไม่คู่ควรกับ Garrett! ข้าได้เงินจากงานต้องสาปมาบ้าง และพร้อมจ่ายเจ้าเพื่อยกฐานะตน\n\nอาวุธคู่ตระกูล Garrett ถูกล็อกในหีบที่ South Common Hall ของ Uldaman ตั้งแต่พวกเราทำงานขุดที่นั่น ไม่มีมัน ข้าคงติดกวาดตามค้างคาวนรกพวกนี้ตลอดกาล จริง ๆ นะ\n\nนำสมบัติตระกูลกลับมาให้ข้า! ช่วยคืนสิทธิ์โดยกำเนิดข้าที!" },
        progress = { "191:1985706883:1456602830", "กวาดไม่จบเสียที... ค้างคาวพวกนี้เยาะข้ากับไม้กวาดไม่หยุด บอกทีว่าได้สมบัติตระกูลคืนแล้ว! ข้าเสนอเหรียญเงินให้ ยังไม่พออีกหรือ?!" },
        completion = { "200:2094308868:716703220", "ในที่สุด ไม้กวาดที่คู่ควร Garrett เจ้าคุ้มทุกเหรียญเงินที่จ่ายจริง ๆ!\n\nได้ยินไหม ค้างคาวชั่ว? ข้าถืออาวุธคู่ตระกูล Garrett แล้ว! สั่นกลัวเสีย ค้างคาว สั่นกลัวไป!!" },
        required = { [8026] = { "23:276660250:1640193764", "สมบัติประจำตระกูล Garrett" } },
        steps = { { "23:276660250:1640193764", "สมบัติประจำตระกูล Garrett" } },
    },
    [2361] = { -- Restoring the Necklace
        title = { "22:1231277358:441044830", "ฟื้นฟูสร้อยคอ" },
        completion = { "40:1128034573:601099805 C 242:1122609036:1113979519", "ข้ายินดีมอบสร้อยให้ {class}ผู้ทรงพลัง เจ้าช่วยอย่างประเมินค่าไม่ได้ ข้าขอบใจ จงสวมอย่างภูมิใจ และอย่าลืมบอกดัง ๆ ซ้ำ ๆ ว่าใครทำให้!\n\nถ้าเสริมด้วยว่ามันไม่ได้ต้องคำสาปจริง ๆ ก็จะเยี่ยมมาก" },
    },
    [2398] = { -- The Lost Dwarves
        title = { "16:1510276778:1641797980", "คนแคระที่สาบสูญ" },
        objective = { "23:59291376:1471089590", "หา Baelog ใน Uldaman" },
        description = { "476:1144933492:1082871214", "Uldaman ไม่ได้ถูกยึดมาตลอด พวกคนแคระ Ironforge เคยคุมพื้นที่ แต่... นั่นก่อนโทรกก์มา มันมาเร็วและมากจนแม้พลังคนแคระก็หยุดไม่ได้!\n\nโจมตีกะทันหันจนข้ากลัวว่าบางคนติดหลังแนวศัตรู\n\nBaelog เพื่อนข้านำคนแคระกลุ่มเล็กลึกเข้าไปก่อนโทรกก์โผล่ หากเขากับพวกยังอยู่ ข้าอยากให้เจ้าหาพวกเขา" },
        completion = { "153:1162191539:318449520 R 90:2013742810:2009602339 N 35:694514600:1312739773", "กว่าจะมา! ข้าเกือบแพ้พนัน Olaf!\n\nเขาพนันว่าหนวดจะยาวถึงเข่าก่อนได้เห็น{race}ที่ยังมีชีวิตอีก แต่เจ้าก็มาแล้ว และเห็นได้ว่าหนวด Olaf ยังขาดอีกหลายนิ้ว\n\nขอบใจ {name} ข้าจะแบ่งเงินชนะพนันให้" },
    },
    [2418] = { -- Power Stones
        title = { "12:848294225:2070588977", "ศิลาพลังงาน" },
        objective = { "89:100630177:120213356", "นำ Dentrium Power Stone 8 ชิ้นและ An'Alleum Power Stone 8 ชิ้นไปให้ Rigglefuzz ที่ Badlands" },
        description = { "496:1664846333:1267110810", "ก่อนหน้านี้ข้ามีเรื่องกับคนแคระ Shadowforge เขาพาข้าไป Angor Fortress ศึกษาหินประหลาดสองชนิดจาก Uldaman ข้าพบว่าหากจัดการถูกต้อง มันเป็นแหล่งพลังงานต่อเนื่องที่เสถียร ของที่พบในแหล่งขุดเก่าน่าทึ่งจริง!\n\nแต่พอบอกความลับหิน พวกเขาก็ไล่ข้าออกแล้วไปขุดหาเพิ่มใน Uldaman\n\nข้าอยากได้หินไว้เอง! เอามาทั้งสองชนิด แล้วข้าจะจ่ายอย่างงาม!" },
        progress = { "30:1603719483:611117942 N 54:1568657915:2067217509", "มีศิลาพลังงานหรือยัง {name}? ข้ามีหนูหุ่นยนต์ต้องใช้แหล่งพลังงาน..." },
        completion = { "44:1029546889:66787709 N 29:367460708:479629583 R 196:1598047225:1561822905", "เยี่ยม เจอมาแล้ว! ขอบใจมาก {name} เจ้าเป็น{race}ที่พึ่งพาได้ที่สุดที่เคยพบ!\n\nข้าแทบอดใจลองกับสิ่งประดิษฐ์ไม่ไหว เดิมพันเลยว่าหากสภาวะเหมาะ เครื่องที่ใช้หินนี้จะทำงานต่อไป ต่อไป และต่อไป..." },
        required = { [8009] = { "20:1387213045:1292261018", "ศิลาพลัง Dentrium" }, [8052] = { "21:1241300232:2078103933", "ศิลาพลัง An'Alleum" } },
        steps = { { "20:1387213045:1292261018", "ศิลาพลัง Dentrium" }, { "21:1241300232:2078103933", "ศิลาพลัง An'Alleum" } },
    },
    [2841] = { -- Rig Wars
        title = { "8:58181649:1752561496", "ศึกชิงเทคโนโลยีเครื่องกล" },
        objective = { "115:1660686937:2119068057", "นำ Rig Blueprints และ Thermaplugg's Safe Combination จาก Gnomeregan ไปให้ Nogg ที่ Orgrimmar" },
        description = { "212:849950777:1052622519 N 224:1855814713:668234958 N 60:523577954:87426936", "เทคโนโลยีโนม... เมื่อสองปีก่อนยังใช้เป็นมุกตลกเป็นส่วนใหญ่ แต่ยุคเปลี่ยนแล้ว ตอนนี้มันสร้างเครื่องกลใหม่ดีกว่าเครื่องตัดไม้เราทุกรุ่นรวมกัน ข้าต้องการแบบแปลน {name}!\n\nน่าเสียดาย แบบถูกล็อกในตู้เซฟใกล้ Mekgineer Thermaplugg และมีแต่เขาที่รู้รหัส\n\nทำทุกวิถีทางให้ได้รหัส {name} แล้วเปิดเซฟนำแบบแปลนกลับมา!" },
        progress = { "121:514939090:20122918", "ข้าไม่เห็นแบบแปลน เจ้าซ่อนตามตัวหรือเพียงยืนกวนใจข้า?" },
        completion = { "24:824796542:544499282 N 303:622622286:1453494383", "รู้อยู่แล้วว่าเจ้าทำได้ {name}! แต่ Sovik ยังแอบสงสัย\n\n<Nogg กระแอม>\n\nเมื่อมีแบบในมือ ก็เหลือเพียงเวลาให้เราเข้าใจนวัตกรรมโนมทั้งหมดที่ใช้สร้างเครื่อง แล้วเปลี่ยนมันเป็นนวัตกรรมก็อบลินสำหรับเครื่องตัดไม้รุ่นใหม่" },
        required = { [9153] = { "14:608498749:1322231479", "แบบพิมพ์เขียวของเครื่องจักร" }, [9299] = { "30:811029864:974785156", "รหัสตู้เซฟของ Thermaplugg" } },
        steps = { { "14:608498749:1322231479", "แบบพิมพ์เขียวของเครื่องจักร" }, { "30:811029864:974785156", "รหัสตู้เซฟของ Thermaplugg" } },
    },
    [2842] = { -- Chief Engineer Scooty
        title = { "21:470513460:1494793751", "หัวหน้าวิศวกร Scooty" },
        objective = { "31:623565118:1506566016", "คุยกับ Scooty ที่ Booty Bay" },
        description = { "210:5303830:528012949 N 257:1499051250:464840337", "ทันทีที่ได้ข่าวเครื่องกลโนมใหม่จาก Kernobee ข้ากับ Scooty ก็เริ่มทำ Transpolyporter 6000 หนทางสู่ Gnomeregan ที่เร็วและเชื่อถือได้ที่สุด\n\nในที่สุดก็พร้อมรับผู้โดยสาร {name} หากอยากลอง ไปคุย Scooty ที่คอก Wind Rider ใน Booty Bay ขึ้นเรือจาก Ratchet ไปได้\n\nแน่นอน เจ้าจะลองวิ่งไป Gnomeregan ผ่านภูเขา Dun Morogh ที่คนแคระยั้วเยี้ยก็ได้!" },
        completion = { "118:778782800:282883458 N 101:272808497:1922601450", "สวยใช่ไหม? สุดยอดเทคโนโลยีขนส่งก็อบลิน... ระเบิดไปแค่สิบกว่าครั้งเอง\n\nอย่ากังวล {name} ข้าซ่อมหมดแล้ว มันไม่ระเบิดใส่เจ้าหรอก ถ้าระเบิดก็รวดเร็วไร้ความเจ็บปวด" },
    },
    [2843] = { -- Gnomer-gooooone!
        title = { "16:282252037:444694644", "โนมเมอร์... ไปแล้ว!" },
        objective = { "52:109431788:375940607", "รอ Scooty ปรับเทียบ Goblin Transponder" },
        description = { "427:98335567:179844413", "ตราบใดที่มีเครื่องรับส่งติดตัว เพียงเหยียบแท่นก็จะถูกส่งไป Gnomeregan\n\nอาจมีผลข้างเคียงแปลก ๆ บ้าง แต่ไม่น่าถาวรอีก... แล้วล่ะ\n\nเกือบลืมส่วนสำคัญที่สุด การกลับมา เมื่อพร้อมกลับให้เหยียบแท่น Transpolyporter ใน Gnomeregan!\n\nทีนี้ปรับเครื่องให้ตรงขนาดและน้ำหนักเจ้า" },
        progress = { "11:1651777610:1432005690", "พร้อมแล้ว!" },
        completion = { "50:889675583:1725667150", "เสร็จแล้ว! พร้อมเมื่อไรก็เหยียบแท่นได้เลย" },
        objectiveLabels = {
            event = { ["Goblin Transponder"] = "เครื่องส่งสัญญาณก็อบลิน" },
        },
    },
    [2904] = { -- A Fine Mess
        title = { "11:1613032542:1200757495", "เรื่องยุ่งชั้นดี" },
        objective = { "81:2134302167:852457938", "คุ้มกัน Kernobee ไปทางออก Clockwerk Run แล้วรายงาน Scooty ที่ Booty Bay" },
        description = { "223:1991081708:251611237 N 226:1544555928:574214735", "<Kernobee คราง> อะ... เกิดอะไรขึ้น?\n\nสุดท้ายที่จำได้ ข้าถูกคนแคระ Dark Iron จับ ทุบตีเกือบตาย แล้วโยนมาขังกับโทรกก์โสโครก\n\nพาข้าออกไป {name}!\n\nแผนคือพาข้าไปทางออก หากรอด เจ้าก็ไป Booty Bay แจ้ง Scooty ว่าข้าไป Ratchet เตือน Tinkerwiz เรื่อง Dark Iron มีส่วนสร้างเครื่องกลมหาพลังนั่น\n\nไปกันเถอะ!" },
        progress = { "23:435268750:1744349809", "หือ? Kernobee ยังอยู่หรือ??" },
        completion = { "80:815542511:47266773 N 144:590333234:934026120", "ข้าคงควรตอบแทนที่เจ้าช่วยพา Kernobee กลับมาอย่างปลอดภัย {name} หากกลับ Gnomeregan สิ่งเหล่านี้อาจช่วยให้ได้เปรียบในการปราบ Mekgineer Thermaplugg เจ้าคนทรยศไร้ค่า" },
        objectiveLabels = {
            event = { ["Kernobee Rescue"] = "ช่วย Kernobee" },
        },
    },
    [2922] = { -- Save Techbot's Brain!
        title = { "21:51361937:2047651257", "ช่วยสมอง Techbot!" },
        objective = { "65:1073162937:2094203885", "นำ Techbot's Memory Core ไปให้ Tinkmaster Overspark ที่ Ironforge" },
        description = { "500:672934703:1757834649", "เมื่อ Gnomeregan อันเป็นที่รักล่มสลาย ประกายไฟผิดปกติคงช็อต Techbot สิ่งประดิษฐ์น่าสงสารของข้า มันเคยช่วยข้ากับเพื่อนด้วยอุปกรณ์นับไม่ถ้วนและคลังข้อมูลไร้ขอบเขต แต่สมองโพสิตรอนกลับขั้ว ตอนนี้เป็นเนกาตรอน... พฤติกรรม Techbot จึงกลับด้าน มันวิ่งบ้าคลั่งทั่ว Gnomeregan!\n\nแต่บางทีซ่อมได้ หากนำแกนความจำมาให้ ข้าอาจพบสาเหตุการกลับขั้วและซ่อม Techbot ผู้น่าสงสาร" },
        progress = { "56:1203649723:114328787", "พบ Techbot หรือยัง? ได้แกนความจำมาหรือไม่??" },
        completion = { "34:125514905:786985143 N 158:986112977:1869484812", "โอ้ เยี่ยมมาก! ขอบใจ {name}! ข้าจะลงมือทันที!!\n\nTechbot ผู้น่าสงสาร... อย่าเสียใจ เราจะซ่อมเจ้า\n\nทีนี้ข้าเอาปลั๊กประแจหมุน Hydro-jack ไปวางไหนนะ..." },
        required = { [9277] = { "21:1651063948:1867243712", "แกนความจำของ Techbot" } },
        steps = { { "21:1651063948:1867243712", "แกนความจำของ Techbot" } },
    },
    [2923] = { -- Tinkmaster Overspark
        title = { "20:1533175981:985527240", "Tinkmaster Overspark" },
        objective = { "45:1786353570:887824282", "คุยกับ Tinkmaster Overspark ที่ Ironforge" },
        description = { "329:1183955074:1293982326", "Tinkmaster Overspark ทุกข์ใจมากกับชะตา Techbot สิ่งประดิษฐ์จักรกลของเขา ข้าจำได้ว่ามันเป็นเครื่องมือใจดีช่วยเหลือโนม แต่ Overspark บอกว่ามันขัดข้อง\n\nน่าเศร้ามาก แต่หากมีโชคอาจซ่อมได้!\n\nคุยกับ Tinkmaster Overspark ที่ Tinker Town ใน Ironforge เขาคงยินดีให้ช่วย" },
        completion = { "63:1854226010:387189278", "จริง Techbot หลุดการควบคุมแล้ว! ได้โปรด ช่วยข้าได้ไหม?" },
    },
    [2924] = { -- Essential Artificials
        title = { "21:513996818:816230475", "ชิ้นส่วนประดิษฐ์จำเป็น" },
        objective = { "69:1538190352:1265449188", "นำ Essential Artificial 12 ชิ้นไปให้ Klockmort Spannerspan ที่ Ironforge" },
        description = { "471:1529340389:1155131395 N 19:1505029739:501626427", "ชิ้นส่วนจักรกลแทบสารพัดประโยชน์อย่าง Essential Artificial มีประโยชน์มากต่อช่างประดิษฐ์กับช่างโลหะ Gnomeregan แต่เมื่อหนีเมืองอย่างโกลาหล ไม่มีใครจำได้ว่าต้องเอามาด้วย! ข้าต้องใช้จำนวนมากในงานที่กำลังจะเริ่ม\n\nโปรดเข้า Gnomeregan หามาให้ พบได้ในส่วนลึกของเมือง เก็บในภาชนะชื่อ Artificial Extrapolator\n\nขอบใจ {name} โปรดรีบด้วย!" },
        progress = { "38:1637133869:2055744765", "มี Essential Artificial หรือยัง?" },
        completion = { "76:865512775:1458807639 N 69:639497771:1469994406", "ได้มาแล้ว! ทีนี้เริ่มการทดลองใหม่ได้!\n\nขอบใจเท่าไรก็ไม่พอ {name} ความกล้าหาญเจ้าทำให้งานวิจัยโนมก้าวกระโดด!" },
        required = { [9278] = { "20:737325127:1006204059", "ชิ้นส่วนกลไกอเนกประสงค์" } },
        steps = { { "20:737325127:1006204059", "ชิ้นส่วนกลไกอเนกประสงค์" } },
    },
    [2925] = { -- Klockmort's Essentials
        title = { "22:910501642:875480110", "ของจำเป็นของ Klockmort" },
        objective = { "46:1663478768:152100143", "คุยกับ Klockmort Spannerspan ที่ Ironforge" },
        description = { "414:49597802:1611527176", "Klockmort Spannerspan เพื่อนโนมส่งข่าวจาก Ironforge ว่าต้องการคนช่วยภารกิจสำคัญแต่อันตรายใน Gnomeregan เมืองโนมที่เคยยิ่งใหญ่ บัดนี้ปนเปื้อนและเต็มด้วยโนมบ้ากับสิ่งประดิษฐ์\n\nข้าต้องอยู่ที่นี่ แต่ปวดใจที่ช่วยเพื่อนไม่ได้ หากไปแทน ข้าจะติดหนี้บุญคุณ\n\nพบ Klockmort ได้ที่ Tinkertown ใน Ironforge" },
        completion = { "73:862004439:1835743031 C 10:1201515725:1735122055", "ใช่! ข้าต้องการคนช่วยภารกิจ Gnomeregan และเจ้าก็เป็น{class}ที่เหมาะพอดี!" },
    },
    [2926] = { -- Gnogaine
        title = { "8:1198228428:109646244", "Gnogaine" },
        objective = { "179:1528762355:457858915", "ใช้ Empty Leaden Collection Phial กับ Irradiated Invader หรือ Irradiated Pillager เก็บสารกัมมันตรังสี เมื่อเต็มให้นำกลับไปให้ Ozzie Togglevolt ที่ Kharanos" },
        description = { "161:1382095764:1506086803 N 328:706162572:684766028", "ตั้งแต่เกิดอุบัติเหตุ Gnoarn ก็คิดและพูดแต่เรื่องกำจัดโทรกก์จาก Gnomeregan กับหายารักษาโรคที่ระบาดที่นั่น {name}\n\nโชคดีข้ากับ Razzle ใกล้ได้ยารักษาแล้ว... หรือไม่ก็สูตรเหล้ารัมแรงจัด ต้องทดสอบจึงจะรู้! แน่นอนว่าทดสอบทฤษฎีต้องใช้ของบางอย่าง นั่นคือสารกัมมันตรังสีจากโทรกก์ปนเปื้อนใน Gnomeregan เติมขวดด้วยสารเรืองแสงเขียวแล้วนำกลับมา!" },
        progress = { "102:1178881596:408790829", "ไม่เห็นหรือว่าเราพยายามรักษาโนมทั้งเผ่าพันธุ์??! ต้องใช้สารเรืองแสงเขียวเพิ่ม!" },
        completion = { "176:1453776805:2081790348", "ยอดเยี่ยม! ถึงเวลาทดสอบสูตรใหม่ หากได้ผล ไม่เพียงโนมโรคเรื้อนที่จับไว้จะหาย ข้าควรมีผมเต็มหัวด้วย! ถอยไป!" },
        required = { [9284] = { "28:874222970:33483072", "ขวดเก็บตัวอย่างบุด้วยตะกั่วที่เติมเต็มแล้ว" } },
        steps = { { "28:874222970:33483072", "ขวดเก็บตัวอย่างบุด้วยตะกั่วที่เติมเต็มแล้ว" } },
    },
    [2927] = { -- The Day After
        title = { "13:907348048:1622734769", "วันถัดมา" },
        objective = { "40:350528329:1283237625", "คุยกับ Ozzie Togglevolt ที่ Kharanos" },
        description = { { "299:1462186899:250305102 N 144:365105656:832072773", "301:400821005:1637423883 N 144:365105656:832072773" }, "ไม่ได้คิดว่าข้าหัวโล้นมาตลอดใช่ไหม? ไม่ใช่เลย! รังสีรั่วใน Gnomeregan ทำผมข้าร่วงอย่างน่าเศร้า ก่อนวันนั้นข้ามีทรงโนมโฟรหนึ่งเดียวใน Azeroth\n\n<Gnoarn ชูกำปั้น>\n\nสาปแช่งโทรกก์โสโครกบัดซบ สาปมันให้หมด!!\n\nบางทีไม่สายเกินไป {name} เรายังช่วยมันได้ หมายถึงเมืองน่ะ! คุย Ozzie Togglevolt ที่ Kharanos เขากับคู่หู Razzle กำลังหาทางแก้" },
        completion = { "440:1641299162:1612486911 N 63:1163215323:61417302", "ข้าคิดว่าการเสียเส้นผมชั้นยอดนั้นจะทำเขาจบสิ้น แต่เขารอด!\n\nข้ายืนข้าง ๆ ตอนโดนลำแสงรังสี ผมหยิกสีน้ำตาลงามร่วงลงพื้นเป็นกระจุก! เป็นกอง! ยิ่งน่าตกใจเมื่อ Gnoarn สติแตก ใช่ ข้าว่าสติแตกเลย! เขาจับหัวโล้นอย่างไม่เชื่อ สายตาร้องหาการแก้แค้น {name}! แล้วก็หันโทสะใส่โทรกก์!\n\n<Ozzie สะดุ้งหวาด>" },
    },
    [2928] = { -- Gyrodrillmatic Excavationators
        title = { "30:1538460565:1468366837", "เครื่องขุด Gyrodrillmatic" },
        objective = { "61:1628076474:2134226571", "นำ Robo-mechanical Guts ยี่สิบสี่ชิ้นไปให้ Shoni ที่ Stormwind" },
        description = { "15:19067214:607554055 N 136:2133828651:579897244 N 291:1411029617:1763057764", "แย่แล้ว {name} เราจะมีชิ้นส่วนไม่พอให้กองเครื่องขุด Gyrodrillmatic ไปถึง Dun Morogh\n\nเราต้องการอะไหล่ {name} จะมีที่ไหนเหมาะกว่าหาอะไหล่ยานเราจาก Gnomeregan? ได้ยินว่าหุ่นกับเครื่องกลเดินไปมาราววัวในทุ่ง\n\nไป Gnomeregan แล้วรื้อหุ่นยนต์พวกนั้น นำเครื่องในหุ่นกลับมา สองโหลน่าจะพอ" },
        progress = { "48:617987551:1222635133", "ถ้าเป็นการแข่ง เจ้าคงแพ้ไปแล้ว" },
        completion = { "21:1129349402:1903439022 N 58:161206071:550650768", "พอใช้เลย {name} ซ่อมเครื่องขุด Gyrodrillmatic หนึ่งคันแล้ว เหลืออีก 398 คัน" },
        required = { [9309] = { "20:825183763:855533618", "เครื่องในกลไกของหุ่นยนต์" } },
        steps = { { "20:825183763:855533618", "เครื่องในกลไกของหุ่นยนต์" } },
    },
    [2929] = { -- The Grand Betrayal
        title = { "18:742110400:725669647", "การทรยศครั้งใหญ่" },
        objective = { "114:1004695676:347338094", "เข้า Gnomeregan สังหาร Mekgineer Thermaplugg แล้วกลับไปหา High Tinker Mekkatorque เมื่องานสำเร็จ" },
        description = { "23:1576752301:1267795291 R 270:657707193:1100166366 N 169:1634656861:1381403656", "ข้าเคยไว้ใจ Thermaplugg {race} ไม่เคยคิดว่าเขาจะทรยศข้ากับโนมทั้งเผ่าพันธุ์ เพื่ออะไร? อำนาจ? ความมั่งคั่ง? สิ่งที่เขาคงได้เมื่อถึงเวลา ตอนนี้เราถูกขับจากบ้านและคนบ้าคุมอยู่ ราชาแห่งความว่างเปล่า...\n\nเราจะยึด Gnomeregan คืน {name} จะไม่หยุดจนเมืองกลับอยู่ใต้เรา หากอยากร่วมสู้ ข้าของานง่าย ๆ สังหารคนทรยศ ทำลาย Mekgineer Thermaplugg" },
        progress = { "58:3679237:844179385", "งานสำเร็จหรือยัง? เขาขอผ่อนโทษไหม? ขอความเมตตาหรือเปล่า??" },
        completion = { "108:1121433630:781172385 R 98:1561676367:946088326", "ข้าชอบคิดว่าสิ่งสุดท้ายที่ทะลุผ่านหัวเขาตอนล้มลงคือเท้าเจ้า {race} เมื่อ Thermaplugg ตาย แผนยึด Gnomeregan คืนก็ใกล้จริงอีกก้าว" },
        objectiveLabels = {
            monster = { ["Mekgineer Thermaplugg slain"] = "ปราบ วิศวกรกล Thermaplugg" },
        },
    },
    [2930] = { -- Data Rescue
        title = { "11:602643881:826638320", "กู้ข้อมูล" },
        objective = { "70:837250367:1743155438", "นำ Prismatic Punch Card ไปให้ Master Mechanic Castpipe ที่ Ironforge" },
        description = { "499:257061447:2070730858", "ตอนหนี Gnomeregan เราทิ้งข้อมูลมากมาย ข้อมูลสำคัญต่อชีวิต!\n\nข้าต้องการข้อมูลบน Prismatic Punch Card จากเครื่องความปลอดภัยสูง Matrix Punchograph 3005-D ลึกใน Gnomeregan ต้องเข้าถึงเครื่อง แต่ต้องมีสิทธิ์ก่อน ซึ่งต้องไปเครื่องความปลอดภัยต่ำกว่า รุ่น -A, -B และ -C และจะทำเช่นนั้นก็ต้องมีบัตรเจาะรู เริ่มจากสีขาว... แต่เราทิ้งบัตรไว้ในเมืองหมด\n\nหายนะชัด ๆ! เจ้าช่วยได้ไหม?" },
        progress = { "38:1110157917:673844439", "มี Prismatic Punch Card หรือยัง??" },
        completion = { "224:517995030:255930957 N 1:46:46", "ทำได้แล้ว! พบ Prismatic Punch Card และกู้ข้อมูลที่หาย! ข้อมูลสำคัญยิ่ง สำคัญมหาศาล ขาดไม่ได้แม้แต่นาทีเดียว!\n\nการรับใช้เหล่าโนมของเจ้าจะถูกจดจำไปนาน {name}" },
        required = { [9316] = { "20:125851839:1708785383", "บัตรเจาะรูสีรุ้ง" } },
        steps = { { "20:125851839:1708785383", "บัตรเจาะรูสีรุ้ง" } },
    },
    [2931] = { -- Castpipe's Task
        title = { "15:560290957:805119648", "งานของ Castpipe" },
        objective = { "49:2026006288:1753261835", "คุยกับ Master Mechanic Castpipe ที่ Ironforge" },
        description = { "462:817631386:347681803", "Master Mechanic Castpipe ที่ Ironforge ต้องการนักผจญภัย! เขากำลังจัดกลุ่มกลับเข้า Gnomeregan เพื่อกู้ข้อมูลที่ลับและสำคัญสูงสุด\n\nแม้ Castpipe ไม่ใช่สมาชิก Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences อย่างข้า แต่เขายังเป็นโนมฉลาด หากคิดว่าสำคัญ ตามคำนวณข้ามีโอกาสแปดสิบสี่เปอร์เซ็นต์ที่สำคัญจริง!\n\nโอกาสดีนะ!" },
        completion = { "97:932022678:982342538", "ข้ากำลังจัดภารกิจกู้ข้อมูลใน Gnomeregan หากมาด้วยเรื่องนี้ก็ฟังให้ดี!" },
    },
    [2945] = { -- Grime-Encrusted Ring
        title = { "20:1784214220:1673697204", "แหวนคราบกรัง" },
        objective = { "67:458607628:1947176488", "หาวิธีขจัดคราบจาก Grime-Encrusted Ring" },
        description = { "471:586158956:1620957527", "เจ้าพบสิ่งคล้ายแหวนจากศพคนแคระ Dark Iron แต่บอกชนิดได้ยาก ดินกับคราบแข็งพอกจนสวมไม่ได้ เจ้าเหมือนเห็นประกายโลหะมีค่า และบางทีแสงอัญมณีใต้คราบ\n\nหากอยากใช้แหวน ต้องหาอะไรขจัดคราบแข็งออกก่อน" },
        progress = { "428:1985051193:992067913", "สิ่งประดิษฐ์โนมตรงหน้ามีป้ายว่า “Sparklematic 5200” อ่านคำแนะนำใต้ป้ายแล้วใจความคือเครื่องใช้ขัดคราบสกปรกบนสิ่งของ มีช่องหยอดเหรียญเงินสามเหรียญเพื่อเริ่มทำงานหลังใส่ของ\n\nแหวนคราบกรังที่เจ้าพบก่อนหน้านี้ดูเหมาะจะลองกับเครื่องพอดี!" },
        completion = { "474:1719812976:133389714", "เจ้าใส่แหวนใน Sparklematic 5200 แล้วหยอดเหรียญเงินหนึ่งเหรียญ\n\nเสียงบดเสียดหูดังจากเครื่องที่เริ่มกระตุกอย่างรุนแรง ได้แต่เดาว่าแหวนข้างในกำลังเจออะไร...\n\nเครื่องหยุดทันใดพร้อมเสียง “ติ๊ง!” ช่องรับของเปิดเผยกล่องเล็กห่อเรียบร้อยผูกโบแดง ดูเหมือน Sparklematic 5200 ห่อของขวัญให้ด้วย!\n\nหมายเหตุผู้แปล: คำแนะนำต้นฉบับระบุสามเหรียญเงิน แต่บทจบนี้ระบุหนึ่งเหรียญเงิน ให้ตรวจค่าใช้จ่ายที่เกมแสดง" },
        required = { [9326] = { "20:1784214220:1673697204", "แหวนที่คราบสกปรกจับหนา" } },
        steps = { { "20:1784214220:1673697204", "แหวนที่คราบสกปรกจับหนา" } },
    },
    [2947] = { -- Return of the Ring
        title = { "18:506879502:745267754", "คืนแหวน" },
        objective = { "126:1047298765:292926379", "เจ้าจะเก็บแหวนไว้ หรือหาผู้ทำรอยตราและอักษรสลักด้านในวงแหวนก็ได้" },
        description = { "481:2097504656:171272686", "เปิดกล่องจาก Sparklematic 5200 แล้วพบอย่างที่คาด แหวนเงางาม! เมื่อสวม พลังเวทไหลผ่านกาย\n\nด้านในมีตรา Ironforge เล็กแต่เห็นชัด ข้างกันสลักอักษรย่อสามตัว “TdK” อาจเป็นเจ้าของเดิมหรือช่างผู้ทำ เก็บไว้... หรือคืนคนนั้น ต้องตัดสินใจ..." },
        progress = { "341:1625873231:1524066695", "เฮ้ ใจเย็น สหาย ข้าเป็นนักธุรกิจสำคัญ! ข้ามั่นใจว่าคนส่งแค่ส่งค่าเช่าช้า... เดี๋ยว... เจ้าไม่ใช่เจ้าของห้องข้า\n\nแน่ล่ะ ไม่ใช่ ข้านี่โง่จริง! เจ้ามาหาช่างอัญมณีดีที่สุดใน Ironforge ผู้ไม่ทำของต้องคำสาป! ใช่!\n\nเอ่อ... ต้องการอะไรหรือ?" },
        completion = { "491:1428514938:1455933653", "แหวนหรือ? มาดู... ใช่ ข้าทำจริง\n\nก่อน Gnomeregan วอดวาย ข้ามีร้านเล็กที่นั่น อาจเป็นของที่ทิ้งตอนหนี แบบเรียบง่าย ข้าทำไว้หลายวง หรืออาจเป็นของคนที่หนีไม่ทัน\n\nคนแคระ Dark Iron มีแหวนนี้หรือ? เพิ่มปมสมคบคิดอีกชั้นจากเก้าชั้นที่มีอยู่ บางทีเจ้าหน้าที่คงอยากรู้ เรื่องนี้บอกคนอย่างข้าก็เปล่า\n\nทีนี้ กลับมาเรื่องแหวน..." },
        required = { [9362] = { "19:876421917:394488771", "แหวนทองคำแวววาว" } },
        steps = { { "19:876421917:394488771", "แหวนทองคำแวววาว" } },
    },
    [2949] = { -- Return of the Ring
        title = { "18:506879502:745267754", "คืนแหวน" },
        objective = { "126:1047298765:292926379", "เจ้าจะเก็บแหวนไว้ หรือหาผู้ทำรอยตราและอักษรสลักด้านในวงแหวนก็ได้" },
        description = { "486:1373733540:1456074324", "เปิดกล่องจาก Sparklematic 5200 พบแหวนเงางาม! เมื่อสวม พลังเวทไหลผ่านกาย\n\nด้านในมีตรา Orgrimmar เล็กแต่เห็นชัด ข้างกันสลักอักษร แต่แม้ล้างแล้วก็เห็นชัดแค่สามตัวแรก “NOG...”\n\nอาจเป็นอักษรย่อเจ้าของเดิมหรือช่างผู้ทำ เก็บไว้... หรือตามหา “NOG” ต้องตัดสินใจ..." },
        progress = { "209:868471433:1106139907", "น่าจะหาวิธีชนะเจ้าโนมสกปรกตัวจ้อยได้เองแล้ว ข้าพนันได้ว่ามันขโมยเครื่องกลเราตั้งแต่แรก! เฮอะ พวกมันทั้งมันเยิ้มทั้งโสโครก... เอ่อ ว่าไง? ต้องการอะไร?" },
        completion = { "492:1848833655:1158752639", "แหวนจาก Gnomeregan? มาดู... ไม่ใช่ของข้า แต่น่าสนใจ\n\nเรื่อง Gnomeregan น่ะ... สมน้ำหน้าพวกหัวทึบ หลายปียังเป็นตัวตลก แล้วแทบข้ามคืนกลับสร้างเครื่องกลดีกว่าเรา?\n\nคนแคระ Dark Iron มีแหวนหรือ? ยิ่งน่าสนใจ! บางทีโนมขโมยแบบโกเลมบ้าคลั่งของมันมาดัดแปลง พวก Dark Iron คงอยากแก้แค้นใหญ่ ควรสืบดูแน่\n\nว่าแต่ เรื่องแหวน..." },
        required = { [9362] = { "19:876421917:394488771", "แหวนทองคำแวววาว" } },
        steps = { { "19:876421917:394488771", "แหวนทองคำแวววาว" } },
    },
    [2951] = { -- The Sparklematic 5200!
        title = { "22:1171581763:161272248", "Sparklematic 5200!" },
        objective = { "118:1735825012:1299499285", "ใส่ Grime-Encrusted Item ใน Sparklematic 5200 และต้องมีเหรียญเงินสามเหรียญเพื่อเริ่มเครื่อง" },
        description = { "471:1736519942:1894643887", "เครื่องนี้เด่นท่ามกลางโนมที่ต้านความบ้าคลั่งนอกห้อง ป้ายเล็กเขียน “Sparklematic 5200” ตามด้วยข้อความ\n\n“คราบสกปรกทำของแวววาวหม่นหรือ? Sparklematic 5200 คืนความเงาวับสุดวิเศษ! ใส่ของที่ต้องการล้าง หยอดเหรียญเงินสามเหรียญ รอเครื่องทำงานสักครู่ แล้วดูสิ! ของมีค่าจะออกมาสะอาดเงางาม!”" },
        progress = { "201:1361810666:250330570", "ดูเหมือนเครื่องต้องการของคราบกรังมาล้าง กับเหรียญเงินสามเหรียญเพื่อเริ่มทำงาน หากมีทั้งสองอย่าง Sparklematic 5200 ก็คงใช้ได้..." },
        completion = { "325:1609186136:411531675", "เจ้าใส่ของคราบกรังกับเหรียญเงินสามเหรียญใน Sparklematic 5200 เครื่องติดอย่างบ้าคลั่งเพื่อขจัดคราบจากของปริศนา เสียงปั่นรุนแรงดังจากหัวใจเครื่อง โครงโลหะครางเอี๊ยดขณะโยกไปมา...", variants = { { "333:2049643956:273434384", "เจ้าใส่ของคราบกรังกับเหรียญเงินสามเหรียญใน Sparklematic 5200 เครื่องเริ่มทำงานอย่างรุนแรงราวกับจะคลุ้มคลั่งเพื่อขจัดคราบจากของปริศนา เสียงปั่นรุนแรงดังจากหัวใจเครื่อง โครงโลหะครางเอี๊ยดขณะโยกไปมา..." } } },
        required = { [9308] = { "22:1354073026:26797563", "วัตถุที่คราบสกปรกจับหนา" } },
        steps = { { "22:1354073026:26797563", "วัตถุที่คราบสกปรกจับหนา" } },
    },
    [2952] = { -- The Sparklematic 5200!
        title = { "22:1171581763:161272248", "Sparklematic 5200!" },
        completion = { "472:635526312:2051978875", "Sparklematic 5200 หยุดกึกเร็วพอ ๆ กับที่เริ่ม เสียง “ติ๊ง” ดัง ปากเครื่องหมุนเปิดขึ้น ข้างในมีกล่องเล็กผูกโบ ดูเหมือนมันห่อของหลังล้างคราบ แม้ล้างไม่สำเร็จ อย่างน้อยของก็อยู่ในกล่องสวยแล้ว\n\nมีวิธีเดียวที่จะรู้ว่ามันล้างสะอาดหรือไม่..." },
    },
    [2953] = { -- More Sparklematic Action
        title = { "24:662482825:486097097", "ใช้ Sparklematic ต่ออีก" },
        progress = { "107:51079210:384252989", "Sparklematic 5200 ว่างอยู่ รอของคราบกรังมาล้างและเหรียญเงินสามเหรียญเพื่อเริ่ม!" },
        completion = { "343:1892319016:1975633426", "Sparklematic 5200 เริ่มทำงาน โยกไปมา ข้างใน คราบบนของที่ใส่กำลังถูกน้ำยาทำความสะอาดโนมบดขยี้อย่างไร้ทางสู้\n\nเครื่องหยุดพร้อมเสียง “ติ๊ง!” คุ้นหู ช่องรับของหมุนเปิด เผยกล่องห่ออย่างเรียบร้อย" },
        description = { "107:51079210:384252989", "Sparklematic 5200 ว่างอยู่ รอของคราบกรังมาล้างและเหรียญเงินสามเหรียญเพื่อเริ่ม!" },
        required = { [9308] = { "22:1354073026:26797563", "วัตถุที่คราบสกปรกจับหนา" } },
        objectiveLabels = {
            item = { ["Grime-Encrusted Object"] = "วัตถุที่คราบสกปรกจับหนา" },
        },
    },
    [2962] = { -- The Only Cure is More Green Glow
        title = { "32:1541795384:104353582", "ทางรักษาเดียวคือแสงเขียวเพิ่ม" },
        objective = { "224:148171254:2073035071", "ไป Gnomeregan แล้วนำ High Potency Radioactive Fallout กลับมา ระวัง สารไม่เสถียรและจะสลายเร็ว\n\nOzzie ต้องการ Heavy Leaden Collection Phial ของเจ้าคืนด้วยเมื่องานเสร็จ" },
        description = { "500:1915497354:1371769143", "ตัวอย่างเจ้าไม่เพียงน้อยเกินไป แต่ยังไม่บริสุทธิ์\n\nเราต้องใช้สารเรืองแสงเขียวเพิ่ม โทรกก์รับรังสีไม่พอสำหรับงานเรา ต้องเข้า Gnomeregan แล้วนำสารกัมมันตรังสีจากต้นทางมา ข้าหมายถึงพวกสไลม์ พวกซุ่มซ่อน และอสูรที่ปนเปื้อนรังสี ระวังด้วย กักเก็บสารชนิดนี้ยาก อาจต้องลองใช้ขวดหลายครั้งจนได้ตัวอย่างเหมาะสม" },
        progress = { "44:736560932:1924801694", "อืม เจ้าไม่เรืองแสง เป็นสัญญาณดี" },
        completion = { "112:654996303:1367408749", "<Ozzie ตรวจตัวเจ้า> น่าประทับใจ แขนขายังครบ ทีนี้มาดูกันว่าสารนี้ทำอะไรได้!" },
        required = { [9365] = { "32:1236540552:1657224576", "ฝุ่นกัมมันตรังสีความเข้มสูง" }, [9364] = { "29:219234757:1894757339", "ขวดเก็บตัวอย่างบุด้วยตะกั่วแบบหนัก" } },
        steps = { { "32:1236540552:1657224576", "ฝุ่นกัมมันตรังสีความเข้มสูง" }, { "29:219234757:1894757339", "ขวดเก็บตัวอย่างบุด้วยตะกั่วแบบหนัก" } },
    },
    [3375] = { -- Replacement Phial
        title = { "17:1604732205:245571617", "ขวดทดแทน" },
        objective = { "131:1713822822:135638338", "นำ Mana Potion, Coal และ Sweet Nectar ไปให้ Talvash del Kissel ที่ Ironforge เพื่อรับ Talvash's Phial of Scrying ทดแทน" },
        description = { "141:977518333:565780360 R 305:345945151:2053259695", "เอ่อ... ต้องการขวดทำนายอีกใบ? ล้อเล่นใช่ไหม เอาใบแรกไปทำอะไร?! เรายังมีงานอีกมาก {race} ขวดไม่ได้งอกบนต้นไม้! ที่จริงข้าอยากให้งอก จะได้ไปเด็ด เพราะข้าไม่มีอีกใบ!!\n\nหากจะทำให้ ต้องใช้ยามานา ถ่านก้อนหนึ่ง และน้ำหวาน อย่าถามทำไม เอาที่ขอมาแล้วข้าจะทำใหม่" },
        progress = { "128:1725567780:936249893", "ทำขวดใหม่ต้องใช้ยามานา ถ่านก้อนหนึ่ง และน้ำหวาน\n\nกับความอดทนอีกมากด้วยสินะ" },
        completion = { "438:1993126382:1588427806", "นักผจญภัยผู้ยิ่งใหญ่ส่งของแล้ว ข้าดีใจจัง ว่าแต่ข้าโกหก ข้ามีอีกขวด เอ้า รับไป\n\nแล้วคาดหวังอะไร?! “โอ้ เอาขวดใหม่ไป ข้าคือเจ้าทึ่มที่ไม่มีอะไรดีกว่าแจกอุปกรณ์สื่อสารเวทให้นักผจญภัย!” แต่มั่นใจได้ ของที่ให้จะพอทำอีกขวดเมื่อเจ้าทำใบนี้หายด้วย\n\nช่วยพิสูจน์ว่าข้าคิดผิดและอย่าทำใบใหม่หาย ตกลงไหม?" },
        required = { [1708] = { "12:226827637:528136144", "น้ำหวาน" }, [3827] = { "11:1068661900:717140923", "ยาฟื้นมานา" }, [3857] = { "4:1144654207:152539783", "ถ่านหิน" } },
        objectiveLabels = {
            item = { ["Sweet Nectar"] = "น้ำหวาน", ["Mana Potion"] = "ยาฟื้นมานา", ["Coal"] = "ถ่านหิน" },
        },
    },
    [4601] = { -- The Sparklematic 5200!
        title = { "22:1171581763:161272248", "Sparklematic 5200!" },
        objective = { "118:1735825012:1299499285", "ใส่ Grime-Encrusted Item ใน Sparklematic 5200 และต้องมีเหรียญเงินสามเหรียญเพื่อเริ่มเครื่อง" },
        description = { "471:1736519942:1894643887", "เครื่องนี้เด่นท่ามกลางโนมที่ต้านความบ้าคลั่งนอกห้อง ป้ายเล็กเขียน “Sparklematic 5200” ตามด้วยข้อความ\n\n“คราบสกปรกทำของแวววาวหม่นหรือ? Sparklematic 5200 คืนความเงาวับสุดวิเศษ! ใส่ของที่ต้องการล้าง หยอดเหรียญเงินสามเหรียญ รอเครื่องทำงานสักครู่ แล้วดูสิ! ของมีค่าจะออกมาสะอาดเงางาม!”" },
        progress = { "201:1361810666:250330570", "ดูเหมือนเครื่องต้องการของคราบกรังมาล้าง กับเหรียญเงินสามเหรียญเพื่อเริ่มทำงาน หากมีทั้งสองอย่าง Sparklematic 5200 ก็คงใช้ได้..." },
        completion = { "325:1609186136:411531675", "เจ้าใส่ของคราบกรังกับเหรียญเงินสามเหรียญใน Sparklematic 5200 เครื่องติดอย่างบ้าคลั่งเพื่อขจัดคราบจากของปริศนา เสียงปั่นรุนแรงดังจากหัวใจเครื่อง โครงโลหะครางเอี๊ยดขณะโยกไปมา..." },
        required = { [9308] = { "22:1354073026:26797563", "วัตถุที่คราบสกปรกจับหนา" } },
        steps = { { "22:1354073026:26797563", "วัตถุที่คราบสกปรกจับหนา" } },
    },
