    [92753] = { -- Destruction in Deadmines
        title = { "24:837966159:320623610", "ทำลายต้นตอใน Deadmines" },
        objective = { "146:201267677:504629937", "หาเตาหลอมที่ซ่อนใน Deadmines วาง Extra-Destructive Explosives ใกล้ ๆ แล้วพบ Alba Fairmoon ที่ทางออก Deadmines" },
        description = { "315:1179744039:1749793865", "ต้นพิษน่าจะเป็นเตาหลอมโลหะขนาดใหญ่สักชนิด หาทางเข้า Deadmines หาเตาหลอม แล้ววางระเบิด\n\nข้าจะรอที่เนินเขาหลัง Moonbrook เมื่อกลับมาเราจะจุดชนวน หวังว่าเมื่อไม่มีเตาหลอม แผ่นดินจะเริ่มฟื้นตัว", variants = { { "314:215182330:350981388", "ต้นพิษน่าจะเป็นเตาหลอมโลหะขนาดใหญ่สักชนิด หาทางเข้า Deadmines หาเตาหลอม แล้ววางระเบิด\n\nข้าจะรอที่เนินเขาหลัง Moonbrook เมื่อกลับมาเราจะจุดชนวน หวังว่าเมื่อไม่มีเตาหลอม แผ่นดินจะเริ่มฟื้นตัว" } } },
        progress = { { "36:1245552185:928767885", "29:857849841:865483348 N 1:46:46", "29:857849841:865483348 C 1:46:46", "29:857849841:865483348 R 1:46:46" }, "ตอนนี้ทุกอย่างขึ้นอยู่กับเจ้า สหาย" },
        completion = { "82:1504671535:1177342049", "เจ้าพบเตาหลอมและวางระเบิดแล้ว... เหลือสิ่งเดียวที่ต้องทำ", variants = { { "82:460887674:1097721694", "เจ้าพบเตาหลอมและวางระเบิดแล้ว... เหลือสิ่งเดียวที่ต้องทำ" } } },
        required = { [254553] = { "28:978584956:746624986", "วัตถุระเบิดพลังทำลายสูงพิเศษ" } },
        steps = { { "17:1984578794:2083755736", "วางวัตถุระเบิด" }, { "28:978584956:746624986", "วัตถุระเบิดพลังทำลายสูงพิเศษ" } },
    },
    [65] = { -- The Defias Brotherhood
        title = { "22:1184404334:2044032401", "ภราดรภาพ Defias" },
        objective = { "58:941504870:2097804190", "Gryan Stoutmantle ต้องการให้เจ้าคุยกับ Wiley ที่ Lakeshire" },
        description = { "417:2041748593:488808762", "พวกเลวที่ขับชาว Westfall ออกจากแผ่นดินเรียกตน Defias Brotherhood ข้าต้องการให้เจ้าแทรกซึมแก๊ง เราต้องรู้ใครเป็นหัวหน้าและซ่อนที่ไหน ที่โรงเตี๊ยม Lakeshire มีโจรชื่อ Wiley ติดหนี้บุญคุณข้า\n\nไป Lakeshire ใน Redridge Mountains ทางตะวันออกของ Elwynn แล้วสืบเท่าที่ทำได้" },
        completion = { "42:673494592:1554649546", "Stoutmantle ส่งมาหรือ? เอาล่ะ ข้าติดหนี้เขา" },
    },
    [132] = { -- The Defias Brotherhood
        title = { "22:1184404334:2044032401", "ภราดรภาพ Defias" },
        objective = { "51:2114298372:804058942", "นำ Wiley's Note ไปให้ Gryan Stoutmantle ที่ Westfall" },
        description = { "260:683385789:134226777", "สิ่งที่จะเล่าอาจทำข้าตาย Defias กำลังทำเรื่องใหญ่ ข่าวล่าสุดคือร่วมมือกับนอลล์ โคโบลด์ แม้แต่ก็อบลิน\n\nนำจดหมายนี้ให้ Stoutmantle มันอธิบายเท่าที่ข้ารู้" },
        progress = { "22:625263164:686448130 N 41:48919302:103068705", "ดีที่กลับมา {name} Wiley ว่าอย่างไรบ้าง?" },
        completion = { "108:1533847039:107002608", "เฮอะ! ตอนมีโอกาส ข้าควรปล่อยคนเลวนั่นเน่าไป แต่ข้อมูลนี้สำคัญมาก ทำได้ดี" },
        required = { [1327] = { "12:539051792:1550411801", "บันทึกของ Wiley" } },
        objectiveLabels = {
            item = { ["Wiley's Note"] = "บันทึกของ Wiley" },
        },
    },
    [135] = { -- The Defias Brotherhood
        title = { "22:1184404334:2044032401", "ภราดรภาพ Defias" },
        objective = { "47:417783542:286695722", "นำ Wiley's Note ไปให้ Mathias Shaw ที่ Stormwind" },
        description = { "357:508926007:1339075853", "ข้าสงสัยว่า Wiley หมายถึงอะไรตอนพูดถึงช่างหิน บางทีหลุดปาก Defias เกี่ยวกับ Stonemasons หรือ? มีเพียงคนเดียวรู้แน่ Mathias Shaw หัวหน้า SI:7 ให้เขาดู Wiley's Note แล้วถามว่ามีอะไรเพิ่มในปริศนานี้ไหม หากหาไม่พบ ลองค่ายทหารใน Old Town" },
        progress = { "60:1347679648:1805257601", "มีธุระอะไรกับข้า? ข้ายุ่งมาก..." },
        completion = { "60:504713058:1760931228", "เรื่องนี้อาจซับซ้อนกว่าที่ Stoutmantle คิด" },
        required = { [1327] = { "12:539051792:1550411801", "บันทึกของ Wiley" } },
        objectiveLabels = {
            item = { ["Wiley's Note"] = "บันทึกของ Wiley" },
        },
    },
    [141] = { -- The Defias Brotherhood
        title = { "22:1184404334:2044032401", "ภราดรภาพ Defias" },
        objective = { "52:369539648:131725150", "นำรายงานของ Shaw ไปให้ Gryan Stoutmantle ที่ Westfall" },
        description = { "405:438566240:407845565", "Stonemasons' Guild เคยมี Edwin VanCleef นำ เขารับผิดชอบสร้าง Stormwind ใหม่หลังออร์คเผาในสงครามครั้งแรก ดูเหมือนเขากับคนไม่พอใจการปฏิบัติของกษัตริย์เมื่อสร้างเสร็จ เรื่องนี้อาจอธิบายได้บางอย่าง\n\nข้าเขียนรายละเอียดให้เจ้านายเจ้าที่ Westfall แล้ว นำไปให้ทันที!" },
        progress = { "41:101210540:1051255041", "Master Shaw ช่วยให้เรื่องกระจ่างบ้างไหม?" },
        completion = { "181:1626314244:145547185", "Edwin VanCleef... ข้ารู้ชื่อนี้ดี คิดว่าคนขยันและมีพรสวรรค์กลับเป็นคนเลวเช่นนี้แล้วไม่สบายใจ ต้องมีหลักฐานเพิ่มก่อนเชื่อ", variants = { { "180:495237400:682767126", "Edwin VanCleef... ข้ารู้จักชื่อนี้ดี พอคิดว่าคนขยันและมีฝีมืออย่างเขากลับกลายเป็นคนชั่วแบบนี้ ข้าก็อดใจหายไม่ได้ ข้าต้องเห็นหลักฐานมากกว่านี้ถึงจะเชื่อ" } } },
        required = { [1353] = { "13:364553261:1265584109", "รายงานของ Shaw" } },
        objectiveLabels = {
            item = { ["Shaw's Report"] = "รายงานของ Shaw" },
        },
    },
    [142] = { -- The Defias Brotherhood
        title = { "22:1184404334:2044032401", "ภราดรภาพ Defias" },
        objective = { "81:1059950222:471406779", "ตามหา Defias Messenger ใน Westfall แล้วนำสารของเขาไปให้ Stoutmantle" },
        description = { "56:1612986183:256736414 N 223:1644485754:1604756510", "เราต้องรู้ที่ซ่อน Defias {name} หน่วยสอดแนมพบ Defias Messenger บนถนนระหว่าง Moonbrook, Gold Coast Quarry และ Jangolode Mine ข้าต้องการให้จับ หากขัดขืนก็ฆ่าแล้วนำของติดตัวมาให้" },
        progress = { "N 72:166180603:1718943074", "{name} ได้ข้อมูลบ้างไหม? พบผู้ส่งสารหรือยัง?" },
        completion = { "400:2070596576:693774981", "นี่คือหลักฐานแน่นหนาว่า VanCleef นำอยู่ ทีนี้เหลือเพียงรู้ที่ซ่อน Defias\n\nระหว่างเจ้าไปเราโชคดี จับโจรที่พยายามขโมยเกวียน Saldean เขาสัญญานำทางแลกชีวิต ข้าต้องการให้เจ้าป้องกันคนทรยศเพื่อเขาเผยที่ซ่อน กลับมาเมื่อรู้ตำแหน่ง" },
        required = { [1381] = { "20:2020786072:242746528", "ข้อความปริศนา" } },
        steps = { { "20:2020786072:242746528", "ข้อความปริศนา" } },
    },
    [155] = { -- The Defias Brotherhood
        title = { "22:1184404334:2044032401", "ภราดรภาพ Defias" },
        objective = { "201:2093580806:157592427", "คุ้มกัน Defias Traitor ไปที่ซ่อนลับ Defias Brotherhood เมื่อเขาแสดงที่ซ่อน VanCleef กับพวกแล้ว ให้กลับไปรายงาน Gryan Stoutmantle" },
        description = { "31:1345738480:431217884 R 356:2069199831:1299007491", "Stoutmantle ส่ง{race}ผอมแห้งอย่างเจ้ามาคุ้มกันข้าหรือ? คงต้องพึ่งเจ้าแล้ว พาเพื่อนมาด้วยก็ดี\n\nรู้ข้อตกลงใช่ไหม? เจ้าดูหลังให้ ข้าจะนำไปที่ซ่อน Defias แต่ต้องอยู่ใกล้ข้า พวกมันต้องการหัวข้าแล้ว หากเห็นข้ากับเจ้ามันจะพยายามฆ่า\n\nบอกเมื่อเจ้ากับเพื่อนที่รวบรวมได้พร้อมไป" },
        progress = { "58:459634728:1112954294", "มีธุระอะไรกับข้า? ข้ายุ่งมาก..." },
        completion = { "16:959884130:63492255 N 66:2082839451:2016746336", "ยอดเยี่ยม {name}! เมื่อรู้ที่ซ่อน VanCleef ก็แทบอยู่ในกำมือเราแล้ว" },
        objectiveLabels = {
            event = { ["Escort The Defias Traitor to discover where VanCleef is hiding"] = "คุ้มกันผู้ทรยศแห่ง Defias เพื่อค้นหาที่ซ่อนของ VanCleef" },
        },
    },
    [720] = { -- A Sign of Hope
        title = { "14:1016816697:1614185711", "ร่องรอยแห่งความหวัง" },
        objective = { "64:1135725474:1939917221", "หา Prospector Ryedol แล้วแจ้งว่า Hammertoe Grez ยังมีชีวิต" },
        description = { "116:1790730783:1400522048", "<มีข้อความเขียนชอล์กลวก ๆ บนแผนที่>\n\n“Ryedol\nพวกมันพาข้าไป Uldaman ส่งคนช่วยด้วย\n-Hammertoe”" },
        completion = { "37:1368418369:1023799015 N 1:33:33", "Hammertoe ยังอยู่หรือ?! น่าทึ่ง {name}!" },
    },
    [2439] = { -- The Platinum Discs
        title = { "18:39549661:953126646", "แผ่นแพลทินัม" },
        objective = { "73:1645380803:2109593786", "นำใบแลกรางวัลของเจ้าไปให้ Dinita Stonemantle ที่ Vault of Ironforge" },
        description = { "268:654755490:1455182108 C 217:210855160:2125892865", "นี่เป็นสิ่งที่ค้นพบอันเหลือเชื่อ หากตำนานที่เก็บในแผ่นดิสก์ถูกต้อง เหล่าไททันโบราณ หรือผู้สร้างตามที่ในแผ่นเรียก คือสายเชื่อมโยงสู่การกำเนิดด้วยเวทมนตร์ของเรา! เราต้องทุ่มเวลาวิจัยเรื่องนี้ให้มากที่สุด\n\nส่วนเจ้า {class}ผู้กล้า นำใบแลกนี้ไปให้ Dinita Stonemantle ที่คลัง มันให้รางวัลที่ข้าคิดว่าเหมาะสมกับการค้นพบยิ่งใหญ่เช่นนี้!\n\nเมื่อพร้อมให้กลับมาหาข้าโดยตรง ยังมีงานให้ทำเพื่อ Explorers' League อีกมาก!" },
        progress = { "35:1464606953:1540215395 N 30:1957802472:1453745660", "ยินดีต้อนรับสู่ Vault of Ironforge {name} วันนี้ให้ข้าช่วยอะไร?" },
        completion = { "335:1353214751:1846211362", "อา ใช่ ใบแลกจาก Explorers' League... และขอบอกว่าเป็นใบที่มีค่ามากด้วย\n\nExplorers' League มอบอำนาจให้ข้าเสนอค่าตอบแทนจากคลังของพวกเขาโดยตรง เจ้าจะได้รับไอเทมนี้ และเลือกระหว่าง superior healing potions ห้าขวดกับ greater mana potions ห้าขวดเป็นรางวัลได้" },
        required = { [8070] = { "14:536832257:796102729", "คูปองรับรางวัล" } },
        steps = { { "14:536832257:796102729", "คูปองรับรางวัล" } },
    },
    [2440] = { -- The Platinum Discs
        title = { "18:39549661:953126646", "แผ่นแพลทินัม" },
        objective = { "60:695171843:191168210", "นำใบแลกรางวัลไปให้ Bena Winterhoof ที่ Thunder Bluff" },
        description = { "109:602115615:478137269 N 385:1234091770:1063632958", "ข้าจะมุ่งพลังไปศึกษาแผ่นดิสก์เหล่านี้ แล้วเมื่อถึงเวลามันจะเผยการทำงานแท้จริงให้ข้ารู้\n\nส่วนเจ้า {name} ข้าจะตอบแทนความขยันที่นำเรื่องนี้มาให้ทราบ นำใบแลกนี้ไปให้ Bena Winterhoof ครูฝึกเล่นแร่แปรธาตุของ Thunder Bluff นางจะมอบไอเทมพิเศษที่ข้าเชื่อว่าเจ้าจะชอบ และให้เลือกยาจากคลังส่วนตัวของข้า\n\nกลับมาหาข้าเร็ว ๆ ข้ารู้สึกว่ายังมีเรื่องให้เราทำอีกมากเกี่ยวกับสิ่งที่ค้นพบนี้" },
        progress = { "11:927657569:725753248 C 63:740821397:970993118", "สวัสดี {class}! มาฝึกเล่นแร่แปรธาตุ หรือมีเรื่องอื่น?" },
        completion = { "5:1151914341:80614338 N 232:990549364:1048185501", "เอาล่ะ {name} เจ้าคงทำให้ Sage Truthseeker พอใจมาก เขาถึงมอบไอเทมนี้ให้ เจ้ายังจะได้ของขวัญจากคลังยา เลือกระหว่าง superior healing potions 5 ขวด กับ greater mana potions 5 ขวดเป็นรางวัลได้" },
        required = { [8070] = { "14:536832257:796102729", "คูปองรับรางวัล" } },
        steps = { { "14:536832257:796102729", "คูปองรับรางวัล" } },
    },
    [92819] = { -- Destruction in Deadmines
        title = { "24:837966159:320623610", "ทำลายต้นตอใน Deadmines" },
        objective = { "18:322295024:1433779066", "ใช้เครื่องจุดชนวน" },
        description = { "56:1761531658:1715050529", "ใกล้เสร็จแล้ว ใช้เครื่องจุดชนวนแล้วจบเรื่องนี้" },
        completion = { { "131:1713471592:1863161658", "26:2042433453:2113842833 N 99:1608717716:610908567", "26:2042433453:2113842833 C 99:1608717716:610908567", "26:2042433453:2113842833 R 99:1608717716:610908567" }, "ข้าไม่รู้จะพูดอะไร สหาย คิดไม่ถึงว่า Stormwind จะให้ความทะเยอทะยานทางทหารสำคัญกว่าการทำมาหากินของประชาชน..." },
        steps = { { "14:1986979491:544177390", "ใช้เครื่องจุดระเบิด" } },
    },
    [9] = { -- The Killing Fields
        title = { "18:487464597:736704166", "ทุ่งสังหาร" },
        objective = { "53:2017511112:1232903198", "Farmer Saldean ต้องการให้เจ้าสังหาร Harvest Watcher 20 ตัว" },
        description = { "426:1052365931:1317243208", "ดูสิว่าที่นี่เป็นอย่างไร! แผ่นดินเคยมีชาวไร่สุจริต แต่โจรบัดซบขับไล่ทุกคนไป เว้นข้า! ทว่าดูเหมือน Harvest Watcher ยึดทุ่งแล้ว\n\nหากพร้อมทำงาน ออกไปกำจัดยี่สิบตัว กลับมารับค่าจ้างเมื่อเสร็จ หากหมดในไร่ข้าแล้วก็ไล่กวาดไร่ข้างเคียงด้วย" },
        progress = { "131:2010271618:1832518576", "อา กลับมาแล้ว! หวังว่าขยันกวาด Harvest Watcher จากทุ่ง กำจัดครบยี่สิบหรือยัง?" },
        completion = { "102:1833719940:610745876", "ทำได้ดี สหาย เจ้าคู่ควรค่าจ้าง ใครจะรู้ บางที Westfall อาจรุ่งเรืองอีกครั้ง" },
        objectiveLabels = {
            monster = { ["Harvest Watcher slain"] = "ปราบ หุ่นเฝ้าไร่" },
        },
    },
    [12] = { -- The People's Militia
        title = { "20:276130866:79271171", "กองกำลังประชาชน" },
        objective = { "115:1970234071:2010880910", "Gryan Stoutmantle ต้องการให้เจ้าสังหาร Defias Trapper 15 คนและ Defias Smuggler 15 คน แล้วกลับไปหาเขาที่ Sentinel Hill" },
        description = { "485:312777633:2091650434", "People's Militia มีเป้าหมายเดียว ปกป้อง Westfall และคืนสันติแก่พื้นที่ น่าเสียดายว่าราคาสันติมักเป็นเลือด\n\nหน่วยสอดแนมรายงานว่า Defias Trapper ก่อความเสียหายใกล้ ๆ พบแถว Jangolode Mine ทางตะวันตกเฉียงเหนือ รวมถึง Molsen Farm กับ Furlbrow's Pumpkin Farm หากอยากร่วมกับเรา จงกำจัด Defias Trapper 15 คนและ Defias Smuggler 15 คน แล้วกลับมา" },
        progress = { "228:1056192475:360052101", "บางทีข้าพูดไม่ชัด ผู้สมัคร หากจะพิสูจน์คุณค่าในการรับใช้ People's Militia และแสงสว่าง ต้องสังหาร Defias Trapper 15 คนและ Defias Smuggler 15 คน แล้วกลับมาหาข้าเมื่องานสำเร็จ" },
        completion = { "11:534428891:784080240 N 83:887913673:2107644168", "ทำได้ดี {name} หน่วยสอดแนมเห็นความกล้าหาญเจ้า ถึงตอนนี้เจ้าพิสูจน์ตนได้ดีมาก" },
        objectiveLabels = {
            monster = { ["Defias Trapper slain"] = "ปราบ นักวางกับดัก Defias", ["Defias Smuggler slain"] = "ปราบ ผู้ลักลอบขนของ Defias" },
        },
    },
    [13] = { -- The People's Militia
        title = { "20:276130866:79271171", "กองกำลังประชาชน" },
        objective = { "113:837772314:266462082", "Gryan Stoutmantle ต้องการให้เจ้าสังหาร Defias Pillager 15 คนและ Defias Looter 15 คน แล้วกลับไปหาเขาที่ Sentinel Hill" },
        description = { "198:335892089:1392888987 N 228:1604674017:765543481", "พบ Defias Pillager ดุร้ายปล้น Gold Coast Quarry, Moonbrook และ Alexston Farmstead People's Militia ไม่ยอมให้ทำเช่นนี้ ไปทันที {name} ให้ Westfall รู้ว่าแสงสว่างยังอยู่\n\nGold Coast Quarry อยู่ใกล้ชายฝั่ง ทางตะวันตกของหอคอย ขั้นฝึกต่อไปข้าต้องการให้กำจัด Defias Pillager ชั่วช้า 15 คนและ Defias Looter 15 คน" },
        progress = { "26:571665932:975618926 N 243:1764855237:860640346", "ไม่มีเวลาคุย {name} Defias Pillager พรากสันติและความรุ่งเรืองที่ชาว Westfall สมควรได้ ต้องให้ตายอย่างน้อย Defias Pillager 15 คนกับ Defias Looter 15 คน นั่นจะส่งสารชัดว่าความเสื่อมทรามไม่ได้รับการต้อนรับที่นี่" },
        completion = { "82:1651119338:1597656713", "ความกล้าหาญที่ผ่านมาได้ยืนยันคุณค่าของเจ้าต่อ People's Militia แล้ว" },
        objectiveLabels = {
            monster = { ["Defias Pillager slain"] = "ปราบ ผู้ปล้นสะดม Defias", ["Defias Looter slain"] = "ปราบ โจรฉกชิง Defias" },
        },
    },
    [14] = { -- The People's Militia
        title = { "20:276130866:79271171", "กองกำลังประชาชน" },
        objective = { "144:610338293:219989758", "Gryan Stoutmantle ต้องการให้เจ้าสังหาร Defias Highwayman 15 คน, Defias Pathstalker 5 คน และ Defias Knuckleduster 5 คน แล้วกลับไปหาเขาที่ Sentinel Hill" },
        description = { "293:1778887305:1621142178", "Defias บางกลุ่มหลบเราได้ หน่วยสอดแนมที่ไว้ใจที่สุดรายงานว่ามันปล้นชนบทไปถึง Westfall ตอนใต้ เราเชื่อว่าซ่อนใน Dagger Hills วางแผนครั้งต่อไป จงกำจัดพวกเลวในนาม People's Militia" },
        progress = { "N 200:430601226:585638764", "{name} ตอนนี้ไม่ใช่เวลาคุยเล่น หากยังอยากพิสูจน์ตนต่อ People's Militia ต้องสังหาร Defias ที่ข้าแจ้งก่อนหน้านี้ กลับมาเมื่อทำหน้าที่สำเร็จ" },
        completion = { "328:288728889:1562577542", "เมื่อจากแผ่นดินแปดเปื้อน Lordaeron ข้ากลับมาพบสภาพบ้านเกิดน่าเศร้า แต่ Westfall ยังมีหวัง ความกล้าในสนามรบพิสูจน์ชัดว่าเจ้ารับใช้อุดมการณ์อย่างมีเกียรติ ข้าภูมิใจอย่างยิ่งที่จะรับเจ้าเข้า People's Militia ขอแสงสว่างส่องเจ้า" },
        objectiveLabels = {
            monster = { ["Defias Highwayman slain"] = "ปราบ โจรดักปล้น Defias", ["Defias Pathstalker slain"] = "ปราบ นักซุ่มตามทาง Defias", ["Defias Knuckleduster slain"] = "ปราบ นักสู้สนับมือ Defias" },
        },
    },
    [22] = { -- Goretusk Liver Pie
        title = { "18:2057935772:1501777027", "พายตับ Goretusk" },
        objective = { "67:400173847:2058265316", "Salma Saldean ต้องการ Goretusk Liver 8 ชิ้นทำพายตับ Goretusk" },
        description = { "206:1215371250:998353722", "ปอกหอมแล้ว สับกระเทียมแล้ว บดโรสแมรีแล้ว อบแป้งพายแล้ว สับผักชีลาวแล้ว น้ำเกรวีกำลังเคี่ยว ทีนี้พายเนื้อขึ้นชื่อข้าขาดเพียง Goretusk Liver 8 ชิ้น!" },
        progress = { "56:1411769892:113600139", "พายเนื้อขึ้นชื่อข้าขาดเพียง Goretusk Liver 8 ชิ้น!" },
        completion = { "24:653657007:1212885509 N 167:1543890883:251602984 C 29:308957429:1520748646", "เหมาะพอดี {name}! ขอบใจมาก คืนนี้ข้ากับ Farmer Saldean จะกินเลี้ยง นี่ของเล็กน้อยตอบแทนงานหนัก เจ้าไม่ได้คิดว่าข้าจะปล่อยให้{class}อย่างเจ้าหิวใช่ไหม?" },
        required = { [723] = { "14:1005650612:1572329028", "ตับหมูป่า Goretusk" } },
        steps = { { "14:1005650612:1572329028", "ตับหมูป่า Goretusk" } },
    },
    [36] = { -- Westfall Stew
        title = { "13:1997392046:1900909718", "สตู Westfall" },
        objective = { "82:1616271891:1336163288", "Verna Furlbrow ต้องการให้เจ้าส่งสูตร Westfall Stew ของนางให้ Salma Saldean" },
        description = { "407:745337903:822780536", "ไม่เคยคิดว่าจะมีวันจากไร่ แต่โจรยึดทุ่ง ตอนนี้อันตรายเกินไป ทันทีที่ Farmer Furlbrow ซ่อมเกวียนเสร็จ เราจะออกเดินทาง\n\nช่วยข้าหน่อยได้ไหม? ให้ข้าจดสูตรสตู Westfall โปรดนำไปให้ Salma Saldean ที่ไร่โน้น ไร่ Saldean อยู่เลยทางแยกไป" },
        progress = { "104:1628323565:1032526262", "ข้าคงคิดถึง Verna Furlbrow มาก เจ้าได้พบนางระหว่างมาที่นี่บ้างไหม?" },
        completion = { "212:978473394:398749132", "Verna เป็นสาวใจดีเสมอ เราคงคิดถึงนางที่ Westfall แต่พูดกันตรง ๆ นางเป็นสาวเมืองในหัวใจ Stormwind คงเหมาะดี เอาล่ะ พอนินทา! ทีนี้ทำสตู Westfall ได้แล้ว!" },
        required = { [2832] = { "28:1962480977:70940259", "สูตรสตูว์ Westfall ของ Verna" } },
        steps = { { "28:1962480977:70940259", "สูตรสตูว์ Westfall ของ Verna" } },
    },
    [38] = { -- Westfall Stew
        title = { "13:1997392046:1900909718", "สตู Westfall" },
        objective = { "85:526767570:407197527", "Salma Saldean ต้องการ Stringy Vulture Meat 3 ชิ้น, Goretusk Snout 3 ชิ้น, Murloc Eye 3 ชิ้น และ Okra 3 ชิ้น" },
        description = { "136:1174855047:749635938", "ช่วยทำสตู Westfall! กลับมาพร้อมวัตถุดิบเหล่านี้:\n\nStringy Vulture Meat 3 ชิ้น\nGoretusk Snout 3 ชิ้น\nMurloc Eye 3 ชิ้น\nOkra 3 ชิ้น" },
        progress = { "103:252375153:2122598034", "กลับมาพร้อมวัตถุดิบเหล่านี้:\n\nStringy Vulture Meat 3 ชิ้น\nGoretusk Snout 3 ชิ้น\nMurloc Eye 3 ชิ้น\nOkra 3 ชิ้น" },
        completion = { "177:2098608405:1480296982 N 58:850596169:978409628", "กระเจี๊ยบจะทำให้น้ำซุปข้นกำลังดี! เติมเนื้อแร้งเหนียว ตาเมอร์ล็อกนิดหน่อย และจมูก Goretusk แสนอร่อยก็เสร็จ! สำหรับความช่วยเหลือทั้งหมด {name} ข้าอยากให้รับสตู Westfall หม้อแรกของวันนี้!" },
        required = { [730] = { "10:1115274483:723062552", "ดวงตาเมอร์ล็อก" }, [729] = { "20:1209258282:775912113", "เนื้อแร้งเหนียวเป็นเส้น" }, [731] = { "14:1562587097:1497467272", "จมูกหมูป่า Goretusk" }, [732] = { "4:1348089485:179450447", "กระเจี๊ยบเขียว" } },
        steps = { { "10:1115274483:723062552", "ดวงตาเมอร์ล็อก" }, { "20:1209258282:775912113", "เนื้อแร้งเหนียวเป็นเส้น" }, { "14:1562587097:1497467272", "จมูกหมูป่า Goretusk" }, { "4:1348089485:179450447", "กระเจี๊ยบเขียว" } },
    },
    [48] = { -- Sweet Amber
        title = { "11:829990953:1045827640", "อำพันหวาน" },
        objective = { "49:126841341:9546138", "นำ Holy Spring Water ไปให้ Grimbooze Thunderbrew" },
        description = { "173:2028904389:1009714956", "แดนใต้เถาวัลย์คดเคี้ยวเลื้อยไกล\nบ่อลับซ่อนน้ำลึกไว้ข้างใน\nบริสุทธิ์ดั่งธิดาศักดิ์สิทธิ์แห่งแสง\nจงนำน้ำพุศักดิ์สิทธิ์มาให้ข้า" },
        progress = { "208:1945352957:2022331395", "เอิ๊ก! โฮโฮ! อยากฟังซ้ำหรือ?\n\nแดนใต้เถาวัลย์คดเคี้ยวเลื้อยไกล\nบ่อลับซ่อนน้ำลึกไว้ข้างใน\nบริสุทธิ์ดั่งธิดาศักดิ์สิทธิ์แห่งแสง\nจงนำน้ำพุศักดิ์สิทธิ์มาให้ข้า" },
        completion = { "14:256170496:1727328479", "เอิ๊ก! โฮโฮ!" },
        required = { [737] = { "17:1435238426:1183373813", "น้ำพุศักดิ์สิทธิ์" } },
        steps = { { "17:1435238426:1183373813", "น้ำพุศักดิ์สิทธิ์" } },
    },
    [49] = { -- Sweet Amber
        title = { "11:829990953:1045827640", "อำพันหวาน" },
        objective = { "79:179635703:1975339638", "Grimbooze Thunderbrew ต้องการ Sack of Barley, Sack of Rye และ Sack of Corn" },
        description = { "174:2108601355:978186720", "อำพันคือสีรักยาวนานแห่งชีวิต\nดั่งถ่านไฟสุดท้ายยามฟ้าสนธยา\nนำมาเพื่อให้รักข้าถือกำเนิด\nข้าวบาร์เลย์ ไรย์ ข้าวโพด อย่างละกระสอบ" },
        progress = { "194:1723569969:1006642957", "ร้องซ้ำหรือ? ได้สิ!\n\nอำพันคือสีรักยาวนานแห่งชีวิต\nดั่งถ่านไฟสุดท้ายยามฟ้าสนธยา\nนำมาเพื่อให้รักข้าถือกำเนิด\nข้าวบาร์เลย์ ไรย์ ข้าวโพด อย่างละกระสอบ" },
        completion = { "14:258284064:1727877631", "เอิ๊ก! โฮโฮ!" },
        required = { [738] = { "14:891570551:2017195694", "กระสอบข้าวบาร์เลย์" }, [739] = { "12:705475599:241242992", "กระสอบข้าวโพด" }, [740] = { "11:1349049100:887322520", "กระสอบข้าวไรย์" } },
        steps = { { "14:891570551:2017195694", "กระสอบข้าวบาร์เลย์" }, { "12:705475599:241242992", "กระสอบข้าวโพด" }, { "11:1349049100:887322520", "กระสอบข้าวไรย์" } },
    },
    [50] = { -- Sweet Amber
        title = { "11:829990953:1045827640", "อำพันหวาน" },
        objective = { "39:462636182:840459420", "Grimbooze Thunderbrew ต้องการ Truesilver" },
        description = { "169:2025812592:1088130730", "ข้าจะผสมจนได้ของหมัก\nเก็บไว้เป็นคลังลับเฉพาะเรา\nเครื่องกลั่นต้องทำจากโลหะแข็งแรง\nนำ Truesilver มาให้ข้าจบเพลง" },
        progress = { "206:803836070:1034947527", "ร้องซ้ำให้เจ้าหรือ? ได้สิ สหาย!\n\nข้าจะผสมจนได้ของหมัก\nเก็บไว้เป็นคลังลับเฉพาะเรา\nเครื่องกลั่นต้องทำจากโลหะแข็งแรง\nนำ Truesilver มาให้ข้าจบเพลง" },
        completion = { "14:258284064:1727877631", "เอิ๊ก! โฮโฮ!" },
        required = { [6037] = { "14:999689902:1924659795", "แท่งเงินทรูซิลเวอร์" } },
        objectiveLabels = {
            item = { ["Truesilver Bar"] = "แท่งเงินทรูซิลเวอร์" },
        },
    },
    [51] = { -- Sweet Amber
        title = { "11:829990953:1045827640", "อำพันหวาน" },
        objective = { "49:1044025915:1227855366", "นำ Sycamore Branch ไปให้ Grimbooze Thunderbrew" },
        description = { "171:1237572269:1105118406", "เพิ่งกลั่นใหม่ยังไม่ได้กรอง\nดั่งดินไถรอเมล็ดงอกงาม\nขั้นต่อไปข้าจะทำกองถ่าน\nนำกิ่ง Sycamore มา คืองานต่อไป" },
        progress = { "205:1714948118:776142439", "ร้องซ้ำหรือ? เพื่อเจ้า ได้ทุกอย่าง!\n\nเพิ่งกลั่นใหม่ยังไม่ได้กรอง\nดั่งดินไถรอเมล็ดงอกงาม\nขั้นต่อไปข้าจะทำกองถ่าน\nนำกิ่ง Sycamore มา คืองานต่อไป" },
        completion = { "14:258284064:1727877631", "เอิ๊ก! โฮโฮ!" },
        required = { [742] = { "17:1945300638:403200617", "กิ่งไม้ Sycamore" } },
        steps = { { "17:1945300638:403200617", "กิ่งไม้ Sycamore" } },
    },
    [53] = { -- Sweet Amber
        title = { "11:829990953:1045827640", "อำพันหวาน" },
        objective = { "52:333776236:2135815223", "นำ Charred Oak หนึ่งมัดไปให้ Grimbooze Thunderbrew" },
        description = { "167:117357161:68305761", "ของเหลวหวานใสดั่งน้ำตาทารก\nผ่านปีเปลี่ยนเป็นอำพันเข้มงดงาม\nแต่ก่อนเราจะเมากันสุดเหวี่ยง\nต้องสร้างถังโอ๊กไหม้เสียก่อน" },
        progress = { "209:977983797:135028551", "ได้สิ ข้าจะร้องอีก สหาย!\n\nของเหลวหวานใสดั่งน้ำตาทารก\nผ่านปีเปลี่ยนเป็นอำพันเข้มงดงาม\nแต่ก่อนเราจะเมากันสุดเหวี่ยง\nต้องสร้างถังโอ๊กไหม้เสียก่อน" },
        completion = { "176:1964039055:599878591", "บ่มในถัง กรองผ่านถ่าน\nผ่านริมฝีปากตรงสู่จิตวิญญาณ\nมาดื่มยกแก้วให้เจ้า\nและให้ข้าด้วย Grimbooze Thunderbrew!" },
        required = { [743] = { "21:800257493:1438503415", "มัดไม้โอ๊กไหม้เกรียม" } },
        objectiveLabels = {
            item = { ["Bundle of Charred Oak"] = "มัดไม้โอ๊กไหม้เกรียม" },
        },
    },
    [64] = { -- The Forgotten Heirloom
        title = { "22:1245752688:232642330", "มรดกที่ลืมไว้" },
        objective = { "122:1244133007:2112338111", "Farmer Furlbrow ต้องการนาฬิกาพกจากตู้เสื้อผ้าในบ้านไร่ฟักทองของเขาทางตะวันตก" },
        description = { "434:1568591605:913598464", "เลวร้ายเหลือเกิน! Verna ปลุกข้าเมื่อได้ยินเสียงอึกทึกในทุ่ง อันธพาลเต็มไปหมด เรารีบหนีจนลืมหยิบนาฬิกาพก พ่อ Verna ให้ในวันแต่งงาน ข้ารู้สึกแย่มากที่โจรมีมัน ข้าทิ้งไว้ในตู้เสื้อผ้าในบ้านไร่ มองหาไร่ฟักทองทางตะวันตก เห็นชัดแน่ หากเอากลับมา ข้าจะขอบใจยิ่ง!" },
        progress = { "44:678434639:165526928", "ได้นาฬิกาข้ากลับมาหรือไม่?" },
        completion = { { "151:583441374:626475071", "151:162626337:40660984" }, "นาฬิกาข้า! ขอบใจมาก ท่านผู้ใจดี!\n\nเราเป็นเพียงชาวไร่ยากจนที่เสียแผ่นดิน แต่โปรดรับรางวัลนี้แทนความขอบคุณ", variants = { { "150:378402672:1972998116", "นาฬิกาของข้า! ขอบคุณมากครับ ท่านผู้ใจดี!\n\nพวกเราเป็นเพียงชาวไร่ยากจนที่เสียที่ดินไป แต่ขอให้ท่านรับรางวัลนี้ไว้แทนคำขอบคุณของเราด้วยครับ" } } },
        required = { [841] = { "23:518505967:1747412599", "นาฬิกาพกของ Furlbrow" } },
        steps = { { "23:518505967:1747412599", "นาฬิกาพกของ Furlbrow" } },
    },
    [102] = { -- Patrolling Westfall
        title = { "19:118240179:1277874531", "ลาดตระเวน Westfall" },
        objective = { "55:1576528010:871461723", "นำ Gnoll Paw 8 ชิ้นไปให้ Captain Danuvin ที่ Sentinel Hill" },
        description = { "472:106872678:1301657610", "Stormwind ทอดทิ้งเราแล้ว ลมชั่วแห่งความเสื่อมทรามพัดทั่วทุ่ง Westfall ที่นี่คือบ้านเกิด ข้าไม่หันหลังให้ผู้ที่เลือกอยู่ต่อ พวกเราชาวไร่เก่าจะยืนหยัด\n\nหากรับงาน จงลาดตระเวนทุ่งหญ้า Westfall ตามล่าสังหารนอลล์ชั่วช้าที่ดูจะร่วมมือกับโจร Deadmines นำอุ้งเท้านอลล์แปดชิ้นมา แล้วข้าจะตอบแทนความกล้า" },
        progress = { "60:551143207:156289669", "เก็บอุ้งเท้านอลล์เจ้าเล่ห์ครบ 8 ชิ้นหรือยัง?" },
        completion = { "11:534428891:784080240 N 214:1485388983:142124860", "ทำได้ดี {name} เมื่อมีนักผจญภัยกล้าเช่นเจ้าสู้เคียง People's Militia Westfall อาจกลับเป็นอู่ข้าวอู่น้ำรุ่งเรืองอย่างเดิม โปรดรับนี่เป็นเกียรติแก่ความเพียรไม่ย่อท้อ" },
        required = { [725] = { "9:1198097599:2030067459", "อุ้งเท้าโนลล์" } },
        objectiveLabels = {
            item = { ["Gnoll Paw"] = "อุ้งเท้าโนลล์" },
        },
    },
    [103] = { -- Keeper of the Flame
        title = { "19:1367265487:498881543", "ผู้ดูแลเปลวไฟ" },
        objective = { "68:1922211944:1192718442", "นำ Flask of Oil 5 ขวดไปให้ Captain Grayson ที่ Westfall Lighthouse" },
        description = { "430:608998145:1587334430", "คืนที่ครอบครัวคนเฝ้าประภาคารตายนั้นเลวร้าย ข้ามองอย่างไร้ทางช่วยขณะ Old Murk-Eye นำโจมตี แต่สิ่งที่เกิดแล้วก็ผ่านไป ตอนนี้ข้าห่วงกะลาสีบน Great Sea ที่เรือเข้าใกล้หินอันตรายริมฝั่ง เมื่อไม่มีใครดูเปลวไฟ หน้าที่จึงตกแก่ข้า\n\nช่วยให้คบไฟสว่างต่อ โดยนำ Flask of Oil 5 ขวดจากพวก Harvest Monster มา" },
        progress = { "46:728275470:630321839 N 1:46:46", "ไม่มีน้ำมัน ไฟจะไหม้ได้ไม่นาน {name}" },
        completion = { "18:996564199:1240051160 C 234:1662251481:1607730934", "ข้าขอสรรเสริญ{class}ผู้กล้า เพราะงานหนักเจ้า โขดหินชายฝั่ง Westfall จะสว่าง หลายชีวิตจะรอดตราบใดที่คบไฟยังติด\n\nข้าตายอย่างไม่จำเป็นบนฝั่งนี้ ภาระหลังความตายคือกันไม่ให้ผู้อื่นตามชะตาข้า" },
        required = { [814] = { "12:1923604494:649441161", "ขวดน้ำมัน" } },
        steps = { { "12:1923604494:649441161", "ขวดน้ำมัน" } },
    },
    [104] = { -- The Coastal Menace
        title = { "18:1499982602:541608201", "ภัยริมฝั่ง" },
        objective = { "76:1366397561:1428764282", "นำเกล็ดของ Old Murk-Eye ไปให้ Captain Grayson ที่ Westfall Lighthouse" },
        description = { "500:1536916807:208140127", "เมื่อชีวิตจบบนโขดหิน ข้าไม่รู้ว่าโลกหลังความตายรออะไร ประภาคารมืดคืนนั้นเพราะ Old Murk-Eye ขู่ครอบครัวคนเฝ้าหนี พวกเขากลับมาจุดไฟ แต่มันชักจูงเมอร์ล็อกจิตใจอ่อนแอมาบุกซ้ำ ครั้งที่สองครอบครัวไม่โชคดี ข้าเห็นพวกเขาตายอย่างไร้ทางสู้\n\nหากเห็น Old Murk-Eye ริมฝั่ง จงสังหารแล้วนำเกล็ดหนึ่งชิ้นมา ข้าจะให้รางวัล" },
        progress = { "157:766796228:1274476336", "กำจัด Old Murk-Eye ตัวอันตรายหรือยัง? มีคนเห็นมันเดินตามชายฝั่ง Westfall\n\nกลับมาเมื่อสัตว์ร้ายตายแล้ว" },
        completion = { "50:1017160797:36024967 N 180:1921833643:1348450241", "Murk-Eye พวกนอกรีตชั่วตายแล้วสินะ ทำได้ดี {name} มือเจ้าจบชีวิตหนึ่ง แต่อาจช่วยอีกมาก Great Sea ที่อันตรายเสมอจะปลอดภัยขึ้นอีกนิดคืนนี้ เพราะวีรกรรมเจ้า" },
        required = { [3636] = { "21:1821288311:1041410504", "เกล็ดของ Old Murk-Eye" } },
        objectiveLabels = {
            item = { ["Scale of Old Murk-Eye"] = "เกล็ดของ Old Murk-Eye" },
        },
    },
    [117] = { -- Thunderbrew
        title = { "11:1820920006:775461568", "Thunderbrew" },
        objective = { "64:49660119:1115558845", "นำ Hops 5 ชิ้นไปให้ Grimbooze Thunderbrew เพื่อทำเครื่องดื่มสูตรพิเศษให้เสร็จ" },
        description = { "139:2061700046:108611163", "รีบหน่อยสหาย อย่ามัวรอ\nให้ลาเกอร์เข้มข้นของเรา\nรสเป็นเบียร์แทนสตู\nต้องมีฮอปส์ช่วยต้มปรุง" },
        progress = { "139:2061700046:108611163", "รีบหน่อยสหาย อย่ามัวรอ\nให้ลาเกอร์เข้มข้นของเรา\nรสเป็นเบียร์แทนสตู\nต้องมีฮอปส์ช่วยต้มปรุง" },
        completion = { "141:970324367:2021915663", "ฮอปส์ บาร์เลย์ ยีสต์และมอลต์\nรสโหมกระหน่ำต่อมรับรส\nไม่ต้องอ้อนวอน ไม่ต้องขอ\nThunderbrew Lager มาเป็นถัง!" },
        required = { [1274] = { "4:1229531034:163782210", "ดอกฮอปส์" } },
        objectiveLabels = {
            item = { ["Hops"] = "ดอกฮอปส์" },
        },
    },
    [136] = { -- Captain Sander's Hidden Treasure
        title = { "32:2134873513:569890669", "สมบัติลับของ Captain Sander" },
        objective = { "65:1102966988:2029567199", "หาหีบส่วนตัวของ Captain Sanders แล้วค้นหาเบาะแสต่อไป" },
        description = { "421:766833630:981169107", "หากอ่านนี่ แสดงว่า Captain Sanders เฒ่าจมหลุมศพน้ำแล้ว สมบัติข้าเป็นของเจ้า เพียงตามเบาะแส\n\nก่อนอื่นหาหีบส่วนตัว ตอนนี้คงจมทรายครึ่งใบ อยู่ริมฝั่งตะวันตก Westfall ใกล้ซากเรือ ซากมีมากแต่สมอขึ้นสนิมริมฝั่งมีเพียงอันเดียว หาสมอแล้วจะพบหีบ! ดูข้างในหาเบาะแสต่อไป" },
        completion = { "157:1165895556:1063924440", "หีบค่อย ๆ เปิดเอี๊ยด เหมือนมีแต่ทรายกับน้ำ แต่เดี๋ยว! ปูตัวเล็กวิ่งออกมา หนีบเบาะแสสมบัติในก้าม!" },
    },
    [138] = { -- Captain Sander's Hidden Treasure
        title = { "32:2134873513:569890669", "สมบัติลับของ Captain Sander" },
        objective = { "77:774744619:1097028056", "หาถังเก่าใกล้ปล่องไฟพัง แล้วค้นหาเบาะแสต่อไป" },
        description = { "228:537555570:860272817", "เบาะแสสมบัติเขียนว่า: ทำได้ดี สหาย! ทีนี้ตรงไปตะวันออก ขึ้นหน้าผาไปทางตะวันออก จนถึงถนน มองหาซากปล่องไฟเก่าข้างถนน จะพบถังเก่าพร้อมเบาะแสถัดไป" },
        completion = { "27:908792276:354249097", "ทำได้ดี นักล่าสมบัติ!" },
    },
    [139] = { -- Captain Sander's Hidden Treasure
        title = { "32:2134873513:569890669", "สมบัติลับของ Captain Sander" },
        objective = { "60:1309026045:289926327", "ค้นเหยือกเปล่าข้างกังหันลมเพื่อหาเบาะแสต่อไป" },
        description = { "315:1787405218:1197384799", "ค้นถังแล้วพบแผ่นหนังอีกชิ้น เขียนว่า: จากถังนี้หันเหนือ เดินตรงไม่อ้อมจนเห็นเหยือกเปล่าข้างกังหันลมโดดเดี่ยวบนผาริมทะเล ค้นในเหยือกแล้วอาจพบสิ่งที่หา" },
        completion = { "51:269284296:1552696920", "เจ้ากำลังไปถึงขุมทรัพย์แล้ว นักล่าสมบัติ!" },
    },
    [140] = { -- Captain Sander's Hidden Treasure
        title = { "32:2134873513:569890669", "สมบัติลับของ Captain Sander" },
        objective = { "58:2092878115:713226662", "หาหีบของ Captain Sanders แล้วเปิดรับรางวัล" },
        description = { "418:1126447193:721047795", "แน่นอน ลึกในเหยือกเก่ามีเบาะแสสมบัติ Sander อีกชิ้น หมึกเลือนบางจุด กระดาษกลิ่นวิสกี้ แต่พออ่านได้: พบเหยือกวิสกี้ข้าแล้วก็ใกล้สมบัติ! หันตะวันตกจากขวด เดินลงชายฝั่ง พอถึงน้ำก็ไปต่อ! ว่ายตรงตะวันตกจนพบเกาะที่มีหีบสมบัติข้า!" },
        completion = { "120:610758623:161352506", "บานพับหีบเก่าขึ้นสนิมแต่ยังใช้ได้ เจ้าออกแรงเปิดแล้วหยิบสมบัติ\n\nยินดีด้วย!" },
    },
    [151] = { -- Poor Old Blanchy
        title = { "16:684395603:1611182894", "Blanchy แก่ผู้น่าสงสาร" },
        objective = { "69:1978772224:1642548392", "Verna Furlbrow ที่ Westfall ต้องการให้เจ้านำ Handful of Oats 8 กำมือมาให้" },
        description = { "419:5063891:1064224684", "Blanchy แก่ผู้น่าสงสาร! เหนื่อยเหลือเกินหลังงานหนักที่เราฝืนให้ทำ ข้าให้อาหารก่อนจากไร่ แต่ไม่คิดว่าเกวียนจะพัง หากนำข้าวโอ๊ตจากทุ่งมาสักไม่กี่กำมือ ข้าจะขอบใจ\n\nตามไร่ทั่ว Westfall คงมี หากเลี่ยงเครื่องจักรน่ากลัวที่ยึดพื้นที่ได้ มีหลายไร่ทางตะวันตกเฉียงใต้ของที่นี่" },
        progress = { "72:568176655:2131856500", "Blanchy แก่แทบไม่ไหวแล้ว พบข้าวโอ๊ตให้นางไหม?" },
        completion = { "19:1061876233:111335988 N 36:386268340:1764371620", "ขอบใจมาก {name}! Blanchy แก่ผู้น่าสงสารคงดีใจ!" },
        required = { [1528] = { "15:1299429667:1495788762", "ข้าวโอ๊ตหนึ่งกำมือ" } },
        steps = { { "15:1299429667:1495788762", "ข้าวโอ๊ตหนึ่งกำมือ" } },
    },
    [152] = { -- The Coast Isn't Clear
        title = { "21:1611564:2048730849", "ชายฝั่งยังไม่ปลอดภัย" },
        objective = { "118:209618048:945020912", "สังหาร Tidehunter 7 ตัว, Warrior 7 ตัว, Oracle 7 ตัว และ Coastrunner 7 ตัว แล้วกลับไปหา Captain Grayson ที่ Westfall Lighthouse" },
        description = { "344:450159187:945362397", "คงเห็นซากเรือมากมายตามฝั่งแล้ว Great Sea อันตรายจริง ต้องให้ฝั่ง Westfall ปลอดภัย เผื่อกะลาสีมาถึงหาดเรา แต่เมอร์ล็อกเป็นปัญหา\n\nกำจัด Tidehunter 7 ตัว, Warrior 7 ตัว, Oracle 7 ตัว และ Coastrunner 7 ตัว ข้าจะตอบแทน" },
        progress = { "104:972946572:419273419", "กำจัด Tidehunter 7 ตัว, Warrior 7 ตัว, Oracle 7 ตัว และ Coastrunner 7 ตัว ข้าจะตอบแทน" },
        completion = { "11:534428891:784080240 N 90:1666559195:586596289", "ทำได้ดี {name} เจ้าถนัดการต่อสู้จริง เพราะเจ้า ชายฝั่ง Westfall จึงปลอดภัยขึ้น" },
        objectiveLabels = {
            monster = { ["Murloc Coastrunner slain"] = "ปราบ เมอร์ล็อกนักวิ่งเลียบชายฝั่ง", ["Murloc Warrior slain"] = "ปราบ นักรบเมอร์ล็อก", ["Murloc Tidehunter slain"] = "ปราบ เมอร์ล็อกนักล่าตามกระแสน้ำ", ["Murloc Oracle slain"] = "ปราบ นักพยากรณ์เมอร์ล็อก" },
        },
    },
    [153] = { -- Red Leather Bandanas
        title = { "20:1038679149:1954050448", "ผ้าโพกหัวหนังแดง" },
        objective = { "64:921800770:825003007", "นำ Red Leather Bandana 15 ผืนไปให้ Scout Galiaan ที่ Sentinel Hill" },
        description = { "285:73175135:1570179459", "แนว Defias เปลี่ยนตลอด ข้าตามความเคลื่อนไหวมาพักหนึ่ง นอกจากนี้พบว่าสมาชิกหลายคนตามรอยได้จาก Red Leather Bandana ที่สวม\n\nนำมา 15 ผืน ข้าจะให้รางวัล" },
        progress = { "55:1798313073:705191592", "นำผ้าโพกหัวหนังแดง 15 ผืนมา แล้วข้าจะจ่ายอย่างงาม" },
        completion = { "11:241196533:450692148 R 69:2141001881:281667568", "ทำได้ดี {race} โปรดเลือกของชิ้นหนึ่งเป็นค่าตอบแทนงานหนักทั้งหมด" },
        required = { [829] = { "19:697586855:490313554", "ผ้าคาดหัวหนังสีแดง" } },
        steps = { { "19:697586855:490313554", "ผ้าคาดหัวหนังสีแดง" } },
    },
    [184] = { -- Furlbrow's Deed
        title = { "15:1383153156:1407111420", "โฉนดของ Furlbrow" },
        objective = { "41:1338943143:1095925549", "นำ Furlbrow's Deed ไปให้ Farmer Furlbrow" },
        description = { "483:597656198:206249567", "นี่คือโฉนดไร่ผืนหนึ่งใน Westfall ลงชื่อ Theodore Furlbrow และมี Verna ภรรยาร่วมลงชื่อ ด้านหลังเขียนลวก ๆ ว่า\n\n“เราขู่ Furlbrow จนได้โฉนด คิดว่าอาจมีประโยชน์หากอยากปลอมแบบนี้ให้ที่ของเจ้า\n\nพวก Furlbrow ไม่สร้างปัญหาหรอก ล่าสุดเห็นกำลังออก Westfall แต่ติดเกวียนพัง”\n\nเจ้าคิดว่าพวก Furlbrow คงอยากได้โฉนดคืน..." },
        progress = { "254:1568041902:1147263817", "เจ้ามีโฉนดไร่ข้าหรือ?? ข่าวดี! อันธพาลขโมยไปหลายวันก่อน... ข้านึกว่าสูญไปตลอดแล้ว!\n\nโปรดคืนให้ เรากำลังออก Westfall และคงไม่กลับเร็ว ๆ นี้ แต่หากกลับก็ต้องมีเอกสาร..." },
        completion = { "17:1929183723:2105806884 N 192:1499604379:1085009456", "ขอบใจมาก {name}! อย่างที่บอก แถวนี้ไม่เหมาะกับคนสุจริตแล้ว แต่หากดีขึ้น โฉนดจะทำให้เอาแผ่นดินคืนได้\n\nข้าไม่มีอะไรให้มากนัก แต่เอานี่ไป" },
        required = { [1971] = { "15:1383153156:1407111420", "โฉนดของ Furlbrow" } },
        steps = { { "15:1383153156:1407111420", "โฉนดของ Furlbrow" } },
    },
    [6181] = { -- A Swift Message
        title = { "15:156971141:1934759724", "สารด่วน" },
        objective = { "45:425532265:425575106", "นำ Lewis' Note ไปให้ Thor ผู้ดูแลกริฟฟอน" },
        description = { "447:332675472:526977078", "แม้ Stormwind ไม่ช่วยเราโดยตรงมากนัก ข้ามีคนในเมืองช่วยส่งเกราะ ชื่อ Osric Strang ร้าน Limited Immunity อยู่ Old Town ของ Stormwind\n\nเกราะเราใกล้หมด ต้องติดต่อ Osric ขอเพิ่ม ช่วยนำจดหมายให้เขาได้ไหม?\n\nไป Stormwind เร็วที่สุดคือติดต่อ Thor ผู้ดูแลกริฟฟอน อยู่ลงเนินไป นำจดหมายให้เขา แล้วขึ้นกริฟฟอนไป Stormwind" },
        progress = { "72:1300128542:1432582505", "ดูรีบร้อนนะ ถ้าอย่างนั้นมาถูกที่แล้ว!" },
        completion = { "94:2051825709:821305686", "ต้องส่งจดหมายไป Stormwind หรือ? ไม่มีปัญหา ใช้กริฟฟอนข้าตัวหนึ่งได้!" },
        required = { [15998] = { "11:2126995793:1118942939", "ข้อความของ Lewis" } },
        steps = { { "11:2126995793:1118942939", "ข้อความของ Lewis" } },
    },
    [6261] = { -- Dungar Longdrink
        title = { "16:1158696826:41963224", "Dungar Longdrink" },
        objective = { "59:1487303774:1857709540", "นำ Osric's Crate ไปให้ Dungar Longdrink ผู้ดูแลกริฟฟอน" },
        description = { "N 387:355787580:1948253581", "{name} ข้ารวบรวมทุกอย่างที่ Lewis ขอไว้ในลัง ช่วยเอาไปให้เขาได้ไหม?\n\nหากคุย Thor ใน Westfall แล้ว ก็ใช้กริฟฟอนกลับได้ Dungar Longdrink เป็นผู้ดูแลของเรา อยู่ Trade District\n\nคุย Dungar แล้วนำลังให้ Lewis เร็วที่สุด เราไม่อยากให้นักรบชายหญิง Westfall ขาดอุปกรณ์ใหม่!" },
        progress = { { "89:356211777:1721710644", "91:1694556345:1128493301" }, "เหงื่อบนหน้าผากเจ้าหรือ? วิ่งมากไปแล้ว คราวหน้าขึ้นกริฟฟอนสิ!" },
        completion = { "152:1879026227:117918123", "ลังส่ง Westfall หรือ? เคยไปมาก่อนไหม? ถ้าเคยก็ไม่มีปัญหา สหาย ข้ามีกริฟฟอนฝึกบินเส้นนั้นมากมาย!" },
        required = { [16115] = { "13:886999055:671146019", "ลังของ Osric" } },
        steps = { { "13:886999055:671146019", "ลังของ Osric" } },
    },
    [6281] = { -- Continue to Stormwind
        title = { "21:1300206047:2030734656", "เดินทางต่อสู่ Stormwind" },
        objective = { "148:104582856:662730682", "ซื้อเที่ยวบินกริฟฟอนจาก Thor แล้วนำ Lewis' Note ไปให้ Osric Strang ที่ร้าน Limited Immunity ใน Old Town ของ Stormwind" },
        description = { "282:602849064:265775734", "จ่ายนิดหน่อยก็นั่งกริฟฟอนไป Stormwind ส่งจดหมาย Lewis ให้ Osric ไม่มีทางอื่นเร็วกว่านี้\n\nหากตกลง พร้อมเมื่อไรก็คุยข้าอีก จะคิดค่าบริการนิดหนึ่ง แต่เชื่อเถอะ คุ้มแน่!" },
        progress = { "62:719385329:994684838", "เดินทางมาหรือ? ไปไหนน่าสนใจบ้างไหม?" },
        completion = { "161:2004759105:1663085319 N 47:285779555:902222704", "อา จดหมาย Quartermaster Lewis? ไม่แปลกที่เขาต้องการอุปกรณ์ Sentinel Hill ไกล ในแผ่นดินที่ Stormwind แทบลืมแล้ว\n\nขอบใจ {name} นี่เงินชดเชยค่าเดินทาง" },
        required = { [15998] = { "11:2126995793:1118942939", "ข้อความของ Lewis" } },
        steps = { { "11:2126995793:1118942939", "ข้อความของ Lewis" } },
    },
    [6285] = { -- Return to Lewis
        title = { "15:727216665:1698652533", "กลับไปหา Lewis" },
        objective = { "128:93975705:66047257", "ซื้อเที่ยวบินกริฟฟอนไป Sentinel Hill จาก Dungar Longdrink แล้วนำ Osric's Crate ไปให้ Lewis ที่ Sentinel Hill" },
        description = { "462:1247797419:813826211", "ผู้ดูแลกริฟฟอนใน Westfall คือ Thor หากเคยคุยเขา ก็ใช้กริฟฟอนข้าไปหาได้\n\nเป็นบทเรียนที่ควรรู้ กริฟฟอนฝึกบินสู่เมืองหลวงเสมอ แต่จะพาไปหาผู้ดูแลตามที่ห่างไกลได้หลังเจ้าเคยไปแล้ว\n\nเจ้าเคยพบ Thor แล้ว พร้อมเมื่อไรก็คุยข้าอีกเพื่อขึ้นกริฟฟอนไป Westfall เมื่อถึงส่ง Osric's Crate ให้ Quartermaster Lewis" },
        progress = { "53:75104911:1396927084", "กลับจาก Stormwind แล้วหรือ? Osric ส่งเกราะมาหรือไม่?" },
        completion = { "98:714306307:1208196224 N 150:1489865072:2093963018", "ดี นำเกราะมาแล้ว! เราจะแบ่งให้ผู้ต้องการทันที\n\nขอบใจ {name} เจ้าช่วยได้มาก และเมื่อคุ้นกับกริฟฟอนแล้ว หวังว่าจะมา Sentinel Hill ช่วยบ่อย ๆ!" },
        required = { [16115] = { "13:886999055:671146019", "ลังของ Osric" } },
        objectiveLabels = {
            item = { ["Osric's Crate"] = "ลังของ Osric" },
        },
    },
    [79008] = { -- ... and that note you found
        title = { "27:652061316:1975462836", "...และจดหมายที่เจ้าพบ" },
        objective = { "53:1042163070:929015352", "เศษจดหมายไหม้เป็นเบาะแสเพียงอย่างเดียวของเจ้า" },
        description = { "225:176396373:359470814", "<เมื่อแสงถ่านค่อย ๆ มืดลง เจ้าพบร่องรอยกองไฟที่มีคนจุดไว้ไม่นาน\n\nท่ามกลางเสบียงกระจัดกระจาย มีจดหมายพองเกรียม>\n\n“ไม่ใช่ทุกสิ่งที่ไหม้จะสูญสิ้น จงหาแผ่นดินฝาแฝด จงหาสถานที่นั้น”" },
        completion = { "121:1545941924:1762860837", "เมื่อพบซากศพไหม้เกรียมอีกแห่ง สายตาเจ้าสะดุดข้อความติดกับแผ่นไม้" },
    },
    [92109] = { -- My First Alchemy Set
        title = { "20:1051115425:1232511782", "ชุดเล่นแร่แปรธาตุชุดแรกของข้า" },
        objective = { "126:1960190482:2057336019", "นำ Empty Vial 5 ใบ, Silverleaf 5 ชิ้น และ Peacebloom 5 ชิ้นไปให้นักเล่นแร่แปรธาตุรุ่นเยาว์ผู้ใฝ่ฝันในยุ้งฉาง Moonbrook ที่ Westfall", variants = { { "127:1153018031:1385476622", "รวบรวม Empty Vial 5 ใบ, Silverleaf 5 ชิ้น และ Peacebloom 5 ชิ้น แล้วนำไปให้นักเล่นแร่แปรธาตุรุ่นเยาว์ในยุ้งฉางที่ Moonbrook ใน Westfall" } } },
        description = { { "385:1577928281:715234035", "383:708631019:963364454" }, "เอ่อ... สวัสดี ข้าไม่ควรคุยกับคนแปลกหน้า แต่... เฮ้ ขวดเงา ๆ ที่โผล่จากกระเป๋าไว้ทำอะไร? เป็นนักเล่นแร่แปรธาตุหรือ? เท่จัง!\n\nโตขึ้นข้าก็อยากเป็นบ้าง พ่อไม่ให้เล่นสมุนไพร บอกว่าอันตรายเกินไป\n\nแต่ข้าอยากเริ่มเรียนตอนนี้ ช่วยหาของให้หน่อยได้ไหม ขอร้องนะ?" },
        progress = { "46:1648379403:37045975", "หวัดดีอีกที! เอาของมาเล่นแร่แปรธาตุให้ข้าหรือเปล่า?" },
        completion = { "157:891320601:294821629", "โห! ดูสิ! ท่านเก็บสมุนไพรพวกนี้เองเลยหรือ?\n\nว้าว ขอบคุณนะคุณผู้ชาย ข้าจะลองดูเดี๋ยวนี้เลยว่าทำอะไรได้บ้าง อยากดูไหม?", variants = { { "155:1563838235:912712297", "โห! ดูสิ! ท่านเก็บสมุนไพรพวกนี้เองเลยหรือ?\n\nว้าว ขอบคุณนะคุณผู้หญิง ข้าจะลองดูเดี๋ยวนี้เลยว่าทำอะไรได้บ้าง อยากดูไหม?" } } },
        required = { [3371] = { "10:2101862828:290474430", "ขวดเปล่า" }, [2447] = { "10:1280200047:1210503404", "สมุนไพร Peacebloom" }, [765] = { "10:438624910:1026177665", "สมุนไพร Silverleaf" } },
        steps = { { "10:2101862828:290474430", "ขวดเปล่า" }, { "10:1280200047:1210503404", "สมุนไพร Peacebloom" }, { "10:438624910:1026177665", "สมุนไพร Silverleaf" } },
    },
    [92110] = { -- My First Real Potion
        title = { "20:559127150:133722441", "ยาจริงขนานแรกของข้า" },
        objective = { "96:783086301:1306528044", "เก็บ Murloc Eye 3 ชิ้นให้นักเล่นแร่แปรธาตุรุ่นเยาว์ผู้ใฝ่ฝันในยุ้งฉาง Moonbrook ที่ Westfall" },
        description = { "433:1685288059:359270175", "ว้าว ยาขนานแรกของข้า! ตอนเริ่มใหม่ ๆ เจ้ารู้ไหมว่าผสมสมุนไพรสองชนิดนั้นแล้วจะกลายเป็นสีแดงสด?\n\nสนุกดี แต่ผสมดอกไม้ไม่กี่ดอกไม่เหมือนการเล่นแร่แปรธาตุที่พ่อทำ เขาใช้ส่วนผสมอื่นด้วย\n\nข้าไม่รู้ใช้อะไร งั้นลองอย่างแรกที่นึกถึง! ดูสิ... ตาเมอร์ล็อกไหม? ฟังน่าขยะแขยง แต่ข้าว่าต้องมีอะไรเกิดขึ้นแน่" },
        progress = { "129:704689014:1763415474", "ไม่ต้องห่วงข้าหรอก ข้าโตแล้ว ดูแลตัวเองได้ แต่อย่าบอกใครว่าข้าซ่อนอยู่ที่นี่นะ ให้เป็นความลับของเราสองคน" },
        completion = { "501:1771486087:1769333770", "ท่านเอาตาเมอร์ล็อกมาให้ข้า! จะได้ทำยาจริง ๆ ขวดแรกแล้ว ตื่นเต้นจนแทบหายใจไม่ออกเลย!\n\nตอนท่านไม่อยู่ ข้าแอบออกไปเก็บสมุนไพรมาอีกหน่อย แล้วก็เจอขวดเปล่าข้างล่างด้วย เอ่อ... คราวนี้ท่านผสมให้ทีนะ\n\n<เด็กหญิงมองเจ้าผสมส่วนประกอบอย่างตื่นเต้น แต่ย่นจมูกตอนเจ้าใส่ลูกตาลงไป ผ่านไปไม่กี่อึดใจ น้ำยาก็กลายเป็นสีส้มขุ่นชวนคลื่นไส้>\n\nโห! เห็นไหม ข้าพูดถูก ข้าคงไม่ดื่มนั่นหรอก แต่นี่สูตรของข้า เผื่อท่านอยากทำอีก ไว้แวะมาใหม่นะ!", variants = { { "492:907784388:1068487073", "เจ้าเอาตาเมอร์ล็อกมาให้ข้าด้วย! ข้าตื่นเต้นสุด ๆ เลย จะได้ทำน้ำยาจริง ๆ ขวดแรกแล้ว!\n\nตอนเจ้าไม่อยู่ ข้าแอบออกไปเก็บสมุนไพรมาอีกหน่อย แล้วก็เจอขวดเปล่าที่ชั้นล่างด้วย เอ่อ... คราวนี้เจ้าช่วยผสมทีนะ\n\n<เด็กน้อยจ้องดูเจ้าผสมส่วนผสมอย่างตื่นเต้น แต่พอเจ้าใส่ลูกตาลงไป นางก็ย่นจมูก เพียงไม่กี่วินาทีน้ำยาก็กลายเป็นสีส้มชวนคลื่นไส้>\n\nว้าว! เห็นไหม ข้าบอกแล้ว ข้าไม่ขอดื่มหรอก แต่ถ้าเจ้าอยากทำเพิ่มก็เอาสูตรของข้าไปได้ ว่าง ๆ แวะมาอีกนะ!" } } },
        required = { [730] = { "10:1115274483:723062552", "ดวงตาเมอร์ล็อก" } },
        steps = { { "10:1115274483:723062552", "ดวงตาเมอร์ล็อก" } },
    },
    [92742] = { -- Testing the Wells
        title = { "17:573660877:1898057696", "ตรวจน้ำบ่อ" },
        objective = { "104:367974252:515303754", "ใช้ Well Water Sample Kit เก็บตัวอย่างจากบ่อที่ Jansen Stead และ Molsen Farm" },
        description = { "255:1476935027:1081082770", "เราต้องหาที่มาและชนิดของพิษที่ทำให้แผ่นดินแปดเปื้อน เริ่มจากน้ำใต้ดินใต้ไร่แถวนี้\n\nไป Jansen Stead ทางเหนือกับ Molsen Farm ทางตะวันตกเฉียงเหนือ เก็บตัวอย่างบ่อที่นั่น" },
        progress = { "28:263261992:206417892", "เก็บตัวอย่างแล้วหรือ?" },
        completion = { "24:1383702119:1177030920", "ขอบใจ ให้ข้าดู..." },
        required = { [254546] = { "25:558987369:413261874", "ตัวอย่างน้ำจากบ้านไร่ Jansen" }, [254547] = { "24:1920715512:994305925", "ตัวอย่างน้ำจากฟาร์ม Molsen" }, [254545] = { "21:246799324:1598924431", "ชุดเก็บตัวอย่างน้ำจากบ่อ" } },
        steps = { { "25:558987369:413261874", "ตัวอย่างน้ำจากบ้านไร่ Jansen" }, { "24:1920715512:994305925", "ตัวอย่างน้ำจากฟาร์ม Molsen" }, { "21:246799324:1598924431", "ชุดเก็บตัวอย่างน้ำจากบ่อ" } },
    },
    [92744] = { -- Murloc Gills
        title = { "12:1791654860:869211286", "เหงือกเมอร์ล็อก" },
        objective = { "92:1468522507:1408870754", "Alba Fairmoon ต้องการ Longshore Murloc Gill 7 ชิ้นจากชายฝั่ง Westfall" },
        description = { "386:1757424501:1942381085", "ความแปดเปื้อนที่กระทบพืช Westfall อาจซึมลงทะเลด้วย หากปลาแถวนี้ได้รับผล Stormwind อาจอดอยาก\n\nเก็บเหงือกเมอร์ล็อกตามชายฝั่งมาให้ข้า เมอร์ล็อกทนทาน แต่ระบบร่างกายไวต่อสิ่งปนเปื้อนมาก พิษในน้ำทะเลจะปรากฏชัดในเหงือกที่เจ้านำมา" },
        progress = { "53:2052287537:1027773326", "หวังว่าเมอร์ล็อกไม่ได้สร้างปัญหามากเกินไปนะ?" },
        completion = { "82:934002417:807158852", "เข้าใจแล้ว... เหงือกดูสุขภาพดีในตอนนี้ แต่เราประมาทไม่ได้", variants = { { "82:801135780:1238626207", "เข้าใจแล้ว... เหงือกดูสุขภาพดีในตอนนี้ แต่เราประมาทไม่ได้" } } },
        required = { [254548] = { "21:631415818:946827409", "เหงือกเมอร์ล็อก Longshore" } },
        steps = { { "21:631415818:946827409", "เหงือกเมอร์ล็อก Longshore" } },
    },
    [92745] = { -- The State of the Mines
        title = { "22:1711434709:1448188721", "สภาพของเหมือง" },
        objective = { "91:123343472:1078626132", "สังหาร Kobold Digger 4 ตัวใน Jangolode Mine และ Riverpaw Miner 6 ตัวใน Gold Coast Quarry" },
        description = { "375:1021778947:1614351820", "ตัวอย่างน้ำบ่อมีโลหะพิษ! หากไม่หยุดความแปดเปื้อนเร็ว ๆ ดินนี้ต้องใช้หลายสิบปีกว่าจะปลูกพืชได้อีก\n\nDefias ยึดเหมือง Westfall ใช้สิ่งมีชีวิตเป็นแรงงานขุดทรัพยากร ขัดขวางด้วยการสังหารคนเหมืองใน Jangolode Mine ทางเหนือ กับ Gold Coast Quarry ทางตะวันตก" },
        completion = { { "80:222845806:451944581", "11:534428891:784080240 N 63:979965768:1418057183", "11:534428891:784080240 C 63:979965768:1418057183", "11:534428891:784080240 R 63:979965768:1418057183" }, "ทำได้ดี สหาย แต่ข้ากลัวว่าต้นพิษอาจอยู่ที่อื่น..." },
        progress = { "32:2041629692:512757244", "มีข่าวจากเหมืองบ้างไหม?" },
        objectiveLabels = {
            monster = { ["Kobold Digger slain"] = "ปราบ โคโบลด์นักขุด", ["Riverpaw Miner slain"] = "ปราบ คนงานเหมือง Riverpaw" },
        },
    },
    [92747] = { -- Moonbrook Espionage
        title = { "19:1303342709:506616003", "สืบข่าวใน Moonbrook" },
        objective = { "56:1543840491:34813496", "เก็บ Suspicious Industrial Supply 8 ชิ้นจาก Moonbrook" },
        description = { "292:2091285507:1549262040 N 88:1817199796:34461949", "แปลก พิษดูไม่มาจากเหมืองที่สำรวจ\n\nข้าได้ยินว่า Deadmines ใต้เมือง Moonbrook เป็นเหมืองใหญ่และลึกที่สุดใน Westfall แต่ถูกทิ้งตั้งแต่สงครามครั้งแรก หรือมันกลับมาทำงานแล้ว?\n\nโปรดไป Moonbrook {name} หาเบาะแสการขุดหรือกิจกรรมอุตสาหกรรม นี่คือเบาะแสสุดท้ายเรา!" },
        progress = { "22:1100807666:322162129", "พบอะไรไหม?" },
        completion = { "17:319730698:1956299484", "ทั้งหมดนี่คืออะไร?" },
        required = { [254676] = { "30:1819921375:476446767", "อุปกรณ์อุตสาหกรรมต้องสงสัย" } },
        steps = { { "30:1819921375:476446767", "อุปกรณ์อุตสาหกรรมต้องสงสัย" } },
    },
    [92748] = { -- Explosive Consultation
        title = { "22:1359047235:1969424723", "ปรึกษาเรื่องระเบิด" },
        objective = { "78:1056441480:1376042801", "ไป Dwarven District ที่ Stormwind แล้วหาวิศวกรที่ช่วยได้" },
        description = { "366:703955021:557575942", "เสบียงที่พบชี้ว่ามีอุตสาหกรรมขนาดใหญ่ที่ไหนสักแห่งใน Deadmines ไม่ต้องสงสัยว่านี่คือต้นพิษที่ทำลายไร่ Westfall ต้องหยุดโดยเร็ว\n\nไม่ว่าข้างล่างมีอะไร คงทำลายยาก ไป Dwarven District ใน Stormwind หาวิศวกรที่จัดหาระเบิดให้เราได้" },
        completion = { "24:149283500:208632481", "มีอะไรต้องระเบิดหรือ?" },
    },
    [92749] = { -- A Dynamite Plan
        title = { "15:1114048164:1802179538", "แผนไดนาไมต์" },
        objective = { "144:638941997:1957064967", "หา Coarse Dynamite 10 ชิ้นจากการสร้าง แลกเปลี่ยน หรือ Auction House แล้วกลับไปหา Sprite Jumpsprocket ที่ Dwarven District ใน Stormwind\n\nหมายเหตุผู้แปล: คลังหลักระบุ Coarse Dynamite แต่แคชเบตาอีกชุดระบุ Rough Dynamite พร้อมข้อความแม่แบบที่ยังไม่ยืนยันรูปแบบแสดงผล จึงยังใช้แทนกันไม่ได้ ให้ยึดชื่อและจำนวนที่เกมระบุ", amount = { "7:1046708115:223027223 W1 134:838502705:119598874", "หา Rough Dynamite {world1} ชิ้นด้วยการสร้าง แลกเปลี่ยน หรือซื้อจาก Auction House แล้วกลับไปหา Sprite Jumpsprocket ที่ Dwarven District ใน Stormwind" } },
        description = { "79:1626130650:703236468", "ก่อวินาศกรรมอุตสาหกรรมหรือ? ข้าสนใจแล้ว!\n\nเริ่มจากไดนาไมต์หน่อย..." },
        progress = { { "33:990114214:233519968", "26:448805976:583264129 N 1:33:33", "26:448805976:583264129 C 1:33:33", "26:448805976:583264129 R 1:33:33" }, "ขอดูระเบิดหน่อย สหาย!" },
        completion = { "83:617971898:1848262627", "เริ่มได้ดีมาก! ทีนี้มัดรวมกัน... แล้วเพิ่มแรงอีกนิด...", variants = { { "83:59327149:95984862", "เริ่มได้ดีมาก! ทีนี้ก็ประกอบทุกอย่างเข้าด้วยกัน... แล้วเติมลูกเล่นให้มันอีกนิด..." } } },
        required = { [4358] = { "14:384525254:1169972252", "ไดนาไมต์แบบหยาบ" } },
        steps = { { "14:384525254:1169972252", "ไดนาไมต์แบบหยาบ" } },
    },
    [92750] = { -- Detonation at a Distance
        title = { "24:1877908580:1259041837", "จุดชนวนจากระยะไกล" },
        objective = { "77:1477098025:868495086", "คุยกับคนใน Stormwind Intelligence เรื่องหาเครื่องจุดชนวนระยะไกล" },
        description = { "277:250096623:540879882", "ข้าเดาว่าอยากได้การระเบิดแบบ “ควบคุมได้”? สนุกน้อยลง แต่เป็นทางเลือกดีหากอยากให้แขนขายังอยู่ครบ\n\nน่าเสียดายข้าไม่มีเครื่องจุดชนวนระยะไกล ลองถามพวกย่องเงียบที่ Stormwind Intelligence สิ พวกนั้นน่าจะหาอะไรให้เราได้", variants = { { "278:859713452:767211934", "ข้าเดาว่าอยากได้การระเบิดแบบ “ควบคุมได้”? สนุกน้อยลง แต่เป็นทางเลือกดีหากอยากให้แขนขายังอยู่ครบ\n\nน่าเสียดายข้าไม่มีเครื่องจุดชนวนระยะไกล ลองถามพวกย่องเงียบที่ Stormwind Intelligence สิ พวกนั้นน่าจะหาอะไรให้เราได้" } } },
        completion = { "47:436521928:398336220", "อืม... มองหาอะไรเฉพาะเจาะจงหรือ?" },
    },
    [92751] = { -- Detonation at a Distance
        title = { "24:1877908580:1259041837", "จุดชนวนจากระยะไกล" },
        objective = { "91:47911427:84426728", "นำ Remote Detonator Kit ไปให้ Sprite Jumpsprocket ที่ Dwarven District ใน Stormwind" },
        description = { "452:558532289:278791735", "ต้องการทำลายบางอย่างหรือ? เกี่ยวกับกิจกรรมเจ้าใน Moonbrook ไหม? อย่าแปลกใจ SI:7 ติดตามทุกสิ่งที่เกิดในดินแดน Stormwind\n\nหากจะระเบิดในถ้ำใต้ Westfall เจ้าควรออกมาไกลก่อน รับเครื่องจุดชนวนระยะไกลนี่ เป็นเครื่องต้นแบบใหม่จากวิศวกรเรา\n\nอ้อ... อย่าพูดเรื่องข้ามีส่วนร่วมให้เพื่อนเอลฟ์เจ้าฟังจะดีที่สุด", variants = { { "454:1598810898:1357040635", "ต้องการทำลายบางอย่างหรือ? เกี่ยวกับกิจกรรมเจ้าใน Moonbrook ไหม? อย่าแปลกใจ SI:7 ติดตามทุกสิ่งที่เกิดในดินแดน Stormwind\n\nหากจะระเบิดในถ้ำใต้ Westfall เจ้าควรออกมาไกลก่อน รับเครื่องจุดชนวนระยะไกลนี่ เป็นเครื่องต้นแบบใหม่จากวิศวกรเรา\n\nอ้อ... อย่าพูดเรื่องข้ามีส่วนร่วมให้เพื่อนเอลฟ์เจ้าฟังจะดีที่สุด" } } },
        progress = { "61:864435548:139728871", "ได้เครื่องจุดชนวนระยะไกลไหม? แบบธรรมดาใช้ไม่ได้นะ!" },
        completion = { "35:439790351:1281862125", "ดี นั่นคือสิ่งที่ต้องการพอดี!", variants = { { "36:1912994885:228207354", "เยี่ยม นั่นคือเครื่องจุดระเบิดที่เราต้องการ!" }, { "37:1690046730:1136627372", "เยี่ยม นั่นคือเครื่องจุดระเบิดที่เราต้องการ!" } } },
        required = { [254552] = { "20:1123285369:1855694949", "ชุดจุดระเบิดระยะไกล" } },
        steps = { { "20:1123285369:1855694949", "ชุดจุดระเบิดระยะไกล" } },
    },
