        description = { "68:1675031015:2141190013", "เรียบร้อย ระเบิดพร้อมแล้ว! ระวังเครื่องจุดชนวนด้วย", variants = { { "69:597865594:2114142957", "เรียบร้อย ระเบิดพร้อมแล้ว! ระวังเครื่องจุดชนวนด้วย" } } },
