    [92909] = { -- Harvesting the Harvesters
        title = { "25:1211556345:933411766", "เก็บเกี่ยวเครื่องเก็บเกี่ยว" },
        objective = { "112:1164725084:883342483", "Ozwin Ironsprocket ที่ Saldean's Farm ต้องการ Golem Isospring 14 ชิ้นและ Harvester Gyrostabilizer 5 ชิ้น" },
        description = { "416:1574778865:1066896289", "โอ้ ไม่... คราวนี้ข้าแย่แน่!\n\nได้ยินเรื่องเครื่องเก็บเกี่ยวคุกคามทุ่ง Westfall ข้าจึงเดินทางจาก Ironforge เพื่อดูว่าปรับเทียบใหม่ได้ไหม แต่มันก้าวร้าวเกินคำนวณมาก ไล่ข้ามาจนติดในคอก!\n\nหากมี Isospring กับ Gyrostabilizer จากเครื่องเก็บเกี่ยว ข้าจะสร้างอุปกรณ์ช่วยหนี ช่วยรวบรวมชิ้นส่วนได้ไหม?" },
        progress = { { "64:180689786:954919770", "23:111265054:1853148395 N 35:2140783178:743339491", "23:111265054:1853148395 C 35:2140783178:743339491", "23:111265054:1853148395 R 35:2140783178:743339491" }, "ข้างนอกวุ่นวาย สหาย! เก็บชิ้นส่วนที่ต้องการแล้วหรือ?" },
        completion = { "79:1734664381:43458622", "ขอบใจมาก! ข้าจะเริ่มแผนหนี ระหว่างนี้รับนี่ไป!" },
        required = { [255007] = { "15:954357313:1971986998", "สปริง Isospring ของโกเลม" }, [255010] = { "24:769605912:1509050683", "ตัวรักษาสมดุลไจโรของเครื่องเก็บเกี่ยว" } },
        steps = { { "15:954357313:1971986998", "สปริง Isospring ของโกเลม" }, { "24:769605912:1509050683", "ตัวรักษาสมดุลไจโรของเครื่องเก็บเกี่ยว" } },
    },
    [92910] = { -- Harvesting the Harvesters
        title = { "25:1211556345:933411766", "เก็บเกี่ยวเครื่องเก็บเกี่ยว" },
        objective = { "84:1605881564:1330922086", "นำ Precessive Autocognition Assembly ไปให้ Ozwin Ironsprocket ที่ Saldean's Farm" },
        description = { "130:2026931529:1041646932", "ชิ้นส่วนที่กู้จากเครื่องเก็บเกี่ยวดูสมบูรณ์เกือบทั้งหมด ผู้สนใจโกเลมเก็บเกี่ยวอาจอยากเห็น" },
        completion = { "12:1899666817:151847254", "นี่อะไรหรือ?" },
        required = { [255155] = { "33:291103442:656793125", "ชุดกลไก Precessive Autocognition" } },
