    },
    [92911] = { -- Harvesting the Harvesters
        title = { "25:1211556345:933411766", "เก็บเกี่ยวเครื่องเก็บเกี่ยว" },
        objective = { "119:766666548:174118303", "Ozwin Ironsprocket ที่ Saldean's Farm ต้องการ Golem Isospring 8 ชิ้น, Copper Modulator 4 ชิ้น และ Crude Scope" },
        description = { "270:1211946513:1363925608", "เข้าใจแล้ว... นี่ช่วยให้รู้กลไกสัตว์ประหลาดพวกนั้น ข้ามีความคิดว่าจะควบคุมระบบมันได้อย่างไร อย่างน้อยก็ชั่วครู่\n\nข้าจะทำงานกับชิ้นส่วนที่เจ้านำมาต่อ ระหว่างนี้ช่วยหาชิ้นส่วนอุปกรณ์เพิ่มได้ไหม?" },
        progress = { "26:2131670155:218800764 N 1:63:63", "งานของเราไปถึงไหนแล้ว {name}?" },
        completion = { "12:1055357314:800872003 N 106:1434196003:175900940", "นี่ไง {name}! น่าจะใช้ได้ดีทีเดียว ลองเอาไปใช้ดูสิ!\n\n...ข้าหรือ? ข้าขออยู่ที่นี่แหละ ยังไงอยู่ไปก็เริ่มรู้สึกเหมือนบ้านแล้ว" },
        required = { [4363] = { "16:930122709:670957792", "ตัวปรับสัญญาณทองแดง" }, [4405] = { "11:1971603190:964584233", "กล้องเล็งแบบหยาบ" }, [255007] = { "15:954357313:1971986998", "สปริง Isospring ของโกเลม" } },
        steps = { { "16:930122709:670957792", "ตัวปรับสัญญาณทองแดง" }, { "11:1971603190:964584233", "กล้องเล็งแบบหยาบ" }, { "15:954357313:1971986998", "สปริง Isospring ของโกเลม" } },
    },
    [93928] = { -- Of Mice and Milk
        title = { "16:1121571884:1623332257", "หนูกับนม" },
        objective = { "23:1975327297:1752992818", "เอาคุกกี้ให้หนู" },
        description = { "28:118775689:169857835", "ข้าต้องการคุกกี้ เข้าใจไหม?\n\nเนียะ!" },
    },
    [98021] = { -- Journey to Sentinel Hill
        title = { "24:1130726851:716282981", "เดินทางสู่ Sentinel Hill" },
        objective = { "57:1295299558:617836949", "รายงานตัวกับ Gryan Stoutmantle ที่ Sentinel Hill ใน Westfall" },
        description = { "485:559936609:1422366493", "หากอยากเริ่มทำสิ่งดีในโลกเรา ข้าแนะนำให้รายงานตัวกับชายชื่อ Gryan Stoutmantle ที่ชุมชน Sentinel Hill ใน Westfall ทางใต้ ผู้คนเขาต้องการความช่วยเหลือ\n\nเมื่อเดินทางมาจากอีกระนาบการดำรงอยู่ ปัญหาแผ่นดินเราอาจดูเล็กน้อย ข้ายืนยันว่าความช่วยเหลือเจ้ามีความหมายทุกอย่างต่อผู้ประสบปัญหา และเจ้าจะแข็งแกร่งขึ้นจากงานเหล่านั้น\n\nโชคดี นักผจญภัย!" },
        completion = { { "191:2041559242:60582344", "141:256671924:45895811 N 40:1714531969:707100135", "141:256671924:45895811 C 40:1714531969:707100135", "141:256671924:45895811 R 40:1714531969:707100135" }, "ข้าขอ Stormwind ส่งคนช่วยหลายเดือน เขากลับส่งเอลฟ์ผอมมา? เอาล่ะ คนขอคงเลือกไม่ได้\n\nยินดีต้อนรับ Westfall นักผจญภัย มาดูว่าจะหางานให้เจ้าทำได้ไหม" },
    },
    [79007] = { -- ... and that note you found
        title = { "27:652061316:1975462836", "...และจดหมายที่เจ้าพบ" },
        objective = { "53:1042163070:929015352", "เศษจดหมายไหม้เป็นเบาะแสเพียงอย่างเดียวของเจ้า" },
        description = { "225:176396373:359470814", "<เมื่อแสงถ่านค่อย ๆ มืดลง เจ้าพบร่องรอยกองไฟที่มีคนจุดไว้ไม่นาน\n\nท่ามกลางเสบียงกระจัดกระจาย มีจดหมายพองเกรียม>\n\n“ไม่ใช่ทุกสิ่งที่ไหม้จะสูญสิ้น จงหาแผ่นดินฝาแฝด จงหาสถานที่นั้น”" },
        completion = { "121:1545941924:1762860837", "เมื่อคุณบังเอิญพบซากศพที่ถูกเผาจนไหม้เกรียมอีกร่าง สายตาก็เหลือบไปเห็นข้อความที่ติดอยู่กับแผ่นไม้" },
    },
    [19] = { -- Tharil'zun
        title = { "10:1344241815:894946071", "Tharil'zun" },
        objective = { "54:1861741589:1355266175", "นำ Tharil'zun's Head ไปให้ Marshal Marris ที่ Redridge" },
        description = { "197:1884615778:512940714", "Blackrock Outrunner กับ Renegade ดักซุ่มระหว่างที่นี่กับ Stonewatch Keep ผู้นำ Outrunner เป็นออร์คชื่อ Tharil'zun เราต้องการตัวมัน นำศีรษะ Tharil'zun มาให้ข้า!" },
        progress = { "87:209113193:1091537466", "แรงกดดันจากออร์ค Blackrock ยังหนัก อย่างน้อยเจ้ากำจัด Tharil'zun ให้เราหรือยัง?" },
        completion = { "103:2143261752:2098198200 N 1:46:46", "Tharil'zun เป็นออร์คโหดเหี้ยมเจ้าเล่ห์ ทำได้ดี ข้าแน่ใจว่ามันไม่ล้มง่าย นี่รางวัล {name}" },
        required = { [1260] = { "17:441984271:480954614", "ศีรษะของ Tharil'zun" } },
        steps = { { "17:441984271:480954614", "ศีรษะของ Tharil'zun" } },
    },
    [20] = { -- Blackrock Menace
        title = { "16:602897066:1167389236", "ภัย Blackrock" },
        objective = { "56:1354906926:639003668", "นำ Battleworn Axe 10 เล่มไปให้ Marshal Marris ที่ Lakeshire" },
        description = { "494:1339539322:1487469728", "ออร์ค Blackrock เดินทางจาก Burning Steppes ยึด Stonewatch Keep ทางเหนือ จากนั้นปล้นพื้นที่เหนือ Lakeshire ขังชาวเมืองไว้ราวฝูงวัว\n\nช่วยขจัดภัยนี้จาก Lakeshire สังหารออร์ค Blackrock แล้วนำ Battleworn Axe สิบเล่มเป็นหลักฐาน\n\nแม้ถูกคุกคามจากเหนือ เรายังได้รายงานว่ามีอีกกลุ่มทางตะวันออกเฉียงใต้ของ Redridge หากพบก็ควรล่าเช่นกัน" },
        progress = { "28:2131487396:961006574 N 24:974958647:512605582", "ได้สังหารออร์คหรือยัง {name}? ถ้าใช่ก็แสดงให้ข้าดู..." },
        completion = { "55:536008917:722361560", "ทีนี้ก็มีออร์คให้กังวลน้อยลงมาก ขอบใจ" },
        required = { [3014] = { "14:263282052:2120998696", "ขวานที่สึกจากการรบ" } },
        steps = { { "14:263282052:2120998696", "ขวานที่สึกจากการรบ" } },
    },
    [34] = { -- An Unwelcome Guest
        title = { "18:2005473391:254532717", "แขกที่ไม่ต้อนรับ" },
        objective = { "86:272655327:1638205021", "Martie Jainrose ที่ Lakeshire ต้องการให้เจ้าสังหาร Bellygrub แล้วนำเขี้ยวให้นางเป็นหลักฐาน" },
        description = { "478:222528246:1146717376", "สวนข้าถูกเหยียบย่ำและปล้นอีกแล้ว ข้ารู้ว่าตัวไหนทำ เจ้าหมูป่าบัดซบที่ Marshal Marris เรียก Bellygrub\n\nข้าปลูกแดฟโฟดิลใหม่ไม่ได้จนฤดูหน้า พังหมด! เพราะหมูป่าอันตรายตัวเดียว กำจัดมันที! นำเขี้ยวให้ดูแล้วข้ายินดีให้รางวัล มันคงหาอาหารในทุ่งตะวันตกเฉียงใต้ Lakeshire แต่บางครั้งก็เดินมาที่นี่และเข้าสวนข้า" },
        progress = { "88:223358859:99933690", "Bellygrub ยังทำอยู่หรือ เจ้ากำจัดภัยนี้ให้ Lakeshire ได้เด็ดขาดแล้ว?" },
        completion = { "47:1401107156:1822986351 N 82:822545837:2010470074", "ในที่สุดเจ้าตัวอันตรายก็ตาย! ขอบใจ {name} เจ้าช่วยข้าอย่างยิ่ง สวนจะผลิบานเต็มที่ฤดูนี้!" },
        required = { [3631] = { "16:1882112500:338234989", "งาของ Bellygrub" } },
        steps = { { "16:1882112500:338234989", "งาของ Bellygrub" } },
    },
    [89] = { -- The Everstill Bridge
        title = { "20:2133664838:746467120", "สะพาน Everstill" },
        objective = { "67:140924181:971119083", "นำ Iron Pike 5 ชิ้นและ Iron Rivet 5 ชิ้นไปให้ Foreman Oslow ที่ Lakeshire" },
        description = { "374:274232787:62480443 N 56:309727852:1165867672", "ตอนออร์คบุกครั้งก่อน เราต้องหลอมเหล็กทำกระสุน ดาบ และเกราะ ส่งข่าว Stormwind ขอวัสดุใหม่ แต่ Redridge Gnoll ปล้นคาราวานแล้วหนีขึ้นเนินหลัง Lakeshire\n\nตอนนี้ของสร้างสะพานใหม่ไม่พอ หากนำ Iron Pike 5 ชิ้นกับ Iron Rivet 5 ชิ้นมา {name} ข้าจะให้รางวัล\n\nเอาล่ะ เริ่มงาน!" },
        progress = { "88:1477651632:785426638", "สะพานสร้างตัวเองไม่ได้! เหล็กกับหมุดอยู่ไหนแล้ว?" },
        completion = { "12:567290253:1686048517 N 99:1257070716:468475593", "ทำได้ดี {name} ของเหล่านี้ช่วยงานสะพานได้มหาศาล เราจะซ่อมให้มั่นคงในไม่ช้า" },
        required = { [2856] = { "9:2140398704:755284257", "หอกยาวเหล็ก" }, [1013] = { "10:462386165:747179462", "หมุดย้ำเหล็ก" } },
        steps = { { "9:2140398704:755284257", "หอกยาวเหล็ก" }, { "10:462386165:747179462", "หมุดย้ำเหล็ก" } },
    },
    [91] = { -- Solomon's Law
        title = { "13:167407189:434751065", "กฎของ Solomon" },
        objective = { "76:299969122:387810615", "นำ Shadowhide Pendant 10 ชิ้นไปให้ Bailiff Conacher ที่ Lakeshire Town Hall" },
        description = { "497:1654435398:758402710", "ศัตรู Stormwind มาพำนักเชิงเขาตะวันออก Redridge วายร้ายนี้ใช้เวทอาร์เคนแพร่ความกลัวและทุกข์แก่เมืองกับประชาชน มันก่อการในชื่อ Morganth\n\nตอนนี้ Morganth ควบคุมเผ่า Shadowhide Gnoll ให้ทำตามคำสั่ง กฎหมาย Lakeshire ระบุว่าช่วยอาชญากรของอาณาจักรมีโทษถึงตาย\n\nต้องสังหารนอลล์ชั่วพวกนี้!\n\nส่ง Shadowhide Pendant 10 ชิ้นให้ข้า แล้วเจ้าจะได้รางวัล" },
        progress = { "64:1977018967:1637096087", "ส่ง Shadowhide Pendant 10 ชิ้นให้ข้า แล้วเจ้าจะได้รางวัล" },
        completion = { "62:1708477919:1128655675 N 86:2019577155:1716603611", "ศาล Lakeshire รับรู้ความมุ่งมั่นต่อความยุติธรรมของเจ้า {name} การบังคับใช้กฎหมายอาณาจักรช่วยค้ำจุนความยุติธรรมของแผ่นดิน" },
        required = { [1075] = { "18:1654653165:1053540616", "จี้ Shadowhide" } },
        steps = { { "18:1654653165:1053540616", "จี้ Shadowhide" } },
    },
    [92] = { -- Redridge Goulash
        title = { "16:866623022:1175508185", "กูลาช Redridge" },
        objective = { "132:1225718993:40902617", "Chef Breanna ที่ Lakeshire ต้องการ Tough Condor Meat ห้าชิ้น, Great Goretusk Snout ห้าชิ้น และ Crisp Spider Meat ห้าส่วน" },
        description = { "387:2081645877:240162034", "ข้ายินดีอย่างยิ่งทำกูลาช Redridge ให้เจ้า แต่มีปัญหานิดหน่อย ตอนออร์คลุกฮือข้าเลี้ยงทหาร Stormwind ทั้งกองพล ตอนนี้ตู้เสบียงว่าง หากหาวัตถุดิบให้ก็ยินดีทำ\n\nนำ Tough Condor Meat ห้าชิ้น, Great Goretusk Snout ห้าชิ้น และ Crisp Spider Meat ห้าส่วนมา" },
        progress = { "113:1790110053:984987076", "ยังต้องการ Tough Condor Meat ห้าชิ้น, Great Goretusk Snout ห้าชิ้น และ Crisp Spider Meat ห้าส่วน" },
        completion = { "11:534428891:784080240 N 89:147281360:88716877", "ทำได้ดี {name} ตัวอย่างดีงามด้วย! นี่อาหารอร่อยที่เรียกว่ากูลาช Redridge!" },
        required = { [2296] = { "20:1051371698:2021852390", "จมูกหมูป่า Goretusk ขนาดใหญ่" }, [1080] = { "17:1785139850:456872383", "เนื้อแร้งคอนดอร์เหนียว" }, [1081] = { "17:284079027:94470893", "เนื้อแมงมุมกรอบ" } },
        steps = { { "20:1051371698:2021852390", "จมูกหมูป่า Goretusk ขนาดใหญ่" }, { "17:1785139850:456872383", "เนื้อแร้งคอนดอร์เหนียว" }, { "17:284079027:94470893", "เนื้อแมงมุมกรอบ" } },
    },
    [94] = { -- A Watchful Eye
        title = { "14:700549068:1879833229", "ดวงตาเฝ้าระวัง" },
        objective = { "81:16974198:1434112517", "นำ Glyph of Azora ไปวางบน Lion Statue ใกล้ Tower of Ilgalar ใน Redridge" },
        description = { "449:1100925027:1270152926", "Morganth คู่แข่งข้าเป็นจอมเวทโหดร้ายทรงพลัง อยู่ Tower of Ilgalar ใน Redridge ข้าพัฒนาวิธีสอดแนมเรียก Eye of Azora ตอนนี้มองเขาจากไกลได้\n\nแต่หากศึกษาความคิด... ต้องให้ช่วยอีก\n\nหากยินดี นำ Glyph of Azora ไป Tower of Ilgalar วางบน Lion Statue ใกล้หอ\n\nเมื่อเสร็จ พลัง Azora จะเผยนิมิตแผนในอนาคตของ Morganth" },
        progress = { "189:484382474:308125075", "รูปสิงโตอยู่ที่นี่หลายสิบปี เฝ้าหอ Ilgalar อื้อฉาวอย่างโดดเดี่ยว\n\nฐานมีรอยเว้าที่น่าจะวางอัญมณีหรืออักขระได้..." },
        completion = { "146:1287611665:1541563200 N 135:889634255:906033281", "เจ้าวาง Glyph of Azora บนศิลา มันติดแน่น... แล้วเสียง Theocritus ดังออกมาอย่างไร้ร่าง\n\nข้าขอบใจเจ้า {name}ผู้เยาว์วัย ตอนนี้พูดกับข้าผ่านอักขระได้ ข้าอาจมีงานต่อไป... หลังเจาะความคิดคู่แข่งแล้ว" },
        required = { [1083] = { "14:1342497050:751002376", "อักขระแห่ง Azora" } },
        steps = { { "14:1342497050:751002376", "อักขระแห่ง Azora" } },
    },
    [115] = { -- Shadow Magic
        title = { "12:101537999:540117063", "เวทเงา" },
        objective = { "53:2007952837:1031668444", "นำ Midnight Orb 3 ลูกไปให้ Marshal Marris ที่ Lakeshire" },
        description = { "446:1075288695:608666254", "ออร์ค Blackrock เกณฑ์ผู้ร่ายเงาช่วยบุก Redridge พวกมันนำอุปกรณ์พลังมืด Midnight Orb มาด้วย ลูกแก้วทำร้ายผู้ป้องกัน Redridge อย่างหนัก จำเป็นต้องเอาของแปดเปื้อนปีศาจออกจากศึก\n\nหา Midnight Orb จากผู้ร่ายเงา Blackrock ที่ตายแล้วส่งให้ข้า ข้าจะสั่งกำจัด โลกคงดีกว่านี้หากไร้มัน!" },
        progress = { "78:447449237:214198630", "สู้ผู้ร่ายเงาเป็นอย่างไร? พบ Midnight Orb หรือยัง?" },
        completion = { "11:1191658970:1224418299 N 46:1952058841:1187460306", "ขอบใจ {name} ข้าจะส่งไปทำลายทันที" },
        required = { [1261] = { "12:562006984:383228966", "ลูกแก้วรัตติกาล" } },
        steps = { { "12:562006984:383228966", "ลูกแก้วรัตติกาล" } },
    },
    [116] = { -- Dry Times
        title = { "9:974272307:1272138160", "ยามขาดเหล้า" },
        objective = { "127:439781002:1814418983", "Barkeep Daniels ที่ Lakeshire ต้องการ Thunderbrew Lager หนึ่งถัง, Merlot หนึ่งถังเล็ก, Moonshine หนึ่งขวด และ Sweet Rum หนึ่งถุงหนัง" },
        description = { "37:1846786594:1321426325 N 420:1381497855:836895653", "ข้าลำบากแล้ว {name} ขวดเหล้าใกล้เกลี้ยง ของรอบล่าสุดเกินกำหนดมานาน ออร์คบุกทำเรื่องยุ่งเหมือนนรก\n\nเจ้ามาทำงานให้ข้าไหม?\n\nต้องการ Thunderbrew Lager หนึ่งถังจาก Grimbooze Thunderbrew ที่เนิน Westfall, Merlot หนึ่งถังเล็กจาก Stormwind, Moonshine หนึ่งขวดจาก Darkshire และ Sweet Rum หนึ่งถุงหนังจาก Goldshire นำกลับมาแล้วข้าจะให้รางวัล", variants = { { "37:1846786594:1321426325 N 462:1008704787:1938315314", "ข้าลำบากแล้ว {name} ขวดเหล้าใกล้เกลี้ยง ของรอบล่าสุดเกินกำหนดมานาน พวกออร์คบุกจนวุ่นวายไปหมด\n\nเจ้ามาทำงานให้ข้าได้ไหม?\n\nข้าต้องการ Merlot หนึ่งถังเล็กจาก Stormwind, Moonshine หนึ่งขวดจาก Darkshire, Sweet Rum หนึ่งถุงหนังจาก Goldshire และ Thunderbrew หนึ่งถังจาก Grimbooze เจ้าจะพบเขาที่ค่ายบน Dagger Hills ทางตอนใต้ของ Westfall นำทั้งหมดกลับมาให้ข้าแล้วข้าจะให้รางวัล" } } },
        progress = { "270:1150643384:185159827", "ต้องการ Thunderbrew Lager หนึ่งถังจาก Grimbooze Thunderbrew ที่เนิน Westfall, Merlot หนึ่งถังเล็กจาก Stormwind, Moonshine หนึ่งขวดจาก Darkshire และ Sweet Rum หนึ่งถุงหนังจาก Goldshire นำกลับมาแล้วข้าจะให้รางวัล" },
        completion = { "17:2049170433:170140679 N 215:839550926:1481163460", "ทำได้ดี {name}! ข้ารู้ดีว่าเส้นทางไปหาเหล้าชั้นดีชุดนี้เป็นอย่างไร แต่ลูกค้าจะมีความสุขอีกครั้ง!\n\nภรรยาข้าเป็นช่างเย็บฝีมือดี โปรดรับเสื้อคลุมที่นางทำตอบแทนงานเจ้า" },
        required = { [1262] = { "18:1500637766:1813821556", "ถังเบียร์ Thunderbrew" }, [1939] = { "17:1978379262:1130889105", "ถุงหนังใส่เหล้ารัมหวาน" }, [1941] = { "14:1068277840:1980077127", "ถังไวน์เมอร์โลต์" }, [1942] = { "19:1412976470:1493481073", "ขวดเหล้าเถื่อน" } },
        objectiveLabels = {
            item = { ["Keg of Thunderbrew"] = "ถังเบียร์ Thunderbrew", ["Skin of Sweet Rum"] = "ถุงหนังใส่เหล้ารัมหวาน", ["Cask of Merlot"] = "ถังไวน์เมอร์โลต์", ["Bottle of Moonshine"] = "ขวดเหล้าเถื่อน" },
        },
    },
    [118] = { -- The Price of Shoes
        title = { "18:1904984106:501478913", "ราคาของเกือกม้า" },
        objective = { "47:1671857026:818531919", "นำ Verner's Note ไปให้ Smith Argus ที่ Goldshire" },
        description = { "248:1712041368:172033784", "ข้าใช้เหล็กมากเพื่อให้องครักษ์ Stormwind มีอุปกรณ์ จนไม่พอทำเกือกให้ม้าในคอก!\n\nนำจดหมายนี้ให้ Blacksmith Argus ที่ Goldshire มันอธิบายปัญหาและขอให้ส่งเกือกม้า" },
        progress = { "75:767032950:636802167", "อะไรนะ? Verner ส่งเจ้ามาหรือ? ส่งจดหมายมา แล้วพูดดัง ๆ!" },
        completion = { "47:1071715878:476310382", "เฮะ Verner เฒ่าต้องการเกือกหรือ!?!" },
        required = { [1283] = { "13:594983385:978477346", "ข้อความของ Verner" } },
        steps = { { "13:594983385:978477346", "ข้อความของ Verner" } },
    },
    [119] = { -- Return to Verner
        title = { "16:1663352642:569354956", "กลับไปหา Verner" },
        objective = { "70:1173604542:1334854739", "กลับไปหา Verner Osgood ที่ Redridge แล้วมอบ Crate of Horseshoes ให้เขา" },
        description = { "183:314354610:1052335305", "ตกลง ข้าจะให้เกือกม้า 50 อัน...\n\nนี่ บรรจุกล่องพร้อมไป! บอก Verner ว่ายินดีค้าขาย และให้เขาอ่านจดหมายที่ติดลังด้วย!" },
        progress = { "42:1617100129:466154299", "ดี กลับมาแล้ว! ได้เกือกไหม?" },
        completion = { "134:833894535:1592358264 N 26:443513355:46617783", "ขอบใจ ช่วยได้มาก\n\nแต่อะไรนี่? Argus ส่งจดหมายมากับลัง... อะไรนะ?? จะให้ข้าจ่ายเงิน? เฮอะ!\n\nเอาล่ะ {name} ขอบใจที่ช่วย" },
        required = { [1284] = { "19:687443917:1741890963", "ลังบรรจุเกือกม้า" } },
        steps = { { "19:687443917:1741890963", "ลังบรรจุเกือกม้า" } },
    },
    [120] = { -- Messenger to Stormwind
        title = { "22:1870890892:752937510", "ผู้ส่งสารสู่ Stormwind" },
        objective = { "182:417009428:1290566873", "Magistrate Solomon มอบรายงานให้ส่งแก่ General Marcus Jonathan ที่ Stormwind และต้องการให้เจ้ากลับไปหาทันทีหลังส่งแล้ว" },
        description = { "24:390410401:1819650924 C 320:425558724:779230775", "ช่วงนี้ยากลำบาก {class} เมืองถูกล้อมตลอด หากไม่มีกำลังเสริมคงพ่ายแน่ สารที่ฝากสำคัญที่สุด ส่งรายงานให้ General Marcus Jonathan แห่ง Stormwind ทันที แล้วกลับมาแจ้งข่าวไม่ว่าดีหรือร้าย\n\nรีบไปเถอะ!" },
        progress = { "20:2114236962:372887303", "มีอะไรนั่น?" },
        completion = { "9:612618706:1153568520 C 286:973873702:2038386493", "ตามสบาย {class}\n\nMagistrate Solomon เป็นผู้นำสูงศักดิ์ คำเขามีน้ำหนักกับข้า ข้าจะปรึกษากษัตริย์และอธิบายสถานการณ์ บอกท่านผู้พิพากษาว่ากองทัพ Stormwind สนับสนุน จะส่งกำลังเสริมทันทีที่พระราชารับสั่ง" },
        required = { [1293] = { "22:1506813767:564448795", "รายงานสถานการณ์ Lakeshire" } },
        steps = { { "22:1506813767:564448795", "รายงานสถานการณ์ Lakeshire" } },
    },
    [121] = { -- Messenger to Stormwind
        title = { "22:1870890892:752937510", "ผู้ส่งสารสู่ Stormwind" },
        objective = { "85:1132133334:1521797206", "นำจดหมายตอบของ General Marcus Jonathan ไปให้ Magistrate Solomon ที่ Lakeshire" },
        description = { "108:1955314872:1811458227 C 1:33:33", "ระหว่างรอคำตอบกษัตริย์ ข้าต้องการให้นำจดหมายนี้ให้ Magistrate Solomon\n\nไปได้ {class}!" },
        progress = { "57:1007405805:850238667", "ท่านนายพลมีข่าวไหม? กำลังเสริมมาหรือยัง?" },
        completion = { "25:488472212:1898712033 C 241:1615082424:1230591290", "ขอบใจที่สละเวลา {class} ข้าให้เหรียญตอบแทนการรับใช้ Lakeshire และ Stormwind\n\nขอตัวก่อน จดหมายนี้ดูเป็นปริศนา มีบางอย่างผิดปกติในอาณาจักร ข้ากลัวว่านี่คือจุดเริ่มความขัดแย้ง ไม่ใช่จุดจบ" },
        required = { [1294] = { "22:1825530329:368523498", "คำตอบของนายพล" } },
        steps = { { "22:1825530329:368523498", "คำตอบของนายพล" } },
    },
    [122] = { -- Underbelly Scales
        title = { "17:688419501:569217538", "เกล็ดใต้ท้อง" },
        objective = { "103:880279538:38428846", "รวบรวม Underbelly Whelp Scale 6 ชิ้นจาก Black Dragon Whelp แล้วนำไปให้ Verner Osgood ที่ Redridge" },
        description = { "384:1507899791:1480564500", "ข้าต้องใช้เกล็ดใต้ท้องลูกมังกรดำจ่ายค่าเกือกที่ Argus ส่งจาก Goldshire หากหาได้ 6 ชิ้น ข้าจะจ่ายส่วนหนึ่งให้เขา และเหลือพอทำอะไรให้เจ้า\n\nลูกมังกรดำมักบินทางใต้ Lakeshire แต่ชอบเร่ร่อน เจ้าอาจต้องคอยมองแล้วล่าเมื่อเห็น" },
        progress = { "131:1356566504:1977114066", "รู้ว่า Argus โลภคงส่งคนมาทวงเกล็ดหากไม่ให้เร็ว ๆ ได้เกล็ดหรือยัง?" },
        completion = { "49:578215546:1042743569", "ขอบใจ! นี่จะทำให้ข้าพ้นหนี้ Argus..." },
        required = { [1221] = { "22:1696887552:1262179239", "เกล็ดใต้ท้องลูกมังกร" } },
        steps = { { "22:1696887552:1262179239", "เกล็ดใต้ท้องลูกมังกร" } },
    },
    [124] = { -- A Baying of Gnolls
        title = { "18:1651660439:970842059", "เสียงเห่าหอนของนอลล์" },
        objective = { "77:85568466:673352614", "สังหาร Redridge Brute 10 ตัวและ Redridge Mystic 8 ตัว แล้วกลับไปหา Verner Osgood" },
        description = { "233:2144363126:1833509514", "ออร์คบุกยังไม่พอหรือ! ตอนนี้นอลล์จอมโหดกับผู้ใช้เวทเดินตามสันเขาเหนือคอก จับม้าที่หลงไป...\n\nหากกำจัดได้ ข้ากับม้าจะขอบใจมาก" },
        progress = { "87:1748467753:1324875561 N 34:1634944347:936382253", "ม้ายังตื่นกลัว ข้ายังได้ยินเสียงหอนบัดซบยามค่ำ ได้โปรด {name} ทำอะไรกับนอลล์ที!" },
        completion = { "29:1597532656:743392282 N 1:46:46", "ขอบใจสำหรับความช่วยเหลือทั้งหมด {name}" },
        objectiveLabels = {
            monster = { ["Redridge Brute slain"] = "ปราบ อันธพาล Redridge", ["Redridge Mystic slain"] = "ปราบ นักเวทลี้ลับ Redridge" },
        },
    },
    [125] = { -- The Lost Tools
        title = { "14:1143921439:224815154", "เครื่องมือที่หายไป" },
        objective = { "95:559131906:1453359819", "Foreman Oslow ที่ Lakeshire ต้องการให้เจ้านำกล่องเครื่องมือของเขาจากก้น Lake Everstill กลับมา" },
        description = { "32:1937650681:2122314874 N 293:1767603460:240986401 N 36:1624660845:56415492", "ข้าต้องการคนช่วยจริง ๆ {name} เมืองถูกล้อมจึงหาของยาก เครื่องมือส่งเกวียนจาก Goldshire แต่สะพานถูกระเบิด เราใส่เรือ ออร์คกลับยิงเครื่องดีดหินใส่ โชคร้ายจริง กล่องเครื่องมือจมก้นทะเลสาบ\n\nนำกลับมา {name} ข้าจะตอบแทนให้คุ้ม" },
        progress = { "31:362200376:869709262", "หาเครื่องมือข้าเจอไหม?" },
        completion = { "20:964294936:1579032551 N 44:1486797298:1046717405", "กู้ได้ยอดเยี่ยม {name}! ไม่คิดว่าจะเห็นเครื่องมืออีกแล้ว" },
        required = { [1309] = { "15:282727351:689962028", "กล่องเครื่องมือของ Oslow" } },
        steps = { { "15:282727351:689962028", "กล่องเครื่องมือของ Oslow" } },
    },
    [126] = { -- Howling in the Hills
        title = { "20:1045476219:1809537002", "เสียงหอนบนเนินเขา" },
        objective = { "49:953871999:170015016", "นำ Yowler's Paw ไปให้ Verner Osgood ที่ Lakeshire" },
        description = { "N 306:1974203799:81733120", "{name} นอลล์ยังอยู่ ข้าได้ยินมันหอนล่าบนเนินเหนือ Lakeshire เสียงหนึ่งดังกว่าทุกตัว คือ Yowler ผู้นำ\n\nสังหาร Yowler ให้ฝูงแตก! นำอุ้งเท้าเป็นหลักฐาน\n\nระวังด้วย ที่เป็นผู้นำต้องมีเหตุผล มันไม่ใช่ Mongrel ธรรมดา..." },
        progress = { "32:1111171774:2054322514 N 44:153667967:1404429475", "Yowler อันตราย {name} หากยังไม่พร้อม ข้าเข้าใจ" },
        completion = { "167:1802640459:1340041759", "ขอบใจอีกครั้ง กองทัพ Stormwind ยุ่งรับมือออร์คจนไม่มีกำลังป้องกัน Redridge จากภัยท้องถิ่นอย่างนอลล์" },
        required = { [3614] = { "12:1927408891:1923055992", "อุ้งเท้าของ Yowler" } },
        steps = { { "12:1927408891:1923055992", "อุ้งเท้าของ Yowler" } },
    },
    [127] = { -- Selling Fish
        title = { "12:754465148:375169788", "ขายปลา" },
        objective = { "58:926064013:1811106726", "นำ Spotted Sunfish 10 ตัวไปให้ Dockmaster Baren ที่ Lakeshire" },
        description = { "232:1296452229:984704566", "Lake Everstill ขึ้นชื่อ Spotted Sunfish คนต้องการเสมอ... แต่ของข้าใกล้หมด!\n\nนำมา 10 ตัว ข้าจะแลกให้อย่างงาม หากตกปลาไม่เป็น... บางทีเอาจากเมอร์ล็อกได้!" },
        progress = { "33:330273603:589918605", "มีปลาซันฟิชให้ข้าหรือ?" },
        completion = { "40:601490623:456027761", "ยินดีค้าขาย สหาย!" },
        required = { [1467] = { "15:515975738:1512062460", "ปลาซันฟิชลายจุด" } },
        steps = { { "15:515975738:1512062460", "ปลาซันฟิชลายจุด" } },
    },
    [128] = { -- Blackrock Bounty
        title = { "16:1692374407:660755546", "ค่าหัว Blackrock" },
        objective = { "72:229990248:288412136", "สังหาร Blackrock Champion 15 คน แล้ว Guard Howe ที่ Lakeshire จะให้รางวัล" },
        description = { "425:1027395525:1502582550", "ต้องทำลายเผ่า Blackrock ศัตรูรุกรานแผ่นดินเรา ภูเขาเหล่านี้อยู่ใต้อธิปไตยกษัตริย์ Stormwind ข่าวระบุว่าหัวหน้าหน่วยในเผ่าเรียก Champion พบได้ที่ค่ายเหนือ ทางตะวันตกของถนนไป Burning Steppes\n\nMagistrate Solomon ต้องการให้พวกชั่วตาย กำจัด Blackrock Champion 15 คนแล้วกลับมา" },
        progress = { "50:1696800038:1971100076", "กลับมาเมื่อสังหาร Blackrock Champion 15 คนแล้ว" },
        completion = { "60:420429974:1002642273 C 47:1934464873:1099929655", "ข้าเห็นว่าเจ้าสู้อย่างกล้าหาญกับ Blackrock {class} เจ้ารับใช้เมืองเราอย่างยิ่ง" },
        objectiveLabels = {
            monster = { ["Blackrock Champion slain"] = "ปราบ นักรบยอดฝีมือ Blackrock" },
        },
    },
    [129] = { -- A Free Lunch
        title = { "12:1307696923:1474332130", "อาหารกลางวันฟรี" },
        objective = { "79:565083303:1431581655", "นำอาหารกลางวันของ Parker ไปให้ Guard Parker ที่ลาดตระเวนถนนไป Darkshire" },
        description = { "355:2071650252:1053871578", "ช่วยหน่อยได้ไหม? ข้าเตรียมอาหารให้ Guard Parker แต่เขาออกลาดตระเวน... เป็นยาม Stormwind ตัวใหญ่แข็งแรง ป้องกันตนได้ แต่ข้างนอกอันตรายเกินชาวเมืองอย่างข้า\n\nหากนำอาหารไปแล้วกลับมา ข้าจะให้อาหารกลางวันฟรี! Parker ลาดตระเวนถนนช่วงไป Duskwood" },
        progress = { "80:1143362767:1146547852", "Darcy ส่งอาหารให้ข้าหรือ? นางใจดีจริง เอาล่ะ... ส่งมาสิ!" },
        completion = { "95:1447140922:836875109", "ขอบใจ ข้าต้องการอาหารพอดี ป้องกัน Lakeshire จากออร์คกับนอลล์งานหนักนัก!" },
        required = { [5534] = { "14:1726460998:1265642203", "มื้อกลางวันของ Parker" } },
        objectiveLabels = {
            item = { ["Parker's Lunch"] = "มื้อกลางวันของ Parker" },
        },
    },
    [130] = { -- Visit the Herbalist
        title = { "19:53804677:1327187020", "ไปพบนักสมุนไพร" },
        objective = { "51:2074279212:671722405", "คุยกับ Martie Jainrose นักสมุนไพรแห่ง Redridge" },
        description = { "257:756877004:978751515", "ก่อนกลับ Darcy นำดอกไม้ไปให้นางแทนข้าได้ไหม? หาได้ร้านสมุนไพรฝั่งตะวันตก Lakeshire\n\nแต่เมื่อได้ดอกไม้... อย่าบอก Martie ว่าใครส่ง หรือส่งให้ใคร..." },
        completion = { "236:1469034752:1666024125", "ต้องการช่อดอกไม้หรือ? มาเมืองไม่นาน... พบคนรักแล้วหรือ?\n\nรู้ว่าไม่ควรสอด แต่ดีที่เห็นความรักเบ่งบาน... โดยเฉพาะยามอันตรายเช่นนี้" },
    },
    [131] = { -- Delivering Daffodils
        title = { "20:668843802:1609325188", "ส่งแดฟโฟดิล" },
        objective = { "32:644595180:497989312", "มอบ Daffodil Bouquet ให้ Darcy" },
        description = { "69:1408987672:1863117427", "นี่ช่อดอกไม้ ข้าเลือกแดฟโฟดิลให้ ชอบที่สุดเลย!" },
        progress = { "13:1366380142:1891123769 N 39:368886580:1302031579", "สวัสดีอีกครั้ง {name} Parker ชอบอาหารที่ข้าส่งไหม?" },
        completion = { "351:257520885:2075809093", "โอ้ สวยมาก! อยากใส่น้ำเร็ว ๆ!\n\nแต่... นี่ดอกโปรด Martie Parker คงไม่ได้ให้ไปหายัยเจ้าเล่ห์ขี้หึงนั่นใช่ไหม? ไม่ได้บอกว่าให้ใครใช่หรือเปล่า? ถ้าบอก ข้าคงไม่แปลกใจหากนางใส่พิษ\n\nโอ้ แต่ไม่ใช่ความผิดเจ้า ขอบใจ นี่อาหารของเจ้า" },
        required = { [1325] = { "16:626307737:600878848", "ช่อดอกแดฟโฟดิล" } },
        steps = { { "16:626307737:600878848", "ช่อดอกแดฟโฟดิล" } },
    },
    [143] = { -- Messenger to Westfall
        title = { "21:1179608349:1313478666", "ผู้ส่งสารสู่ Westfall" },
        objective = { "87:628531712:1266482148", "Magistrate Solomon ต้องการให้นำคำวิงวอนเป็นลายลักษณ์อักษรไปให้ Gryan Stoutmantle ที่ Westfall" },
        description = { "433:1716677024:1225155049", "กองทัพ Stormwind มีเรื่องแปลก ป่านนี้ควรมากันเต็มกำลังแล้ว แต่เราไม่มีเวลารอ ข้าไม่ยืนดูชาว Lakeshire สละชีวิตโดยไม่พยายามขอแรงเพิ่ม ได้ยินว่า Westfall กำลังตั้งกองกำลังประชาชน\n\nนำคำวิงวอนให้ Gryan Stoutmantle ผู้นำ บางทีคนของเขาช่วยค้ำจุนจนกษัตริย์ส่งกำลังสำรองได้" },
        progress = { "6:1136836709:1914036474 C 54:1869423993:884133019", "สวัสดี {class} มีธุระอะไรกับ People's Militia?" },
        completion = { "49:701195016:2038494166", "ผู้ส่งสารที่ดี เจ้ารับใช้เจ้านายได้ดีแล้ว" },
        required = { [1407] = { "26:38319663:890003018", "คำขอความช่วยเหลือจาก Solomon ถึง Westfall" } },
        steps = { { "26:38319663:890003018", "คำขอความช่วยเหลือจาก Solomon ถึง Westfall" } },
    },
    [144] = { -- Messenger to Westfall
        title = { "21:1179608349:1313478666", "ผู้ส่งสารสู่ Westfall" },
        objective = { "63:1888398285:808943311", "กลับไปหา Magistrate Solomon พร้อมคำตอบของ Gryan Stoutmantle" },
        description = { "309:873055590:424756626 C 68:1612755684:1662629959", "อ่านจดหมาย Magistrate Solomon แล้วปวดใจ แต่ชัดว่าไม่รู้ศึกใน Westfall ไม่เช่นนั้นคงไม่หวังแรง Militia หาก Stormwind ไม่ทอดทิ้งเราด้วย คงไม่ต้องตั้งกองกำลังนี้\n\nนำคำตอบให้เจ้านายที่ Redridge {class} บอกว่าข้าหนักใจกับการเสียคนดี" },
        progress = { "82:158776333:1600910072", "จะได้พบ People's Militia เร็ว ๆ นี้หรือ? ข่าว Lord Stoutmantle เป็นลางดีไหม?" },
        completion = { "346:2103695390:1795838498", "ต้องบอกว่าแย่มาก ไม่รู้ว่า Stoutmantle ตกสถานการณ์ไม่ต่าง Lakeshire งานใดสำคัญจนกองทัพ Stormwind ต้องจากประชาชน? เฮอะ ไม่ควรคิดดัง ๆ\n\nนี่ ผู้ส่งสาร รับเหรียญตอบแทนการรับใช้เมือง ข้าอาจเรียกใช้อีก" },
        required = { [1408] = { "33:755420920:802399889", "คำตอบของ Stoutmantle ถึง Solomon" } },
        objectiveLabels = {
            item = { ["Stoutmantle's Response to Solomon"] = "คำตอบของ Stoutmantle ถึง Solomon" },
        },
    },
    [145] = { -- Messenger to Darkshire
        title = { "22:1876411090:1214849823", "ผู้ส่งสารสู่ Darkshire" },
        objective = { "77:992852034:128951952", "Magistrate Solomon ต้องการให้นำจดหมายไปให้ Lord Ebonlocke ที่ Darkshire" },
        description = { "349:437794372:738948769", "ต้องให้ช่วยอีกครั้ง ข้าเขียนถึง Lord Ebonlocke ขอส่งยาม Night Watch ที่ฝึกแล้วมาป้องกัน Lakeshire สารต้องถึงโดยเร็ว เจ้าต้องระวังอย่างยิ่ง Ebonlocke เป็นนายกเทศมนตรี Darkshire ใจกลาง Duskwood อย่าออกนอกถนน" },
        progress = { "39:549839666:1796373787 C 46:447366280:1873429096", "ดูเดินทางมาไกล {class} มีธุระอะไรที่ Darkshire?" },
        completion = { "81:329137522:287860670", "ขอบใจที่เดินทางไกล นี่เป็นข้อมูลสำคัญจริง ๆ" },
        required = { [1409] = { "27:622994780:1574114289", "คำขอความช่วยเหลือจาก Solomon ถึง Darkshire" } },
        steps = { { "27:622994780:1574114289", "คำขอความช่วยเหลือจาก Solomon ถึง Darkshire" } },
    },
    [146] = { -- Messenger to Darkshire
        title = { "22:1876411090:1214849823", "ผู้ส่งสารสู่ Darkshire" },
        objective = { "70:1555348417:1368468120", "กลับไปหา Magistrate Solomon พร้อมจดหมายตอบของ Lord Ebonlocke" },
        description = { "412:126806251:1757630792", "หากไม่รู้จัก Magistrate Solomon เป็นการส่วนตัว ข้าคงว่าเขาบ้า ส่ง Night Watch ไป Lakeshire เพราะ Stormwind ไม่ช่วยหรือ? เราตั้ง Night Watch เพราะ Stormwind ทิ้งเราเมื่อเวทชั่วซึมแผ่นดิน หากส่งไป เมืองจะถูกความชั่วยึดก่อนยามถึงชายป่าด้วยซ้ำ\n\nนำจดหมายตอบให้เจ้านายที่ Lakeshire" },
        progress = { "114:556403823:2046054471", "อา ดีที่กลับมา ผู้ส่งสาร ให้ข้าแจ้ง Marshal ไหมว่า Night Watch กำลังมาจาก Darkshire?" },
        completion = { "192:486487548:519554507 C 105:414444717:911370808", "ด้วยแสงสว่าง! กองทัพ Stormwind ถอนจาก Westfall และยามไม่คุ้มครอง Darkshire แล้ว? มีการทรยศแน่ เป็นเช่นนี้ได้อย่างไร?\n\nอ้อ ลืมตอบแทนงาน {class} นี่เหรียญ ขอตัวก่อน มีอะไรผิดปกติใน Stormwind ข้าต้องสืบให้ถึงที่สุด" },
        required = { [1410] = { "31:387534255:2131875171", "คำตอบของ Ebonlocke ถึง Solomon" } },
        steps = { { "31:387534255:2131875171", "คำตอบของ Ebonlocke ถึง Solomon" } },
    },
    [150] = { -- Murloc Poachers
        title = { "15:868076266:2060831016", "เมอร์ล็อกลักลอบจับปลา" },
        objective = { "53:182587098:1950931784", "นำ Murloc Fin 8 ชิ้นไปให้ Dockmaster Baren ที่ Lakeshire" },
        description = { "280:197894802:561758718", "เมอร์ล็อกเริ่มเป็นปัญหา พวกมนุษย์ปลากลุ่มใหญ่ขึ้นมาปักหลักริม Lake Everstill ตกปลากันไม่หยุด! ต้องไล่ก่อนกินปลาหมดทะเลสาบ!\n\nล่าเมอร์ล็อก! นำครีบแปดชิ้นมา ข้าอาจมีของให้..." },
        progress = { "74:1417219919:235139604", "ได้ครีบไหม? รีบหน่อย เราต้องไล่เมอร์ล็อกจากทะเลสาบ!" },
        completion = { "11:534428891:784080240 N 174:2008105147:1021188004", "ทำได้ดี {name} หวังว่าเมอร์ล็อกไม่สร้างปัญหามากนัก\n\nแปลกที่เห็นมันไกลทะเลขนาดนี้ สงสัยว่าหนีอะไรมา..." },
        required = { [1468] = { "10:1115336429:723077626", "ครีบเมอร์ล็อก" } },
        steps = { { "10:1115336429:723077626", "ครีบเมอร์ล็อก" } },
    },
    [169] = { -- WANTED: Gath'Ilzogg
        title = { "19:1957337631:1060052656", "ประกาศจับ: Gath'Ilzogg" },
        objective = { "86:642494443:1691811402", "สังหาร Gath'Ilzogg แล้วนำศีรษะไปให้ Magistrate Solomon ที่ Lakeshire เพื่อรับรางวัล" },
        description = { "436:782280423:1155367452", "ประกาศจับ! Gath'Ilzogg ผู้นำ Blackrock บุก Stonewatch Keep และโจมตี Lakeshire\n\nGath'Ilzogg อันตรายอย่างยิ่ง ข่าวว่าอยู่ในป้อมเพิ่งยึด วางแผนอาชญากรรมต่อมนุษยชาติเพิ่ม ต้องปราบออร์ครุกรานทุกวิถี ผู้กล้านำศีรษะ Gath'Ilzogg ให้ Magistrate Solomon จะได้รางวัลงาม" },
        progress = { "24:316066776:86638779 R 1:63:63", "มีอะไรนั่น {race}?" },
        completion = { "16:940017130:880912851 N 170:793506559:507858589", "ยอดเยี่ยม {name}! Gath'Ilzogg นำพวกโหดเข้าสู้ ฆ่ามนุษย์บริสุทธิ์มากมาย เราทวงความเป็นธรรมได้แล้ว นี่ก้าวแรกของการยึดป้อมคืนสู่อาณาจักร Stormwind!" },
        required = { [3633] = { "19:1272672749:707725593", "ศีรษะของ Gath'Ilzogg" } },
        steps = { { "19:1272672749:707725593", "ศีรษะของ Gath'Ilzogg" } },
    },
    [178] = { -- Theocritus' Retrieval
        title = { "21:1403360172:1019551771", "ของที่ Theocritus ต้องการ" },
        objective = { "58:309728545:856681618", "นำ Faded Shadowhide Pendant ไปให้ Theocritus the Mage" },
        description = { "431:61312132:1565007732", "<เจ้าได้ยินเสียงไร้ร่าง...>\n\nอย่าตกใจ ข้าคือ Theocritus จอมเวทใหญ่แห่ง Tower Azora ใน Elwynn Forest จี้ที่ถือเป็นเครื่องสื่อสารระหว่าง Shadowhide Gnoll กับนาย Morganth\n\nหลังค้นคว้าหลายเดือน ข้าเชื่อว่าพูดผ่านจี้ได้ด้วย หากได้ยินสารนี้ เวทข้าก็สำเร็จ\n\nนำจี้ให้ข้า ข้าจะตอบแทนงานเจ้า" },
        progress = { "89:1259616082:1460161144", "เจ้าว่าข้าพูดผ่านจี้หรือ? อืม... ส่งมาให้ศึกษาที" },
        completion = { "23:693450116:939511761 N 369:2030054439:563529675", "ขอบใจ {name} ข้าส่งสารไป Shadowhide Pendant หลายสัปดาห์ก่อน คิดว่าล้มเหลวแล้ว แต่เวทถึงจี้บางชิ้นจริง แม้ล่าช้ามาก\n\nต่อไปข้าหวังเรียนรู้วิธีส่งการโจมตีผ่านจี้ เพื่อตรึง Shadowhide Gnoll ที่สวม\n\nแต่ก่อนทำได้ เกรงว่าต้องค้นคว้าอีกมาก" },
        required = { [1956] = { "24:1708213749:644382807", "จี้ Shadowhide ที่สีซีด" } },
        steps = { { "24:1708213749:644382807", "จี้ Shadowhide ที่สีซีด" } },
    },
    [180] = { -- WANTED: Lieutenant Fangore
        title = { "26:1426446758:759885961", "ประกาศจับ: Lieutenant Fangore" },
        objective = { "83:1222292614:686820313", "สังหาร Lieutenant Fangore แล้วนำอุ้งเท้ากลับไปให้ Magistrate Solomon ที่ Lakeshire" },
        description = { "268:1154254931:1060447100", "ประกาศจับ: Lieutenant Fangore\n\nรู้กันว่าเป็นหัวหน้าเผ่า Shadowhide Gnoll ทำงานใต้ Morganth ศัตรูเมืองและอาณาจักร ตามคำสั่ง Magistrate Solomon ผู้ทรยศชั่วต่อ Stormwind นี้ถูกหมายหัวให้ตาย แสดงอุ้งเท้าแก่ผู้พิพากษาเป็นหลักฐาน" },
        progress = { "40:150309082:1757108732", "นำข่าวใดมาแจ้งศาล?" },
        completion = { "97:1536190435:748865383 C 52:87949567:469331849", "Lieutenant Fangore ชั่วตายแล้วหรือ? พ้นจากสัตว์ร้ายนั่นเสียได้ เจ้ากล้ามาก {class} เมือง Lakeshire ขอบใจที่ช่วย" },
        required = { [3632] = { "13:963877186:1599814473", "อุ้งเท้าของ Fangore" } },
        steps = { { "13:963877186:1599814473", "อุ้งเท้าของ Fangore" } },
    },
    [219] = { -- Missing In Action
        title = { "17:944352885:1821989257", "หายไประหว่างปฏิบัติหน้าที่" },
        objective = { "57:1488787856:1803774318", "ปกป้อง Corporal Keeshan ระหว่างเดินทางกลับ Redridge" },
        description = { "339:1992944332:915666198", "ในที่สุดก็พบมิตร Alliance!\n\nช่วย... ได้โปรด...\n\nสุดท้ายที่จำได้ ออร์คชั่วโจมตีกองทหารเราจนพ่าย คนส่วนใหญ่ตาย ข้าถูกตีหัวแรงจนมืดไป ตอนนี้ถูกขังในถ้ำ ช่วยด้วย ข้าบาดเจ็บหนัก\n\nต้องมีคนช่วยกลับเมือง... ได้โปรด... เจ้าเป็นหวังสุดท้าย..." },
        progress = { "4:1517439344:201828488", "ว่าอย่างไร?" },
        completion = { "34:1965439315:1199855428 C 145:120148995:1729902963", "เจ้ารับใช้อาณาจักรได้ดี {class} ขอบใจที่ช่วย Corporal Keeshan หนีออร์ค Blackrock น่ากลัว วันนี้ความกล้าของเจ้าจะได้รับรางวัล" },
        objectiveLabels = {
            event = { ["Escort Corporal Keeshan back to Redridge"] = "คุ้มกัน Corporal Keeshan กลับไปยัง Redridge" },
        },
    },
    [244] = { -- Encroaching Gnolls
        title = { "18:113128690:805572225", "นอลล์รุกล้ำ" },
        objective = { "24:920603856:632549750", "รายงานตัวกับ Deputy Feldon" },
        description = { "6:1136836709:1914036474 C 386:1349247656:961333788", "สวัสดี {class} ข้ารับหน้าที่ลาดตระเวนถนนช่วงนี้ แม้ตอนนี้ปลอดภัย แต่เห็นค่ายนอลล์ทางเหนือและตะวันออก\n\nLakeshire ต้องรู้ว่ากำลังนอลล์รวมตัว! รายงาน Deputy Feldon ใน Lakeshire เรื่องนอลล์ ทำแล้วข้ามั่นใจว่าเขาจะให้ค่าจ้างหน่วยสอดแนม\n\nFeldon มักตรวจพื้นที่ใต้สะพานเข้า Lakeshire" },
        completion = { "284:24283783:2078797906", "มี Redridge Gnoll ใกล้ Elwynn ขนาดนั้นหรือ?? อาจพร้อมบุกบ้านเรา อีกไม่นานชาว Lakeshire อาจไม่ใช่มนุษย์กลุ่มเดียวที่ถูกล้อม!\n\nนี่ค่าจ้าง แม้นำข่าวร้าย มันมาในยามไม่ดี เพราะเราไม่พร้อมรับมือ" },
    },
    [246] = { -- Assessing the Threat
        title = { "20:1307564745:1876038397", "ประเมินภัยคุกคาม" },
        objective = { "98:273185820:2013962501", "สังหาร Redridge Mongrel 10 ตัวและ Redridge Poacher 6 ตัว แล้วกลับไปรายงาน Deputy Feldon ที่ Lakeshire" },
        description = { "365:2084164888:1550968777 N 27:333588092:1772472816", "เราไม่มีกำลังเหลือ แต่ต้องจัดการนอลล์ที่เจ้ารายงาน\n\nสอดแนม Redridge ตอนใต้ ก่อกวนและสังหารเท่าที่ทำได้ แล้วรายงานจำนวนกับระดับภัย อาจพบค่ายตามถนนใต้ Redridge\n\nทำเพื่อกองทัพ Stormwind {name} แล้วเจ้าจะได้รางวัล" },
        progress = { "11:1642759304:615714204 N 121:1117027446:408459550", "ขอโทษ {name} เรามีงานรัดตัวมาก หากไม่มีอะไรจะรายงาน ข้าต้องคิดเรื่องอื่น" },
        completion = { "217:1245468781:377970570 N 218:82452724:1720557530", "<Deputy Feldon ฟังรายงาน...>\n\nกำลังนอลล์ตั้งค่ายมากทีเดียว และจากที่เล่าพวกมันแข็งแกร่ง คงเก็บข่าวนี้ไม่ง่าย\n\nนี่ {name} เราขอบใจที่ช่วย\n\nหากยังไม่ได้คุย จงไปหา Marshal Marris และ Magistrate Solomon ใน Lakeshire สถานการณ์สิ้นหวังขึ้นเรื่อย ๆ สองคนนั้นคงต้องการเจ้าแน่" },
        objectiveLabels = {
            monster = { ["Redridge Mongrel slain"] = "ปราบ ตัวพันธุ์ผสม Redridge", ["Redridge Poacher slain"] = "ปราบ นักล่าสัตว์เถื่อน Redridge" },
        },
    },
    [248] = { -- Looking Further
        title = { "15:1694275532:1437126599", "มองให้ไกลกว่าเดิม" },
        objective = { "107:1482852697:846861564", "ขึ้นหอเฝ้าระวังที่ยังสมบูรณ์ข้าง Stonewatch Keep\n\nหาภาชนะเหมาะสมเพื่อวาง Glyph of Azora" },
        description = { "459:1526769211:511360312", "ข้าเฝ้า Tower of Ilgalar และรู้ว่า Morganth ขัดแย้งกับออร์คใน Stonewatch Keep ยังไม่รู้เหตุ แต่เจ้าช่วยไขปริศนาได้\n\nรับ Glyph of Azora อีกชิ้น ขึ้นยอดหอเฝ้าระวังที่ยังสมบูรณ์ข้าง Stonewatch Keep\n\nหาของเหมาะวางอักขระ หีบหรือเหยือก ที่ใดก็ตามที่ไม่สะดุดตา ก็ตรงเป้าข้า" },
        progress = { "97:645061722:1521829321", "เหยือกนี้เคยใส่เหล้ากลิ่นเหม็น แต่ตอนนี้ว่างและถูกลืมอยู่บนถังสองใบ" },
        completion = { "115:1087295052:324379054", "เป็นภาชนะเหมาะกับ Glyph of Azora ให้ Theocritus เจาะจิตผู้ที่อยู่ใน Stonewatch Keep" },
        required = { [1083] = { "14:1342497050:751002376", "อักขระแห่ง Azora" } },
        steps = { { "14:1342497050:751002376", "อักขระแห่ง Azora" } },
    },
    [249] = { -- Morganth
        title = { "8:1483924166:2084920686", "Morganth" },
        objective = { "98:42329527:1119381786", "ปราบ Morganth\n\nนำ Pendant of Shadow ของเขาไปให้ Theocritus ที่ Tower of Azora ใน Elwynn Forest" },
        description = { "462:2142233330:1731192380", "หลังเฝ้าสังเกตมากมาย ข้าค้นพบแผน Morganth แล้ว\n\nเขาหา Scythe of Elune... และอาจพบแล้ว! หากจริง Redridge Mountains กับอาณาจักร Stormwind จะรู้ซึ้งพลังมืดเขาในไม่ช้า\n\nข้าไม่พร้อมสู้ Morganth แต่กลัวว่าต้องจัดการตอนนี้ เจ้าจึงต้องเข้า Tower of Ilgalar เผชิญเขา\n\nปราบแล้วนำ Pendant of Shadow ให้ข้า ทำสำเร็จอาณาจักรจะติดหนี้เจ้ามาก" },
        progress = { "7:2044825444:644190917 N 64:1753947060:746019865", "รีบเถอะ {name} ก่อนความกลัวว่า Morganth แพร่พลังจะเป็นจริง!" },
        completion = { "20:1921578502:569519135 N 256:1802096558:869985720", "ทำได้ดี {name} การปราบวอร์ล็อก Morganth ช่วย Stormwind พ้นภัยใหญ่หลวง\n\nข้ามอบรางวัลอย่างถ่อมตน หากยามนี้สงบก็คงอวยพรให้สันติ\n\nแต่ขออวยพรให้โชคดีในการทดสอบ และชนะศึกเบื้องหน้าแทน" },
        required = { [3617] = { "17:1471678339:2101010842", "จี้แห่งเงา" } },
        steps = { { "17:1471678339:2101010842", "จี้แห่งเงา" } },
    },
    [3741] = { -- Hilary's Necklace
        title = { "17:1721175244:1081352461", "สร้อยของ Hilary" },
        objective = { "61:840776933:1986457419", "หา Hilary's Necklace แล้วนำกลับไปให้ Hilary ที่ Lakeshire" },
        description = { "377:1436599588:1522454156", "Hilary เพื่อนข้าทำสร้อยหาย หาไม่พบ เราตกปลาตรงนี้ทั้งวันและหาทั่วแล้ว คิดได้แค่ว่าตกทะเลสาบ พ่อแม่ไม่ให้ว่ายน้ำในนั้น... แม่ว่ามีตัวร้ายใต้น้ำ แต่ท่านดูไม่กลัวพวกมัน\n\nช่วยหาให้นางได้ไหม ได้โปรด?" },
        progress = { "125:224337403:996275166", "สวัสดี ข้าคิดถึงสร้อย พ่อให้มา พ่อบอกว่าทะเลสาบมีสัตว์ประหลาด ท่านตีพวกมันบ้างไหม?" },
        completion = { { "41:1010453418:150696574 C 73:2009284440:3455826", "39:639035148:1698123658 C 73:2009284440:3455826" }, "ขอบใจที่หาสร้อยให้ ท่าน{class}... ใจดีจัง! แมวข้าก็ขอบใจ ใช่ไหม Effsee?" },
        required = { [10958] = { "17:1721175244:1081352461", "สร้อยคอของ Hilary" } },
        steps = { { "17:1721175244:1081352461", "สร้อยคอของ Hilary" } },
    },
    [95816] = { -- Sign Me Up!
        title = { "11:1848945524:436738684", "สมัครให้ข้าด้วย!" },
        objective = { "65:1637699195:1283549362", "นำแบบฟอร์มที่กรอกแล้วไปให้ Elaine Compton ที่ Redridge Mountains" },
        description = { "349:316488405:669039283", "สวัสดี ช่างฝีมือผู้ชำนาญ!\n\nการกรอกแบบฟอร์มนี้จะให้สิทธิ์แบบไม่ผูกขาด เพิกถอนได้ และจำกัดตามกฎหมาย ในการแสดงป้ายโฆษณาวิชาชีพของท่านทั่ว Azeroth!\n\nเมื่อกรอกแล้ว โปรดส่งผู้ประสานงานสัญญาประจำสาขา Azeroth Commerce Authority ในพื้นที่ เพื่อเริ่มดำเนินการ\n\nขอให้สร้างผลงานอย่างมีความสุข!" },
        required = { [270888] = { "31:549983441:631209239", "แบบคำขออนุญาตติดป้ายโฆษณา" }, [270897] = { "31:38746501:2062448149", "กองแบบฟอร์มที่กรอกเสร็จแล้วขนาดมหึมา" } },
        steps = { { "31:549983441:631209239", "แบบคำขออนุญาตติดป้ายโฆษณา" }, { "31:38746501:2062448149", "กองแบบฟอร์มที่กรอกเสร็จแล้วขนาดมหึมา" } },
    },
    [95999] = { -- WANTED: Incinerator Gar'im
        title = { "26:1028384513:660333586", "ประกาศจับ: Incinerator Gar'im" },
        objective = { "82:587911054:1611610965", "ส่ง Broken Staff of Incinerator Gar'im ให้ Magistrate Solomon ที่ Lakeshire" },
        description = { "344:1350476124:1804205752", "ประกาศจับ! Incinerator Gar'im ผู้นำออร์ครุกราน Render's Valley เชื่อว่าทำงานร่วมกับ Blackrock แห่ง Stonewatch Keep\n\nระวัง Incinerator Gar'im เขากับผู้ร่ายเงาอันตรายอย่างยิ่ง ผู้กล้าที่นำหลักฐานการตายให้ Magistrate Solomon จะได้รางวัลงาม", variants = { { "347:1364094789:1325272872", "ประกาศจับ! Incinerator Gar'im ผู้นำออร์ครุกราน Render's Valley เชื่อว่าทำงานร่วมกับ Blackrock แห่ง Stonewatch Keep\n\nระวัง Incinerator Gar'im เขากับผู้ร่ายเงาอันตรายอย่างยิ่ง ผู้กล้าที่นำหลักฐานการตายให้ Magistrate Solomon จะได้รางวัลงาม" } } },
        completion = { { "162:623849526:1455388951", "16:1549935302:71513149 N 140:1378341226:1217633818", "16:1549935302:71513149 C 140:1378341226:1217633818", "16:1549935302:71513149 R 140:1378341226:1217633818" }, "ทำได้ดี สหาย! Incinerator Gar'im เตรียมเสริมการป้องกัน Stonewatch Keep ชัยชนะนี้อาจทำให้เรายึดป้อมคืนได้!" },
        progress = { "24:316066776:86638779 R 1:63:63", "มีอะไรนั่น {race}?" },
        required = { [271872] = { "34:1876413301:1334973718", "ไม้เท้าหักของ Incinerator Gar'im" } },
        steps = { { "34:1876413301:1334973718", "ไม้เท้าหักของ Incinerator Gar'im" } },
    },
    [98247] = { -- Shipping Label
        title = { "14:2031926144:1761693998", "ฉลากขนส่ง" },
        objective = { "104:2010819114:570408446", "ส่ง Shipping Label ให้คนที่ศูนย์การค้า Azeroth Commerce Authority ใน Redridge Mountains" },
        description = { "479:1471992944:1833000366", "<ด้านข้างลังที่ตอนนี้บรรจุของครบมีฉลากขาด แม้ส่วนชื่อผู้รับหาย แต่ที่มายังเหลือ\n\n“ทรัพย์สิน Azeroth Commerce Authority โปรดคืนลังเปล่าหรือสินค้าที่ส่งไม่ครบ ณ ศูนย์การค้าของเราที่ทางแยก Three Corners ใน Redridge Mountains ผู้ส่งจะได้รับค่าตอบแทนเวลาและการเดินทาง”\n\nข้างข้อความมีแผนที่วาดหยาบของบริเวณปลายทางดังกล่าว>" },
        progress = { "42:501495545:119707342", "อา สวัสดี! มีอะไรให้ช่วย?" },
        completion = { "500:1442523951:604847081", "มาถูกที่แล้ว! ข้ายินดีบันทึกเจ้าเป็นผู้ร่วมงาน ไม่ต้องเซ็นสัญญาหรือมีข้อผูกมัด ขอเพียงขยันช่วยเติมของให้ครบหรือคืนสินค้าของเราที่พบระหว่างเดินทาง\n\nเมื่อทำเช่นนั้นจะได้รับ Merchant's Favor ใช้ซื้อสินค้าและบริการที่นี่ เอ้านี่เล็กน้อยให้เริ่มต้น\n\nว่าแต่ มีลังที่ฉลากนี้ติดมาหรือไม่?" },
        required = { [280179] = { "14:2031926144:1761693998", "ป้ายกำกับสินค้า" } },
        steps = { { "14:2031926144:1761693998", "ป้ายกำกับสินค้า" } },
    },
    [98248] = { -- Shipping Label
        title = { "14:2031926144:1761693998", "ฉลากขนส่ง" },
        objective = { "119:828291900:604292873", "ส่ง Shipping Label ให้คนที่ศูนย์การค้า Durotar Supply and Logistics ใกล้ Crossroads ใน Barrens" },
        description = { "476:708844756:1535587009", "<ด้านข้างลังที่ตอนนี้บรรจุของครบมีฉลากขาด แม้ส่วนชื่อผู้รับหาย แต่ที่มายังเหลือ\n\n“คืนสินค้าที่เสียหายหรือลังเปล่า ณ จุดค้าขาย Durotar Supply and Logistics ซึ่งตอนนี้ตั้งสะดวกทางตะวันตกตรงจาก Crossroads ใน Barrens เวลาท่านมีค่า เราจะตอบแทนความพยายาม!”\n\nข้างข้อความมีแผนที่วาดหยาบของบริเวณปลายทางดังกล่าว>" },
        progress = { "37:786625511:2035747580", "สวัสดี นักเดินทาง มีอะไรให้ช่วย?" },
        completion = { "486:1553689576:1430781031", "มาถูกที่ คุยถูกคนแล้ว! ข้าบันทึกเป็นผู้ร่วมงานใหม่ได้ เจ้าไม่ต้องทำเอกสาร ข้าไม่อยากยุ่งเพิ่ม\n\nขอเพียงช่วยจัดการสินค้าที่มีปัญหาระหว่างทาง จะได้ Merchant's Favor ซื้อสินค้าและบริการที่นี่ นี่เล็กน้อยให้ตั้งตัว!\n\nมีลังที่ฉลากนี้ติดมาหรือไม่?", variants = { { "490:1489096764:1116484357", "มาถูกที่ คุยถูกคนแล้ว! ข้าบันทึกเป็นผู้ร่วมงานใหม่ได้ เจ้าไม่ต้องทำเอกสาร ข้าไม่อยากยุ่งเพิ่ม\n\nขอเพียงช่วยจัดการสินค้าที่มีปัญหาระหว่างทาง จะได้ Merchant's Favor ซื้อสินค้าและบริการที่นี่ นี่เล็กน้อยให้ตั้งตัว!\n\nมีลังที่ฉลากนี้ติดมาหรือไม่?" } } },
        required = { [280180] = { "14:2031926144:1761693998", "ป้ายกำกับสินค้า" } },
        steps = { { "14:2031926144:1761693998", "ป้ายกำกับสินค้า" } },
    },
    [98386] = { -- Alther's Mill
        title = { "13:1894803063:1508626", "โรงเลื่อย Alther" },
        objective = { "103:1038473997:1170016405", "สังหาร Greater Tarantula 12 ตัวและทำลาย Tarantula Egg 6 ฟองใน Alther's Mill ให้ Foreman Oslow ที่ Redridge", amount = { "5:1000000866:1065647852 W1 32:2073254914:758678869 W2 63:1749695218:1005200456", "สังหาร Greater Tarantula {world1} ตัวและทำลาย Tarantula Egg {world2} ฟองใน Alther's Mill ให้ Foreman Oslow ที่ Redridge" } },
        description = { "460:1488445677:13712034", "ออร์ค นอลล์ เมอร์ล็อก ทุกอย่างเหมือนจะขวางไม่ให้ข้าสร้างสะพานทัน ตอนนี้มีข่าวแมงมุมทารันทูลาระบาดในโรงเลื่อย!\n\nหากอยากได้เงินเพิ่ม ไป Alther's Mill ทางตะวันออก กำจัดแมงมุมหน่อยได้ไหม? หากส่งคนไปรับของอย่างปลอดภัยไม่ได้ ที่นั่นก็แทบไร้ประโยชน์\n\nอ้อ หากพบ Alther เฒ่า บอกว่าเขาติดหนี้ข้าที่ช่วยเก็บกวาดเรื่องยุ่งให้" },
        progress = { "148:809038682:1175476964", "ทารันทูลาที่นี่กัดครั้งเดียวทำคนงานเป็นไข้หยุดงานหนึ่งสัปดาห์ ข้าไม่อยากให้เกิด อย่างน้อยก็ไม่ขณะข้าคุม" },
        completion = { { "174:219653797:1179139336", "167:216596279:912783972 N 1:33:33", "167:216596279:912783972 C 1:33:33", "167:216596279:912783972 R 1:33:33" }, "โรงเลื่อยแย่ขนาดนั้นหรือ? หนักกว่าที่คิด\n\nข้าไม่ได้ขวัญอ่อนนัก แต่งานก็แย่พอแล้ว ไม่ต้องมีแมงมุมจับคนงานเพิ่ม ขอบใจ สหาย!", variants = { { "166:1947783214:695474018 N 1:33:33", "โรงเลื่อยแย่ขนาดนั้นหรือ? หนักกว่าที่คิด\n\nข้าไม่ได้ขวัญอ่อนนัก แต่งานก็แย่พอแล้ว ไม่ต้องมีแมงมุมจับคนงานเพิ่ม ขอบใจนะ {name}!" } } },
        steps = { { "23:473257698:1224562825", "ทำลายไข่ทารันทูลา" } },
        objectiveLabels = {
            monster = { ["Greater Tarantula slain"] = "ปราบ ทารันทูลายักษ์" },
        },
    },
    [98387] = { -- Blackrock Blockade
        title = { "18:195951553:1493482354", "ตัดกำลัง Blackrock" },
        objective = { "80:562094617:1332734380", "นำ Stolen Weapon 8 ชิ้นและ Blackrock Supply 10 ชิ้นไปให้ Marshal Marris ที่ Lakeshire", variants = { { "56:1354906926:639003668", "นำ Battleworn Axe 10 เล่มไปให้ Marshal Marris ที่ Lakeshire" } }, amount = { "6:1273960851:929420321 W1 20:1224868940:941775117 W2 51:55426301:907274272", "นำ Stolen Weapon {world1} ชิ้นและ Blackrock Supply {world2} ชิ้นไปให้ Marshal Marris ที่ Lakeshire" } },
        description = { "338:1393030409:1230504122", "ไม่มีอาวุธก็ทำสงครามไม่ได้\n\nแม้ออร์ค Blackrock รุกล้ำแผ่นดิน ความอุกอาจของมันก็ยังมีจุดอ่อน\n\nมุ่งตะวันออกเฉียงใต้ใต้ Stonewatch Keep หาค่าย แล้วเล่นงานอาวุธกับเสบียง\n\nมาดูว่าขาดเครื่องมือสงครามแล้วจะคุกคามได้แค่ไหน", variants = { { "260:1644510575:922483745 N 176:384793397:621633478", "สิ่งที่พวกออร์ค Blackrock ไม่เข้าใจก็คือ สงครามนี้วัดกันที่ว่าใครจะหมดแรงก่อน พวกมันบุกรุกดินแดน Alliance อย่างไม่เกรงกลัว จนตอนนี้ตกอยู่ในสภาพเสียเปรียบและขาดเสบียง ต้องพึ่งทรัพยากรจากภูเขารอบ ๆ\n\nกองทัพรบตอนท้องว่างไม่ได้หรอก {name} ไปที่ค่ายของพวกมันทางใต้ของป้อม Stonewatch Keep ที่อยู่ทางตะวันออก แล้วยึดอาหารกับอาวุธของพวกมันมา มาดูกันว่าพวกออร์คจะยังฮึกเหิมแค่ไหนเมื่อท้องหิวและไม่มีอาวุธป้องกันตัว" } } },
        progress = { "139:183108143:126548950", "ของส่วนใหญ่คงปล้นจาก Lakeshire อยู่แล้ว ข้าคงสบายใจที่คนเรารุ่งเรืองขณะออร์คอ่อนแรง" },
        completion = { "180:574339461:1451139898", "ทำได้ดี สหาย เมื่อออร์ค Blackrock ถูกตัดจากพันธมิตรใน Burning Steppes มันไม่มีหวังรักษาฐานที่นี่หากขาดเสบียงเหมาะสม", variants = { { "16:1549935302:71513149 N 158:240643422:262518073", "ทำได้ดี {name} เมื่อออร์ค Blackrock ถูกตัดจากพันธมิตรใน Burning Steppes มันไม่มีหวังรักษาฐานที่นี่หากขาดเสบียงเหมาะสม" } } },
        required = { [280841] = { "13:480589297:1998414282", "อาวุธที่ถูกขโมย" }, [280839] = { "18:1996567519:115247197", "เสบียงของ Blackrock" } },
        steps = { { "13:480589297:1998414282", "อาวุธที่ถูกขโมย" }, { "18:1996567519:115247197", "เสบียงของ Blackrock" } },
    },
    [98407] = { -- Show of Force
        title = { "13:1503529979:1004066594", "แสดงแสนยานุภาพ" },
        objective = { "82:918569041:214346889", "เก็บ Spiked Collar 5 ชิ้นจาก Redridge Thrasher ให้ Deputy Feldon ใกล้ Lakeshire", variants = { { "79:541121343:965139104", "เก็บ Spiked Collar 5 ชิ้นจาก Gnoll Thrasher ให้ Deputy Feldon ใกล้ Lakeshire" } }, amount = { "8:1089852795:1107240600 W1 73:1690829459:673416918", "เก็บ Spiked Collar {world1} ชิ้นจาก Redridge Thrasher ให้ Deputy Feldon ใกล้ Lakeshire" } },
        description = { "504:1321453668:1146945242", "หากนอลล์กล้าตั้งค่ายใกล้มนุษย์ขนาดนี้ ก็ไม่รู้จะรุกอีกเพียงใด เราต้องยับยั้ง\n\nพวกมันแทบไม่เป็นระเบียบ แต่ดูนับถือพลังเหนือสิ่งอื่น หากสังหารตัวร้ายที่สุดแล้วชิงของอวดชัยบ้าง อาจเตือนให้รู้ว่าควรอยู่บนเนินตามเดิม\n\nหากพบ Thrasher นำปลอกคอมา คงทำให้มันกลัว Alliance อีกครั้ง" },
        progress = { "116:686017226:1844681428", "ประเมินนอลล์ไม่ครบหากยังไม่เผชิญพวกเลวร้ายที่สุด กำจัด Thrasher พวกนั้น!" },
        completion = { { "168:127993913:2079039521", "161:2023384641:241868892 N 1:46:46", "161:2023384641:241868892 C 1:46:46", "161:2023384641:241868892 R 1:46:46" }, "หอบมาเต็มแขนเลยนะ\n\nแม้ยังไม่แก้ปัญหาทั้งหมด ข้าก็พักสบายได้เมื่อรู้ว่าเราทำให้มันไม่กล้ารุกเพิ่ม ทำได้ดี สหาย" },
        required = { [280911] = { "13:2012199518:772844930", "ปลอกคอหนาม" } },
        steps = { { "13:2012199518:772844930", "ปลอกคอหนาม" } },
    },
    [361] = { -- A Letter Undelivered
        progress = { "4:1517439344:201828488", "ว่าอย่างไร?" },
        title = { "20:1317012883:18723901", "จดหมายที่ส่งไม่ถึง" },
        objective = { "73:568890597:1499249888", "ตามหา Yvette Farthing แล้วส่งจดหมายจาก Thurman Agamand ให้นาง" },
        description = { "158:2147293117:248636684", "จดหมายนี้เขียนโดยเธอร์แมน บุตรชายคนโตของเกรกอร์ อากามันด์ จ่าหน้าถึงหญิงชื่ออีเวตต์ ฟาร์ธิง แต่ดูเหมือนจะส่งไม่ถึงนาง..." },
        completion = { "482:1487710815:217906237", "โอ้... เธอร์แมนผู้น่าสงสาร! ข้าอ้อนวอนให้เขาออกจากโรงโม่อากามันด์ไปกับข้าและพ่อ แต่เขาภักดีต่อตระกูลเหลือเกิน! ข้ารู้อยู่แล้ว! ข้ารู้ว่าแบรนด์คิดร้ายกับเขา!! โอ้ ขอให้โรคระบาดกับสเคิร์จจงพินาศ!\n\n<ใบหน้าของอีเวตต์กลับมาเรียบเฉยและเย็นชา>\n\nแต่ความเสียดายมีไว้สำหรับคนอ่อนแอ ในฐานะฟอร์เซเคน ข้ามีเป้าหมายใหม่ และความรักไม่อยู่ในนั้น ข้าขอบใจที่เอาจดหมายมาส่ง เพราะเคยสงสัยว่าเกิดอะไรขึ้นกับคนที่ข้าเคยรัก\n\nแต่ชีวิตนั้นจบลงแล้ว ตลอดกาล" },
        required = { [2837] = { "16:867329219:132780827", "จดหมายของ Thurman" } },
        steps = { { "16:867329219:132780827", "จดหมายของ Thurman" } },
    },
    [398] = { -- WANTED: Maggot Eye
        progress = { "4:1517439344:201828488", "ว่าอย่างไร?" },
        title = { "18:1036884036:872828981", "ประกาศจับ Maggot Eye" },
        objective = { "81:1708853014:505965649", "สังหาร Maggot Eye แล้วนำอุ้งเท้าของมันกลับไปให้ Executor Zygand ที่ Brill เพื่อรับรางวัล" },
        description = { "484:1813588350:177513171", "ประกาศจับ Maggot Eye!\n\nแม็กกอตอายเป็นสัตว์ชั่วร้ายแม้เทียบกับโนลล์ด้วยกัน มันถูกตัดสินประหารจากอาชญากรรมต่อฟอร์เซเคน เจ้าวายร้ายขโมยศพไปให้กองทัพลิชคิงใช้ ครั้งสุดท้ายมีคนเห็นมันปล้นอยู่ใกล้ Garren's Haunt ทางเหนือของบริลล์\n\nเมืองบริลล์ขอมอบรางวัลแก่ผู้มีฝีมือที่ลงมือประหารได้ เมื่องานเสร็จ ให้นำอุ้งเท้ามันไปแสดงต่อเอ็กเซคิวเตอร์ไซแกนด์\n\nความปรานีมีไว้สำหรับคนอ่อนแอ" },
        completion = { "197:57370697:1613147357 N 1:46:46", "ความชั่วร้ายของแม็กกอตอายได้รับการชำระแล้ว บางทีความกล้าของเจ้าจะส่งสารชัดเจนถึงพวกที่คิดทำร้ายคนของเรา ในนามเมืองบริลล์ ข้าขอบใจเจ้า {name}" },
        required = { [3635] = { "16:1504650713:76240648", "อุ้งเท้าของ Maggot Eye" } },
        steps = { { "16:1504650713:76240648", "อุ้งเท้าของ Maggot Eye" } },
    },
    [567] = { -- Dangerous!
        title = { "10:1205670811:1677670554", "อันตราย!" },
        objective = { "137:214216386:1610998459", "High Executor Darthalia แห่ง Tarren Mill ตั้งค่าหัว Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett และ Farmer Kalaba" },
        description = { "488:1203938437:1055334147", "อันตราย!\n\nHigh Executor Darthalia ตัดสินว่ามนุษย์ Hillsbrad ต่อไปนี้เป็นอันตรายและตั้งค่าหัว\n\nClerk Horrace Whitesteed ฐานฆ่า Deathguard Toma\n\nCitizen Wilkes ฐานฆ่า Apothecary Eli\n\nMiner Hackett ฐานฆ่า Deathstalker Fry\n\nFarmer Kalaba ฐานซุ่มโจมตีเสบียงจาก Undercity\n\nศัตรูทั้งหมดซ่อนตัว หาได้ยาก จะมอบรางวัลเมื่อได้รับแจ้งความตาย" },
        progress = { "4:1517439344:201828488", "ว่าอย่างไร?" },
        completion = { "33:1244990692:387192539 C 12:586053710:1993834439", "เจ้าเป็นนักล่าค่าหัวที่เก่งจริง {class} ทำได้ดี" },
        objectiveLabels = {
            monster = { ["Clerk Horrace Whitesteed slain"] = "ปราบ เสมียน Horrace Whitesteed", ["Citizen Wilkes slain"] = "ปราบ พลเมือง Wilkes", ["Miner Hackett slain"] = "ปราบ คนงานเหมือง Hackett", ["Farmer Kalaba slain"] = "ปราบ ชาวนา Kalaba" },
        },
    },
    [819] = { -- Chen's Empty Keg
        title = { "16:686886081:1969337172", "ถังเปล่าของ Chen" },
        objective = { "46:903157861:287668065", "หาคนที่รู้เรื่อง Chen's Empty Keg" },
        description = { "127:1635362358:625813131", "ป้ายเล็ก ๆ ที่ปลายด้านหนึ่งของถังเขียนไว้ว่า\n\n\"Chen Stormstout—\n\nขอให้ใจเจ้ารื่นเริง และยกจอกเติมความรื่นเริงเสมอ\"" },
        progress = { "4:1517439344:201828488", "ว่าอย่างไร?" },
        completion = { "187:1570942708:901350693 N 1:46:46", "โอ้ ไม่น่าเชื่อ...\n\nนี่เป็นถังใบหนึ่งของ Chen Stormstout เขาเคยเดินทางกับ Rexxar เมื่อนานมาแล้ว ข้าไม่ได้เห็นเขาหรือได้ยินข่าวมานานแสนนาน ขอบใจที่นำมาให้ข้านะ {name}" },
        required = { [4926] = { "16:686886081:1969337172", "ถังเหล้าเปล่าของ Chen" } },
        steps = { { "16:686886081:1969337172", "ถังเหล้าเปล่าของ Chen" } },
    },
    [898] = { -- Free From the Hold
        title = { "18:480933055:1286789619", "หนีพ้นป้อมขัง" },
        objective = { "71:1039405061:1108884429", "คุ้มกัน Gilthares Firebough กลับไปหา Captain Brightsun ใน Ratchet อย่างปลอดภัย" },
        description = { "460:575727058:402531551", "ในที่สุด! มีคนมาช่วยข้าแล้ว!\n\nไม่น่าเชื่อว่าเจ้าผ่านทหารยามมาได้ พวกคลั่งจาก Theramore นี่บ้าไปแล้ว มันจมเรือเราแล้วขังข้า ผู้รอดชีวิตคนเดียว กล่าวหาว่าข้าเป็นศัตรูและภัยต่อ Alliance\n\nข้านี่นะ! เป็นภัยต่อ Alliance จอมลวงโลกอันยิ่งใหญ่ของมันหรือ? ข้าเป็นแค่ลูกเรือขนเหล้าเถื่อนระหว่าง Ratchet กับ Booty Bay\n\nพูดพอแล้ว ช่วยข้ากลับ Ratchet ทีได้ไหม? บอกเมื่อเจ้าพร้อม แล้วเราจะหาทางหนีกัน" },
        progress = { "4:1517439344:201828488", "ว่าอย่างไร?" },
        completion = { "127:1218733528:2064365059 N 1:46:46", "คิดดูสิ เรานึกว่า Firebough ตายไปนานแล้ว!\n\nวีรกรรมของเจ้าทำให้ได้รับเกียรติในหมู่ Thalo'dan Privateers แล้ว {name}" },
        objectiveLabels = {
            event = { ["Escort Gilthares Firebough back to Ratchet"] = "คุ้มกัน Gilthares Firebough กลับไปยัง Ratchet" },
        },
    },
    [1978] = { -- The Deathstalkers
        title = { "17:153157761:1025694371", "Deathstalkers" },
        objective = { "85:76577526:1821458094", "นำ Andron's Ledger ไปให้ Varimathras ที่ Hall of the Dark Lady ใน Undercity" },
        description = { "347:55258350:541334708", "Syndicate หรือ? ข้าไม่เคยสงสัยเลย ดูเหมือนเหล่าขุนนาง Alterac ตกต่ำไปมากนับแต่ทรยศ\n\nLord Varimathras จะยินดีที่รู้เรื่องนี้ เมื่อเจ้ามีส่วนสำคัญในการค้นพบ ก็ควรเป็นผู้นำไปให้เขา\n\nอา ลืมได้อย่างไร?\n\nยินดีต้อนรับสู่ Deathstalkers" },
        progress = { "4:1517439344:201828488", "ว่าอย่างไร?" },
        completion = { { "227:1074109455:773981549 N 49:1189219496:291659413", "227:1074109455:773981549 N 51:864893935:604847425" }, "หืม น่าสนใจ Deathstalkers ทำหน้าที่ได้ดีน่าชื่นชมในการขุดคุ้ยเรื่องนี้\n\nเท่าที่ทราบ เจ้าก็สมควรได้รับคำชม หวังว่าความสำเร็จเช่นนี้จะเป็นเรื่องปกติสำหรับเจ้า {name} Deathstalkers ของข้ามีงานให้คนเก่งเสมอ" },
        required = { [7294] = { "15:655925524:971131134", "สมุดบัญชีของ Andron" } },
        steps = { { "15:655925524:971131134", "สมุดบัญชีของ Andron" } },
    },
    [2282] = { -- Alther's Mill
        title = { "13:1894803063:1508626", "โรงเลื่อย Alther" },
        objective = { "90:1110040478:780545502", "เปิด Lucius's Lockbox นำ Token of Thievery กลับไปให้ Lucius ใน Lakeshire" },
        description = { "319:405707762:966073007", "เราฝึกโจรมาหลายปีแล้ว! ไม่ใช่เจ้าตัวแสบทุกคนจะเกิดมาสง่างามและมีชั้นเชิงเหมือนเฒ่า Lucius\n\nขึ้นจากถนนนี่ไปจะพบ Alther's Mill ข้ามีหีบที่ใส่ของสำคัญอยู่บนนั้น ไปเอามาให้ข้า! นำตรานั้นกลับมา แล้วจะได้ประกาศนียบัตรโจรกรรม!" },
        progress = { "85:2115100517:550563167", "ลืมบอกเรื่องออร์คหรือเปล่านะ?\n\nได้ยินว่าพวกมันสอดส่องแถวโรงสี" },
        completion = { "37:520682360:550595322 N 97:833756943:1986118928", "เปิดได้แล้วหรือ? ทำดีมาก {name}\n\nหากตายตอนนี้ เราก็วางใจได้ว่าเกิดจากความโง่เจ้าเอง ไม่ใช่ขาดประสบการณ์" },
        required = { [7871] = { "17:1250393671:1381757325", "ตราแห่งการลักขโมย" } },
        steps = { { "17:1250393671:1381757325", "ตราแห่งการลักขโมย" } },
    },
    [3121] = { -- A Strange Request
        title = { "17:375115341:333013691", "คำขอประหลาด" },
        objective = { "55:1670377270:1750027648", "นำ Shrunken Head ไปให้ Neeru Fireblade ใน Orgrimmar" },
        description = { "404:1732066123:548487314", "Neeru Fireblade ใน Orgrimmar มีของที่ข้าต้องการเริ่มงาน! เขาผสมส่วนประกอบให้ข้าไว้ใช้กับ... เดี๋ยวเจ้าจะเห็น\n\nไป Orgrimmar ได้แล้ว นี่ เอาไปด้วย เป็นหัวหดที่ข้าสัญญาแลกสมุนไพรกับ Neeru หัวของคนแคระโชคร้ายที่พบในป่า เขาคงพอใจ\n\nหา Neeru ได้ที่ Cleft of Shadow" },
        progress = { "4:1517439344:201828488", "ว่าอย่างไร?" },
        completion = { "125:1750010650:358720996", "ข้ารอให้ Uzer'i ส่งสิ่งนี้มา...\n\nข้าจะให้ส่วนผสมสมุนไพรที่เตรียมไว้สำหรับ... การทดลองของเขา..." },
        required = { [9629] = { "15:345120663:247909324", "ศีรษะย่อส่วน" } },
        steps = { { "15:345120663:247909324", "ศีรษะย่อส่วน" } },
    },
    [95819] = { -- Sign Me Up!
        title = { "11:1848945524:436738684", "สมัครให้ข้าด้วย!" },
        objective = { "50:458142756:224550530", "นำแบบฟอร์มที่กรอกแล้วไปให้ Jornah ใน The Barrens" },
        description = { "340:661716611:970178401", "สวัสดี ช่างฝีมือผู้เชี่ยวชาญ!\n\nการกรอกแบบฟอร์มนี้จะมอบสิทธิ์ที่ไม่ผูกขาด เพิกถอนได้ และอยู่ภายใต้ข้อจำกัดทางกฎหมาย ให้ท่านแสดงป้ายโฆษณาวิชาชีพของท่านทั่ว Azeroth!\n\nเมื่อกรอกเสร็จ โปรดนำไปให้ผู้ประสานงานสัญญา Durotar Supply & Logistics ในพื้นที่ เพื่อเริ่มดำเนินการ\n\nขอให้สร้างสรรค์ผลงานอย่างมีความสุข!" },
        required = { [270887] = { "31:549983441:631209239", "แบบคำขออนุญาตติดป้ายโฆษณา" }, [270897] = { "31:38746501:2062448149", "กองแบบฟอร์มที่กรอกเสร็จแล้วขนาดมหึมา" } },
        steps = { { "31:549983441:631209239", "แบบคำขออนุญาตติดป้ายโฆษณา" }, { "31:38746501:2062448149", "กองแบบฟอร์มที่กรอกเสร็จแล้วขนาดมหึมา" } },
    },
    [5] = { -- Jitters' Growling Gut
        title = { "21:1096318889:2094924867", "ท้องร้องของ Jitters" },
        objective = { "22:6242758:301793264", "คุยกับ Chef Grual" },
        description = { "307:2030225863:569115476", "ข้าติดซ่อนในเมืองผีนี่หลายสัปดาห์ กินแต่หนอนกับวัชพืช! ต้องการอาหารดี ๆ และยอมแลกอย่างงาม\n\nนำอาหารเลี้ยงมา ข้าจะจ่ายให้มาก\n\nได้ยินว่า Chef Grual ที่ Scarlet Raven Tavern ใน Darkshire ทำ Dusky Crab Cake อร่อยมาก..." },
        completion = { "81:802656705:410642015", "ต้องการเค้กปูหรือ? เอาล่ะ ข้าอาจทำให้ได้..." },
    },
    [55] = { -- Morbent Fel
        title = { "11:1847761718:2024580327", "Morbent Fel" },
        objective = { "100:1513844523:754685427", "ใช้ Morbent's Bane กับ Morbent Fel สังหารเขา แล้วคืน Morbent's Bane ให้ Sven ที่ค่าย" },
        description = { "347:1367528931:1078290287", "Morbent Fel ซ่อนในรัง เป็นบ้านบนเนินตะวันออกที่มองลงสุสาน Raven Hill เวลาของมันบนแผ่นดินนี้ใกล้จบ...\n\nใช้ Morbent's Bane ใส่ มันจะทำให้เวทป้องกันไร้พลัง\n\nสังหารมัน ช่วยเราจากความชั่ว เป็นผู้ล้างแค้นแทนข้า และวีรชนแห่ง Duskwood!" },
        progress = { "25:1783770325:1533541276", "ปราบ Morbent Fel แล้วหรือ?!" },
        completion = { "236:1733354499:1494052467 N 56:1385199858:2058013622", "Morbent Fel พ่ายแล้ว แม้ Dark Riders ยังลอยนวล แต่ส่วนเล็ก ๆ ของสิ่งที่ข้าแทบไม่กล้าหวังก็เกิดขึ้น\n\nเจ้าทำสิ่งเป็นไปไม่ได้ วีรกรรมจะอยู่ในตำนาน Duskwood ตลอดไป\n\nไปเถอะ {name} บางทีวันหนึ่งชะตาอาจพากลับมาหาข้า..." },
        required = { [7297] = { "14:1861514198:1302663218", "อาวุธปราบ Morbent" } },
        steps = { { "14:1861514198:1302663218", "อาวุธปราบ Morbent" } },
        objectiveLabels = {
            monster = { ["Morbent Fel slain"] = "ปราบ Morbent Fel" },
        },
    },
    [56] = { -- The Night Watch
        title = { "15:355211882:1934813841", "หน่วย Night Watch" },
        objective = { "99:540051945:152071676", "Commander Althea Ebonlocke ที่ Darkshire ต้องการให้สังหาร Skeletal Warrior 8 ตัวและ Skeletal Mage 6 ตัว" },
        description = { "424:1902052678:444953998", "ในฐานะผู้บัญชาการ Night Watch ข้าสาบานปกป้องชาว Darkshire แต่ Stormwind ถอนยามประจำการ ปล่อยให้เราดูแลตนเอง\n\nหากคิดว่าไหว เราต้องการเจ้าช่วย! ไป Tranquil Gardens ใต้ Darkshire กำจัด Skeletal Warrior 8 ตัวกับ Skeletal Mage 6 ตัว ต้องหยุดภัยอันเดด!" },
        progress = { "20:168162824:875123572 N 143:166805947:298594787", "กลับมาแล้วหรือ {name} หากอยากพิสูจน์ว่ารับใช้ Night Watch ได้ กลับมาเมื่อสังหาร Skeletal Warrior 8 ตัวและ Skeletal Mage 6 ตัวแล้ว" },
        completion = { "10:1582154033:241472075 N 68:8063451:2014406249", "ยอดเยี่ยม {name} เจ้าจะได้รับรางวัลตอบแทนการรับใช้ชาว Darkshire" },
        objectiveLabels = {
            monster = { ["Skeletal Warrior slain"] = "ปราบ นักรบโครงกระดูก", ["Skeletal Mage slain"] = "ปราบ จอมเวทโครงกระดูก" },
        },
    },
    [57] = { -- The Night Watch
        title = { "15:355211882:1934813841", "หน่วย Night Watch" },
        objective = { "101:1957997485:1714114623", "Commander Althea Ebonlocke ที่ Darkshire ต้องการให้สังหาร Skeletal Fiend 15 ตัวและ Skeletal Horror 15 ตัว" },
        description = { "N 332:483856827:406584701", "{name} ข้าได้รายงานอันเดดระบาดในป่า! หากพร้อม ไปสุสาน Raven Hill กำจัด Skeletal Fiend ชั่ว 15 ตัวกับ Skeletal Horror 15 ตัว มีรายงานโครงกระดูกใต้ Darkshire แถว Tranquil Gardens Cemetery ด้วย ต้องขับอันเดดจาก Duskwood!" },
        progress = { "78:665297401:2062148149 N 1:46:46", "กลับมาเมื่อสังหาร Skeletal Fiend 15 ตัวกับ Skeletal Horror 15 ตัวแล้ว {name}" },
        completion = { "35:80459842:527934959 N 65:552100050:198233865", "ชาว Darkshire ขอบใจ {name} เจ้าพิสูจน์ว่าเป็นพันธมิตรยิ่งใหญ่ของ Night Watch" },
        objectiveLabels = {
            monster = { ["Skeletal Fiend slain"] = "ปราบ ปีศาจโครงกระดูก", ["Skeletal Horror slain"] = "ปราบ โครงกระดูกสยองขวัญ" },
        },
    },
    [58] = { -- The Night Watch
        title = { "15:355211882:1934813841", "หน่วย Night Watch" },
        objective = { "114:1522034851:1178621896", "Commander Althea Ebonlocke ที่ Darkshire ต้องการให้สังหาร Plague Spreader 20 ตัวในอาคารสุสานฝั่งตะวันออกของ Raven Hill" },
        description = { "85:931399709:1674370563 N 156:927923103:2101831566", "Raven Hill ยังน่าหวั่น ความปลอดภัย Darkshire อยู่ในมือเจ้า {name} ข้ามี Watcher ไม่พอรักษาเมือง ต้องให้เจ้าไป Raven Hill อีก กวาด Plague Spreader 20 ตัวจากอาคารสุสานฝั่งตะวันออก!" },
        progress = { "24:369722923:308665944 N 136:1148618363:1557029255", "ข้าต้องการเจ้าช่วย {name} ไปสุสานตะวันตกเฉียงเหนือ กวาด Plague Spreader 20 ตัวจากอาคารสุสานฝั่งตะวันออก\n\nกลับเมื่องานจบ" },
        completion = { "88:1806491369:1052408349 N 70:244566571:206034704", "ในนามชาว Darkshire และผู้นำ Night Watch ข้าขอบใจ {name} สำหรับความกล้าและทุ่มเท ขอแสงสว่างส่องเส้นทางเจ้า" },
        objectiveLabels = {
            monster = { ["Plague Spreader slain"] = "ปราบ ผู้แพร่โรคระบาด" },
        },
    },
    [66] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "53:630713604:611512586", "ไปหา Clerk Daltry ที่ Darkshire Town Hall" },
        description = { "441:478918573:1464380969", "เมื่อคืนความปั่นป่วนสยองแล่นในเส้นเลือด ข้ารู้สึกว่า Alyssa หลานสาวตกอันตรายใหญ่หลวง เปิดไพ่แล้วความตายจ้องจากโต๊ะ\n\nหลังเดินทางไกลในภวังค์มืด ข้าพบเบาะแสปริศนาน่ากลัว ชื่อหนึ่งผุดขึ้น Stalvan\n\nไปหาเสมียนที่ศาลาว่าการ ดูว่ารู้เรื่องคนนี้เพิ่มไหม ข้ากลัวแทนเราทุกคน" },
        completion = { "32:874562869:1030127916", "อา Madame Eva ส่งเจ้ามา..." },
    },
    [67] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "105:813111688:113245543", "ไป Moonbrook Schoolhouse แล้วนำข้อมูลใหม่เกี่ยวกับ Stalvan กลับไปให้ Clerk Daltry" },
        description = { "375:899301589:953995792", "Stalvan หรือ? ขอค้นทะเบียนเมือง\n\nStalvan... ดูสิ อา พบแล้ว! มีบันทึก Mr. Stalvan Mistmantle ที่อยู่ล่าสุด Moonbrook Schoolhouse เก่าเสียจริง!\n\nช่วยหน่อย สหาย หากไป Moonbrook แล้วได้ข่าวใหม่ ช่วยบอกข้า ข้าอยากให้ทะเบียนเรียบร้อย" },
        completion = { "37:1761617123:1660347726", "หีบเก่าค่อย ๆ เปิดเอี๊ยด..." },
    },
    [68] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "45:1829051911:972319807", "นำ Dusty Unsent Letter ไปให้ Clerk Daltry" },
        description = { "53:1310393588:1241243141", "เจ้าพบ Dusty Unsent Letter ในหีบเก่า" },
        progress = { "121:1737560220:1594655726", "อา จำได้ เจ้าคนถามเรื่อง Stalvan พบที่หาแล้วหรือ?" },
        completion = { "159:1772347679:1154282183", "น่าสนใจ เขาเคยอยู่ Moonbrook จริง แปลกที่จดหมายไม่เคยถูกส่ง อย่างไรก็จะปรับทะเบียน" },
        required = { [889] = { "21:468190625:1140226026", "จดหมายฝุ่นจับที่ยังไม่ได้ส่ง" } },
        objectiveLabels = {
            item = { ["A Dusty Unsent Letter"] = "จดหมายฝุ่นจับที่ยังไม่ได้ส่ง" },
        },
    },
    [69] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "80:121618716:1009202663", "ไป The Lion's Pride Inn ดูว่ามีใครเคยได้ยินชื่อ Stalvan ไหม" },
        description = { "259:1940044818:638296552 N 1:46:46", "โอ้! คงพลาดตอนแรก ใต้ที่อยู่แรกของ Stalvan ในทะเบียนมีอีกแห่ง ถูกขีดฆ่าแค่บางส่วน ดูเหมือนเขาไป The Lion's Pride Inn ที่ Goldshire เจ้าน่าจะตรวจที่นั่น {name}" },
        completion = { "30:1386144213:767072713", "Stalvan? ฟังคุ้นจริง ๆ" },
    },
    [70] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "103:968362929:1573885326", "นำ Stalvan's Undelivered Letter จากหีบไปส่งที่ Canal District ใน Stormwind" },
        description = { "481:1624469675:1166027767", "ชื่อ Stalvan คุ้นหู จำได้แล้ว\n\nหลายปีก่อน คืนพายุ ผู้ส่งสารเข้ามาขอพัก พอใกล้เที่ยงคืน เขาวิ่งกรีดร้องลงบันได หน้าซีดกลัว หายไปในฝนทั้งชุดนอน\n\nรีบจนลืมจดหมายในหีบข้างบน ไม่กลับมาเอาอีก เหลือฉบับหนึ่งจาก Stalvan ส่ง Canal District ใน Stormwind หยิบไปได้เลย" },
        progress = { "55:106479218:2115512952", "มีอะไรนั่น? ให้ข้าดู..." },
        completion = { "41:178934371:534476360", "เจ้าช่างกล้านำมาที่นี่" },
        required = { [910] = { "21:1734572235:946957775", "จดหมายที่ยังไม่ได้ส่งถึงผู้รับ" } },
        steps = { { "21:1734572235:946957775", "จดหมายที่ยังไม่ได้ส่งถึงผู้รับ" } },
    },
    [72] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "52:1640878845:1227734078", "ค้นข้าวของที่เก็บห่อไว้เพื่อหาเบาะแส" },
        description = { "400:1114909849:944728907", "พ่อข้าเป็นผู้ดูแลคฤหาสน์ก่อนข้านาน เขาต้องเช็ดเลือดหลังเหตุสังหารหมู่ แต่ช่างเถอะ\n\nเงินกองทรัสต์ Flintridge หมดแล้ว ของตระกูลที่เหลือจะถูกประมูล โทษพวกเก็บภาษีหน้าเลือดนั่น หากอยากรู้เพิ่มจริงก็ค้นขยะนี้ได้ ใครจะรู้ว่าจะพบอะไร" },
        completion = { "48:1395284016:2031224928", "เจ้าค่อย ๆ เลื่อนฝาลังออก..." },
    },
    [74] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "61:1747674705:413732241", "Torn Journal Page ที่พบคือเบาะแสต่อไป" },
        description = { "198:1133428771:1769279510", "ในลังมีของหลายอย่าง มรดกเหม็นอับ ภาพครอบครัว ของล่าสัตว์อวดชัย และหนังสือเก่า ใกล้ก้นลังใต้แจกันเซรามิก เจ้าพบ Torn Journal Page" },
        progress = { "83:1056036317:373128009", "มีอะไรนั่น? ข้ามองไม่เห็น สายตาแย่มาก วางในมือข้า" },
        completion = { "127:227423479:844077480", "แทบอ่านอักษรไม่ออก แต่ลายมือนึกถึงสิ่งที่เคยเห็นก่อนสายตาจะแย่เช่นนี้" },
        required = { [916] = { "19:1974982506:345949068", "หน้าบันทึกที่ฉีกขาด" } },
        steps = { { "19:1974982506:345949068", "หน้าบันทึกที่ฉีกขาด" } },
    },
    [75] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "81:1008289284:1019217996", "Marshal Haggard ต้องการให้เจ้าตรวจหีบข้างบนหา Faded Journal Page" },
        description = { "461:432681395:212158297", "ตอนย้ายมา มีแผ่นหนังมัดหนึ่งในหีบข้างบน เคยดูครั้งเดียวแล้วเลิกเมื่อสายตาขุ่นมัว\n\nช่วยชายชราใกล้บอดที ตรวจหีบข้างบนหาของช่วยสืบ Stalvan ข้าค่อนข้างแน่ใจว่ามีหน้าบันทึกเลือนที่อาจสนใจ นำมา แล้วข้าจะช่วยเท่าที่ทำได้" },
        progress = { "36:872592951:827483697 N 1:63:63", "พบหน้าที่บอกไหม {name}?" },
        completion = { "13:423518919:1219993096", "พบแล้ว!" },
        required = { [921] = { "20:556016315:1510147652", "หน้าบันทึกที่หมึกเลือน" } },
        steps = { { "20:556016315:1510147652", "หน้าบันทึกที่หมึกเลือน" } },
    },
    [78] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "49:54849349:1051695776", "นำ Faded Journal Page ไปให้ Tavernkeep Smitts" },
        description = { "283:1643538052:196839646", "ข้ารู้จักคนอาจช่วย สมัยนำยาม Stormwind เราไปดื่มที่ Scarlet Raven Tavern ใน Darkshire Smitts เจ้าของเชี่ยวชาญตำนานท้องถิ่น ให้เขาดูหน้านี้แล้วฟังว่าอย่างไร" },
        progress = { "167:1196773078:878620635", "Marshal Haggard ส่งเจ้าหรือ? ทำไมไม่บอก?\n\nอา Haggard เพื่อนเก่า ผู้น่าสงสารคงบอดสนิทอีกไม่นาน เอาล่ะ ให้ดูของเจ้าหน่อย" },
        completion = { "51:1330255327:602380446", "ด้วยแสงสว่าง! ข้าจำลายมือนี้ได้แน่" },
        required = { [921] = { "20:556016315:1510147652", "หน้าบันทึกที่หมึกเลือน" } },
        steps = { { "20:556016315:1510147652", "หน้าบันทึกที่หมึกเลือน" } },
    },
    [79] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "43:1748830376:590120205", "นำหน้าบันทึกเปื้อนโคลนไปให้ Commander Ebonlocke" },
        description = { "389:2131476154:870782231", "ข้าตามตำนาน Stalvan หลายปี เมื่อขุนนางผู้มาเยือนถูกสังหารเมื่อหลายปีก่อน ข้าไปสืบกับ Haggard พบหน้าเปื้อนโคลน แต่เชื่อมลายมือกับคนบ้าในป่าไม่ได้ หลักฐานเจ้าพิสูจน์ความผิดเขา นำให้ Commander Ebonlocke ทันที แล้วเล่าที่ค้นพบ!" },
        progress = { "21:854778234:657323739 C 184:1160763137:1820644858", "หวังว่าสำคัญ {class} ให้ดูแล้วเล่า แต่ด้วยแสงสว่าง รีบหน่อย การป้องกัน Darkshire มาก่อน ข้าไม่มีเวลาเปลืองกับเบาะแสทางตัน" },
        completion = { "54:792963521:1609199902 C 1:46:46", "โอ้ เจ้าพิสูจน์ว่าเป็นนักสืบเก่งทีเดียว {class}" },
        required = { [938] = { "19:409364914:1395772439", "หน้าบันทึกเปื้อนโคลน" } },
        steps = { { "19:409364914:1395772439", "หน้าบันทึกเปื้อนโคลน" } },
    },
    [80] = { -- The Legend of Stalvan
        title = { "21:1356682843:1288115968", "ตำนาน Stalvan" },
        objective = { "48:1835726841:217817603", "ให้ Clerk Daltry ดู Bloodstained Journal Page" },
        description = { "342:113667097:494666267", "ข้าจับตา Stalvan เจ้าคนน่าขนลุกมาพักใหญ่ หากหน้านี้ลายมือเดียวกัน ก็พิสูจน์ความผิดไร้ข้อสงสัย\n\nClerk Daltry ทำทะเบียนเมืองมานานจนชำนาญลายมือ ให้ดูหน้านี้ว่าตรงลายเซ็นทะเบียนไหม" },
        progress = { "12:1977868436:1919340288 N 29:24592766:1777185598", "มาอีกแล้ว {name}? คราวนี้มีอะไร?" },
        completion = { "85:64163560:613675455", "ใช่แล้ว! ลายมือหน้านี้ตรงลายเซ็นทะเบียนจริง" },
        required = { [939] = { "27:661206944:1265894186", "หน้าบันทึกเปื้อนเลือด" } },
        steps = { { "27:661206944:1265894186", "หน้าบันทึกเปื้อนเลือด" } },
    },
    [90] = { -- Seasoned Wolf Kabobs
        title = { "20:1371246250:221317661", "เนื้อหมาป่าเสียบไม้ปรุงรส" },
        objective = { "95:1460884061:1708912003", "รวบรวม Lean Wolf Flank 10 ชิ้นกับ Stormwind Seasoning Herbs แล้วกลับไปหา Chef Grual ที่ Darkshire", variants = { { "65:2020392999:435824666", "รวบรวม Lean Wolf Flank 10 ชิ้นแล้วกลับไปหา Chef Grual ที่ Darkshire" } } },
        description = { "354:1700915996:386455805", "เนื้อหมาป่าเสียบไม้ปรุงรสเป็นของโปรดประจำร้าน! ได้ ข้าทำให้ แต่ต้องมีเสบียงก่อน นำ Lean Wolf Flank 10 ชิ้นกับ Stormwind Seasoning Herbs มา หมาป่าในป่ามาก หาเนื้อคงไม่ยาก ส่วนสมุนไพรหา Felicia Gump ที่ร้านดอกไม้ Canal District ใน Stormwind", variants = { { "355:240126873:758867392", "เนื้อหมาป่าเสียบไม้ปรุงรสเป็นของโปรดประจำร้าน! ได้ ข้าทำให้ แต่ต้องมีเสบียงก่อน นำ Lean Wolf Flank 10 ชิ้นมา หมาป่าในป่ามาก หาเนื้อคงไม่ยาก โชคดีสำหรับเจ้า ข้าเพิ่งรับ Stormwind Seasoning Herbs ชุดล่าสุดแล้ว จึงต้องการแค่เนื้อเพื่อเริ่มทำ" } } },
        progress = { "93:593056997:13893406", "หา Lean Wolf Flank 10 ชิ้นได้หรือยัง? แล้วสมุนไพรจาก Felicia ใน Stormwind ล่ะ?", variants = { { "46:1919741418:1083167856", "เจ้าเจอเนื้อสีข้างหมาป่าไม่ติดมันครบ 10 ชิ้นหรือยัง?" } } },
        completion = { "16:1810689714:1485155155 N 50:1415862706:912660700", "ทำได้ดี {name}! ขอให้อร่อยกับ Seasoned Wolf Kabob!" },
        required = { [1015] = { "15:1035337332:183485448", "เนื้อสีข้างหมาป่าไร้มัน" } },
        steps = { { "15:1035337332:183485448", "เนื้อสีข้างหมาป่าไร้มัน" } },
    },
    [93] = { -- Dusky Crab Cakes
        title = { "16:1863440342:230405802", "เค้กปูยามสนธยา" },
        objective = { "69:2112867022:1744181333", "รวบรวม Gooey Spider Leg 6 ชิ้นไปให้ Chef Grual ที่ Darkshire" },
        description = { "351:1416477325:605326793", "จะบอกความลับนิด Dusky “Crab” Cake ทำจากขาแมงมุมจริง ๆ! รู้ว่าน่าขยะแขยง แต่รสเปรี้ยวกลมกล่อมอร่อย เป็นของว่างดี! นำ Gooey Spider Leg มา ข้าจะทำให้สักหน่อย\n\nได้ยินว่าหาจาก Venom Web Spider ได้ดี พวกมันทำรังทางเหนือ ระหว่างเชิงเขากับแม่น้ำ" },
        progress = { "6:1136836709:1914036474 N 42:243588467:1135480339", "สวัสดี {name} ได้ Gooey Spider Leg หรือยัง?" },
        completion = { "300:662073221:181386183", "อา ขาสวยดี! ขอปรุงเครื่องเทศลับก่อน ห้ามแอบดู! แล้วให้มันวิ่งอยู่บนกระทะพักหนึ่ง...\n\nแม้ Dusky Crab Cake เป็นเมนูพิเศษที่ข้าไม่แจกสูตร แต่นี่สูตรจานที่ดีเกือบเท่ากัน" },
        required = { [2251] = { "16:452102975:1797389952", "ขาแมงมุมเหนียวหนึบ" } },
        steps = { { "16:452102975:1797389952", "ขาแมงมุมเหนียวหนึบ" } },
    },
    [95] = { -- Sven's Revenge
        title = { "14:1770148845:637289594", "การล้างแค้นของ Sven" },
        objective = { "64:1708159146:806631457", "ไป Sven's Farm แล้วหาสิ่งที่ฝังหลังตอไม้เก่า" },
        description = { "500:432285344:127053302", "ข้าเคยทำไร่ทางตะวันออกเฉียงใต้... จน Dark Riders จาก Deadwind Pass ลงมาฆ่าครอบครัวตอนข้าไม่อยู่!\n\nเมื่อกลับ เห็นร่างเงาย่องใกล้ยุ้งฉางฝังบางอย่าง เขาหนีก่อนจับได้ ข้าหยุดไม่ได้เพราะต้องรีบตาม Dark Riders จึงไม่รู้ว่าซ่อนอะไร\n\nหากหาสิ่งที่เขาฝังได้ ข้าจะขอบใจ จุดซ่อนอยู่หลังตอไม้เก่าใกล้ยุ้งฉาง" },
        completion = { "114:1803529370:1087602227", "กองดินพูนอย่างรีบร้อนอยู่ที่นี่ ราวมีคนต้องซ่อนอะไร... โดยมีเวลาน้อย" },
    },
    [101] = { -- The Totem of Infliction
        title = { "23:1292669959:2026259609", "โทเทมตอบโต้" },
        objective = { "97:207675:1329859921", "นำ Ghoul Fang 10 ชิ้น, Skeleton Finger 10 ชิ้น และ Vial of Spider Venom 5 ขวดไปให้ Madame Eva ที่ Darkshire" },
        description = { "93:1370494661:2086494080 N 148:566090547:731466455 C 184:1246348035:355719126", "เมื่อมลทินเวทคืบป่า การป้องกันตนจำเป็นแน่ {name} สายลมกระซิบบอกภัยใหญ่ที่อดทนรอเจ้าในอนาคตใกล้\n\nหากอยากคุ้มครองตน {class}ผู้สูงศักดิ์ นำเขี้ยวกูล 10 ชิ้น นิ้วโครงกระดูก 10 ชิ้น และพิษแมงมุม 5 ขวดมา ข้าจะลงมนตร์ Totem of Infliction ให้ทำร้ายผู้คิดใช้ความรุนแรงกับเจ้า" },
        progress = { "182:400135552:1452783239", "นำเขี้ยวกูล 10 ชิ้น นิ้วโครงกระดูก 10 ชิ้น และพิษแมงมุม 5 ขวดมา ข้าจะลงมนตร์ Totem of Infliction ให้ทำร้ายผู้คิดใช้ความรุนแรงกับเจ้า" },
        completion = { "18:576966759:2038135080 N 207:1661930366:1693628552 C 87:1620189265:1819308070", "ฉลาดมาก {name} Totem of Infliction จะช่วยคุ้มครองจากความชั่วที่ซ่อนทั่ว Azeroth และไกลกว่านั้น หากรู้สึกถูกคุกคาม จงถือโทเทมและอุ่นใจในออร่าเวท จงกล้า {class}ผู้ดีงาม เจ้าต้องรวบรวมความกล้าทั้งหมด เพราะข้าเห็นการนองเลือดมากในอนาคตเจ้า" },
        required = { [1129] = { "10:695135569:458391949", "เขี้ยวกูล" }, [1130] = { "20:1443868925:1101972784", "ขวดบรรจุพิษแมงมุม" }, [2378] = { "15:1566238968:316309751", "นิ้วโครงกระดูก" } },
        steps = { { "10:695135569:458391949", "เขี้ยวกูล" }, { "20:1443868925:1101972784", "ขวดบรรจุพิษแมงมุม" }, { "15:1566238968:316309751", "นิ้วโครงกระดูก" } },
    },
    [133] = { -- Ghoulish Effigy
        title = { "15:1131237937:804880021", "หุ่นขู่กูล" },
        objective = { "63:1498787137:1313394744", "รวบรวม Ghoul Rib 7 ชิ้นให้ Abercrombie ที่กระท่อม" },
        description = { "444:1997402205:112552785", "ข้าอยู่ไกลการคุ้มครองเมือง น่าแปลกที่กูลกับศพเดินได้ยังไม่กิน! เมื่อวานฝูง Bone Chewer ยังทุบผนังบ้าน!\n\nอยากทำหุ่นขู่คล้ายหุ่นไล่กาสำหรับกูล ต้องใช้ Ghoul Rib หาจาก Flesh Eater, Bone Chewer, Brain Eater, Rotted One และ Plague Spreader\n\nนำซี่โครงให้ ข้าจะจ่ายเหรียญตอบแทน" },
        progress = { "144:1058559376:1942238885", "เหมือนได้ยินกูลวิ่งหลังบ้าน ต้องตั้งหุ่นเร็ว ๆ! ได้ Ghoul Rib ให้ข้าหรือยัง?" },
        completion = { "41:1674841458:1988296600", "อา ขอบใจ ใช้ได้พอดี!" },
        required = { [884] = { "9:1123199084:36492152", "ซี่โครงกูล" } },
        steps = { { "9:1123199084:36492152", "ซี่โครงกูล" } },
    },
    [134] = { -- Ogre Thieves
        title = { "12:1568543451:478999553", "โจรโอเกอร์" },
        objective = { "42:817814087:449567018", "คืน Abercrombie's Crate ให้ Abercrombie" },
        description = { "311:637217099:2010741768 N 50:1449755626:950931987", "หลายสัปดาห์ก่อน ข้าเก็บสมุนไพรไกลบ้านแล้วโอเกอร์โจมตี! ต้องหนี ทิ้งลังเครื่องมือกับสมุนไพรมีค่า\n\nไล่ข้าแล้วพวกมันกลับเนินโอเกอร์ทางใต้ Duskwood ลังคงใกล้เนิน\n\nได้โปรด {name} นำลังกลับมา ข้าคิดถึงมันมาก" },
        progress = { "65:1439891516:1254314388", "มีลังข้าหรือ? ถ้ามี โปรด... ส่งให้เร็ว!" },
        completion = { "34:503496701:898576695 N 73:1120587880:1592566029", "ขอบคุณ Nec-... เอ่อ ขอบคุณเจ้า {name}! เจ้าได้ทำคุ้มรางวัลยิ่งแล้ว\n\nอาฮ่า! สุขใจ! ค่ำคืนสุขสันต์รออยู่!!" },
        required = { [1349] = { "19:951657486:386429491", "ลังของ Abercrombie" } },
        steps = { { "19:951657486:386429491", "ลังของ Abercrombie" } },
    },
    [148] = { -- Supplies from Darkshire
        title = { "23:806734067:2030835985", "เสบียงจาก Darkshire" },
        objective = { "22:319673347:1521828330", "คุยกับ Madame Eva" },
        description = { "293:539827423:698560727", "โอ้ ชายชราน่าสงสารทำอย่างไรดี? ต้องใช้ของจาก Darkshire แต่หมู่บ้านไกล ข้าแก่และอ่อนแอ... เดินทางไม่ไหวแน่\n\nไป Darkshire นำ Ghost Hair Thread กลับมาได้ไหม? หาได้จาก Madame Eva ที่บ้านตรงจัตุรัส Darkshire" },
        completion = { "143:769069963:715482532", "อา ต้องการ Ghost Hair Thread หรือ? เกรงว่าไม่มี แต่ทำให้ได้... หากหาเส้นผมผีมา" },
    },
    [149] = { -- Ghost Hair Thread
        title = { "17:1447462335:1565583959", "ด้ายผมผี" },
        objective = { "38:957778039:776372908", "นำ Spectral Comb ไปให้ Blind Mary" },
        description = { "319:1503100457:981326219", "Blind Mary เป็นวิญญาณเศร้าน่าสงสาร หลอกหลอนบ้านไร่เก่าบนเนินใต้ Darkshire\n\nนี่ รับ Spectral Comb ขอให้นางหวีผม แล้วนำหวีกลับ ข้าจะเก็บผมผีมาทำด้าย\n\nระวังด้วย ตอนนี้มีสิ่งมืดมิดซ่อนใกล้บ้าน..." },
        progress = { "149:689751450:585055141", "<สะอื้น> ได้โปรด อย่ามองข้า! ข้าควักดวงตาตนเองออกด้วยมือแล้ว แต่ยังรู้สึกสายตาท่าน!\n\nข้าอัปลักษณ์! อัปลักษณ์! โปรดมองทางอื่น!!" },
        completion = { "149:1386391484:1587267992", "อะไรนี่? หวีหรือ? งามจัง! ลื่นผ่านผมราวกับไม่ใช่เส้นแข็งเป็นสายที่น่ากลัวอย่างที่เป็น\n\nโอ้ หากมีกระจก..." },
        required = { [1453] = { "13:2074578656:18404418", "หวีวิญญาณ" } },
        steps = { { "13:2074578656:18404418", "หวีวิญญาณ" } },
    },
    [154] = { -- Return the Comb
        title = { "15:1947263:907366046", "คืนหวี" },
        objective = { "54:1566701945:1612387614", "คืน Ghost Hair Comb ให้ Madame Eva ที่ Darkshire" },
        description = { "104:1734224397:857935627", "ไม่!!!!!\n\nเอาไป เอาหวีไปให้พ้นข้า!\n\nข้าเป็นสัตว์ประหลาด ไม่มีใครเห็นว่างามอีกแล้ว!" },
        progress = { "59:1499528609:1910224514", "ข้าสัมผัสได้ว่าเจ้าพบ Blind Mary มีหวีข้าหรือ...?" },
        completion = { "128:2136016596:368930689", "ทำ Ghost Hair Thread ได้หนึ่งหลอด ยังเหลือผมอีกไม่กี่เส้น นี่เหรียญสำหรับส่วนที่เกิน" },
        required = { [1518] = { "15:1863982938:238672033", "หวีที่มีเส้นผมผีติดอยู่" } },
        steps = { { "15:1863982938:238672033", "หวีที่มีเส้นผมผีติดอยู่" } },
    },
    [156] = { -- Gather Rot Blossoms
        title = { "19:1976229101:1497393267", "เก็บ Rot Blossom" },
        objective = { "71:1670812669:1294523034", "รวบรวม Rot Blossom 8 ชิ้นไปให้ Tavernkeep Smitts ที่ Darkshire" },
        description = { "460:2045029266:2074055402", "หากนำ Rot Blossom มา ข้าจะต้ม Zombie Juice ให้\n\nมันขึ้นแปลก ๆ โดยเฉพาะได้ยินว่าพบในกะโหลก Skeletal Horror กับ Skeletal Fiend... ไม่ใช่ว่าข้าเคยเข้าใกล้พอดูหรอก!\n\nRaven Hill Cemetery กับ Tranquil Gardens มีโครงกระดูกมาก กำจัดระหว่างหาดอกไม้เสียเลย ชาว Darkshire คงขอบใจ" },
        progress = { "4:1229117181:163670253 N 44:537473335:402686946", "สวัสดี {name} มี Rot Blossom ให้ข้าหรือยัง?" },
        completion = { "282:2128801588:1658978895", "ดี ได้ Rot Blossom แล้ว ข้าจะบอก Althea Ebonlocke แห่ง Night Watch ว่าเจ้าฆ่าโครงกระดูกอยู่\n\nการรักษาชาว Darkshire เป็นภาระหนักมืดหม่น ข่าวว่าผู้อื่นช่วยต้านอสูร Duskwood เป็นข่าวดีจริง" },
        required = { [1598] = { "11:1787590375:1532461563", "ดอก Rot Blossom" } },
        steps = { { "11:1787590375:1532461563", "ดอก Rot Blossom" } },
    },
    [157] = { -- Deliver the Thread
        title = { "18:495584329:233909129", "ส่งด้าย" },
        objective = { "90:79103898:971921520", "นำ Ghost Hair Thread ให้ Abercrombie ที่กระท่อมเหนือ Raven Hill Cemetery" },
        description = { "21:144231564:1478569493 N 90:899524789:225079330", "นี่ด้าย {name} ใช้ได้สารพัด ตั้งแต่ผูกมัดวิญญาณร้ายจนเย็บชีวิตลงสิ่งไร้ชีวิต" },
        progress = { "120:581130931:375983791", "ต้องขึง Ghost Hair Thread ตามประตูกับหน้าต่างกันวิญญาณไม่พึงประสงค์ ได้ให้ข้าไหม?" },
        completion = { "50:1257316250:1145294410 N 47:277627926:1378206555", "น่ายินดี! ใช้ได้ยอดเยี่ยม...\n\nนี่ {name}ผู้ใจดี รับเป็นค่าตอบแทนการกระทำมีเกียรติ" },
        required = { [1596] = { "17:1447462335:1565583959", "ด้ายจากเส้นผมผี" } },
        objectiveLabels = {
            item = { ["Ghost Hair Thread"] = "ด้ายจากเส้นผมผี" },
        },
    },
    [158] = { -- Zombie Juice
        title = { "12:992055618:1552734456", "Zombie Juice" },
        objective = { "29:1184309012:1894948981", "คุยกับ Tavernkeep Smitts" },
        description = { "147:124298762:1315776730 N 77:1218339221:1857497749", "ข้าต้องการเหล้าชนิดหนึ่ง Zombie Juice สักขวด Tavernkeep Smitts ที่ Scarlet Raven Tavern ใน Darkshire คงมี\n\nรีบด้วย {name} กลางคืนหนาว ต้องใช้เครื่องดื่มจุดไฟในเส้นเลือดอีกครั้ง!" },
        completion = { "105:1038934045:1598424168", "ต้องการ Zombie Juice หรือ? อืม... แรงมาก ไม่ค่อยมีใครสั่ง" },
    },
    [159] = { -- Juice Delivery
        title = { "14:705031860:1546367650", "ส่งเครื่องดื่ม" },
        objective = { "51:709034272:1413599962", "นำ Zombie Juice ไปให้ Abercrombie ที่กระท่อม" },
        description = { "100:1516097965:1392126533", "นี่ Zombie Juice...\n\n...ระวังด้วย แรงพอปลุกคนตาย!" },
        progress = { "91:96762080:1170960281", "ต้องใช้ Zombie Juice อุ่นกายในคืนมืดหนาว ได้ให้ข้าไหม?" },
        completion = { "19:678798078:1196143712 N 139:693298309:2080459999", "ขอบใจพันครั้ง {name} เจ้าอุ่นหัวใจชายแก่ด้วยความโง่-... หมายถึง... ความเมตตา!\n\nนี่ สหาย รับแทนคำขอบคุณ" },
        required = { [1451] = { "22:1690541335:732879401", "น้ำยาซอมบี้หนึ่งขวด" } },
        steps = { { "22:1690541335:732879401", "น้ำยาซอมบี้หนึ่งขวด" } },
    },
    [160] = { -- Note to the Mayor
        title = { "17:1022288007:743256427", "จดหมายถึงนายกเทศมนตรี" },
        objective = { "65:1346174126:1544363260", "นำ Abercrombie's Letter ไปให้ Ello Ebonlocke นายกเทศมนตรี Darkshire" },
        description = { "192:986749420:21240707", "นำจดหมายนี้ให้ Ello Ebonlocke นายกเทศมนตรี Darkshire\n\nเราเป็นเพื่อนเก่า... เมื่ออ่านรู้ว่าเจ้าทำอะไรให้ข้า... ข้ามั่นใจว่าเขาจะสุขใจไม่แพ้ข้า! ฮ่าฮ่าฮ่า!" },
        progress = { "141:720840547:298357728", "Abercrombie...? ข้าไม่รู้จัก เจ้าบอกมีจดหมายจากคนชื่อ Abercrombie ให้ข้าหรือ?\n\nเอาล่ะ ส่งมาสิ..." },
        completion = { "88:826332366:972873912", "<Ello ดูจดหมาย...>\n\nภาษาอะไรนี่? ดูโบราณ... ข้าอ่านไม่ออก" },
        required = { [1637] = { "14:976762795:380526102", "จดหมายถึง Ello" } },
        steps = { { "14:976762795:380526102", "จดหมายถึง Ello" } },
    },
    [163] = { -- Raven Hill
        title = { "10:1156999666:742348674", "Raven Hill" },
        objective = { "37:170472046:1817659346", "หาว่าอะไรหลอกหลอน Raven Hill" },
        description = { "33:1750209357:2122097343 N 296:1942067199:191802842", "มีเรื่องผิดปกติที่ Raven Hill {name} Calor ยืนยันว่าสักคน... หรือบางสิ่ง... หลอกหลอนอาคาร เขาเห็นเงาเคลื่อนสองคืนติด คืนก่อนนั้นอีกคืนเห็นแสงในหน้าต่าง\n\nหากห่วงความปลอดภัย Duskwood อย่างที่บอก จงหาว่าอสูรใดหลอกหลอน Raven Hill" },
        completion = { "165:1247514071:656389161", "ไม่! โปรดอย่าฆ่า! แค่ข้า... Jitters!! พวกมันทุกที่... หนีไม่พ้น! อสูรใน Raven Hill? มะ... ไม่... ไม่มีทาง มีแค่ Jitters ผู้ไร้พิษสง" },
    },
    [164] = { -- Deliveries to Sven
        title = { "18:414339339:1888011131", "ส่งของให้ Sven" },
        objective = { "29:2117435150:907501296", "ส่งเสบียงให้ Sven" },
        description = { "278:537794358:2102809211", "รู้จัก Sven ไหม? นั่นผู้ทำงานแห่งแสงสว่าง! เขากับผู้ติดตามตั้งค่ายริมตะวันตกเฉียงเหนือ Duskwood\n\nคนมีน้อยจนส่งใครเข้ามารับเสบียงไม่ได้ ช่วยนำไปให้ไหม?" },
        progress = { "24:1997737349:1464224509 C 34:1963028166:1761292666", "ดูแข็งแรงนะ {class} มาร่วมการต่อสู้หรือ?" },
        completion = { "133:1004768298:1708218092", "เสบียงมีประโยชน์มาก เราซาบซึ้งความช่วยเหลือตระกูล Carevin เสมอ นี่ตอบแทนเล็กน้อย" },
        required = { [1922] = { "17:807381557:502836162", "เสบียงสำหรับ Sven" } },
        steps = { { "17:807381557:502836162", "เสบียงสำหรับ Sven" } },
    },
    [165] = { -- The Hermit
        title = { "10:1536437871:1442963303", "ฤๅษี" },
        objective = { "59:1890164125:1508307387", "ไปดูชายชราที่กระท่อมใกล้ Raven Hill Cemetery" },
        description = { "261:42319759:1221837820", "มีชายชราเคยเข้าเมืองซื้อของบ่อย แต่หายไปพักใหญ่ ถ้าจำไม่ผิดอยู่กระท่อมมองลง Raven Hill Cemetery บางทีเจ้าควรไปดูว่ามีอะไรผิดปกติไหม" },
        completion = { "217:1351208287:1377588065", "Elaine Carevin? ฮิฮิ อ้อ แน่นอน... พวก Carevin\n\nไม่ ไม่มีอะไรผิด แต่ตอนนี้เข้าเมืองยาก ถนนอันตราย ข้าก็ไม่ได้หนุ่มขึ้น บางทีช่วยชายชราสักหน่อยได้ไหม?" },
    },
    [173] = { -- Worgen in the Woods
        title = { "19:1266022834:1011093797", "วอร์เกนในป่า" },
        objective = { "61:1994901189:380978279", "สังหารวอร์เกน Nightbane Shadow Weaver 6 ตัวให้ Calor ที่ Darkshire" },
        description = { "479:796721798:740992975", "ความมืดเหมือนถูกดึงสู่ Duskwood ไม่หยุด Master Carevin มุ่งขับไล่ความชั่วและนอกรีต ความพยายามเราคุ้มครอง Darkshire\n\nคิดว่าคู่ควรร่วมเราหรือ?\n\nข้าเคยคิดเช่นเจ้า หมดศรัทธาในความนิ่งนอนใจของ Watch จึงเข้าร่วม Carevin หากพิสูจน์ตน ก็ไม่ใช่ด้วยคำพูด\n\nทดสอบฝีมือกับ Nightbane Shadow Weaver ที่ Brightwood Grove... สว่างนักล่ะ!... และ Rotting Orchard" },
        progress = { "N 21:1187090680:492877212", "{name} ล่าเป็นอย่างไร?" },
        completion = { "12:893490672:478301359 N 338:1470160158:1580172379", "น่าประทับใจ {name} ดูมีฝีมือดูแลตัวพอ อาจหาความท้าทายที่เหมาะกว่าสำหรับความสามารถเจ้าได้\n\nแต่แปลก... วอร์เกนเหมือนโผล่จากอากาศเปล่า ทว่าเมื่อมีสิ่งแปลกมากข้ามแดนมา ก็คงเป็นเพียงอีกเรื่องให้ห่วง" },
        objectiveLabels = {
            monster = { ["Nightbane Shadow Weaver slain"] = "ปราบ วอร์เกนผู้ถักทอเงา Nightbane" },
        },
    },
    [174] = { -- Look To The Stars
        title = { "17:449457544:636992844", "มองสู่ดวงดาว", variants = { { "17:1170884010:2009140246", "มองสู่ดวงดาว" } } },
        objective = { "71:133580757:456075944", "Viktori Prism'Antras ที่ Darkshire ต้องการ Bronze Tube" },
        description = { "301:1530542552:971279067", "Cog เพื่อนโนมสัญญาช่วยสร้างเครื่องมองดาว มีความจริงเหนือเวทมนตร์ที่อธิบายป่าเปลี่ยนประหลาดได้\n\nนำ Bronze Tube จากวิศวกรชำนาญมา ตามแบบ Cog นั่นขั้นแรก" },
        progress = { "62:1739836211:1869019521", "พบวิศวกรชำนาญทำ Bronze Tube หรือยัง?" },
        completion = { "17:1552185832:722447846 N 29:792066271:1687957157", "เหมาะพอดี {name} ขั้นแรกเสร็จ!" },
        required = { [4371] = { "11:1255316179:1794554443", "ท่อสำริด" } },
        steps = { { "11:1255316179:1794554443", "ท่อสำริด" } },
    },
    [175] = { -- Look To The Stars
        title = { "17:449457544:636992844", "มองสู่ดวงดาว", variants = { { "17:1170884010:2009140246", "มองสู่ดวงดาว" } } },
        objective = { "83:461090878:640895924", "หา Mary แล้วโน้มน้าวให้มอบสิ่งที่สะท้อนแสงสำหรับโครงการ Viktori" },
        description = { "342:246601529:10589999", "ตามแบบ Cog ตอนนี้ต้องการวิธีสะท้อนแสง จำหญิงชื่อ Mary ได้ ขึ้นชื่อว่าพกกระจกเสมอ ลองตามหาว่ายอมให้ยืมพื้นผิวสะท้อนแสงทำโครงการไหม? เชื่อว่าเคยอยู่ Duskwood ตอนใต้..." },
        completion = { "39:178715351:100825513", "ใช่ ข้าเคยมีกระจก" },
    },
    [177] = { -- Look To The Stars
        title = { "17:449457544:636992844", "มองสู่ดวงดาว", variants = { { "17:1170884010:2009140246", "มองสู่ดวงดาว" } } },
        objective = { "94:1757777997:397517075", "นำ Blind Mary's Looking Glass จาก Insane Ghoul ไปให้ Viktori ที่ Darkshire" },
        description = { "279:637735534:269192951", "กระจกเคยเป็นของรักที่สุดจน... เกิดเหตุนั้น หลังจากนั้นข้าทิ้งหลังยุ้งฉาง มี Insane Ghoul เดินแถวนั้น บางทีเก็บไป เล่าว่าสัตว์ปีศาจนั้นอยู่ Tranquil Gardens Cemetery" },
        progress = { "118:297594712:668409610", "ข้าให้ Cog ดูเครื่องดูดาวที่เริ่มทำ เขาประทับใจ พบอุปกรณ์สะท้อนแสงไหม?" },
        completion = { "51:311690043:1438566772", "เยี่ยมที่สุด! ใช้ได้สมบูรณ์แบบ ขอบใจมาก!" },
        required = { [1946] = { "20:1154185041:955892328", "กระจกส่องหน้าของ Mary" } },
        steps = { { "20:1154185041:955892328", "กระจกส่องหน้าของ Mary" } },
    },
    [181] = { -- Look To The Stars
        title = { "17:449457544:636992844", "มองสู่ดวงดาว", variants = { { "17:1170884010:2009140246", "มองสู่ดวงดาว" } } },
        objective = { "103:1762365988:362276486", "หา Zzarc'Vul ที่เนินโอเกอร์ทางใต้ Duskwood แล้วนำแว่นตาข้างเดียวของเขากลับไปให้ Viktori ที่ Darkshire" },
        description = { "354:2105622967:954004552", "เหลือของอีกอย่างให้เครื่องสมบูรณ์ แบบ Cog ต้องใช้เลนส์ เลนส์เดียวที่รู้ว่าใหญ่พอคงหายากมาก\n\nโอเกอร์ชื่อ Zzarc'Vul อยู่เนินใต้ Duskwood หากทำได้ นำแว่นตาข้างเดียวให้ข้า จะใช้เป็นเลนส์!" },
        progress = { "78:1173510331:1751715275", "โน้มน้าว Zzarc'Vul ให้ยืมแว่นตาข้างเดียวทดลองได้ไหม?" },
        completion = { "55:725725794:614508527 N 37:984798489:550408282", "ในที่สุดเครื่องดูดาวสมบูรณ์! ขอบใจ {name} ทีนี้ค้นคว้าต่อได้..." },
        required = { [1968] = { "14:584327050:1859036355", "แว่นตาข้างเดียวของโอเกอร์" } },
        steps = { { "14:584327050:1859036355", "แว่นตาข้างเดียวของโอเกอร์" } },
    },
    [221] = { -- Worgen in the Woods
        title = { "19:1266022834:1011093797", "วอร์เกนในป่า" },
        objective = { "60:1600028641:600788039", "สังหารวอร์เกน Nightbane Dark Runner 12 ตัวให้ Calor ที่ Darkshire" },
        description = { "348:1549672810:986358658", "คงสังเกตวอร์เกนใหญ่กว่าที่เดินกับ Shadow Weaver ในป่า? เท่าที่รู้ Dark Runner เป็นกำลังส่วนใหญ่\n\nข้าออกสำรวจเห็นมันยึด Rotting Orchard ตะวันตกเฉียงใต้เมือง แข็งแกร่งกว่าพวกก่อนที่เจ้าเจอ\n\nจงระวังตัว" },
        progress = { "14:1903246608:847744056 N 53:1581681981:491078099", "กลับเร็วเชียว {name} หวังว่าไม่ได้มาบอกว่ายอมแพ้" },
        completion = { "45:851570746:647723138 N 310:1112941235:1387177051", "เจ้าสู้ Dark Runner ได้ดี {name} แต่จำนวนเหมือนไม่มีวันหมด คืบหน้าเมื่อไรก็มีเพิ่มมาแทน\n\nพลังชั่วใดดึงมันมา? ทำไมต้องรบกวนแดนทุกข์เรา...\n\nข้าจะเชื่อมั่น Master Carevin เขาคงไขต้นเหตุได้แน่" },
        objectiveLabels = {
            monster = { ["Nightbane Dark Runner slain"] = "ปราบ วอร์เกนนักวิ่งในความมืด Nightbane" },
        },
    },
    [222] = { -- Worgen in the Woods
        title = { "19:1266022834:1011093797", "วอร์เกนในป่า" },
        objective = { "85:1938319304:63513877", "สังหารวอร์เกน Nightbane Vile Fang 8 ตัวและ Nightbane Tainted One 8 ตัวให้ Calor ที่ Darkshire" },
        description = { "374:1065497095:1626362221", "ผลงานก่อนทำให้เชื่อว่าเจ้าพร้อมรับวอร์เกนแข็งแกร่งที่สุดที่ยึดป่า\n\nในพวกตั้งบ้านใหม่ที่นี่ Vile Fang กับ Tainted One อันตรายที่สุด อยู่แถวถ้ำและเหมืองทางใต้\n\nเห็นแสงกองไฟได้แม้จากไกล..." },
        progress = { "51:1669813082:1646926037 N 48:1524927727:1128053230", "น่าข่มขวัญใช่ไหม? แต่อย่ากลัว {name} ผู้ยืนเพื่อแสงสว่างไม่มีวันล้ม!" },
        completion = { "N 94:106804311:290202699 C 142:246027928:1076409371", "{name} พูดตรง ๆ ข้าไม่คิดว่าจะมาถึงนี่ แต่เจ้าคือ{class}ที่ประมาทไม่ได้ หากอยากร่วมศึก Master Carevin อย่างเป็นทางการ ข้ายินดีเขียนจดหมายแนะนำ" },
        objectiveLabels = {
            monster = { ["Nightbane Vile Fang slain"] = "ปราบ วอร์เกนเขี้ยวอัปรีย์ Nightbane", ["Nightbane Tainted One slain"] = "ปราบ วอร์เกนแปดเปื้อน Nightbane" },
        },
    },
    [223] = { -- Worgen in the Woods
        title = { "19:1266022834:1011093797", "วอร์เกนในป่า" },
        objective = { "39:962231509:428103083", "นำ Calor's Note ไปให้ Jonathan Carevin" },
        description = { "13:939218444:1640774044 N 237:1725491312:1855849588", "นี่ {name} นำสารให้ Master Carevin\n\n<เขารีบหยิบแผ่นหนังเลือนแล้วยื่นให้>\n\nมีคนอย่างเจ้าอีกไม่กี่คน เราจะมากกว่า Night Watch! บางทีจึงทำงานที่คนน้อยอย่างเราสานต่อวันนี้ให้เสร็จได้" },
        progress = { "67:866539857:1722530287", "มีอะไร? รีบพูด ข้ามีงานเร่ง" },
        completion = { "33:614729155:878776598 N 212:813486548:1017049849 N 233:147115411:411622036", "ขอโทษที่ต้อนรับเย็นชา {name} คงเห็นว่าข้ายุ่งมาก เจ้าได้ใจ Calor ซึ่งไม่ใช่งานเล็ก และเขาให้คำแนะนำมา\n\nมีคนไม่น่าไว้ใจเคลื่อนไหว {name} เราต้องใช้ผู้พิสูจน์ตนแล้วทั้งหมด ต่อสู้ปีศาจ อันเดด และผู้ช่วยมัน จงตื่นตัว ระวัง อย่าไว้ใจใครที่ไม่ช่วยอุดมการณ์เรา\n\nเกียรติภายใต้แสงสว่าง" },
        required = { [2113] = { "12:209165624:1423669108", "ข้อความของ Calor" } },
        steps = { { "12:209165624:1423669108", "ข้อความของ Calor" } },
    },
    [225] = { -- The Weathered Grave
        title = { "19:669105532:216179749", "หลุมศพผุกร่อน" },
        objective = { "39:600405032:1418943780", "คุยกับ Sirra Von'Indi ที่ Darkshire" },
        description = { "216:1081320104:1717338558", "ป้ายหลุมเก่าผุกร่อนเขียนเพียง\n\nMORGAN LADIMORE\n\n<ตรวจต่อพบดินเหนือหลุมถูกรบกวนไม่นาน และดูเหมือนดินจำนวนมากถูกย้ายออก...>" },
        completion = { "307:1174343575:1557288117", "Morgan Ladimore?\n\nอา แน่นอน เรื่องเขายาวและเศร้า ข้ารู้จักก่อนออกสงคราม แต่นั่นครั้งสุดท้ายที่เห็น เป็นคนสูงศักดิ์ดีงาม แต่จบเลวร้าย\n\nข้าคงมีอะไรเล่าได้ดีกว่าความจำตน..." },
    },
    [226] = { -- Wolves at Our Heels
        title = { "19:1551880581:897886534", "หมาป่าไล่หลัง" },
        objective = { "123:813233724:1220245748", "สังหาร Starving Dire Wolf 12 ตัวและ Rabid Dire Wolf 8 ตัว แล้วกลับไปหา Lars ที่ Sven's Camp ริมตะวันตก Duskwood" },
        description = { "486:2114592291:651512138", "วันข้างหน้าข้ากับ Sven อันตราย มีจอมเวทปลุกศพทางตะวันออก อยู่ลำพังต้องล่าอาหารเอง ทุกครั้งแบกเนื้อกลับค่าย หมาป่ายักษ์หิวโหยหรือคลั่งก็ออกจากป่าหวังแย่ง อยู่ที่นี่งานอันตรายจริง!\n\nหากกำจัดหมาป่าบ้าง เราคงง่ายขึ้น มันเดินเหนือกับตะวันออกใกล้แม่น้ำ" },
        progress = { "28:1073280700:1152729403", "ยังล่าหมาป่าอยู่หรือ...?" },
        completion = { "270:781984917:1774713037", "ดี เจ้าลดฝูงมาก เมื่อไม่มีหมาป่างับส้นเท้า เราก็ตั้งใจจัดการ Morbent Fel ได้\n\nรับ Flash Bundle ไปหน่อย เมืองทำแล้วบริจาค Sven มากเพื่อช่วยอุดมการณ์" },
        objectiveLabels = {
            monster = { ["Starving Dire Wolf slain"] = "ปราบ ไดร์วูล์ฟที่หิวโหย", ["Rabid Dire Wolf slain"] = "ปราบ ไดร์วูล์ฟคลุ้มคลั่ง" },
        },
    },
    [227] = { -- Morgan Ladimore
        title = { "15:235027059:482532477", "Morgan Ladimore" },
        objective = { "51:1698236361:89361727", "คุยกับ Commander Althea Ebonlocke ที่ Darkshire" },
        description = { "191:704689977:913689330", "<เขาค้นชั้นแล้วหยิบหนังสือปกหนัง>\n\nหากอยากรู้เพิ่ม ถาม Althea นางเป็นคนจัดการ... ปัญหา... เกี่ยวกับเขาช่วงนี้" },
        completion = { "492:1441734825:1335717424", "Morgan Ladimore? ไม่เคยได้ยิน...\n\nอ้อ หมายถึง Mor'Ladim! ยังไม่รู้เรื่องหรือ?\n\nเล่าสั้น ๆ อันเดดเร่ร่อนเรียกตัว Mor'Ladim เดินทั่ว Duskwood เท่าที่รู้ดูเป็นร่างอันเดดของ Morgan Ladimore ที่เจ้าคงรู้จัก ก่อปัญหามาก โจมตียามลาดตระเวนและฆ่าคน\n\n<นางพิจารณาเจ้า>\n\nดูมีฝีมือพอ บางทีเจ้าช่วยให้เขาพักสงบได้" },
    },
    [228] = { -- Mor'Ladim
        title = { "9:1730038979:1141477696", "Mor'Ladim" },
        objective = { "81:209545311:982559483", "สังหาร Mor'Ladim แล้วนำกะโหลกกลับไปให้ Commander Althea Ebonlocke ที่ Darkshire" },
        description = { "268:683264276:1836801837", "หน่วยสอดแนมบอก Mor'Ladim เดินทั่ว Duskwood ตามเส้นคดเคี้ยวแปลกผ่านสุสาน เราฝังเขาเลยบ้านบนเนินไป รู้ที่ไหม?\n\nข้าช่วยอะไรไม่ได้ แต่ขอให้โชคดี" },
        progress = { "53:147564478:826599193 N 61:395127414:1202741687", "ไม่โทษหากรับมือยาก {name} Watcher แข็งแกร่งที่สุดบางคนตายเพราะ Mor'Ladim" },
        completion = { "48:2080195338:110078074 N 116:2098429441:1063822411", "เจ้าฆ่าเขาแล้วหรือ? ไม่ใช่งานเล็ก {name}! ในนามชาว Darkshire และ Night Watch ข้าขอบใจ\n\nอา... แต่มีเรื่องเล็กอีกอย่าง..." },
        required = { [3514] = { "17:106588055:151714790", "กะโหลกของ Mor'Ladim" } },
        steps = { { "17:106588055:151714790", "กะโหลกของ Mor'Ladim" } },
    },
    [229] = { -- The Daughter Who Lived
        title = { "22:1980924055:945640228", "ลูกสาวที่ยังมีชีวิต" },
        objective = { "47:1738857093:1184500655", "คุยกับ Watcher Sarah Ladimore ที่ Darkshire" },
        description = { "307:1450774171:1614100920", "ควรบอกก่อนหน้านี้...\n\nจะพูดอย่างไร...\n\nMorgan อาจเชื่อว่าครอบครัวตายหมด แต่จริง ๆ Sarah Ladimore ลูกสาวเป็น Watcher อยู่ตอนนี้ นางทุกข์ใจกับ... เหตุการณ์... รอบการตายพ่อเสมอ บางทีเจ้าไปแจ้งข่าวนางได้" },
        completion = { "145:467636608:1820506801", "ว่าอย่างไร? พ่อข้า...\n\n<นางหลุบตา>\n\nข้าหวัง... ว่าจะทำอะไรให้พ่อได้... หากได้คุยก่อนพ่อจะ..." },
    },
    [230] = { -- Sven's Camp
        title = { "11:1807757879:564559990", "ค่ายของ Sven" },
        objective = { "40:1104527379:542837740", "นำ Book from Sven's Farm ไปให้ Sven" },
        description = { "136:1480220880:862644087", "ขุดกองดินพบหนังสือเล็กเปื้อนดิน\n\nไม่มีชื่อ แต่... มีข้อมูลที่ Sven อยากรู้" },
        progress = { "41:1914999351:700870846", "เจ้าพบอะไรนะ?? โปรดให้ข้าดู..." },
        completion = { "186:404516960:1760359883", "<Sven อ่านแล้วปิดหนังสือดังปัง>\n\nร่างเงาที่เห็นคือพยานการตายครอบครัวข้า! ข้าอยากถามเขาหลายอย่าง... หากเพียงรู้ว่าใคร!" },
        required = { [2161] = { "21:1191186410:338138041", "หนังสือจากฟาร์มของ Sven" } },
        steps = { { "21:1191186410:338138041", "หนังสือจากฟาร์มของ Sven" } },
    },
    [231] = { -- A Daughter's Love
        title = { "17:1827646967:1369664394", "ความรักของลูกสาว" },
        objective = { "54:2039567211:2109267930", "นำแหวนของ Sarah Ladimore ไปยังหลุมศพ Morgan Ladimore" },
        description = { "272:899039007:454007282 N 1:46:46", "นี่ นำไปวางหลุมพ่อ บางที... อย่างใด... พ่อจะรู้ว่าข้ายังสบายดี และเราไม่โทษพ่อเรื่องที่เกิด\n\n<นางน้ำตาคลอ ถอดแหวนจากมือขวาแล้วกดลงมือเจ้า>\n\nและ... ขอบใจ {name}" },
        progress = { "14:515971738:182915834", "ปล่อยข้าไว้..." },
        completion = { "133:383121142:1750790536 N 223:1441175751:1481219069", "<เสียงผีดังมาตามลม...>\n\nนี่คือ...? Sarah? ยังมีชีวิตหรือ? ภาระหลุดจากบ่าแล้ว...\n\n{name} รับดาบ Archeus เมื่อวิญญาณพักสงบ ข้าก็ไม่ต้องใช้อีก มันถูกตีเพื่อความดี แม้ข้าไม่คู่ควรถือ บางทีเจ้าสืบแสงสว่างผ่านมันได้\n\nLys ที่รัก...", variants = { { "133:383121142:1750790536 N 271:938489996:1034122121", "<เสียงผีดังมาตามลม...>\n\nนี่คือ...? Sarah? ยังมีชีวิตหรือ? ภาระหลุดจากบ่าแล้ว...\n\n{name} รับดาบ Archeus เมื่อวิญญาณพักสงบ ข้าก็ไม่ต้องใช้อีก มันถูกตีเพื่อความดี แม้ข้าไม่คู่ควรถือ บางทีเจ้าสืบแสงสว่างผ่านมันได้ เก็บแหวนไว้ด้วยเถิด ข้าไม่คู่ควรกับมันอีกแล้ว\n\nLys ที่รัก..." } } },
        required = { [2162] = { "12:1703268920:1770210536", "แหวนของ Sarah" } },
        steps = { { "12:1703268920:1770210536", "แหวนของ Sarah" } },
    },
    [240] = { -- Return to Jitters
        title = { "17:1297964862:2000116886", "กลับไปหา Jitters" },
        objective = { "44:630744592:1444382251", "กลับไปหา Jitters พร้อม Dusky Crab Cake" },
        description = { "41:1337004605:1597859444", "นี่เลย เค้ก “ปู” สูตร Grual!" },
        progress = { "N 37:2039148832:79629476", "{name} มาแล้ว! มีอาหารข้าหรือ?!?" },
        completion = { "16:2040048014:1005415695 N 71:1233229407:2032195511", "อาฮ่า! ขอบใจ {name} ถูกใจจริง!\n\nนี่ ให้ข้าจ่ายค่าอาหารด้วย!" },
        required = { [2250] = { "16:1863440342:230405802", "ทอดมันปู Dusky" } },
        steps = { { "16:1863440342:230405802", "ทอดมันปู Dusky" } },
    },
    [245] = { -- Eight-Legged Menaces
        title = { "20:1228549161:55570690", "ภัยแปดขา" },
        objective = { "83:1459988861:920951973", "สังหาร Pygmy Venom Web Spider 15 ตัว แล้วรายงาน Watcher Dodds ที่ Duskwood" },
        description = { "6:1136836709:1914036474 C 463:1225501597:914825114", "สวัสดี {class} คงเห็นแมงมุมยึดชายแดนตะวันตก? ภัยแปดขาหนักเกินเรา ผู้บัญชาการไม่มีคนส่งไกล Darkshire\n\nไม่อยากขอ แต่เจ้าดูจัดการไหว สัญญาของมีค่ามากไม่ได้ แต่ให้รางวัลได้หากช่วยกำจัดแมลงสกปรก\n\nอ้อ คำแนะนำ พยายามหลบพิษมัน" },
        progress = { "282:828213721:1348999040", "ระวังเวลาเจอแมงมุม ข้าเสียคนไปหลายคน เชื่อเถอะ ไม่น่าดูเมื่อคนห้อยหัวในใยหลังพิษเริ่มทำร่างอ่อนยุ่ย\n\nข้าไม่อยากให้แมลงกินเจ้าเป็นอาหารกลางวัน" },
        completion = { "72:1213786548:250349225 N 85:1055506364:158553460", "อา กลับมา ดูไม่บอบช้ำเกินไป แน่นอน {name} Night Watch ขอบใจงานเจ้า ข้าสัญญารางวัลไว้ นี่" },
        objectiveLabels = {
            monster = { ["Pygmy Venom Web Spider slain"] = "ปราบ แมงมุมใยพิษแคระ" },
        },
    },
    [251] = { -- Translate Abercrombie's Note
        title = { "28:1155686805:294391165", "แปลจดหมาย Abercrombie" },
        objective = { "43:66740988:568659847", "นำ Letter to Ello ไปให้ Sirra Von'Indi" },
        description = { "146:1839838315:1970963177", "นำจดหมายที่ให้ข้าไป Sirra Von'Indi เขารู้ภาษาและศาสตร์โบราณมาก หากมีใครแปลสารได้ ก็เขา" },
        progress = { "140:533921709:1664185323", "จดหมายจาก Abercrombie ฤๅษีหรือ? ข้าไม่รู้จัก แต่หากอยู่สุสาน สมองคงเน่าไปแล้ว!" },
        completion = { "38:971451764:1014978875", "<Sirra เริ่มแปลจดหมาย...>" },
        required = { [1637] = { "14:976762795:380526102", "จดหมายถึง Ello" } },
        steps = { { "14:976762795:380526102", "จดหมายถึง Ello" } },
    },
    [252] = { -- Translation to Ello
        title = { "19:249299759:1811339246", "ส่งคำแปลให้ Ello" },
        objective = { "50:561299605:1811125592", "นำ Translated Letter ไปให้ Lord Ello Ebonlocke" },
        description = { "219:837713825:472574161", "โอ้! หากจดหมายจริง Abercrombie ทำบางอย่าง... ไม่อาจเอ่ย\n\nรีบนำคำแปลคืน Ello\n\nเร็วด้วย กลัวว่าหายนะกำลังเดินอุ้ยอ้ายเข้ามาเมืองแล้ว..." },
        progress = { "52:789364557:1893647394", "อา แปลแล้วหรือ? โปรดให้ดู..." },
        completion = { "225:317810492:468807377", "<Ello อ่านจดหมาย หน้าซีดแล้วมองเจ้า...>\n\nแม้เจ้าช่วย Abercrombie ด้วยเมตตา การกระทำกลับนำหายนะมาเมือง\n\n<Ello จมในความคิด...>" },
        required = { [1656] = { "17:224601824:836352637", "จดหมายที่แปลแล้ว" } },
        steps = { { "17:224601824:836352637", "จดหมายที่แปลแล้ว" } },
    },
    [253] = { -- Bride of the Embalmer
        title = { "21:2132063212:205200124", "เจ้าสาวของผู้ดองศพ" },
        objective = { "90:791583791:1237312238", "หาหลุมศพ Eliza นำ Embalmer's Heart จากนางกลับไปให้ Ello Ebonlocke" },
        description = { "484:939892794:211744569", "Embalmer เป็นชื่อในนิทานเด็ก เคยเป็นนักเล่นแร่แปรธาตุใจดี แต่ภรรยา Eliza ตายจนเสียสติ เพื่อคืนชีวิต เขาใช้มนตร์มืดวางหัวใจตนในอกภรรยาที่ตาย\n\nEliza ฟื้น... แต่ถูกสาปหิวเนื้อมนุษย์ Embalmer จึงต้องฝังนางไว้\n\nหัวใจคือพลังเขา หาหลุมภรรยา นำหัวใจมาให้ขณะยังเต้น ทำแล้วพลังเขาจะแตกสลาย" },
        progress = { "67:459808346:870141424", "พบหลุม Eliza หรือยัง? มีหัวใจ Embalmer ไหม?" },
        completion = { "179:1390051532:1227747818 N 46:1033286780:242514", "ทำได้แล้ว! เวทในหัวใจจะต้านความชั่ว Embalmer และคุ้มครอง Darkshire อย่างทรงพลัง\n\nเจ้าทำสิ่งยิ่งใหญ่แก่ประชาชน {name} ชื่อจะอยู่ในพงศาวดารตลอดไป" },
        required = { [2382] = { "20:1602332455:2062967572", "หัวใจของ Embalmer" } },
        steps = { { "20:1602332455:2062967572", "หัวใจของ Embalmer" } },
    },
    [254] = { -- Digging Through the Dirt
        title = { "24:1357071913:565463557", "ขุดผ่านผืนดิน" },
        completion = { "253:914952678:592512288", "เจ้าขุดดินค่อนข้างหลวมบนหลุม... พบซากโลง\n\nในโลงรู้สึกแรงสั่นจากนิ้วเล็บขูดกับเสียงฟันผุขบ...\n\nจะเปิดโลงนำหัวใจ Embalmer หรือไม่?" },
    },
    [262] = { -- The Shadowy Figure
        title = { "18:386697929:877897585", "บุคคลในเงามืด" },
        objective = { "77:1264835687:384140869", "นำหนังสือที่พบ Sven's Farm ไปให้ชาว Darkshire ดู" },
        description = { "94:439265109:991497240 N 269:1132412307:2099423843", "ข้าต้องรู้ว่าร่างในเงาที่เห็นคืนครอบครัวถูกฆ่าคือใคร!\n\nได้โปรด {name} เจ้าพิสูจน์ความสามารถแล้ว หาคนนั้น ข้าต้องรู้ความลับที่เขาถือ!\n\nไม่มีเบาะแสเกินที่เจ้ารู้ แต่นี่ หนังสือจากไร่ บางทีชาวเมืองเชื่อมกับเจ้าของได้" },
        progress = { "143:1427408046:1362821527", "หากมีของของบุคคลในเงาที่ตามหา ให้ดู ข้าอาจทำนายบางอย่างเกี่ยวกับเจ้าของได้" },
        completion = { "257:112626170:454464310", "อืม... มีคนจับหนังสือไม่นาน ผู้ถูกความแค้นผลักดัน แต่ร่องรอยที่เหลือ อย่างน้อยของเจ้าของเดิม จางมาก\n\nแต่บอกได้ว่าเจ้าของเดิมไม่ใช่คนพื้นเมือง Darkshire" },
        required = { [2161] = { "21:1191186410:338138041", "หนังสือจากฟาร์มของ Sven" } },
        steps = { { "21:1191186410:338138041", "หนังสือจากฟาร์มของ Sven" } },
    },
    [265] = { -- The Shadowy Search Continues
        title = { "28:79963280:493657020", "ค้นหาเงามืดต่อไป" },
        objective = { "59:1027472358:519972368", "ถามชาวเมืองอื่นว่ามีเบาะแสบุคคลในเงาหรือไม่" },
        description = { "24:269399291:292429713 N 235:1617249665:329615044", "คืนหนังสือ {name} ขอให้โชคดี ถามคนอื่นอาจมีเบาะแสเพิ่ม\n\nอีกอย่าง แม้ผู้เขียนเป็นคนนอก Darkshire แต่ซื้อหนังสือนี้ที่นี่" },
        progress = { "173:250339323:849683720", "บางครั้งข้าขายสมุดเปล่าให้นักวิชาการ จอมเวท หรือผู้ต้องการเขียนบันทึก\n\nจำทุกคนที่ซื้อในไม่กี่เดือนที่ผ่านมาได้ดี..." },
        completion = { "179:78290474:610521725", "อา ใช่ ขายให้คนมีลับลมเดือนก่อน ไม่บอกชื่อ แต่กระวนกระวาย ตัวสั่น คอยมองข้ามบ่าตลอด\n\nหวังว่าช่วยเจ้า..." },
        required = { [2161] = { "21:1191186410:338138041", "หนังสือจากฟาร์มของ Sven" } },
        objectiveLabels = {
            item = { ["Book from Sven's Farm"] = "หนังสือจากฟาร์มของ Sven" },
        },
    },
    [266] = { -- Inquire at the Inn
        title = { "18:470930391:382576643", "สอบถามที่โรงเตี๊ยม" },
        objective = { "50:142576589:1455125040", "หาเบาะแสบุคคลในเงาที่โรงเตี๊ยม" },
        description = { "190:923544361:290997381", "นี่หนังสือ โชคดีกับการสอบถาม\n\nอาจขยายไปโรงเตี๊ยม หากคนที่ตามหาเคยอยู่เมือง คงมีใครเห็นที่นั่น" },
        progress = { "177:1918491653:1455285775", "Scarlet Raven ค้าขายไม่ดีเท่าเก่า แต่ยังมีคนผ่าน\n\nหากบรรยายคนที่หา ข้าอาจจำได้" },
        completion = { "317:348312960:2105104672", "อ้อ จำหนังสือได้ เจ้าของเช่าห้องไม่กี่วัน ใช้กลางคืนเขียนที่บาร์\n\nออกเมืองรีบ ๆ พึมพำว่าถูก... บางสิ่ง... ล่า ล่าสุดมุ่งตะวันตกหาที่ซ่อนใหม่\n\nที่แรกทางตะวันตกที่พบคือ Raven Hill..." },
        required = { [2161] = { "21:1191186410:338138041", "หนังสือจากฟาร์มของ Sven" } },
        steps = { { "21:1191186410:338138041", "หนังสือจากฟาร์มของ Sven" } },
    },
    [268] = { -- Return to Sven
        title = { "14:1760539629:553568987", "กลับไปหา Sven" },
        objective = { "47:540582531:1724896025", "กลับไปหา Sven พร้อม Jitters' Completed Journal" },
        description = { "342:1205623509:1848488429", "หนังสือที่พบเขียนเพียงครึ่ง ต้องทิ้ง Sven's Farm ตอนหนี...\n\nนี่ นำบันทึกฉบับสมบูรณ์ให้ Sven อธิบายเรื่องที่ไร่ครบกว่า\n\nแม้บันทึกเป็นเพื่อนเดียวหลายสัปดาห์ หากสละแล้วไม่ต้องเผชิญ Sven กับโทสะ ข้าก็ยินดี!" },
        progress = { "40:743579138:1199466481", "พบหรือยังว่าบุคคลในเงาคือใคร?" },
        completion = { "195:2019024577:1820402701", "บันทึกอธิบายมาก พาข้าสู่เส้นทางต้าน Dark Riders! ข้าเคยเห็นพวกมันใน Duskwood และเห็นคุยจอมเวท Morbent Fel ที่ Forlorn Rowe" },
        required = { [2560] = { "26:2106658281:128932695", "บันทึกฉบับสมบูรณ์ของ Jitters" } },
        objectiveLabels = {
            item = { ["Jitters' Completed Journal"] = "บันทึกฉบับสมบูรณ์ของ Jitters" },
        },
    },
    [269] = { -- Seeking Wisdom
        title = { "14:1352566284:572909518", "แสวงหาปัญญา" },
        objective = { "64:1068977524:633984563", "มอบ Jitters' Completed Journal ให้ Bishop Farthing ที่ Stormwind" },
        description = { "316:209850520:1996047507 N 67:1089920027:678310052", "ไป Stormwind คุย Bishop Farthing ที่ Cathedral of Light ให้บันทึก Jitters แล้วบอกว่าจะเผชิญ Morbent Fel\n\nแม้ Stormwind ทอดทิ้ง Darkshire แต่ Farthing ใจดีและฉลาด อาจช่วยภารกิจกู้เรา\n\nงานอันตราย แต่รีบ {name} ทุกชั่วโมงเงา Duskwood ยิ่งมืด" },
        progress = { { "131:1970609360:189699427", "130:290871593:410259125" }, "พักเถิด สหายร่วมศรัทธา ข้ารู้ว่าเดินทางไกล แบกภาระหนัก บอกได้ไหมว่าอะไรทอดเงามืดคลุมเจ้า?" },
        completion = { "476:408418260:754802079", "<หลังอ่านบันทึกและฟังเจตนา...>\n\nมลทินชั่วตั้งหลักใน Duskwood ที่เดือดร้อนอยู่แล้ว ขอบคุณแสงสว่างที่มีวีรชนเช่นเจ้ารับมือ\n\nแต่ต้องเตรียมก่อนบททดสอบ... จอมเวทปลุกศพ Morbent Fel ทรงพลังมาก ลงมนตร์รอบตนกันการโจมตีทางกาย หากจะปราบ ต้องใช้อาวุธต้านการป้องกันนี้" },
        required = { [2560] = { "26:2106658281:128932695", "บันทึกฉบับสมบูรณ์ของ Jitters" } },
        steps = { { "26:2106658281:128932695", "บันทึกฉบับสมบูรณ์ของ Jitters" } },
    },
    [270] = { -- The Doomed Fleet
        title = { "16:215338907:1854106914", "กองเรือพบหายนะ" },
        objective = { "71:1925199749:2092688630", "ไป Menethil Harbor ที่ Wetlands แล้วคุยกับ Glorin Steelbrow" },
        description = { "469:858364824:1237299248", "หลายปีก่อน กองเรือที่สาม Kul'Tiras จมริม Wetlands แดนบึงเหนืออาณาจักรคนแคระ Ironforge เรือลำหนึ่งบรรทุก Lightforge Iron\n\nโลหะล้ำค่าแก่เรา ของสร้างจากมันโจมตีด้วยสัจจะศักดิ์สิทธิ์ หากเผชิญ Morbent Fel เจ้าต้องมีอาวุธเช่นนั้น\n\nไป Menethil Harbor คุย Glorin Steelbrow เพื่อนร่วมงานคนแคระ หากหาโลหะหายได้ เขาจะรู้ที่หา" },
        completion = { { "279:1237604139:329615851", "278:884303188:342080142" }, "Lightforge Iron ล้ำค่า แต่ภารกิจเจ้าฟังคับขัน เดินทางไกลนะ สหายร่วมศรัทธา หากมีโชคอาจพบที่หา!\n\nหากได้เหล็ก ข้ารู้ว่าใครทำเป็นอาวุธสู้จอมเวทปลุกศพใน Duskwood ที่เจ้าพูดถึงได้" },
    },
    [321] = { -- Lightforge Iron
        title = { "15:1777215443:1549363416", "เหล็ก Lightforge" },
        objective = { "57:940102940:104206033", "ค้นซาก The Flying Osprey ที่ Wetlands" },
        description = { "489:404764038:418057579", "ซากนอกฝั่งคือกองเรือที่สาม Kul'Tiras ถูกมังกรแดงเผาจมในมหาสงครามครั้งก่อน\n\nกองเรือมาจาก Lordaeron แต่มีเรือพิฆาตเอลฟ์ Flying Osprey ร่วมด้วย บรรทุก Lightforge Iron จึงเข้ากองเรือเพื่อคุ้มครอง น่าขันที่จมเพราะมังกรเดียวกัน...\n\nพอเรื่องประวัติ Flying Osprey จมทางใต้ของ Menethil Harbor หากพบเหล็ก นำให้ข้า" },
        completion = { "332:593646342:1312327146", "หีบชุ่มน้ำ ผนังแตก รอยเล็บมากทั้งในนอก... เหมือนเมอร์ล็อกค้นแล้วขโมยสมบัติ\n\nแต่ลึกในหีบมี Lightforge Ingot หนึ่งแท่ง น่าเสียดายยังต้องมากกว่านี้จึงมีโลหะพอทำอาวุธ" },
    },
    [322] = { -- Blessed Arm
        title = { "11:1421360222:1250085735", "อาวุธอวยพร" },
        objective = { "67:1441382192:1940722406", "นำ Crate of Lightforge Ingots ไปให้ Grimand Elmore ที่ Stormwind" },
        description = { "345:1418548844:371154120", "ช่างอาวุธคนแคระใน Dwarven District ของ Stormwind ใช้ Lightforge Iron ได้ ชื่อ Grimand Elmore\n\nข้าบรรจุเหล็กที่พบใส่ลังแล้ว นำไปเล่าเรื่อง ข้ามั่นใจว่าเขายินดีช่วยภารกิจเช่นเจ้า สร้างอาวุธที่แม้ Morbent Fel ยังหวั่น!" },
        progress = { "34:2037846979:637118688 C 1:63:63", "ให้ข้าใช้ฝีมือช่วยอะไร {class}?" },
        completion = { "302:411616437:1200532802", "เรื่องราวน่าทึ่ง และ Lightforge Iron! หลายปีไม่ได้ทำโลหะเช่นนี้ เป็นเกียรติที่ทำอีก ต้องกลับมาเล่าเรื่องสู้จอมเวทปลุกศพให้ฟังทีหลัง\n\nแต่เราคิดไกลไป ก่อนอื่นอาวุธสู้ Morbent Fel..." },
        required = { [2712] = { "26:1794373562:958826451", "ลังแท่งโลหะ Lightforge" } },
        steps = { { "26:1794373562:958826451", "ลังแท่งโลหะ Lightforge" } },
    },
    [323] = { -- Proving Your Worth
        title = { "18:635072648:375197433", "พิสูจน์คุณค่าของเจ้า" },
        objective = { "93:574712604:267307330", "สังหาร Skeletal Raider 15 ตัว, Skeletal Healer 3 ตัว และ Skeletal Warder 3 ตัว แล้วกลับไปหา Sven" },
        description = { "343:2119928879:1405074145", "Morbent Fel เป็นจอมเวทปลุกศพ พันธมิตร Dark Riders ข้าอยากส่งเจ้าเผชิญพลัง แต่ไม่ส่งสู้ปีศาจชั่วโดยไม่รู้ความแข็งแกร่งก่อน\n\nเจ้าพิสูจน์ความกล้าแล้ว แต่หากอยากเผชิญจริง ตอนนี้ต้องพิสูจน์ฝีมือกับสมุนเขา" },
        progress = { "13:193127963:556220112 N 60:458624313:1865433290", "สู้ให้เต็มที่ {name} อย่าสิ้นหวัง เพราะสิ้นหวังคืออาวุธยิ่งใหญ่สุดของความชั่ว" },
        completion = { "22:1055896235:1988236663 N 84:1825540578:2098932024", "ฝีมือสู้เจ้าไม่ต้องสงสัย {name} ความมุ่งมั่นอาจพาเราเห็นจุดจบ Morbent Fel!" },
        objectiveLabels = {
            monster = { ["Skeletal Raider slain"] = "ปราบ ผู้จู่โจมโครงกระดูก", ["Skeletal Healer slain"] = "ปราบ ผู้เยียวยาโครงกระดูก", ["Skeletal Warder slain"] = "ปราบ ผู้พิทักษ์โครงกระดูก" },
        },
    },
