        progress = { "42:209445907:1065277827", "พบ Lightforge Iron ที่ต้องการไหม?" },
        completion = { "90:238781:1080820413", "อา พบแล้ว! ทีนี้ตีให้มีประโยชน์กันเถอะ?" },
