    [337] = { -- An Old History Book
        title = { "19:170630285:1729031158", "หนังสือประวัติศาสตร์เก่า" },
        objective = { "68:1550666189:1824000433", "คืนหนังสือ The History of Stormwind ให้ Stormwind Library" },
        description = { "318:1120950824:1054055272", "แม้ปกมีรอยขีดและโคลนพอก ยังอ่าน “The History of Stormwind” ที่สันได้ เปิดแล้วเห็นตรา Stormwind Library ชัดบนหน้าแรก\n\nดูเหมือนมีคนยืมแล้วไม่คืน..." },
        progress = { "56:1271852346:1648280588", "โอ้! หนังสือเก่าอะไรนั่น? ขอข้าดูได้ไหม??" },
        completion = { { "297:308883798:1405179064", "299:75464580:1710601113" }, "โอ้! เล่มนี้ไม่อยู่บนชั้นตั้งแต่ก่อนสร้าง Stormwind ใหม่หลายปีก่อน แน่นอนต้องซ่อม สภาพแย่ แต่จะเป็นเกียรติอย่างยิ่งที่ได้เก็บในหมวดหายาก\n\nขอบใจท่าน โปรดรับนี่ตอบแทนการคืนหนังสือ!" },
        required = { [2794] = { "19:170630285:1729031158", "หนังสือประวัติศาสตร์เก่า" } },
        steps = { { "19:170630285:1729031158", "หนังสือประวัติศาสตร์เก่า" } },
    },
    [401] = { -- Wait for Sirra to Finish
        title = { "24:185634435:747573914", "รอ Sirra แปลเสร็จ" },
        objective = { "52:1266601719:1396702534", "รอสักครู่ แล้วคุยกับ Sirra Von'Indi อีกครั้ง" },
        description = { "94:2049930400:1590180390", "เกือบแปลจดหมายเสร็จแล้ว กลับมาอีกครู่คงจบ" },
        completion = { "110:889472454:1563834580", "เรียบร้อย แปลแล้ว...\n\n<อากาศหนักอึ้งราวม่านดำหนาถูกชักคลุมแผ่นดิน...>" },
    },
    [453] = { -- Finding the Shadowy Figure
        title = { "26:1165261540:657727683", "ตามหาบุคคลในเงา" },
        objective = { "135:1394898324:1864970082", "หาบุคคลในเงา เบาะแสคือ:\n\nไม่ใช่คนพื้นเมือง Darkshire\n\nเป็นคนกระวนกระวาย ตัวสั่น\n\nออก Darkshire มุ่งตะวันตก" },
        description = { "11:799504212:1731205453 N 145:1074404869:850827670", "โชคดี {name} หวังว่าพบเขา และพบขณะยังอยู่\n\nหากออกที่ปลอดภัย Darkshire อาจเป็นเหยื่อสัตว์ป่า" },
        progress = { "26:1708577532:1876989138", "เจ้าเป็นใคร?? ปล่อยข้าไว้!" },
        completion = { "145:330321740:1986499988", "<Jitters ถอนใจ...>\n\nใช่ ข้าคนเขียน ในที่สุดก็พบสินะ?\n\nแต่หากอ่านบันทึก... เจ้ารู้เพียงครึ่งเรื่อง!" },
        required = { [2161] = { "21:1191186410:338138041", "หนังสือจากฟาร์มของ Sven" } },
        steps = { { "21:1191186410:338138041", "หนังสือจากฟาร์มของ Sven" } },
    },
    [526] = { -- Lightforge Ingots
        title = { "17:1440936491:1582303016", "แท่งเหล็ก Lightforge" },
