    },
    [1372] = { -- Nothing But The Truth
        title = { "21:212526010:1087086778", "ไม่มีสิ่งใดนอกจากความจริง" },
        objective = { "48:1689217319:839232212", "คุยกับ Apothecary Faustin ที่ Beggar's Haunt" },
        description = { "484:1549106420:1682670857", "หน่วยสำรวจเราถูกส่งตามคำสั่ง Varimathras มาดู Azeroth ตอนล่าง\n\nตอนสอดแนม ข้าเห็นมนุษย์แทรกซึมเฝ้า Beggar's Haunt ก่อนจับได้ พี่น้อง... ออร์ค... บางคนจับไป Stonard ที่มั่นใน Swamp of Sorrows\n\nข้าอยาก... ช่วย... พันธมิตรออร์ค แม้พวกเขาไม่เห็นค่ายเรา แต่ยังอยากยื่นมือ\n\nทำงานกับ Faustin ที่นี่เพื่อพัฒนา... ยาพูดความจริง ให้เพื่อนใน Stonard" },
        completion = { "385:203131033:282010705 N 87:486674568:1935448765", "Zraedus เพิ่งเล่าเรื่องคนแทรกซึมสอดรู้ก่อนเจ้ามา\n\nเป็นปัญหาจริง เราไม่ต้องการคนจุ้นมาดมแถว Beggar's Haunt\n\nออร์ค Stonard คงร้อนใจฟังเพื่อนเราพูด เมื่อเป็นพันธมิตร อะแฮ่ม ต้องช่วยรีดข้อมูลมนุษย์ให้ได้\n\nทำกับข้า {name} เราจะส่งยาพูดความจริงไป Stonard\n\nเพื่อ Horde!\n\n...ข้าพูดถูกไหม?" },
    },
    [1383] = { -- Nothing But The Truth
        title = { "21:212526010:1087086778", "ไม่มีสิ่งใดนอกจากความจริง" },
        objective = { "110:1883139428:2086954110", "Apothecary Faustin ที่ Beggar's Haunt ต้องการ Shadow Panther Heart 5 ชิ้น, Mire Lord Fungus และ Deep Strider Tumor" },
        description = { "302:627313472:383254368 N 191:744476815:1906203497", "ข้านึกถึงยาที่เหมาะพอดี มันจะจัดการความจริงอย่างที่ความจริงควรถูกจัดการ\n\nต้องใช้หัวใจ Shadow Panther หลายชิ้นจากบึง และเห็ดลงมนตร์จาก Mire Lord ที่นั่น มั่นใจว่าผู้เก่งเช่นเจ้า {name} โน้มน้าวให้แบ่งได้\n\nส่วนยากคือ Deepstrider Tumor จาก Desolace ไกล ยักษ์ที่นั่นป่วยเกิดเนื้องอกน้อยมาก\n\nไปได้แล้ว!" },
        progress = { "430:988112965:948177976", "คนแทรกซึม Stonard คง... เปิดใจ... หลังดื่มยาพิเศษ ฮ่าฮ่า!\n\nวัตถุดิบไม่ง่าย Shadow Panther พบทั่วไปในบึง แต่เก็บหัวใจพอใช้ก็หนัก Mire Lord ก็เรื่องมาก\n\nDeepstrider Tumor หายากเหลือเกิน แต่ปฏิกิริยาเคมีที่ข้าใช้จากมันไม่มีใครเทียบ" },
        completion = { "10:1582154033:241472075 N 215:303798516:74479956", "ยอดเยี่ยม {name}! ทันเวลาพอดี Zraedus บอกว่าคนแทรกซึมหายจากแผล พร้อมให้ออร์คสอบแล้ว\n\nขอครู่เตรียมยาพิ-... หมายถึงยาพูดความจริง" },
        required = { [6080] = { "20:1199826810:142331923", "หัวใจเสือดำเงา" }, [6081] = { "16:2064898444:1607009451", "เห็ดของ Mire Lord" }, [6082] = { "17:1262996773:1523635124", "เนื้องอกของ Deepstrider" } },
        objectiveLabels = {
            item = { ["Shadow Panther Heart"] = "หัวใจเสือดำเงา", ["Mire Lord Fungus"] = "เห็ดของ Mire Lord", ["Deepstrider Tumor"] = "เนื้องอกของ Deepstrider" },
        },
    },
    [1388] = { -- Nothing But The Truth
        title = { "21:212526010:1087086778", "ไม่มีสิ่งใดนอกจากความจริง" },
        objective = { "69:424844832:1589230587", "มอบ Faustin's Truth Serum ให้ Deathstalker Zraedus ที่ Beggar's Haunt" },
        description = { "44:1450194927:393771884 N 121:1115183543:1697664624", "ทุกอย่างตามแผน {name} มอบยาพูดความจริงให้ Deathstalker Zraedus เขาจะสอนวิธีใช้... อย่างถูกต้อง\n\nฮ่าฮ่า!" },
        progress = { "78:1430942508:1382558154", "หวังว่าเจ้าพิสูจน์ว่ามีประโยชน์ต่อ Apothecary Faustin เพื่อนรักเราแล้ว" },
        completion = { "133:1445510090:432434802", "รู้อยู่แล้ว Faustin เฒ่าจะคิดของดีได้! เจ้ามีส่วนช่วยมากแน่\n\nทีนี้เริ่มธุระกันเถอะ?" },
    },
    [1391] = { -- Nothing But The Truth
        title = { "21:212526010:1087086778", "ไม่มีสิ่งใดนอกจากความจริง" },
        objective = { "54:1588609020:1824982723", "นำ Zraedus's Brew ไปให้ Infiltrator Marksen ที่ Stonard" },
        description = { "431:1342800390:375655583 N 47:970312599:83937259", "เราต้องทำอย่างรอบคอบ คงไม่เดินเข้าไปโน้มน้าวให้เจ้าโง่ดื่มยาของ Faustin ตรง ๆ หรอกใช่ไหม?\n\nแต่มีสิ่งหนึ่งมนุษย์ปฏิเสธไม่ได้ เหล้า ข้าจะผสมยาลงเอล รับรองคนน่าสงสารไม่ลังเลกระดก\n\nรีบไป Stonard ใน Swamp of Sorrows {name} และเก็บภารกิจเล็กเราให้เงียบ..." },
        progress = { "182:1348254169:995175380", "โปรดเมตตา! ข้ามีข้อมูลที่ข้ามเส้นแบ่งฝ่าย แม้ไม่เห็นใจ Horde แต่มีการทรยศทางการเมืองที่ต้องเปิดโปง!" },
        completion = { "143:1633334200:1742343755", "เครื่องดื่มให้ข้าหรือ? ใจดีจริง หลายวันแล้วที่ไม่ได้รับอนุญาตให้ดื่ม ขอหมดนี่แล้วจะเล่าสิ่งที่รู้..." },
    },
    [1395] = { -- Supplies for Nethergarde
        title = { "24:739667439:781878902", "เสบียงสำหรับ Nethergarde" },
        objective = { "88:1884592817:1462843550", "นำ Crate of Powerstones ไปให้ Quartermaster Lungertz ก่อนศิลาพลังงานหมดอายุ" },
        description = { "428:903629974:34356710 N 65:1989243869:1376841768", "ลังศิลาพลังงานต้องไป Nethergarde Keep ที่ Blasted Lands เก็บพลังไม่นาน จึงส่งคาราวานรอบหน้าไม่ได้\n\nเจ้าต้องเอาไป และไปเร็ว\n\nส่ง Quartermaster Lungertz ที่ Nethergarde Keep เดินตะวันออกผ่าน Deadwind Pass ต่อไปตะวันออกผ่าน Swamp of Sorrows แล้วลงใต้เข้า Blasted Lands\n\nระวัง {name} ต้องผ่านแดนอันตราย แต่ล้มเหลวไม่ได้" },
        progress = { "112:1238818314:482737169", "สวัสดี! อย่าสนเสียงวุ่น นี่กิจวัตร Nethergarde Keep\n\nมีอะไรให้ข้าหรือ?" },
        completion = { "72:420353946:458782266 N 54:1675380676:1769295597", "อา ศิลาพลังงาน! จอมเวทคงดีใจ!\n\nขอบใจมาก {name} รู้ว่าเดินทางจาก Darkshire ไม่ง่าย" },
        required = { [6091] = { "21:2081092381:120975071", "ลังบรรจุศิลาพลัง" } },
        steps = { { "21:2081092381:120975071", "ลังบรรจุศิลาพลัง" } },
    },
    [79362] = { -- Grant's Shield
        title = { "14:1992449746:1294216098", "โล่ของ Grant" },
        objective = { "130:824351796:1023707746", "หา Grant's Mace จากโครงกระดูกใน Raven Hill Cemetery แล้วกลับไปหา Sirra Von'Indie ที่ Darkshire เพื่อรู้ข้อมูลเพิ่ม" },
        description = { "302:458049928:334100051", "โล่ที่วิญญาณ Grant Valor บิดาตระกูล Valor และวีรชน Raven Hill ทิ้งไว้\n\nเมื่อวิญญาณยังสู้กับอันเดด งานค้างอาจเป็นการฆ่าตัวร้ายที่ทำร้ายเขาใน Raven Hill Cemetery คงเป็นตัวที่กระบองยังฝังอยู่" },
        completion = { "271:1153898090:1556432870", "คนทะนงตนอย่าง Grant Valor กลับต้องมาล้มเพราะสัตว์ธรรมดา ๆ เรื่องนี้บอกถึงความโหดร้ายของการสู้รบยิ่งกว่าจะบอกอะไรเกี่ยวกับตัวเขา พลาดเพียงครั้งเดียวก็พิการไปตลอดชีวิตได้\n\nอาวุธพวกนี้บอกอะไรเกี่ยวกับเจ้าของได้มาก ข้าขอเวลาศึกษามันสักหน่อย" },
        progress = { "21:629203736:1056329111", "เจ้าอยากพบข้าหรือ?" },
        required = { [281146] = { "12:1541470835:573735968", "กระบองของ Grant" }, [281147] = { "14:1992449746:1294216098", "โล่ของ Grant" } },
        steps = { { "12:1541470835:573735968", "กระบองของ Grant" }, { "14:1992449746:1294216098", "โล่ของ Grant" } },
    },
    [79363] = { -- Silvia's Sword
        title = { "14:1174584921:81049918", "ดาบของ Silvia" },
        objective = { "134:1040460041:168056346", "ปราบ Defias Night Blade 7 คนและ Defias Enchanter 7 คนใน Addle's Stead แล้วกลับไปหา Sirra Von'Indi ที่ Darkshire เพื่อรู้ข้อมูลเพิ่ม", amount = { "7:1265997621:1189804897 W1 25:1014313426:1519655190 W1 100:776627233:1217846639", "ปราบ Defias Night Blade {world1} คน และ Defias Enchanter {world1} คนที่ Addle's Stead แล้วกลับไปหา Sirra Von'Indi ที่ Darkshire เพื่อขอข้อมูลเพิ่มเติม" } },
        description = { "290:1004269381:1249456226", "ดาบที่วิญญาณ Silvia Valor ยาม Raven Hill ทิ้งไว้ นางใช้ชีวิตปกป้องประชาชนกับบ้านเรือน\n\nเมื่อวิญญาณยังเยือนไร่ งานค้างอาจเป็นการขับไล่ Defias ที่ยึด Addle's Stead ทางใต้ Raven Hill" },
        progress = { "25:926587898:1375257950", "ลุยไปเจออันตรายอะไรมาบ้างหรือยัง?", variants = { { "34:787073197:655337148", "เจ้าทำหน้าเหมือนเพิ่งเห็นผีมา!" } } },
        completion = { "37:1847253059:209826998", "สะบัดโคลนออกซะ เราใกล้เสร็จแล้ว", variants = { { "240:2045208235:1526021767", "Silvia Valor หรือ อา ใช่แล้ว นางเป็นนักรบฝีมือดีและคอยปกป้องวิถีชีวิตของพวกเรา แม้นางจะมองเรื่องนี้ค่อนข้างแคบไปหน่อย\n\nเจ้าคงเดาได้พอ ๆ กับข้าว่านางต้องการอะไร แต่จัดการพวก Defias ก็เป็นจุดเริ่มที่ดี ให้ข้าตรวจดูดาบเล่มนี้ให้ละเอียดกว่านี้ก่อน" } } },
        required = { [281145] = { "14:1174584921:81049918", "ดาบของ Silvia" } },
        objectiveLabels = {
            item = { ["Silvia's Sword"] = "ดาบของ Silvia" },
            monster = { ["Defias Night Blade slain"] = "ปราบ นักดาบราตรี Defias", ["Defias Enchanter slain"] = "ปราบ นักลงอาคม Defias" },
        },
    },
    [96137] = { -- Ira's Dagger
        title = { "12:1692663869:1225838660", "มีดของ Ira" },
        objective = { "116:1696834448:170765322", "ปราบ Young Black Ravager 10 ตัวและ Black Ravager 7 ตัว แล้วกลับไปหา Sirra Von'Indi ที่ Darkshire เพื่อรู้ข้อมูลเพิ่ม", amount = { "7:1265997621:1189804897 W1 26:2021028167:111627115 W2 80:2058960914:188232219", "ปราบ Young Black Ravager {world1} ตัวและ Black Ravager {world2} ตัว แล้วกลับไปหา Sirra Von'Indi ที่ Darkshire เพื่อรู้ข้อมูลเพิ่ม" } },
        description = { "300:1704904090:39247729", "มีดเล็กของ Ira เรนเจอร์ตั้งตน ผู้ดูแลป่าให้ปลอดภัยโดยกันสัตว์ไม่ให้โจมตีนักเดินทาง\n\nเมื่อวิญญาณ Ira ยังเดินป่า งานค้างอาจเป็นการกำจัดวอร์กที่ยังคร่าชีวิตทั่วป่า" },
        progress = { "24:726078769:9476074", "เจ้าถืออะไรมา?" },
        completion = { "160:1895055669:512323770", "Ira หรือ? เจ้าแน่ใจนะ? ฟังดูแล้วนางแทบจะเป็นผีตั้งแต่ก่อนตายเสียอีก ข้าแปลกใจที่เจ้าหานางเจอ\n\nวางใจเถิด ข้าจะดูแลกริชเล่มนี้เป็นอย่างดี" },
        required = { [281143] = { "12:1692663869:1225838660", "มีดสั้นของ Ira" } },
        steps = { { "12:1692663869:1225838660", "มีดสั้นของ Ira" } },
        objectiveLabels = {
            monster = { ["Young Black Ravager slain"] = "ปราบ หมาป่าดำจอมฉีกกระชากวัยเยาว์", ["Black Ravager slain"] = "ปราบ หมาป่าดำจอมฉีกกระชาก" },
        },
    },
    [96138] = { -- Merrick's Bow
        title = { "13:449677543:675999414", "ธนูของ Merrick" },
        objective = { "124:706491236:88824722", "ปราบ Splint Fist Warrior 8 ตนและ Splint Fist Taskmaster 4 ตน แล้วกลับไปหา Sirra Von'Indi ที่ Darkshire เพื่อรู้ข้อมูลเพิ่ม", amount = { "7:1265997621:1189804897 W1 26:1475142117:1739403327 W2 89:804043571:325236622", "ปราบ Splint Fist Warrior {world1} ตนและ Splint Fist Taskmaster {world2} ตน แล้วกลับไปหา Sirra Von'Indi ที่ Darkshire เพื่อรู้ข้อมูลเพิ่ม", variants = { { "7:1265997621:1189804897 W1 28:758346139:1498047019 W2 91:591511141:796769003", "ปราบ Splinter Fist Warrior {world1} ตน และ Splinter Fist Taskmaster {world2} ตน แล้วกลับไปหา Sirra Von'Indi ที่ Darkshire เพื่อขอข้อมูลเพิ่มเติม" } } } },
        description = { "323:2097708357:1710229260", "ธนูที่วิญญาณ Merrick Valor ทิ้งไว้ Watcher ชื่อดังผู้ภูมิใจรักษาถนนจากศัตรูรุกล้ำ\n\nเมื่อวิญญาณยังเดินถนน งานค้างอาจเป็นการไล่ผู้รุกรานใกล้บ้าน Raven Hill โอเกอร์ทางใต้เมืองอาจเป็นสิ่งกวนวิญญาณ" },
        progress = { "16:1205405492:147321852", "ว่าอย่างไร มีอะไรหรือ?" },
        completion = { "146:1223417724:1091259110 N 68:1754465514:469776090", "Merrick Valor หรือ? เด็กหนุ่มผู้น่าสงสาร เขาอยากพิสูจน์ตัวเองมาตลอด เรื่องที่เกิดกับเขาและครอบครัวช่างน่าเศร้า\n\nขอบใจที่นำสิ่งนี้มาให้ {name} บางทีมันอาจช่วยให้เราเข้าใจอดีตของ Raven Hill มากขึ้น" },
        required = { [281142] = { "13:449677543:675999414", "ธนูของ Merrick" } },
        steps = { { "13:449677543:675999414", "ธนูของ Merrick" } },
        objectiveLabels = {
            monster = { ["Splinter Fist Warrior slain"] = "ปราบ นักรบ Splinter Fist", ["Splinter Fist Taskmaster slain"] = "ปราบ ผู้คุมแรงงาน Splinter Fist" },
        },
    },
    [96139] = { -- The Valor Family
        title = { "16:150602505:467615853", "ตระกูล Valor" },
        objective = { "85:2024700588:1578780284", "ค้น Raven Hill หาสิ่งน่าสนใจแล้วกลับไปหา Sirra Von'Indi ที่ Darkshire" },
        description = { "504:1611703240:264283854", "ยามมืดเช่นนี้ เราควรจำวีรชนไม่แพ้ศัตรู Darkshire คงไม่อยู่หากไร้ความกล้าของ Lady Althea หรือผู้เสียชีวิตที่ Raven Hill\n\nอ่านเรื่อง Raven Hill มากไหม? ไม่สิ ประวัติถูกลบพร้อมผู้คน แม้ห้องสมุดข้าน่าประทับใจ ก็มีเรื่องนี้น้อย\n\nหากพบอะไร โปรดนำมา คนเหล่านั้นควรถูกจดจำ", variants = { { "499:1006295711:1357468691", "ยามมืดเช่นนี้ เราควรจำวีรชนไม่แพ้ศัตรู Darkshire คงไม่อยู่หากไร้ความกล้าของ Lady Althea หรือผู้เสียชีวิตที่ Raven Hill\n\nอ่านเรื่อง Raven Hill มากไหม? ไม่สิ ประวัติถูกลบพร้อมผู้คน แม้ห้องสมุดข้าน่าประทับใจ ก็มีเรื่องนี้น้อย\n\nหากพบอะไร โปรดนำมา คนเหล่านั้นควรถูกจดจำ" } } },
        progress = { "55:1988584174:1612293055", "พบอะไรไหม? ข้าไม่ได้หวังมากนัก" },
        completion = { "277:1584007138:2109790158", "ตำราดูเป็นเรื่องตระกูล Valor ข้าเหมือนเคยได้ยินบางคน คนดี แต่ไม่แน่ใจว่าคู่ควรหนังสือทั้งเล่ม\n\nจะทำสำเนาให้ หากพบของเกี่ยวกับพวกเขาระหว่างทาง ข้ายินดีรับไว้" },
        required = { [281046] = { "15:646355887:1080149475", "คัมภีร์ Raven Hill" } },
        steps = { { "15:646355887:1080149475", "คัมภีร์ Raven Hill" } },
    },
    [185] = { -- Tiger Mastery
