    [187] = { -- Tiger Mastery
        title = { "13:271407519:1236481597", "เชี่ยวชาญการล่าเสือ" },
        objective = { "88:130580336:1325774264", "Ajeck Rouack แห่ง Nesingwary's Expedition ต้องการให้สังหาร Elder Stranglethorn Tiger 10 ตัว" },
        description = { "365:2017349315:1543730038", "ทีนี้เพิ่มเดิมพัน ทดสอบฝีมือจริง พิสูจน์ว่าฆ่า Elder Stranglethorn Tiger 10 ตัวได้ หากสำเร็จจะพร้อมบทสุดท้าย ก่อนข้าประกาศต่อ Master Nesingwary ว่าเจ้าเป็นจ้าวการล่าเสือ\n\nเสือแก่ไม่เพียงหายากที่สุด แต่ยังดุร้ายที่สุดให้ปราบ" },
        progress = { "141:429063874:305614060", "ต้องสังหาร Elder Stranglethorn Tiger 10 ตัว ก่อนข้าให้บทสุดท้ายตัดสินว่าเป็นจ้าวการล่าเสือจริงไหม" },
        completion = { "48:263828618:1630437498", "น่าประทับใจมาก เชื่อว่าเจ้าเกือบพร้อมแล้ว" },
        objectiveLabels = {
            monster = { ["Elder Stranglethorn Tiger slain"] = "ปราบ เสือ Stranglethorn วัยชรา" },
        },
    },
    [188] = { -- Tiger Mastery
        title = { "13:271407519:1236481597", "เชี่ยวชาญการล่าเสือ" },
        objective = { "91:570337148:1984626601", "Ajeck Rouack แห่ง Nesingwary's Expedition ต้องการให้สังหาร Sin'Dall แล้วนำอุ้งเท้ากลับมา" },
        description = { "153:1326423590:1707450380 R 136:1270447541:1892097174", "นี่บทสุดท้าย เราตามเสือจับตัวยากหลายสัปดาห์ เรียก Sin'Dall ดูว่าเจ้าทำสิ่งที่ยังไม่มี{race}ทำได้ไหม ตามล่าแล้วสังหาร นำอุ้งเท้าเป็นหลักฐาน\n\nตามหามันไม่ง่ายแน่" },
        progress = { "31:61945971:741556621", "ล่า Sin'Dall เป็นอย่างไร?" },
        completion = { "63:1828652324:1298876336 N 1:33:33", "น่าประทับใจจริง! เจ้าคือจ้าวการล่าเสือแท้ {name}!" },
        required = { [3879] = { "15:1832967274:291897761", "อุ้งเท้าของ Sin'Dall" } },
        steps = { { "15:1832967274:291897761", "อุ้งเท้าของ Sin'Dall" } },
    },
    [189] = { -- Bloodscalp Ears
        title = { "15:1304543814:872180502", "หู Bloodscalp" },
        objective = { "65:2046533111:976351741", "หา Bloodscalp Ear 15 ชิ้นไปให้ Kebok ที่ Booty Bay" },
        description = { "332:1493161280:1389254648 N 161:1064685764:1901683637", "โทรลล์บัดซบ! มันฆ่าคนของเราในป่า! ข้าเสียยามเก่งไปหลายคน ต้นทุนพอกพูน จะอธิบาย Baron Revilgaz อย่างไร?\n\nต้องเด็ดขาด... คิดสิ Kebok... เจ้าไม่ได้ตำแหน่งวันนี้จากการนั่งเฉย... คิดออกแล้ว! เจ้า... {name} ใช่ไหม? ช่วยข้าสิ มีเงินให้!\n\nข้อตกลงคือ นำหูโทรลล์ Bloodscalp สิบห้าชิ้น ข้าจะจ่ายงาม" },
        progress = { "165:1947906976:909832843", "หวังว่าสำเร็จ? โทรลล์เต็มไปหมด ปีศาจโสโครก\n\nอ้อ นึกได้! บอกเพื่อนด้วย เราต้องการคนช่วยมาก!" },
        completion = { "234:933218288:872329170", "โอ้ ดีมาก ดีมาก ช่วยได้บ้างในตอนนี้...\n\n<เขาเสียงค่อยลง บ่นเรื่องกำไรกับต้นทุน...>\n\nอะไร ยังอยู่หรือ? รางวัล? อ้อ แน่นอน นี่รับไป... คงเกินพอแล้ว" },
        required = { [1519] = { "14:96991688:547627024", "หูของเผ่า Bloodscalp" } },
        steps = { { "14:96991688:547627024", "หูของเผ่า Bloodscalp" } },
    },
