        description = { "245:1390687865:1904993703", "ทีนี้ส่วนยาก นักล่าเสือดำแท้แสดงฝีมือด้วยการปราบ Shadowmaw Panther ที่อันตรายที่สุดใน Stranglethorn พิสูจน์ว่าล่าได้ 10 ตัว\n\nถ้าคิดว่าตามยาก รอจนลองฆ่าสักตัว..." },
        progress = { "25:1027295006:651215111 N 131:1321562929:89780624", "ทำอะไรที่นี่ {name}! ควรคลานพุ่มไม้ล่า Shadowmaw Panther 10 ตัว นึกว่าเจ้าอยากเป็นนักล่าสัตว์ใหญ่?" },
        completion = { "18:366880880:1038443585 N 1:33:33", "ทำได้ดี {name}!" },
        objectiveLabels = {
            monster = { ["Shadowmaw Panther slain"] = "ปราบ เสือดำกรามเงา" },
        },
    },
    [193] = { -- Panther Mastery
