        objective = { "92:269576191:973472336", "Sir S. J. Erlgadin แห่ง Nesingwary's Expedition ต้องการ Fang of Bhag'thera" },
        description = { "288:1621403863:453240242", "เกือบพิสูจน์ว่าเป็นจ้าวการล่าเสือดำแล้ว Bhag'thera เดินป่าและหลบทีมเรามาตลอด ดูว่าฝีมือเจ้าฆ่าผู้ยิ่งใหญ่นี้ได้ไหม\n\nนำ Fang of Bhag'thera มา แล้วเจ้าจะได้ความเคารพข้า!" },
        progress = { "64:654297431:1931427882", "Bhag'thera หลบเก่ง ล่าเป็นอย่างไร?" },
        completion = { "48:786171659:1915329805 N 19:785438326:967021927 C 8:681938418:289749352", "Bhag'thera ผู้ยิ่งใหญ่ตายแล้ว! ขอฉลองให้เจ้า {name} เป็น{class}ทรงพลังจริง!" },
        required = { [3876] = { "18:1566923749:1847848409", "เขี้ยวของ Bhag'thera" } },
        steps = { { "18:1566923749:1847848409", "เขี้ยวของ Bhag'thera" } },
    },
    [194] = { -- Raptor Mastery
        title = { "14:132497847:1257329476", "เชี่ยวชาญการล่าแรปเตอร์" },
        objective = { "60:1330127601:1978550153", "Hemet Nesingwary ต้องการให้สังหาร Stranglethorn Raptor 10 ตัว" },
        description = { "301:757941716:1505331873", "คิดว่าฝีมือล่าสุดยอดหรือ? ข้าทดสอบได้ทันที เข้าป่าสังหาร Stranglethorn Raptor 10 ตัว มาดูว่าเป็นนักล่าสัตว์ใหญ่เพียงใด\n\nไม่ ข้าไม่บอกว่าหาที่ไหน! การหาตัวคือครึ่งบททดสอบ" },
        progress = { "174:1966487253:1758343750", "ไม่เคยพบนักล่าที่ฆ่าอะไรได้จากยืนรอบกองไฟ เจ้าจะฆ่า Stranglethorn Raptor หรือหวังให้แก่ตายเอง?" },
        completion = { { "23:1907741180:1081425588", "20:1061662310:686626160" }, "ทำได้ดีจริง!" },
        objectiveLabels = {
            monster = { ["Stranglethorn Raptor slain"] = "ปราบ แรปเตอร์ Stranglethorn" },
        },
    },
    [195] = { -- Raptor Mastery
        title = { "14:132497847:1257329476", "เชี่ยวชาญการล่าแรปเตอร์" },
        objective = { "55:1267536820:467784969", "Hemet Nesingwary ต้องการให้สังหาร Lashtail Raptor 10 ตัว" },
        description = { "164:935354451:379415308", "เพิ่มความท้าทาย ดูว่าไหวไหม เข้าป่าล่า Lashtail Raptor บัดซบ 10 ตัว ให้ดูฝีมือ!" },
        progress = { "223:359070017:1867670904", "นักล่าแท้สนใจเหยื่อ แต่สหายเจ้าดูสนคุยข้างกองไฟ ไปฆ่า Lashtail 10 ตัว ก่อนข้าจะกวาดทั้งป่าหมดในการล่าครั้งเดียว" },
        completion = { "74:1806498313:2128697043 N 1:33:33", "เช่นนี้แหละถึงได้ของอวดเหนือเตาผิง! ฆ่าได้ดี {name}!" },
        objectiveLabels = {
