    },
    [196] = { -- Raptor Mastery
        title = { "14:132497847:1257329476", "เชี่ยวชาญการล่าแรปเตอร์" },
        objective = { "54:1741755308:1882912047", "Hemet Nesingwary ต้องการให้สังหาร Jungle Stalker 10 ตัว" },
        description = { "295:1562266345:1155415665", "ดูว่าจะรับบทต่อไปอย่างไร มีแรปเตอร์ฉลาดแกมโกงชื่อ Jungle Stalker ตามรอยและฆ่ายากกว่าพันธุ์ก่อนมาก กำจัด 10 ตัว แล้วข้าจะบอกยอดงานล่าที่สุดให้" },
        progress = { { "41:908276126:1926021741 N 184:1776912764:114986462", "41:908276126:1926021741 N 182:1554298381:2010472211" }, "เฮอะ ยืนทำอะไร {name}! นักล่าสัตว์ใหญ่แท้ไม่ยอมแพ้เมื่อเล็งเหยื่อแล้ว Jungle Stalker ไม่วิ่งมากระโดดกองไฟเองหรอก เจ้าทึ่ม" },
        completion = { { "71:1967140926:1568220495", "71:1828578459:1712553289" }, "โฮโฮ!! เรามียอดนักฆ่าแรปเตอร์แล้ว ทำได้ดีจริง!", variants = { { "70:951878573:389010260", "โฮ่โฮ่! เราได้นักล่าแรปเตอร์ตัวจริงแล้ว! ทำได้ดีมาก สหาย!" } } },
        objectiveLabels = {
            monster = { ["Jungle Stalker slain"] = "ปราบ แรปเตอร์นักสะกดรอยในป่าดงดิบ" },
        },
    },
    [197] = { -- Raptor Mastery
        title = { "14:132497847:1257329476", "เชี่ยวชาญการล่าแรปเตอร์" },
        objective = { "89:1814875560:1781458254", "Hemet Nesingwary ต้องการให้สังหาร Tethis แรปเตอร์อันตรายที่ตามจับยากใน Stranglethorn" },
        description = { "329:1640934540:687921878", "เมื่อพิสูจน์ว่าลุยป่าเก่ง ข้าจะเล่าแรปเตอร์ดุที่แม้ข้าฆ่าไม่สำเร็จ Ajeck เรียกมัน Tethis\n\nหากอยากเป็นจ้าวแท้ ฆ่าแล้วนำกรงเล็บมา จะเป็นวีรกรรมที่ไม่มีนักล่าสัตว์ใหญ่ใดทำได้" },
        progress = { "76:1477471833:993105569", "ล่า Tethis เป็นอย่างไร? ตามมันกลับค่ายมาเลยหรือ?" },
        completion = { "7:459703642:425541723 N 47:1592349881:1320878167", "Master {name} ผู้สังหารแรปเตอร์!\n\nฟังดีใช่ไหม?" },
        required = { [3877] = { "15:267987795:1034293966", "กรงเล็บของ Tethis" } },
        steps = { { "15:267987795:1034293966", "กรงเล็บของ Tethis" } },
    },
    [198] = { -- Supplies to Private Thorsen
        title = { "27:65764560:1988236658", "เสบียงสำหรับ Private Thorsen" },
        objective = { "61:192295734:1829262358", "ส่ง Miscellaneous Goblin Supplies ให้ Private Thorsen" },
        description = { "493:904410099:477668462", "อืม ใช่ มีงานให้ Lieutenant Doren กับคนทางเหนือต้องการเสบียงประจำจากเรา\n\nยังไม่ได้ส่ง และโทรลล์โจมตีจึงต้องใช้คน ค่าย Doren อยู่ตะวันตกเฉียงเหนือของถนนตรงทางเข้า Stranglethorn จาก Duskwood ส่งให้ Private Thorsen หากไม่อยู่ค่ายคงลาดตระเวนทางใต้ เขาจะดูแลเอง\n\nจำไว้ หากล้มเหลวต้องชดใช้ข้า" },
        progress = { "71:657993574:481576770 R 160:1757787434:178693414", "ว่าไง ต้องการอะไร? อ้อ เสบียงก็อบลิน แปลกที่{race}นำมา ปกติส่งคนตนเอง ไม่เป็นไร... ไม่แตะของใช่ไหม? ดี ๆ... เราไม่อยากให้ทุ่นระเบิดเป็นอะไร โอ้ ไม่เลย" },
        completion = { "234:1445568578:2025061193", "ทุ่นระเบิดพวกนี้ช่วยต้าน Kurzen เจ้าสัตว์ร้ายกับคนของมัน ขอบใจที่นำมา หากต้องการงานอีก ข้าคงหาให้ได้ และไม่ต้องรับมือก็อบลินพวกนั้นด้วยนะ?" },
        required = { [2252] = { "29:2089566949:1699212193", "ข้าวของเบ็ดเตล็ดของก็อบลิน" } },
        steps = { { "29:2089566949:1699212193", "ข้าวของเบ็ดเตล็ดของก็อบลิน" } },
    },
    [200] = { -- Bookie Herod
        title = { "12:1328284718:1367173619", "Bookie Herod" },
        objective = { "28:1722368667:1765939721", "หา Bookie Herod's Records" },
        description = { "499:506605750:1950900525", "หาก Kurzen รู้ความลับ Thorsen เราก็มีสายลับ ต้องรู้ว่าข่าวรั่วอย่างไร!\n\nผู้ติดต่อ Thorsen ในค่าย Kurzen คือ Bookie Herod เจ้าหน้าที่ส่งกำลังบำรุงที่รู้ทุกเรื่องของฐาน หากได้บันทึก อาจรู้ว่าถูกพบได้อย่างไร\n\nตอนเรายังอยู่กับ Kurzen ห้องทำงาน Bookie อยู่ชั้นบนของบ้านสองชั้นหลังเดียวในค่าย บันทึกคงยังอยู่" },
        completion = { "175:1299203496:1695430077", "นี่บันทึกกับทะเบียน Bookie Herod\n\nในนั้นมีรายชื่อเสบียง คำขอวัสดุจาก Colonel Kurzen และจดหมายต่าง ๆ" },
    },
    [201] = { -- Investigate the Camp
        title = { "20:1007571895:1767941775", "สำรวจค่าย" },
        objective = { "70:1236157363:1363853604", "หาค่ายนักล่าแล้วรายงานตำแหน่งให้ Krazek ที่ Booty Bay" },
        description = { "357:825410577:810893947 N 25:1501180744:638446975", "มีรายงานนักล่าตั้งค่ายเหนือน้ำจากค่ายเหมือง Venture Company ที่ Lake Nazferiti ปกติข้าไม่สน แต่ไม่น่าเชื่อว่า Hemet Nesingwary อยู่ด้วย? เขาเส้นสายดี เข้าใจใช่ไหม ระวังไว้ไม่เสียหาย\n\nไปดูค่าย {name} ว่าทำอะไรกันไหม?" },
        progress = { "49:197042006:1509314830", "ว่าไง หาค่ายสำเร็จไหม?" },
        completion = { "232:1011099372:1630453274", "อืม ข้อมูลข้าถูกตามเคย น่าสนใจ คงไม่ขวางกิจการเรา แต่บางทีต้องการสินค้ายอดเยี่ยมของเรา อืม..." },
        objectiveLabels = {
            event = { ["Locate the hunters' camp"] = "หาค่ายของเหล่านายพราน" },
        },
    },
    [202] = { -- Colonel Kurzen
        title = { "14:1575907498:319293510", "Colonel Kurzen" },
        objective = { "103:1314617689:1203786372", "สังหาร Kurzen Elite 6 คน, Kurzen Subchief 4 คน แล้วนำ Kurzen's Head ไปให้ Lieutenant Doren ที่ Rebel Camp" },
        description = { "361:1674598725:1054388635 N 47:1115777560:704283223", "เจ้าพิสูจน์ตนซ้ำแล้ว ความสามารถเหมือนทัดเทียม Kurzen อาจกอบกู้กบฏกลุ่มเรา... หากเผชิญเขาแล้วชนะ!\n\nเขาสั่งคนจากลึกใน Stockpile ต้องเข้าถ้ำ ฝ่าผู้คุ้มกัน เผชิญ Kurzen และผู้นำ\n\nลาก่อน {name} ความหวังข้ากับชะตาคนไปกับเจ้า" },
        progress = { "52:969382772:1838222706 N 1:63:63", "ข้ากล้าหวังไหมว่า Kurzen กับผู้ป้องกันตายแล้ว {name}?" },
        completion = { "261:123666236:1516785068", "ไม่กล้าเชื่อรายงาน แต่เจ้ามีหลักฐานว่า... Kurzen กับผู้นำพ่าย เจ้าช่วยเรา!\n\nป่ามีภัยสารพัด แต่ไม่มีใครมีปัญญาโหดเท่า Kurzen เมื่อเขาไป เราก็หายใจโล่งขึ้น" },
        required = { [3615] = { "13:10605450:1401352787", "ศีรษะของ Kurzen" } },
        steps = { { "13:10605450:1401352787", "ศีรษะของ Kurzen" } },
        objectiveLabels = {
            monster = { ["Kurzen Elite slain"] = "ปราบ ทหารชั้นยอดของ Kurzen", ["Kurzen Subchief slain"] = "ปราบ รองหัวหน้าของ Kurzen" },
        },
    },
    [203] = { -- The Second Rebellion
        title = { "20:1209792188:1529661963", "การกบฏครั้งที่สอง" },
        objective = { "75:1317848610:88335901", "สังหาร Kurzen Jungle Fighter 15 คน\n\nกลับไปหา Sergeant Yohwa ที่ Rebel Camp" },
        description = { "299:712170133:1458175616", "เราสู้ศึกกำลังแพ้ Colonel Kurzen ไม่เพียงนักยุทธศาสตร์เก่ง แต่คนมากกว่าอย่างน้อย 10 ต่อ 1! หากจะรอด ต้องใช้กลยุทธ์ลับของเขาต้านกลับ\n\nเข้าค่ายตะวันออก ฆ่าคนเขามาก ๆ แล้วออกก่อนกำลังเสริมล้อมทัน" },
        progress = { "47:147601225:380966350 N 51:247972953:431902674", "หวังว่าล่าสำเร็จ {name} หากไม่ช่วย เราคงทนเขาได้ไม่นาน" },
        completion = { "204:1251925122:1335591889", "ทำได้ดี เสีย Jungle Fighter ไปจะลดแรงกดค่ายเรา\n\nแต่เมื่อชิมกำลังที่ต้องสู้แล้ว ยังอยากร่วมชะตากับเราหรือ??" },
        objectiveLabels = {
            monster = { ["Kurzen Jungle Fighter slain"] = "ปราบ นักรบป่าดงดิบของ Kurzen" },
        },
    },
    [204] = { -- Bad Medicine
        title = { "12:895531913:1744134764", "ยาอันตราย" },
        objective = { "85:380365677:321677999", "นำ Jungle Remedy 7 ชิ้นและ Venom Fern Extract 1 ชิ้นไปให้ Sergeant Yohwa ที่ Rebel Camp" },
        description = { "502:971425158:1797182503", "หากจะชนะ Kurzen ต้องตัดฝ่ายรักษา เขารวม Medicine Man มาก ใช้ Jungle Remedy รักษาคนและ Venom Fern Extract วางพิษนักสู้เรา\n\nเราต้องใช้ยารักษาคน กับตัวอย่างสารสกัดเพื่อศึกษาแก้เอง ค้นฐาน Kurzen หา Medicine Man มียา ส่วนสารสกัดคงเก็บในลังเสบียง" },
        progress = { "48:1182962426:1590366309 N 1:46:46", "ข้ารอยากับสารสกัด {name}" },
        completion = { "11:534428891:784080240 N 121:326146251:1069868977", "ทำได้ดี {name} ยานี้ให้คนเรารอดและพร้อมสู้ สารสกัดช่วยสร้างยาเอง" },
        required = { [2633] = { "13:14703135:236305818", "ยารักษาจากป่าดงดิบ" }, [2634] = { "18:1582219490:403670535", "สารสกัดจากเฟิร์นพิษ" } },
        steps = { { "13:14703135:236305818", "ยารักษาจากป่าดงดิบ" }, { "18:1582219490:403670535", "สารสกัดจากเฟิร์นพิษ" } },
    },
    [205] = { -- Troll Witchery
        title = { "14:1126748720:898066886", "มนตร์โทรลล์" },
        objective = { "67:382604623:1457926187", "นำ Skullsplitter Fetish 4 ชิ้นไปให้ Brother Nimetz ที่ Rebel Camp" },
        description = { "245:2109446490:1617543729", "ระหว่างศึกษาตำนานที่หาให้ จงรวบรวมเครื่องมือเวทชั่วโทรลล์ เข้าแดน Skullsplitter อีกเผ่าไกลทางใต้ ชิง Skullsplitter Fetish จาก Witchdoctor กับ Mystic" },
        progress = { "28:1434021564:1594892706 N 67:1409301901:1309960543", "มีเครื่องรางไหม {name}? อาจมีความลับที่ทำ Kurzen เสื่อมทราม... ข้าต้องรู้!" },
        completion = { "98:528417549:1722380021", "ขอบใจ ข้าจะศึกษาเครื่องรางว่ามีความลับที่ทำ Kurzen ตกสู่ความชั่วไหม" },
        required = { [2466] = { "20:233213063:1756188075", "เครื่องรางเผ่า Skullsplitter" } },
        steps = { { "20:233213063:1756188075", "เครื่องรางเผ่า Skullsplitter" } },
    },
    [206] = { -- Mai'Zoth
        title = { "8:1553240550:1584604695", "Mai'Zoth" },
        objective = { "57:1860631429:2044541211", "นำ Mind's Eye ไปให้ Brother Nimetz ที่ Rebel Camp" },
        description = { "492:938447593:1322608051", "Kurzen อาจตาย แต่... สิ่งที่ผลักเขาสู่ความชั่วยังอยู่! ข้าศึกษาพบจอมเวทโอเกอร์ Mai'Zoth อยู่เนินโอเกอร์ในภูเขาตะวันออก Stranglethorn เล่าว่าใช้มนตร์ควบคุมจิต ข้ามั่นใจว่าทำ Kurzen แปดเปื้อน\n\nหากปล่อย ความชั่วอาจครอบคนอื่น เกิด Kurzen อีกคน\n\nฆ่าแล้วนำ Mind's Eye วัตถุที่ใช้ครอบงำผู้อื่นมา" },
        progress = { "72:729064059:1783651987", "ข้าให้พร ความแข็งแกร่ง Mai'Zoth มีเพียงความชั่วเขาที่เทียบได้" },
        completion = { "53:804514684:922620265 N 142:417486142:1881600912", "อาฮ่า! สำเร็จ! เจ้าคือพลังยิ่งใหญ่ฝ่ายดี {name} ขอความแข็งแกร่งไม่เลือน!\n\nข้าจะศึกษาว่า Mind's Eye ใช้เพื่อดีได้ไหม หากไม่ได้... ต้องทำลาย" },
        required = { [3616] = { "10:385680669:813601013", "ดวงตาแห่งจิต" } },
        steps = { { "10:385680669:813601013", "ดวงตาแห่งจิต" } },
    },
    [207] = { -- Kurzen's Mystery
        title = { "16:1893488143:1179896735", "ปริศนา Kurzen" },
        objective = { "66:1753365011:1534002668", "หาแผ่นจารึก 4 แผ่น แล้วนำตำนานกลับไปให้ Brother Nimetz" },
        description = { "497:873820246:418866052", "Colonel Kurzen เคยยิ่งใหญ่สูงศักดิ์ ต้องหาสิ่งที่ทำเสื่อมทราม! อาจอยู่ใต้มนตร์โทรลล์ เพื่อยืนยันต้องศึกษาตำนาน\n\nมีแผ่นจารึก 4 แผ่นในซากโทรลล์ Stranglethorn ข้าต้องเห็นข้อความ! คัดอักขระกลับมา\n\nแผ่นแรก Bal'lal Ruins แผ่นสอง Vile Reef แผ่นสามกับสี่ Ruins of Zul'Kunda" },
        progress = { "N 59:908498768:925170928", "{name}! มีตำนานโทรลล์ไหม? ต้องรู้ความลับ!" },
        completion = { "11:1191658970:1224418299 N 124:1550242954:1738269665", "ขอบใจ {name} จะศึกษาว่าโทรลล์เกี่ยวกับความชั่วที่สิง Colonel Kurzen หรือไม่" },
        required = { [2005] = { "22:773853625:1194596674", "ตำนานโทรลล์เรื่องที่ 1" }, [2006] = { "23:1213465683:868137125", "ตำนานโทรลล์เรื่องที่ 2" }, [2007] = { "22:117908125:1698887074", "ตำนานโทรลล์เรื่องที่ 3" }, [2008] = { "23:818326762:630784300", "ตำนานโทรลล์เรื่องที่ 4" } },
        steps = { { "22:773853625:1194596674", "ตำนานโทรลล์เรื่องที่ 1" }, { "23:1213465683:868137125", "ตำนานโทรลล์เรื่องที่ 2" }, { "22:117908125:1698887074", "ตำนานโทรลล์เรื่องที่ 3" }, { "23:818326762:630784300", "ตำนานโทรลล์เรื่องที่ 4" } },
    },
    [208] = { -- Big Game Hunter
        title = { "15:92073620:1240943732", "นักล่าสัตว์ใหญ่" },
        objective = { "90:1219389657:1530414278", "Hemet Nesingwary ต้องการศีรษะ King Bangalash เสือขาวผู้ยิ่งใหญ่" },
        description = { "N 486:575740475:1238198590", "{name} เจ้าคู่ควรเป็นนักล่าร่วมเรา จากสนามรบ Lordaeron ถึงป่าลึก ข้าแทบไม่เคยเห็นฝีมืออาวุธเช่นเจ้า\n\nฆ่า Sin'Dall ดุร้าย, Bag'thera จับยาก และ Tethis เจ้าเล่ห์แล้ว แต่รางวัลแท้คือหัว King Bangalash เสือขาวนั้นคือเหตุที่ข้ามา เฝ้ารอมานาน ฆ่าแล้วพิสูจน์ว่าฝีมือล่าไม่มีใครเหนือ" },
        progress = { { "116:384491549:1953465318", "110:1133753983:250835869" }, "กลับมาแล้วหรือ King Bangalash ทำข้าคลานกลับค่ายหลายครั้ง อดทนไว้" },
        completion = { "44:578957572:1987025652 N 207:1444718425:1407818377", "ยอดเยี่ยมจริง! ถูกต้อง! ยินดี {name} ที่สำเร็จในสิ่งคนอื่นพลาด\n\nเป็นเกียรติที่นับเป็นสหายในคณะล่ายิ่งใหญ่เรา ไม่มีใครสงสัยความชำนาญล่าและตามรอยอีก!\n\nขอฉลองให้เจ้า! ฉลอง!" },
        required = { [3880] = { "17:1168379304:1379122925", "ศีรษะของ Bangalash" } },
        steps = { { "17:1168379304:1379122925", "ศีรษะของ Bangalash" } },
    },
    [209] = { -- Skullsplitter Tusks
        title = { "19:874884227:1533083693", "งา Skullsplitter" },
        objective = { "56:89706816:1039627707", "หา Skullsplitter Tusk 18 ชิ้นไปให้ Kebok" },
        description = { "498:1623864424:1094645830", "ฆ่าเสือพอส่งออกเขี้ยวไปหมู่เกาะ South Seas ทั้งยากและแพง โชคดีเราคิดเทคนิคเปลี่ยนของคล้ายเขาธรรมดาเป็นของปลอมแยกไม่ออก\n\nน่าทึ่งที่ของใกล้ที่สุดคืองาโทรลล์ Skullsplitter\n\nก่อนพูด ผู้ซื้อไม่รู้ก็ไม่เจ็บจริงไหม? นำมามาก ๆ ให้เริ่มของส่งรายเดือน!" },
        progress = { "130:1603741843:1535870158", "พวกนั้นอึดใช่ไหม? ได้มาบ้างหรือ? ขอโทษที่ดูร้อนใจ แต่เป็นหนามตำใจใหญ่! ว่าไง?" },
        completion = { "136:810729955:61239559 N 126:1418709450:1995994200", "อา ดีมาก ดีมาก! อึ๋ย น่าล้างให้สะอาดกว่านี้ตรง... ช่างเถอะ! ขอบใจ {name} กิจการคงผลิตเพิ่มมีประสิทธิภาพเพราะเจ้า ดี ๆ ทีนี้เรื่องอื่น..." },
        required = { [1524] = { "18:1440630628:1339536317", "งา Skullsplitter" } },
        objectiveLabels = {
            item = { ["Skullsplitter Tusk"] = "งา Skullsplitter" },
        },
    },
    [210] = { -- Krazek's Cookery
        title = { "16:1570030026:215447814", "หม้อครัว Krazek" },
        objective = { "46:677075623:2103656562", "นำ Krazek's Crock Pot ไปให้ก็อบลิน Krazek" },
        description = { "299:564077095:1699818152", "ข้าทำอาหารค่ายส่วนใหญ่ เคยงานหนักจนซื้อหม้อกลจากพ่อค้าก็อบลิน Booty Bay มหัศจรรย์! ประหยัดเวลานับไม่ถ้วน... จนพัง!\n\nนำคืนให้ก็อบลินซ่อมได้ไหม? ชื่อ Krazek" },
        progress = { "32:173881952:201166736", "สวัสดี! เอาอะไรให้ข้าหรือ?" },
        completion = { "423:299411086:831248191", "อ้อ หม้อ Krazek! งานชาญฉลาด แต่สปริงขาดหรือเฟืองหลุดบ้าง ขอหาสาเหตุ...\n\nอาฮ่า! ตัวอัดไอน้ำขึ้นสนิม ปะเก็นข้อต่อร้าว ตัว Fobulator ฟันหาย แปลกที่ยังต้มเทอร์นิปไหว!\n\nซ่อมได้ไหม? ได้แน่!\n\nแต่มีราคา อ้อ ทุกอย่างมีราคา..." },
        required = { [4085] = { "18:755019105:1101412398", "หม้อตุ๋นของ Krazek" } },
        steps = { { "18:755019105:1101412398", "หม้อตุ๋นของ Krazek" } },
    },
    [213] = { -- Hostile Takeover
        title = { "16:2015238705:723159084", "ฮุบกิจการอย่างเป็นปฏิปักษ์" },
        objective = { "66:859092959:939348428", "นำ Tumbled Crystal 8 ชิ้นไปให้ Kebok ที่ Booty Bay" },
        description = { "501:735210194:287104531", "คราวนี้มันเอาจริง! Gelriz เบียดเจ้าสัวที่เจ้าชายการค้าแต่งตั้งก็แย่พอ ยังจะตัดหน้าโจรสลัดชื่อฉาวที่สุด!\n\nRevilgaz ไม่ยอม สั่งข้าจัดการตามวิธีตน\n\nวิธีข้าคือขโมย นักธรณี Venture Co. ใกล้ Lake Nazferiti สนใจผลึกฟ้าประหลาดจากเหมือง นำตัวอย่างจากพวกนั้นมา ไม่สนว่าทำอย่างไร" },
        progress = { "21:546285656:444383840 N 90:1751288891:2043436271 N 29:1484205074:1282071244", "ข้าต้องการหิน {name} ทุกวิถีทาง! ทำเลย ไม่ต้องเล่ารายละเอียด!\n\nสนแต่ผลลัพธ์ {name} เท่านั้น" },
        completion = { "257:517941384:977648270", "น่าสนใจ การขัดผลึกด้วยวิธีนี้บอกได้เพียงว่าคิดใช้เป็นเชื้อเพลิงหรือตัวเร่งบางอย่าง ข้าไม่รู้มากกว่านี้ ต้องส่งตัวอย่างให้ Head Chemist Gigglefont" },
        required = { [4106] = { "15:871601849:1295161938", "ผลึกที่ขัดจนมน" } },
        steps = { { "15:871601849:1295161938", "ผลึกที่ขัดจนมน" } },
    },
    [215] = { -- Jungle Secrets
        title = { "14:1513588637:1007182819", "ความลับในป่า" },
        objective = { "46:1380701157:1054822769", "คุยกับ Lieutenant Doren ที่ Rebel Camp" },
        description = { "25:2112727214:1834163064 N 428:289427831:919975170", "ขอบคุณที่ช่วยข้า {name} ข้ารู้ว่าเรื่องนี้ดูเป็นอย่างไร แต่...ขออธิบายก่อน\n\nLieutenant Doren สั่งให้ข้ากลับไปสมัครเป็นทหารของ Kurzen เพื่อสืบข่าวที่ฝ่ายกบฏต้องการอย่างยิ่ง ข้านึกว่าเหตุการณ์ที่เจ้าเห็นจะเปิดโอกาสให้แทรกซึมเข้า Kurzen's Compound แต่ข้าคิดผิด ขอบคุณอีกครั้งที่ช่วยไว้\n\nนี่เป็นภารกิจลับสุดยอด อย่าบอกใคร แต่หากคุยกับ Doren เขาจะอธิบายให้ฟัง" },
        completion = { "459:1499056144:2006542938", "ใช่ เรื่องที่ Thorsen บอกเป็นความจริง เจ้าต้องเก็บเป็นความลับ ครั้งหนึ่งฝ่ายกบฏอย่างเราเคยภักดีต่อ Colonel Kurzen อย่างแรงกล้า แต่ความเสื่อมทรามของเขาเปลี่ยนความภักดีเป็นความแค้น หากใครรู้ว่า Private Thorsen เพิ่งติดต่อกับคนของ Kurzen คืนหนึ่งเขาคงถูกเชือดคอ\n\nเท่าที่ข้ารู้ มีเพียง Sergeant Yohwa, Thorsen และข้าที่รู้ภารกิจนี้ แต่ต้องมีอีกคน คนทรยศ" },
    },
    [328] = { -- The Hidden Key
        title = { "14:2115824611:800125003", "กุญแจที่ซ่อนไว้" },
        objective = { "57:460619628:157873874", "ใช้ Small Brass Key เปิด Bookie Herod's Strongbox" },
        description = { "499:1846919729:1643378926", "แม้บันทึกเหล่านี้จะไม่กล่าวถึง Private Thorsen แต่ในสันสมุดบัญชีเล่มหนึ่งของ Herod มีกุญแจทองเหลืองดอกเล็กซ่อนอยู่\n\nเมื่อตรวจบันทึกเพิ่มเติม ก็พบเอกสารหลายฉบับพูดถึง “หีบนิรภัยที่แน่นหนา” หีบนั้นอยู่ใน Stockpile กลุ่มถ้ำด้านหลัง Kurzen's Compound\n\nหากพบหีบและกุญแจทองเหลืองดอกนี้เปิดได้ ก็อาจไขปริศนาว่า Thorsen ถูกจับได้อย่างไร" },
        progress = { "62:600846090:626013915", "หีบเสริมขอบด้วยสำริด แข็งแรงและหนักมาก" },
        completion = { "99:1965351206:929395421", "เมื่อเปิดหีบก็เห็นชัดว่า Herod เก็บเหรียญและสิ่งของมีค่าของเขาไว้ที่นี่" },
        required = { [2719] = { "15:1884237836:278638781", "กุญแจทองเหลืองดอกเล็ก" } },
        steps = { { "15:1884237836:278638781", "กุญแจทองเหลืองดอกเล็ก" } },
    },
    [329] = { -- The Spy Revealed!
        title = { "17:926445013:267674240", "เปิดโปงสายลับ!" },
        objective = { "58:1100537959:1062105369", "นำ Muddy Note ไปให้ Lieutenant Doren ที่ Rebel Camp" },
        description = { "399:240680118:596515288", "ท่ามกลางของมีค่าในหีบมีกระดาษเปื้อนโคลนเขียนอย่างลวก ๆ แม้อ่านแทบไม่ออก แต่ดูเหมือนตารางกิจวัตรของ Private Thorsen ระบุเส้นทางลาดตระเวน คนที่เขาคุยด้วย และการใช้เวลาอยู่กับฝ่ายกบฏ ลงชื่อเพียงอักษรเดียว: -M\n\nผู้เขียนต้องอยู่ใกล้ชิด Thorsen มาก และคนผู้นั้นก็คือคนทรยศในค่ายกบฏ" },
        progress = { "72:1289357900:467966368", "เจ้ารู้หรือยังว่าใครล่วงรู้ความลับของ Thorsen? มีคนทรยศอยู่ในหมู่เราหรือ?" },
        completion = { "11:1191658970:1224418299 N 56:1065868886:838801971", "ขอบคุณ {name} บันทึกนี้คือเบาะแสที่เราต้องใช้เปิดโปงคนทรยศ!" },
        required = { [2720] = { "10:529173771:978591052", "ข้อความเปื้อนโคลน" } },
        steps = { { "10:529173771:978591052", "ข้อความเปื้อนโคลน" } },
    },
    [330] = { -- Patrol Schedules
        title = { "16:1498399427:13517220", "ตารางลาดตระเวน" },
        objective = { "28:1889386073:1040276584", "คุยกับ Corporal Sethman" },
        description = { "326:1488862465:2143334532", "บันทึกที่เจ้าให้ข้าลงชื่อว่า “-M”...ข้าไม่รู้ว่าหมายถึงอะไร\n\nแต่ในนั้นบอกด้วยว่าคนผู้นี้ลาดตระเวนเส้นทางเดียวกับ Thorsen เมื่อสัปดาห์ก่อน ดังนั้นคนที่ลาดตระเวนร่วมกับ Thorsen สัปดาห์ก่อนก็คือคนทรยศ!\n\nไปหา Corporal Sethman เขาจัดตารางลาดตระเวนและบอกได้ว่าใครอยู่กับ Thorsen" },
        completion = { "167:1609211274:546412869", "อ้อ ได้ ข้าตรวจให้ได้ ไหนดูสิ...สัปดาห์ก่อนเป็น...\n\nอ้าว Private Merle ถูกจัดให้ไปกับ Thorsen ทั้งคู่ลาดตระเวนเวลาเดียวกันตลอดสัปดาห์ก่อน" },
    },
    [331] = { -- Report to Doren
        title = { "15:701206247:455562940", "รายงานต่อ Doren" },
        objective = { "28:1850056793:1625166158", "คุยกับ Lieutenant Doren" },
        description = { "81:1910336635:1280212612", "Lieutenant Doren ต้องการให้เจ้านำข้อมูลลาดตระเวนกลับไปรายงานเขาใช่ไหม?" },
        completion = { "254:48073860:1218437812", "ข้าเสียใจที่รู้ว่า Merle เป็นคนทรยศ เขาเป็นทหารกล้าหาญมาตลอด ข้าเคยคิดว่าเขาซื่อตรง แต่ก็โล่งใจมากที่เปิดโปงเขาได้ หากมีสายลับเช่นเขาอยู่ในหมู่เรา...เราคงต้าน Colonel Kurzen ได้อีกไม่นาน" },
    },
    [338] = { -- The Green Hills of Stranglethorn
        title = { "32:642090983:1200577713", "เนินเขาเขียวแห่ง Stranglethorn" },
        objective = { "135:510155877:2037318820", "เก็บหน้าที่หายไปจากต้นฉบับ The Green Hills of Stranglethorn เมื่อรวบรวมครบทั้งสี่บทแล้ว ให้นำกลับไปให้ Barnil" },
        description = { "472:2135855678:2082703225", "หากอาจารย์ Nesingwary รู้เข้าต้องโกรธมากแน่!\n\nเขาไว้ใจให้ข้าตรวจต้นฉบับนวนิยาย The Green Hills of Stranglethorn ทุกอย่างราบรื่นดี จนลมแรงพัดผ่านค่าย ทำให้หน้ากระดาษปลิวกระจัดกระจาย!\n\nข้าเก็บกลับมาได้เกือบหมด แต่ยังมีอีกหลายหน้าอยู่ทั่วป่า ช่วยเก็บให้ครบทั้งสี่บทด้วย\n\nข้าจะช่วยเรียงหน้าให้ เมื่อครบทั้งสี่บทแล้วนำกลับมาให้ข้า" },
        progress = { "37:924447204:1344698236 N 1:63:63", "เจ้ารวบรวมแต่ละบทได้หรือยัง {name}?" },
        completion = { "45:1427510919:1826454925 N 125:691729863:1524915081", "เจ้าช่วยให้ข้ารอดจากเรื่องยุ่งยากใหญ่หลวงเลย {name}! ขอบคุณเท่าไรก็ไม่พอ อีกไม่นานคงได้เห็นหนังสือของอาจารย์ Nesingwary ตามห้องสมุดทั่วโลกแล้ว!" },
        required = { [2756] = { "40:2095497062:94328799", "เนินเขาเขียวแห่ง Stranglethorn บทที่ I" }, [2757] = { "41:1671833257:1619654597", "เนินเขาเขียวแห่ง Stranglethorn บทที่ II" }, [2758] = { "42:164417722:1721356638", "เนินเขาเขียวแห่ง Stranglethorn บทที่ III" }, [2759] = { "41:1671833270:1619654610", "เนินเขาเขียวแห่ง Stranglethorn บทที่ IV" } },
        steps = { { "40:2095497062:94328799", "เนินเขาเขียวแห่ง Stranglethorn บทที่ I" }, { "41:1671833257:1619654597", "เนินเขาเขียวแห่ง Stranglethorn บทที่ II" }, { "42:164417722:1721356638", "เนินเขาเขียวแห่ง Stranglethorn บทที่ III" }, { "41:1671833270:1619654610", "เนินเขาเขียวแห่ง Stranglethorn บทที่ IV" } },
    },
    [339] = { -- Chapter I
        title = { "9:1017088854:826646109", "บทที่ I" },
        objective = { "126:1082040029:1148822172", "นำหน้า 1, 4, 6 และ 8 ของ The Green Hills of Stranglethorn โดย Nesingwary ไปให้ Barnil Stonepot เพื่อรวบรวมบทที่ I ให้ครบ" },
        description = { "284:555319894:1687772440", "บทที่ I ชวนติดตามมาก! อาจารย์ Nesingwary ปูฉากของเรื่องและกล่าวถึงเพื่อนร่วมล่า รวมถึงข้าด้วย!\n\nแต่เอาเถอะ มาดูว่ายังขาดหน้าไหน ดูเหมือนหน้า 1, 4, 6 และ 8 ยังอยู่ที่ไหนสักแห่งในป่า!" },
        progress = { "125:1452572084:972328762", "เจ้าตามหาหน้า 1, 4, 6 และ 8 ได้หรือเปล่า? เราต้องการเพียงสี่หน้านี้เพื่อรวบรวมบทที่ I กลับมาให้ครบ" },
        completion = { "31:37802598:839597604", "ในที่สุด! บทที่ I ครบแล้ว!" },
        required = { [2725] = { "37:141066341:551032661", "เนินเขาเขียวแห่ง Stranglethorn หน้า 1" }, [2728] = { "37:141066344:551032664", "เนินเขาเขียวแห่ง Stranglethorn หน้า 4" }, [2730] = { "37:141066346:551032666", "เนินเขาเขียวแห่ง Stranglethorn หน้า 6" }, [2732] = { "37:141066348:551032668", "เนินเขาเขียวแห่ง Stranglethorn หน้า 8" } },
        steps = { { "37:141066341:551032661", "เนินเขาเขียวแห่ง Stranglethorn หน้า 1" }, { "37:141066344:551032664", "เนินเขาเขียวแห่ง Stranglethorn หน้า 4" }, { "37:141066346:551032666", "เนินเขาเขียวแห่ง Stranglethorn หน้า 6" }, { "37:141066348:551032668", "เนินเขาเขียวแห่ง Stranglethorn หน้า 8" } },
