    [341] = { -- Chapter III
        title = { "11:118291226:1944516640", "บทที่ III" },
        objective = { "130:1570943909:711032612", "นำหน้า 18, 20, 21 และ 24 ของ The Green Hills of Stranglethorn โดย Nesingwary ไปให้ Barnil Stonepot เพื่อรวบรวมบทที่ III ให้ครบ" },
        description = { "281:1012147483:1689199280", "บทที่ III เป็นบทโปรดของข้า เล่าถึงการล่าสำเร็จครั้งแรกของ Sir Erlgadin และ Lady Rouack ด้วยปืนไรเฟิลคนแคระ ส่วนตอนจบน่ะหรือ ค้างคาใจเสียจริง!\n\nดูเหมือนยังขาดหน้า 18, 20, 21 และ 24 จึงจะครบ หน้าพวกนั้นอยู่ที่ไหนสักแห่งข้างนอก..." },
        progress = { "100:919836869:509562584", "เจอหน้า 18, 20, 21 หรือ 24 บ้างไหม? เราต้องการเพียงหน้าเหล่านี้เพื่อรวบรวมบทที่ III ให้ครบ" },
        completion = { "17:2140221267:1552392564 N 48:992159762:102894482", "เฮ้อ! ทำได้ดี {name} ตอนนี้บทที่ III กลับมาครบแล้ว!" },
