    [348] = { -- Stranglethorn Fever
        title = { "19:1057194224:1481583218", "ไข้ป่า Stranglethorn" },
        objective = { "108:1863969964:2032411084", "ไปหา Witch Doctor Unbagwa ให้เขาเรียก Mokk the Savage ออกมา แล้วนำ Heart of Mokk ไปให้ Fin Fizracket" },
        description = { "322:1735744767:1715734073", "ป่วย...ป่วย...หะ...หนักเหลือเกิน...\n\n...ติดไข้ป่า Stranglethorn...ไว...ไวรัสมรณะ...\n\n...ทางรักษาเดียว...คือ...กินหัวใจของ Mokk the Savage...สัตว์ร้ายสีขาวที่พบตัวยาก...\n\n...Witch Doctor Unbagwa...คนเดียวที่เรียกมันออกมาได้...\n\n...หา Unbagwa ในถ้ำลับบนแหลมทางใต้...\n\n...เร็วเข้า...จะตายแล้ว...จะตายแล้ว..." },
        progress = { "88:708039165:2087757233", "...แม่จ๋า?\n\n...หนาวเหลือเกิน...\n\n...กำลังไปสู่ Twisting Nether...กอด...กอดข้าหน่อยแม่..." },
        completion = { "140:76526933:1807611629", "...รู้สึกว่ากำลังกลับมาแล้ว...\n\nข้าอยู่ที่ไหน? Booty Bay หรือ? ตายจริง! ข้าฝันประหลาดเหลือเกิน...\n\n...ยังรู้สึกอ่อนแรงอยู่บ้าง..." },
        required = { [2797] = { "13:1219616116:1558621735", "หัวใจของ Mokk" } },
        steps = { { "13:1219616116:1558621735", "หัวใจของ Mokk" } },
    },
    [349] = { -- Stranglethorn Fever
        title = { "19:1057194224:1481583218", "ไข้ป่า Stranglethorn" },
        description = { "26:740086088:1367077878", "ข้อความชั่วคราว 02 - คำอธิบาย" },
        progress = { "316:1159889367:1019637871", "Witch Doctor Unbagwa รู้ว่า Mokk the Savage ชอบอะไร ใช่แล้ว ใช่แล้ว!\n\nข้าคุยกับวิญญาณแล้วเรียกมันมาได้\n\nแต่สัตว์กอริลลาตัวอื่นก็ชอบเสียงคุยกับวิญญาณด้วย เจ้าปกป้อง Witch Doctor Unbagwa แล้วข้าจะเรียกมันมาให้\n\nWitch Doctor Unbagwa ต้องการของก่อน เอา Gorilla Fangs มา 10 อัน แล้วข้าจะเริ่มคุยกับวิญญาณ!" },
        completion = { "179:728167262:519819307", "Witch Doctor Unbagwa ชอบ Gorilla Fangs! ข้าจะคุยกับวิญญาณให้เจ้า เรียก Mokk the Savage ออกมา\n\nแต่เจ้าต้องปกป้อง Witch Doctor Unbagwa จากสัตว์กอริลลาตัวอื่น ไม่อย่างนั้นเจ้าก็ไม่ได้พบ Mokk!" },
        objective = { "32:1156414266:1322729090", "คุยกับ Witch Doctor Unbagwa" },
        required = { [2799] = { "12:571053624:729469945", "เขี้ยวกอริลลา" } },
        objectiveLabels = {
            item = { ["Gorilla Fang"] = "เขี้ยวกอริลลา" },
        },
    },
    [568] = { -- The Defense of Grom'gol
        title = { "23:551553035:2139094829", "ป้องกัน Grom'gol" },
        objective = { "85:227569189:2036398613", "Commander Aggro'gosh แห่งค่ายฐาน Grom'gol ต้องการให้เจ้าฆ่า Lashtail Raptors 15 ตัว" },
        description = { "10:1652484069:1189355142 C 447:25738609:329194549", "Throm'ka {class}!\n\nเจ้ามาถึง Grom'gol ได้เหมาะเวลาจริง ๆ ในฐานะผู้บัญชาการฐานของ Warchief ในป่าแห่งนี้ เกียรติยศผูกมัดให้ข้าดูแลความปลอดภัยของชาว Horde ทุกคน ภารกิจจัดเส้นทางส่งเสบียงอย่างปลอดภัยไป Stonard กำลังถูกสัตว์พื้นถิ่นขัดขวาง\n\nข้ามอบหมายให้เจ้าลดจำนวนแรปเตอร์นอก Grom'gol เมื่อจัดการได้มากพอแล้ว จงกลับมารายงานเพื่อรับงานต่อไป" },
        progress = { "81:1891175681:55279268 C 1:46:46", "แรปเตอร์พื้นถิ่นยังขัดขวางการส่งเสบียงของเราอยู่ {class}" },
        completion = { "36:1036235480:16577835 C 1:46:46", "เจ้าปฏิบัติหน้าที่ได้อย่างมีเกียรติ {class}" },
        objectiveLabels = {
            monster = { ["Lashtail Raptor slain"] = "ปราบ แรปเตอร์หางฟาด" },
        },
    },
    [569] = { -- The Defense of Grom'gol
        title = { "23:551553035:2139094829", "ป้องกัน Grom'gol" },
        objective = { "105:2136597638:1730981106", "Commander Aggro'gosh แห่งค่ายฐาน Grom'gol ต้องการให้เจ้าฆ่า Ogre Brutes 10 ตัว และ Ogre Witch Doctors 5 ตัว" },
        description = { "499:1899375781:1634535852", "เมื่อมาถึงป่านี้ เราไม่ได้ตั้งใจทำสงครามกับเผ่าพื้นถิ่น ภารกิจส่งเสบียงให้ Stonard สำคัญที่สุด แต่เกิดปัญหาขึ้น ออกร์กลุ่มหนึ่งยึด Mizjah Ruins ทางตะวันออกเฉียงใต้ของ Grom'gol แม้เราจะเตือนแล้ว พวกมันยังซุ่มโจมตีกองเกวียนเสบียงของเรา\n\nข้ามอบหมายให้เจ้าจัดการออกร์ที่ไม่ยอมร่วมมือเหล่านี้\n\nไปยังซากปรักหักพังแล้วพยายามขับไล่มันออกไป อย่างน้อยก็เป็นการส่งคำเตือนที่ชัดเจน" },
        progress = { "67:813977939:1748868653 C 1:63:63", "เจ้าจัดการออกร์ที่ Mizjah Ruins คืบหน้าบ้างหรือยัง {class}?" },
        completion = { "51:2016689362:1962636833", "ทำได้ดี เจ้ารับใช้ Warchief อย่างมีเกียรติ" },
        objectiveLabels = {
            monster = { ["Mosh'Ogg Brute slain"] = "ปราบ อ็อกเกอร์จอมโหด Mosh'Ogg", ["Mosh'Ogg Witch Doctor slain"] = "ปราบ หมอผี Mosh'Ogg" },
        },
    },
    [570] = { -- Mok'thardin's Enchantment
        title = { "25:67595655:553070638", "มนตร์ของ Mok'thardin" },
        objective = { "99:280347546:77873885", "Far Seer Mok'thardin ที่ค่ายฐาน Grom'gol ต้องการ Shadowmaw Claws 8 อัน และ Pristine Tigress Fang" },
        description = { "178:2006395135:196976485 C 295:903430024:2044755001", "Horde ต้องเข้าใจและควบคุมพลังเวทแห่งป่า พิธีกรรมของข้าได้ผลดีจนถึงตอนนี้ ข้าร่ายมนตร์ทรงพลังได้ และจะสร้างสิ่งของพิเศษให้เจ้า {class} ผู้กล้า\n\nนำกรงเล็บ Shadowmaw Panther กับเขี้ยวเสือโคร่งตัวเมียมาให้ข้า เขี้ยวธรรมดาใช้ไม่ได้ ต้องสมบูรณ์ไร้ตำหนิ\n\nสัตว์เหล่านี้ซุ่มอยู่ทั่วป่า แต่เจ้าอาจพบใกล้ ๆ เพียงข้ามแม่น้ำจาก Mizjah Ruins ทางตะวันออกเฉียงใต้" },
        progress = { "23:753611373:2130935090", "เจ้ามีข่าวอะไร?" },
        completion = { "40:1438969841:875272101 N 120:364752356:1216939893", "เจ้ารู้จักป่าดีมาก {name} ตัวอย่างเหล่านี้เหมาะอย่างยิ่ง ข้าจะขอบคุณวิญญาณที่ยอมสละสัตว์ชั้นดีเช่นนี้เพื่อ Horde" },
        required = { [3838] = { "14:1329708985:1961136801", "กรงเล็บ Shadowmaw" }, [3839] = { "21:826465104:1653284672", "เขี้ยวเสือตัวเมียสภาพสมบูรณ์" } },
        steps = { { "14:1329708985:1961136801", "กรงเล็บ Shadowmaw" }, { "21:826465104:1653284672", "เขี้ยวเสือตัวเมียสภาพสมบูรณ์" } },
    },
    [571] = { -- Mok'thardin's Enchantment
        title = { "25:67595655:553070638", "มนตร์ของ Mok'thardin" },
        objective = { "64:391483156:1702642871", "นำ Aged Gorilla Sinew ไปให้ Far Seer Mok'thardin ที่ Grom'gol" },
        description = { "435:312650393:250065172", "สิ่งที่ข้าต้องการต่อไปหาได้ยากยิ่ง\n\nเพื่อยึดขนนก กรงเล็บ และเขี้ยวไร้ตำหนิเหล่านี้ไว้ด้วยกัน ข้าต้องใช้เส้นผูกวิเศษ มีเพียงเอ็นกอริลลาแก่เท่านั้นที่ใช้ได้\n\nเจ้าหาได้จาก Elder Mistvale Gorilla เท่านั้น พวกมันหาอาหารอยู่ทางตะวันออกของ Booty Bay\n\nเอ็นต้องสมบูรณ์ เจ้าคงต้องฆ่าหลายตัวกว่าจะได้สิ่งที่ข้าต้องการ แต่คุ้มกับการล่าแน่นอน" },
        progress = { "31:789604154:2016490392 N 48:643388476:808074404", "โชคเข้าข้างเจ้าไหม {name}? หาเอ็นกอริลลาแก่ได้หรือยัง?" },
        completion = { "20:773093152:465375796 N 33:1797932868:732206206", "เอ็นเส้นนี้เหมาะที่สุด {name} ความพยายามของเจ้าจะให้ผลในไม่ช้า" },
        required = { [3862] = { "18:934586276:1193677658", "เส้นเอ็นกอริลลาวัยชรา" } },
        steps = { { "18:934586276:1193677658", "เส้นเอ็นกอริลลาวัยชรา" } },
    },
    [572] = { -- Mok'thardin's Enchantment
        title = { "25:67595655:553070638", "มนตร์ของ Mok'thardin" },
        objective = { "83:872881995:845846550", "นำ Jungle Stalker Feathers 10 อัน ไปให้ Far Seer Mok'thardin ที่ค่ายฐาน Grom'gol" },
        description = { "484:459544413:106669888", "สิ่งที่เจ้าเก็บจากสัตว์ตระกูลเสือในหุบเขาเป็นเพียงส่วนแรกของวัตถุลงมนตร์อันทรงพลัง เครื่องรางจากป่าเหล่านี้กับพิธีชามานของข้าจะมอบเครื่องมือที่มีประโยชน์ยิ่งแก่เจ้า เพื่อช่วย Horde และ Warchief\n\nต่อไปเจ้าต้องเก็บ Jungle Stalker Feathers มาให้ข้า ตามธรรมเนียม สัตว์เหล่านี้สวมขนไว้ที่ปลอกแขน เจ้าจะพบฝูงแรปเตอร์ทางใต้ตรงจาก Grom'gol ไม่ไกลจากสนามประลองใหญ่" },
        progress = { "42:1950249422:1658178323", "เจ้าเก็บของได้ผลดีไหม?" },
        completion = { "45:775529564:248717730", "ยอดเยี่ยม ข้าจะเตรียมของเหล่านี้ทันที" },
        required = { [3863] = { "22:907128267:1130182514", "ขนของ Jungle Stalker" } },
        steps = { { "22:907128267:1130182514", "ขนของ Jungle Stalker" } },
    },
    [573] = { -- Mok'thardin's Enchantment
        title = { "25:67595655:553070638", "มนตร์ของ Mok'thardin" },
        objective = { "102:1796538211:674196603", "Far Seer Mok'thardin แห่ง Grom'gol ต้องการ Holy Spring Water และให้เจ้าฆ่า Naga Explorers 10 ตัวด้วย" },
        description = { "494:2086735856:1353858062", "เหลือส่วนประกอบสุดท้ายอีกอย่างเดียวก็จะลงมนตร์ได้สำเร็จ\n\nทางใต้ค่อนไปฝั่งตะวันตก สูงเหนือหน้าผามีน้ำพุศักดิ์สิทธิ์ บรรดานักวิชาการด้านศาสนาและเวทมนตร์ถกเถียงกันเรื่องน้ำพุนี้ ทุกเผ่าพันธุ์ใน Azeroth ต่างอ้างว่าน้ำพุได้รับพรเพื่อชนชาติของตน\n\nคำขอสุดท้ายของข้าคือ นำ Holy Spring Water มาให้ ระวังด้วย คณะสำรวจนากาเข้าครอบครองน้ำพุแล้ว เจ้าต้องจัดการพวกมันด้วย" },
        progress = { "77:1923269148:1195219053", "ข้าเกือบพร้อมลงมนตร์แล้ว เจ้าทำตามที่ข้าขอหรือยัง?" },
        completion = { "98:1385917191:268367104 N 65:1490493613:1566507600", "เมื่อมี Holy Spring Water สร้อยพิธีกรรมก็พร้อมรับมนตร์แล้ว\n\nสวมมันอย่างภาคภูมิ {name} ในนาม Warchief และเพื่อปกป้อง Horde อันยิ่งใหญ่" },
        required = { [737] = { "17:1435238426:1183373813", "น้ำพุศักดิ์สิทธิ์" } },
        steps = { { "17:1435238426:1183373813", "น้ำพุศักดิ์สิทธิ์" } },
        objectiveLabels = {
            monster = { ["Naga Explorer slain"] = "ปราบ นักสำรวจนากา" },
        },
    },
    [574] = { -- Special Forces
        title = { "14:1841393694:673762604", "หน่วยรบพิเศษ" },
        objective = { "99:842720586:1190340728", "ฆ่า Kurzen Commandoes 10 คน และ Kurzen Headshrinkers 6 คน\n\nรายงานต่อ Lieutenant Doren ที่ Rebel Camp" },
        description = { "378:1145617569:1600036185 N 111:1466668403:819595332", "เมื่อทหารทั่วไปของเขาลดจำนวนลงมากแล้ว เจ้าต้องเผชิญหน่วยที่ฝึกมาอย่างดี ยามไม่ได้ออกไปสังหารทหารกบฏของเราในป่า พวกมันอยู่ลึกเข้าไปด้านหลัง Kurzen Compound ในถ้ำที่เรียกว่า Stockpile\n\nข้ารู้จักทหารของ Kurzen หลายคนเป็นการส่วนตัว พวกเขาชำนาญ ภักดี และโหดเหี้ยม งานที่ข้ามอบให้เจ้าไม่ง่ายเลย {name}\n\nเมื่อเอาชนะได้แล้ว จงรายงานต่อ Lieutenant Doren ผู้บังคับบัญชาของข้า เขาต้องการฟังจากเจ้าโดยตรง" },
        progress = { "51:1825144605:1270969351 C 34:1939469140:1203045751", "Sergeant Yohwa บอกว่าเจ้ามีฝีมือและกล้าหาญ {class} มีอะไรมารายงานหรือ?" },
        completion = { "N 276:1594677486:1521651913", "{name} Sergeant Yohwa เชื่อในฝีมือเจ้า และข้าก็เชื่อใจนาง ชัยชนะที่เจ้ามีเหนือกองกำลัง Kurzen เกือบจะเกินกว่าที่เรากล้าหวัง ข้าเคยกลัวว่าฝ่ายกบฏจะโดดเดี่ยว และหากอยู่ลำพัง เราไม่มีวันต่อกรกับความปราดเปรื่องของผู้พันได้\n\nบางทีเราอาจยังมีความหวังรอดอยู่" },
        objectiveLabels = {
            monster = { ["Kurzen Commando slain"] = "ปราบ หน่วยจู่โจมของ Kurzen", ["Kurzen Headshrinker slain"] = "ปราบ หมอผีย่อหัวของ Kurzen" },
        },
    },
    [575] = { -- Supply and Demand
        title = { "17:590037515:417388636", "อุปสงค์และอุปทาน" },
        objective = { "61:871833966:1814729843", "นำ Large River Crocolisk Skins 2 ผืน ไปให้ Drizzlik ที่ Booty Bay" },
        description = { "495:1977642719:679826185", "“ช่างเครื่องหนังฝีมือดีที่สุดแห่งทะเลใต้ ทั้งโลกเก่าและโลกใหม่” นั่นคือคำที่คนเรียกข้า! ข้า Drizzlik! ช่างเครื่องหนังฝีมือดีที่...อะแฮ่ม เอาล่ะ\n\nเครื่องหนังของข้าขึ้นชื่อไปทั่วว่างดงามประณีตที่สุด เป็นตัวเลือกของผู้รู้จริง!\n\nข้าเพิ่งรับคำสั่งซื้อจาก Director Riddlevox แห่ง Tinkers' Union เขาต้องการรองเท้ารุ่น Excelsior ที่ชื่นชอบหนึ่งโหล ซึ่งเป็นรุ่นขายดีที่สุดของเรา\n\nเพื่อเริ่มขึ้นรูป ข้าต้องใช้หนังครอโคลิสก์จากพวกที่อยู่ริมแม่น้ำทางเหนือของ Stranglethorn" },
        progress = { "33:589711475:1822686564 N 178:1591976791:1396531815", "อุปกรณ์ข้าพร้อมหมดแล้ว {name} ขาดเพียงหนังพวกนั้น เราคงไม่อยากให้ Riddlevox รอแน่\n\nการปล่อยให้หัวหน้านักประดิษฐ์แห่ง Tinkers' Union ไม่พอใจไม่เป็นผลดีกับใคร" },
        completion = { "268:738155886:69797636", "หนังพวกนี้ใช้ได้ คุณภาพไม่สำคัญนักเพราะจะใช้เป็นชั้นในรองเท้า แต่ใส่สบายก็ยังสำคัญ\n\nถ้าแข็งไป ข้าจะใช้เลือดเสือทำให้นิ่ม เคล็ดวิชาช่างน่ะ เข้าใจไหม?" },
        required = { [4053] = { "26:527739382:692661390", "หนังครอโคลิสก์แม่น้ำขนาดใหญ่" } },
        steps = { { "26:527739382:692661390", "หนังครอโคลิสก์แม่น้ำขนาดใหญ่" } },
    },
    [576] = { -- Keep An Eye Out
        title = { "15:216393975:2064552064", "ช่วยหาดวงตา" },
        objective = { "87:760034060:561374385", "Dizzy One-Eye ที่ Booty Bay ต้องการให้เจ้าเอาดวงตาของเขาคืนจาก Bloodsail Buccaneers" },
        description = { "472:807127816:495891732", "หยุดก่อน! ใครน่ะ?\n\nอ๊าก หากไม่มีดวงตาลงมนตร์พิเศษ ข้าก็ไร้ประโยชน์ เสียดวงตาในสนามรบก็แย่พอแล้ว! แต่โชคดีตอนเทียบท่าที่ Menethil พ่อมดพเนจรลงมนตร์ให้ตาแก้วพิเศษจนข้ากลับมามองเห็น\n\nเมื่อคืน Bloodsail Buccaneers ดักรุมข้าระหว่างเดินออกมา แล้วเอาดวงตาไป! ดูเหมือนเจ้าพวกนั้นจะมาถึง Booty Bay แล้ว\n\nช่วยกะลาสีแก่คนนี้เอาดวงตาคืนหน่อยได้ไหม?" },
        progress = { "356:2113566473:157335410", "อาฮอย สหาย! แม้ข้ามองไม่เห็น แต่ได้กลิ่นเจ้าตั้งแต่ครึ่งท่าเรือแล้ว\n\nข้าต้องได้ดวงตาคืนจริง ๆ ถ้ากัปตันรู้ว่ามันอยู่ในมือ Bloodsail Buccaneers โสโครกพวกนั้น ข้าคงถูกลากลอดใต้ท้องเรือ\n\nยามเฝ้าระวังที่มองไม่เห็นจะมีประโยชน์อะไร? หอสังเกตการณ์บนเสากระโดงเคยเป็นบ้านข้า...ไร้ดวงตาแบบนี้ ได้ขัดท้องเรือก็บุญแล้ว" },
        completion = { "97:83232017:1931055497 N 24:754472231:1952818156", "ให้ฟ้าผ่าสิ! เจ้าเจอดวงตาแสนสวยของข้าแล้ว! ดูซิว่ายังใส่พอดีไหม\n\nอ้อ {name}! ให้ตายเถอะ ข้ามองเห็นแล้ว!!" },
        required = { [3897] = { "11:188397264:1699175811", "ดวงตาของ Dizzy" } },
        steps = { { "11:188397264:1699175811", "ดวงตาของ Dizzy" } },
    },
    [577] = { -- Some Assembly Required
        title = { "22:429804247:801416263", "ต้องประกอบอีกหน่อย" },
        objective = { "58:1971039323:1062954648", "นำ Snapjaw Crocolisks Skins 5 ผืน ไปให้ Drizzlik ที่ Booty Bay" },
        description = { "504:1238328379:700339737", "ข้าขึ้นรูปรองเท้าแล้ว กำลังไปได้สวย แต่หนังที่เจ้านำมายังไม่พอสำหรับชั้นใน\n\n“เราจะทำอย่างไร Drizzlik?” เจ้าคงอยากถามเช่นนี้ โชคดีที่เจ้าคุยกับ Drizzlik เพราะเขาจะบอกว่าเราจะทำอย่างไร!\n\nไม่มีใครเห็นชั้นในอยู่แล้ว เราจะเอาหนังหนาราคาถูกจากครอโคลิสก์แถว Lake Nazferiti มาเสริมให้รองเท้าเต็มทรง" },
        progress = { "232:567082789:129818545", "รองเท้าหนัง Excelsior ของ Drizzlik ฝีมือประณีตที่สุด ทำจากหนังครอโคลิสก์น้ำเค็มคุณภาพสูงร้อยเปอร์เซ็นต์ ไม่มีใครเหนือกว่า!\n\nคำบรรยายสวยหรูขนาดนี้ ไม่มีอะไรเทียบได้ใช่ไหม?\n\nเว้นแต่ว่า...เจ้ามีหนังที่ข้าต้องการมาให้?" },
        completion = { "35:398443304:15930322 N 240:989232539:1756363660", "รองเท้าข้าก็เหมือนไส้กรอก {name} ดูดี รสเยี่ยม ข้าบอกว่าใช้แต่วัตถุดิบกับเนื้อชั้นดี เจ้าก็กินและชื่นชอบ\n\nแค่เชื่อข้า แล้วอย่าถามละเอียดนักว่าข้างในมีอะไรจริง ๆ จะปลอดภัยและมีความสุขกว่า" },
        required = { [4104] = { "22:1375169410:1617287321", "หนังครอโคลิสก์ Snapjaw" } },
        steps = { { "22:1375169410:1617287321", "หนังครอโคลิสก์ Snapjaw" } },
    },
    [578] = { -- The Stone of the Tides
        title = { "22:276664033:376233119", "ศิลาแห่งกระแสน้ำ" },
        objective = { "56:818937993:2104738802", "ตามหาเกาะผีสิงให้ Baron Revilgaz ที่ Booty Bay" },
        description = { "455:1062058889:98400530", "หากมีจอมเวทก็อบลินกับธาตุน้ำหลอกหลอนเกาะนั้นจริง ก็หมายความว่า Stone of the Tides อาจตกเป็นของข้า!\n\nข้าอยากให้เจ้าหาเกาะผีสิง...ไปดูว่าเกิดอะไรขึ้น อ้อ หากอยากรู้เรื่องศิลาแห่งกระแสน้ำเพิ่ม นำใบนี้ไปห้องสมุด Stormwind พวกเขาน่าจะหาหนังสือที่ข้าอ่านพบตำนานครั้งแรกให้เจ้าได้\n\nหรือ Gazban จะพบศิลาจริง ๆ...?" },
        progress = { "57:205146091:81534574 N 136:1736742739:1148577140", "โทรลล์เคยครอบครองวัตถุเวทอันน่าทึ่งจริง ๆ {name} ตอนนี้ข้าอาจมีโอกาสเพิ่มอีกชิ้นในของสะสมอันมากมายของข้า เจ้าหาที่มาของข่าวลือได้ไหม?" },
        completion = { "231:244537948:1776016133", "เรื่องเล่าเป็นจริงสินะ! เหลือเชื่อ!\n\nแต่หากจะนำศิลาแห่งกระแสน้ำกลับมา เราต้องหาทางเอาชนะคำสาปก่อน คำสาปเป็นเรื่องเวทมนตร์ เราต้องให้พ่อมดสักคนช่วย" },
        objectiveLabels = {
            event = { ["Locate the haunted island"] = "ตามหาเกาะผีสิง" },
        },
    },
    [580] = { -- Whiskey Slim's Lost Grog
        title = { "24:207007721:1509898201", "เหล้าที่หายไปของ Whiskey Slim" },
        objective = { "91:449527406:1145942509", "Whiskey Slim ที่ Booty Bay ต้องการให้เจ้านำขวด Pupellyverbos Port ที่เขาทำหายกลับมาให้" },
        description = { "498:2029602350:1406657427", "เรากำลังดื่มกันอย่างหนักนอก Overlook Cliffs มองเห็น Hinterlands อยู่ไกล ๆ นึกว่าทะเลจะกลืนพวกเราทั้งลำแล้ว\n\nSlim รู้ดีเรื่องน้ำเปลี่ยนคนขลาดให้กล้า! กัปตันมี Pupellyverbos Port หนึ่งลัง เราปล้นมาจากเรือเอกชนติดอาวุธที่กำลังไป Stormwind\n\nพอพายุนอก Hinterlands ซัดมา ข้าก็งัดเหล้าออกดื่ม คลื่นใหญ่ซัดจนขวดกระเด็นตกทะเล ถ้าเจ้าไม่ช่วยเก็บคืน กัปตันต้องเฆี่ยนข้าแน่!" },
        progress = { "178:584885217:1222659995", "ให้ข้าจมน้ำตายเถอะ! เหล้าจะหมดแล้ว! กัปตันจะถอนสมอ และ Slim คนนี้จะแห้งผากเหมือนทะเลทราย Tanaris พอเขารู้ว่าไวน์พอร์ตหายไป...ตายแน่!" },
        completion = { "203:1148832530:193515260", "ให้ฟ้าผ่าสิ! เจ้าเจอเหล้าของกัปตันแล้ว!\n\nข้าเป็นหนี้เจ้าครั้งใหญ่ สหาย\n\nดูเหมือนข้างนอกพายุกำลังตั้งเค้า บางทีข้าคงดื่มสักขวดแก้หนาว ระหว่างรอให้มันผ่านไป..." },
        required = { [3900] = { "18:1270670467:145252900", "ไวน์พอร์ต Pupellyverbos" } },
        steps = { { "18:1270670467:145252900", "ไวน์พอร์ต Pupellyverbos" } },
    },
    [581] = { -- Hunt for Yenniku
        title = { "16:1578653394:537184987", "ตามหา Yenniku" },
        objective = { "62:1268802026:264114971", "นำ Bloodscalp Tusks 9 อัน ไปให้ Nimboya ที่ Grom'gol Base Camp" },
        description = { "490:633375467:1967171022", "มีเคราะห์ร้าย เคราะห์ร้ายตกแก่ Yenniku ลูกชายคนเล็กของหัวหน้าเผ่าข้า ตามธรรมเนียมชนเผ่า เรามอบเขาให้โทรลล์ Gurubashi แห่ง Zul'Gurub แต่เมื่อเผ่า Darkspear ของข้าออกเดินทางไปกับออร์ค Thrall เราก็ขาดการติดต่อกับ Yenniku ผู้น่าสงสาร ข้าถูกส่งมาจาก Orgrimmar อันไกลโพ้น กลับสู่ Stranglethorn เพื่อตามหาลูกชายหัวหน้าเผ่า\n\nและข้าเชื่อว่าเผ่า Bloodscalp จับเขาไว้\n\nหากเจ้าจะช่วย จงล่า Bloodscalp พวกมันอยู่ทางเหนือ เก็บงาแล้วนำกลับมาให้ข้า" },
        progress = { "C 76:485363891:617513525", "{class} แสดงให้ข้าเห็นว่าเจ้าล่าเผ่า Bloodscalp มาแล้ว\n\nเอาของที่ได้จากการล่ามาให้ข้าดู" },
        completion = { "22:953926436:122177836 N 120:331192113:511688893", "งาพวกนี้ดีมาก {name} เจ้าพิสูจน์ว่ามีกำลังล่า Bloodscalp ได้\n\nดีแล้ว เพราะเจ้ายังต้องล่าพวกมันต่อ" },
        required = { [3901] = { "15:1560483938:906245210", "งาของเผ่า Bloodscalp" } },
        steps = { { "15:1560483938:906245210", "งาของเผ่า Bloodscalp" } },
    },
    [582] = { -- Headhunting
        title = { "11:2030851085:1441739159", "ล่าหัว" },
        objective = { "61:115661754:1981066925", "นำ Shrunken Heads 20 หัว ไปให้ Nimboya ที่ Grom'gol Base Camp" },
        description = { "333:315518135:883916843 N 101:861165607:1171263141", "เราต้องรู้ว่า Yenniku ตายแล้วหรือยัง\n\nฆ่า Bloodscalp Headhunters แล้วเก็บ Shrunken Heads จากพวกมันมา ต้องเก็บมามาก ๆ ข้าจะตรวจให้แน่ใจว่าไม่มีหัว Yenniku ปะปนอยู่\n\nหาก Bloodscalp ฆ่า Yenniku ขอให้วิญญาณหัวหน้าเผ่าของมัน Gan'zulah ต้องคำสาปนาน 600 ปี!\n\nไปเถิด {name} เจ้าจะพบพวกล่าหัวมากมายที่ซาก Zuuldaia และ Zul'Kunda ตามชายฝั่งทางเหนือ" },
        progress = { "N 83:1615980770:1543068179", "{name} ข้าเป็นห่วงลูกชายหัวหน้าเผ่า เจ้าหาหัวหดมาให้ข้าตรวจหรือยัง?" },
        completion = { "11:1191658970:1224418299 N 84:1871190761:1631182359", "ขอบคุณ {name} ข้าจะตรวจหัวเหล่านี้ให้แน่ใจว่า Yenniku ผู้น่าสงสารรอดจากขวานนักล่าหัว" },
        required = { [1532] = { "13:223305118:334443317", "ศีรษะย่อส่วน" } },
        steps = { { "13:223305118:334443317", "ศีรษะย่อส่วน" } },
    },
    [583] = { -- Welcome to the Jungle
        title = { "21:418030412:1082770279", "ยินดีต้อนรับสู่ป่า" },
        objective = { "27:1308887761:1606009444", "คุยกับ Hemet Nesingwary", variants = { { "28:1376705691:2081325197", "คุยกับ Hemet Nesingwary" } } },
        description = { "303:596226199:1493614527 C 165:873454778:455972689", "ยินดีต้อนรับสู่ Stranglethorn!\n\nเจ้าอาจยังไม่รู้ คนแคระตรงนั้นคือ Hemet Nesingwary ตัวจริง วีรบุรุษสงครามชื่อก้องแห่ง Alliance และยอดนักล่าสัตว์ใหญ่ ปกติเขาไม่ชอบต้อนรับคนแปลกหน้าเข้าค่าย แต่เจ้าดูผ่านการต่อสู้มามาก {class}\n\nอาจารย์ Nesingwary เองผ่านศึกมานับไม่ถ้วน จึงเอ็นดูวีรบุรุษด้วยกัน\n\nไปคุยกับเขาสิ บางทีเขาอาจสอนเคล็ดลับการล่าให้" },
        completion = { "38:1400805381:804624650 N 17:134697848:1565611041 C 436:481219263:2062684729", "ยินดีอย่างยิ่งที่รู้จักเจ้า {name} ไม่เห็น {class} แถวนี้มาพักใหญ่แล้ว\n\nข้ามาร่วมคณะสำรวจด้วยจุดหมายเดียว คือล่าสัตว์ร้ายยิ่งใหญ่ที่พบตัวยาก เห็นว่าเจ้าก็เป็นวีรบุรุษคนหนึ่ง ข้ายินดีให้ร่วมล่า แต่เจ้าต้องพิสูจน์ตัวเองก่อน\n\nข้าจะสอนวิธีฆ่าแรปเตอร์ Ajeck จะสอนล่าเสือ ส่วน Sir Erlgadin เป็นยอดนักสะกดรอยเสือดำ\n\nพิสูจน์ฝีมือแล้วข้าจะให้เจ้าร่วมการล่าครั้งใหญ่" },
    },
    [584] = { -- Bloodscalp Clan Heads
        title = { "21:1154869778:453206205", "หัวของผู้นำ Bloodscalp" },
        objective = { "94:149922208:219892520", "นำ Gan'zulah's Head และ Nezzliok's Head ไปใส่หม้อต้มเดือดที่ Grom'gol Base Camp" },
        description = { "494:188960862:221685113", "ไม่มีหัว Yenniku อยู่ในนั้น ขอบคุณมหาอสรพิษ แต่เรายังไม่ได้เข้าใกล้การพบเขาเลย\n\nเราต้องรู้ความจริง และข้ากลัวว่ามีเพียงหัวหน้า Bloodscalp กับหมอผีของเขาที่รู้ ทั้งคู่เป็นศัตรูของ Darkspear ไม่ยอมพูดง่าย ๆ เราจึงต้องเค้นความจริงจากปากคนตาย!\n\nนำหัว Gan'zulah กับ Nezzliok the Dire มาใส่หม้อนี้\n\nทั้งคู่อยู่ลึกใน Zul'Kunda เอาหัวมา...แล้วเราจะทำให้มันพูด" },
        progress = { "47:1925915486:1700671217", "น้ำสีเขียวในหม้อกำลังเดือดปุด ๆ" },
        completion = { "68:1540147144:1996633673", "เจ้าวางหัวของ Gan'zulah และ Nezzliok ลงในหม้อ..." },
        required = { [3904] = { "16:334240687:949652924", "ศีรษะของ Gan'zulah" }, [3905] = { "15:63378020:1505179604", "ศีรษะของ Nezzliok" } },
        steps = { { "16:334240687:949652924", "ศีรษะของ Gan'zulah" }, { "15:63378020:1505179604", "ศีรษะของ Nezzliok" } },
    },
    [585] = { -- Speaking with Nezzliok
        title = { "22:1631929518:1118340394", "สนทนากับ Nezzliok" },
        objective = { "119:237655324:524562483", "นำ Balia'mah Trophy, Ziata'jai Trophy และ Zul'Mamwe Trophy ไปใส่ Bubbling Cauldron ที่ Grom'gol Base Camp" },
        description = { "483:1590583229:1995791214", "<หัวของ Nezzliok พูดขึ้น>\n\nจริง ข้ารู้ว่าเด็ก Darkspear ถูกพาไปที่ใด เจ้าชนะและพันธนาการวิญญาณข้าได้ แต่ข้าจะไม่พูดจนกว่าเจ้าจะเอาใจข้า!\n\nBloodscalp ทำสงครามกับ Skullsplitter หากอยากให้ข้าพอใจ จงขโมยกะโหลกรางวัลของ Skullsplitter มา 3 หัว ใส่ไว้กับพวกเราที่นี่ เพื่อให้วิญญาณข้ามีทาสใน Nether หัวหนึ่งต้องมาจากกองรางวัลที่ Balia'mah อีกหัวจาก Ziata'jai และหัวสุดท้ายจาก Zul'Mamwe" },
        progress = { "21:709161475:885272624", "ข้ารอกะโหลกอยู่..." },
        completion = { "131:1721837772:2147198885 R 32:1662138956:1574096188", "ใช่ พวกนี้จะรับใช้ข้าได้ดี เมื่อวิญญาณข้าเป็นอิสระ ข้าจะเข้าสู่ Nether พร้อมคนรับใช้ชั้นดีสามคน!\n\nเจ้าสร้างชื่อให้เผ่า {race} และทำให้ข้าพอใจแล้ว" },
        required = { [3906] = { "16:259843468:1292331823", "กะโหลกที่ยึดจาก Balia'mah" }, [3907] = { "16:38100638:211788134", "กะโหลกที่ยึดจาก Ziata'jai" }, [3908] = { "16:584216806:282635466", "กะโหลกที่ยึดจาก Zul'Mamwe" } },
        steps = { { "16:259843468:1292331823", "กะโหลกที่ยึดจาก Balia'mah" }, { "16:38100638:211788134", "กะโหลกที่ยึดจาก Ziata'jai" }, { "16:584216806:282635466", "กะโหลกที่ยึดจาก Zul'Mamwe" } },
    },
    [586] = { -- Speaking with Gan'zulah
        title = { "23:706088157:1084962635", "สนทนากับ Gan'zulah" },
        objective = { "177:1999104977:117688410", "ฆ่า Skullsplitter Hunters 8 คน, Skullsplitter Headhunters 6 คน และ Skullsplitter Berserkers 4 คน\n\nนำ Broken Armor of Ana'thek ไปใส่ Bubbling Cauldron ที่ Grom'gol Base Camp" },
        description = { "448:1768567604:635318834", "<หัวของ Gan'zulah พูดขึ้น>\n\nขอสาปแช่งเจ้า! และบรรพบุรุษเจ้าด้วย!!\n\nมีเพียงเลือดกับการแก้แค้นที่ดับโทสะข้าได้ หากเจ้าต้องการเช่นนั้น...จงทำดังนี้\n\nบุกใจกลางพวก Skullsplitter ทางตะวันออก ฆ่านักรบดุร้ายที่สุดของมัน หากรอด...ก็ไปตายด้วยมือหัวหน้าของมัน Ana'thek the Cruel ฮ่า! เอาเกราะที่แตกพังของมันมาให้ข้าหากทำได้!\n\nขอให้มันฉีกแขนขาเจ้า ทิ้งให้เน่าเปื่อยเป็นอาหารสัตว์กินซาก" },
        progress = { "110:1828476051:125705493", "แม้เนื้อข้าจะเดือดหลุดจากกะโหลก ข้าก็ยังได้กลิ่นความกลัวของเจ้า\n\nฮ่า! เจ้าไม่มีวันทำงานข้าสำเร็จ..." },
        completion = { "159:301454108:692501761 N 97:138806012:233375555", "ข้าไม่อยากเชื่อ แต่ปฏิเสธสิ่งที่เจ้าทำไม่ได้ เมื่อ Ana'thek พ่ายแพ้ โทสะข้าก็เบาลง\n\nพลังเจ้าจะนำไปสู่ผลงานยิ่งใหญ่ {name} แต่สักวัน...ข้าจะพบเจ้าใน Nether และเราจะประลองกำลังกันอีก\n\nข้าจะรอ" },
        required = { [3909] = { "24:133644129:1037048705", "เกราะที่แตกหักของ Ana'thek" } },
        steps = { { "24:133644129:1037048705", "เกราะที่แตกหักของ Ana'thek" } },
        objectiveLabels = {
            monster = { ["Skullsplitter Hunter slain"] = "ปราบ นักล่า Skullsplitter", ["Skullsplitter Headhunter slain"] = "ปราบ นักล่าหัว Skullsplitter", ["Skullsplitter Berserker slain"] = "ปราบ นักรบคลั่ง Skullsplitter" },
        },
    },
    [587] = { -- Up to Snuff
        title = { "11:1325675910:534489541", "ยานัตถุ์ชั้นดี" },
        objective = { "60:528092554:1839072851", "Deeg ที่ Booty Bay ต้องการ Snuff 15 ส่วน" },
        description = { "422:110301010:454719884 C 52:1810985916:504302770", "อา ชีวิตชาวทะเล ข้าไม่บอกหรอกว่าเป็นชีวิตที่ดี แต่มันคือชีวิตข้า\n\nเวลาเข้าท่า ข้าชอบหาเหล้าดี ๆ กับยานัตถุ์ชั้นเลิศ นิสัยไม่ดีนัก แต่โจรสลัดไม่มีอบายมุขจะเป็นโจรสลัดได้อย่างไร ว่าไหม?\n\nเจ้าคงนึกออกว่าข้าใจสลายเพียงใดเมื่อรู้ว่าร้านสมุนไพรในเมืองขายหมดแล้ว เขาบอกว่าสินค้าถูก Bloodsail Raiders บัดซบปล้นไป\n\nข้าพนันว่า {class} ผู้ไม่รู้กลัวเช่นเจ้า น่าจะเกลี้ยกล่อมให้พวกมันแบ่งของได้ ใช่ไหม?" },
        progress = { "34:58274940:437360393", "หาของได้บ้างไหม สหาย?" },
        completion = { "11:1305456786:1698347065 N 77:485478877:752950627", "เยี่ยมมาก {name}! ทันก่อนข้าต้องออกเรือพอดี! ขอบคุณเท่าไรก็ไม่พอ สหายเก่า" },
        required = { [3910] = { "5:1035266219:1070484835", "ยานัตถุ์" } },
        steps = { { "5:1035266219:1070484835", "ยานัตถุ์" } },
    },
    [588] = { -- The Fate of Yenniku
        title = { "19:1165070086:502962627", "ชะตากรรมของ Yenniku" },
        objective = { "22:348488985:1242743318", "คุยกับ Kin'weelay" },
        description = { "320:1042646736:1333190341 C 91:1275429054:1825361507", "<Nezzliok พูดขึ้น>\n\nเจ้าทำให้ข้าและหัวหน้าเผ่าพอใจแล้ว ข้าจะบอกสิ่งที่เจ้าอยากรู้...\n\nหนุ่มน้อย Yenniku สูญหายจากเผ่าไปแล้ว\n\nหมอผี Zanzil the Outcast พาตัวเขาไป บัดนี้ Zanzil ควบคุมทั้งร่างกายและวิญญาณเขา มีเพียงเวทมนตร์ทรงพลังที่สุดเท่านั้นที่ปลดปล่อยเขาได้\n\nเวทมนตร์ที่เจ้าไม่มี {class}\n\nบางทีพันธมิตร Darkspear ของเจ้าอาจให้ความหวังช่วย Yenniku ได้ แต่ข้าไม่คิดเช่นนั้น" },
        completion = { "194:1593689289:1642348418", "Zanzil the Outcast หรือ??\n\nหาก Yenniku อยู่ในมือโทรลล์หมอผีชั่วร้ายและทรงพลังตนนั้น ข้าเกรงว่าเรามีหวังเหลือเพียงริบหรี่ เล็กน้อย เล็กเท่าแมลงตัวจิ๋วที่สุด\n\nแต่ก็ยังเป็นความหวัง" },
    },
    [589] = { -- The Singing Crystals
        title = { "20:1584523337:179193454", "ผลึกขับขาน" },
        objective = { "68:1870159627:288399626", "นำ Pulsing Blue Shards 3 ชิ้น ไปให้ Kin'weelay ที่ Grom'gol Base Camp" },
        description = { "494:1464164237:2138344239", "ตำนานเล่าถึงอัญมณีที่ซ่อนลึกในใจกลาง Stranglethorn เราเรียกมันว่า Mind's Eye มันทรงพลังยิ่ง หากเจ้าได้มา บางทีเราอาจใช้พา Yenniku กลับจากความมืดได้\n\nข้าจะปรึกษาวิญญาณแห่งป่าเพื่อหาศิลา ระหว่างนั้นเจ้าเข้า Crystalvein Mine ทางตะวันออกเฉียงใต้จากที่นี่ เก็บ Pulsing Blue Shards จาก Ironjaw Basilisks เศษผลึกหายาก แต่เราต้องใช้พลังมันบังคับ Mind's Eye ให้เป็นไปตามเจตนาเรา" },
        progress = { "24:545650323:664484974 N 68:872320201:2064117959", "เจ้ามีเศษผลึกหรือยัง {name}? ต้องใช้ในพิธีสุดท้าย หลังจากเราได้ Mind's Eye มาแล้ว" },
        completion = { "20:1921578502:569519135 N 187:2125436933:581187651", "ทำได้ดี {name} เศษผลึกเหล่านี้สมบูรณ์มาก ข้าได้ยินมันขับขานแล้ว\n\nระหว่างเจ้าไม่อยู่ ข้าคุยกับวิญญาณแห่งป่า ข้ารู้ว่า Mind's Eye อยู่ที่ใด...\n\n...และใครเฝ้ามันอยู่" },
        required = { [3911] = { "18:1355547889:568584510", "เศษผลึกสีน้ำเงินที่สั่นเป็นจังหวะ" } },
        steps = { { "18:1355547889:568584510", "เศษผลึกสีน้ำเงินที่สั่นเป็นจังหวะ" } },
    },
    [591] = { -- The Mind's Eye
        title = { "14:656962226:1950441213", "เนตรแห่งจิต" },
        objective = { "61:825319189:30106932", "นำ Mind's Eye ไปให้ Kin'weelay ที่ Grom'gol Base Camp" },
        description = { "417:129356606:1968256241", "จอมเวทออกร์ครอบครอง Mind's Eye อยู่ทางตะวันออกจากที่นี่ ลึกในเนินออกร์ Mosh'Ogg มันชื่อ Mai'Zoth ข้ารู้จักตั้งแต่ Darkspear ยังอยู่ Stranglethorn มันโหดเหี้ยมและเวทแข็งแกร่ง\n\nหากมี Mind's Eye พลังมันก็ยิ่งกล้าแข็ง\n\nเจ้าต้องเผชิญ Mai'Zoth แล้วชิงศิลามา งานอันตรายยิ่ง แต่เป็นความหวังเดียวในการช่วย Yenniku" },
        progress = { "11:927657569:725753248 N 121:835468357:1389642475", "สวัสดี {name} เหล่าวิญญาณสรรเสริญความกล้าเจ้า แต่ไม่เล่าเรื่องการเผชิญ Mai'Zoth ให้ข้าฟังเลย\n\nเจ้าได้ศิลามาหรือยัง?" },
        completion = { "59:915946006:1228700988 N 385:2015860454:1750922904", "เจ้าเอาศิลามาได้! พลังเจ้าคู่ควรกับตำนาน {name}!\n\nเมื่อได้ศิลา เจ้าคงเอาชนะ Mai'Zoth ส่งมันสู่ Nether แล้ว นั่นจึงเป็นเหตุที่เหล่าวิญญาณไม่กล่าวถึงมันก่อนหน้านี้\n\nดีแล้วที่มันจากโลกแห่งเลือดเนื้อและกระดูกไป แต่ตอนนี้มันอยู่แดนวิญญาณ...ข้ากลัวว่ามันจะเริ่มปกครองที่นั่นแทน\n\nเอาไว้กังวลวันหลัง ตอนนี้ข้าต้องทำพิธีควบคุม Mind's Eye ให้ตรงกับที่เราต้องการ..." },
        required = { [3616] = { "10:385680669:813601013", "ดวงตาแห่งจิต" } },
        steps = { { "10:385680669:813601013", "ดวงตาแห่งจิต" } },
    },
    [592] = { -- Saving Yenniku
        title = { "14:408554559:1576376701", "ช่วยเหลือ Yenniku" },
        objective = { "37:613907607:662469009", "นำ Filled Soul Gem ไปให้ Nimboya" },
        description = { "322:72375512:2139294629", "ข้าเปลี่ยน Mind's Eye เป็น Soul Gem แล้ว มันมีหน้าที่สองอย่าง เจ้าต้องใช้ทำให้ Yenniku มึนงง จากนั้นวางบนศีรษะเขาเพื่อกักวิญญาณ\n\nแล้วนำอัญมณีไปให้ Nimboya\n\nYenniku อยู่กับ Zanzil the Outcast ที่ Ruins of Aboraz ริม Crystal Shore บนแหลม Stranglethorn อันห่างไกล" },
        progress = { "N 81:977837568:1506491748", "{name} Kin'weelay บอกว่าเจ้าออกไปจับ Yenniku\n\nจริงหรือ? เจ้าได้ตัวเขามาหรือยัง?" },
        completion = { "161:1707303025:1488975330 N 67:1777803523:1762000925", "เจ้าทำได้! เจ้าปลดปล่อย Yenniku จากอำนาจ Zanzil และทำภารกิจที่ข้าเคยคิดว่าสิ้นหวังสำเร็จ\n\nเผ่าเราจะจดจำชื่อเจ้าในบทเพลง {name} และสลักเรื่องราวลงหินให้อยู่ตลอดกาล" },
        required = { [3913] = { "15:1500284132:1760344132", "อัญมณีวิญญาณที่เติมพลังแล้ว" } },
        steps = { { "15:1500284132:1760344132", "อัญมณีวิญญาณที่เติมพลังแล้ว" } },
    },
    [593] = { -- Filling the Soul Gem
        title = { "20:359713486:1425052013", "เติมอัญมณีวิญญาณ" },
        progress = { "63:363787500:523342504", "Yenniku ยืนมึนงงอยู่ต่อหน้าเจ้า จิตใจของเขาอยู่ที่อื่น..." },
        completion = { "122:2066067802:1754532868", "เจ้าวาง Soul Gem บนหน้าผากเขา เขาสั่นสะท้านขณะวิญญาณถูกดูดเข้าไป เหลือร่างไร้จิตใจไว้เบื้องหลัง" },
        description = { "63:363787500:523342504", "Yenniku ยืนมึนงงอยู่ต่อหน้าเจ้า จิตใจของเขาอยู่ที่อื่น..." },
        required = { [3912] = { "8:664212272:206678483", "อัญมณีวิญญาณ" } },
        objectiveLabels = {
            item = { ["Soul Gem"] = "อัญมณีวิญญาณ" },
        },
    },
    [594] = { -- Message in a Bottle
        title = { "19:1721482880:1635361150", "สารในขวด" },
        objective = { "43:1218359449:56817079", "ตามหาผู้เขียนสารในขวด" },
        description = { "405:227230368:1919132", "ข้อความเขียนด้วยลายมือค่อนข้างสวยว่า\n\nถึงผู้ที่ช่วยข้าได้\n\nได้โปรด ข้าต้องการความช่วยเหลืออย่างเร่งด่วน Skymane ตัวมหึมาจับข้าไว้บนเกาะในทะเลใต้\n\nดาวยามค่ำคืนไม่คุ้นตาและถูกต้นไม้ในป่าบดบัง แต่ในวันที่ฟ้าใสที่สุด ข้ามองเห็น Wild Shore ทางตะวันตกเฉียงเหนือ และสิ่งที่ดูเหมือนเรือใบใหญ่ทางตะวันตกเฉียงใต้\n\nข้าวิงวอนผู้ที่จะมาช่วยชีวิต ได้โปรดช่วยข้าด้วย" },
        completion = { "25:2134512085:796381138", "เจ้ามาปลดปล่อยข้าหรือ?" },
    },
    [595] = { -- The Bloodsail Buccaneers
        title = { "24:1118361646:1575445526", "โจรสลัด Bloodsail" },
        objective = { "64:993178587:2001891318", "First Mate Crazz ต้องการให้เจ้าตรวจอ่าวเล็กทางเหนือของ Booty Bay" },
        description = { "66:1445284742:1397828707 R 1:32:32 C 421:1736348520:158351164", "เจ้าดูกระตือรือร้นจะทำงานจริง สหาย ไม่รู้ทำไม {class} ชาว{race} ผู้รักแผ่นดินถึงอาสาช่วย Blackwater Raiders แต่ข้าไม่ปฏิเสธหรอก\n\nเรือเราเพิ่งเทียบท่าที่ Booty Bay มีข่าวว่าพบคู่แข่งของเรา พวก Bloodsail Buccaneers โสโครกบัดซบทั่ว Stranglethorn ตอนใต้\n\nพวกลูกเรือมัวแต่ดื่มเหล้าหาสาว! ข้าต้องการคนสอดแนม\n\nตรวจอ่าวเล็กทางเหนือ Booty Bay ตามแนว Savage Coast แล้วดูว่าพบอะไร" },
        completion = { "100:2015699763:766157760", "บนถังไม้ เจ้าพบแผนที่ที่มีข้อความเขียนอย่างเร่งรีบ พร้อมเหรียญจำนวนหนึ่ง" },
    },
    [596] = { -- Bloody Bone Necklaces
        title = { "21:110912215:1431950590", "สร้อยกระดูกเปื้อนเลือด" },
        objective = { "71:1609819076:722017423", "นำ Bloody Bone Necklaces 25 เส้น ไปให้ Kin'weelay ที่ Grom'gol Base Camp" },
        description = { "385:663214135:1760366653", "ข้าถูกส่งมา Grom'gol เพื่อช่วยภารกิจ Nimboya แต่...ข้าก็มีเหตุผลของตนที่มาที่นี่\n\nBloodscalp เป็นศัตรูของเผ่าเรา การเก็บของจากศัตรูเป็นเครื่องหมายชัยชนะทำให้เรามีอำนาจเหนือพวกมัน เจ้าช่วยเผ่าเราได้ด้วยการล่าศัตรู\n\nพวกมันอยู่ทางเหนือ ฆ่าโทรลล์ Bloodscalp แล้วเอาสร้อยกระดูกเปื้อนเลือดมา เก็บให้มาก แล้วรางวัลเจ้าจะงามนัก" },
        progress = { "103:1833104945:1009189001", "วันหนึ่ง Darkspear จะบดขยี้ Bloodscalp! เจ้ามีสร้อยของศัตรูที่ชะตาขาดแล้วหรือยัง?" },
        completion = { "138:153844568:1142212170 N 33:1130371473:1712583764", "อา ดีมาก ข้าจะต้มและสกัดพลังจากมัน ขณะเคี่ยวสร้อยจนเละ วิญญาณเจ้าของมันก็จะอ่อนแอลง!\n\nนี่ {name} ถือว่าชดใช้บุญคุณเจ้า" },
        required = { [3915] = { "20:393162037:1551873371", "สร้อยกระดูกเปื้อนเลือด" } },
        steps = { { "20:393162037:1551873371", "สร้อยกระดูกเปื้อนเลือด" } },
    },
    [597] = { -- The Bloodsail Buccaneers
        title = { "24:1118361646:1575445526", "โจรสลัด Bloodsail" },
        objective = { "54:1584468411:251231803", "รายงานสิ่งที่พบต่อ First Mate Crazz ที่ Booty Bay" },
        description = { "289:876007081:867944724", "แผนที่แสดง Booty Bay พร้อมกากบาทสีแดงตรงจุดที่เจ้ายืนอยู่พอดี\n\nข้อความลวก ๆ เขียนว่า\n\n“พวกเจ้าจงตั้งค่ายให้มั่นที่ตำแหน่งนี้และอย่าส่งเสียง รอสัญญาณจากฐานบัญชาการทางใต้ก่อนโจมตี หากมีใครเข้ามาใกล้ จงฆ่าทิ้ง”" },
        completion = { "22:482627319:1179826602 C 30:1184226853:1135873681", "แน่นอน ข้าจำเจ้าได้ {class} กลับจากสอดแนมแล้วสินะ..." },
    },
    [598] = { -- Split Bone Necklace
        title = { "19:90544795:1033853739", "สร้อยกระดูกแยก" },
        objective = { "70:1442451317:957537807", "นำ Split Bone Necklaces 25 เส้น ไปให้ Kin'weelay ที่ Grom'gol Base Camp" },
        description = { "423:1531083748:89560978", "เมื่อเจ้าเก็บของจาก Bloodscalp มาแล้ว ข้ามีงานอีกอย่าง โทรลล์เผ่า Skullsplitter อยู่ทางตะวันออกเฉียงใต้ เราทำสงครามกับพวกมันมาหลายปี แม้ Darkspear ไม่ได้อยู่ Stranglethorn แล้ว เราก็ยังผูกพันกับสงครามนี้\n\nจงล่าพวกมัน เก็บ Split Bone Necklaces แล้วกลับมาหาข้า ช่วยเราในสงคราม แล้วเจ้าจะได้มิตรภาพจาก Darkspear" },
        progress = { "84:1850672739:1452387008", "Skullsplitter จะสาปแช่งวันที่มันลากเราเข้าสงคราม! เจ้าทำงานเสร็จหรือยัง?" },
        completion = { "55:981588593:653928777 N 113:150120203:2109588347", "เจ้าแข็งแกร่งมากจึงได้สร้อยเหล่านี้มา {name} Skullsplitter ล้มต่อหน้าเจ้าเหมือนต้นกล้าที่ถูกบาซิลิสก์เหยียบจมดิน!\n\nการกระทำเจ้าช่วยเราอย่างยิ่ง" },
        required = { [3916] = { "19:90544795:1033853739", "สร้อยกระดูกผ่าซีก" } },
        steps = { { "19:90544795:1033853739", "สร้อยกระดูกผ่าซีก" } },
    },
    [599] = { -- The Bloodsail Buccaneers
        title = { "24:1118361646:1575445526", "โจรสลัด Bloodsail" },
        objective = { "60:597771903:775884094", "รายงานแผนโจมตีของ Bloodsail ต่อ Fleet Master Seahorn" },
        description = { "323:1507522933:1689417197", "ให้ฟ้าผ่าสิ! Bloodsail Buccaneers วางแผนโจมตี Booty Bay หรือ? เจ้าพวกวายร้ายกล้าดีนัก Booty Bay จะอยู่ใต้การปกครอง Blackwater Raiders ตลอดไป!\n\nเรื่องนี้ใหญ่กว่าที่คิด รีบนำสิ่งที่รู้ไปรายงาน Fleet Master Seahorn ทันที! กะลาสีแก่คนนั้นอยู่ที่ไหนสักแห่งในเมือง..." },
        completion = { "238:647380981:2081070432", "Bloodsail Buccaneers จะโจมตี Booty Bay หรือ? กระโดดจาก Overlook Cliffs ไปเลยยังดีกว่า อย่างไรก็ตาม ข่าวที่เจ้านำมาช่วยกองเรือนักดาบของข้าอย่างยิ่ง Blackwater Raiders ขอบคุณเจ้า" },
    },
    [600] = { -- Venture Company Mining
        title = { "22:625372538:832235462", "เหมืองของ Venture Company" },
        objective = { "63:1306479198:1105896761", "นำ Singing Blue Crystals 10 ชิ้น ไปให้ Crank Fizzlebub ที่ Booty Bay" },
        description = { "500:1751262288:672912534", "Venture Company มีกิจการกระจายทั่ว Stranglethorn ทำให้ก็อบลินขยันอย่างข้าหากินสุจริตไม่ได้! ได้โปรด เจ้าต้องช่วยข้า!\n\nพวกมันทำเหมืองใกล้ Crystalvein Mine ทางเหนือ เข้าเหมืองไม่ได้เพราะบาซิลิสก์เต็มไปหมด แต่ยังขุด Singing Crystals จากเนินรอบ ๆ ได้\n\nชิงผลึกมา แสดงให้มันรู้ว่าป่านี้ไม่ใช่ที่ให้ทำตามใจ\n\nแล้ว...เอ่อ...นำผลึกมาให้ข้าเป็นหลักฐานด้วย!" },
        progress = { "183:1595600738:1259010094", "ได้ผลึกมาหรือยัง?? ข้าต้องการมัน!!\n\nหมายถึง...ข้าต้องรู้ว่า Venture Company ชั่วร้ายกำลังเสียหลักใน Stranglethorn เพราะเจ้าก็รู้ คนสุจริตอย่างเราต้องทำมาหากิน!" },
        completion = { "190:431189381:1792396542 N 35:583558747:1902045782", "เยี่ยม! วิเศษ! พวกนี้ขายได้กำไรอื้อแน่!!\n\nVenture Company เลือกป่าทำเหมืองผิดแห่งแล้ว ว่าไหม? ถ้ามันย้ายออก เราทุกคนคงอยู่ดีกว่านี้\n\nขอบคุณ {name} วันนี้เจ้าทำความดีแล้ว" },
        required = { [3917] = { "20:782222891:1453802250", "ผลึกสีฟ้าที่ขับขาน" } },
        steps = { { "20:782222891:1453802250", "ผลึกสีฟ้าที่ขับขาน" } },
    },
    [601] = { -- Water Elementals
        title = { "16:121660810:1805395514", "ธาตุน้ำ" },
        objective = { "66:1463990723:1404870425", "หา Water Elemental Bracers 6 อัน ให้ Baron Revilgaz ที่ Booty Bay" },
        description = { "445:634681059:1673273647", "ธาตุน้ำคงถูก Gazban เรียกมา ก็อบลินพ่อมดที่ลือกันว่าพบ Stone of the Tides อย่างที่เจ้าอาจรู้ ศิลาสาปผู้ถือครองให้เลือนหายสลับกับปรากฏตัว...\n\nบางทีเราอาจแก้คำสาปได้ ให้จอมเวท Dalaran วิเคราะห์เศษเวทที่ตกค้างบนปลอกแขนธาตุน้ำ ข้าต้องการให้เจ้ากลับเกาะไปนำตัวอย่างมาสักสองสามชิ้น" },
        progress = { "23:249293929:971440504 N 1:63:63", "ได้ผลบ้างไหม {name}?" },
        completion = { "416:606459563:1253266928", "อืม ข้าไม่ชำนาญพอจะดูว่าปลอกแขนไหนใช้ได้ แต่มั่นใจว่าต้องมีประโยชน์อย่างน้อยชิ้นหนึ่ง นำไป Dalaran ให้จอมเวทตรวจดู\n\nข้าจะทิ้ง Booty Bay เพียงเพื่อไปคุยกับพ่อมดแก่น่าเบื่อพวกนั้นไม่ได้\n\nไม่ใช่ว่าข้ากลัวใครแย่งเป็นบารอนคนใหม่หรอก ไม่มีใครขัดขา Revilgaz แล้วรอดไปเล่าได้" },
        required = { [3923] = { "23:831582132:714330477", "ปลอกรัดแขนของธาตุน้ำ" } },
        steps = { { "23:831582132:714330477", "ปลอกรัดแขนของธาตุน้ำ" } },
    },
    [602] = { -- Magical Analysis
        title = { "16:763309759:1837024101", "วิเคราะห์เวทมนตร์" },
        objective = { "76:818804566:1039681398", "นำปลอกแขนธาตุน้ำไปให้ Archmage Ansirem Runeweaver ที่ Dalaran" },
        description = { "467:2088236852:1188633043", "ได้ยินว่าจอมเวท Dalaran ยุ่งกับการสร้างเมืองที่ถูกทำลายขึ้นใหม่ แต่เจ้าคงหาคนสละเวลาตรวจปลอกแขนได้ หากข้ารู้จักพวกจอมเวทดี พวกเขาทนปริศนาเวทมนตร์ไม่ได้แน่\n\nนำถุงปลอกแขนธาตุน้ำไปดูว่าเขาจะไขคำสาปศิลาได้ไหม มองหา Archmage Ansirem Runeweaver โดยเฉพาะ ข้าเคยติดต่อเขา ความรู้เขากว้างขวางมาก" },
        progress = { "49:487038633:371293191", "หากไม่รังเกียจ ตอนนี้ข้าค่อนข้างยุ่ง" },
        completion = { "311:240887960:1024733622", "ศิลาแห่งกระแสน้ำหรือ? น่าสนใจยิ่ง เจ้าอาจประหลาดใจที่รู้ว่าเมื่อหลายปีก่อน ข้าเขียนตำราเกี่ยวกับตำนานจักรวรรดิ Gurubashi ข้ารู้เรื่องศิลานี้ไม่น้อย\n\nปลอกแขนอย่างน้อยหนึ่งชิ้นดูมีเศษเวทตกค้างให้วิเคราะห์ได้\n\nมาดูกันว่าข้าจะพบอะไร..." },
        required = { [3960] = { "30:1253085334:1608694362", "ถุงบรรจุปลอกรัดแขนของธาตุน้ำ" } },
        steps = { { "30:1253085334:1608694362", "ถุงบรรจุปลอกรัดแขนของธาตุน้ำ" } },
    },
    [603] = { -- Ansirem's Key
        title = { "13:292311892:539650879", "กุญแจของ Ansirem" },
        objective = { "29:111942285:846617792", "คุยกับ Catelyn ที่ Booty Bay" },
        description = { "441:170186483:828393281", "จอมเวทที่ถือศิลากำลังขยายพลังมันผ่านจุดรวมพลัง...แท่นบูชาบางชนิด เจ้าคงขัดขวางได้ด้วยพลังที่มากกว่า\n\nบังเอิญข้ารู้จักของที่ใช้ได้พอดี กริชโบราณซึ่งเป็นวัตถุโทรลล์อีกชิ้น แต่มีปัญหา...เล็กน้อย\n\nข้าพบกริชตอนค้นคว้าใน Stranglethorn แต่ยกให้ Catelyn ลูกสาวหัวรั้น นางหนีไป Booty Bay เพื่อเป็นโจรสลัดแล้ว" },
        completion = { "403:1263101259:1830387924", "กริชข้าหรือ? เจ้าเป็นตัวตลกหรืออย่างไร?\n\nอะไรนะ? จะให้ข้าเล่าซ้ำว่าจากยอดนักสู้มีดแห่ง Booty Bay ข้ากลายเป็นตัวตลกของวงการโจรสลัดได้อย่างไรหรือ!\n\nข้าแพ้ดวลมีดให้ Bloodsail Buccaneer คนหนึ่ง เจ้าพวกสารเลว! มันเอาดาบข้าไปเป็นของรางวัล\n\nข้าเป็นนักสู้มีดด้วยคำด่ากับลิ้นคมอย่างเดียวไม่ได้หรอก..." },
    },
    [604] = { -- The Bloodsail Buccaneers
        title = { "24:1118361646:1575445526", "โจรสลัด Bloodsail" },
        objective = { "140:1777872682:1107333779", "Fleet Master Seahorn ที่ Booty Bay ต้องการให้เจ้าฆ่า Bloodsail Swashbucklers 10 คน และนำ Bloodsail Charts กับ Bloodsail Orders กลับมา" },
        description = { "372:642130691:1667153303", "Crazz ชื่นชมความทุ่มเทของเจ้าที่มีต่อ Blackwater Raiders ข้าจะไว้ใจให้เจ้าทำภารกิจสำคัญยิ่งต่อกองเรือ\n\nแทรกซึมฐานที่ Bloodsail Buccaneers เรียกว่าฐานบัญชาการทางใต้บน Wild Shore บุกค่าย นำแผนที่กับคำสั่งเป็นลายลักษณ์อักษรมาให้ข้า เราจะรู้ให้แน่ว่าเจ้าสวะพวกนั้นคิดทำอะไร" },
        progress = { "6:533059392:220789999 N 66:730860540:1801376996", "อาฮอย {name} เจ้าพบข่าวอะไรจากค่าย Bloodsail ทางใต้?" },
        completion = { "9:736088637:128646839 N 123:1757286588:1532247685", "สมบูรณ์แบบ {name} เมื่อรู้แผนแล้ว ก็เหลือแค่เวลา\n\nนึกไม่ถึงว่าเจ้าพวกโง่ทอดสมออยู่นอกแหลมนี่เอง..." },
        required = { [3920] = { "16:1063883727:722956485", "แผนที่เดินเรือของกลุ่ม Bloodsail" }, [3921] = { "16:1662647654:624404932", "คำสั่งของกลุ่ม Bloodsail" } },
        steps = { { "16:1063883727:722956485", "แผนที่เดินเรือของกลุ่ม Bloodsail" }, { "16:1662647654:624404932", "คำสั่งของกลุ่ม Bloodsail" } },
        objectiveLabels = {
            monster = { ["Bloodsail Swashbuckler slain"] = "ปราบ โจรสลัดนักดาบ Bloodsail" },
        },
    },
    [605] = { -- Singing Blue Shards
        title = { "19:1256114789:1447868009", "เศษผลึกสีฟ้าขับขาน" },
        objective = { "51:1503428319:1991341559", "นำ Singing Crystal Shards 10 ชิ้น ไปให้ Crank Fizzlebub" },
        description = { "500:1415177314:59270557", "Singing Crystals พบเฉพาะ Stranglethorn และมีค่ามากสำหรับคนบางกลุ่ม ข้าขายมันได้ แต่ Venture Company บัดซบทำให้ผู้ประกอบการสุจริตอย่างข้าเก็บไม่ได้เลย!\n\nข้าอยากจ้างเจ้า\n\nบาซิลิสก์ใน Stranglethorn กินผลึก ทำให้หนังแข็ง บางครั้งเก็บผลึกคุณภาพดีจากหนังมันได้\n\nหาได้จากบาซิลิสก์ทุกตัว แต่ตัวที่ร้ายน้อยกว่าอยู่ตามชายฝั่งใต้ Zul'Kunda ทางเหนือจากที่นี่" },
        progress = { "74:1964155797:1398618536", "ได้เศษผลึกมาหรือยัง? ข้าจะแบ่งกำไรให้เจ้าพองาม!" },
        completion = { "27:1439652998:1433320837 N 87:827355635:1164580183", "อาฮ้า! พวกนี้ใช้ได้ดี {name} ใช่ ดีทีเดียว!\n\nนี่ส่วนแบ่งเจ้า และ...ยินดีที่ได้ค้าขายด้วย" },
        required = { [3918] = { "21:1722413611:717823762", "เศษผลึกขับขาน" } },
        steps = { { "21:1722413611:717823762", "เศษผลึกขับขาน" } },
    },
    [606] = { -- Scaring Shaky
        title = { "13:1995639522:176931219", "ขู่ Shaky" },
        objective = { "58:1304689693:783752443", "นำ Mistvale Giblets 5 ชิ้น ไปให้ “Shaky” Phillipe ที่ Booty Bay" },
        description = { "482:598247448:1520713328", "สิ่งหนึ่งที่ข้าทนไม่ได้คือพวกไม่จ่ายหนี้พนัน! มีคนติดหนี้ข้ามาก เจ้าช่วยทวงได้ไหม?\n\nคนแรก “Shaky” Phillipe แถวท่าเรือ เขาติดข้ามากจากเกมสัปดาห์ก่อน ข้าจะเอาคืน! แต่ต้องขู่ก่อน\n\nออกนอกเมืองไปล่า Elder Mistvale Gorillas เลือกเครื่องในมาดี ๆ แล้วนำไปให้ Shaky อย่าเผยว่าเป็นของสัตว์ ปล่อยให้เขาคิดเรื่องเลวร้ายที่สุดเอง" },
        progress = { { "52:568599385:1540791945", "50:427261325:1210145842" }, "เฮ้! ข้าไม่ชอบสายตาที่เจ้ามองข้าเลย" },
        completion = { "92:366900066:1058467062", "อ๊าก! เจ้าเอานี่มาจากไหน? ไม่ อย่าบอก ข้าไม่อยากรู้!\n\nใครส่งเจ้ามา? Sea Wolf หรือ?" },
        required = { [3919] = { "16:349271798:1036184833", "เครื่องใน Mistvale" } },
        steps = { { "16:349271798:1036184833", "เครื่องใน Mistvale" } },
    },
    [607] = { -- Return to MacKinley
        title = { "19:847666608:1110915347", "กลับไปหา MacKinley" },
        objective = { "46:138918269:2130058457", "นำ Shaky's Payment ไปให้ “Sea Wolf” MacKinley", variants = { { "45:1429410980:1409665396", "นำ Shaky's Payment ไปให้ “Sea Wolf” MacKinley" } } },
        description = { "216:818743020:664173165", "นี่ เอาถุงเงินไปให้ Sea Wolf บอกเขาว่าข้าตั้งใจจะคืนเงินจริง ๆ! สาบานได้!!\n\nข้าแค่เมานิดหน่อยแล้วหลงทาง และ...เจ้าก็รู้ว่ามันเป็นอย่างไร เขาจะเข้าใจ ไม่ต้องใช้กำลังหรอก!" },
        progress = { "11:507223554:1257787472 N 30:746097959:611875538", "นี่ {name} เจ้าได้เงินจาก Shaky มาหรือยัง?" },
        completion = { "182:1728000664:1190591587 N 35:781468143:1979251756", "เฮะ ๆ ทำได้ดี! ตอนเอาเครื่องในให้ Shaky ดู เขาตัวสั่นหนักแค่ไหน?\n\nฮ่า! อ่านใจเขาง่ายเหลือเกิน ข้าเล่นไพ่กับเขาทีไรก็อดชนะไม่ได้!\n\nขอบใจที่ช่วย {name} ทีนี้ถึงตาเจ้ารับเงินบ้าง..." },
        required = { [3922] = { "15:381154813:146710302", "เงินที่ Shaky จ่าย" } },
        steps = { { "15:381154813:146710302", "เงินที่ Shaky จ่าย" } },
    },
    [608] = { -- The Bloodsail Buccaneers
        title = { "24:1118361646:1575445526", "โจรสลัด Bloodsail" },
        objective = { "115:1398572950:915963533", "Fleet-Master Seahorn ที่ Booty Bay ต้องการให้เจ้าฆ่า Captain Stillwater, Captain Keelhaul และ Fleet Master Firallon" },
        description = { "339:154860436:1154848956 N 151:745866548:1367338070", "Firallon ช่างกล้า! มันพายเรือเล็กผ่าน Crystal Lake ยังไม่รอด จะนำทั้งกองเรือมาสู้เราได้อย่างไร\n\nBloodsail Buccaneers ต้องชดใช้ความประมาท เมื่อรู้แผนบุกแล้ว เราก็สวนกลับได้ก่อนมันรู้ตัว\n\nแต่ทำไมต้องส่งทั้งกองเรือไปทำงานที่กลุ่มนักผจญภัยผู้กล้ากลุ่มเดียวทำได้? {name} พาสหายฝีมือดีที่สุดไปจุดขึ้นฝั่งของ Firallon ลอบสังหารผู้นำ Bloodsail แล้วกองเรือมันจะล่มตามไป..." },
        progress = { "20:1522327554:1736608836 N 55:305327175:13276014", "มีปัญหาอะไร {name}? เราต้องโจมตีก่อน Bloodsail Buccaneers!" },
        completion = { "70:783651084:1150272472 N 1:33:33", "อา วันยิ่งใหญ่ของ Blackwater Raiders! โห่ร้องให้เจ้า {name} สามครั้ง!" },
        objectiveLabels = {
            monster = { ["Captain Stillwater slain"] = "ปราบ กัปตัน Stillwater", ["Captain Keelhaul slain"] = "ปราบ กัปตัน Keelhaul", ["Fleet Master Firallon slain"] = "ปราบ ผู้บัญชาการกองเรือ Firallon" },
        },
    },
    [609] = { -- Voodoo Dues
        title = { "11:1028872425:1246670949", "ทวงหนี้วูดู" },
        objective = { "115:45814569:1077027812", "นำ Maury's Clubbed Foot, Jon-Jon's Golden Spyglass และ Chucky's Huge Ring ไปให้ “Sea Wolf” MacKinley ที่ Booty Bay" },
        description = { "480:1235251219:1812377201", "รายชื่อข้าสั้นลงแล้ว แต่ยังมีคนติดหนี้อยู่\n\nต่อไปคือ Maury “Club Foot” Wilkins, Jon-Jon the Crow และ Chucky “Ten Thumbs”\n\nเจ้าสุนัขทะเลพวกนี้ค้างหนี้มาหลายเดือน ข้านึกว่าหนีออกเมืองไม่ยอมจ่าย! ต่อมาได้ยินว่าถูกสาปและสะกด ตอนนี้เร่ร่อนตามซากเมืองในป่า แต่ข้าไม่สนชะตาพวกมัน ข้าต้องการของที่เป็นของข้า!\n\nพวกมันอยู่ Ruins of Aboraz กับ Ruins of Jubuwal ทางตะวันออกเฉียงเหนือจากที่นี่ ไปหาแล้วทวงมา" },
        progress = { "N 65:1329256732:1371261354", "{name} เจ้าพบเจ้าสุนัขสามตัวนั้นไหม? เอาของมีค่ามาหรือยัง?" },
        completion = { "97:1182663432:1995333624 N 176:2080758832:1222259535", "เยี่ยม! ของพวกนี้ขายได้ราคาดี โดยเฉพาะสิ่งที่อยู่ในเท้า Maury! ขอบใจมาก {name}!\n\nหวังว่าทั้งสามจะได้บทเรียน อย่าพนันด้วยสิ่งที่ตนเสียไม่ได้\n\nและแม้จะสายไปแล้วสำหรับพวกมัน...ก็ควรระวังว่าพนันกับใคร" },
        required = { [3924] = { "20:764817613:1174515350", "เท้าที่ผิดรูปของ Maury" }, [3925] = { "25:641208195:595591465", "กล้องส่องทางไกลทองคำของ Jon-Jon" }, [3926] = { "18:920991191:740130085", "แหวนวงใหญ่ของ Chucky" } },
        steps = { { "20:764817613:1174515350", "เท้าที่ผิดรูปของ Maury" }, { "25:641208195:595591465", "กล้องส่องทางไกลทองคำของ Jon-Jon" }, { "18:920991191:740130085", "แหวนวงใหญ่ของ Chucky" } },
    },
    [610] = { -- "Pretty Boy" Duncan
        title = { "19:710035888:2082806499", "“Pretty Boy” Duncan" },
        objective = { "46:458825402:802675144", "ชิงกริชของ Catelyn จาก “Pretty Boy” Duncan" },
        description = { "456:1183005279:2039145473", "พ่อข้าส่งเจ้ามาหรือ? นึกว่าตาแก่จะเลิกหวังกับข้าแล้วเสียอีก\n\nที่ข้าหนีไม่ใช่ความผิดเขาหรอก เขาแค่ไม่ควรคิดว่าข้าจะยอมอยู่กับชีวิตน่าเบื่อ อ่านหนังสือเหม็นอับ คลุกคลีกับพ่อมดผมหงอกหลังตรงหัวโบราณ!\n\nหากต้องการกริชข้า ก็ต้องชิงคืนจาก “Pretty Boy” Duncan แห่ง Bloodsail Buccaneers แทงกลางหลังเขาสักที ข้ามั่นใจว่าเขาจะยอมยกให้" },
        progress = { "38:523798854:1113982797 N 264:1205816956:448262238", "รู้ไหม ข้าไม่เคยแพ้มาก่อนเลย {name}? แน่นอน เคยถูกบาด สู้มีดจะไม่โดนได้อย่างไร แต่เขาฟาดข้างศีรษะข้าจนสลบ พอฟื้นดาบก็หายแล้ว\n\nแม้ฉายาข้าจะชวนให้คิดอย่างไร ข้าก็ยังต้องใช้มีดสู้ และสำหรับข้า ต้องเป็นเล่มนั้นเท่านั้น" },
        completion = { "167:1513719741:1185001512", "เจ้าชนะ Duncan หรือ? ดูเหมือนจะไม่ได้อ่อนหัดอย่างที่เห็นครั้งแรก\n\nงั้นข้าก็คงไม่ควรท้าเจ้าสู้เร็ว ๆ นี้เหมือนกัน!" },
        required = { [4027] = { "15:31917014:16135555", "ดาบของ Catelyn" } },
        objectiveLabels = {
            item = { ["Catelyn's Blade"] = "ดาบของ Catelyn" },
        },
    },
    [611] = { -- The Curse of the Tides
        title = { "22:1066235495:1463636434", "คำสาปแห่งกระแสน้ำ" },
        objective = { "141:1356103313:1820309553", "ใช้ Catelyn's Blade ทำลาย Altar of the Tides ฆ่า Gazban แล้วนำ Stone of the Tides กับ Catelyn's Blade กลับไปให้ Baron Revilgaz" },
        description = { "306:83182552:1024498912", "เจ้ากำลังหาแท่นบูชาบางอย่างหรือ? ข้าไม่เชี่ยวชาญซากโทรลล์เหมือนพ่อ แต่เคยได้ยินเรื่องเมืองโทรลล์จมน้ำใกล้เกาะที่เจ้าตามหา ลองไปดูที่นั่นสิ\n\nเจ้าเอามีดคืนมาให้ ข้าคงให้ยืมได้...แต่ใช้เสร็จแล้วต้องคืนข้านะ!" },
        progress = { "50:1172416632:63931484 N 69:1935942114:1445111068", "เจ้านำ Stone of the Tides มาให้ข้าหรือยัง {name}? ข้าเคลียร์ที่และซื้อแท่นตั้งงาม ๆ รอแล้ว" },
        completion = { "202:1181380552:133290525", "น่าทึ่ง! ศิลาแห่งกระแสน้ำ! มันจะอยู่ในที่เด่นของชุดสะสมวัตถุโทรลล์โบราณของข้า เจ้าเห็นไหมว่าราวกับมีกระแสน้ำถูกกักไว้ใต้ผิว? งดงามยิ่ง!" },
        required = { [4034] = { "18:645893149:258558463", "ศิลาแห่งกระแสน้ำ" }, [4027] = { "15:31917014:16135555", "ดาบของ Catelyn" } },
        steps = { { "18:645893149:258558463", "ศิลาแห่งกระแสน้ำ" }, { "15:31917014:16135555", "ดาบของ Catelyn" } },
    },
    [613] = { -- Cracking Maury's Foot
        title = { "21:1261283573:1237323042", "ไขความลับเท้าของ Maury" },
        objective = { "55:729486622:1479098063", "นำ Maury's Key ไปให้ “Sea Wolf” Mackinley ที่ Booty Bay" },
        description = { "488:385323916:1228947757", "บัดซบ! เจ้า Maury ล็อกเท้าไว้ ข้าเปิดไม่ได้! ของที่ปล้นมาอยู่ในเท้า และนั่นคือสิ่งที่มันติดหนี้ข้า!\n\nเราต้องหากุญแจมาไข Maury เคยพนันกับออกร์ Mosh'Ogg ที่เนินทางตะวันออกเฉียงเหนือ ตอนยังมีชีวิตเขาบอกว่าครั้งล่าสุดถูกไล่ออกมาเพราะชนะมากเกินไป บางทีออกร์ที่นั่นอาจมีกุญแจ\n\nแต่ถ้ามี เจ้าคงต้องฆ่ามากทีเดียวกว่าจะพบตัวที่ถือ..." },
        progress = { "6:533059392:220789999 N 33:246788041:1760264762", "อาฮอย {name}! เจอ Maury's Key หรือยัง?" },
        completion = { "32:463003169:1369872915 N 62:1574788231:1217240508", "เจอแล้ว! ขอบคุณล้านครั้ง {name} เจ้าช่วยข้าไว้มาก!\n\nเอ้า เจ้าได้มันมาอย่างสมควรแล้ว!" },
        required = { [3930] = { "11:1252591596:1394926031", "กุญแจของ Maury" } },
        steps = { { "11:1252591596:1394926031", "กุญแจของ Maury" } },
    },
    [614] = { -- The Captain's Chest
        title = { "19:1657738786:1563318387", "หีบของกัปตัน" },
        objective = { "54:900113512:1134015518", "นำ Smotts' Chest ไปให้ Hecklebury Smotts ที่ Booty Bay" },
        description = { "484:981459108:417178083", "ข้าเคยเดินเรือจากที่นี่ไปถึง Ratchet ใน Kalimdor เป็นกัปตันที่ประสบความสำเร็จและมีชื่อเสียงไร้ด่างพร้อย\n\nจนกระทั่ง...\n\nยักษ์ทะเลบัดซบทำลายทุกอย่าง! มันทุบเรือ ฆ่าลูกเรือ แล้วจับข้าใส่เรือชูชีพกลับ Booty Bay ยักษ์ตัวหนึ่งชื่อ Gorlash ขโมยหีบกัปตันข้า บอกจะเอาไปใส่ยานัตถุ์ กล้าดีจริง!\n\nได้ยินว่า Gorlash เดินตามชายฝั่งตะวันออกจากที่นี่ หาแล้วเอาหีบคืน! ทำได้ กัปตันคนนี้จะขอบคุณเจ้าอย่างยิ่ง" },
        progress = { "6:533059392:220789999 N 116:936638495:1631444151", "อาฮอย {name}! เจอ Gorlash ไหม? หีบนั้นเป็นใบโปรด และมีช่องลับเก็บสมบัติล้ำค่าที่สุดของข้า!" },
        completion = { "48:1533350858:859916221 N 86:1730848759:618797627", "เจอแล้ว! ช่างเป็นวันดี! ขอบคุณ {name} ได้หีบคืนช่วยดับความแค้นในใจข้าไปบ้าง\n\nแต่การล้างแค้นยังไม่จบ..." },
        required = { [3932] = { "13:354765498:957292558", "หีบของสมอตส์" } },
        objectiveLabels = {
            item = { ["Smotts' Chest"] = "หีบของสมอตส์" },
        },
    },
    [615] = { -- The Captain's Cutlass
        title = { "21:1322447317:870026157", "ดาบโค้งของกัปตัน" },
        objective = { "20:252278587:844265482", "คุยกับ Sprogger" },
        description = { "494:2071480744:1463629237", "หลังเสียเรือลำแรกให้ยักษ์ ข้าซื้ออีกลำ ตั้งชื่อ Smotts' Revenge เตรียมเสบียงกับลูกเรือแล้วออกตามหาพวกชั่ว ข้าพบมัน แต่...ข้าแพ้ มันทุบ Smotts' Revenge ฆ่าลูกเรือชุดที่สอง แล้วจับข้าใส่เรือชูชีพอีกลำ\n\nครั้งนี้ยักษ์อีกตัวชื่อ Negolash ขโมยดาบโค้งข้า\n\nจงเผชิญ Negolash แล้วนำดาบคืนมา!\n\nคุยกับ Sprogger เขาเป็นพ่อครัวบน Smotts' Revenge และรอดการโจมตีครั้งล่าสุด เขาช่วยเจ้าหายักษ์ได้" },
        completion = { "13:2032203351:739554239 N 50:1766069531:1735565784", "สวัสดี สวัสดี {name} กัปตันบอกว่าเจ้าจะตามล่า Negolash ใช่ไหม?" },
    },
    [617] = { -- Akiris by the Bundle
        title = { "20:1266919010:1259651509", "มัดกก Akiris" },
        objective = { "65:1850889874:148651359", "นำ Bundles of Akiris Reed 10 มัด ไปให้ Privateer Bloads ที่ Booty Bay" },
        description = { "22:517633752:1729470511 N 382:149962846:356131116", "หางานอยู่หรือ {name}? ข้าอาจมีให้ ถ้าเจ้าพร้อมรับความท้าทายสักหน่อย\n\nข้ามีเพื่อนชื่อ Groy ทำกำไรอื้อจากสิ่งที่นากาเรียกว่ากก akiris เป็นกกทะเลมีค่า ไม่รู้ใช้ทำอะไร แต่เขาจ่ายดีหากส่งให้เป็นมัด\n\nนำมาสิบต้นแล้วเราค่อยคุยธุรกิจกัน ครั้งสุดท้ายพบนากาตามหาดทางเหนือจากที่นี่" },
        progress = { "48:1249717241:1716886385 N 1:46:46", "ถ้าไม่มีธุระกับข้า ก็ไปเสีย {name}" },
        completion = { "11:534428891:784080240 N 136:1502251542:1596903961", "ทำได้ดี {name} กก akiris 10 ต้นไม่ได้ยากเกินไปสินะ? ไม่ได้จะลบหลู่นากาหรอก แต่ทุกคนต้องทำมาหากิน" },
        required = { [4029] = { "11:793126069:1384781930", "ต้นกก Akiris" } },
        steps = { { "11:793126069:1384781930", "ต้นกก Akiris" } },
    },
    [618] = { -- Facing Negolash
        title = { "15:75431718:1108362740", "เผชิญหน้า Negolash" },
        objective = { "171:800094010:239889423", "นำ Barbecued Buzzard Wings 10 ชิ้น และ Junglevine Wine 5 ขวด ไปที่ Captain Smotts' Lifeboat\n\nฆ่า Negolash แล้วนำ Smotts' Cutlass ไปให้ Captain Smotts ที่ Stranglethorn" },
        description = { "489:107756925:411633980", "Negolash เป็นยักษ์หิวโหย\n\nตอนยักษ์ทำลายเรือเรา Negolash ตรงเข้าครัว ไม่ได้หิวลูกเรือเหมือนตัวอื่น มันต้องการไวน์...กับปีกแร้งย่างของข้า เมนูเด็ดที่ข้าต้องไปถึง Badlands เพื่อหาสูตร!\n\nหากจะล่อยักษ์ จงหาไวน์กับปีกแร้งกองใหญ่ วางในเรือชูชีพเก่าของเราตามชายฝั่งทางตะวันออกเฉียงใต้จากที่นี่ เมื่อ Negolash ได้กลิ่นอาหารทั้งหมด มันมาแน่!" },
        progress = { "24:540693049:1253055690 N 1:63:63", "เจ้าได้ดาบโค้งข้ามาหรือยัง {name}?" },
        completion = { "62:1295286931:1076884651 N 178:52874085:1571898434", "เจ้าชิงดาบโค้งข้าจาก Negolash ได้! ไม่อยากเชื่อโชคตัวเองเลย {name}! การพบเจ้าเปลี่ยนโชคข้าให้ดีขึ้นจริง ๆ!\n\nขอบคุณ! หากข้ามีเรือลำใหม่และเจ้าอยากออกทะเล เจ้าจะเป็นแขกผู้มีเกียรติของข้า" },
        required = { [3935] = { "15:1646901730:1123989935", "ดาบโค้งของสมอตส์" } },
        objectiveLabels = {
            item = { ["Smotts' Cutlass"] = "ดาบโค้งของสมอตส์" },
        },
    },
    [619] = { -- Enticing Negolash
        title = { "17:975451591:917702371", "ล่อ Negolash" },
        progress = { "112:281315167:1183215106", "นี่คือเรือชูชีพที่ถูกทิ้ง ด้านข้างมีชื่อเขียนด้วยสีที่ขูดขีดและซีดจางว่า\n\n“Smotts' Revenge”" },
        completion = { "40:2087533999:1332730879", "เจ้ากองอาหารและเครื่องดื่มบนแพ..." },
        description = { "112:281315167:1183215106", "นี่คือเรือชูชีพที่ถูกทิ้ง ด้านข้างมีชื่อเขียนด้วยสีที่ขูดขีดและซีดจางว่า\n\n“Smotts' Revenge”" },
        required = { [4457] = { "22:465503691:1087231767", "ปีกแร้งย่างบาร์บีคิว" }, [4595] = { "15:2142307797:2080704021", "ไวน์เถาวัลย์ป่า" } },
        objectiveLabels = {
            item = { ["Barbecued Buzzard Wing"] = "ปีกแร้งย่างบาร์บีคิว", ["Junglevine Wine"] = "ไวน์เถาวัลย์ป่า" },
        },
    },
    [621] = { -- Zanzil's Secret
        title = { "15:1170398682:2039624927", "ความลับของ Zanzil" },
        objective = { "69:970848878:143627806", "นำตัวอย่าง Zanzil's Mixture 12 ชิ้น ไปให้ Crank Fizzlebub ที่ Booty Bay" },
        description = { "458:1194918729:1538609994", "Zanzil the Outcast อยู่กับสาวกที่ซาก Jubuwai และ Aboraz ทางตะวันออกเฉียงเหนือของ Booty Bay เขาถูกขับจากเผ่า เพราะอะไรหรือ? ก็...\n\nZanzil มีวิธีบังคับจิตผู้อื่น ผู้นำจึงกลัวเขา เขาใช้ส่วนผสมพืชป่ากับสาวกเพื่อกดเจตจำนงและเพิ่มกำลังร่างกาย\n\nส่วนผสมนี้คงมีค่าสำหรับผู้ต้องการควบคุมคนอื่น\n\nนำตัวอย่างมาให้ข้า แล้วข้าจะหาประโยชน์จากมัน" },
        progress = { "45:80056113:1247911765", "เจ้ามีตัวอย่าง Zanzil's Mixture หรือยัง??" },
        completion = { "93:589185886:992895469", "อา ดีมาก! นี่ค่าจ้างเจ้า\n\nและนี่เงินพิเศษเล็กน้อย...สำหรับการเก็บความลับ" },
        required = { [4016] = { "16:251060364:1486310231", "สารผสมของ Zanzil" } },
        steps = { { "16:251060364:1486310231", "สารผสมของ Zanzil" } },
    },
    [622] = { -- Return to Corporal Kaleb
        title = { "24:1919498781:1248327405", "กลับไปหา Corporal Kaleb" },
        objective = { "61:1530231847:370665821", "นำ Krazek's Fixed Pot ไปให้ Corporal Kaleb ที่ Rebel Camp" },
        description = { "255:766376311:162638127", "ระหว่างเจ้าไม่อยู่ ข้าซ่อมหม้อที่นำมาแล้ว เพิ่มหวูดไอน้ำอีกอันด้วย ดูสิ! ก้นหม้อมีใบสับใหม่ ตัดกระดูกขาได้เลย!\n\nใช่แล้ว หม้อของ Krazek ถูกใจพ่อครัว 100% แน่! เจ้าของต้องพอใจแน่นอน" },
        progress = { "7:989913233:66981971 N 66:367492850:1543487512", "สวัสดี {name} ไปถึง Booty Bay ไหม? ก็อบลิน Krazek ซ่อมหม้อข้าหรือยัง??" },
        completion = { "73:1843515352:1029247209 N 223:1426632987:864307071", "ซ่อมแล้ว! ดีจริง ข้าจะได้เริ่มทำมื้อเย็น! ขอบคุณมาก {name}\n\nหวังว่าเจ้าไม่เป็นอะไรที่ Booty Bay ที่นั่นเถื่อนทีเดียว และ...ได้ยินว่าบางทีก็อบลินลากกะลาสีเมาไปเรือค้าทาส พาไปไหนก็ไม่รู้...ให้ทำอะไรก็ไม่รู้..." },
        required = { [1987] = { "18:1682239661:919511875", "หม้อที่ Krazek ซ่อมแล้ว" } },
        steps = { { "18:1682239661:919511875", "หม้อที่ Krazek ซ่อมแล้ว" } },
    },
    [623] = { -- Akiris by the Bundle
        title = { "20:1266919010:1259651509", "มัดกก Akiris" },
        objective = { "62:1787842072:1949497996", "นำ Bundle of Akiris Reeds ไปให้ Privateer Groy ที่ Theramore" },
        description = { "N 490:421960095:796620174", "{name} ไหน ๆ เจ้าก็อยู่นี่ ระหว่างเจ้าไม่อยู่ข้าได้ข่าวจาก Groy เขาพอใจสินค้างวดล่าสุด และมีลูกค้าอยากได้เพิ่มทันที\n\nอีกสัปดาห์ข้าจึงจะไป Theramore หากเจ้ายอมเดินทาง ก็เอาของไปแทนข้าได้\n\nอยากผจญภัยไหม? รู้ใช่ไหมว่า Dustwallow Marsh อยู่ไหน? ระวังด้วย Theramore อันตรายได้หากเจ้าอยู่ผิดฝ่าย" },
        progress = { "5:1286193019:669424916", "ว่าไง?" },
        completion = { "70:1977194268:403396022 C 280:68408659:925394778 C 74:929187455:1844275047", "อะไร?! ข้ามีเรื่องดีกว่าคุยกับคนอย่างเจ้าอีกมาก {class} ทำให้คุ้มเวลาข้าหรือไปให้พ้นหน้า\n\nหือ? Bloads ส่งมาหรือ? มีอะไรให้ข้า?\n\n<Privateer Groy ตรวจมัดกกอย่างละเอียด>\n\nไม่เลว ไม่เลวเลย อีกมัดต้องทำให้ลูกค้าข้าพอใจมาก\n\nคำถามต่อไปคงเรื่องเงินสินะ {class}? แน่นอนอยู่แล้ว!\n\nเอาเหรียญนี่ไป พร้อมคำแนะนำ ออกไปจากท่าเรือข้าเสีย" },
        required = { [4028] = { "22:67829850:1877346331", "มัดต้นกก Akiris" } },
        steps = { { "22:67829850:1877346331", "มัดต้นกก Akiris" } },
    },
    [624] = { -- Cortello's Riddle
        title = { "17:2147333046:546346061", "ปริศนาของ Cortello" },
        objective = { "17:701960923:269071769", "ไขปริศนา!" },
        description = { "235:1557136510:537005118", "มีสะพานประดับงาม ผู้คนสัญจรมากมาย\nทางตะวันออกของ Deadwind และใต้ Redridge\nเบื้องล่างมีบางสิ่งรอเจ้าอยู่\nบ้างเรียกคำใบ้ บ้างเรียกเบาะแส\nมันจะนอนรอวันพรุ่งนี้อันไม่สิ้นสุด\nคอยเวลาอยู่ใน Swamp of Sorrows" },
        completion = { "46:1317460163:2030105199", "แผ่นหนังชุ่มน้ำมีเบาะแสต่อไป..." },
    },
    [625] = { -- Cortello's Riddle
        title = { "17:2147333046:546346061", "ปริศนาของ Cortello" },
        objective = { "17:701960923:269071769", "ไขปริศนา!" },
        description = { "242:534540292:145582522", "ดินแดนห่างไกลใน Kalimdor รออยู่\nภัยอันตรายทำลายทั้งความหวังและชะตา\nทางตะวันออกของ Barrens อากาศร้ายกาจ\nความมืดมนและอันตรายปกคลุม Dustwallow Marsh\nแต่มีเบาะแสสำหรับผู้พร้อมรับการทดสอบ\nรอให้ค้นพบในถ้ำทางตะวันตกเฉียงใต้" },
        completion = { "24:439123090:102379820", "เจ้าพบม้วนคัมภีร์เหม็นอับ" },
    },
    [626] = { -- Cortello's Riddle
        title = { "17:2147333046:546346061", "ปริศนาของ Cortello" },
        objective = { "17:701960923:269071769", "ไขปริศนา!" },
        description = { "279:1083483638:821282204", "ไป Lordaeron! ดินแดนใหญ่แห่งความวุ่นวาย\nที่ทหารกล้ากรำศึกกับความตาย\nฝ่าความไม่สงบครั้งใหญ่ไป\nแล้วเจ้าจะพบจุดจบของภารกิจนี้\nตามชายฝั่ง Hinterlands ที่เชิงน้ำตกใหญ่\nใต้ผืนน้ำ สมบัติร้องเรียกเจ้าอยู่!" },
        completion = { "34:312483070:1122317280", "เจ้าเปิดหีบแล้วพบว่า..." },
    },
    [627] = { -- Favor for Krazek
        title = { "16:1894385156:1939816543", "ช่วยเหลือ Krazek" },
        objective = { "62:1557396756:431043516", "นำ Lesser Bloodstone Ore 4 ก้อน ไปให้ Krazek ที่ Booty Bay" },
        description = { "494:16758043:117865774", "มีถ้ำบนภูเขาใน Drywhisker Gorge ทางเหนือไกลออกไปใน Arathi Highlands ในถ้ำนั้นมีแร่หายากชื่อ bloodstone แม้แร่จากถ้ำนี้ไม่ใช่เกรดสูงที่สุด แต่คุณภาพต่ำก็ยังมีค่า...สำหรับผู้รู้วิธีใช้\n\nข้าอยากได้บ้าง\n\nข้าจะซ่อมหม้อให้ แต่ระหว่างทำ...นำตัวอย่าง bloodstone มาให้ข้า หากมากพอ ข้าจะแถมรางวัลให้ด้วย\n\nอ้อ หากเจ้าไม่มีทักษะขุดแร่...ก็หาคนที่มีสิ!" },
        progress = { "7:989913233:66981971 N 43:1038962885:378374250", "สวัสดี {name} หา bloodstone ได้ไหม?" },
        completion = { "74:1578554564:1427241322", "อา ยอดเยี่ยม! เจ้าช่วยข้าไว้มากจริง ๆ\n\nนี่ค่าตอบแทน..." },
        required = { [4278] = { "21:902902400:1139306953", "แร่ Bloodstone เกรดรอง" } },
        steps = { { "21:902902400:1139306953", "แร่ Bloodstone เกรดรอง" } },
    },
    [628] = { -- Excelsior
        title = { "9:1193324311:1258001591", "Excelsior" },
        objective = { "55:1172669297:80364335", "นำ Elder Crocolisk Skin ไปให้ Drizzlik ที่ Booty Bay" },
        description = { "475:1662211855:32427202", "เมื่อด้านในเสร็จ เหลือเพียงเสริมชั้นนอก ข้าใช้แต่หนังครอโคลิสก์แก่ชั้นดี ทนกว่าและเหมาะกับการลงลายและรายละเอียดที่เป็นเอกลักษณ์ของรุ่น Excelsior ของ Drizzlik\n\nแต่หนังที่สมบูรณ์นั้นหายาก มีเพียงหนังครอโคลิสก์น้ำเค็มแก่ที่ตรงแผน พวกตัวแก่จะออกมาปกป้องครอโคลิสก์น้ำเค็มตัวอื่นเท่านั้น เจ้าอาจต้องฆ่าสักสองสามตัวเพื่อล่อมันออกมา" },
        progress = { "175:129150844:1465853573", "ข้าอ่านพบว่าครอโคลิสก์น้ำเค็มกำลังค่อย ๆ สูญพันธุ์...ข่าวร้ายต่อธุรกิจข้าใช่ไหม?\n\nเอาเถอะ หวังว่าเจ้าจะมีหนังครอโคลิสก์น้ำเค็มแก่มาให้!" },
        completion = { "304:193393012:1588227155", "เยี่ยม! เพราะเจ้าช่วย ข้าจึงทำคำสั่งซื้อนี้เสร็จ ส่งให้ Director Riddlevox กับเรือเที่ยวหน้าไป Undermine ได้ ก่อนกำหนดเสียอีก!\n\nสำหรับงานหนักทั้งหมด เอ้า ข้าทำเผื่อไว้ เอาไปคู่หนึ่ง Drizzlik ให้ฟรี\n\nจำไว้ ไม่มีรองเท้าใดงามเท่า Excelsior ของ Drizzlik!" },
        required = { [4105] = { "20:2070559202:1591888666", "หนังครอโคลิสก์อาวุโส" } },
        steps = { { "20:2070559202:1591888666", "หนังครอโคลิสก์อาวุโส" } },
    },
    [629] = { -- The Vile Reef
        title = { "13:199436443:1892128711", "แนวปะการังอัปมงคล" },
        objective = { "61:1027386451:1919159474", "นำ Tablet Shard ไปให้ Kin'weelay ที่ Grom'gol Base Camp" },
        description = { "489:1832266967:546538805", "นานมาแล้ว แผ่นดินสั่นสะเทือนครั้งใหญ่จมเมืองโทรลล์เก่าใต้ผืนน้ำ Savage Coast ทางตะวันตกเฉียงเหนือ เราเรียกที่นั่น Vile Reef เพราะตอนนี้เมอร์ล็อกอาศัยในซากเมืองและโจมตีผู้เข้าใกล้\n\nในซากมีศิลาจารึกเก่าเล่าเรื่อง Gri'lek วีรบุรุษในตำนานโทรลล์ เรื่องนี้ศักดิ์สิทธิ์ต่อ Darkspear แม้จารึกใหญ่เกินเคลื่อนย้าย ข้าอยากได้เศษชิ้นหนึ่งไปประดิษฐานในบ้านใหม่ที่ Orgrimmar" },
        progress = { "26:766422584:709322588 N 1:46:46", "ข้ารอ Tablet Shard อยู่ {name}" },
        completion = { "148:826136865:325131226 N 64:1308077407:1585733076", "ดีมาก เมื่อกลับ Orgrimmar ข้าจะวางเศษจารึกนี้ในที่ศักดิ์สิทธิ์ มันจะเตือนเราถึงพลังและเกียรติยศของ Gri'lek\n\nขอบคุณ {name} การกระทำเจ้าแสดงถึงมิตรภาพกับ Darkspear ที่เพิ่มขึ้น" },
        required = { [4094] = { "12:826245153:427424428", "เศษแผ่นจารึก" } },
        steps = { { "12:826245153:427424428", "เศษแผ่นจารึก" } },
    },
    [630] = { -- Message in a Bottle
        title = { "19:1721482880:1635361150", "สารในขวด" },
        objective = { "71:995731296:442483880", "ฆ่า King Mukla แล้วนำกุญแจกลับไปให้ Princess Poobah เพื่อปลดปล่อยนาง" },
        description = { "N 411:1393224179:850294557", "{name} ข้าฝากความหวังไว้กับเจ้าและทุกคนที่เจ้ารวบรวมมาช่วยได้ Skymane ผู้ยิ่งใหญ่ King Mukla จับข้าไว้ มันบัญชาสัตว์บนเกาะให้ขังข้าด้วยโซ่นี้ หากฆ่ามันและหากุญแจไขตรวนได้ ข้าจะเป็นหนี้บุญคุณยิ่งนัก\n\nข้ามักได้ยินมันทางตะวันออกเฉียงใต้ของเกาะ แต่ระวังด้วย มันไม่ใช่คู่ต่อสู้ที่ประมาทได้" },
        progress = { "87:622663596:510289079", "ขอบคุณบรรพบุรุษที่มีคนมาช่วยข้า เจ้ามีกุญแจปลดปล่อยข้าหรือยัง?" },
        completion = { "N 208:670058198:1369555871", "{name} เจ้าช่วยให้ข้าพ้นความอัปยศใหญ่หลวง หากมีอำนาจ ข้าจะเสนอที่ให้เจ้าในเผ่า แต่ตอนนี้ข้ามอบได้เพียงของแทนใจนี้ สำหรับความกล้าหาญและสูงส่งที่เจ้าแสดง" },
        required = { [4103] = { "11:521583252:1980543513", "กุญแจโซ่ตรวน" } },
        steps = { { "11:521583252:1980543513", "กุญแจโซ่ตรวน" } },
    },
    [638] = { -- Trollbane
        title = { "9:1259888271:2035347663", "Trollbane" },
        objective = { "66:1898730467:1323997529", "เดินทางไป Hammerfall ใน Arathi Highlands แล้วคุยกับ Zengu" },
        description = { "370:133197643:1023606213", "เมื่อ Thoras Trollbane ตายและ Stromgarde พังทลาย Vol'jin สั่งให้เราทำทุกวิถีทางเพื่อลอบนำดาบในตำนาน Trol'kalar จากมือมนุษย์ จะได้ใช้ในศึกกับโทรลล์ Zul'Gurub ที่กำลังมา\n\nZengu นักล่ามากประสบการณ์ของเรา ถูกส่งไป Hammerfall ทางตะวันออกเฉียงเหนือของ Arathi Highlands เพื่อดูแลการนำดาบมา" },
        completion = { "15:1358416781:1030275119 C 132:2130840687:1334363115", "เป็นอย่างไร {class}? งานที่ Vol'jin มอบหมายยากนัก ความช่วยเหลือใดที่เจ้ามอบให้ล้วนจำเป็นและเรายินดีรับ" },
    },
    [1036] = { -- Avast Ye, Scallywag
        title = { "19:993891045:1718772360", "หยุดก่อน เจ้าตัวแสบ" },
        objective = { "93:1918811924:1320105030", "คุยกับ Fleet Master Firallon บนเรือ Crimson Vale นอกชายฝั่ง Stranglethorn Vale" },
        description = { { "N 382:1386418518:1137917330", "N 384:1459158948:1290819020" }, "{name}...ใช่ ข้าได้ยินเรื่องเจ้า ได้ยินว่าเจ้าไม่ใช่มิตร Booty Bay เหมือนพวกเรา Bloodsail Buccaneers Fleet Master Firallon กำลังหาคนแข็งแรงกำยำอย่างเจ้าทำภารกิจพิเศษ\n\nหากสนใจ ไปเรือ Crimson Veil แล้วคุยกับเขาใต้ดาดฟ้า เรือทอดสมอนอก Wild Coast ทางตะวันออกจากที่นี่ ข้าง Riptide กับ Damsel's Luck" },
        completion = { "192:1190477886:1513132452", "หยุดก่อน เจ้าตัวแสบ ได้ยินว่าเจ้าชอบเล่ห์กลสักหน่อย หากไม่ใช่มิตร Booty Bay เจ้าก็อาจมีที่พิเศษในหมู่ Bloodsail Buccaneers\n\nอาร์ร์..." },
    },
    [1127] = { -- Fool's Stout
        title = { "12:1557610516:753682013", "Fool's Stout" },
        objective = { "61:36799100:1391173115", "นำ Zanzil's Mixture 12 ชิ้น ไปให้ Crank Fizzlebub ที่ Booty Bay" },
        description = { "160:203258216:1208041545", "อยากได้ Fool's Stout อีกหรือ? คิดจะกลับไปสนามแข่ง...?\n\nได้ นำส่วนผสม Zanzil มาเพิ่ม แล้วข้าจะทำสเตาต์ให้เจ้าอีก" },
        progress = { "39:656748853:1795622106 N 1:63:63", "ได้ส่วนผสม Zanzil มาหรือยัง {name}?" },
        completion = { "93:589185886:992895469", "อา ดีมาก! นี่ค่าจ้างเจ้า\n\nและนี่เงินพิเศษเล็กน้อย...สำหรับการเก็บความลับ" },
    },
    [3625] = { -- Enchanted Azsharite Fel Weaponry
        title = { "32:1452856888:201001549", "อาวุธเฟล Azsharite ลงมนตร์" },
        objective = { "47:552741155:1433090648", "รอ Galvan ตีอาวุธให้เสร็จ" },
        description = { "N 347:264758710:1601724039 N 1:46:46", "{name} การสร้างอาวุธแต่ละชิ้นต้องใช้เวลา\n\nนอกจากนี้ เจ้าใช้พลัง Felcurse ได้เพียงครั้งเดียวทุกสามนาที ระยะเวลาที่มันลดกำลัง Razelikh the Defiler กับสมุนอาจไม่เท่ากัน จึงต้องปล่อย Felcurse ในจังหวะที่เหมาะเท่านั้น!\n\nตอนนี้ขอเวลาข้าสร้างอาวุธสักครู่ {name}" },
        progress = { "82:2141307654:154923310 N 1:46:46", "หากขัดจังหวะการตี อาวุธอาจไม่สมบูรณ์ อดทนไว้ {name}" },
        completion = { "80:76029866:201872595 N 1:46:46", "<Galvan เช็ดเหงื่อจากหน้าผาก>\n\nไม่เคยมีอาวุธสังหารปีศาจใดดีเท่านี้ {name}" },
    },
    [3626] = { -- Return to the Blasted Lands
        title = { "27:1867876086:1356606365", "กลับสู่ Blasted Lands" },
        objective = { "39:105196501:500749449", "กลับไปหา Fallen Hero of the Horde" },
        description = { "32:672989098:1369319628 N 144:1020640745:25716611", "เวลาไถ่บาปใกล้เข้ามาแล้ว {name} เจ้าต้องนำอาวุธใหม่กลับ Blasted Lands และคุยกับ Fallen Hero of the Horde เพื่อรับเป้าหมายสุดท้าย" },
        completion = { "26:1145146491:1971305817 N 52:1498220818:1980394252", "เจ้าดูผ่านศึกมามาก {name} พร้อมเผชิญ Razelikh กับสมุนหรือยัง?" },
    },
    [3721] = { -- An OOX of Your Own
        title = { "18:1182512604:93722076", "OOX ของเจ้าเอง" },
        completion = { "470:1897499248:1029546125", "เจ้านำหุ่นยนต์กลับฐาน OOX ทั้งสามตัวของข้าคืนมาแล้ว! เจ้าทำเกินกว่าที่จำเป็น ข้าจะมอบของพิเศษตอบแทนความช่วยเหลือทั้งหมด มันคือรุ่นย่อของหุ่นยนต์ที่เจ้ารู้จักและรัก OOX นั่นเอง!\n\nปกติข้าไม่ให้ใครมีอุปกรณ์ที่อาจเป็นอันตรายถึงชีวิต แต่เจ้าช่วยข้ามาก อีกอย่าง กลไกต่อสู้และระบบกลับฐานของตัวนี้ถูกปิดแล้ว\n\nนอกนั้น มันคือ OOX แท้ ๆ เลย!" },
    },
    [4621] = { -- Avast Ye, Admiral!
        title = { "18:1480895196:452811700", "หยุดก่อน ท่านพลเรือ!" },
        objective = { "160:776676124:2114864636", "ฆ่า Fleet Master Seahorn และ Baron Revilgaz แห่ง Booty Bay แล้วกลับไปหา Fleet Master Firallon บนเรือ Crimson Veil นอกชายฝั่ง Stranglethorn Vale" },
        description = { { "493:153636300:1347548122", "493:1949701988:159729098" }, "ฟังให้ดี กะลาสี...ผู้มีอำนาจ Booty Bay ขวาง Bloodsail ไม่ให้แล่นเรือไปตามใจและปล้นของที่ควรเป็นสิทธิ์เรา หากเจ้าปักมีด Fleet Master Seahorn เรือ Booty Bay ก็จะไม่มาขวางเราอีก หากเจ้าปักมีด Baron Revilgaz เราก็ไม่ต้องอยู่ใต้กฎหมายมัน\n\nหากจะเป็นพลเรือกิตติมศักดิ์ของเรา ใช่ พลเรือ! เจ้าต้องปักมีดทั้งคู่ตามข้าสั่ง ไปได้ แล้วกลับมาเมื่อทำสำเร็จ" },
        progress = { "117:93527204:985510638", "กลับมาแล้วหรือ เจ้ากะลาสีบัดซบ! ทำตามคำสั่งหรือยัง? ถ้าทำให้เราผิดหวัง เจ้าต้องเดินกระดานลงทะเล\n\nอาร์ร์..." },
        completion = { "20:888609569:878710017 N 207:822106898:587312325", "หยุดก่อน...พลเรือ {name}! เจ้าคือสุดยอดโจรสลัด แม่สาวน้อย!\n\nข้ายินดีจากใจที่มอบหมวกนี้ให้ ไม่มีเหมือนที่ใด ทุกคนที่มองเจ้าจะรู้ว่าเจ้าเป็นพลเรือแห่งกองทัพเรือ Bloodsail!" },
    },
    [7810] = { -- Arena Master
        title = { "12:695950883:704008688", "เจ้าแห่งสนามประลอง" },
        objective = { "57:2093013813:572088683", "คุยกับ Short John Mithril ใน Stranglethorn Arena" },
        description = { "122:68402568:164108203", "การเป็นเจ้าแห่งสนามประลองต้องมีมากกว่านี้แน่! บางทีโจรสลัดที่จัดงานใน Gurubashi คงรู้!" },
        completion = { "124:1146326756:303353278", "อาร์ สหาย! ได้เครื่องประดับชิ้นเดียวยังไม่พอเป็นเจ้าแห่งสนามประลอง! ถึงเวลาพิสูจน์ฝีมือแท้จริงแล้ว" },
    },
    [7838] = { -- Arena Grandmaster
        title = { "17:1696717708:752078960", "ปรมาจารย์สนามประลอง" },
        progress = { "120:1858073277:1747494296", "หยุดก่อน เจ้าบก! นำเครื่องประดับ Arena Master มา 12 ชิ้น แล้วเจ้าจะได้เป็นปรมาจารย์แห่ง Gurubashi Arena! อาร์ร์!" },
        completion = { "96:814305976:1668294893", "เจ้าหลั่งเลือดบนพื้นสนามมากมาย ข้ายินดีขนานนามเจ้าว่าปรมาจารย์สนามประลอง!" },
        required = { [18706] = { "12:695950883:704008688", "เครื่องหมายยอดนักสู้แห่งสนามประลอง" } },
        objectiveLabels = {
            item = { ["Arena Master"] = "เครื่องหมายยอดนักสู้แห่งสนามประลอง" },
        },
    },
    [8551] = { -- The Captain's Chest
        title = { "19:1657738786:1563318387", "หีบของกัปตัน" },
        objective = { "54:900113512:1134015518", "นำ Smotts' Chest ไปให้ Hecklebury Smotts ที่ Booty Bay" },
        description = { "484:981459108:417178083", "ข้าเคยเดินเรือจากที่นี่ไปถึง Ratchet ใน Kalimdor เป็นกัปตันที่ประสบความสำเร็จและมีชื่อเสียงไร้ด่างพร้อย\n\nจนกระทั่ง...\n\nยักษ์ทะเลบัดซบทำลายทุกอย่าง! มันทุบเรือ ฆ่าลูกเรือ แล้วจับข้าใส่เรือชูชีพกลับ Booty Bay ยักษ์ตัวหนึ่งชื่อ Gorlash ขโมยหีบกัปตันข้า บอกจะเอาไปใส่ยานัตถุ์ กล้าดีจริง!\n\nได้ยินว่า Gorlash เดินตามชายฝั่งตะวันออกจากที่นี่ หาแล้วเอาหีบคืน! ทำได้ กัปตันคนนี้จะขอบคุณเจ้าอย่างยิ่ง" },
        progress = { "6:533059392:220789999 N 116:936638495:1631444151", "อาฮอย {name}! เจอ Gorlash ไหม? หีบนั้นเป็นใบโปรด และมีช่องลับเก็บสมบัติล้ำค่าที่สุดของข้า!" },
        completion = { "48:1533350858:859916221 N 86:1730848759:618797627", "เจอแล้ว! ช่างเป็นวันดี! ขอบคุณ {name} ได้หีบคืนช่วยดับความแค้นในใจข้าไปบ้าง\n\nแต่การล้างแค้นยังไม่จบ..." },
        required = { [3932] = { "13:354765498:957292558", "หีบของ Smotts" } },
        steps = { { "13:354765498:957292558", "หีบของ Smotts" } },
    },
    [8552] = { -- The Monogrammed Sash
        title = { "20:27727881:1276153568", "ผ้าคาดเอวปักอักษรย่อ" },
        objective = { "41:1748443037:1255699605", "คืน Monogrammed Sash ให้เจ้าของ" },
        description = { "62:853922211:1750635536", "ผ้าคาดเอวเนื้อดีนี้ปักอักษร “HS” ตามชายผ้า" },
        progress = { "36:519456537:1383087150", "สวัสดี มีธุระกับข้าหรือ?" },
        completion = { "221:1139992928:1304183296 C 11:479707142:1337671816 N 1:46:46", "เจ้าพบผ้าคาดเอวข้าหรือ? ถ้าเช่นนั้น...เจ้าต้องฆ่ายักษ์ทะเล Mok'rash แล้ว! ไชโย!\n\nดีใจที่วายร้ายตาย Mok'rash เป็นหนึ่งในสามยักษ์ทะเลที่ทุบเรือและฆ่าลูกเรือข้า\n\nสามครั้ง\n\nเจ้าเป็น {class} ผู้มีคุณค่า {name}" },
        required = { [3985] = { "16:289564624:1752920362", "ผ้าคาดเอวปักอักษรย่อ" } },
        steps = { { "16:289564624:1752920362", "ผ้าคาดเอวปักอักษรย่อ" } },
    },
    [8553] = { -- The Captain's Cutlass
        title = { "21:1322447317:870026157", "ดาบโค้งของกัปตัน" },
        objective = { "20:252278587:844265482", "คุยกับ Sprogger" },
        description = { "494:2071480744:1463629237", "หลังเสียเรือลำแรกให้ยักษ์ ข้าซื้ออีกลำ ตั้งชื่อ Smotts' Revenge เตรียมเสบียงกับลูกเรือแล้วออกตามหาพวกชั่ว ข้าพบมัน แต่...ข้าแพ้ มันทุบ Smotts' Revenge ฆ่าลูกเรือชุดที่สอง แล้วจับข้าใส่เรือชูชีพอีกลำ\n\nครั้งนี้ยักษ์อีกตัวชื่อ Negolash ขโมยดาบโค้งข้า\n\nจงเผชิญ Negolash แล้วนำดาบคืนมา!\n\nคุยกับ Sprogger เขาเป็นพ่อครัวบน Smotts' Revenge และรอดการโจมตีครั้งล่าสุด เขาช่วยเจ้าหายักษ์ได้" },
        completion = { "13:2032203351:739554239 N 50:1766069531:1735565784", "สวัสดี สวัสดี {name} กัปตันบอกว่าเจ้าจะตามล่า Negolash ใช่ไหม?" },
    },
    [8554] = { -- Facing Negolash
        title = { "15:75431718:1108362740", "เผชิญหน้า Negolash" },
        objective = { "171:800094010:239889423", "นำ Barbecued Buzzard Wings 10 ชิ้น และ Junglevine Wine 5 ขวด ไปที่ Captain Smotts' Lifeboat\n\nฆ่า Negolash แล้วนำ Smotts' Cutlass ไปให้ Captain Smotts ที่ Stranglethorn" },
        description = { "489:107756925:411633980", "Negolash เป็นยักษ์หิวโหย\n\nตอนยักษ์ทำลายเรือเรา Negolash ตรงเข้าครัว ไม่ได้หิวลูกเรือเหมือนตัวอื่น มันต้องการไวน์...กับปีกแร้งย่างของข้า เมนูเด็ดที่ข้าต้องไปถึง Badlands เพื่อหาสูตร!\n\nหากจะล่อยักษ์ จงหาไวน์กับปีกแร้งกองใหญ่ วางในเรือชูชีพเก่าของเราตามชายฝั่งทางตะวันออกเฉียงใต้จากที่นี่ เมื่อ Negolash ได้กลิ่นอาหารทั้งหมด มันมาแน่!" },
        progress = { "24:540693049:1253055690 N 1:63:63", "เจ้าได้ดาบโค้งข้ามาหรือยัง {name}?" },
        completion = { "62:1295286931:1076884651 N 178:52874085:1571898434", "เจ้าชิงดาบโค้งข้าจาก Negolash ได้! ไม่อยากเชื่อโชคตัวเองเลย {name}! การพบเจ้าเปลี่ยนโชคข้าให้ดีขึ้นจริง ๆ!\n\nขอบคุณ! หากข้ามีเรือลำใหม่และเจ้าอยากออกทะเล เจ้าจะเป็นแขกผู้มีเกียรติของข้า" },
        required = { [3935] = { "15:1646901730:1123989935", "ดาบโค้งของ Smotts" } },
        steps = { { "15:1646901730:1123989935", "ดาบโค้งของ Smotts" } },
    },
    [9259] = { -- Traitor to the Bloodsail
        title = { "24:84795435:711509456", "ผู้ทรยศ Bloodsail" },
        progress = { "426:1155050860:634824576", "Revilgaz เจ้าสุนัขขี้เรื้อนเสนออภัยโทษให้อดีต Bloodsail ที่ยอมทรยศกัปตัน! เจ้าสวะนั่นให้ข้าไปฆ่าเพื่อนเก่า เอาผ้าโพกหัวมาเป็นหลักฐาน\n\nข้าทำไม่ลง และจะไม่ขอให้เจ้าทำ นำผ้าไหมกับสีย้อมแดงมา ข้าจะทำของเลียนแบบให้เหมือน ข้าจะบอกบารอนว่าเจ้าย้ายข้างแล้ว แต่เตือนไว้...Bloodsail ไม่ชอบแน่!" },
        completion = { "57:585011170:109573512 N 149:1750280413:481609357", "สงบนิ่งไว้อาลัยเพื่อนที่ล่วงลับสักนาที {name}\n\n<Bloodsail Traitor ยิ้มกว้างแล้วขยิบตาให้เจ้า>\n\nเป็นคนทรยศก็เรื่องหนึ่ง แต่ฆ่าเพื่อนตัวเอง...นั่นชั่วช้าสิ้นดี ว่าไหม!" },
        description = { "426:1155050860:634824576", "Revilgaz เจ้าสุนัขขี้เรื้อนเสนออภัยโทษให้อดีต Bloodsail ที่ยอมทรยศกัปตัน! เจ้าสวะนั่นให้ข้าไปฆ่าเพื่อนเก่า เอาผ้าโพกหัวมาเป็นหลักฐาน\n\nข้าทำไม่ลง และจะไม่ขอให้เจ้าทำ นำผ้าไหมกับสีย้อมแดงมา ข้าจะทำของเลียนแบบให้เหมือน ข้าจะบอกบารอนว่าเจ้าย้ายข้างแล้ว แต่เตือนไว้...Bloodsail ไม่ชอบแน่!" },
        required = { [4306] = { "10:1269080011:1976271755", "ผ้าไหม" }, [2604] = { "7:376146123:2086085102", "สีย้อมสีแดง" } },
        objectiveLabels = {
            item = { ["Silk Cloth"] = "ผ้าไหม", ["Red Dye"] = "สีย้อมสีแดง" },
        },
    },
    [9272] = { -- Dressing the Part
        title = { "17:1073714357:792208806", "แต่งกายให้สมบทบาท" },
        completion = { "310:130993922:1251965053", "ยาร์ร์...หากอยากอยู่ร่วมกับกะลาสีมากประสบการณ์อย่างเรา ก็เลิกแต่งตัวเหมือนคนชั้นต่ำ! เอ้า ใส่อะไรให้เหมาะก่อนข้าจะลากเจ้าลอดใต้ท้องเรือ\n\nชุดนี้เหมาะกับเจ้ายิ่งกว่าเจ้าหมาแก่ Red-Eyed Ben เสียอีก เราเสียเขาไปในพายุร้ายกลางทะเล\n\nสวมอย่างภูมิใจ สหาย!" },
    },
    [95384] = { -- Partial Mystical Notes
        title = { "22:1695309706:1503432329", "บันทึกเวทมนตร์ที่ไม่ครบถ้วน" },
        objective = { "59:139561675:125664886", "นำม้วนคัมภีร์ที่ไม่ครบถ้วนไปให้ Dudd Fizzlescroll ที่ Booty Bay" },
        description = { "231:1003935064:1713315395", "<สัญลักษณ์ประหลาดบนม้วนคัมภีร์เวททำให้เจ้าฉงน แม้อ่านภาษานั้นไม่ออก เจ้าก็ไม่รู้สึกถึงพลังอันตรายรุนแรงภายใน บางทีนักสะสมเวทแปลก ๆ อาจใช้ประโยชน์จากมันได้>" },
        completion = { "253:7131083:1684111533", "ม้วนคัมภีร์ประหลาดอย่างนั้นหรือ? ใช่เลย นี่มันเวทมนตร์ชั้นยอด ของดีจริง ๆ ขอบใจที่เอามาให้ ข้าตอบแทนที่เจ้าสละเวลาด้วยสิ่งนี้แล้วกัน\nทีนี้ขอลองแปลข้อความยุ่งเหยิงนี่แล้วคัดลงบันทึกของข้าดูก่อน..." },
    },
    [95748] = { -- The Gurubashi Legends of Old
        title = { "28:915269053:1708174840", "ตำนานเก่าแก่ของ Gurubashi" },
        objective = { "79:1492734019:1028139081", "ใช้หนังสัตว์กับถ่านลอกลายศิลาจารึก Third Troll Legend" },
        description = { "220:424649700:41656100 N 277:36910117:1326250862", "แปลกนัก เศษจารึกที่เจ้านำมาบอกถึงเมืองสาบสูญ I'lalai ราวกับเป็นอารยธรรมใหญ่แผ่กว้าง แต่ซากนอกแนวปะการังไม่ใหญ่พอจะเป็นเช่นนั้น\n\n{name} ทางเหนือของ Vile Reef มีซากโทรลล์โบราณบนเนินเลียบชายฝั่ง ภายในมีจารึกตำนานเมืองโทรลล์สาบสูญ ข้าอยากศึกษาตำนานนี้ต่อ\n\nนำหนังกับถ่านนี้ไปลอกลายจารึก แล้วกลับมาหาข้า" },
        completion = { "183:1701388016:38493459", "เยี่ยม นี่แหละที่ข้าต้องการ ข้าเคยอ่านศิลาจารึกแผ่นนี้สมัยยังเป็นโทรลล์หนุ่ม ผ่านมาหลายฤดูจันทร์แล้ว ความจำข้าก็ไม่ดีเหมือนแต่ก่อน" },
        progress = { "126:772438719:1753299331", "พบศิลาจารึกหรือยัง?\nข้าหวังว่าพวก Bloodscalp จะไม่ก่อปัญหาให้เจ้ามากนัก ถ้ามันก่อเรื่อง ข้าก็หวังว่าเจ้าจะฆ่าพวกมันเสีย" },
        required = { [2007] = { "22:117908125:1698887074", "ตำนานโทรลล์เรื่องที่ 3" } },
        steps = { { "22:117908125:1698887074", "ตำนานโทรลล์เรื่องที่ 3" } },
    },
    [95770] = { -- Locating the Lost City
        title = { "22:1242342686:1044085751", "ตามหาเมืองสาบสูญ" },
        objective = { "51:1567763850:1632721134", "สำรวจ Vile Reef แล้วหาทางเข้าถ้ำ" },
        description = { "502:21557493:1875939536", "เมื่ออ่านตำนานอีกครั้ง ดูเหมือนเราไม่ได้หาเมืองสาบสูญผิดที่ แต่อาจยังมองข้ามรายละเอียดบางอย่าง\n\nตอนหนุ่ม ข้าเคยดำน้ำในซาก Vile Reef ก่อนเมอร์ล็อกเข้ามาอยู่ หากจำไม่ผิด มีถ้ำอยู่ที่นั่น\n\nได้ยินว่าตอนนี้นากามารวมตัวในแถบนั้น ผิดปกตินัก ข้าอยากรู้ว่าอะไรล่อมันมา\n\nไปสำรวจทางตะวันตกถัดจาก Vile Reef แล้วกลับมารายงานข่าวที่พบ" },
        completion = { "286:1032092009:1264936155 N 188:1099876624:1214358473", "<Kin'weelay ตั้งใจฟังขณะที่เจ้าเล่าถึงสิ่งที่เห็น>\nเจ้าแน่ใจหรือว่าเห็นพวกนากาเข้าออกซากปรักหักพังในถ้ำนี้? พวกมันกำลังหาอะไรกันนะ?\nหรือมันจะเกี่ยวข้องกับ I'lalai จริง ๆ ถ้าเป็นเช่นนั้น นี่อาจเป็นการค้นพบแห่งศตวรรษเลยนะ {name}! เมืองสาบสูญเป็นเพียงเรื่องเล่าขานมานานเท่าที่โทรลล์คนใดจะจำได้\nแต่ตอนนี้เรื่องเล่านั้นอาจเป็นความจริง เราเสียเวลาไม่ได้แล้ว ต้องไปสืบให้รู้" },
        steps = { { "30:1880437421:841050863", "ตามหาทางเข้า Drowned City" } },
    },
    [95773] = { -- Enemies in the Water
        title = { "20:159147228:446282932", "ศัตรูในผืนน้ำ" },
        objective = { "58:1045756180:929971193", "เก็บ Brinescale Tridents 10 อัน จาก Brinescale Skirmishers", amount = { "7:451016854:1830523975 W1 49:346646924:1013798670", "เก็บ Brinescale Tridents {world1} อัน จาก Brinescale Skirmishers" } },
        description = { "C 414:1921568689:339537491", "{class} เจ้ามาได้เหมาะเวลา ข้าเพิ่งได้รายงานนากาเคลื่อนไหวนอกชายฝั่ง ดูเหมือนมันรุมอยู่รอบซากโทรลล์เก่าใกล้พื้นทะเล\n\nกำลังเราตึงมือจากการป้องกัน Bloodscalp กับออกร์ที่ปล้นกองเกวียนอยู่แล้ว จะปล่อยให้ถูกจู่โจมจากทะเลไม่ได้\n\nไปฆ่าให้มากเท่าที่ทำได้ นำตรีศูลมาเป็นหลักฐานความสำเร็จ" },
        completion = { "80:1993272787:1045565481 C 117:1588419016:57983057", "ทำได้ดี งานที่เจ้าทำที่นี่พิสูจน์ให้ Horde เห็นฝีมือของเจ้าอย่างรวดเร็วเลยนะ {class}\nปักตรีศูลพวกนี้ไว้นอกประตู Grom'gol แล้วทุกคนจะรู้ว่าอย่าคิดมาลองดีกับ Horde" },
        progress = { "114:927477186:1415156636", "ยิ่งข้าได้ข่าวว่าพวกนากามีอาวุธครบมือเท่าไร ข้าก็ยิ่งอยากกำจัดพวกมัน เจ้าจัดการเรื่องนี้หรือยัง?" },
        required = { [270305] = { "18:1226113526:1742502460", "สามง่าม Brinescale" } },
        steps = { { "18:1226113526:1742502460", "สามง่าม Brinescale" } },
    },
    [97047] = { -- The Cook in the Cage
        title = { "20:1796207149:1296040329", "พ่อครัวในกรง" },
        objective = { "93:854180070:219317415", "หากุญแจกรง Wendel และชุดปลอมตัวให้เขาลอบหนี ภายในฐาน Kurzen" },
        description = { "375:28344121:346409632", "เฮ้! เจ้านั่น! ช่วยข้าด้วย! ข้าแค่ออกสำรวจป่า จู่ ๆ ก็ถูกคนบ้าพวกนี้ซุ่มโจมตี! ไม่รู้มันจะทำอะไรข้า แต่ได้ยินเรื่องเสือกับพวกย่อหัว ข้าไม่อยากยุ่งทั้งสองอย่าง!\n\nไม่รู้จะทำอย่างไร แต่เจ้าต้องช่วยข้าออกไป! ได้โปรด! กุญแจกรง ชุดปลอมตัวลอบหนี อะไรก็ได้! อะไรก็ได้จริง ๆ!" },
        completion = { "116:1180484491:543893559", "<สีหน้าของ Wendel พลันคลายความกังวล>\n\nโอ้ ขอบคุณ! ขอบใจเจ้ามาก สหาย! เจ้าช่วยชีวิตข้าไว้จริง ๆ" },
        progress = { "84:27518937:119695396", "<ชายหนุ่มในกรงตื่นตระหนกจนแทบพูดไม่เป็นประโยค>" },
        required = { [216616] = { "17:256264827:1023585382", "กุญแจกรงในค่าย" }, [216617] = { "24:886750062:845637079", "เครื่องแบบนักรบของ Kurzen" } },
        objectiveLabels = {
            item = { ["Compound Cage Key"] = "กุญแจกรงในค่าย", ["Kurzen Fighter's Uniform"] = "เครื่องแบบนักรบของ Kurzen" },
        },
    },
    [97048] = { -- Returning to Port
        title = { "17:485785179:1538779286", "กลับท่าเรือ" },
        objective = { "38:770382506:240289673", "คุยกับ Captain Aransas ที่ Booty Bay" },
        description = { "252:245042743:489924602", "ฟังนะ ตอนนี้ข้ายังตอบแทนไม่ได้ แต่ข้าเป็นพ่อครัวบนเรือ Captain Aransas กลับ Booty Bay เมื่อไร ข้าจะชมเจ้าให้ฟังแน่นอน หากมีโอกาสเจ้าควรคุยกับกัปตัน นางต้องยินดีที่ได้ข้ากลับไปแน่" },
        completion = { "15:1654441212:1320369865 N 379:758744710:901181609", "อ้อ เจ้าคงเป็น {name} สินะ Mathers บอกว่าพวกเจ้าหนีออกจากค่ายของ Kurzen มาด้วยกัน แถมฟันพวกมันหัวหลุดไปหลายคนอีกต่างหาก ยอดโจรสลัดทั้งคู่เลยนี่หว่า!\nฮ่า ๆ ข้ารู้ว่าเขาโม้ทั้งเพ สหาย Mathers เป็นเด็กดี แต่ของมีคมอย่างเดียวที่เขาใช้เป็นก็คือมีดทำครัว\nยังไงก็ขอบใจที่ช่วยลูกเรือของข้าไว้ ในงานแบบนี้ พ่อครัวดี ๆ มีค่าจนตีราคาไม่ได้" },
    },
    [97328] = { -- Anything of Value
        title = { "17:1208715759:1144208619", "อะไรก็ได้ที่มีค่า" },
        objective = { "122:1727625922:1557312869", "นำ Stolen Shipments 8 ชุด กลับจาก Ruins of Zul'Kunda ใน Stranglethorn Vale แล้วส่งของที่ได้ให้ใครสักคนใน Booty Bay", amount = { "8:1749550375:377180055 W1 113:1854557752:548690994", "นำ Stolen Shipments {world1} ชุด กลับจาก Ruins of Zul'Kunda ใน Stranglethorn Vale แล้วส่งของที่ได้ให้ใครสักคนใน Booty Bay" } },
        description = { "412:270828087:589814376", "<ขณะคุ้ยซากจากเหตุเรือเหาะตกอย่างน่าสยดสยองเหนือจุดนี้ เจ้าพบหลักฐานว่ามีเสบียงจำนวนมาก แต่ของมีค่าถูกปล้นไปนานแล้ว แม้ป้ายขนส่งก็ถูกฉีกขาด เหลือเพียงคำว่า “Booty Bay” บนป้ายหนึ่งที่พออ่านได้\n\nรอยเท้าสองนิ้วนับไม่ถ้วนกับรอยพื้นดินบุ๋มหลายแห่งมุ่งไปยังซากปรักหักพังทางตะวันตกเฉียงเหนือ>" },
        completion = { "499:1125889627:441526908", "เจ้าว่าของพวกนี้หล่นจากเรือเหาะที่ตกทางเหนือของป่า แล้วพวกโทรลล์ Bloodscalp เก็บไปงั้นหรือ ของนี่ควรถึง Powderfuse Port ตั้งแต่หกสัปดาห์ก่อน! เราถึงกับตกลงกับ Grom'gol เพื่อใช้หอเรือเหาะส่งของด่วน!\n\nว่าทำไม Whizzbuzz ถึงส่งจดหมายเหน็บแนมมาเรื่อย เราไม่น่าปล่อยให้ Zimmix ขับอีกเลยหลังเรื่องคราวก่อน\n\nดี เยี่ยมจริง ๆ เอานี่ไปแล้วไปเสีย ข้าต้องยื่นเรื่องเคลมประกัน" },
        progress = { "24:1865259034:1905673366", "เจ้าดูงง ๆ นะ หลงทางหรือ?" },
        required = { [277953] = { "15:317346334:2073948539", "สินค้าที่ถูกขโมย" } },
        steps = { { "15:317346334:2073948539", "สินค้าที่ถูกขโมย" } },
    },
    [97329] = { -- Where's the Key?
        title = { "16:151275134:1074321680", "กุญแจอยู่ไหน?" },
        objective = { "120:68398931:1805655490", "นำ Primitive Key ที่ได้จากโทรลล์ใน Ruins of Zul'kunda ใน Stranglethorn Vale ไปให้ Zimmix Sputterspark" },
        description = { "482:1068080071:1161916620", "เจ้า! ใช่ เจ้านั่น! มานี่ เบาเสียงด้วย!\n\nข้าทำพลาดครั้งใหญ่ ข้าตกลงให้ Booty Bay ใช้หอเรือเหาะส่งของด่วนได้อย่างดี แต่เที่ยวแรกข้าเห็นนกยักษ์...เอ่อ ถูกยิงตกทางตะวันออกจากที่นี่ต่างหาก!\n\nน่าเสียดายที่ข้ารอด ก่อนฟื้นก็ถูกหิ้วหูลากมาแล้ว! ตอนนี้ถูกขังในกรง ล้อมด้วยโทรลล์กระหายเลือด!\n\nฟังนะ ข้าต้องการแค่กุญแจ เข้าใจไหม? ข้าหนีเองได้" },
        completion = { "155:1438940387:2089670479", "นั่นกุญแจใช่ไหม\n\n<Zimmix โผเข้าหาซี่กรงด้านหน้าและพยายามคว้ากุญแจจากเจ้าอยู่หลายครั้ง>\n\nส่งมาเสียที!" },
        progress = { "146:1709490936:909865831", "ฟังนะ ข้าชอบเจ้าอยู่หรอก แต่เจ้ายืนแกร่วอยู่ตรงนี้ทำให้เราดูน่าสงสัย! ถ้ายังไม่มีกุญแจล่ะก็ ข้าไม่รู้จะบอกยังไงแล้ว ไปเอามาสิ!\n\nขอร้องล่ะ?" },
        required = { [277957] = { "13:487454271:1516681280", "กุญแจแบบดั้งเดิม" } },
        objectiveLabels = {
            item = { ["Primitive Key"] = "กุญแจแบบดั้งเดิม" },
        },
    },
    [97331] = { -- Zimmix's Great Escape
        title = { "21:1511155805:2089409710", "การหลบหนีครั้งใหญ่ของ Zimmix" },
        objective = { "128:866638291:928317917", "คุ้มกัน Zimmix Sputterspark ออกจาก Ruins of Zul'Kunda แล้วบอก Wharfmaster Lozgil ที่ Booty Bay ว่าช่วยสำเร็จแล้ว" },
        description = { "340:1049074382:1695094619", "เดี๋ยว เดี๋ยว อย่าเพิ่งไป!\n\nข้ารู้ว่าบอกขอแค่กุญแจ แต่...มันเคยจับข้าได้ ก็จับอีกได้ใช่ไหม? ข้าเป็นก็อบลินคนเดียว แถวนี้มีโทรลล์เป็นร้อย!\n\nเจ้าลดจำนวนมันไปมากแล้วเพื่อเอากุญแจ คอยคุ้มกันระหว่างเราเดินออกไปคงง่ายพอ ว่าไหม?" },
        completion = { "491:1497892207:280814839", "คุณพระทองช่วย เจ้านี่เองที่ไปช่วย Zimmix หรือ\n\nเจ้ามาผิดจังหวะที่สุด เราเพิ่งชนแก้วฉลองกันเพราะนึกว่าหลุดพ้นจากเขาเสียที แล้วก็กำลังมีงานส่งของสำคัญที่ยังไม่ได้มอบหมาย แน่นอน เขารีบขอรับงานแล้ว และแน่นอน ข้าต้องค้าน ไม่งั้นคงได้เห็นเขาทำพลาดครั้งใหญ่อีก!\n\nขอแนะนำไว้อย่าง ถ้าเจอก็อบลินติดกรง ส่วนใหญ่ก็สมควรติดแล้ว คราวหน้าปล่อยไว้เถอะ" },
        objectiveLabels = {
            event = { ["Escort Zimmix Sputterspark to safety"] = "คุ้มกัน Zimmix Sputterspark ไปยังที่ปลอดภัย" },
        },
    },
    [97420] = { -- Reduce, Reuse, Reconcile
        title = { "24:39354810:1884446608", "ลด ใช้ซ้ำ และประนีประนอม" },
        objective = { "135:1731080338:2070322415", "หา Drums of Crude Oil 5 ถัง จากกิจการ Venture Co. ที่ Lake Nazferiti แล้วกลับไปหา Knaz Blunderflame ใน Stranglethorn Vale", amount = { "8:1617296333:1647798940 W1 126:1500653567:1668828298", "หา Drums of Crude Oil {world1} ถัง จากกิจการ Venture Co. ที่ Lake Nazferiti แล้วกลับไปหา Knaz Blunderflame ใน Stranglethorn Vale" } },
        description = { "500:355147199:703360519", "ข้ามีเรื่องอยากขอให้ใครช่วย เจ้าดูเป็นคนชอบช่วยเสียด้วย!\n\nเห็นเจ้าหนูนี่ไหม? สวยใช่ไหม? รถแข่งใหม่ล่าสุด ข้าออกแบบสร้างเองทั้งหมด เพราะใครบางคนไม่ยอมช่วย ข้าจะนำไปแข่งที่ Thousand Needles แต่ต้องเพิ่มแรงอีกหน่อย\n\nข้าหล่อเกินเป็นก็อบลิน และรู้ดีว่าไม่ควรไว้ใจเทคโนโลยีพวกนั้น แต่รู้ว่า Venture Co พบทองคำเหลวที่ทะเลสาบ พวกเขาคงไม่ว่าอะไรถ้าเจ้า เอ่อ ขอยืมมาบ้าง? ไม่ทันสังเกตด้วยซ้ำ!" },
        completion = { "344:1996256317:83241466", "โห! นี่เอาไปทำเชื้อเพลิงจรวดส่งข้าไปถึงสนามแข่งได้เลย! เอ่อ จริง ๆ คงไม่ได้หรอก ข้ามมหาสมุทรทั้งลูกแบบนั้นเป็นไปไม่ได้... แต่ถ้าส่งเจ้านี่ข้ามไปถึง Kalimdor ได้ ข้าคงขับต่อจนถึงสนามเองไหว!\nขอบใจนะ สหาย! ข้ามีของตอบแทนไม่มาก แต่ไว้มาแข่งด้วยกันสักครั้งไหม?" },
        progress = { "41:446204082:667861691", "อ้าว สวัสดีอีกครั้ง! หาน้ำมันได้บ้างไหม?" },
        required = { [277986] = { "17:326967449:779310186", "ถังน้ำมันดิบ" } },
        steps = { { "17:326967449:779310186", "ถังน้ำมันดิบ" } },
    },
    [98463] = { -- Talk of the Town
        title = { "16:1638700992:1650176061", "เรื่องเลื่องลือในเมือง" },
        objective = { "80:1160975808:2093163207", "ไปหา Nixxrax Fillamug ที่ Salty Sailor Tavern ใน Booty Bay แถบ Stranglethorn" },
        description = { "434:1053457234:1506828927", "ฟังนะ ข้าดีใจที่เจ้ามาบาร์ข้า และนั่นคือเหตุผลที่บอกเรื่องนี้\n\nงานเลี้ยงตัวจริงหรือ? ต้องที่ Salty Sailor Tavern ใน Booty Bay ใช่ ใน Stranglethorn Vale นั่นแหละ\n\nอย่ามองอย่างนั้น ข้ารู้ว่าก็อบลินดูแลที่นั่น บาร์เทนเดอร์คุยกัน ลูกค้าบาร์ก็คุยมากเสียด้วย ข้าแค่บอกว่าถ้าอยากเห็นความสนุกสุดเหวี่ยง ไปที่นั่น\n\nNixxrax Fillamug จะเติมเครื่องดื่มให้ไม่ขาด ไม่ต้องห่วงเลย" },
        completion = { "150:223573522:1295659748", "ข้ามีของที่เจ้าต้องการ สหาย! อยู่ต่อสักหน่อย ใช้ทองที่หนักกระเป๋าบ้าง แล้วสนุกให้เต็มที่\n\nยินดีต้อนรับสู่ Salty Sailor Tavern!" },
    },
    [9085] = { -- Shadows of Doom
        progress = { "23:249293929:971440504 N 1:63:63", "ได้ผลบ้างไหม {name}?" },
        title = { "15:1040528790:1193185009", "เงาแห่งหายนะ" },
        objective = { "139:604673554:917421664", "ไปที่วงอัญเชิญและสังหาร Shadow of Doom หนึ่งตน แล้วกลับไปรายงาน Commander Thomas Helleran ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { "380:1207625049:472187836", "เมื่อท่านทำลายแนวป้องกันวงอัญเชิญที่ Scourge สร้างขึ้นในพื้นที่ถูกโจมตีแล้ว ท่านจะเผชิญหน้ากับสาวกที่คอยเฝ้าวงเหล่านั้นได้\n\nที่แท้พวกมันคือเงา หนึ่งในสิ่งมีชีวิตที่น่าสะพรึงกลัวที่สุดของ Lich King ใช้รูนเนโครติกที่พวกมันพกอยู่เผยร่างที่แท้จริงออกมา แล้วกำจัดมันด้วยเวทมนตร์หรืออาวุธ" },
        completion = { "16:1549935302:71513149 N 140:1287925499:976724990", "ยอดเยี่ยมมาก {name} เมื่อเงาพวกนั้นถูกทำลายแล้ว อีกไม่นาน Lich King คงเรียกเนโครโพลิสของมันกลับไปและปล่อยให้เราอยู่อย่างสงบ" },
    },
    [9368] = { -- The Festival of Fire
        progress = { "23:249293929:971440504 N 1:63:63", "ได้ผลบ้างไหม {name}?" },
        title = { "20:1742339860:1249584203", "เทศกาลแห่งเปลวไฟ" },
        description = { "469:659790648:1644828921", "เทศกาลกลางฤดูร้อนเวียนมาถึงอีกครั้ง!\n\nตามธรรมเนียม ทุกปีเราจะเลือกผู้ดูแลเปลวไฟมาคอยรักษากองไฟในเมืองหลวงของเรา แม้จะจุดไฟกันทั่วอาเซรอธ แต่ไฟของเราต้องร้อนแรงและสว่างที่สุดจึงจะสมกับการเฉลิมฉลองฤดูกาลนี้\n\nข้ามีเรื่องให้ช่วย ถ้าท่านไม่ขัดข้อง ข้ายังไม่ได้ข่าวว่าไฟในเมืองหลวงทุกแห่งลุกดีหรือเปล่า ไปที่นั่นแล้วผิงไฟดูด้วยตัวเองเถิด ดูให้แน่ใจว่าไฟร้อนจริง ๆ!" },
        completion = { "198:1169259857:1597684608", "ยอดเยี่ยม! ถ้ากองไฟได้รับการดูแลดีอย่างที่ท่านว่า ปีนี้เราคงเลือกผู้ดูแลเปลวไฟได้ขยันขันแข็งทีเดียว ขอบคุณที่ไปตรวจให้ข้า รับสิ่งนี้ไว้แทนคำชื่นชมจากข้าเถิด" },
        objective = { "134:830138225:1369441566", "แตะกองไฟใน Orgrimmar, Thunder Bluff และ Undercity แล้วคุยกับ Festival Talespinner ในเมืองหลวง" },
        steps = { { "18:1525219705:583475251", "เปลวไฟแห่ง Orgrimmar" }, { "22:960397355:636783387", "เปลวไฟแห่ง Thunder Bluff" }, { "22:1272039697:1053188363", "เปลวไฟแห่ง Undercity" } },
    },
    [494] = { -- Time To Strike
        title = { "14:1565229054:1495530555", "ถึงเวลาโจมตี" },
        objective = { "88:1882673778:408461242", "เดินทางไป Tarren Mill เพื่อส่งสารของ Deathstalker Lesh ให้ High Executor Darthalia" },
        description = { "29:2008579314:294110122 C 443:227144033:883772499", "เงียบแล้วฟังให้ดี {class}\n\nข้าถูกส่งมาจุดนี้เพื่อสำรวจเมือง Hillsbrad ภารกิจข้าคือสอดแนม เจ้าต้องส่งข่าวถึง High Executor Darthalia ที่ Tarren Mill ทันที บอกนางว่าข้า Deathstalker Lesh ส่งสารดังนี้\n\n“เสียงกาจากตะวันตกกำลังกู่เรียก”\n\nตามถนนไปตะวันออก คอยดูป้ายให้ดี เร็วเข้า! ไป Tarren Mill เดี๋ยวนี้ เรื่องนี้เร่งด่วนนัก!" },
        completion = { "160:856617412:762103696", "เสียงกาจากตะวันตกกำลังกู่เรียกหรือ?\n\nข่าวดีเยี่ยม! Hillsbrad พร้อมให้โจมตีแล้ว เราดำเนินแผนทำลายล้างได้ Varimathras ต้องพอใจ" },
    },
    [496] = { -- Elixir of Suffering
        title = { "19:1169300206:553134511", "น้ำยาแห่งความทุกข์ทรมาน" },
        objective = { "82:624469902:1943466300", "Apothecary Lydon แห่ง Tarren Mill ต้องการ Gray Bear Tongues 10 อัน และ Creeper Ichor" },
        description = { "92:706003999:858551989 N 398:1628963342:1205151993", "อา อีกวันน่าอนาถใน Tarren Mill อากาศสะอาดทั้งหมดนี่ทำให้ข้าอารมณ์เสียเหลือเกิน {name}\n\nยิ่งแพร่โรคใส่มนุษย์แถวนี้ได้เร็วก็ยิ่งดี ข้าศึกษาสารที่อาจใช้ฆ่าในน้ำยาของข้าอย่างหนัก แต่ไม่มีเวลาเก็บเองทั้งหมด\n\nหากอยากทำตัวให้เป็นประโยชน์ จงหา Gray Bear Tongues 10 อัน และ Creeper Ichor ที่หายากยิ่งมาให้ พบทั้งหมีและCreeperได้ใกล้นอก Tarren Mill" },
        progress = { "126:27210368:2006889537", "กลับมาแล้วสินะ หวังว่าจะเก็บสารที่ข้าต้องการได้ อีกวันที่ไม่มีความตายคงทำให้ข้าหดหู่เหลือเกิน" },
        completion = { "35:81883754:1062454881 N 116:478701267:940933284", "ตัวอย่างสมบูรณ์แบบ {name} เจ้าทำให้ข้าเบิกบานได้เพียงนิดในวันน่าอนาถอีกวัน ข้าซาบซึ้งความพยายามเจ้า" },
        required = { [3476] = { "16:486660342:1907507060", "ลิ้นหมีสีเทา" }, [3477] = { "13:166324982:584373813", "ของเหลวจากตัว Creeper" } },
        steps = { { "16:486660342:1907507060", "ลิ้นหมีสีเทา" }, { "13:166324982:584373813", "ของเหลวจากตัว Creeper" } },
    },
    [498] = { -- The Rescue
        title = { "10:1089564626:692884631", "การช่วยเหลือ" },
        objective = { "78:1833454075:1780267610", "Krusk ที่ Tarren Mill ต้องการให้เจ้าปลดปล่อย Drull และ Tog'thar จาก Durnholde Keep" },
        description = { "492:291423470:322104525", "Warchief ส่งข้ากับนักรบอีกกลุ่มไปนำวัตถุชิ้นหนึ่งจาก Durnholde และสืบเรื่องกลุ่มที่เรียกว่า Syndicate\n\nเราไปสำรวจ Durnholde แต่ถูกมนุษย์จำนวนมากจู่โจม แม้สู้กล้าแค่ไหน จำนวนมหาศาลก็ทำให้เราแพ้ พวกมันจับเราไปบางคน แต่ข้าหนีได้\n\nDurnholde อยู่ทางตะวันออกเฉียงใต้จากที่นี่ ข้ามแม่น้ำไป Drull กับ Tog'thar ถูกขังอยู่ เจ้าต้องไปช่วย" },
        progress = { "21:1191933005:785493330 C 74:1663577585:1988033891", "ต้องรีบแล้ว {class} ข้าขนลุกเมื่อนึกว่ามนุษย์อาจทำอะไรกับ Drull และ Tog'thar" },
        completion = { "287:2145747443:1721716219 N 1:46:46", "มนุษย์คิดจะทำให้นักรบเราเป็นทาสหรือ? เราจะสั่งสอนมัน!\n\nดูเหมือนมันพา Gol'dir หัวหน้าของเราไปอีกแห่ง เราต้องหาและช่วยเขา แต่ตอนนี้ยังไม่มีเบาะแสว่าอยู่ไหน...\n\nเมื่อได้เบาะแส ข้าจะบอกเจ้าแน่ {name}" },
        steps = { { "12:675649773:1149128740", "ช่วย Drull" }, { "15:763268768:2136069906", "ช่วย Tog'thar" } },
    },
    [499] = { -- Elixir of Suffering
        title = { "19:1169300206:553134511", "น้ำยาแห่งความทุกข์ทรมาน" },
        objective = { "34:1807302997:151517563", "มอบ Elixir of Suffering ให้ Umpi" },
        description = { "395:290180651:1825622395", "ข้าใช้เวลาเพียงครู่เดียวผสมส่วนประกอบเป็นสิ่งที่เรียกว่า น้ำยาแห่งความทุกข์ทรมาน\n\nเสร็จแล้ว! อา ไม่มีอะไรทำให้วันหม่นในเชิงเขาน่าอนาถนี้สดใส เท่าการเพิ่มความทุกข์ให้โลกอีกนิด\n\nมาดูว่าน้ำยาเล็ก ๆ นี้ได้ผลตามต้องการไหม\n\nให้ Umpi ผู้ช่วยข้าลิ้มรสสิ่งที่ Dark Lady เตรียมไว้ให้ทั้งมนุษย์และ Scourge" },
        progress = { "7:2037622799:1345230816", "อ๊บ!" },
        completion = { "6:1543380124:867470628", "อ๊บ อ๊บ!" },
        required = { [3495] = { "19:1169300206:553134511", "ยาอายุวัฒนะแห่งความทุกข์ทรมาน" } },
        steps = { { "19:1169300206:553134511", "ยาอายุวัฒนะแห่งความทุกข์ทรมาน" } },
    },
    [500] = { -- Crushridge Bounty
        title = { "17:453476305:1227264294", "ค่าหัว Crushridge" },
        objective = { "120:177538694:1574251847", "เก็บ Dirty Knucklebones 9 ชิ้น จากออกร์ Crushridge ใน Alterac Mountains แล้วนำไปให้ Marshal Redpath ที่ Southshore" },
        description = { "475:1139260014:1523515424", "ออกร์ Crushridge ขุดเนินรังบน Alterac Mountains ใกล้ซากเมือง Alterac หน่วยสอดแนมข้าบอกว่ามันยึดซากเมืองด้วย\n\nปล่อยให้อยู่สบายไม่ได้ หากคิดว่าปลอดภัย ขั้นต่อไปมันจะลงเชิงเขา มาถึงหน้าประตูเรา!\n\nไปเหนือสู่ Alterac Mountains ล่าออกร์ นำ Dirty Knucklebones ที่มันพกมาให้ แล้วเจ้าจะได้ค่าหัวงาม" },
        progress = { "N 77:1607990722:1160518029", "{name} ยังล่าออกร์อยู่หรือ? ได้กระดูกข้อนิ้วที่ข้าให้เก็บหรือยัง?" },
        completion = { "11:1776810664:1873330125 N 145:1333385870:641824745", "ดีมาก {name} กว่าจะได้กระดูกทั้งหมดนี้ เจ้าคงฝ่าออกร์มามาก\n\nน่าจะทำให้มันเลิกกวนเรา อย่างน้อยก็พักหนึ่ง" },
        required = { [2843] = { "18:550449500:1870835091", "กระดูกข้อนิ้วเปื้อนดิน" } },
        steps = { { "18:550449500:1870835091", "กระดูกข้อนิ้วเปื้อนดิน" } },
    },
    [501] = { -- Elixir of Pain
        title = { "14:67291862:2110817422", "น้ำยาแห่งความเจ็บปวด" },
        objective = { "73:37731789:2144997597", "นำ Mountain Lion Blood 10 ขวด ไปให้ Apothecary Lydon ที่ Tarren Mill" },
        description = { "4:1347873283:179389729 N 493:618220463:564934718", "โอ้ {name}...ดอกไม้บานใน Hillsbrad อากาศสดชื่นกระปรี้กระเปร่า ข้าจมอยู่กับความทุกข์เสียจริง มองผ่านหน้าต่างสกปรกแล้วโหยหาวันที่โรคระบาดใหม่ของเรานำความตายอันสมควรมาสู่โลก\n\nแม้อยากนั่งหม่นหมองทั้งวัน หน้าที่ต่อ Dark Lady ก็เรียกหา ช่วยข้าหน่อยได้ไหม? งานวิจัยทำให้เชื่อว่าเลือด Mountain Lion จะปรุงยามรณะชั้นเลิศได้ นำมาแล้วเราจะสนุกกันสักนิด" },
        progress = { "16:688892677:887703717 N 167:351465081:1111552496", "ข้าจำเจ้าได้ {name} เจ้าอาสาช่วยปรุงน้ำยาล่าสุด ข้าต้องได้เลือดก่อน จึงจะนำความทุกข์แบบพิเศษของข้าไปให้ชาว Hillsbrad" },
        completion = { "19:192782172:1277747692 N 1:46:46", "เก็บได้ยอดเยี่ยม {name}" },
        required = { [3496] = { "19:812604205:300705678", "เลือดสิงโตภูเขา" } },
        steps = { { "19:812604205:300705678", "เลือดสิงโตภูเขา" } },
    },
    [502] = { -- Elixir of Pain
        title = { "14:67291862:2110817422", "น้ำยาแห่งความเจ็บปวด" },
        objective = { "35:1789708162:437622959", "ป้อน Elixir of Pain ให้ Stanley" },
        description = { "499:1797669866:640561124", "อา ไม่มีกลิ่นใดเท่าเลือดสดบนเชิงเขา!\n\nเติมนี่นิด นั่นหน่อย แล้วเริ่มความสนุกจริง ๆ! สิ่งที่ข้าสร้างจากเลือดนี้เรียกว่าน้ำยาแห่งความเจ็บปวด หากคำนวณถูก มันอาจเป็นจุดเริ่มสิ่งงดงามยิ่งสำหรับ Lady Sylvanas แต่ต้องทดลองก่อน\n\nนำไปฟาร์มทางเหนือใน Hillsbrad Fields ทางตะวันตกเฉียงใต้ มาดูว่า Stanley สุนัขน้อยของ Farmer Ray ชอบ “ขนม” นี้ไหม" },
        progress = { "5:1321856907:103145976", "โฮ่ง?" },
        completion = { "78:1039048674:2133746827", "เจ้าเทน้ำยาลงมือเล็กน้อยแล้วยื่นไปตรงปาก Stanley" },
        required = { [3497] = { "14:67291862:2110817422", "ยาอายุวัฒนะแห่งความเจ็บปวด" } },
        steps = { { "14:67291862:2110817422", "ยาอายุวัฒนะแห่งความเจ็บปวด" } },
    },
    [503] = { -- Gol'dir
        title = { "7:1165585695:422844669", "Gol'dir" },
        objective = { "49:1084585633:592537893", "ปลดปล่อย Gol'dir แล้วกลับไปหา Krusk ที่ Tarren Mill" },
        description = { "208:734041137:1209039180", "จากเอกสารที่เจ้าหามา เท่าที่ข้าดูออก Gol'dir ถูกขังในฐานใหญ่ของ Syndicate ทางเหนือ น่าจะใน Alterac Mountains เขาถูกขังนานเกินไปแล้ว ต้องช่วยให้เป็นอิสระ" },
        progress = { "17:2146987903:2050097632 C 30:7303173:1362136700", "ส่งกุญแจมา {class} ข้าจะไขเอง" },
        completion = { "11:1191658970:1224418299 N 339:1041320096:1766142008", "ขอบคุณ {name} ข้านำคณะมาจาก Durotar ตามคำสั่ง Warchief แต่อย่างที่เห็น แผนผิดพลาดไปไม่น้อย มันจับขังข้าในเมืองนี้ บังคับทำงาน ขนของหนัก ขุดดิน...\n\nแต่ความทุกข์ข้าไม่สำคัญ มีข้อมูลสำคัญที่เจ้าต้องส่งให้ผู้ที่นำกลุ่มเราอยู่ตอนนี้" },
        required = { [3704] = { "15:88250537:2047411268", "กุญแจเหล็กขึ้นสนิม" } },
        steps = { { "15:88250537:2047411268", "กุญแจเหล็กขึ้นสนิม" } },
        objectiveLabels = {
            event = { ["Find where Gol'dir is being held"] = "หาที่คุมขัง Gol'dir" },
        },
    },
    [504] = { -- Crushridge Warmongers
        title = { "21:565575393:267303284", "พวกกระหายศึก Crushridge" },
        objective = { "76:197545898:190682421", "ฆ่า Crushridge Warmongers 15 ตัว แล้วกลับไปหา Marshal Redpath ที่ Southshore" },
        description = { "303:586899303:1419758591", "เมื่อเจ้าได้ลองสู้กับออกร์ Crushridge แล้ว ข้าอยากให้สั่งสอนมันอย่างหนักจริง ๆ...\n\nเข้า Ruins of Alterac ตามหา Crushridge Warmongers ฆ่ามาให้มาก นั่นเป็นวิธีเดียวที่เจ้าสัตว์ถึกพวกนั้นจะเรียนรู้ให้อยู่ห่างเขต Alliance" },
        progress = { "34:1289214388:790623942 N 88:188357596:1570008733", "ยังมี Warmongers ให้เจ้าฆ่าอีก {name} เจ้าควรทำงานบนภูเขา ไม่ใช่เก็บอาวุธมาอยู่ข้างล่างนี่" },
        completion = { "245:1901396383:1827305967", "ดีมาก นี่รางวัลเจ้า\n\nตอนล่าพวก Warmongers เมือง Alterac เป็นอย่างไร? ข้าเดาว่าคงแย่ ออกร์ไม่ได้ขึ้นชื่อเรื่องสะอาด\n\nโชคดีที่ความพยายามเจ้าช่วยกันมันห่าง Southshore" },
        objectiveLabels = {
            monster = { ["Crushridge Warmonger slain"] = "ปราบ นักก่อสงคราม Crushridge" },
        },
    },
    [505] = { -- Syndicate Assassins
        title = { "19:1691308853:1630945997", "มือสังหาร Syndicate" },
        objective = { "104:1642203519:1224452644", "ฆ่า Syndicate Footpads 12 คน และ Syndicate Thieves 8 คน แล้วกลับไปหา Magistrate Henry Maleb ที่ Southshore" },
        description = { "455:1260688806:2133276639", "ข้าเป็นผู้ปกครองคนใหม่ของ Southshore เพิ่งรับแต่งตั้งหลังคนก่อนถูกลอบสังหาร ยังหามือสังหารไม่พบ แต่จากการสืบสวน เราเกือบมั่นใจว่า Syndicate จ้างมา เป็นกลุ่มโจรที่นำโดยขุนนางชั่วจากอาณาจักร Alterac ที่ล่มสลาย\n\nSyndicate ตั้งค่ายทางเหนือของ Tarren Mill ซึ่ง Horde ยึดอยู่ เบาะแสล่าสุดชี้ไปค่ายนั้น จงฆ่าสมาชิก Syndicate ที่พบ" },
        progress = { "46:1598788521:1702885682", "ข้าเชื่อว่าเจ้าฆ่าอันธพาล Syndicate แล้วใช่ไหม?" },
        completion = { "11:1191658970:1224418299 N 283:870671218:1378239193", "ขอบคุณ {name} แม้อาจยังมีพวกมันซ่อนอยู่ เราหวังว่าในโจรและนักฉกชิงที่เจ้าฆ่าจะมีผู้รับผิดชอบความตายของผู้ปกครองคนก่อน แต่แม้ไม่ใช่ Syndicate ก็เป็นมลทินบนแผ่นดินและเผ่าพันธุ์มนุษย์\n\nSouthshore ยินดีกับความตายพวกมัน" },
        objectiveLabels = {
            monster = { ["Syndicate Thief slain"] = "ปราบ ขโมย Syndicate", ["Syndicate Footpad slain"] = "ปราบ โจรตามทาง Syndicate" },
        },
    },
    [506] = { -- Blackmoore's Legacy
        title = { "19:360078606:1159121252", "มรดกของ Blackmoore" },
        objective = { "67:1355100784:1651063101", "นำข้อมูลที่ Gol'dir รวบรวมไปให้ Krusk ที่ Tarren Mill" },
        description = { "489:71455082:1034974669", "วันหรือสองวันก่อน หัวหน้า Syndicate มาเยี่ยม เขาชื่อ Aliden Perenolde เรียกตนว่าเจ้าแห่งแผ่นดินนี้ เขาบอกแผนจับออร์คที่ต่อต้านเป็นทาส เช่นที่พ่อกับ Blackmoore ผู้เป็นอาจารย์อันน่าชังเคยวางไว้\n\nที่สำคัญกว่า เขาพาคนรักชื่อ Elysa เด็กสาวร่างบอบบางมาด้วย รอบคอนางมีจี้ที่ Warchief ต้องการ\n\nไปเถิด ข้าจะหาทางกลับเอง หลังจัดการธุระที่นี่แล้ว" },
        completion = { "268:1371589101:842159392", "มนุษย์อวดดีช่างกล้า! เราจะแสดงให้นายรู้ว่าออร์คไม่มีวันยอมจำนนต่อมัน!\n\nนอกจากนำเครื่องประดับที่ Warchief ต้องการคืนแล้ว นี่จะเป็นภารกิจของเราด้วย ดูเหมือนทำอย่างหนึ่งสำเร็จ ก็จะสำเร็จอีกอย่างพร้อมกัน" },
    },
    [507] = { -- Lord Aliden Perenolde
        title = { "21:1720792308:1204437648", "Lord Aliden Perenolde" },
        objective = { "80:1419156266:1956757669", "ฆ่า Lord Aliden Perenolde แล้วถาม Elysa คนรักของเขาเรื่องจี้ของ Taretha" },
        description = { "171:691907428:856675514 N 71:24058112:1698177559", "ชัดเจนว่า Perenolde ต้องตาย ความชั่วเขาต้องถูกลบจากโลก คฤหาสน์อยู่ขึ้นเหนือไปริม Lordamere Lake ทำหน้าที่เจ้า {name} จากนั้นเอาจี้ที่ Warchief ต้องการแล้วกลับมาที่นี่" },
        progress = { "19:1675326231:1314337759", "จะ...เจ้าต้องการอะไร?" },
        completion = { "113:612895322:681418070", "ไม่ อย่าทำร้ายข้าเลย! ข้าไม่เคยคิดร้ายต่อคนของเจ้า เขาบังคับข้าไว้! ได้โปรด...ไว้ชีวิตข้า!" },
        objectiveLabels = {
            monster = { ["Lord Aliden Perenolde slain"] = "ปราบ ลอร์ด Aliden Perenolde" },
        },
    },
    [508] = { -- Taretha's Gift
        title = { "14:1613824304:1509442912", "ของขวัญจาก Taretha" },
        objective = { "49:966813027:732526447", "นำจี้ของ Taretha คืนให้ Krusk ที่ Tarren Mill" },
        description = { "115:691981063:297218353", "จี้หรือ? เอาไปได้เลย...เอาไป! ข้าไม่อยากเหลืออะไรให้ระลึกถึงเขา...แค่ได้โปรด ออกไปอย่างสงบ..." },
        progress = { "17:1659610970:2055106361 N 20:1547832595:1286819076", "กลับมาแล้ว {name} มีข่าวความสำเร็จหรือ?" },
        completion = { "172:1582024008:1356308329 N 61:982404045:1452303964", "แปลกที่ Warchief ทุ่มเทมากมายเพื่อของเล็กน้อย ข้าไม่อ้างว่าเข้าใจเขา แต่จะทำตามไม่ว่าคำสั่งใด เจ้าทำได้ดี {name} Warchief ต้องยินดีกับข่าวความสำเร็จแน่" },
        required = { [3498] = { "18:230888121:1789134662", "สร้อยคอของ Taretha" } },
        steps = { { "18:230888121:1789134662", "สร้อยคอของ Taretha" } },
    },
    [509] = { -- Elixir of Agony
        title = { "15:1351320373:1530237846", "น้ำยาแห่งความทรมานแสนสาหัส" },
        objective = { "61:1825176183:1143406729", "นำ Mudsnout Blossoms 6 ดอก ไปให้ Apothecary Lydon ที่ Tarren Mill" },
        description = { "333:772445646:867009610 N 161:1701672989:504264608", "อีกวัน อีกน้ำยาที่ต้องปรุง ถ้าเป็นข้า จะปล่อยมนุษย์น่าสมเพชกับ Scourge สู้กันเอง ดูมันก็ตั้งใจฆ่ากันอยู่แล้ว\n\nแต่ Dark Lady อยากเร่งให้เร็วอีกนิด ทำไมไม่ฆ่าเวลาวันหม่นด้วยการแพร่ความตายและโรคทั่วแผ่นดินล่ะ?\n\nแผนคือ {name} เจ้าไป Nethander Stead ใต้ Tarren Mill ทางตะวันออกของแม่น้ำและ Southshore เก็บ Mudsnout Blossoms จากทุ่งมา 6 ดอก สำหรับน้ำยาถัดไป" },
        progress = { "28:2143042301:524343962", "ได้ผลที่ Nethander Stead ไหม?" },
        completion = { "96:2122922612:328536915", "อา กลิ่นเหม็นร้ายกาจของ Mudsnout Blossoms อย่างน้อยโนลล์สกปรกพวกนั้นก็มีประโยชน์บ้าง" },
        required = { [3502] = { "17:1953107080:61190747", "ดอก Mudsnout" } },
        steps = { { "17:1953107080:61190747", "ดอก Mudsnout" } },
    },
    [510] = { -- Foreboding Plans
        title = { "16:304935454:2115109870", "แผนการน่าหวั่นใจ" },
        objective = { "61:66526193:149902834", "นำ Foreboding Plans ไปให้ Magistrate Maleb ที่ Southshore" },
        description = { "349:150263468:854483911", "ในเอกสารมีรายการขอเสบียง ทั้งของธรรมดาอย่างอาหาร อาวุธ เสื้อผ้า และอุปกรณ์พิเศษอย่างหน้ากาก น้ำมัน ยาพิษ\n\nแต่ที่น่าสังเกตที่สุดคือความเร่งด่วน ต้องได้เสบียงเร็วเพื่อทำสิ่งที่เอกสารเรียกว่า “ภารกิจสำคัญต่อ Southshore”" },
        progress = { "N 59:2069889089:1909280730", "{name} เจ้าดูกังวล มีอะไรอยากบอกข้าหรือ?" },
        completion = { "55:1635442784:465424686 N 156:2145406045:414277695", "<Maleb อ่านเอกสาร>\n\nน่ากังวลมาก {name} จากข้อมูลในเอกสารกับการกระทำของ Syndicate ที่ผ่านมา เราต้องถือว่ากลุ่มนักฆ่านี้ทำสงครามกับ Southshore แล้ว" },
        required = { [3718] = { "16:304935454:2115109870", "แผนการที่เป็นลางร้าย" } },
        steps = { { "16:304935454:2115109870", "แผนการที่เป็นลางร้าย" } },
    },
    [511] = { -- Encrypted Letter
        title = { "16:71494942:1416341860", "จดหมายเข้ารหัส" },
        objective = { "61:1880447109:392080182", "นำ Encrypted Letter ไปให้ Loremaster Dibbs ที่ Southshore" },
        description = { "62:452809248:253037469", "จดหมายฉบับหนึ่งบนโต๊ะนี้เข้ารหัสจนอ่านไม่รู้เรื่อง" },
        progress = { { "44:1867738662:1800706748", "46:1657845036:56821078" }, "มีอะไรหรือ? มีธุระกับข้าหรือ?" },
        completion = { "187:1654797643:643215034", "อะไรนี่? รอครู่...ข้าขอดูใกล้ ๆ\n\n...\n\nอืม ไม่เคยเห็นรหัสแบบนี้มาก่อน แต่ต้องยอมรับว่าข้าไม่ได้รู้เรื่องนี้อย่างครบถ้วน" },
        required = { [3521] = { "25:651396810:2139280170", "จดหมายที่เข้ารหัสอย่างแนบเนียน" } },
        steps = { { "25:651396810:2139280170", "จดหมายที่เข้ารหัสอย่างแนบเนียน" } },
    },
    [512] = { -- Noble Deaths
        title = { "12:170399399:1206853714", "มรณกรรมขุนนาง" },
        objective = { "63:17006322:188644236", "นำ Alterac Signet Rings 7 วง ไปให้ Magistrate Maleb ที่ Southshore" },
        description = { "480:576893957:1806839296", "ข้ากลัวว่าผู้นำ Syndicate มุ่งทำลาย Southshore เราต้องโจมตีผู้นำให้หนักก่อนแผนมันเป็นจริง\n\nเข้าสู่ซาก Strahnbrad ใน Alterac Mountains ทางเหนือ เราคิดว่า Syndicate ใช้เป็นกองบัญชาการ\n\nรู้ว่ากลุ่มนักฆ่านี้นำโดยอดีตขุนนาง Alterac พวกมันอาจแฝงเป็นสมาชิกธรรมดา แต่เจ้าจะรู้ว่าฆ่าขุนนางได้จากแหวนตราที่สวม\n\nนำแหวนตราเหล่านั้นมาให้ข้า" },
        progress = { "61:1931624591:239455287", "ไปล่า Syndicate มาไหม? มีแหวนหรือยัง?" },
        completion = { "165:68549380:660450087 N 1:46:46", "กำจัดขุนนางจาก Syndicate จะทำลายความสามารถตัดสินใจอย่างเด็ดขาด เหลือเป็นแค่กลุ่มอันธพาล\n\nเจ้ารับใช้ Alliance ได้ดี {name}" },
        required = { [3505] = { "19:1895625297:1421172986", "แหวนตรา Alterac" } },
        steps = { { "19:1895625297:1421172986", "แหวนตรา Alterac" } },
    },
    [513] = { -- Elixir of Agony
        title = { "15:1351320373:1530237846", "น้ำยาแห่งความทรมานแสนสาหัส" },
        objective = { "75:2077715793:1663710960", "นำ Mudsnout Composite ไปให้ Master Apothecary Faranell ที่ Undercity" },
        description = { "393:968293738:833435367 N 1:46:46", "ข้านึกว่าจะผ่านอีกวันโดยไร้ความสุข แต่เจ้านำ Mudsnout Blossoms วิเศษเหล่านั้นมา\n\nก่อนอื่นข้าจะผสมให้เป็นเนื้อเดียว จากนั้นต้องให้ Master Apothecary Faranell ที่ Undercity เติมคอลลอยด์แห่งความเสื่อมสลาย แล้วเราจะพร้อมสนุกจริง ๆ!\n\nนี่ นำ Mudsnout Composite ไปให้อาจารย์ Faranell ทันที {name}" },
        progress = { "27:1690188195:1147743011 C 214:1956668966:1586291823", "ไม่เห็นหรือว่าข้ายุ่ง {class}? Dark Lady ยืนกรานให้มีโรคระบาดใหม่ก่อน Scourge จาก Northrend จะถาโถมใส่เรา และเมื่อภัยมนุษย์บีบมาจากใต้ เวลาจึงมีค่าที่สุด หวังว่าจะสำคัญจริง!" },
        completion = { "364:1829453777:108570728", "Apothecary Lydon ส่งเจ้าหรือ? อา ทำไมไม่บอก!\n\nแม้อารมณ์หม่น Apothecary Lydon เป็นสมาชิกที่ทุ่มเทและมีฝีมือที่สุดคนหนึ่งของเรา\n\nสหายดีส่ง Mudsnout Composite มา! รู้แล้วว่าเพื่อนที่ Hillsbrad กำลังทำอะไร ข้าชอบวิธีคิดเขา Dark Lady ต้องประทับใจความคืบหน้าสู่โรคระบาดใหม่แน่" },
        required = { [3506] = { "18:1139039699:1781767785", "สารผสม Mudsnout" } },
        steps = { { "18:1139039699:1781767785", "สารผสม Mudsnout" } },
    },
    [514] = { -- Letter to Stormpike
        title = { "19:159626990:1332753357", "จดหมายถึง Stormpike" },
        objective = { "72:1111689937:1681450231", "นำ Cleverly Encrypted Letter ไปให้ Prospector Stormpike ที่ Ironforge" },
        description = { "286:226163240:1303796136", "ข้ามีสหายที่ Ironforge อาจช่วยถอดรหัสได้ ไปห้องสมุดใน Hall of Explorers ของ Ironforge คุยกับ Prospector Stormpike บอกว่าข้าส่งมาแล้วให้ดูจดหมาย หากมีใครทางเหนือ Blackrock Spire อ่านได้ ก็คือเขา" },
        progress = { "70:1223450756:1155220244", "Dibbs จาก Southshore ส่งมาหรือ? เจ้าหนอนหนังสือแก่เป็นอย่างไรบ้าง?" },
        completion = { "55:734842172:303315854", "อา รหัสลับ! ของถนัดข้า ขอดูหน่อย..." },
        required = { [3521] = { "25:651396810:2139280170", "จดหมายที่เข้ารหัสอย่างแนบเนียน" } },
        steps = { { "25:651396810:2139280170", "จดหมายที่เข้ารหัสอย่างแนบเนียน" } },
    },
    [515] = { -- Elixir of Agony
        title = { "15:1351320373:1530237846", "น้ำยาแห่งความทรมานแสนสาหัส" },
        objective = { "135:2133147445:349085607", "นำ Mudsnout Mixture, Strong Troll's Blood Potion, Daggerspine Scales 5 ชิ้น และ Torn Fin Eyes 5 ดวง ไปให้ Apothecary Lydon ที่ Tarren Mill", variants = { { "135:1466064256:506484793", "นำ Mudsnout Mixture, Strong Troll's Blood Elixir, Daggerspine Scales 5 ชิ้น และ Torn Fin Eyes 5 ดวง ไปให้ Apothecary Lydon ที่ Tarren Mill" } } },
        description = { "472:857201828:857763313", "ส่วนผสม mudsnout หรือ? ฉลาดจริง! ทำไมข้าคิดไม่ถึง?\n\nให้ข้าเติมคอลลอยด์แห่งความเสื่อมสลายลงยาร้ายนี้\n\nเพื่อกระตุ้นสารปนเปื้อนในส่วนผสม Lydon ต้องใช้ strong troll's blood potion พร้อมเกล็ด daggerspine กับดวงตา torn fin จากชายฝั่งใต้ Hillsbrad เมื่อเจ้าเก็บส่วนประกอบครบ เขาจะรู้ว่าต้องทำอะไร ข้ารอฟังผลทดลองแทบไม่ไหว!", variants = { { "472:1084810042:1600814437", "ส่วนผสม mudsnout หรือ? ฉลาดจริง! ทำไมข้าคิดไม่ถึง?\n\nให้ข้าเติมคอลลอยด์แห่งความเสื่อมสลายลงยาร้ายนี้\n\nเพื่อกระตุ้นสารปนเปื้อนในส่วนผสม Lydon ต้องใช้ strong troll's blood elixir พร้อมเกล็ด daggerspine กับดวงตา torn fin จากชายฝั่งใต้ Hillsbrad เมื่อเจ้าเก็บส่วนประกอบครบ เขาจะรู้ว่าต้องทำอะไร ข้ารอฟังผลทดลองแทบไม่ไหว!" } } },
        progress = { "25:2117943842:296587184 N 262:1059446151:1897614616", "ดีใจที่เจ้ากลับมา {name} ข้าเบื่ออย่างร้ายกาจ ไม่มีอะไรสนุกนอกจากวางยา แพร่โรคใส่ Umpi แล้วชุบชีวิตนาง...ซ้ำแล้วซ้ำเล่า\n\nไป Undercity เป็นอย่างไร? โชคดีได้ฆ่ามนุษย์ระหว่างทางบ้างไหม?" },
        completion = { "89:282429272:372428692 N 57:958424708:1865214876", "ข้าตื่นเต้นกับการทดลองจนเคลิบเคลิ้ม! เจ้าช่วยมากจริง {name} เราจะแพร่ความตายและโรคสู่แผ่นดินด้วยกัน!" },
        required = { [3508] = { "16:1666045285:1211575551", "สารผสม Mudsnout" }, [3388] = { "27:1270828162:411344351", "ยาอายุวัฒนะเลือดโทรลล์ระดับต้น" }, [3509] = { "17:763662988:1312216450", "เกล็ด Daggerspine" }, [3510] = { "12:997809083:1058653969", "ดวงตาของ Torn Fin" } },
        steps = { { "16:1666045285:1211575551", "สารผสม Mudsnout" }, { "27:1270828162:411344351", "ยาอายุวัฒนะเลือดโทรลล์ระดับต้น" }, { "17:763662988:1312216450", "เกล็ด Daggerspine" }, { "12:997809083:1058653969", "ดวงตาของ Torn Fin" } },
    },
    [517] = { -- Elixir of Agony
        title = { "15:1351320373:1530237846", "น้ำยาแห่งความทรมานแสนสาหัส" },
        objective = { "67:87556266:182555748", "นำ Shindigger Stout หนึ่งถัง ไปให้ Apothecary Lydon ที่ Tarren Mill" },
        description = { "391:968963045:361592685 N 1:46:46", "น้ำยาใหม่พร้อมทดลองแล้ว แต่จะเสียโรคระบาดชั้นดีที่ติดต่อรุนแรงกับแค่กบหรือหมาทำไม? มาสนุกจริงในนาม Lady Sylvanas\n\nไป Dun Garok เจ้ารู้จักค่ายทหารที่คนแคระสกปรกวิ่งกันให้วุ่น ขโมย Shindigger Stout มาถังหนึ่ง เมื่อได้ถัง เจ้าและข้าจะมีงานเลี้ยงกัน {name}" },
        progress = { "333:1819458765:1167824442", "บางทีข้าเบื่อ Tarren Mill จนเปิดโหลฟอร์มาลดีไฮด์ ปล่อยกลิ่นหอมลอยทั่วอากาศ แต่ทำให้ Umpi ประหม่านิดหน่อย\n\nขโมยถังจากคนแคระได้ไหม? สาบานว่าหากต้องมองน้ำยามรณะอีกวันโดยไม่ได้ใช้กับใคร ข้าจะกรีดร้อง" },
        completion = { "37:1348193327:2084298063", "ในที่สุด! พร้อมลงมือแล้ว!" },
        required = { [3517] = { "23:741611049:823681404", "เบียร์ดำ Shindigger หนึ่งถัง" } },
        steps = { { "23:741611049:823681404", "เบียร์ดำ Shindigger หนึ่งถัง" } },
    },
    [518] = { -- The Crown of Will
        title = { "17:1633416585:710073109", "มงกุฎแห่งเจตจำนง" },
        objective = { "55:1373415856:2137653229", "ฆ่า Crushridge Maulers 10 ตัว ให้ Melisara ที่ Tarren Mill", variants = { { "55:136668695:622838134", "ฆ่า Crushridge Maulers 14 ตัว ให้ Melisara ที่ Tarren Mill" } } },
        description = { "234:55562884:1361755054", "Mug'Thol กับออกร์ Crushridge ยึดซาก Alterac แล้ว จะลงโทษมันหนัก ๆ ได้ยากหากไม่ลดจำนวนออกร์ก่อน\n\nเมื่อทำให้อ่อนกำลัง เราจะเดินหน้าต่อ\n\nเข้าใจไหม? ดี ไปได้" },
        progress = { "37:462792449:1652176549 N 47:976874066:1917923737", "ข้าเห็นว่างานเจ้ายังไม่เสร็จ {name} ต้องรายงานความไร้ฝีมือเจ้าให้ Sharlindra ไหม?" },
        completion = { "180:681319891:798556727", "หิมะแดงฉานด้วยเลือดออกร์ แต่เราจะไม่หยุดจนกว่าทั้งขวัญและจำนวน Crushridge จะถูกบดขยี้จมดินกับหิมะ" },
        objectiveLabels = {
            monster = { ["Crushridge Mauler slain"] = "ปราบ นักตะปบ Crushridge" },
        },
    },
    [519] = { -- The Crown of Will
        title = { "17:1633416585:710073109", "มงกุฎแห่งเจตจำนง" },
        objective = { "82:252462572:865403800", "ฆ่า Targ, Muckrake และ Glommus แล้วนำหัวไปให้ Melisara ที่ Tarren Mill" },
        description = { "152:1300101123:556806915 N 76:1895938384:1173532554", "Targ, Muckrake และ Glommus เป็นนายกอง Mug'Thol พวกมันภักดี แม้ใครจะรู้ว่าอะไรทำให้ออกร์ภักดีได้\n\nนำหัวมา {name} แล้วจะเหลือเพียงตัดหัว Mug'Thol พร้อมมงกุฎ" },
        progress = { "20:1350865602:949308973 N 14:77171732:110910050", "ข้าต้องการหัวพวกมัน {name} ไม่ใช่ข้อแก้ตัว" },
        completion = { "220:97794556:690192199", "...ข้านึกว่าออกร์เป็น ๆ ก็เหม็นพอแล้ว\n\nเมื่อเจ้านำหัว Mug'Thol มา ข้าจะเสียบทั้งสี่หัวบนหอกเหนือ Alterac เป็นอนุสรณ์ที่เหมาะแก่ผู้ขัดเจตนา Dark Lady" },
        required = { [3550] = { "11:640441127:48228505", "ศีรษะของ Targ" }, [3551] = { "15:286012826:898011634", "ศีรษะของ Muckrake" }, [3552] = { "14:1251712391:771173277", "ศีรษะของ Glommus" } },
        steps = { { "11:640441127:48228505", "ศีรษะของ Targ" }, { "15:286012826:898011634", "ศีรษะของ Muckrake" }, { "14:1251712391:771173277", "ศีรษะของ Glommus" } },
    },
    [520] = { -- The Crown of Will
        title = { "17:1633416585:710073109", "มงกุฎแห่งเจตจำนง" },
        objective = { "85:1432892893:2024870478", "ฆ่า Mug'Thol แล้วนำหัวพร้อม Crown of Will กลับไปให้ Melisara ที่ Tarren Mill" },
        description = { "330:1900163421:1712257811", "เมื่อเหล่านายกองตาย เหลือเพียงฆ่า Mug'Thol นำ Crown of Will คืน มันคงไม่เต็มใจยกให้ และน่าจะรอเจ้าอยู่ด้วย เมื่อสหายมัน...จากไป...แล้ว\n\nหา Mug'Thol เอาหัวกับมงกุฎมาให้ข้า การต่อต้านของ Crushridge จะจบลง" },
        progress = { "81:1750212069:149349485 N 17:879847021:1914568007", "ข้ามีสามหัวแล้ว ต้องการหัวที่สี่ จะเป็นของ Mug'Thol หรือของเจ้า {name} ข้าสัญญา" },
        completion = { "30:657793623:2061746721 N 149:370765057:1371980724", "เจ้าทำหน้าที่ได้ดี {name} หัว Mug'Thol จะประดับยอดสูงสุดของซาก Alterac และ Deathguard จะกวาดล้าง Crushridge ที่เหลือลงดิน" },
        required = { [3553] = { "15:551338658:1144156418", "ศีรษะของ Mug'thol" }, [3554] = { "13:1896353971:754887809", "มงกุฎแห่งเจตจำนง" } },
        steps = { { "15:551338658:1144156418", "ศีรษะของ Mug'thol" }, { "13:1896353971:754887809", "มงกุฎแห่งเจตจำนง" } },
    },
    [521] = { -- The Crown of Will
        title = { "17:1633416585:710073109", "มงกุฎแห่งเจตจำนง" },
        objective = { "57:2054441812:138104640", "ส่ง Crown of Will ให้ Sharlindra ที่ Undercity" },
        description = { "200:1597560575:385374296 N 48:1931691099:424215255", "เหลือเพียงส่ง Crown of Will ให้ Sharlindra ที่ Undercity นางจะนำต่อให้ Lady Sylvanas ข้าเตือนว่าอย่าคิดใช้เพื่อตนเอง {name} ชะตา Mug'Thol คงเป็นตัวอย่างเพียงพอแล้ว" },
        progress = { "37:1596171747:1136153279", "ว่าอย่างไร? มีอะไรรายงานหรือ?" },
        completion = { "189:554583469:801242302 N 91:1974466250:322413646", "นี่สินะวัตถุที่ออกร์ใช้หลบอำนาจ Dark Lady...\n\nแปลกที่ของเรียบง่ายมีพลังมากมาย และตกในมือเงอะงะเช่นนั้น ทำได้ดี {name} ข้าจะส่งมงกุฎให้ Lady Sylvanas และให้นางได้ยินผลงานเจ้า" },
        required = { [3554] = { "13:1896353971:754887809", "มงกุฎแห่งเจตจำนง" } },
        steps = { { "13:1896353971:754887809", "มงกุฎแห่งเจตจำนง" } },
    },
    [522] = { -- Assassin's Contract
        title = { "19:1163303718:605259070", "สัญญาว่าจ้างมือสังหาร" },
        objective = { "64:773171797:1255863636", "นำ Assassin's Contract ไปให้ Magistrate Maleb ที่ Southshore" },
        description = { "138:481897474:571965780", "นี่คือสัญญาลอบสังหาร Magistrate Henry Maleb ผนึกด้วยขี้ผึ้งแดงและประทับแหวนตรารูปเฉพาะ" },
        progress = { "56:337946913:1638387060", "ดูเจ้าหอบมาก! มีอะไรรายงานหรือ?" },
        completion = { "148:1622100128:1623612071", "<Maleb ตรวจสัญญา>\n\nนี่อธิบายการโจมตี Southshore ล่าสุด Syndicate คงหมายหัวข้า เช่นเดียวกับผู้ปกครองคนก่อน!" },
        required = { [3668] = { "19:1163303718:605259070", "สัญญาว่าจ้างนักฆ่า" } },
        steps = { { "19:1163303718:605259070", "สัญญาว่าจ้างนักฆ่า" } },
    },
    [523] = { -- Baron's Demise
        title = { "14:1205255674:1405288977", "จุดจบของบารอน" },
        objective = { "65:2041294477:477540124", "นำ Head of Baron Vardus ไปให้ Magistrate Maleb ที่ Southshore" },
        description = { "378:1116517503:1887131848", "สัญญาที่เจ้าพบลงชื่อ Baron Vardus ขุนนางแห่งอดีตอาณาจักร Alterac ผู้ขึ้นชื่อว่าใจเย็นชาและโหดเหี้ยม ข้าไม่แปลกใจที่คนอย่างบารอนอยู่เบื้องหลัง\n\nหาเขาให้พบ แล้วนำมารับโทษ ต้องอยู่ตามแหล่ง Syndicate บางทีซาก Strahnbrad หรือหุบเขาทางเหนือจากที่นั่น" },
        progress = { "112:1268177019:1007900874", "Baron Vardus อย่าคิดว่า Southshore จะปล่อยให้ส่งอันธพาลมาทำร้ายเราโดยไม่รับโทษ ข้าต้องการหัวเขา!" },
        completion = { "11:1191658970:1224418299 N 63:1727919309:926719828", "ขอบคุณ {name} เมื่อรู้ว่าเจ้าวายร้ายเสียหัว ข้าก็วางหัวนอนได้สบายขึ้น" },
        required = { [3626] = { "20:2055914583:1031554531", "ศีรษะของบารอน Vardus" } },
        steps = { { "20:2055914583:1031554531", "ศีรษะของบารอน Vardus" } },
    },
    [524] = { -- Elixir of Agony
        title = { "15:1351320373:1530237846", "น้ำยาแห่งความทรมานแสนสาหัส" },
        objective = { "58:1258553821:333783932", "วาง Tainted Keg บนพรมให้ชาวนาที่ถูกจับ" },
        description = { "497:364913499:1396339724", "ข้างห้อง Deathguards จับชาวนาสองสามคนเป็นตัวประกัน High Executor Darthalia สงสัยว่ามีนักยุทธศาสตร์จาก Stormwind ซ่อนอยู่ในกลุ่ม แต่เมื่อคืนพบว่านายทหารนั้นตายใน Plaguelands แล้ว Darthalia ผู้เอาใจใส่ข้าเสมอจึงยกนักโทษให้ข้าจัดการ\n\nถึงเวลาจัดงานเลี้ยงให้ชาวนาแล้ว คงสนุกมาก!\n\nวางถังปนเปื้อนนี้บนพรมในห้องพวกเขา เหล้าติดโรคสำหรับทุกคน!" },
        progress = { "36:1032789817:976197013", "กลิ่นอับลอยจากพรม" },
        completion = { "42:828835012:1435681247", "เจ้าวางถังปนเปื้อนบนพรมฝุ่นจับ" },
        required = { [3520] = { "11:80146515:147682767", "ถังเหล้าที่ปนเปื้อน" } },
        steps = { { "11:80146515:147682767", "ถังเหล้าที่ปนเปื้อน" } },
    },
    [525] = { -- Further Mysteries
        title = { "17:1123058582:1503951546", "ปริศนายิ่งลึก" },
        objective = { "61:318806822:1829890628", "นำ Decrypted Letter ไปให้ Magistrate Maleb ที่ Southshore" },
        description = { "299:270471856:1552291155", "ข้าถอดรหัสแล้ว แต่ไม่รู้ตีความอย่างไร เจ้าพบในหมู่โจรแถวเชิงเขา Alterac หรือ? แปลกมาก...\n\nควรนำไปให้ผู้ปกครอง Southshore แม้เนื้อหาลึกลับ เมืองเขาก็ใกล้ Alterac ที่สุด หากมีภัยก่อตัว เขาควรรู้" },
        progress = { "N 92:540325877:574851509", "{name} เดินทางผ่านเชิงเขากับภูเขามาอีกหรือ? มีข่าวอะไร?" },
        completion = { "251:569267136:530761085", "<Maleb อ่านจดหมาย>\n\nนี่แปลจากจดหมายที่พบในค่าย Syndicate หรือ? ไม่ใช่ฝีมือโจร หรือแม้แต่ขุนนาง Alterac\n\nดูเหมือน Syndicate เชื่อมโยงกับอำนาจอื่น ข้าขนลุกเมื่อนึกว่าอาจเป็นอะไร" },
        required = { [3518] = { "16:316713831:1167603617", "จดหมายที่ถอดรหัสแล้ว" } },
        steps = { { "16:316713831:1167603617", "จดหมายที่ถอดรหัสแล้ว" } },
    },
    [527] = { -- Battle of Hillsbrad
        title = { "19:1895840337:1520688446", "ศึก Hillsbrad" },
        objective = { "120:325451091:1312080723", "ฆ่า Hillsbrad Farmhands 6 คน, Hillsbrad Farmers 6 คน, Farmer Ray และ Farmer Getz แล้วรายงาน Darthalia ที่ Tarren Mill" },
        description = { "40:329174854:610200222 C 446:318018052:679738057", "ยืนตรงเมื่อพูดกับข้า {class}\n\nข้ารับคำสั่งตรงจาก Varimathras เราต้องปราบมนุษย์ที่ยั้วเยี้ยจนกว่าเภสัชกรจะสร้างโรคระบาดใหม่ได้\n\nข้อมูลบอกว่าเมือง Hillsbrad อ่อนแอต่อการโจมตี งานแรกเจ้าคือขัดขวางเสบียงอาหารและโครงสร้างพื้นฐาน\n\nไปตะวันตก บุกฟาร์มเหนือสุดของ Hillsbrad Fields ต้องประหารเจ้าของที่ Farmer Ray กับ Farmer Getz ด้วย" },
        progress = { "349:556154103:222001809", "ในฐานะ High Executor แห่ง Tarren Mill ที่รับคำสั่งตรงจาก Varimathras และ Dark Lady เจ้าต้องทำตามข้า\n\nเจ้าดูเบาสงครามกับ Alliance หรือ? หากใช่ ข้าควรตัดหัวเจ้าตรงนี้ หากไม่ จงไปเมือง Hillsbrad ทางตะวันตก รบกับมนุษย์ตามคำสั่ง\n\nไปได้" },
        completion = { "9:612618706:1153568520 C 100:240444351:541369052", "พักได้ {class} กลับจากศึกแล้วสินะ แหล่งข่าวบอกว่าเจ้าทำได้ดีในแนวรบ Hillsbrad" },
        objectiveLabels = {
            monster = { ["Hillsbrad Farmer slain"] = "ปราบ ชาวนา Hillsbrad", ["Hillsbrad Farmhand slain"] = "ปราบ คนงานไร่ Hillsbrad", ["Farmer Ray slain"] = "ปราบ ชาวนา Ray", ["Farmer Getz slain"] = "ปราบ ชาวนา Getz" },
        },
    },
    [528] = { -- Battle of Hillsbrad
        title = { "19:1895840337:1520688446", "ศึก Hillsbrad" },
        objective = { "71:1814200164:490409516", "ฆ่า Hillsbrad Peasants 15 คน แล้วรายงาน Darthalia ที่ Tarren Mill" },
        description = { "251:2028810051:647880057 N 123:1713371355:1763576796", "ข่าวโจมตีฟาร์มเหนือทำให้ชาวเมืองตื่นกลัว ยอดเยี่ยม\n\nDeathstalkers รายงานว่าชาวนาหนีสู่ทุ่งทางใต้ Hillsbrad พวกโง่คิดว่าซ่อนในสวนผลไม้แล้วพ้นชะตาได้\n\nพิสูจน์ว่ามันคิดผิด {name} กลับ Hillsbrad Fields ตามหาชาวนาขลาดกลัว กำจัดในนาม Dark Lady\n\nไปได้!" },
        progress = { "22:732849797:587055223 C 76:1855734588:425545065", "มีคำสั่งแล้ว {class} เลิกอ้อยอิ่งใน Tarren Mill ขณะที่มีงานให้ทำที่อื่น" },
        completion = { "83:1973021671:671723518", "เงื้อมมือความตายบีบเมือง Hillsbrad แน่นขึ้น ศึกดำเนินไปด้วยดี" },
        objectiveLabels = {
            monster = { ["Hillsbrad Peasant slain"] = "ปราบ ชาวบ้าน Hillsbrad" },
        },
    },
    [529] = { -- Battle of Hillsbrad
        title = { "19:1895840337:1520688446", "ศึก Hillsbrad" },
        objective = { "139:360357268:966082099", "ฆ่า Blacksmith Verringtan และ Hillsbrad Apprentice Blacksmiths 4 คน\n\nนำเหล็กหนึ่งงวดกลับมา แล้วรายงาน Darthalia ที่ Tarren Mill" },
        description = { "453:1306300433:1402329948", "มนุษย์ Hillsbrad ต่อต้านเกินคาด ดูเหมือนช่างตีเหล็กท้องถิ่นติดอาวุธให้ชาวเมือง เราต้องตัดทุกสายส่งเสบียง\n\nภารกิจเจ้าคือประหาร Blacksmith Verringtan ฆ่าลูกมือด้วย ระหว่างนั้นเอาเหล็กหนึ่งงวดจากคลังกลับมา เสบียงจะมีประโยชน์เมื่อเรายึด Hillsbrad เสร็จและเริ่มถล่ม Southshore" },
        progress = { "40:87063576:25845101 C 84:1935845922:1520979016", "ทำตามคำสั่งได้ไหม {class}? จัดการ Verringtan กับผู้ช่วยหรือยัง? แล้วเหล็กอยู่ไหน?" },
        completion = { "22:1992490903:1497789292 C 48:939487863:898550485", "ภารกิจสำเร็จ {class} ต้องบอกด้วยว่าทำอย่างมีฝีมือทีเดียว" },
        required = { [3564] = { "16:2057585021:489167641", "เหล็กที่จัดส่งมา" } },
        steps = { { "16:2057585021:489167641", "เหล็กที่จัดส่งมา" } },
        objectiveLabels = {
            monster = { ["Blacksmith Verringtan slain"] = "ปราบ ช่างตีเหล็ก Verringtan", ["Hillsbrad Apprentice Blacksmith slain"] = "ปราบ ช่างตีเหล็กฝึกหัดแห่ง Hillsbrad" },
        },
    },
    [532] = { -- Battle of Hillsbrad
        title = { "19:1895840337:1520688446", "ศึก Hillsbrad" },
        objective = { "175:1006270079:334805694", "ฆ่า Magistrate Burnside และ Hillsbrad Councilmen 5 คน ทำลาย Hillsbrad Proclamation ขโมย Hillsbrad Town Registry แล้วรายงาน Darthalia ที่ Tarren Mill" },
        description = { "484:161557430:1903251664", "เมือง Hillsbrad ระส่ำระสาย เราเชื่อว่าจะล่มเร็ว ๆ นี้ แต่ต้องโหดเหี้ยมต่อไปจนกว่าสวะมนุษย์จะถูกลบจากเชิงเขาตลอดกาล\n\nแม้สูญเสียหนัก มนุษย์ยังรวมตัวรอบผู้นำสู้ต่อ ต้องกำจัด Magistrate Burnside กับสภาเมือง ทำลายเอกสารการเมืองที่มันเทิดทูน Hillsbrad Proclamation และขโมยทะเบียนเมืองมาด้วย" },
        progress = { "19:1775290449:1909309725", "มีข่าวอะไร?" },
        completion = { "69:466892210:525880697 C 1:46:46", "ข่าววีรกรรมใน Hillsbrad แพร่เร็ว เจ้าทำได้ดี {class}" },
        required = { [3657] = { "23:1875989564:1939458168", "ทะเบียนเมือง Hillsbrad" } },
        steps = { { "32:976380614:442635201", "ทำลายประกาศ Hillsbrad Proclamation" } },
        objectiveLabels = {
            item = { ["Hillsbrad Town Registry"] = "ทะเบียนเมือง Hillsbrad" },
            monster = { ["Magistrate Burnside slain"] = "ปราบ ผู้พิพากษา Burnside", ["Hillsbrad Councilman slain"] = "ปราบ สมาชิกสภา Hillsbrad" },
        },
    },
    [533] = { -- Infiltration
        title = { "12:1609148761:780490869", "แทรกซึม" },
        objective = { "74:1782233001:936290722", "หาข้อมูลที่อยู่ของ Gol'dir ให้ Krusk ที่ Tarren Mill" },
        description = { "229:1714228651:1986465289 N 64:1424036151:167461973", "ในที่สุดก็มีข่าวลือและหลักฐานที่อยู่ Gol'dir มนุษย์ย้ายเขาไปมา แต่เราตีวงค้นหาแคบลง มุ่งที่ค่ายใหญ่ Syndicate ทางเหนือใกล้นี่\n\nไปที่นั่น {name} นำข้อมูลทุกอย่างที่หาได้กลับมา" },
        progress = { "76:1059731492:253245012", "พบอะไรไหม? ข้ากลัวว่าโอกาสของ Gol'dir แย่ลงทุกวัน..." },
        completion = { "191:376414990:1749852292", "ในที่สุดก็รู้ว่า Gol'dir ถูกขังที่ไหน ค่ายนั้นไม่ไกลนัก หวังว่ามันจะไม่พร้อมเท่าครั้งแรกที่จับเรา" },
        required = { [3601] = { "17:694448792:274556993", "สารจากกลุ่ม Syndicate" } },
        steps = { { "17:694448792:274556993", "สารจากกลุ่ม Syndicate" } },
    },
    [535] = { -- Valik
        title = { "5:1016512166:1924605364", "Valik" },
        objective = { "63:573854115:1691123224", "นำ Southshore Stout หนึ่งเหยือก ไปให้ Valik ในค่าย Syndicate" },
        description = { "204:960104450:31091519", "อือ...บาดเจ็บ ใกล้ตาย แล้วยังเจอศัตรู\n\nเจ้าคงฆ่าข้าอยู่ดี แต่หากนำ Southshore stout มา พวกเจ้าก็ดื่มใช่ไหม? ข้าจะบอกสิ่งที่อยากรู้" },
        progress = { "80:1705543057:315644874", "เอาเครื่องดื่มมาหรือกลับมาฆ่าข้าให้จบ?" },
        completion = { "173:1795200557:2080487047", "เมื่อใกล้ตาย ข้าพูดได้เต็มปากว่านี่อร่อยที่สุดในชีวิต...เอ้า เอานี่ไป ตายแล้วก็ไม่มีประโยชน์กับข้า\n\nเอาสิ ลงมือได้แล้ว!" },
        required = { [3703] = { "16:511781594:1414836179", "เบียร์ดำ Southshore" } },
        steps = { { "16:511781594:1414836179", "เบียร์ดำ Southshore" } },
    },
    [536] = { -- Down the Coast
        title = { "14:1577745018:690944356", "ลงไปตามชายฝั่ง" },
        objective = { "98:1884653079:1474341854", "ฆ่า Torn Fin Tidehunters 10 ตัว และ Torn Fin Oracles 10 ตัว ให้ Lieutenant Farren Orinelle ที่ Southshore" },
        description = { "393:1463404080:522396313", "ย้ายจากยามเมือง Stormwind มายัง Southshore เมืองที่ดูแล้วควรถูกทิ้งร้าง...กลิ่นท่าเรือทั้งวันทั้งคืน\n\nยังมีตาแก่ Redpath...อยากให้ข้าจัดการเมอร์ล็อก ฮ่า!\n\nข้าแทบฝืนใจออกไปหาฝูงปลาโตเกินตัวตาม Western Strand ไม่ไหว หากเจ้าไปจัดการแทน ข้าจะขอบคุณมาก" },
        progress = { "137:80010328:470840332 N 36:518984946:1115540117", "ขอเอลอีกแก้ว แก้วก่อนเหมือนหายไปเอง!\n\nแสงสว่างเอ๋ย ข้าต้องติดที่นี่อีกนานเท่าไร?\n\nอ้อ เจ้านี่เอง {name} ฆ่าเมอร์ล็อกหรือยัง?" },
        completion = { "245:415450519:1554261036", "หวังว่านี่พอทำให้ Redpath เชื่อว่าข้า...ฮ่า!...ทำตามคำสั่ง กำจัดภัยเมอร์ล็อกอันน่ากลัวสยองร้ายกาจให้ Southshore! คงไม่มีความชั่วใดเหนือการอาละวาดของปลาโตเกินตัว!" },
        objectiveLabels = {
            monster = { ["Torn Fin Tidehunter slain"] = "ปราบ นักล่าตามกระแสน้ำ Torn Fin", ["Torn Fin Oracle slain"] = "ปราบ นักพยากรณ์ Torn Fin" },
        },
    },
    [537] = { -- Dark Council
        title = { "12:1941645414:1692656963", "สภามืด" },
        objective = { "85:2038319257:473400586", "ฆ่า Argus Shadow Mages 4 คน\n\nนำ Head of Nagaz ไปให้ Magistrate Maleb ที่ Southshore" },
        description = { "476:1353935307:1536953607", "จดหมายที่เจ้านำมาเขียนโดยผู้เรียกตนว่า Nagaz สมาชิก Argus Wake ข้าไม่รู้ว่ากลุ่มนี้คืออะไร แต่หากร่วมกับ Syndicate ก็ต้องเป็นภัย\n\nหา Nagaz กับ Argus Shadow Mages ที่กล่าวในจดหมาย แล้วฆ่าพวกมัน\n\nค้นใน Uplands ทางเหนือ Strahnbrad ที่ Syndicate แข็งแกร่งที่สุด\n\nหากโชคดี เจ้าจะพบทูต Argus Wake ที่นั่น" },
        progress = { "42:1792145055:417040911", "พบทูต Argus Wake ไหม?" },
        completion = { "11:534428891:784080240 N 254:1650509319:234008376", "ทำได้ดี {name} Argus Wake ไม่ใช่กลุ่มที่เราควรปล่อยให้บงการ Syndicate\n\nแม้เจ้าทำลายผู้นำที่นี่แล้ว Nagaz เป็นแค่คนรับใช้ของอีกผู้หนึ่ง Argus Wake อาจฝังรากลึกทั่วทวีป Azeroth\n\nหรือแม้แต่ทั่วโลก" },
        required = { [3672] = { "13:1234255694:1581231041", "ศีรษะของ Nagaz" } },
        steps = { { "13:1234255694:1581231041", "ศีรษะของ Nagaz" } },
        objectiveLabels = {
            monster = { ["Argus Shadow Mage slain"] = "ปราบ จอมเวทเงา Argus" },
        },
    },
    [539] = { -- Battle of Hillsbrad
        title = { "19:1895840337:1520688446", "ศึก Hillsbrad" },
        objective = { "87:816035095:966422699", "ฆ่า Foreman Bonds และ Hillsbrad Miners 10 คน แล้วรายงาน Darthalia ที่ Tarren Mill" },
        description = { "479:1880284105:1722662384", "ทะเบียนเมือง Hillsbrad บอกว่า Azureload Mine อยู่ใต้ Alliance และเป็นแหล่งแร่เหล็กสำคัญให้คลังอาวุธ\n\nแม้เราโจมตีเมืองอย่างเด็ดขาด Alliance ยังสนับสนุนและคุ้มกันเหมืองเต็มที่\n\nเหมืองอยู่ใต้เมือง Hillsbrad ตรงไป จงฆ่าหัวหน้ามนุษย์ชื่อ Bonds กับคนขุดเหมือง นั่นจะส่งคำเตือนชัดเจนถึง Alliance" },
        progress = { "150:1606761203:1426974664", "เจ้ารับคำสั่งตรงให้โจมตี Azureload Mine เหตุผลที่มัวอืดอาดใน Tarren Mill ต้องดีพอ ไม่เช่นนั้นข้าจะตัดหัวฐานกบฏ" },
        completion = { "106:188909763:764919388", "Dark Lady จะพอใจเมื่อรู้ว่ามีเหมืองใหม่สำหรับติดอาวุธทหารแล้ว" },
        objectiveLabels = {
            monster = { ["Foreman Bonds slain"] = "ปราบ หัวหน้าคนงาน Bonds", ["Hillsbrad Miner slain"] = "ปราบ คนงานเหมือง Hillsbrad" },
        },
    },
    [541] = { -- Battle of Hillsbrad
        title = { "19:1895840337:1520688446", "ศึก Hillsbrad" },
        objective = { "132:333862793:360938844", "เดินทางไป Dun Garok ฆ่า Mountaineers 8 คน, Riflemen 4 คน, Priests 2 คน และ Captain Ironhill แล้วรายงาน Darthalia ที่ Tarren Mill", variants = { { "133:1230480305:464881710", "เดินทางไป Dun Garok ฆ่า Mountaineers 10 คน, Riflemen 8 คน, Priests 4 คน และ Captain Ironhill แล้วรายงาน Darthalia ที่ Tarren Mill" } } },
        description = { "435:913381774:1007614916 C 43:1684488595:25802802", "คนแคระช่วยมนุษย์หรือ? สัตว์ตัวจ้อยสกปรกบัดซบ\n\nเราจะทดสอบความแข็งแกร่งของสิ่งที่เรียก Alliance ดูว่าเมื่อเจอโทสะเราแล้ว เจ้าพวกทุบข้อเท้ายังอยากช่วยมนุษย์เพียงใด เรารู้ที่มั่นมันในเขตนี้แน่นอน\n\nมันตั้งค่าย Dun Garok ทางตะวันออกเฉียงใต้ Hillsbrad ตาม Thoradin's Wall ภารกิจสุดท้ายของศึกนี้คือล้อม Dun Garok {class} ผู้นำ Captain Ironhill ต้องตาย" },
        progress = { "56:1097137182:77485620 C 284:177442041:1976875721", "Dun Garok เป็นอุปสรรคเกินฝีมือหรือ {class}? ข้านึกว่าเจ้าพิสูจน์ความกล้าใน Hillsbrad แล้ว\n\nหากทำภารกิจไม่ได้ ข้าจะหาคนที่ให้ผลดีกว่า ส่วนเจ้า ข้ามั่นใจว่า Dark Lady ต้องการคนขุดหลุมศพเพิ่มที่ Tirisfal Glades เสมอ" },
        completion = { "65:28047167:776876124", "ผลงานในสนามรบเจ้าคู่ควรกับคำสรรเสริญสูงสุด" },
        objectiveLabels = {
            monster = { ["Captain Ironhill slain"] = "ปราบ กัปตัน Ironhill", ["Dun Garok Mountaineer slain"] = "ปราบ ทหารภูเขา Dun Garok", ["Dun Garok Rifleman slain"] = "ปราบ พลปืนไรเฟิล Dun Garok", ["Dun Garok Priest slain"] = "ปราบ นักบวช Dun Garok" },
        },
    },
    [544] = { -- Prison Break In
        title = { "15:1881021568:1951657982", "บุกเรือนจำ" },
        objective = { "93:1815580299:1755122229", "ตามหาคนทรยศและนำวัตถุที่ขโมยคืน แล้วกลับไปหา Magus Voidglare ที่ Tarren Mill", variants = { { "66:991980009:1834344760 N 1:46:46", "ตามหาคนทรยศและนำวัตถุที่ขโมยคืน แล้วกลับมาหาข้า {name}" } } },
        description = { "494:1579074753:2059916917", "ข้ามา Tarren Mill เพื่อวิจัย แต่ต้องแก้วิกฤตก่อน หลายเดือนก่อน Forsaken สี่คนหนี Undercity หันหลังให้พี่น้อง และที่แย่กว่า...ขโมยของ Dark Lady\n\nโจรพวกนี้บุกคลังนิรภัย ขโมยวัตถุสี่ชิ้นที่เภสัชกรต้องใช้ศึกษา Sylvanas ต้องการคืน\n\nมันหนีจาก Undercity ไป Dalaran พ่อมดที่นั่นกักตัวไว้ใน Lordamere Internment Camp" },
        progress = { "77:1079951497:1881775471", "พบโจรไหม? ที่สำคัญกว่า พบของที่ขโมยไหม?" },
        completion = { "48:1805031159:2078772732 N 120:1787069059:442972825", "เจ้าช่วย Forsaken อย่างมาก {name} เราขาดวัตถุเหล่านี้มานาน\n\nและดีที่รู้ว่า Kegan กับคนทรยศอื่นได้รับโทษแล้ว" },
        required = { [3691] = { "16:666178779:1422685040", "หิน Bloodstone ทรงลิ่ม" }, [3689] = { "17:1987232036:1293693659", "ลูกกลม Bloodstone" }, [3690] = { "16:446894809:251379586", "เศษผลึก Bloodstone" }, [3688] = { "15:1731298210:271847893", "หิน Bloodstone ทรงรี" } },
        steps = { { "16:666178779:1422685040", "หิน Bloodstone ทรงลิ่ม" }, { "17:1987232036:1293693659", "ลูกกลม Bloodstone" }, { "16:446894809:251379586", "เศษผลึก Bloodstone" }, { "15:1731298210:271847893", "หิน Bloodstone ทรงรี" } },
    },
    [545] = { -- Dalaran Patrols
        title = { "15:1317459380:1619583250", "หน่วยลาดตระเวน Dalaran" },
        objective = { "96:1010990422:1797460346", "ฆ่า Dalaran Summoners 6 คน และ Elemental Slaves 12 ตัว แล้วกลับไปหา Magus Voidglare ที่ Tarren Mill", amount = { "5:409775429:850574908 W1 23:1282836812:1471634509 W2 65:1344347220:239477879", "ฆ่า Dalaran Summoners {world1} คน และ Elemental Slaves {world2} ตัว แล้วกลับไปหา Magus Voidglare ที่ Tarren Mill" } },
        description = { "500:1025721039:488096561", "พ่อมด Dalaran สร้างโดมเวทใหญ่ครอบใจกลางเมือง บ้างว่าป้องกันความรุนแรงยุคนี้ บ้างว่าแค่อยากสันโดษเพื่อศึกษาและวางแผน\n\nข้าไม่สนเหตุผล สนเพียงซากชานเมืองนอกโดมอาจซ่อนสมบัติเวทมีค่า\n\nแต่พ่อมดกับทาสธาตุลาดตระเวนอยู่\n\nจงล่ามัน แล้วกลับเมื่อจำนวนลดพอ", variants = { { "463:1810525767:807848354", "ก่อนหายไปอย่างลึกลับ เคยมีม่านเวทมหึมารอบเมือง Dalaran ที่เพิ่งสร้างใหม่ ข้าไม่สนว่าอะไรทำให้สิ่งมหัศจรรย์นั้นล้มเหลว แต่สนว่าชานเมืองที่เปิดออกอาจซ่อนสมบัติเวทมีค่า ร่องรอยซากที่เมืองใหม่สร้างทับ\n\nแต่พ่อมดกับทาสธาตุลาดตระเวนอยู่\n\nจงล่ามัน แล้วกลับเมื่อจำนวนลดพอ" } } },
        progress = { "60:1436808920:11860839", "ลดจำนวนหน่วยลาดตระเวน Dalaran รอบซากเมืองหรือยัง?", variants = { { "59:686882911:1194998445", "เจ้าลดจำนวนหน่วยลาดตระเวน Dalaran รอบเมืองของพวกมันได้บ้างหรือยัง?" } } },
        completion = { "90:1763547692:900805198 N 1:46:46", "ดีมาก ตอนนี้ซากน่าจะปลอดภัยพอให้ค้น หากระวังตัว\n\nขอบคุณ {name}", variants = { { "22:1285665660:255452583 N 48:1516512966:1786838740", "ดีมาก ขอบคุณ {name}\n\nตอนนี้เราไปเยือน Dalaran กันได้แล้ว" } } },
        objectiveLabels = {
            monster = { ["Dalaran Summoner slain"] = "ปราบ ผู้อัญเชิญแห่ง Dalaran", ["Elemental Slave slain"] = "ปราบ วิญญาณธาตุที่ถูกกดเป็นทาส" },
        },
    },
    [546] = { -- Souvenirs of Death
        title = { "18:849861106:173310316", "ของที่ระลึกแห่งความตาย" },
        objective = { "64:1007227936:906929214", "Deathguard Samsa แห่ง Tarren Mill ต้องการ Hillsbrad Human Skulls 30 หัว" },
        description = { "494:734194304:2106323312", "ได้ยินว่า Darthalia เกณฑ์เจ้าไปรบกับมนุษย์ Hillsbrad ข้าอิจฉานัก...\n\nระหว่างเจ้าสนุกฆ่ามนุษย์ ปล้นเมือง ข่มขวัญผู้บริสุทธิ์ ข้าต้องติดยามใน Tarren Mill\n\nจะสงสาร Deathguard แก่อย่างข้าบ้างไหม? ข้าสะสมกะโหลกมนุษย์ เจ้าคงสู้กับมนุษย์อีกนาน ระหว่างศึกยาวนาน นำกะโหลกมา 30 หัว แล้วข้าจะตอบแทนให้คุ้ม" },
        progress = { "13:881440196:293026955 N 101:1259523893:2084827408", "{name} ผู้โชคดีกลับมาแล้วหรือ? วันนี้ฆ่ามนุษย์เท่าไร? หวังว่าหลายร้อย!\n\nมีกะโหลกให้ข้าไหม?" },
        completion = { "54:271078322:502899510 N 1:33:33", "กะโหลกล้ำค่า! งดงามนัก! ข้าติดหนี้ตามสัญญาแล้ว {name}!" },
        required = { [3692] = { "21:739574125:488722854", "กะโหลกมนุษย์จาก Hillsbrad" } },
        steps = { { "21:739574125:488722854", "กะโหลกมนุษย์จาก Hillsbrad" } },
    },
    [547] = { -- Humbert's Sword
        title = { "15:1505801881:1785039205", "ดาบของ Humbert" },
        objective = { "87:925022135:154494967", "นำดาบของ Deathguard Humbert จาก Dun Garok กลับมาให้เขาที่ Tarren Mill" },
        description = { "494:274551009:2059093911", "High Executor Darthalia ส่งข้าเฝ้าดู Dun Garok ห่าง ๆ ข้าตั้งค่ายพ้นสายตา แต่ตอนเช้าต้องต้มน้ำ จึงออกเก็บฟืน\n\nกลับมาก็พบอุปกรณ์หาย\n\nดูเหมือนหน่วยสอดแนมคนแคระจาก Dun Garok ผ่านมาแล้วขโมยไป ข้าต้องการดาบ! หากเอาคืนได้จะขอบคุณยิ่ง ที่นั่นคนแคระมาก...คงยากจะหาโจรตัวจ้อยสกปรกที่ขโมย" },
        progress = { "36:1781202156:1550057144 N 82:1397774010:314402986", "เอาดาบคืนได้ไหม {name}? หาก High Executor Darthalia รู้ความโง่ข้า นางจะแขวนคอข้าจากขื่อ" },
        completion = { "96:1046715461:1962722852", "เจอแล้ว!\n\nอา ได้ดาบล้ำค่าคืนมือ ข้ารู้สึกครบถ้วนอีกครั้ง ขอบคุณมาก!" },
        required = { [3693] = { "15:1505801881:1785039205", "ดาบของ Humbert" } },
        steps = { { "15:1505801881:1785039205", "ดาบของ Humbert" } },
    },
    [549] = { -- WANTED: Syndicate Personnel
        title = { "27:1949471414:1761725897", "ประกาศจับ: สมาชิก Syndicate" },
        objective = { "117:1125825841:714948582", "ฆ่า Syndicate Rogues 10 คน และ Syndicate Watchmen 10 คน กลับไปรับรางวัลจาก High Executor Darthalia ที่ Tarren Mill" },
        description = { "379:661800459:1710295817", "ด้วยอำนาจ Lady Sylvanas สมาชิกองค์กร Syndicate ทุกคนถูกประกาศจับตาย ผู้ถูกควบคุมหรือจับเป็นจะถูกประหารทันที ขณะนี้ทราบว่ารวมกำลังในซาก Durnholde Keep ทางตะวันออกเฉียงใต้ของ Tarren Mill\n\nมีรางวัลงามแก่ทุกคนที่นำหลักฐานผลงานมาให้ High Executor Darthalia" },
        progress = { "60:319440114:1045289265 C 86:768046785:751828006", "ไม่มีอะไรทำดีกว่ายืนตรงหน้าข้าหรือ {class}? ในฐานะ High Executor ข้ามีเรื่องเร่งด่วนกว่าเพ่งหน้าเน่าเปื่อยเจ้า" },
        completion = { "11:1614239848:1406166483 C 72:743808950:402676362", "ยอดเยี่ยม {class} หากเป็นเช่นนี้ อีกไม่นานจะกำจัดเสี้ยนหนาม Syndicate จากแผ่นดินได้" },
        objectiveLabels = {
            monster = { ["Syndicate Rogue slain"] = "ปราบ โจร Syndicate", ["Syndicate Watchman slain"] = "ปราบ ยาม Syndicate" },
        },
    },
    [550] = { -- Battle of Hillsbrad
        title = { "19:1895840337:1520688446", "ศึก Hillsbrad" },
        objective = { "69:2095859537:774391284", "นำ Darthalia's Sealed Commendation ไปให้ Varimathras ที่ Undercity" },
        description = { "260:2140899873:2047607958 C 1:46:46", "เพราะเจ้ารบอย่างกล้าหาญและไม่ย่อท้อในศึก Hillsbrad ข้าจึงเขียนคำยกย่องวีรกรรมในสนามรบให้กองบัญชาการรับรู้\n\nนำหนังสือผนึกนี้ไปให้ Varimathras ที่ Undercity ไปอย่างภูมิใจ {class}" },
        progress = { "14:693862975:1044752766 C 51:1168712160:934124495", "อะไรพา {class} จากสนามรบมาถึง Undercity?" },
        completion = { "24:1034344033:1964233215 C 470:211672131:848480027", "เจ้าคือ {class} ชื่อกระฉ่อนที่โจมตีกำลัง Alliance ใน Hillsbrad Foothills อย่างเด็ดขาดสินะ? ข่าววีรกรรมรุ่งโรจน์มาถึง Undercity เร็วนัก\n\nหากยังแสดงความเป็นผู้นำและเชี่ยวชาญศึกเช่นนี้ เจ้าจะมีอนาคตไกลในกองทัพ Dark Lady\n\nแม้ภัยหลักคือทัพ Scourge ของ Lich King จากเหนือ “ปัญหา” มนุษย์ยังขัดขวางแผนรบเรา แต่เจ้าพิสูจน์ว่ามนุษย์ล้มลงได้และจะล้มลง" },
        required = { [3701] = { "31:269283247:536214227", "หนังสือยกย่องปิดผนึกของ Darthalia" } },
        steps = { { "31:269283247:536214227", "หนังสือยกย่องปิดผนึกของ Darthalia" } },
    },
    [551] = { -- The Ensorcelled Parchment
        title = { "25:1300631757:2132090668", "แผ่นหนังต้องมนตร์" },
        objective = { "65:2132883424:2015148774", "นำ Ensorcelled Parchment ไปให้ Loremaster Dibbs ที่ Southshore" },
        description = { "126:1792557639:1993961822", "แผ่นหนังนี้ลงมนตร์จนถอดความไม่ได้ แต่มีคำหนึ่งด้านบนที่อ่านออก\n\nNagaz" },
        progress = { "112:152718387:1033769994", "อ้อ มีอะไรอยากให้ข้าดูหรือ? หวังว่าเป็นเศษความรู้ที่เก็บจากบนภูเขา..." },
        completion = { "158:1113978780:1594312051", "บันทึกเข้ารหัสอีกหรือ?\n\nข้าอยากมีฝีมือถอดข้อความแปลก ๆ ทั้งหมดที่หลั่งไหลจาก Alterac แต่เกรงว่าความรู้ยังไม่พอ" },
        required = { [3706] = { "21:492849812:862814595", "แผ่นหนังลงมนตร์" } },
        objectiveLabels = {
            item = { ["Ensorcelled Parchment"] = "แผ่นหนังลงมนตร์" },
        },
    },
    [552] = { -- Helcular's Revenge
        title = { "18:2125466457:1647226835", "การแก้แค้นของ Helcular" },
        objective = { "90:1775744333:527620648", "นำ Helcular's Rod คืนจากเยติ แล้วส่งให้ Novice Thaivand ที่ Tarren Mill" },
        description = { "487:96565796:634203758", "อาจารย์ Helcular เกือบเปลี่ยนเป็นลิชสำเร็จ เมื่อฝูงชนมนุษย์พบรังพิธีกรรมบนเนินแล้วฆ่าอย่างโหดเหี้ยม แย่กว่านั้น มันฝังศพเขาในสุสาน Southshore\n\nจะยอมให้ดูหมิ่นพ่อมดยิ่งใหญ่เช่นนี้ไม่ได้ ในฐานะศิษย์ ข้าจะให้ฝนแห่งการแก้แค้นกระหน่ำ Southshore\n\nก่อนอื่นต้องมี Helcular's Rod เยติยึดรังพิธีกรรมแล้ว สัตว์ตัวใดตัวหนึ่งต้องมีมันแน่" },
        progress = { "155:1068352200:108736413", "ได้ Helcular's Rod คืนหรือยัง? แถวนี้เยติมาก คงหาได้ยาก แต่เราต้องมีก่อนเดินหน้าต่อ" },
        completion = { "30:1822360508:369640382 N 1:33:33", "เจอแล้ว! ยอดเยี่ยม {name}!" },
        required = { [3708] = { "14:536821336:461788651", "คทาของ Helcular" } },
        steps = { { "14:536821336:461788651", "คทาของ Helcular" } },
    },
    [553] = { -- Helcular's Revenge
        title = { "18:2125466457:1647226835", "การแก้แค้นของ Helcular" },
        objective = { "161:368539168:1160726845", "เติมพลัง Rod of Helcular จาก Flame of Azel, Flame of Veraz และ Flame of Uzel\n\nปักคทาที่เติมพลังแล้วลงหลุม Helcular ที่ Southshore" },
        description = { "498:532937248:937319238", "นี่ เอา Rod of Helcular ไป เจ้าต้องใช้\n\nHelcular สร้างกองไฟพิธีกรรม 3 แห่งเป็นส่วนหนึ่งของมนตร์ทรงพลังที่สุด Flame of Azel กับ Flame of Veraz อยู่ใน Foothill Caverns ส่วน Flame of Uzel อยู่ในถ้ำเหนือกลุ่มถ้ำนั้น ขึ้นเหนือไปบนภูเขา\n\nต้องเติมพลังคทาจากไฟทั้งสาม เมื่อพิธีครบ ปักลงหลุม Helcular ใน Southshore เมืองมนุษย์ใต้ที่มียามหนาแน่น การแก้แค้นจะเป็นของเรา!" },
        progress = { "46:295263615:1822985710", "หลุม Helcular อัดแน่นด้วยพลังลี้ลับ" },
        completion = { "42:2126537423:301836467", "เสียงครืนดังก้องจากพื้นดิน" },
        required = { [3710] = { "15:135748979:1486287407", "คทาของ Helcular" } },
        steps = { { "21:1468381464:583949863", "เติมพลังให้เปลวไฟแห่ง Azel" }, { "22:682802968:86577589", "เติมพลังให้เปลวไฟแห่ง Veraz" }, { "21:1808555214:768723021", "เติมพลังให้เปลวไฟแห่ง Uzel" }, { "15:135748979:1486287407", "คทาของ Helcular" } },
    },
    [554] = { -- Stormpike's Deciphering
        title = { "23:1081711924:74552420", "การถอดความของ Stormpike" },
        objective = { "68:435475948:523535606", "นำ Ensorcelled Parchment ไปให้ Prospector Stormpike ที่ Ironforge" },
        description = { "328:843567083:229515385", "Prospector Stormpike เชี่ยวชาญถอดรหัสและถอดความ หากนำแผ่นหนังไปให้ บางทีเขาจะเข้าใจได้ ตอนนี้ Stormpike ศึกษาที่กองบัญชาการนักสำรวจใน Ironforge\n\nเมื่อพบ บอกว่าเจ้าคุยกับข้ามา ช่วงนี้ข้าส่งงานให้เขามากทีเดียว" },
        progress = { "228:905814554:1334813171", "รบกวนอีกแล้วหรือ?\n\nอา แผ่นหนังถูกคลุมด้วยมนตร์ถักทอซับซ้อนประณีต แน่นอนว่าข้าคลายได้ แต่ต้องใช้เวลา และเวลาข้ามีค่ามาก...\n\nบางทีข้าซื้อจากเจ้าเลยดีไหม?" },
        completion = { "181:979377417:1601534540", "ตัดสินใจฉลาด ข้าไม่คิดว่ามีนักปราชญ์อื่นที่แปลม้วนนี้ได้ หากเนื้อหาน่าสนใจ ไม่ต้องกลัว ข้าจะส่งคนไปตามเจ้า" },
        required = { [3706] = { "21:492849812:862814595", "แผ่นหนังลงมนตร์" } },
        steps = { { "21:492849812:862814595", "แผ่นหนังลงมนตร์" } },
    },
    [555] = { -- Soothing Turtle Bisque
        title = { "22:1404935872:1008943184", "ซุปเต่าบำรุงใจ" },
        objective = { "85:1611614233:2029842190", "นำ Turtle Meat 10 ชิ้น และ Soothing Spices ไปให้ Chef Jessen ที่ Southshore" },
        description = { "506:1231623763:1852126629", "สิ่งที่เจ้าจะรู้เกี่ยวกับ Southshore คือเรามีอาหารยอดเยี่ยมที่สุดแห่งหนึ่งทางเหนือ Stormwind!\n\nอย่างสูตรลับซุปเต่าข้า มีคนเดินทางจาก Darkshire มาเพียงเพื่อกินสักชาม พูดแล้วช่วงนี้ข้าทำไม่ได้เลย เคยขึ้นเหนือผ่าน Dalaran ไป Lake Lordamere ล่า Snapjaw เอง แต่ตอนนี้อันตรายเกิน หากนำเนื้อเต่าจาก Snapjaw ทางเหนือพร้อม Soothing Spices มา ข้าจะทำให้!" },
        progress = { "145:1597010459:1610678959", "หาส่วนประกอบได้ไหม? แถบนี้ไม่สงบเหมือนเคยแล้ว อา หากความไม่สงบนี้ไม่เคยเกิด..." },
        completion = { "87:551271907:243984885", "ทุกคนต้องยินดี ซุปเต่าบำรุงใจของ Chef Jessen กลับมาเสิร์ฟแล้ว!" },
        required = { [3712] = { "11:706164050:819578527", "เนื้อเต่า" }, [3713] = { "15:570335490:1770959346", "เครื่องเทศรสละมุน" } },
        steps = { { "11:706164050:819578527", "เนื้อเต่า" }, { "15:570335490:1770959346", "เครื่องเทศรสละมุน" } },
    },
    [556] = { -- Stone Tokens
        title = { "12:980136208:857111802", "เครื่องรางศิลา" },
        objective = { "62:1434739065:1311670923", "นำ Worn Stone Tokens 10 ชิ้น ไปให้ Keeper Bel'varil ที่ Tarren Mill" },
        description = { "470:742114285:928684865", "ความสามารถเด่นของพ่อมด Dalaran คือคุ้นเคยกับธาตุ สิ่งมีชีวิตทรงพลังจากมิติอื่น พ่อมดใช้เครื่องรางเวทควบคุมมัน Magus Voidglare อยากได้มาศึกษาบ้าง\n\nเข้าเขตพ่อมด Dalaran ทางตะวันตก Hillsbrad เก็บเครื่องรางมา\n\nอาจพบจากชาว Dalaran ทุกคน แต่ข้าแนะให้ล่าที่ค่ายกักกัน ปลอดภัยกว่าใน Dalaran" },
        progress = { "35:1450741796:530727474 N 45:2122886970:1416967238", "มี Worn Stone Tokens หรือยัง {name}? Magus อยากไขความลับเต็มที" },
        completion = { "168:466052240:617460560 N 1:46:46", "พวกนี้เหมาะ แม้ดูเหมือนเวทจางไปแล้ว แต่การทดลองแรกของ Magus ควรใช้ตัวอย่างไร้ฤทธิ์เช่นนี้\n\nขอบคุณ {name}" },
        required = { [3714] = { "16:1406227861:1138184446", "ตราหินสึกกร่อน" } },
        objectiveLabels = {
            item = { ["Worn Stone Token"] = "ตราหินสึกกร่อน" },
        },
    },
    [557] = { -- Bracers of Binding
        title = { "18:1233171671:113937151", "ปลอกแขนพันธนาการ" },
        objective = { "68:190975023:737594887", "นำ Bracers of Earth Binding 4 อัน ไปให้ Keeper Bel'varil ที่ Tarren Mill" },
        description = { "355:653624667:1832279769", "Magus คงยุ่งศึกษาเครื่องรางหินที่เจ้าเก็บ แต่ข้ารู้ว่าในที่สุดจะต้องการของคู่กัน คือปลอกแขนพันธนาการ มันสวมรอบข้อมือธาตุจริง ๆ เพื่อผูกมัดให้รับใช้จอมเวท\n\nล่าธาตุในซาก Dalaran เก็บ Bracers of Earth Binding มา แล้ว Magus จะพอใจ" },
        progress = { "7:989913233:66981971 N 102:679524465:130248506", "สวัสดี {name} ธาตุเป็นเหยื่อที่จัดการยาก แต่รู้ว่าเจ้าทำได้ มีปลอกแขนพันธนาการหรือยัง?" },
        completion = { "195:941972104:746396181 N 53:1944673584:655653105", "เจอแล้ว ข้าเชื่อว่าธาตุที่เจ้าถอดปลอกแขนคงยินยอมดีใช่ไหม?\n\nอืม...ความตายไม่เพียงหยุดหัวใจ ดูเหมือนยังขโมยจังหวะเล่นมุกของข้าด้วย\n\nขอบคุณ {name} เจ้ารับใช้ Magus และ Dark Lady ได้ดี" },
        required = { [3715] = { "24:1167267494:1899520893", "ปลอกรัดแขนแห่งพันธนาการปฐพี" } },
        steps = { { "24:1167267494:1899520893", "ปลอกรัดแขนแห่งพันธนาการปฐพี" } },
    },
    [559] = { -- Farren's Proof
        title = { "14:350617933:1562800613", "หลักฐานของ Farren" },
        objective = { "108:267320312:357760934", "เก็บ Murloc Heads 10 หัว จากเมอร์ล็อกที่ Western Strand ให้ Lieutenant Farren Orinelle ที่ Southshore" },
        description = { "22:196805317:681790950 N 217:1122746661:257464662", "เชื่อไหม {name}? Redpath ยังไม่พอใจกับเมอร์ล็อกที่เราฆ่า อ้อ อย่าถ่อมตัว เจ้าก็ช่วยนิดหน่อย ตอนนี้เขาอยากได้หลักฐาน ให้ตัดหัวเมอร์ล็อกเย็นลื่นไปให้ตรวจ" },
        progress = { "32:1384616921:2123362725 N 1:63:63", "ได้หัวให้ข้าหรือยัง {name}?" },
        completion = { "288:724501194:1388933332", "โอ้ แสงสว่างช่วย...มันหยดลงพื้น\n\nข้าทนจับไม่ได้ ปลาเฉย ๆ ก็ดี แต่พองอกขาแล้วเดินไปมา...ข้าไม่กินปลาหลายสัปดาห์แล้ว ที่ Southshore นั่นหมายถึงแทบไม่ได้กินอะไรเลย" },
        required = { [3716] = { "11:1059818951:238315265", "หัวเมอร์ล็อก" } },
        objectiveLabels = {
            item = { ["Murloc Head"] = "หัวเมอร์ล็อก" },
        },
    },
    [560] = { -- Farren's Proof
        title = { "14:350617933:1562800613", "หลักฐานของ Farren" },
        objective = { "67:2124640769:1217557291", "ส่งถุงหัวเมอร์ล็อกให้ Marshall Redpath ที่ Southshore" },
        description = { "10:950905247:1805974890 N 136:1919113973:288554722", "รู้ไหม {name} ข้าไม่อยากถือหัวพวกนี้จริง ๆ...ไหน ๆ เจ้าจับอยู่แล้ว ช่วยส่งให้ Redpath แทนได้ไหม?" },
        progress = { "89:1658608995:739097779", "สวัสดี พลเมือง มาช่วยรักษาความปลอดภัย Southshore หรือ?" },
        completion = { { "164:209703222:435463742", "164:1939777819:2119367247" }, "คนวิ่งธุระให้ Farren หรือ?\n\nหากช่วยเขาหาหัวเหล่านี้ ก็ขอบคุณ Southshore ต้องการคนขยันและความพยายามเพื่อรักษาการป้องกัน" },
        required = { [3717] = { "20:1160645992:1372906457", "กระสอบบรรจุหัวเมอร์ล็อก" } },
        steps = { { "20:1160645992:1372906457", "กระสอบบรรจุหัวเมอร์ล็อก" } },
    },
    [561] = { -- Farren's Proof
        title = { "14:350617933:1562800613", "หลักฐานของ Farren" },
        objective = { "52:1461415198:574140983", "คุยกับ Lieutenant Farren Orinelle ที่ Southshore" },
        description = { "177:1253110582:1371692050", "บอก Lieutenant Orinelle ให้หันไปจัดการนากาที่เต็ม Eastern Strand เมื่อได้ผล ให้มารายงานข้าด้วยตัวเอง" },
        completion = { "139:448379899:949351905", "นากาหรือ? Redpath คงเพิ่งได้ข่าวเดียวกับข้า...ฮ่า! เขาจะไม่ได้เลื่อนยศจากแรงงานข้า ให้ข้าอธิบาย" },
    },
    [562] = { -- Stormwind Ho!
        title = { "13:874948596:1305883724", "มุ่งสู่ Stormwind!" },
        objective = { "104:223947627:1773379349", "ฆ่า Daggerspine Shorehunters 10 ตัว และ Daggerspine Sirens 10 ตัว ให้ Lieutenant Farren Orinelle ที่ Southshore" },
        description = { "340:1872806609:499538695 N 144:1143375159:576840119 N 1:33:33", "อดีตอาจารย์ในยามเมือง Stormwind ส่งข่าวว่ากองบัญชาการ Alliance เริ่มกังวลภัยนากา ได้ยินว่าผู้พิสูจน์ตนมีโอกาสดีที่จะเลื่อนยศ หรืออย่างน้อยย้ายงาน\n\nมีปัญหาเล็กนิดเดียว...ข้าสู้นากาไม่ไหว {name} แน่นอน ห้ามศึกคนเมาในบาร์หรือจับขอทานก้าวร้าวยังได้ แต่นากาเกินกำลัง เจ้าต้องช่วยข้า {name}!" },
        progress = { "86:444826731:1672007536", "ข้าเตรียมจดหมายถึง Major Samuelson ที่ Stormwind แล้ว ขาดเพียงผลงาน" },
        completion = { "148:115179959:484693506", "เมื่อปราบนากา Southshore ข้าต้องได้ย้ายแน่ จะได้เห็น Stormwind อีก...พ้นท่าเรือที่แสงสว่างทอดทิ้งนี้" },
        objectiveLabels = {
            monster = { ["Daggerspine Siren slain"] = "ปราบ ไซเรน Daggerspine", ["Daggerspine Shorehunter slain"] = "ปราบ นักล่าริมฝั่ง Daggerspine" },
        },
    },
    [563] = { -- Reassignment
        title = { "12:432390419:140597952", "โยกย้ายหน้าที่" },
        objective = { "61:1305584678:1176384587", "ส่งรายงานของ Farren ให้ Major Samuelson ที่ Stormwind Keep" },
        description = { "320:1082394545:260373849", "ให้เขาอ่านรายงานคงไม่ยาก ผู้บัญชาการยามคนใหม่ Major Samuelson เคยเป็นอาจารย์ตอนข้าประจำ Stormwind น่าจะเป็นเหตุผลมากพอให้ย้ายกลับเมือง แต่ต้องให้เจ้าถือรายงานไป...ไม่อยากให้ตาแก่ Redpath รู้ทัน" },
        progress = { "66:1340578334:2119169308", "สวัสดี พลเมือง ยามเมือง Stormwind ช่วยอะไรได้?" },
        completion = { "230:952668670:2061691425", "อะไรนี่? อา...ศิษย์ผู้ใส่ใจจัดการปัญหานากา Southshore แล้ว ขอบใจที่นำมา ข้าจะพิจารณาแน่นอนเมื่อตรวจการจัดบุคลากรเดือนหน้า" },
        required = { [3721] = { "15:1538275302:1034222270", "รายงานของ Farren" } },
        steps = { { "15:1538275302:1034222270", "รายงานของ Farren" } },
    },
    [564] = { -- Costly Menace
        title = { "13:1478702321:1532739739", "ภัยที่สร้างความเสียหายแพง" },
        objective = { "93:1232193842:1934905198", "Darren Malvew แห่ง Southshore ต้องการให้เจ้าฆ่า Mountain Lions 8 ตัว และ Hulking Mountain Lions 10 ตัว" },
        description = { "497:617597502:942805561", "ไม่มีอะไรทำให้ข้าหงุดหงิดเท่าเสียม้าสวย ๆ เหล่านี้ เชื่อเถอะ เราเสียไปมากเพราะอันเดดน่ารำคาญ แก๊ง Syndicate บัดซบ และวายร้ายไร้ประโยชน์แถวนี้\n\nแต่สาบานต่อหลุมปู่ ไม่มีภัยต่อม้ายิ่งกว่า Mountain Lions บน Alterac มันลงจากเขามาทำชีวิตข้ายากเสมอ!\n\nคิดว่าตัวเองเป็นวีรบุรุษหรือ? ไปจัดการสิ!" },
        progress = { "198:990888906:1439973198", "Mountain Lions ฆ่าม้าเราทั่วไปหมด แต่เจ้ายังอยากพล่ามเรื่องอากาศกับสารพัดเรื่อง\n\nข้าคงต้องหาวีรบุรุษจริง ฆ่าให้มาก พูดให้น้อย" },
        completion = { "146:1574926281:328238482 N 1:46:46", "ข่าวดีจริง! น่าหาวีรบุรุษสงครามมาจัดการแต่แรก เจ้าคงทำให้พ่อภูมิใจ {name}" },
        objectiveLabels = {
            monster = { ["Mountain Lion slain"] = "ปราบ สิงโตภูเขา", ["Hulking Mountain Lion slain"] = "ปราบ สิงโตภูเขาร่างใหญ่" },
        },
    },
    [565] = { -- Bartolo's Yeti Fur Cloak
        title = { "24:1111252129:737791007", "เสื้อคลุมขนเยติของ Bartolo" },
        objective = { "110:2056344244:1221035117", "นำ Bolt of Wool, Hillman's Cloak, Fine Thread และ Yeti Fur 10 ก้อน ไปให้ Bartolo Ginsetti แห่ง Southshore" },
        description = { "188:447717766:929834187 R 254:798415098:2050527894", "ข้า Bartolo ผู้ยิ่งใหญ่ จะสร้างเสื้อคลุมขนเยติชื่อก้องโลก เลื่องลือทั่ว Alliance ให้เจ้า!\n\nท้าให้เดินทั่วโลกแล้วหาเสื้อคลุมที่ดีกว่า อ้อ ว่าไงนะ {race} ตัวน้อย? “Bartolo ไม่มีเสื้อคลุมใดดีกว่านี้!” ใช่แล้ว ข้าได้ยินมาก่อน\n\nBartolo ต้องใช้ Bolt of Wool, Hillman's Cloak ที่ช่างหนังชำนาญทำ, Fine Thread และแน่นอน ขนเยติ! นำมาแล้วเจ้าจะเป็นลูกค้ามีความสุข!" },
        progress = { "189:116016968:542097071", "กลับมาหา Bartolo ผู้ยิ่งใหญ่แล้ว บางทีเก็บวัสดุเสื้อคลุมขนเยติครบ? หรือแค่อยากอาบรัศมีความยิ่งใหญ่ของข้า Bartolo!" },
        completion = { "167:1541259012:478908222", "ถึงเวลาที่ Bartolo ผู้ยิ่งใหญ่จะแสดงมนตร์! ไม่ต้องมีไม้เท้าพ่อมดหรือคทาจอมเวท เพราะข้า Bartolo ผู้ยิ่งใหญ่ สร้างมนตร์ด้วยเพียงเข็มกับด้าย!" },
        required = { [2997] = { "20:270810616:33490768", "ผ้าขนสัตว์หนึ่งพับ" }, [2321] = { "11:1605976113:1298306081", "ด้ายเนื้อละเอียด" }, [3719] = { "15:1137627885:441987233", "ผ้าคลุมของชาวเขา" }, [3720] = { "8:664961188:463331024", "ขนเยติ" } },
        steps = { { "20:270810616:33490768", "ผ้าขนสัตว์หนึ่งพับ" }, { "11:1605976113:1298306081", "ด้ายเนื้อละเอียด" }, { "15:1137627885:441987233", "ผ้าคลุมของชาวเขา" }, { "8:664961188:463331024", "ขนเยติ" } },
    },
    [566] = { -- WANTED: Baron Vardus
        title = { "20:1921130203:2089243575", "ประกาศจับ: Baron Vardus" },
        objective = { "81:80609744:1827057116", "ฆ่า Baron Vardus แล้วนำหัวไปให้ High Executor Darthalia ที่ Tarren Mill" },
        description = { "378:1727245261:1712885928", "ตามคำสั่ง High Executor Darthalia มนุษย์ Baron Vardus ถูกประกาศจับฐานก่ออาชญากรรมต่อ Forsaken เขาเป็นสมาชิกระดับสูงขององค์กร Syndicate\n\nพบครั้งสุดท้ายที่ Uplands ใน Alterac Mountains เหนือ Tarren Mill\n\nจับตาย นำหลักฐานความตายให้ High Executor Darthalia เพื่อรับรางวัล" },
        progress = { "4:1110228981:147916455 N 72:713969624:568481717", "อา {name} มารับค่าหัว Baron Vardus หรือ?" },
        completion = { "24:457428191:1492706846 N 125:891375005:713820457", "เจ้าทำงานได้ผล {name} เมื่อ Baron Vardus ตาย ผู้นำ Syndicate ก็ลดลง การต่อต้านและก่อกวนคงอยู่ไม่นาน" },
        required = { [3626] = { "20:2055914583:1031554531", "ศีรษะของบารอน Vardus" } },
        steps = { { "20:2055914583:1031554531", "ศีรษะของบารอน Vardus" } },
    },
    [657] = { -- Hints of a New Plague?
        title = { "22:2061412290:2113070759", "เบาะแสโรคระบาดใหม่?" },
        objective = { "18:522779286:610725079", "คุยกับ Kinelory" },
        description = { "498:1131307122:1750974014", "<Quae เริ่มตรวจแฟ้ม>\n\nน่าสนใจจริง Apothecary Jorell ทดลองสิ่งร้ายแรงที่ Go'Shek ไม่รู้เกี่ยวกับ Hillsbrad อย่างไร แต่ Phin คงไม่พอใจหากเราปล่อยไว้\n\nระหว่างเจ้าไม่อยู่ เราปะทะออร์ค ข้าไม่แข็งแรงพอช่วย Kinelory หากเจ้าพร้อม นางต้องมีคนคุ้มกันเมื่อลงฟาร์มขโมยงานวิจัยที่ Jorell ยังไม่ส่ง Tarren Mill" },
        completion = { "247:2108138731:826354729", "หากทำให้ Phin สงบใจ ข้าจะกำจัด Forsaken ทุกตนเอง เขาทำเพื่อเรามากตั้งแต่โรคระบาด เราเคยคิดว่าจะไม่มีมิตรหรือครอบครัวอีกแล้ว\n\nพร้อมเมื่อไรบอกข้า เราจะเริ่มทันที" },
    },
    [658] = { -- Hints of a New Plague?
        title = { "22:2061412290:2113070759", "เบาะแสโรคระบาดใหม่?" },
        objective = { "89:1844228570:1117317164", "ตามหา Forsaken Courier แล้วนำ Sealed Folder ของนางกลับไปให้ Quae ใกล้ Go'Shek Farm" },
        description = { "501:254917943:769712390", "Phin ส่งเจ้ามาดูเราหรือ? ไม่แปลก เขาห่วงเกินไป\n\nเราเฝ้าฟาร์มหลายวัน Kin บอกว่าเพิ่งเห็นคนส่งสารออกจากบ้านเล็กทางใต้\n\nนางพูดมาก แต่ข้าไว้ใจประสาทสัมผัสนางเสมอในแดนอันตราย\n\nเจ้าเชี่ยวชาญสะกดรอยไหม? เราคิดว่าคนส่งสารอาจถือบันทึกไป Tarren Mill หากได้เอกสาร อาจไขเรื่อง Hillsbrad ได้" },
        progress = { "53:460971014:603657219 N 227:1299601528:1709418468", "ขอบคุณที่ช่วยหาคนส่งสาร {name}\n\nระหว่างเจ้าไม่อยู่ Kin เห็นเภสัชกรออกบ้านเดียวกันทางใต้ ข้ามั่นใจว่าทำเรื่องชั่ว แต่ต้องมีหลักฐานก่อนบุ่มบ่าม\n\nได้ผลบ้างไหม?" },
        completion = { "42:174823607:1186786513", "ยอดเยี่ยม!\n\nมาดูว่าเป็นเรื่องอะไร..." },
        required = { [4482] = { "13:418549941:1752533495", "แฟ้มปิดผนึก" } },
        steps = { { "13:418549941:1752533495", "แฟ้มปิดผนึก" } },
    },
    [659] = { -- Hints of a New Plague?
        title = { "22:2061412290:2113070759", "เบาะแสโรคระบาดใหม่?" },
        objective = { "69:260652100:703711204", "หา Quae และ Kinelory ใกล้ Go'Shek Farm ใน Arathi Highlands" },
        description = { "20:811683665:110673604 N 476:1886971649:1553452514", "สวัสดี ยินดีพบ {name} ข้านำกลุ่มนักผจญภัยสืบเหตุแปลกในแถบนี้\n\nญาติข้าที่ Hillsbrad เพิ่งจำใจฆ่าสุนัข Stanley เพราะมันโตมหึมาอย่างลึกลับ โจมตีทุกคนที่เข้าใกล้อย่างดุร้าย\n\nข้าเชื่อว่าอันเดดเกี่ยวข้อง เราหาหลักฐานอยู่\n\nQuae กับ Kinelory สหายสองคนไป Go'Shek Farm ใน Arathi Highlands ไม่ส่งข่าวหลายวัน หาให้ข้าหน่อยได้ไหม? ข้ากังวลแล้ว" },
        completion = { "139:1458331792:1808273604", "พยายามเงียบที่สุด นักเดินทาง\n\nออร์คไม่ชอบถูกสอดแนม และฟาร์มนี้มีมากกว่าที่เห็น" },
    },
    [660] = { -- Hints of a New Plague?
        title = { "22:2061412290:2113070759", "เบาะแสโรคระบาดใหม่?" },
        objective = { "43:842724081:1663221607", "ปกป้อง Kinelory จนกว่านางกลับไปหา Quae" },
        description = { "11:1140617183:1872504242 N 33:246642339:1662132032", "เอาล่ะ {name} ถ้าเจ้าพร้อม ข้าก็พร้อม\n\nไปกันไหม?" },
        progress = { "93:2099128978:1377065494", "หมดเวลาคุย หากห่วงชาว Hillsbrad จงปกป้อง Kinelory" },
        completion = { "36:1396704118:1878785082 N 134:289018953:247858758", "เจ้าช่วยเรามาก {name} ขอบคุณ\n\nหวังว่า Kin ไม่สร้างปัญหาเกินไปข้างล่าง นางเป็นมิตรมาก แต่หากเป็นศัตรูก็อันตรายได้ไม่แพ้กัน" },
        objectiveLabels = {
            event = { ["Protect Kinelory"] = "คุ้มกัน Kinelory" },
        },
    },
    [661] = { -- Hints of a New Plague?
        title = { "22:2061412290:2113070759", "เบาะแสโรคระบาดใหม่?" },
        objective = { "31:1787322541:75902785", "หา Phin Odelic ที่ Southshore" },
        description = { "413:1720140434:1633750641", "ข้าเคยเห็น Kinelory หลังเที่ยวโรงเหล้าดูแย่กว่าตอนนี้มาก เจ้าปกป้องได้ดีแน่นอน\n\nของที่นางนำจากฟาร์มคงทำให้ Phin เข้าใจบ้างว่าเกิดอะไรใน Arathi เพื่อให้แน่ใจว่าไม่มีการตอบโต้หลังเจ้าบุก เราจะอยู่ต่ออีกหน่อย เจ้ากลับ Southshore ไปคุย Phin ได้ไหม?" },
        completion = { "455:1412884801:1012209692", "สองจอมป่วนปลอดภัยสินะ? ฮ่า ๆ ดีใจที่ได้ยิน ขอบใจที่นำข่าวที่อยู่และสภาพทั้งคู่มา ข้ายินดียิ่งที่ยังมีชีวิต ในฐานะเพื่อนและสหายเดินทาง ไม่มีใครแทนได้\n\nแต่...ที่สำคัญ ต้องขอบคุณความช่วยเหลือให้สมควร นี่ รับไว้พร้อมคำขอบคุณจากกลุ่มข้า\n\nหากโชคดี เราจะรู้ว่า Forsaken ทำอะไร แล้วหยุดมัน" },
    },
    [676] = { -- The Hammer May Fall
        title = { "19:965555441:1295453505", "Hammerfall อาจล่มสลาย" },
        objective = { "120:620349808:765112127", "ฆ่า Boulderfist Ogres 8 ตัว และ Boulderfist Enforcers 10 ตัว แล้วหา Drum Fel ที่ฐาน Hammerfall ใน Arathi Highlands" },
        description = { "31:1430617282:1169966498 C 435:706215431:527726334", "พวกอ่อนแอ...ทุกคน เจ้าน่ะ {class} มองอะไร? คิดว่าพิเศษหรือ? ทำไมไม่พิสูจน์?\n\nฐาน Hammerfall ใน Arathi ถูกโจมตี หากไม่ส่งคนช่วยเร็ว ๆ ต้องล่มแน่\n\nแต่ก่อนรีบไป ควรทดสอบฝีมือก่อน ตะวันออกเฉียงเหนือ Stromgarde ใน Arathi มีเนินออกร์เผ่า Boulderfist หากรับมือออกร์กับ Enforcers ได้ ก็ไปรายงาน Drum Fel ที่ Hammerfall" },
        progress = { "195:2060663964:574152207 C 20:287138348:1431869132 N 1:63:63", "ข้าไม่มีเวลาแม้แต่ลับขวาน จะออกจากฐานไปฆ่าสัตว์ที่คิดฆ่าพี่น้องได้อย่างไร\n\nเจ้าดูไม่มีประสบการณ์เท่าทหาร grunt ด้วยซ้ำ อย่าว่าแต่ {class} เต็มตัว ต้องการอะไร {name}?" },
        completion = { "444:1265999731:1102538149", "คิดว่าแข็งแกร่งพอช่วย Hammerfall หรือ? ก็ได้\n\nTallow อาจส่งไปเนินออกร์หวังให้ตาย หรือคิดว่าเจ้าแข็งแกร่งพอช่วยเรา ไม่ว่าอย่างไร เจ้าก็อยู่นี่แล้ว และข้าต้องการทหารเพิ่มสู้การโจมตีไม่หยุด\n\nหากจะอยู่ Hammerfall พักก่อน พร้อมแล้วมาคุยใหม่ ที่นี่ไม่ขาดการต่อสู้" },
        objectiveLabels = {
            monster = { ["Boulderfist Ogre slain"] = "ปราบ อ็อกเกอร์ Boulderfist", ["Boulderfist Enforcer slain"] = "ปราบ มือปราบ Boulderfist" },
        },
    },
    [92432] = { -- An Alarming Request
        title = { "19:1805806287:1164005697", "คำขอน่าวิตก" },
        objective = { "64:1765579308:1047644068", "รายงานต่อ Image of Archmage Modera ใกล้ City of Dalaran" },
        description = { "485:1619739599:1578373746", "ข้านำข่าวร้ายจาก Dalaran บางสิ่งรบกวนสายพลังเวท ทำให้สิ่งประดิษฐ์เวทในเมืองทำงานผิดปกติและทำลายล้าง\n\nยังไม่รู้สาเหตุ สภาสูงสั่งเก็บเป็นความลับไม่ให้องค์กรอับอาย แต่ปิดบังตลอดไม่ได้ เมืองกำลังถูกยึดขณะที่เราคุย!\n\nArchmage Modera ส่งข้ามาขอความช่วยเหลือภายนอก ไปหาร่างภาพนางใกล้ Dalaran ข้าง Lordamere Lake", variants = { { "486:1815654508:1662933796", "ข้านำข่าวร้ายจาก Dalaran บางสิ่งรบกวนสายพลังเวท ทำให้สิ่งประดิษฐ์เวทในเมืองทำงานผิดปกติและทำลายล้าง\n\nยังไม่รู้สาเหตุ สภาสูงสั่งเก็บเป็นความลับไม่ให้องค์กรอับอาย แต่ปิดบังตลอดไม่ได้ เมืองกำลังถูกยึดขณะที่เราคุย!\n\nArchmage Modera ส่งข้ามาขอความช่วยเหลือภายนอก ไปหาร่างภาพนางใกล้ Dalaran ข้าง Lordamere Lake" } } },
        completion = { "216:681867417:30025793", "ดูเหมือน Jacques หาคนช่วยสำเร็จ\n\nแม้ไม่ตรงระเบียบนัก เราจะให้ทิฐิผลักไสพันธมิตรในยามสิ้นหวังไม่ได้ อย่าให้ยามหลอก สถานการณ์ไม่ได้อยู่ในการควบคุมเลย" },
        logReady = { "64:1765579308:1047644068", "รายงานต่อ Image of Archmage Modera ใกล้ City of Dalaran" },
    },
    [92434] = { -- Blood in the Streets
        title = { "20:1443095117:1622498153", "เลือดบนถนน" },
        objective = { "49:1174326443:1048978470", "หาทางเข้า Dalaran ตามแนว Lordamere Lake" },
        description = { "404:822136799:96158217", "สิ่งที่ทำให้ม่านพลัง Dalaran ลดลงทำให้เมืองวุ่นวาย เมื่อเจ้าจัดการหน่วยลาดตระเวนแล้ว ไม่มีเวลาใดเหมาะกว่าตอนนี้ที่จะเข้าไปไขความลับ\n\nนำกุญแจจากค่ายกักกันไปหาท่อระบายน้ำตามชายแดนเหนือเมือง หากโชคดี จอมเวทคงไม่คิดลงอาคมป้องกันทางเข้าอัน...ไม่น่ารื่นรมย์นี้" },
        completion = { "162:791958078:1292174365", "คงไม่ใช่เรื่องบังเอิญที่ Horde สนใจเมืองข้าในยามคับขัน\n\nจริง ๆ ข้าคาดหวังไว้ ข้ามีข้อเสนอให้เจ้า" },
        progress = { "18:249329339:1668470166 R 164:2110910640:1293776362", "เก็บอาวุธก่อน {race}\n\nเจ้าคงพบว่ากุญแจนั้นยังไม่พอผ่านอาคมข้า ไม่ได้คิดจริง ๆ ใช่ไหมว่าเราจะเปิดจุดอ่อนเช่นนี้ไว้ในยามนี้?", variants = { { "190:1537187967:1561261211", "เก็บอาวุธก่อน สกายบอร์น\n\nข้าว่าเจ้าคงพบว่ากุญแจนั้นยังไม่พอจะผ่านอาคมป้องกันของข้า เจ้าคงไม่ได้คิดจริง ๆ ใช่ไหมว่าเราจะปล่อยจุดอ่อนเช่นนี้ไว้ในยามนี้?" } } },
        required = { [279469] = { "9:568529493:2071881639", "กุญแจเปื้อนคราบสกปรก" } },
        steps = { { "9:568529493:2071881639", "กุญแจเปื้อนคราบสกปรก" } },
        objectiveLabels = {
            event = { ["Find a way into Dalaran along the Lordamere Lake"] = "หาทางเข้า Dalaran ตามแนวทะเลสาบ Lordamere" },
        },
    },
    [92459] = { -- Friend of the Kirin Tor
        title = { "23:1776770402:15145086", "มิตรแห่ง Kirin Tor" },
        objective = { "50:1586537570:1564039885", "คุยกับ Archmage Celindra ใน City of Dalaran" },
        description = { "262:2087585398:1337594436", "สภาคงไม่พอใจแผนลับของเรา แต่ปฏิเสธผลงานไม่ได้ เมืองสงบลง เราลดอาคมป้องกันได้แล้ว\n\nข้าว่าเป็นธรรมที่เจ้าจะนำข่าวดีไป นำเศษพลังนี้ให้ Archmage Celindra ใน Violet Citadel" },
        progress = { "65:2087811471:127489021", "Archmage Modera ชื่นชมเจ้า อะไรพามา Dalaran?" },
        completion = { { "275:936930261:309488510", "227:764449207:1446572029 N 38:1946111703:1586494280", "227:764449207:1446572029 C 38:1946111703:1586494280", "227:764449207:1446572029 R 38:1946111703:1586494280" }, "เจอสิ่งนี้ที่ไหน? ห้องรับแขกหรือ?\n\nสีหน้า Archmage Celindra หม่นลงครู่หนึ่งก่อนสงบอีกครั้ง\n\nสหาย ข้าว่าเจ้าควรลืมเรื่องนี้เสีย ตอนนี้ Kirin Tor ยินดีต้อนรับนักผจญภัยมีฝีมือเช่นเจ้า ยินดีต้อนรับสู่ Dalaran", variants = { { "229:10611440:2127519753 C 38:1946111703:1586494280", "เจอสิ่งนี้ที่ไหน? ห้องรับแขกหรือ?\n\n<สีหน้า Archmage Celindra หม่นลงครู่หนึ่งก่อนสงบอีกครั้ง>\n\nสหาย ข้าว่าเจ้าควรลืมเรื่องนี้เสีย ตอนนี้ Kirin Tor ยินดีต้อนรับ{class}ผู้มีฝีมือเช่นเจ้า ยินดีต้อนรับสู่ Dalaran" }, { "219:2009473927:1430378697 C 37:937782561:1653864801", "เจอสิ่งนี้ที่ไหน? ห้องรับแขกหรือ?\n\n<สีหน้าของอัครจอมเวท Celindra หม่นลงครู่หนึ่ง ก่อนนางจะรวบรวมสติได้อีกครั้ง>\n\nสหาย ข้าว่าเจ้าควรลืมเรื่องนี้เสีย ตอนนี้ Kirin Tor ยินดีต้อนรับ{class}ที่มีฝีมืออย่างเจ้า ยินดีต้อนรับสู่ Dalaran" } } },
        required = { [251961] = { "11:575954581:468956656", "ละอองเวทอาร์เคน" } },
        steps = { { "11:575954581:468956656", "ละอองเวทอาร์เคน" } },
    },
    [93680] = { -- Key to the City
        title = { "15:661190692:907364759", "กุญแจสู่เมือง" },
        objective = { "73:1801549242:24954830", "หา Dalaran Sewer Key ให้ Magus Wordeen Voidglare ที่ Tarren Mill" },
        description = { "488:146313732:1192488507", "Alliance เคยมีกองทัพจอมเวท Kirin Tor แม้ทรงพลัง Burning Legion ปีศาจก็ยิ่งกว่า จอมปีศาจ Archimonde ทำลายเมืองในคราวเดียวราวของเล่นเด็ก ผู้รอดเหลือเพียงคนพเนจรไร้บ้าน\n\nจนพวกมันสร้าง Dalaran ใหม่ และมาตั้งหน้าประตู Dark Lady เสียด้วย!\n\nเมื่ออยู่ในค่าย ค้นหาของที่พาเราเข้าเมืองโดยไม่ถูกเห็น ข้าต้องรู้เพิ่ม" },
        progress = { "53:288285964:865275669", "พบอะไร? ตำราโบราณ? วัตถุลับ?" },
        completion = { "123:638206067:538273464", "กุญแจท่อระบายน้ำหรือ? โชคดีที่ข้าไม่ใช่คนต้องใช้\n\nแต่ยังมีงานต้องทำก่อนใช้ได้ปลอดภัย" },
        required = { [279469] = { "9:568529493:2071881639", "กุญแจเปื้อนคราบสกปรก" } },
        objectiveLabels = {
            item = { ["Grimy Key"] = "กุญแจเปื้อนคราบสกปรก" },
        },
    },
    [95534] = { -- Strahnbrad Mystery
        title = { "18:1620225701:1227296335", "ปริศนา Strahnbrad" },
        objective = { "78:1159870008:1518710649", "ไขปริศนา Strahnbrad แล้วรายงานสิ่งที่พบในเมืองที่ Hillsbrad" },
        description = { "362:1212581342:1513145167", "<บันทึกไหม้บางจุดแต่ยังอ่านได้>\n\nลือว่าสูบลมเก่าพวกนั้นมีจิตใจเอง ขยับขึ้นมาเมื่อไม่มีใครมอง ข้าไม่สนว่าเป็นเรื่องผี เจ้าต้องหาความจริงก่อนข้ากลับ\n\nมีพลังยิ่งใหญ่ใน Strahnbrad ข้ารู้\n\n<ส่วนที่เหลือไหม้และฉีกขาด ราวถูกเวทไฟ>" },
        completion = { "176:953374226:251849261", "งั้นมีธาตุไฟอาศัยอยู่ในสูบลมเก่าที่ Strahnbrad หรือ ปริศนาจริง ๆ คงเป็นว่ามันไปอยู่ในนั้นได้อย่างไร อย่างไรก็ทำได้ดี เจ้าจะได้รับรางวัลตอบแทน" },
        steps = { { "40:633264872:1733368709", "ไขปริศนาเรื่องไฟที่ Strahnbrad" } },
    },
    [97287] = { -- Shrewd Negotiations
        title = { "19:723711262:1113108540", "การเจรจาอันชาญฉลาด" },
        objective = { "52:901294394:1958399690", "คุยกับ Archmage Celindra ใน City of Dalaran", variants = { { "53:197755917:1760774380", "คุยกับ Image of Archmage Modera ใกล้ Dalaran" } } },
        description = { "501:1250684942:1685486806", "เจ้าแทรกซึมเมืองจอมเวทได้ดี แต่ข้าว่าถึงเวลา...เจรจามากขึ้น\n\nแม้ไม่อยากยอมรับ ไม่มีที่ใดบน Azeroth มีความรู้อาร์เคนกว้างขวางเท่านี้ งานอันปราดเปรื่องข้ายังเทียบภูมิปัญญาโบราณที่ Kirin Tor สะสมหลายปีไม่ได้ ถึงเวลาให้เราเข้าถึงองค์กรพิเศษนี้แล้ว ว่าไหม?\n\nนำเศษพลังที่เจ้าได้มาไป พวกเขาต้องยอมทุกอย่างเพื่อเอาคืน ทุกอย่าง" },
        completion = { "59:1215994577:1747910473 R 306:1356255284:241621140", "เจ้าจะให้ของนี่... ด้วยความเต็มใจหรือ\n\nข้าไม่รู้ว่าเจ้าคิดเล่นอะไรอยู่ {race} แต่ก็ปฏิเสธไม่ได้ว่าการที่เจ้าเข้ามาช่วยในช่วงเปราะบางนี้มีค่าต่อพวกเรา ข้าจะให้เจ้าเข้าเมืองแลกกับละอองเวท แต่จงรู้ไว้ว่าเราจะจับตาดูเจ้าอย่างใกล้ชิด\n\nทีนี้ไปได้แล้ว ระหว่างที่ Kirin Tor หารือกันต่อ ภาวนาไว้เถอะว่าเราจะไม่มีเหตุให้ตำหนิเจ้า", variants = { { "59:1215994577:1747910473 R 229:1982629517:1593653937", "เจ้าจะมอบสิ่งนี้ให้... ด้วยความเต็มใจหรือ?\r\n\r\nข้าไม่รู้ว่าเจ้าคิดอะไรอยู่ {race} แต่ปฏิเสธไม่ได้ว่าการเข้ามาช่วยของเจ้านั้นมีค่าในช่วงที่พวกเรากำลังเปราะบางเช่นนี้ ตอนนี้ข้าไม่มีอำนาจอนุญาตให้เจ้าเข้าเมือง แต่สักวัน... ก็อาจเป็นไปได้ สำหรับตอนนี้คงต้องรับคำขอบคุณของเราไปก่อน" } } },
        progress = { "17:1424020055:908963632", "อ้อ เจ้ากลับมาแล้ว", variants = { { "19:112946921:221539821 C 101:1257262559:684899505", "เจ้าคือ{class}ฝั่ง Horde ที่ Modera พูดถึงสินะ บอกมาซิว่าทำไมข้าถึงไม่ควรบดขยี้แก่นพลังของเจ้าให้เป็นผงเสียเดี๋ยวนี้" } } },
        required = { [251961] = { "11:575954581:468956656", "ละอองเวทอาร์เคน" } },
        steps = { { "11:575954581:468956656", "ละอองเวทอาร์เคน" } },
    },
    [98059] = { -- Hillsbrad's Hoard
        title = { "17:1055886464:1008948793", "คลังสมบัติ Hillsbrad" },
        objective = { "102:1360147524:271621063", "วาง Sealed Company Request ที่ได้รับบนโต๊ะทำบัญชีในศาลาว่าการ Hillsbrad" },
        description = { "452:2131478799:403162391", "สภา Hillsbrad ไม่ตอบจดหมายผู้ปกครองคนใหม่ของเรา ข่าวล่าสุดที่ข้าเค้นจากพ่อค้าผ่านทางเมืองนั้นก็แทบไม่ช่วยอธิบายความเงียบ\n\nเราขอเพียงหมวดทหารเล็ก ๆ แต่กลับได้ข่าวว่ามีเครื่องยิงลูกศรปิดล้อมหลายเครื่องสภาพสมบูรณ์อยู่ในบริเวณล้อมกำแพง\n\nเดินเข้าศาลาว่าการเหมือนพลเมืองนำคำร้องสำมะโนคืน แล้ววางนี่ให้เรียบร้อยบนโต๊ะทำบัญชี\n\nเสร็จแล้วกลับมาหาข้า" },
        completion = { "259:184757282:1558543057", "ทำได้ดี ทหาร ข้ารู้ว่าเจ้าไม่ได้ประจำการกับเรา แต่เราไม่เคยปฏิเสธคนมีฝีมือ\n\nถ้าจดหมายฉบับนี้ยังไม่ได้คำตอบ เราคงต้องพูดให้แรงกว่านี้\n\nหากต้องติดต่อชาวบ้านอีก เราจะเก็บชื่อเจ้าไว้เผื่อเรียกใช้งาน" },
        steps = { { "53:1895159983:937805697", "ส่ง Sealed Company Request ให้สภา Hillsbrad" } },
    },
    [98071] = { -- Brewer's Trade
        title = { "14:1451314630:104785617", "แลกเปลี่ยนของผู้ต้มเบียร์" },
        objective = { "133:1909730648:98748237", "ส่งขวด Fallrook Varietal ให้ Dun Garok ทางตะวันออกเฉียงใต้ Hillsbrad Foothills แล้วนำ Homebrew Hops หนึ่งกระสอบกลับมา" },
        description = { "498:1803299282:1523837066", "ข้าตกลงค้าขายกับพี่น้องผู้ต้มเบียร์ Dun Garok มานิดหน่อย ดูเหมือนไม่ใช่แค่เราที่คิดถึงไร่องุ่นตระกูล Fallrook! ไวน์ปีดี ๆ ส่วนใหญ่ดื่มหมดไปนานแล้ว แต่ยังมีอีกหลายลังในห้องใต้ดิน\n\nนำ Fallrook Varietal ลังนี้ไป Dun Garok ทางตะวันออกเฉียงใต้ วางไว้ข้างเตาผิงที่พวกเขานั่งรวมกันตรงชั้นล่างของป้อม\n\nขากลับนำ Homebrew Hops หนึ่งกระสอบมาแลก\n\nป้อมนั้นเป็นที่ใกล้เคียงบ้านที่สุดในแถบนี้!" },
        completion = { "58:540521590:1543649309 N 253:1014917289:1046888282", "กลิ่นฮอปส์ที่ข้าคิดถึงนี่เอง! เจ้าช่วยข้าไว้มาก {name} ข้าไป Dun Garok เองทีไร กว่าจะยอมออกจากที่นั่นก็หลายวัน พอนั่งสบายอยู่ในโถงป้อมแล้วก็ยากจะลุกจากไป\n\nข้ายินดีเก็บรสชาติแบบเก่า ๆ ไว้บนชั้นให้เพื่อนคนแคระได้ดื่มกัน\n\nรับนี่ไปเล็ก ๆ น้อย ๆ ที่ช่วยข้าไว้" },
        progress = { "25:1692696685:607330293", "อยากลองเอลชนิดใหม่หรือ?" },
        required = { [279389] = { "21:1307848299:1119924809", "กระสอบฮอปส์สำหรับหมักเบียร์สูตรพื้นบ้าน" } },
        steps = { { "40:225778861:1025639655", "ส่ง Fallrook Varietal ให้ Dun Garok" }, { "21:1307848299:1119924809", "กระสอบฮอปส์สำหรับหมักเบียร์สูตรพื้นบ้าน" } },
    },
    [495] = { -- The Crown of Will
        title = { "17:1633416585:710073109", "มงกุฎแห่งเจตจำนง" },
        objective = { "61:1658612953:110076343", "รายงานตัวต่อ Melisara ที่ Tarren Mill ใน Hillsbrad Foothills" },
        description = { "500:1069412145:1090398309", "Mug'Thol กับกองรบออเกอร์ถูกส่งไป Alterac เพื่อเอา Crown of Will ให้ Lady Sylvanas แต่น่าเสียดาย แทนที่จะนำกลับ เจ้าโง่กลับลองสวม... ข้าว่าออเกอร์ห้ามใจต่อของสว่างแวววาวไม่ได้\n\nความซุ่มซ่ามนั้นกลายเป็นปัญหา Crown of Will ทำให้เขาต้านการครอบงำที่บังคับให้รับใช้ Lady Sylvanas ได้\n\nDark Lady ต้องการลงโทษให้เป็นตัวอย่าง เดินทางไป Tarren Mill ใน Hillsbrad แล้วรายงานตัวต่อ Melisara มือรองของข้า" },
        completion = { "192:48214198:1782989368", "Shalindra ส่งเจ้ามาหรือ? ดี เจ้าจะพบว่าข้าไม่เสียเวลากับคำคุยไร้สาระนัก\n\nMug'Thol เป็นเสี้ยนหนาม เราจะจัดการเร็ว เด็ดขาด และไม่ให้เกิดเรื่องยุ่งยาก" },
    },
    [3102] = { -- Encrypted Letter
        title = { "16:71494942:1416341860", "จดหมายเข้ารหัส" },
        objective = { "92:1000248895:2062772623", "อ่าน Encrypted Letter แล้วคุยกับ Jorik Kerridan ในคอกสัตว์หลัง Northshire Abbey" },
        description = { "91:566813027:607752075 N 178:1140028954:1583208614", "มีคนขอให้ข้านำเรื่องนี้มาบอกทันทีที่เจ้ากลับจากค่ายโคบอลด์ {name} ดูเหมือนเป็นจดหมายผนึกตรา Jorik ครูฝึกคนหนึ่งประจำถิ่น ข้าคงไม่รออ่านก่อนทำธุระอื่นใน Abbey" },
        progress = { "278:1519519768:326609267", "มาถึงครบชิ้น และดูเหมือนมีคนเห็นไม่มาก แค่นั้นข้าก็พอใจ ไม่ชอบให้คนสนใจแถวหลังนี่... สงบเงียบดี คงเข้าใจ\n\nเจอปัญหาหรือยัง? ดีใจที่ยังไม่เจอ อีกไม่นานคงเปลี่ยน" },
        completion = { { "61:293836125:960420421 N 419:1004146883:635975899", "61:293836125:960420421 N 421:1371963319:632556655" }, "เจ้าจะพบหลายกลุ่มต้องการทักษะเรา {name} นักผจญภัย SI:7... แม้แต่ Defias Brotherhood ก็คงไม่รังเกียจสายลับสักคนสองคนใน Stormwind แต่จำไว้ เจ้าเป็นตัวของตัวเอง อย่าให้ใครบังคับทำสิ่งไม่อยากทำ! อีกอย่างเราถือไพ่เหนือกว่า... อย่างน้อยก่อนเกมจบ เข้าใจไหม?\n\nอย่างไรก็แค่อยากแนะนำตัว และบอกว่าอยู่ที่นี่หากต้องการฝึก แวะมาเมื่อใดก็ได้" },
        required = { [9555] = { "16:71494942:1416341860", "จดหมายเข้ารหัส" } },
        steps = { { "16:71494942:1416341860", "จดหมายเข้ารหัส" } },
    },
    [7321] = { -- Soothing Turtle Bisque
        title = { "22:1404935872:1008943184", "ซุปเต่าบำรุงใจ" },
        objective = { "93:34338977:1029924198", "นำ Turtle Meat 10 ชิ้น และ Soothing Spices จำนวนหนึ่งไปให้ Christoph Jeffcoat ใน Tarren Mill" },
        description = { "488:1545765031:1730474803", "ใครบอกว่าพวกอันเดดไม่รู้เรื่องทำอาหาร? อย่างสูตรลับซุปข้นเต่าของข้านี่ไง ข้ารู้จักคนที่ถึงกับยอมฟื้นจากความตายเพื่อมากินสักชาม! หึ หึ...\n\nพูดถึงเรื่องนั้น ช่วงนี้ข้าไม่ได้ทำเลย เมื่อก่อนข้าไปล่า Snapjaw ตัวร้ายพวกนั้นที่ Lake Lordamere เอง แต่ตอนนี้ทิ้งงานที่นี่ไปไม่ได้\n\nหากเจ้านำ Turtle Meat จากพวก Snapjaw กับ Soothing Spices มาให้ ข้าจะสอนวิธีทำ!" },
        progress = { "165:121215333:11451146", "หาวัตถุดิบได้บ้างไหม? จะบอกให้ พวกหนอนแมลงวัน Alliance ในแถบนี้มีมากเกินไปแล้ว... ข้าว่าพวกมันเข้ามาใกล้เกินไปแล้วด้วย..." },
        completion = { "101:152880244:1217559976", "ซุปข้นเต่ารสละมุนของข้าจะทำให้เจ้าอบอุ่นในคืนหนาว... หากเจ้ายังใส่ใจเรื่องแบบนั้นน่ะนะ" },
        required = { [3712] = { "11:706164050:819578527", "เนื้อเต่า" }, [3713] = { "15:570335490:1770959346", "เครื่องเทศรสละมุน" } },
        steps = { { "11:706164050:819578527", "เนื้อเต่า" }, { "15:570335490:1770959346", "เครื่องเทศรสละมุน" } },
    },
    [635] = { -- Crystal in the Mountains
        title = { "24:1321213865:1464615740", "ผลึกในขุนเขา" },
        objective = { "34:1762985669:1085243077", "ตามหาผลึกที่เห็นในนิมิต" },
        description = { "324:1527324602:1982764307", "เศษผลึกเต้นเป็นจังหวะขณะเจ้าถือ...\n\nเจ้ารู้สึกถึงคำวิงวอนจากผลึก ราวมีใครพยายามติดต่อ ผู้ที่ต้องการความช่วยเหลืออย่างสิ้นหวัง\n\nนิมิตปรากฏในใจ เป็นภูเขาทางเหนือ Arathi กับผลึกสว่างเจิดจ้าผุดจากพื้นดิน\n\nเจ้ารู้สึกถูกดึงดูดไปที่นั่น" },
        completion = { "63:1894038134:20200100", "ผลึกเต้นเป็นจังหวะ ราวมีกำลังชีวิตถูกกักภายใน" },
    },
    [636] = { -- Legends of the Earth
        title = { "20:1433156912:939455419", "ตำนานแห่งผืนดิน", variants = { { "26:1407962910:134787835", "ตำนานแห่งผืนดิน <NYI>" } } },
        objective = { "27:279918422:1634256058", "ตามหา Shards of Myzrael" },
        description = { { "350:199376894:2133975056", "351:1509305060:1798261932" }, "หนังสือเล่าเรื่อง Myzrael เจ้าหญิงธาตุ และการถูกขังลึกใต้ Arathi Highlands\n\nยังกล่าวถึงกลุ่มผลึกลับที่ผุดบนที่ราบสูง ผลึก Shards of Myzrael เป็นหน้าต่างสู่คุกเจ้าหญิง\n\nหากผู้กล้าพบผลึก บางทีอาจพูดกับนางได้..." },
    },
    [639] = { -- Sigil of Strom
        title = { "14:66732209:1402164162", "ตราแห่ง Strom" },
        objective = { "47:979519090:195617060", "หา Sigil of Strom ให้ Zengu ที่ Hammerfall" },
        description = { "497:408637491:498183704", "สมัยโบราณ โทรลล์รบกับจักรวรรดิ Arathorian ศัตรูเก่งกาจที่สุดคือ Lord Ignaeus แห่ง Strom ผู้ได้ชื่อ Trollbane เข้าศึกพร้อม Trol'kalar ซึ่งแปลว่าผู้สังหารโทรลล์ในภาษาโบราณ\n\nแต่บัดนี้ลูกหลาน Trollbane อ่อนแอ ที่มั่นพังทลาย\n\nดาบถูกป้องกันด้วยตราหลายอัน แบ่งให้ผู้รอดจาก Stromgarde เราต้องนำมา\n\nอันแรก Syndicate ชิงไป คนของมันใน Stromgarde น่าจะมี" },
        progress = { "123:395481295:704033764", "พบตราแรกหรือยัง? น่าจะอยู่กับสมาชิก Syndicate คนหนึ่งใน Stromgarde" },
        completion = { "115:494365173:597516276", "ยอดเยี่ยม สหาย เริ่มเก็บตราที่ต้องใช้เอา Trol'kalar จากสุสาน Trollbane ได้ดีแล้ว" },
        required = { [4440] = { "14:66732209:1402164162", "ตราผนึกแห่ง Strom" } },
        steps = { { "14:66732209:1402164162", "ตราผนึกแห่ง Strom" } },
    },
    [640] = { -- The Broken Sigil
        title = { "16:832387974:974573785", "ตราที่แตกหัก" },
        objective = { "106:1158587827:1744968130", "เก็บ Sigil Fragments 11 ชิ้น จากผู้ป้องกัน Stromgarde แล้วนำไปให้ Tor'gan ที่ Hammerfall" },
        description = { "445:1141902787:1277177341", "สุสาน Thoras Trollbane มีตราป้องกันสามอัน อันแรกเจ้าเอาจาก Syndicate มาแล้ว อีกสองอันยากกว่า เพราะอยู่กับกองกำลัง Stromgarde ที่ตั้งมั่นแน่นหนา\n\nGalen ลูกชาย Thoras แบ่งตรา Thoradin เป็นสิบเอ็ดชิ้น แจกผู้ป้องกัน Stromgarde เก็บไปให้ Tor'gan ชามานโทรลล์ เขาจะประสานคืนเป็นตราสมบูรณ์ได้" },
        progress = { "10:1652484069:1189355142 C 52:908039225:1402971990", "Throm'ka {class} Zengu แจ้งว่าเจ้าต้องการความช่วยเหลือข้า?" },
        completion = { "191:539716271:809631298", "อา ให้ข้าประกอบตรานี้คืนหรือ? คงไม่ยาก ชิ้นส่วนดูครบ โครงสร้างเวทก็คืนรูปง่าย\n\nเจ้าคงอยากหลับตาไว้" },
        required = { [4450] = { "14:1476796346:1494527091", "เศษตราผนึก" } },
        steps = { { "14:1476796346:1494527091", "เศษตราผนึก" } },
    },
    [641] = { -- Sigil of Thoradin
        title = { "17:2086845711:1271218440", "ตราแห่ง Thoradin" },
        objective = { "60:1610212957:134695132", "นำ Sigil of Thoradin ที่ซ่อมแล้ว ไปให้ Zengu ที่ Hammerfall" },
        description = { "177:27549221:801187035", "การประกอบคืนสมบูรณ์แบบ ตราใช้ปลดผนึกสุสาน Trollbane ได้แล้ว นำคืน Zengu เขาคงมีงานอื่นให้ทำอีก" },
        progress = { "N 31:1670169150:575700099", "{name}! มีตราที่สองหรือยัง?" },
        completion = { "225:306883284:1309495481", "เราเดินมาได้ครึ่งทางสู่การนำ Trol'kalar จากสุสาน Trollbane ยังไม่รู้แน่ว่าตราที่สามอยู่ไหน เพราะผู้ถือเดินทางทั่ว Arathi แต่ข้าเชื่อว่าเจ้าหาได้" },
        required = { [4453] = { "17:2086845711:1271218440", "ตราสัญลักษณ์ของ Thoradin" } },
        objectiveLabels = {
            item = { ["Sigil of Thoradin"] = "ตราสัญลักษณ์ของ Thoradin" },
        },
    },
    [642] = { -- The Princess Trapped
        title = { "20:720218924:1962637553", "เจ้าหญิงที่ถูกขัง" },
        objective = { "89:1750818649:1502185742", "เก็บ Motes of Myzrael 12 ชิ้น แล้วนำไปให้ Iridescent Shards ที่ Drywhisker Gorge" },
        description = { "437:1157548025:1076284367 N 9:2124928137:608558242", "ข้าชื่อ Myzrael เจ้าหญิงแห่งผืนดิน ยักษ์ผู้จับขังข้าไว้ลึกใต้ Arathi Highlands เศษผลึกเหล่านี้เป็นทางเดียวที่ข้าพูดกับโลกเบื้องบนได้\n\nช่วยด้วย โคโบลด์ Drywhisker พันธมิตรยักษ์ มีผลึกเช่นนี้ใน Drywhisker Gorge ทางตะวันออก เพื่อเพิ่มพลังกลุ่มผลึก เจ้าต้องเก็บ Motes of Myzrael จากโคโบลด์มาใช้กับมัน\n\nข้าวิงวอน {name} ช่วยข้าเถิด!" },
        progress = { "123:1878805883:717218914", "กลุ่มผลึกนี้คล้าย Shards of Myzrael มาก แต่ไม่แผ่ความรู้สึกปลอดภัยแบบเดียวกัน" },
        completion = { "97:1389673210:1163236967", "อา! เจ้ากระตุ้นผลึกแล้ว ข้ารู้สึกกลับเป็นตัวเองมากขึ้น!\n\nแต่อนิจจา ยังห่างไกลอิสรภาพ..." },
        required = { [4435] = { "15:1110324083:463132186", "ละอองพลังของ Myzrael" } },
        steps = { { "15:1110324083:463132186", "ละอองพลังของ Myzrael" } },
    },
    [643] = { -- Sigil of Arathor
        title = { "16:2089387803:700085025", "ตราแห่ง Arathor" },
        objective = { "67:597493800:240258398", "นำ Sigil of Arathor กลับไปให้ Zengu ที่ Hammerfall" },
        description = { "415:1657823224:1769208624", "แม้แทบคุม Stromgarde ไม่ได้ อย่าว่าแต่ Arathi Highlands ทั้งหมด เจ้าชายมนุษย์ยังนำทหารม้าที่เหลือเดินทั่วชนบท ข้าไม่เข้าใจว่าทำไม แต่ใครเข้าใจความคิดมนุษย์บ้างล่ะ?\n\nไม่ว่าเหตุผลใด ที่สำคัญคือเขามอบตราหนึ่งให้ Lieutenant Valorcall ผู้นำทหารม้า หาแล้วนำตรามาให้ข้า" },
        progress = { "42:1242170153:313409990 N 89:317882976:1164567730", "ตามหา Valorcall ไม่ง่าย {name} เขาขี่ม้าจึงเดินทางเร็ว แต่เราต้องได้ตราเขา" },
        completion = { "178:1555414423:65003376", "เสียผู้นำทหารม้าจะกระทบผู้ป้องกัน Stromgarde หนัก ยิ่งกว่านั้น เราขาดเพียงอีกตราเดียวก็จะได้ Trol'kalar มา" },
        required = { [4458] = { "16:2089387803:700085025", "ตราผนึกแห่ง Arathor" } },
        steps = { { "16:2089387803:700085025", "ตราผนึกแห่ง Arathor" } },
    },
    [644] = { -- Sigil of Trollbane
        title = { "18:1081583115:1327362346", "ตราแห่ง Trollbane" },
        objective = { "84:1605927840:1660326744", "ฆ่า Prince Galen Trollbane แล้วนำ Sigil of Trollbane ไปให้ Zengu ที่ Hammerfall" },
        description = { "286:147086784:431412268", "ตราสุดท้ายสำหรับเปิดสุสาน Thoras Trollbane อยู่กับลูกชายเขาเอง เขาอยู่ลึกใน Stromgarde ในโบสถ์เขตที่กองกำลังคุม Prince Galen มีคนป้องกันแน่นหนาและเป็นนักรบเก่งกาจ งานนี้คงยากยิ่ง" },
        progress = { "17:1659610970:2055106361 N 42:1611066673:1562392301", "กลับมาแล้ว {name} สายเลือด Ignaeus Trollbane สิ้นแล้วหรือ?" },
        completion = { "21:894774286:424024597 C 191:1404103276:736588443", "ช่างเป็นวันสำคัญ {class} เลือด Trollbane จะไม่หลอกหลอนคนของข้าอีก ตราที่ต้องใช้เอา Trol'kalar อยู่กับเราแล้ว เร็ว ๆ นี้เราจะโจมตีโทรลล์ Zul'Gurub ที่เกลียดชัง" },
        required = { [4466] = { "18:1081583115:1327362346", "ตราผนึกของ Trollbane" } },
        steps = { { "18:1081583115:1327362346", "ตราผนึกของ Trollbane" } },
    },
    [645] = { -- Trol'kalar
        title = { "10:1391928496:1740468826", "Trol'kalar" },
        objective = { "56:536619866:1103611173", "นำ Trol'kalar จากสุสาน Trollbane ใน Stromgarde" },
        description = { "297:746287190:51241857", "อะไรนี่? เมื่อนำตราทั้งสี่มารวม มันกลายเป็นตราเดียว ต้องปลดอาคมป้องกันสุสาน Trollbane ได้แน่\n\nร่าง Trollbane ฝังใน Sanctum หลังโบสถ์ Stromgarde จงนำ Trol'kalar มา" },
        progress = { "111:383221512:288966184", "รอยสลักหินบนหน้าสุสาน Trollbane ตรงกับเส้นเรืองแสงของ Sigil of Ignaeus..." },
        completion = { "210:437522165:676073907", "เมื่อจับเส้นบนหน้าสุสาน Trollbane ให้ตรงกับเส้นเรืองของ Sigil of Ignaeus แสงวาบกลืนตรา แล้วดาบในตำนาน Trol'kalar ก็หลุดจากมือหินที่กำไว้" },
        required = { [4467] = { "16:1337312691:1649095761", "ตราผนึกของ Ignaeus" } },
        steps = { { "16:1337312691:1649095761", "ตราผนึกของ Ignaeus" } },
    },
    [646] = { -- Trol'kalar
        title = { "10:1391928496:1740468826", "Trol'kalar" },
        objective = { "42:379962458:1086254695", "ส่ง Trol'kalar ให้ Zengu ที่ Hammerfall" },
        description = { "91:894256287:1994311870", "แสงค่อย ๆ จาง ดาบ Trol'kalar ที่อยู่ในฝักหินถูกปลดออกแล้ว" },
        progress = { "N 27:418242777:421746039", "{name}! นำดาบมาหรือยัง?" },
        completion = { "217:801751855:1847146376 N 114:659009646:82490232", "หลายชั่วอายุ กองทัพ Strom กับ Arathor ทำลายโทรลล์ บัดนี้อาวุธยิ่งใหญ่ที่สุดอยู่ในมือเรา เราจะไม่ต้องคืบหน้าอย่างเชื่องช้าในป่าร้อนชื้น Zul'Gurub อีก\n\nเจ้าช่วยมหาศาล {name} โทรลล์ Darkspear เป็นหนี้บุญคุณเจ้า\n\nข้าจะให้ส่งดาบถึง Nimboya ที่ Grom'gol แน่นอน" },
        required = { [4468] = { "19:604529248:732405308", "ดาบ Trol'kalar ในฝัก" } },
        steps = { { "19:604529248:732405308", "ดาบ Trol'kalar ในฝัก" } },
    },
    [651] = { -- Stones of Binding
        title = { "17:1960070653:813123118", "ศิลาพันธนาการ" },
        objective = { "195:1821828480:1775662217", "เก็บ Burning Key, Cresting Key และ Thundering Key จาก Stone of West Binding, Stone of East Binding และ Stone of Outer Binding\n\nนำไปให้ Stone of Inner Binding" },
        description = { "341:1814903161:1987368544", "ศิลาพันธนาการสี่แห่งกระจายทั่ว Arathi มันกดข้าไว้ใต้ดิน\n\nเพื่อปลด ต้องเปิดศิลาที่แข็งแกร่งที่สุด Stone of Inner Binding ก่อน โดยเก็บกุญแจจากอีกสามแห่ง\n\nมีผู้พิทักษ์เฝ้า แต่หากฉลาดหรือโชคดี เจ้าอาจหาทางขับไล่มันได้" },
        progress = { "122:2128155114:777395004", "นี่คือ Stone of Inner Binding แข็งแกร่งที่สุด ต้องปลดก่อนศิลาอื่นจึงจะเปิด" },
        completion = { "176:654797323:6184850 C 2:11340:5796 N 13:1791010674:92069706", "<Myzrael พูดผ่านศิลา>\n\nทำได้แล้ว! เจ้าปลดศิลาพันธนาการ! ข้ารู้สึกว่าโซ่ตรวนคลาย อิสรภาพใกล้ขึ้นทุกที\n\nเจ้าเป็น {class} ผู้สูงส่ง {name} ผู้ช่วยชีวิตข้า!" },
        required = { [4483] = { "11:1750293968:551017932", "กุญแจเพลิงลุกโชน" }, [4484] = { "12:519000465:671302784", "กุญแจยอดคลื่น" }, [4485] = { "14:2104646686:731482006", "กุญแจเสียงฟ้าร้อง" } },
        steps = { { "11:1750293968:551017932", "กุญแจเพลิงลุกโชน" }, { "12:519000465:671302784", "กุญแจยอดคลื่น" }, { "14:2104646686:731482006", "กุญแจเสียงฟ้าร้อง" } },
    },
    [652] = { -- Breaking the Keystone
        title = { "21:116042880:2125590861", "ทลายศิลาหลัก" },
        objective = { "85:366413422:874528935", "หาและฆ่า Fozruk นำ Rod of Order ไปให้ Keystone ที่ Arathi Highlands" },
        description = { "341:788053606:117138869 N 118:1228203953:689229454", "เปิดศิลาพันธนาการช่วยคลายกรงข้ามาก แต่ยังมีกุญแจขังอยู่ นั่นคือ Keystone ในวงศิลานี้ ผู้จับข้าคนหนึ่ง Fozruk ผู้เฝ้าศิลา ถือกุญแจไว้\n\nเจ้าต้องเอาสิ่งที่ผู้เฝ้าศิลาเรียก Rod of Order จาก Fozruk แล้วใช้เปิด Keystone\n\n{name} เจ้าช่วยมากแล้ว อีกเพียงนิด...ความขอบคุณข้าจะสะเทือนรากฐานโลก!" },
        progress = { "57:202492511:959104868", "Keystone อัดแน่นด้วยพลังเวทปฐพีมหาศาล" },
        completion = { "71:590678346:1382158711", "เจ้าใส่คทาลงศิลาหลัก รู้สึกถึงแรงสั่นสะเทือนเบื้องล่าง..." },
        required = { [4469] = { "12:234691564:1084904498", "คทาแห่งระเบียบ" } },
        steps = { { "12:234691564:1084904498", "คทาแห่งระเบียบ" } },
    },
    [653] = { -- Myzrael's Allies
        title = { "16:1484240606:595303606", "พันธมิตรของ Myzrael" },
        objective = { "62:966788207:1370899440", "คุยกับ Gerrig Bonegrip ที่ Forlorn Cavern ใน Ironforge" },
        description = { "270:1715829876:1503536621 N 213:1132412238:151878565", "<Myzrael พูดขึ้น>\n\nอิสระ! ข้าเป็นอิสระ! จะหลบซ่อนรวบรวมกำลังได้ เพราะหากผู้จับข้าพบตอนนี้ มันคงชนะแล้วขังข้าอีก\n\nแต่เมื่อถึงเวลา ข้าจะเผชิญยักษ์ และมันจะเสียใจที่กักขัง!\n\nเจ้าคือพันธมิตรสูงส่ง {name} อีกไม่นานข้าจะต้องการเจ้า เมื่อพร้อม ข้าจะให้เรียกสู่พื้นผิว\n\nคุยกับ Gerrig Bonegrip เขาอยู่ร้านใน Forlorn Cavern ที่ Ironforge รู้วิธีเรียกข้า" },
        completion = { "33:636586147:1096888979 C 68:478052878:1963486759", "ท่านหญิงบอกว่าเจ้าจะมา {class} ยินดีต้อนรับสู่ที่อยู่ข้า เพราะเจ้าเหมือนข้า รับใช้จุดหมายที่สูงกว่า" },
    },
    [655] = { -- Hammerfall
        title = { "10:86322623:354471918", "Hammerfall" },
        objective = { "33:1957384512:677185232", "คุยกับ Tor'gan ที่ Hammerfall" },
        description = { "458:496992771:971199259", "ยังชัดเหมือนเมื่อวาน...หลายปีไร้หวัง ไม้และเหล็กขังข้าในที่น่าชังนี้ จนในที่สุด! Warchief มา Doomhammer ในเกราะดำเที่ยงคืน ชูค้อนศึกสูง\n\nมัน...โหดร้ายเกินไป...คนขลาดลอบสังหารวีรบุรุษยิ่งใหญ่ที่สุดของเรา มันขี่ม้าพุ่งจากด้านหลัง แทงทวนทะลุเขา...ข้าทรุดเข่า เหลือความหวังอะไร? ยังเหลือหวังอะไร..." },
        completion = { "380:257518559:1233164069", "อา เจ้าพูดถึง Gor'mul ใช่ จากที่เล่า เขาคงไม่เคยฟื้นจากความตาย Doomhammer\n\nGor'mul ถูกขังที่นี่ตอน Thrall กับ Orgrim รบปลดปล่อยค่าย แต่เมื่อแผ่นดินสั่นและพี่น้องหนี เขาถูกทิ้งไว้ เร่ร่อนลำพังหลายปีไร้ทิศไร้หวัง จนเรากลับมาตั้งหลักที่ Hammerfall" },
    },
    [656] = { -- Summoning the Princess
        title = { "22:99706999:500991010", "เรียกเจ้าหญิง" },
        objective = { "124:135459091:1745594243", "ไป Shards of Myzrael เรียกนางออกมาแล้วเอาชนะ\n\nเก็บ Eldritch Shackles ของนาง แล้วผูกเข้ากับ Shards of Myzrael" },
        description = { "497:1881400799:993934989", "ต้องเอาชนะ Myzrael ก่อนแข็งแกร่งขึ้น มิฉะนั้นเมื่อมีพลังพอ นางจะท้าทายผู้จับขัง! บางคนคิดว่าควบคุมนางได้ แต่หากควบคุมได้ ทำไมยักษ์ต้องล่ามไว้แต่แรก??\n\nตรรกะบ้าบอใช่ไหม?\n\nเพื่อปราบ จงเรียกนางที่ Shards of Myzrael จุดที่คุยครั้งแรก เอาชนะแล้วเก็บ Eldritch Shackles ผูกเข้ากับผลึก\n\nทำเช่นนั้น นางจะถูกขังอีกครั้ง" },
        progress = { "46:742578259:1493755847", "Shards of Myzrael เงียบอย่างประหลาด" },
        completion = { "320:873708673:1704388490", "เมื่อวางตรวนอาถรรพ์รอบผลึก เสียงหวีดที่ไม่ใช่มนุษย์ดังจากเบื้องล่าง ตามด้วยเสียงคำราม\n\nShards of Myzrael ไม่ให้ความอบอุ่นปลอดภัยเหมือนก่อน มันเต้นด้วยภัยคุกคามชัดเจน...ราวสิ่งเบื้องล่างประสงค์ร้ายต่อพื้นผิว" },
        required = { [4473] = { "17:1350160101:1315344516", "โซ่ตรวนมนตร์พิสดาร" } },
        steps = { { "17:1350160101:1315344516", "โซ่ตรวนมนตร์พิสดาร" } },
    },
    [662] = { -- Deep Sea Salvage
        title = { "16:1415400557:1719563240", "กู้ของใต้ทะเลลึก" },
        objective = { "114:1806944736:419903527", "First Mate Nilzlix ต้องการให้เจ้าเก็บ Charts และ Logs จาก Maiden's Folly และ Spirit of Silverpine" },
        description = { "493:1497578531:75318379", "O'Breen นำเรือเข้าอ่าว เรามั่นใจว่าสมบัติอยู่ที่นี่ Harbinger เทียบท่าปลอดภัย แต่เมื่อ Maiden's Folly กับ Spirit of Silverpine เข้าใกล้ น้ำเริ่มลด ประหลาดที่สุดที่เคยเห็น!\n\nสองลำเกยบางสิ่ง...คล้ายวิหารในแนวปะการัง จมเร็วมาก น่าเศร้าจริง\n\nก่อนจากไปต้องเอาทั้งสมุดปูมและแผนที่คืน ทิ้งข้อมูลให้สายตาคนสอดรู้ไม่ได้!" },
        progress = { "42:1277138231:1289360002 N 264:750606077:109303854", "ค้นหาและกู้ของเป็นอย่างไร {name}? ต้องได้สมุดปูมกับแผนที่จาก Maiden's Folly และ Spirit of Silverpine คืนจริง ๆ\n\nหากข้อมูลตกในมือศัตรู Fleet Master Seahorn จะบังคับเราเดินกระดานลงทะเล\n\nถ้าเรารอดจากเรื่องยุ่งนี้ได้นะ..." },
        completion = { "96:739151885:1223998690 N 1:46:46", "รู้ว่าข้อมูลปลอดภัยแล้ว กองบัญชาการ Booty Bay คงโล่งใจบ้าง ทำได้ดี {name}" },
        required = { [4487] = { "21:1122730484:145895421", "แผนที่เดินเรือของ Maiden's Folly" }, [4488] = { "27:801125327:2060202939", "แผนที่เดินเรือของ Spirit of Silverpine" }, [4489] = { "18:792147527:1395546804", "สมุดปูมเรือ Maiden's Folly" }, [4490] = { "24:1954379102:2142187363", "สมุดปูมเรือ Spirit of Silverpine" } },
        objectiveLabels = {
            item = { ["Maiden's Folly Charts"] = "แผนที่เดินเรือของ Maiden's Folly", ["Spirit of Silverpine Charts"] = "แผนที่เดินเรือของ Spirit of Silverpine", ["Maiden's Folly Log"] = "สมุดปูมเรือ Maiden's Folly", ["Spirit of Silverpine Log"] = "สมุดปูมเรือ Spirit of Silverpine" },
        },
    },
    [663] = { -- Land Ho!
        title = { "8:607942370:2000562208", "เห็นฝั่งแล้ว!" },
        objective = { "41:800425961:1841582650", "คุยกับ Captain O'Breen ที่ Faldir's Cove" },
        description = { "17:450780534:275045088 R 458:1047549546:1369155295", "Lolo เห็น {race} ตัวจิ๋ว! Lolo คอยระวังเสมอ!\n\nยินดีต้อนรับสู่ Faldir's Cove Captain O'Breen บอกจะอยู่ไม่กี่ชั่วโมง พอเก็บสมบัติแล้วกลับ Booty Bay\n\nแต่ Lolo ว่าคงนานกว่านั้นมาก เราเสียเรือร่วมขบวนอีกสองลำ Spirit of Silverpine กับ Maiden's Folly ผู้น่าสงสาร นอนก้นทะเลแล้ว!\n\nLolo แนะว่าถ้าจะอยู่ต่อ ไปคุย Captain O'Breen" },
        completion = { "471:1929525862:1240214771", "อาฮอย สหาย\n\nเรื่องยุ่งร้ายกาจ หาก Seahorn รู้เหตุการณ์ ต้องยึดเรือข้าแน่\n\nเครื่องมือศาสตราจารย์บอกว่าสมบัติสาบสูญอยู่ใกล้อ่าว ข้านำ Harbinger เทียบท่า ส่งสัญญาณให้ Spirit of Silverpine กับ Maiden's Folly ตาม\n\nแล้วทะเลครืน น้ำลด สองเรือชนแนวปะการัง\n\nไม่ใช่แค่ปะการัง มีบางอย่างข้างล่าง...\n\nช่วยลูกเรือข้า แล้วจะได้รางวัลงาม" },
    },
    [664] = { -- Drowned Sorrows
        title = { "15:1076890410:1581677862", "ความโศกใต้สมุทร" },
        objective = { "105:2025405291:57642914", "Captain Steelgut ที่ Faldir's Cove ต้องการให้เจ้าฆ่า Daggerspine Raiders 10 ตัว และ Daggerspine Sorceresses 3 ตัว" },
        description = { "494:235662537:464920328", "อ๊าก ชีวิตช่างเลวร้าย ข้าควรนอนในสุสานน้ำ ไม่ใช่นั่งข้างไฟสูดอากาศสด\n\nลูกเรือพยายามหนักเพื่อช่วย Maiden's Folly แสนงาม ขอพรคุ้มพวกเขา\n\nO'Breen ถึงฝั่งปลอดภัย แต่เราไม่โชคดี น้ำทะเลลดฮวบ สาบานได้\n\nชั่วครู่ยังลอยอยู่ ถัดมาน้ำไหลเข้า แล้วสัตว์ร้ายพวกนั้น! ฆ่าผู้รอดทั้งหมด สวะนากาน่าสยอง ข้าหมดสติ แล้วถูกช่วยมาอยู่ที่นี่\n\nข้าต้องการให้มันตาย" },
        progress = { "161:1522898819:1538725437", "ชิ ข้าคงต้องฆ่าสวะนากาเอง เห็นชัดว่าเจ้าไม่ทำ\n\nบางทีจะหาไม้นิตติ้งให้เจ้ามีอะไรทำเสียหน่อย" },
        completion = { "21:93874583:377803652 N 137:1329029432:244710978", "ทำได้ดี {name}\n\nสวะพวกนั้นสมควรแล้ว แม้ไม่มีอะไรคืนเรือหรือลูกเรือได้ ความตายนากาก็ปลอบข้าได้บ้าง" },
        objectiveLabels = {
            monster = { ["Daggerspine Raider slain"] = "ปราบ ผู้จู่โจม Daggerspine", ["Daggerspine Sorceress slain"] = "ปราบ แม่มด Daggerspine" },
        },
    },
    [665] = { -- Sunken Treasure
        title = { "15:1829519271:1005357415", "สมบัติจมทะเล" },
        objective = { "52:940373623:1957601859", "คุ้มกัน Professor Phizzlethorpe ไปถ้ำแล้วกลับมา" },
        description = { "480:1827749690:1108906950", "เมื่อเป็น Blackwater Raiders เต็มตัวแล้ว หน้าที่เราคือช่วยคุณ O'Breen หาสมบัติเอลฟ์สาบสูญ\n\nแทบเป็นไปไม่ได้ที่จะพบอัญมณีในทะเลมืดโดยไม่มีตัวช่วย ด็อกเตอร์ทำแว่นไว้ แต่ต้องเติมพลังจากหินลงมนตร์ในถ้ำบนเนิน\n\nถ้ำต้องสาป! พอเข้าใกล้ก็ถูกซุ่มโจมตี ปกป้องข้า แล้วข้าจะดึงพลังหินเข้าแว่นได้" },
        progress = { "84:1753575283:1121969540", "ไม่ใช่เวลาคุย! ต้องเติมพลังหินให้แว่น!" },
        completion = { "43:1338433481:1675666676 N 1:46:46", "ตอนนี้แว่นทำงานสมบูรณ์! ทำได้ดี {name}" },
        objectiveLabels = {
            event = { ["Defend Professor Phizzlethorpe"] = "ปกป้อง Professor Phizzlethorpe" },
        },
    },
    [666] = { -- Sunken Treasure
        title = { "15:1829519271:1005357415", "สมบัติจมทะเล" },
        objective = { "127:375546629:1425749134", "Doctor Draxlegauge ที่ Faldir's Cove ต้องการ Elven Gems 10 เม็ด และให้คืน Goggles of Gem Hunting เมื่อเสร็จ" },
        description = { "255:302033103:249705290 N 205:1133455710:1887139841", "สมบัติอยู่ก้นทะเลนานจนหินปูนจับอัญมณีเป็นหินหนา แต่พลังในแว่นช่วยหาง่าย\n\nความช่างคิดของโนมช่วยได้มาก!\n\nยืม Goggles of Gem Hunting ไป {name} ลองเก็บสมบัติสาบสูญให้ Captain O'Breen\n\nข้าจะว่ายลงเอง แต่...เอ่อ...มีงานวิทยาศาสตร์สำคัญบนบกแห้งปลอดภัย...เอ่อ ใช่" },
        progress = { "217:356931416:126594053", "แว่นเป็นอย่างไร? ทุกอย่างทำงานดีไหม? ปรับได้หากจำเป็น\n\nอ้อ เสร็จแล้วต้องคืนแว่น ข้ามั่นใจว่า Captain O'Breen ยังต้องใช้หลายอย่างภายหลัง" },
        completion = { "13:986202211:1010244040 N 94:1456785784:804593327", "ยอดเยี่ยมที่สุด {name}! กัปตันต้องพอใจ! รอจนข่าวถึง Fleetmaster Seahorn สิ!" },
        required = { [4492] = { "9:984512657:793240090", "อัญมณีของเอลฟ์" }, [4491] = { "22:1028789851:979715857", "แว่นตาสำหรับค้นหาอัญมณี" } },
        steps = { { "9:984512657:793240090", "อัญมณีของเอลฟ์" }, { "22:1028789851:979715857", "แว่นตาสำหรับค้นหาอัญมณี" } },
    },
    [667] = { -- Death From Below
        title = { "16:1649297870:1326299055", "มรณะจากเบื้องล่าง" },
        objective = { "41:455534554:1724879465", "ปกป้อง Shakes O'Breen ระหว่างการโจมตี" },
        description = { "486:1348764564:778095789 N 1:63:63", "แย่แล้ว Daggerspine ดูเหมือนรวมกำลังจะโจมตี\n\nนากาขึ้นชื่อว่าโหดเหี้ยมในศึก มันจะบุกไม่หยุดจนข้าตาย\n\nข้าไม่ได้เห็นชีวิตตนเหนือกว่าลูกเรือ แต่เจ้าต้องช่วยป้องกัน หากขาดความรู้ทะเลข้า พวกเขากลับ Booty Bay ไม่ได้\n\nนากาจะมาจากทะเล อยู่ข้างบนกับข้าต้านมัน ประจำปืนใหญ่แล้วขับไล่กลับไป\n\nพร้อมไหม {name}?" },
        completion = { "63:1629343050:2009541445 N 188:1904427684:680841444 R 4:783881400:104207664", "เรารอดการโจมตีแล้ว!\n\nหากไม่มีเจ้า คงทำไม่ได้ {name}\n\nเราจะออกเมื่อน้ำขึ้น หากเจ้าไม่ใช่วีรบุรุษอนาคตไกล ข้าจะชวนเข้าลูกเรือ แต่รู้ว่าเจ้ามีเรื่องใหญ่กว่าต้องทำ\n\nแม้เป็น {race} ตัวกระจ้อยก็เถอะ..." },
        progress = { "8:507580899:1259556094", "จับอาวุธ!" },
        objectiveLabels = {
            event = { ["Defend Shakes O'Breen"] = "ปกป้อง Shakes O'Breen" },
        },
    },
    [668] = { -- Sunken Treasure
        title = { "15:1829519271:1005357415", "สมบัติจมทะเล" },
        objective = { "39:1838054612:379531915", "นำ Elven Gems ไปให้ Captain O'Breen" },
        description = { "300:830300876:1998736307 N 24:287751783:1821407612", "อย่าปล่อย Captain O'Breen รอ เขาต้องอยากเห็นอัญมณีเอง นั่นคือเหตุผลที่เรามาที่นี่!\n\nหลังคลุกคลีกับโจรสลัดหลายสัปดาห์ ศาสตราจารย์กับข้ารู้ว่าถูกจับได้ว่าเก็บสมบัติพวกเขาไว้เองไม่ดีต่อสุขภาพที่สุด\n\nนี่ {name} นำไปให้ O'Breen" },
        progress = { "6:533059392:220789999 C 32:371972688:1494770856", "อาฮอย {class} อะไรพามาสะพานเดินเรือ?" },
        completion = { "105:2028363721:852704953", "โนมน้อยพิสูจน์คุณค่าได้สินะ? รู้ว่าเก็บเจ้าพวกกัดข้อเท้าไว้ต้องมีเหตุผล!" },
        required = { [4493] = { "10:1764166265:835237713", "อัญมณีของเอลฟ์" } },
        objectiveLabels = {
            item = { ["Elven Gems"] = "อัญมณีของเอลฟ์" },
        },
    },
    [669] = { -- Sunken Treasure
        title = { "15:1829519271:1005357415", "สมบัติจมทะเล" },
        objective = { "63:1017862285:74075844", "นำ Sample Elven Gem ไปให้ Fleet Master Seahorn ที่ Booty Bay" },
        description = { "456:1874642376:813143188", "Fleet Master Seahorn ต้องอยากรู้การค้นพบทันที\n\nแต่อย่างที่เห็น เราออกไปไม่ค่อยได้ ไม่เพียงน้ำต่ำ สัตว์บัดซบที่เราไปรบกวนยังจับตาเราใกล้ชิด\n\nเจ้าช่วย Blackwater Raiders ได้มาก หากส่งข่าวให้ Fleet Master Seahorn ที่ Booty Bay ว่าเราพบสมบัติและกำลังเก็บเพิ่ม นำตัวอย่างนี้ไปเป็นหลักฐาน" },
        progress = { "30:1993824066:204977702 C 1:63:63", "อะไรพามา Booty Bay {class}?" },
        completion = { "94:1539285392:1630415750", "อา ต้องยกให้ Shakes O'Breen เพื่อนเก่า! รู้ว่าเป็นกัปตันเหมาะกับภารกิจ!" },
        required = { [4502] = { "16:2080972953:18091751", "ตัวอย่างอัญมณีเอลฟ์" } },
        objectiveLabels = {
            item = { ["Sample Elven Gem"] = "ตัวอย่างอัญมณีเอลฟ์" },
        },
    },
    [670] = { -- Sunken Treasure
        title = { "15:1829519271:1005357415", "สมบัติจมทะเล" },
        objective = { "63:189663457:1338103617", "ส่ง Seahorn's Letter ให้ Shakes O'Breen ใน Arathi Highlands" },
        description = { "5:814845730:1041320628 N 312:1570358976:1128889420", "นี่ {name} เจ้าดูชอบผจญภัย กองเรือข้าติด Booty Bay จนกว่าจะเติมเสบียง\n\nมีเรื่องใหญ่ก่อตัวทั้งที่นี่และแดนไกล ข้าต้องส่งจดหมายลับสุดยอดให้ Shakes O'Breen ผู้ติดอยู่นอกชายฝั่ง Arathi\n\nไว้ใจให้เจ้าส่งสารอย่างปลอดภัยและเก็บเป็นความลับได้ไหม?" },
        progress = { "80:1594460121:1618304111", "Seahorn ประทับใจไหม? พนันว่ารอยยิ้มเขายาวจาก Booty Bay ถึง Ratchet" },
        completion = { "104:417361038:924635780", "ขอบคุณที่เดินทางไกลอันตราย Blackwater Raiders ซาบซึ้งเจ้า" },
        required = { [4494] = { "23:1963003800:553072853", "จดหมายปิดผนึกของ Seahorn" } },
        steps = { { "23:1963003800:553072853", "จดหมายปิดผนึกของ Seahorn" } },
    },
    [671] = { -- Foul Magics
        title = { "11:490716564:186869142", "เวทมนตร์ชั่วร้าย" },
        objective = { "52:1021732184:415566480", "หา Bloodstone Amulets 10 อัน ให้ Tor'gan ที่ Hammerfall" },
        description = { "508:90728340:1773111278", "ข้ารู้สึกผิดแปลกในอากาศ...เดือดปุดในเลือด ข้าสงสัย จึงตามหาที่มาความไม่สบายใจ พบทางตะวันตกที่ Northfold Manor ร่องรอยเวทเรียกปีศาจ เมื่อใกล้ เลือดเดือด โทสะเพิ่ม\n\nบนพื้นมีเครื่องราง bloodstone ช่วยเรียกปีศาจ แต่อันนั้นพลังหมดแล้ว ข้าต้องการอีกอันตรวจ แต่ไม่กล้ากลับคฤหาสน์ นำมาให้หน่อยได้ไหม?" },
        progress = { "47:1033785557:1833246159 N 66:1542817326:554488465", "เลือดที่เคยถูกสาปยังไหลในตัว {name} หากใคร...หรือสิ่งใดเรียกปีศาจ ต้องหยุดมัน" },
        completion = { "182:933313046:508795538", "ต้องใช้เวลารู้เจตนาจริง Syndicate แต่ความเกี่ยวข้องชัดกับเวทปีศาจมืดทำให้กังวล รู้เพิ่มแล้วข้าจะบอก" },
        required = { [4495] = { "17:827699929:1442228486", "เครื่องราง Bloodstone" } },
        steps = { { "17:827699929:1442228486", "เครื่องราง Bloodstone" } },
    },
    [672] = { -- Raising Spirits
        title = { "15:278876255:1066336307", "ปลุกขวัญ" },
        objective = { "104:831420176:1356845525", "เก็บ Highland Raptor Eyes 10 ดวง จาก Highland Striders และ Highland Thrashers ให้ Tor'gan ที่ Hammerfall" },
        description = { "438:1713095141:373206963", "เราพยายามให้เขาตั้งหลัก ปลอบด้วยเรื่องเมืองยิ่งใหญ่ Orgrimmar ใน Kalimdor แต่ไม่มีอะไรทำให้ใจขยับ\n\nเรื่อง Warchief หนุ่ม Thrall ผู้สวมเกราะและถือค้อน Orgrim...แต่บางที...ใช่! แสดงเวทชามานที่เราเพิ่งค้นคืนอาจมอบหวังใหม่ คุ้มลอง!\n\nทำของเล็กให้เขา ใช่...นำดวงตาแรปเตอร์มา ข้าจะดูว่าทำอะไรได้" },
        progress = { "133:671744051:992054115", "ข้าจะสร้างเครื่องรางให้ Gor'mul มีพลังแรปเตอร์ บางทีจะปลุกเปลวไฟในใจ..." },
        completion = { "107:1625916121:1487313084", "ยอดเยี่ยม วิญญาณแรปเตอร์เจ้าของดวงตาจะเสริมกำลังผู้สวมเครื่องราง" },
        required = { [4512] = { "19:1320213426:393616411", "ดวงตาแรปเตอร์ที่ราบสูง" } },
        steps = { { "19:1320213426:393616411", "ดวงตาแรปเตอร์ที่ราบสูง" } },
    },
    [673] = { -- Foul Magics
        title = { "11:490716564:186869142", "เวทมนตร์ชั่วร้าย" },
        objective = { "75:722285814:560260996", "นำ Bloodstone Orb ของ Marez Cowl ไปให้ Tor'gan ที่ Hammerfall" },
        description = { "439:81178613:63186105", "ข้ามั่นใจว่ามีวอร์ล็อกทรงพลังในกำแพง Stromgarde ใช้วัตถุอาร์เคนเรียกปีศาจน่าสยองจำนวนมากเป็นครั้งคราว ต้องตัดแหล่งพลัง\n\nหาวอร์ล็อกแล้วฆ่า นำวัตถุเวทที่พบติดตัวมา ข้าจะทำลาย ไม่ให้พลังทำแผ่นดินมัวหมองอีก" },
        progress = { "76:273931501:760025613", "ความร้อนในเลือด...เพิ่มทุกวัน ต้องหยุดวอร์ล็อก" },
        completion = { "92:15443909:1523228991 N 129:865806853:1839803086", "เมื่อทำลายลูกแก้วนี้ได้ คืนกระสับกระส่ายจะกลายเป็นการหลับอย่างสงบ ขอบคุณ {name} มันเตือนถึงพลังน่ากลัวที่ปีศาจเคยครอบงำออร์ค ก่อน Hellscream ปลดคำสาป" },
        required = { [4510] = { "23:1140583931:1631107945", "ลูกแก้ว Bloodstone ที่แปดเปื้อน" } },
        steps = { { "23:1140583931:1631107945", "ลูกแก้ว Bloodstone ที่แปดเปื้อน" } },
    },
    [674] = { -- Raising Spirits
        title = { "15:278876255:1066336307", "ปลุกขวัญ" },
        objective = { "40:1024401131:595687997", "มอบ Raptor Talon Amulet ให้ Gor'mul" },
        description = { "139:1720129538:1883128800", "นี่ นำเครื่องรางให้ Gor'mul ดูว่ากำลังแรปเตอร์จะปลุกไฟนักรบที่เคยเผาในเลือดเขาได้ไหม" },
        progress = { "107:1097853443:1291336756", "จะหวังอะไร เมื่อมือคนขลาดฆ่าผู้ยิ่งใหญ่ที่สุดได้? ข้าถามว่าเหลือหวังอะไร!" },
        completion = { "110:819274139:1341570975", "อะไรนี่? กระดูกขัดเงา ข้าจะใช้ทำอะไร? เครื่องประดับจะคืนความรุ่งโรจน์ให้ Horde หรือ?" },
        required = { [4526] = { "19:1186444038:1707325595", "เครื่องรางกรงเล็บแรปเตอร์" } },
        objectiveLabels = {
            item = { ["Raptor Talon Amulet"] = "เครื่องรางกรงเล็บแรปเตอร์" },
        },
    },
    [675] = { -- Raising Spirits
        title = { "15:278876255:1066336307", "ปลุกขวัญ" },
        objective = { "19:2144962040:106986901", "คุยกับ Tor'gan" },
        description = { "249:1791143301:20584534", "<Gor'mul โยนเครื่องรางลงพื้น>\n\nTor'gan ส่งมาใช่ไหม? ชิ! ไม่เข้าใจทำไมเขาสงสารข้า ข้าถูกปฏิเสธเมตตาเมื่อไม่ได้ตายร่วมศึกกับ Warchief ชะตาทำร้ายข้าโหดเหี้ยม..." },
        completion = { "212:388241309:1037859767", "ไม่ได้ผลสินะ แต่ข้ายังเชื่อว่าแสดงพลังชามานจะทำให้ Gor'mul กลับมาภูมิใจเช่นเดิมในที่สุด เครื่องรางยังไม่แรงพอแสดงพลังที่เราค้นคืน" },
    },
    [677] = { -- Call to Arms
        title = { "12:571120093:257388300", "เรียกรวมพล" },
        objective = { "118:1894462057:1276972980", "ฆ่า Witherbark Axe Throwers 10 คน, Headhunters 10 คน และ Witch Doctors 8 คน แล้วกลับไปหา Drum Fel ที่ฐาน Hammerfall" },
        description = { "504:658282585:844945966", "โทรลล์ Witherbark กับออกร์ Boulderfist แห่ง Arathi ร่วมขับไล่เราจากแผ่นดิน แต่เราจะไม่สิ้นด้วยมือมันหรือใคร เราจะฆ่าให้รู้ว่าเราก็มีบ้านที่นี่\n\nโทรลล์หันหลังให้เรา ออกร์จะใช้เราเป็นอาหารและที่นอนหากยอม จะไม่เกิดเช่นนั้น\n\nเริ่มบุกโทรลล์ Witherbark ทางใต้ ฆ่าให้มาก กลับเมื่อค่ายมันนองเลือดเท่านั้น" },
        progress = { "103:1194890937:9770830", "หากงานยังไม่เสร็จ บางทีเจ้าอาจขลาดในใจพอ ๆ กับอ่อนหัดในสงคราม" },
        completion = { "96:956014374:646969479", "เสื้อผ้าเจ้ามีร่องรอยสงคราม เหงื่อหยดจากหน้าผาก ดี ดีมาก" },
        objectiveLabels = {
            monster = { ["Witherbark Axe Thrower slain"] = "ปราบ นักขว้างขวาน Witherbark", ["Witherbark Headhunter slain"] = "ปราบ นักล่าหัว Witherbark", ["Witherbark Witch Doctor slain"] = "ปราบ หมอผี Witherbark" },
        },
    },
    [678] = { -- Call to Arms
        title = { "12:571120093:257388300", "เรียกรวมพล" },
        objective = { "100:1463409346:1225903649", "ฆ่า Boulderfist Brutes 10 ตัว และ Boulderfist Magi 4 ตัว แล้วกลับไปหา Drum Fel ที่ฐาน Hammerfall" },
        description = { "26:1688068490:230792051 N 428:2079482022:513715346", "ความแข็งแกร่งเจ้าชัดเจน {name} ทีนี้ดูว่าเจอศัตรูจริงจะเป็นอย่างไร\n\nBoulderfist มีรังตะวันตกเฉียงใต้ค่อนไปสะพานคนแคระ หากไม่ผิด พวกนักทุบกับจอมเวทที่นั่นจะท้าทายกว่า มันทำให้เราลำบากมาแล้ว\n\nฆ่าให้มาก สำเร็จก็กลับมาทั้งร่าง ล้มเหลวก็มาในรูปวิญญาณ ข้าจะสรรเสริญความไม่ย่อท้อในศึกไม่ว่าอย่างไร" },
        progress = { "59:882204685:858176028 N 21:1953286576:1932195836", "ลังเลทำไม? เจ้าพิสูจน์กำลังมากแล้ว {name} อย่าทำให้ผิดหวังตอนนี้" },
        completion = { "77:1397831712:1589957759", "เจ้าแข็งแกร่งดั่งโคโด ความกระหายศึกทำให้ชนเผ่าภูมิใจ" },
        objectiveLabels = {
            monster = { ["Boulderfist Brute slain"] = "ปราบ อ็อกเกอร์จอมโหด Boulderfist", ["Boulderfist Magus slain"] = "ปราบ จอมเวท Boulderfist" },
        },
    },
    [679] = { -- Call to Arms
        title = { "12:571120093:257388300", "เรียกรวมพล" },
        objective = { "99:960812484:550850133", "ฆ่า Boulderfist Shaman 7 ตัว และ Boulderfist Lords 3 ตัว แล้วกลับไปหา Drum Fel ที่ฐาน Hammerfall", variants = { { "101:1419839169:894297806", "ฆ่า Boulderfist Shaman 15 ตัว และ Boulderfist Lords 10 ตัว แล้วกลับไปหา Drum Fel ที่ฐาน Hammerfall" } } },
        description = { "68:1542782356:1057504424 N 309:1196159009:1618473121", "พร้อมตัดหัวสัตว์ร้ายแล้ว...อย่างรุนแรง {name} เจ้าพิสูจน์ว่าช่วยปิดศึกสุดท้ายนี้ได้ ผู้นำการโจมตีตั้งรังในซาก Stromgarde สัญลักษณ์ความเปราะบางมนุษย์ชัดเจน\n\nหาและฆ่าหัวหน้า Boulderfist กับชามานลูกสมุนที่คิดขับไล่เรา" },
        progress = { "206:1879808224:35826218", "ในที่สุดความกล้าก็เสื่อมสินะ สัญชาตญาณข้าถูก กำลังเจ้าเทียบความโอ้อวดไม่ได้\n\nกลับเมื่อตัดหัวสัตว์ร้ายแล้ว ไม่เช่นนั้นอย่ากลับอีก" },
        completion = { "26:729202408:1461508612 N 100:848209980:520587734", "เจ้าทำให้ชนเผ่าภูมิใจ {name} ภัยลดลงมาก มั่นใจว่าเราจะเริ่มรุ่งเรืองใน Highlands" },
        objectiveLabels = {
            monster = { ["Boulderfist Shaman slain"] = "ปราบ ชาแมน Boulderfist", ["Boulderfist Lord slain"] = "ปราบ ลอร์ดแห่ง Boulderfist" },
        },
    },
    [680] = { -- The Real Threat
        title = { "15:1977641034:1903830394", "ภัยที่แท้จริง" },
        objective = { "72:2088851753:553814515", "ฆ่า Or'Kalar แล้วนำหัวไปให้ Korin Fel ที่ฐาน Hammerfall" },
        description = { "27:1902291275:1107633920 C 461:883691518:2012276550", "เจ้ารับใช้สามีข้าได้ดี {class} แต่เขาไม่รู้เหตุที่ Hammerfall ถูกโจมตี\n\nOr'Kalar เบี้ยของ Mug'thol ใน Stromgarde เกลียดสามีข้าอย่างแรง อยากให้ตายเพราะเคยแพ้เขาหลายปีก่อน\n\nนิมิตบอกว่ามันวางกับดักสามี ข้าจึงซ่อนร่องรอยการปรากฏตัวออกร์จากเขา\n\nหากรู้ที่อยู่ เขาจะรีบบุกอย่างโง่เขลา ข้าจึงขอให้เจ้าช่วยฆ่าสัตว์นั้น" },
        progress = { "393:963352339:1996099450", "ใกล้ Tower of Arathor คือที่พบ Or'Kalar ฆ่ามันจะหยุดการบุก Hammerfall และปกป้องชีวิตสามีข้า\n\nเห็นแววตาเจ้าคิดว่าข้าอ่อนแอ หรือไร้เกียรติที่เงียบ สักวันจะรู้ว่ารักอย่างข้าเป็นอย่างไร บางทีจะเข้าใจกำลังและเกียรติอีกชนิด\n\nระหว่างนี้ ทำตามขอ ฆ่า Or'Kalar" },
        completion = { "34:340921978:934356450 N 163:1679786196:879489041", "เจ้าช่วยข้ามาก {name} รู้ไว้ว่าเพราะผลงานเจ้า ชีวิตสามีและความปลอดภัย Hammerfall ได้รับการปกป้องอีกวัน รับนี่เป็นรางวัลความกล้า" },
        required = { [4551] = { "15:1533900386:430494428", "ศีรษะของ Or'Kalar" } },
        steps = { { "15:1533900386:430494428", "ศีรษะของ Or'Kalar" } },
    },
    [681] = { -- Northfold Manor
        title = { "15:2022296081:280146857", "คฤหาสน์ Northfold" },
        objective = { "99:1385681662:695325233", "ฆ่า Syndicate Highwaymen 10 คน และ Syndicate Mercenaries 6 คน\n\nกลับไปหา Captain Nials ที่ Refuge Pointe" },
        description = { "499:119833150:205461790", "เรารบเพื่อ Stromgarde และกำลังแพ้ ออกร์ Syndicate กับเราแบ่งเมืองที่เคยยิ่งใหญ่ แต่ละฝ่ายสู้จนทางตันนองเลือด\n\nแต่กำลังเราลด ศัตรูกลับเพิ่ม\n\nต้องการความช่วยเหลือจาก Southshore แต่รับเสบียงยากเมื่อ Syndicate ยึดพื้นที่คั่นกลาง\n\nไปฐานมันที่ Northfold Manor แล้วฆ่า บางทีแรงกดดันกองเกวียนจะลด เสบียงผ่านได้มากขึ้น" },
        progress = { "N 117:192324676:1877609196", "{name} ทุกชั่วโมงที่ผ่าน เราคุม Stromgarde เปราะบางขึ้น ต้องรีบ มิฉะนั้นเมืองล่มแน่" },
        completion = { "11:1776810664:1873330125 N 142:928465527:657993394", "ดีมาก {name} สมาชิก Syndicate ตายแล้ว เราน่าจะรับเสบียง Southshore ง่ายขึ้น\n\nบางทีจุดหมายเรายังมีหวัง" },
        objectiveLabels = {
            monster = { ["Syndicate Highwayman slain"] = "ปราบ โจรดักปล้น Syndicate", ["Syndicate Mercenary slain"] = "ปราบ ทหารรับจ้าง Syndicate" },
        },
    },
    [682] = { -- Stromgarde Badges
        title = { "17:1511127789:91183265", "ตราทหาร Stromgarde" },
        objective = { "60:1928041190:1821745837", "นำ Stromgarde Badges 7 อัน ไปให้ Captain Nials ที่ Refuge Pointe", variants = { { "58:312036969:1808598611", "นำ Stromgarde Badges ไปให้ Captain Nials ที่ Refuge Pointe" } } },
        description = { "457:867091755:496645698", "Syndicate ใน Stromgarde รบกับกองกำลังเรา เพื่อกระตุ้นพวกไร้ระเบียบให้สู้ทหารที่ฝึกดีกว่า ผู้นำมันตั้งค่าหัว จ่ายทองตาม Stromgarde Badge ที่เก็บจากทหารตาย\n\nเราต้องได้ตราคืน ปล่อยนักฆ่าเก็บของจากผู้กล้าล้มตายเป็นรางวัลไม่ได้!\n\nเข้าเขต Syndicate ใน Stromgarde ล่าตราเราคืน" },
        progress = { "42:1203174687:2054021490 N 60:1094831672:189702575", "ได้ Stromgarde Badges คืนบ้างไหม {name}? Syndicate ต้องรู้ว่าหากำไรจากคนตายเราไม่ได้" },
        completion = { "11:1191658970:1224418299 N 179:519939041:944070100", "ขอบคุณ {name} เราจะแจ้งครอบครัวทหารเหล่านี้ว่าพวกเขาตายในศึก\n\nข่าวเศร้า แต่ดีกว่าไม่รู้ชะตาคนรักที่หายไป" },
        required = { [4506] = { "16:941748234:213805117", "ตราสัญลักษณ์ Stromgarde" } },
        steps = { { "16:941748234:213805117", "ตราสัญลักษณ์ Stromgarde" } },
    },
    [684] = { -- WANTED: Marez Cowl
        title = { "18:1849117155:12664595", "ประกาศจับ: Marez Cowl" },
        objective = { "53:1306875094:458781111", "นำหัว Marez ไปให้ Captain Nials ที่ Refuge Pointe" },
        description = { "358:1584215984:706832950", "ตั้งค่าหัว Marez Cowl ที่ปรึกษาและผู้ปฏิบัติการระดับสูง Syndicate พบครั้งสุดท้ายในเขตที่มันคุมใน Stromgarde\n\nรับค่าหัวจาก Captain Nials\n\nระวัง Marez เป็นวอร์ล็อกเก่งกาจเจ้าเล่ห์ ขึ้นชื่อว่าติดต่อปีศาจ ล่านางต้องระมัดระวังอย่างยิ่ง" },
        progress = { "11:927657569:725753248 C 28:1491908802:730803785", "สวัสดี {class} มีรายงานหรือ?" },
        completion = { "37:1656727219:158348127 N 217:1278747035:794169969", "โค่น Marez Cowl ได้หรือ? ทำได้ดี {name} ดีมากจริง!\n\nMarez คุกคามผู้ป้องกัน Stromgarde ลือว่านางเป็นทูตเชื่อม Syndicate กับอำนาจมืดอื่น เราดีใจที่นางจะใช้พลังใส่เราไม่ได้อีก" },
        required = { [4515] = { "12:320456519:944961808", "ศีรษะของ Marez" } },
        steps = { { "12:320456519:944961808", "ศีรษะของ Marez" } },
    },
    [685] = { -- WANTED: Otto and Falconcrest
        title = { "28:1067865908:1292759342", "ประกาศจับ: Otto และ Falconcrest" },
        objective = { "75:1681642085:333595139", "นำ Otto's Head และ Falconcrest's Head ไปให้ Captain Nials ที่ Refuge Pointe" },
        description = { "396:156232676:908789963", "กองกำลัง Stromgarde ตั้งค่าหัว Lord Falconcrest กับบอดีการ์ด Otto Falconcrest นำกิจการ Syndicate ใน Arathi Highlands หากตายจะขัดขวางมันอย่างหนัก\n\nแม้ Otto ไม่ใช่เป้าทางยุทธศาสตร์ แต่ดุร้าย ฆ่าผู้ป้องกันเราหลายสิบคน\n\nรับค่าหัวจาก Captain Nials" },
        progress = { "38:349935296:937354854", "สวัสดี มีรายงานจะส่งหรือ?" },
        completion = { "54:754813724:1712470042 N 23:1587082068:631139082", "Falconcrest กับ Otto หรือ? วิเศษ!\n\nนี่รางวัล {name} ข้ายินดีจ่าย" },
        required = { [4516] = { "11:1911732547:201561926", "หัวของ Otto" }, [4517] = { "18:64435010:298739153", "หัวของ Falconcrest" } },
        objectiveLabels = {
            item = { ["Otto's Head"] = "หัวของ Otto", ["Falconcrest's Head"] = "หัวของ Falconcrest" },
        },
    },
    [687] = { -- Theldurin the Lost
        title = { "18:1343414753:1329031320", "Theldurin the Lost" },
        objective = { "24:1696485686:554472087", "ตามหา Theldurin the Lost" },
        description = { "362:952464521:96658338", "Theldurin the Lost เคยอยู่ในองค์กร Twilight's Hammer ของเรา แต่เสียสติ ลบหลู่คำสอน ก่อนหนียังขโมยม้วนคัมภีร์ Myzrael! เราจับไม่ได้ แต่ลือว่าซ่อนใน Badlands พูดเพ้อคลุ้มคลั่ง\n\nเพื่อพาท่านหญิงกลับมา ต้องหาคัมภีร์ และต้องพบ Theldurin ก่อน" },
        completion = { "165:612422622:991680792", "สวัสดี สวัสดี สวัสดี สวัสดี สวัสดี สวัสดี สวัสดี!\n\nขอโทษ เดี๋ยว ไม่ขอโทษ! อย่าเสียมารยาท!\n\nโอ้ไม่...นั่นพูดบ้าไปแล้ว\n\nแต่...บางทีความบ้าเป็นสิ่งเดียวที่ปลอบข้า" },
    },
    [688] = { -- Myzrael's Allies
        title = { "16:1484240606:595303606", "พันธมิตรของ Myzrael" },
        objective = { "31:999998200:1557950530", "คุยกับ Zaruk ที่ Hammerfall" },
        description = { "270:1715829876:1503536621 N 163:432647908:731376821", "<Myzrael พูดขึ้น>\n\nอิสระ! ข้าเป็นอิสระ! จะหลบซ่อนรวบรวมกำลังได้ เพราะหากผู้จับข้าพบตอนนี้ มันคงชนะแล้วขังข้าอีก\n\nแต่เมื่อถึงเวลา ข้าจะเผชิญยักษ์ และมันจะเสียใจที่กักขัง!\n\nเจ้าคือพันธมิตรสูงส่ง {name} อีกไม่นานข้าจะต้องการเจ้า เมื่อพร้อม ข้าจะให้เรียกสู่พื้นผิว\n\nคุยกับ Zaruk ที่ Hammerfall เขารู้วิธีเรียกข้า" },
        completion = { "9:1106625653:2036951628 C 121:607990462:824469666", "ยินดีต้อนรับ {class} ท่านหญิงบอกว่าเจ้าจะมา หากจะพานางกลับพื้นผิว เรามีเรื่องต้องคุยมาก..." },
    },
    [691] = { -- Worth Its Weight in Gold
        title = { "24:1205469649:1410384020", "มีค่าเท่าน้ำหนักทอง" },
        objective = { "121:1803317164:1585156129", "หา Witherbark Tusks 10 อัน, Witherbark Medicine Pouches 4 ถุง และ Shadow Hunter Knife ให้ Apprentice Kryten ที่ Refuge Pointe" },
        description = { "354:1014764727:129344532", "Archmage Malin ส่งข้ากับ Skuerto มาเก็บส่วนประกอบ ข้าไม่รู้จะเก็บอย่างไร แต่เมื่อเจ้ามา ปัญหาคงคลี่คลาย\n\nต้องการงา Witherbark ถุงยา Witherbark และมีด shadow hunter\n\nหาให้ได้ไหม? Witherbark อยู่ตะวันออกเฉียงใต้ Arathi" },
        progress = { "30:1392586708:1751946727 N 421:1308085734:2083471413", "ได้ผลบ้างไหม {name}?\n\n<Kryten จดบันทึกขณะอ่าน>\n\nหากวิจัยถูก งาได้จากโทรลล์ Witherbark ทุกคน ถุงยาได้จากหมอผี ส่วน shadow hunter ที่แข็งแกร่งที่สุดน่าจะถือมีดพิเศษที่ได้รับหลังผ่านพิธี ไม่มีทางรู้ว่าใครมีจนกว่าจะสู้" },
        completion = { "439:1426898459:952686829", "เหลือเชื่อ! เข้าใจแล้วทำไม Malin ให้เจ้ามาช่วย ทำได้ดีมาก!\n\nอย่างนี้ข้ากับ Skuerto คงกลับ Stormwind เร็ว ๆ\n\nคิดว่าสหายคนแคระกลับจากสำรวจ Boulderfist Hall แล้ว พร้อมเมื่อไรไปคุย\n\nดูเหมือนปะทะออกร์มาเล็กน้อย แต่อย่าพูดกับเขา เขาอ่อนไหวกับคำวิจารณ์ฝีมือสอดแนมมาก" },
        required = { [4503] = { "15:1676549635:1481769307", "งา Witherbark" }, [4522] = { "25:959398134:1085403280", "ถุงยาของ Witherbark" }, [5040] = { "19:1247154134:1703138159", "มีดของนักล่าเงา" } },
        objectiveLabels = {
            item = { ["Witherbark Tusk"] = "งา Witherbark", ["Witherbark Medicine Pouch"] = "ถุงยาของ Witherbark", ["Shadow Hunter Knife"] = "มีดของนักล่าเงา" },
        },
    },
    [693] = { -- Wand over Fist
        title = { "14:1192647148:962970206", "คทาเหนือกำปั้น" },
        objective = { "76:1926353108:534487471", "หา Trelane's Wand of Invocation แล้วนำคืน Skuerto ที่ Refuge Pointe" },
        description = { "5:140209925:2105781119 N 477:1464440088:642362143", "เฮ้ {name} ขอโทษที่ก่อนหน้านี้พูดห้วน...ไม่ได้เล่นคำเรื่องตัวเตี้ยนะ\n\nข้ารู้ว่าของชิ้นแรกของ Trelane ไปไหน Kor'gresh มีมันใน Boulderfist Hall ดูจากที่ยิงน้ำแข็งใส่พวกเดียวกันให้เชื่อฟัง มันคงใกล้รู้วิธีใช้พลังทั้งหมดแล้ว\n\nBoulderfist Hall อยู่ใต้จากที่นี่ แล้วตะวันออก Thandol Span หาออกร์ เอาคทาคืน\n\nระหว่างเจ้าไป ข้าจะคิดว่าทำอย่างไรกับ Stromgarde" },
        progress = { "22:875305977:1135405785 N 24:106143660:1483736715", "เป้าหมายคือคทา {name} ตอนนี้มุ่งที่นั่นก่อน" },
        completion = { "11:2107547062:1465756880 N 271:1573554623:739624596", "ยอดเยี่ยม {name} ได้หนึ่ง เหลือสามตามรายการข้า อีกสามอยู่ใน Stromgarde\n\nพักคืนกำลังก่อน ขั้นต่อไปต้องใช้เวลาและแรงมากกว่า กินอาหารอุ่น ๆ พักแล้วกลับมาหาข้า" },
        required = { [4525] = { "28:1398492110:833176809", "ไม้กายสิทธิ์ร่ายมนตร์ของ Trelane" } },
        steps = { { "28:1398492110:833176809", "ไม้กายสิทธิ์ร่ายมนตร์ของ Trelane" } },
    },
    [694] = { -- Trelane's Defenses
        title = { "18:808620099:678285370", "ระบบป้องกันของ Trelane" },
        objective = { "71:1443625425:65629257", "หา Azure Agate แล้วนำไปให้ Apprentice Kryten ที่ Refuge Pointe" },
        description = { "505:1311074843:292302803", "พักพอแล้วหรือ?\n\nขั้นต่อไป ออกร์อยู่รอบ Tower of Arathor ใน Stromgarde ต้องเปิดระบบป้องกันหอคอย เจ้าจึงจะมีโอกาสสู้และเอาของโดยรอดชีวิต ต้องใช้อัญมณีที่ชามาน Boulderfist ชอบ มันขโมยจากหอคอย แต่จะเก็บไว้ได้ไม่นาน\n\nเอามาเม็ดหนึ่งให้ Kryten เขารู้มนตร์ทำให้ใช้เป็นกุญแจได้" },
        progress = { "N 49:76257292:103592656", "{name} สวัสดีอีกครั้ง พบ azure agate หรือยัง?" },
        completion = { "14:1326122554:410743159 N 101:1966589273:1063350536", "เจ้าทำให้ทึ่ง {name} ทำได้ดีอีกครั้ง\n\nขอเวลาร่ายมนตร์ลงอัญมณีให้ถูก แล้วเจ้าจะพร้อม" },
        required = { [4527] = { "11:1270652154:129460196", "โมราสีฟ้า" } },
        steps = { { "11:1270652154:129460196", "โมราสีฟ้า" } },
    },
    [695] = { -- An Apprentice's Enchantment
        title = { "27:1076158066:233217580", "มนตร์ของศิษย์ฝึกหัด" },
        objective = { "17:356547068:660487830", "คุยกับ Skuerto" },
        description = { "14:510644690:581245021 N 356:1581535595:961915936", "นี่ {name} เพียงกดอัญมณีกับแท่นหนึ่งใกล้ฐานหอคอย ก็เปิดระบบป้องกัน ใช้เมื่อพร้อมเข้าหาไอเทม Trelane ที่เหลือ\n\nโชคดี ข้าจะรอที่ค่าย อ้อ คุย Skuerto ก่อนจาก เขาจะให้รายละเอียดที่เหลือ" },
        completion = { "67:1961474362:1195404625", "ดี ดี\n\nถ้าไม่มีอะไรล่าช้า เริ่มกันเลยไหม?" },
    },
    [696] = { -- Attack on the Tower
        title = { "19:1901215200:1597829809", "บุกหอคอย" },
        objective = { "113:1069384088:398297923", "หา Trelane's Phylactery, Trelane's Orb และ Trelane's Ember Agate แล้วนำคืน Skuerto ที่ Refuge Pointe" },
        description = { "480:1403712321:523196774", "นี่ของที่หา ภาชนะผนึกวิญญาณ ลูกแก้ว และโมราเพลิงของ Trelane\n\nทั้งสามน่าจะอยู่ในหีบในหอคอย เจ้าเปิดเองได้ไม่มีปัญหา แค่ระวังออกร์\n\nระบบป้องกันไม่จัดการมันเองทั้งหมด เจ้าต้องเตรียมอาวุธ หากรู้ว่าเจ้าขโมยของ มันจะทำร้ายแน่\n\nระวังและโชคดี" },
        progress = { "65:1031084490:1420418297", "ทำสำเร็จ ข้ามั่นใจว่า Malin จะยิ่งกว่าพอใจ" },
        completion = { "67:1854703630:1777293455 N 99:269919438:650809428", "Malin คงหาคนคู่ควรช่วยเรากว่าเจ้าไม่ได้ {name} ทำได้ยอดเยี่ยม!\n\nเขาจะยินดีเห็นภารกิจเราสำเร็จอย่างงดงาม" },
        required = { [4530] = { "20:1921083912:1056874779", "ภาชนะบรรจุวิญญาณของ Trelane" }, [4531] = { "13:412616056:1330379461", "ลูกแก้วของ Trelane" }, [4532] = { "21:1566899841:670705772", "โมรา Ember ของ Trelane" } },
        steps = { { "20:1921083912:1056874779", "ภาชนะบรรจุวิญญาณของ Trelane" }, { "13:412616056:1330379461", "ลูกแก้วของ Trelane" }, { "21:1566899841:670705772", "โมรา Ember ของ Trelane" } },
    },
    [697] = { -- Malin's Request
        title = { "15:180447215:34689164", "คำขอของ Malin" },
        objective = { "74:1597470424:2028392305", "นำ Sealed Letter ไปให้ Archmage Malin ที่ Mage Quarter ของ Stormwind" },
        description = { "132:1673772841:1413431486 N 39:446009658:1039636139", "นำจดหมายกลับ Stormwind ให้ Malin รู้ว่าข้ากับ Kryten จะกลับบ้านเร็ว ๆ เขาจะตอบแทนที่เจ้าช่วยเราดีแน่ {name}\n\nเดินทางปลอดภัย" },
        progress = { "92:1712649845:41092800", "มีอะไร? เจ้าดูคุ้นหน้า ขอโทษด้วย เราเคยพบกันไหม? ข้ายุ่งจนจำไม่ไหว" },
        completion = { "244:2122899030:1254529973 N 49:1120307824:343713432", "<Archmage Malin เปิดจดหมาย ตาเบิกกว้าง>\n\nแสงสว่างเอ๋ย เจ้าทำได้ วิเศษนัก Trelane ต้องพอใจ มั่นใจว่า Kryten กับ Skuerto ตื่นเต้นที่จะกลับ Stormwind พอ ๆ กับข้า\n\nขอบคุณ {name} รับนี่ช่วยในการเดินทาง" },
        required = { [4533] = { "31:664629657:192692373", "จดหมายปิดผนึกถึงจอมเวท Malin" } },
        steps = { { "31:664629657:192692373", "จดหมายปิดผนึกถึงจอมเวท Malin" } },
    },
    [701] = { -- Guile of the Raptor
        title = { "19:684312209:756120921", "ไหวพริบแห่งแรปเตอร์" },
        objective = { "65:700439016:1608294437", "เก็บ Raptor Hearts 12 ดวง จาก Highland Fleshstalkers ให้ Tor'gan" },
        description = { "304:706354769:326285662", "เพิ่มของอีกเล็กน้อย ข้าจะสร้างไอเทมมอบไหวพริบแรปเตอร์ให้ Gor'mul! เมื่อพลังไหลผ่าน เขาจะรู้พลังใหม่เราและค้นพบนักรบที่หลับใหลอีกครั้ง!\n\nข้าต้องใช้หัวใจแรปเตอร์สร้างไอเทมและมนตร์" },
        progress = { "62:1366778665:1278411596", "เตรียมพร้อมแล้ว ขาดเพียงหัวใจแรปเตอร์" },
        completion = { "188:2058765209:1245943813", "ใช่ พวกนี้เหมาะที่สุด ข้าจะถ่ายพลังกับวิญญาณแรปเตอร์เข้าลูกแก้ว มันจะมอบกำลังเร่าร้อนและปัญญาแรปเตอร์ให้ Gor'mul" },
        required = { [4513] = { "12:553997732:732293836", "หัวใจแรปเตอร์" } },
        steps = { { "12:553997732:732293836", "หัวใจแรปเตอร์" } },
    },
    [702] = { -- Guile of the Raptor
        title = { "19:684312209:756120921", "ไหวพริบแห่งแรปเตอร์" },
        objective = { "30:331710232:1330104994", "มอบ Tor'gan's Orb ให้ Gor'mul" },
        description = { "303:612357513:1150538591", "นำลูกแก้วไปใช้พลังมอบแก่นแรปเตอร์ให้ Gor'mul ต้องชุบขวัญและมอบจุดหมายใหม่ได้แน่ เมื่อกลับปกติ เราจะอธิบายสภาพ Horde ปัจจุบัน และได้แรงนักรบยิ่งใหญ่ช่วยศึกไม่หยุดหย่อน" },
        progress = { "229:910680183:816811945", "กลับมาอีกหรือ? ตอนนี้คงไม่มีอะไรที่ข้าอยากได้ยิ่งกว่าความสงสารจาก Tor'gan อีก\n\nครั้งนี้มีอะไร? เชือกสีสดสักเส้น? หรือเชือกยาวให้จบความทุกข์ข้า..." },
        completion = { "91:105625805:1337557072", "อย่างน้อยครั้งนี้นำสิ่งน่าสนใจมา พลังแปลกประหลาดแผ่ออก..." },
        required = { [4528] = { "13:1979836476:25271074", "ลูกแก้วของ Tor'gan" } },
        steps = { { "13:1979836476:25271074", "ลูกแก้วของ Tor'gan" } },
    },
    [847] = { -- Guile of the Raptor
        title = { "19:684312209:756120921", "ไหวพริบแห่งแรปเตอร์" },
        objective = { "19:2144962040:106986901", "คุยกับ Tor'gan" },
        description = { "215:1557814922:1592791554", "นี่...พลังนี้...คือพลังชามานที่ Tor'gan พยายามแสดงหรือ? ต้องบอกว่าน่าสนใจ บอกเขาว่าโน้มน้าวข้าได้แล้ว...ชั่วคราว ข้าจะฟังสิ่งที่เขาพูด" },
        completion = { "184:15305730:848727267", "เมื่อมนตร์จาง ข้าจะพูดกับ Gor'mul ขอบใจที่ช่วยพาเขากลับสู่โลกคนเป็น เชื่อว่าเขาก็ขอบคุณมากเช่นกัน" },
    },
    [79624] = { -- Anyone Can Cook
        title = { "15:1547646119:1546063719", "ใครก็ทำอาหารได้" },
        objective = { "47:1545811582:1496880040", "หาออกร์ที่อ่าน Illegible Recipe ได้" },
        description = { "288:542236410:16249247", "สูตรดูเหมือนอาหารเนื้อ เขียนในภาษาที่เจ้าไม่เข้าใจ จากที่มาและเนื้อหา เจ้าคาดว่าน่าจะภาษาออกร์\n\nออกร์ปกติไม่ชอบทำอาหาร แต่หากรู้จักตัวที่ชอบ มันอาจแปลสูตรให้ได้" },
        completion = { "33:295388091:971856362", "เจ้ามีสูตรหรือ Skonk ฟังอยู่" },
        progress = { "36:556071473:1403909556", "เจ้าเป็นใคร? หรือเจ้าจะเป็นลูกค้าคนแรกของ Skonk?" },
        required = { [213422] = { "16:39184802:180375386", "สูตรอาหารที่อ่านไม่ออก" } },
        steps = { { "16:39184802:180375386", "สูตรอาหารที่อ่านไม่ออก" } },
    },
    [92456] = { -- A Green Sample
        title = { "14:807180295:1890760468", "ตัวอย่างสีเขียว" },
        objective = { "87:1647310505:639999490", "เก็บ Fel Infused Blossom จาก City of Dalaran ให้ Shylamiir ที่ Stormwind City" },
        description = { "445:85551171:1731862453", "หากจะรบกวน อย่างน้อยทำตัวมีประโยชน์ ข้ามีธุระให้ทำ\n\nสำหรับเมืองจอมเวท Dalaran สนใจพฤกษศาสตร์น่าประหลาด Kirin Tor เก็บตัว แต่ข้าอยากได้พืชอาบมานามาศึกษา\n\nเห็นชัดว่าเจ้าสบายใจกับการอยู่ในที่คนไม่ต้องการ ลองหาทางเข้าเมือง หากได้ นำสิ่งที่ปลูกในสวนกลางกลับมาให้ข้า", variants = { { "449:283714900:1561174278", "ถ้าข้าต้องสอนวิชาสมุนไพรให้เจ้า อย่างน้อยก็ช่วยทำตัวให้เป็นประโยชน์หน่อย ข้ามีธุระให้เจ้าไปจัดการ\n\nไม่น่าเชื่อว่าเมืองจอมเวทอย่าง Dalaran จะสนใจพฤกษศาสตร์ขนาดนี้ พวก Kirin Tor ชอบเก็บตัว แต่ข้าอยากได้ตัวอย่างพืชอาบมานาของพวกเขา\n\nดูท่าเจ้าจะคุ้นกับการเข้าไปในที่ที่คนไม่ต้อนรับ บางทีเจ้าอาจหาทางเข้าเมืองได้ ถ้าเข้าไปได้ก็เอาพืชที่ขึ้นอยู่ในสวนกลางเมืองกลับมาให้ข้าด้วย" } } },
        progress = { "25:74077047:634212856", "ว่าอย่างไร? ได้มาหรือยัง?" },
        completion = { "208:349902111:340223817", "นี่...ไม่ใช่สิ่งที่คิดไว้\n\nเห็นชัดว่าเมืองเจอเรื่องหนักกว่าคาด แต่สิ่งที่เจอชวนศึกษาพอ ๆ กัน หรือยิ่งกว่า\n\nดูเหมือนเจ้าไม่ได้น่ารำคาญเท่าที่คิด ทำได้ดี", variants = { { "208:1771152158:664167329", "นี่...ไม่ใช่สิ่งที่คิดไว้\n\nเห็นชัดว่าเมืองเจอเรื่องหนักกว่าคาด แต่สิ่งที่เจอชวนศึกษาพอ ๆ กัน หรือยิ่งกว่า\n\nดูเหมือนเจ้าไม่ได้น่ารำคาญเท่าที่คิด ทำได้ดี" } } },
        required = { [251983] = { "19:678906316:1206142342", "ดอกไม้ที่อาบพลังเฟล" } },
        steps = { { "19:678906316:1206142342", "ดอกไม้ที่อาบพลังเฟล" } },
    },
    [92457] = { -- Starving Arcane
        title = { "15:145521738:510845050", "อาร์เคนผู้หิวโหย" },
        objective = { "133:1438359984:10045803", "ปราบ Seeking Remnants 8 ตัว, Saturated Remnants 8 ตัว และ Mana Echoes 8 ตัว ใน City of Dalaran ให้ Archmage Modera นอก Dalaran", amount = { "7:1265997621:1189804897 W1 19:323565100:139602168 W2 25:500520598:362811509 W3 79:376697553:538497599", "ปราบ Seeking Remnants {world1} ตัว, Saturated Remnants {world2} ตัว และ Mana Echoes {world3} ตัว ใน City of Dalaran ให้ Archmage Modera นอก Dalaran" } },
        description = { "396:603676722:1939639459", "รอยรั่วกระทบผู้รับใช้เวทและมนตร์ทั่วเมือง รวมหลายสิ่งที่ดูแลการป้องกัน พลังอาร์เคนแตกกระจายเรียกหาธาตุแตกแถวที่อยากอิ่มพลังเวทไหลเสรีนี้\n\nระหว่างเรารักษาอาคมและเหตุใหญ่ หากเจ้าลดจำนวนฝูงธาตุได้ จะช่วย Kirin Tor มาก" },
        completion = { "10:890369348:779817918 N 49:492029965:554504651", "ขอบคุณ {name} ความคืบหน้าครั้งนี้จะช่วยให้ Dalaran ปลอดภัย" },
        objectiveLabels = {
            monster = { ["Seeking Remnant slain"] = "ปราบ เศษพลังไล่ตาม", ["Saturated Remnant slain"] = "ปราบ เศษพลังอิ่มมานา", ["Mana Echo slain"] = "ปราบ เสียงสะท้อนแห่งมานา" },
        },
    },
    [92458] = { -- Heart of Disruption
        title = { "19:1855252517:1442255796", "ใจกลางความปั่นป่วน" },
        objective = { "82:1030209996:2027733088", "เก็บ Arcane Mote ให้ Image of Archmage Modera ใกล้ City of Dalaran" },
        description = { "502:638500134:1088478300", "สิ่งที่รบกวนสายพลังเวทเริ่มบนยอด Violet Citadel เสียงปะทะกึกก้องจากห้องรับแขกข้างบน แล้วพลังอาร์เคนคลุ้มคลั่งก็ท่วมเรา ต้องใช้กำลังทั้งหมดเพียงรักษาอาคมไว้\n\nช้าอีกไม่ได้ ต้องการความช่วยเหลือ\n\nKirin Tor ยุ่งภายใน แต่เจ้ายังต้องใช้ทางที่ไม่เปิดเผยเพื่อเข้า รับกุญแจนี้ พอเข้าเมืองแล้วพบข้าในป้อม ต้องยุติความปั่นป่วนนี้", variants = { { "503:1806487468:1883205560", "สิ่งที่รบกวนสายพลังเวทเริ่มบนยอด Violet Citadel เสียงปะทะกึกก้องจากห้องรับแขกข้างบน แล้วพลังอาร์เคนคลุ้มคลั่งก็ท่วมเรา ต้องใช้กำลังทั้งหมดเพียงรักษาอาคมไว้\n\nช้าอีกไม่ได้ ต้องการความช่วยเหลือ\n\nKirin Tor ยุ่งภายใน แต่เจ้ายังต้องใช้ทางที่ไม่เปิดเผยเพื่อเข้า รับกุญแจนี้ พอเข้าเมืองแล้วพบข้าในป้อม ต้องยุติความปั่นป่วนนี้" } } },
        progress = { "74:931425729:727266302", "ความภูมิใจจะมีประโยชน์อะไร หากไม่เหลือเมืองให้ภูมิใจ?" },
        completion = { { "194:1364151664:722669797", "36:282771633:1637926002 N 152:1232374323:1951278857", "36:282771633:1637926002 C 152:1232374323:1951278857", "36:282771633:1637926002 R 152:1232374323:1951278857" }, "ไม่รู้ว่าเจ้าเห็นอะไรข้างบน สหาย แต่ไม่สำคัญ ตอนนี้ต้องควบคุมเศษพลังและจบความบ้าคลั่ง\n\nเจ้าทำส่วนของตนดีแล้ว ที่เหลือเป็นหน้าที่เรา" },
        required = { [251961] = { "11:575954581:468956656", "ละอองเวทอาร์เคน" } },
        steps = { { "11:575954581:468956656", "ละอองเวทอาร์เคน" } },
    },
    [92489] = { -- Power Overwhelming
        title = { "18:1217563826:1429832965", "พลังล้นหลาม" },
        objective = { "93:1840205374:1281834265", "ฆ่า Mana Elemental ใน City of Dalaran ให้ High Sorcerer Andromath ที่ Stormwind City" },
        description = { "504:1051520285:1725059131", "Kirin Tor เป็นพันธมิตร Alliance มานาน หลังจอมปีศาจ Archimonde ทำลายเมือง เมืองจอมเวทที่เคยภาคภูมิกลับเก็บตัวไม่ไว้ใจคนนอก\n\nหลายปีมานี้เริ่มสร้าง Dalaran คืนความรุ่งโรจน์ แต่รายงานว่าควบคุมการปะทุของพลังอาร์เคนแตกแถวได้ยาก\n\nเราต้องช่วยสลายการโจมตี มิฉะนั้นจะเสียพันธมิตรทรงพลังที่สุดรายหนึ่ง" },
        completion = { { "213:333606391:241275479", "206:189304276:362354818 N 1:46:46", "206:189304276:362354818 C 1:46:46", "206:189304276:362354818 R 1:46:46" }, "สิ่งมีชีวิตมานาบริสุทธิ์หรือ? สิ่งที่ก่อความวุ่นวายทรงพลังกว่ารายงานแรก\n\nเจ้าช่วยซื้อเวลาอันมีค่า เตือน Kirin Tor ว่ามิตรคือใคร ทำได้ดี สหาย" },
        progress = { "41:1008701459:1783748927 N 52:919091308:1318873702", "Kirin Tor ไม่มีเวลาให้เสียแล้ว {name} ไปที่นคร Dalaran แล้วกำจัดภัยนั่นเสีย" },
        objectiveLabels = {
            monster = { ["Arcanic Enigma slain"] = "ปราบ ปริศนาแห่งอาคม" },
        },
    },
    [92519] = { -- Ward Restocking
        title = { "15:513433846:1827617189", "เติมเสบียงหอผู้ป่วย" },
        objective = { "116:384501488:1299688433", "รับ Packaged Tonics หนึ่งลัง ที่ห้องทดลอง Jorell ใน Go'shek Farm แล้วกลับไปหา Doctor Gregory Victor ที่ Hammerfall" },
        description = { "490:150997322:658273148", "Apothecary Jorell ควรนำยาแก้พิษกับน้ำยามาให้หนึ่งลังหลายวันแล้ว แต่เรายังมือเปล่า เจ้าโง่คงวางยาตนเองอีกตอนปรุงในกระท่อมอากาศไม่ถ่ายเทที่เรียกห้องทดลอง\n\nหากจะช่วยหอผู้ป่วยต่อ เจ้าน่าไว้ใจทำงานนี้กว่า\n\nตามถนนไป Go'shek farm ทางใต้ค่อนไปตะวันตกเล็กน้อย คงพบของแพ็กพร้อม ส่วน Jorell ไม่อยู่หรือไม่สนหน้าที่" },
        completion = { "340:733245814:981893047", "ไม่มีขวดแตกเลยหรือ ใช่แล้ว เจ้าเหมาะกับงานนี้กว่าลูกน้องของ Jorell มาก\n\nเราจะใช้ของพวกนี้ประคองอาการคนไข้ได้อีกพักหนึ่ง\n\nเจ้าแสดงให้เห็นว่ามีพรสวรรค์กับงานภาคสนาม ข้าเข้าใจว่างานแบบนี้เลี่ยงบาดเจ็บไม่ได้ เลือกเอาเสบียงไปสักอย่าง อย่างน้อยเจ้าคงได้ใช้" },
        progress = { "122:1496729617:1148063026", "ถ้าเจ้าหายาบรรเทาปวดมาให้พวกเขาได้ คนไข้บางคนก็กลับออกไปได้ทันทีที่มาถึง" },
        required = { [278462] = { "15:1977061011:1769380933", "ยาบำรุงที่ห่อพร้อมส่ง" } },
        steps = { { "15:1977061011:1769380933", "ยาบำรุงที่ห่อพร้อมส่ง" } },
    },
    [92707] = { -- The Giant in the Den
        title = { "20:1379484373:684327659", "ยักษ์ในรัง" },
        objective = { "58:1268535680:377797378", "นำ Goliath's Wristguards ไปให้ Drum Fel ที่ Hammerfall" },
        description = { "254:18085787:16425052", "ปลอกแขนที่ดึงจากศพยักษ์มโหฬารใหญ่จนแขนเจ้าทั้งข้างถึงไหล่ลอดได้โดยไม่แตะขอบ\n\nควรนำกลับ Hammerfall เป็นคำเตือน Drum Fel ต้องรู้ว่าเผชิญอะไรอยู่" },
        required = { [253711] = { "21:780245691:300533370", "ปลอกรัดข้อมือของ Goliath" } },
        steps = { { "21:780245691:300533370", "ปลอกรัดข้อมือของ Goliath" } },
    },
    [92867] = { -- Ground to Keep
        title = { "14:1567015215:762325120", "ผืนดินที่ต้องรักษา" },
        objective = { "113:18163716:58468105", "ปราบผู้บุกรุก Boulderfist, Syndicate และ Witherbark ใน Stromgarde Keep แล้วกลับไปหา Groundskeeper Lomar" },
        description = { "437:65454631:1304365567", "มรดกเราอาจพังลง แต่ที่นี่ไม่ใช่ที่มั่นสุดท้าย เรายังมีสิ่งสำรอง ต้องซ่อนไว้เพื่อปกป้อง\n\nผู้สนับสนุนให้รักษารูปสลักและสุสานศักดิ์สิทธิ์ที่เหลือเพิ่มขึ้น พวกไร้ระเบียบที่ยึดอาณาจักรเก่าไม่รู้ว่าการแก้แค้นกำลังมา\n\nขับ Boulderfist กับ Syndicate กลับ มันต้องรู้ว่า Stromgarde ไม่ใช่เพียงกำปั้น นกอินทรี และก้อนหิน" },
        completion = { "223:1204308936:1307986615", "เริ่มต้นได้ดี เลือดของพวกมันจะหล่อเลี้ยงผืนดินที่บอบช้ำจากสงคราม ระหว่างที่เรารอเดินหน้าต่อ เมื่อเวลาผ่านไป ผืนดินจะค่อย ๆ ฟื้นคืนสิ่งที่สูญเสียไป\n\nจงรับสิ่งที่หลงเหลือจาก Stromgarde ไว้ เจ้าคู่ควรกับรางวัลที่มากกว่าคำยกย่อง" },
        objectiveLabels = {
            monster = { ["Boulderfist Mauler slain"] = "ปราบ นักขย้ำ Boulderfist", ["Syndicate Conjuror slain"] = "ปราบ นักอัญเชิญ Syndicate", ["Syndicate Prowler slain"] = "ปราบ นักซุ่มย่อง Syndicate", ["Witherbark Berserker slain"] = "ปราบ นักรบคลั่ง Witherbark" },
        },
    },
    [92872] = { -- Dutiful Steps
        title = { "13:2017215832:1514353526", "ก้าวแห่งหน้าที่" },
        objective = { "108:488199058:943165194", "โยน Pouch of Tomb Dust ลง The Great Sea แล้วกลับไปหา Caretaker Alaric ในห้องใต้ดินสุสาน Stromgarde Keep" },
        description = { "463:676461185:1777632116", "เราเฝ้าสุสานกับความรู้พิธีให้เกียรติวิญญาณที่ล่วงลับเหล่านี้ตลอดกาล\n\nเมื่อเจ้าลงใต้ดินสามชั้นแล้ว ก็ก้าวสู่การกลับโลกมีแสงตะวันพร้อมภูมิปัญญาศักดิ์สิทธิ์\n\nทุกฤดู เรานำฝุ่นบางส่วนจากสุสานไปโปรยมหาสมุทร Azeroth เป็นสัญลักษณ์วงจรที่เริ่มใหม่\n\nรับถุงเล็กนี้ ไปหน้าผาหลัง Stromgarde Keep แล้วโยนลงทะเล" },
        completion = { "197:1617945749:733252634", "คบไฟในห้องนี้ลุกสว่างขึ้นตอนที่เจ้าโยนถุงใบเล็กนั้นลงทะเล นั่นทำให้เรารู้ว่าเจ้าทำพิธีที่ได้รับมอบหมายตามที่รับปากไว้ พิธีนี้เรียบง่ายแต่สำคัญยิ่ง" },
        steps = { { "56:661306233:1376980003", "โยน Pouch of Tomb Dust ลงทะเลด้านหลัง Stromgarde" } },
    },
    [96984] = { -- Heart of Disruption
        title = { "19:1855252517:1442255796", "ใจกลางความปั่นป่วน" },
        objective = { "90:1236559687:1948573611", "เก็บ Arcane Mote ใน City of Dalaran ให้ Magus Wordeen Voidglare ที่ Tarren Mill" },
        description = { "499:1301425759:208541253", "เจ้าอาจไม่หวังดีต่อเรา แต่ข้าไม่ปฏิเสธคนช่วย หาก Dalaran ล่ม ทุกอย่างจะล่มตาม รวม Undercity ของเจ้า\n\nผู้อุปถัมภ์เจ้าอยากเข้าหรือ? ได้ ข้าจะลงมนตร์กุญแจให้ผ่านอาคม เข้าเมืองแล้วพบข้าที่ Violet Citadel จุดเริ่มเรื่องทั้งหมด ท่ามกลางความวุ่นวาย Kirin Tor คงยุ่งเกินหยุดเจ้า\n\nจะเก็บของอะไรก็ตามใจ แต่ไม่ว่าเกิดอะไร สิ่งสำคัญแรกคือหยุดหายนะ" },
        progress = { "79:2133954816:627891506", "เจ้าทำถูกแล้วที่กลับมาหาข้าทันที พบอะไรใน Dalaran บ้างไหม" },
        completion = { "173:1423231258:1422304130", "ตายจริง เงาของอัครจอมเวทหรือ น่าอับอายเสียจริงสำหรับพวกนั้น\n\nแล้ว Kirin Tor ยังปล่อยให้เจ้าเข้าไปถึงห้องด้านในด้วยหรือ น่าสนใจ เรื่องนี้อาจเปิดโอกาสให้เรา..." },
        required = { [251961] = { "11:575954581:468956656", "ละอองเวทอาร์เคน" } },
        steps = { { "11:575954581:468956656", "ละอองเวทอาร์เคน" } },
    },
    [96986] = { -- The Grave Knight
        title = { "16:2117573004:1368724273", "อัศวินสุสาน" },
        objective = { "83:876568650:1462130626", "ปราบ Atrexis the Grave Knight ใน City of Dalaran ให้ Melisara ที่ Tarren Mill" },
        description = { "219:1105921155:1445879387 N 151:1497701421:2141603096", "ในส่วนล่างลึกของเมืองจอมเวททางเหนือ มีคนทรยศเผ่าเรา หมอผีปลุกศพฝีมือน่าหวั่น สร้างทัพอันเดดใต้จมูก Kirin Tor\n\nข้าไม่สนชะตาเมืองจอมเวท {name} แต่อัศวินสุสานผู้นี้ถ่มน้ำลายใส่ทุกสิ่งที่ Forsaken ยึดถือ จบชีวิตมัน แสดงว่าไม่มีใครพ้นเงื้อมมือ Dark Lady" },
        progress = { "17:1985690322:1140814719", "ทำสำเร็จหรือยัง?" },
        completion = { "88:1338439241:1893283043", "ทำได้ยอดเยี่ยม เจ้าสัตว์ร้ายไม่คู่ควรเดินร่วมคนตาย ให้มันนอนอยู่ใต้พวกเขา" },
        objectiveLabels = {
            monster = { ["Atrexis the Grave Knight slain"] = "ปราบ Atrexis อัศวินสุสาน" },
        },
    },
    [96987] = { -- Opportunistic Education
        title = { "23:1909874082:1869939813", "ฉวยโอกาสศึกษา" },
        objective = { "105:1361480652:509089773", "เก็บ Founding of Dalaran จาก City of Dalaran ให้ Rexxie Copperclutch ใกล้ทางเข้าท่อระบายน้ำ" },
        description = { "116:968156430:1799699368 R 379:1472864917:1407575093", "โอ้ ผู้ประกอบการคิดตรงกัน ลอบเข้า Dalaran ยามวุ่นวายหรือ? จุ๊ ๆ\n\n{race} แบบที่ข้าชอบ!\n\nระหว่างเพื่อนจอมเวทยุ่ง เราอาจหาสมบัติที่ “วางผิดที่” ห้องสมุดทั้งแห่งอุทิศแก่เวทอาร์เคนหรูหรา หากเอาตำราลับมา ข้าขายได้งาม จะแบ่งกำไร\n\nเฮ้ อย่ามองอย่างนั้น เจ้าก็ไม่ได้มาเที่ยวทัศนศึกษา อยากร่วมไหมล่ะ?", variants = { { "501:1303864649:782819699", "ว่าแล้วเชียว คนหัวการค้าเหมือนข้านี่เอง แอบเข้า Dalaran ในยามวุ่นวายอย่างนี้หรือ จุ๊ ๆ\n\nอันเดดแบบนี้แหละที่ข้าชอบ!\n\nระหว่างที่เพื่อนจอมเวทของเรากำลังยุ่ง เราอาจหาเอาสมบัติที่ ‘วางผิดที่’ ได้บ้าง พวกเขามีห้องสมุดเป็นห้อง ๆ ไว้เก็บเรื่องเวทอาร์เคนหรูหราพวกนั้น ถ้าเจ้าเอาตำราลับมาให้ข้าสักเล่ม ข้าคงขายได้ราคางาม แล้วจะแบ่งกำไรให้เจ้า\n\nเฮ้ อย่ามองข้าแบบนั้น เจ้าก็ไม่ได้มาทัศนศึกษาเสียหน่อย จะเอาด้วยไหมล่ะ" }, { "503:1716323181:1669919453", "ว่าแล้วเชียว คนหัวการค้าเหมือนข้านี่เอง แอบเข้า Dalaran ในยามวุ่นวายอย่างนี้หรือ จุ๊ ๆ\n\nสกายบอร์นแบบนี้แหละที่ข้าชอบ!\n\nระหว่างที่เพื่อนจอมเวทของเรากำลังยุ่ง เราอาจหาเอาสมบัติที่ ‘วางผิดที่’ ได้บ้าง พวกเขามีห้องสมุดเป็นห้อง ๆ ไว้เก็บเรื่องเวทอาร์เคนหรูหราพวกนั้น ถ้าเจ้าเอาตำราลับมาให้ข้าสักเล่ม ข้าคงขายได้ราคางาม แล้วจะแบ่งกำไรให้เจ้า\n\nเฮ้ อย่ามองข้าแบบนั้น เจ้าก็ไม่ได้มาทัศนศึกษาเสียหน่อย จะเอาด้วยไหมล่ะ" } } },
        progress = { "73:771628913:1745880378", "ว่าอย่างไร? เจอห้องสมุดไหม? ต้องมีของดีในนั้นบ้างสิ" },
        completion = { "296:1715935903:89475104", "ข้าคงไม่ควรส่งคนโง่ไปหาวัตถุล้ำค่า นี่แทบไม่คุ้มขายซุ้มนักท่องเที่ยว! เจ้าแค่หยิบหนังสือเล่มแรกที่ยื่นออกมาหรือ?\n\nช่างเถอะ บางทีข้าจะพ่นสีทองแล้วบอกว่าเคยเป็นของอาร์คเมจหรืออะไรทำนองนั้น" },
        required = { [275996] = { "23:383221101:1738922638", "การก่อตั้ง Dalaran" } },
        steps = { { "23:383221101:1738922638", "การก่อตั้ง Dalaran" } },
    },
    [96988] = { -- Source of Power
        title = { "15:1480846688:329644945", "แหล่งพลัง" },
        objective = { "92:1785890107:1247955283", "เก็บ Cracked Sentry Cores 6 ชิ้น ใน City of Dalaran ให้ Doctor Martin Felben ที่ Undercity", amount = { "8:1089852795:1107240600 W1 83:2010680999:442909535", "เก็บ Cracked Sentry Cores {world1} ชิ้น ใน City of Dalaran ให้ Doctor Martin Felben ที่ Undercity" } },
        description = { "421:748383163:16658005", "เมื่อเมือง Dalaran ถูกสิ่งประดิษฐ์เวทของตนล้อม เป็นโอกาสเหมาะจะ...ขอยืมตัวอย่างสักหน่อย\n\nนึกถึงทัพอะบอมิเนชันขับเคลื่อนด้วยอาร์เคน Dark Lady ต้องยอมรับฝีมือเล่นแร่แปรธาตุข้า อาจแต่งตั้งเป็นหัวหน้า Royal Apothecary Society?\n\nเข้าเมืองหาแกนของสิ่งประดิษฐ์ มันคงไม่ยอมให้ง่าย ๆ ทำสิ่งที่จำเป็น" },
        completion = { "208:1582289230:216427578", "ร้าว ร้าว ร้าวหมดเลย\n\nข้าใช้พวกนี้ไม่ได้สักชิ้น! ข้าบอกให้หยุดการทำงานของพวกยามกล เจ้าเล่นทำลายเสียยับ! พวกมันจะอันตรายสักเท่าไรกัน\n\nฝันของข้าที่จะสร้างอะบอมมิเนชันจอมเวทต้องหยุดไว้ก่อน ตอนนี้น่ะนะ" },
        progress = { "118:2002213524:1576060284", "แกนพวกนี้มีค่าก็เพราะเปี่ยมพลัง ข้อเสียคือสิ่งประดิษฐ์เวทพวกนั้นก็ทรงพลังไปด้วย โชคดีล่ะ" },
        required = { [275997] = { "19:1597957305:1305452098", "แกนพลังของยามพิทักษ์ที่แตกร้าว" } },
        steps = { { "19:1597957305:1305452098", "แกนพลังของยามพิทักษ์ที่แตกร้าว" } },
    },
    [97539] = { -- Silky Sutures
        title = { "13:1245189655:59892572", "ไหมเย็บแผล" },
        objective = { "87:1975834422:180230186", "นำ Surgical Spidersilk 12 เส้น ไปให้ Doctor Gregory Victor ที่ Hammerfall ใน Arathi Highlands" },
        description = { "409:1517181401:1452198985 C 60:263569766:191408239", "ค่ายนี้ถูกทิ้งให้ผุพัง ความเสียหายจากการล้อมไม่ซ่อม ราวกับความละเลยเป็นนโยบาย ข้าไม่ให้เสื่อมเช่นนั้นที่นี่ หอผู้ป่วยอยู่ใต้ข้า และต้องใช้งานได้\n\nเสบียงเกือบหมด ต้องการอุปกรณ์เพิ่ม พอให้คนงานกับยามยืนต่อไหว\n\nยามคับขัน เราใช้ใยแมงมุมบิดเป็นไหมเย็บแผลภาคสนามที่ได้ผลดีได้\n\n{class} นำใยจากแมงมุมที่ย่องตามที่ราบสูงมาให้ข้า" },
        progress = { "75:2016679427:1752230987", "ผลออกแล้ว มีข่าวดีและข่าวร้ายสำหรับเจ้า\n\nอ้อ ขอโทษที" },
        completion = { { "264:1240751496:793246054", "202:1032853851:481140612 N 56:331750756:834505130", "202:1032853851:481140612 C 56:331750756:834505130", "202:1032853851:481140612 R 56:331750756:834505130" }, "ใยแมงมุมชั้นดี เมื่อกำลังถูกเย็บร่างกลับ การติดเชื้อนิดหน่อยเป็น...เรื่องน่าห่วงน้อยที่สุด\n\nอะแฮ่ม ขอโทษอีกครั้ง มุกหมอน่ะ\n\nขอบใจที่ช่วยหอผู้ป่วย สหาย ถ้าได้ความช่วยเหลือเช่นนี้สม่ำเสมอก็คงดี", variants = { { "202:1970707900:1581284816 N 56:331750756:834505130", "ใยแมงมุมชั้นดีทีเดียว ตอนที่ร่างเจ้ากำลังถูกเย็บเข้าด้วยกัน การติดเชื้อนิดหน่อยก็เป็น...เรื่องที่น่าห่วงน้อยที่สุด\n\nอะแฮ่ม ขอโทษอีกครั้ง มุกหมอน่ะ\n\nขอบใจที่ช่วยหอผู้ป่วย {name} ถ้าได้ความช่วยเหลือเช่นนี้สม่ำเสมอก็คงดี" } } },
        required = { [278225] = { "19:1622986376:281658444", "ใยแมงมุมสำหรับเย็บแผล" } },
        steps = { { "19:1622986376:281658444", "ใยแมงมุมสำหรับเย็บแผล" } },
    },
    [690] = { -- Malin's Request
        title = { "15:180447215:34689164", "คำขอของ Malin" },
        objective = { "54:958279454:1747545307", "หา Skuerto ที่ Refuge Pointe ใน Arathi Highlands" },
        description = { "11:927657569:725753248 N 459:942551573:916844639", "สวัสดี {name} เจ้าดูเป็นนักผจญภัย ข้ามีงานต้องให้ช่วย\n\nArchmage Trelane อาจารย์คนแรกข้า เพิ่งหนี Stromgarde ใน Arathi Highlands ขอให้ช่วยนำของที่ทิ้งคืน\n\nเมืองถูกล้อม เขาพยายามป้องกัน Tower of Arathor แต่ไม่สำเร็จ ข้ามีคนใน Highlands แล้ว แต่พวกเขาขอกำลังเพิ่ม สนใจไหม?" },
        completion = { "145:1803608161:1478739452", "Malin ส่งมาหรือ? ไม่สนหรอก แม้ Muradin ฟื้นจากตายขี่มังกรพาเจ้ามาก็เถอะ ข้ายุ่ง! ต้องการอะไรคุยกับ Kryten" },
    },
    [692] = { -- The Lost Fragments
        title = { "18:654113832:1154896706", "เศษคัมภีร์ที่หายไป" },
        objective = { "114:2103465991:1629559259", "นำ Torn Scroll Fragment, Crumpled Scroll Fragment และ Singed Scroll Fragment ไปให้ Theldurin the Lost" },
        description = { "481:887677557:193956266", "คัมภีร์ Myzrael...คัมภีร์ Myzrael?! เจ้าไม่อยากได้หรอก! มนตร์ดึงนางขึ้นพื้นผิวได้ ถ้าทำ เราแย่แน่!\n\nหรือ...สายแล้ว บางทีนางอิสระ กำลังรวบรวมกำลังก่อนปล่อยตนใส่เรา ถ้าเช่นนั้น เจ้าต้องมีคัมภีร์!\n\n...เสียดายที่พังแล้ว ธาตุเกรี้ยวกราดขโมยไปฉีก ตอนนี้แย่งเศษกัน\n\nแต่หากเก็บเศษมาได้ เราอาจซ่อม..." },
        progress = { "119:1225719596:1338530098", "พบเศษหรือยัง?!?! ต้องใช้คัมภีร์ Myzrael เพื่อขังนางอีกก่อนสายเกินไป!" },
        completion = { "31:1840788616:1659140002 N 149:922478440:2105500811", "อา เจอแล้ว! ทำได้ดี {name}! นี่อาจเป็นโอกาสเดียวต้านความชั่ว Myzrael!\n\nให้ข้าหาประแจเศษของแล้วดูว่าต่อเศษคืนได้ไหม..." },
        required = { [4518] = { "20:1122235360:1999682270", "เศษม้วนจารึกฉีกขาด" }, [4519] = { "24:1766949559:62919784", "เศษม้วนจารึกยับยู่ยี่" }, [4520] = { "22:1354172583:2105451239", "เศษม้วนจารึกไหม้เกรียม" } },
        steps = { { "20:1122235360:1999682270", "เศษม้วนจารึกฉีกขาด" }, { "24:1766949559:62919784", "เศษม้วนจารึกยับยู่ยี่" }, { "22:1354172583:2105451239", "เศษม้วนจารึกไหม้เกรียม" } },
    },
    [698] = { -- Lack of Surplus
        title = { "15:1907563852:1502037941", "เสบียงไม่เพียงพอ" },
        objective = { "66:935798779:949379414", "นำ Unprepared Sawtooth Flanks 8 ชิ้น ไปให้ Tok'Kar ที่ Swamp of Sorrows" },
        description = { "485:1319847815:567223008", "ข้ากำลังรวบรวมเสบียงให้ฐานใกล้หาดตะวันออก Tok'kar ทำเต็มที่ แต่ต้องผลัดเฝ้ายามและปรุงอาหารให้ทหาร จึงแทบไม่มีเวลาเหลือ\n\nพวกเขาชอบย่างเนื้อ sawtooth เมื่อมีโอกาส แต่ข้ายังส่งเพิ่มไม่ได้ ช่วยหน่อยได้ไหม?\n\nตัวอ่อนอร่อยสู้ตัวโตไม่ได้ อย่าล่าพวกนั้น ปล่อยให้โตเต็มที่อีกปีสองปี" },
        progress = { "9:860935253:1249669357 C 97:1295527744:1423017048", "Lok'tar {class} เดินทางผ่านบึงไม่ใช่ความเสี่ยงเล็กน้อย เจ้ากล้าที่ทดสอบฝีมือที่นี่" },
        completion = { "59:1621740880:410164972 N 282:567692380:1979138996", "อา วิเศษ! คืนนี้มีเนื้อสดย่างไฟ ขอบคุณ {name}\n\nเจ้าช่วยให้คืนข้างหน้าทนอยู่ได้ดีขึ้น ไฟสว่าง ท้องอิ่ม\n\nน่าแปลกใจอย่างยินดีที่เจ้าส่งของมา Dar ไม่ใช่ออร์คน่ามองที่สุด แต่อย่างน้อยนิสัยก็น่ารังเกียจน้อยกว่ากลิ่นตัวมาก" },
        required = { [6169] = { "25:780406438:1544136124", "เนื้อสีข้าง Sawtooth ที่ยังไม่ปรุง" } },
        steps = { { "25:780406438:1544136124", "เนื้อสีข้าง Sawtooth ที่ยังไม่ปรุง" } },
    },
    [699] = { -- Lack of Surplus
        title = { "15:1907563852:1502037941", "เสบียงไม่เพียงพอ" },
        objective = { "66:1725114041:1149587692", "นำ Sawtooth Snapper Claws 6 อัน ไปให้ Tok'Kar ที่ Swamp of Sorrows" },
        description = { "450:76875972:84268937", "เมอร์ล็อกตามชายฝั่งเป็นภัย เราจึงประจำที่นี่เพื่อป้องกัน Stonard หรือเตือนหากกำลังศัตรูมากเกิน ไม่มีเวลาพักนัก หากเจ้าไหว เราต้องการคนช่วยเพิ่ม\n\nกรงเล็บ sawtooth snapper ทำอาวุธชั้นดีได้เมื่อเตรียมถูกวิธี นำมาแล้วข้าจะตอบแทนอาวุธให้ สำหรับเนื้อสดและมิตรภาพดี ๆ" },
        progress = { "254:415929586:1482366470", "เหล้าน้ำผึ้งดี ไฟอุ่น ทัพออร์ค และคลังอาวุธ...เท่านี้ก็พอสำหรับชายฝั่ง ข้าไม่เสียใจที่ปกป้อง Stonard แต่คงดีหากวันหนึ่งมีโพรงที่พัก หรืออย่างน้อยหอคอย" },
        completion = { "35:2094538912:662614314 N 263:1769401747:608849346", "ดีใจที่เจ้ายังปลอดภัย {name}\n\nกรงเล็บใช้ได้ดี ยิ่งมีอาวุธพร้อมรับการบุกมาก เรายิ่งมั่นคง\n\nข้าจะเริ่มทำอาวุธให้เร็วที่สุด ใช้เวลาไม่นาน ข้าชำนาญและทำได้เร็วแล้ว" },
        required = { [6168] = { "21:2037216018:1834460298", "กรงเล็บของ Sawtooth Snapper" } },
        steps = { { "21:2037216018:1834460298", "กรงเล็บของ Sawtooth Snapper" } },
    },
    [703] = { -- Barbecued Buzzard Wings
        title = { "23:1522848117:693442078", "ปีกแร้งย่าง" },
        objective = { "36:2129460874:991257443", "นำ Buzzard Wings 4 ชิ้น ไปให้ Rigglefuzz" },
        description = { "345:2045368136:112050481", "ใช่ ปีกแร้งย่างข้าเป็นเมนูโปรด! ซอสเข้มข้น เนื้อรสจัด กลิ่นเรียกคนหิววิ่งมาจากหลายไมล์!\n\nข้ามีของทำครบทุกอย่าง...ยกเว้นปีกแร้ง!\n\nอยากกินก็นำปีกมา มากพอแล้วข้าอาจแบ่งสูตรให้ด้วย!" },
        progress = { "7:989913233:66981971 N 28:1354470305:2067394980", "สวัสดี {name} นำปีกมาให้หรือยัง?" },
        completion = { "142:1293073661:436915115", "อา จะเริ่มทำปีกทันที แทบรู้รสแล้ว!\n\nนี่สูตร เผื่ออยากทำเอง!" },
        required = { [3404] = { "12:457437459:533839197", "ปีกแร้ง" } },
        steps = { { "12:457437459:533839197", "ปีกแร้ง" } },
    },
    [705] = { -- Pearl Diving
        title = { "12:674745530:1393783365", "ดำน้ำหาไข่มุก" },
        objective = { "50:2099890518:1724572584", "นำ Blue Pearls 9 เม็ด ไปให้ Rigglefuzz ที่ Badlands" },
        description = { "492:698339701:1777391850", "Badlands โหดร้าย เต็มด้วยนักล่าดุร้ายและพวกคุ้ยซากใจกล้า น่ากลัว โดยเฉพาะก็อบลินตัวเตี้ย เพื่อรอดข้าต้องมีเล่ห์เหลี่ยม!\n\nข้ารู้สูตรระเบิดแสง ใช้ไล่สัตว์ แต่ส่วนผสมหนึ่งใกล้หมด ผงไข่มุกสีฟ้าบด หาให้แล้วข้าจะตอบแทนคุ้ม\n\nเฮะ หวังว่าใส่รองเท้าดี ไข่มุกที่ต้องการอยู่ในหอยที่ Vile Reef\n\nใช่ Vile Reef ใน Stranglethorn!" },
        progress = { "53:155310706:1202351595", "ได้ไข่มุกไหม? ระเบิดแสงข้าใกล้หมด!" },
        completion = { "166:1196111159:1699146148", "พวกนี้เหมาะมาก! แค่บดเป็นผง...แล้วผสมนี่นิด นั่นหน่อย\n\nระวัง พวกคุ้ยซาก! เตรียมตาพร่าได้!" },
        required = { [4611] = { "10:1040559381:870529020", "ไข่มุกสีน้ำเงิน" } },
        steps = { { "10:1040559381:870529020", "ไข่มุกสีน้ำเงิน" } },
    },
    [706] = { -- Fiery Blaze Enchantments
        title = { "24:99653398:1103353193", "มนตร์เปลวเพลิง" },
        objective = { "49:182627092:274460929", "หา Black Drake's Heart ให้ Sigrun Ironhew" },
        description = { "491:1939644883:25722785", "เมื่อเป็นศิษย์ Feranor Steeltoe ข้าเรียนเทคนิคพิเศษลงมนตร์ไฟในอาวุธ ข่าวล่าสุดเขาทำงานโรงตีเหล็กกับคณะล่าใน Lordaeron\n\nบอกรายละเอียดมากไม่ได้ แต่ต้องใช้เลือดจากหัวใจลูกเดรคดำหายากที่ยังเต้นอยู่ ระหว่างรอข่าว Ironforge ข้าไม่มีอะไรทำมาก หากนำหัวใจลูกมังกรจาก Lethlor Ravine มา ข้าจะแสดงฝีมือ!" },
        progress = { "19:584766569:1012911725 C 1:63:63", "ล่าเป็นอย่างไร {class}?" },
        completion = { "92:1065426768:530113182", "อา ใช้ได้ยอดเยี่ยม จะให้อาวุธเจ้าโจมตีด้วยความร้อนแผดเผา!" },
        required = { [4612] = { "19:627347414:417420464", "หัวใจเดรกดำ" } },
        steps = { { "19:627347414:417420464", "หัวใจเดรกดำ" } },
    },
    [708] = { -- The Black Box
        title = { "13:1592579662:854975746", "กล่องดำ" },
        objective = { "61:1116312156:1434128438", "นำ Corroded Black Box ไป Hall of Arms ที่ Ironforge" },
        description = { "301:1020454773:908093230", "ผิวกล่องโลหะดำเป็นหลุมหนัก ราวแช่กรด คงอยู่ในท้องคอนดอร์ยักษ์นาน\n\nเมื่อพลิก พบตราประทับใต้กล่อง ใต้ตรามีคำว่า\n\n“เครื่องยนต์ #19 - กองพลปิดล้อม Ironforge”" },
        required = { [4613] = { "18:770183831:565175667", "กล่องดำที่ถูกกัดกร่อน" } },
        steps = { { "18:770183831:565175667", "กล่องดำที่ถูกกัดกร่อน" } },
    },
    [710] = { -- Study of the Elements: Rock
        title = { "27:592178503:115648072", "ศึกษาธาตุ: หิน" },
        objective = { "77:1131147281:74583422", "หา Small Stone Shards 10 ชิ้น แล้วนำไปให้ Lotwil Veriatus ที่ Badlands" },
        description = { "456:551201239:1857005535", "ข้าหยุดที่ Badlands ทำโครงการล่าสุด ตรวนพันธนาการธาตุ\n\nเมื่อเสร็จ จอมเวทจะเรียกธาตุที่ทรงพลังกว่าเพื่อใช้งานได้มากขึ้น เริ่มจากเศษหินเล็ก เพื่อทดสอบมนตร์โจมตีใหม่กับอุปกรณ์ที่ประกอบไว้\n\nหาเศษจากธาตุหินตัวเล็กทางตะวันตกได้ง่าย นำมาให้หน่อยได้ไหม?" },
        progress = { "298:1862300577:932456755", "แถบนี้เหมาะกับ...ช่วยจับให้อยู่ตำแหน่งครู่ได้ไหม? ใช่ แบบนั้น ตามแนวเวกเตอร์ตั้งฉาก เมื่อกี้ข้าพูดอะไร...อ้อ เหมาะทดสอบโครงการใหม่ วัตถุดิบ พื้นที่เปิดโล่ง...ผู้ใช้ศาสตร์อันชาญฉลาดรู้แจ้งจะขออะไรอีก?" },
        completion = { "23:761911698:817441689 N 272:871925961:2119881909", "พวกนี้ใช้ได้ดี {name} ขอบคุณ อืม ทรายมากกว่าคาด ต้องปรับสัมประสิทธิ์เสียดทาน ไม่ เดี๋ยว น้ำมันเย็นน่าจะยังทำให้ค่าน้อยจนละได้\n\n<Lotwil พึมพำ กำมือข้างหนึ่งวางบนฝ่ามืออีกข้าง จ้องอย่างหลงใหล>" },
        required = { [4626] = { "17:1153515648:1665181696", "เศษหินขนาดเล็ก" } },
        steps = { { "17:1153515648:1665181696", "เศษหินขนาดเล็ก" } },
    },
    [711] = { -- Study of the Elements: Rock
        title = { "27:592178503:115648072", "ศึกษาธาตุ: หิน" },
        objective = { "61:2107357245:1043635071", "นำ Large Stone Slabs 3 แผ่น ไปให้ Lotwil Veriatus ที่ Badlands" },
        description = { "N 463:1035498914:1413507167", "{name} เจ้าพิสูจน์ว่าเก่งกว่าศิษย์ข้าทั้งหมดรวมกัน\n\nของต่อไปต้องใช้กำลังอีกหน่อย หาแผ่นหินใหญ่จากธาตุหินได้หากระวัง ร่างมันใหญ่และแข็งแกร่งกว่า จึงน่ามีชิ้นใหญ่พอทดลอง พบไกลไปตะวันตก หรือทางตะวันออกเฉียงใต้ตามขอบภูเขา\n\nไม่ต้องรีบ ข้าต้องทดสอบชิ้นเล็กที่นำมาก่อน" },
        progress = { "18:1160833352:1863434538 N 205:724538561:217533362", "ข้าพอใจมาก {name} มนตร์ส่งผลต่อชิ้นเล็กตามคาด หากทดลองสำเร็จอย่างที่เห็นล่วงหน้า ธาตุที่ควบคุมได้จะทำให้ของที่เคยเรียกมาก่อนด้อยไปเลย" },
        completion = { "N 94:1403909848:1640927595", "{name} น่าทึ่ง! นึกว่าต้องใช้ทอเรนหกคนขนทั้งหมดมา" },
        required = { [4627] = { "16:1632330535:1735905168", "แผ่นหินขนาดใหญ่" } },
        steps = { { "16:1632330535:1735905168", "แผ่นหินขนาดใหญ่" } },
    },
    [712] = { -- Study of the Elements: Rock
        title = { "27:592178503:115648072", "ศึกษาธาตุ: หิน" },
        objective = { "67:1702029415:1529174460", "นำ Bracers of Rock Binding 5 อัน ไปให้ Lotwil Veriatus ที่ Badlands" },
        description = { "N 459:1068822447:326459195", "{name} ยังต้องการอีกส่วนจากธาตุที่ Badlands คือปลอกแขนพันธนาการหินของธาตุหินใหญ่ ตามคำนวณ น่าจะพอวัดกำลังตรวนข้า\n\nการส่องทางเวทเห็นฝูงธาตุใหญ่ทางตะวันตกเฉียงใต้ หากจำไม่ผิดใกล้ออกร์\n\nนำมา 5 อันเผื่อสำรอง Servo ขึ้นชื่อว่าทำส่วนประกอบกับงานวิจัยข้าหาย" },
        progress = { "38:1945115883:10107405 N 329:1074475753:953530165", "แผ่นหินเหมาะมาก {name} Lucien จะนำส่วนเกินกลับ Kharanos เมื่อเสร็จ อาจมีประโยชน์อีก\n\nเช่น ใช้เป็นฐานที่หลบภัยสะดวก เมื่อข้าเริ่มศึกษาแนวทางหลายศาสตร์สำหรับวัตถุระเบิดกำลังสูง...\n\n<เสียง Lotwil ค่อยจางเมื่อกลับไปทดลอง>" },
        completion = { "N 186:1569129749:1756725110", "{name} เคยคิดเป็นผู้ช่วยวิจัยไหม? ไม่หรือ? ไม่รู้จะทำอย่างไรหากขาดฝีมือเจ้า ทั้งปัญญา ความใฝ่รู้ และกำลังในคนเดียว" },
        required = { [4628] = { "23:481290864:915427515", "ปลอกรัดแขนแห่งพันธนาการหิน" } },
        steps = { { "23:481290864:915427515", "ปลอกรัดแขนแห่งพันธนาการหิน" } },
    },
    [713] = { -- Coolant Heads Prevail
        title = { "21:1325499213:304673649", "หัวเย็นด้วยสารหล่อเย็น" },
        objective = { "59:1957265886:1710881261", "หา Frost Oil แล้วนำไปให้ Lotwil Veriatus ที่ Badlands" },
        description = { "497:1127147995:1119106482", "จะเล่าเรื่อง Frost Oil ไม่มีอะไรป้องกันเครื่องยนต์กับเฟืองร้อนเกินได้เท่านี้\n\nคุณสมบัติหล่อเย็นพิเศษ อายุการหล่อลื่นไม่มีใครเทียบ ยังช่วยคงมนตร์บนวัตถุเวทด้วย\n\nต้องการขวดหนึ่งเพิ่มพลังเวทตรวนให้แรงพอหยุดเพื่อนที่เรียกมาไม่ให้ฆ่าเราหมด\n\nBro'kin สหายก็อบลินสอนทำได้ เขาอยู่ Alterac" },
        progress = { "84:223701463:1023406232", "พบน้ำมันหรือยัง? หากหาได้จะช่วยมาก" },
        completion = { "223:754328804:507441126 N 24:1176516665:1050371940", "วิเศษ! น่าจะเป็นสารหล่อเย็นเหมาะที่สุดสำหรับปลอกแขนใหม่ หากมนตร์ไม่อยู่ร้อยปี ข้าจะยกของทั้งหมดให้ Servo\n\nจอมเวท Assembly ต้องทึ่งเมื่อข้าเสร็จ {name} รอดูได้เลย" },
        required = { [3829] = { "9:2048338092:2117751599", "น้ำมันเยือกแข็ง" } },
        steps = { { "9:2048338092:2117751599", "น้ำมันเยือกแข็ง" } },
    },
    [714] = { -- Gyro... What?
        title = { "13:731769572:798954427", "ไจโร...อะไรนะ?" },
        objective = { "57:744745078:148525388", "นำ Gyrochronatom ไปให้ Lotwil Veriatus ที่ Badlands" },
        description = { "N 389:807830907:1933690000", "{name} เจ้าทำงานเกินทุกมาตรฐาน\n\n<Lotwil เห็นชัดว่าใจจดจ่องาน>\n\nหากเจอกัน Kharanos มาสมัครงานได้เลย\n\nอุ๊บ! เร็ว จับ...ใช่ อันนั้น ขอบใจ\n\nขาดอีกอย่าง ชิ้นเล็กแต่สำคัญนัก gyrochronatom\n\nหากเอามาให้ ข้าน่าจะพร้อมทำให้เสร็จ" },
        progress = { "85:1860823727:553221686", "ใช่ ใช่ ใช่ รอครู่\n\n<Lotwil ทำอุปกรณ์บางอย่างต่อ>" },
        completion = { "351:925573473:1822456305", "ฮ่า!\n\n<Lotwil คว้า gyrochronatom จากเจ้า>\n\nสมบูรณ์...เกือบเสร็จแล้ว ไม่ จริง ๆ เกือบเสร็จ โครงการนี้สำคัญอันดับแรก...ตอนนี้ ใส่เข้าที่แล้วเจ้าจะเห็นสิ่งที่ช่วยสร้าง อีกไม่กี่นาที...อาจ...นานกว่า บางทีนานมาก รอดู..." },
        required = { [4389] = { "13:1379758170:702332071", "เครื่อง Gyrochronatom" } },
        steps = { { "13:1379758170:702332071", "เครื่อง Gyrochronatom" } },
    },
    [715] = { -- Liquid Stone
        title = { "12:310793701:77512276", "หินเหลว" },
        objective = { "95:1408784519:1116366639", "นำ Healing Potion และ Lesser Invisibility Potion ไปให้ Lucien Tosselwrench ที่ Badlands" },
        description = { "91:388032336:1579837106 N 397:444607905:1115834042", "ข้าว่าของที่หาให้ Lotwil จะเป็นเรื่องน่าห่วงน้อยที่สุด {name} แต่เจ้าพิสูจน์ว่าเก่งศาสตร์ที่เขาเทิดทูนแล้ว ช่วยข้าบ้างไหม?\n\nต้องการยาล่องหนกับยารักษา ทั้งสองอาจมีประโยชน์เร็ว ๆ นี้หากเขาทำสำเร็จ\n\nตอบแทนด้วยสูตรยาที่ข้าพัฒนาระหว่างเรียนกับ Lotwil อิงงานวิจัยเขาที่ Badlands" },
        progress = { "67:1468013496:320595961", "เขาใกล้เสร็จขึ้นแล้ว ฝั่งเจ้าเป็นอย่างไร?" },
        completion = { "24:516697915:1476769758 N 61:7974597:884330782", "ใช่เลย!\n\nหมายถึง ขอบคุณ {name} พวกนี้ช่วยเดินทางใน Badlands ได้" },
        required = { [929] = { "14:375914481:1243822641", "ยาฟื้นพลังชีวิต" }, [3823] = { "26:654985145:1070803384", "ยาล่องหนระดับต้น" } },
        steps = { { "14:375914481:1243822641", "ยาฟื้นพลังชีวิต" }, { "26:654985145:1070803384", "ยาล่องหนระดับต้น" } },
    },
    [716] = { -- Stone Is Better than Cloth
        title = { "26:1984460085:952496096", "หินดีกว่าผ้า" },
        objective = { "75:1158758099:1461261388", "นำ Patterned Bronze Bracers ไปให้ Lucien Tosselwrench ที่ Badlands" },
        description = { "32:2016089710:1498731452 N 419:107331420:1769701207", "รู้ว่า Lotwil ขี้เหนียวแค่ไหน {name} ข้าจึงจะทำของตอบแทนความลำบาก อาจช่วยป้องกันหายนะจากสิ่งประดิษฐ์ใหม่ของเขาด้วย\n\nข้าใช้หินส่วนเกินที่เจ้าเก็บ ทำปลอกแขนดี ๆ ที่อาจอยากสวม แน่นอนว่าลงมนตร์\n\nแค่ต้องการปลอกแขนสำริดมีลายที่ช่างตีเหล็กสร้าง เพื่อทำชิ้นที่ให้เจ้าเสร็จ" },
        progress = { "45:1395566924:128353610 N 40:430194564:819751537", "อย่ารอหาปลอกแขนนานนัก {name}\n\nใครรู้ว่าจะเกิดอะไรต่อ?" },
        completion = { "13:939218444:1640774044 N 15:607320410:1637354269", "นี่ {name} ลองสวมสิ" },
        required = { [2868] = { "24:1232173144:251921374", "ปลอกรัดแขนสำริดมีลวดลาย" } },
        steps = { { "24:1232173144:251921374", "ปลอกรัดแขนสำริดมีลวดลาย" } },
    },
    [717] = { -- Tremors of the Earth
        title = { "20:676971877:1238557323", "แผ่นดินสั่นสะเทือน" },
        objective = { "286:2034421246:928224920", "ใช้ Sign of the Earth กระตุ้น Pillars of Amethyst, Opal และ Diamond เพื่อรับ Runestones\n\nวางศิลารูนใน Seal of the Earth เพื่อปล่อย Blacklash และ Hematus\n\nฆ่าทั้งคู่ แล้วนำ Blacklash's Bindings, Chains of Hematus และ Sign of the Earth กลับไปให้ Garek" },
        description = { "444:1994063980:1878520134 N 41:1053245470:604881079", "ชัดเจนว่าเรารับรองไม่ได้ว่า Blacklash กับ Hematus จะถูกขังใน Lethlor ต่อไป มังกรดำมาตั้งรัง ออกร์ยังขโมยตราได้ แสดงว่าต้องใช้มาตรการเด็ดขาดกว่า\n\nศิลารูนสามก้อนคงคุกเดรคไว้ ต้องใช้ Sign of the Earth เท่านั้นจึงนำออกได้ แล้วใช้ศิลารูนทำลายผนึกขังพวกมัน\n\n{name}...ทำให้ความฝันมันคงอยู่ชั่วนิรันดร์เถิด" },
        progress = { "141:1715981174:2031118486", "มนตร์และพลังแข็งแกร่งคงคุกเดรคมานาน แต่เราปล่อยให้มีโอกาสที่ Blacklash กับ Hematus ถูกปล่อยไม่ได้" },
        completion = { "152:406480462:26341855", "Kirin Tor ไม่ต้องกังวลนักโทษ Lethlor อีก ข้าจะกลับรายงานอาจารย์ Krasus ต้องพอใจแน่" },
        required = { [4615] = { "20:518563996:1005790211", "เครื่องพันธนาการของ Blacklash" }, [4640] = { "17:1138388394:1345535902", "เครื่องหมายแห่งปฐพี" }, [4645] = { "17:1903694704:1841550863", "โซ่ของ Hematus" } },
        objectiveLabels = {
            item = { ["Blacklash's Bindings"] = "เครื่องพันธนาการของ Blacklash", ["Sign of the Earth"] = "เครื่องหมายแห่งปฐพี", ["Chains of Hematus"] = "โซ่ของ Hematus" },
        },
    },
    [718] = { -- Mirages
        title = { "7:1417246692:1634119036", "ภาพลวงกลางทะเลทราย" },
        objective = { "45:1932824377:1822028356", "นำ Supply Crate กลับมาให้ Sigrun Ironhew" },
        description = { "502:869582686:221562458", "ตอนรีบหนีจุดขุด Uldaman เราต้องทิ้งเกวียนและลังเสบียงมากมาย ออกร์ Camp Kosh รุมอุปกรณ์เราราวแร้งลงศพเน่า กลิ่นก็ไม่ได้ดีกว่า หมายถึงดีกว่าศพน่ะ\n\nมันเอารถขนอาวุธไป...ก็ เอ่อ น่าอายหน่อย...เราจึงหาอาหารไม่ได้\n\nลำบากอยู่ ช่วยหน่อยได้ไหม?" },
        progress = { "104:545179347:1053633145", "ขอบอก ทะเลทรายไม่เหมาะจะหิว สหาย\n\nเฮ้...นั่นอะไรตรงนั้น..." },
        completion = { "16:1674768160:1211638592 N 147:41588480:111201320", "ขอบคุณมาก {name} ระหว่างเจ้าไป ข้า...เอ่อ...กลืนทรายเต็มปาก มัน...\n\nช่างเถอะ คืนนี้จะออกหาอาหาร กินอย่างราชา!" },
        required = { [4629] = { "12:463303343:1773873801", "ลังเสบียง" } },
        steps = { { "12:463303343:1773873801", "ลังเสบียง" } },
    },
    [719] = { -- A Dwarf and His Tools
        title = { "21:544695410:1812554021", "คนแคระกับเครื่องมือ" },
        objective = { "90:1025059284:1401913711", "หา Ryedol's Lucky Pick แล้วนำคืน Prospector Ryedol ทางใต้ของ Hammertoe's Dig Site" },
        description = { "5:140209925:2105781119 N 488:1473984685:540461037", "เฮ้ {name} ระวังแถวนี้ Dark Iron เต็มไปหมด ดูเหมือนตระกูล Shadowforge\n\nมันเพิ่งบุกจุดขุดที่ข้าทำงาน ฆ่าเกือบทุกคน รวม Hammertoe หัวหน้าข้า ข้าหนีแทบไม่รอด\n\nจุดขุดอยู่เหนือใกล้นี่ ข้าวางแผนเอาเสบียงคืน โดยเฉพาะอีเต้อนำโชค\n\nช่วยได้ไหม? Dark Iron บัดซบตัวใดตัวหนึ่งต้องมีอีเต้อ ใครก็ได้ในพวกมัน" },
        progress = { "82:1919515511:217528317", "ไม่รู้ Shadowforge หาอะไร แต่มีจุดหมายแน่นอน" },
        completion = { "17:435792949:940096437 C 86:169380573:701090815", "เจ้าช่วยชีวิตข้า {class} ดีใจที่มีคนสั่งสอน Shadowforge ขอบใจที่ช่วย" },
        required = { [4616] = { "19:1177356571:2139371929", "อีเต้อนำโชคของ Ryedol" } },
        steps = { { "19:1177356571:2139371929", "อีเต้อนำโชคของ Ryedol" } },
    },
    [723] = { -- Prospect of Faith
        title = { "17:2055945797:264527637", "ความหวังแห่งศรัทธา" },
        objective = { "61:1259327248:1974012966", "นำ Hammertoe's Amulet ไปให้ Prospector Ryedol ที่ Badlands" },
        description = { "108:1295725097:102657501 N 262:69583420:176213920", "<Hammertoe กุมแผล สงบใจครู่ก่อนพูดอีก>\n\nหา Ryedol {name} เอาเครื่องรางข้าให้เขา <ไอ ไอ> เขาจะ...<ไอ> รู้ว่าต้องทำอะไร รู้ว่าข้าหาต้นกำเนิดเผ่าเรา และเขา...<ไอ>...รู้ว่าข้ามีภารกิจหยุด Shadowforge ด้วย ปล่อยให้มันพบคัมภีร์ไม่ได้...<ไอ>" },
        progress = { "74:319069997:1226187563", "จะบอกว่าวันแย่ แต่นี่ Badlands ทุกวันก็แย่" },
        completion = { "189:1095949874:1988500539", "เครื่องราง Hammertoe หรือ? ตอนแค่คิดว่าเขาตาย ข้ายังมีกำลังใจกว่านี้ รู้แน่ยิ่งเจ็บ เครื่องรางคืองานทั้งชีวิตเขา ปล่อยให้ตายเปล่าไม่ได้" },
        required = { [4635] = { "18:260398429:841444850", "เครื่องรางของ Hammertoe" } },
        steps = { { "18:260398429:841444850", "เครื่องรางของ Hammertoe" } },
    },
    [724] = { -- Prospect of Faith
        title = { "17:2055945797:264527637", "ความหวังแห่งศรัทธา" },
        objective = { "57:636020723:1473852442", "นำ Hammertoe's Amulet ไปให้ Historian Karnik ที่ Ironforge" },
        description = { "383:1271193617:1439389336", "เอาล่ะ...ใครรู้ว่าควรทำอะไร?\n\nHistorian Karnik! ใช่เลย!\n\nอยู่ Ironforge เขาช่วยได้ ทำงานกับ Hammertoe หาวัตถุสาบสูญใน Uldaman\n\nเดาว่า Shadowforge รู้ว่าสองคนมีความรู้มากกว่าที่เผย\n\nบอกเหตุที่เกิดกับ Hammertoe แล้วมอบเครื่องราง Karnik จะบอกขั้นต่อไป" },
        progress = { { "143:718617308:1756233075", "145:680001026:1966742796" }, "อา นักเดินทางอีกคนมาขอบางอย่างจากคนแคระ\n\nขอโทษจริง ตอนนี้ไม่มีเวลาตอบคำถามไร้สาระ" },
        completion = { "345:588899292:1993085570", "โอ้! นี่คนละเรื่องเลย เจ้าอาจยังไม่รู้ความร้ายแรงใช่ไหม?\n\nข้าเศร้ากับการตาย Hammertoe มาก แต่ส่งเจ้ามาพร้อมเครื่องรางแสดงว่าเขาเข้าใจสิ่งที่เสี่ยง\n\nต้องไว้ทุกข์ภายหลัง\n\nจะให้ดูเหตุผลหนึ่งที่เครื่องรางล้ำค่านัก" },
        required = { [4635] = { "18:260398429:841444850", "เครื่องรางของ Hammertoe" } },
        steps = { { "18:260398429:841444850", "เครื่องรางของ Hammertoe" } },
    },
    [725] = { -- Passing Word of a Threat
        title = { "24:1409001891:100594864", "ส่งข่าวภัยคุกคาม" },
        objective = { "43:1734522578:1435150045", "หา Advisor Belgrum แล้วส่งบันทึกของเขาให้" },
        description = { "N 360:1705736570:1420357411", "{name} รีบหา Advisor Belgrum เร็วที่สุด เล่าสิ่งที่เห็นแล้วถามว่าต้องการให้ทำต่ออย่างไร บันทึกจะอธิบายเพิ่ม\n\nระหว่างนี้ข้าจะพูดกับวิญญาณ Hammertoe บางทีรู้อะไรช่วยหยุดกิจการ Shadowforge สารเลวใน Badlands เราทำได้เพียงภาวนา" },
        progress = { "10:869148981:1828037909 C 1:46:46", "หือ? ว่าอย่างไร {class}" },
        completion = { "132:1455506248:808837255", "อา ข่าวจาก Historian Karnik ยอดเยี่ยม\n\nข้ามีเวลาให้ธุระเขาเสมอ\n\n<Advisor Belgrum เปิดบันทึกอ่าน>" },
        required = { [4622] = { "30:40370919:1869877677", "จดหมายปิดผนึกถึงที่ปรึกษา Belgrum" } },
        objectiveLabels = {
            item = { ["Sealed Note to Advisor Belgrum"] = "จดหมายปิดผนึกถึงที่ปรึกษา Belgrum" },
        },
    },
    [726] = { -- Passing Word of a Threat
        title = { "24:1409001891:100594864", "ส่งข่าวภัยคุกคาม" },
        objective = { "26:33328117:1774565602", "คุยกับ Historian Karnik" },
        description = { "109:988141:1521321645 N 182:80278789:1372640426", "<Advisor Belgrum อ่านถึงท้าย ตาเบิกกว้างชั่วครู่>\n\nโอ้ ข่าวร้าย\n\n{name} กลับหา Historian Karnik แจ้งว่าในพระนามกษัตริย์ ให้ดำเนินการตามข้อมูลรวดเร็วเด็ดขาด ต้องหยุด Shadowforge ใน Badlands" },
        completion = { "78:424774245:466800731 N 164:1266425449:1651258549", "เจ้าปฏิบัติเรื่องนี้เร่งด่วนราวกษัตริย์เอง {name}\n\nเอาล่ะ รู้ว่าอะไรโค่น Shadowforge ได้\n\nเราชะลอมันใน Uldaman ได้หากโจมตีฐานปฏิบัติการ Angor Fortress" },
    },
    [727] = { -- To Ironforge for Yagyin's Digest
        title = { "32:2058242425:684178275", "ไป Ironforge ขอ Yagyin's Digest" },
        objective = { "83:1938986340:284840949", "มอบ Sigil of the Hammer ให้ Gerrig Bonegrip ที่ Forlorn Cavern ใน Ironforge" },
        description = { "441:1781239362:1122763757", "จารึกบอกมาก แต่ไม่พอ! ยังไม่พอเลย!\n\nมีหนังสือ ย่อความที่ Yagyin เขียนสมัยโบราณ ...คนที่ข้าหนีมา...เก็บไว้หลายแห่ง ผู้รู้ที่สุดศึกษามัน มีความรู้มหาศาล ความรู้ปกป้องเรา!\n\nไปหา Gerrig Bonegrip ในร้านที่ Forlorn Cavern ของ Ironforge แสดงตรานี้ เขาจะคิดว่าเป็นพวกเดียวกัน ขอ Yagyin's Digest...แล้วนำมาให้ข้า!" },
        progress = { "77:430464052:1884705797", "สวัสดี ยินดีต้อนรับร้าน แต่ระวังจับของ\n\nความรู้คร่าชีวิตได้" },
        completion = { { "59:1830114664:898951702", "58:1380775744:613824356" }, "โอ้ สวัสดี สหายร่วมอุดมการณ์\n\nสรรเสริญผู้พำนักเบื้องล่าง" },
        required = { [4648] = { "19:884282118:1715358744", "ตราผนึกแห่งค้อน" } },
        steps = { { "19:884282118:1715358744", "ตราผนึกแห่งค้อน" } },
    },
    [728] = { -- To the Undercity for Yagyin's Digest
        title = { "36:2140668940:616216007", "ไป Undercity ขอ Yagyin's Digest" },
        objective = { "67:287861780:123904178", "นำ Sigil of the Hammer ไปให้ Keeper Bel'dugur ที่ Undercity" },
        description = { "419:12380349:730234144", "จารึกบอกมาก แต่ไม่พอ! ยังไม่พอเลย!\n\nมีหนังสือ ย่อความที่ Yagyin เขียนสมัยโบราณ ...คนที่ข้าหนีมา...เก็บไว้หลายแห่ง ผู้รู้ที่สุดศึกษามัน มีความรู้มหาศาล ความรู้ปกป้องเรา!\n\nไป Keeper Bel'dugur ที่ Undercity แห่ง Lordaeron แสดงตรานี้ เขาจะคิดว่าเป็นพวกเดียวกัน ขอ Yagin's Digest...แล้วนำมาให้ข้า!" },
        progress = { "21:928828938:1949857505 C 145:88212215:1480114538", "อา เห็น {class} กระตือรือร้น มาเรียนจากของสะสมข้าหรือ? ดี!\n\nแต่ระวัง ความรู้มอบพลังแก่ผู้แข็งแกร่ง...และทำผู้อ่อนแอเสียสติ" },
        completion = { "29:920532748:335031867 C 185:1763382039:693249327", "แสดงสัญญาณให้แนบเนียน {class} มีผู้ไม่เชื่อความชอบธรรมคำปฏิญาณเรา\n\nและผู้ที่หากรู้เรื่องเรา จะอยากให้ล้มเหลว\n\nต้องระวัง เฝ้าดู และอดทนเสมอ" },
        required = { [4648] = { "19:884282118:1715358744", "ตราผนึกแห่งค้อน" } },
        steps = { { "19:884282118:1715358744", "ตราผนึกแห่งค้อน" } },
    },
    [732] = { -- Tremors of the Earth
        title = { "20:676971877:1238557323", "แผ่นดินสั่นสะเทือน" },
        objective = { "41:916057704:423002914", "นำ Sign of the Earth คืนให้ Garek" },
        description = { "500:1697032830:1535394681", "Sigrun บอกว่าเจ้าช่วยมาก ข้าอาจขอให้ช่วยบ้าง อาจารย์ Krasus แห่ง Kirin Tor ส่งข้ามายุติปัญหาใน Lethlor Ravine\n\nเปิดเผยรายละเอียดหน้าที่และงานไม่ได้ แต่มั่นใจได้ว่าสำคัญยิ่ง\n\nออกร์พเนจรกลุ่มหนึ่งที่เห็นใกล้ Camp Boff บางครั้ง ขโมย Sign of the Earth ข้าต้องได้คืน นำมาแล้วจะเล่าเพิ่ม" },
        progress = { "285:717986361:1960346053", "ออกร์เร่ร่อนเดินระหว่างค่ายทั่ว Badlands ไอร้อนจากดินแห้งและลมหมุนทำตามรอยยาก ได้ยินว่าบางครั้งผ่าน Camp Boff หากหลง ลองหาแถวนั้น" },
        completion = { "41:649073630:1310104063 N 160:1393468861:1819314268", "เจ้าพร้อมตรานำข่าวดีมา {name} Dark Iron แห่ง Angor Fortress สร้าง Sign of the Earth เพื่อพันธนาการ Blacklash กับ Hematus ฝาแฝดนายกองโหดเหี้ยมของ Deathwing" },
        required = { [4640] = { "17:1138388394:1345535902", "เครื่องหมายแห่งปฐพี" } },
        steps = { { "17:1138388394:1345535902", "เครื่องหมายแห่งปฐพี" } },
    },
    [733] = { -- Scrounging
        title = { "10:1174609576:1665975056", "คุ้ยหาเศษวัสดุ" },
        objective = { "39:1413193146:1820254678", "หา Scrap Metal 7 ชิ้น ให้ Sigrun" },
        description = { "498:1260904849:1708423451", "หากหาวัสดุสร้างการป้องกันกับสิ่งจำเป็นไม่ได้ เราคงอยู่ยาก เห็นออกร์แถวนี้มีเศษโลหะมาก บางทีเรื่องเครื่องจักรปิดล้อมใน Badlands อาจไม่ไกลจริงนัก...\n\nProspector เริ่มกังวลสภาพค่ายเล็ก ข้าอยากเริ่มงานเร็ว\n\nค่ายหลักออกร์คือ Dustbelch Grotto เดินไกลไปทางตะวันตก" },
        progress = { "93:777238792:1471612041", "ใช้ของเท่าที่มีแล้ว แต่...ไม่มาก พบเสบียงเพิ่มไหม?" },
        completion = { "14:370035804:762723672 N 155:1566316294:2010540671", "เริ่มได้แล้ว {name} ต้องใช้เท่านี้จนได้ข่าว Ironforge หรือ Explorers' League\n\nถ้าหาเกลือใส่ถังชุบโลหะได้ก็คงดี..." },
        required = { [4630] = { "11:1630480235:1360527189", "เศษโลหะ" } },
        objectiveLabels = {
            item = { ["Scrap Metal"] = "เศษโลหะ" },
        },
    },
    [734] = { -- This Is Going to Be Hard
        title = { "24:435151645:256455814", "งานนี้คงยาก" },
        objective = { "45:2028361967:1838343851", "คุยกับ Lucien Tosselwrench ที่ Badlands" },
        description = { "115:1646587570:1115017839 N 44:364705123:2087812336", "วิเศษ วิเศษ\n\n<Lotwil เงยดูครู่แล้วกลับไปทำตรวน>\n\nไปคุย Lucien {name} ต้องการเฟือง #5 เอามาให้ได้ไหม?" },
        completion = { "47:96033125:1609682730", "เฟือง #5 หรือ? ใช่ ดูท่าจะไม่ดี" },
    },
    [735] = { -- The Star, the Hand and the Heart
        title = { "32:1802815763:5833607", "ดวงดาว มือ และหัวใจ" },
        objective = { "72:439728006:1453677183", "นำไอเทมที่ระบุใน Bonegrip's Note ไปให้ Gerrig Bonegrip ที่ Ironforge" },
        description = { "369:458225309:1811659326", "Yagyin's Digest หรือ? จะตั้งสาขาใหม่ของเราที่ไหนหรือ? ช่างเถอะ ไม่ใช่หน้าที่ข้าถาม\n\nข้าช่วยได้ มีสำเนาสำรอง ต้องช่วยกันใช่ไหม? เราจึงรุ่งเรือง\n\nต้องการวัตถุทรงพลังสามชิ้น นำมาแล้วจะให้หนังสือ\n\nไม่พูดชื่อ อาจมีคนฟังอยู่ ข้าจะเขียนให้" },
        progress = { "41:1630579472:135721800", "มีวัตถุที่ข้าขอหรือยัง?" },
        completion = { "21:518403239:676018686 C 102:888223868:1410609580", "เจ้าหาทางได้เก่ง {class} หากหน้าที่คือตั้งสาขาใหม่ขององค์กร ข้าเชื่อว่าจะดูแลได้ดี" },
        required = { [4646] = { "15:945278523:368554185", "ดาราแห่ง Xil'yeh" }, [4641] = { "13:2100579107:109992363", "มือของ Dagun" }, [4644] = { "16:71266212:192499610", "หัวใจแห่งมรดก" } },
