    },
    [737] = { -- Forbidden Knowledge
        title = { "19:1711698413:1133638865", "ความรู้ต้องห้าม" },
        objective = { "35:470882935:1207324180", "นำ Yagyin's Digest ไปให้ Theldurin" },
        description = { "27:924334135:434011654 N 149:286994158:1697421186", "ข้ามีหนังสือให้ {name} คงไม่ต้องบอกให้ระวัง และเก็บห่างมือที่ไม่เป็นมิตร\n\nหนังสือมีความจริงมากมาย...\n\n...และความจริงแผดเผาได้" },
        progress = { "54:1487315286:700604022", "โฮ่! หายไปนาน ได้หนังสือไหม?" },
        completion = { "61:277643691:1028336223 N 281:1897041789:339429048", "ได้แล้ว! โอ้ ความหวังริบหรี่!\n\nความพยายามเจ้าอาจช่วยเรา {name} ควรสร้างอนุสาวรีย์! สร้างศาล! ขอชื่อเจ้าถูกสรรเสริญจนหลานมีหลาน!\n\nเว้นแต่...พวกมันเป็นอิสระขึ้นพื้นผิว หากเช่นนั้น ลืมเรื่องลูกหลานได้\n\nหากพวกมันหลุด เราทั้งหมดเป็นอาหารหนอน" },
        required = { [4647] = { "15:1213949604:919928676", "บทสรุปของ Yagyin" } },
        objectiveLabels = {
            item = { ["Yagyin's Digest"] = "บทสรุปของ Yagyin" },
        },
    },
    [738] = { -- Find Agmond
        title = { "11:1926010662:412822140", "ตามหา Agmond" },
        objective = { "12:1063501370:392609661", "ตามหา Agmond" },
        description = { "353:1754230954:76975885", "Prospector Agmond เคยดูแลจุดขุดเราใน Badlands ทางตะวันตกเฉียงใต้ ที่ว่า “เคย” เพราะ...ไม่ได้ข่าวหลายสัปดาห์ ต้องให้เจ้าหา เพื่อข้าจะได้รายงาน\n\nข่าวล่าสุดเขาอยู่จุดขุดใต้สุดใน Badlands งานเล็ก ๆ เลย Angor Fortress เริ่มหาแถวนั้น" },
        completion = { "117:132995771:786388598", "โครงกระดูกนี้คงเป็นซาก Agmond ผู้โชคร้าย ร่างแตกบอบช้ำ กระดูกถูกแทะสะอาด" },
    },
    [739] = { -- Murdaloc
        title = { "8:1153776236:63926518", "Murdaloc" },
        objective = { "109:540439888:952665956", "ฆ่า Murdaloc ผู้สังหาร Agmond\n\nฆ่า Stonevault Bonesnappers 12 ตัว\n\nรายงาน Prospector Ironband ที่ Loch Modan" },
        description = { "288:632946644:1853048941", "รอย Agmond มาจากตะวันตก เลือดป้ายบนหินและทรายบอกง่ายว่าคนแคระคลานมาไกล\n\nแล้วตายที่นี่\n\nมองใกล้ พบคำว่า “Murdaloc” ขีดลวก ๆ บนหินทราย Badlands\n\nข้างมือตายของ Agmond" },
        progress = { "52:1527927099:1023041054", "มีข่าวชะตา Agmond หรือ? พบเขาไหม?" },
        completion = { "23:1758804752:482656936 N 189:1540518807:38039535", "ข่าวสะเทือนใจ {name} แต่ Agmond แขนแข็ง เหวี่ยงค้อนดุร้าย หัวก็แข็งที่สุด! แม้ถูกทร็อกบัดซบฆ่า มั่นใจว่าพามันตายไปมาก" },
        objectiveLabels = {
            monster = { ["Murdaloc slain"] = "ปราบ Murdaloc", ["Stonevault Bonesnapper slain"] = "ปราบ จอมหักกระดูก Stonevault" },
        },
    },
    [762] = { -- An Ambassador of Evil
        title = { "21:180379915:1333171650", "ทูตแห่งความชั่วร้าย" },
        objective = { "104:626547163:1192531382", "ฆ่า Ambassador Infernus ใน Angor Fortress แล้วนำหลักฐานความตายไปให้ Advisor Belgrum ที่ Ironforge" },
        description = { "332:373748445:1653497225 C 167:1368207346:68322303", "Ragnaros ส่ง Ambassador Infernus ไป Angor Fortress เอง เพื่อดูแล Shadowforge ที่หาวัตถุสาบสูญใน Uldaman\n\nคนเราเสียชีวิตมหาศาลแล้ว แต่เห็นชัดว่าแย่ลงอีก ไม่กล้าเดาว่ามันจะหาวัตถุได้เท่าไรเพื่อใช้กับ Ironforge\n\nเป้าหมายง่าย {class} กลับ Badlands ทำลายทูต เมื่อกำจัดภัยแล้ว นำหลักฐานชัยชนะให้ Advisor Belgrum\n\nอยู่ในมือเจ้าแล้ว" },
        progress = { "24:64824931:1455161403 N 43:338865473:667859231", "เวลาสำคัญ {name} Ragnaros ไม่รอให้เราเตรียมพร้อม" },
        completion = { "N 406:1634905282:546072215", "{name} ความทุ่มเทต่อ Ironforge และคนแคระเจ้าไม่มีใครปฏิเสธ ขอบใจที่ช่วย\n\nจะส่งข่าวให้ Historian Karnik ว่าสำเร็จ และส่งกำลังช่วยกู้จุดขุด Badlands เร็วที่สุด ขอบคุณอีกครั้ง\n\nก่อนจาก ข้ามีอีกเรื่องขอในพระนาม King Bronzebeard" },
        required = { [4621] = { "27:1810124023:1445447726", "ปลอกรัดแขนของทูต Infernus" } },
        steps = { { "27:1810124023:1445447726", "ปลอกรัดแขนของทูต Infernus" } },
    },
    [777] = { -- This Is Going to Be Hard
        title = { "24:435151645:256455814", "งานนี้คงยาก" },
        objective = { "32:1711520884:1944374108", "นำ Cog #5 ไปให้ Lotwil Veriatus" },
        description = { "83:1176683883:187610563", "เอาล่ะ นี่\n\nข้าจะอยู่ตรงโน้น...หลังกำบัง\n\nมาด้วยกันได้เลย" },
        progress = { "110:81225038:798508093 N 10:1409169444:946610637", "<Lotwil ไม่เงยจากตรวน ยื่นมือขยับนิ้วอย่างร้อนใจ>\n\nเฟือง {name} เฟือง!" },
        completion = { "100:1723407887:1939157082", "อา สมบูรณ์! ถอยไป ข้าจะสร้างประวัติศาสตร์อีก!\n\n<Lotwil ทำงานอย่างเอาเป็นเอาตาย>" },
        required = { [4846] = { "6:1200762390:2112344889", "เฟืองหมายเลข 5" } },
        objectiveLabels = {
            item = { ["Cog #5"] = "เฟืองหมายเลข 5" },
        },
    },
    [778] = { -- This Is Going to Be Hard
        title = { "24:435151645:256455814", "งานนี้คงยาก" },
        objective = { "103:587907239:2079343010", "ปราบ Fam'retor Guardian แล้วนำ Lotwil's Shackles of Elemental Binding คืนให้ Lotwil Veriatus" },
        description = { "164:937509051:439674685 N 92:1366757028:200701607", "ฮ่า ๆ เสร็จ! ตรวนเสร็จแล้ว!\n\nถึงเวลา Lucien! ถึงเวลา Servo!\n\nพร้อมเห็นส่วนผสมสมบูรณ์แห่งเล่นแร่แปรธาตุ วิศวกรรม และอาร์เคนไหม {name}?\n\nข้าจะเรียกธาตุทรงพลัง บุกเบิกวันสำคัญสำหรับเราทุกคน" },
        progress = { "70:87496049:656781455", "ไม่ตรงผลที่คาดนัก เอาตรวนข้าคืนได้ไหม?" },
        completion = { "11:1191658970:1224418299 N 234:1478204341:1623526203", "ขอบคุณ {name} ช่างสาหัสใช่ไหม?\n\nไม่รู้ตรงไหนผิด โชคดีมนตร์ข้าช่วยส่งมันกลับมิติต้นกำเนิด\n\nขอมอบของตอบแทนเล็กน้อยสำหรับงานหนักทั้งหมด..." },
        required = { [4847] = { "38:2123047620:1393524822", "โซ่ตรวนผนึกธาตุของ Lotwil" } },
        steps = { { "38:2123047620:1393524822", "โซ่ตรวนผนึกธาตุของ Lotwil" } },
    },
