    [782] = { -- Broken Alliances
        title = { "16:424679392:2147356808", "พันธมิตรที่แตกสลาย" },
        objective = { "70:726421121:206208247", "ฆ่า Boss Tho'grun แล้วนำ Sign of the Earth ไปให้ Gorn ที่ Kargath" },
        description = { "504:2115627974:1666987404", "จากพันธมิตร Horde กับมังกร Deathwing ในสงครามครั้งที่สอง เรารู้ว่านายกอง Blacklash กับ Hematus ถูกขังใน Lethlor Ravine ไกลตะวันออก ต้องปิดปากอดีตพันธมิตรเสื่อมทรามเพื่อคืนเกียรติ Horde!\n\nเราจ้าง Tho'grun กับออกร์รับจ้างช่วยหา Sign of the Earth กุญแจเปิดคุกเดรค แต่มันทรยศ โจมตีเราแล้วชิงไปเอง ไป Camp Boff เอาคืน!" },
        progress = { "265:1191126637:1053042974", "Tho'grun ทรยศ...แปลกหรือที่ออกร์ไม่อยู่ Horde แล้ว? ข้าจะดีใจเมื่อมันตายและได้ตราคืน\n\nหากยังไม่จัดการ อย่าเสียเวลา ไป Camp Boff ตะวันออกเฉียงใต้ Kargath" },
        completion = { "354:1461954812:865375700", "เมื่อ Tho'grun ตาย ลมทะเลทรายกับแร้งแทะศพสะอาด ออกร์จะวุ่นวาย แม้ชัยชนะเล็ก ก็พาสู่ชัยชนะใหญ่กว่า\n\nตราอยู่กับเราแล้ว เปิดคุกเดรคดำใน Lethlor ได้ เราจะปล่อยมันจากการขังไร้สิ้นสุด...ไปสู่ความตาย!" },
        required = { [4640] = { "17:1138388394:1345535902", "เครื่องหมายแห่งปฐพี" } },
        objectiveLabels = {
            item = { ["Sign of the Earth"] = "เครื่องหมายแห่งปฐพี" },
        },
    },
    [793] = { -- Broken Alliances
        title = { "16:424679392:2147356808", "พันธมิตรที่แตกสลาย" },
        objective = { "285:1949809295:1748688032", "ใช้ Sign of the Earth กระตุ้น Pillars of Diamond, Opal และ Amethyst เพื่อรับ Runestones\n\nวางศิลารูนใน Seal of the Earth เพื่อปล่อย Blacklash และ Hematus\n\nฆ่าทั้งคู่ แล้วนำ Blacklash's Bindings, Chains of Hematus และ Sign of the Earth กลับไปให้ Gorn" },
        description = { "242:1305458813:134751916 N 247:566588357:200841986", "ศิลารูนสามก้อนใน Pillars of Diamond, Opal และ Amethyst ที่ Lethlor Ravine คงผนึกไว้ ใช้ Sign of the Earth นำศิลาออกแล้วเปิด Seal of the Earth\n\nแต่ระวัง {name} เดรคดำ Blacklash กับ Hematus ประมาทไม่ได้ ฆ่าแล้วนำเครื่องพันธนาการคืนข้า\n\nไปหุบเหวต้องตะวันออกสุด Badlands ระวัง มันเป็นบ้านเดรคนับไม่ถ้วน" },
        progress = { "130:163763960:1358097773", "ศัตรูน้อยชนิดร้ายเท่ามังกร และมังกรน้อยตัวรบเดือดเท่า Blacklash กับ Hematus" },
        completion = { "218:1056815826:598583249", "ฝูงมังกรดำยังร่วมมือออร์ค Blackrock นอกรีต ต้องทำให้ทั้งสองอยู่ในระเบียบหรือกำจัด เมื่อ Blacklash กับ Hematus ตาย เราหันสนใจตะวันตกสู่ Blackrock Spire ได้" },
        required = { [4640] = { "17:1138388394:1345535902", "เครื่องหมายแห่งปฐพี" }, [4615] = { "20:518563996:1005790211", "เครื่องพันธนาการของ Blacklash" }, [4645] = { "17:1903694704:1841550863", "โซ่ของ Hematus" } },
        steps = { { "17:1138388394:1345535902", "เครื่องหมายแห่งปฐพี" }, { "20:518563996:1005790211", "เครื่องพันธนาการของ Blacklash" }, { "17:1903694704:1841550863", "โซ่ของ Hematus" } },
    },
