    [1116] = { -- Dream Dust in the Swamp
        title = { "23:679510030:1661560628", "ผงฝันในบึง" },
        objective = { "124:1724191543:1491230067", "นำ Specks of Dream Dust 10 ส่วน ไปให้ Krazek ที่ Booty Bay เก็บ Dream Dust จากลูกมังกรใน Swamp of Sorrows" },
        description = { "50:323212311:1843364767 N 355:1558678373:202564115 N 45:1274576419:1415386023", "หาข่าว Nazz คือช่วยครั้งใหญ่ {name} ใช่ ใหญ่ทีเดียว แต่เจ้ามาจาก Shimmering Flats เพื่อข่าว...ยอมเดินทางเพิ่มไหม?\n\nระหว่างข้าติดต่อแหล่งข่าว ทำไมไม่เก็บของให้ข้า?\n\nอืม อะไรดี? ผงฝันจากลูกมังกร Swamp of Sorrows ดีไหม? ใช่ อยากได้ใส่ถุงยานัตถุ์!\n\nหาให้ข้า {name} แล้วจะให้ข้อมูลที่ต้องการ" },
        progress = { "40:1784151569:587637244", "กลับเร็วจริง มีผงฝันหรือยัง?" },
        completion = { "78:1402050957:876469353 N 47:1906898118:376353681", "ดูสิ พบผงฝันแล้ว!\n\nชอบบึงไหม {name}? หาอาหารร้อน ๆ ไม่ง่ายใช่ไหม?" },
        required = { [5803] = { "19:1768332936:2025978763", "ผงฝันหนึ่งหยิบมือ" } },
        steps = { { "19:1768332936:2025978763", "ผงฝันหนึ่งหยิบมือ" } },
    },
    [1389] = { -- Draenethyst Crystals
        title = { "20:440686828:1976345191", "ผลึก Draenethyst" },
        objective = { "81:257849112:1587566101", "นำผลึก Draenethyst 6 ชิ้น ไปให้ Magtoor ที่ The Harborage ใน Swamp of Sorrows" },
        description = { "493:552304871:709510561", "พวกหลงทางใน Fallow Sanctuary ดูเหมือนเรา แต่เป็นสัตว์ร้าย...บ้าจากความยากลำบากในการมา Azeroth เคยเป็นพี่น้อง บัดนี้อยู่ Fallow Sanctuary ตะวันออก จับหรือฆ่าผู้เข้าใกล้\n\nมันขโมยสิ่งศักดิ์สิทธิ์ ผลึก draenethyst\n\nเราไม่มีกำลังเข้าไปเอาคืนจากกระท่อมกับกองไฟ แต่หากไร้ผลึก...เราอาจหลงทางเช่นกัน" },
        progress = { "25:782468459:131823666", "มีผลึกหรือยัง?" },
        completion = { "11:1191658970:1224418299 N 23:789459911:1710774359", "ขอบคุณ {name} เราเป็นหนี้เจ้า" },
        required = { [6071] = { "19:1255109859:1801924127", "ผลึก Draenethyst" } },
        steps = { { "19:1255109859:1801924127", "ผลึก Draenethyst" } },
    },
    [1392] = { -- Noboru the Cudgel
        title = { "17:1147129386:998199029", "Noboru จอมกระบอง" },
        objective = { "77:1183761627:1627531855", "นำ Noboru's Cudgel ไปให้ผู้นำ The Harborage ใน Swamp of Sorrows" },
        description = { "153:1739580427:1666391022", "Noboru คุกคามเดรไนแห่ง Harborage หลายเดือน กระบองคือสัญลักษณ์ความโหดร้ายที่พวกเขารับจากพวกหลงทาง" },
        progress = { "40:1539269653:2033891598", "สวัสดี ยินดีต้อนรับสู่ Harborage" },
        completion = { "343:1276337964:1793535483 N 1:46:46", "ได้อาวุธ Noboru น่ากลัวหรือ? เขาตายแล้วหรือ?\n\nวันยินดีของ Harborage! Noboru กับแก๊งทำเราหวาดกลัว เร่ร่อนบึง ฆ่าเดรไนที่พบ เป็นภัยตรงต่อความอยู่รอด แต่เราไม่มีกำลังสู้\n\nโชคดีที่มีมิตรเช่นเจ้า {name}" },
        required = { [6196] = { "15:405086536:1810159730", "กระบองของ Noboru" } },
        steps = { { "15:405086536:1810159730", "กระบองของ Noboru" } },
    },
    [1393] = { -- Galen's Escape
        title = { "14:1759702412:103916097", "การหลบหนีของ Galen" },
        objective = { "94:763174832:2037164929", "คุ้มกัน Galen ให้พ้นอันตราย แล้วหาค่ายของเขาใน Swamp of Sorrows เพื่อเปิดหีบนิรภัย" },
        description = { "287:1288073558:794404169", "ช่วยด้วย! สัตว์พวกนี้จะกินข้า!\n\nช่วยออกไปแล้วจะให้สมบัติใหญ่! อยู่ในค่ายบึงเหนือ Stonard แต่ขังในหีบที่เปิดได้ด้วยกลเม็ดที่ข้ารู้คนเดียว\n\nหากช่วยหนี จะสอนให้" },
        progress = { "83:2057182284:125451165", "รูกุญแจหีบนิรภัยอุดด้วยยางดำ เปิดไม่ได้" },
        completion = { "236:1268805933:2067818017", "รูกุญแจหีบนิรภัยอุดด้วยยางดำ เปิดไม่ได้\n\nแต่ Galen บอกว่ามีสลักซ่อนใต้หีบ...\n\n...ค้นครู่ก็พบ พลิกสลักแล้วหีบเปิด..." },
        objectiveLabels = {
            event = { ["Escort Galen out of the Fallow Sanctuary."] = "คุ้มกัน Galen ออกจาก Fallow Sanctuary" },
        },
    },
    [1396] = { -- Encroaching Wildlife
        title = { "20:1738538473:895927114", "สัตว์ป่ารุกล้ำ" },
        objective = { "127:1209789903:1816130414", "ฆ่า Young Sawtooth Crocolisks 8 ตัว, Sorrow Spinners 10 ตัว และ Swamp Jaguars 10 ตัว แล้วกลับไปหา Watcher Biggs ที่ Swamp of Sorrows", amount = { "5:409775429:850574908 W1 28:343912096:1065671197 W2 21:1618102929:361163389 W3 68:1087541950:918209805", "ฆ่า Young Sawtooth Crocolisks {world1} ตัว, Sorrow Spinners {world2} ตัว และ Swamp Jaguars {world3} ตัว แล้วกลับไปหา Watcher Biggs ที่ Swamp of Sorrows" } },
        description = { "294:1501233289:798304944", "กองคาราวานข้าจะไปฝั่งตะวันออก แต่ไม่ถึง พวกหลงทางบุก ฆ่ายาม ทำลายเสบียง\n\nข้ารอดคนเดียว สาบานปกป้องของเหลือ แต่สัตว์ป่าซุ่มใกล้ ช่วยป้องกันค่ายจากพวกมันเถิด!" },
        progress = { "33:1110265716:1691841167 N 35:1073178026:1292522053", "สัตว์บึงเข้าประชิด {name} ได้โปรด ป้องกันค่าย!" },
        completion = { "62:132659143:1395891114 N 35:972696627:1266191220", "เสียงสัตว์แผ่วห่างไปแล้ว ขอบคุณ {name} หวังว่าจะไม่กลับมา!" },
        objectiveLabels = {
            monster = { ["Young Sawtooth Crocolisk slain"] = "ปราบ โครโคลิสก์ฟันเลื่อยวัยอ่อน", ["Sorrow Spinner slain"] = "ปราบ แมงมุมทอใยแห่งความโศก", ["Swamp Jaguar slain"] = "ปราบ เสือจากัวร์หนองบึง" },
        },
    },
    [1398] = { -- Driftwood
        title = { "9:1185659572:2053321794", "ไม้ลอยน้ำ" },
        objective = { "78:2124447265:2142982743", "นำ Sundried Driftwood 8 ชิ้น ไปให้ Watcher Biggs ที่ Swamp of Sorrows" },
        description = { "19:1118881138:1861260865 N 265:897645686:1053803992 N 95:1627810728:2062624632", "ข้าเป็นหนี้มาก {name} เจ้ามีหัวใจเปี่ยมเกียรติ ตอนนี้ขอให้ช่วยอีกงานอย่างนอบน้อม\n\nหากจะถึง Nethergarde ต้องซ่อมเกวียน และต้องใช้ไม้ แข็งแรงแห้ง ไม่ใช่ไม้บึงชื้นพรุนพันกัน\n\n{name} ไปฝั่งตะวันออก หาไม้ลอยน้ำที่แดดตากแห้ง นำมาให้ข้า" },
        progress = { "28:1151369272:1044301392 N 1:63:63", "พบไม้ลอยน้ำไหม {name}?" },
        completion = { "42:36059609:1416753705 N 22:655070926:1459036758", "ไม้นี้เบาแต่เหนียว ขอบคุณ {name} ใช้ได้ดี" },
        required = { [6146] = { "18:1966311564:886819405", "ไม้ลอยน้ำตากแดด" } },
        steps = { { "18:1966311564:886819405", "ไม้ลอยน้ำตากแดด" } },
    },
    [1418] = { -- Neeka Bloodscar
        title = { "15:2053948579:246251624", "Neeka Bloodscar" },
        objective = { "27:1375933698:1567288437", "คุยกับ Neeka Bloodscar" },
        description = { "177:3112135:739026805 N 144:1950208644:1916405707", "Badlands โหดร้าย ใกล้ Loch Modan ที่ Alliance คุม การติดต่อ Stonard กับฐาน Kargath จึงขาดบ่อย\n\nพิสูจน์ตัว {name} ไป Badlands คุย Neeka Bloodscar หัวหน้าสอดแนม Kargath แล้วส่งรายงานนางคืนข้า" },
        completion = { "233:856098399:1204440380", "Helgrum อยากได้รายงานหรือ? ข้าส่งคนวิ่งข่าวไป Stonard ยังไม่สามวัน เขาล้มเหลวหรือ? หากยังไม่ได้รายงาน ก็คงล้มเหลว\n\nหวังว่าคนต่อไปจะเก่งหรือโชคดีกว่า" },
    },
    [1419] = { -- Coyote Thieves
        title = { "14:1251938844:703270013", "โคโยตีจอมขโมย" },
        objective = { "55:204350952:1226749126", "นำ Coyote Jawbones 30 อัน ไปให้ Neeka Bloodscar ที่ Kargath" },
        description = { "42:875502266:182033032 C 270:1313892367:1213787360 N 119:1083026983:503593680", "อยู่ Badlands มาหลายวันไหม {class}? รู้สึกไอร้อนหรือยัง? เผชิญสัตว์บนที่ราบฝุ่นหรือยัง? ถึงเวลาแล้ว\n\nCrag coyote พันธุ์แกร่ง ทั้งทนและกล้าลอบ Kargath ขโมยอาหาร ช่วยกำจัดโจรเหล่านี้!\n\nล่ามัน {name} นำขากรรไกรมา มากพอแล้วข้าอาจเชื่อเมื่อเจ้าบอกว่ารู้จัก Badlands" },
        progress = { "25:1473377446:278197347", "มีขากรรไกรหรือยัง?" },
        completion = { "38:480087346:1022631119 N 179:1717554816:1096420817", "ขากรรไกรดีมาก {name} โคโยตีพวกนี้จะไม่คุ้ยเสบียงหาเศษอีก\n\nทำได้ดี สัตว์ Badlands ไม่ใช่เหยื่อง่าย แสดงว่าเจ้าอาจรอดที่นี่" },
        required = { [6166] = { "14:1894929842:799230187", "กระดูกขากรรไกรโคโยตี" } },
        steps = { { "14:1894929842:799230187", "กระดูกขากรรไกรโคโยตี" } },
    },
    [1420] = { -- Report to Helgrum
        title = { "17:630660873:1454118573", "รายงานต่อ Helgrum" },
        objective = { "53:1979648590:208723200", "นำ Neeka's Report ไปให้ Helgrum the Swift ที่ Stonard" },
        description = { "153:1923642909:1550393987", "เขียนรายงานใหม่ให้ Helgrum ที่ Stonard แล้ว นำไปให้\n\nหากคิดว่าเป็นคนวิ่งข่าว ก็อย่าหลงทาง หรือพ่ายศัตรู" },
        progress = { "32:1970858604:1703225628", "กลับมาแล้ว มีรายงานหรือ?" },
        completion = { "11:1191658970:1224418299 N 131:1518406362:1797553547", "ขอบคุณ {name} รายงาน Neeka บอกว่า Alliance ก็มีปัญหาของตน และเราอาจมีศัตรูร่วมกัน" },
        required = { [6167] = { "14:1104536220:1039721368", "รายงานของ Neeka" } },
        steps = { { "14:1104536220:1039721368", "รายงานของ Neeka" } },
    },
    [1421] = { -- The Lost Caravan
        title = { "16:474635953:938207192", "คาราวานที่หายไป" },
        objective = { "104:2026307351:1242013540", "หา Caravan Chest ใน Fallow Sanctuary เอา Wizards' Reagents ไปให้ Watcher Biggs" },
        description = { "344:1643249101:1083250752 N 32:958979712:917477661", "ข้ามึนงงตอนพวกหลงทางบุก แต่ก่อนภาพดับ เห็นเกวียนเราถูกลากไป Fallow Sanctuary หมู่บ้านพวกมันทางเหนือ\n\nในนั้นมีหีบคาราวานบรรจุส่วนประกอบมีค่า สำคัญต่อการศึกษาพ่อมด Nethergarde Keep หาหีบเอาของคืน {name} นำมาให้ข้า" },
        progress = { "35:1869024734:1774834475 N 1:63:63", "มีส่วนประกอบพ่อมดหรือยัง {name}?" },
        completion = { "226:1979208393:729141132", "อา เจอแล้ว! เมื่อมีสิ่งนี้ พ่อมด Nethergarde ทำงานต่อได้ ไม่รู้ว่าทำอะไร แต่เกี่ยว Dark Portal ใน Blasted Lands และสำคัญต่อความปลอดภัย Alliance" },
        required = { [6170] = { "17:1765888971:1683095916", "วัตถุดิบเวทมนตร์ของเหล่าพ่อมด" } },
        steps = { { "17:1765888971:1683095916", "วัตถุดิบเวทมนตร์ของเหล่าพ่อมด" } },
    },
    [1422] = { -- Threat From the Sea
        title = { "19:1250750726:1717391113", "ภัยจากทะเล" },
        objective = { "39:448114664:1733069292", "คุยกับ Katar ที่ Swamp of Sorrows" },
        description = { "257:1652244536:1436393506", "ระหว่างเริ่มทำอาวุธ ไปคุย Katar ดีไหม? เขาต้องการช่วยลาดตระเวนหาด ข้าอยากให้ฝึกสติกับอาวุธ มากกว่าเมากับพวกเหลือขอร่วมค่าย" },
        completion = { "20:484902682:472233400 C 99:1537594025:406031593", "เงียบครู่ {class} แม้เสียงทะเลครืน ยังได้ยินเสียงกลั้วคอน่าขยะแขยงของมนุษย์ปลา" },
    },
    [1424] = { -- Pool of Tears
        title = { "13:1147745767:440423773", "สระน้ำตา" },
        objective = { "62:208288041:1078512362", "Fel'zerul ที่ Stonard ต้องการให้เจ้าเก็บ Atal'ai Artifacts 10 ชิ้น" },
        description = { "496:858066995:2093013807", "Warchief ส่งเราสืบเหตุแปลกที่ Temple of Atal'Hakkar\n\nโทรลล์ Atal'ai เป็นผู้ร่ายเวทมืด ขึ้นชื่อใช้มนตร์ต้องห้าม นึกได้ว่าตกใจเพียงใดเมื่อมาพบวิหารจมแล้ว\n\nมังกรเขียวเฝ้าที่นั่น อ้างปกป้อง Azeroth\n\nต้องรู้ว่าเกิดอะไร สำรวจรอบ Pool of Tears เก็บวัตถุ Atal'ai ข้าจะเริ่มต่อปริศนาได้" },
        progress = { "436:798363174:249777027", "ไม่มีใครรู้พิธีมืดใน Temple of Atal'Hakkar แต่รู้ว่าใช้พลังเวทยิ่งใหญ่\n\nต้องเรียนให้มากที่สุด บางทีมนตร์ Atal'ai อาจมีประโยชน์ต่อ Horde\n\nเก็บวัตถุรอบ Pool of Tears พอแล้ว ข้าจะเริ่มเข้าใจว่าโทรลล์หวังทำอะไร และอะไรผิดพลาดร้ายแรง" },
        completion = { "72:124463415:1644652811 C 1:46:46", "ความเพียรเก็บวัตถุ Atal'ai คู่ควรคำชม {class}" },
        required = { [6175] = { "16:1744988460:1222391756", "โบราณวัตถุ Atal'ai" } },
        steps = { { "16:1744988460:1222391756", "โบราณวัตถุ Atal'ai" } },
    },
    [1425] = { -- Deliver the Shipment
        title = { "20:1858478648:254610861", "ส่งสินค้า", variants = { { "26:100753379:1091945662", "ส่งสินค้าชุดแรก" } } },
        objective = { "80:809499516:1797505080", "นำ Shipment to Nethergarde ไปให้ Quartermaster Lungertz ที่ Nethergarde Keep" },
        description = { "24:478446385:942855272 N 375:559060512:1131881745 N 14:1767440677:2071721335", "ระหว่างซ่อมเกวียน {name} ข้ามีงานสุดท้าย\n\nแพ็กเสบียงสำคัญที่สุดที่รอดจากออกร์แล้ว นำไป Nethergarde Keep ป้อมอยู่บนเนินเหนือ Blasted Lands เฝ้า Dark Portal\n\nไปตามถนนตะวันออก ถึงแยกลงใต้เข้า Blasted Lands แล้วเลี้ยวซ้ายแยกถัดไป ตามถนน {name} และระวังตัว", variants = { { "24:478446385:942855272 N 381:879524936:2117916865 N 14:1767440677:2071721335", "ระหว่างที่ข้าซ่อมเกวียน {name} ข้ามีงานสุดท้ายให้เจ้า\n\nข้าบรรจุเสบียงสำคัญที่สุดที่กู้มาได้จากการโจมตีของพวก Lost Ones แล้ว นำไปที่ Nethergarde Keep ป้อมนี้อยู่บนเนินทางเหนือของ Blasted Lands คอยเฝ้า Dark Portal\n\nไปตามถนนทางตะวันออก พอถึงทางแยกให้ลงใต้เข้า Blasted Lands แล้วเลี้ยวซ้ายที่แยกถัดไป ไปตามถนนและระวังตัวด้วย {name}" } } },
        progress = { "26:948243843:583913566", "มีธุระกับข้าหรือ?" },
        completion = { "82:1001614389:408154622 N 108:110171097:733485924", "อะไร? ห่อจากคาราวาน Biggs? คิดว่าทั้งของและเขาหายแล้ว\n\nขอบคุณ {name} หากโชคดี จะมี Azoran Crystals ส่วนประกอบจำเป็น สต็อกเราใกล้หมด..." },
        required = { [6178] = { "23:550612326:1519168030", "สินค้าที่ส่งไป Nethergarde" } },
        steps = { { "23:550612326:1519168030", "สินค้าที่ส่งไป Nethergarde" } },
    },
    [1426] = { -- Threat From the Sea
        title = { "19:1250750726:1717391113", "ภัยจากทะเล" },
        objective = { "113:1940357606:230835617", "ฆ่า Marsh Murlocs 10 ตัว, Marsh Inkspewer 10 ตัว และ Marsh Flesheater 10 ตัว แล้วกลับไปหา Katar ที่ Swamp of Sorrows" },
        description = { "355:862275645:1452065852 C 82:2051910573:1099605795", "ข้าไม่รักทะเลหรือสิ่งจากส่วนลึกที่เคยเห็น นางทรงพลังแต่มืดบอด เย็นชาโหดเหี้ยม หากทำได้ ข้าคงยินดีฆ่ามนุษย์ปลาเป็นร้อย แต่ดูมันตายด้วยมือผู้ทำตาม Horde ก็พอใจบ้าง\n\nจึงมาถึงเจ้า {class} ฆ่าได้เท่าไร? จะทดสอบกับพวกทรงพลังที่สุดไหม?" },
        progress = { "293:474124985:464342361", "ข้าอดทน ยืนยาวเหมือนหิน kank เก่าจาก Draenor มนุษย์ปลาจะไม่ผ่านเขต ตราบข้ายืน หากมีทัพ จะล้างมันจากโลกนี้และทุกโลก แค่พูดความชังก็เดือดแล้ว" },
        completion = { "442:1506001817:501563893", "ทะเลกว้างไม่หยุดยั้ง แต่เจ้าย้อมนางด้วยเลือดลูกตน มนุษย์ปลารู้เจ็บ ความโง่ทำให้มันต้องรวมกำลังใหม่หลังเจ้าทำลาย ดีแล้ว\n\nให้เสียงกรีดร้องกลั้วคอกลบทะเลยาวเข้าคืน ข้าจะยิ้มทุกครั้งที่ตัวหนึ่งเงียบ\n\nอยากฆ่าเพิ่มก็กลับมา ยินดีตอบแทนอีก" },
        objectiveLabels = {
            monster = { ["Marsh Murloc slain"] = "ปราบ เมอร์ล็อกแห่งหนองบึง", ["Marsh Inkspewer slain"] = "ปราบ ตัวพ่นหมึกแห่งหนองบึง", ["Marsh Flesheater slain"] = "ปราบ ตัวกินเนื้อแห่งหนองบึง" },
        },
    },
    [1427] = { -- Threat From the Sea
        title = { "19:1250750726:1717391113", "ภัยจากทะเล" },
        objective = { "43:1076357616:1244267504", "คุยกับ Tok'Kar ที่ Swamp of Sorrows" },
        description = { "270:1859056780:2113556354", "ก่อนพัก คุย Tok'Kar อีก ระหว่างเจ้าไป เขาน่าจะทำอาวุธเสร็จบ้าง เพื่อความช่วยเหลือ เขาจะให้หนึ่งชิ้น พร้อมเมื่อไรลองกับมนุษย์ปลา...เพื่อให้ข้าพอใจยิ่งขึ้นเท่านั้น" },
        completion = { "4:1110228981:147916455 N 212:1442607959:630060552", "อา {name} กลับมา ดี ข้าทำอาวุธเพิ่มสู้เมอร์ล็อกแล้ว เพราะเจ้าหาเนื้อ sawtooth สดและทำให้ Katar ยิ้มได้เล็กน้อย จึงให้ชิ้นหนึ่ง" },
    },
    [1428] = { -- Continued Threat
        title = { "16:645845661:2058105604", "ภัยยังไม่สิ้น" },
        objective = { "115:2091365949:1724318709", "ฆ่า Marsh Inkspewers 10 ตัว, Marsh Flesheaters 10 ตัว และ Marsh Oracles 10 ตัว แล้วกลับไปหา Katar ที่ Swamp of Sorrows" },
        description = { "214:659730244:1259057534", "ดีใจที่ความชังมนุษย์ปลาเจ้าเพิ่มร่วมข้า\n\nหาพวกมันตามหาดอีก สู้เต็มที่แล้วกลับ เราค่อยคุยรางวัลความเพียร" },
        progress = { "110:1450315245:1512235828", "จนทะเลกับลูกทั้งหมดเงียบ ข้าจึงจะพอใจ...โดยเฉพาะมนุษย์ปลาน่าขยะแขยง" },
        completion = { "11:534428891:784080240 C 62:986223614:122437737", "ทำได้ดี {class} ข้าขอเลือดมันอีก ให้มนุษย์ปลาทั้งหมดสิ้นไป" },
        objectiveLabels = {
            monster = { ["Marsh Inkspewer slain"] = "ปราบ ตัวพ่นหมึกแห่งหนองบึง", ["Marsh Flesheater slain"] = "ปราบ ตัวกินเนื้อแห่งหนองบึง", ["Marsh Oracle slain"] = "ปราบ นักพยากรณ์แห่งหนองบึง" },
        },
    },
    [1429] = { -- The Atal'ai Exile
        title = { "17:827812490:1185595443", "ผู้ถูกเนรเทศแห่ง Atal'ai" },
        objective = { "78:912150205:2007641272", "นำ Bundle of Atal'ai Artifacts ไปให้ Atal'ai Exile ที่ Hinterlands" },
        description = { "491:1772348104:3461167", "ระหว่างเจ้าฝ่าอันตราย Pool of Tears หน่วยสอดแนมกลับพร้อมคัมภีร์เขียนเลือดบนเนื้อแห้ง ดูเหมือนคำพิพากษานักบวช Atal'ai\n\nเขาถูกตัดสินชะตาที่เผ่าถือว่าเลวกว่าความตาย\n\nถูกเนรเทศไปเหนือไกลใน Hinterlands อยู่กับโทรลล์ Witherbark\n\nข้าจะมัดวัตถุเหล่านี้ เจ้าไปหาผู้ถูกเนรเทศ เรียนรู้ประโยชน์แท้จริง เดินทางเสร็จแล้วกลับมา" },
        progress = { "47:1114748927:2101051986", "กล้าที่มาที่นี่ กล้าหรือโง่..." },
        completion = { "225:1424371645:672588820", "นำวัตถุเรียกอัญเชิญของ Atal'ai มาให้หรือ?\n\nเห็นว่า Jammal'an the Prophet นำสาวก Chamber of Blood สู่ชะตาที่เลือก Hakkar กลับวิหารแล้วหรือ? ชะตาสำเร็จหรือยัง?" },
        required = { [6193] = { "27:632923078:1224486164", "มัดโบราณวัตถุ Atal'ai" } },
        steps = { { "27:632923078:1224486164", "มัดโบราณวัตถุ Atal'ai" } },
    },
    [1430] = { -- Fresh Meat
        title = { "10:593329078:535299620", "เนื้อสด" },
        objective = { "63:1397900167:1556352925", "นำ Monstrous Crawler Legs 10 ขา ไปให้ Dar ที่ Swamp of Sorrows" },
        description = { "423:1655264497:1116803286", "ลูกค้าต้องการรสฉ่ำของเนื้อ crawler มาก โดยเฉพาะตัวมหึมา\n\nหากไปชายฝั่ง นำขากลับให้ข้าส่ง Orgrimmar จะตอบแทนคุ้มง่าย ๆ\n\nฝั่งอยู่ตะวันออก พบสัตว์วิ่งตามหาดและใต้ทะเลไม่ยาก" },
        progress = { "48:933363823:484305940 N 82:76572642:2051421607", "มีไวน์หนึ่งถังรอความสำเร็จ {name} ข้าชิมสินค้าก่อนส่งลูกค้าก็สมควรแล้ว" },
        completion = { "188:489324306:1190940477", "อา เหมาะที่สุด แทบรอชิมหลังย่างไฟอย่างสมบูรณ์ไม่ไหว เอาตัวอย่างติดเดินทางด้วย อร่อยจริง" },
        required = { [6184] = { "21:1077091940:159803570", "ขาปูยักษ์" } },
        steps = { { "21:1077091940:159803570", "ขาปูยักษ์" } },
    },
    [2203] = { -- Badlands Reagent Run II
        title = { "23:747096907:769171518", "เก็บส่วนประกอบ Badlands II" },
        objective = { "154:771131288:1003896515", "ใช้ empty thaumaturgy vessels กับ scorched guardian dragons ใน Badlands เมื่อเติมครบ นำไปให้ Jarkal Mossmeld ที่ Kargath" },
        description = { "34:1972849161:1564245395 C 449:2026456558:863361668", "เจ้าช่วยมาก {class} อยากตอบแทนด้วยสูตรเครื่องดื่มที่ให้ก่อน...แต่ขออีกงานอันตรายนัก ฟังก่อน\n\nกล่องนี้มีภาชนะเวทว่างสามใบ ลงออราปรับประสานเพื่อดูดเลือด scorched guardian dragon ใช้แล้วมันจะโกรธมาก ระวัง เมื่อเต็มทั้งสาม นำมาให้ข้า\n\nทำได้แล้วสูตรเป็นของเจ้า", variants = { { "34:1972849161:1564245395 C 451:2127354029:1777058599", "เจ้าช่วยข้าไว้มาก {class} ข้าอยากตอบแทนด้วยสูตรน้ำยาที่ให้เจ้าไปคราวก่อน แต่ข้ามีงานอันตรายอยากขอให้เจ้าทำ ฟังข้าก่อน\n\nในกล่องนี้มีภาชนะเวทเปล่าสามใบ แต่ละใบลงอาคมไว้ให้ดูดเลือดจาก Scorched Guardian Dragon ระวังไว้ เมื่อใช้กับมัน มันจะเดือดดาลมาก เมื่อเติมเลือดครบทั้งสามใบแล้ว นำกลับมาให้ข้า\n\nทำได้แล้วสูตรจะเป็นของเจ้า" } } },
        progress = { "225:1125117953:1559758912", "ใช้ภาชนะเก็บเลือด scorched guardian dragon หรือยัง? รู้ว่างานอันตราย...แต่สูตรยาฟื้นฟูรอความสำเร็จ ความเสี่ยงกับรางวัล สหาย...ความเสี่ยงกับรางวัล..." },
        completion = { "180:1905520245:369751532", "จากนักเล่นแร่แปรธาตุคนหนึ่งถึงอีกคน ข้าคารวะ รับสูตรไปจดจำ ขอให้มอบความสำเร็จและรางวัลเช่นที่ให้ข้ามาหลายปี" },
        required = { [7867] = { "24:580822843:1913546507", "ภาชนะบรรจุเลือดมังกร" } },
        objectiveLabels = {
            item = { ["Vessel of Dragon's Blood"] = "ภาชนะบรรจุเลือดมังกร" },
        },
    },
    [2258] = { -- Badlands Reagent Run
        title = { "20:437506276:1709535405", "เก็บส่วนประกอบ Badlands" },
        objective = { "116:199815571:349533506", "นำ Buzzard Gizzards 5 ชิ้น, Crag Coyote Fangs 10 อัน และ Rock Elemental Shards 5 ชิ้น ไปให้ Jarkal Mossmeld ที่ Kargath ใน Badlands" },
        description = { "N 481:1673765342:1976465524", "{name} ถ้าพร้อม ข้าต้องการช่วย ข้าเป็นนักเล่นแร่แปรธาตุมีชื่อ ต้องการส่วนประกอบใน Badlands\n\nเติมสต็อกด้วยกึ๋นแร้งห้าชิ้น เขี้ยว crag coyote สิบอัน และเศษธาตุหินห้าชิ้น หาได้จากสัตว์เอง หากไม่ชอบสู้ ก็หาเพื่อนที่สู้\n\nหามาแล้วได้เหรียญ จะทำไหม?" },
        progress = { "93:1041175225:527200801", "ได้ของหรือยัง? ไม่ได้ค่าจ้างจนกว่าจะนำส่วนประกอบมา" },
        completion = { "388:1569942722:940301470", "อา ทำได้ดี! อย่างน้อยคงใช้ได้พักหนึ่ง นี่ค่าจ้างตามสัญญา\n\nหากสนใจ ยังต้องการส่วนประกอบอีก แต่หาได้ลึกในจุดขุด Uldaman เท่านั้น ไม่ง่าย แต่จะตอบแทนคุ้มหากช่วยอีก\n\nอาจมากกว่าเหรียญแวววาว ใช่ไหม?" },
        required = { [7847] = { "15:1348063916:184806579", "กระเพาะบดของนก Buzzard" }, [7846] = { "16:103997381:1799228993", "เขี้ยวโคโยตีผาหิน" }, [7848] = { "20:1076783869:157258461", "เศษชิ้นส่วนของธาตุหิน" } },
        steps = { { "15:1348063916:184806579", "กระเพาะบดของนก Buzzard" }, { "16:103997381:1799228993", "เขี้ยวโคโยตีผาหิน" }, { "20:1076783869:157258461", "เศษชิ้นส่วนของธาตุหิน" } },
    },
    [2521] = { -- To Serve Kum'isha
        title = { "17:1824435120:2065874272", "รับใช้ Kum'isha" },
        objective = { "377:1588920120:82725565", "ระหว่างเดินทางทั่ว Blasted Lands หากพบ Flawless Draenethyst Sphere ให้นำกลับไป Kum'isha the Collector\n\nระวัง อัญมณีนี้เป็นหนึ่งในผลึกหายากที่สุดทั่ว Azeroth สัตว์ใดในแดนนี้ก็อาจถือไว้\n\nจะได้รับรางวัลสำหรับ Flawless Draenethyst Sphere ทุกชิ้นที่เก็บได้" },
        description = { "R 315:1837630811:1012225182 R 184:736043189:1067598493", "{race} สมองจิ๋วเจ้าเข้าใจความหายากของทรงกลม draenethyst ไร้ตำหนิไหม? เดรไนใช้ทั้งชีวิตหาเพียงหนึ่ง แล้วพบชะตาสยองโดยไม่สำเร็จ\n\nยังยืนต่อหน้า Kum'isha รู้คำขอแล้วอยากช่วยหรือ? ได้ {race}...เมื่อใดที่เดินทางแดนนี้แล้วพบ จงนำกลับ ข้าจะให้ทรัพย์ยิ่งกว่าฝันสุดไกล" },
        progress = { "84:695267050:680575639 R 1:33:33", "ข้าอุทิศชีวิตหาทรงกลม draenethyst ไร้ตำหนิ ทั้งชีวิต {race}!" },
        completion = { "122:1567018343:1822811675", "ตาฝาดหรือ? เป็นไปไม่ได้! หาได้ที่...อย่างไร...\n\nบางทีเปิดรอยแยกพาเรากลับบ้านเกิดได้แล้ว" },
        required = { [8244] = { "27:727213447:451364398", "ลูกแก้ว Draenethyst ไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Flawless Draenethyst Sphere"] = "ลูกแก้ว Draenethyst ไร้ตำหนิ" },
        },
    },
    [2522] = { -- Kum'isha's Endeavors
        title = { "20:1112748991:1396110387", "ความพยายามของ Kum'isha" },
        objective = { "72:995249153:921651139", "หา Flawless Draenethyst Sphere แล้วนำคืน Kum'isha the Collector" },
        description = { "174:146164945:1583285175 R 163:188771380:746951037", "แม้เรียกประตูมิติล้มเหลว ข้ายังหวังครั้งหน้าสำเร็จ\n\nความหวังเดรไนเร่าร้อนเท่าความโลภเครื่องประดับเจ้า {race} กลับแดนต้องสาปหาอีกลูก\n\nแน่นอน จะรับงานหรือไม่แล้วแต่เจ้าทั้งหมด *ยิ้มกว้าง*" },
        progress = { "51:280021292:786810863", "พบทรงกลม draenethyst ไร้ตำหนิอีกหรือยัง?" },
        completion = { "116:1331916375:1490434140 N 117:1506575572:1559202351", "น่าทึ่ง ข้าเคยสงสัยว่าจะหาอีกได้หรือไม่ แต่มันเต้นในมือแล้ว\n\nทำได้ดี {name}!\n\nหากพบเพิ่ม แม้ข้าคิดว่าเป็นไปไม่ได้ นำกลับมา จะตอบแทนอีก" },
        required = { [8244] = { "27:727213447:451364398", "ลูกแก้ว Draenethyst ไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Flawless Draenethyst Sphere"] = "ลูกแก้ว Draenethyst ไร้ตำหนิ" },
        },
    },
    [2581] = { -- Snickerfang Jowls
        title = { "17:1708170491:416699164", "เหนียง Snickerfang" },
        objective = { "99:2068922951:950758741", "นำ Snickerfang Jowls สามชิ้น, Blasted Boar Lungs สองชิ้น และ Scorpok Pincer หนึ่งอัน ไปให้ Bloodmage Drazial" },
        description = { "468:35774744:1943468481", "รู้กันว่าไฮยีนากรามแข็งแรง แต่กัดเหล็กทอเรียมหนาสามนิ้วขาดหรือ? เป็นไปไม่ได้ ไม่น่าเป็น แต่ข้าเห็นกับตา\n\nเข้า Blasted Lands นำเหนียง snickerfang สามชิ้น ระหว่างหา มองหมูป่ากับ scorpok ด้วย การทดสอบแรกต้องใช้ปอดหมูป่าสองชิ้นกับก้ามหนึ่งอันจึงครบ" },
        progress = { "16:742141212:2083486840 N 73:116992291:1336032925", "เจ้ากลิ่นเหม็น {name} เดินทุ่งกำมะถันมาหรือ? แล้วส่วนประกอบข้าอยู่ไหน?!" },
        completion = { "17:1857002774:1220871567 N 259:354056251:1110708197", "รู้สึกอย่างไร {name}? เจ้าเปล่งออรา snickerfang กำลังไร้มนุษย์เทียบ!\n\nเสียดายของที่นำมาทำได้เพียงหนึ่งเม็ด หากต้องการอีก ต้องส่วนประกอบเพิ่ม" },
        required = { [8391] = { "16:1460584922:314648000", "เนื้อแก้ม Snickerfang" }, [8392] = { "17:1117656504:1866058350", "ปอดหมูป่าแห่ง Blasted Lands" }, [8393] = { "14:296933197:551674223", "ก้าม Scorpok" } },
        objectiveLabels = {
            item = { ["Snickerfang Jowl"] = "เนื้อแก้ม Snickerfang", ["Blasted Boar Lung"] = "ปอดหมูป่าแห่ง Blasted Lands", ["Scorpok Pincer"] = "ก้าม Scorpok" },
        },
    },
    [2582] = { -- Rage of Ages
        title = { "12:674520557:1600940317", "โทสะข้ามยุค" },
        objective = { "99:2068922951:950758741", "นำ Snickerfang Jowls สามชิ้น, Blasted Boar Lungs สองชิ้น และ Scorpok Pincer หนึ่งอัน ไปให้ Bloodmage Drazial" },
        description = { "4:1110228981:147916455 N 385:638918751:497905682", "อา {name} กลับมา ดูเหมือนชอบพลังเสริมเข้มแข็งใช้งานได้จาก snickerfang ระวัง แม้ผลทันทีคือกำลังมหาศาล ระยะยาวอาจเป็นอันตรายต่อจิตวิญญาณและสติปัญญา\n\nยังต้องการเพิ่มหรือ? นำเหนียงสามชิ้น ปอดหมูป่าสองชิ้น และก้าม scorpok หนึ่งอันมาอีก" },
        progress = { "29:835813129:419735954", "มีอวัยวะสัตว์หรือยัง?" },
        completion = { "141:809227531:131723150", "นี่! จำไว้ ใช้แต่น้อย ต้องการอีก มาหลังใช้ของที่มีหมดแล้ว" },
        required = { [8391] = { "16:1460584922:314648000", "เนื้อแก้ม Snickerfang" }, [8392] = { "17:1117656504:1866058350", "ปอดหมูป่าแห่ง Blasted Lands" }, [8393] = { "14:296933197:551674223", "ก้าม Scorpok" } },
        objectiveLabels = {
            item = { ["Snickerfang Jowl"] = "เนื้อแก้ม Snickerfang", ["Blasted Boar Lung"] = "ปอดหมูป่าแห่ง Blasted Lands", ["Scorpok Pincer"] = "ก้าม Scorpok" },
        },
    },
    [2583] = { -- A Boar's Vitality
        title = { "17:1791459627:1050155006", "พลังชีวิตหมูป่า" },
        objective = { "97:662567410:1518429001", "นำ Blasted Boar Lungs สามชิ้น, Scorpok Pincers สองอัน และ Basilisk Brain หนึ่งชิ้น ไปให้ Bloodmage Drazial" },
        description = { "305:696997914:1443931526 N 189:1925055441:1253095789", "แดนร้างนี้มีหมูป่าสองชนิด ash-mane กับ helboar\n\nความอึดทำมันแทบไม่รับอันตราย สัตว์อื่นฆ่ายากเกินจึงไม่คุ้ม\n\nต้องวิเคราะห์เพิ่ม {name} นำปอดหมูป่าสามชิ้น ก้าม scorpok สองอัน และสมองบาซิลิสก์หนึ่งชิ้นมา ข้าจะทำยาวิเศษจากสิ่งตกค้างการทดสอบ เจ้าจะเป็นผู้ทดลองคนแรก!" },
        progress = { "22:1356322622:1715143123 N 2:8544:4386", "อวัยวะอยู่ไหน {name}!?" },
        completion = { "47:1055490019:1791955985 N 74:1934448151:1267543812", "วิญญาณหมูป่าส่องทั่วตัว {name}! สงสัยว่าเจ้าคิดว่าตนคงกระพันเหมือนสัตว์เหล่านี้หรือไม่?" },
        required = { [8392] = { "17:1117656504:1866058350", "ปอดหมูป่าแห่ง Blasted Lands" }, [8393] = { "14:296933197:551674223", "ก้าม Scorpok" }, [8394] = { "14:1774712681:572704623", "สมองบาซิลิสก์" } },
        objectiveLabels = {
            item = { ["Blasted Boar Lung"] = "ปอดหมูป่าแห่ง Blasted Lands", ["Scorpok Pincer"] = "ก้าม Scorpok", ["Basilisk Brain"] = "สมองบาซิลิสก์" },
        },
    },
    [2584] = { -- Spirit of the Boar
        title = { "18:1907621045:326708133", "วิญญาณหมูป่า" },
        objective = { "97:662567410:1518429001", "นำ Blasted Boar Lungs สามชิ้น, Scorpok Pincers สองอัน และ Basilisk Brain หนึ่งชิ้น ไปให้ Bloodmage Drazial" },
        description = { "38:32957410:1867432041 N 402:164907821:240709214", "ตอนให้ยาครั้งแรก {name} ข้ารู้ว่าใช้ครั้งสองครั้งไม่พอความอยาก แม้ตอนนี้เห็นความหิวในตา สารนี้เสพติดจนดูเหมือนใจแข็งที่สุดก็ไม่อาจต้าน\n\nก็ได้! หากต้องการน้ำปอดผสมเพิ่ม กลับแดนร้างหาปอดหมูป่าสามชิ้น ก้าม scorpok สองอัน และสมองบาซิลิสก์หนึ่งชิ้น" },
        progress = { "22:1356322622:1715143123 N 2:8544:4386", "อวัยวะอยู่ไหน {name}!?" },
        completion = { "17:1828699078:946148113 N 216:1969071887:612110755", "ข้าเตือน {name} อย่าพยายามผสมสูตรที่สร้าง สูตรที่กินล่าสุดจะมีผลเหนือมนตร์ก่อนหน้าเสมอ ทำให้สูตรอื่นไร้ผล" },
        required = { [8392] = { "17:1117656504:1866058350", "ปอดหมูป่าแห่ง Blasted Lands" }, [8393] = { "14:296933197:551674223", "ก้าม Scorpok" }, [8394] = { "14:1774712681:572704623", "สมองบาซิลิสก์" } },
        objectiveLabels = {
            item = { ["Blasted Boar Lung"] = "ปอดหมูป่าแห่ง Blasted Lands", ["Scorpok Pincer"] = "ก้าม Scorpok", ["Basilisk Brain"] = "สมองบาซิลิสก์" },
        },
    },
    [2585] = { -- The Decisive Striker
        title = { "20:1170289434:685370790", "ผู้จู่โจมเด็ดขาด" },
        objective = { "98:329435393:1542812037", "นำ Scorpok Pincers สามอัน, Vulture Gizzards สองชิ้น และ Blasted Boar Lung หนึ่งชิ้น ไปให้ Bloodmage Drazial" },
        description = { "38:1670262636:724269710 N 292:962417225:2087012226 N 168:801604654:275390648", "เคยดูมันสู้ไหม {name}? หมายถึง scorpok เคยเห็นความสง่างามคล่องแคล่ว หรือความเด็ดขาดโจมตีไหม?\n\nหากแยกความคล่องแคล่วมาบรรจุได้ เราจะร่ำรวยเกิน...หมายถึง เป็นประโยชน์ต่อวงการวิทยาศาสตร์\n\nช่วยข้า {name} แล้วจะให้ลองตัวอย่าง\n\nให้ตัวอย่างเสถียร ต้องก้าม scorpok สามอัน กึ๋นแร้งสองชิ้น และปอดหมูป่าหนึ่งชิ้น" },
        progress = { "22:1356322622:1715143123 N 2:8544:4386", "อวัยวะอยู่ไหน {name}!?" },
        completion = { "249:1107998205:1925341397", "น่าศึกษา นี่วิเคราะห์ยากที่สุด\n\nหยิบเกลือตกค้างนิดวางใต้ลิ้น น่ารู้สึกเคลิบเคลิ้มเล็กน้อย ตามด้วยความคล่องแคล่วและรวดเร็วไม่เคยมี" },
        required = { [8393] = { "14:296933197:551674223", "ก้าม Scorpok" }, [8396] = { "15:557929143:1506096109", "กึ๋นแร้ง" }, [8392] = { "17:1117656504:1866058350", "ปอดหมูป่าแห่ง Blasted Lands" } },
        objectiveLabels = {
            item = { ["Scorpok Pincer"] = "ก้าม Scorpok", ["Vulture Gizzard"] = "กึ๋นแร้ง", ["Blasted Boar Lung"] = "ปอดหมูป่าแห่ง Blasted Lands" },
        },
    },
    [2586] = { -- Salt of the Scorpok
        title = { "19:1488724104:1257853494", "เกลือ Scorpok" },
        objective = { "98:329435393:1542812037", "นำ Scorpok Pincers สามอัน, Vulture Gizzards สองชิ้น และ Blasted Boar Lung หนึ่งชิ้น ไปให้ Bloodmage Drazial" },
        description = { "101:464316485:708827867 N 147:1525017365:66934517", "เจ้ายังอยู่! ข่าวดีจริง คงกลับมาขอตัวอย่าง scorpok เพิ่ม?\n\nได้ {name} กลับแดนร้าง อย่ากลับจนเก็บก้ามสามอัน กึ๋นแร้งสองชิ้น และปอดหมูป่าหนึ่งชิ้น" },
        progress = { "22:1356322622:1715143123 N 2:8544:4386", "อวัยวะอยู่ไหน {name}!?" },
        completion = { "11:1531455831:727352998 N 190:721754978:1640158563", "ทำได้ดี {name} นี่ตัวอย่างหนึ่ง ส่วนอีกเก้าใช้วิจัย\n\nต้องการสาร scorpok บดเพิ่มเมื่อไร กลับมาค่อยตกลงกัน" },
        required = { [8392] = { "17:1117656504:1866058350", "ปอดหมูป่าแห่ง Blasted Lands" }, [8393] = { "14:296933197:551674223", "ก้าม Scorpok" }, [8396] = { "15:557929143:1506096109", "กึ๋นแร้ง" } },
        objectiveLabels = {
            item = { ["Blasted Boar Lung"] = "ปอดหมูป่าแห่ง Blasted Lands", ["Scorpok Pincer"] = "ก้าม Scorpok", ["Vulture Gizzard"] = "กึ๋นแร้ง" },
        },
    },
    [2601] = { -- The Basilisk's Bite
        title = { "19:1036716744:1503676372", "เขี้ยวบาซิลิสก์" },
        objective = { "72:1904269525:1838907804", "นำ Basilisk Brains สิบชิ้น และ Vulture Gizzards สองชิ้น ไปให้ Bloodmage Lynnore" },
        description = { "53:1004429803:1661142584 N 320:580937981:878422712 N 106:2142997427:598593699", "แดนร้างเต็มด้วย redstone basilisk {name} มันปรับตัวรุ่งเรืองยิ่งกว่าสัตว์อื่น\n\nข้าดูไกล ๆ ขณะล่าและใช้ชีวิต มีกระบวนการคิดซับซ้อนกว่ามนุษย์บางพวกด้วยซ้ำ\n\nต้องศึกษาสมอง!\n\nนำมาสิบชิ้น {name} แต่สารยังไม่ครบหากขาดกึ๋นแร้งสองชิ้นเป็นฐานสารละลาย" },
        progress = { "44:1388767783:761935256", "นำอวัยวะที่ขอมาแล้วหรือ?" },
        completion = { "18:1967955725:1033216321 N 158:469219737:1928309690", "มหัศจรรย์ {name}! ข้ามอบให้ลิ้มรสกลไกภายใน redstone basilisk\n\nหากชอบ ทำเพิ่มได้เสมอ...โดยมีราคา" },
        required = { [8394] = { "14:1774712681:572704623", "สมองบาซิลิสก์" }, [8396] = { "15:557929143:1506096109", "กึ๋นแร้ง" } },
        objectiveLabels = {
            item = { ["Basilisk Brain"] = "สมองบาซิลิสก์", ["Vulture Gizzard"] = "กึ๋นแร้ง" },
        },
    },
    [2602] = { -- Infallible Mind
        title = { "15:1993613061:80237277", "จิตไร้พลาด" },
        objective = { "72:1904269525:1838907804", "นำ Basilisk Brains สิบชิ้น และ Vulture Gizzards สองชิ้น ไปให้ Bloodmage Lynnore" },
        description = { "113:880975860:1058494641 N 115:1278559453:1900296872", "สมาธิจดจ่อหมดเร็วเพียงนี้หรือ? ต้องวิจัยเพิ่ม!\n\nใช่ ราคาเท่าเดิม {name} เข้า Blasted Lands นำสมอง redstone สิบชิ้นกับกึ๋นแร้งสองชิ้นคืนข้า" },
        progress = { "44:1388767783:761935256", "นำอวัยวะที่ขอมาแล้วหรือ?" },
        completion = { "88:1934059161:1650421583 N 17:69133703:361079177 N 112:1505044634:1112887437", "ใช่ รอครู่ สารเพิ่มจะพร้อมกิน {name}\n\nรับไป...และ {name} อย่ากินสารทดลองเหล่านี้ต่อกันรวดเร็ว ผลอาจหายนะ" },
        required = { [8394] = { "14:1774712681:572704623", "สมองบาซิลิสก์" }, [8396] = { "15:557929143:1506096109", "กึ๋นแร้ง" } },
        objectiveLabels = {
            item = { ["Basilisk Brain"] = "สมองบาซิลิสก์", ["Vulture Gizzard"] = "กึ๋นแร้ง" },
        },
    },
    [2603] = { -- Vulture's Vigor
        title = { "15:423955567:2078461263", "พลังแร้ง" },
        objective = { "74:1597260495:940156069", "นำ Vulture Gizzards สิบชิ้น และ Snickerfang Jowls สองชิ้น ไปให้ Bloodmage Lynnore" },
        description = { "53:1242921669:806122401 R 299:172692671:532526125 N 143:875708651:1489002426", "ความตายมีปีกจริงในแดนนี้ {race} ข้าเห็น black slayer กับ bonepicker กินซากนักสำรวจมาก บางครั้งซากเน่าโรคร้ายที่สุด น่าสงสัยว่าระบบภายในต้านโรคที่ครองแดนได้อย่างไร\n\nช่วยศึกษา {name}! ต้องการกึ๋น! กับเหนียง snickerfang สองชิ้นเป็นฐานสาร\n\nจะตอบแทนความพยายามสองต่อ" },
        progress = { "22:247548530:1113281944 N 83:1450711051:803750310", "อย่าเสียเวลา {name} ไม่มีอะไรคุยหากยังไม่เอาของที่ขอคืน" },
        completion = { "236:1884773037:744299720", "ยอดเยี่ยม! เริ่มทันที บางทีพบยารักษาโรคมากมายในโลก!\n\nอา รางวัล แน่นอน หากต้องการยางเคี้ยวเพิ่ม กลับมา จะให้งานอีก" },
        required = { [8391] = { "16:1460584922:314648000", "เนื้อแก้ม Snickerfang" }, [8396] = { "15:557929143:1506096109", "กึ๋นแร้ง" } },
        objectiveLabels = {
            item = { ["Snickerfang Jowl"] = "เนื้อแก้ม Snickerfang", ["Vulture Gizzard"] = "กึ๋นแร้ง" },
        },
    },
    [2604] = { -- Spiritual Domination
        title = { "20:1302401300:612179442", "จิตวิญญาณครอบงำ" },
        objective = { "74:1597260495:940156069", "นำ Vulture Gizzards สิบชิ้น และ Snickerfang Jowls สองชิ้น ไปให้ Bloodmage Lynnore" },
        description = { "198:1514289042:746456060 N 68:364021418:1183548491", "เห็นว่าไฟภายในลดแล้ว ความเคลิบเคลิ้มทางจิตอยู่ได้หนึ่งชั่วโมงหรือ?\n\nหากอยากได้ยางกึ๋นเพิ่ม ก็ต้องกึ๋นอีก กลับแดนร้าง {name} อย่ากลับจนได้กึ๋นสิบชิ้นกับเหนียงสองชิ้น" },
        progress = { "22:247548530:1113281944 N 83:1450711051:803750310", "อย่าเสียเวลา {name} ไม่มีอะไรคุยหากยังไม่เอาของที่ขอคืน" },
        completion = { "250:35302340:1359249304", "สักวันอาจแยกเอนไซม์ออกฤทธิ์จากตัวอย่าง ทำผลลัพธ์มีประสิทธิภาพกว่าได้ เสียดายตอนนี้ต้องใช้เท่าที่ผลิตได้ ต้องการยางกึ๋นเพิ่มก็กลับมา" },
        required = { [8391] = { "16:1460584922:314648000", "เนื้อแก้ม Snickerfang" }, [8396] = { "15:557929143:1506096109", "กึ๋นแร้ง" } },
        objectiveLabels = {
            item = { ["Snickerfang Jowl"] = "เนื้อแก้ม Snickerfang", ["Vulture Gizzard"] = "กึ๋นแร้ง" },
        },
    },
    [2621] = { -- The Disgraced One
        title = { "17:630698290:177072565", "ผู้สูญเสียเกียรติ" },
        objective = { "44:1272594184:1609445500", "คุยกับ Dispatch Commander Ruag ที่ Stonard" },
        description = { "476:1694644671:1124739554", "ความเสียใจ คือทั้งหมดที่เหลือ ตัดสินใจผิดครั้งเดียวก่อผลสยองหลายอย่าง หากรอคำสั่ง บางทีจะบอกภัยที่รอในแดนต้องสาป! หรือสั่งไปงานอื่น? ท้ายสุดผิดที่ข้า ทั้งหมดผิดที่ข้า\n\nจึงยืนรอคำสั่ง ต้องรู้ ต้องได้คำสั่งนั้น\n\nDispatch Commander Ruag อยู่ Stonard หาเขา ถามว่าเกิดอะไรกับคำสั่ง" },
        completion = { "211:143063272:987464080", "Thrall's Grasp...เรื่องยังสดในใจ\n\n<Commander Ruag ส่ายหน้า>\n\nเหตุร้ายกับกองนั้น Horde เสียทหารยอดเยี่ยมบางส่วนเมื่อกองพันถูกทำลาย" },
    },
    [2622] = { -- The Missing Orders
        title = { "18:1729511774:287205346", "คำสั่งที่หายไป" },
        objective = { "16:1410346529:1826995101", "คุยกับ Bengor" },
        description = { "81:1902632615:985155057 N 350:1259942717:313442854 N 70:1408957536:668995677", "คำสั่งหรือ? ต้องการทำไม?\n\nสื่ออะไร {name}? แน่นอนว่าข้าส่ง! ทหารนำคำสั่งถูกเมอร์ล็อกซุ่มตีโหดเหี้ยม รอดคนเดียว หากเรียกว่ารอดได้ แทบพูดไม่ได้ เดินไม่ได้ ต้องให้อาหารทางสาย อยากรู้ก็ถาม Bengor คงแถวนี้...และ {name} ระวังสอดจมูก อาจโดนกัดขาด" },
        completion = { "29:828367238:1883627471", "Swamp tal... talk... talker..." },
    },
    [2623] = { -- The Swamp Talker
        title = { "16:1379521474:115704081", "Swamp Talker" },
        objective = { "79:1192587725:280852811", "นำ Warchief's Orders คืนให้ Fallen Hero of the Horde" },
        description = { "249:1521467606:820020948", "ผู้บัญชาการส่งคำสั่ง เรารับ...รับคำสั่ง ไป Blasted Lands ถูกซุ่ม\n\nเมอร์ล็อก...มาก...ตัวหนึ่ง Swamp Talker แย่งจากมือขณะหอกแทงกะโหลกข้า ตะวันออก...ถ้ำ...\n\n<Bengor หมดสติ>" },
        progress = { "16:582788611:1670876302", "รอคำสั่ง" },
        completion = { "165:108670684:547724206 N 24:730348949:682722601", "เลวกว่าคิด คนข้าสิบเก้าคนอาจรอดทรมาน หากข้าไม่บุ่มบ่าม\n\nต้องช่วยพวกเขา {name}! ข้าไร้กำลังทำอะไร" },
        required = { [8463] = { "17:535623372:116236649", "คำสั่งของขุนศึก" } },
        objectiveLabels = {
            item = { ["Warchief's Orders"] = "คำสั่งของขุนศึก" },
        },
    },
    [2681] = { -- The Stones That Bind Us
        title = { "23:1849674483:629311329", "ศิลาที่พันธนาการเรา" },
        objective = { "247:112022312:803402646", "ปลดปล่อย Servants of Razelikh เก้าคน, Servants of Sevine สามคน, Servants of Allistarj สามคน และ Servants of Grol สามคน เสร็จแล้วกลับ Fallen Hero ต้องอยู่ใกล้ศิลา มิฉะนั้นขั้นตอนล้มเหลว" },
        description = { "236:1568282996:856798623 N 1:46:46", "ลำพังเจ้าไม่พอเอาชนะ Razelikh และผู้ใต้บังคับบัญชา\n\nรวบรวมกลุ่มนักผจญภัยเหมาะสม ปลดคนข้าจากทรมานนิรันดร์! ต้องทำลายศิลาสิบแปดก้อน\n\nสู้เต็มกำลัง ตายอย่างมีเกียรติ {name}" },
        progress = { "20:963132033:664288036 N 17:388857484:1044303039", "งานไม่ง่าย {name} อย่ายอมแพ้!" },
        completion = { "18:1677330748:1750015206 N 71:69222991:641917028 N 54:127872644:1473546199", "ทำได้แล้ว {name}! วิญญาณทรมานน่าสงสารพักได้ในที่สุด\n\nงานยังไม่จบ {name} มีอีกมากต้องคุยและทำ" },
        steps = { { "26:284149805:767440243", "ปลดปล่อยบริวารของ Razelikh" }, { "22:1517464286:1170172774", "ปลดปล่อยบริวารของ Grol" }, { "27:1457927340:645538202", "ปลดปล่อยบริวารของ Allistarj" }, { "24:528753252:1309903721", "ปลดปล่อยบริวารของ Sevine" } },
    },
    [2701] = { -- Heroes of Old
        title = { "13:1545442563:375875247", "วีรบุรุษกาลก่อน" },
        objective = { "37:1861355244:1072569239", "เปิดหีบแล้วรับรางวัล" },
        description = { "132:1785671507:2012771927", "รับวัตถุเก่าจากนี้เถิด เราไม่ต้องใช้แล้ว\n\nขอให้ช่วยเจ้ารบกับ Legion ได้ดี" },
        completion = { "53:1063578180:826969768", "ประกายเจิดจ้าทำเจ้ามองไม่เห็นชั่วครู่" },
    },
    [2702] = { -- Heroes of Old
        title = { "13:1545442563:375875247", "วีรบุรุษกาลก่อน" },
        objective = { "34:761191179:412434938", "คุยกับ Corporal Thund Splithoof" },
        description = { "52:96132161:1317280499 N 31:1075473615:690336022", "เจ้ามอบเกียรติแก่ข้าด้วยความสูงส่งและกล้าหาญ {name}\n\nและแก่พวกเขาด้วย..." },
        completion = { "69:111451128:1963206437", "จริง เจ้าสร้างเกียรติให้เราทั้งหมด แค่คำขอบคุณไม่พอ" },
    },
    [2721] = { -- Kirith
        title = { "6:187257653:1917096040", "Kirith" },
        objective = { "42:1546607222:1832339977", "สืบชะตาของ Lieutenant Kirith" },
        description = { "61:170052882:1939820746 N 398:1629237293:491355741", "เมื่อการผจญภัยบทหนึ่งจบ อีกบทเริ่ม {name}\n\nคนข้ายังหายหนึ่งคน อยู่สักแห่งใน Blasted Lands แน่นอน หมายถึง Lieutenant Kirith\n\nอย่างเคยบอก Allistarj ขังทรมานเราทั้งคู่ แต่ Kirith ผู้น่าสงสารใจอ่อนลง ข้าได้ยินการทดลองจากกรง เสียงกรีดร้องทรมานก้องถ้ำ นั่นคือครั้งสุดท้ายที่เห็นหรือได้ยินเขา" },
        completion = { "24:2052253182:1168735946", "Trebor หรือ? Trebor ส่งมา?" },
    },
    [2743] = { -- The Cover of Darkness
        title = { "21:2016044022:1240176046", "ใต้เงามืด" },
        objective = { "58:1633672399:750945084", "กลับไปรายงานสิ่งที่พบให้ Fallen Hero of the Horde" },
        description = { "24:1364910646:2093777973 R 469:381707458:644929568", "ไม่ต้องอ้อมค้อม {race} เวลาข้าเหลือน้อย\n\nต้องทำลายสามขั้วพลังที่ป้องกันจอมปีศาจ Razelikh ไม่ง่ายเท่าปลดวิญญาณต้องสาป\n\n<Kirith ยิ้มกว้าง>\n\nสมุนแต่ละคนสวมหนึ่งในสามชิ้นเครื่องรางที่ Razelikh สร้าง เครื่องรางเดียวกับที่ต้องใช้เรียกจอมปีศาจ\n\nกลับ Trebor บอกสิ่งที่ต้องใช้เรียก เขาจะสอนต่อได้" },
        completion = { "73:68436050:1918556516 N 1:46:46", "จอมปีศาจเจ้าเล่ห์มีแผนพอ ๆ กับโหดเหี้ยม {name}" },
    },
    [2744] = { -- The Demon Hunter
        title = { "16:200398455:1749569600", "นักล่าปีศาจ" },
        objective = { "41:742903941:1716803406", "คุยกับ Loramus Thalipedes ที่ Azshara" },
        description = { "415:2023199530:1838110335 N 86:1985791816:292937797", "Razelikh ปกป้องสามขั้วพลัง\n\nแลกการรับใช้ มันให้พลังแทบไร้ขีดจำกัดใน Blasted Lands ชิ้นเครื่องรางประสานกำลังชีวิตเจ้าของ มอบอมตะ ตราบอยู่แดนนี้ ฆ่าไม่ตาย อายุยืนถึงสิ้นกาล\n\nมีผู้หนึ่งอาจช่วยต่อ {name} ไป Azshara หา Loramus Thalipedes นักล่าปีศาจ ค้นตามเกาะ" },
        progress = { "24:898085798:1365590525", "มาทำอะไรที่นี่?" },
        completion = { "87:1543084733:438602536", "ข้าจะช่วย แม้ไม่คิดว่าเจ้าเข้าใจสิ่งที่เผชิญเต็มที่" },
        objectiveLabels = {
            event = { ["Conversation with Loramus"] = "สนทนากับ Loramus" },
        },
    },
    [2783] = { -- Petty Squabbles
        title = { "15:892444462:1253787092", "วิวาทเล็กน้อย" },
        objective = { "89:1522036128:1555923748", "คุยกับ Fallen Hero of the Horde ที่ชายแดน Blasted Lands กับบึง" },
        description = { "26:844580784:735993454 N 291:111785970:713717715 N 87:1948248858:449660280", "เรารบผิดศัตรู {name}\n\nอำนาจแท้ในแดนนี้ยังเพิ่มกำลังและจำนวน ขณะที่เราแย่งดินไหม้กับออร์ค\n\nจะรบ Horde ต่อ เพื่อวันหนึ่งถูก Burning Legion ตีแตกหรือ? ไร้ประโยชน์\n\nวางความต่าง {name} คุยวีรบุรุษ Horde ที่ล่วงลับ เขารู้ความจริงของ Blasted Lands" },
        completion = { "186:145667692:620188612", "Alliance อยากช่วยหรือ?\n\nนึกว่าจะไม่เห็นอีก วันที่ Alliance รบเคียง Horde กับศัตรูร่วม\n\nจะเป็นเช่นนั้น...เราจะรวมกัน" },
    },
