    [3501] = { -- Everything Counts In Large Amounts
        title = { "34:823344830:615242633", "มากชิ้นยิ่งมีค่า" },
        objective = { "88:1262423574:808857090", "นำ Imperfect Draenethyst Fragments ไปให้ Kum'isha จะได้รับรางวัลต่อทุกชิ้นที่ส่ง" },
        description = { "417:382321367:1640617190", "แม้อาจไม่พบทรงกลม draenethyst ไร้ตำหนิ แต่สำรวจแดนนี้ต้องพบเศษไม่สมบูรณ์หลายชนิด\n\nแม้สงสัยว่า Kum'isha ใช้เศษมีตำหนิกลับบ้านได้หรือไม่ มันอาจเป็นประโยชน์อื่นแก่เดรไน\n\nนำเศษที่พบมา จะให้รางวัล" },
        progress = { "42:556802996:261464997", "สำรวจได้ผลบ้างไหม?" },
        completion = { { "22:223142745:645848936 R 94:516390856:1920588598", "22:223142745:645848936 R 96:1947730637:778298524" }, "เจ้าทำข้าขยะแขยง {race} โตแล้วแต่ยังน้ำลายไหลใส่กองขยะ? น่าสมเพช! รับรางวัลแล้วไปให้พ้น" },
        required = { [10593] = { "30:1467747391:1347332828", "เศษผลึก Draenethyst ที่มีตำหนิ" } },
        steps = { { "30:1467747391:1347332828", "เศษผลึก Draenethyst ที่มีตำหนิ" } },
    },
    [3502] = { -- One Draenei's Junk...
        title = { "21:781341251:138167455", "ขยะของเดรไนคนหนึ่ง..." },
        objective = { "118:1023800663:1586171915", "นำ Imperfect Draenethyst Fragments ไปให้ Kum'isha สัตว์ประหลาดทุกชนิดใน Blasted Lands อาจถือเศษผลึกไว้" },
        description = { "323:864077688:1069565897", "เห็นความโลภไม่รู้พอแล้วข้าคลื่นไส้\n\nแต่จะไม่เสียเวลากับอาการติดวัตถุเจ้านาน\n\nแต่ละเศษที่ส่ง ข้าให้ขยะเพิ่ม กองข้าลด กองเจ้าเพิ่ม บน Draenor เรียกว่าได้ประโยชน์ทั้งคู่" },
        progress = { "99:1194486364:1421769388", "ว่าอย่างไร? Draenethyst จำได้ไหม?\n\n<Kum'isha กำมือเคาะหัวเจ้า>\n\nมีใครอยู่ไหม?" },
        completion = { { "22:223142745:645848936 R 193:69517900:232846818", "22:223142745:645848936 R 195:447447239:1980899267" }, "เจ้าทำข้าขยะแขยง {race} โตแล้วแต่ยังน้ำลายไหลใส่กองขยะ? น่าสมเพช! รับรางวัลแล้วไปให้พ้น\n\nคุ้นไหม? ควรคุ้น ข้าพูดพันครั้งต่อวัน\n\nโอ้ ชังโลกนี้เหลือเกิน" },
        required = { [10593] = { "30:1467747391:1347332828", "เศษผลึก Draenethyst ที่มีตำหนิ" } },
        objectiveLabels = {
            item = { ["Imperfect Draenethyst Fragment"] = "เศษผลึก Draenethyst ที่มีตำหนิ" },
        },
    },
    [3512] = { -- In Eranikus' Own Words
        title = { "22:2081548453:2036837154", "จากคำของ Eranikus เอง" },
        objective = { "85:2061481703:1351575153", "เดินทางไปตะวันออก Winterspring แล้วคุยกับ Umbranse the Spiritspeaker" },
        description = { "N 497:1191237188:1315517691", "{name} ขั้นแรกต้องหาวิธีพูดกับ Eranikus ผ่านอัญมณี ตอนนี้อยู่กึ่งหลับกึ่งตาย บิดเบี้ยวในข่ายฝันร้าย แม้แก่นที่เจ้ามอบแปดเปื้อนหนัก ยังอาจเข้าถึงได้\n\nไปแดนน้ำแข็งตะวันออก Winterspring หาพันธมิตรผู้ไม่เป็นอมตะ Umbranse the Spiritspeaker ร่างทรงมนุษย์ผู้พูดแทนคนตาย แม้ Eranikus ไม่ได้ตายจริง เขาอาจยังช่วยได้" },
        completion = { "474:145757435:701153441", "Itharius ฉลาดที่ส่งมาหาข้า แม้ไม่ได้ตายในความเข้าใจเจ้า Eranikus จะให้คำแนะนำเองในไม่ช้า แต่ตอนนี้ข้าช่วยตรง ๆ ไม่ได้...อย่างน้อยยังไม่ได้\n\nจะให้ยืมทักษะพูดกับความตาย แต่ก่อนต้องการผู้ไม่ถูกวัยชราจำกัดเช่นข้า อุปกรณ์พยากรณ์ทรงพลังที่สุดถูกชิงไป หากไม่ได้คืน เราจะช่วย Eranikus ไม่ได้" },
    },
    [3627] = { -- Uniting the Shattered Amulet
        title = { "28:1043158466:990952268", "รวมเครื่องรางที่แตกสลาย" },
        objective = { "288:1585477654:1163025051", "ฆ่า Grol the Destroyer, Lady Sevine และ Archmage Allistarj เก็บ Amulet of Grol, Amulet of Sevine และ Amulet of Allistarj จากศพ\n\nอย่าลืมใช้ Enchanted Azsharite Fel Weaponry ลดพลังทั้งสาม มิฉะนั้นฆ่าไม่ได้ แต่ต้องใช้ให้ถูกจังหวะ..." },
        description = { "188:742088331:725260622 N 62:1063008900:1947866905", "เพื่อถึง Defiler ต้องทำลายสามขั้วพลังและนำชิ้นเครื่องรางคืน ได้ครบสามแล้วกลับ ข้าจะสอนต่อ\n\nไป {name}! สู่ Blasted Lands! Sevine, Allistarj และ Grol ต้องล้ม!" },
        progress = { "58:847685675:513272888", "สามจะรวมเป็นหนึ่ง หนึ่งจะส่องทาง" },
        completion = { "140:1906760316:595551798", "เครื่องราง Razelikh the Defiler สมบูรณ์อีกครั้ง แต่เขารู้ว่าการบังคับบัญชาถูกรบกวน รู้ว่าเจ้ากำลังมา..." },
        required = { [10755] = { "19:1696487767:148639249", "เครื่องรางของอัลลิสทาร์จ" }, [10753] = { "14:838861103:408513146", "เครื่องรางของกรอล" }, [10754] = { "16:2121163307:687113348", "เครื่องรางของเซวีน" } },
        objectiveLabels = {
            item = { ["Amulet of Allistarj"] = "เครื่องรางของอัลลิสทาร์จ", ["Amulet of Grol"] = "เครื่องรางของกรอล", ["Amulet of Sevine"] = "เครื่องรางของเซวีน" },
        },
    },
    [3628] = { -- You Are Rakh'likh, Demon
        title = { "24:1309489553:265625745", "เจ้าคือ Rakh'likh เจ้าปีศาจ" },
        objective = { "251:137554854:910744910", "ทำลาย Razelikh the Defiler แล้วนำ Severed Horn of the Defiler คืนให้ Fallen Hero of the Horde ต้องคืน Ward of the Defiler ด้วย เพื่อให้เขาทำลาย ป้องกันตกในมือผู้ไม่หวังดีอีก" },
        description = { "302:1696945535:1222706784 N 195:2120834438:1237855097", "รัง Razelikh อยู่ยอดเขาสูงที่สุด Blasted Lands ไปได้ทางเดียวคือรูนเคลื่อนย้ายใกล้ภูเขา ตราบถือเครื่องราง เจ้าขึ้นรังได้เสรี ถึงแล้วต้องเรียกสัตว์ร้าย เครื่องรางคือกุญแจ {name} ใช้ที่ Altar of the Defiler\n\nหากชนะ เอาเขากลับ มันจะเป็นสัญลักษณ์หวังแก่ทุกคน หลักฐานว่าวีรบุรุษยังมีในโลกสงครามนี้" },
        progress = { "30:56738601:1862179272", "ไม่เหลืออะไรให้กลัวแล้ว" },
        completion = { "118:1129164783:840558293", "วันนี้จะถูกจดจำชั่วนิรันดร์ จอมปีศาจผู้ครอง Blasted Lands ล่มแล้วในที่สุด!" },
        required = { [10759] = { "27:1454783019:562172978", "เขาที่ถูกตัดของผู้แปดเปื้อน" } },
        objectiveLabels = {
            item = { ["Severed Horn of the Defiler"] = "เขาที่ถูกตัดของผู้แปดเปื้อน" },
        },
    },
    [3821] = { -- Dreadmaul Rock
        title = { "14:1939946337:864837650", "Dreadmaul Rock" },
        objective = { "82:537316447:1436041154", "เดินทางไป Burning Steppes สืบชะตาของ Sha'ni Proudtusk" },
        description = { "338:1934169504:942051612 N 90:1198400346:1374898396", "Sha'ni ถูกส่งสืบพิธีแปลกของออกร์ Firegut ใน Burning Steppes กว่าสามสัปดาห์ก่อน\n\nGoretooth ไม่ได้ข่าวใครในหมวด บอกให้ข้าเดินหน้าทำหน้าที่ปัจจุบัน เชื่อไหม? นั่นภรรยาข้า!\n\nข้าทิ้งตำแหน่งไม่ได้ {name} แต่ต้องรู้ว่า Sha'ni เป็นอย่างไร ไปหาใน Burning Steppes" },
        completion = { "148:1052017467:379438337", "Thal'trak ผู้น่าสงสาร\n\nเราวางแผนย้ายไปอยู่กับพ่อแม่ข้าที่ Hinterlands เมื่อจบประจำการ ตอนนี้แผนพังแล้ว!" },
    },
    [93176] = { -- My Little Friends
        title = { "17:485034629:1030894637", "เพื่อนตัวน้อยของข้า" },
        objective = { "132:484382333:886152998", "ใช้ไอเทมใน Entomology Starter Kit หาและจับ Arbor Tarantula, Hay Weevil Specimen และ Flesh Picker" },
        description = { "367:1281381763:699490794", "ชื่นชมสัตว์น้อยที่เลี้ยงหรือ? นี่ผลงานตลอดชีวิตหลังความตาย ข้าใช้เวลานับไม่ถ้วนศึกษาร่างกาย อาหาร แม้พิธีเข้าสังคม\n\nอยากร่วมงานอดิเรกไหม? รับห่อนี้ บันทึกกับวัสดุจะช่วยเริ่ม หากทำหาย ต้องซื้อใหม่จากข้าราคาเล็กน้อย" },
        required = { [213566] = { "24:2032330860:795737288", "ตัวอย่างแมงมุมทารันทูลาต้นไม้" }, [213568] = { "19:320287496:1672441753", "ตัวอย่างด้วงงวงหญ้าแห้ง" }, [213567] = { "21:1436648494:396713184", "ตัวอย่างแมลง Flesh Picker" } },
        steps = { { "24:2032330860:795737288", "ตัวอย่างแมงมุมทารันทูลาต้นไม้" }, { "19:320287496:1672441753", "ตัวอย่างด้วงงวงหญ้าแห้ง" }, { "21:1436648494:396713184", "ตัวอย่างแมลง Flesh Picker" } },
    },
    [93429] = { -- Blood of My Blood
        title = { "17:2085069890:812853747", "เลือดเนื้อเชื้อไข" },
        objective = { "42:800996505:866744446", "ฆ่า Lost Ones 10 คน ใน Fallow Sanctuary" },
        description = { "394:1255664927:1083667264", "แม้เป็นญาติ พวกหลงทาง Fallow Sanctuary กลับเป็นสิ่งมีชีวิตแห่งความรุนแรงและเกลียดชังล้วน\n\nไม่มีการไถ่กู้หรือช่วยรอด ต้องเดินบึงไร้สติเกลียดชังตลอดชีวิต\n\nความทุกข์ต้องจบ ใครต้องปลดจากทุกข์ งานน่ากลัว ข้ารู้ แต่จะทำเพื่อปกป้องผู้เหลือได้ไหม?" },
        completion = { "90:588241497:1118116039", "ขอบใจที่ช่วยให้ The Harborage ปลอดภัย และช่วยให้มือของเราไม่ต้องเปื้อนเลือดญาติพี่น้อง" },
        objectiveLabels = {
            monster = { ["Lost One slain"] = "ปราบ ผู้หลงทาง" },
        },
    },
    [93430] = { -- Taking the Bait Back
        title = { "20:1366221490:558964741", "ชิงเหยื่อตกปลาคืน" },
        objective = { "70:2091680210:1520688995", "หา Lost One Fisherman ที่ขโมยเหยื่อตกปลาของ Pelluk แล้วนำคืน" },
        description = { "463:1984472319:1845017732 R 1:33:33", "คราวนี้มากเกิน! แค่รับมือพวกชั่วก็พอแล้ว ยังขโมยเหยื่อนำโชคข้า!\n\nเช้านี้ตกปลา ตัวหนึ่งขึ้นจากโคลน ตัดสายแล้วหนี โจรคงเป็นชาวประมงพวกหลงทาง หวังใช้เอง\n\nเสบียงปลาเราขึ้นกับเหยื่อนี้ ต้องได้คืน พวกมันตกปลาริมน้ำตะวันออก หาโจร {race}!" },
        completion = { "31:1639958185:939575858 R 59:872749061:351972833", "อันนี้แหละ! โอ้ ขอบใจนะ {race} ไว้แวะมาอีก ข้าจะแบ่งปลาที่จับได้ให้เจ้า!" },
        progress = { "73:294601146:1635060229", "ถ้าไม่มีเหยื่อนำโชค ข้าจับอะไรไม่ได้เลย! เราอาจอดตายอยู่ที่นี่ก็ได้" },
        required = { [258530] = { "10:1745998973:2009022045", "เหยื่อตกปลานำโชค" } },
        steps = { { "10:1745998973:2009022045", "เหยื่อตกปลานำโชค" } },
    },
    [93464] = { -- The Visiting Mage
        title = { "17:2006422566:273545750", "จอมเวทผู้มาเยือน" },
        objective = { "67:152127405:1015387951", "หาจอมเวทใน Desolace ผู้รู้พลัง draenethyst" },
        description = { "29:1523972942:1064502297 N 416:702936811:1161627248 R 48:1285919019:1289834692", "ขอยอมรับ {name} แม้ draenethyst ศักดิ์สิทธิ์และรักษาสติเรา ไม่มีใครที่นี่เข้าใจทั้งหมด\n\nจำได้ว่าจอมเวทมนุษย์ชื่อ Azore จาก Desolace เคยมา Harborage เขากลัวพลังผลึก บอกไม่ควรตกมือผิดคน\n\nตอนนั้นเราขับไล่เพื่อปกป้องของเรา แต่ระยะนี้ข้าสงสัยว่าเขารู้อะไรกันแน่\n\nขอให้หา {race} ความรู้เขาอาจล้ำค่าต่อเรา" },
        completion = { "66:803556708:1292646210", "Draenethyst อย่างนั้นหรือ? ใช่ ข้าพอรู้เรื่องนี้อยู่บ้าง..." },
    },
    [93585] = { -- This Light of Mine
        title = { "18:1758623458:1348137476", "แสงของข้า" },
        objective = { "38:1838519263:1003097366", "คุ้มกัน Father Tuttle ไป The Harborage" },
        description = { "472:1793456687:337714045 C 1:63:63", "โอ้ ขอบคุณสวรรค์ คนมีอารยธรรม!\n\nข้ามาแทน Church of the Holy Light เพื่อติดต่อเดรไน Harborage Alliance ไม่มีที่มั่นที่นี่ การทูตกับท้องถิ่นอาจช่วย แสงสว่างต้อนรับทุกคนสู่อ้อมกอดอยู่แล้ว!\n\nแต่ถนนเลยสะพานมีญาติดุร้ายของเดรไนเต็มไปหมด ต้องมีคนป้องกันจึงจะถึงปลอดภัย ช่วยไหม {class}?" },
        completion = { "409:1995559022:1151723039", "มนุษย์ที่มากับเจ้าเป็นคนเขลา เขาคิดว่าเราแยกจากแสงศักดิ์สิทธิ์เพราะความไม่รู้ แต่ความจริงเราถูกพรากจากแสงอย่างโหดร้าย คนที่เจ้าเห็นที่นี่คือผู้รอดชีวิตทั้งหมด ข้าจะไม่ยอมให้คนเช่นนั้นมาดูหมิ่นประวัติศาสตร์ของชาวเดรไน\n\nเจ้าไม่แสดงความหยิ่งผยองอย่างนักบวชคนนั้น ข้าจึงไม่มีเหตุให้ขับไล่เจ้าเหมือนเขา ตราบใดที่เจ้าให้เกียรติสถานที่แห่งนี้ เจ้าก็อยู่ต่อได้" },
        objectiveLabels = {
            event = { ["Escort Father Tuttle to The Harborage"] = "คุ้มกัน Father Tuttle ไปยัง The Harborage" },
        },
    },
    [93663] = { -- Lost in Transit
        title = { "15:748773321:578490523", "หายระหว่างขนส่ง" },
        objective = { "82:1960961396:622143610", "หาคนส่งสารที่หายไป และให้แน่ใจว่าสินค้าของ Dar ส่งถึง Harborage" },
        description = { "499:181100512:1476583908", "เดรไน Harborage ตกปลาเก่ง กล้าลากอวนในน้ำอันตรายกว่าข้า บางครั้งค้าขายกัน พวกเขาแบ่งปลา ข้าให้เสบียงส่วนเกิน\n\nส่งก็อบลินนำสินค้างวดล่าสุดไป แต่ไม่กลับ ครอโคลิสก์คงกินแล้ว\n\nสำคัญกว่าคือชื่อเสียงธุรกิจข้า ต้องหาสินค้าให้พบแล้วส่ง Harborage ช่วยหา ตรวจใกล้น้ำตามถนน" },
        completion = { "111:1884487787:436784854 R 47:1909496914:705610038", "<Magtoor เปิดกล่องแล้วตรวจดูของข้างใน>\nมาถึงช้าไปหน่อย แต่ของอยู่ครบตามที่ควรจะเป็น ขอบใจเจ้า {race} เจอ Dar คราวหน้าฝากทักทายเขาด้วย" },
        progress = { "60:1990015664:176014903", "เจ้าเอาของจาก Stonard มาส่งหรือ? เอามาให้ข้าดูหน่อยสิ" },
        required = { [260452] = { "18:745048029:2120604278", "สินค้าที่คนส่งของนำมา" } },
        steps = { { "18:745048029:2120604278", "สินค้าที่คนส่งของนำมา" } },
    },
    [736] = { -- The Star, the Hand and the Heart
        title = { "32:1802815763:5833607", "ดวงดาว มือ และหัวใจ" },
        objective = { "73:1529575900:932308502", "นำไอเทมที่ระบุใน Bel'dugur's Note ไปให้ Keeper Bel'dugur ที่ Undercity" },
        description = { { "419:2045690773:473569748", "418:861192598:488813281" }, "ต้องการ Yagyin's Digest หรือ? แผนคือรวบรวมผู้ติดตามกลุ่มใหม่? แน่นอน...ข้าจะช่วย สหายร่วมอุดมการณ์\n\nแต่ต้องช่วยข้าด้วย\n\nต้องการวัตถุทรงพลังสามชิ้น นำมาแล้วหนังสือเป็นของเจ้า\n\nเอ่ยชื่อไม่ได้ แต่จะเขียน\n\nเอาของในรายการมาได้ จึงคู่ควรตั้งสาขาตนในองค์กรเรา" },
        progress = { "23:283455491:1828648899 C 1:46:46", "ภารกิจเป็นอย่างไร {class}?" },
        completion = { "123:1004573673:1634181923", "ประทับใจ! ต้องมีฝีมือหรือโชคมากจึงได้วัตถุเหล่านี้ ไม่ว่าอย่างไร เจ้ามีคุณค่าต่อเรา" },
        required = { [4641] = { "13:2100579107:109992363", "มือของ Dagun" }, [4644] = { "16:71266212:192499610", "หัวใจแห่งมรดก" }, [4646] = { "15:945278523:368554185", "ดาราแห่ง Xil'yeh" } },
        objectiveLabels = {
            item = { ["Hand of Dagun"] = "มือของ Dagun", ["The Legacy Heart"] = "หัวใจแห่งมรดก", ["Star of Xil'yeh"] = "ดาราแห่ง Xil'yeh" },
        },
    },
    [1444] = { -- Return to Fel'Zerul
        title = { "19:1384464686:616753942", "กลับไปหา Fel'Zerul" },
        objective = { "31:636213453:2077073749", "กลับไปหา Fel'Zerul ที่ Stonard" },
        description = { "480:429593400:430180815", "Jammal'an the Prophet ตัดสินเนรเทศข้าจาก Temple of Atal'Hakkar ครั้งหนึ่งข้าคิดว่ามหาปุโรหิตคู่ควรนำ\n\nศรัทธาแข็งกร้าวในคำพยากรณ์จะทำลาย Atal'ai หากยังไม่เกิดแล้ว\n\nเมื่อแสดงความกังวล ข้าถูกเรียกคนนอกศรัทธาและขับจากวิหาร\n\nวัตถุที่นำมาไม่มีอันตราย แต่หาก Jammal'an พบมนตร์เครื่องรางที่ถูกสำหรับพิธีเรียก โลกจะเสี่ยงใหญ่หลวง..." },
        completion = { "44:1123722089:1372762753 C 109:1526632481:762214476", "ไม่ได้คุยกันนาน {class} หวังว่าเดินทางสำเร็จ\n\nได้ความรู้อะไรจาก Atal'ai ผู้ถูกเนรเทศใน Hinterlands?" },
    },
    [2500] = { -- Badlands Reagent Run
        title = { "20:437506276:1709535405", "เก็บส่วนประกอบ Badlands" },
        objective = { "93:1191603573:1111888576", "เก็บส่วนผสมจาก Badlands ที่ Ghak Healtouch ต้องการ แล้วกลับไปหาเขาใน Thelsamar" },
        description = { "C 476:1795107970:880108230", "{class} ข้าต้องการใช้บริการ เป็นนักเล่นแร่แปรธาตุมีชื่อบ้าง อยากให้ช่วยหาส่วนผสมใน Badlands\n\nต้องเติมคลังด้วยกึ๋นแร้งห้าชิ้น เขี้ยว Crag Coyote สิบชิ้น และเศษ Rock Elemental ห้าชิ้น หาได้จากตัวสัตว์ หากไม่ถนัดสู้ หาสหายที่ถนัด\n\nเก็บมาแล้วจะได้เหรียญ\n\nว่าอย่างไร?" },
        progress = { "93:1041175225:527200801", "ได้ของหรือยัง? ไม่ได้ค่าจ้างจนกว่าจะนำส่วนประกอบมา" },
        completion = { "14:1953039402:1129575126 N 375:1003840883:1278071908", "อา ทำได้ดี {name} คงพอใช้สักพัก นี่ค่าตอบแทนตามสัญญา\n\nหากสนใจ ยังต้องการส่วนผสมเพิ่ม แต่พบเฉพาะส่วนลึกจุดขุด Uldaman หาไม่ง่าย แต่จะตอบแทนคุ้มถ้าช่วยอีก\n\nบางทีมากกว่าเหรียญวาว ๆ ใช่ไหม?" },
        required = { [7847] = { "15:1348063916:184806579", "กระเพาะบดของนก Buzzard" }, [7846] = { "16:103997381:1799228993", "เขี้ยวโคโยตีผาหิน" }, [7848] = { "20:1076783869:157258461", "เศษชิ้นส่วนของธาตุหิน" } },
        steps = { { "15:1348063916:184806579", "กระเพาะบดของนก Buzzard" }, { "16:103997381:1799228993", "เขี้ยวโคโยตีผาหิน" }, { "20:1076783869:157258461", "เศษชิ้นส่วนของธาตุหิน" } },
    },
    [2501] = { -- Badlands Reagent Run II
        title = { "23:747096907:769171518", "เก็บส่วนประกอบ Badlands II" },
        objective = { "155:1768115506:320355443", "ใช้ Empty Thaumaturgy Vessels กับ Scorched Guardian dragons ใน Badlands เมื่อเต็มแล้วนำไปให้ Ghak Healtouch ใน Thelsamar" },
        description = { "34:1972849161:1564245395 N 439:127444141:1666704180", "เจ้าช่วยมาก {name} อยากตอบแทนด้วยสูตรน้ำยาที่ให้ก่อนหน้า แต่ต้องขอช่วยงานอันตราย\n\nกล่องนี้มี Empty Thaumaturgy Vessels สามใบ มีพลังปรับจูนดูดเลือด Scorched Guardian dragon ใช้แล้วมันจะโกรธมาก ระวัง เมื่อทั้งสามเต็มนำมา\n\nทำสำเร็จ สูตรเป็นของเจ้า", variants = { { "34:1972849161:1564245395 N 441:2021929296:810489607", "เจ้าช่วยข้าไว้มาก {name} ข้าอยากตอบแทนด้วยสูตรปรุงน้ำยาที่ให้เจ้าก่อนหน้านี้ แต่ข้าต้องขอให้เจ้าช่วยงานที่ค่อนข้างอันตราย\n\nกล่องที่ล็อกอยู่นี้มี Empty Thaumaturgy Vessels สามใบ แต่ละใบลงอาคมไว้ให้ดูดเลือดจากมังกร Scorched Guardian ได้ ใช้กับมันแล้วมันจะโกรธมาก ระวังด้วย เมื่อเติมเลือดจนครบทั้งสามใบแล้วให้นำกลับมา\n\nทำสำเร็จแล้วสูตรจะเป็นของเจ้า" } } },
        progress = { "225:1125117953:1559758912", "ใช้ภาชนะเก็บเลือด scorched guardian dragon หรือยัง? รู้ว่างานอันตราย...แต่สูตรยาฟื้นฟูรอความสำเร็จ ความเสี่ยงกับรางวัล สหาย...ความเสี่ยงกับรางวัล..." },
        completion = { "180:1905520232:369751519", "ในฐานะนักเล่นแร่แปรธาตุด้วยกัน ข้าคารวะ รับสูตรนี้ไปเรียน ขอให้นำความสำเร็จและผลตอบแทนเหมือนที่ข้าได้มาหลายปี!" },
        required = { [7867] = { "24:580822843:1913546507", "ภาชนะบรรจุเลือดมังกร" } },
        steps = { { "24:580822843:1913546507", "ภาชนะบรรจุเลือดมังกร" } },
    },
    [77] = { -- A Sticky Situation
        title = { "18:1720059154:1294444448", "สถานการณ์เหนียวหนืด" },
        objective = { "117:1953686851:1472223349", "นำ Hinterlands Honey Ripple 10 ขวด คืนจากลังรอบฐาน Horde ร้างใน Skulk Rock" },
        description = { "496:2119580686:1469662713", "ข้ามีบรรจุภัณฑ์เดิมสำหรับเหล้า ripple ที่ Dran Droffers ต้องการ จะช่วยแพ็กให้พ่อปากร้ายของ Malton...แลกเหล้าเพิ่มสองขวด อยู่ในลังที่ฐาน Horde ร้างใกล้ Skulk Rock\n\nงานหนักทีเดียว สไลม์กับโคลนเหนียวเกาะซาก ลือว่ามีหัวหน้าโคลนบางชนิดนำ แต่ไม่ว่าอย่างไร เอาเหล้ากลับมาที่นี่ให้แพ็ก" },
        progress = { "122:1449746636:47214983", "ข้าเชื่อว่ามาค่ายเราเพื่อส่งขวด ripple ที่จำเป็นต่องาน ใช่ไหม?" },
        completion = { "17:1994980209:97912681 N 446:115090887:1349320905", "ทำได้ดี {name} ดีที่คิดล่วงหน้าไม่กระทบรสละเอียด ไม่มีอะไรแย่กว่ากลิ่นเหล้าที่ถูกเขย่าไร้เหตุ\n\nรอมนตร์ทำงานกับสินค้าล้ำค่าครู่ จริง ๆ ไม่มีมนตร์ ข้าแค่มีกล่องเปล่า Hinterlands Honey Ripple กลลวงจะเปลี่ยนขวดเหล่านี้เป็นสมบัติสุราเหนือกาล\n\nเดินหน้า เพื่อเหล้าชั้นยอด!" },
        required = { [8684] = { "24:984479930:1391533073", "ฮันนีริปเปิลแห่ง Hinterlands" } },
        objectiveLabels = {
            item = { ["Hinterlands Honey Ripple"] = "ฮันนีริปเปิลแห่ง Hinterlands" },
        },
    },
    [836] = { -- Rescue OOX-09/HL!
        title = { "17:1333605780:186947884", "ช่วย OOX-09/HL!" },
        objective = { "106:305654114:2084839619", "คุ้มกัน OOX-09/HL ไปชายฝั่งเลย Overlook Cliff แล้วรายงาน Oglethorpe Obnoticus ที่ Booty Bay" },
        description = { "497:707656013:2072965971", "เสียงโนมแตกพร่าจากหุ่นอีก\n\n“ต้องย้าย OOX-09/HL ไปที่โล่งปลอดภัยเพื่อเริ่มขั้นบินขึ้นยาวนาน มีระบบพรางตัว แต่ข้าต้องใช้เวลาทำให้กลับทำงาน คุ้มกันจากจุดนี้ไป...ชายฝั่งเลย Overlook Cliff! เหมาะที่สุดและนานพอให้ระบบพร้อม!”\n\n“พาถึงฝั่งปลอดภัย แล้วมาคุยที่ Booty Bay! Oglethorpe Obnoticus จบการติดต่อ!”" },
        completion = { "374:946800183:1167044372 N 35:1508532347:1119755817", "อ้อ เจ้าคือผู้ช่วย OOX-09/HL! ขอบคุณเท่าไรก็ไม่พอ! หุ่นกลับฐานยังต้องพัฒนา แต่เจ้าช่วยประหยัดเวลาสร้างใหม่นับไม่ถ้วนและทองค่าผลิตมากมาย\n\nเลือกของเหล่านี้ได้เลย ขอบคุณอีกครั้ง {name} ข้ากับหุ่นเป็นหนี้บุญคุณ!" },
    },
    [1133] = { -- Journey to Astranaar
        title = { "20:1480962652:1790637363", "เดินทางสู่ Astranaar" },
        objective = { "44:1675618816:565068788", "คุยกับ Shindrell Swiftfire ที่ Astranaar" },
        description = { "311:347732633:1379120659", "หากเพิ่งลงเรือจาก Menethil สิ่งแรกคือ...ไป Astranaar สมาชิก Alliance กระตือรือร้นเช่นเจ้าคงช่วยได้มาก คุย Shindrell Swiftfire อาสารับใช้\n\nแต่ไม่ต้องบอกว่าใครส่ง นางไม่รู้จักข้า..." },
        completion = { "53:1583658806:195755845 N 112:1355716482:1505261993", "มาช่วย Alliance หรือ {name}? เรายินดีรับ แม้ Ashenvale ยังงาม...ก็ไม่สงบเช่นก่อนแล้ว" },
    },
    [1135] = { -- Highperch Venom
        title = { "15:1475458106:324410138", "พิษ Highperch" },
        objective = { "61:74043334:100648422", "นำ Highperch Venom Sacs 10 ถุง ไปให้ Fiora Longears ที่ Theramore" },
        description = { "411:641237598:543342002", "อาจรู้ว่าออร์คมักฝึกไวเวิร์นเป็นพาหนะ แต่ที่รู้กันน้อยคือบางวงการพิษมีค่ากว่าสัตว์เอง หากไม่กลัวล่าไวเวิร์น...ข้ามีงาน\n\nมี Highperch ใน Thousand Needles ทางตะวันตก ไวเวิร์นที่นั่นพิษแรง ทั้งแรงและมีค่า" },
        progress = { "24:1149635654:431533979 N 34:41633244:1508600078", "พบ Highperch ไหม {name}? ล่าไวเวิร์นได้ผลหรือ?" },
        completion = { "50:965350603:1916422937 N 132:683583154:806209153", "อา ส่วนใหญ่พิษเกือบล้น {name} ปกติเก็บได้จากตัวอ่อนหรือตัวเมียที่ให้ลูกได้ คงสังหารหนักที่ Highperch!" },
        required = { [5809] = { "19:326769821:865515621", "ถุงพิษจาก Highperch" } },
        steps = { { "19:326769821:865515621", "ถุงพิษจาก Highperch" } },
    },
    [1166] = { -- Overlord Mok'Morokk's Concern
        title = { "29:574324104:788650204", "เรื่องกังวลของ Overlord Mok'Morokk" },
        objective = { "115:1109448152:1166868005", "Overlord Mok'Morokk ที่ Brackenwall Village ต้องการเหล้า ยานัตถุ์ และหีบนิรภัยของเขาคืนจาก Dustwallow Swamp" },
        description = { "249:2019205563:1121923334 R 182:2062254264:946061099", "คำนับ Overlord Mok'Morokk!\n\nRexxar ตั้งข้าเป็นผู้นำ Stonemaul ผู้ยิ่งใหญ่!\n\nข้านำดี ข้าคุ้มเผ่า\n\nมังกรใหญ่พ่นไฟบ้านเก่า ข้าฉลาด หาบ้านใหม่ให้เผ่าที่นี่\n\nหนีเร็ว ลืมของ {race} ตัวน้อย ไปเอาของข้า ลงใต้หาเหล้าอร่อย ยานัตถุ์ และหีบ ทำแล้วข้าชอบเจ้า หาใน Den of Flame กับ Stonemaul Ruins...อยู่แน่ ข้ามั่นใจ!" },
        progress = { "156:1141385315:1391676299", "ข้าหิวเหล้า คิดถึงยานัตถุ์ด้วย หีบอยู่ไหน? ไปเอาให้ Overlord Mok'Morokk\n\nหาที่บ้านเก่าทางใต้ ข้ายุ่งนำออกร์ ไม่มีเวลา" },
        completion = { "9:1004052415:788799545 R 44:624554673:983836205", "เจ้าเป็น {race} ดี ข้าคิดถึงของมาก ตอนนี้ข้าชอบเจ้า" },
        required = { [5834] = { "18:1208146044:1478565982", "ยานัตถุ์ของ Mok'Morokk" }, [5835] = { "17:1831768598:1672857024", "เหล้าของ Mok'Morokk" }, [5836] = { "22:1851370774:155314897", "หีบนิรภัยของ Mok'Morokk" } },
        steps = { { "18:1208146044:1478565982", "ยานัตถุ์ของ Mok'Morokk" }, { "17:1831768598:1672857024", "เหล้าของ Mok'Morokk" }, { "22:1851370774:155314897", "หีบนิรภัยของ Mok'Morokk" } },
    },
    [1168] = { -- Army of the Black Dragon
        title = { "24:1622266114:166847028", "กองทัพมังกรดำ" },
        objective = { "116:1369011775:455990253", "Tharg ที่ Brackenwall Village ต้องการให้เจ้าฆ่า Firemane Scouts 10 ตัว, Firemane Ash Tails 10 ตัว และ Firemane Scalebanes 5 ตัว", variants = { { "112:1415223849:1498792251", "Tharg ที่ Brackenwall Village ต้องการให้เจ้าฆ่า Firemane Scouts 15 ตัว, Firemane Ash Tails 10 ตัว และ Firemane Guards 5 ตัว" } } },
        description = { "422:704553989:1293108007", "Rexxar ตั้ง Mok'Morokk เป็นผู้นำ เขาสนพลังมากกว่าออกร์\n\nมังกรดำฆ่าออกร์มาก ฆ่าเมีย Tharg Mok'Morokk บอกหนี พาเราที่นี่\n\nออกร์ควรสู้ วิ่งไม่เก่ง Mok'Morokk สนแต่ตัวเอง\n\nข้าเรียก Stonemaul Ruins ว่าบ้าน ข้าชอบทางใต้ ที่นี่ไม่ใช่บ้าน\n\nช่วยออกร์สู้ทัพมังกรดำ อยากแก้แค้น อยากกลับบ้าน" },
        progress = { "182:1901984187:365864821", "Mok'Morokk สั่งออกร์อยู่คุ้มที่นี่ ข้าคิดว่าต้องฆ่าทัพมังกรดำ เอาบ้านเก่าคืน\n\nเจ้าช่วยเอาบ้านคืน ช่วยแก้แค้น" },
        completion = { "50:2002112311:1952047293 R 19:1022390416:1337572205", "เจ้าฆ่าทัพมังกรดำมาก เป็น {race} กล้า\n\nทำ Tharg ดีใจ" },
        objectiveLabels = {
            monster = { ["Firemane Scout slain"] = "ปราบ หน่วยสอดแนม Firemane", ["Firemane Ash Tail slain"] = "ปราบ หางเถ้าถ่าน Firemane", ["Firemane Scalebane slain"] = "ปราบ นักพิฆาตเกล็ด Firemane" },
        },
    },
    [1169] = { -- Identifying the Brood
        title = { "21:1456209917:1116476274", "ระบุต้นตอฝูงมังกร" },
        objective = { "102:35834495:2080447579", "Draz'Zilb ที่ Brackenwall Village ต้องการ Searing Tongues 15 ชิ้น และ Searing Hearts 15 ดวง" },
        description = { "263:1537088234:1954221204 N 204:274196348:968528666", "ขณะ Mok'Morokk เจ้าโง่ขลาดมัวเมาอำนาจ และ Tharg ต่อสู้ความเศร้าแค้นแย่งนำเผ่า ดูเหมือนข้าคนเดียวสนต้นตอที่บุกบ้านเก่า\n\nทำไมมองงง {name}? คิดว่าข้าต้องพูดไร้มารยาทเพียงเพราะเป็นออกร์หรือ?\n\nกลับธุระ นำหัวใจกับลิ้นลูกมังกรมา จะตามรากความชั่วนี้..." },
        progress = { "420:1785543759:109725936", "ด้วยหัวใจกับลิ้นลูกมังกรไฟแห่งทัพดำ ข้าจะรู้ว่าสัตว์ร้ายใดวางลูกในบ้านเรา รู้ศัตรูมากขึ้น บางทีทำลายถาวร กู้ Stonemaul Village จากซากได้\n\nแน่นอน เกลี้ยกล่อม Mok'Morokk ให้ขยับก้อนไขมันขี้เกียจจากหลุมโคลน ก็เป็นมหากาพย์ภารกิจในตัว..." },
        completion = { "204:439669082:1221332208", "เก็บหัวใจกับลิ้นคงอันตรายแน่ ข้าจะเจาะลึกอาร์เคนตามต้นกำเนิดภัยดำที่ลงบ้านเก่า" },
        required = { [5840] = { "14:644651966:1414657677", "ลิ้นแผดร้อน" }, [5841] = { "13:1236200735:814636575", "หัวใจแผดร้อน" } },
        steps = { { "14:644651966:1414657677", "ลิ้นแผดร้อน" }, { "13:1236200735:814636575", "หัวใจแผดร้อน" } },
    },
    [1170] = { -- The Brood of Onyxia
        title = { "19:564244339:35555229", "ลูกหลาน Onyxia" },
        objective = { "54:1323039063:695906436", "คุยกับ Overlord Mok'Morokk ที่ Brackenwall Village" },
        description = { "304:668492906:1961990602", "ลูกหลาน Onyxia บุก Stonemaul แต่เหตุใดธิดาจอมมังกรดำ Deathwing จึงมาที่เรา?\n\nน่ากังวล ต้องมีจุดหมายเหนือกว่าล้อมออกร์กลุ่มเล็ก\n\nแจ้ง Mok'Morokk ทันที! ต้องลงมือ" },
        completion = { "84:1474690052:988608399", "ทำไมบอกเรื่องมังกร? ข้าไม่ชอบมังกร ชอบที่นี่ ไม่มีมังกร" },
    },
    [1171] = { -- The Brood of Onyxia
        title = { "19:564244339:35555229", "ลูกหลาน Onyxia" },
        objective = { "44:496417452:1537489005", "คุยกับ Draz'Zilb ที่ Brackenwall Village" },
        description = { "77:657867948:1653732691", "เลิกรบกวนข้า ไปบอก Draz'Zilb ว่าเราอยู่ที่นี่ ไม่มีมังกรดำ" },
        completion = { "275:1915839499:797348628", "เจ้าขลาดขี้เกียจ!\n\nตอน Rexxar นำ Mok'Morokk เคยเข้มแข็ง แต่ไม่นานหลัง Rexxar จาก ก็หลงสิ่งยั่วอำนาจ แทนนำกลับสั่ง ไม่รับใช้คนของตน แต่หวังเราเป็นฝ่ายรับใช้\n\nต้องทำอะไรแล้ว" },
    },
    [1172] = { -- The Brood of Onyxia
        title = { "19:564244339:35555229", "ลูกหลาน Onyxia" },
        objective = { "71:1937553864:1975028984", "Draz'Zilb ที่ Brackenwall Village ต้องการให้เจ้าทำลาย Eggs of Onyxia 5 ฟอง" },
        description = { "405:1293140424:1187099505", "ลูกหลาน Onyxia กระจายทั่ว Dragonmurk ต้องห้ามฟักลูกเพิ่ม\n\nรีบ Wyrmbog ทางใต้ Dustwallow Marsh นางคงมีรังที่นั่น หาไข่มังกรชั่วแล้วทำลาย\n\nไม่อาจเอา Stonemaul คืนหากรอบ ๆ ยังเพาะพันธุ์\n\nส่วน Mok'Morokk...ข้ามีแผนอื่นสำหรับมัน" },
        progress = { "34:1278710475:1780536867 N 191:399493486:1385134906", "รีบ Dragonmurk {name} ไข่ Onyxia เต็ม Wyrmbog จะถูกจำนวนท่วมหากไม่ทำเร็ว\n\nทำลายไข่! อย่าให้ภัยมังกรดำลามบ้านเรา!" },
        completion = { "104:1321464465:1516780437 N 329:193238968:469729968", "ยอดเยี่ยม! อีกพักใหญ่ Onyxia จึงวางไข่เพิ่มได้\n\nในนามคนของข้า ขอบคุณ {name}\n\nขอมากแล้ว บางทีช่วย Stonemaul ครั้งสุดท้าย\n\nMok'Morokk ไม่เหมาะนำ Tharg ดีแต่ติดแผลกับอายุ ใช้กำลังไล่ Mok'Morokk จึงจะตั้งผู้นำใหม่พากลับบ้านใต้ได้" },
        steps = { { "23:513249605:1104335285", "ทำลายไข่ของ Onyxia" } },
    },
    [1173] = { -- Challenge Overlord Mok'Morokk
        title = { "29:1638650028:1861791039", "ท้า Overlord Mok'Morokk" },
        objective = { "74:1531827435:1029624015", "เอาชนะ Mok'Morokk แล้วรายงาน Draz'Zilb ที่ Brackenwall Village" },
        description = { "59:144014905:906799709 R 42:1983231776:1609883491", "กล้าท้า Overlord Mok'Morokk?\n\nฮ่า!\n\nข้าบด {race} ตัวจิ๋ว!\n\nพร้อมโดนอัดเมื่อไรบอก" },
        progress = { "112:1163235507:603516932", "คิดว่าเจ้าจะไล่ Mok'Morokk จากหมู่บ้าน แต่กลับมาคุยข้าหรือ?" },
        completion = { "91:1334512739:1396650276 N 101:2105133494:736501472", "ก้อนไขมันขลาด Mok'Morokk หนีเหมือนเด็กกลัว เจ้าช่วยมาก {name}\n\nบัดนี้เผ่าตั้งผู้นำใหม่ที่จะช่วยคืนบ้านเก่าได้ถาวร" },
        objectiveLabels = {
            event = { ["Drive Overlord Mok'Morokk from Brackenwall Village"] = "ขับไล่ Overlord Mok'Morokk ออกจาก Brackenwall Village" },
        },
    },
    [1177] = { -- Hungry!
        title = { "7:1587649940:1588835822", "หิว!" },
        objective = { "64:139859373:321241535", "Mudcrush Durtfeet ทางเหนือ Dustwallow ต้องการ Mirefin Heads 12 หัว" },
        description = { "84:209097375:19908469", "Mud ออกร์ใหญ่\n\nข้าหิว\n\nไปทุบปลา เอาอาหารให้ Mud\n\nเจ้าให้อาหาร ไม่งั้น Mud กินเจ้า" },
        progress = { "25:306174046:465431656", "เอาอาหาร ไม่งั้นกินเจ้า" },
        completion = { "38:1614143577:2071874294", "ข้าชอบหัวปลา!\n\nตอนนี้ไม่กินเจ้า" },
        required = { [5847] = { "12:1967642980:73785831", "หัวของ Mirefin" } },
        objectiveLabels = {
            item = { ["Mirefin Head"] = "หัวของ Mirefin" },
        },
    },
    [1201] = { -- Theramore Spies
        title = { "15:1049089922:1083598267", "สายลับ Theramore" },
        objective = { "86:621202450:664680882", "ฆ่า Theramore Infiltrators 9 คน แล้วกลับไปหา Nazeer Bloodpike ที่ Brackenwall Village" },
        description = { "498:481502298:995499720", "Horde กับ Alliance สงบศึกอย่างเปราะบาง แต่ต่างฝ่ายยังปะทะรอบนอกและลงมือลับ หน้าที่เราคือให้ Horde เหนือกว่า!\n\nตอนนี้มีโอกาส\n\nAlliance แทรกซึมตะวันออก Brackenwall สอดแนมหมู่บ้าน รายงานความเคลื่อนไหวให้ Theramore ปล่อยไม่ได้\n\nตามฆ่าพวกมัน ส่งสารชัดถึงหัวหน้าว่าเราไม่ยอมให้สายลับอยู่!" },
        progress = { "31:746645338:1984066504 N 1:63:63", "พบผู้แทรกซึมไหม {name}?" },
        completion = { "111:1233294695:1536807480", "ดีมาก สายลับเก่ง แต่ไม่พอหลบสายตา Horde!" },
        objectiveLabels = {
            monster = { ["Theramore Infiltrator slain"] = "ปราบ ผู้แฝงตัวจาก Theramore" },
        },
    },
    [1202] = { -- The Theramore Docks
        title = { "19:2115502994:692788921", "ท่าเรือ Theramore" },
        objective = { "73:427918291:98000384", "นำ Captain's Documents ไปให้ Nazeer Bloodpike ที่ Brackenwall Village" },
        description = { "N 416:1491501055:1517006172 N 23:418498471:534672749", "{name} สายลับเราสองคนถูกส่งขโมยเอกสารจากเรือที่ท่า Theramore ได้มาแต่ถูกพบ จึงต้องโยนลงทะเล\n\nคนหนึ่งหนีภายหลัง แต่กู้ของไม่ได้ รายงานความล้มเหลว ข้าจึงมอบงานให้เจ้า\n\nเอกสารอยู่หีบในน้ำใต้ท่าเรือสักแห่ง หาให้พบ {name} แล้วนำมา" },
        progress = { "28:1653339402:2128915980 N 110:1518313873:1970397764", "พบเอกสารไหม {name}? ข้อมูลสำคัญต่อเสถียรภาพ Alliance จึงสำคัญต่อความปลอดภัย Horde" },
        completion = { "15:421406717:488920675 N 97:818912612:1594623645", "ข้าชมเชย {name} งานไม่ง่าย แต่ผู้บังคับบัญชาให้ค่าเอกสารมาก" },
        required = { [5882] = { "19:257835343:1380547589", "เอกสารของกัปตัน" } },
        steps = { { "19:257835343:1380547589", "เอกสารของกัปตัน" } },
    },
    [1203] = { -- Jarl Needs a Blade
        title = { "18:794750849:410351209", "Jarl ต้องการดาบ" },
        objective = { "57:1930373872:1625829395", "นำ Moonsteel Broadsword ไปให้ Jarl ที่ Dustwallow Marsh" },
        description = { "341:1168584477:1287347671", "ข้ามีของต้องหั่น บอกไม่ได้ว่าอะไร แต่...ต้องมีดาบ ดาบแบบหนึ่ง...\n\nบางคนเรียก moonsteel broadsword ข้าเรียกดาบเหวี่ยง\n\nช่วยไหม? อาจหาในเมือง หรือคุยช่างตีเหล็กให้ทำพิเศษ\n\nแต่อย่าช้า ของจะหั่นเก็บไม่ได้ตลอด..." },
        progress = { "19:1919710602:1044239746", "มีดาบข้าไหม??" },
        completion = { "196:832549912:354045728", "ดาบดี เหวี่ยงดี ดาบเหวี่ยงดี ขอบคุณ ขอบคุณ ขอบคุณ ขอบคุณ!!! อยากลองแล้ว...\n\nไว้ก่อน ค่อยลอง อย่างที่บอก...ขอบใจ" },
        required = { [3853] = { "20:844015315:1051409058", "ดาบใบกว้างเหล็กกล้าจันทรา" } },
        steps = { { "20:844015315:1051409058", "ดาบใบกว้างเหล็กกล้าจันทรา" } },
    },
    [1204] = { -- Mudrock Soup and Bugs
        title = { "21:1744353153:1153770480", "ซุป Mudrock กับแมลง" },
        objective = { "60:1952076728:1868950542", "นำ Forked Mudrock Tongues 8 ชิ้น ไปให้ Morgan Stern ที่ Theramore" },
        description = { "170:500811548:1394270296 N 320:1281444266:2079976736", "ข้าทำเมนู “ซุป Mudrock กับแมลง” ยังขาดส่วนหลัก และ...คงอยู่ไม่นานหากลุยบึงเอง!\n\n{name} ล่าให้ได้ไหม? ก่อนอื่นลิ้นเต่า Mudrock พบตามชายฝั่ง โดยมากรอบอ่าว\n\nแต่ไม่ใช่ลิ้นอะไรก็ได้ ได้ยินว่าบางตัวลิ้นแฉก...\n\nว่ากันว่ารสเฉพาะ ข้าต้องการรสนั้นในจาน..." },
        progress = { "31:479396112:34680012", "ได้ลิ้นแฉกไหม?" },
        completion = { "31:1468691643:1405266067 N 188:1042962000:376431175", "ใช้ได้ดี! ขอบคุณ {name}!\n\nจะลองเทคนิคปรุงหลายอย่าง หาวิธีดึงรสดีที่สุด\n\nท้ายสุดจะได้จานคู่ควรเสิร์ฟ Blue Recluse ที่ Stormwind!" },
        required = { [5883] = { "21:396280850:289338392", "ลิ้นแฉกของเต่า Mudrock" } },
        steps = { { "21:396280850:289338392", "ลิ้นแฉกของเต่า Mudrock" } },
    },
    [1205] = { -- Deadmire
        title = { "8:384697930:1353997817", "Deadmire" },
        objective = { "49:1485606775:371577089", "นำ Deadmire's Tooth ไปให้ Melor ที่ Thunder Bluff" },
        description = { "389:423078356:875962381 N 34:1088549964:359473033", "Deadmire คือครอโคลิสก์โบราณใน Dustwallow ถึงเวลาตายแล้ว\n\nกระดูกเก่าเสียดสีขณะลากกายใหญ่ผ่านบึง แม้ยังแรงเร็วอย่างหนุ่ม ร่างชราทรมานวิญญาณยิ่งใหญ่ภายใน เปลวไฟที่ไม่ยอมอ่อน\n\nแต่มันอยู่กับปวดคลั่งไม่หยุด ต้องจบชีวิตสัตว์สูงส่งนี้ {name} พา Deadmire สู่สงบ" },
        progress = { "35:1592092976:2075183165 N 42:590181942:1127495460", "มีเขี้ยว Deadmire หรือยัง {name}? จบทุกข์มันแล้วหรือ?" },
        completion = { "11:1776810664:1873330125 N 93:483137755:1012075781", "ดีมาก {name}\n\nมั่นใจว่าล่าไม่ง่าย แต่ดีที่ความเจ็บสัตว์สิ้นสุด" },
        required = { [5945] = { "16:755088952:87468166", "ฟันของ Deadmire" } },
        steps = { { "16:755088952:87468166", "ฟันของ Deadmire" } },
    },
    [1206] = { -- Jarl Needs Eyes
        title = { "15:1592985661:519469736", "Jarl ต้องการดวงตา" },
        objective = { "76:1543272237:310167942", "นำ Unpopped Darkmist Eyes 40 ดวง ไปให้ “Swamp Eye” Jarl ที่ Swamplight Manor" },
        description = { "363:1732818490:963557940", "น้ำตาในลูกตาดื่มดี เสียดายสัตว์ส่วนใหญ่แค่สองตา\n\nแต่แมงมุมตามาก มากมาย น้ำตา Darkmist อร่อย นุ่มเค็ม! ลูกตาไม่แตก...แทบรู้รสแล้ว\n\nแมงมุม Darkmist อยู่ตะวันตก ใน Darkmist Cavern เจ้าคิดว่าชื่อตามถ้ำ...หรือถ้ำตามแมงมุม?" },
        progress = { "21:1015692454:2009675425", "ตาพวกนั้นอยู่ไหน?" },
        completion = { "259:951923746:1300834920", "ได้ตาแล้ว! ได้แล้ว! ตาแมงมุมอร่อย!\n\nบางตา...พอจ้องมันก็จ้องกลับ กินทีหลัง มันเป็นเพื่อน...ในบึง\n\nสวัสดี ตาแมงมุมน้อย สวัสดี! รสเหมือนไก่ ไก่เหนียวเค็ม!\n\nอืม" },
        required = { [5884] = { "21:2024238357:1231128535", "ดวงตา Darkmist ที่ยังไม่แตก" } },
        objectiveLabels = {
            item = { ["Unpopped Darkmist Eye"] = "ดวงตา Darkmist ที่ยังไม่แตก" },
        },
    },
    [1218] = { -- Soothing Spices
        title = { "15:570335490:1770959346", "เครื่องเทศบำรุงใจ" },
        objective = { "64:1075635988:2076073257", "นำ Soothing Spices 3 ส่วน ไปให้ “Swamp Eye” Jarl ที่ Dustwallow Marsh" },
        description = { "213:1923524560:1229837462", "ข้าชอบทำอาหาร อาหารบึงดี เช่นขากบเขียวทอด\n\nปรุงต้องเครื่องเทศ เครื่องเทศบำรุงใจ แล้วจะทำสตู ตุ๋นให้เดือด ซด แล้วแบ่งเจ้าด้วย\n\nชอบสตูไหม?" },
        progress = { "58:1743828861:788275498", "เครื่องเทศ ชีวิตเราควรมีรสชาติสักหน่อย เห็นด้วยไหม?" },
        completion = { "55:1593263070:988077626", "อา เครื่องเทศนี่เอง! รับสตูบึงอร่อยไป" },
        required = { [3713] = { "15:570335490:1770959346", "เครื่องเทศรสละมุน" } },
        steps = { { "15:570335490:1770959346", "เครื่องเทศรสละมุน" } },
    },
    [1219] = { -- The Orc Report
        title = { "14:1193609714:400153685", "รายงานออร์ค" },
        objective = { "49:2051341961:1557161744", "นำ Spy's Report ไปให้ Theramore Lieutenant" },
        description = { "223:1207186824:954957343", "คุ้ยดินร่วนพบมือออร์คขาด กำกระบอกกระดูกแกะ ภายในมีแผ่นหนังเปื้อนดิน\n\nเขียนภาษาออร์ค...ดูสำคัญ" },
        progress = { "29:1079283817:182134432", "มีอะไรจะรายงาน?" },
        completion = { "91:327499339:1439116773", "อืม...ข้าอ่านออร์คไม่คล่อง แต่ดูเป็นรายงาน...จากสายลับออร์ค!" },
        required = { [5917] = { "12:1952028509:202289053", "รายงานของสายลับ" } },
        steps = { { "12:1952028509:202289053", "รายงานของสายลับ" } },
    },
    [1222] = { -- Stinky's Escape
        title = { "15:1140118643:317318709", "การหลบหนีของ Stinky" },
        objective = { "66:1478926914:1022835432", "คุ้มกัน “Stinky” Ignatz แล้วคุยกับ Morgan Stern ที่ Theramore" },
        description = { { "407:326370274:599347259", "406:1581809590:207435307" }, "เยี่ยม ในที่สุดก็สิ่งที่ไม่อยากกินข้า!\n\nต้องการคนช่วยรับมือสัตว์ เจ้าเหมาะเลย สหาย\n\nพ่อครัว Morgan Stern วิจัยสูตรใหม่ ส่งข้าเก็บใบ bogbean คงคิดว่าอร่อย\n\nแต่ตอนหาต้น...ถูกล้อม! ช่วยออกไปและคุ้มกันขณะหาได้ไหม?" },
        progress = { "89:1945066808:1495643396", "เห็นคุณ Ignatz ไหม? ส่งเข้าบึงพักใหญ่ยังไม่กลับ!" },
        completion = { "117:591760310:497879986 N 100:1597621651:494984019", "คุณ Ignatz เพิ่งนำใบ bogbean มา บอกว่าเจ้าช่วยจากปัญหาจริง ๆ\n\nขอบคุณ {name} จะขอให้ลุงเลี้ยงมื้อใหญ่เมื่อเจ้าไป Blue Recluse ที่ Stormwind ครั้งหน้า" },
        objectiveLabels = {
            event = { ["Help Stinky find Bogbean Leaves"] = "ช่วย Stinky หาใบ Bogbean" },
        },
    },
    [1239] = { -- The Severed Head
        title = { "16:617478708:1080317031", "ศีรษะที่ถูกตัด" },
        objective = { "70:1070217243:120017732", "นำ Defiant Orc Head ไปให้ Nazeer Bloodpike ที่ Brackenwall Village" },
        description = { "145:1505821523:1240375699", "ขุดแรงขึ้นพบหัวออร์คชาย คอถูกตัดขาดขรุขระ ปากค้างแยกเขี้ยว ตาดำจ้องท้าทาย" },
        progress = { "35:1338236245:623390133 N 1:63:63", "มีเรื่องอื่นรายงานหรือ {name}?" },
        completion = { "200:440725961:1126941110 N 68:1134450467:1363634540", "หัว Marg Nighteye! ตายจริงดังกลัว\n\nดูแผลคอ! อาวุธทำรอยขาดเช่นนี้ หรือสัตว์ฆ่าสายลับ?\n\nปริศนาต้องไข {name} ต้องรู้ว่า Alliance ลงมือหรือไม่!" },
        required = { [5918] = { "16:910327667:1602391438", "ศีรษะของออร์กผู้แข็งข้อ" } },
        steps = { { "16:910327667:1602391438", "ศีรษะของออร์กผู้แข็งข้อ" } },
    },
    [1240] = { -- The Troll Witchdoctor
        title = { "21:232993953:1937168659", "หมอผีโทรลล์" },
        objective = { "88:1419768948:86078936", "นำ Defiant Orc Head ไปให้ Kin'weelay ที่ Grom'gol Base Camp ใน Stranglethorn Vale" },
        description = { "79:1874093982:2042412889 N 247:1018508509:1283173622", "ต้องรู้เหตุรอบความตาย Marg! ทางเดียว {name} คือเวทหมอผีโทรลล์\n\nนำหัวไปให้ Kin'weelay ที่ Grom'gol Base Camp ใน Stranglethorn\n\nเขาคือหมอผีทรงพลังที่สุดของ Darkspear หากใครพูดกับวิญญาณ Marg ได้ ต้องเขา" },
        progress = { { "75:567137837:1249371503", "74:1453657191:1387844514" }, "มีวิญญาณโกรธอยู่รอบเจ้า สหาย อะไรพามาหา Kin'weelay?" },
        completion = { "149:1159800755:587624703", "อา เห็นแล้ว วิญญาณออร์คนี้ผูกกับโลก เดือดแค้นเพราะงานยังไม่จบ\n\nมาคุยกับออร์คโกรธนี้กัน..." },
        required = { [5918] = { "16:910327667:1602391438", "ศีรษะของออร์กผู้แข็งข้อ" } },
        steps = { { "16:910327667:1602391438", "ศีรษะของออร์กผู้แข็งข้อ" } },
    },
    [1251] = { -- The Black Shield
        title = { "16:1993554830:1930164564", "โล่ดำ" },
        objective = { "63:1510171973:710597418", "นำ Blackened Iron Shield ไปให้ Krog ที่ Brackenwall Village" },
        description = { "245:198592495:99867202", "โล่เหล็กดำจากไฟที่โหมโรงเตี๊ยมติดอยู่กับปล่องผุพัง หนึ่งในส่วนเหลือไม่กี่อย่างของ Shady Rest Inn\n\nถอดโล่จากอิฐปล่องได้" },
        progress = { "28:492447491:187554544 N 50:1623377304:318224084", "มีอะไรนั่น {name}? หลักฐานจากซาก Shady Rest Inn หรือ?" },
        completion = { "206:773253799:365836051", "ยอมรับว่ามนุษย์แต่งบ้านแปลก แต่จะใช้โล่เหล็กธรรมดาประดับเตาผิงหรือ? บางทีผู้เผาโรงเตี๊ยมวางไว้\n\nคำเตือน? ข่มขู่?" },
        required = { [5919] = { "21:69126555:1056793148", "โล่เหล็กดำคล้ำ" } },
        steps = { { "21:69126555:1056793148", "โล่เหล็กดำคล้ำ" } },
    },
    [1252] = { -- Lieutenant Paval Reethe
        title = { "23:1544055727:1758594384", "Lieutenant Paval Reethe" },
        objective = { "58:1892105814:1210451510", "นำ Reethe's Badge ไปให้ Captain Garran Vimes ที่ Theramore" },
        description = { "291:772584369:888842044", "แสงจากใต้ซากบนพื้นสะดุดตา ปัดเศษกับเถ้าจับวัตถุ เผยตราสมอทองบนพื้นเคลือบขาว เครื่องหมาย Theramore\n\nใต้สมอมีชื่อ “Lieutenant Paval Reethe” นูนอยู่" },
        progress = { "58:495114387:968537696", "พบอะไรน่าสนใจที่ Shady Rest Inn ไหม?" },
        completion = { "264:151164962:1095604956", "ไม่เคยเป็นข่าวดีเมื่อมีคนเอาตรายามมาให้\n\nบางครั้งคนล้มในศึก ข้าต้องแจ้งครอบครัวเศร้า บางครั้งไม่รู้เลยว่าเกิดอะไร และบางครั้งยิ่งเลวร้ายกว่า" },
        required = { [5950] = { "14:1922733337:1674622971", "ตราของ Reethe" } },
        steps = { { "14:1922733337:1674622971", "ตราของ Reethe" } },
    },
    [1253] = { -- The Black Shield
        title = { "16:1993554830:1930164564", "โล่ดำ" },
        objective = { "69:2002102174:1451434335", "นำ Blackened Iron Shield ไปให้ Captain Garran Vimes ที่ Theramore" },
        description = { "245:198592495:99867202", "โล่เหล็กดำจากไฟที่โหมโรงเตี๊ยมติดอยู่กับปล่องผุพัง หนึ่งในส่วนเหลือไม่กี่อย่างของ Shady Rest Inn\n\nถอดโล่จากอิฐปล่องได้" },
        progress = { "60:1265136292:211890592", "พบหลักฐานที่ Shady Rest Inn หรือ?" },
        completion = { "192:1392202498:1796211611", "อืม ไม่เชี่ยวชาญสร้างอาวุธเกราะ ใช้เป็น แต่ทำไม่เป็น\n\nโล่ดูธรรมดา เว้นรอยไฟที่กลืนโรงเตี๊ยม" },
        required = { [5919] = { "21:69126555:1056793148", "โล่เหล็กดำคล้ำ" } },
        steps = { { "21:69126555:1056793148", "โล่เหล็กดำคล้ำ" } },
    },
    [1258] = { -- ... and Bugs
        title = { "12:1279730702:1419274693", "...กับแมลง" },
        objective = { "60:1464619986:220060263", "นำ Pristine Crawler Legs 12 ขา ไปให้ Morgan Stern ที่ Theramore" },
        description = { "440:621209029:904353154 N 30:95457649:1040766046", "อีกส่วนสูตรใหม่คือขาปูยักษ์มีเปลือก แต่ปู Dustwallow ที่เรียก Muckshell ใช้ไม่ได้! เกรงว่าที่เหมาะมีไกลใน Swamp of Sorrows เท่านั้น\n\nเปลือกขาสำคัญต่อจัดจาน ต้องสมบูรณ์ไร้แผล ปูโตอาจมีเพียงหนึ่งสองขาเช่นนั้น แต่ข้าต้องมากเพื่อวิจัย\n\n{name}...ยอมเดินทางไหม?" },
        progress = { "93:1540537894:1875618125", "วิจัยลิ้น Mudrock คืบหน้าดี เชื่อว่าล่าปูก็ได้ผล?" },
        completion = { "31:203909678:1604388045 N 125:1042936571:508838896", "ตัวอย่างวิเศษ {name}! เปลือกสมบูรณ์ เนื้อชมพูนุ่ม มั่นใจว่าเจ้ามีเลือดพ่อครัวในตัว!" },
        required = { [5938] = { "20:530376190:1147936730", "ขาปูสภาพสมบูรณ์" } },
        steps = { { "20:530376190:1147936730", "ขาปูสภาพสมบูรณ์" } },
    },
    [1259] = { -- Lieutenant Paval Reethe
        title = { "23:1544055727:1758594384", "Lieutenant Paval Reethe" },
        objective = { "62:1828543774:864994131", "ถามข้อมูล Reethe เพิ่มจาก Adjutant Tesoran ที่ Theramore" },
        description = { "285:428195232:289490109", "ไม่รู้จักชื่อ Lieutenant Paval Reethe ควรถาม Adjutant Tesoran เขาเก็บบันทึกยาม Theramore ทั้งบุคลากรและอุปกรณ์\n\nดูสมุดครู่คงบอกว่า Reethe คือใครได้" },
        completion = { "7:989913233:66981971 N 134:812762282:875198627", "สวัสดี {name} อยากรู้ข้อมูลยามคนหนึ่ง? Reethe ใช่ไหม?\n\nรอข้าหาสมุดถูกเล่มครู่" },
    },
    [1260] = { -- Morgan Stern
        title = { "12:373978472:1096717713", "Morgan Stern" },
        objective = { "37:2082212810:122516340", "คุยกับ Morgan Stern ที่ Theramore" },
        description = { "393:270763178:1144397468 C 55:1263927982:417707673", "ข้าพัฒนาเมนูร้านใหม่ เต็มด้วยอาหารพื้นบ้านธีมบึง คิดว่าลูกค้า Blue Recluse ต้องชอบ!\n\nส่งหลาน Morgan ไป Theramore เมืองริม Dustwallow เก็บสูตรจากชาวบ้าน ต้องรู้ว่าพบอะไรแล้ว\n\nทางไกลเกินข้า แต่ {class} รุ่นเยาว์เช่นเจ้าคงคว้าโอกาสเดินทาง ใช่ไหม?" },
        completion = { "152:1085019309:1771118286", "อ้อ ลุงส่งมาหรือ?\n\nข้าวิจัยสูตร มีเบาะแสบ้าง แต่ต้องการช่วย\n\nจากคนยอมให้เท้าเปียก" },
    },
    [1261] = { -- Marg Speaks
        title = { "11:1388732044:378006985", "Marg พูดขึ้น" },
        objective = { "59:2021745937:929379280", "นำ Jeweled Pendant ไปให้ Nazeer ที่ Brackenwall Village" },
        description = { "119:158539820:1030955529 N 311:1068081737:104990103 N 55:414552578:677537561", "Muckshell บัดซบ! ฆ่า Marg ไม่ได้! อา แต่ข้าตายแล้ว งั้นมันคงฆ่า...\n\nแต่ภารกิจ! {name} เจ้าต้องทำให้จบ\n\nใกล้ Theramore เห็นทหาร Alliance ตั้งค่ายหาด คนหนึ่งสวมจี้...อัญมณีมากเกินเงินทหาร!\n\nคืนนั้นลอบขโมย แต่กลับฐานถูกมนุษย์ปู muckshell ฆ่า!\n\n{name} ต้องหาปูนั้นเอาจี้คืน!" },
        progress = { "N 31:839815377:121563641", "{name} รู้ชะตา Marg หรือยัง?" },
        completion = { "61:1321162806:498358356 N 154:971055445:1857221584", "ทหาร Stormwind สวมจี้นี้หรือ??\n\nขอบคุณ {name} เปิดความลับการตาย Marg แล้ว แต่จี้เป็นปริศนาใหม่ อาจส่งผลร้ายทั้ง Alliance และ Horde" },
        required = { [5942] = { "15:576159700:1700177955", "จี้ประดับอัญมณี" } },
        steps = { { "15:576159700:1700177955", "จี้ประดับอัญมณี" } },
    },
    [1262] = { -- Report to Zor
        title = { "13:1573198421:553261303", "รายงานต่อ Zor" },
        objective = { "55:756378985:452270790", "นำ Jeweled Pendant ไปให้ Zor Lonetree ที่ Orgrimmar" },
        description = { "447:636509764:934701535", "แปลกที่จี้ Marg ขโมยอยู่กับทหารธรรมดา เจ้าของอาจปลอมตัว หรือทหารขโมยมา!\n\nไม่ว่าจริงข้อใด นี่จี้ขุนนาง ต้องรู้เจ้าของแท้จึงไขได้\n\nนำให้ Zor Lonetree ที่ Orgrimmar เขารู้การเมือง Alliance ดี จะรู้ว่าจี้มีประวัติในหมู่ขุนนาง Stormwind หรือไม่" },
        progress = { "109:2044373769:203260173", "มาจาก Brackenwall Village ใน Dustwallow หรือ? Nazeer กับงานในบึงเป็นอย่างไร?" },
        completion = { "57:1829252178:146899473 N 156:1739303470:298091503", "จี้สร้างอย่างประณีตแม่นยำ {name} ไม่มีออร์คอยากได้อัญมณีเช่นนี้...\n\nแต่มนุษย์มากคนอยาก\n\nจะให้ศึกษา หวังว่าสักวันปริศนาจะเผย" },
        required = { [5942] = { "15:576159700:1700177955", "จี้ประดับอัญมณี" } },
        steps = { { "15:576159700:1700177955", "จี้ประดับอัญมณี" } },
    },
    [1268] = { -- Suspicious Hoofprints
        title = { "21:95447675:1430866720", "รอยกีบน่าสงสัย" },
        objective = { "88:2041512585:1497354900", "รายงานรอยน่าสงสัยที่ Shady Rest Inn ให้ Krog ที่ Brackenwall Village" },
        description = { "205:1771720733:1551279151", "แนวรอยกีบออกจากโครง Shady Rest Inn ที่ยังควันกรุ่น เห็นชัดอย่างน้อยสองสามรอย และแนวอื่นแทบมองไม่เห็นในโคลนอ่อน" },
        completion = { "379:1067629947:2041049677", "รอยกีบ...อาจควิลบอร์ หรือแม้แต่เซนทอร์ มีไม่น้อยใน Barrens ทำเรื่องนี้คงไม่เกินตัว\n\nบอกหรือยัง? ไม่ใช่แค่เผาโรงเตี๊ยม ภรรยากับลูกเจ้าของถูกฆ่า เรื่องเลวร้าย\n\nอย่างไรก็จะส่ง Kagoro ตามรอย" },
    },
    [1269] = { -- Lieutenant Paval Reethe
        title = { "23:1544055727:1758594384", "Lieutenant Paval Reethe" },
        objective = { "52:296451963:1776184485", "นำ Reethe's Badge ไปให้ Krog ที่ Brackenwall Village" },
        description = { "287:352047478:209755912", "แสงจากใต้ซากบนพื้นสะดุดตา ปัดเศษกับเถ้าจับวัตถุ เผยตราสมอทองบนพื้นเคลือบขาว เครื่องหมาย Theramore\n\nใต้สมอมีชื่อ “Lieutenant Paval Reethe” นูนอยู่" },
        progress = { "64:321240232:525208213", "พบเบาะแสเหตุ Shady Rest Inn บ้างไหม?" },
        completion = { "280:791630151:1750161091", "รู้จักมนุษย์ Paval Reethe น่าสมเพชแม้เทียบเผ่าตน ทิ้งเพื่อนทหาร ซ่อนป่าอยู่\n\nส่ง Ogron ตาม บางคนสงสัยว่าขโมยเสบียงเรา เห็น Ogron ไปตะวันออกเฉียงใต้" },
        required = { [5950] = { "14:1922733337:1674622971", "ตราของ Reethe" } },
        steps = { { "14:1922733337:1674622971", "ตราของ Reethe" } },
    },
    [1270] = { -- Stinky's Escape
        title = { "15:1140118643:317318709", "การหลบหนีของ Stinky" },
        objective = { "66:1049126547:1846054867", "คุ้มกัน “Stinky” Ignatz แล้วคุยกับ Mebok Mizzyrix ที่ Ratchet" },
        description = { { "450:1306690824:1837433837", "449:498246679:1310261227" }, "เยี่ยม ในที่สุดสิ่งที่ไม่อยากกินข้า!!\n\nต้องการคนช่วยรับมือสัตว์ เจ้าเหมาะเลย สหาย\n\nก็อบลิน Ratchet ชื่อ Mebok Mizzyrix ต้องการใบ bogbean ทำน้ำยาหรืออะไร...ไม่สนเหตุผล จ่ายดี ข้ารู้จักบึง จึงมา\n\nแย่ที่ถูกล้อมก่อนพบต้น! ช่วยออกไปและคุ้มกันขณะหาต้นให้ Mebok ได้ไหม?" },
        completion = { "242:2056553762:353396430", "Stinky นำสมุนไพรที่ขอมา บอกเจ้าช่วยพ้นปัญหา ทำได้ดี! เพื่อน Stinky ก็เพื่อนข้า!\n\nเขาฝากให้เจ้านี่ถ้าพบ ก่อนเดินกลับลงใต้เข้าบึง" },
        objectiveLabels = {
            event = { ["Help Stinky find Bogbean Leaves"] = "ช่วย Stinky หาใบ Bogbean" },
        },
    },
    [1271] = { -- Feast at the Blue Recluse
        title = { "25:1510272198:837398339", "งานเลี้ยงที่ Blue Recluse" },
        completion = { "201:1985886218:1061171618 N 53:654528895:1221510060", "หลานบอกช่วยวิจัย Dustwallow และช่วยสหายพ้นลำบาก ตระกูล Stern อยู่ด้วยกัน ไม่ละเลยเพื่อน!\n\nล้างมือ {name} เราจะเลี้ยงฉลองให้เจ้า!" },
    },
    [1273] = { -- Questioning Reethe
        title = { "18:294316158:1069917032", "สอบถาม Reethe" },
        objective = { "79:2112073793:1108318299", "ไปกับ Ogron เพื่อคุยกับ Reethe แล้วกลับไปหา Krog ที่ Brackenwall Village" },
        description = { "181:1483513512:505152569", "ใช้เวลานาน แต่พบ Reethe แล้ว ซ่อนเก่งสำหรับมนุษย์\n\nOgron ห่วงว่าอยู่บึงนานอาจบ้า มากับข้า ไปเอาคำตอบ" },
        progress = { "20:90265801:818047712", "พบ Reethe ไหม?" },
        completion = { "260:1139949076:1022975801", "ฮึ ดีที่ Reethe ไม่หลบในบึงอีก แต่เสียดายมนุษย์เปราะบางจนฟื้นจากแผลลูกศรนิดไม่ได้\n\nเบาะแสนี้คงตัน ต้องหาอื่น" },
        objectiveLabels = {
            event = { ["Question Reethe with Ogron"] = "สอบถาม Reethe พร้อมกับ Ogron" },
        },
    },
    [1276] = { -- The Black Shield
        title = { "16:1993554830:1930164564", "โล่ดำ" },
        objective = { "58:1190935650:86353984", "นำ Blackened Iron Shield ให้ Mosarn ดูที่ Thunder Bluff" },
        description = { "372:1630776039:1617113003", "อา จำได้! Mosarn ช่างตีเหล็กที่นับถือใน Thunder Bluff รู้ว่าเคยได้ยินชื่อ\n\nEarthen Ring เคยขอบคุณด้วยเกราะที่เขาทำ ฝีมือดีมาก\n\nอาจบอกเรื่องโล่ที่สร้างได้\n\nเบาะแสน้อย แต่เมื่อไม่ได้อะไรจาก Reethe ก็เหลือเท่านี้" },
        progress = { "13:1911146197:485773127 C 32:932809696:954972629", "สวัสดี {class} ช่วยอะไรได้?" },
        completion = { "118:1726880631:594522296 N 86:1459332374:2121594712", "ใช่ เจ้าถูก นี่โล่ที่ข้าทำ\n\nแต่เกรงว่าบอกเพิ่มไม่ได้มาก {name} ข้าทำโล่และเกราะหลายแบบจนจำหมดไม่ได้" },
        required = { [5919] = { "21:69126555:1056793148", "โล่เหล็กดำคล้ำ" } },
        steps = { { "21:69126555:1056793148", "โล่เหล็กดำคล้ำ" } },
    },
    [1282] = { -- They Call Him Smiling Jim
        title = { "25:511123165:124779599", "ใคร ๆ เรียกเขาว่า Smiling Jim" },
        objective = { "69:1018687687:890823992", "คุยกับ Captain Garran Vimes ที่ชั้นบนสุดของ Foothold Citadel", variants = { { "45:433086445:334477184", "คุยกับ Captain Garran Vimes ที่ Theramore" } } },
        description = { "234:39219598:190253972", "ข้าอดสงสาร Jim แก่ไม่ได้ เขาไม่ได้เป็นอย่างนั้นเสมอ เคยทำโรงเตี๊ยมในบึง ที่วิเศษ\n\nฟังนะ ไม่อยากพูด หากจำเป็นคุย Captain Vimes" },
        completion = { "505:1162572157:1194730540", "ชื่อจริง James Hyal เปิดโรงเตี๊ยมริม Barrens อยากสร้างที่ดีให้นักเดินทางพัก...\n\nอาจฝันใหญ่ แต่กิจการดีพักหนึ่ง แล้วเราคุมถนนบึงไม่ได้ ออกร์ยึด\n\nJames ดื้อเกินทิ้งฝันมาปลอดภัยในกำแพง Shady Rest Inn ถูกเผาราบ เราสืบแต่ไม่คืบ หากช่วยได้ ไปดูว่าพบอะไรในซาก" },
    },
    [1284] = { -- Suspicious Hoofprints
        title = { "21:95447675:1430866720", "รอยกีบน่าสงสัย" },
        objective = { "94:614958260:853866717", "รายงานรอยน่าสงสัยที่ Shady Rest Inn ให้ Captain Garran Vimes ที่ Theramore" },
        description = { "205:1771720733:1551279151", "แนวรอยกีบออกจากโครง Shady Rest Inn ที่ยังควันกรุ่น เห็นชัดอย่างน้อยสองสามรอย และแนวอื่นแทบมองไม่เห็นในโคลนอ่อน" },
        completion = { "310:952202219:938927766", "รอยกีบหรือ? จริงที่เซนทอร์เคลื่อนไหวมากใกล้ Dustwallow ออกสำรวจ Barrens สั้น ๆ พบค่ายกับที่ยึดกระจาย\n\nจะส่ง Falgran Hastil คนสะกดรอย ดูว่ารอยไปไหน" },
    },
    [1285] = { -- Daelin's Men
        title = { "12:296622145:995559973", "คนของ Daelin" },
        objective = { "73:137980769:2071962933", "นำข้อมูล Reethe กลับไปให้ Captain Garran Vimes ที่ Theramore" },
        description = { "285:1651341310:334358801", "Reddon...Redpath...อา นี่ Lieutenant Paval Reethe\n\nเข้ายาม Theramore พร้อมทหารใหม่ส่วนใหญ่ที่ข้ามทะเลกับ Lady Proudmoore สมัครนาวิกโยธิน Kul Tiras อายุสิบหก รับใช้ดี เลื่อนยศ...\n\nระบุว่าสูญหาย" },
        completion = { "233:844621248:571742990", "สูญหายหรือ? วิธีสุภาพของ Tesoran ที่จะเรียกคนทรยศ\n\nคงเป็นคนโง่ภักดี Admiral Daelin จนมืดบอด เลยทรยศ ช่างย้อนแย้งน่าขัน พวกหนีทัพกลับหาว่าเราทรยศ Alliance" },
    },
    [1286] = { -- The Deserters
        title = { "13:1513170000:740732432", "ผู้หนีทัพ" },
        objective = { "85:1531875577:1000113095", "สอบถามข้อมูล Reethe จาก Balos Jacken และพวกหนีทัพใน Dustwallow Marsh" },
        description = { "450:1303843871:1054968387 N 33:878199809:491989125", "รักษาที่มั่นในบึงยาก แต่ความมุ่งมั่นทำให้คงหอสังเกตการณ์หลายแห่ง\n\nข่าวล่าสุดบอกพวกหนีทัพยึดหอร้างที่ Lost Point ตะวันออกเฉียงใต้โรงเตี๊ยม\n\nหัวหน้าชื่อ Jacken ลองเค้นข้อมูล\n\nระวัง {name} เขาอาจไม่ยอมพูดง่าย" },
        completion = { "67:1552939502:1610758500", "Vimes ส่งมาหรือ? ทำงานสกปรกเองไม่ได้สินะ..." },
    },
    [1287] = { -- The Deserters
        title = { "13:1513170000:740732432", "ผู้หนีทัพ" },
        objective = { "58:1822500224:1202656093", "คุยกับ Captain Garran Vimes ที่ Theramore เรื่อง Reethe" },
        description = { "368:2016328276:1201523011", "Reethe? เจ้าขลาดนั่น?\n\nเราไล่ออกจากค่าย เพราะยืนกรานปล้นเสบียงออกร์ Brackenwall เราน้อยเกินสู้สัตว์โง่พวกนั้น\n\nเขาล้ำเส้นบ่อยเกิน จึงปล่อยเอาตัวรอดเอง\n\nข้าช่วยแล้ว...ช่วยเราบ้าง ลืมว่าเจอกันได้ไหม?" },
        completion = { "198:1852386150:1008754473", "จะส่ง Lieutenant Caldwell จัดการผู้หนีทัพ Lost Point และสั่งหา Reethe บึงไม่ใหญ่ไร้รอยจนหาไม่พบหรอก" },
    },
    [1319] = { -- The Black Shield
        title = { "16:1993554830:1930164564", "โล่ดำ" },
        objective = { "63:344816194:1890494287", "นำ Blackened Iron Shield ให้ Caz Twosprocket ดูที่ Theramore" },
        description = { "35:186061039:227592668 N 177:152878171:371068792", "ขอโทษที่ช่วยไม่มาก {name} แต่แนะนำคนได้ Caz Twosprocket ช่างตีเหล็กเก่งที่สุดคนหนึ่ง ทำงานเตาหลอมโรงตีเหล็ก\n\nนำโล่ให้เขาดูว่าบอกอะไรได้" },
        progress = { "28:2136313063:1524504051", "มีอะไรให้ดูหรือ?" },
        completion = { "161:1720171477:1007493588", "อืม...เหล็กน่าสนใจ ไม่ใช่งานช่างที่ข้ารู้จักฝั่งนี้แน่ และไม่ใช่ข้าทำ" },
        required = { [5919] = { "21:69126555:1056793148", "โล่เหล็กดำคล้ำ" } },
        steps = { { "21:69126555:1056793148", "โล่เหล็กดำคล้ำ" } },
    },
    [1320] = { -- The Black Shield
        title = { "16:1993554830:1930164564", "โล่ดำ" },
        objective = { "45:433086445:334477184", "คุยกับ Captain Garran Vimes ที่ Theramore" },
        description = { "252:217182727:344301624", "อา เกือบพลาด...สายหนังหลังโล่คงไหม้หลุด แต่ดูเหมือนทำให้คนใหญ่ ข้าเดาว่าทอเรน\n\nบอกได้เท่านี้ แจ้ง Captain Vimes ว่าเสียใจช่วยมากกว่านี้ไม่ได้" },
        completion = { "198:1885040916:389622061", "ข้อมูลยังน้อย แต่ต้องจำไว้ หวังเบาะแสอื่นจะเข้าที่ บอกภาพเหตุการณ์ชัดขึ้น" },
    },
    [1321] = { -- The Black Shield
        title = { "16:1993554830:1930164564", "โล่ดำ" },
        objective = { "64:1611721368:556699515", "นำ Blackened Iron Shield ให้ Do'gol ดูที่ Brackenwall Village" },
        description = { "196:1300744720:1547341441", "อืม...ไม่เห็นผิดปกติ ให้ Do'gol ช่างตีเหล็กดู เผื่อบอกเพิ่มได้ แต่ไม่ควรหวังมาก..." },
        progress = { "18:238494143:1271901768 C 1:63:63", "มีอะไรให้ข้าหรือ {class}?" },
        completion = { "103:1072218219:1371603776 N 23:1509918782:1420487725", "โล่ดี แกร่ง หนัก ดี แต่ Do'gol ไม่ต้องการ ข้าทำโล่ ไม่ซื้อ {name}\n\nเจ้าควรรู้" },
        required = { [5919] = { "21:69126555:1056793148", "โล่เหล็กดำคล้ำ" } },
        steps = { { "21:69126555:1056793148", "โล่เหล็กดำคล้ำ" } },
    },
    [1322] = { -- The Black Shield
        title = { "16:1993554830:1930164564", "โล่ดำ" },
        objective = { "62:1074831174:711816079", "หา Acidic Venom Sacs 6 ถุง ให้ Do'gol ที่ Brackenwall Village" },
        description = { "248:1797011736:1997163861", "อืม มีตัวหนังสือขอบโล่ แต่อ่านยากเพราะของไหม้\n\nต้องใช้กรดทำชัด พิษแมงมุม Darkfang ในบึงใช้ได้ เอาถุงมาจะล้างให้" },
        progress = { "39:1552777313:1724216374", "ได้ถุงจากแมงมุมไหม?" },
        completion = { "99:1621997753:1790132054 N 54:33005245:1112834987", "ข้าไม่ชอบแมงมุมใหญ่จนเอาก้นนั่งทับบี้ไม่ได้\n\nขอบใจที่หา {name} ทีนี้ฉีกแล้วเทใส่โล่..." },
        required = { [5959] = { "16:418231752:626843814", "ถุงพิษฤทธิ์เป็นกรด" } },
        steps = { { "16:418231752:626843814", "ถุงพิษฤทธิ์เป็นกรด" } },
    },
    [1323] = { -- The Black Shield
        title = { "16:1993554830:1930164564", "โล่ดำ" },
        objective = { "38:116857984:1593793751", "คุยกับ Krog ที่ Brackenwall Village" },
        description = { "214:1670554272:983834863", "โอ้ คงเทกรดมากไป ขอขัดนิด...\n\nอืม อ่านยาก แต่เหมือนชื่อ Mosarn ไม่เคยได้ยิน บางที Krog รู้ เขารู้จักคนมาก" },
        completion = { "171:301983869:15132480", "Mosarn? คุ้น...นึกไม่ออก บางทีนึกได้ภายหลัง\n\nคงไม่สำคัญ โล่มาจากไหนก็ได้ ไม่ต้องมีความหมาย..." },
    },
    [1450] = { -- Gryphon Master Talonaxe
        title = { "23:849068897:1407875249", "Gryphon Master Talonaxe" },
        objective = { "64:1358839618:1602580671", "คุยกับ Gryphon Master Talonaxe ใน Aerie Peak Aviary" },
        description = { { "99:587375379:1756251090 C 324:1763003446:1260565384", "100:1411580790:529247641 C 324:1763003446:1260565384" }, "เป็นคนวิ่งธุระอย่างโก้ให้ตาแก่ Explorers' League หรือ?\n\nฟัง {class} ไม่รู้เพื่อนแก่เจ้าไปบินกับใครทางใต้ใน Azeroth ข้าดูเหมือน Gryphon Master Talonaxe หรือ? เหมือนหรือ?\n\nสนใจงานบินก็ถามเขา หากเห็นอ้อยอิ่งนานกว่านี้ จะให้งานจริง\n\nไปได้แล้ว" },
        completion = { "427:608803387:1244831607", "อา จำได้ ส่งคนขี่กริฟฟอนช่วย Brohann Caskbelly\n\nข้าเอ็นดู Explorers' League เสมอ พ่อช่วยทีมขุดแรกที่พบ Uldaman จริง ๆ\n\nส่งคนที่คิดว่าดีที่สุดตอนนั้นไป ชื่อ Rhapsody Shindigger\n\nขี่เก่งเหลือเกิน! จนกระทั่ง..." },
    },
    [1451] = { -- Rhapsody Shindigger
        title = { "19:1588577130:1570779168", "Rhapsody Shindigger" },
        objective = { "48:1797879567:271255661", "ตามหา Rhapsody Shindigger ที่ The Hinterlands" },
        description = { "502:1429988018:112569264", "Rhapsody ชอบเหล้ามาก อย่าเข้าใจผิด คนแคระที่โรงกริฟฟอนก็รักเอลดีเมื่อถึงเวลา\n\nแต่ Shindigger ติดสุราเหมือนกริฟฟอนชอบฟ้า เสียดายบัดซบ ไม่มีใครบินเท่าเขา\n\nเริ่มปัญหาตอนเดินเซกลับภารกิจกับ Brohann เพื่อนเจ้า จากนั้นแย่เร็ว ต้องเลิกจ้าง\n\nข่าวล่าสุดตั้งค่ายต้มเหล้าตะวันออก..." },
        completion = { "179:1357873955:509279256", "ฮึก!\n\nข้ามองตรง ๆ แต่เจ้ากระเด้งขึ้นลง ทำเวียนหัว โฮะโฮ่!\n\nฮึก!\n\nโอ้ รู้สึกไหม? พื้นสั่น สหาย ข้าต้องดื่ม\n\nฮึก!" },
    },
    [1452] = { -- Rhapsody's Kalimdor Kocktail
        title = { "28:1612298746:1608975101", "ค็อกเทล Kalimdor ของ Rhapsody" },
        objective = { "116:337316622:1103363103", "Rhapsody Shindigger ที่ The Hinterlands ต้องการ Roc Gizzards 3 ชิ้น, Groddoc Livers 3 ชิ้น และ Ironfur Livers 3 ชิ้น" },
        description = { "493:1945631094:1107497298", "ฮึก!\n\nBrohann คนบ้าส่งหรือ? ผจญภัยกันหนัก...ฮึก!\n\nอยากให้เล่าเหตุในบึง ต้องมีเหล้าแรง ไม่ใช่ภาพสวย ฮึก!\n\nเอาอย่างนี้...นำของทำ Kalimdor Kocktail มา แล้วจะเล่าหมด\n\nต้องกึ๋น Roc จาก Tanaris...ตับ Groddoc กับ Ironfur จาก Feralas...\n\nค็อกเทลแรง ๆ จะทำข้าพูด!" },
        progress = { "348:1267955677:165689312", "เคยดื่ม Rhapsody Malt ไหม? หนึ่งในที่ข้าต้มดีที่สุด ฮึก!\n\nแต่จะย้อนฝันร้ายเที่ยวบิน...ฮึก...เหนือบึง ต้องแรงกว่านั้น ฮึก!\n\nได้กึ๋นกับตับที่ต้องเติมความแรงให้ Kalimdor Kocktail หรือยัง?\n\nฮึก!" },
        completion = { "398:326679165:1951266631", "เห็นว่าเอาของมาได้ไม่ยาก! คงอยู่ Kalimdor ไกลนั้นนานทีเดียว\n\nใช้ครู่สกัดของจากกึ๋นกับตับ ฮึก!\n\nแล้วกลั่นเหล้าแรง เล่าสิ่งที่อยากรู้ได้\n\nฮึก!\n\nคิดถึงบึงก็สั่นแล้ว\n\nฮึก!\n\nขอทำเครื่องดื่มเร็ว ๆ" },
        required = { [6257] = { "11:376232648:2124236041", "กระเพาะบดของนกร็อก" }, [6258] = { "13:1541791425:1685548854", "ตับของ Ironfur" }, [6259] = { "13:374333798:678489502", "ตับของ Groddoc" } },
        steps = { { "11:376232648:2124236041", "กระเพาะบดของนกร็อก" }, { "13:1541791425:1685548854", "ตับของ Ironfur" }, { "13:374333798:678489502", "ตับของ Groddoc" } },
    },
    [1469] = { -- Rhapsody's Tale
        title = { "15:295156056:1438411419", "เรื่องเล่าของ Rhapsody" },
        objective = { "68:1296210112:634078231", "นำ Atal'ai Tablet Fragment ไปให้ Brohann Caskbelly ที่ Stormwind" },
        description = { "502:1148289990:1982015471", "ก่อนบิน ข้าดื่มสเตาต์ทั้งถัง ฮึก!\n\nช่างเป็นเที่ยวบิน! ว่อนโดย Brohann ตาม ไม่เห็นวิหาร ฮึก!\n\nไม่เห็นจนเมาเกินตกจากพาหนะ พุ่งลงน้ำถูกดูด พบตัวเองล้อมโทรลล์น่าขนลุก ว่ายหนีเร็วเลย! ยังเอาของที่ระลึกนี้มา นี่ นำให้ Brohann บอกว่าวิหารเขาอยู่ข้างล่างจริง ฮึก!" },
        progress = { "32:1672363834:1035586326 N 174:1326462260:1856356915", "กลับมาเสียที {name} ไม่คุยกันนาน คิดว่าอาจลืมงานข้า\n\nพบนักขี่กริฟฟอนเจ้าเล่ห์ไหม? มีอะไรรายงาน?" },
        completion = { "230:1988228718:6796193", "Rhapsody Shindigger! ใช่ ทำไมลืมชื่อนี้?\n\nรู้วิหารจมมาตลอดหรือ? น่าจะช่วยเจ้าไม่ต้องเดินมาก\n\nแต่วัตถุ Atal'ai นี้! พบครั้งใหญ่!" },
        required = { [6287] = { "23:637453062:5822401", "เศษแผ่นจารึก Atal'ai" } },
        steps = { { "23:637453062:5822401", "เศษแผ่นจารึก Atal'ai" } },
    },
    [2742] = { -- Rin'ji is Trapped!
        title = { "18:1607733101:2146635444", "Rin'ji ถูกขัง!" },
        objective = { "106:438448821:2123621938", "คุ้มกัน Rin'ji ออกจาก Quel'Danil Lodge แล้วหาความลับที่ซ่อนไว้ ณ Overlook Cliffs ทางตะวันออก" },
        description = { { "4:1228872774:163611696 R 77:875273963:1635464848 R 98:1734521446:1433949725 R 92:108862158:1655947510", "4:1228872774:163611696 R 77:875273963:1635464848 R 98:1734521446:1433949725 R 93:265331222:555552054" }, "เฮ้ {race}!\n\nRin'ji ทำขวานหาย ถูกจับ! ช่วยหนี ข้ารู้ว่า {race} อย่างเจ้าไม่ชอบเผ่าข้า แต่ Rin'ji วิงวอน ต้องออก!\n\nมีของให้ {race} ใจดีหากช่วยหนี...\n\nRin'ji ซ่อนความลับที่ Overlook Cliffs" },
        progress = { "17:186899644:50616022", "Rin'ji กลัว!" },
        completion = { "143:1708958066:314895908", "จารึกโทรลล์นี้คงเป็น “ความลับ” ที่ Rin'ji พูด\n\nเต็มด้วยเครื่องหมายประหลาด เจ้าอ่านไม่ออก" },
    },
    [2782] = { -- Rin'ji's Secret
        title = { "15:700706660:338760711", "ความลับของ Rin'ji" },
        objective = { "185:780261453:1921578629", "Oran Snakewrithe นักปราชญ์มีชื่อเรื่องโทรลล์ Witherbark อาจถอดจารึกได้ นางอาศัยใน Magic Quarter ของ Undercity" },
        description = { "318:1122959043:608165727", "จารึกเต็มเครื่องหมายโทรลล์ Witherbark ความลับ Rin'ji เป็นปริศนาจริง...\n\nอาจได้ของล้ำค่า แต่ตรงข้ามก็เป็นไปได้ โทรลล์ Witherbark ลำบากคงทำทุกอย่างให้พ้นปัญหา..." },
        progress = { "24:79950249:168911543", "เอาล่ะ นี่อะไร?" },
        completion = { "57:1305624474:1243850890 N 1:63:63", "จารึกนี้...แปลกนัก...พบที่ไหน {name}?" },
        required = { [8724] = { "15:700706660:338760711", "ความลับของ Rin'ji" } },
        steps = { { "15:700706660:338760711", "ความลับของ Rin'ji" } },
    },
    [2877] = { -- Skulk Rock Clean-up
        title = { "19:367301107:1985107820", "เก็บกวาด Skulk Rock" },
        objective = { "101:248467292:1543923957", "ฆ่า Green Sludges 10 ตัว และ Jade Oozes 10 ตัว แล้วรายงาน Fraggar Thundermantle ที่ Aerie Peak" },
        description = { "492:1880599824:2111400992", "Wildhammer จำอดีตยิ่งกว่าพี่น้อง Ironforge อยากเป็นมิตรต้องลงมือให้เรา!\n\nHorde ทิ้งฐานรอบ Skulk Rock ตอนนี้โคลนกับเมือกชั่วเต็ม เรามีแผนใช้พื้นที่ แต่ต้องหน่วยกวาดเปิดช่องก่อน\n\nนั่นงานเจ้า เจ้าสดใส! ไปฆ่าโคลนเขียวสิบกับเมือกหยกสิบ แล้วรายงานข้าที่นี่ ไปได้!" },
        progress = { "49:549027711:888840806 R 101:1714655959:2100129745", "อย่าต่อรองงาน {race}! หากเทพอยากให้เมือกตาย คงเสกปาฏิหาริย์เสร็จแล้ว ใช่ไหม?!" },
        completion = { "56:1494838122:2133185001 C 332:1288015284:229587130", "ดูสิ ช่วย Wildhammer แล้ว! เจ้าเป็น {class} ลงมือทำ และที่นี่เราเคารพการกระทำ\n\nงานกวาดสำคัญกว่าที่คิด ลดเมือกโคลนแล้วเราขยายอิทธิพลเร็วได้ นี่ รับนอกจากมิตรใหม่ที่ Aerie Peak!" },
        objectiveLabels = {
            monster = { ["Green Sludge slain"] = "ปราบ สไลม์สีเขียว", ["Jade Ooze slain"] = "ปราบ อูซสีหยก" },
        },
    },
    [2880] = { -- Troll Necklace Bounty
        title = { "21:401115096:1084641938", "ค่าหัวสร้อยโทรลล์" },
        objective = { "70:625772416:1400337020", "นำ Troll Tribal Necklaces 5 เส้น ไปให้ Fraggar Thundermantle ที่ Aerie Peak" },
        description = { "19:1777548394:816211504 R 469:600408685:799200488", "เข้าใจให้ชัด {race} เราไม่ใช่ส่วน Alliance! Wildhammer อิสระ ใช้ผลงานพิสูจน์คุณค่า ไม่ใช่พล่ามเสริมท่าทีไม่ยอมทำอะไร!\n\nอยากมีมิตรต้องพิสูจน์ก่อน โทรลล์ชั่วที่เต็มเนิน Hinterlands บางตัวถือสร้อยเผ่า นำห้าเส้นมา เราจะนับเป็นก้าวถูกทาง" },
        progress = { "202:66627851:82472626", "ต้องการสร้อยเผ่าโทรลล์ห้าเส้น หากต้องอธิบายอีก ฆ่าสักตัวก็มีโอกาสดีได้สร้อย!\n\nพิสูจน์คุณค่าต่อ Wildhammer!" },
        completion = { "218:877339043:1022409324", "อย่างนี้สิ! สร้อยพิสูจน์ว่ายอมลงมือ Wildhammer ให้ค่ากับคนที่เราคบเช่นนั้น\n\nทำต่อ แล้วเราจะยิ่งชอบเจ้า" },
        required = { [9259] = { "21:2054634500:1185105558", "สร้อยคอชนเผ่าโทรลล์" } },
        steps = { { "21:2054634500:1185105558", "สร้อยคอชนเผ่าโทรลล์" } },
    },
    [2881] = { -- Troll Necklace Bounty
        title = { "21:401115096:1084641938", "ค่าหัวสร้อยโทรลล์" },
        progress = { "340:1405769676:1362716821 N 1:46:46", "ทำแล้ว แต่เรายังรับสร้อยเผ่าโทรลล์ที่พบและยอมส่ง ส่งให้ข้าต่อก็เพิ่มฐานะในหมู่ Wildhammer หากยอมสู้เพื่อเรา เราก็ยอมสู้เพื่อเจ้า!\n\nต้องห้าเส้นจึงนับ {name}" },
        completion = { "218:877339043:1022409324", "อย่างนี้สิ! สร้อยพิสูจน์ว่ายอมลงมือ Wildhammer ให้ค่ากับคนที่เราคบเช่นนั้น\n\nทำต่อ แล้วเราจะยิ่งชอบเจ้า" },
        description = { "340:1405769676:1362716821 N 1:46:46", "ทำแล้ว แต่เรายังรับสร้อยเผ่าโทรลล์ที่พบและยอมส่ง ส่งให้ข้าต่อก็เพิ่มฐานะในหมู่ Wildhammer หากยอมสู้เพื่อเรา เราก็ยอมสู้เพื่อเจ้า!\n\nต้องห้าเส้นจึงนับ {name}" },
        required = { [9259] = { "21:2054634500:1185105558", "สร้อยคอชนเผ่าโทรลล์" } },
        objectiveLabels = {
            item = { ["Troll Tribal Necklace"] = "สร้อยคอชนเผ่าโทรลล์" },
        },
    },
    [2932] = { -- Grim Message
        title = { "12:751483066:870700032", "สารมรณะ" },
        objective = { "175:835559154:1309686808", "เก็บ Witherbark Skulls ใส่ Nimboya's Pike วาง Nimboya's Laden Pike ที่หมู่บ้าน Witherbark แห่งหนึ่งใน Hinterlands แล้วกลับไปหา Nimboya ที่ Stranglethorn" },
        description = { "476:1032756144:790301138", "โทรลล์ Witherbark เคยร่วม Horde แต่ทรยศ Thrall...ต้องลงโทษ!\n\nเอาหอกข้าไป Hinterlands ไกลเหนือ อยู่ตะวันออกเฉียงเหนือ Tarren Mill หมู่บ้าน Forsaken พันธมิตรเรา\n\nเข้าแล้วล่า Witherbark เก็บกะโหลก ปักหอกที่หมู่บ้านเล็ก Hiri'watha หรือ Zun'watha\n\nให้เห็นว่าการชั่วมีผลตาม!" },
        progress = { "32:1095763471:1267098526 N 1:46:46", "งานยังไม่เสร็จ {name}" },
        completion = { "107:324998138:601079767", "ข่าวผลงานมาถึง น่าสยองแต่มีเกียรติ หวังว่า Witherbark จะฟังสารเจ้า" },
        objectiveLabels = {
            event = { ["Place the grim message."] = "วางสารข่มขู่" },
        },
    },
    [2933] = { -- Venom Bottles
        title = { "13:1683130752:2084808018", "ขวดพิษ" },
        objective = { "53:1059013904:1595811056", "นำ Venom Bottle ไปให้เภสัชกรที่ Tarren Mill" },
        description = { "200:1168128799:1846741180", "ขวดมีพิษเขียวร้ายกาจ\n\nดูจากจำนวนในหมู่บ้าน Witherbark ต้องให้ค่ามาก บางทีเภสัชกร Tarren Mill ใกล้นี่อยากได้ตัวอย่าง" },
        progress = { "14:2069817520:1595955245 C 98:1234391858:692752514", "สวัสดี {class} ใจดี วันยาว ไม่มีทดลองใดสำเร็จ...หวังนำข่าวดีมา" },
        completion = { "110:782268209:1166059573", "อา นี่อะไร? ดูเป็นพิษ...คงจากสัตว์ตระกูลแมง แล้วเอามาจากไหน?" },
        required = { [9321] = { "12:1928421671:606062737", "ขวดบรรจุพิษ" } },
        steps = { { "12:1928421671:606062737", "ขวดบรรจุพิษ" } },
    },
    [2934] = { -- Undamaged Venom Sac
        title = { "19:1851570738:878930154", "ถุงพิษไร้ความเสียหาย" },
        objective = { "64:1567943258:532860327", "นำ Undamaged Venom Sac ไปให้ Apothecary Lydon ที่ Tarren Mill" },
        description = { "273:1431102999:5427701 N 54:673468714:1411389731", "ต้องตัวอย่างสดของพิษนั้น แมงมุมต้นทางต้องอยู่ Hinterlands ล่าจนพบถุงไม่เสียหายแล้วนำมา พบมากใกล้เมืองโทรลล์ Shadra'Alor\n\nอย่าช้า {name} ส่งถึงต้องยังสด" },
        progress = { "37:940529735:1051801158 N 133:2021787901:1062138846", "มีถุงพิษสมบูรณ์ไหม {name}? อยากทดลองพิษสด และสั่งสัตว์ตัวเล็กน่ารักมากมาทดลองแล้ว!" },
        completion = { "75:1543720048:830779139", "โอ้ วิเศษ! พิษสดดี แน่ใจว่าร้ายแรง ขอบคุณ!" },
        required = { [9322] = { "19:1851570738:878930154", "ถุงพิษสภาพสมบูรณ์" } },
        steps = { { "19:1851570738:878930154", "ถุงพิษสภาพสมบูรณ์" } },
    },
    [2935] = { -- Consult Master Gadrin
        title = { "21:2073938197:1936690383", "ปรึกษา Master Gadrin" },
        objective = { "44:1267587516:747756678", "คุยกับ Master Gadrin ที่ Sen'jin Village" },
        description = { "393:277582719:1952506193", "พิษ broodguards ไม่แรงเท่าที่นำมาแรก ต้องมาจากแมงมุมอื่น\n\nต้องการตัวอย่างสดนั้น หาต้นทางต้องถามโทรลล์ที่รู้ Witherbark ดี Master Gadrin ใน Sen'jin Village ไป Durotar คุยเขา หากโชคดีจะรู้ว่าเอาพิษจากไหน" },
        completion = { "136:1581763109:824491065", "อา อยากได้พิษสดจากแมงมุม Witherbark ใช่ไหม? นั่งก่อน...เจ้าคงไม่ชอบสิ่งที่จะเล่า" },
    },
    [2937] = { -- Summoning Shadra
        title = { "16:2098825257:287216859", "เรียก Shadra" },
        objective = { "99:2059455673:150241925", "ปราบ Shadra ที่แท่นบูชา Shadra'Alor แล้วนำพิษไปให้ Apothecary Lydon ที่ Tarren Mill" },
        description = { "153:1743675450:1697757155", "นำแผ่นหนังของเขาไปอ่านที่แท่น Shadra'Alor ลึกในเขต Witherbark ของ Hinterlands จะเรียก Shadra เทพแมงมุม" },
        progress = { "22:454795544:1476588516", "ได้พิษไหม?" },
        completion = { "18:200355418:250862354", "เยี่ยม ได้แล้ว!" },
        required = { [9324] = { "14:1111439960:1181775301", "พิษของ Shadra" } },
        objectiveLabels = {
            item = { ["Shadra's Venom"] = "พิษของ Shadra" },
        },
    },
    [2938] = { -- Venom to the Undercity
        title = { "22:310848820:1365900296", "ส่งพิษสู่ Undercity" },
        objective = { "71:1787366779:508562062", "นำ Faranell's Parcel ไปให้ Master Apothecary Faranell ที่ Undercity" },
        description = { "499:578086482:1483310539", "พิษเทพแมงมุม Witherbark เป็นของสำคัญ! ข้าฆ่ากระต่ายเกือบสองโหลด้วยหยดเดียว แน่นอน บางตัวเด็กเล็กพออยู่ฝ่ามือ จึงคงต้านพิษต่ำ แต่ปฏิเสธไม่ได้ว่าแรง!\n\nอยากส่งตัวอย่างให้หัวหน้า Apothecary Faranell ที่ Apothecarium ใน Undercity มั่นใจว่าอยากทดลองเอง" },
        progress = { "30:399609125:1756167898 N 27:1649044264:364049139", "ได้ข่าวว่าจะมา {name} มีห่อให้ข้า?" },
        completion = { "195:367830357:519638181 N 61:877110731:82299039", "อา ดีมาก Lydon บอกว่าพิษในห่อแรงที่สุดที่เคยพบ กำลังหาวิธีใช้ใหม่\n\nหวังว่าพบหลายทาง\n\nขอบคุณ {name} ผลงานต่อ Royal Apothecary Society ปฏิเสธไม่ได้" },
    },
    [2988] = { -- Witherbark Cages
        title = { "16:2036171748:81552785", "กรง Witherbark" },
        objective = { "87:636562504:2139813144", "ตรวจกรงในหมู่บ้าน Witherbark ทั้งสอง แล้วกลับไปหา Gryphon Master Talonaxe" },
        description = { "274:964142447:1908036543", "ลูกกริฟฟอนแข็งแกร่งที่สุดเราหาย! Sharpbeak ทายาท Swiftwing หายขณะล่ากับพ่อแม่ไม่กี่วันก่อน เชื่อว่าโทรลล์จับ\n\nช่วยด้วย! ค้นกรงในหมู่บ้าน Witherbark สองแห่งว่ามีหรือไม่" },
        progress = { "29:2006812888:1970932845 N 25:908178409:152602560", "ค้นกรงหรือยัง {name}? ต้องพบ Sharpbeak!" },
        completion = { "203:980999290:323891819", "Sharpbeak ไม่อยู่หรือ? อืม...ข่าวร้าย กริฟฟอนนั้นมีชะตานำรุ่นต่อไป หากเสีย กำลังกับขวัญฝูงเราจะกระทบหนัก" },
        steps = { { "16:1354286963:981459432", "ตรวจกรงแรก" }, { "17:734658464:1272698975", "ตรวจกรงที่สอง" }, { "16:413965935:296342874", "ตรวจกรงที่สาม" } },
    },
    [2989] = { -- The Altar of Zul
        title = { "16:326807718:2005171465", "แท่นบูชา Zul" },
        objective = { "74:715735290:330528290", "ตรวจยอด Altar of Zul แล้วกลับไปหา Gryphon Master Talonaxe" },
        description = { "186:294751368:2088218630", "Sharpbeak ไม่อยู่กับ Witherbark บางที Vilebranch จับ ไป Altar of Zul ขอบตะวันตกเขต Vilebranch หาลูกกริฟฟอน" },
        progress = { "7:2044825444:644190917 N 92:1297836423:1523993888", "รีบ {name}! หาก Vilebranch มี Sharpbeak ใครรู้ว่าทำอะไรอยู่!" },
        completion = { "261:1185553645:1670251029", "ไม่อยู่หรือ? ข่าวร้าย แต่ก็ดี...\n\nดีที่ไม่อยู่แท่น Zul เพราะ Vilebranch ขึ้นชื่อบูชายัญ\n\nขอบใจที่ช่วยมาก แต่เกรงว่ามีงานใหญ่กว่าอีก" },
    },
    [2990] = { -- Thadius Grimshade
        title = { "17:1064111511:1135403906", "Thadius Grimshade" },
        objective = { "68:304262154:737054340", "นำ Sharpbeak's Feather ไปให้ Thadius Grimshade ที่ Blasted Lands" },
        description = { "378:455966267:1993728220 N 84:1505962705:133108573", "นำขนให้ Thadius Grimshade ผู้พยากรณ์ เขาจาก Aerie Peak หลายปีเพื่อความรู้มืด แต่ใจยัง Wildhammer!\n\nบางทีพรสวรรค์ช่วยหา Sharpbeak\n\nขนมาจากรังที่ลูกกริฟฟอนนอน ให้ Thadius แล้วหากโชคดี เวทพยากรณ์จะพบ\n\nโชคดี {name} พบที่หอจอมเวท Nethergarde Keep ใน Blasted Lands" },
        progress = { "N 26:1362785556:375893185", "{name} นำของขวัญมาหรือ?" },
        completion = { "173:1178962518:1747805173 C 3:3050122:795478", "อา ขนกริฟฟอนชั้นดี ผู้ถูกกำหนดให้ยิ่งใหญ่...หากโตได้ไร้ความเสียหาย\n\nอยากหาหรือ? ฟังใกล้ ๆ {class} ผู้กล้า..." },
        required = { [9468] = { "19:1445377947:2137878592", "ขนนกของ Sharpbeak" } },
        steps = { { "19:1445377947:2137878592", "ขนนกของ Sharpbeak" } },
    },
    [2992] = { -- The Divination
        title = { "14:115270312:863539911", "การพยากรณ์" },
        objective = { "55:1578317670:827376638", "รอ Grimshade ทำพิธีพยากรณ์" },
        description = { "279:502613401:492063682", "เว้นที่ให้ทำพิธี ข้าจะหาเส้นเชื่อมขนกับเจ้าของ แล้วตามถึง Sharpbeak\n\nนั่นคือ...หากตามแผน หากไม่...หลับตาไว้ดีกว่า" },
        completion = { "81:1198680748:1748609886", "พิธีสำเร็จ เห็น Sharpbeak แล้ว บอกวิธีหาได้" },
        objectiveLabels = {
            event = { ["Wait for Grimshade to finish"] = "รอ Grimshade ทำงานให้เสร็จ" },
        },
    },
    [2993] = { -- Return to the Hinterlands
        title = { "25:1700106901:850811422", "กลับสู่ Hinterlands" },
        objective = { "35:1872087415:177288067", "คุยกับ Gryphon Master Talonaxe" },
        description = { "255:1140653299:1618174749 N 1:46:46", "Sharpbeak อยู่กรงสูงบนหน้าผายอด Jintha'Alor ใน Hinterlands กุญแจอยู่กับมหาปุโรหิตหญิง Vilebranch ชื่อ Vile Priestess Hexx\n\nนี่ ทำส่วนข้าแล้ว ขอให้โชคดีกับภารกิจ {name}" },
        completion = { "154:808394104:869163898", "คุย Grimshade แล้วหรือ? ว่าอย่างไร?\n\n...อะไรนะ? Vilebranch มี Sharpbeak? ทนไม่ได้! ต้องรวบรวมกำลังเอาคืน!" },
    },
    [2994] = { -- Saving Sharpbeak
        title = { "16:1282010912:232266990", "ช่วย Sharpbeak" },
        objective = { "110:1965117162:611294901", "ต่อสู้ขึ้นยอด Jintha'Alor ฆ่า Vile Priestess Hexx เอากุญแจกรง Sharpbeak แล้วช่วย Sharpbeak" },
        description = { "199:1961025200:16111691", "ต้องช่วย Sharpbeak!\n\nฝ่าไปยอด Jintha'Alor ใจกลาง Vilebranch เอากุญแจจาก Priestess Hexx แล้วหาและช่วย Sharpbeak!" },
        progress = { "15:1412624069:805053134", "ช่วย Sharpbeak!" },
        completion = { "241:910578343:876014172 N 90:308971594:1298754051", "Swiftwind กับ Keenclaw เพิ่งกลับพร้อมลูก เอาใจราวพ่อแม่มือใหม่ เห็นพร้อมหน้าอีกครั้ง แม้คนแคระแก่ก็ยังน้ำตาคลอ...\n\nตอบแทนไม่พอ {name} กริฟฟอน Aerie Peak กับผู้ขี่จะร้องชื่อเจ้าไปอีกนาน" },
    },
    [4787] = { -- The Ancient Egg
        title = { "15:1574619107:1383824941", "ไข่โบราณ" },
        objective = { "46:1861535730:1788907447", "นำ Ancient Egg ไปให้ Yeh'kinya ที่ Tanaris" },
        description = { "246:1947276487:1564012297 N 128:280768079:768473634", "คำพยากรณ์ Mosh'aru กล่าวถึงไข่โบราณ วัตถุจากยุคโทรลล์ครองจักรวรรดิใหญ่ มีพลังเก็บแก่น Hakkar อาจเป็นทางเดียวคุ้มโลกจากความชั่ว\n\nนำไข่มา {name} ว่าซ่อนลึก Jintha'Alor ใน Hinterlands ถ้ำหลังอัฒจันทร์ยอดเมือง" },
        progress = { "93:712947814:1570393715", "มีไข่โบราณหรือยัง? รู้สึกพลังใหญ่ขยับ กลัวเวลาเหลือน้อย" },
        completion = { "36:1574129386:1176271851 N 52:2076476885:1662764175", "อา ได้ไข่! ข้าคำนับ {name} กำลังกล้าจะถูกจำไปนาน" },
        required = { [12402] = { "11:574735662:634129142", "ไข่โบราณ" } },
        steps = { { "11:574735662:634129142", "ไข่โบราณ" } },
    },
    [6570] = { -- Emberstrife
        title = { "11:1511750412:594354764", "Emberstrife" },
        objective = { "153:1312221691:1348152157", "ไป Wyrmbog ใน Dustwallow Marsh หา Emberstrife's Den เข้าแล้วสวม Amulet of Draconic Subversion และคุยกับ Emberstrife" },
        description = { "450:651986627:483103854", "ข้าประสานเหรียญกับเวทสร้างคงภาพลวงภายในรัง Emberstrife\n\nเขาเป็นเดรคโบราณ อดีตผู้เฝ้าประตู Nefarian มีหน้าที่ทดสอบ dragonspawn ที่จะขึ้นเป็นยามชั้นสูงของ Onyxia\n\nไป Wyrmbog เข้ารัง สวมเครื่องราง แล้วตามชะตา!" },
        completion = { "112:1600421919:1955963907", "ทหารเก่งขาดจน Nefarian ส่งลูกมาหรือ? เจ้าไม่มีวันผ่านทดสอบ เจ้าตัวอ่อน" },
    },
    [6582] = { -- The Test of Skulls, Scryer
        title = { "26:2134589202:1086474502", "ทดสอบกะโหลก: Scryer" },
        objective = { "184:983007555:2072949958", "หาและฆ่า Scryer เดรคยอดนักรบฝูงมังกรน้ำเงิน เอากะโหลกจากศพคืน Emberstrife\n\nเจ้ารู้ว่าพบ Scryer ได้ใน Winterspring" },
        description = { "422:1940045846:354575810", "เราคือลูก Deathwing อำนาจเหนือ Aspect ต่ำกว่าต้องคงไว้\n\nหากคู่ควรเลื่อนขั้น ฝูงด้อยจะเหี่ยวต่อหน้าเจ้า\n\nหายอดนักรบ ทำลายในนามพระบิดา!\n\nไป Winterspring ตามเดรคน้ำเงิน Scryer บดมันกับฝูงน้ำเงินที่ขวาง ฉีกกะโหลกคืนข้า" },
        progress = { "21:1984578909:1056445028", "<Emberstrife ขู่ฟ่อ>" },
        completion = { "28:254974488:2020708102", "สำเร็จหนึ่งในหลายอย่าง..." },
        required = { [16869] = { "19:1510449649:1585525390", "กะโหลกของ Scryer" } },
        objectiveLabels = {
            item = { ["The Skull of Scryer"] = "กะโหลกของ Scryer" },
        },
    },
    [6583] = { -- The Test of Skulls, Somnus
        title = { "26:711547448:314079167", "ทดสอบกะโหลก: Somnus" },
        objective = { "100:1839105797:282756156", "ทำลาย Somnus เดรคยอดนักรบฝูงเขียว เอากะโหลกคืน Emberstrife" },
        description = { "388:481206945:1887932341", "เช่นพระบิดาบด Aspect เราต้องนำความโกลาหลทำลายลูกพวกมัน\n\nทดสอบฝีมือกับผู้ฝันไร้นิทรา ลูกฝูงเขียว\n\nไป Swamp of Sorrows หา Somnus ปล่อยความชัง ครอบงำแมลง...คืนกะโหลกให้ข้า..." },
        progress = { "98:2060876366:135148116", "อย่ากลับจนชุ่มเลือดศัตรูและดื่มความทุกข์พวกมัน" },
        completion = { "19:1143080967:1496268364", "สำเร็จอีกหนึ่ง..." },
        required = { [16870] = { "19:87407895:813130055", "กะโหลกของ Somnus" } },
        objectiveLabels = {
            item = { ["The Skull of Somnus"] = "กะโหลกของ Somnus" },
        },
    },
    [6584] = { -- The Test of Skulls, Chronalis
        title = { "29:1688486942:204357155", "ทดสอบกะโหลก: Chronalis" },
        objective = { "132:1950478329:259362491", "Chronalis บุตร Nozdormu เฝ้า Caverns of Time ในทะเลทราย Tanaris ทำลายแล้วนำกะโหลกคืน Emberstrife" },
        description = { "337:87664016:1597279803", "ผู้เฝ้าเวลา ลูก Nozdormu เจ้าแห่งศตวรรษ...\n\nสามตนเฝ้า Caverns of Time แต่มีหนึ่งเดียวที่ฝูงดำสนใจ Time Shifter ชื่อ Chronalis เดรคโปรด Nozdormu\n\nโจมตีมันให้แม้ทรายเวลานิ่งเฉยยังร้องไห้ เอากะโหลกคืน" },
        progress = { "45:2111798257:1587847571", "ย้อนแย้งนัก ตัวอ่อน เวลาสำคัญยิ่ง..." },
        completion = { "27:448860523:678053250", "ยังเหลือผู้ที่เกลียดที่สุด..." },
        required = { [16871] = { "22:736820398:2141913493", "กะโหลกของ Chronalis" } },
        objectiveLabels = {
            item = { ["The Skull of Chronalis"] = "กะโหลกของ Chronalis" },
        },
    },
    [6585] = { -- The Test of Skulls, Axtroz
        title = { "26:553916056:39297778", "ทดสอบกะโหลก: Axtroz" },
        objective = { "142:364182819:530486860", "เดินทางไป Grim Batol ตามหา Axtroz เดรคยอดนักรบฝูงแดง ทำลาย เอากะโหลกคืน Emberstrife" },
        description = { "380:157101944:972481969", "เหนือภูเขา Grim Batol พระบิดาโหมใส่กำลังรวม Aspect การขลาดของผู้ทรยศ Alexstrasza ซื้อเวลาให้คนอื่นหนีโทสะ\n\nช่างน่าอาย...\n\nฝูงแดงเฝ้า Grim Batol แล้ว ต้องทำลายนายกอง Axtroz นำกะโหลกมา เพื่อพระบิดา เจ้าตัวอ่อน!" },
        progress = { "95:1972350895:818427903", "เปลี่ยนแปลง...ข้ารู้สึกในตัวเจ้า ผ่านครั้งนี้เหลือเพียงพิธี" },
        completion = { "156:1106428638:1772155635", "เคยสงสัยความทุ่มเท แต่เจ้าไม่หยุด ครอบงำศัตรู นำเกียรติฝูงเรา\n\nต้องเตรียมกะโหลกเพื่อเลื่อนขั้นแล้ว" },
        required = { [16872] = { "19:2077260150:538348666", "กะโหลกของ Axtroz" } },
        objectiveLabels = {
            item = { ["The Skull of Axtroz"] = "กะโหลกของ Axtroz" },
        },
    },
    [6601] = { -- Ascension...
        title = { "12:2133443695:1197457999", "เลื่อนขั้น..." },
        objective = { "306:933017713:1387061116", "ดูเหมือนการแสดงจบแล้ว เจ้ารู้ว่า Amulet of Draconic Subversion ที่ Myranda the Hag สร้างใช้ใน Blackrock Spire ไม่ได้ ควรหา Rexxar อธิบายปัญหา แสดง Dull Drakefire Amulet หวังเขารู้ขั้นต่อไป" },
        description = { "461:2037571204:321530274", "กะโหลกศัตรูสร้างเหรียญ เจ้ารู้จัก ใช่ไหม? คงเห็นผู้อาวุโสสวม\n\nรับไป กลับ Spire แสดงแก่ General Drakkisath เขาจะลงมนตร์สุดท้ายประสานกับวิญญาณเจ้า\n\nจะสวมเหรียญเสร็จเป็นตราเกียรติ แสดงการขึ้นชั้นลับที่สุดชั้นหนึ่ง ผู้พิทักษ์แม่ฝูง\n\nไป!" },
        progress = { "14:1198612194:301722915 N 1:33:33", "อย่าตกใจ {name}!" },
        completion = { "26:305815642:1141556795 N 116:1749811889:1116763553", "แค่คำพูดมังกร {name} ลมมากกว่าเนื้อหา พวกมันชอบโอ่อ่าก้าวร้าวอยู่แล้ว" },
    },
    [7541] = { -- Service to the Horde
        title = { "20:647491458:44585483", "รับใช้ Horde" },
        completion = { "158:1437428629:2075753522 N 42:1690335632:1916204327", "นักปราชญ์ต้องใช้เวลาศึกษาจี้ที่นำมา แต่เพื่อผลงานต่อ Horde ข้าขอมอบของแทนใจเล็กน้อย\n\nขอบคุณ {name} การกระทำสร้างเกียรติทั้งเจ้าและเรา" },
    },
    [7816] = { -- Gammerita, Mon!
        title = { "15:1937708972:1972254010", "Gammerita สหาย!" },
        objective = { "213:1392305381:1561244828", "Katoom the Angler ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้าฆ่า Gammerita แล้วนำ Katoom's Best Lure จากศพคืน\n\nKatoom บอกว่า Gammerita อยู่ชายฝั่งกับเต่าตัวอื่น" },
        description = { "305:1906566666:302375878", "เฮ้! มีเต่าต่างจากพวก มันคือ Gammerita หัวหน้า snapjaw เจ้าสัตว์เลื้อยคลานขโมยสกปรก\n\nสหาย มันงับเหยื่อดีที่สุดข้าจากสาย! ตั้งแต่นั้นปลาไม่ค่อยกิน\n\nหาแล้วเอาเหยื่อจากท้องคืน" },
        progress = { "19:1702746416:924816232", "ได้หรือยัง?" },
        completion = { "97:1066099997:1341942028", "สหาย! วิเศษ! ได้เหยื่อดีคืนกับเต่าน้อยลง ปลาจะกองพะเนิน" },
        required = { [19023] = { "18:2000186760:665174954", "เหยื่อตกปลาที่ดีที่สุดของ Katoom" } },
        objectiveLabels = {
            item = { ["Katoom's Best Lure"] = "เหยื่อตกปลาที่ดีที่สุดของ Katoom" },
        },
    },
    [7828] = { -- Stalking the Stalkers
        title = { "21:433210803:1819515983", "สะกดรอยผู้ซุ่มล่า" },
        objective = { "237:252783052:113478511", "Huntsman Markhor ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้าฆ่า Silvermane Stalkers 10 ตัว และ Silvermane Howlers 10 ตัว เสร็จแล้วกลับไปหา\n\nMarkhor บอกว่าหมาป่าซ่อนในป่า Hinterlands", variants = { { "237:593230728:823443104", "Huntsman Markhor ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้ากำจัด Silvermane Stalker 15 ตัวและ Silvermane Howler 15 ตัว เสร็จแล้วกลับไปหาเขา\n\nMarkhor บอกว่าฝูงหมาป่าซ่อนอยู่ตามป่าเขาใน Hinterlands" } } },
        description = { "72:14181016:1350350729 R 299:1666585962:1214502919", "โทรลล์กล้าหายมากในป่าโหด Hinterlands {race} หมาป่า Silvermane เป็นภัยใหญ่ต่อนักล่า ซ่อนรอในพุ่มและภูมิประเทศ แล้วโจมตีเมื่อมีโอกาส\n\nปล่อยดุร้ายไร้คนคุมไม่ได้!\n\nคิดอย่าง Silvermane สะกดรอยผู้ซุ่มล่า! ฆ่าทั้งหมด!" },
        progress = { "33:108743615:1370754106", "แสดงพลัง Revantusk ให้มันเห็น!" },
        completion = { "17:2049170433:170140679 R 48:1983548963:936990632", "ทำได้ดี {race} Revantusk ขอบคุณผลงานเจ้า" },
        objectiveLabels = {
            monster = { ["Silvermane Stalker slain"] = "ปราบ หมาป่าสะกดรอย Silvermane", ["Silvermane Howler slain"] = "ปราบ หมาป่าจอมหอน Silvermane" },
        },
    },
    [7829] = { -- Hunt the Savages
        title = { "16:611304350:1573356022", "ล่าพวกดุร้าย" },
        objective = { "217:1739454020:1892718305", "Huntsman Markhor ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้าฆ่า Savage Owlbeasts 20 ตัว เสร็จแล้วกลับไปหา\n\nMarkhor บอกว่าพวกมันอยู่ในป่า Hinterlands" },
        description = { "210:845739711:423558447 R 114:811805977:1842238879", "สัตว์ดุที่สุดกลุ่มหนึ่งใน Hinterlands คือ savage owlbeast นักรบ Revantusk ดีมากคนสิ้นเพราะกรงเล็บกับจะงอย\n\nฆ่าทุกตัวที่เห็น {race} กลับเมื่อทนหลั่งเลือดต่อไม่ไหว แล้วเราจะชั่งวัดตัดสินผลงาน" },
        progress = { "36:1009086602:1050977715 R 28:973611868:1143367488", "ละความคิดไม่บริสุทธิ์ {race} เป็นหนึ่งกับป่า!" },
        completion = { "48:1291827656:618219663 N 12:586053710:1993834439", "พิสูจน์ว่าเป็นพันธมิตรคู่ควร Revantusk แล้ว {name} ทำได้ดี" },
    },
    [7830] = { -- Avenging the Fallen
        title = { "19:687434267:1366515347", "ล้างแค้นผู้ล่วงลับ" },
        objective = { "279:1717135978:96792939", "Huntsman Markhor ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้าฆ่า Razorbeak Skylord และนำ Skylord Plume คืน เสร็จแล้วกลับไปหา\n\nMarkhor บอกว่าพวกมันเป็นกริฟฟอนพันธุ์หายาก อยู่ตามป่า Hinterlands" },
        description = { "281:1797983298:528604543", "สวะที่เรียก Wildhammer ฝึกกริฟฟอนฆ่าโทรลล์ ร้ายกาจ รู้ แต่ไม่ต้องกลัว ความยุติธรรมจะมาถึง\n\nตอนนี้มุ่งกำจัดกริฟฟอนอาวุโสที่เรียก Skylords\n\nฆ่าหนึ่ง แล้วคืนขนให้ข้า" },
        progress = { "116:143702441:1413692333", "Razorbeak Skylord หายากกว่ามาก ทำหน้าที่ผสมพันธุ์สร้างลูกฆาตกร" },
        completion = { "116:1942425428:1970147415", "<Markhor ตรวจขน>\n\nสงสัยสัตว์นี้กินนักล่าเราเท่าไรก่อนเจ้าลงทัณฑ์" },
        required = { [19025] = { "13:1087358035:1751699592", "ขนนกของเจ้าเวหา" } },
        steps = { { "13:1087358035:1751699592", "ขนนกของเจ้าเวหา" } },
    },
    [7839] = { -- Vilebranch Hooligans
        title = { "20:1195507449:307852354", "อันธพาล Vilebranch" },
        objective = { "312:1582680428:786003674", "Smith Slagtree ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้าหา Slagtree's Lost Tools เสร็จแล้วกลับไปหา\n\nจำได้ว่าเขาบอกอาจอยู่ที่วิหาร Vilebranch แห่งหนึ่งทางตะวันออกเฉียงเหนือ ควรตรวจ Skulk Rock ด้วย" },
        description = { "214:1825910137:64082567 N 202:2065737437:727027904", "Vilebranch สวะบุกขโมยเครื่องมือ! มีสำรอง แต่ชุดนั้นเป็นของขวัญโนมใจดีที่ช่วยชีวิตตอนข้ายังออร์คหนุ่ม\n\nต้องการคืน {name} มันคือทุกสิ่งของข้า\n\nMarkhor รายงานว่าเห็นใกล้วิหาร Agol'watha กับ Shaol'watha\n\nทางตะวันออกเฉียงเหนือ Hinterlands\n\nเอาเครื่องมือข้าคืน!" },
        progress = { "51:239487837:1263084686 N 37:2143382042:1239974277", "ระวัง Vilebranch {name} มันโหดเหี้ยม ฆาตกรสกปรก" },
        completion = { "54:1666928073:983161190 N 1:46:46", "เครื่องมือข้า! พบแล้ว! วันรุ่งโรจน์! ขอบคุณ {name}" },
        required = { [19033] = { "21:545356808:795572341", "เครื่องมือที่สูญหายของ Slagtree" } },
        objectiveLabels = {
            item = { ["Slagtree's Lost Tools"] = "เครื่องมือที่สูญหายของ Slagtree" },
        },
    },
    [7840] = { -- Lard Lost His Lunch
        title = { "19:110376204:1459958398", "Lard ทำมื้อกลางวันหาย" },
        objective = { "210:813240727:292378057", "Lard ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้าหา Lard's Lunch เสร็จแล้วกลับไปหา\n\nเขาบอกทิ้งไว้บนเกาะเหนือ ระวังโทรลล์ Vilebranch" },
        description = { "293:1128370399:720653084", "Lard ปิกนิกที่ลับพิเศษ แล้ว Vilebranch ใจร้ายน่าเกลียดตีด้วยไม้ใหญ่ Lard วิ่งกลับ Revantusk ลืมอาหาร Lard หิว เจ้าไปที่ลับเอาให้ไหม? Lard กลัว ไปเหนือ! เกาะเหนือคือที่ลับพิเศษ" },
        progress = { "47:795146382:1569105351", "<Lard ลูบท้องมหึมา>\n\nLard หิวมาก" },
        completion = { "158:787534802:1337142013", "<Lard รับขาเนื้อยักษ์แล้วยัดเข้าปาก>\n\nอิ่มใจเลย! ขอบใจ ตัวน้อย\n\nLard ทำตะกร้าปิกนิกพิเศษให้ที่ช่วย" },
        required = { [19034] = { "12:298004691:1317496546", "มื้อกลางวันของ Lard" } },
        objectiveLabels = {
            item = { ["Lard's Lunch"] = "มื้อกลางวันของ Lard" },
        },
    },
    [7841] = { -- Message to the Wildhammer
        title = { "25:479727783:1909136993", "สารถึง Wildhammer" },
        objective = { "315:650675252:705899154", "Otho Moji'ko ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้าฆ่า Highvale Outrunners 15 คน, Highvale Scouts 15 คน, Highvale Marksman 15 คน และ Highvale Rangers 15 คน เสร็จแล้วกลับไปหา\n\nพบไฮเอลฟ์ Highvale ที่ Quel'Danil Lodge ทางตะวันตกเฉียงเหนือ Hinterlands" },
        description = { "354:1062880851:841878300", "Wildhammer ตกลงกับศัตรู สร้างพันธมิตรใหม่ คราวนี้ไฮเอลฟ์ สหาย\n\n<Otho ถ่มน้ำลาย>\n\nต้องส่งสารถึงคนแคระด้วยเลือดศัตรู ฆ่า Highvale ทุกคนที่พบ ทิ้งศพเป็นคำเตือน\n\nอย่ายุ่งกับโทรลล์!" },
        progress = { "79:600090990:1767601595", "เจ้าสะอาดเกิน สหาย ต้องลงคลุกต่อสู้ศัตรูให้เปื้อน" },
        completion = { "87:858021170:250262318", "ดูเหมือน Revantusk ก็สร้างพันธมิตรใหม่เช่นกัน สหาย! ทำดีแล้ว" },
    },
    [7842] = { -- Another Message to the Wildhammer
        title = { "33:1225628991:557718594", "อีกสารถึง Wildhammer" },
        objective = { "253:2079337280:124390073", "Otho Moji'ko ที่ Revantusk Village ใน Hinterlands ต้องการ Long Elegant Feathers 10 อัน จากกริฟฟอนใน Hinterlands เสร็จแล้วกลับไปหา\n\nกริฟฟอนอาศัยทุกภูมิภาคของ Hinterlands" },
        description = { "284:321570886:1538038798", "ว่ากันว่า Wildhammer กับกริฟฟอนใกล้ชิดเท่าโทรลล์กับคู่ น่าขยะแขยง แต่ใช้ประโยชน์ได้ สหาย ส่งสารอีก\n\nฆ่ากริฟฟอนที่เห็น เก็บขน ใช้ทำสารสุดท้าย" },
        progress = { "90:65660603:289126849", "สารสุดท้ายต้องทำมันกลัวหนี หรือโกรธมาก ๆ" },
        completion = { "100:141722320:1215072786", "โอ้ สหาย ต้องดีแน่ อีกขั้นเดียว Wildhammer จะรู้ว่ายุ่งโทรลล์ไม่ได้!" },
        required = { [4589] = { "20:1505389641:1332052923", "ขนนกยาวงาม" } },
        objectiveLabels = {
            item = { ["Long Elegant Feather"] = "ขนนกยาวงาม" },
        },
    },
    [7843] = { -- The Final Message to the Wildhammer
        title = { "35:433073042:1900188437", "สารสุดท้ายถึง Wildhammer" },
        objective = { "321:2130340557:591142141", "Otho Moji'ko ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้าไป Aerie Peak ทางตะวันตก วาง Final Message to the Wildhammer ข้างบ่อกลางเมือง แล้วกลับไปหา\n\nระวังคนแคระ Wildhammer โกรธและสมาชิก Alliance ไม่ยอมอยู่เฉย" },
        description = { "315:1876500216:176521389", "<Otho ส่งหอกยาวชุ่มเลือดพันขนกริฟฟอน>\n\nรับไป สหาย เอาถึง Aerie Peak ใจกลางข้างบ่อ ปักลงดิน! ให้รู้ว่าโทรลล์เอาจริง! เสร็จแล้วกลับ หวังว่ายังรอด" },
        progress = { "24:1733566451:2044693562", "ช้าอะไร สหาย?" },
        completion = { "125:376976620:736360672 N 47:125995028:609002009", "อยากอยู่ดูหน้ามัน สหาย เก็บกระเป๋าหนีเมืองไหม?\n\nทำดี {name} ดีจริง Otho ตอบแทนโมโจใหญ่" },
        objectiveLabels = {
            event = { ["Message to the Wildhammer Delivered"] = "ส่งสารถึงตระกูล Wildhammer" },
        },
    },
    [7844] = { -- Cannibalistic Cousins
        title = { "21:1099800777:1049292625", "ญาติกินเนื้อพวกเดียวกัน" },
        objective = { "321:610626515:2030541911", "Mystic Yayo'jin ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้าฆ่า Vilebranch Scalpers 30 คน และ Vilebranch Soothsayers 15 คน เสร็จแล้วกลับไปหานาง\n\nYayo'jin บอกว่าพบใกล้วิหาร Shaol'watha กับ Agol'watha ทางเหนือค่อนไปตะวันออกเฉียงเหนือ Hinterlands" },
        description = { "58:1451967491:1482410845 N 429:1238947814:98180392", "มีโทรลล์สามเผ่าใน Hinterlands {name} คล้ายกันเพียงแค่นั้น เป็นโทรลล์และอยู่ที่นี่\n\nVilebranch ชื่อเหมาะสม เป็นพวกเสื่อมทราม กินโทรลล์อื่นและเผ่ารูปมนุษย์\n\nหาก Zul'jin อยู่ คงสะบัดมือทำลายหมด แต่เขายังไม่กลับ เราต้องพึ่งตน\n\nหน้าที่เจ้าคือทำลายสวะนี้!" },
        progress = { "97:883677035:223999598", "Vilebranch Soothsayers กับ Scalpers อยู่เหนือค่อนไปตะวันออกเฉียงเหนือ Hinterlands" },
        completion = { "11:534428891:784080240 C 51:871927562:765317117", "ดีมาก {class} แม้ Zul'jin ก็ทำได้ไม่ดีกว่านี้!" },
    },
    [7845] = { -- Kidnapped Elder Torntusk!
        title = { "25:236267842:300664320", "Elder Torntusk ถูกลักพาตัว!" },
        objective = { "266:436527559:131321061", "Primal Torntusk ที่ Revantusk Village ใน Hinterlands ต้องการให้เจ้าช่วยคู่ของนาง Elder Torntusk จาก Jintha'alor\n\nทราบว่าเขาถูกขังบนยอดเมืองหลวง Vilebranch นี้ ทางใต้ Hinterlands", variants = { { "266:1043214718:320116453", "Primal Torntusk ที่ Revantusk Village ใน Hinterlands ขอให้เจ้าช่วย Elder Torntusk คู่ชีวิตของนางออกจาก Jintha'alor\n\nมีคนบอกว่าเขาถูกขังอยู่บนยอด Jintha'alor เมืองหลวงของเผ่า Vilebranch ทางใต้ของ Hinterlands" } } },
        description = { "290:1078508695:1141223920 N 48:729394879:385151838", "Vilebranch ป่าเถื่อนบุกกลางดึกจับคู่ข้า สายลับบอกยังอยู่ ถูกขังยอด Jintha'alor ว่า Vile Priestess Hexx เตรียมบูชายัญต่อ Hakkar เทพเลือดไร้หน้า\n\nต้องช่วย {name}! หมู่บ้านทนเสียหนักเช่นนี้ไม่ได้" },
        completion = { "22:1004496963:1122245280 N 55:1418133752:677840166", "ต้องเร็ว {name} ยามคงรู้แล้วว่าเจ้ามา" },
    },
    [7846] = { -- Recover the Key!
        title = { "16:1959634298:1774626839", "นำกุญแจคืน!" },
        objective = { "165:464223461:416237734", "Elder Torntusk ที่ Jintha'alor ต้องการให้เจ้าฆ่า Hitah'ya the Keeper เอา Shackle Key ไขเครื่องพันธนาการ แล้วนำกุญแจกลับไปหาเขา", variants = { { "166:87156314:1490872659", "Elder Torntusk ที่ Jintha'alor ขอให้เจ้ากำจัด Hitah'ya the Keeper เพื่อเอา Shackle Key มาไขเครื่องพันธนาการของเขา เมื่อได้กุญแจแล้ว กลับไปหา Elder Torntusk" } } },
        description = { "94:1811282367:1840036152 C 122:1155921077:466663172", "Hitah'ya the Keeper ถือกุญแจข้า อยู่ถ้ำใกล้ ระวัง {class} นางมียามแน่นหนา\n\nฆ่าแล้วนำกุญแจคลายตรวน จึงเป็นอิสระกลับบ้านได้" },
        progress = { "15:92487270:1571404537", "ต้องรีบ!" },
        completion = { "28:628711547:1491529663 N 33:693046395:1408886418", "อิสระในที่สุด! ขอบคุณ {name} Revantusk จะรู้วีรกรรม!" },
        required = { [19064] = { "11:521583252:1980543513", "กุญแจปลดตรวน" } },
        objectiveLabels = {
