    },
    [7849] = { -- Separation Anxiety
        title = { "18:1967585273:207548762", "ทุกข์จากการพลัดพราก" },
        objective = { "447:1403548035:1670853281", "Huntsman Markhor ที่ Revantusk Village ใน Hinterlands ต้องการซากพี่น้องฝาแฝด หา Huntsman Malkhor's Skull และ Huntsman Malkhor's Bones คืนให้ Markhor\n\nเขาบอกว่าซากถูกให้เมือกกับหมาป่า Vilebranch กิน มีบ่อขยะเต็มเมือกและรังหมาป่าใน Jintha'alor ทั้งคู่ใกล้ยอดวิหาร" },
        description = { "388:1891853364:584108566 N 1:46:46", "เหมือนคนในหมู่บ้านมากมาย ข้าก็เสียคนรักแก่ป่า คราวนี้ฝาแฝด Malkhor ถูก Vilebranch จับครั้งเดียวกับคู่ Torntusk\n\nน่าเศร้า เขาไม่ถูกกำหนดให้รอด ถูกประหารเร็วโหด ซากให้เมือกกับหมาป่ากิน\n\nสายช่วยชีวิต แต่ยังช่วยวิญญาณได้ เอาซากคืน {name}" },
        progress = { "98:1791048417:798038479", "เมื่อได้ซาก จะนำให้ Yayo'jin เตรียมฝังอย่างเหมาะสม" },
        completion = { "74:194685059:1577421507 N 34:665608749:937821554", "พี่น้องที่รัก ข้าจะคิดถึงเพียงใด...\n\nขอบคุณที่ช่วย {name} เจ้าเป็นวีรบุรุษในสายตาข้าจริง" },
        required = { [19069] = { "24:1811492926:1191183663", "กะโหลกของนายพราน Malkhor" }, [19070] = { "24:731374344:488523591", "กระดูกของนายพราน Malkhor" } },
        objectiveLabels = {
            item = { ["Huntsman Malkhor's Skull"] = "กะโหลกของนายพราน Malkhor", ["Huntsman Malkhor's Bones"] = "กระดูกของนายพราน Malkhor" },
        },
    },
    [7850] = { -- Dark Vessels
        title = { "12:161499219:1486359612", "ภาชนะมืด" },
        objective = { "176:2077472478:111031595", "Primal Torntusk ที่ Revantusk Village ใน Hinterlands ต้องการ Vessels of Tainted Blood 10 ใบ จาก Jintha'alor เสร็จแล้วกลับไปหา" },
        description = { "429:113208490:777868257", "Vilebranch สู้ดุเหนือธรรมชาติ เพราะมนตร์ชั่ว Vile Priestess Hexx\n\nทั่ว Jintha'alor มีภาชนะเลือดมัวหมอง แผ่มนตร์เทพเลือดไร้หน้า เสริมพลังและทำมันบ้า\n\nขโมยคืนให้ข้า จะถอนมลทิน คลายอำนาจเทพเลือดในที่สุด" },
        progress = { "40:8655703:1117271792 N 52:1719867904:2134457468", "ระวังต่อสู้ Vilebranch {name} ใจมันมัวหมอง สู้จนตาย" },
        completion = { "201:1260223074:182255227", "พลังมืดที่ผลัก Vilebranch ถูกถอน...ตอนนี้ ต้องเฝ้าระวังชั่วเสมอ แม้ฆ่ามหาปุโรหิต ก็มีคนแทนเร็ว" },
        required = { [19071] = { "23:299038450:1996525374", "ภาชนะบรรจุโลหิตแปดเปื้อน" } },
        objectiveLabels = {
            item = { ["Vessel of Tainted Blood"] = "ภาชนะบรรจุโลหิตแปดเปื้อน" },
        },
    },
    [7861] = { -- Wanted: Vile Priestess Hexx and Her Minions
        title = { "43:1632979103:566757525", "ประกาศจับ: Vile Priestess Hexx และสมุน", variants = { { "43:223866906:1659215796", "ประกาศจับ: Vile Priestess Hexx และสมุน" } } },
        objective = { "268:198142598:772286490", "เจ้าถูกสั่งให้ฆ่า Vile Priestess Hexx และ Vilebranch Aman'zasi Guards 20 คน เสร็จแล้วพบ Primal Torntusk ที่ Revantusk Village ใน Hinterlands\n\nHexx กับ Aman'zasi Guards อยู่ยอด Jintha'alor ใน Hinterlands" },
        description = { "200:1586585701:265545431", "ตามคำสั่ง Primal Torntusk ต้องลงทัณฑ์ Vile Priestess Hexx กับสมุน!\n\nรางวัลงามแก่ผู้ฆ่านางและยามชั้นสูง Aman'zasi ทั้งหมด" },
        progress = { "35:1307694043:526615717", "นำข่าวจาก Jintha'alor หรือ?" },
        completion = { "74:747928658:752066363 N 1:46:46", "โจมตี Vilebranch จนเสียหลักจริง เจ้าจะได้รางวัลงาม {name}" },
    },
    [7862] = { -- Job Opening: Guard Captain of Revantusk Village
        title = { "47:1601716462:1518022116", "รับสมัคร: หัวหน้ายาม Revantusk Village" },
        objective = { "258:1111977326:2128529481", "เจ้ารับงานกำจัด Vilebranch Berserkers 20 คน, Vilebranch Shadow Hunters 20 คน, Vilebranch Blood Drinkers 20 คน และ Vilebranch Soul Eaters 20 คน\n\nเสร็จแล้วกลับไปหา Primal Torntusk ที่ Revantusk Village ใน Hinterlands" },
        description = { "398:1431344526:1425201070", "เมื่อเสีย Guard Captain Malkhor ตำแหน่งหัวหน้ายาม Revantusk ว่างอีก หากสนใจ ทำงานต่อไปแล้วส่งใบสมัคร Primal Torntusk\n\nกำจัด Vilebranch Berserkers\n\nกำจัด Vilebranch Shadow Hunters\n\nกำจัด Vilebranch Blood Drinkers\n\nกำจัด Vilebranch Soul Eaters" },
        progress = { "35:974619271:603575514", "มาเรื่องรับสมัครหรือ?" },
        completion = { "56:281359273:931079918 N 120:450957379:829180267", "คู่ควรตำแหน่งใหม่จริง {name} รับเครื่องประดับแทนขอบคุณงานหนัก ข้าจะตรวจใบสมัครทั้งหมดปีหน้า" },
        objectiveLabels = {
            monster = { ["Vilebranch Berserker slain"] = "ปราบ นักรบคลั่ง Vilebranch", ["Vilebranch Shadow Hunter slain"] = "ปราบ นักล่าเงา Vilebranch", ["Vilebranch Blood Drinker slain"] = "ปราบ นักดื่มเลือด Vilebranch", ["Vilebranch Soul Eater slain"] = "ปราบ ผู้กลืนกินวิญญาณ Vilebranch" },
        },
    },
    [8273] = { -- Oran's Gratitude
        title = { "16:1653057923:1537028513", "ความขอบคุณของ Oran" },
        completion = { "129:878705053:405646495 C 241:64106238:1619678516", "น่าสนใจ เจ้าว่าพบจารึกบนเกาะเล็กร้างที่ Overlook Cliffs ใน Hinterlands หรือ {class}? น่าสนใจมาก <Oran เก็บจารึกอย่างระวังแล้วถูมือ>\n\nขอบคุณผลงาน Dark Lady ต้องพอใจการค้นพบ รับรางวัลตามสมควรเถิด" },
    },
    [1448] = { -- In Search of The Temple
        title = { "23:1974125583:1590730627", "ค้นหาวิหาร" },
        objective = { "81:92095976:1333255325", "Brohann Caskbelly ที่ Stormwind ต้องการให้เจ้าค้นหา Temple of Atal'Hakkar" },
        description = { "62:690271107:465051409 C 435:1258721014:832601511", "เคยมีวันที่ข้าหนุ่มมีกำลังเช่นเจ้า {class}\n\nแต่ตอนนี้แก่ สำรวจโลกเหมือนเดิมไม่ได้ อา เคยเห็นมากมาย!\n\nมีปริศนาหนึ่งหลุดรอด ภารกิจสุดท้าย Explorers' League ส่งหา Temple of Atal'Hakkar ลือว่าอยู่ Swamp of Sorrows\n\nเพราะอ่อนแอจึงบินกริฟฟอนหา แต่ไม่พบ\n\nช่วยคนแคระแก่ไหม? เดินเท้าอาจโชคดีกว่า" },
        progress = { "358:1748646147:101561514 C 91:802404155:170432802", "ข้าเที่ยวโลก จากป่า Azeroth ถึงยอดหิมะ Khaz Modan\n\nไม่เคยขอใครช่วยผจญภัย แต่กระดูกแก่เหนื่อยแล้ว\n\nไม่มีอะไรอิ่มใจยิ่งกว่ารู้ว่าทำภารกิจสุดท้ายให้ Explorers' League สำเร็จ\n\nหากใจดีช่วยหา Temple of Atal'Hakkar {class} ขอบคุณมาก\n\nค้นทั่ว Swamp of Sorrows กลับรายงานสิ่งที่พบ!" },
        completion = { "131:1336985865:153314997 C 50:847466317:1908431083", "Temple of Atal'Hakkar จมใต้ Pool of Tears? ล้อมด้วยฝูงมังกรเขียว?\n\nค้นพบน่าทึ่ง {class} แต่ชัดว่ามีบางอย่างผิดร้ายแรง" },
        objectiveLabels = {
            event = { ["Search for the Temple of Atal'Hakkar"] = "ค้นหาวิหาร Atal'Hakkar" },
        },
    },
    [1449] = { -- To The Hinterlands
        title = { "18:526628047:838260355", "สู่ Hinterlands" },
        objective = { "74:1648269926:1576855323", "คุยกับ High Thane Falstad Wildhammer ที่ Aerie Peak ใน Hinterlands" },
        description = { "489:1000097148:347162179", "อย่างบอก เคยสำรวจวิหารจากฟ้าเอง แต่ไม่เชิงลำพัง\n\nไปโรงกริฟฟอนมีชื่อ Aerie Peak ใน Hinterlands ขอคนขี่ชั้นดีคนหนึ่ง เขาตกพาหนะลงบึง...\n\nแก่แล้วจำชื่อไม่ได้ แต่ผู้ดูแลโรงคงจำได้\n\nไปหา Falstad Wildhammer\n\nต้องรู้ว่าเกิดอะไรกับคนขี่นั้น" },
        completion = { { "126:610636414:1723593909 R 73:633320643:1362898464", "126:662049797:1891728005 R 73:633320643:1362898464" }, "ต้องการอะไร? ไม่เห็นมีปัญหาให้จัดการหรือ? ใครมีเวลายืนพล่ามกับ {race} ช่างพูด?\n\nโทรลล์ผุดทุกซอกมุม! ว่ามาเร็ว" },
    },
    [805] = { -- Report to Sen'jin Village
        objective = { "44:1267587516:747756678", "คุยกับ Master Gadrin ที่ Sen'jin Village" },
        title = { "25:1315301621:656353841", "ไปรายงานที่ Sen'jin Village" },
        description = { "383:1446371247:1850721804 N 104:1824820027:711324941", "บททดสอบของท่านกับ Burning Blade จบแล้ว... สำหรับที่หุบเขา แต่ข้าต้องการให้ท่านไปรายงานสิ่งที่พบ\n\nไปหมู่บ้านโทรลล์ Sen'jin แล้วตามหา Master Gadrin ออกจากหุบเขาไปทางตะวันออก แล้วเลี้ยวขวาที่ทางแยกก็จะถึง Sen'jin Village\n\nบอกกาดรินเรื่อง Burning Blade และว่าพวกมันมาถึง Valley of Trials แล้ว ถามเขาว่าพวกมันมาถึง Sen'jin หรือยัง\n\nรีบไป {name} ข้าเกรงว่าความชั่วร้ายใน Burning Blade Coven เป็นเพียงสัญญาณของภัยที่ใหญ่กว่านี้..." },
        completion = { "265:2026641095:2036098230", "อืม... ท่านมารายงานในจังหวะไม่ดีเสียแล้ว ยังไม่เห็น Burning Blade ที่ Sen'jin แต่ความชั่วร้ายของพวกมันหยั่งรากแล้วบน Echo Isles นอกชายฝั่ง\n\nพวกออร์คเป็นมิตรกับโทรลล์ดาร์กสเปียร์ เป็นมิตรผู้มีเกียรติ เราอยากช่วยพวกออร์ค แต่... พวกเราก็ต้องการความช่วยเหลือเหมือนกัน" },
    },
    [2] = { -- Sharptalon's Claw
        title = { "17:570267005:950707214", "กรงเล็บของ Sharptalon" },
        objective = { "79:896638189:322020505", "นำ Sharptalon's Claw ไปให้ Senani Thunderheart ที่ Splintertree Post ใน Ashenvale" },
        description = { "241:1914170693:1048356072", "ฮิปโปกริฟผู้ทรงพลัง Sharptalon ถูกสังหารแล้ว กรงเล็บของมันเป็นหลักฐานแห่งชัยชนะของเจ้า Senani Thunderheart ที่ Splintertree Post คงอยากเห็นของที่ระลึกชิ้นนี้เพื่อยืนยันวีรกรรมของเจ้า" },
        progress = { "12:278993546:962440370 C 84:25651462:1042852106", "ใช่แล้ว {class} ผู้เก่งกาจ ข้าสัมผัสได้ว่าเจ้ามาถึง เชื่อว่าเจ้ามีข่าวเรื่องการล่ามารายงานอีกใช่ไหม?" },
        completion = { "17:227795612:681635069 N 394:1762247309:1326133671", "น่าประทับใจมาก {name}... กรงเล็บของ Sharptalon คงได้มาไม่ง่าย! การล่าแห่ง Ashenvale ของเจ้ากำลังไปได้สวย!\n\nSharptalon คุกคามคนงานจากค่ายตัดไม้ตามเส้นทางของมันมานาน ระหว่างที่พวกเขาเดินทางมายัง Splintertree Post เมื่อข่าวแพร่ไปว่าเจ้าเป็นผู้โค่นมัน เพลงเชิดชูความกล้าหาญของเจ้าคงดังก้องรอบกองไฟและโรงเลื่อยทั่ว Ashenvale!" },
        required = { [16305] = { "17:570267005:950707214", "กรงเล็บของ Sharptalon" } },
        steps = { { "17:570267005:950707214", "กรงเล็บของ Sharptalon" } },
    },
    [23] = { -- Ursangous's Paw
        title = { "15:347257057:917495938", "อุ้งเท้าของ Ursangous" },
        objective = { "77:1235505334:650359413", "นำ Ursangous's Paw ไปให้ Senani Thunderheart ที่ Splintertree Post ใน Ashenvale" },
        description = { "345:284036366:68339003", "อุ้งเท้าของหมีผู้ทรงพลัง Ursangous เป็นของที่ระลึกจากการล่าแห่ง Ashenvale ในขั้นนี้ บนอุ้งเท้ามีตรารูปเสี้ยวจันทร์เล็ก ๆ ซึ่งยังไม่ทราบความหมาย\n\nควรนำอุ้งเท้าไปให้ Senani Thunderheart ที่ Splintertree Post เพื่อพิสูจน์ว่าเจ้าเอาชนะสัตว์ร้ายตัวนี้และผ่านการล่าขั้นนี้แล้ว", variants = { { "347:2133572702:1181766273", "<อุ้งเท้าของหมีผู้ทรงพลัง Ursangous เป็นของที่ระลึกจากการล่าแห่ง Ashenvale ในขั้นนี้ บนอุ้งเท้ามีตรารูปเสี้ยวจันทร์เล็ก ๆ ซึ่งยังไม่ทราบความหมาย\n\nควรนำอุ้งเท้าไปให้ Senani Thunderheart ที่ Splintertree Post เพื่อพิสูจน์ว่าเจ้าเอาชนะสัตว์ร้ายตัวนี้และผ่านการล่าขั้นนี้แล้ว>" } } },
        progress = { "5:1860217498:49498747 N 56:936515038:1606505318", "อ้อ {name} ข้ากำลังคิดถึงเจ้าอยู่พอดี! การล่าเป็นอย่างไรบ้าง?" },
        completion = { "52:1318537203:905529388 C 324:1950938696:1966548586", "อา อุ้งเท้าของ Ursangous! ฝีมือเจ้าน่าประทับใจ {class} มันคร่าชีวิตมาแล้วมากมาย ตราเสี้ยวจันทร์บนอุ้งเท้าคงเป็นสัญญาณว่ามันถูกฝึกโดยไนต์เอลฟ์ที่ซุ่มอยู่ทั่ว Ashenvale Ursangous เป็น... เคยเป็นหมีที่แข็งแกร่งที่สุดตัวหนึ่งในแถบนี้ การเอาชนะมันได้พิสูจน์ถึงความมุ่งมั่นและใจอันเด็ดเดี่ยวของเจ้า\n\nบรรพชนของเจ้าคงภาคภูมิใจ!" },
        required = { [16303] = { "15:347257057:917495938", "อุ้งเท้าของ Ursangous" } },
        steps = { { "15:347257057:917495938", "อุ้งเท้าของ Ursangous" } },
    },
    [24] = { -- Shadumbra's Head
        title = { "16:2032218035:122083684", "หัวของ Shadumbra" },
        objective = { "78:457163560:616329499", "นำ Shadumbra's Head ไปให้ Senani Thunderheart ที่ Splintertree Post ใน Ashenvale" },
        description = { "289:1964485359:1938038961", "Shadumbra ที่เคยว่องไวนอนแน่นิ่งหลังชัยชนะของเจ้าแล้ว หัวของไนต์เซเบอร์ที่ถูกสังหารเป็นของที่ระลึกอันเหมาะสมสำหรับการต่อสู้ขั้นนี้ของการล่าแห่ง Ashenvale Senani Thunderheart ที่ Splintertree Post คงอยากเห็นมันเพื่อรับรองว่าเจ้าผ่านการล่าขั้นนี้แล้ว" },
        progress = { "22:940931934:1505085707 N 46:1183751408:544117694", "สวัสดีอีกครั้ง {name}! เจ้านำหลักฐานการล่ามาให้ข้าดูหรือ?" },
        completion = { "14:1845885603:794182028 N 354:1166212227:45424235", "ชัยชนะในการล่าแห่ง Ashenvale เป็นของ {name}! ทำได้ดี หัวของ Shadumbra เป็นของที่ระลึกที่คู่ควรกับการต่อสู้อันน่าประทับใจนี้อย่างไม่ต้องสงสัย\n\nทุกคนในฐานนี้รู้ดีว่า Shadumbra ดุร้ายเพียงใด การเดินทางไปทางตะวันตก โดยเฉพาะการเดินเท้าไป Zoram Strand เต็มไปด้วยอันตรายเพราะเสือตัวนี้ ต้องขอบใจเจ้าที่ทำให้อันตรายนั้นบรรเทาลง" },
        required = { [16304] = { "16:2032218035:122083684", "หัวของ Shadumbra" } },
        steps = { { "16:2032218035:122083684", "หัวของ Shadumbra" } },
    },
    [25] = { -- Stonetalon Standstill
        title = { "21:1644637226:978296600", "เส้นทาง Stonetalon หยุดชะงัก" },
        objective = { "258:1275048009:2010318741", "กำจัด Befouled Water Elementals 12 ตัวที่ Mystral Lake ทางตะวันออกของ Talondeep Path และตะวันตกเฉียงใต้ของ Splintertree Post\n\nสำรวจศาลาบน Mystral Lake ที่มองเห็นฐาน Alliance ใกล้ ๆ\n\nกลับไปหา Mastok Wrilehiss ที่ Splintertree Post ใน Ashenvale" },
        description = { "499:2012791398:1481188914", "ถ้าเจ้าอยากทำตัวให้เป็นประโยชน์ ทำไมไม่ไปจัดการสถานการณ์แถว Talondeep Path ล่ะ?\n\nการขนส่งระหว่าง Ashenvale กับ Stonetalon หยุดชะงัก เพราะทะเลสาบนั่นลุกขึ้นมาโจมตีทุกสิ่งที่เข้าใกล้... ซึ่งก็คือทุกคนบนเส้นทางนั้น นอกจากจัดการธาตุน้ำแล้ว หากมีใครไปสำรวจศาลาบน Mystral Lake ที่มองเห็นฐาน Alliance ได้ชัด ก็ยิ่งมีประโยชน์\n\nพร้อมทำตัวให้เป็นประโยชน์หรือยัง?" },
        progress = { "85:1627070787:1159065142", "กลับมาแล้วหรือ? ที่นั่นเป็นอย่างไรบ้าง เจ้าเคลียร์ทุกอย่างเรียบร้อยแล้วใช่ไหม?" },
        completion = { "435:2132306070:1438991306", "ใช่ ข้าได้ยินว่ามีคนถล่มทะเลสาบนั่นราวกับลมหมุนที่กวาดผ่าน Barrens ฟังดูแล้วเราอาจตั้งจุดสังเกตการณ์ไว้คอยจับตาสหายฝ่าย Alliance ของเราได้ด้วย ถ้าเราเก็บเรื่องนี้ให้เงียบได้น่ะนะ...\n\nดูเหมือนสุดท้ายเจ้าก็มีประโยชน์มากทีเดียว การขนส่งระหว่างที่นี่กับ Stonetalon คงสะดวกขึ้น รับนี่ไป เจ้าสมควรได้มัน" },
        objectiveLabels = {
            event = { ["Scout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost."] = "สำรวจศาลาริม Mystral Lake ที่มองเห็นด่าน Alliance ใกล้ ๆ" },
            monster = { ["Befouled Water Elemental slain"] = "ปราบ ธาตุน้ำที่แปดเปื้อน" },
        },
    },
    [216] = { -- Between a Rock and a Thistlefur
        title = { "31:290780826:1713665100", "ติดขัดเพราะ Thistlefur" },
        objective = { "191:1123404600:1169571652", "กำจัด Thistlefur Avengers 8 ตัว และ Thistlefur Shaman 8 ตัว ส่วนใหญ่อยู่ใน Thistlefur Village ทางตะวันออกของ Zoram Strand แล้วกลับไปหา Karang Amakkar ที่ Zoram'gar Outpost ใน Ashenvale", variants = { { "193:1923909707:1120184017", "กำจัด Thistlefur Avengers 12 ตัว และ Thistlefur Shaman 12 ตัว ส่วนใหญ่อยู่ใน Thistlefur Village ทางตะวันออกของ Zoram Strand แล้วกลับไปหา Karang Amakkar ที่ Zoram'gar Outpost ใน Ashenvale" } } },
        description = { "262:1368232556:74961919 N 212:1824153821:1122180799", "เฟอร์โบลก์ Thistlefur กำลังขวางการขยายอาณาเขตของเรา! Thistlefur Village ทางตะวันออกปิดกั้นเส้นทางจากที่นี่ไป Splintertree Post เส้นทางนี้ใช้เลี่ยงหมู่บ้าน Astranaar ได้ ถ้าใช้ไม่ได้ เราก็เปิดทางให้ Alliance ขยายอาณาเขตเพิ่ม\n\n{name} เราจะยอมให้มี... ช่องโหว่บนเส้นทางขยายอาณาเขตไม่ได้!\n\nไป Thistlefur Village แล้วลดจำนวนเฟอร์โบลก์ เจ้าจะได้รับค่าตอบแทน แต่ที่สำคัญกว่านั้นคือเจ้าได้ทำหน้าที่เพื่อ Horde!" },
        progress = { "150:1804303230:510547751", "เจ้าไปจัดการ Thistlefur แล้วหรือยัง? หากเส้นทางระหว่างฐานของเราโล่ง โอกาสยึดครอง Ashenvale ทั้งหมดจะเพิ่มขึ้นมหาศาล" },
        completion = { "10:963015740:1087923650 C 265:1599416588:173841060", "ทำได้ดี {class} ทำได้ดี! ข้าจะส่งกองกำลังไปลดจำนวนเฟอร์โบลก์ต่อ แต่ตอนนี้อย่างน้อยเราก็มีเส้นทางอีกสายที่ไม่ต้องพัวพันกับ Alliance การพิชิต Ashenvale ของ Horde กำลังเดินหน้าเต็มกำลังแล้ว!\n\nวันนี้เจ้าสมควรได้รับค่าจ้าง วีรบุรุษ ข้าขอคารวะ!" },
        objectiveLabels = {
            monster = { ["Thistlefur Avenger slain"] = "ปราบ นักล้างแค้น Thistlefur", ["Thistlefur Shaman slain"] = "ปราบ ชาแมน Thistlefur" },
        },
    },
    [247] = { -- The Hunt Completed
        title = { "18:988025005:1949179271", "การล่าสำเร็จแล้ว" },
        completion = { "N 401:306688382:498819395", "{name} เจ้าสังหารสัตว์ทั้งสามที่เป็นเป้าหมายของการล่าแห่ง Ashenvale แล้ว และนำหลักฐานมายืนยันอย่างเพียงพอ ไม่มีข้อกังขาในความแข็งแกร่งและความทรหดของเจ้า เลือดของนักล่าไหลอยู่ในตัวเจ้า สมควรได้รับคำยกย่อง!\n\nโปรดรับของเล็กน้อยชิ้นนี้เพื่อแสดงความยินดีกับวีรกรรมที่เจ้าทำเพื่อ Horde ใน Ashenvale วันนี้ ขอให้บรรพชนคุ้มครองเจ้า!" },
    },
    [824] = { -- Je'neu of the Earthen Ring
        title = { "26:1294618624:1096523363", "Je'neu แห่ง Earthen Ring" },
        objective = { "81:603474405:78517329", "นำ Befouled Water Globe ไปให้ Je'neu Sancrea ที่ Zoram'gar Outpost ใน Ashenvale" },
        description = { "432:304941407:980885304", "Earthen Ring เป็นกลุ่มชามานที่อุทิศตนศึกษาธาตุและปกป้องสมดุลของมัน เรื่องเทพเจ้าโบราณวิปลาส ตำนานเก่าแก่ และความรู้ลี้ลับที่พวกเขาลืมไป ยังมากกว่าที่นักวิชาการส่วนใหญ่จะได้เรียนรู้ทั้งชีวิต\n\nโชคดีที่ข้ารู้จักคนของ Earthen Ring ใน Ashenvale ไปที่ Zoram'gar Outpost บนชายฝั่ง Zoram Strand แล้วให้ Je'neu Sancrea ดูสิ่งที่เจ้าพบ หากใครจะไขความสำคัญของลูกแก้วนั้นได้ ก็คงเป็นเขา" },
        progress = { "196:226591057:1139933083", "อ้อ สวัสดี ข้าใช้เวลาศึกษาน้ำมากทีเดียว ที่จริงก็ทุกธาตุนั่นแหละ จนบางครั้งไม่ทันสังเกตว่ามีคนอยู่ข้าง ๆ\n\nมีอะไรให้ข้าช่วยหรือ?" },
        completion = { "445:1047761386:2115603582", "ลูกแก้วนี้... น่ากังวลยิ่ง ธาตุที่ทรงพลังหลายตนได้รับพลังผ่านอุปกรณ์เช่นนี้ การพบลูกแก้วที่แทบสมบูรณ์ก็เป็นเรื่องหนึ่ง แต่พบว่ามันแปดเปื้อนถึงขนาดนี้เป็นอีกเรื่อง\n\nข้าจะให้ Earthen Ring ศึกษามันอย่างเหมาะสม บางทีเราอาจยุติความเสื่อมทรามของเหล่าธาตุได้ โปรดรับสิ่งนี้เป็นการตอบแทนที่นำลูกแก้วมาให้ Earthen Ring รับรู้" },
        required = { [16408] = { "20:1027649815:845629786", "ลูกแก้วน้ำแปดเปื้อน" } },
        steps = { { "20:1027649815:845629786", "ลูกแก้วน้ำแปดเปื้อน" } },
    },
    [1058] = { -- Jin'Zil's Forest Magic
        title = { "22:1813192638:698791694", "เวทแห่งป่าของ Jin'Zil" },
        objective = { "131:1289580798:695455020", "Witch Doctor Jin'Zil ที่ Malaka'jin ต้องการ Stonetalon Sap 5 ส่วน, Twilight Whiskers 5 ชิ้น, Courser Eyes 30 ดวง และ Fey Dragon Scale หนึ่งชิ้น" },
        description = { "459:437553388:474360823 N 34:362528029:980884222", "ข้าตื่นเต้นเสียจริง!\n\nกรงน้อยสามกรงสำหรับเอลฟ์น้อยสามคน! แต่เราจะทำอะไรกับสหายรักต้นไม้ผู้น่ารักของเราดี? ให้พวกเขาได้ลิ้มรส... เรียกว่าอะไรนะ... เวทแห่งป่ายังไงล่ะ!\n\nข้าต้องการยางไม้ Stonetalon มากพอสมควร เอาหนวดจากแมวน่าเกลียดพวกนั้นมาให้ด้วย สูตรนี้ต้องใช้ดวงตาของ courser มากแน่นอน มีดวงตาเท่าไรก็ไม่เคยพอ อ้อ อย่าลืมเกล็ดล้ำค่าจากมังกรเฟย์ด้วย\n\nรีบไป Stonetalon Peak เถอะ {name} ข้าจะได้ปรุงเวทแห่งป่า!" },
        progress = { "335:397972799:495637856", "ดูสหายเอลฟ์น้อยที่น่าสงสารของเราสิ ถูกขังอยู่ในกรง ไม่มีป่าให้วิ่งเล่น!\n\nหายางไม้มาให้ข้าได้หรือยัง? แล้วหนวดจาก twilight runners ล่ะ? คงไม่ได้มีเกล็ดมังกรเฟย์ติดตัวมาด้วยหรอกนะ?\n\nแล้วดวงตา! ข้าต้องการดวงตามากมาย! หากไม่ใส่ดวงตาให้เพียงพอ ก็ปรุงเวทแห่งป่าให้ร้ายกาจไม่ได้หรอก!" },
        completion = { "116:648933058:882458699", "เหล่านางไม้ตัวน้อยคงมีความสุขนัก! น้ำยาพิเศษนี้จะทำให้พวกเขารู้สึกเหมือนได้กลับบ้านเลย!" },
        required = { [5582] = { "14:578787456:1649377728", "ยางไม้จาก Stonetalon" }, [5584] = { "16:1969118434:436256378", "หนวด Twilight" }, [5585] = { "11:762521120:1461686105", "ดวงตาของ Courser" }, [5583] = { "16:1916471384:1073101468", "เกล็ดมังกรภูต" } },
        steps = { { "14:578787456:1649377728", "ยางไม้จาก Stonetalon" }, { "16:1969118434:436256378", "หนวด Twilight" }, { "11:762521120:1461686105", "ดวงตาของ Courser" }, { "16:1916471384:1073101468", "เกล็ดมังกรภูต" } },
    },
    [1061] = { -- The Spirits of Stonetalon
        title = { "25:461073137:1217555323", "วิญญาณแห่ง Stonetalon" },
        objective = { "58:1296490052:168168000", "คุยกับ Seereth Stonebreak ใน Stonetalon Mountains" },
        description = { "487:1605892593:785870972", "เหล่าวิญญาณแห่ง Stonetalon Mountains กำลังโกรธเกรี้ยว เพราะก็อบลินกับสมุนปล้นทำลายและเผาผืนดิน ผืนดินจึงร้องคร่ำครวญ และผู้ที่คอยฟังเสียงเช่นนั้น... ก็ได้ยิน\n\nSeereth Stonebreak ชามานผู้มีแววของ Horde ถูกส่งไป Stonetalon นางรายงานว่าก็อบลินตัดไม้ทำลายป่าครั้งใหญ่ และร้องขอความช่วยเหลือ\n\nไปพบนางที่ Stonetalon โดยใช้ถนนทางตะวันตกจาก Crossroads ใน Barrens นางตั้งค่ายอยู่ใกล้ Greatwood Vale" },
        completion = { "6:1537380568:68647516 C 68:472296385:1524887986", "อา {class} ดีมาก เราต้องใช้ฝีมือของเจ้าจัดการพวกที่มาปล้นทรัพยากรเหล่านี้!" },
    },
    [1062] = { -- Goblin Invaders
        title = { "15:64584557:1755354403", "ก็อบลินผู้รุกราน" },
        objective = { "107:1308256513:120571247", "ฆ่า Venture Co. Loggers 15 ตัว แล้วกลับไปหา Seereth Stonebreak ที่ชายแดน Stonetalon กับ Barrens" },
        description = { "476:1506663244:1571810335", "Venture Company ที่ก็อบลินเป็นผู้บริหารย้ายเข้ามาใน Stonetalon Mountains ตัดต้นไม้และเผาป่าเป็นบริเวณกว้าง วิญญาณของที่นี่แทบมืดบอดด้วยความเจ็บปวดและความโกรธ เราต้องหยุด Venture Company!\n\nมุ่งไปตะวันตกเฉียงเหนือ ผ่าน Greatwood Vale เข้าสู่ Windshear Crag เจ้าจะพบก็อบลินกับสมุนกำลังทำงานอยู่ จงแสดงให้เห็นว่า Horde ไม่ยอมให้ใครกอบโกยจาก Stonetalon บอกพวกมันด้วยภาษาที่เข้าใจดีที่สุด...\n\nความรุนแรง" },
        progress = { "42:979210423:1846829351 N 57:596990247:580229407", "Greatwood Vale อยู่ทางตะวันตกเฉียงเหนือ {name} ไปเสีย ทำให้พวกที่คิดปล้นผืนดินแห่งนี้รู้จักความกลัว!" },
        completion = { "14:765600965:214150388 N 174:976456982:1337295016", "กล้าหาญมาก {name}\n\nท้ายที่สุดเราอาจต้องพึ่งภูมิปัญญาของผู้อาวุโสทอเรนเพื่อปลอบวิญญาณแห่ง Stonetalon แต่...\n\nการกำจัดคนงานของ Venture Company ก็เป็นก้าวแรกที่ดีในการต่อต้านพวกมัน" },
        objectiveLabels = {
            monster = { ["Venture Co. Logger slain"] = "ปราบ คนตัดไม้ของ Venture Co." },
        },
    },
    [1063] = { -- The Elder Crone
        title = { "15:53439397:977002845", "หญิงชราผู้อาวุโส" },
        objective = { "36:1477527367:219542123", "คุยกับ Magatha ที่ Thunder Bluff" },
        description = { "443:1823571925:479832921", "หากจะดูแลวิญญาณแห่ง Stonetalon อย่างแท้จริง เราต้องปรึกษาผู้อาวุโสทอเรน\n\nข้าไม่รู้จักชื่อผู้นำของพวกเขามากนัก แต่รู้จักอยู่คนหนึ่งคือ Magatha ได้ยินว่านางมีอายุมากและรอบรู้ หากใครจะรวบรวมพลังวิญญาณของทอเรนมาช่วยได้ ก็คงเป็นนาง\n\nMagatha อยู่ที่ Elder Rise ใน Thunder Bluff เมืองหลวงทอเรน บนหน้าผาด้านตะวันออกเฉียงเหนือของเมือง ไปคุยกับนางและบอกถึงภัยที่คุกคาม Stonetalon Mountains" },
        completion = { "50:81385291:822293287", "ข้าขอต้อนรับ เจ้ากำลังแสวงหาคำปรึกษาหรือ?" },
    },
    [1068] = { -- Shredding Machines
        title = { "18:292604128:1721848385", "เครื่องจักรตัดไม้" },
        objective = { "126:1918854601:1586861375", "ทำลายเครื่องตัดไม้ XT:4 และ XT:9 แล้วกลับไปหา Seereth Stonebreak ที่ชายแดน Stonetalon Mountains กับ Barrens" },
        description = { "479:399177191:2073078415", "เวทวิญญาณของชามานกับเวทธรรมชาติของดรูอิดมีความเกี่ยวข้องกัน นั่นทำให้ชามานอย่างเราได้ยินคำวิงวอนของวิญญาณแห่ง Stonetalon ข้าไม่เข้าใจเสียงกระซิบมากมาย แต่มีสารหนึ่ง นิมิตหนึ่ง ที่ชัดเจน...\n\nข้าเห็นเครื่องจักรรูปร่างคล้ายมนุษย์สองเครื่องใน Windshear Crag ทางตะวันตกเฉียงเหนือของ Greatwood Vale กำลังโค่นต้นไม้ด้วยความเร็วเหลือเชื่อ เราต้องหยุดอสูรโลหะพวกนี้!\n\nในนิมิตของข้า เครื่องจักรมีสัญลักษณ์ประหลาดเขียนไว้ว่า:\n\nXT:4 และ XT:9" },
        progress = { "53:1017761436:545494118 N 90:1392321174:1030739039", "วิญญาณต้นไม้คร่ำครวญกับการสูญเสียพี่น้อง {name} เจ้าต้องทำลายเครื่องตัดไม้ XT:4 และ XT:9 ไม่เช่นนั้นข้ากลัวว่า Stonetalon จะไม่มีวันฟื้นคืน" },
        completion = { "94:660827606:1170326023 N 192:151520035:1663982984", "การทำลายเครื่องจักร XT:4 และ XT:9 ช่วยปลอบวิญญาณแห่ง Stonetalon ได้มาก {name} หวังว่าการสูญเสียพวกมันจะทำให้ Venture Company ถอนตัวจากเทือกเขานี้\n\nหากไม่เป็นเช่นนั้น ข้าเกรงว่าความโหดร้ายที่เกิดขึ้นแล้วจะดูเล็กน้อย เมื่อเทียบกับสิ่งที่กำลังจะตามมา" },
        objectiveLabels = {
            monster = { ["XT:4 slain"] = "ปราบ XT:4", ["XT:9 slain"] = "ปราบ XT:9" },
        },
    },
    [1087] = { -- Cenarius' Legacy
        title = { "16:922887248:1465749025", "มรดกของ Cenarius" },
        objective = { "117:1142546855:1952801429", "ฆ่า Sons of Cenarius 4 ตัว, Daughters of Cenarius 4 ตัว และ Cenarion Botanists 4 ตัว ให้ Braelyn Firehand ใกล้ Sun Rock Retreat" },
        description = { "503:1068843871:1477050313", "เจ้าคงนึกไม่ถึงว่าข้าเกลียดผืนดินน่าสังเวชนี้มากเพียงใด พวกพ้องของ Cenarius กับดรูอิดคัลโดไรบนยอดเขาใช้พลังอันน้อยนิดของตนขัดขวางกระแสเวทมนตร์ แม้ไกลลงมาทางใต้จากอาณาเขตแสนกระจ้อยร่อย... ป่าอันเป็นที่รักของพวกมัน\n\nข้าอยากกลับ Jaedenar และดื่มด่ำกระแสเวทมนตร์นัก แต่นายของข้าไม่ยอมให้กลับจนกว่าจะทำงานเสร็จ\n\nข้าเชื่อว่าเจ้ารักไนต์เอลฟ์กับพันธมิตรของพวกมันน้อยพอ ๆ กับข้า ช่วยข้า แล้วเราทั้งคู่คงได้สิ่งที่ต้องการ" },
        progress = { "85:1695747413:1462968554", "การเรียกใช้เวทมนตร์ที่นี่เหมือนตักน้ำจากบ่อด้วยถังที่มีแต่รูรั่ว" },
        completion = { "256:1224624601:1303799222", "ข้าสัมผัสได้แล้ว... ใช่... พลังอันหอมหวาน... หลั่งไหลเข้ามาดุจสายน้ำเชี่ยว คัลโดไรช่างโง่เขลาที่ดูแคลนของขวัญจากโลกนี้ ปฏิเสธเวทมนตร์ที่ไหลขับขานอยู่ในเส้นเลือด\n\nชีวิตช่างจืดชืดไร้ค่า หากปราศจากอ้อมกอดอันร้อนแรงของมัน!" },
        objectiveLabels = {
            monster = { ["Son of Cenarius slain"] = "ปราบ บุตรแห่ง Cenarius", ["Daughter of Cenarius slain"] = "ปราบ ธิดาแห่ง Cenarius", ["Cenarion Botanist slain"] = "ปราบ นักพฤกษศาสตร์ Cenarion" },
        },
    },
    [1088] = { -- Ordanus
        title = { "7:514376051:750115443", "Ordanus" },
        objective = { "62:969357416:1646240669", "นำหัวของ Ordanus ไปให้ Braelyn Firehand ใกล้ Sun Rock Retreat" },
        description = { "459:1808427688:1618113746", "พวกมันคิดว่าจะหยุดกระแสเวทมนตร์ได้ พวกมันคิดผิด คิดว่าจะซ่อน Ordanus ได้ แต่ข้าจะเอาหัวมันมาให้ได้!\n\nเวทมนตร์ทำให้ข้ามองเห็นความจริง ใช่... มันอยู่ตรงนั้น ทางแยก... บนยอดต้นไม้ใหญ่ในป่า Ashenvale ชื่อว่า... Raynewood บุตรผู้ใหญ่คนหนึ่งของเทพแห่งป่า พวกมันลอบพาเขาหนีจากยอดเขาก่อนข้าพบตัว แต่เวลาของเขาใกล้หมดแล้ว\n\nนำหัวมาให้ข้า แล้วข้าจะแบ่งของขวัญอันทรงพลังให้เจ้า" },
        progress = { "255:1881944375:538899843", "เมื่อนายของข้าส่งข้ามาที่ Stonetalon Peak ข้าคิดว่าเพียงกำจัดไนต์เอลฟ์ที่คลานยั้วเยี้ยอยู่ตามซากวิหารโบราณแห่ง Azshara ของเรา สัมผัสของพวกมันแปดเปื้อนความศักดิ์สิทธิ์... แต่ Ordanus กลับหลุดมือข้าไป" },
        completion = { "152:445794391:207354895 N 63:274036770:1166532916", "ข้าเคยรู้จัก Ordanus เมื่อนานมาแล้ว เขาหยิ่งผยองเช่นเดียวกับเผ่าพันธุ์ของตน ยกตัวเหนือแม้กระทั่งไฮบอร์น\n\nตอนนี้หัวของเขาไม่ได้ชูสูงเช่นนั้นแล้ว จริงไหม {name}?\n\nข้าสัญญาว่าจะให้รางวัล และเจ้าจะได้รับมัน จงฟังข้า" },
        required = { [5686] = { "13:1057066859:1040488295", "ศีรษะของ Ordanus" } },
        steps = { { "13:1057066859:1040488295", "ศีรษะของ Ordanus" } },
    },
    [1089] = { -- The Den
        title = { "7:1622258210:1775782258", "โพรงลับ" },
        objective = { "143:508544504:1834467099", "ไปที่ Talon Den บน Stonetalon Peak ใช้ Gatekeeper's Key เก็บไอเทมที่ดรูอิดซ่อนไว้ แล้วใช้ไอเทมเหล่านั้นเปิด Talon Den Hoard" },
        description = { "476:558226634:201660090", "เหล่าดรูอิดสร้าง Talon Den บน Stonetalon Peak และเก็บไอเทมทรงพลังมากมายไว้ที่นั่น\n\nพวกเขาวางกลไกซับซ้อนเพื่อไม่ให้ของตกไปอยู่ในมือผู้ไม่หวังดี\n\nโชคดีที่ข้าสามารถ... เค้นรายละเอียดจากคนหนึ่งมาได้\n\nในตะเกียงเล็กตรงทางเข้าโพรง เจ้าจะพบ Gatekeeper's Key ใช้มันเปิดที่เก็บของรอบโพรง ไอเทมจากที่เก็บเหล่านี้จะช่วยให้เจ้าเปิดคลังสมบัติที่อยู่บริเวณกลางโพรงได้" },
        progress = { "41:1754982660:1413641426", "มีรูกุญแจสามรูสลักอยู่บนหิน" },
        completion = { "117:1375091945:1009925083", "เมื่อสอดกุญแจทั้งสามเข้ารูที่ตรงกัน ไอเทมจำนวนหนึ่งก็ปรากฏขึ้นท่ามกลางแสงเรืองรอง" },
        required = { [5689] = { "13:1092413374:1338666119", "กุญแจของผู้หลับใหล" }, [5690] = { "8:2091806641:218600732", "กุญแจกรงเล็บ" }, [5691] = { "10:670406425:806030950", "กุญแจสุสานเนินดิน" } },
        steps = { { "13:1092413374:1338666119", "กุญแจของผู้หลับใหล" }, { "8:2091806641:218600732", "กุญแจกรงเล็บ" }, { "10:670406425:806030950", "กุญแจสุสานเนินดิน" } },
    },
    [1361] = { -- Regthar Deathgate
        title = { "17:1361512321:724407714", "Regthar Deathgate" },
        objective = { "29:848593628:1009342127", "คุยกับ Regthar Deathgate" },
        description = { "283:71929555:677668828", "Regthar Deathgate นักรบแห่ง Horde กำลังรับสมัครคนไปปฏิบัติภารกิจใน Desolace หากอยากอาสา จงไปคุยกับเขา เขาประจำอยู่ในกลุ่มบังเกอร์ทางตะวันตกของ Crossroads ใน Barrens\n\nลับอาวุธให้คมด้วย Desolace เป็นดินแดนที่สงครามฉีกกระชาก" },
        completion = { "129:522868989:2128615113", "ใช่ ข้ากำลังรับสมัคร ภารกิจนี้จะพาเข้า Desolace ไปต่อต้านเซนทอร์ที่นั่น ข้าจะอธิบายสั้น ๆ เพื่อให้เจ้าออกเดินทางได้ทันที" },
    },
    [1362] = { -- The Kolkar of Desolace
        title = { "22:913060226:1309131061", "Kolkar แห่ง Desolace" },
        objective = { "59:265802422:1287601972", "คุยกับ Felgur Twocuts ที่ Ghost Walker Post ใน Desolace" },
        description = { "450:1115382562:1894911926", "เซนทอร์ Kolkar อาศัยใน Desolace และกองกำลังของพวกมันแผ่มาถึง Barrens เรารู้เรื่องนี้และส่งคนของ Horde จัดการพวกมันที่นี่แล้ว\n\nแต่ตราบใดที่เซนทอร์ใน Desolace ยังแข็งแกร่ง พวกมันก็ยังเป็นภัย ถึงเวลาขจัดภัยนั้นแล้ว\n\nไปคุยกับ Felgur Twocuts ที่ Ghost Walker Post ใน Desolace เขาถูกส่งไปสืบข่าวเรื่องเซนทอร์ และคงรู้วิธีจัดการ Kolkar แห่ง Desolace ได้ดีที่สุด" },
        completion = { "231:1527758659:1009547556", "เจ้ามาตามคำสั่ง Regthar หรือ? เช่นนั้นก็มาเพื่อจัดการเซนทอร์ ดี\n\nหวังว่าเจ้าพักมาพอแล้ว ข้าไม่รู้ว่าสงครามกับเซนทอร์จะจบอย่างไร แต่รู้ว่าการต่อสู้จะยืดเยื้อ\n\nนั่งลงแล้วฟัง" },
    },
    [1365] = { -- Khan Dez'hepah
        title = { "14:285123127:826579860", "Khan Dez'hepah" },
        objective = { "58:1040706061:2070859415", "นำ Khan Dez'hepah's Head ไปให้ Felgur Twocuts ใน Desolace" },
        description = { "476:1618965907:121888656", "Kolkar ไม่ใช่เซนทอร์เผ่าเดียวใน Desolace มีหลายเผ่าเร่ร่อนบนที่ราบแห้งแล้งนี้ ต่อสู้และล้มตายด้วยน้ำมือกันเอง นับว่าดีที่พวกมันรบกัน เพราะพวกมันแข็งแกร่งและโหดเหี้ยม หากรวมกำลังโจมตีเรา ย่อมเป็นศัตรูที่น่ากลัว\n\nเราต้องจัดการก่อนพวกมันรวมตัวกัน\n\nภารกิจแรกของเจ้าคือสร้างความปั่นป่วนให้เผ่า Kolkar ด้วยการฆ่าผู้นำ Khan Dez'hepah\n\nKolkar Village อยู่ทางตะวันออกเฉียงเหนือ ไปเถอะ ขอให้โชคเข้าข้างเจ้า" },
        progress = { "N 35:1603228588:608120339", "{name} เจ้าเอาชนะ Khan Dez'hepah แล้วหรือยัง?" },
        completion = { "222:907467502:689541119", "ทำได้ดี การจู่โจม Kolkar อย่างรวดเร็วครั้งนี้แสดงพลังได้อย่างมีประสิทธิภาพ และพลังคือสิ่งที่เซนทอร์เข้าใจดีที่สุด\n\nความตายของผู้นำ Kolkar จะไม่เพียงทำให้เผ่านี้ปั่นป่วน แต่ยังทำให้เผ่าอื่นชะงักด้วย" },
        required = { [6066] = { "21:1949908188:1878262995", "ศีรษะของข่าน Dez'hepah" } },
        steps = { { "21:1949908188:1878262995", "ศีรษะของข่าน Dez'hepah" } },
    },
    [1480] = { -- The Corrupter
        title = { "13:2076373758:1475890414", "ผู้แพร่ความเสื่อมทราม" },
        objective = { "63:1070387198:223682160", "นำ Flayed Demon Skin ไปให้ Maurin Bonesplitter ใน Desolace" },
        description = { "348:1772442534:1496607605", "หนังที่ฉีกขาดส่งกลิ่นเน่า และยืดหยุ่นอย่างน่าประหลาดทั้งที่ดูแห้งเปราะ\n\nเมื่อคลี่ออก เจ้าก็เห็นเครื่องหมายสีแดงเป็นภาษาบางอย่างอยู่ด้านหนึ่งชัดเจน ด้านล่างมีสัญลักษณ์ที่ชัดเจนมาก คาดว่าน่าจะเป็นลายเซ็น\n\nบางที Maurin อาจอธิบายเรื่องนี้ได้มากกว่านี้?" },
        progress = { "215:591779759:1432702761", "Burning Blade เริ่มตระหนักแล้วว่าตนอ่อนแอเพียงใด เวทมนตร์ช่างน่าสมเพช กำลังก็อ่อนด้อย\n\nพลังที่มีมาจากผู้ที่พวกมันรับใช้เท่านั้น หาใช่ความเข้าใจในพลังและความรู้ที่แท้จริงไม่" },
        completion = { "40:175304924:437147391 N 224:2075461891:920801472", "อืม รูนเหล่านี้เป็นภาษาจริง ๆ {name} เป็นภาษาเก่าแก่ ดูคล้ายภาษา Eredun อยู่บ้าง แต่แตกต่างกันมาก หากข้าไม่ผิด นี่คือสัญญาบางชนิด... ตรงนี้ ใช่ สัญลักษณ์นี้เป็นลายเซ็นของปีศาจ Lord Azrethoc" },
        required = { [20310] = { "17:587391705:1785674285", "หนังปีศาจที่ถลกแล้ว" } },
        objectiveLabels = {
            item = { ["Flayed Demon Skin"] = "หนังปีศาจที่ถลกแล้ว" },
        },
    },
    [1481] = { -- The Corrupter
        title = { "13:2076373758:1475890414", "ผู้แพร่ความเสื่อมทราม" },
        objective = { "63:985497229:491469941", "นำ Shadowstalker Scalp ไปให้ Maurin Bonesplitter ใน Desolace" },
        description = { "477:693248149:567628488", "ข้าเชื่อว่าจะตามหาจอมปีศาจตนนี้ได้หากมีส่วนประกอบที่เหมาะสม\n\nหากมันทรงพลังอย่างที่ข้าสงสัยจริง ก็ต้องเก็บของจากสัตว์ร้ายอันตราย แต่เจ้าปฏิบัติงานในนาม Warchief ข้าจึงมั่นใจว่าจะรับภารกิจ\n\nก่อนอื่นต้องทำลายมนตร์ป้องกันการสอดส่องของมัน ข้าต้องใช้หนังศีรษะของซาเทอร์ แต่ไม่ใช่ตัวไหนก็ได้ ต้องเป็น Hatefury shadowstalker\n\nหาพวกมันในซากโบราณทางตะวันออกเฉียงเหนือของ Desolace" },
        progress = { "36:329650353:1013368056 C 189:782037174:2027275898", "อย่านำหนังศีรษะผิดชนิดมา {class} ใช้ส่วนประกอบผิดอาจทำให้เราตาย จอมปีศาจอาจลงมนตร์เตรียมไว้ฆ่าผู้ที่พยายามสอดส่องมัน\n\nโชคชะตาทำให้ข้าเจ็บปวดมามากพอแล้ว" },
        completion = { "44:83814282:634387886 C 286:1948748300:1722584014", "shadowstalkers ฆ่าเจ้าไม่ได้ {class} น่าประทับใจ... น่าประทับใจจริง ๆ\n\nหนังศีรษะนี้เหมาะกับคาถาของข้า ระหว่างเจ้าไม่อยู่ ข้าเก็บส่วนประกอบอื่นมาได้แล้ว\n\nเกือบพร้อมแล้ว ข้าขาดเพียงสื่อกลางของคาถา สิ่งที่จะฉายภาพจอมปีศาจและที่อยู่ของมัน" },
        required = { [6441] = { "19:1004745495:1818290720", "หนังศีรษะของ Shadowstalker" } },
        steps = { { "19:1004745495:1818290720", "หนังศีรษะของ Shadowstalker" } },
    },
    [1482] = { -- The Corrupter
        title = { "13:2076373758:1475890414", "ผู้แพร่ความเสื่อมทราม" },
        objective = { "59:206361809:1272781409", "นำ Oracle Crystal ไปให้ Maurin Bonesplitter ใน Desolace" },
        description = { "423:602831558:891094303", "Oracle Crystal น่าจะใช้ได้ดี นากาสร้างมันไว้ให้เหล่านักพยากรณ์ใช้\n\nทางตะวันตกเฉียงเหนือเลียบชายฝั่งมีแนวปะการังกว้างใหญ่ นากาใช้เป็นที่อยู่เมื่อเข้ามาใกล้ฝั่ง เจ้าจะพบนักพยากรณ์ที่นั่น Slitherblade อันตรายและไม่ต้อนรับผู้บุกรุก จงระวังและรีบไป\n\nเมื่อกลับมา เราจะเริ่มตามหาจอมปีศาจ Azrethoc กัน" },
        progress = { "35:1124364247:47452483 C 233:978128415:1716817005", "ข้าพร้อมรับ Oracle Crystal แล้ว {class} หากหาและทำลาย Lord Azrethoc ได้ เราทั้งคู่จะได้รับความโปรดปรานจาก Warchief อย่างมาก เราควรร่วมมือและรีบลงมือ เพื่อให้บรรลุเป้าหมายของตนและเป็นที่พอใจของ Warchief" },
        completion = { "207:373883098:551437709 C 63:2028762711:1543983689", "Oracle Crystal อันล้ำค่า... ไร้ตำหนิ... งดงาม จริงแท้\n\nเราจะเริ่มทันที การหาจอมปีศาจควรเป็นงานสำคัญที่สุด และการฆ่ามันต้องทุ่มเทอย่างเต็มที่\n\nถอยไปหน่อย {class} มาดูกันว่าปีศาจตนนี้เป็นอะไรและอยู่ที่ใด" },
        required = { [6442] = { "14:1147302571:988089305", "ผลึกพยากรณ์" } },
        steps = { { "14:1147302571:988089305", "ผลึกพยากรณ์" } },
    },
    [1484] = { -- The Corrupter
        title = { "13:2076373758:1475890414", "ผู้แพร่ความเสื่อมทราม" },
        objective = { "39:1307726133:905227120", "คุยกับ Takata Steelblade ใน Desolace" },
        description = { "365:1357122358:10577622", "สัตว์ร้ายตนนี้อันตรายกว่าที่ข้าคาดมาก Takata คงสงสัยว่าข้ารับมือมันไหวหรือไม่ และหากไม่บอกสิ่งที่เพิ่งเกิดขึ้นก็จะเป็นการหยามเกียรติเขา\n\nไปคุยกับนักดาบ บอกว่าเจ้ายินดีสังหารปีศาจหากเขาอนุญาต แต่อย่ารุกเร้าจนเกินไป ให้เขาคิดว่าเป็นความคิดของตนเองจะดีกว่า" },
        completion = { "397:461001633:1440130698", "ข้าเห็นสิ่งที่เกิดขึ้นระหว่าง Maurin กับจอมปีศาจแล้ว แม้เป็นเพียงภาพปรากฏ มันก็ดูมีพลังมากกว่าสหายวอร์ล็อกของข้า เขาจะเอาชนะมันไหวหรือ? หากข้าไปเองคงรับใช้ Warchief ได้ดีกว่า แต่ข้ามีหน้าที่ที่นี่ หากทิ้งหน้าที่ไปต่อสู้ความชั่วร้ายเพื่อเกียรติของตนเอง ก็จะทำให้เผ่าอับอาย" },
    },
    [1488] = { -- The Corrupter
        title = { "13:2076373758:1475890414", "ผู้แพร่ความเสื่อมทราม" },
        objective = { "83:425906364:21153911", "ฆ่า Lord Azrethoc และ Jugkar Grim'rod แล้วกลับไปหา Takata Steelblade ใน Desolace" },
        description = { "417:428928079:1778900043", "แม้ข้าไม่รู้เรื่อง Lord Azrethoc แต่เห็นด้วยกับ Maurin ว่าต้องหยุดมัน โดยเฉพาะหากมันพยายามครอบงำ Burning Blade เพื่อทำตามเป้าหมายของตน\n\nเจ้าแสดงให้เห็นแล้วว่าอยากช่วย Warchief ข้าเชื่อใจให้เจ้ารวบรวมกลุ่มไปฆ่าจอมปีศาจกับสมุนวอร์ล็อกของมัน\n\nเมื่อพร้อม จงมุ่งตรงลงใต้ แล้วกลับมาหาข้าเมื่อกำจัดภัยนั้นแล้ว" },
        progress = { "46:539079195:1155553374 N 227:141401080:357364385", "เกียรติจงมีแด่ Horde และความตายจงมีแด่ศัตรู {name}!\n\nปีศาจใน Desolace เป็นภัยยิ่งกว่าครั้งใด ความหวังที่จะได้กลับไปหา Warchief ริบหรี่ลง เมื่อสัตว์โสมมพวกนี้ปรากฏมากขึ้นเรื่อย ๆ\n\nบางครั้งข้าก็หวังว่าเราต้องจัดการเพียงเซนทอร์เท่านั้น" },
        completion = { "29:1558558908:800108635 N 236:1897537953:1505763428", "นี่คือชัยชนะอันยิ่งใหญ่ของพวกเราทุกคน {name} มาร่วมยินดีกับความสำเร็จของเจ้าเถอะ ตอนนี้ข้าเชื่อว่าอนาคตของเราที่นี่ไม่มืดมนอย่างที่เคยคิด\n\nปีศาจจะถูกสังหาร Burning Blade จะล้มเหลว และสักวันเราอาจมีสถานที่ปลอดภัยที่เรียกว่าบ้านได้อีกครั้ง" },
        objectiveLabels = {
            monster = { ["Lord Azrethoc slain"] = "ปราบ ลอร์ด Azrethoc", ["Jugkar Grim'rod slain"] = "ปราบ Jugkar Grim'rod" },
        },
    },
    [1918] = { -- The Befouled Element
        title = { "20:1162071646:1255563351", "ธาตุที่แปดเปื้อน" },
        objective = { "83:1184174271:1077023210", "นำ Befouled Water Globe ไปให้ Mastok Wrilehiss ที่ Splintertree Post ใน Ashenvale" },
        description = { "444:426553641:1842697730", "ธาตุที่ถูกฆ่าทิ้งลูกแก้วน้ำเรืองแสงจ้าไว้ สิ่งที่อยู่ภายในชวนขยะแขยงอย่างยิ่ง คงพอคาดได้ว่าสิ่งที่ทำให้น้ำใน Mystral Lake แปดเปื้อนน่าจะอยู่ในลูกแก้วด้วย\n\nไม่ใช่เรื่องที่ใคร ๆ รู้ว่าผู้ใดสนใจของเช่นนี้ บางที Mastok Wrilehiss ที่ Splintertree Post ผู้ส่งเจ้าไปทะเลสาบแต่แรก อาจมีความคิดดี ๆ" },
        progress = { "23:2094456976:1725103984", "ว่าไง เจ้าต้องการอะไร?" },
        completion = { "309:1536408592:1235875413 N 1:63:63", "เจ้าพบก้อนน้ำสกปรกแล้วคิดจะเอามาให้ข้าหรือ? ข้าดูเป็น Earthen Ring หรืออย่างไร?\n\nแต่ที่จริงก็ทำให้ข้าคิดได้... บางทีเจ้าคงต้องให้ Earthen Ring ช่วยเรื่องนี้ หากช่วยแก้สถานการณ์ที่ทะเลสาบได้ถาวร ข้าก็เห็นด้วยเต็มที่\n\nเจ้ารู้จัก Earthen Ring ไหม {name}?" },
        required = { [16408] = { "20:1027649815:845629786", "ลูกแก้วน้ำแปดเปื้อน" } },
        steps = { { "20:1027649815:845629786", "ลูกแก้วน้ำแปดเปื้อน" } },
    },
    [5381] = { -- Hand of Iruxos
        title = { "14:910493710:1891075826", "หัตถ์แห่ง Iruxos" },
        objective = { "131:1225564886:588305325", "นำ Demon Box จาก Thunder Axe Fortress กลับไปให้ Taiga Wisemane ที่ Shadowprey Village พร้อมกับ Demon Pick" },
        description = { "208:768578916:2026382171 N 97:151282774:2054543544", "Burning Blade ครอบครอง Demon Box ภายในบรรจุ Hand of Iruxos อันทรงพลัง พวกมันใช้เปิดประตูปีศาจที่ Mannoroc Coven เราต้องหยุดฝูงปีศาจที่หลั่งไหลเข้าสู่โลก {name}!\n\nใช้ Demon Pick นี้กับผลึกสีแดงใน Thunder Axe Fortress เพื่อให้เข้าถึง Demon Box ได้" },
        progress = { "N 28:2038770410:986712993", "{name} เจ้าได้ Demon Box มาหรือยัง?" },
        completion = { "34:921683547:1808156856 C 64:560995792:1359867358", "อา Demon Box ส่งมาให้ข้า {class} ข้าจะเปิดมัน... และเผยให้เจ้าเห็น Hand of Iruxos" },
        required = { [13542] = { "9:506022515:454815831", "กล่องปีศาจ" }, [14523] = { "10:1436010253:1630183542", "เครื่องเจาะปีศาจ" } },
        steps = { { "9:506022515:454815831", "กล่องปีศาจ" }, { "10:1436010253:1630183542", "เครื่องเจาะปีศาจ" } },
    },
    [5386] = { -- Catch of the Day
        title = { "16:606958720:2031192772", "ปลาที่จับได้วันนี้" },
        objective = { "93:1610634158:1418555800", "คุยกับ Jinar'Zillen ที่ Shadowprey Village แล้วนำ Bloodbelly fish 2 ตัว ไปให้ Nataka Longhorn" },
        description = { "442:1974445819:893009257", "Ghost Walker Post ไม่ได้กลิ่นปลาปรุงสุกมานานแล้ว โทรลล์ที่ Shadowprey Village จับปลาเก่งที่สุด... แต่กิจกรรมของเซนทอร์ทำให้ข้ามีเวลาไปหาพวกเขาน้อยนัก อืม...\n\nช่วยไป Shadowprey Village แทนข้าที คุยกับชาวประมง Jinar'Zillen แล้วนำปลา Bloodbelly ของโปรดข้ากลับมา ถนนทางใต้จากที่นี่จะพาเลี้ยวไปตะวันตกถึงหมู่บ้านโทรลล์" },
        progress = { "106:28614718:2102819976", "แค่นึกถึงปลา Bloodbelly ทอด กีบข้าก็สั่น น้ำลายก็ไหล... เจ้าพกมาบ้างไหม?" },
        completion = { "18:1726901168:1351323986 N 156:1414625657:753871130", "เจ้าช่วยชีวิตข้าไว้ {name}! ปลา Bloodbelly พวกนี้ดูน่ากินจนแทบอยากกินดิบ\n\n<Nataka เริ่มน้ำลายไหล>\n\nเอาล่ะ เลือกของชิ้นหนึ่งเป็นค่าปลาพวกนี้ได้เลย" },
        required = { [13546] = { "15:1756723350:1266984093", "ปลา Bloodbelly" } },
        steps = { { "15:1756723350:1266984093", "ปลา Bloodbelly" } },
    },
    [5421] = { -- Fish in a Bucket
        title = { "16:1771861334:1442596672", "ปลาในถัง" },
        progress = { "374:1885189188:49522946", "ข้าจะให้รางวัลใครก็ตามที่ช่วยให้ชีวิตสบายขึ้น... ข้าชอบทำงานให้น้อยที่สุด เพื่อนเอ๋ย!\n\nใต้ท่าเรือที่ Shadowprey Village ข้าวางกับดักหอยไว้มากมาย ถ้าเจ้ามีน้ำใจทำงานแทนและเก็บหอยมาให้ ข้าจะให้สิ่งที่เจ้าต้องการเป็นรางวัล... เข้าใจใช่ไหมเพื่อน? ทุกครั้งที่นำหอยมาให้ห้าตัว ข้าจะให้ปลา Bloodbelly ชั้นดีหนึ่งตัว!" },
        completion = { "95:1433287431:1702296074", "เยี่ยมเลยเพื่อน ไม่มีอะไรดีเท่างานเสร็จ โดยเฉพาะถ้าคนอื่นเป็นคนทำ... จริงไหม?" },
        description = { "374:1885189188:49522946", "ข้าจะให้รางวัลใครก็ตามที่ช่วยให้ชีวิตสบายขึ้น... ข้าชอบทำงานให้น้อยที่สุด เพื่อนเอ๋ย!\n\nใต้ท่าเรือที่ Shadowprey Village ข้าวางกับดักหอยไว้มากมาย ถ้าเจ้ามีน้ำใจทำงานแทนและเก็บหอยมาให้ ข้าจะให้สิ่งที่เจ้าต้องการเป็นรางวัล... เข้าใจใช่ไหมเพื่อน? ทุกครั้งที่นำหอยมาให้ห้าตัว ข้าจะให้ปลา Bloodbelly ชั้นดีหนึ่งตัว!" },
        required = { [13545] = { "9:1254974737:1989536670", "หอย" } },
        objectiveLabels = {
            item = { ["Shellfish"] = "หอย" },
        },
    },
    [5581] = { -- Portals of the Legion
        title = { "21:1450270762:1002440486", "ประตูแห่ง Legion" },
        objective = { "86:409232860:1877983566", "ปิด Portals 6 แห่งที่ Mannoroc Coven แล้วกลับไปหา Taiga Wisemane ที่ Shadowprey Village" },
        description = { "286:624289939:35883735 N 40:706444184:954809952", "ดูนี่ Hand of Iruxos ช่างสยดสยองจริง ๆ\n\nเจ้าต้องถือมันไว้จึงจะปิดประตูปีศาจที่ Mannoroc Coven ได้ และนั่นคืองานที่ข้าขอให้ทำ ภัยปีศาจกำลังเพิ่มขึ้น เราต้องปิดประตูเพื่อหยุดพวกมันเข้าสู่โลก ขอให้โชคดี {name}... ระวังผู้พิทักษ์ประตูด้วย" },
        progress = { "54:2021816417:934163047", "เจ้าปิดประตูปีศาจที่ Mannoroc Coven แล้วหรือยัง?" },
        completion = { "25:1450046495:820949271 N 105:358645368:1293962628", "เจ้าสมควรได้รับคำยกย่อง {name} ความพยายามของเจ้าช่วยต่อสู้ภัยปีศาจได้มาก และทำให้ Azeroth ทั้งหมดปลอดภัยขึ้น" },
        required = { [14547] = { "14:910493710:1891075826", "มือของ Iruxos" } },
        steps = { { "16:1261671296:209325001", "ปิดประตูมิติ" } },
        objectiveLabels = {
            item = { ["Hand of Iruxos"] = "มือของ Iruxos" },
        },
    },
    [5763] = { -- Hunting in Stranglethorn
        title = { "24:1899421165:566296185", "การล่าใน Stranglethorn" },
        objective = { "60:1426139935:1031417519", "นำ Roon's Kodo Horn ไปให้ Hemet Nesingwary ใน Stranglethorn" },
        description = { "472:1439583196:1022123625", "นานมาแล้ว คนแคระผู้หนึ่งมาที่ดินแดนนี้ ชื่อ Hemet เขาอยากล่าสัตว์ใหญ่ ฝีมือปืนยาวของเขายอดเยี่ยมจนน่าทึ่ง เราใช้เวลาหลายวันออกล่าด้วยกัน จนลืมแม้แต่ความเป็นอริระหว่างเผ่าพันธุ์\n\nเมื่อเขาออกจาก Desolace ไป Stranglethorn ข้าตั้งใจว่าสักวันจะเชิญเขากลับมาล่าด้วยกันอีก ตอนนี้ถึงเวลาแล้ว\n\nนำเขาโคโดนี้ไปให้ Hemet เขาจะรู้ว่ามาจากข้า หาเขาได้ใน Stranglethorn ทางเหนือของ Grom'gol Base Camp" },
        progress = { "5:950312229:1059219551 C 49:1084833109:1682527639", "นั่งก่อน {class} อีกไม่นานเจ้าก็ต้องบุกป่าต่อแล้ว" },
        completion = { "199:48784681:20809712 N 85:1511828189:1137874714", "อา เขานี้เป็นของทอเรนชื่อ Roon Wildmane เราเคยสนุกกับการล่าสัตว์ใน Desolace ด้วยกัน งั้น Roon เชิญข้ากลับไปสินะ?\n\nตอนนี้เรายังติดพันอยู่ในป่า แต่ขอบใจ {name} บางทีการเดินทางครั้งต่อไปของข้าอาจพากลับ Desolace ดินแดนเซนทอร์" },
        required = { [14546] = { "16:902477516:1360941752", "เขาโคโดของ Roon" } },
        steps = { { "16:902477516:1360941752", "เขาโคโดของ Roon" } },
    },
    [5881] = { -- Calling in the Reserves
        title = { "23:1595198283:52007927", "เรียกกำลังสำรอง" },
        objective = { "92:121424641:1531722836", "Maggran ขอให้เจ้าส่งจดหมายให้ Grish Longrunner ที่ Great Lift ใน Barrens" },
        description = { "449:1807536943:486404630", "Horde ดูแลให้ทหารของเรามีเรี่ยวแรงพร้อมเสมอ... ตั้งแต่สงครามใหญ่ เราก็รุ่งเรืองใน Kalimdor\n\nข้ามีเรื่องให้ช่วย เด็กหนุ่มชื่อ Grish Longrunner กำลังเฝ้า Great Lift ทางใต้ของ Barrens นำจดหมายนี้ไปให้เขา ในนั้นบอกว่าข้าส่งนักรบสำรองไปผลัดเวร เพื่อให้เขาได้เยี่ยมครอบครัว เขาขอเรื่องนี้ไว้นานแล้ว คงยินดีที่ได้ข่าว" },
        progress = { "39:854350839:29772105", "เจ้ามีข่าวจาก Maggran Earthbinder หรือ?" },
        completion = { "137:87163376:810034968", "ข่าวดีจริง ๆ! ข้านั่งเฝ้ากองไม้นี้มานานเกินไปแล้ว คราวนี้จะได้อยู่กับครอบครัวสักพัก... ไชโย!" },
        required = { [16189] = { "24:1482505004:2093120873", "จดหมายแจ้งกำลังเสริมของ Maggran" } },
        steps = { { "24:1482505004:2093120873", "จดหมายแจ้งกำลังเสริมของ Maggran" } },
    },
    [6142] = { -- Clam Bait
        title = { "9:1033545875:1451261982", "เหยื่อหอย" },
        objective = { "94:57818636:102178767", "หา Soft-shelled Clam Meat 10 ชิ้น แล้วนำกลับไปให้ Mai'Lahii ที่ Shadowprey Village" },
        description = { "34:1383465599:1424245360 C 343:1410329274:1837296290", "เจ้าดูเหมือนชาวประมงนะ {class}! ข้ารักการตกปลา ทำมาตลอดชีวิต เหยื่อที่ดีที่สุดคือเนื้อหอยเปลือกนิ่ม ปลาอดใจไม่ไหวเลย รู้ไหม?\n\nทางเหนือมีซากเรืออยู่นอกชายฝั่ง แถวนั้นมีหอยเปลือกนิ่มอยู่ทั่ว หากนำเนื้อมาให้ข้า 10 ชิ้น ข้าจะมีของตอบแทน" },
        progress = { "111:1362178270:1257209523", "ข้าอยากออกตกปลาด้วยเนื้อหอยเปลือกนิ่มสด ๆ เต็มทีแล้ว เจ้านำ 10 ชิ้นที่ข้าต้องการมาหรือยัง?" },
        completion = { "178:1724764604:157491685", "เยี่ยมเลยเพื่อน นี่ตรงกับที่หมอผีบอกให้ทำแก้ปวดหัว เขาบอกว่า “Mai'Lahii ไปตกปลาสิ แล้วจะรู้สึกดีขึ้น”\n\nเอาล่ะ ข้ารู้สึกดีขึ้นแล้ว ขอบใจเพื่อน!" },
        required = { [15924] = { "22:1057953601:1678355847", "เนื้อหอยกาบเปลือกนิ่ม" } },
        steps = { { "22:1057953601:1678355847", "เนื้อหอยกาบเปลือกนิ่ม" } },
    },
    [6143] = { -- Other Fish to Fry
        title = { "17:1728345549:373221642", "ยังมีนากาให้สะสาง" },
        objective = { "136:1615314467:1028425744", "ฆ่า Slitherblade Myrmidon 7 ตัว, Slitherblade Naga 7 ตัว และ Slitherblade Sorceresses 5 ตัว แล้วคุยกับ Drulzegar ที่ Shadowprey ใน Desolace" },
        description = { "347:2009236978:2117039424 C 120:149163853:1081956840", "เจ้าอาจเคยได้ยินหรืออาจไม่... ข้ากับลูกเรือออกตกปลาใกล้ Ranazjar Isle ทางเหนือของซากเรือนอกชายฝั่งด้านเหนือ เราเคยไปตกปลาที่นั่นเสมอ แต่ตอนนี้ข้าคิดได้เพียงจะแก้แค้นให้สหายที่ตายไปอย่างไร\n\nเช้าวันหนึ่งนากาโจมตีเรา ฆ่าทุกคนยกเว้นข้า\n\nข้าทนความรู้สึกผิดไม่ไหว {class} อยากให้เจ้าไปจัดการนากาพวกนั้นแทน ข้าจะตอบแทนให้คุ้ม เจ้าช่วยเรื่องนี้ได้ไหม?" },
        progress = { "270:2123548350:1585524834", "ข้ายังได้ยินเสียงพวกเขาร้องขอความช่วยเหลือเมื่อนากาโจมตี หากเข่าไม่เจ็บ ข้าจะไปช่วยเจ้าฆ่านากาบ้าพวกนั้นด้วย!\n\nส่วนมากหาพวกมันได้ลึกลงไปในแนวปะการังใต้น้ำ... ซุ่มซ่อน... วางแผนร้าย..." },
        completion = { "312:163378008:1974096353", "แม้ข่าวว่านากาถูกกำจัดจะน่าพอใจเพียงใด ใจข้าก็ยังว่างเปล่า ตลอดชีวิตที่เหลือ ข้าจะทุ่มเทให้พวกมันตายจนหมด\n\nนี่เพื่อน รางวัลตามสัญญา มันเล็กน้อยเมื่อเทียบกับความสะใจที่รู้ว่านากาชดใช้สิ่งเลวร้ายที่ทำกับลูกเรือข้าแล้ว" },
        objectiveLabels = {
            monster = { ["Slitherblade Myrmidon slain"] = "ปราบ ทหารชั้นยอด Slitherblade", ["Slitherblade Naga slain"] = "ปราบ นากา Slitherblade", ["Slitherblade Sorceress slain"] = "ปราบ แม่มด Slitherblade" },
        },
    },
    [6282] = { -- Harpies Threaten
        title = { "16:1965077924:1038600689", "ภัยจากฮาร์ปี" },
        objective = { "152:1643275313:608781016", "Maggran Earthbinder ที่ Sun Rock Retreat ต้องการให้เจ้าฆ่า Bloodfury Harpies 7 ตัว, Bloodfury Ambushers 7 ตัว, Bloodfury Slayers 7 ตัว และ Bloodfury Roguefeathers 7 ตัว" },
        description = { "356:997273337:169353040 N 1:33:33", "ทอเรนภูมิใจที่เป็นผู้พิทักษ์ผืนดินเหล่านี้ เจ้าคงเดาได้ว่าทำไมข้าจึงกังวลกับจำนวนฮาร์ปีใน Stonetalon\n\nBloodfury เป็นแหล่งที่ทำให้ฮาร์ปีใน Kalimdor เพิ่มจำนวน พวกมันรุกล้ำชีวิตทุกรูปแบบ กีดกันผู้บริสุทธิ์ไม่ให้ออกจากอาณาเขต\n\nข้าต้องการให้เจ้าลดจำนวนฮาร์ปี {name}!", variants = { { "357:1178229861:932194758 N 1:33:33", "ทอเรนภูมิใจที่เป็นผู้พิทักษ์ผืนดินเหล่านี้ เจ้าคงเดาได้ว่าทำไมข้าจึงกังวลกับจำนวนฮาร์ปีใน Stonetalon\n\nBloodfury เป็นแหล่งที่ทำให้ฮาร์ปีใน Kalimdor เพิ่มจำนวน พวกมันรุกล้ำชีวิตทุกรูปแบบ กีดกันผู้บริสุทธิ์ไม่ให้ออกจากอาณาเขต\n\nข้าต้องการให้เจ้าลดจำนวนฮาร์ปี {name}!" } } },
        progress = { "88:1878842175:1158238632 N 135:955090264:709664670", "อย่าท้อกับ Charred Vale สัตว์ร้ายมากมายอยู่บนเนินเหล่านั้น จงเข้มแข็ง {name} แล้วเจ้าจะเอาชนะภัยที่คุกคามชนเผ่าเราได้ ไปลงมืออย่างเด็ดขาด ลูกหลานของเราจะได้ไม่ต้องรู้จักความชั่วร้ายที่เคยมี" },
        completion = { "152:1601860671:466386855", "ข่าวดีเยี่ยมจริง ๆ! เล่าอีกสิว่าเจ้าทำให้หัวใจเย็นชาของฮาร์ปีโสมมพวกนั้นหวาดกลัวอย่างไร Bloodfury ถูกโจมตีอย่างหนักแล้ว!" },
        objectiveLabels = {
            monster = { ["Bloodfury Harpy slain"] = "ปราบ ฮาร์ปี Bloodfury", ["Bloodfury Ambusher slain"] = "ปราบ นักซุ่มโจมตี Bloodfury", ["Bloodfury Slayer slain"] = "ปราบ นักสังหาร Bloodfury", ["Bloodfury Roguefeather slain"] = "ปราบ ฮาร์ปีขนนอกคอก Bloodfury" },
        },
    },
    [6283] = { -- Bloodfury Bloodline
        title = { "19:2006679369:749837341", "สายเลือด Bloodfury" },
        objective = { "108:335783059:571333088", "Maggran ที่ Sun Rock Retreat ขอให้เจ้าฆ่า Bloodfury Ripper และนำซากของนางมาเป็นหลักฐาน" },
        description = { "386:84633195:660547623", "แค่ลดจำนวน Bloodfury Harpies ยังไม่พอ วิธีรักษาโรคร้ายนี้อย่างแท้จริงคือต้องฆ่าผู้นำ Bloodfury Ripper!\n\nนางแทบเป็นราชินีของสัตว์โสมมเหล่านั้น ฆ่านางแล้วจำนวนของพวกมันย่อมลดลง\n\nกลับเข้า Charred Vale ไปหานางตามเนินด้านตะวันตก เอาชนะนางไม่ง่าย แต่รางวัลก็คุ้มค่า" },
        progress = { "202:1645588310:1560218790", "Bloodfury Ripper เป็นสัตว์ร้ายกาจ! หาได้ตามแนวเนินด้านตะวันตกของ Charred Vale\n\nหากขาดนาง Bloodfury จะหมดหนทาง... เราคงกำจัดพวกมันได้ถาวร!" },
        completion = { "287:258008970:1097337757", "ข้ารู้สึกแล้วว่าความโกรธกำลังเลือนหาย จะใช้เวลาทำอะไรดีนะ? การรู้ว่าความชั่วร้ายเคลื่อนไหวใกล้ผืนดินของข้าทำให้คิดไม่หยุด แต่ตอนนี้ทุกอย่างเงียบแล้ว บางทีอาจเป็นเรื่องดี... ข้าจะได้มุ่งถึงสิ่งดีงามอย่างที่ทอเรนทุกคนควรทำ\n\nโปรดรับสิ่งนี้เป็นรางวัลสำหรับความลำบากของเจ้า" },
        required = { [16190] = { "26:400816274:1486011543", "ซาก Bloodfury Ripper" } },
        steps = { { "26:400816274:1486011543", "ซาก Bloodfury Ripper" } },
    },
    [6284] = { -- Arachnophobia
        title = { "13:456931386:340668665", "หวาดกลัวแมงมุม" },
        objective = { "73:2036264203:1153252259", "ฆ่า Besseleth แล้วนำ Besseleth's Fang ไปให้ Maggran ที่ Sun Rock Retreat" },
        description = { "369:366031935:1261518487", "คำเตือน: ผู้เข้า Sishir Canyon ทางตะวันตกจากที่นี่ต้องรับความเสี่ยงเอง\n\nBesseleth กับลูกแปดขาแห่งป่าของนางยึดหุบเขานี้เป็นรังใยแมงมุม\n\nMaggran Earthbinder ที่ Sun Rock Retreat ตั้งค่าหัว Besseleth ไว้ ฆ่านางและนำหลักฐานไปให้ Maggran แล้วเจ้าจะได้รับรางวัลที่กำจัดภัยแปดขานี้" },
        progress = { "316:1442907258:1273982996", "Besseleth เป็นนักล่าที่โหดเหี้ยม... ข้าห่วงคนที่เดินทางบน Webwinder Path ตอนกลางคืน นั่นคือเวลาที่นางกับลูกออกล่าผู้เดินทางผู้บริสุทธิ์ ข้าเองเคยตกเป็นเหยื่อเขี้ยวมรณะยาวสองฟุตของนาง แต่โชคดีที่สู้ไล่ไปและหนีถึงที่ปลอดภัยได้ ข้ายอมทุกอย่างเพื่อเห็นอสูรนั่นถูกทำลาย" },
        completion = { "14:988798844:158890021 N 268:1103974062:785235114", "ล่าได้ดี {name}! Besseleth เป็นนักล่าเก่าแก่ในแถบนี้... ข้าไม่คิดถึงมันหรอก รับรางวัลนี้ในฐานะผู้พิทักษ์ป่า\n\n<Maggran ลูบแผลที่ Besseleth ทำไว้>\n\nบางทีผู้คนจะเดินทางมา Sun Rock Retreat มากขึ้น โดยไม่ต้องกลัวสิ่งที่ซ่อนในความมืด" },
        required = { [16192] = { "16:278705841:1643321572", "เขี้ยวของ Besseleth" } },
        steps = { { "16:278705841:1643321572", "เขี้ยวของ Besseleth" } },
    },
    [6301] = { -- Cycle of Rebirth
        title = { "16:1129804290:1943712451", "วัฏจักรแห่งการเกิดใหม่" },
        objective = { "71:736277726:1252477698", "Tammra Windfield ที่ Sun Rock Retreat ต้องการให้เจ้าเก็บ Gaea Seeds 10 เมล็ด" },
        description = { "134:1539765149:1472048765 N 269:1867599032:1235552085", "ความโลภของอุตสาหกรรมและสงครามไม่สิ้นสุดทำลาย Stonetalon มีเพียงพรจากพระแม่ธรณีที่รักษาบาดแผลนี้ได้\n\n{name} ข้าต้องการให้เจ้าหาเมล็ดพิเศษ Gaea Seed พบเฉพาะใน Stonetalon Mountains ทางเหนือของ Sun Rock Retreat ริมน้ำ Mirkfallon Lake\n\nเมื่อเจ้าส่งเมล็ดให้ ข้าจะอาบพลังชามานเพื่อเร่งการเติบโตของมัน" },
        progress = { "189:1572983360:1544405769 C 1:63:63", "การทำลายไม่หยุดจากสงครามและผู้แสวงหากำไรจากไม้ทำให้ข้าเจ็บปวด เพื่อช่วยวัฏจักรเกิดใหม่และฟื้นผืนดิน ข้าต้องใช้ Gaea Seeds เจ้าหามาหรือยัง {class}?" },
        completion = { "4:1110228981:147916455 N 168:1317857325:1806160441", "อา {name} เจ้าได้ Gaea Seeds มาแล้ว ดูให้ดีว่าพรแห่งพระแม่ธรณีทำให้เมล็ดชีวิตเล็ก ๆ เหล่านี้งอกงามได้อย่างไร\n\n<Tammra เริ่มสวด>" },
        required = { [16205] = { "9:795645890:1466191134", "เมล็ดพันธุ์ Gaea" } },
        steps = { { "9:795645890:1466191134", "เมล็ดพันธุ์ Gaea" } },
    },
    [6381] = { -- New Life
        title = { "8:875433483:1836699751", "ชีวิตใหม่" },
        objective = { "122:2075773884:167221857", "ปลูก Gaea Seeds 10 เมล็ดใน Gaea Dirt Mounds แล้วนำ Enchanted Gaea Seeds ที่เหลือกลับไปให้ Tammra ที่ Sun Rock Retreat" },
        description = { "18:42493138:546937196 C 280:277467262:698275095 N 105:1176300343:1740406378", "อย่างที่เจ้าเห็น {class} แม้ผืนดินเจ็บปวด แต่วัฏจักรชีวิตก็ทรงพลัง ตอนนี้เราต้องช่วยมัน เจ้าต้องปลูกเมล็ดตรงใจกลางความเสียหาย ทางตะวันตกใน Charred Vale ระวังฮาร์ปีกับธาตุไฟที่โกรธแค้นยังรังควานผืนดินที่บอบช้ำ\n\n{name} นำ Enchanted Gaea Seeds เหล่านี้ไปปลูกในกองดินอุดมสมบูรณ์ วัฏจักรชีวิตต้องดำเนินต่อ!" },
        progress = { "285:969249204:1395980292", "เมล็ดที่เจ้าปลูกแข็งแกร่ง ต้านความเสื่อมทรามและเปิดที่ให้ชีวิตอื่นหยั่งราก มันจะเติบโตต่อไป เริ่มจากป้องกันความเสื่อมทรามและรักษาผืนดินที่บอบช้ำ แล้ววันหนึ่งจะทำให้ Stonetalon กลับเป็นป่าเขียวชอุ่มอีกครั้ง\n\nเจ้าปลูก Gaea Seeds ทั้งหมดแล้วหรือยัง?" },
        completion = { "224:325168883:776026141 N 56:251660295:1625634540 C 81:1627610063:826064712", "นี่คือชัยชนะอันยิ่งใหญ่ของผืนดิน เมื่อเวลาผ่านไป สิ่งอื่นจะตามมา Venture Co. จะเก็บเลื่อยกับขวาน วิญญาณไฟที่โกรธเกรี้ยวจะสงบ และผืนดินจะผลักฮาร์ปีออกไป\n\nเมื่อถึงตอนนั้นเท่านั้น {name} Stonetalon จึงจะสงบอย่างแท้จริง\n\nเจ้าทำได้ดี {class} เลือกไอเทมชิ้นหนึ่งเพื่อแทนคำขอบคุณสำหรับชีวิตใหม่ที่เจ้าสร้างขึ้นที่นี่วันนี้" },
        required = { [16208] = { "20:567539407:1647338296", "เมล็ด Gaea ลงมนตร์" } },
        steps = { { "17:2024503591:1645826446", "ปลูกเมล็ด Gaea" } },
        objectiveLabels = {
            item = { ["Enchanted Gaea Seeds"] = "เมล็ด Gaea ลงมนตร์" },
        },
    },
    [6383] = { -- The Ashenvale Hunt
        title = { "18:470123318:630157178", "การล่าแห่ง Ashenvale" },
        completion = { "469:446328154:686207802", "การล่าแห่ง Ashenvale มีเป้าหมายเป็นสัตว์ในตำนานสามตัว เจ้าสามารถตามหาและทดสอบตนกับไหวพริบและพละกำลังของมัน ระหว่างนั้นหวังว่าเจ้าจะได้เรียนรู้เกี่ยวกับตนเองด้วย พวกมันคือหมี Ursangous, ไนต์เซเบอร์ Shadumbra และฮิปโปกริฟ Sharptalon\n\nสัตว์เหล่านี้ทรงพลัง เจ้าอาจต้องการผู้ช่วยโค่นมัน หากเอาชนะได้ จงนำหลักฐานมาให้ข้า" },
    },
    [6393] = { -- Elemental War
        title = { "13:597002404:218793310", "สงครามแห่งธาตุ" },
        objective = { "53:2115952144:12883596", "นำ Incendrites 10 ชิ้น ไปให้ Tsunaman ที่ Sun Rock Retreat" },
        description = { "229:1985702542:1929638653 N 188:1187302973:853119455", "Tribunal of the Tides ส่งข้ามาทำสงครามกับธาตุไฟที่ Stonetalon Mountains Neptulon the Tidehunter ผู้เป็นนายแห่งธาตุน้ำทั้งหมด ทรงสนพระทัยเป็นพิเศษที่จะเห็นญาติผู้ร้อนแรงของเราดับสูญ\n\n{name} เจ้าช่วยให้ข้าได้รับความโปรดปรานจาก Tribunal ได้ด้วยการทำลายธาตุไฟใน Charred Vale เมื่อถูกทำลาย พวกมันจะทิ้ง Incendrites นำมาให้ข้าแล้วรับรางวัล" },
        progress = { "249:1353730061:1750276463", "Tribunal of the Tides เริ่มหมดความอดทน พวกเขาต้องการจบสงครามที่โหมข้ามทุกมิติมานับยุค พี่น้องข้ารอฟังข่าวชัยชนะเหนือธาตุไฟที่เกลียดชัง เจ้าหา Incendrites ที่ข้าต้องการมาหรือยัง?" },
        completion = { "56:649786936:614284814 N 78:1432313280:2045067887", "วิญญาณน้ำในตัวข้าพลุ่งพล่านด้วยความตื่นเต้น {name} เจ้าทำให้ข้ามีชัยชนะอันรุ่งโรจน์ไปรายงาน Tribunal of the Tides" },
        required = { [16312] = { "11:1856171797:789116423", "ผลึก Incendrite" } },
        steps = { { "11:1856171797:789116423", "ผลึก Incendrite" } },
    },
    [6401] = { -- Kaya's Alive
        title = { "12:201017279:1684288652", "Kaya ยังมีชีวิต" },
        objective = { "56:2006898963:758858684", "บอกข่าวดีแก่ Tammra Windfield ที่ Sun Rock Retreat" },
        description = { "221:749998986:1215499741", "ไปบอกข่าวดีแก่ Tammra Windfield ญาติผู้ใหญ่ของ Kaya ที่ Sun Rock Retreat! Kaya ยังมีชีวิต! เราคิดว่านางหายไปแล้วหลังการโจมตีหมู่บ้านอย่างโหดร้าย เดินตามเส้นทางไปทางตะวันตกเพื่อถึง Sun Rock Retreat" },
        completion = { "74:1294429895:2049706580 N 1:46:46", "โอ้ หลานสาว Kaya ยังมีชีวิต! เป็นข่าวดีจริง ๆ ขอบใจ {name}" },
    },
    [6421] = { -- Boulderslide Ravine
        title = { "19:1997016256:103020193", "Boulderslide Ravine" },
        objective = { "135:594040325:436234396", "สำรวจลึกเข้าไปในถ้ำที่ Boulderslide Ravine แล้วนำ Resonite Crystals 10 ชิ้น กลับไปให้ Mor'rogal ที่ Sun Rock Retreat ตรวจสอบ" },
        description = { "76:851370549:1556354095 N 296:58331258:1721614226 C 63:305616422:1666128216", "มีบางอย่างผิดปกติใน Stonetalon เจ้าสัมผัสถึงความตึงเครียดในอากาศไหม {name}?\n\nทางตะวันออกเฉียงใต้มีถ้ำลึกใน Boulderslide Ravine โคโบลด์ที่นั่นเร่งขุดผลึกหายากชื่อ Resonite อย่างบ้าคลั่ง ข้าต้องการตัวอย่างแร่มาศึกษาว่าเกิดอะไรขึ้น และอยากให้เจ้าสำรวจส่วนลึกของถ้ำด้วย\n\nไปเถอะ {class} หนุ่มสาว ข้าจำเป็นต้องรู้ว่าความชั่วใดซ่อนใต้เทือกเขานี้" },
        progress = { "233:1185304217:2059714247", "เจ้าพบข่าวอะไรจาก Boulderslide Ravine? ข้าจำได้ว่ามีตำนานเกี่ยวกับ Resonite... แต่นึกไม่ออก บางทีหากรู้ว่ามีอะไรอยู่ก้นถ้ำ ก็อาจเข้าใจแผนร้ายของพวกมัน" },
        completion = { "407:798288858:389448629", "อา... ใช่แล้ว! ผลึก Resonite มีร่องรอยเวทของเอิร์ธเธน โคโบลด์คงขุดลึกจนพบเอิร์ธเธนเข้า\n\nตำนานกล่าวว่าเอิร์ธเธนเป็นสิ่งมีชีวิตที่ไททันสร้างขึ้น เพื่อสร้างผืนดินที่เราเดินอยู่ นี่เป็นภัยที่มองข้ามไม่ได้อย่างแน่นอน\n\n<Mor'rogal ส่ายหน้า>\n\nบางทีข้าอาจเสกตัวอย่างแร่เหล่านี้ให้ใช้ต่อต้านแผนของโคโบลด์ได้" },
        required = { [16581] = { "16:1270919611:1699793647", "ผลึก Resonite" } },
        steps = { { "16:1270919611:1699793647", "ผลึก Resonite" } },
        objectiveLabels = {
            event = { ["Investigate Cave in Boulderslide Ravine"] = "สำรวจถ้ำใน Boulderslide Ravine" },
        },
    },
    [6441] = { -- Satyr Horns
        title = { "11:1370151492:883192787", "เขาซาเทอร์" },
        objective = { "54:1228207648:893274593", "เก็บ Satyr Horns 16 ชิ้น ให้ Pixel ที่ Splintertree Post" },
        description = { "504:1260050459:1670004483", "ว่าไง! ข้าเดินทางผ่าน Ashenvale จะไป Ratchet แล้วตัดสินใจหยุดที่ Splintertree ข้ามองหาโอกาสอยู่เสมอ ช่วงนี้ดูเหมือนเขาซาเทอร์เป็นที่ต้องการมากใน Ratchet\n\nถามคนแถวนี้แล้ว ซาเทอร์ใน Night Run, Satyrnaar และ Xavian มีเขาแบบที่ข้าต้องการ ข้าสู้มันไม่ไหว... แต่เจ้าดูเหมือนจะไหว!\n\nเอาอย่างนี้ เจ้าช่วยเก็บเขาให้ แล้วข้าจะตอบแทนให้คุ้มเวลา" },
        progress = { "51:1013226638:145251698 N 35:1673290363:1448878109", "หวังว่าเจ้าจะหาเขาพวกนั้นได้เร็ว ๆ {name} ข้าจะกลับ Ratchet ในไม่ช้าแล้ว!" },
        completion = { "19:554587191:437047549 N 61:359332937:720520298", "สมบูรณ์แบบ {name}! ขอบใจที่ช่วย!\n\nอ้อ นี่สำหรับเวลาที่เสียไป..." },
        required = { [5481] = { "11:1370151492:883192787", "เขาเซเทอร์" } },
        steps = { { "11:1370151492:883192787", "เขาเซเทอร์" } },
    },
    [6442] = { -- Naga at the Zoram Strand
        title = { "24:346743064:1708762053", "นากาที่ Zoram Strand" },
        objective = { "59:508668337:882964797", "นำ Wrathtail Heads 20 ชิ้น ไปให้ Marukai ที่ Zoram Strand" },
        description = { "44:1444383529:811464464 R 361:905739284:60807775", "มีความชั่วร้ายซ่อนอยู่ตามชายฝั่งนี้ {race}\n\nที่นี่คือสุสานของนคร Zoram ผู้ประสบชะตากรรมอันเลวร้าย ถูกทำลายและจมใต้ทะเลมานาน สูญหายและแทบถูกลืม\n\nตอนนี้นากากลับมาแล้ว เราไม่รู้เหตุผล แต่เหตุผลไม่สำคัญนัก เราต้องปกป้องผืนดินที่ทุ่มเทยึดครองมาเป็นของตน\n\nนำหัวพวกมันกลับมา 20 หัว! ผลักนากากลับสู่ก้นทะเล!", variants = { { "413:1810267929:1560189094", "มีความชั่วร้ายซ่อนอยู่ตามชายฝั่งนี้ สกายบอร์น\n\nที่นี่คือสุสานของนคร Zoram ผู้ประสบชะตากรรมอันเลวร้าย ถูกทำลายและจมใต้ทะเลมานาน สูญหายและแทบถูกลืม\n\nตอนนี้นากากลับมาแล้ว เราไม่รู้เหตุผล แต่เหตุผลไม่สำคัญนัก เราต้องปกป้องผืนดินที่ทุ่มเทยึดครองมาเป็นของตน\n\nนำหัวพวกมันกลับมา 20 หัว! ผลักนากากลับสู่ก้นทะเล!" } } },
        progress = { "30:1614396604:410436984 N 35:697249095:239870900", "นากากำลังเพิ่มจำนวน {name} โปรดทำภารกิจนี้ให้ข้าสำเร็จ" },
        completion = { "44:731533219:1024991038 N 26:519545202:504028735", "แถวนี้น่าจะมีคนแบบเจ้ามากกว่านี้ {name} ขอบใจที่ช่วย" },
        required = { [5490] = { "14:840604607:1973963518", "หัวของ Wrathtail" } },
        steps = { { "14:840604607:1973963518", "หัวของ Wrathtail" } },
    },
    [6461] = { -- Blood Feeders
        title = { "13:1320054018:1811938620", "พวกดูดเลือด" },
        objective = { "92:211139605:1553148823", "Xen'zilla ที่ Malaka'Jin ต้องการให้เจ้าฆ่า Deepmoss Creepers 10 ตัว และ Deepmoss Venomspitters 7 ตัว" },
        description = { "466:1241268642:150723536", "โทรลล์ที่ Malaka'Jin อย่างเราอยู่ดีกินดีด้วยผืนดิน Stonetalon Mountains มีสัตว์ให้ล่าพอเลี้ยงชีพ\n\nแต่พักนี้เราได้แขกกินมื้อค่ำผิดพวก... แมงมุมบนเขาบุกค่ายตอนกลางคืนเพื่อขโมยเหยื่อที่เราล่ามา\n\nหากเจ้าช่วยฆ่าสัตว์น่าขนลุกเหล่านี้ Malaka'Jin จะติดหนี้บุญคุณเจ้า แมงมุมอยู่ทั่ว Stonetalon แค่มุ่งเหนือจากที่นี่ก็จะเข้าใจสิ่งที่ข้าพูด" },
        progress = { "233:499609844:1323264079 C 1:33:33", "ว่าไงเพื่อน ฆ่าพวกดูดเลือดขนดกแล้วหรือยัง? ข้าไม่กลัวอะไรใน Stonetalon หรอก แต่ไม่เดินแถวนี้ตอนกลางคืน... เข้าใจใช่ไหมเพื่อน!\n\nตราบใดที่ข้าไม่อยู่บนจานอาหารของมันก็ไม่มีปัญหา\n\nขอให้โชคดี {class}!" },
        completion = { "95:884203210:1360113561 N 30:408846427:825197431", "เยี่ยมเลยเพื่อน! ข่าวดี คืนนี้แขกที่เราไม่ได้เชิญอาจน้อยลง\n\nขอบใจมาก {name} เราจะเป็นหนี้บุญคุณเจ้าตลอดไป" },
        objectiveLabels = {
            monster = { ["Deepmoss Venomspitter slain"] = "ปราบ ตัวพ่นพิษ Deepmoss", ["Deepmoss Creeper slain"] = "ปราบ แมงมุมไต่คลาน Deepmoss" },
        },
    },
    [6462] = { -- Troll Charm
        title = { "11:1157964683:190680825", "เครื่องรางโทรลล์" },
        objective = { "57:2097025030:1276793856", "นำ Troll Charms 8 ชิ้น ไปให้ Mitsuwa ที่ Zoram'gar Outpost" },
        description = { "362:1975176509:1016725859 N 131:1468495666:2058915064", "ญาติของข้าเดินทางมาพร้อมเครื่องรางศักดิ์สิทธิ์ของโทรลล์มากมาย แต่เฟอร์โบลก์ Thistlefur โจมตีและฆ่าพวกเขาก่อนถึง Zoram'gar! เฟอร์โบลก์ชั่ว!\n\nข้าคิดถึงพี่น้องที่ตาย แต่เราจะได้พบกันในโลกหน้า ส่วนเครื่องรางของพวกเขายังมีค่ามากในโลกนี้ ช่างน่าแค้นที่อยู่ในมือเฟอร์โบลก์!\n\n{name} เจ้าต้องนำเครื่องรางคืน! มันอยู่ในหีบใน Thistlefur Hold ถ้ำสุด Thistlefur Village ทางเหนือของ Astranaar" },
        progress = { "25:1818932496:469330673 N 81:144415667:641640907", "พบเครื่องรางหรือยัง {name}? ทุกขณะที่เฟอร์โบลก์ครอบครองสิ่งศักดิ์สิทธิ์เหล่านี้ เลือดข้าเดือดด้วยความโกรธ!" },
        completion = { { "38:108132644:83429435 N 137:268185103:401300833", "38:108132644:83429435 N 137:2085084448:1811378393", "38:108132644:83429435 N 137:463788064:329929333", "38:108132644:83429435 N 137:133203762:1740006893" }, "เจ้าพบแล้ว! ขอบใจ! ขอบใจ {name}! เจ้าไม่รู้หรอกว่าสิ่งที่ทำมีความหมายต่อข้ามากเพียงใด\n\nโทรลล์ที่ไร้เครื่องรางประจำตัว ก็เหมือนออร์คที่ไร้แผลเป็นจากการต่อสู้...\n\nไร้ค่า", variants = { { "38:108132644:83429435 N 60:1194359544:790162259 R 72:1160602696:667434435", "เจ้าพบแล้ว! ขอบใจ! ขอบใจ {name}! เจ้าไม่รู้หรอกว่าสิ่งที่ทำมีความหมายต่อข้ามากเพียงใด\n\n{race}ที่ไร้เครื่องรางประจำตัว ก็เหมือนออร์คที่ไร้แผลเป็นจากการต่อสู้...\n\nไร้ค่า" } } },
        required = { [16602] = { "11:1157964683:190680825", "เครื่องรางโทรลล์" } },
        steps = { { "11:1157964683:190680825", "เครื่องรางโทรลล์" } },
    },
    [6481] = { -- Earthen Arise
        title = { "13:768355778:2031103504", "เอิร์ธเธนตื่นขึ้น" },
        objective = { "149:1022498140:1314073741", "ใช้ Enchanted Resonite Crystal เปิด Resonite Cask แล้วฆ่า Goggeroc จากนั้นกลับไปแจ้งข่าว Mor'rogal พร้อมคืน Enchanted Resonite Crystal" },
        description = { "46:733171655:706985344 C 349:1496926868:1916054429 N 1:33:33", "เจ้าพบภัยมืดที่คุกคามผืนดินแล้ว {class} Resonite Cask ในถ้ำนั้นบรรจุเอิร์ธเธนชื่อ Goggeroc ที่กำลังหลับใหล\n\nข้าใช้พลังชามานปรับส่วนผสมของผลึก Resonite ที่เจ้าเก็บมา นำผลึกที่เสกแล้วไปทุบเปิด Resonite Cask ซึ่งบรรจุเอิร์ธเธนไว้\n\nเมื่อตื่น Goggeroc จะอ่อนแอ... ฆ่าเขาเสีย {name}!" },
        progress = { "276:1648208444:1908006304 N 1:33:33", "ข้าเกรงว่าหากไม่กำจัดภัยนี้ทันที Stonetalon ทั้งหมดจะสูญสิ้น ไม่มีสิ่งใดทัดเทียมพลังของเอิร์ธเธน เมื่อ Goggeroc ตื่น เขาจะยังอ่อนแรงจากการหลับยาว เจ้าต้องฉวยโอกาสนั้น... ไปเดี๋ยวนี้ {name}!" },
        completion = { "20:913176997:1857414553 C 205:1153066694:298626492 C 46:2055322407:1398987504", "เจ้านำข่าวดีมา {class}! ข้ากลัวว่าเอิร์ธเธนอาจก่ออะไรต่อ Kalimdor ได้บ้าง\n\nการฆ่า Goggeroc เป็นงานของวีรบุรุษเท่านั้น เจ้าทำได้ดี Stonetalon และ Kalimdor ทั้งหมดติดหนี้เจ้า {class} ผู้สูงส่ง\n\nผู้ทรงเกียรติ โปรดรับสิ่งนี้เป็นรางวัล", variants = { { "20:913176997:1857414553 C 205:329486962:502192098 C 46:2055322407:1398987504", "เจ้านำข่าวดีมา {class}! ข้ากลัวว่าเอิร์ธเธนอาจก่ออะไรต่อ Kalimdor ได้บ้าง\n\nการฆ่า Goggeroc เป็นงานของวีรบุรุษเท่านั้น เจ้าทำได้ดี Stonetalon และ Kalimdor ทั้งหมดติดหนี้เจ้า {class} ผู้สูงส่ง\n\nผู้ทรงเกียรติ โปรดรับสิ่งนี้เป็นรางวัล" } } },
        required = { [16603] = { "26:364181935:1051289582", "ผลึก Resonite ลงมนตร์" } },
        steps = { { "26:364181935:1051289582", "ผลึก Resonite ลงมนตร์" } },
        objectiveLabels = {
            monster = { ["Goggeroc slain"] = "ปราบ Goggeroc" },
        },
    },
    [6482] = { -- Freedom to Ruul
        title = { "15:1548955744:1761562003", "อิสรภาพของ Ruul" },
        objective = { "64:1357873425:2125663531", "คุ้มกัน Ruul แล้วคุยกับ Yama Snowhoof ที่ Splintertree Post", variants = { { "63:1972320628:1372716925", "คุ้มกัน Ruul แล้วคุยกับ Yama Snowhoof ที่ Spintertree Post" } } },
        description = { "17:816464288:1866851044 N 216:1783769237:721766986 N 16:2070655961:731203771", "เอ๊ะ? เจ้าเป็นใคร?\n\n{name} หรือ? เจ้าไม่ใช่เฟอร์โบลก์ พวกมันต้องคำสาป! คิดว่าข้าเป็นหมีแล้วจับมา ตอนนี้ก็ปล่อยให้ข้าอดอยาก! กำลังข้าร่อยหรอ...\n\nช่วยข้าหนี แล้วไปคุยกับ Yama พี่น้องหญิงของข้าที่ Splintertree Post ทางตะวันออก\n\n{name}! ข้าต้องหนีออกไป!" },
        progress = { "89:1861843962:947979158", "เห็น Ruul พี่น้องชายของข้าบ้างไหม? เขาเดินเข้าป่าไปหลายวันแล้วยังไม่กลับ..." },
        completion = { "201:77373562:1215372379 N 102:1511740657:1576871052", "เจ้าพบพี่น้องชายของข้าแล้ว! เขาถูก Thistlefur จับไปหรือ? ข่าวร้ายจริง ๆ แม้เฟอร์โบลก์จำนวนมากจะมีจิตใจสูงส่ง แต่ Thistlefur เสื่อมทรามแล้ว\n\nขอบใจที่ช่วยเขา {name} ข้าไม่อยากคิดเลยว่าพวกมันทำอะไรกับ Ruul ผู้น่าสงสารบ้าง เขาคงต้องหลับพักอีกนานหลังเรื่องเลวร้ายนี้..." },
        objectiveLabels = {
            event = { ["Escort Ruul from the Thistlefurs."] = "คุ้มกัน Ruul ให้พ้นจากพวก Thistlefur" },
        },
    },
    [6503] = { -- Ashenvale Outrunners
        title = { "20:323005897:1810860785", "หน่วยสอดแนม Ashenvale" },
        objective = { "78:1350687727:423284677", "ฆ่า Ashenvale Outrunners 9 ตัว แล้วกลับไปหา Kuray'bin ที่ Splintertree Outpost" },
        description = { "338:1897892960:1743482000", "เราได้รายงานว่าหน่วยสอดแนม Ashenvale ออกจาก Silverwing Outpost ไม่นานมานี้ และกำลังลอบเข้ามาใกล้อาณาเขตเราในป่า เราไม่ต้องการให้พวกมันสืบข้อมูลแนวป้องกัน!\n\nลอบผ่านป่าทางใต้ของฐานเราและทางตะวันออกของ Silverwing ฐาน Alliance หาและฆ่าหน่วยสอดแนม แล้วกลับมาหาข้า" },
        progress = { "41:1847575290:722393872 N 1:46:46", "ข้ารอฟังรายงานการฆ่าหน่วยสอดแนมของเจ้า {name}" },
        completion = { "11:1776810664:1873330125 N 166:1250843454:2034045958", "ดีมาก {name} ฝีมือการล่าของเจ้าน่าประทับใจ...\n\nการสูญเสียหน่วยสอดแนมช่วยปิดหูปิดตา Alliance และเมื่อขาดข้อมูล พวกมันก็มีแนวโน้มโจมตีน้อยลง" },
        objectiveLabels = {
            monster = { ["Ashenvale Outrunner slain"] = "ปราบ หน่วยลาดตระเวน Ashenvale" },
        },
    },
    [6504] = { -- The Lost Pages
        title = { "14:635734518:1162687620", "หน้ากระดาษที่หายไป" },
        objective = { "170:675004656:1927182764", "หาหน้ากระดาษ Shredder Operating Manual ที่หายไป 12 หน้า ประกอบเป็น Chapters 1, 2 และ 3 แล้วนำกลับไปให้ Gurda Ragescar ใกล้ Splintertree Post" },
        description = { "457:2138896828:771511311", "ข้าเพิ่งไปรับเครื่องตัดไม้จาก Ratchet กำลังกลับ Warsong Lumber Camp เพื่อเข้าประจำหน้าที่ ได้คู่มือใช้งานมาด้วย แต่ระหว่างทางลมแรงพัดมันหลุดมือ หน้ากระดาษปลิวไปทั่ว เหลือแค่ปก\n\nตอนนี้มันอาจอยู่ที่ไหนก็ได้... แต่ถ้าไม่มีคู่มือ ข้าใช้เครื่องไม่เป็น! เจ้าช่วยหาให้ได้ไหม?" },
        progress = { "32:517141412:1971579726 N 36:195658377:291991533", "หวังว่าเจ้าจะพบหน้ากระดาษเร็ว ๆ {name}! ข้าต้องรีบกลับไปทำงาน!" },
        completion = { "83:508264439:2118322895 N 1:33:33", "ข้าอ่านหนังสือไม่เก่ง... แต่ตอนนี้กลับไปทำงานได้แล้ว! ขอบใจ {name}!" },
        required = { [16642] = { "37:1009160343:1123911682", "คู่มือควบคุม Shredder บทที่ 1" }, [16643] = { "37:1009160344:1123911683", "คู่มือควบคุม Shredder บทที่ 2" }, [16644] = { "37:1009160345:1123911684", "คู่มือควบคุม Shredder บทที่ 3" } },
        steps = { { "37:1009160343:1123911682", "คู่มือควบคุม Shredder บทที่ 1" }, { "37:1009160344:1123911683", "คู่มือควบคุม Shredder บทที่ 2" }, { "37:1009160345:1123911684", "คู่มือควบคุม Shredder บทที่ 3" } },
    },
    [6523] = { -- Protect Kaya
        title = { "12:2032572578:1854102060", "ปกป้อง Kaya" },
        objective = { "114:755695502:1617439051", "คุ้มกัน Kaya Flathoof ไป Camp Aparaje แล้วกลับไปหา Makaba Flathoof ใกล้ชายขอบตะวันออกเฉียงใต้ของ Stonetalon" },
        description = { "216:735253208:1337318060", "ขอบใจที่ช่วยข้า! เราต้องรีบไปก่อนพวกมันรู้ว่าข้าเป็นอิสระ โปรดคุ้มกันไป Camp Aparaje จากนั้นข้ารู้ทางเอง\n\nMakaba Flathoof พ่อของข้าคงร้อนใจอยากรู้ว่าข้าปลอดภัย" },
        completion = { "15:1472863484:1568040647 N 39:633319691:1817943339", "Kaya ยังมีชีวิต! {name} ข้าต้องขอบใจเจ้าที่ช่วยนางไว้" },
        objectiveLabels = {
            event = { ["Kaya Escorted to Camp Aparaje"] = "คุ้มกัน Kaya ถึง Camp Aparaje แล้ว" },
        },
    },
    [6542] = { -- Report to Kadrak
        title = { "16:1966035642:1310894047", "รายงานต่อ Kadrak" },
        objective = { "56:2113603299:1793595057", "รายงานตัวกับ Kadrak ที่หอสังเกตการณ์ทางเหนือของ Barrens" },
        description = { "345:1495443436:1017259450", "เคยไป Ashenvale ทางเหนือไหม? Horde เพิ่งตั้งฐานที่ Zoram Strand ที่นั่น เราต้องการกำลังใหม่ช่วยป้องกันแนวรบใหม่อยู่เสมอ\n\nหากคิดว่าไหว ไปพบ Kadrak ที่หอสังเกตการณ์ทางเหนือของ Barrens เขานำการรบใน Ashenvale และจะให้คำสั่งต่อไปได้" },
        completion = { "184:1812949208:541110060", "Ashenvale เป็นดินแดนที่แตกแยก แต่ความพยายามล่าสุดของเราประสบผลดีมาก เราไม่ได้มีแค่ฐานที่ Zoram Strand แต่ยังมีอีกแห่งทางเหนือจากที่นี่ชื่อ Splintertree" },
    },
    [6544] = { -- Torek's Assault
        title = { "15:2099666941:396740685", "การบุกของ Torek" },
        objective = { "126:589153309:119998641", "คุ้มกัน Torek ระหว่างบุกโจมตี Silverwing Outpost และ Duriel Moonfire แล้วรายงานต่อ Ertog Ragetusk ที่ Splintertree Post" },
        description = { "5:140207098:2105779678 C 268:945074414:1553213333 N 149:2042229046:1997168111", "เฮ้! {class}! มานี่!\n\nข้ากับกองจู่โจมกำลังจะบุก Silverwing Outpost ทางตะวันตก เป้าหมายคือผู้นำ Duriel Moonfire หน่วยสอดแนมรายงานว่ามีเซนทิเนลกับนักรบป้องกันแน่นหนา ศึกนี้จะรุ่งโรจน์!\n\nเจ้าอยากร่วมเกียรติยศและช่วยเราไหม {name}? ถ้าร่วม เมื่อจบแล้วเจ้าจะรายงานความสำเร็จต่อผู้บังคับบัญชาของข้า Ertog Ragetusk ที่ Splintertree ได้\n\nว่าอย่างไร จะไปกับเราไหม?" },
        progress = { "82:126969036:992894877", "Torek ถูกส่งไปโจมตี Silverwing Outpost การบุกสำเร็จหรือไม่?" },
        completion = { "45:2087145935:264986712 N 151:748344092:275786359", "งั้น Torek บุกสำเร็จแล้ว! ทำได้ดี {name} ไนต์เอลฟ์เป็นคู่ต่อสู้ที่ใช้ได้ ผอมไปหน่อย แต่แข็งแกร่งดุดัน! ศึกคงน่าชม...\n\nหวังว่าเจ้าจะได้แผลเป็นมาสักรอยสองรอย!" },
        objectiveLabels = {
            event = { ["Take Silverwing Outpost."] = "ยึดด่าน Silverwing" },
        },
    },
    [6545] = { -- Warsong Runner Update
        title = { "21:1776988819:44957051", "รายงานจาก Warsong Runner" },
        progress = { "191:577030152:45385331 N 204:1630312560:1558742766", "เจ้ามาพร้อมคำสั่งให้ข้าหรือ? ดีเสมอที่ได้เห็นทหารใหม่กระตือรือร้นและใจแข็งแกร่ง\n\nหากอยากตามให้ทันที่นี่ เจ้าต้องเรียนรู้ให้ไว ภัยนากาเพิ่มขึ้น {name} ตั้งแต่มาถึง ข้าเฝ้าดูและตั้งรับการโจมตีฐานนี้หลายครั้งแล้ว\n\nหากอยากช่วยเรื่องนั้น ไปคุยกับคนอื่นในฐานได้" },
        completion = { "103:1721142405:443615457", "รายงานของข้าจะอธิบายทุกอย่างแก่ Kadrak เจ้าต้องนำกลับไปให้เขาโดยเร็วที่สุด" },
        description = { "191:577030152:45385331 N 204:1630312560:1558742766", "เจ้ามาส่งคำสั่งให้ข้ารึ? ดีเสมอที่ได้เห็นทหารใหม่กระตือรือร้นและใจสู้\n\nถ้าอยากตามคนที่นี่ให้ทัน เจ้าต้องเรียนรู้ให้เร็ว ภัยจากนากากำลังหนักขึ้น {name} ตั้งแต่ข้ามาถึง ข้าเห็นพวกมันโจมตีด่านนี้หลายครั้งและช่วยตั้งรับมาแล้ว\n\nถ้าเจ้าอยากช่วยป้องกันด่าน ก็ไปคุยกับคนอื่น ๆ ที่นี่สักคน" },
        required = { [16746] = { "14:48935701:962484795", "รายงาน Warsong" } },
        objectiveLabels = {
            item = { ["Warsong Report"] = "รายงาน Warsong" },
        },
    },
    [6546] = { -- Warsong Outrider Update
        title = { "23:1850986197:904367435", "รายงานจาก Warsong Outrider" },
        progress = { "34:735192644:1383390795 N 396:1538145330:356500146 N 1:46:46", "เส้นทางนี้มีภัยมากมาย {name} เจ้าควรจำไว้เวลาเดินทางในดินแดนนี้ ภัยจาก Alliance อยู่ใกล้มาก\n\nเรามีศัตรูทุกด้าน ซาเทอร์ใน Ashenvale ตะวันออกมีกำลังน่ากลัวและกระจายอยู่ทั่วไป ข้ายังพบว่านากายึดพื้นที่กว้างใหญ่ใน Azshara แล้ว\n\nดีที่เรายังเสริมกำลัง เตรียมพร้อมรับสิ่งที่อยู่ข้างหน้า {name}" },
        completion = { "35:512878431:1490445919 N 1:46:46", "นำรายงานข้าไปให้ Kadrak โดยเร็ว {name}" },
        description = { "34:735192644:1383390795 N 396:1538145330:356500146 N 1:46:46", "เส้นทางนี้มีอันตรายมาก {name} จำไว้ให้ดีเมื่อเดินทางแถบนี้ พวกอะไลแอนส์อยู่ใกล้กว่าที่คิด\n\nเรามีศัตรูทุกด้าน พวกซาเทอร์ใน Ashenvale ตะวันออกทั้งแข็งแกร่งและมีอยู่ทั่ว ข้ายังพบว่านากายึดพื้นที่ส่วนใหญ่แถบหนึ่งของ Azshara ไปแล้ว\n\nดีที่เรายังเสริมกำลังกันอยู่ เตรียมตัวให้พร้อมสำหรับสิ่งที่รออยู่ข้างหน้า {name}" },
        required = { [16746] = { "14:48935701:962484795", "รายงาน Warsong" } },
        objectiveLabels = {
            item = { ["Warsong Report"] = "รายงาน Warsong" },
        },
    },
    [6547] = { -- Warsong Scout Update
        title = { "20:412229072:1231784767", "รายงานจาก Warsong Scout" },
        progress = { "17:1836037573:651791587 R 224:2053222939:1673803258", "คอยระวังไว้ {race} เอลฟ์มักซ่อนในเงามืด...\n\nเราต้องเฝ้าดูเสมอ เราทุ่มเทอย่างมากเพื่อยึดผืนดินนี้ และเอลฟ์กำลังหาโอกาสชิงคืน\n\nข้าคิดว่าเจ้ามีคำสั่งถัดไปจาก Kadrak มาให้ใช่ไหม?", variants = { { "249:268455099:904406394", "คอยระวังไว้ สกายบอร์น เอลฟ์มักซ่อนในเงามืด...\n\nเราต้องเฝ้าดูเสมอ เราทุ่มเทอย่างมากเพื่อยึดผืนดินนี้ และเอลฟ์กำลังหาโอกาสชิงคืน\n\nข้าคิดว่าเจ้ามีคำสั่งถัดไปจาก Kadrak มาให้ใช่ไหม?" } } },
        completion = { "102:1403171214:1609446868", "แจ้ง Kadrak ว่าเราต้านไนต์เอลฟ์ที่นี่ได้สำเร็จ แผนกำลังดำเนินไปด้วยดี" },
        description = { "17:1836037573:651791587 R 224:2053222939:1673803258", "คอยระวังไว้ {race} พวกเอลฟ์มักซ่อนอยู่ในเงามืด...\n\nเราต้องเฝ้าดูตลอดเวลา เราลงแรงไปมากกว่าจะยึดดินแดนนี้มาได้ และพวกเอลฟ์ก็กำลังหาโอกาสชิงคืน\n\nเจ้าคงเอาคำสั่งต่อไปจาก Kadrak มาให้ข้าใช่ไหม?" },
        required = { [16746] = { "14:48935701:962484795", "รายงาน Warsong" } },
        objectiveLabels = {
            item = { ["Warsong Report"] = "รายงาน Warsong" },
        },
    },
    [6548] = { -- Avenge My Village
        title = { "17:426296487:887493211", "ล้างแค้นให้หมู่บ้านข้า" },
        objective = { "131:745648060:1547848696", "ฆ่า Grimtotem Ruffians 8 ตัว และ Grimtotem Mercenaries 6 ตัว แล้วกลับไปหา Makaba Flathoof ใกล้ชายขอบตะวันออกเฉียงใต้ของ Stonetalon" },
        description = { "118:1637209896:1776066008 N 92:1439095324:1628846626", "เผ่า Grimtotem บุกหมู่บ้านข้า ฆ่าแทบทุกคน ข้าฆ่าพวกมันได้เท่าที่ทำได้ แต่แทบเอาชีวิตไม่รอด\n\n{name} ตอนนี้ข้าต้องการเพียงให้พวกมันตายมากขึ้น หาได้ทางตะวันตกจากที่นี่ไม่ไกล" },
        progress = { "25:911266445:716354855", "ฆ่าพวกมันแล้วหรือยัง?" },
        completion = { "N 84:1916794679:211706332", "{name} ขอบใจ... แต่ข้าจะไม่มีวันลืมสิ่งที่ Grimtotem ทำกับหมู่บ้านข้า" },
        objectiveLabels = {
            monster = { ["Grimtotem Ruffian slain"] = "ปราบ นักเลง Grimtotem", ["Grimtotem Mercenary slain"] = "ปราบ ทหารรับจ้าง Grimtotem" },
        },
    },
    [6568] = { -- The Testament of Rexxar
        title = { "23:1726474795:953795755", "สารของ Rexxar" },
        objective = { "70:1066042315:1479987431", "ส่ง Rexxar's Letter ให้ Myranda the Hag ใน Western Plaguelands" },
        description = { "31:625994349:291394951 N 417:1743156825:1290906418", "เจ้ารู้อะไรเกี่ยวกับภาพลวงตาบ้าง {name}? เจ้าต้องสร้างภาพลวงตาเพื่อลอดแนวป้องกันของฝูงมังกรดำ\n\nข้ารู้จักผู้หนึ่งที่อาจช่วยแผนลวงของเจ้าได้ นางเคยช่วยพวกเราเมื่อเห็นว่าเหตุผลคู่ควร\n\nใน Western Plaguelands เจ้าจะพบ Myranda the Hag จ้าวแห่งภาพลวงตา ผู้ถูกเนรเทศจาก Alliance แห่ง Lordaeron ไปที่นั่นพร้อมสารฉบับนี้" },
        progress = { "105:1456664204:1806023281", "ไม่บ่อยที่ข้าเห็นคนของ Horde ในแถบนี้ของ Lordaeron เจ้ามีอะไรมาให้ Myranda?" },
        completion = { "393:630956134:1792563288 R 54:48279767:23167777", "<Myranda ถือจดหมาย นิ่งไปครู่หนึ่ง แล้วยิ้ม>\n\nเขาเป็นอย่างไรบ้าง? ข้าหมายถึง Rexxar โธ่ อย่าทำหน้างงเช่นนั้น จดหมายตั้งใจเว้นว่างไว้ มันบรรทุกเจตนาและความคิดของผู้เขียน ดูจากเนื้อหาแล้วไม่แปลกที่ Rexxar เลือกทำแบบนี้ ลองคิดสิหากเจ้าถูกจับหรือฆ่า แล้วข้อมูลถูกค้นพบ!\n\nช่างเถอะ! Myranda จะช่วยเจ้า {race} ข้าติดค้าง Warchief อยู่สักเรื่องสองเรื่อง\n\n<Myranda ยิ้ม>" },
    },
    [6571] = { -- Warsong Supplies
        title = { "16:1870886905:161601805", "เสบียง Warsong" },
        objective = { "143:1746855304:1835535055", "รวบรวมเสบียง Warsong ได้แก่ Warsong Saw Blades, Logging Rope, Warsong Oil และ Warsong Axe Shipment ให้ Locke Okarr ที่ Splintertree Post" },
        description = { "473:1169423672:1386286710", "ค่ายตัดไม้ Warsong ขาดของอยู่หลายอย่าง!\n\nPixel ที่ Splintertree Post มีใบเลื่อยที่ส่งมา ส่วนลังขวานต้องไปเอาจาก Wharfmaster Lozgil ที่ Booty Bay\n\nน้ำมันกับเชือกยากกว่า เชือกถูกเฟอร์โบลก์ Thistlefur และ Foulweald ขโมย ส่วนซาเทอร์สกัดการส่งน้ำมันและนำไปใช้ในพิธีน่ารังเกียจที่ Night Run, Satyrnaar และ Xavian!\n\nเจ้าช่วยข้าได้ไหม?" },
        progress = { "95:974767608:898021801", "หวังว่าเจ้าจะหาเสบียงมาได้! ถ้าไม่ส่งเร็ว ๆ ข้าเดือดร้อนหนักแน่!" },
        completion = { "11:1614239848:1406166483 N 71:2060907337:1425389184", "เยี่ยมมาก {name} เจ้าช่วยข้าประหยัดแรงไปมาก!\n\nแต่อย่าคิดว่าข้าไม่ซาบซึ้งนะ!" },
        required = { [16742] = { "18:1757851282:1761557611", "ใบเลื่อย Warsong" }, [16745] = { "20:1041639644:2084735458", "ขวานที่ส่งมาให้ Warsong" }, [16744] = { "11:152020423:796643193", "น้ำมัน Warsong" }, [16743] = { "12:449436495:994483679", "เชือกชักลากไม้" } },
        steps = { { "18:1757851282:1761557611", "ใบเลื่อย Warsong" }, { "20:1041639644:2084735458", "ขวานที่ส่งมาให้ Warsong" }, { "11:152020423:796643193", "น้ำมัน Warsong" }, { "12:449436495:994483679", "เชือกชักลากไม้" } },
    },
    [6581] = { -- Warsong Saw Blades
        title = { "18:1757851282:1761557611", "ใบเลื่อย Warsong" },
        progress = { "467:1232224679:481852925", "ใบเลื่อย Warsong ส่งตรงจาก Ratchet! ใช่ อยู่กับข้าตรงนี้\n\n...แต่เจ้ามีอะไรมาจ่าย? จะหยิบไปเฉย ๆ ไม่ได้นะ เวลาข้าไม่ใช่ของราคาถูก!\n\nสิ่งที่ต้องการจริง ๆ คือปืนดี ๆ ไว้พกระหว่างเดินทาง ผู้หญิงก็ต้องป้องกันตัวเอง ข้าชอบปืนแบบหนึ่ง มั่นใจว่าวิศวกรสร้างได้ไม่ยาก\n\nหากนำ Deadly Blunderbuss มาให้ ข้าจะมอบใบเลื่อยที่ส่งมานี้ ตกลงไหม?" },
        completion = { "61:146234755:427889825", "สมบูรณ์แบบ ใช่เลย! เอาล่ะ นี่ของที่ส่งมา" },
        description = { "467:1232224679:481852925", "ใบเลื่อย Warsong ส่งตรงจาก Ratchet! ใช่ อยู่กับข้านี่แหละ\n\nแต่ว่า... เจ้ามีอะไรจะจ่ายให้ข้าล่ะ? จะหยิบไปเฉย ๆ ไม่ได้หรอกนะ เวลาข้ามีค่า!\n\nที่ข้าต้องการจริง ๆ คือปืนดี ๆ สักกระบอกไว้พกเวลาเดินทาง ผู้หญิงก็ต้องป้องกันตัวเองนะ มีปืนอยู่รุ่นหนึ่งที่ข้าชอบมาก ช่างวิศวกรรมทำได้สบายอยู่แล้ว\n\nถ้าเจ้าเอา Deadly Blunderbuss มาให้ ข้าจะยกใบเลื่อยชุดนี้ให้ ตกลงไหม?" },
        required = { [4369] = { "18:383638155:1179125482", "ปืนปากแตรพิฆาต" } },
        objectiveLabels = {
            item = { ["Deadly Blunderbuss"] = "ปืนปากแตรพิฆาต" },
        },
    },
    [6621] = { -- King of the Foulweald
        title = { "21:1462141597:199814284", "ราชาแห่ง Foulweald" },
        objective = { "172:767847096:1404856028", "ปัก Karang's Banner บน Foulweald Totem Mound อย่าให้เฟอร์โบลก์ทำลายธง เอาชนะ Chief Murgut แล้วนำ Murgut's Totem ไปให้ Karang Amakkar ที่ Zoram'gar" },
        description = { "N 457:1330106531:529800703 N 31:545122916:316712653 C 1:46:46", "{name} เฟอร์โบลก์อีกเผ่าชื่อ Foulweald อยู่ทางตะวันออกเฉียงใต้ของ Astranaar แม้จำนวนน้อยกว่า Thistlefur แต่ความดุร้ายจะเป็นภัยในอนาคต เราขจัดภัยได้ด้วยการแสดงพลัง\n\nนำธงนี้ไปปักบนเนินโทเท็มในหมู่บ้าน Foulweald พวกมันจะพยายามทำลายธง จงยืนหยัดจนหัวหน้า Murgut ออกมากู้หน้าเผ่า แล้วนำโทเท็มที่เขาถือมาให้ข้า\n\nรวบรวมสหายของเจ้า {name} นี่ไม่ใช่งานสำหรับ {class} เพียงคนเดียว" },
        progress = { "29:2120143927:1504916832 N 39:1340172569:2133383779", "เอาชนะ Chief Murgut แล้วหรือยัง {name}? เอา Foulweald Totem ของเขามาหรือเปล่า?" },
        completion = { "11:354343371:1318038540 N 207:1025151709:1192838680", "ทำได้ดี {name} การท้าทาย Foulweald และเอาชนะผู้นำส่งสารหนักแน่นถึงพวกมันว่า:\n\nอย่าคิดเล่นกับ Horde\n\nข้าเชื่อว่าเผ่านี้คงไม่สร้างปัญหาให้เราไปอีกนาน", variants = { { "11:354343371:1318038540 N 210:1379163394:2024123192", "ทำได้ดี {name} การท้าทาย Foulweald และเอาชนะผู้นำส่งสารหนักแน่นถึงพวกมันว่า:\n\nอย่าคิดเล่นกับ Horde\n\nข้าเชื่อว่าเผ่านี้คงไม่สร้างปัญหาให้เราไปอีกนาน" } } },
        required = { [16976] = { "14:558420076:1782856105", "โทเท็มของ Murgut" } },
        steps = { { "14:558420076:1782856105", "โทเท็มของ Murgut" } },
    },
    [6629] = { -- Kill Grundig Darkcloud
        title = { "22:1822570180:1547278971", "ฆ่า Grundig Darkcloud" },
        objective = { "118:1083838402:1004383229", "ฆ่า Grundig Darkcloud และ Grimtotem Brutes 6 ตัว แล้วกลับไปหา Makaba Flathoof ใกล้ชายขอบตะวันออกเฉียงใต้ของ Stonetalon" },
        description = { "N 311:1340411938:1319991587", "{name} เจ้าจัดการ Grimtotem ได้ดี หากเจ้ากล้า Grundig Darkcloud กับกลุ่มลูกสมุนส่วนตัวเลวร้ายที่สุด เขาเป็นคนนำการโจมตีหมู่บ้านข้าอย่างโหดเหี้ยม\n\nหาเขาได้ที่ Grimtotem Post เลยตามทางตะวันตกไปอีกหน่อย ฆ่าเขา แล้วข้าจะขอบคุณตลอดไป" },
        progress = { "66:401365943:1599859823", "ฆ่า Grundig Darkcloud กับกลุ่ม Brutes ส่วนตัวของเขาแล้วหรือยัง?" },
        completion = { "27:123174765:1788924280 N 60:1023107739:1340640428", "Grundig Darkcloud ตายแล้ว! {name} ข้าจะซาบซึ้งสิ่งที่เจ้าทำวันนี้ตลอดไป" },
        objectiveLabels = {
            monster = { ["Grundig Darkcloud slain"] = "ปราบ Grundig Darkcloud", ["Grimtotem Brute slain"] = "ปราบ นักเลงจอมโหด Grimtotem" },
        },
    },
    [6641] = { -- Vorsha the Lasher
        title = { "17:503843448:1249462828", "Vorsha the Lasher" },
        objective = { "252:2064949157:917033942", "คุ้มครอง Muglash ระหว่างเดินทางไปกระถางไฟ ช่วยดับไฟ แล้วปกป้องเขาขณะต่อสู้กับนากา\n\nหากสำเร็จ กลับไป Zoram'gar Outpost แล้วแจ้ง Warsong Runner ว่า Vorsha the Lasher ตายแล้ว" },
        description = { "180:402988575:1201517538 N 304:1732352089:1311431743", "Vorsha the Lasher... ไฮดราชั่วร้ายผู้ท่องทะเล...\n\nนางโจมตีฐานเราโดยไม่ถูกยั่วยุทุกครั้ง ทำลายทุกสิ่งที่ขวางทาง\n\nแต่ข้าพร้อมแล้ว {name} ข้าเตรียมโค่นไฮดราและหยุดการโจมตี Zoram'gar\n\nนากายกย่องความชั่วร้ายของสัตว์นี้ด้วยกระถางไฟที่จุดไว้ตลอด บนเกาะใกล้ฝั่ง ข้าเชื่อว่าหากดับไฟ Vorsha จะโกรธและปรากฏตัว\n\nเราต้องมีคนช่วย อย่าลืมพาสหายแข็งแกร่งมาด้วย" },
        completion = { "142:1562256596:1752251323 N 1:46:46", "ตั้งแต่มาถึงที่นี่ ข้าเห็นนากาโจมตีหลายครั้ง รู้ว่า Vorsha จะไม่ท่องไปได้อย่างเสรีอีกก็สบายใจขึ้น\n\nเราเป็นหนี้เจ้า {name}" },
        objectiveLabels = {
            event = { ["Defeat Vorsha the Lasher"] = "เอาชนะ Vorsha the Lasher" },
        },
    },
    [86576] = { -- Bloodfury Trinkets
        title = { "18:1704555865:875987818", "ของประดับ Bloodfury" },
        objective = { "43:703287579:473943466", "นำ Glittering Sunstones 15 ชิ้น ไปให้ Mor'rogal", amount = { "6:1273960851:929420321 W1 35:267699608:1572022715", "นำ Glittering Sunstones {world1} ชิ้น ไปให้ Mor'rogal" } },
        description = { "440:1307898486:2040652782", "นอกจากแพร่ความโสโครกทั่ว Charred Vale แล้ว ฮาร์ปี Bloodfury ยังเก็บทุกอย่างที่แวววาว ได้ยินว่าพวกมันสะสมหินตะวันสีเหลืองทองไว้ประดับ ข้าไม่ต้องใช้ของพวกนั้น แต่ Mor'rogal เคยพูดถึงการใช้มัน\n\nระหว่างต่อสู้กับฮาร์ปีในหุบเขา คอยหา Glittering Sunstones นำที่พบไปให้ Mor'rogal บนเนินเหนือเรา" },
        progress = { "59:1432868600:1130851223", "ข้ามีเรื่องสำคัญต้องคิด นักผจญภัย ว่ามาเร็ว ๆ", variants = { { "38:902198043:436609664 C 11:484730368:505327099", "ข้ามีเรื่องสำคัญต้องคิด {class} ว่ามาเร็ว ๆ" } } },
        completion = { "460:2121990568:1179288715", "อา เจ้านำหินตะวันที่ฮาร์ปีสะสมมาแล้ว! พวกมันชอบเก็บของแวววาว แต่ไม่รู้คุณค่าที่แท้จริงของหิน หินเหล่านี้จับแสงอาทิตย์เจิดจ้าและสะท้อนความสง่างาม ให้เราประดับศาลและบ้านด้วยประกายเล็ก ๆ เพื่อยกย่องดวงตะวัน ยามค่ำคืน ดวงจันทร์ก็ส่องให้มันงดงามด้วยแสงเงิน\n\nหินเหล่านี้เตือนถึงสายสัมพันธ์ของเรากับแสงบนท้องฟ้า" },
        required = { [277936] = { "19:109903394:2057046573", "ศิลาตะวันระยิบระยับ" } },
        steps = { { "19:109903394:2057046573", "ศิลาตะวันระยิบระยับ" } },
    },
    [97265] = { -- Hate the Hatefury
        title = { "17:848306901:1362679891", "แค้น Hatefury" },
        objective = { "108:1851244049:659605385", "เอาชนะซาเทอร์ Hatefury หลายชนิดที่ Sargeron ใน Desolace แล้วกลับไปหา Aka'rai ที่ Shadowprey Village" },
        description = { "475:1894388466:2132780957", "เคยตกลงกับซาเทอร์ไหมเพื่อน?\n\nข้าเคย จะอดใจได้อย่างไร? ทั้งคำสัญญาว่าจะได้พลัง ความรู้ล้ำเกินตำราธรรมดา... พร้อมสมุนกระตือรือร้นมีเสน่ห์ จะขออะไรอีก?\n\nชิ แน่นอนว่าพวกมันไม่ยอมก้มหัวให้ผู้ต้องตาย ข้าต่อรองตอนที่ไม่มีอะไร แต่กลับถูกทิ้งโดยเหลือน้อยกว่าเดิม\n\nตอนนี้ข้าต้องการแก้แค้น แก้แค้น Hatefury บุกค่ายทางตะวันออกเฉียงเหนือ! ให้เลือดโสมมของพวกมันเปื้อนผืนดิน" },
        completion = { "471:1290430746:254724246", "ข้าอยากได้เห็นเจ้าสู้ด้วยตาตัวเอง อยากได้ยินเสียงร้องน่าสมเพชตอนพวกมันล้มลงด้วยฝีมือเจ้า\n\nแต่ต้องมีตัวหนึ่งรอดการเข่นฆ่าของเจ้าแน่ ตัวที่ข้าเคยจับมือทำพิธีโลหิต ตราบใดที่มันยังเดินเพ่นพ่านใน Desolace ข้าก็เสี่ยงก้าวออกจาก Shadowprey ไม่ได้ มันจะตามหาข้าเจออีก และถ้าศิลาวิญญาณของข้ายังอยู่ในมือมัน... แม้แต่ความตายก็หนีมันไม่พ้น\n\nสักวันข้าจะเอาคืนมา แต่ตอนนี้งานของเจ้าเสร็จแล้ว" },
        objectiveLabels = {
            monster = { ["Hatefury Trickster slain"] = "ปราบ นักต้มตุ๋น Hatefury", ["Hatefury Hellcaller slain"] = "ปราบ ผู้เรียกอสูร Hatefury", ["Hatefury Shadowstalker slain"] = "ปราบ นักสะกดรอยในเงามืด Hatefury", ["Hatefury Felsworn slain"] = "ปราบ ผู้สาบานตนต่อเฟล Hatefury", ["Hatefury Rogue slain"] = "ปราบ โจร Hatefury" },
        },
    },
    [97538] = { -- Pigments for Paints
        title = { "19:1188537536:1845813948", "เม็ดสีสำหรับวาดภาพ" },
        objective = { "76:839746139:960505602", "Tah Winterhoof ที่ Thunder Bluff ต้องการ Mirkweed Pods 30 ชิ้น จาก Mirkfallon Lake", amount = { "38:2043233473:1804861515 W1 36:556099147:1484360744", "Tah Winterhoof ที่ Thunder Bluff ต้องการ Mirkweed Pods {world1} ชิ้น จาก Mirkfallon Lake" } },
        description = { "508:1911294797:2080179918", "สวัสดีสหาย ข้าขอรบกวนหน่อยได้ไหม? เม็ดสีแดงสำหรับวาดภาพเพิ่งหมด ข้ากำลังหาผู้มีกีบที่อ่อนเยาว์กว่าเดินทางไกลไป Stonetalon Mountains แทน\n\nกลางเส้นทางผ่านเขามีทะเลสาบกลมขนาดใหญ่ Mirkfallon Lake ในน้ำมีพืชพิเศษชื่อ mirkweed ฝักของมันจะเปลี่ยนเป็นแดงสดเมื่อแห้ง เก็บฝักมาให้ข้า แล้วข้าจะตอบแทนความพยายามอย่างดี" },
        progress = { "354:966110696:405556175", "เจ้ากลับมาแล้ว! หาฝัก mirkweed ใน Mirkfallon Lake ได้หรือไม่?\n\nทอเรนใช้เม็ดสีจากพืชนี้วาดภาพมาหลายชั่วอายุคนแล้ว ไม่ว่าเจ้าจะหามาได้เท่าไรก็ขอบใจ แม้มีวิธีทำสีแดงมากมาย ข้าพบว่า mirkweed ให้สีเข้มข้นและสดใสที่สุดในบรรดาวิธีที่รู้จัก" },
        completion = { "15:77186111:238310768 N 323:880416259:2117328842", "อา ขอบใจ {name}\n\nมีความหมายกับข้ามากที่เจ้ายอมเดินทางไปไกลขนาดนั้น เพื่อเรื่องที่เจ้าอาจมองว่าเป็นเพียงความคิดเล็ก ๆ น้อย ๆ ของทอเรนแก่ ๆ คนหนึ่ง เพราะน้ำใจของเจ้า ข้าจึงมีผงสีใช้พอไปจนหมดฤดูกาล\n\nขอบใจที่ช่วยให้ข้าทำมาหากินต่อไปได้ ข้าจะตั้งใจใช้ผงสีที่เจ้านำมาสร้างผลงานให้สวยงามสมกับที่เจ้าช่วยข้า" },
        required = { [278201] = { "13:1659711605:764814187", "ฝัก Mirkweed" } },
        steps = { { "13:1659711605:764814187", "ฝัก Mirkweed" } },
    },
    [1064] = { -- Forsaken Aid
        title = { "12:1126773075:1677523240", "ความช่วยเหลือจาก Forsaken" },
        objective = { "68:54344687:1056280634", "คุยกับ Apothecary Zamah ที่ Pools of Vision ใน Thunder Bluff" },
        description = { "490:559359241:11648266", "ทอเรนผูกพันกับผืนดิน ข้าจึงเจ็บปวดที่ได้ยินความทุกข์ของ Stonetalon แต่เกรงว่าหากจะรักษาผืนดิน เราต้องขจัดโรคที่เกาะกินก่อน\n\nนับว่าโชคดีไม่ใช่หรือที่ Forsaken เป็นพันธมิตรกับเรา? พวกเขารู้เรื่องโรคภัยมาก ข้าเชื่อว่าช่วยได้ และยังเสริมความไว้ใจระหว่างชนเผ่าเรา\n\nไปคุยกับ Apothecary Zamah นางเป็นนักวิชาการและทูต Forsaken อยู่ที่ Pools of Vision ใต้ Spirit Rise" },
        completion = { "34:174249014:1532134553 N 137:1073928427:881571566", "Magatha แจ้งว่าเจ้าจะมาแล้ว {name} แม้หัวใจข้าไม่เต้นอีก แต่ยังเศร้าใจแทนวิญญาณแห่ง Stonetalon\n\nForsaken ยินดีช่วยทุกอย่างที่ทำได้" },
    },
    [1065] = { -- Journey to Tarren Mill
        title = { "22:274997761:274206373", "เดินทางสู่ Tarren Mill" },
        objective = { "54:1573243642:1966506315", "นำ Zamah's Note ไปให้ Apothecary Lydon ที่ Tarren Mill" },
        description = { "492:1417086451:1153811169", "เพื่อขับ Venture Company ออกจาก Stonetalon เราต้องใช้มาตรการรุนแรง รุนแรงแต่ไม่เสียเลือด\n\nเพื่อนร่วมงานข้าคนอาจมีเครื่องมือที่ต้องการ เขาชื่อ Lydon อยู่ที่เมือง Tarren Mill ใน Hillsbrad Foothills บนดินแดน Lordaeron อันไกลโพ้น\n\nไป Hillsbrad โดยขึ้นเรือเหาะสู่ Undercity เมืองหลวงของเรา จากนั้นไปเหนือเข้า Tirisfal Glades ไปตะวันตกเฉียงใต้สู่ Silverpine แล้วลงใต้เข้า Hillsbrad\n\nหา Lydon แล้วนำจดหมายนี้ให้ มันอธิบายสิ่งที่เราต้องการไว้" },
        progress = { "43:1357281013:261232994", "อา เจ้ามาพร้อมตัวทดลองใหม่ของข้าหรือ?" },
        completion = { "137:2576341:1480872330", "จดหมายจาก Zamah หรือ? นางคงต้องการมาก จึงส่งสารมาไกลเช่นนี้ มาดูว่านางว่าอย่างไร...\n\nอา เยี่ยมมาก! ข้ารู้แล้วว่าต้องทำอะไร!" },
        required = { [5628] = { "12:412573408:1776034969", "ข้อความของ Zamah" } },
        steps = { { "12:412573408:1776034969", "ข้อความของ Zamah" } },
    },
    [1066] = { -- Blood of Innocents
        title = { "18:1018721714:806295538", "เลือดผู้บริสุทธิ์" },
        objective = { "67:1640500111:295466226", "นำ Vials of Innocent Blood 5 ขวด ไปให้ Apothecary Lydon ที่ Tarren Mill" },
        description = { "491:428432438:20628500", "ข้าจะสร้างพิษที่สลายความรุนแรงของ Venture Company ทำให้พวกมันอ่อนแอและเชื่อง น่าจะแก้ปัญหา Horde ที่ Stonetalon ได้ใช่ไหม?\n\nแต่การสร้างพิษต้องใช้เลือดผู้บริสุทธิ์ ซึ่งหาได้ยาก\n\nโชคดีที่ Syndicate กลุ่มโจรมนุษย์แถบนี้จ้างจอมเวทเงา... พวกเขาเก็บเลือดผู้บริสุทธิ์ไว้ใช้เพื่อจุดประสงค์อันน่ารังเกียจ\n\nหา Syndicate Shadow Mages ได้ที่ Durnholde Keep ทางตะวันออกเฉียงใต้" },
        progress = { "73:359286377:179405973", "เจ้าพบ Syndicate Shadow Mages และเก็บเลือดจากพวกเขาแล้วหรือยัง?" },
        completion = { "249:1541107159:1780178473", "ดีมาก! หวังว่า Syndicate คงไม่สร้างปัญหามากนัก?\n\nอย่างที่บอก เลือดผู้บริสุทธิ์หาไม่ได้ง่าย เราโชคดีที่จอมเวทเงา Syndicate ทำงานยากแทน\n\nรอสักครู่ ให้ข้าปรุงน้ำยาก่อน..." },
        required = { [5620] = { "22:672670126:1200508138", "ขวดบรรจุเลือดผู้บริสุทธิ์" } },
        steps = { { "22:672670126:1200508138", "ขวดบรรจุเลือดผู้บริสุทธิ์" } },
    },
    [1067] = { -- Return to Thunder Bluff
        title = { "23:1226102165:1989355423", "กลับ Thunder Bluff" },
        objective = { "57:1448061123:1302827902", "นำ Lydon's Toxin ไปให้ Apothecary Zamah ที่ Thunder Bluff" },
        description = { "315:2072545743:620251862", "นี่คือพิษ ใช้กับ Venture Company แล้วน่าจะได้ผลตามต้องการ บางทีอาจติดต่อกันได้ด้วย ต้องบอกว่าน่าตื่นเต้นที่งานข้าถูกนำไปใช้จริง!\n\nแต่ก่อนใช้ นำไปให้ Apothecary Zamah ก่อน นางต้องหาวิธีปล่อยพิษให้ได้ผลสูงสุด" },
        progress = { "19:2050034882:1559736641 N 41:1859363112:1656519033", "เจ้ากลับมาแล้ว {name} นำความช่วยเหลือจาก Apothecary Lydon มาหรือไม่?" },
        completion = { "129:580479228:541257606", "พิษจาก Apothecary Lydon หรือ? ดีมาก จากที่ข้ารู้จักเขา พิษนี้คงได้ผลกับ Venture Company อย่างยิ่ง..." },
        required = { [5588] = { "13:762310246:806917346", "สารพิษของ Lydon" } },
        steps = { { "13:762310246:806917346", "สารพิษของ Lydon" } },
    },
    [1086] = { -- The Flying Machine Airport
        title = { "26:960368159:756695872", "สนามบินเครื่องบินจักรกล" },
        objective = { "84:1063818706:1078648802", "นำ Toxic Fogger ไปที่ท่าอากาศยาน Venture Co. แล้วกลับไปหา Apothecary Zamah" },
        description = { "59:71370431:267340676 N 435:414381168:1092560284", "พิษพร้อมแล้ว เหลือเพียงนำไปส่ง เจ้า {name} ต้องเป็นผู้ส่ง\n\nVenture Company ต้องมีวิธีส่งข้อความกับสินค้าน้ำหนักเบาระหว่างสำนักงานใหญ่และงานใน Stonetalon น่าจะเป็นท่าอากาศยานเล็ก ๆ ไม่ใหญ่พอรับเรือเหาะ แต่อาจรับเครื่องบินจักรกลได้ เจ้าต้องค้นหาพื้นที่ Stonetalon ที่ Venture Company ควบคุม หากท่าแห่งนี้มีจริงและพบมัน จงวางพิษไว้ที่นั่น\n\nวางแล้ววิ่งหนี" },
        progress = { "56:1436883680:2121808389 N 1:46:46", "เจ้าต้องหาสนามบิน Venture Company หากมีอยู่จริง {name}" },
        completion = { "31:586126490:531409475 N 426:1051667735:2123674588", "พบท่าแล้วหรือ? ทำได้ดี {name}! ก็อบลินคงประหลาดใจกับสิ่งที่เจ้าส่งให้ หวังว่าพิษจะไปถึงสำนักงานใหญ่ของพวกมัน\n\nเจ้ารับใช้ชนเผ่าได้ดี ข้าแนะนำให้ละความรู้สึกผิดที่วางพิษ Venture Company พวกมันสมควรเจอเลวร้ายกว่านั้น\n\nและหากมีภูมิปัญญาสักข้อที่ Forsaken สอนพันธมิตรได้ ก็คือ:\n\nอย่าหลีกหนทางมืด... หากหนทางนั้นนำสู่ชัยชนะ" },
        objectiveLabels = {
            event = { ["Place the Toxic Fogger"] = "วาง Toxic Fogger" },
        },
    },
    [1483] = { -- Ziz Fizziks
        title = { "11:602262750:1005859949", "Ziz Fizziks" },
        objective = { "41:1603728857:481229343", "คุยกับ Ziz Fizziks ที่ Windshear Crag" },
        description = { "505:588987327:959073010", "Venture Company แย่งยอดฝีมือก็อบลินไปมาก แต่บางครั้งเราก็ได้โอกาสแย่งคืน\n\nไม่นานมานี้ หน่วย Venture Company ใน Stonetalon Mountains จ้าง Gerenzo Wrenchwhistle ซึ่งเป็นโนม! วิศวกรอีกคน Ziz Fizziks ตกใจมากจนขอให้ข้าหางานใหม่ใน Tinkers' Union ให้ ข้าให้เขาทำงานไว้หลายอย่าง แต่อาจต้องการคนช่วย\n\nเจ้าช่วยไปดูเขาแทนข้าได้ไหม? เขาอยู่ริม Windshear Crag ด้านตะวันตก" },
        completion = { "273:1786558089:465543674", "ข้าเคยคิดว่าผู้บริหาร Venture Company ใช้งานคนเยี่ยงทาส จนได้พบ Sputtervalve ผู้โหดที่สุด!\n\nฮ่า! แต่ก็คงดีกว่าตกงาน... หรือแย่กว่านั้น ต้องทำงานกับ Gerenzo หากเจ้ามาช่วย ข้ามีงานให้ทำ" },
    },
    [1453] = { -- Reclaimers' Business in Desolace
        title = { "32:1196294797:1877716791", "งาน Reclaimers ใน Desolace" },
        objective = { "35:560351324:1183304371", "คุยกับ Kreldig Ungor ใน Desolace" },
        description = { "37:320811997:1900025898 N 398:2098942192:2027224234", "มีงานต้องทำที่ Desolace {name} เป็นที่น่าเกลียด ถูกเซนทอร์กับตัวร้ายอื่นทำให้โสโครก แต่ถ้าอยากทำงานสุจริตสักสัปดาห์ ก็ไปพบ Kreldig Ungor บอกว่าข้าส่งมา\n\nเขาอยู่ที่ Nijel's Point ค่ายเล็กอบอุ่นที่ซ่อนในภูเขาทางเหนือของ Desolace หากเข้ามาจาก Stonetalon Mountains ก็ตรงไปทางตะวันออก พลาดได้ง่าย คอยมองให้ดี" },
        completion = { "108:1354895639:972050165 N 281:1612079644:1995331636", "ดีที่ Reclaimers ยังไม่ขาดงานหรือนักผจญภัยที่ยอมช่วย\n\nข้าชื่อ Kreldig {name} เจ้าเลือกถูกแล้วที่ช่วย Reclaimers สมัยนี้ทุกคนต้องการอะไรสักอย่าง ไม่ว่ามรดกตกทอด ไอเทมเวทมนตร์ หรือคนที่รักซึ่งสูญหาย ไม่มีทางรู้ล่วงหน้า แต่เมื่อมี Reclaimers หากจ่ายเหมาะสม ทุกคนก็มีโอกาสได้สิ่งที่หายไปคืน" },
    },
    [6543] = { -- The Warsong Reports
        title = { "19:1787902412:1265530260", "รายงาน Warsong" },
        objective = { "203:389161129:1440092866", "เปิด Bundle of Reports นำ Warsong Reports ไปให้ Warsong Scout, Warsong Runner และ Warsong Outrider แล้วนำรายงานล่าสุดที่ได้รับกลับไปให้ Kadrak ที่หอสังเกตการณ์ทางเหนือของ Barrens" },
        description = { "498:994422635:995268506", "ข้าเพิ่งส่งหน่วยสอดแนมเข้า Ashenvale หลายคน ต้องการคนวิ่งส่งคำสั่งและนำรายงานสิ่งที่พวกเขาพบกลับมา\n\nจุดแรกควรเป็น Zoram'gar Outpost บนชายฝั่งด้านตะวันตกที่ Zoram Strand เพื่อหา runner คนแรก จากนั้นต้องแวะ Splintertree Post ทางเหนือ และตามถนนตะวันออกใกล้ Azshara จะพบ scout กับ outrider ที่นั่น\n\nส่งรายงานให้แต่ละคน แล้วรับข้อมูลล่าสุดที่พบกลับมา" },
        progress = { "7:2044825444:644190917 N 48:1660403004:425663542", "รีบเถอะ {name} พวกเขาต้องได้รับรายงาน เป็นเรื่องเร่งด่วน" },
        completion = { "158:1126191513:1871380593", "ข้าเห็นแล้วว่าเจ้าพึ่งพาได้ ข้อมูลล่าสุดนี้สำคัญต่อแผนเพิ่มอำนาจของเราใน Ashenvale ตอนนี้วางแผนก้าวต่อไปได้แล้ว" },
        required = { [16764] = { "20:412229072:1231784767", "รายงานล่าสุดจากหน่วยลาดตระเวน Warsong" }, [16763] = { "21:1776988819:44957051", "รายงานล่าสุดจากคนส่งข่าว Warsong" }, [16765] = { "23:1850986197:904367435", "รายงานล่าสุดจากพลม้าลาดตระเวน Warsong" } },
        steps = { { "20:412229072:1231784767", "รายงานล่าสุดจากหน่วยลาดตระเวน Warsong" }, { "21:1776988819:44957051", "รายงานล่าสุดจากคนส่งข่าว Warsong" }, { "23:1850986197:904367435", "รายงานล่าสุดจากพลม้าลาดตระเวน Warsong" } },
    },
    [235] = { -- The Ashenvale Hunt
        title = { "18:470123318:630157178", "การล่าแห่ง Ashenvale" },
        objective = { "63:644160388:1168549108", "คุยกับ Senani Thunderheart ที่ Splintertree Post ใน Ashenvale" },
        description = { "462:1398010130:2078952964", "เหล่านักผจญภัยรุ่นเยาว์จงฟัง! ป่าแห่ง Ashenvale รอเจ้าอยู่!\n\nHorde ตั้งมั่นในดินแดนเหนือ Barrens แล้ว ฐานทั้งสองของเรา Splintertree Post กับ Zoram Strand Outpost มุ่งสร้างเกียรติแก่ Horde! ผู้ที่อยากพิสูจน์ตนควรไปขอคำแนะนำที่นั่น โดยเฉพาะ Senani Thunderheart ที่ Splintertree Post ทางเหนือจาก Barrens โดยตรง กำลังหานักผจญภัยที่ยินดีร่วมการล่าครั้งใหญ่ใน Ashenvale!" },
        completion = { "29:1583511806:1798444235 N 56:1723226412:436207449 C 341:1155779532:538292366", "ยินดีต้อนรับสู่ชายแดนใหม่ {name} Ashenvale เป็นดินแดนแห่งโอกาส ที่{class}รุ่นเยาว์อย่างเจ้ามีโอกาสพิสูจน์ความสามารถไม่สิ้นสุด ลองดูรอบฐานนี้ และอย่าลืมไป Zoram Strand เพราะ Horde มีอีกฐานอยู่ที่นั่นด้วย\n\nการมาถึงของเจ้าบอกว่าอยากรู้เรื่องการล่า ฟังให้ดี ข้ายินดีบอกสิ่งที่ต้องรู้" },
    },
    [742] = { -- The Ashenvale Hunt
        title = { "18:470123318:630157178", "การล่าแห่ง Ashenvale" },
        objective = { "63:644160388:1168549108", "คุยกับ Senani Thunderheart ที่ Splintertree Post ใน Ashenvale" },
        description = { "462:1398010130:2078952964", "เหล่านักผจญภัยรุ่นเยาว์จงฟัง! ป่าแห่ง Ashenvale รอเจ้าอยู่!\n\nHorde ตั้งมั่นในดินแดนเหนือ Barrens แล้ว ฐานทั้งสองของเรา Splintertree Post กับ Zoram Strand Outpost มุ่งสร้างเกียรติแก่ Horde! ผู้ที่อยากพิสูจน์ตนควรไปขอคำแนะนำที่นั่น โดยเฉพาะ Senani Thunderheart ที่ Splintertree Post ทางเหนือจาก Barrens โดยตรง กำลังหานักผจญภัยที่ยินดีร่วมการล่าครั้งใหญ่ใน Ashenvale!" },
        completion = { "29:1583511806:1798444235 N 56:1723226412:436207449 C 341:1155779532:538292366", "ยินดีต้อนรับสู่ชายแดนใหม่ {name} Ashenvale เป็นดินแดนแห่งโอกาส ที่{class}รุ่นเยาว์อย่างเจ้ามีโอกาสพิสูจน์ความสามารถไม่สิ้นสุด ลองดูรอบฐานนี้ และอย่าลืมไป Zoram Strand เพราะ Horde มีอีกฐานอยู่ที่นั่นด้วย\n\nการมาถึงของเจ้าบอกว่าอยากรู้เรื่องการล่า ฟังให้ดี ข้ายินดีบอกสิ่งที่ต้องรู้" },
    },
    [1432] = { -- Alliance Relations
        title = { "18:1907397034:1825629155", "ความสัมพันธ์กับ Alliance" },
        objective = { "39:1307726133:905227120", "คุยกับ Takata Steelblade ใน Desolace" },
        description = { "493:1438466384:705450797", "เมื่อ Alliance รุกลึกเข้า Kalimdor มากขึ้น อาจสรุปผิดว่า Horde ทำสัญญากับ Burning Legion ประมุขศึกยอมให้เป็นเช่นนั้นไม่ได้ และด้วยความเห็นชอบของเขา ข้ารับหน้าที่ดูแลการกำจัดพวกนั้น\n\nข้ามีเจ้าหน้าที่ใน Desolace ที่ Ghost Walker Post ทางเหนือของ Kodo Graveyard ใหญ่ ไปทางใต้จาก Charred Vale ใน Stonetalon Mountains แล้วจะพบ เมื่อถึงให้หา Takata Steelblade" },
        completion = { "11:927657569:725753248 C 457:1672602094:115850586", "สวัสดี {class} เจ้านำข่าวจาก Orgrimmar มา ดีแล้ว\n\nปีศาจแพร่เต็มพื้นที่นี้ยิ่งกว่ากลิ่นมูลเซนทอร์ พวกคนม้าอ้างว่าดินแดนเป็นของตน แต่เห็นชัดว่ามีอำนาจที่ควบคุมไม่ได้ ซึ่งจะบดขยี้พวกมันหากไม่หยุดยั้ง\n\nข้าไม่ชอบที่เราช่วยเซนทอร์ทางอ้อม แต่เพื่อ Horde ข้าจึงทำหน้าที่ต่อประมุขศึก แม้หมายถึงการช่วยวอร์ล็อกใน Horde ด้วยก็ตาม" },
    },
    [2967] = { -- Return to Thunder Bluff
        title = { "23:1226102165:1989355423", "กลับ Thunder Bluff" },
        objective = { "42:1966878617:1076197491", "คุยกับ Nara Wildmane ที่ Thunder Bluff" },
        description = { "277:434919849:1997152192", "เจ้าใช้งานแท่นอีกครั้ง จู่ ๆ แผ่นดิสก์แพลทินัมก็ปรากฏในเป้ของเจ้าอีกหน\n\nเมื่อได้รับความรู้จาก Stone Watcher และได้แผ่นดิสก์คืนแล้ว ก็ถึงเวลากลับ Thunder Bluff เพื่อแจ้งสิ่งที่ค้นพบแก่ Nara Wildmane" },
        progress = { "13:23130796:2039583150 N 73:900514056:2059652495", "ยินดีต้อนรับกลับ {name} เจ้าใช้แผ่นดิสก์ให้เกิดประโยชน์ได้ไหม หรือสูญเปล่า?" },
        completion = { "455:15848662:251377486", "เจ้าขาดแผ่นดิสก์บางส่วนหรือ? น่าสนใจ ดูเหมือน Discs of Norgannon เป็นเพียงบางส่วนของชุดที่สมบูรณ์ คล้ายกุญแจแต่ละดอกบนพวงนั่นเอง\n\nถ้าหา Plates of Uldum ได้ เราก็จะเข้าไปในกลุ่มอาคาร Uldum จริง ๆ ข้าไม่รู้ว่าควรตื่นเต้นหรือหวาดกลัว\n\nเราอาจต้องเสี่ยงทุกอย่าง เพื่อให้ความลับที่โลกเก็บไว้และอาจทำลายเราทุกคนยังคงเป็นเพียงความลับ" },
        required = { [6064] = { "24:500077704:355707172", "แผ่นแพลทินัมขนาดย่อม" } },
        steps = { { "24:500077704:355707172", "แผ่นแพลทินัมขนาดย่อม" } },
    },
    [6382] = { -- The Ashenvale Hunt
        title = { "18:470123318:630157178", "การล่าแห่ง Ashenvale" },
        objective = { "63:644160388:1168549108", "คุยกับ Senani Thunderheart ที่ Splintertree Post ใน Ashenvale" },
        description = { "28:1353611860:459679216 C 438:1269008214:917540835", "พลังของเจ้าน่าประทับใจ {class} ความเต็มใจยอมรับวิถีล่าทำให้ข้ามั่นใจว่าเจ้าพร้อมไปหาเหยื่อใหญ่ขึ้น... และความท้าทายที่ยิ่งใหญ่ขึ้น\n\nป่า Ashenvale คือผืนพงไพรกว้างใหญ่ที่ยังไม่สยบ ซึ่ง Horde มุ่งจะให้เป็นไปตามเจตจำนงของตน ทั้งทางการเมืองและจิตวิญญาณ หากอยากพิสูจน์ตัวในดินแดนที่ยังไม่เคยพิสูจน์ฝีมือ จงไปขอคำแนะนำจาก Senani Thunderheart ที่ Splintertree Post ด่านอยู่ตรงขึ้นเหนือจากเส้นทางที่มาจาก Barrens" },
        completion = { "29:1583511806:1798444235 N 56:1723226412:436207449 C 341:1155779532:538292366", "ยินดีต้อนรับสู่ชายแดนใหม่ {name} Ashenvale เป็นดินแดนแห่งโอกาส ที่{class}รุ่นเยาว์อย่างเจ้ามีโอกาสพิสูจน์ความสามารถไม่สิ้นสุด ลองดูรอบฐานนี้ และอย่าลืมไป Zoram Strand เพราะ Horde มีอีกฐานอยู่ที่นั่นด้วย\n\nการมาถึงของเจ้าบอกว่าอยากรู้เรื่องการล่า ฟังให้ดี ข้ายินดีบอกสิ่งที่ต้องรู้" },
    },
    [6541] = { -- Report to Kadrak
        title = { "16:1966035642:1310894047", "รายงานต่อ Kadrak" },
        objective = { "56:2113603299:1793595057", "รายงานตัวกับ Kadrak ที่หอสังเกตการณ์ทางเหนือของ Barrens" },
        description = { "345:1495443436:1017259450", "เคยไป Ashenvale ทางเหนือไหม? Horde เพิ่งตั้งฐานที่ Zoram Strand ที่นั่น เราต้องการกำลังใหม่ช่วยป้องกันแนวรบใหม่อยู่เสมอ\n\nหากคิดว่าไหว ไปพบ Kadrak ที่หอสังเกตการณ์ทางเหนือของ Barrens เขานำการรบใน Ashenvale และจะให้คำสั่งต่อไปได้" },
        completion = { "184:1812949208:541110060", "Ashenvale เป็นดินแดนที่แตกแยก แต่ความพยายามล่าสุดของเราประสบผลดีมาก เราไม่ได้มีแค่ฐานที่ Zoram Strand แต่ยังมีอีกแห่งทางเหนือจากที่นี่ชื่อ Splintertree" },
    },
    [1147] = { -- The Swarm Grows
        title = { "15:1062346132:1570499687", "ฝูงแมลงขยายตัว" },
        objective = { "121:1660076694:2088854810", "ฆ่า Silithid Searchers 5 ตัว, Silithid Hive Drones 5 ตัว และ Silithid Invaders 5 ตัว แล้วกลับไปหา Moktar Krin ใน Thousand Needles" },
        description = { "486:1758412750:190992229", "อืม ดูเหมือน Belgrom เห็นว่าสัตว์ประหลาดพวกนั้นเป็นภัย เขาอยากผลักมันกลับลงไปในส่วนลึกที่คลานขึ้นมา\n\nดูเหมือนฆ่าคนแคระที่ Explorers' League ส่งมายังไม่พอ ตอนนี้ข้าต้องส่งกองรบที่แทบหมดสภาพเข้าสู้อีกศึก เราทำเองไม่ได้ในสภาพนี้ จุดขุดอยู่ทางใต้ ไม่น่ามีคนแคระให้จัดการอีก เจ้าไหวไหมที่จะยกดาบหรือไม้เท้าแล้วช่วยเรา?" },
        progress = { "204:1326682795:1642493031", "มีคนเดินทางไปชมการแข่งขันที่ Flats มากมาย คงโน้มน้าวนักผจญภัยมาช่วยผลักแมลงพวกนั้นกลับไปได้มากพอ ข้ากับพวกยังไปไหนไม่ได้จนกว่าจะทำสำเร็จ" },
        completion = { "62:2102683812:893536850 N 297:1185726669:1368461172 N 1:46:46", "ฮ่า! น้ำเหนียวจากแมลงที่เปื้อนตัวทำให้เจ้าดูดีขึ้นนะ {name}! แต่ก็เหม็นขึ้นด้วย อย่าเข้าใกล้โคโดนัก เจ้าอาจทำให้มันแตกตื่นหรือเป็นสัด\n\nข้าคิดว่าสหายคงเห็นตรงกัน แค่กลิ่นก็พิสูจน์แล้วว่าเจ้าช่วยจัดการสัตว์แมลงพวกนั้น ขอบใจ {name}" },
        objectiveLabels = {
            monster = { ["Silithid Searcher slain"] = "ปราบ ซิลิธิดหน่วยค้นหา", ["Silithid Hive Drone slain"] = "ปราบ ซิลิธิดแรงงานประจำรัง", ["Silithid Invader slain"] = "ปราบ ซิลิธิดผู้รุกราน" },
        },
    },
    [1148] = { -- Parts of the Swarm
        title = { "18:1794384865:662226073", "ชิ้นส่วนจากฝูงแมลง" },
        objective = { "104:1275934820:34576504", "นำ Silithid Heart 1 ชิ้น, Silithid Talons 5 ชิ้น และ Intact Silithid Carapaces 3 ชิ้น ไปให้ Korran ที่ Crossroads" },
        description = { "507:653363521:955697067", "เจ้าตรวจเกราะอย่างถี่ถ้วน เมื่อพลิกดูในมือก็พบว่าแผ่นไคตินประสานกันจนแข็งแกร่งอย่างเหลือเชื่อ ไม่เหมือนอะไรที่เคยเห็น เมื่อตรวจซากส่วนอื่นต่อก็รู้ว่าสิ่งมีชีวิตเหล่านี้ทรงพลังและวิวัฒนาการสูงมาก\n\nมองเกราะอีกครั้งแล้วเจ้าคิดว่า Korran คงอยากศึกษาพวกมันเพิ่มเติม อาจช่วยให้เขารู้ว่ามันคืออะไรและมาจากไหน" },
        progress = { "53:994370359:467387255 N 208:1343434760:706806861", "อา นานแล้วที่เจ้าไม่ได้มาหาข้า {name} วันนี้มีอะไรให้ช่วย? ดูเหมือนเพิ่งผ่านการต่อสู้มา ดี... ดีต่อ Horde และตัวเจ้า ยิ่งผ่านศึกมาก ก็ยิ่งช่วยงานได้มากและแข็งแกร่งขึ้น" },
        completion = { "287:655414694:699416747 N 159:1682207134:1925085823", "อา เพิ่งพบ Moktar มาหรือ? เขาดูแลข้าเสมอ เสียใจที่เขาได้แต่เฝ้ากองรบเล็ก ๆ แทนลงสนาม แต่คงมีความสุขที่ได้ฆ่าคนของ Explorers' League\n\nเจ้าคิดถูกที่นำตัวอย่างมา {name} เมื่อรวมกับไข่ที่เราพบใน Field of Giants ก็พอให้ข้าเริ่มศึกษาว่าแมลงเหล่านี้เป็นอะไรและต้องการอะไร" },
        required = { [5855] = { "14:1153458047:1629195115", "หัวใจซิลิธิด" }, [5854] = { "14:1896322721:859422917", "กรงเล็บซิลิธิด" }, [5853] = { "24:383052675:1229993451", "กระดองซิลิธิดสภาพสมบูรณ์" } },
        steps = { { "14:1153458047:1629195115", "หัวใจซิลิธิด" }, { "14:1896322721:859422917", "กรงเล็บซิลิธิด" }, { "24:383052675:1229993451", "กระดองซิลิธิดสภาพสมบูรณ์" } },
    },
    [1149] = { -- Test of Faith
        title = { "13:501322532:617468292", "บททดสอบศรัทธา" },
        objective = { "69:1284216488:1350443580", "หากมีศรัทธา จงกระโดดจากแผ่นไม้ที่ยื่นเหนือ Thousand Needles" },
        description = { "492:2002167887:69277707", "เจ้าตามหาข้า หรือชะตาพามา? ไม่สำคัญ ตอนนี้เจ้าอยู่ที่นี่ และการเดินทางจะเริ่มต้นใหม่\n\nตัวตนประกอบด้วยหลายด้าน ทั้งจิตวิญญาณ ร่างกาย และจิตใจ บางอย่างวัดได้ด้วยธรรมเนียมของวัฒนธรรม บางอย่างเราทำได้เพียงหวังว่ามีในตน หากยินยอม ข้าจะทดสอบบางด้านของเจ้า\n\nหากผ่าน เจ้าจะแข็งแกร่งขึ้น หากล้มเหลว เจ้าจะรู้ถึงความเวิ้งว้างของ Nether\n\nขั้นแรกคือบททดสอบศรัทธา" },
        progress = { "149:780936552:1893358723", "ศรัทธาสำคัญกว่าที่บางคนเข้าใจ\n\nบางครั้งสิ่งที่เจ้าเชื่ออาจไม่สำคัญเท่าการมีสิ่งใดสักอย่างให้เชื่อมั่น" },
        completion = { "307:544265744:1459591431", "จนกว่าจะเผชิญความยากลำบากที่ไม่อาจคาด เราจึงเริ่มเห็นว่าจิตวิญญาณแข็งแกร่งเพียงใด เจ้ากระโดดด้วยศรัทธา แม้ไม่มีหลักประกันว่าจะรอด จิตใจเปิดกว้าง และวิญญาณพร้อมรับสิ่งที่จะมา\n\nหากยินดี บททดสอบถัดไปก็พร้อมแล้ว" },
    },
    [1150] = { -- Test of Endurance
        title = { "17:783482298:3974542", "บททดสอบความอดทน" },
        objective = { "61:1587095874:581005973", "นำ Grenka's Claw ไปให้ Dorn Plainstalker ใน Thousand Needles" },
        description = { "507:1927189809:325763017", "ข้ายินดีที่ความกล้าของเจ้ายังมั่นคงหลังสิ่งที่ผ่าน เมื่อศรัทธาไม่สั่นคลอน ก็ถึงเวลาทดสอบร่างกาย\n\nเริ่มด้วยความอดทน พาสหายไป Roguefeather Den ทางตะวันตกของ Freewind Post เข้าส่วนลึกของรังแล้วทำลายเสบียงอาหาร เพื่อยั่วความโกรธ หากรอดได้นานพอ Grenka Bloodscreech จะมาหาเอง ฆ่านางและนำกรงเล็บมาเพื่อจบบททดสอบ" },
        progress = { "314:612293496:598062297", "เจ้าต้องพร้อมทั้งวิญญาณ ร่างกาย และจิตใจเพื่อความท้าทายข้างหน้า\n\nเรามักรีบร้อนทั้งที่ยังไม่พร้อม ข้าถือเป็นหน้าที่ต่อคนรุ่นเยาว์ ไม่ว่าเผ่าใด ที่จะเตรียมพวกเขารับภัยหลังออกจากบ้านอันปลอดภัย" },
        completion = { "29:104487516:1082090193 R 244:1344022739:375613483", "Grenka ทรงพลัง แม้เทียบมาตรฐานของ{race} เจ้าควรภูมิใจในผลงานวันนี้\n\nบททดสอบศรัทธาแสดงความเข้มแข็งของวิญญาณ และการต่อสู้กับฮาร์ปี Roguefeather แสดงความอดทน แต่ถึงเวลาทดสอบใหม่แล้ว" },
        required = { [5843] = { "13:1007154128:768999736", "กรงเล็บของ Grenka" } },
        steps = { { "13:1007154128:768999736", "กรงเล็บของ Grenka" } },
    },
    [1151] = { -- Test of Strength
        title = { "16:617326517:1412119157", "บททดสอบพละกำลัง" },
        objective = { "69:1488395335:631479425", "นำ Fragments of Rok'Alim ไปให้ Dorn Plainstalker ใน Thousand Needles" },
        description = { "500:1953555124:113574070", "ยุคเทพเจ้าโบราณ เหล่าธาตุอาศัยทั่วโลกและบูชาเทพเหล่านั้น เทพใช้พลังผูกมัดพวกมันกับโลก เมื่อเทพเจ้าโบราณถูกขับออก เหล่าธาตุก็ค่อยเลือนหาย และตอนนี้กลับมาเฉพาะเมื่อจอมเวททรงพลังเรียก\n\nแต่มีข้อยกเว้น บางตนแข็งแกร่งพออยู่ได้ด้วยตนเอง Rok'Alim เป็นหนึ่งในนั้น\n\nเพื่อทดสอบกำลัง จงหา Rok'Alim ใน Thousand Needles แล้วฆ่าเขา" },
        progress = { "193:1126390317:139924549", "เผ่าเซนทอร์ใน Thousand Needles เรียก Rok'Alim ว่าผู้ทุบทำลาย เพราะหมัดดังกึกก้องยามทุบสิ่งมีชีวิตที่กล้า หรือโง่พอ มายืนขวางทาง" },
        completion = { "144:1817529308:119962047", "บททดสอบพละกำลังสำเร็จแล้ว เจ้าแสดงความแข็งแกร่งและกล้าหาญ พร้อมรับบททดสอบสุดท้ายก่อนพิธีเหล่านี้สิ้นสุด" },
        required = { [5844] = { "21:268227369:924777786", "เศษชิ้นส่วนของ Rok'Alim" } },
        steps = { { "21:268227369:924777786", "เศษชิ้นส่วนของ Rok'Alim" } },
    },
    [1184] = { -- Parts of the Swarm
        title = { "18:1794384865:662226073", "ชิ้นส่วนจากฝูงแมลง" },
        objective = { "40:458066511:1914004241", "กลับไปหา Belgrom Rockmaul ใน Orgrimmar" },
        description = { "224:2025947354:353476646", "กลับไปหา Belgrom ที่ Orgrimmar บอกว่า Moktar ทำตามคำสั่งได้ดีใน Thousand Needles บอกด้วยว่างานศึกษาข้าคืบหน้าและหวังจะรู้มากขึ้นเร็ว ๆ นี้ เขาคงพอใจมาก" },
        completion = { "34:296836830:1363149745 C 355:1425506856:225815702", "ข้าซาบซึ้งความพยายาม {class} Warchief คงยินดีที่รู้ว่าเจ้ายืนหยัดกับหน้าที่เพียงใด\n\nแน่นอน ข้าจะเอ่ยชื่อเจ้า เขาคุยกับข้าบ่อยและเห็นค่าความคิดเห็นของข้ามาก\n\nไปเถอะ ข้ามีงานอีกมาก หากพบ Korran และเขามีข่าวสัตว์พวกนี้ จงกลับมา ข้าเห็นว่าเป็นภัยที่ต้องจริงจัง" },
    },
    [1394] = { -- Final Passage
        title = { "13:1265150131:491192220", "ผ่านด่านสุดท้าย" },
        objective = { "47:490043409:407344145", "คุยกับ Dorn Plainstalker ใน Thousand Needles" },
        description = { "20:1921578502:569519135 N 294:1244780763:963143307 N 51:651835502:679486663", "เจ้าทำได้ดี {name} ผ่านทั้งบททดสอบข้าและก่อนหน้านี้ กลับไปหา Dorn ใน Thousand Needles เขาจะสัมผัสความเปลี่ยนแปลง และเห็นว่าจิตใจ ร่างกาย และวิญญาณแข็งแกร่งพอสมควรได้รับรางวัล\n\nจงรักษาสมดุลที่แสดงมาตลอด {name} หากทำได้ Dorn จะทดสอบเจ้าอีกในอนาคต" },
        completion = { "4:1110228981:147916455 N 321:1345890225:1324466962", "อา {name} นานแล้วที่เจ้าไม่ได้ก้าวเข้าบ้านข้า ราวกับผ่านหลายเดือนจากวันที่เจ้ากระโดดครั้งแรกและเริ่มเส้นทาง\n\nตอนนี้กลับมาแข็งแกร่งและรู้แจ้งกว่าเดิม ข้ายินดี และเจ้าควรได้รางวัลที่ติดตามบททดสอบจนจบ" },
    },
    [2862] = { -- War on the Woodpaw
        title = { "18:1009818128:485157421", "สงครามกับ Woodpaw" },
        objective = { "69:2015614537:1971498311", "นำ Woodpaw Gnoll Manes 10 ชิ้น ไปให้ Hadoken Swiftstrider ที่ Camp Mojache" },
        description = { "479:275631495:411522399", "พวกโนลล์... ไม่ใช่แค่กวนใจ แต่คุกคามการอยู่รอดของค่ายนี้เสมอ ไม่สำคัญว่าเป็นชาวพื้นเมือง Feralas หรือไม่ หากเราไม่เด็ดขาดต่อพวกมัน ก็จะถูกไล่ออกจากภูมิภาคทั้งหมด\n\nช่วงหลังพวกมันโจมตีค่ายรุนแรงขึ้น เราต้องการเจ้าช่วยลดจำนวน นำแผงคอมาสิบชิ้น แล้วข้าจะตอบแทนอย่างงาม\n\nไป!" },
        progress = { "132:8947604:305917666 N 59:1184913927:50925727", "เราผลักกลับไป แต่มันยังโจมตี! ต้องมีใครหรืออะไรทำให้คลุ้มคลั่ง... อ้อ กลับมาแล้วหรือ {name}? มีแผงคอครบสำหรับรับค่าหัวหรือยัง?" },
        completion = { "31:186103198:526376333 N 388:2047257020:812636376 N 59:1093618116:641501751", "นี่เป็นหลักฐานของการเริ่มต้นที่ดี {name} ฝีมือทหารของเจ้าควรได้รับคำชม\n\nข้าไม่ได้มอบงานให้เจ้าคนเดียว หลายคนก่อนเจ้าก็สู้พวกมัน ที่ผ่านมาเรากันพวกมันได้ แต่พักนี้พยายามรุกเหนือเข้าเขตอิทธิพลเรามากขึ้นมาก การโจมตีก็ดุร้ายขึ้น... ราวกับสิ้นหวัง\n\nแต่ข้ามีแผน {name} ที่อาจสะสางกับมันได้เด็ดขาด..." },
        required = { [9237] = { "18:1337360300:1665694060", "แผงคอของโนลล์ Woodpaw" } },
        steps = { { "18:1337360300:1665694060", "แผงคอของโนลล์ Woodpaw" } },
    },
    [2863] = { -- Alpha Strike
        title = { "12:1088770932:638551472", "โจมตีจ่าฝูง" },
        objective = { "73:1232238625:1268099228", "ฆ่า Woodpaw Alphas 5 ตัว แล้วกลับไปหา Hadoken Swiftstrider ภายในหนึ่งชั่วโมง" },
        description = { "460:2097602053:2025794661 N 34:69858515:501390791", "แผนคือกำจัดผู้นำโนลล์ที่เรียกตัวว่า Alphas ต่อเนื่องอย่างรวดเร็ว หากโจมตีฉับไวแม่นยำเช่นนี้ได้ พวกมันจะปั่นป่วน บางทีอาจยัดสารลงหัวหนามีหมัดเกาะได้ว่าเราสามารถและจะทำลายมัน!\n\nข้าอยากให้เจ้าเป็นผู้ส่งเจตนาข้า ฆ่า Alphas ห้าตัวภายในหนึ่งชั่วโมงจึงจะได้ผล {name} ไม่เช่นนั้นเราจะติดอยู่เช่นเดิม!" },
        progress = { "21:2000683357:294010387 N 90:1750984253:1852972247", "เวลาใกล้หมดแล้ว {name}! หากไม่ได้มารายงานว่าฆ่า Alphas แล้ว เจ้าก็กำลังเสียเวลา!" },
        completion = { "113:936606673:463156371 N 329:83532161:455745532", "เจ้าทำตามที่ข้าขอ ข้าขอคารวะ รับรางวัลเล็กน้อยชดเชยความพยายาม {name}\n\nเมื่อจำนวนลดและผู้นำถูกฆ่า โนลล์คงคิดก่อนบุกค่าย แต่เรื่องยังไม่จบ...\n\nต้องมีเหตุที่ทำให้โนลล์คลุ้มคลั่งเช่นนี้ ก่อนรวมตัวใหม่ ข้าต้องการรู้ว่าอะไรเป็นสาเหตุ" },
        objectiveLabels = {
            monster = { ["Woodpaw Alpha slain"] = "ปราบ จ่าฝูง Woodpaw" },
        },
    },
    [2902] = { -- Woodpaw Investigation
        title = { "21:913836031:1847522924", "สืบเรื่อง Woodpaw" },
        objective = { "86:910417907:752273180", "หาแผนการรบของโนลล์ในค่ายโนลล์ทางใต้ของ Camp Mojache" },
        description = { "470:1004317833:2008918734", "โนลล์ไม่ฉลาดนัก แต่กิจกรรมช่วงหลังคงมีแผนเขียนไว้ หากพบก็จะเข้าใจชัดขึ้นว่าอะไรทำให้มันกระสับกระส่าย\n\nข้าอยากให้กลับไปหา Woodpaw และมองหาสิ่งคล้ายแผนรบ ต้องมีสักอย่าง การโจมตีประสานกันเกินกว่าจะทำโดยไร้แผน หาให้พบแล้วนำกลับมา" },
        completion = { "476:1909439376:1874136567", "เมื่อตรวจแผนที่ พบว่าเป็นแผนการรบที่ Hadoken Swiftstrider ต้องการ มีลูกศรมากมายที่อาจแทนการเคลื่อนทหาร แต่ส่วนใหญ่มุ่งใต้ แทนที่จะเหนือซึ่งเป็นที่ตั้ง Camp Mojache\n\nอีกส่วนมีภาพที่เจ้าคิดว่าเป็นแมลงขนาดใหญ่ พร้อมขีดหลายขีดใต้ภาพ ดูจากสภาพโนลล์ อาจแทนจำนวนที่สูญเสียในการต่อสู้กับแมลงไม่ทราบชนิด..." },
    },
    [2903] = { -- The Battle Plans
        title = { "16:194667793:878165718", "แผนการรบ" },
        objective = { "71:7180378:1770972539", "นำ Woodpaw Battle Plans ไปให้ Hadoken Swiftstrider ที่ Camp Mojache" },
        description = { "217:828733076:459376560", "เมื่อพบแผนการรบของโนลล์แล้ว เหลือเพียงนำกลับไปให้ Hadoken Swiftstrider ที่ Camp Mojache บางทีเขาหรือคนที่นั่นอาจเข้าใจสิ่งที่โนลล์กำลังทำมากขึ้น" },
        progress = { "13:23130796:2039583150 N 78:225606727:1033072418", "ยินดีต้อนรับกลับ {name} พบหลักฐานที่จับต้องได้เรื่องแผนโนลล์หรือยัง?" },
        completion = { "477:2111782673:2057204752", "อา นี่ตรงกับที่ต้องการ แม้ข้าถอดลายขีดเขียนส่วนใหญ่บนแผนที่ไม่เก่ง แต่เห็นแผนรบมามากพอเข้าใจสิ่งที่เกิดกับโนลล์ ดูเหมือนกำลังรบสองด้าน ด้านหนึ่งกับเรา... แต่กำลังหลักดูจะสู้ศัตรูทางใต้\n\nมีเรื่องมากกว่าที่เห็น ถึงเวลาหาว่าศัตรูอีกฝ่ายของมันคือใคร" },
        required = { [9266] = { "20:1215252499:1056099246", "แผนการรบ Woodpaw" } },
        objectiveLabels = {
            item = { ["Woodpaw Battle Plans"] = "แผนการรบ Woodpaw" },
        },
    },
    [2973] = { -- A New Cloak's Sheen
        title = { "19:1237235574:1197015602", "ประกายเสื้อคลุมใหม่" },
        objective = { "79:435911222:1757236396", "นำ Iridescent Sprite Darter Wings 10 ชิ้น ไปให้ Krueg Skullsplitter ที่ Camp Mojache" },
        description = { "10:1401179418:1568553899 C 334:1928970125:126777008", "ยินดีที่พบ {class} ข้ากับสหายลงมา Feralas เพื่อทำภารกิจให้นายที่ Orgrimmar\n\nKorrin คู่ชีวิตข้าชอบเสื้อผ้าใหม่ ข้าจึงอยากทำเสื้อคลุมประดับปีกบางโปร่งของมังกรเฟย์ให้นาง เจ้าช่วยได้ไหม? Sprite darters ที่มีปีกงดงามแบบที่ต้องการอยู่ทางตะวันตกของ Camp Mojache" },
        progress = { "95:799929468:314678716 C 201:1399062074:618623585", "Sprite darters อันตรายเมื่อถูกยั่ว ระวังเวลาจัดการ {class} และระวังไนต์เอลฟ์แถวนั้นให้มากกว่า พวกน่ารำคาญมักซ่อนในป่าเช่นกัน\n\nเมื่อได้ปีกพอแล้ว บอกข้า จะตอบแทนอย่างดี!" },
        completion = { "11:2138623245:698779024 C 257:1796999720:1436373807 C 1:46:46", "เยี่ยมมาก {class}! ใช้ได้ดีเลย มีพอทำเสื้อคลุมให้ Korrin และอาจเหลืออีก! ขอบใจ\n\nหวังว่าการเดินทางไม่อันตรายเกินไป? Feralas ไม่ใช่ที่ปรานีใคร แต่เห็นชัดว่าเจ้าทำได้ดี\n\nขอบใจอีกครั้ง {class}" },
        required = { [9369] = { "29:968320323:1684805218", "ปีก Sprite Darter เหลือบสี" } },
        steps = { { "29:968320323:1684805218", "ปีก Sprite Darter เหลือบสี" } },
    },
    [2974] = { -- A Grim Discovery
        title = { "16:1970352508:1998647599", "การค้นพบอันน่าสะพรึง" },
        objective = { "64:403755242:403107712", "นำ Grimtotem Horns 20 ชิ้น ไปให้ Krueg Skullsplitter ที่ Camp Mojache" },
        description = { "243:1864724554:1593390611 C 203:139116646:1857010006", "อะไรนะ!? เจอทอเรนแถวนี้? ล้อเล่นหรือ! หน้าตาอย่างไร!?\n\nเผ่า Grimtotem! เจ้าพบพวกมันหรือ? Belgrom หนึ่งในนายเรา สนใจพวกนี้... ถึงกับตั้งค่าหัว\n\nต้องกลับไป {class} นำเขามาให้ข้า... มากเป็นกองถ้าทำได้ Grimtotem ไม่ใช่พวกที่จะประมาท กลับไปฆ่ามัน ให้เลือดมืดของมันย้อมแม่น้ำ Feralas เป็นสีแดง" },
        progress = { "25:1292914986:976325867 C 230:1858149618:642448474", "ฟังข้าจริงจัง {class} เผ่า Grimtotem ชั่วร้าย หากรู้ที่อยู่ ก็ต้องกลับไปโจมตีก่อน... ก่อนมันเข้าแผ่นดินเรา เผาหมู่บ้าน หรือปล้นทรัพยากร" },
        completion = { "22:181781612:413151431 C 216:1379528902:1960328401", "เขาพวกนี้ดี {class} ทำได้ดี ข้าจะเก็บไว้และบอก Belgrom ทันทีเมื่อกลับ Orgrimmar เจ้าช่วยข้าสองครั้งแล้ว ข้าจดจำไว้ บางทีภายหน้าข้าจะช่วยเจ้าได้! ขอให้โชคดี" },
        required = { [9460] = { "14:1015070159:688902670", "เขาของเผ่า Grimtotem" } },
        steps = { { "14:1015070159:688902670", "เขาของเผ่า Grimtotem" } },
    },
    [2975] = { -- The Ogres of Feralas
        title = { "20:2133219266:1826270240", "ออกร์แห่ง Feralas" },
        objective = { "108:504660950:34977546", "Rok Orhan ที่ Camp Mojache ต้องการให้เจ้าฆ่า Gordunni Ogres 10 ตัว, Gordunni Ogre-Magi 10 ตัว และ Gordunni Brutes 5 ตัว" },
        description = { "90:995846012:1485302306 N 189:1175638795:1936896493 N 55:840086963:215013310", "อิทธิพลของเผ่าออกร์ Gordunni ในพื้นที่นี้เห็นชัด มองรอบตัวสิ {name} แค่การมีอยู่ก็ทิ้งแผลให้ผืนดิน เราต้องผลักกลับก่อนขยายเข้า Feralas มากกว่านี้\n\nตามแม่น้ำขึ้นเหนือจะพบฐานพวกมัน ลดจำนวนเสีย {name} เราต้องแสดงว่าไม่ต้อนรับพวกมันที่นี่" },
        progress = { "14:1825069646:1151663625 N 43:1540127202:923663459", "รีบลงมือ {name} หรืองานที่ขอจะยากเกินไป?" },
        completion = { "11:1614239848:1406166483 N 51:962393063:565601207", "เยี่ยม {name} เมื่อเวลาผ่านไป ผืนดินจะฟื้น เราต้องไม่ยอมแพ้" },
        objectiveLabels = {
            monster = { ["Gordunni Ogre slain"] = "ปราบ อ็อกเกอร์ Gordunni", ["Gordunni Ogre Mage slain"] = "ปราบ จอมเวทอ็อกเกอร์ Gordunni", ["Gordunni Brute slain"] = "ปราบ อ็อกเกอร์จอมโหด Gordunni" },
        },
    },
    [2976] = { -- A Grim Discovery
        title = { "16:1970352508:1998647599", "การค้นพบอันน่าสะพรึง" },
        objective = { "68:1742416765:93612445", "นำ Crate of Grimtotem Horns ไปให้ Belgrom Rockmaul ใน Orgrimmar" },
        description = { "368:618254377:481306769 C 49:1274397371:766520074", "อะไรนะ?!\n\nอา ข้าพูดเรื่องค่าหัวไว้สินะ? คราวนี้คงสอนให้หัดหุบปากได้แล้ว!\n\nเจ้าลงแรง ก็ควรได้รางวัลสูงสุด เอาเขาไป ข้าจะใส่ลังให้ หา Belgrom Rockmaul ใน Valley of Honor เขาอยากรู้สิ่งที่เจ้าเห็นและจะตอบแทนความเหนื่อยยาก\n\nขอให้ปลอดภัย {class} และขอบใจอีกครั้งสำหรับทุกอย่าง" },
        progress = { "10:398614612:867430094 C 32:1574314099:1480336770", "รีบหน่อย {class} วันนี้ข้ามีงานต้องทำอีกมาก" },
        completion = { "137:1091027578:497004510 C 160:1919655273:278119653", "Grimtotem หรือ!? น่าสนใจ เจ้าบอกว่าพบขณะล่าสัตว์ใน Feralas? จริงหรือ?\n\nสหายร่วมงานข้าคงอยากได้ยินข่าว {class} เล่าต่อ ข้าจะนับเหรียญให้ไปด้วย\n\nก่อนเจ้าไป จงรู้ว่าข้าขอบคุณข้อมูลที่นำมาบอกวันนี้" },
        required = { [9462] = { "24:1236771878:1583958829", "ลังบรรจุเขาของเผ่า Grimtotem" } },
        steps = { { "24:1236771878:1583958829", "ลังบรรจุเขาของเผ่า Grimtotem" } },
    },
    [2978] = { -- The Gordunni Scroll
        title = { "19:2136138728:1706078132", "ม้วนคัมภีร์ Gordunni" },
        objective = { "55:172845860:2082399965", "นำ Gordunni Scroll ไปให้ Rok Orhan ที่ Camp Mojache" },
        description = { "190:245726891:833837300", "เมื่อหยิบม้วนคัมภีร์เปื้อนดินขึ้นมา เจ้าสังเกตว่ามีภาพคล้ายการประชุมหรือพิธีบางอย่าง Rok Orhan คงสนใจมันและความหมายต่อ Gordunni" },
        progress = { "13:597869732:1707424667", "นี่คืออะไร?" },
        completion = { "54:666578576:69789570", "ม้วนคัมภีร์นี้... เจ้าพบใน Gordunni Outpost หรือ?" },
        required = { [9370] = { "15:39809706:1972005650", "ม้วนจารึกของ Gordunni" } },
        steps = { { "15:39809706:1972005650", "ม้วนจารึกของ Gordunni" } },
    },
    [2979] = { -- Dark Ceremony
        title = { "13:772328805:40746054", "พิธีมืด" },
        objective = { "59:1941698293:74031171", "Rok Orhan ที่ Camp Mojache ต้องการให้เจ้าหา Gordunni Orb" },
        description = { "55:799360318:880526457 N 269:1906542576:910394322", "ดูเหมือนแผนพิธีมืดบางชนิด {name} เท่าที่ข้าอ่านออก พิธีนี้ดำเนินโดย Gordunni mage-lords\n\nหาพวกเขาสักคนแล้วเอาลูกแก้วมา\n\nลูกแก้วของจอมเวทมีพลังมาก จะช่วยให้เรารู้เรื่องพิธีและเวทของ Gordunni มากขึ้น" },
        progress = { "55:723045402:1296129769 N 1:46:46", "เราต้องรู้ให้มากขึ้นว่าทำไม Gordunni อยู่ที่นี่ {name}" },
        completion = { "120:1986638560:1082407418 N 1:46:46", "ลูกแก้วจะให้ข้อมูล Gordunni มากขึ้น... แล้วเราจะใช้วางแผนโค่นพวกมัน {name}" },
        required = { [9371] = { "12:813107540:714581690", "ลูกแก้ว Gordunni" } },
        steps = { { "12:813107540:714581690", "ลูกแก้ว Gordunni" } },
    },
    [2980] = { -- The Ogres of Feralas
        title = { "20:2133219266:1826270240", "ออกร์แห่ง Feralas" },
        objective = { "109:456384588:358164733", "Rok Orhan ที่ Camp Mojache ต้องการให้เจ้าฆ่า Gordunni Shaman 10 ตัว, Gordunni Warlocks 10 ตัว และ Gordunni Maulers 5 ตัว" },
        description = { "466:1563154178:1689194147 N 11:2085027157:132565949", "เมื่อพิสูจน์ว่าเป็นนักสู้แท้ ข้าเชื่อว่าเจ้ากล้าทำงานต่อ\n\nไป High Wilderness ทางตะวันตกเฉียงใต้ มีสิ่งก่อสร้างถูกทิ้งและทำลายบนผืนดินที่เคยเป็นของไนต์เอลฟ์ มองหาซากเหล่านี้ เมื่อพบต้นไม้เหี่ยวและพื้นดินถูกทำให้แปดเปื้อน ก็จะพบ Gordunni จงผลักมันกลับ\n\nออกร์เหล่านี้แข็งแกร่งกว่าพวกที่เคยสู้มาก {name} ระวังด้วย" },
        progress = { "26:83713308:1412595035 N 1:63:63", "พบซากหรือยัง {name}?" },
        completion = { "66:1716550658:1454608080 N 1:46:46", "เจ้าพิสูจน์แล้วว่าเป็นพันธมิตรที่ไว้ใจและพึ่งพาได้ {name}" },
        objectiveLabels = {
            monster = { ["Gordunni Shaman slain"] = "ปราบ ชาแมน Gordunni", ["Gordunni Warlock slain"] = "ปราบ วอร์ล็อก Gordunni", ["Gordunni Mauler slain"] = "ปราบ นักขย้ำ Gordunni" },
        },
    },
    [2987] = { -- Gordunni Cobalt
        title = { "15:29943303:230794849", "โคบอลต์ Gordunni" },
        objective = { "67:576977632:2135149427", "Orwin Gizzmick ที่ Camp Mojache ต้องการตัวอย่าง Gordunni Cobalt 12 ชิ้น" },
        description = { "485:783234870:1751093142", "ข้าเพิ่งมาถึง Feralas ได้ยินว่าออกร์ Gordunni ในแดนป่านี้มีแร่น่าสนใจ ใครจะรู้ว่าทำอะไรอยู่ แต่พวกมันหวงของจริง ๆ! ไม่วางทิ้งไว้เฉย ๆ แต่ฝังเพื่อกันคนอย่างข้าไม่ให้เอาไป\n\nหากเจ้ายินดี ข้าจะให้พลั่ว ไป Gordunni Outpost ทางเหนือแล้วขุด Gordunni Cobalt ให้ข้า มองหาแสงสีฟ้าแล้วเริ่มขุด!" },
        progress = { "92:1122672601:293964628", "ขึ้นไปแล้วเริ่มขุด!\n\nข้ามีที่ต้องไป มีคนต้องพบ เวลาเป็นเงินเป็นทอง!" },
        completion = { "59:972569241:1814177470 N 109:806187871:1434537809", "สมบูรณ์แบบ! ข้าจะพกไปเดินทางต่อ {name} มั่นใจว่าหาคนจ่ายงาม ๆ ให้โคบอลต์นี้ได้\n\nนี่ สำหรับความลำบากของเจ้า" },
        required = { [9463] = { "15:29943303:230794849", "โคบอลต์ของ Gordunni" }, [9466] = { "14:1464627004:414499644", "พลั่วของ Orwin" } },
        steps = { { "15:29943303:230794849", "โคบอลต์ของ Gordunni" }, { "14:1464627004:414499644", "พลั่วของ Orwin" } },
    },
    [3002] = { -- The Gordunni Orb
        title = { "16:85115265:140484425", "ลูกแก้ว Gordunni" },
        objective = { "72:560446297:1810674351", "นำ Gordunni Orb ไปให้ Uthel'nay ที่ Darkbriar Lodge ใน Orgrimmar" },
        description = { "47:1210225641:1603545080 N 152:1744142089:58039644", "แม้รู้จักศัตรูดี แต่ข้าเป็นนักรบ {name} บอกไม่ได้เลยว่าลูกแก้วนี้ทำอะไรได้\n\nข้ารู้จักจอมเวทใน Orgrimmar ที่อธิบายได้มากกว่า นำไปให้เขา" },
        progress = { "26:759148741:1254969395 R 1:63:63", "เจ้านำอะไรมาให้ข้า {race}?" },
        completion = { "13:1819362961:1158416710 N 55:2128800720:1075920820", "น่าทึ่ง {name}...\n\nลูกแก้วนี้ทรงพลังมาก แต่อันตรายมากเช่นกัน" },
        required = { [9371] = { "12:813107540:714581690", "ลูกแก้ว Gordunni" } },
        steps = { { "12:813107540:714581690", "ลูกแก้ว Gordunni" } },
    },
    [3062] = { -- Dark Heart
        title = { "10:1154173933:1753483219", "หัวใจมืด" },
        objective = { "66:1812269105:335344460", "Talo Thornhoof ที่ Camp Mojache ต้องการ Edana Hatetalon's Dark Heart" },
        description = { "500:580400657:1151883087", "Edana Hatetalon เป็นราชินีฮาร์ปี Northspring ในซากทางตะวันตก นางชั่วร้ายล้วน ๆ ได้ยินว่าหัวใจเป็นผลึก ไร้อารมณ์อื่นนอกจากเกลียดทุกคน เจ้าต้องเผชิญนางและนำหัวใจมืดกลับมา\n\nข้าได้ยินว่าฮาร์ปีพกเขาสัตว์ เป่าข้าง Hatetalon Stones ทางเหนือของซากแล้วจะเรียกราชินีมา\n\nลองนึกว่านางจะตกใจเพียงใด เมื่อผู้เรียกไม่ใช่พวกพ้อง แต่คือความตาย" },
        progress = { "60:1363008080:1895770789", "ต้องหยุดความเกลียดชังที่ Edana แพร่ทั่วผืนดิน" },
        completion = { "99:413002332:1787309633 N 12:513407318:1685728707", "ตอนนี้ข้ารู้ว่า Edana ตายจริง หัวใจนี้ข้าจะเก็บไว้ระลึกถึงสิ่งที่เจ้าทำให้ {name} ขอบใจ" },
        required = { [9528] = { "18:1756250048:1175517229", "หัวใจมืดของ Edana" } },
        steps = { { "18:1756250048:1175517229", "หัวใจมืดของ Edana" } },
    },
    [3063] = { -- Vengeance on the Northspring
        title = { "28:439337819:1584517344", "ล้างแค้น Northspring" },
        objective = { "138:449939460:1522774079", "Talo Thornhoof ต้องการให้เจ้าฆ่า Northspring Harpies 4 ตัว, Northspring Roguefeathers 4 ตัว, Northspring Windcallers 4 ตัว และ Northspring Slayers 4 ตัว" },
        description = { "467:314244314:609707866 N 17:96075971:1017975508", "สมัยก่อนข้าเป็นนักล่าช่ำชอง ไม่มีสัตว์ใดให้กลัว จนกระทั่ง...\n\nข้าอยู่ในป่า ลับดาบหลังศึกหนัก แล้วถูกซุ่มโจมตี ฮาร์ปีล้อมไว้ ข้าแทบลากตัวเองถึงที่ปลอดภัยไม่ไหว\n\nแม้ตอนนี้ยังได้ยินเสียงร้องก้อง...\n\nข้าไม่เหมือนเดิมอีก แต่ความแค้นยังเดือดภายใน หลังหลายปีนี้ต้องเอาคืน\n\nฮาร์ปี Northspring อยู่ทางตะวันตก {name} ล้างแค้นให้ข้า" },
        progress = { "130:355648311:1280921082", "ปีกฮาร์ปี Northspring ดำดุจราตรี อย่าละสายตา มิฉะนั้นมันจะหายเข้าความมืด" },
        completion = { "11:1191658970:1224418299 N 45:2078220289:1566347869", "ขอบใจ {name} เจ้าทำให้ใจทอเรนชราสงบแล้ว" },
        objectiveLabels = {
            monster = { ["Northspring Harpy slain"] = "ปราบ ฮาร์ปี Northspring", ["Northspring Roguefeather slain"] = "ปราบ ฮาร์ปีขนนอกคอก Northspring", ["Northspring Slayer slain"] = "ปราบ นักสังหาร Northspring", ["Northspring Windcaller slain"] = "ปราบ ผู้เรียกสายลม Northspring" },
        },
    },
    [3122] = { -- Return to Witch Doctor Uzer'i
        title = { "29:2070914295:1128105169", "กลับไปหา Witch Doctor Uzer'i" },
        objective = { "61:2127597697:1352887273", "ส่ง Neeru's Herb Pouch ให้ Witch Doctor Uzer'i ใน Feralas" },
        description = { "20:2117898539:278719012 N 99:1357612643:496087509", "นี่สมุนไพร {name} นำไปให้ Witch Doctor Uzer'i\n\nบอกเขาด้วยว่าข้าพอใจหัวหด" },
        progress = { "25:1992889652:1465058490", "คุยกับ Neeru แล้วหรือยัง?" },
        completion = { "55:1611029580:1980971704 N 149:1936197889:970888348", "นี่ตรงกับที่ข้าต้องใช้เตรียมภาชนะมุยเซก {name} อีกไม่นานจะรู้ว่าคาถาล่าสุดทรงพลังอย่างที่หวังหรือไม่\n\nรอสักครู่ ข้าต้องทำพิธีและใช้สมุนไพร" },
        required = { [9628] = { "18:2078174699:870984204", "ถุงสมุนไพรของ Neeru" } },
        steps = { { "18:2078174699:870984204", "ถุงสมุนไพรของ Neeru" } },
    },
    [3123] = { -- Testing the Vessel
        title = { "18:1352809074:1776011550", "ทดสอบภาชนะ" },
        objective = { "209:610170541:1389166148", "ไป Hinterlands แล้วหา Wildkin ฆ่า 10 ตัว จากนั้นใช้ Muisek Vessel ย่อและจับ Wildkin ที่ตายแล้ว\n\nนำ Wildkin Muiseks 10 ชิ้น และ Muisek Vessel ไปให้ Witch Doctor Uzer'i ใน Feralas" },
        description = { "94:515963830:1646497396 N 262:995633415:1576067330 N 96:1694727679:1226472463", "นี่คือการทดสอบทั้งพิธีของข้าและความสามารถเจ้า รับภาชนะนี้ {name} มันให้พลังย่อและจับสิ่งมีชีวิตไว้ภายใน\n\nไป Hinterlands หาสิ่งมีชีวิตชื่อ Wildkin ซึ่งเคยเป็นสัตว์เลี้ยงของเทพีไนต์เอลฟ์ Elune เป้าหมายคืออาวล์บีสต์ชนิด vicious, primitive หรือ savage {name} ฆ่า 10 ตัว แล้วใช้ภาชนะย่อและจับก่อนวิญญาณหลุดหนี" },
        progress = { "128:510469621:1689736269", "เจ้าจับ Wildkin ได้หรือยัง?\n\nหากสำเร็จ เราจะพร้อมย่อและจับมุยเซกของสิ่งมีชีวิตใน Feralas" },
        completion = { "113:1467115773:1107935906 N 68:2139601129:951785033", "เมื่อตายอย่างรุนแรง มุยเซกของสิ่งมีชีวิตอาจหลุดหนีและตามแก้แค้น การย่ออย่างที่เจ้าทำ {name} ป้องกันไม่ให้มันหนี ตอนนี้เราใช้ได้ตามใจ!" },
        required = { [9594] = { "14:466648725:2093188037", "มุยเซ็กของ Wildkin" }, [9618] = { "21:1798137641:294114061", "ภาชนะมุยเซ็กสำหรับ Wildkin" } },
        steps = { { "14:466648725:2093188037", "มุยเซ็กของ Wildkin" }, { "21:1798137641:294114061", "ภาชนะมุยเซ็กสำหรับ Wildkin" } },
    },
    [3124] = { -- Hippogryph Muisek
        title = { "17:2012855943:1248723998", "มุยเซกฮิปโปกริฟ" },
        objective = { "99:148589782:554830363", "ฆ่า Frayfeather Hippogryphs ชนิดใดก็ได้ 10 ตัว แล้วใช้ Muisek Vessel ย่อและจับไว้" },
        description = { "480:1064175190:1747004350", "เมื่อพิสูจน์ว่าไว้ใจได้และมีพรสวรรค์ใช้ภาชนะ ข้าอยากให้จับสิ่งมีชีวิตชนิดต่อไป\n\nฮิปโปกริฟเป็นสหายภักดีของไนต์เอลฟ์มาหลายปี วิญญาณของมันซื่อตรงมั่นคง\n\nงานเจ้าคือฆ่า Frayfeather Hippogryphs 10 ตัว แล้วรีบใช้ภาชนะย่อและจับ เพื่อเก็บมุยเซกไว้ พบฮิปโปกริฟได้ใน High Wilderness ทางใต้" },
        progress = { "41:987886662:1951096651", "จับฮิปโปกริฟได้หรือยัง?" },
        completion = { "196:2062656915:711858147 N 36:1975075113:617834467", "หลังฆ่าสัตว์ หากปล่อยมุยเซกหนี มันอาจอยู่ในร่างสิ่งมีชีวิตที่ยิ่งใหญ่กว่า เราจะไม่มีวันปลอดภัยจากการแก้แค้น\n\nข้ามอบงานอันตรายให้ {name} และเจ้าทำสำเร็จดีอีกครั้ง" },
        required = { [9595] = { "17:2012855943:1248723998", "มุยเซ็กของฮิปโปกริฟฟ์" } },
        objectiveLabels = {
            item = { ["Hippogryph Muisek"] = "มุยเซ็กของฮิปโปกริฟฟ์" },
        },
    },
    [3125] = { -- Faerie Dragon Muisek
        title = { "20:942417470:39189439", "มุยเซกมังกรเฟย์" },
        objective = { "111:1843996390:211268677", "ฆ่า Sprite Darters หรือ Sprite Dragons 8 ตัว ใช้ Muisek Vessel ย่อและจับ Faerie Dragons ที่ตายแล้ว" },
        description = { "N 326:33553729:203411320 N 107:360970809:484491183", "{name} ต่อไปต้องจับสิ่งมีชีวิตที่อาจดูเปราะบาง แต่สิ่งที่เราต้องการจริงคือวิญญาณทรงพลัง มังกรเฟย์เหล่านี้เคยเป็นพันธมิตรไนต์เอลฟ์ เราต้องจับเพื่อให้ Horde ได้ใช้ความแข็งแกร่งของวิญญาณเช่นกัน\n\nนี่มุยเซก {name} ฆ่า Sprite Darters หรือ Sprite Dragons 8 ตัว แล้วจับมุยเซก พบได้ทางตะวันตกจากที่นี่" },
        progress = { "58:44435054:980898645", "จับมุยเซกมังกรเฟย์ได้หรือยัง?" },
        completion = { "11:1191658970:1224418299 N 123:645572532:401327249", "ขอบใจ {name} ตอนนี้พลังวิญญาณมังกรเฟย์พร้อมให้เราใช้แล้ว\n\nหวังว่าเจ้าจะยินดีทำงานให้ข้าอีก" },
        required = { [9596] = { "20:942417470:39189439", "มุยเซ็กของมังกรภูต" } },
        objectiveLabels = {
            item = { ["Faerie Dragon Muisek"] = "มุยเซ็กของมังกรภูต" },
        },
    },
    [3126] = { -- Treant Muisek
        title = { "13:1305814206:1983936710", "มุยเซกเทรนต์" },
        objective = { "96:1689177158:1552486045", "ฆ่า Wandering Forest Walkers 3 ตัว ใช้ Muisek Vessel ย่อและจับ Treants ที่ตายแล้ว" },
        description = { "98:79425372:427206860 N 303:1396279524:889726932", "Wandering Forest Walkers ที่เดินเร่ในป่าคือเป้าหมายต่อไป {name} ไนต์เอลฟ์เกณฑ์เทรนต์เป็นพันธมิตรสู้ Horde แม้เคลื่อนไหวช้า แต่บทบาทผู้พิทักษ์ปฏิเสธไม่ได้\n\nอีกไม่นานเราจะใช้พลังนี้เพื่อประโยชน์ตน\n\nหา Wandering Forest Walkers 3 ตัว ฆ่าแล้วใช้ภาชนะย่อและจับไว้" },
        progress = { "54:1450197223:1413837378", "จับ Wandering Forest Walkers ได้หรือยัง?" },
        completion = { "11:1191658970:1224418299 N 43:1087710511:1844326107", "ขอบใจ {name} มุยเซกของเราเกือบครบแล้ว" },
        required = { [9593] = { "13:1305814206:1983936710", "มุยเซ็กของทรีแอนต์" } },
        objectiveLabels = {
            item = { ["Treant Muisek"] = "มุยเซ็กของทรีแอนต์" },
        },
    },
    [3127] = { -- Mountain Giant Muisek
        title = { "21:1916621525:996912628", "มุยเซกยักษ์ภูเขา" },
        objective = { "108:1474086862:746710255", "ฆ่า Land Walkers หรือ Cliff Giants 7 ตัว ใช้ Muisek Vessel ย่อและจับ Mountain Giants ที่ตายแล้ว" },
        description = { "448:429393059:1933451594", "งานสุดท้ายที่ต้องการคือเดินทางตะวันตกเฉียงเหนือไปหาศัตรูชนิดสุดท้าย\n\nยักษ์ภูเขาออกจากภูเขามาช่วยไนต์เอลฟ์เมื่อ Burning Legion ปรากฏในโลก เจ้าจะจำได้จากขนาดมหึมาและพื้นดินสั่นระหว่างเดินผ่านถิ่นหินของมัน\n\nข้าอยากใช้พลังขนาดนั้น ฆ่ายักษ์ภูเขา 7 ตัว แล้วใช้ภาชนะจับมุยเซกอันทรงพลัง" },
        progress = { "45:1544896333:1011991744", "จับยักษ์ภูเขาได้หรือยัง?" },
        completion = { "55:1839610246:709176527 N 134:590244174:1475345800", "ลองนึกถึงสิ่งที่เราทำได้ด้วยของที่มี {name} เมื่อรวมกับวัสดุที่เจ้าเก็บ ข้าจะผนึกมุยเซกของสัตว์เหล่านี้ไว้ตลอดกาลในสิ่งใดก็ได้ตามใจ" },
        required = { [9597] = { "21:1916621525:996912628", "มุยเซ็กของยักษ์ภูเขา" }, [9621] = { "28:365935948:1117377168", "ภาชนะมุยเซ็กสำหรับยักษ์ภูเขา" } },
        steps = { { "21:1916621525:996912628", "มุยเซ็กของยักษ์ภูเขา" }, { "28:365935948:1117377168", "ภาชนะมุยเซ็กสำหรับยักษ์ภูเขา" } },
    },
    [3128] = { -- Natural Materials
        title = { "17:376729696:258100261", "วัสดุธรรมชาติ" },
        objective = { "142:612171000:1279486051", "นำ Splintered Logs 2 ชิ้น, Encrusted Minerals 6 ชิ้น, Resilient Sinew 20 ชิ้น และ Metallic Fragments 40 ชิ้น ไปให้ Witch Doctor Uzer'i ที่ Camp Mojache" },
        description = { "459:420012172:1898779049", "ข้าต้องใช้วัสดุบางอย่างเพื่อให้งานเสร็จ... เจ้าทำพร้อมงานอื่นที่ข้ามอบให้ได้\n\nต้องการ Splintered Log จากเทรนต์ใน Feralas ส่วน Encrusted Minerals พบได้บนยักษ์ภูเขาและมังกรเฟย์ทางตะวันตก หา Resilient Sinew จากอาวล์บีสต์ใน Hinterlands หรือฮิปโปกริฟใน Feralas ด้วย สุดท้ายต้องใช้ Metallic Fragments จำนวนมากจากสิ่งมีชีวิตชนิดใดก็ได้ที่กล่าวมา" },
        progress = { "46:1388295659:950300873", "เก็บวัสดุที่ต้องการได้หรือยัง?" },
        completion = { "103:1408880305:2074810884", "เยี่ยม! วัสดุเหล่านี้รวมกับมุยเซกน่าจะให้ผลตามที่เราต้องการ" },
        required = { [9590] = { "14:1066623453:486335183", "ท่อนไม้ที่แตกเป็นเสี้ยน" }, [9589] = { "18:230177038:1111176288", "แร่ที่มีเปลือกจับ" }, [9591] = { "15:1946804119:1102755230", "เส้นเอ็นที่ยืดหยุ่นทนทาน" }, [9592] = { "18:1061232435:1064011332", "เศษโลหะ" } },
        steps = { { "14:1066623453:486335183", "ท่อนไม้ที่แตกเป็นเสี้ยน" }, { "18:230177038:1111176288", "แร่ที่มีเปลือกจับ" }, { "15:1946804119:1102755230", "เส้นเอ็นที่ยืดหยุ่นทนทาน" }, { "18:1061232435:1064011332", "เศษโลหะ" } },
    },
    [3129] = { -- Weapons of Spirit
        title = { "17:250371127:1171127979", "อาวุธแห่งวิญญาณ" },
        objective = { "81:878987190:2129287408", "Witch Doctor Uzer'i ขอให้เจ้ารอสักครู่ขณะเขาเตรียมอาวุธ" },
        description = { "209:1824752165:1849829743", "การอัดมุยเซกลงอาวุธเป็นกระบวนการยาก เมื่อมีวัสดุครบและมุยเซกของสัตว์ที่จับมาแล้ว ข้าก็เริ่มได้ โปรดรอ ข้าจะกลับมาในครู่เดียว" },
        completion = { "35:1871393033:1563000039 N 143:405988724:1019174440", "ตามสัญญา เจ้าเลือกได้ {name} มุยเซกของสัตว์ถูกผนึกเป็นพลังของอาวุธเหล่านี้ตลอดกาล\n\nตอนนี้เจ้าถือพลังนั้นเป็นของตนได้ จงใช้ให้ดี" },
    },
    [4120] = { -- The Strength of Corruption
        title = { "26:1987915326:824941657", "พลังแห่งความเสื่อมทราม" },
        objective = { "117:1037011261:2002570485", "Talo Thornhoof ที่ Camp Mojache ใน Feralas ต้องการให้เจ้าฆ่า Angerclaw Grizzlies 12 ตัว และ Felpaw Ravagers 12 ตัว ใน Felwood" },
        description = { "156:908372481:311870172 N 224:687458918:1412491237 N 103:1103652852:1577040677", "ในฐานะนักล่า ข้าพยายามเรียนรู้ความแข็งแกร่งของคู่ต่อสู้ แค่รู้จักศัตรูดีก็ทำให้การรบเป็นต่อได้ {name}\n\nใน Felwood ทางเหนือของ Ashenvale สัตว์ถูกสารที่เรียกว่าเฟลทำให้แปดเปื้อน หมีและหมาป่าคลุ้มคลั่ง แต่ข้าเชื่อว่าแข็งแกร่งขึ้นด้วย\n\nไปเถอะ {name} เดินทางไป Felwood เผชิญสัตว์เหล่านั้น เรียนรู้เองว่าพวกมันแข็งแกร่งอย่างที่ข้าเชื่อจริงหรือไม่" },
        progress = { "119:11980488:977491929", "ทุกสิ่งที่สัมผัสเฟลแผ่แสงสีเขียวประหลาด... ข้าสัมผัสว่าชั่วร้าย แต่ก็ทรงพลังมากเช่นกัน" },
        completion = { "93:690659163:100427701 N 92:852989302:1594730153", "จากคำบรรยาย ดูเหมือนสัตว์เหล่านั้นดุร้ายไร้สติ...\n\nระวังตัว {name} เจ้าควรเรียนรู้ความเสื่อมทรามให้มากขึ้น จงรู้จักศัตรูเสมอ" },
    },
    [4542] = { -- Message to Freewind Post
        title = { "24:479663038:1310795709", "สารถึง Freewind Post" },
        objective = { "67:1215865024:146813575", "นำ Urgent Message ไปให้ Cliffwatcher Longhorn ที่ Freewind Post" },
        description = { "327:97581107:359811281", "นักเดินทางผู้กล้า เซนทอร์โจมตีแถบนี้มากขึ้น Freewind Post ต้องรู้เรื่องการคุกคามครั้งใหม่ทันที! หา Cliffwatcher Longhorn ที่ Freewind Post ทางตะวันออกเฉียงใต้ แล้วมอบสารด่วน\n\nระวัง หลีกเลี่ยงเผ่า Grimtotem ใกล้ ๆ... พักนี้ปฏิบัติต่อเราแปลกไป" },
        progress = { "18:678499973:1231431024 C 29:333078717:2076814646", "ต้องการอะไร {class}? สารด่วน... ถึงข้าหรือ?" },
        completion = { "170:1377992661:10411879", "ข่าวร้ายอีกแล้ว! เซนทอร์พวกนี้เกินไปแล้ว! บุกขบวนเสบียงขบวนหนึ่งและฆ่าทุกคน เรื่องน่าแค้นนี้ต้องไม่ลอยนวล!" },
        required = { [11886] = { "14:607697453:2082623251", "ข้อความด่วน" } },
        steps = { { "14:607697453:2082623251", "ข้อความด่วน" } },
    },
    [4767] = { -- Wind Rider
        title = { "10:904772131:1764593154", "ผู้ขี่สายลม" },
        objective = { "55:1005582782:727436422", "นำ Highperch Wyvern Eggs 10 ฟอง ไปให้ Elu ที่ Freewind Post" },
        description = { "238:1291780221:1369153030 N 253:487775885:255812437", "ข้าได้รับหน้าที่หาวีเวิร์นเพิ่มให้อาจารย์ผู้ขี่สายลม คนของพวกเขามากขึ้น และข้าก็หวังจะเป็นผู้ขี่สายลมสักวัน แต่ฝึกวีเวิร์นไม่ทันความต้องการ บางทีเจ้าช่วยได้ {name}\n\nไป Highperch เก็บไข่วีเวิร์น จากที่นี่ไปตะวันตกเฉียงเหนือเลียบผนังหุบเขาจนพบทางลาดขึ้น Highperch ระวัง วีเวิร์นหวงไข่มากและไม่ปรานีผู้บุกรุก" },
        progress = { "N 101:1333155395:888310803", "{name} ได้ไข่วีเวิร์นที่ต้องการหรือยัง? ข้าอยากเริ่มฝึกเป็นผู้ขี่สายลมเต็มที!" },
        completion = { "154:916907241:724101736 C 1:46:46", "สมบูรณ์แบบ! ไข่เหล่านี้ทำให้ข้าหวังก้าวสู่การเป็นผู้ขี่สายลม นี่สิ่งแทนความขอบคุณ ขอให้การล่าที่ดีส่องทางเสมอ {class}" },
        required = { [12356] = { "20:1774031751:345172787", "ไข่ไวเวิร์นจาก Highperch" } },
        steps = { { "20:1774031751:345172787", "ไข่ไวเวิร์นจาก Highperch" } },
    },
    [4770] = { -- Homeward Bound
        title = { "14:590001865:186255640", "มุ่งหน้ากลับบ้าน" },
        objective = { "96:22878326:2096884652", "คุ้มกัน Pao'ka Swiftmountain ออกจาก Highperch แล้วคุยกับ Motega Firemane ที่ Whitereach Post" },
        description = { "16:1843054140:695158275 C 444:39042410:1900683846", "โปรดช่วย {class}! ข้าซ่อนใน Highperch มาพักใหญ่ ไม่เห็นมิตรหลายวันแล้ว ข้ามาศึกษาวีเวิร์นและคงเข้าใกล้เกินไป หลังถูกไล่จากรังก็หลงทาง\n\nข้าต้องกลับ Whitereach Post! Motega ไม่รู้ว่าหายไป หากรู้ว่าข้ามา Highperch คนเดียวคงโกรธมาก\n\nWhitereach Post อยู่ตะวันออกจากที่นี่... โปรดพาไปที!" },
        completion = { "377:376416254:1916239244", "อะไรนะ!? หากรู้ว่า Pao'ka Swiftmountain จะไปสอดส่อง Highperch ข้าคงล่ามเขากับโทเท็ม! พ่อเขาไม่ค่อยอยากให้ตามข้ามา Thousand Needles เรามาศึกษาสัตว์ต่าง ๆ ในดินแดนงดงามนี้\n\nข้าซาบซึ้งที่ช่วย Pao'ka หวังว่าสิ่งนี้จะชดเชยเคราะห์ร้ายที่เกิดจากการช่วยครั้งนี้ได้" },
        objectiveLabels = {
            event = { ["Escort Pao'ka from Highperch"] = "คุ้มกัน Pao'ka ออกจาก Highperch" },
        },
    },
    [4821] = { -- Alien Egg
        title = { "9:343713968:1727273288", "ไข่ประหลาด" },
        objective = { "61:1498928391:506187431", "นำ Alien Egg กลับไปให้ Hagar Lightninghoof ที่ Freewind Post" },
        description = { "456:1605633550:2100126606", "มีข่าวลือเรื่องไข่ประหลาดใน Thousand Needles ผู้พบเห็นยังเข้าใกล้ไม่พอตรวจละเอียด งูเฝ้าไข่ราวกับเป็นไข่ตนเอง\n\nข้าอยากให้ตามหาและนำมาเพื่อตรวจสอบ รายงานว่าอยู่ในรังงู แต่มีหลายรังตามตีนหน้าผาทางใต้และตะวันออกเฉียงเหนือของ Freewind Post" },
        progress = { "78:657758896:1555327593", "ข้าต้องรู้เรื่องไข่ลึกลับนี้ให้มากขึ้น ใครจะรู้ว่าอะไรจะฟักออกมา" },
        completion = { "134:292920435:758362285", "ใช่ ในที่สุด... ไข่ลึกลับถูกส่งมาแล้ว ให้ข้าดูใกล้ ๆ... อะไร..! นี่อะไร.. ?" },
        required = { [12467] = { "9:343713968:1727273288", "ไข่ประหลาด" } },
        steps = { { "9:343713968:1727273288", "ไข่ประหลาด" } },
    },
    [4841] = { -- Pacify the Centaur
        title = { "18:662725800:486948539", "ปราบเซนทอร์" },
        objective = { "125:1335084920:1003951467", "ฆ่า Galak Scouts 12 ตัว, Galak Wranglers 10 ตัว และ Galak Windchasers 6 ตัว แล้วกลับไปหา Cliffwatcher Longhorn ที่ Freewind Post" },
        description = { "N 167:1199823872:947363096", "{name} ข้าขอให้ตามล่าเซนทอร์พวกนี้ ให้มันรู้รสความแค้น โจมตีค่ายทางเหนือของ Freewind Post! ให้ความโกรธนำมือเจ้า!" },
        progress = { "9:2048101242:1609303135 N 107:838916092:176911666", "เอาน่า {name} ข้ารู้ว่ายังฆ่าไม่ครบส่วนของเจ้า จงล่าพวกมัน แล้วข้าจะให้รางวัลแทนคำขอบคุณ" },
        completion = { "35:577032365:1526831094 N 1:46:46", "นี่สำหรับเจ้า แทนคำขอบคุณ {name}" },
        objectiveLabels = {
            monster = { ["Galak Scout slain"] = "ปราบ หน่วยสอดแนม Galak", ["Galak Wrangler slain"] = "ปราบ ผู้ต้อนสัตว์ Galak", ["Galak Windchaser slain"] = "ปราบ ผู้ไล่ตามสายลม Galak" },
        },
    },
    [4865] = { -- Serpent Wild
        title = { "12:2051087112:2138181665", "อสรพิษคลุ้มคลั่ง" },
        objective = { "40:761547946:1274970188", "รายงานสิ่งที่พบแก่ Motega Firemane" },
        description = { "146:2117261277:1739039201 N 166:2000965694:1323518767", "หากไม่เห็นกับตา ข้าคงไม่เชื่อ ความแค้นมาเยือน Thousand Needles แล้ว!\n\n<Hagar เช็ดหน้าผาก>\n\n{name} ต้องรีบลงมือ! หา Motega Firemane ที่ Whitereach Post ตามถนนตะวันตกเฉียงเหนือจาก Freewind Post เขาจะรู้ว่าต้องทำอย่างไร!" },
        completion = { "106:252981546:1888151731", "ความแค้น! เช่นนั้นตำนาน Arikara ก็จริง ปัญหานี้ต้องแก้ทันที" },
    },
    [4881] = { -- Assassination Plot
        title = { "18:428572511:903229886", "แผนลอบสังหาร" },
        objective = { "65:1121894411:1465343151", "เตือน Kanati Greycloud ที่ Whitereach Post เรื่องแผนฆ่าเขา" },
        description = { "216:324814931:1669899427", "ทอเรน Kanati Greycloud ช่างกล้าตั้งค่ายล่าสัตว์ใน Thousand Needles เราต้องฆ่าเพื่อกำจัดค่ายและทุกคนที่อาจตามมา เราจะรวมตัวกันที่ฐานเล็กทางตะวันตกเฉียงใต้ของ Great Lift" },
        completion = { "59:676759748:1699726331", "พวกมันจะฆ่าข้าหรือ? ข้าจะแสดงให้เห็นว่าทอเรนต่อสู้อย่างไร!" },
    },
    [4904] = { -- Free at Last
        title = { "12:1752326530:1080305321", "เป็นอิสระเสียที" },
        objective = { "103:1303294009:1848865271", "คุ้มกัน Lakota Windsong ออกจาก Darkcloud Pinnacle แล้วคุยกับ Thalia Amberhide ที่ Freewind Post" },
        description = { "241:69731508:107038899 N 127:47130311:1326156552", "Arnak คิดว่าเราจะแต่งงานกัน... แต่เมื่อข้าปฏิเสธ เขากลับมาคืนนั้นและลักพาตัวข้า พี่น้องชายพยายามหยุด แต่ Arnak แข็งแกร่งเกินไป เขา... ฆ่าพี่น้องข้าแล้วพามาที่นี่ พี่น้องผู้น่าสงสาร...\n\n{name} ช่วยคุ้มกันข้าออกจาก Darkcloud Pinnacle ได้ไหม? ขอร้อง... ข้าต้องกลับไปหา Thalia! นางคงห่วงจนแทบบ้า" },
        progress = { "17:871705076:332939186", "Thalia Amberhide:" },
        completion = { "11:1191658970:1224418299 N 201:448122308:981111057", "ขอบใจ {name} ลึกในใจข้ารู้ว่านางจะกลับมา นางเล่าถึงความกล้าและการช่วยหลบหนี ไอเทมเหล่านี้เป็นของพี่น้องชายของนาง ข้ารู้ว่านางคงอยากมอบให้เจ้า" },
        objectiveLabels = {
            event = { ["Escort Lakota Windsong from the Darkcloud Pinnacle."] = "คุ้มกัน Lakota Windsong ออกจาก Darkcloud Pinnacle" },
        },
    },
    [4966] = { -- Protect Kanati Greycloud
        title = { "24:1205124440:324618228", "ปกป้อง Kanati Greycloud" },
        objective = { "49:109500391:1585534218", "ปกป้อง Kanati Greycloud จากการโจมตีของเซนทอร์" },
