    [5062] = { -- Sacred Fire
        title = { "11:1534019917:421451546", "ไฟศักดิ์สิทธิ์" },
        objective = { "102:1770969632:1233554587", "เก็บ Incendia Agave 10 มัด แล้วปรึกษา Magatha Grimtotem ที่ Elder Rise ใน Thunderbluff" },
        description = { "485:284385557:1524954233", "Arikara เป็นสัตว์ร้ายอันตราย ต้องจัดการโดยเร็ว หากจะล่า ต้องจุดไฟศักดิ์สิทธิ์แห่งชีวิตเพื่อเรียกนาง\n\nไปเก็บพืชหายาก Incendia Agave เมื่อพอแล้ว ปรึกษา Magatha Grimtotem ที่ Elder Rise ใน Thunder Bluff นางเป็นชามานทรงพลัง สามารถเสกพืชให้เป็นผงจุดไฟ\n\nไปตะวันออกเฉียงเหนือถึง Boiling Pool แล้วเก็บ Incendia Agave" },
        progress = { "218:1236345833:327204377", "อา Motega Firemain ส่งข่าว Arikara มา... นี่ข่าวร้ายจริง\n\n<Magatha มองรอบตัว>\n\nArikara เป็นสัตว์อันตรายที่เกิดมาเพื่อล้างแค้นผู้ทำสิ่งชั่วร้ายร้ายแรงเท่านั้น\n\n<Magatha ยิ้ม>" },
        completion = { "206:1054696171:899025542", "ดี เก็บ Incendia Agave มาพอแล้ว สมุนไพรหายากที่มีเฉพาะ Thousand Needles จะช่วยจุดไฟศักดิ์สิทธิ์แห่งชีวิตที่ดับอยู่\n\n<Magatha เริ่มเสก Incendia Agave>" },
        required = { [12732] = { "14:1675949826:2115975531", "ต้น Incendia Agave" } },
        steps = { { "14:1675949826:2115975531", "ต้น Incendia Agave" } },
    },
    [5064] = { -- Grimtotem Spying
        title = { "16:1968218390:1991618739", "สืบความลับ Grimtotem" },
        objective = { "65:2026227434:1023756538", "หาและนำ Secret Notes ทั้งสามฉบับจาก Darkcloud Pinnacle มา" },
        description = { "N 307:603154031:44745451 N 70:530207120:1737983276", "{name} เจ้ารับใช้ได้ดี ข้าจึงฝากภารกิจสำคัญ เผ่า Grimtotem ทำบางอย่างลับ ๆ ช่วงหลายสัปดาห์มานี้มีผู้ส่งสารสามคนไม่ทราบที่มามาเยี่ยม เราพบว่าหีบที่แยกอยู่ใน Darkcloud Pinnacle เก็บข้อความที่มีคนเฝ้าเหล่านี้\n\n{name} หากทำภารกิจอันตรายสำเร็จ ข้าจะให้รางวัลอย่างสมควร" },
        progress = { "49:1741617562:1335822375", "พบว่า Grimtotem ทำอะไรอยู่หรือยัง?" },
        completion = { "90:491075987:1072972628 N 58:643940315:224251453", "มหาวิญญาณโทเท็ม! ข่าวร้ายจริง ข้าต้องเริ่มวางแผนรับทุกสิ่งที่อาจมา\n\n{name} ตามสัญญา นี่รางวัลสำหรับความกล้าของเจ้า" },
        required = { [12765] = { "14:1330824245:375806822", "บันทึกลับฉบับที่ 1" }, [12766] = { "14:1330824246:375806823", "บันทึกลับฉบับที่ 2" }, [12768] = { "14:1330824247:375806824", "บันทึกลับฉบับที่ 3" } },
        steps = { { "14:1330824245:375806822", "บันทึกลับฉบับที่ 1" }, { "14:1330824246:375806823", "บันทึกลับฉบับที่ 2" }, { "14:1330824247:375806824", "บันทึกลับฉบับที่ 3" } },
    },
    [5088] = { -- Arikara
        title = { "7:602462390:603977183", "Arikara" },
        objective = { "116:1233675575:34538658", "ฆ่า Arikara นำซากของนางและ Incendia Powder ไปให้ Motega Firemane ที่ Whitereach Post เพื่อเป็นหลักฐาน", variants = { { "116:178893102:2140140073", "ฆ่า Arikara นำซากของนางและ Incendia Powder ไปให้ Motega Firemane ที่ Whitereach Post เพื่อเป็นหลักฐาน" } } },
        description = { "285:1242942555:791360237 N 151:1633226049:1416158572 C 1:33:33", "นำ Incendia Powder ที่ขัดเกลาและชำระแล้วไป Thousand Needles โยนลงไฟศักดิ์สิทธิ์แห่งชีวิตที่ Darkcloud Pinnacle บนเสาหินโดดเดี่ยวซึ่งใช้ฝังผู้ตาย\n\nมนตร์ที่ข้าใส่ในผงจะเรียก Arikara มาหา {name}\n\nข้ากลัวว่านางกำลังตาม Cairne Bloodhoof ตำนานทอเรนเปลี่ยนไปมาก และเกรงว่าทำให้นางโกรธ รีบก่อนทุกอย่างสูญสิ้น {class}!", variants = { { "285:510364835:1861114266 N 151:1633226049:1416158572 C 1:33:33", "นำ Incendia Powder ที่ขัดเกลาและชำระแล้วไป Thousand Needles โยนลงไฟศักดิ์สิทธิ์แห่งชีวิตที่ Darkcloud Pinnacle บนเสาหินโดดเดี่ยวซึ่งใช้ฝังผู้ตาย\n\nมนตร์ที่ข้าใส่ในผงจะเรียก Arikara มาหา {name}\n\nข้ากลัวว่านางกำลังตาม Cairne Bloodhoof ตำนานทอเรนเปลี่ยนไปมาก และเกรงว่าทำให้นางโกรธ รีบก่อนทุกอย่างสูญสิ้น {class}!" } } },
        progress = { "44:556066553:1939078363 N 1:63:63", "ฆ่าอสรพิษร้าย Arikara แล้วหรือยัง {name}?" },
        completion = { "277:1196808556:1221006489", "ไม่เข้าใจเลย ทำไม Arikara ตามล่า Cairne Bloodhoof? Magatha ไม่น่าผิด นางเป็นชามานที่ทรงพลังที่สุดของเรา\n\n<Motega ส่ายหน้า>\n\nอย่างไรก็ตาม วีรกรรมเพื่อ Horde จะไม่ถูกมองข้าม โปรดเลือกรางวัลชิ้นหนึ่งสำหรับความช่วยเหลือ" },
        required = { [12785] = { "15:366125567:1444319941", "ผง Incendia" }, [12925] = { "20:1501050451:481954719", "หนังอสรพิษ Arikara" } },
        steps = { { "15:366125567:1444319941", "ผง Incendia" }, { "20:1501050451:481954719", "หนังอสรพิษ Arikara" } },
        objectiveLabels = {
            event = { ["Light the Sacred Fire of Life"] = "จุดไฟศักดิ์สิทธิ์แห่งชีวิต" },
        },
    },
    [5147] = { -- WANTED: Arnak Grimtotem
        title = { "23:1824913450:1676019845", "ประกาศจับ: Arnak Grimtotem" },
        objective = { "92:1569828516:1187892242", "ฆ่า Arnak Grimtotem แล้วนำหลักฐานไปให้ Cliffwatcher Longhorn ที่ Freewind Post" },
        description = { "351:167116690:706881606", "ประกาศจับ: Arnak Grimtotem\n\nArnak ผู้ถูกขับไล่ต้องโทษคดีฆาตกรรมและลักพาตัวอันเลวร้าย มีรางวัลอย่างงามให้ผู้กล้านำอาชญากรนี้มารับโทษ\n\nพบ Arnak ล่าสุดบนหน้าผาใกล้ Darkcloud Pinnacle นำหลักฐานให้ Cliffwatcher Longhorn ที่ Freewind Post เพื่อรับรางวัล" },
        progress = { "52:1211239415:241680793", "มีข่าว Arnak Grimtotem ฆาตกรนั่นบ้างไหม?" },
        completion = { "116:1511825989:991134076 N 59:1856332339:2141228456", "ฮ่า! ข่าวดีเยี่ยม! ข้าเริ่มคิดว่าจะไม่มีวันนำมันมารับโทษได้!\n\nนี่ {name}... และขอบใจ ข่าววีรกรรมชั่วของ Arnak ทำให้เลือดข้าเดือด!" },
        required = { [12884] = { "12:1286441795:570984154", "กีบของ Arnak" } },
        steps = { { "12:1286441795:570984154", "กีบของ Arnak" } },
    },
    [5151] = { -- Hypercapacitor Gizmo
        title = { "20:792533765:327689695", "อุปกรณ์ Hypercapacitor" },
        objective = { "99:58646680:1847378885", "ฆ่าสัตว์ร้าย แล้วนำ Hypercapacitor Gizmo และ Panther Cage Key กลับไปให้ Wizlo Bearingshiner" },
        description = { "406:2145269987:1207811113", "ข้าเป็นผู้รอดคนเดียวจากขบวนที่ถูกเซนทอร์โจมตี! เสือดำหายากแต่ทรงพลังเฝ้าอุปกรณ์ดีที่สุดของข้าไว้รอบคอ ฮ่า! แม้เซนทอร์ยังตัวสั่นต่อหน้าสัตว์ดุร้ายนี้!\n\nนี่กุญแจกรง พวกมันเอาทุกอย่างที่นั่นไป แต่ปล่อยเสือไว้ ฆ่าสัตว์นี้แล้วนำ Hypercapacitor คืน ข้าจะให้รางวัล\n\nซากขบวนอยู่ทางเหนือจากที่นี่ไม่ไกล" },
        progress = { "30:904878116:656169138", "ได้ Hypercapacitor ของข้าหรือยัง?" },
        completion = { "92:832617388:837102894", "Hypercapacitor ของข้า! คงมีงานให้ทำไปพักใหญ่ จนกว่าจะคิดออกว่ามันทำอะไรได้..." },
        required = { [12942] = { "16:919350739:424219736", "กุญแจกรงเสือดำ" }, [12946] = { "20:792533765:327689695", "อุปกรณ์ Hypercapacitor" } },
        steps = { { "16:919350739:424219736", "กุญแจกรงเสือดำ" }, { "20:792533765:327689695", "อุปกรณ์ Hypercapacitor" } },
    },
    [5361] = { -- Family Tree
        title = { "11:1846494366:356472055", "สายใยครอบครัว" },
        objective = { "89:248333498:1990858984", "ส่ง Cliffwatcher Longhorn Report ให้ Nataka Longhorn ที่ Ghost Walker Post ใน Desolace" },
        description = { "452:1764052065:288716888", "Nataka พี่น้องชายข้าประจำ Ghost Walker Post ใน Desolace ข้าขอให้เจ้าส่งรายงานแทนได้ไหม? ผ่านหนึ่งปีจากจดหมายครั้งสุดท้าย มีพฤติกรรมเซนทอร์ผิดปกติตั้งแต่นั้น เขาควรได้รู้\n\nเดินทางไป Stonetalon Mountains ทางเหนือของ Crossroads แล้วไปตะวันตกเข้า Charred Vale จากนั้นลงใต้เข้า Desolace จะพบถนนใต้ไป Ghost Walker Post" },
        progress = { "20:983107378:1011470554 C 74:1430248275:600098867", "มีข่าวอะไร {class}! อา สารจากพี่น้องชายข้าหรือ? ส่งรายงานมาสิ!" },
        completion = { "93:1115957233:1339050869 C 99:2124842604:2139137759 C 54:1728913674:599290346", "ไม่รู้ว่าเจ้ารู้จักพี่น้องชายข้าอย่างไร แต่ดูเหมือนเขาเชื่อใจ {class}\n\nข้าชื่อ Nataka Longhorn ขอต้อนรับสู่ Ghost Walker Post เรามีงานให้ {class} มากมาย! คุยกับคนอื่นดู บางทีเขาต้องการเจ้า" },
        required = { [13507] = { "28:781759516:830114768", "รายงานของ Cliffwatcher Longhorn" } },
        objectiveLabels = {
            item = { ["Cliffwatcher Longhorn Report"] = "รายงานของ Cliffwatcher Longhorn" },
        },
    },
    [7730] = { -- Zukk'ash Infestation
        title = { "20:634978321:1469347413", "การระบาดของ Zukk'ash" },
        objective = { "77:1435733831:1213140256", "นำ Zukk'ash Carapaces 20 ชิ้น ไปให้ Hadoken Swiftstrider ที่ Camp Mojache ใน Feralas" },
        description = { "497:173557270:2063596473", "จากการสอดแนมเท่าที่จัดได้ เราเชื่อว่าศัตรูทางใต้ของโนลล์เป็นเผ่าพันธุ์คล้ายแมลง จะมีสติปัญญาหรือไม่ก็ไม่สำคัญ หากมันทำให้โนลล์คลุ้มคลั่งใส่เรา ก็เป็นภัยพอ ๆ กันหรือยิ่งกว่า\n\nบุกลึกเข้าที่อยู่ของแมลง Zukk'ash ซึ่งเรียก Writhing Deep ลดจำนวนและรายงานสิ่งที่พบ พร้อมนำเกราะกลับมาเป็นหลักฐานผลงาน" },
        progress = { "19:584766569:1012911725 N 38:1429854450:627246994", "การล่าเป็นอย่างไร {name}? มารายงานความสำเร็จหรือ?" },
        completion = { "11:534428891:784080240 C 375:1930931005:538629020", "ทำได้ดี {class} แม้การยับยั้ง Zukk'ash ที่มีอยู่มากต้องใช้การบุกเต็มกำลัง แต่เจ้าซื้อเวลาให้เราวางยุทธศาสตร์เหมาะสม\n\nข้าจะให้วิเคราะห์เกราะ เราต้องรู้ทุกอย่างก่อนจัดการปัญหาที่น่าเสียดายว่าใหญ่กว่าคาดมาก" },
        required = { [18961] = { "17:861315556:22271609", "กระดอง Zukk'ash" } },
        steps = { { "17:861315556:22271609", "กระดอง Zukk'ash" } },
    },
    [7731] = { -- Stinglasher
        title = { "11:1200943532:227258978", "Stinglasher" },
        objective = { "115:893353497:1542392623", "เอาชนะ Stinglasher ใน Writhing Deep แล้วนำต่อมของมันกลับไปให้ Hadoken Swiftstrider ที่ Camp Mojache ใน Feralas" },
        description = { "478:1610343497:1583439245", "ระหว่างสำรวจ Writhing Deep หน่วยสอดแนมรายงานแมลงยักษ์ ใหญ่กว่าตัวอื่นมาก เดินบนพื้นที่คดเคี้ยว ไม่เพียงขนาดใหญ่ แต่ยังดูเหมือนแผ่พลังบางอย่างที่ตัวอื่นไม่มี เราตั้งชื่อว่า Stinglasher\n\nอวัยวะภายในจะมีค่ามากในการหาวิธีรับมือภัยใหม่ ตัดต่อมหลั่งสารแล้วรีบนำกลับมา!" },
        progress = { "47:1651972077:644532531", "โค่น Stinglasher ได้หรือยัง?" },
        completion = { "12:893490672:478301359 C 304:900482612:878878644 N 12:586053710:1993834439", "น่าประทับใจ {class}... น่าประทับใจมาก! หาก Stinglasher เป็นตัวแข็งแกร่งที่สุดตัวหนึ่ง การศึกษามันจะมีค่ามาก หน้าที่ข้าคือต้านไว้นานพอใช้ประโยชน์จากความรู้นั้น\n\nโปรดรับเหรียญค่าหัวแทนคำขอบคุณของค่ายทั้งหมด {name} ทำได้ดี" },
        required = { [18962] = { "20:1304747780:960111024", "ต่อมของ Stinglasher" } },
        steps = { { "20:1304747780:960111024", "ต่อมของ Stinglasher" } },
    },
    [7732] = { -- Zukk'ash Report
        title = { "15:1267788191:1839605764", "รายงาน Zukk'ash" },
        objective = { "99:2094739464:1782393336", "ส่ง Camp Mojache Zukk'ash Report ให้ Zilzibin Drumlore ที่อาศัยใน The Drag ของ Orgrimmar" },
        description = { "482:2101649736:613174212", "เจ้าทำได้ดีทั้งสองงานในการจัดการภัย Zukk'ash ต่อ Camp Mojache แต่ภัยยังไม่จบ ข้าอยากขออีกงานในนาม Horde\n\nนี่เอกสารรายละเอียดที่เรารู้เกี่ยวกับแมลง Zukk'ash นำไปให้ Zilzibin Drumlore ที่ The Drag ใน Orgrimmar เขาเชี่ยวชาญสัตว์ประหลาดเช่นนี้ หวังว่าจะใช้ความรู้ที่เราหามาได้" },
        progress = { "106:1981219969:1223466637", "สวัสดีสหาย... ดูมีธุระด่วน มีอะไรให้ช่วยหรือ?" },
        completion = { "489:1980544746:392394405", "อา ข้ารออยู่ สัตว์ที่เจ้าเผชิญ... เป็นภัยโบราณที่ Horde ยังเลือกมองข้าม Hadoken ฉลาดที่นำเรื่องและเจ้ามาหาข้า\n\nZukk'ash ก็คือสัตว์ที่เรียกซิลิธิด บางคนคิดว่าเป็นแค่ตัวกวนใจไร้สมอง แต่ข้ารับรองว่ามันเป็นภัยร้ายยิ่งกว่าทุกสิ่งที่ Alliance จะรวบรวมมาได้\n\nหากยินดีและแข็งแกร่งพอ ข้าอยากให้ช่วยเปิดเผยภัยนี้" },
        required = { [19020] = { "28:1991731331:1161817870", "รายงานเรื่อง Zukk'ash จากค่าย Mojache" } },
        steps = { { "28:1991731331:1161817870", "รายงานเรื่อง Zukk'ash จากค่าย Mojache" } },
    },
    [98069] = { -- Stolen Freewind Supplies
        title = { "24:1506493224:2099636161", "เสบียง Freewind ที่ถูกขโมย" },
        objective = { "60:666234250:1889911644", "นำ Stolen Freewind Supplies 8 ชิ้น ไปให้ Jandia ที่ Freewind Post" },
        description = { "438:1831913160:492259876", "ฮาร์ปีน่ารังเกียจ! โจมตีขบวนล่าสุดที่ข้าจัดส่งเสบียงให้ Freewind Post ตอนนี้ยังพอมี แต่หากไม่ได้เพิ่มก็จะขาดแคลนเร็ว ๆ นี้\n\nไม่รู้ว่าพวกมันจะเอาเสบียงไปทำอะไร แต่ข้าจะขอบคุณหากช่วยเก็บคืน รังอยู่ทางตะวันตก พบได้ทั้งตีนหน้าผาและในถ้ำด้านบน" },
        progress = { "61:1147448136:795721348", "เก็บเสบียงที่ฮาร์ปีขโมยคืนได้หรือยัง?" },
        completion = { { "91:478090918:2029021121", "11:1191658970:1224418299 N 74:309440022:344946160", "11:1191658970:1224418299 C 74:309440022:344946160", "11:1191658970:1224418299 R 74:309440022:344946160" }, "ขอบใจสหาย เสบียงนี้ช่วยประคองจนของขบวนถัดไปมาถึงได้" },
        required = { [279383] = { "24:1506493224:2099636161", "เสบียงของ Freewind ที่ถูกขโมย" } },
        steps = { { "24:1506493224:2099636161", "เสบียงของ Freewind ที่ถูกขโมย" } },
    },
    [98070] = { -- Stop the Screeching
        title = { "19:1347592039:136582073", "หยุดเสียงกรีดร้อง" },
        objective = { "97:1884516948:1872861701", "ฆ่า Screeching Harpies 5 ตัว, Screeching Roguefeather Harpies 5 ตัว และ Screeching Windcaller Harpies 5 ตัว", amount = { "5:1000000866:1065647852 W1 21:1050617855:1625169972 W2 37:1212973480:172222271 W3 31:1608065822:66523185", "ฆ่า Screeching Harpies {world1} ตัว, Screeching Roguefeather Harpies {world2} ตัว และ Screeching Windcaller Harpies {world3} ตัว" } },
        description = { "458:859189096:422195237", "Screeching Canyon เป็นถิ่นฮาร์ปีท้องถิ่นที่ขึ้นชื่อว่าดุร้ายและชอบบุกปล้น พวกมันซุ่มโจมตีขบวนเสบียงหลายขบวนล่าสุดที่กล้าผ่าน\n\nข้ากลัวว่าหากไม่ทำอะไรเร็ว ๆ นี้ จะไม่มีขบวนใดกล้ามา Freewind Post\n\nไปฆ่าฮาร์ปีให้มากเท่าที่ทำได้ กลับมาหลังเสร็จแล้ว ข้าจะตอบแทนความพยายามอย่างดี" },
        completion = { "175:1601261163:1081294387", "ข่าวดีเยี่ยม! ข้าจะส่งข่าวให้ผู้ส่งเสบียงว่าจัดการฮาร์ปีแล้ว อย่างน้อยขบวนต่อไปก็มีภัยให้กังวลน้อยลงหนึ่งอย่าง" },
        progress = { "102:1932791740:1647041706", "จัดการพวกฮาร์ปีตัวร้ายแล้วหรือ? ข้าอยากให้เส้นทางกลับมาปลอดภัยสำหรับกองคาราวานเสียที" },
        objectiveLabels = {
            monster = { ["Screeching Harpy slain"] = "ปราบ ฮาร์ปี Screeching", ["Screeching Roguefeather slain"] = "ปราบ ฮาร์ปีขนนอกคอก Screeching", ["Screeching Windcaller slain"] = "ปราบ ฮาร์ปีผู้เรียกสายลม Screeching" },
        },
    },
    [1145] = { -- The Swarm Grows
        title = { "15:1062346132:1570499687", "ฝูงแมลงขยายตัว" },
        objective = { "62:224260617:1451386675", "ส่ง Korran's Sealed Note ให้ Belgrom Rockmaul ใน Orgrimmar" },
        description = { "460:284331527:1165453825", "นักเดินทางหลายคนที่ผ่าน Crossroads ช่วยข้าเก็บไข่จาก Field of Giants หลายคนเล่าว่าสัตว์พวกนี้อันตรายเพียงใด ฟังมาพอจะเห็นว่าเป็นภัยใหญ่กว่าที่นายของข้าคิดแต่แรก\n\nข้าต้องการผู้ส่งสารไปพบ Belgrom Rockmaul ที่ Orgrimmar เรื่องไม่เล็กน้อย ต้องเป็นคนที่จริงจังกับงาน\n\nมักพบ Belgrom นอกอาคารกิลด์นักรบ" },
        progress = { "12:1765777835:892816175 C 284:116961762:175976774", "ข้าอิจฉา {class} ดูเหมือนเจ้าออกนอกกำแพง Orgrimmar มาพักใหญ่\n\nข้าก็อยากเดินทางในนาม Warchief หาก Thrall ไม่ต้องใช้ฝีมือข้าในเมือง แต่เขานำเราดี และข้าเชื่อการตัดสินใจ จะอยู่ตราบใดที่เขาต้องการ" },
        completion = { "131:1334812299:85675172", "อา จดหมายจาก Korran เขารับใช้อย่างภักดีมานาน ข้ากำลังสงสัยว่างานที่ Crossroads เป็นอย่างไร" },
        required = { [5846] = { "20:818356009:543659183", "ข้อความปิดผนึกของ Korran" } },
        steps = { { "20:818356009:543659183", "ข้อความปิดผนึกของ Korran" } },
    },
    [1146] = { -- The Swarm Grows
        title = { "15:1062346132:1570499687", "ฝูงแมลงขยายตัว" },
        objective = { "65:939461783:1389972213", "ส่ง Belgrom's Sealed Note ให้ Moktar Krin ใน Thousand Needles" },
        description = { "505:71041659:1765199571", "งั้น Korran สรุปเรื่องแมลงคล้ายข้า มันดูเป็นภัยใหญ่กว่าที่คิด\n\nไม่กี่วันก่อน นักล่ากลับจาก Thousand Needles แทบเอาชีวิตไม่รอด เขาร่วมกองบุกที่ถูกส่งไปขับทีมขุดคนแคระออกจาก Shimmering Flats ระหว่างโจมตี แมลงพวกนี้พุ่งจากถ้ำในจุดขุด เกือบฆ่ากองบุกทั้งหมด\n\nMoktar Krin นำพวกเขา ตอนนี้หลบพักริม Shimmering Flats นำจดหมายนี้ไปให้เขา" },
        progress = { "51:168882369:2052372203 C 23:1284773915:897101210", "สงครามพาข้ากับพวกมา Shimmering Flats {class} อะไรพาเจ้ามา?" },
        completion = { "396:504296636:1562375010", "อย่าสนเสียงกึกก้องสะท้อนผนังเขา ก็อบลินกับโนมกำลังแข่งใน Flats ด้วยของวิปริตที่สร้างจากสิ่งเรียกว่าวิทยาศาสตร์ Thousand Needles มีภัยใหญ่กว่า หนึ่งในนั้นฆ่าคนในกองข้าไปกว่าครึ่ง\n\nแต่เราจะอยู่จนได้ข่าวจาก Belgrom ที่ Orgrimmar ระหว่างนั้นยึดตำแหน่งและเฝ้าระวังต่อ" },
        required = { [5850] = { "21:796795309:316991660", "ข้อความปิดผนึกของ Belgrom" } },
        steps = { { "21:796795309:316991660", "ข้อความปิดผนึกของ Belgrom" } },
    },
    [2981] = { -- A Threat in Feralas
        title = { "19:1966999742:1621249767", "ภัยใน Feralas" },
        objective = { "67:1179489489:1141702803", "Belgrom Rockmaul ต้องการให้เจ้าคุยกับ Rok Orhan ที่ Camp Mojache" },
        description = { { "49:13077804:1558961140 C 332:851614478:1746870229", "49:13077804:1558961140 C 332:613383189:1809468180" }, "Feralas เหมาะให้ {class} ฝีมือดีพิสูจน์ตน เผ่าออกร์ Gordunni มีกำลังทหารเหนือใครที่นั่นและเพิ่มจำนวน ต้องหยุดก่อนคุกคามการอยู่รอดของเราใน Feralas\n\nนักรบที่ข้ารู้จักชื่อ Rok Orhan อยู่ Camp Mojache ใน Feralas ไปหานาง นางจะอธิบายสถานการณ์เพิ่มเมื่อเจ้าถึง" },
        completion = { "44:1538798473:1829408777 R 156:178067951:824583136", "งั้น Belgrom ส่งมา เจ้าทันเวลาพอดี {race}\n\nข้าจะอธิบายก่อน แล้วเจ้าตัดสินใจว่าพร้อมรับความท้าทายหรือไม่... แต่ถ้า Belgrom ส่ง ข้าคงไม่ต้องสงสัยความกล้า" },
    },
    [8615] = { -- The Horde Needs Baked Salmon!
        title = { "29:985461850:677161336", "ฮอร์ดต้องการแซลมอนอบ!" },
        objective = { "79:644481857:1517800768", "นำ Baked Salmon 20 ชิ้นไปให้ Chief Sharpclaw ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "52:1661176015:877350743 C 399:149414693:1534580516 C 1:63:63", "งานระดมเสบียงสงครามอันคิราจเป็นภารกิจใหญ่หลวง {class} วัตถุดิบทั้งหมดที่รวบรวมที่นี่ ไม่ว่าจะเป็นโลหะทำอาวุธหรืออาหารสำหรับกิน ล้วนสำคัญเท่าเทียมกัน เพราะหากไม่ได้กินอาหารมาหลายวัน เจ้าก็ไม่มีแรงยกขวานในยามจำเป็น\n\nเราจึงรวบรวมอาหารเท่าที่หาได้ ข้ากำลังเก็บแซลมอนอบ อาหารที่เลือกมาทั้งเพราะให้สารอาหารและเก็บรักษาได้ดี เจ้าช่วยข้าในงานนี้ได้ไหม {class}?" },
        progress = { "95:799929468:314678716 C 201:1399062074:618623585", "Sprite darters อันตรายเมื่อถูกยั่ว ระวังเวลาจัดการ {class} และระวังไนต์เอลฟ์แถวนั้นให้มากกว่า พวกน่ารำคาญมักซ่อนในป่าเช่นกัน\n\nเมื่อได้ปีกพอแล้ว บอกข้า จะตอบแทนอย่างดี!" },
        completion = { "11:2138623245:698779024 C 257:1796999720:1436373807 C 1:46:46", "เยี่ยมมาก {class}! ใช้ได้ดีเลย มีพอทำเสื้อคลุมให้ Korrin และอาจเหลืออีก! ขอบใจ\n\nหวังว่าการเดินทางไม่อันตรายเกินไป? Feralas ไม่ใช่ที่ปรานีใคร แต่เห็นชัดว่าเจ้าทำได้ดี\n\nขอบใจอีกครั้ง {class}" },
        required = { [13935] = { "12:697604345:1823457003", "ปลาแซลมอนอบ" } },
        steps = { { "12:697604345:1823457003", "ปลาแซลมอนอบ" } },
    },
    [6] = { -- Bounty on Garrick Padfoot
        title = { "25:507316878:182239369", "ค่าหัว Garrick Padfoot" },
        objective = { "77:28366682:1724513225", "ฆ่า Garrick Padfoot แล้วนำหัวไปให้ Deputy Willem ที่ Northshire Abbey" },
        description = { "237:1744331554:596027249 N 87:2058517115:1657566769", "มีคนเห็น Garrick Padfoot โจรฆาตกรที่รังควานชาวนาและพ่อค้ามาหลายสัปดาห์ อยู่ที่กระท่อมใกล้ไร่องุ่น ทางตะวันออกของวิหาร ข้ามสะพานไป นำหัวคนร้ายมาแล้วรับค่าหัว!\n\nระวังด้วย {name} Garrick รวบรวมลูกสมุนไว้รอบตัว คงเข้าถึงไม่ง่าย" },
        progress = { "66:1254949199:1721605048", "พบกระท่อม Garrick หรือยัง? ในที่สุดเราพ้นคนร้ายนั่นแล้วหรือ?" },
        completion = { "83:1790904352:1820517837", "ฮ่า จับได้แล้ว! เจ้าช่วย Elwynn อย่างมาก และสมควรได้ค่าหัวงาม ๆ!" },
        required = { [182] = { "14:2056979008:43917433", "หัวของ Garrick" } },
        steps = { { "14:2056979008:43917433", "หัวของ Garrick" } },
    },
    [11] = { -- Riverpaw Gnoll Bounty
        title = { "21:2102092328:727293221", "ค่าหัวโนลล์ Riverpaw" },
        objective = { "64:1686402685:1330865218", "นำ Painted Gnoll Armbands 8 ชิ้น ไปให้ Deputy Rainer ที่ Barracks" },
        description = { "422:810192575:2056360590", "พบโนลล์ สัตว์ป่าเถื่อนที่ไม่มีธุระดีใดในดินแดนนี้ ตามชายแดน Elwynn Forest ฝูงใหญ่เกินกว่าพวกเรารับมือเองได้เข้ายึดป่าทางใต้ของหอยามตรงนั้น อีกกลุ่มอยู่ใกล้ Stone Cairn Lake ทางตะวันออก\n\nกองทัพ Stormwind จะยกย่องผู้ช่วยฆ่ามัน นำปลอกแขนทาสีของโนลล์มาเป็นหลักฐาน" },
        progress = { "6:1136836709:1914036474 N 34:528545119:767757815", "สวัสดี {name} ได้ฆ่าโนลล์มาบ้างไหม...?" },
        completion = { "45:81638424:1154623595 N 1:46:46", "เห็นว่าเจ้างานยุ่งทีเดียว! เราขอบใจ {name}" },
        required = { [782] = { "21:797963099:491445995", "ปลอกแขนโนลล์ทาสี" } },
        objectiveLabels = {
            item = { ["Painted Gnoll Armband"] = "ปลอกแขนโนลล์ทาสี" },
        },
    },
    [15] = { -- Investigate Echo Ridge
        title = { "22:2046771233:1916936625", "สำรวจ Echo Ridge" },
        objective = { "60:509756951:1375795573", "ฆ่า Kobold Workers 10 ตัว แล้วกลับไปรายงาน Marshal McBride" },
        description = { "N 275:1380900879:554299481", "{name} หน่วยสอดแนมบอกว่าการระบาดของโคโบลด์ใหญ่กว่าที่คิด กลุ่มคนงานตั้งค่ายใกล้ Echo Ridge Mine ทางเหนือ\n\nไปเหมืองแล้วกำจัด เรารู้ว่ามีอย่างน้อย 10 ตัว ฆ่ามัน ดูว่ามีอีกหรือไม่ แล้วกลับมารายงาน" },
        progress = { "52:1204760918:1304645615", "ไปเหมืองแล้วหรือ? พร้อมรายงานไหม?" },
        completion = { "208:984812194:685079024", "ข้าไม่ชอบข่าวโคโบลด์มากมายในเหมืองเรา ไม่มีเรื่องดีแน่ นี่ ค่าตอบแทน เมื่อพร้อมคุยกับข้าอีก อยากให้กลับไปเหมืองอีกครั้ง..." },
        objectiveLabels = {
            monster = { ["Kobold Worker slain"] = "ปราบ คนงานโคโบลด์" },
        },
    },
    [16] = { -- Give Gerard a Drink
        title = { "19:984380796:1999687169", "ให้น้ำ Gerard ดื่ม" },
        progress = { "127:1278365744:2006613260", "ทำไร่ทำให้กระหายน้ำ ข้ามองหาน้ำพุสดชื่นเสมอ\n\nหากมี ข้ายินดีแลกของ" },
