    },
    [18] = { -- Brotherhood of Thieves
        title = { "22:1797330424:606604332", "ภราดรโจร" },
        objective = { "75:43284659:200526635", "นำ Red Burlap Bandanas 12 ชิ้น ไปให้ Deputy Willem ด้านนอก Northshire Abbey" },
        description = { "291:893056009:306620513", "ช่วงนี้มีโจรกลุ่มใหม่แถว Northshire เรียกตัวเอง Defias Brotherhood พบข้ามแม่น้ำไปทางตะวันออก\n\nไม่รู้ว่าคิดอะไร แต่คงไม่ดีแน่! นำผ้าโพกที่มันสวมมา แล้วข้าจะให้อาวุธเป็นรางวัล" },
        progress = { "44:581655121:445839728", "เก็บผ้าโพกให้ข้าแล้วหรือยัง?" },
        completion = { "73:1710893006:1438581543", "เห็นว่ากลับมาพร้อมผ้าโพกแล้ว กองทัพ Stormwind ซาบซึ้งที่เจ้าช่วย" },
        required = { [752] = { "18:2110868660:592386022", "ผ้าโพกศีรษะกระสอบสีแดง" } },
        steps = { { "18:2110868660:592386022", "ผ้าโพกศีรษะกระสอบสีแดง" } },
    },
    [21] = { -- Skirmish at Echo Ridge
        title = { "22:1222894752:1834998243", "ปะทะที่ Echo Ridge" },
        objective = { "76:1988659760:1574773517", "ฆ่า Kobold Laborers 12 ตัว แล้วกลับไปหา Marshal McBride ที่ Northshire Abbey" },
        description = { "143:1247692640:2092020617 N 104:1758227741:858939901", "การสำรวจก่อนหน้าพิสูจน์ว่า Echo Ridge Mine ต้องกวาดล้าง กลับไปช่วยกำจัดโคโบลด์ในเหมือง\n\nอย่าเสียเวลา {name} ยิ่งปล่อยไว้นาน พวกมันยิ่งหยั่งรากใน Northshire ลึกขึ้น" },
        progress = { "25:1943386740:2033146805 N 70:1025492410:438625395", "ข้ารู้ว่าเป็นงานนองเลือด {name} แต่จำเป็นต่อความปลอดภัยของ Northshire พร้อมรายงานหรือยัง?" },
        completion = { "189:1307435522:1497518891", "เจ้าได้รับความนับถือจากข้าและคำขอบคุณของกองทัพ Stormwind อีกครั้ง ในเหมืองอาจยังมีโคโบลด์ แต่ข้าจะส่งคนอื่นไป เรามีงานต่อให้เจ้า" },
        objectiveLabels = {
            monster = { ["Kobold Laborer slain"] = "ปราบ โคโบลด์แรงงานเหมือง" },
        },
    },
    [35] = { -- Further Concerns
        title = { "16:458356527:5743031", "ข้อกังวลเพิ่มเติม" },
        objective = { "52:1167997721:1412308431", "Marshal Dughan ต้องการให้เจ้าคุยกับ Guard Thomas" },
        description = { "250:544801345:111399448", "หากกังวลว่าข่าวลือเมอร์ล็อกเป็นจริง จงไปสะพานทางตะวันออกของ Elwynn แล้วคุยกับ Guard Thomas เขาประจำสะพานมาสัปดาห์หนึ่งและจะรู้สภาพพื้นที่\n\nนำรายงานเขามาให้ข้า" },
        completion = { "158:1284416380:836481718", "ใช่ เมอร์ล็อกตั้งถิ่นฐานในลำธาร Elwynn ตะวันออกและรอบ ๆ เราไม่รู้เหตุที่มา แต่พวกมันก้าวร้าวและมีสติปัญญาอย่างน้อยระดับหนึ่ง" },
    },
    [37] = { -- Find the Lost Guards
        title = { "20:334168456:2141718125", "ตามหายามที่หายไป" },
        objective = { "105:1728514320:837121497", "Guard Thomas ต้องการให้เจ้าเดินทางขึ้นเหนือตามแม่น้ำ เพื่อตามหายามที่หายไปสองคน Rolf และ Malakai" },
        description = { "249:1616199895:949902059", "หลายวันก่อน เราส่งยาม Rolf กับ Malakai สำรวจตามแม่น้ำ แต่ยังไม่กลับ หากจะทำรายงานให้ครบ ข้าต้องรู้ว่าเกิดอะไรกับพวกเขา\n\nขึ้นเหนือตามแม่น้ำแล้วหายาม... หรือซากของพวกเขา" },
        completion = { "133:2040809625:1678540842", "แม้หลายสิ่งถูกเอาออกจากศพ แต่ใกล้กันมีเหรียญห้อยคอสลักว่า “Footman Malakai Stone”" },
    },
    [39] = { -- Deliver Thomas' Report
        title = { "22:1041498720:431594075", "ส่งรายงาน Thomas" },
        objective = { "38:909308080:243557278", "รายงานต่อ Marshal Dughan ใน Goldshire" },
        description = { "235:1872886494:1244647843", "บอก Marshal Dughan เรื่องการตายของ Malakai กับ Rolf และรายงานว่าทหารที่เรามีตอนนี้คุมเมอร์ล็อกใน Elwynn ตะวันออกไม่ไหว\n\nรู้ว่าเหลือทหารส่งมาช่วยไม่มาก แต่หวังว่า Dughan จะหาคนได้" },
        completion = { "228:1001615743:248532688", "อืม ข่าวน่าห่วง แนวป้องกันเราก็เบาบางอยู่แล้ว การเสีย Rolf กับ Malakai ให้เมอร์ล็อกยิ่งทำให้แย่\n\nหากไม่ดีขึ้น อาจมีการต่อสู้ใน Goldshire ก่อนสิ้นสัปดาห์!" },
    },
    [40] = { -- A Fishy Peril
        title = { "13:1122980415:873170525", "ภัยคาวปลา" },
        objective = { "69:311741085:354689950", "Remy \"Two Times\" ต้องการให้เจ้าคุยกับ Marshal Dughan ใน Goldshire" },
        description = { "N 280:1035614592:488558129 N 67:1534491440:632850910", "{name} มีภัยใหม่ใน Elwynn Forest! เมอร์ล็อกว่ายขึ้นลำธารทางตะวันออก ไล่ปลาและโจมตีผู้คนดี ๆ!\n\nข้าเตือน Marshal Dughan แล้ว แต่เขาห่วงโนลล์กับโจรมากกว่า ยังไม่เชื่อว่าเมอร์ล็อกเป็นภัย\n\nขอร้อง {name} คุยกับ Dughan ชวนให้ส่งทหารไปตะวันออกเพิ่ม!" },
        completion = { "247:624553636:77306304", "ใช่ ข้าคุยกับ Remy แล้ว เคารพเขาในฐานะพ่อค้า แต่รายงานเมอร์ล็อกตะวันออกยังคลุมเครือ\n\nรับรู้ข้อกังวลแล้ว แต่หากไม่มีรายงานภัยเมอร์ล็อกจากทหาร เราคงส่งกำลังไปตะวันออกเพิ่มไม่ไหว" },
    },
    [45] = { -- Discover Rolf's Fate
        title = { "20:785323096:1996846125", "สืบชะตากรรม Rolf" },
        objective = { "58:912189397:821220234", "ค้นหมู่บ้านเมอร์ล็อกเพื่อหา Rolf หรือหลักฐานว่าเขาตายแล้ว" },
        description = { "215:1239699609:1026449785", "เมื่อสำรวจบริเวณต่อ เจ้าพบรอยเท้ามีพังผืดมุ่งตะวันออกตามฝั่ง Stone Cairn Lake ไกลออกไปทางตะวันออกพอมองเห็นหมู่บ้านเมอร์ล็อกเลือน ๆ\n\nบางที Rolf อาจพบจุดจบที่นั่น..." },
        completion = { "106:422237973:1144957136", "รอบคอศพมีเหรียญโลหะจารึกว่า “Footman Rolf Hartford”" },
    },
    [46] = { -- Bounty on Murlocs
        title = { "17:1171852902:2062173413", "ค่าหัวเมอร์ล็อก" },
        objective = { "67:590584012:1463326074", "นำ Torn Murloc Fins 8 ชิ้น ไปให้ Guard Thomas ที่สะพาน Elwynn ตะวันออก" },
        description = { "294:1288183268:301111979", "กองทัพ Stormwind ตั้งค่าหัว Murloc Lurkers กับ Foragers ใน Elwynn ฆ่าแล้วนำครีบฉีกมา แล้วกองทัพ Stormwind จะตอบแทนอย่างดี\n\nเมอร์ล็อกสร้างหมู่บ้านที่ Stone Cairn Lake ทางเหนือ และอีกแห่งทางใต้ตรงลำธารแยก" },
        progress = { "22:1587245246:68769387 N 1:63:63", "การล่าเป็นอย่างไร {name}?" },
        completion = { "195:1202434309:1185546644", "มีครีบมาแล้วหรือ? ดี! Marshal Dughan กังวลเรื่องเมอร์ล็อกใน Elwynn ตะวันออก ข้าอยากบอกว่าสถานการณ์เริ่มควบคุมได้\n\nสิ่งที่เจ้าทำช่วยให้เป็นเช่นนั้น" },
        required = { [780] = { "15:888991797:361611259", "ครีบเมอร์ล็อกที่ฉีกขาด" } },
        steps = { { "15:888991797:361611259", "ครีบเมอร์ล็อกที่ฉีกขาด" } },
    },
    [47] = { -- Gold Dust Exchange
        title = { "18:981555279:1301179024", "แลกผงทอง" },
        objective = { "105:1075983625:232591811", "นำ Gold Dust 10 ชิ้น ไปให้ Remy \"Two Times\" ใน Goldshire เก็บ Gold Dust ได้จาก Kobolds ใน Elwynn Forest" },
        description = { "283:878281280:867671476", "โคโบลด์แถวนี้บางตัวพก Gold Dust ข้าต้องใช้จริง ๆ เอามาให้แล้วจะจ่ายราคาดีที่สุดในเมือง... ดีที่สุดในเมือง!\n\nหาโคโบลด์ได้ที่ Fargodeep Mine ทางใต้ และรอบ Jasperlode Mine ทางตะวันออกเฉียงเหนือ" },
        progress = { "46:414964465:1524490888", "ชู่ว์! มี Gold Dust ให้ข้าไหม... ให้ข้า?" },
        completion = { "21:2055694487:621867366 N 101:643443311:304415453", "ขอบใจสำหรับผงทอง {name} นี่เงิน และ... ของแทนใจจากสหายร่วมงานข้า เจ้าอาจใช้ประโยชน์ได้... ประโยชน์ได้" },
        required = { [773] = { "9:1389485762:1162722604", "ผงทอง" } },
        steps = { { "9:1389485762:1162722604", "ผงทอง" } },
    },
    [52] = { -- Protect the Frontier
        title = { "20:1928434361:1499728427", "ปกป้องชายแดน" },
        objective = { "100:2010098589:91440309", "ฆ่า Prowlers 8 ตัว และ Young Forest Bears 5 ตัว แล้วกลับไปหา Guard Thomas ที่สะพาน Elwynn ตะวันออก" },
        description = { "6:1136836709:1914036474 N 204:520586526:1178610190", "สวัสดี {name} ยิ่งห่าง Goldshire สัตว์ป่ายิ่งก้าวร้าว Eastvale Logging Camp ถูกหมาป่ากับหมีโจมตีแทบไม่หยุด!\n\nเราต้องการเจ้าช่วยที่นี่" },
        progress = { "39:1215364072:157227129", "ฆ่าหมาป่ากับหมีแล้วหรือยัง?" },
        completion = { "27:756936165:2099380642 N 102:816032590:1246844230", "ขอบใจมากที่ช่วย {name} ต้องมีบางอย่างในป่าทำให้สัตว์กล้าเช่นนี้\n\nไม่ว่าอะไร หวังว่ามันจะอยู่ในนั้นต่อ" },
        objectiveLabels = {
            monster = { ["Prowler slain"] = "ปราบ นักย่องล่า", ["Young Forest Bear slain"] = "ปราบ หมีป่าวัยอ่อน" },
        },
    },
    [54] = { -- Report to Goldshire
        title = { "19:1990665132:434810625", "รายงานต่อ Goldshire" },
        objective = { "64:1980091567:757315966", "นำ Marshal McBride's Documents ไปให้ Marshal Dughan ใน Goldshire" },
        description = { "N 12:1527649276:452560194 C 296:2134209591:1340041108", "{name} เจ้าเป็น {class} ที่พิสูจน์ว่าใส่ใจความปลอดภัยของ Northshire ตอนนี้ได้รับหน้าที่ปกป้อง Elwynn Forest รอบนอก\n\nหากรับหน้าที่ ข้าเตรียมเอกสารให้ส่ง Marshal Dughan ใน Goldshire แล้ว Goldshire อยู่ตามถนนใต้ พ้นประตูเขตไป" },
        progress = { "158:464907884:1585828915", "มีข่าวจาก McBride หรือ? Northshire เหมือนสวนเมื่อเทียบ Elwynn Forest แต่ข้าสงสัยว่า Marshal McBride มีอะไรจะรายงาน\n\nส่งเอกสารเขามาสิ..." },
        completion = { "297:1696157893:509147923", "อืม ในนี่บอกว่าเจ้าได้รับสถานะผู้ช่วยรักษาการของ Stormwind Marshals ยินดีด้วย\n\nขอให้โชคดี รักษาความปลอดภัย Elwynn ไม่ใช่งานง่าย... กองทัพส่วนใหญ่ยุ่งกับเรื่องอะไรก็ไม่รู้ ให้ขุนนางคนไหนก็ไม่รู้!\n\nยุคมืดเช่นนี้ติดตามการเมืองยาก..." },
        required = { [745] = { "27:1733058542:338195159", "เอกสารของ Marshal McBride" } },
        steps = { { "27:1733058542:338195159", "เอกสารของ Marshal McBride" } },
    },
    [59] = { -- Cloth and Leather Armor
        title = { "23:1724914622:2125553013", "เกราะผ้าและหนัง" },
        objective = { "48:686378402:1593457646", "มอบ Stormwind Armor Marker ให้ Sara Timberlain" },
        description = { "247:1641612406:84347550 N 102:447879802:977055772", "ด้วยไหวพริบและความกล้า ข้ามีตราแลกเกราะหนึ่งชิ้นให้ นำไปให้ Sara Timberlain ที่ Eastvale Logging Camp นางจะทำเกราะให้ เมื่อได้แล้ว {name} จงใช้ปกป้อง Elwynn\n\nEastvale Logging Camp อยู่เลยฐาน Guard Thomas ไปทางตะวันออก" },
        progress = { "169:1614720183:953288349", "กองทัพ Stormwind ว่าจ้างข้าให้จัดหาเกราะผ้าและหนังแก่คนของพวกเขา\n\nหากมีตรามา ข้าก็ยินดีทำของให้" },
        completion = { "96:529920950:35102652 C 36:1296591452:949866513", "อา ขอบใจสำหรับตรา โปรดเลือกเกราะได้ตามใจ\n\nขอให้โชคดี {class} ผู้กล้า ขอให้เกราะนี้รับใช้เจ้าได้ดี" },
        required = { [748] = { "22:345724433:1807588935", "เครื่องหมายเกราะ Stormwind" } },
        steps = { { "22:345724433:1807588935", "เครื่องหมายเกราะ Stormwind" } },
    },
    [60] = { -- Kobold Candles
        title = { "14:1045753262:28595228", "เทียนโคโบลด์" },
        objective = { "53:1472340674:386504247", "นำ Large Candles 8 เล่ม ไปให้ William Pestle ใน Goldshire" },
        description = { { "381:1281114445:552726630", "380:1744735599:228255625" }, "สวัสดี! มีเวลาสักครู่ไหม?\n\nข้ากับพี่น้องชายเปิดร้านยาใน Stormwind ข้ามาเก็บเทียนใหญ่เพื่อเอาขี้ผึ้ง ช่วยได้ไหม?\n\nหาเทียนใหญ่จากโคโบลด์ ได้ยินว่ามันยึดเหมือง Elwynn ทั้ง Fargodeep ทางใต้และ Jasperlode ทางตะวันออก ลองหาเทียนที่ใดที่หนึ่งดู" },
        progress = { "33:125081406:1527375627", "เก็บเทียนแล้วหรือยัง?" },
        completion = { "65:688147378:1233941943 N 27:560212546:636679040", "มัวล่าโคโบลด์อยู่หรือ? ขอบใจสำหรับเทียน {name} นี่รางวัล..." },
        required = { [772] = { "12:343659626:1608413167", "เทียนเล่มใหญ่" } },
        steps = { { "12:343659626:1608413167", "เทียนเล่มใหญ่" } },
    },
    [61] = { -- Shipment to Stormwind
        title = { "21:806843553:208731816", "สินค้าส่ง Stormwind" },
        objective = { "74:1778585460:1302651302", "นำ William's Shipment ไปให้ Morgan Pestle ใน Stormwind Trade District" },
        description = { "302:1032787887:2074887518", "Morgan พี่น้องชายข้ารอเทียนที่ Stormwind ข้าไม่มีเวลาไปเอง หากเจ้าเอาไปส่ง เขาจะจ่ายดี\n\nข้าแพ็กเทียนแล้ว หา Morgan ได้ในร้าน Pestle's Apothecary ของเราที่ Stormwind Trade District" },
        progress = { "75:1405412179:1262586126", "โอ้ ของส่งจากพี่น้องข้าหรือ? เยี่ยม! วันนี้โชคเข้าข้างจริง ๆ!" },
        completion = { "129:1377440200:1860760630", "นี่ค่าตอบแทน... ไหน ๆ มาแล้ว ลองดูรอบร้าน! มั่นใจว่ามียาหรือของเล็กน้อยที่เจ้าใช้ประโยชน์ได้" },
        required = { [957] = { "18:1035929020:99221582", "ของที่ William ส่งมา" } },
        steps = { { "18:1035929020:99221582", "ของที่ William ส่งมา" } },
    },
    [62] = { -- The Fargodeep Mine
        title = { "18:1001942015:771261487", "เหมือง Fargodeep" },
        objective = { "71:1641569814:1913719940", "สำรวจ Fargodeep Mine แล้วกลับไปหา Marshal Dughan ใน Goldshire" },
        description = { "295:1999736668:761445938", "เหมือง Northshire ไม่ใช่แห่งเดียวที่มีปัญหา! มีรายงานว่า Fargodeep Mine ใน Elwynn ก็กลายเป็นที่อยู่โคโบลด์\n\nสำรวจยืนยันแล้วกลับมา เหมืองอยู่แทบตรงใต้ของ Goldshire ระหว่างที่ดิน Stonefield กับ Maclure" },
        progress = { "28:1652796246:843930526 N 38:448138032:631526440", "มีอะไรจะรายงาน {name}? ไป Fargodeep Mine หรือยัง?" },
        completion = { "118:1653525243:257561741 N 57:1516238469:1684684492", "ข่าวร้าย ต่อไปอะไร มังกรหรือ?!? ต้องเพิ่มลาดตระเวนใกล้เหมือง ขอบใจที่พยายาม {name} รอสักครู่... อาจมีอีกงานให้" },
        objectiveLabels = {
            event = { ["Scout through the Fargodeep Mine"] = "สำรวจภายในเหมือง Fargodeep" },
        },
    },
    [71] = { -- Report to Thomas
        title = { "16:1993327937:572612030", "รายงานต่อ Thomas" },
        objective = { "83:1620276542:2080105260", "ส่ง Rolf and Malakai's Medallions ให้ Guard Thomas ที่สะพาน Elwynn ตะวันออก" },
        description = { "132:2115236419:1169567126", "เมื่อมีเหรียญห้อยคอทั้งสองแล้ว นำให้ Guard Thomas ที่สะพาน เพื่อให้เขารู้ชะตาของยามที่ถูกฆ่า" },
        progress = { "7:989913233:66981971 N 52:1864653035:5304535", "สวัสดี {name} รู้ชะตาของ Rolf กับ Malakai หรือยัง?" },
        completion = { "29:1672535173:1649171942 N 44:1561316277:101342843", "เจ้ายืนยันความกลัวของข้า {name} เมอร์ล็อกเป็นภัยที่มองข้ามไม่ได้" },
        required = { [735] = { "29:1424714876:2136522263", "เหรียญตราของ Rolf และ Malakai" } },
        steps = { { "29:1424714876:2136522263", "เหรียญตราของ Rolf และ Malakai" } },
    },
    [76] = { -- The Jasperlode Mine
        title = { "19:562006680:1390916899", "เหมือง Jasperlode" },
        objective = { "77:92863472:1584435573", "สำรวจ Jasperlode Mine แล้วกลับไปรายงาน Marshal Dughan ใน Goldshire" },
        description = { "339:752226908:1459568077", "เพราะเจ้า เรารู้ว่า Fargodeep Mine ถูกโคโบลด์ยึด ตอนนี้ต้องการคนสำรวจ Jasperlode Mine ที่ไกลกว่า\n\nสำรวจยืนยันโคโบลด์ใน Jasperlode เดินตามถนนตะวันออกจนถึง Tower of Azora จากหอไปเหนือจะพบเหมืองเชิงเขา" },
        progress = { "6:1136836709:1914036474 N 67:360094870:1078916373", "สวัสดี {name} มีอะไรจะรายงาน? สำรวจ Jasperlode Mine แล้วหรือ?" },
        completion = { "117:1254182068:254370264 N 53:1241194344:208947717", "มีโคโบลด์ที่ Jasperlode Mine หรือ? บ้าจริง! สถานการณ์แย่ลงทุกนาที!\n\nขอบใจรายงาน {name} แต่ข้าอยากให้ข่าวที่นำมาดีกว่านี้" },
        objectiveLabels = {
            event = { ["Scout through the Jasperlode Mine"] = "สำรวจภายในเหมือง Jasperlode" },
        },
    },
    [83] = { -- Red Linen Goods
        title = { "15:1158853353:367276712", "สินค้าผ้าลินินแดง" },
        objective = { "75:336633235:775695274", "นำ Red Linen Bandanas 6 ชิ้น ไปให้ Sara Timberlain ที่ Eastvale Logging Camp" },
        description = { "262:1265894030:1576012043", "Defias ใน Northshire สวมหน้ากากผ้ากระสอบ แต่พวกใน Elwynn ใช้ลินินที่ข้านำมาทำของดี ๆ ได้\n\nเอาผ้าโพกลินินแดงมา แล้วข้าจะทำของให้\n\nกลุ่ม Defias มีค่ายกระจายทั่ว Elwynn" },
        progress = { "26:1477793866:141854411 N 25:2130310869:2083661372", "ลินินข้าใกล้หมด {name} มีมาให้ไหม?" },
        completion = { "63:1063774711:2089937852", "อา ผ้าโพกสวย แม้หยาบไปหน่อย...\n\nนี่สำหรับเจ้า!" },
        required = { [1019] = { "17:677943718:603569637", "ผ้าคาดหัวลินินสีแดง" } },
        steps = { { "17:677943718:603569637", "ผ้าคาดหัวลินินสีแดง" } },
    },
    [84] = { -- Back to Billy
        title = { "13:228918910:161277300", "กลับไปหา Billy" },
        objective = { "67:313086132:132972597", "นำ Pork Belly Pie ไปให้ Billy Maclure ที่ Maclure Vineyards" },
        description = { "91:460051585:588617753", "นี่ เมื่อให้พายแก่ Billy บอกด้วยว่าข้าหวังให้มันติดคอ!" },
        progress = { "50:1491330010:1740569423 N 1:63:63", "อึ๋ย... หิวจะตาย! มีพายให้ข้าไหม {name}?" },
        completion = { "72:1315994418:2032874225", "อืม อร่อย! พายนี่สุดยอด!\n\nคิดว่าความทรงจำเริ่มกลับมาแล้ว..." },
        required = { [962] = { "14:527069251:14344300", "พายหมูสามชั้น" } },
        steps = { { "14:527069251:14344300", "พายหมูสามชั้น" } },
    },
    [85] = { -- Lost Necklace
        title = { "13:1722034024:165193091", "สร้อยที่หายไป" },
        objective = { "25:1262432720:394674737", "คุยกับ Billy Maclure" },
        description = { "213:326717711:316641446", "สร้อยข้าหาย คิดว่า Billy Maclure เด็กเกเรนั่นเอาไป! มักวิ่งเหมือนหนูแถวไร่องุ่น Maclure ทางตะวันออก\n\nเอาสร้อยคืน แล้วแม่ม่ายชราคนนี้จะชื่นใจ" },
        completion = { "138:1307608507:1197475848", "เจ้าทำอะไรหาย? ข้าไม่ได้เอาสร้อย เพราะไม่ใช่ขโมย!\n\nอาจรู้ว่าใครเอาไป แต่... <ยิ้มเจ้าเล่ห์>... หิวเกินจะจำได้" },
    },
    [86] = { -- Pie for Billy
        title = { "13:43904039:2080315259", "พายให้ Billy" },
        objective = { "82:711258724:1708054581", "นำ Chunks of Boar Meat 4 ชิ้น ไปให้ Auntie Bernice Stonefield ที่ Stonefield's Farm" },
        description = { "304:1631803455:1400108528", "บางทีถ้าได้พาย ข้าคงบอกได้ว่าใครมีสร้อย แล้วข้าคิดว่า Bernice หญิงชราที่อีกฟาร์มทำพายหมูสามชั้นอร่อย...\n\nบางทีเอาเนื้อจากหมูป่ารอบฟาร์มไปให้ แล้วบอกว่าใช้เพื่ออะไร นางอาจอบพายให้" },
        progress = { "178:683654106:33890270", "ข้าไม่เห็นด้วยที่ต้องให้อาหารเด็กที่ขโมยสร้อยแต่แรก แต่หากต้องทำเพื่อเอาของคืน ก็เอา!\n\nมีเนื้อหมูป่าหรือยัง?" },
        completion = { "95:1694921023:1497908091", "แม้เนื้อหมูป่าเหนียว แต่ตุ๋นพอก็ทำพายอร่อยได้!" },
        required = { [769] = { "18:403259379:436492272", "เนื้อหมูป่าชิ้นหนึ่ง" } },
        steps = { { "18:403259379:436492272", "เนื้อหมูป่าชิ้นหนึ่ง" } },
    },
    [87] = { -- Goldtooth
        title = { "9:1346807259:227477486", "Goldtooth" },
        objective = { "79:1602215627:341505017", "นำ Bernice's Necklace ไปให้ \"Auntie\" Bernice Stonefield ที่ Stonefield Farm" },
        description = { "303:984822646:909429626", "ข้าเล่นใกล้ Fargodeep Mine คิดว่าทำตก เอ่อ... หมายถึงเห็นสร้อยหญิงชรา อย่าถามว่ามาได้อย่างไร... ไม่ใช่ข้านะ!\n\nอย่างไรก็ตาม ข้าเห็นโคโบลด์ตัวใหญ่ฟันทองเก็บสร้อยวิ่งเข้าเหมือง หาโคโบลด์นั่นก็พบสร้อย สาบานได้!" },
        progress = { "7:989913233:66981971 N 29:648010961:92787475", "สวัสดี {name} พบสร้อยข้าหรือยัง?" },
        completion = { "172:734119723:1924847469", "โอ้ พบแล้ว! ขอบใจ ขอบใจที่รัก!\n\nเอานี่ไป เป็นของสามีข้า เขาบอกเสมอว่านำโชค หากเขาไม่ลืมพกไปศึกครั้งสุดท้ายก็คงดี! *สะอื้น*" },
        required = { [981] = { "18:1993247909:1526951008", "สร้อยคอของ Bernice" } },
        steps = { { "18:1993247909:1526951008", "สร้อยคอของ Bernice" } },
    },
    [88] = { -- Princess Must Die!
        title = { "18:1789447326:1233468", "Princess ต้องตาย!" },
        objective = { "91:82774346:39324365", "ฆ่า Princess เก็บปลอกคอ แล้วนำกลับไปให้ Ma Stonefield ที่ Stonefield Farm" },
        description = { "424:349766954:300623144", "Brackwell มีหมูชนะรางวัลชื่อ Princess แม่หมูตัวใหญ่มหึมา เพราะแอบมากินผักข้า!\n\nก่อนกลับมาที่ไร่... Princess ต้องตาย! นำปลอกคอมาเป็นหลักฐาน แล้วข้าจะให้ของตอบแทนเวลา!\n\nPrincess มักอยู่ Brackwell Pumpkin Patch ทางตะวันออกเลยฟาร์ม Maclure จัดการก่อนหิวแล้วกลับมาที่นี่!" },
        progress = { "37:929906619:332478024", "เห็นนางหรือยัง? จัดการได้หรือไม่?" },
        completion = { "88:2143701535:1379589554 N 35:73741620:1254547807", "ขอบคุณสวรรค์! หมูนั่นใหญ่ขึ้นจนจะกินพืชผลเราหมด! ขอบใจ {name}\n\nของสองชิ้นนี้มีชิ้นไหนเหมาะกับเจ้าไหม?" },
        required = { [1006] = { "12:1245534285:518601915", "ปลอกคอทองเหลือง" } },
        steps = { { "12:1245534285:518601915", "ปลอกคอทองเหลือง" } },
    },
    [106] = { -- Young Lovers
        title = { "12:1630703732:919372750", "คู่รักวัยเยาว์" },
        objective = { "51:502832684:1366136427", "มอบ Maybell's Love Letter ให้ Tommy Joe Stonefield" },
        description = { "312:1696997141:2017199369", "โอ้ ข้าเหมือนต้องคำสาป! ใจเป็นของ Tommy Joe Stonefield แต่ครอบครัวเราเป็นศัตรู จึงพบเขาไม่ได้ ทั้งที่ดวงตาปวดร้าวอยากเห็นใบหน้าหล่อเหลานั้น!\n\nโปรดนำจดหมายให้ Tommy Joe เขามักอยู่ริมแม่น้ำทางตะวันตกของ Stonefield Farm ซึ่งอยู่ตรงตะวันตกจากที่นี่" },
        progress = { "83:620459462:1949760524", "เจ้ามีอะไรนะ?? Maybell คือแสงสว่างของชีวิตหม่นหมองข้า รีบให้ดูจดหมาย!" },
        completion = { "53:2100107127:1661603652", "อา! ข้าทนแยกจากกันไม่ไหว ต้องพบนาง!!" },
        required = { [1208] = { "21:1331339390:1070259411", "จดหมายรักของ Maybell" } },
        objectiveLabels = {
            item = { ["Maybell's Love Letter"] = "จดหมายรักของ Maybell" },
        },
    },
    [107] = { -- Note to William
        title = { "15:1518357874:1392191540", "จดหมายถึง William" },
        objective = { "48:1916791639:571962133", "นำ Gramma Stonefield's Note ไปให้ William Pestle" },
        description = { "148:978795878:233119050", "ข้าเชื่อว่า William Pestle มียาช่วยให้คู่รักหนุ่มสาวได้อยู่ด้วยกัน!\n\nนี่ นำจดหมายให้ William เขาพักที่ Lion's Pride Inn ใน Goldshire" },
        progress = { "110:1508681259:225554618", "มีจดหมายจาก “Gramma” Stonefield หรือ? ข้าไม่พบ Mildred หลายปีแล้ว! สงสัยว่านางจะบอกอะไร..." },
        completion = { "170:924439532:850181982", "ข้าสงสารคู่รักน่าสงสาร Maybell กับ Tommy Joe จำได้ว่าครั้งหนึ่งก็เคยหนุ่มและมีรัก\n\nต้องมีทางช่วยสิ! ขอคิดก่อน..." },
        required = { [1252] = { "24:258911496:533567760", "บันทึกของคุณยาย Stonefield" } },
        steps = { { "24:258911496:533567760", "บันทึกของคุณยาย Stonefield" } },
    },
    [109] = { -- Report to Gryan Stoutmantle
        title = { "27:1452978152:2042006101", "รายงานต่อ Gryan Stoutmantle" },
        objective = { "133:1459581291:1742955848", "คุยกับ Gryan Stoutmantle มักพบในหอหินบน Sentinel Hill ข้างถนนกลาง Westfall" },
        description = { "60:922642451:1147327288 C 283:1904830612:1732599024", "ดูเหมือนผ่านการต่อสู้มาไม่น้อย {class} หากยังไม่ได้ทำ ควรไปรายงาน Gryan Stoutmantle เขานำ People's Militia เพื่อปกป้องไร่ Westfall คงใช้ความช่วยเหลือของเจ้าได้ มักพบเขาในหอหินบน Sentinel Hill ข้างถนนกลาง Westfall" },
        completion = { "258:1412164141:382707386", "อา สหายข้าส่งมาหรือ? มีน้ำใจจริง\n\nราชสำนัก Stormwind ทอดทิ้งเรา ตอนนี้ People's Militia ต้องรักษาดินแดนให้พ้นความเสื่อมทราม หากสนใจ ข้าจะใช้ฝีมือการรบเจ้าในนามอิสรภาพ" },
    },
    [111] = { -- Speak with Gramma
        title = { "17:1641593600:1582528692", "คุยกับ Gramma" },
        objective = { "29:429438317:559003257", "คุยกับ Gramma Stonefield" },
        description = { "8:53454870:415607459 N 128:282164647:223594872", "ขอร้อง {name} คุยกับ Gramma ของข้า หากใครหาทางให้ข้ากับ Maybell อยู่ด้วยกันได้ ก็คือนาง\n\nนางอยู่ในบ้านทางตะวันออกจากที่นี่" },
        progress = { "66:1142657151:2053755384", "ข้าอยากรู้ว่าสหายจะมีท่าทีอย่างไรเต็มที!\n\nพวกเขาต้องคาดไม่ถึงแน่" },
        completion = { "167:1490403061:576898650", "ขณะครอบครัวบาดหมาง Tommy Joe กับ Maybell คงไม่มีอนาคตร่วมกันนัก แต่... บางทีเราช่วยให้พบกันสักช่วงสั้น ๆ ได้\n\nอืม ทำอย่างไรดี..." },
    },
    [112] = { -- Collecting Kelp
        title = { "15:690286887:717655249", "เก็บสาหร่ายเคลป์" },
        objective = { "59:1645445644:581569317", "นำ Crystal Kelp Fronds 4 ชิ้น ไปให้ William Pestle ใน Goldshire" },
        description = { "330:1727790694:321640616", "ข้าทำเหล้าล่องหนให้ Maybell ได้ นางจะได้ลอบออกจาก Maclure Vineyards ไปหา Tommy Joe แต่ต้องใช้ Crystal Kelp\n\nแม้สาหร่ายนี้มักขึ้นในทะเล... บางครั้งเมอร์ล็อกเก็บไว้ ลองดูพวกใกล้ Crystal Lake ว่ามีไหม ทะเลสาบอยู่ทางตะวันออกจาก Goldshire" },
        progress = { "77:1585164584:376547300", "มี Crystal Kelp หรือยัง? Maybell คงอยากพบคนรักเต็มที..." },
        completion = { "75:2017636276:1032501286", "ได้มาแล้ว ดีมาก! รอสักครู่ข้าจะผสมยา..." },
        required = { [1256] = { "18:678997652:1003997525", "ใบสาหร่ายเคลป์ผลึก" } },
        steps = { { "18:678997652:1003997525", "ใบสาหร่ายเคลป์ผลึก" } },
    },
    [114] = { -- The Escape
        title = { "10:1720783701:1462715557", "ลอบหนี" },
        objective = { "48:1371076517:695616916", "นำ Invisibility Liquor ไปให้ Maybell Maclure" },
        description = { "102:1664971982:1713136703", "นำเหล้าล่องหนให้ Maybell น่าจะออกฤทธิ์นานพอให้นางพบ Tommy Joe" },
        progress = { "57:507144296:1526568997", "ส่งจดหมายให้ Tommy Joe แล้วหรือ? เขาว่าอย่างไร??" },
        completion = { "111:639298146:1819923261 N 113:1260294000:1095749039", "โอ้... ตายจริง! ข้ารู้สึกผิดที่หลอกครอบครัว แต่ความรักต่อ Tommy Joe แรงกล้าเกินเมินได้\n\nขอบใจ {name} จะดื่มทันทีที่ได้โอกาสแล้วลอบไปหาคนรัก\n\nส่วนเจ้า... โปรดรับนี่" },
        required = { [1257] = { "19:540115649:2105230064", "เหล้าล่องหน" } },
        steps = { { "19:540115649:2105230064", "เหล้าล่องหน" } },
    },
    [123] = { -- The Collector
        title = { "13:2040069837:470904883", "ผู้เก็บทอง" },
        objective = { "72:300925426:1058503060", "ไปหา Marshal Dughan ใน Goldshire แล้วมอบ The Collector's Schedule ให้เขา", variants = { { "71:1613872643:1303127555", "ไปหา Marshal Dughan ใน Goldshire แล้วมอบ The Collector's Schedule ให้เขา" } } },
        description = { "356:1262003731:492656739", "จดหมายนี้เป็นตารางวันเวลาที่คนซึ่งระบุเพียง “The Collector” จะรับทองจากเหมืองใน Elwynn Forest\n\nจากตาราง ดูเหมือนผู้เก็บทองอยู่ใกล้ Brackwell Pumpkin Patch ใน Elwynn ตะวันออก\n\nฟังดูสำคัญ ควรรายงาน Marshal Dughan ใน Goldshire" },
        progress = { "103:2037422772:1976446170", "อะไรนะ?!? เราไม่มีคนทำเหมือง Elwynn มาหลายเดือนแล้ว!\n\nขอดูจดหมายนั่น..." },
        completion = { "142:262390836:1573759683", "อืม... เคยได้ยิน “Collector” แต่ไม่รู้ทำงานให้ใคร ขอบใจตารางนี้ มันจะช่วยไขปริศนา" },
        required = { [2223] = { "24:1495863058:1023333035", "ตารางงานของนักสะสม" } },
        steps = { { "24:1495863058:1023333035", "ตารางงานของนักสะสม" } },
    },
    [147] = { -- Manhunt
        title = { "7:2067032478:1073822791", "ตามล่าคนร้าย" },
        objective = { "86:1622121742:2024945611", "หาและฆ่า \"the Collector\" แล้วกลับไปหา Marshal Dughan พร้อม The Collector's Ring" },
        description = { "356:1066501125:2096877049", "หาก “Collector” เอาทองจากเหมืองเรา ก็ขโมยจากอาณาจักร! นำคนร้ายมารับโทษ และเอาแหวนที่กล่าวในตารางรับของมาให้ข้า อาจบอกได้ว่าเขาทำงานให้ใคร...\n\nตารางบอกว่าผู้เก็บทองซ่อนที่ Brackwell Pumpkin Patch ควรไปค้นที่นั่น" },
        progress = { "67:493088735:1317866210", "พบ Collector หรือยัง? รู้หรือไม่ทำงานให้ใคร?" },
        completion = { "26:1116009649:1583147863 N 337:213811013:2004649140", "พบแล้วหรือ? ทำได้ดี {name} เขาจะไม่ได้ “เก็บ” จากเหมือง Elwynn อีก!\n\nแหวนนี้น่าสนใจ... เป็นแหวนสมาชิก Stonemason's Guild เก่าใน Stormwind ทำไมโจรต่ำต้อยมีแหวนกิลด์ช่าง และทำไม Defias Thieves เก็บเงินจากเหมืองเรา?\n\nคำถามยาก หวังว่าสักวันเราจะได้คำตอบ" },
        required = { [2239] = { "20:29308115:951617009", "แหวนของนักสะสม" } },
        steps = { { "20:29308115:951617009", "แหวนของนักสะสม" } },
    },
    [176] = { -- WANTED: "Hogger"
        title = { "16:1972156259:797049180", "ประกาศจับ: \"Hogger\"" },
        objective = { "70:1400411076:1187714382", "ฆ่าโนลล์ Hogger แล้วนำ Huge Gnoll Claw ไปให้ Marshal Dughan" },
        description = { "297:1049898160:109664889", "ประกาศจับ: Hogger\n\nโนลล์ร่างใหญ่ Hogger ออกหากินในป่าตะวันตกเฉียงใต้ของ Elwynn เอาชนะทุกความพยายามจับกุมมาแล้ว\n\nกองทัพ Stormwind ตั้งค่าหัวอย่างงาม นักล่าค่าหัวต้องนำหลักฐานความตายไปให้ Marshal Dughan ใน Goldshire เพื่อรับรางวัล" },
        progress = { "97:1716872232:345808666", "ใช่ Hogger สร้างปัญหาให้ข้ากับคนมาก มีอะไรจะรายงานเกี่ยวกับมันหรือ?" },
        completion = { "91:1015720296:412793235 N 79:684561357:743590603", "ฮ่า! ทำได้ดี! ข้าเริ่มคิดว่าไม่มีใครโค่นสัตว์ประหลาดนั่นได้!\n\nนี่ {name} และขอบใจ โนลล์นั่นทำข้าปวดหัวใหญ่เท่า Blackrock Spire!" },
        required = { [1931] = { "15:1353742786:500990927", "กรงเล็บโนลล์ขนาดใหญ่" } },
        steps = { { "15:1353742786:500990927", "กรงเล็บโนลล์ขนาดใหญ่" } },
    },
    [239] = { -- Westbrook Garrison Needs Help!
        title = { "30:699999247:1193530774", "Westbrook Garrison ต้องการคนช่วย!" },
        objective = { "58:1697033309:79996615", "ไป Westbrook Garrison แล้วคุยกับ Deputy Rainer" },
        description = { "412:949819955:1704508080", "ป้อมชายแดนตะวันตกส่งข่าวว่าโนลล์กับโจรเคลื่อนไหวมากขึ้น ขอทหาร Stormwind เพิ่ม... แต่เราไม่มีเหลือให้!\n\nหากเจ้าช่วยได้ เราต้องการ ไปคุยกับ Deputy Rainer ที่ Westbrook Garrison ว่าต้องทำอะไร\n\nป้อมอยู่ตามถนนตะวันตก เมื่อข้ามสะพานลำธารเล็ก จะอยู่ขวามือ" },
        completion = { "198:1334034803:1622959192", "Marshall Dughan ส่งเจ้ามาหรือ? แม้ไม่ใช่ทหาร แต่หาก Dughan ส่งมาก็พอสำหรับข้า!\n\nสถานการณ์เราตึงเครียด แม้จะพูดให้น้อยที่สุด หวังว่าเจ้าช่วยได้" },
    },
    [2158] = { -- Rest and Relaxation
        title = { "19:731562698:1473949925", "พักผ่อนหย่อนใจ" },
        objective = { "52:1962250687:515675438", "คุยกับ Innkeeper Farley ที่ Lion's Pride Inn" },
        description = { "378:1679095205:1816953680", "นักผจญภัยทุกคนควรพักเมื่อเหนื่อย และไม่มีที่ใดพักได้ดีเท่า Lion's Pride Inn!\n\nInnkeeper Farley สหายสนิทข้าดูแลโรงเตี๊ยม หากบอกว่าข้าส่งมา เขาอาจลดค่าอาหารเครื่องดื่มเป็นพิเศษ\n\nหาโรงเตี๊ยมโดยเดินถนนใต้จากที่นี่ ไม่มีทางพลาด!" },
        completion = { "191:185490465:1460711865", "พักผ่อนให้คนหนาวเหนื่อย นั่นคือคำขวัญเรา! นั่งข้างไฟพักกระดูกที่ล้าเถอะ\n\nอยากลองอาหารเครื่องดื่มดี ๆ ของเราบ้างไหม?" },
    },
    [3903] = { -- Milly Osworth
        title = { "13:1835435140:1158349674", "Milly Osworth" },
        objective = { "25:1131542269:392037837", "คุยกับ Milly Osworth" },
        description = { "35:1353525424:471414235 C 2:11340:5796 N 238:1765863791:30595066", "เจ้าพิสูจน์ว่าเป็น {class} ที่พึ่งได้ {name} พึ่งได้และไม่กลัวมือเปื้อนสินะ?\n\nสหายข้า Milly Osworth มีปัญหา อยู่กับเกวียนอีกด้านของวิหารใกล้คอกม้า มั่นใจว่านางต้องการมือช่วยอย่างเจ้า" },
        completion = { "219:833010603:1363295923", "โอ้ Deputy Willem ให้มาคุยกับข้าหรือ? เขากล้าและพร้อมช่วยเสมอ แต่หน้าที่ทำให้ติด Northshire Abbey และเกรงว่าปัญหาวันนี้เกินกำลังเขา\n\nบางทีเจ้าช่วยได้?" },
    },
    [3904] = { -- Milly's Harvest
        title = { "15:1885104100:599809403", "ผลผลิตของ Milly" },
        objective = { "71:481020596:268971427", "นำ Milly's Harvest 8 ลัง ไปให้ Milly Osworth ที่ Northshire Abbey" },
        description = { "483:1448880396:1823058091", "โจร Defias ย้ายเข้า Northshire Vineyards ตอนข้ากำลังเก็บเกี่ยว! ข้าแจ้งยามแล้ว พวกเขารับปากจัดการ แต่... ห่วงองุ่น! หากโจรไม่ขโมย ก็กลัวยามเหยียบเสียตอนขับไล่\n\nโปรดช่วย! ข้าเก็บองุ่นส่วนใหญ่ใส่ถังแล้ว แต่ทิ้งไว้ในไร่ทางตะวันออกเฉียงใต้\n\nเอาลังเหล่านั้นมา! ช่วยผลผลิตข้า!" },
        progress = { "24:1327049244:650477639 N 1:63:63", "มีผลผลิตข้าไหม {name}?" },
        completion = { "14:1072558204:133718918 N 205:636510752:581767908", "โอ้ ขอบใจ {name}! เจ้าช่วยผลผลิตไว้! หวังว่าได้สอน Defias บางคนด้วยว่าก่อเรื่องแถวนี้ไม่ได้\n\nช่วงนี้ยามอาจน้อย แต่โชคดีมีวีรบุรุษอย่างเจ้าปกป้อง!" },
        required = { [11119] = { "15:1885104100:599809403", "ผลผลิตของ Milly" } },
        steps = { { "15:1885104100:599809403", "ผลผลิตของ Milly" } },
    },
    [3905] = { -- Grape Manifest
        title = { "14:1162206500:1933087581", "บัญชีส่งองุ่น" },
        objective = { "62:167848808:1629950251", "นำ Grape Manifest ไปให้ Brother Neals ใน Northshire Abbey" },
        description = { "284:535911422:357979113", "เมื่อผลผลิตปลอดภัย นำ Grape Manifest ให้ Brother Neals เขาดูแลคลังอาหารเครื่องดื่ม Northshire คงยินดีที่มีองุ่นสด\n\nพบ Brother Neals ในหอระฆังของวิหาร... ที่เขาชอบชิมไวน์" },
        progress = { "68:826185819:1179897184", "ดูอารมณ์ดีทีเดียว! มา นั่งดื่มสักแก้ว!" },
        completion = { "256:1935110621:109748310 N 20:962640626:1307821352", "มาดู...\n\nโอ้! องุ่น Milly ปลอดภัย! เมื่อนางบอกว่าโจรยึดไร่ ข้าแทบสิ้นหวัง แต่ศรัทธาในแสงสว่างไม่สั่นคลอน!\n\nความกล้าของเจ้าทำให้เรามีองุ่นทำไวน์อีก! ขอแสงสว่างอวยพร {name} และคุ้มครองเจ้า!" },
        required = { [11125] = { "14:1162206500:1933087581", "บัญชีรายการองุ่น" } },
        steps = { { "14:1162206500:1933087581", "บัญชีรายการองุ่น" } },
    },
    [5261] = { -- Eagan Peltskinner
        title = { "17:1655643747:40922286", "Eagan Peltskinner" },
        objective = { "29:1278442465:1667063477", "คุยกับ Eagan Peltskinner" },
        description = { "242:1844717868:1083625618", "Eagan Peltskinner หาคนล่าหมาป่า เป็นข่าวดี เพราะพักนี้เห็นหมาป่าใน Northshire Valley มากขึ้น\n\nหากสนใจ คุยกับ Eagan เขาอยู่ข้างวิหารด้านซ้าย" },
        completion = { "81:224221676:240485380", "จริง ข้าหาคนล่าหมาป่า! เจ้าคือคนนั้นหรือ?" },
    },
    [5545] = { -- A Bundle of Trouble
        title = { "19:474958427:1975197868", "ไม้ฟืนกับเรื่องยุ่ง" },
        objective = { "63:1004408304:2071357412", "นำ Bundles of Wood 8 มัด ไปให้ Raelen ที่ Eastvale Logging Camp" },
        description = { "429:97800934:280641807", "ข้ามีปัญหาใหญ่ คำสั่งซื้อไม้ใกล้กำหนดส่ง เวลาเหลือน้อย หมาป่ากับหมีทางเหนือไล่คนงานหนีจากมัดไม้ที่ตัดแล้ว\n\nคุยกับ Deputy Rainer เรื่องกำจัดสัตว์แล้ว แต่ต้องมีคนไปเก็บไม้ หากเจ้าเก็บมาแปดมัด ข้าอาจส่งงานทัน" },
        progress = { "46:391017020:771102708 C 49:228274009:2003211676", "กำหนดส่งไม่เลื่อนหนีไปไหน {class} โปรดรีบเก็บมัดไม้" },
        completion = { "186:2142875288:1709056183", "เยี่ยม! เพราะเจ้า ข้าคงส่งงานทัน เพื่อขอบคุณ อยากมอบเหรียญชดเชยความลำบาก\n\nขอบใจและลาก่อน" },
        required = { [13872] = { "14:765750328:671332681", "มัดไม้" } },
        steps = { { "14:765750328:671332681", "มัดไม้" } },
    },
    [7677] = { -- White Stallion Exchange
        title = { "23:1424073665:1254367676", "แลก White Stallion" },
        objective = { "258:710885618:1064394968", "หากนำ White Stallion มา ข้าจะแลกตัวหนึ่งจากฝูงใหม่ให้ ม้าใหม่เร็วเท่าตัวเก่า แต่รูปลักษณ์ต่างกัน ดูม้าฝีเท้าไวที่นี่ได้ว่าเป็นอย่างไร\n\nต้องจ่ายเพิ่ม 500 Gold ด้วย..." },
        completion = { "232:1342122968:812155548", "หากนำ White Stallion มา ข้าจะแลกตัวหนึ่งจากฝูงใหม่ให้ ม้าใหม่เร็วเท่าตัวเก่า แต่รูปลักษณ์ต่างกัน ดูม้าฝีเท้าไวที่นี่ได้ว่าเป็นอย่างไร" },
        required = { [12353] = { "21:800198778:1717956865", "บังเหียนม้าขาว" } },
        objectiveLabels = {
            item = { ["White Stallion Bridle"] = "บังเหียนม้าขาว" },
        },
    },
    [7678] = { -- Palomino Exchange
        title = { "17:1722186576:116919980", "แลก Palomino" },
        completion = { "228:1597003436:1021715627", "หากนำ Palomino มา ข้าจะแลกตัวหนึ่งจากฝูงใหม่ให้ ม้าใหม่เร็วเท่าตัวเก่า แต่รูปลักษณ์ต่างกัน ดูม้าฝีเท้าไวที่นี่ได้ว่าเป็นอย่างไร" },
        required = { [12354] = { "15:138683779:606419831", "บังเหียนม้า Palomino" } },
        objectiveLabels = {
            item = { ["Palomino Bridle"] = "บังเหียนม้า Palomino" },
        },
    },
    [91723] = { -- Delicate Instruments
        title = { "20:993408646:103701342", "เครื่องมืออันละเอียดอ่อน" },
        objective = { "98:1545294841:532955274", "ฆ่า Kobold Geomancers 8 ตัว ใน Jasperlode Mine แล้วกลับไปหา Hamish Bergwort ที่ Tower of Azora" },
        description = { "299:967008399:1014119041", "บ้าจริง! ทุกครั้งที่ปรับเทียบเครื่องมืออาร์เคนอันละเอียดอ่อน ก็มีพลังพุ่งมารบกวนอีก\n\nดูเหมือนมาจากเหนือ ที่โคโบลด์ป่าเถื่อนใช้เวทหยาบ ๆ เจ้าช่วยกำจัดบางส่วนเพื่อให้ข้าทำงานต่อได้ไหม?" },
        progress = { "82:1015034122:1492599588", "แจ้งเมื่อเสร็จ ข้าจะลองปรับเทียบเครื่องมืออีกครั้ง" },
        completion = { "57:1333723294:1022070535", "ทำได้ดีสหาย ให้ข้าลองปรับเทียบอีก..." },
        objectiveLabels = {
            monster = { ["Kobold Geomancer slain"] = "ปราบ โคโบลด์ผู้ใช้เวทปฐพี" },
        },
    },
    [91724] = { -- Delicate Instruments
        title = { "20:993408646:103701342", "เครื่องมืออันละเอียดอ่อน" },
        objective = { "102:585701740:1317311752", "ฆ่า Defias Rogue Wizards 6 ตัว ที่ Stone Cairn Lake แล้วกลับไปหา Hamish Bergwort ที่ Tower of Azora", amount = { "5:409775429:850574908 W1 96:938706855:1912258710", "ฆ่า Defias Rogue Wizards {world1} ตัว ที่ Stone Cairn Lake แล้วกลับไปหา Hamish Bergwort ที่ Tower of Azora" } },
        description = { "108:1308158339:982633268 N 186:1739229141:121771199", "เกือบแล้ว และ... ให้ตายเถอะ! ยังมีอะไรขัดเครื่องมือ\n\nน่าหงุดหงิดนัก {name} ได้ยินข่าวว่าโจรท้องถิ่นฝึกคาถาใกล้ Stone Cairn Lake หากเจ้าหยุดพวกนั้น การรบกวนอาจจบและข้าจะได้ทำงาน?" },
        completion = { { "64:92730651:1369313542", "57:939171613:1451111252 N 1:46:46", "57:939171613:1451111252 C 1:46:46", "57:939171613:1451111252 R 1:46:46" }, "ดูเหมือนทุกอย่างทำงานดี ขอบใจสหาย" },
        progress = { "82:1015034122:1492599588", "เสร็จแล้วบอกข้าด้วย ข้าจะได้ลองปรับเทียบเครื่องมืออีกครั้ง" },
        objectiveLabels = {
            monster = { ["Defias Rogue Wizard slain"] = "ปราบ พ่อมดนอกรีต Defias" },
        },
    },
    [91725] = { -- Stolen Enchanting Supplies
        title = { "26:1464115590:1922673001", "อุปกรณ์เอนแชนต์ที่ถูกขโมย" },
        objective = { "134:1323175305:1495639617", "เก็บ Stolen Enchanting Supplies 5 ชิ้น จากค่ายโนลล์รอบ Stone Cairn Lake แล้วกลับไปหา Blixie Fitzwink ใกล้ Tower of Azora" },
        description = { "335:1734984638:142423128", "Master Theocritus ส่งข้าไปรับอุปกรณ์เอนแชนต์จากจุดค้าขาย แต่ขากลับถูกโนลล์ซุ่มโจมตี!\n\nข้าทิ้งห่อของแล้วหนี หากกลับมือเปล่า คงถูกลงโทษเก็บกวาดหลังทดลองแปลงร่างหลายสัปดาห์! เจ้าช่วยหาของให้ได้ไหม?" },
        progress = { "26:1244820764:1591441387", "พบเสบียงหรือยัง?" },
        completion = { "60:1119288512:1195868156", "โอ้ โล่งใจ! ดูเหมือนอยู่ครบ ขอบใจ!" },
        required = { [247805] = { "26:1464115590:1922673001", "อุปกรณ์ลงมนตร์ที่ถูกขโมย" } },
        steps = { { "26:1464115590:1922673001", "อุปกรณ์ลงมนตร์ที่ถูกขโมย" } },
    },
    [91732] = { -- Good Steel
        title = { "10:1331905465:1697441443", "เหล็กกล้าดี" },
        objective = { "96:410466337:1485020649", "เก็บ Mining Tools 4 ชิ้น จาก Jasperlode Mine แล้วกลับไปหา Hagar Lowe ที่ Eastvale Logging Camp" },
        description = { "274:535981928:837531233", "หลังสงครามเหล็กกล้าดีขาดแคลน เครื่องมือเราจึงแย่ตาม คนเหมือง Jasperlode ใช้พลั่วขุดฝีมือดี คิดว่าบางส่วนยังอยู่ลึกในเหมือง ช่วยเอามา ข้าจะดูว่านำเหล็กใช้ใหม่ได้ไหม?" },
