        required = { [247813] = { "15:551990117:910684181", "เลื่อยอมน้ำ" }, [247817] = { "15:550807128:910378278", "ขวานอมน้ำ" }, [247818] = { "19:889076986:2005314069", "กล่องเครื่องมืออมน้ำ" } },
