        description = { "103:1846809345:330155880", "โคโบลด์เลวพวกนั้นกินหนังสือข้า! ต้องเอาคืนก่อนกินทั้งห้องสมุด" },
        progress = { { "39:1176714329:922553427", "31:402394686:262084735 N 2:16224:8286", "31:402394686:262084735 C 2:16224:8286", "31:402394686:262084735 R 2:16224:8286" }, "ช่วยหนังสือคืนแล้วหรือยังสหาย?!", variants = { { "31:402394686:262084735 N 2:16224:8286", "เอาหนังสือของข้าคืนมาได้หรือยัง {name}?!" } } },
        completion = { "187:15339932:499485761", "ขอบใจมาก! นี่ รับคู่มือเล่มหนึ่งไป ข้าไม่ต้องใช้\n\nแต่ยังหายอีกมาก ดูเหมือนโคโบลด์ไม่ได้กิน แล้วเอาไปทำไม?", variants = { { "185:180650213:2080083209", "ขอบใจมาก! นี่ รับคู่มือเล่มหนึ่งไป ข้าไม่ต้องใช้\n\nแต่ยังหายอีกมาก ดูเหมือนโคโบลด์ไม่ได้กิน แล้วเอาไปทำไม?" } } },
        required = { [247839] = { "11:1680329842:1492771055", "หนังสือที่ถูกขโมย" } },
