        title = { "16:1119024158:504949494", "หนังหมาป่าหยาบ" },
        objective = { "118:539834466:1796481399", "ถลกหนังหมาป่ารอบ Elwynn Forest เพื่อเก็บ Rough Wolf Pelts 7 ผืน แล้วส่งให้ Helene Peltskinner ใกล้ Goldshire", amount = { "43:479835951:987409474 W1 74:1114819970:228520066", "ถลกหนังหมาป่ารอบ Elwynn Forest เพื่อเก็บ Rough Wolf Pelts {world1} ผืน แล้วส่งให้ Helene Peltskinner ใกล้ Goldshire" } },
        description = { "211:371589724:902097956", "หาโอกาสฝึกถลกหนังอยู่หรือ? ปกติสามีช่วยล่าหมาป่า แต่ตอนนี้ยุ่งใกล้วิหาร ข้าอยากได้คนช่วยเก็บหนังเพิ่มเพื่อทำงานสั่งซื้อให้เสร็จ" },
        progress = { "31:1864999400:4939488", "ได้หนังหมาป่าบ้างไหม?" },
        completion = { { "86:1340833990:871262665", "39:142339875:729379131 N 37:2083985887:1009442315", "39:142339875:729379131 C 37:2083985887:1009442315", "39:142339875:729379131 R 37:2083985887:1009442315" }, "เก็บหนังได้ดี นักผจญภัย เจ้ามีพรสวรรค์ล่าจริง ๆ", variants = { { "83:1535731739:108749089", "พาลาดิน เจ้าเก็บหนังพวกนี้มาได้ดีมาก เจ้ามีพรสวรรค์ด้านการล่าจริง ๆ" } } },
        required = { [247877] = { "15:672831579:2020194166", "หนังหมาป่าหยาบ" } },
        steps = { { "15:672831579:2020194166", "หนังหมาป่าหยาบ" } },
    },
    [91752] = { -- The Big Picture
        title = { "15:2066225690:850972079", "ภาพรวมของเรื่อง" },
        objective = { "123:1543575235:263545928", "นำ Sack of \"Picture\" Books จาก Shinyfinder Narf ไปให้ Marshal McBride ด้านใน Northshire Abbey ใกล้ทางเข้า" },
        description = { "360:1582916740:349397577", "นาน ๆ ทีมีโคโบลด์ผ่านมา ตะโกน “Picture for Narf!” ไม่รู้ Narf คือใคร อาจเป็นหัวหน้าแถวท้ายเหมือง? คงมีหนังสือเต็มถุงแล้ว\n\nไปเอาหนังสือให้ผู้รักษากฎหมายท้องถิ่น Marshal McBride ควรหาสหายช่วย โคโบลด์ในเหมืองดุร้ายกว่าเยอะ" },
        progress = { "42:2103691696:149549391", "นำหนังสือที่ถูกขโมยคืนแล้วหรือยัง?" },
        completion = { { "152:703236895:107199277", "44:657879787:1524764585 N 102:2020829159:1531776285", "44:657879787:1524764585 C 102:2020829159:1531776285", "44:657879787:1524764585 R 102:2020829159:1531776285" }, "ขอบใจที่คืนหนังสือสหาย ข้าจะส่งคืน Brother Paxton ทันที\n\nเจ้ากลายเป็นวีรบุรุษแถวนี้แล้ว ทำได้เยี่ยม!" },
        required = { [247886] = { "23:1687240149:765209679", "กระสอบใส่หนังสือ “ภาพ”" } },
        steps = { { "23:1687240149:765209679", "กระสอบใส่หนังสือ “ภาพ”" } },
    },
    [91753] = { -- An Enchanting Lesson
        title = { "20:556423845:2021107875", "บทเรียนเอนแชนต์" },
        objective = { "176:758263014:824288275", "Kitta Firewind ที่ Tower of Azora ต้องการให้เจ้าเก็บ Luminous Residue 3 ชิ้น\n\nหา Luminous Residue ได้โดยสลายมนตร์ Crude Wax Effigies ที่ตกจาก Kobold Geomancers" },
        description = { "387:477098119:751646048", "ความเข้มงวดทางวิชาการจำเป็นต่องานเอนแชนต์แน่นอน แต่รากฐานลงมือจริงก็มีประโยชน์ ลองดูโคโบลด์ต่ำต้อย แม้ไร้การศึกษาเป็นระบบ ยังแสดงพรสวรรค์โดยกำเนิดต่อคาถาและการเสริมมนตร์ง่าย ๆ\n\nเอารูปปั้นขี้ผึ้งของพวกมันมาแยกมนตร์ที่ผูกไว้ เจ้าอาจเข้าใจมากขึ้น" },
        progress = { "32:749211727:1282320337", "การศึกษาพบอะไรบ้าง?" },
        completion = { { "67:525975855:1662185091", "45:1174511281:344196363 N 16:1021715616:1048037489", "45:1174511281:344196363 C 16:1021715616:1048037489", "45:1174511281:344196363 R 16:1021715616:1048037489" }, "ทฤษฎีกับปฏิบัติเป็นสองด้านของเหรียญสหาย จำไว้" },
        required = { [247884] = { "16:477056569:1563801170", "เศษตกค้างเรืองแสง" } },
        steps = { { "16:477056569:1563801170", "เศษตกค้างเรืองแสง" } },
    },
    [91758] = { -- Follow That Kobold!
        title = { "19:1107837236:799916872", "ตามโคโบลด์นั่นไป!" },
        objective = { "70:1845587610:1951150558", "คุยกับ Tordrin Sternblade ใกล้คอกม้าหลัง Northshire Abbey" },
        description = { "400:1052451574:2027577990", "งานโคโบลด์ยังไม่จบ เพิ่งได้ข่าว Kelsey ว่ามีตัวหนึ่งออกจากเหมืองพร้อมถุงหนังสือใหญ่ ข้าต้องให้เจ้าตามเพื่อเอาหนังสือคืน Brother Paxton\n\nไปคุยกับ Tordrin Sternblade อาจารย์ Hunter คนใหม่ที่เพิ่งมาจาก Ironforge อยู่หลังวิหารใกล้คอกม้า เขาช่วยตามโจรโคโบลด์ได้" },
        completion = { "73:1942547345:493086660", "ข้าช่วยตามเจ้าตัวแสบนี่ได้ ขอเตรียมอะไรให้หน่อย" },
    },
    [91772] = { -- Shhh! We're Hunting Kobolds
        title = { "27:892308186:497241718", "ชู่ว์! เรากำลังล่าโคโบลด์" },
        objective = { "114:15874011:1694990641", "ตามรอยโคโบลด์ แล้วรายงานสิ่งที่พบแก่ Marshal Dughan ใน Goldshire พร้อมนำ Kobold Tracking Kit ไปด้วย" },
        description = { "291:848859318:345536918", "เอาล่ะ รับ Kobold Tracking Kit มันช่วยตามโคโบลด์ที่ Marshal McBride ห่วง\n\nตามรอยแล้วนำสิ่งที่พบไปให้ Marshal Dughan ใน Goldshire\n\nรู้สึกว่าเจ้าตัวแสบคิดทำบางอย่างนอก Northshire เจ้าคงต้องให้ Dughan ช่วย" },
        progress = { "51:949968943:1704718722", "รู้หรือยังว่าโคโบลด์ไปไหน?" },
        completion = { { "209:1490507903:1961946784", "13:735579249:564635156 N 190:1772329834:235664379", "13:735579249:564635156 C 190:1772329834:235664379", "13:735579249:564635156 R 190:1772329834:235664379" }, "อะไรนะสหาย? ตามรอยโคโบลด์?\n\nแน่นอน มันมุ่ง Fargodeep Mine! ที่นั่นเต็มไปด้วยโคโบลด์\n\nก็ทำได้ดี ข้าคงต้องมีคนจัดการปัญหานั้น" },
        required = { [247970] = { "19:1805938572:2122577519", "ชุดติดตามโคโบลด์" } },
        steps = { { "22:1178380674:184507940", "ตามรอยเท้าโคโบลด์" }, { "19:1805938572:2122577519", "ชุดติดตามโคโบลด์" } },
    },
    [91775] = { -- Book Return
        title = { "11:1849854170:1592662473", "คืนหนังสือ" },
        objective = { "78:1091506321:478798084", "หา Lost Books 6 เล่ม และ \"Fun with Elementals\" แล้วคืนให้ Marshal Dughan" },
        description = { "402:1711428606:489729956", "ระหว่างสำรวจ Fargodeep Mine ลองหาหนังสือ Brother Paxton คืน เขาห่วงเล่มชื่อ “Fun with Elementals” เป็นพิเศษ คิดว่าแม้โคโบลด์ก็ใช้เรียกธาตุมารับใช้ได้ ระวัง ส่วนลึกของเหมืองอันตราย ควรพาสหาย\n\nเอาถุงหนังสือนี้ไปป้องกันหนังสือเมื่อพบ!" },
        progress = { "33:1177406019:452001610", "พบหนังสือครบหรือยัง?" },
        completion = { { "195:2063150703:1418684685", "26:137521694:226561447 N 163:1481802238:1971862056", "26:137521694:226561447 C 163:1481802238:1971862056", "26:137521694:226561447 R 163:1481802238:1971862056" }, "ข้าขอชมความขยันสหาย Brother Paxton ส่งรายชื่อมา เจ้าพบส่วนใหญ่แล้ว ที่เหลือคงถูกเอาไป Jasperlode Mine\n\nเก็บถุงหนังสือไว้ได้!" },
        required = { [248002] = { "33:1476384155:403698392", "หนังสือภาพ: สนุกกับภูตธาตุ" }, [248001] = { "9:1736708880:1345977745", "หนังสือที่หายไป" } },
        steps = { { "33:1476384155:403698392", "หนังสือภาพ: สนุกกับภูตธาตุ" }, { "9:1736708880:1345977745", "หนังสือที่หายไป" } },
    },
    [91777] = { -- Rare Books
        title = { "10:1369671695:83953693", "หนังสือหายาก" },
        objective = { "159:2137879681:1888962960", "หา \"Geomancy for Curious Young Wizards\" และ \"Arcane Explainer: Magical Stuff in Simple Words\" คืนให้ Brother Paxton ใน Northshire Abbey" },
        description = { "455:391954044:722887414", "ในรายชื่อ Brother Paxton ยังขาดสองเล่ม: “Geomancy for Curious Young Wizards” กับ “Arcane Explainer: Magical Stuff in Simple Words”\n\nโคโบลด์คงนำไป Jasperlode Mine โปรดตามหาสองเล่มนี้แล้วคืน Brother Paxton\n\nแต่คงอันตราย หากโคโบลด์ “ฝึกหัด” เรียกธาตุได้ ใครจะรู้ว่าอาจารย์ทำอะไรได้ หากเป็นข้าจะพาสหายไป", variants = { { "453:61071417:2130294060", "ในรายชื่อ Brother Paxton ยังขาดสองเล่ม: “Geomancy for Curious Young Wizards” กับ “Arcane Explainer: Magical Stuff in Simple Words”\n\nโคโบลด์คงนำไป Jasperlode Mine โปรดตามหาสองเล่มนี้แล้วคืน Brother Paxton\n\nแต่คงอันตราย หากโคโบลด์ “ฝึกหัด” เรียกธาตุได้ ใครจะรู้ว่าอาจารย์ทำอะไรได้ หากเป็นข้าจะพาสหายไป" } } },
        progress = { "40:1075117745:1323038209", "พบหนังสือที่หายของข้าครบหรือยัง?" },
        completion = { { "199:1136165348:293848665", "4:1347873283:179389729 N 189:1883684112:1938673606", "4:1347873283:179389729 C 189:1883684112:1938673606", "4:1347873283:179389729 R 189:1883684112:1938673606" }, "โอ้สหาย! ขอบใจมากที่ช่วยห้องสมุด เจ้าช่วยข้าอย่างเหลือเชื่อ โปรดรับอาวุธดีชิ้นหนึ่ง เดิมตั้งใจให้กองอาสา แต่เจ้าใช้ประโยชน์ได้ดีกว่า" },
        required = { [248003] = { "34:167911769:1060888803", "เวทแห่งผืนดินสำหรับพ่อมดน้อยผู้ใฝ่รู้" }, [248004] = { "47:1661445634:178075828", "คู่มือเวทอาร์เคน ฉบับอธิบายเรื่องเวทง่าย ๆ" } },
        steps = { { "34:167911769:1060888803", "เวทแห่งผืนดินสำหรับพ่อมดน้อยผู้ใฝ่รู้" }, { "47:1661445634:178075828", "คู่มือเวทอาร์เคน ฉบับอธิบายเรื่องเวทง่าย ๆ" } },
    },
    [92124] = { -- Book Inventory
        title = { "14:1819982165:718247358", "ตรวจนับหนังสือ" },
        objective = { "59:2041181121:654205682", "คุยกับ Daniel ผู้ช่วย Brother Paxton ในห้องสมุด" },
        description = { "392:1038110250:838576900", "ต้องตรวจว่าหนังสือหายกี่เล่ม!\n\nไปคุยกับผู้ช่วยไร้ประโยชน์ Daniel เขาตรวจคร่าว ๆ แล้วบอกว่าปัญหาร้ายแรงเพียงใดได้\n\nเด็กนั่นหมกมุ่นวิชาชีพต่าง ๆ ใน Elwynn Forest สนใจแต่เรื่องนั้นแทนงานช่วยข้าที่สำคัญ\n\nอย่าปล่อยให้พล่ามเรื่องวิชาชีพ จงหาว่าเกิดอะไรกับหนังสือ!" },
        completion = { "405:816978059:1071833459", "ใช่ ข้าได้ยินแล้ว เตือน Brother Paxton สามครั้งเรื่องโคโบลด์ขุดใต้ฐานวิหาร\n\nดูเหมือนเอาหนังสือไปมาก ชั้นว่างทั้งชั้น ควรถาม Brother Paxton ว่าอยากให้ทำอะไร\n\nไหน ๆ มาแล้ว ให้ข้าคุยเรื่องวิชาชีพได้ไหม? ยินดีตอบคำถามหรือชี้อาจารย์ท้องถิ่นให้" },
    },
    [99127] = { -- A Net Disaster
        title = { "14:821441298:768374323", "หายนะในกับดักปลา" },
        objective = { "40:1675392973:1221473102", "ตรวจดูกับดักปลาใน Crystal Lake" },
        description = { "307:1177236689:1525313817", "วันนี้ปลาไม่กินเบ็ด และมีบางอย่างผิดปกติ ไม่ใช่แค่เบ็ดว่าง ข้าไม่เห็นแม้ปลาซิวสักตัวในน้ำ\n\nLee ตั้งกับดักไว้เมื่อคืน ไปดูว่ายังพอมีปลาไหม หากพบอะไรแปลก นำให้ข้าดูด้วย", variants = { { "307:1795693940:1513274888", "วันนี้ปลาไม่กินเบ็ด และมีบางอย่างผิดปกติ ไม่ใช่แค่เบ็ดว่าง ข้าไม่เห็นแม้ปลาซิวสักตัวในน้ำ\n\nLee ตั้งกับดักไว้เมื่อคืน ไปดูว่ายังพอมีปลาไหม หากพบอะไรแปลก นำให้ข้าดูด้วย" } } },
        progress = { "24:1358660348:1347955620", "มีปลาอะไรจับได้บ้าง?" },
        completion = { "165:1257759260:1955728988", "กับดักทุกอันเป็นเช่นนี้หรือ? เพื่อนบ้านน่ารำคาญใหม่คงทำลายมากกว่าที่รู้ หากไม่ทำอะไร ข้าจะหมดตัว", variants = { { "164:994355164:1032270534", "ตาข่ายทุกผืนเป็นแบบนี้เลยหรือ? เพื่อนบ้านน่ารำคาญใหม่คงทำลายมากกว่าที่รู้ หากไม่ทำอะไร ข้าจะหมดตัว" } } },
        required = { [286205] = { "15:1636173689:1729507616", "ปลาที่ถูกกินไปครึ่งตัว" } },
        steps = { { "15:1636173689:1729507616", "ปลาที่ถูกกินไปครึ่งตัว" } },
    },
    [99128] = { -- Slimy Menace
        title = { "12:1909591774:1480416147", "ภัยลื่นเมือก" },
        objective = { "33:1918935643:273433559", "ฆ่าเมอร์ล็อกที่ Crystal Lake", amount = { "5:409775429:850574908 W1 13:411107774:2094466667 W2 67:447559108:809072069", "สังหาร Murloc {world1} ตัว และ Murloc Streamrunner {world2} ตัวที่ Crystal Lake แล้วกลับไปหา Jason Mathers" } },
        description = { "292:1650791881:761611896", "คงเป็นฝีมือเมอร์ล็อกอีกฝั่งทะเลสาบ สัตว์เล็กน่าขยะแขยง อารมณ์ดุร้ายกับฟันก็เหมาะกัน\n\nหากปล่อยต่อ ทะเลสาบนี้คงไม่เหลือปลาให้พูดถึง ช่วยกำจัดบางส่วนจะช่วยข้ามาก" },
        progress = { "14:351938725:1644227353", "มันตายหรือยัง?" },
        completion = { "166:1736365256:105443002", "ได้ยินเสียงร้องจากตรงนี้... คงตามไปในฝันร้าย เอาล่ะ คงทำให้ช้าลง แม้มั่นใจว่าจะเพิ่มจำนวนกลับเร็ว", variants = { { "166:2057277148:2079513072", "ได้ยินเสียงร้องจากตรงนี้... คงตามไปในฝันร้าย เอาล่ะ คงทำให้ช้าลง แม้มั่นใจว่าจะเพิ่มจำนวนกลับเร็ว" } } },
        objectiveLabels = {
            monster = { ["Murloc slain"] = "ปราบ เมอร์ล็อก", ["Murloc Streamrunner slain"] = "ปราบ เมอร์ล็อกนักวิ่งริมลำธาร" },
        },
    },
    [99129] = { -- A Man About a Murloc
        title = { "20:177405085:160679485", "คนรู้เรื่องเมอร์ล็อก" },
        objective = { "58:514371638:1230488408", "คุยกับ Remy \"Two Times\" เรื่องปัญหาเมอร์ล็อกของ Jason" },
        description = { "263:267489501:1282921730", "Remy พูดถึงเมอร์ล็อกวันก่อน... มั่นใจว่าเกลียดตัวแสบพอกับข้า\n\nเขาอาจมีวิธีกันมันจากปลาในอนาคต ขอให้ไปคุยว่าคิดอะไรออกบ้าง" },
        completion = { "178:1764330216:1485960300", "ข้าเตือนยามเรื่องเมอร์ล็อกแล้ว แต่ไม่ฟัง\n\nมีความคิดหลายอย่างเอาคืนเจ้าสัตว์พวกนั้น แต่ต้องให้เจ้าช่วยหาของที่ใช้" },
    },
    [99130] = { -- An Enticing Offer
        title = { "17:244218908:2086032249", "ข้อเสนอชวนลิ้มลอง" },
        objective = { "36:92779078:1602538859", "เก็บส่วนผสมสำหรับเหยื่อเมอร์ล็อก", amount = { "8:1089852795:1107240600 W1 27:1793613293:1590080525 W2 79:1006270949:1945391158", "เก็บ Vial of Animal Blood {world1} ขวด และ Duskweed Petal {world2} ชิ้นเพื่อทำเหยื่อเมอร์ล็อก แล้วกลับไปหา Remy “Two Times” ที่ Goldshire" } },
        description = { "425:1492212233:1975136383", "ข้ามีวิธีจัดการเมอร์ล็อกหลายอย่าง วิธีหนึ่งช่วยคนอื่นด้วย\n\nวัชพืชตามไร่แถวนี้ชื่อ Duskweed กลีบปริมาณมากเป็นพิษต่อสัตว์ส่วนใหญ่ หากใช้ทำเหยื่อเมอร์ล็อก หวังว่าจะสอนให้มันอยู่ห่าง\n\nชาวนาก็ได้กำจัดวัชพืชไปด้วย ได้ประโยชน์ทั้งคู่จริง ๆ... ทั้งคู่จริง ๆ" },
        progress = { "16:1022263219:1297075481", "พบครบหรือยัง?" },
        completion = { "148:1001246688:1989815371", "ขอสักครู่...\n\nเป็นเหยื่อง่าย ๆ หากไม่มีสัตว์เลี้ยงใครมากินก็น่าจะปลอดภัย แค่บอก Jason ว่าอย่ากิน" },
        required = { [286215] = { "20:616863479:1132540436", "ขวดบรรจุเลือดสัตว์" }, [286214] = { "14:1799424013:1200372289", "กลีบดอก Duskweed" } },
        steps = { { "20:616863479:1132540436", "ขวดบรรจุเลือดสัตว์" }, { "14:1799424013:1200372289", "กลีบดอก Duskweed" } },
    },
    [99131] = { -- Baited for Success
        title = { "18:503832599:1028644232", "เหยื่อนำสู่ความสำเร็จ" },
        objective = { "24:1954351881:425736579", "กลับไปหา Jason Mathers" },
        description = { "197:2030587613:1344657479", "บอก Mathers ว่ามารับเหยื่อได้ภายหลังวันนี้ ข้าจะอธิบายวิธีใช้ให้\n\nหวังว่าจะขายปลาได้อีกเร็ว ๆ นี้ และโลกเราจะมีเมอร์ล็อกน้อยลง" },
        completion = { "113:2014401141:464154697", "เหยื่อพิษหรือ? ตราบใดที่ปลาไม่กิน ก็น่าจะใช้ได้ ข้าจะไปรับจาก Remy ภายหลัง" },
    },
    [99143] = { -- Bottles and Baubles
        title = { "19:887625713:1374708287", "ขวดและของแวววาว" },
        objective = { "59:1226069111:362763578", "เก็บของขยะวาว ๆ 6 ชิ้น จากค่ายเมอร์ล็อกใกล้ ๆ", amount = { "8:1089852795:1107240600 W1 50:163868833:2023056441", "เก็บของขยะวาว ๆ {world1} ชิ้น จากค่ายเมอร์ล็อกใกล้ ๆ" } },
        description = { "229:916855000:715023799", "มนุษย์ปลาต้องคิดเหมือนปลาจริง ๆ ใช่ไหม? งั้นสิ่งที่มันชอบ ปลาก็คงชอบ!\n\nหากค้นขยะแล้วเอาของที่ดูเหมาะทำเหยื่อกลับมา ข้าจะให้รางวัล" },
        progress = { "40:1346355672:717156574", "พบอะไร? มีของน่าสนใจไหม?" },
        completion = { "157:978937062:1656462150", "ของชุดนี้น่าสนใจ คงใช้ได้!\n\nนี่อุปกรณ์เก่าของข้า น่าจะช่วยคนเริ่มต้นตกปลาได้" },
        required = { [286209] = { "10:509825042:1810621632", "ของขยะวาว ๆ" } },
        objectiveLabels = {
            item = { ["Shiny Junk"] = "ของขยะวาว ๆ" },
        },
    },
    [863] = { -- The Escape
        title = { "10:1720783701:1462715557", "ลอบหนี" },
        objective = { "89:476766236:1834590429", "คุ้มกัน Wizzlecrank และเครื่องตัดไม้ก็อบลินที่ขโมยมา ระหว่างเดินทางไปหา Sputtervalve ใน Ratchet" },
        description = { "127:1257824501:1443099046", "คงต้องเรียนรู้ระหว่างทาง... ไม่น่ายากนักหรอก แค่ปุ่มตรงนี้ แล้วก็คันโยกอีกสักอันสองอัน... เอาละ พร้อมไปหรือยัง?" },
        progress = { "15:1285031552:843897474", "ให้ข้าช่วยอะไรไหม?" },
        completion = { "234:930426417:2046549853", "หวังว่าเราจะได้อะไรที่มีประโยชน์จากซากเครื่องตัดไม้ต้นแบบบ้าง... ข้าเหลือเวลาไม่มากแล้ว! จะส่งทีมกู้ซากไปยังจุดที่ Wizzlecrank อยู่ทันที\n\nอ้อ ให้ข้ามอบอะไรตอบแทนที่เจ้าช่วยด้วย" },
        objectiveLabels = {
            event = { ["Escort Wizzlecrank out of the Venture Co. drill site"] = "คุ้มกัน Wizzlecrank ออกจากจุดขุดเจาะของ Venture Co." },
        },
    },
    [8499] = { -- The Alliance Needs Thorium Bars!
        title = { "32:22085184:709537905", "อัลไลแอนซ์ต้องการแท่งทอเรียม!" },
        objective = { "74:1509396883:1938099234", "นำ Thorium Bars 20 แท่งไปให้ Dame Twinbraid ที่ Military Ward ใน Ironforge" },
        description = { "469:1302287974:2129647165 C 1:63:63", "ใจดีเหลือเกินที่เจ้าถามถึงสิ่งที่อัลไลแอนซ์ต้องการ นอกเหนือจากการรวบรวมของอื่นที่กำลังดำเนินอยู่ เรายังต้องการแท่งทอเรียมจำนวนมาก ซึ่งเป็นงานที่ข้ารับผิดชอบ ทอเรียมจะใช้ผลิตสิ่งของมากมายสำหรับสงคราม ที่สำคัญที่สุดคือการสร้างกองพันรถถังไอน้ำ ซึ่งจะขนส่งทางอากาศไปซิลิธัสทันทีที่สร้างเสร็จ เจ้าช่วยเราในงานนี้ได้ไหม {class}?" },
        progress = { "75:1405412179:1262586126", "โอ้ ของส่งจากพี่น้องข้าหรือ? เยี่ยม! วันนี้โชคเข้าข้างจริง ๆ!" },
        completion = { "68:1560359670:2030082692", "งั้น Gnoarn ก็ไม่ไว้ใจความสามารถลาดตระเวนของข้าหรือ? สงสัยจังว่าเพราะอะไร..." },
        required = { [12359] = { "11:2096858940:1132233669", "แท่งทอเรียม" } },
        steps = { { "11:2096858940:1132233669", "แท่งทอเรียม" } },
    },
    [170] = { -- A New Threat
        title = { "12:865036025:1414162342", "ภัยคุกคามใหม่" },
        objective = { "80:610471865:991879073", "Balir Frosthammer ต้องการให้เจ้าฆ่า Rockjaw Troggs 6 ตัว และ Burly Rockjaw Troggs 6 ตัว" },
        description = { { "38:1341614955:475016852 C 442:2016506125:395613455", "38:1341614955:475016852 C 442:518856084:1585149360" }, "หวังว่าเจ้ามาช่วย {class} หลังโทรกก์โจมตีครั้งล่าสุด เราต้องการความช่วยเหลือทุกอย่าง\n\nได้ยินว่าพวกมันโผล่ทั่วดินแดน Coldridge Valley ก็ไม่เว้น พบตามเนินตะวันออกเฉียงใต้และใกล้ทะเลสาบน้ำแข็ง\n\nไม่เพียงเท่านั้น ไม่กี่คืนก่อนมันบุกยึดค่ายทางตะวันตก!\n\nเราขาดคน ต้องการแขนแข็งแรงช่วยไล่โทรกก์กลับไป", variants = { { "38:1341614955:475016852 C 441:408918015:682364890", "หวังว่าเจ้ามาช่วยเรานะ {class} หลังโทรกก์บุกครั้งล่าสุด ใครช่วยได้เราก็ยินดีทั้งนั้น\n\nได้ยินว่าพวกมันโผล่ไปทั่ว และ Coldridge Valley ก็ไม่เว้น มีคนเห็นพวกมันตามเนินทางตะวันออกเฉียงใต้กับแถวทะเลสาบน้ำแข็ง\n\nเท่านั้นยังไม่พอ เมื่อไม่กี่คืนก่อนพวกมันบุกยึดค่ายทางตะวันตกของเราด้วย!\n\nเราขาดคนอยู่ เจ้าหนุ่ม เราต้องการคนแข็งแรงมาช่วยขับไล่โทรกก์กลับไป" } } },
        progress = { "38:1472858400:844168565", "เจ้าตัวแสบพวกนี้ดื้อด้านจริงใช่ไหม?" },
        completion = { "242:605894762:1884641551", "หากปัญหาที่นี่บอกถึงสิ่งที่เกิดที่อื่นในดินแดนเรา ในนามเคราของ Magni ข้างหน้าคงมีปัญหาใหญ่! ได้แต่หวังว่าราชากับวุฒิสภากำลังรับมือภัยโทรกก์" },
        objectiveLabels = {
            monster = { ["Rockjaw Trogg slain"] = "ปราบ โทรกก์ Rockjaw", ["Burly Rockjaw Trogg slain"] = "ปราบ โทรกก์ Rockjaw ร่างกำยำ" },
        },
    },
    [182] = { -- The Troll Cave
        title = { "14:1269690429:1302108437", "ถ้ำโทรลล์" },
        objective = { "67:1487782947:1669189421", "Grelin Whitebeard ต้องการให้เจ้าฆ่า Frostmane Troll Whelps 14 ตัว" },
        description = { "503:913191962:1992013711", "ข้ากับ Senir พี่น้องชาย ถูกส่งไปคนละส่วนของ Dun Morogh เพื่อสำรวจภัยโทรลล์ วุฒิสภายุ่งกับโทรกก์อยู่แล้ว ไม่ต้องการเรื่องกวนใจเพิ่ม\n\nเท่าที่เห็น โทรลล์ใน Coldridge Valley ยังตั้งตัวไม่มั่น ส่วนใหญ่อยู่ถ้ำใต้ คงไม่ต้องใช้กองทัพ แรงแข็งขันไม่กี่คนก็เกินพอ\n\nสนใจช่วยไหม? ข้ามีอำนาจให้ค่าตอบแทน" },
        progress = { "145:271119240:383084250 N 1:46:46", "เท่าที่รู้ โทรลล์เหล่านี้มาจากเผ่า Frostmane เกรงว่าไม่รู้อะไรที่ช่วยเจ้าได้มากกว่านี้ {name}" },
        completion = { "207:131198283:1446503874", "อ๊าก! โทรลล์บ้าพวกนั้น!\n\n<เขาสูดหายใจหลายครั้ง ดูสงบลง... นิดหน่อย>\n\nพวกมันมากลางคืน ขโมยสมุดบันทึก! รู้อยู่แล้วว่าไม่ควรเชื่อใจเจ้าฝึกหัดไร้ประโยชน์..." },
        objectiveLabels = {
            monster = { ["Frostmane Troll Whelp slain"] = "ปราบ โทรลล์ Frostmane วัยอ่อน" },
        },
    },
    [218] = { -- The Stolen Journal
        title = { "18:941065303:461615242", "สมุดบันทึกที่ถูกขโมย" },
        objective = { "80:366164781:483613900", "Grelin Whitebeard ต้องการให้เจ้าฆ่า Grik'nir the Cold และนำสมุดบันทึกของเขาคืน" },
        description = { "249:1487441915:266862099", "สมุดข้า! มันเอาไปถ้ำ ตัวที่ถือ... เป็นตัวใหญ่ มีลายแปลกบนผิวและหน้า เห็นไม่ชัดกว่านั้น\n\nเจ้าจัดการโทรลล์ได้ดี ช่วยเอาคืนให้ข้าได้ไหม?" },
        progress = { "N 11:2005957275:122233192", "{name}! ได้เรื่องบ้างไหม?" },
        completion = { "11:2138623245:698779024 N 259:754361985:1694051519", "เยี่ยม {name}! ขอบใจที่นำสมุดคืน ดูเหมือนโทรลล์ใน Coldridge Valley ควบคุมได้แล้ว ไม่น่าห่วงนัก\n\nเมื่อเขียนรายงานเสร็จ ต้องมีคนนำไปให้ Senir พี่น้องชายข้า" },
        required = { [2004] = { "27:1077327953:1385180724", "สมุดบันทึกของ Grelin Whitebeard" } },
        steps = { { "27:1077327953:1385180724", "สมุดบันทึกของ Grelin Whitebeard" } },
    },
    [233] = { -- Coldridge Valley Mail Delivery
        title = { "30:1403949468:795515316", "ส่งไปรษณีย์ Coldridge Valley" },
        objective = { "46:731711360:1205365214", "ส่งกองจดหมายให้ Talin Keeneye" },
        description = { { "301:1313848483:2009641010", "301:334311084:1629272259" }, "อืม ช่วยข้าหน่อยได้ไหม? วันนี้มีกองจดหมายผ่านช่องเขามา แต่ข้าไม่มีเวลาไปส่ง\n\nทั้งหมดจ่าถึง Talin Keeneye ตามถนนตะวันตกไปจะพบเขาตั้งค่ายข้างทะเลสาบน้ำแข็ง\n\nว่าอย่างไร?", variants = { { "300:391384967:1176970310", "อืม เจ้าหนุ่ม พอจะช่วยอะไรข้าหน่อยได้ไหม? วันนี้มีจดหมายกองหนึ่งส่งผ่านช่องเขามา แต่ข้าไม่มีเวลาเอาไปส่งต่อ\n\nทุกฉบับจ่าถึง Talin Keeneye ตามถนนไปทางตะวันตกจะพบเขาตั้งค่ายข้างทะเลสาบน้ำแข็ง\n\nว่าอย่างไรล่ะ?" } } },
        progress = { "34:549874813:1029307167", "ว่าอย่างไร? มีอะไรให้ข้าหรือ?" },
        completion = { "219:1589801804:478170133", "ขอบใจ รอจดหมายพวกนี้นานแล้ว...\n\nแต่ไม่ใช่ทั้งหมดของข้า ฉบับนี้ถึง Grelin Whitebeard เขาอยู่ไม่ไกล หากเจ้าอยากนำไปส่ง" },
        required = { [2187] = { "18:1279350536:31226424", "จดหมายหนึ่งปึก" } },
        steps = { { "18:1279350536:31226424", "จดหมายหนึ่งปึก" } },
    },
    [234] = { -- Coldridge Valley Mail Delivery
        title = { "30:1403949468:795515316", "ส่งไปรษณีย์ Coldridge Valley" },
        objective = { "40:1379184102:261973153", "ส่งจดหมายให้ Grelin Whitebeard" },
        description = { "114:704897162:2129492019", "ถ้าจำถูก ค่าย Grelin อยู่ตามถนนตะวันออกเฉียงใต้ เขาคงอยากได้จดหมายเต็มที" },
        progress = { "39:1434636018:103319421", "มีอะไรให้ข้าช่วยหรือ?" },
        completion = { "71:991037179:26869411", "อา เยี่ยม นานแล้วไม่ได้ข่าวจาก Ironforge", variants = { { "213:1995107013:1132284134", "อา เยี่ยมเลย ข้าไม่ได้ข่าวจาก Ironforge มานานแล้ว จดหมายจากแม่ทำให้ข้าอบอุ่นใจจริง ๆ เอ้า จะให้เจ้าไม่มีอะไรอ่านก็คงไม่ยุติธรรม เลือกคู่มือที่วางอยู่แถวนี้ไปสักเล่มสิ" } } },
        required = { [2188] = { "29:1133704962:1490466824", "จดหมายถึง Grelin Whitebeard" } },
        steps = { { "29:1133704962:1490466824", "จดหมายถึง Grelin Whitebeard" } },
    },
    [282] = { -- Senir's Observations
        title = { "20:686878845:695577531", "ข้อสังเกตของ Senir" },
        objective = { "30:46169474:1124585168", "คุยกับ Mountaineer Thalos" },
        description = { "451:937521551:1599791528", "ข้าจะให้เด็กฝึกนำรายงานไปให้ Senir แต่คงสบายใจกว่าถ้าอยู่ในมือที่... เชื่อถือได้ หากเจ้าไม่รังเกียจนะ?\n\nอืม ต้องผ่านอุโมงค์ไป Kharanos\n\nคุยกับ Mountaineer Thalos ก่อนเข้าอุโมงค์ ตอนนี้โทรกก์ยึดเต็มแล้ว\n\nตามถนนกลับ Anvilmar แล้วมุ่งตะวันออกต่อถึงอุโมงค์ Thalos ประจำอยู่ใกล้ ๆ" },
        progress = { "19:36480204:284387754 N 200:1001804097:1145944991", "สวัสดี! ระวัง {name} อุโมงค์ไป Dun Morogh เต็มไปด้วยโทรกก์ ไม่ปลอดภัย\n\nหากไม่มีธุระด่วน ต้องขอให้อยู่ Anvilmar จนกว่าอุโมงค์ปลอดภัยกว่าเดิม" },
        completion = { "171:1775359568:968399013", "อืม หาก Whitebeard ส่งไปทำธุระสำคัญใน Dun Morogh ก็คงห้ามไม่ได้สินะ?\n\nอย่างน้อยให้ข้าแนะนำและบอกทาง" },
        required = { [2619] = { "15:1778779380:567376640", "รายงานของ Grelin" } },
        steps = { { "15:1778779380:567376640", "รายงานของ Grelin" } },
    },
    [287] = { -- Frostmane Hold
        title = { "14:2137086746:730119100", "Frostmane Hold" },
        objective = { "90:439454345:1619691421", "สำรวจ Frostmane Hold และฆ่า Frostmane Headhunters 5 ตัว ให้ Senir Whitebeard ใน Kharanos" },
        description = { "50:1097148786:1224660343 N 423:867890124:733782315", "รายงานข้าล่าช้า ช่วยได้ไหม {name}? เพิ่งพบที่ซ่อนโทรลล์ แต่เห็นมากจนกลัวเข้าไป\n\nต้องการดังนี้... ลงถ้ำ สำรวจข้างใน ฆ่าโทรลล์บางตัว แล้วกลับมา\n\nตามถนนเหนือจาก Kharanos ถึงสะพานแล้วเลียบแม่น้ำแข็งไปตะวันตกจน Iceflow Lake พบ Brewnall Village ฝั่งตะวันตก Hold อยู่ตะวันตกเฉียงใต้ของหมู่บ้าน" },
        progress = { "140:2133946225:877744752", "หาไม่พบหรือ? ข้าบอกทางชัดมาก! เวลาไม่มาก รีบเข้า อย่ากลับจนกว่าจะพบถ้ำ" },
        completion = { "4:1110228981:147916455 N 266:2147438819:882473410 N 50:921463200:2121188653", "อา {name}! คิดว่าเจ้าคงหาไม่ยาก ข้าบอกทางยอดเยี่ยม...\n\nขอเขียนรายงานให้เสร็จ\n\n<เขาหยิบกระดาษออกมาเขียนครู่หนึ่ง>\n\nเรียบร้อย! ฮ่า เรื่องน่าขันเสียจริง... {name} จะรังเกียจไหมหากช่วยอีกครั้งสุดท้าย?" },
        objectiveLabels = {
            event = { ["Fully explore Frostmane Hold"] = "สำรวจ Frostmane Hold ให้ทั่ว" },
            monster = { ["Frostmane Headhunter slain"] = "ปราบ นักล่าหัว Frostmane" },
        },
    },
    [291] = { -- The Reports
        title = { "11:846226390:1864485798", "รายงานทั้งหลาย" },
        objective = { "62:1265104825:343957526", "ส่งรายงาน Senir ให้ Senator Barin Redstone ใน Ironforge" },
        description = { "495:1114106375:380936672", "เยี่ยม! นำรายงานให้ Senator Barin Redstone เขาอารมณ์บูด อย่าเก็บท่าทีมาคิด อยู่ Ironforge ในห้องที่ King Magni ออกว่าราชการ\n\nไม่รู้ทางหรือ? ออก Kharanos ไปเหนือ ข้ามสะพาน แล้วตามถนนตะวันออก มีธงใหญ่ขนาบทางขึ้นไหล่เขา\n\nอ้อ ช่วยไม่พูดว่าเจ้าช่วยข้าได้ไหม? จะให้คิดว่าข้าไม่ทำงานหนักที่นี่ไม่ได้!" },
        progress = { "125:1314132621:2082787848", "อืม... ดูเหมือนยามข้าเลือกผู้เข้ายื่นคำร้องน้อยลง เอาล่ะ ต้องการอะไร ว่ามาเร็ว ๆ" },
        completion = { "296:1524458985:1747270650", "<เขาอ่านรายงานอย่างรวดเร็ว>\n\nอำนาจของราชาหรือ!? Magni เสียสติหมดแล้วหรือ! Whitebeard บ้านั่น... จัดการเองแล้วสินะ? วุฒิสภาจะไม่พอใจ ไม่พอใจเลย!\n\nอะไร ยังอยู่หรือ? ไป ก่อนเรียกยาม!" },
        required = { [2628] = { "14:842403323:909266207", "รายงานของ Senir" } },
        steps = { { "14:842403323:909266207", "รายงานของ Senir" } },
    },
    [308] = { -- Distracting Jarven
        title = { "18:1384392596:1752593031", "เบี่ยงเบนความสนใจ Jarven" },
        progress = { "177:2069714804:1251285182", "ฮึ! เหล้ามากมายที่นี่ แต่ข้าได้รับคำสั่งห้ามแตะ หากได้ชิม Thunder Ale สักหน่อย... จะช่วยให้หัวไว ไม่ได้โกหก!" },
        completion = { "28:1352473244:1784104105 N 1:33:33", "ให้ข้าหรือ? เจ้าคือวีรบุรุษแท้ {name}!" },
        description = { "177:2069714804:1251285182", "ฮึ! เหล้ามากมายที่นี่ แต่ข้าได้รับคำสั่งห้ามแตะ หากได้ชิม Thunder Ale สักหน่อย... จะช่วยให้หัวไว ไม่ได้โกหก!" },
        required = { [2686] = { "11:697362248:626247572", "เอลสายฟ้า" } },
        objectiveLabels = {
            item = { ["Thunder Ale"] = "เอลสายฟ้า" },
        },
    },
    [310] = { -- Bitter Rivals
        title = { "13:1131816947:1406279647", "คู่แข่งรสขม" },
        objective = { "127:1493433466:911259248", "ในห้องใต้ดิน Thunderbrew Distillery ที่ Kharanos ให้สลับถัง Thunder Ale ด้วย Barrel of Barleybrew Scalder" },
        description = { "474:312707029:415326427", "ยอมรับว่า Thunderbrew ทำเครื่องดื่มดี แต่ต้องรู้ว่าของตนไม่ใช่สูตรดีเพียงอย่างเดียว! เจ้าช่วยสอนได้...\n\nนี่ ถัง Barleybrew Scalder ลอบเข้าห้องใต้ดิน Thunderbrew Distillery ใน Kharanos แล้วสลับกับถัง Thunder Ale จะดูว่าลูกค้าชอบของข้าเทียบกับของเขาอย่างไร!\n\nหากมีคนเฝ้า อาจต้องเบี่ยงเบนความสนใจยาม...", variants = { { "473:812670292:118161718", "ยอมรับว่า Thunderbrew ทำเครื่องดื่มดี แต่ต้องรู้ว่าของตนไม่ใช่สูตรดีเพียงอย่างเดียว! เจ้าช่วยสอนได้...\n\nนี่ ถัง Barleybrew Scalder ลอบเข้าห้องใต้ดิน Thunderbrew Distillery ใน Kharanos แล้วสลับกับถัง Thunder Ale จะดูว่าลูกค้าชอบของข้าเทียบกับของเขาอย่างไร!\n\nหากมีคนเฝ้า อาจต้องเบี่ยงเบนความสนใจยาม..." } } },
        progress = { "56:1632622423:1355027272", "วันที่บนถังบอกว่าใกล้จะถูกเปิดดื่ม" },
        completion = { "87:2101584228:347506327", "เจ้ารีบวางถัง Barleybrew Scalder ของ Marleth ไว้ในกลุ่มถัง Thunderbrew" },
        required = { [2548] = { "28:1088689458:414317233", "ถังเบียร์ Barleybrew Scalder" } },
        steps = { { "28:1088689458:414317233", "ถังเบียร์ Barleybrew Scalder" } },
    },
    [311] = { -- Return to Marleth
        title = { "17:689717036:352386409", "กลับไปหา Marleth" },
        objective = { "78:104770:2131949917", "นำถัง Thunder Ale ไปให้ Marleth Barleybrew ที่ Brewnall Village" },
        description = { "139:624569295:532326430", "เมื่อวางถัง Scalder ของ Marleth ในห้องใต้ดินโรงกลั่น Kharanos เจ้าก็หยิบ Thunder Ale มาถังหนึ่งเป็นหลักฐาน..." },
        progress = { "24:748003687:153474849", "สลับแล้วหรือ?" },
        completion = { "9:1775424254:365803329 N 156:1627921513:1646559031", "ไม่เลว {name}! ผ่านยามยากไหม?\n\nไม่สำคัญ ขอบใจมาก หากต้องการสเตาต์แรง ๆ อย่าลืม Barleybrew!", variants = { { "9:1775424254:365803329 N 155:187370647:836373821", "ไม่เลว {name}! ผ่านยามยากไหม?\n\nไม่สำคัญ ขอบใจมาก หากต้องการสเตาต์แรง ๆ อย่าลืม Barleybrew!" } } },
        required = { [2666] = { "21:851404048:222694833", "ถังเบียร์ Thunder Ale" } },
        steps = { { "21:851404048:222694833", "ถังเบียร์ Thunder Ale" } },
    },
    [312] = { -- Tundra MacGrann's Stolen Stash
        title = { "30:2125513059:1278583643", "คลังเสบียงที่ถูกขโมยของ Tundra MacGrann" },
        objective = { "90:497503225:1909004440", "นำเนื้อแห้งของ Tundra MacGrann คืนจากตู้เก็บเนื้อที่ถูกขโมยในถ้ำ Old Icebeard" },
        description = { "472:1757407853:1755722060", "ข้าหมักเกลือเนื้อแห้งพอกินเดือนหนึ่ง ล็อกไว้รับหน้าหนาว กันหมีเอาไป! แต่ตอนออกล่ากวาง Old Icebeard ขโมยตู้เนื้อ มันคงทุบทะลุทอเรียมไม่ได้หรอก แต่ข้าจะอดตายหากไม่ได้เนื้อคืน\n\nเจ้าดูย่องเบากว่าข้า ช่วยเอาคืนได้ไหม? ขาข้าเจ็บแบบนี้คงเข้าออกถ้ำเร็วพอไม่ไหว" },
        progress = { "42:344198047:1107535282 N 1:63:63", "เข้าถึงตู้เนื้อได้ไหม {name}?" },
        completion = { "26:1864908758:452728919 N 92:92528203:1759844549", "เจ้าช่างมีน้ำใจ {name}! เพราะความกล้า ข้าจะไม่อดตายเมื่อพายุหิมะหน้าหนาวมา" },
        required = { [2667] = { "22:531205411:1450471871", "เนื้อแห้งของ MacGrann" } },
        steps = { { "22:531205411:1450471871", "เนื้อแห้งของ MacGrann" } },
    },
    [313] = { -- The Grizzled Den
        title = { "16:430941066:311997500", "Grizzled Den" },
        objective = { "57:384781213:1621213528", "เก็บ Wendigo Manes 8 ชิ้น แล้วนำไปให้ Pilot Stonegear" },
        description = { "382:1172077731:1793329519", "ขับเครื่องจักรล้อมเมืองไม่ใช่งานทุกคน ต้องมือแกร่งกับใจเหล็ก... โชคดีข้ามีทั้งสอง! เจ้าเล่า ใจสู้แค่ไหน อยากพิสูจน์ไหม?\n\nเอาล่ะ... อยากให้ Trollplow ของข้าสบายขึ้น หาแผงคอเวนดิโกจาก Grizzled Den ทางตะวันตกของ Kharanos ให้หน่อย มันทำพรมปูดาดฟ้าภายในได้ดี!" },
        progress = { "5:140209925:2105781119 N 61:43825699:397054231", "ว่าไง {name} ไป Grizzled Den หรือยัง? เวนดิโกพวกนั้นดุได้เรื่อง" },
        completion = { "61:1427905420:229116702 C 43:756516578:1143425217", "อา ใช่ แผงคอนี้ใช้ได้ดี! ใจเจ้าสู้มาก {class} ข้าว่าเราจะเห็นเจ้าทำสิ่งยิ่งใหญ่" },
        required = { [2671] = { "12:1927439207:302593756", "แผงคอเวนดิโก" } },
        steps = { { "12:1927439207:302593756", "แผงคอเวนดิโก" } },
    },
    [314] = { -- Protecting the Herd
        title = { "19:445999297:1436751650", "ปกป้องฝูงแกะ" },
        objective = { "85:2137346319:1645913798", "Rudra Amberstill ต้องการให้เจ้าฆ่า Vagash และนำเขี้ยวไปให้นางที่ฟาร์มแกะ" },
        description = { "484:269817339:1918008916", "เราได้ยินเสียงร้องกลางคืน เช้านี้ฝูงหายไปสองตัวจริง ๆ สัตว์ชั่ว Vagash ล่าเครื่องเลี้ยงชีพเรา ทหาร King Magni ส่วนใหญ่ไปรบดินแดนไกลกับ Alliance จึงไม่มีใครกันมัน\n\nบางทีเจ้ากล้าพอหามันแล้วฆ่า นำเขี้ยวมาชิ้นหนึ่ง ข้าจะให้รางวัล Vagash ซ่อนอยู่เหนือฟาร์ม แต่ระวัง มันอันตรายถึงตาย" },
        progress = { "79:1936584006:1267906024", "Vagash ยังคุกคามฝูง! โปรดช่วยฆ่าสัตว์ร้ายนั่น" },
        completion = { "186:599492077:1523367660", "ทำได้ดีมาก! Veron คงยินดีที่ได้ข่าว ฆ่า Vagash ไม่ง่าย วันหนึ่งเจ้าคงรบเคียงทหาร King Magni ที่แนวหน้า Alliance" },
        required = { [3627] = { "14:52329949:496981040", "เขี้ยวของ Vagash" } },
        steps = { { "14:52329949:496981040", "เขี้ยวของ Vagash" } },
    },
    [315] = { -- The Perfect Stout
        title = { "17:546539231:1174068308", "สเตาต์สมบูรณ์แบบ" },
        objective = { "66:1038895908:975339089", "นำ Shimmerweeds 6 ชิ้น ไปให้ Rejold Barleybrew ที่ Brewnall Village" },
        description = { "475:1030280570:2027572944", "ข้าตามหาสเตาต์สมบูรณ์แบบ รู้ว่าทำได้ การหมักอยู่ในสายเลือด แค่หาสูตรเหมาะ...\n\nโทรลล์ Frostmane ปลูก Shimmerweed บนเนินสูงทางตะวันออก ใช้ทำพิธีประหลาด คนแคระยังไม่ค่อยใช้ แต่มันรสเฉพาะ... อยากทดลองในสูตรข้า!\n\nเอาจาก Frostmane Seers หรือฉกจากตะกร้า Shimmerweed ของโทรลล์" },
        progress = { "133:707691965:1581717333", "มี Shimmerweed หรือยัง? เกือบเตรียมสเตาต์ชุดหนึ่งพร้อม อยากลองใส่พืชลงส่วนผสม" },
        completion = { "112:731963400:377840454", "เยี่ยม! อยากใช้กับสูตรเต็มที มีสูตรหนึ่งคิดว่าเหมาะมาก..." },
        required = { [2676] = { "11:1130679390:1386144522", "สมุนไพร Shimmerweed" } },
        steps = { { "11:1130679390:1386144522", "สมุนไพร Shimmerweed" } },
    },
    [317] = { -- Stocking Jetsteam
        title = { "17:234097765:1093987136", "เตรียมเสบียง Jetsteam" },
        objective = { "110:895460661:1796942204", "เก็บ Chunks of Boar Meat 4 ชิ้น และ Thick Bear Furs 2 ผืน แล้วส่งให้ Pilot Bellowfiz ที่ Steelgrill's Depot" },
        description = { "389:36257685:925567388", "กำลังเตรียมภารกิจยาวให้ Siege Brigade ต้องบรรทุกเสบียงเดือนหนึ่งบน Jetsteam ระหว่าง Steelgrill ซ่อมรถถัง ช่วยล่าสัตว์ได้ไหม?\n\nต้องใช้ขนสัตว์ปูที่นอนกับเนื้อหมูป่าเป็นอาหาร เอาเนื้อจากหมูป่าและขนจากหมี พบทั้งสองในทุ่งหิมะใต้ Grizzled Den" },
        progress = { "51:1473281481:951312690", "เตรียมการไปได้ดี การล่าเจ้าเป็นอย่างไร?" },
        completion = { "61:956312808:437914054 N 1:46:46", "ในนามเครา Magni เจ้าล่ามาไม่น้อย!! ขอบใจ {name}" },
        required = { [769] = { "18:403259379:436492272", "เนื้อหมูป่าชิ้นหนึ่ง" }, [6952] = { "14:314387041:903255739", "ขนหมีหนา" } },
        steps = { { "18:403259379:436492272", "เนื้อหมูป่าชิ้นหนึ่ง" }, { "14:314387041:903255739", "ขนหมีหนา" } },
    },
    [318] = { -- Evershine
        title = { "9:948422227:67269404", "Evershine" },
        objective = { "67:10285409:400869933", "รับถัง Evershine จาก Rejold Barleybrew ที่ Brewnall Village" },
        description = { "456:37157876:1723306920", "Rejold Barleybrew ชอบทดลองเครื่องดื่ม บ้างอร่อย บ้างไม่ดี บ้าง... ทำให้คนแคระทุกคนยกเว้นพวกคอแข็งที่สุดล้มราบ\n\nเขาอยู่ Brewnall Village ทางตะวันตกของ Kharanos ข้าอยากได้ Evershine ช่วยอุ่นระหว่างทางหนาว\n\nและ... มันเผาไหม้ร้อนจนโยนเข้าเตา Jetsteam เพื่อเร่งพลังได้! วิธีเล็ก ๆ นี้พาข้าพ้นอันตรายมาหลายครั้ง" },
        completion = { "53:874794454:1167982272", "Bellowfiz ต้องการ Evershine หรือ? อืม... ได้" },
    },
    [319] = { -- A Favor for Evershine
        title = { "21:1200448968:549457077", "ช่วยงานแลก Evershine" },
        objective = { "121:929775788:763982501", "ฆ่า Ice Claw Bears 6 ตัว, Elder Crag Boars 8 ตัว และ Snow Leopards 8 ตัว แล้วกลับไปหา Rejold Barleybrew ที่ Brewnall Village" },
        description = { "374:1535870276:1658937699", "ข้ามี Evershine ถังหนึ่ง แต่... ช่วยหน่อยได้ไหม? Brewnall Village ต้องการคนช่วยรับมือสัตว์ในหิมะใกล้ ๆ บางครั้งเข้ามาใกล้มาก\n\nเราไม่กลัวหมี แมว หรือหมูป่าหรอก คนแคระที่เคารพตนไม่กลัว แต่หากเจ้าจัดการ เราจะมีเวลาทำงานฝีมือและหมักเครื่องดื่มมากขึ้น" },
        progress = { "42:1524233609:1367541303", "จัดการสัตว์ป่าแล้วหรือยัง?" },
        completion = { "11:1191658970:1224418299 N 97:1329623443:1878797352", "ขอบใจ {name} คงดีที่ทำงานฝีมือโดยได้ยินเสียงคำรามกับพ่นลมนอกหมู่บ้านน้อยลง" },
        objectiveLabels = {
            monster = { ["Ice Claw Bear slain"] = "ปราบ หมีกรงเล็บน้ำแข็ง", ["Elder Crag Boar slain"] = "ปราบ หมูป่าผาหินวัยชรา", ["Snow Leopard slain"] = "ปราบ เสือดาวหิมะ" },
        },
    },
    [320] = { -- Return to Bellowfiz
        title = { "19:1284483884:1194942794", "กลับไปหา Bellowfiz" },
        objective = { "68:1845303588:320342209", "มอบถัง Evershine ให้ Pilot Bellowfiz ที่ Steelgrill's Depot" },
