    },
    [400] = { -- Tools for Steelgrill
        title = { "20:1122954987:1553890760", "เครื่องมือให้ Steelgrill" },
        objective = { "48:1486181720:1973248520", "ส่ง Steelgrill's Tools ให้ Beldin Steelgrill" },
        description = { "492:474164415:1428700185", "Beldin Steelgrill เป็นเจ้าของอู่ท้องถิ่น ช่างเครื่องจักรล้อมเมืองดีที่สุด! แต่ใช้เครื่องมือโหด ข้าว่าทำ Arclight Spanners พังแทบมากกว่าที่ส่งให้ทัน!\n\nเราเพิ่งจัดของตามสั่งล่าสุด หากนำไปส่ง เขาคงตอบแทนคุ้ม\n\nSteelgrill's Depot อยู่ตะวันออกเฉียงเหนือของ Kharanos นักขับเครื่องล้อมเมืองเก๋ามารวมตัว ฟังหาโอกาสทำงานไว้ด้วย" },
        progress = { "284:1558662823:1395162517", "อืม? ดูเด็กไปหน่อยสำหรับนักขับเครื่องล้อมเมือง แต่ไม่สำคัญ... ต้องการซ่อมอะไรหรือ?\n\nรับบัตรคิวแล้วรอสบาย ๆ ข้าซ่อมเครื่องหลายคัน คงไม่มีเวลารับเพิ่มอีกหลายวัน\n\nหรือมาธุระอื่น...?" },
        completion = { { "219:1726879038:1270754116 N 39:308031583:1490158117", "220:2130715915:362172575 N 39:308031583:1490158117" }, "มีเครื่องมือข้าหรือ? ทำได้ดี! ประแจเขี้ยวเฟืองอันสุดท้ายเพิ่งพังเมื่อชั่วโมงก่อน ต้องใช้ซ่อมเครื่องล้อมเมือง Pilot Stonegear เจ้าช่วยมากที่ขนมา {name}\n\nนี่เหรียญสำหรับความช่วยเหลือ" },
        required = { [2999] = { "18:583576344:1879173548", "เครื่องมือของ Steelgrill" } },
        steps = { { "18:583576344:1879173548", "เครื่องมือของ Steelgrill" } },
    },
    [403] = { -- Guarded Thunderbrew Barrel
        title = { "26:1185801842:491486316", "ถัง Thunderbrew ที่มียามเฝ้า" },
        completion = { "114:1173949302:1904850272", "Jarven Thunderbrew เฝ้าถังเบียร์นี้ ตราบใดที่อยู่ในห้องใต้ดิน ห้ามแตะต้องถังใด" },
    },
    [412] = { -- Operation Recombobulation
        title = { "25:2111409311:1988056170", "ปฏิบัติการคืนสภาพ" },
        objective = { "86:411223967:2077320596", "นำ Restabilization Cogs 8 ชิ้น และ Gyromechanic Gears 8 ชิ้น ไปให้ Razzle Sprysprocket ใน Kharanos" },
        description = { "500:361279189:1380802643", "เมื่อวิเคราะห์ Gnomeregan เพิ่ม ดูเหมือนไม่เพียงกำจัดโทรกก์ไม่สำเร็จ แต่ยังเปลี่ยนโนมส่วนใหญ่เป็น leper gnomes น่าสยอง ไร้สติ และทำชั่ว\n\nOzzie กับข้าจะย้อนผลน่ากลัวด้วยสิ่งประดิษฐ์ล่าสุด Recombobulator ใกล้เสร็จแล้ว แต่ขาด Restabilization Cogs กับ Gyromechanic Gears อย่างหนัก ไปเอาจาก leper gnomes หน้า Gnomeregan ให้เรา" },
        progress = { "116:1547664650:2141240656", "Recombobulator จะทำงานทันทีที่มี Restabilization Cogs กับ Gyromechanic Gears พอ" },
        completion = { "316:1520468784:1953010514", "Gyromechanic Gears กับ Restabilization Cogs ตรงแบบ Ozzie ทุกอย่าง เมื่อเติม hydrolubricant ให้ลูกสูบสันดาปภายใน ปรับ crank-o-ratchet และเพิ่มความหนืดเจล electrogum เผ่าโนมก็จะดีเหมือนใหม่" },
        required = { [3083] = { "19:127636070:1345310975", "เฟืองคืนสมดุล" }, [3084] = { "17:1511475210:431211634", "เฟืองกลไกไจโร" } },
        steps = { { "19:127636070:1345310975", "เฟืองคืนสมดุล" }, { "17:1511475210:431211634", "เฟืองกลไกไจโร" } },
    },
    [413] = { -- Shimmer Stout
        title = { "13:918559806:1226673987", "Shimmer Stout" },
        objective = { "59:289378040:252217312", "นำ Barrel of Shimmer Stout ไปให้ Mountaineer Barleybrew" },
        description = { "328:1366516452:1885548044", "อยากให้ Wellart พี่น้องข้าลอง Shimmer Stout ใหม่ เขาเป็น Mountaineer ที่หอยามใต้ หนึ่งในสองหอชายแดน Loch Modan\n\nแม้ไม่ใช่นักหมักเหมือน Barleybrew คนอื่น แต่ชอบดื่ม และรู้ว่าจะชอบสูตรนี้\n\nนำ Barrel of Shimmer Stout ไปให้แทนได้ไหม?" },
        progress = { "7:989913233:66981971 C 159:1636656768:190038933", "สวัสดี {class}! ธุระอะไรพามาไกลถึงนี่?\n\nหวังว่าน่าตื่นเต้น ไม่ได้ต่อสู้ดี ๆ มาหลายวันแล้ว ถังเบียร์นี้ก็ใกล้หมด..." },
        completion = { "142:129949825:704691564", "<Mountaineer Barleybrew ชิม Shimmer Stout...>\n\nโอ้ ว้าว! มันทำให้ตาเป็นประกายจริง รู้สึกเหมือนมองเห็นในมืด!" },
        required = { [3085] = { "23:447888520:1492823533", "เบียร์ Shimmer Stout หนึ่งถังใหญ่" } },
        steps = { { "23:447888520:1492823533", "เบียร์ Shimmer Stout หนึ่งถังใหญ่" } },
    },
    [414] = { -- Stout to Kadrell
        title = { "16:1488675689:1170518961", "สเตาต์ให้ Kadrell" },
        objective = { "54:274350707:268324578", "นำ Cask of Shimmer Stout ไปให้ Mountaineer Kadrell" },
        description = { "435:488950718:718751890", "ข้าดื่ม Shimmer Stout ที่พี่น้องทำเพิ่ม ดีเยี่ยม! อยากให้ Mountaineer อีกคนลอง ชื่อ Kadrell มักลาดตระเวนถนนผ่าน Thelsamar ใน Loch Modan\n\nไป Thelsamar ทางตะวันออกเฉียงใต้ผ่านอุโมงค์ จากนั้นเลี้ยวตะวันออกเฉียงเหนือเมื่อทางแยกเป็นถนน ตามตรงเข้าหมู่บ้าน\n\nให้ถัง Shimmer Stout แก่ Kadrell ดูว่าเขาคิดอย่างไร!" },
        progress = { "11:927657569:725753248 C 27:1058375818:70102181", "สวัสดี {class} ยินดีต้อนรับ Thelsamar!" },
        completion = { "132:1508147417:658591128", "ขอชิม...\n\nเครา Magni! หัวหมุนเลย! แขนขายังเบาด้วย\n\nรู้สึกบินได้!" },
        required = { [3086] = { "21:980003992:1481933167", "เบียร์ Shimmer Stout หนึ่งถังเล็ก" } },
        steps = { { "21:980003992:1481933167", "เบียร์ Shimmer Stout หนึ่งถังเล็ก" } },
    },
    [415] = { -- Rejold's New Brew
        title = { "17:1238246726:2049747067", "สูตรใหม่ของ Rejold" },
        objective = { "29:1577171928:1948889424", "คุยกับ Rejold Barleybrew" },
        description = { "294:990550595:1537211900", "Rejold Barleybrew ที่ Brewnall Village ถามหาเจ้า\n\nอยากคุยสูตรใหม่ที่กำลังหมัก... บอกว่าเจ้าเคยช่วย ควรกลับไปดูว่าเขามีอะไร\n\nอาจมีของดื่มฟรีให้..." },
        completion = { "N 178:381547098:355544247", "{name}! จำ Shimmerweed ที่นำมาได้ไหม? ข้าใช้กับหลายสูตรที่กำลังทำ หนึ่งสูตรออกมายอดเยี่ยม!\n\nนี่ ลองแล้วบอกว่าคิดอย่างไร..." },
    },
    [417] = { -- A Pilot's Revenge
        title = { "17:465143074:1673427895", "การล้างแค้นของนักขับ" },
        objective = { "80:1040588421:1435075504", "ฆ่า Mangeclaw\n\nนำ Mangy Claw และ Hildelve's Journal ไปให้ Pilot Hammerfoot" },
        description = { "332:500429518:164927927", "Hildelve เขียนในสมุดว่าถูก Mangeclaw “หมี Ice Claw ตัวมหึมา” โจมตี เขาไล่ไปได้ แต่ถูกขย้ำร้ายแรงก่อน\n\nดูจากสภาพศพ Mangeclaw คงกลับมาฆ่าในภายหลัง\n\nอย่างไรก็ตาม เขาเขียนความปรารถนาสุดท้ายไว้:\n\nล้างแค้น Mangeclaw" },
        progress = { "7:989913233:66981971 N 41:216345085:1502338732", "สวัสดี {name} มีข่าว Hildelve สหายข้าหรือ?" },
        completion = { "143:2039602982:36992532 N 76:1082272929:1960926084", "ข่าวเศร้า Hildelve เป็นสหายที่ดี ข้าอยากอยู่กับเจ้าตอนพบ Mangeclaw!\n\nขอบใจ {name} เหล่านักขับแห่ง Ironforge Siege Brigade จะจดจำวีรกรรมเจ้า" },
        required = { [3183] = { "10:492833475:2085665748", "กรงเล็บสัตว์ขี้เรื้อน" }, [3117] = { "18:331210580:1858695636", "บันทึกของ Hildelve" } },
        steps = { { "10:492833475:2085665748", "กรงเล็บสัตว์ขี้เรื้อน" }, { "18:331210580:1858695636", "บันทึกของ Hildelve" } },
    },
    [419] = { -- The Lost Pilot
        title = { "14:771864078:1180759464", "นักขับที่หายไป" },
        objective = { "20:1517220566:1803744902", "หา Pilot Hildelve" },
        description = { "477:629317385:557219415 N 11:376958295:219035827", "Mori Hildelve สหายและนักขับเครื่องล้อมเมือง หายในเนินเขา เราหาแร่หายากใช้ทำดินระเบิดชั้นดี ระหว่างค้น เขาขับขึ้นเนินชันจนเครื่องพัง!\n\nยังเชื่อว่าแร่อยู่บนเขา จึงฝากข้าเฝ้าเครื่องแล้วเดินค้นต่อ\n\nผ่านหลายวัน ข้าได้ยินเสียงสัตว์คำรามบนเนินตอนกลางคืน Mori แข็งแกร่ง แต่ข้าห่วง\n\nขอร้อง {name} หาเขาที" },
        completion = { "326:102409702:1240233691", "นี่ศพคนแคระ ถูกขย้ำ แช่แข็ง และสัตว์กินซากบนเขารุมแทะ มือกำหนังสือบันทึกลายหยาบของ Mori Hildelve รอบร่างยังสวม Brigadier's Vest สภาพดีเยี่ยม\n\nฉากสยดสยองนี้คงเป็นที่นักขับเครื่องล้อมเมืองพบจุดจบ" },
    },
    [420] = { -- Senir's Observations
        title = { "20:686878845:695577531", "ข้อสังเกตของ Senir" },
        objective = { "56:1174390869:760574034", "ส่งรายงาน Grelin ให้ Senir Whitebeard ใน Kharanos" },
        description = { "401:232506653:1248869468", "โทรกก์ในอุโมงค์ดุร้ายมาก ไม่ลังเลโจมตีผู้เดินทาง แต่เจ้าดูแกร่งพอ คงปลอดภัย\n\nทางหรือ? หากจะคุย Senir เขาอยู่ Kharanos\n\nผ่านอุโมงค์ออกอีกด้าน แล้วตามถนนต่อ มันพาตรงเข้า Kharanos" },
        progress = { "85:243468365:470103643", "เป็นอย่างไร? ดื่มด้วยกันไหม? อากาศหนาวแบบนี้ไม่มีอะไรให้ทำมากนัก" },
        completion = { "459:2091354185:682103288", "นี่อะไร? อา รายงานพี่น้องข้า อืม...\n\nบอกให้ใช้ชื่อราชาพอประมาณ แต่ไม่ฟัง คงไม่เสียหาย แม้วุฒิสภาจะขุ่นเคืองแน่ แต่พวกนั้นสมควรถูกกวนบ้าง! ฮ่า!\n\nอย่างไรก็ตาม ข้าก็ควรส่งรายงานไป Ironforge เช่นกัน แต่ยอมรับว่าล่าช้า หนาวบ้าเอ๊ย\n\nภายหลังน่าจะมีงานให้ หากสนใจ" },
        required = { [2619] = { "15:1778779380:567376640", "รายงานของ Grelin" } },
        steps = { { "15:1778779380:567376640", "รายงานของ Grelin" } },
    },
    [432] = { -- Those Blasted Troggs!
        title = { "21:841945372:79618321", "โทรกก์บ้าพวกนั้น!" },
        objective = { "75:455150966:1043395675", "ฆ่า Rockjaw Skullthumpers 6 ตัว ให้ Foreman Stonebrow ที่ Gol'Bolar Quarry" },
        description = { "478:2022370187:727779243", "โทรกก์บ้า ทำไซต์ข้าพัง! ดูสิ ถังดินระเบิดหายอีกแล้ว!\n\nโอ๊ย อยากลงไปบิดคอเล็ก ๆ ของมันทุกตัว ฆ่าให้หมด!\n\nความเครียดกับโกรธแบบนี้ไม่ดีต่อสุขภาพ... มันเหลืออะไรให้? ไม่มี!\n\nข้าจะฆ่าเอง แต่ตอนนี้เล็งไม่แม่น! เจ้าลงเหมืองฆ่าเจ้าตัวสกปรก ข้าจ่ายให้! ทำร้ายมัน ฆ่ามัน!" },
        progress = { "27:905214195:1810930043", "โกรธจริง ๆ! ฮึ่ม..." },
        completion = { "101:1307080203:1855437625", "เอาล่ะ รู้สึกดีขึ้นหน่อย...\n\nแต่จะไม่สุขจนตายหมด! ทุกตัว!" },
        objectiveLabels = {
            monster = { ["Rockjaw Skullthumper slain"] = "ปราบ นักทุบกะโหลก Rockjaw" },
        },
    },
    [433] = { -- The Public Servant
        title = { "18:1583374307:344779692", "ผู้รับใช้ประชาชน" },
        objective = { "82:722918877:391037564", "ฆ่า Rockjaw Bonesnappers 10 ตัว ให้ Senator Mehr Stonehallow ที่ Gol'Bolar Quarry" },
        description = { "500:1519798481:723087242", "ในฐานะสมาชิกวุฒิสภาและ Explorers' League ข้ารับหน้าที่จัดการโทรกก์ส่วนนี้ที่ระบาดทั่วแผ่นดิน\n\nมันทำ Gol'Bolar Quarry พังไร้เหตุ ขุดลงลึกแล้วมันทะลักออก ทำลายเครื่องมือไล่คนงาน เราทำได้เพียงกำจัดทั้งหมด สร้างใหม่ แล้วกลับทำงาน\n\nหากช่วย ข้ายินดีจ่ายชดเชยเวลา" },
        progress = { "148:1786644982:1703480223", "หากขับโทรกก์จาก Gol'Bolar Quarry ได้ จะเป็นก้าวแรกจากอีกหลายก้าวเพื่อพ้นภัยนี้" },
        completion = { "216:189308568:1745125683 N 1:46:46", "เป็นการเริ่มต้น หวังว่าฉวยโอกาสส่ง Mountaineers เข้าคุมพื้นที่ แล้วฟื้นระบบงานให้คนเหมืองกลับทำงาน\n\nขอบใจที่ช่วย {name}" },
        objectiveLabels = {
            monster = { ["Rockjaw Bonesnapper slain"] = "ปราบ นักหักกระดูก Rockjaw" },
        },
    },
    [466] = { -- Search for Incendicite
        title = { "22:571576492:585506724", "ตามหา Incendicite" },
        objective = { "66:892884781:1674642768", "นำ Incendicite Ore 6 ชุด ไปให้ Pilot Stonegear ใน Dun Morogh" },
        description = { "490:394729071:1387771529", "ได้ยินว่าแร่หายาก Incendicite พบใน Wetlands ที่ถ้ำตะวันตกเฉียงเหนือของ Algaz Gate มันระเบิดง่าย ใช้ยากโดยไม่ระเบิดตัวเอง แต่หากถลุงถูกวิธี คงทำกระสุนปืนใหญ่ทรงพลัง!\n\nเอาแร่มา ข้าจะหาคนกล้าทดลอง\n\nอ้อ ขุดแร่จากสายแร่ต้องทักษะทำเหมือง หากไม่มี... พาสหายที่มีไปถ้ำด้วย!" },
        progress = { "19:267803207:1809771339 N 2:16224:8286", "แร่อยู่ไหน {name}?!" },
        completion = { "28:1432200561:578022524 N 87:772895603:71558143", "ได้แร่แล้ว! ทำได้ดี {name}! จะให้คนเริ่มทำทันที หวังว่าจะไม่ระเบิดตัวเอง!" },
        required = { [3340] = { "15:34136692:1880680792", "แร่ Incendicite" } },
        steps = { { "15:34136692:1880680792", "แร่ Incendicite" } },
    },
    [467] = { -- Stonegear's Search
        title = { "18:1920086765:1224293086", "การค้นหาของ Stonegear" },
        objective = { "27:748206327:35772517", "คุยกับ Pilot Stonegear" },
        description = { "331:546004447:1513108427", "Pilot Stonegear รักเครื่องล้อมเมืองเหมือนนักขับทุกคนควรทำ! อยากหาวิธีเพิ่มอำนาจยิงรถถังเสมอ!\n\nได้ยินข่าวแร่หายาก กำลังหาคนค้น หากเริ่มอยากออกเดินทาง หา Stonegear ที่ Steelgrill's Depot ใน Dun Morogh ดูว่าต้องการอะไร" },
        completion = { "6:1457790135:951305579 N 66:1261394954:953286015 R 62:790370476:1071701469", "สวัสดี {name} มาเรื่องงานข้าหรือ? ดีที่เห็น{race}รุ่นเยาว์อย่างเจ้าตื่นเต้นกับการผจญภัย!" },
    },
    [2160] = { -- Supplies to Tannok
        title = { "18:289360744:1604794245", "เสบียงถึง Tannok" },
        objective = { "68:1518196272:25068475", "ส่ง Crate of Inn Supplies ให้ Tannok Frosthammer ใน Kharanos" },
        description = { "442:1745118402:225169128", "เฮ้! ดูเป็นนักผจญภัยแข็งแรง หากจะฝ่าช่องเขา ช่วยนำห่อไปโรงเตี๊ยม Kharanos ได้ไหม?\n\nตั้งใจแวะโรงเตี๊ยมอยู่แล้วใช่ไหม? หากผ่านได้ คงอยากพักแน่\n\nเอาให้ Tannok Frosthammer ผู้ช่วยเจ้าของโรงเตี๊ยม ข้าผ่านเองไม่ได้ อีกหลายวันกว่าหน่วยคุ้มกัน Mountaineer จะมา!" },
        progress = { "82:918213769:1755432469", "สวัสดี! เข้ามานั่งข้างไฟ อุ่นตัวด้วยเบียร์เหยือกหนึ่ง" },
        completion = { "172:720858681:765242935 N 78:822838454:266804433", "อา ในที่สุดเสบียง Hands มา! เริ่มห่วง ข่าวจาก Anvilmar น้อยตั้งแต่โทรกก์ยึดช่องเขา\n\nขอบใจที่นำมา {name} พักสบาย ๆ คงเหนื่อยจากเดินทาง" },
        required = { [7646] = { "21:59107561:2006148488", "ลังเสบียงโรงเตี๊ยม" } },
        steps = { { "21:59107561:2006148488", "ลังเสบียงโรงเตี๊ยม" } },
    },
    [3361] = { -- A Refugee's Quandary
        title = { "20:2084213517:94876164", "ปัญหาของผู้ลี้ภัย" },
        objective = { "94:309706100:194239062", "นำ Felix's Box, Felix's Chest และ Felix's Bucket of Bolts ไปให้ Felix Whindlebolt ใน Anvilmar" },
        description = { "485:1764923996:1254118715", "เราขับโทรกก์จาก Gnomeregan แต่ทุกอย่างผิดพลาดน่ากลัว! ตอนนี้บ้านเต็มรังสี โนมกระจัดกระจายทั่ว Dun Morogh\n\nรีบหนีรังสีจนทำของส่วนตัวกับเครื่องมือหาย โทรลล์เอาไป มันขโมยหีบ กล่อง และถังสลักเกลียว! นำกลับค่ายตะวันตกเฉียงใต้ของ Anvilmar\n\nข้าไม่ใช่นักผจญภัย ช่วยหาของแล้วนำมาได้ไหม?" },
        progress = { "12:502075208:2030905537 N 238:716102668:505199003", "โอ้ {name} เมืองนี้ไม่เหมาะกับคนอย่างข้า สัตว์ร้ายมากพอ ๆ กับ Gnomeregan ก่อนอุบัติเหตุ!\n\nมีของข้าหรือยัง? หากไม่มี ใครรู้ว่าโทรลล์ทำอะไรไปแล้ว..." },
        completion = { "153:1670994696:735558860", "ไชโย พบแล้ว! เจ้าช่วยชีวิตจริงสหาย นี่ไม่มาก แต่ตอบแทนปัญหาที่ข้าทำให้ ขอบใจ!" },
        required = { [10438] = { "11:1806427955:1313660262", "กล่องของ Felix" }, [16313] = { "13:663511818:1866554975", "หีบของ Felix" }, [16314] = { "23:1057472546:304982110", "ถังใส่สลักเกลียวของ Felix" } },
        steps = { { "11:1806427955:1313660262", "กล่องของ Felix" }, { "13:663511818:1866554975", "หีบของ Felix" }, { "23:1057472546:304982110", "ถังใส่สลักเกลียวของ Felix" } },
    },
    [3364] = { -- Scalding Mornbrew Delivery
        title = { "26:426784538:1100245492", "ส่ง Mornbrew ร้อนลวก" },
        objective = { "97:1787454979:860893336", "นำ Scalding Mornbrew ไปให้ Durnan Furcutter ใน Anvilmar ก่อนเย็นลงภายในห้านาที!" },
        description = { "438:1635488931:1130369398 N 43:510007380:112928102", "อ๊าก! ควรนำ Mornbrew ร้อนอร่อยไปให้ Durnan Furcutter ใน Anvilmar ตั้งนานแล้ว แต่ต้องส่ง Grelin ก่อน ไปไม่ทันก่อนเย็นแน่!\n\nเจ้าดูไว อาจไปทัน ถ้วยนี้ร้อนอีกแค่ห้านาที Durnan ไม่ได้สั่งแบบ “เย็น” รีบไป Anvilmar อยู่ตะวันออกเฉียงเหนือ เป็นชุมชนขุดในภูเขา\n\nขอบใจ {name} อย่าลืมเอาแก้วคืน!" },
        progress = { "53:909458403:944108869", "ใช่ ข้า Durnan Furcutter มีอะไรให้หรือ?" },
        completion = { "105:2028899272:1893487830", "อา ดี ถูกใจเลย ขอพักสักหน่อยระหว่างเพลิดเพลิน Mornbrew ร้อนลวก!" },
        required = { [10439] = { "26:167692936:679787347", "เบียร์เช้าร้อนจัดของ Durnan" } },
        steps = { { "26:167692936:679787347", "เบียร์เช้าร้อนจัดของ Durnan" } },
    },
    [3365] = { -- Bring Back the Mug
        title = { "18:1180772345:2129397472", "นำแก้วกลับมา" },
        objective = { "37:1171098604:932591770", "คืน Nori's Mug ให้ Nori Pridedrift" },
        description = { "142:1927320934:1226502445 N 70:2056897506:531489591", "ถูกใจจริง! ไม่มีอะไรเท่า Mornbrew ร้อน ไม่สิ ร้อนลวก อุ่นถึงวิญญาณในวันหนาว\n\nนี่ {name} ช่วยเอาแก้วเปล่าคืน Nori แทนข้าทีได้ไหม" },
        progress = { "94:1915305912:1155296422", "เชื่อว่า Mornbrew ถึง Durnan ทันเวลา! จำได้ไหมว่าต้องเอาแก้วคืน?" },
        completion = { "11:1614239848:1406166483 N 221:522314364:158305167", "เยี่ยม {name}! คงแปลกใจหากรู้ว่าคนส่งของมากเพียงใดลืมงานง่ายอย่างคืนแก้ว แก้วไม่ได้งอกบนต้นไม้ เขาว่ากัน!\n\nนี่เล็กน้อยสำหรับความพยายาม ขอบใจอีกครั้ง" },
        required = { [10440] = { "10:1588530791:2068584221", "แก้วของ Nori" } },
        steps = { { "10:1588530791:2068584221", "แก้วของ Nori" } },
    },
    [5541] = { -- Ammo for Rumbleshot
        title = { "19:2049499023:349460745", "กระสุนให้ Rumbleshot" },
        objective = { "59:1207042781:88757710", "นำ Rumbleshot's Ammo ไปให้ Hegnar Rumbleshot ใน Dun Morogh" },
        description = { "366:1111273218:689502446 N 105:93121049:100584195", "Hegnar Rumbleshot ขายปืนข้างทางไป Anvilmar พลปืนกับทีมปืนครกฝึกแถวร้านบ่อย ต้องการกระสุนใหม่เสมอ\n\nแต่... ลังล่าสุดที่ส่งหายกลางทาง คนส่งบอกตั้งค่ายใกล้ Grizzled Den แล้วเวนดิโกไล่ เจ้าทึ่มทิ้งกระสุนไว้!\n\n{name} เอากระสุนส่งให้ได้ไหม? เขารออยู่ คงใกล้หมดแล้ว" },
        progress = { "56:51505163:155133328", "หวังว่าเจ้าไม่ได้มาหากระสุน เพราะใกล้หมด!" },
        completion = { "174:136055423:1837958683 N 45:805257013:2030393333", "เยี่ยม กระสุนเพิ่ม! ของ Loslor มาถึงเสียที! แม้ช้า แต่ปู่ข้าบอกเสมอ ช้าดีกว่าไม่มา!\n\nขอบใจมาก {name} มีคนรอซื้อของพวกนี้แล้ว!" },
        required = { [13850] = { "17:914156994:1255187663", "กระสุนของ Rumbleshot" } },
        steps = { { "17:914156994:1255187663", "กระสุนของ Rumbleshot" } },
    },
