    [95041] = { -- Data Hoarders
        title = { "13:1687027128:590491798", "ผู้เก็บสะสมข้อมูล" },
        objective = { "116:1628681480:443359156", "เก็บ Gnomeregan Archival Data cards 7 ใบ รอบ Gnomeregan แล้วส่งให้ Jemma Quikswitch ใน Ironforge" },
        description = { "493:532165618:838465342", "ก่อนหนี Gnomeregan ข้าทำสำเนาคลังข้อมูลครอบครัว ทั้งสมการสนามอาร์เคนผสานวิศวกรรม แบบตัวเรือดำน้ำยุคสงครามครั้งที่สอง สูตรชิลี Grandma Quikswitch... ความสำเร็จยิ่งใหญ่ของเราอยู่ในแฟ้มเหล่านั้น\n\nถึง Ironforge จึงพบรูที่กระเป๋า! บัตรเจาะรูหายหลายใบ ไม่มีมันข้อมูลก็สับสนจนกู้ไม่ได้\n\nบัตรคงฝังหิมะนอก Gnomeregan ช่วยหาได้ไหม? รู้ว่าโอกาสน้อย..." },
        progress = { "38:1182550488:2109004942", "กู้ข้อมูลคืบหน้าอย่างไร?" },
        completion = { "75:103108252:1047737602", "บัตรดูชื้นหน่อย... แต่ข้าจัดการได้! ขอบใจสหาย!", variants = { { "68:1814582327:727309830 N 1:33:33", "การ์ดพวกนี้ดูชื้นไปหน่อย... แต่ข้ายังเอาไปใช้ได้! ขอบใจนะ {name}!" } } },
        required = { [267413] = { "24:218516207:1449152367", "ข้อมูลจากคลังจดหมายเหตุ Gnomeregan" } },
        steps = { { "24:218516207:1449152367", "ข้อมูลจากคลังจดหมายเหตุ Gnomeregan" } },
    },
    [95212] = { -- Never Saddle on Quality
