        objective = { "70:1738444936:1135544191", "เก็บ Pristine Leopard Pelts 6 ผืน แล้วส่งให้ Amberstill Ranch" },
        description = { "313:714594690:415509457", "เราจะส่งแกะชุดหนึ่งเสริมคณะเดินทาง Alterac แต่ขาดวัสดุทำอาน\n\nเก็บหนังจากเสือดาวตัวใหญ่ดุที่สุดทางตะวันออกมาให้ ที่นั่นหนาวกัดกระดูก กำลังของเราคู่ควรกับหนังดีที่สุดเพื่ออุ่นตัว!" },
        progress = { "47:1442300950:1206479983", "ดูหนาวนะนักผจญภัย ล่าเป็นอย่างไร?", variants = { { "17:391683128:707147908 C 20:427800993:1393405794", "ดูหนาวนะ{class} ล่าเป็นอย่างไร?" } } },
        completion = { "84:1963156989:414643446", "หนังนี้ทำอานได้ยอดเยี่ยม เจ้าทำให้ Alliance ภูมิใจ นักผจญภัย!", variants = { { "73:1503126505:2021042794 C 1:33:33", "หนังนี้ทำอานได้ยอดเยี่ยม เจ้าทำให้ Alliance ภูมิใจ {class}!" } } },
