        description = { "247:1025380118:357266618", "ถังประทับว่า:\n\nดินระเบิด - อันตราย - ห้ามจับต้อง - อันตราย - เฉพาะผู้ได้รับอนุญาตจากนายเหมือง - อันตราย\n\nเจ้ารู้สึกใจหายที่โทรกก์มีของเช่นนี้ ควรรีบรายงานเหมือง" },
        progress = { "23:2101701093:1265623654", "ถืออะไรมา?" },
        completion = { "5:1187980023:680763879 R 66:1953763156:461034695", "<{race} หน้าซีดเมื่อเห็นถังเปล่า>\n\n...เจ้าเจอถังนี้ที่ไหน?", variants = { { "76:159082344:1188270988", "<คนแคระหน้าซีดเมื่อเห็นถังเปล่า>\n\n...เจ้าเจอถังนี้ที่ไหน?" } } },
