        title = { "22:294107284:327713062", "ดินระเบิดที่ถูกขโมย" },
        objective = { "112:2041555287:957440460", "นำ Stolen Blasting Powder 16 ชิ้น คืนจากโทรกก์ทางตะวันออกของ Gol'Bolar Quarry แล้วกลับไปหา Quarrymaster Thesten", amount = { "8:1749550375:377180055 W1 102:1051574786:545407429", "นำ Stolen Blasting Powder {world1} ชิ้น คืนจากโทรกก์ทางตะวันออกของ Gol'Bolar Quarry แล้วกลับไปหา Quarrymaster Thesten" } },
        description = { "168:1989236261:75728344", "ถังนี้มีดินระเบิดพอเปลี่ยนท้องพระโรง King Magni เป็นลานโล่ง ต้องเอาคืนก่อนโทรกก์รู้วิธีจุด" },
        progress = { "35:765257902:1520834616", "หวังว่ามีข่าวดี?" },
        completion = { "163:903649410:636411026", "คงเป็นดินระเบิดที่หายทั้งหมด ขอบใจนักผจญภัย\n\nโปรดรับรางวัล และ... จะดีหากไม่บอกเรื่องเล็กนี้กับใคร", variants = { { "49:898208246:855747972 C 104:1649952508:568811971", "คงเป็นดินระเบิดที่ถูกขโมยไปทั้งหมดแล้ว ขอบใจนะ {class}\n\nรับรางวัลนี่ไว้เถอะ แล้วก็... ถ้าเจ้าไม่เล่าเรื่องเล็ก ๆ นี้ให้ใครฟัง ข้าจะขอบใจมาก" } } },
        required = { [267415] = { "22:294107284:327713062", "ดินระเบิดที่ถูกขโมย" } },
        steps = { { "22:294107284:327713062", "ดินระเบิดที่ถูกขโมย" } },
    },
