        description = { "239:544023798:1536027794", "สายลับ Dark Iron แทรก Dun Morogh ไม่แน่ใจเป้าหมาย แต่ต้องตัดปัญหาก่อนลุกลาม\n\nไปตะวันออกถึง Ironband's Compound แล้วฆ่าสายลับที่พบ", variants = { { "240:325292793:1100843402", "สายลับ Dark Iron แทรก Dun Morogh ไม่แน่ใจเป้าหมาย แต่ต้องตัดปัญหาก่อนลุกลาม\n\nไปตะวันออกถึง Ironband's Compound แล้วฆ่าสายลับที่พบ" } } },
        completion = { "266:1809012457:1387051969", "Dark Iron อาจเป็นญาติ แต่ไม่ใช่ครอบครัวแน่ ข้าไม่เสียใจต่อเคราะห์ร้ายของพวกที่ออกห่างภูเขาต้องสาปเกินไป\n\nหวังว่าพอให้เลิกบุกดินแดนนี้อีก" },
        progress = { "38:2057866577:1083858270", "เป็นยังไงบ้าง? เจ้าเล่นงานพวกมันจนเข็ดหรือยัง?", variants = { { "38:1233907698:845359159", "เป็นยังไงบ้าง? เจ้าเล่นงานพวกมันจนเข็ดหรือยัง?" } } },
        objectiveLabels = {
            monster = { ["Dark Iron Spy slain"] = "ปราบ สายลับ Dark Iron" },
        },
    },
    [96391] = { -- Underground Map
        title = { "15:697776863:2109809516", "แผนที่ใต้ดิน" },
        objective = { "60:1187544222:828867510", "ส่ง Dark Iron Map ให้ Earthseer Farsen ใน Dun Morogh" },
        description = { "474:951230549:1840846001", "แผนที่ในมือดูแสดงอุโมงค์และทางใต้ดินซับซ้อน ทุกสายเหมือนมารวมใต้ Ironforge\n\nเจ้าอ่านรูนฟันหยักน่าเกลียดของคนแคระ Dark Iron ไม่แน่ใจ แต่พอเดาจุดประสงค์อุโมงค์ได้ ขณะอ่าน ลมพัดผ่าน มีเสียงคนแคระแผ่วมาด้วย Earthseer Farsen ต้องเห็นสิ่งนี้", variants = { { "476:936020233:1899089795", "<แผนที่ในมือดูแสดงอุโมงค์และทางใต้ดินซับซ้อน ทุกสายเหมือนมารวมใต้ Ironforge\n\nเจ้าอ่านรูนฟันหยักน่าเกลียดของคนแคระ Dark Iron ไม่แน่ใจ แต่พอเดาจุดประสงค์อุโมงค์ได้ ขณะอ่าน ลมพัดผ่าน มีเสียงคนแคระแผ่วมาด้วย Earthseer Farsen ต้องเห็นสิ่งนี้>" }, { "490:1930893410:1748216742", "แผนที่ในมือเจ้าดูเหมือนจะแสดงเครือข่ายอุโมงค์และเส้นทางใต้ดินที่ซับซ้อน ทุกสายดูจะมาบรรจบกันใต้เมือง Ironforge พอดี\n\nเจ้าอ่านอักษรรูนหยักกระด้างของคนแคระ Dark Iron ได้ไม่แน่ชัด แต่พอเดาได้ว่าอุโมงค์เหล่านี้มีไว้ทำอะไร ขณะอ่านแผนที่ ลมวูบหนึ่งพัดผ่านตัวเจ้า พาเสียงแผ่ว ๆ ของคนแคระมาบอกให้เจ้าไปหา Earthseer ผู้มีนามว่า “Farsen”" }, { "492:381395890:638185683", "<แผนที่ในมือเจ้าดูเหมือนจะแสดงเครือข่ายอุโมงค์และเส้นทางใต้ดินที่ซับซ้อน ทุกสายดูจะมาบรรจบกันใต้เมือง Ironforge พอดี\n\nเจ้าอ่านอักษรรูนหยักกระด้างของคนแคระ Dark Iron ได้ไม่แน่ชัด แต่พอเดาได้ว่าอุโมงค์เหล่านี้มีไว้ทำอะไร ขณะอ่านแผนที่ ลมวูบหนึ่งพัดผ่านตัวเจ้า พาเสียงแผ่ว ๆ ของคนแคระมาบอกให้เจ้าไปหา Earthseer ผู้มีนามว่า “Farsen”>" } } },
        progress = { "21:1535918480:1600199703", "โอ้ นี่อะไร?" },
        completion = { "304:1090385507:1229116133", "ดูจากแผนที่ Dark Iron คงวางแผนบุกคลังใต้ Ironforge กลุ่มที่เจ้าจัดการตะวันออกคงเป็นหน่วยสำรวจ\n\nขอบใจที่นำมา หากรีบ อาจถึงเป้าหมายข้างล่างก่อนพวกมัน" },
        required = { [274268] = { "13:1237825306:521636549", "แผนที่ของ Dark Iron" } },
        steps = { { "13:1237825306:521636549", "แผนที่ของ Dark Iron" } },
    },
    [96392] = { -- Farsen's Watch
        title = { "14:163124392:1158433261", "นิมิตของ Farsen" },
        objective = { "99:2059135766:2068617003", "คุยกับ Earthseer Farsen ขอให้เขาใช้พลังมองไกลเพื่อให้เจ้าสังเกตภัย Dark Iron", variants = { { "97:1469824396:88589838", "คุยกับ Earthseer Farsen ขอให้เขาใช้พลังมองไกลเพื่อให้เจ้าสังเกตภัย Dark Iron" }, { "98:1237475618:728097537", "คุยกับ Earthseer Farsen ขอให้เขาใช้พลังมองไกลเพื่อให้เจ้าสังเกตภัย Dark Iron" } } },
        description = { "300:567299534:1398846766", "สวัสดีสหาย ข้าชื่อ Earthseer Farsen มาเยือน Dun Morogh จาก Aerie Peak ระหว่างทางสังเกตว่าเรามี... ปัญหาคนแคระ Dark Iron อยู่บ้าง\n\nหากมีเวลา ข้าแสดงให้ดูได้ มีเวทเล็กน้อยน่าจะช่วย" },
        completion = { "173:1294553592:472568535", "เห็นแล้วใช่ไหมนักผจญภัย? ยั้วเยี้ยเหมือนแมลงสาบ นั่นแค่ส่วนที่มองจากฟ้า\n\nเจ้าดูแข็งแกร่ง สนใจลงไม้ลงมือหน่อยไหม?", variants = { { "15:1376361810:38154547 C 148:2072855979:1998542995", "เห็นแล้วใช่ไหม {class} พวกมันยั้วเยี้ยอย่างกับแมลงสาบ นั่นแค่พวกที่มองเห็นจากฟ้านะ\n\nเจ้าดูท่าทางแข็งแรงดี สนใจลงไม้ลงมือสักหน่อยไหม" }, { "15:1376361810:38154547 C 147:385264680:1871093844", "เห็นแล้วใช่ไหม {class}? ยั้วเยี้ยเหมือนแมลงสาบ นั่นแค่ส่วนที่มองจากฟ้า\n\nเจ้าดูแข็งแกร่ง สนใจลงไม้ลงมือหน่อยไหม?" } } },
        progress = { "74:1465149422:1952385145", "Farsight ทำให้เจ้าเห็นอะไรได้มากมาย แม้แต่สิ่งที่เจ้าไม่อยากเห็น", variants = { { "75:538975296:483231512", "Farsight ทำให้เจ้าเห็นอะไรได้มากมาย แม้แต่สิ่งที่เจ้าไม่อยากเห็น" } } },
        steps = { { "22:1577002766:958388888", "ใช้ Far Sight ของ Farsen" }, { "21:2038186636:615625215", "ใช้ Far Sight ของ Farsen" } },
    },
    [96408] = { -- A Visitor to Dun Morogh
        title = { "23:1446482765:532607374", "ผู้มาเยือน Dun Morogh" },
        objective = { "58:1522073131:1942411724", "สำรวจค่ายที่มองลงเห็น Gol'Bolar Quarry" },
        description = { "301:84566700:244752960", "เมื่อคืน Mountaineer คนหนึ่งเห็นกองไฟบนเนินตะวันออก ดูอยู่สูง มองลงเห็น Gol'Bolar Quarry\n\nคงไม่มีอะไร แต่ขอให้ไปดู หากมิตร ก็ไม่เสียหาย หากไม่ใช่... รู้ว่าต้องทำอะไร" },
        completion = { "30:1738206581:821270620", "สวัสดีสหาย เป็นอย่างไร?" },
    },
    [98319] = { -- Secure the Mountain
        title = { "19:1695893801:1226806666", "รักษาความปลอดภัยภูเขา" },
        objective = { "72:1380081157:39789412", "หา Mountaineer Cornelius ใน Grizzled Den ให้ Mountaineer Gretchen" },
        description = { "497:1078604215:752045979", "แค่ปัญหาโทรลล์ก็แย่แล้ว แต่ภูเขายังเต็มเวนดิโก! ปกติอยู่ถ้ำตน ตอนนี้เพิ่มเหมือนกระต่าย เต็ม Grizzled Den ทางเหนือ\n\nหากอยากได้รายงาน Whitebeard ต้องหา Cornelius คู่หูข้า เจ้าทึ่มตื่นเต้นบุกพรวดเข้า กล้าแต่โง่\n\nเข้าถ้ำดูว่าอยู่ไหน และจัดการสัตว์ร้ายได้ตามสะดวก", variants = { { "494:1621450203:705085896", "แค่ปัญหาโทรลล์ก็แย่แล้ว แต่ภูเขายังเต็มเวนดิโก! ปกติอยู่ถ้ำตน ตอนนี้เพิ่มเหมือนกระต่าย เต็ม Grizzled Den ทางเหนือ\n\nหากอยากได้รายงาน Whitebeard ต้องหา Cornelius คู่หูข้า เจ้าทึ่มตื่นเต้นบุกพรวดเข้า กล้าแต่โง่\n\nเข้าถ้ำดูว่าอยู่ไหน และจัดการสัตว์ร้ายได้ตามสะดวก" } } },
        completion = { { "73:1296001137:647216714", "40:2009293568:44305505 N 27:1611906634:1355284556", "40:2009293568:44305505 C 27:1611906634:1355284556", "40:2009293568:44305505 R 27:1611906634:1355284556" }, "เฮ้อ เจ้าทึ่ม...\n\nขอบใจสหาย คงได้รายงานแล้ว" },
        progress = { "104:1907217970:2132245402", "มีข่าวอะไรไหม? ข้าบอก Cornelius แล้วว่าอย่าเข้า Grizzled Den คนเดียว แต่เขาก็ดื้อมาแต่ไหนแต่ไร" },
        steps = { { "27:1332842344:958117609", "พบ Mountaineer Cornelius" } },
    },
    [98321] = { -- Flintfire's Shipment
        title = { "20:587429018:954906900", "สินค้าของ Flintfire" },
        objective = { "85:173133425:1231475102", "เก็บ Flintfire Shipments 8 ชิ้น จาก Grizzled Den ให้ Tongus Flintfire ใน Kharanos", amount = { "8:1089852795:1107240600 W1 76:1802753400:1232853559", "เก็บ Flintfire Shipments {world1} ชิ้น จาก Grizzled Den ให้ Tongus Flintfire ใน Kharanos" } },
        description = { "20:448379266:295489691 R 437:1240232310:531218740", "โฮ่! ดีที่พบ{race}ไม่กลัวมือเปื้อน\n\nหากหางาน เกรงว่าตอนนี้ขาดเสบียง แหล่งแร่ที่ไว้ใจที่สุดถูกเวนดิโกยึด ถ้ำถูกทิ้ง คนงานหนีจนต้องทิ้งทุกอย่าง!\n\nลองดู Grizzled Den ทางตะวันตกว่ามีของส่งที่หายไหม จะช่วยลดปัญหามาก", variants = { { "474:29998765:1847020620", "โฮ่! ดีใจที่เจอเพื่อนช่างตีเหล็กที่ไม่กลัวมือเปื้อน\n\nถ้าเจ้ามาหางาน เกรงว่าตอนนี้เราขาดเสบียงอยู่บ้าง พวกเวนดิโกบุกยึดแหล่งแร่ที่เราไว้ใจที่สุด ตอนนี้ถ้ำถูกทิ้งร้าง คนงานเหมืองต้องทิ้งทุกอย่างตอนหนี!\n\nทำไมเจ้าไม่ลองไปดูแถว Grizzled Den ทางตะวันตก เผื่อจะเจอของที่ส่งมาแล้วหายไปบ้าง จะช่วยเราได้มากทีเดียว" } } },
        progress = { "104:1725321268:235842523", "เวนดิโกเป็นสัตว์ร้าย โชคดีคนเหมืองทุกคนออก Grizzled Den ครบถ้วนปลอดภัย!", variants = { { "103:1624021130:1607164025", "เวนดิโกเป็นสัตว์ร้าย โชคดีคนเหมืองทุกคนออก Grizzled Den ครบถ้วนปลอดภัย!" } } },
        completion = { "97:169560697:1738803807", "อย่างนี้สิ! มีของพวกนี้ โรงตีเหล็กจะกลับทำงานเร็ว ๆ นี้!" },
        required = { [280413] = { "20:587429018:954906900", "สินค้าของ Flintfire" } },
        steps = { { "20:587429018:954906900", "สินค้าของ Flintfire" } },
    },
    [98322] = { -- Secure the Mountain
        title = { "19:1695893801:1226806666", "รักษาความปลอดภัยภูเขา" },
        objective = { "50:1322235673:183932166", "แวะหา Mountaineer Gretchen ทางตะวันตกของ Kharanos" },
        description = { "423:807999736:366168834", "สำรวจถ้ำมืดเป็นงานนักผจญภัย งานข้าแค่เขียนรายงานส่ง Ironforge\n\nปัญหาคือรายงานหนึ่งยังไม่... รายงานกลับ ข้าให้ Mountaineers ไปศึกษาเวนดิโก แต่ยังไม่ได้ข่าว\n\nหากเจ้าออกไปอยู่แล้ว แวะหา Mountaineer Gretchen ทางตะวันตกของเมืองหน่อยไหม ข้าล่าช้ามากพอแล้ว!", variants = { { "429:2037418834:1733711741", "สำรวจถ้ำมืดเป็นงานนักผจญภัย งานข้าแค่เขียนรายงานส่ง Ironforge\n\nปัญหาคือรายงานหนึ่งยังไม่... รายงานกลับ ข้าให้ Mountaineers ไปศึกษาเวนดิโก แต่ยังไม่ได้ข่าว\n\nหากเจ้าออกไปอยู่แล้ว ว่าอย่างไรหากจะไม่แวะหา Mountaineer Gretchen ทางตะวันตกของเมือง ข้าล่าช้ามากพอแล้ว!\n\nหมายเหตุผู้แปล: ฉบับนี้มีคำว่า don't ในประโยคท้าย แต่ช่องเป้าหมายยังระบุให้ไปพบ Gretchen" } } },
        completion = { "86:1377593247:192558693", "เฒ่า Whitebeard ส่งมาหรือ?\n\nมีรายงานแล้ว เรื่องทั้งหมดเละเทะ!" },
    },
    [98323] = { -- Secure the Mountain
        title = { "19:1695893801:1226806666", "รักษาความปลอดภัยภูเขา" },
        objective = { "75:678414634:1919206998", "ส่ง Mountaineer Gretchen's Report กลับให้ Senir Whitebeard ใน Kharanos" },
        description = { "338:165684672:1020938756 N 55:1216197833:1530169500", "หวังว่าจัดการสัตว์เลวในนั้นได้ไม่น้อย แต่น่าเสียดายเรื่อง Cornelius\n\nจากที่เล่า ไม่มีอะไรรายงานนอกจากถ้ำหมดหวัง Whitebeard คงไม่ชอบ แต่ข้าไม่กล้าส่งใครเข้าสู่กับดักมรณะอีก\n\nฝากบอกได้เลย {name} ข้าจะไม่ไปไหนจนภูเขาปลอดภัย" },
        progress = { "88:448057224:875644898", "อา กลับมาทันพอดี\n\nเป็นอะไรพ่อหนุ่ม? เหมือนเห็นผีมา", variants = { { "89:1991368307:1381994588", "อา กลับมาทันพอดี\n\nเป็นอะไรไป สาวน้อย? หน้าตาเหมือนเพิ่งเห็นผีมาเลย" } } },
        completion = { "136:214876809:1480850879", "ถูกยึดหมดเลยหรือ? ทำไมข้าไม่แปลกใจเลยนะ\n\nเอาละ เรื่องนี้ก็ต้องลงรายงานด้วย\n\n<Senir พับจดหมายของ Gretchen เก็บเข้ากองบันทึก>" },
        required = { [280430] = { "29:1561582654:1819835683", "รายงานของทหารภูเขา Gretchen" } },
        steps = { { "29:1561582654:1819835683", "รายงานของทหารภูเขา Gretchen" } },
    },
    [98326] = { -- Frosthowl
        title = { "9:1125142307:132681508", "Frosthowl" },
        objective = { "82:533572193:1779213915", "ฆ่า Frosthowl แล้วเก็บ Sack of Fish ให้ Gretta Ganter ที่ Brewnall Village", variants = { { "81:921232581:1521738227", "ฆ่า Frosthowl แล้วเก็บ Sack of Fish ให้ Gretta Ganter ที่ Brewnall Village" } } },
        description = { "502:1881593348:413443175", "รู้ไหมตกปลาทะเลสาบน้ำแข็งยากเพียงใด? Paxton สามีข้าอยู่กลางทะเลสาบหลายวัน เพิ่งได้แทบถุงเดียว\n\nคือเราเคยมีถุงหนึ่ง จนเวนดิโกบ้าบุกเอาไป ต้องหลายสัปดาห์กว่าจะจับคืนหมด! หาก Frosthowl จอมเสียงดังยังไม่ไล่ปลาหนีหมดเสียก่อน\n\nช่วยเอาคืนได้ไหม? สัตว์ยักษ์น้ำลายย้อยซ่อนลึกใน Grizzled Den ทางตะวันออกเฉียงใต้" },
        progress = { "95:1473020113:1654486246", "Dun Morogh คงร้อนขึ้นมาก่อนข้ายอมบอก Paxton ว่าทำปลาทั้งหมดหายให้เวนดิโก" },
        completion = { { "177:1236794351:203430164", "22:219180265:414737257 N 149:1291597336:1242194933", "22:219180265:414737257 C 149:1291597336:1242194933", "22:219180265:414737257 R 149:1291597336:1242194933" }, "เจ้าช่วยชีวิตจริงสหาย!\n\nสามีคงหัวเราะผ่านไป แต่ข้าทนบอกให้เขาอยู่ทะเลสาบอีกคืนไม่ได้ ตอนนี้อาจได้กินมื้อใหญ่กัน", variants = { { "22:219180265:414737257 N 149:849003884:1709718520", "เจ้าช่วยข้าไว้มากเลย {name}!\n\nสามีคงหัวเราะผ่านไป แต่ข้าทนบอกให้เขาอยู่ทะเลสาบอีกคืนไม่ได้ ตอนนี้อาจได้กินมื้อใหญ่กัน" } } },
        required = { [280426] = { "12:756003335:247884424", "กระสอบปลา" } },
        steps = { { "12:756003335:247884424", "กระสอบปลา" } },
    },
    [98423] = { -- The Treaty of Understanding
        title = { "27:1170553411:1159714825", "สนธิสัญญาแห่งความเข้าใจ" },
        objective = { "70:2062847628:1033348849", "ส่ง Treaty of Understanding ให้ Magni Bronzebeard ใน Ironforge" },
        description = { "335:1815232197:1583052008", "ในคลัง เจ้าพบแผ่นจารึกรายละเอียดสนธิสัญญาสันติภาพระหว่างเผ่าคนแคระ Bronzebeard กับ Wildhammer ดูมีอายุหลัง War of the Three Hammers ไม่นาน น่าจะเป็นประวัติศาสตร์คนแคระสำคัญ ราชา Ironforge คงสนใจวัตถุนี้", variants = { { "331:870118042:939221114", "ในคลัง เจ้าพบแผ่นจารึกรายละเอียดสนธิสัญญาสันติภาพระหว่างเผ่าคนแคระ Bronzebeard กับ Wildhammer ดูมีอายุหลัง War of the Three Hammers ไม่นาน น่าจะเป็นประวัติศาสตร์คนแคระสำคัญ ราชา Ironforge คงสนใจวัตถุนี้" }, { "334:694324256:1260520387", "ในคลัง เจ้าพบแผ่นจารึกรายละเอียดสนธิสัญญาสันติภาพระหว่างเผ่าคนแคระ Bronzebeard กับ Wildhammer ดูมีอายุหลัง War of the Three Hammers ไม่นาน น่าจะเป็นประวัติศาสตร์คนแคระสำคัญ ราชา Ironforge คงสนใจวัตถุนี้" } } },
        progress = { "50:228169742:1119549159", "นำอะไรจากส่วนลึกมา นักผจญภัย", variants = { { "39:1676757099:939789501 C 1:46:46", "นำอะไรจากส่วนลึกมา {class}" } } },
        completion = { "437:11707256:1044992829", "อา ใช่ Madoran บรรพชนข้าเป็นราชา Bronzebeard คนแรกของ Ironforge หลังสงครามกลางเมืองระหว่าง Wildhammer, Bronzebeard และ Dark Iron สนธิสัญญานี้ร่างกำหนดหยุดรบและสันติภาพหลัง Bronzebeard ชิงภูเขาได้\n\nอย่างที่เห็น Wildhammer กับ Bronzebeard ลงนาม... แต่ Dark Iron ไม่ลง\n\nขอบใจที่กู้คืนและนำมา นักผจญภัย", variants = { { "426:1497304876:701544002 C 1:46:46", "อา ใช่ Madoran บรรพชนข้าเป็นราชา Bronzebeard คนแรกของ Ironforge หลังสงครามกลางเมืองระหว่าง Wildhammer, Bronzebeard และ Dark Iron สนธิสัญญานี้ร่างกำหนดหยุดรบและสันติภาพหลัง Bronzebeard ชิงภูเขาได้\n\nอย่างที่เห็น Wildhammer กับ Bronzebeard ลงนาม... แต่ Dark Iron ไม่ลง\n\nขอบใจที่กู้คืนและนำมา {class}" } } },
        required = { [281030] = { "23:64594174:1039475019", "สนธิสัญญาว่าด้วยความเข้าใจร่วมกัน" } },
        steps = { { "23:64594174:1039475019", "สนธิสัญญาว่าด้วยความเข้าใจร่วมกัน" } },
    },
    [99158] = { -- Dawn in the Mountains
        title = { "21:1826011771:1936131280", "รุ่งอรุณบนภูเขา" },
        objective = { "64:1779950527:658395566", "นำลังเทียนไปให้ Father Gavin ที่ Misty Pine Refuge" },
        description = { "505:1213528404:1742173461", "มีนักบวชบนเขาสังกัด Argent Dawn กลุ่มศักดิ์สิทธิ์ที่อุทิศตนค้นและทำลายสิ่งอธรรมผิดธรรมชาติ\n\nแต่ Father Gavin เน้นช่วยและรักษาทุกคนแทนจับอาวุธ เขาซ่อมอาคารเก่าเป็นที่พักผู้เดินทาง เรียก Misty Pine Refuge ข้ามีเทียนศักดิ์สิทธิ์ต้องส่ง หากไปทางนั้นช่วยนำให้ได้ไหม?", variants = { { "471:1639870024:1275424041", "บนภูเขามีนักบวชคนหนึ่งสังกัด Argent Dawn พวกเขาเป็นกลุ่มศักดิ์สิทธิ์ที่อุทิศตนตามหาและกำจัดสิ่งอธรรมกับสิ่งผิดธรรมชาติ\n\nแต่ Father Gavin เป็นคนที่ชอบช่วยเหลือและรักษาผู้อื่นมากกว่าจะจับอาวุธ เขาซ่อมอาคารเก่าหลังหนึ่งให้เป็นที่พักสำหรับนักเดินทาง ข้ามีเทียนศักดิ์สิทธิ์ที่ต้องส่งให้เขา ถ้าเจ้าจะไปทางนั้น ช่วยเอาไปให้เขาทีได้ไหม?" }, { "503:257621171:195872296", "มีนักบวชบนเขาสังกัด Argent Dawn กลุ่มศักดิ์สิทธิ์ที่อุทิศตนค้นและทำลายสิ่งอธรรมผิดธรรมชาติ\n\nแต่ Father Gavin เน้นช่วยและรักษาทุกคนแทนจับอาวุธ เขาซ่อมอาคารเก่าเป็นที่พักผู้เดินทาง เรียก Misty Pine Refuge ข้ามีเทียนศักดิ์สิทธิ์ต้องส่ง หากไปทางนั้นช่วยนำให้ได้ไหม?" } } },
        progress = { "39:1754921188:66278307", "วันนี้แสงสว่างนำเจ้ามาที่นี่ด้วยเหตุใด?" },
        completion = { "163:2023481553:1999465987", "อา เทียนจาก Ironforge\n\nแม้อยู่ในอาศรมได้ด้วยตนเองเป็นส่วนใหญ่ แต่มีของสำคัญบางอย่างที่ข้าซาบซึ้งจากเมืองและผู้ศรัทธา" },
        required = { [286355] = { "16:327203889:228432831", "ลังเทียน" } },
        steps = { { "16:327203889:228432831", "ลังเทียน" } },
    },
    [99159] = { -- Finding Warmth
        title = { "14:309629937:1310180522", "ค้นหาความอบอุ่น" },
        objective = { "30:115065276:614095399", "เก็บฟืน 14 ชิ้น", amount = { "8:1089852795:1107240600 W1 20:310868334:294632961", "เก็บฟืน {world1} ชิ้น" } },
        description = { "201:1844286598:2140332077", "เตาข้าต้อนรับทุกวิญญาณให้อุ่น แต่หากช่วยได้ ข้าขอแรงหน่อย\n\nแค่ต้องการฟืนเพิ่ม ปกติทำเอง แต่ยุ่งกับงานอื่น" },
        progress = { "30:1238181094:1681344743", "ขอแสงสว่างนำทางภารกิจเจ้า" },
        completion = { "151:470358977:1994283826", "อา สมบูรณ์แบบ ใช้ได้ ส่วนที่เปียกเกินตอนนี้จะตากไว้\n\nหากยินดี ข้ายังมีงานให้ช่วยอีก" },
        required = { [286339] = { "19:306619223:1270784103", "ฟืนที่ส่วนใหญ่แห้งแล้ว" } },
        steps = { { "19:306619223:1270784103", "ฟืนที่ส่วนใหญ่แห้งแล้ว" } },
    },
    [99160] = { -- Rime's Wrath
        title = { "12:1209083095:1568684196", "พิโรธแห่งน้ำค้างแข็ง" },
        objective = { "32:940152308:989302263", "ทำลายธาตุน้ำแข็งขนาดเล็ก 10 ตน", amount = { "8:286779151:428491486 W1 22:1694148100:1290981984", "ทำลายธาตุน้ำแข็งขนาดเล็ก {world1} ตน" } },
        description = { "344:1695749426:2083861399", "อาจสังเกตธาตุใกล้ ๆ หลายวันก่อนชั้นหินกับน้ำแข็งถล่มจากยอดเขาทำให้โกรธ\n\nภูเขาแข็งนี้อันตรายต่อคนแคระหรือมนุษย์ทั่วไปอยู่แล้ว แม้ไม่มีธาตุปรากฏ ข้าไม่ใช่นักสู้อีกต่อไป หากเจ้าฆ่าวิญญาณได้ก็ช่วยให้ถนนปลอดภัย" },
        completion = { "131:953409607:231176572", "อยากให้ปลอบพวกเขาได้ แต่นอกเหนือความรู้ข้า และอันตรายเกินปล่อยไว้" },
        progress = { "17:2002626072:1875813106", "เจ้าต้องการอะไรหรือ" },
        objectiveLabels = {
            monster = { ["Minor Ice Elemental slain"] = "ปราบ ธาตุน้ำแข็งขนาดเล็ก" },
        },
    },
    [99161] = { -- Rime's Wrath
        title = { "12:1209083095:1568684196", "พิโรธแห่งน้ำค้างแข็ง" },
        objective = { "33:527548036:1622402906", "ฆ่า Avala แล้วเก็บแก่นของมัน" },
        description = { "300:1280311405:1082853629", "ข้าสังเกตธาตุตนแรกหลังหินถล่มใหญ่กว่าตนอื่น เท่าที่เห็น มันเป็นต้นเหตุอากาศเปลี่ยนเป็นพัก ๆ และการถล่มเล็กน้อยเพิ่มเติม\n\nข้าเรียกมันว่า Avala หากฆ่าแล้วนำแก่นมาเป็นหลักฐาน จะให้รางวัล", variants = { { "302:1828972625:1591742751", "ข้าสังเกตธาตุตนแรกหลังหินถล่มใหญ่กว่าตนอื่น เท่าที่เห็น มันเป็นต้นเหตุอากาศเปลี่ยนเป็นพัก ๆ และการถล่มเล็กน้อยเพิ่มเติม\n\nข้าเรียกมันว่า Avala หากฆ่าแล้วนำแก่นมาเป็นหลักฐาน จะให้รางวัล" } } },
        progress = { "25:274219682:339641551", "ระวังเหมันต์สหาย" },
        completion = { { "114:642733638:1106891507", "17:331464546:990140092 N 87:463244023:2037713027", "17:331464546:990140092 C 87:463244023:2037713027", "17:331464546:990140092 R 87:463244023:2037713027" }, "ขอแสงสว่างอวยพรนักผจญภัย ความพยายามทำให้แถวนี้ปลอดภัยขึ้น หวังว่าจะป้องกันความตายไม่จำเป็นได้" },
        required = { [286325] = { "12:550694507:918640315", "แก่นพลังของ Avala" } },
        steps = { { "12:550694507:918640315", "แก่นพลังของ Avala" } },
    },
    [99162] = { -- Treacherous Cold
        title = { "16:1151961044:105534126", "ความหนาวอันตราย" },
        objective = { "42:1465112214:848048380", "เก็บปืนยาวของ Mountaineers ที่เสียชีวิต" },
        description = { "497:1827869968:1786546395", "แม้ Mountaineers จาก Ironforge ก็ต้องระวังข้ามยอดเขา Dun Morogh หิมะน้ำแข็งถล่มมักจบชีวิตสมาชิกใหม่\n\nหลังถล่ม ข้ามักค้นร่องรอยผู้รอดหรือเหยื่อ พลางสวดต่อแสงสว่างว่าอย่าพบอะไร แต่เมื่อธาตุอาละวาด จึงไม่ออกไกล หากช่วยหาคนที่หายและนำปืนยาวมา ข้าจะส่งคืน Ironforge" },
        progress = { "17:2002626072:1875813106", "ต้องการอะไร?" },
        completion = { "196:1920092451:1864395494", "Mountaineers สลักชื่อบนพานท้ายปืน เพื่อระบุตัวหากเกิดเหตุ ข้าจะส่งกลับ Ironforge จะมีคนนำต่อให้ครอบครัว" },
        required = { [286360] = { "18:20056708:935603077", "ปืนไรเฟิลของ Stoneanvil" }, [286359] = { "17:1410179175:944647309", "ปืนไรเฟิลของ Sunhammer" }, [286358] = { "17:1319120542:1089517894", "ปืนไรเฟิลของ Coalbeard" } },
        steps = { { "18:20056708:935603077", "ปืนไรเฟิลของ Stoneanvil" }, { "17:1410179175:944647309", "ปืนไรเฟิลของ Sunhammer" }, { "17:1319120542:1089517894", "ปืนไรเฟิลของ Coalbeard" } },
    },
    [3106] = { -- Simple Rune
        title = { "11:1838132089:931515377", "รูนเรียบง่าย" },
        objective = { "68:282711667:912520346", "อ่าน Simple Rune แล้วคุยกับ Thran Khorman ใน Coldridge Valley" },
        description = { "252:872789937:1884406574", "ระหว่างเจ้าช่วยข้า มีคนฝากรูนนี้ส่งให้เจ้า หาเวลาอ่าน คิดว่ามาจากอาจารย์นักรบ Thran อ่านแล้วไปพบใน Anvilmar เมื่อสะดวก" },
        progress = { "68:1642794773:844463762 N 313:1592174693:1133772638", "วันนี้หนาวบ้าจริงใช่ไหม? หิมะเหมือนไม่เคยหาย {name}\n\nคงสังเกตว่ามีโนมอยู่เมืองเราแล้ว เพราะบ้านเขาระเบิดจนต้องหนี อย่าไปบอกใคร แต่ข้าโทษไม่ลง หาก Ironforge เต็ม Dark Iron ก็คงใช้ระเบิดเหมือนกัน", variants = { { "69:1263490115:1592632651 N 313:1592174693:1133772638", "หนาวเป็นบ้าเลยวันนี้ ว่าไหม? หิมะนี่เหมือนไม่มีวันละลายเลยนะ {name}\n\nเจ้าคงเห็นแล้วว่าตอนนี้มีพวกโนมมาอยู่ในเมืองเรา ก็พวกเขาดันระเบิดบ้านตัวเองจนต้องย้ายออกมาน่ะสิ อย่าเอาไปพูดต่อล่ะ แต่ข้าโทษพวกเขาไม่ลงหรอก ถ้า Ironforge เต็มไปด้วยพวก Dark Iron หรือพวกทำนองนั้น ข้าก็คงงัดระเบิดมาใช้เหมือนกัน" } } },
        completion = { "353:295880447:1372225159 C 85:765030637:1160716930", "เรื่องอื่นที่อาจเห็นคือคนแคระใช้เวทสู้แทนปืน บางคนบูชาแสงสว่างศักดิ์สิทธิ์เหมือนมนุษย์ และสุดท้าย โทรกก์ เจ้าจะรู้จักภายหลัง ตอนนี้แค่รู้ว่าข้าอยู่ช่วยเจ้า\n\nข้าจะสอนให้เป็น {class} ที่แท้ หากคิดว่าต้องฝึกเพิ่ม กลับมาหา แล้วดูว่าจะช่วยอะไรได้" },
        required = { [9543] = { "11:1838132089:931515377", "รูนเรียบง่าย" } },
        steps = { { "11:1838132089:931515377", "รูนเรียบง่าย" } },
    },
    [3107] = { -- Consecrated Rune
        title = { "16:1935222061:1322757174", "รูนชำระศักดิ์สิทธิ์" },
        objective = { "75:1105191876:57787176", "อ่าน Consecrated Rune แล้วคุยกับ Bromos Grummner ใน Coldridge Valley" },
        description = { "253:1057136255:238546655", "ระหว่างเจ้าช่วยข้า มีคนฝากรูนนี้ส่งให้เจ้า หาเวลาอ่าน คิดว่ามาจากอาจารย์พาลาดิน Bromos อ่านแล้วไปพบใน Anvilmar เมื่อสะดวก" },
        progress = { "229:1663503243:1809335696", "มาถึงแล้ว! ทันเวลาพอดี มีงานมากใน Coldridge Valley และนอกเขต ข้าต้องให้เจ้าช่วยพอ ๆ กับเจ้าต้องการข้า!\n\nตอนนี้เจ้าเป็นอัศวิน Silver Hand จงพร้อมทำหน้าที่" },
        completion = { "502:1835674651:945775731", "มนุษย์สอนเรื่องแสงสว่างศักดิ์สิทธิ์มาก และความสำคัญของคณะต่อพวกเขา... ต่อการปกป้อง Azeroth เราเคารพธรรมเนียมยาวนาน รวมถึงการที่บุคคลเดียว การเสียสละครั้งเดียว เปลี่ยนความเจ็บปวดเป็นความรอดได้\n\nเราจะทำงานด้วยกันพักหนึ่ง เมื่อพร้อมกลับมาฝึก จะปล่อยเจ้าออกโลกโดยไม่เตรียมตัวไม่ได้ใช่ไหม?" },
        required = { [9563] = { "16:1935222061:1322757174", "รูนที่ผ่านพิธีชำระ" } },
        steps = { { "16:1935222061:1322757174", "รูนที่ผ่านพิธีชำระ" } },
    },
    [3109] = { -- Encrypted Rune
        title = { "14:487148318:288146124", "รูนเข้ารหัส" },
        objective = { "70:208783878:965859427", "อ่าน Encrypted Rune แล้วคุยกับ Solm Hargrin ใน Coldridge Valley" },
        description = { "249:215523754:91754529", "ระหว่างเจ้าช่วยข้า มีคนฝากรูนนี้ส่งให้เจ้า หาเวลาอ่าน คิดว่ามาจากอาจารย์โร้ก Solm อ่านแล้วไปพบใน Anvilmar เมื่อสะดวก" },
        progress = { "351:883733568:1504846358", "มาแล้ว! เยี่ยม!\n\nกิจกรรมพักนี้มากขึ้น ดีที่มีคนตระกูล Ironforge เข้ากลุ่มเพิ่ม สำหรับข้า พวกเราหันไปพึ่งอาร์เคนกับเทพมากเกิน ไม่ต่อต้านความเชื่อ แต่ไม่มีอะไรเท่าคมดาบเย็นในมือกับเงาที่หลบแสง รู้ใช่ไหม?", variants = { { "259:2033730506:1485321791", "มาแล้วเรอะ! เยี่ยมเลย!\n\nพักนี้เรางานชุก ข้าดีใจที่ได้คนตระกูล Ironforge มาเข้าพวกอีกคน มีคมมีดเย็น ๆ อยู่ในมือกับเงาคอยกำบังให้เรานำหน้าอยู่ก้าวหนึ่ง ไม่มีอะไรดีไปกว่านี้แล้ว เจ้ามาถึงที่นี่ได้ก็คงรู้ดีว่าข้าหมายถึงอะไร!" } } },
        completion = { "458:782444750:910002647", "ระหว่างสำรวจ Coldridge คงต้องฝึกบ้าง กลับมาเมื่อจำเป็น ข้าจะสอนเคล็ดลับหรือท่าทางที่ช่วยให้รอดและได้เหรียญเพิ่มนิดหน่อย\n\nดูแลสหายโนมด้วย พวกเขาโชคร้ายที่ Gnomeregan... ถูกทำลาย ต้องให้รู้สึกเป็นที่ต้อนรับ" },
        required = { [9550] = { "14:487148318:288146124", "รูนเข้ารหัส" } },
        steps = { { "14:487148318:288146124", "รูนเข้ารหัส" } },
    },
    [3110] = { -- Hallowed Rune
        title = { "13:28976888:1004398836", "รูนศักดิ์สิทธิ์" },
        objective = { "66:455061072:345690457", "อ่าน Hallowed Rune แล้วคุยกับ Branstock Khalder ใน Anvilmar" },
        description = { "255:1516642121:918404188", "ระหว่างเจ้าช่วยข้า มีคนฝากรูนนี้ส่งให้เจ้า หาเวลาอ่าน คิดว่ามาจากอาจารย์นักบวช Branstock อ่านแล้วไปพบใน Anvilmar เมื่อสะดวก" },
        progress = { "17:1893544372:1412100396 N 184:267568402:314481011", "อา มาแล้ว {name}! เยี่ยม!\n\nเกือบหมดศรัทธาว่าเจ้าจะมา... เข้าใจไหม หมดศรัทธา? มุกน่ะสาวน้อย... ช่างเถอะ ไม่ได้มาเพื่อมุกแย่ของข้าอยู่แล้ว", variants = { { "17:1893544372:1412100396 N 183:2077517400:301176698", "อา! มาถึงแล้วหรือ {name}! เยี่ยมไปเลย!\n\nข้ากำลังจะบอกว่าเกือบหมดศรัทธาแล้วว่าเจ้าจะมาถึง... เข้าใจไหม หมดศรัทธาน่ะ? มุกน่ะ เจ้าหนุ่ม... เอ้อ ช่างเถอะ ยังไงเจ้าก็ไม่ได้มาเพื่อฟังมุกฝืด ๆ ของข้าอยู่แล้ว" } } },
        completion = { "290:1330622656:374809032 N 50:426216334:1374188766", "ข้าคือคนฝึกให้เมื่อเจ้าเริ่มรู้ทางใน Coldridge Valley เมื่อพร้อมกลับมา อาจสอนคาถาใหม่สักอย่างสองอย่างป้องกันหุบเขาจากโทรกก์บ้า\n\nเจ้ามีแสงสว่างกับ Ironforge ทั้งหมดเคียงข้าง {name}... ไม่ได้กดดันให้เป็นคนพิเศษหรอก" },
        required = { [9556] = { "13:28976888:1004398836", "รูนศักดิ์สิทธิ์" } },
        steps = { { "13:28976888:1004398836", "รูนศักดิ์สิทธิ์" } },
    },
    [3112] = { -- Simple Memorandum
        title = { "17:1129860607:151981528", "บันทึกเรียบง่าย" },
        objective = { "74:304781682:1421208672", "อ่าน Simple Memorandum แล้วคุยกับ Thran Khorman ใน Coldridge Valley" },
        description = { "258:2296291:782285184", "ระหว่างเจ้าช่วยข้า มีคนฝากบันทึกนี้ส่งให้เจ้า หาเวลาอ่าน คิดว่ามาจากอาจารย์นักรบ Thran อ่านแล้วไปพบใน Anvilmar เมื่อสะดวก" },
        progress = { "36:518988982:1576133173 R 247:2097001356:1741371107", "อา บันทึกอีกฉบับจาก{race}ที่มีภารกิจ... น่ารักดีนะ\n\nไม่ ๆ ไม่ได้ล้อเจ้าตัวน้อย ต้องเคารพความมุ่งมั่น หาก Ironforge ถูก Dark Iron ยึด ข้าก็คงโกรธเหมือนกัน อย่าคิดว่าไม่เห็นใจ...", variants = { { "288:1880776121:2057420672", "อา บันทึกอีกฉบับจากโนมที่มีภารกิจ... น่ารักดีนะ\n\nไม่ ๆ ไม่ได้ล้อเจ้าตัวน้อย ต้องเคารพความมุ่งมั่น หาก Ironforge ถูก Dark Iron ยึด ข้าก็คงโกรธเหมือนกัน อย่าคิดว่าไม่เห็นใจ..." } } },
        completion = { "405:509412413:382691923", "หากนี่คือคำสั่งสูงสุด หรือเรียกอะไรกันสมัยนี้ ข้าให้คำว่าจะช่วยให้เจ้ากับพวกพร้อมชิงบ้านคืน... และจะทำเช่นนั้น\n\nเมื่อพร้อม กลับมาหาเฒ่า Thran ยินดีแบ่งความรู้ มีค่าเรียนบ้าง แต่ไม่แพงนัก ขอให้โชคดี" },
        required = { [9544] = { "17:1129860607:151981528", "บันทึกข้อความเรียบง่าย" } },
        steps = { { "17:1129860607:151981528", "บันทึกข้อความเรียบง่าย" } },
    },
    [3113] = { -- Encrypted Memorandum
        title = { "20:27361453:611261813", "บันทึกเข้ารหัส" },
        objective = { "76:836290446:499073114", "อ่าน Encrypted Memorandum แล้วคุยกับ Solm Hargrin ใน Coldridge Valley" },
        description = { "255:60511770:381936302", "ระหว่างเจ้าช่วยข้า มีคนฝากบันทึกนี้ส่งให้เจ้า หาเวลาอ่าน คิดว่ามาจากอาจารย์โร้ก Solm อ่านแล้วไปพบใน Anvilmar เมื่อสะดวก" },
        progress = { "380:1022619962:1917192824", "ดีที่ได้จดหมายแล้วมา ขอโทษที่แกล้งเป็นบันทึกจากผู้บังคับบัญชา ไม่ได้ตั้งใจดูหมิ่น แค่รู้ว่าเรากับคนอย่างเราต้องร่วมกัน\n\nไม่ใช่ทุกคนเห็นดีที่เผ่าของเจ้ากับข้าอยู่เมืองเดียว แต่ข้าคิดว่าจัดการได้ เจ้าคิดอย่างไร?" },
        completion = { "446:1128226390:112386007", "ข้าเก็บตัวเป็นส่วนใหญ่ จะได้ไม่ถูกกล่าวหาเวลาของหาย หากต้องการอะไรหรือฝึก กลับมาได้เสมอ\n\nเราเข้าใจกัน ท้ายที่สุดไว้ใจได้แค่ครอบครัว... และที่นี่ก็เป็นแบบนั้นใช่ไหม? ไม่ว่า Gnomeregan ถูกยึดหรือเจออะไร เรามีกันคอยหนุนหลัง จริงไหม?" },
        required = { [9558] = { "20:27361453:611261813", "บันทึกข้อความเข้ารหัส" } },
        steps = { { "20:27361453:611261813", "บันทึกข้อความเข้ารหัส" } },
    },
    [3114] = { -- Glyphic Memorandum
        title = { "18:207394800:229908192", "บันทึกอักขระเวท" },
        objective = { "96:2143715899:655830976", "อ่าน Glyphic Memorandum แล้วคุยกับ Marryk Nurribit ใน Anvilmar เหนือ Coldridge Valley" },
        description = { "256:71175471:2114877581", "ระหว่างเจ้าช่วยข้า มีคนฝากบันทึกนี้ส่งให้เจ้า หาเวลาอ่าน คิดว่ามาจากอาจารย์เมจ Marryk อ่านแล้วไปพบใน Anvilmar เมื่อสะดวก" },
        progress = { "19:1164157581:1675920816 R 69:735070651:1930989269", "ว่าอะไรนะ {race}? พูดดังหน่อย หากไม่รังเกียจ ดื่มเบียร์หลายแก้วแล้วหูไม่ดีนัก" },
        completion = { "66:1269957598:724043888 N 233:659731819:1031166915", "อ้อ ใช่! ศาสตร์อาร์เคน... แน่นอน\n\nสิ่งที่ต้องรู้ {name}: อย่าสร้างปัญหามาก เก็บเหรียญไว้ซื้อเบียร์ให้ข้า... หรือคาถาที่ต้องการ และอยู่ให้ห่าง Gnomeregan นอกนั้นก็ขอให้มีวันดี! ข้าอยู่ที่นี่หากต้องการ ฝึก... หรืออะไรก็ตาม" },
        required = { [9573] = { "18:207394800:229908192", "บันทึกข้อความลงอักขระ" } },
        steps = { { "18:207394800:229908192", "บันทึกข้อความลงอักขระ" } },
    },
    [3115] = { -- Tainted Memorandum
        title = { "18:2100012021:1949031180", "บันทึกแปดเปื้อน" },
        objective = { "93:1626562360:2029795670", "อ่าน Tainted Memorandum แล้วคุยกับ Alamar Grimm ใน Anvilmar เหนือ Coldridge Valley" },
        description = { "279:1501961179:2139020614 N 49:1675552749:1975800393", "ระหว่างเจ้าช่วยข้า มีคนฝากบันทึกนี้ส่งให้เจ้า หาเวลาอ่าน คิดว่ามาจากอาจารย์วอร์ล็อก Alamar อ่านแล้วไปพบใน Anvilmar เมื่อสะดวก\n\nระวังด้วย {name} คนแถวนี้ไม่ค่อยไว้ใจพวกเจ้า" },
        progress = { "73:689206983:1817580267 N 399:1499636246:1185887473", "เยี่ยม! เห็นชัดว่าได้บันทึกข้า\n\nอย่าสนคนโง่รอบตัว {name} แสงสว่างศักดิ์สิทธิ์หรือ?! ดาบกับโล่หรือ?! ไม่ใช่ทางคนเปิดใจเช่นเรา ดูเวท “ปกติ” ทำอะไรกับบ้าน เมื่อรวมช่างประดิษฐ์บ้านั่น เผ่าเราแทบสูญพันธุ์ ตอนนี้ต้องพึ่งคนแคระ ซึ่งอยากเป็นมิตรมนุษย์มากกว่าช่วยสร้างบ้านคืน เราเหมือนพลเมืองชั้นสอง เห็นสายตาพวกเขาไหม?" },
        completion = { "294:1439870361:1357288000 N 129:726439280:1657816873", "แต่ไม่สำคัญ สิ่งสำคัญคือเจ้าเห็นแสงศักดิ์สิทธิ์ของตน! รู้ว่าพลังมาจากไหน และมีพันธมิตรของตนย่อม... รอบคอบกว่า พันธมิตรพิเศษที่ไม่ว่างานใดก็เชื่อฟังจนลมหายใจสุดท้าย\n\nนั่นคือหน้าที่ข้า {name} ฝึกพลังพิเศษขั้นต้นให้ได้ มาหาบ่อย ๆ จะสอนคาถาเพิ่มเท่าที่ทำได้" },
        required = { [9577] = { "18:2100012021:1949031180", "บันทึกข้อความแปดเปื้อน" } },
        steps = { { "18:2100012021:1949031180", "บันทึกข้อความแปดเปื้อน" } },
    },
    [96393] = { -- Old Ironforge Incursion
        title = { "23:348349966:1859002695", "การบุก Old Ironforge" },
        objective = { "88:2121635218:381181784", "เข้า Hall of Thanes ใต้ Old Ironforge แล้วนำ Head of Durgen Dirgehammer มา" },
        description = { "377:733673523:1835162608", "รวบรวมสหายลงถ้ำใต้ Old Ironforge เข้า Hall of Thanes แล้วฝ่าไปคลังชั้นล่าง\n\nภาษา Dark Iron ข้าขึ้นสนิมนิด แต่พออ่านชื่อ Durgen Dirgehammer คงเป็นผู้บัญชาการ เอาหัวส่ง King Magni Bronzebeard\n\nอ้อ บอกด้วยว่าสหายเก่า Farsen ฝากความคิดถึง!" },
        progress = { "25:1391198556:1450912220", "ต้องการอะไรพลเมือง?" },
        completion = { { "505:1550179283:1222343825", "352:284548369:2101421723 N 143:384120842:227302340", "352:284548369:2101421723 C 143:384120842:227302340", "352:284548369:2101421723 R 143:384120842:227302340" }, "Dark Iron บุกใต้เท้าเราหรือ? โล่งใจที่ผู้บัญชาการถูกจัดการแล้ว\n\nยามจะลงกวาดส่วนที่เหลือ เราจะปิดช่องและเสริมชั้นล่าง ไม่ให้บุกได้อีก\n\nขอบใจที่รับใช้ Ironforge นักผจญภัย รับสิ่งนี้แทนความซาบซึ้ง อ้อ หากพบเฒ่า Wildhammer รักหิน Farsen อีก บอกให้มาเยี่ยมข้าเป็นเรื่องเป็นราว", variants = { { "351:2031607294:507831531 C 143:384120842:227302340", "Dark Iron บุกใต้เท้าเราหรือ? โล่งใจที่ผู้บัญชาการถูกจัดการแล้ว\n\nยามจะลงกวาดส่วนที่เหลือ เราจะปิดช่องและเสริมชั้นล่าง ไม่ให้บุกได้อีก\n\nขอบใจที่รับใช้ Ironforge {class} รับสิ่งนี้แทนความซาบซึ้ง อ้อ หากพบเฒ่า Wildhammer รักหิน Farsen อีก บอกให้มาเยี่ยมข้าเป็นเรื่องเป็นราว" } } },
        required = { [274286] = { "25:745440976:73481273", "ศีรษะของ Durgen Dirgehammer" } },
        steps = { { "25:745440976:73481273", "ศีรษะของ Durgen Dirgehammer" } },
    },
    [98574] = { -- Hallowed Memorandum
        title = { "19:1068724748:590657143", "บันทึกศักดิ์สิทธิ์" },
        objective = { "72:1841410258:2070605094", "อ่าน Hallowed Memorandum แล้วคุยกับ Branstock Khalder ใน Anvilmar" },
        description = { "261:648481176:1715014593", "ระหว่างเจ้าช่วยข้า มีคนฝากบันทึกนี้ส่งให้เจ้า หาเวลาอ่าน คิดว่ามาจากอาจารย์นักบวช Branstock อ่านแล้วไปพบใน Anvilmar เมื่อสะดวก" },
        progress = { "321:350909533:1922549699", "อา โนมอีกคนมาเรียนแสงสว่าง! ความผูกพันกับแสงอาศัยความใคร่รู้และปัญญา ซึ่งโนมมีมาก วิถีแสงไม่ใช่ศาสตร์เทคนิค แต่เป็นปริศนาที่ให้ทั้งบทเรียนชีวิตและพรใช้ได้จริง" },
        completion = { "377:959909673:1440332292", "ด้วยเวลาและฝึก เจ้าจะพบแสงด้านใหม่ คล้ายประสานความคิดกับความรู้สึก เมื่อผูกพันลึกขึ้น กลับมาคุยสิ่งที่เรียนรู้ ยินดีแสดงวิธีใช้พลังเพื่อรักษาหรือลงทัณฑ์คนชั่ว แลกเงินบริจาคเล็กน้อยแน่นอน!" },
        required = { [282338] = { "19:1068724748:590657143", "บันทึกข้อความศักดิ์สิทธิ์" } },
        steps = { { "19:1068724748:590657143", "บันทึกข้อความศักดิ์สิทธิ์" } },
    },
    [98581] = { -- Archaic Rune
        title = { "12:750247778:893776777", "รูนโบราณ" },
        objective = { "63:129741370:1044826999", "อ่าน Archaic Rune แล้วคุยกับ Teo Hammerstorm ใน Anvilmar" },
        description = { "316:1278904121:913498004", "ระหว่างเจ้าช่วยข้า มีคนฝากรูนนี้ส่งให้เจ้า หาเวลาอ่าน ลายสลักแบบ Wildhammer ทำให้เดาว่ามาจากอาจารย์ชามาน Teo Hammerstorm อ่านแล้วไปพบใน Anvilmar เมื่อสะดวก" },
        completion = { "339:1579025857:1323644634", "ตระกูล Wildhammer สืบทอดวิชาชาแมนมาหลายปี และตอนนี้คนแคระ Bronzebeard ก็ได้ร่วมสืบทอดวิชานี้ด้วย ข้ามาที่นี่เพื่อถ่ายทอดคำสอนและชี้แนะชาแมนรุ่นใหม่ที่กำลังเรียนวิถีแห่งธาตุ มาหาข้าได้ถ้าอยากฝึกเวทดิน ลม ไฟ และน้ำเพิ่มเติม" },
        progress = { "150:1704529822:1916220597 C 1:46:46", "อ้อ เจ้าอ่านรูนออกแล้วหรือ? อักขระเก่าแก่ที่สุดบางส่วนของเราฝังพลังแห่งธาตุไว้ในรูนนี้ แสดงว่าเจ้ามีแววจะเป็น {class}", variants = { { "157:473218653:1024176776", "อ้อ เจ้าอ่านรูนออกแล้วหรือ? อักขระเก่าแก่ที่สุดบางส่วนของเราฝังพลังแห่งธาตุไว้ในรูนนี้ แสดงว่าเจ้ามีแววจะเป็นชาแมน" } } },
        required = { [282400] = { "12:750247778:893776777", "รูนโบราณ" } },
        steps = { { "12:750247778:893776777", "รูนโบราณ" } },
    },
    [161] = { -- A Dark Threat Looms
        title = { "19:101932833:265746682", "ภัยมืดคืบคลาน" },
        objective = { "128:561052728:665332797", "Chief Engineer Hinderweir ต้องการให้เจ้านำผงกลิ่นประหลาดไปให้ Ashlan Stonesmirk ผู้เชี่ยวชาญวัตถุระเบิดใน Dun Modr" },
        description = { "297:1105804246:55094885 N 163:1335322277:1704966706", "หากสงสัยถูก นี่คือผงระเบิดชนิดหนึ่ง ต้องให้ผู้เชี่ยวชาญวิเคราะห์เพื่อรู้ว่ากำลังเจออะไร Ashlan Stonesmirk ถูกส่งประจำกองรักษา Dun Modr กับ Thandol Span ข้าต้องให้เจ้าเดินทางสำคัญและอันตราย {name}\n\nผ่าน Algaz Gate ตามถนนผ่าน Wetlands หา Stonesmirk ใน Dun Modr ฟังให้ดี อยู่บนถนน อย่าหยุดเพื่อสิ่งใด!" },
        progress = { { "116:1863935595:2072399037", "115:531330070:695578311" }, "พูดอะไรหรือ? ข้าได้ยินแต่เสียงอื้อในหู ว่าแต่ถืออะไรมา?", variants = { { "115:484888106:1675207205", "เจ้าพูดอะไรหรือ ไอ้หนู? ข้าไม่ได้ยินอะไรเลยนอกจากเสียงอื้อในหู ว่าแต่เจ้าถืออะไรมา?" } } },
        completion = { "46:2114636014:330976145", "อา เฒ่า Hinderweir คิดถูกที่กังวล" },
        required = { [2563] = { "23:1916649778:2144219364", "ผงกลิ่นประหลาด" } },
        objectiveLabels = {
            item = { ["Strange Smelling Powder"] = "ผงกลิ่นประหลาด" },
        },
    },
