    [217] = { -- In Defense of the King's Lands
        title = { "30:1718227844:107885185", "ปกป้องดินแดนราชา" },
        objective = { "138:639465082:1276930627", "ฆ่าผู้นำโทรกก์ Grawmug กับยามสองตัว Gnasher และ Brawler แล้วรายงาน Captain Rugelfuss ที่หอยามใต้" },
        description = { "N 307:377125533:2076004087 N 183:1762725698:837125794", "{name} หน่วยสอดแนมระบุผู้นำการบุกล่าสุดแล้ว โทรกก์ใน Loch Modan ดูจะตามหัวหน้า Grawmug แต่เขามียามแน่นหนา Gnasher กับ Brawler ยามชั้นยอดสองตัวไม่เคยห่าง\n\nหากเห็นว่าคู่ควร {name} ข้าอยากให้เจ้าลอบสังหาร Grawmug กับลูกสมุนทั้งสอง เมื่อผู้นำตาย เราอาจผลักมันกลับใต้ดินได้" },
        progress = { "174:1760334396:1410502327 N 1:46:46", "Grawmug กับยาม Gnasher และ Brawler ยังอยู่ งานไม่จบจนทั้ง 3 ตาย อาณาจักรคนแคระหวังพึ่งเจ้า {name}" },
        completion = { "16:959884130:63492255 N 129:464648391:444133947", "ยอดเยี่ยม {name}! เจ้านำความหวังให้ Loch Modan เมื่อ Grawmug ตาย โอกาสขจัดโทรกก์จากผืนดินก็ดีขึ้น" },
        objectiveLabels = {
            monster = { ["Grawmug slain"] = "ปราบ Grawmug", ["Gnasher slain"] = "ปราบ Gnasher", ["Brawler slain"] = "ปราบ Brawler" },
        },
    },
    [224] = { -- In Defense of the King's Lands
        title = { "30:1718227844:107885185", "ปกป้องดินแดนราชา" },
        objective = { "122:2093218471:2004457662", "Mountaineer Cobbleflint ที่หอยามใต้ต้องการให้เจ้าฆ่า Stonesplinter Troggs 10 ตัว และ Stonesplinter Scouts 10 ตัว" },
        description = { "29:424556318:311864096 N 430:361416730:1813662785", "ต้องปกป้อง Loch {name}! ทหารราชาจำนวนมากสู้กล้าในแนวรบไกล แนวหลังจึงถูกถาโถม โทรกก์ขุดขึ้นทุกซอก เป็นภัยใหญ่สุดต่อ Ironforge ต้องทำลายสัตว์กลายพันธุ์น่าขยะแขยง!\n\nนักผจญภัยผู้กล้า ไปทำลายภัยนี้ ฆ่า Stonesplinter Troggs 10 และ Stonesplinter Scouts 10 แล้วรายงาน" },
        progress = { "27:1059333176:644729671 N 141:1432256163:161707774", "Loch Modan ถูกล้อม {name}! ต้องให้สมาชิก Alliance แข็งแรงทุกคนช่วย ฆ่า Stonesplinter Troggs 10 กับ Stonesplinter Scouts 10 แล้วหรือยัง?" },
        completion = { "11:534428891:784080240 N 399:572897730:1773427324", "ทำได้ดี {name}! กล้าหาญน่าทึ่งในสนาม ความพยายามเช่นนี้จะชนะโทรกก์ เจ้ารับใช้ King Magni ได้ดี\n\nหากเหมาะกับการผจญภัยแบบนี้ คุยกับ Mountaineer Gravelgaw กัปตันให้ลาดตระเวนหนัก เขาคงต้องการความช่วยเหลือ อยู่ด้านในหอ" },
        objectiveLabels = {
            monster = { ["Stonesplinter Trogg slain"] = "ปราบ โทรกก์ Stonesplinter", ["Stonesplinter Scout slain"] = "ปราบ หน่วยสอดแนม Stonesplinter" },
        },
    },
    [237] = { -- In Defense of the King's Lands
        title = { "30:1718227844:107885185", "ปกป้องดินแดนราชา" },
        objective = { "149:1649289961:1006293314", "Mountaineer Gravelgaw ในหอยามใต้ต้องการให้เจ้าฆ่า Stonesplinter Skullthumpers 10 ตัว และ Stonesplinter Seers 10 ตัว แล้วกลับไปรายงานเขา" },
        description = { "70:1125692522:363538941 R 374:573815166:82189476", "Mountaineer Cobbleflint ชมเจ้าทุกอย่าง {race} ข้าจึงฝากภารกิจสำคัญ ต้องกดดันโทรกก์รุกรานจนพี่น้องคนแคระกลับจากแนวหน้า Alliance\n\nไปเนินใต้ฆ่า Stonesplinter Skullthumpers 10 และ Stonesplinter Seers 10 เพื่อซื้อเวลา เสร็จแล้วรายงาน" },
        progress = { "19:1663884535:151746304 R 186:1332468296:837467289", "ต้องการเวลาเพิ่ม {race} คำสั่งคือฆ่า Stonesplinter Skullthumpers 10 กับ Stonesplinter Seers 10 กดดันศัตรูจนกำลังเสริมมา ไม่ใช่เวลาว่างงาน" },
        completion = { "36:1297734985:507126925 R 445:1857151978:328867525", "ทำภารกิจได้ดี {race} ราชาคงภูมิใจ\n\nแต่กำลังเสริมที่สัญญาไม่มา แนวหน้า Alliance ดูเหมือนทะเลแดงจากเลือดพี่น้องที่ล้ม ข่าวสูญเสียขมขื่น แต่จะให้ตายเปล่าไม่ได้ ต้องรวมกำลังในยุคมืดและคืนเกียรติ Alliance\n\nคุย Mountaineer Wallbang รับงานใหม่ ตอนนี้ต้องการเจ้ากว่าครั้งไหน" },
        objectiveLabels = {
            monster = { ["Stonesplinter Skullthumper slain"] = "ปราบ นักทุบกะโหลก Stonesplinter", ["Stonesplinter Seer slain"] = "ปราบ ผู้พยากรณ์ Stonesplinter" },
        },
    },
    [250] = { -- A Dark Threat Looms
        title = { "19:101932833:265746682", "ภัยมืดคืบคลาน" },
        objective = { "152:449963620:589279860", "สำรวจใกล้ทางลาดตะวันออกของเขื่อน แล้วนำเบาะแสที่อาจบอกแผน Dark Iron Dwarves ไปให้ Chief Engineer Hinderweir" },
        description = { "348:1034523221:514848002 N 121:373254475:699947634", "ขอบคุณดวงดาวที่มีคนห่วงเขื่อน Thandol Span ถูกทำลาย ต่อด้วย Dun Modr ถูกปล้น! มั่นใจว่าเขื่อนเป็นเป้าต่อไปของ Dark Iron คนรักษาความปลอดภัยส่วนใหญ่ถูกส่งแนวหน้า Alliance รวมผู้ตรวจเก่งสุด\n\nจึงต้องให้เจ้าช่วย {name} เห็น Dark Iron Sappers แถวทางลาดตะวันออก สำรวจแล้วเอาเบาะแสมา" },
        completion = { "65:1945656985:392819159", "ถังน่าสงสัยมีผงกลิ่นประหลาดอยู่ภายใน" },
    },
    [255] = { -- Mercenaries
        title = { "11:2045466474:1529602523", "ทหารรับจ้าง" },
        objective = { "117:1295394441:537800987", "Magistrate Bluntnose แห่ง Thelsamar จ้างให้เจ้าฆ่า Mo'grosh Ogres 4 ตัว, Mo'grosh Brutes 4 ตัว และ Mo'grosh Enforcers 4 ตัว" },
        description = { "351:1819903412:1867526514 C 142:160508809:2139387195", "รอสองเดือนกว่าจะได้ข่าว Ironforge ว่าส่งทหารนิดหน่อยป้องกันเรา แล้วอีกสองเดือนกว่าจะมา! เมืองไร้คนคุ้มก็แย่แล้ว จุดขุดกับเขื่อน เขื่อนด้วยนะ ก็เปิดให้โจมตี\n\nดูไม่มีทางเลือก ต้องจ้างนักสู้\n\nเจ้าล่ะ ดูเหมาะ {class} ออกร์ตั้งค่ายตะวันออกเฉียงเหนือของทะเลสาบ รวบรวมคนแล้วช่วยขจัดภัยเมืองได้ไหม?" },
        progress = { "22:702871304:843458840", "ได้ผลบ้างไหม?" },
        completion = { "213:560751948:314336902", "อา ข่าวเยี่ยม! ข้ากับชาว Thelsamar ซาบซึ้ง หากแก้ปัญหาออกร์ได้ จะหันไปสนโทรกก์บ้านั่นได้ยิ่งดี" },
        objectiveLabels = {
            monster = { ["Mo'grosh Ogre slain"] = "ปราบ อ็อกเกอร์ Mo'grosh", ["Mo'grosh Brute slain"] = "ปราบ อ็อกเกอร์จอมโหด Mo'grosh", ["Mo'grosh Enforcer slain"] = "ปราบ มือปราบ Mo'grosh" },
        },
    },
    [256] = { -- WANTED: Chok'sul
        title = { "16:278774944:1932902584", "ประกาศจับ: Chok'sul" },
        objective = { "70:2106578723:738083295", "ฆ่า Chok'sul แล้วนำหัวไปให้ Magistrate Bluntnose แห่ง Thelsamar" },
        description = { "416:1219788463:363575585", "ตามคำสั่งผู้พิพากษา Thelsamar:\n\nChok'sul ออกร์ที่เชื่อว่าเป็นผู้นำประสานโจมตีเมือง Thelsamar, Stonewrought Dam และจุดขุด ต้องถูกสังหารด้วยทุกวิถีจำเป็น\n\nจะจ่ายค่าตอบแทนเมื่อนำหลักฐานความตายให้ผู้พิพากษา\n\nพบ Chok'sul ล่าสุดที่ค่ายออกร์ตะวันออกเฉียงเหนือของ Loch Modan" },
        progress = { "41:2044135350:1668288896", "ว่าอย่างไร? มีอะไรให้ช่วยหรือ?" },
        completion = { "235:192016340:56256382", "แหวะ! นั่นอะไร ทำไมเอามา...\n\nบ้าเอ๊ย! ใช่ไหม? ให้ตายเถอะ หัวออกร์นั่นหรือ? งั้นผลงานยอดเยี่ยม! นี่รางวัลกับคำขอบคุณจากข้าและชาว Thelsamar" },
        required = { [2561] = { "15:1259460998:2047808331", "หัวของ Chok'sul" } },
        objectiveLabels = {
            item = { ["Chok'sul's Head"] = "หัวของ Chok'sul" },
        },
    },
    [257] = { -- A Hunter's Boast
        title = { "16:266512831:1262581897", "คำโอ้อวดของนักล่า" },
        objective = { "101:2118775524:999982003", "ฆ่า Mountain Buzzards 6 ตัว แล้วกลับไปหา Daryl the Youngling ที่ Farstrider Lodge ภายใน 15 นาที" },
        description = { "498:1960904574:1715853890", "คิดจะแข่งไหวพริบ Daryl the Bold หรือ? ข้าไม่คิดว่าจะไหว! แต่ลองได้เต็มที่ นี่ความท้าทายเหนือความสามารถ อย่าเสียใจหากทำไม่ได้\n\nฝูงแร้งทำรังใน Loch Modan ลองล่าดูสิ หากผ่านในสิบห้านาที จะให้ธนูหรือปืนข้า\n\n<เขามองเจ้าอย่างดูแคลน>\n\nดูไม่มีอะไรให้เสียมากอยู่แล้ว" },
        progress = { "29:1201890299:1803506407 N 27:233514566:630820524", "ไม่สำเร็จหรือ? อย่าเสียใจ {name}...\n\nไม่ใช่ทุกคนเป็นข้าได้" },
        completion = { "32:886448738:1629455776 N 303:969859456:2063476497", "อะไร? สำเร็จ?\n\nฟังนะ {name}ama อย่าเหลิงไป เด็กหนวดไม่ขึ้นถือธนูก็ฆ่า... ตัวเล็กพวกนั้นได้ หวังว่าไม่ชอบฆ่าแร้งเกินไป ไม่อยากให้สูญพันธุ์ใช่ไหม?\n\nเอ่อ... อย่าให้ใครบอกว่า Daryl the Bold ไม่รักษาคำพูด" },
        objectiveLabels = {
            monster = { ["Mountain Buzzard slain"] = "ปราบ แร้งภูเขา" },
        },
    },
    [258] = { -- A Hunter's Challenge
        title = { "20:1976569730:1025626647", "ความท้าทายของนักล่า" },
        objective = { "104:322822162:1005409682", "ฆ่า Elder Mountain Boars 5 ตัว แล้วกลับไปหา Daryl the Youngling ที่ Farstrider Lodge ภายใน 12 นาที" },
        description = { "N 480:1336939594:729386619", "{name}ath ใช่ไหม? ดูภูมิใจจนแทบระเบิดที่ผ่านครั้งแรก อย่างที่บอก ไม่ใช่เรื่องใหญ่\n\nลองล่าหมูป่า เชื่อเถอะ ไม่ใช่แบบ Coldridge Valley ระวังให้ดี คราวนี้ให้สิบสองนาที\n\nอย่าเสียใจหากพลาด หากสำเร็จจะให้เสื้อที่ใส่อยู่!\n\nเคยเล่าว่าได้แผลเป็นโด่งดังอย่างไรไหม? ไม่หรือ? สองปีก่อน..." },
        progress = { "116:223492454:2037570950 N 34:10726065:1234613194", "เป็นธรรมดาที่สงสารตัวเองเมื่อคนเพิ่งออกโลกทำให้ขายหน้า อย่าเสียใจ {name}ah\n\nหืม? เรียกชื่อผิดหรือ?" },
        completion = { "343:1356627163:1825047300", "ดูโทรมหน่อย หมูป่าคงสร้างปัญหา? ไม่ห่วง ข้าจะไม่บอกใคร เข้าใจว่าลำบากอยู่แล้วโดยไม่ต้องถูกคนนินทา\n\nโอ้! ฆ่าได้หรือ? ข้า... เอ่อ... หมายถึง ไม่แปลกใจ! เด็กคนไหนก็... พนัน?\n\nพนันอะไร?" },
        objectiveLabels = {
            monster = { ["Elder Mountain Boar slain"] = "ปราบ หมูป่าภูเขาวัยชรา" },
        },
    },
    [263] = { -- In Defense of the King's Lands
        title = { "30:1718227844:107885185", "ปกป้องดินแดนราชา" },
        objective = { "125:1083955909:1993845001", "Mountaineer Wallbang ที่หอยามใต้ต้องการให้เจ้าฆ่า Stonesplinter Shaman 10 ตัว และ Stonesplinter Bonesnappers 10 ตัว" },
        description = { "58:1841852591:76277121 N 12:1911038966:774425088 R 172:172988735:913051985 C 167:264914161:701220466", "Mountaineers บอกว่ากล้าและเก่ง {name} ต้องการ{race}เช่นเจ้า โทรกก์ไม่ดีขึ้น กำลังสำรองถูกเรียกแนวหน้า เราเหลือลำพัง แต่เมื่อมี {class} ช่ำชอง มาดูว่าทำอะไรได้\n\nไปฆ่า Stonesplinter Shaman 10 กับ Stonesplinter Bonesnappers 10 ดูว่าจะสมชื่อผู้สังหารโทรกก์หรือไม่" },
        progress = { "128:166163501:1900008280 N 31:1121884249:1984381371", "กลับเร็วหรือ? หากข้าบอกไม่ชัด ต้องฆ่า Stonesplinter Shaman 10 กับ Stonesplinter Bonesnappers 10 {name} ไปจัดการ ผู้สังหารโทรกก์!" },
        completion = { "38:1607322346:1283762545 N 248:547233796:552971963 N 1:46:46", "รู้ทันทีที่เห็น {name} ว่าจะทำ Ironforge ภูมิใจ รับใช้ King Magni ดีแล้ว เมื่อพิสูจน์ภักดีต่ออาณาจักร ลองคุยกัปตันว่าไว้ใจให้งานสูงกว่านี้ไหม\n\nข้าคารวะ {name}" },
        objectiveLabels = {
            monster = { ["Stonesplinter Shaman slain"] = "ปราบ ชาแมน Stonesplinter", ["Stonesplinter Bonesnapper slain"] = "ปราบ นักหักกระดูก Stonesplinter" },
        },
    },
    [267] = { -- The Trogg Threat
        title = { "16:926849838:737326384", "ภัยโทรกก์" },
        objective = { "75:296699001:590935813", "นำ Trogg Stone Teeth 8 ชิ้น ไปให้ Captain Rugelfuss ที่หอยามใต้" },
        description = { "C 499:1959491258:1168376426", "{class} เจ้าอาจรู้เรื่องภัยโทรกก์ที่คืบเหนือดินแดนคนแคระ เมื่อกำลังสำรอง Ironforge ถูกเรียกแนวหน้า Alliance เราเหลือป้องกันไม่พอ กองข้าต้องเฝ้าประตู ทิ้งฐานไม่ได้เพราะกลัวบุก\n\nแต่ต้องกดดันโทรกก์ในเนิน หากพร้อม จงบุก นำ Trogg Stone Teeth 8 ชิ้นเป็นหลักฐาน" },
        progress = { "84:628389964:837403268 N 1:46:46", "มี Trogg Stone Teeth 8 ชิ้นให้ดูหรือ? หากไม่ ยังมีงานต้องทำ {name}" },
        completion = { "22:171017383:806758228 N 117:1807712720:1361949666", "ข้าประทับใจ {name} เจ้าช่วยเผ่าคนแคระอย่างมากที่ปกป้องผืนดิน King Magni Bronzebeard คงภูมิใจ!" },
        required = { [2536] = { "17:1303496077:1378152553", "ฟันหินของโทรกก์" } },
        steps = { { "17:1303496077:1378152553", "ฟันหินของโทรกก์" } },
    },
    [271] = { -- Vyrin's Revenge
        title = { "15:1633828920:762952442", "การเอาคืนของ Vyrin" },
        objective = { "87:1630253804:1913756753", "ฆ่า Ol' Sooty แล้วแสดงผลงานให้ Daryl the Youngling ที่ Farstrider Lodge" },
        description = { "502:467503069:592060769", "สนใจเอาคืนท่านผู้กล้านั่นไหม? ต้องยอมรับอย่างเจ็บใจว่า Daryl มีฝีมือ\n\nปีก่อน หมีใหญ่เป็นเป้า Farstrider Lodge แต่นักล่าไม่มีใครสำเร็จ Daryl เลยลอง ผลที่ได้คือแผลน่าเกลียดเหนือตา\n\nฆ่าหมี แล้วแม้เขาคงพูดไม่ออกสักครั้ง\n\nOl' Sooty อยู่รอบรังในเนินเหนือ Thelsamar" },
        progress = { "4:1110228981:147916455 N 179:29605597:1849427436", "อา {name}! กลับเร็ว? คงล่าอีกแล้ว หากพลาดไม่ต้องห่วง ระยะยาวจะเก่งขึ้น!\n\n...แย่กว่านี้คงยาก..." },
        completion = { "320:493764461:1888058900", "เอ่อ... นี่อะไร? ดูเหมือนหัวหมี\n\n<เขาลูบแผลเป็นโดยไม่รู้ตัว>\n\nผลงานน่าสนใจ คงไม่ใช่หมีครั้งนั้น...\n\n<เขาพูดค้างแล้วเริ่มสั่นให้เห็น>\n\nเอาออกไป เอาออก! เอาของสยองนี่ไป!" },
        required = { [2713] = { "16:365196957:1308881896", "ศีรษะของเจ้าเฒ่า Sooty" } },
        steps = { { "16:365196957:1308881896", "ศีรษะของเจ้าเฒ่า Sooty" } },
    },
    [273] = { -- Resupplying the Excavation
        title = { "26:704974239:2119475348", "เติมเสบียงจุดขุด" },
        objective = { "18:266202448:735443894", "คุยกับ Huldar" },
        description = { "367:1440147314:407985808", "ยังไม่สาย ไปหา Huldar ได้ คงไปไม่ไกล แม้ Miran กับ Saean แข็งแรง แต่แบกถังหนักก็ไปได้ไม่เร็ว\n\nใช้ทางปกติไปจุดขุด ออกเมืองทางใต้แล้วตามโค้ง Loch\n\nคงหาไม่ยาก เว้นแต่ถึงแล้ว" },
        completion = { "259:1244214506:734744323", "ฮึ ต้องมากกว่าการซุ่ม Dark Iron จึงจะหยุดส่งของได้!\n\nแต่ Saean... ไม่เคยสงสัยว่าสนับสนุนพวกนั้น ทำงานด้วยเกือบปี... อาจมองข้ามสัญญาณ\n\nไว้คิดภายหลัง" },
        objectiveLabels = {
            event = { ["Find Huldar, Miran, and Saean"] = "ตามหา Huldar, Miran และ Saean" },
        },
    },
    [274] = { -- A Dark Threat Looms
        title = { "19:101932833:265746682", "ภัยมืดคืบคลาน" },
        objective = { "103:1433022093:637933541", "Ashlan Stonesmirk ต้องการให้เจ้ากลับไปหา Chief Engineer Hinderweir และแจ้งการค้นพบใหม่" },
        description = { "436:868233383:213064980", "ไม่ใช่ดินระเบิดธรรมดา ดูผลึกเงินเล็กกับกลิ่นเฉพาะ! ชัดว่านี่ Seaforium Powder มันไม่อันตรายนัก แต่พอเปียก อาจระเบิด Ironforge หลุดจากภูเขา\n\nหยุดปฏิกิริยาได้ด้วยส่วนประกอบสี่อย่าง: พิษ Lurker, ผลึก Mo'Grosh บด, น้ำตาจระเข้ และ Disarming Colloid นี้ รีบบอก Hinderweir ก่อนสาย!" },
        progress = { "35:1018763524:1708062864", "เอาอะไรจาก Ashlan มา?" },
        completion = { "47:344729809:927551923", "Disarming Colloid? สำหรับ Seaforium? โอ้สวรรค์!" },
        required = { [2609] = { "17:264373389:1892813749", "คอลลอยด์ปลดชนวน" } },
        steps = { { "17:264373389:1892813749", "คอลลอยด์ปลดชนวน" } },
    },
    [278] = { -- A Dark Threat Looms
        title = { "19:101932833:265746682", "ภัยมืดคืบคลาน" },
        objective = { "101:1411689600:1819827640", "Chief Engineer Hinderweir ต้องการให้เจ้าเก็บ Lurker Venom, Mo'grosh Crystal และ Crocolisk Tear" },
        description = { "54:866379746:657573974 N 396:1296943548:1761093287", "เริ่มเก็บส่วนประกอบหยุดระเบิดทันที {name} Lurker Venom จากแมงมุมพื้นเมือง Loch Modan น้ำตาจระเข้ก็ใน Loch แต่ Mo'Grosh Crystal หายาก ออกร์ตะวันออกเฉียงเหนือขุดมัน แต่เป็นของหายากมาก\n\nต้องพร้อมหยุดการโจมตี Dark Iron! กลับเมื่อครบ แล้วข้าจะเตรียมส่วนผสม" },
        progress = { "54:808297372:1376122713", "มีของจำเป็นไหม? เวลาสำคัญมาก!!" },
        completion = { "14:245818094:983663440 N 1:33:33", "ทันเวลาพอดี {name}!" },
        required = { [2606] = { "12:1398986046:1762648400", "พิษของ Lurker" }, [2607] = { "16:299183298:139941999", "ผลึก Mo'grosh" }, [2939] = { "14:1855177358:1529920189", "น้ำตาครอโคลิสก์" } },
        steps = { { "12:1398986046:1762648400", "พิษของ Lurker" }, { "16:299183298:139941999", "ผลึก Mo'grosh" }, { "14:1855177358:1529920189", "น้ำตาครอโคลิสก์" } },
    },
    [280] = { -- A Dark Threat Looms
        title = { "19:101932833:265746682", "ภัยมืดคืบคลาน" },
        objective = { "153:454384077:1932340112", "Chief Engineer Hinderweir ต้องการให้เจ้าว่ายลงฐานเขื่อน หาถังดินระเบิด แล้วคน Disarming Mixture ลงไปเพื่อป้องกันการระเบิด" },
        description = { "399:1218735193:1611857924", "วันนี้เห็น Dark Iron Insurgents ว่ายหาเขื่อนพร้อมถังใหญ่ ไม่มี Mountaineers หยุด! กลัวว่าฝัง Seaforium ไว้ฐานเขื่อน ระเบิดได้ทุกเมื่อ! ขอผสมของทั้งหมดเป็น Disarming Mixture เรียบร้อย\n\nนำไปคนในถังก่อนสาย รีบ!" },
        progress = { "37:304317963:1137775306", "ฝาถังค่อย ๆ หมุนเปิด" },
        completion = { "61:118037752:1530182393", "ถังมีเสียงฟู่เล็กน้อยเมื่อ Disarming Mixture ลงไป" },
        required = { [2610] = { "17:1419177150:1852946367", "สารผสมปลดชนวน" } },
        steps = { { "17:1419177150:1852946367", "สารผสมปลดชนวน" } },
    },
    [283] = { -- A Dark Threat Looms
        title = { "19:101932833:265746682", "ภัยมืดคืบคลาน" },
        objective = { "105:596243990:1747995487", "Disarming Mixture ดูได้ผล กลับไปรายงานข่าวดีแก่ Chief Engineer Hinderweir" },
        description = { "25:1324352586:1593505222", "ถังมีเสียงฟู่เล็กน้อย" },
        completion = { "19:1061876233:111335988 N 197:1844454514:334804127 C 68:781508569:1866892117", "ขอบใจมาก {name}!! เจ้าช่วย Stonewrought Dam! หากไม่มี Dark Iron ผู้ก่อการร้ายคงทำลายสถานที่ยิ่งใหญ่สำเร็จ เจ้าทำอาณาจักรกับ Alliance ภูมิใจ {class} ผู้กล้า\n\nเขื่อนปลอดภัยอีกครั้ง... อย่างน้อยตอนนี้..." },
    },
    [297] = { -- Gathering Idols
        title = { "15:1805012231:1215722314", "เก็บรูปเคารพ" },
        objective = { "42:917026462:1369172343", "นำ Carved Stone Idols 8 ชิ้น ไปให้ Magmar Fellhew" },
        description = { "447:503576903:1782442194", "ก่อนโทรกก์โผล่ เราพบรูปเคารพแกะสลักแปลกจำนวนมาก แต่ยังไม่ทันศึกษา มันก็ไล่เราออกซาก! รูปเคารพทำให้โทรกก์คลั่ง\n\nนำมา 8 ชิ้น ข้าอยากศึกษาและเอาออกจากมือมัน! หาได้จากโทรกก์ที่ยึดจุดขุด" },
        progress = { "81:698902299:131818139", "มีรูปเคารพหรือยัง? ต้องศึกษาแล้วรายงาน Ironforge!" },
        completion = { "27:2105830793:1296022391 N 135:639195687:1227796120", "ได้แล้ว! ทำได้ดี {name}!\n\nดูไม่บอบช้ำมากแม้เจอโทรกก์คลั่ง ข้าจะจับตาดูเจ้า... มีแวว" },
        required = { [2636] = { "17:1232609945:1777760608", "รูปเคารพหินแกะสลัก" } },
        steps = { { "17:1232609945:1777760608", "รูปเคารพหินแกะสลัก" } },
    },
    [298] = { -- Excavation Progress Report
        title = { "26:1078781644:1544456993", "รายงานคืบหน้าการขุด" },
        objective = { "63:1680882425:1026902321", "นำ Ironband's Progress Report ไปให้ Jern Hornhelm ใน Thelsamar" },
        description = { "247:211703777:888899745", "ต้องส่งรายงานคืบหน้าไป Thelsamar พร้อมย้ำขอดินระเบิดเพิ่ม! นี่รายงาน นำให้ Jern Hornhelm ผู้ประสานท้องถิ่นเรา\n\nไม่ยาก แต่ต้องทำ" },
        progress = { "47:559540074:1584531935", "โอ้ รายงานคืบหน้าจุดขุด? ดีมาก!" },
        completion = { "289:661111002:743994052", "ชิ! Ironband มีปัญหาโทรกก์ สงสัยต้องการดินระเบิดช่วยขุดหรือสู้สัตว์พวกนั้น...\n\nอย่างไรก็คุ้ม!\n\nแต่แปลก ข้าส่งไปมากเมื่อหลายสัปดาห์ก่อน หายไหน..." },
        required = { [2637] = { "26:2027256620:1806603489", "รายงานความคืบหน้าของ Ironband" } },
        steps = { { "26:2027256620:1806603489", "รายงานความคืบหน้าของ Ironband" } },
    },
    [301] = { -- Report to Ironforge
        title = { "19:1780550991:482960111", "รายงานต่อ Ironforge" },
        objective = { "56:1115430446:49060603", "นำ Ironband's Progress Report ไปให้ Prospector Stormpike" },
        description = { "382:1336636877:1607716263", "ต้องอนุมัติเพื่อส่งดินระเบิดเพิ่ม เอารายงานไปสำนักงานใหญ่ Explorers' League ใน Ironforge\n\nนี่ ส่ง Prospector Stormpike แล้วอย่าลืมหลบ เขาใจร้อน คงไม่ชอบข่าวคืบหน้าช้าของ Ironband\n\nเขาอยู่ Assembly of Explorers" },
        progress = { "62:528778871:1924774264 C 58:1964267681:250120924", "พวก Stormpike ไม่ชอบเรื่องหยุมหยิม {class} หวังว่าข่าวคู่ควรกับความสนใจมีค่าของข้า" },
        completion = { "148:1648605760:1556878744", "Ironband บ้า! ข้าส่งดินระเบิดไปมากหลายสัปดาห์ แต่รายงานไม่กล่าวเลย\n\nงั้น... ดินระเบิดหายไหน?!?" },
        required = { [2637] = { "26:2027256620:1806603489", "รายงานความคืบหน้าของ Ironband" } },
        steps = { { "26:2027256620:1806603489", "รายงานความคืบหน้าของ Ironband" } },
    },
    [302] = { -- Powder to Ironband
        title = { "18:1165544647:1880747420", "ดินระเบิดให้ Ironband" },
        objective = { "38:877681671:1088134992", "คุยกับ Jern Hornhelm ใน Thelsamar" },
        description = { "374:1225927051:1279514959", "หาก Ironband ยังต้องการดินระเบิด ในนาม Magni เขาจะได้! ส่งอนุมัติล่วงหน้ากับผู้ส่งสารถึง Jern Hornhelm ใน Thelsamar แล้ว เขาจะเตรียมพร้อมเสบียงอื่น\n\nอีกอย่าง เจ้าเองต้องดูให้ถึงปลายทาง ชุดก่อนไม่ถึง จงหัวไวตาไว" },
        completion = { "232:197120576:1245636874", "อะไร? Stormpike ให้เจ้าดูส่งถึง Ironband เอง?\n\nข้า... ก็ได้ แต่ส่ง Huldar กับคนแบก Miran และ Saean ไปแล้ว เพิ่งออก เจ้ามาช้านิดเดียว" },
    },
    [307] = { -- Filthy Paws
        title = { "11:1346688701:2082128777", "อุ้งมือสกปรก" },
        objective = { "98:1161545857:1124989521", "ไป Silver Stream Mine เก็บ Miners' Gear 4 ชุด\n\nกลับไปหา Mountaineer Stormpike" },
        description = { "488:1488619830:182941884", "Silver Stream Mine ตะวันออกหมดแร่มานาน Miners' League ใช้เป็นคลัง แต่ตอนนี้โคโบลด์เข้ามา เอามือสกปรกจับเครื่องมือคนแคระดี ๆ!\n\nเราจะไล่เร็ว ๆ นี้ แต่ League ต้องให้คนเอาของออกก่อนนักรบบุกเหยียบพัง งานลึกยาก อาจอยากมีสหาย\n\nของอยู่ Miners' League Crates ทั่วเหมือง โชคดี" },
        progress = { "31:1805068126:1848116709 N 1:63:63", "มี Miners' Gear ไหม {name}?" },
        completion = { "178:1158863411:1620290567", "โคโบลด์มากไหม? อยากได้คำสั่งกวาดล้างเต็มที นึกถึงมือเปื้อนจับเหมืองแล้วท้องข้าร้อง!" },
        required = { [2640] = { "12:1050263141:10604371", "อุปกรณ์ของคนงานเหมือง" } },
        steps = { { "12:1050263141:10604371", "อุปกรณ์ของคนงานเหมือง" } },
    },
    [309] = { -- Protecting the Shipment
        title = { "23:940699458:921522677", "คุ้มครองเสบียง" },
        objective = { "93:1895264317:334649947", "ดูให้ Miran และเสบียงถึงจุดขุด แล้วแจ้ง Prospector Ironband" },
        description = { "13:630489068:843547548 N 230:1007829800:1557693743", "พร้อมไปหรือยัง {name}?\n\nต้องเอาดินระเบิดถึง Ironband หนักมาก และแถวนี้อันตราย ใครรู้ว่า Dark Iron เตรียมอะไรอีก\n\nไปด้วยกันข้าจะสบายใจขึ้น" },
        progress = { "20:1653859668:1804359976 N 41:1144066950:2042705328", "ดินระเบิดข้าอยู่ไหน {name}? ต้องการมากขึ้นทุกวัน" },
        completion = { "299:2056870795:1538329708", "โอ้ ขอบคุณแสงสว่างที่ดินระเบิดมา แต่ข่าวที่นำก็น่าห่วง คิดไม่ถึงว่า Dark Iron มีผู้สนับสนุนหาวัสดุแบบนี้ทำแผนชั่ว\n\nเป็นเรื่องคนอื่นคิดทีหลัง ข้าต้องใช้ดินระเบิดให้ดี" },
        objectiveLabels = {
            event = { ["Escort Miran to the excavation site"] = "คุ้มกัน Miran ไปยังแหล่งขุดค้น" },
        },
    },
    [385] = { -- Crocolisk Hunting
        title = { "17:1727480004:1376133369", "ล่าจระเข้" },
        objective = { "97:1356040703:127559814", "นำ Crocolisk Meat 5 ชิ้น และ Crocolisk Skins 6 ผืน ไปให้ Marek Ironheart ที่ Farstrider Lodge" },
        description = { "468:389095860:994666891", "นักล่ามากมายมา Loch Modan ล่าจระเข้ชื่อดัง พ่อค้าต้องการหนังทำเสื้อเกราะ และบางคนชอบรสเนื้อ\n\nเราค้าบ้างแต่ไม่มาก จระเข้ดุและยึดเกาะใน Loch แต่อย่าให้ข้าทำหมดใจ มันเป็นประสบการณ์ดี ปล้ำขากรรไกรสัตว์ร้าย\n\nครั้งหนึ่งน่ะ..." },
        progress = { "220:2088626905:547975670", "เล่าเรื่องเกือบเสียมือให้จระเข้หรือยัง? ตัวร้าย ฟันเหมือนมีด แต่โชคดี... ใช้มีดขัดขากรรไกรมันให้ปิดอยู่ มีดยังอยู่แถวนี้..." },
        completion = { "55:688902120:1625086693 N 57:2026428778:1875607294", "เอาล่ะ ตัวอย่างดีมากที่เก็บมา {name} วัสดุคุณภาพย่อมได้เงินดีแน่" },
        required = { [2924] = { "14:1736355209:1514183554", "เนื้อครอโคลิสก์" }, [2925] = { "14:1838601111:1527776108", "หนังครอโคลิสก์" } },
        steps = { { "14:1736355209:1514183554", "เนื้อครอโคลิสก์" }, { "14:1838601111:1527776108", "หนังครอโคลิสก์" } },
    },
    [416] = { -- Rat Catching
        title = { "12:1548817157:720207903", "จับหนู" },
        objective = { "61:752234890:54641841", "นำ Tunnel Rat Ears 12 ชิ้น ไปให้ Mountaineer Kadrell ใน Thelsamar" },
        description = { "330:562582203:1247431879", "เรามีปัญหาระบาดทางตะวันตก โคโบลด์ Tunnel Rat ตั้งรังเชิงเขา ทำผืนดินโสโครก!\n\nอยากกำจัด จงล่า เอาหูมาแลกค่าหัว\n\nพบมันและรังได้ตะวันตก Thelsamar กระจายตามไหล่เขา" },
        progress = { "6:1136836709:1914036474 N 28:1971009842:1457134329", "สวัสดี {name} จับหนูเป็นอย่างไร?" },
        completion = { "91:576838666:731824741 N 12:586053710:1993834439", "อึ๋ย! ตอนขอหูไม่คิดว่าจะเหม็นขนาดนี้!\n\nนี่รางวัล {name} ทำได้ดี" },
        required = { [3110] = { "14:1199942615:922487491", "หูหนูอุโมงค์" } },
        steps = { { "14:1199942615:922487491", "หูหนูอุโมงค์" } },
    },
    [418] = { -- Thelsamar Blood Sausages
        title = { "24:1845245322:86774985", "ไส้กรอกเลือด Thelsamar" },
        objective = { "101:1636896690:698932625", "นำ Bear Meat 3 ชิ้น, Boar Intestines 3 ชิ้น และ Spider Ichor 3 ชิ้น ไปให้ Vidra Hearthstove ใน Thelsamar" },
        description = { "327:1911611530:385322925 C 166:1116482374:1528105780", "Thelsamar ไม่เคยขาดท้องหิว ทั้งเด็กวิ่งเข้าออกกับคนขุดหลังงานหนัก เราดังเรื่องไส้กรอกเลือด เจ้าเคยลองไหม?\n\nไม่หรือ? ที่นี่ต้องทำงานแลกอาหาร แม้เป็น {class} โก้หรูก็ไม่ยกเว้น\n\nต้องเนื้อหมี ไส้หมูทำปลอก และของเหลวแมงมุมปรุงรส เก็บมา แล้วให้ Vidra จัดครัว!" },
        progress = { "67:928745361:1161289703", "พร้อมเริ่มทำอาหารแล้ว มีส่วนผสมไหม?" },
        completion = { "212:1474526739:99095571", "เชื่อเถอะ ยากกว่าที่ดู แต่...\n\nโอ้ ไม่เคยมีใครสนใจทำไส้กรอกมากนัก แต่จะให้สูตรเผื่อไว้ นี่ จำไว้ว่ากินสดใหม่!" },
        required = { [3172] = { "15:1350455235:1292503765", "ไส้หมูป่า" }, [3173] = { "9:782703437:881349839", "เนื้อหมี" }, [3174] = { "12:1432929126:2071168307", "ของเหลวจากตัวแมงมุม" } },
        steps = { { "15:1350455235:1292503765", "ไส้หมูป่า" }, { "9:782703437:881349839", "เนื้อหมี" }, { "12:1432929126:2071168307", "ของเหลวจากตัวแมงมุม" } },
    },
    [436] = { -- Ironband's Excavation
        title = { "21:1515308230:679650494", "จุดขุด Ironband" },
        objective = { "28:415798063:1667929568", "คุยกับ Explorer Fellhew" },
        description = { "500:1142297869:112712630", "Prospector Ironband นำขุดซากโบราณทางตะวันออกของทะเลสาบ พักนี้คืบหน้าช้า โดยเฉพาะเมื่อเทียบเสบียงมากมายที่ส่ง\n\nIronband เป็นคนแคระแข็งแกร่งซื่อตรงที่เห็นค่าผลงาน ข้าจึงห่วงว่ามีอะไรกีดขวาง\n\nไป Ironband's Excavation คุย Magmar Fellhew เขาดูแลรายละเอียด คงรู้เหตุช้า\n\nอ้อมปลายใต้ทะเลสาบแล้วมุ่งตะวันออกถึงจุดขุด" },
        completion = { "157:2009484896:772222869", "Jern อยากรู้เหตุช้าหรือ?\n\nIronband กำลังรวมรายงานละเอียดล่าสุด แต่ข้าบอกได้ว่า:\n\nเพราะโทรกก์!!" },
    },
    [454] = { -- After the Ambush
        title = { "16:39070890:727951699", "หลังถูกซุ่มโจมตี" },
        objective = { "17:184933627:666230701", "คุยกับ Miran" },
        description = { "329:882534931:609986216", "ก่อน... เรื่องนี้ เราขนถังดินระเบิดหลายเที่ยว ตอนนี้ต้องแบ่งงาน Miran ขนถัง ส่วนข้าเฝ้าที่เหลือ\n\nไม่สบายใจให้ Miran ขนส่วนที่เหลือลำพัง เมื่อพร้อมไป เจ้าคุ้มกันเที่ยวหน้าได้ไหม?" },
        completion = { "7:989913233:66981971 C 251:834446398:1312972001", "สวัสดี {class}\n\nจะคุ้มกันข้าไปจุดขุดหรือ? ดีใจ... หลัง Saean กับพวก ใครรู้ว่า Dark Iron ซ่อนแผนอะไรอีก\n\nขอตรวจครั้งสุดท้าย คุยอีกเมื่อพร้อมไป" },
    },
    [531] = { -- Vyrin's Revenge
        title = { "15:1633828920:762952442", "การเอาคืนของ Vyrin" },
        objective = { "66:716433840:312352732", "นำหัว Ol' Sooty ไปให้ Vyrin Swiftwind ที่ Farstrider Lodge" },
        description = { "197:1399948157:1949313290", "แสงสว่างช่วย! อย่านำของแบบนี้เข้า Lodge... ไม่สะอาด พูดไม่ออก ไม่... ไม่... ไม่สะอาด!\n\nเอาออกไปได้ไหม? ไม่มีใครอยากดูถ้วยรางวัลเปื้อนเลือดของเจ้าหรอก!" },
        progress = { "11:1037110534:1315099288 N 72:236035564:303258404", "ทำได้ดี {name}! สอนเขาแล้ว! นี่ ส่งหัวมา ข้าจะจัดการเอง" },
        completion = { "47:1371478731:575192857 N 145:1910926814:923023561", "ขอบใจที่ช่วยแผนเล็ก ๆ {name} อยากเอาคืนเด็กหยิ่งเชิดหน้ามาหลายเดือนแล้ว ข้าว่าเราทำได้ดี! นี่ รับไป สมควรได้" },
        required = { [2713] = { "16:365196957:1308881896", "ศีรษะของเจ้าเฒ่า Sooty" } },
        steps = { { "16:365196957:1308881896", "ศีรษะของเจ้าเฒ่า Sooty" } },
    },
    [1338] = { -- Stormpike's Order
        title = { "17:433161833:840669118", "คำสั่งซื้อ Stormpike" },
        objective = { "58:1983315793:1662529501", "นำ Stormpike's Request ไปให้ Furen Longbeard ใน Stormwind" },
        description = { "500:1917864908:988607504", "มีช่างเกราะคนแคระที่ข้าชื่นชม ชื่อ Furen Longbeard ฝีมือไร้เทียม ต้องการโล่ใหม่และต้องเป็นของเขา!\n\nปัญหาคืออยู่ใต้ไกล ใน Dwarven District ของ Stormwind ดินแดนมนุษย์! ไม่เข้าใจทำไมอยู่ไกล Ironforge มนุษย์คงจ่ายมหาศาลให้เขาอยู่!\n\nหากอยากเดินทางและได้เงิน ช่วยส่งคำขอโล่ให้ Furen ได้ไหม?" },
        progress = { "114:268602238:92668608", "จดหมายจากดินแดนคนแคระหรือ? ใครติดต่อมาไกลจากเหนือ...\n\nขอดูคำสั่งซื้อ" },
        completion = { "115:1507055109:805144310 N 75:2044547412:624903113", "อา คำขอจากคน Stormpike ตระกูลภูมิใจ คนแคระคุณภาพ และมั่งคั่งด้วย\n\nขอบใจ {name} จะเริ่มโล่ Mountaineer Stormpike ก่อนสิ้นวัน" },
        required = { [5998] = { "19:1097475410:979823461", "คำขอของ Stormpike" } },
        steps = { { "19:1097475410:979823461", "คำขอของ Stormpike" } },
    },
    [1339] = { -- Mountaineer Stormpike's Task
        title = { "28:1304066473:1879674396", "งานของ Mountaineer Stormpike" },
        objective = { "33:574104444:588103121", "คุยกับ Mountaineer Stormpike" },
        description = { "122:1145645869:1576822094 R 87:1599685876:507799849", "ได้ยิน Mountaineer Stormpike ต้องการคนวิ่งงาน เดินทางแทนเขานิดหน่อย สนใจไหม? เจ้าเป็น{race}ที่เหมาะหรือเปล่า?\n\nหากใช่ พบเขาชั้นบนหอยามเหนือ" },
        completion = { "143:2031271847:1364863267", "ถูกต้อง มีงานที่ทำระหว่างเฝ้ายามไม่ได้ ที่จริงพาเจ้าไกลจาก Loch Modan\n\nโอกาสผจญภัยพอดี!" },
    },
    [2038] = { -- Bingles' Missing Supplies
        title = { "25:250625614:1535722728", "เสบียงที่หายของ Bingles" },
        objective = { "118:1269224617:1106291574", "หาของ Bingles คืน:\n\nBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer และ Bingles' Blastencapper" },
        description = { "283:94016377:338655609 N 17:771790496:75660118", "ตกลง Loch ก็แย่พอ แต่โทรกก์จากเกาะใกล้ยังบุกขโมยเครื่องมือกับระเบิด Blastenheimer Blastencapper พิเศษ! ไม่มียานไจโรคอปเตอร์หรือระเบิด ขบวนการหมดโอกาส!\n\nเอาเครื่องมือกับระเบิดคืน {name} เพื่อ Gnomeregan!" },
        progress = { "N 23:1187891613:437126008", "{name}! ของข้าอยู่ไหน?!" },
        completion = { "42:915561306:166423892 N 101:1411995808:1832749325", "เจ้าช่วยขบวนการมาก {name} อีกไม่นานโทรกก์กับ leper gnomes ใน Gnomeregan จะรู้รสการบุกอากาศของโนม!" },
        required = { [7343] = { "15:1634690065:920944242", "ประแจของ Bingles" }, [7345] = { "20:2064636257:2078060284", "ไขควงของ Bingles" }, [7346] = { "15:243912267:1355615747", "ค้อนของ Bingles" }, [7376] = { "22:842025353:377492859", "ระเบิด Blastencapper ของ Bingles" } },
        steps = { { "15:1634690065:920944242", "ประแจของ Bingles" }, { "20:2064636257:2078060284", "ไขควงของ Bingles" }, { "15:243912267:1355615747", "ค้อนของ Bingles" }, { "22:842025353:377492859", "ระเบิด Blastencapper ของ Bingles" } },
    },
    [3182] = { -- Proof of Deed
        title = { "13:802621171:462798415", "หลักฐานวีรกรรม" },
        objective = { "60:694958865:1629376628", "นำ Margol's Gigantic Horn ไปให้ Curator Thorius ใน Ironforge" },
        description = { "338:1264047028:1553586642", "จะให้เชื่อเรื่องเช่นนี้หรือ? เขาจริงต้องมีหัวขวานหักของข้าฝังอยู่\n\nฟังนะ เอาของปลอมชัด ๆ นี้ไปให้ Curator Thorius ใน Ironforge หากยืนยันคำกล่าว จะได้ Proof of Deed เอาหลักฐานกลับมา ข้าจะให้กุญแจ Searing Gorge\n\nไป!" },
        progress = { { "63:1974852743:293618816", "64:2143914383:853227168" }, "โอ้ สวัสดีคนหนุ่มสาว อยากชมพิพิธภัณฑ์ไหม?" },
        completion = { "77:58194468:482995011 R 135:1979117650:734474703", "นี่อะไร?\n\nโอ้ ไม่เชื่อเลย! รู้ไหมว่ามีอะไร {race}? เขา Margol the Rager! ศัตรูนักโบราณคดีทุกคนที่ก้าวเข้า Searing Gorge\n\nข้าเก็บไว้ได้ไหม?" },
        required = { [10005] = { "22:1067145585:1052356037", "เขาขนาดมหึมาของ Margol" } },
        steps = { { "22:1067145585:1052356037", "เขาขนาดมหึมาของ Margol" } },
    },
    [6387] = { -- Honor Students
        title = { "14:787222103:1435463394", "นักเรียนเกียรติยศ" },
        objective = { "54:2073144668:1018540860", "นำ Brock's List ไปให้ Thorgrum Borrelson ใน Thelsamar" },
        description = { "474:1352355711:859302469", "ข้าเห็นคนแคระหนุ่มมากมายมาหน้าประตู อยากเรียนเหมือง สิ่งที่ต้องการเหนืออะไรคือพลั่วขุด!\n\nมีรายชื่อนักเรียนคะแนนสูงที่ได้พลั่วเกียรติยศ นำให้ Golnir Bouldertoe ใน Ironforge เขาจะเตรียม\n\nเร็วสุดคือกริฟฟอน เอารายชื่อให้ผู้ดูแล Thorgrum Borrelson แล้วคุยเดินทางไป Ironforge" },
        progress = { "85:522497628:2028179694", "อิ่มใจกับ Thelsamar เร็วหรือ? พร้อมไปอีกเมืองหรือยัง?" },
        completion = { "150:1598712181:2057504797", "ต้องส่งถึง Ironforge หรือ? ค่าธรรมเนียมเล็กน้อย ข้าส่งขึ้นกริฟฟอนพาไปได้ ฟังดูอย่างไร?" },
        required = { [16310] = { "12:1059918536:1600541535", "รายการของ Brock" } },
        steps = { { "12:1059918536:1600541535", "รายการของ Brock" } },
    },
    [6388] = { -- Gryth Thurden
        title = { "13:80704288:1473616788", "Gryth Thurden" },
        objective = { "55:687922433:1853673295", "นำ Honorary Picks ไปให้ Gryth Thurden ใน Ironforge" },
        description = { "232:208187363:109611941", "นี่พลั่วเกียรติยศให้นักเรียน Brock หากเคยไป Thelsamar แล้ว ควรบินกริฟฟอนกลับ!\n\nนำพลั่วให้ Gryth Thurden ผู้ดูแลกริฟฟอน คุยเรื่องบินกลับ Thelsamar" },
        progress = { "64:2023740229:1901213050", "ดูมีที่ต้องไป ต้องการกริฟฟอนหรือ?" },
        completion = { "192:573961423:1708227447", "ต้องส่ง Thelsamar หรือ? ไม่ยาก หากเคยไปและคุย Thorgrum Borrelson แล้ว ก็บินกลับหาเขาได้" },
        required = { [16311] = { "14:1311458192:1980846872", "อีเต้อเกียรติยศ" } },
        steps = { { "14:1311458192:1980846872", "อีเต้อเกียรติยศ" } },
    },
    [6391] = { -- Ride to Ironforge
        title = { "17:1528933885:1964593986", "บินไป Ironforge" },
        objective = { "129:464824362:316128037", "ซื้อเที่ยวกริฟฟอนไป Ironforge จาก Thorgrum Borrelson แล้วนำ Brock's List ไปให้ Golnir Bouldertoe ใน Ironforge" },
        description = { "327:1512476658:242096856", "ไม่กี่เหรียญ กริฟฟอนข้าจะพาไป Ironforge จากนั้นส่งรายชื่อ Brock ให้ Golnir Bouldertoe ที่ Deep Mountain Mining Guild ใน Great Forge District ตรงที่ลงกริฟฟอน!\n\nคุยอีกเมื่อพร้อมเดินทาง" },
        progress = { { "27:1549585506:606688149", "31:538639752:774209051" }, "ให้ช่วยอะไรท่าน?", variants = { { "31:538639752:774209051", "ให้ช่วยอะไรท่าน?" } } },
        completion = { "144:737753545:298729097", "อา รายชื่อนักเรียนเก่งล่าสุดของ Brock มีพลั่วเกียรติยศพร้อม แค่สลักชื่อ..." },
        required = { [16310] = { "12:1059918536:1600541535", "รายการของ Brock" } },
        steps = { { "12:1059918536:1600541535", "รายการของ Brock" } },
    },
    [6392] = { -- Return to Brock
        title = { "15:272325362:930224053", "กลับไปหา Brock" },
        objective = { "130:262078290:456781958", "ซื้อเที่ยวกริฟฟอนไป Thelsamar จาก Gryth Thurden แล้วนำ Honorary Picks ไปให้ Brock Stoneseeker ใน Thelsamar" },
        description = { "443:1700525440:913755556", "จ่ายเล็กน้อยซื้อเที่ยวไป Thelsamar ได้ หากเคยไปแล้ว กริฟฟอนพาเฉพาะที่เคยไป จึงควรคุยผู้ดูแลทุกคนที่พบเพื่อบินไปภายหลัง\n\nเจ้าเคยพบ Thorgrum ผู้ดูแล Thelsamar จึงกลับหาได้ ถึงแล้วนำพลั่วให้ Brock Stoneseeker\n\nคุยเมื่อพร้อมไป" },
        progress = { "4:1110228981:147916455 N 35:1895050852:914177565", "อา {name} กลับจาก Ironforge หรือ?" },
        completion = { "163:799877000:1037177656 N 81:1392278054:228961604", "นำพลั่วมาแล้ว ดี! จะส่งนักเรียนเหมือง คงอยากใช้ขุดแร่ Loch Modan เต็มที\n\nขอบใจ {name} ข้าเป็นหนี้ หวังเงินนี้พอค่าทาง" },
        required = { [16311] = { "14:1311458192:1980846872", "อีเต้อเกียรติยศ" } },
        steps = { { "14:1311458192:1980846872", "อีเต้อเกียรติยศ" } },
    },
    [86585] = { -- Banner of the Fallen
        title = { "20:1813614575:730969076", "ธงของผู้ล่วงลับ" },
        objective = { "111:1729935377:53919927", "ชูธง Ironforge เรียกโทรกก์ Headsplitter ออกมาฆ่า แล้วรายงาน Captain Rugelfuss" },
        description = { "449:583854842:917591271", "Mountaineer ที่ตายถือธง Ironforge อาจสอดแนมหรือบุกอย่างหมดหวัง อย่างไรธงก็ถูกทิ้งเหยียบ นางถูกโทรกก์ตีหัวแรงจนหมวกหลุดและตายทันที คงด้วยกระบองหนาม\n\nตัวที่ฆ่าอาจยังใกล้และจำธงได้ ชูธง Ironforge อีกครั้งอาจเรียกมันออก" },
        progress = { "42:685164245:920028709", "ธงนั้นดูผ่านสงครามมา!" },
        completion = { "449:1631758878:35075514", "พบศพ Ylva หรือ? อา น่าสงสาร นางบอกว่าจะทำให้โทรกก์รู้ว่า Ironforge ไม่มีวันพ่ายแก่พวกมัน ออกหาคนลาดตระเวนที่ไม่กลับจากถิ่นโทรกก์ นางคิดอิสระเกินจะระวัง ตอนนี้รู้แล้วว่าเกิดอะไร\n\nข้าจะรับธง ทำความสะอาดและจัดแสดง เจ้าควรรับอาวุธนาง ขอให้ใช้สู้โทรกก์ได้ดี" },
        required = { [253247] = { "19:1403356575:1084672940", "ธงแห่ง Ironforge" } },
        steps = { { "19:1403356575:1084672940", "ธงแห่ง Ironforge" } },
        objectiveLabels = {
            monster = { ["Headsplitter slain"] = "ปราบ จอมผ่ากะโหลก" },
        },
    },
    [86613] = { -- Excavation Tools
        title = { "16:417917099:1373432973", "เครื่องมือขุดค้น" },
        objective = { "44:1453656777:554198757", "คืน Excavation Tools 6 ชิ้น ให้ Magmar Fellhew", amount = { "7:754587951:547508582 W1 36:159148536:1311481718", "คืน Excavation Tools {world1} ชิ้น ให้ Magmar Fellhew" } },
        description = { "158:315276743:1252978813", "เครื่องมือที่คนแคระทิ้งตอนหนีโทรกก์ส่วนใหญ่ยังไม่ถูกแตะ นำกลับให้คนขุดคงช่วยงานได้" },
        completion = { "177:1059530422:681263979", "เครื่องมือของเรา!\n\nตอนที่พวกโทรกก์บุกยึดค่าย เราต้องทิ้งเครื่องมือส่วนใหญ่ไว้ พอควบคุมการรุกรานได้และกลับมาทำงานอีกครั้ง ของพวกนี้จะช่วยได้มากเลย!" },
        progress = { "87:1966555805:1688500728", "เราก็แค่ เอ่อ ปรับพื้นที่ขุดค้นสักหน่อย แล้วทุกอย่างก็จะกลับมาเข้าที่!" },
        required = { [278398] = { "16:417917099:1373432973", "เครื่องมือขุดค้น" } },
        steps = { { "16:417917099:1373432973", "เครื่องมือขุดค้น" } },
    },
    [86614] = { -- Silver of the Waves
        title = { "19:240777334:1062239791", "เงินแห่งเกลียวคลื่น" },
        objective = { "53:1935159425:172895079", "คืน Monogrammed Silver Hair clip ให้เจ้าของ" },
        description = { "167:1877860143:1135212872", "<ในเศษของตกปลามีเบ็ดสนิม ขดลวดหัก และกิ๊บเงินประณีตที่ผุเล็กน้อย สลักอักษรย่อ “K.D.”>" },
        progress = { "55:1437618993:1913896349", "วันนี้งานมาก ว่ามาเร็วหน่อยได้ไหม?" },
        completion = { "159:999943747:1150909735", "กิ๊บข้า! คิดว่าหายตลอดกาลแล้ว!\n\nขัดนิดเดียวก็เงา ขอบใจนำคืน จะตอบแทนคุ้ม" },
        required = { [278051] = { "28:2111656265:698851737", "กิ๊บเงินสลักอักษรย่อ" } },
        steps = { { "28:2111656265:698851737", "กิ๊บเงินสลักอักษรย่อ" } },
    },
    [86667] = { -- Snowbound
        title = { "9:1101305180:1953474341", "หิมะที่ต้องการ" },
        objective = { "90:1952445842:863305516", "ส่ง Jar of Snow ให้ Norric Lochthane ที่บ้านริมฝั่งตะวันตกเฉียงเหนือของ Loch" },
        description = { "500:987797495:1401027554", "Norric อาจารย์เก่าส่งธาตุตนเล็กมาพร้อมคำขอแปลก ต้องการหิมะหนึ่งไหเพื่อพิธีชามาน! ไม่รู้ใช้ทำอะไร แต่เรียนรู้มานานว่าไม่ควรสงสัยวิธีเวทของเขา\n\nข้ายุ่งศึกษาธาตุท้องถิ่น ไปช่วยไม่ได้ ไปทางเข้าอุโมงค์ South Gate Pass ที่มีหิมะทั้งปี ตักใส่ไหเซรามิกนี้ แล้วส่งก่อนละลาย ไหคงเก็บความเย็นได้", variants = { { "497:982365767:1441150422", "Norric อาจารย์เก่าของข้าส่งภูตธาตุตัวเล็กมาพร้อมคำขอแปลก ๆ เขาต้องการหิมะหนึ่งโถไปใช้ในงานเวทของชาแมน ข้าไม่รู้ว่าเขาจะเอาไปทำอะไร แต่ข้าเรียนรู้มานานแล้วว่าเรื่องเวทมนตร์ อย่าไปตั้งคำถามกับวิธีของเขาเลย\n\nข้ากำลังตั้งหลักอยู่ที่นี่และศึกษาพวกภูตธาตุในแถบนี้ จึงปลีกตัวไปช่วยเขาไม่ได้ เจ้าช่วยแทนข้าได้ไหม? ไปที่ South Gate Pass ที่นั่นมีหิมะตลอดปี ตักหิมะใส่โถดินเผาใบนี้ แล้วเอาไปให้เขาก่อนที่มันจะละลาย" } } },
        progress = { "21:1058999755:288711897", "เอ๊ะ? ต้องการอะไร?" },
        completion = { "221:1022058199:1509498202", "ไหนี้ให้ข้าหรือ?\n\nหิมะ! Grenhild ทำได้ ส่งหิมะที่ขอ!\n\nแต่น่าเสียดาย หวังว่านางจะมาเยี่ยมเอง\n\nอย่างไรก็ตาม ขอบใจที่ลงแรง ช่วยงานข้ามาก", variants = { { "223:1017925515:2072254304", "โถนี้ให้ข้าหรือ?\n\nหิมะ! Grenhild ทำได้จริง ๆ นางส่งหิมะที่ข้าขอมาแล้ว!\n\nเสียดาย ข้าหวังว่านางจะมาเยี่ยมด้วยตัวเอง\n\nเอ้อ เจ้าลงแรงตั้งขนาดนี้ก็ควรได้อะไรตอบแทนสักหน่อย เอ้านี่" } } },
        required = { [279379] = { "11:1685517107:35202177", "โหลใส่หิมะ" } },
        steps = { { "11:1685517107:35202177", "โหลใส่หิมะ" } },
    },
    [86758] = { -- Twisting the Knife
        title = { "18:1664578721:1836098547", "บิดมีดเอาคืน" },
        objective = { "70:1548240294:1586076383", "หาและเอาชนะจระเข้ Daggerfang แล้วนำมีด Marek คืน" },
        description = { "498:380091569:823030535", "เคยเล่าว่าเกือบเสียมือให้จระเข้ไหม? ใช้มีดขัดในขากรรไกรแล้วรีบหนี คิดว่ามีดอยู่แถวนี้ แต่หาไม่พบ\n\nจระเข้อาจยังล่าริมทะเลสาบ สัตว์ร้ายควรถูกกำจัด อย่างน้อยเพื่อความปลอดภัยนักล่าอื่น\n\nข้าเรียก Daggerfang หากเห็น ฝากสวัสดีแทน! “สวัสดี” หมายถึง “แทง”" },
        completion = { "224:1751208910:662433344", "ฮ่า! เจ้าทำสำเร็จ! ข้าไม่คิดเลยว่าไอ้จระเข้แก่นั่นจะได้รับผลกรรม แต่วิธีนี้ได้ผลจริง ๆ!\n\nเอ้อ... รู้ไหม ข้าต้องหามีดเล่มใหม่แล้ว แต่เล่มนั้นอาจนำโชคมาให้เจ้า เก็บไว้เถอะ" },
        progress = { "21:1794336667:984096880", "ล่าไปถึงไหนแล้วล่ะ?" },
        required = { [279591] = { "26:1582856595:1460958387", "มีดล่าครอโคลิสก์ของ Marek" } },
        steps = { { "26:1582856595:1460958387", "มีดล่าครอโคลิสก์ของ Marek" } },
    },
    [86776] = { -- Ingredients for the Forge
        title = { "25:1304293379:923156516", "ส่วนผสมสำหรับเตาหลอม" },
        objective = { "44:947142326:1272378888", "นำ Bronze Bars 10 แท่ง ไปให้ Morhan Coppertongue", amount = { "6:1273960851:929420321 W1 36:2060436566:740841929", "นำ Bronze Bars {world1} แท่ง ไปให้ Morhan Coppertongue" } },
        description = { "320:1595728623:991364822", "Thelsamar น่าอยู่ แต่ไม่มีสิ่งสะดวกเท่า Ironforge บรอนซ์ข้าหมดเสมอ ต้องเพิ่มหากจะทำเครื่องมือ กาน้ำ หม้อ!\n\nดูมีประสบการณ์เตาหลอมบ้าง ช่วยถลุงแท่งบรอนซ์ได้ไหม? จ่ายดี!" },
        progress = { "28:1494490249:224329154", "ต้องให้เตาหลอมทำงานต่อ!" },
        completion = { "149:185244307:1071227488", "อา โล่งใจ คงทำงานต่อได้ หวังว่าสักวันมีพ่อค้านำถ่านเข้าเมืองสม่ำเสมอ!" },
        required = { [2841] = { "10:1541188512:1013360679", "แท่งสำริด" } },
        steps = { { "10:1541188512:1013360679", "แท่งสำริด" } },
    },
    [87318] = { -- Hearts of the Lost
        title = { "18:1262632668:118577301", "หัวใจของผู้พลัดหาย" },
        objective = { "34:1963844675:1023062799", "ตามหา Essene คู่หูของ Corma" },
        description = { "464:712907083:965465412", "Thandol Span อันตรายตั้งแต่ Dark Iron ระเบิดสะพาน แต่ไม่คิดว่าจะเจอมันที่นั่น!\n\nข้าหนีได้ แต่คลาด Essene ค้นทั่วก็ไร้ร่องรอย ถูกจับหรือ? ตกแม่น้ำหรือ? กลับอีกฝั่งหรือ? ไม่รู้ ไม่รู้แม้ยังมีชีวิตไหม!\n\nโปรดแจ้งหากเห็นร่องรอยนาง!" },
        completion = { "492:800321539:565689749", "Corma ส่งเจ้ามาหรือ? ดีจริง ๆ!\n\nตอนพวก Dark Iron ซุ่มโจมตี เราพลัดกัน ข้าหัวกระแทกจนไม่รู้ว่ากำลังไปทางไหน สุดท้ายก็มาอยู่ที่นี่ หลายวันมานี้ข้าประทังชีวิตด้วยเสบียงในกระเป๋า แต่เมื่อเจ้าฝ่าพวก Dark Iron มาได้ ข้าก็อาจมีทางหนีออกไป\n\nขอข้าเก็บของและตั้งสติสักครู่ เดี๋ยวข้าจะคิดหาทางหนีออกไปเอง!\n\nนางไม่เคยเลิกตามหาข้าเลย ช่างเป็นคนที่จิตใจงดงามจริง ๆ" },
    },
    [87491] = { -- Spark of Freedom
        title = { "16:835693912:1014793750", "ประกายแห่งอิสรภาพ" },
        objective = { "69:1256157481:1897814292", "คุ้มกันธาตุไฟที่ถูกจับออกจาก Dun Modr สู่อิสรภาพ" },
        description = { "311:1914613610:561908221", "ฟ่อ! Dark Iron โสมมเรียกข้ามาแล้วขังข้างกองไฟกระจ้อยร่อย!\n\nไฟต้องโลดแล่น เป็นอิสระ! ปล่อยข้า! ต้องหนี! ต้องเผา!\n\nไม่มี Dark Iron ปลอดภัย! เผาให้ราบ! เผาดินระเบิด ป้อม ชนวน ความโง่!\n\nปล่อยข้า แล้วจะเผาพวกมันทั้งหมด!" },
        completion = { "233:869641718:160594631", "ระเบิดไฟสวยเอาเรื่อง! ข้าว่าไม่เคยเห็นอะไรแบบนี้มาก่อนเลย!\n\nดีที่ธาตุไฟนั่น เอ่อ... หมดแรงไปเสียก่อน ถ้ามันหันมาเล่นงานพวกเราที่เหลือแทนพวก Dark Iron คงแย่แน่!" },
        objectiveLabels = {
            event = { ["Escort the fire elemental out of Dun Modr"] = "คุ้มกันธาตุไฟออกจาก Dun Modr" },
        },
    },
    [88756] = { -- Bring Back a Bang
        title = { "17:36254731:48509792", "นำเสียงระเบิดกลับมา" },
        objective = { "60:430152374:1170683350", "เก็บ Stolen Explosives 3 ชิ้น คืนจากค่ายคนแคระ Dark Iron", amount = { "9:1866698604:257786470 W1 50:1660178188:1944959724", "เก็บ Stolen Explosives {world1} ชิ้น คืนจากค่ายคนแคระ Dark Iron" } },
        description = { "443:1647510905:1446680544", "Dark Iron มีค่ายบน Direforge Hill ทางตะวันออก ขโมยระเบิดจากจุดก่อสร้างเราไปเต็นท์\n\nคงไม่ต้องบอกว่ามีถังดินระเบิดแล้วมันสร้างเรื่องอะไรได้!\n\nรู้ว่าอันตราย แต่ต้องเอาถังคืน สังเกตเครื่องหมายสีแดงเพื่อแยกจากถังอื่น ปล่อยให้เก็บไม่ได้!" },
        progress = { "59:1887522108:395365910", "ศึก Dark Iron ไม่จบเสียที!" },
        completion = { "321:1449574363:1704676156", "เฮ้อ โล่งใจ อย่างน้อยมันก็เข็นรถระเบิดใส่เกวียนเราไม่ได้... หรือใช้เครื่องเหวี่ยง... หรือกลิ้งลงเนิน... หรือให้สไลม์กินแล้วปล่อยใกล้ค่ายจุดไฟ\n\nตอนนี้แค่ต้องเก็บดินระเบิดให้แห้ง!\n\nขอบใจ!", variants = { { "321:1210310470:959437134", "เฮ้อ โล่งอกไปที อย่างน้อยพวก Dark Iron ก็เข็นรถบรรทุกระเบิดมาชนเกวียนเราไม่ได้... หรือใช้เครื่องเหวี่ยงยิงระเบิดมา... หรือกลิ้งระเบิดลงเนินใส่เรา... หรือเอาให้สไลม์กินแล้วปล่อยมันมาใกล้ค่ายก่อนจุดไฟ\n\nทีนี้เราก็แค่ต้องระวังอย่าให้ดินระเบิดเปียก!\n\nขอบใจ!" } } },
        required = { [280806] = { "17:650862852:982096529", "วัตถุระเบิดที่ถูกขโมย" } },
        steps = { { "17:650862852:982096529", "วัตถุระเบิดที่ถูกขโมย" } },
    },
    [88757] = { -- Accessories of the Lost
        title = { "23:321308394:324834207", "สัมภาระของผู้พลัดหาย" },
        objective = { "73:70413410:725767012", "นำ Essene's Necklace, Essene's Spellbook และ Essene's Waterskin กลับมา" },
        description = { "276:1612219213:1526735920", "ตอนหนี Dark Iron ข้าทำอุปกรณ์ตกมาก!\n\nดูเหมือนเสียถุงน้ำหนังเขียว ตำราเวท สร้อย และ... ต้องใช้พวกนี้!\n\nช่วยหาขณะข้าจัดของและพักหายใจจะช่วยมาก" },
        completion = { "148:1293338969:1508124411", "เจ้าได้หนังสือของข้ามา! ทั้งถุงน้ำกับสร้อยคอด้วย! วันนี้ข้าโชคดีจริง ๆ ขอบใจเจ้ามาก\n\nข้าขอตรวจดูว่าทุกอย่างยังอยู่ครบก่อนนะ!" },
        progress = { "85:1276609223:1162686241", "ข้ากำลังร้อยเชือกรองเท้าใหม่อยู่! เจ้าฝ่าพวก Dark Iron ไปเจอข้าวของของข้าบ้างไหม?" },
        required = { [284146] = { "18:862832878:510640444", "ถุงน้ำหนังของ Essene" }, [284150] = { "18:790539827:1710135734", "ตำราเวทของ Essene" }, [284705] = { "17:1537088456:1195873509", "สร้อยคอของ Essene" } },
        objectiveLabels = {
            item = { ["Essene's Waterskin"] = "ถุงน้ำหนังของ Essene", ["Essene's Spellbook"] = "ตำราเวทของ Essene", ["Essene's Necklace"] = "สร้อยคอของ Essene" },
        },
    },
    [88758] = { -- Sentiments of the Lost
        title = { "22:566377596:1026896034", "ความรู้สึกของผู้พลัดหาย" },
        objective = { "42:293199430:1656471539", "นำจดหมาย Essene กลับไปให้ Corma Villard" },
        description = { "175:1717479466:1802943625", "จัดของเสร็จก็ไปจากนี่ได้แล้ว!\n\nช่วยครั้งสุดท้าย เอาจดหมายให้ Corma นางจะรู้ว่าข้ายังมีชีวิตและกำลังกลับ!" },
        completion = { "242:1111507427:989464210", "นางยังมีชีวิตอยู่หรือ นางยังไม่ตาย!\n\nข้าขอดูจดหมายหน่อย... ‘ถึง Corma ที่รัก...’ อืม... ช่างเป็นวันดีเหลือเกิน! ขอบคุณแสงศักดิ์สิทธิ์!\n\nข้าไม่รู้จะขอบคุณเจ้าอย่างไรที่ช่วยให้เราได้พบกันอีก ข้าแทบรอไม่ไหวแล้วให้นางกลับมาถึงที่นี่!\n\nเจ้าช่วยเราสองคนไว้มากจริง ๆ" },
        progress = { "31:1170316450:1103122880", "เจ้าพบร่องรอยของนางบ้างไหม?" },
        required = { [284151] = { "13:858883919:1588003464", "บันทึกของ Essene" } },
        objectiveLabels = {
            item = { ["Essene's Note"] = "บันทึกของ Essene" },
        },
    },
    [98197] = { -- Spoils of War
        title = { "13:692642516:1497799731", "ทรัพย์จากสงคราม" },
        objective = { "92:983961102:1520695218", "เก็บ Khaz Modan Timber 6 ชิ้น และ Khaz Modan Iron 30 ชิ้น คืนจาก Menethil Harbor ให้ Valstag Ironjaw", amount = { "8:1749550375:377180055 W1 23:47753756:371398697 W2 58:425256961:1975360431", "เก็บ Khaz Modan Timber {world1} ชิ้น และ Khaz Modan Iron {world2} ชิ้น คืนจาก Menethil Harbor ให้ Valstag Ironjaw" } },
        description = { "454:1962957375:17621804", "ท่าเรือนี้ Old Horde สร้างเป็นฐานบุกทะเล Hillsbrad เลี่ยงแนวป้องกัน Lordaeron ทั้งหมด!\n\nชีวิตสูญเสียมาก...\n\nแย่กว่านั้น กองเรือสร้างจากทรัพยากรที่ขโมยจาก Khaz Modan!\n\nยังเหลือมากในท่า หลัง Admiral Proudmoore ไล่พวกนั้นและสร้างที่นี่ให้ Alliance เราต้องเสริมแนวป้องกันเมื่อ Dragonmaw เคลื่อนไหว" },
        progress = { "81:384097993:1134310505", "ระวังใต้น้ำ มีตัวร้ายมาก!" },
        completion = { { "163:507709:1795490113", "72:569315762:136229168 N 81:361188590:409708779", "72:569315762:136229168 C 81:361188590:409708779", "72:569315762:136229168 R 81:361188590:409708779" }, "อา! เปียกหน่อย แต่ตากแดดไม่กี่วันก็แก้ได้\n\nขอบใจนักผจญภัย ดีที่ไม่ต้องพึ่งของจาก Theramore หรือ Auberdine อย่างเดียวสักครั้ง!" },
        required = { [279821] = { "17:1168403018:2116416240", "ไม้จาก Khaz Modan" }, [279822] = { "15:1281226037:1230427309", "เหล็กจาก Khaz Modan" } },
        steps = { { "17:1168403018:2116416240", "ไม้จาก Khaz Modan" }, { "15:1281226037:1230427309", "เหล็กจาก Khaz Modan" } },
    },
    [98209] = { -- Bloom of the Heavens
        title = { "20:797559570:879443509", "บุปผาแห่งสรวงสวรรค์" },
        objective = { "139:1935118690:1279572399", "นำ Nord'el ไปให้ Thundris Windweaver ที่ Auberdine ใน Darkshore\n\nเจ้าจำได้ว่า Sylessa บอกมีเรือใน Menethil Harbor พาไปได้" },
        description = { "306:1590321701:1587677388", "โปรดส่ง Nord'el ให้ผู้อาวุโส Thundris Windweaver ใน Auberdine ได้ไหม?\n\nเรือจากที่นี่น่าจะไปได้รวดเร็ว\n\nขอโทษที่รบกวนจริง ๆ ข้ายังเหนื่อยจากเดินทาง และหนีเมอร์ล็อกตอนลองเก็บบุปผาศักดิ์สิทธิ์ครั้งแรก!" },
        progress = { { "84:313850660:557015422", "28:1851680688:261034122 N 46:98773225:88916036", "28:1851680688:261034122 C 46:98773225:88916036", "28:1851680688:261034122 R 46:98773225:88916036" }, "ต้อนรับสู่ Auberdine นักผจญภัย ให้ช่วยการเดินทางอย่างไร?" },
        completion = { "416:1229169837:411379215", "Nord'el รอดหรือ? ไม่น่าเป็นไปได้... หลังหลายปี!\n\nเทพีช่างมหัศจรรย์!\n\nขอบใจที่นำมา เป็นแสงหายากในช่วงมืดมน และสัญลักษณ์ทั้งพระคุณ Elune กับความมุ่งมั่นของชนเรา แม้ไร้อมตภาพ\n\nข้าจะจัดส่ง Darnassus อย่างปลอดภัยเพื่อเพาะเลี้ยงเหมาะสม", variants = { { "416:340782555:838866172", "Nord'el รอดมาได้หรือ? เป็นไปไม่ได้... ผ่านมาตั้งหลายปี!\n\nเทพีของเราช่างอัศจรรย์จริง ๆ!\n\nขอบใจที่นำมาถึงที่นี่ มันเป็นแสงสว่างที่หาได้ยากในช่วงเวลามืดมนที่ผ่านมา เป็นทั้งสัญลักษณ์แห่งพระเมตตาของ Elune และความมุ่งมั่นของชนเผ่าเราที่จะยืนหยัดต่อไปเมื่อสิ้นความเป็นอมตะ\n\nข้าจะจัดการให้มันไปถึง Darnassus อย่างปลอดภัย เพื่อให้ได้รับการเพาะเลี้ยงอย่างเหมาะสม" } } },
        required = { [279924] = { "7:663698690:2072636216", "ดอก Nord'el" } },
        steps = { { "7:663698690:2072636216", "ดอก Nord'el" } },
    },
    [98216] = { -- Understanding Our Present
        title = { "25:1040944055:1350418619", "เข้าใจปัจจุบันของเรา" },
        objective = { "98:1055324811:121805810", "ใช้ Goaz Stone ใกล้ Goaz Warder แล้วนำ Titanic Keystone ของมันกลับไปให้ Prospector Whelgar" },
        description = { "455:1061108268:1089216532", "เทพเจ้าโบราณ?! ไม่ใช่ข่าวดีเลย!\n\nอ่านหินเพิ่มได้ว่าพูดถึงผู้พิทักษ์บางอย่าง ต้องเชื่อมกับหิน!\n\nนำไปหาเครื่องสร้างยักษ์ของไททันในจุดขุด อ่านตอนท้ายตรงนี้ดูว่าเกิดอะไร!\n\nหากถูก เจ้าจะปลุกมัน ถ้าเช่นนั้นกำจัด แต่รักษาของน่าสนใจไว้ ต้องรู้เพิ่ม!" },
        completion = { "226:515086093:469070232", "ดูนั่นสิ เห็นไหมว่า Goaz Stone เริ่มเรืองแสงเมื่ออยู่ใกล้ศิลาหลัก? ข้าเกือบจะอ่านคำออกเพิ่มอีกสองสามคำแล้ว...\n\nเรายังต้องหาความรู้เรื่อง Goaz อีกมาก ข้ารู้สึกว่าสิ่งที่เราเห็นเป็นเพียงส่วนเล็ก ๆ ของเรื่องใหญ่!" },
        progress = { "27:1552343612:798893582", "ศิลานั่นทำอะไรบ้างไหม?!" },
        required = { [279993] = { "16:1503608714:88217204", "ศิลาหลักของไททัน" } },
        steps = { { "16:1503608714:88217204", "ศิลาหลักของไททัน" } },
    },
    [98221] = { -- From the Ashes
        title = { "14:1447561762:1706589131", "จากเถ้าถ่าน" },
        objective = { "111:1583917096:629433046", "Captain Stoutfist ใน Menethil Keep ต้องการให้เจ้าทำลาย Attack Plans ทั้ง 4 ชุดใน Angerfang Encampment" },
        description = { "500:913465017:71076255", "สงครามครั้งที่สอง Dragonmaw สร้างเรือที่เรายืน ตั้งใจยึด Hillsbrad เกือบสำเร็จ!\n\nถูกมังกรแดงไล่ เหลือพวกกระจัดกระจายลึกในเขา แต่ค่ายตะวันออกเฉียงเหนือของ Menethil เคลื่อนไหวมากขึ้น\n\nDun Algaz พิสูจน์ว่าตั้งใจรบชิงผืนดินอีก หาแผนโจมตี จดข้อมูลสำคัญแล้วทำลาย ต้องรู้ว่าจะบุกที่ใดต่อ!" },
        completion = { "221:1670508921:1163578099", "Ironforge ด้วยหรือ? Nek'rosh ได้ความทะเยอทะยานมาจากพ่อเต็ม ๆ เลยนะ!\n\nแน่ละ เขายังขาดกองทัพมังกรแดงที่ถูกจับเป็นทาส ซึ่งเคยสร้างความเสียหายมหาศาลในสงคราม เขาวางเดิมพันครั้งใหญ่ทีเดียว และจะต้องชดใช้อย่างสาสม" },
        progress = { "75:788406364:1971608955", "ข่าวกรองชี้เป็นชี้ตายว่าเราจะแพ้หรือชนะสงคราม จำเรื่องนี้ไว้ให้ดี" },
        steps = { { "38:1598631641:733741721", "ทำลายแผนโจมตี Menethil Harbor" }, { "32:1816913354:1674346978", "ทำลายแผนโจมตี Thelsamar" }, { "33:1969869955:429364272", "ทำลายแผนโจมตี Southshore" }, { "32:441569282:101000388", "ทำลายแผนโจมตี Ironforge" } },
    },
    [98223] = { -- Old Habits
        title = { "10:662007725:129879652", "นิสัยเก่า" },
        objective = { "69:1831888367:123809496", "นำ Tattered Spellbook ไปให้ Captain Stoutfist ใน Menethil Harbor" },
        description = { "499:108056853:1793814551", "หนังสือไหม้หนัก อาจจากไฟมังกรที่ทำลาย Dragonmaw ส่วนใหญ่\n\nส่วนอ่านได้เล็กน้อยดูเป็นพิธีใช้ Demon Soul ที่เผ่าเคยใช้คุมมังกร\n\nขาดเกินใช้จริง แต่หน้าหนังสัตว์แทรกหยาบ ๆ บอกว่า Nek'rosh พยายามกู้ หมึกเพิ่งแห้งกล่าวถึง “Shadow Council”\n\nCaptain Stoutfist ใน Menethil Harbor คงอยากรู้" },
        progress = { "99:1530897125:894737220", "ข้าแทบได้ยินเสียงร้องของพวก Dragonmaw จากตรงนี้เลย! พวกมันสมควรโดนยิ่งกว่านี้เสียอีก" },
        completion = { "263:917707514:1852879930", "ทำลายมันทิ้งจะดีที่สุด ต่อให้ใช้ประโยชน์ได้ เราก็เสี่ยงกับออร์คโสมมพวกนั้นไม่ได้\n\nขืนมีพวกขี่มังกรโผล่มาถึงหน้าประตูเมือง ยิ่งแย่กันใหญ่!\n\nส่วนเรื่อง Shadow Council นี่... น่าเป็นห่วงมาก ข้าจะส่งข่าวให้ผู้บังคับบัญชาทันที" },
        required = { [280042] = { "18:1085142160:1207185413", "ตำราเวทขาดรุ่งริ่ง" } },
        steps = { { "18:1085142160:1207185413", "ตำราเวทขาดรุ่งริ่ง" } },
    },
    [98230] = { -- This Land Was Their Land
        title = { "24:777542318:1713694903", "ผืนดินที่เคยเป็นของพวกเขา" },
        objective = { "63:1406429983:776604798", "หา Howin Kindfeather ตามถนนทางตะวันออกของ Menethil Harbor" },
        description = { "481:31698198:1696264809", "หลัง War of the Three Hammers ฉีกชีวิตคนแคระ Wildhammer มาตั้งถิ่นฐาน สร้างป้อมภูเขา Grim Batol\n\nสถานที่มหัศจรรย์ กริฟฟอนเต็มฟ้า โฉบลงพื้นที่ชุ่มน้ำจับปลา\n\nน่าเศร้าที่ไม่นาน\n\nHowin Kindfeather เป็น Wildhammer กลุ่มแรกที่กลับหลังเนิ่นนาน เก็บตัวไกลเมือง ตามถนนตะวันออกแล้วจะพบ เขาคงต้องการความช่วยเหลือ" },
        completion = { "77:441443497:1976090235", "ถ้าเจ้ามาช่วย ข้าก็ยินดี เดี๋ยวนี้หาคนช่วยยากเหลือเกิน" },
    },
    [98240] = { -- Crimson Crate Delivery
        title = { "22:391839411:748362718", "ส่งลังสีชาด" },
        objective = { "89:1150738509:383706149", "นำ Crimson Crate ไปให้ Howin Kindfeather ข้างถนนทางตะวันออกของ Menethil Harbor" },
        description = { "40:1647382319:252207600 N 371:1059220264:2002526266", "ข่าวลูกมังกรแพร่แล้ว {name} มีคนสั่งแล้ว!\n\nข้าจะแพ็กเรียบร้อย เจ้านำให้ลูกค้า รู้ ๆ ขอช่วยครั้งสุดท้าย สัญญา!\n\nของ “Howin Kindfeather” ส่งกริฟฟอนเข้าเมืองพร้อมจดหมายสั่ง! บอกอยู่ข้างถนนตะวันออก เลย Whelgar's Excavation Site นิด หากรู้จัก" },
        progress = { "17:639254850:1295432366 C 1:63:63", "เดินทางผ่านมาแถวนี้หรือ {class}?" },
        completion = { "51:201693750:1048690480", "นี่แหละที่ข้าต้องการ ขอบใจที่อุตส่าห์เดินทางมา" },
        required = { [280099] = { "13:181012326:60070526", "ลังสีชาด" } },
        objectiveLabels = {
            item = { ["Crimson Crate"] = "ลังสีชาด" },
        },
    },
    [98245] = { -- Razormaw Needling
        title = { "17:1560984379:921852374", "เข็มจาก Razormaw" },
        objective = { "51:2131681823:112068217", "เก็บ Razormaw Incisors 10 ชิ้น ให้ Howin Kindfeather", amount = { "8:1089852795:1107240600 W1 41:1993095865:161452731", "เก็บ Razormaw Incisors {world1} ชิ้น ให้ Howin Kindfeather" } },
        description = { "493:62030444:136720456", "ไม่รู้เกลียดใครกว่า Dark Iron, Dragonmaw หรือมังกรที่มันขี่\n\n<Howin ถ่มน้ำลาย>\n\nจะทำให้ถูกต้อง แต่ต้องเสบียง\n\nเกล็ดลูกมังกรช่วยกันไฟ แต่เย็บเข้าด้วยกันยากเหลือเกิน\n\nแรปเตอร์ Razormaw ใน Raptor Ridge ตะวันออกเฉียงเหนือกับ Saltspray Glen ตะวันตกเฉียงเหนือ ได้ชื่อจากฟันแหลม คงเจาะเกล็ดได้\n\nเอาฟันหน้ามากำหนึ่ง" },
        progress = { "94:2070322525:574270286", "งัดฟันได้ไหม? ต้องสมบูรณ์ จะได้ไม่หักกับเกล็ดทันที" },
        completion = { "48:491995933:1521370910", "ทำเหล็กแหลมเจาะเย็บชุดงามได้ ขอบใจ" },
        required = { [280103] = { "16:983856413:380650083", "ฟันตัดของ Razormaw" } },
        steps = { { "16:983856413:380650083", "ฟันตัดของ Razormaw" } },
    },
    [98246] = { -- Trying Times
        title = { "12:1147917207:458717645", "ช่วงเวลาทดลอง" },
        objective = { "54:1914713745:2089752050", "เก็บ Perfect Razormaw Eggs 12 ฟอง ให้ Howin Kindfeather", amount = { "7:451016854:1830523975 W1 45:839807297:1238538355", "เก็บ Perfect Razormaw Eggs {world1} ฟอง ให้ Howin Kindfeather" } },
        description = { "437:1485241704:1517067980", "ต้องใช้ไข่เพื่อให้แผนสำเร็จ Bassbeak ต้องอิ่ม ข้าไม่ขึ้นหลังกริฟฟอนอารมณ์บูด\n\nต้องสมบูรณ์ ไม่มีร้าว\n\nเอาจาก Razormaw ที่ไข่แดงใหญ่เท่าหัวโนม พบ Raptor Ridge ตะวันออกเฉียงเหนือกับ Saltspray Glen ตะวันตกเฉียงเหนือ\n\nเอาหนึ่งโหลเต็มเผื่อไว้" },
        progress = { "93:317893639:409251463", "Razormaw คงไม่ยินดีที่เอาไข่ เตรียมสู้" },
        completion = { "231:3188924:749756132", "ไม่ได้ใช้กับแผน แต่เลี้ยง Bassbeak หากหิว นางช่วยไม่ได้เลย เชื่อเถอะ ถ้าโกรธอาจอันตรายกว่าออร์ค!\n\nพักนี้หาอาหารไม่แปดเปื้อนในแผ่นดินยาก..." },
        required = { [280132] = { "20:251284194:750063614", "ไข่ Razormaw สภาพสมบูรณ์" } },
        steps = { { "20:251284194:750063614", "ไข่ Razormaw สภาพสมบูรณ์" } },
    },
    [98282] = { -- Alchemical Hazards
        title = { "18:770192699:690373481", "ภัยจากงานเล่นแร่แปรธาตุ" },
        objective = { "94:1643609910:2105920236", "เก็บ Unruptured Stalker Gland จาก Thelgen Rock ให้ Caitlin Grassman ใน Menethil Harbor" },
        description = { "503:458599125:2031455872", "สูตรเล่นแร่แปรธาตุบางอย่างต้องของจากที่อันตรายมาก แค่นั้นมักเป็นสมุนไพรพื้นฐาน ส่วนอื่นแย่กว่า!\n\nต้องทำยาต้านพิษเพิ่มก่อนเดินทาง ทุกอย่างในบึงเหมือนมีพิษ ราวไหลทั่วผืนดิน!\n\nช่วยได้ไหม? ต้องต่อมพิษแมงมุม Thelgen Rock ไกลตะวันออกเฉียงใต้ แต่ห้ามแตก ไม่เช่นนั้นพิษหกมากก่อนถึง ขอโทษ!" },
        completion = { "176:1559796887:907945247", "โอ้ เยี่ยมเลย! นี่ละที่ข้าต้องการ เจ้ารู้ไหมว่าเจ้าเป็นวีรบุรุษตัวจริงเลยนะ\n\nรับไว้เถอะ ข้าคงทำไม่ถูกถ้าไม่แบ่งผลจากแรงกายของเจ้าให้บ้าง ระวังตัวด้วยนะ!" },
        progress = { "85:184105065:341505696", "พอหาได้บ้างไหม? ข้ารู้ว่าขอแบบนี้มันลำบาก แต่ข้าต้องใช้ต่อมที่สมบูรณ์ทั้งต่อมจริง ๆ!" },
        required = { [280319] = { "24:1565027651:1836135618", "ต่อมของ Stalker ที่ยังไม่แตก" } },
        steps = { { "24:1565027651:1836135618", "ต่อมของ Stalker ที่ยังไม่แตก" } },
    },
    [98283] = { -- Carnage
        title = { "7:1218422607:2013248945", "Carnage" },
        objective = { "66:1669382043:1070310246", "นำ Carnage's Head ไปให้ Rethiel the Greenwarden ที่ The Green Belt" },
        description = { "458:172341830:2044502356", "ระเบียบธรรมชาติผืนดินกำลังพัง ครั้งหนึ่งแรปเตอร์ Razormaw กันพืชรกเกิน ตอนนี้กลัวจ่าฝูงที่ได้ชื่อจากการเข่นฆ่าที่ทิ้งไว้\n\nกลัวว่ามันบ้าจากโรคที่เรายังขจัดไม่หมด\n\nมันตอบสนองเนื้อร้ายของหมีป่วยใต้ Raptor Ridge ตะวันออกเฉียงเหนือ นำเครื่องในไปวางในถ้ำมัน\n\nCarnage จะมา เอาหัวให้ข้า" },
        progress = { "98:1048836019:773893868", "Rotclaw ลงจากบ้านใน Loch Modan ตอนนี้คลุ้มคลั่ง\n\nเสียของขวัญแห่งชีวิตจริง ๆ" },
        completion = { "176:584664030:1336096795", "Carnage ตายจะคืนสมดุลฝูง บางทีซื้อเวลาให้ระบบนิเวศใหญ่ที่มันค้ำจุน\n\nต้องดูกัน แต่ขอบใจที่พยายาม" },
        required = { [280331] = { "23:1519634462:2041258386", "เนื้อ Malignant Rotclaw" }, [280330] = { "14:1850152303:1100427373", "ศีรษะของ Carnage" } },
        steps = { { "23:1519634462:2041258386", "เนื้อ Malignant Rotclaw" }, { "14:1850152303:1100427373", "ศีรษะของ Carnage" } },
    },
    [98291] = { -- Death to the Dragonmaw
        title = { "22:75178500:2120806909", "ความตายแด่ Dragonmaw" },
        objective = { "126:1418849260:47622237", "ฆ่า Dragonmaw Reclaimers 8 ตัว, Dragonmaw Soulbinders 5 ตัว และ Dragonmaw Infiltrators 3 ตัว ใน Dragonmaw Retreat ให้ Howin Kindfeather", amount = { "5:409775429:850574908 W1 23:448196492:1445184943 W2 28:516048800:1786333870 W3 67:2065121829:455486178", "ฆ่า Dragonmaw Reclaimers {world1} ตัว, Dragonmaw Soulbinders {world2} ตัว และ Dragonmaw Infiltrators {world3} ตัว ใน Dragonmaw Retreat ให้ Howin Kindfeather" } },
        description = { "72:577948807:31943507 N 427:1732823497:2061688540", "ข้าว่าจะกลับ Grim Batol ชิงคืน Wildhammer {name} หรืออย่างน้อยเรียนรู้นิดหน่อย\n\nอย่ามองแบบนั้น รู้ความเสี่ยง ไม่ได้จะควงค้อนไปบุก\n\nแต่ต้องช่วยก่อน ออร์ค Dragonmaw เดินทัพอยู่ตอนนี้ ทั่ว Dragonmaw Retreat ที่มังกรแดงเคยไล่\n\nลดจำนวนก่อนข้าจะเข้าใกล้ได้ ตามถนนตะวันออกไม่มีทางพลาด" },
        completion = { "63:1531055198:598068931", "อย่าหวังเห็นข้าโศกให้พวกมัน สมควรชะตานั้น" },
        progress = { "24:939400693:941460462", "ตั้งสติไว้ให้ดี" },
        objectiveLabels = {
            monster = { ["Dragonmaw Reclaimer slain"] = "ปราบ ผู้ทวงคืน Dragonmaw", ["Dragonmaw Soulbinder slain"] = "ปราบ ผู้ผูกวิญญาณ Dragonmaw", ["Dragonmaw Infiltrator slain"] = "ปราบ ผู้แฝงตัว Dragonmaw" },
        },
    },
    [98293] = { -- Forced Disarmament
        title = { "18:431456888:91166609", "บังคับปลดอาวุธ" },
        objective = { "107:1207289042:930374958", "เก็บ Dragonmaw Armaments 30 ชิ้น ใน Dragonmaw Retreat แล้วนำให้ Captain Stoutfist ใน Menethil Keep", amount = { "8:1089852795:1107240600 W1 97:693365725:2029288622", "เก็บ Dragonmaw Armaments {world1} ชิ้น ใน Dragonmaw Retreat แล้วนำให้ Captain Stoutfist ใน Menethil Keep" } },
        description = { "202:697526440:647522907", "Dragonmaw สะสมอาวุธทุกแบบ ควรยึดก่อนติดอาวุธให้ทหารเพิ่ม\n\nCaptain Stoutfist ใน Menethil Keep คงสนใจ" },
        progress = { "28:492447491:187554544 C 1:63:63", "เจ้ามีอะไรอยู่ในมือนั่น {class}?" },
        completion = { "219:2025708628:1602529783 C 1:46:46", "ทำได้ดี! ดีมาก!\n\nเอาพวกนี้ไปเติมอาวุธให้คนของเราได้แน่ ครึ่งหนึ่งก็เป็นของทหารเราตั้งแต่แรก\n\nศัตรูมีอาวุธน้อยลง พวกเรามีมากขึ้น คิดเลขแบบนี้ถูกใจข้าเลย {class}" },
        required = { [280369] = { "19:1048861427:47395765", "ยุทโธปกรณ์ของ Dragonmaw" } },
        steps = { { "19:1048861427:47395765", "ยุทโธปกรณ์ของ Dragonmaw" } },
    },
    [98297] = { -- Stopping the Cycle
        title = { "18:1093816313:815192353", "หยุดวงจร" },
        objective = { "74:1906672009:2032402064", "ฆ่า Subdued Dragonspawn ที่ Dragonmaw Gates ให้ Howin Kindfeather" },
        description = { "467:518630609:1690837602", "ลองบินตอนเจ้าไม่อยู่ ข่าวดีคือเกราะที่ช่วยทำให้ Bassbeak ใช้ได้ดี!\n\nข่าวร้ายมากคือเห็น Dragonmaw กลุ่มหนึ่งกำลังกดขี่ dragonspawn แดง\n\nไม่ยอม ไม่อีกแล้ว\n\nต้องกำจัด คงต้องมีสหาย ฆ่าวอร์ล็อกที่คุมก่อนเพื่อให้เป็นอิสระ แล้วจบความทรมานมัน\n\nไม่มีใครขวาง Wildhammer" },
        completion = { "25:1907870975:1582417669 N 315:1967574022:1191792297", "ข้าขอบใจเจ้าเท่าไรก็ไม่พอ {name} สิ่งที่เจ้าทำในวันนี้ ต่อให้ข้าทำอะไรตอบแทนก็คงไม่พอจริง ๆ\n\nยังมีอีกมากที่เราต้องทำ ก่อนเสียงหัวเราะของเด็กคนแคระจะกลับมาก้องโถง Grim Batol อีกครั้ง แต่วันนี้เราก็เข้าใกล้ขึ้นอีกก้าวใหญ่\n\nเพื่อคนแคระทุกคนที่เราสูญเสียไปในวันอันมืดมน เราอาจทวงสิ่งที่เคยเป็นของเรากลับคืนมาได้\n\nอย่างน้อยก็ขอให้เป็นเช่นนั้นเถอะ" },
        objectiveLabels = {
            monster = { ["Subdued Dragonspawn slain"] = "ปราบ ดราก้อนสปอว์นที่ถูกพันธนาการ" },
        },
    },
    [98310] = { -- Gleaning Our Future
        title = { "19:293465164:1900268357", "เก็บเกี่ยวอนาคตของเรา" },
        objective = { "101:987676323:356838762", "ใช้ Goaz Stone ใกล้ Ados, Modr, Golm และ Neru แล้วนำหัวใจของพวกมันกลับไปให้ Prospector Whelgar" },
        description = { "495:266099795:1548138525", "มีโกเลมใหญ่กว่าอีกทั่ว Wetlands จารึกชื่อ Ados, Modr, Golm และ Neru ตรงชิ้นที่หายของ Goaz Stone!\n\nข้าพนันว่าหากนำส่วนของมันมา เราจะเผยข้อความหินเพิ่ม\n\nAdos อยู่ Dragonmaw Gates ทางตะวันออกใกล้ Grim Batol ส่วน Modr นอก Dun Modr ทางเหนือ Golm ใต้ Grim Batol ทางตะวันออก Dun Algaz และ Neru หลัง Direforge Hill ตะวันออกเฉียงเหนือ" },
        progress = { "85:1128428577:1011562649", "ระวัง คิดว่าเครื่องสร้างเหล่านี้แข็งแกร่งกว่า Warder" },
        completion = { "352:534584157:1599085177", "เครา Magni! งามจริง! เดี๋ยว เห็นไหม?! ถือหัวใจใกล้ Goaz Stone ครู่หนึ่ง...\n\nข้อความใหม่ปรากฏด้วยแสงแผ่ว\n\nอืม อ่านยาก “คำสาปแห่งเนื้อหนัง... พวกเขาจะล้มเหลว” หมายถึงอะไร?!\n\nต้องนำไปที่ปลอดภัยศึกษาเพิ่ม!", variants = { { "354:2033276688:149281083", "เครา Magni! งามจริง! เดี๋ยว เห็นไหม?! ถือหัวใจใกล้ Goaz Stone ครู่หนึ่ง...\n\n<ข้อความใหม่ปรากฏบนศิลาท่ามกลางแสงริบหรี่>\n\nอืม อ่านยาก “คำสาปแห่งเนื้อหนัง... พวกเขาจะล้มเหลว” หมายถึงอะไร?!\n\nต้องนำไปที่ปลอดภัยศึกษาเพิ่ม!" } } },
        required = { [280395] = { "13:1015195497:1531456404", "หัวใจแห่ง Ados" }, [280396] = { "13:1219614324:1558620825", "หัวใจแห่ง Modr" }, [280397] = { "13:1117768817:1545133322", "หัวใจแห่ง Golm" }, [280398] = { "13:1235932028:1560699143", "หัวใจแห่ง Neru" } },
        steps = { { "13:1015195497:1531456404", "หัวใจแห่ง Ados" }, { "13:1219614324:1558620825", "หัวใจแห่ง Modr" }, { "13:1117768817:1545133322", "หัวใจแห่ง Golm" }, { "13:1235932028:1560699143", "หัวใจแห่ง Neru" } },
    },
    [98459] = { -- A Lack of Virtue
        title = { "16:911339742:2063019619", "ไร้คุณธรรม" },
        objective = { "72:2045779897:314743106", "ส่ง Tom's Gift ให้ Bart Tidewater ใน Menethil Harbor ที่ Wetlands" },
        description = { "499:2102509578:1194927615", "Bart Tidewater เป็นคนขี้เหนียวไร้ดี!\n\nเรียกตัวว่า “กัปตัน Maiden's Virtue” เรือนั่นเดินทางไกลพอก้อนหินใน Tanaris! ไม่ใช่กัปตัน แต่เป็นนักแสดงชนะโป๊กเกอร์จนซื้อ Virtue!\n\nหากไป Menethil Harbor ใน Wetlands เอานี่ให้ บอกว่าเฒ่า Half-fish ส่ง\n\nอ้อ มีเรือจากนี่ไปตรงท่า เป็นป้ายที่สอง!\n\nและมันโกงโป๊กเกอร์!" },
        progress = { "88:1529129828:621157100", "ออกแรงเข้า! เราออกเรือตามคำข้า!\n\nโอ้? ถืออะไรมา นักเดินทาง?" },
        completion = { "433:207751353:666107767", "<Bart แกะห่อของขวัญ>\n\nไอ้สารเลว ลูกไอ้...\n\nมันได้บอกเจ้าหรือเปล่าว่ามันนั่นละที่โกงโป๊กเกอร์?! ข้าชนะจนมีเงินพอซื้อ Maiden's Virtue ก็หลังจากที่เราไล่มันออกจากวงโป๊กเกอร์ไปแล้ว!\n\nข้าสาบานเลย ถ้าคราวหน้าเจอไอ้ตัวที่อยู่ไปก็เปลืองน้ำทะเลนั่นละก็...\n\nขอโทษที ขอโทษ ข้าไม่ควรมาลงกับคนส่งข่าว ในนามลูกเรือ Maiden's Virtue เรือที่ดีที่สุดใน Great Sea ขอต้อนรับสู่ Menethil Harbor!" },
        required = { [281240] = { "10:2046759255:1925674581", "ของขวัญของ Tom" } },
        steps = { { "10:2046759255:1925674581", "ของขวัญของ Tom" } },
    },
    [98461] = { -- Unrequited Love
        title = { "15:921355655:624796814", "รักไม่สมหวัง" },
        objective = { "80:849557253:1969835589", "ส่ง Hollee's Note ให้ Tarrel Rockweaver ใกล้ Menethil Harbor ใน Wetlands" },
        description = { "498:597243271:303872933", "หากออกจาก Auberdine ขอช่วยหน่อย!\n\nTarrel สหายรักเรียนรุ่นเดียวกับข้า เขาเก่งเรื่องขุดค้นมาก! จบแล้วถูกแยก เขาไป Wetlands ข้ามา Darkshore\n\n<Hollee ถอนใจแล้วขมวดคิ้วนิดหนึ่ง>\n\nขอโทษ และภรรยาเขา... Merrin\n\nไม่สำคัญ หากไป Wetlands ช่วยดูว่าเขาปลอดภัยไหม? และให้นี่ได้ไหม? คงใกล้ Menethil Harbor มีเรือตรงไป" },
        progress = { "22:652810642:834349619", "เรื่องอะไรกัน?" },
        completion = { "361:2125497866:2017533735", "<Tarrel อ่านจดหมาย>\n\nโอ้... ตายจริง Hollee ผู้น่าสงสาร\n\nนางมีใจให้ข้ามาตลอด และพูดตามตรงก็เคยมีช่วงที่ข้าคงตอบรับความรู้สึกนั้น แต่ข้าแต่งงานแล้ว และมีความสุขดีด้วย!\n\nข้าว่าไม่ตอบจะดีที่สุด ข้าไม่รู้จะปฏิเสธนางอย่างไร แล้วตอนนี้ยังมีเรื่องเร่งด่วนกว่าที่ต้องห่วง! ภรรยาข้าหายตัวไป!" },
        required = { [281243] = { "13:1451712756:1504472403", "ข้อความของ Hollee" } },
        steps = { { "13:1451712756:1504472403", "ข้อความของ Hollee" } },
    },
    [2039] = { -- Find Bingles
        title = { "12:1668597678:1402824634", "ตามหา Bingles" },
        objective = { "41:1597802964:835074637", "หา Bingles Blastenheimer ใน Loch Modan" },
        description = { "242:444072221:678643542 N 1:46:46", "เราขาดการติดต่อ Bingles! ส่งไปบินสำรวจเหนือ Gnomeregan แต่ไม่รายงานเกินสัปดาห์ รู้เลยคงระเบิดตัวเองแล้ว\n\nเห็นล่าสุดบินเหนือ Loch เจ้าช่วยสำรวจได้ไหม {name}" },
        completion = { "149:805811410:118099810", "งั้น Gnoarn ไม่เชื่อฝีมือสำรวจข้าหรือ? สงสัยทำไม...\n\nช่างเถอะ ข้าต้องการความช่วยเหลือ ไม่สิ! ขบวนการต้องการความช่วยเหลือ!" },
    },
    [3201] = { -- At Last!
        title = { "8:1531857386:2088680561", "ในที่สุด!" },
        objective = { "55:921727141:835402171", "นำ Proof of Deed กลับไปให้ Mountaineer Pebblebitty" },
        description = { "411:441100379:2103703219", "ไม่เชื่อว่า Pebblebitty สงสัยเขาจริง ข้าคิดว่านางแค่อิจฉา อยากฆ่าสัตว์นั้นเองมาก โดยเฉพาะหลัง “เหตุการณ์”\n\nต้องการหลักฐานวีรกรรมหรือ? เมื่อมอบของให้พิพิธภัณฑ์มากขนาดนี้ ไม่มีปัญหา\n\n<Curator Thorius เริ่มกรอกเอกสารแผ่นใหญ่>\n\nเรียบร้อย นำกลับ Pebblebitty ได้" },
        progress = { "19:1351806557:1158649898", "ข้าไม่เชื่อ" },
        completion = { "161:748978782:596919469", "ไม่รู้ว่าคนอ่อนแออย่างเจ้าเอาชนะ Margol ได้อย่างไร แต่สัญญาคือสัญญา นี่กุญแจ\n\nหากมีอะไรเกิดหลังจากนี้ ก็เป็นความผิดเจ้าเอง" },
        required = { [10022] = { "13:802621171:462798415", "เอกสารรับรองผลงาน" } },
        steps = { { "13:802621171:462798415", "เอกสารรับรองผลงาน" } },
    },
    [98208] = { -- Bloom of the Heavens
        title = { "20:797559570:879443509", "บุปผาแห่งสรวงสวรรค์" },
        objective = { "59:2058161574:894621379", "นำ Nord'el กลับมาให้ Sylessa Duskwhisper ที่ Menethil Harbor" },
        description = { "496:1000479953:1564538390", "ข้าเดินทางจาก Auberdine จากต้นไม้ใหญ่ Teldrassil มายัง Menethil Harbor เพื่อตามหาดอกไม้ที่สำคัญยิ่งต่อชนของข้า\n\nFlying Osprey เรือของชนข้า อับปางที่นี่เมื่อหลายเดือนก่อน ขณะร่วมทางกับกองเรือที่สามแห่งคุลทีรัส ในบรรดาของที่บรรทุกมามีดอกไม้ชื่อ Nord'el ซึ่งในภาษาของท่านแปลว่า ‘บุปผาแห่งฟากฟ้า’ มันบานใต้แสงจันทร์เต็มดวงบนยอด Mount Hyjal บ้านเดิมของเรา\n\nโปรดช่วยข้าเอามันคืนมา! ซากเรืออยู่ทางใต้ของเมืองไปนิดเดียว แต่มีพวกเมอร์ล็อกจู่โจมดุร้ายอาศัยอยู่!" },
        progress = { "57:1262949090:1915505179", "ท่านไปดูซากเรือมาแล้วหรือ? เป็นภาพที่ชวนให้เศร้าเหลือเกิน" },
        completion = { "58:152603695:1766715915 N 63:349019190:712070917", "มันยังอยู่! โอ้ สรรเสริญ Elune!\n\nขอบคุณเจ้านับพันครั้ง {name} ถ้าเจ้ายินดี ข้ายังมีอีกเรื่องหนึ่งอยากขอให้ช่วย..." },
        required = { [279915] = { "7:663698690:2072636216", "ดอก Nord'el" } },
        steps = { { "7:663698690:2072636216", "ดอก Nord'el" } },
    },
    [212] = { -- A Meal Served Cold
        title = { "18:1004724212:29161471", "อาหารจานเย็น" },
        objective = { "106:985854116:2127430845", "ฆ่า Cold Eye Basilisk เก็บ Chilled Basilisk Haunch แล้วนำกลับไปให้ Angus Stern ที่ Blue Recluse", variants = { { "167:821594838:732071936", "ฆ่า Cold Eye Basilisk เก็บ Chilled Basilisk Haunch แล้วนำกลับไปให้ Angus Stern ที่ Blue Recluse\n\n<เพื่อให้เควสสำเร็จ ห้ามกดปล่อยวิญญาณ>" } } },
        description = { "460:529359179:62018919", "หนึ่งในอาหารขึ้นชื่อที่สุดของข้าคือเนื้อบาซิลิสก์เย็นราดน้ำสลัดมะนาว แต่ปัญหาก็คือ... เก็บเนื้อให้สดไม่ได้เลย และคืนนี้ข้าต้องทำจานนี้เสิร์ฟในงานวันเกิดของขุนนางด้วย!\n\nหากเจ้าหา Chilled Basilisk Haunch จาก Cold Eye Basilisk ที่เพิ่งฆ่าสด ๆ แล้วรีบนำมาให้ข้าได้ ข้าจะติดค้างเจ้าเป็นงานเลี้ยงสมพระเกียรติราชาเลยทีเดียว!\n\nมีผู้พบ Cold Eye Basilisks เดินอยู่ตามเนินทรายชายหาดทางตะวันตกเฉียงเหนือของ Stranglethorn เจ้ามีทางต้องเดินอีกไกล รีบเข้าล่ะ!" },
        progress = { "N 89:1106175552:1749599890", "{name}! ได้เนื้อส่วนสะโพกมาหรือยัง? ข้าต้องเริ่มเตรียมแล้ว ไม่เช่นนั้นงานเลี้ยงจะพังหมด!" },
        completion = { "140:1884114895:1296206509", "อา ชิ้นนี้เหมาะทีเดียว! ขอบใจมากจริง ๆ!\n\nขอตัวก่อนนะ ข้าต้องสับ หมัก และจัดเครื่องเคียงให้เนื้อชิ้นนี้สำหรับงานเลี้ยง" },
        required = { [2476] = { "23:995445692:1604329074", "เนื้อสะโพกบาซิลิสก์แช่เย็น" } },
        steps = { { "23:995445692:1604329074", "เนื้อสะโพกบาซิลิสก์แช่เย็น" } },
    },
    [332] = { -- Wine Shop Advert
        title = { "16:1318627722:217288177", "ใบโฆษณาร้านไวน์" },
        objective = { "94:1578252817:316756825", "ไปที่ Gallina Winery แล้วนำ Wine Ticket ให้ Suzetta Gallina เพื่อรับไวน์ฟรีหนึ่งขวด" },
        description = { "313:1843039106:1249412601", "ถ้าเคยคุยเรื่องไวน์กับใคร เจ้าก็คงรู้ว่าตระกูล Gallina ของเราขายไวน์ที่ดีที่สุดใน Stormwind ร้านอยู่ไม่ไกล ยังอยู่ใน Trade District ริมคลองแสนงามของเมืองนี่เอง\n\nเอ้า รับแผ่นพับนี้ไป นำไปให้ Suzetta พี่น้องของข้าที่ร้านเรา แล้วรับไวน์ปิโนต์นัวร์อันเลื่องชื่อของเราฟรีหนึ่งขวด เจ้าจะไม่ผิดหวังแน่นอน!" },
        progress = { { "72:1173073785:1573350811", "71:161214221:1265134986" }, "สวัสดี ยินดีต้อนรับท่าน ได้ลองไวน์ชั้นดีของเราบ้างหรือยัง?", variants = { { "72:1173073785:1573350811", "สวัสดี ยินดีต้อนรับท่าน ได้ลองไวน์ชั้นดีของเราบ้างหรือยัง?" } } },
        completion = { { "131:473196669:871672226", "133:2014925863:208985598" }, "อา พบ Renato มาแล้วสินะ? เอ้า เชิญรับไปท่าน ปิโนต์นัวร์สูตรพิเศษของเราหนึ่งขวด ทั่ว Azeroth ก็หาไวน์ที่ทัดเทียมไม่ได้!", variants = { { "131:473196669:871672226", "อา พบ Renato มาแล้วสินะ? เอ้า เชิญรับไปท่าน ปิโนต์นัวร์สูตรพิเศษของเราหนึ่งขวด ทั่ว Azeroth ก็หาไวน์ที่ทัดเทียมไม่ได้!" } } },
        required = { [2722] = { "11:1541544280:1089907815", "คูปองไวน์" } },
        steps = { { "11:1541544280:1089907815", "คูปองไวน์" } },
    },
    [333] = { -- Harlan Needs a Resupply
        title = { "23:304074433:1551500939", "Harlan ต้องการสินค้าเพิ่ม" },
        objective = { "90:245179257:443334945", "ไปที่ Canal Tailor Shop แล้วนำ Cloth Request จาก Harlan Bagley ให้ Rema Schneider" },
        description = { "395:699892089:804193722", "พักนี้ค้าขายดีมาก ดูเหมือนทุกคนพากันซื้อเกราะกับเสื้อผ้าที่ทนทาน ราวกับคาดว่าฤดูกาลข้างหน้าจะหนาวเหน็บและโหดร้าย...\n\nแต่นั่นเป็นเรื่องของวันหน้า วันนี้ข้ากังวลว่าเสื้อผ้าถักที่ขายกำลังจะหมด ต้องขอสินค้าจากผู้จัดส่งมาอีกชุด\n\nหากเจ้าช่วยนำใบสั่งนี้ไปให้ Rema Schneider ที่ Canal Tailor and Fit Shop ได้ ข้าจะขอบใจมาก" },
        progress = { "31:977227292:244037683", "นำข่าวจากคุณ Bagley มาหรือ?" },
        completion = { "313:1125954127:1121015522", "ในนี้เขียนว่ากิจการของ Harlan กำลังรุ่งเรือง เป็นข่าวดีทีเดียว แต่ข้าสงสัยว่าทำไมผู้คนจึงต้องการเกราะมากขนาดนั้น ข้าไม่ได้ยินว่ามีสงครามเปิดหน้าเลย... มีอะไรที่พวกขุนนางไม่ได้บอกเราหรือเปล่า?\n\nอย่างไรก็ขอบใจที่นำใบสั่งมา นี่ค่าตอบแทนของเจ้า ข้าจะจัดการส่งสินค้าให้ Harlan เอง" },
        required = { [2724] = { "13:1993701202:960674054", "ใบขอผ้า" } },
        steps = { { "13:1993701202:960674054", "ใบขอผ้า" } },
    },
    [334] = { -- Package for Thurman
        title = { "19:760146797:41597325", "ห่อของสำหรับ Thurman" },
        objective = { "100:1562409294:684536908", "ไปที่ Larson Clothiers ใน Mage Quarter ของ Stormwind แล้วมอบ Sewing Kit ให้ Thurman Schneider" },
        description = { "154:1019558740:1050504265 C 113:1197187713:447739257 N 159:758669086:1463389669", "Thurman ลูกชายของข้าเป็นเด็กฝึกงานที่ Larson Clothiers ใน Mage's Quarter วันนี้เขารีบจนลืมกรรไกรกับเข็ม ข้ารู้ว่า{class}ผู้เก่งกาจอย่างเจ้าคงมีงานสำคัญต้องทำ แต่ถ้าไม่มีเครื่องมือ Thurman ก็ทำงานฝึกหัดไม่ได้!\n\nขอร้องล่ะ {name} ช่วยนำชุดเย็บผ้าไปให้ลูกชายข้าทีได้ไหม? Larson Clothiers เป็นหนึ่งในร้านเสื้อผ้าสองร้านใน Mage's Quarter อยู่ร้านที่ลึกเข้าไปใกล้ Mage's Tower" },
        progress = { "28:1849126245:1898644092", "มาซื้อเสื้อผ้าหรือ?" },
        completion = { "165:1925045101:596447151", "โธ่เอ๊ย! ข้านึกว่าลืมชุดอุปกรณ์แล้วจะได้อู้งานเสียอีก แบบนี้ก็คงต้องช่วยพวก Larson เย็บผ้าแล้ว...\n\nเอาเถอะ เรื่องสนุกคงต้องไว้ทีหลัง" },
        required = { [2760] = { "20:2045362787:787360651", "ชุดเย็บผ้าของ Thurman" } },
        steps = { { "20:2045362787:787360651", "ชุดเย็บผ้าของ Thurman" } },
    },
    [335] = { -- A Noble Brew
        title = { "12:1216370645:677816839", "เหล้าสูตรพิเศษสำหรับขุนนาง" },
        objective = { "116:876602012:968840439", "Zardeth the Black Claw ต้องการให้เจ้านำ Tear of Tilloa จาก Darkshire และ Musquash Root จาก Wetlands มาให้เขา" },
        description = { "498:1750654770:61149799", "Lord Wishock กำลังทำให้สภาขุนนางวุ่นวาย เขารู้เรื่อง \"กิจการ\" เล็ก ๆ ของเราข้างล่างนี่แล้ว และกำลังวิ่งเต้นให้มีการสอบสวนเต็มรูปแบบ ข้ามีแผนทำให้ Wishock \"ติดธุระ\" แต่ต้องให้เจ้าช่วย\n\nมีดอกไม้ชนิดหนึ่งขึ้นใน Garden of Stalvan แถบชานเมือง Darkshire เป็นดอกเล็กสีขาวที่เรียกว่า Tear of Tilloa ข้ายังต้องการ Musquash Root ซึ่งพบได้เฉพาะตรงตีนของน้ำตก ลึกลงไปใต้ Stonewrought Dam ใน Wetlands" },
        progress = { "128:1495997502:2043191438", "อีกไม่นาน Wishock จะรวบรวมเสียงสนับสนุนได้มากพอจะสร้างความเดือดร้อนให้เรา เจ้าได้ Tear of Tilloa หรือ Musquash Root มาแล้วหรือยัง?" },
        completion = { "46:745252050:2133091201", "ยอดเยี่ยมที่สุด! เป็นของชั้นดีจริง ๆ!" },
        required = { [2779] = { "14:1229213287:558263471", "น้ำตาแห่ง Tilloa" }, [2784] = { "13:597979271:1380547547", "ราก Musquash" } },
        steps = { { "14:1229213287:558263471", "น้ำตาแห่ง Tilloa" }, { "13:597979271:1380547547", "ราก Musquash" } },
    },
    [336] = { -- A Noble Brew
        title = { "12:1216370645:677816839", "เหล้าสูตรพิเศษสำหรับขุนนาง" },
        objective = { "69:2063719491:120560688", "นำ Black Claw Stout ไปให้ Lord Wishock ที่ Hall of Petitioners" },
        description = { "377:1960421031:1496782585 N 108:1407033191:1561210756", "Lord Wishock ก็มีจุดอ่อนเหมือนคนอื่น ๆ และจุดอ่อนของเขาคือความชอบดื่มเหล้า ช่างเสแสร้งเสียจริง เจ้าคนเขลานั่นใช้เวลาทั้งวันพยายามปิด \"โรงเหล้า\" เล็ก ๆ ของเรา แต่กลางคืนกลับขึ้นไปดื่มชั้นบนจนติดหนี้ที่ไม่เคยจ่าย เอาล่ะ มาดูกันว่า Wishock จะชอบเหล้าสูตรพิเศษที่ข้าเตรียมไว้ให้หรือไม่ นั่นคือ Black Claw stout ฤทธิ์แรงเอาเรื่องเชียว {name}\n\nนำไปให้เขาแล้วดูว่าเขาชอบไหม ตาแก่งี่เง่านั่นคงเดินเตร่อยู่แถว Hall of Petitioners" },
        progress = { "173:1102812054:470936864", "ไม่เห็นหรือว่าข้ากำลังยุ่ง? ทุกคนต้องรับฟังคำของข้า! ข้าสำคัญต่ออนาคตของอาณาจักรนี้มากนะ!\n\nโอ้... เจ้าถืออะไรอยู่นั่น? ดูเหมือนเครื่องดื่มชื่นใจเลย..." },
        completion = { "142:920915469:1092988888", "อา ขอบใจที่นำสเตาต์หน้าตาดีขวดนี้มาให้ เจ้าคนรับใช้ เอาเหรียญทองแดงไปหนึ่งเหรียญ ทีนี้ก็หลบไปให้พ้นตา ปล่อยให้ข้าดื่มอย่างสบายใจ!" },
        required = { [2788] = { "16:756792150:766914558", "เบียร์ดำ Black Claw" } },
        steps = { { "16:756792150:766914558", "เบียร์ดำ Black Claw" } },
    },
    [343] = { -- Speaking of Fortitude
        title = { "21:600214565:878661924", "ว่าด้วยความแกร่งกล้า" },
        objective = { "157:1358060079:1548335115", "ไปที่ Royal Library ใน Stormwind Keep แล้วคุยกับ Milton Sheaf เขาจะหาหนังสือโลหวิทยาที่ Brother Kristoff ต้องใช้กล่าวสุนทรพจน์ให้เจ้าได้" },
        description = { "465:949647150:1262712843", "ข้าจะกล่าวสุนทรพจน์เรื่องความแกร่งกล้าแห่งจิตใจ และอยากยกข้อความจากหนังสือโลหวิทยาเล่มหนึ่งชื่อ \"The Stresses of Iron\" น่าจะมีหนังสือเล่มนี้อยู่ที่ Royal Library ใน Stormwind Keep ช่วยนำมาให้ข้าได้ไหม? หากช่วยได้ ก็ขอพรแห่งแสงสว่างจงสถิตกับเจ้า!\n\nRoyal Library ใหญ่มาก แต่ Milton Sheaf หัวหน้าบรรณารักษ์รู้จักชั้นหนังสือทุกชั้นราวกับเป็นลูกชายของตน ไปคุยกับเขา เขาจะหาหนังสือให้เจ้าเอง" },
        completion = { "169:1772856437:812607050", "โลหวิทยาหรือ? อา ใช่ เรามีหนังสือเรื่องนี้หลายเล่ม และยินดีช่วย Brother Kristoff เตรียมสุนทรพจน์! ว่าแต่... เขาต้องการเล่มไหนนะ?" },
    },
    [344] = { -- Brother Paxton
        title = { "14:1230467777:1686385249", "Brother Paxton" },
        objective = { "50:1197368116:476772687", "คุยกับ Brother Paxton ที่ Northshire Abbey" },
        description = { "488:1049375727:841546193", "The Stresses of Iron หรือ? ใช่ ข้ารู้จักเล่มนั้น เป็นหนังสือดีทีเดียว คนเหมืองชาวดวอร์ฟชื่อ Margulf Blaggon เขียนไว้เมื่อหลายสิบปีก่อน เขาใช้เวลาส่วนใหญ่ขุดแร่อยู่ลึกในเทือกเขา Khaz Modan เป็นคนฉลาด!\n\nแต่ข้าพูดถึงไหนแล้วนะ? อ้อ The Stresses of Iron! เกรงว่าหนังสือถูกย้ายไปที่ Northshire Abbey แล้ว Brother Paxton ผู้ดูแลห้องสมุดของวิหารอยากคัดสำเนาไว้บนชั้นของตน\n\nแต่นั่นก็หลายเดือนมาแล้ว สงสัยจังว่าทำไมจึงใช้เวลานานนัก..." },
        completion = { "169:42719103:897417094", "คุณ Sheaf สงสัยหรือว่าหนังสือของเขาอยู่ไหน? อืม น่าอายอยู่นิดหน่อย หนังสืออยู่กับข้าเอง แต่ข้ายังคัดสำเนาอยู่ ยังไม่พร้อมคืนต้นฉบับเลย!" },
    },
    [345] = { -- Ink Supplies
        title = { "12:1671678133:962260451", "วัตถุดิบทำหมึก" },
        objective = { "71:855240227:283681320", "คุยกับ Foreman Oslow ที่ Lakeshire แล้วขอ Rethban Iron Ore จากเขา" },
        description = { "449:1596193557:1587538223", "ข้าตั้งใจจะคัดสำเนา The Stresses of Iron ให้เสร็จ แต่...\n\nคืออย่างนี้ ข้าทำหมึกสำหรับคัดหนังสือเอง เป็นสูตรของข้าโดยเฉพาะ ไม่ไหลเยิ้มหรือเปรอะเปื้อน และแห้งเร็วมาก แต่มันดันแห้งเร็วเกินไป! หมึกชุดล่าสุดแห้งหมดก่อนข้าคัดหนังสือเสร็จ และข้ายังไม่มีโอกาสทำเพิ่มเลย!\n\nถ้าจะทำเพิ่ม ข้าต้องใช้ Rethban Iron Ore จาก Redridge Mountains ปกติ Foreman Oslow ที่ Lakeshire เป็นคนจัดหามาให้" },
        completion = { "197:1973817004:554647148", "เจ้าต้องการอะไรนะ?? ไม่ทันสังเกตหรือว่าเรากำลังยุ่งกับการเสริมแนวป้องกัน Lakeshire และซ่อมความเสียหายจากการโจมตีของออร์คเมื่อไม่นานนี้ ถ้าต้องการ Rethban Iron Ore ก็ต้องไปหาเอง!" },
    },
    [346] = { -- Return to Kristoff
        title = { "18:556743457:1965417376", "กลับไปหา Kristoff" },
        objective = { "91:2095522572:1562471261", "กลับไปหา Brother Kristoff ที่ Cathedral Square แล้วมอบหนังสือ The Stresses of Iron ให้เขา" },
        description = { "175:756264893:259307943", "ตอนนี้ข้าคัดหนังสือเสร็จแล้ว นี่ต้นฉบับ The Stresses of Iron ขอบใจที่อดทนรอ หากเจอ Milton ก็ช่วยบอกด้วยว่าข้าขอโทษที่ล่าช้าไปนาน" },
        progress = { "31:26484750:2021702365", "หาหนังสือพบหรือยัง?" },
        completion = { "27:147344274:1162550424 N 62:1407785339:1133956994", "เล่มนี้แหละ! ขอบใจ {name} ขอแสงสว่างจงส่องทั้งกายและจิตใจของเจ้าให้เจิดจ้า!" },
        required = { [2795] = { "22:537834883:468725341", "หนังสือว่าด้วยความเค้นในเหล็ก" } },
        steps = { { "22:537834883:468725341", "หนังสือว่าด้วยความเค้นในเหล็ก" } },
    },
    [347] = { -- Rethban Ore
        title = { "11:2013241737:1633370397", "แร่ Rethban" },
        objective = { "87:1400222628:1715117503", "รวบรวม Rethban Ore 5 ชุด แล้วนำไปให้ Brother Paxton ที่ Northshire Library" },
        description = { "501:997106695:593713836", "Rethban Ore ตั้งชื่อตาม Bart Rethban ผู้ค้นพบเป็นคนแรก เมื่อถลุงแล้วมันไม่แข็งแรงเท่าเหล็ก แต่ตัวแร่มีสีเข้มด้าน นักคัดหนังสือบางคนจึงนำไปใช้ทำสีย้อม หาได้ที่ Rethban Caverns ทางเหนือของที่นี่\n\nปกติเรามีเก็บไว้บ้าง แต่ตอนนี้ยุ่งกับการเตรียมรับการโจมตีของออร์คจนไม่มีเวลาเก็บ และอีกอย่าง... ตอนนี้พวก Redridge Gnolls เข้าไปอาศัยใน Rethban Caverns แล้ว พวก Drudgers ของมันก็ขุดแร่กันอยู่\n\nถ้าต้องการ เจ้าก็ต้องไปหาเอง" },
        progress = { "28:1917992418:233209870", "ได้ Rethban Ore มาหรือยัง?" },
        completion = { "110:153851954:610984139 N 1:33:33", "โอ้ วิเศษ! ข้าใช้แร่นี้ทำสีย้อม แล้วจะได้คัด The Stresses of Iron ให้เสร็จเสียที\n\nขอบใจ {name}!" },
        required = { [2798] = { "11:2013241737:1633370397", "แร่ Rethban" } },
        steps = { { "11:2013241737:1633370397", "แร่ Rethban" } },
    },
    [350] = { -- Look to an Old Friend
        title = { "21:1268374494:40233229", "ขอแรงสหายเก่า" },
        objective = { "35:2112359375:1286503984", "คุยกับ Elling Trias ที่ Stormwind" },
        description = { "498:601429981:2099875861", "Marzon ติดต่อกับคนของ Defias และยังเกี่ยวข้องกับ Lescovar ด้วย...\n\nเมื่อ VanCleef กับ Thredd ถูกฆ่าแล้ว การนำ Lescovar มาลงโทษตามกระบวนการยุติธรรมก็คงยาก หลักฐานของเจ้าไม่มีน้ำหนักหากขาดคำให้การของพวกเขา นี่ยังไม่นับว่า Lescovar เป็นขุนนางและมีเส้นสายมาก เท่ากับว่าเขาอยู่เหนือกฎหมาย\n\nเจ้าต้องการความช่วยเหลือจากคนอื่น ข้าไม่อยากทำเช่นนี้เลย แต่ข้ารู้จักคนที่ช่วยเราได้ เจ้าจะพบ Trias ที่ Trade District ของเมือง" },
        completion = { "379:1729309729:2030153040", "ล้อกันเล่นหรือ? Shaw จะให้ข้าช่วยอีกแล้ว? ช่างกล้านัก...\n\nว่าไงนะ Defias Brotherhood หรือ? เจ้านำข่าวดีมาให้จริง ๆ เลยใช่ไหม? ต่อไปคงจะบอกว่า Deathwing ยังมีชีวิตและกำลังบุกเมืองละสิ\n\nเอาล่ะ เล่าทุกอย่างตั้งแต่ต้น อย่าข้ามสิ่งที่เจ้าคิดว่าอาจไม่สำคัญ ข้าต้องรู้ทั้งหมด" },
    },
    [353] = { -- Stormpike's Delivery
        title = { "20:1380812813:473961763", "ของส่งให้ Stormpike" },
        objective = { "73:1687788432:62420665", "นำ Package for Stormpike ไปส่งให้ Mountaineer Stormpike ที่ Loch Modan" },
        description = { "481:453252961:981642880", "ตระกูล Stormpike เป็นตระกูลดวอร์ฟที่ได้รับความนับถือ ขึ้นชื่อเรื่องรสนิยมอันประณีตและพิถีพิถัน จึงไม่น่าแปลกที่ Gringer Stormpike พลภูเขาแห่ง Ironforge จะว่าจ้างข้าทำอาวุธให้\n\nอาวุธเสร็จแล้ว แต่... Mountaineer Stormpike อยู่ไกลถึง Loch Modan หากเจ้าคิดจะเดินทางขึ้นเหนือ ช่วยนำห่อนี้ไปส่งให้เขาได้ไหม?\n\nข่าวล่าสุดที่ข้าได้รับจาก Mountaineer Stormpike บอกว่าเขาประจำการอยู่ที่หอยามทางเหนือของ Loch Modan" },
        progress = { "154:592671324:1635525377 C 20:817663325:874842014", "เจ้าเดินทางมาจาก Stormwind เลยหรือ? ได้ยินว่าดินแดนมนุษย์ทางใต้นั่นเริ่มอันตราย มีโจรกับออร์คเดินเพ่นพ่าน เหมาะให้{class}พิสูจน์ฝีมือเสียจริง!", variants = { { "154:592671324:1635525377 C 22:603545895:1834003039", "เจ้าเดินทางมาจาก Stormwind เลยหรือ? ได้ยินว่าดินแดนมนุษย์ทางใต้นั่นเริ่มอันตราย มีโจรกับออร์คเดินเพ่นพ่าน เหมาะให้{class}พิสูจน์ฝีมือเสียจริง!" }, { "81:1431423629:611667650 R 68:1991820680:1320941480 C 22:603545895:1834003039", "เจ้าเดินทางมาจาก Stormwind เลยหรือ? ได้ยินว่าดินแดนของชาว{race}ทางใต้นั่นเริ่มอันตราย มีโจรกับออร์คเดินเพ่นพ่าน เหมาะให้{class}พิสูจน์ฝีมือเสียจริง!" } } },
        completion = { "110:813102913:1863737153 N 91:194703761:1470486587", "อาฮา! ในที่สุด Grimand ก็ทำขวานของข้าเสร็จแล้ว! อยากเอาไปลองกับโทรกก์และโคโบลด์แทบไม่ไหว!\n\nขอบใจมาก {name} เจ้าเดินทางมาไกลเพื่อส่งของชิ้นนี้ เอาเหรียญเหล่านี้ไปเป็นค่าตอบแทนความพยายามเถอะ" },
        required = { [2806] = { "21:1118247333:1356180804", "พัสดุถึง Stormpike" } },
        steps = { { "21:1118247333:1356180804", "พัสดุถึง Stormpike" } },
    },
    [397] = { -- You Have Served Us Well
        title = { "23:941376820:338644576", "เจ้ารับใช้เราได้ดี" },
        objective = { "76:868044415:1422122633", "คุยกับ Zggi ผู้รับใช้ของ Zardeth the Blackclaw เพื่อรับรางวัลของเจ้า" },
        description = { "67:1945730145:1251178659 N 207:259232618:1317269229", "ข้าได้ยินว่า Lord Wishock ชอบเครื่องดื่มของเขา\n\nเจ้ารับใช้เราได้ดี {name} เพราะเจ้า เหล่าวอร์ล็อกแห่ง Stormwind จึงจะฝึกศาสตร์ของเราได้โดยไม่มีใครรบกวน เพื่อตอบแทนความพยายาม ข้าเตรียมของขวัญพิเศษไว้ให้ คุยกับ Zggi ผู้รับใช้ของข้าแล้วรับรางวัลเถอะ" },
        completion = { "25:2147250657:1170278814 N 75:834596658:1577968159", "นายบอกให้มอบของขวัญให้ {name} Zggi อยากเก็บของขวัญดี ๆ ไว้เอง แต่ Zggi รู้ว่าไม่ควรทรยศนาย" },
    },
    [1097] = { -- Elmore's Task
        title = { "13:946208885:123959459", "งานของ Elmore" },
        objective = { "26:559387221:1881855972", "คุยกับ Grimand Elmore" },
        description = { "472:156747694:1421770537", "มีช่างทำอาวุธชาวดวอร์ฟใน Stormwind ชื่อ Grimand Elmore ส่งข่าวมาว่าต้องการความช่วยเหลือในการส่งของ ข้าเชื่อว่าเขาอยากส่งห่อของไปยังบ้านเกิดทางเหนือ\n\nขาของเจ้าดูแข็งแรงดี! ถ้าสนใจเดินส่งของก็ไปคุยกับ Grimand ที่นี่ก็ใช้คนอย่างเจ้าได้ แต่เราต้องรักษาสัมพันธไมตรีกับพวกดวอร์ฟให้แน่นแฟ้นด้วย\n\nเจ้าจะพบ Grimand Elmore ที่ร้านอาวุธใน Dwarven District ของ Stormwind ทางตะวันออกเฉียงเหนือของเมือง" },
        completion = { "48:1489926917:294073534", "เจ้ามาช่วยส่งของให้ข้าหรือ? ดีมาก!" },
    },
    [1247] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "35:2112359375:1286503984", "คุยกับ Elling Trias ที่ Stormwind" },
        description = { "331:775937427:2002076177", "ก็ใช่... เอ่อ... ข้าอาจรู้เรื่องการประชุมที่ Addle's Stead บ้าง คิดว่าเมื่อสองสามสัปดาห์ก่อน ข้าไม่ได้มีส่วนด้วยจริง ๆ ส่วนของข้าจบไปตอนแผน A ล้มเหลว... ไอ้พวกนักผจญภัย\n\nคนวงในที่เราหาได้สำหรับแผน B มาจาก Menethil ชื่อ Slim ข้ารู้เรื่องแผนสำรองของพวกเขาแค่นี้" },
        completion = { "32:318749600:1658718894 N 388:1675425701:2080541507", "ดีใจที่เจ้ายังมีชีวิต {name} คุยกับ Dashel ได้ผลสินะ?\n\nข้าอ่านแผนของพวกนั้นเพิ่ม แม้ไม่ระบุชื่อนักการทูตที่ตามล่า แต่ก็พูดถึงแผน B ที่เริ่มหลังจากพยายามจับเขาครั้งแรกล้มเหลว\n\nSlim ที่ Dashel พูดถึงไม่มีชื่ออื่นเขียนไว้ในนี้ แต่ถ้าเจ้าว่าอยู่ Menethil ก็ถือว่าเป็นจุดเริ่มต้นแล้ว" },
    },
    [373] = { -- The Unsent Letter
        title = { "17:2086081005:1359961297", "จดหมายที่ไม่ได้ส่ง" },
        objective = { "72:2118161489:1007273273", "นำ Letter to the City Architect ไปส่งให้ Baros Alexston ที่ Stormwind" },
        description = { "229:660866453:362913190", "เมื่อค้นตัว Edwin VanCleef เจ้าพบจดหมายที่ยังไม่ได้ส่งอยู่ท่ามกลางข้าวของ จ่าหน้าถึง Baros Alexston สถาปนิกประจำเมือง Stormwind ที่ศาลาว่าการใน Cathedral Square\n\nดูเหมือนเพิ่งเขียนและผนึกไว้ไม่นาน" },
        progress = { "44:647764518:1506380149", "ว่าอย่างไร? มีอะไรให้ข้าช่วยหรือ?" },
        completion = { "431:2088054689:180293495 N 67:1646441449:1824685359", "เจ้าว่า Edwin VanCleef หรือ? ข้าคงประหลาดใจพอ ๆ กับได้รับจดหมายจากย่าที่ตายไปแล้ว... แปลว่าเจ้าฆ่าเขาแล้วสินะ? ขออภัยที่พูดเช่นนี้ แต่ข้าแปลกใจอยู่บ้าง ตอนหนุ่ม ๆ เขาเป็นนักสู้ที่ไม่มีใครทัดเทียม มาดูกันว่าเวลาผ่านไปตั้งหลายปี เขามีอะไรต้องเขียนมาหาข้า\n\n<Baros อ่านจดหมายอย่างละเอียด>\n\nEdwin... ข้าเห็นแล้วว่ากาลเวลาไม่ได้เปลี่ยนเจ้าเลย ยังยึดมั่นในอุดมคติและช่างฝันเหมือนเคย เขาไม่สนว่าจะทำร้ายใครบ้าง {name} ความแค้นกลืนกินเขาแล้ว แต่ข้าก็ไม่แน่ใจว่าจะโทษเขาได้" },
        required = { [2874] = { "16:1561263161:574073332", "จดหมายที่ยังไม่ได้ส่ง" } },
        steps = { { "16:1561263161:574073332", "จดหมายที่ยังไม่ได้ส่ง" } },
    },
    [389] = { -- Bazil Thredd
        title = { "12:1346484100:959665591", "Bazil Thredd" },
        objective = { "44:1061327935:1850401564", "คุยกับ Warden Thelwater ที่ Stockade" },
        description = { "504:66617670:1205191427", "VanCleef กับข้าเคยเป็นสมาชิกสมาคมช่างหิน งานหลักของเราคือสร้าง Stormwind ขึ้นใหม่หลังสงคราม\n\nพอทำงานเสร็จ เรากลับถูกโกง พวกขุนนางไม่ยอมจ่ายค่าแรงให้เรา ช่างหินอาวุโสบางคนได้รับข้อเสนอตำแหน่งงานในรัฐบาล แต่ VanCleef ปฏิเสธเพราะภักดีต่อช่างหินทุกคน เขานำการจลาจลแล้วออกจากเมืองไป พร้อมสาบานว่าจะแก้แค้น\n\nBazil Thredd มือรองของเขาอาจรู้เรื่องแผนของ VanCleef มากกว่านี้ ตอนนี้ถูกคุมขังอยู่ใน Stockade" },
        completion = { "303:1499533569:1093838894", "ในนามแห่งแสงสว่าง เจ้าต้องการอะไร? ไม่เห็นหรือว่าที่นี่กำลังวิกฤต?\n\nBazil Thredd งั้นรึ?! จะคุยกับไอ้สารเลวนั่นทำไม? ข้าจะรู้ได้อย่างไรว่าเจ้าไม่ใช่ลูกสมุนของมันที่ลงมาช่วยก่อจลาจลบ้า ๆ นี่? ถ้าห้องขังเฮงซวยไม่ได้เปิดกันหมด ข้าคงโยนเจ้าเข้าไปสักพักแล้ว!" },
    },
    [392] = { -- The Curious Visitor
        title = { "19:1211408081:692642460", "ผู้มาเยือนน่าสงสัย" },
        objective = { "80:799799634:354004696", "นำ Sealed Description of Thredd's Visitor ไปให้ Baros Alexston ที่ Stormwind" },
        description = { "476:894270117:625011394", "ช่วงปีแรก ๆ ที่ Thredd ถูกขัง ไม่เคยมีใครมาเยี่ยม ข้าคิดว่าเขาคงหมดประโยชน์ต่อ Brotherhood แล้ว พวกนั้นจึงทิ้งเขา\n\nแต่เมื่อไม่กี่เดือนก่อน ทุกอย่างเปลี่ยนไป เขาเริ่มมีคนมาเยี่ยมเป็นประจำ สัปดาห์ละครั้ง หรืออาจสองครั้ง เป็นชายแปลกหน้าที่เงียบขรึม ข้าสงสัยอยู่บ้าง แต่เอกสารของเขาตรวจแล้วถูกต้องทั้งหมด\n\nในเอกสารระบุว่าชื่อ Maelik นี่คำบรรยายรูปร่างหน้าตาของเขา ข้าคิดว่าเขาคงไม่มาเยี่ยม Thredd อีกแล้ว" },
        progress = { "5:1287366450:669725923 N 22:1154480401:1334433790", "ว่าอย่างไร {name}? เจ้าพบอะไรบ้าง?" },
        completion = { "275:1150278106:1250655073", "อืม Maelik หรือ? ไม่ ข้าไม่คุ้นชื่อนี้เลย คำบรรยายรูปร่างหน้าตาก็ไม่คุ้น แต่เป็นใครก็ได้ทั้งนั้น! อดีตช่างหิน หรือคนของ Defias Brotherhood... แต่ถ้าเขามีเส้นสายมากอย่างที่ Thelwater ว่า บางทีคนอื่นอาจจำเขาได้ ขอข้าคิดก่อน" },
        required = { [8687] = { "38:585529434:89635695", "บันทึกปิดผนึกว่าด้วยผู้มาเยี่ยม Thredd" } },
        steps = { { "38:585529434:89635695", "บันทึกปิดผนึกว่าด้วยผู้มาเยี่ยม Thredd" } },
    },
    [393] = { -- Shadow of the Past
        title = { "18:311869717:227892617", "เงาแห่งอดีต" },
        objective = { "85:267675635:823425667", "นำ Sealed Description of Thredd's Visitor ไปให้ Master Mathias Shaw ที่ Stormwind" },
        description = { "25:301729228:2018217745 N 310:509373376:205675920", "ข้าไม่รู้จริง ๆ {name} ยังมีอีกคนที่อาจช่วยเจ้าได้ และบังเอิญว่าเขาติดค้างข้าอยู่เรื่อง... เอาเถอะ อย่าพูดถึงเลย เจ้าจะพบ Master Mathias Shaw แห่ง SI:7 ได้ที่ค่ายทหารใน Old Town เรื่องลับลมหรือสกปรกส่วนใหญ่ในเมืองล้วนอยู่ในความรับรู้ของ Shaw\n\nหากมีใครรู้ ก็คงเป็นเขา" },
        progress = { "44:1569753586:312131282 C 1:63:63", "สวัสดี มีอะไรให้ข้ารับใช้ {class}?" },
        completion = { "485:474309668:1494651002", "อะไรนะ? นี่อะไร? ใช่ ข้าคิดว่ารู้ว่าชายคนนี้เป็นใคร แต่เขาไม่ได้ชื่อ Maelik นักลอบสังหารใช้หลายชื่อ สวมหลายหน้ากาก แล้วทิ้งเมื่อหมดประโยชน์ อีกชื่อหนึ่งที่รู้กันว่าเขาใช้คือ Marzon แม้ชื่อนั้นก็คงไม่ใช่ชื่อจริง\n\nอย่างไรก็ตาม เขาเป็นนักลอบสังหาร และข้ารู้เรื่องเขาไม่น้อย\n\nตอนนี้ Marzon รับจ้าง Lord Gregor Lescovar ขุนนางชื่อเสียงด่างพร้อย แม้เทียบกับเหล่าขุนนางทุจริตของ Stormwind ด้วยกันก็ตาม" },
        required = { [8687] = { "38:585529434:89635695", "บันทึกปิดผนึกว่าด้วยผู้มาเยี่ยม Thredd" } },
        steps = { { "38:585529434:89635695", "บันทึกปิดผนึกว่าด้วยผู้มาเยี่ยม Thredd" } },
    },
    [394] = { -- The Head of the Beast
        title = { "21:1040036767:619036519", "ตัดหัวอสูรร้าย" },
        objective = { "35:1852013031:1915775435", "คุยกับ Mathias Shaw ที่ Stormwind" },
        description = { "331:2122137754:485725254 N 99:1613232164:1858171793", "ไปหา Shaw ใน Old Town บอกเขาว่าภัยจาก Lescovar ถูกจัดการแล้ว และเล่าว่าเจ้าเกี่ยวข้องกับแผนร้ายที่ขุนนางนั่นวางต่อเมืองอย่างไร ข้ามั่นใจว่าเขาจะภูมิใจที่ชาว Stormwind มีวีรบุรุษเพิ่มอีกคน\n\nเขาคงส่งเจ้าไปพบเจ้าชายหรือขุนนางคนอื่น อย่าได้เหลิงล่ะ {name} พวกขุนนางจะคิดว่าปกครองเมืองนี้ก็เชิญ แต่บางอย่างยังอยู่นอกอำนาจพวกเขา" },
        completion = { "42:1562239719:196464622 N 119:1373789340:248289876 N 145:701431848:190468359", "แปลว่าเขาตายแล้วสินะ? ความยุติธรรมของเจ้ารวดเร็วนัก {name} ข้าขอภาวนาต่อแสงสว่างว่าอย่าได้ตกเป็นเหยื่อของเจ้าเลย!\n\n<เขาหัวเราะแล้วตบไหล่เจ้า>\n\nข้าไม่ได้ตำหนิ {name} จะตำหนิได้อย่างไร ในเมื่อข้าเองก็เป็นจ้าวแห่งนักลอบสังหารทั้งปวง? แต่พูดตามตรง เจ้าทำคุณประโยชน์ใหญ่หลวงให้ชาว Stormwind ข้าขอขอบใจสำหรับเรื่องนั้น" },
    },
    [395] = { -- Brotherhood's End
        title = { "17:2020792738:583191009", "จุดจบแห่งภราดรภาพ" },
        objective = { "39:611777988:932441215", "คุยกับ Baros Alexston ที่ Stormwind" },
        description = { "186:1549684504:1847627705 N 245:916725628:593096868", "อา เกือบลืม Alexston มาตอนเจ้าไม่อยู่ เขาอยากคุยกับเจ้า คงอยากรายงานเรื่องของ Defias Brotherhood ให้พวกขุนนางรู้\n\nข้าแนะนำอย่างหนึ่งนะ {name} หากมีใครถาม จงเล่ารายละเอียดทุกอย่าง เว้นแต่เรื่องที่เจ้าเป็นคนลงมือฆ่า Lescovar เชื่อข้าเถอะ ข้า... คุ้นเคย... กับวิธีจัดการเรื่องแบบนี้\n\nส่วน Trias นั้น ถ้าเลี่ยงได้ก็อย่าพูดถึงเขาให้ใครฟัง... เด็ดขาด..." },
        completion = { "22:1693581182:50253142 N 213:1839137572:1964098768", "ดีใจที่ได้พบ {name} ข้าได้ยินว่าเมื่อไม่นานมานี้มีคนพบ Lord Gregor Lescovar เป็นศพ\n\nดูเหมือนภารกิจของเจ้าจะสำเร็จ ข้าขอบใจที่เจ้าช่วยข้าและคนอีกมากให้พ้นจากการแก้แค้นของ VanCleef" },
    },
    [396] = { -- An Audience with the King
        title = { "25:1793627410:218828685", "เข้าเฝ้ากษัตริย์" },
        objective = { "97:450189938:123684195", "นำรายงานเรื่อง Defias Brotherhood ของ Baros Alexston ไปส่งให้ King Varian Wrynn ที่ Stormwind Keep" },
        description = { "331:1185720376:496195491", "ข้าเตรียมรายงานสำหรับกษัตริย์ไว้แล้ว ข้าคิดว่าเจ้าควรเป็นคนนำไปถวาย พร้อมเล่าสิ่งที่เจ้าพบ ไม่ต้องกังวล พระองค์ย่อมทรงยกย่องที่เจ้าทำหน้าที่เพื่อชาว Stormwind\n\nใกล้ถึงเวลาเข้าเฝ้าแล้ว รีบไปเถอะ จากนี่ถึง Stormwind Keep ยังไกลอยู่พอควร" },
        progress = { "N 123:1468532401:2005130737", "{name} ใช่ไหม? Baros Alexston แจ้งข้าแล้วว่าเจ้าจะมา ต้องบอกว่าข้าสนใจสิ่งที่เจ้าจะเล่ามาก" },
        completion = { "69:2022860930:144887122 N 163:1586223476:1103361800 C 168:1785838573:303373075", "เจ้าสมควรได้รับคำยกย่องสำหรับสิ่งที่ทำให้ Stormwind {name} หากแผนชั่วของ VanCleef สำเร็จ ย่อมสร้างความเสียหายใหญ่หลวงแก่อาณาจักร ซึ่งเห็นชัดว่าเราต้องหลีกเลี่ยง\n\nรับสิ่งนี้ไป {class} เป็นเครื่องแสดงความขอบพระทัยจากกษัตริย์ ข้าเสียใจเพียงที่พระองค์ไม่อาจมอบให้ด้วยพระองค์เอง เพราะเสด็จไปปฏิบัติภารกิจทางการทูตและยังไม่กลับมาอีกระยะหนึ่ง" },
        required = { [2956] = { "32:1856798246:1261281292", "รายงานเรื่องภราดรภาพ Defias" } },
        steps = { { "32:1856798246:1261281292", "รายงานเรื่องภราดรภาพ Defias" } },
    },
    [399] = { -- Humble Beginnings
        title = { "17:496761695:1138906859", "จุดเริ่มต้นอันเรียบง่าย" },
        objective = { "124:450839039:1148608350", "ไปที่บ้านของ Baros Alexston ใน Westfall ค้นหาเข็มทิศของเขา แล้วนำกลับไปให้เขาที่ Cathedral Square ใน Stormwind" },
        description = { "501:527836051:395440797", "เหมือนผ่านมาชั่วกัปชั่วกัลป์แล้ว ตั้งแต่ข้ายังเป็นเด็กทำไร่ใน Westfall เขาว่าคนเราไม่มีทางย้อนกลับไปได้ ซึ่งก็จริง สำหรับข้ายิ่งจริงเข้าไปใหญ่ บ้านของครอบครัวข้าถูกเผาและพวกโจรยึดไปแล้ว\n\nข้าคุยกับพ่อถึงข้าวของบางชิ้นของข้า รวมถึงเข็มทิศอันแรก เขาช่วยเก็บไว้ไม่ได้ แต่บอกว่าของเหล่านั้นน่าจะซ่อนอยู่ในไร่\n\nAlexston Farmstead อยู่ทางตะวันตกของ Sentinel Hill เจ้าอาจไปนำเข็มทิศกลับมาให้ข้าได้ไหม?" },
        progress = { "N 24:1627778237:401215260", "{name}! โชคดีบ้างหรือเปล่า?" },
        completion = { "15:403356219:907429681 N 283:1352317230:1545562570", "โอ้ ขอบใจ {name}! มันไม่มีประโยชน์ใช้สอยสำหรับข้าแล้ว แต่คุณค่าทางใจนั้น... ขอบใจที่นำมาให้ ทั้งที่เจ้าต้องเสี่ยงอันตราย และยังเสียเวลาเดินทางไปถึง Westfall ข้าซาบซึ้งใจมาก รับสิ่งนี้ไว้แทนคำขอบคุณเถอะ" },
        required = { [2998] = { "16:18914817:1144248891", "เข็มทิศแบบเรียบง่าย" } },
        steps = { { "16:18914817:1144248891", "เข็มทิศแบบเรียบง่าย" } },
    },
    [434] = { -- The Attack!
        title = { "11:1975736318:1884094722", "ลงมือโจมตี!" },
        objective = { "178:966801740:174542284", "อยู่ในสวนจนกว่า Lord Gregor Lescovar กับ Marzon the Silent Blade จะคุยกันจบ จากนั้นฆ่าทั้งสองคน แล้วกลับไปหา Elling Trias ที่ Stormwind" },
        description = { "503:14302677:1721813679", "เมื่อข้าจัดการเรื่องชุดปลอมตัวของ Spybot เรียบร้อยแล้ว มันจะเข้าไปคุยกับ Lescovar พวกยามคงปล่อยให้ผ่านโดยไม่มีปัญหา\n\nระหว่างที่เจ้าหาวัตถุดิบให้ข้า ข้าจัดการแจ้ง Marzon แล้วว่าถึงเวลาที่เขากับ Lescovar ต้องพบกันอีกครั้ง ข้ายังปล่อยข่าวปลอมไปด้วย\n\nLescovar จะไล่ยามออกไป แล้วรอ Marzon อยู่ในสวนนี้ เมื่อเจ้าได้ยินเรื่อง Defias ก็ลงมือ ต้องฆ่าทั้งคู่ก่อนยามกลับมา! เสร็จแล้วไปคุยกับ Trias" },
        progress = { "5:1287366450:669725923 N 426:1680224180:1414006823", "ว่าอย่างไร {name}? งานกับ Tyrion เป็นไปด้วยดีไหม? เขาแจ้งสถานการณ์ให้ข้ารู้ และข้าช่วยเขาหลอก Marzon ให้ไปปราสาทแล้ว\n\nMarzon เป็นเสี้ยนหนามของคนมากมายใน Stormwind หลายคนเป็นเพื่อนสนิทข้า ไม่มีใครมายุ่งกับเพื่อนข้าได้... ถ้ายังอยากมีชีวิตอยู่ดี ๆ\n\nน่าเสียดายที่ระหว่างนี้ข้ากลับทำประโยชน์ให้ Shaw กับ SI:7 ทางอ้อมด้วย เอาเถอะ ไม่มีแผนใดสมบูรณ์แบบ" },
        completion = { "60:965556646:734195463 N 154:166406979:37683382", "เสร็จแล้วสินะ? ดี ขอบใจมากที่เก็บเรื่องนี้เป็นความลับ {name} เจ้าได้พิสูจน์คุณค่าของตัวเองหลายครั้งแล้ว ข้าจะคอยจับตาดูเจ้าและความก้าวหน้าของเจ้าใน Alliance\n\nระวังอย่าไปมีเรื่องเสื่อมเสียล่ะ" },
        objectiveLabels = {
            event = { ["Overhear Lescovar and Marzon's Conversation"] = "แอบฟัง Lescovar กับ Marzon คุยกัน" },
            monster = { ["Lord Gregor Lescovar slain"] = "ปราบ ลอร์ด Gregor Lescovar", ["Marzon the Silent Blade slain"] = "ปราบ Marzon คมดาบเงียบ" },
        },
    },
    [538] = { -- Southshore
        title = { "10:274497397:904173675", "Southshore" },
        objective = { "42:283722436:1626218114", "คุยกับ Loremaster Dibbs ที่ Southshore" },
        description = { "N 487:926659547:1706874108", "{name} หากไม่รังเกียจการเดินทางไกล ข้ามีงานให้เจ้าช่วยเติมหนังสือให้ห้องสมุด Stormwind อีกครั้ง\n\nอาณาจักร Alterac เก่าล่มสลายหลังมหาสงคราม ที่นั่นเคยมีหนังสือสะสมไว้มากมาย เมืองพังทลายก็น่าเศร้าแล้ว แต่ความรู้ทั้งหมดที่สูญหายยิ่งน่าเศร้ากว่า! เราต้องกู้คืนมาให้ได้เท่าที่ทำได้\n\nSouthshore เป็นเมืองที่อยู่ใกล้ Ruins of Alterac ที่สุด ไปคุยกับ Loremaster Dibbs ที่นั่น เขาจะบอกทางไปซากเมืองและบอกว่ามีหนังสืออะไรให้หาได้บ้าง" },
        completion = { "226:932630590:768651003", "อา ใช่ ข้าจำ Milton ได้ หนอนหนังสือตัวจริง ขอพรจงคุ้มครองเขา\n\nเขาพูดถูก Ruins of Alterac ยังมีคลังความรู้ที่เสี่ยงจะสูญหาย!\n\nตอนนี้ออเกอร์อาศัยอยู่ใน Alterac และพวกมันไม่สนใจการศึกษาชั้นสูงนักหรอก" },
    },
    [540] = { -- Preserving Knowledge
        title = { "20:802312302:582765917", "รักษาความรู้ไว้" },
        objective = { "114:1691531924:1238644695", "นำ Recovered Tomes 5 เล่ม และ Worn Leather Book ที่มีเรื่อง The Arm of Gri'lek ไปให้ Loremaster Dibbs ที่ Southshore" },
        description = { "478:1453907252:513111915", "ตอนนี้ออเกอร์ป่าเถื่อนพวกนั้นอาศัยอยู่ในซาก Alterac คิดว่ามันอาจทำอะไรกับหนังสือล้ำค่าที่ยังเหลืออยู่ก็ขนลุกแล้ว เจ้าต้องกู้คืนให้ได้มากที่สุด!\n\nเข้าไปใน Ruins of Alterac แล้วหาตำราที่ออเกอร์ปล้นไป นำทุกเล่มที่พบมาให้ข้า แต่มีเล่มหนึ่งที่ต้องหาเป็นพิเศษคือ The Arm of Gri'lek ในนั้นมีตำนานโทรลล์โบราณที่ข้าต้องศึกษา และ Ruins of Alterac เป็นสถานที่สุดท้ายที่มีผู้รู้ว่ามีหนังสือเล่มนี้ฉบับสมบูรณ์อยู่" },
        progress = { "163:1208775032:92241142 N 1:63:63", "ข้าก็อยากค้นซากเมืองด้วย แต่เกรงว่ากระดูกแก่ ๆ คงพาข้าปีนเขาไม่ไหว แล้วการตามล่าความรู้ของเจ้าเป็นอย่างไรบ้าง {name}?" },
        completion = { "81:2060500825:1758413199", "โอ้ ได้มาแล้ว! วิเศษ! ข้าต้องเริ่มศึกษา The Arm of Gri'lek ทันที!" },
        required = { [3658] = { "14:1337455243:1011216561", "ตำราที่กู้คืนมา" }, [3659] = { "17:1729791230:344205484", "หนังสือปกหนังเก่า" } },
        steps = { { "14:1337455243:1011216561", "ตำราที่กู้คืนมา" }, { "17:1729791230:344205484", "หนังสือปกหนังเก่า" } },
    },
    [542] = { -- Return to Milton
        title = { "16:316052465:263427776", "กลับไปหา Milton" },
        objective = { "56:40491262:419615629", "นำ Tomes of Alterac ไปให้ Milton Sheaf ที่ Stormwind" },
        description = { "326:1289095445:557514603", "ข้าต้องใช้เวลาศึกษาหนังสือ The Arm of Gri'lek ที่เจ้านำมาให้ แต่มั่นใจว่า Milton คงอยากนำหนังสืออื่นที่กู้คืนมาเข้าคลังของ Stormwind แล้ว\n\nนี่หนังสือที่เจ้าเก็บจาก Ruins of Alterac จัดห่อและทำบัญชีเรียบร้อย นำกลับไปให้ Milton Sheaf ที่ Stormwind ข้ามั่นใจว่าเขาจะขอบใจ" },
        progress = { "N 92:1220606650:333019122", "{name} กลับมาแล้ว! การเข้าไปใน Alterac เป็นอย่างไรบ้าง? นำอะไรมาด้วยหรือเปล่า?" },
        completion = { "117:1368914048:333621592 N 125:421402621:1011254121", "โอ้โฮ! ดูสิ่งเหล่านี้สิ! ไม่อยากเชื่อว่าจะรอดจากการล่มสลายของ Alterac มาได้ แถมยังรอดจากออเกอร์พวกนั้นด้วย!\n\nขอบใจ {name} ขอบใจมาก! เจ้าช่วยรักษาความรู้ของมนุษย์ไว้ และเพิ่มความยิ่งใหญ่ให้ Royal Library แห่ง Stormwind" },
        required = { [3660] = { "16:1249323516:2036053790", "ตำราแห่ง Alterac" } },
        steps = { { "16:1249323516:2036053790", "ตำราแห่ง Alterac" } },
    },
    [543] = { -- The Perenolde Tiara
        title = { "19:1601113217:1192233248", "มงกุฎ Perenolde" },
        objective = { "62:2004081113:1056216467", "นำ Perenolde Tiara ไปให้ Remington Ridgewell ที่ Stormwind" },
        description = { "469:406260333:634485462", "Perenolde Tiara เป็นมรดกเก่าแก่ของ \"ขุนนาง\" ตระกูล Perenolde ผู้ปกครอง Alterac ก่อนอาณาจักรนั้นล่มสลาย กล่าวกันว่าปรมาจารย์ช่างอัญมณีแห่ง Ironforge เป็นผู้สร้าง ประดับด้วยมรกตชั้นเลิศ\n\nมงกุฎสูญหายเมื่อ Alterac ถูกทำลาย แต่มีข่าวลือว่าจอมเวทออเกอร์ Grel'borg the Miser พบเข้า และตอนนี้เดินหาสมบัติอื่นอยู่ใน Ruins of Alterac\n\nเราอยากให้เจ้านำมงกุฎมาให้เรา" },
        progress = { "13:1760559889:1711752451 N 75:1384621547:625080581", "สวัสดี {name} ระวังอย่าเหยียบขากางเกงข้าล่ะ ชุดนี้เพิ่งตัดมาใหม่" },
        completion = { "94:1551866526:1201748023 N 158:1873616232:2047781133", "อา วิเศษ แน่นอนว่าต้องทำความสะอาด แต่เจ้าทำได้ยอดเยี่ยมจริง ๆ {name} ข้าจะให้คนจัดเตรียมมงกุฎแล้วนำเข้าชุดสะสมของเราทันที\n\nข้ามั่นใจว่าเจ้าคงเห็นด้วย ความซาบซึ้งของเรายิ่งใหญ่พอ ๆ กับชุดสะสมของเรา" },
        required = { [3684] = { "15:1652267842:1458160766", "มงกุฎเล็กแห่ง Perenolde" } },
        steps = { { "15:1652267842:1458160766", "มงกุฎเล็กแห่ง Perenolde" } },
    },
    [579] = { -- Stormwind Library
        title = { "17:95952716:11487403", "ห้องสมุด Stormwind" },
        progress = { "258:817631581:2009910828", "King Anduin ทรงให้ความสำคัญอย่างยิ่งต่อการเรียนรู้ จึงพระราชทานทุนให้คัดสำเนาตำราและงานเขียนต่าง ๆ เพื่อประชาชน วิธีง่ายมาก เพียงนำใบแลกของห้องสมุดมาให้ข้า ข้าก็จะมอบสำเนาหนังสือเล่มหนึ่งจากที่มีให้เจ้าได้" },
        completion = { "37:1994291051:792048297 N 1:63:63", "หนังสือเหล่านี้มีเล่มใดที่เจ้าสนใจไหม {name}?" },
        description = { "258:817631581:2009910828", "King Anduin ทรงให้ความสำคัญอย่างยิ่งต่อการเรียนรู้ จึงพระราชทานทุนให้คัดสำเนาตำราและงานเขียนต่าง ๆ เพื่อประชาชน วิธีง่ายมาก เพียงนำใบแลกของห้องสมุดมาให้ข้า ข้าก็จะมอบสำเนาหนังสือเล่มหนึ่งจากที่มีให้เจ้าได้" },
        required = { [3898] = { "13:1026275907:1836821838", "ใบแลกของห้องสมุด" } },
        objectiveLabels = {
            item = { ["Library Scrip"] = "ใบแลกของห้องสมุด" },
        },
    },
    [1241] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "30:1957328456:1651821874", "ตามหา Jorgen ในเมือง Stormwind" },
        description = { "502:195907956:814213046", "เมื่อไม่นานมานี้มีนักการทูตถูกส่งไป Theramore เพื่อพบ Jaina Proudmoore แต่นักการทูตคนนั้นไปไม่ถึง\n\nข้าเชื่อว่า Defias มีส่วนในแผนนี้ แต่ยังไม่แน่ใจว่าอย่างไร ประชาชนยังไม่รู้เรื่องการหายตัวไปของนักการทูต แต่คงปิดไว้ได้อีกไม่นาน\n\nเจ้าหน้าที่ของกษัตริย์กำลังค้นหาเบาะแสทั่วเมือง แต่ข้าก็มีคนรู้จักที่อยากให้ช่วยเรื่องนี้\n\nสหายเก่าของข้าชื่อ Jorgen อยู่ใน Valley of Heroes ไปหาเขา มอบข้อความนี้ให้ แล้วทำตามคำแนะนำของเขา" },
        progress = { "121:584171975:2021724643", "ฮึ หวังว่ามีเหตุผลดีพอที่มากวนคนกำลังตกปลา ข้าไม่ชอบพวกเร่ขายของ ยิ่งขอทานยิ่งไม่ชอบ" },
        completion = { "335:2010745392:229499708", "อืม... <Jorgen หรี่ตามองเจ้า>\n\nเอาล่ะ ข้าจะช่วย แต่เพราะมีพันธะต้องทำ ไม่ใช่เพราะอยากช่วย\n\nขอให้เข้าใจอย่างหนึ่ง ตั้งแต่แรกเจ้าก็รู้มากเกินควรแล้ว เก็บเรื่องนี้เป็นความลับของเรา อย่าเอาสิ่งที่รู้ไปพล่ามตามโรงเหล้า เข้าใจไหม?" },
        required = { [5948] = { "16:648124950:231506640", "จดหมายถึง Jorgen" } },
        steps = { { "16:648124950:231506640", "จดหมายถึง Jorgen" } },
    },
    [1242] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "64:1863199653:1616236387", "นำ Jorgen's Sealed Note ไปส่งให้ Elling Trias ในเมือง Stormwind" },
        description = { "183:1649138880:1677896143 N 144:1481042372:629039078", "นำข้อความนี่ไปให้ Elling Trias ไม่ต้องพูดอย่างอื่น แค่สุภาพแล้วรอเขาตอบ ไม่ต้องห่วง เขาตอบแน่\n\nข้าจะย้ำอีกครั้งเท่านั้นนะ {name} จงจริงจังกับเรื่องนี้และหุบปากไว้\n\nเจ้าจะพบ Trias ที่ร้านชีส Trias' Cheese ใน Trade District โชคดี" },
        progress = { "7:989913233:66981971 N 130:1416688593:697386988", "สวัสดี {name} มีอะไรให้ข้าช่วยหรือ? อยากลองเชดดาร์สูตรพิเศษของ Trias ไหม? หรือบลูชีส Darnassian สักก้อน?" },
        completion = { "245:1388602101:1683481584 N 1:63:63", "ขอโทษนะ จดหมายถึงข้าหรือ? โอ้... ถ้าทำแต่งานอย่างข้า ก็ไม่ค่อยมีใครส่งอะไรมาให้นอกจากลังหรือถัง มาดูกันว่าเรื่องอะไร\n\n<Elling เงยหน้ามองเจ้าระหว่างเปิดจดหมาย>\n\nเจ้าดูเครียดนิดหน่อย เป็นอะไรไหม {name}?" },
        required = { [5946] = { "21:2038129388:181129530", "ข้อความปิดผนึกถึง Elling" } },
        steps = { { "21:2038129388:181129530", "ข้อความปิดผนึกถึง Elling" } },
    },
    [1243] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "51:1154350353:251874494", "มอบ Sealed Note ให้ Watcher Backus ที่ Duskwood" },
        description = { "180:2118101089:1426302452 N 320:2064860370:2096122172", "Jorgen ไอ้แก่ระยำ... จะเอาอย่างนี้สินะ?\n\nเอาล่ะ ข้ารับมือได้ ขอให้เขาไปพบ Twisting Nether เร็วขึ้นก็แล้วกัน!\n\nเราจะทำอย่างนี้ {name} ข้าจะเริ่มใช้เส้นสายที่นี่ แต่เจ้าต้องเดินเรื่องเป็นส่วนใหญ่ ข้าจะได้ประหยัดเงิน\n\nไปที่ Darkshire ใน Duskwood แล้วหา Watcher Backus ปกติเขาลาดตระเวนบนถนนทางเหนือที่อยู่พ้นเมืองไปนิดเดียว แค่บอกว่ากำลังตรวจสอบความเคลื่อนไหวของ Defias ให้ข้า เขาก็จะช่วยบอกข้อมูลเท่าที่ทำได้" },
        progress = { "49:122375607:1267402546 N 360:898969732:45206444", "เดินทางในป่าไม่ค่อยปลอดภัยนะ {name} ระวังตัว หากเห็นอะไรน่าสงสัยหรืออันตราย ให้แจ้งพวก Watchers ทันที อย่าจัดการเอง เราไม่รับผิดชอบหากเกิดเรื่องร้ายกับเจ้า\n\nแต่เราต่างรู้ว่าเจ้าคงไม่ฟัง แล้วก็ไปสู้กับทุกอย่างที่โผล่จากความมืดอยู่ดีใช่ไหม? ฮ่า ๆ พวกนักผจญภัยอย่างเจ้านี่... เหมือนกันหมด" },
        completion = { "303:1439378647:806711808", "อ้อ Trias ส่งเจ้ามาหรือ? ถ้าอย่างนั้นก็ต่างออกไปหน่อย\n\nเชิญสู้กับสัตว์ประหลาดอะไรก็ตามที่โผล่มาจากความมืดได้เลย ข้ามั่นใจว่าเจ้าคงจัดการได้ง่าย ๆ ถ้าเป็นคนที่คบหากับพวกอย่างเขา\n\nแล้วสหายข้าต้องการอะไรจากข้าในวันอึมครึมเช่นนี้?" },
        required = { [5960] = { "29:1324336886:1252087036", "ข้อความปิดผนึกถึง Watcher Backus" } },
        steps = { { "29:1324336886:1252087036", "ข้อความปิดผนึกถึง Watcher Backus" } },
    },
    [1244] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "67:1661509954:664960582", "หา Defias Docket แล้วนำกลับไปให้ Watcher Backus ที่ Duskwood" },
        description = { "485:236890311:971786718", "ความเคลื่อนไหวของ Defias หรือ? พวกนั้นมีความเคลื่อนไหวอยู่เสมอ ต่อให้เก็บตัว เราก็ยังถือว่าเป็นภัย\n\nแต่พอนึกดูแล้ว มีรายงานการพบเห็นเมื่อไม่นานมานี้ที่ดูแปลก คงสักสองสามสัปดาห์ก่อน เจ้าหน้าที่ของพวกนั้นมารวมตัวกันแถว Addle's Stead จากรายงาน ข้าเดาว่าคงมีเรื่องใหญ่เกิดขึ้น\n\nทำไมเจ้าไม่ลองไปตรวจที่นั่นก่อน แล้วนำสิ่งที่พบกลับมาให้ข้า?\n\nไร่อยู่ทางใต้ของถนนจาก Westfall ตรงที่เพิ่งเข้าเขต Duskwood" },
        progress = { "22:316587522:386019714 N 198:696885779:147441767", "ระวังตัวข้างนอกด้วย {name} ข้ารู้ว่า Trias ส่งเจ้ามา แต่นั่นไม่ได้แปลว่าไม่มีสิ่งใดซุ่มอยู่ในป่าที่สร้างปัญหาให้เจ้าได้... ยิ่งเจ้ากำลังสืบเรื่อง Defias ด้วยแล้ว" },
        completion = { "268:132913019:94936904", "กลับมาปลอดภัยดี จะขออะไรมากกว่านี้ได้อีก จริงไหม?\n\nมาดูกันว่าเราได้อะไรมา ในบรรดาเอกสาร Defias ที่ข้าเคยเห็น นี่ดูเป็นทางการทีเดียว แต่ก็อาจเป็นของปลอมไว้หลอกให้เจ้าหลงทางจากสิ่งที่กำลังตามหา" },
        required = { [5947] = { "13:1042641539:1496478506", "แฟ้มเอกสารของ Defias" } },
        steps = { { "13:1042641539:1496478506", "แฟ้มเอกสารของ Defias" } },
    },
    [1245] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "53:812662754:461282969", "นำ Defias Docket ไปให้ Elling Trias ที่ Stormwind" },
        description = { "300:1623933108:99825781 N 139:474769359:1112009067", "เดี๋ยวนะ นี่ซับซ้อนเกินกว่าจะทำมาแค่หลอกเจ้า ข้าไม่ควรได้อ่านของพวกนี้ด้วยซ้ำ นำไปให้ Trias เขาจะเข้าใจมัน และอย่าให้ใครขวางเจ้าเด็ดขาด เรื่องนี้ใหญ่เกินข้า อาจใหญ่เกินเขาด้วย แต่เดี๋ยวก็รู้\n\nช่วยอย่างหนึ่งนะ {name} อย่าบอกใครว่าข้าช่วยเจ้า หากผู้บังคับบัญชารู้ว่าข้ารู้เรื่องนี้แล้วไม่รายงาน พวกเขาคงแขวนคอข้า" },
        progress = { "173:111227043:50683724", "เห็นว่ากลับมาแล้ว แถมยังอยู่ครบทั้งตัว เราต่างรู้ว่าเจ้าไม่ได้มาซื้อชีส ไม่ต้องเสียเวลาทักทาย Backus ช่วยอะไรได้ไหม หรือเจ้ายังไม่ได้ออกไป Duskwood เลย?" },
        completion = { "221:1028193060:1268895357", "ใช่... อ่านแล้วน่าสนใจ Jorgen กับ DeLavey คิดถูกที่ดึงข้าเข้ามา\n\nดูเหมือน Defias พยายามเต็มที่ให้แผนสำเร็จ อืม... นี่อะไร? \"Fist\" หรือ? ชื่อคุ้น ๆ" },
        required = { [5947] = { "13:1042641539:1496478506", "แฟ้มเอกสารของ Defias" } },
        steps = { { "13:1042641539:1496478506", "แฟ้มเอกสารของ Defias" } },
    },
    [1246] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "39:1985417462:1500787431", "คุยกับ Dashel Stonefist ที่ Stormwind" },
        description = { "504:1181773854:1036582256", "ใช่ พอมานึกดู... Dashel... Dashel อะไรสักอย่าง... ชื่ออะไรนะ? FIST! Dashel Stonefist บางวงเรียกเขาว่า Fist คงเพราะชอบทะเลาะต่อยตี\n\nปกติพบเขาได้ใน Old Town ตรงใจกลางเลย ไปคุยกับเขา หากจำเป็นก็ใช้ดาบหรือของหนักทื่อเกลี้ยกล่อมให้ยอมปริปาก อย่าลังเล หากเขาพัวพันลึกอย่างที่เอกสารบอก เขาคงไม่ยอมให้ข้อมูลดี ๆ หรอก" },
        completion = { "129:1009027128:994224785", "อะไรนะ?!\n\nเจ้าบุกเข้ามาในตรอกข้าแล้วถามเรื่องส่วนตัวงั้นรึ? เรื่องที่เห็นชัดว่าไม่เกี่ยวกับเจ้าเลย" },
    },
    [1248] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "33:1977169332:1864308468", "คุยกับ Mikhail ที่ Wetlands" },
        description = { "507:1273410152:682565331", "คนรู้จักของข้าคนหนึ่งเกษียณไปอยู่ Menethil เมืองท่าใน Wetlands หากเจ้าบอกว่าทำงานให้ข้า เขาก็น่าจะยอมช่วยโดยเชื่อคำเจ้า ชื่อของเขาคือ Mikhail ก่อนออกจาก Stormwind เมื่อหลายปีก่อน เขาเคยพูดว่าจะไปเป็นคนขายเหล้า\n\nคุยกับเขา ตามหา Slim แล้วดูว่ามีอะไรให้รู้เพิ่มเกี่ยวกับนักการทูตที่ถูกลักพาตัว เราต้องรู้ว่าพวกนั้นพาเขาไปไหน หรืออย่างน้อยเขาเป็นใคร เอกสารไม่ได้บอกแผนหลังจับตัวได้เลย" },
        completion = { "27:1567324533:1120608111 N 298:1987467022:1739904436", "ยินดีต้อนรับ ยินดีต้อนรับ {name} ดีใจที่เจ้ามาร่วมวง วันนี้รับเอลไหม? หรือเนื้อแกะสักหน่อย?\n\nบอกสิว่าต้องการอะไร ข้าจะดูแลให้ ข้าชื่อ Mikhail ยินดีรับใช้เจ้า\n\nหืม? อะไรนะ Trias หรือ? เบาเสียงหน่อยสหาย เรื่องนี้ไม่ควรให้ทั้งโรงเหล้าได้ยิน" },
    },
    [1249] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "77:225725784:24554151", "ปราบ Tapoke Jahn ให้ยอมจำนนก่อนเขาหนี แล้วกลับไปหา Mikhail ที่ Menethil" },
        description = { "250:847283196:1536905887 N 227:1301871601:1983193376", "เจ้าว่า Elling ส่งมาที่นี่หรือ? ถ้าอย่างนั้นการต้อนรับเมื่อครู่ขอเพิ่มเป็นสิบเท่า ต้องการอะไรก็บอก ข้าจะช่วยให้เต็มที่\n\nอืม เจ้าบอกว่า Slim หรือ? ไม่แน่ใจว่าคุ้นชื่อ แต่จะช่วยมองหาให้\n\nอย่าเพิ่งหันไปนะ {name} สุภาพบุรุษใกล้ทางออกกำลังมองมาที่นี่ เขาตั้งใจฟังเราคุยกันมากเกินไปนิด หากเข้าใจที่ข้าหมายถึงนะ ถ้าเป็นข้า ข้าจะหาทางปราบเขาให้ยอมจำนนก่อนชิงวิ่งหนีออกประตู" },
        progress = { "70:1521753501:1817321413", "เขาหลุดหนีไปหรือ? ท่าที่เขาคอยมองเราดูน่าสงสัยอยู่หน่อย" },
        completion = { "435:1830439842:129858807", "จับได้แล้วหรือ? เก่งมาก ข้าแปลกใจว่านั่นคือ Slim\n\nพูดตามตรง ข้าไม่เคยคิดว่าจะคิดถึงความตื่นเต้นของกิจกรรมใต้ดินเจ้าเล่ห์พวกนั้น นิสัยเก่าคงแก้ยาก อย่าบอก Elling ล่ะ ถ้าได้ยินว่าข้าคิดถึงความตื่นเต้น เขาคงพยายามให้ข้ากลับ Stormwind\n\nดีใจที่อย่างน้อยก็ช่วยเจ้าได้บ้างตอนอยู่ Menethil ต้องการอะไรก็บอก" },
        objectiveLabels = {
            event = { ["Defeat Tapoke Jahn"] = "เอาชนะ Tapoke Jahn" },
        },
    },
    [1250] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "33:1977169332:1864308468", "คุยกับ Mikhail ที่ Wetlands" },
        description = { "508:770328249:1512588640", "Defias ไม่ได้จ่ายข้ามากพอให้ยอมตายเพื่อมัน พวกมันจับกษัตริย์ไป ใช่ กษัตริย์แห่ง Stormwind ไม่ใช่นักการทูตกระจอก พระองค์กำลังไป Theramore เพื่อพบ Jaina Proudmore ดูเหมือนเป็นเรื่องใหญ่และเป็นความลับมาก แต่ไม่ได้มีแค่ Defias พวกมันร่วมมือกับใครบางคน ข้าว่าพวกมันรู้ว่าเรื่องนี้ใหญ่เกินตัว\n\nส่วนของข้าแค่พาคนของพวกมันขึ้นเรือกษัตริย์ตอนเรืออยู่ในท่า ชายคนนั้นชื่อ Hendel ข้ารู้แค่นี้ สาบานได้!", variants = { { "502:626845713:1962699344", "Defias ไม่ได้จ่ายข้ามากพอให้ยอมตายเพื่อมัน พวกมันจับกษัตริย์ไป ใช่ กษัตริย์แห่ง Stormwind ไม่ใช่นักการทูตกระจอก พระองค์กำลังไป Theramore เพื่อพบ Jaina Proudmoore ดูเหมือนเป็นเรื่องใหญ่และเป็นความลับมาก แต่ไม่ได้มีแค่ Defias พวกมันร่วมมือกับใครบางคน ข้าว่าพวกมันรู้ว่าเรื่องนี้ใหญ่เกินตัว\n\nส่วนของข้าแค่พาคนของพวกมันขึ้นเรือกษัตริย์ขณะเรือจอดเทียบท่า ชายคนนั้นชื่อ Hendel ข้ารู้แค่นี้ สาบานได้!" } } },
        completion = { "494:923775621:563798280", "กษัตริย์งั้นรึ?! ข้าหมายถึง... กษัตริย์น่ะหรือ? กษัตริย์ตัวจริง? ล้อเล่นหรือเปล่า? เจ้าไม่ได้บอกว่ากำลังตามคนที่ลักพาตัวกษัตริย์ ข้ายังไม่รู้ด้วยซ้ำว่าพระองค์หายไป แบบนี้ก็พออธิบายได้แล้วว่าทำไมพระโอรสจึงขึ้นครองราชย์\n\nข้าจะส่งข่าวให้ Elling ทันที เขาคงอยากรู้ว่าเจ้าตามรอยอยู่\n\nไม่เคยคิดว่า Jahn จะขาย Stormwind เพื่อเงินกระจอกไม่กี่เหรียญ แม้แต่โจรก็ยังต้องมีเกียรติในบางเรื่อง\n\nตอนนี้สำคัญที่ต้องหา Hendel และข้าคิดว่าช่วยเรื่องนั้นได้" },
    },
    [1264] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "42:3757348:1484472690", "ตามหา Commander Samaul ที่ Dustwallow Marsh" },
        description = { "493:1888427262:1824613640", "ทุกต้นเดือนทหารนาวิกโยธิน Kul Tiras จะได้รับค่าจ้าง และมักออกจาก Theramore ไปเที่ยวที่อื่น หลายคนมาที่นี่เพื่อเกี้ยวผู้หญิง ดื่มเหล้า และสนุกกัน กลุ่มหนึ่งถือเป็นขาประจำโรงเหล้า ข้าเชื่อว่า Hendel อยู่ในกลุ่มนั้น\n\nCommander Samaul ที่ Theramore คงช่วยเจ้าหาเขาได้ หาก Hendel ยังประจำการอยู่ที่นั่น เขาภักดีต่อ Proudmoore อย่างเต็มที่ แต่หากเอ่ยชื่อ Elling ก็น่าจะช่วยเจ้า... อย่างเงียบ ๆ" },
        completion = { "24:1541942836:1863377639 N 423:1666222462:1986279290", "ยินดีที่ได้พบ {name} ข้าคือ Commander Samaul ผู้บัญชาการกองกำลังของคุณ Proudmoore ที่ Theramore\n\nแม้ข้าจะยุ่งมาก หากมีคำถามก็เชิญถามได้ ข้าอาจต้องตอบสั้น ๆ แต่ไม่มีเหตุผลให้เสียมารยาทหากเจ้าต้องการความช่วยเหลือ\n\nถ้าคิดจะออกนอกเมือง ข้าแนะนำให้ระวัง นอกจากออเกอร์ ออร์ค และเมอร์ล็อกแล้ว ทางใต้ของบึงยังเต็มไปด้วยมังกรดำ" },
    },
    [1266] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "40:526370581:708939155", "ตามหา Private Hendel ใน Dustwallow Marsh" },
        description = { "486:1121690368:922186258", "Private Hendel อยู่ทางตะวันตกของที่นี่ ตอนนี้เข้าเวรคุ้มกันสายแทรกซึมของ Theramore บางคนขณะพัก พวกนั้นคอยจับตา Brackenwall ฐานของ Horde และมองหาภัยอื่นที่อาจคุกคามชายแดนเรา\n\nเจ้าคงหาไม่ยาก แค่มองหากระโจมริมถนน\n\nข้ามีอีกเรื่องต้องจัดการ แต่จะตามเจ้าไปในไม่ช้า หากมีปัญหา เจ้าพบข้าได้เสมอที่หอคอยของ Lady Proudmoore" },
        completion = { "417:541626559:440711670", "สวัสดี ประชาชน ที่นี่อันตรายเกินกว่าจะเดินเตร่ หากยังรักชีวิต ข้าคงไม่อยู่แถวนานนัก\n\nถ้าถามสั้น ๆ ข้าจะดูว่าช่วยอะไรได้บ้าง แค่ระวังออเกอร์โสโครกพวกนั้นไว้ มีข่าวลือว่าฐาน Horde อยู่ที่ไหนสักแห่งในบึง สายแทรกซึมพยายามหาอยู่ แต่กระบวนการช้าและคืบหน้าน้อยมาก" },
    },
    [1267] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "45:190749714:1301708317", "คุยกับ Jaina Proudmore ที่ Dustwallow Swamp", variants = { { "46:774709043:1160392555", "คุยกับ Jaina Proudmoore ที่ Dustwallow Swamp" } } },
        completion = { "50:276638244:1197546309 N 387:529163764:1683396973 N 1:46:46", "ให้ข้าเป็นคนแรกที่ขอบใจสำหรับทุกสิ่งที่เจ้าทำ {name} เจ้าช่วยเหลือประชาชนของข้าและชาว Stormwind อย่างใหญ่หลวง ข้าเสียใจที่ไม่ได้รู้จักเจ้าภายใต้สถานการณ์ที่ดีกว่านี้\n\nโปรดเข้าใจด้วยว่าข้าไม่อาจขอบใจเจ้าต่อสาธารณะได้ แต่ขอยืนยันอีกครั้งว่าซาบซึ้งในความพยายามของเจ้า\n\nเมื่อมา Theramore ในอนาคต จงมาหาข้า ข้าจะพยายามแจ้งความคืบหน้าของสถานการณ์ให้รู้\n\nขอบใจอีกครั้ง {name}" },
        description = { "7:989913233:66981971 N 239:1213883241:1734436587", "สวัสดี {name}! Tervosh เล่าเรื่องภารกิจของเจ้าให้ข้าฟังมากแล้ว พอรู้ว่าเจ้ากำลังตามหาคนหนึ่งที่มีส่วนโดยตรงกับการหายตัวไปของนักการทูต เราก็จำเป็นต้องตามหาเจ้า เพื่อให้แน่ใจว่าจะจัดการเขาได้โดยเร็ว" },
    },
    [1274] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "38:1815665619:863425521", "ตามหา Bishop DeLavey ที่ Stormwind Keep" },
        description = { { "312:1755084129:1693025950", "313:1691411323:952775725" }, "ขอโทษนะท่าน Bishop DeLavey ขอให้ข้าติดต่อเหล่านักผจญภัยที่อาจช่วยเรื่องละเอียดอ่อนได้\n\nหากท่านไป Stormwind Keep อย่างเงียบ ๆ แล้วคุยกับเขาเมื่อสะดวกโดยเร็ว ข้ามั่นใจว่าเขาจะซาบซึ้งในความช่วยเหลือ ขอย้ำว่าโปรดเก็บเป็นความลับ เรื่องนี้สำคัญทีเดียว", variants = { { "311:915419600:49702675", "ขอโทษนะท่าน Bishop DeLavey ขอให้ข้าติดต่อเหล่านักผจญภัยที่อาจช่วยเรื่องละเอียดอ่อนได้\n\nหากท่านไป Stormwind Keep อย่างเงียบ ๆ แล้วคุยกับเขาเมื่อสะดวกโดยเร็ว ข้ามั่นใจว่าเขาจะซาบซึ้งในความช่วยเหลือ ขอย้ำว่าโปรดเก็บเป็นความลับ เรื่องนี้สำคัญทีเดียว" } } },
        completion = { "7:989913233:66981971 N 348:2130002868:1153377650", "สวัสดี {name} ข้าคือ Bishop DeLavey\n\nหากเจ้ามาถามเรื่องงานของข้าที่ปราสาท ก็คงแปลว่า Thomas หนุ่มน้อยชักชวนเจ้ามาช่วยอาณาจักรได้แล้ว เขาทำตามคำขอของข้าได้ดีเสมอ\n\nเกรงว่าข้าไม่มีเวลาอธิบายมาก ขอพูดตรง ๆ... และโปรดอย่าให้เรื่องนี้กลายเป็นที่รู้กันทั่วไป" },
    },
    [1324] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "42:886005141:1035862577", "เอาชนะ Private Hendel ที่ Dustwallow Marsh" },
        description = { "172:1801384317:1199375819", "อะไรนะ?! เจ้าบุกมากล่าวหาว่าข้าร่วมมือกับ Defias แล้วคิดว่าข้าจะยืนเฉยให้ดูหมิ่นรึ?! ดูท่าเจ้าคงสมควรโดนมานานแล้ว" },
        progress = { "13:1366380142:1891123769 N 101:1766156661:282079875", "สวัสดีอีกครั้ง {name} หวังว่าเจ้าคงไม่รังเกียจที่เราช่วย แต่เราปล่อยให้ Hendel หนีไม่ได้ หรือที่แย่กว่านั้นคือตายไป" },
        completion = { "263:989465703:651321126", "ข้ารับรองว่าพวกเราล้วนไม่พอใจกับเหตุการณ์ตอนนี้ แต่ขอให้เราพาเขากลับ Theramore เพื่อสอบปากคำ แล้วจะดูเรื่องตามหากษัตริย์ต่อ\n\nข้ามั่นใจว่า Lady Proudmore อยากขอบใจที่เจ้าช่วย หากมีเวลาจงไปคุยกับนาง", variants = { { "264:812181935:863596333", "ข้ารับรองว่าพวกเราต่างไม่สบายใจกับเรื่องที่เกิดขึ้น แต่ขอให้เราพาเขากลับ Theramore ไปสอบปากคำก่อน แล้วเราจะหาทางตามหากษัตริย์\n\nข้ามั่นใจว่า Lady Proudmoore อยากขอบคุณที่เจ้าช่วย ว่างเมื่อไรก็ไปพบนางเถอะ" } } },
        objectiveLabels = {
            event = { ["Subdue Private Hendel"] = "ปราบ Private Hendel ให้ยอมจำนน" },
        },
    },
    [1363] = { -- Mazen's Behest
        title = { "14:122266709:574583876", "คำขอของ Mazen" },
        objective = { "39:745132519:1191889280", "คุยกับ Acolyte Dellis ที่ Stormwind" },
        description = { "501:1254556235:1823815654", "ในฐานะผู้ดูแลงานเขียนในห้องสมุด Academy of Arcane Arts and Sciences ข้ามีหน้าที่ตรวจให้ตำราเวทและม้วนคัมภีร์ทุกชิ้นอยู่ครบตลอดเวลา ใครจะรู้ว่าเรื่องโง่เขลาอะไรจะเกิดขึ้น หากอักษรต้องมนตร์เหล่านี้ตกไปอยู่ในมือคนผิด?\n\nพูดแล้วก็นึกขึ้นได้... Dellis ผู้ช่วยข้าทำผิดพลาดร้ายแรงเมื่อสัปดาห์ก่อน อยู่ในห้องสมุดก็เก่งดี แต่พอพ้นประตู Stormwind กลับไม่ได้เรื่อง ช่วยเป็นวีรบุรุษไปช่วย Dellis หน่อยได้ไหม?" },
        completion = { "37:140938182:1556053809", "ไม่ใช่ความผิดข้านะ ไม่ใช่จริง ๆ" },
    },
    [1364] = { -- Mazen's Behest
        title = { "14:122266709:574583876", "คำขอของ Mazen" },
        objective = { "110:2043613339:1822729249", "นำ Khadgar's Essays on Dimensional Convergence กลับคืนมา แล้วส่งให้ Watcher Mahar Ba ที่ Nethergarde Keep" },
        description = { "494:2131441032:35309289", "คำสั่งของอาจารย์ Mazen ชัดเจนมาก ให้นำบทความสำคัญไปส่ง Watcher Mahar Ba ที่ Nethergarde Keep\n\nแต่ข้าไม่เคยไป Blasted Lands มาก่อน! การเดินทางน่ากลัวมาก!\n\nพอถึง Swamp of Sorrows ข้าเลี้ยวผิดจนถูกสัตว์บึงรูปร่างคล้ายพืชน่าสยดสยองล้อมไว้ พวกมันโถมเข้ามาราวจะโจมตี ข้าจึงวิ่งหนี แต่รีบร้อนจนทำบทความตก ข้ามั่นใจว่าสัตว์ตัวหนึ่งเอาไป\n\nเจ้าช่วยเอาคืนมาแล้วนำไปส่ง Mahar Ba ได้ไหม?" },
        progress = { "37:159877704:379648389 R 1:63:63", "อะไรพาเจ้ามาที่ Nethergarde Keep ชาว{race}?" },
        completion = { "414:1173485600:729757066", "อา วิเศษที่สุด!\n\nข้าเคยกลัวอยู่นานว่าอาจารย์ Mazen แห่ง Academy of Arcane Arts and Sciences จะมองข้ามคำขอ Khadgar's Essays on Dimensional Convergence ของข้า\n\nเขาคงติดพันกับคำขอมากมาย เพราะมีเรื่องแปลก ๆ เกิดขึ้นไม่หยุด\n\nขอตัวก่อน ข้าต้องเริ่มวิจัยทันที การจะได้เห็นข้อคิดของผู้ยิ่งใหญ่อย่าง Khadgar ทำให้ข้าตื่นเต้นเหลือเกิน" },
        required = { [6065] = { "43:1978121378:558666384", "บทความของ Khadgar ว่าด้วยการบรรจบกันของมิติ" } },
        steps = { { "43:1978121378:558666384", "บทความของ Khadgar ว่าด้วยการบรรจบกันของมิติ" } },
    },
    [1447] = { -- The Missing Diplomat
        title = { "20:426690917:1416213843", "นักการทูตที่หายไป" },
        objective = { "37:348748269:1296512737", "เอาชนะ Dashel Stonefist ที่ Stormwind" },
        description = { "40:1707301896:1739651316 C 107:1383237283:1569412831", "ใช่ เห็นชัดว่าเจ้าไม่ใช่{class}ที่ฉลาดที่สุดที่เข้ามาใน Stormwind แต่เจ้ากำลังจะเป็นหนึ่งในคนโง่ที่สุดที่ไม่มีวันได้ออกไป\n\nเจอเพื่อนข้าหรือยัง?" },
        progress = { "63:1245510322:1763279476 C 41:1668728251:1447843598", "ที่พูดว่าเจ้าเป็น{class}โง่ ๆ ข้าไม่ได้หมายความอย่างนั้นนะ เราเป็นเพื่อนกันใช่ไหม? ไม่ถือสากันนะ?" },
        completion = { "53:238225684:1598239961", "เจ้ามาหาข้าเพราะมีเหตุผลสินะ ต้องการอะไร?" },
        objectiveLabels = {
            event = { ["Defeat Dashel Stonefist"] = "เอาชนะ Dashel Stonefist" },
        },
    },
    [1477] = { -- Vital Supplies
        title = { "14:537863084:1685596032", "เสบียงสำคัญ" },
        objective = { "31:1194489776:1204507199", "คุยกับ Watchmaster Sorigal" },
        description = { "383:30221494:1167404333 N 19:413057432:1660150586", "จอมเวทของเรากำลังวิจัยที่ Nethergarde Keep ใน Blasted Lands งานนี้สำคัญต่อความเข้าใจเรื่อง Dark Portals พวกเขาต้องใช้เสบียงแทบตลอดเวลา แต่เส้นทางส่งเสบียงไป Nethergarde ของเราไม่มั่นคง\n\nเจ้าต้องช่วยให้เสบียงไปถึง Nethergard ไปรายงานตัวต่อ Watchmaster Sorigal ที่ Darkshire แล้วทำตามคำขอ งานนี้จะพาเจ้าเข้าดินแดนศัตรู {name} เตรียมตัวให้พร้อม" },
        completion = { "66:2130171798:480965341", "Andromath ส่งเจ้ามาหรือ? ดีมาก ข้ามีงานสำคัญให้ทำ..." },
    },
    [2745] = { -- Infiltrating the Castle
        title = { "23:1725307591:1388876576", "แทรกซึมปราสาท" },
        objective = { "36:1147496828:1172423371", "คุยกับ Tyrion ที่ Stormwind Castle" },
        description = { "494:23819290:1825648088", "อืม เรื่องน่าสนใจ และมองข้ามไม่ได้ ใช่ ข้าช่วยเจ้าได้ แต่หากจะทำจนจบ เจ้าต้องลงโทษในรูปแบบที่ไม่... ถูกกฎหมาย\n\nต้องจัดการ Lescovar กับ Marzon โดยเร็ว เจ้าคิดว่าทำได้ไหม?\n\nตัดสินใจเอง หากทำได้ก็รีบไปปราสาท ตามหาสหายเก่าของข้าชื่อ Tyrion เป็นโนม เขาเฝ้าดู Lescovar มาสองสามสัปดาห์แล้ว น่าจะช่วยเจ้าจบเรื่องนี้ได้" },
        completion = { "439:846977534:842195591", "อะไรกัน...?! อย่าย่องเข้ามาแบบนั้น! แล้วเบาเสียงด้วย! ในนามแห่งเงามืด เจ้าย่องเข้ามาหาข้าทำไม? ไม่เห็นหรือว่าข้ากำลังยุ่ง เจ้าคนโง่?\n\nหมายความว่าอย่างไรที่ถามว่าข้าทำอะไร? รอ Dark Portal แห่งถัดไปเปิดอยู่น่ะสิ คิดว่าข้าทำอะไรล่ะ? มีอะไรก็พูดแล้วไปเสีย... ก่อนยามเห็นว่าเราสองคนซ่อนอยู่ในพุ่มไม้ด้วยกัน ข้ามีชื่อเสียงต้องรักษา" },
    },
    [2746] = { -- Items of Some Consequence
        title = { "25:168127978:1230519223", "ของที่มีความสำคัญอยู่บ้าง" },
        objective = { "72:1876645266:1048275035", "นำ Silk Cloth 3 ผืน และ Clara's Fresh Apples 2 ผล ไปให้ Tyrion ที่ Stormwind" },
        description = { { "486:7189697:632145010", "486:204467506:1285316243" }, "Trias อยากให้ขยับเวลามาเร็วขึ้นหน่อยสินะ? ได้ แต่ข้ายังไม่พร้อม และรู้ไว้ด้วย ข้าทำส่วนยาก แต่เจ้าจะเป็นคนลงมือทำเรื่องสกปรก เข้าใจไหม? ดี\n\nเอาล่ะ ข้าต้องให้เจ้าหาของบางอย่างก่อนเริ่มแผน ข้ามีชุดปลอมตัวที่เหมาะเจาะ ช่วยให้ Spybot ผ่านยามพวกนั้นไปได้\n\nเอาผ้าไหมกับแอปเปิลสองผลมา ผ้าไหมเจ้าจัดหาเอง ส่วนแอปเปิลจากไร่เล็ก ๆ ของ Clara นอกเมืองมีขนาดพอดี" },
        progress = { "382:1629073318:1442372364", "ข้าเฝ้าดู Lescovar มาสองสามสัปดาห์แล้ว Trias ไม่เคยไว้ใจเขา แต่เราไม่เคยสงสัยว่าจะเกี่ยวกับ Defias Brotherhood เราตามเบาะแสที่เชื่อมเขากับ Twilight's Hammer อยู่ ไม่ว่าอย่างไร เขาก็อันตรายเกินกว่าเมืองนี้จะรับมือ นั่นจึงเป็นหน้าที่ของเรา\n\nนำของพวกนั้นมา แล้วเราจะเริ่มแผนได้" },
        completion = { "22:1465595043:356124885 N 276:2084754523:50065875", "ของพวกนี้เหมาะเลย {name} ทำได้ดี\n\nอุปกรณ์ที่ต้องใช้นอกนั้นอยู่ในเป้ข้าแล้ว... ขอบคุณแสงสว่างที่ข้าเพิ่งให้เพื่อนช่างตัดเสื้อทำกระเป๋าผ้าไหมให้ แบกของไปมาจนแทบไม่มีที่เหลือ\n\nก่อนส่ง Spybot เข้าไป มาทบทวนรายละเอียดให้เจ้ารู้ว่าต้องทำอะไร" },
        required = { [4306] = { "10:1269080011:1976271755", "ผ้าไหม" }, [8683] = { "19:62312144:1678493919", "แอปเปิลสดของ Clara" } },
        steps = { { "10:1269080011:1976271755", "ผ้าไหม" }, { "19:62312144:1678493919", "แอปเปิลสดของ Clara" } },
    },
    [3765] = { -- The Corruption Abroad
        title = { "21:145956875:1541131498", "ความเสื่อมทรามในแดนไกล" },
        objective = { "45:61342611:2051117354", "เดินทางไปหา Gershala Nightwhisper ที่ Auberdine" },
        description = { "345:1084606098:1033900414 C 18:807710612:960958540", "Stormwind ช่างเป็นเมืองศูนย์กลางที่คึกคัก\n\nข้าเดินทางจากแดนไกลมาเพื่อขอความช่วยเหลือ ได้ยินเสมอว่ามีนักผจญภัยผู้กล้าเดินอยู่ตามถนนเมืองนี้\n\nGershala พี่น้องของข้าต้องการความช่วยเหลือใน Darkshore เขาอยู่ที่ Auberdine เมืองชายทะเล\n\nเส้นทางนั้นไกลและยิ่งใหญ่ จึงเป็นเหตุให้ข้าขอความช่วยเหลือจาก{class}ผู้มีประสบการณ์เช่นเจ้า" },
        completion = { "114:1109339561:1557352560", "อา Argos พี่น้องของข้าส่งเจ้ามาหรือ? ข้ารู้ว่าเจ้าคงเหนื่อยจากการเดินทาง แต่เรามีเรื่องต้องคุยกันมาก" },
    },
    [5048] = { -- Good Natured Emma
        title = { "17:747342367:1085457381", "Emma ผู้ใจดี" },
        objective = { "144:388576593:1443210235", "ตามหา Ol' Emma ที่ Stormwind แล้วดูว่านางคือ Emma Felstone จริงหรือไม่ หากใช่ นางอาจอยากได้ห่อของที่ Janice Felstone ทำไว้ให้" },
        description = { "473:855191821:365333489", "นางขี้หงุดหงิดอยู่หน่อย และอาจเสียสติไปแล้ว... แต่บันทึกบอกว่า Ol' Emma มีลักษณะตรงกับคนที่อาจเป็น Emma Felstone\n\nบางทีเจ้าอาจเคยเห็น Ol' Emma เดินเตร่ในเมือง นางพูดกับตัวเอง ส่วนใหญ่งึมงำไม่ได้เรื่อง แต่ก็ไม่ได้ทำร้ายใครหรืออะไร ผู้คนจึงปล่อยให้อยู่อย่างนั้น\n\nเมื่อพิจารณาทั้งหมด ข้าว่า Ol' Emma คือ Emma Felstone จริง ๆ เจ้าอาจลองถามดูว่านามสกุล Felstone ใช่หรือไม่" },
        progress = { "73:1624454104:1255702973", "ข้าอยากบอกให้เจ้าออกไปจากสนามหญ้าข้า แต่ก็เห็นอยู่ว่าข้าไม่มีสนามหญ้า" },
        completion = { "470:121777171:610159912", "ข้าชื่อ Emma Felstone จริง ๆ เจ้าเป็นคนแรกในรอบหลายปีที่เรียกข้าอย่างนั้น ใคร... เจ้าเป็นใคร?\n\nเจ้าว่ารู้จัก... พี่น้องของข้าหรือ?! นางยังมีชีวิตไหม? ข้าหลอกใครอยู่ แน่นอนว่าไม่แล้ว ตอนโรคระบาดเกิดใน Lordaeron ข้าก็ทำใจรับสิ่งเลวร้ายที่สุด คนในครอบครัวข้าตายไปมาก... หรือแย่กว่านั้น ตอนนี้ข้ากลายเป็น Ol' Emma บ้า ๆ อยู่ตัวคนเดียว เจ้าเป็นอะไร นักขุดสุสานหรือไง? มองหาเป้าหมายรายต่อไปหรือ?\n\nอะไรนะ... เจ้าถือห่อของจากพี่น้องข้ามาให้หรือ?" },
        required = { [12724] = { "15:1442721204:1307405515", "พัสดุของ Janice" } },
        steps = { { "15:1442721204:1307405515", "พัสดุของ Janice" } },
    },
    [6182] = { -- The First and the Last
        title = { "22:905640507:953895865", "คนแรกและคนสุดท้าย" },
        objective = { "74:1800391310:1020797312", "คุยกับ Mathias Shaw ใน Old Town ของ Stormwind เขาอยู่ที่ Barracks" },
        description = { "503:1985793762:658941871", "Nathanos Marris เป็นมนุษย์คนแรกและคนสุดท้ายที่เป็นจ้าวแห่งเรนเจอร์ เป็นศิษย์ของ Sylvanas Windrunner ซึ่งตอนนี้คือราชินีแบนชีแห่ง Forsaken\n\nเราเคยคิดว่า Nathanos เสียชีวิตในการรบปกป้อง Lordaeron เมื่อห้าปีก่อน แม้ไม่พบศพ ก็เชื่อกันว่าเขาออกจาก Eastern Plaguelands ไม่สำเร็จ\n\nMathias Shaw สืบเรื่องการหายตัวไปอยู่ และอาจมีข้อมูลใหม่ ไปรายงานตัวต่อเขาทันที เขาอยู่ที่ Barracks ใน Old Town" },
        completion = { "169:175237173:1186428751", "หลังมีรายงานความเคลื่อนไหวผิดปกติของ Forsaken ใน Eastern Plaguelands เราส่งเจ้าหน้าที่ SI:7 ไปตรวจสอบ ผลที่ได้น่าวิตก" },
    },
    [6183] = { -- Honor the Dead
        title = { "14:872580422:1718853616", "ให้เกียรติผู้ล่วงลับ" },
        objective = { "61:5234575:1934460862", "คุยกับ Mathias Shaw อีกครั้งหากต้องการรับงานของเขา" },
        description = { "474:1874093274:148848247", "ข้ามอบหมายคดี Marris ให้เจ้าหน้าที่ภาคสนามฝีมือดีที่สุดห้าคน มีคนกลับมาเพียงคนเดียว แล้วก็ตายขณะหลับในอีกสามวันต่อมา\n\nข้อมูลน้อยนิดที่ได้จากเขาเป็นคำพูดวกวนไม่ได้ความ เราจับได้สองคำ คือ \"Nathanos\" กับ \"Blightcaller\"\n\nข้าไม่มีกำลังคนว่างพอจะสืบต่อ และ Ravenholdt ก็ไม่ยอมช่วย เราต้องรู้ความจริง อย่างน้อยเพื่อให้ครอบครัวผู้ตายคลายค้างคา เจ้าจะช่วยไหม?" },
        completion = { "123:1981494198:1457894301", "<Mathias พยักหน้า>\n\nข้าเชื่อมั่นว่า Bolvar จะส่งชายหญิงผู้มีเกียรติมาให้ ทหารที่อุทิศตนที่สุดของ Alliance" },
    },
    [6186] = { -- The Blightcaller Cometh
        title = { "23:958620781:528042158", "Blightcaller มาเยือน" },
        objective = { "88:1413670098:859600962", "กลับ Stormwind แล้วแจ้งชะตากรรมของ Nathanos Marris ให้ Highlord Bolvar Fordragon ทราบ" },
        description = { "316:1584388168:529732376 N 123:690879807:25062013", "<ใบหน้าของ Flint ดูซีดเผือดราวกับไร้เลือด>\n\nNa... Nathanos ทำอย่างนี้หรือ? Nathanos คือ Blightcaller งั้นรึ?\n\nทำไม? เขาเคย... มีเกียรตินัก เป็นจ้าวแห่งเรนเจอร์ที่ทุกคนเคารพ มนุษย์เพียงคนเดียวที่ได้รับอนุญาตให้ฝึกกับไฮเอลฟ์ ตอนนี้กลับเป็นผู้รับใช้ Forsaken ที่ไร้ปรานีหรือ?\n\nข้า... ข้าเสียใจที่ต้องขอ {name} แต่ต้องแจ้งเรื่องที่พลิกผันนี้ให้ Highlord Fordragon ทราบทันที โปรดกลับ Stormwind แล้วนำข่าวไปบอก" },
        completion = { "127:2031003297:764174475", "ไม่ เป็นไป... ไม่! ได้อย่างไร? ผู้รับใช้ Forsaken รึ? ยอดนักรบของราชินีแบนชีงั้นหรือ???\n\n<Highlord Bolvar Fordragon ทรุดลงอย่างหมดอาลัย>" },
    },
    [7781] = { -- The Lord of Blackrock
        title = { "21:1231827177:1988961878", "จอมแห่ง Blackrock" },
        objective = { "70:1261462001:674769666", "นำ Head of Nefarian ไปให้ Highlord Bolvar Fordragon ที่ Stormwind" },
        description = { "191:1867632760:777564350", "ความรู้สึกเก่าหวนคืน ความปลาบปลื้มแห่งชัยชนะที่เฝ้ารอก้องกังวานไปทั่วกายใจ เบื้องหน้าเจ้าคือศีรษะมหึมาของ Nefarian ที่เต็มไปด้วยรอยแผลจากศึก นำไปให้ Highlord ของเจ้า ยอดนักรบเอ๋ย" },
        progress = { "14:621730222:107222783", "เป็นไปไม่ได้!" },
        completion = { "56:991574733:566892450 N 138:2012183392:1701226788", "ไม่ต้องมีใครบอกความหมายของสิ่งที่เจ้าทำหรอก {name} วันนี้จะถูกจารึกในประวัติศาสตร์ เป็นชัยชนะที่ Alliance ไม่เคยพบมาหลายปี หรืออาจไม่เคยพบมาก่อนเลย!" },
    },
    [7782] = { -- The Lord of Blackrock
        title = { "21:1231827177:1988961878", "จอมแห่ง Blackrock" },
        objective = { "89:465366784:1258461693", "ไปที่ Valley of Heroes ในเมือง Stormwind แล้วคุยกับ Field Marshal Afrasiabi" },
        description = { "66:125760533:915715838", "ไปที่ Valley of Heroes แล้วคุยกับ Field Marshal Afrasiabi" },
        completion = { "78:71981709:1600732505", "<Field Marshal Afrasiabi โค้งคำนับ>\n\nเลือกรางวัลของเจ้า แล้วเริ่มงานฉลองกัน!" },
    },
    [93963] = { -- Exploring the Alliance
        title = { "22:185314989:678366983", "สำรวจ Alliance" },
        objective = { "205:1598609178:2116331770", "คุยกับ Randal Emerson ที่ Stormwind Keep เพื่อรับคำแนะนำเพิ่มเติม ใช้คำแนะนำนั้นตามหาและคุยกับ King Magni Bronzebeard, High Tinker Mekkatorque และ Tyrande Whisperwind" },
        description = { "277:1064466467:165316459", "Stormwind, Ironforge และ Darnassus ต่างมีผู้คนและวัฒนธรรมเฉพาะตัว ในฐานะแขกของ Alliance บน Azeroth เจ้าควรใช้เวลาไปเยือนนครหลวงของเราทีละแห่ง\n\nคุยกับ Randal Emerson ในห้องโถงด้านใต้เพื่อรับคำแนะนำเริ่มต้น" },
        completion = { "483:243785970:1643394098", "อา กลับมาแล้ว\n\nหวังว่าการผจญภัยทำให้เจ้าเห็นขนาดและความมหัศจรรย์ของโลกเรา ข้ารู้ว่ามันคงดูมากมายเกินรับไหว แต่หากจะช่วยผู้คนของเจ้า เจ้าต้องพร้อมรับทุกสิ่งที่อาจเผชิญบน Azeroth\n\nระหว่างรอให้คณะของเจ้าตั้งหลักใน Dalaran ข้าแนะนำให้สนใจดินแดนรอบ Stormwind โดยเฉพาะ Westfall ที่ต้องการนักผจญภัยแข็งแกร่งมาช่วยเสมอ หากเจ้ายินดี" },
        progress = { "17:1033678358:1166556335 N 1:46:46", "สวัสดีอีกครั้ง {name}" },
        steps = { { "40:199604588:34538162", "รับคำสั่งจาก Randal Emerson", variants = { { "40:1982641640:1048568596", "รับคำสั่งจาก Randal Emerson" } } }, { "34:1904780931:225210816", "คุยกับ High Tinker Mekkatorque" }, { "33:1989882518:680542878", "คุยกับ King Magni Bronzebeard" }, { "30:831391339:1998545292", "คุยกับ Tyrande Whisperwind" } },
    },
    [94947] = { -- Welcome to Azeroth
        title = { "18:1918171245:194063416", "ยินดีต้อนรับสู่ Azeroth" },
        objective = { "87:356300321:87655737", "ใช้ Skyborne Portal ไป Stormwind แล้วรายงานตัวต่อ Bolvar Fordragon ที่ Stormwind Keep" },
        description = { "502:1685272953:1040231473", "โลกเบื้องล่างกว้างใหญ่นัก เราต้องให้คนของเราเริ่มออกสำรวจ และนี่คือส่วนที่เจ้าจะช่วยได้\n\nKirin Tor เป็นสมาชิกของ \"Alliance\" กลุ่มชาติที่มีแนวคิดร่วมกัน ศูนย์กลางโดยพฤตินัยของพันธมิตรนี้คือเมือง Stormwind ทางใต้ Elaadrin ขอให้ข้าหาคนไป Stormwind เพื่อพบผู้สำเร็จราชการที่นั่น มนุษย์ชื่อ Bolvar Fordragon\n\nเมื่อเจ้าพร้อม เหล่าจอมเวท Kirin Tor ได้สร้างประตูมิติพิเศษให้ High Order ใช้เดินทางเข้า Stormwind แล้ว", variants = { { "501:2123533121:167674057", "โลกเบื้องล่างกว้างใหญ่นัก เราต้องให้คนของเราเริ่มออกสำรวจ และนี่คือส่วนที่เจ้าจะช่วยได้\n\nKirin Tor เป็นสมาชิกของ \"Alliance\" กลุ่มชาติที่มีแนวคิดร่วมกัน ศูนย์กลางโดยพฤตินัยของพันธมิตรนี้คือเมือง Stormwind ทางใต้ Elaadrin ขอให้ข้าหาคนไป Stormwind เพื่อพบผู้สำเร็จราชการที่นั่น มนุษย์ชื่อ Bolvar Fordragon\n\nเมื่อเจ้าพร้อม เหล่าจอมเวท Kirin Tor ได้สร้างประตูมิติพิเศษให้ High Order ใช้เดินทางเข้า Stormwind แล้ว" } } },
        completion = { "429:886329495:275548025", "ยินดีที่ได้พบ นักผจญภัย ข้าคือ Bolvar Fordragon ผู้สำเร็จราชการแห่งบัลลังก์ Stormwind\n\nผู้ส่งสาร Kirin Tor แจ้งให้ข้าเตรียมต้อนรับสมาชิก High Order แล้วเจ้าก็มาถึง นานแล้วที่ไม่มีไฮเอลฟ์ยืนอยู่ในท้องพระโรงนี้ แต่ข้ายินดีต้อนรับเจ้าเป็นแขกในวันนี้\n\nในนามกษัตริย์ ข้าขอต้อนรับสู่ Stormwind และอนุญาตให้เดินทางในดินแดนพันธมิตรได้อย่างเสรี ยินดีต้อนรับสู่ Azeroth ชาว Skyborne", variants = { { "10:1401179418:1568553899 C 409:495681418:446754188", "ยินดีที่ได้พบ {class} ข้าคือ Bolvar Fordragon ผู้สำเร็จราชการแห่งบัลลังก์ Stormwind\n\nผู้ส่งสาร Kirin Tor แจ้งให้ข้าเตรียมต้อนรับสมาชิก High Order แล้วเจ้าก็มาถึง นานแล้วที่ไม่มีไฮเอลฟ์ยืนอยู่ในท้องพระโรงนี้ แต่ข้ายินดีต้อนรับเจ้าเป็นแขกในวันนี้\n\nในนามกษัตริย์ ข้าขอต้อนรับสู่ Stormwind และอนุญาตให้เดินทางในดินแดนพันธมิตรได้อย่างเสรี ยินดีต้อนรับสู่ Azeroth ชาว Skyborne" }, { "10:1401179418:1568553899 C 404:1668684465:37570350", "ยินดีที่ได้พบ {class} ข้าคือ Bolvar Fordragon ผู้สำเร็จราชการแห่งบัลลังก์ Stormwind\n\nผู้ส่งสาร Kirin Tor แจ้งให้ข้าเตรียมต้อนรับทูตจาก High Order แล้วเจ้าก็มาถึง นานแล้วที่ไม่มีไฮเอลฟ์ยืนอยู่ในท้องพระโรงนี้ แต่ข้ายินดีต้อนรับเจ้าเป็นแขกในวันนี้\n\nในนามกษัตริย์ ข้าขอต้อนรับสู่ Stormwind และอนุญาตให้เดินทางในดินแดนพันธมิตรได้อย่างเสรี ยินดีต้อนรับสู่ Azeroth ชาว Skyborne" }, { "10:1401179418:1568553899 C 409:1518992726:537254372", "ยินดีที่ได้พบ {class} ข้าคือ Bolvar Fordragon ผู้สำเร็จราชการแห่งบัลลังก์ Stormwind\n\nผู้ส่งสาร Kirin Tor แจ้งให้ข้าเตรียมต้อนรับสมาชิก High Order แล้วเจ้าก็มาถึง นานแล้วที่ไม่มีไฮเอลฟ์ยืนอยู่ในท้องพระโรงนี้ แต่ข้ายินดีต้อนรับเจ้าเป็นแขกในวันนี้\n\nในนามกษัตริย์ ข้าขอต้อนรับสู่ Stormwind และอนุญาตให้เดินทางในดินแดนพันธมิตรได้อย่างเสรี ยินดีต้อนรับสู่ Azeroth ชาว Skyborne" }, { "10:1401179418:1568553899 C 400:602620465:1391544054 R 1:46:46", "ยินดีที่ได้พบ {class} ข้าคือ Bolvar Fordragon ผู้สำเร็จราชการแห่งบัลลังก์ Stormwind\n\nผู้ส่งสารจาก Kirin Tor แจ้งให้ข้าเตรียมต้อนรับสมาชิก High Order และตอนนี้เจ้าก็มายืนอยู่ตรงหน้า นานแล้วที่ไม่มีไฮเอลฟ์มายืนในท้องพระโรงแห่งนี้ ข้ายินดีต้อนรับเจ้าในฐานะแขก\n\nในนามของกษัตริย์ ข้าขอต้อนรับเจ้าสู่ Stormwind และอนุญาตให้เจ้าเดินทางทั่วดินแดนของฝ่ายพันธมิตรได้อย่างเสรี ยินดีต้อนรับสู่ Azeroth ชาว{race}" }, { "10:1401179418:1568553899 C 400:1287786589:1349782143 R 1:46:46", "ยินดีที่ได้พบ {class} ข้าคือ Bolvar Fordragon ผู้สำเร็จราชการแห่งบัลลังก์ Stormwind\n\nผู้ส่งสารจาก Kirin Tor แจ้งให้ข้าเตรียมต้อนรับสมาชิก High Order และตอนนี้เจ้าก็มายืนอยู่ตรงหน้า นานแล้วที่ไม่มีไฮเอลฟ์มายืนในท้องพระโรงแห่งนี้ ข้ายินดีต้อนรับเจ้าในฐานะแขก\n\nในนามของกษัตริย์ ข้าขอต้อนรับเจ้าสู่ Stormwind และอนุญาตให้เจ้าเดินทางทั่วดินแดนของฝ่ายพันธมิตรได้อย่างเสรี ยินดีต้อนรับสู่ Azeroth ชาว{race}" } } },
        steps = { { "37:1059622728:1103361747", "ผ่านประตูมิติ Skyborne ไป Stormwind" } },
    },
    [95065] = { -- Fishin' Time
        title = { "12:991479403:414321705", "เวลาออกตกปลา" },
        objective = { "84:1741639609:175836729", "นำ Shiny Bauble 1 ชิ้น และ Nightcrawlers 3 ตัว ไปให้ Gilbert Gray ที่ท่าเรือ Stormwind", amount = { "6:1273960851:929420321 W1 18:2098659260:960526926 W2 58:2134707329:612383072", "นำ Shiny Bauble {world1} ชิ้น และ Nightcrawlers {world2} ตัว ไปให้ Gilbert Gray ที่ท่าเรือ Stormwind" } },
        description = { "503:1012623985:45874396", "วิวสวยจริง ๆ... คนแก่อย่างข้าคงขอได้ดีที่สุดเท่านี้\n\nปลากำลังกินเบ็ดดี แต่ข้าเหลือเหยื่อชิ้นสุดท้ายแล้ว เจ้าพอมีอุปกรณ์ตกปลาเหลือบ้างไหม? คงไม่มีสินะ ขอโทษด้วย แค่นึกว่าจะได้เหวี่ยงเบ็ดอีกครั้งข้าก็ตื่นเต้น จนลืมว่าข้าอาจเป็นหนึ่งในไม่กี่คนที่พกของพวกนี้ไปทุกที่\n\nช่วยเติมของให้ข้าได้ไหม? Catherine Leland มีอุปกรณ์ตกปลาหลากหลาย ขายอยู่ริมคลองทางตะวันตกของ Trade District บอกนางว่าตาแก่ Gray ส่งมา" },
        progress = { "33:574581920:677939299", "ได้อุปกรณ์ตกปลามาหรือยัง?" },
        completion = { "209:1114835362:1616339814", "มาทันเวลาพอดี! ข้าจับตัวใหญ่ได้ด้วยเหยื่อชิ้นสุดท้าย วันนี้ดีจริง ๆ ปลาแถวนี้กินเบ็ดเก่งเหลือเกิน!\n\nเอาอย่างนี้ เจ้าช่วยให้คนแก่อย่างข้ายังตกปลาต่อได้ เอาปลาสักหน่อยไว้กินระหว่างทางไหม?" },
        required = { [6529] = { "12:458856588:1306973023", "เหยื่อตกปลาวาววับ" }, [6530] = { "13:44341031:1607101331", "ไส้เดือนสำหรับตกปลา" } },
        steps = { { "12:458856588:1306973023", "เหยื่อตกปลาวาววับ" }, { "13:44341031:1607101331", "ไส้เดือนสำหรับตกปลา" } },
    },
    [97220] = { -- Philmor's Favor
        title = { "15:2026756278:515291771", "คำขอของ Philmor" },
        objective = { "107:535743998:1972064679", "นำ Gatehouse Shipment ไปยังทางเข้าห้องเก็บของที่อยู่ในร้าน Trias' Cheese ใน Trade District", variants = { { "106:1364107309:1129778255", "นำ Gatehouse Shipment ไปยังทางเข้าห้องเก็บของที่อยู่ในร้าน Trias' Cheese ใน Trade District" } } },
        description = { "417:331006249:1061898286", "ทุกวันในสัปดาห์นี้เราขาดคนงานท่าเรือ\n\nสนใจช่วยลดความตึงเครียดของตารางส่งสินค้าไหม?\n\nนำห่อนี้ไปที่ทางเข้าห้องเก็บของของ Gatehouse อยู่ในร้าน Trias' Cheese บนชั้นสอง Elaine ผู้ดูแลร้านคุ้นกับการส่งของดี Gatehouse มักรับของอย่างเงียบ ๆ เพื่อให้นายทหารยามเตรียมเรื่องเซอร์ไพรส์ในงานพิธีได้" },
        progress = { "56:36033742:109625488", "เจ้ากำลังหาชีสบ่มก้อนกลมชั้นเลิศของเราไปใส่ลังหรือ?" },
        completion = { "154:1704147601:106064318", "โอ้ ให้ตายสิ คิดว่าเราอยากแบกมันขึ้นบันไดเองหรือ? เจ้ามีหน้าที่รักษาของมีค่าให้ครบถ้วนจนกว่าจะส่งถึงจุดวางของ" },
        required = { [277119] = { "18:2066066887:683930984", "สินค้าที่ส่งมาจากป้อมประตู" } },
        steps = { { "18:2066066887:683930984", "สินค้าที่ส่งมาจากป้อมประตู" } },
    },
    [97222] = { -- Gatehouse Goods
        title = { "15:138585372:638078797", "สินค้าของ Gatehouse" },
        objective = { "88:1329011888:1934986458", "แบก Gatehouse Shipment ขึ้นบันไดในร้าน Trias แล้ววางไว้นอกประตู" },
        description = { "407:1072611971:934908716", "ใช่ มีบันไดแค่ช่วงเดียว แต่ถ้าเป็นเรื่องเล็กน้อยขนาดนั้น เจ้าก็คงส่งให้เสร็จเองได้ไม่มีปัญหา!\n\nTrias' Cheese ไม่ใช่ส่วนหนึ่งของ Gatehouse และไม่ได้ดูแลคลังสินค้าของพวกเขา เพียงแต่อาคารของเราใช้ชั้นร่วมกัน\n\nวางลังไว้นอกประตูห้องเก็บของ ยามจะส่งคนมารับตามรอบ พวกเขาจะเห็นว่าห่อของมาถึง แล้วขนเข้าไปตอนกลับมาประจำจุด" },
        completion = { { "250:1298563429:1914039376", "181:600622775:72473833 N 59:1008494170:797930462", "181:600622775:72473833 C 59:1008494170:797930462", "181:600622775:72473833 R 59:1008494170:797930462" }, "ใช่แล้ว ประตูบานนั้นเปิดเข้าด้านในฝั่งพวกเขาก็มีเหตุผล เพื่อไม่ให้ของที่ใครนึกจะวางตรงไหนก็วางมาขวางประตู\n\nถือว่าเราได้รู้จักกันในทางงานแล้ว นักผจญภัย\n\nเราเคารพงานของเจ้า และคาดหวังให้เจ้าเคารพงานของเราด้วย" },
        progress = { "76:2111768976:1511603541", "อย่างน้อยเจ้าควรลองเชดดาร์บ่มนี่สักหน่อย กินแล้วจะหยุดไม่ได้เลย" },
        steps = { { "28:259297340:120381143", "ส่ง Gatehouse Shipment" } },
    },
    [97234] = { -- Reading Room
        title = { "12:2024515930:1603114339", "ห้องอ่านหนังสือ" },
        objective = { "60:989755620:1318245511", "นำหนังสือที่ห่อไว้ไปยังห้องสมุด Stormwind" },
        description = { "415:1804207682:981252654", "เจ้ามาคุยเรื่องความหมายลึกซึ้งของตำนานอันเลื่องชื่อของเราหรือ? ไม่ใช่หรือ?\n\nถ้าอย่างนั้น พอดูรอบ ๆ เสร็จ ช่วยขนสิ่งนี้ไปห้องสมุดให้ข้าได้ไหม? เราจะแลกงานเขียนที่ไม่ค่อยมีคนอ่านบางส่วนกับงานสมัยใหม่ ข้ามีรายชื่อตำราที่มั่นใจว่าบรรณารักษ์จัดหาให้ได้ตามข้อตกลงเดิม\n\nถ้าช่วยเรา ก็มีเครื่องดื่มและของว่างจากชมรมให้ฟรี" },
        progress = { "28:462802630:877403129", "โปรดเบาเสียงด้วย" },
        completion = { "321:2139920431:1969651717", "ขอดูหน่อย ชมรมหนังสือของ Roy ใช่ไหม? ข้าจำวิธีห่อแบบนี้ได้\n\nถ้าเขาบอกว่านี่คือสิ่งที่ผู้คนอยากคุยกัน ข้าก็ไม่มีปัญหา หนังสือที่ได้คืนมามีสภาพดีเท่าตอนให้ยืมเสมอ เราจึงรู้ว่าพวกเขาดูแลอย่างเคารพ ไม่ว่าถ้อยคำข้างในจะชวนถกเถียงเพียงใด" },
        required = { [277158] = { "24:1095074617:1685645706", "เอกสารสำหรับอ่านที่ห่อไว้" } },
        steps = { { "24:1095074617:1685645706", "เอกสารสำหรับอ่านที่ห่อไว้" } },
    },
    [97237] = { -- Shelf Picked
        title = { "12:1886334519:980872835", "เลือกจากชั้น" },
        objective = { "119:879651630:1228758276", "หาหนังสือแต่ละรายการที่อยู่ในห้องสมุด แล้วกลับไปหา Roy Lewells ที่ Park ของ Stormwind" },
        description = { "487:1182372204:1027969103 N 1:46:46", "ข้าตรวจคลังแล้ว หนังสือทุกรายการที่คุณ Lewells ขอมีอยู่ในตอนนี้\n\nแต่เจ้าต้องไปหยิบจากชั้นเอง หน้าที่บรรณารักษ์ส่วนหนึ่งคือคอยดูแลให้ทั่วถึง ข้าจึงจะกลับไปตรวจบัญชีหนังสือต่อ\n\nการนำหนังสือกลับไปให้ Roy แทนเขาไม่ได้ทำให้เจ้าต้องรับผิดชอบการคืน เพราะตามข้อความของเขา เจ้าทำหน้าที่ผู้ส่งสารอย่างเป็นทางการของชมรมหนังสือ สถานประกอบการของพวกเขาจะรับผิดชอบเรื่องนั้นเอง\n\nขอให้เป็นวันที่ดี {name}" },
        progress = { "95:1459921462:756929565", "ลืมว่าต้องทำอะไรตั้งแต่ก้าวพ้นประตูเลยหรือ? ใคร ๆ ก็เป็นกัน" },
        completion = { { "256:2071694474:2008206942", "194:1225453182:1402261068 N 56:216060525:664327261", "194:1225453182:1402261068 C 56:216060525:664327261", "194:1225453182:1402261068 R 56:216060525:664327261" }, "ใช่พวกนี้เลย! บางเล่มถึงกับมีกลิ่นแปลกถิ่น! วิเศษ ข้าอยากให้เราได้คุยเรื่องงานเขียนเหล่านี้อย่างออกรสเร็ว ๆ\n\nแน่นอนว่าในห้องใต้ดิน หลังเวลาทำการ\n\nขอบใจที่วิ่งธุระให้รวดเร็วสหาย ตามสัญญา ทางเราเลี้ยงเอง ที่นี่รักษาคำพูด" },
        required = { [277196] = { "31:808525921:172785634", "บันทึกภาคสนามว่าด้วยการทำลายล้างของ Horde" }, [277194] = { "19:507633934:504321087", "ชัยชนะของ Trollbane" }, [277195] = { "17:1555134515:667452234", "พันธมิตรผู้ถูกทอดทิ้ง" }, [277197] = { "18:486798537:1279082210", "วัฏจักรแห่งศีลธรรม" } },
        steps = { { "31:808525921:172785634", "บันทึกภาคสนามว่าด้วยการทำลายล้างของ Horde" }, { "19:507633934:504321087", "ชัยชนะของ Trollbane" }, { "17:1555134515:667452234", "พันธมิตรผู้ถูกทอดทิ้ง" }, { "18:486798537:1279082210", "วัฏจักรแห่งศีลธรรม" } },
    },
    [97914] = { -- Expanding Horizons
        title = { "18:945349116:511573481", "เปิดขอบฟ้าใหม่" },
        objective = { "118:1522448539:1072473227", "นำ Thundris' Letter ไปให้ Baros Alexston ที่ Stormwind\n\nThundris พูดถึงเรือที่ Auberdine ซึ่งพาเจ้าไปที่นั่นได้" },
        description = { "29:1724409029:1751833195 C 471:806782343:1004608608", "Auberdine เป็นสถานที่เล็ก ๆ ธรรมดา {class} เจ้าไม่ได้ยินชื่อมันตามกิ่งก้านแห่ง Darnassus หรอก ส่วนใหญ่เอ่ยถึงแต่สิ่งที่มหาวิบัติแยกแผ่นดินพรากไป นครรุ่งเรืองอย่าง Ameth'Aran, Bashal'Aran และ... Lathar'Lazal\n\nแต่ Auberdine ยังอยู่ใต้เงาของนครเหล่านั้น\n\nข้าอยากให้งานของเราที่นี่ได้รับการยอมรับ เรือใหม่เชื่อมเรากับอาณาจักร Stormwind นำชีวิตและเสบียงมายังชายฝั่ง ข้าขอร้องให้เจ้าร่วมเดินทางเที่ยวถัดไป แล้วนำจดหมายนี้ไปให้มนุษย์ชื่อ Baros Alexston\n\nทำให้บ้านของเราเป็นที่รู้จักเถอะ", variants = { { "29:1724409029:1751833195 C 471:975994428:764941166", "Auberdine เป็นสถานที่เล็ก ๆ ธรรมดา {class} เจ้าไม่ได้ยินชื่อมันตามกิ่งก้านแห่ง Darnassus หรอก ส่วนใหญ่เอ่ยถึงแต่สิ่งที่มหาวิบัติแยกแผ่นดินพรากไป นครรุ่งเรืองอย่าง Ameth'Aran, Bashal'Aran และ... Lathar'Lazal\n\nแต่ Auberdine ยังอยู่ใต้เงาของนครเหล่านั้น\n\nข้าอยากให้งานของเราที่นี่ได้รับการยอมรับ เรือใหม่เชื่อมเรากับอาณาจักร Stormwind นำชีวิตและเสบียงมายังชายฝั่ง ข้าขอร้องให้เจ้าร่วมเดินทางเที่ยวถัดไป แล้วนำจดหมายนี้ไปให้มนุษย์ชื่อ Baros Alexston\n\nทำให้บ้านของเราเป็นที่รู้จักเถอะ" } } },
        completion = { "63:875635450:1462183031", "Baros เปิดจดหมายแล้วเริ่มอ่าน รอยยิ้มของเขาค่อย ๆ เลือนหาย", variants = { { "65:1975491609:1619099533", "<Baros เปิดจดหมายแล้วเริ่มอ่าน รอยยิ้มของเขาค่อย ๆ เลือนหาย>" } } },
        progress = { "81:1099500533:146310539", "ข้าได้กลิ่นทะเลติดตัวเจ้ามาด้วยนะ สหาย!\n\n<Baros หัวเราะ>\n\nเจ้ามาที่ Stormwind ด้วยธุระอะไร?" },
        required = { [279045] = { "16:1112384972:1005121080", "จดหมายของ Thundris" } },
        steps = { { "16:1112384972:1005121080", "จดหมายของ Thundris" } },
    },
    [98190] = { -- A Friend of the Family
        title = { "22:1427352399:2146456106", "มิตรของครอบครัว" },
        objective = { "76:227158047:1518258841", "นำ Menethil Statuette ไปให้ Highlord Bolvar Fordragon ที่ Stormwind Keep" },
        description = { { "483:137573836:789523077", "484:579639520:1300699378" }, "เจ้าควรรีบนำสิ่งนี้ไป Stormwind แม้ข้าภูมิใจที่ปราสาทและท่าเรือนี้ใช้พระนาม King Terenas Menethil II แต่เราก็เป็นเพียงท่าเรือสงบท่ามกลางพายุศัตรูร้ายกาจ ที่นี่ไม่ปลอดภัย\n\nโดยเฉพาะ Dragonmaw พวกมันคงยอมเสียมากมายเพื่อปล้นสิ่งแบบนี้... และข้าขนลุกเมื่อคิดว่ามันจะเอาไปทำอะไร\n\nเรื่องนี้ไม่ต้องเสียเวลาไล่ตามสายบังคับบัญชา สหาย นำไปหา Highlord Fordragon โดยตรง เขาจะรู้ว่าควรเก็บไว้ที่ไหนจึงดีที่สุด" },
        progress = { "14:1018027912:369264215 C 46:1908072134:944511283", "มาคุยกันเถิด {class} ข้าสัมผัสได้ว่าเจ้าพกบางสิ่งที่มีพลังแห่งแสงศักดิ์สิทธิ์" },
        completion = { "94:204012709:134894472", "ข้าขอบใจที่เจ้าชิงสิ่งนี้คืนมาได้ โล่งใจจริง ๆ ที่มันไม่ตกไปอยู่ในมือคนผิด" },
        required = { [279595] = { "18:1305917549:656121578", "รูปปั้นเล็ก Menethil" } },
        steps = { { "18:1305917549:656121578", "รูปปั้นเล็ก Menethil" } },
    },
    [98191] = { -- A Friend of the Family
        title = { "22:1427352399:2146456106", "มิตรของครอบครัว" },
        objective = { "85:1786268225:1038849898", "นำ Menethil Statuette ไปให้ Lord Grayson Shadowbreaker ที่ Cathedral of Light" },
        description = { "459:440812681:1963196566", "King Terenas ทรงเป็นคนดี ศรัทธาอย่างแรงกล้า เป็นที่รักของประชาชน และเป็นเหตุผลแท้จริงที่เรามี Alliance นี้\n\nน่าขันที่พระองค์ทรงถ่อมตน ไม่ชอบอนุสรณ์แบบนี้ จึงมีเหลืออยู่น้อยมาก และในจำนวนนั้น มีไม่กี่ชิ้นที่รอดจากการล่มสลายของ Lordaeron\n\nดูเหมือนแสงสว่างจะรวมตัวอยู่ในรูปปั้นเล็กนี้ ควรเก็บไว้ที่ Cathedral of the Light ใน Cathedral Square กลางเมือง นำไปให้ Lord Grayson Shadowbreaker ดูแลเถอะ" },
        completion = { "456:568044187:540875355 C 18:425845985:866662706", "พระแสงช่วย... มันเหมือนลูกชายเขาไม่มีผิด...\n\n<Lord Grayson Shadowbreaker หยุดนิ่งครู่หนึ่ง>\n\nรูปสลักนี้ได้รับพรจริง ๆ ทั้งความเชื่อมโยงกับ Terenas และการที่มันยังอยู่หลังจากสิ่งที่เจ้าปีศาจนั่นทำกับเขา มันเปี่ยมด้วยพลังสำหรับผู้ที่เชื่อในพลังของมัน\n\nตอนนี้เก็บไว้ที่นี่ภายใต้การดูแลของภาคีพาลาดินดีที่สุด เราจะใคร่ครวญต่อเพื่อทำความเข้าใจพรของมัน และบางทีมันอาจช่วยเราได้ในยามมืดมนข้างหน้า\n\nขอบใจ {class} ขอพระแสงอวยพรเจ้า" },
        progress = { "19:1039919833:844026077 C 54:1868960419:1353610369", "ขอแสงสถิตกับเจ้า {class} ดูท่าเจ้าคงไม่ได้มาเพื่อคุยเล่น มีเรื่องอะไรรึ?" },
        required = { [279598] = { "18:1305917549:656121578", "รูปปั้นเล็ก Menethil" } },
        steps = { { "18:1305917549:656121578", "รูปปั้นเล็ก Menethil" } },
    },
    [98219] = { -- The Shamed Lieutenant
        title = { "21:1382026202:1314840998", "ร้อยโทผู้เสียเกียรติ" },
        objective = { "73:1146667689:855123609", "คุยกับ Lieutenant Farren Orinelle ที่ Southshore ใน Hillsbrad Foothills" },
        description = { "53:2079749079:1981437814 N 440:49883625:316171677", "ขอบใจอีกครั้งที่ส่งรูปปั้นเล็กมาอย่างปลอดภัย {name}\n\nข้ามีอีกเรื่องอยากให้ช่วย มียามของเมืองคนหนึ่งถูกย้ายไปประจำการที่ Southshore ใน Hillsbrad Foothills\n\nพ่อของเขาเป็นเพื่อนข้า แม้ข้าเห็นด้วยว่าเขาควรได้รับบทเรียน... แต่ก็ยังอยากเห็นเขาประสบความสำเร็จ การมีคนอย่างเจ้าช่วยจะเป็นประโยชน์กับเขามาก\n\nหากเจ้ากลับผ่าน Menethil Harbor มีเรือพาไปทางนั้นได้" },
        completion = { "89:1879487773:434125379", "อา แน่นอน คนฝีมือเยี่ยมของ Stormwind มาเช็กข้าอีกคน เหมือนเดือนที่แล้วเลย!" },
    },
    [5049] = { -- The Jeremiah Blues
        title = { "18:403509229:458723550", "ความเศร้าของ Jeremiah" },
        objective = { "156:1854495774:540299369", "ตามหา Jeremiah Payson ใน Undercity แล้วดูว่าเขาคือ Jeremiah Felstone จริงหรือไม่ หากใช่ เขาอาจอยากได้ห่อของที่ Janice Felstone ทำไว้ให้" },
        description = { "296:402090435:1167013200 C 194:1738971146:811388420", "จากหลักฐานเท่าที่ข้ารวบรวมได้ คนที่เจ้าตามหาและเป็นผู้รับห่อของคือ Jeremiah Payson คนขายแมลงสาบแห่ง Undercity\n\nข้าคิดเสมอว่าการขาย... แมลงสาบ ต้องอาศัยพรสวรรค์พิเศษ ตอนนี้เจ้าคงกำลังเดินทางครั้งยิ่งใหญ่จริง ๆ {class}ผู้ทรงพลัง ข้าจะปล่อยให้เจ้าทำภารกิจพลิกโลกต่อไป แต่ขอมีส่วนในผลงานชิ้นเอกของเจ้าด้วยการบอกว่าเขาอยู่ใกล้ธนาคาร หมอบอยู่ใต้ทางเดินแห่งหนึ่งอย่างเหมาะเจาะ" },
        progress = { "73:1944293351:290479577", "ทุกครั้งที่มีคนเหยียบแมลงสาบ ข้าจะร้องไห้ โปรดอย่าทำให้ข้าร้องไห้" },
        completion = { "437:248908900:771676496", "ข้าไม่ได้ใช้ชื่อนั้นมาหลายปีแล้ว... แต่ใช่ ครั้งหนึ่งในชีวิต ก่อนการดำรงอยู่อันรุ่งโรจน์ในร่างอันเดด นั่นเคยเป็นนามสกุลข้า\n\nเจ้าอ้างว่าเคยรู้จักพี่น้องของข้า... หรือพูดให้ถูก เพิ่งคุยกับนางมา\n\nทั้งที่นางตายแล้ว\n\nมาสี่ปี\n\nรู้ไหม หากกระดูกข้าไม่เปราะอยู่แล้ว ข้าคงอยากเตะก้นเจ้าจนเท้าหักคา เจ้ามันอีแร้งจริง ๆ ใช่ไหม?\n\nอะไรนะ... เจ้าถือห่อของจากพี่น้องข้ามาให้หรือ?" },
    },
    [7783] = { -- The Lord of Blackrock
        title = { "21:1231827177:1988961878", "จอมแห่ง Blackrock" },
        objective = { "51:1759631453:24512923", "นำ Head of Nefarian ไปให้ Thrall ที่ Orgrimmar" },
        description = { "191:516842344:1172066616", "ความรู้สึกเก่าหวนคืน ความปลาบปลื้มแห่งชัยชนะที่เฝ้ารอก้องกังวานไปทั่วกายใจ เบื้องหน้าเจ้าคือศีรษะมหึมาของ Nefarian ที่เต็มไปด้วยรอยแผลจากศึก นำไปให้ประมุขศึกของเจ้า ยอดนักรบเอ๋ย" },
        progress = { "109:175684305:150137579 N 1:46:46", "ข้าอยากอยู่ด้วยเพื่อเห็นสีหน้าอสูรร้ายนั่น ตอนเจ้าลงมือปลิดชีพ {name}" },
        completion = { "38:3592806:1770008205 N 61:750202412:1834759506", "เจ้าสร้างเกียรติแก่ Horde อีกครั้ง {name} บุตรของ Deathwing ตายแล้ว แน่นอนว่าเจ้าตัวร้ายคงเริ่มเคลื่อนไหว" },
    },
    [7784] = { -- The Lord of Blackrock
        title = { "21:1231827177:1988961878", "จอมแห่ง Blackrock" },
        objective = { "100:406099965:1626952949", "คุยกับ High Overlord Saurfang ที่ Orgrimmar เขายืนรออยู่ใน Valley of Strength" },
        description = { "58:2003617101:1309701464", "ตามหา High Overlord Saurfang ที่ Valley of Strength" },
        completion = { "76:2116478607:525482501", "เลือกรางวัล เพื่อข้าจะได้นำศีรษะอสูรร้ายขึ้นแสดงให้ทุกคนเห็น" },
    },
    [95350] = { -- Welcome to Azeroth
        title = { "18:1918171245:194063416", "ยินดีต้อนรับสู่ Azeroth" },
        objective = { "66:1789475990:201516115", "เดินทางไป Orgrimmar แล้วคุยกับ Thrall ที่ Valley of Wisdom" },
        description = { "474:1439719351:1856105117 N 1:46:46", "โลกเบื้องล่างกว้างใหญ่นัก และพันธมิตรใหม่คือกุญแจสู่การอยู่รอดของเรา\n\nEarthen Ring เป็นสมาชิกของ \"Horde\" กลุ่มชนชาติที่มีแนวคิดร่วมกันและภาคภูมิใจ Thunder Bluff เมืองใกล้เคียงเป็นส่วนหนึ่งของ Horde และไกลออกไปทางตะวันออกคือนครหลวง Orgrimmar\n\nไปหาผู้ดูแลเส้นบินกลาง Thunder Bluff เขาจะพาบินไป Orgrimmar ให้เจ้าติดต่อ Thrall ประมุขศึก Horde ในนาม Windshapers ขอสายลมนำทาง {name}", variants = { { "473:136901702:1712242850 N 1:46:46", "โลกเบื้องล่างกว้างใหญ่นัก และพันธมิตรใหม่คือกุญแจสู่การอยู่รอดของเรา\n\nEarthen Ring เป็นสมาชิกของ \"Horde\" กลุ่มชนชาติที่มีแนวคิดร่วมกันและภาคภูมิใจ Thunder Bluff เมืองใกล้เคียงเป็นส่วนหนึ่งของ Horde และไกลออกไปทางตะวันออกคือนครหลวง Orgrimmar\n\nไปหาผู้ดูแลเส้นบินกลาง Thunder Bluff เขาจะพาบินไป Orgrimmar ให้เจ้าติดต่อ Thrall ประมุขศึก Horde ในนาม Windshapers ขอสายลมนำทาง {name}" } } },
        completion = { "361:771698654:431622779", "Lok-tar นักผจญภัย ข้าคือ Thrall ประมุขศึกแห่ง Horde\n\nผู้ส่งสาร Earthen Ring บอกให้ข้าเตรียมต้อนรับสมาชิก Windshapers แล้วเจ้าก็มาถึง ข้าไม่คาดว่าจะเห็นไฮเอลฟ์ยืนตรงหน้าใน Orgrimmar แต่ Horde ก็ยินดีต้อนรับเจ้าเป็นแขกเช่นกัน\n\nข้าอนุญาตให้เดินทางในดินแดน Horde จงไปอย่างมีเกียรติ Windshaper", variants = { { "9:1871511191:798375331 C 342:1797176066:2105497970", "Lok-tar {class} ข้าคือ Thrall ประมุขศึกแห่ง Horde\n\nผู้ส่งสาร Earthen Ring บอกให้ข้าเตรียมต้อนรับสมาชิก Windshapers แล้วเจ้าก็มาถึง ข้าไม่คาดว่าจะเห็นไฮเอลฟ์ยืนตรงหน้าใน Orgrimmar แต่ Horde ก็ยินดีต้อนรับเจ้าเป็นแขกเช่นกัน\n\nข้าอนุญาตให้เดินทางในดินแดน Horde จงไปอย่างมีเกียรติ Windshaper" }, { "9:1871511191:798375331 C 348:1106407234:1869184668", "Lok-tar {class} ข้าคือ Thrall ประมุขศึกแห่ง Horde\n\nผู้ส่งสารจาก Earthen Ring แจ้งว่าจะมีทูตจาก Windshapers มาพบ และตอนนี้เจ้าก็มาถึงแล้ว ข้าไม่เคยคิดว่าจะได้เห็นไฮเอลฟ์มายืนต่อหน้าข้าใน Orgrimmar แต่ Horde ยินดีต้อนรับเจ้าเป็นแขก\n\nข้าอนุญาตให้เจ้าเดินทางในดินแดนของ Horde จงไปอย่างมีเกียรติ Windshaper" }, { "9:1871511191:798375331 C 342:1026627164:61445275", "Lok-tar {class} ข้าคือ Thrall ประมุขศึกแห่ง Horde\n\nผู้ส่งสาร Earthen Ring บอกให้ข้าเตรียมต้อนรับสมาชิก Windshapers แล้วเจ้าก็มาถึง ข้าไม่คาดว่าจะเห็นไฮเอลฟ์ยืนตรงหน้าใน Orgrimmar แต่ Horde ก็ยินดีต้อนรับเจ้าเป็นแขกเช่นกัน\n\nข้าอนุญาตให้เดินทางในดินแดน Horde จงไปอย่างมีเกียรติ Windshaper" } } },
    },
    [637] = { -- Sully Balloo's Letter
        title = { "21:170899978:894698585", "จดหมายของ Sully Balloo" },
        objective = { "45:393663861:1553428656", "นำ Sully Balloo's Letter ไปส่งให้ Sara Balloo" },
        description = { "239:131657096:1754254791", "ซองจดหมายที่ชุ่มน้ำและฉีกขาดจากสงครามเปื่อยสลายในมือเจ้า เหลือกระดาษจดหมายไม่กี่หน้าที่เขียนอย่างประณีตบรรจง\n\nจดหมายจ่าหน้าถึงคุณนาย Sara Balloo แห่ง Ironforge และเริ่มว่า \"Sara ที่รักของข้า...\"" },
        progress = { "90:1895365307:1052201278 C 82:23261661:1543049681", "เจ้าดูเหมือนเดินทางมาไกลและพบความวุ่นวายมากมาย {class} ยุคสมัยที่เราอยู่ช่างทดสอบจิตใจ วันนี้นำข่าวอะไรมาให้ข้าหรือ?" },
        completion = { "102:119354686:831789030", "เจ้าว่าเห็น Sully ของข้าติดอยู่ใต้น้ำเย็นจัดหรือ? บอกทีว่าไม่จริง!\n\nขอข้าอ่านสิ่งที่เขาเขียนก่อน..." },
        required = { [4432] = { "21:170899978:894698585", "จดหมายของ Sully Balloo" } },
        steps = { { "21:170899978:894698585", "จดหมายของ Sully Balloo" } },
    },
    [683] = { -- Sara Balloo's Plea
        title = { "18:794006572:1060990051", "คำวิงวอนของ Sara Balloo" },
        objective = { "63:33206162:972345677", "นำข้อความของ Sara Balloo ไปให้ King Magni Bronzebeard แห่ง Ironforge" },
        description = { "N 374:497328026:1217274859", "{name} ข้ามีคำขอเล็กน้อย\n\nนำข้อความที่ข้าเตรียมไว้นี้ไปให้ King Magni Bronzebeard กษัตริย์ผู้ยิ่งใหญ่แห่ง Ironforge ของเรา เป็นงานเล็กน้อยสำหรับคนเช่นเจ้า ผู้แสดงความกล้าหาญเพื่อ Alliance มามากแล้ว\n\nหากข้าไปเข้าเฝ้าในสภาพเศร้าโศกเช่นนี้ คงไม่ช่วยให้สิ่งที่ข้าต้องการสำเร็จ เจ้าคงเข้าใจ" },
        progress = { "11:321922253:1585025312 N 5:1988563650:1096639519 C 124:865328553:983352692", "เจ้าคือ {name} ผู้เป็น{class}สินะ? ข่าวความดีความชอบที่เจ้าทำเพื่อ Alliance เลื่องลือไปไกลทีเดียว รู้หรือไม่?\n\nวันนี้มีธุระอะไรจึงมาเข้าเฝ้าข้า?" },
        completion = { "57:2113156072:1255362533", "ขอเวลาข้าอ่านจดหมายนี้สักครู่..." },
        required = { [4514] = { "18:794006572:1060990051", "คำวิงวอนของ Sara Balloo" } },
        steps = { { "18:794006572:1060990051", "คำวิงวอนของ Sara Balloo" } },
    },
    [686] = { -- A King's Tribute
        title = { "16:233136637:1720947250", "การสดุดีจากกษัตริย์" },
        objective = { "70:53308605:679699480", "King Magni Bronzebeard ต้องการให้เจ้าคุยกับ Grand Mason Marblesten" },
        description = { "459:793212292:1964862305 C 39:1619931843:60760805", "ข้าไม่ได้คาดหวังให้ชาวดวอร์ฟที่ดีอย่างคุณนาย Balloo เข้าใจว่าเหตุใดเราจึงต้องอดทนต่อความอยุติธรรมของสงครามเพื่อประโยชน์ส่วนรวม การสูญเสียสามีของนาง และดวอร์ฟทุกคนที่รบในนาม Alliance หนักอึ้งในใจข้า\n\nแม้ข้าไม่อาจนำสามีนางกลับจาก Twisting Nether ได้ แต่ข้าสดุดีเขาได้\n\nข้าจะว่าจ้าง Grand Mason Mablesten ให้สร้างอนุสรณ์แก่ Sully Balloo\n\nจงนำคำสั่งไปแจ้งเขาเดี๋ยวนี้ {class} เจ้าจะเป็นผู้ดูแลงานตามประสงค์ของข้า" },
        completion = { "74:1716316863:769787168", "King Magni Bronzebeard ทรงส่งเจ้ามาด้วยพระองค์เองหรือ?\n\nโอ้โฮ! ต้องเป็นเรื่องสำคัญแน่!" },
    },
    [689] = { -- A King's Tribute
        title = { "16:233136637:1720947250", "การสดุดีจากกษัตริย์" },
        objective = { "70:449936221:1297160236", "Grand Mason Marblesten แห่ง Ironforge ต้องการ Alterac Granite 5 ชิ้น" },
        description = { "430:300884703:836900461", "กษัตริย์ผู้ทรงคุณธรรมของเราอยากให้สร้างอนุสรณ์สดุดีทหารชื่อ Sully Balloo หรือ? และเจ้าว่าชายผู้น่าสงสารตายในโศกนาฏกรรมที่ Thandol Span?\n\nเฮ้อ Azeroth จะมีสันติภาพบ้างไหมนะ?\n\nอย่างไรก็ตาม งานจากกษัตริย์สำคัญที่สุดเสมอ ถ้าจะสร้างผลงานยิ่งใหญ่และยั่งยืน ข้าอยากใช้หินชั้นเลิศ ไปที่ Darrow Hill ใน Hillsbrad แล้วเก็บ Alterac Granite มาให้ข้า" },
        progress = { "N 2:11340:5796 N 2:11340:5796 N 98:706297296:1603126832", "{name}, {name}, {name}! บอกทีว่ามี Alterac Granite มากพอให้ข้าเริ่มผลงานชิ้นเอกสดุดี Sully Balloo แล้ว" },
        completion = { "87:907576474:1025912278", "สมบูรณ์แบบ! ดีกว่าที่ข้าจินตนาการเสียอีก!\n\nและข้าก็เป็นคนจินตนาการกว้างไกลเชียวนะ..." },
        required = { [4521] = { "15:951949323:2051174527", "หินแกรนิต Alterac" } },
        objectiveLabels = {
            item = { ["Alterac Granite"] = "หินแกรนิต Alterac" },
        },
    },
    [700] = { -- A King's Tribute
        title = { "16:233136637:1720947250", "การสดุดีจากกษัตริย์" },
        objective = { "33:1739278056:1219649305", "รายงานต่อ King Magni Bronzebeard" },
        description = { "269:1337926800:837836176", "อา หินชั้นดีเช่นนี้มาจาก Lordaeron น่าเสียดายที่ดินแดนนั้นยับเยินเหลือเกิน\n\nแต่อนุสรณ์ออกมาดีทีเดียว! ข้าคิดว่ากษัตริย์คงทรงพอพระทัยมาก\n\nหากช่วยได้ โปรดนำข่าวไปทูลว่าพระอนุสรณ์สร้างเสร็จตามพระประสงค์แล้ว" },
        completion = { "340:37437454:1895476026", "หินแกรนิตดูเป็นเพียงสิ่งเล็กน้อยเมื่อเทียบกับชีวิตของดวอร์ฟผู้ยิ่งใหญ่ แต่ไม่มีดวอร์ฟคนใดอยู่บนโลกนี้ได้ชั่วนิรันดร์\n\nหวังว่าอนุสรณ์จะยืนยงเตือนใจผู้ที่เดินบน Azeroth อันยิ่งใหญ่ในอนาคต เพื่อมิให้ลืมว่าทหารผู้กล้าอย่าง Sully Balloo ยอมสละชีวิตอย่างองอาจเพื่อพวกเขา" },
    },
    [707] = { -- Ironband Wants You!
        title = { "19:72084711:2131372065", "Ironband ต้องการเจ้า!" },
        objective = { "75:391040297:2123220411", "คุยกับ Prospector Ironband ที่ Ironband's Excavation Site ใน Loch Modan" },
        description = { "N 252:1507849057:838747099", "{name} ข้าได้รับรายงานจาก Prospector Ironband ณ จุดขุดค้นของเขาใน Loch Modan เขาต้องการคนช่วยเดินเรื่องเกี่ยวกับจุดขุดค้นอีกแห่งของเรา\n\nข้าไม่มีรายละเอียดมากกว่านั้น แต่ถ้าอยากยืดแข้งยืดขาก็ไปคุยกับ Ironband เถอะ" },
        completion = { "65:1174831104:1291449498", "Stormpike ส่งเจ้ามาสินะ? ดี\n\nข้ามีงานใหญ่ให้ทำ..." },
    },
    [2041] = { -- Speak with Shoni
        title = { "16:37618189:1868145409", "คุยกับ Shoni" },
        objective = { "42:867808766:1808459621", "คุยกับ Shoni the Shilent ที่ Stormwind" },
        description = { "294:1347779736:291123000 N 1:46:46", "บางที... บางทีเจ้าช่วยเราในการรบเพื่อ Gnomeregan ได้\n\nใน Stormwind เจ้าจะพบ Shoni the Shilent ผู้บัญชาการหน่วยจู่โจมใต้ดินของเรา Shoni ต้องการความช่วยเหลือเกี่ยวกับเครื่องขุด gyrodrillmatic excavationators ของนาง\n\nน่าจะพบนางอยู่ท่ามกลางพวกดวอร์ฟใน Stormwind\n\nโชคดี {name}" },
        completion = { "39:165793493:205975323", "นำข่าวจากกองบัญชาการกลางมาหรือ?" },
    },
    [2946] = { -- Seeing What Happens
        title = { "19:1699849438:36816056", "ดูว่าจะเกิดอะไรขึ้น" },
        objective = { "124:1495573508:969337110", "นำ miniature platinum discs ไปยังประตู Uldum ใน Tanaris แล้วหาเบาะแสความเชื่อมโยงระหว่างทั้งสองสิ่ง" },
        description = { "492:737077082:187105594", "เราอยากให้เจ้านำแผ่นดิสก์ขนาดเล็กที่พบไปยังประตู Uldum ที่ปิดผนึก เรา... ไม่แน่ใจว่าจะเกิดอะไรขึ้น\n\nฟังดูเสี่ยง เรารู้ แต่ก็อาจไม่เกิดอะไรเลย เจ้าอาจต้องใช้แผ่นดิสก์กับบางสิ่ง หรือประตูอาจปลดล็อกเมื่อเจ้ามีแผ่นดิสก์ติดตัว เปิดใจลองทุกอย่าง และเตรียมพร้อมกับทุกสิ่งที่อาจเกิดขึ้น\n\nเมื่อรู้ว่าเกิดอะไรขึ้นแล้ว กลับ Ironforge เราคงมีเรื่องให้วิเคราะห์มากมาย!" },
        progress = { "109:1149819445:626612892", "แท่นที่ดูคุ้นตานี้โผล่พ้นทรายร้อน บางทีการที่มันอยู่ที่นี่อาจมีความหมาย..." },
        completion = { "468:268243397:1261346036", "เมื่อเจ้าแตะแท่น แผ่นดิสก์ขนาดเล็กจาก Uldaman ส่งเสียงครางและเรืองแสงในเป้ ความรู้สึกซ่าที่คุ้นเคยแล่นผ่านมือ ขณะภาพของ Stone Watcher อีกตนปรากฏขึ้นหน้าประตู Uldum\n\n\"สวัสดี ข้าคือผู้พิทักษ์ทางเข้า ชุดแผ่นดิสก์ที่ใช้ขอผ่านยังขาดแผ่นสำหรับเข้าใช้งานที่ถูกต้อง นั่นคือ Plates of Uldum โปรดรวมแผ่นดังกล่าวเข้ากับโครงสร้างแผ่นดิสก์ แล้วทำลำดับการขอผ่านซ้ำ ขอบคุณ\"" },
        required = { [6064] = { "24:500077704:355707172", "แผ่นแพลทินัมขนาดย่อม" } },
        steps = { { "24:500077704:355707172", "แผ่นแพลทินัมขนาดย่อม" } },
    },
    [2948] = { -- Gnome Improvement
        title = { "17:631287838:1826085506", "ฝีมือพัฒนาของโนม" },
        objective = { "114:39460613:1577197788", "นำ Brilliant Gold Ring, Silver Bar, Moss Agate และเหรียญเงิน 30 เหรียญ ไปให้ Talvash del Kissel ที่ Ironforge" },
        description = { "7:1470474127:1087134216 N 470:1219188281:447734360", "ฟังนะ {name} แหวนเป็นของเจ้า แน่นอน... แต่ข้าทำให้ดีกว่านี้ได้! อย่างที่บอก แบบนี้ง่ายมาก ตอนนี้ข้าฝีมือดีกว่าเดิมมาก แค่จ่ายสามสิบเหรียญเงิน ข้าจะปรับให้สวยขึ้น! เอ่อ จริง ๆ ก็มากกว่าสามสิบนิดหน่อย...\n\nตอนนี้ข้าลำบาก วัตถุดิบหมดคลังแล้ว หากนำแท่งเงินกับมอสอะเกตมาให้ ข้าจะเพิ่มลายตาข่ายเงินและอะเกตให้แหวนดูโดดเด่นขึ้น!\n\nเชื่อข้าสิ!" },
        progress = { "92:696082810:827217659", "มีวัตถุดิบที่ข้าต้องการหรือยัง? หากไม่ตกอับจริง ๆ ข้าคงไม่ขอหรอก..." },
        completion = { "348:1259586439:1379460394", "อา ตรงตามที่ต้องการ! สักวัน เมื่อพ้นหลุมที่ข้าต้องมาติดอย่างไม่เป็นธรรมนี้ ข้าจะทำเครื่องประดับที่ดีที่สุดใน Azeroth ให้เจ้า ให้ทุกคนเลย! ระหว่างนี้ขอบใจที่ไม่ถือสาเรื่องวัตถุดิบ ปกติแหวนคุณภาพเช่นนี้ ข้าคิดแพงกว่าที่คิดเจ้าสิบเท่า...\n\nพูดถึงแหวน นี่แหวนวงใหม่ของเจ้า!" },
        required = { [9362] = { "19:876421917:394488771", "แหวนทองคำแวววาว" }, [2842] = { "10:1293727786:854722126", "แท่งเงิน" }, [1206] = { "10:1747381559:30372131", "โมราลายมอส" } },
        steps = { { "19:876421917:394488771", "แหวนทองคำแวววาว" }, { "10:1293727786:854722126", "แท่งเงิน" }, { "10:1747381559:30372131", "โมราลายมอส" } },
    },
    [2963] = { -- Portents of Uldum
        title = { "17:1307916101:666828308", "สัญญาณแห่ง Uldum" },
        objective = { "70:196256650:2065189873", "คุยกับ Historian Karnik ที่ Hall of Explorers ใน Ironforge" },
        description = { "22:940931934:1505085707 N 471:1646808034:2108246756", "สวัสดีอีกครั้ง {name}! สิ่งที่เจ้าค้นพบใน Uldaman ทำให้ Explorers' League ตื่นเต้นกันใหญ่ สมาคมพยายามไขความลับของ miniature platinum discs ที่เจ้าพบอยู่ การที่เจ้ามาถึงหอแห่งนี้พอดี ทำให้ข้าได้บอกว่าเราอาจพบอะไรบางอย่างแล้ว!\n\nHistorian Karnik พบเบาะแสสำคัญเรื่องต้นกำเนิดแท้จริงของ Valley of the Watchers ในทะเลทราย Tanaris เขาอยากคุยกับเจ้าโดยเร็วที่สุด!" },
        completion = { "59:692187073:1249144638 N 381:1072945846:635673902", "ดีใจที่เจ้ายังสนใจการสำรวจ {name}! ด้วยพรสวรรค์และความกล้าของเจ้า เราอาจไขความลับที่ไม่เคยนึกว่าจะเป็นไปได้!\n\nDiscs of Norgannon ใน Uldaman เป็นคลังข้อมูลมหาศาล แต่เจ้าได้รับอนุญาตให้เข้าถึงเพียงชั้นนอกของข้อมูลเท่านั้น มีข่าวลือว่าผู้สร้างมีคลังอื่นกระจายทั่ว Azeroth เรื่องนี้จึงพาเรามาถึง Uldum..." },
    },
    [2964] = { -- A Future Task
        title = { "13:495001730:1713837883", "งานในอนาคต" },
        objective = { "47:1992006795:984287557", "คุยกับ High Explorer Magellas ที่ Ironforge" },
        description = { "5:1151914341:80614338 N 396:1953300039:761588542 N 83:1738527021:187234946", "เอาล่ะ {name}... ดูเหมือนเราจะพบทางตันชั่วคราว เรารู้ว่าต้องการ Plates of Uldum แต่ไม่รู้ว่าอยู่ที่ใด ต้องวิจัยอีกมากจึงจะวางแผนที่แน่นอนได้ ข้ามีแนวคิดอยู่สองสามอย่างว่าจะเริ่มหาที่ไหน และหวังว่าไม่นานเราจะขอให้เจ้าออกไปนำมันกลับมา\n\nต้องแจ้ง High Explorer ให้ทราบ {name} เขาคงอยากขอบใจเจ้าด้วยตัวเองที่ช่วยสมาคมอีกครั้ง" },
        completion = { "177:1509404198:1553409869 N 293:1125582536:128783873", "เราจึงเห็นตรงกัน แผนที่ดีที่สุดคือพักเรื่องนี้ไว้จนจำกัดพื้นที่ที่แผ่นเหล่านั้นอาจซ่อนอยู่ได้ เจ้าพาเรามาไกลถึงเพียงนี้ {name} ข้าหวังว่าเจ้าจะเป็นคนกลับออกภาคสนามไปไขประตู Uldum ให้เราทุกคน!\n\nระหว่างนี้รับค่าตอบแทนนี้เถอะ น่าจะครอบคลุมค่าใช้จ่ายที่เสียไปในการช่วยเรา และมีเพิ่มให้อีกเล็กน้อย อย่าลืมกลับมาถามข่าวเร็ว ๆ นี้... Uldum กำลังเรียกหา!" },
    },
    [2977] = { -- Return to Ironforge
        title = { "19:1303221771:1101574696", "กลับ Ironforge" },
        objective = { "41:1293741991:1116630438", "คุยกับ Historian Karnik ที่ Ironforge" },
        description = { "277:2018468718:415327782", "เจ้าใช้งานแท่นอีกครั้ง จู่ ๆ แผ่นดิสก์แพลทินัมก็ปรากฏในเป้ของเจ้าอีกหน\n\nเมื่อได้รับความรู้จาก Stone Watcher และได้แผ่นดิสก์คืนแล้ว ก็ถึงเวลากลับ Ironforge เพื่อแจ้งสิ่งที่ค้นพบแก่ Explorers' League" },
        progress = { "13:23130796:2039583150 N 94:2087935511:1863966433", "ยินดีต้อนรับกลับ {name} เจ้าใช้แผ่นดิสก์ให้เกิดประโยชน์ได้ไหม หรือกลายเป็นการตามหาที่เสียเปล่า?" },
        completion = { "418:601807171:1531339306", "เจ้าขาดแผ่นดิสก์บางส่วนหรือ? น่าสนใจ ดูเหมือน Discs of Norgannon เป็นเพียงบางส่วนของชุดที่สมบูรณ์ คล้ายกุญแจแต่ละดอกบนพวงนั่นเอง\n\nถ้าหา Plates of Uldum ได้ เราก็จะเข้าไปในกลุ่มอาคาร Uldum จริง ๆ! ลองนึกถึงการสำรวจสถานที่ทำงานของผู้สร้างโดยไม่ต้องแบกพลั่วมหึมาสิ!\n\nไม่ใช่ว่าพลั่ว... หรือการขุด... มีอะไรไม่ดีหรอกนะ" },
        required = { [6064] = { "24:500077704:355707172", "แผ่นแพลทินัมขนาดย่อม" } },
        steps = { { "24:500077704:355707172", "แผ่นแพลทินัมขนาดย่อม" } },
    },
    [3371] = { -- Dwarven Justice
        title = { "15:2088365633:164507625", "ความยุติธรรมของดวอร์ฟ" },
        objective = { "63:560718986:2025176641", "กลับ Searing Gorge แล้วตามหาหน่วยโบราณคดีของ Dorius" },
        description = { "60:1884466854:1121765502 N 243:1825788983:1819422416", "ตรงที่เคยเป็นหัวใจข้าเหลือเพียงช่องว่างเวิ้งว้าง {name} การสูญเสีย Dorius ไม่ใช่เรื่องที่ข้าจะทำใจได้เร็ว ๆ ข้าต้องทำความปรารถนาสุดท้ายของเขาให้สำเร็จ ผู้ก่อเหตุฆาตกรรมเลือดเย็นนี้ต้องได้รับโทษ\n\nกลับ Searing Gorge แล้วทำคำขอสุดท้ายของเขา ปลดปล่อยคนของเขา" },
        completion = { "33:1176292938:495510468", "ไม่ต้องห่วงข้า ไปช่วยคนอื่น" },
    },
    [3448] = { -- Passing the Burden
        title = { "18:1861816380:113466807", "ส่งต่อภาระ" },
        objective = { "28:1899692474:2049342466", "คุยกับ Tymor ที่ Ironforge" },
        description = { "498:163101652:1555886342", "เมื่อไม่นานมานี้ข้าได้รับหน้าที่สำรวจ Azshara ดินแดนที่เคยงดงามและเป็นบ้านของเอลฟ์ สมัยที่พวกเขายังฝึกเวทมนตร์ ตอนนี้อันตรายยิ่งกว่างดงาม แต่ก็หยุดเราไม่ให้พลิกหินทุกก้อนเพื่อหาคำตอบเรื่องอดีตไม่ได้\n\nสหายข้าชื่อ Tymor เสนอตัวช่วยสำรวจ เพราะเขาสนใจเรื่องแบบนี้เป็นพิเศษ\n\nเขามีที่พักเล็ก ๆ อยู่ทางขวาของ Hall of Mysteries ในเมืองนี้" },
        completion = { "501:672799438:1083555625", "อา Karnik ส่งเจ้ามาหรือ? ข้าคาดว่าจะได้ข่าวจากเขาเร็ว ๆ นี้ ข้าค้นพบเรื่องวิเศษเกี่ยวกับ Azshara มากมาย ข้ารู้ว่าไนต์เอลฟ์มีอายุยืนเหลือเชื่อ แต่บางครั้งทุกคนก็ลืมเหตุการณ์ที่... ไม่น่าพอใจ... ในชีวิตได้บ้าง ไม่ได้ตำหนิ แค่ตั้งข้อสังเกต\n\nนานมาแล้ว เอลฟ์สร้างนครที่เต็มไปด้วยความรู้เรื่องเวทมนตร์และศาสตร์ที่สูญหายอื่น ๆ ในฐานะผู้ศึกษาเรื่องนี้ ข้าจึงเริ่มสืบค้น สิ่งที่พบช่างน่าตื่นเต้น" },
    },
    [3449] = { -- Arcane Runes
        title = { "12:282922588:642181995", "อักขระอาร์เคน" },
        objective = { "261:690149501:1770079280", "ใช้ Drawing Kit ถูสำเนา Rune of Beth'Amara, Rune of Jin'yael, Rune of Markri และ Rune of Sael'hai จากนั้นไปเกาะเล็กนอกคาบสมุทรทางใต้ของ Azshara แล้วส่งสัญญาณเรียก Pilot Xiggs Fuselighter มารับสำเนา" },
        description = { "483:148546370:767414515", "ครั้งหนึ่งเอลฟ์บางกลุ่มเคารพเวทมนตร์เทียบเท่า Elune เหล่าจอมเวทผู้ทรงพลังสร้างอักขระและแผ่นจารึกกฎแห่งอาร์เคนกับข้อคิดจากการค้นพบ แล้ววางไว้ในที่สาธารณะให้ทุกคนไตร่ตรอง\n\nข้าอยากได้สำเนาถูของอักขระเหล่านี้จาก Ruins of Eldarath มาก ข้ามีชุดอุปกรณ์ให้ทำสำเนา แต่เจ้าต้องหาอักขระเอง ระวังด้วย Explorers' League ไม่ใช่กลุ่มเดียวที่สนใจ Eldarath" },
        progress = { "52:1940315141:1653085689 N 226:1767582894:1898097127", "โอ้โฮ ดีใจที่เจ้ามาถึงนี่ {name} ได้สำเนาถูให้ Tymor หรือยัง?\n\nแม้ที่นี่อันตราย ก็ยังไม่ค่อยมีเรื่องตามชายฝั่ง อาจเพราะนากาว่ายอยู่ใต้น้ำ แต่นั่นไม่ใช่ปัญหาข้า... ข้าลาดตระเวนบนฟ้า" },
        completion = { "32:1146128802:1988329723 N 242:789537625:1475584355", "ดีใจที่เจ้าปลอดภัย {name} หวังว่าคงไม่ลำบากเกินไป\n\nข้าจะนำของพวกนี้ไปให้ Tymor ทันที เขาคงตื่นเต้นที่จะได้ดู\n\nทิ้งปืนพลุได้เลย... มันคงไม่มีประโยชน์กับเจ้าแล้ว และข้าก็ได้กระบอกใหม่มาแล้ว" },
        required = { [10563] = { "27:13789496:935014714", "สำเนาถูอักษรรูนของ Beth'Amara" }, [10564] = { "25:1620814174:482842605", "สำเนาถูอักษรรูนของ Jin'yael" }, [10565] = { "23:497546399:1790080534", "สำเนาถูอักษรรูนของ Markri" }, [10566] = { "25:1990507777:91609587", "สำเนาถูอักษรรูนของ Sael'hai" } },
        objectiveLabels = {
            item = { ["Rubbing: Rune of Beth'Amara"] = "สำเนาถูอักษรรูนของ Beth'Amara", ["Rubbing: Rune of Jin'yael"] = "สำเนาถูอักษรรูนของ Jin'yael", ["Rubbing: Rune of Markri"] = "สำเนาถูอักษรรูนของ Markri", ["Rubbing: Rune of Sael'hai"] = "สำเนาถูอักษรรูนของ Sael'hai" },
        },
    },
    [3450] = { -- An Easy Pickup
        title = { "14:573472311:25857848", "รับของง่าย ๆ" },
        objective = { "40:842980026:1507958947", "คุยกับ Xiggs Fuselighter ที่ Ironforge" },
        description = { "506:1064681515:1544844978", "ข้าอยากให้ส่งสำเนาถูไปหอคอยของข้า แต่ไม่จำเป็นให้เจ้าเดินไปถึงนั่น ข้าจะให้ขนทางอากาศออกจาก Azshara\n\nXiggs Fuselighter ติดค้างข้าอยู่สองสามเรื่อง และกำลังจะไปแถวนั้น เขารับงานลาดตระเวนชายฝั่งไว้ คุยกับเขาก่อนออกเดินทาง เขาจะให้ปืนพลุไว้ส่งสัญญาณ เมื่อได้สำเนาแล้ว ให้ไปจุดที่เขาบอกและมอบให้เขา เขาจะขนไปหอคอยข้าอย่างปลอดภัย เขาน่าจะอยู่ในโรงเก็บอากาศยานที่ Military Ward" },
        completion = { "23:845437671:750047252 N 336:969627282:1385903667", "ให้ข้าช่วยอะไร {name}? ตอนนี้ยุ่งอยู่หน่อย กำลังเตรียมยานเดินทางไกล แค่มาหาพวกพลขับรถถัง ข้าต้องการขนแผงคอเวนดิโกไว้บุห้องนักบิน และปกติพวกเขามีเหลือ\n\nถ้าพูดสั้น ๆ ข้าพอมีเวลาให้... คนหนึ่งเพิ่งออกไป Steelgrill's Depot เพื่อดูว่าพลขับที่นั่นมีขนแผงคอเหลือให้ข้าหรือไม่" },
    },
    [3451] = { -- Signal for Pickup
        title = { "17:1834788991:311544792", "ส่งสัญญาณรับของ" },
        objective = { "84:1578734424:800024823", "คุยกับ Xiggs Fuselighter แล้วรับ Standard Issue Flare Gun จากเขาที่ Ironforge" },
        description = { "405:1608203438:1322994990", "อา Tymor ส่งเจ้ามาหรือ? ใช่ ข้าติดค้างเขาอยู่สองสามเรื่อง อะไรนะ? เจ้าตัวแสบนั่นเอ๊ย ใช่ ข้าช่วยได้ เจ้าต้องใช้ปืนพลุกับสถานที่... ง่ายพอ\n\nมีเกาะเล็กนอกคาบสมุทรทางใต้ของ Azshara ที่เราสร้างลานจอดไว้ นำปืนพลุนี้ไปใช้ที่นั่น ข้าจะเห็นสัญญาณแล้วบินไปรับ... อะไรก็ตามที่เขาต้องการ" },
        completion = { "260:1173164771:272078143", "นี่ Standard Issue Flare Gun ของข้า ยิงแล้วให้อดทนรอ กระบอกหนึ่งยิงได้แค่สองสามครั้ง ข้าอาจต้องใช้เวลาสักพักไปหาเจ้า ขึ้นอยู่กับว่าอยู่ไกลออกทะเลแค่ไหน ยิงพลุแล้วมองออกไปทางทะเลไว้" },
    },
    [3461] = { -- Return to Tymor
        title = { "15:1606074432:1951959267", "กลับไปหา Tymor" },
        objective = { "47:1903440890:1429854946", "นำ Tymor's Drawing Kit กลับไปคืนเขาที่ Ironforge" },
        description = { "428:2040169725:257430820", "Tymor ไม่ได้ฝากเงินให้ข้าจ่ายเจ้า แนะนำให้ไปคุยกับเขาตอนกลับ Ironforge ข้ามั่นใจว่ายังอยู่ที่พักใน Mystic Ward เคาะประตูแล้วให้แน่ใจว่าเขาจ่ายดี ๆ ที่นี่ไม่ใช่ที่เที่ยวสบายแน่นอน\n\nอย่างไรก็ขอบใจอีกครั้งที่ช่วยเขา และขอให้โชคดี\n\nอ้อ ข้าไม่ต้องใช้ชุดวาด ทำไมเจ้าไม่นำกลับไปคืน Tymor ตอนพบเขาล่ะ?" },
        progress = { "56:14944089:1185127123", "กลับมาแล้ว! ยอดเยี่ยม นำชุดวาดของข้ามาด้วยไหม?" },
        completion = { "341:265940468:3418664", "วิเศษ! ดีใจที่ได้ยินอย่างนั้น\n\nข้าตื่นเต้นที่จะไปหอคอยแล้วศึกษาสำเนาพวกนั้น อิจฉาเจ้าจริง ๆ ได้ไปสถานที่อย่าง Azshara คงเป็นความฝันของผู้ศึกษาอาร์เคนทุกคน\n\nเราไม่เคยคุยเรื่องรางวัล เพราะเจ้าทำงานให้ Explorers' League แต่เจ้าสมควรได้รับบางอย่าง" },
    },
    [3483] = { -- Signal for Pickup
        title = { "17:1834788991:311544792", "ส่งสัญญาณรับของ" },
        completion = { "198:1714812146:1773178010", "อา ต้องการปืนพลุอีกกระบอกหรือ? ข้าจัดให้ได้\n\nอย่าลืม ปลายด้านใต้ของ Azshara มีเกาะเล็กที่ทำเป็นลานจอด หากไปถูกจุดก็ไม่มีทางมองพลาด" },
    },
    [3701] = { -- The Smoldering Ruins of Thaurissan
        title = { "34:25172218:75217966", "ซากคุกรุ่นแห่ง Thaurissan" },
        objective = { "187:653399086:140035547", "ไปที่ Ruins of Thaurissan ใน Burning Steppes แล้วเก็บข้อมูลจาก Thaurissan Relics เมื่อได้ข้อมูลแล้วกลับไปหา Royal Historian Archesonus" },
        description = { "209:376792011:925435113 N 128:2089495267:212806307", "เดินทางไปยังซากคุกรุ่นแห่ง Thaurissan ใน Burning Steppes แล้วรวบรวมข้อมูลให้มากที่สุด\n\nว่ากันว่ามีวัตถุโบราณลึกลับกระจายอยู่ทั่วซากเมือง เจ้าน่าจะเริ่มค้นจากตรงนั้น {name} ระวังผู้พิทักษ์ Thaurissan เหล่านักลอบสังหารที่เฝ้าซากเมือง ปกป้องความลับใดก็ตามที่ยังฝังอยู่" },
        progress = { "29:610537237:705473298", "นำข้อมูลใหม่มาหรือ?" },
        completion = { "91:1668119866:844563657", "โอ้! ข้อมูลนี้อธิบายเรื่อง Thaurissan ได้มากทีเดียว\n\nยังมีเรื่องให้เรียนรู้อีกมาก!" },
        steps = { { "21:1789578924:409990907", "กู้ข้อมูลกลับมา" } },
    },
    [3702] = { -- The Smoldering Ruins of Thaurissan
        title = { "34:25172218:75217966", "ซากคุกรุ่นแห่ง Thaurissan" },
        objective = { "70:1651525371:947778105", "ฟัง Royal Historian Archesonus เล่าประวัติของ Thaurissan" },
        description = { "64:1963284031:426726232", "อยากฟังประวัติย่อของพวกดวอร์ฟ Dark Iron ไหม?" },
        progress = { "55:1438217009:970213045", "ให้ข้าเล่าเรื่อง Thaurissan จบก่อน" },
        completion = { "17:150200574:1178633253", "เราจะไปต่อกันไหม?" },
    },
    [4512] = { -- A Little Slime Goes a Long Way
        title = { "30:1577124892:2049153260", "เมือกนิดเดียวก็ได้เรื่องไกล" },
        objective = { "96:614628320:98777682", "นำ Filled Cursed Ooze Jars 6 ใบ และ Filled Tainted Ooze Jars 6 ใบ ไปให้ Laris Geardawdle ที่ Ironforge" },
        description = { "501:1937132190:1162217199", "แต่สิ่งที่ข้าศึกษามากที่สุดคือพวกเมือก รู้ว่าฟังแปลก แต่มันอยู่ทุกที่เลย!\n\nไม่นานก่อนข้าช่วยผู้หญิงคนหนึ่งที่ Menethil หากระเป๋า มันถูกเมือกกินไป ข้ายังเห็นคนของ Royal Apothecary Society จาก Undercity เก็บตัวอย่างมัน ข้าอยากรู้ว่าทำไม! มันมาจากไหน?\n\nได้ยินว่าที่ Felwood มีอีก ข้าต้องการตัวอย่างจากที่นั่นเพื่อวิจัยต่อ ข้าจะให้ภาชนะ เจ้าใช้เก็บตัวอย่างจากซากสิ่งมีชีวิตเหล่านั้น" },
        progress = { "476:2095278476:203559747", "การทดลองบางอย่างที่ข้าทำน่าทึ่งมาก ข้าคิดว่าหากทำต่ออีกหน่อย จะเข้าใจธรรมชาติของสิ่งมีชีวิตเหล่านี้และบทบาทต่อวิวัฒนาการของชีวิตบน Azeroth... หากมันเกี่ยวข้องตั้งแต่แรกน่ะนะ\n\nทฤษฎีสำคัญข้อหนึ่งของข้าที่ไม่ค่อยมีคนชอบ คือพวกเมือกและสไลม์เกี่ยวพันกับการกำเนิดโลกนี้ ราวกับเป็นของเหลวที่โลกหลั่งออกมา\n\nแต่ข้าจะพิสูจน์หรือหักล้างไม่ได้จนกว่าจะมีตัวอย่างเพิ่ม" },
        completion = { "17:916638280:900536014 N 387:1003846169:1920652323", "ผลงานน่าทึ่ง {name}! เจ้าเข้าใกล้พวกที่แปดเปื้อนจนเก็บตัวอย่างได้ แล้วยังกลับมาดูไม่บอบช้ำเลย! ขอบใจ ตัวอย่างเหล่านี้เหมาะที่สุด อยากเริ่มทดลองแทบไม่ไหว\n\nหากข้าคิดถูก อาจได้เป็นนักวิทยาศาสตร์ผู้ยิ่งใหญ่ที่สุดคนหนึ่งของ Explorers' League!\n\nนั่นจะพิสูจน์ให้ดวอร์ฟทุกคนเห็นว่า การให้โนมอย่างเราเข้า Ironforge หลังเหตุการณ์ Gnomeregan ไม่ใช่ความผิดพลาด" },
        required = { [11947] = { "22:276051688:1539657999", "ขวดบรรจุเมือกต้องสาปที่เติมแล้ว" }, [11949] = { "23:1814571176:1359198704", "ขวดบรรจุเมือกแปดเปื้อนที่เติมแล้ว" } },
        steps = { { "22:276051688:1539657999", "ขวดบรรจุเมือกต้องสาปที่เติมแล้ว" }, { "23:1814571176:1359198704", "ขวดบรรจุเมือกแปดเปื้อนที่เติมแล้ว" } },
    },
    [4513] = { -- A Little Slime Goes a Long Way
        title = { "30:1577124892:2049153260", "เมือกนิดเดียวก็ได้เรื่องไกล" },
        objective = { "142:1366029616:597260207", "นำ Filled Pure Sample Jars 10 ใบ ไปให้ Laris Geardawdle ที่ Ironforge\n\nหากหาไม่พบ ลองขอเบาะแสเพิ่มเติมจาก Laris" },
        description = { "32:1726092441:166598507 N 389:634705757:1501923065 N 62:1646780030:1768873295", "ข้าต้องการตัวอย่างเพิ่ม {name} แต่... ข้าไม่รู้จะพูดอย่างไร... ต้องเป็นตัวอย่างบริสุทธิ์ รู้แล้ว รู้แล้ว \"บริสุทธิ์หมายถึงอะไร Laris?\" ข้าก็ไม่แน่ใจ แต่รู้ว่าพวกนี้แปดเปื้อน เหมือน Felwood นั่นทำให้สิ่งที่ข้าตระหนักได้สำคัญนัก พวกเมือกดูจะปรับตัว รับลักษณะของพื้นที่ที่อยู่ ข้าต้องหาตัวอย่างที่ยังไม่ปนเปื้อน แต่ที่ไหน? ที่ไหนล่ะ?!\n\nโธ่! {name} รับภาชนะเหล่านี้ไป เผื่อเจ้าพบเองระหว่างทาง" },
        progress = { "109:239004583:1506298014", "มีเรื่องให้คิดมากเหลือเกิน แต่มันหมายความว่าอย่างไร? และส่งผลต่อชีวิตผู้คนบน Azeroth อย่างไร?" },
        completion = { "17:855783804:1641189031 N 301:49633038:879511256", "เจ้าพบแล้วหรือ? {name} เจ้าเองนี่แหละคือสมบัติล้ำค่า ความทุ่มเทและความช่วยเหลือของเจ้าวิเศษมาก ข้าขอบใจเท่าไรก็คงไม่พอ\n\nรับสิ่งนี้สำหรับความลำบากเถอะ ข้ามีงานต้องทำ แต่มั่นใจว่าหากเจ้ากลับมาภายหลัง ข้าคงต้องการให้ช่วยอีก\n\nขอบใจ ขอบใจมากจริง ๆ" },
        required = { [11954] = { "22:1350666302:38330271", "ขวดบรรจุตัวอย่างบริสุทธิ์ที่เติมแล้ว" } },
        steps = { { "22:1350666302:38330271", "ขวดบรรจุตัวอย่างบริสุทธิ์ที่เติมแล้ว" } },
    },
    [7342] = { -- Arrows Are For Sissies
        title = { "22:825051064:726492596", "ลูกธนูมีไว้สำหรับพวกขี้ขลาด" },
        progress = { "347:633746295:1439707149", "เชื่อเรื่องเหลวไหลนี่ไหม?! กระสุนเที่ยวล่าสุดจาก Kharanos ส่งผิด! ตอนนี้มีแต่ลูกธนูบอบบางไร้ประโยชน์ ข้าจะทำอะไรกับลูกธนูหัวทอเรียม 500,000 ดอกดี?\n\nเอาอย่างนี้ เจ้าหนู หากนำกระสุนปืนทอเรียมมา ข้าจะแลกกับลูกธนูหัวทอเรียม ตรง ๆ เลย! ตกลงไหม?" },
        completion = { "52:892869467:911105090", "ตกลงกันเรียบร้อย! ลูกธนูเป็นของเจ้าแล้ว" },
        description = { "347:633746295:1439707149", "เชื่อเรื่องเหลวไหลนี่ไหม?! กระสุนเที่ยวล่าสุดจาก Kharanos ส่งผิด! ตอนนี้มีแต่ลูกธนูบอบบางไร้ประโยชน์ ข้าจะทำอะไรกับลูกธนูหัวทอเรียม 500,000 ดอกดี?\n\nเอาอย่างนี้ เจ้าหนู หากนำกระสุนปืนทอเรียมมา ข้าจะแลกกับลูกธนูหัวทอเรียม ตรง ๆ เลย! ตกลงไหม?" },
        required = { [15997] = { "14:2086458669:2123321154", "กระสุนทอเรียม" } },
        objectiveLabels = {
            item = { ["Thorium Shells"] = "กระสุนทอเรียม" },
        },
    },
    [7905] = { -- The Darkmoon Faire
        title = { "18:1452120556:1355770990", "งาน Darkmoon Faire" },
        objective = { "95:1461682388:369354358", "นำ Free Ticket Voucher ไปส่งให้ Gelvas Grimgate ภายในงาน Darkmoon Faire" },
        description = { "347:364990026:1223592654", "Darkmoon Faire กำลังมา! อย่าลืมสัมผัสสิ่งมหัศจรรย์และความตื่นเต้นทั้งหมดเมื่องานมาถึงเมือง!\n\nหากไปตอนนี้ เจ้าใช้ใบแลกนี้รับตั๋วรางวัลฟรีได้! เพียงมอบให้ Gelvas Grimgate ภายในงาน\n\nตอนนี้งานอยู่ด้านนอก Goldshire ใน Elwynn Forest อย่าพลาด! ไปวันนี้เลย!" },
        progress = { "71:459068297:339315007", "ว่าอย่างไรสหาย มีอะไรให้ช่วย? มีใบแลกที่ต้องการใช้หรือ?" },
        completion = { "253:942363679:2052734256", "ยินดีต้อนรับสู่ Darkmoon Faire! ใบแลกนี้รับตั๋วรางวัลได้ห้าใบ ใช่แล้ว ห้าใบ!\n\nเมื่อสะสมตั๋วรางวัลแล้ว ให้มาคุยกับข้าเรื่องแลกของมีค่า ยิ่งมีตั๋วมาก ก็ยิ่งรับรางวัลได้มาก ไชโย!" },
        required = { [19338] = { "19:1214859949:1816878322", "คูปองแลกตั๋วฟรี" } },
        steps = { { "19:1214859949:1816878322", "คูปองแลกตั๋วฟรี" } },
    },
    [8275] = { -- Taking Back Silithus
        title = { "20:676320677:644628828", "ทวงคืน Silithus" },
        objective = { "58:1940832120:1670680797", "คุยกับ Windcaller Proudhorn ที่ Cenarion Hold ใน Silithus" },
        description = { "491:705038203:402485027", "เหล่าวีรบุรุษแห่ง Alliance จงฟัง! เราปล่อยภัยจากซิลิธิดไว้โดยไม่หยุดยั้งมานานเกินไป เมื่อไร้การต่อต้านจริงจัง พวกมันก็เตรียมขยายอาณาเขตครั้งใหญ่มาตลอด\n\nกองกำลัง Cenarion Circle กำลังรวมตัวใน Silithus เพื่อบุกสู้สิ่งมีชีวิตชั่วร้ายเหล่านี้ ขอเรียกนักผจญภัยที่พร้อมรบทุกคนมาร่วม!\n\nอย่ารอจนสาย! ช่วยเราป้องกัน Azeroth! รายงานตัวต่อ Windcaller Proudhorn ที่ Cenarion Hold เพื่อรับคำสั่งโดยละเอียด!" },
        completion = { "100:752870178:1752425769 C 230:1110158245:1512186270", "ยอดเยี่ยม ผู้สมัครใหม่ตอบรับเสียงเรียกให้รบกับซิลิธิด ยินดีต้อนรับสู่ Cenarion Hold {class} ดีใจที่คำของทูตเราไปถึงวีรบุรุษระดับเจ้า ที่นี่มีโอกาสให้ช่วยมากมาย ข้าคาดว่าอีกไม่นานเจ้าจะพิสูจน์ตนเป็นพันธมิตรที่มีค่าต่อภารกิจเรา" },
    },
    [8371] = { -- Concerted Efforts
        title = { "17:1907522337:693460465", "ร่วมแรงร่วมใจ" },
        objective = { "160:132025680:427132948", "นำ Alterac Valley Mark of Honor 3 ชิ้น, Arathi Basin Mark of Honor 3 ชิ้น และ Warsong Gulch Mark of Honor 3 ชิ้น ไปให้ Alliance Brigadier General ที่อยู่นอกสนามรบ", variants = { { "200:1232643659:825623294", "นำ Alterac Valley Marks of Honor 3 ชิ้น, Arathi Basin Marks of Honor 3 ชิ้น, Warsong Gulch Marks of Honor 3 ชิ้น และ Darkspear Islands Marks of Honor 3 ชิ้น ไปให้ Alliance Brigadier General ที่อยู่นอกสนามรบ" } } },
        description = { { "396:1369192929:800198212 N 91:1470888812:1712020900", "397:1024368036:424354047 N 91:1470888812:1712020900" }, "เราไม่ได้สู้กับ Horde เป็นศึกแยกขาดจากกันอีกแล้ว สหาย\n\nชนะในแนวรบหนึ่งเท่ากับตัดทรัพยากรที่ Horde จะใช้กับเราในอีกศึก เช่นเดียวกัน ความพ่ายแพ้ที่ใดก็อาจทำให้ศัตรูได้เปรียบในอีกแห่งของโลก\n\nAlliance ต้องการนักรบที่เข้าใจภาพรวมเช่นนี้มากขึ้น ทหารผ่านศึกที่เจนสนามจริง ๆ! {name} กลับมาหาข้าหลังจากรับใช้ด้วยการรบกับ Horde ในสนามรบที่เปิดอยู่ทุกแห่งของเราแล้ว" },
        progress = { { "34:2053590305:1456331125", "32:2098536049:1557053969" }, "การเดินทางเป็นอย่างไรบ้าง สหาย?" },
        completion = { "30:268255285:11924892 N 200:1484230887:1214584491 C 37:1171811633:819608632", "เจ้าไม่ทำให้ผิดหวังเลย {name}! สิ่งที่เรียนรู้อยู่เหนือเหรียญกับคำชมเล็กน้อย เป็นความรู้ที่ได้จากประสบการณ์และการขัดเกลาจิตใจในสนามรบเท่านั้น\n\nทำได้ดี {class} เจ้าคือวีรบุรุษแท้จริงแห่ง Alliance!" },
        required = { [20558] = { "27:1151639554:183227099", "เหรียญเกียรติยศ Warsong Gulch" }, [20559] = { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" }, [20560] = { "28:1124473597:1604635920", "เหรียญเกียรติยศ Alterac Valley" }, [274895] = { "31:832704024:1368023717", "ตราเกียรติยศ Darkspear Islands" } },
