        description = { "10:1401179418:1568553899 C 483:1797862860:229612946", "ยินดีที่ได้พบ {class} ข้ามีบางอย่างที่เจ้าอาจสนใจ\n\nข้ามีชุดเกราะคล้ายที่คนอาชีพเจ้าสวม แต่คุณภาพสูงกว่ามาก ข้ายินดีแลกปลอกรัดแขนกับของธรรมดา หากช่วยธุระเล็กน้อย\n\nเลือดของฟรอสต์เซเบอร์กับหมีที่อยู่ใน Winterspring มีคุณสมบัติที่ข้าต้องการตอนนี้ นำตัวอย่างจำนวนมากพอมา พร้อมปลอกรัดแขนกับเงินทองเล็กน้อย เจ้าจะพบว่าคุ้มความพยายาม" },
        progress = { "45:622411099:806033473 N 1:63:63", "นำสิ่งที่ข้าขอมาแล้วหรือ {name}?" },
        completion = { "244:1055352563:1341160308", "ยอดเยี่ยม! มาแลกกันเถอะ ตัดใจจากเกราะชั้นเลิศนี้ยาก แต่เกรงว่าข้าคงยังไม่ต้องใช้ในเร็ววัน\n\nถ้าสนใจทำงานให้ข้าเพิ่ม ข้าอาจยอมมอบชิ้นที่เหลือให้" },
        required = { [16735] = { "16:486340281:555898680", "ปลอกแขนแห่งความกล้า" }, [21928] = { "25:2015114131:1353431141", "ตัวอย่างเลือดจาก Winterspring" } },
        objectiveLabels = {
            item = { ["Bracers of Valor"] = "ปลอกแขนแห่งความกล้า", ["Winterspring Blood Sample"] = "ตัวอย่างเลือดจาก Winterspring" },
        },
