    [8951] = { -- Anthion's Parting Words
        title = { "23:573656928:1309079977", "คำอำลาของ Anthion" },
        objective = { "103:281021981:1622049274", "กลับไปหา Deliana ที่ Ironforge พร้อม Wildheart Boots, Wildheart Kilt และ Wildheart Spaulders" },
        description = { "458:1132217706:1938632134", "วิญญาณของ Valthalak ถูกเก็บอยู่ในเครื่องรางนี้ ด้วยความโลภ เราโง่เขลาแบ่งมันเป็นสามส่วน โดยไม่รู้คำสาปที่รออยู่\n\nหนทางเดียวที่จะหยุดคาถาของ Valthalak คือประกอบเหรียญกลับเข้าด้วยกัน กลับไปบอก Deliana ว่า Bodley เป็นความหวังเดียวที่จะหาส่วนที่เหลือได้ คุยกับนางเรื่องรางวัลที่ตกลงกันไว้ด้วย\n\nคราวนี้ข้าจะได้พักอย่างสงบ ขอให้เจ้าโชคดีที่สุด เพราะเจ้าจะต้องใช้โชคทั้งหมดที่มี!" },
        progress = { "13:1761969110:399778402 N 93:1800554215:1475646531", "กลับมาแล้ว {name} ต้องเล่าทุกสิ่งที่ค้นพบให้ข้าฟัง แต่ก่อนอื่นมาจัดการรางวัลของเจ้าก่อน" },
        completion = { "190:1310137436:1966522662", "ไม่อยากเชื่อว่าชีวิตพวกเราแทบจะต้องสูญสิ้นเพราะเหรียญงี่เง่าชิ้นเดียว! และเจ้าแน่ใจว่า Anthion เอ่ยถึง Bodley?\n\nเอาล่ะ เจ้าทำงานสำเร็จแล้ว มาจัดการเรื่องรางวัลกันให้เรียบร้อย" },
        required = { [16715] = { "15:216658111:910753435", "รองเท้าบูตแห่งหัวใจพงไพร" }, [16719] = { "14:1105797594:1961456342", "กระโปรงคิลต์แห่งหัวใจพงไพร" }, [16718] = { "19:480658180:2108834782", "เกราะไหล่แห่งหัวใจพงไพร" } },
        objectiveLabels = {
            item = { ["Wildheart Boots"] = "รองเท้าบูตแห่งหัวใจพงไพร", ["Wildheart Kilt"] = "กระโปรงคิลต์แห่งหัวใจพงไพร", ["Wildheart Spaulders"] = "เกราะไหล่แห่งหัวใจพงไพร" },
        },
    },
    [8952] = { -- Anthion's Parting Words
        title = { "23:573656928:1309079977", "คำอำลาของ Anthion" },
        objective = { "114:68603805:935615364", "กลับไปหา Deliana ที่ Ironforge พร้อม Beaststalker's Boots, Beaststalker's Pants และ Beaststalker's Mantle" },
        description = { "458:1132217706:1938632134", "วิญญาณของ Valthalak ถูกเก็บอยู่ในเครื่องรางนี้ ด้วยความโลภ เราโง่เขลาแบ่งมันเป็นสามส่วน โดยไม่รู้คำสาปที่รออยู่\n\nหนทางเดียวที่จะหยุดคาถาของ Valthalak คือประกอบเหรียญกลับเข้าด้วยกัน กลับไปบอก Deliana ว่า Bodley เป็นความหวังเดียวที่จะหาส่วนที่เหลือได้ คุยกับนางเรื่องรางวัลที่ตกลงกันไว้ด้วย\n\nคราวนี้ข้าจะได้พักอย่างสงบ ขอให้เจ้าโชคดีที่สุด เพราะเจ้าจะต้องใช้โชคทั้งหมดที่มี!" },
        progress = { "13:1761969110:399778402 N 93:1800554215:1475646531", "กลับมาแล้ว {name} ต้องเล่าทุกสิ่งที่ค้นพบให้ข้าฟัง แต่ก่อนอื่นมาจัดการรางวัลของเจ้าก่อน" },
        completion = { "190:1310137436:1966522662", "ไม่อยากเชื่อว่าชีวิตพวกเราแทบจะต้องสูญสิ้นเพราะเหรียญงี่เง่าชิ้นเดียว! และเจ้าแน่ใจว่า Anthion เอ่ยถึง Bodley?\n\nเอาล่ะ เจ้าทำงานสำเร็จแล้ว มาจัดการเรื่องรางวัลกันให้เรียบร้อย" },
        required = { [16675] = { "20:1199498718:268959505", "รองเท้าบูตของนักสะกดรอยสัตว์" }, [16678] = { "20:1906831865:65500706", "กางเกงของนักสะกดรอยสัตว์" }, [16679] = { "21:2071711769:216304167", "ผ้าคลุมไหล่ของนักสะกดรอยสัตว์" } },
        objectiveLabels = {
            item = { ["Beaststalker's Boots"] = "รองเท้าบูตของนักสะกดรอยสัตว์", ["Beaststalker's Pants"] = "กางเกงของนักสะกดรอยสัตว์", ["Beaststalker's Mantle"] = "ผ้าคลุมไหล่ของนักสะกดรอยสัตว์" },
        },
    },
    [8953] = { -- Anthion's Parting Words
        title = { "23:573656928:1309079977", "คำอำลาของ Anthion" },
        objective = { "105:551465731:1085145475", "กลับไปหา Deliana ที่ Ironforge พร้อม รองเท้าบูตของจอมเวท, กางเกงของจอมเวท และ ผ้าคลุมไหล่ของจอมเวท" },
        description = { "458:1132217706:1938632134", "วิญญาณของ Valthalak ถูกเก็บอยู่ในเครื่องรางนี้ ด้วยความโลภ เราโง่เขลาแบ่งมันเป็นสามส่วน โดยไม่รู้คำสาปที่รออยู่\n\nหนทางเดียวที่จะหยุดคาถาของ Valthalak คือประกอบเหรียญกลับเข้าด้วยกัน กลับไปบอก Deliana ว่า Bodley เป็นความหวังเดียวที่จะหาส่วนที่เหลือได้ คุยกับนางเรื่องรางวัลที่ตกลงกันไว้ด้วย\n\nคราวนี้ข้าจะได้พักอย่างสงบ ขอให้เจ้าโชคดีที่สุด เพราะเจ้าจะต้องใช้โชคทั้งหมดที่มี!" },
        progress = { "13:1761969110:399778402 N 93:1800554215:1475646531", "กลับมาแล้ว {name} ต้องเล่าทุกสิ่งที่ค้นพบให้ข้าฟัง แต่ก่อนอื่นมาจัดการรางวัลของเจ้าก่อน" },
        completion = { "190:1310137436:1966522662", "ไม่อยากเชื่อว่าชีวิตพวกเราแทบจะต้องสูญสิ้นเพราะเหรียญงี่เง่าชิ้นเดียว! และเจ้าแน่ใจว่า Anthion เอ่ยถึง Bodley?\n\nเอาล่ะ เจ้าทำงานสำเร็จแล้ว มาจัดการเรื่องรางวัลกันให้เรียบร้อย" },
        required = { [16682] = { "16:1497047108:414814931", "รองเท้าบูตของจอมเวท" }, [16687] = { "19:1283747150:653326846", "กางเกงของจอมเวท" }, [16689] = { "17:1232236707:2143495941", "ผ้าคลุมไหล่ของจอมเวท" } },
        objectiveLabels = {
            item = { ["Magister's Boots"] = "รองเท้าบูตของจอมเวท", ["Magister's Leggings"] = "กางเกงของจอมเวท", ["Magister's Mantle"] = "ผ้าคลุมไหล่ของจอมเวท" },
        },
    },
    [8954] = { -- Anthion's Parting Words
        title = { "23:573656928:1309079977", "คำอำลาของ Anthion" },
        objective = { "109:1134600907:510471551", "กลับไปหา Deliana ที่ Ironforge พร้อม รองเท้าบูตหลอมแสง, เกราะขาหลอมแสง และ เกราะไหล่หลอมแสง" },
        description = { "458:1132217706:1938632134", "วิญญาณของ Valthalak ถูกเก็บอยู่ในเครื่องรางนี้ ด้วยความโลภ เราโง่เขลาแบ่งมันเป็นสามส่วน โดยไม่รู้คำสาปที่รออยู่\n\nหนทางเดียวที่จะหยุดคาถาของ Valthalak คือประกอบเหรียญกลับเข้าด้วยกัน กลับไปบอก Deliana ว่า Bodley เป็นความหวังเดียวที่จะหาส่วนที่เหลือได้ คุยกับนางเรื่องรางวัลที่ตกลงกันไว้ด้วย\n\nคราวนี้ข้าจะได้พักอย่างสงบ ขอให้เจ้าโชคดีที่สุด เพราะเจ้าจะต้องใช้โชคทั้งหมดที่มี!" },
        progress = { "13:1761969110:399778402 N 93:1800554215:1475646531", "กลับมาแล้ว {name} ต้องเล่าทุกสิ่งที่ค้นพบให้ข้าฟัง แต่ก่อนอื่นมาจัดการรางวัลของเจ้าก่อน" },
        completion = { "190:1310137436:1966522662", "ไม่อยากเชื่อว่าชีวิตพวกเราแทบจะต้องสูญสิ้นเพราะเหรียญงี่เง่าชิ้นเดียว! และเจ้าแน่ใจว่า Anthion เอ่ยถึง Bodley?\n\nเอาล่ะ เจ้าทำงานสำเร็จแล้ว มาจัดการเรื่องรางวัลกันให้เรียบร้อย" },
        required = { [16725] = { "16:954391816:1182387180", "รองเท้าบูตหลอมแสง" }, [16728] = { "20:1673653188:759791659", "เกราะขาหลอมแสง" }, [16729] = { "20:861537357:1877445172", "เกราะไหล่หลอมแสง" } },
        objectiveLabels = {
            item = { ["Lightforge Boots"] = "รองเท้าบูตหลอมแสง", ["Lightforge Legplates"] = "เกราะขาหลอมแสง", ["Lightforge Spaulders"] = "เกราะไหล่หลอมแสง" },
        },
    },
    [8955] = { -- Anthion's Parting Words
        title = { "23:573656928:1309079977", "คำอำลาของ Anthion" },
        objective = { "92:1439655563:1293315650", "กลับไปหา Deliana ที่ Ironforge พร้อม รองเท้าแตะแห่งศรัทธา, กระโปรงแห่งศรัทธา และ ผ้าคลุมไหล่แห่งศรัทธา" },
        description = { "458:1132217706:1938632134", "วิญญาณของ Valthalak ถูกเก็บอยู่ในเครื่องรางนี้ ด้วยความโลภ เราโง่เขลาแบ่งมันเป็นสามส่วน โดยไม่รู้คำสาปที่รออยู่\n\nหนทางเดียวที่จะหยุดคาถาของ Valthalak คือประกอบเหรียญกลับเข้าด้วยกัน กลับไปบอก Deliana ว่า Bodley เป็นความหวังเดียวที่จะหาส่วนที่เหลือได้ คุยกับนางเรื่องรางวัลที่ตกลงกันไว้ด้วย\n\nคราวนี้ข้าจะได้พักอย่างสงบ ขอให้เจ้าโชคดีที่สุด เพราะเจ้าจะต้องใช้โชคทั้งหมดที่มี!" },
        progress = { "13:1761969110:399778402 N 93:1800554215:1475646531", "กลับมาแล้ว {name} ต้องเล่าทุกสิ่งที่ค้นพบให้ข้าฟัง แต่ก่อนอื่นมาจัดการรางวัลของเจ้าก่อน" },
        completion = { "190:1310137436:1966522662", "ไม่อยากเชื่อว่าชีวิตพวกเราแทบจะต้องสูญสิ้นเพราะเหรียญงี่เง่าชิ้นเดียว! และเจ้าแน่ใจว่า Anthion เอ่ยถึง Bodley?\n\nเอาล่ะ เจ้าทำงานสำเร็จแล้ว มาจัดการเรื่องรางวัลกันให้เรียบร้อย" },
        required = { [16691] = { "14:1020361494:2119549174", "รองเท้าแตะแห่งศรัทธา" }, [16694] = { "12:917115017:284057719", "กระโปรงแห่งศรัทธา" }, [16695] = { "13:22237946:369391771", "ผ้าคลุมไหล่แห่งศรัทธา" } },
        objectiveLabels = {
            item = { ["Devout Sandals"] = "รองเท้าแตะแห่งศรัทธา", ["Devout Skirt"] = "กระโปรงแห่งศรัทธา", ["Devout Mantle"] = "ผ้าคลุมไหล่แห่งศรัทธา" },
        },
    },
    [8956] = { -- Anthion's Parting Words
        title = { "23:573656928:1309079977", "คำอำลาของ Anthion" },
        objective = { "108:63128552:485769981", "กลับไปหา Deliana ที่ Ironforge พร้อม รองเท้าบูตช่างเงา, กางเกงช่างเงา และ เกราะไหล่ช่างเงา" },
        description = { "458:1132217706:1938632134", "วิญญาณของ Valthalak ถูกเก็บอยู่ในเครื่องรางนี้ ด้วยความโลภ เราโง่เขลาแบ่งมันเป็นสามส่วน โดยไม่รู้คำสาปที่รออยู่\n\nหนทางเดียวที่จะหยุดคาถาของ Valthalak คือประกอบเหรียญกลับเข้าด้วยกัน กลับไปบอก Deliana ว่า Bodley เป็นความหวังเดียวที่จะหาส่วนที่เหลือได้ คุยกับนางเรื่องรางวัลที่ตกลงกันไว้ด้วย\n\nคราวนี้ข้าจะได้พักอย่างสงบ ขอให้เจ้าโชคดีที่สุด เพราะเจ้าจะต้องใช้โชคทั้งหมดที่มี!" },
        progress = { "13:1761969110:399778402 N 93:1800554215:1475646531", "กลับมาแล้ว {name} ต้องเล่าทุกสิ่งที่ค้นพบให้ข้าฟัง แต่ก่อนอื่นมาจัดการรางวัลของเจ้าก่อน" },
        completion = { "190:1310137436:1966522662", "ไม่อยากเชื่อว่าชีวิตพวกเราแทบจะต้องสูญสิ้นเพราะเหรียญงี่เง่าชิ้นเดียว! และเจ้าแน่ใจว่า Anthion เอ่ยถึง Bodley?\n\nเอาล่ะ เจ้าทำงานสำเร็จแล้ว มาจัดการเรื่องรางวัลกันให้เรียบร้อย" },
        required = { [16711] = { "17:482834663:248346360", "รองเท้าบูตช่างเงา" }, [16709] = { "17:1190167810:44887561", "กางเกงช่างเงา" }, [16708] = { "21:332342943:1049048847", "เกราะไหล่ช่างเงา" } },
        objectiveLabels = {
            item = { ["Shadowcraft Boots"] = "รองเท้าบูตช่างเงา", ["Shadowcraft Pants"] = "กางเกงช่างเงา", ["Shadowcraft Spaulders"] = "เกราะไหล่ช่างเงา" },
        },
    },
