    [8977] = { -- Return to Deliana
        title = { "17:24742170:1057641438", "กลับไปหา Deliana" },
        objective = { "67:1526987280:1186573086", "นำ Extra-Dimensional Ghost Revealer ไปให้ Deliana ที่ Ironforge" },
        description = { "34:1195322377:1109795208 N 167:1674110699:513019215", "ได้ร่วมงานกับเจ้าดีมาก {name} นี่ชิ้นงานที่เสร็จแล้ว\n\nหวังว่ามันจะช่วยงานที่เจ้ากำลังทำ และถ้าไม่รบกวน ช่วยบอกต่อด้วย ข้าไม่รังเกียจที่จะมีลูกค้าเพิ่ม!" },
        progress = { "16:474391829:310761940", "กลับมาแล้วหรือ?" },
        completion = { "29:800629453:2000973965 N 85:1634326232:878553047", "ยอดเยี่ยม! ทำได้ดี {name} ข้าไม่แน่ใจว่าจะไว้ใจฝีมือกอบลินได้ แต่ก็ไม่มีทางเลือกอื่น" },
    },
    [8997] = { -- Back to the Beginning
        title = { "21:1461300965:1905746562", "กลับสู่จุดเริ่มต้น" },
        objective = { "49:449130385:571307069", "คุยกับ Deliana ที่ The High Seat ใน Ironforge" },
        description = { "329:353266693:107766633", "คงถึงเวลาลาแล้วสินะ สหาย แต่ข้าจะอยู่ที่นี่เสมอ หากเจ้าอยากแวะมาคุยเป็นครั้งคราว อาจเป็นตอนเดินเตร่รอเพื่อนมาร่วมบุก Blackrock Spire\n\nไปเถอะ ก่อนข้าจะร้องไห้ กลับไปหา Deliana ที่ Ironforge แล้วบอกนางว่าเกิดอะไรขึ้น" },
        completion = { "48:1007009448:482088592 N 91:577669748:1532027964", "ข้าดีใจมากที่เจ้ากลับมาปลอดภัย {name} ดูแข็งแรงดี แม้จะบอบช้ำมาบ้าง\n\nมา เล่าทุกอย่างที่เกิดขึ้นให้ข้าฟัง" },
    },
