    [95817] = { -- Rotgath Stonebeard
        title = { "18:221831392:2110476571", "Rotgath Stonebeard" },
        objective = { "58:18171721:502013250", "พบ Rotgath Stonebeard ใกล้ Great Forge ใน Ironforge" },
        description = { "479:127826757:293374398", "เคยพบ Rotgath Stonebeard ไหม? เขาเป็นช่างตีเหล็กชาวดวอร์ฟใน Ironforge ไม่ค่อยช่างคุย แต่ไว้ใจได้เสมอ เรามักไปหาเมื่อต้องการของแบบเรียบง่ายจำนวนมาก งานชนิดที่ Stondry หยิ่งเกินกว่าจะรับทำเอง\n\nเขาทำงานเสร็จรวดเร็วมาก โดยเฉพาะเมื่อช่วยช่างใหม่ตั้งร้าน ข้าไม่ไว้ใจใครให้ทำป้ายของเจ้าได้เร็วเท่าเขา หากเขาสร้างปัญหา ก็บอกว่าข้าส่งมา!" },
    },
    [97263] = { -- Your Package Has Arrived
        title = { "24:1127365813:175004154", "ห่อของของเจ้ามาถึงแล้ว" },
        objective = { "35:293555640:1390692503", "นำห่อของที่วางผิดที่ของ Eldrun ไปส่ง" },
        description = { "186:1109205732:968777247", "<มีห่อของที่วางผิดที่หลายห่ออยู่ข้างตู้ไปรษณีย์ เจ้าสังเกตว่าห่อหนึ่งระบุให้ส่งจาก Aerie Peak ไป Ironforge ถึง Eldrun Stormbreaker และเขียนว่า \"ด่วน\">" },
        progress = { "29:876713009:2055858412", "เจ้าถืออะไรมานั่น?" },
        completion = { "410:441783949:397776885", "อะไรนะ! ข้าไปตู้ไปรษณีย์ข้างธนาคารทุกวันเพื่อตามหาห่อนี้! เมืองนี้ควรจัดผังให้เป็นเรื่องเป็นราว ไม่ได้หาทางง่ายเหมือน Aerie Peak เลย!\n\nขอดูว่าได้อะไรมา... เครื่องมือแกะสลักโทเทม... ขวานสำรอง... อุปกรณ์กอบลินอะไรสักอย่าง? ข้าไม่ได้สั่ง! อา ส่งคืนก็แล้วกัน\n\nเอ่อ คือ... ขอบใจที่นำทุกอย่างมาให้ นี่ของเล็กน้อยตอบแทนที่ลำบาก", variants = { { "410:2027949414:776310419", "อะไรนะ! ข้าไปตู้ไปรษณีย์ข้างธนาคารทุกวันเพื่อตามหาห่อนี้! เมืองนี้ควรจัดผังให้เป็นเรื่องเป็นราว ไม่ได้หาทางง่ายเหมือน Aerie Peak เลย!\n\nขอดูว่าได้อะไรมา... เครื่องมือแกะสลักโทเทม... ขวานสำรอง... อุปกรณ์กอบลินอะไรสักอย่าง? ข้าไม่ได้สั่ง! อา ส่งคืนก็แล้วกัน\n\nเอ่อ คือ... ขอบใจที่นำทุกอย่างมาให้ นี่ของเล็กน้อยตอบแทนที่ลำบาก" } } },
        required = { [277505] = { "17:794591476:1029123900", "พัสดุที่วางผิดที่" } },
        steps = { { "17:794591476:1029123900", "พัสดุที่วางผิดที่" } },
    },
    [98300] = { -- Word to Ironforge
        title = { "17:1950334045:36950797", "ส่งข่าวถึง Ironforge" },
        objective = { "63:690283922:368526738", "นำ Howin's Missive ไปส่งให้ King Magni Bronzebeard ที่ Ironforge" },
        description = { "31:1355861753:934691177 N 466:1076561599:1483484181", "งานข้าที่นี่ยังอีกไกลกว่าจะจบ {name} ข้าต้องส่งข่าวให้ Claira ภรรยาข้าที่ Aerie Peak และแจ้งความคืบหน้าให้ Falstad ด้วย\n\nแต่นั่นเป็นธุระของข้า ธุระของ Wildhammer\n\nอย่างไรก็ตาม เจ้าควรแจ้ง King Magni Bronzebeard ที่ Ironforge เรื่องทั้งหมดด้วย Wetlands อยู่ใกล้ดินแดนพระองค์นิดเดียว และสิ่งที่เกิดขึ้นก็ไม่มีเรื่องใดเป็นข่าวดีตรงหน้าบ้าน จดหมายนี้น่าจะช่วยได้\n\nเจ้ากลับผ่าน Dun Algaz หรือบินจาก Menethil Harbor เพื่อไป Ironforge ได้", variants = { { "31:1355861753:934691177 N 478:84197401:1612936305", "งานข้าที่นี่ยังอีกไกลกว่าจะจบ {name} ข้าต้องส่งข่าวให้ Claira ภรรยาข้าที่ Aerie Peak และแจ้งความคืบหน้าให้ Falstad ด้วย\n\nแต่นั่นเป็นธุระของข้า เจ้ายังไม่พร้อมเดินทางกลับบ้านตอนนี้\n\nอย่างไรก็ตาม เจ้าควรแจ้ง King Magni Bronzebeard ที่ Ironforge เรื่องทั้งหมดด้วย Wetlands อยู่ไม่ไกลจากดินแดนของพระองค์ และเรื่องที่เกิดขึ้นก็ล้วนเป็นข่าวร้ายที่มาถึงหน้าประตูบ้าน จดหมายนี้น่าจะช่วยได้\n\nเจ้ากลับผ่าน Dun Algaz หรือบินจาก Menethil Harbor ไป Ironforge ก็ได้" } } },
        completion = { "482:574701889:221778088", "อา พวก Wildhammer ใช่ ข้ารู้จักพวกเขาดี พวกเขาอาจไม่ได้ถือว่าข้าเป็นกษัตริย์ของตน แต่ช่วงหลังความสัมพันธ์ของเราดีขึ้นมาก สะพาน Thandol เป็นหลักฐานเรื่องนี้\n\nถ้ารายงานของ Howin เป็นจริง เราต้องเตรียมลงมือเพิ่มทางชายแดนเหนือ Grim Batol มีประวัตินองเลือดยาวนาน และข้ารู้ดีว่าที่นั่นสำคัญทางยุทธศาสตร์เพียงใด\n\nข้าขอบใจที่เจ้าช่วยทั้งพวก Wildhammer ใน Wetlands และฝ่ายสัมพันธมิตรที่ Menethil Harbor" },
        progress = { "22:103036130:210292086 C 52:904160184:1421922545", "ยินดีต้อนรับสู่ Ironforge {class} ข้าคือราชา Magni Bronzebeard ผู้ปกครองดินแดนแห่งนี้" },
        required = { [280392] = { "15:1206888713:1041933018", "สารจาก Howin" } },
        steps = { { "15:1206888713:1041933018", "สารจาก Howin" } },
    },
    [98313] = { -- For Further Study
        title = { "17:1750320076:775058305", "เพื่อศึกษาต่อ" },
        objective = { "65:1173398458:1764809876", "นำ Whelgar Relic Package ไปให้ Historian Karnik ที่ Ironforge" },
        description = { "28:697722924:14066106 N 353:72691297:632885564", "ไม่ว่าเรื่องนี้เกี่ยวกับอะไร {name} มันยิ่งใหญ่แน่นอน\n\nข้าจะห่อทุกอย่างให้เรียบร้อย นำไปให้ Historian Karnik ที่ Hall of Explorers ใน Ironforge ปกติพบเขาได้ด้านหลัง ก้มหน้าจมอยู่กับตำราสักเล่มในห้องสมุด\n\nคงต้องใช้คนเป็นกองทัพถึงจะไขเรื่องนี้ได้ แต่หากสิ่งที่เราเห็นจนถึงตอนนี้บอกอะไรได้ ความพยายามก็จะคุ้มแน่!" },
        completion = { "261:145568938:515865679", "โอ้โฮ...\n\nมีเรื่องให้ไล่ดูเยอะทีเดียว แต่น่าตื่นเต้นจริง ๆ น่าตื่นเต้นมาก!\n\nข้าคงต้องใช้เวลาสักพักกว่าจะวางแผนได้ ไว้กลับมาอีกครั้งแล้วข้าจะเล่าความคืบหน้าให้ฟัง ตอนนี้ขอให้รับคำขอบคุณจาก Explorers' League ไปก่อน" },
        progress = { "63:1515788339:2066074050", "ขอโทษที ข้ายุ่งมากจริง ๆ เจ้าต้องการอะไรหรือ?" },
        required = { [280403] = { "21:700952689:1779273969", "ห่อโบราณวัตถุ Whelgar" } },
        objectiveLabels = {
            item = { ["Whelgar Relic Package"] = "ห่อโบราณวัตถุ Whelgar" },
        },
    },
    [2965] = { -- Portents of Uldum
        title = { "17:1307916101:666828308", "สัญญาณแห่ง Uldum" },
        objective = { "60:1670759715:1912007558", "คุยกับ Nara Wildmane ที่ Elder Rise ใน Thunder Bluff" },
        description = { "4:1110228981:147916455 N 475:317728617:509679139", "อา {name} ช่างเหมาะที่เจ้ากลับมาหาข้า สิ่งที่เจ้าเปิดเผยที่จุดขุดค้น Uldaman ทำให้เหล่าปราชญ์มีเรื่องหารือมาก ข้ากำลังคุยเรื่องนั้นกับดรูอิดคนหนึ่งชื่อ Nara Wildmane แล้วก็นึกได้ว่าประสบการณ์ผจญภัยของนางอาจสำคัญมากต่อก้าวต่อไปของเรา\n\nข้าอยากให้เจ้าคุยกับนางเรื่องการเดินทางไป Valley of the Watchers ในทะเลทราย Tanaris นางรอเจ้าอยู่ที่ Elder Rise" },
        completion = { "313:916119384:2107208908 N 90:362167950:822268219", "ลึกเข้าไปในทะเลทราย Tanaris มีสถานที่ชื่อ Valley of the Watchers แผ่นดิสก์ที่เจ้ากู้คืนมา... เมื่อแปลอักขระแล้ว มีการกล่าวถึงสถานที่ชื่อ Uldum คนส่วนใหญ่คิดว่าเป็นเพียงตำนาน\n\nข้ารู้ว่าไม่จริง Uldum มีอยู่ ข้าเคยไปมา เอ่อ... อย่างน้อยก็ด้านนอก\n\nประเด็นคือ {name} เราคิดว่าแผ่นดิสก์เชื่อมโยงกับ Uldum และอยากให้เจ้าไปที่นั่น" },
    },
    [2966] = { -- Seeing What Happens
        title = { "19:1699849438:36816056", "ดูว่าจะเกิดอะไรขึ้น" },
        objective = { "124:1495573508:969337110", "นำ miniature platinum discs ไปยังประตู Uldum ใน Tanaris แล้วหาเบาะแสความเชื่อมโยงระหว่างทั้งสองสิ่ง" },
        description = { "484:513222817:645356849", "Sage Truthseeker กับข้าอยากให้เจ้านำแผ่นดิสก์ขนาดเล็กที่พบไปยังประตู Uldum ที่ปิดผนึก เรา... ไม่แน่ใจว่าจะเกิดอะไรขึ้น\n\nฟังดูเสี่ยง เรารู้ แต่ก็อาจไม่เกิดอะไรเลย เจ้าอาจต้องใช้แผ่นดิสก์กับบางสิ่ง หรือประตูอาจปลดล็อกเมื่อเจ้ามีแผ่นดิสก์ติดตัว เปิดใจลองทุกอย่าง และเตรียมพร้อมกับทุกสิ่งที่อาจเกิดขึ้น\n\nเรียนรู้ให้ได้เท่าที่ทำได้ แล้วกลับมาหาข้า เราจะมีเรื่องให้คุยกันมาก" },
        progress = { "109:1149819445:626612892", "แท่นที่ดูคุ้นตานี้โผล่พ้นทรายร้อน บางทีการที่มันอยู่ที่นี่อาจมีความหมาย..." },
        completion = { "468:268243397:1261346036", "เมื่อเจ้าแตะแท่น แผ่นดิสก์ขนาดเล็กจาก Uldaman ส่งเสียงครางและเรืองแสงในเป้ ความรู้สึกซ่าที่คุ้นเคยแล่นผ่านมือ ขณะภาพของ Stone Watcher อีกตนปรากฏขึ้นหน้าประตู Uldum\n\n\"สวัสดี ข้าคือผู้พิทักษ์ทางเข้า ชุดแผ่นดิสก์ที่ใช้ขอผ่านยังขาดแผ่นสำหรับเข้าใช้งานที่ถูกต้อง นั่นคือ Plates of Uldum โปรดรวมแผ่นดังกล่าวเข้ากับโครงสร้างแผ่นดิสก์ แล้วทำลำดับการขอผ่านซ้ำ ขอบคุณ\"" },
    },
    [2968] = { -- A Future Task
        title = { "13:495001730:1713837883", "งานในอนาคต" },
        objective = { "45:1823844886:486299692", "คุยกับ Sage Truthseeker ที่ Thunder Bluff" },
        description = { "5:1151914341:80614338 N 381:739610809:115814438 N 82:801357931:1240600530", "เอาล่ะ {name}... ดูเหมือนเราจะพบทางตันที่ไม่น่ายินดี เรารู้ว่าต้องการ Plates of Uldum แต่ไม่รู้ว่าอยู่ที่ใด เราจะวิจัยแล้ววางแผนที่แน่นอน ข้ามีแนวคิดอยู่สองสามอย่างว่าจะเริ่มหาที่ไหน และหวังว่าไม่นานเราจะขอให้เจ้ากลับมาร่วมค้นหาความจริง\n\nต้องแจ้ง Sage Truthseeker ให้ทราบ {name} เขาคงอยากขอบใจเจ้าด้วยตัวเองที่ตอบรับเสียงเรียกอีกครั้ง" },
        completion = { "166:1052088674:249403253 N 317:1859685769:497416936", "เราจึงเห็นตรงกัน ทางที่ดีที่สุดคือรอจนจำกัดพื้นที่ที่แผ่นเหล่านั้นอาจซ่อนอยู่ได้ เจ้าพาเรามาไกลถึงเพียงนี้ {name} ข้าหวังว่าเจ้าจะเป็นคนกลับออกภาคสนามไปเผชิญความลับของ Uldum\n\nระหว่างนี้รับค่าตอบแทนนี้เถอะ น่าจะครอบคลุมค่าใช้จ่ายที่เสียไปในการช่วยเรา และมีเพิ่มให้อีกเล็กน้อย อย่าลืมกลับมาถามข่าวเร็ว ๆ นี้... Uldum กำลังเรียกหาเราทุกคน เจ้าหนุ่มสาวเอ๋ย" },
    },
    [2950] = { -- Nogg's Ring Redo
        title = { "16:1887832115:914639685", "Nogg ทำแหวนใหม่" },
        objective = { "100:306688062:1503077435", "นำ Brilliant Gold Ring, Silver Bar, Moss Agate และเหรียญเงิน 30 เหรียญ ไปให้ Nogg ที่ Orgrimmar" },
        description = { "473:482320592:896621959", "ไม่ ไม่ ไม่ ข้าไม่ได้จู่ ๆ จะบอกว่าแหวนเป็นของข้า ปกติข้าไม่ทำอย่างนี้ แต่ข้อมูลเรื่อง Dark Iron ของเจ้ามีประโยชน์มาก ข้าจะปรับแหวนให้ดีกว่าที่คนทำของเรียบง่ายชิ้นนี้จะเคยทำได้ คงเป็นโนมสักคน...\n\nถ้านำแท่งเงิน มอสอะเกต และสามสิบเหรียญเงินเป็นค่าแรงมาให้ ข้าจะเพิ่มลายตาข่ายเงินกับอะเกตให้แหวน เสริมเวทมนตร์ข้างใน สนใจไหม?" },
        progress = { "96:1786630085:989905084", "มีวัตถุดิบที่ข้าต้องการหรือยัง? ถ้าไม่ได้ครบตามที่ขอ ข้าปรับแบบนี้ให้ดีขึ้นไม่ได้" },
        completion = { "209:1951329776:137146837", "นี่แหวนของเจ้า ดีกว่าเดิม ขอบใจอีกครั้งสำหรับข้อมูลดวอร์ฟ Dark Iron นั่นดูเป็นเบาะแสสมเหตุสมผลว่าเหตุใดจู่ ๆ พวกโนมจึงได้แรงบันดาลใจแบบกอบลิน" },
        required = { [9362] = { "19:876421917:394488771", "แหวนทองคำแวววาว" }, [2842] = { "10:1293727786:854722126", "แท่งเงิน" }, [1206] = { "10:1747381559:30372131", "โมราลายมอส" } },
        steps = { { "19:876421917:394488771", "แหวนทองคำแวววาว" }, { "10:1293727786:854722126", "แท่งเงิน" }, { "10:1747381559:30372131", "โมราลายมอส" } },
    },
    [8276] = { -- Taking Back Silithus
        title = { "20:676320677:644628828", "ทวงคืน Silithus" },
        objective = { "58:1940832120:1670680797", "คุยกับ Windcaller Proudhorn ที่ Cenarion Hold ใน Silithus" },
        description = { "491:109815333:137102740", "เหล่ายอดนักรบแห่ง Horde จงฟัง! มีภัยที่เราปล่อยไว้โดยไม่ต่อต้านนานเกินไป แรงสั่นสะเทือนของพื้นดินใกล้รังซิลิธิดทั่ว Azeroth เตือนให้รู้ว่าพวกมันเคลื่อนกำลังจำนวนมากเพื่อเตรียมขยายอาณาเขต\n\nกองกำลัง Cenarion Circle กำลังรวมตัวใน Silithus เพื่อบุกสู้ซิลิธิดก่อนสายเกินไป! เราจะไม่ให้มันย่ำยีดินแดนเราอีก!\n\nนักรบที่พร้อมรบทุกคนจงรายงานตัวต่อ Windcaller Proudhorn ที่ Cenarion Hold! ซิลิธิดจะต้องถูกปราบ!" },
        completion = { "100:752870178:1752425769 C 230:1110158245:1512186270", "ยอดเยี่ยม ผู้สมัครใหม่ตอบรับเสียงเรียกให้รบกับซิลิธิด ยินดีต้อนรับสู่ Cenarion Hold {class} ดีใจที่คำของทูตเราไปถึงวีรบุรุษระดับเจ้า ที่นี่มีโอกาสให้ช่วยมากมาย ข้าคาดว่าอีกไม่นานเจ้าจะพิสูจน์ตนเป็นพันธมิตรที่มีค่าต่อภารกิจเรา" },
    },
    [7926] = { -- The Darkmoon Faire
        title = { "18:1452120556:1355770990", "งาน Darkmoon Faire" },
        objective = { "95:1461682388:369354358", "นำ Free Ticket Voucher ไปส่งให้ Gelvas Grimgate ภายในงาน Darkmoon Faire" },
        description = { "346:1842736222:396752386", "Darkmoon Faire กำลังมา! อย่าลืมสัมผัสสิ่งมหัศจรรย์และความตื่นเต้นทั้งหมดเมื่องานมาถึงเมือง!\n\nหากไปตอนนี้ เจ้าใช้ใบแลกนี้รับตั๋วรางวัลฟรีได้! เพียงมอบให้ Gelvas Grimgate ภายในงาน\n\nตอนนี้งานอยู่ด้านนอก Thunder Bluff ใน Mulgore อย่าพลาด! ไปวันนี้เลย!" },
        progress = { "71:459068297:339315007", "ว่าอย่างไรสหาย มีอะไรให้ช่วย? มีใบแลกที่ต้องการใช้หรือ?" },
        completion = { "253:942363679:2052734256", "ยินดีต้อนรับสู่ Darkmoon Faire! ใบแลกนี้รับตั๋วรางวัลได้ห้าใบ ใช่แล้ว ห้าใบ!\n\nเมื่อสะสมตั๋วรางวัลแล้ว ให้มาคุยกับข้าเรื่องแลกของมีค่า ยิ่งมีตั๋วมาก ก็ยิ่งรับรางวัลได้มาก ไชโย!" },
        required = { [19338] = { "19:1214859949:1816878322", "คูปองแลกตั๋วฟรี" } },
        steps = { { "19:1214859949:1816878322", "คูปองแลกตั๋วฟรี" } },
    },
    [8913] = { -- An Earnest Proposition
        title = { "22:1183475074:147978204", "ข้อเสนอที่จริงใจ" },
        objective = { "122:1672040691:275176521", "หา Silithus Venom Samples 15 ชิ้น และเงิน 20 ทอง แล้วนำไปพร้อม Wildheart Bracers ให้ Mokvar ที่ Orgrimmar" },
        description = { "6:1136836709:1914036474 C 423:287029186:1488951061", "สวัสดี {class}! ท่าทีบอกว่าเจ้าพบเห็นและทำสิ่งต่าง ๆ ในโลกมามาก แต่ข้ากล้าพนันว่ายังไม่เคยเห็นเกราะเช่นนี้\n\nช่วยธุระเล็กน้อย แล้วข้าจะยอมแลกกับปลอกรัดแขนธรรมดาของเจ้า\n\nข้าต้องการตัวอย่างพิษจำนวนมากพอจากแมงมุมกับแมงป่องใน Silithus นำมาให้พร้อมเหรียญทองเล็กน้อย แล้วข้าจะแลกให้" },
        progress = { "39:292799259:1437363122 N 1:63:63", "ได้ไอเทมที่ข้าต้องการหรือยัง {name}?" },
        completion = { "208:344574223:2051793325", "อา ใช่ Mux จะพอใจมาก\n\nปลอกรัดแขนนั้นเป็นส่วนหนึ่งของชุดเกราะใหญ่ หากสนใจช่วยข้าต่อ ข้าอาจพิจารณามอบส่วนที่เหลือให้" },
