    [8957] = { -- Anthion's Parting Words
        title = { "23:573656928:1309079977", "คำอำลาของ Anthion" },
        objective = { "105:843878935:1177516525", "กลับไปหา Mokvar ที่ Orgrimmar พร้อม รองเท้าบูตแห่งธาตุ, กระโปรงเกราะแห่งธาตุ และ เกราะไหล่แห่งธาตุ" },
        description = { "454:1366191329:981737942", "วิญญาณของ Valthalak ถูกเก็บอยู่ในเครื่องรางนี้ ด้วยความโลภ เราโง่เขลาแบ่งมันเป็นสามส่วน โดยไม่รู้คำสาปที่รออยู่\n\nหนทางเดียวที่จะหยุดคาถาของ Valthalak คือประกอบเครื่องรางกลับเข้าด้วยกัน กลับไปบอก Mokvar ว่า Bodley เป็นความหวังเดียวที่จะหาส่วนที่เหลือได้ คุยกับเขาเรื่องรางวัลที่ตกลงกันไว้ด้วย\n\nคราวนี้ข้าจะได้พักอย่างสงบ ขอให้เจ้าโชคดีที่สุด เพราะเจ้าจะต้องใช้โชคทั้งหมดที่มี!" },
        progress = { "13:1761969110:399778402 N 93:1800554215:1475646531", "กลับมาแล้ว {name} ต้องเล่าทุกสิ่งที่ค้นพบให้ข้าฟัง แต่ก่อนอื่นมาจัดการรางวัลของเจ้าก่อน" },
        completion = { "190:1310137436:1966522662", "ไม่อยากเชื่อว่าชีวิตพวกเราแทบจะต้องสูญสิ้นเพราะเหรียญงี่เง่าชิ้นเดียว! และเจ้าแน่ใจว่า Anthion เอ่ยถึง Bodley?\n\nเอาล่ะ เจ้าทำงานสำเร็จแล้ว มาจัดการเรื่องรางวัลกันให้เรียบร้อย" },
        required = { [16670] = { "17:2137193873:1530208696", "รองเท้าบูตแห่งธาตุ" }, [16668] = { "16:1794528290:1974409132", "กระโปรงเกราะแห่งธาตุ" }, [16669] = { "21:1402688556:413531712", "เกราะไหล่แห่งธาตุ" } },
        objectiveLabels = {
            item = { ["Boots of Elements"] = "รองเท้าบูตแห่งธาตุ", ["Kilt of Elements"] = "กระโปรงเกราะแห่งธาตุ", ["Pauldrons of Elements"] = "เกราะไหล่แห่งธาตุ" },
        },
    },
    [8978] = { -- Return to Mokvar
        title = { "16:704225018:2028211703", "กลับไปหา Mokvar" },
        objective = { "72:1598709243:800418904", "กลับไปหา Mokvar ที่ Orgrimmar พร้อม Extra-Dimensional Ghost Revealer" },
        description = { "34:1195322377:1109795208 N 167:1674110699:513019215", "ได้ร่วมงานกับเจ้าดีมาก {name} นี่ชิ้นงานที่เสร็จแล้ว\n\nหวังว่ามันจะช่วยงานที่เจ้ากำลังทำ และถ้าไม่รบกวน ช่วยบอกต่อด้วย ข้าไม่รังเกียจที่จะมีลูกค้าเพิ่ม!" },
        progress = { "32:258780485:998253693", "กลับมาพร้อมอุปกรณ์แล้วหรือ?" },
        completion = { "67:1408966436:1043233584 N 17:422294901:1766786651", "เจ้ากลับมาพร้อมอุปกรณ์! ข้าประทับใจความทุ่มเท {name} ทำได้ยอดเยี่ยม" },
    },
    [8998] = { -- Back to the Beginning
        title = { "21:1461300965:1905746562", "กลับสู่จุดเริ่มต้น" },
        objective = { "67:1190471164:1619542405", "คุยกับ Mokvar ที่ Grommash Hold ใน Valley of Wisdom ของ Orgrimmar" },
        description = { "328:123432835:701154964", "คงถึงเวลาลาแล้วสินะ สหาย แต่ข้าจะอยู่ที่นี่เสมอ หากเจ้าอยากแวะมาคุยเป็นครั้งคราว อาจเป็นตอนเดินเตร่รอเพื่อนมาร่วมบุก Blackrock Spire\n\nไปเถอะ ก่อนข้าจะร้องไห้ กลับไปหา Mokvar ที่ Orgrimmar แล้วบอกเขาว่าเกิดอะไรขึ้น" },
        completion = { "44:632921438:1102814507 N 86:816443347:1157499727", "ข้าดีใจที่เจ้ารอดมา {name} ดูแข็งแรงดี และอาจเจนสนามขึ้นอีกหน่อย\n\nมา เล่าทุกอย่างที่เกิดขึ้นให้ข้าฟัง" },
    },
