    [9016] = { -- Anthion's Parting Words
        title = { "23:573656928:1309079977", "คำอำลาของ Anthion" },
        objective = { "101:2129334400:967792802", "กลับไปหา Mokvar ที่ Orgimmar พร้อม Wildheart Boots, Wildheart Kilt และ Wildheart Spaulders" },
        description = { "454:1366191329:981737942", "วิญญาณของ Valthalak ถูกเก็บอยู่ในเครื่องรางนี้ ด้วยความโลภ เราโง่เขลาแบ่งมันเป็นสามส่วน โดยไม่รู้คำสาปที่รออยู่\n\nหนทางเดียวที่จะหยุดคาถาของ Valthalak คือประกอบเครื่องรางกลับเข้าด้วยกัน กลับไปบอก Mokvar ว่า Bodley เป็นความหวังเดียวที่จะหาส่วนที่เหลือได้ คุยกับเขาเรื่องรางวัลที่ตกลงกันไว้ด้วย\n\nคราวนี้ข้าจะได้พักอย่างสงบ ขอให้เจ้าโชคดีที่สุด เพราะเจ้าจะต้องใช้โชคทั้งหมดที่มี!" },
        progress = { "68:1289344252:1339787041 N 40:280573826:1697604824", "เจ้ากลับมา และข้าเห็นในตาว่ามีเรื่องมากมายอยากเล่า {name} มาจัดการรางวัลก่อน" },
        completion = { "247:1689309257:803644258", "เราถูกสาปเพราะเหรียญชิ้นเดียว Lord Valthalak รู้จักผูกใจเจ็บจริง ๆ\n\nเราจะพยายามหาส่วนที่เหลือ หวังว่าก่อนข้าจะตายก่อนเวลาอันควร แต่ก่อนอื่น มาดูรางวัลของเจ้า" },
        required = { [16715] = { "15:216658111:910753435", "รองเท้าบูตแห่งหัวใจพงไพร" }, [16719] = { "14:1105797594:1961456342", "กระโปรงคิลต์แห่งหัวใจพงไพร" }, [16718] = { "19:480658180:2108834782", "เกราะไหล่แห่งหัวใจพงไพร" } },
        objectiveLabels = {
            item = { ["Wildheart Boots"] = "รองเท้าบูตแห่งหัวใจพงไพร", ["Wildheart Kilt"] = "กระโปรงคิลต์แห่งหัวใจพงไพร", ["Wildheart Spaulders"] = "เกราะไหล่แห่งหัวใจพงไพร" },
