    [8367] = { -- For Great Honor
        title = { "15:170467736:237098528", "เพื่อเกียรติยิ่งใหญ่" },
        objective = { "152:1318261250:1126469430", "นำ Alterac Valley Marks of Honor 3 ชิ้น, Arathi Basin Marks of Honor 3 ชิ้น และ Warsong Gulch Marks of Honor 3 ชิ้น ไปให้ Horde Warbringer ที่อยู่นอกสนามรบ", variants = { { "189:980040641:587194858", "นำ Alterac Valley Marks of Honor 3 ชิ้น, Arathi Basin Marks of Honor 3 ชิ้น, Warsong Gulch Marks of Honor 3 ชิ้น และ Darkspear Islands Marks of Honor 3 ชิ้น ไปให้ Horde Warbringer ที่อยู่นอกสนามรบ" } } },
        description = { "419:1422573838:117906562", "การรับใช้ Horde ในศึกใหญ่กับ Alliance เป็นเกียรติยิ่ง! แต่ผู้ที่รับใช้ในทุกแนวรบที่เปิดอยู่ต่างหากคือนักสู้ยิ่งใหญ่แท้จริง เราจะพิชิตศัตรูด้วยสงครามที่ประสานกันดี ไม่ใช่รบย่อยแยกกัน\n\nออกไปบดขยี้ Alliance ใน Arathi Basin, Alterac Valley และ Warsong Gulch! เพื่อเกียรติ! เพื่อ Horde!" },
        progress = { "166:240875487:1499585966", "Arathi ยังชุ่มเลือดนักรบผู้ยิ่งใหญ่ และเสียงเหล็กกระทบยังดังก้องทั่ว Alterac อย่าทำข้าเสียเวลา เว้นแต่นำข่าวจากแนวรบมา!" },
        completion = { "134:498337704:428168670 C 71:1508681851:1434431257 N 58:257873217:1569682291", "บททดสอบไม่ง่าย แต่เจ้าไม่สูญความกล้าและกำลังไม่ถดถอย จงมอบเครื่องหมายชัยชนะในอดีตมา {class} ไม่มีใครต้องใช้มันย้ำคุณค่าของเจ้า ยืนตัวตรง {name} วันนี้เจ้าจะเดินด้วยความภาคภูมิ เพราะเจ้าคือวีรบุรุษ!" },
        required = { [20558] = { "27:1151639554:183227099", "เหรียญเกียรติยศ Warsong Gulch" }, [20559] = { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" }, [20560] = { "28:1124473597:1604635920", "เหรียญเกียรติยศ Alterac Valley" }, [274895] = { "31:832704024:1368023717", "ตราเกียรติยศ Darkspear Islands" } },
        objectiveLabels = {
            item = { ["Warsong Gulch Mark of Honor"] = "เหรียญเกียรติยศ Warsong Gulch", ["Arathi Basin Mark of Honor"] = "เหรียญเกียรติยศ Arathi Basin", ["Alterac Valley Mark of Honor"] = "เหรียญเกียรติยศ Alterac Valley", ["Darkspear Islands Mark of Honor"] = "ตราเกียรติยศ Darkspear Islands" },
        },
    },
