    [93739] = { -- Exploring the Horde
        title = { "19:196631471:1355722997", "สำรวจ Horde" },
        objective = { "180:619765866:2029845531", "คุยกับ Nazgrel ที่ Grommash Hold เพื่อรับคำแนะนำเพิ่มเติม ใช้คำแนะนำนั้นตามหาและคุยกับ Vol'jin, Cairne Bloodhoof และ Lady Sylvanas Windrunner" },
        description = { "317:1864411776:859945791", "Azeroth เป็นโลกกว้างใหญ่ และอาณาเขต Horde ก็ไพศาล Undercity, Orgrimmar และ Thunder Bluff ต่างมีผู้คนกับวัฒนธรรมเฉพาะตัว\n\nหากเจ้าจะเป็นแขกของ Horde บน Azeroth การไปเยือนนครหลวงแต่ละแห่งย่อมเป็นประโยชน์ คุยกับ Nazgrel ที่ปรึกษาข้าเพื่อขอคำแนะนำ", variants = { { "317:95996782:1705102452", "Azeroth เป็นโลกกว้างใหญ่ และอาณาเขต Horde ก็ไพศาล Undercity, Orgrimmar และ Thunder Bluff ต่างมีผู้คนกับวัฒนธรรมเฉพาะตัว\n\nหากเจ้าจะเป็นแขกของ Horde บน Azeroth การไปเยือนนครหลวงแต่ละแห่งย่อมเป็นประโยชน์ คุยกับ Nazgrel ที่ปรึกษาข้าเพื่อขอคำแนะนำ" } } },
        completion = { "319:70740250:727943415", "กลับมาแล้วสินะ หวังว่าเจ้าได้เรียนรู้มากจากการเดินทาง\n\nเท่าที่ข้ารู้ ผู้คนของเจ้ายังตั้งหลักใน Mulgore ระหว่างรอ ข้าสนับสนุนให้สำรวจอาณาเขตรอบ Orgrimmar โดยเฉพาะ Barrens ที่ต้องการนักผจญภัยกระตือรือร้นเช่นเจ้าเสมอ" },
        progress = { "9:1871511191:798375331 N 1:46:46", "Lok-tar, {name}" },
        steps = { { "32:430632272:1747960253", "รับคำสั่งจาก Nazgrel" }, { "18:786567876:543169345", "คุยกับ Vol'jin" }, { "27:1268260794:284767744", "คุยกับ Cairne Bloodhoof" }, { "35:1851704840:1078134578", "คุยกับ Lady Sylvanas Windrunner" } },
    },
    [97242] = { -- Yelmak's Medley
        title = { "15:1981342937:1267356092", "ส่วนผสมของ Yelmak" },
        objective = { "160:1509002996:496189692", "ตัดกิ่งใบจาก Cattails และ Speargrass ที่ขึ้นรอบทางน้ำใน Valley of Honor แล้วกลับไปหา Kor'geld ที่ Yelmak's Alchemy and Potions", variants = { { "161:1266713558:576340828", "ตัดกิ่งใบจาก Cattails และ Speargrass ที่ขึ้นรอบทางน้ำใน Valley of Honor แล้วกลับไปหา Kor'geld ที่ Yelmak's Alchemy and Potions" } } },
        description = { "478:1133100482:1226535809", "Yelmak ไม่อยากให้เด็กฝึกงานทำอะไรแตกอีก อย่างน้อยก็ไม่ให้มากกว่าที่ทำไปแล้ว\n\nเขาบอกว่านักผสมฝึกหัดหนุ่มหยิ่งเกินจะขอความช่วยเหลือเมื่อจำเป็น Yelmak อยากให้เขาลองชิมยาสูตรทำเองบางอย่าง\n\nเก็บกิ่งใบ cattail กับ speargrass จากต้นที่ขึ้นรอบน้ำใน Valley of Honor มาผสมกัน ข้าจะไปเอง แต่ถ้าออกจากร้าน Whuut ต้องรู้ว่าเรากำลังเอาใจตามอารมณ์เขาแน่" },
        progress = { "126:38684536:1560965146", "เราค้นพบสูตรผสมโดยนำส่วนผสมเก่าให้คนรุ่นใหม่รู้จัก แล้วพวกเขาก็ทดลองในแบบของตน", variants = { { "124:1645652242:895916498", "เราค้นพบสูตรผสมโดยนำส่วนผสมเก่าให้คนรุ่นใหม่รู้จัก แล้วพวกเขาก็ทดลองในแบบของตน" } } },
        completion = { "320:2145099173:104908870", "Cattail กับ speargrass ชนิดนี้พบเฉพาะ Orgrimmar มันดื่มน้ำพุภูเขาจาก Azshara และรับแร่ธาตุจากฝุ่นหินบนแผ่นดินที่ชุ่มเหงื่อและเลือด จึงมีพลังเข้มข้นซ่อนอยู่ภายใน\n\nข้าจะมอบให้ Yelmak เขาอาจทำให้ Whuut ยอมฟังอีกครั้งด้วยบทเรียนลงมือทำ" },
        required = { [277278] = { "19:1164906593:1880645155", "ต้นธูปฤาษีหนึ่งกำมือ" }, [277279] = { "19:225189550:316502703", "กิ่งพันธุ์หญ้า Speargrass" } },
        steps = { { "19:1164906593:1880645155", "ต้นธูปฤาษีหนึ่งกำมือ" }, { "19:225189550:316502703", "กิ่งพันธุ์หญ้า Speargrass" } },
    },
    [97246] = { -- Meal Appeal
        title = { "11:142547974:2041017554", "มื้ออาหารชวนกิน" },
        objective = { "96:1144877765:1115777469", "ไปที่ Borstan's Firepit แล้วบอกเขาว่า Thatog ต้องการให้เจ้านำอาหารกลางวันของ Migi ไปส่งให้เจ้าตัวโดยตรง" },
        description = { "489:777071698:2099692798", "Migi ลูกชายข้ามักออกไปเล่นกับเพื่อนทั้งวัน ข้าบอกให้แวะรับอาหารกลางวันที่ Borstan's แต่รู้ว่าแทบไม่ไป เพราะกลับบ้านมาหิวโซ เด็กพวกนี้คิดว่าเกมสำคัญกว่าร่างกายตัวเอง!\n\nโปรดแวะ Borstan's Firepit แล้วบอกว่ามาส่งอาหารกลางวันให้ Migi เจ้าคงพบเขาด้านหลัง Grommash Hold กับเพื่อน ๆ\n\nหน้าที่ทำให้ข้าต้องอยู่ที่นี่กลางวัน คอยดูเขาทุกมื้อไม่ได้" },
        completion = { "295:1737214244:748528767", "ได้เลย พ่อแม่ Migi ตกลงกับข้าให้จัดอาหารกลางวันใส่ถุงให้ทุกวัน แต่ข้ารับรองว่าเด็กได้กินได้ก็ต่อเมื่อเขามารับจริง ๆ\n\nบางสัปดาห์เขาไม่มารับหลายวัน ข้าสงสัยว่าเอาแรงที่ไหนไปเล่นข้างนอก" },
    },
    [97249] = { -- Favorite Food
        title = { "13:1835151660:686990809", "อาหารจานโปรด" },
        objective = { "46:1250762780:1063565169", "นำ Migi's Lunch ไปให้เขาด้านหลัง Grommash Hold", variants = { { "47:1470971103:1888084929", "นำ Migi's Lunch ไปให้เขาด้านหลัง Grommash Hold" } } },
        description = { "493:129002947:913981656", "ตอนนี้รู้แล้วว่าพ่อแม่ห่วงว่าเขากินอิ่มจริงแค่ไหน ข้าจึงมีความคิด\n\nพวกเขาให้ข้าสัญญาว่าจะไม่จัดอาหารเหมือนเดิมทุกวัน เพื่อให้ Migi รู้จักชอบหลายอย่าง แต่ทุกครั้งที่เตารมควันเต็มและเราทำแซนด์วิชหมูสามชั้นเคลือบหวาน เขาจะมารับอาหารเสมอ เราเริ่มบดเศษเคลือบกรอบที่เหลือไว้โรยหน้า เป็นสิ่งที่เติมได้ทุกวัน\n\nนำไปให้เขา บางทีเขาจะเริ่มมาเร็วและพาเพื่อนมาด้วย!" },
        progress = { "30:1407425003:923317926", "ข้าว่าเราชนะรอบนี้ได้..." },
        completion = { "447:1190938492:2016549214", "Borstan's Meats หรือ? ของใครในพวกเราหรือเปล่า?\n\nโอ้!\n\nว้าว... หอมมาก! น่าอร่อย\n\nขอบใจที่นำอาหารกลางวันมาให้ แค่ได้กลิ่นตอนเดินไป Grommash Hold กับเพื่อน ข้าก็รู้ว่าแต่ละวัน Borstan จะขายอะไร นี่รสเหมือนของโปรด เคลือบหวาน! แต่ต่างออกไป ข้าชอบเศษโรยรสเข้มพวกนี้\n\nถ้าทุกวันอร่อยแบบนี้ ข้าว่าเราต้องหยุดเกมมานั่งกินกลางวันด้วยกันแล้ว!", variants = { { "447:84003003:2049299079", "Borstan's Meats หรือ? ของใครในพวกเราหรือเปล่า?\n\nโอ้!\n\nว้าว... หอมมาก! น่าอร่อย\n\nขอบใจที่นำอาหารกลางวันมาให้ แค่ได้กลิ่นตอนเดินไป Grommash Hold กับเพื่อน ข้าก็รู้ว่าแต่ละวัน Borstan จะขายอะไร นี่รสเหมือนของโปรด เคลือบหวาน! แต่ต่างออกไป ข้าชอบเศษโรยรสเข้มพวกนี้\n\nถ้าทุกวันอร่อยแบบนี้ ข้าว่าเราต้องหยุดเกมมานั่งกินกลางวันด้วยกันแล้ว!" }, { "447:1424865928:1313279941", "Borstan's Meats หรือ? ของใครในพวกเราหรือเปล่า?\n\nโอ้!\n\nว้าว... หอมมาก! น่าอร่อย\n\nขอบใจที่นำอาหารกลางวันมาให้ แค่ได้กลิ่นตอนเดินไป Grommash Hold กับเพื่อน ข้าก็รู้ว่าแต่ละวัน Borstan จะขายอะไร นี่รสเหมือนของโปรด เคลือบหวาน! แต่ต่างออกไป ข้าชอบเศษโรยรสเข้มพวกนี้\n\nถ้าทุกวันอร่อยแบบนี้ ข้าว่าเราต้องหยุดเกมมานั่งกินกลางวันด้วยกันแล้ว!" } } },
        required = { [277284] = { "12:1314326336:275832068", "มื้อกลางวันของ Migi" } },
        steps = { { "12:1314326336:275832068", "มื้อกลางวันของ Migi" } },
    },
    [97275] = { -- Whuut's the Rush
        title = { "16:825764671:241309563", "Whuut จะรีบไปไหน" },
        objective = { "30:1177770583:64712062", "มอบ Yelmak's Potion ให้ Whuut" },
        description = { "474:71159316:1411976490", "Whuut เป็นอัจฉริยะ จริงอย่างนั้น แต่ยังขาดประสบการณ์ ปัญญา และชั่วโมงจับไม้คน จึงไม่รู้จักเคารพกระบวนการเล่นแร่แปรธาตุ\n\nเขาใช้วัตถุดิบหายากและแปลกถิ่นที่สุดของเราจนหมด โดยไม่หยุดฝึกฝนทักษะพื้นฐานให้ดีขึ้น\n\nนำยาที่ข้าปรุงด้วยวิธีทำโทนิกอย่างรวดเร็วนี้ให้เขา เมื่อรู้ว่าวิธีพื้นบ้านกับความละเอียดอ่อนคือความเชี่ยวชาญแท้จริงขั้นแรก เขาจะทบทวนทุกอย่างที่ทำ" },
        progress = { "59:1269897772:1957194472", "เอาล่ะ ต่อไปอะไร... Black Lotus, Mountain Silversage..." },
        completion = { { "417:49033712:1681597835", "299:2053316935:1438650987 N 112:1509785143:827464594", "299:2053316935:1438650987 C 112:1509785143:827464594", "299:2053316935:1438650987 R 112:1509785143:827464594" }, "กรอร์รู... หา?\n\nเจ้าว่า Yelmak ทำยานี้จาก speargrass กับ cattail โดยไม่มีวัตถุดิบอื่นหรือ? ข้าไม่รู้ว่านักปรุงยาต้องใช้พืชธรรมดาที่เห็นทุกวันพวกนี้จริง ๆ\n\nบางทีเขาพูดถูก ข้าอาจพลาดอะไรไปมาก เมื่อข้ามไปเริ่มที่พืชหายากที่สุดและมีคนศึกษาน้อยที่สุด\n\nสหาย เลือกยาที่ข้าปรุงไว้ก่อนหน้านี้สักขวด ข้าซาบซึ้งที่สละเวลามาเยือนร้านเรา" },
        required = { [277566] = { "15:1285576229:1875143932", "ยาของ Yelmak" } },
        objectiveLabels = {
            item = { ["Yelmak's Potion"] = "ยาของ Yelmak" },
        },
    },
    [97326] = { -- Rocks to Rests
        title = { "14:1129321471:667667184", "ก้อนหินสำหรับพัก" },
        objective = { "54:628482676:433159714", "นำ Smooth Boulders 8 ก้อน กลับไปให้ Thra ด้านหลัง Grommash Hold", amount = { "7:754587951:547508582 W1 46:1176270503:1545099646", "นำ Smooth Boulders {world1} ก้อน กลับไปให้ Thra ด้านหลัง Grommash Hold" } },
        description = { "405:265685381:1878248131", "นี่! เจ้าพอมีเวลาช่วยเรา! ข้ารู้น่า ดูจากที่ยิ้มตอนมองเกมที่เราเล่นก็รู้แล้ว\n\nตรงหลัง Grommash Hold นี่ดีเพราะโล่งพอให้ตั้งตัวหมาก แต่แย่ที่มีหินทำเก้าอี้หรือโต๊ะไม่พอ\n\nเจ้าตัวใหญ่แข็งแรง... ช่วยแบกหินขนาดกลางที่เรียบพอให้นั่งพักได้กลับมาหน่อยไหม?", variants = { { "405:1334931079:61136370", "นี่! เจ้าพอมีเวลาช่วยเรา! ข้ารู้น่า ดูจากที่ยิ้มตอนมองเกมที่เราเล่นก็รู้แล้ว\n\nตรงหลัง Grommash Hold นี่ดีเพราะโล่งพอให้ตั้งตัวหมาก แต่แย่ที่มีหินทำเก้าอี้หรือโต๊ะไม่พอ\n\nเจ้าตัวใหญ่แข็งแรง... ช่วยแบกหินขนาดกลางที่เรียบพอให้นั่งพักได้กลับมาหน่อยไหม?" } } },
        progress = { "48:1769251701:336813492", "ดีจังที่ไม่ต้องนั่งดินตลอด!" },
        completion = { "226:1072923585:398889849", "เจ้าแบกหินพวกนั้นหมดได้อย่างไร!\n\nดีมาก ส่วนใหญ่ยังมีด้านแบนเรียบด้วย เมื่อเจ้าแบกมาถึงนี่ เราก็เลื่อนไปบนดินให้อยู่ตรงที่ต้องการได้\n\nขอบใจสหาย!", variants = { { "219:230131055:1046445845 N 1:33:33", "เจ้าแบกหินพวกนั้นหมดได้อย่างไร!\n\nดีมาก ส่วนใหญ่ยังมีด้านแบนเรียบด้วย เมื่อเจ้าแบกมาถึงนี่ เราก็เลื่อนไปบนดินให้อยู่ตรงที่ต้องการได้\n\nขอบใจ {name}!" } } },
        required = { [277952] = { "14:687233650:1423511986", "ก้อนหินผิวเรียบ" } },
        steps = { { "14:687233650:1423511986", "ก้อนหินผิวเรียบ" } },
    },
    [3804] = { -- Morrowgrain to Thunder Bluff
        title = { "28:1269612767:1739748207", "Morrowgrain สู่ Thunder Bluff" },
        progress = { "275:1168723032:797905794", "อัครดรูอิดต้องการ morrowgrain เพิ่มให้งานวิจัย Un'Goro Crater ของ Cenarion Circle เสมอ เรารับครั้งละสิบชิ้น แล้วตอบแทนด้วยห่อของที่น่าจะมีประโยชน์ เมื่อมีสิบชิ้นแจ้งข้า จะให้รางวัลตามนั้น" },
        completion = { "369:1384695948:1050283780 N 60:2019879359:1717107802", "ยอดเยี่ยม morrowgrain นี้จะช่วยได้เมื่อถึงเวลา เรารู้ว่าไนต์เอลฟ์ก็วิจัยสมุนไพรนี้คล้ายกัน แต่ยังไม่ชัดว่าจะนำผลค้นพบไปใช้อย่างไร อัครดรูอิดคิดว่าความต้องการ morrowgrain จะยังมีจนกว่าเราไขปริศนาสมุนไพรนี้ได้\n\nนี่สำหรับเจ้า {name} Cenarion Circle ขอบใจที่สนับสนุนอย่างต่อเนื่อง" },
        description = { "275:1168723032:797905794", "อัครดรูอิดต้องการ morrowgrain เพิ่มให้งานวิจัย Un'Goro Crater ของ Cenarion Circle เสมอ เรารับครั้งละสิบชิ้น แล้วตอบแทนด้วยห่อของที่น่าจะมีประโยชน์ เมื่อมีสิบชิ้นแจ้งข้า จะให้รางวัลตามนั้น" },
        required = { [11040] = { "11:35561619:35128800", "มอร์โรว์เกรน" } },
        objectiveLabels = {
            item = { ["Morrowgrain"] = "มอร์โรว์เกรน" },
        },
    },
    [5728] = { -- Hidden Enemies
        title = { "14:1095003067:1533520320", "ศัตรูที่ซ่อนอยู่" },
        objective = { "78:167692966:97420410", "ฆ่า Bazzalan และ Jergosh the Invoker ก่อนกลับไปหา Thrall ที่ Orgrimmar" },
        description = { { "292:1470566244:1907191059 N 185:1202094966:1011742779", "292:1470566244:1907191059 N 184:1120527758:1573710724" }, "อืม ผู้นำ Searing Blade... ข้ากังวลเรื่องนี้ที่สุด หากพวกเขามีค่าต่อ Neeru เราก็ต้องเล็งเป้าพวกเขาก่อน ซาเทอร์ Bazzalan กับอีกคนที่ Neeru เอ่ยถึง เป็นอะไรนะ วอร์ล็อกหรือ? ต้องถูกฆ่า\n\nกลับ Cleft of Shadow แล้วเข้า Ragefire Chasm {name} หาผู้นำ Searing Blade สองคนแล้วฆ่า แต่ระวังอย่าให้ Neeru รู้ว่าเจ้าลงมือ ต้องรักษาตัวตนเป็นสหายร่วมรบของเขาไว้", variants = { { "292:1470566244:1907191059 N 185:1202094966:1011742779", "อืม ผู้นำ Searing Blade... ข้ากังวลเรื่องนี้ที่สุด หากพวกเขามีค่าต่อ Neeru เราก็ต้องเล็งเป้าพวกเขาก่อน ซาเทอร์ Bazzalan กับอีกคนที่ Neeru เอ่ยถึง เป็นอะไรนะ วอร์ล็อกหรือ? ต้องถูกฆ่า\n\nกลับ Cleft of Shadow แล้วเข้า Ragefire Chasm {name} หาผู้นำ Searing Blade สองคนแล้วฆ่า แต่ระวังอย่าให้ Neeru รู้ว่าเจ้าลงมือ ต้องรักษาตัวตนเป็นสหายร่วมรบของเขาไว้" } } },
        progress = { "25:1969982042:676191056 N 365:1238210764:1795062368", "พบพวกเขาหรือยัง {name}? ผู้นำ Searing Blade\n\nข้ารู้ว่า Shadow Council อยากแย่ง Orgrimmar กับ Horde ทั้งหมดไป แต่ไม่คิดว่าจะแทรกซึมเมืองได้เร็วเช่นนี้ อสูรร้ายนี้มีแขนมากนัก ตัดจนหมดแรงก็ยังไม่คืบจากจุดเริ่มต้น ข้าต้องให้สายลับเพิ่มความพยายามเป็นสองเท่า" },
        completion = { "27:1539523209:1774979765 N 300:831819515:1656261338", "ดีใจที่เจ้ากลับมา {name} ผู้ภักดีบางคนนำข่าวมาทันทีว่าถ้ำใต้ Orgrimmar โกลาหลเมื่อผู้นำถูกฆ่า ถึงกับมีรายงานว่า Neeru ร้อนใจอย่างหนัก ดูเหมือนเราเจาะเกราะเขาได้ ข้าพอใจทีเดียว... แม้เป็นชัยชนะเล็กน้อย" },
        objectiveLabels = {
            monster = { ["Bazzalan slain"] = "ปราบ Bazzalan", ["Jergosh the Invoker slain"] = "ปราบ Jergosh ผู้อัญเชิญ" },
        },
    },
    [98024] = { -- Journey to the Crossroads
        title = { "25:377641842:1261476287", "เดินทางสู่ Crossroads" },
        objective = { "49:1258472970:662995882", "รายงานตัวต่อ Thork ที่ The Crossroads ใน The Barrens" },
        description = { "456:716522097:859242782", "เมื่อเดินทางมาจากมิติธาตุ ปัญหาในแผ่นดินเราอาจดูเล็กน้อย แต่จงมั่นใจ ภัยที่ Horde เผชิญเป็นจริง หากรอดจากการรับใช้ เจ้าจะเติบโตแข็งแกร่ง\n\nถ้าอยากเริ่มทำความดีในโลกเรา เดินทางตะวันตกเฉียงใต้สู่ Barrens อันกว้างใหญ่ ที่นั่นมีชุมชนชื่อ Crossroads ประชาชนผู้ภาคภูมิต้องการความช่วยเหลือเสมอ\n\nจงไปอย่างมีเกียรติ นักผจญภัย!" },
        completion = { "259:1827199898:1231793879", "อะไรกันนี่? เอลฟ์หรือ? แล้วเจ้าว่า Warchief ส่งเจ้ามาอย่างนั้นหรือ?\n\n<Thork ส่งเสียงฮึ่มพลางมองเจ้าตั้งแต่หัวจรดเท้า>\n\nข้าว่าเจ้าดูผอมไปหน่อย แต่ช่างเถอะ ที่นี่เจ้าต้องตั้งหลักให้ได้และเอาชีวิตรอด ไม่อย่างนั้นก็ตาย ดินแดนแถบนี้เป็นอย่างนั้นแหละ" },
    },
    [854] = { -- Journey to the Crossroads
        title = { "25:377641842:1261476287", "เดินทางสู่ Crossroads" },
        objective = { "50:1456559882:1257281305", "คุยกับ Thork ที่ Crossroads ใน Barrens" },
        description = { "36:1687202844:1241049181 C 428:1625534312:1171673706", "ข้าเห็นล่วงหน้าแล้วว่าเจ้าจะมา {class} รุ่นเยาว์ แม้เจ้าอาจไม่เยาว์นักแล้ว\n\nข้าคิดว่าถึงเวลาที่เจ้าจะเดินทางลึกเข้าไปในดินแดนนี้ ข้าสัมผัสได้ว่าเจ้ามีชะตาที่ยิ่งใหญ่\n\nเจ้าต้องไปครอสโรดส์ ชีวิตของเรากับพวกออร์คผูกพันกันแล้ว และพวกเขาต้องการความช่วยเหลือ เดินไปตามถนนสายนี้ทางตะวันออก แล้วตามทางขึ้นเหนือสู่ครอสโรดส์ ตามหาธอร์กในกำแพงเมือง เขาได้รับพรจากพระแม่ธรณี" },
        completion = { "35:567113739:1740350562 R 87:1211838852:1278418493", "ดีที่เห็นพันธมิตรชาว{race} เดินทางมาไกลจากธันเดอร์บลัฟฟ์เพื่อช่วยเราอีก ข้าขอต้อนรับเจ้าอีกครั้ง" },
    },
    [3762] = { -- Assisting Arch Druid Runetotem
        title = { "30:1211130143:400228049", "ช่วยอัครดรูอิด Runetotem" },
        objective = { "56:1558032120:1164794554", "คุยกับ Arch Druid Hamuul Runetotem ที่ Thunder Bluff" },
        description = { "10:1827992962:185023149 C 421:6141590:72571722", "ขอโทษนะ {class} ถ้าเป็นไปได้ ข้าขอเวลาสักครู่\n\nCenarion Circle ที่ Thunder Bluff สนใจให้นักผจญภัยมีประสบการณ์เช่นเจ้าช่วยโครงการวิจัยสำคัญ แม้ข้าไม่รู้รายละเอียด แต่บอกได้ว่าผู้นำงานนี้ไม่ใช่ใครอื่น เป็น Hamuul Runetotem เอง\n\nหากสนใจ โปรดคุยกับเขาโดยตรงบน Elder Rise ในตัวเมือง Thunder Bluff" },
        completion = { "11:927657569:725753248 C 315:1125054124:935911111", "สวัสดี {class} ดีใจที่เจ้าสนใจช่วยงานวิจัยเรา มีงานมากมาย และข้าคงทำไม่ถูกหากบอกว่างานนี้ไม่อันตราย หวังว่าคงไม่ทำให้กลัวจนถอย... แต่ดูจากเจ้า ข้าว่าคงเคยรับมืออันตรายมาแล้ว" },
    },
    [3784] = { -- Assisting Arch Druid Runetotem
        title = { "30:1211130143:400228049", "ช่วยอัครดรูอิด Runetotem" },
        objective = { "56:1558032120:1164794554", "คุยกับ Arch Druid Hamuul Runetotem ที่ Thunder Bluff" },
        description = { "10:1827992962:185023149 C 421:6141590:72571722", "ขอโทษนะ {class} ถ้าเป็นไปได้ ข้าขอเวลาสักครู่\n\nCenarion Circle ที่ Thunder Bluff สนใจให้นักผจญภัยมีประสบการณ์เช่นเจ้าช่วยโครงการวิจัยสำคัญ แม้ข้าไม่รู้รายละเอียด แต่บอกได้ว่าผู้นำงานนี้ไม่ใช่ใครอื่น เป็น Hamuul Runetotem เอง\n\nหากสนใจ โปรดคุยกับเขาโดยตรงบน Elder Rise ในตัวเมือง Thunder Bluff" },
        completion = { "11:927657569:725753248 C 315:1125054124:935911111", "สวัสดี {class} ดีใจที่เจ้าสนใจช่วยงานวิจัยเรา มีงานมากมาย และข้าคงทำไม่ถูกหากบอกว่างานนี้ไม่อันตราย หวังว่าคงไม่ทำให้กลัวจนถอย... แต่ดูจากเจ้า ข้าว่าคงเคยรับมืออันตรายมาแล้ว" },
    },
    [232] = { -- Errand for Apothecary Zinge
        title = { "27:500422077:81973516", "ธุระให้ Apothecary Zinge" },
        objective = { "60:1915362460:274350131", "นำใบสั่งซื้อไปให้ Alessandro Luca ที่ Undercity" },
        description = { "496:1964925253:1733812836", "Royal Apothecary Society ต้องการให้เจ้าช่วย ฟังให้ดี แล้วเราทั้งคู่อาจได้ประโยชน์จากแผนข้า\n\nApothecary Keever ห้องถัดไปอาจ... สติไม่ดี... แต่งานวิจัยเขามีโอกาสเกิดผล หากผู้ฉลาดนำไปทำต่อ โชคดี ข้าคือนักวิจัยแบบนั้น นำใบสั่งซื้อนี้ไปให้ Alessandro Luca เจ้าของ Blue Moon Odds and Ends เขาจะให้ชุดทดสอบ เมื่อได้แล้วนำกลับมา ข้าจะอธิบายงานโดยละเอียด" },
        progress = { "147:775043122:1642873723", "ว่าอย่างไร ให้ข้าช่วยอะไร? มาทำธุระให้ Royal Apothecary Society หรือเพียงมาให้วันของข้าสดใส?" },
        completion = { "155:2128793108:1867500866", "อา Zinge ต้องการชุดอุปกรณ์หรือ? น่าเศร้าที่นางไม่เลือกมาปรากฏกายอันแสนหวานให้ข้าเห็นเอง\n\nเอาล่ะ ขอข้าหาชุดให้เจ้า" },
        required = { [8525] = { "22:819518733:894671930", "ใบสั่งซื้อของ Zinge" } },
        steps = { { "22:819518733:894671930", "ใบสั่งซื้อของ Zinge" } },
    },
    [238] = { -- Errand for Apothecary Zinge
        title = { "27:500422077:81973516", "ธุระให้ Apothecary Zinge" },
        objective = { "66:1767366295:970158401", "นำ Field Sampling Kit ไปให้ Apothecary Zinge ที่ Undercity" },
        description = { "18:1646424815:1536734778 N 297:2019522832:2094424105", "ชุดพร้อมแล้ว {name} Apothecary Zinge คงอยากได้เร็วที่สุด นำไปให้นางอย่าช้า บอกด้วยว่าข้าจะลงราคาชุดไว้ในบัญชีของสมาคม และฝากความปรารถนาดีอย่างอบอุ่นด้วย\n\nอย่ายืนเฉย ชีวิตคนส่งของธรรมดาก็อย่างนี้ใช่ไหม?" },
        progress = { "216:973832462:579030318", "ใช่ ข้าก็คิดว่า Luca น่ารำคาญชวนขนลุกเหมือนเจ้า แต่ไม่สำคัญ ส่งชุดเก็บตัวอย่างภาคสนามมา ข้าต้องปรับมันเล็กน้อยเพื่อสำรวจหาวัตถุดิบพื้นฐานที่เหมาะสม\n\nมีชุดมาด้วยใช่ไหม?" },
        completion = { "441:1797043432:553433705", "ดี ข้าพอใจที่ได้ทำงานกับคนภูมิใจในการไม่ทำข้าเสียเวลา\n\nเมื่อปรับชุดนี้แล้ว เจ้าจะพร้อมออกภาคสนาม ใช้มันเก็บข้อมูลสำคัญต่องานนี้\n\nปรับอีกครู่เดียวก็เสร็จ ระหว่างรอ เริ่มคิดก็ดีว่าจะนำอะไรไปทะเลทราย\n\nใช่ ข้าบอกว่าทะเลทราย" },
        required = { [8523] = { "17:874435004:1884063455", "ชุดทดสอบภาคสนาม" } },
        steps = { { "17:874435004:1884063455", "ชุดทดสอบภาคสนาม" } },
    },
    [264] = { -- Until Death Do Us Part
        title = { "22:1948081195:1997489162", "จนกว่าความตายจะแยกเรา" },
        objective = { "54:1762647194:1570085571", "วาง Clarice's Pendant บน Yuriv's Tomb ใน Silverpine" },
        description = { "315:271801882:1347337243 N 178:7740246:196950051", "ไอ้สารเลวโสโครก! ทิ้งข้าไปทำสงครามศักดิ์สิทธิ์บ้า ๆ เพราะ \"แสงสว่างคือสิ่งสำคัญที่สุดที่เรามีไว้ต้านภัยอันเดด\"\n\nแล้วลูก ๆ เขาล่ะ?! แล้วข้าล่ะ?! คืนแล้วคืนเล่าข้านั่งรออย่างอดทน... เป็นรองหน้าที่เฮงซวยเสมอ!\n\nดูสิว่า \"ความยุติธรรม\" ให้อะไร {name}! เขาตายแล้ว ส่วนข้ากลับมีสิ่งที่เขาพยายามหยุดอยู่ในตัว!\n\nนำขยะชิ้นนี้ไปวางบนหลุมศพเขาที่ Sepulcher ข้าไม่อยากเกี่ยวข้องกับมัน... หรือเขาอีก!" },
        progress = { "291:1849747982:1483099122", "หินเย็นเมื่อสัมผัส แต่เห็นชัดว่าถูกทำลาย ขยะกระจายรอบบริเวณ รอยบิ่นและรอยกรีดอยู่บนภาพนูนเหนือโลง พืชรอบหลุมศพเริ่มขึ้นรกคลุม\n\nไม่มีใครใส่ใจผู้ที่ฝังอยู่ที่นี่ โดยเฉพาะเหยื่อของโรคระบาด" },
        completion = { "373:1019167169:52462143", "เจ้าวางจี้ไร้ค่าบนหลุมศพ อัญมณีในตัวเรือนดูหม่นลงอย่างเห็นได้ชัด\n\nเมื่อลุกจะไป เจ้ามองจี้อีกครั้ง มันนอนนิ่งไร้ชีวิตอยู่บนมือของรูปนูนที่แกะไว้บนฝาโลง สายลมเย็นแรงที่พัดผ่าน Sepulcher ขัดความคิดเจ้า ชั่วขณะหนึ่งทุกสิ่งรอบตัวเงียบงัน" },
        required = { [6145] = { "17:524833925:1275667246", "จี้ของ Clarice" } },
        steps = { { "17:524833925:1275667246", "จี้ของ Clarice" } },
    },
    [357] = { -- The Lich's Identity
        title = { "19:1506427861:606757919", "ตัวตนของลิช" },
        objective = { "63:923680876:688099490", "นำ Lich's Spellbook ไปให้ Bethor Iceshard ที่ Undercity" },
        description = { "477:2063298614:1251880757", "มีลิชอยู่บนเกาะใน Brightwater Lake ทางเหนือ แม้เป็น Forsaken ผู้มีเจตจำนงเสรี เขากลับเชื่อว่าอันเดดอื่นทั้งหมดเป็นทาส Scourge จึงให้สมุนโจมตีใครก็ตามที่เข้าใกล้\n\nแต่เพราะเขาเป็น Forsaken ราชินีคงอยากได้ตัว หากชำนาญศาสตร์ปลุกศพ ความรู้เขาก็... มีประโยชน์มากต่อเรา\n\nเพื่อรู้ตัวตนและความสามารถ ข้าต้องเห็นตำราเวท ลอบเข้าค่ายนำมา แล้วกลับมาหาข้า", variants = { { "136:1540497135:881311782 R 335:2147034532:2030108778", "มีลิชอยู่บนเกาะใน Brightwater Lake ทางเหนือ แม้เป็น Forsaken ผู้มีเจตจำนงเสรี เขากลับเชื่อว่าชาว{race}อื่นทั้งหมดเป็นทาส Scourge จึงให้สมุนโจมตีใครก็ตามที่เข้าใกล้\n\nแต่เพราะเขาเป็น Forsaken ราชินีคงอยากได้ตัว หากชำนาญศาสตร์ปลุกศพ ความรู้เขาก็... มีประโยชน์มากต่อเรา\n\nเพื่อรู้ตัวตนและความสามารถ ข้าต้องเห็นตำราเวท ลอบเข้าค่ายนำมา แล้วกลับมาหาข้า" } } },
        progress = { "N 29:392840613:2035422138", "{name} ได้หนังสือมาหรือยัง?" },
        completion = { "11:1776810664:1873330125 N 462:658431700:544844165", "ดีมาก {name} ข้าจะศึกษาหนังสือและหาว่าลิชคนนั้นเป็นใคร เจ้ารับใช้ราชินีได้ดี\n\n<Bethor เปิดหนังสือ จ้องหน้าที่เรืองแสงอย่างตั้งใจ...>\n\nน่าทึ่ง! หนังสือที่เจ้านำมาเป็นของ Gunther Arcanus ไม่ใช่ใครอื่น!\n\nตอนมีชีวิต Gunther เป็นผู้ชำนาญศาสตร์ปลุกศพ เราเป็นสหายร่วมรบกันก่อนโรคระบาด ดูจากตำรา เขาทรงพลังกว่าเดิมอีกหลังความตาย\n\nฝีมือเขาจะช่วยเราได้มาก" },
        required = { [2833] = { "20:2040711094:1582056524", "ตำราเวทของลิช" } },
        steps = { { "20:2040711094:1582056524", "ตำราเวทของลิช" } },
    },
    [744] = { -- Preparation for Ceremony
        title = { "24:1462496515:65409821", "เตรียมพิธี" },
        objective = { "100:1308731918:1778987187", "รวบรวม Azure Feathers 6 ชิ้น และ Bronze Feathers 6 ชิ้น แล้วนำไปให้ Eyahn Eagletalon ที่ Thunder Bluff" },
        description = { "N 456:944977183:570270066", "{name} อีกไม่นานพี่น้องของข้าจะยืนต่อหน้า Chief Bloodhoof ข้าได้รับเกียรติให้ทำเครื่องสวมศีรษะให้เขา\n\nระหว่างฟอกสายหนังเหล่านี้ ข้าอยากขอให้ช่วย มีเวลาไม่พอหาขนนก จึงอยากรู้ว่าเจ้าช่วยเก็บเพิ่มได้ไหม?\n\nขนาดที่เหมาะหาได้จากฮาร์ปีไกลทางเหนือและตะวันตกเฉียงเหนือของ Thunder Bluff ข้าต้องการสีฟ้า 6 กับสีบรอนซ์ 6 ก็จะทำแบบเสร็จ" },
        progress = { "65:1265048898:1492177075", "เครื่องสวมศีรษะนี้จะเป็นของขวัญวิเศษให้พี่น้องของข้าแน่นอน" },
        completion = { "25:328543501:1621241081 N 139:1809022372:908595260", "ขอบใจที่ช่วย {name}\n\nส่วนของข้าในพิธีของพี่น้องใกล้เสร็จแล้ว เหลือเพียงมอบเครื่องสวมศีรษะและร่วมเป็นพยานในพิธี ก็ครบหน้าที่ข้า" },
        required = { [4752] = { "13:842392066:1444706302", "ขนนกสีฟ้า" }, [4753] = { "14:951348383:268395928", "ขนนกสีบรอนซ์" } },
        steps = { { "13:842392066:1444706302", "ขนนกสีฟ้า" }, { "14:951348383:268395928", "ขนนกสีบรอนซ์" } },
    },
    [768] = { -- Gathering Leather
        title = { "17:2066653428:826748917", "รวบรวมหนัง" },
        objective = { "71:1690460204:1241805980", "นำ Light Leather 12 ชิ้น ไปให้ Veren Tallstrider ที่ Thunder Bluff" },
        description = { "343:1583786787:1563692105", "สวัสดีผู้เยาว์ แววตาเจ้าสดใส ข้าดูออกว่ากระตือรือร้นกลับทุ่งไปล่า ขอให้สร้างเกียรติแก่เผ่าของเจ้า!\n\nข้าทำงานกับหนังสัตว์ สร้างเสื้อผ้าและเกราะให้ชาว Thunder Bluff\n\nหากล่าสัตว์แล้วนำหนังมา ข้าจะทำบางอย่างให้เจ้า" },
        progress = { "61:165307471:1910795396", "สวัสดีอีกครั้ง ไปล่ามาหรือ? มีหนังให้ข้าไหม?" },
        completion = { "71:738195288:1361928085 N 23:1511262162:2010911707", "อา เป็นหนังดีมาก ทำเครื่องหนังชั้นดีได้\n\nนี่ {name} รับสิ่งนี้แลกไป..." },
        required = { [2318] = { "13:512583266:745641545", "หนังบาง" } },
        steps = { { "13:512583266:745641545", "หนังบาง" } },
    },
    [769] = { -- Kodo Hide Bag
        title = { "13:1959694088:738127858", "กระเป๋าหนังโคโด" },
        objective = { "80:489915183:2080384339", "นำ Light Leather 4 ชิ้น และ Coarse Thread 4 เส้น ไปให้ Veren Tallstrider ที่ Thunder Bluff" },
        description = { "254:1370380785:788213900", "โคโดแห่ง Mulgore แข็งแรงและทรหด คุณสมบัติที่พวกเราเคารพ หากชำนาญ Leatherworking และอยากเรียนรู้วิธีทำ Kodo Hide Bag นำวัตถุดิบสำหรับงานข้ามา\n\nทำแล้วข้าจะแบ่งปันความรู้" },
        progress = { "25:404998364:1893283704 N 1:63:63", "มีวัตถุดิบของข้าหรือยัง {name}?" },
        completion = { "21:656597530:87701879 N 85:1140261982:2011423521", "อา ดี ขอบใจ {name} ข้าภูมิใจที่คนรุ่นเยาว์สนใจงาน Leatherworking" },
        required = { [2318] = { "13:512583266:745641545", "หนังบาง" }, [2320] = { "13:392152061:1000008462", "ด้ายหยาบ" } },
        steps = { { "13:512583266:745641545", "หนังบาง" }, { "13:392152061:1000008462", "ด้ายหยาบ" } },
    },
    [864] = { -- Return to Apothecary Zinge
        title = { "26:1507202039:2089210155", "กลับไปหา Apothecary Zinge" },
        objective = { "72:1897844817:1101135614", "นำ Sealed Field Testing Kit ไปให้ Apothecary Zinge ที่ Undercity" },
        description = { "408:1376366214:331292392", "\"เอ้า ถอดแหล่งพลังงานออกอย่างปลอดภัยและเก็บข้อมูลไว้แล้ว เดินทางปลอดภัยก็แล้วกัน หวังว่าการทดลองวิทยาศาสตร์ชั่วร้ายนั่นจะได้ผลนะ\"\n\nกอบลินหันไปจัดการความต้องการของ Gadgetzan Water Company เจ้าจัดเก็บชุดทดสอบที่ผนึกแล้วให้แน่นหนาสำหรับเดินทางกลับ Undercity Apothecary Zinge รอเจ้าและชุดนั้นอยู่" },
        progress = { "237:2002230774:1704876803", "ยินดีต้อนรับกลับ อย่างน้อยก็ถ้ามีชุดทดสอบที่ผนึกแล้วมาด้วย ไม่เช่นนั้น ข้าจะแสร้งไม่เห็นความไร้ความสามารถสิ้นเชิง และละความโกรธไว้จนกว่าเจ้าจะทำงานที่ได้รับมอบหมายสำเร็จ" },
        completion = { "368:1280556443:1739339743", "ข้าจะวิเคราะห์ข้อมูลทันที บางทีความบ้าของ Keever จะพิสูจน์อัจฉริยภาพข้าได้ในที่สุด\n\nส่วนเจ้า... มีประโยชน์ต่อข้า และข้าตอบแทนคนที่ยังมีประโยชน์อย่างดี รับไอเทม เงิน และสำคัญที่สุด คำขอบใจของข้าไปด้วย\n\nแวะมาถามเป็นครั้งคราว ข้าพนันว่างานโครงการนี้ร่วมกันยังไม่จบ" },
        required = { [8527] = { "24:936481582:411579818", "ชุดทดสอบภาคสนามที่ปิดผนึก" } },
        steps = { { "24:936481582:411579818", "ชุดทดสอบภาคสนามที่ปิดผนึก" } },
    },
    [1130] = { -- Melor Sends Word
        title = { "16:1713385691:615931258", "Melor ส่งข่าว" },
        objective = { "44:43710650:700728006", "คุยกับ Melor Stonehoof ที่ Thunder Bluff" },
        description = { "N 180:1865755434:579009747", "{name} Melor Stonehoof ได้ยินวีรกรรมของเจ้าและวางเส้นทางไว้ให้\n\nหากอยากเลือกเส้นนั้น ไป Thunder Bluff แล้วคุยกับ Melor เขาอยู่ที่ Hunter's Rise" },
        completion = { "4:1416233998:188502220 N 86:2129804553:1980316528 C 19:1473138822:1497648110", "เจ้ามาแล้ว {name} พร้อมเดินทางผ่านแดนไกลหรือยัง?\n\nหากพร้อม {class}รุ่นเยาว์ ก็ฟังต่อ..." },
    },
    [1131] = { -- Steelsnap
        title = { "9:1331274275:883726981", "Steelsnap" },
        objective = { "58:459851983:373099270", "นำ Steelsnap's Rib ไปให้ Melor Stonehoof ที่ Thunder Bluff" },
        description = { "425:30196241:2082716421 N 27:1241414860:1355132154", "บางครั้งเราล่าเพื่ออาหาร บางครั้งเพื่อเกียรติ และบางครั้งเพื่อเรียนรู้คำสอนพระแม่ธรณี\n\nแต่การล่าที่ข้ามอบตอนนี้ไม่ใช่ทั้งสามอย่าง เป็นการฆ่าสิ่งมีชีวิตที่อยู่นอกพรของพระแม่\n\nไฮยีนา Steelsnap เดินอยู่ใน Thousand Needles ทางใต้ของ Barrens มันเป็นทรราช ดึงดูดไฮยีนาอื่นมารวมตัว แพร่ความกลัวและการนองเลือดสู่สัตว์ที่สงบกว่า\n\nหา Steelsnap {name} หาแล้วเอาชนะมัน" },
        progress = { "38:388287280:155296755 N 1:63:63", "เอาชนะ Steelsnap ชั่วร้ายแล้วหรือ {name}?" },
        completion = { "107:117781379:1736932507 N 26:1414488674:1405729908", "การปราบ Steelsnap ช่วยชำระมลทินร้ายจาก Thousand Needles\n\nและนั่นคือบทเรียนวันนี้ {name}" },
        required = { [5837] = { "15:1827863807:1266837575", "ซี่โครงของ Steelsnap" } },
        steps = { { "15:1827863807:1266837575", "ซี่โครงของ Steelsnap" } },
    },
    [1136] = { -- Frostmaw
        title = { "8:907149122:919105075", "Frostmaw" },
        objective = { "58:1699121855:818711488", "นำ Frostmaw's Mane ไปให้ Melor Stonehoof ที่ Thunder Bluff" },
        description = { "N 362:63640298:1960400645 N 126:678296277:465735393", "{name} ถึงเวลาเดินทางสู่แดนไกลแล้ว เจ้าพร้อม\n\nคราวนี้ล่า Frostmaw เยติใน Alterac Mountains มันหลบซ่อนเก่ง ขนขาวกลืนกับหิมะแห่งภูเขาบ้านเกิด ไม่ค่อยปรากฏตัว\n\nแต่ข้าจะแสดงวิธีล่อสิ่งมีชีวิตเช่นมัน นี่ รับม้วนคัมภีร์ไป ข้าเขียนวิธีล่อ Frostmaw ไว้\n\nไปเถอะ {name} ทางไกลและมีความท้าทายมากรออยู่ เมื่อนำขนแผงคอ Frostmaw กลับมา งานจึงจะสำเร็จ" },
        progress = { "40:503763269:203739847 N 36:54223973:137180999", "ไป Alterac Mountains มาหรือยัง {name}? ได้เผชิญ Frostmaw ที่หลบซ่อนเก่งหรือไม่?" },
        completion = { "67:89348870:1183674204 N 210:1052637367:2078286972", "ต้องใช้ทั้งกำลังและไหวพริบจึงจะหาและเอาชนะ Frostmaw ได้ {name} เจ้ามีทั้งสอง\n\nเส้นทางพาเจ้าไปหุบเขา Thousand Needles และภูเขาสูง Alterac วันหนึ่งจะนำผ่านดินแดนทั้งหมดของพระแม่ธรณี เพราะนี่คือวิถีนักล่า" },
        required = { [5811] = { "15:1354040431:6779677", "แผงคอของ Frostmaw" } },
        steps = { { "15:1354040431:6779677", "แผงคอของ Frostmaw" } },
    },
    [1164] = { -- To Steal From Thieves
        title = { "21:1460644023:1713964507", "ขโมยจากหัวขโมย" },
        objective = { "80:391776273:2087166800", "นำศีรษะของ Kenata, Fardel และ Marcel Dabyrie ไปให้ Genavie Callow ที่ Undercity" },
        description = { "490:1969195318:802229121", "นางแพศยา! นางสุกร! Kenata ยังมีชีวิต ครอบครัวแข็งแรงรุ่งเรือง ขณะที่ข้าทนทุกข์ ถูกทอดทิ้งสมชื่อ Forsaken จริง ๆ!\n\nครอบครัวข้าหายไป ถูกโรคระบาดพราก ที่ดินก็สูญ ถูกปล้นและเผาระหว่างสงคราม หลังทุกอย่างนั้น นางกับลูก ๆ เฮงซวยยังกล้าขโมยสมบัติล้ำค่าเพียงอย่างเดียวที่ข้าเหลือ\n\nข้าไม่สนของที่ขโมยอีกแล้ว ตอนนี้อยากได้ศีรษะพวกมัน!\n\nฆ่าให้ข้า! ไป Dabyrie Farmstead ใน Arathi ทางตะวันออกเฉียงเหนือของ Refuge Point" },
        progress = { "39:219936785:398310689", "ฆ่าให้หมดแล้วนำศีรษะมาให้ข้า!" },
        completion = { "295:1605495954:350733980", "เจ้ายืนต่อหน้าข้าดุจร่างแห่งการล้างแค้น ข้าขอโค้งคำนับด้วยความขอบคุณ\n\nเมื่อนางวัวนั่นตาย และรู้ว่าลูกหลานจะไม่แพร่ต่อบน Azeroth ข้าก็ทุ่มกำลังกับสิ่งที่ทำกำไรได้มากกว่า หวังว่าเจ้าปล้นไร่หลังจัดการพวกมันแล้วนะ" },
        required = { [5830] = { "13:1395667379:483455985", "ศีรษะของ Kenata" }, [5832] = { "13:348148629:2009204004", "ศีรษะของ Marcel" }, [5831] = { "13:1371232220:333394489", "ศีรษะของ Fardel" } },
        steps = { { "13:1395667379:483455985", "ศีรษะของ Kenata" }, { "13:348148629:2009204004", "ศีรษะของ Marcel" }, { "13:1371232220:333394489", "ศีรษะของ Fardel" } },
    },
    [1195] = { -- The Sacred Flame
        title = { "16:575422096:955418221", "เปลวไฟศักดิ์สิทธิ์" },
        objective = { "66:594741524:381952343", "นำ Filled Etched Phial กลับไปให้ Zangen Stonehoof ที่ Thunder Bluff" },
        description = { "484:897358909:1096489342", "เซนทอร์ Galak ใน Thousand Needles ปกป้องวัตถุโบราณจากยุคกำเนิดเซนทอร์\n\nเราอยากนำกลับมา แต่ต้องใช้น้ำขวดหนึ่งจาก moonwell ของไนต์เอลฟ์\n\nก่อนเก็บน้ำ ต้องได้ขวดจากดรายแอดใกล้ Raynewood Retreat กลางป่า Ashenvale มี moonwell ใกล้ฝั่งตะวันตกของ Falfarren River ทางใต้ของถนนหลัก ใช้เติมขวดได้" },
        progress = { "195:1946831628:2063716888", "เมื่อได้ขวดเต็มแล้ว เราจะส่งต่อให้ Rau ผู้ร่วมงานใน Thousand Needles เขาเป็นคนขอน้ำ จึงน่าจะรู้วิธีใช้ได้ดีกว่า" },
        completion = { "138:718691909:1085725787", "ดีมาก น่าจะตรงตามที่ Rau ขอ ช่วยนำไปให้เขาได้ไหม? เจ้าอาจชอบไปใช้เวลาใน Thousand Needles" },
        required = { [5868] = { "19:1383264579:605547745", "ขวดแกะลายที่เติมแล้ว" } },
        steps = { { "19:1383264579:605547745", "ขวดแกะลายที่เติมแล้ว" } },
    },
    [1196] = { -- The Sacred Flame
        title = { "16:575422096:955418221", "เปลวไฟศักดิ์สิทธิ์" },
        objective = { "72:267617953:32286825", "นำ Filled Etched Phial ไปส่งให้ Rau Cliffrunner ที่ Freewind Post" },
        description = { "250:1960757532:1094259135", "นำขวดเต็มไปให้ Rau Cliffrunner ที่ Freewind Post ทางตะวันออกเฉียงใต้ของ Thousand Needles ไปถึงได้โดยใช้ Great Lift ที่ขอบใต้ Barrens\n\nข้าคงไม่แปลกใจหากเจ้ายังช่วยเราได้อีก" },
        progress = { "47:2105583038:687436617", "Zangen ส่งเจ้ามาหรือเปล่า?" },
        completion = { "245:1460104031:2013942737", "อืม ใช่ น้ำขวดนี้เหมาะกับงานเราอย่างยิ่ง เพราะดรายแอดกับเซนทอร์มีบรรพชนร่วมกัน น้ำ moonwell จึงทำให้เราฝ่าแนวป้องกันของไฟนิรันดร์ที่ล้อมวัตถุโบราณเซนทอร์ได้" },
        required = { [5868] = { "19:1383264579:605547745", "ขวดแกะลายที่เติมแล้ว" } },
        steps = { { "19:1383264579:605547745", "ขวดแกะลายที่เติมแล้ว" } },
    },
    [1197] = { -- The Sacred Flame
        title = { "16:575422096:955418221", "เปลวไฟศักดิ์สิทธิ์" },
        objective = { "66:2038329840:954508347", "นำ Cloven Hoof กลับมาให้ Rau Cliffrunner ที่ Freewind Post" },
        description = { "467:1659289327:2012162497", "น้ำที่นำมาจะช่วยดับเปลวไฟซึ่งคุมวัตถุโบราณไว้ได้ชั่วคราว แต่ไม่ถาวร จึงต้องรีบ\n\nSplithoof Crag ฐานเซนทอร์อยู่ทางเหนือ ไฟอยู่ใน Splithoof Hold ส่วนหนึ่งของหน้าผาที่คุ้มกันแน่นหนา\n\nระวังด้วย เซนทอร์ Galak มีมาก และคงไม่ยอมมอบสิ่งล้ำค่าง่าย ๆ" },
        progress = { "71:1391108345:2038997599", "ข้าอยากได้ Cloven Hoof มาถือเร็ว ๆ เจ้าเอามาหรือยัง?" },
        completion = { "162:44738276:1483923642 N 68:2124499164:733278953", "ข้าสัมผัสพลังแปลกจากกีบ... ไม่สงสัยเลยว่าศึกษาแล้วจะพบข้อมูลน่าประหลาดเกี่ยวกับเซนทอร์\n\nขอบใจ {name} ทีนี้ข้าต้องเริ่มไขปริศนาที่เจ้านำมา" },
        required = { [5869] = { "11:1505670253:917862714", "กีบแยก" } },
        steps = { { "11:1505670253:917862714", "กีบแยก" } },
    },
    [1358] = { -- Sample for Helbrim
        title = { "18:1379937536:1949323214", "ตัวอย่างให้ Helbrim" },
        objective = { "65:707047457:833249676", "นำ Wolf Heart Sample ไปให้ Apothecary Helbrim ที่ Barrens" },
        description = { "455:916122893:127303782", "Apothecary Helbrim ผู้ร่วมงานใน Kalimdor กำลังศึกษาผลสารพิษจาก Lordaeron ต่อสัตว์ใน Kalimdor เขาคงสนใจตัวอย่างหัวใจหมาป่าที่ Renferrel ส่งให้ข้ามาก\n\nHelbrim อยู่ใน Barrens ที่หมู่บ้าน Crossroads หากจะไป ต้องโดยสารเรือเหาะไป Orgrimmar นครหลวงออร์ค แล้วเดินลงใต้สู่ Durotar จากนั้นไปตะวันตกเข้า Barrens ก็จะถึง Crossroads ในไม่ช้า" },
        progress = { "26:1926655420:65699218", "มีห่อของให้ข้าหรือ?" },
        completion = { "166:187196438:318366737 N 29:60145553:1289893570", "อา ดีมาก หากรายงานแรกจริง พิษในหัวใจเหล่านี้อาจช่วยให้ความรู้เรื่องสารพิษเราก้าวหน้า\n\nเป็นของส่งที่น่ายินดี {name} เจ้าสมควรได้รับรางวัล" },
        required = { [6016] = { "17:689662376:424839181", "ตัวอย่างหัวใจหมาป่า" } },
        steps = { { "17:689662376:424839181", "ตัวอย่างหัวใจหมาป่า" } },
    },
    [2995] = { -- Lines of Communication
        title = { "22:236343261:1358357127", "เส้นทางสื่อสาร" },
        objective = { "136:1528906612:41082483", "Oran Snakewrithe ที่ Undercity ต้องการให้เจ้าไป Hinterlands แล้วเผา Highvale Records, Highvale Report และ Highvale Notes" },
        description = { "409:131209287:1726649206 N 92:291961322:1309785042", "Quel'Danil Lodge เป็นศูนย์สื่อสารของไฮเอลฟ์ Hinterlands ทูตของพวกเขาสร้างสัมพันธ์กับเผ่าอื่น แบ่งปันความรู้เรื่องโทรลล์ Witherbark ที่อยู่ทางใต้ของ Hinterlands เอกสารการสื่อสารทั้งหมดเก็บที่นั่น\n\nเราไม่ต้องการให้ Highvale สร้างพันธมิตรกับคนอื่น {name}\n\nทำลายเอกสาร Highvale เราต้องเผาเส้นทางสื่อสารของพวกมัน... ตามตัวอักษรเลย" },
        progress = { "73:2039488637:2123316938", "กุญแจคือทำให้เอลฟ์ Highvale โดดเดี่ยว พบที่พักหรือยัง?" },
        completion = { "9:736088637:128646839 N 114:738985441:1016729177", "สมบูรณ์แบบ {name} ระหว่าง Highvale กู้ข้อมูลที่เสียไป เราจะปิดเส้นทางได้แน่นหนาขึ้นอีก..." },
        steps = { { "25:151824720:793678132", "เผาเอกสารบันทึกของ Highvale" }, { "23:1642538815:1843361269", "เผาบันทึกย่อของ Highvale" }, { "24:1157128842:2002444386", "เผารายงานของ Highvale" } },
    },
    [3568] = { -- Seeping Corruption
        title = { "18:1224433089:2111188490", "ความเสื่อมทรามที่ซึมซ่าน" },
        objective = { "127:584386452:889678430", "เติม Empty Vials ทั้ง 4 ใบ ที่แอ่งน้ำขึ้นลงตามชายฝั่ง Ruins of Eldarath ใน Azshara แล้วกลับไปหา Chemist Cuely" },
        description = { "493:232700539:946024440", "เห็นทอเรนข้างหลังข้าที่เหมือนจะป่วยได้ทุกเมื่อไหม? นางเพิ่งไป Azshara อ้างว่าถูกนากาทำร้ายขณะผ่าน Ruins of Eldarath\n\nหลังสู้ไล่ไปสองสามตัว นางพักบนหาดแล้วดื่มน้ำจากแอ่งน้ำขึ้นลง ตอนนี้รู้สึกคลื่นไส้... และอย่างอื่นอีก\n\nข้าอยากรู้ว่านางดื่มอะไร นำกล่องนี้ไป มีขวดเปล่าที่ข้าติดป้ายไว้ เติมแต่ละใบจากคนละแอ่ง แล้วกลับมา" },
        progress = { "43:1248385441:1397476135 N 311:872642299:1966197657", "รู้ใช่ไหมว่าเรื่องนี้จะจบอย่างไร {name}? นางไม่มีทางรอด... ดูสิ สิ่งดีที่สุดตอนนี้คือช่วยเราหาวิธีรักษาโรคระบาด น้ำที่นางดื่มอาจมีเบาะแสบอกวิธี นางจะตายอยู่แล้ว ก็ควรตายหลังทำเรื่องสูงส่งเพื่อคนของเรา ไม่เห็นด้วยหรือ?" },
        completion = { "354:342848948:1441663130", "วิเศษ กลับมาก่อนนางตาย ดี ดี\n\nเริ่มกันเลยไหม?\n\nข้าศึกษาอาการมาพักหนึ่งแล้ว น่าเกลียดทีเดียว แปลกใจที่ยังยืนไหว นางอาเจียนสามสี่ครั้งทั่วบริเวณ... กลิ่นช่างน่ารื่นรมย์\n\nขอครู่เดียว ข้าจะปรุงอะไรไปทดสอบกับ... สหายของเรา" },
        required = { [10691] = { "22:1123943529:11134488", "ขวดที่เติมแล้วติดป้ายหมายเลข 1" }, [10692] = { "22:1123943530:11134489", "ขวดที่เติมแล้วติดป้ายหมายเลข 2" }, [10693] = { "22:1123943531:11134490", "ขวดที่เติมแล้วติดป้ายหมายเลข 3" }, [10694] = { "22:1123943532:11134491", "ขวดที่เติมแล้วติดป้ายหมายเลข 4" } },
        steps = { { "22:1123943529:11134488", "ขวดที่เติมแล้วติดป้ายหมายเลข 1" }, { "22:1123943530:11134489", "ขวดที่เติมแล้วติดป้ายหมายเลข 2" }, { "22:1123943531:11134490", "ขวดที่เติมแล้วติดป้ายหมายเลข 3" }, { "22:1123943532:11134491", "ขวดที่เติมแล้วติดป้ายหมายเลข 4" } },
    },
    [3569] = { -- Seeping Corruption
        title = { "18:1224433089:2111188490", "ความเสื่อมทรามที่ซึมซ่าน" },
        objective = { "52:368902989:994675590", "มอบ Cuely's Elixir ให้ Thersa Windsong ที่ Undercity" },
        description = { "109:1606230215:190824985", "นำไปให้ Thersa บางทีรักษาได้... หรือไม่ได้ เราไม่รู้จนกว่านางจะดื่ม" },
        progress = { "344:1871407588:1549897400", "ข้ามา Undercity เพราะได้ยินว่านักเล่นแร่แปรธาตุที่นี่ศึกษาวิธีรักษาโรคของตนอย่างหนักมานาน มีคนแนะนำว่าอาจช่วยข้าได้ด้วย\n\nแม้ที่นี่ทำให้รู้สึกไม่เป็นที่ต้อนรับ ข้าก็ไม่มีทางเลือก โรคที่พบกำลังทำลายจากภายใน และข้าต้องให้พวกเขาช่วยทันที" },
        completion = { "300:801867109:1569933806", "Chemist Cuely ต้อนรับข้าดีมาก... จนน่าหวาดระแวง แต่หากเขาว่านี่จะช่วย ข้าก็ไม่มีทางเลือก ไม่มีเวลาหาวิธีอื่นแล้ว ข้าคุยกับนักบวชและชาแมนมา ไม่มีใครช่วยได้\n\nหวังว่าพระแม่ธรณีจะคุ้มครองวิญญาณข้า" },
    },
    [3570] = { -- Seeping Corruption
        title = { "18:1224433089:2111188490", "ความเสื่อมทรามที่ซึมซ่าน" },
        completion = { "68:1556558436:47052571 N 139:1371195852:1906143135", "ไม่เคยคิดว่ายาจะออกฤทธิ์เร็วขนาดนั้น ขอบใจ {name} ข้าจะเริ่มจัดการตัวอย่างที่เหลือทันที มั่นใจว่าอีกไม่นาน Lady Sylvanas กับ Forsaken จะใช้ประโยชน์ได้" },
        description = { "49:1381892534:1802685719", "ฮ่า เห็นสีหน้านางไหม?! ตลกจนลืมไม่ลง!" },
    },
    [4293] = { -- A Sample of Slime...
        title = { "20:895513320:262715807", "ตัวอย่างสไลม์..." },
        objective = { "249:1356024573:230332352", "เก็บ Felwood Slime Samples จากสไลม์ใดก็ได้ใน Felwood แล้วใช้ Testing Equipment ข้าง Chemist Fuely ที่ Undercity เพื่อตรวจว่าตัวอย่างใดแปดเปื้อนที่สุด นำ Corrupted Felwood Samples ที่พบ 5 ชิ้น ไปให้ Chemist Fuely" },
        description = { "463:1689123919:1629502875", "Felwood เป็นป่าไกลทางเหนือของ Barrens เลย Ashenvale ไปอีก ที่นั่นมีสไลม์รอบแอ่งน้ำที่ได้รับสัมผัส Fel กลุ่ม Scourge ทำลายพื้นที่ด้วย Infernals และเวทปีศาจอื่น ว่ากันว่าสไลม์คืบจากใต้ดินระหว่างการโจมตี\n\nเก็บตัวอย่างสไลม์ Felwood แล้วเราจะใช้อุปกรณ์ทดสอบข้างข้าสร้างกลุ่มควบคุมสำหรับทดลองเทียบกับตัวอย่างอื่นที่เจ้าหามา" },
        progress = { "67:1567476640:309475351 N 126:1701240687:1531686724", "ข้าต้องการตัวอย่างแปดเปื้อนอย่างน้อยห้าชิ้นเป็นกลุ่มควบคุม {name} เก็บสไลม์ Felwood ต่อจนให้สิ่งที่ต้องการได้ Lady Sylvanas มีบัญชา..." },
        completion = { "426:788357834:1809084273", "อา ยอดเยี่ยม ตัวอย่างใช้ได้ดี ขอบใจที่ช่วย\n\nเมื่อรวบรวมตัวอย่างสไลม์ทั้งหมดแล้ว เราจะบอกได้มากขึ้น ข้าเริ่มสงสัยว่าลางสังหรณ์ Lady Sylvanas ไม่เพียงถูก แต่ลึกซึ้งกว่าที่นางคาดด้วย ตัวอย่างน่าสนใจ แค่เห็นปฏิกิริยากับสารผสมของข้า... อืม ใช่ ต้องศึกษาเพิ่มแน่" },
        required = { [12234] = { "24:1359332485:1874140463", "ตัวอย่างปนเปื้อนจาก Felwood" } },
        objectiveLabels = {
            item = { ["Corrupted Felwood Sample"] = "ตัวอย่างปนเปื้อนจาก Felwood" },
        },
    },
    [4294] = { -- ... and a Batch of Ooze
        title = { "23:1379576469:2070491476", "...และอูซอีกชุด" },
        objective = { "248:715852241:2125479377", "เก็บ Un'Goro Slime Samples จากสไลม์ใดก็ได้ใน Un'Goro Crater แล้วใช้ Testing Equipment ข้าง Chemist Fuely ที่ Undercity เพื่อตรวจว่าตัวอย่างใดบริสุทธิ์ที่สุด นำ Pure Un'Goro Samples ที่พบ 5 ชิ้น ไปให้ Chemist Fuely" },
        description = { "38:1055265444:1702599512 N 411:126764889:1944450604", "เคยได้ยิน Un'Goro Crater ไหม {name}? อยู่ใกล้ทะเลทราย Tanaris เป็นสถานที่วิเศษ อุดมสมบูรณ์ มีชีวิตชีวา เต็มไปด้วยสัตว์และพืช\n\nเจ้าต้องไปที่นั่น ข้าได้ข่าวว่าดูเหมือนไม่แปดเปื้อนจากมือคนนอกเลย นักสำรวจเพิ่งเริ่มค้นความลับ\n\nข้าอยากทดสอบสไลม์หรืออูซที่นั่น หากจริงว่าไม่แปดเปื้อน ข้าก็อยากเห็นว่าสิ่งมีชีวิตเช่นนี้วิวัฒนาการอย่างไร" },
        progress = { "5:1287366450:669725923 N 23:2104103389:1875780886", "ว่าอย่างไร {name}? การค้นหาเป็นอย่างไร?" },
        completion = { "15:1170215385:1418151963 N 456:889166129:1849207347", "น่าทึ่งจริง ๆ {name} Un'Goro Crater เก็บความลับมากกว่าที่คิด สงสัยว่าทดลองต่อแล้วจะพบอะไรอีก\n\nน่าทึ่ง... ดูความบริสุทธิ์ของตัวอย่างสิ อืม หมายความว่าอะไรนะ? ธรรมชาติมันดูเป็นธาตุ แต่... มีอะไรมากกว่านั้น ทำให้นึกถึง... เหล่าเทพโบราณ เราพบร่องรอยของพวกเขาทั่ว Azeroth ตอนนี้จึงสงสัยว่าสิ่งมีชีวิตเหล่านี้อาจเกี่ยวข้องกัน\n\nเราต้องทดลองต่อ" },
        required = { [12236] = { "19:592926746:445718978", "ตัวอย่างบริสุทธิ์จาก Un'Goro" } },
        objectiveLabels = {
            item = { ["Pure Un'Goro Sample"] = "ตัวอย่างบริสุทธิ์จาก Un'Goro" },
        },
    },
    [4561] = { -- Testing for Impurities - Un'Goro Crater
        title = { "39:1908124698:60302788", "ทดสอบสิ่งเจือปน — Un'Goro Crater" },
        progress = { "333:1329627953:1897572829", "เจ้านำตัวอย่างสไลม์ Un'Goro Crater ใส่ลงในหลอดและบีกเกอร์ต่าง ๆ บนโต๊ะ เมื่อเริ่มเดือดและพุ่งกระเซ็น สไลม์เปลี่ยนสี เมื่อกระบวนการช้าลงและของเหลวสงบ เจ้าพบจานเพาะเชื้อเล็กที่มีสไลม์ Un'Goro ซึ่งผ่านการทำให้บริสุทธิ์ พร้อมเศษอื่น" },
        completion = { "223:1328475417:1237405136", "เจ้าหยิบจานเพาะเชื้อที่มีตัวอย่างสไลม์ วิธีเดียวที่จะรู้ว่าบริสุทธิ์พอไหมคือเปิดตรวจข้างในด้วยตัวเอง หวังว่าจะพบตัวอย่างที่ตรงเกณฑ์ Chemist Fuely" },
        description = { "333:1329627953:1897572829", "เจ้านำตัวอย่างสไลม์ Un'Goro Crater ใส่ลงในหลอดและบีกเกอร์ต่าง ๆ บนโต๊ะ เมื่อเริ่มเดือดและพุ่งกระเซ็น สไลม์เปลี่ยนสี เมื่อกระบวนการช้าลงและของเหลวสงบ เจ้าพบจานเพาะเชื้อเล็กที่มีสไลม์ Un'Goro ซึ่งผ่านการทำให้บริสุทธิ์ พร้อมเศษอื่น" },
        required = { [12235] = { "20:371156569:447947131", "ตัวอย่างเมือกจาก Un'Goro" } },
        objectiveLabels = {
            item = { ["Un'Goro Slime Sample"] = "ตัวอย่างเมือกจาก Un'Goro" },
        },
    },
    [4642] = { -- Melding of Influences
        title = { "21:78459639:982368066", "ผสานอิทธิพล" },
        objective = { "57:933129770:1980719869", "นำ Merged Ooze Sample ไปให้ Chemist Fuely ที่ Undercity" },
        description = { "390:736619010:1063599587", "นี่อูซในภาชนะที่สร้างจากตัวอย่าง Felwood ที่เจ้ากู้มา นำไป Un'Goro Crater แล้วหาอูซบริสุทธิ์... ชนิด primal จะเหมาะมาก เมื่อใกล้พอ ปล่อยอูซจากภาชนะ มาดูว่าทั้งสองจะมีปฏิกิริยาต่อกันอย่างไร\n\nเมื่อทดลองจบ นำตัวอย่างสิ่งที่เหลือมาให้ข้า ข้าจะรอใน Apothecarium" },
        progress = { "25:333675170:1586754086 N 229:1608749962:1461773657", "การทดลองเป็นอย่างไร {name}? ข้าจะศึกษาตัวอย่างที่เจ้านำมาให้ต่อ เริ่มเห็นแล้วว่าทำไม Lady Sylvanas สนใจสิ่งมีชีวิตพวกนี้ หากเป็นส่วนหนึ่งของเทพโบราณจริง ใครจะรู้ว่าใช้ให้เราได้ประโยชน์อย่างไรได้บ้าง" },
        completion = { "20:514189652:1660309047 N 324:149930523:1997548038", "โอ้ ยอดเยี่ยมที่สุด {name} ยอดเยี่ยมจริง ๆ\n\nช่างเป็นเรื่อง ใครจะคิดว่าทั้งสองตอบสนองกันแบบนั้น... ข้าต้องใช้เวลาศึกษาปัจจัยแวดล้อมที่เปลี่ยนสิ่งมีชีวิตเหล่านี้เพิ่ม\n\nตอนนี้จะวิจัยต่อ บางทีเราอาจได้คุยอีกเร็ว ๆ ระหว่างนี้ขอให้โชคดี" },
        required = { [12291] = { "18:939386877:1657648406", "ตัวอย่างอูซที่หลอมรวมกัน" } },
        objectiveLabels = {
            item = { ["Merged Ooze Sample"] = "ตัวอย่างอูซที่หลอมรวมกัน" },
        },
    },
    [4661] = { -- Testing for Corruption - Felwood
        title = { "32:1384587030:1592454789", "ทดสอบความแปดเปื้อน — Felwood" },
