    [5961] = { -- The Champion of the Banshee Queen
        title = { "33:1017747316:1795721993", "ยอดนักรบแห่งราชินีแบนชี" },
        objective = { "119:638265574:2064213132", "คุยกับ Nathanos Blightcaller ใน Eastern Plaguelands ว่ากันว่าเขาพำนักที่ Marris Stead" },
        description = { "169:171373481:2030347916 C 312:1913494710:1454751629", "ข้าพอใจมากที่เห็นผู้เจนศึกเข้าร่วมงานเรา จำนวนและกำลังเพิ่มขึ้นทุกวัน บางทีเจ้าพร้อมทดสอบฝีมือแล้ว {class}?\n\nหนึ่งในยอดนักรบคนแรกของข้าคือ Nathanos ที่ตอนนี้รู้จักในนาม Blightcaller มีน้อยคนในหมู่เราที่ทุ่มเทและแข็งขันกว่า\n\nไปหาใน Eastern Plaguelands เขาอยู่ที่ Marris Stead บางครั้งเดินไปในดินแดนยับเยิน ฆ่า Scourge กับพวกสกปรก Alliance ที่ขวางทาง" },
        completion = { "161:1938299080:453200486", "Dark Lady คงไม่คิดว่าเจ้าคู่ควรพบยอดนักรบของนางหรอก มาป้อนอาหารสุนัขข้าใช่ไหม? ไม่มีเหตุผลอื่นที่จะมารบกวน" },
    },
    [7662] = { -- New Kodo - Teal
        title = { "15:483516065:551879721", "โคโดตัวใหม่ — สีเขียวน้ำทะเล" },
        completion = { "273:782364466:508627066", "หากนำโคโดตัวเก่ามา ข้าจะแลกให้จากฝูงใหม่ ตัวใหม่จะเร็วเท่าตัวเก่า แต่รูปลักษณ์ต่างไป ดูเหล่า great kodos รอบลานนี้ได้ จะได้รู้ว่ามีตัวเลือกหน้าตาอย่างไร" },
