    [97290] = { -- Unending Torment
        title = { "16:66632423:142628065", "ทรมานไม่สิ้นสุด" },
        objective = { "64:2132304796:390316918", "รายงานสิ่งที่พบต่อ Master Apothecary Faranell ที่ Undercity" },
