    [435] = { -- Escorting Erland
        title = { "16:481435817:15014087", "คุ้มกัน Erland" },
        objective = { "49:76635323:279254983", "คุ้มกัน Erland ผ่านฝูงหมาป่าไปหา Rane Yorick" },
        description = { "395:1744646903:435470518", "หมาป่าข้างนอกไม่ไปไหน จ้องร้ายทุกครั้งที่ข้าออกประตู มันต้องหิวมากถึงคิดว่าข้าน่ากิน\n\nข้าต้องรายงานตัวต่อเพื่อนร่วมทีม Deathstalker Rane Yorick และจะไปถึงได้ก็ต้องมีคนช่วยต้านหมาป่า\n\nโปรดคุ้มกัน! ข้างนอกมีหมาป่ามาก หากมีเพื่อนช่วย โอกาสคงดีขึ้น..." },
        progress = { "85:1468078114:783129556", "โปรดพูดสั้น ๆ รอบตัวอันตรายมาก เราหยุดยืนคุยเฉยไม่ได้" },
        completion = { "23:719079444:2124347427 N 103:1241778416:220739881", "ขอบใจที่ช่วย {name} ข้ากลัวว่า Erland จะพ่ายอันตราย Silverpine แต่เพราะเจ้า เห็นแล้วว่าเขารอด" },
        objectiveLabels = {
            event = { ["Erland must reach Rane Yorick"] = "พา Erland ไปให้ถึง Rane Yorick" },
        },
    },
    [449] = { -- The Deathstalkers' Report
        title = { "25:88118753:774914324", "รายงานของ Deathstalkers" },
        objective = { "71:2021744825:285821106", "นำ Deathstalker Report ไปให้ High Executor Hadrec ที่ Sepulcher" },
        description = { "186:1958638906:177381481", "แม้บาดแผล Quinn กำลังดีขึ้น ข้าก็อยากให้รายงานถึง High Executor Hadrec เร็วที่สุด มีข้อมูลสำคัญต่อการยึดครอง Silverpine ของ Forsaken" },
        progress = { "47:503535358:1923002740", "ได้รู้ชะตาของ Deathstalkers หรือยัง?" },
        completion = { "207:771708942:569268745 N 28:2008329594:784364813", "ข้าไม่ได้คาดว่า Scourge จะมีมากขนาดที่พบใน Silverpine Forest หรือว่า Deathstalkers จะลำบากในการลาดตระเวนเพียงนี้\n\nความช่วยเหลือต่อ Deathstalkers มีค่ายิ่ง {name} เจ้าจะได้รับคำยกย่อง" },
        required = { [3252] = { "19:1624593202:1774300752", "รายงานของ Deathstalker" } },
        steps = { { "19:1624593202:1774300752", "รายงานของ Deathstalker" } },
    },
    [3221] = { -- Speak with Renferrel
        title = { "20:112557820:2050709037", "คุยกับ Renferrel" },
        objective = { "49:736940396:1371223618", "คุยกับ Apothecary Renferrel ที่ Sepulcher" },
        description = { "187:1101253641:2001866374", "ระหว่างเจ้าช่วย Deathstalkers Apothecary Renferrel ส่งคำเรียกมา เขาไม่ให้รายละเอียด แต่อยากคุยเรื่องหัวใจหมาป่าที่เจ้าเคยมอบให้" },
        completion = { "112:358382081:1763292568", "อา ดีมาก มีเรื่องหัวใจหมาป่าที่นำมาก่อนหน้านี้ซึ่งเราต้องให้ความสนใจ" },
    },
    [97288] = { -- Unending Torment
        title = { "16:66632423:142628065", "ทรมานไม่สิ้นสุด" },
        objective = { "79:692678391:1034640540", "นำ Abominable Head ไปให้ Master Apothecary Faranell ใน Undercity", variants = { { "60:814856735:91926633", "นำ Abominable Head ไปให้ใครสักคนใน Undercity" } } },
        description = { "233:1610585797:436792110", "<เมื่อสิ่งมีชีวิตล้มลง ศีรษะของมันก็หลุดกลิ้งออกมา ดูเหมือนเคยถูกต่อกลับหลายครั้ง และจุดเชื่อมก็อ่อนแอลงทุกครั้ง\n\nใครสักคนใน Undercity น่าจะรู้เรื่องอะบอมิเนชันที่ไม่เหมือนใครนี้มากกว่านี้>" },
        progress = { "18:86409350:1779796507", "เราได้อะไรมานี่?" },
        completion = { "119:192491665:1156157993", "โอ้โฮ! ข้าคิดว่าจำศีรษะนี้ได้ เรื่องตลกอันโหดร้ายของ Dark Lady ช่างสะใจเสียด้วย\n\nข้าคิดว่ามีประโยชน์ให้มันทำ" },
        required = { [280438] = { "15:1068994419:384685825", "ศีรษะของอสูร Abomination" } },
        steps = { { "15:1068994419:384685825", "ศีรษะของอสูร Abomination" } },
        objectiveLabels = {
            event = { ["Deliver the Abominable Head to someone within the Undercity."] = "นำ Abominable Head ไปให้ใครสักคนใน Undercity" },
        },
    },
    [97289] = { -- Unending Torment
        title = { "16:66632423:142628065", "ทรมานไม่สิ้นสุด" },
        objective = { "67:339201854:1446950005", "นำ Head of the Baron ไปยังร่างของ Othmar ใน Undercity" },
        description = { "444:61022725:1932455796", "เราทำหัวอะบอมิเนชันเป็นประจำ แต่หัวนี้พิเศษ ครั้งหนึ่งมันเคยเป็นของ Grand Marshal แห่ง Alliance คนที่น่ารังเกียจเป็นพิเศษ ข้าเชื่อว่ามันชื่อ Othmar Dark Lady ได้ลงมือกำจัดเจ้าตัวนี้ด้วยตนเองอย่างสำราญ\n\nโอ้ หากพูดได้ มันคงบอกความลับได้มากมาย และมันพูดได้! ถ้าเราต่อกลับเข้าร่างรองรับที่เหมาะสม\n\nเอาไปวางข้างร่างที่ว่างอยู่ในห้องถัดไป แต่ยังไม่ต้องต่อมัน ยังไม่ใช่ตอนนี้", variants = { { "447:731020525:828195380", "เราทำหัวอะบอมิเนชันเป็นประจำ แต่หัวนี้พิเศษ ครั้งหนึ่งมันเคยเป็นของ Grand Marshal แห่ง Alliance คนที่น่ารังเกียจเป็นพิเศษ ข้าเชื่อว่ามันชื่อ Othmar Dark Lady ได้ลงมือกำจัดเจ้าตัวนี้ด้วยตนเองอย่างสำราญ\n\nโอ้ หากพูดได้ มันคงบอกความลับได้มากมาย และมันพูดได้! ถ้าเราต่อกลับเข้าร่างรองรับที่เหมาะสม\n\nเอาไปวางข้างร่างที่ว่างอยู่ในห้องถัดไป แต่ยังไม่ต้องต่อมัน ยังไม่ใช่ตอนนี้" } } },
        progress = { "62:1876287316:196836916", "อะบอมิเนชันยังไร้ชีวิตเมื่อไม่มีศีรษะควบคุม", variants = { { "64:460318016:1287247814", "<อะบอมิเนชันยังไร้ชีวิตเมื่อไม่มีศีรษะควบคุม>" } } },
        completion = { "76:829413958:703763288", "ร่างกระตุกกลับมีชีวิต ตื่นตระหนกขณะหวนเผชิญช่วงสุดท้ายก่อนตาย\n\nเจ้า...", variants = { { "78:430120381:1691913640", "<ร่างกระตุกกลับมีชีวิต ตื่นตระหนกขณะหวนเผชิญช่วงสุดท้ายก่อนตาย>\n\nเจ้า..." } } },
        required = { [268518] = { "17:1693310088:789760135", "ศีรษะของบารอน" } },
        objectiveLabels = {
            item = { ["Head of the Baron"] = "ศีรษะของบารอน" },
        },
    },
    [97291] = { -- Unending Torment
        title = { "16:66632423:142628065", "ทรมานไม่สิ้นสุด" },
        objective = { "218:103015325:1395406650", "รวบรวม Toxic Skullcap จาก Tawny Grisette ใน Trade Quarter, Blisterweed ใกล้ครูฝึก Herbalism และ Essence of Agony จากพ่อค้าขายพิษใน Rogues' Quarter ให้ Master Apothecary Faranell ใน Undercity" },
        description = { "500:1208457038:1268368611", "เมื่อต่อศีรษะกลับแล้ว ตอนนี้เหลือเพียงผูกมันไว้กับเจตจำนง Dark Lady คงไม่เป็นปัญหา หลังโดนทุบตีมาขนาดนั้น อสูรนี่แทบไม่เหลือสมองแล้ว\n\nเราเพียงต้องกระตุ้นมัน\n\nหา Toxic Skullcap จากคุณ Grisette ใน Trade Quarter มาให้ข้า อ้อ แล้วก็ Blisterweed จากครูฝึกสมุนไพรท้องถิ่นของเรา พวก Alliestar หยิบมาได้เลย พวกเขาติดหนี้ข้าอยู่ สุดท้ายขอ Essence of Agony สักหน่อย พ่อค้าขายพิษคนไหนก็น่าจะมี\n\nเรามียาที่ต้องปรุง!" },
        progress = { "87:116851106:1659843791", "จะน่ายินดีเพียงใดที่แกะหลงฝูงของเรากลับเข้าคอก ว่าไหม?" },
        completion = { "117:38471493:2089090064", "ของเหล่านี้ใช้ได้ดี เราจะได้เห็นว่าแขกผู้ทรงเกียรติยังเหลือความกร่างเพียงใด หลังได้ลิ้มผลงานชิ้นเอกของข้า" },
        required = { [281246] = { "14:1137317295:1418556256", "สมุนไพร Toxic Skullcap" }, [281300] = { "11:446277972:467685325", "สมุนไพร Blisterweed" }, [8923] = { "16:1398035032:1057026058", "แก่นพิษแห่งความทรมาน" } },
        steps = { { "14:1137317295:1418556256", "สมุนไพร Toxic Skullcap" }, { "11:446277972:467685325", "สมุนไพร Blisterweed" }, { "16:1398035032:1057026058", "แก่นพิษแห่งความทรมาน" } },
    },
    [97292] = { -- Unending Torment
        title = { "16:66632423:142628065", "ทรมานไม่สิ้นสุด" },
        objective = { "92:1788598887:450635456", "ฉีด Hissing Serum เข้าระบบเหนือร่าง Othmar ให้ Master Apothecary Faranell" },
        description = { "285:1914999988:741103224", "ข้าปรุงเซรุ่มชั้นดีที่แขกใหม่ของเราต้องรู้สึก... กระปรี้กระเปร่าอย่างแน่นอน\n\nเอ้านี่ ใส่ลงในกลไกที่หยดของเหลวจากเหนือร่างเขา มาดูกันว่าเราจะแสดงให้เขารู้ได้ไหมว่าทำไมการรับใช้อย่างภักดีจึงเป็นผลดีต่อตัวเขาเองที่สุด\n\nแล้วพยายามอย่าทำตก ข้าไม่มีปัญญาหาผู้ช่วยคนใหม่" },
        progress = { "125:66510740:1712814689", "สำหรับความผิดที่ Othmar ก่อต่อ Dark Lady การเอาเขาไว้ใต้ตัวอย่างที่หยดของเหลวนั้นยังน้อยไป\n\nแถมยังตลกด้วย..." },
        completion = { "211:1275701663:1346975949", "ยอดเยี่ยม เราจะปล่อยให้เนื้อเขาเดือดกรุ่นสักพัก ให้เวลาเขาปรับตัวเข้ากับบ้านใหม่\n\nตอนนี้ข้ายังไม่มีอะไรใช้เจ้าสารเลวนี่ทำ แต่เราจะคอยดูเขาไว้ ข้ามีแผนมากมายสำหรับอนาคตของ Othmar" },
        required = { [281327] = { "13:368943874:1119953278", "เซรุ่มเสียงฟู่" } },
        steps = { { "26:1080988647:1729392172", "ฉีด Hissing Serum" } },
        objectiveLabels = {
            item = { ["Hissing Serum"] = "เซรุ่มเสียงฟู่" },
        },
    },
    [384] = { -- Beer Basted Boar Ribs
        title = { "21:754063449:435187980", "ซี่โครงหมูป่าราดเบียร์" },
        objective = { "81:1796279130:766648879", "Ragnar Thunderbrew ใน Kharanos ต้องการ Crag Boar Ribs 6 ชิ้น และ Rhapsody Malt หนึ่งแก้ว" },
        description = { "435:294701990:103531482", "ไม่มีอะไรถูกใจลูกค้าในร้านข้ามากไปกว่าซี่โครงหมูป่าราดเบียร์! ปัญหาเดียวคือนายพรานท้องถิ่นที่เคยนำวัตถุดิบมาส่ง สมัครเข้ากองทัพของกษัตริย์เพื่อช่วยรบในแนวหน้าของ Alliance ไปแล้ว\n\nเจ้าช่วยข้าได้ไหม? ถ้านำ Crag Boar Ribs หกชิ้นกับ Rhapsody Malt จากร้านนี้มาให้ ข้าจะให้สูตรซี่โครงหมูป่าราดเบียร์อันเลื่องชื่อที่สืบทอดในครอบครัว แถมให้ชิมฟรีด้วย! เคล็ดลับอยู่ที่มอลต์นี่แหละ!" },
        progress = { "65:1376402237:420342457 N 1:46:46", "ข้าต้องใช้ Crag Boar Ribs หกชิ้นกับ Rhapsody Malt หนึ่งแก้ว {name}" },
        completion = { "155:1885551966:1020364658", "มอลต์หมักได้ที่ หมูป่าสิ้นชีวี\nก่อนเรื่องราวจะจบลงตรงนี้\nคงต้องแย่งกันว่าใครจะได้ชิมก่อน\nซี่โครงหมูป่าราดเบียร์หอมกรุ่นชวนอร่อย!" },
        required = { [2886] = { "13:526458894:1648227861", "ซี่โครงหมูป่าผา" }, [2894] = { "13:252964500:651848177", "มอลต์ Rhapsody" } },
        steps = { { "13:526458894:1648227861", "ซี่โครงหมูป่าผา" }, { "13:252964500:651848177", "มอลต์ Rhapsody" } },
    },
    [862] = { -- Dig Rat Stew
        title = { "12:817374189:887689180", "สตูหนู Dig Rat" },
        objective = { "48:390194528:1395989592", "นำ Dig Rats 8 ตัวไปให้ Grub ทางตะวันออกของ Crossroads" },
        description = { "2:16737:8547 C 407:73295222:383230595", "{class} อย่างเจ้าคงหิวน่าดูเมื่อต้องอยู่กลาง The Barrens แบบนี้ ส่วนข้าน่ะ หิวโซทั้งวัน\n\nเอาอย่างนี้ ข้าจะทำสตูอร่อย ๆ ให้ ขอแค่หนู Dig Rat สักหน่อย\n\nดูเหมือนพวกคนแคระโสโครกที่ Bael Modan จะมีของโปรดของทุกคนพวกนี้ชุกชุมจนรับมือไม่ไหว ลงใต้ไป Bael Modan แล้วนำหนู Dig Rat กลับมาให้ข้า\n\nยังเรียกตัวเองว่านักผจญภัยผู้ช่ำชองไม่ได้หรอก จนกว่าจะเคยใช้เวลาไล่ฆ่าหนูมาแล้ว! ฮ่า!" },
        progress = { "27:1500262018:806443541 N 1:63:63", "ตีหนู Dig Rat ได้พอหรือยัง {name}?" },
        completion = { "231:1077075781:2088156770", "ปกติข้าไม่ชอบกินสัตว์ฟันแทะพวกนี้ตอนที่มันยัง... ยัง... สดขนาดนี้ ชอบปล่อยให้เน่าสักสองสามสัปดาห์ รสชาติจะได้ออกมาเต็มที่ แต่เจ้าดูหิวเหลือเกิน\n\nให้ข้าทำสตูหนู Dig Rat ให้กินนะ อา ได้แล้ว\n\nเอ้า รับไป!" },
        required = { [5051] = { "7:834975569:1028064035", "หนูขุดรู" } },
        steps = { { "7:834975569:1028064035", "หนูขุดรู" } },
    },
    [1579] = { -- Gaffer Jacks
        title = { "12:1373604480:1970824016", "Gaffer Jacks" },
        objective = { "57:68445340:2062486840", "นำ Gaffer Jacks 8 ชิ้นไปให้ Wizbang Cranktoggle ใน Auberdine" },
        description = { "414:1929495861:1790795771", "ข้ามา Auberdine เพราะที่นี่เงียบสงบ ข้าอยากประดิษฐ์ของในที่เงียบ ๆ เพราะหลังจากดื่มมาทั้งคืน ข้าไม่อยากฟังเสียงเอะอะของ Ironforge!\n\nข้าจึงลงเรือมา Auberdine แต่ระหว่างทางดื่มมากไปหน่อย แล้วทำกล่อง Gaffer Jacks ตกทะเล! ข้าต้องใช้ Gaffer Jacks!\n\nข้าจำไม่ได้แน่ชัดว่าทำตกตรงไหน แต่ถ้าเจ้าลองตกปลาในทะเลก็อาจโชคดีเจอมัน..." },
        progress = { "30:1713455009:1660448432 N 55:1400880490:86246308", "หา Gaffer Jacks ของข้าเจอหรือยัง {name}? ถ้าไม่มีมัน ข้าก็ปรับ Stintle Pegs ไม่ได้!" },
        completion = { "57:1719223420:895515604 R 13:1150476147:804194862", "ไม่อยากเชื่อว่าเจ้าหาเจอ! เจ้าต้องเป็น{race}ที่โชคดีที่สุดใน Kalimdor แน่ ๆ!" },
        required = { [6717] = { "11:289447659:1523200899", "แม่แรง Gaffer Jack" } },
        steps = { { "11:289447659:1523200899", "แม่แรง Gaffer Jack" } },
    },
    [1580] = { -- Electropellers
        title = { "14:1545751600:47362745", "Electropellers" },
        objective = { "60:1744869272:2017379445", "นำ Electropellers 12 ชิ้นไปให้ Wizbang Cranktoggle ใน Auberdine" },
        description = { "53:897205336:533577703 N 427:945393935:1800454001", "เรารู้ว่าเจ้าโชคดี แต่... จะโชคดีสักแค่ไหนกันนะ {name}?\n\nคืนหนึ่งข้าเดินไปตามถนนใน Darkshore กำลังหาแม่น้ำหรือทะเลสาบดี ๆ เพื่อทดลองเป็ดล่อระเบิดแบบขับเคลื่อนตัวเองตัวใหม่ ข้าคงกรึ่มไปหน่อย... เพราะข้าหมดสติ แล้วตื่นขึ้นอีกหลายชั่วโมงให้หลังที่ Auberdine ผมข้าไหม้เกรียม ส่วนถุง Electropellers ก็หายไป! ข้าต้องทำตกน้ำแน่ ๆ!\n\nข้าต้องใช้ Electropellers พวกนั้น! เจ้าอาจตกมันขึ้นมาจากทะเลสาบหรือลำธารสักแห่งใน Darkshore ได้..." },
        progress = { "96:1618781364:1339484677", "เจอ Electropellers บ้างไหม? ข้าต้องใช้มันเพื่อวิจัยเป็ดล่อต่อ..." },
        completion = { "90:2057072606:1219352460 N 119:1800474749:1994052209", "ไม่อยากเชื่อเลย! เจ้าหาเจอแล้ว! เจ้าเป็นคนตกปลาที่เก่งที่สุดเท่าที่ข้าเคยพบ!\n\nขอบใจนะ {name} เอ้า รับของพวกนี้ไป ถึงเจ้าจะเก่งจนคงไม่ต้องใช้แล้ว แต่มันก็ช่วยให้เจ้าตกปลาได้ดีขึ้น" },
        required = { [6718] = { "13:941882957:65933566", "เครื่องขับเคลื่อนไฟฟ้า Electropeller" } },
        steps = { { "13:941882957:65933566", "เครื่องขับเคลื่อนไฟฟ้า Electropeller" } },
    },
    [1582] = { -- Moonglow Vest
        title = { "13:235147990:1553401814", "เสื้อกั๊ก Moonglow" },
        objective = { "114:1895429345:660164612", "นำ Embossed Leather Gloves 1 ชิ้น, Embossed Leather Boots 5 ชิ้น และ Embossed Leather Cloaks 5 ชิ้นไปให้ Lotherias ใน Darnassus", variants = { { "113:501845238:1928408154", "นำ Embossed Leather Glove 1 ชิ้น, Embossed Leather Boots 5 ชิ้น และ Embossed Leather Cloaks 5 ชิ้นไปให้ Lotherias ใน Darnassus" } } },
        description = { "280:138057248:1665774039", "พวกเราใน Darnassus โดยเฉพาะเหล่าช่างฝีมือ มีงานยุ่งกันมาก นักผจญภัยรุ่นใหม่กระตือรือร้นจะทดสอบตัวเองในป่า จึงต้องการเสบียงและอุปกรณ์อยู่เสมอ\n\nหากเจ้าช่วยข้าทำเครื่องหนังให้ครบตามรายการสั่งซื้อ ข้าก็อาจสอนเทคนิคงานเครื่องหนังขั้นสูงให้เจ้าได้" },
        progress = { "11:927657569:725753248 N 1:46:46", "สวัสดี {name}" },
        completion = { "126:1276735342:957055987 N 56:1479268099:787863753", "ใช่แล้ว ผลงานพวกนี้ดีมาก เจ้าฝีมือประณีตและใส่ใจรายละเอียด อนาคตในฐานะช่างเครื่องหนังของเจ้าสดใสนัก\n\nมาสิ {name} ข้าจะแสดงแบบสำหรับทำ Moonglow Vest ให้ดู" },
        required = { [4239] = { "23:566215793:1905422790", "ถุงมือหนังลายนูน" }, [2309] = { "22:1194617165:56946073", "รองเท้าบูตหนังลายนูน" }, [2310] = { "22:1211191602:344699224", "ผ้าคลุมหนังลายนูน" } },
        steps = { { "23:566215793:1905422790", "ถุงมือหนังลายนูน" }, { "22:1194617165:56946073", "รองเท้าบูตหนังลายนูน" }, { "22:1211191602:344699224", "ผ้าคลุมหนังลายนูน" } },
    },
    [2178] = { -- Easy Strider Living
        title = { "19:337144368:877086495", "อิ่มสบายด้วยเนื้อ Strider" },
        objective = { "64:1255766474:1088861844", "นำ Strider Meat 5 ชิ้นกลับไปให้ Alanndarian Nightsong ใน Auberdine" },
        description = { "58:476821310:482097401 N 373:1393405371:365372049", "ได้กลิ่นหอมอร่อยนั่นไหม? สูตรลับของข้าเอง {name} สตูเนื้อ Strider สด ๆ อร่อยที่สุด!\n\nเจ้าอาจสนใจเรียนสูตรนี้ก็ได้นะ?\n\nก่อนข้าจะสอน เจ้าต้องพิสูจน์ว่าเอาอยู่เมื่อต้องรับมือสัตว์พวกนี้\n\nข้าไม่ได้คาดหวังให้เจ้าไปฝึกมันให้เชื่องแล้วขี่กลับมาหรอก แต่ถ้าฆ่าได้สักสองสามตัวและนำเนื้อฉ่ำ ๆ กลับมา ข้าอาจยอมสอนวิธีทำสตู Strider ให้เจ้า" },
        progress = { "59:157935144:1266825381", "หม้อว่างแล้ว ข้าก็หิว! ทำไมเจ้าถึงช้านัก?" },
        completion = { "46:142090761:1458558757 N 1:33:33", "ยอดเยี่ยม! ลองชิมแล้วบอกข้าทีว่าคิดอย่างไร {name}!" },
        required = { [5469] = { "12:999970032:1255254832", "เนื้อสไตรเดอร์" } },
        steps = { { "12:999970032:1255254832", "เนื้อสไตรเดอร์" } },
    },
    [2847] = { -- Wild Leather Armor
        title = { "18:1428299663:1477321321", "เกราะหนัง Wild Leather" },
        objective = { "68:1145131131:661887602", "นำ Thick Leather 10 ชิ้นไปให้ Pratt McGrubben ใน Feathermoon Stronghold" },
        description = { "N 497:1651039587:1884939654", "{name} เจ้ากำลังเป็นช่างเครื่องหนังที่เก่งขึ้นมาก! ข้ารู้จักแบบที่เจ้าน่าจะสนใจ... เกราะ Wild Leather! Wild Leather ใช้คุณสมบัติอันทรงพลังและแปรปรวนของ Wildvine ซึ่งพบในพื้นที่พืชพรรณหนาแน่นและบนสิ่งมีชีวิตบางชนิดที่นั่น ในระดับฝีมือเจ้า เกราะที่ทำจากมันไม่เป็นรองใคร ข้ารับรอง\n\nข้าจะสอนให้ แต่เจ้าต้องทำงานให้ข้าสักพัก ค่าตอบแทนขั้นแรกมีแค่ Thick Leather สิบชิ้น หลังจากนั้นเราค่อยคุยรายละเอียดกัน" },
        progress = { "429:2007321285:1423515546", "อย่างที่บอก เจ้าต้องทำงานให้ข้าระหว่างเรียนรู้เรื่องเกราะ Wild Leather เพราะ Wildvine ทั้งทรงพลังและแปรปรวน มันจึงเสริมคุณสมบัติที่สุ่มได้แต่แข็งแกร่งให้แก่เกราะที่แข็งแรงอยู่แล้ว ความรู้นี้กว่าข้าจะได้มาก็ไม่ง่าย\n\nค่าเริ่มต้นกระบวนการนี้คือ Thick Leather สิบชิ้น\n\nเมื่อเรียบร้อยแล้ว เราค่อยเริ่มงานที่เจ้าต้องทำเพื่อแลกกับแบบเหล่านั้น" },
        completion = { "5:1151914341:80614338 N 248:1946815508:219906177", "ดีแล้ว {name} ข้ายินดีที่เจ้าร่วมงานด้วย เจ้าเลือกได้ฉลาดสมกับเป็นช่างเครื่องหนัง พอเจ้าเรียนรู้วิธีทำเกราะ Wild Leather แม้เพียงชิ้นเดียว ผู้สวมเกราะหนังก็จะแห่มาขอให้เจ้าทำให้\n\nมาเริ่มงานกัน เจ้าอยากเริ่มตรงไหน?" },
        required = { [4304] = { "13:983336109:1264322130", "หนังหนา" } },
        objectiveLabels = {
            item = { ["Thick Leather"] = "หนังหนา" },
        },
    },
    [2848] = { -- Wild Leather Shoulders
        title = { "22:1481234814:2062184358", "เกราะไหล่ Wild Leather" },
        objective = { "85:1092712521:332631766", "นำ Thick Armor Kits 6 ชิ้น และ Wildvine หนึ่งชิ้นไปให้ Pratt McGrubben ใน Feathermoon Stronghold" },
        description = { "384:1810189730:1126269081", "เกราะไหล่ Wild Leather ช่วยรองรับร่างกายผู้สวมได้ดีเยี่ยม ปกป้องต้นแขนและหัวไหล่ได้อย่างยอดเยี่ยม เช่นเดียวกับเกราะ Wild Leather ทุกชิ้น เมื่อเย็บ Wildvine เข้าไป มันจะเพิ่มคุณสมบัติที่ทรงพลังแต่สุ่มชนิดได้ให้กับชิ้นงาน\n\nสำหรับแบบนี้ ข้าต้องการ Thick Armor Kits หกชิ้นกับ Wildvine หนึ่งชิ้น เจ้าน่าจะหามาให้ได้ไม่ยากนัก" },
        progress = { "342:253812249:623977383", "มี Thick Armor Kits หกชิ้นกับ Wildvine ที่ข้าต้องการหรือยัง?\n\nอย่าคิดว่าการทำชุดเสริมเกราะเป็นงานจำเจ วิธีลงมืออย่างสม่ำเสมอที่เจ้าได้ฝึกจากชุดเหล่านี้ ช่วยพัฒนาทักษะสำหรับงานละเอียดซับซ้อนที่ต้องใช้ในการทำเกราะ Wild Leather\n\nเห็นไหม งานที่ข้าให้เจ้าทำมีเหตุผลจริง ๆ..." },
        completion = { "39:50719949:532841529 N 195:1840028291:659584008", "ชุดเสริมเกราะพวกนี้คุณภาพดีแน่นหนา {name} สิ่งหนึ่งที่ข้าเรียกร้องทั้งจากงานตัวเองและจากคนที่ทำงานให้ข้าก็คือคุณภาพ\n\nเจ้าทำได้ดีจนสมควรได้รับแบบนี้ หวังว่ามันจะให้ผลตอบแทนแก่เจ้าเหมือนที่เคยให้ข้า" },
        required = { [8173] = { "15:1616630267:2060595163", "ชุดเสริมเกราะแบบหนา" }, [8153] = { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
        steps = { { "15:1616630267:2060595163", "ชุดเสริมเกราะแบบหนา" }, { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
    },
    [2849] = { -- Wild Leather Vest
        title = { "17:1622918041:894308115", "เสื้อกั๊ก Wild Leather" },
        objective = { "118:259535021:979297625", "นำ Turtle Scale Breastplates 2 ชิ้น, Turtle Scale Gloves 2 ชิ้น และ Wildvine หนึ่งชิ้นไปให้ Pratt McGrubben ใน Feathermoon Stronghold" },
        description = { "442:2083318536:491913682", "เสื้อกั๊ก Wild Leather เป็นชิ้นหลักของชุดเกราะ Wild Leather ทุกชุด โครงเสื้อผสานกับ Wildvine กลายเป็นชิ้นงานที่ปกป้องลำตัวได้สูงสุด และเปิดทางให้เวทมนตร์อันทรงพลังไหลผ่านเนื้อเสื้อ\n\nสำหรับแบบนี้ ข้าต้องการ Turtle Scale Breastplates สองชิ้น, Turtle Scale Gloves สองชุด และ Wildvine หนึ่งชิ้น ของไม่น้อยเลย แต่เจ้าคงทำให้ข้าได้ไม่ลำบากนัก" },
        progress = { "442:291347997:1378987564", "มีเสื้อเกราะกับถุงมือ Turtle Scale อย่างละสองตามที่ข้าสั่งหรือยัง? แล้วอย่าลืม Wildvine ด้วย!\n\nแม้แต่แบบพื้นฐานที่สุดก็สอนให้เรารู้ว่า หลักการขึ้นรูปใช้กับเสื้อผ้าที่ยากขึ้นได้ดี ถึงจะเป็นของคนละชนิด รูปทรงของเสื้อเกราะ Turtle Scale ก็ช่วยเตรียมเจ้าให้พร้อมสำหรับรายละเอียดที่ต้องใช้ในการทำเสื้อกั๊ก Wild Leather\n\nส่วนถุงมือน่ะ... ข้าแค่อยากได้ไว้ใช้เอง จำไว้สิ เจ้ากำลังทำงานให้ข้า!" },
        completion = { "38:756234351:4287159 N 232:660531056:1755801930", "ผลงานพวกนี้งดงามมาก {name} แค่ฝีมือและความใส่ใจที่ใช้ทำ ก็น่าจะขายได้แพงกว่าชิ้นงานทั่วไปหลายเหรียญเงินแล้ว\n\nเจ้าทำตามรายการสั่งซื้อครบ รางวัลจึงเป็นของเจ้า บัดนี้เจ้าจะได้เรียนรู้วิธีทำเสื้อกั๊ก Wild Leather!" },
        required = { [8189] = { "24:1134388533:1065446975", "เกราะอกเกล็ดเต่า" }, [8187] = { "19:1672709702:1863723700", "ถุงมือเกล็ดเต่า" }, [8153] = { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
        steps = { { "24:1134388533:1065446975", "เกราะอกเกล็ดเต่า" }, { "19:1672709702:1863723700", "ถุงมือเกล็ดเต่า" }, { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
    },
    [2850] = { -- Wild Leather Helmet
        title = { "19:137664708:193241029", "หมวกเกราะ Wild Leather" },
        objective = { "111:1691249836:26669442", "นำ Nightscape Tunics 2 ชิ้น, Nightscape Headbands 2 ชิ้น และ Wildvine หนึ่งชิ้นไปให้ Pratt McGrubben ใน Feathermoon Stronghold" },
        description = { "440:245811801:855447222", "หมวกเกราะ Wild Leather ปกป้องจุดสำคัญบนศีรษะได้เหนือชั้นโดยยังสวมสบาย เช่นเดียวกับเกราะ Wild Leather ทุกชิ้น Wildvine ที่ผสานเข้าไปจะเพิ่มคุณสมบัติทรงพลังแบบสุ่มให้โครงหมวก ผู้สวมเกราะหนังต้องอยากได้ชิ้นนี้แน่นอน!\n\nสำหรับแบบนี้ ข้าต้องการ Nightscape Tunics สองชิ้น, Nightscape Headbands สองชิ้น และ Wildvine หนึ่งชิ้น ทำตามรายการนี้ครบแล้วแบบก็เป็นของเจ้า!" },
        progress = { "384:211631458:579015968", "ข้าต้องการให้เจ้าทำเสื้อกับผ้าคาดศีรษะพวกนั้น และยังต้องใช้ Wildvine อีกชิ้น ก่อนจะแบ่งปันความรู้เรื่องหมวกเกราะ Wild Leather ให้\n\nอุปกรณ์ศีรษะเป็นที่ต้องการอย่างมากในหมู่นักผจญภัย ไม่ว่าจะเป็นผ้าคาดศีรษะที่ดูเรียบง่ายเหลือเชื่อ หรือหมวกเกราะที่ปิดคลุมทั้งหัว หลักการทำอุปกรณ์ศีรษะอันมีค่ายังคงเหมือนเดิม ไม่ว่าภายนอกจะดูเป็นอย่างไร" },
        completion = { "71:1435639425:1443228232 N 168:635896199:1155572231", "อุปกรณ์ Nightscape ที่เจ้านำมาครบถ้วนตามที่สั่งพอดี {name} ข้าคาดหวังจากช่างเครื่องหนังระดับเจ้าไม่น้อยไปกว่านี้อยู่แล้ว\n\nเจ้าคู่ควรกับแบบนี้แน่นอน ข้ายกให้ด้วยความเต็มใจ และหวังว่าเจ้าจะใช้มันสร้างรายได้งดงาม" },
        required = { [8175] = { "16:250784020:367936008", "เสื้อคลุมตัวสั้น Nightscape" }, [8176] = { "19:1615819192:820948959", "ผ้าคาดหัว Nightscape" }, [8153] = { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
        steps = { { "16:250784020:367936008", "เสื้อคลุมตัวสั้น Nightscape" }, { "19:1615819192:820948959", "ผ้าคาดหัว Nightscape" }, { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
    },
    [2851] = { -- Wild Leather Boots
        title = { "18:1445012375:1765111947", "รองเท้าบูต Wild Leather" },
        objective = { "107:1121616311:1266133982", "นำ Nightscape Pants 2 ชิ้น, Nightscape Boots 2 ชิ้น และ Wildvines 2 ชิ้นไปให้ Pratt McGrubben ใน Feathermoon Stronghold" },
        description = { "32:28130351:734711807 N 458:1975242163:1666878576", "ตอนนี้เจ้าเรียนรู้มามากแล้ว {name} แต่ยังมีให้เรียนอีก ต่อไปคือรองเท้าบูต Wild Leather ซึ่งเป็นรากฐานของทุกชุด\n\nรองเท้าเหล่านี้ทำขึ้นเพื่อโอบรับเท้าอย่างสบาย พร้อมประคองป้องกันอันตรายจากการผจญภัย พื้นรองเท้านุ่มยังเป็นพรแก่ผู้ต้องการย่างก้าวอย่างเงียบเชียบ\n\nสำหรับแบบนี้ ข้าต้องการ Nightscape Pants สองชิ้นกับ Nightscape Boots สองชิ้นตามรายการสั่งซื้อ และต้องใช้ Wildvine สองชิ้นด้วย... ไม่ใช่แค่ชิ้นเดียว เมื่อมีครบแล้วก็บอกข้า" },
        progress = { "92:1306207768:1980206115 N 308:361914012:1106324789", "เจ้าต้องนำกางเกง รองเท้าบูต และ Wildvine มาให้ครบตามสั่งก่อนจึงจะได้แบบ {name} เสร็จหรือยัง?\n\nตั้งแต่รองเท้าบูตคู่แรกที่เราเรียนทำ เราก็เริ่มเข้าใจว่ารองเท้าคุณภาพดีต้องรักษาสมดุลอันละเอียดอ่อนระหว่างความสบายและการใช้งาน เมื่อมีทั้งสองอย่าง เราจึงทำอุปกรณ์ที่ช่วยให้ผู้สวมลืมความเหนื่อยล้าซึ่งอาจทำให้ผู้สวมของคุณภาพต่ำกว่าหมดแรงได้" },
        completion = { "136:1821689511:738457148", "อีกครั้งที่เจ้าทำรายการสั่งซื้ออันซับซ้อนได้ครบด้วยฝีมือของมืออาชีพผู้ช่ำชอง เจ้าคู่ควรกับทั้งแบบนี้และคำขอบใจจากข้า" },
        required = { [8153] = { "8:542661520:1452607669", "เถาวัลย์ Wildvine" }, [8193] = { "16:1788766222:1292459590", "กางเกง Nightscape" }, [8197] = { "16:1081433075:1495918389", "รองเท้าบูต Nightscape" } },
        objectiveLabels = {
            item = { ["Wildvine"] = "เถาวัลย์ Wildvine", ["Nightscape Pants"] = "กางเกง Nightscape", ["Nightscape Boots"] = "รองเท้าบูต Nightscape" },
        },
    },
    [2852] = { -- Wild Leather Leggings
        title = { "21:1483154169:706164949", "กางเกงเกราะ Wild Leather" },
        objective = { "113:863956333:2052743987", "นำ Turtle Scale Helms 2 ชิ้น, Turtle Scale Bracers 2 ชิ้น และ Wildvines 2 ชิ้นไปให้ Pratt McGrubben ใน Feathermoon Stronghold" },
        description = { "65:1555721823:274507067 N 396:2020572648:889547051", "เมื่อเข้าใจพื้นฐานแล้ว เจ้าก็พร้อมฝึกงานที่ซับซ้อนขึ้นจนชำนาญ {name} กางเกงเกราะ Wild Leather เป็นเครื่องหนังที่ทนทานและทรงพลังที่สุดกลุ่มหนึ่ง ทั้งเอว ต้นขา น่อง และจุดสำคัญล้วนได้รับการปกป้องอย่างมาก เมื่อรวมกับคุณสมบัติที่ Wildvine เสริมให้ นักผจญภัยที่เป็นเจ้าของจะขอบใจเจ้าทุกครั้งที่พบกัน\n\nสำหรับแบบนี้ ข้าต้องการ Turtle Scale Helms สองชิ้น, Turtle Scale Bracers สองชิ้น และ Wildvine สองชิ้นตามรายการสั่งซื้อ" },
        progress = { "381:669842602:618364167", "เตรียมปลอกแขนกับหมวกเกราะ Turtle Scale พร้อมหรือยัง? อย่าลืม Wildvine สองชิ้นที่ข้าต้องการด้วย!\n\nถึงตอนนี้ เจ้าคงเริ่มเห็นพลังที่ซ่อนอยู่ในเกราะ Wild Leather แล้ว เกราะที่นำไปใช้ได้อย่างไร้ขอบเขตนั้นแทบประเมินค่ามิได้สำหรับช่างเครื่องหนัง ข้อจำกัดมีเพียงปริมาณทรัพยากรที่ใช้ทำ ไม่ใช่คุณภาพของผลงานที่เสร็จแล้ว!" },
        completion = { "102:1653287547:819847286 N 161:1678196560:1561758661", "เจ้าทำตามรายการสั่งซื้อได้อย่างไร้ที่ติอีกแล้ว บางทีสักวันข้าอาจต้องไปขอความรู้จากเจ้าเสียเอง ว่าไหม {name}?\n\nนี่คือแบบกางเกงเกราะ พร้อมคำขอบใจจากข้า จดจำความรู้นี้ไว้ แล้วให้ผลงานที่เสร็จแล้วแสดงฝีมืออันน่าประทับใจของเจ้า!" },
        required = { [8153] = { "8:542661520:1452607669", "เถาวัลย์ Wildvine" }, [8191] = { "17:1865123908:1887807128", "หมวกเกราะเกล็ดเต่า" }, [8198] = { "20:596847337:1034256254", "ปลอกแขนเกล็ดเต่า" } },
        objectiveLabels = {
            item = { ["Wildvine"] = "เถาวัลย์ Wildvine", ["Turtle Scale Helm"] = "หมวกเกราะเกล็ดเต่า", ["Turtle Scale Bracers"] = "ปลอกแขนเกล็ดเต่า" },
        },
    },
    [2853] = { -- Master of the Wild Leather
        title = { "26:654236145:1665346798", "ผู้เชี่ยวชาญ Wild Leather" },
        objective = { "70:1239409104:1328136410", "นำ Pratt's Letter ไปให้ Telonis ช่างเครื่องหนังผู้เชี่ยวชาญแห่ง Darnassus" },
        description = { "5:1151914341:80614338 N 475:23727794:1088203323", "เอาละ {name} เจ้าเป็นแบบอย่างของความขยันจริง ๆ แบบเกราะ Wild Leather เหลืออีกเพียงแบบเดียว ที่เหลือเจ้าเชี่ยวชาญหมดแล้ว ข้าจะไม่ให้เจ้าตรากตรำโดยไม่จำเป็นเพื่อแลกแบบนี้ เจ้าได้พิสูจน์ว่าคู่ควรแล้ว และยิ่งกว่านั้นเสียอีก... แต่ข้ามอบให้เจ้าเองไม่ได้ อาจารย์ผู้พาข้าเข้าสู่งานฝีมือนี้ต่างหากที่ต้องเป็นผู้มอบรางวัล\n\nนำจดหมายนี้ไปให้ Telonis เขาสอนงานเครื่องหนังอยู่ใน Darnassus ให้เขาอ่านจดหมาย แล้วให้เขายอมรับเจ้าเป็นผู้มีฝีมือทัดเทียม เช่นเดียวกับที่ข้ายอมรับ" },
        progress = { "11:927657569:725753248 R 151:1677309450:2127593124", "สวัสดี {race}... ดูจากท่าที ข้าก็บอกได้ว่าเจ้าเป็นช่างเครื่องหนังเช่นเดียวกับข้า เจ้ามาเรียนรู้จากฝีมือข้า หรือมีธุระอื่น?" },
        completion = { "422:1701249164:1744269391", "อา ใช่ Pratt ส่งเจ้ามา แม้เขาเป็นมนุษย์ บางครั้งก็ทำให้ข้านึกถึงพวกเราไนต์เอลฟ์ ความทุ่มเทและพรสวรรค์ด้านเครื่องหนังของเขาน่าประทับใจนัก การที่เขาชมเจ้าในจดหมายถึงเพียงนี้เป็นการแสดงความเคารพที่ข้ายอมรับ\n\nข้ารู้ว่าเขาสอนศิลปะ Wild Leather ให้เจ้าแล้ว ให้ข้าฝึกเจ้าให้จบด้วยแบบนี้ จงใช้ให้คุ้มค่า มีเพียงไม่กี่คนในโลกที่รู้ความลับของผ้าคลุม Wild Leather" },
    },
    [2854] = { -- Wild Leather Armor
        title = { "18:1428299663:1477321321", "เกราะหนัง Wild Leather" },
        objective = { "63:1608668179:118087659", "นำ Thick Leather 10 ชิ้นไปให้ Jangdor Swiftstrider ใน Camp Mojache" },
        description = { "N 493:1620588483:450909568", "{name} ชื่อเสียงด้านฝีมืองานเครื่องหนังของเจ้ามาถึงก่อนตัวเสียอีก ข้ามีความรู้เรื่องเครื่องหนังที่เจ้าควรเรียนไว้... เกราะ Wild Leather! Wild Leather ใช้คุณสมบัติอันทรงพลังและแปรปรวนของ Wildvine ซึ่งพบในพื้นที่พืชพรรณหนาแน่นและบนสิ่งมีชีวิตบางชนิดที่นั่น ในระดับฝีมือเจ้า เกราะที่ทำจากมันไม่เป็นรองใคร ข้ารับรอง\n\nข้าจะสอนให้ แต่เจ้าต้องทำงานให้ข้าสักพัก ค่าตอบแทนขั้นแรกมีแค่ Thick Leather สิบชิ้น หลังจากนั้นเราค่อยคุยรายละเอียดกัน" },
        progress = { "445:347754813:1254008254", "เราต้องตกลงกันให้ชัด เจ้าเป็นศิษย์ฝึกงานของข้าระหว่างเรียนศิลปะการทำเกราะ Wild Leather เพราะ Wildvine ทั้งทรงพลังและแปรปรวน มันจึงเสริมคุณสมบัติที่สุ่มได้แต่แข็งแกร่งให้แก่เกราะที่แข็งแรงอยู่แล้ว ความรู้นี้กว่าข้าจะได้มาก็ไม่ง่าย\n\nค่าเริ่มต้นกระบวนการนี้คือ Thick Leather สิบชิ้น\n\nเมื่อเรียบร้อยแล้ว เราค่อยเริ่มงานที่เจ้าต้องทำเพื่อแลกกับแบบเหล่านั้น" },
        completion = { "5:1151914341:80614338 N 260:771713813:862562577", "ดีแล้ว {name} ข้ายินดีที่รับเจ้าเป็นศิษย์ฝึกงาน เจ้าเลือกได้อย่างชาญฉลาดสมกับเป็นช่างเครื่องหนัง เมื่อเจ้าชำนาญศิลปะ Wild Leather แล้ว ผู้ใช้เกราะหนังก็จะแห่มาหาเจ้า\n\nมาเริ่มงานกัน เจ้าอยากเริ่มตรงไหน?" },
        required = { [4304] = { "13:983336109:1264322130", "หนังหนา" } },
        steps = { { "13:983336109:1264322130", "หนังหนา" } },
    },
    [2855] = { -- Wild Leather Shoulders
        title = { "22:1481234814:2062184358", "เกราะไหล่ Wild Leather" },
        objective = { "80:2037245022:1490270437", "นำ Thick Armor Kits 6 ชิ้น และ Wildvine หนึ่งชิ้นไปให้ Jangdor Swiftstrider ใน Camp Mojache" },
        description = { "389:1433566429:708651352", "เกราะไหล่ Wild Leather ช่วยรองรับร่างกายผู้สวมได้ดีเยี่ยม ปกป้องทั้งต้นแขนและหัวไหล่ได้เหนือชั้น เช่นเดียวกับเกราะ Wild Leather ทุกชิ้น เมื่อเย็บ Wildvine เข้าไป มันจะประทับคุณสมบัติเสริมที่สุ่มได้แต่ทรงพลังอย่างยิ่งไว้ในชิ้นงาน\n\nสำหรับแบบนี้ ข้าต้องการ Thick Armor Kits หกชิ้นกับ Wildvine หนึ่งชิ้น เจ้าน่าจะหามาให้ได้ไม่ยากนัก" },
        progress = { "331:1846458247:236878935 N 50:1048538476:1331465759", "มี Thick Armor Kits หกชิ้นกับ Wildvine ที่ข้าต้องการหรือยัง?\n\nจงคิดว่าการทำชุดเสริมเกราะเป็นบทเรียนของการทำงานอย่างสม่ำเสมอและเชื่อถือได้ วิธีลงมืออย่างคงเส้นคงวาที่เจ้าได้ฝึกจากชุดเหล่านี้ ช่วยพัฒนาทักษะสำหรับงานละเอียดซับซ้อนที่ต้องใช้ในการทำเกราะ Wild Leather\n\nทุกบทเรียนมีจุดประสงค์ {name} เจ้าจึงควรตั้งใจเรียนรู้จากแต่ละบท" },
        completion = { "39:50719949:532841529 N 204:138011548:1340598888", "ชุดเสริมเกราะพวกนี้คุณภาพดีแน่นหนา {name} สิ่งหนึ่งที่ข้าเรียกร้องทั้งจากงานตัวเองและจากงานของศิษย์ที่ข้าสั่งสอนก็คือคุณภาพ\n\nเจ้าทำได้ดีจนสมควรได้รับแบบนี้ หวังว่ามันจะให้ผลตอบแทนแก่เจ้าเหมือนที่เคยให้ข้า" },
        required = { [8173] = { "15:1616630267:2060595163", "ชุดเสริมเกราะแบบหนา" }, [8153] = { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
        steps = { { "15:1616630267:2060595163", "ชุดเสริมเกราะแบบหนา" }, { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
    },
    [2856] = { -- Wild Leather Vest
        title = { "17:1622918041:894308115", "เสื้อกั๊ก Wild Leather" },
        objective = { "113:522767353:889469284", "นำ Turtle Scale Breastplates 2 ชิ้น, Turtle Scale Gloves 2 ชิ้น และ Wildvine หนึ่งชิ้นไปให้ Jangdor Swiftstrider ใน Camp Mojache" },
        description = { "448:151180162:996441271", "เสื้อกั๊ก Wild Leather เป็นชิ้นหลักของชุดเกราะ Wild Leather ทุกชุด โครงเสื้อกับ Wildvine ที่ถักทออยู่ภายในทำให้ได้ชิ้นงานที่ปกป้องลำตัวได้สูงสุด และเปิดทางให้เวทมนตร์อันทรงพลังไหลผ่านเนื้อเสื้อ\n\nสำหรับแบบนี้ ข้าต้องการ Turtle Scale Breastplates สองชิ้น, Turtle Scale Gloves สองชุด และ Wildvine หนึ่งชิ้น บทเรียนนี้ไม่ง่าย แต่เจ้ามีฝีมือพอจะทำสำเร็จแน่นอน" },
        progress = { "419:1291282678:1690219038", "มีเสื้อเกราะกับถุงมือ Turtle Scale อย่างละสองหรือยัง? แล้วอย่าลืม Wildvine ด้วย!\n\nแม้แต่แบบพื้นฐานที่สุดก็สอนให้เรารู้ว่า หลักการขึ้นรูปใช้กับเสื้อผ้าที่ยากขึ้นได้ดี ถึงจะเป็นของคนละชนิด รูปทรงของเสื้อเกราะ Turtle Scale ก็ช่วยเตรียมเจ้าให้พร้อมสำหรับรายละเอียดที่ต้องใช้ในการทำเสื้อกั๊ก Wild Leather\n\nเมื่อเจ้าก้าวหน้าไปตามบทเรียน ทักษะที่ข้าสอนจะกลายเป็นดั่งศิลปะ" },
        completion = { "38:756234351:4287159 N 229:171723233:1952507131", "ผลงานพวกนี้งดงามมาก {name} ฝีมือและความใส่ใจที่ใช้ทำ แสดงว่าเจ้าเลือกทุ่มเทให้กับงานเหล่านี้อย่างเต็มที่\n\nเจ้าทำตามที่ข้าขอครบ รางวัลจึงเป็นของเจ้า บัดนี้เจ้าจะได้เรียนรู้วิธีทำเสื้อกั๊ก Wild Leather!" },
        required = { [8189] = { "24:1134388533:1065446975", "เกราะอกเกล็ดเต่า" }, [8187] = { "19:1672709702:1863723700", "ถุงมือเกล็ดเต่า" }, [8153] = { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
        steps = { { "24:1134388533:1065446975", "เกราะอกเกล็ดเต่า" }, { "19:1672709702:1863723700", "ถุงมือเกล็ดเต่า" }, { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
    },
    [2857] = { -- Wild Leather Helmet
        title = { "19:137664708:193241029", "หมวกเกราะ Wild Leather" },
        objective = { "106:1454505611:714706431", "นำ Nightscape Tunics 2 ชิ้น, Nightscape Headbands 2 ชิ้น และ Wildvine หนึ่งชิ้นไปให้ Jangdor Swiftstrider ใน Camp Mojache" },
        description = { "438:242270537:1582900159", "หมวกเกราะ Wild Leather ปกป้องจุดสำคัญบนศีรษะได้เหนือชั้นโดยยังสวมสบาย เช่นเดียวกับเกราะ Wild Leather ทุกชิ้น Wildvine ที่ผสานเข้าไปจะประทับเวทมนตร์ทรงพลังแบบสุ่มให้โครงหมวก ผู้สวมเกราะหนังต้องอยากได้ชิ้นนี้แน่นอน!\n\nสำหรับแบบนี้ ข้าต้องการ Nightscape Tunics สองชิ้น, Nightscape Headbands 2 ชิ้น และ Wildvine หนึ่งชิ้น ผ่านบทเรียนนี้แล้วแบบก็เป็นของเจ้า!" },
        progress = { "384:211631458:579015968", "ข้าต้องการให้เจ้าทำเสื้อกับผ้าคาดศีรษะพวกนั้น และยังต้องใช้ Wildvine อีกชิ้น ก่อนจะแบ่งปันความรู้เรื่องหมวกเกราะ Wild Leather ให้\n\nอุปกรณ์ศีรษะเป็นที่ต้องการอย่างมากในหมู่นักผจญภัย ไม่ว่าจะเป็นผ้าคาดศีรษะที่ดูเรียบง่ายเหลือเชื่อ หรือหมวกเกราะที่ปิดคลุมทั้งหัว หลักการทำอุปกรณ์ศีรษะอันมีค่ายังคงเหมือนเดิม ไม่ว่าภายนอกจะดูเป็นอย่างไร" },
        completion = { "98:1298274890:1062112569 N 197:1014520910:1781775435", "อุปกรณ์ Nightscape ที่เจ้านำมาตรงตามข้อกำหนดที่ข้าให้ทุกประการ {name} ข้าคาดหวังจากช่างเครื่องหนังระดับเจ้าไม่น้อยไปกว่านี้อยู่แล้ว\n\nเจ้าคู่ควรกับเกียรติในการสร้างหมวกเกราะ Wild Leather ข้ายกแบบนี้ให้ด้วยความเต็มใจ และหวังว่าเจ้าจะใช้มันสร้างรายได้งดงาม" },
        required = { [8175] = { "16:250784020:367936008", "เสื้อคลุมตัวสั้น Nightscape" }, [8176] = { "19:1615819192:820948959", "ผ้าคาดหัว Nightscape" }, [8153] = { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
        steps = { { "16:250784020:367936008", "เสื้อคลุมตัวสั้น Nightscape" }, { "19:1615819192:820948959", "ผ้าคาดหัว Nightscape" }, { "8:542661520:1452607669", "เถาวัลย์ Wildvine" } },
    },
    [2858] = { -- Wild Leather Boots
        title = { "18:1445012375:1765111947", "รองเท้าบูต Wild Leather" },
        objective = { "102:1210111819:59597788", "นำ Nightscape Pants 2 ชิ้น, Nightscape Boots 2 ชิ้น และ Wildvines 2 ชิ้นไปให้ Jangdor Swiftstrider ใน Camp Mojache" },
        description = { "44:375159943:2131129377 N 447:339281742:46364743", "ความรู้เรื่องเกราะ Wild Leather ของเจ้าเพิ่มพูนขึ้น {name} แต่ยังมีให้เรียนอีก\n\nรองเท้าบูต Wild Leather เป็นรากฐานของทุกชุด ทำขึ้นเพื่อโอบรับเท้าอย่างสบาย พร้อมประคองป้องกันอันตรายจากการผจญภัย พื้นรองเท้านุ่มยังเป็นพรแก่ผู้ต้องการย่างก้าวอย่างเงียบเชียบ\n\nสำหรับแบบนี้ ข้าต้องการให้ทำ Nightscape Pants สองชิ้นกับ Nightscape Boots สองชิ้น และต้องใช้ Wildvine สองชิ้นด้วย... ไม่ใช่แค่ชิ้นเดียว เมื่อมีของเหล่านี้แล้ว เราค่อยดำเนินการต่อ" },
        progress = { "89:429831863:778278527 N 316:1508813867:737489790", "เจ้าต้องส่งกางเกง รองเท้าบูต และ Wildvine ให้ข้าก่อนจึงจะได้เรียนแบบนี้ {name} ทำตามที่ข้าขอแล้วหรือยัง?\n\nตั้งแต่รองเท้าบูตคู่แรกที่เราเรียนทำ เราก็เริ่มเข้าใจว่ารองเท้าคุณภาพดีต้องรักษาสมดุลอันละเอียดอ่อนระหว่างความสบายและการใช้งาน เมื่อมีทั้งสองอย่าง เราจึงทำอุปกรณ์ที่ช่วยให้ผู้สวมลืมความเหนื่อยล้าซึ่งอาจทำให้ผู้สวมของคุณภาพต่ำกว่าหมดแรงได้" },
        completion = { "139:1211044125:1839566768", "อีกครั้งที่เจ้าผลิตชิ้นงานด้วยฝีมือของมืออาชีพผู้ช่ำชอง เจ้าคู่ควรกับทั้งแบบนี้และคำแสดงความยินดีจากข้า" },
        required = { [8153] = { "8:542661520:1452607669", "เถาวัลย์ Wildvine" }, [8193] = { "16:1788766222:1292459590", "กางเกง Nightscape" }, [8197] = { "16:1081433075:1495918389", "รองเท้าบูต Nightscape" } },
        objectiveLabels = {
            item = { ["Wildvine"] = "เถาวัลย์ Wildvine", ["Nightscape Pants"] = "กางเกง Nightscape", ["Nightscape Boots"] = "รองเท้าบูต Nightscape" },
        },
    },
    [2859] = { -- Wild Leather Leggings
        title = { "21:1483154169:706164949", "กางเกงเกราะ Wild Leather" },
        objective = { "108:1178659630:7423827", "นำ Turtle Scale Helms 2 ชิ้น, Turtle Scale Bracers 2 ชิ้น และ Wildvines 2 ชิ้นไปให้ Jangdor Swiftstrider ใน Camp Mojache" },
        description = { "46:954011419:1577913732 N 389:544968289:576860131", "เจ้าพร้อมฝึกบทเรียนที่ซับซ้อนขึ้นจนชำนาญแล้ว {name} กางเกงเกราะ Wild Leather เป็นเครื่องหนังที่ทนทานและทรงพลังที่สุดกลุ่มหนึ่ง ทั้งเอว ต้นขา น่อง และจุดสำคัญล้วนได้รับการปกป้องอย่างมาก เมื่อรวมกับคุณสมบัติที่ Wildvine เสริมให้ นักผจญภัยที่เป็นเจ้าของจะขอบใจเจ้าทุกครั้งที่พบกัน\n\nหากต้องการแบบนี้ ข้าต้องการ Turtle Scale Helms สองชิ้น, Turtle Scale Bracers สองชิ้น และ Wildvine สองชิ้น" },
        progress = { "384:1176890579:1682594070", "เตรียมปลอกแขนกับหมวกเกราะ Turtle Scale พร้อมหรือยัง? อย่าลืม Wildvine สองชิ้นที่ข้าต้องการด้วย\n\nถึงตอนนี้ เจ้าคงเริ่มเห็นพลังที่ซ่อนอยู่ในเกราะ Wild Leather แล้ว เกราะที่นำไปใช้ได้อย่างไร้ขอบเขตนั้นแทบประเมินค่ามิได้สำหรับช่างเครื่องหนัง ข้อจำกัดมีเพียงปริมาณทรัพยากรที่ใช้ทำ ไม่ใช่คุณภาพของผลงานที่เสร็จแล้ว!" },
        completion = { "104:506137564:1651492222 N 161:1678196560:1561758661", "เจ้าทำงานของข้าได้อย่างไร้ที่ติอีกแล้ว บางทีสักวันข้าอาจต้องไปขอความรู้จากเจ้าเสียเอง ว่าไหม {name}?\n\nนี่คือแบบกางเกงเกราะ พร้อมคำขอบใจจากข้า จดจำความรู้นี้ไว้ แล้วให้ผลงานที่เสร็จแล้วแสดงฝีมืออันน่าประทับใจของเจ้า!" },
        required = { [8153] = { "8:542661520:1452607669", "เถาวัลย์ Wildvine" }, [8191] = { "17:1865123908:1887807128", "หมวกเกราะเกล็ดเต่า" }, [8198] = { "20:596847337:1034256254", "ปลอกแขนเกล็ดเต่า" } },
        objectiveLabels = {
            item = { ["Wildvine"] = "เถาวัลย์ Wildvine", ["Turtle Scale Helm"] = "หมวกเกราะเกล็ดเต่า", ["Turtle Scale Bracers"] = "ปลอกแขนเกล็ดเต่า" },
        },
    },
    [2860] = { -- Master of the Wild Leather
        title = { "26:654236145:1665346798", "ผู้เชี่ยวชาญ Wild Leather" },
        objective = { "72:1960806571:1422674486", "นำ Jangdor's Letter ไปให้ Una ช่างเครื่องหนังผู้เชี่ยวชาญแห่ง Thunder Bluff" },
        description = { "N 494:983342884:771302141", "{name} เจ้าเรียนรู้ทุกอย่างที่ข้าสอนได้แล้ว แต่ยังเหลือแบบเกราะ Wild Leather อีกแบบหนึ่ง ข้าจะไม่ให้เจ้าตรากตรำโดยไม่จำเป็นเพื่อแลกมัน เจ้าพิสูจน์ว่าคู่ควรแล้ว และยิ่งกว่านั้นเสียอีก ทว่าแบบนี้เป็นสิ่งที่ข้าแบ่งปันให้ตามใจไม่ได้\n\nอาจารย์ผู้พาข้าเข้าสู่งานฝีมือนี้ต่างหากที่ต้องเป็นผู้มอบรางวัล นำข้อความนี้ไปให้ Una เธอสอนงานเครื่องหนังอยู่ใน Thunder Bluff ให้เธออ่านจดหมาย แล้วให้เธอยอมรับเจ้าเป็นผู้มีฝีมือทัดเทียม เช่นเดียวกับที่ข้ายอมรับ" },
        progress = { "11:927657569:725753248 R 151:1677309450:2127593124", "สวัสดี {race}... ดูจากท่าที ข้าก็บอกได้ว่าเจ้าเป็นช่างเครื่องหนังเช่นเดียวกับข้า เจ้ามาเรียนรู้จากฝีมือข้า หรือมีธุระอื่น?" },
        completion = { "440:655901004:25698217", "อา ใช่ Jangdor ส่งเจ้ามา ข้ายินดีที่ศิษย์ยอดฝีมือคนหนึ่งของข้า ตอนนี้มีศิษย์ของตัวเองแล้ว\n\nความทุ่มเทและพรสวรรค์ด้านเครื่องหนังของเขาน่าประทับใจนัก การที่เขาชมเจ้าในจดหมายถึงเพียงนี้เป็นการแสดงความเคารพที่ข้ายอมรับ\n\nข้ารู้ว่าเขาสอนศิลปะ Wild Leather ให้เจ้าแล้ว ให้ข้าฝึกเจ้าให้จบด้วยแบบนี้ จงใช้ให้คุ้มค่า มีเพียงไม่กี่คนในโลกที่รู้ความลับของผ้าคลุม Wild Leather" },
    },
    [4161] = { -- Recipe of the Kaldorei
        title = { "22:782074190:821379409", "ตำรับอาหารแห่ง Kaldorei" },
        objective = { "51:21851789:1648943436", "รวบรวม Small Spider Legs 7 ชิ้นให้ Zarrin ใน Dolanaar" },
        description = { "155:641657392:1863663918 C 2:11340:5796 N 256:1040829900:2083142316 N 84:1108664157:404661990", "นานมาแล้ว ไนต์เอลฟ์ถูกเรียกว่า Kaldorei ชื่อที่หมายถึง \"บุตรแห่งดวงดาว\" การเรียนรู้อดีตเป็นก้าวสำคัญบนเส้นทางของ{class}อย่างเจ้า {name} จงตั้งใจฟังสิ่งที่ข้าจะบอก\n\nชาว Kaldorei ภูมิใจในสายสัมพันธ์อันกลมกลืนกับธรรมชาติมาเสมอ นั่นหมายความว่าเราจะรับจากธรรมชาติเพียงเท่าที่จำเป็น และตอบแทนคืนอย่างเหมาะสม สมดุลนี้มอบสิ่งต่าง ๆ ให้เรามากมาย {name}\n\nออกไปรวบรวม Small Spider Legs เจ็ดชิ้น ไม่เกินนั้น แล้วกลับมาหาข้า" },
        progress = { "22:1278172681:1843188412 N 85:397116242:797824397", "จงจดจำเรื่องสมดุลไว้ {name} ข้าต้องการให้เจ้าเข้าใจและเห็นอกเห็นใจผืนป่าที่มีชีวิตอย่างลึกซึ้ง" },
        completion = { "45:1103119640:679114418 N 104:1348732860:1782414692", "จงจดจำสิ่งที่ข้าสอนเจ้าในวันนี้ไว้เสมอ {name} เจ้าเป็นส่วนหนึ่งของสมดุลที่ชาวไนต์เอลฟ์พยายามรักษาให้คงอยู่ แม้ในยามยากลำบาก" },
        required = { [5465] = { "16:643011043:1694172363", "ขาแมงมุมขนาดเล็ก" } },
        steps = { { "16:643011043:1694172363", "ขาแมงมุมขนาดเล็ก" } },
    },
    [5141] = { -- Dragonscale Leatherworking
        title = { "26:91690089:97422505", "งานเครื่องหนังสาย Dragonscale" },
        objective = { "367:1998062703:773236790", "นำ Tough Scorpid Breastplates 2 ชิ้น, Tough Scorpid Gloves 2 ชิ้น และ Worn Dragonscales 10 ชิ้นไปให้ Peter Galen ใน Azshara\n\nการทำเควสนี้สำเร็จจะเปิดให้เจ้าเรียนศิลปะการทำเครื่องหนังสาย Dragonscale\n\nเมื่อทำเควสนี้สำเร็จ เจ้าจะเรียนสาย Elemental และ Tribal ไม่ได้ จงแน่ใจว่านี่คือเส้นทางที่เจ้าต้องการก่อนทำให้สำเร็จ" },
        description = { "493:963949625:610585014", "งานเครื่องหนังสาย Dragonscale ไม่ง่าย แต่คุ้มค่าอย่างยิ่ง ข้าจะสอนวิธีทำเกราะถักชั้นดีนี้ให้ หากเจ้ายอมรับเงื่อนไขบางประการ\n\nการเลือกเส้นทางนี้หมายความว่าเจ้าตกลงจะไม่เรียนงานเครื่องหนังสาย Elemental หรือ Tribal เลย ในจุดสูงสุดของงานฝีมือนี้ มีที่ให้เชี่ยวชาญเพียงหนึ่งในสามสายเท่านั้น นอกจากนี้ ข้าต้องการตัวอย่างงานเกราะ Scorpid ที่ดีที่สุดของเจ้า สุดท้าย ข้าต้องการหลักฐานว่าเจ้าหาวัตถุดิบหลักของงานนี้ได้ นั่นคือเกล็ดของเหล่ามังกร" },
        progress = { "207:1047609626:2063432834", "หากเจ้าพร้อมตัดสินใจถาวรด้วยการเป็นช่างเครื่องหนังสาย Dragonscale ข้าก็พร้อมรับเจ้าเป็นศิษย์ เพียงนำของที่ข้าขอมาให้ แล้วเราจะเริ่มฝึกกัน" },
        completion = { "338:1918133446:511039920", "ข้าขอยอมรับเลย การตัดสินใจถาวรอย่างที่เจ้าทำต้องอาศัยใจแน่วแน่ ข้ารับรองว่างานเครื่องหนังสาย Dragonscale จะเป็นเส้นทางที่สร้างรายได้และคุ้มค่าให้เจ้า\n\nหากต้องการฝึกศิลปะนี้ต่อในภายหน้า เพียงมาคุยกับข้า แล้วข้าจะสอนความรู้ที่เจ้ายังไม่เคยเรียนให้" },
        required = { [8165] = { "16:910941412:1909423270", "เกล็ดมังกรสึก" }, [8203] = { "25:1830799748:634832450", "เกราะอกสกอร์ปิดแบบทนทาน" }, [8204] = { "20:489766077:1441117373", "ถุงมือสกอร์ปิดแบบทนทาน" } },
        objectiveLabels = {
            item = { ["Worn Dragonscale"] = "เกล็ดมังกรสึก", ["Tough Scorpid Breastplate"] = "เกราะอกสกอร์ปิดแบบทนทาน", ["Tough Scorpid Gloves"] = "ถุงมือสกอร์ปิดแบบทนทาน" },
        },
    },
    [5143] = { -- Tribal Leatherworking
        title = { "21:1314343308:1443454910", "งานเครื่องหนังสาย Tribal" },
        objective = { "342:1983789547:528565033", "นำ Wild Leather Vest และ Wild Leather Helmet ไปให้ Caryssia Moonhunter ใน Feralas\n\nการทำเควสนี้สำเร็จจะเปิดให้เจ้าเรียนศิลปะการทำเครื่องหนังสาย Tribal\n\nเมื่อทำเควสนี้สำเร็จ เจ้าจะเรียนสาย Dragonscale และ Elemental ไม่ได้ จงแน่ใจว่านี่คือเส้นทางที่เจ้าต้องการก่อนทำให้สำเร็จ" },
        description = { "218:232322726:1394472260 C 259:1162132609:87983785", "การเรียนงานเครื่องหนังสาย Tribal ต้องเข้าใจพลังดั้งเดิมที่เป็นแก่นแท้ของธรรมชาติ ข้ารู้ว่าเจ้าเชี่ยวชาญศิลปะการทำเกราะ Wild Leather แล้ว และข้ายินดีฝึกเจ้าให้สำเร็จ\n\nจงรู้ไว้ {class} การเลือกเส้นทางนี้หมายความว่าเจ้าตกลงจะไม่เรียนงานเครื่องหนังสาย Dragonscale หรือ Elemental เลย เจ้าฝึกได้เพียงหนึ่งในสามศิลปะเท่านั้น นอกจากนี้ ให้นำตัวอย่างเกราะ Wild Leather ที่ดีที่สุดของเจ้ามาให้ จากนั้นเราจะเริ่มฝึกสู่ความเชี่ยวชาญ" },
        progress = { "187:1049736942:571334637", "ธรรมชาติคือพลังที่เจ้าต้องเอาใจก่อนจะหวังเรียนรู้วิธีน้อมพลังนั้นมาอยู่ในเครื่องหนังของเจ้า จงนำเครื่องบูชาของเจ้าต่อพลังนี้มาให้ข้า แล้วข้าจะทำให้แน่ใจว่าเสียงของเจ้าถูกได้ยิน" },
        completion = { "309:1193263498:1267322235", "เจ้ามอบเครื่องบูชาที่ดีที่สุดแล้ว อีกไม่นานธรรมชาติจะยอมให้เจ้าน้อมพลังมาใช้ เมื่อข้าสอนเจ้าเสร็จ ผลงานของเจ้าจะกลายเป็นพลังแห่งธรรมชาติในตัวมันเอง\n\nหากต้องการฝึกศิลปะนี้ต่อในภายหน้า เพียงมาคุยกับข้า แล้วข้าจะสอนความรู้ที่เจ้ายังไม่เคยเรียนให้" },
        required = { [8211] = { "17:1622918041:894308115", "เสื้อเกราะหนังสัตว์ป่า" }, [8214] = { "19:137664708:193241029", "หมวกเกราะหนังสัตว์ป่า" } },
        objectiveLabels = {
            item = { ["Wild Leather Vest"] = "เสื้อเกราะหนังสัตว์ป่า", ["Wild Leather Helmet"] = "หมวกเกราะหนังสัตว์ป่า" },
        },
    },
    [5144] = { -- Elemental Leatherworking
        title = { "24:948301811:1134379086", "งานเครื่องหนังสาย Elemental" },
        objective = { "368:1460470844:1303537531", "นำ Heart of Fire 2 ชิ้น, Globe of Water 2 ชิ้น, Core of Earth 2 ชิ้น และ Breath of Wind 2 ชิ้นไปให้ Sarah Tanner ใน Searing Gorge\n\nการทำเควสนี้สำเร็จจะเปิดให้เจ้าเรียนศิลปะการทำเครื่องหนังสาย Elemental\n\nเมื่อทำเควสนี้สำเร็จ เจ้าจะเรียนสาย Dragonscale และ Tribal ไม่ได้ จงแน่ใจว่านี่คือเส้นทางที่เจ้าต้องการก่อนทำให้สำเร็จ" },
        description = { "173:1739824600:1509085401 C 307:294698030:886084361", "งานเครื่องหนังสาย Elemental คือสิ่งที่ข้าเชี่ยวชาญ หากเจ้ายอมเปิดใจต่อพลังอันยิ่งใหญ่ของสสาร ข้าจะแบ่งปันทุกอย่างที่มีให้เรียนรู้\n\nจงรู้ไว้ {class} การเลือกเส้นทางนี้หมายความว่าเจ้าตกลงจะไม่เรียนงานเครื่องหนังสาย Dragonscale หรือ Tribal เลย เจ้าฝึกได้เพียงหนึ่งในสามศิลปะเท่านั้น นอกจากนี้ ข้าต้องการหลักฐานที่เพียงพอว่าเจ้าสอดคล้องกับธาตุแห่งธรรมชาติ ดังนั้น ให้นำแก่นแท้อันบริสุทธิ์ที่สุดของไฟ น้ำ ดิน และลมมาให้ข้า" },
        progress = { "217:880557211:2096718104", "การทำเกราะที่ใช้หนังชนิดนี้ต้องอาศัยความอดทนและทุ่มเท เมื่อเจ้าฝากชะตาไว้กับเหล่าธาตุแล้ว ก็จะหันหลังให้ไม่ได้ นำหลักฐานความคู่ควรมาให้ข้า แล้วเราจะเริ่มกัน" },
        completion = { "282:1348678838:862208086", "เจ้าเลือกเส้นทางแล้ว และเหล่าธาตุยอมรับเจ้า เมื่อข้าสอนเจ้าเสร็จ เจ้าจะมีพลังใจที่จะสร้างเครื่องหนังชั้นเลิศที่สุด\n\nหากต้องการฝึกศิลปะนี้ต่อในภายหน้า เพียงมาคุยกับข้า แล้วข้าจะสอนความรู้ที่เจ้ายังไม่เคยเรียนให้" },
        required = { [7077] = { "13:1100399464:1542783043", "หัวใจแห่งไฟ" }, [7079] = { "14:1693715973:1569041085", "ลูกแก้วแห่งน้ำ" }, [7075] = { "13:2095447005:1016735003", "แก่นธาตุดิน" }, [7081] = { "14:414950436:1184012937", "ลมหายใจแห่งสายลม" } },
        objectiveLabels = {
            item = { ["Heart of Fire"] = "หัวใจแห่งไฟ", ["Globe of Water"] = "ลูกแก้วแห่งน้ำ", ["Core of Earth"] = "แก่นธาตุดิน", ["Breath of Wind"] = "ลมหายใจแห่งสายลม" },
        },
    },
    [5145] = { -- Dragonscale Leatherworking
        title = { "26:91690089:97422505", "งานเครื่องหนังสาย Dragonscale" },
        objective = { "378:1511462216:233420250", "นำ Tough Scorpid Breastplates 2 ชิ้น, Tough Scorpid Gloves 2 ชิ้น และ Worn Dragonscales 10 ชิ้นไปให้ Thorkaf Dragoneye ใน Badlands\n\nการทำเควสนี้สำเร็จจะเปิดให้เจ้าเรียนศิลปะการทำเครื่องหนังสาย Dragonscale\n\nเมื่อทำเควสนี้สำเร็จ เจ้าจะเรียนสาย Elemental และ Tribal ไม่ได้ จงแน่ใจว่านี่คือเส้นทางที่เจ้าต้องการก่อนทำให้สำเร็จ" },
        description = { "493:963949625:610585014", "งานเครื่องหนังสาย Dragonscale ไม่ง่าย แต่คุ้มค่าอย่างยิ่ง ข้าจะสอนวิธีทำเกราะถักชั้นดีนี้ให้ หากเจ้ายอมรับเงื่อนไขบางประการ\n\nการเลือกเส้นทางนี้หมายความว่าเจ้าตกลงจะไม่เรียนงานเครื่องหนังสาย Elemental หรือ Tribal เลย ในจุดสูงสุดของงานฝีมือนี้ มีที่ให้เชี่ยวชาญเพียงหนึ่งในสามสายเท่านั้น นอกจากนี้ ข้าต้องการตัวอย่างงานเกราะ Scorpid ที่ดีที่สุดของเจ้า สุดท้าย ข้าต้องการหลักฐานว่าเจ้าหาวัตถุดิบหลักของงานนี้ได้ นั่นคือเกล็ดของเหล่ามังกร" },
        progress = { "207:1047609626:2063432834", "หากเจ้าพร้อมตัดสินใจถาวรด้วยการเป็นช่างเครื่องหนังสาย Dragonscale ข้าก็พร้อมรับเจ้าเป็นศิษย์ เพียงนำของที่ข้าขอมาให้ แล้วเราจะเริ่มฝึกกัน" },
        completion = { "338:1918133446:511039920", "ข้าขอยอมรับเลย การตัดสินใจถาวรอย่างที่เจ้าทำต้องอาศัยใจแน่วแน่ ข้ารับรองว่างานเครื่องหนังสาย Dragonscale จะเป็นเส้นทางที่สร้างรายได้และคุ้มค่าให้เจ้า\n\nหากต้องการฝึกศิลปะนี้ต่อในภายหน้า เพียงมาคุยกับข้า แล้วข้าจะสอนความรู้ที่เจ้ายังไม่เคยเรียนให้" },
        required = { [8165] = { "16:910941412:1909423270", "เกล็ดมังกรสึก" }, [8203] = { "25:1830799748:634832450", "เกราะอกสกอร์ปิดแบบทนทาน" }, [8204] = { "20:489766077:1441117373", "ถุงมือสกอร์ปิดแบบทนทาน" } },
        objectiveLabels = {
            item = { ["Worn Dragonscale"] = "เกล็ดมังกรสึก", ["Tough Scorpid Breastplate"] = "เกราะอกสกอร์ปิดแบบทนทาน", ["Tough Scorpid Gloves"] = "ถุงมือสกอร์ปิดแบบทนทาน" },
        },
    },
