    [8307] = { -- Desert Recipe
        title = { "13:32243469:1329967193", "ตำรับอาหารทะเลทราย" },
        objective = { "101:405437948:2086621872", "ค้นหาข้อมูลวิธีทำอาหารจาก Sandworm Meat ที่ค่าย Twilight's Hammer ทางตะวันตกของ Cenarion Hold" },
        description = { "500:862667542:1923701727", "จะว่าไปแล้ว การปรับตัวใช้ชีวิตในทะเลทรายนั้นยากลำบากมาก ข้าไม่ได้คิดถึงแค่นกกับต้นไม้ใน Auberdine เท่านั้น สภาพแห้งแล้งที่นี่ยังทำให้อาหารที่เราเลือกกินได้มีจำกัดมาก ข้ากำลังพยายามเรียนรู้เรื่องสมุนไพรทะเลทราย แต่ก็มีไม่กี่ชนิด\n\nข้าเห็นกลุ่ม Twilight's Hammer จากค่ายทางตะวันตกของที่นี่ล่าหนอนทรายเป็นอาหาร แต่เนื้อหนอนทรายขมมากจนข้านึกไม่ออกว่าพวกเขาทำให้กินอร่อยได้อย่างไร หากเจ้าไปค่ายของพวกเขา ก็ช่วยสังเกตแล้วบอกข้าด้วยถ้าได้รู้อะไรมา" },
        completion = { "156:1982924785:1002555650", "หนังสือเล่มนี้มีสูตรอาหารทั่วไปหลายสูตรและสูตรแปลก ๆ อีกไม่กี่สูตร หลังเปิดดูอยู่สองสามวินาที เจ้าก็พบสูตรที่ใช้เนื้อหนอนทราย" },
    },
    [8313] = { -- Sharing the Knowledge
        title = { "21:1334556126:489373766", "แบ่งปันความรู้" },
        objective = { "69:37669139:31301400", "นำ Torn Recipe Page ไปให้ Calandrath ที่โรงเตี๊ยมใน Cenarion Hold" },
        description = { "218:504050494:1875290313", "แม้สูตรทำอาหารจากเนื้อหนอนทรายจะอ่านออก แต่ก็อ้างถึงสมุนไพรและเครื่องเทศที่เจ้าไม่เคยได้ยินชื่อ Calandrath อาจรู้จักพืชที่เติบโตในทะเลทรายมากพอจะเข้าใจสูตรนี้" },
        progress = { "64:1503048908:1001806351", "เรียนรู้สูตรมาแล้วหรือ? หวังว่าเจ้าจะไม่เก็บไว้คนเดียวนะ!" },
        completion = { "169:1112643494:662776370", "ขอดูหน่อย...\n\nดูเหมือนไม่ยากนัก พวกเขามีชื่อเรียกสมุนไพรบางอย่างเป็นของตัวเอง แต่ก็เดาได้ไม่ยากว่าเป็นอะไร มาสิ ให้ข้าสอนเจ้า!" },
    },
    [8317] = { -- Kitchen Assistance
        title = { "18:497113988:1894793571", "ช่วยงานในครัว" },
        objective = { "72:1551680965:597552861", "Calandrath ที่ Cenarion Hold ต้องการ Smoked Desert Dumplings หนึ่งชุดจำนวน 10 ชิ้น" },
        description = { "185:1571386311:1515741538", "สูตรนั้นต้องได้ใช้ประโยชน์แน่ ข้าควรลงมือแล้ว จะได้มีเกี๊ยวทะเลทรายรมควันพร้อมเสิร์ฟวันนี้ ข้าต้องการคนช่วยทำสักหน่อย แล้วข้าจะตอบแทนให้คุ้มค่า" },
        progress = { "37:401919725:1405726988", "เกี๊ยวพวกนั้นไปถึงไหนแล้ว?" },
        completion = { "141:1368744572:2122377150", "ยอดเยี่ยม! เจ้าช่วยชีวิตข้าไว้เลย เกี๊ยวพวกนี้ออกมาอร่อยทีเดียว ไม่คิดจริง ๆ ว่าพวก Twilight's Hammer จะมีรสนิยมดีขนาดนี้" },
        required = { [20452] = { "23:2106119058:2085597598", "เกี๊ยวทะเลทรายรมควัน" } },
        objectiveLabels = {
            item = { ["Smoked Desert Dumplings"] = "เกี๊ยวทะเลทรายรมควัน" },
        },
    },
