        title = { "19:824585950:1753297078", "เหล่าผู้นำแห่งเขี้ยว" },
        objective = { "93:1337048519:964520180", "นำ Gems of Cobrahn, Anacondra, Pythas และ Serpentis ไปให้ Nara Wildmane ใน Thunder Bluff" },
        description = { "417:1268245909:49496767 N 61:1333231788:360814194", "เหล่าดรูอิดใน Wailing Caverns ผู้เรียกตนว่า Druids of the Fang เป็นพวกผิดเพี้ยน เดิมพวกเขาเป็นส่วนหนึ่งของคณะดรูอิดผู้สูงส่งที่วางแผนเยียวยา Barrens แต่ตอนนี้กลับต้องการเปลี่ยนดินแดนนั้นให้เหมือนความฝันบิดเบี้ยวของตน\n\nDruids of the Fang มีผู้นำสี่คน แต่ละคนครอบครองอัญมณีแห่งความฝัน แม้ยามนี้ใบหน้าของพวกเขายังหลอกหลอนข้า! จงปราบเหล่าผู้นำและนำอัญมณีมาให้ แล้ว Barrens อาจได้รู้จักความสงบอีกครั้ง\n\nไปเถอะ {name} เจ้าจะพบพวกเขาซ่อนตัวอยู่ลึกใน Wailing Caverns" },
        progress = { "36:1526581593:1199146214 N 68:359014295:123299587", "ความทรงจำจากฝันร้ายยังหลอกหลอนข้า {name} เจ้าปราบผู้นำแห่งเขี้ยวและได้อัญมณีของพวกเขามาหรือยัง?" },
        completion = { "18:1677330748:1750015206 N 170:2011029427:1340417900 N 76:364416155:580976030", "เจ้าทำสำเร็จแล้ว {name} เจ้าสังหารเหล่าผู้นำของ Druids of the Fang ใบหน้าชั่วร้ายของพวกเขาไม่รบกวนความฝันข้าอีก และเจ้าได้ช่วย Barrens ให้พ้นจากอนาคตต้องสาป\n\nข้าขอบใจเจ้า {name} ขอบใจในนามของตัวข้า เหล่าดรูอิดแห่ง Thunder Bluff และผืนแผ่นดิน" },
        required = { [9738] = { "14:1124441738:216977195", "อัญมณีของ Cobrahn" }, [9739] = { "16:1253459051:1952073595", "อัญมณีของ Anacondra" }, [9740] = { "13:2112661851:1730464758", "อัญมณีของ Pythas" }, [9741] = { "16:1105363394:1329277361", "อัญมณีของ Serpentis" } },
        steps = { { "14:1124441738:216977195", "อัญมณีของ Cobrahn" }, { "16:1253459051:1952073595", "อัญมณีของ Anacondra" }, { "13:2112661851:1730464758", "อัญมณีของ Pythas" }, { "16:1105363394:1329277361", "อัญมณีของ Serpentis" } },
    },
    [959] = { -- Trouble at the Docks
        title = { "20:433450464:1884172893", "ปัญหาที่ท่าเรือ" },
        objective = { "145:1646160226:59543107", "Crane Operator Bigglefuzz ใน Ratchet ต้องการให้เจ้าชิงขวด 99-Year-Old Port คืนจาก Mad Magglish ซึ่งซ่อนอยู่ใน Wailing Caverns" },
        description = { "496:691839903:55929805", "อุ๊บส์!\n\nเกิดอุบัติเหตุนิดหน่อย อย่างที่เห็น! สินค้าที่ส่งมาจาก Booty Bay เมื่อเช้ามีมหาศาล ข้าบอกว่ามหาศาลเลยนะ! ไม่เคยเห็นลังเยอะขนาดนั้น ข้าอยากเร่งงาน จึงเริ่มขนลงทีละมากเกินกำลัง แล้วทุกอย่างก็พังครืนลงมา\n\nก่อนจะรู้ตัวว่าเกิดอะไรขึ้น ข้าเห็นเจ้า Mad Magglish ตัวแสบนั่นวิ่งหนีไปพร้อมไวน์พอร์ตอายุ 99 ปีขวดหนึ่ง ข้าไล่ตามไปถึง Wailing Caverns แต่ไม่มีทางยอมเข้าไปในนั้นแน่\n\nบางทีเจ้าอาจกล้าพอจะไปหาเขา?" },
        progress = { "324:1079716098:1116088994", "นายท่าคอยเล่นงานข้ามาตั้งแต่ Mad Magglish ขโมยไวน์พอร์ตอายุ 99 ปีไป ข้าคิดว่าขวดนั้นตั้งใจส่งเป็นของขวัญให้ Gazlowe จากใครอื่นไม่ได้ นอกจาก Baron Revilgaz เอง\n\nหากเจ้ากล้าและอดทนพอจะตามหา Mad Magglish แล้วเอาไวน์คืนมา ข้าจะจัดรางวัลงาม ๆ ให้" },
        completion = { "121:1625329518:1693982513 N 21:394275742:1621542373", "ยอดเยี่ยม! พอดีกับที่ข้าเกือบจะตกงานอยู่แล้ว! ข้าจะจัดการส่งของขวัญนี้ให้ Gazlowe ทันที\n\nขอบใจ {name} ทำได้งดงามจริง ๆ!" },
        required = { [5334] = { "16:435796542:1072755605", "ไวน์พอร์ตบ่ม 99 ปี" } },
        steps = { { "16:435796542:1072755605", "ไวน์พอร์ตบ่ม 99 ปี" } },
    },
    [962] = { -- Serpentbloom
        title = { "12:420704760:147653440", "Serpentbloom" },
        objective = { "71:801556437:395143245", "Apothecary Zamah ใน Thunder Bluff ต้องการให้เจ้ารวบรวม Serpentbloom 10 ชิ้น" },
        description = { "119:56971338:144764283 N 363:687141247:1750689070", "Royal Apothecary Society ซึ่งมีฐานอยู่ใน Undercity อันยิ่งใหญ่แห่ง Lordaeron ส่งข้ามาทำงานเฉพาะอย่างที่นี่ {name} บางทีเจ้าอาจอยากช่วยข้า และช่วย Dark Lady ในความพยายามผลักดัน Forsaken ให้ก้าวหน้าด้วย\n\nไม่นานมานี้ข้าศึกษาพืชหายากชื่อ Serpentbloom ข้าเชื่อว่าหากมีปริมาณมากขึ้น สมุนไพรนี้จะมีศักยภาพมหาศาล\n\nน่าเสียดายที่ Serpentbloom พบได้เฉพาะซอกมืดที่สุดของ Wailing Caverns ระบบถ้ำอันตรายใน Barrens เท่านั้น" },
        progress = { "137:24539034:239956412", "ข้าอยากรู้เหลือเกินว่าเจ้าจะรวบรวม Serpentbloom จาก Wailing Caverns ได้มากพอไหม ข้าส่งคนไปทำงานนี้หลายคนแล้ว แต่ยังไม่มีใครกลับมา" },
        completion = { "44:2109289439:1755523878 N 1:46:46", "อา ตัวอย่างชั้นยอด เจ้าทำได้ดี {name}" },
        required = { [5339] = { "12:420704760:147653440", "ดอก Serpentbloom" } },
        steps = { { "12:420704760:147653440", "ดอก Serpentbloom" } },
    },
    [1014] = { -- Arugal Must Die
        title = { "15:1375454633:836917475", "Arugal ต้องตาย" },
        objective = { "68:932639790:1423951238", "ฆ่า Arugal แล้วนำศีรษะของเขาไปให้ Dalar Dawnweaver ที่ Sepulcher" },
        description = { "183:1751186791:792815194 N 200:1501223354:1372095575", "Arugal ยังอยู่ใน Shadowfang Keep เราจะยึด Silverpine เป็นฐานยุทธศาสตร์ให้ Dark Lady ไม่ได้ จนกว่า Arugal จะถูกสังหาร\n\nข้าจะจัดการให้เวทมนตร์ของเขาถูกกวาดล้าง {name} แต่ข้ามอบหน้าที่ส่ง Arugal ไปพบความตายที่สมควรได้รับให้เจ้า\n\nเดินทางไป Shadowfang Keep แล้วหยุดคาถาชั่วร้ายของ Arugal ให้สิ้นซาก นำศีรษะพ่อมดชั่วนั่นมาให้ข้า!" },
        progress = { "81:976738820:502599155", "เมื่อ Arugal ตาย เราก็จะเสริมอำนาจของ Dark Lady ใน Lordaeron ได้มากขึ้น" },
        completion = { "116:2117991619:740800498 N 34:1073026488:260809333", "ในที่สุด Silverpine Forest ก็พ้นจากเงื้อมมือเจ้า Arugal สารเลวนั่น เจ้าทำคุณความดีใหญ่หลวงให้ Dark Lady {name} ความมุ่งมั่นของเจ้าจะได้รับรางวัล" },
        required = { [5442] = { "14:719623148:556262553", "ศีรษะของ Arugal" } },
        steps = { { "14:719623148:556262553", "ศีรษะของ Arugal" } },
    },
    [1098] = { -- Deathstalkers in Shadowfang
        title = { "27:779375624:893957315", "Deathstalker ใน Shadowfang" },
        objective = { "55:2079002150:1481553435", "ตามหา Deathstalker Adamant และ Deathstalker Vincent" },
        description = { "264:417527968:1105235340 N 182:1498503704:1941161497 N 14:1156631296:1336435094", "เพื่อเตรียมบุก Shadowfang เราส่ง Deathstalker สองคนเข้าไปเก็บข่าวในปราการ หลายวันแล้วที่พวกเขายังไม่กลับมา แต่เราต้องได้รายงาน หากยังหวังให้การโจมตีสำเร็จ!\n\nนี่คืองานของเจ้า {name} ไป Shadowfang Keep ทางใต้ แล้วตามหา Deathstalker Adamant กับ Vincent หาให้พบ และหากพวกเขาต้องการความช่วยเหลือก็จงช่วย\n\nภารกิจนี้อันตรายพอ ๆ กับที่สำคัญ {name} อย่าล้มเหลว" },
        completion = { "214:240678015:1491882933", "ร่างของ Vincent นอนบอบช้ำและนิ่งสนิท\n\nแม้ Deathstalker Adamant จะส่งรายงานของเขาให้ Hadrec... รายละเอียดอื่นใดที่ Vincent ได้รู้คงต้องตายไปพร้อมเขา\n\nแต่ในมือของเขากำเครื่องประดับชิ้นเล็กไว้..." },
    },
    [1101] = { -- The Crone of the Kraul
        title = { "22:1320174210:1866478428", "แม่เฒ่าแห่ง Kraul" },
        objective = { "65:2076552312:2130090062", "นำ Razorflank's Medallion ไปให้ Falfindel Waywarder ใน Thalanaar" },
        description = { "262:1093218117:1046320116 N 89:1271312761:1348951162", "Heralath ผู้น่าสงสาร! แล้วคนแคระผู้นี้... Lonebrow เขาช่างกล้าหาญนัก\n\nเราจะปล่อยให้ความกล้าของพวกเขาสูญเปล่าไม่ได้ แม่เฒ่าผู้นี้... Charlga Razorflank... ต้องถูกหยุด\n\nแน่นอนว่าการแทรกซึม Kraul จะอันตราย ไม่มีเวลาส่งข่าวไป Darnassus แล้ว {name} จงรวบรวมพรรคพวกไปสังหารแม่เฒ่านั่น\n\nนำ Razorflank's Medallion มาให้ข้าเป็นหลักฐานการตาย" },
        progress = { "102:585474242:1318808678", "ตราบใดที่ Charlga Razorflank ยังรวบรวมกำลังใน Razorfen Kraul ดินแดนเหล่านี้ก็ตกอยู่ในอันตรายใหญ่หลวง" },
        completion = { "57:104292081:861048395 N 338:1137423331:908155072", "แม่เฒ่าถูกกำจัดแล้ว นี่เป็นข่าวดีเหลือเกิน {name}\n\nในยามอันตรายเช่นนี้ การได้เห็นคนกล้าหาญเช่นเจ้าช่วยให้ใจสดชื่นขึ้น\n\nเมื่อจัดการสมุนของ Razorflank แล้ว เราก็ศึกษาพื้นที่นี้ต่อได้ บางทีตอนนี้เราอาจได้รู้ชัดขึ้นว่าเกิดอะไรขึ้นจึงทำให้สถานที่พักผ่อนของ Agamaggan แปดเปื้อน\n\nแต่ข้าเกรงว่าคำตอบของคำถามนั้นจะเกี่ยวพันกับการทรยศเช่นกัน..." },
        required = { [5792] = { "22:1853700087:816380596", "เหรียญตราของ Razorflank" } },
        steps = { { "22:1853700087:816380596", "เหรียญตราของ Razorflank" } },
    },
    [1102] = { -- A Vengeful Fate
        title = { "15:1256346678:1738397819", "ชะตาแห่งการล้างแค้น" },
        objective = { "61:254806001:70332007", "นำ Razorflank's Heart ไปให้ Auld Stonespire ใน Thunder Bluff" },
        description = { "433:432893450:265795004 N 1:46:46", "Cairne เป็นผู้นำผู้สูงส่งที่รวบรวมผู้คนของเรามารวมกันที่ Thunder Bluff\n\nแต่ข้าให้อภัยคนที่ขับไล่เราออกจากดินแดนบรรพชนได้ไม่ง่ายเหมือนบางคน เผ่าของข้าอาศัยใน Barrens ตอนใต้มาหลายสิบปี แผ่นดินนั้นศักดิ์สิทธิ์ต่อเรา แต่ศัตรูมากมายกลับขับไล่เราออกมา\n\nชะตาแห่งการล้างแค้นรอแม่เฒ่า Charlga Razorflank ผู้รวบรวมกองทัพชั่วร้ายใน Razorfen Kraul อยู่\n\nนำหัวใจของ Razorflank มาให้ แล้วข้าจะตายตาหลับ {name}" },
        progress = { "268:421507367:1010710402", "เมื่อรู้ว่าอสูรชั่วแห่ง Razorfen Kraul ถูกขับออกจากรังโสมม ข้าก็จะพักอย่างสงบได้ ด้วยรู้ว่าการล้างแค้นสำเร็จแล้ว\n\nเจ้าขับพวกควิลบอร์ออกจาก Kraul แล้วหรือ? เจ้านำข่าวดีในรูปหัวใจของ Razorflank มาฝากข้าหรือไม่?" },
        completion = { "188:2075154028:1019361665 N 29:652000365:185174148", "ข้าเห็นว่าเผ่าโหดร้ายแห่ง Razorfen Kraul ได้รู้จักความเจ็บปวดของผู้คนข้าแล้ว สมน้ำหน้าอสูรชั่วพวกนั้น\n\nการขับไล่ผู้ใดออกจากแผ่นดินศักดิ์สิทธิ์ เป็นบาปที่สมควรได้รับการล้างแค้นอย่างรุนแรงที่สุด\n\nขอบใจ {name} ที่ช่วยข้าในยามทุกข์ยาก" },
        required = { [5793] = { "18:225787564:633191856", "หัวใจของ Razorflank" } },
        steps = { { "18:225787564:633191856", "หัวใจของ Razorflank" } },
    },
    [1109] = { -- Going, Going, Guano!
        title = { "20:1454147614:1087133146", "หนึ่ง สอง... มูลค้างคาว!" },
        objective = { "75:1665023224:1841857111", "นำ Kraul Guano 1 กองไปให้ Master Apothecary Faranell ใน Undercity" },
        description = { "16:1674991282:289885126 N 238:1617447988:1874002736 C 238:370217752:454692812", "อย่างที่เจ้าเห็น {name} พวกเราที่ Royal Apothecary Society กำลังทำการทดลองที่... น่าสนใจมาก\n\nในฐานะหัวหน้าที่นี่ ข้ามีหน้าที่ดูแลความพยายามทางเล่นแร่แปรธาตุที่ทะเยอทะยานที่สุดของเรา งานมากเหลือเกิน แต่เวลาน้อยนัก!\n\nเจ้าดูเดินทางมาไกลมากสำหรับ{class} บางทีอาจช่วยข้าได้\n\nข้าต้องการวัตถุหายากอย่างหนึ่ง เป็นของเหม็นโสโครกจากค้างคาวสายพันธุ์หายาก ที่พบเฉพาะในหลุมโคลนที่เรียกกันว่า Razorfen Kraul นำมูลของ Kraul Bats มาให้ข้า เราจะได้เริ่มงานกัน..." },
        progress = { "70:62946879:1918216614", "อา เจ้ากลับมาแล้ว หา Kraul Guano มาได้บ้างไหม?" },
        completion = { "44:1156470787:888807715 N 1:46:46", "เยี่ยมมาก! นี่แหละจุดเริ่มต้นที่เราต้องการ {name}" },
        required = { [5801] = { "11:55700212:1075530691", "มูลค้างคาวจาก Kraul" } },
        steps = { { "11:55700212:1075530691", "มูลค้างคาวจาก Kraul" } },
    },
    [1142] = { -- Mortality Wanes
        title = { "15:1904901621:1364030056", "ชีวิตร่วงโรย" },
        objective = { "72:858014702:775664797", "ค้นหา Treshala's Pendant แล้วนำกลับไปให้ Treshala Fallowbrook ใน Darnassus" },
        description = { "357:1383837876:1354480046", "ข้าอยู่ได้อีกไม่นาน... อ่อน... อ่อนแรงเหลือเกิน\n\n...คนแคระผู้กะ... กล้าหาญ Lonebrow ถูกส่งไปตะ... เตือน Falfindel แล้ว...\n\nแต่ก่อนที่ข้าจะ... ตะ... ตาย...\n\n...ภรรยาข้า Treshala... จี้ที่ผูกสัมพันธ์นางกับข้า... ถูกขโมย... โดยหนึ่งในผู้บุกรุกชะ... ชั่วพวกนั้น...\n\nได้โป... โปรดหาให้พบ... แล้วคืนให้ Treshala ที่ Darnassus...\n\n...พร้อมบะ... บอกข่าวการตาย... อันเดียวดายของข้า" },
        progress = { "28:1168006940:1351125668 R 1:63:63", "สิ่งใดนำเจ้ามาบ้านข้า {race}?" },
        completion = { "187:106906324:2008105027 N 53:709055066:694720455", "ไม่!\n\nไม่ยุติธรรมเลย โอ้ โลกช่างโหดร้ายและเหลือทน!\n\nบัดนี้ข้าต้องแบกรับความโศกเศร้านี้ และไม่ปล่อยให้งานของ Heralath ตายไปพร้อมเขา\n\nเจ้ากล้าหาญที่เดินทางมาจากสถานที่อันตรายเช่นนั้น {name} แต่ได้โปรดปล่อยข้าอยู่คนเดียวตอนนี้\n\nข้าจะไว้ทุกข์เพียงลำพัง" },
        required = { [5825] = { "18:1252650084:720926578", "จี้ของ Treshala" } },
        steps = { { "18:1252650084:720926578", "จี้ของ Treshala" } },
    },
    [1144] = { -- Willix the Importer
        title = { "19:1464350718:2047864833", "Willix พ่อค้านำเข้า" },
        objective = { "49:1310226297:517833438", "คุ้มกัน Willix the Importer ออกจาก Razorfen Kraul" },
        description = { "491:1153259424:755530184", "ในที่สุดความช่วยเหลือก็มาถึง!\n\nเจ้าไม่รู้หรอกว่าข้าถูกขังที่นี่นานแค่ไหน ข้าจำไม่ได้แล้วว่าเห็นโลกภายนอกครั้งสุดท้ายเมื่อไร\n\nข้าเป็นผู้ประกอบการ อย่างที่เขาว่ากัน มองหาทางหาเงินทองแดงอยู่เสมอ ข้าได้ข่าวว่า Mebok Mizzyrix จ่ายงามสำหรับ Redleaf Tuber จากคอกหมูแห่งนี้ ข้าคิดว่าคงแค่เข้าง่ายออกง่าย อย่างที่เจ้าเห็น ข้าคิดผิดไปหน่อย!\n\nอย่างไรก็เถอะ ถ้าเจ้ามีน้ำใจช่วยข้าออกไป ข้าจะตอบแทนให้คุ้มค่า" },
        completion = { "62:1224029041:276465634", "ขอบใจอีกครั้ง เพื่อน! ข้าบอกแล้วว่าจะตอบแทนให้คุ้มค่า" },
        objectiveLabels = {
            event = { ["Help Willix the Importer escape from Razorfen Kraul"] = "ช่วย Willix the Importer หนีออกจาก Razorfen Kraul" },
        },
    },
    [1221] = { -- Blueleaf Tubers
        title = { "15:681518722:1167369986", "หัวพืช Blueleaf" },
        objective = { "360:770449074:1955894065", "หยิบ Crate with Holes\nหยิบ Snufflenose Command Stick\nหยิบและอ่าน Snufflenose Owner's Manual\n\nใน Razorfen Kraul ใช้ Crate with Holes เรียก Snufflenose Gopher แล้วใช้ Command Stick กับมันเพื่อสั่งค้นหาหัวพืช\n\nนำ Blueleaf Tubers 6 ชิ้น, Snufflenose Command Stick และ Crate with Holes ไปให้ Mebok Mizzyrix ใน Ratchet" },
        description = { "456:410361153:709400596", "หัวพืช Blueleaf เป็นอาหารโอชะทั่วโลก! แต่มันหายาก หายากมาก พบได้เพียงที่นี่ใน Barrens ลึกลงไปใต้ดินใน Razorfen Kraul\n\nถึงอย่างนั้นก็ไม่มีทางเจอ เว้นแต่จะรู้ว่าต้องหาตรงไหน! ข้าจึงฝึกโกเฟอร์ Snufflenose พวกนี้ให้หาแทน จมูกพวกมันยอดเยี่ยม ดมหัวพืชได้ไกลถึงห้าสิบก้าว\n\nงานนี้ไม่ง่าย แต่ถ้าเจ้าหาหัวพืชมาให้ ข้าจะจ่ายให้อย่างงาม" },
        progress = { "24:778899553:1705471887 N 1:63:63", "มีหัวพืชมาหรือยัง {name}?" },
        completion = { "92:525914258:728114757 N 26:908430835:633546522", "ดีมาก เจ้าได้มาแล้ว! ข้าเอาพวกนี้ไปขายให้คนที่ติดต่อไว้ได้เงินเป็นกอบเป็นกำแน่!\n\nขอบใจที่นำมาส่ง {name}! เจ้าเป็นหุ้นส่วนที่ยอดเยี่ยม" },
        required = { [5876] = { "14:1606997583:123662254", "หัวพืช Blueleaf" }, [5880] = { "16:888781661:1092076849", "ลังเจาะรู" }, [5897] = { "26:2033504350:1275945116", "คู่มือเจ้าของ Snufflenose" }, [6684] = { "25:436318077:1277558155", "ไม้สั่งการ Snufflenose" } },
        steps = { { "14:1606997583:123662254", "หัวพืช Blueleaf" }, { "16:888781661:1092076849", "ลังเจาะรู" }, { "26:2033504350:1275945116", "คู่มือเจ้าของ Snufflenose" }, { "25:436318077:1277558155", "ไม้สั่งการ Snufflenose" } },
    },
    [1486] = { -- Deviate Hides
        title = { "13:1762440678:1872409429", "หนังสัตว์กลายพันธุ์" },
        objective = { "53:234312608:814513307", "Nalpak ใน Wailing Caverns ต้องการ Deviate Hides 20 ชิ้น" },
        description = { "464:1764780282:958821591", "ขณะที่ Naralex จมลึกลงในฝันร้ายมากขึ้น สัตว์สายพันธุ์ประหลาดก็ปรากฏจากใต้ Barrens เข้ามาใน Wailing Caverns\n\nสัตว์กลายพันธุ์เหล่านี้มีคุณสมบัติแปลกประหลาดราวกับมาจากต่างโลก แม้ธรรมชาติของมันจะชั่วร้าย ข้าก็คิดว่าการมีอยู่ของพวกมันที่นี่ใน Kalimdor อาจก่อประโยชน์ได้บ้าง ข้าเชื่อว่าหนังของมันจะมีประโยชน์เป็นพิเศษต่องานเครื่องหนัง\n\nหากเจ้าคิดว่าทำไหว จงผจญลงไปในถ้ำเบื้องล่างแล้วนำหนังสัตว์กลายพันธุ์กลับมา" },
        progress = { "144:321063936:930393319 C 1:63:63", "ข้าสนใจศึกษาหนังของสัตว์กลายพันธุ์ที่เข้ามายึดถ้ำเหล่านี้มาก เจ้ารวบรวมมาได้บ้างหรือยัง {class}?" },
        completion = { "62:1695200475:189009704 N 32:327703001:1297990109", "ความพยายามรวบรวมหนังเหล่านี้ของเจ้าจะไม่ถูกมองข้าม {name}\n\nขอบใจในความทุ่มเทของเจ้า" },
        required = { [6443] = { "12:1644627375:1407698609", "หนัง Deviate" } },
        steps = { { "12:1644627375:1407698609", "หนัง Deviate" } },
    },
    [1487] = { -- Deviate Eradication
        title = { "19:384210156:1090351086", "กวาดล้างสัตว์กลายพันธุ์" },
        objective = { "129:1997391071:453565540", "Ebru ใน Wailing Caverns ต้องการให้เจ้าฆ่า Deviate Ravagers 7 ตัว, Deviate Vipers 7 ตัว, Deviate Shamblers 7 ตัว และ Deviate Dreadfangs 7 ตัว" },
        description = { "414:1333111245:2086588764 N 34:887710466:613607037", "Naralex มีเป้าหมายอันสูงส่ง\n\nผู้นำผู้ยิ่งใหญ่ของเราหวังเข้าสู่ Emerald Dream และช่วยฟื้นดินแดนแห้งแล้งเหล่านี้ให้กลับเป็นป่าเขียวชอุ่มอย่างที่เคย แต่บางสิ่งผิดพลาดอย่างร้ายแรง\n\nความฝันของ Naralex กลายเป็นฝันร้าย และสิ่งมีชีวิตแปดเปื้อนก็เริ่มเข้ามาอาศัยในถ้ำ\n\nขณะที่ศิษย์ Naralex บางคนพยายามปลุกอาจารย์ ข้าห่วงเรื่องกำจัดสัตว์ร้ายออกจากถ้ำเหล่านี้\n\nจงกล้าฝ่าเข้าไปในถ้ำ {name} แล้วกวาดล้างสิ่งกลายพันธุ์เหล่านั้น" },
        progress = { "N 291:1347480191:1676769982", "{name} พวกเราศิษย์ของ Naralex ต้องการความช่วยเหลือจากเจ้า จำนวนเราลดน้อยลง ขณะที่อาจารย์ติดอยู่ในฝันร้ายบิดเบี้ยว เราไม่มีกำลังพอจัดการสิ่งมีชีวิตแปดเปื้อนที่หลอกหลอนถ้ำเหล่านี้อยู่\n\nข้าขอร้อง จงเข้าถ้ำแล้วต่อสู้กับสัตว์กลายพันธุ์พวกนั้น!" },
        completion = { "50:350312634:1121588617 N 130:551926476:1086936879", "ในฐานะศิษย์ของ Naralex ข้าขอชื่นชมความกล้าของเจ้า {name}\n\nการช่วยกวาดล้างถ้ำของเจ้าเป็นก้าวแรกในความพยายามอันยาวนานเพื่อให้ Barrens ฟื้นคืน\n\nขอบใจ และขอให้เจ้ารุ่งเรือง" },
        objectiveLabels = {
            monster = { ["Deviate Ravager slain"] = "ปราบ ผู้ทำลายล้าง Deviate", ["Deviate Viper slain"] = "ปราบ งูพิษ Deviate", ["Deviate Shambler slain"] = "ปราบ ตัวเดินโซเซ Deviate", ["Deviate Dreadfang slain"] = "ปราบ เขี้ยวสยอง Deviate" },
        },
    },
    [1489] = { -- Hamuul Runetotem
        title = { "16:2140007327:130599278", "Hamuul Runetotem" },
        objective = { "28:1240953822:1556133306", "คุยกับ Hamuul Runetotem", variants = { { "27:1784649691:1651179360", "คุยกับ Hamuul Runetotem" } } },
        description = { "488:1137448950:1350543519", "กระดองที่เจ้านำมามีมลทินชนิดที่ข้าไม่เคยเห็น ข้ามั่นใจว่าน้ำในโอเอซิสเป็นสาเหตุ และสัมผัสได้ถึงความปั่นป่วนที่มันก่อแก่แผ่นดิน ราวกับผืนดินกำลังฝันและไม่อาจตื่น\n\nWailing Caverns ต้องเป็นต้นตอของมลทิน แต่ก่อนเจ้าไปที่นั่น จงคุยกับ Hamuul Runetotem ดรูอิดอาวุโส ข้าส่งข่าวเรื่องที่เกิดใน Barrens ให้เขาแล้ว เขาฉลาดและให้คำปรึกษาเจ้าได้\n\nเจ้าจะพบเขาบน Elder Rise ใน Thunder Bluff" },
        completion = { "21:424205032:671010760 N 121:293724582:1857477867", "ข้าขอทักทายเจ้า {name} ที่นี่ต้อนรับเจ้า และข้าแนะนำให้รวบรวมพลังทั้งหมดไว้ เพราะภารกิจที่เรากำลังมอบให้เจ้า... ร้ายแรงนัก" },
    },
    [1490] = { -- Nara Wildmane
        title = { "13:841968805:941399231", "Nara Wildmane" },
        objective = { "25:1361248167:2036300610", "คุยกับ Nara Wildmane" },
        description = { "487:1395881169:2115747948", "ข้าเข้าสู่ดินแดนแห่งความฝัน และฝันถึงลัทธิดรูอิดที่อาศัยใน Wailing Caverns ข้าเห็นว่าเป้าหมายเดิมของพวกเขาสูงส่ง แต่พวกเขาหลงทางไปแล้ว ตอนนี้พวกเขาเป็นข้ารับใช้ของมลทินที่ซึมผ่าน Barrens\n\nข้าแก่แล้วและกำลังถดถอย จึงอยู่ในแดนฝันนั้นได้ไม่นาน และรู้เรื่องดรูอิดแปดเปื้อนเพิ่มเพียงเล็กน้อย แต่ Nara ยังเยาว์และจิตใจแข็งกล้า นางอยู่ในแดนฝันต่อเมื่อข้าถอนตัวออกมา\n\nคุยกับ Nara นางอยู่ในกระโจมทางโน้น" },
        completion = { "168:151838125:2000127682 N 1:46:46", "ใช่ เป็นความจริง ข้ารู้เรื่องดรูอิดใน Wailing Caverns ข้าเห็นใบหน้าบิดเบี้ยวที่ปกคลุมด้วยเกล็ดของพวกเขา รู้ความผิดที่ก่อ และรู้แผนของพวกเขา\n\nเจ้าต้องหยุดพวกเขา {name}" },
    },
    [1491] = { -- Smart Drinks
        title = { "12:2049529469:48862900", "เครื่องดื่มเพิ่มปัญญา" },
        objective = { "65:1307939773:1558002234", "นำ Wailing Essence 6 ส่วนไปให้ Mebok Mizzyrix ใน Ratchet" },
        description = { "486:806596092:644008336", "เอาละ เขาแรปเตอร์ใช้ไม่ได้ผลนัก แต่ไม่เป็นไร ไม่มีใครรวยจากการลองครั้งแรก! อีกอย่าง ข้าคิดว่าเจอของที่จะใช้กับเครื่องดื่มเพิ่มปัญญาได้ดีกว่าแล้ว!\n\nมีสารอย่างหนึ่งชื่อ Wailing Essence ข้าคิดว่ามันเป็นสาเหตุของพืชกับสัตว์ประหลาดใน Barrens หามาให้หน่อย แล้วข้าจะลองใส่เครื่องดื่ม!\n\nได้ยินว่าแก่นสารนี้สะสมในสิ่งมีชีวิตเอ็กโทพลาซึมใน Wailing Caverns ทางตะวันตก ล่าพวกมันแล้วรวบรวมแก่นสารมา" },
        progress = { "28:1661571804:615917250", "Wailing Essence ของข้าอยู่ไหน?" },
        completion = { "110:541025194:1374756793 N 62:1478842921:912271251", "เยี่ยม เจ้าได้มาแล้ว! ข้าอดใจรอลองไม่ไหว มันต้องทำให้ข้ารวยแน่ ข้ารู้เลย!\n\nขอบใจ {name} รับนี่ไป แล้วหลังจากข้ารวย ข้าจะส่งให้เจ้าเพิ่ม ข้าสัญญา!" },
        required = { [6464] = { "15:1278139326:1185531897", "แก่นพลัง Wailing Essence" } },
        steps = { { "15:1278139326:1185531897", "แก่นพลัง Wailing Essence" } },
    },
    [3341] = { -- Bring the End
        title = { "13:170605006:21663877", "นำจุดจบมาเยือน" },
        objective = { "80:1181296956:762159095", "Andrew Brownell ต้องการให้เจ้าฆ่า Amnennar the Coldbringer แล้วนำกะโหลกของเขากลับมา" },
        description = { "463:1530493377:677653224 N 38:2133168835:275093398", "ใน Barrens มีดงเถาวัลย์พันยุ่งน่าสะพรึงกลัวเรียกว่า Razorfen Downs แม้การสำรวจช่วงแรกของเราจะพบภัยคุกคามเพียงเล็กน้อย แต่สิ่งที่ค้นพบล่าสุดร้ายแรงกว่ามาก...\n\nพวกควิลบอร์แห่ง Razorfen Downs เข้าร่วมกับ Scourge แล้ว ตอนนี้ลิชชื่อ Amnennar the Coldbringer ปกครองพวกมัน ใช้พลังจิตอันมหาศาลควบคุมทุกการเคลื่อนไหว\n\nAmnennar เชื่อมจิตกับ Ner'zhul โดยตรง เราต้องตัดสายสัมพันธ์นี้ {name} จุดจบต้องมาถึง Coldbringer" },
        progress = { "37:1487427046:1261394008 N 65:852553453:246708095", "เรื่องนี้สำคัญอย่างยิ่ง {name} เราต้องหยุดทุกความพยายามของ Scourge ที่จะเพิ่มกำลังพล" },
        completion = { "37:881055119:637603124 N 67:370915185:597519694", "ความภักดีของลิชไม่เคยสั่นคลอน {name} จงให้พวกมันรู้ว่าความภักดีเช่นนั้นจะนำมาเพียงความพินาศ" },
        required = { [10420] = { "24:350405197:1802011974", "กะโหลกของ Coldbringer" } },
        steps = { { "24:350405197:1802011974", "กะโหลกของ Coldbringer" } },
    },
    [3523] = { -- Scourge of the Downs
        title = { "20:368828338:1605048338", "Scourge แห่ง Downs" },
        objective = { "101:473666351:23704647", "หากเจ้าตกลงช่วย Belnistrasz ให้คุยกับเขาอีกครั้ง แล้วคืน Oathstone ที่เขามอบให้" },
        description = { "498:419841341:305012049", "ยอดเยี่ยม! ข้าชื่อ Belnistrasz ขอบใจที่ช่วยข้า ข้าทำใจไว้แล้วว่าจะตาย... หรือแย่กว่านั้น คือเป็นอาหารของพวกสวะติดเชื้อ Scourge ใช่ ข้าพูดว่า Scourge ไม่ผิด พวกมันทำข้อตกลงบางอย่างกับควิลบอร์ที่นี่ และฝันร้ายนี้คือผลลัพธ์\n\nฟังนะ... แทนที่จะหนีอย่างเดียว ข้าอยากทำสิ่งที่เปลี่ยนสถานการณ์เพื่อพวกเราทุกคน เจ้าจะช่วยให้ข้าทำสำเร็จไหม? คงอันตราย แต่เจ้าดูไม่ใช่คนที่จะกังวลเรื่องนั้นมากนัก" },
        progress = { "437:1774252546:1636668230", "ข้าไม่สนการเมือง ไม่ใส่ใจว่าเจ้าเข้าข้าง Horde หรือ Alliance ข้าสนใจหยุดภัยร้ายแรงที่คุกคามทุกเผ่าโดยตรงมากกว่า... และเรามีภัยใหญ่ทีเดียวอยู่ในนี้\n\nหากเจ้ายินดีเป็นวีรชนที่แท้จริงของทุกผู้คน จงคืน Oathstone ที่ข้ามอบให้เพื่อแสดงความตั้งใจ ข้า... ไม่ใช่คนแถวนี้ สำหรับเผ่าพันธุ์ของข้า Oathstone สำคัญในฐานะสิ่งผูกพันข้อตกลง" },
        completion = { "89:1827232335:1817579211 N 169:1732844748:891701798", "เยี่ยมมาก ข้าคิดแล้วว่าเจ้าดูเป็นวีรชน! เรามีงานหนักรออยู่ {name} ข้าจะไม่โกหก หากเราจดจ่อกับงานตรงหน้า ก็น่าจะผ่านไปได้อย่างมีชัย\n\nเอาละ ให้ข้าเล่าเรื่องที่เกิดขึ้นให้เจ้าตามทัน..." },
        required = { [10682] = { "23:1332224653:1921525380", "ศิลาแห่งคำสัตย์ของ Belnistrasz" } },
        steps = { { "23:1332224653:1921525380", "ศิลาแห่งคำสัตย์ของ Belnistrasz" } },
    },
    [3525] = { -- Extinguishing the Idol
        title = { "22:546560184:1269416812", "ดับพลังรูปเคารพ" },
        objective = { "132:1903693506:713843593", "คุ้มกัน Belnistrasz ไปยังรูปเคารพของควิลบอร์ใน Razorfen Downs\n\nปกป้อง Belnistrasz ขณะเขาทำพิธีหยุดการทำงานของรูปเคารพ" },
        description = { "493:1183130445:865753959", "ใกล้ทางเข้ามีรูปเคารพที่ทำหน้าที่เป็นเตาอันสยดสยองของควิลบอร์ อสูรพวกนี้... กินคนที่พวกมันลักพาตัวมาจาก Barrens จริง ๆ ข้าหยุดการทำงานของรูปเคารพและผนึกไม่ให้พวกมันใช้ได้อีก แต่ต้องอาศัยความช่วยเหลือจากเจ้า แผนคือคุ้มกันข้าไปยังรูปเคารพ เมื่อถึงแล้วข้าจะเริ่มพิธี ข้าแทบจะสื่อสารกับเจ้าไม่ได้ อย่าว่าแต่ป้องกันตัวเองเลย ปกป้องข้าระหว่างที่ข้าหยุดรูปเคารพ หากพวกมันล้มข้าได้ ทุกอย่างก็จบสำหรับเรา\n\nเจ้าจะร่วมมือกับข้าไหม?!" },
        completion = { "475:555519410:1252563657", "การจากไปอย่างฉับพลันของ Belnistrasz ทิ้งไว้เพียงกระถางไฟที่ลุกโชน ขณะเจ้าจ้องเปลวไฟ ภาพมังกรแดงปีกใหญ่ก็ปรากฏเต็มความคิด เสียงที่แหบพร่ากว่าเดิมของ Belnistrasz พูดตรงเข้ามาในใจเจ้า\n\n\"ใช่แล้ว เหล่าผู้เป็นมรรตัย พวกเจ้าคือวีรชนอย่างที่ข้าหวังไว้ ขอบใจพวกเจ้า การฆ่าชำแหละที่อสูรพวกนี้ก่อขึ้นกลายเป็นอดีตไปแล้ว ศรัทธาที่ข้ามีต่อผู้เป็นมรรตัยเช่นพวกเจ้าฟื้นคืนอีกครั้ง จงรับสิ่งนี้เป็นรางวัลที่สมกับวีรชน\"" },
        objectiveLabels = {
            event = { ["Protect Belnistrasz while he performs the ritual to shut down the idol"] = "ปกป้อง Belnistrasz ขณะเขาทำพิธีปิดการทำงานของรูปเคารพ" },
        },
    },
    [3636] = { -- Bring the Light
        title = { "15:831219260:161965966", "นำแสงสว่างมาเยือน" },
        objective = { "82:1826618658:1931653670", "Archbishop Bendictus ต้องการให้เจ้าสังหาร Amnennar the Coldbringer ใน Razorfen Downs" },
        description = { "149:1550186521:277428255 N 305:788232053:1006268987 N 32:181683284:520368558", "Scourge เป็นภัยคุกคาม Alliance อย่างไม่หยุดหย่อน ข้าเชื่อว่าเจ้ารู้เรื่องนี้ดี ไม่นานมานี้เราพบสิ่งแปลกประหลาดมาก {name}\n\nใน Barrens มีดงพุ่มหนามพันยุ่งน่าสะพรึงกลัวเรียกว่า Razorfen Downs ครั้งหนึ่งเคยเป็นบ้านของควิลบอร์ธรรมดา แต่ตอนนี้ชัดเจนแล้วว่ามีการทำข้อตกลงกับ Scourge จนเกิดสิ่งมีชีวิตที่เลวร้ายกว่านั้นมาก... บัดนี้ลิช Amnennar the Coldbringer ปกครองพวกมัน\n\nจงยืนเคียงข้างแสงสว่าง {name} หยุดพันธมิตรชั่วร้ายนี้เสีย" },
        progress = { "41:1600768394:654393969", "ต้องกำจัด Amnennar ไป เร็วเข้า" },
        completion = { "12:1312887944:1484804295 N 113:1712077038:901410960", "ขอบใจ {name} ตอนนี้ Scourge คงต้องคิดให้ดีก่อนพยายามเพิ่มกำลังพลอีก\n\nขอแสงสว่างอวยพรเจ้า" },
        objectiveLabels = {
            monster = { ["Amnennar the Coldbringer slain"] = "ปราบ Amnennar ผู้นำความหนาวเย็น" },
        },
    },
    [5722] = { -- Searching for the Lost Satchel
        title = { "30:1696761546:1382519677", "ค้นหาย่ามที่หายไป" },
        objective = { "90:1469624315:488762945", "ค้นหาศพของ Maur Grimtotem ใน Ragefire Chasm แล้วค้นศพหาไอเทมที่น่าสนใจ" },
        description = { "502:701122024:1160277378", "โทรกก์ไม่ใช่สิ่งเดียวใน Ragefire Chasm ที่ Magatha สนใจ นางได้ข่าวว่าคนรับใช้ชื่อ Maur Grimtotem พบอะไรประหลาดในเหว แต่ไม่เคยออกมาแสดงให้นางเห็น นางอยากให้หาศพของ Maur หากยังมีอยู่ และร่องรอยสิ่งที่เขาพบระหว่างพยายามพูดกับโทรกก์\n\nนำไอเทมที่น่าสนใจกลับมาให้ Magatha ข้ามั่นใจว่านางจะให้รางวัลอย่างใจกว้าง\n\nอีกครั้ง จงหาเหวนี้ในส่วนที่มืดที่สุดของ Orgrimmar" },
        completion = { "263:373065147:905741231", "ศพดูถูกกระบองหรือกำปั้นทุบตีอย่างรุนแรง แต่เสื้อผ้าและอุปกรณ์ส่วนใหญ่ยังดูอยู่ครบ ดูเหมือนโทรกก์ไม่ใส่ใจทรัพย์สินเงินทองนัก\n\nเจ้าเริ่มค้นศพหาสิ่งน่าสนใจที่อาจช่วย Magatha ได้" },
    },
    [5723] = { -- Testing an Enemy's Strength
        title = { "27:1430072045:1633547118", "ทดสอบกำลังศัตรู" },
        objective = { "132:1043922222:379169260", "ค้นหา Ragefire Chasm ใน Orgrimmar แล้วฆ่า Ragefire Troggs 8 ตัว และ Ragefire Shaman 8 ตัว ก่อนกลับไปหา Rahauro ใน Thunder Bluff" },
        description = { "506:592772366:1452150344", "ใต้เมือง Orgrimmar สิ่งมีชีวิตล่ำเตี้ยที่เรียกว่าโทรกก์เริ่มขึ้นสู่ผิวดินจากอุโมงค์ลึกที่เต็มไปด้วยลาวา ด้วยความเมตตาเสมอมา Magatha พยายามผูกมิตรกับพวกมัน แต่พวกมันกลับหันมาโจมตีและฆ่าทูตของนาง นางจะไม่ยอมให้ชาวทอเรนถูกกระทำเช่นนี้ และบัดนี้ถือว่าพวกมันเป็นภัยต่อ Horde ทั้งหมด\n\nนางขอให้เจ้าหยุดภัยโทรกก์นี้ ก่อนมันจะทะลักจากเบื้องล่างเข้าท่วม Horde จงหา Ragefire Chasm แล้วทำลายพวกมันให้หมด" },
        progress = { "146:1143545316:1595386355", "การค้นหาเหวเป็นอย่างไรบ้าง? แล้วพวกโทรกก์ล่ะ?\n\nเราปล่อยให้ภัยนี้คงอยู่ไม่ได้ หากดำเนินต่อไปก็จะมีแต่ทำร้ายพี่น้องออร์คของเรา", variants = { { "117:1353094760:689700855 R 26:1834406100:1252704138", "การค้นหาเหวเป็นอย่างไรบ้าง? แล้วพวกโทรกก์ล่ะ?\n\nเราปล่อยให้ภัยนี้คงอยู่ไม่ได้ หากดำเนินต่อไปก็จะมีแต่ทำร้ายพี่น้องชาว{race}ของเรา" } } },
        completion = { "63:385194548:1268117897 N 218:858588850:1198497180", "ข้ายินดีที่เจ้าจริงจังกับงานของ Magatha ขอบใจ {name} เมื่อจำนวนลดลงมากเช่นนี้ โทรกก์คงขึ้นสู่ผิวดินได้ยากขึ้นแน่\n\nบางทีในอนาคตเราอาจมีเวลาศึกษาว่าสิ่งมีชีวิตพวกนี้มาจากไหน และต้องการอะไรกันแน่" },
        objectiveLabels = {
            monster = { ["Ragefire Trogg slain"] = "ปราบ โทรกก์ Ragefire", ["Ragefire Shaman slain"] = "ปราบ ชาแมน Ragefire" },
        },
    },
    [5724] = { -- Returning the Lost Satchel
        title = { "26:9239952:503510806", "คืนย่ามที่หายไป" },
        objective = { "55:80736481:669563980", "นำ Grimtotem Satchel ไปให้ Rahauro ใน Thunder Bluff" },
        description = { "330:127161043:1210028735", "เจ้าพบย่ามอยู่ใต้ร่างของทอเรน แขนของเขายังกอดมันแน่น ราวกับพยายามปกป้องขณะถูกโทรกก์โจมตี\n\nเจ้าดึงย่ามออกจากอ้อมแขนที่รัดแน่นดุจคีม เก็บรวมกับอุปกรณ์ของตน แล้วเตรียมออกจากอุโมงค์กลับไปหา Rahauro ใน Thunder Bluff" },
        progress = { "32:1138884851:168987932 N 81:1772836079:1846692291", "พบอะไรบ้างไหม {name}? เบาะแสใดก็ตามที่ช่วยอธิบายว่าทำไมคนร่วมเผ่าของนางต้องตายอย่างไร้เหตุผล ย่อมเป็นประโยชน์" },
        completion = { "11:1614239848:1406166483 N 131:1786636460:1608564395", "ยอดเยี่ยม {name} ขอบใจ\n\nMagatha บอกว่าหากเจ้าตามหาคนร่วมเผ่าของนางสำเร็จ ให้มอบสิ่งนี้แก่เจ้า ได้โปรดรับไว้แทนคำขอบใจ" },
        required = { [14381] = { "17:354753194:698679494", "กระเป๋าสะพายของเผ่า Grimtotem" } },
        steps = { { "17:354753194:698679494", "กระเป๋าสะพายของเผ่า Grimtotem" } },
    },
    [5725] = { -- The Power to Destroy...
        title = { "23:875327238:951532024", "พลังแห่งการทำลาย..." },
        objective = { "94:1851948918:557940483", "นำตำรา Spells of Shadow และ Incantations from the Nether ไปให้ Varimathras ใน Undercity" },
        description = { "503:1108476693:19805188", "ดังที่เจ้าคงรู้ ผู้อาศัยใน Legion มากมายมอบของขวัญแก่ผู้ติดตาม Dark Lady เห็นว่าของขวัญบางอย่างควรอยู่ในมือนาง มากกว่าจะอยู่กับผู้มี... วิสัยทัศน์คับแคบ\n\nตัวอย่างชัดเจนคือกลุ่มแยกของ Shadow Council ที่ชื่อ Searing Blade ซึ่งซ่อนในถ้ำใต้ Orgrimmar นางบอกข้าว่าสมาชิก Searing Blade ได้ตำราเวททรงพลังสองเล่มมา นางอยาก \"ยืม\" ตำราจากพวกมัน เจ้าจะไปเอามาให้นาง" },
        progress = { "55:1578082811:764714844 C 24:2063278314:748501182", "มีงานอีกเป็นร้อยรอข้าจัดการ {class} เจ้าคว้าตำรามาแล้วหรือยัง?" },
        completion = { "6:2014770050:1830635039 C 314:1481967932:1980623597", "ดี {class} เจ้ารับใช้ Dark Lady ได้ดี ความมุ่งมั่นและความทะเยอทะยานของเจ้าจะเป็นประโยชน์อย่างยิ่งต่อผู้อยู่ใต้อำนาจนาง กลับมาหาข้าอีกในภายหน้า บางทีข้าอาจมีงานอื่นให้เจ้าช่วย Dark Lady ในความพยายามโค่น Lich King และปลดปล่อย Scourge ให้เป็นอิสระอย่างสมบูรณ์" },
        required = { [14395] = { "16:251001139:603591926", "มนตร์แห่งเงา" }, [14396] = { "28:1408168668:1114872011", "บทมนตร์จากเนเธอร์" } },
        steps = { { "16:251001139:603591926", "มนตร์แห่งเงา" }, { "28:1408168668:1114872011", "บทมนตร์จากเนเธอร์" } },
    },
    [5761] = { -- Slaying the Beast
        title = { "17:775519189:1850107999", "สังหารอสูร" },
        objective = { "112:761144203:1509283412", "เข้า Ragefire Chasm แล้วสังหาร Taragaman the Hungerer จากนั้นนำหัวใจของมันกลับไปให้ Neeru Fireblade ใน Orgrimmar" },
        description = { "503:698536817:1674090941", "งานหลักที่ Warchief ผู้ยิ่งใหญ่มอบให้ข้าคือถอนรากสิ่งมีชีวิตที่นำอิทธิพลปีศาจมาแพร่ในนครอันยิ่งใหญ่ของผู้นำเรา Burning Blade เป็นภัยหนึ่ง แต่ยังมีพวกอื่น เช่น Searing Blade ที่อาศัยใน Ragefire Chasm แอบพยายามชักจูงสมาชิก Horde ผู้ไม่รู้อิโหน่อิเหน่ให้เสียคน\n\nหากจะหยุดพวกมัน ต้องฆ่าผู้นำเสีย นั่นคือเฟลการ์ดชื่อ Taragaman the Hungerer\n\nฆ่ามัน แล้วหัวใจของมันจะทำให้ Thrall พอใจ ข้ามั่นใจ" },
        progress = { "95:1018188101:1614245547", "ฆ่าอสูรนั่นหรือยัง? มันต้องเป็นผู้นำ Searing Blade ใน Ragefire Chasm แน่" },
        completion = { "210:985817903:1173913681 C 1:46:46", "ฮ่า! เจ้าทำสำเร็จแล้ว! Thrall จะต้องพอใจมาก\n\nข้าจะดูแลให้หัวใจนี้ได้รับการจัดการอย่างเหมาะสม\n\nแต่ตอนนี้เจ้าต้องฉลองชัยชนะเสียก่อน ข้าจะรายงานความสำเร็จของเจ้าให้ Thrall\n\nขอบใจที่ช่วย {class}" },
        required = { [14540] = { "30:1685518069:144922655", "หัวใจของ Taragaman the Hungerer" } },
        steps = { { "30:1685518069:144922655", "หัวใจของ Taragaman the Hungerer" } },
    },
    [6521] = { -- An Unholy Alliance
        title = { "18:1057537289:921920416", "พันธมิตรอันชั่วร้าย" },
        objective = { "63:995323002:1776188881", "นำ Ambassador Malcin's Head ไปให้ Varimathras ใน Undercity" },
        description = { "399:795362354:1296906981 N 38:1089611745:1012713559", "Malcin อ้างว่าอยู่ด้านนอก Razorfen Downs ต้องสังหารทูตผู้นี้ ให้ภารกิจของเขาล้มเหลวในสายตาของ Lich King\n\nการที่เขาอยู่ที่นั่นอธิบายสิ่งที่เราพบเกี่ยวกับพื้นที่นี้ได้มาก ควิลบอร์บางตัวแข็งแกร่งขึ้นอย่างน่ากลัว พร้อมแสดงอาการของโรคระบาดในแบบของมันเอง นั่นต้องเป็นสัญญาณของข้อตกลงบางอย่างที่พวกมันทำไว้แน่\n\nหา Malcin แล้วฆ่าเขา {name} กลับมาหาข้าเมื่อจัดการแล้ว" },
        progress = { "31:1241635090:1182237877 N 425:1511886113:653942134", "พบทูตแล้วหรือยัง {name}? เขาตายแล้วหรือ?\n\nเราปล่อยให้ Scourge ตั้งฐานบน Kalimdor ไม่ได้ แค่พวกมันคุกคามชายแดนของเราเองก็มากพอแล้ว เราไม่ควรต้องรับศึกสองด้าน\n\nสัญญาณชวนหวังเพียงอย่างเดียวจากเรื่องที่เจ้าเล่าคือ แม่เฒ่าดูยังไม่แปดเปื้อน ลึกในใจนางคงรู้ว่า Scourge อาจมอบพลังยิ่งใหญ่ให้ แต่ Barrens จะไม่เป็นของนางอย่างแท้จริง หากยอมรับข้อตกลงของพวกมัน" },
        completion = { "17:715027:1308047084 C 301:356616774:1712697824", "ดี ทำได้ดี {class}\n\nตอนนี้ Malcin ตายแล้ว อย่างน้อยเราก็รู้ว่าการรุกคืบของ Scourge จะถูกหยุด Dark Lady ขอบใจในความพยายามของเจ้าและประสงค์มอบของขวัญเป็นรางวัล\n\nแม้เรายังไม่รู้ว่าอิทธิพล Scourge ใน Downs แผ่ไปไกลเพียงใด ข้ามั่นใจว่าอีกไม่นานเราจะค้นพบแผนของพวกมัน" },
        required = { [17009] = { "24:1650207229:357564449", "ศีรษะของทูต Malcin" } },
        steps = { { "24:1650207229:357564449", "ศีรษะของทูต Malcin" } },
    },
    [6522] = { -- An Unholy Alliance
        title = { "18:1057537289:921920416", "พันธมิตรอันชั่วร้าย" },
        objective = { "54:1256804943:1934826339", "นำ Small Scroll ไปให้ Varimathras ใน Undercity" },
        description = { "470:223096589:1010667313", "ท่านหญิง\n\nท่านรู้ดีว่าเรากำลังเสนอสิ่งใด โอกาสที่ท่านจะยึด Barrens และดินแดนถัดไปนั้นยิ่งใหญ่ เราต้องการเพียงความช่วยเหลือตอบแทน และความช่วยเหลือที่ว่าก็ไม่มีอะไรมากไปกว่าการให้เราเคลื่อนไหวในพื้นที่ได้อย่างอิสระ\n\nได้โปรดให้เราหารือเรื่องนี้ต่อ เรามีพลังมหาศาลและยินดีแบ่งปันแก่ผู้ฉลาดพอจะเข้าร่วมกับเรา ข้าจะอยู่ด้านนอก Razorfen Downs ไปก่อนในระหว่างนี้\n\nด้วยความนับถือ\nAmbassador Malcin" },
        progress = { "42:109599602:327808010 N 61:1736903036:697819653", "มีธุระอะไรที่เจ้าอยากคุย {name}? เจ้าคงคิดว่าสำคัญสินะ ถึงคอยรบกวนข้าไม่หยุด" },
        completion = { "41:636158606:613334633 N 382:93751653:1296079541", "ข้าจำตราบนม้วนคัมภีร์นี้ได้ {name} เจ้าพบมันกับแม่เฒ่าที่ปกครอง Razorfen Kraul หรือ? น่าสนใจ\n\nดูเหมือน Scourge จะไม่พอใจกับทวีปเดียว ทูต Malcin ผู้เขียนข้อความนี้ เป็นข้ารับใช้ติดโรคของ Scourge คนหนึ่ง เคยเป็นนักการทูตมนุษย์ประจำอาณาจักร Lordaeron ก่อนสิ่งต่าง ๆ จะ... เปลี่ยนไป\n\nหาก Scourge กำลังพยายามตั้งฐานใน Kalimdor เราก็ต้องลงมือ" },
        required = { [17008] = { "12:40715351:1388552520", "ม้วนจารึกขนาดเล็ก" } },
        steps = { { "12:40715351:1388552520", "ม้วนจารึกขนาดเล็ก" } },
    },
    [6562] = { -- Trouble in the Deeps
        title = { "20:483070002:1899148468", "ปัญหาในห้วงลึก" },
        objective = { "37:380341784:1359409601", "คุยกับ Je'neu Sancrea ใน Ashenvale" },
        description = { "294:130963089:1087673140 N 68:1654496491:1700502658", "Je'neu Sancrea ต้องการความช่วยเหลือ เขาอยู่ที่ Zoram'gar Outpost ใน Ashenvale ป่าของไนต์เอลฟ์อยู่ทางเหนือของเทือกเขา Stonetalon เจ้าไปถึงได้โดยผ่าน Windshear Crag หรือขึ้นเหนือผ่าน Barrens ส่วน Zoram Strand อยู่ทางตะวันตกสุดของป่า ระวังตัวด้วย {name} มีกองกำลังที่ไม่ต้อนรับเจ้าอยู่ที่นั่น" },
        completion = { "62:259271764:241757861", "Tsunaman ส่งเจ้ามาหรือ? ดีมาก ถ้าอย่างนั้นเรามีเรื่องต้องคุยกัน" },
    },
    [6563] = { -- The Essence of Aku'Mai
        title = { "22:815404455:1253421940", "แก่นพลังของ Aku'Mai" },
        objective = { "61:1155208245:1136304916", "นำ Sapphires of Aku'Mai 20 ชิ้นไปให้ Je'neu Sancrea ใน Ashenvale" },
        description = { "387:374932094:315078133 N 80:497212117:1607719893", "ตามผนังอุโมงค์ช่วงต้นของ Blackfathom Deeps มีกลุ่มไพลินขนาดใหญ่ ไม่นานมานี้มีคนสังเกตว่านากากำลังเก็บผลึกเหล่านั้น ก่อนเราจะรู้เหตุผล ข้าสัมผัสว่าเราควรหยุดไม่ให้พวกมันทำสำเร็จ ผลึกมีพลังธาตุมหาศาล หากใช้ผิดทางก็อาจเป็นส่วนประกอบเวทอาร์เคนอันทรงพลัง\n\nเจ้าจะช่วยข้าไหม {name}? Blackfathom Deeps อยู่ตาม Zoram Strand ทางเหนือของด่านเรา" },
        progress = { "39:848963084:529547191 N 121:659069545:99671315", "การหาผลึกเป็นอย่างไรบ้าง {name}? เห็นนากาเก็บมันหรือไม่? ข้าภาวนาต่อบรรพชนให้เราพบเหตุผลที่พวกมันรวบรวมของเช่นนี้" },
        completion = { "11:534428891:784080240 N 225:1857756162:1546938948", "ทำได้ดี {name} นี่คือผลึกที่ข้าพูดถึง น่าสนใจ...\n\nข้าสัมผัสพลังภายในได้ วิญญาณแห่งน้ำเกาะเกี่ยวอยู่กับมัน ไม่ว่านากาจะเอาไปใช้ทำอะไร... เอาเถอะ เราควรยินดีที่มันไม่อยู่ในมือพวกนั้นแล้ว" },
        required = { [16784] = { "19:147005450:2058461347", "ไพลินแห่ง Aku'Mai" } },
        steps = { { "19:147005450:2058461347", "ไพลินแห่ง Aku'Mai" } },
    },
    [6564] = { -- Allegiance to the Old Gods
        title = { "26:1576572586:1045445868", "ภักดีต่อ Old Gods" },
        objective = { "51:179594149:881809684", "นำ Damp Note ไปให้ Je'neu Sancrea ใน Ashenvale" },
        description = { "449:1517820445:972318251", "บนกระดาษขยำมีข้อความเขียนหวัดด้วยลายมือไม่ดีนัก:\n\n\"ใช่ บอกนักบวชหญิงทุกคนให้นำผลึกมาให้ข้า วิญญาณธาตุน้ำภายในนั้นแข็งแกร่ง และจะช่วยจอมเวทน้ำของเราในการอัญเชิญได้อย่างมาก\n\nเมื่อควบคุมพลังภายในผลึก เราจะทำให้ Aku'Mai พอใจ สักวันเราจะมีพลังพอนำ Aku'Mai กลับมาหาเรา และโลกจะกลับสู่ยุคอันยิ่งใหญ่ที่สุด ยุคที่ Old Gods ปกครอง!\"" },
        progress = { "5:1287366450:669725923 N 98:335042265:1792834938", "ว่าอย่างไร {name}? เจ้าต้องการอะไร? ข้ายังต้องเรียนรู้เรื่องผลึกที่นาการวบรวมอีกมาก" },
        completion = { "126:650191636:501381012", "น่าสนใจจริง ๆ ข้ายินดีที่เจ้านำเรื่องนี้มาให้ข้ารู้\n\nตอนนี้เรารู้ชื่อผู้ก่อปัญหาแล้ว... Lorgus Jett" },
        required = { [16790] = { "9:143211714:1688987316", "ข้อความเปียกชื้น" } },
        steps = { { "9:143211714:1688987316", "ข้อความเปียกชื้น" } },
    },
    [6565] = { -- Allegiance to the Old Gods
        title = { "26:1576572586:1045445868", "ภักดีต่อ Old Gods" },
        objective = { "85:1658081739:1916526393", "ฆ่า Lorgus Jett ใน Blackfathom Deeps แล้วกลับไปหา Je'neu Sancrea ใน Ashenvale" },
        description = { "290:1818974688:23187790 N 137:477007707:1675547495", "เราปล่อยให้สาวก Twilight's Hammer ผู้นี้ทำแผนสำเร็จไม่ได้ พวก Twilight's Hammer ไม่เข้าใจวิญญาณแห่งธรรมชาติ พวกเขาศรัทธา Old Gods สิ่งมีชีวิตแห่งความโกลาหลและการทำลายที่ถูกปราบไปนานแล้ว เราปล่อยให้ Lorgus ผู้นี้สำเร็จไม่ได้ เจ้าต้องหยุดเขา {name} ข้าทำเองไม่ได้ ข้าอ่อนแอเกินไป\n\nเข้า Blackfathom Deeps หาเขาแล้วฆ่า เสร็จแล้วกลับมาหาข้าที่ Zoram'gar" },
        progress = { "24:1433049274:1643053976 N 25:2141617955:1473577733", "พบเขาหรือยัง {name}? ต้องหยุด Lorgus!" },
        completion = { "23:949992239:854238178 N 228:1394446040:1298538947", "ดีมาก!! ขอบใจ {name} เราอาจหยุด Twilight's Hammer ไม่ได้ทั้งหมด แต่อย่างน้อยเจ้าก็ขัดขวางแผนอีกอย่างที่พวกเขาจะใช้คืนอำนาจให้ Old Gods\n\nใครจะรู้ว่าพวกเขากำลังก่อแผนอื่นใดอีก แต่ตอนนี้เราพอพักใจได้แล้ว" },
        objectiveLabels = {
            monster = { ["Lorgus Jett slain"] = "ปราบ Lorgus Jett" },
        },
    },
    [6626] = { -- A Host of Evil
        title = { "14:1964302173:1960803767", "กองทัพแห่งความชั่วร้าย" },
        objective = { "150:1865612887:1143492287", "ฆ่า Razorfen Battleguard 8 ตัว, Razorfen Thornweavers 8 ตัว และ Death's Head Cultists 8 ตัว แล้วกลับไปหา Myriam Moonsinger ใกล้ทางเข้า Razorfen Downs" },
        description = { "390:727722406:1988430769 N 47:2060436897:383508531", "เท่าที่ข้าเห็น Forsaken ไม่แพร่... โรคของพวกเขา... ต่อให้ผู้อื่น แต่ทูตผู้นี้ดูเหมือนกำลังมอบสภาพอันเดดให้คนที่จะเป็นผู้ติดตาม ข้าเริ่มคิดว่าเขาเป็น Scourge\n\nแต่ตอนนี้สิ่งที่ข้าห่วงไม่ใช่เขา เป็นจำนวนผู้ติดตามรอบตัวที่เพิ่มขึ้นต่างหาก พวกมันคลานออกจากเงาทุกวัน แทบอ้อนวอนให้เขามอบพลังเพิ่ม\n\nข้าไม่แข็งแกร่งพอสู้พวกมันลำพัง {name} ว่าอย่างไร? สนใจออกล่าสักหน่อยไหม?" },
        progress = { "19:584766569:1012911725 N 160:248100673:321757209", "การล่าเป็นอย่างไร {name}? แค่เห็นตัวอย่างพลังของทูตผู้นี้เพียงเล็กน้อย ก็ลบข้อสงสัยทั้งหมดของข้าว่า Scourge เป็นหนึ่งในภัยใหญ่ที่สุดที่โลกเคยพบ" },
        completion = { "11:1191658970:1224418299 N 326:1253520390:102877701", "ขอบใจ {name}! งานของเจ้าต้องช่วยได้มากแน่นอน\n\nข้าจะศึกษาทูตกับพวกควิลบอร์ที่นี่ต่อ หากเจ้าอยากผจญภัยยิ่งกว่านี้ ข้าแนะนำให้หาเพื่อนสักสองสามคนแล้วเข้าถ้ำที่ดูเหมือนปากหมูป่ายักษ์ตรงโน้น ข้ามั่นใจว่าเมื่อเข้าไปแล้ว เจ้าจะพบความท้าทายยิ่งกว่าเดิม" },
        objectiveLabels = {
            monster = { ["Razorfen Battleguard slain"] = "ปราบ ผู้พิทักษ์แนวรบ Razorfen", ["Razorfen Thornweaver slain"] = "ปราบ ผู้ถักหนาม Razorfen", ["Death's Head Cultist slain"] = "ปราบ สาวกลัทธิ Death's Head" },
        },
    },
    [6921] = { -- Amongst the Ruins
        title = { "17:1291732365:972914668", "ท่ามกลางซากปรักหักพัง" },
        objective = { "72:1265015579:159257333", "นำ Fathom Core ไปให้ Je'neu Sancrea ที่ Zoram'gar Outpost ใน Ashenvale" },
        description = { "214:1838576823:884497578 N 282:1155049014:1893905453", "Twilight's Hammer ย้ายเข้าไปใน Moonshrine Ruins แห่ง Blackfathom Deeps การมีอยู่ของพวกเขามีแต่จะบีบบังคับธาตุให้ต่อต้านเรา หากไม่หยุดไว้ ภูมิภาคนี้จะเป็นของพวกเขาตลอดไป\n\n{name} เข้า Blackfathom แล้วหาหิน Fathom ของซากวิหาร มันน่าจะอยู่ในน้ำแถวใกล้ ๆ ภายในมี Fathom Core อุปกรณ์ที่เมื่ออ่านอย่างถูกวิธีจะบอกประวัติกิจกรรมของธาตุทั้งหมด หากข้าได้มันมา ข้ากับ Earthen Ring อาจทำอะไรสักอย่างเพื่อหยุดพวกเขาได้!" },
        progress = { "139:1405619929:1878559651", "หา Fathom Core พบหรือยัง? หากไม่มีมัน เราจะไม่รู้เลยว่า Twilight's Hammer กำลังทำอะไรอยู่ข้างล่างนั่นกันแน่" },
        completion = { "414:1482017081:462345621", "นี่แหละสิ่งที่ข้าต้องการ! Fathom Core เป็นขุมข้อมูลมหัศจรรย์ที่เราจะใช้สร้างประโยชน์ได้มาก ไม่ว่า Twilight's Hammer กำลังทำอะไรอยู่ในนั้น และเชื่อข้าเถอะว่าไม่ใช่เรื่องดี ข้ากับสหายจะเปิดโปงมันแล้ว\n\nวันนี้เจ้าทำได้ดี Earthen Ring ชื่นชมเจ้าที่ช่วยเรา เจ้ายังช่วย Horde โดยรวมด้วย และควรภูมิใจกับสิ่งนั้น" },
        required = { [16762] = { "11:1975522595:1589733162", "แก่นห้วงลึก" } },
        steps = { { "11:1975522595:1589733162", "แก่นห้วงลึก" } },
    },
    [6922] = { -- Baron Aquanis
        title = { "13:1708984273:1608021478", "Baron Aquanis" },
        objective = { "80:1033215325:1584426343", "นำ Strange Water Globe ไปให้ Je'neu Sancrea ที่ Zoram'gar Outpost ใน Ashenvale" },
        description = { "406:22535933:597261648", "ธาตุน้ำที่ถูกปราบทิ้งลูกแก้วน้ำประหลาดไว้ เจ้าคาดว่าของชิ้นนี้น่าจะส่งพลังให้อสูรนั้นด้วยวิธีใดวิธีหนึ่ง ภายในลูกแก้วมีน้ำที่ดูเน่าเหม็นกระฉอกไปมา ตัวลูกแก้วเองดูไม่สะเทือนต่อแรงทางกายภาพใด ๆ\n\nหากมีใครเข้าใจไอเทมนี้ได้ คนนั้นน่าจะเป็น Je'neu Sancrea แห่ง Earthen Ring เขาอยู่ที่ Zoram'gar Outpost ของ Horde ใน Ashenvale" },
        progress = { "16:1883382497:1175130663 N 94:1721800849:1812777491", "อา สวัสดีอีกครั้ง {name} ข้ากำลังอ่านคลื่นทะเลเหมือนที่ทำเสมอ อะไรนำเจ้ามาที่ด่าน?" },
        completion = { "32:1103297898:1139526637 N 420:1192267186:1842228064", "นี่... เป็นการค้นพบที่น่าทึ่งจริง ๆ {name}\n\nเจ้าบอกว่าได้มาจาก Baron Aquanis ใน Blackfathom หรือ? เชื่อกันมานานว่า Baron Aquanis เป็นพลังธาตุที่แปดเปื้อน ลูกแก้วนี้จะพิสูจน์ได้ว่าอะไรทำให้มันแปดเปื้อน แม้จะไม่น่าแปลกใจหากเป็น Twilight's Hammer การศึกษาของเราก็จะบอกได้ด้วยว่าพวกเขาทำอย่างไร\n\nเจ้าทำถูกแล้วที่นำมาให้ข้า ได้โปรดรับนี่ พร้อมคำขอบคุณอย่างอบอุ่นที่สุดจาก Earthen Ring" },
        required = { [16782] = { "19:1953997721:2094638485", "ลูกแก้วน้ำประหลาด" } },
        steps = { { "19:1953997721:2094638485", "ลูกแก้วน้ำประหลาด" } },
    },
    [6981] = { -- The Glowing Shard
        title = { "17:1402979252:286913873", "เศษผลึกเรืองแสง" },
        objective = { "126:441603161:1975715812", "เดินทางไป Ratchet เพื่อหาคนที่บอกเจ้าได้มากขึ้นเกี่ยวกับเศษผลึกเรืองแสง\n\nจากนั้นนำเศษผลึกไปส่งตามคำชี้แนะที่ได้รับ" },
        description = { "317:725708986:1608979938", "เศษผลึกเป็นสีเขียวเจิดจ้า แม้จะแข็ง แต่สิ่งที่ดูคล้ายควันหมุนวนอยู่ใต้ผิว เจ้าอดจ้องลึกเข้าไปในผลึกไม่ได้ ขณะเดียวกันก็รู้ว่ามีบางอย่างน่าหวั่นใจอย่างยิ่งเกี่ยวกับมัน\n\nบางทีเจ้าควรหาดูว่ามีใครใน Ratchet บอกเรื่องเศษผลึกประหลาดนี้ได้มากกว่านี้ไหม" },
        progress = { "7:989913233:66981971 R 24:44117753:590565424", "สวัสดี {race} มีอะไรให้ข้าช่วย?", variants = { { "39:1347101460:659481747", "สวัสดี สกายบอร์น มีอะไรให้ข้าช่วย?" } } },
        completion = { "45:1547543538:1889448686", "โอ้... ข้าไม่เคยเห็นอะไรเช่นนี้เลย..." },
        required = { [10441] = { "13:1665916638:331728573", "เศษผลึกเรืองแสง" } },
        steps = { { "13:1665916638:331728573", "เศษผลึกเรืองแสง" } },
        objectiveLabels = {
            event = { ["Speak with someone in Ratchet about the Glowing Shard"] = "คุยกับใครสักคนใน Ratchet เรื่อง Glowing Shard" },
        },
    },
    [92401] = { -- A Frightened Request
        title = { "20:1043457100:200049818", "คำขอด้วยใจหวาดหวั่น" },
        objective = { "78:1357471570:1942124769", "สืบหาการหายตัวไปของ Edward Heartweaver ใน Ruins of Lordaeron" },
        description = { "479:896091011:1419881856", "เรื่องสามีข้า Edward...\n\nเขายังไม่กลับจากการไปสุสานในซาก Lordaeron ประจำสัปดาห์ เราสูญเสียลูกชายไปตอน Arthas ทำลายเมือง และ Edward ที่รักของข้ายังเต็มไปด้วยความรู้สึกผิดกับความเศร้าที่เราไม่เคยพบศพลูก ข้าพยายามเตือนไม่ให้เขาไปค้นในซากเมืองที่ถูกยึดครองนั้น แต่เขาไม่ยอมเลิกล้ม ข้าพยายามไม่กังวล ทว่าผ่านมาหลายวันแล้ว\n\nที่นั่นมีสิ่งที่ข้ารับมือไม่ได้ แต่หากเจ้ายินดีช่วย ข้าจำเป็นต้องรู้ชะตาของสามี", variants = { { "476:1267031603:525262903", "เรื่องสามีข้า Edward...\n\nเขายังไม่กลับจากการไปสุสานในซาก Lordaeron ประจำสัปดาห์ เราสูญเสียลูกชายไปตอน Arthas ทำลายเมือง และ Edward ที่รักของข้ายังเต็มไปด้วยความรู้สึกผิดกับความเศร้าที่เราไม่เคยพบศพลูก ข้าพยายามเตือนไม่ให้เขาไปค้นในซากเมืองที่ถูกยึดครองนั้น แต่เขาไม่ยอมเลิกล้ม ข้าพยายามไม่กังวล ทว่าผ่านมาหลายวันแล้ว\n\nที่นั่นมีสิ่งที่ข้ารับมือไม่ได้ แต่หากเจ้ายินดีช่วย ข้าจำเป็นต้องรู้ชะตาของสามี" } } },
        progress = { "36:918543618:1120458898", "ก่อนก็ลูกชายข้า ตอนนี้ก็ Edward ที่รักอีก..." },
        completion = { "234:1524069738:1390872312", "สิ่งที่ข้าขอจากเจ้าไม่ยุติธรรมเลย และหากเจ้าเพียงเดินจากไปก็ไม่ใช่เรื่องผิด ขอบใจ คนแปลกหน้า ข้าไม่มีทางตอบแทนได้ทัดเทียม แต่หวังว่าของชิ้นใดชิ้นหนึ่งนี้จะพอรับได้\n\nหวังว่าเราจะได้พบกันอีกครั้งโดยไม่มีความเศร้าเช่นนี้" },
    },
    [92415] = { -- Remember That I Love You
        title = { "24:462846997:1690912133", "จงจำไว้ว่าข้ารักเจ้า" },
        objective = { "78:513842320:1144126908", "นำ Blood-Stained Letter ไปให้ Orphan Matron Nightingale ใน Stormwind City" },
        description = { "220:551508065:1475553830", "<ห่อกระดาษขาดเปื้อนรอดมาได้อย่างหวุดหวิดจากผืนดินสุสานที่อันเดดย่ำเหยียบ มันกล่าวถึงเด็กที่หายไปจากครอบครัว Heartweaver บางทีผู้ดูแลเด็กกำพร้าใน Stormwind City อาจรู้มากกว่านี้>" },
        progress = { { "45:282168733:223753744", "12:351164566:2103200252 N 27:686083595:543700703", "12:351164566:2103200252 C 27:686083595:543700703", "12:351164566:2103200252 R 27:686083595:543700703" }, "มีอะไรหรือ เพื่อน? เจ้ากำลังหาอะไร?" },
        completion = { "244:1032492485:368388458", "Heartweaver? Heartweaver...\n\nอ้อ! Jeremy Heartweaver ตัวน้อย เขาถูกพามาที่นี่เมื่อหลายปีก่อน หลังการโจมตี Lordaeron เสียพ่อแม่ไปทั้งคู่ในการโจมตี น่าสงสารจริง\n\nที่จริง ไม่นานมานี้มีสตรีใจดีที่ Duskwood รับเขาไปเลี้ยงแล้ว" },
        required = { [251522] = { "20:1426573663:1515986016", "จดหมายเปื้อนเลือด" } },
        steps = { { "20:1426573663:1515986016", "จดหมายเปื้อนเลือด" } },
    },
    [92421] = { -- Light's Justice
        title = { "15:1671550474:1879820354", "ความยุติธรรมแห่งแสงสว่าง" },
        objective = { "92:70437642:1131674925", "รวบรวม Intact Limbs 25 ชิ้นใน Ruins of Lordaeron ให้ Morbin Lightbane ใน Undercity", amount = { "8:1089852795:1107240600 W1 82:2142335818:1067166719", "รวบรวม Intact Limbs {world1} ชิ้นใน Ruins of Lordaeron ให้ Morbin Lightbane ใน Undercity" } },
        description = { "506:176427317:1197022577", "ในฐานะพาลาดินแห่ง Forsaken หน้าที่ข้าคือทำตามประสงค์ Dark Lady พร้อมดูแลความต้องการของผู้คนเรา โชคดีที่มีโอกาสทำทั้งสองอย่างพร้อมกัน\n\nเหนือ Undercity พวก Scourge ยังเพ่นพ่านมากมายโดยไร้การควบคุม กำลังของเราร่อยหรอระหว่างพยายามทวงแผ่นดินคืน และเนื้อหนังเน่าเปื่อยก็ประสานกลับไม่ได้ หากไม่มีส่วนทดแทน\n\nหากกัปตันผู้ทรงเกียรติ Garek Bandarion ยังอยู่กับเรา ข้ารู้ว่าเขาต้องการสิ่งใด ทำสิ่งที่เขาเริ่มไว้ให้สำเร็จและเยียวยาญาติพี่น้องของเรา เพื่อ Lordaeron!" },
        progress = { "90:55724828:552722958", "พวก Scourge ผู้รุกรานเหลืออะไรอยู่บ้าง? เจ้าหาชิ้นส่วนทดแทนที่เหมาะสมได้หรือยัง?" },
        completion = { "172:1127704201:369322770", "จงให้ผู้ที่หลุดพ้นจากพระกรุณาของ Banshee Queen เผชิญความยุติธรรมของเรา!\n\nชิ้นส่วนเหล่านี้ทำให้พี่น้องของเรามีหวังได้เห็นวันพรุ่งนี้ เจ้าทำให้ Captain Bandarion ภูมิใจ" },
        required = { [268580] = { "12:1265498959:9154168", "แขนขาที่ยังสมบูรณ์" } },
        steps = { { "12:1265498959:9154168", "แขนขาที่ยังสมบูรณ์" } },
    },
    [92422] = { -- The Wrath of Rath'mael
        title = { "22:36683576:137089046", "โทสะของ Rath'mael" },
        objective = { "73:5576412:1509626109", "ฆ่า Rath'mael ใน Ruins of Lordaeron ให้ Deathguard Kristof ใน Brill" },
        description = { "360:1420947290:809015454 N 102:1033640798:63108494", "มีรายงานมาจาก Lordamere Overlook ลึกใน Ruins of Lordaeron หมอกอัปมงคลเข้าปกคลุมถนนและสุสาน ช่วยให้ Scourge บนนั้นพรางตัวได้ระดับหนึ่ง\n\nหน่วยสอดแนมระบุว่าผู้เรียกหมอกคือขุมพลังใหม่ในกลุ่มพวกมัน ผู้ใช้มนตร์ปลุกศพชื่อ Rath'mael เราไม่มีเวลารอให้เรื่องนี้ผ่านไปเอง {name}\n\nหากเจ้ามีพันธมิตร จงเรียกพวกเขามาช่วย Forsaken ขับสิ่งมีชีวิตนี้ออกจากดินแดนเรา" },
        completion = { "130:130978018:1321695137", "แม้ข้าไม่สงสัยว่าจะมีสิ่งแบบเขามาทดแทน แต่เราก็ได้แต่หวังว่าจำนวนพวกมันจะลดลงในระหว่างนี้\n\nขอบใจ เพื่อน", variants = { { "123:322442069:550481129 N 1:46:46", "แม้ข้าไม่สงสัยว่าจะมีสิ่งแบบเขามาทดแทน แต่เราก็ได้แต่หวังว่าจำนวนพวกมันจะลดลงในระหว่างนี้\n\nขอบใจ {name}" } } },
        progress = { "39:1963480106:1933820500", "กำจัดนายทหารโครงกระดูกได้แล้วหรือยัง?" },
        objectiveLabels = {
            monster = { ["Rath'mael slain"] = "ปราบ Rath'mael" },
        },
    },
    [95189] = { -- Crest of Lordaeron
        title = { "18:697909594:35465669", "ตราแห่ง Lordaeron" },
        objective = { "69:237186112:1926048245", "คืน Crest of Lordaeron ให้ Lady Dena Kennedy ใน Stormwind City" },
        description = { "170:2144079581:1938842472", "<ตราเก่าโทรมที่แสดงสัญลักษณ์ Lordaeron เมื่อของตกทอดเหลือเพียงน้อยนิดหลังอาณาจักรล่มสลาย ใครสักคนใน Stormwind คงอยากได้สิ่งนี้อย่างมาก>" },
        progress = { "44:1138640386:1982041904", "ยินดีต้อนรับสู่หอจัดแสดง เชิญชมตามสบาย" },
        completion = { { "228:1694964211:913137146", "152:739332749:110119893 N 66:1500405977:72614112", "152:739332749:110119893 C 66:1500405977:72614112", "152:739332749:110119893 R 66:1500405977:72614112" }, "เจ้าไปพบสิ่งนี้ที่ไหนกัน? สภาพมันดีอย่างน่าทึ่ง... เมื่อคิดถึงทุกสิ่งที่เกิดขึ้น\n\nขอบใจที่นำชิ้นส่วนประวัติศาสตร์ Alliance นี้กลับมา นักผจญภัย ข้าจะให้คนที่เก่งที่สุดลงมือบูรณะทันที", variants = { { "152:491531132:685685542 C 66:1500405977:72614112", "เจ้าไปพบสิ่งนี้ที่ไหนกัน? สภาพมันดีอย่างน่าทึ่ง... เมื่อคิดถึงทุกสิ่งที่เกิดขึ้น\n\nขอบใจที่นำชิ้นส่วนประวัติศาสตร์ Alliance นี้กลับมา {class} ข้าจะให้คนที่เก่งที่สุดลงมือบูรณะทันที" } } },
        logReady = { "69:237186112:1926048245", "คืน Crest of Lordaeron ให้ Lady Dena Kennedy ใน Stormwind City" },
        required = { [268579] = { "18:697909594:35465669", "ตราประจำ Lordaeron" } },
        objectiveLabels = {
            item = { ["Crest of Lordaeron"] = "ตราประจำ Lordaeron" },
        },
    },
    [95195] = { -- Bloodied Insignia
        title = { "17:303688575:2004224706", "เครื่องหมายเปื้อนเลือด" },
        objective = { "89:1436266974:1848218892", "รวบรวม Bloodied Insignias 10 ชิ้น แล้วนำไปให้ General Marcus Jonathan ใน Stormwind City", amount = { "8:1089852795:1107240600 W1 79:1378869654:508534029", "รวบรวม Bloodied Insignias {world1} ชิ้น แล้วนำไปให้ General Marcus Jonathan ใน Stormwind City" } },
        description = { "195:1950928082:675891089", "<เครื่องหมาย Alliance เก่านี้ดูเหมือนเคยเป็นของทหาร Lordaeron ซากเมืองเหล่านี้น่าจะเต็มไปด้วยเหรียญตราคล้ายกัน ซึ่งญาติที่ยังมีชีวิตคงซาบซึ้งหากได้รับคืน>" },
        progress = { { "66:2110118154:1448931709", "47:1852654755:2016936532 N 13:1755961457:1529561191", "47:1852654755:2016936532 C 13:1755961457:1529561191", "47:1852654755:2016936532 R 13:1755961457:1529561191" }, "เจ้าดูเหมือนแบกภาระหนักมา เพื่อน มีอะไรหรือ?" },
        completion = { { "320:218460597:1567115577", "249:1220274753:1582906038 N 65:2014797707:199520573", "249:1220274753:1582906038 C 65:2014797707:199520573", "249:1220274753:1582906038 R 65:2014797707:199520573" }, "สัญชาตญาณที่ให้นำสิ่งเหล่านี้มาหาข้าไม่ได้ไร้เหตุผล เมื่อ Lordaeron ตกแก่ Scourge ผู้คนมากมายหนีมาลี้ภัยที่ Stormwind คงเหลือเพียงน้อยคนที่จะมารับเครื่องหมายเหล่านี้ด้วยตนเอง\n\nการทำหน้าที่ต่อ Stormwind ของเจ้าสมควรได้รับคำชื่นชม เพื่อน ข้าจะเริ่มส่งสิ่งแทนใจเหล่านี้ให้ญาติใกล้ชิดทันที", variants = { { "249:1931590065:928964385 N 65:2014797707:199520573", "เจ้าคิดถูกแล้วที่นำสิ่งเหล่านี้มาหาข้า เมื่อ Lordaeron ตกแก่ Scourge ผู้คนมากมายหนีมาลี้ภัยที่ Stormwind คงเหลือเพียงน้อยคนที่จะมารับเครื่องหมายเหล่านี้ด้วยตนเอง\n\nการทำหน้าที่ต่อ Stormwind ของเจ้าสมควรได้รับคำชื่นชม {name} ข้าจะเริ่มส่งสิ่งแทนใจเหล่านี้ให้ญาติใกล้ชิดทันที" } } },
        required = { [268540] = { "17:303688575:2004224706", "ตราที่เปื้อนเลือด" } },
        steps = { { "17:303688575:2004224706", "ตราที่เปื้อนเลือด" } },
    },
