        title = { "18:697909594:35465669", "ตราแห่ง Lordaeron" },
        objective = { "62:574888290:1852571124", "นำ Crest of Lordaeron ไปให้ Oran Snakewrithe ใน Undercity" },
        description = { "174:1858406425:1759865080", "<ตราเก่าโทรมที่แสดงสัญลักษณ์ Lordaeron เมื่อของตกทอดเหลือเพียงน้อยนิดหลังอาณาจักรล่มสลาย ใครสักคนใน Undercity คงอยากได้สิ่งนี้อย่างมาก>" },
        progress = { "52:554967009:411394935", "เจ้าได้อะไรมา นักผจญภัย? ของกินโอชะหรือ?", variants = { { "25:1918645140:1241363237 C 17:2012881256:1549862315", "เจ้าได้อะไรมา {class}? ของกินโอชะหรือ?" } } },
        completion = { "202:84587619:1426722360 C 48:1771957472:884687286", "<Oran กัดตราเพื่อดูว่าเป็นของแท้หรือเปล่า>\n\nโอ้โฮ ของเก่าจากบ้านเราแท้ ๆ เสียด้วย ยังอยู่เกือบครบเลย เราต้องระวังกับชิ้นนี้เป็นพิเศษ\n\nขอบใจที่ช่วยฟื้นคืนประวัติศาสตร์ของเรา {class} ข้าจะดูแลให้เราเก็บรักษามันอย่างดี" },
        required = { [275521] = { "18:697909594:35465669", "ตราสัญลักษณ์ Lordaeron" } },
        steps = { { "18:697909594:35465669", "ตราสัญลักษณ์ Lordaeron" } },
    },
    [95216] = { -- The New Plague
        title = { "14:1571720665:548007023", "โรคระบาดชนิดใหม่" },
        objective = { "103:486690655:1780885398", "เก็บ Highly Toxic Strain จาก Witherfang ใน Ruins of Lordaeron ให้ Theodore Griffs ใน Undercity" },
        description = { "498:431832106:2020212666", "ยินดีต้อนรับสู่อวัยวะสำคัญที่สุดของ Undercity นั่นคือ Apothecarium! ที่นี่เราทดลองกับตัวอย่างสิ่งมีชีวิตแปลกถิ่นที่มีพิษร้ายแรงที่สุดของ Azeroth\n\nเจ้ามาตอนข้าอารมณ์ดีพอดี ข้าจึงจะบอกการศึกษาล่าสุดให้ฟัง ดูเหมือนมีสัตว์ขาปล้องพิษร้ายเป็นพิเศษตัวหนึ่งย่องอยู่ในซากเมืองเหนือมหานครอันงดงามของเรา ว่ากันว่าพิษมันกัดกร่อนได้แม้แต่เนื้ออันเดด ช่างน่าตื่นเต้น!\n\nข้าอยากพิสูจน์คำกล่าวเหล่านี้ หากเจ้าถูกมันกัดจนร่างเหี่ยวเฉา ข้าจะยินดีมากหากได้ตัวอย่าง" },
        progress = { "126:89466325:2088482759", "คนโง่ที่ไหนก็บอกได้ว่าวิธีแพร่ที่รุนแรงที่สุดย่อมผ่านทางเลือดเสมอ\n\nข้าต้องเห็นสายพันธุ์นี้ด้วยตนเอง!" },
        completion = { "173:1238354760:536383470", "เจ้าฆ่ามันหรือ??\n\nฮึ่ม โชคดีสำหรับเจ้าที่ของเหลวนี้คงพอให้ข้าย้อนศึกษาคุณสมบัติของมันได้ ข้าคาดหวังจากนักเล่นแร่แปรธาตุด้วยกันมากกว่านี้เสียอีก\n\nไปให้พ้นหน้าข้า!", variants = { { "185:692318117:997715826", "เจ้าฆ่ามันหรือ??\n\nฮึ่ม โชคดีสำหรับเจ้าที่ของเหลวนี้คงพอให้ข้าย้อนศึกษาคุณสมบัติของมันได้ เจ้าไม่อยากเป็นศัตรูกับ Royal Apothecary Society หรอก\n\nไปให้พ้นหน้าข้า!" } } },
        required = { [275443] = { "19:1582637688:852570816", "สายพันธุ์ที่มีพิษสูง" } },
        steps = { { "19:1582637688:852570816", "สายพันธุ์ที่มีพิษสูง" } },
    },
    [95250] = { -- Abominable Creatures
        title = { "20:1411610688:2076467298", "สิ่งมีชีวิตอันน่าสะอิดสะเอียน" },
        objective = { "92:1755192741:1182646293", "เก็บ Head of the Baron ใน Ruins of Lordaeron แล้วนำกลับไปให้ Captain Truman" },
        description = { "18:678499973:1231431024 R 390:1436791695:1414286339", "เจ้าต้องการอะไร {race}? ไม่เห็นหรือว่ามีสงครามที่เราต้องชนะ?\n\nนายข้าบุกเข้าสู่การต่อสู้แล้ว และสั่งให้ข้าประจำอยู่ที่นี่ แต่ก็ผ่านมานานพอควรแล้ว\n\nข้าสงสัยว่าเจ้าจะรอดในสนามรบถึงสิบนาทีหรือไม่ แต่ถ้ามันช่วยให้สมองทึบ ๆ ของเจ้ามีอะไรทำ ทำไมไม่ไปหา Grand Marshal ล่ะ? เขาเป็นวีรบุรุษที่สูงสง่า ยิ่งกว่าใครที่เจ้าเคยเห็น พอพบเจ้าก็จะรู้เอง", variants = { { "434:391156010:1632726667", "อา เพื่อนมนุษย์ด้วยกัน ถึงเวลาเสียทีที่ Lordaeron ส่งกำลังเสริมมา\n\nนายข้าบุกเข้าสู่การต่อสู้แล้ว และสั่งให้ข้าประจำอยู่ที่นี่ แต่ก็ผ่านมานานพอควรแล้ว\n\nข้าไม่กล้าฝากงานนี้ไว้กับพวกลูกครึ่งโสโครกนั่น หากพอจะขอให้เจ้าช่วยได้ ข้าขอร้องให้เจ้าไปตามหา Grand Marshal ให้ข้าที เขาเป็นวีรบุรุษที่สูงสง่ายิ่งกว่าใครที่เจ้าเคยเห็น พอพบเจ้าจะรู้เอง" } } },
        progress = { "88:1395425663:813493289", "ดีใจที่เจ้ายังมีชีวิตและแข็งแรง! การรบเป็นอย่างไรบ้าง? เห็นนายข้าหรือยัง?", variants = { { "72:775117370:2145033116", "เจ้ายังไม่ตายอีกหรือ? ฮึ่ม ว่าอย่างไรล่ะ? เจอนายข้าหรือยัง?" } } },
        completion = { "418:240654073:1731144104", "Truman มองศีรษะอดีตนายของตนด้วยความสยดสยองและรังเกียจ\n\nนี่มัน... เรื่องตลกหรืออย่างไร? ทำไมเจ้าถึงเอาศีรษะสัตว์ประหลาดนี่มาให้ข้า?\n\nไปให้พ้นหน้าข้า! ข้าน่าจะรู้ว่าไว้ใจคนที่ร่วมมือกับพวกโสมมอย่างที่เจ้าทำไม่ได้ บุตรที่แท้จริงแห่ง Lordaeron จะทวงบ้านเราคืน และเมื่อถึงวันนั้น เราจะได้กวาดล้างพวกอสูรและคนที่คบหาพวกมันอย่างเจ้าให้สิ้นเสียที!", variants = { { "420:762337445:1296711264", "<Truman มองศีรษะของอดีตนายด้วยความตกตะลึงและรังเกียจ>\n\nนี่มัน... ล้อกันเล่นหรือ? ทำไมเจ้าถึงเอาหัวของสัตว์ประหลาดตัวนี้มาให้ข้า?\n\nไปให้พ้นหน้าข้า! ข้าน่าจะรู้ว่าไว้ใจคนที่เข้าพวกกับสิ่งโสมมอย่างที่เจ้าทำไม่ได้ บุตรที่แท้จริงแห่ง Lordaeron จะทวงบ้านของเราคืน และเมื่อถึงวันนั้น เราจะได้กวาดล้างพวกอสูรและคนที่คบหากับพวกมันอย่างเจ้าเสียที!" }, { "359:375775444:1299118005", "<Truman มองศีรษะอดีตนายของตนด้วยความสะพรึงและรังเกียจ>\n\nนี่มัน... เรื่องตลกหรืออย่างไร? ทำไมเจ้าถึงเอาศีรษะสัตว์ประหลาดนี่มาให้ข้า?\n\nไปให้พ้นหน้าข้า! ข้าน่าจะรู้ว่าไว้ใจเผ่าพันธุ์ต่ำต้อยโสโครกอย่างเจ้าไม่ได้ บุตรที่แท้จริงแห่ง Lordaeron จะทวงบ้านของเราคืน ถึงตอนนั้นเราจะได้กวาดล้างสัตว์ร้ายอย่างเจ้าให้สิ้นเสียที!" } } },
        required = { [268518] = { "17:1693310088:789760135", "ศีรษะของบารอน" } },
        steps = { { "17:1693310088:789760135", "ศีรษะของบารอน" } },
    },
    [96394] = { -- The Restless Dead
        title = { "17:447746182:490853466", "ผู้ตายไม่สงบ" },
        objective = { "87:881893802:1198192260", "ฆ่า Enraged Apparitions 15 ตน, Tormented Souls 10 ตน และทำให้วิญญาณ Anvilmar สงบ", amount = { "5:409775429:850574908 W1 22:1475871590:1102389696 W2 56:1919355815:184442456", "ฆ่า Enraged Apparitions {world1} ตน, Tormented Souls {world2} ตน และทำให้วิญญาณ Anvilmar สงบ" } },
        description = { "356:1818055170:1125626953", "มีบางสิ่งรบกวนสุสานใต้ Hall of Thanes และได้ยินเสียงประหลาดจากส่วนลึกของห้องเก็บศพ วิญญาณผู้ตายหลับตื้น และสิ่งที่เกิดข้างล่างดูเหมือนทำให้พวกเขาตื่นตกใจ\n\nลงไปดูว่าจะช่วยจัดการอะไรให้เราได้บ้าง หากผู้ตายตนใดตื่นขึ้น... ก็ทำให้พวกเขากลับไปนอนเสีย!" },
        progress = { "70:970087629:509229118", "ข้าไม่มีเวลาให้กูลกับผี ข้ามีงานต้องทำข้างล่างนี่" },
        completion = { "149:718775099:2072490041", "อา ดี เสร็จแล้วสินะ ข้าจะปล่อยให้ผู้ดูแลคนอื่นไม่ยอมเข้าหอไปทำหน้าที่เพราะ \"ผี\" กับ \"คนตายขี้โมโห\" ไม่ได้ จริงไหม?", variants = { { "148:291474152:864717773", "อา ดี เสร็จแล้วสินะ ข้าจะปล่อยให้ผู้ดูแลคนอื่นไม่ยอมเข้าหอไปทำหน้าที่เพราะ \"ผี\" กับ \"คนตายขี้โมโห\" ไม่ได้ จริงไหม?" } } },
        objectiveLabels = {
            monster = { ["Enraged Apparition slain"] = "ปราบ ภูตพิโรธ", ["Tormented Soul slain"] = "ปราบ วิญญาณทุกข์ทรมาน" },
        },
    },
    [96403] = { -- Important Heirlooms
        title = { "19:1073962251:1851961618", "มรดกชิ้นสำคัญ" },
        objective = { "52:140481702:311650989", "รวบรวม Dwarven Heirlooms 8 ชิ้นจาก Hall of Thanes", amount = { "8:1089852795:1107240600 W1 43:1551098386:2033764861", "รวบรวม Dwarven Heirlooms {world1} ชิ้นจาก Hall of Thanes" } },
        description = { "475:2129902709:1062905834", "เจ้าน่ะ นักผจญภัย... ข้าต้องการความช่วยเหลือจากเจ้ามาก\n\nข้ากำลังลอบเข้าไป... เอ่อ... 'ลาดตระเวน' ในห้องเก็บสมบัติ ตอนที่กองคนแคระ Dark Iron โผล่จากใต้ดินด้วยเครื่องจักรตัวตุ่น! ข้าไม่รู้ว่ามาทำไม แต่ข้างล่างมีของปล้นล้ำค่า... เอ่อ หรือให้ถูก... ข้าหมายถึง 'มรดกสำคัญทางวัฒนธรรม'! ได้โปรดเก็บของตกทอดที่พบแล้วนำกลับมาที่นี่\n\nข้ารับรองว่าทุกสิ่งที่เจ้าเก็บมาจะถูกลงบัญชีและนำกลับไปไว้ในตำแหน่งอันทรงเกียรติที่เหมาะสม" },
        progress = { "73:1239766319:624336466", "Thom ดูเหมือนจะถูมือไปมาโดยไม่รู้ตัวขณะมองเจ้า", variants = { { "75:1700793858:1852234312", "<Thom ดูเหมือนจะถูมือไปมาโดยไม่รู้ตัวขณะมองเจ้า>" } } },
        completion = { "317:1994694197:1769550348", "ดูเจ้าสิ ทั้งกล้าหาญทั้งรู้จักคว้าโอกาส! ข้าเป็นโนมที่รักษาคำพูด และเจ้าสมควรได้รับรางวัลแล้ว!\n\nเอาละ ขอดูของที่กวาดมา... เอ่อ หมายถึง... มรดกที่กู้คืนมา ข้าต้องเริ่มประเมินราคา... ขอโทษที 'ลงบัญชี' มัน เพื่อจะได้นำกลับไปไว้ที่ที่เหมาะสมโดยเร็วที่สุด", variants = { { "317:1076699191:987200327", "ดูเจ้าสิ ทั้งกล้าหาญทั้งรู้จักคว้าโอกาส! ข้าเป็นโนมที่รักษาคำพูด และเจ้าสมควรได้รับรางวัลแล้ว!\n\nเอาละ ขอดูของที่กวาดมา... เอ่อ หมายถึง... มรดกที่กู้คืนมา ข้าต้องเริ่มประเมินราคา... ขอโทษที 'ลงบัญชี' มัน เพื่อจะได้นำกลับไปไว้ที่ที่เหมาะสมโดยเร็วที่สุด" } } },
        required = { [274289] = { "16:28674251:1408450580", "มรดกตกทอดของคนแคระ" } },
        steps = { { "16:28674251:1408450580", "มรดกตกทอดของคนแคระ" } },
    },
    [870] = { -- The Forgotten Pools
        title = { "19:1268441762:1218923392", "แอ่งน้ำที่ถูกลืม" },
        objective = { "50:1793440565:1818057861", "กลับไปรายงานสิ่งที่พบให้ Tonga Runetotem" },
        description = { "492:1518508906:1737411563", "นานมาแล้ว Barrens เขียวชอุ่มและเต็มไปด้วยชีวิต แต่สงครามกับมหันตภัยโหมทั่วแผ่นดิน เผาผลาญจนเหลือเพียงซากแห้งแล้ง นั่นคือวิถีของสิ่งต่าง ๆ และทำให้หัวใจข้าเศร้าหมอง\n\nแต่ไม่กี่ปีมานี้ มีโอเอซิสใหม่เกิดขึ้นใน Barrens และชีวิตเริ่มเคลื่อนไหว ลึกลงไป พวกเราดรูอิดสัมผัสได้ถึงพลังที่รั่วไหลขึ้นสู่ผิวดิน\n\nเราต้องหาต้นตอ เดินทางไป Forgotten Pools ทางตะวันตกเฉียงเหนือของ Crossroads ค้นหาต้นกำเนิดพลังในน้ำ แล้วกลับมาที่นี่" },
        progress = { "38:1413443676:1279355088 N 24:1372882170:855646962", "ไป Forgotten Pools มาแล้วหรือ {name}? พบอะไรบ้าง?" },
        completion = { "193:1431772550:1495584709", "เจ้าพบรอยแยกในดินที่มีก๊าซผุดเป็นฟองออกมาหรือ? แปลก นี่อาจเป็นคำตอบของคำถามเรา แต่ยังมั่นใจไม่ได้\n\nอย่างน้อยก็เป็นเบาะแส และข้าซาบซึ้งที่เจ้าพบมัน" },
        objectiveLabels = {
            event = { ["Explore the waters of the Forgotten Pools"] = "สำรวจแหล่งน้ำใน Forgotten Pools" },
        },
    },
    [877] = { -- The Stagnant Oasis
        title = { "18:1207469756:2145031428", "โอเอซิสน้ำนิ่ง" },
        objective = { "74:250180520:148204928", "กลับไปหา Tonga ที่ Crossroads หลังตรวจสอบ Stagnant Oasis" },
        description = { "368:814606573:121563408", "โอเอซิสอื่นใน Barrens อาจมีรอยแยกเหมือนที่เจ้าพบใน Forgotten Pools หากเป็นเช่นนั้น รอยแยกอาจเป็นแหล่งชีวิตของโอเอซิส\n\nเราต้องทดสอบ\n\nเอ้านี่ รับเมล็ดไป มันตายแล้วและงอกไม่ได้ แต่ให้นำไป Stagnant Oasis ทางตะวันออกเฉียงใต้ หากมีรอยแยกที่นั่น จงวางเมล็ดลงไป... แล้วสังเกต" },
        progress = { "76:393302579:1276828837", "ไป Stagnant Oasis มาแล้วหรือ? มีรอยแยกอยู่ใต้น้ำไหม?" },
        completion = { "159:1788281936:577105225", "สิ่งที่เจ้าพบน่าอัศจรรย์! เมล็ดที่ข้าให้แห้งและตายแล้ว สิ่งใดก็ตามใต้โอเอซิสเหล่านี้สร้างชีวิตจากความว่างเปล่าได้!\n\nเราต้องศึกษาให้มากขึ้น..." },
        steps = { { "20:1855562782:1258167859", "ทดสอบ Dried Seeds" } },
    },
    [880] = { -- Altered Beings
        title = { "14:2075257522:702616117", "สิ่งมีชีวิตที่เปลี่ยนไป" },
        objective = { "68:1514010331:741445530", "นำ Altered Snapjaw Shells 8 ชิ้นไปให้ Tonga Runetotem ที่ Crossroads" },
        description = { "30:1874894482:534661326 N 288:1393417429:1688227110", "สิ่งที่เจ้าพบน่าทึ่ง {name} คุณสมบัติของโอเอซิสเหล่านี้ต้องมาจากต้นกำเนิดภายนอก หรืออาจเป็นภายใน\n\nข้าอยากรู้ว่ารอยแยกเหล่านี้ส่งผลอย่างไรต่อสัตว์ที่ดื่มน้ำโอเอซิส\n\nล่า Oasis Snapjaw ที่ Lushwater Oasis กับ Stagnant Oasis นำกระดองมาให้ข้าตรวจดู" },
        progress = { "49:114607308:563448582", "การรวบรวมเป็นอย่างไร? ได้กระดองมาหรือยัง?" },
        completion = { "11:1191658970:1224418299 N 224:531142981:523343411", "ขอบใจ {name} การศึกษาสัตว์ในพื้นที่บอกเรื่องพื้นที่นั้นได้มาก เราจะได้เห็นว่ากระดองเหล่านี้เล่าเรื่องอะไร\n\nโปรดรับคำขอบคุณที่ช่วยข้า... และบางทีเหรียญเหล่านี้อาจมีประโยชน์กับเจ้า ข้าพบว่าตนไม่ต้องใช้มัน" },
        required = { [5098] = { "21:453788807:1832823688", "กระดอง Snapjaw ที่เปลี่ยนสภาพ" } },
        steps = { { "21:453788807:1832823688", "กระดอง Snapjaw ที่เปลี่ยนสภาพ" } },
    },
    [886] = { -- The Barrens Oases
        title = { "17:396529355:699889518", "โอเอซิสแห่ง Barrens" },
        objective = { "45:1690757784:1613323383", "คุยกับ Tonga Runetotem ที่ Crossroads" },
        description = { "453:1701416928:257446652 N 34:1149218592:202949152", "เหล่าดรูอิดแห่ง Thunder Bluff สัมผัสพลังประหลาดที่รั่วไหลเข้าสู่ Barrens ทางตะวันออกของ Mulgore\n\nTonga Runetotem ถูกส่งไปหาต้นตอของพลังนี้ แต่เราเกรงว่าเขาจะต้องการความช่วยเหลือ\n\nเดินทางไป Barrens แล้วคุยกับ Tonga เขาจะอยู่ที่ Crossroads เส้นทางคือใช้ถนนออกจากหมู่บ้าน Bloodhoof ไปทางตะวันออก เข้าสู่ Barrens แล้วเลี้ยวเหนือเมื่อถนนแยก ขึ้นเหนือไปเรื่อย ๆ ก็จะพบ Crossroads\n\nอย่าออกนอกถนน {name} เพราะ Barrens เป็นดินแดนอันโหดร้าย" },
        completion = { "58:1049397216:903587201 C 133:1920563240:1094995700", "พี่น้องข้าที่ Thunder Bluff คิดถูกแล้วที่ส่งเจ้ามา {class}รุ่นเยาว์ เพราะปริศนาแห่ง Barrens ไม่ใช่สิ่งที่ข้าแก้ได้ลำพัง\n\nเมื่อมีเจ้าช่วย ก็หวังว่าเราจะพบคำตอบของคำถามเหล่านี้" },
    },
    [3301] = { -- Mura Runetotem
        title = { "14:482964749:416104097", "Mura Runetotem" },
        objective = { "43:824862639:278518835", "คุยกับ Mura Runetotem ที่ Sepulcher" },
        description = { "472:327978058:1876870130", "Mura Runetotem คนร่วมเผ่าข้าเดินทางไป Silverpine เพื่อช่วยพันธมิตรอันเดด ป่า Silverpine ป่วยไข้และกำลังตาย Mura หวังนำชีวิตใหม่ไปให้ บางทีชีวิตประหลาดที่พบใน Barrens อาจช่วยงานของนางใน Silverpine ได้\n\nนำตัวอย่างกระดองที่เจ้ารวบรวมไปให้ Mura ใน Silverpine นางพักอยู่ที่ Sepulcher หากโชคดี การศึกษากระดองจะให้ความเข้าใจที่นางต้องใช้เยียวยาสถานที่ใกล้ตายนั้น" },
        progress = { "44:1549082371:1178509130 C 24:320364938:928209899", "ข้าได้กลิ่นฝุ่น Barrens จากตัวเจ้า {class} เจ้าเดินทางมาไกลนัก" },
        completion = { "126:1643643791:2088652890 N 88:1755745163:61441808", "อา นี่อะไร? กระดองนี้เรืองแสงจากภายใน ราวกับยังเต้นตุบด้วยชีวิต น่าอัศจรรย์! ข้าต้องศึกษาให้ลึกกว่านี้\n\nขอบใจ {name} หากโชคดี กระดองนี้อาจซ่อนความลับที่ข้าใช้ช่วยแผ่นดิน Silverpine อันน่าสงสารได้" },
        required = { [10414] = { "20:1879962410:1696827836", "ตัวอย่างกระดอง Snapjaw" } },
        steps = { { "20:1879962410:1696827836", "ตัวอย่างกระดอง Snapjaw" } },
    },
    [865] = { -- Raptor Horns
        title = { "12:724865466:755065958", "เขาแรปเตอร์" },
        objective = { "100:1067696351:1982701021", "รวบรวม Intact Raptor Horns 5 ชิ้นจาก Sunscale Scytheclaws แล้วนำไปให้ Mebok Mizzyrix ใน Ratchet" },
        description = { "417:101627364:67622138", "แรปเตอร์ใน Barrens ฉลาดกว่าแรปเตอร์ในดินแดนอื่น ข้าคิดว่าความฉลาดทั้งหมดซ่อนอยู่ในเขาของมัน! ถ้าใช่ ข้าก็บดเขาเป็นผงแล้วนำมาทำ \"เครื่องดื่มเพิ่มปัญญา\" ได้ ข้าจะขายจนรวยมหาศาล!!!\n\nเจ้าช่วยข้าได้ หาเขาแรปเตอร์ที่สมบูรณ์จาก Sunscale Scytheclaws มา พวกมันเดินอยู่ใน Barrens ตอนใต้ และทางตอนเหนือใกล้ชายแดนป่า Ashenvale" },
        progress = { "23:290261031:1089852736 N 46:1297708483:481495717", "ได้เขามาหรือยัง {name}? ของพวกนั้นจะทำข้ารวยแน่!" },
        completion = { "92:644566561:558904239", "ดีมาก ได้มาแล้ว! ตอนนี้แค่บดมันแล้วผสมกับไวน์ และ..." },
        required = { [5055] = { "18:1113938262:1873673528", "เขาแรปเตอร์สภาพสมบูรณ์" } },
        steps = { { "18:1113938262:1873673528", "เขาแรปเตอร์สภาพสมบูรณ์" } },
    },
    [3369] = { -- In Nightmares
        title = { "13:1697284088:1349555023", "ในห้วงฝันร้าย" },
        objective = { "60:1745223163:808948833", "นำ Nightmare Shard ไปให้ Hamuul Runetotem บน Elder Rise" },
        description = { "205:449542637:1858894092 N 199:793952715:1602141935", "เศษผลึกนี้มีความลับยิ่งใหญ่ เป็นแก่นแท้บริสุทธิ์ของ Emerald Dream แต่สิ่งที่ข้าเห็นในนั้นไม่ใช่ความฝัน ภาพเช่นนี้คงเรียกว่าฝันร้าย\n\nข้าไม่อยากให้เจ้าตื่นกลัว {name} แต่คิดว่าควรส่งเศษผลึกนี้ถึงมือดรูอิดผู้มีปัญญาโดยเร็วที่สุด\n\nคนที่เจ้าต้องไปหาคือ Hamuul Runetotem บน Elder Rise มุ่งหน้าไป Thunder Bluff ข้าพูดได้เพียงเท่านี้" },
        progress = { "30:1025149654:1788159191", "มีอะไรให้ข้าช่วยไหม?" },
        completion = { "157:479045883:1411552949 N 291:679630998:1044868399", "Falla ส่งเจ้ามาหาข้าหรือ? เอาละ ขอดูเศษผลึกที่เจ้าว่านางลังเลจะพูดถึงหน่อย...\n\n<Hamuul เพ่งมองเข้าไปในเศษผลึก>\n\nโอ้... ข้าไม่... เอาละ\n\n{name} ขอบใจที่นำมาให้ แต่ข้าขอแนะนำว่าไม่ควรพูดเรื่องเช่นนี้ มันเป็นเรื่องที่เจ้าไม่ควรเข้าไปเกี่ยวข้อง\n\nเอาเป็นว่าสิ่งต่าง ๆ ใน Emerald Dream ไม่ได้เป็นอย่างที่เราคิด...\n\nบางทีในภายหน้า เส้นทางเราอาจบรรจบกันอีก" },
        required = { [10649] = { "15:1978474218:1305947095", "เศษผลึกฝันร้าย" } },
        steps = { { "15:1978474218:1305947095", "เศษผลึกฝันร้าย" } },
    },
    [3370] = { -- In Nightmares
        title = { "13:1697284088:1349555023", "ในห้วงฝันร้าย" },
        objective = { "64:569842753:1734894730", "นำ Nightmare Shard ไปให้ Mathrengyl Bearwalker ใน Darnassus" },
        description = { "205:449542637:1858894092 N 211:2058111128:1644727529", "เศษผลึกนี้มีความลับยิ่งใหญ่ เป็นแก่นแท้บริสุทธิ์ของ Emerald Dream แต่สิ่งที่ข้าเห็นในนั้นไม่ใช่ความฝัน ภาพเช่นนี้คงเรียกว่าฝันร้าย\n\nข้าไม่อยากให้เจ้าตื่นกลัว {name} แต่คิดว่าควรส่งเศษผลึกนี้ถึงมือดรูอิดผู้มีปัญญาโดยเร็วที่สุด...\n\nคนที่เจ้าต้องไปหาคือ Mathrengyl Bearwalker ใน Cenarion Circle มุ่งหน้าไป Darnassus ข้าพูดได้เพียงเท่านี้" },
        progress = { "30:1025149654:1788159191", "มีอะไรให้ข้าช่วยไหม?" },
        completion = { "161:554753500:422885185 N 295:1427993083:2097301916", "Falla ส่งเจ้ามาหาข้าหรือ? เอาละ ขอดูเศษผลึกที่เจ้าว่านางลังเลจะพูดถึงหน่อย...\n\n<Mathrengyl เพ่งมองเข้าไปในเศษผลึก>\n\nโอ้... ข้าไม่... เอาละ\n\n{name} ขอบใจที่นำมาให้ แต่ข้าขอแนะนำว่าไม่ควรพูดเรื่องเช่นนี้ มันเป็นเรื่องที่ดรูอิด Cenarion เท่านั้นต้องจัดการ\n\nเอาเป็นว่าสิ่งต่าง ๆ ใน Emerald Dream ไม่ได้เป็นอย่างที่เราคิด...\n\nบางทีในภายหน้า เส้นทางเราอาจบรรจบกันอีก" },
        required = { [10649] = { "15:1978474218:1305947095", "เศษผลึกฝันร้าย" } },
        steps = { { "15:1978474218:1305947095", "เศษผลึกฝันร้าย" } },
    },
    [95161] = { -- Remember That I Love You
        title = { "24:462846997:1690912133", "จงจำไว้ว่าข้ารักเจ้า" },
        objective = { "64:1377015730:1339279105", "นำ Blood-Stained Letter ไปให้ Avette Fellwood ใน Duskwood" },
        description = { "316:780676124:1179643407", "หากเจ้าตามหา Jeremy Heartweaver ทางที่ดีที่สุดคงไปคุยกับแม่บุญธรรมคนใหม่ Avette Fellwood ใน Duskwood นางเป็นสตรีใจดี คงต้องการคนเพิ่มมาช่วยงาน แต่ก็ดีกว่าอยู่สถานเลี้ยงเด็กกำพร้า\n\nหากพบ Jeremy ตัวน้อย ช่วยบอกเขาด้วยว่าพวกเราทุกคนคิดถึงเขา ได้ไหม?", variants = { { "315:601358691:1556871840", "หากเจ้าตามหา Jeremy Heartweaver ทางที่ดีที่สุดคงไปคุยกับแม่บุญธรรมคนใหม่ Avette Fellwood ใน Duskwood นางเป็นสตรีใจดี คงต้องการคนเพิ่มมาช่วยงาน แต่ก็ดีกว่าอยู่สถานเลี้ยงเด็กกำพร้า\n\nหากพบ Jeremy ตัวน้อย ช่วยบอกเขาด้วยว่าพวกเราทุกคนคิดถึงเขา ได้ไหม?" } } },
        progress = { "22:404515733:30197781", "ว่าอย่างไร? เจ้าต้องการอะไร?" },
        completion = { "446:495767332:1788310884", "โอ้ ไม่นะ...\n\nเจ้าใจดีที่นำสิ่งนี้มา แต่ข้าไม่คิดว่า Jeremy พร้อมจะเห็นมัน Matron Nightingale บอกว่า Jeremy ตัวน้อยของข้าไม่พูดมาตั้งแต่การโจมตี Lordaeron และข้าก็ไม่คิดจะบังคับเขาตอนนี้ การให้เขาเห็นมันมีแต่จะเพิ่มความเจ็บปวด\n\nอย่ามองข้าแบบนั้น ข้าจะไม่ปิดบังอดีตจากเขา แต่เขาต้องการเวลาเยียวยา ข้าจะมอบสิ่งนี้ให้เมื่อเขาโตกว่านี้ ขอบใจที่แวะมา แต่ข้าว่าเจ้าควรไปได้แล้ว" },
        required = { [251522] = { "20:1426573663:1515986016", "จดหมายเปื้อนเลือด" } },
        objectiveLabels = {
            item = { ["Blood-Stained Letter"] = "จดหมายเปื้อนเลือด" },
        },
    },
    [866] = { -- Root Samples
        title = { "12:379968010:405670370", "ตัวอย่างรากพืช" },
        objective = { "50:1937232573:1060483763", "นำ Root Samples 8 ชิ้นไปให้ Mebok Mizzyrix ใน Ratchet" },
        description = { "429:883521870:391903245", "สมุนไพรใน Barrens ไม่เหมือนสมุนไพรในดินแดนอื่นนัก คุณสมบัติส่วนใหญ่เหมือนกัน แต่น้ำโอเอซิสที่นี่เปลี่ยนพืชให้ต่างออกไปเล็กน้อย\n\nข้าอยากศึกษาความต่างเหล่านั้น... เพื่อดูว่าจะหาประโยชน์ได้ไหม!\n\nหากเจ้าชำนาญการเก็บสมุนไพร จงเก็บตัวอย่างรากจากสมุนไพรที่พบใน Barrens นำกลับมาให้ข้าเปรียบเทียบกับสมุนไพรจากภูมิภาคอื่น" },
        progress = { "7:989913233:66981971 N 33:1969928862:1379693363", "สวัสดี {name} ได้ตัวอย่างรากพืชหรือยัง?" },
        completion = { "260:1538089603:1219846686", "ใช่ ใช่ พวกนี้ดีมาก! ข้าจะเพาะตัวอย่างจากรากเหล่านี้แล้วศึกษา หวังว่าจะพบคุณสมบัติใหม่ที่ซ่อนอยู่และมีค่า...!\n\nไม่ต้องห่วง หากพบอะไรเจ้าจะรู้เป็นคนแรก เพราะข้าจะต้องหาคนไปเก็บเพิ่ม!" },
        required = { [5056] = { "11:1288297469:1035856022", "ตัวอย่างรากพืช" } },
        steps = { { "11:1288297469:1035856022", "ตัวอย่างรากพืช" } },
    },
    [1559] = { -- Flash Bomb Recipe
        title = { "17:884379495:2088832109", "สูตรระเบิดแสง" },
        completion = { "151:375961044:813954910", "เจ้าเป็นวิศวกรสินะ? เอาละ เพื่อขอบคุณที่ช่วยหาไข่มุกมาให้ นี่คือสูตรระเบิดแสง\n\nโชคดี และพยายามอย่าทำให้ตัวเองตาบอดล่ะ!" },
    },
    [1578] = { -- Supplying the Front
        title = { "19:276989810:1070929420", "ส่งเสบียงสู่แนวหน้า" },
        objective = { "99:693014657:1765778304", "นำ Copper Axes 6 ชิ้น และ Copper Chain Belts 6 ชิ้นไปให้ Thorvald ในหอยามทางใต้ของ Loch Modan", variants = { { "98:1749093762:620020401", "นำ Copper Axes 6 ชิ้น และ Copper Chain Belts 6 ชิ้นไปให้ Thorvald ในหอยามทางใต้ของ Loch Modan" } } },
        description = { "476:1908324144:926378397", "เหล่า Mountaineer แห่ง Loch Modan กำลังรบกับโทรกก์ และวุ่นกันมาก! หากเราจะคุมสถานการณ์ได้ พวกเขาต้องมีเกราะกับอาวุธใหม่ส่งให้อย่างต่อเนื่อง\n\nเพื่อนร่วมงานข้าชื่อ Thorvald จึงอยู่ที่นั่น พยายามให้เหล่า Mountaineer มีอุปกรณ์ดี ๆ ใช้ หากเจ้าทำขวานทองแดงกับเข็มขัดโซ่ทองแดงไปให้ Thorvald เขาคงซาบซึ้ง อาจแบ่งปันความรู้ให้เจ้าด้วย\n\nThorvald อยู่ในหอยามทางใต้ของ Loch Modan" },
        progress = { "53:1796474640:357833660", "ข้าไม่มีเวลาคุยเล่น เจ้ามีธุระอะไร?" },
        completion = { "173:700378322:1241639809", "อา ขอโทษด้วย! ข้าไม่รู้ว่าเจ้ามาช่วยส่งอุปกรณ์ให้ทหารเรา ของที่เจ้าทำจะช่วยได้มาก!\n\nนี่คือแบบเกราะบางอย่าง หวังว่าจะมีประโยชน์กับเจ้า" },
        required = { [2845] = { "10:1315722971:1190362594", "ขวานทองแดง" }, [2851] = { "17:157326378:1346952868", "เข็มขัดโซ่ทองแดง" } },
        steps = { { "10:1315722971:1190362594", "ขวานทองแดง" }, { "17:157326378:1346952868", "เข็มขัดโซ่ทองแดง" } },
    },
    [1581] = { -- Elixirs for the Bladeleafs
        title = { "26:702963073:744612190", "น้ำยาสำหรับครอบครัว Bladeleaf" },
        objective = { "97:543969865:1093946355", "นำ Elixirs of Lion's Strength 6 ชิ้น และ Elixirs of Minor Defense 2 ชิ้นไปให้ Syral Bladeleaf ใน Dolanaar" },
        description = { "286:243105578:1715402865", "ร้านสมุนไพรและเล่นแร่แปรธาตุของเราขายดีมาก แต่สามีข้าใช้เวลาผสมยามากเสียจนเราไม่มีเวลาให้กัน\n\nเจ้าช่วยเราได้ไหม?\n\nหากนำน้ำยาที่ผสมสำเร็จมาส่ง ข้าก็ยินดีแลกของด้วย ข้ามีสมุนไพรหายากที่อาจเป็นประโยชน์กับเจ้า" },
        progress = { "7:989913233:66981971 N 35:530613340:1414062740", "สวัสดี {name} มีน้ำยามาแลกหรือยัง?" },
        completion = { "59:162493999:1163764769 N 103:1191452991:302615303", "ผสมได้ดีทีเดียว เจ้าใส่ใจงานของตนมาก {name} และนั่นสำคัญสำหรับนักเล่นแร่แปรธาตุ\n\nนี่สมุนไพรของเจ้า เพิ่งเก็บสด ๆ ขอให้ใช้ได้อย่างคุ้มค่า" },
        required = { [2454] = { "24:1810844973:811017282", "ยาเพิ่มพละกำลังระดับต้น" }, [5997] = { "23:143712812:1255530836", "ยาเพิ่มพลังป้องกันระดับต้น" } },
        steps = { { "24:1810844973:811017282", "ยาเพิ่มพละกำลังระดับต้น" }, { "23:143712812:1255530836", "ยาเพิ่มพลังป้องกันระดับต้น" } },
    },
    [1618] = { -- Gearing Redridge
        title = { "16:1080328382:589462585", "เตรียมอุปกรณ์ให้ Redridge" },
        objective = { "111:2093770613:320204059", "Tormus Deepforge ต้องการให้เจ้านำ Runed Copper Belts 4 ชิ้น และ Heavy Copper Mauls 4 ชิ้นไปให้ Verner Osgood ใน Redridge" },
        description = { "298:190452234:79011091", "ไม่ได้มีแค่พวกเราคนแคระที่กำลังรบ พันธมิตรมนุษย์ก็มีงานล้นมือเหมือนกัน!\n\nRedridge ถูกออร์ค Blackrock โจมตีเป็นระยะ อุปกรณ์จึงขาดแคลนเสมอ หากเจ้าช่วยพวกเขา ข้ามั่นใจว่าช่างตีเหล็กประจำถิ่น Verner Osgood จะสอนเคล็ดลับให้เจ้าบ้าง" },
        progress = { "78:382245853:241599335", "หวังว่าเจ้าจะนำข่าวดีจาก Ironforge มา เพราะข้าจนปัญญาแล้ว!" },
        completion = { "11:1191658970:1224418299 N 324:2073820537:198305046", "ขอบใจ {name} นี่ช่วยข้าได้อย่างมาก ออร์ค Blackrock โจมตีจาก Stonewatch Keep ส่วนโนลล์ Redridge ก็ซุ่มอยู่แถวเชิงเขาทางเหนือ ข้าจึงต้องซ่อมเกราะและทำอาวุธใหม่ให้ทหารตลอด\n\nของที่เจ้านำมาจะให้ข้าได้พักสักครู่ มีเวลาพอสอนอะไรเจ้าได้บ้าง..." },
        required = { [2857] = { "17:146821789:2004011350", "เข็มขัดทองแดงจารึกรูน" }, [6214] = { "17:1525035441:606235255", "ค้อนศึกทองแดงหนัก" } },
        steps = { { "17:146821789:2004011350", "เข็มขัดทองแดงจารึกรูน" }, { "17:1525035441:606235255", "ค้อนศึกทองแดงหนัก" } },
    },
    [2751] = { -- Barbaric Battlements
        title = { "20:1509282861:1207286812", "แนวเกราะของนักรบเถื่อน" },
        objective = { "108:1384529236:906257777", "นำ Patterned Bronze Bracers สองชิ้น, Bronze Greatswords สองชิ้น และ Sharp Claws สองชิ้นไปให้ Orokk Omosh ใน Orgrimmar" },
        description = { "51:22382949:669795815 N 291:195498987:36024923 N 151:1951966769:1432840733", "คนตระกูล Omosh ยี่สิบรุ่นเคยถือค้อนนี้ {name} เราหลอมโลหะมาแสนตัน น่าเศร้าที่ทุกอย่างจบลงที่ Orokk ผู้ล้มเหลวแห่ง Omosh ไร้ญาติและไม่อาจมีลูกสืบสกุล\n\nข้าปล่อยให้สูตรลับ Omosh ตายไปพร้อมข้าไม่ได้! ต้องมีคนสานต่อมรดก จะเป็น Omosh หรือไม่ก็ตาม!\n\nพิสูจน์ให้ Orokk เห็นว่าเจ้าทำได้ {name} นำของต่อไปนี้มาให้ Orokk: ปลอกแขนสำริดลวดลายสองชิ้น ดาบใหญ่สำริดสองเล่ม และกรงเล็บแหลมสองชิ้น นำมาให้ Orokk แล้วเราจะเรียนต่อ" },
        progress = { "8:326169224:13825706 N 15:559511186:1264297841", "สำริด {name}! เอาสำริดมาอีก!!" },
        completion = { "114:137784782:1680610607 N 224:1606835048:671255058", "สายเลือดจะเลือนหาย แต่บางทีตำนาน Omosh อาจอยู่ต่อ!\n\nเจ้าพิสูจน์แล้วว่าเป็นช่างตีเหล็ก {name} สำหรับช่างตีเหล็ก รางวัลคือความพอใจที่เห็นอาวุธและเกราะของตนชุ่มเลือดศัตรู!\n\nขอให้เสื้อเกราะที่เจ้าสร้างแก่คนรุ่นต่อไปชุ่มโชกด้วยเลือดศัตรูของเจ้า!" },
        required = { [2868] = { "24:1232173144:251921374", "ปลอกรัดแขนสำริดมีลวดลาย" }, [7957] = { "17:1375046484:168713415", "ดาบใหญ่สำริด" }, [5635] = { "10:1679137503:673631999", "กรงเล็บคม" } },
        steps = { { "24:1232173144:251921374", "ปลอกรัดแขนสำริดมีลวดลาย" }, { "17:1375046484:168713415", "ดาบใหญ่สำริด" }, { "10:1679137503:673631999", "กรงเล็บคม" } },
    },
    [2752] = { -- On Iron Pauldrons
        title = { "17:287835240:1091214833", "ว่าด้วยเกราะไหล่เหล็ก" },
        objective = { "84:1472168127:1522516380", "นำ Bronze Battleaxes สี่ชิ้น และ Bronze Warhammers สี่ชิ้นไปให้ Orokk Omosh ใน Orgrimmar" },
        description = { "39:1190882656:140155508 N 248:1252201584:389701257", "Orokk เห็นความกระตือรือร้นในดวงตาเจ้า {name} เจ้าซึมซับภูมิปัญญา Omosh ดุจฟองน้ำ\n\nข้าจะสอนสามบทเรียน!\n\nกลับไปยังทั่ง ซึมซับไอร้อนจากเตา ทำขวานรบสำริดสี่เล่มกับค้อนสงครามสำริดสี่อันให้ Orokk เมื่อนั้นจึงจะได้เรียนเรื่องเกราะไหล่เหล็ก" },
        progress = { "25:172510240:966562423 R 1:46:46", "แสดงความทุ่มเทให้ข้าเห็น {race}" },
        completion = { "20:2134258526:213800414 N 32:1847787479:1561986105", "เจ้าทำให้ Orokk ภูมิใจ {name} อ่านเสีย เรียนรู้เรื่องเกราะไหล่เหล็ก!" },
        required = { [7958] = { "17:1037289082:1021859674", "ขวานศึกสำริด" }, [7956] = { "16:265261258:2016095580", "ค้อนศึกสำริด" } },
        steps = { { "17:1037289082:1021859674", "ขวานศึกสำริด" }, { "16:265261258:2016095580", "ค้อนศึกสำริด" } },
    },
    [2753] = { -- Trampled Under Foot
        title = { "19:1238003465:366559147", "ย่ำไว้ใต้เท้า" },
        objective = { "110:1439512337:1268590458", "นำ Green Iron Helms สี่ชิ้น, Green Iron Bracers สี่ชิ้น และ Green Iron Leggings สองชิ้นไปให้ Orokk Omosh ใน Orgrimmar" },
        description = { "40:694610173:1989453052 N 196:949494707:1100111174", "Orokk จะสอนอีกแค่สองบท {name} ข้ารู้ว่ากล้ามเนื้อเจ้าปวดล้า แต่จงทำต่อเพื่อ Omosh!\n\nนำหมวกเกราะเหล็กเขียวสี่ชิ้น ปลอกแขนเหล็กเขียวสี่ชิ้น และกางเกงเกราะเหล็กเขียวสองชิ้นมาให้ Orokk แล้วเจ้าจะได้เรียน ขณะที่ศัตรูต้องทนทุกข์!" },
        progress = { "57:48348413:1101916407", "กะโหลกพวกมันจะแตกใต้แรงกดจากรองเท้าบูตของเจ้า!" },
        completion = { "89:1965197023:520659767", "เจ้าทำให้ Orokk นึกถึงปู่ของเขา Chief Gorokk แห่ง Omosh! อ่านเสีย เรียนรู้เรื่องรองเท้าเหล็ก" },
        required = { [3836] = { "15:1878563542:2043659715", "หมวกเกราะเหล็กสีเขียว" }, [3835] = { "18:1431278195:1288411805", "ปลอกรัดแขนเหล็กสีเขียว" }, [3842] = { "19:1673542151:2019914896", "เกราะขาเหล็กสีเขียว" } },
        steps = { { "15:1878563542:2043659715", "หมวกเกราะเหล็กสีเขียว" }, { "18:1431278195:1288411805", "ปลอกรัดแขนเหล็กสีเขียว" }, { "19:1673542151:2019914896", "เกราะขาเหล็กสีเขียว" } },
    },
    [2754] = { -- Horns of Frenzy
        title = { "15:195208097:1297452648", "เขาแห่งความคลั่ง" },
        objective = { "117:83299357:724333798", "นำ Solid Iron Mauls สองชิ้น, Silvered Bronze Boots สองชิ้น และ Silvered Bronze Gauntlets สองชิ้นไปให้ Orokk Omosh ใน Orgrimmar" },
        description = { "36:1567785615:1953431257 N 187:1216279816:2012576015", "นี่คือบทสุดท้ายที่ Orokk จะสอนเจ้า {name} จงกลับไปยังทั่งและเตาศักดิ์สิทธิ์! นำตะบองเหล็กตันสองอัน รองเท้าสำริดชุบเงินสองชิ้น และถุงมือเกราะสำริดชุบเงินสองชิ้นมาให้ Orokk\n\nจงมองความกลัวในดวงตาพวกมันเมื่อเจ้าเข้าใกล้!" },
        progress = { "32:1145884522:959307565 N 1:33:33", "แสดงให้เหล็กเห็นว่าใครเป็นนาย {name}!" },
        completion = { "51:35630480:147668651 N 1:33:33", "น่าอัศจรรย์! เจ้าเรียนรู้วิถี Omosh แล้ว {name}!" },
        required = { [3482] = { "21:1311829581:1416283686", "รองเท้าบูตสำริดเคลือบเงิน" }, [3483] = { "25:170174014:1884864324", "ถุงมือเกราะสำริดเคลือบเงิน" }, [3851] = { "15:835291256:1057884753", "ค้อนเหล็กตัน" } },
        steps = { { "21:1311829581:1416283686", "รองเท้าบูตสำริดเคลือบเงิน" }, { "25:170174014:1884864324", "ถุงมือเกราะสำริดเคลือบเงิน" }, { "15:835291256:1057884753", "ค้อนเหล็กตัน" } },
    },
    [2755] = { -- Joys of Omosh
        title = { "13:154012481:1490360883", "ความยินดีแห่ง Omosh" },
        objective = { "39:1825441631:1487892854", "ชมและเรียนรู้ Omosh Dance of Joy" },
        description = { "21:1889239164:1999783538 N 137:641870484:660965581 N 59:925637103:835216265", "Orokk ไม่ได้ร้องไห้ {name} เขม่ามันเข้าตา\n\n<Orokk เช็ดน้ำตา>\n\nยังมีความลับตระกูล Omosh อีกอย่างที่ Orokk จะสอน ด้วยความช่วยเหลือของ {name} Orokk จะตายอย่างมีความสุข\n\nเรียนระบำแห่งความยินดีของ Omosh แล้วเจ้าจะได้เรียนหมัดเหล็ก!" },
        completion = { "100:457196467:2114117089 N 1:33:33", "<Orokk หอบ>\n\nนานมากแล้วที่ Orokk ไม่ได้เต้นระบำแห่งความยินดีของ Omosh เรียนรู้เดี๋ยวนี้ {name}!" },
        objectiveLabels = {
            event = { ["Omosh Dance of Joy Learned"] = "เรียนรู้ท่าเต้น Omosh Dance of Joy แล้ว" },
        },
    },
    [2756] = { -- The Old Ways
        title = { "12:1848255253:795009256", "วิถีเก่าแก่" },
        objective = { "89:1095932070:574400481", "นำ Steel Breastplates สี่ชิ้น และ Steel Plate Helms สี่ชิ้นไปให้ Aturk the Anvil ใน Orgrimmar" },
        description = { "153:1816697149:1273774830 R 300:763860867:929302667", "ในยุคแห่งตำนาน Aturk บดกะโหลกศัตรูแล้วป่นกระดูกเป็นผงละเอียดเพื่อใช้ทำเส้นใย วันเหล่านั้นผ่านไปนานแล้ว {race} Warchief เรียกร้องสันติระหว่างเผ่า ศัตรูเก่าจึงถูกเพียงจับตามองด้วยสายตาอ่อนล้า!\n\nข้ารู้ว่าเหลือเชื่อ แต่นั่นคือเจตจำนง Thrall\n\nเลิกคร่ำครวญได้แล้ว! เจ้ามาเรียน และจะได้เรียน! นำเสื้อเกราะเหล็กกล้าสี่ชิ้นกับหมวกเกราะเหล็กกล้าสี่ชิ้นมาให้ แล้วเจ้าจะได้ลิ้มรสสงคราม!" },
        progress = { "50:629831568:2032393366", "Aturk ก็เหมือนเวลา ไม่รอใคร! เร็วเข้า เจ้าคนโง่!" },
        completion = { "65:584086532:1024434736 N 175:768195992:1368501248", "ดูเหมือนเจ้าก็เป็นพวกเชื่องเชื่อฟัง Warchief อีกคนเท่านั้น {name} น่าผิดหวัง\n\nข้าโหยหาความตายอันรุ่งโรจน์ในสนามรบ แต่กลับติดอยู่ที่นี่ตามคำสั่ง Thrall เพื่อสอนเด็กอ่อนทำงานช่าง! ดูแล้วเรียนรู้ เจ้าหนู!" },
        required = { [7963] = { "17:164166510:1082412145", "เกราะอกเหล็กกล้า" }, [7922] = { "16:271231826:871068498", "หมวกเกราะแผ่นเหล็กกล้า" } },
        steps = { { "17:164166510:1082412145", "เกราะอกเหล็กกล้า" }, { "16:271231826:871068498", "หมวกเกราะแผ่นเหล็กกล้า" } },
    },
    [2757] = { -- Booty Bay or Bust!
        title = { "18:1035614843:1337916373", "Booty Bay หรือไม่ก็พัง!" },
        objective = { "32:2017718018:1032342411", "คุยกับ McGavan ใน Booty Bay" },
        description = { "266:315891839:372493975 N 126:837840435:1057551608", "ฟังนะ เจ้าหนู มัวอยู่แถวนี้เจ้าไม่ได้เรียนรู้อะไรหรอก\n\nข้ารู้จักคนที่รู้จักอีกคน เขาวนเวียนอยู่แถวโรงตีเหล็กใน Booty Bay ถ้าเจ้าแสดงเครื่องหมายนี้ให้ดู เขาจะบอกทุกเรื่องเกี่ยวกับมิธริล\n\nว่าอย่างไร? ปล่อยของเด็กเล่นไว้ให้พวกยังใส่ผ้าอ้อมเถอะ {name} ได้เวลาก้าวต่อไปแล้ว\n\nถ้าสนใจ เขาชื่อ McGavan แสดงเครื่องประดับนี้ แล้วเขาจะเห็นความมุ่งมั่นของเจ้า" },
        progress = { "59:157668074:1970072757", "คนแบบเจ้าหายากนะ สหาย ขอดูเครื่องหมายนั่นหน่อย" },
        completion = { "69:1987124957:1993846692", "ให้ตายสิ ขนหลังของ Blackhoof เป็นพยาน ในที่สุดก็มีคนคู่ควรกับ Mithril Order!" },
    },
    [2758] = { -- The Origins of Smithing
        title = { "23:498304359:1886023060", "ต้นกำเนิดงานตีเหล็ก" },
        objective = { "63:1772031383:1986489882", "นำ Golden Scale Bracers หกชิ้นไปให้ Hank the Hammer ใน Stormwind" },
        description = { "445:1570224849:1242501735 N 1:46:46", "ตอนข้าอายุราวเจ้า คนแคระชื่อ Galvan รับข้าไว้ในความดูแลและฝึกวิถีช่างตีเกราะให้ ก่อนเขาไป Booty Bay เขาให้ข้าสัญญาว่าจะฝึกทุกคนที่มีความปรารถนาและแน่วแน่จะก้าวหน้าในงานตีเหล็ก หลายปีผ่านไป ข้าจึงยังอยู่ที่นี่\n\nตอนนี้ถึงเวลาให้เจ้าเรียนรู้บ้าง ทำปลอกแขนเกล็ดทองหกชิ้นมาให้ แล้วเจ้าจะได้เรียนว่าการตีเหล็กถือกำเนิดอย่างไร {name}" },
        progress = { "37:214452662:757828609", "เจ้าจะเป็นศิษย์ผู้สืบทอดคนต่อไปของ Galvan ได้หรือไม่?" },
        completion = { "11:1776810664:1873330125 N 260:122442994:925981608", "ดีมาก {name}! ฟังแล้วเรียนรู้\n\nงานตีเหล็กไม่ได้มาจากตรงนี้! <Hank ชี้ไปที่ค้อนของตน>\n\nงานตีเหล็กไม่ได้มาจากตรงนี้! <Hank ชี้ไปที่ทั่ง>\n\nงานตีเหล็กมาจากตรงนี้เท่านั้น! <Hank ชี้ไปที่หัวใจตน>\n\nตอนนี้เจ้ารู้ต้นกำเนิดงานตีเหล็กแล้ว" },
        required = { [6040] = { "20:1084065780:1386588320", "ปลอกรัดแขนเกล็ดทอง" } },
        steps = { { "20:1084065780:1386588320", "ปลอกรัดแขนเกล็ดทอง" } },
    },
    [2759] = { -- In Search of Galvan
        title = { "19:1076046317:828477067", "ตามหา Galvan" },
        objective = { "32:2017718018:1032342411", "คุยกับ McGavan ใน Booty Bay" },
        description = { "289:1150167493:311921262 N 1:33:33", "แม้ Galvan จะจาก Booty Bay ไปหลายปีแล้ว สมาชิกของคณะยังอยู่ในเมือง หวังว่าสักวันจะพบคนอื่นที่คู่ควรกับคำสอนของเขา\n\nนำเครื่องหมายนี้ไปแสดงให้ McGavan ใน Booty Bay\n\nหากเจ้าไปถึงจริง ๆ เขาจะรู้ว่าเจ้าคู่ควร ข้าเชื่อมั่น {name}!" },
        progress = { "59:157668074:1970072757", "คนแบบเจ้าหายากนะ สหาย ขอดูเครื่องหมายนั่นหน่อย" },
        completion = { "69:1987124957:1993846692", "ให้ตายสิ ขนหลังของ Blackhoof เป็นพยาน ในที่สุดก็มีคนคู่ควรกับ Mithril Order!" },
        required = { [8663] = { "16:1999898711:1795544912", "ตรามิธริล" } },
        objectiveLabels = {
            item = { ["Mithril Insignia"] = "ตรามิธริล" },
        },
    },
    [2760] = { -- The Mithril Order
        title = { "17:1018324848:861734498", "คณะ Mithril Order" },
        objective = { "52:1225935941:1172609301", "คุยกับ Galvan the Ancient ใน Stranglethorn Vale" },
        description = { "49:1501128334:1085562480 N 329:906089491:1675630631", "คนที่เรารับเข้ามาส่วนใหญ่ไปไม่ถึง Booty Bay หรอก {name} แค่แสงแวววาวของเครื่องหมายก็กระตุ้นความโลภอยากได้สมบัติ แม้ในช่างตีเหล็กที่หนักแน่นที่สุด พวกโง่เอ๋ย เครื่องหมายนี้เทียบไม่ได้เลยกับสมบัติมากมายที่เจ้าจะได้เห็น!\n\nหา Galvan the Ancient แล้วแสดงเข็มกลัดนี้ให้เขาดู บ้านเขาอยู่ไกลขึ้นไปทางเหนือ ระหว่าง Zul Gurub กับเนินยักษ์ Mosh'Ogg" },
        progress = { "45:1748462292:372450790", "สวัสดี! เข้ามาใกล้ ๆ แสดงให้ Galvan ดูว่าเจ้ามีอะไร" },
        completion = { "106:473820725:460531777", "อา หลายปีแล้วที่ไม่มีใครคู่ควรกับการเริ่มฝึกแห่ง Mithril Order เราจะเริ่มกันเดี๋ยวนี้!" },
    },
    [2761] = { -- Smelt On, Smelt Off
        title = { "19:1992260306:850048651", "หลอมเข้า หลอมออก" },
        objective = { "84:425194710:1637624761", "นำ Mithril Bars สี่สิบชิ้น และ Iron Bars สี่สิบชิ้นไปให้ Galvan the Ancient ใน Stranglethorn" },
        description = { "260:845887394:809809629 N 126:81369340:1960009608", "ช่างตีเหล็กหลายคนเชื่อว่าการทำเหมืองกับตีเหล็กเป็นงานแยกขาดจากกัน แต่จะมีการตีเหล็กโดยไม่มีเหมืองได้หรือ? ฮ่าฮ่า เป็นไปไม่ได้! ช่างตีเหล็กที่ชำนาญต้องเป็นนักขุดแร่ที่ชำนาญด้วย\n\nแสดงให้ Galvan เห็นว่าเจ้าทำได้ {name} นำแท่งเหล็กสี่สิบกับแท่งมิธริลสี่สิบมาให้ แล้ว Galvan จะสอนวิธีทำกางเกงมิธริลประดับลาย!" },
        progress = { "58:606664115:379633053", "หลังขุดแร่มาขนาดนั้น กล้ามเนื้อเจ้าทั้งปูดโปนและปวดล้า!" },
        completion = { "31:1255352098:675512162 N 109:1020814187:407195971", "จรรยาบรรณการทำงานของเจ้าไร้ที่ติ {name}! เจ้ากำลังเริ่มเข้าใจวิถีแร่วิทยาของ Galvan รับนี่ไป แล้วเรียนรู้ให้มากที่สุด" },
        required = { [3575] = { "8:1010117764:989104521", "แท่งเหล็ก" }, [3860] = { "11:1665667963:654296337", "แท่งมิธริล" } },
        objectiveLabels = {
            item = { ["Iron Bar"] = "แท่งเหล็ก", ["Mithril Bar"] = "แท่งมิธริล" },
        },
    },
    [2762] = { -- The Great Silver Deceiver
        title = { "25:321049809:1023771034", "เจ้าเงินจอมลวง" },
        objective = { "89:2075122898:1568740556", "นำ Mithril Bars สี่สิบชิ้น และ Truesilver Bars ห้าชิ้นไปให้ Galvan the Ancient ใน Stranglethorn" },
        description = { "298:1615242131:1953814127 N 184:1681455511:1577059679", "ว่ากันว่า Truesilver แข็งแรงและทนทานกว่ามิธริล Galvan ไม่เถียงข้อประเมินนั้น แต่แม้ชื่อจะสื่อว่าแท้ Truesilver ก็ไม่แท้จริง! มิธริลเป็นแร่ที่สูงส่งกว่ามาก! ฮ่า! อย่างไรก็เถอะ บทเรียนนี้เจ้าต้องหาเจ้าเงินจอมลวง {name}\n\nนำแท่งมิธริลสี่สิบกับแท่ง Truesilver ห้ามาให้ แลกกับความลับการทำถุงมือมิธริลประดับลาย และที่สำคัญกว่า เจ้าจะได้รู้ว่า Truesilver เป็นจอมโกหก!" },
        progress = { "58:606664115:379633053", "หลังขุดแร่มาขนาดนั้น กล้ามเนื้อเจ้าทั้งปูดโปนและปวดล้า!" },
        completion = { "36:1197145102:848538973 N 168:1200369896:1863668620", "นางช่างเป็นนายหญิงที่โหดร้าย ว่าไหม {name}? แน่นอน ข้าพูดถึง Truesilver Galvan ใช้เวลากว่าสิบปีในเทือกเขา Alterac เพื่อเรียนบทนี้ รับนี่ไปแล้วเรียนรู้ให้มากที่สุด!" },
        required = { [3860] = { "11:1665667963:654296337", "แท่งมิธริล" }, [6037] = { "14:999689902:1924659795", "แท่งเงินทรูซิลเวอร์" } },
        objectiveLabels = {
            item = { ["Mithril Bar"] = "แท่งมิธริล", ["Truesilver Bar"] = "แท่งเงินทรูซิลเวอร์" },
        },
    },
    [2763] = { -- The Art of the Imbue
        title = { "20:177200844:1906851713", "ศิลปะแห่งการประทับพลัง" },
        objective = { "82:1616671422:71843104", "นำ Mithril Bars สี่สิบชิ้น และ Citrines สี่ชิ้นไปให้ Galvan the Ancient ใน Stranglethorn" },
        description = { "70:423744611:1240840953 N 334:1035560956:321401935", "การหาอัญมณีมีค่ามีความสำคัญสูงสุดต่องานเรา {name} มีอัญมณีไม่กี่ชนิดมีค่าเหนือซิทริน การมีซิทรินช่วยขยายคุณสมบัติเวทมนตร์ที่เราประทับในชิ้นงานอย่างมาก\n\nบทเรียนนี้ เราจะเสริมแท่งมิธริลสี่สิบด้วยซิทรินสี่ชิ้น ผลคือความเข้าใจอัญมณีเวทมนตร์ดีขึ้น และความรู้ในการสร้างเกราะไหล่มิธริลประดับลาย" },
        progress = { "58:606664115:379633053", "หลังขุดแร่มาขนาดนั้น กล้ามเนื้อเจ้าทั้งปูดโปนและปวดล้า!" },
        completion = { "58:377970132:1669966006 N 93:1630652145:213510034", "แทบละสายตาจากความงดงามของมันไม่ได้เลย {name} ใช่ ซิทรินเป็นอัญมณีอันรุ่งโรจน์\n\nตั้งใจแล้วเรียนรู้ว่าการค้นพบเช่นนี้สอนอะไรเราได้บ้าง!" },
        required = { [3860] = { "11:1665667963:654296337", "แท่งมิธริล" }, [3864] = { "7:621808321:2009653988", "ซิทริน" } },
        objectiveLabels = {
            item = { ["Mithril Bar"] = "แท่งมิธริล", ["Citrine"] = "ซิทริน" },
        },
    },
    [2764] = { -- Galvan's Finest Pupil
        title = { "21:73343373:1371818896", "ศิษย์ยอดฝีมือของ Galvan" },
        objective = { "44:1830213697:940357998", "คุยกับ Trenton Lighthammer ใน Gadgetzan" },
        description = { "277:399679947:1805740764", "หากเจ้าพร้อมจบการฝึกกับ Galvan ก็ควรเดินทางไป Gadgetzan\n\nที่นั่นเจ้าจะพบศิษย์ยอดฝีมือของข้า Trenton Lighthammer เขามีเรื่องมิธริลประดับลายให้สอนเจ้าอีกมาก หากยังไม่พร้อมก็อยู่ที่นี่แล้วเรียนต่อ!\n\nอ้อ แน่นอนว่า Gadgetzan อยู่ใน Tanaris!" },
        completion = { "105:1512615140:1498462695", "Galvan the Ancient ส่งเจ้ามาหรือ??\n\n<Trenton โค้งคำนับ>\n\nเป็นเกียรติอย่างยิ่งที่ได้พบศิษย์อีกคนของอาจารย์!" },
    },
    [2765] = { -- Expert Blacksmith!
        title = { "18:1722858867:430109679", "ช่างตีเหล็กผู้ชำนาญ!" },
        objective = { "42:1237460851:1338602620", "รับรางวัลจาก Galvan the Ancient!" },
        description = { "323:644765281:1871763562 N 19:1118500087:1217790604", "เมื่อเจ้ามาหาข้าครั้งแรก ข้ารู้ว่าเจ้าจะกลายเป็นหนึ่งในศิษย์ยอดฝีมือ! เจ้ายกเครื่องประดับที่มีพลังให้ McGavan โดยไม่ลังเล เพียงเพื่อมาพบข้า ศรัทธาอย่างไร้ข้อกังขาและความทุ่มเทต่องานช่างเช่นนั้นสมควรได้รางวัล\n\nเจ้าชำนาญงานตีเหล็กแล้ว {name} จงรับผลตอบแทน!" },
        completion = { "131:634197533:199168262 N 1:46:46", "เหมาะสมแล้วที่เจ้าจะได้เครื่องประดับทรงพลังกว่าชิ้นที่สละมาเพื่อถึงที่นี่มาก ขอให้เจ้าใช้มันอย่างผาสุก {name}" },
        progress = { "18:1155279891:1295350420", "มารับรางวัลของเจ้าได้เลย!" },
    },
    [2771] = { -- A Good Head On Your Shoulders
        title = { "29:604089596:1763570310", "หัวดีบนบ่า" },
        objective = { "79:1199226663:354162222", "นำ Mithril Coifs สองชิ้น และ Ornate Mithril Shoulder หนึ่งชิ้นไปให้ Trenton Lighthammer" },
        description = { "201:774662231:1306018548 N 151:1549721123:460194148", "ดูเหมือนอาจารย์วางแผนไว้ตั้งแต่ต้น ข้าไม่ได้เรียนทำสิ่งที่เจ้าเรียน และเจ้าก็ไม่ได้เรียนสิ่งที่ข้าเรียน\n\nอาจารย์ช่างมีปัญญา {name} เราจะสอนกันและกัน!\n\nแสดงวิธีทำหมวกโซ่มิธริลกับเกราะไหล่มิธริลประดับลาย แล้วข้าจะแสดงวิธีทำหมวกเกราะมิธริลประดับลายให้" },
        progress = { "46:1672846796:1271241271 N 1:63:63", "ทำชิ้นงานครบแล้วหรือยัง {name}?" },
        completion = { "68:1218913731:496513886 N 1:33:33", "ยอดเยี่ยม! ข้าว่านี่เป็นการแลกเปลี่ยนที่ยุติธรรม ดูแล้วเรียนรู้ {name}!" },
        required = { [7931] = { "12:745317806:1963445884", "หมวกคลุมมิธริล" }, [7928] = { "23:1164010824:1752559436", "เกราะไหล่มิธริลประดับลาย", variants = { { "24:650554950:1952021557", "เกราะไหล่มิธริลประดับลาย" } } } },
        objectiveLabels = {
            item = { ["Mithril Coif"] = "หมวกคลุมมิธริล", ["Ornate Mithril Shoulder"] = "เกราะไหล่มิธริลประดับลาย", ["Ornate Mithril Shoulders"] = "เกราะไหล่มิธริลประดับลาย" },
        },
    },
    [2772] = { -- The World At Your Feet
        title = { "22:148809680:119688224", "โลกอยู่ใต้เท้าเจ้า" },
        objective = { "82:852412974:205816821", "นำ Heavy Mithril Boots สองชิ้น และ Ornate Mithril Pants หนึ่งชิ้นไปให้ Trenton Lighthammer" },
        description = { "493:1333877953:1767836191", "ในการแข่งขันตีเหล็กชิงแชมป์ All-Valley ปีที่แล้ว ผู้ชมทุกคนเห็นข้าถูกเจ้าขี้ขลาดจาก Venture Co. Foundry กวาดขาจนล้ม แต่สิ่งที่พวกเขาไม่รู้คือเหตุผลที่ข้าสู้ต่อจนชนะการแข่งขันได้ ใช่แล้ว รองเท้ามิธริลประดับลาย!\n\nแต่สำหรับปีนี้ ข้าต้องเรียนทำกางเกงมิธริลประดับลาย เพราะมีเครื่องจักร Shredder ของ Venture Co. ลงแข่งด้วย! สอนวิถีกางเกงให้ข้า แล้วเรียนวิถีรองเท้าบูต!" },
        progress = { "46:1672846796:1271241271 N 1:63:63", "ทำชิ้นงานครบแล้วหรือยัง {name}?" },
        completion = { "32:491044322:1826713167 N 62:373461450:104915984", "โลกจะอยู่ใต้เท้าเจ้า {name}! ปล่อยพวกมันเล็งขามาได้เลย เพราะบัดนี้ไม่มีใครกวาดขาเจ้าให้ล้มได้อีก!" },
        required = { [7933] = { "19:1306663887:1947602717", "รองเท้าบูตมิธริลหนัก" }, [7926] = { "20:294248688:1131330382", "กางเกงมิธริลประดับลาย" } },
        objectiveLabels = {
            item = { ["Heavy Mithril Boots"] = "รองเท้าบูตมิธริลหนัก", ["Ornate Mithril Pants"] = "กางเกงมิธริลประดับลาย" },
        },
    },
    [2773] = { -- The Mithril Kid
        title = { "15:518664244:1404147619", "เจ้าหนูมิธริล" },
        objective = { "90:1306389324:1080519302", "นำ Heavy Mithril Breastplates สองชิ้น และ Ornate Mithril Gloves หนึ่งชิ้นไปให้ Trenton Lighthammer" },
        description = { "314:2702090:1275466644 N 128:1696234870:1163732316", "แถวนี้ข้าเป็นที่รู้จักในชื่อ Mithril Kid ข้าจัดหามิธริลประดับลายให้นักผจญภัยจากทั่วโลก\n\n<Trenton กระซิบ>\n\nพวกเขาไม่รู้เลยว่าข้าไม่รู้เทคนิคทำถุงมือมิธริลประดับลาย ชู่ว์! ให้เป็นความลับระหว่างเรา\n\nสอนเทคนิคทำถุงมือมิธริลประดับลายให้ข้า {name} แล้วข้าจะสอนผลงานสุดยอดจากการฝึกกับ Galvan นั่นคือเสื้อเกราะมิธริลประดับลาย" },
        progress = { "46:1672846796:1271241271 N 1:63:63", "ทำชิ้นงานครบแล้วหรือยัง {name}?" },
        completion = { "43:1358769106:1807932626 N 93:1004261619:12639770", "ขอบใจสำหรับทุกอย่างที่เจ้าสอน {name} อีกไม่นานชิ้นเอกที่เป็นหัวใจแห่งชุดมิธริลประดับลายจะเป็นของเจ้า\n\nดูนี่!" },
        required = { [7930] = { "25:1671221731:1545987464", "เกราะอกมิธริลหนัก" }, [7927] = { "21:1851242296:1799146876", "ถุงมือมิธริลประดับลาย" } },
        objectiveLabels = {
            item = { ["Heavy Mithril Breastplate"] = "เกราะอกมิธริลหนัก", ["Ornate Mithril Gloves"] = "ถุงมือมิธริลประดับลาย" },
        },
    },
    [3321] = { -- Did You Lose This?
        title = { "18:555137781:743915608", "เจ้าทำสิ่งนี้หายหรือ?" },
        objective = { "36:1609468220:763240047", "รอให้ Trenton ทำงานเสร็จ" },
        description = { "34:1934669297:828487879 N 365:373333000:451614495", "เจ้าทำให้คณะมากมาย {name} ความทุ่มเทที่ต้องใช้เพื่อมาถึงขั้นนี้คงทำให้คนธรรมดาถอดใจ ข้ากับ Galvan ไม่สงสัยเลยว่าเจ้าเป็นพวกเรา\n\nนั่นจึงเป็นเหตุให้ข้าคิดว่าเจ้าคู่ควรกับรางวัลเล็กน้อย ไม่มีอะไรมากหรอก แค่เครื่องประดับ เจ้าคงคุ้นคุณสมบัติมัน เพราะข้าเชื่อว่านี่คือสิ่งที่นำเจ้ามาหาเราตั้งแต่แรก" },
        progress = { "66:15951043:951400828", "วันนี้เราจะปิดท้ายการเฉลิมฉลองความมุ่งมั่นที่เจ้ามีต่อคณะ" },
        completion = { "24:238071908:385442977 N 34:505655026:633225610", "จงยืนขึ้นให้เราเชิดชู {name} ช่างตีเหล็กแห่ง Mithril Order" },
    },
    [3379] = { -- Shadoweaver
        title = { "11:1155242807:403259679", "ผู้ทอเงา" },
        objective = { "222:684737678:522090827", "ฆ่ากลุ่ม Shadow Silk Poachers ที่เดินอยู่ใน Searing Gorge Nilith มีเหตุให้เชื่อว่ามีห้าคนที่ต้องกำจัด เสร็จแล้วกลับไปหา Nilith ใน Searing Gorge" },
        description = { "479:1330116020:1961840239", "แมงมุมใน Searing Gorge เป็นแหล่ง Shadow Silk อันประเมินค่ามิได้ อย่างที่เจ้ารู้ ช่างฝีมือในวิชาชีพเราต้องการใยเงานี้อย่างมาก\n\nช่วงหลัง กลุ่มนักลักลอบล่าเข้ามารุกล้ำดินแดน ฆ่าแมงมุมจำนวนมากอย่างไม่ใส่ใจผลระยะยาว งานแรกที่ข้าขอจึงง่ายนัก ตามหาพวกมัน... แล้วจบชีวิตเสีย\n\nเริ่มหาทางเหนือ\n\nหากต้องการความช่วยเหลือ ให้คุยกับ Raze" },
        progress = { "29:1435303769:667467919", "เจ้ามีข้อมูลอะไร?" },
        completion = { "16:1549935302:71513149 N 74:1433082339:431371250", "ทำได้ยอดเยี่ยม {name}\n\nข้ามั่นใจว่านี่เป็นชิ้นงาน Shadoweave ที่เจ้ายังไม่เคยเห็น" },
    },
    [3385] = { -- The Undermarket
        title = { "15:1475398488:1531994234", "ตลาดใต้ดิน Undermarket" },
        objective = { "116:1444322659:285638730", "สังหาร Trade Master Kovic และสมุน Clunk เก็บ Trader's Satchel จากศพเขาแล้วนำกลับไปให้ Nilith" },
        description = { "147:1902659599:1821918655 N 351:1660431761:523771130", "พวกมันเรียกตนว่า Undermarket เป็นพ่อค้าอำมหิตที่จะขาย ขนส่ง แลกเปลี่ยน และทำแทบทุกอย่างหากได้ราคาดี\n\nยิ่งกว่านั้น {name} พวกมันตั้งฐานปฏิบัติการใน Searing Gorge แล้ว Trade Master Kovic เป็นหัวหน้าและใกล้ชิดกับคนแคระ Dark Iron ในแถบนี้\n\nเราต้องโจมตีให้หนักเพื่อส่งสารถึงผู้นำ สังหาร Trade Master Kovic กับสมุน Clunk เสร็จแล้วนำย่ามพ่อค้าของเขากลับมา\n\nไป Cauldron!" },
        progress = { "29:279459100:235963879", "Trade Master ยังมีชีวิตอยู่หรือ?" },
        completion = { "231:1988652556:284900399", "เจ้าโจมตี Undermarket อย่างเด็ดขาด ผู้นำพวกมันจะคิดให้ดีก่อนส่งพรรคพวกเข้ามาในหุบเขาอีก\n\nอ้อ ข้าไม่พบอะไรมีประโยชน์ในย่ามพ่อค้า เจ้าจะเก็บสิ่งที่พบข้างในไว้ก็ได้" },
        required = { [10467] = { "16:1641503337:117218203", "ย่ามของพ่อค้า" } },
        objectiveLabels = {
            item = { ["Trader's Satchel"] = "ย่ามของพ่อค้า" },
        },
    },
    [3402] = { -- The Undermarket
        title = { "15:1475398488:1531994234", "ตลาดใต้ดิน Undermarket" },
        objective = { "34:579320208:1264363642", "คุยกับ Vizzklick ใน Gadgetzan" },
        description = { "184:1946570570:1122541354", "ข้าอยากให้เจ้านำข่าวการปราบ Kovic ไปบอก Vizzklick ใน Gadgetzan ด้วยตนเอง เขาจะดีใจที่รู้ว่า Kovic ตายแล้วจนข้ามั่นใจว่าจะให้รางวัลงามแก่เจ้า" },
        completion = { "39:107829216:196094312 N 216:410050945:277302003", "Kovic ถูกฆ่าแล้วหรือ??! วันนี้ช่างรุ่งโรจน์ {name}! เจ้าสารเลวนั่นลอบค้าขายใต้ดินและตัดราคาพ่อค้าซื่อสัตย์ที่ทำงานหนักทั่วโลกมาหลายปี\n\nเจ้าคู่ควรกับรางวัลชั้นดีสำหรับความสำเร็จนี้ และเจ้าจะได้รับแน่นอน!" },
    },
    [3526] = { -- Goblin Engineering
        title = { "18:1210586148:2085550562", "วิศวกรรมสายก็อบลิน" },
        objective = { "131:751450707:371837181", "หากต้องการเรียนรู้วิศวกรรมสาย Goblin ให้นำ Manual of Engineering Disciplines ไปให้ Nixx Sprocketspring ใน Gadgetzan" },
        description = { "231:62532453:1101934820 N 256:1848077826:1536553717", "วิศวกรรมระดับเชี่ยวชาญแยกเป็นสองสาย คือโนมกับก็อบลิน แน่นอนว่าสายก็อบลินเป็นตัวเลือกของวิศวกรอัจฉริยะทุกคน เรียนรู้การครองโลกด้วยการใช้ระเบิดกำลังสูงและอุปกรณ์มหัศจรรย์อย่างเหมาะสม!\n\n{name} อ่านคู่มือนี้ หากอยากเรียนสายก็อบลิน ให้นำไปให้ Nixx Sprocketspring ใน Gadgetzan จำไว้ สมาชิกภาพเป็นการถาวรและทำให้เข้าร่วมอีกสายไม่ได้ จงแน่ใจก่อนทำงานของเขาให้สำเร็จว่านี่คือสิ่งที่เจ้าต้องการ" },
        progress = { "158:2139350791:162920759", "ข้าได้กลิ่นสมาชิกใหม่เหมือนผงระเบิดชั้นดี ดมได้ไกลเป็นไมล์ เจ้ามาเรียนความเชี่ยวชาญด้านการระเบิดหรือ?" },
        completion = { "5:1151914341:80614338 N 309:1701065824:605832551 N 32:1225623224:557922036", "เอาละ {name} เจ้าคิดถูกแล้วที่มาเรียนกับข้า! คนซื่อบื้อที่ไหนก็เชี่ยวชาญวิศวกรรมพื้นฐานได้ พวกโนมกับ Gnomeregan บ้านที่เปื้อนรังสีของพวกเขาเป็นหลักฐาน แต่การเชี่ยวชาญวิศวกรรมสายก็อบลินต้องใช้สมองแข็งแกร่งและมือที่นิ่ง เน้นว่านิ่ง!\n\nเงี่ยหูฟังให้ดี {name} แล้วเจ้าอาจได้เรียนรู้บ้าง" },
        required = { [10789] = { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
        steps = { { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
    },
    [3629] = { -- Goblin Engineering
        title = { "18:1210586148:2085550562", "วิศวกรรมสายก็อบลิน" },
        objective = { "131:751450707:371837181", "หากต้องการเรียนรู้วิศวกรรมสาย Goblin ให้นำ Manual of Engineering Disciplines ไปให้ Nixx Sprocketspring ใน Gadgetzan" },
        description = { "240:894764684:1080651359 N 255:1629061532:1479876220", "วิศวกรรมระดับเชี่ยวชาญแยกเป็นสองสาย คือโนมกับก็อบลิน ข้าพูดถึงสายก็อบลินเพียงเพราะเป็นครูที่ยุติธรรม พวกนั้นชอบทำของที่ระเบิดได้ และแทบไม่สนว่าอะไรขวางอยู่ แม้แต่ตัวเอง\n\n{name} อ่านคู่มือนี้ หากอยากเรียนวิธีระเบิดตัวเอง ให้นำไปให้ Nixx Sprocketspring ใน Gadgetzan จำไว้ สมาชิกภาพเป็นการถาวรและทำให้เข้าร่วมอีกสายไม่ได้ จงแน่ใจก่อนทำงานของเขาให้สำเร็จว่านี่คือสิ่งที่เจ้าต้องการ" },
        progress = { "158:2139350791:162920759", "ข้าได้กลิ่นสมาชิกใหม่เหมือนผงระเบิดชั้นดี ดมได้ไกลเป็นไมล์ เจ้ามาเรียนความเชี่ยวชาญด้านการระเบิดหรือ?" },
        completion = { "5:1151914341:80614338 N 309:1701065824:605832551 N 32:1225623224:557922036", "เอาละ {name} เจ้าคิดถูกแล้วที่มาเรียนกับข้า! คนซื่อบื้อที่ไหนก็เชี่ยวชาญวิศวกรรมพื้นฐานได้ พวกโนมกับ Gnomeregan บ้านที่เปื้อนรังสีของพวกเขาเป็นหลักฐาน แต่การเชี่ยวชาญวิศวกรรมสายก็อบลินต้องใช้สมองแข็งแกร่งและมือที่นิ่ง เน้นว่านิ่ง!\n\nเงี่ยหูฟังให้ดี {name} แล้วเจ้าอาจได้เรียนรู้บ้าง" },
        required = { [10789] = { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
        steps = { { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
    },
    [3630] = { -- Gnome Engineering
        title = { "17:137600338:1348180482", "วิศวกรรมสายโนม" },
        objective = { "131:1833354953:702994730", "หากต้องการเรียนรู้วิศวกรรมสาย Gnome ให้นำ Manual of Engineering Disciplines ไปให้ Tinkmaster Overspark ใน Ironforge" },
        description = { "224:931386294:627809508 N 258:757249578:986504245", "วิศวกรรมระดับเชี่ยวชาญแยกเป็นสองสาย คือโนมกับก็อบลิน สายโนมเหนือกว่าอีกสายอย่างชัดเจน! เป็นเรื่องของการสร้างกลไกและอุปกรณ์มหัศจรรย์ที่ทำให้ชีวิตดีขึ้น!\n\n{name} อ่านคู่มือนี้ หากอยากเรียนสายโนมเพิ่มเติม ให้นำคู่มือไปให้ Tinkmaster Overspark ใน Ironforge จำไว้ สมาชิกภาพเป็นการถาวรและทำให้เข้าร่วมอีกสายไม่ได้ จงแน่ใจให้ดีก่อนทำงานของเขาสำเร็จ!" },
        progress = { "177:187474945:654092465", "ใช่ ใช่ วันนี้มีเรื่องใดให้ข้าจัดการ? เห็นได้ชัดว่าข้ามีเวลาทำ เพราะข้าเพียงยืนอยู่ที่นี่ ขณะนครที่รักจมในเมฆรังสีมรณะ" },
        completion = { "256:369128849:1460459063", "อา วิศวกรรุ่นเยาว์สนใจสายวิศวกรรมหนึ่งเดียวที่แท้จริง! ขอโทษที่ข้าเล่นใหญ่ เพื่อน แม้สถานการณ์เรายังย่ำแย่ แต่วันที่ได้เห็นวิศวกรอีกคนตอบรับเสียงเรียกของวิศวกรรมแท้จริงก็เป็นวันดีเสมอ!" },
        required = { [10789] = { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
        steps = { { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
    },
    [3632] = { -- Gnome Engineering
        title = { "17:137600338:1348180482", "วิศวกรรมสายโนม" },
        objective = { "131:1833354953:702994730", "หากต้องการเรียนรู้วิศวกรรมสาย Gnome ให้นำ Manual of Engineering Disciplines ไปให้ Tinkmaster Overspark ใน Ironforge" },
        description = { "224:931386294:627809508 N 263:1502930550:913230770", "วิศวกรรมระดับเชี่ยวชาญแยกเป็นสองสาย คือโนมกับก็อบลิน สายโนมเหนือกว่าอีกสายอย่างชัดเจน! เป็นเรื่องของการสร้างกลไกและอุปกรณ์มหัศจรรย์ที่ทำให้ชีวิตดีขึ้น!\n\n{name} อ่านคู่มือนี้ หากอยากเรียนสายโนมเพิ่มเติม ให้นำคู่มือไปให้ Tinkmaster Overspark ที่นี่ใน Ironforge จำไว้ สมาชิกภาพเป็นการถาวรและทำให้เข้าร่วมอีกสายไม่ได้ จงแน่ใจให้ดีก่อนทำงานของเขาสำเร็จ!" },
        progress = { "177:187474945:654092465", "ใช่ ใช่ วันนี้มีเรื่องใดให้ข้าจัดการ? เห็นได้ชัดว่าข้ามีเวลาทำ เพราะข้าเพียงยืนอยู่ที่นี่ ขณะนครที่รักจมในเมฆรังสีมรณะ" },
        completion = { "256:369128849:1460459063", "อา วิศวกรรุ่นเยาว์สนใจสายวิศวกรรมหนึ่งเดียวที่แท้จริง! ขอโทษที่ข้าเล่นใหญ่ เพื่อน แม้สถานการณ์เรายังย่ำแย่ แต่วันที่ได้เห็นวิศวกรอีกคนตอบรับเสียงเรียกของวิศวกรรมแท้จริงก็เป็นวันดีเสมอ!" },
        required = { [10789] = { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
        steps = { { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
    },
    [3633] = { -- Goblin Engineering
        title = { "18:1210586148:2085550562", "วิศวกรรมสายก็อบลิน" },
        objective = { "131:751450707:371837181", "หากต้องการเรียนรู้วิศวกรรมสาย Goblin ให้นำ Manual of Engineering Disciplines ไปให้ Nixx Sprocketspring ใน Gadgetzan" },
        description = { "231:62532453:1101934820 N 256:1848077826:1536553717", "วิศวกรรมระดับเชี่ยวชาญแยกเป็นสองสาย คือโนมกับก็อบลิน แน่นอนว่าสายก็อบลินเป็นตัวเลือกของวิศวกรอัจฉริยะทุกคน เรียนรู้การครองโลกด้วยการใช้ระเบิดกำลังสูงและอุปกรณ์มหัศจรรย์อย่างเหมาะสม!\n\n{name} อ่านคู่มือนี้ หากอยากเรียนสายก็อบลิน ให้นำไปให้ Nixx Sprocketspring ใน Gadgetzan จำไว้ สมาชิกภาพเป็นการถาวรและทำให้เข้าร่วมอีกสายไม่ได้ จงแน่ใจก่อนทำงานของเขาให้สำเร็จว่านี่คือสิ่งที่เจ้าต้องการ" },
        progress = { "158:2139350791:162920759", "ข้าได้กลิ่นสมาชิกใหม่เหมือนผงระเบิดชั้นดี ดมได้ไกลเป็นไมล์ เจ้ามาเรียนความเชี่ยวชาญด้านการระเบิดหรือ?" },
        completion = { "5:1151914341:80614338 N 309:1701065824:605832551 N 32:1225623224:557922036", "เอาละ {name} เจ้าคิดถูกแล้วที่มาเรียนกับข้า! คนซื่อบื้อที่ไหนก็เชี่ยวชาญวิศวกรรมพื้นฐานได้ พวกโนมกับ Gnomeregan บ้านที่เปื้อนรังสีของพวกเขาเป็นหลักฐาน แต่การเชี่ยวชาญวิศวกรรมสายก็อบลินต้องใช้สมองแข็งแกร่งและมือที่นิ่ง เน้นว่านิ่ง!\n\nเงี่ยหูฟังให้ดี {name} แล้วเจ้าอาจได้เรียนรู้บ้าง" },
        required = { [10789] = { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
        steps = { { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
    },
    [3634] = { -- Gnome Engineering
        title = { "17:137600338:1348180482", "วิศวกรรมสายโนม" },
        objective = { "131:1833354953:702994730", "หากต้องการเรียนรู้วิศวกรรมสาย Gnome ให้นำ Manual of Engineering Disciplines ไปให้ Tinkmaster Overspark ใน Ironforge" },
        description = { "236:1090904708:579670785 N 264:1336530488:105222987", "วิศวกรรมระดับเชี่ยวชาญแยกเป็นสองสาย คือโนมกับก็อบลิน แม้ข้าคิดว่าเสียเวลา เจ้าก็ควรรู้ว่ามีสายเฉพาะทางของโนม พวกนั้นทำของกับอุปกรณ์ที่อ้างว่าเปลี่ยนโลกได้ แต่แทบไม่เคยใช้ได้จริง\n\n{name} อ่านคู่มือนี้ หากอยากเรียนวิธีทำที่ทับกระดาษโลหะ ให้นำคู่มือไปให้ Tinkmaster Overspark ใน Ironforge จำไว้ สมาชิกภาพเป็นการถาวรและทำให้เข้าร่วมอีกสายไม่ได้ จงแน่ใจให้ดีก่อนทำงานของเขาสำเร็จ!" },
        progress = { "177:187474945:654092465", "ใช่ ใช่ วันนี้มีเรื่องใดให้ข้าจัดการ? เห็นได้ชัดว่าข้ามีเวลาทำ เพราะข้าเพียงยืนอยู่ที่นี่ ขณะนครที่รักจมในเมฆรังสีมรณะ" },
        completion = { "256:369128849:1460459063", "อา วิศวกรรุ่นเยาว์สนใจสายวิศวกรรมหนึ่งเดียวที่แท้จริง! ขอโทษที่ข้าเล่นใหญ่ เพื่อน แม้สถานการณ์เรายังย่ำแย่ แต่วันที่ได้เห็นวิศวกรอีกคนตอบรับเสียงเรียกของวิศวกรรมแท้จริงก็เป็นวันดีเสมอ!" },
        required = { [10789] = { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
        objectiveLabels = {
            item = { ["Manual of Engineering Disciplines"] = "คู่มือสาขาวิศวกรรม" },
        },
    },
    [3635] = { -- Gnome Engineering
        title = { "17:137600338:1348180482", "วิศวกรรมสายโนม" },
        objective = { "131:315592316:1393490324", "หากต้องการเรียนรู้วิศวกรรมสาย Gnome ให้นำ Manual of Engineering Disciplines ไปให้ Oglethorpe Obnoticus ใน Booty Bay" },
        description = { "230:492102811:1735683856 N 263:724174906:1249923941", "วิศวกรรมระดับเชี่ยวชาญแยกเป็นสองสาย คือโนมกับก็อบลิน แม้ข้าคิดว่าเสียเวลา เจ้าก็ควรรู้ว่ามีสายเฉพาะทางของโนม พวกนั้นทำของกับอุปกรณ์ที่อ้างว่าเปลี่ยนโลกได้ แต่แทบไม่เคยใช้ได้จริง\n\n{name} อ่านคู่มือนี้ หากอยากเรียนวิธีทำที่ทับกระดาษโลหะ ให้นำคู่มือไปให้ Oglethorpe Obnoticus ใน Booty Bay จำไว้ สมาชิกภาพเป็นการถาวรและทำให้เข้าร่วมอีกสายไม่ได้ จงแน่ใจให้ดีก่อนทำงานของเขาสำเร็จ" },
        progress = { "193:1637735959:1927859371", "สวัสดี! หากเจ้ามาเรื่องหุ่นยนต์กลับบ้านที่อาจพุ่งทะลุกำแพงบ้านเจ้า ข้าขอส่งเจ้าไปหาทนายไว้ก่อน หากไม่ใช่ วันนี้มีอะไรให้ช่วย?" },
        completion = { "426:1170730934:1029988233", "เจ้ามาเรียนวิศวกรรมสายโนมสินะ? มาถูกโนมแล้ว แม้ฝ่ายปกครอง Gnomeregan จะใช้การเมืองกีดกันคนที่เห็นว่าเป็นภัยทางปัญญา พวกเขาก็รู้ว่าความรู้เป็นสิ่งที่ควบคุมไม่ได้\n\nทั้งพวกเขาและข้ารู้ดีว่าเมื่อข้าจาก Gnomeregan พวกเขาสูญเสียหนึ่งในวิศวกรโนมผู้ยิ่งใหญ่ที่สุดที่ยังมีชีวิต หากเจ้าเป็นศิษย์ที่มีความสามารถ ข้าจะสอนสิ่งที่รู้ให้" },
        required = { [10789] = { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
        steps = { { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
    },
    [3637] = { -- Gnome Engineering
        title = { "17:137600338:1348180482", "วิศวกรรมสายโนม" },
        objective = { "131:315592316:1393490324", "หากต้องการเรียนรู้วิศวกรรมสาย Gnome ให้นำ Manual of Engineering Disciplines ไปให้ Oglethorpe Obnoticus ใน Booty Bay" },
        description = { "230:492102811:1735683856 N 263:724174906:1249923941", "วิศวกรรมระดับเชี่ยวชาญแยกเป็นสองสาย คือโนมกับก็อบลิน แม้ข้าคิดว่าเสียเวลา เจ้าก็ควรรู้ว่ามีสายเฉพาะทางของโนม พวกนั้นทำของกับอุปกรณ์ที่อ้างว่าเปลี่ยนโลกได้ แต่แทบไม่เคยใช้ได้จริง\n\n{name} อ่านคู่มือนี้ หากอยากเรียนวิธีทำที่ทับกระดาษโลหะ ให้นำคู่มือไปให้ Oglethorpe Obnoticus ใน Booty Bay จำไว้ สมาชิกภาพเป็นการถาวรและทำให้เข้าร่วมอีกสายไม่ได้ จงแน่ใจให้ดีก่อนทำงานของเขาสำเร็จ" },
        progress = { "193:1637735959:1927859371", "สวัสดี! หากเจ้ามาเรื่องหุ่นยนต์กลับบ้านที่อาจพุ่งทะลุกำแพงบ้านเจ้า ข้าขอส่งเจ้าไปหาทนายไว้ก่อน หากไม่ใช่ วันนี้มีอะไรให้ช่วย?" },
        completion = { "426:1170730934:1029988233", "เจ้ามาเรียนวิศวกรรมสายโนมสินะ? มาถูกโนมแล้ว แม้ฝ่ายปกครอง Gnomeregan จะใช้การเมืองกีดกันคนที่เห็นว่าเป็นภัยทางปัญญา พวกเขาก็รู้ว่าความรู้เป็นสิ่งที่ควบคุมไม่ได้\n\nทั้งพวกเขาและข้ารู้ดีว่าเมื่อข้าจาก Gnomeregan พวกเขาสูญเสียหนึ่งในวิศวกรโนมผู้ยิ่งใหญ่ที่สุดที่ยังมีชีวิต หากเจ้าเป็นศิษย์ที่มีความสามารถ ข้าจะสอนสิ่งที่รู้ให้" },
        required = { [10789] = { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
        steps = { { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
    },
    [3638] = { -- The Pledge of Secrecy
        title = { "21:928659263:2009726806", "คำปฏิญาณรักษาความลับ" },
        objective = { "142:643780199:946453421", "หากตกลงเป็น Goblin Engineer ให้คลิกขวาที่ Pledge of Secrecy แล้วคุยกับ Nixx Sprocketspring ใน Gadgetzan อีกครั้ง" },
        description = { "497:2057238879:1752327831 N 1:46:46", "วิศวกรรมสายก็อบลินเน้นใช้งานจริงเพื่อกำไรสูงและพลังระเบิดที่สูงกว่า! แบบของเราสร้างระเบิดและอาวุธทรงพลังได้ คู่มือที่เจ้าอ่านบอกเรื่องนี้แล้ว\n\nคู่มือยังกล่าวถึงคำสาบานรักษาความลับของแบบที่มีมาแต่โบราณ เมื่อเป็นวิศวกรก็อบลินแล้วก็เป็นเช่นนั้น จะเข้าถึงวิศวกรรมโนมไม่ได้เลย\n\nหากยังอยากเป็นวิศวกรก็อบลิน จงลงนามเอกสารสัญญารักษาความลับตลอดชีวิต แล้วคุยกับข้าอีก คิดให้รอบคอบ {name}" },
        progress = { "162:800470220:195647585", "หากลงนามแล้วและพร้อมยื่นเอกสารให้ข้า ก็เป็นอันตกลง เจ้าถูกบอกแล้วว่านี่เป็นทางเดินไปได้อย่างเดียว หากพร้อมก็มาร่วมกัน!" },
        completion = { "32:1972442528:1104529495 N 307:1701086593:1873733508", "ยินดีต้อนรับ วิศวกรก็อบลิน {name}! อีกไม่นานเจ้าจะได้เข้าถึงแบบวิศวกรรมที่ทรงพลังที่สุดใน Azeroth\n\nเมื่อเจ้ามุ่งมั่นแสวงหาความรู้นี้แล้ว ก็ถึงเวลาตรวจผลงานวิศวกรรมแนวก็อบลินของเจ้า จากนั้นเราจะช่วยวางแผนพัฒนาพรสวรรค์สายก็อบลินให้สูงสุด!" },
        required = { [11270] = { "20:859369878:2141395516", "คำปฏิญาณที่ Nixx ลงนามแล้ว" } },
        steps = { { "20:859369878:2141395516", "คำปฏิญาณที่ Nixx ลงนามแล้ว" } },
    },
    [3639] = { -- Show Your Work
        title = { "14:417871975:199642101", "แสดงผลงาน" },
        objective = { "102:1625982618:90458352", "นำ Big Iron Bombs 20 ชิ้น, Solid Dynamite 20 ชิ้น และ Explosive Sheep 5 ชิ้นไปให้ Nixx Sprocketspring ใน Gadgetzan" },
        description = { "102:692351753:443522853 N 399:1594380097:639314346", "ในฐานะอาจารย์ ข้าต้องการตัวอย่างผลงาน เจ้าเป็นวิศวกรฝีมือดี ไม่ต้องสงสัยเลย {name} สิ่งที่ข้าหวังคือวิเคราะห์เพื่อหาวิธีเน้นเทคนิคแนวก็อบลินในงานต่อไป ข้าต้องการระเบิดเหล็กใหญ่ยี่สิบลูก ไดนาไมต์แข็งยี่สิบแท่ง และแกะระเบิดห้าตัว อย่าปลดระบบนิรภัยล่ะ!\n\nส่งของเหล่านี้ให้ข้า แล้วข้าจะออก Goblin Engineer Membership Card ให้ ต้องใช้บัตรนี้เพื่อเข้าถึงครูฝึกวิศวกรรมก็อบลินทุกคน!" },
        progress = { "234:348590467:1929665218", "เมื่อข้าได้รับอุปกรณ์วิศวกรรมที่เจ้าทำมาให้ตรวจ ก็จะมอบ Goblin Engineer Membership Card ของแท้ให้! ตราบใดที่บัตรยังใช้ได้ เจ้าจะเข้าถึงครูฝึกวิศวกรรมก็อบลินคนใดในโลกก็ได้อย่างไม่จำกัด" },
        completion = { "445:2114752650:1852440041", "นี่ Goblin Engineer Membership Card ใบแรกของเจ้า!\n\nบัตรนี้ชำระค่าธรรมเนียมล่วงหน้าสิบสี่วัน บัตรทุกใบหมดอายุหลังใช้งานสองสัปดาห์ เมื่อหมดอายุ ให้จ่ายค่าธรรมเนียมงวดต่อไปแก่ครูฝึกวิศวกรรมก็อบลินคนใดก็ได้เพื่อรับใบใหม่ หากไม่มีบัตร สมาชิกภาพจะขาดชั่วคราวและเจ้าเข้าถึงแบบใหม่ไม่ได้\n\nสิ่งนี้ไม่กระทบความรู้ที่มี เมื่อเป็นวิศวกรก็อบลินแล้ว ก็เป็นตลอดไป" },
        required = { [4394] = { "13:1998331106:669751615", "ระเบิดเหล็กลูกใหญ่" }, [10507] = { "14:2122920835:31278899", "ไดนาไมต์แบบแท่ง" }, [4384] = { "15:1486159952:1099663342", "แกะระเบิด" } },
        steps = { { "13:1998331106:669751615", "ระเบิดเหล็กลูกใหญ่" }, { "14:2122920835:31278899", "ไดนาไมต์แบบแท่ง" }, { "15:1486159952:1099663342", "แกะระเบิด" } },
    },
    [3640] = { -- The Pledge of Secrecy
        title = { "21:928659263:2009726806", "คำปฏิญาณรักษาความลับ" },
        objective = { "142:1671511631:1613821796", "หากตกลงเป็น Gnome Engineer ให้คลิกขวาที่ Pledge of Secrecy แล้วคุยกับ Tinkmaster Overspark ใน Ironforge อีกครั้ง" },
        description = { "488:273424962:236882041 N 1:46:46", "วิศวกรรมสายโนมคือการปรับทฤษฎีวิศวกรรมให้ตอบสนองความต้องการ! แบบของเราสร้างอุปกรณ์ควบคุมโลกรอบตัวได้ คู่มือที่เจ้าอ่านบอกเรื่องนี้แล้ว\n\nคู่มือยังกล่าวถึงคำสาบานรักษาความลับของแบบที่มีมาแต่โบราณ เมื่อเป็นวิศวกรโนมแล้วก็เป็นเช่นนั้น จะเข้าถึงวิศวกรรมก็อบลินไม่ได้เลย\n\nหากยังอยากเป็นวิศวกรโนม จงลงนามเอกสารสัญญารักษาความลับตลอดชีวิต แล้วคุยกับข้าอีก คิดให้รอบคอบ {name}" },
        progress = { "321:1706207576:207383159 N 1:33:33", "หากลงนามแล้วและพร้อมยื่นเอกสารให้ข้า ก็เป็นอันตกลง\n\nความลับที่ข้าจะแบ่งปันยิ่งใหญ่จนการลงนาม Pledge of Secrecy จำเป็นอย่างยิ่ง ข้าเองก็ลงนาม เช่นเดียวกับพี่น้องวิศวกรโนมของข้า เจ้ากำลังเข้าร่วมคณะอันเป็นมงคลทีเดียว วิศวกร {name}!" },
        completion = { "16:986036512:573657706 N 305:990288218:1970612525", "ยินดีต้อนรับ {name}! อีกไม่นานเจ้าจะได้เข้าถึงแบบวิศวกรรมที่ก้าวหน้าที่สุดใน Azeroth\n\nเมื่อเจ้ามุ่งมั่นแสวงหาความรู้นี้แล้ว ก็ถึงเวลาตรวจผลงานวิศวกรรมแนวโนมของเจ้า จากนั้นเราจะช่วยวางแผนพัฒนาพรสวรรค์สายโนมให้สูงสุด!" },
        required = { [11283] = { "25:2042695607:1813326429", "คำปฏิญาณที่ Overspark ลงนามแล้ว" } },
        steps = { { "25:2042695607:1813326429", "คำปฏิญาณที่ Overspark ลงนามแล้ว" } },
    },
    [3641] = { -- Show Your Work
        title = { "14:417871975:199642101", "แสดงผลงาน" },
        objective = { "109:1975089168:1399869350", "นำ Mithril Tubes 6 ชิ้น, Accurate Scope หนึ่งชิ้น และ Advanced Target Dummies 2 ชิ้นไปให้ Tinkmaster Overspark ใน Ironforge" },
        description = { "107:1879753347:741934384 N 371:1358171792:1307238492", "ในฐานะอาจารย์ ข้าต้องการตัวอย่างผลงานบางส่วน เจ้าเป็นวิศวกรฝีมือดี ไม่ต้องสงสัยเลย {name} สิ่งที่ข้าหวังคือวิเคราะห์งานเพื่อหาวิธีเน้นเทคนิคแนวโนมในงานต่อไป ข้าต้องการท่อมิธริลหกชิ้น กล้องเล็งแม่นยำหนึ่งชิ้น และหุ่นเป้าขั้นสูงสองชิ้น\n\nส่งของเหล่านี้ให้ข้า แล้วข้าจะออก Gnome Engineer Membership Card ให้ ต้องใช้บัตรนี้เพื่อเข้าถึงครูฝึกวิศวกรรมโนมทุกคน!" },
        progress = { "232:81971105:689735521", "เมื่อข้าได้รับอุปกรณ์วิศวกรรมที่เจ้าทำมาให้ตรวจ ก็จะมอบ Gnome Engineer Membership Card ของแท้ให้! ตราบใดที่บัตรยังใช้ได้ เจ้าจะเข้าถึงครูฝึกวิศวกรรมโนมคนใดในโลกก็ได้อย่างไม่จำกัด" },
        completion = { "441:107227033:116101843", "นี่ Gnome Engineer Membership Card ใบแรกของเจ้า!\n\nบัตรนี้ชำระค่าธรรมเนียมล่วงหน้าสิบสี่วัน บัตรทุกใบหมดอายุหลังใช้งานสองสัปดาห์ เมื่อหมดอายุ ให้จ่ายค่าธรรมเนียมงวดต่อไปแก่ครูฝึกวิศวกรรมโนมคนใดก็ได้เพื่อรับใบใหม่ หากไม่มีบัตร สมาชิกภาพจะขาดชั่วคราวและเจ้าเข้าถึงแบบใหม่ไม่ได้\n\nสิ่งนี้ไม่กระทบความรู้ที่มี เมื่อเป็นวิศวกรโนมแล้ว ก็เป็นตลอดไป" },
        required = { [4392] = { "21:768240110:1010460574", "หุ่นเป้าฝึกขั้นสูง" }, [10559] = { "12:1034280381:2001765479", "ท่อมิธริล" }, [4407] = { "14:1420297701:1233560249", "กล้องเล็งความแม่นยำสูง" } },
        steps = { { "21:768240110:1010460574", "หุ่นเป้าฝึกขั้นสูง" }, { "12:1034280381:2001765479", "ท่อมิธริล" }, { "14:1420297701:1233560249", "กล้องเล็งความแม่นยำสูง" } },
    },
    [3642] = { -- The Pledge of Secrecy
        title = { "21:928659263:2009726806", "คำปฏิญาณรักษาความลับ" },
        objective = { "142:2091052621:169255723", "หากตกลงเป็น Gnome Engineer ให้คลิกขวาที่ Pledge of Secrecy แล้วคุยกับ Oglethrope Obnoticus ใน Booty bay อีกครั้ง" },
        description = { "488:273424962:236882041 N 1:46:46", "วิศวกรรมสายโนมคือการปรับทฤษฎีวิศวกรรมให้ตอบสนองความต้องการ! แบบของเราสร้างอุปกรณ์ควบคุมโลกรอบตัวได้ คู่มือที่เจ้าอ่านบอกเรื่องนี้แล้ว\n\nคู่มือยังกล่าวถึงคำสาบานรักษาความลับของแบบที่มีมาแต่โบราณ เมื่อเป็นวิศวกรโนมแล้วก็เป็นเช่นนั้น จะเข้าถึงวิศวกรรมก็อบลินไม่ได้เลย\n\nหากยังอยากเป็นวิศวกรโนม จงลงนามเอกสารสัญญารักษาความลับตลอดชีวิต แล้วคุยกับข้าอีก คิดให้รอบคอบ {name}" },
        progress = { "325:751453132:706503354", "หากลงนามแล้วและพร้อมยื่นเอกสารให้ข้า ก็เป็นอันตกลง\n\nแม้ข้าจะขัดแย้งกับ Gnomeregan ทางการเมืองอย่างรุนแรง โดยเฉพาะเจ้า Tinkmaster Overspark โง่นั่น แต่ Pledge of Secrecy อยู่เหนือทุกสิ่ง! เจ้าต้องตกลงเลือกเพียงเส้นทางเดียวและซื่อตรงต่อเส้นทางนั้นตลอดชีวิต" },
        completion = { "16:986036512:573657706 N 305:990288218:1970612525", "ยินดีต้อนรับ {name}! อีกไม่นานเจ้าจะได้เข้าถึงแบบวิศวกรรมที่ก้าวหน้าที่สุดใน Azeroth\n\nเมื่อเจ้ามุ่งมั่นแสวงหาความรู้นี้แล้ว ก็ถึงเวลาตรวจผลงานวิศวกรรมแนวโนมของเจ้า จากนั้นเราจะช่วยวางแผนพัฒนาพรสวรรค์สายโนมให้สูงสุด!" },
        required = { [11282] = { "26:154771612:161839983", "คำปฏิญาณที่ Oglethorpe ลงนามแล้ว" } },
        steps = { { "26:154771612:161839983", "คำปฏิญาณที่ Oglethorpe ลงนามแล้ว" } },
    },
