    [3644] = { -- Membership Card Renewal
        title = { "23:65684867:1997292830", "ต่ออายุบัตรสมาชิก" },
        progress = { "96:1130515441:1134362596", "หากต้องการต่ออายุบัตรสมาชิก เจ้าต้องจ่ายค่าต่ออายุสองเหรียญทอง" },
        completion = { "489:2078502662:1668799491", "เมื่อเจ้าเป็นผู้ฝึกวิศวกรรมก็อบลินและมีสถานะสมาชิกที่ดี ข้าจึงต่อบัตรที่ขาดอายุให้ได้ด้วยค่าธรรมเนียมสองเหรียญทอง เมื่อจ่ายแล้วจะออกบัตรใหม่ให้ ใช้เข้าถึงแบบวิศวกรรมก็อบลินจากครูฝึกที่เกี่ยวข้อง\n\nบัตรนี้ใช้งานได้สองสัปดาห์ เมื่อครบกำหนดต้องจ่ายค่าสมาชิกอีก หากอยากเข้าถึงแบบ เจ้าต้องชำระค่าธรรมเนียมที่ค้างไว้" },
        description = { "96:1130515441:1134362596", "หากต้องการต่ออายุบัตรสมาชิก เจ้าต้องจ่ายค่าต่ออายุสองเหรียญทอง" },
    },
    [3645] = { -- Membership Card Renewal
