        title = { "23:65684867:1997292830", "ต่ออายุบัตรสมาชิก" },
        progress = { "96:1130515441:1134362596", "หากต้องการต่ออายุบัตรสมาชิก เจ้าต้องจ่ายค่าต่ออายุสองเหรียญทอง" },
        completion = { "491:1731789702:1780934494", "เมื่อเจ้าเป็นผู้ฝึกวิศวกรรมโนมและมีสถานะสมาชิกที่ดี ข้าจึงต่อบัตรที่ขาดอายุให้ได้ด้วยค่าธรรมเนียมสองเหรียญทอง เมื่อจ่ายแล้วจะออกบัตรใหม่ให้ ใช้เข้าถึงแบบวิศวกรรมโนมจากครูฝึกที่เกี่ยวข้อง\n\nบัตรนี้ใช้งานได้สองสัปดาห์ เมื่อครบกำหนดต้องจ่ายค่าสมาชิกอีก หากอยากเข้าถึงแบบ เจ้าต้องชำระค่าธรรมเนียมที่ค้างไว้", variants = { { "487:13343899:1018553032", "เมื่อเจ้าเป็นผู้ฝึกวิศวกรรมโนมและมีสถานะสมาชิกที่ดี ข้าจึงต่อบัตรที่ขาดอายุให้ได้ด้วยค่าธรรมเนียมสองเหรียญทอง เมื่อจ่ายแล้วจะออกบัตรใหม่ให้ ใช้เข้าถึงแบบวิศวกรรมโนมจากครูฝึกที่เกี่ยวข้อง\n\nบัตรนี้ใช้งานได้สองสัปดาห์ เมื่อครบกำหนดต้องจ่ายค่าสมาชิกอีก หากอยากเข้าถึงแบบ เจ้าต้องชำระค่าธรรมเนียมที่ค้างไว้" } } },
        description = { "96:1130515441:1134362596", "หากต้องการต่ออายุบัตรสมาชิก เจ้าต้องจ่ายค่าต่ออายุสองเหรียญทอง" },
    },
    [4181] = { -- Goblin Engineering
        title = { "18:1210586148:2085550562", "วิศวกรรมสายก็อบลิน" },
        objective = { "131:751450707:371837181", "หากต้องการเรียนรู้วิศวกรรมสาย Goblin ให้นำ Manual of Engineering Disciplines ไปให้ Nixx Sprocketspring ใน Gadgetzan" },
        description = { "240:894764684:1080651359 N 255:1629061532:1479876220", "วิศวกรรมระดับเชี่ยวชาญแยกเป็นสองสาย คือโนมกับก็อบลิน ข้าพูดถึงสายก็อบลินเพียงเพราะเป็นครูที่ยุติธรรม พวกนั้นชอบทำของที่ระเบิดได้ และแทบไม่สนว่าอะไรขวางอยู่ แม้แต่ตัวเอง\n\n{name} อ่านคู่มือนี้ หากอยากเรียนวิธีระเบิดตัวเอง ให้นำไปให้ Nixx Sprocketspring ใน Gadgetzan จำไว้ สมาชิกภาพเป็นการถาวรและทำให้เข้าร่วมอีกสายไม่ได้ จงแน่ใจก่อนทำงานของเขาให้สำเร็จว่านี่คือสิ่งที่เจ้าต้องการ" },
        progress = { "158:2139350791:162920759", "ข้าได้กลิ่นสมาชิกใหม่เหมือนผงระเบิดชั้นดี ดมได้ไกลเป็นไมล์ เจ้ามาเรียนความเชี่ยวชาญด้านการระเบิดหรือ?" },
        completion = { "5:1151914341:80614338 N 309:1701065824:605832551 N 32:1225623224:557922036", "เอาละ {name} เจ้าคิดถูกแล้วที่มาเรียนกับข้า! คนซื่อบื้อที่ไหนก็เชี่ยวชาญวิศวกรรมพื้นฐานได้ พวกโนมกับ Gnomeregan บ้านที่เปื้อนรังสีของพวกเขาเป็นหลักฐาน แต่การเชี่ยวชาญวิศวกรรมสายก็อบลินต้องใช้สมองแข็งแกร่งและมือที่นิ่ง เน้นว่านิ่ง!\n\nเงี่ยหูฟังให้ดี {name} แล้วเจ้าอาจได้เรียนรู้บ้าง" },
        required = { [10789] = { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
        steps = { { "33:2059976389:1564787881", "คู่มือสาขาวิศวกรรม" } },
    },
    [5103] = { -- Hot Fiery Death
        title = { "15:250981969:318496897", "ความตายร้อนระอุ" },
        objective = { "75:1613810258:410571750", "ใครสักคนในโลกต้องรู้ว่าควรทำอะไรกับถุงมือเกราะเหล่านี้ โชคดี!" },
        description = { "216:1296214582:869684160", "สิ่งที่เหลือจากมนุษย์ผู้นี้มีเพียงกระดูกไหม้เกรียม ดูเหมือนเขาตายในระยะเอื้อมถึงสิ่งที่ตามหา ถุงมือเกราะแผ่นที่ยังไม่ได้เผา\n\nบางทีเจ้าควรหยิบถุงมือแล้วออกจากกองไฟ?" },
        completion = { "11:2128479398:1349041600", "อะไรกัน..." },
    },
