    [5283] = { -- The Art of the Armorsmith
        title = { "25:1934994104:1143490263", "ศิลปะช่างตีเกราะ" },
        objective = { "164:598144125:1246052676", "หากต้องการเป็น Armorsmith เจ้าต้องทำไอเทมต่อไปนี้แล้วนำกลับไปให้ Grumnus: Ornate Mithril Helms 4 ชิ้น, Ornate Mithril Boots 2 ชิ้น และ Ornate Mithril Breastplate 1 ชิ้น" },
        description = { "498:344539007:1358840341", "เจ้าเลือกได้ฉลาดแล้ว\n\nข้ากับตา Ironus นี่ไม่ถูกกัน เจ้าคนทำของเล่นไม่ได้เรื่องนั่นรู้ดีว่าใครคือช่างฝีมือตัวจริงแถวนี้\n\nสงครามยิ่งใหญ่ชนะได้ด้วยการป้องกันที่ดี พอถึงเวลาจริง การบุกช่วยเจ้าไม่ได้หรอก\n\nเอาละ เริ่มงานกัน แค่แสดงให้เห็นว่าเจ้ามีพรสวรรค์ดิบอยู่บ้าง จากนั้นข้าจะดึงสิ่งเจือปนที่เหลือออกแล้วหล่อเจ้าเป็นช่างตีเกราะ เจ้ารู้วิธีทำมิธริลประดับลายใช่ไหม?" },
        progress = { "105:1681100386:1495127426", "อา ไม่มีอะไรเหมือนผิวแทนจากหน้าเตาดี ๆ ดูรอยผ้ากันเปื้อนก็รู้ว่าใครแทนได้ที่จริง" },
        completion = { "12:1458812690:83383244 N 143:1696836608:1242719045", "ถึงตรงนี้แล้ว {name} หลังจากนี้ไม่มีทางกลับ ยังไม่สายที่จะเป็นคนทำของเล่น เอ่อ ช่างตีอาวุธ\n\nข้าเชื่อว่าเจ้าจะเลือกถูก" },
        required = { [7935] = { "26:340510424:1004165534", "เกราะอกมิธริลประดับลาย" }, [7936] = { "20:1734399188:1334789181", "รองเท้าเกราะมิธริลประดับลาย" }, [7937] = { "19:216562502:974300044", "หมวกเกราะมิธริลประดับลาย" } },
        objectiveLabels = {
            item = { ["Ornate Mithril Breastplate"] = "เกราะอกมิธริลประดับลาย", ["Ornate Mithril Boots"] = "รองเท้าเกราะมิธริลประดับลาย", ["Ornate Mithril Helm"] = "หมวกเกราะมิธริลประดับลาย" },
        },
    },
    [5284] = { -- The Way of the Weaponsmith
        title = { "26:1270406214:1245838013", "วิถีช่างตีอาวุธ" },
        objective = { "176:241670984:1684273541", "หากต้องการเป็น Weaponsmith เจ้าต้องทำไอเทมต่อไปนี้แล้วนำกลับไปให้ Ironus: Moonsteel Broadswords 4 ชิ้น, Massive Iron Axes 4 ชิ้น, Heavy Mithril Axes 2 ชิ้น และ Big Black Maces 2 ชิ้น" },
        description = { { "228:785677296:596624311 N 261:743695591:479730085", "228:785677296:596624311 N 262:1448590778:752291020" }, "ในฐานะช่างตีอาวุธ เจ้าจะพบว่าวีรชนและนักผจญภัยมักมาหาเพื่อหาอุปกรณ์ แม้บางครั้งงานมากจนแทบทนไม่ไหว แต่ความร่ำรวยก็คุ้มยิ่งกว่าอาการปวดหลังและปอดเปื้อนเถ้า\n\nใช่แล้ว {name} ช่างตีอาวุธต่างหากที่มีทองเต็มมือ!\n\nหากอยากเข้าร่วม เจ้าต้องแสดงว่าทำเงินให้ข้าสักเหรียญสองเหรียญได้ เอ่อ หมายถึงแสดงว่ามีฝีมือพอจะเป็นคนที่ใครก็นึกถึงเมื่อต้องการอาวุธคุณภาพเหนือชั้น ลงมือทำงาน!" },
        progress = { "60:1102915571:853984816", "<Ironus กำลังง่วนเรียงเหรียญทองเป็นกองเล็ก ๆ อย่างเป็นระเบียบ>" },
        completion = { "143:697930229:105689291", "มาสักที! ข้ามีลูกค้ารออยู่\n\nส่งของมาแล้วตั้งใจฟัง เจ้ากำลังจะก้าวแรกในอาชีพช่างตีอาวุธ" },
        required = { [3853] = { "20:844015315:1051409058", "ดาบใบกว้างเหล็กกล้าจันทรา" }, [3855] = { "16:1022735601:1035782688", "ขวานเหล็กขนาดมหึมา" }, [7941] = { "17:2002592076:2062737941", "ขวานมิธริลหนัก" }, [7945] = { "14:2024503114:714954748", "กระบองดำขนาดใหญ่" } },
        steps = { { "20:844015315:1051409058", "ดาบใบกว้างเหล็กกล้าจันทรา" }, { "16:1022735601:1035782688", "ขวานเหล็กขนาดมหึมา" }, { "17:2002592076:2062737941", "ขวานมิธริลหนัก" }, { "14:2024503114:714954748", "กระบองดำขนาดใหญ่" } },
    },
    [5301] = { -- The Art of the Armorsmith
        title = { "25:1934994104:1143490263", "ศิลปะช่างตีเกราะ" },
        objective = { "164:163984533:510790939", "หากต้องการเป็น Armorsmith เจ้าต้องทำไอเทมต่อไปนี้แล้วนำกลับไปให้ Okothos: Ornate Mithril Helms 4 ชิ้น, Ornate Mithril Boots 2 ชิ้น และ Ornate Mithril Breastplate 1 ชิ้น" },
        description = { "201:70179503:944331809 N 262:1368127235:679307796", "ความพอใจ นั่นคือสิ่งที่ข้าได้จากค้อนและทั่ง การเห็นนักรบ Horde ผู้หยิ่งทะนงได้รับการปกป้องด้วยเหล็กของข้า เตือนให้รู้ว่าการมีชีวิตคืออะไร มันเป็นสิ่งเสพติดที่ข้าไม่กล้าเลิก {name}\n\nข้ามอบความพอใจนี้ให้เจ้าไม่ได้ เพียงพาเข้าสู่เส้นทางเท่านั้น เช่นเดียวกับความพยายามทั้งหลายในชีวิต วิถีช่างตีเกราะคือการเดินทาง\n\nหากอยากเป็นหนึ่งในคนพิเศษไม่กี่คน เพียงขอมา ข้าจะฝึกให้ แต่เจ้าต้องทำงานหนึ่งให้สำเร็จก่อน" },
        progress = { "70:1534812685:1173505811", "ข้าจะทุบเหล็กจนกว่าลมหายใจจะถูกพรากไปจากตัว" },
        completion = { "74:814290395:1467520629 N 116:1556203285:1192748076", "นี่คือขั้นสุดท้ายก่อนเริ่มอาชีพใหม่ในฐานะช่างตีเกราะ {name} หากอยากถอนตัว ตอนนี้เป็นโอกาสสุดท้าย หากไม่ ก็เตรียมรับชีวิตแห่งเกียรติยศ" },
        required = { [7935] = { "26:340510424:1004165534", "เกราะอกมิธริลประดับลาย" }, [7936] = { "20:1734399188:1334789181", "รองเท้าเกราะมิธริลประดับลาย" }, [7937] = { "19:216562502:974300044", "หมวกเกราะมิธริลประดับลาย" } },
        objectiveLabels = {
            item = { ["Ornate Mithril Breastplate"] = "เกราะอกมิธริลประดับลาย", ["Ornate Mithril Boots"] = "รองเท้าเกราะมิธริลประดับลาย", ["Ornate Mithril Helm"] = "หมวกเกราะมิธริลประดับลาย" },
        },
    },
    [5302] = { -- The Way of the Weaponsmith
        title = { "26:1270406214:1245838013", "วิถีช่างตีอาวุธ" },
        objective = { "177:23116023:1577411822", "หากต้องการเป็น Weaponsmith เจ้าต้องทำไอเทมต่อไปนี้แล้วนำกลับไปให้ Borgosh: Moonsteel Broadswords 4 ชิ้น, Massive Iron Axes 4 ชิ้น, Heavy Mithril Axes 2 ชิ้น และ Big Black Maces 2 ชิ้น" },
        description = { "94:888015574:170804196 N 238:465046708:1416076725", "สักวันข้าจะสร้างค้อนในตำนาน ค้อนที่คู่ควรกับ Warchief!\n\nมันคืองานทั้งชีวิต {name} คือความหลงใหล ข้าเห็นศักยภาพที่เจ้าจะเข้าร่วม เป็นพวกเรา เป็นช่างตีอาวุธ และข้าคือคนที่ช่วยดึงศักยภาพนั้นออกมาได้\n\nเจ้าต้องทำแค่งานง่าย ๆ ง่ายสำหรับคนที่ฝีมือโดดเด่นอย่างเจ้า" },
        progress = { "27:558117423:384603429", "เพื่อเกียรติแห่ง Horde!" },
        completion = { "74:1176042306:1526985561 N 111:524601826:1798033534", "นี่คือขั้นสุดท้ายก่อนเริ่มอาชีพใหม่ในฐานะช่างตีอาวุธ {name} หากอยากถอนตัว ตอนนี้เป็นโอกาสสุดท้าย หากไม่ ก็เตรียมให้ความรู้ครอบงำเจ้า!" },
        required = { [3853] = { "20:844015315:1051409058", "ดาบใบกว้างเหล็กกล้าจันทรา" }, [3855] = { "16:1022735601:1035782688", "ขวานเหล็กขนาดมหึมา" }, [7941] = { "17:2002592076:2062737941", "ขวานมิธริลหนัก" }, [7945] = { "14:2024503114:714954748", "กระบองดำขนาดใหญ่" } },
        objectiveLabels = {
            item = { ["Moonsteel Broadsword"] = "ดาบใบกว้างเหล็กกล้าจันทรา", ["Massive Iron Axe"] = "ขวานเหล็กขนาดมหึมา", ["Heavy Mithril Axe"] = "ขวานมิธริลหนัก", ["Big Black Mace"] = "กระบองดำขนาดใหญ่" },
        },
    },
    [5305] = { -- Sweet Serenity
        title = { "14:1447022723:1196910852", "Serenity อันหอมหวาน" },
        objective = { "116:1734136642:832325239", "เดินทางไป Stratholme แล้วฆ่า Crimson Hammersmith เก็บ Crimson Hammersmith's Apron แล้วกลับไปหา Lilith" },
        description = { "345:1593630695:1173688272", "ภายใน Scarlet Bastion มี Serenity อันหอมหวาน Crimson Hammersmith ปกป้องสูตรด้วยชีวิต จงปราบเขาแล้วนำผ้ากันเปื้อนมาให้ แล้วข้าจะฝึกเจ้าเป็นช่างทำค้อน\n\nจงเข้าใจ เมื่อเลือกเส้นทางช่างทำค้อนแล้ว เส้นทางช่างทำดาบกับช่างทำขวานจะไม่เปิดให้เจ้าอีก" },
        progress = { "23:488664715:105064946", "ผ้ากันเปื้อนเขา! อยู่ที่ไหน?" },
        completion = { "30:456137722:1264564522 N 1:33:33", "ขอให้เจ้าทุบสมองได้มากมาย {name}!" },
        required = { [13351] = { "27:1994701802:1723704290", "ผ้ากันเปื้อนของช่างตีค้อนสีชาด" } },
        objectiveLabels = {
            item = { ["Crimson Hammersmith's Apron"] = "ผ้ากันเปื้อนของช่างตีค้อนสีชาด" },
        },
    },
    [5306] = { -- Snakestone of the Shadow Huntress
        title = { "33:1383024738:2042966670", "หินงูของพรานเงา" },
        objective = { "114:1056956991:1741955216", "เดินทางไป Blackrock Spire แล้วสังหาร Shadow Hunter Vosh'gajin เก็บ Vosh'gajin's Snakestone แล้วกลับไปหา Kilram" },
        description = { "31:417219747:785364930 C 336:61729062:165554430", "อย่าให้ความงามนางหลอกเจ้า {class} พรานเงา Vosh'gajin ทั้งอันตรายและวิปลาส\n\n<Kilram ชี้แผลเป็นบนใบหน้า>\n\nใช่ นางทำให้ข้า นางเรียกมันว่าการแตะด้วยรัก\n\nในที่สุดเวลาล้างแค้นก็มาถึง\n\nเจ้าพบ Vosh'gajin ได้ใน Blackrock Spire สังหารนางแล้วนำหินงูกลับมาให้ข้า ทำได้แล้วข้าจะสอนวิถีช่างทำขวาน" },
        progress = { "100:1815848366:1313202161", "ตำนานกล่าวว่าการใช้หินงูของ Vosh'gajin เพียงครั้งเดียว ทำให้ขวานคมกริบได้นาน 1000 ปี!" },
        completion = { "19:1067587147:1376510624", "ความรู้คือพลัง!" },
        required = { [13352] = { "23:2143064921:208320120", "ศิลาอสรพิษของ Vosh'gajin" } },
        objectiveLabels = {
            item = { ["Vosh'gajin's Snakestone"] = "ศิลาอสรพิษของ Vosh'gajin" },
        },
    },
    [5307] = { -- Corruption
        title = { "10:781093328:1078829414", "ดาบ Corruption" },
        objective = { "135:440355629:1617665166", "หา Black Guard Swordsmith ใน Stratholme แล้วทำลายเขา เก็บ Insignia of the Black Guard แล้วกลับไปหา Seril Scourgebane" },
        description = { "379:1098230721:1391185348", "หากข้าพูดห้วนกับเจ้าก็มีเหตุผล แบบสร้างดาบใหญ่ Corruption ถูก Black Guard หน่วยโครงกระดูกชั้นยอดของ Baron Rivendare ขโมยไป\n\nใช่ Baron Rivendare แห่ง Stratholme\n\nตอนนี้ช่างทำดาบ Black Guard ปกป้องแบบเหล่านั้นด้วย... ชีวิตอันเดด\n\nสังหารเขาแล้วนำหลักฐานกลับมา ข้าจะฝึกวิถีช่างทำดาบให้เจ้า" },
        progress = { "57:494661080:842068145 N 1:63:63", "เจ้าลืมงานที่ได้รับแล้วหรือ {name}?" },
        completion = { "60:1761672019:1293675091", "น่าจะชัดเจนว่าดาบเป็นตัวเลือกที่ดีที่สุดเสมอ" },
        required = { [13350] = { "27:706878572:1328546635", "ตราแห่งกองพิทักษ์ดำ" } },
        objectiveLabels = {
            item = { ["Insignia of the Black Guard"] = "ตราแห่งกองพิทักษ์ดำ" },
        },
    },
