    [94004] = { -- Craftsman's Writ: Elixir of Ogre's Strength
        title = { "43:2145577068:1172719830", "ใบสั่งงานช่าง: Elixir of Ogre's Strength" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "4:1484547199:197607013", "หา?" },
        completion = { "32:569723799:586337152 R 133:1488058544:1180674929", "เจ้าเอายามาแล้ว!!\n\nขอบใจ ชาว{race} เจ้ามาไกลขนาดนี้เพื่อช่วย Sos'mol โอเกอร์ตัวไหนก็ไม่เคยทำแบบนี้มาก่อน\n\nSos'mol จะจำไว้ วันหน้าจะตอบแทน ข้าสัญญา" },
        description = { "197:644468242:1080381215", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Elixir of Ogre's Strength จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 151:1093029440:7505714", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Elixir of Ogre's Strength จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        required = { [3391] = { "23:481528647:142125479", "ยาอายุวัฒนะแห่งพละกำลังโอเกอร์" }, [264011] = { "43:2145577068:1172719830", "ใบสั่งงานช่างสำหรับยาอายุวัฒนะแห่งพละกำลังโอเกอร์" } },
        steps = { { "23:481528647:142125479", "ยาอายุวัฒนะแห่งพละกำลังโอเกอร์" }, { "43:2145577068:1172719830", "ใบสั่งงานช่างสำหรับยาอายุวัฒนะแห่งพละกำลังโอเกอร์" } },
    },
    [94212] = { -- Craftsman's Writ: Elixir of Wisdom
