        description = { "188:124483939:1074669360", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Elixir of Wisdom จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 142:1046441358:2106484943", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Elixir of Wisdom จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        completion = { "230:327341532:1046268645 R 119:589659361:220463349", "ข้ายอมรับว่าคิดว่าลมแรงบนที่สูงจะฉีกจดหมายนั่นขาดเป็นชิ้น ๆ ข้าไม่คิดว่าจะมีใครเห็นคำขอเล็ก ๆ ของข้า นับประสาอะไรกับการนำของมาส่งถึงมือ\nเจ้ามีน้ำใจและน่าชื่นชมมาก {race} ข้าจะใช้สิ่งนี้ช่วยในการทำสมาธิ\nถ้าอยากอยู่เล่าเรื่องการเดินทางสักเรื่องสองเรื่องก็เชิญนะ ข้าชอบมีเพื่อนคุย" },
        progress = { "32:695050921:1319430548", "มาสิ มาผิงไฟให้ร่างกายอบอุ่นก่อน" },
        required = { [3383] = { "16:1157188141:1835738591", "ยาอายุวัฒนะเพิ่มปัญญา" }, [264012] = { "34:1346176741:585576844", "ใบสั่งงานช่างสำหรับยาอายุวัฒนะเพิ่มปัญญา" } },
        steps = { { "16:1157188141:1835738591", "ยาอายุวัฒนะเพิ่มปัญญา" }, { "34:1346176741:585576844", "ใบสั่งงานช่างสำหรับยาอายุวัฒนะเพิ่มปัญญา" } },
    },
    [94213] = { -- Craftsman's Writ: Lesser Mana Potion
        title = { "36:1426799185:1406383139", "ใบสั่งงานช่าง: Lesser Mana Potion" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "10:10763625:219111161 R 108:2107147611:1619097806", "สวัสดี ชาว{race} ข้ายินดีที่มีคนมาคุยด้วย แต่ตอนนี้ข้ากำลังสนใจเรื่องอื่นอยู่ ถ้าไม่มีธุระก็เดินทางต่อเถอะ" },
        completion = { "245:1346155036:1742746787", "อา นี่คือยาที่ข้าสั่งไว้หรือ?\n\n<หญิงชาวเอลฟ์รับขวดยาจากเจ้าด้วยความสุภาพ>\n\nเจ้ามาทันเวลาพอดี ข้าซาบซึ้งในน้ำใจของเจ้ามาก ข้าขอรับยาไว้ และขอมอบของเล็ก ๆ น้อย ๆ แทนคำขอบคุณ\n\nขอบคุณนะ หวังว่าจะได้พบกันอีก" },
        description = { "45:505273345:953170475 W2 144:487052709:1355723271", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Lesser Mana Potion จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [3385] = { "18:93714149:2070669696", "ยาฟื้นมานาระดับต้น" }, [264013] = { "36:1426799185:1406383139", "ใบสั่งงานช่างสำหรับยาฟื้นมานาระดับต้น" } },
        steps = { { "18:93714149:2070669696", "ยาฟื้นมานาระดับต้น" }, { "36:1426799185:1406383139", "ใบสั่งงานช่างสำหรับยาฟื้นมานาระดับต้น" } },
    },
    [94214] = { -- Craftsman's Writ: Shadow Protection Potion
        title = { "42:1819409034:1626034594", "ใบสั่งงานช่าง: Shadow Protection Potion" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "137:874309901:543236742", "เฮ้ คราวหน้าจำไว้นะ อย่าวิ่งเต็มฝีเท้าเข้าใส่ก็อบลินที่มีคนคุ้มกัน! ไม่มีทางรู้ว่าจะเกิดอะไรขึ้นหรอก" },
        completion = { "266:108621177:1156156719", "แต่ก็เอาเถอะ พอได้ใบสั่งด่วนแบบนี้ ข้าก็โทษเจ้าไม่ได้ที่รีบมารับเงิน\n\nเอ้า นี่ของเจ้า ขอบใจที่หายาป้องกันเงาที่ข้าต้องการมากมาให้ เห็นหรือยังว่าข้างนอกนี่มันมีอะไรเกิดขึ้นบ้าง?" },
        description = { "45:505273345:953170475 W2 150:2062779101:1644650635", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Shadow Protection Potion จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [6048] = { "24:400575771:2010491069", "ยาป้องกันพลังเงา" }, [264014] = { "42:1819409034:1626034594", "ใบสั่งงานช่างสำหรับยาป้องกันพลังเงา" } },
        steps = { { "24:400575771:2010491069", "ยาป้องกันพลังเงา" }, { "42:1819409034:1626034594", "ใบสั่งงานช่างสำหรับยาป้องกันพลังเงา" } },
    },
    [94215] = { -- Craftsman's Writ: Free Action Potion
        title = { "36:1244132580:2050255731", "ใบสั่งงานช่าง: Free Action Potion" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "111:1849086162:1956429160", "<เจ้ามาถึงจุดที่ระบุไว้ในใบสั่งงานพอดี ตรงหน้ามีสิ่งมีชีวิตกำลังดิ้นอยู่ในใยแมงมุม เห็นชัดว่ามันติดอยู่>" },
        completion = { "346:1083968095:845905987", "<เจ้ารีบยื่น Free Action Potion ที่ขอไว้ให้ก้อนใยที่กำลังดิ้น มันดูเหมือนจะไม่รู้ว่าเจ้าอยู่ตรงนั้น หรือไม่ก็ขยับมารับของไม่ได้\n\nข้างรังใยมีเหรียญโปรยอยู่กำหนึ่ง เจ้าอาจวางยาไว้ตรงนั้นแล้วหยิบเหรียญไปเสีย ธรรมชาติคงจัดการเรื่องที่เหลือเอง>" },
        description = { "45:505273345:953170475 W2 144:1740558955:182521254", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Free Action Potion จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [5634] = { "18:2058531191:567058659", "ยาเคลื่อนไหวอิสระ" }, [264015] = { "36:1244132580:2050255731", "ใบสั่งงานช่างสำหรับยาเคลื่อนไหวอิสระ" } },
        steps = { { "18:2058531191:567058659", "ยาเคลื่อนไหวอิสระ" }, { "36:1244132580:2050255731", "ใบสั่งงานช่างสำหรับยาเคลื่อนไหวอิสระ" } },
    },
    [94216] = { -- Craftsman's Writ: Elixir of Lesser Agility
        title = { "42:962493207:337664514", "ใบสั่งงานช่าง: Elixir of Lesser Agility" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "101:45585529:1686995386", "เจ้ามาเรื่อง...\n\n<Ziz กวาดตามองกระท่อมเล็ก ๆ ของตัวเองอย่างระแวง แล้วลดเสียงลง>\n\nยาใช่ไหม?" },
        completion = { "431:1903347994:1177954668", "<Ziz ยังพูดด้วยเสียงแผ่ว>\n\nข้าจะไม่เล่ายืดยาวหรอกว่ามาทำงานนี้ได้อย่างไร แต่มีคำแนะนำให้เจ้าหน่อย\n\nบางทีถ้าอยากให้เจ้านายใหม่ประทับใจ ก็แค่เอาผลงานคนอื่นมาเป็นของตัวเอง เจ้าส่งยามา แล้วข้าจะเล่าว่ากว่าจะทำมันได้ ข้าต้องเสียทั้งเลือด เหงื่อ และน้ำตาไปเท่าไร\n\nข้าเพิ่งได้งานใหม่นะ เข้าใจไหม? ต้องทำให้เขาประทับใจตั้งแต่แรกสิ!" },
        description = { "45:505273345:953170475 W2 150:69938774:1200852539", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Elixir of Lesser Agility จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [3390] = { "24:1691143591:722120989", "ยาอายุวัฒนะเพิ่มความว่องไวระดับต้น" }, [264016] = { "42:962493207:337664514", "ใบสั่งงานช่างสำหรับยาอายุวัฒนะเพิ่มความว่องไวระดับต้น" } },
        steps = { { "24:1691143591:722120989", "ยาอายุวัฒนะเพิ่มความว่องไวระดับต้น" }, { "42:962493207:337664514", "ใบสั่งงานช่างสำหรับยาอายุวัฒนะเพิ่มความว่องไวระดับต้น" } },
    },
    [94217] = { -- Craftsman's Writ: Lesser Troll's Blood Elixir
        title = { "45:1297180594:711201498", "ใบสั่งงานช่าง: Lesser Troll's Blood Elixir" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        completion = { "193:450466214:496791234", "ได้ตรงตามที่ Short John Mithril สั่งไว้เลย!\n\nนี่เงินของเจ้า กอดไว้แน่น ๆ ตอนรีบออกไปจากที่นี่ล่ะ พวกนักสู้ในสนามกระหายเงินทองพอ ๆ กับที่กระหายเลือด!" },
        progress = { "35:83557496:1239671166", "ยาร์ เอายาของข้ามาให้หรือยัง?" },
        description = { "45:505273345:953170475 W2 153:1753564303:572846852", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Lesser Troll's Blood Elixir จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [3388] = { "27:1270828162:411344351", "ยาอายุวัฒนะเลือดโทรลล์ระดับต้น" }, [264017] = { "45:1297180594:711201498", "ใบสั่งงานช่างสำหรับยาอายุวัฒนะเลือดโทรลล์ระดับต้น" } },
        steps = { { "27:1270828162:411344351", "ยาอายุวัฒนะเลือดโทรลล์ระดับต้น" }, { "45:1297180594:711201498", "ใบสั่งงานช่างสำหรับยาอายุวัฒนะเลือดโทรลล์ระดับต้น" } },
    },
    [94218] = { -- Craftsman's Writ: Elixir of Defense
        title = { "35:881544013:551448102", "ใบสั่งงานช่าง: Elixir of Defense" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        completion = { "300:637190902:555745860", "โอ๊ะ โอ้! ยานั่นเอง!\n\nตายจริง ข้าขอโทษที่ใส่อารมณ์กับเจ้า ข้าระแวงไปหมดตั้งแต่ได้ยินข่าวลือว่ามีก็อบลินตัวหนึ่งว่าจ้างคนมาฆ่าข้า!\n\nเสียดายที่ข้าไม่มีเงินจ้างคนคุ้มกันเพิ่ม อย่างมากก็ทำได้แค่กระดกยานี่สักขวดแล้วหวังให้ทุกอย่างผ่านไปด้วยดี เอ้า ชนแก้ว!" },
        progress = { "126:1137433360:1525766884", "ถ้าเจ้าคือมือสังหารที่พวกลูกเรือเตือนข้าอยู่เรื่อย ก็คิดให้ดีก่อนจะพุ่งเข้ามาหาข้าล่ะ เจ้านี่!" },
        description = { "189:1120296625:31002847", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Elixir of Defense จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 143:1840152138:2054859222", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Elixir of Defense จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        required = { [8951] = { "17:1703597694:1113881155", "ยาเสริมการป้องกัน" }, [264018] = { "35:881544013:551448102", "ใบสั่งงานช่าง: ยาเสริมการป้องกัน" } },
        objectiveLabels = {
            item = { ["Elixir of Defense"] = "ยาเสริมการป้องกัน", ["Craftsman's Writ: Elixir of Defense"] = "ใบสั่งงานช่าง: ยาเสริมการป้องกัน" },
        },
    },
    [94219] = { -- Craftsman's Writ: Draught of Water Breathing
        title = { "44:1023263816:1737819994", "ใบสั่งงานช่าง: Draught of Water Breathing" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "192:733829322:182030475", "ถ้ามาซื้อของ ข้ามีข่าวร้าย คนแคระคนหนึ่งเหมาของชุดสุดท้ายไปหมดแล้ว ข้ากำลังรอของจากที่ไกล ๆ อยู่\n\nแต่ถ้าอยากได้ขวดเปล่าละก็ มาถูกที่แล้ว!" },
        completion = { "341:564513553:643757882", "ยาหายใจใต้น้ำนี่จำเป็นมากถ้าจะมาตั้งค่ายแถวนี้ในคืนฝนตก ข้าชอบไปงีบใต้สะพานตรงโน้น แต่บางทีน้ำก็ท่วมขึ้นมาถึงใต้สะพาน\n\nทีนี้ข้าก็นอนสบายใจได้ ฝันว่าจมน้ำก็เป็นแค่ฝันแล้ว\n\nคิดดูอีกที ข้าน่าจะสั่งมาเผื่อขายต่อด้วย..." },
        description = { "45:505273345:953170475 W2 152:356458952:1351128138", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Draught of Water Breathing จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [5996] = { "26:396463715:178195552", "ยาดื่มสำหรับหายใจใต้น้ำ" }, [264019] = { "44:1023263816:1737819994", "ใบสั่งงานช่างสำหรับยาดื่มสำหรับหายใจใต้น้ำ" } },
        steps = { { "26:396463715:178195552", "ยาดื่มสำหรับหายใจใต้น้ำ" }, { "44:1023263816:1737819994", "ใบสั่งงานช่างสำหรับยาดื่มสำหรับหายใจใต้น้ำ" } },
    },
    [94220] = { -- Craftsman's Writ: Pearl-Handled Dagger
        title = { "38:1460614371:1305353197", "ใบสั่งงานช่าง: Pearl-Handled Dagger" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "32:1006588022:809397819 R 35:88972858:1657591613", "ย่องเข้ามาหาข้าแบบนี้ไม่ฉลาดเลย ชาว{race} รีบพูด และพูดเบา ๆ" },
        completion = { "296:1346197458:291002488", "อ้อ เจ้าเอากริชมาส่งหรือ? ฮ่า งั้นที่ข้าขู่ไปก็คงฟังดูไม่มีน้ำยาแล้วสิ ว่าไหม?\n\nข้าต้องตื่นตัวอยู่เสมอเพราะหน้าที่ที่นี่ ยิ่งมีพวกอื่... เอ่อ พวก Syndicate ชั่วช้าเพ่นพ่านอยู่แถวนี้ด้วย\n\nทีนี้ส่งกริชให้ข้าได้ไหม? ข้าต้องกลับไปทำงานต่อ" },
        description = { "45:505273345:953170475 W2 146:1226881951:622110980", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Pearl-Handled Dagger จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [5540] = { "20:1645453474:778006190", "มีดสั้นด้ามมุก" }, [264020] = { "38:1460614371:1305353197", "ใบสั่งงานช่างสำหรับมีดสั้นด้ามมุก" } },
