    [94221] = { -- Craftsman's Writ: Golden Rod
        title = { "28:248343794:27627959", "ใบสั่งงานช่าง: Golden Rod" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "131:555484213:326636038", "<คนแคระดูเหมือนกำลังทำสมาธิอย่างลึกซึ้ง การมาถึงของเจ้าทำให้เขาหลุดจากภวังค์ โชคดีที่เขายังยิ้มต้อนรับเจ้า>" },
        completion = { "412:802046737:599229832", "อา Golden Rod ที่ข้าสั่งไว้ ข้าไม่นึกว่าจะได้ของแล้ว กำลังคิดจะกลับไป Ironforge เพื่อซื้อที่โรงประมูลอยู่พอดี เจ้าช่วยให้ข้าไม่ต้องเดินทางอีกเที่ยว เท้าแก่ ๆ คู่นี้ขอบใจเจ้ามาก\n\nข้ายังไม่รู้ว่าจะใช้มันสื่อสารกับ Binding Stones อย่างไร หรือจะทำได้หรือเปล่าด้วยซ้ำ แต่ข้าคิดว่านี่น่าจะช่วยให้เข้าใกล้คำตอบอีกก้าว\n\nอย่างแย่ที่สุด ข้าก็ยังดีใจที่ได้ไม้เท้าใหม่" },
        description = { "45:505273345:953170475 W2 136:733000684:1889520724", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Golden Rod จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [11128] = { "10:742386124:390333358", "คทาทองคำ" }, [264021] = { "28:248343794:27627959", "ใบสั่งงานช่างสำหรับคทาทองคำ" } },
        steps = { { "10:742386124:390333358", "คทาทองคำ" }, { "28:248343794:27627959", "ใบสั่งงานช่างสำหรับคทาทองคำ" } },
    },
    [94222] = { -- Craftsman's Writ: Iridescent Hammer
        title = { "35:1730838068:1153151839", "ใบสั่งงานช่าง: Iridescent Hammer" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        description = { "187:89818404:2071441167", "ข้อความที่เขียนด้วยหมึกจางขอ Iridescent Hammer 1 ชิ้น พร้อมข้อมูลสถานที่ส่งและค่าตอบแทน ด้านล่างมีข้อความระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้", amount = { "45:505273345:953170475 W2 143:1823218410:1615123239", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Iridescent Hammer จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        completion = { "303:1909889454:1086106306", "นี่ค้อนใหม่ข้าเหรอ\n\n<พีออนฉวยอาวุธจากมือเจ้าก่อนที่เจ้าจะทันตอบ เขาเหวี่ยงมันมั่วไปทางเจ้า เฉียดหัวเจ้าไปนิดเดียว>\n\nเยี่ยม! ทีนี้ข้าสู้กลับได้แล้ว อันนี้ไม่ทำหายแน่\n\nเอานี่ไป ข้าไม่รู้ใช้ทำอะไร แต่มันหล่นจากตัวเมือก" },
        progress = { "51:2051847383:506039127", "อ๊ากกก! อ้อ... ข้านึกว่าเจ้าเป็นตัวสไลม์เสียอีก" },
        required = { [5541] = { "17:405408102:1715584892", "ค้อนเหลือบสี" }, [264022] = { "35:1730838068:1153151839", "ใบสั่งงานช่างสำหรับค้อนเหลือบสี" } },
        steps = { { "17:405408102:1715584892", "ค้อนเหลือบสี" }, { "35:1730838068:1153151839", "ใบสั่งงานช่างสำหรับค้อนเหลือบสี" } },
    },
    [94223] = { -- Craftsman's Writ: Silver Skeleton Key
        title = { "37:969769743:693377295", "ใบสั่งงานช่าง: Silver Skeleton Key" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "459:1043410162:451151686", "<เจ้าเดินตามคำแนะนำในใบสั่งงานจนมาถึงส่วนลึกของสุสานใต้ดินที่มีพวกอันเดดล้อมอยู่ บนหีบใกล้ ๆ มีกระดาษโน้ตวางไว้>\n\nใครก็ตามที่ได้อ่านข้อความนี้ก่อน จะเป็นคนแรกที่รู้ว่าข้าตายแล้ว ข้าเป็นเพียงผู้ดูแลสุสาน Raven Hill ที่แม้แต่นายจ้างใน Darkshire ก็แทบลืมว่าข้ามีตัวตน ข้าไม่มีทายาทให้ยกทรัพย์สมบัติมหาศาลนี้ให้ ข้าจึงซ่อนไว้ในหีบนี้ ให้แก่ใครหรืออะไรก็ตามที่เปิดมันได้" },
        completion = { "309:533697711:988534555", "<พวกอันเดดยังรวมตัวกันไม่หยุดอยู่ใกล้ ๆ และไม่เห็นใครอื่น เจ้าเลือกใช้ Silver Skeleton Key เปิดหีบได้อย่างง่ายดาย\n\nถึงข้อความจะอ้างว่ามีทรัพย์สมบัติมากมาย แต่หีบกลับแทบว่างเปล่า อย่างน้อยก็ยังเหลือพอชดเชยค่าใช้จ่ายที่เสียไปกับเรื่องทั้งหมดนี้ได้บ้าง>" },
        description = { "191:2070983639:2104354754", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Silver Skeleton Key จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 145:372333549:103390683", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Silver Skeleton Key จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        required = { [264023] = { "37:969769743:693377295", "ใบสั่งงานช่างสำหรับกุญแจผีเงิน" }, [15869] = { "19:1964299011:1815571102", "กุญแจผีเงิน" } },
        steps = { { "37:969769743:693377295", "ใบสั่งงานช่างสำหรับกุญแจผีเงิน" }, { "19:1964299011:1815571102", "กุญแจผีเงิน" } },
    },
