    [94225] = { -- Craftsman's Writ: Rough Bronze Leggings
        title = { "39:1597277532:288899194", "ใบสั่งงานช่าง: Rough Bronze Leggings" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "10:1294133814:1929270946", "ว่าไงล่ะ?" },
        completion = { "343:1127701950:616351805", "นี่กางเกงเกราะที่ข้าสั่งไว้ใช่ไหม? เขาว่า «สามถึงห้าวันทำการ» เหอะ สามถึงห้าเดือนทำการมากกว่ามั้ง!\n\nข้าสั่งไว้ตอนยังทำงานให้ Venture Co. อยู่ข้างนอกนั่น บอกเลยว่าตอนนี้ข้ากับพวกนั้นเลิกเกี่ยวข้องกันแล้ว ถือว่าใบสั่งนี้หมดอายุไปเถอะ\n\nทำไมเจ้ายังไม่ไปอีกล่ะ? เฮ้อ เอ้า! นี่ค่าตอบแทนเจ้า" },
        description = { "45:505273345:953170475 W2 147:922607686:2080153640", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Rough Bronze Leggings จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [2865] = { "21:2031105228:1771119878", "เกราะขาสำริดแบบหยาบ" }, [264025] = { "39:1597277532:288899194", "ใบสั่งงานช่างสำหรับเกราะขาสำริดแบบหยาบ" } },
        steps = { { "21:2031105228:1771119878", "เกราะขาสำริดแบบหยาบ" }, { "39:1597277532:288899194", "ใบสั่งงานช่างสำหรับเกราะขาสำริดแบบหยาบ" } },
    },
    [94226] = { -- Craftsman's Writ: Green Iron Gauntlets
        title = { "38:748630018:601010153", "ใบสั่งงานช่าง: Green Iron Gauntlets" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        description = { "192:323610506:2136827983", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Green Iron Gauntlets จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 146:1857201364:2003537420", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Green Iron Gauntlets จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        completion = { "415:1149228822:177802275", "อืม ดูเหมือนจะแปลผิดไปไกลเลย ข้าไม่ได้ขอถุงมือเกราะ Green Iron ข้าระบุชัดว่าขอสนับมือ Green Iron\n<MacKinley ทำท่าชกเสยคางเจ้า แล้วจงใจหยุดหมัดห่างจากกรามเจ้าไปเพียงนิดเดียว>\nใส่พวกนี้ชกคนให้สลบได้เหมือนกัน ข้าคงใช้ไปพลาง ๆ ระหว่างรอของใหม่ได้\nนี่ค่าจ้าง อ้อ เจ้าหวังว่าจะได้มากกว่านี้หรือ? ข้าก็หวังเหมือนกัน" },
        progress = { "29:2096654616:67937545", "มารับหมัดประจำวันหรือ?" },
        required = { [3485] = { "20:792097901:1579512098", "ถุงมือเกราะเหล็กสีเขียว" }, [264026] = { "38:748630018:601010153", "ใบสั่งงานช่างสำหรับถุงมือเกราะเหล็กสีเขียว" } },
        steps = { { "20:792097901:1579512098", "ถุงมือเกราะเหล็กสีเขียว" }, { "38:748630018:601010153", "ใบสั่งงานช่างสำหรับถุงมือเกราะเหล็กสีเขียว" } },
    },
