    [94228] = { -- Craftsman's Writ: Green Iron Boots
        title = { "34:1708409315:584308450", "ใบสั่งงานช่าง: Green Iron Boots" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "47:1670550837:617190709", "บอกทีเถอะว่าเจ้าเอารองเท้าบูตมาส่ง..." },
        completion = { "157:1133099090:1654193671", "ในที่สุด! ข้าเดินย่ำพื้นที่ชุ่มน้ำจนเท้าเปียกมาหลายวันแล้ว!\n\nหวังว่าคู่นี้จะไม่ขึ้นสนิมง่ายด้วยนะ ข้าเชื่อว่าเจ้ารู้ว่ากำลังทำอะไรอยู่" },
        description = { "45:505273345:953170475 W2 142:211848397:1519445510", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Green Iron Boots จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [3484] = { "16:1519420715:1834470197", "รองเท้าบูตเหล็กสีเขียว" }, [264028] = { "34:1708409315:584308450", "ใบสั่งงานช่างสำหรับรองเท้าบูตเหล็กสีเขียว" } },
        steps = { { "16:1519420715:1834470197", "รองเท้าบูตเหล็กสีเขียว" }, { "34:1708409315:584308450", "ใบสั่งงานช่างสำหรับรองเท้าบูตเหล็กสีเขียว" } },
    },
    [94229] = { -- Craftsman's Writ: Ornate Spyglass
        title = { "33:338157708:320083836", "ใบสั่งงานช่าง: Ornate Spyglass" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "125:909610084:1165262607", "โห! ข้าเกือบไม่เห็นเจ้าตรงนั้นแน่ะ ถ้าช่างวิศวกรสักคนยอมเอาของที่ข้าสั่งมาส่งเสียที ข้าอาจมองเห็นเจ้าเร็วกว่านี้ก็ได้" },
        completion = { "172:134681078:1685288847", "อ้อ อ้อ! เจ้าเป็นวิศวกรหรือ? อย่างน้อยเจ้าก็คงเป็นคนส่งของละนะ\n\nส่งกล้องส่องทางไกลมาให้ข้าที ข้ามีเวลาไม่มาก แต่มีอะไรต้องตรวจดูอีกเยอะ" },
        description = { "187:1262108392:782923814", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Ornate Spyglass จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 141:1065152555:446547168", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Ornate Spyglass จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        required = { [5507] = { "15:1615885371:2018106550", "กล้องส่องทางไกลประดับลาย" }, [264029] = { "33:338157708:320083836", "ใบสั่งงานช่างสำหรับกล้องส่องทางไกลประดับลาย" } },
        steps = { { "15:1615885371:2018106550", "กล้องส่องทางไกลประดับลาย" }, { "33:338157708:320083836", "ใบสั่งงานช่างสำหรับกล้องส่องทางไกลประดับลาย" } },
    },
    [94230] = { -- Craftsman's Writ: Explosive Sheep
        title = { "33:208432289:1549124257", "ใบสั่งงานช่าง: Explosive Sheep" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "185:1804191453:126349288", "<หญิงผู้ร้อนใจชะเง้อมองเข้าไปในไร่ใกล้ ๆ นางสังเกตเห็นเจ้าเข้ามาทันก่อนจะตกใจ>\n\nบอกทีเถอะว่าเจ้ามาส่งของที่ข้าสั่งทำ!" },
        completion = { "258:1056780231:365934177", "แกะระเบิด (Explosive Sheep) เหรอ? ตัวเล็กกว่าที่ข้าหวังไว้นิดหน่อย แต่...\n\n<นางเอื้อมมือไปรับ แล้วค่อย ๆ ยกมันออกจากอ้อมแขนของเจ้าอย่างระวัง ก่อนจะวางลงเบา ๆ>\n\nหวังว่ามันจะระเบิดแรงพอให้พวกนั้นตกใจหนีไปบ้าง..." },
        description = { "45:505273345:953170475 W2 141:151393633:1722433109", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Explosive Sheep จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [4384] = { "15:1486159952:1099663342", "แกะระเบิด" }, [264030] = { "33:208432289:1549124257", "ใบสั่งงานช่างสำหรับแกะระเบิด" } },
        steps = { { "15:1486159952:1099663342", "แกะระเบิด" }, { "33:208432289:1549124257", "ใบสั่งงานช่างสำหรับแกะระเบิด" } },
    },
    [94231] = { -- Craftsman's Writ: Moonsight Rifle
        title = { "33:766570998:464711495", "ใบสั่งงานช่าง: Moonsight Rifle" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "136:83903241:999456285", "เฮ้ เฮ้ เจ้าน่ะ ไม่เคยได้ยินคำว่า «แนบเนียน» หรือไง? พูดตามข้านะ แนบ... เนียน! เจ้าจะทำข้าเสียเรื่องหมด!" },
        completion = { "175:1329873915:970033735", "โอ้โห ข้าขอถอนคำพูด ดูปืนสวย ๆ กระบอกนี้สิ รับรองว่ายิงหัวซาเทอร์หลุดได้ทั้งหัว\n\nขอบใจนะเพื่อน ทีนี้หลบไปข้าง ๆ ก่อน เดี๋ยวจะโดนลูกหลง" },
        description = { "45:505273345:953170475 W2 141:1235147020:1290325077", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Moonsight Rifle จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [4383] = { "15:2044298661:15250580", "ปืนไรเฟิลเล็งจันทร์" }, [264031] = { "33:766570998:464711495", "ใบสั่งงานช่างสำหรับปืนไรเฟิลเล็งจันทร์" } },
        steps = { { "15:2044298661:15250580", "ปืนไรเฟิลเล็งจันทร์" }, { "33:766570998:464711495", "ใบสั่งงานช่างสำหรับปืนไรเฟิลเล็งจันทร์" } },
    },
    [94232] = { -- Craftsman's Writ: Minor Recombobulator
        title = { "38:1275140274:1399478320", "ใบสั่งงานช่าง: Minor Recombobulator" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "20:1136172086:53973779", "เจ้ามีธุระกับข้าหรือ?" },
        completion = { "416:993985480:811366889", "ไม่รู้เหมือนกันว่าข้าคาดหวังอะไรตอนสั่งเครื่องถอนคำสาป แต่เจ้า Minor Recon... Racom... เฮ้อ เจ้าเครื่องอะไรสักอย่างนี่ไม่ใช่แน่!\n\nฟังนะ ข้ารู้ว่าขั้นตอนขอคืนเงินยุ่งยากแค่ไหน และข้าไม่มีเวลาเสียกับเรื่องนั้นหรอก ข้ารับของไปเสียเลยจะง่ายกว่าสำหรับเราทั้งคู่ คราวหน้าข้าจะเขียนใบสั่งให้ชัดกว่านี้\n\nเพื่อเราทั้งคู่ ก็หวังว่าเจ้าจะไม่ทำใบสั่งหน้านั้นพังอีกล่ะ!" },
        description = { "45:505273345:953170475 W2 146:906035916:556977822", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Minor Recombobulator จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [4381] = { "20:1318608157:230496636", "เครื่องคืนร่างขนาดเล็ก" }, [264032] = { "38:1275140274:1399478320", "ใบสั่งงานช่าง: เครื่องคืนร่างขนาดเล็ก" } },
        objectiveLabels = {
            item = { ["Minor Recombobulator"] = "เครื่องคืนร่างขนาดเล็ก", ["Craftsman's Writ: Minor Recombobulator"] = "ใบสั่งงานช่าง: เครื่องคืนร่างขนาดเล็ก" },
        },
    },
    [94233] = { -- Craftsman's Writ: Practice Lock
        title = { "31:1605791231:1798950428", "ใบสั่งงานช่าง: Practice Lock" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        completion = { "312:1154514523:450446268", "อา ตัวล็อกสำหรับฝึกของข้ามาแล้ว\n\nพวก Syndicate ที่นี่กำลังวางแผนทำให้ที่นี่กลับเป็นคุกเหมือนแต่ก่อน ข้ารู้อยู่แล้วว่าตอนนี้มีออร์คถูกขังอยู่ที่นี่อย่างน้อยคนหนึ่ง อาจมากกว่านั้น ข้าจะไม่ยอมเป็นนักโทษอีกคน แต่ถ้าพวกมันเล่นงานข้าตอนเผลอ คราวนี้ข้าจะเตรียมตัวให้พร้อมกว่าครั้งก่อน" },
        progress = { "177:280919672:1035933266", "ข้าเห็นที่นี่ถูกเผาจนราบและเห็นป้อมถูกโค่นลงกับตา สะใจจริง ๆ\n\nไม่คิดว่าจะมีพวกโจรสักกลุ่มมาพยายามใช้ที่นี่เป็นฐานปฏิบัติการ" },
        description = { "45:505273345:953170475 W2 139:329092421:989875116", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Practice Lock จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [6712] = { "13:627642163:1303129695", "กุญแจล็อกสำหรับฝึก" }, [264033] = { "31:1605791231:1798950428", "ใบสั่งงานช่างสำหรับกุญแจล็อกสำหรับฝึก" } },
        steps = { { "13:627642163:1303129695", "กุญแจล็อกสำหรับฝึก" }, { "31:1605791231:1798950428", "ใบสั่งงานช่างสำหรับกุญแจล็อกสำหรับฝึก" } },
    },
    [94234] = { -- Craftsman's Writ: Shadow Goggles
        title = { "32:325293570:1017694174", "ใบสั่งงานช่าง: Shadow Goggles" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "32:356440530:629982712", "เฮ้! เดินดูทางหน่อยสิ!" },
        completion = { "260:13140811:819763625", "แว่น Shadow Goggles ใหม่ของข้า!\n\n<ก็อบลินโยนเหรียญกำหนึ่งให้เจ้าด้วยมือข้างหนึ่งโดยไม่พูดอะไรอีก ขณะที่อีกมือฉวยแว่นไปจากมือเจ้า กว่าเจ้าจะทันตั้งตัว การซื้อขายก็จบลงและเขาก็หันไปสนใจอย่างอื่นแล้ว>" },
        description = { "45:505273345:953170475 W2 140:1046305095:1613195624", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Shadow Goggles จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [4373] = { "14:196569793:489687021", "แว่นตาเงา" }, [264034] = { "32:325293570:1017694174", "ใบสั่งงานช่างสำหรับแว่นตาเงา" } },
        steps = { { "14:196569793:489687021", "แว่นตาเงา" }, { "32:325293570:1017694174", "ใบสั่งงานช่างสำหรับแว่นตาเงา" } },
    },
    [94235] = { -- Craftsman's Writ: Gnomish Universal Remote
        title = { "42:1169677549:589035660", "ใบสั่งงานช่าง: Gnomish Universal Remote" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "24:803901540:920623514 N 160:1351026017:1664246874", "เดินระวังหน่อย {name}! เจ้าเครื่องนี่ชอบทำงานตอนที่ไม่ทันตั้งตัว และเวลาเราไม่ได้คุมแผงควบคุมอยู่ เราก็ยังไม่ค่อยรู้ว่ามันจะพาเจ้าไปไหน" },
        completion = { "338:886529174:1050031442", "ดูเหมือนเราจะโชคดี ตัวควบคุมมาถึงแล้ว! เจ้าน่าจะปรับตั้งมันไว้ให้ล่วงหน้าแล้วสินะ ยอมรับเลยว่าสำหรับงานนี้ไม่ค่อยเหมาะเท่าไร\n\nข้าคงแกะระบบของมันได้ในเวลาไม่นาน แล้วบางทีข้าอาจได้พักเสียที รู้สึกเหมือนข้านั่งงมแผงควบคุมเครื่องเคลื่อนย้ายมวลสารนี่มาหลายเดือนแล้ว!" },
        description = { "45:505273345:953170475 W2 150:591718954:1721725947", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Gnomish Universal Remote จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [7506] = { "24:1898327933:973492135", "รีโมตอเนกประสงค์แบบโนม" }, [264035] = { "42:1169677549:589035660", "ใบสั่งงานช่างสำหรับรีโมตอเนกประสงค์แบบโนม" } },
        steps = { { "24:1898327933:973492135", "รีโมตอเนกประสงค์แบบโนม" }, { "42:1169677549:589035660", "ใบสั่งงานช่างสำหรับรีโมตอเนกประสงค์แบบโนม" } },
    },
    [94236] = { -- Craftsman's Writ: Big Bronze Bomb
        title = { "33:524166654:432117447", "ใบสั่งงานช่าง: Big Bronze Bomb" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "18:955670467:1263758165", "ได้ของมาไหม?" },
        completion = { "281:160400597:2089140417", "เฮ้ ระเบิดที่ข้าสั่งมาแล้วนี่!\n\nอย่างน้อยก็มาแบบหนึ่งละ ข้าสั่งไว้หลายชนิด! จะได้มีพอทดสอบว่าแต่ละแบบใช้ได้ผลแค่ไหน แถมเหลือไว้ใช้เองอีกสักหน่อย!\n\nเอาเถอะ นี่เงินส่วนหนึ่งของเจ้า ข้าจะจ่ายที่เหลือเมื่อเจ้าเอาของที่ข้าสั่งมาครบ!" },
        description = { "45:505273345:953170475 W2 141:90815406:176430052", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Big Bronze Bomb จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [4380] = { "15:1801894317:2130140161", "ระเบิดสำริดลูกใหญ่" }, [264036] = { "33:524166654:432117447", "ใบสั่งงานช่างสำหรับระเบิดสำริดลูกใหญ่" } },
        steps = { { "15:1801894317:2130140161", "ระเบิดสำริดลูกใหญ่" }, { "33:524166654:432117447", "ใบสั่งงานช่างสำหรับระเบิดสำริดลูกใหญ่" } },
    },
    [94237] = { -- Craftsman's Writ: Crafted Solid Shot
        title = { "36:441366846:1626824933", "ใบสั่งงานช่าง: Crafted Solid Shot" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "21:912023636:1795991637", "มาซื้อหรือมาขายล่ะ?" },
        completion = { "299:1133871606:397863784", "ดีจริงที่เจ้ามาตอนนี้ เมื่อวันก่อนพวกออร์ค Dragonmaw วิ่งผ่านมาสองสามตัว แถมยังถลึงตาใส่ข้าด้วย\n\nกระสุนข้าหมดระหว่างทางมาที่นี่ นั่นเป็นเหตุผลครึ่งหนึ่งที่ข้ายังไม่ได้ออกจากที่เฮงซวยนี่!\n\nอีกครึ่งก็เพราะข้ายังมีเงินให้หาอีกน่ะสิ\n\n<Kixxle ถูมือไปมาด้วยความโลภ>" },
        description = { "192:881511862:177316657", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Crafted Solid Shot จำนวน 200 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 144:1789786394:393401568", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Crafted Solid Shot จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        required = { [8069] = { "18:1255765457:143627861", "ลูกกระสุนตันทำมือ" }, [264037] = { "36:441366846:1626824933", "ใบสั่งงานช่างสำหรับลูกกระสุนตันทำมือ" } },
        steps = { { "18:1255765457:143627861", "ลูกกระสุนตันทำมือ" }, { "36:441366846:1626824933", "ใบสั่งงานช่างสำหรับลูกกระสุนตันทำมือ" } },
    },
    [94238] = { -- Craftsman's Writ: Heavy Leather Ball
        title = { "36:1976905643:1582594693", "ใบสั่งงานช่าง: Heavy Leather Ball" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        description = { "45:505273345:953170475 W2 144:58809632:555173774", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Heavy Leather Ball จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [264038] = { "36:1976905643:1582594693", "ใบสั่งงานช่างสำหรับลูกบอลหนังชนิดหนัก" }, [18662] = { "18:643820607:99397621", "ลูกบอลหนังชนิดหนัก" } },
        steps = { { "36:1976905643:1582594693", "ใบสั่งงานช่างสำหรับลูกบอลหนังชนิดหนัก" }, { "18:643820607:99397621", "ลูกบอลหนังชนิดหนัก" } },
        completion = { "47:1613687485:986471102 R 178:1579741216:1369232489", "นี่อะไร? ลูกบอลที่ข้าฝันอยากได้งั้นเหรอ?\nเจ้า ชาว{race} ยกลูกบอลให้ข้าเหรอ?\nนี่เป็นวันที่มีความสุขที่สุดในชีวิตอ็อกร์เลย... สำคัญกว่ามาก... เอ่อ... แล้วอีกอย่างที่ข้าอยากได้คืออะไรนะ?\nจำไม่ได้แล้ว ตอนนี้ลูกบอลสำคัญที่สุด\nขอบใจนะ!!" },
        progress = { "251:1403362310:1947035958", "<ก่อนเจ้าจะมาถึงตั้งนาน Sos'mol ก็ร้องเพลงที่แต่งสด ๆ ด้วยเสียงเพี้ยน ๆ อยู่แล้ว พอเจ้าเดินเข้ามาใกล้ เขายังคงร้องต่อ เพียงแต่ลดเสียงลง ดูเหมือนเขาจะเขินนิดหน่อย แต่ก็ยังเขินไม่พอที่จะหยุดฮัมเพลงบ่นเรื่องความเบื่อหน่าย>" },
    },
    [94239] = { -- Craftsman's Writ: Fine Leather Pants
        title = { "36:2125186574:1896911582", "ใบสั่งงานช่าง: Fine Leather Pants" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "56:1094824681:323684352", "ไปต่อเถอะ ขอร้องล่ะ อย่าทำให้ใครหันมาสนใจเรา" },
        completion = { "322:1142638713:1652815224", "อ้อ! กางเกงนั่นน่ะหรือ? พอเขียนใบสั่งเสร็จได้ไม่นาน ข้าก็นึกขึ้นได้ว่าต้องหาเสื้อผ้าใหม่ทั้งชุด รวมถึงชุดเอี๊ยมด้วย\n\nถ้ารับของแล้วเจ้าจะเลิกกวนข้า ข้าก็คงต้องทำตามที่ตกลงไว้ ไหน ๆ เจ้าก็ลำบากเดินทางมาหาข้าถึงนี่\n\nรับนี่ไป แล้วขอเถอะ...\n\n<นางโบกมือไล่อย่างสุภาพแต่หนักแน่น>" },
        description = { "190:235061885:654864531", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Fine Leather Pants จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 144:554335084:1639563289", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Fine Leather Pants จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        required = { [5958] = { "18:792101538:413714510", "กางเกงหนังเนื้อดี" }, [264039] = { "36:2125186574:1896911582", "ใบสั่งงานช่างสำหรับกางเกงหนังเนื้อดี" } },
        steps = { { "18:792101538:413714510", "กางเกงหนังเนื้อดี" }, { "36:2125186574:1896911582", "ใบสั่งงานช่างสำหรับกางเกงหนังเนื้อดี" } },
    },
    [94240] = { -- Craftsman's Writ: Herbalist's Gloves
        title = { "36:1836301324:682132302", "ใบสั่งงานช่าง: Herbalist's Gloves" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        description = { "45:505273345:953170475 W2 144:425617180:1874325915", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Herbalist's Gloves จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [7349] = { "18:503216288:1346418859", "ถุงมือของนักสมุนไพร" }, [264040] = { "36:1836301324:682132302", "ใบสั่งงานช่างสำหรับถุงมือของนักสมุนไพร" } },
        steps = { { "18:503216288:1346418859", "ถุงมือของนักสมุนไพร" }, { "36:1836301324:682132302", "ใบสั่งงานช่างสำหรับถุงมือของนักสมุนไพร" } },
        completion = { "476:424357771:755228716", "<Murache ชี้ลงไปตามไหล่เขาไปยังทะเลสาบที่เต็มไปด้วยสิ่งมีชีวิตจำพวกพืชรูปร่างน่ากลัว>\nสิ่งมีชีวิตเหล่านี้น่าทึ่งมาก ข้าสังเกตพวกมันมาหลายวันแล้ว เชื่อว่ามีอะไรให้เราเรียนรู้เกี่ยวกับการเก็บสมุนไพรและเทคนิคเพาะปลูกอีกมาก ถุงมือที่เจ้านำมาน่าจะเหมาะกับงานนี้ ข้าเคยลองจับพวกมันด้วยมือเปล่าครั้งหนึ่ง แล้วต้องนั่งถอนหนามออกจากนิ้วอยู่หลายชั่วโมง\nถ้าข้าค้นพบอะไรน่าสนใจ เจ้าจะเป็นคนแรกที่รู้ สหาย" },
        progress = { "91:1458877644:799693665", "อา ดูเหมือนเจ้าจะมาส่งของสินะ พักหายใจสักครู่ก่อนก็ได้" },
    },
    [94241] = { -- Craftsman's Writ: Dark Leather Tunic
        title = { "36:1395639518:1538165248", "ใบสั่งงานช่าง: Dark Leather Tunic" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "7:2137186954:644959466", "อะไรนะ???" },
        completion = { "157:989087121:792462876 R 110:628221803:1072449169", "เจ้ามาถูกจังหวะพอดีเลย!\n\nCallahan! เสื้อใหม่เจ้ามาแล้ว รีบไปเปลี่ยนเสียที ข้าจะได้เลิกฟังเจ้าบ่นว่าคันอยู่ทั้งวัน\n\nส่วนเจ้า ชาว{race} นี่ค่าตอบแทน ก่อนจะไปไหนลองดูสินค้าของข้าหน่อยสิ ตอนนี้เจ้ามีเงินซื้อแล้วนี่!" },
        description = { "190:1626194330:256337992", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Dark Leather Tunic จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 144:1945467529:1241036750", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Dark Leather Tunic จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        required = { [2317] = { "18:62554482:54968176", "เสื้อหนังสีเข้ม" }, [264041] = { "36:1395639518:1538165248", "ใบสั่งงานช่างสำหรับเสื้อหนังสีเข้ม" } },
        steps = { { "18:62554482:54968176", "เสื้อหนังสีเข้ม" }, { "36:1395639518:1538165248", "ใบสั่งงานช่างสำหรับเสื้อหนังสีเข้ม" } },
    },
    [94242] = { -- Craftsman's Writ: Pilferer's Gloves
        title = { "35:1851408251:143541969", "ใบสั่งงานช่าง: Pilferer's Gloves" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        description = { "189:1462450632:1530981050", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Pilferer's Gloves จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 143:34822498:1407353796", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Pilferer's Gloves จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        completion = { "125:818378994:1023956547 N 86:724696561:1287927127", "ใช่ ดี ข้าพอใจทั้งฝีมือและความรวดเร็ว ข้าจะพูดถึงเจ้าในทางที่ดีกับผู้บังคับบัญชาของข้า\nฉายา “{name} แห่ง Syndicate” ฟังเป็นอย่างไร? ทำงานดีแบบนี้ต่อไป สักวันฉายานั้นอาจเป็นของเจ้าก็ได้!" },
        progress = { "19:1830598057:344894461", "มาซื้อหรือมาขาย?" },
        required = { [7358] = { "17:525978285:705975022", "ถุงมือของนักล้วงมือเบา" }, [264042] = { "35:1851408251:143541969", "ใบสั่งงานช่างสำหรับถุงมือของนักล้วงมือเบา" } },
        steps = { { "17:525978285:705975022", "ถุงมือของนักล้วงมือเบา" }, { "35:1851408251:143541969", "ใบสั่งงานช่างสำหรับถุงมือของนักล้วงมือเบา" } },
    },
