        title = { "30:1252063140:1094363362", "ใบสั่งงานช่าง: Heavy Quiver" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        description = { "182:101606605:2039177179", "ข้อความที่เขียนด้วยหมึกจางขอ Heavy Quiver 1 ชิ้น พร้อมข้อมูลสถานที่ส่งและค่าตอบแทน ด้านล่างมีข้อความระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้", amount = { "45:505273345:953170475 W2 138:816341782:831579300", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Heavy Quiver จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        progress = { "15:1826290293:1959760166", "ต้องการงานทำหรือ?" },
        completion = { "107:1931914249:1185287752", "ข้า... อืม\n\nข้าจำไม่ได้ว่าสั่งนี่มาทำไม\n\n<Ziz ยักไหล่แล้วโยนกระบอกลูกธนูใส่กองขยะใกล้ ๆ>" },
        required = { [7371] = { "12:1239901145:2074158759", "กระบอกธนูแบบหนัก" }, [264043] = { "30:1252063140:1094363362", "ใบสั่งงานช่างสำหรับกระบอกธนูแบบหนัก" } },
        steps = { { "12:1239901145:2074158759", "กระบอกธนูแบบหนัก" }, { "30:1252063140:1094363362", "ใบสั่งงานช่างสำหรับกระบอกธนูแบบหนัก" } },
