    [94244] = { -- Craftsman's Writ: Dark Leather Shoulders
        title = { "40:1000941783:1478042513", "ใบสั่งงานช่าง: Dark Leather Shoulders" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "47:864234217:758838521", "ย้าร์ เจ้ามีธุระอะไรกับ Narkk ล่ะ?" },
        completion = { "239:1776661067:1507366571", "ในที่สุดก็ได้สนับไหล่เสียที!\n\nเคยให้นกช่างร้องพวกนี้มาเกาะไหล่ไหม? พนันได้ว่าไม่เคย! กรงเล็บพวกมันจิกเจ็บจะตาย!\n\nทีนี้พวกมันก็มีที่เกาะทั้งวัน ส่วนถุงเงินเจ้าก็หนักขึ้น!\n\n<Narkk เหลือบมองถุงเงินใบนั้น>\n\nอย่างน้อยก็ตอนนี้ละนะ!" },
        description = { "194:955493719:1999316287", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Dark Leather Shoulders จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 148:589412065:1670029529", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Dark Leather Shoulders จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        required = { [4252] = { "22:825510011:227941878", "เกราะไหล่หนังสีเข้ม" }, [264044] = { "40:1000941783:1478042513", "ใบสั่งงานช่างสำหรับเกราะไหล่หนังสีเข้ม" } },
        steps = { { "22:825510011:227941878", "เกราะไหล่หนังสีเข้ม" }, { "40:1000941783:1478042513", "ใบสั่งงานช่างสำหรับเกราะไหล่หนังสีเข้ม" } },
    },
    [94245] = { -- Craftsman's Writ: Barbaric Gloves
        title = { "33:2093471377:2082864970", "ใบสั่งงานช่าง: Barbaric Gloves" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        description = { "45:505273345:953170475 W2 141:1007707529:1736313815", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Barbaric Gloves จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [4254] = { "15:1223715393:1633404055", "ถุงมือแบบชนเผ่า" }, [264045] = { "33:2093471377:2082864970", "ใบสั่งงานช่างสำหรับถุงมือแบบชนเผ่า" } },
        steps = { { "15:1223715393:1633404055", "ถุงมือแบบชนเผ่า" }, { "33:2093471377:2082864970", "ใบสั่งงานช่างสำหรับถุงมือแบบชนเผ่า" } },
        completion = { "305:337762753:270672502", "โอ้ ขอบคุณทองคำ! ในที่สุดถุงมือใหม่ของข้าก็มาถึงเสียที\nเจ้าไม่รู้หรอกว่าข้ารอมานานแค่ไหน ก็อบลินคนอื่น ๆ เอาแต่จะทำงานด้วยมือเปล่า แต่นั่นแหละวิธีทำให้เล็บหลุด หรือไม่ก็นิ้วขาด!\n<ผู้คุมงานถอดถุงมือเก่าที่เขรอะสิ่งสกปรกออกอย่างรวดเร็ว แล้วคว้าถุงมือคู่ใหม่ไปจากมือเจ้า>" },
        progress = { "88:1158717232:1302951746", "ปิดรับสมัครแล้ว เพื่อน อีกอย่าง เจ้าดูตัวใหญ่เกินกว่าจะขึ้นรถของเราได้" },
    },
    [94246] = { -- Craftsman's Writ: Red Whelp Gloves
        title = { "34:2042193053:107815424", "ใบสั่งงานช่าง: Red Whelp Gloves" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        description = { "45:505273345:953170475 W2 142:1702136004:1778052895", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Red Whelp Gloves จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [7284] = { "16:1853204453:1357977171", "ถุงมือหนังลูกมังกรแดง" }, [264046] = { "34:2042193053:107815424", "ใบสั่งงานช่างสำหรับถุงมือหนังลูกมังกรแดง" } },
        steps = { { "16:1853204453:1357977171", "ถุงมือหนังลูกมังกรแดง" }, { "34:2042193053:107815424", "ใบสั่งงานช่างสำหรับถุงมือหนังลูกมังกรแดง" } },
        completion = { "317:1735657134:1463590754", "นี่คือ Red Whelp Gloves หรือ? ได้ยินมาว่าทำแพงมาก แต่คุ้มค่าทุกเหรียญทองแดง ข้ากำลังคิดจะเตรียมอุปกรณ์ไปจัดการพวกมังกรตัวเล็ก ๆ ทางตะวันออกเฉียงเหนืออยู่พอดี แต่ได้ยินว่ามันพ่นไฟได้\nเอาเป็นว่าข้าขอรับถุงมือจากมือเจ้า มาสวมบนมือข้าเองเลยแล้วกัน! ขอบใจนะ เพื่อน!" },
        progress = { "19:2054261349:1564919624", "มีอะไรมาให้ข้าล่ะ?" },
    },
    [94247] = { -- Craftsman's Writ: Lesser Wizard's Robe
        title = { "38:1902332838:926900567", "ใบสั่งงานช่าง: Lesser Wizard's Robe" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "153:739626307:273539257", "<ชายผู้นั้นยืนตัวตรง มองข้ามไหล่เขาไปทาง Dalaran เมื่อเห็นเจ้า เขาก็ยกมือโบกเบา ๆ เป็นสัญญาณให้เข้ามาใกล้>" },
        completion = { "301:652578762:1861889225", "<Alan พูดกระซิบ>\n\nเจ้าไม่คิดหรือว่าการถือเสื้อคลุมหรู ๆ มาส่งให้ชายในชุดหนังสีเข้มกลางวันแสก ๆ มันดูน่าสงสัยไปหน่อย?\n\nแต่ เอ่อ โชคดีที่ข้ามาที่นี่ในนามของ Kirin Tor จึงไม่มีการส่งมอบของแบบลับ ๆ ล่อ ๆ แน่นอน ไม่มีเลย\n\nขอเสื้อคลุมด้วย" },
        description = { "45:505273345:953170475 W2 146:1775064579:1467008686", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Lesser Wizard's Robe จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [5766] = { "20:1945800721:1905402512", "เสื้อคลุมพ่อมดระดับต้น" }, [264047] = { "38:1902332838:926900567", "ใบสั่งงานช่างสำหรับเสื้อคลุมพ่อมดระดับต้น" } },
        steps = { { "20:1945800721:1905402512", "เสื้อคลุมพ่อมดระดับต้น" }, { "38:1902332838:926900567", "ใบสั่งงานช่างสำหรับเสื้อคลุมพ่อมดระดับต้น" } },
    },
    [94248] = { -- Craftsman's Writ: Blue Overalls
        title = { "31:1938427656:1163179018", "ใบสั่งงานช่าง: Blue Overalls" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        completion = { "200:325236465:1232788286", "Blue Overalls! ขอบคุณสวรรค์ ในที่สุดข้าก็มีเสื้อผ้าดี ๆ ไว้เปลี่ยน\n\nรับนี่ไปเถอะ แล้วรีบไปตามทาง ข้าไม่มีเวลาคุย ต้องเฝ้าดูไร่และเสี่ยงเสียสมาธิอีกไม่ได้แล้ว" },
        progress = { "120:1360086735:1831646556", "โอ๊ะ เบาเสียงหน่อยเถอะ เราไม่ควรดึงความสนใจมาที่ตัวเองมากกว่านี้\n\nเจ้ามีอะไรมาให้ข้าหรือ?", variants = { { "120:673952097:185583397", "โอ๊ะ เบาเสียงหน่อยเถอะ เราไม่ควรทำให้ใครหันมาสนใจเรามากกว่านี้\n\nเจ้ามีอะไรมาให้ข้าหรือ?" } } },
        description = { "185:1681213589:209108780", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Blue Overalls จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 139:1821181191:1295657581", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Blue Overalls จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        required = { [6263] = { "13:960278588:667358285", "ชุดเอี๊ยมสีน้ำเงิน" }, [264048] = { "31:1938427656:1163179018", "ใบสั่งงานช่างสำหรับชุดเอี๊ยมสีน้ำเงิน" } },
        steps = { { "13:960278588:667358285", "ชุดเอี๊ยมสีน้ำเงิน" }, { "31:1938427656:1163179018", "ใบสั่งงานช่างสำหรับชุดเอี๊ยมสีน้ำเงิน" } },
    },
    [94249] = { -- Craftsman's Writ: Azure Silk Hood
        title = { "33:939595220:83376583", "ใบสั่งงานช่าง: Azure Silk Hood" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        completion = { "159:1808631856:1273305366", "นี่มันหมวกคลุมที่ข้าสะ...สั่งไว้นี่!\n\nข้าลืมไปแล้วว่าสั่งมาทำไม แต่รับไว้ก็แล้วกัน\n\nเอ้านี่ เหรียญแวววาว หล่นออกมาจากตัวสไลม์ มีตั้งเยอะแยะ!" },
        progress = { "21:1545696061:152529457 R 5:1505628796:735282883 R 1:33:33", "อ๊ากกก! อ้อ แค่ {race} นี่เอง\n\nหวัดดี {race}!" },
        description = { "45:505273345:953170475 W2 141:187315031:1321608009", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Azure Silk Hood จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [7048] = { "15:69839236:1781399297", "หมวกคลุมผ้าไหมสีฟ้า" }, [264049] = { "33:939595220:83376583", "ใบสั่งงานช่างสำหรับหมวกคลุมผ้าไหมสีฟ้า" } },
        steps = { { "15:69839236:1781399297", "หมวกคลุมผ้าไหมสีฟ้า" }, { "33:939595220:83376583", "ใบสั่งงานช่างสำหรับหมวกคลุมผ้าไหมสีฟ้า" } },
    },
    [94250] = { -- Craftsman's Writ: Small Silk Pack
        title = { "33:312794815:1718732853", "ใบสั่งงานช่าง: Small Silk Pack" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "24:1205521472:205002388", "เฮ้! กระเป๋าใบนั้นของข้าหรือ?" },
        completion = { "262:348943167:833913500", "ฮ่า ๆ ขอบใจนะเพื่อน ข้าติดหนี้เจ้าแล้ว\n\n<Kzixx ล้วงมือเข้าไปใน Small Silk Pack ใบที่เขามีอยู่แล้ว เหรียญอัดแน่นเต็มถุงจนเขาควักออกมาได้กำหนึ่ง เขานับเหรียญเพียงเศษเสี้ยวจากทรัพย์สินทั้งหมดของตัวเองแล้วยื่นให้เจ้า>\n\nเท่านี้น่าจะพอเป็นค่าของ ตกลงแล้วห้ามเปลี่ยนใจนะ!" },
        description = { "187:2124687127:749419409", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Small Silk Pack จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 141:1927731290:413042763", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Small Silk Pack จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
        required = { [4245] = { "15:1590522478:1269271938", "กระเป๋าผ้าไหมขนาดเล็ก" }, [264050] = { "33:312794815:1718732853", "ใบสั่งงานช่างสำหรับกระเป๋าผ้าไหมขนาดเล็ก" } },
