        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "24:1550521174:2101857253", "เจ้ามาเอาของวูดูเรอะ?" },
        completion = { "189:337437221:906156595", "อืม\n\nถ้าเจ้าคิดว่ากางเกงฉูดฉาดนี่เป็นของที่ข้าตามหา ก็คงมาผิดที่นิดหน่อยแล้วละ\n\nแต่ข้าจะรับไว้ให้ก็แล้วกัน ใครจะรู้ อาจมีนักผจญภัยคนอื่นอยากได้กางเกงคู่ใหม่!" },
        description = { "185:1070901234:715485620", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Phoenix Pants จำนวน 1 พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>", amount = { "45:505273345:953170475 W2 139:1210868836:1802034421", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Phoenix Pants จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" } },
