    [94255] = { -- Craftsman's Writ: Spider Silk Slippers
        title = { "38:130653606:1602409927", "ใบสั่งงานช่าง: Spider Silk Slippers" },
        objective = { "162:389979501:1112696269", "หาของที่ลูกค้าขอแล้วนำไปส่งยังตำแหน่งที่ทำเครื่องหมายบนแผนที่ เจ้าต้องมีใบสั่งงานนี้อยู่กับตัวจึงจะทำธุรกรรมสำเร็จได้" },
        progress = { "3:5906921:1541903", "ว่าไง!" },
        completion = { "402:773756819:1072109015", "นี่รองเท้าบูตใหม่ของข้าหรือ?\n\n<Kixxle ดูตื่นเต้นมาก แต่พอเห็นรองเท้าชัด ๆ ความตื่นเต้นก็หายไปทันที>\n\nอา ข้านึกว่ายกเลิกคำสั่งซื้อรองเท้าแตะไปแล้วเสียอีก พอรู้ตัวว่าใส่รองเท้าเปิดนิ้วเดินลุยหนองน้ำนี่มันโง่แค่ไหน ข้าก็สั่งบูตดี ๆ อีกคู่ แต่ยังมาไม่ถึงเลย\n\nช่างเถอะ ยินดีที่ได้ค้าขายกัน ข้าจะเก็บคู่นี้ไว้ใช้ทีหลัง!" },
        description = { "45:505273345:953170475 W2 146:828246821:1807304955", "<ข้อความที่เขียนด้วยหมึกจางระบุให้จัดหา Spider Silk Slippers จำนวน {world2} พร้อมข้อมูลสถานที่ส่งมอบและค่าตอบแทน ด้านล่างระบุว่าใบสั่งงานนี้โอนให้ผู้อื่นได้>" },
        required = { [4321] = { "20:174121489:433428243", "รองเท้าผ้าใยแมงมุม" }, [264055] = { "38:130653606:1602409927", "ใบสั่งงานช่างสำหรับรองเท้าผ้าใยแมงมุม" } },
        steps = { { "20:174121489:433428243", "รองเท้าผ้าใยแมงมุม" }, { "38:130653606:1602409927", "ใบสั่งงานช่างสำหรับรองเท้าผ้าใยแมงมุม" } },
    },
