        description = { "47:542172104:1998871674 N 139:547221996:1079201356", "อา ระหว่างเจ้าไม่อยู่ มีแผ่นจารึกส่งมาถึงเจ้า {name}\n\nว่างเมื่อไรก็อ่านเสีย ถ้าข้าจำไม่ผิด มันมาจากครูฝึกนักบวช Ken'jai เขาอยากคุยกับเจ้าเมื่อพร้อม" },
        progress = { "238:2115537176:43114334", "เจ้ามาถึงแล้ว... ดี ดี! วิญญาณบอกว่าอีกไม่นานเจ้าจะมาหา Ken'jai ให้ข้าเป็นคนแรก ๆ ที่ต้อนรับสู่ Valley of Trials ที่นี่จะไม่เป็นบ้านเจ้านานนัก แต่ระหว่างยังอยู่ ทำไมไม่ใช้เวลาให้คุ้มล่ะ" },
        completion = { "400:599239200:398868974", "เมื่อทดสอบตัวเอง เจ้าจะควบคุมเหล่าวิญญาณได้ดีขึ้นเรื่อย ๆ เรียกขอให้ช่วยเรื่องใหญ่ขึ้นเรื่อย ๆ... นั่นคือหน้าที่ของ Ken'jai คนเก่านี้ เมื่อรู้สึกพร้อมก็มาคุยกับข้า หากวิญญาณเห็นด้วย เราค่อยดูว่าจะสอนความสามารถที่ทรงพลังกว่าให้ได้ไหม... แต่ต้องให้วิญญาณเห็นด้วยเท่านั้น\n\nไปคุยกับคนอื่น ๆ ในหุบเขาเสีย แล้วค่อยมาคุยกับข้าอีก" },
        required = { [9561] = { "15:1417619488:1159995749", "แผ่นจารึกศักดิ์สิทธิ์" } },
        steps = { { "15:1417619488:1159995749", "แผ่นจารึกศักดิ์สิทธิ์" } },
    },
    [3097] = { -- Hallowed Scroll
        title = { "15:1655989805:1860233110", "ม้วนคัมภีร์ศักดิ์สิทธิ์" },
        objective = { "86:1367751321:1912509608", "อ่าน Hallowed Scroll แล้วคุยกับ Dark Cleric Duesten ในโบสถ์ที่ Deathknell" },
        description = { "252:2116982287:1157493615", "อา ระหว่างเจ้าจัดการ Scourge ไร้สติ ม้วนคัมภีร์นี้มาถึงเจ้า ข้าคิดว่าคงเป็นเรื่องสำคัญ เพราะดูเหมือนมีตราครูฝึกนักบวช Duesten ข้าคงหาเวลาอ่านก่อนออกไปอีกครั้ง" },
        progress = { "129:617533839:1704331413 C 285:1665662535:2072449985", "อา ท่ามกลางไฟ โรคระบาด จลาจล และเรื่องแย่กว่านั้นมาก \"ผู้มีศรัทธา\" อีกคนก็มาถึงประตูข้า เอาละ ยินดีต้อนรับ {class} ให้ข้าอธิบายสักเรื่องสองเรื่องก่อนเจ้าจะไปตามหาสิ่งที่ผลักดันตนต่อ แสงสว่างศักดิ์สิทธิ์ไม่เกี่ยวกับเจ้าอีกแล้ว วิญญาณบรรพชนเป็นนิทาน และสิ่งมีชีวิตจาก Nether ไม่ต้องการเจ้า\n\nถึงตรงนี้เข้าใจข้าไหม?" },
        completion = { "500:1350895876:851857476", "มีเรื่องเดียวที่เจ้าต้องรู้ เรารอดมาได้ด้วยเจตจำนงล้วน ๆ ศรัทธาในตนเองแยกเราจากผู้อื่น และด้วยพลังของเรา เราจะเปลี่ยนแปลง Azeroth ทั้งหมดอย่างใหญ่หลวง ผู้อ่อนแอจะพึ่งพาเจ้า คนโรคเรื้อนจะเรียกเจ้าว่านาย และผู้ไม่รู้จะขอคำชี้แนะ หน้าที่ข้าคือให้แน่ใจว่าเจ้ามีเครื่องมือจำเป็น พร้อมเมื่อเวลานั้นมาถึง เมื่อมีประสบการณ์มากขึ้นจงมาหาข้า หากเจ้าพร้อม ข้าจะสอนพลังยิ่งใหญ่กว่าให้", variants = { { "500:383848721:1258437887", "มีเรื่องเดียวที่เจ้าต้องรู้ เรารอดมาได้ด้วยเจตจำนงล้วน ๆ ศรัทธาในตนเองแยกเราจากผู้อื่น และด้วยพลังของเรา เราจะเปลี่ยนแปลง Azeroth ทั้งหมดอย่างใหญ่หลวง ผู้อ่อนแอจะพึ่งพาเจ้า คนโรคเรื้อนจะเรียกเจ้าว่านายหญิง และผู้ไม่รู้จะขอคำชี้แนะ หน้าที่ข้าคือให้แน่ใจว่าเจ้ามีเครื่องมือจำเป็น พร้อมเมื่อเวลานั้นมาถึง เมื่อมีประสบการณ์มากขึ้นจงมาหาข้า หากเจ้าพร้อม ข้าจะสอนพลังยิ่งใหญ่กว่าให้" } } },
        required = { [9569] = { "15:1655989805:1860233110", "ม้วนคัมภีร์ศักดิ์สิทธิ์" } },
        steps = { { "15:1655989805:1860233110", "ม้วนคัมภีร์ศักดิ์สิทธิ์" } },
    },
    [3103] = { -- Hallowed Letter
        title = { "15:646268396:832840096", "จดหมายศักดิ์สิทธิ์" },
        objective = { "75:1903236391:777785962", "อ่าน Hallowed Letter แล้วคุยกับ Priestess Anetta ใน Northshire Abbey" },
        description = { "91:566813027:607752075 N 188:696408743:149099367", "ข้าถูกขอให้รีบแจ้งเรื่องนี้เมื่อเจ้ากลับจากค่ายโคบอลด์ {name} ดูเหมือนเป็นจดหมายผนึกตราของ Priestess Anetta ครูฝึกนักบวชประจำถิ่น ข้าคงรีบอ่านก่อนทำธุระอื่นใน Abbey" },
        progress = { "330:1778670652:1560479446", "อา ในที่สุดก็มาถึง ข้ารู้ว่าเจ้าจะหาทางมาพบ แสงสว่างศักดิ์สิทธิ์ส่องลงบนเจ้าและเส้นทางที่เลือก ยามนี้ยากลำบาก Burning Legion ยังอยู่บน Azeroth ทั่ว Kalimdor ต่างหาวิธีใหม่ป้องกันตนจากความทุกข์ยาก และเป็นหน้าที่เจ้าที่จะช่วยให้ได้มากที่สุด" },
        completion = { "240:328157383:1145048155", "เมื่อมีประสบการณ์เพิ่ม จงกลับมาหาข้า ข้าจะถ่ายทอดความรู้เท่าที่ทำได้ ระหว่างนั้น จงเดินไปด้วยเมตตาในใจและให้ปัญญานำทาง จำไว้ โลกจะดีขึ้นได้ก็ต่อเมื่อเจ้าลงมือทำให้เป็นเช่นนั้น" },
        required = { [9548] = { "15:646268396:832840096", "จดหมายศักดิ์สิทธิ์" } },
        steps = { { "15:646268396:832840096", "จดหมายศักดิ์สิทธิ์" } },
    },
    [3119] = { -- Hallowed Sigil
        title = { "14:867956059:847149481", "ตราศักดิ์สิทธิ์" },
        objective = { "57:755175097:765268744", "อ่าน Hallowed Sigil แล้วคุยกับ Shanda ใน Aldrassil" },
        description = { "180:1194884630:1308759276", "ผู้ส่งสารจาก Shanda ครูฝึกนักบวชของเรามอบตรานี้ให้ข้า ดูเหมือน Shanda อยากคุยกับเจ้าเมื่อมีเวลา อ่านแล้วนำไปให้นางด้วย" },
        progress = { "48:934715745:183483040 N 267:1503083680:1556898192", "ข้ายินดีที่เจ้ามาถึงรวดเร็วเช่นนี้ {name} ยินดีต้อนรับ\n\nอย่างที่คงได้ยิน ทั่ว Teldrassil คึกคักด้วยผู้เดินทางเข้าออก แม้สมาชิก Alliance ยังได้รับอนุญาตให้ขึ้นสู่กิ่งก้าน Teldrassil เพื่อพบ Kaldorei คนอื่นที่เตรียมพร้อมสำหรับการผจญภัยเบื้องหน้า" },
        completion = { "327:664224397:98679753", "ตอนนี้อย่าเพิ่งกังวลเรื่องโลกเบื้องล่าง Teldrassil ภายหลังยังมีเวลา ไปคุยกับคนอื่นใน Shadowglen พวกเขาเล่าเหตุการณ์ที่เกิดขึ้นให้ฟังได้ ช่วยทุกทางที่ทำได้ และเมื่อใดรู้สึกว่าต้องฝึกเพิ่ม จงกลับมา ข้าจะสอนเท่าที่ทำได้" },
        required = { [9557] = { "14:867956059:847149481", "ตราศักดิ์สิทธิ์" } },
        steps = { { "14:867956059:847149481", "ตราศักดิ์สิทธิ์" } },
    },
    [5621] = { -- Garments of the Moon
        title = { "20:1959641719:601567076", "อาภรณ์แห่งจันทรา" },
        objective = { "163:659891930:1443512713", "หา Sentinel Shaya แล้วรักษาบาดแผลด้วย Lesser Heal (Rank 2) จากนั้นมอบ Power Word: Fortitude ให้นาง แล้วกลับไปหา Laurna Morninglight ใน Dolanaar" },
        description = { "18:1049130648:1284051395 N 403:842180416:1085949370", "ข้าต้องการความช่วยเหลือ {name} ข้าต้องอยู่ฝึกศิษย์คนอื่นที่นี่ แต่เจ้าช่วย Sentinel ที่บาดเจ็บอยู่ทางใต้ของ Dolanaar ได้ นางบาดเจ็บขณะลาดตระเวนเมืองและต้องการความช่วยเหลือ นางชื่อ Shaya\n\nเมื่อพบนาง จงรักษาบาดแผลแล้วใช้เวทเสริมร่างกาย อย่างน้อยจะช่วยปกป้องนางได้นานขึ้นหากเจอปัญหา เมื่อทำหน้าที่ต่อ Elune แล้วจงกลับมาหาข้าที่นี่" },
        progress = { "364:1070943896:1065226462", "เวท Fortify ของเราทรงพลังมาก Delor มันช่วยให้สหายรับบาดเจ็บจากการโจมตีทุกชนิดได้มากขึ้น และรอดในสถานการณ์ที่ปกติคงล้มลง แต่ก็ยังเทียบไม่ได้กับความสามารถรักษาของเรา ไม่มีผู้เยียวยาใดยิ่งใหญ่กว่านักบวช จงจำไว้ให้ดี พลังของเจ้าเพียงผู้เดียวพลิกกระแสการรบได้ง่ายดาย" },
        completion = { "286:1079229630:181640021 N 16:1341658357:212464636", "เจ้าทำได้ดีและรับใช้ Elune ข้าขอบใจในเรื่องนั้น\n\nโปรดรับเสื้อคลุมนี้แทนคำขอบคุณ มันแสดงว่าเจ้าคู่ควรกับที่ยืนในคณะ หากอยากสวมก็จงสวมอย่างภูมิใจ แต่ไม่ว่าอย่างไร เราจะยอมรับเจ้าเป็นพวกเราเสมอ\n\nจงไปกับ Elune {name} และขอบใจ" },
        steps = { { "31:1406705301:2051334850", "รักษาและเสริมพลังให้ Sentinel Shaya" } },
    },
    [5622] = { -- In Favor of Elune
        title = { "17:1714167435:739754608", "ในพระกรุณาของ Elune" },
        objective = { "43:1817992852:1575295232", "คุยกับ Laurna Morninglight ใน Teldrassil" },
        description = { { "N 326:1255621927:4461793", "N 329:349383084:1201135326" }, "{name} เมื่อเสร็จธุระใน Shadowglen เจ้าต้องเดินทางไป Dolanaar ที่นั่นจะพบ Laurna Morninglight นางจะสอนวิถี Elune เพิ่มเติม และเจ้าจะได้รับอาภรณ์ชุดแรกที่แสดงฐานะนักบวชแห่ง Elune จากนาง\n\nดูแลตัวเอง ขอให้การเดินทางได้รับความคุ้มครอง" },
        completion = { "49:2133586685:2124959263 N 71:2051111118:509101239", "ข้ายินดีที่ Shanda ส่งเจ้ามาหา {name} การสอนวิถี Elune แก่นักบวชรุ่นใหม่ทำให้ข้าพอใจมาก", variants = { { "49:2133586685:2124959263 N 75:1418187897:216614275", "ข้าดีใจที่ Shanda ส่งเจ้ามาหา {name} การได้สอนวิถีแห่ง Elune ให้แก่นักบวชหญิงรุ่นเยาว์เป็นความสุขของข้า" } } },
    },
    [5623] = { -- In Favor of the Light
        title = { "21:844814981:1560339400", "ในพระกรุณาของแสงสว่าง" },
        objective = { "44:1588532339:617042202", "คุยกับ Priestess Josetta ใน Elwynn Forest" },
        description = { { "335:96373546:661807053", "338:1257129119:1960488919" }, "สวัสดีอีกครั้ง นักบวชรุ่นเยาว์ ถึงเวลาเรียนศาสนาของเราให้มากขึ้น เมื่อเสร็จงานที่ Northshire แล้ว จงไปหา Priestess Josetta ใน Goldshire นางมีเรื่องสอนเจ้าอีก และได้ยินว่าเจ้าก้าวหน้าในวิถีแสงสว่าง นางรอสอนเจ้าเพิ่มเติมอยู่" },
        completion = { "25:2089692431:1019187282 N 75:1012191790:1237052522", "ข้ายินดีที่เจ้ามาถึง {name} เรามีเรื่องต้องคุยมากมายเกี่ยวกับอนาคตและเส้นทางของเจ้าในแสงสว่าง" },
    },
    [5624] = { -- Garments of the Light
        title = { "21:946867902:1187749887", "อาภรณ์แห่งแสงสว่าง" },
        objective = { "161:644083786:1037563565", "หา Guard Roberts แล้วรักษาบาดแผลด้วย Lesser Heal (Rank 2) จากนั้นมอบ Power Word: Fortitude ให้เขา แล้วกลับไปหา Priestess Josetta ใน Goldshire" },
        description = { { "488:431156214:386610899", "488:460323035:148280261", "491:2061623694:56354564", "491:2090790515:1965507555" }, "ปกติข้าจะให้บททดสอบเล็กน้อยแก่ผู้ติดตามแสงสว่าง เพื่อดูว่าคู่ควรกับเสื้อคลุมชุดแรกหรือไม่ มันเป็นสัญญาณภายนอกว่าศาสนจักรยอมรับและสนับสนุนนักบวชผู้นั้น\n\nแต่สถานการณ์นี้ต่างไป ชาว Goldshire คนหนึ่งเห็นยามบาดเจ็บใกล้ทะเลสาบทางตะวันออก เขาชื่อ Roberts หาเขา รักษา เสริมความแข็งแกร่งให้ร่างกาย แล้วกลับมาที่นี่ หากทำได้ ข้าจะถือว่าเจ้าผ่านบททดสอบ", variants = { { "198:2037684263:1685769577 C 284:193515895:197704694", "ปกติข้าจะให้บททดสอบเล็กน้อยแก่ผู้ติดตามแสงสว่าง เพื่อดูว่าคู่ควรกับเสื้อคลุมชุดแรกหรือไม่ มันเป็นสัญญาณภายนอกว่าศาสนจักรยอมรับและสนับสนุน{class}ผู้นั้น\n\nแต่สถานการณ์นี้ต่างไป ชาว Goldshire คนหนึ่งเห็นยามบาดเจ็บใกล้ทะเลสาบทางตะวันออก เขาชื่อ Roberts หาเขา รักษา เสริมความแข็งแกร่งให้ร่างกาย แล้วกลับมาที่นี่ หากทำได้ ข้าจะถือว่าเจ้าผ่านบททดสอบ" } } },
        progress = { "484:1805578322:487699181", "อย่างที่เจ้าคงเริ่มเรียนรู้ เวทรักษาของเราจำเป็นต่อการอยู่รอดของผู้คนในยามยาก โดยเฉพาะนักผจญภัยกับวีรชนที่ใช้อาวุธและเวทต่อสู้ภัยต่าง ๆ มากมาย\n\nจงจำความสำคัญของทักษะนี้เสมอ เมื่อใช้คู่กับ Fortitude สหายของเจ้าจะแข็งแกร่งในการรบมากขึ้น เพราะรับการโจมตีได้หลายครั้งกว่าเดิม\n\nอย่าให้ใครดูแคลนพลังเวทของเจ้า" },
        completion = { "11:1614239848:1406166483 N 432:728231238:1272914050", "ยอดเยี่ยม {name} เมื่อมียามสุขภาพดีช่วยเมืองเพิ่มอีกคน เราก็ปลอดภัยขึ้น ข้ายินดีที่เจ้าเริ่มใช้ความสามารถอย่างมีปัญญา หากพร้อมฝึกเพิ่มเมื่อใดก็กลับมาหา แต่ตอนนี้รับเสื้อคลุมไป มันบอกผู้อื่นว่าเจ้าเป็นสมาชิกคณะ หากไม่อยากสวมก็ไม่เป็นไร ภายหลังจะมีบททดสอบอีก และไม่จำเป็นต้องใช้เสื้อตัวนี้ในการทดสอบเหล่านั้น", variants = { { "11:1614239848:1406166483 N 433:2102535771:1692347326", "ยอดเยี่ยม {name} เมื่อมียามแข็งแรงคอยดูแลเมืองอีกคน พวกเราก็ปลอดภัยขึ้น ข้าดีใจที่เจ้าเริ่มรู้จักใช้พลังอย่างรอบคอบ หากพร้อมฝึกต่อเมื่อใดก็กลับมาหาข้าได้ ตอนนี้รับเสื้อคลุมตัวนี้ไปก่อน ผู้คนจะได้รู้ว่าเจ้าเป็นคนในคณะของเรา จะไม่สวมก็ได้ ต่อไปยังมีบททดสอบอีก แต่ไม่ต้องใช้เสื้อคลุมตัวนี้" } } },
        steps = { { "30:1571091943:1086823272", "รักษาและเสริมพลังให้ Guard Roberts" } },
    },
    [5625] = { -- Garments of the Light
        title = { "21:946867902:1187749887", "อาภรณ์แห่งแสงสว่าง" },
        objective = { "157:1529741007:1001267117", "หา Mountaineer Dolf แล้วรักษาบาดแผลด้วย Lesser Heal (Rank 2) จากนั้นมอบ Power Word: Fortitude ให้เขา แล้วกลับไปหา Maxan Anvol ใน Kharanos" },
        description = { "426:220248886:780440077", "ปกติช่วงนี้จะทดสอบผู้มีพลังระดับเจ้า ว่าคู่ควรกับเสื้อคลุมที่แสดงฐานะในศาสนจักรหรือยัง แต่พูดตามตรง ข้ามีเรื่องเร่งด่วนกว่า ชาว Kharanos เพิ่งมาบอกว่ามี Mountaineer บาดเจ็บอยู่นอกเมืองทางใต้ ชื่อ Dolf\n\nเจ้ารักษา Dolf แล้วให้ Fortitude ข้าก็ถือว่าพิสูจน์ตัวเองแล้ว ว่าอย่างไร?" },
        progress = { "25:13093380:1181753877 N 375:436113452:1200547590", "พบ Dolf หรือยัง {name}?\n\nเจ้าคงรู้แล้วว่าความสามารถรักษาของเรามีประโยชน์มาก ไม่เพียงดูแลผู้บาดเจ็บ แต่ยังจำเป็นต่อการอยู่รอดของคนที่หวังเป็นวีรชนและสร้างชื่อ ด้วย Fortitude ที่ช่วยรับการโจมตีได้มากขึ้น กับเวทรักษาที่คงชีวิตพวกเขา ไม่มีสิ่งใดที่เราฝ่าไปไม่ได้!" },
        completion = { "11:1614239848:1406166483 N 432:728231238:1272914050", "ยอดเยี่ยม {name} เมื่อมียามสุขภาพดีช่วยเมืองเพิ่มอีกคน เราก็ปลอดภัยขึ้น ข้ายินดีที่เจ้าเริ่มใช้ความสามารถอย่างมีปัญญา หากพร้อมฝึกเพิ่มเมื่อใดก็กลับมาหา แต่ตอนนี้รับเสื้อคลุมไป มันบอกผู้อื่นว่าเจ้าเป็นสมาชิกคณะ หากไม่อยากสวมก็ไม่เป็นไร ภายหลังจะมีบททดสอบอีก และไม่จำเป็นต้องใช้เสื้อตัวนี้ในการทดสอบเหล่านั้น", variants = { { "11:534428891:784080240 N 444:787382407:1046187714", "ทำได้ดี {name} เจ้ามีแสงอยู่ในตัวจริง ๆ\n\nเอ้านี่ รับเสื้อคลุมนี้ไป มันจะบอกหน้าที่ของเจ้าในศาสนจักร และให้ผู้คนรู้ว่าเจ้าเป็นนักบวชหญิง จะสวมไว้หรือไม่ก็แล้วแต่เจ้า\n\nต่อไปยังมีบททดสอบอีกหลายอย่าง จงเรียนรู้ความสามารถของตนให้มากที่สุด ลองต่อสู้ตามลำพังสักครั้งสองครั้ง แล้วลองร่วมสู้กับนักเดินทางคนอื่นดู\n\nแต่อย่ากังวลไปเลย... เจ้าเก่งไม่แพ้ใครหรอก" }, { "11:534428891:784080240 N 143:29833956:203774455 C 292:391680878:1054438310", "ทำได้ดีมาก {name} ข้าแน่ใจแล้วว่าแสงสถิตอยู่ในตัวเจ้า\n\nรับเสื้อคลุมนี้ไปสิ มันแสดงหน้าที่ของเจ้าในศาสนจักรและช่วยให้ผู้คนรู้ว่าเจ้าเป็น{class} จะใส่หรือไม่ก็แล้วแต่เจ้า\n\nต่อไปยังมีบททดสอบรออยู่อีก จงหัดใช้ความสามารถของเจ้าและดูว่าเจ้าทำอะไรได้บ้าง ลองสู้ด้วยตัวเองสักครั้งสองครั้ง แล้วลองสู้ร่วมกับนักเดินทางคนอื่นดู\n\nแต่ไม่ต้องกังวลไป เจ้ามีฝีมือไม่แพ้ใครหรอก" } } },
        steps = { { "33:19586385:1733991908", "รักษาและเสริมพลังให้ Mountaineer Dolf" } },
    },
    [5626] = { -- In Favor of the Light
        title = { "21:844814981:1560339400", "ในพระกรุณาของแสงสว่าง" },
        objective = { "35:465665914:1869724770", "คุยกับ Maxan Anvol ใน Dun Morogh" },
        description = { { "5:140207098:2105779678 N 348:347765286:1762134125", "5:140207098:2105779678 N 351:1974946950:195127882" }, "เฮ้ {name}! มีเวลาสักครู่ไหม?!\n\nเจ้าตามแสงสว่างมานานพอจะไปหา Maxan Anvol ใน Kharanos แล้ว เขาจะสอนเส้นทางนี้เพิ่ม และหากพิสูจน์ว่าคู่ควร ก็จะให้อาภรณ์ชุดแรกแสดงฐานะนักบวช\n\nไปได้แล้ว! เมื่อเสร็จงานที่นี่ก็ผ่านอุโมงค์ไป เขารออยู่" },
        completion = { "260:1054657046:1361395718", "อ้อ Branstock ส่งเจ้ามาหรือ? ดี ดี! เขาพูดถูก ถึงเวลาเจ้าก้าวสู่แสงสว่างให้ไกลกว่าเดิม มันจะหล่อหลอมนิสัยและทำให้แข็งแกร่ง... สิ่งที่เจ้าต้องการเหนืออื่นใดคือกำลังกาย... และกำลังใจ" },
    },
    [5627] = { -- Stars of Elune
        title = { "14:833126182:1022651527", "ดวงดาวแห่ง Elune" },
        completion = { "52:1821983492:740383833 N 103:64996413:490607925", "เจ้าพิสูจน์ว่าคู่ควรกับความสนพระทัยของ Elune แล้ว {name} หากรู้สึกพร้อม ข้าอยากสอนเวทบทหนึ่งของนางที่เป็นเอกลักษณ์เฉพาะผู้คนเรา" },
    },
    [5628] = { -- Returning Home
        title = { "14:739898651:749603059", "กลับบ้าน" },
        objective = { "40:751090212:719807644", "คุยกับ Priestess Alathea ใน Darnassus" },
        description = { "16:1817792354:140287719 N 474:221343979:1504256305", "อา สวัสดี {name} ใช่ไหม? ดีใจที่แวะมาคุยสักครู่ อายุเท่านี้แต่เจ้าเดินทางไกลบ้านนัก ข้าชื่นชมความทะเยอทะยานนั้น หวังว่าเมื่อหนุ่มสาวกว่านี้ ข้าจะรวบรวมความกล้าออกเที่ยวโลกได้บ้าง\n\nไม่นานมานี้นักบวชหญิงในคณะเจ้ามาตามหา บอกว่าเร่งด่วนมาก เจ้าต้องกลับ Temple of the Moon ใน Darnassus แล้วคุยกับ Priestess Alathea เกี่ยวกับการฝึกของเจ้า หากเลี่ยงได้ก็อย่าชักช้านัก" },
        completion = { "33:2098673443:1416320849 N 274:1373963763:2051541647", "ยอดเยี่ยม เจ้ากลับบ้านแล้ว {name} Tyrande กับข้ายินดีเสมอเมื่อผู้ที่เราฝึกออกไปสู่โลกแล้วกลับมาอย่างปลอดภัย เป็นอย่างไรบ้าง? Elune ยังอวยพรการเดินทางไหม? บางทีหลังคุยธุระตรงหน้าแล้ว เจ้าคงเล่าการเดินทางให้ฟังได้อีก" },
    },
    [5629] = { -- Returning Home
        title = { "14:739898651:749603059", "กลับบ้าน" },
        objective = { "40:751090212:719807644", "คุยกับ Priestess Alathea ใน Darnassus" },
        description = { "13:1366380142:1891123769 N 382:1292794082:1942500053", "สวัสดีอีกครั้ง {name} ข้ารู้ว่าเจ้าวุ่นกับการช่วยผู้คนเรา แต่ต้องมีเวลาให้ตัวเองด้วย Priestess Alathea ส่งคนมาตามหา ดูเหมือนเจ้าได้รับความสนใจจากผู้อาวุโส และพวกเขาเห็นว่าพร้อมสำหรับสิ่งใหญ่กว่า ไป Temple of the Moon ใน Darnassus แล้วหา Alathea นางจะรออยู่ โชคดี ขอ Elune สถิตกับเจ้า" },
        completion = { "28:712749294:1143866607 N 274:1373963763:2051541647", "ยอดเยี่ยม เจ้ากลับมาแล้ว {name} Tyrande กับข้ายินดีเสมอเมื่อผู้ที่เราฝึกออกไปสู่โลกแล้วกลับมาอย่างปลอดภัย เป็นอย่างไรบ้าง? Elune ยังอวยพรการเดินทางไหม? บางทีหลังคุยธุระตรงหน้าแล้ว เจ้าคงเล่าการเดินทางให้ฟังได้อีก" },
    },
    [5630] = { -- Returning Home
        title = { "14:739898651:749603059", "กลับบ้าน" },
        objective = { "40:751090212:719807644", "คุยกับ Priestess Alathea ใน Darnassus" },
        description = { { "434:1320697170:2104931329", "434:1773031419:2037326869" }, "สวัสดี เจ้าหนู ดีใจที่เจ้าเที่ยวไปไกลถึงดินแดนห่างไกล ไม่ได้ตั้งใจลบหลู่ แต่คนเผ่าเจ้าหลายคนมักทนอากาศหนาวแบบนี้ไม่ค่อยได้ ดีใจที่เจ้าแกร่งกว่า\n\nไม่นานมานี้นักบวชหญิงของเจ้าคนหนึ่งมาตามหา บอกให้ไปหา Priestess Alathea ใน Temple of the Moon กลับไปที่ Darnassus บอกว่าสำคัญและควรกลับเร็ว ๆ นี้" },
        completion = { "33:2098673443:1416320849 N 274:1373963763:2051541647", "ยอดเยี่ยม เจ้ากลับบ้านแล้ว {name} Tyrande กับข้ายินดีเสมอเมื่อผู้ที่เราฝึกออกไปสู่โลกแล้วกลับมาอย่างปลอดภัย เป็นอย่างไรบ้าง? Elune ยังอวยพรการเดินทางไหม? บางทีหลังคุยธุระตรงหน้าแล้ว เจ้าคงเล่าการเดินทางให้ฟังได้อีก" },
    },
    [5631] = { -- Returning Home
        title = { "14:739898651:749603059", "กลับบ้าน" },
        objective = { "40:751090212:719807644", "คุยกับ Priestess Alathea ใน Darnassus" },
        description = { "62:904669254:307339262 R 230:781460825:368712804 N 1:46:46", "นักบวชหญิงเพิ่งมาเยือนหอของเราเพื่อตามหาเจ้า {race}รุ่นเยาว์ นางบอกว่าได้รับภารกิจให้หาเจ้า และเจ้าควรกลับ Temple of the Moon ใน Darnassus โดยเร็วที่สุด เมื่อถึงแล้วหา Priestess Alathea นางจะบอกรายละเอียด\n\nขอแสงสว่างสถิตกับเจ้า {name}" },
        completion = { "33:2098673443:1416320849 N 274:1373963763:2051541647", "ยอดเยี่ยม เจ้ากลับบ้านแล้ว {name} Tyrande กับข้ายินดีเสมอเมื่อผู้ที่เราฝึกออกไปสู่โลกแล้วกลับมาอย่างปลอดภัย เป็นอย่างไรบ้าง? Elune ยังอวยพรการเดินทางไหม? บางทีหลังคุยธุระตรงหน้าแล้ว เจ้าคงเล่าการเดินทางให้ฟังได้อีก" },
    },
    [5632] = { -- Returning Home
        title = { "14:739898651:749603059", "กลับบ้าน" },
        objective = { "40:751090212:719807644", "คุยกับ Priestess Alathea ใน Darnassus" },
        description = { "27:689518837:1195147204 N 368:596612363:1668286431", "อ้อ ใช่ แน่นอน สวัสดี {name} ผู้ส่งสารจากคณะเราเพิ่งมาตามหา นางพูดถึงเรื่องสำคัญที่ Darnassus และเจ้าควรกลับ Temple of the Moon โดยเร็วที่สุด เมื่อถึงแล้วคุยกับ Priestess Alathea ข้าเชื่อว่าเกี่ยวกับการที่เจ้าก้าวหน้าในวิถีเราได้ดี\n\nขอย้ำ กลับ Darnassus เมื่อทำได้" },
        completion = { "33:2098673443:1416320849 N 274:1373963763:2051541647", "ยอดเยี่ยม เจ้ากลับบ้านแล้ว {name} Tyrande กับข้ายินดีเสมอเมื่อผู้ที่เราฝึกออกไปสู่โลกแล้วกลับมาอย่างปลอดภัย เป็นอย่างไรบ้าง? Elune ยังอวยพรการเดินทางไหม? บางทีหลังคุยธุระตรงหน้าแล้ว เจ้าคงเล่าการเดินทางให้ฟังได้อีก" },
    },
    [5633] = { -- Returning Home
        title = { "14:739898651:749603059", "กลับบ้าน" },
        objective = { "40:751090212:719807644", "คุยกับ Priestess Alathea ใน Darnassus" },
        description = { { "387:453923212:1661955163", "386:1062912667:2133255439" }, "สวัสดี เจ้าหนู ดีใจที่เห็นเจ้าในหออันยิ่งใหญ่ของเรา ขอพรสถิตกับเจ้าและผู้คนของเจ้า\n\nระหว่างเดินทางในดินแดนเรา นักบวชหญิงจากวิหารเจ้ามาตามหา บอกให้กลับ Temple of the Moon โดยเร็วที่สุด ข้าเสียใจที่เล่าเพิ่มไม่ได้ แต่ฟังดูสำคัญ เมื่อถึงวิหารจงคุยกับ Priestess Alathea" },
        completion = { "33:2098673443:1416320849 N 274:1373963763:2051541647", "ยอดเยี่ยม เจ้ากลับบ้านแล้ว {name} Tyrande กับข้ายินดีเสมอเมื่อผู้ที่เราฝึกออกไปสู่โลกแล้วกลับมาอย่างปลอดภัย เป็นอย่างไรบ้าง? Elune ยังอวยพรการเดินทางไหม? บางทีหลังคุยธุระตรงหน้าแล้ว เจ้าคงเล่าการเดินทางให้ฟังได้อีก" },
    },
    [5634] = { -- Desperate Prayer
        title = { "16:1434986297:2032252961", "คำภาวนายามสิ้นหวัง" },
        objective = { "40:1954887690:1611417486", "คุยกับ High Priest Rohan ใน Ironforge" },
        description = { "59:485735848:148595316 R 224:608073499:462802639 N 1:46:46", "นักบวชเพิ่งมาเยือนหอของเราเพื่อตามหาเจ้า {race}รุ่นเยาว์ เขาบอกว่าได้รับภารกิจให้หาเจ้า และเจ้าควรกลับ Hall of Mysteries ใน Ironforge โดยเร็วที่สุด เมื่อถึงแล้วหา High Priest Rohan เขาจะบอกรายละเอียด\n\nขอแสงสว่างสถิตกับเจ้า {name}" },
        completion = { "186:829567589:854288386", "เจ้ารับใช้แสงสว่างอย่างยิ่งใหญ่ ด้วยการเป็นแบบอย่างอันเจิดจ้าแก่ผู้เดินทางในดินแดนอันตรายเหล่านี้และไกลออกไป โปรดรับบทเรียนนี้แทนคำขอบคุณสำหรับทุกสิ่งที่ทำ" },
    },
    [5635] = { -- Desperate Prayer
        title = { "16:1434986297:2032252961", "คำภาวนายามสิ้นหวัง" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind", variants = { { "40:1954887690:1611417486", "คุยกับ High Priest Rohan ใน Ironforge" } } },
        description = { "46:186108260:356086005 N 311:375616969:2088147520", "เจ้าได้รับความสนใจจากผู้ใหญ่ของเรา {name} พวกเขาขอให้ไป Cathedral of Light ใน Stormwind โดยเร็วที่สุด ดูเหมือนเห็นว่าเจ้าพิสูจน์ตัวเองแล้วและพร้อมฝึกต่อ เมื่อถึงจงหา High Priestess Laurena นางจะชี้ทางให้ โชคดี ขอแสงสว่างสถิตกับเจ้า", variants = { { "46:186108260:356086005 N 304:1183534586:830561318", "เจ้าได้รับความสนใจจากผู้ใหญ่ของเรา {name} พวกเขาขอให้ไป Hall of Mysteries ใน Ironforge โดยเร็วที่สุด ดูเหมือนเห็นว่าเจ้าพิสูจน์ตัวเองแล้วและพร้อมฝึกต่อ เมื่อถึงจงหา High Priest Rohan เขาจะชี้ทางให้ โชคดี ขอแสงสว่างสถิตกับเจ้า" } } },
        completion = { "25:2089692431:1019187282 N 228:819820501:896419647", "ข้ายินดีที่เจ้ามาถึง {name} เรามีเรื่องต้องคุยมากมาย แต่ที่สำคัญกว่าคือการฝึกวิถีแสงสว่างของเจ้า\n\nมีบทเรียนที่ผู้รับใช้แสงสว่างทุกคนต้องเรียน หากพร้อม เราจะเริ่มคุยเรื่องเหล่านั้นกันตอนนี้" },
    },
    [5636] = { -- Desperate Prayer
        title = { "16:1434986297:2032252961", "คำภาวนายามสิ้นหวัง" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind", variants = { { "40:1954887690:1611417486", "คุยกับ High Priest Rohan ใน Ironforge" } } },
        description = { "22:1882722298:723343487 R 350:22293589:1796639612", "ขอ Elune อวยพรเจ้า {race}ผู้มีไมตรี หวังว่าแสงสว่างของเจ้าจะพบและปกป้องเจ้าในวันนี้\n\nไม่นานมานี้นักบวชของเจ้าคนหนึ่งมาตามหา เขาบอกให้กลับ Cathedral of Light โดยเร็วที่สุด เพื่อคุยกับ High Priestess Laurena ดูเหมือนเจ้าทำดีจนได้รับความสนใจเช่นนั้น ข้าคงไม่อยู่ที่นี่นานนัก ผู้คนเจ้าต้องการเจ้า", variants = { { "22:1882722298:723343487 R 344:2135553704:1528898397", "ขอ Elune อวยพรเจ้า {race}ผู้มีไมตรี หวังว่าแสงสว่างของเจ้าจะพบและปกป้องเจ้าในวันนี้\n\nไม่นานมานี้นักบวชของเจ้าคนหนึ่งมาตามหา เขาบอกให้กลับ Hall of Mysteries โดยเร็วที่สุด เพื่อคุยกับ High Priest Rohan ดูเหมือนเจ้าทำดีจนได้รับความสนใจเช่นนั้น ข้าคงไม่อยู่ที่นี่นานนัก ผู้คนเจ้าต้องการเจ้า" } } },
        completion = { "25:2089692431:1019187282 N 228:819820501:896419647", "ข้ายินดีที่เจ้ามาถึง {name} เรามีเรื่องต้องคุยมากมาย แต่ที่สำคัญกว่าคือการฝึกวิถีแสงสว่างของเจ้า\n\nมีบทเรียนที่ผู้รับใช้แสงสว่างทุกคนต้องเรียน หากพร้อม เราจะเริ่มคุยเรื่องเหล่านั้นกันตอนนี้" },
    },
    [5637] = { -- Desperate Prayer
        title = { "16:1434986297:2032252961", "คำภาวนายามสิ้นหวัง" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind", variants = { { "40:1954887690:1611417486", "คุยกับ High Priest Rohan ใน Ironforge" } } },
        description = { "42:864259708:463981160 N 354:379928339:1690873709", "ถึงเวลาเจ้าไป Stormwind {name} High Priestess Laurena ใน Cathedral of Light อยากคุยด้วย ต้องมีเรื่องดีมากหรือแย่มากแน่ นางถึงอยากพบด้วยตนเอง แต่ข้าเดาว่าเจ้าทำดีมาตลอด คงเป็นเรื่องดีที่นางอยากคุย\n\nอย่าเสียเวลาแถวนี้มากนัก ข้าคงไปทันทีที่ทำได้", variants = { { "42:864259708:463981160 N 344:79610178:1498782271", "ถึงเวลาเจ้าไป Stormwind {name} High Priest Rohan ใน Hall of Mysteries อยากคุยด้วย ต้องมีเรื่องดีมากหรือแย่มากแน่ เขาถึงอยากพบด้วยตนเอง แต่ข้าเดาว่าเจ้าทำดีมาตลอด คงเป็นเรื่องดีที่เขาอยากคุย\n\nอย่าเสียเวลาแถวนี้มากนัก ข้าคงไปทันทีที่ทำได้\n\nหมายเหตุผู้แปล: ฉบับนี้เอ่ย Stormwind ในคำอธิบาย แต่เป้าหมายในแคชเดียวกันระบุ Ironforge โปรดเทียบกับตำแหน่งผู้รับที่เกมแสดง" } } },
        completion = { "25:2089692431:1019187282 N 228:819820501:896419647", "ข้ายินดีที่เจ้ามาถึง {name} เรามีเรื่องต้องคุยมากมาย แต่ที่สำคัญกว่าคือการฝึกวิถีแสงสว่างของเจ้า\n\nมีบทเรียนที่ผู้รับใช้แสงสว่างทุกคนต้องเรียน หากพร้อม เราจะเริ่มคุยเรื่องเหล่านั้นกันตอนนี้", variants = { { "25:2089692431:1019187282 N 125:1908894041:1066349688", "ข้ายินดีที่เจ้ามาถึง {name} เจ้าได้พิสูจน์แล้วว่าคู่ควรกับการฝึกขั้นต่อไป รับบทเรียนนี้ไว้แทนคำขอบคุณสำหรับทุกสิ่งที่เจ้าทำเถอะ" } } },
    },
    [5638] = { -- Desperate Prayer
        title = { "16:1434986297:2032252961", "คำภาวนายามสิ้นหวัง" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind", variants = { { "40:1954887690:1611417486", "คุยกับ High Priest Rohan ใน Ironforge" } } },
        description = { "69:974748309:1386129621 R 319:552991150:2111368082 R 1:46:46", "ไม่นานมานี้นักบวชของเจ้าคนหนึ่งมาตามหา {race} เขาบอกว่าหากข้าเห็นเจ้า ให้ชี้ทางไป Cathedral of Light บอกว่าสำคัญมาก แต่หากเป็นข้า คงไม่กังวลเกินไป ท่าทีเขาดูดี... ราวกับเป็นข่าวดี หากเป็นข้าคงไม่ชักช้าเดินทางไป\n\nขอ Elune สถิตกับเจ้า {race}ผู้มีไมตรี", variants = { { "69:974748309:1386129621 R 318:1262829189:739591879 R 1:46:46", "ไม่นานมานี้นักบวชของเจ้าคนหนึ่งมาตามหา {race} เขาบอกว่าหากข้าเห็นเจ้า ให้ชี้ทางไป Hall of Mysteries บอกว่าสำคัญมาก แต่หากเป็นข้า คงไม่กังวลเกินไป ท่าทีเขาดูดี... ราวกับเป็นข่าวดี หากเป็นข้าคงไม่ชักช้าเดินทางไป\n\nขอ Elune สถิตกับเจ้า {race}ผู้มีไมตรี" } } },
        completion = { "25:2089692431:1019187282 N 228:819820501:896419647", "ข้ายินดีที่เจ้ามาถึง {name} เรามีเรื่องต้องคุยมากมาย แต่ที่สำคัญกว่าคือการฝึกวิถีแสงสว่างของเจ้า\n\nมีบทเรียนที่ผู้รับใช้แสงสว่างทุกคนต้องเรียน หากพร้อม เราจะเริ่มคุยเรื่องเหล่านั้นกันตอนนี้", variants = { { "25:2089692431:1019187282 N 228:1557771026:860677750", "ข้ายินดีที่เจ้ามาถึง {name} เรามีเรื่องต้องคุยกันมากมาย แต่สิ่งสำคัญที่สุดคือการฝึกฝนวิถีแห่งแสงสว่างของเจ้า\n\nมีบทเรียนที่ผู้รับใช้แสงสว่างทุกคนต้องเรียนรู้ หากเจ้าพร้อม เราจะเริ่มพูดคุยเรื่องบทเรียนเหล่านั้นกันตอนนี้" } } },
    },
    [5639] = { -- Desperate Prayer
        title = { "16:1434986297:2032252961", "คำภาวนายามสิ้นหวัง" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind" },
        description = { "28:1954922019:1918898949 N 331:1316440288:1152709634 N 1:46:46", "Stormwind ต้องการเจ้า {name} มหานักบวชหญิง Laurena ที่นั่นบอกว่า ถึงเวลาพิสูจน์ว่าคู่ควรกับการฝึกขั้นต่อไป อย่าเสียเวลาหาทางไปมากนัก พบนางได้ใน Cathedral of Light กลางเมือง ฝากความนับถือจากข้า และพิสูจน์ให้เห็นว่าเจ้าคู่ควรกับหน้าที่เช่นนี้เพียงใด ขอแสงสว่างสถิตกับเจ้า {name}" },
        completion = { "25:2089692431:1019187282 N 228:819820501:896419647", "ข้ายินดีที่เจ้ามาถึง {name} เรามีเรื่องต้องคุยมากมาย แต่ที่สำคัญกว่าคือการฝึกวิถีแสงสว่างของเจ้า\n\nมีบทเรียนที่ผู้รับใช้แสงสว่างทุกคนต้องเรียน หากพร้อม เราจะเริ่มคุยเรื่องเหล่านั้นกันตอนนี้" },
    },
    [5640] = { -- Desperate Prayer
        title = { "16:1434986297:2032252961", "คำภาวนายามสิ้นหวัง" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind", variants = { { "40:1389828707:2131752886", "คุยกับ High Priest Rohan ใน Stormwind" } } },
        description = { "39:1677350494:1562927690 N 273:2055097521:1631470866", "สรรเสริญ Elune และแสงสว่างของเจ้า {name}\n\nช่วงนี้หลายคนในคณะเราจะเรียนความสามารถที่สะท้อนศรัทธาใน Elune หากข้าจำไม่ผิด คณะเจ้าก็คงเช่นกัน\n\nเมื่อเสร็จธุระใน Darnassus ข้าคงไปหามหานักบวชหญิงของเจ้าสักคนเพื่อฝึกต่อ", variants = { { "39:1677350494:1562927690 N 269:1285346328:806334501", "สรรเสริญ Elune และแสงสว่างของเจ้า {name}\n\nช่วงนี้หลายคนในคณะเราจะเรียนความสามารถที่สะท้อนศรัทธาใน Elune หากข้าจำไม่ผิด คณะเจ้าก็คงเช่นกัน\n\nเมื่อเสร็จธุระใน Darnassus ข้าคงไปหามหานักบวชชายของเจ้าสักคนเพื่อฝึกต่อ" } } },
        completion = { "25:2089692431:1019187282 N 228:819820501:896419647", "ข้ายินดีที่เจ้ามาถึง {name} เรามีเรื่องต้องคุยมากมาย แต่ที่สำคัญกว่าคือการฝึกวิถีแสงสว่างของเจ้า\n\nมีบทเรียนที่ผู้รับใช้แสงสว่างทุกคนต้องเรียน หากพร้อม เราจะเริ่มคุยเรื่องเหล่านั้นกันตอนนี้" },
    },
    [5641] = { -- A Lack of Fear
        title = { "14:1485278402:2029973903", "ไร้ความหวาดกลัว", variants = { { "8:1902992789:2135747247", "ลงทัณฑ์" } } },
        completion = { "34:1480677558:461499999 C 2:11340:5796 N 126:1449256252:1786031896", "เจ้ามีแววเป็น{class}ผู้ยิ่งใหญ่ {name} ทำดีต่อไป!\n\nเจ้าพิสูจน์แล้วว่าพร้อมรบ บางทีถึงเวลาสอนอะไรเพิ่มเติมบ้าง" },
    },
    [5642] = { -- Shadowguard
        title = { "11:1628357179:1036862649", "ผู้พิทักษ์เงา" },
        objective = { "29:1109543802:1767790034", "คุยกับ Ur'kyo ใน Orgrimmar" },
        description = { "40:1877641691:1226741081 N 244:681330545:90173255", "มีเรื่องสำคัญใน Orgrimmar {name}\n\nปกติผู้ส่งสารที่ผ่านมาตามหานักบวชโทรลล์จะสบาย ๆ แต่ครั้งนี้ดูรีบร้อนกว่ามาก อย่าชักช้าใน Thunder Bluff ข้าคงกลับ Valley of Spirits โดยเร็วที่สุด" },
        completion = { "133:904636914:523851185", "พิธีของเจ้าจะมาถึงในไม่ช้า ตอนนี้ข้าจะสอนเวทที่มีประโยชน์มากเมื่อต่อสู้ศัตรู" },
    },
    [5643] = { -- Shadowguard
        title = { "11:1628357179:1036862649", "ผู้พิทักษ์เงา" },
        objective = { "29:1109543802:1767790034", "คุยกับ Ur'kyo ใน Orgrimmar" },
        description = { "346:603561497:1863147755", "เช่นเดียวกับนักบวชหลายคนของเรา เผ่าเจ้ามีพิธีผ่านวัย พิธีเหล่านี้มักสอนความสามารถพิเศษที่จำเป็นต่อการอยู่รอด ข้าสัมผัสว่าเวลานั้นมาถึงเจ้าแล้วแม้ขณะเราคุย เจ้าต้องกลับ Valley of Spirits ใน Orgrimmar แล้วคุยกับ Ur'kyo สิ่งที่เขาสอนอาจสำคัญต่ออนาคตมาก" },
        completion = { "133:904636914:523851185", "พิธีของเจ้าจะมาถึงในไม่ช้า ตอนนี้ข้าจะสอนเวทที่มีประโยชน์มากเมื่อต่อสู้ศัตรู" },
    },
    [5644] = { -- Devouring Plague
        title = { "16:2021450309:1250193794", "โรคระบาดกลืนกิน", variants = { { "14:1675294638:869685478", "บูชายัญแห่งความมืด" } } },
        objective = { "38:1042132235:1799646349", "คุยกับ Aelthalyste ใน Undercity" },
        description = { "29:927197036:411846721 N 370:1210000751:1980828299 N 46:740761418:1732511270", "อา วันนี้วิเศษสำหรับเจ้า {name} ดูจากบทเรียนที่ผ่าน ถึงเวลาส่งเจ้ากลับไป Aelthalyste มีสิ่งที่นางคนเดียวสอนได้ และต้องพิสูจน์ว่าคู่ควรด้วย\n\nข้าจะไม่ทำลายความประหลาดใจ แต่จำได้ตอนยังเป็นนักบวชรุ่นเยาว์เรียนเรื่องพลังแท้จริง... พลังศักดิ์สิทธิ์ ใช่ วันเหล่านั้น\n\nกลับไปหา Aelthalyste ใน Undercity {name} นางจะรอใน War Quarter" },
        completion = { "65:1147678628:944387529 N 113:2120478390:1140138715", "ข้าจะสอน Devouring Plague หากเจ้ารู้สึกพร้อม {name} มันเป็นเวททรงพลังไม่น้อยที่จะช่วยในการรบเบื้องหน้า จงฝึกใช้ ภายหลังจะมีบททดสอบ", variants = { { "83:1941081975:1075526535 N 75:908507977:529242140", "ดีที่เจ้ากลับมาทันเวลา เรามีเรื่องสำคัญต้องคุยกัน {name} เจ้ากำลังแข็งแกร่งขึ้น และเราต้องแน่ใจว่าเจ้าพร้อม" } } },
    },
    [5645] = { -- A Lack of Fear
        title = { "14:1485278402:2029973903", "ไร้ความหวาดกลัว", variants = { { "8:1902992789:2135747247", "ลงทัณฑ์" } } },
        objective = { "40:1954887690:1611417486", "คุยกับ High Priest Rohan ใน Ironforge" },
        description = { "N 357:970497713:1517573219", "{name} High Priest Rohan ของเจ้าอยากพบที่ Ironforge รีบเถอะ สหายผู้แข็งแกร่ง บททดสอบต่อไปใกล้มาถึง แม้ข้าอยากเห็นพิธีพิเศษของเผ่าเจ้า แต่ที่ของข้าอยู่ที่นี่ ขอแสงสว่างร่วมเดินทางกับเจ้า เมื่อถึงเมือง Rohan คงยังอยู่ใน Mystic Ward เขาจะรอ" },
        completion = { "24:1516693862:1606504120 N 156:461522512:1371174373", "ดีแล้วที่เจ้ามา {name} เผ่าพันธุ์เราภาคภูมิและแข็งแกร่ง ถึงเวลาเจ้าเรียนไม่เพียงเป็นเช่นนั้นเอง แต่จุดประกายความรู้สึกและความมั่นใจแบบนั้นในผู้อื่น พร้อมไหม เจ้าหนู?" },
    },
    [5646] = { -- Devouring Plague
        title = { "16:2021450309:1250193794", "โรคระบาดกลืนกิน", variants = { { "14:1675294638:869685478", "บูชายัญแห่งความมืด" } } },
        objective = { "38:1042132235:1799646349", "คุยกับ Aelthalyste ใน Undercity" },
        description = { "154:2005443797:409469977 N 125:481142001:1482540259", "Aelthalyste ให้เกียรติผู้คนเราอย่างมาก ส่งกลับมาหาข้าเพื่อฝึกต่อ ตอนนี้ข้าจึงทำเช่นเดียวกันแก่เผ่านาง\n\nกลับ Undercity {name} ที่ War Quarter นางพร้อมสอนเรื่องผู้คนกับวิถีของเจ้าเพิ่ม ไปเถอะ อย่าชักช้า" },
        completion = { "83:1941081975:1075526535 N 75:908507977:529242140", "ดี เจ้ากลับมาแล้ว ไม่ช้าเกินไปแม้แต่น้อย เรามีเรื่องยิ่งใหญ่ต้องคุย {name} ความสามารถเจ้าแข็งแกร่งขึ้น และเราต้องให้แน่ใจว่าพร้อม" },
    },
    [5647] = { -- A Lack of Fear
        title = { "14:1485278402:2029973903", "ไร้ความหวาดกลัว", variants = { { "8:1902992789:2135747247", "ลงทัณฑ์" } } },
        objective = { "40:1954887690:1611417486", "คุยกับ High Priest Rohan ใน Ironforge" },
        description = { "29:1979820714:240448472 N 435:1559305148:1181607050", "เผ่าพันธุ์เจ้าแข็งแกร่งนัก {name} เราภูมิใจที่เรียกเจ้าว่าพันธมิตร ทุกครั้งที่ตะวันลับ เจ้าและญาติพี่น้องใกล้ค้นพบต้นกำเนิดแท้จริงยิ่งขึ้น พร้อมมั่นใจว่าเดินถูกทางในหลายเรื่อง ความรู้สึกนั้นคงทำให้เปี่ยมชัยชนะ\n\nเพิ่งมีข่าวจาก Ironforge ขอให้กลับไปคุยกับ High Priest Rohan ใน Mystic Ward ข้าคงไม่ให้เขารอนาน ขอ Elune นำทางการเดินทางเจ้า" },
        completion = { "34:1480677558:461499999 C 2:11340:5796 N 25:639352636:2115876148 N 101:1982229928:901429802", "เจ้ามีแววเป็น{class}ผู้ยิ่งใหญ่ {name} ทำดีต่อไป!\n{name} เจ้าพิสูจน์แล้วว่าพร้อมรบ บางทีถึงเวลาสอนอะไรเพิ่มเติมบ้าง" },
    },
    [5648] = { -- Garments of Spirituality
        title = { "24:2034035444:569740134", "อาภรณ์แห่งจิตวิญญาณ" },
        objective = { "151:1844650317:247692417", "หา Grunt Kor'ja แล้วรักษาบาดแผลด้วย Lesser Heal (Rank 2) จากนั้นมอบ Power Word: Fortitude ให้นาง แล้วกลับไปหา Tai'jin ที่ Razor Hill" },
        description = { "34:1395174710:1049648811 N 373:316898699:1993975668", "เจ้าพร้อมทดสอบครั้งแรกแล้ว {name} ทางใต้ของ Razor Hill เพิ่งพ้นเมืองไป มีทหาร Grunt ของเราบาดเจ็บจากการสู้ทหารเก่าของ Proudmoore นางอาการไม่ดีนัก และคงได้ประโยชน์มากหากคนอย่างเราช่วย หาให้พบ นางชื่อ Kor'ja รักษาบาดแผลแล้วมอบพรบรรพชน\n\nทำได้แล้ว ข้าว่าก็พอพิสูจน์ว่าเจ้าพร้อมก้าวต่อในวิถีเรา" },
        progress = { "369:1383707007:2016331435", "คนส่วนใหญ่เห็นว่าเวทรักษาทรงพลัง แต่ไม่กี่คนเข้าใจว่าทรงพลังเพียงใด เจ้าคงชีวิตคนมากมายไว้ได้ แทนที่จะส่งพวกเขาไปพบบรรพชน เวทรักษาคู่กับ Fortitude เป็นการผสานเวทที่ทรงพลังมาก จงจำไว้ มีประโยชน์ต่อคนทุกแบบ ทั้งนักรบ จอมเวท และทุกคนระหว่างนั้น" },
        completion = { { "260:516012079:383521012 N 113:236647219:1586076583", "260:516012079:383521012 N 112:701249351:996592820" }, "ดี Kor'ja จึงรอดและออกไปปกป้องเมืองจากมนุษย์มุ่งร้าย ข้ามักหวนนึกวันรบ เมื่อพลังปรากฏในการต่อสู้ และผู้มีปัญญามักทำลายคนที่พึ่งแต่กำลัง\n\nเจ้าทำให้ข้าได้ดี {name} รับเสื้อคลุมไป บางทีมันช่วย บางทีเจ้าไม่ใส่ใจ แต่เจ้าคู่ควรแล้ว และข้าภูมิใจที่เรียกว่าเป็นพี่น้อง" },
        steps = { { "29:1134755864:1760975328", "รักษาและเสริมพลังให้ Grunt Kor'ja" } },
    },
    [5649] = { -- In Favor of Spirituality
        title = { "24:1574157487:448536512", "ในความโปรดปรานของเหล่าวิญญาณ" },
        objective = { "28:1412554836:903800147", "คุยกับ Tai'jin ใน Durotar" },
        description = { "443:1516483236:1509858269", "ใช่แล้ว เพื่อน พวกเราเข้าร่วม Horde เพราะพวกเขาดีต่อเรา ภักดีและสอนเรื่องต่าง ๆ อย่างเกียรติยศให้มาก แต่วิถีเก่าทิ้งยาก ออร์คอาจไม่เห็นด้วยกับทุกประเพณี แต่นั่นไม่ได้หมายความว่าเราแอบสืบทอดบางอย่างไม่ได้\n\nเจ้ารู้เรื่องนี้ ข้าจึงส่งไปหา Tai'jin ใน Razor Hill นางจะสอนประวัติและวิถีเผ่าเราเพิ่ม ไปหาเมื่อพร้อม" },
        completion = { "433:92087921:136674585", "อา... ในที่สุดก็มาหา Tai'jin ดีแล้ว\n\nเจ้ารู้ว่าเราไม่ใช่เผ่าเดิมที่เคยร่วมกับ Horde ตอนนี้แข็งแกร่งกว่ามาก เพราะเราปรับตัว Horde สอนเราเช่นนั้น เราไม่ปราบศัตรูแล้วรับพลังจากพวกมันอีก ตอนนี้เราสร้างพลัง แล้วจึงปราบศัตรู\n\nความต่างละเอียดอ่อน แต่เจ้าจะเรียนรู้ จะเห็น เผ่าหวังให้เจ้าเรียนเรื่องเช่นนี้" },
    },
    [5650] = { -- Garments of Darkness
        title = { "20:1130095059:767792448", "อาภรณ์แห่งความมืด" },
        objective = { "158:781057092:1431949877", "หา Deathguard Kel แล้วรักษาบาดแผลด้วย Lesser Heal (Rank 2) จากนั้นมอบ Power Word: Fortitude ให้เขา แล้วกลับไปหา Dark Cleric Beryl ใน Brill" },
        description = { "42:975036069:1906637068 N 463:50655430:781062995", "พลังเรามาจากความมืดและเงา {name} แต่นั่นไม่ใช่บทบาทเดียว เจ้ารู้ว่าศิลปะรักษามีคุณค่า นั่นฉลาดนัก แต่ก่อนรู้จักความมืด เจ้าต้องรู้จักแสงด้วย ข้าจึงมีบททดสอบ\n\nเหนือสุสานมี Deathguard บาดเจ็บชื่อ Kel เขาปกป้องเราจากโนลล์มาระยะหนึ่งและต้องการรักษา แต่เจ้าต้องเสริมร่างกายก่อนเขากลับทำหน้าที่ด้วย ใช้เวททำทั้งสองอย่างแล้วกลับมาหาข้า" },
        progress = { "49:263543902:10745792 N 246:839818088:777791746 C 149:573367169:434922437", "พลังเราเหมาะกับสถานการณ์มากมาย {name} แต่ไม่ว่าอย่างไร ความสามารถรักษาบาดแผลและทำให้สหายทนรับความเสียหายได้มากขึ้นจะเป็นพรสวรรค์ที่ต้องการมากที่สุดเสมอ อย่าให้เรื่องนั้นขวางการแสวงหาวิถีอื่นในฐานะ{class} เจ้าทำประโยชน์ได้หลายแบบ แต่... หากต้องการทำลายศัตรูด้วยพลังเวทจริง ๆ บางทีอาร์เคนอาจถูกใจกว่า" },
        completion = { "153:298865014:44097100 C 251:1113266771:1712277542", "เจ้าผ่านการทดสอบง่ายดาย ดี\n\nอีกไม่นานจะพร้อมรับผิดชอบมากขึ้น และเส้นทางนั้นนำไปสู่พลังมืดกว่า พลังที่{class}เผ่าอื่นไม่มี\n\nรับเสื้อคลุมเป็นสัญลักษณ์ฐานะ เจ้าคู่ควรแล้ว หากไม่อยากสวมก็ตามใจ จัดการมันได้ตามต้องการ ข้าและพวกเราจะยอมรับสิ่งที่เจ้าทำสำเร็จในคณะเสมอ", variants = { { "413:230412313:1713056605", "เจ้าผ่านการทดสอบง่ายดาย ดี\n\nอีกไม่นานจะพร้อมรับผิดชอบมากขึ้น และเส้นทางนั้นนำไปสู่พลังมืดกว่า พลังที่นักบวชหญิงเผ่าอื่นไม่มี\n\nรับเสื้อคลุมเป็นสัญลักษณ์ฐานะ เจ้าคู่ควรแล้ว หากไม่อยากสวมก็ตามใจ จัดการมันได้ตามต้องการ ข้าและพวกเราจะยอมรับสิ่งที่เจ้าทำสำเร็จในคณะเสมอ" } } },
        steps = { { "31:1673522709:1641330907", "รักษาและเสริมพลังให้ Deathguard Kel" } },
    },
    [5651] = { -- In Favor of Darkness
        title = { "20:795459266:1246033782", "ในความโปรดปรานของความมืด" },
        objective = { "46:1827480259:1340951597", "คุยกับ Dark Cleric Beryl ใน Tirisfal Glades" },
        description = { "497:1193804563:153304237", "Forsaken เรียนรู้หลายบทจากประสบการณ์ เป็นสิ่งที่บางเผ่าเพิ่งเริ่มเข้าใจ แม้เส้นทางเราอยู่ในความมืด เจ้าจะพบว่าหลายสิ่งพึ่งทั้งแสงและมืด บทเรียนจะสอนใช้ทั้งคู่... อย่างมีวิจารณญาณ แต่จำคำข้าไว้ อย่าลืมว่าเราถูกหล่อหลอมในความแปดเปื้อนและทิ้งให้เน่าดุจซาก ความมืดคือบ้านเรา\n\nไปหา Dark Cleric Beryl ใน Brill เมื่อพร้อมเรียนเพิ่ม" },
        completion = { "154:1305400055:571205178", "ในที่สุดก็มาถึง ศรัทธาอย่างเดียวไม่ทำให้เจ้าผ่านบททดสอบเบื้องหน้าหรอก ผู้เยาว์ ความรู้จักเร่งมือและความทะเยอทะยานจะช่วยด้วย" },
    },
    [5652] = { -- Hex of Weakness
        title = { "15:1398200648:851493900", "คำสาปแห่งความอ่อนแอ" },
        completion = { "202:1426966372:1221821703", "เจ้าควรตั้งใจบทเรียนนี้ให้ดี ผู้เยาว์ Hex of Weakness จะช่วยเจ้าอย่างมากในการรบ ภายหลังข้าจะมีบททดสอบให้พัฒนาตนและพิสูจน์ความคู่ควรต่อเผ่า" },
        objective = { "29:1109543802:1767790034", "ไปคุยกับ Ur'kyo ใน Orgrimmar" },
        description = { "64:1740553551:232552505 N 215:1571978452:469656031", "ข้าถูกส่งมาคอยดูไม่ให้เจ้าเตลิดไปไกลบ้านนัก {name} พวกเขาให้ข้ามาตามเจ้ากลับ เพราะ Ur'kyo ผู้ยิ่งใหญ่ที่สุดในหมู่นักบวชของเราอยากคุยกับเจ้า ไปเสีย ไปที่ Valley of Spirits ในเมืองของพวกออร์คแล้วคุยกับ Ur'kyo เขารอเจ้าอยู่เดี๋ยวนี้" },
    },
    [5654] = { -- Hex of Weakness
        title = { "15:1398200648:851493900", "คำสาปแห่งความอ่อนแอ" },
        objective = { "29:1109543802:1767790034", "คุยกับ Ur'kyo ใน Orgrimmar" },
        description = { "40:667878250:1998586623 N 207:1732736275:1152867682", "ถึงเวลาพบ Ur'kyo {name} เขาอยู่ Valley of Spirits ในเมืองออร์ค ไปคุยกับเขา ถึงเวลาเรียนวิถีเก่าของผู้คนเราเพิ่ม ถึงเวลาเข้าวงและเป็นนักบวชที่แท้จริงของเผ่า" },
        completion = { "202:1426966372:1221821703", "เจ้าควรตั้งใจบทเรียนนี้ให้ดี ผู้เยาว์ Hex of Weakness จะช่วยเจ้าอย่างมากในการรบ ภายหลังข้าจะมีบททดสอบให้พัฒนาตนและพิสูจน์ความคู่ควรต่อเผ่า", variants = { { "70:1569167740:1833267704", "อา ดีแล้วที่เจ้ามา ถึงเวลาเริ่มฝึกตามวิถีดั้งเดิมของเราเสียที" } } },
    },
    [5655] = { -- Hex of Weakness
        title = { "15:1398200648:851493900", "คำสาปแห่งความอ่อนแอ" },
        objective = { "29:1109543802:1767790034", "คุยกับ Ur'kyo ใน Orgrimmar" },
        description = { "64:1740553551:232552505 N 214:580412305:2054022116", "ข้าถูกส่งมาให้แน่ใจว่าเจ้าไม่ไกลบ้านเกินไป {name} พวกเขาให้ข้าดูว่าเจ้าจะกลับบ้าน เพราะ Ur'kyo นักบวชผู้ยิ่งใหญ่ที่สุดของเราอยากคุยด้วย จงไป Valley of Spirits ในเมืองออร์ค คุยกับ Ur'kyo เขารออยู่ตอนนี้" },
        completion = { "202:1426966372:1221821703", "เจ้าควรตั้งใจบทเรียนนี้ให้ดี ผู้เยาว์ Hex of Weakness จะช่วยเจ้าอย่างมากในการรบ ภายหลังข้าจะมีบททดสอบให้พัฒนาตนและพิสูจน์ความคู่ควรต่อเผ่า", variants = { { "70:1569167740:1833267704", "อา ดี เจ้ามาถึงแล้ว ทีนี้เราก็เริ่มฝึกฝนวิถีดั้งเดิมของเราได้" } } },
    },
    [5656] = { -- Hex of Weakness
        title = { "15:1398200648:851493900", "คำสาปแห่งความอ่อนแอ" },
        objective = { "29:1109543802:1767790034", "คุยกับ Ur'kyo ใน Orgrimmar" },
        description = { "202:2014940705:1205352158 N 113:1708398098:814948111", "หัวใจอมตะของข้าอบอุ่นเสมอเมื่อเห็นนักบวชทุกวัฒนธรรมออกเที่ยวโลก ได้รู้ว่ามีพลังที่ไม่ใช่อาร์เคนและอยู่ในมือเราจริง ๆ ข้าจึงรู้สึกเป็นเกียรติที่ได้ชี้ทางกลับบ้าน {name}\n\nUr'kyo นักบวชผู้ยิ่งใหญ่ของเจ้าใน Orgrimmar ขอให้ไปพบ เขาอยู่ใน Valley of Spirits" },
        completion = { "202:1426966372:1221821703", "เจ้าควรตั้งใจบทเรียนนี้ให้ดี ผู้เยาว์ Hex of Weakness จะช่วยเจ้าอย่างมากในการรบ ภายหลังข้าจะมีบททดสอบให้พัฒนาตนและพิสูจน์ความคู่ควรต่อเผ่า" },
    },
    [5657] = { -- Hex of Weakness
        title = { "15:1398200648:851493900", "คำสาปแห่งความอ่อนแอ" },
        objective = { "29:1109543802:1767790034", "คุยกับ Ur'kyo ใน Orgrimmar" },
        description = { "25:572482394:1888095310 R 184:1033379116:83529942", "บ้าน กลับบ้านเถอะ {race}รุ่นเยาว์\n\nUr'kyo ผู้นำจิตวิญญาณขอให้เจ้ากลับไปคุยเรื่องเส้นทางที่เดิน\n\nไป Valley of Spirits ในมหานคร Orgrimmar ของ Horde เจ้าจะพบเขาที่นั่น" },
        completion = { "202:1426966372:1221821703", "เจ้าควรตั้งใจบทเรียนนี้ให้ดี ผู้เยาว์ Hex of Weakness จะช่วยเจ้าอย่างมากในการรบ ภายหลังข้าจะมีบททดสอบให้พัฒนาตนและพิสูจน์ความคู่ควรต่อเผ่า", variants = { { "70:1569167740:1833267704", "อา ดี เจ้ามาถึงแล้ว ทีนี้เราก็เริ่มฝึกฝนวิถีดั้งเดิมของเราได้" } } },
    },
    [5658] = { -- Touch of Weakness
        title = { "17:1181411933:1859400161", "สัมผัสแห่งความอ่อนแอ" },
        completion = { "10:179830513:380461342 C 113:1803735648:691060818", "อา {class}รุ่นเยาว์ ยินดีที่เจ้ากลับมา ข้าจะสอนบทเรียนที่ไม่ควรลืม พร้อมหรือยัง?", variants = { { "132:977706793:54969217", "อา นักบวชหญิงรุ่นเยาว์ ข้าดีใจที่เจ้ากลับมา ข้าจะสอนบทเรียนที่เจ้าควรจดจำไว้ พร้อมหรือยัง" } } },
        objective = { "38:1042132235:1799646349", "ไปคุยกับ Aelthalyste ใน Undercity" },
        description = { "22:1222342992:1994413365 C 303:1838181763:1031884488", "เจ้ามาไกลบ้านนะ {class} ที่เมืองใต้ดินของเจ้ายังต้องการเจ้าอยู่ อาจารย์หญิงของเจ้าที่เรียกกันว่า Aelthalyste ต้องการให้เจ้ากลับไป เช่นเดียวกับเผ่าข้า มีบางอย่างที่เจ้าต้องเรียนจากนางเท่านั้น อย่าอยู่ที่นี่นานนัก รีบไปยัง War Quarter ให้เร็วเท่าที่เรือเหาะจะพาเจ้าไปได้" },
    },
    [5660] = { -- Touch of Weakness
        title = { "17:1181411933:1859400161", "สัมผัสแห่งความอ่อนแอ" },
        objective = { "38:1042132235:1799646349", "คุยกับ Aelthalyste ใน Undercity" },
        description = { "22:1222342992:1994413365 C 303:1838181763:1031884488", "เจ้าอยู่ไกลบ้าน {class} ที่นั่นต้องการเจ้า กลับไปยังเมืองใต้ดินของเจ้า นายหญิงที่เรียกว่า Aelthalyste ต้องการให้กลับ เช่นเดียวกับเผ่าข้า มีสิ่งที่เจ้าต้องเรียนจากนางเท่านั้น อย่าอยู่ที่นี่นาน ควรมุ่งไป War Quarter ให้เร็วเท่าที่เรือเหาะจะพาไปได้" },
        completion = { "238:1296789206:201874201", "อา ดี มาอีกคนแล้ว เวลาอาจไม่สำคัญต่อข้า แต่สำหรับเจ้ามันมีค่าอย่างยิ่ง เจ้ามีเรื่องเรียนมาก และข้าอยากสอนมาก เพียงพิสูจน์ความคู่ควร ทำได้แล้วรางวัลจะยิ่งใหญ่" },
    },
    [5661] = { -- Touch of Weakness
        title = { "17:1181411933:1859400161", "สัมผัสแห่งความอ่อนแอ" },
        objective = { "38:1042132235:1799646349", "คุยกับ Aelthalyste ใน Undercity" },
        description = { "56:2082718799:1661764745 N 303:682916600:1516897456", "เจ้าอยู่ Bloodhoof Village ไกลบ้านนัก {name} ข้าถูกส่งมาตามหานักบวชเผ่าตัวเองเพื่อให้กลับไปคุยกับผู้นำ แต่นั่นไม่ได้หมายความว่าข้าช่วยเจ้าไม่ได้\n\nได้ข่าวว่าวิญญาณมหานักบวชหญิงของเจ้าอยากให้ Forsaken ทุกคนไปหา มีสิ่งที่เจ้าต้องเรียน\n\nไปพบ Aelthalyste ใน War Quarter ของเมืองเจ้า" },
        completion = { "238:1296789206:201874201", "อา ดี มาอีกคนแล้ว เวลาอาจไม่สำคัญต่อข้า แต่สำหรับเจ้ามันมีค่าอย่างยิ่ง เจ้ามีเรื่องเรียนมาก และข้าอยากสอนมาก เพียงพิสูจน์ความคู่ควร ทำได้แล้วรางวัลจะยิ่งใหญ่" },
    },
    [5662] = { -- Touch of Weakness
        title = { "17:1181411933:1859400161", "สัมผัสแห่งความอ่อนแอ" },
        objective = { "38:1042132235:1799646349", "คุยกับ Aelthalyste ใน Undercity" },
        description = { "33:1130307011:1619054741 N 283:541434350:2106325997", "ข้านับถือเจ้าและผู้คนของเจ้า {name} ปกติข้าสอนเฉพาะคนเผ่าตน บทเรียนของเจ้ามาจาก Aelthalyste ในเมืองที่ครั้งหนึ่งเรียกว่า Lordaeron\n\nควรกลับไปหานาง หากจะเรียนความสามารถที่แยกเจ้าจากศรัทธาอื่น\n\nไป War Quarter ใน Undercity แล้วหานายหญิงที่นั่น" },
        completion = { "238:1296789206:201874201", "อา ดี มาอีกคนแล้ว เวลาอาจไม่สำคัญต่อข้า แต่สำหรับเจ้ามันมีค่าอย่างยิ่ง เจ้ามีเรื่องเรียนมาก และข้าอยากสอนมาก เพียงพิสูจน์ความคู่ควร ทำได้แล้วรางวัลจะยิ่งใหญ่" },
    },
    [5663] = { -- Touch of Weakness
        title = { "17:1181411933:1859400161", "สัมผัสแห่งความอ่อนแอ" },
        objective = { "38:1042132235:1799646349", "คุยกับ Aelthalyste ใน Undercity" },
        description = { "272:630939323:226568596", "Aelthalyste ส่งข่าวถึงนักบวชทุกคนของนาง ให้เราส่งสมาชิกอายุน้อยในคณะไป Undercity เพื่อฝึกเพิ่ม หากเจ้านับตัวเองในหมู่ผู้มีศรัทธาจริง ก็ควรกลับเช่นกัน\n\nพบ Aelthalyste ได้ใน War Quarter ลึกใน Undercity" },
        completion = { "238:1296789206:201874201", "อา ดี มาอีกคนแล้ว เวลาอาจไม่สำคัญต่อข้า แต่สำหรับเจ้ามันมีค่าอย่างยิ่ง เจ้ามีเรื่องเรียนมาก และข้าอยากสอนมาก เพียงพิสูจน์ความคู่ควร ทำได้แล้วรางวัลจะยิ่งใหญ่" },
    },
    [5672] = { -- Elune's Grace
        title = { "13:781732272:2004283949", "พระกรุณาแห่ง Elune" },
        completion = { "200:892478050:1722346298", "ด้วยการอุทิศตนต่อ Elune และผู้คนเรา เจ้าบรรลุภาวะที่ไม่ใช่ทุกคนทำได้ ตามธรรมเนียม เราจึงสอนความสามารถยิ่งใหญ่ขึ้นตอบแทนความภักดี เจ้ายอมรับไหม?" },
        objective = { "40:751090212:719807644", "ไปคุยกับนักบวชหญิง Alathea ใน Darnassus" },
        description = { "26:981875768:884185089 N 355:1109815101:1942195552", "วันอันน่ายินดีมาถึงแล้ว {name} เจ้าโตพอที่เหล่านักบวชของเราจะได้ฝึกฝนความสามารถที่มีเพียงไนท์เอลฟ์เท่านั้นที่รู้จัก ส่วนผู้ที่จะฝึกเจ้าเป็นคนอื่น เมื่อเสร็จธุระที่นี่แล้ว จงรีบกลับไปยัง Temple of the Moon และคุยกับนักบวชหญิง Alathea นางจะทดสอบว่าเจ้าพร้อมหรือยัง เมื่อผ่านแล้วนางจึงจะสอน Elune's Grace ให้เจ้า" },
    },
    [5673] = { -- Elune's Grace
        title = { "13:781732272:2004283949", "พระกรุณาแห่ง Elune" },
        objective = { "40:751090212:719807644", "คุยกับ Priestess Alathea ใน Darnassus" },
        description = { "61:1583203991:1953791180 N 322:116928296:1642522672", "เจ้ารู้ว่าฝึกกับครูของเราได้ทุกเมื่อ {name} แต่มีบางสิ่งที่เราถ่ายทอดไม่ได้ หนึ่งในนั้นคือคำสอนของเทพี Elune ของเจ้า นางมอบความสามารถพิเศษแก่ผู้ศรัทธา หากข้าไม่ผิด ถึงเวลาเจ้ากลับ Temple of the Moon เพื่อรับบททดสอบ\n\nกลับเมื่อทำได้ แล้วคุยกับ Priestess Alathea" },
        completion = { "303:732761229:1677092683", "ขอ Elune อวยพรที่เจ้ากลับหาเรารวดเร็วเช่นนี้ นี่เป็นช่วงสำคัญของการฝึก เป็นเวลาที่ทุกคนในคณะจริงจังมาก เมื่อพักจากการเดินทางแล้วโปรดบอก เราจะคุยเรื่องฝึกต่อและเส้นทางที่จะนำเจ้าไปข้างหน้า" },
    },
    [5674] = { -- Elune's Grace
        title = { "13:781732272:2004283949", "พระกรุณาแห่ง Elune" },
        objective = { "40:751090212:719807644", "คุยกับ Priestess Alathea ใน Darnassus" },
        description = { { "26:981875768:884185089 N 338:945329455:214294585", "26:981875768:884185089 N 342:1584473117:2117523544" }, "วันวิเศษมาถึงแล้ว {name} เจ้าถึงวัยที่นักบวชของเราได้ฝึกความสามารถซึ่งมีเพียงไนต์เอลฟ์รู้จัก แต่ไม่ใช่ข้าที่จะฝึกให้ เมื่อเสร็จธุระที่นี่ จงกลับ Temple of the Moon แล้วคุยกับ Priestess Alathea นางจะทดสอบให้แน่ใจว่าพร้อม เมื่อนั้นจึงสอน Elune's Grace ให้" },
        completion = { "200:892478050:1722346298", "ด้วยการอุทิศตนต่อ Elune และผู้คนเรา เจ้าบรรลุภาวะที่ไม่ใช่ทุกคนทำได้ ตามธรรมเนียม เราจึงสอนความสามารถยิ่งใหญ่ขึ้นตอบแทนความภักดี เจ้ายอมรับไหม?", variants = { { "303:732761229:1677092683", "ขอให้ Elune อวยพรเจ้า ที่กลับมาหาพวกเราได้รวดเร็วเช่นนี้ นี่เป็นช่วงสำคัญในการฝึกฝนของเจ้า และเป็นช่วงที่ทุกคนในคณะของเราต่างให้ความสำคัญอย่างยิ่ง เมื่อเจ้าพักจากการเดินทางจนหายเหนื่อยแล้ว โปรดบอกข้า เราจะได้พูดคุยกันถึงการฝึกขั้นต่อไป และเส้นทางที่เจ้าจะก้าวเดินต่อจากนี้" } } },
    },
    [5675] = { -- Elune's Grace
        title = { "13:781732272:2004283949", "พระกรุณาแห่ง Elune" },
        objective = { "40:751090212:719807644", "คุยกับ Priestess Alathea ใน Darnassus" },
        description = { { "354:2044658836:1306152258", "355:1418500193:1297361042" }, "เวลาไม่รอใคร เจ้าหนู ถึงเวลากลับบ้านที่ Darnassus Priestess Alathea ส่งข่าวให้เจ้ากลับไปฝึก ดูเหมือนพวกเขาเห็นว่าพร้อมทดสอบ เช่นเดียวกับผู้รับใช้แสงสว่าง ควรออกเดินทางเมื่อทำได้ ข้อความ Alathea บอกว่าจะรอใน Temple of the Moon โชคดี" },
        completion = { "303:732761229:1677092683", "ขอ Elune อวยพรที่เจ้ากลับหาเรารวดเร็วเช่นนี้ นี่เป็นช่วงสำคัญของการฝึก เป็นเวลาที่ทุกคนในคณะจริงจังมาก เมื่อพักจากการเดินทางแล้วโปรดบอก เราจะคุยเรื่องฝึกต่อและเส้นทางที่จะนำเจ้าไปข้างหน้า" },
    },
    [5676] = { -- Arcane Feedback
        title = { "15:1096122489:1932291760", "ผลสะท้อนอาร์เคน" },
        completion = { "223:855122219:168547365", "เราจำต้องเรียนเวทบางอย่างเพื่อปกป้องตนจากสิ่งที่มักถูกเรียกว่าศัตรูใหญ่ที่สุด นั่นคืออาร์เคน\n\nข้าจะสอนเวทที่ช่วยให้เจ้าปกป้องตัวเองและสหายจากผู้ใช้พลังเช่นนั้น" },
        objective = { "45:1006910416:2105132205", "ไปคุยกับมหานักบวชหญิง Laurena ใน Stormwind" },
        description = { "457:433967877:150833233", "ถึงเวลากลับ Stormwind แล้ว ผู้เยาว์ อาจารย์ของเจ้าที่นั่นเรียกตัวเจ้ากลับไปฝึกต่อ แม้เรื่องนี้จะทำให้ข้ากังวลอยู่บ้าง แต่เผ่าของเจ้ากับเผ่าของข้าเป็นพันธมิตรกัน ข้าจะไม่ทรยศต่อไมตรีนั้น\n\nข้ามิได้ตั้งใจปิดบังกับเจ้าเช่นนี้ เพียงแต่ข้ายังไม่วางใจเวทอาร์เคนอยู่มาก ไม่ว่าจะมีที่มาจากพลังศักดิ์สิทธิ์หรือไม่ก็ตาม\n\nเมื่อกลับถึง Cathedral of Light แล้วเจ้าจะเข้าใจว่าข้าหมายถึงอะไร จงคุยกับมหานักบวชหญิง Laurena เมื่อไปถึง" },
    },
    [5677] = { -- Arcane Feedback
        title = { "15:1096122489:1932291760", "ผลสะท้อนอาร์เคน" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind" },
        description = { "145:983278644:2123760628 N 277:685027626:1395549528", "แม้ข้าอยากสอนคำสอนแสงสว่างพิเศษของเรา แต่นั่นไม่ใช่หน้าที่เรา ที่ของเจ้าอยู่กับคนเผ่าเดียวกันใน Stormwind {name}... อย่างน้อยตอนนี้ เชื่อเถอะ ข้าไม่ได้ตั้งใจลบหลู่ เมื่อกลับไปหา High Priestess Laurena ใน Cathedral of Light เจ้าจะเข้าใจ ถึงเวลาเผ่าของเจ้าต้องเตรียมอนาคตให้ แยกเจ้าจากคนอื่นที่เดินวิถีคล้ายกัน" },
        completion = { "31:639375376:756305980 N 363:649198030:1835535123", "อา เจ้ามาถูกจังหวะ {name} ข้าเริ่มสงสัยว่าผู้ส่งสารสำเร็จครบทุกคนไหม ยินดีที่เห็นว่าใช่ ไม่อย่างนั้นข้าคงพนันว่าเจ้ายังออกเรียนรู้ภัยต่าง ๆ ต่อผู้คนเราอยู่ข้างนอก\n\nพร้อมไหม? หมายถึงฝึกต่อ พลังเจ้าเพิ่มเร็วขึ้น และข้าเห็นว่าพร้อมเรียนศรัทธาเราเพิ่ม" },
    },
    [5678] = { -- Arcane Feedback
        title = { "15:1096122489:1932291760", "ผลสะท้อนอาร์เคน" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind" },
        description = { "457:433967877:150833233", "ถึงเวลากลับ Stormwind ผู้เยาว์ ผู้ใหญ่ของเจ้าเรียกกลับไปฝึกเพิ่ม แม้ข้าจะไม่สบายใจบ้าง แต่เผ่าเจ้าเป็นพันธมิตรเผ่าข้า ข้าไม่ทรยศสิ่งนั้น\n\nข้าไม่ได้ตั้งใจอ้อมค้อมกับเจ้า ความไม่ไว้ใจเวทอาร์เคนยังแข็งแรงในใจ ไม่ว่ามันจะมีแรงบันดาลใจจากเทพหรือไม่\n\nเมื่อกลับ Cathedral of Light เจ้าจะรู้ว่าข้าพูดอะไร คุยกับ High Priestess Laurena เมื่อถึง" },
        completion = { "31:639375376:756305980 N 363:649198030:1835535123", "อา เจ้ามาถูกจังหวะ {name} ข้าเริ่มสงสัยว่าผู้ส่งสารสำเร็จครบทุกคนไหม ยินดีที่เห็นว่าใช่ ไม่อย่างนั้นข้าคงพนันว่าเจ้ายังออกเรียนรู้ภัยต่าง ๆ ต่อผู้คนเราอยู่ข้างนอก\n\nพร้อมไหม? หมายถึงฝึกต่อ พลังเจ้าเพิ่มเร็วขึ้น และข้าเห็นว่าพร้อมเรียนศรัทธาเราเพิ่ม" },
    },
    [5679] = { -- Devouring Plague
        title = { "16:2021450309:1250193794", "โรคระบาดกลืนกิน", variants = { { "14:1675294638:869685478", "บูชายัญแห่งความมืด" } } },
        completion = { "65:1147678628:944387529 N 113:2120478390:1140138715", "ข้าจะสอน Devouring Plague หากเจ้ารู้สึกพร้อม {name} มันเป็นเวททรงพลังไม่น้อยที่จะช่วยในการรบเบื้องหน้า จงฝึกใช้ ภายหลังจะมีบททดสอบ", variants = { { "63:832170433:220556270 N 113:2120478390:1140138715", "ข้าจะสอน Dark Sacrifice หากเจ้ารู้สึกพร้อม {name} มันเป็นเวททรงพลังไม่น้อยที่จะช่วยในการรบเบื้องหน้า จงฝึกใช้ ภายหลังจะมีบททดสอบ" } } },
    },
    [5680] = { -- Shadowguard
        title = { "11:1628357179:1036862649", "ผู้พิทักษ์เงา" },
        completion = { "133:904636914:523851185", "พิธีของเจ้าจะมาถึงในไม่ช้า ตอนนี้ข้าจะสอนเวทที่มีประโยชน์มากเมื่อต่อสู้ศัตรู" },
        objective = { "28:1531655225:1724069899", "ไปคุยกับ Ur'kyo ใน Orgrimmar" },
        description = { "346:603561497:1863147755", "เช่นเดียวกับนักบวชคนอื่นของเรา คนในเผ่าของเจ้าก็ให้เจ้าผ่านพิธีเปลี่ยนผ่าน พิธีเหล่านี้มักสอนความสามารถพิเศษที่สำคัญต่อการเอาชีวิตรอดของนักบวช ข้ารู้สึกว่าเวลาของเจ้ามาถึงแล้ว จงกลับไปที่ Valley of Spirits ใน Orgrimmar และคุยกับ Ur'kyo สิ่งที่เขาจะสอนเจ้าอาจสำคัญอย่างยิ่งในภายหน้า" },
    },
    [5691] = { -- <NYI> <TXT> In the Dark it was Created
        title = { "38:1444714798:762075226", "<NYI> <TXT> มันถูกสร้างในความมืด" },
    },
    [5692] = { -- <NYI> In the Dark It was Created
        title = { "32:1622211541:1075333533", "<NYI> มันถูกสร้างในความมืด" },
        objective = { "38:1042132235:1799646349", "คุยกับ Aelthalyste ใน Undercity" },
        description = { "37:1434312191:400605207 N 304:690841300:74206577", "ข้าอยากสอนทุกสิ่งที่จำเป็น {name} แต่บางอย่างมีเพียงเผ่าของเจ้าแสดงให้ดูได้ อย่างหนึ่งคือการทำเสื้อคลุมใหม่ที่สะท้อนฐานะในศรัทธา\n\nAelthalyste บอกให้ส่งเจ้าไปหานางใน Undercity นางรอใน War Quarter หากเจ้าไม่ไป นางจะไม่พอใจเราทั้งคู่มาก" },
    },
    [5693] = { -- <NYI> In the Dark It was Created
        title = { "32:1622211541:1075333533", "<NYI> มันถูกสร้างในความมืด" },
        objective = { "38:1042132235:1799646349", "คุยกับ Aelthalyste ใน Undercity" },
        description = { "29:1577062410:757155294 N 258:1506524792:684409773", "ดีใจที่เจ้ายัง... มีชีวิต {name}\n\nAelthalyste ขอให้กลับ Undercity หลังเสร็จธุระใน Thunder Bluff ดูเหมือนพลังเจ้ามากพอจนควรได้อาภรณ์ใหม่ ข้าเชื่อว่าเป็นเสื้อคลุม\n\nนางจะรอใน War Quarter" },
    },
    [5704] = { -- <NYI> <TXT> Undead Priest Robe
        title = { "30:1389923557:25107878", "<NYI> <TXT> เสื้อคลุมนักบวชอันเดด" },
    },
    [5705] = { -- <NYI> No Longer a Shadow
        title = { "24:84429562:1358748555", "<NYI> ไม่ใช่เพียงเงาอีกต่อไป" },
        objective = { "38:1042132235:1799646349", "คุยกับ Aelthalyste ใน Undercity" },
        description = { "45:223996833:770922261 N 268:185912306:432385418", "ยินดีต้อนรับกลับ Valley of Spirits {name} แต่ข้าต้องบอกว่า Undercity เรียกหาตัวเจ้า มหานักบวชหญิงที่นั่นอยากคุยด้วย\n\nเจ้ารู้แล้วว่านางอยู่ไหน War Quarter ลึกในเมืองเจ้า\n\nไปเถอะ และอย่าลืมว่าเจ้ามาฝึกกับผู้คนข้าที่นี่ได้เสมอ" },
    },
    [5706] = { -- <NYI> No Longer a Shadow
        title = { "24:84429562:1358748555", "<NYI> ไม่ใช่เพียงเงาอีกต่อไป" },
        objective = { "38:1042132235:1799646349", "คุยกับ Aelthalyste ใน Undercity" },
        description = { "23:140679440:2097538806 N 278:725436000:749717723", "ดีใจที่ได้พบเจ้าอีก {name} แต่คงต้องคุยกันเท่านี้ก่อน Aelthalyste ฝากข่าวมาให้เจ้ากลับไปพบเธอที่ Undercity เธอยังอยู่ที่ War Quarter\n\nไม่ต้องห่วง ข้าว่าน่าจะเป็นข่าวดี ได้ยินมาว่าเธอพอใจกับความก้าวหน้าของเจ้า เพราะงั้นอย่ากังวลไปนักเลย" },
    },
    [7621] = { -- A Warning
        title = { "9:1540746926:138258856", "คำเตือน" },
        completion = { { "413:398889886:1187174013", "416:1973906599:1166422622" }, "นักบวช เจ้ากำลังจะเผชิญเหตุการณ์หนักหน่วงต่อเนื่องที่จะทดสอบทุกความสามารถ\n\nข้าแนะนำให้ฟังเรื่องที่จะเล่า\n\nจงระวัง เจ้าต้องทำงานนี้ลำพัง แนะนำให้พันธมิตรอยู่ห่าง การแทรกแซงจากคนภายนอกจะนำบทลงโทษร้ายแรงที่สุดมาให้\n\nชะตานำเจ้ามาที่นี่เพียงผู้เดียว จงสู้อย่างมีเกียรติ ใช้พลังแสงสว่าง" },
    },
    [7622] = { -- The Balance of Light and Shadow
        title = { "31:1206502011:2121510116", "สมดุลแห่งแสงและเงา" },
        objective = { "167:1559812880:743776275", "ช่วย Peasants 50 คนก่อนมีผู้ถูกสังหาร 15 คน หากสำเร็จให้คุยกับ Eris Havenfire\n\nเจ้าดูจำนวน Peasants ที่ถูกสังหารได้ที่ Death Post" },
        description = { "344:382174965:2115260409 N 1:46:46", "เจ้าต้องทำสิ่งที่ข้าทำไม่ได้ ช่วยชาวบ้านที่ถูกฆ่าขณะหนีจาก Stratholme\n\nพวกเขาจะเดินสู่แสงสว่าง เจ้าต้องให้แน่ใจว่ารอด หากล้มมากเกินไป สภาพต้องสาปของเราจะคงอยู่ เจ้าจะล้มเหลว\n\nทุกความสามารถ คำภาวนา และเวทที่เรียนมาจะถูกทดสอบ ขอแสงสว่างปกป้องเจ้า {name}" },
        completion = { { "188:1930265626:1574159658", "191:1593297207:1800819815" }, "ความมุ่งมั่นและความกล้าของเจ้าน่าอัศจรรย์ นักบวช เจ้าได้สิทธิ์ถือ Splinter of Nordrassil เหลืองานเดียว คือต้องหา Eye of Shadow จงค้นทั่วโลก" },
    },
    [7785] = { -- Examine the Vessel
        title = { "18:1507923964:1561131838", "ตรวจภาชนะ" },
        objective = { "66:1426791811:88042467", "ตรวจ Vessel of Rebirth แล้วนำกลับไปให้ Highlord Demitrian" },
        description = { "95:1819488322:831401185", "จงตรวจภาชนะฟื้นคืนชีพของเขา ผู้เป็นมรรตัย Windseeker จะถือกำเนิดใหม่จากสิ่งนี้!" },
        progress = { "45:99919042:71376328", "เจ้าจะปล่อยเขาจากคุกนิรันดร์หรือไม่?" },
        completion = { "72:604895452:173485871", "ขอให้ได้รับความคุ้มครองในการศึก ขอให้นายท่านอวยพรความพยายามเจ้า" },
        required = { [19016] = { "17:1764704861:777695782", "ภาชนะแห่งการเกิดใหม่" } },
        objectiveLabels = {
            item = { ["Vessel of Rebirth"] = "ภาชนะแห่งการเกิดใหม่" },
        },
    },
    [7786] = { -- Thunderaan the Windseeker
        title = { "25:785079526:2045337516", "Thunderaan ผู้แสวงหาสายลม" },
        objective = { "218:1749021980:1114357349", "เพื่อปลดปล่อย Thunderaan the Windseeker จากคุก เจ้าต้องนำ Bindings of the Windseeker ทั้งซีกขวาและซ้าย, Elementium 10 แท่ง และ Essence of the Firelord ไปให้ Highlord Demitrian ใน Silithus" },
        description = { "33:572649882:1255267996 N 140:1870975771:1479604581", "ข้าบอกทุกสิ่งที่รู้แล้ว {name} เจ้าต้องเป็นผู้หา Elementium เจ้าต้องทำลายร่างกายของ Firelord\n\nทำให้สำเร็จแล้วรับพร Thunderaan" },
        progress = { "41:1081696194:429082494", "ทำให้ทั้งโลกคุกเข่าหากจำเป็น!" },
        completion = { "186:1460514815:1710957284", "แม้ในฝัน ข้าก็ไม่กล้าคาดว่าจะเห็นวันนี้\n\nจงดู ผู้เป็นมรรตัย\n\nจงดูผู้เก่าแก่กว่าการดำรงอยู่!\n\nจงดูผู้เผชิญทั้งไททันและเทพเจ้า!\n\nลุกขึ้น นายท่าน! หลุดพ้นจากพันธนาการ!" },
        required = { [17771] = { "14:839597628:1776044977", "แท่งเอเลเมนเทียม" }, [19017] = { "23:1471221473:1904927809", "แก่นพลังของเจ้าแห่งไฟ" }, [18563] = { "26:1405842055:967132351", "โซ่พันธนาการแห่งผู้แสวงวายุ" }, [18564] = { "26:1405842055:967132351", "โซ่พันธนาการแห่งผู้แสวงวายุ" } },
        objectiveLabels = {
            item = { ["Elementium Bar"] = "แท่งเอเลเมนเทียม", ["Essence of the Firelord"] = "แก่นพลังของเจ้าแห่งไฟ", ["Bindings of the Windseeker"] = "โซ่พันธนาการแห่งผู้แสวงวายุ" },
        },
    },
    [7787] = { -- Rise, Thunderfury!
        title = { "18:1277321288:1999695797", "จงตื่น Thunderfury!" },
        objective = { "60:1170023821:1267805938", "นำ Dormant Wind Kissed Blade ไปมอบให้ Highlord Demitrian" },
        description = { "168:191257432:42983735", "เจ้าปราบ Wind Seeker แล้ว นำดาบที่หลับใหลไปบังคับ Demitrian เจ้าสารเลวจอมโกหก ให้ใช้วัตถุดิบที่เจ้าเคยมอบไปเพื่อแผนทรยศของเขาปลุก Thunderfury" },
        progress = { "36:688679967:845853331", "<Demitrian หวาดกลัวจนหดตัวต่อหน้าเจ้า>" },
        completion = { "93:231613930:1455780067", "ได้โปรดอย่าทำร้ายข้า! รับไป! รับดาบไป! ปล่อยให้ Demitrian ปรับชีวิตอันน่าสมเพชใหม่เถอะ!" },
    },
    [8254] = { -- Cenarion Aid
        title = { "12:137011798:618117145", "ช่วยเหลือ Cenarion" },
        objective = { "27:1397746544:1390194196", "ไปหา Ogtinc ใน Azshara" },
        description = { "265:2141836294:1879470944", "วิถีแห่งความศักดิ์สิทธิ์คือช่วยผู้เดือดร้อน วิธีทำไม่สำคัญ มีเพียงเหตุผลที่สำคัญ\n\nCenarion Circle ต้องการความช่วยเหลือเช่นนั้น คุยกับ Ogtinc เพื่อช่วยในยามทุกข์ยาก เขาอยู่บนหน้าผาทางตะวันออกเฉียงเหนือของ Ruins of Eldarath ใน Azshara" },
        completion = { "71:1112839679:642278099", "การมาของเจ้าปลดภาระจากบ่าข้า เรามีงานต้องทำมากมาย" },
    },
    [8255] = { -- Of Coursers We Know
        title = { "19:1183817709:1227671902", "สิ่งที่เรารู้เกี่ยวกับ Courser" },
        objective = { "133:1006350346:947688708", "หา Healthy Courser Glands 4 ชิ้น แล้วนำไปให้ Ogtinc ใน Azshara เขาอยู่บนหน้าผาทางตะวันออกเฉียงเหนือของ Ruins of Eldarath" },
        description = { "436:109134649:914804957", "Mosshoof Courser แห่ง Azshara เป็นสัตว์งามสง่าที่เคยอยู่ใน Felwood พวกมันทนโรคและพิษตามธรรมชาติ จึงไม่กระทบจากความแปดเปื้อน ด้วยปัญญาบรรพชน พวกมันเพียงเลือกจากสถานที่เจ็บป่วยนั้นมา\n\nข้าเศร้าใจ แต่ต้องขอให้เจ้าล่าสัตว์ทรงพลังพวกนี้ เก็บต่อม Courser สี่ชิ้นเป็นส่วนผสมแรกของยาขี้ผึ้งฟื้นฟู ที่เราจะใช้เยียวยา Felwood" },
        progress = { "39:686918144:1002502183", "เจ้ากลับมาแล้ว สำเร็จหรือไม่?" },
        completion = { "46:1939789829:1927928278 N 214:137050550:1968726934", "ดีที่เส้นทางศักดิ์สิทธิ์นำเจ้ามาหาเรา {name} ความเชื่อเจ้าไม่ขัดกับงานปรุงยาขี้ผึ้งนี้\n\nเจ้ารู้ไหม Courser ศักดิ์สิทธิ์ต่อ Cenarion Circle การฆ่าพวกมันไม่ว่าด้วยเหตุใด จำเป็นเพียงใด ล้วนบั่นทอนจิตวิญญาณพวกมัน" },
        required = { [20027] = { "21:313151977:1494846478", "ต่อมของกวางคอร์เซอร์ที่แข็งแรง" } },
        objectiveLabels = {
            item = { ["Healthy Courser Gland"] = "ต่อมของกวางคอร์เซอร์ที่แข็งแรง" },
