    },
    [8256] = { -- The Ichor of Undeath
        title = { "20:1265071818:1118263855", "ของเหลวแห่งอันเดด" },
        objective = { "114:251605114:409349425", "หา Ichor of Undeath หนึ่งชิ้นให้ Ogtinc ใน Azshara เขาอยู่บนหน้าผาทางตะวันออกเฉียงเหนือของ Ruins of Eldarath" },
        description = { "447:1574471115:888138717", "ยาขี้ผึ้งฟื้นฟูนี้ต้องใช้สูตรง่าย ๆ พิษหนึ่งส่วน ตัวยาสองส่วน เจ้าได้ตัวยาหนึ่งอย่างแล้ว ตอนนี้ต้องเก็บพิษ\n\nอันเดดทรงพลัง เช่น Highborne ที่ยังวนเวียนใน Ruins of Eldarath บางครั้งมีความชั่วร้ายอัดแน่นจนรวมเป็นเมือกสีเขียวชวนสะอิดสะเอียน ผู้มีชีวิตรู้จักสารนี้ในชื่อ Ichor of Undeath\n\nเพราะส่วนผสมชั่วร้ายนี้รุนแรง ข้าต้องการเพียงชิ้นเดียว" },
        progress = { "52:1869229338:1509131807", "เราต้องได้ของเหลวนั้นโดยเร็ว พบหรือยัง?" },
        completion = { "102:823225608:1983844823 N 1:46:46", "ข้าพูดไม่ได้ว่ายินดีรับสารน่ารังเกียจนี้ แต่เป็นความชั่วที่จำเป็น ขอบใจ {name}" },
        required = { [7972] = { "16:1526908561:1595030649", "น้ำเหลืองแห่งอันเดด" } },
        objectiveLabels = {
            item = { ["Ichor of Undeath"] = "น้ำเหลืองแห่งอันเดด" },
        },
    },
    [8257] = { -- Blood of Morphaz
        title = { "16:444942467:617905796", "เลือดของ Morphaz" },
        objective = { "172:1247274284:1169006337", "ฆ่า Morphaz ในวิหารจมของ Atal'Hakkar แล้วนำเลือดกลับไปให้ Greta Mosshoof ใน Felwood ทางเข้าวิหารจมอยู่ใน Swamp of Sorrows" },
        description = { "460:1788978994:617063939", "ตอนนี้ถึงส่วนสุดท้าย ตัวยาอย่างที่สอง\n\nรู้กันว่ามังกรเขียว Morphaz มีภูมิคุ้มกันต่อพิษและโรคทุกรูปแบบ ดรูอิดหลายคนตายเพื่อให้ได้ข้อมูลนี้ ไม่ต้องสงสัยว่าเลือดมันมีพลังพอต่อความต้องการ\n\nผู้ส่งสาร Cenarion Circle จะนำส่วนที่เจ้าเก็บแล้วไป ระหว่างหาส่วนสุดท้าย เรียกพันธมิตรแล้วไปหารังมังกรในวิหารจม Atal'Hakkar นำเลือดให้ Greta Mosshoof ใน Felwood" },
        progress = { "33:806507807:1630481155", "มีเลือด Morphaz หรือยัง?" },
        completion = { "282:229562461:1560929662", "เจ้าสังหาร Morphaz แล้วนำเลือดมาให้เรา... ข้าแทบเชื่อข่าวดีนี้ไม่ลง!\n\nเราจะผสมส่วนประกอบทันที แล้วเริ่มเยียวยาต้นไม้กับสัตว์ใน Felwood คงใช้เวลาทั้งชีวิตแก้สิ่งที่เกิดขึ้น แต่เจ้ามอบหนทางให้เราแล้ว" },
        required = { [20025] = { "16:444942467:617905796", "เลือดของ Morphaz" } },
        objectiveLabels = {
            item = { ["Blood of Morphaz"] = "เลือดของ Morphaz" },
        },
    },
    [8447] = { -- Waking Legends
        title = { "14:1679996775:810374930", "ปลุกตำนานให้ตื่น" },
        objective = { "82:111932781:1537767350", "รอ Keeper Remulos ที่ Moonglade ชำระล้าง Nightmare Engulfed Object" },
        description = { "126:1078772198:237785636 N 1:46:46", "น้ำ Lake Elune'ara น่าจะสลายฝันร้ายที่ห่อหุ้มวัตถุนี้ ขอเวลาข้าทำพิธีชำระล้างสักครู่ {name}" },
        completion = { "15:56997475:2025987572 N 86:223150857:305526612", "รับแหวนของเขาไป {name} มันทำหน้าที่ให้ Malfurion แล้ว บัดนี้จะรับหน้าที่ใหม่เพื่อเจ้า..." },
        progress = { "34:2040478716:1461917707", "เจ้าได้เห็นสิ่งที่เจ้าต้องเห็นแล้ว" },
    },
    [9250] = { -- Frame of Atiesh
        title = { "15:383862605:1127700617", "โครงคทา Atiesh" },
        objective = { "102:1455799227:1219062566", "หาคนช่วยกู้ชิ้นส่วนคทาสองชิ้นสุดท้ายและขจัดความชั่วร้ายจากมัน" },
        description = { "290:23236449:1572684538", "เมื่อประกอบโครงแล้ว Atiesh เกือบสมบูรณ์ ขาดเพียงหัวกับฐานคทา ยังมีปัญหาเล็กน้อยว่าคทาเป็นสื่อนำความชั่วร้ายของ Sargeras\n\nหาคนช่วยตามชิ้นส่วนที่เหลือและขับความชั่วร้ายออกจากคทา" },
        progress = { "24:203226959:20640214", "ถึงเวลาของนางแล้ว ผู้เป็นมรรตัย" },
        completion = { "53:679047313:289082792 N 87:1891023876:105402671", "เหล่าอัครจอมเวทตายแล้ว\n\nอย่าโศกเศร้าต่อการจากไป {name} ทุกสิ่งมีชะตากำหนด เช่นเดียวกับการที่เจ้าถือคทาของ Guardian ก็เป็นชะตา..." },
    },
    [9251] = { -- Atiesh, the Befouled Greatstaff
        title = { "31:360426897:2003312138", "Atiesh มหาคทาอันแปดเปื้อน" },
        objective = { "99:1131057514:2145373790", "Anachronos ที่ Caverns of Time ใน Tanaris ต้องการ Staff Head of Atiesh และ Base of Atiesh" },
        description = { "125:1831646117:738514505 N 353:1477728952:616859893", "เจ้าสงสัยว่าทำไมยังมีชีวิต ทั้งที่ครอบครองไอเทมชั่วร้ายยิ่ง คำตอบไม่ชัดเจน {name} ข้าเพียงทำสิ่งที่ต้องทำ\n\nKel'Thuzad นั่งวางแผนบนบัลลังก์ใน Naxxramas... เขาหาสิ่งที่เจ้าถือ และถือสิ่งที่เจ้าหา\n\nส่วนฐานคทา คนแคระ Brann Bronzebeard ถือมันเมื่อเข้า Ahn'Qiraj เขาจากมาแล้ว แต่ฐาน Atiesh ยังอยู่\n\nหากกู้ชิ้นส่วนสำเร็จ จงนำกลับมาให้ข้า" },
        progress = { "83:621751423:1362912606", "ในสภาพนี้ คทาอันตรายเกินกว่าจะอยู่ในมือผู้เป็นมรรตัย" },
        completion = { "53:314512107:235305393", "มีตัวตนอยู่ภายใน... ตัวตนที่ไม่ได้มาจากโลกนี้" },
        required = { [22733] = { "20:223643088:694220318", "หัวคทา Atiesh" }, [22734] = { "14:790491007:955304879", "ฐานคทา Atiesh" } },
        objectiveLabels = {
            item = { ["Staff Head of Atiesh"] = "หัวคทา Atiesh", ["Base of Atiesh"] = "ฐานคทา Atiesh" },
        },
    },
    [9257] = { -- Atiesh, Greatstaff of the Guardian
        title = { "34:27114098:2046121050", "Atiesh มหาคทาแห่ง Guardian" },
        objective = { "214:1806282206:1358043257", "Anachronos ที่ Caverns of Time ใน Tanaris ต้องการให้เจ้านำ Atiesh, Greatstaff of the Guardian ไป Stratholme แล้วใช้บน Consecrated Earth ปราบตัวตนที่ถูกขับออกจากคทาแล้วกลับไปหาเขา" },
        description = { "51:1744271082:1216300903 N 451:333071754:1610068243", "งานสุดท้ายนี้ยากที่สุด {name} เจ้าปราบทั้ง Old God และแม่ทัพ Lich King มาแล้ว แต่ตอนนี้ต้องเผชิญหัตถ์ของ Sargeras\n\nนำคทาไป Stratholme ที่นั่นมีผืนดินศักดิ์สิทธิ์ซึ่งอัศวินผู้ยิ่งใหญ่ที่สุดแห่ง Lordaeron ถูกฆ่า วางคทาแปดเปื้อนบนพื้นศักดิ์สิทธิ์ แล้วเตรียมรับตัวตนพลังมหาศาลที่จะแหวกออกมา... ปราบปีศาจที่ควบคุมคทา แล้วกลับมาหาข้า" },
        progress = { "22:42938510:2029640491 R 1:46:46", "ข้าต้องไม่แทรกแซง {race}" },
        completion = { "62:1276226796:1540664170 N 115:1454012584:719786787", "ความยิ่งใหญ่ของความสำเร็จนี้ไม่ควรถูกกล่าวให้ด้อยลง {name} เจ้าทำสิ่งที่คนส่วนใหญ่คงคิดว่าเป็นไปไม่ได้ ทว่ามันเป็นชะตา คทาตัดสินใจแล้ว..." },
    },
