    [94773] = { -- Divine Grace
        title = { "12:1373260677:1993784112", "พระกรุณาศักดิ์สิทธิ์" },
        completion = { "186:829567589:854288386", "เจ้ารับใช้แสงศักดิ์สิทธิ์อย่างยิ่งด้วยการเป็นแบบอย่างอันเจิดจ้าแก่ผู้เดินทางในดินแดนอันตรายแห่งนี้และที่อื่น ๆ โปรดรับบทเรียนนี้แทนคำขอบคุณสำหรับทุกสิ่งที่เจ้าทำ" },
    },
    [94774] = { -- Divine Grace
        title = { "12:1373260677:1993784112", "พระกรุณาศักดิ์สิทธิ์" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind" },
        description = { "46:186108260:356086005 N 314:1447416627:219356561", "เจ้าได้รับความสนใจจากผู้ใหญ่ของเรา {name} พวกเขาขอให้ไป Cathedral of Light ใน Stormwind โดยเร็วที่สุด ดูเหมือนเห็นว่าเจ้าพิสูจน์ตัวเองแล้วและพร้อมฝึกต่อ เมื่อถึงจงหา High Priestess Laurena นางจะชี้ทางให้ โชคดี ขอแสงสว่างสถิตกับเจ้า", variants = { { "46:186108260:356086005 N 311:375616969:2088147520", "เจ้าได้รับความสนใจจากผู้ใหญ่ของเรา {name} พวกเขาขอให้ไป Cathedral of Light ใน Stormwind โดยเร็วที่สุด ดูเหมือนเห็นว่าเจ้าพิสูจน์ตัวเองแล้วและพร้อมฝึกต่อ เมื่อถึงจงหา High Priestess Laurena นางจะชี้ทางให้ โชคดี ขอแสงสว่างสถิตกับเจ้า" } } },
        completion = { "25:2089692431:1019187282 N 228:819820501:896419647", "ดีใจที่เจ้ามาถึง {name} เรามีเรื่องต้องคุยกันมาก แต่ที่สำคัญกว่าคือการฝึกเจ้าตามวิถีแห่งพระแสง\n\nมีบทเรียนที่ผู้รับใช้พระแสงทุกคนต้องเรียนรู้ ถ้าเจ้าพร้อม เราจะเริ่มคุยกันสักสองสามเรื่องตอนนี้เลย" },
    },
    [94775] = { -- Divine Grace
        title = { "12:1373260677:1993784112", "พระกรุณาศักดิ์สิทธิ์" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind" },
        description = { "22:1882722298:723343487 R 350:22293589:1796639612", "ขอ Elune อวยพรเจ้า {race}ผู้มีไมตรี หวังว่าแสงสว่างของเจ้าจะพบและปกป้องเจ้าในวันนี้\n\nไม่นานมานี้นักบวชของเจ้าคนหนึ่งมาตามหา เขาบอกให้กลับ Cathedral of Light โดยเร็วที่สุด เพื่อคุยกับ High Priestess Laurena ดูเหมือนเจ้าทำดีจนได้รับความสนใจเช่นนั้น ข้าคงไม่อยู่ที่นี่นานนัก ผู้คนเจ้าต้องการเจ้า" },
        completion = { "25:2089692431:1019187282 N 228:819820501:896419647", "ข้าดีใจที่เจ้ามาถึงแล้ว {name} เรามีเรื่องต้องคุยกันอีกมาก แต่สิ่งสำคัญกว่าคือการฝึกเจ้าตามวิถีแห่งแสง\n\nมีบทเรียนที่ผู้รับใช้แสงทุกคนต้องเรียน หากเจ้าพร้อม เราจะเริ่มคุยกันบางเรื่องเดี๋ยวนี้เลย" },
    },
    [94776] = { -- Divine Grace
        title = { "12:1373260677:1993784112", "พระกรุณาศักดิ์สิทธิ์" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind" },
        description = { "42:864259708:463981160 N 354:379928339:1690873709", "ถึงเวลาเจ้าไป Stormwind {name} High Priestess Laurena ใน Cathedral of Light อยากคุยด้วย ต้องมีเรื่องดีมากหรือแย่มากแน่ นางถึงอยากพบด้วยตนเอง แต่ข้าเดาว่าเจ้าทำดีมาตลอด คงเป็นเรื่องดีที่นางอยากคุย\n\nอย่าเสียเวลาแถวนี้มากนัก ข้าคงไปทันทีที่ทำได้" },
    },
    [94777] = { -- Divine Grace
        title = { "12:1373260677:1993784112", "พระกรุณาศักดิ์สิทธิ์" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind" },
        description = { "69:974748309:1386129621 R 319:552991150:2111368082 R 1:46:46", "ไม่นานมานี้นักบวชของเจ้าคนหนึ่งมาตามหา {race} เขาบอกว่าหากข้าเห็นเจ้า ให้ชี้ทางไป Cathedral of Light บอกว่าสำคัญมาก แต่หากเป็นข้า คงไม่กังวลเกินไป ท่าทีเขาดูดี... ราวกับเป็นข่าวดี หากเป็นข้าคงไม่ชักช้าเดินทางไป\n\nขอ Elune สถิตกับเจ้า {race}ผู้มีไมตรี" },
    },
    [94778] = { -- Divine Grace
        title = { "12:1373260677:1993784112", "พระกรุณาศักดิ์สิทธิ์" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind" },
        description = { "28:1954922019:1918898949 N 331:1316440288:1152709634 N 1:46:46", "Stormwind ต้องการเจ้า {name} มหานักบวชหญิง Laurena ที่นั่นบอกว่า ถึงเวลาพิสูจน์ว่าคู่ควรกับการฝึกขั้นต่อไป อย่าเสียเวลาหาทางไปมากนัก พบนางได้ใน Cathedral of Light กลางเมือง ฝากความนับถือจากข้า และพิสูจน์ให้เห็นว่าเจ้าคู่ควรกับหน้าที่เช่นนี้เพียงใด ขอแสงสว่างสถิตกับเจ้า {name}" },
    },
    [94779] = { -- Divine Grace
        title = { "12:1373260677:1993784112", "พระกรุณาศักดิ์สิทธิ์" },
        objective = { "45:1006910416:2105132205", "คุยกับ High Priestess Laurena ใน Stormwind" },
        description = { "39:1677350494:1562927690 N 273:2055097521:1631470866", "สรรเสริญ Elune และแสงสว่างของเจ้า {name}\n\nช่วงนี้หลายคนในคณะเราจะเรียนความสามารถที่สะท้อนศรัทธาใน Elune หากข้าจำไม่ผิด คณะเจ้าก็คงเช่นกัน\n\nเมื่อเสร็จธุระใน Darnassus ข้าคงไปหามหานักบวชหญิงของเจ้าสักคนเพื่อฝึกต่อ" },
        completion = { "25:2089692431:1019187282 N 228:819820501:896419647", "ข้าดีใจที่เจ้ามาถึงแล้ว {name} เรามีเรื่องต้องคุยกันอีกมาก แต่สิ่งสำคัญกว่าคือการฝึกเจ้าตามวิถีแห่งแสง\n\nมีบทเรียนที่ผู้รับใช้แสงทุกคนต้องเรียน หากเจ้าพร้อม เราจะเริ่มคุยกันบางเรื่องเดี๋ยวนี้เลย" },
    },
    [94817] = { -- Confounding Flash
        title = { "17:1563399473:2081347980", "แสงวาบชวนสับสน" },
        completion = { "29:745678091:333911223 N 110:1287941204:1126872770", "เจ้าใช้เวลาเดินทางมานานทีเดียว {name} แต่ด้วยความทุ่มเทรับใช้พระแสงของเจ้า ข้าก็ยกโทษให้ได้ จงตั้งใจฟังบทเรียนนี้ให้ดี" },
    },
    [94818] = { -- Contingency Plan
        title = { "16:1988262732:404685796", "แผนสำรอง" },
        completion = { "63:38824003:2093586366 C 2:11340:5796 N 88:2145135521:708312724", "จงรับใช้แสงศักดิ์สิทธิ์ต่อไป แล้วเจ้าจะเป็น{class}ที่ยิ่งใหญ่ {name} จงตื่นตัวและมุ่งมั่นอยู่เสมอ!\n\nเจ้าพร้อมสำหรับบทเรียนถัดไปของการรับใช้แล้ว" },
    },
    [94819] = { -- Contingency Plan
        title = { "16:1988262732:404685796", "แผนสำรอง" },
        objective = { "42:971861545:1315663016", "คุยกับ High Priestess Mims ใน Ironforge" },
        description = { "N 359:1372761900:698193621", "{name} High Priestess Mims ของเจ้าอยากพบที่ Ironforge รีบเถอะ สหายผู้เฉลียวฉลาด บททดสอบต่อไปใกล้มาถึง แม้ข้าอยากเห็นพิธีพิเศษของเผ่าเจ้า แต่ที่ของข้าอยู่ที่นี่ ขอแสงสว่างร่วมเดินทางกับเจ้า เมื่อถึงเมือง Mims คงยังอยู่ใน Mystic Ward นางจะรอ" },
        completion = { "63:38824003:2093586366 C 2:11340:5796 N 88:2145135521:708312724", "จงรับใช้แสงต่อไป แล้วเจ้าจะเป็น{class}ผู้ยิ่งใหญ่ {name} จงระวังตัวและยึดมั่นในหน้าที่!\n\nเจ้าพร้อมเรียนบทต่อไปแห่งการรับใช้แล้ว" },
    },
    [94820] = { -- Contingency Plan
        title = { "16:1988262732:404685796", "แผนสำรอง" },
        objective = { "42:971861545:1315663016", "คุยกับ High Priestess Mims ใน Ironforge" },
        description = { "29:333299908:549373303 N 410:1241376342:2002278106", "เผ่าพันธุ์เจ้าฉลาดล้ำ {name} เราภูมิใจที่เรียกเจ้าว่าพันธมิตร ทุกครั้งที่ตะวันลับ เจ้าและญาติพี่น้องใกล้ทวงเมืองคืนยิ่งขึ้น แต่ก็ต้องแบกภาระดูแลครอบครัวให้ปลอดภัยระหว่างพลัดถิ่น ความโหยหาบ้านคงหนักอึ้งในใจ\n\nเพิ่งมีข่าวจาก Ironforge ขอให้กลับไปคุยกับ High Priestess Mims ใน Mystic Ward ข้าคงไม่ให้รอนาน ขอ Elune นำทางการเดินทางเจ้า" },
    },
    [94821] = { -- Confounding Flash
        title = { "17:1563399473:2081347980", "แสงวาบชวนสับสน" },
        objective = { "42:971861545:1315663016", "คุยกับ High Priestess Mims ใน Ironforge" },
        description = { "59:485735848:148595316 R 227:1394722047:1704752520 N 1:46:46", "นักบวชเพิ่งมาเยือนหอของเราเพื่อตามหาเจ้า {race}รุ่นเยาว์ เขาบอกว่าได้รับภารกิจให้หาเจ้า และเจ้าควรกลับ Hall of Mysteries ใน Ironforge โดยเร็วที่สุด เมื่อถึงแล้วหา High Priestess Mims นางจะบอกรายละเอียด\n\nขอแสงสว่างสถิตกับเจ้า {name}" },
        completion = { "29:745678091:333911223 N 110:1287941204:1126872770", "เจ้ามาถึงช้าเสียจริง {name} แต่ข้าพอจะยกโทษให้ได้ เพราะเจ้าทุ่มเทรับใช้แสงมาตลอด ตั้งใจฟังบทเรียนนี้ให้ดี" },
    },
    [94822] = { -- Confounding Flash
        title = { "17:1563399473:2081347980", "แสงวาบชวนสับสน" },
        objective = { "42:971861545:1315663016", "คุยกับ High Priestess Mims ใน Ironforge" },
        description = { "46:186108260:356086005 N 310:1318960815:1999442906", "เจ้าได้รับความสนใจจากผู้ใหญ่ของเรา {name} พวกเขาขอให้ไป Hall of Mysteries ใน Ironforge โดยเร็วที่สุด ดูเหมือนเห็นว่าเจ้าพิสูจน์ตัวเองแล้วและพร้อมฝึกต่อ เมื่อถึงจงหา High Priestess Mims นางจะชี้ทางให้ โชคดี ขอแสงสว่างสถิตกับเจ้า", variants = { { "46:186108260:356086005 N 307:260379910:1181992418", "เจ้าได้รับความสนใจจากผู้ใหญ่ของเรา {name} พวกเขาขอให้ไป Hall of Mysteries ใน Ironforge โดยเร็วที่สุด ดูเหมือนเห็นว่าเจ้าพิสูจน์ตัวเองแล้วและพร้อมฝึกต่อ เมื่อถึงจงหา High Priestess Mims นางจะชี้ทางให้ โชคดี ขอแสงสว่างสถิตกับเจ้า" } } },
        completion = { "29:745678091:333911223 N 110:1287941204:1126872770", "เจ้าใช้เวลาเดินทางมานานทีเดียว {name} แต่ด้วยความทุ่มเทรับใช้พระแสงของเจ้า ข้าก็ยกโทษให้ได้ จงตั้งใจฟังบทเรียนนี้ให้ดี" },
    },
    [94823] = { -- Confounding Flash
        title = { "17:1563399473:2081347980", "แสงวาบชวนสับสน" },
        objective = { "42:971861545:1315663016", "คุยกับ High Priestess Mims ใน Ironforge" },
        description = { "22:1882722298:723343487 R 346:619036710:1567590221", "ขอ Elune อวยพรเจ้า {race}ผู้มีไมตรี หวังว่าแสงสว่างของเจ้าจะพบและปกป้องเจ้าในวันนี้\n\nไม่นานมานี้นักบวชของเจ้าคนหนึ่งมาตามหา เขาบอกให้กลับ Hall of Mysteries โดยเร็วที่สุด เพื่อคุยกับ High Priestess Mims ดูเหมือนเจ้าทำดีจนได้รับความสนใจเช่นนั้น ข้าคงไม่อยู่ที่นี่นานนัก ผู้คนเจ้าต้องการเจ้า" },
    },
    [94824] = { -- Confounding Flash
        title = { "17:1563399473:2081347980", "แสงวาบชวนสับสน" },
        objective = { "42:971861545:1315663016", "คุยกับ High Priestess Mims ใน Ironforge" },
        description = { "42:55530343:1019519888 N 364:445918327:1485614572", "ถึงเวลาเจ้าไป Ironforge {name} High Priestess Mims ใน Hall of Mysteries สั่งให้เจ้าไปคุยด้วย ต้องมีเรื่องดีมากหรือแย่มากแน่ นางถึงอยากพบด้วยตนเอง แต่ข้าเดาว่าเจ้าทำดีมาตลอด คงเป็นเรื่องดีที่นางอยากคุย\n\nอย่าเสียเวลาแถวนี้มากนัก ข้าคงไปทันทีที่ทำได้", variants = { { "42:864259708:463981160 N 364:445918327:1485614572", "ถึงเวลาที่เจ้าต้องไป Stormwind แล้ว {name} High Priestess Mims แห่ง Hall of Mysteries สั่งให้เจ้าไปพบ ต้องมีเรื่องดีมากหรือไม่ก็แย่มากแน่ นางถึงอยากพบเจ้าด้วยตัวเอง แต่ข้าเดาว่าเจ้าทำดีมาตลอด นางคงมีเรื่องดีจะคุยด้วย\n\nอย่าเสียเวลาอยู่แถวนี้นานนัก ถ้าเป็นข้า ข้าจะรีบไปให้เร็วที่สุด\n\n[เป้าหมายเควสต์ระบุให้ไปพบ High Priestess Mims ที่ Ironforge ส่วนคำบรรยายฉบับนี้ระบุ Stormwind]" } } },
        completion = { "29:745678091:333911223 N 110:1287941204:1126872770", "เจ้าใช้เวลาเดินทางมานานทีเดียว {name} แต่ด้วยความทุ่มเทรับใช้พระแสงของเจ้า ข้าก็ยกโทษให้ได้ จงตั้งใจฟังบทเรียนนี้ให้ดี" },
    },
    [94825] = { -- Confounding Flash
        title = { "17:1563399473:2081347980", "แสงวาบชวนสับสน" },
        objective = { "42:971861545:1315663016", "คุยกับ High Priestess Mims ใน Ironforge" },
        description = { "69:974748309:1386129621 R 318:1262829189:739591879 R 1:46:46", "ไม่นานมานี้นักบวชของเจ้าคนหนึ่งมาตามหา {race} เขาบอกว่าหากข้าเห็นเจ้า ให้ชี้ทางไป Hall of Mysteries บอกว่าสำคัญมาก แต่หากเป็นข้า คงไม่กังวลเกินไป ท่าทีเขาดูดี... ราวกับเป็นข่าวดี หากเป็นข้าคงไม่ชักช้าเดินทางไป\n\nขอ Elune สถิตกับเจ้า {race}ผู้มีไมตรี" },
    },
    [94826] = { -- Confounding Flash
        title = { "17:1563399473:2081347980", "แสงวาบชวนสับสน" },
        objective = { "42:971861545:1315663016", "คุยกับ High Priestess Mims ใน Ironforge" },
        description = { "39:1677350494:1562927690 N 264:557144203:226738444", "สรรเสริญ Elune และแสงสว่างของเจ้า {name}\n\nช่วงนี้หลายคนในคณะเราจะเรียนความสามารถที่สะท้อนศรัทธาใน Elune หากข้าจำไม่ผิด คณะเจ้าก็คงเช่นกัน\n\nเมื่อเสร็จธุระใน Darnassus ข้าคงไปหามหานักบวชหญิงของเจ้าเพื่อฝึกต่อ" },
    },
    [1860] = { -- Speak with Jennea
        title = { "17:1490074880:1852591260", "คุยกับ Jennea" },
        objective = { "38:1250938154:1959433983", "คุยกับ Jennea Cannon ใน Stormwind" },
        description = { "249:720448849:881036461", "พวกเราจอมเวทมีงานต้องทำ งานที่สำคัญต่อความปลอดภัยของ Stormwind และป่า Elwynn\n\nJennea Cannon รู้รายละเอียด นางศึกษาอยู่ที่ Wizard's Sanctum ในย่านจอมเวทของ Stormwind เจ้าควรรีบไปหา" },
        completion = { "41:991884499:943089530 N 141:1804646515:307080932", "เจ้าถูกส่งมาช่วยงานข้าหรือ {name}? ดี เห็นจอมเวทรุ่นใหม่อยากช่วยเป้าหมายของเราแล้วชื่นใจ...\n\nเป้าหมายอะไรหรือ? เมื่อถึงเวลา ผู้เยาว์ เจ้าจะรู้... เมื่อถึงเวลา" },
    },
    [1861] = { -- Mirror Lake
        title = { "11:1593881481:1346568850", "ทะเลสาบ Mirror Lake" },
        objective = { "57:1817019481:1916841633", "นำตัวอย่างน้ำ Mirror Lake ไปให้ Jennea Cannon ใน Stormwind" },
        description = { "494:451084201:1594482255", "โลกนี้ตกเป็นเหยื่อการต่อสู้เวทมนตร์ครั้งใหญ่ ซึ่งฉีกกระแสเวทออกจากช่องทางที่เคยมั่นคง เราพยายามหาว่าความเปลี่ยนแปลงนี้ส่งผลใด บางคนหวั่นถึงสิ่งเลวร้ายที่สุด!\n\nข้าจะเล่าเพิ่มภายหลัง ตอนนี้ต้องการให้เจ้าเก็บข้อมูล\n\nรับขวดนี้ไป ไปเชิงน้ำตกที่ Mirror Lake ทางตะวันตกเฉียงใต้ของประตู Stormwind เก็บตัวอย่างน้ำแล้วนำกลับมาให้ข้าตรวจมลทินเวทมนตร์" },
        progress = { "24:210026546:1591419362 N 110:1478974225:1484940825", "มีตัวอย่างหรือยัง {name}? กระแสเวทใน Stormwind และ Elwynn เปลี่ยนไป ข้าต้องรู้ว่ามันกำลังซึมลงน้ำหรือไม่" },
        completion = { "11:1191658970:1224418299 N 184:1647398720:831225668 N 75:1675555584:109427072", "ขอบใจ {name} ข้าจะตรวจคุณสมบัติเวทของน้ำ หวังว่าจะไม่พบ ไม่อย่างนั้นเราอาจรู้ว่าคนที่ดื่มน้ำ Mirror Lake นานเกินไปได้รับผลร้าย\n\nนี่ {name} รับลูกแก้วหรือไม้เท้านี้เป็นสิ่งตอบแทน ขอให้รับใช้เจ้าได้ดี" },
        required = { [7206] = { "24:1958159577:936262814", "ตัวอย่างน้ำจากทะเลสาบ Mirror" } },
        steps = { { "24:1958159577:936262814", "ตัวอย่างน้ำจากทะเลสาบ Mirror" } },
    },
    [1879] = { -- Speak with Bink
        title = { "15:1290921939:238348208", "คุยกับ Bink" },
        objective = { "29:2018622347:111521755", "คุยกับ Bink ใน Ironforge" },
        description = { "N 150:1175260852:849443358 N 108:2028404466:1960877011", "{name}! Bink เพื่อนร่วมงานโนมของข้าที่ Ironforge ส่งข่าวมา นางมีงานที่ไม่ยอมพึ่งใครนอกจากจอมเวท! เจ้าจะเป็นจอมเวทคนนั้นไหม {name}?\n\nถ้าใช่ จงคุยกับ Bink นางใช้เวลาอยู่ที่ Hall of Mysteries ใน Mystic Ward ของ Ironforge" },
        completion = { "262:1709846760:1929361432", "โอ้ ข้าเห็นว่าเจ้ามีแวว ใช่ มีแน่นอน! แต่การเป็นจอมเวทที่ดีต้องใช้มากกว่านั้น ถ้าไม่ใช่จอมเวทที่ดี เจ้าก็เป็นจอมเวทที่แย่ และจอมเวทที่แย่เป็นส่วนหนึ่งของปัญหา ใช่แล้ว!\n\nอุ๊ย ข้าพูดล้ำหน้าไปหน่อย มาเริ่มตั้งแต่ต้นกัน!" },
    },
    [1880] = { -- Mage-tastic Gizmonitor
        title = { "22:269383658:533981228", "Gizmonitor สุดยอดจอมเวท" },
        objective = { "38:631706387:808552778", "นำ Mage-tastic Gizmonitor กลับไปให้ Bink" },
        description = { "460:1663374529:1941826872 N 25:1409633960:239297950", "จอมเวทอย่างเราไม่ได้แค่กระดิกนิ้วแล้วทำประกายสวย ๆ! เราควบคุมเวทมนตร์ ซึ่งเป็นโครงสร้างพื้นฐานของโลก! ต้องใส่ใจ แน่วแน่ และมีความรู้... ความรู้มากมาย!\n\nอุปกรณ์หนึ่งของข้า Mage-tastic Gizmonitor รวบรวมและเก็บความรู้นั้นมหาศาล! แต่มันหายไป! ตอนเราหนีจาก Gnomeregan ข้าทิ้งไว้ในหีบในกระท่อมหลังหนึ่งนอกเมือง ตอนนี้ที่นั่นเต็มไปด้วยโนมโรคเรื้อน!\n\nได้โปรด {name} นำ Gizmonitor กลับมา!" },
        progress = { "78:717518765:199260063", "พบ Gizmonitor หรือยัง? ข้าต้องได้มันก่อนพลังงานหมด!" },
        completion = { "142:655186668:488339174 N 160:584155147:2113295747", "โอ้ วันนี้ช่างวิเศษ! ตอนสร้าง Gizmonitor ข้าไม่เคยคิดว่าจะพึ่งมันมากเพียงนี้ ตอนนี้เริ่มศึกษาใหม่ได้แล้ว!\n\nขอบใจ {name}! นี่คือเครื่องมือแรกที่ข้าใช้เป็นจอมเวท เป็นรอยบ้างแต่ผ่านการทดสอบมาอย่างดี เลือกชิ้นที่ชอบ ข้ามั่นใจว่าชิ้นไหนก็เป็นประโยชน์" },
        required = { [7226] = { "22:269383658:533981228", "เครื่องตรวจวัดเวท Gizmonitor" } },
        steps = { { "22:269383658:533981228", "เครื่องตรวจวัดเวท Gizmonitor" } },
    },
    [1881] = { -- Speak with Anastasia
        title = { "20:807581668:434594460", "คุยกับ Anastasia" },
        objective = { "30:1971544536:272279852", "คุยกับ Anastasia Hartwell" },
        description = { "N 186:2115295626:1828204344", "{name} Anastasia Hartwell มีงานสำหรับผู้มีพรสวรรค์เช่นเจ้า คุยกับนางใน Magic Quarter ของ Undercity และเตรียมพร้อมสำหรับงานแรกเพื่อเหล่าจอมเวท Forsaken" },
        completion = { "11:927657569:725753248 N 81:968745869:106636267", "สวัสดี {name} เจ้าคิดถูกที่ตอบรับคำเรียก และจะฉลาดยิ่งกว่านั้นหากฟังสิ่งที่ข้าจะบอกต่อ..." },
    },
    [1882] = { -- The Balnir Farmstead
        title = { "20:62112760:1954015107", "ไร่ Balnir" },
        objective = { "84:1415691985:777106841", "นำ Balnir Snapdragons ไปให้ Anastasia Hartwell ใน Mage Quarter ของ Undercity", variants = { { "54:39895236:361856422 C 26:940262444:758741945", "นำ Balnir Snapdragons ไปให้ Anastasia Hartwell ในย่าน{class}ของ Undercity" } } },
        description = { "476:613520444:574463717", "Plaguelands ทางตะวันออกเป็นสิ่งผิดเพี้ยน Lich King สร้างมันขึ้น พลังเวทแพร่ลงดิน ทำให้แปดเปื้อนและฆ่าทุกชีวิต แม้พลังทำลายของโรคระบาดจะมีเสน่ห์บางอย่าง แต่พวกเราจอมเวท Forsaken เห็นว่ามันควบคุมยากและต้องจำกัด\n\nก่อนอื่น เราต้องวัดว่าแพร่ถึง Tirisfal ไกลเพียงใด ไป Balnir Farmstead ทางตะวันออกของ Tirisfal ในสวนมีดอก Snapdragon เก็บแล้วกลับมา" },
        progress = { "200:1490612576:1225304308", "มีดอก Snapdragon หรือยัง? ดอกชนิดนี้ตอบรับพลังเวทได้ดีมาก การศึกษาดอกไม้ใกล้ Plaguelands จึงบอกได้ว่าโรคระบาดเข้ามาใน Tirisfal Glades แล้วหรือไม่" },
        completion = { "140:150317277:268001260 N 120:488858727:1558226647", "อา ตัวอย่างดีนัก ข้าจะส่งให้นักปรุงยาศึกษาเพื่อวัดขอบเขตมลทินจาก Plaguelands\n\nทำได้ดี {name} สำหรับงานนี้ ข้าให้เจ้าเลือกระหว่างลูกแก้วกับไม้เท้า ไม่ว่าเลือกชิ้นใดก็มีประโยชน์มาก" },
        required = { [7227] = { "18:1917548600:2138300563", "ดอก Snapdragon จาก Balnir" } },
        steps = { { "18:1917548600:2138300563", "ดอก Snapdragon จาก Balnir" } },
    },
    [1883] = { -- Speak with Un'thuwa
        title = { "19:1457651228:1634810890", "คุยกับ Un'thuwa" },
        objective = { "20:954211064:1559347365", "คุยกับ Un'thuwa" },
        description = { "229:489193741:137079329", "Un'thuwa จอมเวทประจำเผ่าที่ Sen'jin Village พบความปั่นป่วนในกระแสเวทของ Durotar และขอความช่วยเหลือ คุยกับเขาแล้วช่วยเท่าที่ทำได้\n\nทำสำเร็จ แล้วเมื่อถึงเวลาจะมีความลับเผยให้เจ้ารู้อีก" },
        completion = { "6:1136836709:1914036474 N 91:1001784043:410031512", "สวัสดี {name} ขอสรรเสริญเจ้าที่ตอบรับคำขอช่วย หวังว่าเจ้าจะรับมืองานนี้ไหว..." },
    },
    [1884] = { -- Ju-Ju Heaps
        title = { "11:708809093:1845126966", "กองเครื่องราง Ju-Ju" },
        objective = { "66:974669241:351881815", "ทำลาย Ju-Ju Heaps 4 กอง แล้วกลับไปหา Un'thuwa ใน Sen'jin Village" },
        description = { "359:2100787211:271511904 N 46:1029091619:1979262732", "วอร์ล็อก Zalazane แห่ง Echo Isles รบกวนกระแสเวทปกติใน Durotar ด้วยเครื่องรางแปดเปื้อนที่เรียกว่า Ju-Ju Heaps ซึ่งวางไว้แถวกระท่อมบนเกาะ Echo หลัก\n\nกองเหล่านี้ทำให้สัตว์ป่าแปดเปื้อน และให้พลังวอร์ล็อกกับอสูรจากนรกที่ซ่อนตามมุมมืดของดินแดน\n\nเจ้าต้องทำลายกอง Ju-Ju {name} ก่อนกระแสเวทเปลี่ยนไปตลอดกาล" },
        progress = { "16:146911132:1843051065 N 26:602736005:1149358999", "ต้องรีบ {name} ทำลายกอง Ju-Ju!" },
        completion = { "173:881854437:616417484 N 62:233450135:810311806", "ข้าสัมผัสว่ากอง Ju-Ju ของ Zalazane ถูกทำลายแล้ว เมื่อเวลาผ่านไปและหากโชคดี กระแสเวทใน Durotar จะกลับปกติ\n\nเจ้าทำสิ่งยิ่งใหญ่เพื่อผู้คนของเจ้า {name} และพิสูจน์ความคู่ควรต่อพวกเรา จอมเวทแห่ง Horde" },
        steps = { { "21:450773298:706790633", "ทำลายกอง Ju-Ju" } },
    },
    [1919] = { -- Report to Jennea
        title = { "16:89617852:439038553", "รายงานต่อ Jennea" },
        objective = { "38:1250938154:1959433983", "คุยกับ Jennea Cannon ใน Stormwind" },
        description = { "41:108327814:2051336202 N 287:1614919714:1112712326", "ความรู้งานเวทของเจ้าเพิ่มขึ้น {name}ผู้เยาว์ พร้อมเริ่มบทเรียนแท้จริงหรือยัง? พร้อมรับที่ยืนในสงครามลับที่เราต่อสู้อยู่ไหม?\n\nหากพร้อม ไปคุยกับ Jennea Cannon ที่ Wizard's Sanctum ในย่านจอมเวท Stormwind นางมีงานที่จะเปิดหน้าต่างบานแรกสู่โลกที่มองไม่เห็นให้เจ้า" },
        completion = { "N 101:220840112:1431951369", "{name} ข้ามีภารกิจให้ที่นี่ในย่านจอมเวท ตั้งใจฟัง เราไม่มีเวลาเสียเปล่า" },
    },
    [1920] = { -- Investigate the Blue Recluse
        title = { "28:1731941490:781390652", "ตรวจสอบ Blue Recluse" },
        objective = { "167:1375515829:304946288", "รับ Cantation of Manifestation และ Chest of Containment Coffers จากด้านหลัง Jennea Cannon นำ Filled Containment Coffers 3 ชิ้นไปให้ Jennea ที่ Wizard's Sanctum" },
        description = { "476:1935424413:2102380589", "มีรายงานความปั่นป่วนที่โรงเตี๊ยม Blue Recluse ใน Mage Quarter สิ่งมีชีวิตประหลาดที่มองไม่เห็นเดินอยู่ในร้าน ข้าเกรงว่ามีรอยแยกมานาเกิดขึ้น\n\nข้าอยากให้เจ้าตรวจโรงเตี๊ยมและจับสิ่งเหล่านั้น ใช้ Cantation of Manifestation ในร้านเพื่อให้มองเห็น สยบพวกมันให้อยู่หมัดแล้วใช้ Containment Coffer กักจับ เมื่อได้พอแล้ว จงกลับพร้อมกล่องที่บรรจุแล้ว กล่องเปล่า และคาถา" },
        progress = { "33:2033108597:544608940 N 77:1827787465:1179662796", "จับสิ่งมีชีวิตแล้วหรือยัง {name}? เราต้องศึกษาเพื่อหาสาเหตุที่พวกมันมาถึง" },
        completion = { "160:819397798:2105295528 N 1:46:46", "ทำได้ดีมาก! ข้าจะศึกษาสิ่งเหล่านี้ และด้วยความพยายามกับโชค คงหาวิธีที่มันหลุดเข้ามาในโลกเราได้\n\nคุณค่าที่เจ้ามีต่อสังคมจอมเวทเพิ่มขึ้น {name}" },
        required = { [7247] = { "28:2112625966:925670992", "หีบใส่กล่องกักกัน" }, [7292] = { "25:48261132:1504957389", "กล่องกักกันที่บรรจุแล้ว" }, [7308] = { "26:1172209434:1496847466", "บทสวดแห่งการสำแดง" } },
        objectiveLabels = {
            item = { ["Chest of Containment Coffers"] = "หีบใส่กล่องกักกัน", ["Filled Containment Coffer"] = "กล่องกักกันที่บรรจุแล้ว", ["Cantation of Manifestation"] = "บทสวดแห่งการสำแดง" },
        },
    },
    [1921] = { -- Gathering Materials
        title = { "19:1074963021:561869752", "รวบรวมวัสดุ" },
        objective = { "78:1269710325:259372776", "นำ Linen Cloth 10 ชิ้น และ Charged Rift Gems 6 ชิ้นไปให้ Wynne Larson ใน Stormwind", variants = { { "72:1702845903:1492525442", "นำ Linen 10 ชิ้น และ Charged Rift Gems 6 ชิ้นไปให้ Wynne Larson ใน Stormwind" } } },
        description = { "495:2040752834:2140437435", "เจ้ารับใช้เพื่อนจอมเวทได้ดี ถึงเวลาสวมเสื้อคลุมพ่อมดแล้ว Wynne Larson ทำให้ได้ แต่เจ้าต้องนำวัสดุจำเป็นมา\n\nเสื้อจะทำจากลินินที่หาง่าย แต่ต้องมี Charged Rift Gems ซึ่งแหล่งเดียวที่รู้คือ Silver Stream Mine ใน Loch Modan สมาคมคนงานเหมืองคนแคระทิ้งไว้ในลัง\n\nรวบรวมลินินกับอัญมณี นำไปให้ Wynne Larson ที่ Larson Clothiers ใน Mage District" },
        progress = { "7:989913233:66981971 N 62:319629882:1512156562", "สวัสดี {name} Jennea บอกว่าเจ้าจะมา มีอะไรให้ข้าหรือ?" },
        completion = { "149:1397658391:1698330421", "ใช่ ผ้าลินินพวกนี้ดีมาก ข้าทำเสื้อคลุมชั้นดีได้ และเมื่อทออัญมณีรอยแยกเข้าไป ก็จะได้อาภรณ์คู่ควรจอมเวท!" },
        required = { [2589] = { "11:1393025601:1453557725", "ผ้าลินิน" }, [7249] = { "16:194312574:760511881", "อัญมณีรอยแยกอัดพลัง" } },
        objectiveLabels = {
            item = { ["Linen Cloth"] = "ผ้าลินิน", ["Charged Rift Gem"] = "อัญมณีรอยแยกอัดพลัง" },
        },
    },
    [1938] = { -- Ur's Treatise on Shadow Magic
        title = { "29:212227816:877205645", "ตำราเวทเงาของ Ur" },
        objective = { "76:117087348:157582408", "นำ Ur's Treatise on Shadow Magic ไปให้ High Sorcerer Andromath ใน Stormwind" },
        description = { "445:1444823066:231808235", "นานมาแล้ว จอมเวทสามคนศึกษาในหอนี้ จนคนหนึ่งตกสู่อาคมมืด แม้ถูกทัดทานให้เลิกเวทชั่วร้าย เขาก็ห้ามใจไม่ได้ จึงถูกเนรเทศ\n\nอาณาเขตใหม่ของจอมเวทผู้ตกต่ำคือ Tower of Ilgalar ใน Redridge เขานำตำราทรงพลังไปด้วย Ur's Treatise on Shadow Magic\n\nพวกเราจอมเวท Stormwind ต้องการตำราคืน เข้า Tower of Ilgalar หาตำราในห้องสมุดแล้วนำมาให้ข้า" },
        progress = { "22:384662313:1261983318 N 97:1761305051:1669726538", "มีตำราหรือยัง {name}? ความลับไม่เหมาะกับผู้ไร้การฝึก การขุดลึกเข้าไปอาจนำความหายนะและพินาศมาให้" },
        completion = { "223:267765373:565931623", "ข้ากลัวว่า Morganth ซ่อนตำราไว้ที่อื่น หรือหาวิธีเปิดอ่านได้\n\nดีที่เขายังทำไม่ได้ และผนึกที่เราวางบน Ur's Treatise on Shadow Magic ยังอยู่" },
        required = { [7266] = { "29:212227816:877205645", "บทนิพนธ์ว่าด้วยเวทเงาของ Ur" } },
        steps = { { "29:212227816:877205645", "บทนิพนธ์ว่าด้วยเวทเงาของ Ur" } },
    },
    [1939] = { -- High Sorcerer Andromath
        title = { "23:689677706:1037332278", "High Sorcerer Andromath" },
        objective = { "35:1710740621:1028282333", "คุยกับ High Sorcerer Andromath" },
        description = { "50:637607484:543480294 N 233:331252825:305712253", "High Sorcerer Andromath อยากคุยกับเจ้า {name} เขาอยู่บนสุดของ Wizard's Sanctum ในย่านจอมเวท Stormwind\n\nควรไปคุย เพราะ Andromath เป็นหนึ่งในจอมเวททรงพลังที่สุดที่ไม่ได้เก็บตัวใน Dalaran คำปรึกษาจากเขาย่อมสูงค่านัก" },
        completion = { "11:927657569:725753248 N 84:1294376389:1792960285", "สวัสดี {name} ข้ายินดีที่เห็นเจ้า และหวังว่าจะมีเวลาฟังคำชายชรา..." },
    },
    [1940] = { -- Pristine Spider Silk
        title = { "20:1683038673:1371490096", "ใยแมงมุมบริสุทธิ์" },
        objective = { "58:1711392123:350597682", "นำ Pristine Spider Silk 8 ชิ้นไปให้ Wynne Larson ใน Stormwind" },
        description = { "34:242306058:672284279 N 426:181133698:513278636", "เจ้ารับใช้อย่างแน่วแน่ {name} ข้าคิดว่าบางทีถึงเวลาได้อาภรณ์ชั้นดีขึ้น สมฐานะจอมเวทผู้ชำนาญ หากรวบรวมวัสดุที่ต้องใช้ เราจะจัดการให้ตัดเสื้อคลุม\n\nเจ้าต้องเข้า Duskwood ล่าแมงมุม Carrion Recluse เก็บใย แต่รับเฉพาะใยชั้นดีที่บริสุทธิ์ที่สุดเท่านั้น เมื่อได้พอแล้ว นำให้ Wynne Larson ที่ Larson Clothiers ในย่านจอมเวทนี้ นางจะทำเสื้อให้" },
        progress = { "99:1979452905:1700421163", "อา ใช่ เหล่าจอมเวท Wizard's Sanctum บอกว่าเจ้าจะมาคุย มีใยที่ต้องการหรือยัง?" },
        completion = { "46:1025751899:938959707", "ตัวอย่างดีนัก ข้าจะลงมือทันที!" },
        required = { [7267] = { "20:1683038673:1371490096", "ใยแมงมุมสภาพสมบูรณ์" } },
        steps = { { "20:1683038673:1371490096", "ใยแมงมุมสภาพสมบูรณ์" } },
    },
    [1941] = { -- Manaweave Robe
        title = { "14:808935707:587238173", "เสื้อคลุม Manaweave" },
        completion = { "137:315183071:494624360", "นี่เสื้อคลุมของเจ้า เป็นหนึ่งในผลงานที่ดีที่สุดของข้า! สวมอย่างภูมิใจ และหากใครถาม... บอกว่าได้มาจาก Larson Clothiers!" },
    },
    [1942] = { -- Astral Knot Garment
        title = { "19:1967974714:2047484944", "อาภรณ์ Astral Knot" },
        completion = { "263:1006829707:1760048810", "อาภรณ์เจ้าพร้อมแล้ว! ใยที่เก็บมาดีมาก... คงไม่ว่าอะไรหากข้าทำสั้นหน่อย เพื่อเหลือใยไว้ใช้เอง ใช่ไหม?\n\nล้อเล่นน่ะ มันจะพอดีตัว เหมาะทั้งผจญภัยและร่วมโต๊ะอาหารอย่างเป็นทางการ ใช้ให้สนุก!" },
    },
    [1943] = { -- Speak with Deino
        title = { "16:1121235164:1738766619", "คุยกับ Deino" },
        objective = { "17:394628496:145162461", "คุยกับ Deino" },
        description = { "50:1140215894:1567247763 N 51:703582881:947823569", "จอมเวทโทรลล์ Deino ต้องการความช่วยเหลือ {name} นางอยู่ที่ Darkbriar Lodge ใน Orgrimmar" },
        completion = { "137:1799894917:1891178930", "ดี เจ้ามาถึงแล้ว งานข้าไม่ง่าย แต่สำคัญต่อสังคมจอมเวท หากช่วย ข้ามั่นใจว่าเจ้าจะพบว่าคุ้มค่า" },
    },
    [1944] = { -- Waters of Xavian
        title = { "16:1855779644:824818295", "สายน้ำแห่ง Xavian" },
        objective = { "52:33983835:1511572985", "นำ Xavian Water Sample ไปให้ Deino ใน Orgrimmar" },
        description = { "493:1821756343:1484065958", "นครในตำนาน Xavian ซ่อนอยู่ลึกทางตะวันออกของ Ashenvale เรื่องความรู้โบราณเป็นที่รู้กันในหมู่ผู้ศึกษา ว่ากันว่าน้ำ Xavian มีพลังเวทมหาศาล\n\nข้าต้องการตัวอย่างจากต้นกำเนิดน้ำ\n\nนำขวดนี้ไป Xavian เก็บน้ำด้านล่างของน้ำตกที่สูงที่สุดแล้วกลับมา ระวังขณะผ่านนครโบราณ เซเทอร์ยึดซากเมืองอยู่ และไม่ชอบให้จอมเวทสอดรู้เรื่องของมัน" },
        progress = { "54:1691865494:487271745 N 67:2094698544:1080049893", "ข้ายินดีที่เจ้ากลับมาหนังยังครบ {name} มีตัวอย่างน้ำไหม? ข้าอยากศึกษาคุณสมบัติมันมาก" },
        completion = { "80:48305445:1389828877 N 55:1167500969:1507550276", "อา ดีมาก เชื่อว่าเซเทอร์ Xavian คงไม่ก่อปัญหามากนักนะ?\n\nขอบใจ {name} ข้าจะศึกษาตัวอย่างน้ำ Xavian ทันที" },
        required = { [7268] = { "19:581821212:1679607381", "ตัวอย่างน้ำจาก Xavian" } },
        steps = { { "19:581821212:1679607381", "ตัวอย่างน้ำจาก Xavian" } },
    },
    [1945] = { -- Laughing Sisters
        title = { "16:614498536:1691283107", "เหล่า Laughing Sister" },
        objective = { "63:1794571337:428393544", "นำ Laughing Sister's Hairs 12 ชิ้นไปให้ Kil'hala ที่ Crossroads" },
        description = { "407:850057688:2062302788", "เพื่อตอบแทนงานเจ้า ข้าจัดเตรียมให้ทำเสื้อคลุมใหม่แล้ว หากรวบรวมวัสดุจำเป็นได้...\n\nเสื้อนี้ต้องให้เจ้ากลับ Ashenvale เก็บปอยผม Laughing Sister เหล่าดรายแอดที่รวมตัวใกล้ Raynewood Retreat\n\nเมื่อได้ผม นำไปให้ Kil'hala ช่างตัดเย็บโทรลล์ที่ Crossroads ใน Barrens เขาจะรอและทำเสื้อคลุมให้" },
        progress = { "11:927657569:725753248 N 88:683917941:1661828815", "สวัสดี {name} Deino บอกว่าเจ้าจะมาพร้อมผม Laughing Sister มีหรือยัง?" },
        completion = { "43:711525218:608548456 N 146:867394511:668090937", "อา ผมนี้ทอเป็นเสื้อคลุมชั้นดีได้ {name} น่าเสียดายที่ Laughing Sister ต้องตายเพื่อให้มันมา แม้ข้าจะสงสัยว่าพวกนางไม่มีทางยกให้โดยสมัครใจ\n\nน่าเสียดาย แต่เพียงเล็กน้อยเท่านั้น" },
        required = { [7270] = { "22:1158754396:1148349865", "เส้นผมของ Laughing Sister" } },
        steps = { { "22:1158754396:1148349865", "เส้นผมของ Laughing Sister" } },
    },
    [1946] = { -- Nether-lace Garment
        title = { "19:1164601961:1296668294", "อาภรณ์ Nether-lace" },
        completion = { "26:1899179422:945716651 N 203:1186908662:1563331533", "นี่ Nether-lace ของเจ้า {name} ทั้งสบาย ทนทาน และมีพลังเวทจากผม Laughing Sister\n\nใช้ให้ดี หากพอใจโปรดบอก Deino ข้าอยากให้นางจอมเวทผู้นั้นพอใจข้าเสมอ..." },
    },
    [1947] = { -- Journey to the Marsh
        title = { "20:1725039803:1491533111", "เดินทางสู่บึง" },
        objective = { "19:1290614870:778012043", "คุยกับ Tabetha" },
        description = { "321:1350879971:1107466939", "ถึงเวลาได้รับไม้กายสิทธิ์จอมเวทแล้ว เริ่มด้วยคุยกับ Tabetha มนุษย์ผู้ปลีกวิเวกใน Dustwallow Marsh กระท่อมนางอยู่ลึกในบึงทางตะวันตกของ Theramore\n\nคุยกับนาง ความรู้นางกว้างใหญ่ พบกระท่อมได้ทางตะวันตกของ Theramore และเหนือ Stonemaul Ruins เพียงเล็กน้อย" },
        completion = { "73:2041356952:114231696", "เงียบ! ข้ากำลังอยู่ในช่วงละเอียดอ่อน ห้ามรบกวน!\n\nรอเดี๋ยว..." },
    },
    [1948] = { -- Items of Power
        title = { "14:825087481:2097490911", "สิ่งของแห่งพลัง" },
        objective = { "73:1825738886:1209596117", "นำ Jade 1 ชิ้น และ Bolt Charged Bramble ไปให้ Tabetha ใน Dustwallow Marsh" },
        description = { "450:1578201894:932600520", "การทำไม้กายสิทธิ์จอมเวทไม่ง่าย ต้องใช้สารหายากและทำภาชนะเก็บพลังเวทมหาศาล เจ้าต้องรวบรวมแล้วนำมาให้ข้า\n\nข้าเขียนรายการที่ต้องใช้และวิธีหาไว้บนกระดาษนี้ นำของมาให้ตรงรายการทุกอย่างและทำตามคำแนะนำทุกตัวอักษร ไม่อย่างนั้นตอนทำไม้กายสิทธิ์ เรื่องอาจ... แย่ได้" },
        progress = { "7:989913233:66981971 N 34:73977270:996554744", "สวัสดี {name} มีของที่ข้าต้องการหรือยัง?" },
        completion = { "227:1942585397:2116358481", "อาฮ่า! ได้หยกและทำกิ่งหนามแล้ว! ทำได้ดี!\n\nข้าเห็นควันขึ้นจากหูเจ้าหรือ? เจ้าอาจอยู่ใกล้เกินไปตอนสายฟ้าฟาดแท่งโทเทม แต่ไม่ต้องห่วง ถูกฟ้าผ่าถือว่าโชคดี!" },
        required = { [1529] = { "4:1262552436:168036552", "หยก" }, [7272] = { "20:468553814:1879382059", "พุ่มหนามอาบประจุสายฟ้า" } },
        steps = { { "4:1262552436:168036552", "หยก" }, { "20:468553814:1879382059", "พุ่มหนามอาบประจุสายฟ้า" } },
    },
    [1949] = { -- Hidden Secrets
        title = { "14:2094544917:1126046935", "ความลับที่ซ่อนอยู่" },
        objective = { "47:1745552656:879534539", "คุยกับ Magus Tirth ใน Shimmering Flats" },
        description = { "438:1213364986:253972675", "เพื่อทำไม้กายสิทธิ์ ข้าต้องอ่านข้อความสำคัญในตำราหนึ่ง ชื่อ Rituals of Power เขียนโดย Magus Tirth\n\nข้าไม่มีสำเนา และห้องสมุดใหญ่ใดในโลกก็ไม่มี เจ้าจึงต้องคุยกับ Tirth เพื่อขอจากเขา\n\nโชคดี Tirth เคยเป็นจอมเวทและนักปราชญ์ยิ่งใหญ่ แต่ตอนนี้มัวอยู่สนามแข่งโนมกับก็อบลินใน Shimmering Flats ดื่มเหล้าและเล่นพนัน" },
        completion = { "242:710752487:2019302409", "อะไรนะ? พูดดัง ๆ! หูแก่ ๆ ไม่คมเหมือนก่อนแล้ว\n\nหวังว่าเจ้าจะมาพร้อมเบียร์แก้วใหม่หรือข่าวเด็ดแข่งรอบหน้า! หากไม่ ก็เดินต่อเถอะ... เพราะข้ามีไม้กายสิทธิ์แปลงร่างรอเจ้าอยู่!" },
    },
    [1950] = { -- Get the Scoop
        title = { "13:1935900196:837948217", "ล้วงความลับ" },
        objective = { "59:333716443:1195599167", "หาวลีเปิดหีบนิรภัยของ Tirth แล้วกลับไปหาเขา" },
        description = { "483:1001422967:1351813407", "ข้าช่วยเรื่องตำราได้ แต่เจ้าต้องช่วยข้าก่อน!\n\nตำราที่หาคือเล่มในหีบนิรภัยล็อกด้วยเวท ต้องเอ่ยวลีพิเศษเพื่อเปิด แต่ข้าจำไม่ได้! ปกติผู้ช่วยเตือนเรื่องพวกนี้ แต่ตอนนี้หาตัวไม่พบ\n\nถ้าอยากได้ตำรา จงหาศิษย์ข้า! ถามแถวสนามแข่ง หากโชคดีอาจมีคนเห็น ลากเขากลับมา หรืออย่างน้อยเอาวลีเวทมาจากเขา เราจะได้เปิดหีบ!" },
        progress = { "49:1964001565:1254174460", "รออะไรอยู่? ข้าต้องการวลีเวท!" },
        completion = { "163:992222987:1692926053", "อา ตอนนี้จำได้แล้ว...\n\nข้าลืมคำสาปเล็กน้อยที่ใส่ Johnson จำไม่ได้ว่าทำไม แต่มั่นใจว่าเจ้าคนอกตัญญูนั่นสมควรโดน!" },
        objectiveLabels = {
            event = { ["Secret phrase found"] = "พบวลีลับแล้ว" },
        },
    },
    [1951] = { -- Rituals of Power
        title = { "16:784257306:1288026834", "พิธีกรรมแห่งพลัง" },
        objective = { "63:1827637756:811791075", "นำตำรา Rituals of Power ไปให้ Tabetha ใน Dustwallow Marsh" },
        description = { "438:1442264668:991945427", "อืม... พอคิดดู ข้าไม่มีตำราแล้ว! ข้ามีหนี้พนัน จึงขายสำเนา Rituals of Power เล่มสุดท้ายให้คนในหมู่นักบวชเพื่อใช้หนี้...\n\nสมาชิก Scarlet Brotherhood เขาต้องนำไปห้องสมุด Scarlet Monastery ใน Tirisfal Glades แน่!\n\nถ้าต้องการตำรา เจ้าต้องไปหาที่อาราม ขอโทษที่ทำให้ยุ่งยาก ช่วงนี้ข้าไม่เป็นตัวเอง..." },
        progress = { "11:927657569:725753248 N 42:1002572626:1027915140", "สวัสดี {name} พบตำรา Rituals of Power หรือยัง?" },
        completion = { "124:2027536572:991478282", "ใช่เลย! นี่แหละที่ข้าต้องใช้เตรียมพิธีสร้างไม้กายสิทธิ์! หวังว่าจะหามาไม่ลำบากเกินไป..." },
        required = { [7274] = { "16:784257306:1288026834", "พิธีกรรมแห่งพลัง" } },
        steps = { { "16:784257306:1288026834", "พิธีกรรมแห่งพลัง" } },
    },
    [1952] = { -- Mage's Wand
        title = { "11:1787545068:2138424324", "ไม้กายสิทธิ์จอมเวท" },
        objective = { "36:1295532321:482077266", "คุยกับ Tabetha หลังพิธีของนาง" },
        description = { "27:1671351083:1813964244", "ข้าจะไปทำไม้กายสิทธิ์เดี๋ยวนี้" },
        completion = { "42:1366714258:593383310", "นี่ไม้กายสิทธิ์ที่ข้าทำ เลือกชิ้นที่ชอบ!" },
    },
    [1953] = { -- Return to the Marsh
        title = { "19:906267859:248068467", "กลับสู่บึง" },
        objective = { "19:1290614870:778012043", "คุยกับ Tabetha" },
        description = { "12:376119921:82606574 N 202:1302204020:417524872", "ถึงเวลา {name} ที่เจ้าต้องคุยกับ Tabetha ผู้ปลีกวิเวกใน Dustwallow Marsh นางจะสอนสร้างอุปกรณ์จอมเวทอันทรงพลัง\n\nกระท่อม Tabetha อยู่ลึกใน Dustwallow Marsh ทางตะวันตกของ Theramore" },
        completion = { "45:1496729029:1747830305 N 213:85989274:1522503484", "อา ใช่ เจ้ามาเพื่อลูกแก้วหรือไม้เท้า {name}? ดี ข้าจะช่วยสร้าง\n\nแต่เตือนไว้ กระบวนการอันตราย อาจหมายถึงความตายของเจ้า\n\nหรือของข้า ต้องมีใครสักคนตายแน่...\n\nแต่หวังว่าจะเป็นคนอื่น ว่าไหม?" },
    },
    [1954] = { -- The Infernal Orb
        title = { "16:639680798:90265508", "ลูกแก้วอสูร" },
        objective = { "53:233519517:278080150", "นำ Infernal Orb ไปให้ Tabetha ใน Dustwallow Marsh" },
        description = { "346:1451641137:424517547", "ขั้นแรกต้องหาลูกแก้วที่มีพลัง วอร์ล็อก Burning Blade มีลูกแก้วคุณภาพสูงชั้นดี... เสียดายที่ผูกปีศาจไว้ข้างใน! แต่เราแก้ได้ ใช่ แก้ได้\n\nไป Desolace ชิง Infernal Orb จาก Burning Blade Summoner พบพวกอัญเชิญได้ที่ Mannoroc Coven\n\nเมื่อได้ลูกแก้ว จงกลับมาหาข้า" },
        progress = { "29:100707152:1531751887 N 1:63:63", "มี Infernal Orb หรือยัง {name}?" },
        completion = { "176:1932422761:712329915 N 58:1514594100:1380685948", "โอ้ ชิ้นนี้ดี! ไม่ได้หมายถึง \"ดี\" แบบน้ำผลไม้เย็นในวันร้อน\n\nที่จริง พอคิดดูมันไม่ดีเอามาก ๆ ไม่ใช่น้ำผลไม้ ลูกแก้วต่างหาก!\n\nตั้งสติ {name}! ต้องตั้งสติไว้ถ้าจะทำงานให้เสร็จ!" },
        required = { [7291] = { "12:1367673073:664362773", "ลูกแก้วอินเฟอร์นัล" } },
        steps = { { "12:1367673073:664362773", "ลูกแก้วอินเฟอร์นัล" } },
    },
    [1955] = { -- The Exorcism
        title = { "12:807326781:1778678869", "ขับไล่ปีศาจ" },
        objective = { "51:815278128:1703242794", "ฆ่า Demon of the Orb แล้วคุยกับ Tabetha" },
        description = { "472:1151625293:1380476160", "เมื่อมีลูกแก้วของผู้อัญเชิญ เราต้องขับปีศาจภายในออก ข้าทำได้ นั่นคือส่วนง่าย\n\nเจ้าต่างหากมีงานยาก ต้องฆ่าปีศาจเมื่อมันออกมา\n\nและต้องเร็ว หากช้าเกินไป มันจะกระโดดกลับลูกแก้ว แล้วเราต้องเริ่มใหม่!\n\nเตรียมตัวให้พร้อม จัดเวทที่แรงที่สุดกับยาไว้ใกล้มือ และไปหาเพื่อนหากมี เพราะเรื่องนี้ไม่น่าดูแน่" },
        progress = { "65:756433904:73982959 N 1:46:46", "ต้องฆ่าปีศาจนั้นจึงขจัดมลทินจากลูกแก้วได้ {name}" },
        completion = { "13:96413020:153092913 N 271:773275390:1378845493 R 37:1442818530:621813796 N 1:63:63", "ทำได้ดี {name}! เจ้าสอนบทเรียนที่มันจะไม่ลืมง่าย ๆ\n\nมันคงคิดให้ดีก่อนยื่นหัวน่าเกลียดกลับโลกนี้ เพื่อตามหามรรตัยโง่ที่ปราบมัน ครั้งหน้าคงพาเพื่อนมา เพื่อนตัวใหญ่มีเกล็ดที่อยากฉีกชาว{race}อย่างเจ้าเป็นชิ้นเล็กชิ้นน้อย\n\nข้าไม่ได้ทำเจ้ากลัวใช่ไหม... {name}?" },
        objectiveLabels = {
            event = { ["Kill the Demon of the Orb"] = "กำจัดปีศาจแห่งลูกแก้ว" },
            monster = { ["Demon of the Orb slain"] = "ปราบ ปีศาจในลูกแก้ว" },
        },
    },
    [1956] = { -- Power in Uldaman
        title = { "16:227368461:414761286", "พลังใน Uldaman" },
        objective = { "78:2144524614:472333569", "เก็บ Obsidian Power Source แล้วนำไปให้ Tabetha ใน Dustwallow Marsh" },
        description = { "391:334387911:1410575235 N 67:2094722229:115909995", "เมื่อเอาปีศาจออกแล้ว เราต้องหาแหล่งพลัง น่าเสียดายที่แหล่งดีที่สุดมักเก่าแก่ที่สุดและหายากที่สุด บางครั้งชะตาก็ชอบงับเจ้าเล่น ช่างน่าสนุกใช่ไหม?\n\nเจ้าต้องไป Uldaman ปราบ Obsidian Sentinel ที่นั่น มันใหญ่ แข็งแกร่ง และแหล่งพลังของมันทรงอานุภาพ!\n\nขอให้โชคดีที่สุด {name} หากไม่โชคดี เอาเถอะ... ยินดีที่ได้รู้จัก" },
        progress = { "26:459062464:1035051824 N 39:660984288:1796261416", "ไป Uldaman มาแล้วหรือ {name}? ปราบ Obsidian Sentinel ได้ไหม?" },
        completion = { "118:1721469572:1707959632 N 179:967443810:245697062 N 132:2093531776:758303272", "เจ้าทำได้หรือ? เยี่ยมมาก!\n\nข้าคุยกับเพื่อนร่วมงาน พอพูดชื่อเจ้า พวกเขาบอกว่า \"รู้ไหม {name} ทำงานภายใต้แรงกดดันได้ดีจริง ๆ!\"\n\nแต่เมื่อข้าบอกว่าส่งเจ้าไปสู้ Obsidian Sentinel ใน Uldaman พวกเขาว่าข้าบ้า! บอกว่า \"Tabetha เจ้าบ้า! ไม่มีทางที่ {name} จะสู้ Sentinel นั่นได้!\"\n\nข้าจึงบอก \"คอยดู\" พวกเขาก็บอก \"ใช่ คอยดู...\"\n\nเราแสดงให้เห็นแล้ว จริงไหม!" },
        required = { [8053] = { "21:1343347881:75425492", "แหล่งพลังงานออบซิเดียน" } },
        steps = { { "21:1343347881:75425492", "แหล่งพลังงานออบซิเดียน" } },
    },
    [1957] = { -- Mana Surges
        title = { "11:1944884662:106477998", "มานาปะทุ" },
        objective = { "46:223131906:1738112445", "ฆ่า Mana Surges 12 ตัวภายในเวลาที่กำหนด" },
        description = { "65:2109884929:961924262 N 418:1710499974:1116329543", "เกือบเสร็จแล้ว แต่ขั้นสุดท้ายอันตรายที่สุด {name}\n\nข้ามีลูกแก้วผู้อัญเชิญที่ว่างและพร้อมเติมพลัง เราจะใช้พลังจากรอยแยกมานา ข้าจะร่ายเปิดรอยแยกชั่วคราว สิ่งมีชีวิต Mana Surge จะทะลักออกมา เจ้าต้องปราบเพื่อปล่อยพลัง แล้วข้าจะรวบรวม\n\nฆ่า Mana Surge ให้พอก่อนรอยแยกปิด ข้าจะใส่พลังที่เก็บทั้งหมดลงลูกแก้วเจ้า" },
        progress = { "56:1182520570:479584915 N 1:46:46", "เจ้ายังฆ่า Mana Surge ไม่ครบจำนวน {name}" },
        completion = { "132:2045519176:1275225904", "ทำได้แล้ว! ข้าไม่เคยสงสัยเจ้าแม้แต่วินาที! เอาละ อาจสักวินาทีหรือสอง... แต่โดยหลักก็ไม่ได้สงสัยเท่าไร\n\nจริงนะ" },
        objectiveLabels = {
            monster = { ["Mana Surge slain"] = "ปราบ มานาไหลบ่า" },
        },
    },
    [1958] = { -- Celestial Power
        title = { "15:583445970:1095308418", "พลังแห่งฟากฟ้า" },
        completion = { "33:1515477944:768025125 N 185:993563004:2027425725", "จงภูมิใจ {name} จอมเวทมากมายตายต่อสิ่งที่เจ้าเผชิญ\n\nCelestial Orb พร้อมแล้ว หากต้องการ ข้าติดไว้บนยอดไม้เท้าได้ แล้วแต่เจ้า ข้าชอบลูกแก้วมากกว่า แต่ข้าเป็นใครจะไปตัดสิน?" },
    },
    [1959] = { -- Report to Anastasia
        title = { "19:1449048900:50549227", "รายงานต่อ Anastasia" },
        objective = { "30:1971544536:272279852", "คุยกับ Anastasia Hartwell" },
        description = { "226:965248338:541878349", "จอมเวท Undercity พบความปั่นป่วนเวทในเมือง และส่งข่าวให้จอมเวท Horde มาตรวจสอบ\n\nAnastasia Hartwell บอกเพิ่มได้ คุยกับนางใน Magic Quarter ของ Undercity" },
        completion = { "186:1693905236:2070615033 N 25:1810279132:878618730", "จริง มีผู้ตรวจพบความปั่นป่วนเวทในเมืองเรา ยังไม่แน่ใจต้นตอ หรือว่าเป็นคุณหรือโทษ ต้องรวบรวมข้อมูลเพิ่มก่อน...\n\nและนั่น {name} นำมาสู่งานเจ้า" },
    },
    [1960] = { -- Investigate the Alchemist Shop
        title = { "30:555213764:468640181", "ตรวจสอบร้านเล่นแร่แปรธาตุ" },
        objective = { "237:474048527:1339486700", "รับ Cantation of Manifestation และ Chest of Containment Coffers จากด้านหลัง Anastasia Hartwell นำ Filled Containment Coffers 3 ชิ้น พร้อม Chest of Containment Coffers และ Cantation of Manifestation ไปให้ Anastasia ใน Undercity" },
        description = { "498:522275113:317437281", "ร้านเล่นแร่แปรธาตุของ Algernon ใน Apothecarium เป็นศูนย์กลางความปั่นป่วนประหลาด สิ่งมีชีวิตล้วนเกิดจากเวทที่มองไม่เห็นเดินอยู่ในร้าน ต้องมีสาเหตุ และเราต้องหา!\n\nไปตรวจและกักจับสิ่งเหล่านั้น หยิบหีบกล่องกับม้วนคาถาจากด้านหลังข้า ใช้ม้วนคาถาในร้านให้มองเห็นพวกมัน ใช้เวทสยบให้อยู่หมัดแล้ววางกล่องกักจับ กลับมาพร้อมกล่องที่บรรจุแล้ว กล่องเปล่า และคาถา" },
        progress = { "39:639876774:1734433850 N 34:1363618398:1643367846", "ตรวจความปั่นป่วนแล้วหรือ {name}? จับสิ่งมีชีวิตแล้วหรือยัง?" },
        completion = { "11:1776810664:1873330125 N 403:1042040648:1488668703", "ดีมาก {name} ผู้มีปัญญาชั้นยอดของเราจะศึกษาสิ่งในกล่องกักจับเหล่านี้ และหาสาเหตุที่มันอยู่ใน Undercity\n\nหากเกิดจากรอยแยกในกระแสเวทตามธรรมชาติ ต้องรู้ว่าเกิดโดยบังเอิญหรือไม่ หากไม่ใช่ แต่เป็นการโจมตีจากพลังเวทบางอย่าง เราต้องเตรียมรับความปั่นป่วนที่ร้ายแรงกว่าในอนาคต" },
        required = { [7247] = { "28:2112625966:925670992", "หีบใส่กล่องกักกัน" }, [7292] = { "25:48261132:1504957389", "กล่องกักกันที่บรรจุแล้ว" }, [7308] = { "26:1172209434:1496847466", "บทสวดแห่งการสำแดง" } },
        objectiveLabels = {
            item = { ["Chest of Containment Coffers"] = "หีบใส่กล่องกักกัน", ["Filled Containment Coffer"] = "กล่องกักกันที่บรรจุแล้ว", ["Cantation of Manifestation"] = "บทสวดแห่งการสำแดง" },
        },
    },
    [1961] = { -- Gathering Materials
        title = { "19:1074963021:561869752", "รวบรวมวัสดุ" },
        objective = { "64:792701757:482881390", "นำ Linen Cloth 10 ชิ้น และ Dalaran Mana Gems 6 ชิ้นไปให้ Josef Gregorian", variants = { { "58:1286457357:1418478674", "นำ Linen 10 ชิ้น และ Dalaran Mana Gems 6 ชิ้นไปให้ Josef Gregorian" } } },
        description = { "51:1912819462:1677423782 N 405:2047018189:1830252658", "ถึงเวลาสวมเสื้อคลุมจอมเวทชุดแรก {name} มันแสดงฐานะและเป็นหลักฐานความคู่ควร\n\nเพื่อให้ได้เสื้อ เจ้าต้องเก็บอัญมณีมานาจากจอมเวท Dalaran ใน Silverpine ความเชื่อพวกเขาคล้ายเรา การฆ่าจึงน่าขัดใจบ้าง แต่หากไร้กำลังต้านเรา ก็ไม่คู่ควรมีชีวิต\n\nนำอัญมณีกับลินินไปให้ Josef Gregorian ที่ร้านตัดเย็บใน Magic Quarter" },
        progress = { "113:1739544653:398933054", "Anastasia บอกว่าเจ้าจะมา ข้าพร้อมทำเสื้อคลุม มีอัญมณีกับลินินหรือยัง?" },
        completion = { "177:2035428554:363341890", "วัสดุดีมาก แม้ข้าไม่มีพรสวรรค์ประเมินคุณภาพอัญมณีมานา แต่ไม่นานจะรู้ว่ามีพลังพอสร้างเสื้อคลุม Spellfire หรือไม่..." },
        required = { [2589] = { "11:1393025601:1453557725", "ผ้าลินิน" }, [7293] = { "16:356336368:1688943870", "อัญมณีมานาแห่ง Dalaran" } },
        steps = { { "11:1393025601:1453557725", "ผ้าลินิน" }, { "16:356336368:1688943870", "อัญมณีมานาแห่ง Dalaran" } },
    },
    [1962] = { -- Spellfire Robes
        title = { "15:846857453:813375806", "เสื้อคลุม Spellfire" },
        completion = { "21:1134053416:1052722483 N 17:957420195:1352079892", "นี่เสื้อคลุมของเจ้า {name} สวมให้คุ้มค่า" },
    },
    [3086] = { -- Glyphic Tablet
        title = { "14:675844684:485262241", "แผ่นจารึกอักขระ" },
        objective = { "99:2128637209:490352502", "อ่าน Glyphic Tablet แล้วคุยกับ Mai'ah ใกล้ทางเข้า Den ใน Valley of Trials" },
        description = { "47:542172104:1998871674 N 137:402670688:227345751", "อา ระหว่างเจ้าไม่อยู่ มีแผ่นจารึกส่งมาถึงเจ้า {name}\n\nว่างเมื่อไรก็อ่านเสีย ถ้าข้าจำไม่ผิด มันมาจากครูฝึกจอมเวท Mai'ah นางอยากคุยกับเจ้าเมื่อพร้อม" },
        progress = { "34:543761805:1053811566 N 215:1910263442:776420685 N 38:666896114:660782251", "เจ้าดูอยากเอาใจ Mai'ah แล้ว {name} ดีมาก เจ้ารู้จักเคารพ Mai'ah บางที Mai'ah ก็เคารพตอบ แต่พอเรื่องนั้น เจ้ามาเรียนเวท ไม่ใช่ฟัง Mai'ah คุย\n\nมีเพียงเรื่องเดียวเกี่ยวกับเวทที่ Mai'ah สอนเจ้าไม่ได้ {name} คือวิธีหยุดความแปดเปื้อน" },
        completion = { "51:78272593:2129395100 N 434:120583553:1616162944", "เจ้าเป็นหนึ่งในผู้ทรงพลังที่สุดบนโลก {name}... เถียงไม่ได้ ทุกคนก็รู้ รู้ดีด้วย!\n\nแต่ต้องระวัง! สิ่งที่ควรกลัวไม่ใช่ออร์ค เอลฟ์ หรือคนแคระ... แต่เป็นสิ่งที่มองไม่เห็น เวทมีพลัง ทำให้เจ้าทำสิ่งที่อาจไม่อยากทำ ทำให้คิดว่าตนมีพลังเกินจริง จงอดทน ใช้ปัญญา\n\nเมื่อคิดว่าพร้อมฝึก กลับมาหา Mai'ah นางจะสอนสิ่งที่พร้อมเรียน ไม่มีปัญหา" },
        required = { [9575] = { "14:675844684:485262241", "แผ่นจารึกลงอักขระ" } },
        steps = { { "14:675844684:485262241", "แผ่นจารึกลงอักขระ" } },
    },
    [3098] = { -- Glyphic Scroll
        title = { "14:914215001:1185499602", "ม้วนคัมภีร์อักขระ" },
        objective = { "74:452780556:2077642388", "อ่าน Glyphic Scroll แล้วคุยกับ Isabella ในโบสถ์ที่ Deathknell" },
        description = { "251:453318116:873597447", "อา ระหว่างเจ้าจัดการ Scourge ไร้สติ ม้วนคัมภีร์นี้มาถึงเจ้า ข้าคิดว่าคงเป็นเรื่องสำคัญ เพราะดูเหมือนมีตราครูฝึกจอมเวท Isabella ข้าคงหาเวลาอ่านก่อนออกไปอีกครั้ง" },
        progress = { "29:1892137798:1881063556 N 286:540158595:1669014018", "ข้ารู้ว่าเจ้าจะมา {name} ไม่ใช่เพราะไม่มีเจตจำนงเดินทางตนเอง แต่เพราะจิตใจเราคล้ายกัน ต่างเคยเจ็บปวดและทุกข์ทรมาน ตอนนี้ต้องการพลังทวงคืนสิ่งที่รู้ว่าเป็นของเรา ดินแดน ชีวิต ชะตา แต่เจ้ายังต้องเรียนอีกมาก" },
        completion = { "142:1190224911:1139143247 N 324:985305234:101474424", "ต้องกลับมาหาข้าบ่อย ๆ หากอยากมีพลังพอทำลายผู้ต่อต้านเรา กฎเวทยังใช้กับเจ้า {name} ความแปดเปื้อนยังตามดุจหมาป่าหิวในราตรี สัมผัสมันไม่ต่างจากการเสพติด คนรักเก่าที่ยังอยากเคียงข้าง แต่สิ่งเหล่านี้ยับยั้งได้ มันควบคุมเจ้าได้ต่อเมื่อเจ้ายอม\n\nไปเถอะ กลับมาเมื่อพลังเพิ่มขึ้น" },
        required = { [9574] = { "14:914215001:1185499602", "ม้วนคัมภีร์ลงอักขระ" } },
        steps = { { "14:914215001:1185499602", "ม้วนคัมภีร์ลงอักขระ" } },
    },
    [3104] = { -- Glyphic Letter
        title = { "14:2051977239:158106588", "จดหมายอักขระ" },
        objective = { "76:488700968:1173139061", "อ่าน Glyphic Letter แล้วคุยกับ Khelden Bremen ภายใน Northshire Abbey" },
        description = { "91:566813027:607752075 N 177:508765902:1315433576", "ข้าถูกขอให้รีบแจ้งเรื่องนี้เมื่อเจ้ากลับจากค่ายโคบอลด์ {name} ดูเหมือนเป็นจดหมายผนึกตราของ Khelden ครูฝึกจอมเวทประจำถิ่น ข้าคงรีบอ่านก่อนทำธุระอื่นใน Abbey" },
        progress = { "7:989913233:66981971 N 52:69142081:1050470797", "สวัสดี {name} ข้าคือ Khelden มีอะไรให้ช่วยไหม?" },
        completion = { "254:538997462:923157750 N 155:1988403990:516327605", "ฮ่าฮ่า ข้ารู้ว่าข้อความไม่ทำเจ้าถอยจากเส้นทาง พร้อมแล้วสินะ? พร้อมรับชะตา? พร้อมท้าทายเทพกับทุกพลังเบื้องหน้าเพื่อแสวงความรู้และอำนาจ?\n\nข้าไม่โกหก {name} เจ้าจะเป็นที่หวาดกลัวพอ ๆ กับเคารพ แต่จงรู้ด้วยว่าเมื่ออยากฝึก ข้าจะอยู่ที่นี่ เพียงมาหาเมื่อพลังเพิ่มขึ้น" },
        required = { [9571] = { "14:2051977239:158106588", "จดหมายลงอักขระ" } },
        steps = { { "14:2051977239:158106588", "จดหมายลงอักขระ" } },
    },
    [6031] = { -- Runecloth
        title = { "9:897047003:553648234", "ผ้า Runecloth" },
        objective = { "48:302048614:1354770803", "นำ Runecloth 30 ชิ้นไปให้ Meilosh ใน Timbermaw Hold" },
        description = { "388:242543890:589941159", "ที่ Timbermaw เราอยู่กันพอใจ ไม่ชอบคนแปลกหน้า ดีต่อเรา แต่ไม่ดีต่อการค้า\n\nไม่นานมานี้หนึ่งในสหายไนต์เอลฟ์อันหาได้ยากของเรามาเยือน นางสวมผ้าคลุม Runecloth ผ้าชนิดนี้หายากในหมู่เรา แต่คลุมนั้นงามจนผู้คนอยากให้ข้าทำเสื้อผ้า Runecloth เพิ่ม\n\nเจ้าจะนำ Runecloth มาให้ไหม? หากมากพอ ข้าจะให้ของแลกเปลี่ยน" },
        progress = { "75:1446714662:303700890", "มี Runecloth หรือยัง? ผู้คนข้าอยากได้ของจากผ้านี้เพิ่มนัก!" },
        completion = { "64:2024092059:1474832054 N 56:482916340:932328611", "อา นำผ้ามาแล้ว วัสดุชั้นดีจริง!\n\nขอบใจ {name} เจ้าเป็นสหายแท้ โปรดรับสิ่งนี้แลกเปลี่ยน" },
        required = { [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        objectiveLabels = {
            item = { ["Runecloth"] = "ผ้ารูน" },
        },
    },
    [6032] = { -- Sacred Cloth
        title = { "12:1101831538:646256897", "ผ้าศักดิ์สิทธิ์" },
        objective = { "47:1097764970:1577964779", "นำ Mooncloth 2 ชิ้นไปให้ Meilosh ใน Timbermaw Hold" },
        description = { "211:359837832:537906265", "แม้ผู้คน Timbermaw ชอบสัมผัส Runecloth แต่มันไม่ศักดิ์สิทธิ์ต่อเรา ส่วน Mooncloth นั้นศักดิ์สิทธิ์\n\nนำผ้าศักดิ์สิทธิ์มาเล็กน้อย ข้าจะสอนเทคนิคลับในการตัดเย็บ" },
        progress = { "32:1424046996:897615772 N 1:63:63", "นำ Mooncloth มาแล้วหรือ {name}?" },
        completion = { "89:543713459:143989111 N 23:1438501782:1464286319", "อา ดีมาก Mooncloth นี้จะใช้ทำอาภรณ์ศักดิ์สิทธิ์ของผู้คนเรา ขอบใจ {name} ตอนนี้ข้าจะฝึกให้" },
        required = { [14342] = { "9:1533651162:2094570343", "ผ้าแสงจันทร์" } },
        objectiveLabels = {
            item = { ["Mooncloth"] = "ผ้าแสงจันทร์" },
        },
    },
    [7463] = { -- Arcane Refreshment
        title = { "18:177170246:2134257199", "เครื่องดื่มดับกระหายอาร์เคน" },
        objective = { "159:1091744947:1388283552", "เดินทางไป Warpwood Quarter ใน Dire Maul สังหารธาตุน้ำ Hydrospawn แล้วนำ Hydrospawn Essence กลับไปให้ Lorekeeper Lydros ใน Athenaeum" },
        description = { "2:16737:8547 R 483:1030831104:1165610578", "จอมเวทชาว{race}! น่าอัศจรรย์ ข้าไม่พบคนเผ่าเจ้ามา... โอ้ นานเท่าไรแล้ว? 500 ปี!\n\nข้ามีของดับกระหายให้ แต่ต้องทำงานหนึ่งก่อน\n\n<Lydros หัวเราะคิก>\n\nมีสิ่งผิดปกติใน Eldre'Thalas ธาตุน้ำเข้าพำนักปีกตะวันออก ต้องลงบันทึกการมีอยู่ของมัน!\n\nไป Warpwood Quarter เก็บแก่นพลังธาตุ Hydrospawn ส่วนหนึ่งกลับมาให้ ข้าจะสอนเวทเล็กน้อยที่มีประโยชน์" },
        progress = { "19:2053054781:3884539", "ว่าอย่างไร? ข้ารู้จักเจ้าหรือ?" },
        completion = { "144:277668184:1495659038", "ยอดเยี่ยม! เจ้าเป็นใครนะ? โอ้ ไม่สำคัญ ข้าควรให้อะไรนะ? อืม... เจ้าเป็นจอมเวท บางทีสิ่งนี้อาจมีประโยชน์" },
        required = { [18299] = { "18:1269930329:1944936032", "แก่นพลังของ Hydrospawn" } },
        objectiveLabels = {
            item = { ["Hydrospawn Essence"] = "แก่นพลังของ Hydrospawn" },
        },
    },
    [8250] = { -- Magecraft
        title = { "9:1587416717:1944969186", "วิชาจอมเวท" },
        objective = { "62:1790584358:143258283", "ไปหา Sanath Lim-yo แล้วขอทางเข้าพบ Archmage Xylem" },
        description = { "471:1568873495:1599316983", "พักนี้ Archmage Xylem ถามหาคนที่มีประสบการณ์ระดับเจ้า...\n\nหากอยากพบ ไป Azshara หอเขาตั้งบนหน้าผาสูง ทางขึ้นเดียวคือเวทเคลื่อนย้ายที่คนรับใช้หยิ่งยโส Sanath Lim-yo ร่ายให้\n\nSanath ตั้งค่ายใต้หอนาย ไปจุดที่ถนนหลัก Azshara แยกตรงทางเข้า Ruins of Eldarath แล้วมุ่งเหนือโดยตรงจนถึงหน้าผา" },
        completion = { "28:1949776940:694611118 C 27:1693644527:186025016", "<Sanath แสยะยิ้มเยาะเจ้า>\n\nอัคร{class} Xylem รอการมาของเจ้า" },
    },
    [8251] = { -- Magic Dust
        title = { "10:1706779187:37978020", "ผงเวทมนตร์" },
        objective = { "43:1927073467:226914238", "นำ Glittering Dust 10 ชิ้นไปให้ Archmage Xylem" },
        description = { "341:1591334165:2050960100 N 118:1221943105:617727594", "บลัดเอลฟ์ใน Azshara พัฒนาวิธีบดไอเทมเวทที่หาได้ ผงแวววาวที่ได้ต่างจากส่วนประกอบตามปกติของเวทสลายมนตร์\n\nเมื่อข้าส่งศิษย์ไปแลกผง เขาถูกฆ่าโดยไม่ลังเล พวกนั้นต้องชดใช้\n\nหมดเวลาคุยแล้ว {name} หาบลัดเอลฟ์ตามหน้าผา Azshara แล้วใช้วิธี \"โน้มน้าว\" ที่ได้ผลกว่าเพื่อเอาผงแวววาวมา" },
        progress = { "18:123084062:2024389161", "มีผงหรือยัง?" },
        completion = { "11:534428891:784080240 N 80:2139432818:1501796264", "ทำได้ดี {name}! ข้าไม่เคยเลิกทึ่งว่าการระดม Arcane Missiles โน้มน้าวได้เพียงใด" },
        required = { [20028] = { "15:386805218:793426204", "ผงระยิบระยับ" } },
        objectiveLabels = {
            item = { ["Glittering Dust"] = "ผงระยิบระยับ" },
        },
    },
    [8252] = { -- The Siren's Coral
        title = { "17:1387464074:700362701", "ปะการังของไซเรน" },
        objective = { "60:742073686:2093041505", "รวบรวม Enchanted Coral 6 ชิ้น แล้วนำกลับไปให้ Archmage Xylem" },
        description = { "431:1360901847:1808699583", "มองรอบตัวสิ ซากเมืองและชายหาดเต็มไปด้วย Spitelash ช่วงหลังสิ่งน่ารังเกียจพวกนี้รู้จักส่วนประกอบหายากพื้นถิ่น Azshara\n\nข้าหมายถึงปะการังลงมนตร์โดยเฉพาะ มันดึงดูดพวกนั้นด้วยเหตุผลที่ข้าไม่รู้ ตอนนี้ปะการังในอ่าวเหลือน้อย และสำคัญต่องานวิจัย ข้าต้องให้เจ้าแยกปะการังบางส่วนจาก Spitelash Siren แล้วนำมาให้" },
        progress = { "79:569406669:243537144", "Spitelash Siren เป็นจอมเวทชำนาญน่าประหลาดใจ หวังว่าจะไม่เท่าเจ้านะ?" },
        completion = { "36:1253612166:219229928 N 154:2038895211:493991650", "ตัวอย่างปะการังยอดเยี่ยม {name} ฝีมือเจ้าแม่นยำและอันตรายถึงตายอย่างไม่ต้องสงสัย\n\nอย่าคิดว่าความพยายามถูกมองข้าม บางทีเจ้าคู่ควรกับการทดสอบฝีมือแท้จริงแล้ว..." },
        required = { [20029] = { "15:872583381:1446943469", "ปะการังลงมนตร์" } },
        objectiveLabels = {
            item = { ["Enchanted Coral"] = "ปะการังลงมนตร์" },
        },
    },
    [8253] = { -- Destroy Morphaz
        title = { "15:935419211:1463065354", "ทำลาย Morphaz" },
        objective = { "68:893559940:333332790", "เก็บ Arcane Shard จาก Morphaz แล้วกลับไปหา Archmage Xylem" },
        description = { "428:1600147531:1622579087", "ลึกในวิหารจม Atal'Hakkar มีมังกรเขียวชื่อ Morphaz\n\nหลายปีก่อนมันซุ่มโจมตีอย่างอุกอาจจนข้ารับมือไม่ไหว แล้วกลืนศิษย์ทั้งตัว แม้การเสียศิษย์ไม่ใช่เรื่องใหม่สำหรับข้า แต่คนนี้ถือ Arcane Shard ที่ขนาดและคุณภาพไม่มีใครเทียบ\n\nเจ้าต้องรวมพันธมิตรทรงพลังเข้าไปในวิหาร ทำลาย Morphaz แล้วกู้เศษผลึกอาร์เคนจากกระเพาะที่ไม่เสื่อมตามกาลเวลาของมัน" },
        progress = { "30:590976266:1729223842", "สังหารศัตรูเก่าข้าหรือยัง?" },
        completion = { "220:707614980:629294655 N 31:728124893:762399836", "เหลือเชื่อ เศษผลึกโตขึ้นจากการดูดพลังมังกรตลอดหลายปี\n\nตอนนี้ข้าไม่มีอะไรขอเพิ่มแล้ว ความสามารถหล่อหลอมอาร์เคนกลับคืนเต็มที่พร้อมผลึกนี้ ผลงานแรกเป็นของเจ้า {name} เพียงเลือกมา..." },
        required = { [20085] = { "12:128900675:907235328", "เศษผลึกอาคม" } },
        objectiveLabels = {
            item = { ["Arcane Shard"] = "เศษผลึกอาคม" },
        },
    },
    [8461] = { -- Deadwood of the North
        title = { "21:2138559600:752197475", "Deadwood แห่งแดนเหนือ" },
        objective = { "170:217929926:1127323000", "Nafien ต้องการให้เจ้าฆ่า Deadwood Den Watchers 6 ตัว, Deadwood Avengers 6 ตัว และ Deadwood Shamans 6 ตัว แล้วกลับไปหาเขาทางเหนือของ Felwood ใกล้ทางเข้า Timbermaw Hold" },
        description = { "378:1598627847:186985342 N 113:1407029898:1821446805", "มีค่ายเฟอร์โบลก์ Deadwood ทางตะวันตกเฉียงใต้ตรงไปจากเรา ความแปดเปื้อนแทรกทั่วค่าย ข้าอยากหยุดก่อนเป็นปัญหา\n\nเผ่า Deadwood ชั่วร้าย แต่เป็นผลจากเฟลที่ทำจิตใจมัวหมอง ความเป็นปฏิปักษ์ไม่ได้ติดตัวแต่กำเนิด ทว่าช่วยพวกเขาไม่ได้ ข้าเศร้าที่ต้องสู้พี่น้องตน\n\nได้โปรด {name} ข้าขอให้ทำสิ่งจำเป็น เพียงอย่าเล่ารายละเอียด ภาพเช่นนั้นรบกวนใจข้ามากเกินไป" },
        progress = { "193:1572370329:566569534", "เมื่อเจ้าชนะใจ Timbermaw ข้าเชื่อว่าเราจะทำอะไรให้ได้ Timbermaw ไม่ลืมพันธมิตร โดยเฉพาะในยามมืดมนเช่นนี้" },
        completion = { "425:1976605081:1305409067", "ข้าสัมผัสว่าเจ้ามีชัย ชัยชนะ... คำกลวงเปล่านักเมื่อคิดถึงสิ่งที่ต้องทำ อย่างไรก็พิสูจน์ว่าคู่ควรความไว้ใจแล้ว\n\nอาจต้องใช้เวลาก่อน Timbermaw ต้อนรับใน Hold โดยไม่เป็นศัตรู แต่ความเพียรจะสลายความระแวงของพี่น้องข้า ตราบใดไม่ทรยศและยกอาวุธใส่เรา เราจะหาจุดร่วมกันได้" },
        objectiveLabels = {
            monster = { ["Deadwood Den Watcher slain"] = "ปราบ ยามเฝ้ารัง Deadwood", ["Deadwood Avenger slain"] = "ปราบ นักล้างแค้น Deadwood", ["Deadwood Shaman slain"] = "ปราบ ชาแมน Deadwood" },
        },
    },
    [8464] = { -- Winterfall Activity
        title = { "19:1229852007:1805446750", "ความเคลื่อนไหวของ Winterfall" },
        objective = { "172:640346321:1925955778", "Salfa ต้องการให้เจ้าฆ่า Winterfall Shaman 8 ตัว, Winterfall Den Watchers 8 ตัว และ Winterfall Ursa 8 ตัว เขาอยู่ด้านนอกทางเข้า Timbermaw Hold ใน Winterspring", variants = { { "24:485224825:520900558 W1 20:1713226896:930724551 W2 30:726756509:161376686 W3 95:1311790458:2069412618", "Salfa ต้องการให้เจ้าฆ่า Winterfall Shaman {world1} ตัว, Winterfall Den Watchers {world2} ตัว และ Winterfall Ursa {world3} ตัว เขาอยู่ด้านนอกทางเข้า Timbermaw Hold ใน Winterspring" } } },
        description = { "42:261326954:1081398306 N 440:230820571:606588157", "Timbermaw ชอบอยู่ตามลำพัง {name} แม้ยอมให้ผู้ไว้ใจผ่านอย่างปลอดภัย แต่เราพยายามเลี่ยงเฟอร์โบลก์เผ่าอื่นทุกทาง\n\nพักนี้ Winterfall เป็นศัตรูกับเรามากขึ้น ดูโกรธเกรี้ยว ถูกความกลัวและความเกลียดสิ่งที่ไม่เข้าใจกลืนกิน\n\nข้าต้องขอให้เจ้าลดจำนวนเพื่อลดภัยต่อเรา หาได้ที่ Winterfall Village ไกลไปทางตะวันออกของที่นี่" },
        progress = { "62:785370587:615252907 N 71:1198365549:695997955", "เราซาบซึ้งสิ่งที่เจ้าทำเพื่อ Timbermaw มาก {name} ความพยายามต่อเนื่องจะทำให้เผ่าไว้ใจและเคารพแน่" },
        completion = { "141:1605347855:1188498231 N 148:516148138:2016343806", "ขอบใจในสิ่งที่ทำ แม้ชวนเศร้า โปรดรับสิ่งนี้แทนคำขอบคุณ\n\nขอให้เจ้าช่วยต่อไป {name} เรามีพันธมิตรน้อยนัก หากไม่มีเจ้า ภัยต่อเผ่าคงเกินกำลังรับมือลำพัง" },
        objectiveLabels = {
            monster = { ["Winterfall Shaman slain"] = "ปราบ ชาแมน Winterfall", ["Winterfall Den Watcher slain"] = "ปราบ ยามเฝ้ารัง Winterfall", ["Winterfall Ursa slain"] = "ปราบ นักรบหมี Winterfall" },
        },
    },
    [8481] = { -- The Root of All Evil
        title = { "20:1609985116:1044668549", "ต้นตอแห่งความชั่วร้ายทั้งปวง" },
        objective = { "203:1445290392:461762714", "ปัก Demon Summoning Torch ที่ปากถ้ำของ High Chief Winterfall ในหมู่บ้านเฟอร์โบลก์ Winterfall ปราบปีศาจแล้วเก็บ Essence of Xandivious ไปให้ Gorn One Eye ใน Timbermaw Hold" },
        description = { "N 491:1629336579:478134983", "{name} เพราะเจ้า เราจึงคิดวิธีเรียกต้นตอความชั่วร้ายของ Winterfall ออกมาได้ ปีศาจแปดเปื้อนที่ครอบงำพวกเขา!\n\nนำคบเพลิงไปปักปากถ้ำส่วนตัวของ High Chief Winterfall มันจะบังคับปีศาจเผยตัวมาตรวจ นั่นคือเวลาที่เจ้ากับพันธมิตรต้องโค่นมัน! มีเพียงแก่นพลังปีศาจที่ล้มแล้วจึงเริ่มการเยียวยาอันยาวนานของ Winterfall... และความรอด Timbermaw Hold ได้" },
        progress = { "25:2093074577:447371734 N 49:1186198910:1397209854", "เจ้ากลับมาหาเรา {name}... หมายความว่าปีศาจถูกฆ่าแล้วหรือ?" },
        completion = { "403:1094026436:1525183695", "เจ้า... ช่วยเราไว้! การปราบปีศาจ Xandivious ทำให้ Timbermaw Hold ปลอดภัยไปอีกหลายปี เจ้าเป็นวีรชนแท้ในหมู่เรา\n\nโปรดรับสิ่งนี้พร้อมพร แม้การเยียวยาเฟอร์โบลก์จะช้า และความขัดแย้งยังดำเนินต่อ แต่เจ้ามอบสิ่งที่ Winterfall ไม่เคยมีก่อนวันนี้\n\nพวกเขามีโอกาสอยู่รอด" },
        required = { [21145] = { "21:743323395:1037147729", "แก่นพลังของ Xandivious" } },
        objectiveLabels = {
            item = { ["Essence of Xandivious"] = "แก่นพลังของ Xandivious" },
        },
    },
    [8484] = { -- The Brokering of Peace
        title = { "22:1357045921:1011962273", "สานสันติภาพ" },
        objective = { "77:2052206428:403959190", "นำ Timbermaw Offering of Peace ไปให้ King Magni Bronzebeard ใน Ironforge" },
        description = { "48:725907749:399237873 N 408:1144081142:1789665248", "การกระทำเจ้ายิ่งกว่าเรื่องวีรชนธรรมดา {name} หากเป็นตัวแทนผู้คนเจ้า พวกเขาก็คือคนที่เราอยากร่วมสร้างสันติ\n\nโปรดนำของถวายนี้ให้กษัตริย์คนแคระที่อยู่ในขุนเขาเหล็ก ข้าเชื่อว่าเรียกเมืองนั้น Ironforge อดีตเขาเคยพยายามติดต่อเราในนาม Alliance ตอนนี้เหมาะสมแล้วที่จะยอมรับว่าเจ้าเป็นคนสำคัญในการสานสันติของ Alliance" },
        progress = { "C 145:434399702:663083762", "{class} เจ้าคือผู้ได้รับการต้อนรับในอาณาจักรข้า วีรชนเช่นเจ้าควรถือ Ironforge เป็นบ้านเสมอ เอาละ มีธุระใด?" },
        completion = { "353:1928123957:1919925560 N 107:1067874172:1029259906", "แท้จริง เป็นความเปลี่ยนแปลงโชคดียิ่ง หากสร้างสันติถาวรกับพวกเขาได้ เราจะได้เปรียบในกิจการ Kalimdor สิ่งที่ไนต์เอลฟ์สนับสนุนลำพังไม่ได้ ข้าจะแจ้งผู้นำ Alliance คนอื่นทันทีและส่งทูตเพิ่ม!\n\nส่วนเจ้า {name}... แสดงความกล้าทั้งการทูตและการลงมือ ข้าขอบใจ เช่นเดียวกับ Alliance ทั้งหมด" },
    },
    [8485] = { -- The Brokering of Peace
        title = { "22:1357045921:1011962273", "สานสันติภาพ" },
        objective = { "61:168712763:231026628", "นำ Timbermaw Offering of Peace ไปให้ Thrall ใน Orgrimmar" },
        description = { "48:725907749:399237873 N 407:814500757:1184461182", "การกระทำเจ้ายิ่งกว่าเรื่องวีรชนธรรมดา {name} หากเป็นตัวแทนผู้คนเจ้า พวกเขาก็คือคนที่เราอยากร่วมสร้างสันติ\n\nโปรดนำของถวายนี้ให้ Warchief ออร์คที่อยู่ใน Durotar ข้าเชื่อว่าเรียกเมืองนั้น Orgrimmar อดีตเขาเคยพยายามติดต่อเราในนาม Horde ตอนนี้เหมาะสมแล้วที่จะยอมรับว่าเจ้าเป็นคนสำคัญในการสานสันติของ Horde" },
        progress = { "48:845576335:1198087952 C 107:1453863892:339737125", "Warchief ขอต้อนรับเจ้า {class} การกระทำช่วยให้ Horde แข็งแกร่งในยามปั่นป่วน เอาละ มีธุระใด?" },
        completion = { "310:1744633848:67810290 N 107:1086400696:1993125233", "แท้จริง เป็นความเปลี่ยนแปลงโชคดียิ่ง หากสร้างสันติถาวรกับพวกเขาได้ เราจะได้เปรียบในการปกป้อง Kalimdor จากภัยภายนอก ข้าจะแจ้งผู้นำ Horde คนอื่นทันทีและส่งทูตเพิ่ม!\n\nส่วนเจ้า {name}... แสดงความกล้าทั้งการทูตและการลงมือ ข้าขอบใจ เช่นเดียวกับ Horde ทั้งหมด" },
    },
    [9362] = { -- Warlord Krellian
        title = { "16:2094260992:68019902", "Warlord Krellian" },
        objective = { "108:1223639484:1884188126", "เก็บ Prismatic Shell ให้ Archmage Xylem เขาอยู่ในหอบนหน้าผา Azshara" },
        description = { "23:993414638:1893318915 N 341:1410809205:40455611", "เวลาเหลือน้อย {name}! เวทส่องนิมิตพบแหล่งพลังเวทแข็งแกร่ง ข้าทิ้งหอไม่ได้ จึงขอให้เจ้าฆ่าสิ่งชั่วร้ายที่ถือวัตถุนี้\n\nเจ้าคนโง่น่าสมเพชนั่นชื่อ Warlord Krellian ซ่อนหลังยามใน Temple of Zin-Malor เผาเป็นเถ้าแล้วเอา Prismatic Shell ที่มันหวงนักมา" },
        progress = { "47:345317376:459443443", "ไม่มีเวลาเสียเปล่า! มีเปลือกหอยหรือยัง?" },
        completion = { "152:1622566461:1457565794", "ข้าต้องบอกว่าเปลือกนี้มีออร่าประหลาด เหมาะแล้วที่รางวัลส่วนหนึ่งสำหรับการนำมาคือทดสอบความสามารถเวทของมัน..." },
        required = { [23250] = { "15:1833879572:856638790", "เปลือกเหลือบรุ้ง" } },
        objectiveLabels = {
            item = { ["Prismatic Shell"] = "เปลือกเหลือบรุ้ง" },
        },
    },
    [9364] = { -- Fragmented Magic
        title = { "16:1150675511:1242843282", "เวทมนตร์แตกเสี้ยว" },
        objective = { "167:238831403:230514587", "ใช้ Polymorph กับ Spitelash ใน Azshara แล้วฆ่าร่างแยกที่ปรากฏหลังผ่านไปหลายวินาที เมื่อฆ่า Polymorph Clones ครบ 50 ตัว ให้กลับไปหา Archmage Xylem ใน Azshara" },
        description = { "395:372848558:114705949", "งานวิจัยเผยการใช้งาน Prismatic Shell ที่ไม่เหมือนใคร\n\nถือเปลือกหอยแล้วใช้ Polymorph กับ Spitelash ใน Azshara หากรอสักครู่ ออร่าโกลาหลของเปลือกจะทำให้พวกมันแตกเป็นร่างแยกเล็กหลายร่างชั่วคราว ฆ่าร่างแยกให้เร็วที่สุด เปลือกจะรวบรวมแก่นพลัง\n\nเมื่อเปลือกเต็ม ให้นำกลับมา" },
        progress = { "29:732463818:1460111579", "เก็บพลังเวทแล้วหรือยัง?" },
        completion = { "82:796701893:2077598880", "ยอดเยี่ยม! ยอดเยี่ยม!\n\nตอนนี้เราปรับพลังเวทนี้เป็นเวทบทใหม่ได้ ดูนี่!" },
    },
    [92481] = { -- A Student of the Arcane
        title = { "23:1298743240:2070055910", "ศิษย์แห่งอาร์เคน" },
        objective = { "89:1847462073:232036641", "ตรวจ Glowing Recall Crystal แล้วคุยกับ Dorii Brightwhisper ใน Thendal Grove" },
        description = { "260:427668872:370759763", "ระหว่างเจ้าจัดการปัญหา Vuldren ครูฝึกจอมเวทประจำถิ่น Dorii Brightwhisper ทิ้ง Recall Crystal นี้ไว้ให้ ภายในมีข้อความถึงเจ้า ลองดูเสีย จากนั้นพบ Dorii ได้ในสิ่งปลูกสร้างด้านหลังข้า" },
        progress = { { "88:1714994681:1085072169", "11:927657569:725753248 N 71:556007976:669245161", "11:927657569:725753248 C 71:556007976:669245161", "11:927657569:725753248 R 71:556007976:669245161" }, "สวัสดี สหาย ข้ายินดีที่มีเกียรติช่วยให้การศึกษาเวทของเจ้าก้าวหน้า", variants = { { "11:927657569:725753248 N 71:556007976:669245161", "สวัสดี {name} ข้ายินดีที่ได้มีโอกาสช่วยให้เจ้าเรียนรู้เวทมนตร์ลึกซึ้งขึ้น" } } },
        completion = { { "438:238788608:822032971", "69:1072794392:1396190288 N 359:2341565:1795805310", "69:1072794392:1396190288 C 359:2341565:1795805310", "69:1072794392:1396190288 R 359:2341565:1795805310" }, "ให้ข้าดูเจ้าหน่อย ใช่ ข้าเชื่อว่าเจ้าจะเป็นนักผจญภัยรุ่นเยาว์ที่ดี พลังอาร์เคนเสื่อมถอยในหมู่ผู้คนเรา แต่มีผู้พยายามค้นคืนสิ่งที่สูญเสียระหว่างหลายพันปีที่อยู่ท่ามกลางเมฆ ข้ามั่นใจว่าเจ้าจะนำการแสวงหาความรู้อาร์เคนอันไม่สิ้นสุด และทำให้เราภูมิใจในที่สุด\n\nคุยกับข้าอีกหากต้องการก้าวต่อไป", variants = { { "69:1072794392:1396190288 C 359:2341565:1795805310", "ขอข้ามองเจ้าชัด ๆ หน่อย ใช่ ข้าเชื่อว่าเจ้าจะเป็น {class} รุ่นเยาว์ที่มีอนาคต พลังอาร์เคนในหมู่ชนของเราอ่อนลง แต่ยังมีผู้ที่อยากค้นคืนสิ่งที่เราสูญเสียไปตลอดหลายพันปีที่อยู่ท่ามกลางเมฆ ข้ามั่นใจว่าเจ้าจะเป็นผู้นำการค้นหาความรู้อาร์เคนที่ไม่มีวันสิ้นสุดนี้ และทำให้เราภูมิใจในตัวเจ้า\n\nถ้าอยากก้าวต่อไป ก็มาคุยกับข้าอีกครั้ง" } } },
        required = { [282416] = { "22:2093235504:1133569723", "คริสตัลเรียกกลับเรืองแสง" } },
        steps = { { "22:2093235504:1133569723", "คริสตัลเรียกกลับเรืองแสง" } },
    },
    [92841] = { -- Valley of Bones
        title = { "15:468798100:1315477866", "หุบเขากระดูก" },
        objective = { "108:1374562469:872040210", "เพิ่มชื่อเสียงกับ Magram และตามหา Orgrul ใกล้ Valley of Bones ทางใต้ของ Magram Village" },
        description = { "383:2043247433:1205962063", "ถึงเวลา คนนอก ที่จะเรียนรู้การค้นพบยิ่งใหญ่ของเรา... แต่ Warug จะไม่ใช่คนเล่า!\n\nลงใต้ไปอีกฝั่งหมู่บ้าน หาเซนทอร์ตัวใหญ่เหม็นชื่อ Orgrul\n\nพอถึงเจ้าจะรู้\nพอเห็นเขาเจ้าจะรู้\nหากเขาเห็นว่าคู่ควรรู้ เจ้าจะได้รู้\n\nถ้าไม่ล่ะ? อย่างน้อยเจ้าก็ยินดีได้ที่ Warug มีมงกุฎใหม่" },
        completion = { "501:238976526:2116854426", "ข่าวลือเป็นจริงสินะ น่าเสียดายที่ Warug ใช้เจ้าให้วิ่งวุ่นทำแต่งานไร้สาระ แต่อย่างน้อยเจ้าก็พิสูจน์ตัวเองแล้ว\n\nมองลงไปในหุบเขาสิ เจ้าเห็นอะไร กระดูกกับศพ พวกอันเดดที่เดินเพ่นพ่าน และ Twin Goliaths\n\nที่นี่ต้องคำสาปมานานก่อนเรามาถึง และข้าว่าจะเป็นแบบนี้อีกหลายชั่วคน เผ่าเราเป็นเผ่าแรกที่กล้าเผชิญความสยองเบื้องล่าง และจะเป็นเผ่าเดียวที่ได้ครองพลังของมัน\n\nเจ้าอยากปกครอง Desolace ทั้งหมดเหมือนข้าหรือไม่" },
        progress = { "183:1654391030:510330326", "เจ้าคือนักพเนจรที่ข้าได้ยินคนเล่าถึงบ่อย ๆ ใช่ไหม?\n\nข้าสนใจจะคุยกับคนผู้นั้นเท่านั้น และจะคุยก็ต่อเมื่อชื่อเสียงของเขาในหมู่ Magram สมกับที่คนกล่าวขานถึงเขา" },
        objectiveLabels = {
            reputation = { ["Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [92844] = { -- Mountain of Bones
        title = { "17:1180345879:431346417", "ภูเขากระดูก" },
        objective = { "126:1801673456:478503523", "รักษาระดับชื่อเสียงกับ Magram และนำ Gently Cursed Bones 426 ชิ้นไปให้ Orgrul ทางใต้ของ Magram Village ใน Desolace", amount = { "52:1491736042:485491818 W1 71:1002457485:1870631409", "รักษาระดับชื่อเสียงกับ Magram และนำ Gently Cursed Bones {world1} ชิ้นไปให้ Orgrul ทางใต้ของ Magram Village ใน Desolace" } },
        description = { "439:737309243:772057503", "พลังปลุกศพบางอย่างซึมทั่ว Valley of Bones ด้วยเหตุที่เรายังไม่เข้าใจ\n\nเหตุผลเหล่านั้นก็ไม่สำคัญ เวทเป็นของเราแล้ว ผู้ที่ไม่สู้ด้วยคมหรือค้อนจะถูกฝึกใช้เวทใหม่นี้\n\nหากคิดว่าข้าจะเริ่มด้วยงานท้าทาย คิดใหม่เสีย ตอนนี้เข้าหุบเขากระดูก ไปเอากระดูกมา ข้ามั่นใจว่าเจ้ารับมือไหว" },
        completion = { "343:223200005:692839606", "<Orgrul เริ่มนับกระดูก แต่พอขึ้นเลขสองหลักก็เริ่มข้ามตัวเลขจนสุดท้ายจำไม่ได้ว่านับถึงไหน เขาลองนับใหม่ แต่กลางทางก็หันมาถลึงตาใส่เจ้าเมื่อเห็นสีหน้าเจ้าเปลี่ยนไปขณะมอง>\n\nเฮอะ ไว้ข้าค่อยนับทีหลัง ดูแล้วน่าจะพอ เจ้าอย่าได้คิดหลอกข้าเชียว\n\nข้าจะเก็บพวกนี้ไว้" },
        progress = { "94:359782401:917075350", "ถ้าเจ้าหากระดูกมาไม่ครบ ข้าจะเอากระดูกของเจ้ามาแทนหนึ่งชิ้นต่อทุกชิ้นที่ขาด" },
        required = { [254663] = { "18:606338670:1830415768", "กระดูกที่ลงคำสาปอ่อน ๆ" } },
        steps = { { "18:606338670:1830415768", "กระดูกที่ลงคำสาปอ่อน ๆ" } },
        objectiveLabels = {
            reputation = { ["Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [92846] = { -- Outcast Necromancers
        title = { "20:2067531444:1238138118", "ผู้ใช้มนตร์ปลุกศพนอกคอก" },
        objective = { "99:119923149:298520061", "รักษาระดับชื่อเสียงกับ Magram และสังหาร Outcast Necromancers ใน Valley of Bones" },
        description = { "482:2101210801:1201901110", "เห็นเซนทอร์อ่อนแอที่ย่ำเท้าแถวนี้ไหม? พวกนั้นเชื้อสาย Gelkis\n\nเรา Magram ตั้งฐานลึกเข้าไปในหุบเขาแล้ว เมื่อ Gelkis เห็นเรา บางคนจึงตามรอย ข้าไม่รู้ว่าอยากเข้าร่วมหรือโค่นเรา แต่รู้ว่าพวกเดียวกันตัดสินขับพวกมันออกจากเผ่าหมด\n\nพวกมันเป็นหมาป่าโดดเดี่ยว ยุ่งกับพลังที่ไม่ใช่ของตน ข้าอยากให้ตาย" },
        completion = { "331:1772558381:1319688202", "ฮ่า ๆ ข้าได้ยินเสียงร้องของพวกมันมาถึงนี่!\n\nพวก Gelkis ควรหัดฆ่าคนเผ่าตัวเองที่ทรยศสายเลือดเสียบ้าง พอทำไม่ได้ก็เป็นภาระให้เราตามเก็บกวาด ข้าไม่ได้มาคอยจัดการเรื่องเละเทะให้เผ่าที่ด้อยกว่า\n\nถ้าเจออีกก็ดับแสงในตาพวกมันเสีย เป็น Gelkis แล้วก็เป็น Gelkis วันยังค่ำ" },
        objectiveLabels = {
            monster = { ["Outcast Necromancer slain"] = "ปราบ เนโครแมนเซอร์นอกเผ่า" },
        },
    },
    [92847] = { -- Corrupting Tears
        title = { "16:1598140969:2006955472", "น้ำตาแปดเปื้อน" },
        objective = { "103:2070586560:753218123", "รักษาระดับชื่อเสียงกับ Magram และนำ Petrified Bark 3 ชิ้น กับ Imbued Tears 3 ชิ้นกลับไปให้ Orgrul", amount = { "52:1491736042:485491818 W1 20:197481198:1867069437 W2 29:1414100103:832820789", "รักษาระดับชื่อเสียงกับ Magram และนำ Petrified Bark {world1} ชิ้น กับ Imbued Tears {world2} ชิ้นกลับไปให้ Orgrul" } },
        description = { "495:1297019340:111593884", "คนนอก สังเกตอาวุธในมือพวกปลุกศพนอกคอกไหม? เราจะไม่ให้ Gelkis อยู่จนชำนาญวิชานี้ แต่เทคนิคชักนำพลังน่าสนใจ พวกมันยังใช้ผลึกแบบเดียวกับที่ Warug ให้เจ้าขโมย\n\nข้าว่าใช้เทคนิคนี้ให้เราได้เปรียบได้ กลับหุบเขาเอาไม้จากต้นไม้ต้องสาป แล้วดูว่า Warug จะยอมแบ่งผลึกบ้างไหม ข้าจะทำไม้เท้าจากมัน" },
        completion = { "274:754100873:329073998", "แค่สามอันหรือ ฮึ Warug ขี้เหนียวเหมือนเคย รอข้าทำไม้เท้าสักครู่\n\nข้าจะเอาไว้หนึ่งอัน อันที่สองให้ Necrokhan ที่ลาดตระเวนตรงทางแคบไปซากเมืองเอลฟ์\n\nอันที่สามของเจ้า ตอนนี้เจ้าเป็นส่วนหนึ่งของสงครามนี้ยิ่งกว่าครั้งไหน" },
        progress = { "97:1964705874:2138705365 R 66:1981068624:1035455935", "ไม้เท้าเหล่านี้อาจเป็นสิ่งที่เราขาดอยู่ในการยึดพื้นที่ส่วนที่เหลือของ Valley of Bones ไปเถอะ {race} เราต้องใช้วิธีของพวก Gelkis ให้เป็นประโยชน์ก่อนที่พวกมันจะค้นพบอะไรใหม่" },
        required = { [254841] = { "14:794598543:151148583", "เปลือกไม้ที่กลายเป็นหิน" }, [254840] = { "12:655544479:452332495", "หยาดน้ำตาที่อาบพลัง" } },
        steps = { { "14:794598543:151148583", "เปลือกไม้ที่กลายเป็นหิน" }, { "12:655544479:452332495", "หยาดน้ำตาที่อาบพลัง" } },
        objectiveLabels = {
            reputation = { ["Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [92873] = { -- Proof of Concept
        title = { "16:823279325:1096675138", "พิสูจน์แนวคิด" },
        objective = { "120:230117609:1617379726", "รักษาระดับชื่อเสียงกับ Magram Clan แล้วนำ Well Cursed Bones 426 ชิ้นจากพิธีที่สำเร็จกลับไปให้ Orgrul", amount = { "58:1677077596:1197029022 W1 59:899825357:960704530", "รักษาระดับชื่อเสียงกับ Magram Clan แล้วนำ Well Cursed Bones {world1} ชิ้นจากพิธีที่สำเร็จกลับไปให้ Orgrul" } },
        description = { "459:842178148:1311020235", "เรารู้แล้วว่าผลึกทำได้มากกว่าฉีกพื้น Gelkis พิสูจน์ว่าบิดให้เป็นพลังปลุกศพได้ จำกระดูกที่ให้เก็บไหม? ข้าประกอบเท่าที่ทำได้ไว้เหนือเนิน พอทำโครงกระดูกใช้งานได้สองร่าง\n\n<Orgrul ยื่นไม้เท้าที่ทำใหม่ให้>\n\nข้าจะส่งไม้เท้าของ Necrokhan ส่วนเจ้าก็เล่นของใหม่ไป กลับมาเมื่อพิสูจน์ได้ว่าใช้เป็นเท่านั้น" },
        completion = { "342:912722202:803656820", "ข้าเห็นไฟดวงใหม่ลุกโชนอยู่ในดวงตาเจ้า คนนอก เจ้าแสดงให้เห็นว่าสร้างอาวุธของตัวเองได้ เรียกสมุนมารับใช้ได้ และที่สำคัญที่สุดคือรู้จักกำราบพวกมันเมื่อขัดคำสั่ง\n\nเสียดายที่เจ้าไม่มีเลือดเซนทอร์ ไม่อย่างนั้นเจ้าอาจก้าวไปเป็นข่านคนต่อไปได้" },
        progress = { "119:1259877119:966310663", "ถึงเจ้าจะช่วยเรามาจนถึงตอนนี้ แต่ถ้าชุบคนตายขึ้นมาไม่ได้ พวก Magram ก็หมดธุระกับเจ้าแล้ว" },
        required = { [254842] = { "16:1650214123:1654022210", "กระดูกที่ลงคำสาปอย่างดี" } },
        steps = { { "16:1650214123:1654022210", "กระดูกที่ลงคำสาปอย่างดี" } },
        objectiveLabels = {
            reputation = { ["Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [92893] = { -- No Mercy for the Weak
        title = { "21:1514497821:539354166", "ไม่ปรานีผู้อ่อนแอ" },
        objective = { "156:557470320:608892152", "รักษาระดับชื่อเสียงกับ Magram Clan และสังหาร Gelkis Captives 5 คนที่กระจายทั่ว Valley of Bones เสร็จแล้วกลับไปหา Orgrul", amount = { "56:798486193:1959002682 W1 99:1617561828:553540590", "รักษาระดับชื่อเสียงกับ Magram Clan และสังหาร Gelkis Captives {world1} คนที่กระจายทั่ว Valley of Bones เสร็จแล้วกลับไปหา Orgrul" } },
        description = { "370:1750882964:59516670", "เมื่อเข้า Valley of Bones ลึกขึ้น เจ้าจะพบ Gelkis ที่กล้าเดินเข้าดินแดนเรา ข้าสั่งให้ไว้ชีวิตเพื่อเป็นอาหารหนอนกระดูกที่ขุดอยู่ แต่หนอนไม่สนว่าเหยื่อยังมีชีวิต\n\nงานง่าย ๆ หาเชลยแล้วดับชีวิต อย่าให้แม้ความหวังวูบเดียวว่าจะเป็นอิสระ" },
        completion = { "306:503402949:1848307244", "ข้าอยากแขวนกะโหลกพวกมันไว้ที่กระโจมใจจะขาด แต่ร่างของพวกมันมีค่าต่อ Magram ที่ยังอยู่ในหุบเขามากกว่า\n\nพอถึงพรุ่งนี้เช้า หนอนกระดูกจะกินเนื้อพวกมันหมด แล้วเราจะมีโครงกระดูกชุดใหม่ให้ปลุกอีกมาก\n\nทุกครั้งที่ Gelkis ตาย กองทัพ Magram ก็ยิ่งแข็งแกร่ง!" },
        objectiveLabels = {
            reputation = { ["Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
            monster = { ["Gelkis Captive slain"] = "ปราบ เชลย Gelkis" },
        },
    },
    [92894] = { -- Bone Raising
        title = { "12:193603130:1688745", "ปลุกกระดูก" },
        objective = { "217:1075525074:1650513953", "รักษาระดับชื่อเสียงกับ Magram Clan และใช้ Enhanced Necromancy Staff ปลุกอันเดดที่ดิ้นรนโผล่ขึ้นทั่ว Valley of Bones ให้ขึ้นมาได้เต็มตัว กลับไปหา Orgrul เมื่อกองทัพ Magram เพิ่มกำลังแล้ว" },
        description = { "494:265891973:407240013", "ข้าเห็นความตื่นเต้นในตาเจ้า คนนอก เข้าใจศักยภาพวิชาปลุกศพหรือยัง?\n\nแน่นอนว่าเข้าใจ ข้าจึงสั่งให้ฝึกทักษะเพิ่ม\n\nเมื่อเข้าหุบเขาลึกขึ้น จะเห็นซากความพยายามปลุกศพที่ล้มเหลว ต้องเป็นฝีมือ Gelkis แน่ แทบตะกุยพ้นดินไม่ได้ คงตลกหากไม่น่าสมเพช\n\nข้าประทับพลังเพิ่มในไม้เท้า ใช้มันเพิ่มกองทัพเรา และบดขยี้ตัวที่ต่อต้าน!" },
        completion = { "492:954002177:915324608", "<Orgrul ฟังคำอธิบายของเจ้า พลางกลั้นยิ้มไว้ไม่อยู่>\n\nอย่ากังวลเลย คนนอก การทดลองนี้ห่างไกลจากคำว่าล้มเหลว ตอนนี้เรารู้แล้วว่าเวทปลุกคนตายของ Gelkis อ่อนแอและเปราะบางเพียงใด พวกมันยังต้องไปอีกไกลกว่าจะเทียบพลังเราได้\n\nแค่เจ้าควบคุมพวกมันได้บ้างก็แสดงฝีมือมากแล้ว ถึงจะเสียโครงกระดูกไป เจ้าก็แสดงให้เห็นว่ามีความสามารถน่าประทับใจ\n\nข้าจะเก็บไม้เท้าไว้ก่อน ยังมีงานอีก" },
        steps = { { "28:1183008117:1647487206", "อัญเชิญหรือสังหาร Haggard Bones" } },
        objectiveLabels = {
            reputation = { ["Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [93034] = { -- Valley of Bones
        title = { "15:468798100:1315477866", "หุบเขากระดูก" },
        objective = { "112:1514457019:131139888", "เพิ่มชื่อเสียงกับ Gelkis และตามหา Nerlokh ใกล้ Valley of Bones ไกลไปทางตะวันออกของ Gelkis Village" },
        description = { "130:2049595344:85709259 N 333:938953978:1429250495", "ระหว่างเจ้าไม่อยู่ หน่วยสอดแนมคนหนึ่งกลับมาพร้อมข่าวยืนยันสิ่งที่ข้ากลัว\n\nMagram กำลังทำบางอย่าง {name} ไม่ใช่เรื่องดี\n\nValley of Bones ไกลทางตะวันออกเป็นดินแดนต้องสาป เซนทอร์น้อยคนกล้าเข้า และน้อยกว่านั้นที่กลับบ้าน ศัตรูพบอะไรชั่วร้ายที่นั่น เราต้องรู้ว่าคืออะไร\n\nไปหาหน่วยสอดแนม Nerlokh ที่ทางเข้าใต้ แต่เจ้าอาจต้องพิสูจน์ตัวเองต่อ Gelkis เพิ่ม" },
        completion = { "318:433749539:577958512 N 94:73385107:2073013930", "ดูเถิด Valley of Bones ดินแดนต้องคำสาปชั่วกาล ที่ซึ่งแม้แต่ Theradras ผู้ยิ่งใหญ่ก็ไม่โปรดยิ้มให้ ไม่มีเผ่าใดกล้าเหยียบเข้ามาหลายชั่วคน แต่ตอนนี้ดูเหมือนพวก Magram จะยึดเป็นของตนแล้ว!\n\nข้าฝึกมาน้อยและไม่มีเครื่องพร้อมรบ ข้าไปได้ไกลสุดแค่ซุ้มโค้งพวกนี้ ส่วนเจ้า {name} ต้องสู้แทนเผ่า Gelkis\n\nเจ้าช่วยเรามามากแล้ว แต่งานของเจ้าเพิ่งเริ่ม" },
        progress = { "113:1718029300:1388699303", "เจ้าคงเป็นพันธมิตรที่ Uthek พูดถึง ข้าคือ Nerlokh แห่งเผ่า Gelkis เรามีเวลาแนะนำตัวกันแค่นี้" },
        objectiveLabels = {
            reputation = { ["Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [93035] = { -- Ravaging Ravagers
        title = { "17:629397788:2048859050", "กวาดล้าง Ravager" },
        objective = { "141:617383982:1039316810", "รักษาระดับชื่อเสียงกับ Gelkis Clan ฆ่า Undead Ravagers 6 ตัว แล้วกลับไปหา Nerlokh ที่ทางเข้าใต้ของ Valley of Bones", amount = { "55:432022450:683501644 W1 85:772323558:1383641734", "รักษาระดับชื่อเสียงกับ Gelkis Clan ฆ่า Undead Ravagers {world1} ตัว แล้วกลับไปหา Nerlokh ที่ทางเข้าใต้ของ Valley of Bones" } },
        description = { "465:1967293237:490855200 N 1:46:46", "มองไปไม่ไกลก็เห็นอันเดดเดินโซเซข้างหน้า สังเกตอะไรผิดปกติไหม?\n\nพวกมันเดินสองขา ไม่ใช่สี่! โครงกระดูกไม่ใช่ญาติผู้ตายของเราเสียด้วย Magram ต้องย่ำยีร่างผู้ตายก่อน Desolace เป็นดินแดนเราเสียนาน ข้านึกไม่ออกว่าหาเหตุผลใดมาหันหลังให้ Mother Theradras แล้วลบหลู่ศพที่พักมาหลายศตวรรษ\n\nทำให้อันเดดสงบเสีย {name}" },
        completion = { "299:562085898:499316693", "เจ้าดูสะบักสะบอม แต่ยังไม่ยอมแพ้ สิ่งที่เจ้าทำช่วยให้ผู้ที่ถูกฝังได้กลับไปพักสงบ แต่เจ้าคงเห็นแล้วว่าความวุ่นวายในหุบเขามีแต่จะหนักขึ้น\n\nข้าเกรงว่าอีกไม่นานกระดูกที่เจ้าฝังไปจะลุกขึ้นยืนอีก\n\nเราต้องเดินหน้าต่อ" },
        objectiveLabels = {
            reputation = { ["Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
            monster = { ["Undead Ravager slain"] = "ปราบ อันเดดจอมฉีกกระชาก" },
        },
    },
    [93037] = { -- Outing Outcasts
        title = { "15:897298417:1683447673", "เปิดโปงผู้ถูกขับไล่" },
        objective = { "126:615417394:2017398397", "รักษาระดับชื่อเสียงกับ Gelkis Clan และนำ Necromantic Garb 1 ชิ้นไปให้ Nerlokh ที่ทางเข้า Valley of Bones", amount = { "57:1930826964:2020487109 W1 68:1728026575:22762657", "รักษาระดับชื่อเสียงกับ Gelkis Clan และนำ Necromantic Garb {world1} ชิ้นไปให้ Nerlokh ที่ทางเข้า Valley of Bones" } },
        description = { "205:1544814882:232766001 N 226:261802955:1508956438", "ระหว่างรอ ข้ามองผ่านซุ้มโค้งลึกไปหน่อย แล้วเห็นสิ่งที่อยากให้เจ้ายืนยัน\n\nข้าทนพูดออกมาไม่ได้ จนกว่าจะพิสูจน์ข้อสงสัย\n\n{name} ระหว่างสำรวจหุบเขา จงฆ่าพวกปลุกศพที่ดูอ่อนแอกว่าตัวอื่น ถอดชุดพิธีอย่างระวังแล้วนำมา ข้าต้องรู้ว่าจิตกับสายตายังชัดเจนดี" },
        completion = { "162:593821586:598841732 N 243:373412141:776751095", "<Nerlokh รีบรับผ้าและเครื่องประดับจากเจ้า สีหน้าของเขาเย็นชาลง พอดูไปเพียงไม่กี่ชิ้นก็วางที่เหลือไว้ข้างตัว>\n\n{name} นักปลุกคนตายชั้นผู้น้อยพวกนี้เป็น Gelkis\n\nตอนนี้ข้ารู้แล้วว่าทำไมจำนวนคนของเผ่าเราถึงลดลงมากกว่าที่การปะทะเล็ก ๆ จะอธิบายได้ มีคนของเรากำลังแปรพักตร์ คงหวังเอาใจพวก Magram\n\nเผ่าเรากำลังแพ้สงคราม" },
        progress = { "163:2035530452:337706010", "ข้าให้คำมั่นว่าเมื่อเจ้าทำงานนี้เสร็จ ข้าจะบอกเจ้าว่าข้าสงสัยอะไร\n\nเพื่อเผ่าของเรา ขอให้ข้าตาฝาดไปเองเถอะ" },
        required = { [255875] = { "16:1692103526:1639306417", "อาภรณ์นักเวทปลุกศพ" } },
        objectiveLabels = {
            reputation = { ["Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
            item = { ["Necromantic Garb"] = "อาภรณ์นักเวทปลุกศพ" },
        },
    },
    [93041] = { -- Facing the Truth
        title = { "16:517746997:233708335", "เผชิญความจริง" },
        objective = { "139:378496347:1505682773", "รักษาระดับชื่อเสียงกับ Gelkis Clan และนำ Accursed Skull กับ Gelkis Necromantic Garb ไปให้ Uthek the Wise ใน Gelkis Village" },
        description = { "460:546831239:1426782759", "การค้นพบนี้ทำลายใจเผ่า แต่ควรรู้เฉพาะคนจำเป็น Uthek เป็นคนหนึ่งที่ต้องรู้เหตุการณ์ ข้าคิดว่านางจะรู้ว่าควรทำต่ออย่างไร\n\nนำสิ่งนี้ไปแสดง และควรมีหลักฐานวิชาปลุกศพด้วย หากะโหลกที่ดูเพิ่งต้องสาป ข้าสงสัยว่าพวกนั้นสะสมไว้ในปากโครงกระดูกยักษ์ตัวหนึ่ง" },
        completion = { "142:1753250663:672408069 N 221:1024585787:823291223", "<Uthek ฟังคำอธิบายของเจ้าด้วยสีหน้าสงสัย จนกระทั่งเจ้ายื่นหลักฐานให้ดู>\n\nข้าสังเกตว่าจำนวนพวกเราลดลง {name} แต่ไม่เคยคิดว่าจะเป็นเรื่องนี้! เวทปลุกคนตาย... พวก Magram ชั่วช้าใช้โดยไม่ละอาย แล้วตอนนี้ข้ายังต้องมารู้ว่าเผ่าของข้าเองมีส่วนด้วยหรือ\n\nข้าจะคุยกับข่าน ตอนนี้เจ้าเตรียมกลับไปแนวหน้า" },
        progress = { "61:1083263829:1681951556", "ข้าไม่นึกว่าเจ้าจะกลับมาเร็วขนาดนี้ หรือนี่จะเป็นลางร้าย?" },
        required = { [255945] = { "14:831892198:204638475", "กะโหลกต้องสาป" }, [255941] = { "23:1130095945:1669909049", "ชุดผู้ใช้เวทเนโครแมนซีของเผ่า Gelkis" } },
        steps = { { "14:831892198:204638475", "กะโหลกต้องสาป" }, { "23:1130095945:1669909049", "ชุดผู้ใช้เวทเนโครแมนซีของเผ่า Gelkis" } },
        objectiveLabels = {
