    [93058] = { -- Saving Our Own
        title = { "14:828556641:1123412006", "ช่วยคนของเรา" },
        objective = { "158:1338410072:1434375658", "รักษาระดับชื่อเสียงกับ Gelkis Clan และช่วย Gelkis Captives 5 คนใน Valley of Bones เมื่อเสร็จให้กลับไปหา Nerlokh ใกล้ทางเข้า", amount = { "58:2127776007:534893493 W1 99:1402326288:1610521179", "รักษาระดับชื่อเสียงกับ Gelkis Clan และช่วย Gelkis Captives {world1} คนใน Valley of Bones เมื่อเสร็จให้กลับไปหา Nerlokh ใกล้ทางเข้า" } },
        description = { "127:758840070:436222283 N 351:1552968483:924149653", "มีพวกปลุกศพต่อสู้กันสั้น ๆ หลังเนิน ข้าใช้จังหวะนั้นมองเข้าไปใกล้ขึ้น\n\n{name} คนที่เราสูญเสียช่วงนี้ไม่ได้แปรพักตร์ทั้งหมด มี Gelkis ถูกจับลึกในหุบเขา! ข้าตรวจสถานการณ์ไม่ได้ เพราะ Magram ร่างยักษ์เริ่มพุ่งมาหา โชคดีที่มันเลิกสนใจเร็ว\n\nเจ้าต้องกลับ Valley of Bones ปลดปล่อยพวกเขา Gelkis ยืนเคียงกัน" },
        completion = { "321:211797371:1217524013 N 84:999565912:118439447", "ตอนแรกที่ได้ยินเสียงกีบกระทืบพื้น ข้านึกว่ากำลังจะถูกตีถอยไปถึงหมู่บ้าน ลองคิดดูว่าข้าดีใจแค่ไหนที่เห็นพี่น้องเราถอยผ่านซุ้มโค้งมาได้อย่างปลอดภัย!\n\nข้าให้ผู้รอดชีวิตไปรายงาน Uthek ว่าได้รู้อะไรบ้าง ข้าไม่คาดว่าจะมีกำลังเสริม {name} แต่นี่เป็นลางดีสำหรับอนาคตของเผ่าเรา\n\nเรามุ่งทำงานตรงหน้าต่อเถอะ" },
        steps = { { "22:195051911:1462389000", "ช่วยเชลยชาว Gelkis" } },
        objectiveLabels = {
            reputation = { ["Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [93062] = { -- Bone Burying
        title = { "12:1032439622:2047104659", "ฝังกระดูก" },
        objective = { "122:1635449011:445054203", "รักษาระดับชื่อเสียงกับ Gelkis Clan และสลายคำสาปจากการอัญเชิญที่ล้มเหลว 8 ร่างทั่ว Valley of Bones", amount = { "74:95863232:416701714 W1 47:862979290:525917989", "รักษาระดับชื่อเสียงกับ Gelkis Clan และสลายคำสาปจากการอัญเชิญที่ล้มเหลว {world1} ร่างทั่ว Valley of Bones" } },
        description = { "488:89531014:245349802", "เรื่องไม้เท้าเจ้า ข้าจำได้ว่าเป็นของ Uthek เจ้าบอกว่าทำด้วย Theradras' Tears เสริมด้วย Draenethyst Crystal และสลายเวทมืดได้ใช่ไหม?\n\nข้าเห็นโครงกระดูกติดอยู่ใต้ดินหินลึกในหุบเขา เชื่อว่าเป็นการอัญเชิญล้มเหลวของ Outcast Necromancer อาจถูกขังใต้ดินตลอดกาล\n\nการให้พวกมันกลับสงบย่อมดีต่อเป้าหมายเราและวิญญาณพวกมัน" },
        completion = { "295:1865175788:195190002 N 1:46:46", "ข้าโล่งอกที่รู้ว่าเจ้าคืนความสงบให้ร่างผู้ตายมากมาย\n\nทั้งชีวิตข้าคิดว่าสงครามระหว่างเผ่าคงจบด้วยความโหดร้ายและการนองเลือด ไม่เคยคิดเลยว่าวันหนึ่งข้าจะจ้องหน้าความตาย แล้วความตายจะจ้องกลับมา\n\nขอบใจเจ้าอีกครั้ง {name}" },
        steps = { { "26:1717640216:949244360", "ส่ง Haggard Bones ไปสู่ความสงบ" } },
        objectiveLabels = {
            reputation = { ["Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [93066] = { -- Bristleback Retreat
        title = { "19:1644059356:1603733263", "ค่าย Bristleback Retreat" },
        objective = { "175:957743958:1941973527", "รักษาระดับชื่อเสียงกับ Magram และสังหารควิลบอร์ที่ Bristleback Retreat จากนั้นรายงาน Hagiak ที่ Magram Front อีกฟากของ Valley of Bones ใน Desolace" },
        description = { "492:1474988831:1718007311", "อีกฝั่งหุบเขา เราตั้งฐานเล็กเตรียมเดินทัพเข้าป่าใกล้ ๆ ก่อนเจ้าตรงไป ข้าอยากให้จัดการ Bristleback ที่เพิ่งรุกล้ำตามทาง ดูเหมือนมาพร้อมเรา แต่ชิงวัตถุจากวิหารใกล้ ๆ ได้จนทำให้เราเข้าใกล้ไม่ได้\n\nงานง่าย ๆ หาหนามกับหมู ฆ่าไปให้มากไม่ต้องเลือก แล้วรายงาน Hagiak ที่ค่ายที่บอก" },
        completion = { "309:1498386067:956403639", "น่าเสียดายที่เจ้ามาไกลถึงนี่ คนนอก แต่แนวหน้าของ Magram ไม่ต้องการเจ้า เจ้าเบี่ยงความสนใจข้าจนงานเราช้าไปแล้ว\n\nกลับไปหา Orgrul แล้วบอกเขาว่า...\n\nคิดอีกที ข้ามีงานให้ทหารใช้แล้วทิ้งอย่างเจ้าพอดี เรื่องนี้จบเร็วแน่ ไม่ว่าจะจบดีหรือร้าย" },
        objectiveLabels = {
            reputation = { ["Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
            monster = { ["Bristleback Nomad slain"] = "ปราบ คนเร่ร่อน Bristleback", ["Bristleback Thornweaver slain"] = "ปราบ ผู้ถักหนาม Bristleback", ["Bristleback Skullcrusher slain"] = "ปราบ จอมบดกะโหลก Bristleback" },
        },
    },
    [93072] = { -- Long-Term Solutions
        title = { "19:1331254434:458531552", "ทางแก้ระยะยาว" },
        objective = { "163:976564527:433070650", "รักษาระดับชื่อเสียงกับ Magram Clan และสังหาร Outcast Scouts 2 คน, Outcast Marauders 6 คน และ Outcast Necromancers 8 คน แล้วกลับไปหา Hagiak ที่ Magram Front", amount = { "55:1303372872:2094730087 W1 17:178683150:1570826591 W2 24:1904720034:1007301824 W3 64:256552859:1855146331", "รักษาระดับชื่อเสียงกับ Magram Clan และสังหาร Outcast Scouts {world1} คน, Outcast Marauders {world2} คน และ Outcast Necromancers {world3} คน แล้วกลับไปหา Hagiak ที่ Magram Front" } },
        description = { "294:603119332:1234655340", "มีหมู่บ้านเซนทอร์อีกแห่งทางตะวันตกเฉียงใต้ เป็นของ Gelkis เจ้าคาดว่าข้าจะส่งไปให้เลือดตกใช่ไหม? ดี นั่นควรเป็นสิ่งแรกที่คิด ไม่อย่างนั้นข้าจะสงสัยความภักดีต่อ Magram!\n\nรออะไร? ไป! ฆ่า!" },
        completion = { "361:2069439382:1882348640", "หน่วยลาดตระเวนรายงานความสำเร็จของเจ้าแล้ว ทีนี้เราอาจฝึกต่อได้อย่างสงบ พวก Gelkis ต้องเรียนรู้ว่าที่นี่ และทั้ง Desolace เป็นของเซนทอร์สายเลือด Magram\n\nถ้าเจอตัวที่เหลือก็สับหัวเสียด้วย พวกมันจะได้กลัวจนไม่กล้ายื่นกีบออกจากกระท่อม\n\nอีกไม่นานที่นั่นก็จะเป็นของเรา" },
        objectiveLabels = {
            monster = { ["Outcast Necromancer slain"] = "ปราบ เนโครแมนเซอร์นอกเผ่า", ["Outcast Scout slain"] = "ปราบ หน่วยสอดแนมนอกเผ่า", ["Outcast Marauder slain"] = "ปราบ ผู้ปล้นสะดมนอกเผ่า" },
        },
    },
    [93122] = { -- Checking Things Out
        title = { "19:826785497:1478555845", "สำรวจสถานการณ์" },
        objective = { "182:423940539:1645703875", "รักษาระดับชื่อเสียงกับ Gelkis และตรวจจุดสำคัญของเซนทอร์ใน Shen'dralas จากนั้นนำสิ่งที่พบกลับไปรายงาน Nerlokh ที่ทางเข้า Valley of Bones" },
        description = { "459:657415106:1017941301", "เราทุกคนประเมินพลังและจำนวน Magram ในแถบนี้ต่ำไป แต่เรื่องนี้อาจเป็นข้อได้เปรียบ\n\nเมื่อคนมากมายติดภารกิจและไม่ยอมรับผู้ถูกขับไล่จากเผ่าอื่น ใครเหลือป้องกันหมู่บ้าน? แล้ว Khan ของพวกเขาล่ะ?\n\nข้าต้องการให้เจ้าเข้าไปในหุบเขาลึกกว่าที่เคย แล้วสำรวจ หาก Magram ตั้งมั่นที่นี่อย่างที่เห็น พวกมันอาจทิ้งหมู่บ้านให้เปราะบาง..." },
        completion = { "217:1516080291:994215589 N 38:1946351135:1357363356", "<เจ้าสรุปสิ่งที่พบ>\n\nมีถึงสองค่ายเลยหรือ\n\n<เจ้าอธิบายว่าค่ายหนึ่งเป็นของ Magram แน่นอน แต่อีกค่ายดูจะเป็นของพวกนอกเผ่า>\n\nถ้าอย่างนั้น Magram น่าจะกำลังสู้กับใครอยู่ {name} ข้าว่านี่อาจเป็นโอกาสของเรา" },
        steps = { { "28:664595241:1726574002", "สำรวจแนวหน้าของ Magram" }, { "32:260861844:2071975947", "สำรวจ Outcast Hideaway" } },
    },
    [93125] = { -- Going Home
        title = { "10:139825308:1648774075", "กลับบ้าน" },
        objective = { "154:1105523805:1803562881", "รักษาระดับชื่อเสียงกับ Gelkis และคุ้มกัน Rokren ออกจาก Outcast Hideaway จากนั้นแจ้ง Nerlokh ใกล้ Valley of Bones ว่าเกิดอะไรขึ้น" },
        description = { "453:125140389:276505254", "เจ้า! ข้าเห็นเจ้าสู้กับพวกนอกคอก ไม่รู้ว่ามาจากไหน แต่ข้าต้องการความช่วยเหลือ\n\nพี่น้อง Gelkis ล่อข้ามาที่นี่โดยรับรองความปลอดภัย ข้ารู้ว่าสงครามใน Desolace รุนแรงเกินควบคุม แต่ไม่คิดว่าพวกเดียวกันหันสู่วิชาปลุกศพด้วยแผนซับซ้อนเพื่อแปรพักตร์ไป Magram เมื่อข้าคัดค้าน พวกมันขู่ว่าจะฆ่าหากย่างกีบพ้นกระโจม!\n\nได้โปรดช่วยด้วย" },
        objectiveLabels = {
            reputation = { ["Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
            event = { ["Escort Rokren out of the Outcast Hideaway"] = "คุ้มกัน Rokren ออกจาก Outcast Hideaway" },
        },
    },
    [93129] = { -- Threat of Starvation
        title = { "20:1138285523:662427177", "ภัยจากความอดอยาก" },
        objective = { "105:639724007:300024924", "รักษาระดับชื่อเสียงกับ Magram และนำ Stolen Supplies 6 ชิ้นกลับไปให้ Hagiak ที่ Magram Front", amount = { "52:1491736042:485491818 W1 52:5448902:125653294", "รักษาระดับชื่อเสียงกับ Magram และนำ Stolen Supplies {world1} ชิ้นกลับไปให้ Hagiak ที่ Magram Front" } },
        description = { "405:1690336673:1964293202", "เมื่อเจ้ากระตือรือร้นช่วยเผ่าเหลือเกิน ข้ามั่นใจว่าคงยินดีขนเสบียงมาขณะอยู่ Outcast Hideaway\n\nการโค่นศัตรูน่าจะจูงใจ Magram พอแล้ว แต่ไม่เห็นเหตุผลที่เราจะหากำไรจากงานด้วยไม่ได้\n\nเมื่อจัดการพวกเนรเทศ เราจะยึดที่นี่ให้ Magram แล้วสร้างกองทัพให้เผ่าอื่นคุกเข่า!" },
        completion = { "330:143549507:2119851718", "<Hagiak ชะโงกดูในลังหลายใบโดยยังไม่พูดอะไร>\n\nบรรดาของที่เอามาแนวหน้าได้ ข้าไม่เคยนึกว่าจะเป็น... ช่างเถอะ บางลังมีอาหาร นั่นแหละสำคัญ เราตัดเวลาที่พวกมันจะอยู่รอดที่นี่ไปได้มาก\n\nชัยชนะครั้งสุดท้ายของเผ่าเราใกล้เข้ามาแล้ว" },
        progress = { "135:684125959:620116088", "สังหารทหารของพวกมัน แล้วปล่อยให้คนที่เหลืออดอยาก ที่ซ่อนเล็ก ๆ นั่นจะได้ใช้เป็นฐานตั้งทัพเล่นงานเผ่าเราไม่ได้อีก!" },
        required = { [256892] = { "15:1561291513:154504613", "เสบียงที่ถูกขโมย" } },
        steps = { { "15:1561291513:154504613", "เสบียงที่ถูกขโมย" } },
        objectiveLabels = {
            reputation = { ["Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [93188] = { -- Return to Orgrul
        title = { "16:1175435551:604738101", "กลับไปหา Orgrul" },
        objective = { "114:1041491813:1950971399", "รักษาระดับชื่อเสียงกับ Magram และกลับไปรายงาน Orgrul ใกล้ทางเข้าเหนือของ Valley of Bones" },
        description = { "286:1556654017:216551480", "เจ้าทำที่แนวหน้าพอแล้ว เราดูแลตัวเองได้\n\nบอก Orgrul ว่าเจ้าทำหน้าที่สำเร็จ Magram Front แข็งแกร่งขึ้น ตอนนักรบอีกกองเข้าร่วม เราเล็งค่ายพวกนอกคอกเป็นที่ตั้งถัดไป\n\nเอ้า? ไปได้แล้ว!" },
        completion = { "427:596682632:608644086", "ระหว่างที่เจ้าหายไปไม่นาน เกิดเรื่องน่าสนใจขึ้นใน Magram Village เป็นการก่อศึกที่คนนอกทำอย่างรอบคอบภายใต้ธง Gelkis\n\nถ้าเกิดขึ้นเมื่อไม่กี่เดือนก่อน ข้าคงสั่งประหารเจ้าและคนนอกทุกคนที่ไม่รู้อะไรแล้วยังมาหลอกลวงเผ่าของเรา\n\nแต่สถานการณ์นี้ต่างออกไป\n\nนี่คือโอกาสของเจ้า ของ Magram และของสงครามนี้" },
        objectiveLabels = {
            reputation = { ["Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Magram Clan Centaur"] = "ชื่อเสียงกับ Magram Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [93791] = { -- Speak with Belann
        title = { "17:107834799:302114916", "คุยกับ Belann" },
        objective = { "39:1795484782:4308795", "คุยกับ Belann Windwood ใน Valanaar" },
        description = { "N 365:1428769723:1866512341", "{name} เห็นชัดว่าฝีมือเวทเจ้าก้าวหน้า ข้าว่าถึงเวลาร่วมประเพณีเก่าแก่ที่สุดอย่างหนึ่งของ High Order สำหรับจอมเวทรุ่นเยาว์ผู้ใฝ่ก้าวหน้า ถึงเวลาสร้างสื่อรวมเวทของตนเอง\n\nหา Belann Windwood ใน Valanaar เขาทำไม้เท้ากับไม้กายสิทธิ์ให้ High Order มากว่าศตวรรษ เจ้าจะอยู่ในการดูแลที่ดี" },
        completion = { "16:1956901891:2074826166 N 140:1975018971:922231837", "อ้อ เจ้าคงเป็น {name} สินะ? ข้าชื่นใจที่เห็นจอมเวทรุ่นเยาว์อยากเรียนรู้วิถีและประวัติศาสตร์ของเรา มาสิ ข้าจะอธิบายขั้นตอนต่อไปในการทำสื่อรวมพลังเวทของเจ้า" },
    },
    [93797] = { -- Boughs in the Wind
        title = { "18:312835074:1171251064", "กิ่งไม้ในสายลม" },
        objective = { "58:1991729367:1446163002", "นำ Wind-Infused Bough ไปให้ Belann Windwood ใน Valanaar" },
        description = { "470:1737974398:436302903", "เป็นประเพณีเก่าแก่ให้จอมเวทรุ่นเยาว์สร้างสื่อรวมเวทเอง เมื่อแสดงความชำนาญระดับหนึ่ง ปกติทำโดยเก็บกิ่งที่ตกจากต้นไม้เก่าแก่ที่สุด เพราะยังมีร่องรอยธาตุลมอยู่\n\nข้าพบว่ากิ่งเหมาะที่สุดอยู่ใกล้ศาลแห่งสายลม ทางใต้ของ Falaath Village ไปนำกิ่งใหญ่มา แล้วข้าจะสอนประเพณีระหว่างสร้างสื่อรวมเวทให้" },
        progress = { "239:1369992345:1047430801", "ทุกปีที่ผ่านไปใน Zephras ผู้ที่มีพรสวรรค์ด้านเวทมนตร์ยิ่งเหลือน้อยลง\n\nข้าดีใจที่จอมเวทรุ่นเยาว์อย่างเจ้าเข้าร่วมประเพณีเก่าแก่ที่สุดของเรา เพื่อช่วยให้ประวัติศาสตร์และวัฒนธรรมของเราดำรงอยู่ต่อไป" },
        completion = { "11:1191658970:1224418299 N 251:1475182560:1578153212 C 88:1306063713:11676914", "ขอบใจ {name} ข้าสัมผัสพลังธาตุในกิ่งไม้นี้ได้จริง ๆ มันกำลังรอให้ผู้มีพรสวรรค์ดึงพลังออกมาใช้ กิ่งนี้จะเป็นสื่อรวมพลังเวทชั้นเยี่ยม\n\nกิ่งไม้นี้ส่งเสียงร้องเพลงให้เจ้าได้ยินหรือเปล่า? หลายครั้งกิ่งไม้เป็นฝ่ายเลือก {class} เอง\n\n<Belann หัวเราะเบา ๆ ขณะรับกิ่งไม้จากมือเจ้าอย่างทะนุถนอม>" },
        required = { [262668] = { "18:375665558:1225056509", "กิ่งไม้ที่อาบพลังลม" } },
        steps = { { "18:375665558:1225056509", "กิ่งไม้ที่อาบพลังลม" } },
    },
    [97286] = { -- Research Access
        title = { "15:1735145900:518937075", "สิทธิ์เข้าถึงงานวิจัย" },
        completion = { "98:677214391:1870493299", "การกระทำของเจ้าบอกว่าเจ้าเป็นคนที่เห็นค่าของความรู้ ห้องสมุดเปิดให้เจ้าใช้ศึกษาค้นคว้าได้แล้ว" },
        description = { "N 80:1641173314:2015906574", "{name} ดูท่าว่าเจ้าศึกษาศาสตร์เวทมนตร์อยู่ ห้องสมุดน่าจะเป็นประโยชน์กับเจ้า" },
    },
    [98576] = { -- Glyphic Parchment
        title = { "17:1341991591:787058562", "แผ่นคัมภีร์อักขระ" },
        objective = { "102:1994025209:992317945", "อ่าน Glyphic Parchment แล้วคุยกับ Mai'ah ใกล้ทางเข้า Den ใน Valley of Trials" },
        description = { "50:504738005:547472890 N 137:402670688:227345751", "อา ระหว่างเจ้าไม่อยู่ มีแผ่นคัมภีร์ส่งมาถึงเจ้า {name}\n\nว่างเมื่อไรก็อ่านเสีย ถ้าข้าจำไม่ผิด มันมาจากครูฝึกจอมเวท Mai'ah นางอยากคุยกับเจ้าเมื่อพร้อม" },
        progress = { "203:365035723:463581900", "เจ้ามาหา Mai'ah พร้อมเรียน ดีมาก เจ้ามีพลังแตะเส้นใยจักรวาล แต่ก็มีปัญญารู้ว่าต้องมีผู้ชี้นำ ข้าสอนก้าวแรกในการใช้พลังนั้นได้" },
        completion = { "361:1353706084:1161821524", "เวทที่ไหลในตัวเจ้าคือพลังยิ่งใหญ่ที่สุดในจักรวาล แต่ต้องอดทน รอจังหวะสมบูรณ์แบบ เลือกวิธีตอบปัญหาตรงหน้าให้ถูก หากฉลาดและสังเกตดี ไม่มีสิ่งใดที่ทำไม่ได้\n\nเมื่อคิดว่าพร้อมฝึก กลับมาหา Mai'ah นางจะสอนสิ่งที่พร้อมเรียน ไม่มีปัญหา" },
        required = { [282380] = { "17:1341991591:787058562", "แผ่นหนังลงอักขระ" } },
        steps = { { "17:1341991591:787058562", "แผ่นหนังลงอักขระ" } },
    },
    [4961] = { -- Cleansing of the Orb of Orahil
        title = { "30:754219448:1527036646", "ชำระลูกแก้ว Orahil" },
        objective = { "51:815278128:1703242794", "ฆ่า Demon of the Orb แล้วคุยกับ Tabetha" },
        description = { "359:1172826499:895686078 N 136:1540250979:118118679", "อา ลูกแก้วผู้อัญเชิญ ต้นตอความแปดเปื้อนสินะ ต้องขับปีศาจข้างในเพื่อใช้ ข้าทำได้ง่าย\n\nเจ้าต่างหากงานยาก ต้องฆ่าปีศาจเมื่อปล่อย\n\nและต้องเร็ว ช้าเกินจะกลับเข้าลูกแก้ว ต้องเริ่มใหม่!\n\nเตรียมตัว {name} จัดเวทแรงที่สุด ยาใกล้มือ และหาเพื่อนหากมี เพราะไม่น่าดูแน่" },
        progress = { "80:1349250676:993364399 N 1:46:46", "ต้องฆ่าปีศาจจึงลบตัวตนมันจากลูกแก้วถาวร {name}" },
        completion = { "13:96413020:153092913 N 199:488958674:1888989090 C 37:1709951343:778728629", "ทำดีมาก {name}! สอนบทเรียนที่ปีศาจไม่ลืมง่าย แสดงพลังและฝีมือมาก ทีนี้กลับ Menara พร้อมลูกแก้วชำระแล้ว เพื่อใช้ประโยชน์\n\nโชคดี {class} บางทีเราจะพบกันอีก" },
        objectiveLabels = {
            monster = { ["Demon of the Orb slain"] = "ปราบ ปีศาจในลูกแก้ว" },
        },
    },
    [1498] = { -- Path of Defense
        title = { "15:26900275:241173800", "วิถีแห่งการป้องกัน" },
        objective = { "64:1987776192:1698823233", "นำ Singed Scales 5 ชิ้นไปให้ Uzzek ที่ Far Watch Post ใน Barrens" },
        description = { "450:473714777:1139204217", "สำหรับนักรบ หนึ่งในหน้าที่สำคัญที่สุดของเราคือ... การปกป้อง เราคือโล่ของ Horde คอยคุ้มครองพี่น้องที่อ่อนแอกว่า หากจะเข้าร่วมกับเรา เจ้าต้องพิสูจน์ความแกร่งต่อข้า\n\nไป Thunder Ridge ใน Durotar ที่อยู่ของพวก Lightning Hide และ Thunder Lizard ล่าพวกมัน! แสดงว่าเจ้าแข็งแกร่งกว่า! ฝ่าการโจมตีแล้วนำเกล็ดไหม้ของมันมาหนึ่งกองเป็นหลักฐาน\n\nทำเช่นนี้ แล้วข้าจะสอนเจ้า" },
        progress = { "24:621774566:921358206 N 104:1706789253:1679080459", "มีเกล็ดมาหรือยัง {name}? หากทนการโจมตีของ Thunder Lizard ไม่ได้ คำสอนของข้าก็ช่วยเจ้าไม่ได้" },
        completion = { "210:1159776113:1565921712 N 38:983677209:2003677547", "อา ข้าเห็นว่าเจ้าปราบ Thunder Lizard ได้ นั่นพิสูจน์ความทรหดของเจ้า ทีนี้ข้าจะแสดงให้เห็นว่าผิวหนังอันทนทานกับการเคลื่อนไหวอย่างมีชั้นเชิงสร้างกำแพงป้องกันที่ทะลวงไม่ได้อย่างไร\n\nตั้งใจเรียนให้ดี {name} และเตรียมพร้อมสำหรับคำสอนในภายหน้า" },
        required = { [6486] = { "12:1758151318:1004909047", "เกล็ดไหม้เกรียม" } },
        steps = { { "12:1758151318:1004909047", "เกล็ดไหม้เกรียม" } },
    },
    [1502] = { -- Thun'grim Firegaze
        title = { "18:454415526:1379959889", "Thun'grim Firegaze" },
        objective = { "45:1130286613:936827525", "คุยกับ Thun'grim Firegaze ใน Barrens" },
        description = { "394:900459606:1675238532", "อาวุธที่มีคุณภาพเป็นสิ่งจำเป็นสำหรับนักรบ และหากมีออร์คผู้สร้างอาวุธชั้นดีได้ ผู้นั้นก็คือ Thun'grim Firegaze เขาปลีกวิเวกอยู่บนเนินทางตะวันออกของ Crossroads\n\nหากต้องการอาวุธ นักรบเอ๋ย จงไปหา Thun'grim ก่อนอื่นเดินทางไป Crossroads ทางตะวันตก แล้วมุ่งตะวันออกเข้าสู่เนินเขา ค่ายของเขาอยู่สูงบนยอดเนิน" },
        completion = { "193:296100670:17627359", "ดวงตาข้าแห้งผากไปนานแล้วจากการจ้องเปลวไฟในเตาหลอม แต่บางสิ่งข้ายังมองเห็น ข้าเห็นว่าเจ้าต้องการบางอย่าง\n\nและหากหาทางมาถึงที่นี่ได้ ข้าก็พอเดาความต้องการเจ้าออก" },
    },
    [1503] = { -- Forged Steel
        title = { "12:454278898:1729690011", "เหล็กกล้าหลอมขึ้นรูป" },
        objective = { "65:1159849576:1700736181", "นำ Forged Steel Bars ไปให้ Thun'grim Firegaze ใน Barrens" },
        description = { "26:428379012:910512164 N 459:2122016439:1023868281", "ข้าจะให้อาวุธเจ้า {name} แต่ต้องช่วยข้าก่อน พวก Razormane ทางตะวันตกเฉียงเหนือบุกค่ายข้าเมื่อไม่กี่คืนก่อน มันไม่กล้าสู้ แต่รู้ว่าข้าตาไม่ดี บางตัวส่งเสียงเบี่ยงความสนใจ ส่วนตัวอื่นก็ขโมยของ! พวกขี้ขลาด!\n\nมันเอาหีบเหล็กที่มีเหล็กกล้าหลอมขึ้นรูปอยู่ข้างในไป หากนำกลับมาได้ ข้าจะให้อาวุธที่เจ้าต้องการ\n\nค้นหาหีบเหล็กในค่ายควิลบอร์ แล้วกลับมาพร้อมเหล็กกล้าเหล่านั้น" },
        progress = { "26:1881008684:1675750845", "มีเหล็กกล้าของข้าหรือยัง?" },
        completion = { "160:635764140:386025107 N 45:1319326127:1959959529", "เจ้าพบมันแล้ว! และเหล็กก็อยู่ครบ ไม่แปลกใจนัก ข้าไม่คิดว่าพวก Razormane จะรู้วิธีใช้เหล็กกล้าชั้นดีเช่นนี้\n\nขอบใจ {name} นี่รางวัล ขอให้มันรับใช้เจ้าได้ดี" },
        required = { [6534] = { "17:1670314050:2142145378", "แท่งเหล็กกล้าที่ตีขึ้นรูป" } },
        steps = { { "17:1670314050:2142145378", "แท่งเหล็กกล้าที่ตีขึ้นรูป" } },
    },
    [1505] = { -- Veteran Uzzek
        title = { "13:2049814240:1618754621", "ทหารผ่านศึก Uzzek" },
        objective = { "35:551661475:231315643", "คุยกับ Uzzek ที่ Far Watch Post" },
        description = { "344:280321543:40546603", "Horde ยกย่องนักรบเพราะพละกำลังที่ไม่มีใครกังขา แต่นักรบผู้ยิ่งใหญ่จริงยังเป็นศิษย์ที่ดีด้วย\n\nไปหา Uzzek เขาผ่านศึกมากมาย และบัดนี้สอนวิชาต่อสู้ให้นักรบรุ่นใหม่ จะพบเขาทางใต้ของ Far Watch Post กองทหารออร์คตรงชายแดน Barrens กับ Durotar ทางตะวันออก", variants = { { "278:871885021:547628010 R 63:383102394:615648905", "Horde ยกย่องนักรบเพราะพละกำลังที่ไม่มีใครกังขา แต่นักรบผู้ยิ่งใหญ่จริงยังเป็นศิษย์ที่ดีด้วย\n\nไปหา Uzzek เขาผ่านศึกมากมาย และบัดนี้สอนวิชาต่อสู้ให้นักรบรุ่นใหม่ จะพบเขาทางใต้ของ Far Watch Post กองทหารชาว{race}ตรงชายแดน Barrens กับ Durotar ทางตะวันออก" } } },
        completion = { "53:1257748291:1817870105", "สวัสดี คนรุ่นใหม่ มาหาคำชี้แนะหรือ?" },
    },
    [1638] = { -- A Warrior's Training
        title = { "20:666503673:890605975", "การฝึกของนักรบ" },
        objective = { "27:1868854158:290588055", "คุยกับ Harry Burlguard" },
        description = { "49:894394441:1253381569 N 258:933698615:1809998028", "เจ้าพิสูจน์แล้วว่าเป็นนักรบมีฝีมือ {name} แต่ยังเยาว์และมีอีกมากให้เรียนรู้\n\nไปคุยกับ Harry Burlguard ปกติเขาอยู่โรงเตี๊ยม Pig and Whistle ใน Old Town ของ Stormwind Harry เป็นทหารผ่านศึกอาวุโสและครูที่ดี เขาสอนท่วงท่าสักสองสามอย่างที่จะช่วยให้เจ้ารอดชีวิตได้นานขึ้น" },
        completion = { "29:431694195:157070623 N 151:1660131333:827720389", "โอ้โฮ! มาดื่มกับข้า {name} ภายนอกดูแข็งแกร่ง แต่ต้องดูว่าท้องเจ้ารับเบียร์แรงที่สุดของ Pig and Whistle สักสองสามแก้วไหวไหม!!\n\nหรือว่า... มาหาบทเรียน?", variants = { { "183:1689432945:1426439933", "โอ้โฮ! มาดื่มกับข้าหน่อยสิ เจ้าหนุ่ม ท่าทางเจ้าอึดเอาเรื่อง แต่ต้องดูว่าท้องเจ้ารับเหล้าที่แรงที่สุดของร้าน Pig and Whistle สักสองสามเหยือกไหวไหม!\n\nหรือว่า... เจ้ามาเรียนวิชากันแน่?" }, { "184:1238919264:55539255", "โอ้โฮ! มาดื่มกับข้าสิ แม่สาวน้อย ภายนอกดูแข็งแกร่ง แต่ต้องดูว่าท้องเจ้ารับเบียร์แรงที่สุดของ Pig and Whistle สักสองสามแก้วไหวไหม!!\n\nหรือว่า... เจ้ามาให้ข้าสอนวิชากันแน่?" } } },
    },
    [1639] = { -- Bartleby the Drunk
        title = { "18:986431073:995718048", "Bartleby ขี้เมา" },
        objective = { "20:1487193259:998516263", "คุยกับ Bartleby" },
        description = { "233:1600258446:548904104", "ใช่ ข้าสอนเจ้าได้ แต่ก่อนอื่นอยากดูว่าเจ้ามีท่วงท่าอะไรอยู่แล้ว\n\nเห็นขี้เมาที่ปลายเคาน์เตอร์นั่นไหม? Bartleby น่ะ ข้าอยากให้เจ้าเอาแก้วเขามา\n\nฮ่า และถ้ารู้จัก Bartleby ก็คงรู้ว่าเขาไม่ยกให้เฉย ๆ หรอก" },
        completion = { { "119:244603088:1711145320", "120:1199600916:2100109592" }, "สวัสดี เจ้าสำอาง! คนบอบบางอย่างเจ้ามาทำอะไรใน Pig and Whistle? ระวังหน่อย เดี๋ยวเล็บจะหัก..." },
    },
    [1640] = { -- Beat Bartleby
        title = { "13:1792050989:1251896428", "เอาชนะ Bartleby" },
        objective = { "32:468062667:652130533", "เอาชนะ Bartleby แล้วคุยกับเขา" },
        description = { "109:1947341911:2059962787", "เจ้าต้องการอะไรนะ?? บ้าไปแล้ว!\n\nทางเดียวที่จะได้แก้วนี้ คือแกะมันออกจากนิ้วเย็นเฉียบของศพข้า..." },
        progress = { "79:426408165:1347086153", "ทางเดียวที่จะได้แก้วนี้ คือแกะมันออกจากนิ้วเย็นเฉียบของศพข้า..." },
        completion = { "35:850790445:84377068", "เจ้าแกร่งกว่าที่เห็นเยอะเลย!" },
        objectiveLabels = {
            event = { ["Beat Bartleby"] = "เอาชนะ Bartleby" },
        },
    },
    [1665] = { -- Bartleby's Mug
        title = { "14:1839992926:2068047398", "แก้วของ Bartleby" },
        objective = { "33:996333587:21644716", "นำ Bartleby's Mug ไปให้ Burlguard" },
        description = { "73:1214184078:1900677876", "ก็ได้ นี่แก้วข้า เดี๋ยว! ขอข้าดื่มที่เหลือให้หมดก่อน... เอาละ" },
        progress = { "65:989964173:1060422307", "ข้าเห็นเจ้าสู้กับ Bartleby ทำได้ดี! ได้แก้วเขามาไหม?" },
        completion = { "108:1757469348:5439228", "อยู่นี่เอง! เขาไม่อยากยกให้จริง ๆ แต่เจ้ากล่อมได้ดีมาก\n\nทีนี้มาถึงบทเรียนของเจ้า..." },
        required = { [6781] = { "14:1839992926:2068047398", "แก้วหูจับของ Bartleby" } },
        steps = { { "14:1839992926:2068047398", "แก้วหูจับของ Bartleby" } },
    },
    [1666] = { -- Marshal Haggard
        title = { "15:436719853:726159688", "Marshal Haggard" },
        objective = { "27:212494987:10735951", "คุยกับ Marshal Haggard" },
        description = { "349:1570508524:1783942891", "เจ้าเรียนท่วงท่ามาบ้างแล้ว แต่ยังต้องมีอาวุธดี ๆ ข้าว่าถ้าคุยกับ Marshal Haggard เขาคงช่วยได้\n\nMarshal Haggard อาศัยในคฤหาสน์ที่ Eastvale Lumber Camp ใน Elwynn Forest ตอนนี้เกษียณแล้ว แต่ตลอดชีวิตทหารเขาสะสมอุปกรณ์ไว้มาก\n\nบอกว่าข้าส่งมา หากโชคดีเขาอาจมีอาวุธเหลือให้เจ้า" },
        completion = { "159:1291329590:1381806564", "ใครน่ะ?\n\nBurlguard เจ้าหรือ?\n\nเข้ามาใกล้อีกหน่อย ตาข้าไม่ดีเหมือนก่อน\n\nเดินมาอย่างนั้น ข้านึกว่ากนอลล์เสียอีก!" },
    },
    [1667] = { -- Dead-tooth Jack
        title = { "15:1496610641:1262057779", "Dead-tooth Jack" },
        objective = { "84:1137179473:114296555", "นำ Haggard's Badge กลับมาจากค่ายของ Dead-tooth Jack แล้วกลับไปหา Marshal Haggard" },
        description = { "462:1817728003:348865577", "Burlguard ส่งเจ้ามาหรือ? ใช่ ข้ามีอาวุธเหลืออยู่แถวนี้ แต่มีงานให้ทำก่อน...\n\nก่อนหน้านี้วายร้าย Defias ชื่อ Dead-tooth Jack หลอกข้า ตอนนั้นมืดและมันสวมเสื้อคลุมตรา Stormwind ข้าจึงนึกว่า Marshal Dughan มันบอกว่าต้องการตราจอมพล Stormwind เก่าของข้า ข้าก็ให้ไป... แล้วมันหัวเราะวิ่งหนีก่อนจะจับได้!\n\nเอาตราข้าคืนมา! Dead-tooth Jack คงซ่อนไว้ในค่ายทางใต้" },
        progress = { "96:1147842365:233301401", "มีตราข้าหรือยัง? ไม่อยากคิดว่า Dead-tooth Jack จะใช้มันก่อเรื่องอะไรได้บ้าง" },
        completion = { "244:483671952:1721550089", "เยี่ยม เจ้าพบมันแล้ว! ข้ากลัวจะหายไปตลอดกาล ถูก Defias ใช้ปลอมตัวเป็นเจ้าหน้าที่ Stormwind ทีนี้คงไม่เกิดแล้ว ต้องขอบใจเจ้า\n\nนี่อาวุธที่ข้าเคยใช้ตอนเป็นจอมพล ดูแลไว้อย่างดี เลือกมาเลย!" },
        required = { [6782] = { "23:104129792:937768164", "ตราของจอมพล Haggard" } },
        steps = { { "23:104129792:937768164", "ตราของจอมพล Haggard" } },
    },
    [1678] = { -- Vejrek
        title = { "6:1634761623:2041375363", "Vejrek" },
        objective = { "52:2020593259:1270789740", "นำ Vejrek's Head ไปให้ Muren Stormpike ใน Ironforge" },
        description = { "374:716628595:1414019911", "หากอยากก้าวหน้าในหมู่นักรบ เจ้าต้องแกร่ง ข้าสอนท่วงท่าใหม่ได้ แต่ก่อนอื่นพิสูจน์ว่ารับมือศัตรูจริงได้\n\nVejrek คือโทรลล์ที่แกร่งที่สุดแถวนี้ และเป็นผู้ที่เจ้าต้องปราบ มีกระท่อมอยู่ตรงเชิงเขาทางใต้ของ Frostmane Hold\n\nนำหัว Vejrek มา แล้วข้าจะรู้ว่าเจ้ามีความกล้า" },
        progress = { "31:1606425666:307203296 N 10:961471505:1099808742 R 22:1036688799:660699032", "ไปกระท่อม Vejrek มาหรือยัง {name}? กลิ่นเหม็นชาว{race}ที่ข้าได้กลิ่นมาจากเจ้าหรือ?", variants = { { "31:1606425666:307203296 N 37:609051775:729513697", "ไปกระท่อม Vejrek มาหรือยัง {name}? กลิ่นเหม็นของโทรลล์ที่ข้าได้กลิ่นนี่มาจากเจ้าหรือ?" } } },
        completion = { "46:260652654:556744908 N 122:565644813:2080336344 C 90:1513143871:1291986485", "Vejrek น่าเกลียดจริง ๆ ว่าไหม? ทำดีมาก {name}! เจ้าพร้อมแล้ว มาเริ่มบทเรียนกัน...\n\nเจ้าอาจไม่รู้ แต่การป้องกันที่แข็งแกร่งสำคัญกับ{class}มาก มันช่วยให้ยังยืนหยัดต่อศัตรูที่โค่นคนอื่นได้ และนั่นคือสิ่งที่พันธมิตรต้องการจากเจ้า" },
        required = { [6799] = { "13:1038019948:1724981615", "ศีรษะของ Vejrek" } },
        steps = { { "13:1038019948:1724981615", "ศีรษะของ Vejrek" } },
    },
    [1679] = { -- Muren Stormpike
        title = { "15:1978526244:650307490", "Muren Stormpike" },
        objective = { "27:1319746426:811516158", "คุยกับ Muren Stormpike" },
        description = { "275:1526215487:1349638216", "สวัสดี นักรบ! เจ้ามีแววมาก แต่ยังต้องเรียนกลเม็ดอีกบ้าง และ Muren Stormpike ก็คือคนแคระที่จะสอนเจ้าได้\n\nพบ Muren ได้ที่ Hall of Arms ใน Military Ward ของ Ironforge ไปคุยเมื่อพร้อมเรียนรู้ความหมายของการเป็นนักรบ" },
        completion = { "4:1110228981:147916455 N 120:1413055991:2083714977", "อา {name} ข้าได้ยินพวกนักรบ Dun Morogh พูดถึงชื่อเจ้า หวังว่าคงไม่ได้เอาแต่หมกตัวอยู่ในโรงเบียร์นะ!" },
    },
    [1680] = { -- Tormus Deepforge
        title = { "16:591863962:176646603", "Tormus Deepforge" },
        objective = { "28:652583712:1145881994", "คุยกับ Tormus Deepforge" },
        description = { "207:2065218429:635271164", "เมื่อเรียนท่วงท่ามาบ้างแล้ว ก็ถึงเวลาหาอาวุธดี ๆ ไปคุยกับ Tormus Deepforge เขาทำอาวุธที่ข้ามั่นใจว่าเจ้าจะชอบได้\n\nจะพบ Tormus ที่ Great Forge ใน Ironforge นี่เอง" },
        completion = { "206:107911535:779135837 C 7:584299957:913771255", "Muren ส่งเจ้ามาหรือ? ใช่ ข้าทำอาวุธดี ๆ ให้ได้... แต่ก่อนทำ มีเรื่องอยากให้ช่วย\n\nไม่ต้องห่วง อันตรายมากและอาจถึงตาย เป็นงานแบบที่{class}ต้องการพอดี" },
    },
    [1681] = { -- Ironband's Compound
        title = { "19:752311973:111112201", "เขตโรงงานของ Ironband" },
        objective = { "60:23971368:881441890", "นำ Umbral Ore หนึ่งกองไปให้ Tormus Deepforge ใน Ironforge" },
        description = { "407:2043506234:824858224 N 83:1024023986:651279129", "Sturgy Ironband อาจารย์ของข้ามีโรงงานทางใต้ของ Helm's Bed Lake ใน Dun Morogh ตะวันออก เขาสอนตีเหล็กที่นั่น และฝีมือดีที่สุด\n\nแต่วันหนึ่งศิษย์คนหนึ่งนำแร่ประหลาดมาให้ อาจารย์เรียกมันว่าแร่อัมบรัลและอยากลองใช้ ทว่าไม่นานหลังแร่มาถึง... คนแคระ Dark Iron ก็บุกโรงงาน พวกมันฆ่าทุกคน!\n\nเข้าโรงงาน Ironband เถอะ {name} แก้แค้นให้อาจารย์ข้า และนำแร่อัมบรัลต้นเหตุเรื่องนี้กลับมา" },
        progress = { "66:1176978002:2010188347", "เข้าโรงงาน Ironband แล้วหรือ? พบแร่อัมบรัลไหม?" },
        completion = { "184:2007651083:1861987240 N 47:1918498185:465111634", "เจ้าพบมันแล้ว! ทำได้ดี!\n\nหวังว่าจะฆ่าคนแคระ Dark Iron ไปมากระหว่างค้นหา ข้าเกรงว่าโรงงาน Ironband คงไม่ใช่ที่สุดท้ายที่เราจะพบพวกมัน\n\nแต่ขอบใจสำหรับแร่นะ {name} ข้าอยากลองใช้และค้นหาคุณสมบัติของมันแล้ว" },
        required = { [6800] = { "10:606433346:1836677564", "แร่เงามืด" } },
        objectiveLabels = {
            item = { ["Umbral Ore"] = "แร่เงามืด" },
        },
    },
    [1682] = { -- Grey Iron Weapons
        title = { "17:856545394:1324374262", "อาวุธเหล็กสีเทา" },
        completion = { "98:2069911809:375184121 N 17:434898842:304005777", "นี่อาวุธที่เพิ่งยกจากทั่ง ทำจากแร่อัมบรัลใหม่ที่เจ้านำมา!\n\nเลือกมาได้เลย {name}!" },
    },
    [1683] = { -- Vorlus Vilehoof
        title = { "15:671605748:1479662037", "Vorlus Vilehoof" },
        objective = { "50:1802420039:1895380097", "นำ Horn of Vorlus ไปให้ Elanaria ใน Darnassus" },
        description = { "394:35994987:1499247783 N 50:257144701:774098309", "ก่อนจะสอนได้ เจ้าต้องแสดงความมุ่งมั่นให้ข้าเห็น\n\nเซเทอร์ Vorlus Vilehoof พบบ่อน้ำจันทราห่างไกลของเราทางตะวันออกเฉียงใต้ของ Ban'ethil Barrow Den ตอนนี้มันลงเล่นน้ำ ทำให้น้ำบริสุทธิ์แปดเปื้อนด้วยความโสโครก\n\nหา Vorlus ที่บ่อน้ำแล้วทำลายมัน นำเขาของมันมาเป็นหลักฐาน แล้วข้าจะเริ่มฝึกวิชานักรบขั้นสูงให้\n\nทางไปบ่อน้ำซ่อนอยู่มิดชิด {name} แต่หากจดจ่อและตื่นตัว เจ้าจะพบ" },
        progress = { "22:1446360177:817485048 N 43:1710312214:1909170225", "มีเขามาหรือยัง {name}? บ่อน้ำจันทราของเราพ้นจากปีศาจ Vorlus แล้วหรือ?" },
        completion = { "11:534428891:784080240 N 194:945490800:761321490", "ทำดีมาก {name} ยินดีที่รู้ว่า Vorlus พ่ายแพ้และบ่อน้ำจันทราสะอาดแล้ว และยินดีที่เห็นนักรบรุ่นใหม่อยากรักษา Teldrassil ที่รักให้พ้นความแปดเปื้อน\n\nทีนี้มาเริ่มฝึกกัน..." },
        required = { [6805] = { "14:263857302:1745572513", "เขาของ Vorlus" } },
        steps = { { "14:263857302:1745572513", "เขาของ Vorlus" } },
    },
    [1684] = { -- Elanaria
        title = { "8:1688847225:1732926391", "Elanaria" },
        objective = { "20:431152887:281810754", "คุยกับ Elanaria" },
        description = { "237:116541121:1291940537", "สวัสดี นักรบ ฝีมือเจ้าเพิ่มขึ้น แต่วิชาชีพนี้มีอะไรมากกว่าที่อาจคิด หากจะก้าวหน้าต่อ อีกไม่นานต้องหาครู\n\nนักรบ Elanaria อยู่ที่ Warrior's Terrace ใน Darnassus นางสอนเจ้าได้" },
        completion = { "21:424205032:671010760 N 145:1126435870:813495445 C 1:46:46", "ข้าขอต้อนรับ {name} ชื่อเจ้าเลื่องลือใน Darnassus เพราะมีแวว แต่เราจะได้รู้กันในไม่ช้าว่ามีใจเด็ดเดี่ยวพอจะเดินบนวิถี{class}หรือไม่" },
    },
    [1686] = { -- The Shade of Elura
        title = { "18:1650042533:1076845938", "เงาวิญญาณของ Elura" },
        objective = { "81:2080958129:956733749", "นำ Elunite Ore 8 กอง และ Medallion of Elura ไปให้ Elanaria ใน Darnassus" },
        description = { "23:1746025095:765080031 N 465:201387010:1773967710", "เจ้าเรียนรู้มากแล้ว {name} ทีนี้เราจะสร้างอาวุธให้ อาวุธของนักรบ\n\nเจ้าต้องเดินทางไป Darkshore\n\nนานมาแล้ว เรือชนโขดหินใกล้ประภาคาร Auberdine ลังแร่เอลูไนต์มากมายจึงกระจัดกระจายตามพื้นทะเล\n\nก่อนอื่นต้องปราบผู้พิทักษ์แร่ Shade of Elura ครั้งหนึ่งนางเป็นกัปตันเรือ แต่สาปตนเองให้ท่องห้วงลึกและปกป้องสินค้าตลอดกาล ปราบนาง เอาเหรียญตรามา แล้วรวบรวมลังแร่เอลูไนต์ที่สูญหาย" },
        progress = { "38:1546389022:1545656094 N 39:1146176628:273242629", "ปราบ Shade of Elura แล้วหรือ {name}? และมีแร่เอลูไนต์ที่สูญหายไหม?" },
        completion = { "14:765600965:214150388 N 124:968014120:802103926", "ทำได้กล้าหาญมาก {name}\n\nเจ้ามอบความสงบที่ Shade of Elura สมควรได้รับ เราจะใช้แร่เอลูไนต์ที่รวบรวมมาสร้างอาวุธชั้นดีให้เจ้า" },
        required = { [6808] = { "11:802498718:1843213701", "แร่ Elunite" }, [6809] = { "17:412054517:1072880267", "เหรียญตราของ Elura" } },
        steps = { { "11:802498718:1843213701", "แร่ Elunite" }, { "17:412054517:1072880267", "เหรียญตราของ Elura" } },
    },
    [1692] = { -- Smith Mathiel
        title = { "13:2012928149:66909092", "ช่างตีเหล็ก Mathiel" },
        objective = { "43:86044766:1279666978", "นำ Case of Elunite ไปให้ Smith Mathiel" },
        description = { "192:1297107746:90612147", "ข้าใส่แร่เอลูไนต์ที่เจ้ารวบรวมมาไว้ในกล่องแล้ว นำไปให้ช่างตีเหล็ก Mathiel เขาจะสร้างอาวุธเอลูไนต์ให้\n\nMathiel อยู่ทางใต้ อีกด้านของอาคารนี้" },
        progress = { "17:1545238973:664863442 C 32:1419304010:1613543586", "สวัสดี {class}รุ่นเยาว์ ฝีมือข้าจะรับใช้เจ้าได้อย่างไร?" },
        completion = { "174:1682608342:1536583664", "อา แร่เอลูไนต์ เป็นโลหะชั้นดี เพราะได้รับพรจากเทพี Elune ด้วยพระองค์เอง การสร้างอาวุธจากมันถือเป็นเกียรติ\n\nโปรดรอระหว่างข้าทำงาน..." },
        required = { [6812] = { "15:436692593:508155076", "กล่องบรรจุ Elunite" } },
        steps = { { "15:436692593:508155076", "กล่องบรรจุ Elunite" } },
    },
    [1693] = { -- Weapons of Elunite
        title = { "18:1718459897:983918163", "อาวุธแห่งเอลูไนต์" },
        completion = { "N 181:488790217:1392819363", "{name} ข้าสร้างอาวุธเหล่านี้จากแร่เอลูไนต์ที่เจ้านำมาแล้ว โปรดเลือกชิ้นที่เหมาะที่สุด\n\nและข้าต้องขอบใจเจ้า การได้ใช้แร่เอลูไนต์เป็นทั้งเกียรติและความยินดี" },
    },
    [1698] = { -- Yorus Barleybrew
        title = { "16:2069347666:388974948", "Yorus Barleybrew" },
        objective = { "28:261290121:1043608012", "คุยกับ Yorus Barleybrew" },
        description = { "182:1462779911:52219188", "Yorus Barleybrew ท้านักรบผู้มีฝีมือทุกคนของ Alliance เขารออยู่ที่ Lakeshire Inn ใน Redridge และสัญญาจะมอบรางวัลใหญ่ให้ผู้ผ่านบททดสอบ" },
        completion = { "130:468100953:954653542", "ฮ่า! ได้ยินคำท้าข้าแล้วสินะ?\n\nนั่งลงแล้วฟัง ดื่มสักแก้ว ลิ้มรสให้ดี... เพราะอาจเป็นแก้วสุดท้ายของเจ้า" },
    },
    [1699] = { -- The Rethban Gauntlet
        title = { "20:458474938:1101649138", "บททดสอบฝ่า Rethban" },
        objective = { "146:1986069967:1152645152", "เข้า Rethban Caverns ไปถึงทางแยกแรก แล้วกลับไปหา Yorus Barleybrew ภายในเวลาที่กำหนด\n\nห้ามตายและปล่อยวิญญาณ" },
        description = { "490:1734802863:915505017", "ข้าเรียกบททดสอบนี้ว่า Rethban Gauntlet จะผ่านได้เพียงเข้า Rethban Caverns ถึงทางแยกแรกแล้วกลับมาที่นี่ ง่าย! เว้นแต่มีเรื่องยุ่งนิดหน่อย...\n\nเจ้าต้องกลับมาภายในหนึ่งชั่วโมง\n\nระหว่างทางมีกนอลล์ Redridge อยู่เพียบ\n\nก่อนเริ่ม เจ้าต้องดื่มสุราสูตรประจำตระกูลข้า Barleybrew Scalder สักอึก!\n\nว่าอย่างไร? Rethban Caverns อยู่เชิงเขาทางเหนือของ Lakeshire พร้อมฝ่าบททดสอบ Rethban แล้วหรือยัง?" },
        progress = { "17:694409669:2090443941 N 33:1012077195:1250837726", "เวลาไม่คอยนะ {name} หากเป็นข้าคงออกเดินทางแล้ว..." },
        completion = { "41:1358868662:366627446 N 1:33:33", "เจ้าทำได้! ยอดเยี่ยม! ไชโยให้ {name} สามครั้ง!" },
        objectiveLabels = {
            event = { ["Enter the Rethban Caverns"] = "เข้าไปในถ้ำ Rethban" },
        },
    },
    [1700] = { -- Grimand Elmore
        title = { "14:1540297760:911136747", "Grimand Elmore" },
        objective = { "38:458257791:1787526337", "นำ Furen's Notes ไปให้ Grimand Elmore" },
        description = { "302:741530582:834796319", "ข้าคัดบันทึกเทคนิคที่ได้เรียนรู้ตอนสร้างเกราะให้เจ้า และต้องส่งให้ Grimand Elmore เขาอยู่ร้านอาวุธใน Dwarven District นี่เอง\n\nตอนยื่นให้ก็ก้มหัวหลบหน่อย เขาภูมิใจฝีมือตนเองมาก คงไม่ชอบความคิดที่ว่าต้องเรียนอะไรจากข้า..." },
        progress = { "54:669685136:940071052", "สวัสดี ยินดีที่ได้พบ ข้ารับใช้ท่านได้อย่างไร?" },
        completion = { "199:252437050:735025234", "Furen เขียนนี่หรือ? กล้าดีอย่างไร! ข้าต่างหากสอนทุกอย่างที่เขารู้! คิดจะมาสอนข้ามันเหลวไหล! เหลวไหลที่สุด!\n\nหืม... แต่ในบันทึกเขามีบางอย่างที่ข้าอยากลอง..." },
        required = { [6926] = { "13:531981081:1461791013", "บันทึกของ Furen" } },
        objectiveLabels = {
            item = { ["Furen's Notes"] = "บันทึกของ Furen" },
        },
    },
    [1701] = { -- Fire Hardened Mail
        title = { "18:441840258:634827645", "เกราะถักชุบแข็งด้วยไฟ" },
        objective = { "82:812517819:1441195148", "รวบรวมวัสดุที่ Furen Longbeard ต้องการ แล้วนำไปให้เขาใน Stormwind" },
        description = { "253:325327094:600142326 N 97:500160235:1480471106", "ข้าให้โล่ดี ๆ ไปแล้ว แต่ไม่จำเป็นต้องหยุดแค่นั้น ข้ารู้เคล็ดลับสร้างเกราะถักที่แข็งแกร่งมาก ไม่ง่ายและใช้วัสดุหายาก แต่หากยอมออกตามหา ข้าจะทำให้สักชิ้น\n\nว่าอย่างไร {name}? หากรับคำท้า ข้าจะให้รายการว่าต้องหาอะไรและที่ไหน" },
        progress = { "29:685142217:786402414 N 28:744074283:989073279", "การตามหาของเป็นอย่างไร {name}? มีวัสดุหรือยัง?" },
        completion = { "120:253633653:1061639040", "ได้ครบแล้วหรือ? น่าทึ่ง! ข้านึกว่าไคมีราจะกินเจ้าไปแล้วแน่ ๆ!\n\nมาเริ่มทำเกราะกัน..." },
        required = { [6838] = { "20:1229015220:165839006", "เขี้ยวแมงมุมไหม้เกรียม" }, [6839] = { "12:1291957213:737838064", "เขาสัตว์ไหม้เกรียม" }, [6840] = { "15:968638351:1181794772", "เขาสัตว์ชุบโลหะ" }, [6841] = { "18:887915042:531421932", "ขวดบรรจุ Phlogiston" } },
        steps = { { "20:1229015220:165839006", "เขี้ยวแมงมุมไหม้เกรียม" }, { "12:1291957213:737838064", "เขาสัตว์ไหม้เกรียม" }, { "15:968638351:1181794772", "เขาสัตว์ชุบโลหะ" }, { "18:887915042:531421932", "ขวดบรรจุ Phlogiston" } },
    },
    [1702] = { -- The Shieldsmith
        title = { "15:833956031:559248759", "ช่างทำโล่" },
        objective = { "45:91115989:44993292", "นำ Cask of Scalder ไปให้ Furen Longbeard" },
        description = { "75:500834553:309794108 N 338:586866218:1211118014", "เจ้าพิสูจน์ความแกร่งตอนฝ่า Rethban Gauntlet แล้ว {name} และข้ารักษาคำพูด จะมอบรางวัลที่สัญญาให้...\n\nเพียงแต่มันอยู่ Stormwind\n\nคุยกับ Furen Longbeard สหายข้าใน Dwarven District ของ Stormwind เขาคือช่างทำโล่ที่ดีที่สุดที่เจ้าจะพบ และติดหนี้บุญคุณข้าครั้งใหญ่\n\nนี่ นำ Barleybrew Scalder ถังนี้ไปให้ Furen แล้วขอโล่ เขาจะให้ชิ้นดีแน่นอน" },
        progress = { "34:1318665178:1762263401", "สวัสดี! ช่วงนี้คอแห้งจริง ว่าไหม?" },
        completion = { "152:949335503:1839598406", "อา Barleybrew Scalder ของดี! ไปพบ Yorus มาแล้วสินะ?\n\nได้ ข้าหาโล่ให้ได้แน่นอน! เจ้าจะไม่พบชิ้นที่ดีกว่านี้ ข้าไม่ได้โกหก!", variants = { { "154:68203339:339820419", "อา Barleybrew Scalder ของดี! ไปพบ Yorus มาแล้วสินะ?\n\nได้ ข้าหาโล่ให้ได้แน่นอน! เจ้าจะไม่พบชิ้นที่ดีกว่านี้ ข้าไม่ได้โกหก!" } } },
        required = { [6843] = { "15:204334745:2140801684", "เหล้า Scalder หนึ่งถังเล็ก" } },
        steps = { { "15:204334745:2140801684", "เหล้า Scalder หนึ่งถังเล็ก" } },
    },
    [1703] = { -- Mathiel
        title = { "7:323772564:693131569", "Mathiel" },
        objective = { "31:1447647505:791505253", "นำ Furen's Notes ไปให้ Mathiel" },
        description = { "241:826200598:1280055650", "ข้าคัดบันทึกเทคนิคที่ได้เรียนรู้ตอนสร้างเกราะให้เจ้า และต้องส่งให้ช่างตีเหล็ก Mathiel เขาอยู่ Darnassus ซึ่งไกลทีเดียว แต่ข้าแน่ใจว่าเขาจะยินดีมากที่ได้เรียนสิ่งที่ข้าเรียนรู้" },
        progress = { "21:424205032:671010760 C 1:46:46", "ข้าขอต้อนรับ {class}" },
        completion = { "120:1629318663:34780833 N 70:790718726:526687214", "น่าสนใจ น่าสนใจมากจริง ๆ Furen เพื่อนร่วมอาชีพคนแคระค้นพบสิ่งยิ่งใหญ่ทีเดียว!\n\nขอบใจ {name} เป็นเกียรติที่จะนำเทคนิคใหม่ของเขามาใช้กับงานข้า" },
        required = { [6926] = { "13:531981081:1461791013", "บันทึกของ Furen" } },
        steps = { { "13:531981081:1461791013", "บันทึกของ Furen" } },
    },
    [1704] = { -- Klockmort Spannerspan
        title = { "21:1478454914:722633394", "Klockmort Spannerspan" },
        objective = { "45:1480083571:443283791", "นำ Furen's Notes ไปให้ Klockmort Spannerspan" },
        description = { "263:2031690758:1608175116", "ข้าคัดบันทึกเทคนิคที่ได้เรียนรู้ตอนสร้างเกราะให้เจ้า และต้องมีคนนำไปให้ Klockmort Spannerspan เขาเป็นช่างตีเหล็กโนมใน Ironforge เมื่อรู้สิ่งที่ข้าค้นพบ... พนันได้เลยว่าเขาจะตื่นเต้นจนทึ้งหนวดตัวเองหลุด" },
        progress = { "97:1444273179:1454405002", "สวัสดีตอนกลางวัน หรือเช้า หรือเย็น อยู่ลึกลงมาอย่างนี้ข้าดูไม่ออกหรอก มีธุระกับข้าหรือ?" },
        completion = { "222:1348908626:969197248", "โอ้! บันทึกนี่น่าทึ่ง! ยิ่งกว่านั้น... เหลือเชื่อ มหัศจรรย์ จนข้าเข่าอ่อนไปหมด!\n\nFuren ค้นพบครั้งใหญ่แล้ว! ครั้งใหญ่จริง ๆ! ข้าแทบรอลองเทคนิคใหม่ของเขาไม่ไหว!" },
        required = { [6926] = { "13:531981081:1461791013", "บันทึกของ Furen" } },
        steps = { { "13:531981081:1461791013", "บันทึกของ Furen" } },
    },
    [1705] = { -- Burning Blood
        title = { "13:1337269453:160876573", "โลหิตร้อนระอุ" },
        objective = { "82:1153000848:249058945", "นำ Burning Blood 20 ขวด และ Burning Rock 1 ก้อนไปให้ Grimand Elmore ใน Stormwind" },
        description = { "169:990447185:1579943071 N 298:176566374:2140761807 N 1:46:46", "ข้าไม่อยากยอมรับว่า Furen อาจค้นพบบางอย่างจริง แต่ต้องลองเทคนิคเขากับเกราะใหม่ให้แน่ใจ หากช่วยหาวัสดุ {name} เจ้าจะได้เกราะนั้น\n\nต้องมีตัวอย่างเลือดร้อนระอุและหินร้อนระอุ\n\nที่เดียวที่ข้ารู้ว่าหาได้คือ Duskwood พวกเวอร์เกน Nightbane ที่ตั้งหลักในเหมือง Roland's Doom มีเลือดร้อนระอุ ส่วน Gutspill ผู้นำของมันมีหิน\n\nขอโชคช่วยให้เดินทางรวดเร็ว {name}" },
        progress = { "N 79:1744256093:1220380461", "{name} มีเลือดกับหินร้อนระอุหรือยัง? ข้าต้องใช้ทำเกราะให้เสร็จ" },
        completion = { "68:1253891903:2131766659", "ทำได้ดี! ทีนี้ขอตัว ข้าเองก็มีงานต้องทำ..." },
        required = { [6844] = { "13:1337269453:160876573", "เลือดเดือดพล่าน" }, [6845] = { "12:1120944647:1332294807", "หินลุกไหม้" } },
        steps = { { "13:1337269453:160876573", "เลือดเดือดพล่าน" }, { "12:1120944647:1332294807", "หินลุกไหม้" } },
    },
    [1706] = { -- Grimand's Armor
        title = { "15:552341775:1502432401", "เกราะของ Grimand" },
        completion = { "133:1770080845:473176336 N 124:907443568:1549074908", "แทบไม่อยากเชื่อ! เทคนิคของ Furen สำเร็จ เกราะนี้น่าจะทนแรงกดดันมหาศาลได้\n\nนี่ {name} และขอบใจ หากเจ้าไม่หาวัสดุให้ข้าลองเอง ข้าคงไม่เชื่อการค้นพบของ Furen" },
    },
    [1708] = { -- Iron Coral
        title = { "10:1698905533:638067275", "ปะการังเหล็ก" },
        objective = { "70:701549191:1136340896", "นำ Searing Coral 20 กองไปให้ Klockmort Spannerspan ใน Ironforge" },
        description = { "393:1339370705:1355452268 N 56:983952286:365204067", "ข้าอยากลองเทคนิคใหม่ของ Furen Longbeard กับเกราะที่ทำเอง เพราะเจ้าช่วย Furen และเขาช่วยข้า เจ้ารับเกราะได้เลยหลังทำเสร็จ!\n\nต้องมีปะการังพิเศษ Searing Coral เพื่อทำให้เสร็จ มันขึ้นที่เดียว ตามชายฝั่งใต้ Menethil Harbor ใน Wetlands\n\nนำมาให้พอ ข้าจะเริ่มทำเกราะทันที รีบด้วยนะ {name} ข้าอยากเริ่มจนปลายเท้าบิดไปหมดแล้ว!" },
        progress = { "13:2032203351:739554239 N 61:1801551177:460432527", "สวัสดี ๆ {name}! มี Searing Coral หรือยัง? ข้าแทบรอเริ่มงานไม่ไหว!" },
        completion = { "214:1126071128:1555430261", "ใช่อันนี้! ทำได้ดี! ให้ข้าหลอมแล้วตีมัน เพื่อผสานเทคนิคของ Furen กับของข้า แล้วเราจะเห็นผลกัน!\n\nโอ้ โอ้! ข้ารู้เลยว่าเกราะจะต้องแข็งแกร่งมาก มาก มาก!" },
        required = { [6848] = { "13:1069549586:1512391011", "ปะการังร้อนจัด" } },
        steps = { { "13:1069549586:1512391011", "ปะการังร้อนจัด" } },
    },
    [1709] = { -- Klockmort's Creation
        title = { "20:1605772859:2686545", "ผลงานของ Klockmort" },
        completion = { "19:943037866:1007744550 N 161:1580906850:1939688393", "นี่เกราะเจ้า {name} วิธีของ Furen ได้ผลยอดเยี่ยม! สมบูรณ์แบบ! มหัศจรรย์จริง ๆ!\n\nต่อให้เอาเครื่องจักรล้อมเมืองทับ เกราะนี้ก็คงเด้งกลับเข้ารูปเดิม!" },
    },
    [1710] = { -- Sunscorched Shells
        title = { "18:293508807:876071496", "เปลือกไข่เกรียมแดด" },
        objective = { "52:488358605:1440227972", "นำ Sunscorched Shells 20 ชิ้นไปให้ Mathiel ใน Darnassus" },
        description = { "493:13154188:1582846891", "Furen Longbeard เพื่อนร่วมอาชีพของข้าค้นพบบางอย่างที่ข้าอยากทดสอบ ข้าอยากลองกับเกราะใหม่ที่กำลังวิจัย เพราะเชื่อว่าเทคนิคของเขาจะให้ผลเหนือกว่า\n\nจะช่วยไหม? หากรวบรวมของที่ข้าต้องใช้ทำเกราะ ข้าจะทำเพิ่มให้เจ้าชิ้นหนึ่ง\n\nข้าต้องการเปลือกไข่เกรียมแดดของ Highperch Wyvern ที่อยู่ Highperch ใน Thousand Needles ค้นหาเปลือกใต้รัง แล้วกลับมาหาข้าเมื่อได้พอ" },
        progress = { "24:950145717:762091121 N 110:1287001896:1243960379", "มีเปลือกไข่หรือยัง {name}? มันแข็งแรงมาก แปรรูปเป็นน้ำยาเคลือบที่ข้าจะใช้เคลือบห่วงเกราะถักใหม่ได้" },
        completion = { "91:816444204:1359910464", "อา ขอบใจ ใช้งานได้ดีแน่นอน!\n\nข้าจะเริ่มสร้างเกราะทันที..." },
        required = { [6849] = { "17:719755262:72259587", "เปลือกไหม้แดด" } },
        objectiveLabels = {
            item = { ["Sunscorched Shell"] = "เปลือกไหม้แดด" },
        },
    },
    [1711] = { -- Mathiel's Armor
        title = { "15:2106913591:806957480", "เกราะของ Mathiel" },
        completion = { "188:84584367:1039348421 N 48:1876248066:1956620242", "ข้าทำเกราะเจ้าเสร็จแล้ว พอใจทีเดียว เทคนิคใหม่ของ Furen ผสานกับของข้าได้สมบูรณ์ และแน่ใจว่าเกราะนี้จะทนทานมาก\n\nขอบใจ {name} ขอให้มันรับใช้เจ้าได้ดีในการศึกภายหน้า" },
    },
    [1712] = { -- Cyclonian
        title = { "9:686034811:1236937193", "Cyclonian" },
        objective = { "79:1767959005:1902549655", "นำสิ่งของที่ระบุใน Bath'rah's Parchment ไปให้ Bath'rah the Windwatcher ใน Alterac" },
        description = { "492:1886040683:238063931", "ข้าเฝ้าสถานที่นี้มานาน เฝ้าเพื่อว่าวันหนึ่งจะได้เห็น Cyclonian ผู้ยิ่งใหญ่พ่ายแพ้ แต่ยังไม่พบผู้กล้าปราบจ้าวแห่งลม\n\nบางทีเจ้าอาจเป็นผู้กล้านั้น\n\nพิสูจน์ให้ข้าเห็น รวบรวมสิ่งของที่ต้องใช้อัญเชิญ Cyclonian แล้วข้าจะรู้ว่าเจ้าเป็นนักรบยิ่งใหญ่ บางทีจากนั้นอาจปราบเขาและได้หัวใจลมหมุนมา\n\nหากทำได้ ข้าจะใส่พลังหัวใจลงในอาวุธ แล้วมอบอาวุธนั้นให้เจ้า\n\nนี่แผ่นหนังระบุสิ่งที่ข้าต้องการ" },
        progress = { "23:488881855:689886956 N 82:678021967:815505905", "มีของหรือยัง {name}? การรวบรวมมันคือหลักฐานที่ข้าต้องการว่าเจ้าแข็งแกร่งพอเผชิญ Cyclonian" },
        completion = { "184:794600024:1634058390", "เจ้ารวบรวมของสำหรับเวทข้าแล้ว แสดงทั้งกำลังและไหวพริบ แต่ขั้นต่อไปอันตรายยิ่งกว่า\n\nหวังว่ากำลังเจ้าจะไม่ถดถอย" },
        required = { [3901] = { "15:1560483938:906245210", "งาของเผ่า Bloodscalp" }, [3357] = { "8:1268324434:1565187757", "สมุนไพร Liferoot" }, [6851] = { "20:2060326639:2122628462", "แก่นพลังของผู้ถูกเนรเทศ" } },
        steps = { { "15:1560483938:906245210", "งาของเผ่า Bloodscalp" }, { "8:1268324434:1565187757", "สมุนไพร Liferoot" }, { "20:2060326639:2122628462", "แก่นพลังของผู้ถูกเนรเทศ" } },
    },
    [1713] = { -- The Summoning
        title = { "13:790690511:950357836", "การอัญเชิญ" },
        objective = { "50:213748039:1032334442", "นำ Whirlwind Heart ไปให้ Bath'rah Windwatcher" },
        description = { "185:356544302:704777655 N 38:873697274:985254185", "ข้าพร้อมทำพิธีอัญเชิญ Cyclonian เมื่อเรียกมาแล้ว เจ้าต้องปราบเขาและเอาหัวใจลมหมุนมา ข้าจะใช้มันใส่พลัง Cyclonian ลงในอาวุธ\n\n{name} พร้อมเผชิญจ้าวแห่งลมแล้วหรือยัง?" },
        progress = { "N 34:1312636844:209331580", "{name} ข้าต้องมีหัวใจลมหมุน!" },
        completion = { "66:1696071758:2068833663", "เจ้าทำได้! ปราบ Cyclonian และได้ Whirlwind Heart มาแล้ว!" },
        required = { [6894] = { "15:637138006:1535893893", "หัวใจวายุหมุน" } },
        steps = { { "15:637138006:1535893893", "หัวใจวายุหมุน" } },
    },
    [1714] = { -- Essence of the Exile
        title = { "20:2060326639:2122628462", "แก่นแท้ของผู้ถูกเนรเทศ" },
        progress = { "42:922521040:703693810", "ของเหลวในหม้อเดือดปุด ไอระเหยเชื้อเชิญ..." },
        completion = { "167:812591529:915450560", "เครื่องรางค่อย ๆ จมสู่ก้นหม้อ...\n\nฟองใหญ่ลอยขึ้นสู่ผิวของเหลวแล้วแตก...\n\n...เผยก้อนหินหลอมเหลวที่ปั่นป่วนอยู่" },
        description = { "42:922521040:703693810", "ของเหลวในหม้อเดือดปุด ไอระเหยเชื้อเชิญ..." },
        required = { [4479] = { "13:1335950282:446144278", "เครื่องรางเปลวไฟ" }, [4480] = { "16:554352811:718725174", "เครื่องรางสายฟ้า" }, [4481] = { "14:837082525:922721981", "เครื่องรางคลื่นซัด" } },
        objectiveLabels = {
            item = { ["Burning Charm"] = "เครื่องรางเปลวไฟ", ["Thundering Charm"] = "เครื่องรางสายฟ้า", ["Cresting Charm"] = "เครื่องรางคลื่นซัด" },
        },
    },
    [1718] = { -- The Islander
        title = { "12:149810791:637700880", "ผู้คนแห่งเกาะ" },
        objective = { "27:798169803:10805483", "คุยกับ Klannoc Macleod" },
        description = { "32:821438408:1338169407 N 451:2123482393:1184502488", "ชื่อเสียงนักรบของเจ้าเพิ่มขึ้น {name} ถึงเวลาประลองกับผู้ร่วมวิถีเพื่อดูฝีมือตนแล้ว\n\nมีเกาะนอกฝั่ง Barrens ทางใต้ของ Ratchet ชื่อ Fray Island เป็นที่ที่นักรบมาพบกัน\n\nพบกัน และต่อสู้\n\nคุยกับ Klannoc Macleod หัวหน้านักรบ Fray Island หากเห็นว่าเจ้าคู่ควร Klannoc จะนำทางบนวิถีนักรบต่อไป\n\nไป Fray Island โดยมองหาสันทรายน้ำตื้นตาม Merchant Coast" },
        completion = { "97:1789418153:27869050", "สวัสดี นักรบ ดีใจที่เจ้ามาถึง Fray Island หวังว่าจะชอบที่นี่..." },
    },
    [1719] = { -- The Affray
        title = { "10:221568795:89596962", "ศึกประลอง" },
        objective = { "60:373988926:998895013", "ฆ่า Big Will แล้วคุยกับ Klannoc Macleod บน Fray Island" },
        description = { "477:270975236:1673872878", "หากอยากเรียนกับข้า ต้องผ่าน The Affray ก่อน เป็นคำท้าที่เราบน Fray Island ชอบมอบให้นักรบหน้าใหม่ซึ่งคิดว่าตนแกร่ง หากผ่านได้ข้าก็จะรู้ว่าแกร่งจริง\n\nเริ่มโดยเดินเข้าไปกลางฝูงชนตรงนั้น แล้วยืนบนตะแกรง Twiggy Flathead จะรู้ว่าเจ้าพร้อม และส่งผู้ท้าชิงมาสู้\n\nเอาชนะทุกคน แล้วเขาจะเรียก Big Will ฆ่า Big Will แล้วกลับมาหาข้าภายในเวลาที่เราให้" },
        progress = { "34:826656602:249637892", "ผ่านบททดสอบแล้วหรือ?" },
        completion = { "11:534428891:784080240 N 88:1527057924:1999835649", "ทำได้ดี {name} เจ้าผ่าน The Affray แล้ว!\n\nเจ้าเป็นนักรบที่คู่ควร ข้าเป็นเกียรติที่จะได้สอน..." },
        objectiveLabels = {
            event = { ["Step on the grate to begin the Affray"] = "เหยียบตะแกรงเพื่อเริ่มการประลอง" },
            monster = { ["Big Will slain"] = "ปราบ Big Will" },
        },
    },
    [1782] = { -- Furen's Armor
        title = { "13:1852388342:1934884753", "เกราะของ Furen" },
        completion = { "19:943037866:1007744550 N 369:268536043:369168726", "นี่เกราะเจ้า {name} มันจะทนการโจมตีที่แรงที่สุดได้ ไม่อย่างนั้นข้าคงไม่ได้ชื่อ Furen Longbeard!\n\nและข้าต้องขอบใจเจ้า ได้เรียนรู้มากขณะใช้วัสดุที่เจ้านำมา คิดว่าสักวันจะมีการค้นพบครั้งใหญ่อีก!\n\nข้าจะส่งสิ่งที่เรียนรู้ให้ช่างตีเหล็กคนอื่นของ Alliance\n\nจะบอกว่าเจ้าช่วยมาก บางทีพวกเขาอาจอยากตอบแทน" },
    },
    [1791] = { -- The Windwatcher
        title = { "15:1927714057:1705198494", "ผู้เฝ้าสายลม" },
        objective = { "36:1114859802:1956660506", "คุยกับ Bath'rah the Windwatcher" },
        description = { "429:393670980:676696397", "เมื่อเรียนท่วงท่าเบอร์เซิร์กเกอร์แล้ว เจ้าคงต้องการอาวุธดี ๆ ไว้ใช้คู่กัน\n\nคุยกับ Bath'rah the Windwatcher โทรลล์ผู้ปลีกวิเวกที่อยู่ระหว่าง Alterac Mountains กับ Western Plaguelands เขาเป็นทั้งช่างอาวุธฝีมือดีและชามันทรงพลัง\n\nหา Bath'rah โดยไปแม่น้ำที่ไหลเลียบฝั่งตะวันออกของ Tarren Mill ตามน้ำขึ้นเหนือ เขาตั้งค่ายใกล้ซากปรักบนฝั่งตะวันออกของแม่น้ำ" },
        completion = { "164:862163189:1837367491", "เจ้าเดินทางมาไกล นักรบรุ่นเยาว์ ข้าเห็นเปลวไฟในตา เจ้าต้องการอาวุธทรงพลังใช่ไหม?\n\nข้าช่วยภารกิจเจ้าได้ และเจ้าก็ช่วยภารกิจข้าได้เช่นกัน" },
    },
    [1792] = { -- Whirlwind Weapon
        title = { "16:914533295:357852554", "อาวุธลมหมุน" },
        completion = { "103:336405312:1990296277 N 52:681017420:1986814826", "ข้ามีหัวใจลมหมุนแล้ว พร้อมใส่มันลงในภาชนะที่เจ้าเลือก\n\nเลือกอาวุธเถอะ {name} และจงรู้ว่าพลังของมันคือพลัง Cyclonian" },
    },
    [1818] = { -- Speak with Dillinger
        title = { "20:1186897962:995108516", "คุยกับ Dillinger" },
        objective = { "41:368348500:150228794", "คุยกับ Deathguard Dillinger ใน Brill" },
        description = { "242:1898630458:2131111144", "ข้าได้ข่าวว่า Deathguard Dillinger มีงานสำหรับคนอย่างเจ้า หากยอมพิสูจน์คุณค่าต่อกองกำลัง Dark Lady จงไปรายงานตัวกับเขาทันที\n\nDeathguard Dillinger ประจำอยู่ปลายฝั่งตะวันตกของ Brill ใกล้สุสาน" },
        completion = { "153:1778448681:882139959", "มารับภารกิจหรือ? ดี ข้ามีงานสำคัญที่จะทดสอบทั้งฝีมือต่อสู้... และความมุ่งมั่นในการปกป้อง Forsaken" },
    },
    [1819] = { -- Ulag the Cleaver
        title = { "16:301321582:1371279858", "Ulag the Cleaver" },
        objective = { "60:1426087822:1180237662", "ฆ่า Ulag the Cleaver แล้วคุยกับ Deathguard Dillinger" },
        description = { "477:1239253452:1149515358 N 1:46:46", "เมื่อ Scourge กวาดผ่าน Tirisfal Glades เราจับตัวหนึ่งมาศึกษา เขามีความคิดเป็นอิสระ เรียกตัวเองว่า Ulag the Cleaver แต่แม้เจตจำนงจะเป็นอิสระ ก็ยังตกอยู่ใต้อำนาจ Lich King\n\nเราหวังหาวิธีทำลายการควบคุม Ulag ของราชา แต่ล้มเหลว ในที่สุดก็ถึงเวลาปลดปล่อยเขา\n\nปลดปล่อย แล้วฆ่าเขา\n\nกดกลไกหินกะโหลกใกล้สุสานทางเหนือ มันจะยกผนึกเวทที่กักเขาไว้\n\nจากนั้น... เตรียมพร้อม {name}" },
        progress = { "25:556664305:596005723 N 46:9747216:1428954457", "งานเจ้ายังไม่เสร็จ {name} การแสดงความกลัวไม่เหมาะกับนักรบ..." },
        completion = { "11:534428891:784080240 N 182:123285899:1827589109", "ทำดีมาก {name} Ulag ไม่ใช่สมุน Scourge ธรรมดา เจ้าพิสูจน์ต่อ Deathguard และต่อ Dark Lady ว่าเป็นนักรบมีฝีมือและมุ่งมั่น คู่ควรได้รับคำสอนต่อไป" },
        objectiveLabels = {
            monster = { ["Ulag the Cleaver slain"] = "ปราบ Ulag จอมสับ" },
        },
    },
    [1820] = { -- Speak with Coleman
        title = { "18:1885041325:1063330818", "คุยกับ Coleman" },
        objective = { "28:1169993664:761336298", "คุยกับ Coleman Farthing" },
        description = { "279:752581388:2042833356", "เจ้าพิสูจน์คุณค่าต่อ Dark Lady แล้ว บางทีอาจพิสูจน์ตัวต่อผู้ใต้ปกครองของนางได้\n\nColeman Farthing รอนักรบที่ยอมเป็นเครื่องมือแก้แค้นศัตรู Forsaken ให้เขา\n\nจะพบเขาที่ Gallow's End Tavern ทางตะวันออกของ Brill" },
        completion = { "166:37220481:179891961", "ใช่ เป็นความจริง ข้าต้องใช้ฝีมือต่อสู้เจ้า ทรัพย์ข้ามีน้อย แต่งานช่วยทั้งข้าและอุดมการณ์ Forsaken ทำสำเร็จแล้วรางวัลจะเป็นสองต่อ" },
    },
    [1821] = { -- Agamand Heirlooms
        title = { "17:1975045615:385162140", "มรดกตระกูล Agamand" },
        objective = { "127:186642311:672519748", "นำ Agamand Family Axe, Agamand Family Sword, Agamand Family Mace และ Agamand Family dagger ไปให้ Coleman Farthing" },
        description = { "442:774546710:452432003", "ตระกูล Agamand เคยเป็นนายจ้างตอนข้ายังมีชีวิต และเป็นต้นเหตุให้ข้าตาย! สมควรแล้วที่ตอนนี้พวกมันเป็นสมุนไร้สติของ Lich King\n\nทีนี้ข้าต้องการเกียรติยศเศษสุดท้ายของพวกมัน เข้าสุสานตระกูลแล้วชิงสมบัติตกทอดมา ดาบ ขวาน มีด และกระบอง เอามาให้ข้า!\n\nสุสานตระกูล Agamand อยู่ปลายเหนือของ Agamand Mills มี Scourge ที่ซุ่มอยู่กับพวก Agamand ที่ตายแล้วเฝ้าไว้" },
        progress = { "27:1571928383:1231191454 N 1:63:63", "มีสมบัติตกทอดหรือยัง {name}?" },
        completion = { "138:1530913087:316780501", "อา! เจ้าเอากลับมาแล้ว! ตอนนี้ร่องรอยสุดท้ายของเกียรติยศและความทรงจำถูกพรากจากดินแดน Agamand ต้องสาป ตระกูลนี้สิ้นแล้วจริง ๆ!" },
        required = { [7566] = { "20:69761286:1078615484", "ดาบตระกูล Agamand" }, [7567] = { "18:196071778:1456979578", "ขวานตระกูล Agamand" }, [7568] = { "21:895717509:638223326", "กริชตระกูล Agamand" }, [7569] = { "19:1200498641:1912347594", "กระบองตระกูล Agamand" } },
        objectiveLabels = {
            item = { ["Agamand Family Sword"] = "ดาบตระกูล Agamand", ["Agamand Family Axe"] = "ขวานตระกูล Agamand", ["Agamand Family Dagger"] = "กริชตระกูล Agamand", ["Agamand Family Mace"] = "กระบองตระกูล Agamand" },
        },
    },
    [1822] = { -- Heirloom Weapon
        title = { "15:2027005523:1193324160", "อาวุธตกทอด" },
        completion = { "98:7697215:805320717 N 132:2113680421:377398189", "ข้าจะเก็บอาวุธที่เจ้านำกลับมาสามชิ้นเป็นที่ระลึกถึงความเจ็บปวดและสูญเสีย แต่โปรดเลือกชิ้นโปรดแล้วเก็บไว้เองเถอะ {name}\n\nขอให้มันรับใช้เจ้าได้ดีกว่าเจ้าของเก่าที่ต้องสาป" },
    },
    [1823] = { -- Speak with Ruga
        title = { "15:1563306206:274522669", "คุยกับ Ruga" },
        objective = { "26:578906648:1855962725", "คุยกับ Ruga Ragetotem" },
        description = { "196:884960462:727314230", "เจ้าเป็นนักรบมีฝีมือและชื่อเสียงเพิ่มขึ้น บางทีพร้อมสำหรับบททดสอบ Ruga Ragetotem แล้ว? หากพร้อม ไปหาเขาที่ Camp Taurajo ใน Barrens\n\nเขารอนักรบผู้ตอบรับคำเรียก" },
        completion = { "27:1660194923:1897072411 N 1:63:63", "มารับบททดสอบของข้าหรือ {name}?" },
    },
    [1824] = { -- Trial at the Field of Giants
        title = { "28:1718471283:2135200054", "บททดสอบที่ Field of Giants" },
        objective = { "60:1340232924:2015408764", "นำ Twitching Antennae 5 ชิ้นไปให้ Ruga Ragetotem ที่ Camp Taurajo" },
        description = { "248:1119276849:953131461 N 122:1531724349:1731106402", "จะผ่านบททดสอบได้ เจ้าต้องไปใต้ถึง Field of Giants ที่นั่นมีสัตว์คล้ายแมลงคลานอยู่มากมาย มันเพิ่งมาถึง Barrens และข้าไม่ชอบลางที่พวกมันนำมา\n\nนำหนวดที่ยังกระตุกของมันมา อย่าเสียเวลา {name} เพราะหนวดที่เก็บมาไม่กระตุกนานนัก นำกลับภายในเวลาที่กำหนดแล้วเจ้าจะผ่าน" },
        progress = { "109:62707929:2008514609", "มีหนวดหรือยัง? หากมีรีบให้ข้า เพราะหนวดที่กระตุกไม่ได้กระตุกตลอดไป..." },
        completion = { "13:96413020:153092913 N 79:2113196835:1618567126 C 8:310623485:374336724", "ทำดีมาก {name}! การผ่านบททดสอบ Field of Giants ทำให้เจ้าก้าวบนวิถี{class}ไปอีกขั้น" },
        required = { [7119] = { "17:1863314976:775823301", "หนวดที่กระตุก" } },
        steps = { { "17:1863314976:775823301", "หนวดที่กระตุก" } },
    },
    [1825] = { -- Speak with Thun'grim
        title = { "20:1593419109:2052254736", "คุยกับ Thun'grim" },
        objective = { "45:1130286613:936827525", "คุยกับ Thun'grim Firegaze ใน Barrens" },
        description = { "266:335026749:727913362", "Thun'grim Firegaze ช่างตีเหล็กออร์คชื่อดังได้ยินเรื่องวีรกรรมต่อเนื่องที่เจ้ารับใช้ Horde เขาอยากสร้างชุดเกราะให้ และขอให้ไปคุยทันที\n\nThun'grim ตั้งค่ายทางตะวันออกของ Crossroads ใน Barrens" },
        completion = { "73:125403646:1326005457", "ใช่ เจ้าก็มาถึงแล้ว ดี เราสองคนมีเรื่องต้องคุยกันมาก" },
    },
    [1838] = { -- Brutal Armor
        title = { "12:416151758:994360901", "เกราะดุดัน" },
        objective = { "109:1154086777:1079532074", "นำ Smoky Iron Ingots 15 ชิ้น, Powdered Azurite 10 ชิ้น, Iron Bars 10 แท่ง และ Vial of Phlogiston ไปให้ Thun'grim Firegaze" },
        description = { "209:861407274:594453175 N 275:797338917:460520718", "ข้าได้ยินเรื่องกำลังและความกล้าหาญ จึงอยากสร้างชุดเกราะให้เป็นสหายช่วยเจ้า ระหว่างเรื่องวีรกรรมแพร่ไกลขึ้น\n\nแต่การสร้างเกราะนี้ก็เป็นภารกิจในตัวเอง {name} ข้าต้องให้เจ้ากับช่างตีเหล็กคนอื่นของ Horde ช่วย\n\nนี่ รับม้วนบันทึกไป ข้าใช้หลายคืนเพ่งตาเกือบบอดเขียนสิ่งที่ต้องใช้ทำเกราะ นำของในรายการมา แล้วจะสร้างชิ้นแรกของชุดให้" },
        progress = { "36:755829538:1585805686 N 1:63:63", "มีของในม้วนบันทึกข้าหรือยัง {name}?" },
        completion = { "55:2146371963:741192704", "เจ้านำทุกสิ่งที่ขอมาแล้ว ทีนี้ข้าจะทำส่วนของข้า..." },
        required = { [7126] = { "16:539332232:731423512", "แท่งเหล็กสีควัน" }, [7127] = { "16:1829473689:1087846221", "ผงอะซูไรต์" }, [3575] = { "8:1010117764:989104521", "แท่งเหล็ก" }, [6841] = { "18:887915042:531421932", "ขวดบรรจุ Phlogiston" } },
        steps = { { "16:539332232:731423512", "แท่งเหล็กสีควัน" }, { "16:1829473689:1087846221", "ผงอะซูไรต์" }, { "8:1010117764:989104521", "แท่งเหล็ก" }, { "18:887915042:531421932", "ขวดบรรจุ Phlogiston" } },
    },
    [1839] = { -- Ula'elek and the Brutal Gauntlets
        title = { "33:1133392649:1056897539", "Ula'elek กับถุงมือเกราะดุดัน" },
        objective = { "31:1492147459:839483307", "คุยกับ Ula'elek ใน Durotar" },
        description = { "162:958354155:1160699132", "ช่างตีเหล็กโทรลล์ Ula'elek จะสร้างถุงมือเกราะดุดันให้ เขาอยู่ Sen'jin Village ใน Durotar กับพี่น้อง Darkspear และรอเจ้ามา" },
        completion = { "11:927657569:725753248 N 159:77766593:1410245556 C 57:1892637301:549275242", "สวัสดี {name} เฒ่า Thun'grim ส่งข่าวว่าเจ้าจะมา แต่ต่อให้ไม่บอก ข้าก็ไม่แปลกใจที่พบเจ้าที่นี่\n\nเหล่าวิญญาณเฝ้าดูความก้าวหน้า {class}รุ่นเยาว์ และบอกว่าศัตรูมากมายล้มต่อหน้าเจ้า" },
    },
    [1840] = { -- Orm Stonehoof and the Brutal Helm
        title = { "33:1915402199:908881586", "Orm Stonehoof กับหมวกเกราะดุดัน" },
        objective = { "42:1217025146:361367447", "คุยกับ Orm Stonehoof ใน Thunder Bluff" },
        description = { "168:33213758:1512920890", "Orm Stonehoof ได้รับความเคารพอย่างยิ่งเพราะฝีมือ เขาจะทำหมวกเกราะดุดันให้\n\nไปหาใน Thunder Bluff ใกล้สระน้ำข้างเสาโทเทมใหญ่ใจกลางเมือง" },
        completion = { "11:927657569:725753248 C 56:1240720181:419232821", "สวัสดี {class} ข้าชื่อ Orm และ Thun'grim บอกว่าเจ้าอยากให้ทำหมวกหรือ?" },
    },
    [1841] = { -- Velora Nitely and the Brutal Legguards
        title = { "38:1579235880:1362685582", "Velora Nitely กับเกราะขาดุดัน" },
        objective = { "42:1654088376:629640892", "คุยกับ Velora Nitely ใน Undercity" },
        description = { "276:490324316:606227800", "ว่ากันว่าก่อนตาย Velora Nitely เป็นหนึ่งในช่างเกราะดีที่สุดแห่ง Lordaeron ดูเหมือนความตายไม่ลดพรสวรรค์นางเลย ไปคุยกับ Velora นางจะทำเกราะขาดุดันให้\n\nVelora ทำงานใน Trade Quarter ของ Undercity แห่ง Lordaeron" },
        completion = { "261:449852674:1461543863", "มาหาเกราะขาหรือ? เยี่ยม!\n\nเอ่อ... ข้าทำเกราะให้เจ้า หรือเจ้าทำให้ข้านะ?\n\nล้อเล่นน่ะ ตลกไหม? ข้าดูไม่ออก... เสียอารมณ์ขันไปพร้อมประสาทรับกลิ่น ซึ่งก็พอ ๆ กับตอนหยุดหายใจ", variants = { { "263:864755316:66026023", "มาหาเกราะขาหรือ? เยี่ยม!\n\nเอ่อ... ข้าทำเกราะให้เจ้า หรือเจ้าทำให้ข้านะ?\n\nล้อเล่นน่ะ ตลกไหม? ข้าดูไม่ออก... เสียอารมณ์ขันไปพร้อมประสาทรับกลิ่น ซึ่งก็พอ ๆ กับตอนหยุดหายใจ" } } },
    },
    [1842] = { -- Satyr Hooves
        title = { "12:2038700113:1875014056", "กีบเซเทอร์" },
        objective = { "72:1738263059:2097436185", "นำ Uncloven Satyr Hooves 7 ชิ้นไปให้ Ula'elek ที่ Sen'jin Village ใน Durotar", variants = { { "71:1343718469:1163521299", "นำ Uncloven Satyr Hooves 7 ชิ้นไปให้ Ula'elek ที่ Sen'jin Village ใน Durotar" } } },
        description = { "438:364577274:1143249154", "ข้าทำถุงมือเกราะดุดันที่บรรจุพลังเวทมหาศาลให้ได้ แต่เจ้าต้องรวบรวมพลังนั้นมาให้ข้าก่อน\n\nเซเทอร์อยู่ทางตะวันออกเฉียงเหนือของ Ashenvale เพราะพลังป่า พวกมันดูดกินความบริสุทธิ์ สูบพลังและทำให้แปดเปื้อน เจ้าดูออกว่าตัวใดดูดเวท Ashenvale ไปมากที่สุดจากกีบบวมโตที่ไม่แยกเป็นสองซีก\n\nกีบเหล่านั้นเก็บพลังมหาศาล ข้าต้องใช้สร้างถุงมือเจ้า" },
        progress = { "24:841075973:2061578198 N 34:584858552:1135136446", "มีกีบหรือยัง {name}? เวทภายในทรงพลังมาก" },
        completion = { "160:901411448:1833652749", "อา ได้มาแล้ว! เช่นที่เซเทอร์สูบพลัง Ashenvale ข้าจะสูบพลังในกีบมาใช้สร้างงาน..." },
        required = { [7128] = { "19:1944954200:249594296", "กีบซาเทอร์ที่ไม่แยกเป็นสองซีก" } },
        steps = { { "19:1944954200:249594296", "กีบซาเทอร์ที่ไม่แยกเป็นสองซีก" } },
    },
    [1843] = { -- Brutal Gauntlets
        title = { "16:1455644665:744281675", "ถุงมือเกราะดุดัน" },
        completion = { "11:1191658970:1224418299 N 103:1907342242:1316991354", "ขอบใจ {name} ถุงมือคู่นี้เป็นผลงานดีที่สุดของข้า รับไป การสวมมันนำเกียรติมาสู่ข้าและบรรพชน" },
    },
    [1844] = { -- Chimaeric Horn
        title = { "14:2031293754:1156973323", "เขาไคมีรา" },
        objective = { "58:1065077864:1058148098", "นำ Galvanized Horn ไปให้ Orm Stonehoof ใน Thunder Bluff" },
        description = { "316:561317796:797418350 N 172:762371177:1794759433", "ข้าจะทำหมวกให้ แต่ต้องแสดงว่าคู่ควรก่อน\n\nCharred Vale อยู่ทางตะวันตกเฉียงเหนือของ Stonetalon Mountains เคยเขียวขจี แต่บัดนี้แปดเปื้อนและเต็มเถ้าถ่าน สัตว์ที่เหลืออยู่คลุ้มคลั่งด้วยความเจ็บปวดและสิ้นหวัง\n\nนั่นคือที่ที่ข้าจะส่งเจ้าไป {name}\n\nไป Charred Vale หาแม่ไคมีรา ฆ่านาง ปลดปล่อยจากความทุกข์ นำ Galvanized Horn มาเป็นหลักฐาน แล้วข้าจะทำหมวกให้" },
        progress = { "52:1367800022:600888089", "มีเขาหรือยัง? แม่ไคมีราพ้นความเจ็บปวดแล้วหรือ?" },
        completion = { "30:1211524102:476349484 N 64:1815080874:1850567657", "เจ้าทำงานสำเร็จแล้ว {name} แสดงทั้งคุณค่าและความมุ่งมั่น หมวกจะเป็นของเจ้า..." },
        required = { [6840] = { "15:968638351:1181794772", "เขาสัตว์ชุบโลหะ" } },
        steps = { { "15:968638351:1181794772", "เขาสัตว์ชุบโลหะ" } },
    },
    [1845] = { -- Brutal Helm
        title = { "11:537380897:465715081", "หมวกเกราะดุดัน" },
        completion = { "56:479245960:1947634183 N 63:1493380206:669625379", "ข้ามอบหมวกนี้ให้เจ้า\n\nวีรกรรมนำเจ้ามาหาข้า {name} และหาก Earthmother ทรงประสงค์... วีรกรรมที่ยิ่งใหญ่กว่ายังรออยู่ข้างหน้า" },
    },
    [1846] = { -- Dragonmaw Shinbones
        title = { "19:1898896979:50656679", "กระดูกหน้าแข้ง Dragonmaw" },
        objective = { "69:398934261:1684831297", "นำ Sturdy Dragonmaw Shinbones 8 ชิ้นไปให้ Velora Nitely ใน Undercity" },
        description = { "314:772574947:965897547", "จะทำเกราะขาดุดันได้ ข้าต้องมีกระดูกหน้าแข้งแข็งแรงไว้ทำโครง ออร์ค Dragonmaw ใน Wetlands มีกระดูกหน้าแข้งหนาดี ข้าต้องการของพวกมัน\n\nแต่ต้องแข็งแรงจริง ทดสอบตอนเก็บด้วย หากหักด้วยมือเปล่าได้ ก็ยังไม่แข็งแรงพอใช้งาน" },
        progress = { "33:16750954:1189127448 N 48:418292301:1196633709", "ข้ารอกระดูกหน้าแข้งอยู่นะ {name} มันจะเป็นโครงเกราะขาที่ดี" },
        completion = { "115:1203508022:730723665 N 99:79244718:2141593614", "ทำดีมาก! ดูแข็งแรงทุกชิ้น คิดว่าใช้ได้ดีทีเดียว พวกออร์คว่าอย่างไรที่เจ้าเอาหน้าแข้งมันมา {name}? บ่นมากไหม?\n\nนั่นก็มุกอีกอัน เจ้าไม่หัวเราะเลย\n\nช่วงนี้ข้าไม่ค่อยตลกสินะ..." },
        required = { [7134] = { "25:2124890677:1036721349", "กระดูกหน้าแข้งที่แข็งแรงของ Dragonmaw" } },
        steps = { { "25:2124890677:1036721349", "กระดูกหน้าแข้งที่แข็งแรงของ Dragonmaw" } },
    },
    [1847] = { -- Brutal Legguards
        title = { "16:1857240545:990611747", "เกราะขาดุดัน" },
        completion = { "25:60610442:83705157 N 202:1480234077:2023153716", "นี่เกราะขาเจ้า {name} บอกด้วยว่าใส่พอดีไหมหรือต้องปรับอะไร ข้ามุ่งให้พอใจ! อย่างน้อยเมื่อก่อนก็ใช่\n\nช่วงนี้ไม่ค่อยใส่ใจงานนัก แต่ก็ดีกว่าเป็นสมุนไร้สติของ Scourge!\n\nข้าว่านะ" },
    },
    [1848] = { -- Brutal Hauberk
        title = { "14:576135110:1526960759", "เสื้อเกราะดุดัน" },
        completion = { "68:2101039798:1316555838 N 125:603194427:1516356123", "ข้าแน่ใจว่าเจ้าฝ่าความลำบากและหลั่งเลือดมากกับงานข้า {name} นี่ผลแห่งความพยายาม\n\nขอให้สวมใส่มันอย่างสมเกียรติ และสักวันกลับมาเล่าให้ฟังว่ามันรับใช้เจ้าอย่างไร" },
    },
    [2383] = { -- Simple Parchment
        title = { "16:1846939002:1114323798", "แผ่นหนังธรรมดา" },
        objective = { "69:2091175728:622124999", "อ่าน Simple Parchment แล้วคุยกับ Frang ใน Valley of Trials" },
        description = { "50:504738005:547472890 N 198:583512878:594652802", "อา ระหว่างเจ้าไม่อยู่ มีแผ่นหนังมาถึง {name}\n\nมีเวลาค่อยอ่าน หากจำไม่ผิด มาจาก Frang ครูฝึกนักรบ เขาอยากคุยเมื่อเจ้าพร้อม จะพบเขาหลบร่มอยู่นอก Den" },
        progress = { "72:1758197815:1523834041", "ถืออะไรอยู่นั่น? แผ่นหนังหรือ? หวังว่าคงไม่ใช่นักปราชญ์นะ..." },
        completion = { "64:552744521:449046443 N 172:1751969161:1438795867 C 13:557023019:146433754 N 43:1162581186:2067343256", "อา แผ่นหนังข้าเอง ได้ยินว่าเจ้าจะมา Valley {name} ดีใจที่มาถึง หวังว่าจะรอดบททดสอบข้างหน้า อย่างที่บอก เมื่อแข็งแกร่งขึ้นจงมาหาข้า ข้าจะทำเท่าที่ทำได้เพื่อฝึกเจ้าบนวิถี{class}\n\nโชคดี {name} และกลับมาเมื่อรู้สึกพร้อม" },
        required = { [12635] = { "16:1846939002:1114323798", "แผ่นหนังเรียบง่าย" } },
        steps = { { "16:1846939002:1114323798", "แผ่นหนังเรียบง่าย" } },
    },
    [3065] = { -- Simple Tablet
        title = { "13:1876920316:242427928", "แผ่นจารึกธรรมดา" },
        objective = { "66:192075031:1946175552", "อ่าน Simple Tablet แล้วคุยกับ Frang ใน Valley of Trials" },
        description = { "50:504738005:547472890 N 198:583512878:594652802", "อา ระหว่างเจ้าไม่อยู่ มีแผ่นหนังมาถึง {name}\n\nมีเวลาค่อยอ่าน หากจำไม่ผิด มาจาก Frang ครูฝึกนักรบ เขาอยากคุยเมื่อเจ้าพร้อม จะพบเขาหลบร่มอยู่นอก Den" },
        progress = { "8:603431178:489660419 R 188:636549819:1102075643", "ชาว{race}อีกคนมาเสริมกำลัง แค่นั้นข้าก็พอใจ\n\nเจ้าคงลำบากหน่อยถ้าจะยกอาวุธดี ๆ อย่างขวาน แต่หอกก็ดีไม่แพ้อะไร\n\nยินดีต้อนรับสู่ Valley of Trials" },
        completion = { "63:931460719:336823987 C 157:2051194159:1066240848 C 73:389448807:160836528", "ที่นี่เหมาะกับการฝึกวิถี{class}ต่อไป หากมีคำถามก็ถามคนแถวนี้ได้ เมื่อรู้สึกพร้อมกลับมาฝึกกับข้า ข้าเชี่ยวชาญเทียบได้กับ{class}คนใดใน Valley และถ่ายทอดความรู้นั้นให้เจ้าได้... โดยมีค่าตอบแทน", variants = { { "307:1966453995:647542677", "ที่นี่เหมาะกับการฝึกวิถีนักรบต่อไป หากมีคำถามก็ถามคนแถวนี้ได้ เมื่อรู้สึกพร้อมกลับมาฝึกกับข้า ข้าเชี่ยวชาญเทียบได้กับนักรบคนใดใน Valley และถ่ายทอดความรู้นั้นให้เจ้าได้... โดยมีค่าตอบแทน" } } },
        required = { [6488] = { "13:1876920316:242427928", "แผ่นจารึกเรียบง่าย" } },
        objectiveLabels = {
            item = { ["Simple Tablet"] = "แผ่นจารึกเรียบง่าย" },
        },
    },
    [3091] = { -- Simple Note
        title = { "11:1769838965:922420833", "บันทึกธรรมดา" },
        objective = { "69:1439214125:1869099536", "อ่าน Simple Note แล้วคุยกับ Harutt Thunderhorn ใน Camp Narache" },
        description = { "51:1119716052:1206024959 N 131:1167001374:547510411", "เมื่อครู่มีผู้ส่งสารตามหาเจ้า {name} เชื่อว่า Harutt ครูฝึกนักรบส่งนางมา หากบันทึกนี้มาจาก Harutt ก็อย่ารออ่านเนื้อหานานนัก" },
        progress = { "29:1315332139:1348795301 C 28:451352302:820505976 N 194:1312019630:7683053", "อา ในที่สุดก็มาถึง {class} ข้าไม่ได้โกหกในบันทึก {name} เราก็เป็นกลุ่มพิเศษ ไม่ต่างจากดรูอิดหรือชามันในเผ่า เจ้าสำคัญเท่ากัน เราคือผู้ถูกเรียกให้ป้องกันชายแดน ล่าเซนทอร์ และออกรบ" },
        completion = { "366:1064210619:1879811894 N 1:46:46", "เราแต่ละคนมีหน้าที่ในเผ่า และทุกคนต้องผ่านพิธีเดียวกัน อย่าให้ความทะนงบอกเป็นอื่น\n\nข้าอยู่ที่นี่เพื่อฝึกนักรบใหม่ผู้แสวงหาเกียรติแห่งศึกและตามวิถีบรรพชนเก่าแก่ที่สุด เมื่อพร้อมจงกลับมา ข้าจะทำเท่าที่ทำได้เพื่อฝึกเพิ่มเติม จงไปพร้อมพรของเผ่า {name}" },
        required = { [9547] = { "11:1769838965:922420833", "บันทึกเรียบง่าย" } },
        steps = { { "11:1769838965:922420833", "บันทึกเรียบง่าย" } },
    },
    [3095] = { -- Simple Scroll
        title = { "13:2115290633:942665289", "ม้วนคัมภีร์ธรรมดา" },
        objective = { "63:1182512496:1116648632", "อ่าน Simple Scroll แล้วคุยกับ Dannal Stern ใน Deathknell" },
        description = { "252:474227619:1262586629", "อา ระหว่างเจ้าจัดการ Scourge ไร้สติ ม้วนคัมภีร์นี้มาถึงเจ้า ข้าว่าน่าจะเป็นเรื่องสำคัญ เพราะดูเหมือนมีตรา Dannal ครูฝึกนักรบ ข้าคงหาเวลาอ่านก่อนออกไปอีกครั้ง" },
        progress = { "352:1091246498:2054204007", "อา มาถึงแล้ว ดี ได้ยินว่าอีกหลายคนหนีจาก\"ความตาย\"ได้และกำลังเข้าเมือง บางทีความทรหดนั้นอาจเป็นประโยชน์ในอนาคตด้วย\n\nขอบคุณ Sylvanas ได้สำหรับอิสรภาพ... ทั้งกายและใจ แม้ยังถูกโรคระบาดกับผลของมันทรมาน แต่บัดนี้เจ้ามีอิสระจะไปมาได้ตามใจ" },
        completion = { "463:584492818:1450797276", "ข้าจะอยู่ฝึกให้เมื่อเจ้ามีประสบการณ์มากขึ้น มาหาบ่อยเท่าที่ชอบ ข้าคิดค่าฝึกเล็กน้อย แต่ทุกอย่างที่สอนจะคุ้มค่า\n\nไปทดสอบฝีมือเถอะ ยิ่งมีประสบการณ์ก็จะรู้สิ่งต่าง ๆ อีกมาก บางเรื่องข้าพูดที่นี่ไม่ได้ เพียงรู้ว่า Sylvanas จะต้องการนักรบแข็งแกร่งอย่างเจ้าในอนาคต เจ้าจะเป็นกำลังหลักแห่งความรอดเรา อย่าลืม" },
        required = { [9546] = { "13:2115290633:942665289", "ม้วนคัมภีร์เรียบง่าย" } },
        steps = { { "13:2115290633:942665289", "ม้วนคัมภีร์เรียบง่าย" } },
    },
    [3100] = { -- Simple Letter
        title = { "13:1105569224:2062755904", "จดหมายธรรมดา" },
        objective = { "70:928449097:571861817", "อ่าน Simple Letter แล้วคุยกับ Llane Beshere ใน Northshire Abbey" },
        description = { "91:566813027:607752075 N 178:502556797:2010891760", "มีคนขอให้ข้านำเรื่องนี้มาบอกทันทีที่เจ้ากลับจากค่ายโคบอลด์ {name} ดูเหมือนเป็นจดหมายผนึกตรา Llane ครูฝึกนักรบประจำถิ่น ข้าคงไม่รออ่านก่อนทำธุระอื่นใน Abbey" },
        progress = { "23:1688681253:125572344 N 142:1208414831:136971302", "อา ได้จดหมายข้าแล้ว {name}... ดี\n\nระยะนี้มีนักรบเข้ามา Elwynn มาก ดีต่อ Stormwind แต่ไม่ดีต่อโคบอลด์และ Defias แถวนี้", variants = { { "23:1688681253:125572344 N 141:931673413:1868305319", "อา ได้จดหมายข้าแล้ว {name}... ดี\n\nระยะนี้มีนักรบเข้ามา Elwynn มาก ดีต่อ Stormwind แต่ไม่ดีต่อโคบอลด์และ Defias แถวนี้" } } },
        completion = { "330:1074930638:1262446220 C 26:1908005939:2103511279", "เตรียมตัวให้พร้อม เรียนรู้ภูมิประเทศ แล้วกลับมาเมื่อใดที่ต้องการฝึก ข้าอยู่ที่นี่ทั้งกลางวันกลางคืน\n\nอัศวิน Silver Hand ทำได้ดีจนที่นี่ค่อนข้างปลอดภัย แต่เมื่อพบชาวเมืองคนอื่น คงเห็นว่าทุกคนมีปัญหาที่อยากได้ความช่วยเหลือ ความช่วยเหลือที่{class}มอบให้ได้ โชคดี", variants = { { "329:801249988:1933895865 C 26:1908005939:2103511279", "เตรียมตัวให้พร้อม เรียนรู้ภูมิประเทศ แล้วกลับมาเมื่อใดที่ต้องการฝึก ข้าอยู่ที่นี่ทั้งกลางวันกลางคืน\n\nอัศวิน Silver Hand ทำได้ดีจนที่นี่ค่อนข้างปลอดภัย แต่เมื่อพบชาวเมืองคนอื่น คงเห็นว่าทุกคนมีปัญหาที่อยากได้ความช่วยเหลือ ความช่วยเหลือที่{class}มอบให้ได้ โชคดี" } } },
        required = { [9542] = { "13:1105569224:2062755904", "จดหมายเรียบง่าย" } },
        steps = { { "13:1105569224:2062755904", "จดหมายเรียบง่าย" } },
    },
    [3116] = { -- Simple Sigil
        title = { "12:1964374964:2036834497", "ตราธรรมดา" },
        objective = { "58:1962351561:509967238", "อ่าน Simple Sigil แล้วคุยกับ Alyissia ใน Shadowglen" },
        description = { "185:215384693:552364359", "ผู้ส่งสารจาก Alyissia ครูฝึกนักรบของเรามอบตรานี้ให้ข้า ดูเหมือนนางอยากคุยเมื่อเจ้ามีเวลา อ่านแล้วนำไปให้นางด้วย" },
        progress = { "69:694708845:1732170660 N 294:2090481420:882197818", "เจ้ามาถึงแล้ว ดีใจจริง ๆ\n\nหลายปีมานี้มีเรื่องมากมาย {name} ทั้งการสร้าง Teldrassil สัตว์ป่ามากมายที่นี่และที่อื่นแปดเปื้อน การค้นพบดินแดนอย่าง Feralas ที่เคยคิดว่าสูญเสียไป... มากมายในเวลาเพียงน้อยนิด แต่นั่นเป็นเพียงบางเหตุผลที่เราอยู่ที่นี่ ที่สำคัญที่สุดคือปกป้องเผ่าพันธุ์จากความชั่วร้ายเพิ่มเติม" },
        completion = { "409:1568220970:2068466232 C 92:1946976623:1973134237", "อีกไม่นานจะเห็นคนต่างเผ่าพันธุ์บนกิ่งก้านบ้านเรา อย่าให้อคติเกิดในใจ พวกเขาได้รับการต้อนรับ จะช่วยเราเมื่อทำได้ แม้ไม่ใช่ทุกคนจะทำโดยไม่หวังผล แต่ก็ควรได้รับความไว้วางใจบ้าง\n\nแต่ตอนนี้เรื่องเหล่านั้นยังไม่สำคัญ เราต้องใส่ใจเจ้าและวิธีช่วยผู้คนเรา ข้าอยู่เพื่อการนี้ จะฝึกวิถี{class}ให้เมื่อเจ้าแข็งแกร่งขึ้น กลับมาเมื่อใดก็ได้ ข้าจะช่วยเท่าที่ทำได้" },
        required = { [9545] = { "12:1964374964:2036834497", "ตราเรียบง่าย" } },
        steps = { { "12:1964374964:2036834497", "ตราเรียบง่าย" } },
    },
    [6661] = { -- Deeprun Rat Roundup
        title = { "19:797086338:543736647", "รวบรวมหนู Deeprun" },
        objective = { "141:979810746:1442571865", "ใช้ Rat Catcher's Flute จับ Deeprun Rats 5 ตัว แล้วนำหนูกลับไปหา Monty อย่าลืมคืนขลุ่ยเมื่อเสร็จ" },
        description = { "382:421279757:1258213147", "เฮ้ เจ้าตัวแสบ อ๊าร์... หา... หางานอยู่หรือ? พวกข้ามีปัญหาหนูร้ายแรงข้างล่างนี่ แต่คนบนดาดฟ้าไม่พอ\n\nว่าอย่างไร? แค่เอาขลุ่ยจับหนูนี่ไปเป่าทำนองใกล้เจ้าสัตว์รบกวน มันจะตามเจ้าไปสุดหล้า!\n\nจับเจ้าตัวเล็กห้าตัวแล้วพากลับมานี่ เราต้องการมันเป็น ๆ\n\nอ๊าร์..." },
        progress = { "43:1871514896:1878029665", "ย๊าร์... เจ้าเด็กขัดดาดฟ้า อะไรทำให้ช้านัก?" },
        completion = { "138:2061453235:403987693", "พวกนี้ใช้ได้ดีเลย สหาย พี่น้องข้าต้องการให้มันยังเต้นตุ้บและดิ้นได้ ไม่อย่างนั้นจะบูด... เจ้าไม่อยากชิมหนูเสียบไม้บูดหรอก" },
        required = { [17117] = { "19:1043740275:1752915427", "ขลุ่ยของคนจับหนู" } },
        steps = { { "13:742827605:838566790", "จับหนู" }, { "19:1043740275:1752915427", "ขลุ่ยของคนจับหนู" } },
    },
    [6662] = { -- Me Brother, Nipsy
        title = { "17:1616906424:317609815", "พี่น้องข้า Nipsy" },
        objective = { "77:419312140:313563361", "นำ Carton of Mystery Meat ไปให้ Nipsy ที่สถานี Deeprun Tram ฝั่ง Stormwind" },
        description = { "340:154469860:1819246909", "Nipsy พี่น้องข้าขายหนูเสียบไม้อีกฝั่งของ Deeprun เจ้าต้องนำลังหนูนี่ไปก่อนมันเสีย รีบเข้า!\n\nเคยนั่งรถรางแล้วใช่ไหม? ง่ายมาก พอมาถึงก็ก้าวขึ้นแล้วเพลินกับการเดินทาง เก็บแขนขาไว้ข้างในด้วย ไม่งั้นอาจต้องใส่ขาไม้ไปตลอดชีวิต" },
        progress = { "112:366118576:982263090", "<Nipsy แหย่นิ้วชี้ผ่านรูระบายอากาศรูหนึ่งของกล่อง>\n\nยังมีชีวิตและดิ้นได้... มาทันเวลาพอดี!" },
        completion = { "227:2023358311:461836410", "Monty ผู้น่าสงสาร ตั้งแต่เหตุการณ์ Gnomeregan เขาก็ไม่เหมือนเดิม เด็กนั่นทั้งชีวิตไม่เคยเห็นมหาสมุทรด้วยซ้ำ อย่าว่าแต่เป็นโจรสลัดเลย\n\n<Nipsy ถอนหายใจ>\n\nอย่างน้อยก็ยังส่งสัตว์ดิ้นกระตุกมาไม่ขาด" },
        required = { [17118] = { "22:41156393:547032925", "กล่องเนื้อปริศนา" } },
        steps = { { "22:41156393:547032925", "กล่องเนื้อปริศนา" } },
    },
    [8423] = { -- Warrior Kinship
        title = { "15:27521235:1823213561", "สายสัมพันธ์นักรบ" },
        objective = { "79:1089417512:581267464", "ฆ่า Helboar 7 ตัวใน Blasted Lands แล้วกลับไปหา Fallen Hero of the Horde" },
        description = { "37:1543581563:472861092 C 245:1636180455:760612838", "<วีรชนมองสำรวจเจ้า>\n\nเจ้าเป็น{class}แน่นอน ข้าอยากขอให้ทำงานอันทรงเกียรติ แต่ต้องทดสอบกำลังก่อน\n\nว่ากันว่า Rexxar วัดความคมของดาบด้วยการฆ่า Helboar ในฟันเดียวที่รวดเร็ว บัดนี้ข้าจะวัดกำลังเจ้าจากการฆ่าพวกมัน" },
        progress = { "165:967653487:1269452674", "หนามร้อนระอุของ Helboar ทิ้งแผลเป็นสยอง อย่ากลัวความเจ็บและเสียโฉม นักรบ มันเทียบไม่ได้กับคุกที่พันธนาการข้า" },
        completion = { "44:895500104:1372165892 C 56:1181377778:1459494701", "ข้าไม่ต้องการหลักฐานก็รู้สิ่งที่เจ้าทำ {class} ข้าเห็นความมุ่งมั่นสลักบนสีหน้า" },
        objectiveLabels = {
            monster = { ["Helboar slain"] = "ปราบ หมูป่านรก" },
        },
    },
    [8424] = { -- War on the Shadowsworn
        title = { "22:556926565:1638743778", "ทำสงครามกับ Shadowsworn" },
        objective = { "90:1876207075:1610527872", "สังหาร Shadowsworn ใน Blasted Lands แล้วกลับไปหา Fallen Hero of the Horde" },
        description = { "240:893775689:1592955217", "การที่ Shadowsworn ยังอยู่ใน Blasted Lands นำความเจ็บปวดมาสู่ข้ามาก พิธีมืดและเวทของมันทรมานยิ่งกว่าสิ่งใดตอนมีชีวิต\n\nผ่านเจ้า ข้าส่งสารแห่งความเจ็บปวดของตนได้ จงไปนำความพิโรธข้าสู่พวกมัน" },
        progress = { "112:213167729:1091772322", "Shadowsworn ปราบไม่ง่ายสินะ? แต่เจ้าเป็นนักรบ และจะชนะหรือตายระหว่างพยายาม" },
        completion = { "60:689519136:1245985568 C 1:46:46", "เจ้าบรรเทาความเจ็บปวดและให้เกียรติข้าแล้ว ขอบใจ {class}" },
        objectiveLabels = {
            monster = { ["Shadowsworn Adept slain"] = "ปราบ ผู้ชำนาญเวท Shadowsworn", ["Shadowsworn Cultist slain"] = "ปราบ สาวกลัทธิ Shadowsworn", ["Shadowsworn Thug slain"] = "ปราบ อันธพาล Shadowsworn" },
        },
    },
    [8425] = { -- Voodoo Feathers
        title = { "15:259246460:1750898483", "ขนนกวูดู" },
        objective = { "95:1273207649:127833165", "นำ Voodoo Feathers จากโทรลล์ใน Sunken Temple ไปให้ Fallen Hero of the Horde" },
        description = { "426:2102928997:1720776774", "เกียรติของเจ้านำความสงบมาให้ข้าบ้าง สมควรที่ข้าจะตอบแทน\n\nอาวุธและเกราะข้าเคยงดงามตอนมีชีวิต แต่บัดนี้ไม่มีประโยชน์กับข้าแล้ว มันจะรับใช้ได้ดีกว่าหากอยู่กับเจ้า\n\nไปวิหารจม ทำลายผู้พิทักษ์โทรลล์ Gasher, Mijan, Zolo, Hukku, Zul'lor และ Loro พวกมันมีขนนกเวทที่คืนร่างกายข้าได้นานพอจะมอบรางวัลให้", variants = { { "425:1770977908:1119186171", "เกียรติของเจ้าทำให้ข้าได้สงบใจขึ้นบ้าง ข้าควรตอบแทนเจ้าสักอย่าง\n\nอาวุธและเกราะของข้าเคยงดงามในยามมีชีวิต แต่บัดนี้ข้าใช้มันไม่ได้แล้ว ให้เจ้าเก็บไว้ใช้จะดีกว่า\n\nจงไปที่ Sunken Temple แล้วปราบผู้พิทักษ์โทรลล์ Gasher, Mijan, Zolo, Hukku, Zul'lor และ Loro พวกมันมีขนนกอาคมที่จะช่วยให้ข้ากลับมามีร่างกายได้นานพอจะมอบรางวัลแก่เจ้า" } } },
        progress = { "111:1538809682:468757211", "กลับมาเร็วเพียงนี้หรือ? เวลาสำหรับข้าไม่เหมือนเดิมแล้ว บางทีเจ้าอาจเดินทางมานานจริง ๆ..." },
        completion = { "76:37278891:1423983641", "ในที่สุดข้าก็สัมผัสความเย็นของเหล็กกล้าได้อีกครั้ง แม้เพียงครู่เดียว" },
        required = { [20606] = { "20:116773895:110391659", "ขนนกวูดูสีอำพัน" }, [20607] = { "19:47936181:1879616036", "ขนนกวูดูสีน้ำเงิน" }, [20608] = { "20:1196264854:1089628285", "ขนนกวูดูสีเขียว" } },
        objectiveLabels = {
            item = { ["Amber Voodoo Feather"] = "ขนนกวูดูสีอำพัน", ["Blue Voodoo Feather"] = "ขนนกวูดูสีน้ำเงิน", ["Green Voodoo Feather"] = "ขนนกวูดูสีเขียว" },
        },
    },
    [79975] = { -- Eagle's Fist
        title = { "12:983067544:684199699", "หมัดอินทรี" },
        objective = { "52:1839446812:1401611402", "ละอองน้ำทำให้อากาศชื้น ทิวทัศน์ช่างงดงาม" },
        description = { "339:1158602670:1088406110", "<เจ้าพบจดหมายพับอย่างประณีตในกล่องเครื่องมือ>\n\n\"จากที่นี่ หากมีเครื่องมือเหมาะสม เจ้าก็เป็นผู้สั่งการได้ เป็นที่เหมาะมากสำหรับปล่อยเครื่องร่อนร่มชูชีพ\n\nความภักดีต่ออินทรีและหมัดกำหนดให้ข้าต้องอยู่ห่าง เพื่อรับใช้พวกเขาได้ดีที่สุด แนวกั้นนี้เคยรุ่งเรืองกว่านี้ เช่นเดียวกับอาณาจักรเก่าที่มันเคยปกป้อง แต่ข้าจะไม่มีวันละทิ้งมัน\"" },
        completion = { "78:2112262726:314657148", "กองไฟเพิ่งเติมฟืนใหม่ แต่เห็นร่องรอยชัดเจนว่าเพิ่งออกไปอย่างเร่งรีบ" },
    },
    [92479] = { -- A Scribbled Letter
        title = { "18:38596069:736718270", "จดหมายเขียนหวัด" },
        objective = { "77:1388261603:109827819", "อ่าน Scribbled Letter แล้วคุยกับ Tordrin Stemblade ใน Northshire Abbey" },
        description = { "91:566813027:607752075 N 179:1429206747:1460933064", "มีคนขอให้ข้านำเรื่องนี้มาบอกทันทีที่เจ้ากลับจากค่ายโคบอลด์ {name} ดูเหมือนเป็นจดหมายผนึกตรา Tordrin Stemblade ครูฝึกฮันเตอร์ประจำถิ่น หาเวลาอ่านก่อนทำธุระอื่นใน Abbey" },
        completion = { { "314:1529522998:2006531310", "279:1946462761:207925060 N 25:1423895986:910919973", "279:1946462761:207925060 C 25:1423895986:910919973", "279:1946462761:207925060 R 25:1423895986:910919973" }, "เตรียมตัวให้พร้อม เรียนรู้ภูมิประเทศ แล้วกลับมาเมื่อใดที่ต้องการฝึก ข้าอยู่ที่นี่ทั้งกลางวันกลางคืน\n\nดินแดนนี้อันตรายขึ้น และเมื่อพบผู้คนอื่น คงเห็นว่าทุกคนมีปัญหาที่อยากได้ความช่วยเหลือ ความช่วยเหลือที่นักผจญภัยมีฝีมือมอบให้ได้ โชคดี", variants = { { "279:1946462761:207925060 C 25:1423895986:910919973", "เตรียมตัวให้พร้อม ทำความรู้จักแถบนี้ แล้วกลับมาหาข้าได้ทุกเมื่อที่อยากฝึก ข้าอยู่ที่นี่ทั้งกลางวันและกลางคืน\n\nดินแดนนี้อันตรายขึ้นทุกที พอได้พบผู้คนมากขึ้น เจ้าจะเห็นว่าพวกเขาต่างมีเรื่องให้ช่วย และ {class} ฝีมือดีอย่างเจ้าช่วยพวกเขาได้ ขอให้โชคดี" } } },
        progress = { "22:1316226568:502190038 N 41:779183975:1000506871 R 133:1722004393:2026748936", "อ้อ ได้จดหมายข้าแล้วสินะ {name}... ดี\n\nแต่ก่อนแทบไม่มีทางเห็น {race} ถือธนูสักคัน เดี๋ยวนี้คงเปลี่ยนไปแล้ว ก็ดีต่อ Stormwind แต่คงไม่ดีต่อพวกโคโบลด์กับสัตว์กินคนแถวนี้" },
        required = { [251941] = { "16:1942654891:780591781", "จดหมายเขียนหวัด" } },
        steps = { { "16:1942654891:780591781", "จดหมายเขียนหวัด" } },
    },
    [92532] = { -- The Warrior's Path
        title = { "18:856322946:281412721", "วิถีนักรบ" },
        objective = { "110:324763645:606207987", "อ่าน Crumpled Note ที่ได้รับ แล้วไปหา Blademaster Ren ในหอคอยยามของ Thendal Village" },
        description = { "229:1812370001:127145220", "ระหว่างเจ้าไม่อยู่ Blademaster Ren ครูฝึกนักรบของเราขอให้ส่งเจ้าไปหาเมื่อกลับมา นางฝากบันทึกนี้ไว้ให้ด้วย\n\nอ่านแล้วไปหา Blademaster Ren ในหอคอยยามของหมู่บ้าน" },
        progress = { "34:471163668:665546203", "มาฝึกฝนสินะ?" },
        completion = { { "322:1133127312:410441574", "290:1636021787:1273938357 N 26:1605466164:1817396099", "290:1636021787:1273938357 C 26:1605466164:1817396099", "290:1636021787:1273938357 R 26:1605466164:1817396099" }, "เจ้ากำลังจะเริ่มการเดินทางอันตราย โลกเราเปลี่ยนแปลง และหากผู้คนเราหวังรอด ก็ต้องมีผู้มุ่งมั่นนำทางและคุ้มครองผู้อื่น เมื่อแข็งแกร่งขึ้น เจ้าต้องมีคำชี้แนะ มาหาข้า ข้าจะฝึกให้เท่าที่ทำได้ระหว่างเจ้าก้าวหน้า\n\nโชคดี สหาย ขอสายลมนำทาง" },
        required = { [282419] = { "13:2102951297:153168764", "บันทึกยับยู่ยี่" } },
        steps = { { "13:2102951297:153168764", "บันทึกยับยู่ยี่" } },
    },
    [94003] = { -- The Skybreaker Bulwark
        title = { "22:1723984619:1135871434", "โล่ Skybreaker" },
        objective = { "75:2013288094:1550704862", "ชิง Skybreaker Bulwark คืนจาก Zaal Stormshield ที่ Shrine of Akir" },
        description = { "504:410331259:1851396106", "ข้าคือผู้เหลือรอดเพียงคนเดียวของสายตระกูล Skybreaker บน Zephras Isle ที่เหลือถูก Al'Aketh สังหาร\n\nสิ่งเดียวที่หนักกว่าความเศร้าคือความอับอาย โล่บรรพชน Skybreaker Bulwark อยู่ในมือสาวกลัทธิชื่อ Zaal Stormshield ตำนานตระกูลบอกว่าผู้คู่ควรที่ถือโล่นี้จะไม่พบอันตราย\n\nZaal ไม่คู่ควร ข้าแน่ใจ ไปหาชายผู้นี้ที่ Shrine of Akir แล้วชิงโล่คืน ทำได้แล้วข้าจะสอน Skybreaker Defense" },
        progress = { "27:568705573:414824516", "<Seena พยักหน้าให้เจ้าอย่างห้วน ๆ>" },
        completion = { "393:247170135:1983721926", "เจ้าทำสิ่งที่ข้าทำไม่ได้และกอบกู้เกียรติของตระกูลข้าคืนมา ข้าจะตอบแทนด้วยของขวัญที่มีคนเพียงไม่กี่คนบน Zephras คู่ควรจะได้รับ ข้าจะสอนเคล็ดวิชา Skybreaker Defense ให้เจ้า\n\nเจ้าต้องมีโล่ไว้ฝึกสิ่งที่ข้าจะสอนด้วย รับใบนี้ไปเถิด ตอนนี้ข้าได้ Skybreaker Bulwark คืนมาแล้ว ข้าคงไม่ได้ใช้มันเท่าไร\n\nBanu'Adoraah สหาย", variants = { { "393:177344672:1910398091", "เจ้าทำสิ่งที่ข้าทำไม่ได้และกอบกู้เกียรติของตระกูลข้าคืนมา ข้าจะตอบแทนด้วยของขวัญที่มีคนเพียงไม่กี่คนบน Zephras คู่ควรจะได้รับ ข้าจะสอนเคล็ดวิชา Skybreaker Defense ให้เจ้า\n\nเจ้าต้องมีโล่ไว้ฝึกสิ่งที่ข้าจะสอนด้วย รับใบนี้ไปเถิด ตอนนี้ข้าได้ Skybreaker Bulwark คืนมาแล้ว ข้าคงไม่ได้ใช้มันเท่าไร\n\nBanu'Adoraah สหาย" } } },
        required = { [263993] = { "18:2093213735:1018196778", "โล่ป้องกันแห่ง Skybreaker" } },
        steps = { { "18:2093213735:1018196778", "โล่ป้องกันแห่ง Skybreaker" } },
    },
    [97277] = { -- Grund and Gozwin
        title = { "16:1635555028:2112154403", "Grund และ Gozwin" },
        objective = { "126:132484312:832005111", "หาค่ายของ Grund และ Gozwin บนเนินเขาทางตะวันตกเฉียงเหนือ นำ Gozwin's Mechanic's Log กลับมา และฆ่า Snow Leopard Prowler" },
        description = { "496:1657901193:628484389", "เฮ้ ข้าหันหลังเตรียมหมูย่างอยู่ ก็ได้ยิน Gozwin สหายข้ากรีดร้องสุดชีวิต!\n\nพอหันไปเห็นแค่เขี้ยวโหดกับเงาวูบ อุ้งเท้าใหญ่อะไรอย่างนั้น! เสือดาวหิมะกำลังลากเหยื่อโนมไป ข้าคว้าปืนลูกซองยิงเหนือเจ้าสัตว์ มันปล่อยเขาแล้ววิ่งหนี\n\nโชคดีที่เฒ่า Goz มีแค่รอยข่วนลึก ๆ\n\nกลับค่ายบนเนินเขาตะวันตกเฉียงเหนือ นำ Gozwin's Mechanic's Log มา ฆ่าเสือดาวหิมะนั่นด้วยหากเห็น!" },
        progress = { "191:319583169:1593040531", "Goz ผู้น่าสงสารห่วงหุ่นเดินกลมากกว่าตัวเอง บอกว่าหากใครได้บันทึกช่างไป เขาซวยแน่ ฮ่า! ข้าถึงบอกให้ทิ้งงานไว้บ้านไง!" },
        completion = { { "381:1130633681:1652866108", "268:1584952987:785762951 N 107:819202963:777943061", "268:1584952987:785762951 C 107:819202963:777943061", "268:1584952987:785762951 R 107:819202963:777943061" }, "ใช่ ไม่แปลกใจที่ได้ยินว่าเสือดาวหิมะกินหมูที่เราเตรียมย่างอยู่!\n\nพอเจ้าเอาสมุดบันทึกกลับมา Goz ก็หายเครียดไปเรื่องหนึ่ง บางทีจะทุ่มแรงทั้งหมดให้ฟื้นตัวกลับมายืนได้แล้ว\n\nขอบใจ สหาย รับของเล็กน้อยแทนคำขอบคุณสำหรับการเดินทางและปกป้องเนินเขา" },
        required = { [277976] = { "23:35034664:1510894781", "สมุดบันทึกงานช่างของ Gozwin" } },
        steps = { { "23:35034664:1510894781", "สมุดบันทึกงานช่างของ Gozwin" } },
        objectiveLabels = {
            monster = { ["Snow Leopard Prowler slain"] = "ปราบ เสือดาวหิมะซุ่มล่า" },
        },
    },
    [1858] = { -- The Shattered Hand
        title = { "18:2067249054:972445469", "Shattered Hand" },
        objective = { "123:27291455:396980667", "ขโมย Tazan's Key แล้วใช้เปิด Satchel ของเขา นำของข้างในไปให้ Therzok ที่ Cleft of Shadow ใน Orgrimmar" },
        description = { "441:93078135:1210506010", "ข้าจะให้เจ้าหาวิธีเปิดถุงของ Tazan แล้วนำของข้างในกลับมา กลไกล็อกซับซ้อน คงง่ายที่สุดหากได้กุญแจมา\n\nเมื่อไม่พบกุญแจบนศพ Tazan ข้าคงต้องคิดว่าเขาฝากคนอื่นไว้... อา ใช่แล้ว เขามีผู้ช่วยชื่อ Gamon เป็นขี้เมา คงพบได้ที่โรงเตี๊ยม บางทีเจ้าอาจเอากุญแจจากเขามาอย่างเงียบ ๆ" },
        progress = { "107:923480572:483134918", "น่าหงุดหงิดไหมที่สิ่งปรารถนาอยู่ในกำมือ แต่ไม่มีทางเข้าถึงมัน?" },
        completion = { "77:717089657:1329602321 N 152:1298635550:2010031823", "หืม น่าสนใจจริง ๆ เจ้าพิสูจน์คุณค่าเกินพอแล้ว {name} ข้าประทับใจมาก ถือว่าตนเป็นสมาชิกใหม่ล่าสุดของ Shattered Hand ได้เลย รับนี่ด้วย ข้าว่ามันจะช่วยเจ้าได้มากในอนาคต" },
        required = { [7295] = { "15:2090087845:1537148660", "สมุดบันทึกของ Tazan" } },
        steps = { { "15:2090087845:1537148660", "สมุดบันทึกของ Tazan" } },
    },
    [1859] = { -- Therzok
        title = { "7:870260402:1961053721", "Therzok" },
        objective = { "55:950741250:956122676", "คุยกับ Therzok ที่ Cleft of Shadow ใน Orgrimmar" },
        description = { "18:570052052:1625568228 N 308:4929022:1342089390", "เบาเสียงหน่อย {name} ใช่ ข้ารู้ชื่อเจ้า มีคนสั่งให้คอยมองหาออร์คหน้าตาอย่างเจ้า\n\nจากที่ได้ยิน เจ้าเอาตัวรอดในการต่อสู้ได้ และไม่รังเกียจเล่ห์กลบ้างเป็นครั้งคราว\n\nข้าพูดถูกไหม?\n\nอย่างไรก็ไปพบ Therzok ใน Orgrimmar เขามีข้อเสนอให้ฟัง" },
        completion = { "143:625629707:334516447", "ดีมาก ยินดีที่ Kaplak ติดต่อเจ้าได้\n\nเรามีเรื่องต้องคุยกันหลายอย่าง โดยเฉพาะอนาคตเจ้ากับ Hand" },
    },
    [1885] = { -- Mennet Carkad
        title = { "13:420313758:917512367", "Mennet Carkad" },
        objective = { "65:694112429:878617753", "คุยกับ Mennet Carkad ที่ Rogues' Quarter ใน Undercity" },
        description = { "N 273:655195032:997776511", "{name}? ไม่ค่อยเหมือนที่คาด เมื่อ Carkad สนใจเจ้าด้วยตัวเอง แต่รูปลักษณ์อาจหลอกตาได้ใช่ไหม?\n\nอย่างไรก็ควรไปพบเขาโดยเร็ว เจ้าคงไม่อยากรู้ว่าเกิดอะไรกับคนก่อน ๆ ที่เลือกเพิกเฉยต่อคำเรียก" },
        completion = { "139:112080152:1531773328", "หืม คงรีบมาทันทีที่ได้ยินคำเรียกข้าใช่ไหม? แน่นอน ข้าคาดหวังเช่นนั้นจากผู้สมัครเป็น Deathstalker" },
    },
    [1886] = { -- The Deathstalkers
        title = { "17:153157761:1025694371", "Deathstalkers" },
        objective = { "89:1502165658:1533319274", "นำ Astor's Letter of Introduction กลับไปให้ Mennet Carkad ที่ Rogues' Quarter" },
        description = { "128:95216507:1917981730 N 356:1874577438:1743605618", "หากจะเข้าร่วม Deathstalkers องครักษ์ชั้นยอดของ Lord Varimathras เจ้าต้องพิสูจน์คุณค่า\n\nข้าไม่โกหก {name} งานนี้อาจทำให้เจ้าตาย\n\nมีบางเรื่องต้องจัดการ ข้าต้องการข้าวของส่วนตัวของ Astor Hadren ผู้ส่งสารระหว่าง Silverpine กับ Undercity ส่วนวิธีเอามา ข้าปล่อยให้เจ้าตัดสินใจ\n\nรู้น้อยเรื่องลักษณะงานนี้จะดีกับเจ้า ทำสำเร็จแล้วข้าจะบอกเพิ่ม" },
        progress = { "18:1874344052:671616677", "มีความสำเร็จมารายงานหรือ?" },
        completion = { "11:534428891:784080240 N 197:1688708142:1816098222", "ทำดีมาก {name} เจ้าผ่านส่วนแรกของบททดสอบแล้ว หวังว่า Andron ยังไม่ได้ข่าวเรื่องที่เจ้าทำ และเราจะทำให้เขาเชื่อว่าเจ้าเป็นผู้ส่งสารที่รออยู่ได้จริง ๆ" },
        required = { [7231] = { "30:1014108220:883467978", "จดหมายแนะนำตัวของ Astor" } },
        steps = { { "30:1014108220:883467978", "จดหมายแนะนำตัวของ Astor" } },
    },
    [1898] = { -- The Deathstalkers
        title = { "17:153157761:1025694371", "Deathstalkers" },
        objective = { "40:374830898:86313286", "คุยกับ Andron Gant ใน Undercity" },
        description = { "466:401084749:697722699", "จดหมายแนะนำตัวน่าจะพอทำให้ Andron เชื่อว่าเจ้าเป็นผู้ส่งสารที่รอ ข้าเคยพบเขา เขาไม่ได้หัวดีพอจะสงสัยมากนัก\n\nLord Varimathras สงสัยว่า Andron ช่วยกลุ่มอื่นอยู่ อยากรู้ว่าองค์กรใดและต้องการหลักฐาน\n\nข้าอยากให้เจ้าคุยกับ Andron แล้วเอาข้อมูลนี้มา พบเขาได้ที่ร้านใกล้ Apothecarium" },
        progress = { "34:1240707589:1700190546", "สวัสดี มีอะไรให้ข้าช่วยหรือ?" },
        completion = { "275:2143851800:1758801456", "อา ใช่ ข้ารอเจ้าอยู่ คนรู้จักร่วมกันของเราคงพอใจข้อมูลที่ข้าให้ไปแล้วสินะ?\n\nคงไม่มีประโยชน์จะถามเจ้า ข้าสงสัยว่าพวกเขาคงไม่ให้เจ้ารับรู้เรื่องนี้ จะไว้ใจผู้ส่งสารมากขนาดนั้นทำไม หืม?" },
        required = { [7231] = { "30:1014108220:883467978", "จดหมายแนะนำตัวของ Astor" } },
        objectiveLabels = {
            item = { ["Astor's Letter of Introduction"] = "จดหมายแนะนำตัวของ Astor" },
        },
    },
    [1899] = { -- The Deathstalkers
        title = { "17:153157761:1025694371", "Deathstalkers" },
        objective = { "75:1397291648:615129748", "นำ Andron's Ledger ไปให้ Mennet Carkad ที่ Rogues' Quarter ใน Undercity", variants = { { "74:1021148316:424245484", "นำ Astor's Ledger ไปให้ Mennet Carkad ที่ Rogues' Quarter ใน Undercity" } } },
        description = { "251:1429027314:239576843", "สมุดบัญชีที่มีข้อมูลซึ่งนายจ้างเจ้าต้องการอยู่บนชั้นหนังสือด้านหลังข้า ฝากความปรารถนาดีไปด้วย และบอกว่าหากเห็นคุณค่าพอจะร่วมงานกันต่อ ข้าก็อยากให้พวกเขาส่งเจ้ามา" },
        progress = { "9:471947649:1360905426 N 1:63:63", "สำเร็จไหม {name}?" },
        completion = { "146:1134939189:726921611", "นี่ข้อมูลมากกว่าที่ข้าคาดว่าจะได้จาก Andron เสียอีก ขอเวลาอ่านก่อนจะมอบงานต่อไป" },
        required = { [7294] = { "15:655925524:971131134", "สมุดบัญชีของ Andron" } },
        objectiveLabels = {
            item = { ["Andron's Ledger"] = "สมุดบัญชีของ Andron" },
        },
    },
    [1963] = { -- The Shattered Hand
        title = { "18:2067249054:972445469", "Shattered Hand" },
        objective = { "80:2045253788:633645940", "ฆ่า Tazan แล้วนำ Satchel ของเขาไปให้ Therzok ที่ Cleft of Shadow ใน Orgrimmar" },
        description = { "470:1776722513:1076439530", "Warchief ใช้วิธีอ้อมค้อมเกินไป ระวังเกินกว่าจะปล่อยกำลัง Horde ออกมา ครั้งหนึ่งเราแข็งแกร่งกว่านี้ ล้วนเป็นผู้พิชิตทรงอำนาจ เราต้องกู้ความภาคภูมินั้น และ Shattered Hand จะทำ\n\nเราสร้างกำลังจากเงามืด โจมตีจุดเปิด และลอบโค่นศัตรู ข้ามีงานให้เจ้าทำเพื่อพิสูจน์คุณค่า\n\nโทรลล์ Tazan ค้าขายกับโจรสลัดใกล้ Ratchet เขามีข้อมูลที่ข้าต้องการ ฆ่าเขาแล้วนำถุงมาให้ข้า" },
        progress = { "93:945134911:1417959263", "คนโง่เท่านั้นที่เชื่อว่าการชักขวานบุกเข้าหาอันตรายกว่ามีดในความมืด" },
        completion = { "222:100225575:48106701", "หืม แม้ยินดีที่ Tazan ไม่อยู่แล้ว แต่ถุงล็อกไว้ก็ไม่มีประโยชน์ เราต้องการข้อมูลข้างใน\n\nนี่น่าจะเป็นบททดสอบที่สองอันคู่ควรสำหรับผู้ต้องการเข้าร่วม Shattered Hand" },
        required = { [7209] = { "15:835285245:1872532245", "กระเป๋าสะพายของ Tazan" } },
        steps = { { "15:835285245:1872532245", "กระเป๋าสะพายของ Tazan" } },
    },
    [1998] = { -- Fenwick Thatros
        title = { "15:1249918395:1051536513", "Fenwick Thatros" },
        objective = { "102:1192307677:25645550", "ฆ่า Fenwick Thatros แล้วนำหัวกลับไปให้ Mennet Carkad ที่ Rogues' Quarter ใน Undercity" },
        description = { "278:1293983498:1230918363 N 216:1571941255:313465252", "Lord Varimathras เพิ่งส่งสารถึงข้าเรื่องภัยต่อ Forsaken ที่ต้องกำจัดทันที เขาชื่อ Fenwick Thatros ผู้ที่ Lord Varimathras เชื่อว่าเป็นผู้นำอันเดดซึ่งลงหลักใน Silverpine Forest\n\nข้านึกถึงชื่อเจ้าทันที {name} ไว้ใจความสามารถพอว่าเจ้าจะทำภารกิจอย่างไร้ที่ติ\n\nรายงานล่าสุดจาก Deathstalkers ใน Silverpine บอกว่าพบ Thatros ได้ใกล้ท่าเรือผุพังริม Lordamere" },
        progress = { "83:1629031119:898927701", "ข้าไว้ใจเจ้าสูงสุดให้ทำงานนี้รับใช้ Lord Varimathras" },
        completion = { "18:366880880:1038443585 N 178:1415014204:963183924", "ทำดีแล้ว {name} เจ้ารับใช้ Deathstalkers หลายครั้ง พิสูจน์คุณค่า บางทีถึงเวลาฝึกวิชาเงามืดให้ลึกขึ้น" },
        required = { [7306] = { "14:1236022489:1883215309", "ศีรษะของ Fenwick" } },
        steps = { { "14:1236022489:1883215309", "ศีรษะของ Fenwick" } },
    },
    [1999] = { -- Tools of the Trade
        title = { "18:2016515751:456482828", "เครื่องมือประจำอาชีพ" },
        objective = { "102:963140752:1148529813", "หา Dalaran Status Report แล้วนำกลับไปให้ Mennet Carkad ที่ Rogues' Quarter ใน Undercity" },
        description = { "296:353219994:369238614 N 167:2006681970:1604742264", "พ่อมด Kirin Tor ที่ Ambermill เก็บเอกสารสำคัญเกี่ยวกับสภาพปัจจุบันของ Dalaran ไว้ เรารู้จากคำรับของเชลยคนหนึ่ง Lord Varimathras มอบหน้าที่กู้เอกสารแก่ Deathstalkers\n\nงานนี้ตกเป็นของเจ้า {name} แต่ต้องมีอุปกรณ์และความรู้สะเดาะกุญแจ คุยกับ Estelle Gendry ผู้จัดหาอุปกรณ์ของเรา ขอชุดเครื่องมือก่อนออกเดินทาง" },
        progress = { "32:865582725:343270539 N 1:63:63", "พบเอกสารหรือยัง {name}?" },
        completion = { { "11:1776810664:1873330125 N 220:253500026:441726536", "11:1776810664:1873330125 N 220:1616036059:608914878" }, "ดีมาก {name}! เจ้าเรียนศิลปะสะเดาะกุญแจได้ดี และเร็วกว่าที่ข้าคาดได้เสียอีก\n\nข้าคิดถูกที่ไว้ใจ เชื่อเถอะ เด็กเอ๋ย ข้าเห็นว่าเจ้าจะก้าวหน้าในงานสายนี้ได้ไกล" },
        required = { [7309] = { "21:1038476300:822945600", "รายงานสถานการณ์ Dalaran" } },
        steps = { { "21:1038476300:822945600", "รายงานสถานการณ์ Dalaran" } },
    },
    [2205] = { -- Seek out SI: 7
        title = { "14:1420607869:960453057", "ไปหา SI: 7" },
        objective = { "81:1313701044:683701550", "นำพัสดุของ Keryn Sylvius ไปให้ Master Mathias Shaw ที่ Stormwind Barracks" },
        description = { { "376:1639220137:1242487801", "377:1991182935:584661033" }, "ตราหรือ? โอ้ ไม่มีอะไรหรอก เจ้ามือใหม่ อย่างไรก็ไม่ใช่สิ่งที่เจ้ารับมือได้ ดูแล้ว Mathias คงเข้าใจผิดว่าเป็นเด็กส่งชีสแทนโร้กที่เหมาะสม แต่ข้าได้รับงานและสัญญาว่าจะทำให้สำเร็จ\n\nพูดถึงงาน นำพัสดุนี้ให้ Mathias เขาอาจให้งานเล็ก ๆ สักงานสองงาน\n\nรีบลงมือ" },
        progress = { "16:1688106022:1028901558 C 1:63:63", "มีอะไรให้ข้าช่วย {class}?" },
        completion = { "234:1223445500:730388306", "หาข้าเจอแล้ว ดูจากสภาพ การวิ่งกับค้นหาคงทำระบบเจ้าเหนื่อยหนักทั้งกายใจ\n\nอยากให้ Renzik บอกทางไปโรงเตี๊ยม หรือพร้อมทำงานแล้ว?" },
        required = { [7674] = { "19:1819719050:992005377", "พัสดุถึง Mathias" } },
        steps = { { "19:1819719050:992005377", "พัสดุถึง Mathias" } },
    },
    [2206] = { -- Snatch and Grab
        title = { "15:1596706878:1174243061", "ฉกแล้วชิง" },
        objective = { "85:1261868212:1603672556", "หา Defias Dockmaster แล้วนำ Shipping Schedule กลับมาให้ Master Mathias Shaw" },
        description = { "327:923908812:1412592971 N 81:2068367482:2077914390 N 78:1530344365:1953544091", "สายลับภาคสนามรายงานความเคลื่อนไหว Defias หนาแน่นทางใต้ของ Goldshire รายงานบอกว่าพวกมันยึด Jerod's Landing และใช้ลักลอบขนของเถื่อนจำนวนมากจาก Redridge ไป Westfall\n\nข้าต้องการให้เจ้าแทรกซึมอาคารท่าเรือ แล้วเอาตารางขนส่งมา {name} คงอยู่ลึกในกระเป๋าของ Dockmaster\n\n...และ {name} หากถูกจับได้ SI:7 จะปฏิเสธว่าไม่เคยรู้ถึงการมีอยู่ของเจ้า" },
        progress = { "76:696836074:1807168555 C 1:46:46", "ทุกขณะที่เสียเวลาเตร็ดเตร่ในค่ายทหาร ชีวิตเจ้าก็ยิ่งริบหรี่ {class}" },
        completion = { "138:587889433:2109030521 N 195:149820958:1914076833", "ข้าอัศจรรย์ใจ... ที่ในที่สุด Keryn ก็หาคนใหม่ซึ่งอาจมีแววเป็นโร้กที่เหมาะสมได้ รับดาบนี้ {name} สักวันจะถูกเรียกมารับใช้ SI:7 อีก ฝึกฝีมือ ลืมตาระวังภัย และรักษาคมดาบไว้\n\nเจ้าจะไม่เห็นเรามา แต่จะรู้สึกเมื่อเราถึงตัว..." },
        required = { [7675] = { "24:1754762657:1519688130", "กำหนดการขนส่งของกลุ่ม Defias" } },
        steps = { { "24:1754762657:1519688130", "กำหนดการขนส่งของกลุ่ม Defias" } },
    },
    [2218] = { -- Road to Salvation
        title = { "17:850834989:1477262698", "หนทางสู่ความรอด" },
        objective = { "43:1835983408:1327636321", "คุยกับ Hulfdan Blackbeard ใน Ironforge" },
        description = { "446:368052956:978363846", "วิญญาณหลงทางอีกคนมาหาคำชี้แนะหรือ? คงอยากหาจุดหมาย จุดหมายของเจ้าเอง ข้าเห็นเป็นพันครั้งแล้ว วีรชนอีกคนหางานทำ\n\nวันนี้เจ้าโชคดี สหาย Hogral มีทางรักษาอาการเจ้า\n\nทำตามนี้ ไปถนนเส้นนี้ขึ้น Ironforge มุ่งสู่ Forlorn Cavern เมื่อถึงก็หาสมาคมโจรแล้วคุยกับ Hulfdan Blackbeard เขาจะนำเจ้าสู่หนทางความรอด" },
        completion = { "239:1217328981:947825267 N 1:33:33", "คิดว่าตัวเองเป็นวายร้ายตัวจริงหรือ? มีชะตาเป็นหนึ่งในคนโปรดไม่กี่คนของ Blackbeard เป็นเจ้าหน้าที่ Hidden Circle?\n\nมีแต่เจ้าตัวแสบไร้ประโยชน์เท่านั้นที่คิดกับตัวเองสูงอย่างนี้\n\nนั่นแหละที่เรามองหา! ยินดีต้อนรับ {name}!" },
    },
    [2238] = { -- Simple Subterfugin'
        title = { "19:1788064199:2026398233", "อุบายง่าย ๆ" },
        objective = { "34:419253842:999836012", "หา Onin MacHammar ใกล้ Gnomeregan" },
        description = { "152:1065377478:828067319 N 333:435953345:807912918", "คืออย่างนี้ กษัตริย์กำลังเปิดหน้าดินเหมืองหาแร่กับอัญมณี ทรัพย์มากกว่าคนแคระคนหนึ่งควรได้เห็นในสิบชาติ\n\nHidden Circle มีสิ่งที่เราให้คุณค่า {name} เราให้คุณค่ากับของมีค่า เข้าใจไหม?\n\nเราว่ากษัตริย์ควรแบ่งทรัพย์บ้าง แต่ไม่อยากให้เฒ่า 'Stinkbeard' รู้ว่ากำลังแบ่ง เข้าใจที่ข้าหมายถึงนะ\n\nไปคุยกับ Onin MacHammar แถว Gnomeregan แล้วนำรายงานกลับมา คนแคระเจ้าเล่ห์ซ่อนตัวในหมู่โนมโรคเรื้อน ระวังด้วย" },
        completion = { "51:346988069:717983191", "ชู่ว์! เบาเสียง เจ้าคนโง่ พวกมันจะได้ยินเรา" },
    },
    [2239] = { -- Onin's Report
        title = { "13:1428487726:2007826930", "รายงานของ Onin" },
        objective = { "48:1784257234:891835923", "นำ Onin's Report กลับไปให้ Hulfdan ใน Ironforge" },
        description = { "393:1263814770:2098079301 R 55:1375172097:346442915", "เหมืองหรือ? ใช่ ข้าเห็นรถถังไอน้ำหุ้มเกราะยักษ์พวกนั้นผ่านที่นี่แทบทุกวัน\n\nสายข่าวตะวันออกบอกว่ารถถังเริ่มจาก Ironforge ไปรับของที่ Gol'Bolar Quarry แวะ Kharanos เติมเชื้อเพลิง แล้วด้วยเหตุผลบ้าอะไรก็ไม่รู้ อ้อมไกลผ่าน Gnomeregan ก่อนกลับ Ironforge ส่งสินค้า\n\nทั้งหมดอยู่ในรายงาน ชาว{race} นำกลับไปให้ Hulfdan วางแผนขั้นต่อไป" },
        progress = { "125:656821772:1641703466", "ชอบกลิ่นโนมโรคเรื้อนไหม? ข้าถามเพราะเจ้าทำหน้ายิ้มบ้า ๆ\n\nมีข่าวอะไรจาก Onin?" },
        completion = { "55:296931642:1542334659 N 221:1013711943:1357191091", "เส้นทางอ้อมหรือ? ในนามหนวดเคราข้า!\n\nทำดีแล้ว {name} รับมีดแล้วไปได้ Circle จะเรียกอีกเมื่อขั้นสามพร้อมลงมือ\n\nขั้นสามคืออะไร? ก็ตามหลังขั้นสอง ข้าเอารองเท้าเตะก้นเจ้าไง\n\nสนใจไหม?" },
        required = { [7715] = { "13:1428487726:2007826930", "รายงานของ Onin" } },
        steps = { { "13:1428487726:2007826930", "รายงานของ Onin" } },
    },
    [2241] = { -- The Apple Falls
        title = { "15:753977328:136163772", "ผลแอปเปิลร่วง" },
        objective = { "42:1998141265:1726161771", "นำ Jannok's Rose ไปให้ Syurna ใน Darnassus" },
        description = { "500:1441782104:2116846912", "พวกเขาว่าข้า 'ป่วยรัก' ไม่รู้หมายความว่าอะไร\n\nใช่ ข้าคิดถึง Syurna ทุกขณะที่ตื่น ใช่ บ้านเต็มไปด้วยภาพวาดของนาง ใช่ ข้ามักไม่กิน ไม่นอน ไม่ดื่มหลายวัน พลางคร่ำครวญถึงรักที่เราอาจมีได้ มันผิดนักหรือ?\n\nตอนนี้นางไม่ยอมพบข้า! ข้าเลยนะ! ส่งข้อความไปแล้ว แต่นางไม่ยอมคุยกับคนอื่นด้วยซ้ำ เว้นแต่เป็นโร้ก\n\nช่วยนำดอกไม้นี้ให้นางได้ไหม? อย่าลืมบอกว่าจาก Jannok" },
        progress = { "70:634208936:1105088723", "โอ้ ช่างดีจริง ๆ เจ้าพาดอกไม้มางานศพตัวเอง" },
        completion = { "200:2091209275:1290731876 C 1:63:63", "หากเก็บดอกไม้ทุกดอกที่เจ้างั่ง Jannok ส่งมา ข้าคงเปิดร้านได้แล้ว อย่างไรก็ดูเหมือนผู้ส่งสารคนล่าสุดอาจมีประโยชน์\n\nสนใจงานไหม {class}?" },
        required = { [7735] = { "13:350335769:1685251342", "ดอกกุหลาบของ Jannok" } },
        steps = { { "13:350335769:1685251342", "ดอกกุหลาบของ Jannok" } },
    },
    [2242] = { -- Destiny Calls
        title = { "13:1095668371:1561707428", "ชะตาเรียกหา" },
        objective = { "81:1100490885:1887733227", "หา Sethir the Ancient แล้วนำเบาะแสที่ค้นพบกลับไปให้ Syurna" },
        description = { "377:1397825152:99682262 N 74:1767055873:1801191766", "เราเชื่อว่ามีผู้หนึ่งช่วยให้เข้าใจสิ่งที่เกิดกับป่า Teldrassil ได้ แต่น่าเสียดาย ความพยายามให้มันร่วมมือจบหายนะ\n\nมันซ่อนบนกิ่งไม้ริม Oracle Glade ทุกคนที่เข้าหาเซเทอร์ ไม่ว่าด้วยกำลังหรือเจรจา ล้วนพบจุดจบ บางทีการลอบเร้นคือคำตอบ {name}\n\nหาว่า Sethir the Ancient พกอะไรในถุง แล้วกลับมารายงานข้า" },
        progress = { "53:1670994418:1542668712 N 1:63:63", "มีอะไรจาก Sethir the Ancient มารายงานไหม {name}?" },
        completion = { "19:736622476:532871052 N 244:1154073795:1982430795", "ข่าวร้ายนัก {name} ดูเหมือนโรคที่ครอบงำป่าและแม่น้ำ Darkshore เริ่มทำบ้านเราแปดเปื้อน\n\nเจ้ารับใช้ได้ดี แต่ไม่มีอะไรให้ทำต่อที่นี่ รับดาบเป็นรางวัลที่รับใช้ Teldrassil" },
        required = { [7737] = { "16:405557435:1467502215", "บันทึกของ Sethir" } },
        steps = { { "16:405557435:1467502215", "บันทึกของ Sethir" } },
    },
    [2259] = { -- Erion Shadewhisper
        title = { "18:1374837210:916765794", "Erion Shadewhisper" },
        objective = { "40:557520079:1787334336", "ติดต่อ Erion Shadewhisper ใน Darnassus" },
        description = { "14:2042533762:194019387 N 103:1503221519:351408342", "ไม่ต้องห่วง {name} ข้าไม่ได้ส่งไปหา Syurna Erion ต้องการพบที่ Cenarion Enclave รีบไป!" },
        completion = { "26:1005189779:2112313354 R 20:295781242:70215077", "ถึงเวลาออกสู่ทางใหม่ ชาว{race} โลกกำลังรออยู่" },
    },
    [2260] = { -- Erion's Behest
        title = { "14:1671511480:1386112461", "คำขอของ Erion" },
        objective = { "65:1985840294:1758918732", "เดินทางไป Stormwind City แล้วขอคำปรึกษาจาก Renzik \"The Shiv\"" },
        description = { "44:155072887:1364693296 N 211:1712949068:421599686 N 95:1835487754:1288463050", "ข่าววีรกรรมเจ้าแพร่ไกล {name} ไกลจนหน่วยข่าวกรอง Stormwind ขอพบเจ้าโดยระบุชื่อ\n\nการเดินทางเหนื่อยยากและมีภัย แต่โอกาสฝึกใต้ SI:7 ไม่ควรมองข้าม\n\nโลกใหม่รออยู่ {name} ไป Old Town ใน Stormwind แล้วคุยกับ Renzik \"The Shiv\" ที่สำนักงานใหญ่ SI:7" },
        completion = { "34:1917871903:1564754975 N 94:992456729:727515230", "เจ้าตอบรับคำเรียก SI:7 {name} เดินทางจากฝั่งห่างไกลมาเข้าร่วมเรา แต่ยังมีอีกมากให้เรียนรู้" },
    },
    [2281] = { -- Redridge Rendezvous
        title = { "19:1264923921:196432115", "นัดพบที่ Redridge" },
        objective = { "75:355472380:1128750784", "ไป Lakeshire ใน Redridge Mountains แล้วคุยกับ Lucius" },
        description = { "124:525342452:499108452 N 228:188991670:1442207927", "ส่งเจ้าออกภาคสนามตอนนี้ก็เท่ากับให้ไปตาย Renzik ไม่อยากมีโร้กตายเพิ่มในความรับผิดชอบ แต่อย่าห่วง {name} Renzik จะทำให้พร้อม\n\nไป Redridge Mountains คุยกับ Lucius ผู้ร่วมงาน SI:7 พบเขาได้แถวท่าเรือ Lakeshire กับพวกไร้ประโยชน์น่าสงสัยคนอื่น" },
        completion = { "55:2066000857:644894921 N 69:761285197:1225943821", "อา นิ้วเจ้าอ้วนไปหน่อยสินะ? ไม่ต้องห่วง {name} ข้าเคยฝึกโจรไร้ประโยชน์กว่าเจ้าให้เป็นโร้กมีฝีมือมาแล้ว" },
    },
    [2298] = { -- Kingly Shakedown
        title = { "16:1522154873:779115884", "รีดทรัพย์กษัตริย์" },
        objective = { "51:724611706:302913590", "เดินทางไป Stormwind แล้วหา Renzik \"The Shiv\"" },
        description = { "477:579460592:847716442", "ตอนนั้นเรากำลังจะวางแผนขั้นสาม คนหัวทึบของ Magni สองสามคนก็บุกเข้ามา พูดเรื่องปล้นอะไรสักอย่าง แล้วจับคน Hidden Circle ไปบ้าง\n\nไม่มีใครใส่ตรวนเฒ่า Blackbeard ได้! เถียงกันรุนแรง แล้วไม่รู้ทำไมชื่อเจ้าหลุดออกมา!\n\nคำแนะนำข้าหรือ? ขึ้นกริฟฟอนเที่ยวแรกออก Ironforge ไป Stormwind ไป Old Town แล้วคุยกับสหายเก่าข้าชื่อ Renzik \"The Shiv\"" },
        completion = { "65:1074965240:1473968504", "ดีเสมอที่มีโร้กของ Hulfdan มาอยู่กับเรา!" },
    },
    [2299] = { -- To Hulfdan!
        title = { "11:468981931:333399177", "ไปหา Hulfdan!" },
        objective = { "54:74100843:307606613", "เดินทางไป Ironforge แล้วคุยกับ Hulfdan Blackbeard" },
        description = { "21:404070415:1036556769 N 160:1115302903:1600079883", "ไปอยู่ไหนมา {name}? Hulfdan ตามหาทั่วแล้ว เรานึกว่ากษัตริย์ใส่ตรวนเจ้าไป\n\nไป Ironforge โดยเร็วแล้วคุยกับ Hulfdan!" },
        completion = { "21:647151092:1909676012 N 25:1898995519:2030521683", "เบาเสียง {name} ยามอาจได้ยิน" },
    },
    [2300] = { -- SI:7
        title = { "4:1413727757:187851959", "SI:7" },
        objective = { "51:724611706:302913590", "เดินทางไป Stormwind แล้วหา Renzik \"The Shiv\"" },
        description = { "100:701430891:1535488655", "Renzik ตามหาเจ้าอยู่ เจ้ามือใหม่\n\nหากเป็นข้า จะไม่ปล่อยให้รองผู้บัญชาการของ Mathias รอนาน" },
        completion = { "80:1539036251:102036277", "พร้อมทำงานหรือยัง หรือต้องงีบก่อนเริ่ม?" },
    },
    [2358] = { -- Horns of Nez'ra
        title = { "15:1016877184:1208185973", "เขาของ Nez'ra" },
        objective = { "60:1263059718:1520671192", "นำ Horns of Nez'ra กลับไปให้ Arantir's Shadow ใน Lakeshire" },
        description = { "396:1004029206:1279359793 N 1:46:46", "หลายปีก่อน Horns of Nez'ra ถูกขโมยจากคฤหาสน์ Ravenholdt ข้าค้นข้ามทวีปและมหาสมุทร สุดท้ายพบว่าเจ้าสัตว์ต่ำต้อยพวกนี้ครอบครองมาตลอด\n\nฆ่าออร์ค Blackrock ทุกตัวที่เจอจนได้ Horns of Nez'ra คืน หากได้แล้วมาหาข้าที่ Lakeshire\n\nทำให้ข้า แล้ว Ravenholdt จะรู้จักชื่อเจ้า {name}" },
        progress = { "37:776357949:762001133", "มีเขาของเจ้าชายปีศาจหรือยัง?" },
        completion = { "361:1408052368:1007359675 N 33:836311764:940758877", "การปฏิเสธไม่ให้ Ravenholdt ได้สิ่งประดิษฐ์คืน ก็เหมือนปฏิเสธการมีอยู่ของตน ทำดีมาก โร้ก สักวันอาจเดินเคียงนักฆ่า Ravenholdt\n\nเมื่อเป็นโร้กหนุ่มสาวผจญภัยใน Darkshore ข้าพบชาฟื้นพลังงานระหว่างต่อสู้ มันรับใช้ข้าอย่างดีมาหลายปี ทีนี้ข้าจะส่งต่อรสชา Thistle ให้ ล้าเมื่อใดก็ดื่ม {name} แล้วสู้ด้วยพลังอีกครั้ง!" },
    },
    [2359] = { -- Klaven's Tower
        title = { "14:2070914925:252986400", "หอคอยของ Klaven" },
        objective = { "229:724557340:439801210", "ขโมย Defias Tower Key บุกเข้า Defias Tower แล้วตรวจของใน Duskwood Chest นำข้อมูลที่พบกลับไปให้ Mathias Shaw ใน Stormwind อ่าน Kearnen's Journal เพื่อเข้าใจเรื่องหอคอย" },
        description = { "44:1139353029:940601416 N 433:183500616:873299707", "ข้าเฝ้าดูหอคอยนี้มาหลายสัปดาห์ {name} ไม่นานมานี้มีสินค้าครั้งใหญ่จาก Duskwood มาถึง พร้อมยามพวกนั้น\n\nมันเป็นอะไรน่ะหรือ? เจ้าก็เดาได้พอ ๆ กับข้า บอกได้อย่างหนึ่ง มันไม่ใช่มนุษย์\n\nอย่างไรก็มีหีบมากับสินค้า ข้าเดาว่า Abomination พวกนั้นกำลังเฝ้ามัน ซอมบี้มีหนามถือกุญแจที่ต้องใช้\n\nเอากุญแจ เข้าหอคอย แล้วตรวจทุกสิ่งในหีบนั้น นำสิ่งที่พบกลับไปให้ Mathias" },
        progress = { "28:158901905:504361030", "มีข่าวจาก Agent Kearnen ไหม?" },
        completion = { "79:562522807:171329788 N 336:743682417:1684508944 N 67:478257349:1375400566", "นี่อธิบายพวก Defias Drone ที่เจ้ากับ Kearnen เห็นนอกหอคอยได้ {name} รวมถึงความเกี่ยวข้องของ Venture Company กับ Defias และสินค้าประหลาดจาก Duskwood\n\nตามหนังสือนี้ โทรลล์ Zanzil ใน Stranglethorn พบวิธีปลุกคนตายด้วยยา... หรือให้ชัดกว่านั้น คือพิษ\n\nเจ้าจะไม่มีประโยชน์ต่อ SI:7 หากไม่เข้าใจพิษอย่างถ่องแท้ {name} โดยเฉพาะเมื่อเรามีสูตรสร้างอันเดดอยู่ในมือ" },
        required = { [7908] = { "25:853800278:1283230734", "บันทึกของ Klaven Mortwake" }, [7923] = { "16:1132575231:2052595547", "กุญแจหอคอย Defias" } },
        steps = { { "25:853800278:1283230734", "บันทึกของ Klaven Mortwake" }, { "16:1132575231:2052595547", "กุญแจหอคอย Defias" } },
    },
    [2360] = { -- Mathias and the Defias
        title = { "22:1975393464:1801102600", "Mathias กับ Defias" },
        objective = { "62:259036660:379458104", "เดินทางไป Westfall หา Agent Kearnen เพื่อรับฟังสรุปภารกิจ" },
        description = { "23:686353825:1571117783 N 391:1808617130:498407321 N 78:1530344365:1953544091", "มาทันเวลาพอดี {name} หน่วยลาดตระเวน SI:7 รายงานความเคลื่อนไหว Defias ใน Westfall หนาแน่นผิดปกติ\n\nดูเหมือนพวกมันยึดหอคอยยาม Alliance ที่ถูกทิ้ง ทางตะวันออกเฉียงใต้ของ Sentinel Hill ใช้เป็นฐานลักลอบขนของจากเส้นส่งเสบียง Redridge\n\nไป Westfall ติดต่อ Agent Kearnen เพื่อรับฟังสรุปภารกิจ จะพบนางซ่อนใกล้หอคอย\n\n...และ {name} หากถูกจับได้ SI:7 จะปฏิเสธว่าไม่เคยรู้ถึงการมีอยู่ของเจ้า" },
        completion = { "99:646707521:600664057", "ในที่สุด Mathias ก็ส่งสายลับอีกคนมาช่วยสินะ? หวังว่าเขาพร้อมฟังข่าวร้าย" },
    },
    [2378] = { -- Find the Shattered Hand
        title = { "23:641307772:1179391938", "ตามหา Shattered Hand" },
        objective = { "68:386496324:1179085908", "เดินทางไป Orgrimmar แล้วคุยกับ Shenthul ที่ Cleft of Shadow" },
        description = { "40:967656934:127390645 N 276:912197332:988134805", "เจ้ารับใช้ Deathstalkers ได้ดี {name} แต่บางทีถึงเวลาออกไปไกลกว่านี้ แม้มีแววด้านลอบเร้นและหลอกลวง ก็ยังต้องฝึกอีกมาก\n\nDeathstalkers มีพันธมิตรใน Shattered Hand ไปหาผู้ที่จะช่วยเรา หา Shenthul ใน Orgrimmar" },
        completion = { "74:236663459:1926671215", "เจ้านี่เองที่พันธมิตรทรงพลังส่งมาให้ Shenthul? ไม่น่าประทับใจเลย..." },
    },
    [2379] = { -- Zando'zan
        title = { "9:1909793191:1248232795", "Zando'zan" },
        objective = { "44:782784931:669007034", "คุยกับ Zando'zan ที่ Cleft of Shadow" },
        description = { "295:198335001:1956603307", "ความมุ่งมั่นอย่างเดียวไม่พอฝ่าอุปสรรคข้างหน้า\n\nคุยกับ Zando'zan เพื่อเริ่มฝึกเป็นสายปฏิบัติการ Shattered Hand\n\nเมื่อเชี่ยวชาญการลอบเร้นและโจรกรรมแล้วเท่านั้น จึงก้าวต่อสู่ชะตาได้" },
        completion = { "50:188666383:120779346", "บางที Zando'zan อาจคิดผิด Zando'zan ขอโทษ" },
    },
    [2380] = { -- To Orgrimmar!
        title = { "13:641968765:1267231294", "ไป Orgrimmar!" },
        objective = { "56:1620736592:1727939972", "คุยกับ Shenthul ที่ Cleft of Shadow ใน Orgrimmar" },
        description = { "294:216631844:560864087", "เจ้ายังไม่ใช่ปรมาจารย์ลอบเร้นและหลอกลวง แต่ทั้งหมดเปลี่ยนได้และจะเปลี่ยน ฝีมืออันน้อยนิดคงทำผู้บังคับบัญชาประทับใจ เพราะ Shenthul ผู้ยิ่งใหญ่ขอพบเจ้าโดยระบุชื่อ\n\nไปตามถนนเหนือจากที่นี่สู่ Orgrimmar แล้วคุยกับ Shenthul ใน Cleft of Shadow" },
        completion = { "226:723718987:725608738", "Shattered Hand ต้องตื่นตัวต่อการเปลี่ยนแปลงที่ Thrall อยากนำมาสู่ Horde จำนวนคนอย่างเดียวไม่พอเอาชนะการปกครองเขา เราต้องเชี่ยวชาญการลอบเร้นและหลอกลวง" },
    },
    [2381] = { -- Plundering the Plunderers
        title = { "25:433299377:849079153", "ปล้นพวกปล้นสะดม" },
        objective = { "292:7517562:442533321", "นำ Southsea Treasure กลับไปให้ Wrenix the Wretched ใน Ratchet อย่าลืมรับ E.C.A.C. และ Thieves' Tools จาก Wrenix's Gizmotronic Apparatus ต้องใช้ทั้งสองอย่างเพื่อทำภารกิจ\n\nหากถูกนกแก้วที่ดุร้ายผิดปกติโจมตี จงใช้ E.C.A.C.!" },
        description = { "27:614475421:1779258784 N 468:729534613:1384882045", "ข้าไม่ได้จะขู่ {name} แต่โจรห้าคนล่าสุดที่ส่งไปขโมยสมบัติ Southsea กลับมาเป็นชิ้น ๆ\n\nลงใต้ตามชายฝั่งจะพบ Tide Razor เรือของโจรสลัด Southsea รางวัลอยู่ในระวาง สมบัติ Southsea นั่นเอง ชั้นที่สองของเรือเป็นรังโจรสลัด ที่ฝึกโจรทั้งหมดของพวกมัน\n\nขึ้นเรือ ขโมยสมบัติแล้วนำกลับมา ใช้รังโจรสลัดฝึกโจรกรรมได้หากจำเป็น แต่ระวัง!" },
        progress = { "80:631631237:1432202893", "อย่างน้อยอวัยวะก็ยังครบ พบสมบัติไหม?" },
        completion = { { "59:27181636:1423809646 N 141:1269256192:581115123", "59:27181636:1423809646 N 143:1880786106:1651632213" }, "เหลือเชื่อ! ไม่น่าเป็นไปได้! น่าทึ่งจริง ๆ! เจ้ามีพรสวรรค์ {name} ไม่อย่างนั้นก็โชคดีที่สุดในบรรดาคนมีชีวิต!\n\nนี่ส่วนแบ่งเจ้า แน่ใจว่าใช้ของพวกนี้ได้ดีกว่าข้า" },
        required = { [7968] = { "17:105978040:986929725", "สมบัติทะเลใต้" } },
        steps = { { "17:105978040:986929725", "สมบัติทะเลใต้" } },
    },
    [2382] = { -- Wrenix of Ratchet
        title = { "17:1372875479:1496032024", "Wrenix แห่ง Ratchet" },
        objective = { "53:438979649:402967480", "เดินทางไป Ratchet แล้วคุยกับ Wrenix the Wretched" },
        description = { "158:1726296316:681582527 N 27:1556045226:201806375 N 2:8513:4355 N 88:1775284400:2137875699", "Zando'zan เห็นแล้ว! ใช่ วันนั้นจะมาถึง! ความตายของ Thrall... มีดที่หลัง พิษซึมไปทุกเส้นเลือด... Zando'zan พูดมากไปแล้ว\n\n{name}! Zando'zan มีงานให้ {name}! {name} ต้องไป Ratchet ทางตะวันออกของ Crossroads แล้วคุยกับ Wrenix the Wretched ไป!" },
        completion = { "116:1350214656:1591637930", "อีกคนหรือ? ห้าคนล่าสุดที่โทรลล์บ้าส่งมากลายเป็นอาหารฉลาม หวังว่าเจ้าจะดีกว่าหน่อยนะ?" },
    },
    [2458] = { -- Deep Cover
        title = { "10:1572745009:538981897", "แฝงตัวลึก" },
        objective = { "433:231748881:1247478502", "ไป Venture Co. Tower ทางเหนือของ Sludge Fen ติดต่อสายลับ Shattered Hand ชื่อ Taskmaster Fizzule\n\nเมื่อมองเห็นหอคอย ใช้ Flare Gun ส่งสัญญาณถึง Taskmaster Fizzule ยิงพลุสองครั้ง แล้วเข้าหา Taskmaster Fizzule ทำ Shattered /Salute\n\nต้องทำตามลำดับให้ถูก เพราะ Fizzule จะโจมตีและสังหารทุกคนที่จำไม่ได้" },
        description = { "495:1421649876:1403961378", "Venture Company... คงเคยได้ยินสินะ?\n\nเราทำงานหนึ่งปีเพื่อฝังสายลับลึกในกลุ่ม ด้วยความพยายามและแผนรอบคอบ เราทำสำเร็จ\n\nไม่นานนี้มีข่าวว่า Venture Co. วางแผนเรื่องใหญ่ ไปเหนือ Sludge Fen ถึงหอคอย Venture Co. ติดต่อ Taskmaster Fizzule สายลับแฝงตัวของเรา\n\nเมื่อพบหอคอย ใช้ปืนพลุนี้ จากนั้นเข้าหา Fizzule แล้วทำความเคารพแบบ Shattered Hand ให้ดู" },
        completion = { "217:1355621238:1866923871", "ดีที่เห็นสายปฏิบัติการ Shattered Hand อีกคนแถวนี้ แต่พลุอาจมากไปหน่อย!\n\nครั้งหน้าที่ต้องคุยกับข้า เป่านกหวีดนี้สองครั้ง แล้วจะรู้ว่าเป็นพันธมิตร" },
    },
    [2460] = { -- The Shattered Salute
        title = { "20:247450205:1357334650", "การทำความเคารพแบบ Shattered" },
        objective = { "41:1292010241:698436695", "ทำ Shattered Salute ต่อ Shenthul" },
        description = { "174:960978076:20858472", "ในฐานะโร้ก Shattered Hand เจ้าจำเป็นต้องเรียน Shattered Salute เป็นทางเดียวที่จะยืนยันสมาชิก Hand อีกคนได้จริง\n\nดู เรียนรู้ แล้วทำตาม" },
        progress = { "9:1573154565:838992544", "ฝึกเข้า!" },
        completion = { "11:534428891:784080240 N 31:1432143695:1358041831", "ทำดีมาก {name} ตอนนี้พร้อมเดินหน้าต่อแล้ว" },
        objectiveLabels = {
            event = { ["Shattered Salute Performed"] = "ทำท่าคำนับ Shattered Salute แล้ว" },
        },
    },
    [2478] = { -- Mission: Possible But Not Probable
        title = { "34:1043231105:1605204175", "ภารกิจ: เป็นไปได้แต่โอกาสน้อย" },
        objective = { "381:828217549:723111445", "ขโมย Silixiz's Tower Key จาก Foreman Silixiz แล้วฆ่า Mutated Venture Co. Drones สองตัว, Venture Co. Patrollers สองตัว และ Venture Co. Lookouts สองตัว\n\nลอบสังหาร Grand Foreman Gallywix เอาหัวมา จากนั้นสะเดาะ Gallywix's Lockbox แล้วขโมย Cache of Zanzil's Altered Mixture นำ Cache พร้อม Gallywix's Head กลับไปให้ Shenthul ใน Orgrimmar เพื่อรับคำสั่งต่อ" },
        description = { "59:1705645722:1301877133 N 442:1041088871:341840347", "เจ้าต้องขโมยกุญแจหอคอยจาก Foreman Silixiz {name} เมื่อได้แล้วเก็บไว้ ข้าอาจต้องใช้ภายหลัง\n\nจำไว้ว่าพิษทำให้ทุกสิ่งในหอคอยอ่อนแอ ใช้ความสามารถก่อความวุ่นวายและทำลายผู้อาศัย ฆ่าทั้งหมด อย่าปรานี!\n\nเมื่อทุกสิ่งข้างในกองจมเลือดแล้ว สะเดาะหีบ Gallywix ขโมยส่วนผสม Zanzil ที่เก็บไว้ นำทั้งหัว Gallywix กับส่วนผสมไปให้ Shenthul ใน Orgrimmar" },
        progress = { "25:1198726147:94034482 N 1:63:63", "มีอะไรมารายงาน {name}?" },
        completion = { "84:1961096025:1665025163 N 98:1173016287:1446054519 C 60:684432673:147507884", "Fizzule ผู้น่าสงสาร เขาเป็นสายลับที่ดี หนึ่งในคนดีที่สุด แต่นี่คือราคาที่จ่าย {name} สายลับภาคสนาม Shattered Hand เป็นงานอันตราย\n\nเจ้าทำหน้าที่ได้ดี {class} คงน่าเสียดายหากไม่รอดมารับใช้เราอีก" },
        required = { [8074] = { "15:253620203:1361292119", "ศีรษะของ Gallywix" }, [8072] = { "19:1606699290:913924129", "กุญแจหอคอยของ Silixiz" }, [8073] = { "33:127002679:1180310843", "หีบเก็บสารผสมดัดแปลงของ Zanzil" } },
        steps = { { "15:253620203:1361292119", "ศีรษะของ Gallywix" }, { "19:1606699290:913924129", "กุญแจหอคอยของ Silixiz" }, { "33:127002679:1180310843", "หีบเก็บสารผสมดัดแปลงของ Zanzil" } },
        objectiveLabels = {
            monster = { ["Mutated Venture Co. Drone slain"] = "ปราบ คนงานกลายพันธุ์ของ Venture Co.", ["Venture Co. Lookout slain"] = "ปราบ ยามเฝ้าระวังของ Venture Co.", ["Venture Co. Patroller slain"] = "ปราบ ยามลาดตระเวนของ Venture Co." },
        },
    },
    [2479] = { -- Hinott's Assistance
        title = { "19:378377237:398813007", "ความช่วยเหลือของ Hinott" },
        objective = { "248:1048758457:840144372", "เดินทางไป Tarren Mill ใน Hillsbrad Foothills นำ Sample of Zanzil's Mixture ไปให้ Serge Hinott\n\nไป Tarren Mill โดยขึ้นเรือเหาะสู่ Undercity แล้วตามถนนใต้ผ่าน Silverpine ไปทาง Hillsbrad ตามป้ายบอกทาง!" },
        description = { "174:22316270:1407797499", "นำตัวอย่างส่วนผสมให้ Serge Hinott ใน Tarren Mill\n\nหากมีใครรักษาได้ก็คือ Serge รอดให้นานพอ แล้วเขาจะแสดงวิธีสร้างและใช้พิษให้ดู" },
        progress = { "14:66569018:953092233", "นี่อะไร???" },
        completion = { "27:1654269901:1192470834 C 62:1836901324:1067450412", "เจ้าซีดน่าลิ้มลองจริง {class} กลิ่นเหม็นที่โชยมาจากเจ้าคืออะไร? ข้าต้องรู้!" },
        required = { [8087] = { "34:402655005:1151430316", "ตัวอย่างสารผสมดัดแปลงของ Zanzil" } },
        steps = { { "34:402655005:1151430316", "ตัวอย่างสารผสมดัดแปลงของ Zanzil" } },
    },
    [2480] = { -- Hinott's Assistance
        title = { "19:378377237:398813007", "ความช่วยเหลือของ Hinott" },
        objective = { "43:566003558:1621543184", "รอ Serge Hinott ทำยารักษาให้เสร็จ" },
        description = { "278:235234764:823857601 N 1:46:46", "ข้าไม่เคยเห็นผลพิษมหัศจรรย์เช่นนี้! Zanzil หรือ? ไม่เคยได้ยิน แต่ต้องชมที่สร้างส่วนผสมนี้\n\nข้าต้องรักษาเจ้า แล้วสอนใช้พิษนี้สินะ?\n\nขอเวลาตรวจพิษสักครู่ {name}" },
        completion = { "136:1527480568:1970252708", "ยารักษาพร้อม! ดื่มยาต้านพิษนี้แล้วความบ้าที่คืบคลานจะหยุด แต่เรื่องกลิ่นข้าช่วยไม่ได้" },
        objectiveLabels = {
            event = { ["Cure Completed"] = "ปรุงยารักษาเสร็จแล้ว" },
        },
    },
    [2607] = { -- The Touch of Zanzil
        title = { "19:2020905694:1910665842", "สัมผัสแห่ง Zanzil" },
        objective = { "56:158365176:1828897852", "คุยกับ Doc Mixilpixil ที่ห้องใต้ดินของ Barracks" },
        description = { "120:17767946:1281692220 N 94:2044709372:1048864451", "ดูเหมือนเจ้านำข้อมูลกลับมามากกว่าที่ข้าคาดเสียอีก เหตุการณ์พลิกผันแปลกจริง {name}\n\nยารักษาหรือ? หืม... ลงห้องใต้ดินคุยกับ Doc Mixilpixil เขาอาจช่วยได้" },
        completion = { "101:1533219391:430472422", "มาเสียที! วางชีสบนโต๊ะแล้วรีบไป Osborne จะจ่ายเงินตอนออก" },
    },
    [2608] = { -- The Touch of Zanzil
        title = { "19:2020905694:1910665842", "สัมผัสแห่ง Zanzil" },
        objective = { "96:1403374948:660927800", "ใช้ /Lay นอนลงให้ Doc Mixilpixil ตรวจ จะหายารักษาได้อย่างไรหากไม่รู้สาเหตุ?" },
        description = { { "383:730623919:225487644 N 1:46:46", "384:1842695172:1739152675 N 1:46:46" }, "โอ้ ดูเหมือนความตายเลย แก้ก่อน ข้าเคยเห็นความตาย เจ้าแย่ยิ่งกว่า เหมือนสิ่งที่ความตายไอออกมาตอนตรวจร่างกายครั้งล่าสุด\n\nฮ่า! ได้ยินไหม Noarm? จดมุกนี้ไว้!\n\n*ไอ* อืม ใช่ จะช่วยได้ก็ต้องเจาะเลือด ไม่ต้องห่วง เจ็บแค่สองสาม... สักห้าสิบครั้งแรก... ใช้ /lay นอนลงเมื่อพร้อมรักษา {name}" },
        progress = { "93:1099128348:1522955937", "พร้อมตรวจเมื่อใด ใช้ /lay นอนบนพื้น แล้วข้าจะเริ่มเจาะเลือด" },
        completion = { "47:1094206457:1926322366 N 47:517686849:135415968", "ขอเวลาปรึกษาเพื่อนร่วมงาน {name} Dr. Montgomery, Mr. Noarm มาประชุมกัน!" },
        objectiveLabels = {
            event = { ["Diagnosis Complete"] = "ตรวจวินิจฉัยเสร็จแล้ว" },
        },
    },
    [2609] = { -- The Touch of Zanzil
        title = { "19:2020905694:1910665842", "สัมผัสแห่ง Zanzil" },
        objective = { "187:1128388609:215818123", "นำ Simple Wildflowers หนึ่งช่อ, Leaded Vial หนึ่งขวด, Bronze Tube หนึ่งท่อ และ Spool of Light Chartreuse Silk Thread หนึ่งหลอดไปให้ Doc Mixilpixil โรค 'itis' ไม่หายเองหรอก เด็กเอ๋ย", variants = { { { "180:1345705137:1665574656", "179:684426042:1770585836" }, "นำ Simple Wildflowers หนึ่งช่อ, Leaded Vial หนึ่งขวด, Bronze Tube หนึ่งท่อ และ Spool of Light Chartreuse Silk Thread หนึ่งหลอดไปให้ Doc Mixilpixil โรค 'itis' ไม่หายเองหรอก เด็กเอ๋ย" } } },
        description = { "16:972039198:23026146 N 345:1928433470:911518396 N 119:230550201:582519532", "เป็นเอกฉันท์ {name} เจ้าเป็นโรค 'itis'\n\nโชคดี ข้ามียารักษา 'itis'\n\nต้องการสิ่งต่อไปนี้ ดอกไม้ป่าธรรมดาหนึ่งช่อ ขวดแก้วตะกั่วหนึ่งขวด ท่อสำริดหนึ่งท่อ และสุดท้ายที่สำคัญไม่แพ้กัน ด้ายไหมสีเขียวชาร์เทริซอ่อนหนึ่งหลอด Ol' Emma ทิ้งด้ายให้ข้าที่ 'The Finest Thread' ร้านอยู่ตามคลอง\n\nรีบไป {name} พยายามอย่าแตะใครจนกว่าจะหาย อ้อ Dr. Montgomery บอกว่าต้องอาบน้ำ คำเขานะ ไม่ใช่ข้า" },
        progress = { "76:738159097:600323092 N 38:676428399:1202467786", "หากอยากรักษา 'itis' ต้องพยายามกว่านี้ {name} วัตถุดิบทำยาอยู่ไหน?" },
        completion = { "121:1895632975:1015941654 N 124:1942518316:434511043", "ข้าทำอะไรหรือ? ดูเหมือนทำอะไรล่ะ? ข้ากำลังคิดยารักษา 'itis' ของเจ้า! อย่ามาไม่พอใจข้า {name}!\n\nอีกไม่กี่วินาที นี่ไง! แค่ฉีดยาที่ เอ่อ กลิ่นมหัศจรรย์นี่ใส่ตัว แล้วจะดีเหมือนใหม่" },
        required = { [3421] = { "18:1698378117:1743313154", "ดอกไม้ป่าธรรมดา" }, [3372] = { "11:1633400656:1678275684", "ขวดแก้วผสมตะกั่ว" }, [4371] = { "11:1255316179:1794554443", "ท่อสำริด" }, [8431] = { "37:2109006052:1699022980", "ด้ายไหมสีเขียวอมเหลืองอ่อนหนึ่งหลอด" } },
        steps = { { "18:1698378117:1743313154", "ดอกไม้ป่าธรรมดา" }, { "11:1633400656:1678275684", "ขวดแก้วผสมตะกั่ว" }, { "11:1255316179:1794554443", "ท่อสำริด" }, { "37:2109006052:1699022980", "ด้ายไหมสีเขียวอมเหลืองอ่อนหนึ่งหลอด" } },
    },
    [3083] = { -- Encrypted Tablet
        title = { "16:842846034:1743497513", "แผ่นจารึกเข้ารหัส" },
        objective = { "68:1076743884:1752376814", "อ่าน Encrypted Tablet แล้วคุยกับ Rwag ใน Valley of Trials" },
        description = { "47:542172104:1998871674 N 135:2041138337:1722011723", "อา ระหว่างเจ้าไม่อยู่ มีแผ่นจารึกมาถึง {name}\n\nมีเวลาค่อยอ่าน หากจำไม่ผิด มาจาก Rwag ครูฝึกโร้ก เขาอยากคุยเมื่อเจ้าพร้อม" },
        progress = { "33:1429944212:1666930278 N 395:1255461064:630018465", "ยินดีต้อนรับสู่ Valley of Trials {name} หากไม่ได้แผ่นจารึกคงไม่มาที่นี่ ข้าจะเข้าเรื่องเลย\n\nข้าชื่อ Rwag รับผิดชอบฝึกโร้ก โจร และนักล้วงกระเป๋าใน Valley หากเจ้ายังไม่พร้อมกับสิ่งข้างหน้า Hand จะมาหาข้า แต่ไม่ต้องห่วง Hand ไม่ได้ควบคุมทุกอย่างที่ทำ ถึงอย่างนั้นก็ควรร่วมมือหากพวกเขาต้องใช้พรสวรรค์เจ้า" },
        completion = { "322:739372833:626184293", "จนกว่าจะถึงเวลานั้น เจ้าจะเป็นศิษย์ข้า ข้าจะสอนพื้นฐานอย่างที่บางคนเรียก เมื่อรู้สึกพร้อมก็มาหา จะดูว่าฝึกเพิ่มเติมได้ไหม ระหว่างนี้ฝึกฝีมือให้คมดั่งมีดโกน ไม่มีทางรู้ว่าจะต้องใช้แม้ความสามารถเล็กน้อยที่สุดเมื่อใด" },
        required = { [9554] = { "16:842846034:1743497513", "แผ่นจารึกเข้ารหัส" } },
        steps = { { "16:842846034:1743497513", "แผ่นจารึกเข้ารหัส" } },
    },
    [3088] = { -- Encrypted Parchment
        title = { "19:1942920732:1396510836", "แผ่นหนังเข้ารหัส" },
        objective = { "71:929315047:1105996406", "อ่าน Encrypted Parchment แล้วคุยกับ Rwag ใน Valley of Trials" },
        description = { "50:504738005:547472890 N 135:2041138337:1722011723", "อา ระหว่างเจ้าไม่อยู่ มีแผ่นหนังมาถึง {name}\n\nมีเวลาค่อยอ่าน หากจำไม่ผิด มาจาก Rwag ครูฝึกโร้ก เขาอยากคุยเมื่อเจ้าพร้อม" },
        progress = { "181:164325103:182886173", "ชู่ว์ อย่าดัง ข้าไม่ไว้ใจ Nartok ตรงนั้น ใครที่ต้องซ่อนลึกในถ้ำกว่าข้า ไม่ควรไปยุ่งด้วย\n\nคงหาทางแถวนี้ไม่ลำบากสินะ?" },
        completion = { "416:609458148:643437368", "เมื่อรู้ว่าข้าพักอยู่ไหน ก็ควรบอกว่า Shattered Hand ขอให้ข้าดูแลเจ้า อยากให้ฝึกและแจ้งข่าวสิ่งที่พวกเขาอาจต้องการ แม้ยังไม่สนช่วย ซึ่งคงโง่หากไม่สน ข้าก็จะฝึกเท่าที่ทำได้... ด้วยค่าฝึกเล็กน้อย กลับมาเมื่อคิดว่าพร้อม แล้วจะดูว่าพร้อมเรียนอะไร" },
        required = { [9560] = { "19:1942920732:1396510836", "แผ่นหนังเข้ารหัส" } },
        steps = { { "19:1942920732:1396510836", "แผ่นหนังเข้ารหัส" } },
    },
    [3096] = { -- Encrypted Scroll
        title = { "16:1081216351:296251245", "ม้วนคัมภีร์เข้ารหัส" },
        objective = { "65:1537821236:2071415859", "อ่าน Encrypted Scroll แล้วคุยกับ David Trias ใน Deathknell" },
        description = { "255:1968343234:174393122", "อา ระหว่างเจ้าจัดการ Scourge ไร้สติ ม้วนคัมภีร์นี้มาถึง ข้าว่าน่าจะเป็นเรื่องสำคัญ เพราะดูเหมือนมีตรา David Trias ครูฝึกโร้ก ข้าคงหาเวลาอ่านก่อนออกไปอีกครั้ง" },
        progress = { "272:1632222262:800045053", "มาถึงแล้วหรือ? ดี เราจะต้องการโร้กเพิ่มเมื่อเวลาผ่านไป Shadowstalkers คงมาหาเมื่อเห็นว่าถึงเวลา อย่าพลาดหรือทำสิ่งที่อาจเสียใจ พวกเขาต้องการสายลับมีพรสวรรค์... ไม่ใช่นักล้วงกระเป๋ากับคนโง่" },
        completion = { "287:926484221:583423109", "ข้าใช้เวลาส่วนใหญ่ในโรงเตี๊ยม คอยดูหน้าใหม่และจับตาผู้มีแวว ทำตัวให้เรียบร้อย แล้วข้าจะสอนให้เท่าที่ทำได้ กลับมาเมื่อใดก็ได้ แล้วจะดูว่าพร้อมเรียนทักษะใหม่สักอย่างสองอย่างไหม" },
        required = { [9559] = { "16:1081216351:296251245", "ม้วนคัมภีร์เข้ารหัส" } },
        steps = { { "16:1081216351:296251245", "ม้วนคัมภีร์เข้ารหัส" } },
    },
    [3118] = { -- Encrypted Sigil
        title = { "15:506412984:1507323885", "ตราเข้ารหัส" },
        objective = { "72:1855531788:1579395404", "อ่าน Encrypted Sigil แล้วคุยกับ Frahun Shadewhisper ใน Shadowglen" },
        description = { "179:1106477828:160448249", "ผู้ส่งสารจาก Frahun ครูฝึกโร้กของเรามอบตรานี้ให้ข้า ดูเหมือนเขาอยากคุยเมื่อเจ้ามีเวลา อ่านแล้วนำไปให้ด้วย" },
        progress = { "7:989913233:66981971 N 272:1328695610:228095273", "สวัสดี {name} ยินดีที่หาข้าพบ นึกว่าอาจหลงระหว่างทาง\n\nไม่มีอะไรใหม่ใน Shadowglen นับแต่ส่งตราไป แต่เรื่องรวบรวมข้อมูลข้าจะให้เจ้าทำเอง อยากคุยกับผู้คนรอบ Aldrassil ก็ตามสบาย" },
        completion = { "441:1012207543:1136304053", "ระหว่างนี้จงรู้ว่าเราจำเป็นกว่าที่เคยในยามเปราะบาง สันติภาพกับเผ่าอื่นอาจล้มได้ทุกเมื่อ และมีข่าวมากว่าสมาชิก Horde อยากหว่านความไม่ไว้ใจให้เพิ่มขึ้น จำไว้\n\nเมื่อแข็งแกร่งและรู้สึกพร้อมขึ้น กลับมาหาข้าที่นี่ จะดูเรื่องฝึกให้ สิ่งสำคัญอย่างหนึ่งคือรู้วิธีใช้อาวุธที่เลือก" },
        required = { [9551] = { "15:506412984:1507323885", "ตราเข้ารหัส" } },
        steps = { { "15:506412984:1507323885", "ตราเข้ารหัส" } },
    },
    [6681] = { -- The Manor, Ravenholdt
        title = { "21:2134951102:1299982371", "คฤหาสน์ Ravenholdt" },
        objective = { "153:2146053623:2033425311", "นำ Seal of Ravenholdt ไปให้ Fahrad ที่ Ravenholdt Manor ซึ่งซ่อนในเนินเขาของ Hillsbrad\n\nไหวพริบเจ้าจะถูกทดสอบระหว่างทาง เตรียมพร้อม" },
        description = { "N 467:583042692:105055540", "{name}\n\nRavenholdt สนใจเจ้า โจรรุ่นเยาว์ เราเฝ้าดูอยู่ ท่วงท่ายังเก้งก้างบ้าง แต่ไม่มีอะไรที่แก้ไม่ได้\n\nหากพร้อมเริ่มชีวิตศิษย์ Master Ravenholdt และสมาชิก Assassin's League เพียงนำ Seal of Ravenholdt ที่แนบกับจดหมายนี้มายัง Ravenholdt Manor\n\nงานแรกคือหาคฤหาสน์ที่ซ่อนในเนินเขาของ Hillsbrad และแสดงไหวพริบ\n\nด้วยความปรารถนาดี\n\nFahrad" },
        progress = { "37:1696191267:1641629220", "พบ Milton หรือยัง?\n\n<Fahrad หัวเราะ>" },
        completion = { "271:1787341230:197881349", "ยอดเยี่ยมมาก โจรรุ่นเยาว์\n\nดูสะบักสะบอมหน่อย แต่ก็ไม่ได้เสียหายนัก\n\nการเดินทางยาวนานรออยู่ ยาวนานและคุ้มค่า พร้อมรับชะตาในหมู่ปรมาจารย์ Ravenholdt แล้วหรือ?\n\nคุยกับยามด้านนอก พวกเขาจะให้เริ่มงาน" },
        required = { [17125] = { "18:2028434491:1777067046", "ตราประทับ Ravenholdt" } },
        steps = { { "15:500824795:251792091", "พิธีทดสอบไหวพริบ" }, { "18:2028434491:1777067046", "ตราประทับ Ravenholdt" } },
    },
    [6701] = { -- Syndicate Emblems
        title = { "17:1703187345:762969028", "ตรา Syndicate" },
        progress = { "485:1546915459:546484498", "เรารบกับ Syndicate มาหลายปี สิ่งที่ขาดด้านฝีมือ พวกมันชดเชยด้วยจำนวน ฆ่าไม่ทันจนจะลดประชากรได้เห็นผล!\n\nพบว่าวิธีรับมือจำนวนได้ดีที่สุดคือขโมยตรา เมื่อถูกขโมย สมาชิกผู้อับอายจะถูก 'จัดการ' ภายใน\n\nล้วงกระเป๋าให้เกลี้ยงแล้วส่งตราให้ข้าหรือยามคนอื่น\n\nเริ่มที่ Durnholde ทางใต้จากที่นี่" },
        completion = { "77:224962023:1355590641", "เฮ้ ทำดีมาก! ทำต่อไป โร้กคนอื่นอาจเลิกถ่มน้ำลายใส่เจ้า" },
        description = { "485:1546915459:546484498", "เรารบกับ Syndicate มาหลายปี สิ่งที่ขาดด้านฝีมือ พวกมันชดเชยด้วยจำนวน ฆ่าไม่ทันจนจะลดประชากรได้เห็นผล!\n\nพบว่าวิธีรับมือจำนวนได้ดีที่สุดคือขโมยตรา เมื่อถูกขโมย สมาชิกผู้อับอายจะถูก 'จัดการ' ภายใน\n\nล้วงกระเป๋าให้เกลี้ยงแล้วส่งตราให้ข้าหรือยามคนอื่น\n\nเริ่มที่ Durnholde ทางใต้จากที่นี่" },
        required = { [17124] = { "16:716884425:268112267", "ตราสัญลักษณ์ซินดิเคต" } },
        objectiveLabels = {
            item = { ["Syndicate Emblem"] = "ตราสัญลักษณ์ซินดิเคต" },
        },
    },
    [8233] = { -- A Simple Request
        title = { "16:1592233595:1315807642", "คำขอเรียบง่าย" },
        objective = { "54:674256515:999777288", "คุยกับ Lord Jorach Ravenholdt ใน Ravenholdt Manor" },
        description = { "219:1652659307:1959309370", "Lord Jorach Ravenholdt ขอพบเจ้า เรื่องนี้เป็นความลับ ข้าบอกเพิ่มไม่ได้\n\nRavenholdt Manor อยู่ Hillsbrad Foothills มองหาทางในภูเขาทางตะวันตกเฉียงเหนือของ Durnhold Keep" },
        completion = { "35:140310203:2059482199 N 60:1758623438:54003112 N 199:911587972:761377205 N 34:1464428223:1195736927", "ยินดีต้อนรับ ยินดี ยินดี! โปรดนั่งลงคุยเรื่องง่าย ๆ กับข้า {name}\n\nคืออย่างนี้ {name} ข้าเพิ่งเสียของรักไป พูดตรง ๆ อยากได้คืนไม่ว่าต้องแลกอะไร เจ้าจะได้ตอบแทนด้วย ไม่ต้องห่วง! ใช่ ของดีมาก\n\nว่าอย่างไร {name}... พร้อมผจญภัยไหม?" },
    },
    [8234] = { -- Sealed Azure Bag
        title = { "16:1967449022:1113194131", "ถุงสีฟ้าผนึกไว้" },
        objective = { "127:1748944248:1800082869", "นำ Sealed Azure Bag กลับมาจาก Timbermaw Shaman ใน Azshara แล้วนำถุงไปให้ Archmage Xylem ซึ่งอยู่ใน Azshara เช่นกัน" },
        description = { "483:305590631:1018629015", "เริ่มเรื่องแรกก่อน ของที่เสียไปคือถุงสีฟ้าเล็ก ๆ ข้างในเป็นเรื่องส่วนตัว\n\nไม่ต้องตามโจร เพราะตายแล้ว เรารู้ว่าพวกโง่เปิดถุงไม่ได้ จึงขายให้ชามัน Timbermaw ใน Azshara ในฐานะวัตถุศักดิ์สิทธิ์ ฉลาดดี\n\nข้าต้องให้เจ้าไป Azshara นำถุงกลับจากชามันด้วยวิธีแนบเนียน... หรือกำลัง ข้าว่าวิธีแรกมีโอกาสดีกว่า เมื่อได้แล้วนำให้ Archmage Xylem" },
        progress = { "14:2097511699:840677519", "ข้ารู้จักเจ้าหรือ?" },
        completion = { { "65:1642722396:1885204988", "66:1508078222:1460132983" }, "เห็นว่ามีถุง Lord Ravenholdt ทำไมไม่บอกก่อน เด็กเอ๋ย?" },
        required = { [19775] = { "16:1967449022:1113194131", "ถุงสีฟ้าที่ปิดผนึก" } },
        objectiveLabels = {
            item = { ["Sealed Azure Bag"] = "ถุงสีฟ้าที่ปิดผนึก" },
        },
    },
    [8235] = { -- Encoded Fragments
        title = { "17:77488298:596466529", "ชิ้นส่วนเข้ารหัส" },
        objective = { "56:1032449253:1998326390", "นำ Encoded Fragments 10 ชิ้นไปให้ Archmage Xylem ใน Azshara" },
        description = { "486:1763899372:1847251865", "Lord Ravenholdt ขอให้เราทั้งสองช่วย อยากถอนมนตร์จากถุงนี้\n\nน่าเสียดาย หนังสือข้าบางเล่มเรื่องลบมนตร์ถูกเอาไปไม่นาน แล้วถูกคนป่าเถื่อนทำลาย เศษหนังสือยังมีค่า\n\nหากนำชิ้นส่วนเข้ารหัสมาให้พอ ข้าจะต่อกลับได้ โอกาสดีที่สุดคือฆ่า Forest Ooze เพราะชอบเก็บแทบทุกอย่าง พบได้ทางตะวันออกเฉียงเหนือของ Azshara" },
        progress = { "52:580384661:1437747643", "พบชิ้นส่วนพอให้งานข้าดำเนินต่อหรือยัง?" },
        completion = { "97:1711570349:61491483", "ดูเหมือนเลือกชิ้นส่วนที่ดีกว่ามา บางทีเจ้าอาจไม่ไร้ค่าซะทีเดียว" },
        required = { [20023] = { "16:1888750165:725845390", "ชิ้นส่วนรหัสลับ" } },
        objectiveLabels = {
            item = { ["Encoded Fragment"] = "ชิ้นส่วนรหัสลับ" },
        },
    },
    [8236] = { -- The Azure Key
        title = { "13:777376678:1779301603", "กุญแจสีฟ้า" },
        objective = { "47:1563407353:1769798164", "นำ Azure Key กลับไปให้ Lord Jorach Ravenholdt" },
        description = { "450:533278031:2038232709", "ต้องใช้เวลาถอดรหัสชิ้นส่วนและถอนมนตร์ เมื่อเสร็จข้าจะส่งถุงให้ Lord Ravenholdt ด้วยตนเอง\n\nยังมีกุญแจที่ว่ากันว่าอยู่กับเดรกเขียวชื่อ Morphaz มันอาศัยลึกใน Temple of Atal'Hakkar ซึ่งทางเข้าอยู่ Swamp of Sorrows\n\nรวมเพื่อนเข้ารังมัน Lord Ravenholdt จะรอเจ้ากลับมาพร้อมกุญแจ" },
        progress = { "72:2049700176:764954179", "ถุงมาจาก Archmage Xylem แล้ว พบกุญแจหรือยัง?" },
        completion = { "175:1790683874:948479064 N 126:1691634694:1653068898", "กุญแจ! ข้านึกว่าสูญไปตลอดกาลแล้ว โปรดเลือกอาภรณ์ลงมนตร์จากคลัง มันสงวนไว้สำหรับโร้กที่ฝีมือและความภักดีโดดเด่น จงให้รู้กันว่าไม่ควรล้อเล่นกับ {name}!\n\n<Jorach เปิดถุง แสงทองจากข้างในอาบตัวเขา ดวงตาเบิกกว้างและจ้องมอง...>" },
        required = { [20022] = { "9:1804105110:328039011", "กุญแจสีฟ้า" } },
        objectiveLabels = {
            item = { ["Azure Key"] = "กุญแจสีฟ้า" },
        },
    },
    [8249] = { -- Junkboxes Needed
        title = { "16:1184089809:1551674541", "ต้องการกล่องของจุกจิก" },
        progress = { "434:1451788245:603420351", "โร้กข้าต้องฝึกสะเดาะกุญแจ ต้องมีกุญแจยากพอ ของที่ Zan ทำเหมาะแค่มือใหม่ต่ำสุด\n\nเอาอย่างนี้ นำ Heavy Junkboxes 5 กล่องมา แล้วข้าจะให้มีดขว้างชั้นยอดที่สุดที่ชาวโร้กรู้จัก\n\nปลดล็อกแล้วค้นของข้างในได้ แต่ต้องเหลือเหรียญอย่างน้อยสองสามเหรียญ... แม้แต่โร้กฝึกหัดก็ต้องมีแรงจูงใจ" },
        completion = { "60:1939213753:1811999294", "ขอให้มีดเหล่านี้ได้ที่ในหัวใจใครสักคน\n\nตามตัวอักษรเลยนะ" },
        description = { "434:1451788245:603420351", "โร้กข้าต้องฝึกสะเดาะกุญแจ ต้องมีกุญแจยากพอ ของที่ Zan ทำเหมาะแค่มือใหม่ต่ำสุด\n\nเอาอย่างนี้ นำ Heavy Junkboxes 5 กล่องมา แล้วข้าจะให้มีดขว้างชั้นยอดที่สุดที่ชาวโร้กรู้จัก\n\nปลดล็อกแล้วค้นของข้างในได้ แต่ต้องเหลือเหรียญอย่างน้อยสองสามเหรียญ... แม้แต่โร้กฝึกหัดก็ต้องมีแรงจูงใจ" },
        required = { [16885] = { "13:768452873:685389573", "กล่องของจุกจิกหนัก" } },
        objectiveLabels = {
            item = { ["Heavy Junkbox"] = "กล่องของจุกจิกหนัก" },
        },
    },
    [8811] = { -- One Commendation Signet
        title = { "23:1317548385:700566555", "ตรายกย่องหนึ่งชิ้น" },
        progress = { "473:788762751:2038876241", "สำหรับนักผจญภัยที่มีตรายกย่องเพียงชิ้นเดียว ข้าจะแลกเป็นการยอมรับเล็กน้อยจาก Darnassus\n\nโปรดจำไว้ว่าส่งครั้งละสิบชิ้นดีกว่า ความพยายามจะได้รับการยอมรับมากกว่า เราเปิดแลกทีละชิ้นเพื่อช่วยผู้มีไม่พอครบสิบ\n\nถึงอย่างนั้น หากยังอยากส่งชิ้นเดียว ข้าก็พร้อมช่วย" },
        completion = { "128:326354308:430234106 C 95:1526801603:563910160", "ดีมาก วีรกรรมถูกบันทึกแล้ว เจ้ารับการยอมรับตามความพยายาม ทำดีต่อไป {class}\n\nหากมีตราจะส่งเพิ่ม ข้าก็ช่วยได้อีก" },
        description = { "473:788762751:2038876241", "สำหรับนักผจญภัยที่มีตรายกย่องเพียงชิ้นเดียว ข้าจะแลกเป็นการยอมรับเล็กน้อยจาก Darnassus\n\nโปรดจำไว้ว่าส่งครั้งละสิบชิ้นดีกว่า ความพยายามจะได้รับการยอมรับมากกว่า เราเปิดแลกทีละชิ้นเพื่อช่วยผู้มีไม่พอครบสิบ\n\nถึงอย่างนั้น หากยังอยากส่งชิ้นเดียว ข้าก็พร้อมช่วย" },
        required = { [21436] = { "28:763609816:1802454029", "ตราเชิดชูเกียรติฝ่ายพันธมิตร" } },
        objectiveLabels = {
