    [78676] = { -- The Eye of Bhossca
        title = { "18:345092586:1214550035", "ดวงตาแห่ง Bhossca" },
        objective = { "145:1740056837:615957818", "หา Eye of Bhossca ใน Scarlet Monastery แล้วนำกลับจุดทิ้งของลับของ C ใกล้ Pyrewood Village ต้องทำงานนี้เพียงลำพัง" },
        description = { "50:480019770:1781992113 N 439:930739922:1066770633", "<มีบันทึกอยู่ในหีบ>\n\nยินดีที่กลับมา {name}\n\nสิ่งล่าสุดที่ข้าปรารถนาคือวัตถุชื่อ Eye of Bhossca สายข่าวบอกว่าดวงตาอยู่ที่ใดสักแห่งใน Scarlet Monastery เช่นเดียวกับ Shadowfang Keep เจ้าต้องแทรกซึมอารามเพียงลำพัง\n\nอาจเป็นประโยชน์หากหาชุดปลอมตัวก่อนเข้า จะช่วยเดินทางข้างในง่ายขึ้นหน่อย แน่ใจว่าหาบางอย่างได้ในบริเวณอาราม\n\nนำดวงตากลับที่นี่ แล้วจะส่งค่าจ้างเหมือนก่อน\n\n- C" },
        progress = { "24:1284825576:1651902609", "<หีบตั้งอยู่ตรงหน้า ภายในว่างเปล่า>" },
        completion = { "45:371740175:10196124", "<เจ้าวาง The Eye of Bhossca ลงในหีบ>" },
        required = { [210953] = { "14:1348007731:642824848", "ดวงตาแห่ง Bhossca" } },
        steps = { { "14:1348007731:642824848", "ดวงตาแห่ง Bhossca" } },
    },
    [78699] = { -- The Eye of Bhossca
        title = { "18:345092586:1214550035", "ดวงตาแห่ง Bhossca" },
        completion = { "31:1863555910:1779561947 N 43:1604582188:390300661", "<มีกระดาษโน้ตวางอยู่ในหีบ>\n\nถึง {name} ข้าจะคอย «จับตา» ดูเจ้าไว้\n- C" },
    },
