        title = { "22:608653107:184918144", "คุ้นเคยกับเงามืด" },
        objective = { "92:517889533:756589628", "อ่าน Simple Note แล้วคุยกับ Akeri Duskblade ในหอคอยยามของ Thendal Grove" },
        description = { "312:1535203101:1129852940", "ระหว่างเจ้าจัดการปัญหา Vuldren ครูฝึกโร้กประจำถิ่น Akeri Duskblade ขอคุยด้วย เขาฝากบันทึกนี้ไว้ อ่านก่อนแล้วไปหาในหอคอยยามของหมู่บ้าน\n\nเขาเป็นคนน่าสงสัย แต่เจ้าก็เหมือนกัน ข้าว่าจะเข้ากันดี" },
        completion = { "433:565572074:1137057595", "ข้าแทบไม่ได้ยินเจ้ามา โร้กรุ่นเยาว์\n\nแทบ\n\nแค่แทบไม่พอเมื่อออก Thendal Grove เจ้าต้องเป็นดาบเพรียว เงียบและมั่นคง ตื่นตัวและใส่ใจรอบข้างเสมอ อาจมีคุณสมบัติพอรอดภัย Zephras หรืออาจจบด้วยถูกเชือดคอในคู ทั้งหมดขึ้นกับเจ้าเอง\n\nคุยอีกครั้งหากอยากก้าวต่อ" },
        progress = { "30:1171943518:720709958", "<Akeri มองเจ้าอย่างระแวง>" },
        required = { [282422] = { "11:1769838965:922420833", "บันทึกเรียบง่าย" } },
        steps = { { "11:1769838965:922420833", "บันทึกเรียบง่าย" } },
    },
    [96779] = { -- Syndicate Sabotage
        title = { "18:476779314:270578648", "บ่อนทำลาย Syndicate" },
        objective = { "112:1328250281:1774180218", "หา Lord Tomas ใน Durnholde Keep ที่ Hillsbrad Foothills แล้วฆ่าเขา จากนั้นกลับไปหา Myrokos Silentform" },
        description = { "11:328310480:1426080469 R 410:1609484131:424560114", "บางครั้ง ชาว{race} แค่กรีดถูกจุดครั้งเดียวก็ทำศัตรูล้มตาย องค์กรก็มักเช่นกัน\n\nสายลับเราระบุเป้าหมายสำคัญใน Syndicate ชายชื่อ Lord Tomas\n\nเขามีบทบาทหลักต่อการทำงานของ Durnholde Keep ใน Hillsbrad Foothills หากจะรับใช้ Ravenholdt จงไป Durnholde กำจัดเขา ยิ่งเร็วและเงียบยิ่งดี" },
        completion = { "168:695490871:1955047891 N 42:513921769:967722559", "เมื่อ Tomas ตาย Durnholde Keep จะสั่นคลอนอย่างไม่ต้องสงสัย พวกอันธพาลชั้นต่ำแบบ Syndicate มักแตกกระเจิงเมื่อไร้ผู้นำ\n\nทำได้ดี {name} วันหน้าข้าอาจเรียกเจ้าไปทำภารกิจอีก" },
        objectiveLabels = {
            monster = { ["Lord Tomas slain"] = "ปราบ ลอร์ด Tomas" },
        },
    },
    [96781] = { -- What's the Big Idea?
        title = { "20:1213640293:344359064", "คิดทำอะไรกัน?" },
        objective = { "126:1783514929:945750722", "ขโมย Barton's Scouting Report ด้วยการล้วงกระเป๋าเขา แล้วนำรายงานไปให้ Myrokos Silentform ที่ Ravenholdt Manor" },
        description = { "502:2081964443:1998720090", "เราสังเกตเห็นหน่วยลาดตระเวน Syndicate ป้วนเปี้ยนซาก Alterac นำโดยชายชื่อ Barton\n\nชัดว่าตามหาบางอย่าง แต่ข้าไม่รู้ว่าอะไรหากไม่ได้อ่านรายงานลาดตระเวน\n\nขอให้ล้วงรายงานจากกระเป๋าแทนการฆ่า Barton ตายแล้ว Syndicate จะรู้ว่าเราจับตาอยู่ และใช้มาตรการกลบร่องรอยแน่\n\nหากจะหาเขา คงอยู่ในหมู่ Syndicate ที่ Strahnbrad" },
        completion = { "45:804966124:1959480589 N 12:1977978485:1805433266", "ดูท่าเจ้าจะมือไวเอาเรื่องนะ {name} ดีมาก" },
        progress = { "45:685454060:462073828", "ข้าสงสัยว่าพวกนั้นหาอะไรอยู่ในซากปรักหักพัง" },
        required = { [275482] = { "24:1265779847:1874452727", "รายงานการลาดตระเวนของ Barton" } },
        steps = { { "24:1265779847:1874452727", "รายงานการลาดตระเวนของ Barton" } },
    },
    [96782] = { -- Covert Extraction
        title = { "17:2087292249:1473041341", "ลอบนำออก" },
        objective = { "134:221395348:297722909", "หา Blade of House Perenolde และ Royal Aegis of Perenolde ในซาก Alterac แล้วนำไปให้ Myrokos Silentform" },
        description = { "491:452107060:1941863209", "ดูเหมือนสหาย Barton ทำให้เรื่องง่ายมาก เขาตามหาสมบัติสองชิ้นของตระกูล Perenolde ในซาก Alterac คือดาบ Blade of House Perenolde กับโล่ Royal Aegis of Perenolde\n\nจากรายงาน อาวุธเหล่านี้อยู่ในหอคอยสองแห่งท่ามกลางซากเมือง เราควรได้มาก่อน Syndicate\n\nโอเกอร์ที่ยึดซากดุร้าย แต่ข้าไว้ใจว่าเจ้าลอบผ่านได้โดยไม่ต้องให้คมดาบเปื้อนเลือดเลย" },
        completion = { "115:1313114022:675177002 N 12:1153558778:309430962", "เยี่ยม ข้าจะเก็บของพวกนี้ไว้ให้ปลอดภัยก่อน ระหว่างคิดว่าจะจัดการอย่างไรต่อ\n\nเจ้าไปได้แล้ว {name} ทำได้ดี" },
        progress = { "90:323619174:363465505", "เราน่าจะได้ของตกทอดพวกนั้นมาก่อนที่ Barton จะทันสังเกตว่ารายงานของเขาหายไปเสียอีก" },
        required = { [275635] = { "24:1509526957:228502129", "ดาบประจำตระกูล Perenolde" }, [275636] = { "24:1184929552:314178357", "โล่ราชวงศ์ Perenolde" } },
        steps = { { "24:1509526957:228502129", "ดาบประจำตระกูล Perenolde" }, { "24:1184929552:314178357", "โล่ราชวงศ์ Perenolde" } },
    },
    [96783] = { -- A Way In
        title = { "8:1515103801:785920523", "ทางเข้า" },
        objective = { "77:1952311468:1018227526", "ขโมยเครื่องแบบ Syndicate จาก Northfold Manor เพื่อแทรกซึม Stromgarde Keep" },
        description = { "496:241031578:1169021502", "Stromgarde Keep คือฐานใหญ่ที่สุดแห่งหนึ่งของ Syndicate ธุรกิจสำคัญมากมายเกิดหลังกำแพง\n\nข้าได้ข่าวการซื้อขายบางอย่างระหว่างสมาชิก Syndicate ที่ใดสักแห่งใน Arathi Highlands แน่ใจว่าหารายละเอียดได้ใน Stromgarde\n\nหากจะแทรกซึมโดยไม่ชวนสงสัย ต้องปลอมตัว ลองหาชุดจาก Syndicate นอกป้อมที่ Northfold Manor" },
        completion = { "75:665189820:16978125", "<เจ้ารับเครื่องแบบมา แล้วเตรียมพร้อมสำหรับภารกิจขั้นต่อไป>" },
    },
    [96784] = { -- Master of Disguise
        title = { "18:255944466:423569701", "ยอดฝีมือปลอมตัว" },
        objective = { "114:1079344859:664129333", "ขณะปลอมตัวเป็นสมาชิก Syndicate หาคนใน Stromgarde Keep ที่รู้เรื่องการซื้อขายลับ" },
        description = { "247:1431349124:773177392", "<เจ้าทวนคำสั่ง Myrokos ให้หาข่าวการซื้อขายสำคัญของ Syndicate ใน Stromgarde Keep ชุดปลอมตัวน่าจะช่วยให้คุยกับสมาชิกได้ค่อนข้างอิสระ ต้องมีใครสักคนรู้อะไรบ้างแน่>" },
        completion = { "84:592616916:649087285", "<Anastasia หรี่ตามองอย่างระแวง>\n\n...เจ้ารู้เรื่องข้อตกลงนั่นได้อย่างไรกันแน่" },
    },
    [96785] = { -- Ain't No Telling
        title = { "16:2017877954:1851186038", "ไม่มีอะไรจะบอก" },
        objective = { "98:1514532029:1288122624", "หาบางอย่างใน Stromgarde Keep เพื่อโน้มน้าว Anastasia ให้เผยรายละเอียดการซื้อขายลับ" },
        description = { "262:1047065868:360636101", "คิดว่าตัวเองเป็นใคร? โผล่มาสอดจมูกเรื่องงานทางการ\n\nข้าไม่บอกเรื่องธุรกิจเบื้องบนกับมือใหม่โดยไม่มีเหตุผลดี หากไม่มีของสำคัญหรือมีค่าให้ ข้าก็ไม่มีอะไรจะพูด" },
        completion = { "166:1857120339:956980987", "เจ้านี่... ไปเจอนั่นที่ไหน!?\n\n<Anastasia หยุดตั้งสติครู่หนึ่ง>\n\nก็ได้ ข้าจะเล่าเรื่องข้อตกลงให้ฟัง แค่คืนของนั่นมา ถือว่าหายกัน" },
        progress = { "58:1650160737:466394631", "ข้าบอกไปแล้วว่าไม่มีอะไรให้เจ้า ทีนี้ก็ไสหัวไป!" },
        required = { [275709] = { "12:572348600:1323468233", "เงินที่ถูกขโมย" } },
        steps = { { "12:572348600:1323468233", "เงินที่ถูกขโมย" } },
    },
    [96786] = { -- The Syndicate Sting
        title = { "19:1600881041:711125135", "ปฏิบัติการล่อจับ Syndicate" },
        objective = { "132:1263054809:1670765292", "ขัดขวางการซื้อขายลับ แล้วชิงวัตถุที่กำลังขายให้ Syndicate จากนั้นกลับไปหา Myrokos Silentform ที่ Ravenholdt Manor" },
        description = { "308:934550382:440483328", "Falconcrest ส่งคนไปส่งมอบของที่ตอนใต้ของ Thoradin's Wall ไม่รู้ว่าจะรับอะไร ต้องของดี เพราะทุกคนที่เกี่ยวปิดลับสนิท ข้าว่าพวกที่ไปรับยังไม่รู้ด้วยซ้ำว่าคืออะไร\n\nรู้แค่นี้ อย่าทำให้ข้าเสียใจที่บอก" },
        completion = { "312:1160244811:1368379117", "แหม ดูท่ากว่าจะได้ของนี่มา เจ้าคงลงแรงไปไม่น้อย เล่นเกมลับลวงพรางได้ดีนี่\n\nถ้าเจ้าอยากรู้ว่าข้างในห่อมีอะไร ก็คงเข้าใจนะว่ามีแค่คนที่จำเป็นต้องรู้เท่านั้นที่จะได้รู้\n\nถึงอย่างนั้น เจ้าก็รับใช้คฤหาสน์อย่างมีเกียรติ สมควรได้รับรางวัล" },
        progress = { "4:1110228981:147916455 N 40:190224868:604394985", "อ้อ {name} เจ้ากลับมาจาก Stromgarde แล้วสินะ" },
        required = { [275882] = { "20:1650310229:1481312604", "สินค้าที่สกัดไว้" } },
        objectiveLabels = {
            item = { ["Intercepted Shipment"] = "สินค้าที่สกัดไว้" },
        },
    },
    [441] = { -- Raleigh and the Undercity
        progress = { "14:2097511699:840677519", "ข้ารู้จักเจ้าหรือ?" },
        title = { "25:537580816:205786875", "ราลีกับอันเดอร์ซิตี" },
        objective = { "31:975839047:372970119", "นำ Deliah's Ring ไปให้ Raleigh" },
        description = { "202:524908632:1001000310", "ดีไลอาห์มีสามีชื่อราลี ซึ่งตอนนี้อาศัยอยู่ในอันเดอร์ซิตี หากดีไลอาห์ที่เคยอยู่บริลล์คือเจ้าของแหวนนี้ ราลีจะรู้\n\nราลีอยู่ในย่านการค้าของอันเดอร์ซิตี" },
        completion = { "276:250990548:424013461 N 21:1122926125:392248451", "ใช่ แหวนวงนี้เป็นของภรรยาข้า นางประสบชะตาเดียวกับทุกคนที่ไม่อาจทนผ่านยุคอันโหดร้ายนี้ ข้าไม่รู้สึกอะไรต่อการตายของนาง หรือเรื่องที่เจ้าบอกว่าศพนางถูกลักไป\n\nความรู้สึกเช่นนั้นเย็นชืดไปจากข้านานแล้ว แต่ความปรารถนายังลุกไหม้อยู่ในหัวใจที่ตายแล้วของข้า {name}\n\nความปรารถนาที่จะล้างแค้น" },
        required = { [3234] = { "13:904641910:15766750", "แหวนของ Deliah" } },
        steps = { { "13:904641910:15766750", "แหวนของ Deliah" } },
    },
    [1442] = { -- Seeking the Kor Gem
        title = { "19:1122219637:258749622", "ตามหาอัญมณี Kor" },
        objective = { "52:1322737466:904014149", "นำ Kor Gem ไปให้ Thundris Windweaver ใน Darkshore" },
        description = { "11:927657569:725753248 N 484:1586854852:1103092200 C 1:46:46", "สวัสดี {name} ข้าช่วยผู้เดินทางศักดิ์สิทธิ์ได้อย่างไร?\n\nอา ใช่ Stilwell ช่างตีเหล็ก... จากนานมาแล้ว ข้าจำเขาได้ดี แม้ไม่ได้ยินชื่อนานแล้ว\n\nเขาไม่เคยดูเป็นคนอวดดี จึงคิดว่าความปรารถนาอัญมณี Kor คงมีเจตนาดี\n\nหากต้องการจริง ต้องไปตะวันตกเฉียงเหนือของ Ashenvale จะพบ Blackfathom Deeps ในซากโบราณ นากาที่ยังใช้อัญมณีอยู่ด้านล่าง อย่าไปคนเดียว {class}" },
        progress = { "222:158568436:1118455566", "ข้าคงไว้ใจน้อยกว่านี้หากผู้ไม่เดินวิถีศักดิ์สิทธิ์มาถามอัญมณี Kor แต่ข้าไว้ใจคนอย่างเจ้ามากกว่าญาติร่วมเผ่าบางคน ข้าไม่ตัดสินทั้งภาคีจากการกระทำของผู้หลงผิดเพียงคนเดียว" },
        completion = { "366:430647756:2142364792 C 37:1130099372:1976370772", "นี่คืออัญมณีที่ Stilwell ต้องการจริง แต่ก่อนให้เจ้านำไป ต้องชำระความแปดเปื้อน นางนากาใส่พลังในอัญมณีจริง แต่เป็นพลังชั่วร้ายของพวกนาง\n\nบอก Stilwell ว่าพลังยังอยู่ครบ น่าจะใช้ได้ดีกับพิธีที่เขาต้องการ\n\nหวังว่าเจ้ารู้ว่าทำอะไร {class} สิ่งที่ครอบครองไม่ธรรมดาเลย" },
        required = { [6995] = { "17:1845242218:189171043", "อัญมณี Kor ที่แปดเปื้อน" } },
        objectiveLabels = {
            item = { ["Corrupted Kor Gem"] = "อัญมณี Kor ที่แปดเปื้อน" },
        },
    },
    [1641] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        completion = { "490:1491199572:341187772", "ที่ Stormwind ข้ารับผิดชอบนำพาลาดินสู่วิถีคุณธรรมสูงขึ้น เมื่ออุทิศตนต่อแสงและป้องกัน Azeroth จาก Scourge กับภัยอื่น\n\nถึงเวลาก้าวแรกสู่ความมีคุณธรรมแท้ หากยอมรับ ข้าจะมอบ Book of Divinity การศึกษาจะสอนเรื่องแสงและสิ่งที่คาดหวังจากเจ้า หากเข้าใจและมีความสามารถ ก็จะได้พลังที่ยิ่งขึ้น" },
    },
    [1642] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "37:1332158203:474395012", "คุยกับ Duthorian Rall ใน Stormwind" },
        description = { "492:846471529:928792028", "ทุกสิ่งที่ทำ พาลาดินต้องสะท้อนแสงที่เสริมกำลังเรา การมุ่งสู่ความศักดิ์สิทธิ์ไม่ได้หมายถึงอยากเป็นเทพ แต่คือมุ่งทำดีทุกการกระทำ\n\nแม้ยุคโหดร้ายเรียกให้ปราบชั่ว ต้องจำว่าการช่วยผู้อื่นต่างหากที่ทำให้โดดเด่นจากชาว Azeroth ความเมตตา อดทน กล้าหาญ สำคัญกับพาลาดินเท่ากำลังในศึก\n\nจงรู้และอย่าลืม" },
        completion = { "13:1366380142:1891123769 N 404:2114620681:1938178759", "สวัสดีอีกครั้ง {name} ศึกษา Tome of Divinity เป็นอย่างไร?\n\nถ้าอย่างนั้นคงพร้อมรับบททดสอบ ในเมืองและดินแดนเรามีงานเสมอ ทั้งการแสดงความเมตตาและเข้าใจ ผู้คนต้องช่วย สัตว์ต้องปราบ\n\nพิสูจน์ว่าอดทนช่วยคนอื่น โดยเฉพาะผู้ด้อยโอกาส ก็พิสูจน์ว่าเป็นผู้รับใช้แสงที่มีจิตมั่นคง" },
    },
    [1643] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "60:1790654415:829384357", "ค้นหา Stephanie Turner ใน Trade District ของ Stormwind" },
        description = { "16:870719416:1339166715 N 388:317460230:1643215449", "งานเจ้าคือหาคนใน Stormwind ที่ต้องการความช่วยเหลือ {name} ผู้มีใจและเจตนาบริสุทธิ์ อาจเป็นผู้ช่วยคนอื่นหรือผู้ต้องการคนนำทาง อย่างไรก็ต้องมีเจตนาดีและอาศัยความเมตตาเจ้า\n\nทำให้สำเร็จแล้วกลับมา เราจะคุยต่อเรื่องวิถีและความหมายของการเป็นพาลาดินแห่งแสง" },
        completion = { "471:467090771:2005951588", "โอ้ สวัสดีจ้ะ ผจญภัยเป็นอย่างไร? ยินดีจริงที่ไปได้ดี\n\nข้าหรือ? ขอบใจที่ถาม เมื่อคิดถึงทุกอย่างก็นับว่าสบายดี\n\nพ่อค้าเพิ่มขึ้นทำให้คนยอมแบ่งหนังกับผ้าน้อยลง ช่วงนี้จึงทำเสื้อผ้าให้เด็กกำพร้ายากขึ้น แต่เราจะรับมือได้ หมายถึงข้ากับสามี เขาไป Ironforge ขอความช่วยเหลือจากชาวเมือง" },
    },
    [1644] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "54:411432946:1930037071", "นำ Linen Cloth 10 ชิ้นไปให้ Stephanie Turner ใน Stormwind" },
        description = { "393:1211403937:454465495 N 107:306506040:1672765346", "ขอพรคุ้มครองเด็ก ๆ ส่วนใหญ่ไม่มีครอบครัวเพราะ Scourge โจมตีในสิบปีที่ผ่านมา\n\nJohn สามีข้ารวบรวมวัสดุให้ทำเสื้อกางเกง แต่ข้ายังไม่มีเวลาทำ มัวใส่ใจให้เด็กมีอาหารและหลังคาคุ้มศีรษะ\n\nว่าอย่างไรนะ? ยอมช่วยหรือ? โอ้ ขอบคุณแสง และขอบใจ {name}\n\nหากนำผ้าลินินมาให้เย็บเสื้อเด็กได้ จะช่วยมากจริง ๆ" },
        progress = { "340:2053175481:1939981794", "หวังว่า John จะโชคดีกว่าที่ Ironforge เขาไม่ชอบไปเพราะต้องทิ้งข้ากับเด็กไว้ แต่รู้ว่าจำเป็น เขาใจดีมาก\n\nบางปีง่ายกว่าปีอื่น แต่ปีนี้หนักกว่ามาก ราวกับมีบางอย่างในอากาศส่งสัญญาณการเปลี่ยนแปลงใหญ่ แต่ใครจะรู้?" },
        completion = { "11:1191658970:1224418299 N 236:461630888:2020554921 N 70:1524067425:168197746", "ขอบใจ {name} ขอบใจมาก!\n\nเด็ก ๆ จะดีใจ เจ้าช่วยประหยัดเวลามาก ตอนนี้ข้าจะใส่ใจความต้องการด้านอื่นของเด็กได้ หวังว่า John จะได้กลับเร็วกว่าที่คิด\n\nขอบใจอีกครั้ง {name} ข้ารู้ว่าพึ่งน้ำใจผู้อื่นได้ ขอแสงอยู่กับเจ้า" },
        required = { [2589] = { "11:1393025601:1453557725", "ผ้าลินิน" } },
        steps = { { "11:1393025601:1453557725", "ผ้าลินิน" } },
    },
    [1645] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        completion = { "24:1541942836:1863377639 N 473:719384122:2073657864", "ยินดีที่ได้พบ {name} ข้ารับผิดชอบนำพาลาดินสู่วิถีคุณธรรมสูงขึ้น เมื่ออุทิศตนต่อแสงและป้องกัน Azeroth จาก Scourge กับภัยอื่น\n\nถึงเวลาก้าวแรกสู่ความมีคุณธรรมแท้ หากยอมรับ ข้าจะมอบ Book of Divinity การศึกษาจะสอนเรื่องแสงและสิ่งที่คาดหวังจากเจ้า หากเข้าใจและมีความสามารถ ก็จะได้พลังที่ยิ่งขึ้น" },
    },
    [1646] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "39:19873971:979803672", "คุยกับ Tiza Battleforge ใน Ironforge" },
        description = { "492:846471529:928792028", "ทุกสิ่งที่ทำ พาลาดินต้องสะท้อนแสงที่เสริมกำลังเรา การมุ่งสู่ความศักดิ์สิทธิ์ไม่ได้หมายถึงอยากเป็นเทพ แต่คือมุ่งทำดีทุกการกระทำ\n\nแม้ยุคโหดร้ายเรียกให้ปราบชั่ว ต้องจำว่าการช่วยผู้อื่นต่างหากที่ทำให้โดดเด่นจากชาว Azeroth ความเมตตา อดทน กล้าหาญ สำคัญกับพาลาดินเท่ากำลังในศึก\n\nจงรู้และอย่าลืม" },
        completion = { "14:1649650394:897424258 N 401:1737473392:1693354287", "ยินดีที่กลับมา {name} หวังว่าใช้เวลาอ่านหนังสือแล้ว?\n\nถ้าอย่างนั้นคงพร้อมรับบททดสอบ ในเมืองและดินแดนเรามีงานเสมอ ทั้งการแสดงความเมตตาและเข้าใจ ผู้คนต้องช่วย สัตว์ต้องปราบ\n\nพิสูจน์ว่าอดทนช่วยคนอื่น โดยเฉพาะผู้ด้อยโอกาส ก็พิสูจน์ว่าเป็นผู้รับใช้แสงที่มีจิตมั่นคง" },
    },
    [1647] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "51:54323515:834650107", "ค้นหา John Turner บนวงแหวนชั้นนอกของ Ironforge" },
        description = { "16:870719416:1339166715 N 481:1507568250:1375744109", "งานเจ้าคือหาคนใน Ironforge ที่ต้องการความช่วยเหลือ {name} ผู้มีใจและเจตนาบริสุทธิ์ อาจเป็นผู้ช่วยคนอื่นหรือผู้ต้องการคนนำทาง อย่างไรก็ต้องมีเจตนาดีและอาศัยความเมตตาเจ้า\n\nทำให้สำเร็จแล้วกลับมา เราจะคุยต่อเรื่องวิถีและความหมายของการเป็นพาลาดินแห่งแสง ข้าจะรอในวิหาร พาลาดินคนอื่นก็ต้องการคำชี้แนะด้วย" },
        completion = { { "309:1851852443:1634867289", "310:1268059358:916522150" }, "สถานเลี้ยงเด็กกำพร้าแห่ง STOR... โอ้ ขอโทษ ไม่ได้ตั้งใจตะโกนใส่ท่าน\n\nข้าชื่อ John Turner สบายดีไหม?\n\nดี ดี ยินดีที่ไปได้ดี ข้าทำงานมานานทั้งวันและคิดถึงภรรยามาก แต่ต้องจ่ายราคานี้เมื่อมีปากต้องเลี้ยงและหลังต้องหาเสื้อให้ใส่", variants = { { "310:73129059:486974762", "สถานเลี้ยงเด็กกำพร้าแห่ง STOR... โอ้ ขอโทษ ไม่ได้ตั้งใจตะโกนใส่คุณผู้หญิง\n\nข้าชื่อ John Turner สบายดีไหม?\n\nดี ดี ยินดีที่ไปได้ดี ข้าทำงานมานานทั้งวันและคิดถึงภรรยามาก แต่ต้องจ่ายราคานี้เมื่อมีปากต้องเลี้ยงและหลังต้องหาเสื้อให้ใส่" } } },
    },
    [1648] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "49:111527840:79211920", "นำ Linen Cloth 10 ชิ้นไปให้ John Turner ใน Ironforge" },
        description = { "479:1316672231:444570737", "ข้ากับภรรยาดูแลสถานเลี้ยงเด็กกำพร้าใน Stormwind ส่วนใหญ่เสียพ่อแม่จาก Scourge โจมตีในสิบปีที่ผ่านมา ข้ามา Ironforge ทุกเดือนหรือราวนั้น เพื่อรวบรวมเสบียงจากชาวเมืองและคุยกับกลุ่มต่าง ๆ ว่าช่วยอะไรได้\n\nเที่ยวนี้ช้าทรมานและไม่ค่อยได้ผล\n\nหากได้ลินินเพิ่มให้ภรรยาทำเสื้อผ้า ในที่สุดก็จะส่งของกลับบ้านได้" },
        progress = { "243:48443629:312233840 N 68:1129293446:67680093", "พ่อค้าเพิ่มที่นี่และทั่ว Azeroth ทำให้วัสดุทำเสื้อผ้าเด็กกำพร้ามีน้อยลง เจ้ามีน้ำใจมากที่ช่วยรวบรวมลินินให้ภรรยาข้าทำเสื้อใหม่ {name} ขอบใจ\n\nหวังว่าจะได้กลับบ้านหาภรรยาเร็ว ๆ นี้" },
        completion = { { "29:1268175336:438038976 N 256:1277095281:1746940048 N 75:858745580:1704338277", "29:1268175336:438038976 N 258:1962363316:155202773 N 75:858745580:1704338277" }, "เจ้าทำดีมาก {name} ขอบใจอีกครั้ง\n\nเจ้ามีน้ำใจสูงส่งที่ช่วยข้า ไม่แปลกที่เลือกตามแสง หวังว่าจะมีทางตอบแทนทุกอย่าง... ว่าอย่างไรนะ? เป็นเพียงสิ่งเล็กน้อยที่ทำได้หรือ? เห็นไหม นี่แหละที่ข้าพูด {name} มีน้ำใจเสมอต้นเสมอปลาย\n\nจงปลอดภัย ขอแสงคุ้มครองระหว่างเดินทาง" },
        required = { [2589] = { "11:1393025601:1453557725", "ผ้าลินิน" } },
        steps = { { "11:1393025601:1453557725", "ผ้าลินิน" } },
    },
    [1649] = { -- The Tome of Valor
        title = { "17:766339301:681013694", "คัมภีร์แห่งความกล้าหาญ" },
        objective = { "37:1332158203:474395012", "คุยกับ Duthorian Rall ใน Stormwind" },
        description = { "496:14636250:252136294", "ความกล้าหาญและคุณธรรมร่วมทางเหมือนแร่หายาก ต้องทะนุถนอมเมื่อพบเพราะมีค่า แต่ต้องใช้เวลาเก็บและขัดเกลา เมื่อผสมถูกส่วนจะเป็นโลหะผสมแข็งแกร่ง บางครั้งแม้แรงที่สุดก็ทำลายไม่ได้\n\nกำลัง ศรัทธา และความกล้าเจ้าต้องถูกทดสอบ ต้องเรียนไม่เสียศรัทธา และรู้ว่าด้วยพลังแสง เจ้าฝ่าสิ่งที่คนส่วนใหญ่ทำไม่ได้" },
        completion = { { "230:1801615507:1924725551 N 214:210948389:2041840037", "232:1537002477:1593406238 N 214:210948389:2041840037" }, "อา อยากขอรับบททดสอบความกล้าจากข้า ยอดเยี่ยม\n\nในเมืองกับรอบดินแดนมีงานท้าทายมากมาย ที่ต้องใช้คนมีฝีมืออย่างเจ้า\n\nอย่ามองบททดสอบนี้เบา {name} เช่นหลายสิ่งบนวิถีเรา มันอาจพรากชีวิต ศาสนจักรอยากเพิ่มกำลังเสมอ แต่เข้าใจการเสียสละที่ต้องมี เพื่อให้พาลาดินผู้รับใช้คู่ควร\n\nพร้อมหรือยัง?" },
    },
    [1650] = { -- The Tome of Valor
        title = { "17:766339301:681013694", "คัมภีร์แห่งความกล้าหาญ" },
        objective = { "33:1361830579:2013545464", "หา Daphne Stilwell ใน Westfall" },
        description = { "501:1016710598:210592495", "ดี! ความไม่ลังเลแสดงว่าพร้อมและอยากทดสอบตน เช่นนั้นก็ได้\n\nสุด Longshore ใน Westfall มีบ้านเล็กมองออกทะเล คู่สามีภรรยา Stilwell อาศัยอยู่ Jordan เป็นช่างตีเหล็กยอดเยี่ยม ไปพบคนแคระที่ Ironforge ระยะหนึ่ง ทำให้ Daphne ภรรยาอยู่คนเดียวไร้ผู้คุ้มครอง\n\nรายงานว่าพวก Defias แทบยึดพื้นที่หมด Daphne อาจต้องการคนป้องกันเหล่าวายร้าย ไปที่นั่น" },
        completion = { "7:989913233:66981971 N 477:1761634126:726450858", "สวัสดี {name} ดูเกราะกับอาวุธแล้ว คงมาชิงที่ดิน หรือศาสนจักรส่งมาคุ้มครองระหว่าง Jordan ไม่อยู่\n\nขอแนะนำตัว ข้าชื่อ Daphne Stilwell ยินดีที่ได้พบ\n\nเจ้ายังไม่สาย... ข้าฆ่าพวกสวะไปแค่ครึ่งโหลนับแต่ตะวันขึ้นครั้งก่อน พวกมันอ้อมโค้งนั่นมาช้าหน่อย แต่คงเห็นเจ้ามาแล้ว หมายความว่าจะมาถึงได้ทุกเมื่อ" },
    },
    [1651] = { -- The Tome of Valor
        title = { "17:766339301:681013694", "คัมภีร์แห่งความกล้าหาญ" },
        objective = { "193:1110255746:289376416", "ปกป้อง Daphne Stilwell จากการโจมตีของ Defias\n\nหากจะสำเร็จ ทั้งเจ้ากับนางต้องไม่ตาย\n\nเมื่อสำเร็จแล้วคุยกับ Daphne Stilwell อีกครั้ง" },
        description = { "418:1163841200:29511730", "ข้าว่าพวกมันจะมาอีกเร็ว ๆ นี้ เตรียมตัว\n\nมีปืนในบ้าน ข้าจะไปหยิบพร้อมช่วย แต่ส่วนใหญ่เจ้าต้องพึ่งตัวเอง\n\nไม่รู้จะส่งมากี่คน แต่แน่ใจว่ามากกว่ากลุ่มเล็กก่อนหน้า\n\nขอพรจากแสงให้มากที่สุด เพราะ... ได้ยินไหม? ข้าว่ามาแล้ว\n\nเราตั้งรับใกล้บ้าน!" },
        progress = { "34:1735853487:1605327427", "เราจะตั้งรับที่บ้าน!" },
        completion = { "15:2058457633:923592818 N 185:1242308932:1948859082", "ทำได้แล้ว {name}! ขอบใจที่ช่วย เจ้ายอดเยี่ยมจริง ไม่คิดว่าพาลาดินจะรับมือศัตรูมากพร้อมกันได้\n\nเจ้ากล้าหาญต่อโอกาสที่เป็นรองอย่างแท้จริง" },
        objectiveLabels = {
            event = { ["Protect Daphne Stilwell"] = "ปกป้อง Daphne Stilwell" },
        },
    },
    [1652] = { -- The Tome of Valor
        title = { "17:766339301:681013694", "คัมภีร์แห่งความกล้าหาญ" },
        objective = { "37:1332158203:474395012", "คุยกับ Duthorian Rall ใน Stormwind" },
        description = { "249:1747617204:1099474803", "โปรดกลับไปบอก Duthorian ว่าตอนนี้ข้าปลอดภัย ต้องขอบใจเจ้ากับศาสนจักร\n\nเขาจะส่งข่าว Ironforge ให้ Jordan รู้ว่าไม่ต้องกลัว\n\nโอ้ คิดถึงสามีเหลือเกิน แทบรอเขากลับไม่ไหว" },
        completion = { "19:1583053499:850208847 N 357:1149001645:1839023495", "พบกันอีกแล้ว {name} ดูจิตใจเบิกบานดี\n\nบ้าน Stilwell จะปลอดภัยไปอีกวัน และจากเรื่องที่เล่าก็ไม่ขาดอันตรายเลย ทำดีมาก\n\nDaphne กับ Jordan ช่วยศาสนจักรมามาก การให้เจ้าปกป้องทรัพย์สินและชีวิตเป็นสิ่งน้อยที่สุดที่ทำให้ได้\n\nเจ้าจะได้รางวัลสำหรับความกล้า" },
    },
    [1653] = { -- The Test of Righteousness
        title = { "25:1999447463:2028398700", "บททดสอบความชอบธรรม" },
        objective = { "37:585459939:1973949970", "คุยกับ Jordan Stilwell ใน Ironforge" },
        description = { "496:663347336:759816825", "ที่จริง Jordan คงอยากขอบใจด้วยตนเอง และเมื่อต้องส่งสารว่าภรรยาปลอดภัย ข้าว่าเจ้าเหมาะที่สุด\n\nJordan เคยตั้งใจเป็นพาลาดินแห่งแสง ก่อนความทุ่มเทต่องานฝีมือบิดานำสู่อีกทาง เขารู้จักวิถีเราลึกซึ้งและนับเป็นผู้ศรัทธาที่สุดคนหนึ่ง\n\nคงยังอยู่ Ironforge ชอบทำงานนอกประตูกลางวัน เห็นว่าเพราะอากาศภูเขาเย็นสบาย" },
        completion = { "10:10763625:219111161 N 424:23441630:530663451 N 55:27068561:642940916", "สวัสดี {name} เชื่อว่าแสงอยู่กับเจ้าสินะ?\n\nอะไรนะ? Duthorian ส่งมา!? ภรรยาข้าเป็นอย่างไร? รู้แล้วว่าจะมีปัญหาถ้าจากมา โปรดบอกว่านาง... โอ้ ขอบคุณ ยินดีจริงที่ปลอดภัย Defias เป็นภัยมานานก่อนโจมตีครั้งนี้ แต่ทีนี้ที่ปรึกษากษัตริย์ปฏิเสธไม่ได้แล้ว\n\nDuthorian บอกอะไรอีก?\n\nเจ้าคือคนที่ส่งไปปกป้องภรรยาหรือ? ขอบใจอีกครั้ง {name} นึกไม่ออกว่าจะมีบททดสอบความกล้าใดดีกว่านี้" },
    },
    [1654] = { -- The Test of Righteousness
        title = { "25:1999447463:2028398700", "บททดสอบความชอบธรรม" },
        objective = { "182:15788613:392528447", "ใช้ Jordan's Weapon Notes หา Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer และ Kor Gem แล้วนำกลับไปให้ Jordan Stilwell ใน Ironforge" },
        description = { "494:767268978:624470763 C 1:63:63", "ข้าอยากตอบแทน หากยอมรับ? อย่าเข้าใจผิด ความใจกว้างขึ้นกับว่าเจ้าช่วยได้มากแค่ไหน แต่เห็นว่าเราทั้งคู่จะได้ประโยชน์มากจากความร่วมมือนี้\n\nข้าจะสร้างอาวุธคู่ควรผลงาน สัญลักษณ์ความเป็นพาลาดินและแสง แต่เจ้าต้องรวบรวมวัสดุให้ เริ่มจดรายการแล้ว เพียงต้องมีคนกล้าและฝีมือพอกู้กลับ ว่าอย่างไร {class}?" },
        progress = { "226:1573780154:154061087", "ของที่ตามหาจะได้มายาก แต่ข้ารับรองว่าอาวุธที่สร้างจะคุ้มความพยายาม\n\nจะเป็นผลงานดีที่สุดถึงตอนนี้ และเป็นเพียงค่าตอบแทนเล็กน้อยที่เจ้าช่วยข้า" },
        completion = { "235:1464012420:613531248 N 110:1970732242:612585804", "วิเศษ! ได้ของครบแล้ว\n\nข้าน่าจะตีอาวุธชั้นยอดด้วยของเหล่านี้ได้ไม่มีปัญหา ที่จริงวางแผนไว้นานแล้ว เพียงไม่เคยมีโอกาสรวบรวมของ ขอบใจ {name}\n\nดีจริงที่ได้ค้อนบิดาคืน... และอัญมณี Kor ไม่คิดว่าจะได้เห็นด้วยตาตนเอง" },
        required = { [6994] = { "21:1837031187:1998177872", "ไม้โอ๊ก Whitestone แปรรูป" }, [6993] = { "29:984971540:1532228370", "แร่ถลุงที่ส่งมาให้ Jordan" }, [6895] = { "24:1247241134:543372825", "ค้อนตีเหล็กของ Jordan" }, [7083] = { "16:738523197:1168599911", "อัญมณี Kor ที่ชำระแล้ว" } },
        steps = { { "21:1837031187:1998177872", "ไม้โอ๊ก Whitestone แปรรูป" }, { "29:984971540:1532228370", "แร่ถลุงที่ส่งมาให้ Jordan" }, { "24:1247241134:543372825", "ค้อนตีเหล็กของ Jordan" }, { "16:738523197:1168599911", "อัญมณี Kor ที่ชำระแล้ว" } },
    },
    [1655] = { -- Bailor's Ore Shipment
        title = { "21:998681487:1996286686", "แร่ที่ส่งให้ Bailor" },
        objective = { "62:1574932073:1102089674", "นำ Jordan's Ore Shipment ไปให้ Bailor Stonehand ใน Loch Modan" },
        description = { { "485:1035751167:1042077948", "487:1817390861:1632485622" }, "อ๊า ทำข้าตกใจ! ไม่เห็นหรือว่าคิดอะไรเพลินอยู่?\n\nอะไรนะ? ของส่ง Jordan... สำหรับ Ironforge อา ใช่ รู้ว่าพูดถึงอะไร โอเกอร์ Mo'grosh นั่นแหละเอาแร่ของสหายเก่าไป คาราวานมาจาก Wetlands ถูกซุ่มโจมตี ยามที่รอดเพิ่งตายไม่กี่วันก่อน ผู้รักษาไปไม่ทัน\n\nหากอยากได้ของ ต้องข้าม Loch ไปตะวันออกเฉียงเหนือ มันต้องอยู่ที่ไหนสักแห่ง" },
        progress = { "76:1673701462:1261735283", "เป็นอย่างไร โชคดีบ้างไหม? ฮ่า ๆ โอเกอร์ยังเอาชนะเจ้าไม่ได้สินะ?" },
        completion = { "352:755159845:257720696 C 1:46:46", "ใช่ ๆ นี่แหละ ฮ่า! หากรู้ว่าจะไปสู้โอเกอร์จริง คงให้รายการของมาแทนอย่างเดียว แต่เจ้าไม่ได้มาทำธุระให้ข้าใช่ไหม?\n\nตกลงแล้วต้องตามนั้น Jordan ต้องการโลหะผสมข้าหนึ่งชุด เขาจะได้มัน\n\nฝากสวัสดีเขาด้วย และเดินทางปลอดภัย {class}" },
        required = { [6992] = { "21:449310565:584931533", "แร่ชุดที่ส่งให้ Jordan" } },
        objectiveLabels = {
            item = { ["Jordan's Ore Shipment"] = "แร่ชุดที่ส่งให้ Jordan" },
        },
    },
    [1661] = { -- The Tome of Nobility
        title = { "20:1134088226:597188250", "คัมภีร์แห่งความสูงส่ง" },
        objective = { "37:1332158203:474395012", "คุยกับ Duthorian Rall ใน Stormwind" },
        description = { { "24:1616777343:624527127 N 372:1247119344:172782620", "24:1616777343:624527127 N 371:1526837221:477731821" }, "สวัสดีอีกครั้ง {name} ข้าภูมิใจเรียกเจ้าว่าพี่น้องยิ่งกว่าเดิม ความทุ่มเทเป็นเกียรติแก่เราทั้งหมด\n\nถึงเวลามอบของขวัญยิ่งใหญ่ แต่จงรู้ว่าตอนนี้ให้เปล่า ภายหลังเมื่อเวลาพร้อม งานนี้จะท้าทายพาลาดินทุกคนที่เลือกรับมากกว่านี้\n\nคุยกับข้าอีกครั้ง แล้วจะมอบพรยิ่งใหญ่" },
        completion = { "47:991089976:917738564", "ยินดีด้วย ขอแสงคุ้มครองเจ้า" },
    },
    [1778] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "39:19873971:979803672", "คุยกับ Tiza Battleforge ใน Ironforge" },
        description = { "161:199340054:558409592 C 1:46:46", "ข้าจะวางแผนกลับบ้านเร็ว ๆ นี้ หวังว่า Stephanie สบายดีที่ Stormwind แทบรอพบอีกไม่ไหว ไว้พบกัน {class}" },
        completion = { "305:1310460902:2111686217 N 108:1529732564:2031035835", "กลับมาเร็วอย่างนี้เลยหรือ? บอกหน่อยว่าระหว่างจากไปทำอะไรสำเร็จ?\n\nช่วยงานที่มีเจตนาดีได้ไหม? บางทีได้เรียนคุณค่าการให้ หรือหน้าที่ต่อชาว Azeroth เพิ่ม บอกสิ ช่วยใครอย่างไร... น่าประทับใจ {name} นั่นคือการกระทำของผู้ตามแสงแน่นอน\n\nการเสียสละเช่นนี้จะได้รับตอบแทนเมื่อถึงเวลา" },
    },
    [1779] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "71:2144710276:1948813187", "นำ Symbol of Life ไปคุยกับ Muiredon Battleforge ใน Ironforge" },
        description = { "25:938274039:1514575683 N 458:913764333:2107448932", "รับนี่ {name} มันเรียกว่า Symbol of Life\n\nเจ้าพิสูจน์ความเอื้อเฟื้อและอดทนแล้ว ทีนี้ข้าอยากให้พิสูจน์ว่าชำนาญทั้งการต่อสู้และพลังเพียงใด\n\nMuiredon สามีข้าเพิ่งกลับจากเผชิญคนแคระ Dark Iron แทบไม่รอดชีวิต อยู่ตรงนั้นให้พรีสต์คนหนึ่งรักษาแผล\n\nนำสัญลักษณ์ไปคุยกับเขา หากช่วยได้เราจะได้คุยกันอีกเร็ว ๆ นี้ ขอแสงส่องเจ้า" },
        completion = { "24:115827572:1982046815 C 345:1494746991:1616927778", "*ไอ*\n\nสวัสดี {class} อย่าสนแผล พรีสต์ใจดีนี่จะดูแลเฒ่า Muiredon ในที่สุด ยังไม่ต้องใช้พลัง Symbol of Life ที่เจ้าถือ\n\nภรรยาส่งมาคุยหรือ? ได้ ข้าจะเล่าให้ฟังว่าเกิดอะไรกับ Muiredon และ Narm เพื่อนรัก พาลาดินเช่นเจ้า", variants = { { "24:115827572:1982046815 C 319:1600666385:1823799238 C 19:115948494:330198003", "*ไอ*\n\nสวัสดี {class} อย่าห่วงแผลข้าเลย เดี๋ยวนักบวชใจดีท่านนี้ก็ดูแลเฒ่า Muiredon เอง ข้ายังไม่ต้องใช้พลังจาก Symbol of Life ที่เจ้าถือมาหรอก\n\nภรรยาข้าส่งเจ้ามาคุยด้วยสินะ เอาสิ ข้าจะเล่าให้ฟังว่าเกิดอะไรขึ้นกับ Muiredon และ Narm เพื่อนรักที่เป็น {class} เหมือนเจ้า" } } },
    },
    [1780] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "37:1332158203:474395012", "คุยกับ Duthorian Rall ใน Stormwind" },
        description = { { "68:807452427:1545679958 C 180:366091192:630134166", "68:807452427:1545679958 C 182:584915407:1001861345" }, "ข้าจะนำของไปให้เด็กวันนี้เลย โปรดปลอดภัย {class}ผู้ใจดี ไม่บ่อยที่คนมีนิสัยเช่นเจ้ามาเมือง แต่เจ้าพิสูจน์ว่าพาลาดินใน Stormwind จะไม่หันหลังให้ผู้เดือดร้อน\n\nลาก่อน" },
        completion = { "28:1468068047:641870779 N 272:1692434067:1785846804 N 140:1117868778:1905916901", "กลับมาเร็วมาก {name} ระหว่างออกจากมหาวิหารทำอะไรสำเร็จ?\n\nช่วยงานที่มีเจตนาดีไหม? บางทีได้เรียนคุณค่าการให้ หรือหน้าที่ต่อชาว Azeroth เพิ่ม บอกสิ ช่วยใครอย่างไร... ข้าประทับใจ {name} นั่นคือการกระทำของผู้ตามแสงและเห็นผู้อื่นสำคัญกว่าตน\n\nการเสียสละเช่นนี้จะได้รับตอบแทนเมื่อถึงเวลา" },
    },
    [1781] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "53:2036098549:719116642", "นำ Symbol of Life ไปให้ Gazin Tenorm ใน Stormwind" },
        description = { "11:575381343:581364008 N 489:220384635:1134687611", "รับนี่ {name} เรียกว่า Symbol of Life\n\nเจ้าพิสูจน์ความเอื้อเฟื้อและอดทนแล้ว ถึงเวลาดูว่ามีพลังพอรวมศูนย์หนึ่งในของขวัญยิ่งใหญ่ที่สุดของแสงหรือไม่\n\nGazin สหายข้าเพิ่งกลับจากเผชิญ Defias ใน Elwynn ใกล้ Heroes' Vigil แทบไม่รอด อยู่ใกล้แท่นบูชาให้พรีสต์รักษาแผล\n\nนำสัญลักษณ์ไปคุยกับเขา หากช่วยได้เราจะได้คุยกันอีกเร็ว ๆ นี้ ขอให้ได้อาบรัศมีแสง" },
        completion = { "30:1553957293:548600022 C 368:392377505:571658381", "*ไอ*\n\nยินดีที่ได้พบ {class} อย่าสนแผล พรีสต์ใจดีนี่ดูแลเฒ่า Gazin ได้คราวนี้ ข้ายังไม่ต้องใช้พลัง Symbol of Life ที่เจ้าถือ... อย่างน้อยตอนนี้\n\nDuthorian ส่งมาคุยสินะ? ได้ ข้าจะเล่าเรื่องที่เกิดกับข้าและ Henze หากมีโชคกับฝีมือเจ้า บางทียังช่วยเราทุกคนได้" },
    },
    [1783] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "63:455249265:1815160708", "นำ Symbol of Life ไปชุบชีวิต Narm Faulk ใน Dun Morogh" },
        description = { "475:1885590689:1052010125 N 1:63:63", "เราสอดแนมคนแคระ Dark Iron ที่ตั้งมั่นใต้ Helm's Bed Lake รู้ว่าคิดร้าย ข้ากับ Narm จึงมองใกล้ขึ้น เห็นผู้นำสั่งคนของมัน\n\nเราได้โอกาสฆ่าบางคน แต่แกร่งกว่าที่คิด และพวกอื่นซุ่มเล่นงาน Narm บอกให้ข้าวิ่งหากำลังเสริม ข้าจึงอยู่ที่นี่\n\nNarm ต้องการความช่วยเหลือ ข้าไม่พักจนเขาได้มัน\n\nช่วยได้ไหม {name}?" },
        completion = { { "463:660337074:113140094", "462:1985626870:1525528861" }, "ขอบใจเท่าไรก็ไม่พอ พี่น้อง\n\nหากถือ Symbol of Life ก็คงเป็น Tiza กับ Muiredon ที่ส่งมาช่วย\n\nจริง ข้าล้มต่อ Dark Iron ตอนพยายามชิงเอกสาร ทนได้นานพอให้ Muiredon หนี แต่แสงแทบโอบรับข้าเต็มที่แล้วตอนเจ้ามา การมีพลังพอใช้สัญลักษณ์เป็นนิมิตยิ่งใหญ่ แต่ไว้คุยภายหลัง" },
    },
    [1784] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "120:1166248621:900877661", "นำ Dark Iron Script จากคนแคระ Dark Iron ใกล้ Helm's Bed กลับไปให้ Muiredon Battleforge ใน Ironforge" },
        description = { "496:1182116074:676060672 N 1:46:46", "ก่อนล้มในศึก ข้ากับ Muiredon แทบปราบสายลับ Dark Iron คนหนึ่งใกล้บ้านเล็กได้ เห็นกัปตันส่งคำสั่ง จึงจะฆ่าเขาเอาคำสั่งมา\n\nสมาชิกสภา Ironforge บางคนยังไม่เชื่อว่ามี Dark Iron ใน Dun Morogh หากได้เอกสาร ไม่เพียงพิสูจน์การเคลื่อนไหว อาจรู้แผนด้วย\n\nเอาเอกสารสักฉบับกลับไปให้ Muiredon {name}" },
        progress = { "30:1267435038:1100414415 N 124:1608334862:489362554", "กลับมาแล้ว! ดีใจที่เห็น {name} แผลหายแล้ว ข้าแทบพร้อมกลับ Helm's Bed Lake ทันทีที่กล่อมภรรยาได้ว่าจะไม่เป็นไร" },
        completion = { "196:2139211279:1119060408 N 1:46:46", "ฮ่า ๆ! ทำได้แล้ว! ช่วย Narm และพบหลักฐานให้ภรรยาข้านำเข้าสภา เป็นพรแห่งแสงจริง... ไม่นับภรรยาข้าแน่นอน\n\nขอบใจอีกครั้ง {name}" },
        required = { [6847] = { "16:663276681:1599874104", "เอกสารอักษร Dark Iron" } },
        steps = { { "16:663276681:1599874104", "เอกสารอักษร Dark Iron" } },
    },
    [1785] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "39:19873971:979803672", "คุยกับ Tiza Battleforge ใน Ironforge" },
        description = { "170:455296774:768174830 C 103:665603835:1811960973", "เห็นภรรยาข้ายิ้มภูมิใจตรงนั้นแล้ว รีบย้ายก้นไปหา ข้าว่านางมีเรื่องคุย\n\nแสงอยู่กับเจ้า {class}ผู้เกรียงไกร เมื่อถึงเวลาข้าจะมองหาเจ้าในสนามรบกับ Scourge และ Dark Iron" },
        completion = { "50:510123133:1197410327 N 349:1115842658:1106771011 N 64:911836381:914061766", "วันนี้เจ้าช่วย Ironforge ทั้งเมืองอย่างมาก {name} ภูมิใจที่นับเจ้าเป็นพวกเรา หากรู้สึกพร้อม ข้าอยากให้พรด้วยม้วนคาถานี้ Symbol of Life ใช้ได้เฉพาะพาลาดินที่พร้อมรับพรยิ่งใหญ่ที่สุดอย่างหนึ่งของแสง พลังคืนคนตายสู่ชีวิต\n\nข้าจะสอนชุบชีวิตสหาย ใช้อย่างมีสติ {name} และขอบใจแทนตัวข้า สามี และ Ironforge" },
    },
    [1786] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "60:2084789108:1825918100", "นำ Symbol of Life ไปชุบชีวิต Henze Faulk ใน Elwynn" },
        description = { "492:862180168:1402210752 N 1:63:63", "ข้ากับ Henze ไปถึง Heroes' Vigil เกาะกลาง Stone Cairn Lake ทางตะวันออกเฉียงเหนือของ Elwynn ได้ข่าว Defias แทรกพรมแดน จึงอยากหาหลักฐานให้ที่ปรึกษากษัตริย์\n\nเห็นพวกสวะสองสามคนตรวจเอกสารจึงโจมตี แต่พวกจอมเวทที่เพิ่มมาปราบเราอย่างเร็ว\n\nHenze ต้านไว้ให้ข้าหนี... เจ้างั่ง ทำกล้าหาญเสียได้\n\nเขายังอยู่ตรงนั้น Henze น่ะ ช่วยเราได้ไหม {name}?" },
        completion = { { "388:54645785:329934576 N 77:73279985:835247376", "387:754393913:1183363189 N 77:73279985:835247376" }, "ขอบใจ พี่น้อง\n\nเห็นเจ้าใช้ Symbol of Life ขอเดาว่า Duthorian หรือ Gazin ส่งมา?\n\nข้าล้มต่อผู้ร่ายเวท Defias ตอนข้ากับ Gazin พยายามชิงแผน ทนได้นานพอให้ Gazin หนี แต่สุดท้ายเวทพวกมันชนะ\n\nเจ้าพาข้ากลับมาได้ ไม่ใช่ทุกคนจะใช้สัญลักษณ์ได้ {name} การเติมพลังด้วยศรัทธาตนเป็นนิมิตที่ดี" },
    },
    [1787] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "106:798784540:1049002845", "นำ Defias Script จาก Defias Rogue Wizards ใน Elwynn กลับไปให้ Gazin Tenorm ใน Stormwind" },
        description = { "325:907555238:548180447 N 176:902623132:717996388", "ไว้คุยเรื่องสัญลักษณ์ภายหลัง ตอนนี้ต้องเอาเอกสารที่เห็น Defias ตรวจอยู่ หากได้จะพิสูจน์ว่าแทรก Elwynn และหวังว่าจะเข้าใจแผน\n\nตอนนี้ข้ายังสู้ไม่ไหว {name} คิดว่าแกร่งพอเอาเอกสารจาก Defias บนเกาะไหม?\n\nหากได้ นำกลับ Gazin บอกว่าข้าปลอดภัย" },
        progress = { "15:949952493:1787088192 N 191:1186657533:894903998", "Henze ปลอดภัยไหม {name}? สำเร็จหรือ?\n\nด้วยฝีมืออาวุธกับพลังแสง ข้าว่า Heroes' Vigil คงปลอดภัยจาก Defias แต่กษัตริย์กับที่ปรึกษาต้องเป็นผู้ตัดสิน" },
        completion = { "73:1199768593:2124746302 N 1:33:33", "วิเศษ! เจ้ารอดและช่วย Henze แสงอยู่กับเจ้าแน่นอน {name}!" },
        required = { [6846] = { "13:866050077:1162900131", "เอกสารอักษร Defias" } },
        steps = { { "13:866050077:1162900131", "เอกสารอักษร Defias" } },
    },
    [1788] = { -- The Tome of Divinity
        title = { "20:580979070:1619520455", "คัมภีร์แห่งความศักดิ์สิทธิ์" },
        objective = { "37:1332158203:474395012", "คุยกับ Duthorian Rall ใน Stormwind" },
        description = { "210:1686226306:267453460 N 71:1358367786:1883346167", "หลัง Duthorian ดูแล้ว ข้าจะนำเอกสารให้ที่ปรึกษากษัตริย์ ระหว่างนี้ไปคุยกับเขาเลย เขาคงอยากตบหลังชมแน่!\n\nขอบใจอีกครั้ง {name} หวังว่าจะพบกัน เจ้าเป็นพันธมิตรที่ภูมิใจเรียกว่าสหาย" },
        completion = { "27:277260357:1418937638 N 397:1662902253:207972508 N 61:612636491:1454222326", "วันนี้ทำดีมาก {name} ควรภูมิใจกับสิ่งที่สำเร็จ\n\nยิ่งกว่านั้นควรภูมิใจความสามารถ ไม่ใช่ทุกคนใช้ Symbol of Life ได้ การเรียกแสงคืนคนตายแปลว่าพร้อมรับเกียรติยิ่งใหญ่อย่างหนึ่งของพาลาดิน พลังชุบชีวิต\n\nเจ้าจะคืนสหายที่ล้มลงได้เช่นที่ทำกับ Henze\n\nจงอยู่ดี {name} แสงส่องเจ้าแล้ว ควรต้อนรับเต็มใจ" },
    },
    [1789] = { -- The Symbol of Life
        title = { "18:157505019:905954602", "สัญลักษณ์แห่งชีวิต" },
        completion = { "12:423093272:1742530706 N 275:760795158:1371530694 C 50:1443446330:1997436446", "รีบ {name} มากกว่าหนึ่งชีวิตแขวนบนเส้นด้ายหากล้มเหลว\n\nหากช่วย Muiredon กับ Narm ไม่สำเร็จด้วยเหตุใด กลับมาข้าจะให้ Symbol of Life อีกชิ้นสำหรับเดินทาง\n\nอย่าคิดว่าเป็นการให้เปล่า เจ้าต้องพิสูจน์ว่าคู่ควรเหมือน{class}คนอื่น ความล้มเหลวต่อเนื่องอาจมีผลต่อเจ้าในภายหลัง", variants = { { "63:1192674564:367471191 N 138:865268615:1487101270", "หากใช้ Symbol of Life แล้วช่วย Narm ไม่สำเร็จ {name} ให้กลับมาหาข้า ข้าจะให้อีกชิ้น\n\nทั้งข้าและสามีหวังให้เจ้ากลับมาพร้อมข่าวดี ได้โปรดรีบไปเถอะ" } } },
        description = { "63:1192674564:367471191 N 138:865268615:1487101270", "{name} ถ้าใช้ Symbol of Life แล้วช่วย Narm ไม่สำเร็จ ให้กลับมาหาข้า ข้าจะให้อีกชิ้น\n\nทั้งข้ากับสามีหวังอย่างยิ่งว่าเจ้าจะกลับมาโดยทำสำเร็จ ได้โปรดรีบไปเถอะ" },
    },
    [1790] = { -- The Symbol of Life
        title = { "18:157505019:905954602", "สัญลักษณ์แห่งชีวิต" },
        completion = { "12:423093272:1742530706 N 273:1767643461:1645655961 C 50:1443446330:1997436446", "รีบ {name} มากกว่าหนึ่งชีวิตแขวนบนเส้นด้ายหากล้มเหลว\n\nหากช่วย Gazin กับ Henze ไม่สำเร็จด้วยเหตุใด กลับมาข้าจะให้ Symbol of Life อีกชิ้นสำหรับเดินทาง\n\nอย่าคิดว่าเป็นการให้เปล่า เจ้าต้องพิสูจน์ว่าคู่ควรเหมือน{class}คนอื่น ความล้มเหลวต่อเนื่องอาจมีผลต่อเจ้าในภายหลัง" },
        description = { "12:423093272:1742530706 N 330:14965725:764643551", "รีบเข้า {name} ถ้าเจ้าพลาด จะมีมากกว่าหนึ่งชีวิตที่ตกอยู่ในอันตราย\n\nถ้าช่วย Gazin กับ Henze ไม่สำเร็จด้วยเหตุใดก็ตาม กลับมาหาข้า ข้าจะให้ Symbol of Life อีกชิ้นติดตัวไป\n\nอย่าคิดว่าข้าช่วยเพราะสงสารอย่างเดียว เจ้าต้องพิสูจน์ว่าคู่ควรเหมือนพาลาดินคนอื่น หากล้มเหลวซ้ำ ๆ อาจส่งผลกับเจ้าในภายหลัง" },
    },
    [1793] = { -- The Tome of Valor
        title = { "17:766339301:681013694", "คัมภีร์แห่งความกล้าหาญ" },
        completion = { "47:1411517023:555572023 N 457:1149593938:1955954602", "พิสูจน์แล้วว่าแสงอยู่กับเจ้า {name} แต่เมื่อยุคอันตรายขึ้น ต้องรู้กำลังใต้เนื้อหนัง เมื่อปีศาจ มังกร หรือชั่วร้ายใดก้าวสู่ดินแดน ความกล้าจะถูกทดสอบ แข็งแกร่งพอไหม?\n\nความกล้าไม่ว่าสถานการณ์ใดเป็นส่วนหนึ่งของพาลาดิน เท่ากับแสง เกราะ อาวุธ การปกป้องผู้อ่อนแอและไม่เสียศรัทธาคืออีกสองบทเรียนที่ต้องเชี่ยวชาญระหว่างศึกษาใน Cathedral of Light" },
    },
    [1794] = { -- The Tome of Valor
        title = { "17:766339301:681013694", "คัมภีร์แห่งความกล้าหาญ" },
        completion = { "47:1411517023:555572023 N 457:1149593938:1955954602", "พิสูจน์แล้วว่าแสงอยู่กับเจ้า {name} แต่เมื่อยุคอันตรายขึ้น ต้องรู้กำลังใต้เนื้อหนัง เมื่อปีศาจ มังกร หรือชั่วร้ายใดก้าวสู่ดินแดน ความกล้าจะถูกทดสอบ แข็งแกร่งพอไหม?\n\nความกล้าไม่ว่าสถานการณ์ใดเป็นส่วนหนึ่งของพาลาดิน เท่ากับแสง เกราะ อาวุธ การปกป้องผู้อ่อนแอและไม่เสียศรัทธาคืออีกสองบทเรียนที่ต้องเชี่ยวชาญระหว่างศึกษาใน Cathedral of Light" },
    },
    [1806] = { -- The Test of Righteousness
        title = { "25:1999447463:2028398700", "บททดสอบความชอบธรรม" },
        objective = { "60:1467185093:490126034", "รอ Jordan Stilwell ตีอาวุธให้เสร็จ" },
        description = { "274:1680318415:2101850981 N 167:1946951817:1621635957", "ไปเตาหลอมเริ่มกันไหม? ข้าเตรียมรับเจ้ามาระยะหนึ่งแล้ว ไม่น่านานเลย\n\nเมื่อเสร็จ เจ้าจะพร้อมปกป้องแสงยิ่งกว่าเดิม ข้าสาบาน\n\nขอพูดตรงบ้าง {name} เห็นผลงานผจญภัยก็อิจฉา แต่การรู้ว่าช่วยการเดินทางในทางสำคัญของตนได้ ก็นำความสุขมา" },
        completion = { "12:1055357314:800872003 N 323:1408254693:1950859563", "นี่ {name} อาวุธคู่ควรผู้กล้าแห่งแสงเช่นเจ้า ข้าตั้งชื่อตามสหายพาลาดินคนแคระผู้ยิ่งใหญ่ เขาชื่อ Verigan... Bosch Verigan\n\nรับแทนข้ากับภรรยา เราติดหนี้มาก โลกจะปลอดภัยขึ้นเมื่อคนฝีมือเช่นเจ้าเดินทางในแผ่นดิน" },
    },
    [2997] = { -- Tome of Divinity
        title = { "16:842815813:2096287249", "คัมภีร์ความศักดิ์สิทธิ์" },
        objective = { "39:19873971:979803672", "คุยกับ Tiza Battleforge ใน Ironforge" },
        description = { "7:989913233:66981971 N 426:1382145446:289068386 N 1:46:46", "สวัสดี {name} รู้ว่ายุ่งช่วยชาว Dun Morogh แต่มีเวลาควรขึ้น Ironforge คุยกับ Tiza Battleforge ผู้ที่เราเคารพมาก พาลาดินรุ่นเยาว์ไปหานางเมื่อถึงเวลาเรียนแสงและสิ่งที่คาดหวัง\n\nพบนางชั้นบน Hall of Mysteries หากไม่เคยไป อยู่ Mystic Ward โชคดี {name}" },
        completion = { "10:1401179418:1568553899 N 72:822677109:743413756", "ยินดีที่ได้พบ {name} หวังว่าแสงแสดงวิถีแท้และคุ้มครองจากชั่วร้าย" },
    },
    [2998] = { -- Tome of Divinity
        title = { "16:842815813:2096287249", "คัมภีร์ความศักดิ์สิทธิ์" },
        objective = { "37:1332158203:474395012", "คุยกับ Duthorian Rall ใน Stormwind" },
        description = { { "423:823466612:209905540", "422:1718958553:1973714425" }, "สวัสดี พี่น้อง Duthorian Rall หนึ่งในพาลาดินผู้มีอิทธิพลมากที่สุดเพิ่งพูดถึงเจ้า ข้าได้ยินว่าถึงเวลาทดสอบบ้าง พร้อมคำชมมากมายเรื่องผลงานที่ผ่านมา\n\nหากเป็นข้าคงไป Stormwind คุยเมื่อมีเวลา แน่ใจว่าอยู่ Cathedral of Light ที่เขาใช้เวลาส่วนใหญ่" },
        completion = { "94:604245957:1595313429 N 1:46:46", "Stormwind สวยงามใช่ไหม?\n\nจังหวะมาพอดีที่สุดเลย {name}" },
    },
    [2999] = { -- Tome of Divinity
        title = { "16:842815813:2096287249", "คัมภีร์ความศักดิ์สิทธิ์" },
        objective = { "38:1921949855:89444441", "คุยกับ Tiza Battleforge ใน Ironforge" },
        description = { "7:989913233:66981971 N 286:911159731:1951836842", "สวัสดี {name} รู้ว่ายุ่งช่วยชาว Dun Morogh แต่มีเวลาควรขึ้นชั้นบนคุยกับ Tiza Battleforge ผู้ที่เราเคารพมาก พาลาดินรุ่นเยาว์ไปหานางเมื่อถึงเวลาเรียนแสงและสิ่งที่คาดหวัง" },
        completion = { "10:1401179418:1568553899 N 72:822677109:743413756", "ยินดีที่ได้พบ {name} หวังว่าแสงแสดงวิถีแท้และคุ้มครองจากชั่วร้าย" },
    },
    [3000] = { -- Tome of Divinity
        title = { "16:842815813:2096287249", "คัมภีร์ความศักดิ์สิทธิ์" },
        objective = { "39:19873971:979803672", "คุยกับ Tiza Battleforge ใน Ironforge" },
        description = { "7:989913233:66981971 N 413:126887888:473376874", "สวัสดี {name} รู้ว่ายุ่งช่วยชาว Azeroth แต่มีเวลาควรกลับ Ironforge คุยกับ Tiza Battleforge หนึ่งในพาลาดินที่บ้านเจ้าเคารพที่สุด พาลาดินคนแคระรุ่นเยาว์ไปหาเมื่อถึงเวลาเรียนแสงและสิ่งที่คาดหวังจากเราทุกคน\n\nพบนางชั้นบน Hall of Mysteries ใน Mystic Ward" },
        completion = { "34:1737362673:1592107595 N 1:46:46", "ข้าขอทักทายและต้อนรับ {name}" },
    },
    [3101] = { -- Consecrated Letter
        title = { "18:1414959910:981926338", "จดหมายศักดิ์สิทธิ์" },
        objective = { "77:1840737777:606004247", "อ่าน Consecrated Letter แล้วคุยกับ Brother Sammuel ใน Northshire Abbey" },
        description = { "91:566813027:607752075 N 188:124104772:182227676", "มีคนขอให้ข้านำเรื่องนี้มาบอกทันทีที่เจ้ากลับจากค่ายโคบอลด์ {name} ดูเหมือนจดหมายผนึกตรา Brother Sammuel ครูฝึกพาลาดินประจำถิ่น ข้าคงไม่รออ่านก่อนทำธุระอื่นใน Abbey" },
        progress = { { "325:1912972240:503082234", "324:1870658895:1620141108" }, "ในที่สุด! พบหน้ากันอย่างพี่น้อง ยินดีต้อนรับสู่ Northshire ที่นี่จะเป็นบ้านชั่วคราวระหว่างเรียนรู้วิธีทำสิ่งต่าง ๆ แต่ Stormwind ไม่ไกล ไม่ช้าก็เร็ววิถีจะพาไป จนกว่านั้นจงอดทน... อัศวิน Silver Hand" },
        completion = { "474:1794890543:1468829774 C 1:33:33", "ระหว่างนี้ควรรู้อีกสักอย่างสองอย่าง เจ้าเป็นสัญลักษณ์ต่อหลายคนในแผ่นดิน จงประพฤติให้สม แสงศักดิ์สิทธิ์ส่องในตัว ทั้งพันธมิตรและศัตรูจะเห็นชัด\n\nเมื่อปัญญาและพลังเพิ่ม ต้องฝึกเรียนความสามารถใหม่ นั่นคือหน้าที่ข้า เมื่อรู้สึกมีประสบการณ์ใน Northshire แล้วกลับมา ข้าจะสอนสิ่งที่เห็นว่าพร้อม โชคดี... {class}!" },
        required = { [9570] = { "18:1414959910:981926338", "จดหมายที่ผ่านพิธีชำระ" } },
        steps = { { "18:1414959910:981926338", "จดหมายที่ผ่านพิธีชำระ" } },
    },
    [3681] = { -- Tome of Divinity
        title = { "16:842815813:2096287249", "คัมภีร์ความศักดิ์สิทธิ์" },
        objective = { "39:1969802159:1119030629", "คุยกับ Duthorian Rall ใน Stormwind" },
        description = { "33:1747674573:1216266132 R 335:1236771365:494582460", "ขอโทษที่ขัดการเดินทาง ชาว{race} แต่ควรรู้ว่า Stormwind เพิ่งส่งข่าวให้พาลาดินไปรายงานตัวฝึก\n\nหากไม่รู้อะไรมากกว่านี้ ข้าว่าเจ้าใกล้ถึงช่วงพิเศษและควรเริ่มศึกษาคัมภีร์\n\nหา Duthorian Rall ใน Stormwind ปกติเขาฝึกพาลาดินที่ Cathedral of Light" },
        completion = { "35:1951965010:164938304 C 1:46:46", "ยินดีต้อนรับสู่ Cathedral of Light {class}" },
    },
    [4485] = { -- The Tome of Nobility
        title = { "20:1134088226:597188250", "คัมภีร์แห่งความสูงส่ง" },
        objective = { "37:1332158203:474395012", "คุยกับ Duthorian Rall ใน Stormwind" },
        description = { "7:989913233:66981971 N 242:385278320:567254629 N 143:2070927695:586880769", "สวัสดี {name} เห็นว่าความทุ่มเทกับศรัทธายังเข้มแข็ง\n\nถึงเวลาคุยกับ Duthorian Rall ใน Stormwind มีบทเรียนอีก และข้ารู้สึกว่าพร้อมแล้ว\n\nหาเขาที่ Cathedral of Light และ {name} จงจริงจัง เจ้าบรรลุฐานะด้วยความถ่อมตนกับขยัน อย่าทำให้ผิดหวังด้วยความหยิ่ง\n\nจงอยู่ดี" },
        completion = { "38:1808560534:1703536824 N 155:840164256:1460860447", "อา กลับมหาวิหารแล้ว {name} ดี ช่วงนี้เกิดเรื่องมาก ข้าจะขอแรงหากพิสูจน์ว่าคู่ควร\n\nมีศัตรูร้ายกาจมากมาย ต้องให้เจ้าช่วยหยุด" },
    },
    [4486] = { -- The Tome of Nobility
        title = { "20:1134088226:597188250", "คัมภีร์แห่งความสูงส่ง" },
        objective = { "37:1332158203:474395012", "คุยกับ Duthorian Rall ใน Stormwind" },
        description = { { "73:1342543777:1753649086 N 422:803102063:749445481", "73:45331228:582636022 N 422:803102063:749445481" }, "อ้าว ๆ ดูพาลาดินผู้เกรียงไกรในความสง่างามสิ\n\nขอโทษ {name} ไม่ได้ดูหมิ่น... แค่อิจฉาบ้างเมื่อเห็นผลงาน Tiza ว่าเป็นจุดอ่อน ข้าสาบานจะปรับปรุง แต่บางครั้งก็ยาก เข้าใจไหม?\n\nเหตุที่อยากคุยคือ Duthorian Rall จาก Stormwind ส่งข่าวให้ไปพบที่ Cathedral of Light เมื่อพร้อม ฟังดูสำคัญ เหมือนมีเรื่องเกิดขึ้น" },
        completion = { "38:1808560534:1703536824 N 155:840164256:1460860447", "อา กลับมหาวิหารแล้ว {name} ดี ช่วงนี้เกิดเรื่องมาก ข้าจะขอแรงหากพิสูจน์ว่าคู่ควร\n\nมีศัตรูร้ายกาจมากมาย ต้องให้เจ้าช่วยหยุด" },
    },
    [7637] = { -- Emphasis on Sacrifice
        title = { "21:1519196606:649281733", "เน้นการเสียสละ" },
        objective = { "132:1715107925:1675852925", "เดินทางไป Ironforge รับ Exorcism Censer ของ High Priest Rohan ต้องบริจาค 150 โกลด์จึงจะได้รับ" },
        description = { "451:239449186:262399866 N 25:607666844:1328566199", "จะเตรียมรับงานนี้ ต้องแสดงการเสียสละและวิจารณญาณอันควร... โดยเน้นการเสียสละ\n\nเจ้าต้องได้กระถางขับวิญญาณของ High Priest Rohan แม้จะใช้เพื่อเหตุผลดีและยุติธรรม ก็ต้องชดเชยเหมาะสม\n\nไป Ironforge คุยกับมหาปุโรหิต นำเงินพอช่วยชดเชยกระถางที่เสียไป จะแสดงการเสียสละ\n\nไปเถอะ {name} เวลาสำคัญยิ่ง" },
        progress = { "257:1806535321:102458634", "สวัสดี พาลาดินผู้สูงส่ง! ข้าใส่เครื่องหอมสดใหม่ในกระถางคู่ใจ และอวยพรสามครั้งให้เจ้าใช้ เงินบริจาคจะช่วย Ironforge ทั้งสร้างกระถางใหม่และเพิ่มเสบียงอาหารที่ร่อยหรอสำหรับผู้ยากไร้" },
        completion = { "27:512452227:211256078 C 257:1083300396:1377773608", "พรจงมีแด่สหาย{class}! เงินบริจาคมากกว่าที่จำเป็น การเสียสละไม่เพียงชดเชยสิ่งที่เสีย แต่ช่วยผู้เดือดร้อนที่สุดใน Ironforge\n\nทีนี้ขอตรวจว่ากระถางเตรียมเหมาะกับงานภายหน้าแล้ว..." },
    },
    [7638] = { -- Lord Grayson Shadowbreaker
        title = { "26:312903867:1237982410", "Lord Grayson Shadowbreaker" },
        objective = { "72:321861201:103873172", "คุยกับ Lord Grayson Shadowbreaker ใน Cathedral District ของ Stormwind" },
        description = { { "19:1057308443:1361522860 N 422:1945027716:433564595", "19:1057308443:1361522860 N 420:1144914959:54614291" }, "ถึงเวลาแล้ว {name} ที่จะเรียนรู้ว่าต้องทำสิ่งใดเพื่อได้สิ่งที่รอมานาน... ม้าศึกของเจ้า\n\nคุยกับ Lord Grayson Shadowbreaker ใน Cathedral District ของ Stormwind เขาจะนำทางทั้งเรื่องวิชาม้าคู่ใจที่สุดของพาลาดิน และงานเพื่อได้ม้าของตน\n\nขอให้ผ่านบททดสอบได้ดี เพื่อแสง พี่น้องผู้สูงส่ง!", variants = { { "19:1057308443:1361522860 N 421:442078512:593457827", "ถึงเวลาแล้ว {name} ที่จะเรียนรู้ว่าต้องทำสิ่งใดเพื่อได้สิ่งที่รอมานาน... ม้าศึกของเจ้า\n\nคุยกับ Lord Grayson Shadowbreaker ใน Cathedral District ของ Stormwind เขาจะนำทางทั้งเรื่องวิชาม้าคู่ใจที่สุดของพาลาดิน และงานเพื่อได้ม้าของตน\n\nขอให้ผ่านบททดสอบได้ดี เพื่อแสง พี่น้องผู้สูงส่ง!" } } },
        completion = { "21:1838430250:1482072818 N 466:204272369:537604571", "ดีใจที่เห็น {name} รอข่าววิธีได้ม้าศึกสินะ บัดนี้ถึงเวลาแล้ว\n\nเจ้าจะถูกทดสอบหลายด้าน ที่สำคัญที่สุดคือใจที่จะก้าวเหนืออุปสรรคมากมาย นี่ไม่ใช่แบบฝึกหัดเรียนรู้ ฐานะเจ้าพ้นบททดสอบง่าย ๆ แล้ว เจ้าต้องช่วยสหายในอนาคตจากเงื้อมมือชั่วร้ายที่ต่อสู้มาตลอดชีวิต\n\nจงฟัง ถึงเวลาแล้ว!" },
    },
    [7639] = { -- To Show Due Judgment
        title = { "20:592596373:360392101", "แสดงวิจารณญาณอันควร" },
        objective = { "96:928861370:1811483463", "นำ Exorcism Censer กลับไปให้ Lord Grayson Shadowbreaker ใน Cathedral District ของ Stormwind" },
        description = { "202:1563154092:1467851450 N 32:822624140:409646700", "รับกระถางพร้อมพรข้า ข้าเคยใช้ขับวิญญาณหลายครั้ง น่าจะรับใช้งานลำบากข้างหน้าได้ดี\n\nกลับ Lord Grayson Shadowbreaker ที่ Stormwind เถอะ {name} ภารกิจดำเนินต่อกับเขา" },
        progress = { "14:1649650394:897424258 N 40:1539337789:409555863", "ยินดีที่กลับมา {name} ได้กระถางขับวิญญาณแล้วหรือ?" },
        completion = { "294:373512698:2055735510 N 169:1786630376:1312036249", "ใช่ ใช้ได้ ระหว่างกระบวนการนี้จะต้องเสียสละมากกว่าหนึ่งครั้ง ยินดีที่เต็มใจ การเสียสละสำคัญต่อการรักษาหน้าที่พาลาดิน... แต่ข้าไม่ต้องเทศน์เรื่องนี้หรอก\n\nทีนี้ {name} ต้องแสดงวิจารณญาณในการกระทำ กระถางนี้จะเป็นภาชนะใช้พิพากษาเหล่าวิญญาณทุกข์ทรมานในดินแดนที่เราเสียไป" },
    },
    [7640] = { -- Exorcising Terrordale
        title = { "21:751479789:1111333091", "ขับวิญญาณ Terrordale" },
        objective = { "193:1001329272:1332900648", "ใช้ Exorcism Censer ขับวิญญาณที่ทรมาน Terrordale เมื่อสังหาร Terrordale Spirits 25 ตนแล้ว กลับไปหา Lord Grayson Shadowbreaker ใน Cathedral District ของ Stormwind" },
        description = { "468:1322681221:1804566766", "ข้าใส่ดินแปดเปื้อนจาก Terrordale ใน Eastern Plaguelands หนึ่งหยิบมือลงกระถาง ทีนี้ใช้หาพื้นที่ซึ่งมีสัญญาณวิญญาณปั่นป่วน มองหาออร่าเขียวแผ่พื้นดิน เมื่อโลกกายภาพบิดเบี้ยวใต้ความทรมานแดนวิญญาณ แล้วใช้กระถางขับวิญญาณชั่วร้าย\n\nเมื่อพิพากษาวิญญาณพอ จะพร้อมดำเนินต่อ" },
        progress = { "28:1994220463:1564526748 N 34:1215395319:1543602897", "ยินดีที่พบอีก {name} งาน Terrordale เสร็จไหม?" },
        completion = { "11:534428891:784080240 N 395:1182338442:1587982462", "ทำดีมาก {name} การพิพากษาด้วยแสงต่อผู้อยู่ในมืดต้องมุ่งมั่นกระตือรือร้น เจ้าทำเช่นนั้นทั้งเสียสละที่ Ironforge และพิพากษาวิญญาณ Terrordale\n\nขั้นต่อไปจะใช้ทั้งการเสียสละและวิจารณญาณอีก เพื่อกู้วิญญาณม้าศึกที่ล้มลง บัดนี้รับใช้ Death Knight ชื่อ Darkreaver" },
    },
    [7641] = { -- The Work of Grimand Elmore
        title = { "26:982855859:811535987", "ผลงานของ Grimand Elmore" },
        objective = { "58:1610304347:858832190", "คุยกับ Grimand Elmore ใน Dwarven District ของ Stormwind" },
        description = { "294:58522613:137749403 N 201:1708111326:1340907783", "หากไม่มีเกราะเหมาะสม ม้าศึกพาลาดินก็ไม่ต่างจากสัตว์บรรทุก เกราะต้องใช้วัสดุดีที่สุด และด้วยสถานการณ์นี้ต้องปรับให้เข้ากับแดนวิญญาณพอด้วย\n\nเริ่มทำเกราะก่อน {name} Grimand Elmore ใน Dwarven District ของ Stormwind เป็นหนึ่งในช่างดีที่สุดที่มีชีวิต งานไม่ถูก แต่เราต้องการคุณภาพ ไปคุยเขา" },
        completion = { "394:1416917304:977118065", "สวัสดี Lord Shadowbreaker ส่งข่าวก่อนว่าเจ้าจะมา ข้ายอมทำเกราะม้าให้ แต่ไม่ถูกและไม่ง่าย ขอชัดเจนตั้งแต่ต้น\n\nข้าพูดได้ และ Grayson จะรับรอง... ไม่มีที่ใดทั่ว Azeroth ทำเกราะม้าดีกว่าที่นี่" },
    },
    [7642] = { -- Collection of Goods
        title = { "19:615304804:1069074601", "รวบรวมสิ่งของ" },
        objective = { "154:1877863468:2123603324", "นำ Runecloth 40 ชิ้น, Arcanite Bars 6 แท่ง, Arthas' Tears 10 ชิ้น, Stratholme Holy Water 5 ขวด และ 150 โกลด์ไปให้ Grimand Elmore ใน Dwarven District ของ Stormwind" },
        description = { "493:1967664441:1829416835", "เกราะม้าต้องใช้สี่อย่าง Runecloth บุด้านใน แท่ง Arcanite ทำแผ่นเกราะ Arthas' Tears ปรับเข้ากับวิญญาณ และน้ำมนต์ Stratholme ใส่พลังวิญญาณ ที่จริงห้าอย่าง... โกลด์เป็นค่าจ้าง รวมค่าแรง อานทำมือ และโกลนทั้งหมด\n\nเมื่อได้ครบจะทำเสร็จ ระหว่างเจ้ารวบรวม ข้าเริ่มบางส่วนก่อนได้" },
        progress = { "4:1110228981:147916455 C 109:216634843:19417951", "อา {class} หากไม่มีของที่บอก ข้าทำเกราะม้าให้เสร็จไม่ได้ รวบรวมครบหรือยัง?" },
        completion = { "74:1762352094:1276165899 C 73:905146033:348449605", "นี่... ใช่ ตรงสิ่งที่ต้องการ เจ้าเป็น{class}ที่มีวิธีหาของจริงสินะ?\n\nได้ มาทำเกราะม้าให้เสร็จ!" },
        required = { [8836] = { "13:588229817:456656669", "หยาดน้ำตาของ Arthas" }, [12360] = { "12:582063918:1116898133", "แท่งอาร์คาไนต์" }, [13180] = { "21:1808788802:870975348", "น้ำศักดิ์สิทธิ์แห่ง Stratholme" }, [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        objectiveLabels = {
            item = { ["Arthas' Tears"] = "หยาดน้ำตาของ Arthas", ["Arcanite Bar"] = "แท่งอาร์คาไนต์", ["Stratholme Holy Water"] = "น้ำศักดิ์สิทธิ์แห่ง Stratholme", ["Runecloth"] = "ผ้ารูน" },
        },
    },
    [7643] = { -- Ancient Equine Spirit
        title = { "21:1595770769:12865707", "วิญญาณม้าโบราณ" },
        objective = { "365:1856926704:1317469399", "หาอาหารพิเศษสำหรับม้าวิญญาณ ดูเหมือน Merideth Carlson ที่ Southshore จะเป็นแหล่งอาหารนั้น\n\nไปดันเจียน Dire Maul ใน Feralas ฆ่า Tendris Warpwood เพื่อปลดปล่อย Ancient Equine Spirit ให้อาหารพิเศษเพื่อปลอบวิญญาณให้สงบ สุดท้ายมอบ Arcanite Barding เพื่อให้มันอวยพร" },
        description = { "233:724656434:975203500 N 242:432051812:1350809520", "เกราะม้าต้องรับพรพิเศษจากวิญญาณที่เหมาะ Ancient Equine Spirit ใน Dire Maul คือวิญญาณเช่นนั้น ตอนนี้ถูกทรีแอนต์แปดเปื้อน Tendris Warpwood กักไว้ จงพิพากษาสัตว์โสมมนี้ {name}\n\nรู้ไว้ว่าอิสระอย่างเดียวไม่พอ ต้องปลอบวิญญาณก่อนรับพร จึงต้องมีอาหารม้าพิเศษ ไป Southshore คุยกับ Merideth Carlson ก่อน... และเตรียมเสียสละเพิ่ม" },
        progress = { "90:988079811:234494239", "Ancient Equine Spirit มองอย่างคาดหวัง ราวกับต้องการบางสิ่งจากเจ้า" },
        completion = { "292:235189486:1759541396", "Ancient Equine Spirit รับ Manna-Enriched Horse Feed เอาจมูกดุนภาชนะแล้วกินข้าวโอ๊ตกับธัญพืชพิเศษ หลังจากกินเล็กน้อย มันมองเกราะม้าที่เจ้าถือ และจัดท่าเหมือนอยากให้วางบนหลัง..." },
        required = { [18775] = { "25:1098678359:872946794", "อาหารม้าผสมมานนา" } },
        objectiveLabels = {
            item = { ["Manna-Enriched Horse Feed"] = "อาหารม้าผสมมานนา" },
        },
    },
    [7644] = { -- Blessed Arcanite Barding
        title = { "24:946410299:225895454", "เกราะม้า Arcanite รับพร" },
        objective = { "110:51077987:1180815894", "นำ Blessed Arcanite Barding กลับไปให้ Lord Grayson Shadowbreaker ใน Cathedral District ของ Stormwind" },
        description = { "374:1268979840:187213005", "เมื่อเกราะอยู่บนหลัง Ancient Equine Spirit มันเรืองเล็กน้อย อากาศอัดแน่นพลังชั่วครู่ แล้วเกราะหายจากหลังม้า มาอยู่ปลอดภัยในกระเป๋าเจ้า\n\nดูเหมือนได้รับพรแล้ว ตามคำสั่ง Lord Shadowbreaker ควรนำกลับให้เขาที่ Stormwind" },
        progress = { "N 158:1454178639:565353616", "{name} กลับมาแล้ว! จัดการ Merideth Carlson กับ Tendris Warpwood สำเร็จไหม? จริง ๆ บางครั้งข้าไม่แน่ใจว่าใครเป็นภัยมากกว่า..." },
        completion = { "358:754331148:378248083 N 88:1723668389:1733565813", "มาไกลแล้ว สหาย เกราะม้าเตรียมเหมาะกับงานสุดท้ายแล้ว\n\nจะใช้เกราะนี้ควบคุมม้าศึกเมื่อไถ่คืนสำเร็จ แต่ก่อนนั้นต้องผ่านศึกใหญ่ ถึงเวลาใกล้เข้ามาแล้ว ไชโย!\n\nยังต้องสร้างของอีกชิ้นก่อนเริ่ม {name} หวังว่าความสามารถหาของยังไม่หายไปตั้งแต่ทำเกราะม้า..." },
    },
    [7645] = { -- Manna-Enriched Horse Feed
        title = { "25:1098678359:872946794", "อาหารม้าเสริม Manna" },
        objective = { "291:239758457:2032234900", "นำ Enriched Manna Biscuits 20 ชิ้น วัตถุดิบหลักทำ Manna-Enriched Horse Feed ไปให้ Merideth Carlson ที่ Southshore ใน Hillsbrad Foothills ทราบว่า Argent Dawn เป็นผู้ขายรายเดียว\n\nต้องให้ 50 โกลด์เพื่อปลอบความขุ่นเคืองของนางด้วย" },
        description = { "484:1426120139:98277949", "Silver Hand คิดว่าข้าบ้าเมื่อบอกว่าทำอาหารเลี้ยงม้าวิญญาณได้ ทุกคนคิดว่าบ้า! ทีนี้ถึงเวลาเอาคืน!\n\nข้าจะทำให้ พาลาดิน... ที่เรียกตัวว่าผู้กล้า... แต่ต้องจ่าย ต้องใช้ Enriched Manna Biscuits ที่ขายเฉพาะ Argent Dawn ผสม และข้าเรียกร้อง ใช่ เรียกร้องโกลด์ชดเชยความทุกข์ที่ทนมา!\n\nแสดงการเสียสละที่โอ้อวดนักสิ พาลาดิน" },
        progress = { "95:1748441410:798664383", "ใช่ ข้าพิสูจน์ว่าเจ้าผิดแล้วสินะ? พิสูจน์ว่าทุกคนผิด! ข้าถูกมาตลอด!!!" },
        completion = { "240:572372120:661842719 N 105:1987062783:377799521 C 95:840660632:1393393618", "ใช่ ทีนี้ใคร... เดี๋ยว ให้โกลด์ด้วยหรือ? เจ้าไม่ใช่คนว่าข้าบ้า ที่จริงพวกนั้นเรียกข้าคนเพี้ยนสติหลุด... แต่ยังยอมเสียสละแม้เพื่อความผิดที่ไม่ได้ก่อ?\n\nข้า... ตัดสินเจ้าผิด {name} หากต้องการอาหารม้าเพิ่ม มาหา จะให้ฟรี ขอบใจ... {class}ผู้สูงส่ง\n\nแต่ข้าจะเก็บเงินไว้ ไม่บ้าพอทิ้งทรัพย์มากอย่างนี้หรอก" },
        required = { [13724] = { "22:548969929:511010248", "บิสกิตเสริมมานนา" } },
        objectiveLabels = {
            item = { ["Enriched Manna Biscuit"] = "บิสกิตเสริมมานนา" },
        },
    },
    [7646] = { -- The Divination Scryer
        title = { "21:498146847:74165471", "เครื่องทำนาย Divination Scryer" },
        objective = { "126:345884148:109886620", "นำ Azerothian Diamond และ Pristine Black Diamond ไปให้ Lord Grayson Shadowbreaker ใน Cathedral District ของ Stormwind" },
        description = { "504:1458001040:117600253", "ต้องประกอบ Divination Scryer เพื่อเริ่มบททดสอบไถ่คืนม้าศึกที่ล้มลง ที่จริงเครื่องแทบเสร็จแล้ว กระถางขับวิญญาณจาก Terrordale เป็นตัวเร่ง ข้าจะทำเรือนอุปกรณ์ที่เหมาะ\n\nส่วนสุดท้ายคือเพชรสองชนิด ทั้งประกายและหน้าที่ต้องตัดกัน Azerothian กับ Pristine Black ทั้งคู่จะเป็นประทีปให้เครื่องทำนายทะลวงเงามืด!" },
        progress = { "27:1660452996:396760527 N 149:971689754:256042870", "มาไกลมากแล้ว {name} การเสียสละสิ่งของทางโลกครั้งสุดท้ายจะเป็นกำเนิดหนึ่งในความสำเร็จยิ่งใหญ่ที่สุด ข้าสัมผัสได้ทั่วทุกอณู!" },
        completion = { "26:769417548:1087670994 N 382:303343234:677186795 N 68:123565728:906123736", "ตัวอย่างชั้นดี {name} ชิ้นสุดท้ายครบแล้ว ในที่สุดถึงเวลา!\n\nลึกใน Great Ossuary แห่ง Scholomance มีโครงกระดูกมากมาย รวมม้าศึกที่เคยสูงส่ง วิญญาณว่างเปล่ารับใช้เป็นพาหนะ Death Knight Darkreaver เขาคือผู้ที่ต้องเผชิญ และม้าคือผู้ที่ต้องพิพากษา มีเพียงเจ้า {name} ที่ไถ่คืนวิญญาณและช่วยจากความทรมานแห่งทาสได้" },
        required = { [12800] = { "18:1398536143:412119698", "เพชรแห่ง Azeroth" }, [18335] = { "22:140138788:1102101996", "เพชรดำไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Azerothian Diamond"] = "เพชรแห่ง Azeroth", ["Pristine Black Diamond"] = "เพชรดำไร้ตำหนิ" },
        },
    },
    [7647] = { -- Judgment and Redemption
        title = { "23:541720632:1105083661", "การพิพากษาและไถ่คืน" },
        objective = { "370:224053200:1462310121", "ใช้ Divination Scryer ใจกลางห้องใต้ดิน Great Ossuary ใน Scholomance เพื่อเรียกวิญญาณที่ต้องพิพากษา ปราบวิญญาณแล้วจะเรียก Death Knight Darkreaver ปราบเขาและกู้วิญญาณที่สูญของม้าศึก\n\nมอบ Charger's Redeemed Soul และ Blessed Enchanted Barding ให้ Darkreaver's Fallen Charger" },
        description = { "397:1843143003:284873379 N 86:1370406324:2063022474", "รับถุงนี้ ข้างในมีของจำเป็น\n\nใช้ Divination Scryer ใจกลางห้องใต้ดิน Great Ossuary เรียกวิญญาณต้องสาปที่ต้องพิพากษา ใช้ Judgments อย่างชาญฉลาดในบททดสอบ มันทรงพลังกว่าที่คิด หลังวิญญาณ Death Knight จะปรากฏ ปราบแล้วกู้วิญญาณม้า เมื่อนั้นเท่านั้น {name} จึงไถ่คืนและวางเกราะบนพาหนะใหม่ได้!\n\nโชคดี!" },
        progress = { "140:2080439706:462742550", "วิญญาณม้าศึกที่ล้มลงมองเศร้าสร้อย ดวงตาเศร้าแทบว่างเปล่ามองราวกับสิ้นหวังทั้งหมด" },
        completion = { "455:1855065958:1468096575 C 18:86733953:1457680573", "ประกายชีวิตที่หายไปนานส่องในตาม้าน่าสงสารเมื่อส่งวิญญาณที่ผ่านการพิพากษาคืน เจ้ารู้สึกพลังศักดิ์สิทธิ์พุ่งรอบกายขณะวางเกราะบนหลัง ตัดสินแล้วว่าม้าได้รับการไถ่คืน ม้าดุนมือขณะภาระอดีตถูกยกออก ทีนี้รู้สึกว่าสามารถเรียกให้เป็นพาหนะเมื่อจำเป็น\n\nเจ้าได้ม้าศึกระดับมหากาพย์แล้ว {class}! ยินดีด้วย!" },
        required = { [18799] = { "23:1646170986:2070530861", "วิญญาณม้าศึกที่ได้รับการไถ่บาป" }, [18792] = { "24:946410299:225895454", "เกราะม้าอาร์คาไนต์ที่ผ่านการอวยพร" } },
        objectiveLabels = {
            item = { ["Charger's Redeemed Soul"] = "วิญญาณม้าศึกที่ได้รับการไถ่บาป", ["Blessed Arcanite Barding"] = "เกราะม้าอาร์คาไนต์ที่ผ่านการอวยพร" },
        },
    },
    [7648] = { -- Grimand's Finest Work
        title = { "21:1169657351:187451926", "ผลงานชั้นยอดของ Grimand" },
        objective = { "109:1096365716:688776552", "นำ Arcanite Barding ให้ Lord Grayson Shadowbreaker ใน Cathedral District ของ Stormwind ตรวจสอบ" },
        description = { "427:339872994:148466876", "<Grimand ปาดเหงื่อจากคิ้ว ยิ้มภูมิใจ>\n\nเสร็จแล้ว สหาย นี่หนึ่งในผลงานดีที่สุด ดีเท่าเกราะที่ข้าทำให้ Lord Shadowbreaker ตอนไปหาม้าศึก ขอบใจที่ไว้ใจให้ข้าจัดหาสิ่งดีที่สุด\n\nGrayson คงอยากเห็นด้วยตนเอง นำเกราะไป พร้อมฝากขอบคุณที่อุดหนุนอย่างมีเกียรติ" },
        progress = { "33:852321415:370014861 N 79:963655187:769946982", "ก้าวหน้าดี {name} เมื่อทำเกราะม้าแล้ว ก็ใกล้ถึงงานต่อไป" },
        completion = { "440:2119713723:1986498966 C 49:1672648822:1458801862", "ผลงานน่าประทับใจ ยิ่ง Grimand แก่ ฝีมือยิ่งดี น่าทึ่งเมื่อครั้งทำเกราะข้า เขาก็เป็นหนึ่งในผู้ฝีมือดีที่สุดอยู่แล้ว\n\nแม้เป็นเกราะชั้นดีสำหรับม้าธรรมดา แต่เราไม่ได้รับมือสัตว์ธรรมดา ต้องรับพรจากแหล่งเหมาะสมจึงคู่ควรบนม้าศึกของ{class} ข้าจะเก็บไว้ให้จนกว่านั้น" },
    },
    [7666] = { -- Again Into the Great Ossuary
        title = { "28:1561423313:1835199818", "สู่ Great Ossuary อีกครั้ง" },
        completion = { "42:338429609:1672519190 N 253:1566619826:1688564022", "จะกลับ Scholomance หรือ {name}? จ่ายราคามากเพื่อใช้ Divination Scryer แล้ว บางทีอยากนำอีกเครื่องไป เพื่อเผชิญภัย Great Ossuary อีกครั้ง\n\nเชิญรับ เจ้าสมควรได้แน่นอน" },
    },
    [7670] = { -- Lord Grayson Shadowbreaker
        title = { "26:312903867:1237982410", "Lord Grayson Shadowbreaker" },
        objective = { "72:321861201:103873172", "คุยกับ Lord Grayson Shadowbreaker ใน Cathedral District ของ Stormwind" },
        description = { { "19:1057308443:1361522860 N 417:1633030310:1282741566", "19:1057308443:1361522860 N 415:1267095939:156775926" }, "ถึงเวลาแล้ว {name} ที่จะเรียนรู้ว่าต้องทำสิ่งใดเพื่อได้สิ่งที่รอมานาน... ม้าศึกของเจ้า\n\nคุยกับ Lord Grayson Shadowbreaker ใน Cathedral District ของ Stormwind เขาจะนำทางทั้งเรื่องวิชาม้าคู่ใจที่สุดของพาลาดิน และงานเพื่อได้ม้าของตน\n\nขอให้ผ่านบททดสอบได้ดี เพื่อแสง พี่น้องผู้สูงส่ง!", variants = { { "19:1057308443:1361522860 N 416:1777819314:1091730238", "ถึงเวลาแล้ว {name} ที่จะเรียนรู้ว่าต้องทำสิ่งใดเพื่อได้สิ่งที่รอมานาน... ม้าศึกของเจ้า\n\nคุยกับ Lord Grayson Shadowbreaker ใน Cathedral District ของ Stormwind เขาจะนำทางทั้งเรื่องวิชาม้าคู่ใจที่สุดของพาลาดิน และงานเพื่อได้ม้าของตน\n\nขอให้ผ่านบททดสอบได้ดี เพื่อแสง พี่น้องผู้สูงส่ง!" } } },
        completion = { "21:1838430250:1482072818 N 466:204272369:537604571", "ดีใจที่เห็น {name} รอข่าววิธีได้ม้าศึกสินะ บัดนี้ถึงเวลาแล้ว\n\nเจ้าจะถูกทดสอบหลายด้าน ที่สำคัญที่สุดคือใจที่จะก้าวเหนืออุปสรรคมากมาย นี่ไม่ใช่แบบฝึกหัดเรียนรู้ ฐานะเจ้าพ้นบททดสอบง่าย ๆ แล้ว เจ้าต้องช่วยสหายในอนาคตจากเงื้อมมือชั่วร้ายที่ต่อสู้มาตลอดชีวิต\n\nจงฟัง ถึงเวลาแล้ว!" },
    },
    [8414] = { -- Dispelling Evil
        title = { "15:2041440230:2056618867", "ขจัดความชั่วร้าย" },
        objective = { "102:1569148471:1125241004", "รวบรวม Minion's Scourgestones 20 ชิ้นไปให้ High Priest Thel'danis ใน Western Plaguelands" },
        description = { "11:927657569:725753248 C 444:410723361:85827826", "สวัสดี {class} เห็นนักรบครูเสดเช่นเจ้าแล้วยินดีในแดนร้างนี้\n\nเราต้องใช้กำลังศักดิ์สิทธิ์สู้กับอันเดดไม่สิ้นสุด รวบรวมหิน Scourgestone จำนวนมากไปให้ High Priest Thel'danis เขาเฝ้า Uther's Tomb ที่ Sorrow Hill ไม่ไกล\n\nมีแต่ผู้ถือ Argent Dawn Commission จึงหวังพบหินได้ หากยังไม่ได้คุย จงหา Officer Pureheart" },
        progress = { "30:1749978474:1299228702", "นำความชั่วร้ายใดมาให้ข้า?" },
        completion = { "152:489134736:441931793 N 30:2065803888:195081455", "การขจัดชั่วร้ายจาก Scourgestone เสี่ยง เพราะดึงความสนใจอันเดดไกลนับไม่ถ้วน แต่เจ้าเข้มแข็งในแสง {name} ข้าไม่กลัวแทนเจ้า..." },
        required = { [12840] = { "21:1430951278:1059279595", "ศิลา Scourge ของสมุน" } },
        objectiveLabels = {
            item = { ["Minion's Scourgestone"] = "ศิลา Scourge ของสมุน" },
        },
    },
    [8415] = { -- Chillwind Point
        title = { "15:1086210112:1737417999", "Chillwind Point" },
        objective = { "54:2051994356:1787847933", "คุยกับ Commander Ashlam Valorfist ที่ Chillwind Camp", variants = { { "55:700946:1121057734", "คุยกับ Commander Ashlam Valorfist ที่ Chillwind Point" } } },
        description = { "87:174920025:1979618205 N 131:932798773:837048821", "Commander Ashlam Valorfist เรียกหาพาลาดินบริสุทธิ์และกล้าหาญเช่นเจ้า {name} พบเขาได้ที่ Chillwind Point ทางใต้ของ Western Plaguelands ไปช่วยอุดมการณ์แห่งแสง!" },
        completion = { "11:1598769728:2013240452 C 32:1076944887:1945781831", "ดีมาก {class}! มาดูฝีมือกัน" },
    },
    [8416] = { -- Inert Scourgestones
        title = { "19:1875027822:579832233", "หิน Scourgestone ไร้ฤทธิ์" },
        objective = { "78:808880360:295201668", "นำ Inert Scourgestone ไปให้ Commander Ashlan Valorfist ที่ Chillwind Point" },
        description = { "42:384256724:695793762 N 151:1800261728:1067455114", "ชั่วร้ายถูกชำระจากหินแล้ว {name}\n\nข้ารู้แผน Commander Ashlam เขาต้องการหินไร้ฤทธิ์เพียงชิ้นเดียว นำไปให้ เพื่อเราจะชำระ Scourge ด้วยไฟชอบธรรม" },
        progress = { "49:1701902647:1998576031", "Thal'danis ชำระ Scourgestone ได้ไหม?" },
        completion = { "43:525691392:1980489324 N 87:64418544:884203008", "เจ้าทำตามโดยไม่กังขา {name}\n\nดูเหมือนเกิดความไว้ใจแล้ว บางทีข้าเปิดเผยแผนละเอียดขึ้นได้" },
    },
    [8418] = { -- Forging the Mightstone
        title = { "22:1845377585:921288196", "หลอม Mightstone" },
        objective = { "46:2062923760:1666397313", "นำ Voodoo Feathers ไปให้ Ashlam Valorfist" },
        description = { "121:1694816332:645250515 N 278:263783950:557542394", "ทีนี้ต้องรวมหิน Scourgestone ไร้ฤทธิ์สร้างอาวุธทำลายแนวอันเดด ไม่ใช่งานเล็ก {name} มีแต่โทรลล์วิหารจมที่ถือเวทหายากแบบเปลี่ยนความชั่วร้ายย้อนทำลายตัวมันเอง\n\nโทรลล์ในวิหารชื่อ Gasher, Mijan, Zolo, Hukku, Zul'lor และ Loro อย่าเสียใจต่อวิญญาณแปดเปื้อน พวกมันไม่ใช่ไร้ชั่วร้าย" },
        progress = { "35:1833578855:1515559502", "ฆ่าโทรลล์ชั่วร้ายแล้วหรือ?" },
        completion = { "19:30849056:1815428005 N 162:1874775344:1560112863", "ยอดเยี่ยม {name} ข้าคงบอกว่าแปลกใจ แต่รู้แน่ว่าไม่ทำให้ผิดหวัง\n\nเป็นเกียรติมอบ Holy Mightstone ให้หนึ่งชิ้น ใช้ให้ดี" },
        required = { [20606] = { "20:116773895:110391659", "ขนนกวูดูสีอำพัน" }, [20607] = { "19:47936181:1879616036", "ขนนกวูดูสีน้ำเงิน" }, [20608] = { "20:1196264854:1089628285", "ขนนกวูดูสีเขียว" } },
        objectiveLabels = {
            item = { ["Amber Voodoo Feather"] = "ขนนกวูดูสีอำพัน", ["Blue Voodoo Feather"] = "ขนนกวูดูสีน้ำเงิน", ["Green Voodoo Feather"] = "ขนนกวูดูสีเขียว" },
        },
    },
    [78088] = { -- A Strange Artifact
        title = { "18:1853387937:28115019", "วัตถุประหลาด" },
        objective = { "79:1374883388:1885624799", "นำ Althalaxx Orb ไปให้ Delgren the Purifier ที่ Maestra's Post ใน Ashenvale" },
        description = { "365:701816374:1250492332", "<ลูกแก้วลึกลับในมือทำให้เจ้าหวาดหวั่นเย็นเยียบ แทบได้ยินเสียงก้องแผ่วในใจ ต่ำและลึกในลำคอ เจ้ารู้ดีว่าภาษานั้นเป็นภาษาปีศาจ\n\nแม้เป็นพาลาดิน เวทนี้ก็เกินความรู้ จงหาพาลาดินอาวุโสใน Kalimdor ที่อาจช่วยแยกลักษณะวัตถุร้ายนี้>", variants = { { "338:884432907:1584364148", "<ลูกแก้วลึกลับในมือทำให้เจ้าหวาดหวั่นจนเย็นเยียบ เจ้าคล้ายได้ยินเสียงต่ำแหบพร่าดังก้องแผ่ว ๆ อยู่ในใจ และรู้ดีว่านั่นเป็นภาษาปีศาจ\n\nแม้เจ้าจะเป็นพาลาดิน เวทมนตร์นี้ก็ยังเกินความเข้าใจของเจ้า Delgren the Purifier อาจช่วยบอกได้ว่าวัตถุอัปมงคลนี้คืออะไร>" } } },
        progress = { "36:794741746:1297582737", "เจ้าพบอะไรในหอคอยหรือ?" },
        completion = { "36:1587958775:1866725496 N 1:46:46", "เจ้าทำถูกแล้วที่เอาสิ่งนี้มาให้ข้า {name}" },
        required = { [209836] = { "13:1665877643:1933598625", "ลูกแก้วแห่ง Althalaxx" } },
        steps = { { "13:1665877643:1933598625", "ลูกแก้วแห่ง Althalaxx" } },
    },
    [78089] = { -- Advice From Stormwind
        title = { "21:1332971747:1009699952", "คำแนะนำจาก Stormwind" },
        objective = { "59:847428961:1351682181", "นำ Althalaxx Orb ไปให้ Katherine the Pure ใน Stormwind" },
        description = { "256:471132490:950939268", "ลูกแก้วมีความมืดทรงพลัง ชัดว่าเกี่ยวกับปีศาจ แต่นอกนั้นข้าแยกจุดประสงค์ไม่ได้\n\nนำไปให้ Katherine the Pure ในมหาวิหาร Stormwind ปรึกษานางเรื่องลูกแก้ว" },
        progress = { "29:764187597:237568776", "เจ้านำข่าวจาก Kalimdor มาหรือ" },
        completion = { "44:214560:171031121", "<ตรวจดูลูกแก้วด้วยสีหน้ากังวล>" },
        required = { [209748] = { "13:1665877643:1933598625", "ลูกแก้วแห่ง Althalaxx" } },
        steps = { { "13:1665877643:1933598625", "ลูกแก้วแห่ง Althalaxx" } },
    },
    [78090] = { -- A Second Opinion
        title = { "16:1425912616:1067760708", "ความเห็นที่สอง" },
        objective = { "69:1907455905:1686320327", "หาที่พำนักวอร์ล็อกใน Stormwind แล้วขอคำแนะนำเรื่องลูกแก้ว" },
        description = { "39:2071559285:874873844 N 323:1035134194:302328164", "ไม่แน่ใจว่าควรคิดอย่างไรกับลูกแก้ว {name} เราคงต้องให้... ผู้เชี่ยวชาญช่วย\n\nเรารู้ว่ามีลัทธิวอร์ล็อกทำงานใน Stormwind ทางการเราไม่ยอมรับพวกเขาในเมือง แต่ไม่เป็นทางการ ความรู้อาจมีประโยชน์ต่อการรับมือปีศาจ\n\nหาตัวแทนวอร์ล็อกเหล่านี้ ขอความเห็นเรื่องลูกแก้ว" },
        progress = { "38:305589994:1400591447 C 48:420808108:707108560", "เจ้ามาไกลจากมหาวิหารทีเดียว {class} หวังว่าเจ้าจะรู้ว่าที่นี่เจ้าไม่มีอำนาจ" },
        completion = { "61:62842446:821492169", "ถึงขั้นที่ Silver Hand ต้องมาขอแรงข้าเชียวหรือ งานนี้ข้าคิดราคาแพงแน่" },
        required = { [209748] = { "13:1665877643:1933598625", "ลูกแก้วแห่ง Althalaxx" } },
        steps = { { "13:1665877643:1933598625", "ลูกแก้วแห่ง Althalaxx" } },
    },
    [78091] = { -- Earning Your Salt
        title = { "17:458132782:351849561", "พิสูจน์คุณค่าด้วยเกลือ" },
        objective = { "117:2049851966:1491916808", "รวบรวม Summoner's Salt 14 ชิ้นจาก Blackrock Summoners ใน Redridge Mountains แล้วกลับไปหา Ursula Deline ใน Stormwind" },
        description = { "293:2026028728:343665169", "ข้าจะศึกษาลูกแก้วแล้วบอกสิ่งที่พบ แต่ต้องทำบางอย่างให้ก่อน\n\nวอร์ล็อก Blackrock ใช้เกลือเตรียมพิเศษเสริมพิธีอัญเชิญ รวบรวมจากออร์คใน Redridge\n\nเมื่อกลับมาจะบอกผลการศึกษา" },
        progress = { "42:1621358576:1304137049", "<วอร์ล็อกกำลังพินิจลูกแก้วอย่างตั้งใจ>" },
        completion = { "90:1192589669:1517900083 N 1:46:46", "อา... เกลือนั่นเอง ข้าลืมไปเสียสนิท\n\nลูกแก้วนี้ไม่เหมือนสิ่งใดที่ข้าเคยเห็นเลย {name}" },
        required = { [209778] = { "15:727980556:912989386", "เกลือสำหรับอัญเชิญ" } },
        steps = { { "15:727980556:912989386", "เกลือสำหรับอัญเชิญ" } },
    },
    [78092] = { -- It Must Be Destroyed
        title = { "20:1692330746:298268958", "มันต้องถูกทำลาย" },
        objective = { "145:999704846:2042843178", "รวบรวม Motes of Mannoroth 12 ชิ้นจากปีศาจใน Ashenvale นำไปพร้อม Orb of Althalaxx ที่ Spear of Mannoroth ใน Demon Fall Canyon" },
        description = { "163:1685617288:69253613 N 326:650665312:2083482687", "สายใยความรู้สึกนึกคิดที่แผ่จากลูกแก้วมากเกินแม้แต่วอร์ล็อกมีประสบการณ์อย่างข้าจะทนได้นาน ไม่อยากยอมรับ {name} แต่มันต้องถูกทำลาย\n\nลูกแก้วแทบไม่อาจทำอันตราย แต่อาจแพ้อาวุธจ้าวปีศาจทรงพลัง ได้ยินว่ามีคมอาวุธเช่นนั้นใน Ashenvale ที่ซึ่งพิทลอร์ด Mannoroth ถูกทำลาย\n\nรวบรวมเศษแก่นพลังปีศาจที่ล้มลง แล้วทุบลูกแก้วบนคมอาวุธ" },
        progress = { "59:911341535:1800325600", "<ขนเจ้าลุกชันเมื่อพลังนรกแผ่ล้อมตัว>" },
        completion = { "37:572700700:1603570680", "<เจ้ายกลูกแก้วขึ้นจ่อหอก>" },
        required = { [209779] = { "17:54912158:1435926939", "ละอองพลังของ Mannoroth" }, [209748] = { "13:1665877643:1933598625", "ลูกแก้วแห่ง Althalaxx" } },
        steps = { { "17:54912158:1435926939", "ละอองพลังของ Mannoroth" }, { "13:1665877643:1933598625", "ลูกแก้วแห่ง Althalaxx" } },
    },
    [78093] = { -- Return to Delgren
        title = { "17:2139397164:1053435827", "กลับไปหา Delgren" },
        objective = { "33:355166788:1910532406", "นำ Orb Shards กลับไปให้ Delgren" },
        description = { "97:790744756:1143453415", "<เศษลูกแก้วแตกอยู่แทบเท้า Delgren คงอยากเห็นว่าเจ้าทำสำเร็จ>" },
        progress = { "38:419290647:1395372210", "เจ้าหาวิธีทำลายลูกแก้วได้หรือยัง?" },
        completion = { "18:1838994939:178217371 N 173:136406755:1337999371", "โล่งอกไปที {name} แต่ไม่ว่าอะไรที่เฝ้ามอง Azeroth ผ่านลูกแก้วนั่น ข้าว่ามันคงไม่พอใจที่ลูกแก้วถูกทำลาย\n\nรับนี่ไว้แทนคำขอบคุณสำหรับความช่วยเหลือของเจ้า แล้วก็... ระวังตัวด้วย" },
        required = { [209800] = { "13:1260742452:1175383544", "เศษลูกแก้ว" } },
        steps = { { "13:1260742452:1175383544", "เศษลูกแก้ว" } },
    },
    [90902] = { -- Rediscovering the Light
        title = { "23:1843816074:1269147212", "ค้นพบแสงอีกครั้ง" },
        objective = { "55:936354723:1791683721", "ใช้ Holy Light รักษา Injured Deathguard 5 คน", amount = { "5:138641197:2105377639 W1 49:701460718:1647713233", "ใช้ Holy Light รักษา Injured Deathguard {world1} คน" } },
        description = { "501:606218019:979089026", "ข้าภูมิใจต้อนรับพาลาดินผู้เพิ่งฟื้นขึ้นอีกคน เมื่อเริ่มเชื่อมกับแสงใหม่ อาจพบว่าความสามารถที่เคยเป็นธรรมชาติกลับเจ็บปวดเมื่อใช้ โดยเฉพาะรวมแสงรักษาตนหรือผู้อื่น\n\nน่าเสียดาย ทางเดียวผ่านปัญหาคือต้องเผชิญมัน เหมือนกล้ามเนื้อลีบ ต้องฝ่าความเจ็บและฝึกกายจึงกลับทำงานเต็มที่" },
        progress = { "42:1239086158:1664430138", "ความชำนาญแสงจะกลับมาเมื่อถึงเวลา" },
        completion = { "336:766402990:312155758", "ความเจ็บไม่ใหม่สำหรับผู้ผ่านความตาย Forsaken จึงทนได้เป็นพิเศษ มันมีคุณสมบัติชำระด้วย จงถือเป็นตราเกียรติและหลักฐานว่ายังรับใช้แสง แม้สภาพใหม่\n\nจงอยู่ดี และเดินในแสงอีกครั้ง พาลาดิน", variants = { { "328:478003777:356255241 C 1:46:46", "ความเจ็บไม่ใหม่สำหรับผู้ผ่านความตาย Forsaken จึงทนได้เป็นพิเศษ มันมีคุณสมบัติชำระด้วย จงถือเป็นตราเกียรติและหลักฐานว่ายังรับใช้แสง แม้สภาพใหม่\n\nจงอยู่ดี และเดินในแสงอีกครั้ง {class}" } } },
        steps = { { "25:195447200:2012897226", "รักษา Deathguard ที่บาดเจ็บ" } },
    },
    [91208] = { -- Coming to Terms
        title = { "15:1779674671:1397460864", "ยอมรับความจริง" },
        objective = { "42:257082423:150102677", "หา Frightened Paladin ใน Deathknell" },
        description = { "481:2110658261:1439638280", "พาลาดินร่วมทางที่ฟื้นขึ้นไม่ได้ปรับตัวกับความจริงใหม่เร็วทุกคน บางคนยอมรับยากว่าบัดนี้กลายเป็นสิ่งที่เคยต่อสู้มาตลอดชีวิตในทางหนึ่ง\n\nพวกเขามักเพียงต้องการไมตรีและคนรับฟัง แต่น่าเสียดายอีกมากใช้ความรุนแรง จงหาพาลาดินหวาดกลัวที่หนีขึ้นเนินตรงตะวันตกของโบสถ์นี้ ยื่นมือเป็นมิตร นำกลับสู่แสงหากทำได้" },
        progress = { "107:1201272591:479612608", "ยอมรับชีวิตใหม่นี้ไม่ง่ายสำหรับใคร บางคนทนไม่ไหวจริง ๆ" },
        completion = { "310:855931941:1997069682", "น่าเศร้าที่พี่น้องไม่น้อยแพ้ความบ้าคล้ายกันหลังฟื้น แม้วิญญาณ Forsaken ทุกตนมีค่า บางครั้งสิ่งดีที่สุดคือให้ผู้ปรับตัวไม่ได้จากไปอย่างหมดจด\n\nข้าจะสวดต่อแสงเพื่อนาง ขอบใจที่ทำสิ่งจำเป็น สหาย", variants = { { "303:2032578808:1004567166 N 1:46:46", "น่าเศร้าที่พี่น้องไม่น้อยแพ้ความบ้าคล้ายกันหลังฟื้น แม้วิญญาณ Forsaken ทุกตนมีค่า บางครั้งสิ่งดีที่สุดคือให้ผู้ปรับตัวไม่ได้จากไปอย่างหมดจด\n\nข้าจะสวดต่อแสงเพื่อนาง ขอบใจที่ทำสิ่งจำเป็น {name}" } } },
        steps = { { "35:987986471:1503313570", "เสนอความช่วยเหลือให้พาลาดินที่กำลังหวาดกลัว" } },
    },
    [91209] = { -- Continue Your Training
        title = { "22:1634387676:974724210", "ฝึกฝนต่อไป" },
        objective = { "117:1508751197:1022139151", "ตามถนนตะวันออกจาก Deathknell ไปเมือง Brill รายงานตัวกับ Shari Stilwell เพื่อฝึกต่อ" },
        description = { "496:519665774:839243097", "Lordaeron อาจไม่เหมือนเดิม แต่บ้านยังต้องปกป้องภัยทุกรูปแบบ ถึงเวลาออกเผชิญโลก จุดต่อไปคือ Brill กลาง Tirisfal Glades ไปพบ Shari Stilwell นางดูแลการฝึกต่อได้\n\nคำแนะนำสุดท้าย ระวังเป็นพิเศษเมื่อเป็นพาลาดินเดินทางในแดน Forsaken ผู้รับใช้ Dark Lady มากมายไม่ไว้ใจเราและความใกล้ชิดกับแสง" },
        completion = { "419:903212932:2074880569", "ยินดีต้อนรับ พาลาดิน เห็นพวกเราเดินในดินแดนนี้เพิ่มแล้วมีกำลังใจ ที่ Brill มีหลายคนต้องการนักผจญภัยช่วย หางานและเข้มแข็งในแสง กลับมาฝึกเมื่อใดก็ได้\n\nเมื่อพิสูจน์ตัวต่อข้าและชาว Brill แล้ว จะชี้ทางช่วงต่อไป\n\nไปกับแสง พาลาดิน", variants = { { "16:986036512:573657706 C 388:1351693425:1277217394 C 1:46:46", "ยินดีต้อนรับ {class} เห็นพวกเราเดินในดินแดนนี้เพิ่มแล้วมีกำลังใจ ที่ Brill มีหลายคนต้องการนักผจญภัยช่วย หางานและเข้มแข็งในแสง กลับมาฝึกเมื่อใดก็ได้\n\nเมื่อพิสูจน์ตัวต่อข้าและชาว Brill แล้ว จะชี้ทางช่วงต่อไป\n\nไปกับแสง {class}" } } },
        steps = { { "33:532283314:1204428291", "ไปรายงานตัวกับ Shari Stilwell ที่ Brill" } },
    },
    [91282] = { -- A Second Home
        title = { "13:499791904:55538278", "บ้านหลังที่สอง" },
        objective = { "71:1236756685:99219977", "หาป้อม Bandarion Keep แล้วรายงานตัวกับ Breton Samuels ที่นั่น" },
        description = { "473:1657808728:621428533", "เห็นพี่น้องเพิ่งฟื้นเติบโตเช่นเจ้าแล้วมีกำลังใจ แต่ชุมชนกับศรัทธาร่วมกันเท่านั้นทำให้บรรลุศักยภาพแท้ เราจึงเริ่มตั้งภาคีพาลาดินใหม่ใน Tirisfal\n\nหากอยากรู้เพิ่ม ไปอารามริม Whispering Woods ชื่อ Bandarion Keep อยู่หน้าผาตะวันตกเฉียงเหนือของ Solliden Farmstead ไม่น่าพลาดสายตา", variants = { { "455:481990827:1150817910", "เห็นพี่น้องเพิ่งฟื้นเติบโตเช่นเจ้าแล้วมีกำลังใจ แต่ชุมชนกับศรัทธาร่วมกันเท่านั้นทำให้บรรลุศักยภาพแท้ เราจึงเริ่มตั้งภาคีพาลาดินใหม่ใน Tirisfal\n\nหากอยากรู้เพิ่ม ไปอารามที่ Northface Rock ชื่อ Bandarion Keep อยู่หน้าผาตะวันตกเฉียงเหนือของ Solliden Farmstead ไม่น่าพลาดสายตา" } } },
        completion = { "55:158490906:300036986", "ทหารใหม่อีกคนหรือ? ยินดีต้อนรับสู่ Tyr's Watch พี่น้อง", variants = { { "58:822116029:1764663833", "ทหารใหม่อีกคนหรือ? ยินดีต้อนรับสู่ Bandarion Keep พี่น้อง" }, { "54:2129815683:560557599", "ทหารใหม่อีกคนหรือ? ยินดีต้อนรับสู่ Tyr's Watch สหายหญิง" } } },
    },
    [91285] = { -- Murlocs at the Gates
        title = { "20:2066903696:1745340196", "เมอร์ล็อกหน้าประตู" },
        objective = { "97:514253276:456704515", "ฆ่า Vile Fin Attackers 8 ตัว และ Vile Fin Seers 8 ตัว แล้วรายงาน Breton Samuels เมื่อเสร็จ", amount = { "5:1000000866:1065647852 W1 24:400066074:1214548752 W2 66:1826503900:1008309278", "ฆ่า Vile Fin Attackers {world1} ตัว และ Vile Fin Seers {world2} ตัว แล้วรายงาน Breton Samuels เมื่อเสร็จ" } },
        description = { "497:1101713070:9754454", "ปกติจะต้อนรับคนใหม่ดีกว่านี้ แต่ตอนนี้มีปัญหาเมอร์ล็อก\n\nเผ่าหนึ่งเคยใช้ป้อมวางไข่ เป็นปัญหาตั้งแต่เราย้ายเข้าไล่ออก ตอนนี้เริ่มคุมไม่อยู่ ดูเหมือนผ่านศึกมา คิดว่าช่วยขับพวกก่อกวนได้ไหม? พบแอบอยู่ตามหน้าผาริมถนนตะวันออก และค่ายรอบทะเลสาบตะวันตก" },
        completion = { "219:1772106725:686803926", "ขอบใจที่ช่วย คงไม่หยุดการโจมตีทั้งหมด แต่หวังว่าชะลอบ้าง แค่บูรณะที่นี่ก็ยากพอ ไม่ต้องมีเมอร์ล็อกเอาหอกแทงหลังด้วย" },
        progress = { "20:1947940143:1828594505", "พวกเมอร์ล็อกนี่นะ! จริงไหมล่ะ" },
        objectiveLabels = {
            monster = { ["Vile Fin Attacker slain"] = "ปราบ ผู้จู่โจม Vile Fin", ["Vile Fin Seer slain"] = "ปราบ ผู้พยากรณ์ Vile Fin" },
        },
    },
    [91294] = { -- Touring the Grounds
        title = { "19:511585451:176230134", "สำรวจบริเวณป้อม" },
        objective = { "41:2014706701:195546628", "คุยกับผู้อาศัยใน Bandarion Keep" },
        description = { "290:584779467:236867275 N 30:159479057:803967978", "เมื่อภัยเมอร์ล็อกเฉพาะหน้าควบคุมได้ อยากให้เดินชมฐานเรา ยังไม่มาก แต่เป็นบ้าน\n\nสำรวจเสร็จหา Danitha Morr ผู้นำ นางช่วยให้เข้าที่ได้\n\nดีใจที่พบ {name} ขอแสงนำทาง" },
        completion = { "377:1347152432:1073065073", "Breton ส่งขึ้นมาหรือ? เยี่ยม\n\nข้าชื่อ Danitha Morr เป็นคนที่ใกล้คำว่าผู้บัญชาการที่สุดของป้อม หากมาหามิตรในหมู่ผู้ยังภักดีต่อแสง มาถูกที่แล้ว\n\nยังมีงานมากก่อนตั้งมั่นได้เต็มที่ จะขอบใจมากหากยอมช่วย" },
        progress = { "27:1508833779:1406784120 C 37:52832980:451129761", "ยินดีต้อนรับสู่ Bandarion Keep {class} ข้าดีใจเสมอที่ได้เห็นหน้าใหม่ ๆ" },
        steps = { { "28:213777970:615948645", "คุยกับ Hilda the Breaker" }, { "22:539440879:1093237957", "คุยกับ Jorin Croge" }, { "25:1627833608:535610622", "คุยกับ Ander Solliden" }, { "23:1221714347:338091764", "คุยกับ Danitha Morr" } },
    },
    [91316] = { -- Making Repairs
        title = { "14:1510745080:1711174444", "ซ่อมแซม" },
        objective = { "70:1103565263:911581397", "รวบรวม Sturdy Lumber 12 ชิ้นจาก Shadowvale ใน Tirisfal Glades" },
        description = { "439:23100906:18208694", "ห่าง Undercity เท่านี้ การส่งกำลังบำรุงท้าทาย เราขาดวัสดุบูรณะป้อมอย่างหนัก อยากให้ช่วย\n\nซากหมู่บ้าน Shadowvale อยู่ Whispering Forest ทางตะวันตกเฉียงใต้ อาคารหนึ่งมีห้องใต้ดินเก่าเก็บของสารพัด น่าจะมีวัสดุใช้ได้ข้างล่าง เก็บเท่าที่ได้แล้วกลับมา" },
        progress = { "230:2100287414:1672184388", "ว่ากันว่าสถานที่สำคัญที่สุด แม้ป้อมบนหน้าผาดูยิ่งใหญ่ แต่จัดเสบียงไกลอารยธรรมเป็นงานยาก เป็นความสะเพร่าที่น่าเสียดายของเรา", variants = { { "229:103876063:1246245938", "ว่ากันว่าสถานที่สำคัญที่สุด แม้ป้อมบนหน้าผาดูยิ่งใหญ่ แต่จัดเสบียงไกลอารยธรรมเป็นงานยาก เป็นความสะเพร่าที่น่าเสียดายของเรา" } } },
        completion = { "201:2048494042:1618691467", "ยินดีที่การไป Shadowvale เกิดผล ภายหลังจะส่ง Breton กับคนใหม่สองสามคนไปเก็บห้องใต้ดินให้หมด นำของที่ยังอยู่ในมืดกลับมา" },
        required = { [246213] = { "13:1924469522:569018732", "ไม้แปรรูปเนื้อแน่น" } },
        steps = { { "13:1924469522:569018732", "ไม้แปรรูปเนื้อแน่น" } },
    },
    [91317] = { -- The Tarnished
        title = { "13:1811867483:1055033523", "ผู้มัวหมอง" },
        objective = { "117:662040635:320219006", "ฆ่า Tarnished Drudges 8 คน, Tarnished Zealots 6 คน และเก็บหัว Commander Rudolph Gelhardt ใน Tirisfal Glades" },
        description = { "504:374276654:2143748788", "พาลาดินฟื้นขึ้นไม่ได้ปรับตัวดีทุกคน เจ้าอาจเห็นเอง บางคนยังมีอคติสมัยมีชีวิต และใช้ความรุนแรงต่อ Forsaken ร่วมเผ่า\n\nผู้คนไม่ไว้ใจเราอยู่แล้ว เพราะจำการข่มเหงของคนเป็นในนามแสง การโจมตียิ่งไม่ช่วย ผู้มัวหมองจำนวนหนึ่งตั้งหลักที่ Shadowvale ทางตะวันตกเฉียงใต้ กำจัดแล้วนำหัวผู้นำมา" },
        progress = { "212:1147145882:2129094289", "ผู้มัวหมองคุกคามไมตรีเล็กน้อยที่มีกับ Forsaken อื่น แม้เจ็บใจต้องประดาบพี่น้องเก่า แต่ต้องหยุดหากภาคีเกิดใหม่จะรอด" },
        completion = { "16:1549935302:71513149 N 445:1817862393:1435731026", "ทำได้ยอดเยี่ยม {name} ทุกครั้งที่พวก Tarnished ลงมือฆ่า Forsaken สักคน พวกที่คอยโจมตีเราก็ยิ่งปลุกปั่นให้คนระแวงพาลาดินอย่างเราได้ง่ายขึ้น การกำจัดพวกมันจะช่วยให้เป้าหมายของเราคืบหน้า และให้เรายืนหยัดใน Tirisfal ได้มั่นคงขึ้น\n\nกว่าที่ Forsaken และ Horde จะยอมรับเราอย่างเต็มใจคงต้องใช้เวลา อาจหลายปี... หรือหลายสิบปี แต่สิ่งที่ดีที่สุดที่เราทำได้คือพยายามพิสูจน์ตัวเองต่อไป" },
        required = { [270435] = { "23:1070669361:2091564883", "ศีรษะของ Rudolph Gelhardt" } },
        steps = { { "23:1070669361:2091564883", "ศีรษะของ Rudolph Gelhardt" } },
        objectiveLabels = {
            monster = { ["Tarnished Drudge slain"] = "ปราบ กุลี Tarnished", ["Tarnished Zealot slain"] = "ปราบ สาวกคลั่ง Tarnished" },
        },
    },
    [91858] = { -- Diplomatic Incident
        title = { "19:2000230584:1836574931", "เหตุพิพาททางการทูต" },
        objective = { "112:1514615601:661992563", "เดินทางไป The Sepulcher ใน Silverpine Forest คุยกับ Trevan Rol เรื่องนักเดินทาง Earthen Ring ที่หายไป" },
        description = { "503:2033350577:1744651945", "เหตุไม่คาดฝันอันน่าเสียดายใน Silverpine ให้โอกาสพิเศษพิสูจน์คุณค่าต่อ Horde\n\nผู้แทนสำคัญ Earthen Ring คู่หนึ่งหายใน Silverpine Forest ระหว่างไป Tarren Mill ไม่รู้อื่นมาก แต่ข่าวลือว่าเริ่มเป็นเหตุพิพาททางการทูตใหญ่ หากช่วยคนหายได้ อาจทำให้ได้การยอมรับที่ต้องการอย่างยิ่ง\n\nเรามี Trevan Rol อยู่ The Sepulcher ไปคุยกับเขา" },
        completion = { "110:1242457465:1392760190 C 1:46:46", "Danitha ส่งเจ้ามาหรือ? งั้นข้าก็รู้แล้วว่าเจ้ามาทำไม เจ้าเพิ่งเดินเข้ามาเจอเรื่องยุ่งเข้าเต็ม ๆ เลยละ {class}" },
    },
    [91859] = { -- A Curious Pair
        title = { "14:1852898426:2129313273", "คู่ชวนสงสัย" },
        objective = { "116:723600058:511412556", "คุยกับ Deathguard Baldren เรื่องนักเดินทาง Earthen Ring ลึกลับที่เพิ่งผ่าน The Sepulcher" },
        description = { "504:2061691074:1688023528", "เข้าเรื่องเลย 'ผู้แทน' คู่นี้ไม่ใช่นักการทูตธรรมดา หนึ่งเป็นทอเรน ปกติสำหรับ Earthen Ring แต่อีกคน เจ้าคงแทบไม่เชื่อ เป็นเอลฟ์ ไฮเอลฟ์ พวกเขาสวมผ้าคลุม แต่ข้าเคยเห็น Quel'dorei พนันด้วยนิ้วก้อยดี ๆ ได้ว่านั่นใช่\n\nทำไมเอลฟ์มากับทอเรนในแดน Horde? ข้าก็เดาได้พอ ๆ กับเจ้า รู้เท่านี้ แนะนำคุยกับ Deathguard Baldren ใกล้ทางเข้าเมือง" },
        completion = { "127:1107117679:1144900194", "ข้าอาจไม่ชอบพวกเจ้าที่เป็นพาลาดิน แต่ต้องยอมรับว่าเจ้ามาได้ถูกจังหวะพอดี โชคดีไว้ก่อนคงดีกว่ามีฝีมือกระมัง?" },
    },
    [91860] = { -- A Grim Fate
        title = { "11:1536680470:399060382", "ชะตาอันโหดร้าย" },
        objective = { "91:1597522636:1506168227", "สำรวจ Fenris Isle ทางตะวันออก เพื่อรู้ชะตาคณะเดินทาง Earthen Ring" },
        description = { "489:69937905:236040629", "ออกลาดตระเวนเมื่อคืน ข้าเห็นกนอลล์กลุ่มหนึ่งโยนศพใหญ่มากบนเชิงตะกอนริม Fenris Isle ไม่เห็นเอลฟ์หรือศพเล็กกว่า แต่คงไม่ใช่ลางดี\n\nหากกล้าหรือโง่ ก็เชิญบุก Fenris Isle หาข่าว แต่ถ้าถามข้า เป็นงานหนักเพื่อหาเอลฟ์ถือตัวที่คงตายนานแล้ว\n\nรู้ว่าพาลาดินชอบสาบานและรับงานหมดหวัง แต่เรื่องนี้ไม่คุ้ม เชื่อเถอะ", variants = { { "488:1273435175:896562444", "ออกลาดตระเวนเมื่อคืน ข้าเห็นกนอลล์กลุ่มหนึ่งโยนศพใหญ่มากบนเชิงตะกอนริม Fenris Isle ไม่เห็นเอลฟ์หรือศพเล็กกว่า แต่คงไม่ใช่ลางดี\n\nหากกล้าหรือโง่ ก็เชิญบุก Fenris Isle หาข่าว แต่ถ้าถามข้า เป็นงานหนักเพื่อหาเอลฟ์ถือตัวที่คงตายนานแล้ว\n\nรู้ว่าพาลาดินชอบสาบานและรับงานหมดหวัง แต่เรื่องนี้ไม่คุ้ม เชื่อเถอะ" } } },
        completion = { "334:758587235:1769688702", "<ศพตรงหน้าเจ้าเป็นชาวทอเรนแน่ ๆ ตามร่างมีรอยถูกแทะจนเหวอะหวะก่อนจะถูกโยนขึ้นกองฟืนเผาศพ แต่เจ้ามองไม่เห็นวี่แววหญิงเอลฟ์ที่เขาเล่าให้ฟัง บางทีนางอาจยังมีชีวิตอยู่ลึกเข้าไปในป้อมใกล้ ๆ นี้\n\nเสี่ยงก็จริง แต่มีทางเดียวที่จะรู้แน่>" },
    },
    [91861] = { -- Into Fenris Keep
        title = { "16:2029061612:1588275051", "เข้า Fenris Keep" },
        objective = { "104:219247574:241598063", "สำรวจ Fenris Keep ทางเหนือ พยายามหาสมาชิกคณะ Earthen Ring ที่หายไป" },
        description = { "172:493988302:1548843514", "<การพบศพเพียงหนึ่งเป็นสัญญาณมีหวัง บางทีไฮเอลฟ์ที่ Trevan กับ Hadrec บอกอาจยังอยู่ลึกในป้อมใกล้เคียง?>", variants = { { "177:1529478069:479407228", "<การพบศพเพียงหนึ่งเป็นสัญญาณมีหวัง บางทีไฮเอลฟ์ที่ Trevan กับ Hadrec บอกอาจยังอยู่ลึกในป้อมใกล้เคียง?>" } } },
        completion = { "104:45957076:1284183574", "เจ้าเป็น Forsaken ใช่ไหม? ช่วยปล่อยข้าเป็นอิสระได้หรือเปล่า?\n\nข้าเกรงว่าเวลาเหลือไม่มากแล้ว ได้โปรดรีบหน่อย!" },
    },
    [91862] = { -- Lumina Windsinger
        title = { "17:1486615610:2127758171", "Lumina Windsinger" },
        objective = { "91:1645707926:1567022846", "นำ Fenris Isle Key จาก Rot Hide Gnolls มาใช้ปลดปล่อย Lumina Windsinger" },
        description = { "493:1953032980:1276440474", "Quel'dorei หรือ? ไม่ ข้าไม่ใช่ 'Quel'dorei' ข้าคือ Lumina Windsinger เป็น Shen'dorei หนึ่งใน Windshaper Skyborne\n\nมาในฐานะแขก Earthen Ring ข้ากับ Banon ผ่าน Silverpine เพื่อไป Arathi Highlands ศึกษาจุดบรรจบธาตุ ชัดว่าไปไม่ถึง\n\nแต่ไม่มีเวลาคุย ฆ่ากนอลล์ใกล้ ๆ เอากุญแจกรงมาปล่อยข้า ไว้ปลอดภัยจะเล่าที่เหลือ" },
        completion = { "11:1191658970:1224418299 C 44:314352447:1934043551", "ขอบใจ {class} แต่น่าเสียดายที่เรายังไม่พ้นอันตราย" },
        progress = { "70:1019243941:1164687340", "พวกโนลล์เป็นสิ่งมีชีวิตที่ข้าเคยเจอแล้วเห็นว่าเลวร้ายเป็นอันดับสองใน Azeroth" },
        required = { [267412] = { "15:1699729973:762567531", "กุญแจเกาะ Fenris" } },
        objectiveLabels = {
            item = { ["Fenris Isle Key"] = "กุญแจเกาะ Fenris" },
        },
    },
    [94427] = { -- A Lesson in Divinity
        title = { "20:1793015738:1703587054", "บทเรียนความศักดิ์สิทธิ์" },
        objective = { "42:1659359305:571154477", "คุยกับ Tanis Alderwood ใน Undercity" },
        description = { "436:1549966402:1133844250", "หลักสำคัญพาลาดินคือมุ่งสู่ความศักดิ์สิทธิ์ ไม่ใช่เป็นเทพ แต่ทำดีเพื่อความดี เรามาถึงจุดนี้เพราะโศกนาฏกรรมรูปใดรูปหนึ่ง จะสูญความเมตตาที่เคยนิยามพาลาดินตอนมีชีวิตก็ง่าย\n\nไป Undercity หา Tanis Alderwood ใน Trade Quarter เขาเดือดร้อน และน้ำใจจะช่วยได้มาก", variants = { { "436:846817951:666091658", "หลักสำคัญพาลาดินคือมุ่งสู่ความศักดิ์สิทธิ์ ไม่ใช่เป็นเทพ แต่ทำดีเพื่อความดี เรามาถึงจุดนี้เพราะโศกนาฏกรรมรูปใดรูปหนึ่ง จะสูญความเมตตาที่เคยนิยามพาลาดินตอนมีชีวิตก็ง่าย\n\nไป Undercity หา Tanis Alderwood ใน Trade Quarter เขาเดือดร้อน และน้ำใจจะช่วยได้มาก" } } },
        completion = { "17:1396640416:1732062939 C 136:1411698831:1390260384", "เจ้า... เจ้าเป็น {class} หรือ? ได้โปรดอย่าทำร้ายข้า ขะ... ข้ารู้ว่าขอทานไม่ได้ ข้าไม่มีเรื่องบาดหมางกับเจ้าหรือภาคีของเจ้า ปล่อยข้าไปเถอะ ข้าขอร้อง!" },
    },
    [94434] = { -- A Lesson in Divinity
        title = { "20:1793015738:1703587054", "บทเรียนความศักดิ์สิทธิ์" },
        objective = { "57:1829048295:1643261812", "นำ Linen Cloth 10 ชิ้นไปให้ Tanis Alderwood ใน Undercity" },
        description = { "493:440484668:485866963", "เดี๋ยว อยาก... ช่วยหรือ? ทำไมพาลาดินอยากช่วยขอทานอย่างข้า?\n\nเอาละ คงช่วยได้บ้าง\n\nเรื่องภรรยาน่ะ นางกำลัง... หลุดเป็นชิ้น ๆ ตามตัวอักษรเลย นักปรุงยาเย็บให้ดีเหมือนใหม่ได้ แต่ยุ่งงาน Dark Lady ไม่มีใครว่าง หากนำผ้าสะอาดมา อย่างน้อยข้าจะพันให้นางอยู่เป็นชิ้นเดียวระหว่างรอ", variants = { { "492:841729078:148075523", "เดี๋ยว อยาก... ช่วยหรือ? ทำไมพาลาดินอยากช่วยขอทานอย่างข้า?\n\nเอาละ คงช่วยได้บ้าง\n\nเรื่องภรรยาน่ะ นางกำลัง... หลุดเป็นชิ้น ๆ ตามตัวอักษรเลย นักปรุงยาเย็บให้ดีเหมือนใหม่ได้ แต่ยุ่งงาน Dark Lady ไม่มีใครว่าง หากนำผ้าสะอาดมา อย่างน้อยข้าจะพันให้นางอยู่เป็นชิ้นเดียวระหว่างรอ" } } },
        progress = { { "62:1820849681:482761455", "51:77149882:2009666830 N 1:46:46", "51:77149882:2009666830 C 1:46:46", "51:77149882:2009666830 R 1:46:46" }, "หวังว่าไม่รบกวนท่าน นักผจญภัยผู้ใจดี" },
        completion = { { "55:304072073:686770890", "26:622997273:256947415 N 19:279669870:416482862", "26:622997273:256947415 C 19:279669870:416482862", "26:622997273:256947415 R 19:279669870:416482862" }, "เจ้ามีน้ำใจมาก นักผจญภัย มากจริง ๆ" },
        required = { [2589] = { "11:1393025601:1453557725", "ผ้าลินิน" } },
        steps = { { "11:1393025601:1453557725", "ผ้าลินิน" } },
    },
    [94435] = { -- A Lesson in Divinity
        title = { "20:1793015738:1703587054", "บทเรียนความศักดิ์สิทธิ์" },
        objective = { "41:1604808771:1978332855", "กลับไปหา Danitha Morr ที่ Bandarion Keep" },
        description = { "184:1864981635:142795661 C 1:46:46", "ไม่รู้ทำไมยอมลำบากช่วย แต่ขอบใจ หากมีคนส่งมา บอกว่าข้าขอบใจเขาด้วย เจ้าจะมี Tanis Alderwood เป็นสหายเสมอ {class}" },
        completion = { { "506:1725718204:1999511760", "20:1921578502:569519135 N 480:203441742:428990336", "20:1921578502:569519135 C 480:203441742:428990336", "20:1921578502:569519135 R 480:203441742:428990336" }, "ทำดีแล้ว สหาย แม้เล็กน้อย แต่การรับใช้เล็ก ๆ เช่นนี้ช่วยเสริมสายสัมพันธ์กับแสงได้\n\nDark Lady กับผู้รับใช้มากมายไม่ไว้ใจ บางคนถึงคิดร้าย แต่เราจะตอบความสงสัยและกลัวด้วยกล้าและชอบธรรม แสดงว่าเป็น Forsaken และเต็มใจทำหน้าที่ใหญ่หรือเล็ก ช่วยให้ผู้คนรุ่งเรืองอีก\n\nรับสัญลักษณ์นี้ ต้องใช้กับสิ่งต่อไป" },
    },
    [94436] = { -- A Lesson in Divinity
        title = { "20:1793015738:1703587054", "บทเรียนความศักดิ์สิทธิ์" },
        objective = { "132:1606221841:1857320945", "คุยกับ Deathguard Billmuth ที่ Bandarion Keep\n\nหากทำ Symbol of Life หาย กลับไปหา Danitha Morr เพื่อรับชิ้นใหม่" },
        description = { "497:1731716109:1178670377", "ถึงเวลาแสดงพลังเรียกหนึ่งในของขวัญยิ่งใหญ่ที่สุดของแสง\n\nของที่เพิ่งให้ชื่อ Symbol of Life ระวัง การจับเครื่องรางแสงเช่นนี้อาจไม่สบาย แสงอาจเป็นปฏิปักษ์ต่อพลังที่สร้างเรา แต่ยังเป็นผู้นำและพันธมิตร ความเจ็บเตือนเรื่องนี้\n\nไปหา Deathguard Billmuth ชั้นล่าง เขาเพิ่งมาขอความช่วยเหลือ แสดงให้เขาและ Forsaken เห็นว่าพาลาดินแท้ทำอะไรได้" },
        completion = { "209:1793433658:1117559821", "ถ้าอย่างนั้นเจ้าจะช่วยข้าใช่ไหม? ดี ดีเลย ข้ายอมรับว่าข้าไม่ได้ภูมิใจที่ต้องหันมา... เอ่อ ขอให้พาลาดินช่วย พวกนักบวชปัดข้าไปแล้ว และเจ้าอาจเป็นความหวังเดียวของเพื่อนข้า\n\nได้โปรด ช่วยข้าที" },
        logReady = { "49:732427663:60021160", "คุยกับ Deathguard Billmuth ที่ Bandarion Keep", variants = { { "46:1343446009:865451079", "คุยกับ Deathguard Billmuth ที่ Tyr's Watch" } } },
        objectiveLabels = {
            event = { ["Speak with Deathguard Billmuth at Tyr's Watch."] = "คุยกับ Deathguard Billmuth ที่ Tyr's Watch" },
        },
    },
    [94438] = { -- A Lesson in Divinity
        title = { "20:1793015738:1703587054", "บทเรียนความศักดิ์สิทธิ์" },
        objective = { "166:761968497:267476141", "นำ Symbol of Life ไปชุบชีวิต Deathguard Falgan ที่ Venomweb Vale\n\nหากทำ Symbol of Life หาย กลับไปหา Danitha Morr เพื่อรับชิ้นใหม่" },
        description = { "504:2005093333:1963785015", "ข้ากับ Falgan ไปสอดแนม Scarlet ใน Venomweb Vale ลอบใกล้ค่ายพอได้ยินคำสั่งใหม่โจมตี Brill ก่อนตัดสินใจต่อ ข้าเหยียบกิ่งไม้ เสียงทำให้พวกมันรู้ตัว\n\nFalgan ตะโกนให้วิ่ง ข้าก็วิ่ง กว่าจะรู้ว่าไม่ได้ตามมาก็ครึ่งทางถึง Brill แล้ว เจ้างั่งผู้กล้าคงอยู่ต้านให้\n\nโปรดหาและช่วยสหายหากทำได้" },
        completion = { "28:1570469621:874352111 C 418:129459275:1209058977", "ข้า... กลับมาแล้วหรือ? แถมคนที่ช่วยข้าก็เป็น {class} เสียด้วย? ข้าเห็นเจ้าพก Symbol of Life มาด้วย ข้าไม่เห็นของอย่างนี้ตั้งแต่... ตั้งแต่ก่อนสงคราม สมัยที่ Lordaeron ยังต่างจากตอนนี้มาก ข้าคงได้แต่เดาว่าเจ้ามาเพื่อช่วย ข้ากับ Billmuth ถูกส่งมาสอดแนมความเคลื่อนไหวของพวก Scarlet และพบว่าพวกมันกำลังวางแผนโจมตีบางอย่าง\n\nถ้าเจ้ายังเต็มใจช่วย ก็อาจมีอะไรอีกที่เจ้าทำเพื่อ Forsaken ได้", variants = { { "28:1570469621:874352111 C 418:67967529:791476980", "ข้า... กลับมาแล้วหรือ? แถม{class}เป็นคนช่วยข้าเสียด้วย? ข้าเห็นเจ้าพก Symbol of Life มาด้วย ข้าไม่ได้เห็นของแบบนี้ตั้งแต่... ตั้งแต่ก่อนสงคราม ตอนที่ Lordaeron ยังต่างจากตอนนี้มาก ข้าคิดว่าเจ้าคงมาช่วย ข้ากับ Billmuth ถูกส่งมาสอดแนมความเคลื่อนไหวของพวก Scarlet ที่นี่ และพบว่าพวกมันกำลังเตรียมโจมตีบางอย่าง\n\nถ้าเจ้ายินดีช่วยต่อ ก็อาจยังมีอะไรอีกที่เจ้าทำให้ชาว Forsaken ได้" } } },
        logReady = { "83:940012024:1991855207", "นำ Symbol of Life ไปใช้ชุบชีวิต Deathguard Falgan ที่ Venomweb Vale" },
        objectiveLabels = {
            event = { ["Take the Symbol of Life and use it to resurrect Deathguard Falgan at Venomweb Vale."] = "นำ Symbol of Life ไปใช้ชุบชีวิต Deathguard Falgan ที่ Venomweb Vale" },
        },
    },
    [94440] = { -- A Lesson in Divinity
        title = { "20:1793015738:1703587054", "บทเรียนความศักดิ์สิทธิ์" },
        objective = { "139:638252810:444593374", "นำ Scarlet Crusade Attack Plans จาก Scarlet Crusaders ที่ Venomweb Vale กลับไปให้ Deathguard Billmuth ที่ Bandarion Keep", variants = { { "136:125710589:2139378104", "นำ Scarlet Crusade Attack Plans จาก Scarlet Crusaders ที่ Venomweb Vale กลับไปให้ Deathguard Billmuth ที่ Tyr's Watch" } } },
        description = { "373:1899812297:258351141", "Scarlet Crusader มักพกถุงใส่คำสั่งวางกำลัง เรารู้ว่าจะโจมตี แต่หากกู้คำสั่งได้ จะเตือน Deathguard ที่เหลือและเตรียมซุ่มตอบโต้\n\nเจ้าเป็นพาลาดินน่าประทับใจ ฆ่าสัตว์ Scarlet พวกนี้ เอาคำสั่งฉบับหนึ่งกลับ Deathguard Billmuth เขาจะจัดการต่อ" },
        progress = { "31:770806424:1475193555", "มีข่าว Deathguard Falgan อย่างไร?" },
        completion = { "31:1075568623:2083245068 N 310:1643327070:196110438", "ขอบใจที่ช่วยเพื่อนข้าไว้ {name} ข้าจะนำแผนพวกนี้กลับไปให้ผู้บัญชาการ แล้วเราจะต้อนรับพวก Crusade อย่างที่พวกมันไม่มีวันลืม\n\nข้ารู้ว่าคนของเราหลายคนไม่ไว้ใจพวกเจ้าที่เป็นพาลาดิน แต่ข้าเห็นชัดว่าเจ้าเป็น Forsaken ทั้งกายและใจ ข้าจะไม่ลืมเรื่องนี้ และจะบอกคนอื่นให้รู้ว่าเจ้าทำอะไรลงไปในวันนี้", variants = { { "32:1543229327:174683057 N 311:1500267208:74019702", "ขอบใจที่ช่วยเพื่อนข้าไว้ {name} ข้าจะนำแผนพวกนี้กลับไปให้ผู้บัญชาการ แล้วเราจะต้อนรับพวก Crusade อย่างที่พวกมันไม่มีวันลืม\n\nข้ารู้ว่าคนของเราหลายคนไม่ไว้ใจพวกเจ้าที่เป็นพาลาดิน แต่ข้าเห็นชัดว่าเจ้าเป็น Forsaken ทั้งกายและใจ ข้าจะไม่ลืมเรื่องนี้ และจะบอกคนอื่นให้รู้ว่าเจ้าทำอะไรลงไปในวันนี้" } } },
        required = { [264693] = { "28:294972999:794813536", "แผนโจมตีของ Scarlet Crusade" } },
        steps = { { "28:294972999:794813536", "แผนโจมตีของ Scarlet Crusade" } },
    },
    [94441] = { -- A Lesson in Divinity
        title = { "20:1793015738:1703587054", "บทเรียนความศักดิ์สิทธิ์" },
        objective = { "54:1072397436:2039137629", "คุยกับ Danitha Morr ในป้อม Bandarion Keep" },
        description = { "302:117545720:917724269 N 1:46:46", "ฝากขอบใจ Danitha Morr และบอกว่า Deathguard ที่เหลือจะรู้เรื่องความช่วยเหลือจากพาลาดิน Bandarion Keep\n\nเจ้ามีแววมาก ภูมิใจมีคนเช่นเจ้าใน Forsaken ขอ Dark Lady คุ้มครอง {name}", variants = { { "299:628580969:1762740025 N 1:46:46", "ฝากขอบใจ Danitha Morr และบอกว่า Deathguard ที่เหลือจะรู้เรื่องความช่วยเหลือจากพาลาดิน Tyr's Watch\n\nเจ้ามีแววมาก ภูมิใจมีคนเช่นเจ้าใน Forsaken ขอ Dark Lady คุ้มครอง {name}" } } },
        completion = { "48:1850070379:1840206452 C 440:399686088:1577089975 N 1:46:46", "มีเพียง {class} ที่พร้อมรับพรอันยิ่งใหญ่อย่างหนึ่งของพระแสงเท่านั้นที่ใช้ Symbol of Life ได้ ข้าภูมิใจที่มีเจ้าอยู่ในหมู่พวกเรา และบัดนี้ข้าขอมอบพรแห่งการไถ่บาปแก่เจ้า ด้วยพรนี้เจ้าจะชุบชีวิตสหายที่ล้มลงได้ จงใช้พรใหม่นี้อย่างมีปัญญา\n\nเจ้าทำคุณทั้งแก่ Forsaken และเหล่าพาลาดินแห่ง Tyr's Watch ทุกก้าวที่จะช่วยให้เราได้ใจและความไว้วางใจจากพี่น้อง Forsaken ล้วนคุ้มค่าที่จะลงแรง ขอพระแสงสถิตกับเจ้า {name}", variants = { { "48:1850070379:1840206452 C 443:1336372636:848106805 N 1:46:46", "มีเพียง {class} ที่พร้อมรับพรอันยิ่งใหญ่ของพระแสงจึงจะใช้ Symbol of Life ได้ ข้าภูมิใจที่มีเจ้าอยู่ในหมู่เรา และบัดนี้ข้าขอมอบพรแห่งการไถ่บาปให้เจ้า ด้วยพรนี้เจ้าจะชุบชีวิตสหายที่ล้มลงได้ จงใช้พรใหม่นี้อย่างรอบคอบ\n\nเจ้าทำคุณให้ทั้งเหล่า Forsaken และพาลาดินแห่ง Bandarion Keep ทุกก้าวที่ช่วยให้พี่น้อง Forsaken เปิดใจและไว้ใจเราล้วนคุ้มค่า ขอพระแสงสถิตกับเจ้า {name}" } } },
    },
    [95034] = { -- The Debt
        title = { "8:308529484:699242410", "หนี้บุญคุณ" },
        objective = { "46:1043275623:638236081", "คุยกับ Lumina Windsinger ใน Sepulcher" },
        description = { "498:885719882:1277224613", "ควรรู้ว่าที่จริงไม่ใช่กนอลล์โจมตีเราบนถนน\n\nเป็นสัตว์ยักษ์คล้ายหมาป่า ที่ตอนนี้รู้ว่าชื่อ 'เวอร์เกน' มันจัดการยามแล้วเข้าหาข้า แต่ Banon ขวางไว้ ข้าร่ายเวททำให้มันตกใจหนี แต่ Banon ถูกกัดหนักแล้ว ยืนยันให้ทิ้ง แต่ข้าไม่ยอม\n\nเรากะเผลกกลับตอนกนอลล์พบ สิ่งที่ตามมาน่ากลัวมาก..." },
        completion = { "489:2032024300:1092766728", "ทีนี้เจ้าก็เข้าใจแล้ว ตอนที่เขาแทบสิ้นแรงหลังถูกคมดาบของพวกโนลล์ถึงสิบสองเล่มแทง เขาผุดขึ้นมาจะโจมตีข้า ในวินาทีสุดท้ายนั้นเราสบตากัน ข้าดูออกว่าเขายังรู้ว่าตัวเองเป็นใครและจำข้าได้ เขารู้ว่ากำลังเกิดอะไรขึ้นแต่ควบคุมตัวเองไม่ได้ นั่นคือส่วนที่เลวร้ายที่สุด\n\nถ้าข้าทำได้ ข้าจะฆ่าสิ่งที่ทำให้เขาต้องพบชะตากรรมเช่นนี้ เพื่อให้มันไม่มีวันนำความสยดสยองนี้ไปให้ชีวิตอื่นอีก ข้าขอสาบานต่อท้องฟ้าเบื้องบน" },
        progress = { "151:1713556343:1297924685", "ข้าไม่เคยเห็นอะไรเหมือนที่เกิดกับ Banon มาก่อน Azeroth เป็นดินแดนมหัศจรรย์ แต่พอคิดว่าที่นี่เกิดเรื่องได้สารพัดขนาดไหน ก็น่ากลัวจริง ๆ" },
        steps = { { "28:354016332:1607771416", "คุยกับ Lumina Windsinger" } },
    },
    [95036] = { -- A Moon-Kissed Blade
        title = { "19:753783983:1060561237", "คมดาบจุมพิตจันทร์" },
        objective = { "79:536347207:621664665", "คุยกับ Trevan Rol ใน Sepulcher แล้วนำวัสดุที่เขาต้องการมาให้" },
        description = { "499:1501070091:63599642", "Trevan ว่าเวอร์เกนเป็นภัยใหญ่ต่อชาว Silverpine Forest แม้แกร่งและทนก็ฆ่าได้ แต่มีตัวหนึ่งไม่ยอมตายถาวรเพราะเวทไม่ทราบชนิด\n\nตัวนั้นโจมตีเรา ชื่อ Old Fire-Eye ใหญ่และดุที่สุด หากจะล้มต้องใช้อาวุธพิเศษ\n\nคุยกับ Trevan เขาจะให้รายการของที่ต้องใช้ตีอาวุธ" },
        progress = { "87:811633997:556946628", "ไว้ใจแสงนำคมดาบ แต่แสงต้องมีคมดาบดีให้นำด้วย" },
        completion = { "123:2074534786:1666623703", "เมื่อมีวัสดุแล้ว ก็ต้องมีช่างตีดาบ ข้าว่ารู้จักช่างเช่นนั้น" },
        required = { [6994] = { "21:1837031187:1998177872", "ไม้โอ๊ก Whitestone แปรรูป" }, [267361] = { "22:692150916:1739655043", "แท่งเงินลงมนตร์" }, [272448] = { "16:738523197:1168599911", "อัญมณี Kor ที่ชำระแล้ว" }, [267454] = { "21:615850062:1018358955", "บันทึกเรื่องอาวุธของ Trevan" } },
        steps = { { "28:964916619:385917288", "รับบันทึกจาก Trevan" }, { "21:1837031187:1998177872", "ไม้โอ๊ก Whitestone แปรรูป" }, { "22:692150916:1739655043", "แท่งเงินลงมนตร์" }, { "16:738523197:1168599911", "อัญมณี Kor ที่ชำระแล้ว" } },
        objectiveLabels = {
            item = { ["Trevan's Weapon Notes"] = "บันทึกเรื่องอาวุธของ Trevan" },
        },
    },
    [95042] = { -- Seeking the Kor Gem
        title = { "19:1122219637:258749622", "ตามหาอัญมณี Kor" },
        objective = { "48:1302960666:1477525837", "นำ Kor Gem ไปให้ Ulric Frostveil ใน Ashenvale" },
        progress = { "122:1756491298:2067134865", "อัญมณี Kor ใช้ทำชั่วใหญ่หลวงได้ ข้าไม่ขอตัดสินเจตนาว่าบริสุทธิ์หรือไม่ ไม่สำคัญกับข้า" },
        completion = { "413:144729832:1083573550", "คงเห็นความแปดเปื้อนทั่วอัญมณี เวทที่ต้องใช้ขจัดชั่วร้ายซึ่งนางแม่มดนากาใส่ไว้ สำหรับงานเจ้าเรียบง่ายมาก น่าเสียดาย มีสิ่งให้เรียนจากพลังเช่นนี้มาก\n\nจะยอมละภารกิจที่ทำให้หาอัญมณี แล้วขายให้ข้าแทนไหม? อาจมีค่าต่อ... การศึกษาของข้า", variants = { { "410:931474691:732499608", "คงเห็นความแปดเปื้อนทั่วอัญมณี เวทที่ต้องใช้ขจัดชั่วร้ายซึ่งนางแม่มดนากาใส่ไว้ สำหรับงานเจ้าเรียบง่ายมาก น่าเสียดาย มีสิ่งให้เรียนจากพลังเช่นนี้มาก\n\nจะยอมละภารกิจที่ทำให้หาอัญมณี แล้วขายให้ข้าแทนไหม? อาจมีค่าต่อ... การศึกษาของข้า" }, { "413:314637184:467835099", "คงเห็นความแปดเปื้อนทั่วอัญมณี เวทที่ต้องใช้ขจัดชั่วร้ายซึ่งนางแม่มดนากาใส่ไว้ สำหรับงานเจ้าเรียบง่ายมาก น่าเสียดาย มีสิ่งให้เรียนจากพลังเช่นนี้มาก\n\nจะยอมละภารกิจที่ทำให้หาอัญมณี แล้วขายให้ข้าแทนไหม? อาจมีค่าต่อ... การศึกษาของข้า" } } },
        description = { "416:194292667:769083072 C 1:46:46", "พาลาดิน Forsaken... มาอยู่ที่ Ashenvale งั้นหรือ? ชวนขำดีนี่\n\nเจ้ากำลังตามหา Kor Gem ใช่ไหม? ไม่น่าแปลกใจ บางครั้งพาลาดินของ Alliance ก็ใช้อัญมณีนี้เสริมพลังให้อาวุธและเครื่องมือเวทมนตร์ แล้วพาลาดินผู้ร่วงหล่นอย่างเจ้าจะต่างจากพวกเขาตรงไหน?\n\nถ้าอยากได้อัญมณีจริง ๆ เจ้าต้องมุ่งไปทางเหนือ ไปยังซากปรักหักพังที่เรียกว่า Blackfathom Deeps พวกนากาที่ยังใช้อัญมณีอยู่ข้างล่าง อย่าไปตามลำพังนะ {class}", variants = { { "416:791190971:116559213 C 1:46:46", "พาลาดิน Forsaken... มาอยู่ที่ Ashenvale งั้นหรือ? ชวนขำดีนี่\n\nเจ้ากำลังตามหา Kor Gem ใช่ไหม? ไม่น่าแปลกใจ บางครั้งพาลาดินของ Alliance ก็ใช้อัญมณีนี้เสริมพลังให้อาวุธและเครื่องมือเวทมนตร์ แล้วพาลาดินผู้ร่วงหล่นอย่างเจ้าจะต่างจากพวกเขาตรงไหน?\n\nถ้าอยากได้อัญมณีจริง ๆ เจ้าต้องมุ่งไปทางเหนือ ไปยังซากปรักหักพังที่เรียกว่า Blackfathom Deeps พวกนากาที่ยังใช้อัญมณีอยู่ข้างล่าง อย่าไปตามลำพังนะ {class}" } } },
    },
    [95111] = { -- An Underrated Talent
        title = { "20:48527483:859697484", "พรสวรรค์ที่ถูกมองข้าม" },
        objective = { "47:2095106855:1214233018", "คุยกับ Ott ขอให้เขาตีดาบให้" },
        description = { "501:225510200:1435436731", "Tarren Mill มีช่างอาวุธชื่อ Ott ใคร ๆ ว่าไม่โดดเด่น ขายดาบธรรมดาให้นักเดินทาง ข้าเคยซื้อ แล้วนำไปบำรุงใน Undercity ภายหลัง ช่างที่นั่นประหลาดใจคุณภาพ นึกว่ามาจากปรมาจารย์ชื่อดัง แต่ไม่ใช่ แค่ Ott\n\nอยากให้ออร์คนี้มีโอกาสทำสิ่งพิเศษจริง นำวัสดุไป Ott ที่ Tarren Mill เสนองานให้เขา", variants = { { "501:522333806:1990766360", "Tarren Mill มีช่างอาวุธชื่อ Ott ใคร ๆ ว่าไม่โดดเด่น ขายดาบธรรมดาให้นักเดินทาง ข้าเคยซื้อ แล้วนำไปบำรุงใน Undercity ภายหลัง ช่างที่นั่นประหลาดใจคุณภาพ นึกว่ามาจากปรมาจารย์ชื่อดัง แต่ไม่ใช่ แค่ Ott\n\nอยากให้ออร์คนี้มีโอกาสทำสิ่งพิเศษจริง นำวัสดุไป Ott ที่ Tarren Mill เสนองานให้เขา" } } },
        progress = { { "39:1137150190:1948581329", "28:780121688:399890867 N 1:63:63", "28:780121688:399890867 C 1:63:63", "28:780121688:399890867 R 1:63:63" }, "ต้องการคมดาบหรือ นักผจญภัย?", variants = { { "36:1693279825:1602308072", "เจ้าต้องการดาบหรือ พาลาดิน" } } },
        completion = { "378:1820863206:533532720", "น่าสนใจ คงไม่เคยมีใครขอทำงานสั่งพิเศษจริง ส่วนใหญ่ข้าทำอาวุธเรียบง่าย ใช้งานได้ตามแบบตน ไม่มาก แต่สุจริต ไม่แสวงหาคำยกย่องหรือเกียรติ\n\nยินดีลอง แต่ทำไมมาหาข้า? ช่างใน Undercity มากมายรับงานพิเศษแบบนี้", variants = { { "377:618319869:109565836", "น่าสนใจ คงไม่เคยมีใครขอทำงานสั่งพิเศษจริง ส่วนใหญ่ข้าทำอาวุธเรียบง่าย ใช้งานได้ตามแบบตน ไม่มาก แต่สุจริต ไม่แสวงหาคำยกย่องหรือเกียรติ\n\nยินดีลอง แต่ทำไมมาหาข้า? ช่างใน Undercity มากมายรับงานพิเศษแบบนี้" } } },
        required = { [268192] = { "33:238480594:878473190", "มัดวัสดุสำหรับตีเหล็ก" } },
        steps = { { "33:238480594:878473190", "มัดวัสดุสำหรับตีเหล็ก" } },
    },
    [95125] = { -- Ott's Masterwork
        title = { "16:336867478:1644271761", "ผลงานชั้นครูของ Ott" },
