    [95126] = { -- The Moonsilver Blade
        title = { "20:2079494143:1961359302", "ดาบ Moonsilver" },
        objective = { "58:904860119:2113824352", "นำ Ott's Masterwork ไปให้ Trevan Rol ใน Silverpine Forest" },
        description = { "162:1876780873:161583694", "นี่ดาบ เจ้าบอกพาลาดินชื่อ Trevan ส่งมาหรือ? พบครั้งหน้าฝากขอบคุณสำหรับโอกาส จงไปอย่างมีเกียรติ สหาย" },
        progress = { "41:1554833917:430845735", "Ott ทำงานที่สั่งได้ไหม?" },
        completion = { "73:495869964:1243783670 N 147:952337664:833893234", "<Trevan รับดาบไปพินิจอย่างละเอียด>\n\nดาบนี้ใช้ได้ดีทีเดียว {name} ข้ารู้ว่า Ott มีฝีมือพอจะทำสิ่งที่ยอดเยี่ยมเช่นนี้ได้\n\nตอนนี้เหลือเพียงสังหารเจ้าสัตว์ร้ายนั่น ไปคุยกับ Lumina เมื่อเจ้าพร้อม" },
        required = { [268359] = { "16:336867478:1644271761", "ผลงานชิ้นเอกของ Ott" } },
        steps = { { "16:336867478:1644271761", "ผลงานชิ้นเอกของ Ott" } },
    },
    [95140] = { -- Old Fire-Eye
        title = { "12:550039726:290155433", "Old Fire-Eye" },
        objective = { "70:1258062985:368169582", "ใช้ Moonsilver Blade ทำลาย Old-Fire Eye ใน Silverpine Forest", variants = { { "70:460193600:1656234484", "ใช้ Moonsilver Blade ทำลาย Old Fire-Eye ใน Silverpine Forest" } } },
        description = { "37:1990716919:314593798 C 287:1922695595:1907473431", "เห็นว่ามีอาวุธแล้ว {class} ข้าภาวนาว่ามันไม่ทำให้ผิดหวัง\n\nคนท้องถิ่นว่า Old Fire-Eye ล่ากว้างทางใต้จากที่นี่ ปกติพบใกล้ประตู Gilneas หาและใช้ดาบใหม่จบชีวิต เมื่อเสร็จกลับมา แล้วจะได้ความขอบคุณจาก Windshaper" },
        progress = { "31:35237729:1330231181", "เสร็จหรือยัง? สัตว์ร้ายถูกฆ่าแล้วหรือ?" },
        completion = { { "483:1107088300:180187735", "11:1191658970:1224418299 N 455:1584127267:548462624 N 1:46:46", "11:1191658970:1224418299 N 455:1584127267:548462624 C 1:46:46", "11:1191658970:1224418299 N 455:1584127267:548462624 R 1:46:46", "11:1191658970:1224418299 C 455:1584127267:548462624 N 1:46:46", "11:1191658970:1224418299 C 455:1584127267:548462624 C 1:46:46", "11:1191658970:1224418299 C 455:1584127267:548462624 R 1:46:46", "11:1191658970:1224418299 R 455:1584127267:548462624 N 1:46:46", "11:1191658970:1224418299 R 455:1584127267:548462624 C 1:46:46", "11:1191658970:1224418299 R 455:1584127267:548462624 R 1:46:46" }, "ขอบใจ สหาย Banon พักสงบได้แล้ว\n\nหากยอม ข้าคิดว่าใส่เวทเล็กน้อยจากผู้คนข้าลงดาบที่เพิ่งเปื้อนเลือดได้\n\nดวงตา Lumina Windsinger เรืองฟ้าสดใสขณะสัมผัสดาบเปื้อนเลือดในมือเจ้า\n\nเสร็จแล้ว เพียงเล็กน้อย ข้าแทบปรับดาบงดงามเช่นนี้ให้ดีขึ้นไม่ได้ อย่างไรก็จะขอต่อสายลมให้รับใช้เจ้าได้ดี นักผจญภัย", variants = { { "11:1191658970:1224418299 N 457:1228300359:1937673462 C 1:46:46", "ขอบใจ {name} ตอนนี้ Banon พักสงบได้แล้ว\n\nถ้าเจ้าอนุญาต ข้าคิดว่าข้าพอจะใส่เวทมนตร์ของชนเผ่าข้าลงไปในดาบที่เพิ่งเปื้อนเลือดของเจ้าได้สักเล็กน้อย\n\n<ดวงตาของ Lumina Windsinger เรืองแสงสีฟ้าสดใส ขณะนางแตะดาบเปื้อนเลือดในมือเจ้า>\n\nเรียบร้อยแล้ว ข้าทำได้เพียงเล็กน้อย ดาบงามขนาดนี้แทบไม่มีอะไรให้ปรับปรุงอีก ถึงอย่างนั้น ข้าจะขอต่อสายลมให้ดาบนี้รับใช้เจ้าได้ดีนะ {class}" } } },
        required = { [268484] = { "16:193847239:290642467", "ดาบ Moonsilver" } },
        steps = { { "16:193847239:290642467", "ดาบ Moonsilver" } },
        objectiveLabels = {
            monster = { ["Old Fire-Eye slain"] = "ปราบ เจ้าเฒ่าตาไฟ" },
        },
    },
    [95803] = { -- A Token of Good Faith
        title = { "21:578628938:1620166008", "เครื่องหมายไมตรี" },
        objective = { "75:1645637176:309855833", "นำหัว Rudolph Gelhardt ไปให้ Sylvanas Windrunner ใน Undercity" },
        description = { "318:958218430:334847664", "เมื่อได้หัวผู้บัญชาการมัวหมองแล้ว ต้องนำไป Undercity Sylvanas Windrunner ไม่ไว้ใจเรามาก แทบดูหมิ่นเปิดเผย\n\nนำหัว Rudolph Gelhardt ให้ Dark Lady แสดงว่าเราดูแลเรื่องภายใน และอุทิศตนเพื่อความรุ่งเรือง Forsaken" },
        progress = { { "38:1778718839:742274537", "27:1462408590:1973920752 N 1:63:63", "27:1462408590:1973920752 C 1:63:63", "27:1462408590:1973920752 R 1:63:63" }, "พูดกับข้าทำไม นักผจญภัย?", variants = { { "35:185210855:1263556661", "เจ้ามาคุยกับข้าทำไม พาลาดิน" } } },
        completion = { "444:1784765943:557370163", "ข้าไม่สงสัยความจริงใจ Danitha และความอยากหาที่ให้พวกเจ้าใน Forsaken แต่สงสัยว่านี่คงไม่ใช่ครั้งสุดท้ายที่พี่น้องเจ้าคลั่งแล้วหันแสงใส่ผู้คนตนเอง\n\nสักวันอาจตัดสินว่าการยอมให้ภาคีผิดธรรมชาตินี้อยู่ต่อไม่เป็นประโยชน์ Forsaken แล้ว แนะนำให้ตั้งใจรับใช้ผู้คนต่อไป\n\nเราจะจับตาดู" },
        required = { [270436] = { "23:1070669361:2091564883", "ศีรษะของ Rudolph Gelhardt" } },
        steps = { { "23:1070669361:2091564883", "ศีรษะของ Rudolph Gelhardt" } },
    },
    [96204] = { -- The Windshaper's Wrath
        title = { "22:96359460:2083041928", "โทสะของ Windshaper" },
        objective = { "60:1798051213:394361473", "ร่วมทางกับ Lumina Windsinger และช่วยนางหนี Fenris Keep" },
        description = { "121:1512042127:137392045 C 1:46:46", "เมื่อเป็นอิสระ ข้าจะทำให้สัตว์ชั่วพวกนี้เสียใจที่เคยมอง Windshaper\n\nออกจากที่นี่กัน {class}" },
        completion = { "17:689065638:2099367606 N 375:1154551941:498223787", "ขอบใจอีกครั้งนะ {name} ข้าเพิ่งได้ทำความรู้จักกับ Trevan ที่อยู่ตรงนี้ ถึงได้รู้ว่าเขาเป็นคนส่งเจ้ามาตามหาข้า\n\nระหว่างเดินทาง ข้าได้ยินเรื่องที่ไม่น่าฟังนักเกี่ยวกับพาลาดิน ในฐานะเอลฟ์ shen'dorei ผู้ได้รับพรจากฟ้าและเดินทางผ่านดินแดน Horde ข้าเข้าใจดีว่าความไม่ยอมรับและอคติฝังรากได้ง่ายแค่ไหน\n\nเจ้าและพวกพ้องมีมิตรอยู่ในหมู่ Windshapers แล้ว", variants = { { "17:689065638:2099367606 N 286:1722770913:557802728", "ขอบใจอีกครั้งนะ {name} ข้าเพิ่งได้ทำความรู้จักกับ Trevan ที่อยู่ตรงนี้ ถึงได้รู้ว่าเขาเป็นคนส่งเจ้ามาตามหาข้า\n\nระหว่างเดินทาง ข้าได้ยินเรื่องที่ไม่น่าฟังนักเกี่ยวกับพาลาดิน ข้าดีใจที่คำครหาเหล่านั้นไม่มีมูลเลย\n\nเจ้าและพวกพ้องมีมิตรอยู่ในหมู่ Windshapers แล้ว" }, { "17:689065638:2099367606 N 375:1539476401:58200232", "ขอบใจอีกครั้งนะ {name} ข้าเพิ่งได้ทำความรู้จักกับ Trevan ที่อยู่ตรงนี้ ถึงได้รู้ว่าเขาเป็นคนส่งเจ้ามาตามหาข้า\n\nระหว่างเดินทาง ข้าได้ยินเรื่องที่ไม่น่าฟังนักเกี่ยวกับพาลาดิน ในฐานะเอลฟ์ shen'dorei ผู้ได้รับพรจากฟ้าและเดินทางผ่านดินแดน Horde ข้าเข้าใจดีว่าความไม่ยอมรับและอคติฝังรากได้ง่ายแค่ไหน\n\nเจ้าและพวกพ้องมีมิตรอยู่ในหมู่ Windshapers แล้ว" } } },
        objectiveLabels = {
            event = { ["Escort Lumina Windsinger to safety"] = "คุ้มกัน Lumina Windsinger ไปยังที่ปลอดภัย" },
        },
    },
    [98601] = { -- A Difficult Path
        title = { "16:1678426609:1541381224", "เส้นทางยากลำบาก" },
        objective = { "87:1842486436:1419686933", "อ่าน Consecrated Scroll แล้วคุยกับ Aramis Hammerhand ในโบสถ์ Deathknell" },
        description = { "271:1375931964:352995143", "ระหว่างจัดการ Scourge ไร้สติ ม้วนคัมภีร์มาถึงเจ้า เหม็นแสงเชียว คงสำคัญต่อพาลาดินอย่างเจ้า\n\nอ่านก่อนออกไปอีก แค่ขอ... ถอยห่างตอนอ่านด้วย พาลาดินทำข้าไม่สบายใจมาก", variants = { { "270:1081482598:762389789", "ระหว่างจัดการ Scourge ไร้สติ ม้วนคัมภีร์มาถึงเจ้า เหม็นแสงเชียว คงสำคัญต่อพาลาดินอย่างเจ้า\n\nอ่านก่อนออกไปอีก แค่ขอ... ถอยห่างตอนอ่านด้วย พาลาดินทำข้าไม่สบายใจมาก" } } },
        progress = { "27:1625061256:1748221432", "ความมุ่งมั่นเกิดผ่านความเจ็บปวด" },
        completion = { "282:1063082371:2111538100", "การฝึกเริ่มจริงจังได้แล้ว พาลาดิน เห็นแววมาก แต่ระวังอย่าหันหลังแสงแม้ครู่เดียว จงยอมรับความเจ็บที่แสงก่อ มันคือเบ้าหลอม เจ้าจะออกมาแกร่งกว่าชีวิตก่อน", variants = { { "40:477954762:144499338 C 235:141975093:1454246155", "การฝึกเริ่มจริงจังได้แล้ว {class} เห็นแววมาก แต่ระวังอย่าหันหลังแสงแม้ครู่เดียว จงยอมรับความเจ็บที่แสงก่อ มันคือเบ้าหลอม เจ้าจะออกมาแกร่งกว่าชีวิตก่อน" } } },
        required = { [282423] = { "18:277197672:2009319352", "ม้วนคัมภีร์ที่ผ่านพิธีชำระ" } },
        steps = { { "18:277197672:2009319352", "ม้วนคัมภีร์ที่ผ่านพิธีชำระ" } },
    },
    [7669] = { -- Again Into the Great Ossuary
        title = { "28:1561423313:1835199818", "สู่ Great Ossuary อีกครั้ง" },
        completion = { "42:338429609:1672519190 N 253:1566619826:1688564022", "จะกลับ Scholomance หรือ {name}? จ่ายราคามากเพื่อใช้ Divination Scryer แล้ว บางทีอยากนำอีกเครื่องไป เพื่อเผชิญภัย Great Ossuary อีกครั้ง\n\nเชิญรับ เจ้าสมควรได้แน่นอน" },
    },
    [1470] = { -- Piercing the Veil
        title = { "17:872176746:571805331", "ทะลวงม่านกั้น" },
        objective = { "41:1037712980:1668619944", "นำ Rattlecage Skulls 3 ชิ้นไปให้ Venya Marthand" },
        description = { "494:199578617:49849836", "สวัสดี เด็กเอ๋ย เห็นว่ายังใหม่ในวิถีวอร์ล็อก พลังยังหลุดจากกำมือ ข้าสัมผัสความอยากเรียนรู้ได้\n\nและเจ้าจะได้เรียน\n\nความไม่รู้ไร้พลัง ความรู้คืออำนาจสูงสุด ใช้มันควบคุมเวทโกลาหลและสิ่งจากห้วงว่าง บังคับตามเจตนาเรา\n\nข้าจะสอนผูกผู้รับใช้กับเจตนา แต่ก่อนต้องนำกะโหลกโครงกระดูก Rattlecage ใกล้โรงตีเหล็กร้างมาสามชิ้น", variants = { { "72:393359525:1328519531 C 415:526622179:1028502994", "สวัสดี เด็กเอ๋ย เห็นว่ายังใหม่ในวิถี{class} พลังยังหลุดจากกำมือ ข้าสัมผัสความอยากเรียนรู้ได้\n\nและเจ้าจะได้เรียน\n\nความไม่รู้ไร้พลัง ความรู้คืออำนาจสูงสุด ใช้มันควบคุมเวทโกลาหลและสิ่งจากห้วงว่าง บังคับตามเจตนาเรา\n\nข้าจะสอนผูกผู้รับใช้กับเจตนา แต่ก่อนต้องนำกะโหลกโครงกระดูก Rattlecage ใกล้โรงตีเหล็กร้างมาสามชิ้น" } } },
        progress = { "148:59366390:1121984331", "ตอนนี้พลังน้อย แต่ข้าว่าคงสัมผัสความเป็นไปได้แล้ว\n\nแม้คนตายก็อาจรู้สึกมีชีวิต เมื่อพลังนั้นไหลผ่านเรา" },
        completion = { "313:1415846641:1941435661 N 73:194552852:1104466142", "แม้ยังไม่ผ่านการทดสอบและเพิ่งเริ่มเรียน เจ้าพิสูจน์ว่ามีความสามารถพออัญเชิญและผูกอิมป์ อย่าหลงขนาดเล็ก แม้กำลังกายน้อย แต่พลังและไหวพริบจะรับใช้ได้ดี\n\nตั้งใจดู {name} ข้าไม่สอนซ้ำ และจะให้เจ้าฝึกจนเชี่ยวชาญเอง" },
        required = { [6281] = { "16:244187028:2135629361", "กะโหลก Rattlecage" } },
        steps = { { "16:244187028:2135629361", "กะโหลก Rattlecage" } },
    },
    [1471] = { -- The Binding
        title = { "11:105979108:1835480523", "พันธนาการ" },
        objective = { "154:1486472759:1734892113", "ใช้ Runes of Summoning อัญเชิญและสยบ Voidwalker แล้วคืน Runes of Summoning ให้ Carendin Halgar ใน Magic Quarter ของ Undercity" },
        description = { "402:1331684830:797894632", "คงเห็นวงอัญเชิญใต้เราแล้ว? มีแต่ที่นั่นจึงเรียก Voidwalker ที่ยังไม่ถูกผูกได้\n\nใช้รูนเหล่านี้เรียกออกมา แล้วต้องครอบงำด้วยกำลังอาวุธและเวท\n\nเมื่อสยบ มันจะเป็นผู้รับใช้ มาหาข้าแล้วจะอธิบายคาถาอัญเชิญ เพื่อให้มันรับใช้จุดหมายใดก็ตามที่ต้องการ" },
        progress = { "34:1666901921:1355292327 N 90:899294615:2050696335", "ข้าคาดหวังข่าวความสำเร็จ {name} แต่หากพลาด การไม่สมคาดข้าจะเป็นเรื่องเล็กที่สุดที่ต้องกังวล" },
        completion = { "20:1921578502:569519135 N 149:463837229:1406743421", "ทำดีแล้ว {name} ทีนี้ข้าจะถ่ายทอดคาถาอัญเชิญ Voidwalker\n\nพลังที่มันปล่อยใส่เจ้าบัดนี้เป็นของเจ้าสั่ง ใช้อย่างมีสติ" },
        required = { [6284] = { "18:1886698491:670926377", "รูนสำหรับอัญเชิญ" } },
        steps = { { "18:1886698491:670926377", "รูนสำหรับอัญเชิญ" } },
        objectiveLabels = {
            monster = { ["Summoned Voidwalker slain"] = "ปราบ วอยด์วอล์กเกอร์ที่ถูกอัญเชิญ" },
        },
    },
    [1472] = { -- Devourer of Souls
        title = { "17:904315564:180553437", "ผู้กลืนกินวิญญาณ" },
        objective = { "54:120190380:498572153", "คุยกับ Godrick Farsan ใน Temple of the Damned" },
        description = { "480:187542802:661461049", "ซัคคิวบัสกลืนวิญญาณ ทำลายหัวใจ ล่อลวงชาย เป็นสิ่งชั่วร้ายล้ำลึก มีจุดหมายเด็ดเดี่ยว\n\nหากไร้สิ่งกระตุ้น จะนำเข้าโลกเราไม่ได้\n\nเราจึงใช้จุดแข็งมันย้อนทำลาย ด้วยหัวใจชายดี บริสุทธิ์ และรักมั่น มันจะต้านไม่ไหว ข้ามสู่โลกเรา แล้วเจ้าครอบงำให้เป็นของตนได้\n\nคุยกับ Godrick Farsan ผู้ช่วยข้าในวิหาร เขาช่วยหาเหยื่อล่อ", variants = { { "502:1591882038:295399597", "ซายาดกลืนวิญญาณ ครอบงำเจตนา ล่อลวงหัวใจ เป็นสิ่งชั่วร้ายล้ำลึกมีจุดหมายเด็ดเดี่ยว\n\nนิทานที่คนดีและชั่วเล่าต่างใช้ชื่อทั่วไป ซัคคิวบัสสำหรับเพศหญิง อินคิวบัสสำหรับเพศชาย\n\nต้องล่อปีศาจสู่โลกด้วยสิ่งกระตุ้น หัวใจมรรตัยบริสุทธิ์เปี่ยมรัก ซายาดจะต้านไม่ไหว จากนั้นครอบงำให้เป็นของเจ้าได้\n\nคุยกับ Godrick Farsan ผู้ช่วยข้าในวิหาร เขาช่วยหาเหยื่อล่อ" } } },
        completion = { "27:196123724:1868565431 N 168:1266417894:1410866562", "Carendin ส่งมาหรือ? ถ้าอย่างนั้น {name}\n\nอย่าดูเบาเพราะข้าตาบอด บัดนี้เห็นสิ่งที่ซ่อนเบื้องหลังชัดกว่าที่เคย สิ่งที่เคยคิดว่าคำสาปกลับเป็นพร" },
    },
    [1473] = { -- Creature of the Void
        title = { "20:1762302849:713197538", "สิ่งมีชีวิตแห่งห้วงว่าง" },
        objective = { "86:1339437128:789396856", "นำ Egalin's Grimoire กลับไปให้ Carendin Halgar ใน Temple of the Damned" },
        description = { "468:1904380389:1634755823", "ดูเหมือนทุกฝ่ายเห็นว่าพร้อมเรียนอัญเชิญ Voidwalker\n\nสิ่งที่เกิดจากโกลาหลเหนือแดนนี้ หากเรียกแต่ควบคุมไม่ได้ เจ้าจะถูกฉีก\n\nEgalin เรียกตัวแรก วิธีอยู่ในคัมภีร์ของเขา\n\nน่าเสียดาย สายลับ Scarlet Crusade ขโมยแล้วซ่อนไว้ฐานที่หอคอยตะวันตก นำกลับมาแล้วข้าจะถ่ายทอดความรู้" },
        progress = { "210:2088064651:1385983115 N 37:1584617497:329710320", "Egalin คือครูข้า แทบไม่ต้องมองก็สั่ง Voidwalker ที่เรียกมาได้\n\nเมื่อถึงตาข้า ข้ามั่นใจเกินไป อย่าล้อเล่นกับพลังที่ใช้ {name} มันกลืนกินแม้ผู้ระวังตัวได้" },
        completion = { "166:1736080586:904894680 N 79:565874584:1542900324", "อา ดีเยี่ยม คงเป็นไปได้ว่า Perrine ไม่รู้พลังแท้ของหนังสืออับที่ขโมย\n\nมันจะไม่หลุดจากมือเราอีก จงดู {name} โครงสร้างคาถาและวิธีรวมพลัง" },
        required = { [6285] = { "17:1647485716:217662701", "คัมภีร์เวทของ Egalin" } },
        steps = { { "17:1647485716:217662701", "คัมภีร์เวทของ Egalin" } },
    },
    [1474] = { -- The Binding
        title = { "11:105979108:1835480523", "พันธนาการ" },
        objective = { "138:1315064092:283723614", "ใช้ Pure Hearts อัญเชิญและสยบ Succubus แล้วคืน Pure Hearts ให้ Carendin Halgar ใน Magic Quarter ของ Undercity" },
        description = { "211:57663907:652847270 N 173:1225459006:250297129", "ใช้หัวใจร่ายเวทที่วงอัญเชิญเปิดประตูให้ซัคคิวบัสผ่าน พลังเจ้าเพิ่มแล้ว และต้องใช้ทั้งหมดปราบมัน\n\nระวังเสน่ห์ {name} จิตแข็งแกร่งมากมายถูกผูกใต้เจตนามัน เมื่อแพ้จะกลับห้วงว่าง ข้าจะสอนคาถาเรียกมาตามคำสั่ง" },
        progress = { "171:864795556:608247838", "ในบรรดาพลังเหนือห้วงว่าง ซัคคิวบัสอันตรายที่สุดชนิดหนึ่ง เพราะผู้อ่อนแอตกในอำนาจง่าย\n\nจำไว้ทั้งตอนนี้และภายหน้า" },
        completion = { "27:790528204:249103511 N 280:421531204:168851181", "ทำดีอีกแล้ว {name} นานแล้วที่ไม่เห็นวอร์ล็อกรุ่นเยาว์มีแววเช่นเจ้า มั่นใจได้ว่าข้าจะเฝ้าดูความก้าวหน้า เตรียมและช่วยบททดสอบต่อไป\n\nตอนนี้ขอสอนอัญเชิญซัคคิวบัสที่เพิ่งครอบงำ" },
        required = { [6286] = { "11:1734275384:170179805", "หัวใจบริสุทธิ์" } },
        steps = { { "11:1734275384:170179805", "หัวใจบริสุทธิ์" } },
        objectiveLabels = {
            monster = { ["Summoned Succubus slain"] = "ปราบ ซัคคิวบัสที่ถูกอัญเชิญ" },
        },
    },
    [1476] = { -- Hearts of the Pure
        title = { "18:1330927062:127672485", "หัวใจผู้บริสุทธิ์" },
        objective = { "103:1120035301:151963218", "นำหัวใจของ Dalin Forgewright และ Comar Villard ไปให้ Carendin Halgar ใน Temple of the Damned", variants = { { "103:1844767787:897000928", "นำหัวใจของ Dalin Forgewright และ Corma Villard ไปให้ Carendin Halgar ใน Temple of the Damned" } } },
        description = { "496:619904406:977778542", "ชายมีเกียรติและดีงาม? มีด้วยหรือ?\n\nต้องค้นมาก แต่จากเรื่องที่ได้ยินทีละน้อย ข้าพบสองคนที่น่าจะใช้ได้\n\nคนแรก Dalin Forgewright อุทิศตนดูแลผู้ลี้ภัย Lordaeron ที่ญาติร่วมเผ่าปฏิเสธตรง Greymane Wall\n\nอีกคน Comar Villard ซื่อสัตย์ต่อรักที่เสียไป เดินหาเบาะแสภรรยาใน Wetlands\n\nนำหัวใจให้ Carendin แต่ก่อนขอชี้เป้าเหยื่อให้ดู", variants = { { "496:990415879:881342745", "ล่อซัคคิวบัสต้องใช้หัวใจผู้บริสุทธิ์ แต่มรรตัยคนใดไร้กิเลส?\n\nจากเรื่องที่ได้ยินทีละน้อย ข้าพบมนุษย์สองคนเหมาะ\n\nคนแรก Dalin Forgewright อุทิศตนดูแลผู้ลี้ภัย Lordaeron ที่ญาติร่วมเผ่าปฏิเสธตรง Greymane Wall\n\nอีกคน Corma Villard หญิงผู้ยังซื่อสัตย์ต่อรักที่เสียไป เดิน Wetlands หาร่องรอยหญิงคนรัก\n\nนำหัวใจให้ Carendin แต่ก่อนขอชี้เป้าเหยื่อให้ดู" } } },
        progress = { "71:1306513850:1589327667 N 57:1854314751:28394735", "ข้าแปลกใจยินดีกับความก้าวหน้ารวดเร็ว {name} นำหัวใจมาแล้วจะประทับใจอีกครั้ง" },
        completion = { "259:1047844275:122166717", "หัวใจคนดีมองอย่างนี้ก็เหมือนของคนอื่น ว่าไหม?\n\nบางทีเรามีมุมมอง... ต่าง... ในเรื่องนี้ แต่มันใช้ได้ แน่ใจว่าความบริสุทธิ์จะดึงซัคคิวบัสมา", variants = { { "256:763142848:677170002", "พอเห็นแบบนี้ หัวใจของผู้บริสุทธิ์ก็ดูเหมือนหัวใจคนอื่น ๆ ว่าไหม?\n\nบางทีเราคงมองเรื่องนี้... ต่างกันอยู่บ้าง... แต่หัวใจพวกนี้ใช้ได้ ข้ามั่นใจว่าความบริสุทธิ์ของมันจะล่อซัคคิวบัสมา" } } },
        required = { [6312] = { "13:1479221056:1021532863", "หัวใจของ Dalin" }, [6313] = { "13:1673915763:1195712792", "หัวใจของ Corma" } },
        steps = { { "13:1479221056:1021532863", "หัวใจของ Dalin" }, { "13:1673915763:1195712792", "หัวใจของ Corma" } },
    },
    [1478] = { -- Halgar's Summons
        title = { "16:47756931:692501379", "คำเรียกของ Halgar" },
        objective = { "44:1521645979:1660705794", "คุยกับ Carendin Halgar ใน Undercity" },
        description = { "4:1110228981:147916455 N 129:73555679:54240119 N 185:1129182124:2120493100", "อา {name}! เพิ่งได้ข่าว Carendin Halgar อยากพบเพื่อฝึกต่อ\n\nควรภูมิใจ {name} ไม่ใช่ทุกวันที่ Master Halgar เห็นควรสอนวอร์ล็อกรุ่นเยาว์ด้วยตนเอง\n\nหาเขาที่ Magic Quarter ใน Undercity ใกล้ Temple of the Damned" },
        completion = { "40:678276177:1911547718 N 126:782894247:770366499", "ดี Ageron หาพบแล้ว {name} อย่าเสียเวลากับคำทักทาย มาสนใจการฝึก ยังมีอีกมากให้เรียน" },
    },
    [1485] = { -- Vile Familiars
        title = { "14:2096056998:498448343", "อสูรรับใช้ชั่วร้าย" },
        objective = { "37:1083902933:1055009631", "นำ Vile Familiar Heads 6 ชิ้นไปให้ Ruzan" },
        description = { "454:1886404555:1716034737", "วอร์ล็อกรุ่นก่อนทำให้ Horde ไม่ไว้ใจ แม้ยอมให้เราอยู่ ก็ไม่รัก\n\nแต่นี่ไม่ได้ทำให้วอร์ล็อกใกล้กัน หลายคนเลือกปลีกวิเวกลองเวทลำพัง ข้าไม่ชี้ให้เลือกทางใด เพียงช่วยเติบโต\n\nก่อนสอนอัญเชิญ นำหัวอสูรรับใช้ชั่วร้ายจากถ้ำตะวันออกเฉียงเหนือมาหกชิ้น" },
        progress = { "144:1420790269:1912766163 C 90:1915812047:2130538920", "ต้องควบคุมสิ่งที่เรียกด้วยเวทได้ ผู้สนใจวิถี{class}ก็มีน้อยอยู่แล้ว การสอนสิ่งที่ยังไม่พร้อมอาจเสี่ยงทิ้งชีวิตเจ้า" },
        completion = { "30:71166233:1618866103 C 203:592288336:1061030825", "ระหว่างฝึกเป็น{class} จะเรียนเรียกสิ่งหลายชนิด แม้บางตัวดูไม่เหมือน แต่ทุกตัวเป็นเครื่องมือมีประโยชน์\n\nอย่าหลงขนาดเล็กของอิมป์ อย่างที่สังเกต มันยังเป็นคู่ต่อสู้ร้ายกาจ" },
        required = { [6487] = { "18:185960672:1171579735", "หัวของ Vile Familiar" } },
        steps = { { "18:185960672:1171579735", "หัวของ Vile Familiar" } },
    },
    [1499] = { -- Vile Familiars
        title = { "14:2096056998:498448343", "อสูรรับใช้ชั่วร้าย" },
        objective = { "28:665954805:1665607791", "คุยกับ Zureetha Fargaze" },
        description = { "312:783361997:1337362392", "Zureetha ส่งมือใหม่เช่นเจ้าช่วยลดสัตว์ในถ้ำใกล้ที่สู้พวกอสูรรับใช้\n\nข้าว่าช่วยนางจะได้ประสบการณ์ อย่าลืมบอกว่าช่วยปัญหาอิมป์ นางคงมีรางวัลให้" },
        completion = { "20:1921578502:569519135 N 150:1003965205:1506673221", "ทำดีแล้ว {name}\n\nแม้อสูรรับใช้เป็นเพียงสัตว์เลี้ยงของพลังมืดกว่าใน Burning Blade ความสำเร็จแสดงว่าจะมีวีรกรรมยิ่งใหญ่ข้างหน้า" },
    },
    [1501] = { -- Creature of the Void
        title = { "20:1762302849:713197538", "สิ่งมีชีวิตแห่งห้วงว่าง" },
        objective = { "63:596908038:1668012817", "นำ Tablet of Verga กลับมาให้ Gan'rul Bloodeye ใน Orgrimmar" },
        description = { "469:1075545455:714860879", "วอร์ล็อกเหลือน้อย... เราเสี่ยงมาก แต่คุ้ม เจ้าเร่งฝีมือให้เติบโต หากจะมีประโยชน์ Horde และ Warchief\n\nถึงเวลาเรียนอัญเชิญใหม่\n\nก่อนอื่นเอา Tablet of Verga คืน วอร์ล็อก Burning Blade ขโมยไว้รังที่ Skull Rock ตะวันออกเมือง ด้วยแผ่นจารึก ข้าจะแสดงรูนจำเป็นเรียก Voidwalker" },
        progress = { "33:1392325487:1787237154 N 55:1264599467:906789869", "มี Tablet of Verga หรือยัง {name}? หากไม่มี ข้าไม่อยากคุยจนกว่าจะได้" },
        completion = { "203:1716737570:1668047749", "ดี หวังว่าทำ Burning Blade เสียหายอย่างอื่นด้วยตอนกู้ของ\n\nมันสร้างความรำคาญใหญ่ให้ Warchief และเป็นมลทินต่อวอร์ล็อกทั้งหมด" },
        required = { [6535] = { "15:2105532265:1346648990", "แผ่นจารึกของ Verga" } },
        steps = { { "15:2105532265:1346648990", "แผ่นจารึกของ Verga" } },
    },
    [1504] = { -- The Binding
        title = { "11:105979108:1835480523", "พันธนาการ" },
        objective = { "132:1338153704:1743341391", "ใช้ Glyphs of Summoning อัญเชิญและสยบ Voidwalker แล้วคืน Glyphs of Summoning ให้ Gan'rul Bloodeye ใน Orgrimmar" },
        description = { "448:656941460:27260936", "ดู Tablet of Verga มีอักขระที่ต้องใช้ นำไปวงในกระโจม Neeru Fireblade อีกฝั่งถ้ำ ที่นั่นเรียก Voidwalker ได้\n\nต้องปราบด้วยวิธีทางกายและเวทที่มี เมื่อเสร็จ กลับพร้อมอักขระอัญเชิญ ข้าจะแสดงวิธีผูกมันตามเจตนา" },
        progress = { "88:1387718818:1702963014 N 152:481879269:268023141 N 1:46:46", "Voidwalker ทรงพลัง ข้าจำตอนอยู่จุดเดียวกับเจ้า {name} หลายปีมา ตัวของข้าต่อสู้น้อยลง แต่คงเพียงหวังให้เผลอ\n\nจำไว้ {name}" },
        completion = { "20:1921578502:569519135 N 311:897088100:1404316151", "ทำดีแล้ว {name} ข้าจะแสดงวิธีเรียก Voidwalker คล้ายตัวที่เพิ่งปราบ\n\nรู้ไว้ว่าเราหวังสูง และเจ้าทำได้ตรงคาดจนตอนนี้\n\nแต่อย่าหลงตัว งานข้างหน้าจะทำให้นี่ง่ายเหมือนตื่นเช้า" },
        required = { [7464] = { "19:1716920184:562557169", "อักขระสำหรับอัญเชิญ" } },
        steps = { { "19:1716920184:562557169", "อักขระสำหรับอัญเชิญ" } },
        objectiveLabels = {
            monster = { ["Summoned Voidwalker slain"] = "ปราบ วอยด์วอล์กเกอร์ที่ถูกอัญเชิญ" },
        },
    },
    [1506] = { -- Gan'rul's Summons
        title = { "17:1561820323:1585829776", "คำเรียกของ Gan'rul" },
        objective = { "41:1114203669:1594010065", "คุยกับ Gan'rul Bloodeye ใน Orgrimmar" },
        description = { "11:832768810:1518065742 N 253:1977301946:1810159667", "เจ้าตรงนั้น {name} ใช่ไหม?\n\nหวังว่าไม่ยุ่ง เพราะ Gan'rul อยากพบทันที อยู่กับวอร์ล็อกอาวุโสใน Cleft of Shadow\n\nจากที่ข้าเคยติดต่อ การเรียกนี้คงดีมากหรือร้ายมากอย่างใดอย่างหนึ่ง" },
        completion = { "191:1150664204:2100509000", "ดี กลัวว่า Ophek จะติดต่อไม่ถึง\n\nถึงเวลาฝึกวอร์ล็อกต่อ ธุระปัจจุบันต้องรอ\n\nเชื่อว่าคงไม่มีปัญหาใช่ไหม?", variants = { { "76:2025541783:1007444287 C 108:910775931:1972748755", "ดีแล้ว ข้านึกว่า Ophek จะติดต่อเจ้าไม่ถึง\n\nถึงเวลาที่ข้าจะฝึกวิชา{class}ให้เจ้าต่อ ธุระที่เจ้าทำอยู่ต้องรอไปก่อน\n\nข้าหวังว่าคงไม่มีปัญหาใช่ไหม?" } } },
    },
    [1507] = { -- Devourer of Souls
        title = { "17:904315564:180553437", "ผู้กลืนกินวิญญาณ" },
        objective = { "40:1544228016:801596945", "คุยกับ Cazul ใน Cleft of Shadow" },
        description = { "501:1415463607:983155213", "ถึงเวลาเรียนเวทอัญเชิญเพิ่ม เจ้าจะเรียกซัคคิวบัส ผู้มีพลังจิตเหลือเชื่อ กล่อมจิตอ่อนให้เป็นทาสได้ แต่อย่ากลัว! ข้าแน่ใจว่ารับมือได้\n\nเรียกได้เฉพาะเมื่อใช้ของแทนความรักและภักดีใหญ่หลวงล่อ ข้าให้เจ้าหาของเช่นนั้น\n\nคำแนะนำหรือ? คุยกับ Cazul... ดูเหมือนมีน้อยสิ่งที่วอร์ล็อกโบราณไม่รู้", variants = { { "497:274324669:160887600", "ถึงเวลาเรียนเวทอัญเชิญเพิ่ม เจ้าจะเรียกซายาด ผู้มีพลังจิตเหลือเชื่อ กล่อมจิตอ่อนให้เป็นทาสได้ แต่อย่ากลัว! ข้าแน่ใจว่ารับมือได้\n\nเรียกซายาดได้เฉพาะเมื่อใช้ของแทนความรักและภักดีใหญ่หลวงล่อ ข้าให้เจ้าหาของเช่นนั้น\n\nคำแนะนำหรือ? คุยกับ Cazul... ดูเหมือนมีน้อยสิ่งที่วอร์ล็อกโบราณไม่รู้" } } },
        completion = { "6:941278482:1019367179 N 110:1724424614:1123069619 N 35:1003025823:483385049", "หืม... {name} ยังใหม่ในวิถี แต่ข้าสัมผัสโอกาสยิ่งใหญ่ได้\n\nเจ้ามีพรสวรรค์แต่เกิด {name} อย่าให้สูญเปล่า" },
    },
    [1508] = { -- Blind Cazul
        title = { "11:400352905:1934995845", "Cazul ผู้ตาบอด" },
        objective = { "32:555137468:1886151080", "คุยกับ Zankaja ใน Orgrimmar" },
        description = { "235:140462546:1404038576 N 136:1892437403:974459073", "หืม... แน่นอน นั่นไม่ใช่เหตุที่มาคุย\n\nหาก Gan'rul ส่งมา คงจะเรียกซัคคิวบัสและต้องมีของล่อ\n\nหืม... หากไว้ใจคนตาบอดนำทาง {name} จงฟัง Zankaja อยู่หน้าผา Orgrimmar ทางตะวันตกของหอคอย Wind Rider นางรอคู่ครองกลับ\n\nไปหานาง", variants = { { "193:62216428:487611295 N 136:1892437403:974459073", "หาก Gan'rul ส่งมาหาข้า คงจะเรียกซัคคิวบัส เพศหญิงของเผ่าซายาด และต้องมีของล่อ\n\nหืม... หากไว้ใจคนตาบอดนำทาง {name} จงฟัง Zankaja อยู่หน้าผา Orgrimmar ทางตะวันตกของหอคอย Wind Rider นางรอคู่ครองกลับ\n\nไปหานาง" } } },
        completion = { "96:829135105:175055195", "มีข่าว Dogran หรือ? ควรกลับหลายวันแล้ว แต่ไม่ได้ยินอะไร..." },
    },
    [1509] = { -- News of Dogran
        title = { "14:1515146713:72199548", "ข่าวของ Dogran" },
        objective = { "36:2072074726:1782252213", "คุยกับ Gazrog ที่ Crossroads" },
        description = { "477:1427427437:2057324263", "Dogran คู่ข้าเพิ่งถูกส่งไปทำงาน Crossroads เป็นการเลื่อนตำแหน่ง เขาภูมิใจมาก\n\nแน่นอนข้าเศร้า แต่ไม่บอก และกังวลด้วย Barrens อันตรายกว่า Orgrimmar ข้ากลัวที่สุด\n\nตอนนี้เลยวันควรกลับหนึ่งสัปดาห์แล้ว ไม่มีข่าว...\n\nช่วยไป Crossroads ถามข่าวได้ไหม? เขาทำงานกับ Gazrog ที่คงยังประจำที่นั่น" },
        completion = { "196:250190194:17381596", "Zankaja? คู่ Dogran ใช่ไหม?\n\nใช่ มีข่าว แต่ไม่ควรให้นางรู้...\n\nไม่ เขายังไม่ตาย แต่บาดเจ็บและเป็นเชลยควิลบอร์" },
    },
    [1510] = { -- News of Dogran
        title = { "14:1515146713:72199548", "ข่าวของ Dogran" },
        objective = { "39:1129994823:303515756", "คุยกับ Ken'zigla ที่ Malaka'jin" },
        description = { "491:275455658:998483744", "เขาประจำ Camp Taurajo ที่เรากำลังกำจัดควิลบอร์ นำทหารออร์คบางคนไปค่ายแล้วเจ็บหนัก คนอื่นกลับมาแล้วพยายามช่วย สภาพเขาแย่ แผลเน่า จึงกลัวย้ายโดยไม่รักษาก่อน\n\nส่งข่าวมาขอยารักษาจากโทรลล์ Malaka'jin เชิง Stonetalon Mountains เราส่งคนไปเอา แต่ยังไม่กลับ" },
        completion = { "161:387736148:1592203266", "ออร์คอีกคนหรือ? หวังว่าไม่ได้มาตามอีกคน เขาไม่รอด ก็อบลินจัดการหนัก\n\nบอกแค่ต้องการยารักษา ไม่มากกว่านั้น" },
    },
    [1511] = { -- Ken'zigla's Draught
        title = { "19:826920135:1429383840", "ยาของ Ken'zigla" },
        objective = { "58:2108545809:466877112", "นำ Ken'zigla's Draught ไปให้ Grunt Logmar ที่ Camp Taurajo" },
        description = { "99:2110339902:1394459284 N 308:1683181797:50708545", "ข้าคิดว่าคงมีคนมาเอายาอีก จึงเตรียมไว้\n\nนี่ {name} จำไว้ ให้เขาแค่ครึ่งเดียว! จะมีกำลังพอเคลื่อนโดยไม่เสียเลือดหมดตัว รอหนึ่งคืนแล้วให้อีกครึ่ง\n\nอย่างไรก็นำให้ Logmar ที่ Camp Taurajo จากที่คนแรกบอก เขาน่าจะรู้ว่า Dogran อยู่ไหน" },
        progress = { "16:1205405492:147321852", "ใช่ มีอะไร?" },
        completion = { "185:2042891631:1513160517", "มาเสียที! Dogran ใกล้ตายอยู่ข้างนอกเพื่อรอสิ่งนี้\n\nต้องส่งให้ทันที แต่ทหารที่นี่ส่วนใหญ่ออกหาเสบียง" },
        required = { [6624] = { "19:826920135:1429383840", "ยาดื่มของ Ken'zigla" } },
        steps = { { "19:826920135:1429383840", "ยาดื่มของ Ken'zigla" } },
    },
    [1512] = { -- Love's Gift
        title = { "11:1085673463:1958963266", "ของขวัญแห่งรัก" },
        objective = { "62:643907327:1704694312", "นำ Dirt-caked Pendant ไปให้ Gan'rul Bloodeye ใน Orgrimmar" },
        description = { "120:1383258286:1046945893 N 180:1754339789:748036113", "Zankaja ยังสาวและงาม ต้องผูกชีวิตกับคนพิการ... ข้าไม่ยอมให้นางทรมานกับความอยุติธรรมนั้น\n\nทิ้งข้าไว้ {name} และขอบใจ ข้าอาจจบชีวิตในศึกอย่างมีเกียรติ แทนเป็นร่างไร้ชีวิตชีวา\n\nโปรดอย่าบอกคู่ข้า... ไม่อยากให้นางรู้สึกผิด" },
        progress = { "54:2050297095:1479943260", "กลับมาแล้ว พร้อมสู้ซัคคิวบัสหรือ?" },
        completion = { "57:871083950:416278235 N 98:1413959847:1248854820", "หากบอกว่านี่พอ ข้าก็เชื่อ {name} แต่ขอทำความสะอาดก่อน... เมื่อสะอาดเป็นประกาย อาจล่อซัคคิวบัสได้ยิ่งขึ้น" },
        required = { [6625] = { "18:597008294:2024299698", "จี้เปื้อนดินเกรอะกรัง" } },
        steps = { { "18:597008294:2024299698", "จี้เปื้อนดินเกรอะกรัง" } },
    },
    [1513] = { -- The Binding
        title = { "11:105979108:1835480523", "พันธนาการ" },
        objective = { "116:778142409:1147827334", "ใช้ Dogran's Pendant อัญเชิญและสยบ Succubus แล้วคืน Dogran's Pendant ให้ Gan'rul Bloodeye ใน Orgrimmar" },
        description = { "51:1393659906:1690064513 N 292:2144727522:1933955435", "นำไปวงอัญเชิญในกระโจม Neeru {name} เรียกซัคคิวบัสชั่วออกแล้วแสดงอำนาจ ข้าเชื่อพลังเวทเจ้า แต่ระวังเช่นเคย ความหยิ่งและมั่นใจเกินทำวอร์ล็อกมีแววล้มมามาก\n\nปราบแล้วคืนจี้ให้ข้า เพื่อส่งข่าว Zankaja" },
        progress = { "161:116685095:2144043518", "เมื่อมองซัคคิวบัส ใจข้าพองขึ้น... แต่พร้อมกันแทบสัมผัสวิญญาณไหลหายเหมือนน้ำลด\n\nระวัง สหาย" },
        completion = { "476:1326248493:1543664671", "สำเร็จ! แน่นอนข้าหวังไม่ต่ำกว่านี้จากศิษย์ดาวเด่น\n\nพิสูจน์คุณค่าแล้ว ยินดีสอนเรียกซัคคิวบัสที่สยบ ไปเถอะ ยังต้องเรียนมาก พบคราวหน้าข้าหวังว่าจะเชี่ยวชาญมันแท้\n\nทิ้งความเศร้า Dogran กับ Zankaja ให้พวกข้าที่แก่กว่า แต่จดจำไว้ป้องกันกลลวงพลังมืดที่เรียนเรียกวันนี้" },
        required = { [6626] = { "16:1818491743:564388794", "จี้ของ Dogran" } },
        objectiveLabels = {
            item = { ["Dogran's Pendant"] = "จี้ของ Dogran" },
            monster = { ["Summoned Succubus slain"] = "ปราบ ซัคคิวบัสที่ถูกอัญเชิญ" },
        },
    },
    [1515] = { -- Dogran's Captivity
        title = { "18:1608768329:1259521033", "Dogran ถูกจองจำ" },
        objective = { "51:1843480751:1997914511", "นำ Ken'zigla's Draught ไปให้ Dogran ใน Barrens" },
        description = { "370:1258184942:425573530", "มาไกลแล้ว หากอยากทำจนจบข้าไม่หยุด แต่ให้กำลังเพิ่มไม่ได้ ต้องพึ่งตัวเอง\n\nDogran ถูกกักในค่ายควิลบอร์ทางเหนือ มองหากระท่อมสองหลัง มีคนเฝ้าหนัก หากยังไม่ฆ่าหรือเขายังไม่ตายจากแผล\n\nโชคดี" },
        progress = { "12:2028903871:1989205264", "อื๊อกกก..." },
        completion = { "150:948869767:1289325357", "ยารสแย่...\n\nรู้สึกมีกำลังแล้ว พอกะเผลกหนี... แต่ขาจะเสียไปตลอดชีวิต แขนด้วย" },
        required = { [6624] = { "19:826920135:1429383840", "ยาดื่มของ Ken'zigla" } },
        steps = { { "19:826920135:1429383840", "ยาดื่มของ Ken'zigla" } },
    },
    [1598] = { -- The Stolen Tome
        title = { "15:838271794:135448595", "คัมภีร์ที่ถูกขโมย" },
        objective = { "54:2015927328:1164468890", "นำ Powers of the Void กลับมาให้ Drusilla La Salle" },
        description = { "11:832765469:1518064039 N 482:1050623696:920326306", "เฮ้ เจ้าน่ะ! {name} ใช่ไหม?\n\nข้าหวังว่าเจ้าคิดดีแล้วที่จะเป็นวอร์ล็อก ถ้าเอาตัวรอดด้วยตัวเองไม่ได้ เจ้าคงถูกฉุดให้จมลงไปด้วย\n\nข้าจะสอนเจ้า แต่ต้องแน่ใจก่อนว่าเจ้าแข็งแกร่งพอ\n\nมีศิษย์ฝึกหัดคนหนึ่งเคยเรียนอยู่ที่ Abbey แล้วหนีไปเข้ากับ Defias Brotherhood ข้าสนใจทำไมน่ะหรือ? ก็เพราะเขาขโมยหนังสือสำคัญไปหลายเล่ม\n\nหนึ่งในนั้นคือ Powers of the Void หนังสือที่ข้าอยากได้ไว้เอง ขโมยมาให้ข้าที พวกมันซ่อนไว้ในกระโจมของพวกมันที่ Vineyards" },
        progress = { "117:100856823:600425086", "ถ้าข้าไปขโมยหนังสือเองคงเป็นที่สังเกตเกินไป โชคดีที่มีเจ้าหน้าโง่คนหนึ่งในพวกมันลงมือทำงานสกปรกแทนข้า" },
        completion = { "336:414371942:719297230", "ยอดเยี่ยม... ข้าไม่เคยเข้าไปถึงหนังสือเล่มนี้ได้เลย มันถูกเก็บไว้ในปีกห้องสมุดที่มีคนคุ้มกัน ถ้าข้าไปเดินป้วนเปี้ยนแถวนั้นคงดูน่าสงสัย\n\nเจ้าเอาหนังสือมาได้ดีมาก ข้าเชื่อว่าเจ้าคงรับมืออิมป์ของตัวเองไหว ทีนี้ข้าก็สอนเจ้าเรียกอิมป์ได้แล้ว" },
        required = { [6785] = { "18:1721978034:871415739", "พลังแห่งความว่างเปล่า" } },
        steps = { { "18:1721978034:871415739", "พลังแห่งความว่างเปล่า" } },
    },
    [1599] = { -- Beginnings
        title = { "10:401191033:1007751546", "จุดเริ่มต้น" },
        objective = { "51:1404533200:864796435", "นำ Feather Charms 3 ชิ้นไปให้ Alamar Grimm ใน Anvilmar" },
        description = { "494:825814735:2098186346", "คงเป็นวอร์ล็อกใหม่ที่ทุกคนกระซิบถึง มีคนชอบแน่จึงขอให้ข้าทิ้งงานวิจัยมาฝึกเจ้า\n\nไม่ต้องห่วง ข้าไม่ถือ\n\nคาถาอัญเชิญง่ายสุดที่จะเรียนคืออิมป์ แต่ก่อนถ่ายทอด ต้องพิสูจน์กำลังเวทและกาย\n\nนำเครื่องรางขนนกจาก Frostmane Novice ในถ้ำตะวันตกเฉียงใต้มาสามชิ้น" },
        progress = { "165:1053629527:446084175", "เครื่องรางขนนกที่ศิษย์เหล่านั้นถือมีพลังเวทบางอย่าง น่าศึกษา ไม่คิดว่าจะได้จากโทรลล์" },
        completion = { "40:1483903165:1662740317 N 262:1267784717:1152110759 C 24:554385781:253190272 N 7:1448354517:1831712619 R 69:334416060:2015008832", "ดีมาก ดีมาก! ทำดีแล้ว {name} บางทีความสนใจที่ได้รับก็สมควร\n\nให้คนอื่นตัดสิน หากอิมป์ไม่ปราบเจ้าแล้วจบอาชีพตั้งแต่เริ่ม ตอนนี้ข้าพอใจว่าคงรอดสองสามเดือนแรกในฐานะ{class}\n\nเรื่องอิมป์นะ {name} อย่างที่ชาว{race}รู้ อย่าให้ขนาดหลอก เวทมันอันตรายมาก" },
        required = { [6753] = { "13:1028011408:334452444", "เครื่องรางขนนก" } },
        steps = { { "13:1028011408:334452444", "เครื่องรางขนนก" } },
    },
    [1685] = { -- Gakin's Summons
        title = { "15:1823818458:1225493026", "คำเรียกของ Gakin" },
        objective = { "64:1982846850:849126769", "รายงานตัวกับ Gakin the Darkbinder ใน Mage Quarter ของ Stormwind" },
        description = { "501:1592283082:1055393183", "เป็นอย่างนี้เสมอใช่ไหม? ตามทั้งวันไม่พบ พอไม่คาดกลับเดินมาหา\n\nเสียเวลาตามพอแล้ว ไม่หน่วงอีก Master Gakin เรียกฝึกเพิ่ม ควรไปหาโดยเร็ว\n\nเขาอยู่ใต้ดินโรงเตี๊ยม Slaughtered Lamb อ้อ เก็บสถานที่นี้เงียบไว้ ไม่อยากให้ข่าวแพร่" },
        completion = { "241:1392660551:1964034302", "มาเสียที บางทีควรส่งคนเก่งกว่า Remen ไปตาม\n\nช่างเถอะ\n\nเว้นฝึกนานเกิน วอร์ล็อกไร้ฝึกคงรักษาหัวบนบ่าได้ไม่นาน" },
    },
    [1688] = { -- Surena Caledon
        title = { "14:588442774:837127624", "Surena Caledon" },
        objective = { "63:264252601:1145325171", "นำ Surena's Choker กลับมาให้ Gakin the Darkbinder ใน Stormwind" },
        description = { "505:1227821718:2096419943", "เคยมีศิษย์ชื่อ Surena Caledon ยืนจุดเดียวกับเจ้าตอนนี้ อยากเรียนเวทวอร์ล็อกและมีพรสวรรค์ไม่น้อย ยังสาวและงาม หากข้ารู้ทันตั้งแต่ตอนนั้น นางคนทรยศ!\n\nนางหัวขโมยหนีไปกับ Defias ชื่อ Erlan Drudgemoor เสียศิษย์ไม่สำคัญ แต่ข้าให้สร้อย Bloodstone ที่ต้องเอาคืน\n\nชีวิตนางไม่มีค่าสำหรับข้าแล้ว พบได้ที่ Brackwell Pumpkin Patch เอาของข้าคืน" },
        progress = { "75:1934978393:1115496443 N 71:1639620443:1694041366", "แม้คนแก่และฉลาดกว่าก็เสียหลักกับกลวัยเยาว์และความงามได้ {name} เป็นคำแนะนำควรจำตลอดชีวิต" },
        completion = { "206:593946396:1580176574", "Surena มีแวว แต่ไม่พอเชี่ยวชาญเวทวอร์ล็อกลำพัง น่าเสียดายที่เสียพรสวรรค์ แต่บางครั้งจำเป็น\n\nหวังว่าการลงทุนในเจ้าจะได้ผลต่างกัน" },
        required = { [6810] = { "15:170290687:2019286793", "สร้อยคอแนบคอของ Surena" } },
        steps = { { "15:170290687:2019286793", "สร้อยคอแนบคอของ Surena" } },
    },
    [1689] = { -- The Binding
        title = { "11:105979108:1835480523", "พันธนาการ" },
        objective = { "132:913332362:815261073", "ใช้ Bloodstone Choker อัญเชิญและสยบ Voidwalker แล้วคืน Bloodstone Choker ให้ Gakin the Darkbinder ใน Stormwind" },
        description = { "503:763885581:1473221675", "เอาสร้อยคืนและชนะ Surena พิสูจน์ว่าฝีมืออย่างน้อยเท่านาง\n\nแต่เห็นชัดว่าต้องฝึกด่วน เจ้าจัดกระแสเวทได้ก็จริง แต่วอร์ล็อกมีมากกว่านั้น\n\nข้าจะสอนสั่ง Voidwalker แต่ก่อนต้องเรียกที่วงอัญเชิญแล้วสยบด้วยอาวุธกายหรือเวทที่มี ใช้เวทสร้อยที่วงด้านล่าง" },
        progress = { "75:316012176:784435149", "ข้าสอนควบคุม Voidwalker ไม่ได้จนกว่าเจ้าจะสยบได้สักตน" },
        completion = { "32:1183794149:1197694598 N 248:982485127:847811854 N 1:46:46", "ทำดีกว่าคาด {name} แต่สมหวัง ทีนี้เรียนสั่ง Voidwalker ที่พิชิตได้ เป็นพันธมิตรมีค่าในบททดสอบข้างหน้าแน่นอน\n\nตอนนี้ไม่มีอะไรสอนเพิ่ม แต่ยังไม่จบกับเจ้าแน่ {name}" },
        required = { [6928] = { "17:725129431:1953275459", "สร้อยคอแนบคอประดับ Bloodstone" } },
        steps = { { "17:725129431:1953275459", "สร้อยคอแนบคอประดับ Bloodstone" } },
        objectiveLabels = {
            monster = { ["Summoned Voidwalker slain"] = "ปราบ วอยด์วอล์กเกอร์ที่ถูกอัญเชิญ" },
        },
    },
    [1715] = { -- The Slaughtered Lamb
        title = { "20:1092958318:769157259", "Slaughtered Lamb" },
        objective = { "64:1982846850:849126769", "รายงานตัวกับ Gakin the Darkbinder ใน Mage Quarter ของ Stormwind" },
        description = { "476:109751881:779095665", "ฮึ เมื่อก่อนวอร์ล็อก Khaz Modan ฝึกใต้การดูแลปรมาจารย์ Gnomeregan แต่เมื่อถูกบังคับย้ายมาในรูหนู Ironforge และ Magni จับตา เราต้องส่งศิษย์ไปฝึก Stormwind\n\nโชคดี Gakin ไม่ใช่กระจอก ยังได้เรียนที่จำเป็น แต่ข้าเดือดดาล!\n\nอย่างไรก็หา Gakin ใต้ดิน Slaughtered Lamb ใน Stormwind" },
        completion = { "230:414120077:288408631", "Blackwrench ส่งมาหรือ? พวกวอร์ล็อก Ironforge ต้องจัดการกันเสียที Stormwind มีที่กับครูจำกัด คนเพิ่มอย่างนี้ไม่ช้าก็เร็วคงดึงสายตา" },
    },
    [1716] = { -- Devourer of Souls
        title = { "17:904315564:180553437", "ผู้กลืนกินวิญญาณ" },
        objective = { "41:544586749:2033568144", "คุยกับ Takar the Seer ใน Barrens" },
        description = { "501:861114771:185620214", "ซัคคิวบัสกลืนวิญญาณ ทำลายหัวใจ และครอบงำจิต รู้จักแต่ชั่วร้าย\n\nเจ้าจะเรียนเรียกและควบคุมมัน แต่ไม่มีสิ่งกระตุ้นก็พามาโลกเราไม่ได้\n\nใช้สัญลักษณ์รักล่อ มันจะตอบรับ แล้วปราบให้เป็นเครื่องมือได้\n\nแต่ของเช่นนี้หายาก คุยกับ Takar the Seer พบใน Barrens แห่ง Kalimdor ใกล้ Camp Taurajo", variants = { { "501:1353815304:871421382", "ซายาดกลืนวิญญาณ ครอบงำเจตนา และล่อลวงหัวใจ รู้จักแต่ชั่วร้าย\n\nเรื่องเล่าเสน่หาเรียกชื่อทั่วไป ซัคคิวบัสสำหรับเพศหญิง อินคิวบัสสำหรับเพศชาย\n\nต้องมีสิ่งกระตุ้นเรียก ใช้สัญลักษณ์รักล่อ มันจะตอบรับแน่ ปราบให้เป็นเครื่องมือ\n\nแต่ของเช่นนี้หายาก คุยกับ Takar the Seer พบใน Barrens แห่ง Kalimdor ใกล้ Camp Taurajo" } } },
        completion = { "29:1730461352:575057485 N 144:572568391:290774806", "ข้ามฝั่งลำบากไหม {name}? มาไกลเพื่อคุย แต่ไม่ต้องกลัว ข้ารู้ทำไม Gakin ส่งมา เขาฉลาด เพราะข้าช่วยค้นหาได้" },
    },
    [1717] = { -- Gakin's Summons
        title = { "15:1823818458:1225493026", "คำเรียกของ Gakin" },
        objective = { "64:1982846850:849126769", "รายงานตัวกับ Gakin the Darkbinder ใน Mage Quarter ของ Stormwind" },
        description = { "N 234:1775423800:1689705242", "{name}! ไม่คาดเห็นแถวนี้ แต่มีคำสั่งให้มองหา\n\nควรฝึกเพิ่มนานแล้ว คราวหน้าเข้า Stormwind แวะหา Gakin เขาจะรอ" },
        completion = { "48:1688307202:1266175378 N 181:362429465:1518499006", "ยินดีที่มีคนติดต่อถึง {name} เริ่มกลัวที่สุด คงเสียดายเสียเจ้าไปหลังลงทุนเวลามาก\n\nไว้คุยทีหลัง ตอนนี้การฝึกสำคัญอย่างเดียว" },
    },
    [1738] = { -- Heartswood
        title = { "10:2030295820:1803368284", "Heartswood" },
        objective = { "109:794218455:161260552", "นำ Heartswood จาก Ashenvale ไปให้ Gakin the Darkbinder ใน Mage Quarter ของ Stormwind" },
        description = { "444:998346699:178084658", "เพื่อเตรียมรับเจ้า ข้าใช้ญาณมองทั่วโลกและหมอกเวลา พบสิ่งที่หาแล้ว\n\nใน War of the Ancients คู่รักสองคนล้มในศึกด้วยกัน ที่สิ้นลมหายใจมีต้น Heartswood งอก เป็นสัญลักษณ์รักไม่ตาย\n\nน่าพอล่อซัคคิวบัส พบในซาก Ordil'Aran ทางตะวันตกเฉียงเหนือของป่า Ashenvale" },
        progress = { "27:2132341509:118646468 N 1:63:63", "ค้นหาสำเร็จไหม {name}?" },
        completion = { "192:621680690:1053186983", "ใช่ ใช้ได้ดี ขอจัดการสักครู่...\n\nTakar เป็นคนมีวิธีช่วยดีจริงใช่ไหม? หากกล่อมให้กลับมาอยู่ในอารยธรรมได้ก็ดี" },
        required = { [6912] = { "10:2030295820:1803368284", "ไม้ Heartswood" } },
        steps = { { "10:2030295820:1803368284", "ไม้ Heartswood" } },
    },
    [1739] = { -- The Binding
        title = { "11:105979108:1835480523", "พันธนาการ" },
        objective = { "137:215212878:2049122608", "ใช้ Heartswood Core อัญเชิญและสยบ Succubus แล้วคืน Heartswood Core ให้ Gakin the Darkbinder ที่ Slaughtered Lamb" },
        description = { "166:1214699530:207670715 N 162:910497617:1469791416", "Heartswood Core ให้เจ้าร่ายที่วงในสุสานใต้ดินด้านล่าง เปิดประตูให้ซัคคิวบัสผ่าน\n\nระวัง {name} ซัคคิวบัสพิชิตแม้จิตแกร่งที่สุดมาแล้ว\n\nเมื่อชนะส่งกลับห้วงว่าง มาหาข้า จะสอนเรียกและควบคุม" },
        progress = { "135:1105345944:842213107", "บางครั้งสงสัย Surena เป็นซัคคิวบัสปลอมมาบิดจิตหรือเปล่า... ฮ่า! ข้าคงให้ค่านางมากไป" },
        completion = { "22:1241268598:681858976 N 193:1272585033:2016597516", "ดีมาก ดีมาก {name} เราคิดถูกที่ฝึกเจ้า ผลงานไม่ผิดหวังเลย\n\nข้าไม่มีข้อกังขาจะสอนควบคุมซัคคิวบัสที่เพิ่งผูก ตั้งใจดู" },
        required = { [6913] = { "15:588783745:1148593233", "แก่นไม้ Heartswood" } },
        steps = { { "15:588783745:1148593233", "แก่นไม้ Heartswood" } },
        objectiveLabels = {
            monster = { ["Summoned Succubus slain"] = "ปราบ ซัคคิวบัสที่ถูกอัญเชิญ" },
        },
    },
    [1740] = { -- The Orb of Soran'ruk
        title = { "20:2060570787:2084328332", "ลูกแก้ว Soran'ruk" },
        objective = { "104:766672347:1849450872", "หา Soran'ruk Fragments 3 ชิ้น และ Large Soran'ruk Fragment 1 ชิ้น นำกลับไปให้ Doan Karhan ใน Barrens" },
        description = { "503:592900952:578937037", "เมื่อปีศาจ Legion หมดความโปรดปราน วิญญาณจะถูกกักในลูกแก้วแจกให้จอมเวทกับวอร์ล็อก\n\nผู้รับใช้หลายคนถือมา Azeroth แม้แตกก็ยังมีพลังปีศาจข้างใน\n\nลูกแก้ว Soran'ruk แตกสองส่วน ส่วนหนึ่งแตกย่อยให้ศิษย์ Twilight's Hammer ใช้ใน Blackfathom Deeps อีกส่วนใหญ่กว่าอยู่กับพ่อมด Shadowfang Keep หาให้ครบ ข้าจะประกอบคืน" },
        progress = { "143:275504430:885380493", "ข้าใช้หลายปีเก็บเศษลูกแก้ว Zargain แต่มันรับใช้ดี เช่นที่เชื่อว่า Soran'ruk จะรับใช้เจ้า" },
        completion = { "381:617746797:1037682055", "ใช่... ลูกแก้วไม่ได้แตกมาก และชิ้นส่วนแทบครบ ประกอบให้ Soran'ruk สมบูรณ์ไม่ยาก\n\nข้าอุทิศชีวิตศึกษาลูกแก้ว Burning Legion และสร้างคืน เจ้าช่วยเก็บชิ้นส่วนให้ศึกษา ข้าจะคืนที่ประกอบแล้วเต็มชิ้น ในรูปแบบที่เลือก", variants = { { "379:1758875778:66640418", "ใช่... ลูกแก้วแตกไม่มาก และชิ้นส่วนก็อยู่เกือบครบ จะประกอบให้ Soran'ruk กลับมาสมบูรณ์อีกครั้งก็ไม่ยาก\n\nข้าอุทิศทั้งชีวิตให้กับการศึกษาลูกแก้วของ Burning Legion และวิธีประกอบมันขึ้นใหม่ เจ้าช่วยเก็บชิ้นส่วนเหล่านี้มาให้ข้าศึกษา ข้าจะประกอบให้สมบูรณ์แล้วคืนให้ในรูปแบบที่เจ้าเลือก" } } },
        required = { [6914] = { "18:1678577607:1706389626", "เศษชิ้นส่วน Soran'ruk" }, [6915] = { "24:1302207364:470170704", "เศษชิ้นส่วน Soran'ruk ขนาดใหญ่" } },
        steps = { { "18:1678577607:1706389626", "เศษชิ้นส่วน Soran'ruk" }, { "24:1302207364:470170704", "เศษชิ้นส่วน Soran'ruk ขนาดใหญ่" } },
    },
    [1758] = { -- Tome of the Cabal
        title = { "17:1914556970:312440767", "คัมภีร์ Cabal" },
        objective = { "38:1622138383:607452172", "คุยกับ Krom Stoutarm ใน Ironforge" },
        description = { "493:1298444591:1607070334", "ต้องมากกว่าวงอัญเชิญธรรมดาจึงเรียก Felhunter ให้ท้าสู้ได้\n\nข้ากับศิษย์สามคนจะช่วยสร้างวงเวท เจ้าต้องมี Tome of the Cabal ที่สูญไปนาน เขียนโดยวอร์ล็อกกลุ่มแรกที่เรียก Felhunter โดยไม่พึ่งผู้ช่วย\n\nบางที Krom Stoutarm ช่วยได้ ทุกวันนี้เป็นวอร์ล็อกเร่ร่อน ใช้เวลาเก็บคัมภีร์โบราณและหลบในห้องสมุด Ironforge" },
        completion = { "203:1274865442:1048842178", "Tome of the Cabal? หืม... คุ้น ไม่เคยเห็นที่นี่ แต่เชื่อเถอะ จำหนังสือทุกเล่มที่อ่านได้\n\nหืม...\n\nอา ใช่! เคยเห็นการอ้างถึงในบัญชีห้องสมุด" },
    },
    [1795] = { -- The Binding
        title = { "11:105979108:1835480523", "พันธนาการ" },
        objective = { "123:527470469:1329969974", "ใช้ Tome of the Cabal อัญเชิญและสยบ Felhunter แล้วคืน Tome of the Cabal ให้ Strahad Farsan ใน Ratchet" },
        description = { "364:1045779187:132425364 N 90:1242041873:174447485", "หากเตรียมพอ มาเริ่ม ข้าจะอธิบาย\n\nข้าสร้างวงพื้นฐานก่อน เสร็จแล้วศิษย์ใช้แท่งรวมพลังสร้างวงใหญ่\n\nจากนั้นอ่านคาถาใน Tome of the Cabal แล้ว Felhunter จะถูกเรียก ระวัง {name} มันทรงพลัง ข้าอยากเห็นหัวเจ้าอยู่บนบ่าต่อ" },
        progress = { "143:11420343:1775630632", "วอร์ล็อกทุกคนควรมี Felhunter แม้ฝึกยาก พลังที่มอบแก่นายคุ้มราคามากกว่า" },
        completion = { "26:840162635:2134711016 N 157:84179405:403625456", "ต้องบอกว่าประทับใจ {name} เมื่อข้าเผชิญ Felhunter แทบไม่รอด สัมผัสว่าเจ้าอาจเป็นวอร์ล็อกทรงพลังที่สุดคนหนึ่งในยุค" },
        required = { [6999] = { "17:1914556970:312440767", "คัมภีร์แห่งกลุ่มลับ" } },
        steps = { { "17:1914556970:312440767", "คัมภีร์แห่งกลุ่มลับ" } },
        objectiveLabels = {
            monster = { ["Summoned Felhunter slain"] = "ปราบ เฟลฮันเตอร์ที่ถูกอัญเชิญ" },
        },
    },
    [1796] = { -- Components for the Enchanted Gold Bloodrobe
        title = { "43:2051054028:722437535", "ส่วนประกอบ Enchanted Gold Bloodrobe" },
        objective = { "62:1882900051:1561718986", "นำ Robes of the Arcana ไปให้ Menara Voidrender ใน Barrens" },
        description = { "502:2000093701:1155013576", "ของแรกที่ช่วยสร้างคือเสื้อคลุม เจ้าเก็บวัสดุ เราจะประกอบ หลังสำเร็จ จะเป็นชิ้นแรกในบรรดาของที่เพิ่มพลังและช่วยต่อสู้มากมาย\n\nเริ่มด้วย Robes of Arcana ที่สร้างขึ้น ช่างตัดเย็บทำให้ได้ หรือซื้อจากผู้อื่น ข้าจะประทับใจมากหากทำเอง แต่จะอย่างไรก็นำเสื้อมา แล้วเริ่มจากนั้น" },
        progress = { "36:834940263:1250710479 N 280:646251837:496266325", "หาเสื้อเป็นอย่างไร {name}? ทำเองไหม? ข้าพบว่ารายละเอียดส่วนตัวทำการใส่เวทหวานขึ้น รู้สึกสำเร็จมากกว่า แต่เข้าใจหากเลือกเร็วโดยให้คนทำ มีบางอย่างน่าพูดถึงความ... ทะเยอทะยานเช่นนั้น" },
        completion = { "21:1129349402:1903439022 N 290:57101488:1580568659", "ใช้ได้ดี {name}\n\nของเวททุกชิ้นต้องเริ่มจากของคุณภาพสูง ยิ่งใช้แรงและฝีมือ ยิ่งรับเวทมาก วัสดุหายากแพงเก็บเวทดีกว่า เจ้าจะไม่เสียใจที่แปรเสื้อนี้เป็นสิ่งที่จะทำภายหลัง" },
        required = { [5770] = { "15:171996674:32638053", "เสื้อคลุมแห่งมนตรา" } },
        steps = { { "15:171996674:32638053", "เสื้อคลุมแห่งมนตรา" } },
    },
    [1798] = { -- Seeking Strahad
        title = { "15:104362230:1666271580", "ตามหา Strahad" },
        objective = { "41:751326323:414234924", "คุยกับ Strahad Farsan ใน Barrens" },
        description = { "48:207535104:537099991 N 264:769194239:2144214123", "ถึงเวลาเรียนเรียก Felhunter {name} ข้าไม่มีวัสดุและของจำเป็นสอนที่นี่ จึงต้องหาอีกคน Strahad Farsan สมาชิกวงในเรา\n\nเขาอยู่ท่าเรือก็อบลิน Ratchet ข้าจะส่งข่าวล่วงหน้าว่าเจ้าจะมา" },
        completion = { "N 167:682753402:595071084", "{name}? อา แน่นอน อัจฉริยะล่าสุด ตัวจริงคงสู้ตำนานไม่ไหว ข้าเกรงว่าอย่างนั้น\n\nช่างเถอะ มาที่นี่เพื่อเรียน ไม่ใช่ฟังข้าพูดมุกคนเดียว" },
    },
    [1799] = { -- Fragments of the Orb of Orahil
        title = { "30:285216063:935742432", "เศษลูกแก้ว Orahil" },
        objective = { "164:702982900:1899665369", "คุยกับศิษย์ Menara ในหอคอยเหนือ Ratchet แล้วเลือกหนึ่งเส้นทาง\n\nจากนั้นนำ Infernal Orb ไปให้ Tabetha ใน Dustwallow Marsh" },
        description = { "480:463580028:263762319", "ดี มาเริ่ม\n\nก่อนอื่นคุยกับศิษย์ข้างใน เลือกหนึ่งเส้นทาง พวกเขาจะอธิบาย\n\nอย่างที่สอง ไป Desolace หา Infernal Orb จากวอร์ล็อก Mannoroc Coven เจ้าจะชำระลูกแก้วโดยให้จอมเวท Tabetha ลึกใน Dustwallow Marsh ทางใต้ช่วย นางยอมเพราะประวัติร่วมกันของเรา\n\nอย่ากลับจนทำครบทั้งสองเรื่อง" },
        progress = { "211:104433399:336650699 C 6:898443352:1601115061 C 65:1581019035:702187811 N 1:63:63", "เห็นว่าไม่ใช่จอมเวท ข้าสงสัยจะไว้ใจได้ไหม ดมพลังอาร์เคนได้ แต่ดูเลี่ยงกลิ่นแปดเปื้อนที่มักมากับพวกเจ้า\n\nใช่ {class}... {class}มาขอข้าช่วย\n\nมีอะไรให้ทำ {name}?" },
        completion = { "252:616518253:2108896660", "อ้อ Menara ส่งมา เช่นนั้นก็ได้... อยู่เป็นแขกชั่วคราว แต่คงมีธุระด่วน บางทีมาหาพลังสูญหาย? หรือข้าคิดผิด บางทีความแปดเปื้อนก็ไม่ได้ไกลจากเจ้าขนาดนั้น" },
        required = { [7291] = { "12:1367673073:664362773", "ลูกแก้วอินเฟอร์นัล" } },
        steps = { { "12:1367673073:664362773", "ลูกแก้วอินเฟอร์นัล" } },
    },
    [1801] = { -- Tome of the Cabal
        title = { "17:1914556970:312440767", "คัมภีร์ Cabal" },
        objective = { "42:783192023:72148853", "คุยกับ Jorah Annison ใน Undercity" },
        description = { "489:820090461:734257382", "ต้องมากกว่าวงอัญเชิญธรรมดาจึงเรียก Felhunter ให้ท้าสู้ได้\n\nข้ากับศิษย์สามคนจะช่วยสร้างวงเวท เจ้าต้องมี Tome of the Cabal ที่สูญไปนาน เขียนโดยวอร์ล็อกกลุ่มแรกที่เรียก Felhunter โดยไม่พึ่งผู้ช่วย\n\nบางที Jorah Annison ช่วยได้ ทุกวันนี้เป็นนักทำแผนที่ใน Undercity แต่ยังรู้คัมภีร์โบราณมากกว่าใครที่ข้ารู้จัก" },
        completion = { "255:1151977940:2064327067", "ทำแผนที่! ภาพ การคาดคะเนความจริง ข้าไม่ต้องการ\n\nในหนังสือ เรื่องเล่า คำอธิบาย! ความจริงอยู่ที่นั่น ข้าแลกแผนที่ทั้งร้านกับหนังสือกำเนิดวิชาปลุกศพเล่มเดียว หรือเรื่องชัยชนะ Dark Lady ได้เลย" },
    },
    [1802] = { -- Tome of the Cabal
        title = { "17:1914556970:312440767", "คัมภีร์ Cabal" },
        objective = { "79:1867135807:1583317909", "นำ Moldy Tome และ Tattered Manuscript กลับไปให้ Krom Stoutarm ใน Ironforge" },
        description = { "488:401466790:725397838", "มันหาย แต่พอรู้ว่าจะพบที่ไหน\n\nมีเพียงฉบับเดียว เคยถูกทำลาย หน้าใหญ่ส่วนหนึ่งถูกฉีกจากสัน ลือว่าตกถึงมือเซนทอร์ Thousand Needles\n\nส่วนที่เหลือหายนอกชายฝั่งตะวันตก Southshore ระหว่างจะส่งเรือไป Menethil Harbor ไม่เคยถึง\n\nแลกความรู้นี้ ข้าขอเพียงหากพบ นำมาให้เห็นด้วย" },
        progress = { "27:535304510:163843862 N 1:63:63", "ข่าวลือจริงไหม {name}?" },
        completion = { "140:1842544272:1805423215 N 118:1532608398:1876896886", "วิเศษ! ทีนี้ข้าจะเป็นหนึ่งในไม่กี่คนที่เห็นเนื้อหา\n\nแทบรออ่านต่อไม่ไหว วันยิ่งใหญ่ {name}! ขอเพียงดูสักหน่อยก่อนจาก แน่ใจว่า Strahad ยอมส่งสำเนาให้" },
        required = { [6931] = { "10:482037467:1346780787", "ตำราขึ้นรา" }, [6997] = { "19:1426509341:1235046827", "ต้นฉบับขาดรุ่งริ่ง" } },
        steps = { { "10:482037467:1346780787", "ตำราขึ้นรา" }, { "19:1426509341:1235046827", "ต้นฉบับขาดรุ่งริ่ง" } },
    },
    [1803] = { -- Tome of the Cabal
        title = { "17:1914556970:312440767", "คัมภีร์ Cabal" },
        objective = { "83:864545282:2132872727", "นำ Moldy Tome และ Tattered Manuscript กลับไปให้ Jorah Annison ใน Undercity" },
        description = { "502:409035656:1194599544", "อา! วอร์ล็อกรสนิยมคล้ายข้า การหา Tome of the Cabal เป็นเป้าหมายคู่ควร รู้ไหมครั้งหนึ่งอยู่ใน Lordaeron? แต่ถูกทำลาย เอาหน้าไปแทบครึ่ง ใครทำสิ่งเลวร้ายเช่นนั้น?\n\nครึ่งนั้นหาย ลือว่าตกถึงมือเซนทอร์ Thousand Needles\n\nส่วนที่เหลือจะส่ง Ironforge แต่หายระหว่างทางตรงชายฝั่งตะวันตก Southshore" },
        progress = { "50:2100878020:620814971 N 66:1157378730:1481359342", "อาจกำลังไล่นิทาน {name} แต่กลางข่าวลือบ้าที่สุดก็พบความจริงได้" },
        completion = { "58:376243960:1992934094 N 182:1878428444:251219097", "อ้าว ๆ มีอะไรนี่?\n\nน่าประทับใจ {name} ไม่คิดว่าเป็นไปได้ แต่ตอนนี้ Tome of the Cabal สมบูรณ์อยู่ในมือ\n\nขอพลิกดูสักครู่ก่อนเจ้าไปอีก" },
        required = { [6931] = { "10:482037467:1346780787", "ตำราขึ้นรา" }, [6997] = { "19:1426509341:1235046827", "ต้นฉบับขาดรุ่งริ่ง" } },
        steps = { { "10:482037467:1346780787", "ตำราขึ้นรา" }, { "19:1426509341:1235046827", "ต้นฉบับขาดรุ่งริ่ง" } },
    },
    [1804] = { -- Tome of the Cabal
        title = { "17:1914556970:312440767", "คัมภีร์ Cabal" },
        objective = { "83:2040587239:390494179", "นำ Reconstructed Tome และ Rods of Channeling 3 ชิ้นไปให้ Strahad Farsan ใน Ratchet" },
        description = { "500:1587200922:1649217778", "เอ่อ ปล่อยไปยาก แต่เจ้าหาพบและมีงานสำคัญกว่า แน่นอน โปรดบอก Strahad ว่าข้าอยากได้สำเนา\n\nระหว่างไม่อยู่ เขาฝากข่าวว่า หากจะให้ศิษย์ช่วยอัญเชิญ ต้องหาแท่งรวมพลังสามชิ้น\n\nเขาอาจไม่รู้แหล่ง แต่ข้ารู้! ล่าสุดออร์ค Dragonmaw ใน Wetlands ใช้ ลองดูผู้ร่ายเวท!" },
        progress = { "86:1913606955:1282484587", "ไม่เห็นแถวนี้นาน พบคัมภีร์กับแท่งหรือยัง?" },
        completion = { "208:1540921968:1472378465", "ทำดี! Tome of the Cabal และแท่งรวมพลังไร้ตำหนิสามชิ้น เอ่อ มีรอยนิดหน่อยก็ได้\n\nน่าสนใจ นานแล้วที่วอร์ล็อกรุ่นเยาว์ท้าสู้ Felhunter เพื่อให้เป็นของตน" },
        required = { [7006] = { "18:1696282542:2059101959", "คัมภีร์ที่ประกอบขึ้นใหม่" }, [6930] = { "17:1243767942:238341691", "คทาสำหรับถ่ายทอดพลัง" } },
        steps = { { "18:1696282542:2059101959", "คัมภีร์ที่ประกอบขึ้นใหม่" }, { "17:1243767942:238341691", "คทาสำหรับถ่ายทอดพลัง" } },
    },
    [1805] = { -- Tome of the Cabal
        title = { "17:1914556970:312440767", "คัมภีร์ Cabal" },
        objective = { "83:2040587239:390494179", "นำ Reconstructed Tome และ Rods of Channeling 3 ชิ้นไปให้ Strahad Farsan ใน Ratchet" },
        description = { "499:781968925:549773088", "นี่หนึ่งในหนังสือน่าสนใจที่สุดที่อ่านหลายปี หนังสือที่นี่น้อย ส่วนใหญ่ภูมิศาสตร์ ข้าอ่านหมดแล้ว หวังว่า Strahad ส่งสำเนาเมื่อมีโอกาส\n\nพูดถึงเขา ฝากข่าวมาตอนไม่อยู่ งานเจ้าต้องใช้แท่งรวมพลังสามชิ้น\n\nที่ยอมให้ข้าดูหนังสือ จะบอกความลับ พบแท่งได้จากออร์ค Dragonmaw ใน Wetlands" },
        progress = { "5:1287366450:669725923 N 34:1160725676:18835198", "ว่าอย่างไร {name}? ข้ารับใช้อะไรได้?" },
        completion = { "208:1540921968:1472378465", "ทำดี! Tome of the Cabal และแท่งรวมพลังไร้ตำหนิสามชิ้น เอ่อ มีรอยนิดหน่อยก็ได้\n\nน่าสนใจ นานแล้วที่วอร์ล็อกรุ่นเยาว์ท้าสู้ Felhunter เพื่อให้เป็นของตน" },
        required = { [7006] = { "18:1696282542:2059101959", "คัมภีร์ที่ประกอบขึ้นใหม่" }, [6930] = { "17:1243767942:238341691", "คทาสำหรับถ่ายทอดพลัง" } },
        steps = { { "18:1696282542:2059101959", "คัมภีร์ที่ประกอบขึ้นใหม่" }, { "17:1243767942:238341691", "คทาสำหรับถ่ายทอดพลัง" } },
    },
    [2996] = { -- Seeking Strahad
        title = { "15:104362230:1666271580", "ตามหา Strahad" },
        objective = { "35:57723190:1069512475", "คุยกับ Strahad Farsan ใน Ratchet" },
        description = { "385:803408994:1667015402", "ข้าเคยสอนทักษะ แต่ถึงเวลาคนอื่นสอน เขาอยู่ Ratchet ชื่อ Strahad เป็นมนุษย์ แต่อย่าให้คิดว่าอ่อนแอ แม้ตัวเล็กก็ทรงพลัง สอนการอัญเชิญแกร่งกว่าได้ ข้าว่าพร้อม ไปหาเดี๋ยวนี้ อยู่เหนือเมืองท่า Ratchet ข้างหอคอยเขา" },
        completion = { "171:2092124504:1412232824 N 37:1998851435:1792810756", "Ratchet ยุ่งใช่ไหม? ข้าชอบดูงานหนักเมืองท่า ลึกลับ ผจญภัย... และความเขลามากมาย\n\nนั่นความเกลียดในตาหรือ {name}? ดี เราจะใช้ให้เป็นประโยชน์" },
    },
    [3001] = { -- Seeking Strahad
        title = { "15:104362230:1666271580", "ตามหา Strahad" },
        objective = { "31:1232436253:243635334", "หา Strahad Farsan ใน Ratchet" },
        description = { "452:2118980668:2055473318", "ข้าเคยสอนทักษะ แต่ถึงเวลาคนอื่นสอน เขาอยู่ Ratchet ชื่อ Strahad เป็นมนุษย์ แต่อย่าคิดว่าอ่อนแอหรือเป็นศัตรู อย่างน้อยตอนนี้ เขาทรงพลังควรเคารพ สอนอัญเชิญที่ยิ่งใหญ่กว่าซึ่งข้าว่าพร้อม ไปหา\n\nอยู่เหนือเมืองท่า Ratchet ข้างหอคอยที่นั่น" },
        completion = { "171:2092124504:1412232824 N 37:1998851435:1792810756", "Ratchet ยุ่งใช่ไหม? ข้าชอบดูงานหนักเมืองท่า ลึกลับ ผจญภัย... และความเขลามากมาย\n\nนั่นความเกลียดในตาหรือ {name}? ดี เราจะใช้ให้เป็นประโยชน์" },
    },
    [3090] = { -- Tainted Parchment
        title = { "17:672522493:324784499", "แผ่นหนังแปดเปื้อน" },
        objective = { "86:86194712:1548177698", "อ่าน Tainted Parchment แล้วคุยกับ Nartok ใน Den ที่ Valley of Trials" },
        description = { "50:504738005:547472890 N 227:2013815388:879602314", "อา มีแผ่นหนังมาถึงตอนไม่อยู่ {name}\n\nปกติข้าเลี่ยงวอร์ล็อกหากทำได้ แต่ควรอ่านเมื่อมีเวลา หากจำไม่ผิด มาจาก Nartok ครูใหม่ เขาอยากคุยเมื่อพร้อม" },
        progress = { "82:1758284121:126766928 N 278:971813633:2090461696", "ในที่สุดก็มาถึง... อย่างเงียบด้วย ดี\n\nโลกเต็มคนโง่ {name} แม้ Thrall ผู้ยิ่งใหญ่มีข้อบกพร่องมากกว่าคนเห็น หันหลังพลังจำเป็นยึดดินแดนให้เป็นของเรา! เราไม่เหมือนผู้เคยถูกสิ่งจาก Nether ชักใยใช้งาน เราเป็นตัวเอง ภูมิใจ... และแข็งแกร่ง", variants = { { "82:250333771:1148967543 N 278:971813633:2090461696", "ในที่สุดเจ้าก็มาถึง... แถมยังไม่ให้ใครสังเกตเห็นด้วย ดีมาก\n\nโลกเราเต็มไปด้วยคนโง่ {name} แม้แต่ Thrall ผู้ยิ่งใหญ่ก็มีข้อบกพร่องมากกว่าที่คนส่วนใหญ่เห็น เขาหันหลังให้พลังที่เราต้องใช้เพื่อให้ดินแดนนี้เป็นของเราโดยสมบูรณ์! เราเปลี่ยนไปแล้วจากสมัยที่ถูกพวกสิ่งมีชีวิตจาก Nether ชักใยและหลอกใช้ เราเป็นนายของตัวเอง เราภาคภูมิ... และเราแข็งแกร่ง" } } },
        completion = { "59:928369879:1698633327 N 431:1393591050:448847032", "ตอนนี้เข้าร่วมแล้ว {name} อย่าเข้าใจผิด แม้เข้าถึงพลังที่หลายคนอิจฉา ไม่ได้แปลว่ายอมรับง่าย Thrall ให้เข้า Orgrimmar เพราะยังเป็นญาติร่วมเผ่า เขาหันหลังไม่ได้ ไม่เช่นนั้นเราจะน่าสมเพชเหมือนมนุษย์ที่เคยกดเขาเป็นทาส ข้าหมายถึงระวัง มีพลังได้ แต่ถ้าโง่ก็เหมือนตายแล้ว\n\nต้องฝึกคาถากลับมาหาข้า" },
        required = { [9579] = { "17:672522493:324784499", "แผ่นหนังแปดเปื้อน" } },
        steps = { { "17:672522493:324784499", "แผ่นหนังแปดเปื้อน" } },
    },
    [3099] = { -- Tainted Scroll
        title = { "14:1366306974:18743686", "ม้วนคัมภีร์แปดเปื้อน" },
        objective = { "63:705678378:499773229", "อ่าน Tainted Scroll แล้วคุยกับ Maximillion ใน Deathknell" },
        description = { "257:44355495:287037525", "อา ระหว่างจัดการ Scourge ไร้สติ ม้วนคัมภีร์มาถึงเจ้า น่าจะสำคัญ เพราะดูมีตรา Maximillion ครูฝึกวอร์ล็อก ข้าคงอ่านก่อนออกอีกครั้ง", variants = { { "169:2120213508:109034817 C 81:858764319:467660325", "อา ระหว่างจัดการ Scourge ไร้สติ ม้วนคัมภีร์มาถึงเจ้า น่าจะสำคัญ เพราะดูมีตรา Maximillion ครูฝึก{class} ข้าคงอ่านก่อนออกอีกครั้ง" } } },
        progress = { { "373:1538026310:1656381419", "372:835678675:132342815" }, "ยินดีต้อนรับ พี่น้อง รู้ว่าจะมา แค่เรื่องเวลา\n\nคำข้าทำให้สนใจใช่ไหม? แตะบางอย่างในใจ รู้ว่าสิ่งที่อ้างจริง ดี\n\nแต่รู้ไว้ ข้าไม่ทรยศ Sylvanas นางคงเห็นด้วยด้วยซ้ำ เพราะความเชื่อนางเองทำ Forsaken อยู่จุดนี้" },
        completion = { "486:750186787:776736040", "ข้าเคยว่า ทาสก็ยังเป็นทาสไม่ว่านายใด จำได้ไหม? เรารู้ว่าการควบคุมและพลังแบบนั้นขับเรา บังคับสิ่งมีชีวิตให้รับใช้ รู้ว่าทรงพลังและควรได้ความเคารพกว่าที่คนให้... จึงมุ่งชิงมา\n\nข้าจะเป็นพันธมิตรในการต่อสู้เพื่อเสรีภาพ เสรีภาพเลือกความภักดีเอง พร้อมเมื่อใดกลับมา จะสอนทุกอย่างที่รู้" },
        required = { [9578] = { "14:1366306974:18743686", "ม้วนจารึกแปดเปื้อน" } },
        objectiveLabels = {
            item = { ["Tainted Scroll"] = "ม้วนจารึกแปดเปื้อน" },
        },
    },
    [3105] = { -- Tainted Letter
        title = { "14:356585565:1138834301", "จดหมายแปดเปื้อน" },
        objective = { "80:1865207231:817942448", "อ่าน Tainted Letter แล้วคุยกับ Drusilla La Salle ข้าง Northshire Abbey" },
        description = { "91:566813027:607752075 N 181:1752892494:83106746", "มีคนขอให้ข้านำเรื่องนี้มาบอกทันทีที่กลับจากค่ายโคบอลด์ {name} ดูเหมือนจดหมายผนึกตรา Drusilla ครูคนหนึ่งประจำถิ่น ข้าคงไม่รออ่านก่อนทำธุระอื่นใน Abbey" },
        progress = { "50:1433366108:2035128874 N 103:1878918791:1254935478", "อา มาถึงทันเวลาพอดี {name} ยามบางคนเพิ่งมามองสงสัย... คนไร้เวทน่าสมเพช" },
        completion = { "380:415066542:1232770887", "ยิ่งมีพลังยิ่งถูกล่อ ต้องจำควบคุมตน ข้าไม่โกหก ความแปดเปื้อนเกิดกับผู้ใช้อาร์เคนทุกคน โดยเฉพาะผู้ติดต่อสิ่งจาก Twisting Nether อดทนและรอบคอบ... แต่อย่าให้กดความทะเยอทะยาน\n\nมีพลังเพิ่มแล้วกลับมา ข้าจะสอนวิถีเพิ่ม" },
        required = { [9576] = { "14:356585565:1138834301", "จดหมายแปดเปื้อน" } },
        steps = { { "14:356585565:1138834301", "จดหมายแปดเปื้อน" } },
    },
    [3631] = { -- Summon Felsteed
        title = { "15:1338639831:607136667", "อัญเชิญ Felsteed" },
        objective = { "39:1454961443:1658068195", "คุยกับ Strahad Farsan ใน Barrens" },
        description = { "288:859261228:2074014337", "ฮึ ข้าว่ายังไม่พร้อม แต่ไม่ใช่ข้าตัดสิน Strahad เห็นต่าง และเป็นสิทธิ์เขา... ครั้งนี้\n\nเขาอยากคุยโดยเร็ว ยังอยู่เหนือ Ratchet ใน Barrens ที่หอคอยเล็กกับศิษย์\n\nอย่าช้า" },
        completion = { "207:1137631751:822840880", "กลับมาให้เกียรติข้าอีกแล้ว ใจดีจริง\n\nศิษย์สงสัยว่าจะโผล่ไหม ข้าบอกไม่ต้องสงสัย เมื่อเกี่ยวพลัง เจ้าก็ถูกดึงเหมือนผีเสื้อเข้ากองไฟ" },
    },
    [4487] = { -- Summon Felsteed
        title = { "15:1338639831:607136667", "อัญเชิญ Felsteed" },
        objective = { "35:57723190:1069512475", "คุยกับ Strahad Farsan ใน Ratchet" },
        description = { { "487:41648539:688915502", "487:2002476833:711398713" }, "อา ดี มาแล้ว ข้าส่งอสูรไปตามเพื่อเรียกความสนใจ แต่ดูเหมือนมาถึงก่อนมันพบ ช่างเถอะ\n\nช่วงนี้มีคนพูดเรื่องพลังที่เพิ่ม ดีต่อเจ้า อาจร้ายต่อผู้อื่น แต่นั่นไม่สำคัญ ประเด็นคือพิสูจน์ตัวแล้ว จึงสมควร... ฮิ ๆ... รับพรบางอย่าง\n\nเหนือ Ratchet ใน Barrens มี Strahad เชื่อว่าเคยพบกันแล้ว" },
        completion = { "207:1137631751:822840880", "กลับมาให้เกียรติข้าอีกแล้ว ใจดีจริง\n\nศิษย์สงสัยว่าจะโผล่ไหม ข้าบอกไม่ต้องสงสัย เมื่อเกี่ยวพลัง เจ้าก็ถูกดึงเหมือนผีเสื้อเข้ากองไฟ" },
    },
    [4488] = { -- Summon Felsteed
        title = { "15:1338639831:607136667", "อัญเชิญ Felsteed" },
        objective = { "35:57723190:1069512475", "คุยกับ Strahad Farsan ใน Ratchet" },
        description = { "4:1110228981:147916455 N 476:1926154370:565148161", "อา {name} เห็นควรมาให้เกียรติ วิเศษ!\n\nหวังว่าไม่คาดให้รับใช้ทุกอย่าง แม้พลังเพิ่มเร็ว ยังเป็นลูกหมาเรื่องความรู้แท้ หากไม่ระวัง ความแปดเปื้อนจะครอบงำเจตนาอ่อนแอ\n\nเข้าเรื่อง Strahad อยากคุย ยังอยู่หอคอยมองลง Ratchet ใน Barrens แนะนำอย่านาน" },
        completion = { "207:1137631751:822840880", "กลับมาให้เกียรติข้าอีกแล้ว ใจดีจริง\n\nศิษย์สงสัยว่าจะโผล่ไหม ข้าบอกไม่ต้องสงสัย เมื่อเกี่ยวพลัง เจ้าก็ถูกดึงเหมือนผีเสื้อเข้ากองไฟ" },
    },
    [4489] = { -- Summon Felsteed
        title = { "15:1338639831:607136667", "อัญเชิญ Felsteed" },
        objective = { "35:57723190:1069512475", "คุยกับ Strahad Farsan ใน Ratchet" },
        description = { "5:1457244478:692241155 R 38:979098687:141784432 N 318:1167788469:770518156", "เจ้าชาว{race}! มานี่!\n\nคนที่เรียกว่า {name} ใช่ไหม?\n\nข้าคิดแล้ว จะพูดสั้น พลังเพิ่มและได้รับยอมรับ ถึงเวลารับรางวัลความพยายาม\n\nไป Barrens เหนือ Ratchet จะพบ Strahad Farsan จำได้ไหม? เขาอยากคุย อย่าช้า" },
        completion = { "207:1137631751:822840880", "กลับมาให้เกียรติข้าอีกแล้ว ใจดีจริง\n\nศิษย์สงสัยว่าจะโผล่ไหม ข้าบอกไม่ต้องสงสัย เมื่อเกี่ยวพลัง เจ้าก็ถูกดึงเหมือนผีเสื้อเข้ากองไฟ" },
    },
    [4490] = { -- Summon Felsteed
        title = { "15:1338639831:607136667", "อัญเชิญ Felsteed" },
        objective = { "77:263773517:831446081", "คุยกับ Strahad Farsan ใน Ratchet เพื่อเรียนอัญเชิญ Felsteed" },
        description = { "282:1730919494:28704166", "ข้าจะตอบแทนความอดทนและขยัน แต่รู้ไว้ ภายหน้าการได้อัญเชิญ Felsteed จะยากกว่านี้ ต้องทำเพื่อให้ได้มา... ไม่ง่าย\n\nตอนนี้ไปพร้อมพลังเรียกมัน ใช้ตามเห็นควร" },
        completion = { "11:799504212:1731205453 N 45:1092377462:1230054678", "โชคดี {name} รอพบภายหน้า" },
    },
    [4736] = { -- In Search of Menara Voidrender
        title = { "30:1294459789:1077948329", "ตามหา Menara Voidrender" },
        objective = { "42:1932133567:1315841043", "คุยกับ Menara Voidrender ใน Barrens" },
        description = { "11:1660708764:694672350 N 325:1412178594:525499953 N 90:1925087377:1717981411", "อา สวัสดี {name} ฝึกก้าวหน้าดีจนข้าว่าควรตอบแทนงานหนัก และที่ยังไม่แปดเปื้อนอาร์เคน\n\nหากสนใจ หา Menara Voidrender ใน Ratchet ตอนนี้พักหอคอย Strahad Farsan เหนือเมือง\n\nนางไม่เป็นมิตรนัก {name} อย่าหวังคำชม แต่หากขยันจะดูแลให้แน่" },
        completion = { "132:1505215536:1737428463 N 309:870762796:1464311478", "อา Briarthorn ส่งมา ดี ข่าวไปไกลพอพบศิษย์อนาคต ข้าพอใจ\n\nพวกเรามักรวมตัวไม่ว่าเผ่าใด {name} ยิ่งสำคัญเพราะสิ่งที่เราติดต่อส่วนใหญ่ไม่ละเว้นเผ่าใดจากความร้าย หากเราเอาใจหรือควบคุมไม่ถูก\n\nเจ้าคงเรียนมามาก หากยอม ข้าจะช่วยสร้างเครื่องมือเสริมฝีมือ" },
    },
    [4737] = { -- In Search of Menara Voidrender
        title = { "30:1294459789:1077948329", "ตามหา Menara Voidrender" },
        objective = { "42:1932133567:1315841043", "คุยกับ Menara Voidrender ใน Barrens" },
        description = { "498:1635057851:213995300", "ฮึ ยังมุ่งพลังเพิ่ม ข้าว่าแค่รอความแปดเปื้อนกับเสพติดยึดเจ้า ให้เป็นทาสสิ่งที่อยากควบคุม\n\nถุย! คนโง่! เวลาจะพิสูจน์ Zevrost ถูก ไม่มีอย่างอื่น แค่เวลา\n\nแต่ดูไม่ใช่ทุกคนเห็นด้วย Menara อยากสร้างเครื่องมือให้มีพลังและใช้กำลังได้ยิ่งขึ้น สนใจก็ไป Ratchet ใน Barrens นางอยู่เหนือเมือง" },
        completion = { "129:341622731:1705891265 N 309:870762796:1464311478", "อา Zevrost ส่งมา ดี ข่าวไปไกลพอพบศิษย์อนาคต ข้าพอใจ\n\nพวกเรามักรวมตัวไม่ว่าเผ่าใด {name} ยิ่งสำคัญเพราะสิ่งที่เราติดต่อส่วนใหญ่ไม่ละเว้นเผ่าใดจากความร้าย หากเราเอาใจหรือควบคุมไม่ถูก\n\nเจ้าคงเรียนมามาก หากยอม ข้าจะช่วยสร้างเครื่องมือเสริมฝีมือ" },
    },
    [4738] = { -- In Search of Menara Voidrender
        title = { "30:1294459789:1077948329", "ตามหา Menara Voidrender" },
        objective = { "44:1794668594:104544427", "คุยกับ Menara Voidrender ใน Barrens" },
        description = { "33:1258912501:1358271979 N 469:1377791837:74218828", "ขอชัดเรื่องหนึ่ง {name} ข้าไม่เห็นว่าพร้อมรับผิดชอบ ไม่คิดว่ามือใหม่ควรเกี่ยวสร้างของพลัง โดยเฉพาะผู้ยังไม่ผ่านการทดสอบ\n\nแต่ไม่ใช่ข้าตัดสิน ผู้มีอำนาจ หรืออย่างน้อยผู้ต้องการมอบของ เป็นคนตัดสิน\n\nสนใจเรียนเพิ่มก็หา Menara Voidrender ใน Ratchet ปกติอยู่หอคอยเหนือเมืองท่า" },
        completion = { "131:1768788137:878432678 N 309:870762796:1464311478", "อา Demisette ส่งมา ดี ข่าวไปไกลพอพบศิษย์อนาคต ข้าพอใจ\n\nพวกเรามักรวมตัวไม่ว่าเผ่าใด {name} ยิ่งสำคัญเพราะสิ่งที่เราติดต่อส่วนใหญ่ไม่ละเว้นเผ่าใดจากความร้าย หากเราเอาใจหรือควบคุมไม่ถูก\n\nเจ้าคงเรียนมามาก หากยอม ข้าจะช่วยสร้างเครื่องมือเสริมฝีมือ" },
    },
    [4739] = { -- In Search of Menara Voidrender
        title = { "30:1294459789:1077948329", "ตามหา Menara Voidrender" },
        objective = { "42:1932133567:1315841043", "คุยกับ Menara Voidrender ใน Barrens" },
        description = { "C 426:485120544:1521797523", "{class}! ใช่ เจ้า!\n\nแม้อุปกรณ์ไม่ครบ แต่เห็นชัดว่าพร้อม อากาศรอบตัวแผ่ความมั่นใจเพิ่ม ใช่ เห็นแล้ว\n\nMenara Voidrender จะสอนหากรู้สึกพร้อม นางสอนอาร์เคนแก่ศิษย์รุ่นเยาว์ ถึงให้ของขวัญผู้ผ่านบททดสอบ\n\nสนใจก็ไป Ratchet ใน Barrens นางอยู่หอคอย Strahad เหนือเมือง" },
        completion = { "126:668744197:1830858912 N 309:870762796:1464311478", "อา Kaal ส่งมา ดี ข่าวไปไกลพอพบศิษย์อนาคต ข้าพอใจ\n\nพวกเรามักรวมตัวไม่ว่าเผ่าใด {name} ยิ่งสำคัญเพราะสิ่งที่เราติดต่อส่วนใหญ่ไม่ละเว้นเผ่าใดจากความร้าย หากเราเอาใจหรือควบคุมไม่ถูก\n\nเจ้าคงเรียนมามาก หากยอม ข้าจะช่วยสร้างเครื่องมือเสริมฝีมือ" },
    },
    [4781] = { -- Components for the Enchanted Gold Bloodrobe
        title = { "43:2051054028:722437535", "ส่วนประกอบ Enchanted Gold Bloodrobe" },
        objective = { "58:1138319659:1637296723", "นำ Gold Bar ไปให้ Xizk Goodstitch ใน Stranglethorn Vale" },
        description = { "501:553708441:1361525516", "งานต่อไปง่ายเหมือนแรก แต่ต้องหาคนช่วย\n\nต้องใช้ด้ายทองปักเสื้อคลุม แต่หายากและน้อยคนทำเป็น โชคดีผู้ภักดีต่อเราอยู่คนหนึ่งรู้เคล็ดและยอมช่วยผู้ก้าวหน้า\n\nนำทองแท่งให้ Xizk Goodstitch ใน Booty Bay เขาเป็นช่างตัดเย็บชั้นครู ยินดีปั่นด้ายให้ นักขุดแร่ฝีมือดีหลอมทองแท่งได้ ขอเขาช่วย" },
        progress = { "319:1786464036:1759133526", "ทองแท่ง ใช่... ใช่ นำมาหนึ่งแท่งแล้วดูว่าจะปั่นด้ายอย่างไร ระหว่างนี้แนะนำสนใจเพิ่มพลัง บททดสอบหนักสุดยังรอ เชื่อเถอะ... ไม่ว่าคิดว่าเก่งแค่ไหนก็จะหวังว่าเตรียมพร้อมกว่านี้" },
        completion = { "9:736088637:128646839 N 392:466325872:636281699", "เยี่ยม {name} ยินดีที่พบนักขุดช่วยเร็ว หรือทำเอง? อย่างไรก็ดีมาก เหมาะทำด้าย\n\nต้องใช้เวลา คงกลับมาอีก ที่จริงข้าส่งให้เจ้าหญิงขังในหอคอยที่มีงานเดียวคือปั่นด้ายทอง... ไม่ ข้าพูดจริงนะ... หมายความอย่างนั้น... ก็ได้ ไม่จริงหรอก" },
        required = { [3577] = { "8:1868650072:189161854", "แท่งทองคำ" } },
        steps = { { "8:1868650072:189161854", "แท่งทองคำ" } },
    },
    [4782] = { -- Components for the Enchanted Gold Bloodrobe
        title = { "43:2051054028:722437535", "ส่วนประกอบ Enchanted Gold Bloodrobe" },
        objective = { "43:1245240059:585707978", "กลับไปหา Menara Voidrender ใน Barrens" },
        description = { "257:374378569:404366685 N 128:1643780544:1016048133", "กลับ Menara บอกต้องใช้เวลา แต่จะทำให้ทั้งนางและเจ้า บอกให้นางส่งเจ้าเก็บส่วนประกอบที่เหลือ ถึงตอนนั้นด้ายคงเสร็จ กลับมารับได้\n\nโชคดี {name} อ้อ ฝากสวัสดี Strahad เฒ่านั่น... ตั้งหอคอยข้าง Ratchet... บ้าจริง" },
        completion = { "23:1843206281:921435140 N 294:1417299880:1203244119", "ดี กลับแล้ว {name} ด้ายอยู่ไหน?\n\nอา เข้าใจ รับได้ ก็อบลินกับพี่น้องเขายังไม่เคยทำผิดหวัง ก็คงเข้าใจที่ไม่ได้เตรียมทันที ช่างเถอะ... มีอย่างอื่นทำระหว่างนี้\n\nพร้อมขั้นต่อไปไหม?" },
    },
    [4783] = { -- Components for the Enchanted Gold Bloodrobe
        title = { "43:2051054028:722437535", "ส่วนประกอบ Enchanted Gold Bloodrobe" },
        objective = { "97:1415517354:1179932280", "นำ Vials of Hatefury Blood 10 ขวด และ Lesser Infernal Stone 1 ชิ้นไปให้ Menara Voidrender ใน Barrens" },
        description = { "468:707711175:391293810", "ส่วนประกอบถัดไปอยู่ Desolace ไกลตะวันตกกว่า Barrens และแม้แต่ Stonetalon Mountains\n\nที่นั่นโกลาหลนับแต่ Sundering กำลังกับไหวพริบจะถูกทดสอบ เผชิญสิ่งแห่งความเกลียดและ Burning Legion\n\nนำเลือดเซเทอร์ Hatefury ทางตะวันออกเฉียงเหนือ และหินจาก Lesser Infernal ใน Mannoroc Coven\n\nจะใช้ทั้งสองสร้างเสื้อคลุม" },
        progress = { "279:1432149078:86838245 N 1:46:46", "Desolace ไม่อ่อนโยน นากา ยักษ์ เซเทอร์ Burning Legion... รวมเผ่าเซนทอร์ทำศึก ล้วนทำแดนอันตรายหากไม่ระวัง\n\nอย่างที่บอก ไม่เพียงกำลังไหวพริบ แต่ทดสอบอดทนด้วย ระวัง {name}" },
        completion = { "11:1614239848:1406166483 N 109:1610745895:1823810139", "ยอดเยี่ยม {name} ใช้ได้ดี ข้าจะเตรียม ขณะเจ้าไปเก็บส่วนประกอบสองอย่างสุดท้าย พร้อมไหม?" },
        required = { [6989] = { "22:351969583:1246852625", "ขวดบรรจุเลือด Hatefury" }, [6990] = { "21:781982837:1721241645", "ศิลาอินเฟอร์นัลระดับต้น" } },
        steps = { { "22:351969583:1246852625", "ขวดบรรจุเลือด Hatefury" }, { "21:781982837:1721241645", "ศิลาอินเฟอร์นัลระดับต้น" } },
    },
    [4784] = { -- Components for the Enchanted Gold Bloodrobe
        title = { "43:2051054028:722437535", "ส่วนประกอบ Enchanted Gold Bloodrobe" },
        objective = { "102:1283758612:135827616", "นำ Fine Gold Thread, Smoldering Coals 2 ชิ้น และ Soul Shard ไปให้ Menara Voidrender ใน Barrens" },
        description = { "30:1503446179:1952113556 N 413:98664702:1105712654", "ต้องการเพียงสามอย่าง {name} แล้วเสื้อจะเสร็จ\n\nแรก ด้ายทองอย่างดีที่ Xizk ทำ ไป Booty Bay รับมา\n\nสอง ถ่านคุสองชิ้นจากธาตุไฟใน Arathi Highlands หากจำถูก อยู่ตะวันตกใกล้ Thoradin's Wall\n\nสุดท้าย Soul Shard ที่เจ้าสร้างเอง\n\nได้ครบแล้วกลับหอคอย จะทำเสื้อให้เสร็จ" },
        progress = { "6:1889098769:928218597 N 119:1757912972:1989906119", "ใกล้แล้ว {name} ข้าสัญญา เสื้อจะพอความต้องการยิ่งกว่า และให้ได้เปรียบคู่ต่อสู้แน่" },
        completion = { "11:1614239848:1406166483 N 76:567276066:1565307488", "ยอดเยี่ยม {name}! วัสดุครบ เราพร้อม\n\nเชื่อว่าเจ้าจะพอใจ" },
        required = { [12293] = { "16:283913391:2129990244", "ด้ายทองเนื้อละเอียด" }, [6991] = { "15:1209494321:610509868", "ถ่านคุกรุ่น" }, [6265] = { "10:473126638:559560453", "เศษวิญญาณ" } },
        steps = { { "16:283913391:2129990244", "ด้ายทองเนื้อละเอียด" }, { "15:1209494321:610509868", "ถ่านคุกรุ่น" }, { "10:473126638:559560453", "เศษวิญญาณ" } },
    },
    [4785] = { -- Fine Gold Thread
        title = { "16:283913391:2129990244", "ด้ายทองอย่างดี" },
        completion = { "13:939218444:1640774044 N 187:381364818:759378194", "นี่ {name} ฝากสวัสดี Menara ด้วย\n\nเราหวังยิ่งใหญ่จากเจ้า บางทีเมื่อ Legion คุกเข่า ชื่อเจ้าจะถูกกล่าวชมพลัง ข้าแทบรอไม่ไหว!" },
        description = { "23:1454898822:227342474 N 157:1409650887:149393062", "เจ้ากลับมาแล้วสินะ {name} เราสองพี่น้องดีใจที่ได้เห็นเจ้ากลับมา\n\nคงมารับด้ายสินะ แน่นอน เราเตรียมไว้รอเจ้าแล้ว ได้มาเร็วกว่าที่เราคาดไว้มากทีเดียว" },
    },
    [4786] = { -- The Completed Robe
        title = { "18:699079204:1259457041", "เสื้อคลุมที่เสร็จแล้ว" },
        objective = { "77:2035239933:1479282728", "รอ Menara Voidrender ทำเสื้อคลุมเสร็จ แล้วคุยกับนางอีกครั้ง" },
        description = { "88:981914428:396515574", "ข้าจะประกอบให้ ใช้เพียงครู่ อย่าไปไกล" },
        progress = { "10:711356376:1558500379 N 3:3050122:795478", "สักครู่ {name}..." },
        completion = { "12:250727635:907821298 N 252:2093156271:347783816", "เสร็จแล้ว {name} นี่ สวมอย่างภูมิใจ\n\nขยันมาก ข้าเห็นอนาคตยิ่งใหญ่ จำไว้ว่าต้านความแปดเปื้อนบนวิถีต้องใจและความทรหดมาก ตราบเจตนายังเป็นของตน จะสำเร็จยิ่งใหญ่" },
        objectiveLabels = {
            event = { ["Wait for Menara Voidrender to complete your item"] = "รอให้ Menara Voidrender ทำไอเท็มของเจ้าให้เสร็จ" },
        },
    },
    [4962] = { -- Shard of a Felhound
        title = { "19:183818110:845649457", "เศษวิญญาณ Felhound" },
        objective = { "191:772997007:1113599916", "นำ Felhas Ruby ไปใช้กับ Felhound ใน Desolace เมื่อสำเร็จ นำ Felhas Ruby และ Imprisoned Felhound Spirit กลับไปให้ Menara Voidrender ใน Barrens" },
        description = { "470:1539015522:1768934294", "เลือกจับวิญญาณ Felhound ดี\n\nรับทับทิม ใช้จับวิญญาณ คล้ายเวทที่รู้ เมื่อสัตว์ใกล้ตาย ใช้อัญมณีแล้วมันจะทำที่เหลือ\n\nแนะนำไป Desolace ลอง Felhound ที่นั่น น่าจะดี\n\nสำเร็จแล้วนำทั้งวิญญาณที่จับและทับทิมให้ Menara" },
        progress = { "5:1287366450:669725923 N 323:1552983870:1008729356", "ว่าอย่างไร {name}? เลือกแล้วหรือ? Infernal หรือ Felhound?\n\nแต่ละทางเป็นส่วนตัว ควรสะท้อนจุดแข็งและอ่อน บางคนเสริมจุดแข็งแทนอุดสิ่งที่ขาด บางครั้งกำลังเหนือศัตรูก็เป็นกลยุทธ์ดีเท่าการร่ายเวทสมดุล" },
        completion = { "41:2049597704:1479991569 N 101:852494035:1687808488", "อา วิญญาณ Felhound ทำดี {name}\n\nเมื่อมีทั้งวิญญาณและลูกแก้วชำระแล้ว ข้าจะรวมให้ แต่ไม่ก่อนนั้น" },
        required = { [12647] = { "11:1490079431:461845739", "ทับทิม Felhas" }, [12648] = { "26:380179440:1034953412", "วิญญาณเฟลฮาวนด์ที่ถูกกักขัง" } },
        steps = { { "11:1490079431:461845739", "ทับทิม Felhas" }, { "26:380179440:1034953412", "วิญญาณเฟลฮาวนด์ที่ถูกกักขัง" } },
    },
    [4963] = { -- Shard of an Infernal
        title = { "20:1655375113:285683569", "เศษวิญญาณ Infernal" },
        objective = { "195:1108720631:70206425", "นำ Infus Emerald ไปใช้กับ Infernal ใน Desolace เมื่อสำเร็จ นำ Infus Emerald และ Imprisoned Infernal Spirit กลับไปให้ Menara Voidrender ใน Barrens" },
        description = { "477:2053778056:1033329361", "เลือกจับวิญญาณ Infernal ดี\n\nรับมรกต ใช้จับวิญญาณ คล้ายเวทที่รู้ เมื่อสัตว์ใกล้ตาย ใช้อัญมณีแล้วมันจะทำที่เหลือ\n\nแนะนำไป Desolace ลอง Infernal ที่นั่น น่าจะดี\n\nสำเร็จแล้วนำทั้งวิญญาณที่จับและมรกตให้ Menara" },
        progress = { "5:1287366450:669725923 N 323:1552983870:1008729356", "ว่าอย่างไร {name}? เลือกแล้วหรือ? Infernal หรือ Felhound?\n\nแต่ละทางเป็นส่วนตัว ควรสะท้อนจุดแข็งและอ่อน บางคนเสริมจุดแข็งแทนอุดสิ่งที่ขาด บางครั้งกำลังเหนือศัตรูก็เป็นกลยุทธ์ดีเท่าการร่ายเวทสมดุล" },
        completion = { "42:2029319001:2002428369 N 101:852494035:1687808488", "อา วิญญาณ Infernal ทำดี {name}\n\nเมื่อมีทั้งวิญญาณและลูกแก้วชำระแล้ว ข้าจะรวมให้ แต่ไม่ก่อนนั้น" },
        required = { [12646] = { "13:740131717:1030742339", "มรกต Infus" }, [12649] = { "26:913732819:703328144", "วิญญาณอินเฟอร์นัลที่ถูกกักขัง" } },
        steps = { { "13:740131717:1030742339", "มรกต Infus" }, { "26:913732819:703328144", "วิญญาณอินเฟอร์นัลที่ถูกกักขัง" } },
    },
    [4964] = { -- The Completed Orb of Dar'Orahil
        title = { "31:72682116:757747034", "ลูกแก้ว Dar'Orahil ที่เสร็จแล้ว" },
        objective = { "89:738710724:17634575", "รอ Menara Voidrender ทำ Orb of Dar'Orahil เสร็จ แล้วคุยกับนางอีกครั้ง" },
        description = { "287:744990465:1153998320", "ข้าจะเริ่มสร้างลูกแก้ว ใส่ปีศาจใหม่ทันที เมื่อเสร็จ เลือกรูปไม้เท้าหรือลูกแก้วได้ ข้าคิดว่าควรตอบสนองอาวุธที่วอร์ล็อกเลือก... ไม่มีเหตุจะหยุดทำเช่นนั้น" },
        completion = { "12:250727635:907821298 N 287:374773523:1586966547 N 46:1712314784:1020283590", "เสร็จแล้ว {name} บอกว่าอยากได้ไม้เท้าต้องใช้สองมือ หรือลูกแก้วเพื่อใช้มีดหรือดาบเป็นอาวุธ\n\nรับมือ Felhound เป็นผลงานใหญ่ ของจะรับใช้ดีแน่ ขยันฝึกศาสตร์ต่อ {name} ข้าจะรอฟังวีรกรรม" },
        objectiveLabels = {
            event = { ["Wait for Menara Voidrender to complete your item"] = "รอให้ Menara Voidrender ทำไอเท็มของเจ้าให้เสร็จ" },
        },
    },
    [4965] = { -- Knowledge of the Orb of Orahil
        title = { "30:541664229:1197527239", "ความรู้เรื่องลูกแก้ว Orahil" },
        objective = { "42:1932133567:1315841043", "คุยกับ Menara Voidrender ใน Barrens" },
        description = { "63:51911056:1951348772 N 362:733789171:1837468664", "อ้าว... ยินดีที่พลังเพิ่ม {name} ข้าว่าพร้อมคุยกับ Menara Voidrender ใน Barrens หากไม่เคยพบ ต้องบอกว่าไม่เคยเห็นผู้เชี่ยวชาญสร้างของ โดยเฉพาะลูกแก้ว ที่กักแม้ปีศาจรับใช้เราได้ง่ายเช่นนาง\n\nสนใจก็ไปหอคอย Strahad เหนือ Ratchet ใน Barrens" },
        completion = { "224:1856345611:784177222 N 1:63:63", "อา แสวงหาสิ่งที่... เป็นรูปธรรมกว่า ข้าช่วยได้หากพร้อมจริง\n\nน่ายินดีเห็นพวกเราหาพลังในรูปอื่นนอกจากความรู้\n\nรู้สึกพร้อมไหม {name}?" },
    },
    [4967] = { -- Knowledge of the Orb of Orahil
        title = { "30:541664229:1197527239", "ความรู้เรื่องลูกแก้ว Orahil" },
        objective = { "42:1932133567:1315841043", "คุยกับ Menara Voidrender ใน Barrens" },
        description = { "496:282461516:1653234692", "ยังโง่และหาของประดับคนเป็น ใช่ ข้าพูดหยิ่ง มองเจ้าแล้วขำ น่าสมเพช!\n\nแต่ที่ข้าคิดไม่สำคัญ สำคัญแค่คนยอมติดต่อคิดอย่างไร! ครั้งนี้สวนความเห็นข้า ผู้มีพลังบางส่วนกลับคิดว่าเจ้าควรได้เพิ่ม\n\nหากแสวงหาก็ไป Menara Voidrender ในหอคอยเหนือ Ratchet เชื่อว่าเคยพบแล้วนานก่อน" },
        completion = { "224:1856345611:784177222 N 1:63:63", "อา แสวงหาสิ่งที่... เป็นรูปธรรมกว่า ข้าช่วยได้หากพร้อมจริง\n\nน่ายินดีเห็นพวกเราหาพลังในรูปอื่นนอกจากความรู้\n\nรู้สึกพร้อมไหม {name}?" },
    },
    [4968] = { -- Knowledge of the Orb of Orahil
        title = { "30:541664229:1197527239", "ความรู้เรื่องลูกแก้ว Orahil" },
        objective = { "42:1932133567:1315841043", "คุยกับ Menara Voidrender ใน Barrens" },
        description = { "333:1362994699:954107812", "หืม มาไกลขนาดนี้... น่าทึ่ง นึกว่าการรวมอาร์เคนจะแปดเปื้อนวิญญาณจนคลั่งแล้ว ลองผลักต่อดีไหม?\n\nอยากทดสอบฝีมือก็หา Menara Voidrender ในหอคอย Strahad เหนือ Ratchet นางจะชี้ทาง" },
        completion = { "224:1856345611:784177222 N 1:63:63", "อา แสวงหาสิ่งที่... เป็นรูปธรรมกว่า ข้าช่วยได้หากพร้อมจริง\n\nน่ายินดีเห็นพวกเราหาพลังในรูปอื่นนอกจากความรู้\n\nรู้สึกพร้อมไหม {name}?" },
    },
    [4969] = { -- Knowledge of the Orb of Orahil
        title = { "30:541664229:1197527239", "ความรู้เรื่องลูกแก้ว Orahil" },
        objective = { "42:1932133567:1315841043", "คุยกับ Menara Voidrender ใน Barrens" },
        description = { "49:1216696932:983159029 C 362:532916596:286364510", "ฮ่า ๆ! ไปได้ดี {class}รุ่นเยาว์\n\nให้เวลา อินเฟอร์นัลกับเดรดลอร์ดจะก้มต่อหน้า!\n\nแต่จนกว่านั้น ยังต้องพึ่งอาวุธตีด้วยมือเผ่ามรรตัย\n\nดูพร้อมสร้างอีกชิ้น หากยอม Menara Voidrender อยากคุย! อยู่ใกล้หอคอย Strahad เหนือเมืองท่า Ratchet ไปเมื่อพร้อม" },
        completion = { "219:360502932:2094039436 N 1:63:63", "อา แสวงหาสิ่งที่... เป็นรูปธรรมกว่า ข้าช่วยได้หากพร้อมจริง\n\nน่ายินดีเห็นพวกเราหาพลังในรูปอื่นนอกจากความรู้\n\nรู้สึกพร้อมไหม {name}?" },
    },
    [4975] = { -- The Completed Orb of Noh'Orahil
        title = { "31:630594311:834277273", "ลูกแก้ว Noh'Orahil ที่เสร็จแล้ว" },
        objective = { "89:98636695:1798108154", "รอ Menara Voidrender ทำ Orb of Noh'Orahil เสร็จ แล้วคุยกับนางอีกครั้ง" },
        description = { "287:744990465:1153998320", "ข้าจะเริ่มสร้างลูกแก้ว ใส่ปีศาจใหม่ทันที เมื่อเสร็จ เลือกรูปไม้เท้าหรือลูกแก้วได้ ข้าคิดว่าควรตอบสนองอาวุธที่วอร์ล็อกเลือก... ไม่มีเหตุจะหยุดทำเช่นนั้น" },
        completion = { "12:250727635:907821298 N 275:968939876:880272288 N 1:46:46", "เสร็จแล้ว {name} บอกว่าอยากได้ไม้เท้าต้องใช้สองมือ หรือลูกแก้วเพื่อใช้มีดหรือดาบเป็นอาวุธ\n\nรับมือ Infernal เป็นผลงานใหญ่ รางวัลจะเหมาะ ขอให้สำเร็จในศาสตร์ต่อไป {name}" },
        objectiveLabels = {
            event = { ["Wait for Menara Voidrender to complete your item"] = "รอให้ Menara Voidrender ทำไอเท็มของเจ้าให้เสร็จ" },
        },
    },
    [4976] = { -- Returning the Cleansed Orb
        title = { "26:2133615459:457448503", "คืนลูกแก้วที่ชำระแล้ว" },
        objective = { "69:106241021:414225967", "นำ Cleansed Infernal Orb กลับไปให้ Menara Voidrender ใน Barrens" },
        description = { "49:339701181:892819680 N 160:326400627:990719357", "นำลูกแก้วชำระแล้วกลับ Menara ที่ Ratchet {name} ฝากความปรารถนาดีและเดินทางปลอดภัย หวังจริงว่าจะทนสิ่งล่อและแปดเปื้อนที่ต้องมาบนวิถีได้\n\nโชคดี" },
        progress = { "46:1839917666:493944467 N 149:720707904:2018839663", "หา Tabetha กับลูกแก้วเป็นอย่างไร {name}?\n\nTabetha มีประโยชน์มากเรื่องอาร์เคน แน่ใจว่าช่วยได้ไม่มีปัญหา หากหานางพบ" },
        completion = { "11:534428891:784080240 N 193:992156407:1949522954", "ทำดี {name} ใช้ได้\n\nเหลือเพียงตัดสินใจว่าจะให้กักปีศาจใดในลูกแก้วชำระแล้ว เลือกแล้วจะมีของใหม่ยอดเยี่ยมไว้ใช้" },
        required = { [12642] = { "21:477659600:191956464", "ลูกแก้วอินเฟอร์นัลที่ผ่านพิธีชำระ" } },
        steps = { { "21:477659600:191956464", "ลูกแก้วอินเฟอร์นัลที่ผ่านพิธีชำระ" } },
    },
    [7562] = { -- Mor'zul Bloodbringer
        title = { "20:114912339:312413542", "Mor'zul Bloodbringer" },
        objective = { "55:238486838:2009146978", "คุยกับ Mor'zul Bloodbringer ใน Burning Steppes" },
        description = { "N 410:1325741261:1339071183 N 86:1605199785:151618183", "{name} เจ้าดำดิ่งศาสตร์มืดลึก ควบคุมผู้พำนักต่างโลกแข็งแกร่งมาก... บางทีพร้อมผูก Dreadsteed อันเลื่องชื่อกับตน\n\nพิธีเรียกสัตว์จากบ้านต้องใช้พลังและทรัพยากรมาก หากอยากครองพาหนะมหากาพย์ คุยกับ Mor'zul Bloodbringer ค่ายใกล้ Altar of Storms ใน Burning Steppes\n\nไป {name} ภารกิจอันตราย แต่วอร์ล็อกระดับเจ้าไม่หนีภัย!" },
        completion = { "11:927657569:725753248 N 404:1553814300:1851168397", "สวัสดี {name} ยินดีต้อนรับ มาศึกษาใกล้ Altar of Storms เช่นข้าหรือ เพื่อใช้พลังกับจุดหมายซ่อน...\n\nหรือ... มาคุยกับข้า? ใช่ คงใช่\n\nอยากครอง Dreadsteed? ไม่ง่าย ต้องจ่ายทั้งเลือด เหงื่อ... และแน่นอน โกลด์ไม่น้อย แต่ Dreadsteed แห่ง Xoroth เป็นรางวัลคุ้ม สนใจก็ฟังต่อ..." },
    },
    [7563] = { -- Rage of Blood
        title = { "13:1706127023:1723181076", "โทสะแห่งโลหิต" },
        objective = { "88:377193460:1197828268", "นำ Raging Beast's Blood 30 ขวดไปให้ Mor'zul Bloodbringer ใน Burning Steppes" },
        description = { "480:1476133626:1221490300", "Dreadsteed อยู่โลกอื่น ที่ราบเพลิง Xoroth จะผูกสัตว์โด่งดังต้องใช้จารึกทรงพลัง ข้าเขียนบนแผ่นหนังได้ แต่ต้องใช้หมึกพิเศษก่อน\n\nWinterspring ไกลออกไปมีสัตว์คล้ายนกฮูก เคยบริสุทธิ์ แต่พลังปีศาจ Darkwhisper Gorge ทำคลั่ง เดี๋ยวนี้เดินหิมะอย่างบ้าคลั่ง\n\nข้าต้องใช้เลือดทำหมึก นำมา" },
        progress = { "37:1869079329:1704272743 N 116:2121553634:2119753717", "เห็นสัตว์นกฮูกคลั่งไหม {name}? เวทมันแกร่งและรวมในเลือดที่ไหลผ่านร่างทรมาน" },
        completion = { "195:2009874383:392305827", "อา ดีมาก จะกลั่นเลือดเป็นหมึก เขียนแผ่นหนังตามสัญญา บางทีเก็บเองนิดหน่อย ได้ยินว่ารสทำเคลิบเคลิ้ม..." },
        required = { [18590] = { "20:842385278:1880065245", "เลือดสัตว์เดือดดาล" } },
        objectiveLabels = {
            item = { ["Raging Beast's Blood"] = "เลือดสัตว์เดือดดาล" },
        },
    },
    [7564] = { -- Wildeyes
        title = { "8:255147924:1414663533", "Wildeyes" },
        objective = { "68:1404231244:447748655", "นำ Case of Blood ไปให้ Gorzeeki Wildeyes ใน Burning Steppes" },
        description = { "202:1433255587:442129720", "Gorzeeki ผู้รับใช้เป็นนักเล่นแร่แปรธาตุพอมีฝีมือ เตรียมหมึกสำหรับแผ่นหนังได้ ข้ารวมเลือดที่หามาแล้ว นำไปให้เริ่มงาน" },
        progress = { "162:193220077:1426771010", "มีของให้ข้าหรือ? แมงมุมตัวใหญ่อวบน้ำไหม? หรือแมลงสาบ? หวังว่ายังเป็น... ข้าชอบเคี้ยวตอนมันยังเป็น..." },
        completion = { "450:937328016:222499002", "อ้อ เลือด ต้องจากนาย Mor'zul เขาหลงสิ่งนี้ ชอบดูมันไหล ส่วนข้าชอบอยู่ในเส้นเลือดสัตว์ฟันแทะเล็ก ๆ จะอุ่น... จนต้องการ\n\nเลือดทรงพลัง Mor'zul คงทำแผ่นหนังเรียก Dreadsteed อีก! น่าตื่นเต้น!\n\nหากจริงและเจ้าจะทำพิธี... ต้องมีมากกว่าเลือดมาก สหาย" },
    },
    [7581] = { -- The Prison's Bindings
        title = { "21:936391210:711133608", "เครื่องผูกคุมขัง" },
        objective = { "171:340084628:1219478787", "ไป Dire Maul ใน Feralas นำ Satyr Blood 15 ชิ้นจาก Wildspawn Satyr ใน Warpwood Quarter แล้วกลับไปหา Daio ที่ Tainted Scar" },
        description = { "232:1115462096:1880523810", "ต้องนำเครื่องผูกคุก Doomguard มาจากปีศาจชั้นรอง\n\nเลือดเซเทอร์ Wildspawn ใน Dire Maul น่าจะดี เลือดจับตัวจะประสานเศษ Hederine และให้พลังคุกผลึก" },
        progress = { "47:935139705:1187358265", "มีแต่เลือดเซเทอร์ Wildspawn จึงใช้ได้" },
        completion = { "88:839362708:1827913896", "อา กู้ได้ยอดเยี่ยม เลือดจะกดการป้องกันเวท Doomguard" },
        required = { [18603] = { "11:914011166:1256881250", "เลือดเซเทอร์" } },
        objectiveLabels = {
            item = { ["Satyr Blood"] = "เลือดเซเทอร์" },
        },
    },
    [7582] = { -- The Prison's Casing
        title = { "19:1219648091:2010644414", "โครงคุก" },
        objective = { "197:1305088897:1162196627", "ไป Darkwhisper Gorge ใน Winterspring นำ Tears of the Hederine 5 ชิ้นจากปีศาจ Hederine ที่อยู่ในหุบเขา แล้วกลับไปหา Daio ที่ Tainted Scar" },
        description = { "393:244436125:2002456210", "ปีศาจ Hederine เชิง Mount Hyjal หลั่งพิษเฟลทรงพลัง ทิ้งให้แก่จะเป็นผลึกต้านเวทหนาแน่น เรียกว่า Tears of the Hederine\n\nแม้พลังมหาศาล Doomguard ก็พังกำแพงคุกที่สร้างจากวัสดุนี้ไม่ได้\n\nไป Darkwhisper Gorge ใน Winterspring กู้ผลึกมา" },
        progress = { "67:982542958:605043266 N 1:46:46", "Hederine ไม่ยอมยกอัญมณีรักโดยไม่สู้ {name}" },
        completion = { "110:309079419:1575745305", "เพียงรวมเลือด Wildspawn กับผลึกเหล่านี้ คุกก็พร้อมใช้" },
        required = { [18604] = { "21:793726417:27910825", "หยาดน้ำตาแห่งเฮเดอรีน" } },
        objectiveLabels = {
            item = { ["Tears of the Hederine"] = "หยาดน้ำตาแห่งเฮเดอรีน" },
        },
    },
    [7583] = { -- Suppression
        title = { "11:131765407:1194573255", "การกดปราบ" },
        objective = { "300:499273500:1751011313", "เข้า Tainted Scar หา Doomguard Commander\n\nใช้ Glowing Crystal Prison กับ Doomguard Commander เตรียมรับการโจมตีรุนแรง ขณะปีศาจพยายามหนีการจับ\n\nหากสำเร็จ นำ Imprisoned Doomguard กลับไปให้ Daio ที่ Tainted Scar" },
        description = { "391:2000929336:729705662 N 90:450649361:2005232324", "คุกพร้อม ทีนี้ส่วนยากที่สุด\n\nหาและจับ Doomguard Commander ใน Tainted Scar ด้วยคุกผลึก\n\nระวัง! Doomguard เจ้าเล่ห์และถึงตาย จะพยายามทำลายเจ้าขณะเริ่มพิธี ดิ้นโจมตีเพื่อหนีอย่างรุนแรง\n\nมันจะสนใจแต่เจ้า {name} ด้วยเหตุนี้ข้าแนะนำพาสหายที่ช่วยให้รอดชีวิตได้!" },
        progress = { "10:358723167:736042463", "หืม? ว่าอย่างไร?" },
        completion = { "104:1126115635:1748572630", "ทำตามที่ขอแล้ว พร้อมรับความรู้เรียกและควบคุมสัตว์ร้าย" },
        required = { [18605] = { "20:277025397:75239542", "ดูมการ์ดที่ถูกกักขัง" } },
        objectiveLabels = {
            item = { ["Imprisoned Doomguard"] = "ดูมการ์ดที่ถูกกักขัง" },
        },
    },
    [7601] = { -- What Niby Commands
        title = { "18:1692286405:790438525", "สิ่งที่ Niby สั่ง" },
        objective = { "28:205938040:487663760", "คุยกับ Impsy ใน Felwood" },
        description = { "421:481470527:308841480", "หากจะสอนความลับเรียก Infernal ผู้รับใช้ เจ้าต้องทำลาย Kroshius นำแก่นจากซากไหม้มา แต่ไม่ง่าย Kroshius แทบมอดหมด ต้องจุดศพให้ลุกแล้วปลุกจากซาก จึงต้องเก็บวัสดุจากปีศาจอื่น\n\nImpsy อิมป์ข้าจะนำทาง" },
        completion = { "25:1006095076:988844633", "โอ้ เอาอีกแล้ว" },
    },
    [7602] = { -- Flawless Fel Essence
        title = { "20:2110452397:657506164", "แก่นพลังเฟลไร้ตำหนิ" },
        objective = { "434:987725997:2044070154", "Impsy ใน Felwood ขอ Flawless Fel Essences สามชนิดจากสามพื้นที่ต่างกัน\n\nLegashi Satyrs ใน Azshara ถือแก่นพลังของพื้นที่นั้น Jaedenar Legionnaires ใน Jaedenar ถือของพื้นที่ตน และ Felguard Sentries ใน Blasted Lands ถือของพื้นที่ตน\n\nรวบรวม Flawless Fel Essences แล้วกลับไปหา Impsy ใน Felwood" },
        description = { "500:1062564667:314616361", "จะปลุก Kroshius ต้องมีไฟเฟล ข้าสร้างได้แต่ต้องใช้ส่วนประกอบ\n\nนำแก่นพลังเฟลไร้ตำหนิจากสามภูมิภาคต่างกัน\n\nLegashi Satyr ใน Azshara มีชนิดแรก Jaedenar Legionnaire ใน Jaedenar มีชนิดสอง Felguard Sentry ใน Blasted Lands มีชนิดสาม\n\nนำอย่างละหนึ่งมา ข้าจะสร้างไฟเฟลให้ปลุก Kroshius" },
        progress = { "40:1950828816:645483563", "อย่าบอกใครนะ แต่ Niby งี่เง่า" },
        completion = { "61:1196845958:14017578", "ขอสักครู่ จะรวมแก่นพลังเป็นไฟเฟล" },
        required = { [18624] = { "30:832136856:1309393021", "แก่นพลังเฟลไร้ตำหนิ (Azshara)" }, [18622] = { "31:8232893:828823635", "แก่นพลังเฟลไร้ตำหนิ (Jaedenar)" }, [18623] = { "34:2089582218:713274621", "แก่นพลังเฟลไร้ตำหนิ (Dark Portal)" } },
        objectiveLabels = {
            item = { ["Flawless Fel Essence (Azshara)"] = "แก่นพลังเฟลไร้ตำหนิ (Azshara)", ["Flawless Fel Essence (Jaedenar)"] = "แก่นพลังเฟลไร้ตำหนิ (Jaedenar)", ["Flawless Fel Essence (Dark Portal)"] = "แก่นพลังเฟลไร้ตำหนิ (Dark Portal)" },
        },
    },
    [7603] = { -- Kroshius' Infernal Core
        title = { "23:1681237455:233318600", "แก่น Infernal ของ Kroshius" },
        objective = { "301:260684867:1886957661", "หา Kroshius ที่เหลืออยู่ใน Shatter Scar Vale แห่ง Felwood เมื่อพบ ใช้ Fel Fire ใกล้ซาก รอ Kroshius กลับ เมื่อ Infernal ตื่น ฆ่าแล้วนำ Kroshius' Infernal Core จากศพ\n\nนำ Kroshius' Infernal Core กลับไปให้ Niby the Almighty ใน Felwood" },
        description = { "407:1326124146:1915366431", "Kroshius กองอยู่ตะวันออกเฉียงเหนือใน Shatter Scar Vale รับไฟเฟลไปใช้กับซาก น่าปลุก Infernal ที่ล้มลงได้\n\nจากนั้นข้าคาดเต็มที่ว่ามันจะฆ่าเจ้ากับเพื่อนที่พามา เชื่อเถอะ เจ้าจะอยากพาเพื่อน\n\nหากปาฏิหาริย์ทำให้ฆ่าได้ เอาแก่น Infernal กลับ Niby" },
        progress = { "17:1555199644:1298953893", "หลงทางหรือ?" },
        completion = { "112:314825263:1714017998", "ตกลงแล้วต้องตามนั้น! เร็ว รับนี่ จดไว้ ไม่มีเวลา! การอัญเชิญยิ่งใหญ่ที่สุดของข้ากำลังมา!" },
        required = { [18625] = { "23:1681237455:233318600", "แกนอินเฟอร์นัลของโครเชียส" } },
        objectiveLabels = {
            item = { ["Kroshius' Infernal Core"] = "แกนอินเฟอร์นัลของโครเชียส" },
        },
    },
    [7623] = { -- Lord Banehollow
        title = { "15:1075090954:563170191", "Lord Banehollow" },
        objective = { "138:1683316144:1666014888", "ซื้อ Shadowy Potions จาก Gorzeeki ใน Burning Steppes\n\nใช้ยาผ่าน Jaedenar ไปคุยกับ Lord Banehollow" },
        description = { "471:433456376:452607950", "Mor'zul ว่าอยากเปิดประตู Xoroth ต้องใช้ผงดาว Xorothian หาใน Azeroth ไม่ง่าย!\n\nผู้หนึ่งอาจมี Lord Banehollow ที่ Jaedenar ฐาน Shadow Council คุยแล้วอาจยอมให้\n\nแต่จะเข้า Jaedenar ต้องคลุมด้วยความชั่วร้ายแบบ Shadow Council ต้องใช้ยาเงามืดข้า และต้องจ่าย..." },
        completion = { "32:368674651:1995719947 C 69:52162057:858149382", "ความอดทนข้ายาวนับพันปี {class} แต่อย่าคิดว่าจะให้เวลาเจ้าเกินชั่วพริบตา..." },
    },
    [7624] = { -- Ulathek the Traitor
        title = { "19:1272632882:931848368", "Ulathek ผู้ทรยศ" },
        objective = { "80:1016199967:1461078703", "เผชิญหน้า Ulathek แล้วนำ The Traitor's Heart ไปให้ Lord Banehollow ใน Jaedenar" },
        description = { "438:2132419862:1044617446", "อยากเป็นที่โปรดหรือ? ฆ่าให้ข้า\n\nUlathek ผู้รับใช้น่าสมเพช หมอบต่อหน้าแต่แอบสมคบ Lord Hel'nurath ที่ Xoroth Hel'nurath จะชิงอำนาจที่นี่ และ Ulathek คือสายลับ...\n\nพิสูจน์ว่ารับใช้ข้าไม่ใช่คู่แข่ง ไปเผชิญในห้องที่ Shadow Hold ทางตะวันตก บอกว่าข้ารู้ความลับ ดูมันกลัว แล้วนำหัวใจผู้ทรยศมา!" },
        progress = { "90:192667297:2036007054", "ข้าลิ้มรสหัวใจ Ulathek บนปากได้แล้ว เนื้อผู้ทรยศหวานนัก..." },
        completion = { "183:178149112:1947850174 C 51:1822318844:2054509205", "อา วิเศษ! ปล่อยเน่าหนึ่งสัปดาห์หัวใจนี้จะอร่อยฉ่ำ! บางทีส่งคนไปเอาหัว Ulathek วางตรงหน้าระหว่างกิน...\n\nเจ้ารับใช้แล้ว {class} ความอดทนข้าจึงเพิ่ม เล็กน้อย" },
        required = { [18719] = { "19:1888666382:1842275498", "หัวใจของผู้ทรยศ" } },
        objectiveLabels = {
            item = { ["The Traitor's Heart"] = "หัวใจของผู้ทรยศ" },
        },
    },
    [7625] = { -- Xorothian Stardust
        title = { "18:414970120:1622645835", "ผงดาว Xorothian" },
        objective = { "94:564231016:209296868", "ซื้อ Xorothian Stardust จาก Ur'dan แล้วนำไปให้ Gorzeeki Wildeyes ใน Burning Steppes" },
        description = { "306:1873633954:1195644974", "มาหาข้าเพื่อผงดาว Xorothian? อยากเปิดประตูสู่แดนคู่แข่ง Hel'nurath? อาจจะขโมย Dreadsteed ล้ำค่าของมัน?\n\nได้ Ur'dan ผู้รับใช้มีผงดาว ไปเอาได้... หากจ่ายราคาไหว" },
        progress = { "27:1478276117:353196931 N 48:60829399:1516831090", "ไป Jaedenar แล้วหรือ {name}? ได้ผงดาวจาก Lord Banehollow ไหม?" },
        completion = { "303:655763602:1445080807", "นี่เอง! แทบไม่เชื่อว่าได้มา ต้องทำข้อตกลงใหญ่กับ Dreadlord หรือจ่ายมาก หรือทั้งคู่!\n\nMor'zul จะมีหมึกเร็ว ๆ นี้ ในที่สุดทำแผ่นจารึกให้เปิด Xoroth แล้วดึง Dreadsteed เลื่องชื่อมาได้!" },
        required = { [18687] = { "18:414970120:1622645835", "ผงดาวแห่งโซรอธ" } },
        objectiveLabels = {
            item = { ["Xorothian Stardust"] = "ผงดาวแห่งโซรอธ" },
        },
    },
    [7626] = { -- Bell of Dethmoora
        title = { "17:374527753:857213050", "ระฆัง Dethmoora" },
        objective = { "77:1551638883:618106107", "นำ Elixirs of Shadow Power 10 ชิ้นไปให้ Gorzeeki Wildeyes ใน Burning Steppes" },
        description = { "426:1477510322:2031132196", "Bell of Dethmoora ตั้งตามวอร์ล็อก Dethmoora Darkeyes ผู้ล่วงลับ เป็นหนึ่งในสามเครื่องมือสร้าง Circle of Greater Summoning เมื่อปรับกับวงล้อและเทียนถูก มันนำพลังอาร์เคนมหาศาล\n\nGorzeeki ผู้รับใช้สร้างระฆังได้ แต่ต้องมียาเสริมพลังเงาจำนวนมาก หาจากนักเล่นแร่แปรธาตุแล้วนำให้เขา" },
        progress = { "24:1283071297:285607790 N 100:492859495:829117342", "มียาหรือยัง {name}? Mor'zul ว่าต้องการ Bell of Dethmoora ทำมันใช้พลังเงามาก!" },
        completion = { "186:201813654:1925371936", "ดีมาก! หวังว่าไม่ยาก บางครั้งนักเล่นแร่แปรธาตุหวงผลงานเหลือเกิน...\n\nข้าจะทำระฆัง เก็บจนพร้อมพิธี" },
        required = { [9264] = { "22:628605362:900704803", "ยาเสริมพลังเงา" } },
        objectiveLabels = {
            item = { ["Elixir of Shadow Power"] = "ยาเสริมพลังเงา" },
        },
    },
    [7627] = { -- Wheel of the Black March
        title = { "24:1772158716:433317837", "วงล้อ Black March" },
        objective = { "87:1134830135:1667966584", "นำ Large Brilliant Shards 6 ชิ้น และ Dark Iron Ore 25 ชิ้นไปให้ Gorzeeki ใน Burning Steppes" },
        description = { "291:936985787:1599191203", "Wheel of the Black March กักและนำพลังรุนแรงจำเป็นต่อ Circle of Greater Summoning หาก Gozeeki จะสร้าง ต้องใช้ทั้ง Large Brilliant Shard จากนักลงมนตร์ และ Dark Iron Ore จากนักขุดชั้นครู\n\nรวบรวมให้ผู้รับใช้ข้า" },
        progress = { "106:1408662113:183515222", "Wheel of the Black March ไม่ง่ายและใช้วัสดุมาก รวบรวมหรือยัง?" },
        completion = { "398:43750431:1070601268", "มาแล้ว! ได้ยินว่าแร่ Dark Iron มีแต่ลึกใน Blackrock และเศษผลึกก็หายากแน่ ข้ามักทึ่งความทุ่มเทวอร์ล็อก หากใช้แรงนั้นจับแมลง โอ้... จะได้งานเลี้ยงยิ่งใหญ่!\n\nขอโทษ นอกเรื่องนิด ข้าจะสร้างวงล้อ เก็บจนพร้อมพิธี" },
        required = { [14344] = { "21:390863609:542366453", "เศษผลึกเจิดจ้าขนาดใหญ่" }, [11370] = { "13:1237961762:521673087", "แร่เหล็กดำ" } },
        objectiveLabels = {
            item = { ["Large Brilliant Shard"] = "เศษผลึกเจิดจ้าขนาดใหญ่", ["Dark Iron Ore"] = "แร่เหล็กดำ" },
        },
    },
    [7628] = { -- Doomsday Candle
        title = { "15:1212859876:432918772", "เทียนวันพิพากษา" },
        objective = { "72:1529355335:798793271", "นำ Black Dragonscales 35 ชิ้นไปให้ Gorzeeki Wildeyes ใน Burning Steppes" },
        description = { "377:315163248:2139047304", "Doomsday Candle เก็บไฟและส่งใส่ผู้ขัดพิธี เมื่อสร้าง Circle of Greater Summoning หากเทียนติด ปีศาจหลงมาจะถูกเผา!\n\nกักไฟไม่ง่าย ต้องใช้แก่นในเกล็ดมังกรดำ หาจากนักถลกหนังแล้วนำให้ Gorzeeki Wildeyes" },
        progress = { "32:695611443:1801529808 N 93:172937751:1292863555", "นำเกล็ดมังกรมาไหม {name}? ไม่อยากเริ่มเทียนจนมี... ไม่งั้นอาจระเบิดทั้งค่าย!" },
        completion = { "209:724621812:348883883", "อา ดีมาก ต้องใช้กักไฟเทียน เมื่อมีเกล็ดแล้วจะทำ เก็บจนพร้อมพิธีสร้าง Circle of Greater Summoning" },
        required = { [15416] = { "17:1029596263:1938301188", "เกล็ดมังกรดำ" } },
        objectiveLabels = {
            item = { ["Black Dragonscale"] = "เกล็ดมังกรดำ" },
        },
    },
    [7629] = { -- Imp Delivery
        title = { "12:1635038396:1013783068", "ส่งอิมป์" },
        objective = { "130:948869813:1953355844", "นำ Imp in a Jar ไปห้องเล่นแร่แปรธาตุใน Scholomance หลังสร้างแผ่นหนังแล้ว คืนโหลให้ Gorzeeki Wildeyes" },
        description = { "458:1068939887:1677933480", "ยังต้องทำอีกขั้นสำหรับแผ่นหนัง Mor'zul ต้องใช้กระดาษใส่ผงดาว Xorothian และ... ข้าทำที่นี่ไม่ได้ ไร้อุปกรณ์!\n\nแต่มีห้องเล่นแร่แปรธาตุครบทุกอย่างใน Scholomance บนเกาะ Caer Darrow แห่ง Plaguelands\n\nข้าไปไม่ได้ รับโหลนี้ ข้างในมีอิมป์ฉลาด ปล่อยในห้องนั้น มันจะใส่พลังแผ่นหนัง" },
        progress = { "34:1457990267:2116597033 N 58:1706302536:1257185641", "ไป Scholomance หรือยัง {name}? อิมป์ใส่ผงดาวในแผ่นหนังแล้วหรือ?" },
        completion = { "152:951264362:468879782 N 91:1547360742:1980393411", "อา ดี J'eevee ทำแล้ว Scholomance เป็นอย่างไร? มีเสน่ห์ใช่ไหม? แมลงที่นั่น... ได้ยินว่าอร่อย!\n\nทำดี {name} และขอบใจคืนโหล ใช้มานาน... ไม่ขายนะ!" },
    },
    [7630] = { -- Arcanite
        title = { "8:895968537:1494452098", "Arcanite" },
        objective = { "56:1196639401:75015678", "นำ Arcanite Bar 3 แท่งไปให้ Gorzeeki ใน Burning Steppes" },
        description = { "391:115778371:463015958", "เมื่อระฆัง วงล้อ เทียนเสร็จ ควรทำ Black Lodestone ระหว่างพิธีต้องใช้รักษาสิ่งอื่นหากหยุดทำงาน\n\nทำ Lodestone ต้องใช้ Arcanite มีไหม? หากไม่... ต้องหาจากนักเล่นแร่แปรธาตุ\n\nมีแล้วกลับมา ข้าจะทำ Black Lodestone" },
        progress = { "26:1783838991:934644089 N 52:377895234:77377256", "มี Arcanite หรือยัง {name}? ได้แล้วข้าทำ Black Lodestone ให้ได้" },
        completion = { "209:692962756:1936041220", "ได้แล้ว! ทำดี! ทีนี้สร้าง Lodestone ได้ เมื่อพร้อมพิธีสร้าง Circle of Greater Summoning ต้องมีไว้ให้แน่ใจว่าพิธีไม่ล้มกลางคัน!" },
        required = { [12360] = { "12:582063918:1116898133", "แท่งอาร์คาไนต์" } },
        objectiveLabels = {
            item = { ["Arcanite Bar"] = "แท่งอาร์คาไนต์" },
        },
    },
    [7631] = { -- Dreadsteed of Xoroth
        title = { "20:2060973869:744844489", "Dreadsteed แห่ง Xoroth" },
        objective = { "99:1679297326:820345386", "อ่าน Mor'zul's Instructions อัญเชิญ Xorothian Dreadsteed ปราบมัน แล้วผูกวิญญาณกับเจ้า" },
        description = { "350:1821744851:1175577861 N 81:891795783:3795731", "เตรียมครบแล้ว ต้องทำพิธีสร้าง Circle of Greater Summoning จากนั้นใช้แผ่นหนังใส่ผงดาว Xorothian... เปิดประตู Xoroth\n\nข้าเขียนวิธีพิธีในม้วนบันทึก ศึกษาใกล้ชิด เพราะต้องทำทุกขั้นตรงจึงสำเร็จ\n\nโชคดี {name} ขอวิญญาณศัตรูหาทางสู่ถุงเก็บเศษวิญญาณเจ้าอย่างเร็ว" },
        completion = { "236:1933422874:135090583", "วิญญาณ Xorothian Dreadsteed แพ้แล้ว แม้โทสะเต้นผ่านสีข้างไร้กาย เจ้ารู้ว่าวิญญาณสัตว์เป็นของเจ้า...\n\nมันกระซิบเวทมืดในใจ ใส่ความรู้อัญเชิญ Dreadsteed ให้" },
    },
    [8419] = { -- An Imp's Request
        title = { "16:2146921246:1980679222", "คำขอของอิมป์" },
        objective = { "46:2028543649:805246711", "นำ Felcloth หนึ่งชิ้นไปให้ Impsy ใน Felwood" },
        description = { "N 400:1071080706:1318598864", "{name} อิมป์ชื่อ Impsy ใน Felwood ขอพบ แปลกหน่อยที่ให้เอา Felcloth เป็นไมตรี ด้วยพลังวอร์ล็อกที่มี ข้าเดาว่ารู้ว่าเซเทอร์ Felwood ถือผ้านี้\n\nหา Impsy เหนือ Bloodvenom Falls ที่ได้ยินว่าสวยเวลานี้ของปี" },
        progress = { "24:871782389:192363350", "มี Felcloth ข้าไหม?" },
        completion = { "16:1906258244:1123980397 C 151:1632166236:1665192497", "เป็น{class}ยอดเยี่ยมจริง!\n\n<Impsy แนบ Felcloth กับหน้า>\n\nโอ้ ชอบสัมผัสมัน วิธีเผาผิวและถักความคิดชั่วในใจ..." },
        required = { [14256] = { "8:1251982681:2100526280", "ผ้าเฟล" } },
        objectiveLabels = {
            item = { ["Felcloth"] = "ผ้าเฟล" },
        },
    },
    [8420] = { -- Hot and Itchy
        title = { "13:393909849:503331826", "ร้อนและคัน" },
        objective = { "46:2028543649:805246711", "นำ Felcloth หนึ่งชิ้นไปให้ Impsy ใน Felwood" },
        description = { "412:210318071:1042631197", "อาจฟังแปลกจากอิมป์ แต่ข้าอยากมีสัตว์เลี้ยงเอง จริงนะ ไม่ยุติธรรมที่ Niby ได้ข้า แต่ข้าไม่ได้อะไร!\n\nที่จริงไม่ต้องมีชีวิตก็ได้ ต้องมีของเริ่มทำ เช่น Felcloth บางครั้งเซเทอร์ที่นี่มี แค่ฆ่าพอจนพบ ฟังไม่แย่ใช่ไหม?" },
        progress = { "24:871782389:192363350", "มี Felcloth ข้าไหม?" },
        completion = { "190:1393244622:1478859452", "ว้าว! ใจดีเกิน โดยเฉพาะวอร์ล็อก!\n\n<Impsy แนบ Felcloth กับหน้า>\n\nโอ้ ชอบสัมผัสมัน วิธีเผาผิวและถักความคิดชั่วในใจ..." },
        required = { [14256] = { "8:1251982681:2100526280", "ผ้าเฟล" } },
        objectiveLabels = {
            item = { ["Felcloth"] = "ผ้าเฟล" },
        },
    },
    [8421] = { -- The Wrong Stuff
        title = { "15:1890399108:141180295", "ของผิดประเภท" },
        objective = { "67:805312456:2129935119", "นำ Rotting Wood 10 ชิ้น และ Bloodvenom Essence 4 ชิ้นไปให้ Impsy ใน Felwood" },
        description = { "405:89223981:1685127328", "เมื่อมี Felcloth เริ่มทำสัตว์เลี้ยงของข้าได้จริง\n\nแต่ต้องมีตา ช่วยฉีกไม้ผุจากพวก Irontree ให้แกะตางามหน่อย อยู่เหนือใน Irontree Woods\n\nยังต้องใช้ Bloodvenom Essence ให้กลิ่นปีศาจใหม่ Ooze แปดเปื้อนถือไว้ อยู่ใกล้ข้ากับ Niby นี่เอง" },
        progress = { "22:1226364863:885794168", "มีของไหม?" },
        completion = { "28:1158910381:1485193939", "จะใช้ได้ดีมาก" },
        required = { [20613] = { "12:1218559376:270094535", "ไม้ผุ" }, [20614] = { "18:2021175785:2104870148", "แก่นพลังพิษโลหิต" } },
        objectiveLabels = {
            item = { ["Rotting Wood"] = "ไม้ผุ", ["Bloodvenom Essence"] = "แก่นพลังพิษโลหิต" },
        },
    },
    [8422] = { -- Trolls of a Feather
        title = { "19:1571645645:358685171", "โทรลล์กับขนนก" },
        objective = { "68:1513920025:691693207", "นำ Voodoo Feathers รวม 6 ชิ้นจากโทรลล์ในวิหารจมมา" },
        description = { "256:1936354656:92223107 N 107:1036808675:1962156640", "สัตว์เลี้ยงแทบเสร็จ ต้องมีของยัดไส้\n\nมีแต่ขนนกวูดูโทรลล์วิหารจมจึงได้ Gasher, Mijan, Zolo, Hukku, Zul'lor และ Loro ฆ่า ฆ่าทั้งหมด\n\nไม่ใช่งานเล็ก {name} ข้าจะทำให้คุ้มโดยให้ของ Niby เขาคงไม่ต้องใช้หรอก" },
        progress = { "52:1618521296:1965542629", "นำขนนกมาไหม? ตุ๊กตาต้องยัดไส้!" },
        completion = { "152:1183461630:1540159784", "วิเศษ สัตว์เลี้ยงเสร็จแล้ว!\n\n<Impsy รีบยัดตุ๊กตาแล้วกอดแบบปีศาจ>\n\nโอ้ ผลข้างเคียงขนนกวูดูแปลกจริง..." },
        required = { [20606] = { "20:116773895:110391659", "ขนนกวูดูสีอำพัน" }, [20607] = { "19:47936181:1879616036", "ขนนกวูดูสีน้ำเงิน" }, [20608] = { "20:1196264854:1089628285", "ขนนกวูดูสีเขียว" } },
        objectiveLabels = {
            item = { ["Amber Voodoo Feather"] = "ขนนกวูดูสีอำพัน", ["Blue Voodoo Feather"] = "ขนนกวูดูสีน้ำเงิน", ["Green Voodoo Feather"] = "ขนนกวูดูสีเขียว" },
        },
    },
    [65593] = { -- Hearts of the Lovers
        title = { "20:295103591:1244567705", "หัวใจคู่รัก" },
        objective = { "99:352415587:1770068154", "นำหัวใจของ Avelina Lilly และ Isaac Pearson ไปให้ Carendin Halgar ใน Temple of the Damned" },
        description = { "481:1066584041:944529528", "อินคิวบัสถูกดึงด้วยหัวใจคู่รัก รักปวดร้าวที่สุดสร้างเหยื่อล่อที่ต้านไม่ได้ที่สุด\n\nญาณพบสองคนเหมาะอย่างยิ่ง\n\nAvelina Lilly ใน Silverpine Forest ตัดเย็บให้พ่อมดที่ล้มลงใน Ambermill ส่วน Isaac Pearson ใน Barrens หวังสร้างชื่อที่เมืองริมทะเล Ratchet\n\nทำงานคนละฟากโลก แต่ใจโหยหาเพียงกันและกัน นำหัวใจให้ Carendin" },
        progress = { "4:1110228981:147916455 N 58:267503364:1076428266", "อา {name} กลับมาแล้วหรือ เจ้าได้หัวใจของคู่รักคู่นั้นมาหรือไม่?" },
        completion = { "31:1442900257:1966563782 N 9:1603800330:970587339", "เป็นไปตามคาด ทำได้ยอดเยี่ยม {name}\n\nพวกโง่เอ๊ย", variants = { { "31:1442900257:1966563782 N 84:775750947:2054917373", "เป็นไปตามคาด ทำได้ยอดเยี่ยม {name}\n\n<Carendin ถือหัวใจไว้ข้างละดวง แล้วค่อย ๆ นำมาประกบกัน>\n\nพวกโง่เอ๊ย" } } },
        required = { [190179] = { "15:493768972:1760363257", "หัวใจของ Avelina" }, [190180] = { "13:853336522:1512835516", "หัวใจของ Isaac" } },
        steps = { { "15:493768972:1760363257", "หัวใจของ Avelina" }, { "13:853336522:1512835516", "หัวใจของ Isaac" } },
    },
    [65597] = { -- The Binding
        title = { "11:105979108:1835480523", "พันธนาการ" },
        objective = { "144:379613725:1396270119", "ใช้ Lovers' Hearts อัญเชิญและสยบ Incubus แล้วคืน Lovers' Hearts ให้ Carendin Halgar ใน Magic Quarter ของ Undercity" },
        description = { "250:159523075:265626387 N 88:311757204:1627690470", "ถึงเวลา นำหัวใจลงวงอัญเชิญด้านล่าง วางกลางวงเรียกอินคิวบัส\n\nปีศาจจะไม่พอใจเมื่อรู้ว่าถูกล่อเข้ากับดัก อย่าหลงเล่ห์ {name} ต้องสยบเต็มที่\n\nเมื่อนั้นจึงสอนคาถาผูกตามเจตนาได้" },
        progress = { "195:2508661:1297278200 N 1:46:46", "อินคิวบัสต่อสู้เก่ง แต่เสน่ห์ลวงตาคืออาวุธที่ร้ายกาจที่สุดของมัน เพียงเจ้าพลาดไปชั่วขณะ ปีศาจจะฉวยโอกาสสะกดใจเจ้า\n\nอย่ายอมให้มันทำได้ {name}" },
        completion = { "83:1837699432:946998842 C 133:1918906137:414478485 N 93:7734023:2016252352", "น่าประทับใจ น่าประทับใจมาก พวกซายาดถนัดล่อลวงเหล่าผู้มีวันตาย {class}หลายคนคิดว่าตนแข็งแกร่งพอจะสั่งมันได้ แต่กลับเป็นฝ่ายถูกมันสั่งเสียเอง\n\nเจ้ายังตั้งมั่นแม้ผ่านบททดสอบนี้ {name} ความพยายามของเจ้าคู่ควรกับรางวัล ข้าจะสอนคาถาอัญเชิญอินคิวบัสให้เจ้า" },
        required = { [190181] = { "14:228960496:2135764256", "หัวใจของคู่รัก" } },
        steps = { { "14:228960496:2135764256", "หัวใจของคู่รัก" } },
        objectiveLabels = {
            monster = { ["Summoned Incubus slain"] = "ปราบ อินคิวบัสที่ถูกอัญเชิญ" },
        },
    },
    [65601] = { -- Love Hurts
        title = { "10:1278861689:1216983974", "รักทำร้าย" },
        objective = { "30:1742194806:2107570112", "คุยกับ Magar ใน Orgrimmar" },
        description = { "242:1500394045:1011692259 N 248:1104141104:1352429024", "Sayaad เพศชายเรียกว่าอินคิวบัส เป็นสิ่งชั่วร้ายล้ำลึก มีจุดหมายเด็ดเดี่ยว\n\nต้องล่อสู่โลกด้วยวัตถุแทนรักและภักดีใหญ่หลวง\n\nหากไว้ใจคนตาบอดนำทาง {name} จงฟัง ไปตะวันออกจาก Cleft of Shadow ตามถนนหลัก Orgrimmar จะพบ Magar เขาโหยหาคู่ครอง Krilge กลับ\n\nไปหา เขาจะให้ตามสิ่งล้ำค่า นั่นคือกุญแจที่ต้องนำให้ Gan'rul" },
        completion = { "91:1052494710:1053371909", "ใครบอกเรื่อง Krilge? มีข่าวหรือ? อย่ามาล้อเล่นกับข้า..." },
    },
    [65602] = { -- What Is Love?
        title = { "13:1701715015:816844674", "ความรักคืออะไร?" },
        objective = { "99:632756088:1308454731", "นำ Wooden Figurine กลับไปให้ Gakin the Darkbinder ใน Mage Quarter ของ Stormwind" },
        description = { "502:1719757176:509284069", "ต้องใช้วัตถุทรงพลังล่ออินคิวบัส สิ่งแทนความรักและภักดีมาก\n\nญาณข้าพบรูปแกะเล็กที่เหมาะพิธี\n\nหลายพันปีก่อนเป็นของคู่รักรุ่นเยาว์ เจ้าของเดิมไม่อยู่แล้ว แต่ของแทนใจรอดถึงวันนี้\n\nตามถนนเหนือเข้า Ashenvale แล้วตะวันตกผ่าน Maestra's Post จะเห็นบ้านท่ามกลางต้นไม้ สิ่งที่หาอยู่ที่นั่น" },
        progress = { "40:1235628956:782513765", "กลับมาแล้วสินะ คงทำสำเร็จใช่ไหม?" },
        completion = { "226:1709302265:600074811", "<Gakin พลิกรูปแกะสลักไม้ไปมาในมือ>\n\nข้าสัมผัสพลังแห่งความรู้สึกที่สถิตอยู่ในวัตถุชิ้นนี้ได้ กาลเวลายังทำให้มันจางลงไม่ได้ อินคิวบัสจะถูกมันดึงดูดเหมือนแมลงวันตอมน้ำผึ้ง\n\nTakar ไม่เคยทำให้ผิดหวัง" },
        required = { [190309] = { "15:2123645020:1330280729", "ตุ๊กตาไม้แกะสลัก" } },
        steps = { { "15:2123645020:1330280729", "ตุ๊กตาไม้แกะสลัก" } },
    },
    [65603] = { -- The Binding
        title = { "11:105979108:1835480523", "พันธนาการ" },
        objective = { "137:268479623:1862378364", "ใช้ Wooden Figurine อัญเชิญและสยบ Incubus แล้วคืน Wooden Figurine ให้ Gakin the Darkbinder ที่ Slaughtered Lamb" },
        description = { "494:1364621905:189192157", "ถึงเวลา นำรูปแกะลงสุสานใต้ดินด้านล่าง เตรียมวงอัญเชิญแล้ว วางมันกลางวง\n\nประตูจะเปิด อินคิวบัสข้ามสู่โลกเรา\n\nอย่าดูเบา Sayaad ปีศาจไม่ลังเลโจมตีเมื่อรู้กล ต้องดึงทุกสิ่งที่เรียนมาปราบ\n\nหากสำเร็จกลับมา ข้าจะผูกให้ตามเจตนา หากพลาด วิญญาณเจ้าสูญแน่" },
        progress = { "213:887983753:498515544", "อินคิวบัสจะใช้เสน่ห์และกลลวงทำให้เจ้าลดการป้องกัน ปีศาจตนนี้เก่งเรื่องชักจูงจิตใจของผู้มีวันตาย\n\nจำไว้ว่าอะไรก็ตามที่มันเสนอให้ล้วนเป็นเรื่องหลอกลวง สำหรับมัน เจ้าเป็นเพียงเหยื่อ" },
        completion = { "9:1775424254:365803329 N 69:1313026970:1100488911 C 236:1311272308:1914978340", "ไม่เลวนี่ {name} เจ้าเอาชนะปีศาจได้และยังคงตั้งมั่นในเจตจำนงของตน\n\n{class}หลายคนเคยคิดว่าตนแข็งแกร่งพอจะพันธนาการซายาด แต่กลับกลายเป็นอาหารมื้อต่อไปของมัน ข้ายินดีที่เจ้าไม่พลาดเช่นนั้น\n\nดูให้ดี ข้าจะสอนบทอัญเชิญอินคิวบัสที่เจ้าพันธนาการไว้" },
        required = { [190186] = { "15:2123645020:1330280729", "ตุ๊กตาไม้แกะสลัก" } },
        steps = { { "15:2123645020:1330280729", "ตุ๊กตาไม้แกะสลัก" } },
        objectiveLabels = {
            monster = { ["Summoned Incubus slain"] = "ปราบ อินคิวบัสที่ถูกอัญเชิญ" },
        },
    },
    [65604] = { -- The Binding
        title = { "11:105979108:1835480523", "พันธนาการ" },
        objective = { "120:689904023:1122993101", "ใช้ Withered Scarf อัญเชิญและสยบ Incubus แล้วคืน Withered Scarf ให้ Gan'rul Bloodeye ใน Orgrimmar" },
        description = { "195:1063397632:458522026 N 308:93310848:1042506930", "ใช่... เห็นแล้ว สัมผัสอารมณ์ตกค้างในเส้นด้าย รักถักในรอยเย็บ อินคิวบัสต้านไม่ได้\n\nนำไปวงอัญเชิญในกระโจม Neeru {name} เรียกอินคิวบัสร้ายแล้วแสดงอำนาจ อย่าหวังยอมเงียบ เตรียมเวทและตัวสู้ การดูเบาปีศาจเป็นความผิดสุดท้ายของวอร์ล็อกมามาก\n\nเมื่อปราบ คืนผ้าให้ข้า จะบอก Magar ว่าเจ้าพบอะไร" },
        progress = { "202:1583712683:1111241190 N 37:376822863:1089531159", "ซายาดครอบงำจิตใจและทรมานวิญญาณ รูปลักษณ์ของพวกมันทำให้ใจเจ้าปลาบปลื้มจนไม่ทันระวังตัว ตอนที่พวกมันฉีกเนื้อเจ้าด้วยแส้และกรงเล็บ\n\nอย่าเคลิ้มไปกับเสน่ห์ของอินคิวบัส {name} รีบสังหารมันให้จบเรื่อง" },
        completion = { "477:1179041484:1854187857", "ฮ่า! ชนะตามที่คิดไว้!\n\nอินคิวบัสถูกปราบแล้ว ข้ายินดีจะสอนเจ้าอัญเชิญมัน พลังของเจ้าเพิ่มขึ้นเรื่อย ๆ ข้าแน่ใจว่านี่เป็นเพียงก้าวหนึ่งไปสู่พลังที่ยิ่งใหญ่กว่า\n\nข้าจะนำผ้าพันคอไปคืน Magar ข้ารู้จักออร์คผู้นั้นมาหลายปี ไม่เคยคิดเลยว่าเขาจะห่วงใยใครได้เท่าที่เขาห่วงใย Krilge\n\nเรื่องนี้เตือนใจว่าอะไรทำให้เราต่างจากปีศาจ เราใช้ความมืดของพวกมันได้ แต่พวกมันจะไม่มีวันบงการเรา" },
        required = { [190187] = { "14:1561040940:777639432", "ผ้าพันคอเก่าเปื่อย" } },
        steps = { { "14:1561040940:777639432", "ผ้าพันคอเก่าเปื่อย" } },
        objectiveLabels = {
            monster = { ["Summoned Incubus slain"] = "ปราบ อินคิวบัสที่ถูกอัญเชิญ" },
        },
    },
    [65610] = { -- Wish You Were Here
        title = { "18:1956038287:327965262", "อยากให้เจ้าอยู่ที่นี่" },
        objective = { "99:894909846:1150972046", "สำรวจ Fallen Sky Lake ใน Ashenvale แล้วรายงานสิ่งที่พบแก่ Gan'rul Bloodeye ใน Orgrimmar" },
        description = { "430:1034802278:1052040263", "ข้าพบ Krilge ระหว่างทำ Mooncloth ใน Ashenvale เขาประจำป้องกันผู้คนจากภัย ก่อนหายไป...\n\nเลิกค้นแล้ว ถือว่าหนีทัพ แต่ข้าไม่เชื่อ\n\nเคยพบกันบ่อยที่ Fallen Sky Lake ก่อนสัตว์หนองน้ำดุยึด\n\nปกติไม่ขอใคร แต่หากไป Ashenvale หาร่องรอยเขาได้ จะขอบใจมาก" },
        progress = { "16:1205405492:147321852", "ใช่ มีอะไร?" },
        completion = { "27:699801113:524056956 N 70:2026566103:1803798213", "เจ้าถืออะไรมา {name}? ผ้าพันคอที่ทำจาก... Mooncloth หรือ? คงไม่ได้คิดจะมาจีบข้าหรอกนะ" },
        required = { [190232] = { "14:1561040940:777639432", "ผ้าพันคอเก่าเปื่อย" } },
        steps = { { "14:1561040940:777639432", "ผ้าพันคอเก่าเปื่อย" } },
    },
    [98575] = { -- Tainted Tablet
        title = { "14:1127936657:1465989954", "แผ่นจารึกแปดเปื้อน" },
        objective = { "83:666591764:1031797273", "อ่าน Tainted Tablet แล้วคุยกับ Nartok ใน Den ที่ Valley of Trials" },
        description = { "47:542172104:1998871674 N 228:1599106677:216182037", "อา มีแผ่นจารึกมาถึงตอนไม่อยู่ {name}\n\nปกติข้าเลี่ยงวอร์ล็อกหากทำได้ แต่ควรอ่านเมื่อมีเวลา หากจำไม่ผิด มาจาก Nartok ครูใหม่ เขาอยากคุยเมื่อพร้อม" },
        completion = { "344:88591956:1710372768", "เพิ่งเห็นแวบหนึ่งของพลังที่เป็นของเจ้าได้ พวกอ่อนแอโง่กลัววิถีเรา แต่ด้วยความกล้าและไหวพริบ เรากำหนดชะตาเอง\n\nปกป้องพลังให้ดี ผู้หวาดกลัวโจมตีสิ่งไม่เข้าใจ\n\nตอนนี้เป็นพวกเรา ต้องฝึกคาถากลับมาหาข้า" },
        progress = { "367:924094895:1725017056", "อา ได้ข้อความแล้ว ดีเยี่ยม พวกเราออร์คมีประวัติยาวนานปั่นป่วนกับสิ่งจาก Nether แต่บัดนี้สร้างทางเอง ควบคุมชะตา เจ้าก็ยึดพลังสร้างอนาคตผู้คนได้ เมื่อผู้นำสะดุด เราพร้อมเดินหน้าและชิงที่อันควร เจ้าจะเป็นผู้โดดเด่นในหมู่โทรลล์" },
        required = { [282346] = { "14:1127936657:1465989954", "แผ่นจารึกแปดเปื้อน" } },
        steps = { { "14:1127936657:1465989954", "แผ่นจารึกแปดเปื้อน" } },
    },
    [792] = { -- Vile Familiars
        title = { "14:2096056998:498448343", "อสูรรับใช้ชั่วร้าย" },
        objective = { "67:1006053680:1657686130", "สังหาร Vile Familiar 12 ตัว\n\nแล้วกลับไปหา Zureetha Fargaze ด้านนอก The Den" },
        description = { "56:1387383516:1316230202 C 413:654502074:961183872", "ข้าเชื่อว่า Valley of Trials จะสอนท่านได้มาก ท่าน{class}ผู้เยาว์\n\nข้าถูกส่งมาชี้แนะท่านที่หุบเขา แต่พบว่าความชั่วร้ายกำลังก่อตัวขึ้นที่นี่...\n\nพวกที่เรียกตัวเองว่า Burning Blade มีชุมนุมลับใน Valley of Trials มันซ่อนตัวในถ้ำทางตะวันออกเฉียงเหนือ และฝูง Vile Familiar ทะลักออกมาจากปากถ้ำก่อความวุ่นวาย\n\nงานแรกในการต่อกรกับ Burning Blade คือกำจัดสัตว์รับใช้พวกนี้ ฆ่าพวกมันให้มาก แล้วหากรอดก็กลับมาหาข้า" },
        progress = { "124:259647487:202144409", "จะพิสูจน์ฝีมือในการสู้กับ Burning Blade ได้ ท่านต้องกำจัด Vile Familiar ของพวกมันเสียก่อน ทำเสร็จแล้วกลับมาหาข้า" },
        completion = { "20:1921578502:569519135 N 150:83139352:1228716531", "ทำได้ดี {name}\n\nแม้ Vile Familiar จะเป็นเพียงสัตว์เลี้ยงของพลังมืดใน Burning Blade แต่ชัยชนะของท่านบ่งบอกว่าจะทำงานที่ยิ่งใหญ่กว่านี้ได้" },
        objectiveLabels = {
            monster = { ["Vile Familiar slain"] = "ปราบ อสูรรับใช้ชั่วร้าย" },
        },
    },
    [906] = { -- Betrayal from Within
        title = { "20:958511388:1642172495", "การทรยศจากพวกเดียวกัน" },
        objective = { "60:244463208:530933681", "นำ Lok's Skull ไปให้ Thork ที่ Crossroads ใน Barrens" },
        description = { "44:1406374305:176287190 R 312:365300236:1382609141 R 23:40365558:558466023", "นำศีรษะ Lok ไปให้ Thork ใน Crossroads {race} <พ่นลมทางจมูก> เขาน่าจะเข้าใจว่าเกิดอะไรกับเผ่าข้าโดยไม่ต้องพูด ฮ่า ถึงเขาจะไม่เชื่อว่า Mangletooth ช่วยทำ <พ่นลมทางจมูก> เรื่องแบบนี้ก็เถอะ แต่ข้ามั่นใจว่าเขาจะตอบแทนวีรกรรมยิ่งใหญ่ของเจ้า <พ่นลมทางจมูก>\n\nข้าจะอวยพรด้วยพลังของ Agamaggan ต่อไปตราบใดที่ยังอยู่ในกรงนี้ {race} ระหว่างนี้ ลาก่อน", variants = { { "395:2080486017:1184113554", "นำศีรษะ Lok ไปให้ Thork ใน Crossroads Skyborne <พ่นลมทางจมูก> เขาน่าจะเข้าใจว่าเกิดอะไรกับเผ่าข้าโดยไม่ต้องพูด ฮ่า ถึงเขาจะไม่เชื่อว่า Mangletooth ช่วยทำ <พ่นลมทางจมูก> เรื่องแบบนี้ก็เถอะ แต่ข้ามั่นใจว่าเขาจะตอบแทนวีรกรรมยิ่งใหญ่ของเจ้า <พ่นลมทางจมูก>\n\nข้าจะอวยพรด้วยพลังของ Agamaggan ต่อไปตราบใดที่ยังอยู่ในกรงนี้ Skyborne ระหว่างนี้ ลาก่อน" } } },
        progress = { "16:1205405492:147321852", "ใช่ มีอะไร?" },
        completion = { "56:461909375:1639156841 N 253:636952021:2119309229 N 1:46:46", "เจ้าพบผู้นำ Razormane แล้วฆ่าเขาด้วยตัวเองหรือ {name}? น่าทึ่ง\n\nข้าพูดไม่ออก แต่ไม่ได้หมายความว่าข้าไม่ขอบคุณ ชาว Crossroads ควรเคารพความแข็งแกร่งของเจ้า\n\nต้องยอมรับว่าข้าคิดว่าผู้นำการปล้นเสบียงของเราเป็นควิลบอร์อีกตัวหนึ่ง ขอบใจอีกครั้ง {name}" },
        required = { [5072] = { "11:1275814371:117742035", "กะโหลกของ Lok" } },
        steps = { { "11:1275814371:117742035", "กะโหลกของ Lok" } },
    },
    [63] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "186:1874494735:56401142", "ปราบ Corrupt Manifestation of Water แล้ววาง Corrupted Manifestation's Bracers พร้อม Remaining Drops of Purest Water บน Brazier of Everfount ใน Silverpine Forest" },
        description = { "502:52510827:897754630", "ริมฝั่ง Silverpine ทางตะวันตกของ Sepulcher มีศาลที่ถูกโรคระบาดทำให้แปดเปื้อน วิญญาณที่นั่นไม่พูดกับคนของเราอีกแล้ว เจ้าต้องปราบร่างสำแดงนั้นและชำระแอ่งน้ำ\n\nนำปลอกแขนของธาตุพร้อมหยดน้ำยาของ Brine ที่เหลือไปวางบนกระถางไฟ พิธีนี้น่าจะเรียกวิญญาณบริสุทธิ์ให้เจ้าสื่อสารด้วยได้\n\nนำหลักฐานว่าทำสำเร็จกลับมา แล้วข้าจะมอบโทเทมให้เจ้า" },
        progress = { "296:818547111:1263564346", "กระถางไฟยังสะท้อนแสงรอบบริเวณ เปลวไฟไหวเล็กน้อยเมื่อเจ้าเข้าใกล้\n\nความแปดเปื้อนตามเนินเขาดูจะยังไม่ลุกลามมาถึง นอกจากส่วนประกอบที่ขาดอยู่ กระถางไฟก็ดูพร้อมสำหรับพิธีอัญเชิญร่างสำแดงแห่งน้ำที่ผ่านการชำระแล้ว" },
        completion = { "208:327508514:1282041885", "เจ้าวางปลอกแขนบนกระถางไฟ แล้วเทหยดน้ำยาของ Brine ที่เหลือลงในเปลวไฟ เสียงเปรี๊ยะดังขึ้นเมื่อหยดน้ำกระทบไฟ และเจ้าเริ่มกล่าวถ้อยคำเรียบง่ายที่ Islen สอน..." },
        required = { [7812] = { "31:747673525:172901740", "ปลอกรัดแขนของ Corrupt Manifestation" }, [7811] = { "31:954020276:1472835043", "หยดน้ำบริสุทธิ์ที่สุดที่เหลือ" } },
        steps = { { "31:747673525:172901740", "ปลอกรัดแขนของ Corrupt Manifestation" }, { "31:954020276:1472835043", "หยดน้ำบริสุทธิ์ที่สุดที่เหลือ" } },
    },
    [96] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "59:381732412:2117250147", "นำ Shard of Water ไปให้ Islen Waterseer ใน Barrens" },
        description = { "160:1701097664:1500739457", "รับเศษผลึกไป รับไปแล้วมอบชีวิต\n\nมอบชีวิตแล้วจงเข้าใจ เข้าใจว่าน้ำคือชีวิต... ความแปดเปื้อนขัดขวางชีวิต\n\nเจ้าปกป้องและมอบชีวิตด้วยพลังแห่งน้ำ" },
        progress = { "380:454392355:438712885", "เจ้ากลับมาแล้ว เยี่ยมมาก!\n\nการเดินทางไป Silverpine เป็นอย่างไร ใช้เวลานานไหม?\n\nข้าบอกได้ยากว่าเจ้าทำสำเร็จหรือไม่ เพราะแผ่นดินมากมายแปดเปื้อนไปแล้ว กลิ่นเหม็นของมันกลบความดีที่เจ้าอาจทำไว้ แต่ความสำเร็จเล็ก ๆ บางครั้งก็สำคัญเท่าความสำเร็จใหญ่ การชำระน้ำที่นั่นมีความหมายยิ่งต่อเจ้าและชาแมนทุกคน" },
        completion = { "49:1422651382:425598186 N 397:1078273132:83109868", "นี่คือหลักฐานที่ข้าขอ ทำได้ดีมาก {name}\n\nข้ายินดีที่ได้เป็นคนแรกที่แสดงความยินดีและมอบสิ่งนี้ให้... โทเทมน้ำของเจ้า\n\nจงใช้ให้ดี และขอให้โชคดี\n\nอีกพักใหญ่กว่าจะถึงบททดสอบถัดไป จงเรียนรู้บทเรียนให้ดี น้ำบริสุทธิ์ไม่เพียงคืนชีวิตให้ผู้บาดเจ็บ แต่ยังให้ผลอื่นอีกมาก หากมีเวลา ข้าแนะนำให้ไปหาครูฝึกชาแมน พวกเขาอาจมีคาถาอื่นให้เจ้าเรียน", variants = { { "49:1422651382:425598186 N 312:1694428206:898946908 C 79:1425562515:1175951966", "นี่แหละหลักฐานที่ข้าขอ ทำได้ดีมาก {name}\n\nข้ายินดีที่ได้แสดงความยินดีกับเจ้าเป็นคนแรก และมอบสิ่งนี้ให้เจ้า... โทเท็มแห่งน้ำ\n\nจงใช้ให้ดี และขอให้โชคดี\n\nอีกพักใหญ่กว่าจะถึงบททดสอบครั้งต่อไป จงตั้งใจเรียนรู้ไว้ น้ำบริสุทธิ์ช่วยฟื้นพลังชีวิตให้ผู้บาดเจ็บได้ และยังมีผลอีกหลายอย่าง เมื่อมีเวลา ลองไปหาครูฝึก{class}ดู พวกเขาอาจมีเวทอื่นให้เจ้าเรียน" } } },
        required = { [7813] = { "14:140666625:860039488", "เศษผลึกน้ำ" } },
        steps = { { "14:140666625:860039488", "เศษผลึกน้ำ" } },
    },
    [100] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "63:503879362:1747834661", "คุยกับ Minor Manifestation of Water ใน Silverpine Forest" },
        description = { "186:1085543463:2115764861", "แสงสว่างระเบิดออกเมื่อเจ้ากล่าวคาถาจบ เสียงหยดน้ำกระทบเปลวไฟเงียบลง ประสาทสัมผัสของเจ้าถูกพลังท่วมท้น ขณะที่วิญญาณแปดเปื้อนรอบตัวถูกทำลาย" },
        completion = { "112:2075202244:1814868866", "ขอบคุณเจ้า ขอบคุณเหล่าชาแมน\n\nความแปดเปื้อนลดลง แต่ชีวิตยังคงร่อยหรอ ชาแมนต้องปกป้องชีวิต" },
        progress = { "186:1085543463:2115764861", "แสงสว่างระเบิดออกเมื่อเจ้ากล่าวคาถาจบ เสียงหยดน้ำกระทบเปลวไฟเงียบลง ประสาทสัมผัสของเจ้าถูกพลังท่วมท้น ขณะที่วิญญาณแปดเปื้อนรอบตัวถูกทำลาย" },
    },
    [220] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "65:834803967:606289123", "นำ Vial of Purest Water ไปให้ Islen Waterseer ใน Barrens" },
        description = { "204:142145991:2121491467", "Islen จะมีงานให้เจ้าอีกอย่างก่อนมอบโทเทมชิ้นถัดไป ไม่ว่างานนั้นจะเป็นอะไร ก็ต้องใช้น้ำในขวดที่ข้ามอบให้\n\nไปหานางได้แล้ว สักวันเราจะพบกันอีก" },
        progress = { "13:1366380142:1891123769 N 58:2067000419:160783575", "สวัสดีอีกครั้ง {name} เจ้าดูสบายดี\n\nอะไรพาเจ้ากลับมาหาข้าเร็วนัก?" },
        completion = { "440:1522225900:714988149 N 1:63:63", "อา น้ำหนึ่งขวดที่ Brine สร้างและอวยพร ทั้งยังเป็นเจ้าที่รวบรวมมาด้วยตนเอง\n\nน้ำนี้เป็นหัวใจของการปรุง Sapta ให้เจ้า และยังต้องใช้อีกงานหนึ่งด้วย\n\nSapta ที่ข้าปรุงจะช่วยให้เจ้ามองเห็นวิญญาณน้ำที่ศาลใน Silverpine Forest ทางใต้ของ Undercity ส่วนหยดน้ำที่เหลือ... ข้าจะบอกเมื่อเจ้ารู้สึกว่าพร้อม\n\nเจ้าพร้อมเดินทางอีกครั้งหรือยัง {name}?" },
        required = { [7810] = { "20:533830180:2011110999", "ขวดบรรจุน้ำบริสุทธิ์ที่สุด" } },
        steps = { { "20:533830180:2011110999", "ขวดบรรจุน้ำบริสุทธิ์ที่สุด" } },
    },
    [972] = { -- Water Sapta
        title = { "11:811447847:1444598440", "น้ำศักดิ์สิทธิ์แห่งธาตุน้ำ" },
        completion = { "73:860203964:1481364173 N 39:1259445020:559889539", "นำ Water Sapta นี้ไปหาแอ่งน้ำแปดเปื้อนใน Silverpine เถิด {name} ข้าเชื่อมั่นในความสามารถของเจ้า" },
        description = { "62:460331670:145263421", "ข้าเสียใจที่เห็นว่าเจ้าต้องใช้ Sapta อีกขวด แต่เจ้าก็ทำมาจนสมควรได้รับแล้ว" },
    },
    [1103] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "116:800512162:2102785396", "หากไม่ได้คุยกับ Minor Manifestation of Water ให้นำ Water Sapta ไปให้ Tiev Mordune ใน Silverpine Forest" },
        description = { { "491:2041001806:1470303042", "490:1534359578:1126862304" }, "สวัสดี สหาย! เจ้ามาชำระน้ำที่นี่และพิสูจน์ความเข้าใจต่อ Islen เหมือนกันหรือ?\n\nข้าเพิ่งปราบวิญญาณน้ำแปดเปื้อน และกำลังจะวางปลอกแขนกับหยดน้ำที่เหลือบนกระถางไฟ\n\nว่าอย่างไรนะ? อ้อ Tiev เข้าใจดีเวลามีอะไรผิดพลาด ถ้าต้องการพบวิญญาณน้ำบริสุทธิ์อีกครั้ง Tiev ช่วยได้\n\nนำ Water Sapta จาก Islen มาให้ข้าเป็นหลักฐานว่าพร้อม แล้วข้าจะรอส่งส่วนประกอบของข้า" },
        progress = { { "298:829947316:289353907", "297:1112375906:1724938989" }, "มี Sapta แล้วหรือ สหาย?\n\nข้ารู้จักอีกคนที่ประสบปัญหาหลังปราบวิญญาณน้ำแปดเปื้อน ดูเหมือนเขารอนานเกินไป จึงออกจากโลกวิญญาณเร็วกว่าที่ต้องการ ข้าไม่อยากให้ใครเจออย่างนั้นอีก จะรออยู่ตรงนี้สักพัก เผื่อมีคนต้องการความช่วยเหลือ" },
        completion = { { "322:924557531:2062528869", "321:2076585525:46284352" }, "อา ถ้าอย่างนั้นก็พร้อมแล้ว...\n\nข้าจะวางของลงในกระถางไฟ แล้วเจ้าจะได้คุยกับวิญญาณด้วย\n\nอย่ากังวลเรื่องใช้ Sapta มองโลกวิญญาณเลย Tiev คนนี้รู้เคล็ดลับเกี่ยวกับเวทของ Sapta อยู่บ้าง\n\nมาเถิด ลงไปที่ศาลกับข้า แล้วคุยกับเหล่าวิญญาณด้วยกัน สหาย" },
        required = { [6637] = { "11:811447847:1444598440", "น้ำซัปตา" } },
        objectiveLabels = {
            item = { ["Water Sapta"] = "น้ำซัปตา" },
        },
    },
    [1462] = { -- Earth Sapta
        title = { "11:318297221:1784516132", "น้ำศักดิ์สิทธิ์แห่งธาตุดิน" },
        objective = { "51:2032168458:637267500", "คุยกับ Seer Ravenfeather เพื่อขอ Earth Sapta อีกขวด" },
        completion = { "37:1177307499:328791381", "รับไป และจำไว้ว่านี่เป็นของศักดิ์สิทธิ์" },
        description = { "71:1538138461:1633980633", "เจ้ากลับมาหาข้าทั้งที่ไม่มี Sapta และไม่มีโทเทมแห่งดิน น่าเสียดาย" },
    },
    [1463] = { -- Earth Sapta
        title = { "11:318297221:1784516132", "น้ำศักดิ์สิทธิ์แห่งธาตุดิน" },
        objective = { "52:663806518:1561768438", "คุยกับ Canaga Earthcaller เพื่อขอ Earth Sapta อีกขวด" },
        completion = { "120:343957019:1174973168", "ข้ามอบให้ด้วยความเชื่อใจ เจ้าพิสูจน์ตนมาแล้วครั้งหนึ่ง แต่ข้าคิดว่าต่อไปควรระมัดระวังให้มากกว่านี้" },
        description = { "48:1926913117:1478594700 N 1:63:63", "เจ้าต้องใช้ Sapta อีกขวดเพื่อทำภารกิจหรือ {name}?" },
    },
    [1464] = { -- Fire Sapta
        title = { "10:1894250526:440813189", "น้ำศักดิ์สิทธิ์แห่งธาตุไฟ" },
        objective = { "44:700926519:1700655351", "คุยกับ Telf Joolam เพื่อขอ Fire Sapta อีกขวด" },
        completion = { "33:1648711972:59103623 N 25:333232212:744061430", "ขอให้เปลวไฟลุกโชนในหัวใจเจ้า {name}\n\nเหล่าธาตุกำลังรอเจ้าอยู่" },
        description = { "149:27312432:575831543", "ถ้าเจ้าพ่ายแพ้ในการต่อสู้กับร่างที่ปรากฏขึ้น มาคุยกับข้า ข้าจะให้ Sapta อีกขวดเพื่อให้เจ้ามองเห็นเหล่าวิญญาณที่ศาลด้านบน" },
    },
    [1516] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "72:57637571:180234307", "นำ Felstalker Hooves 2 ชิ้นไปให้ Canaga Earthcaller ใน Valley of Trials" },
        description = { "23:126865699:148228313 C 472:993387872:935159865", "ถึงเวลาแล้ว {class} น้อย เจ้าแข็งแกร่งขึ้น และจิตวิญญาณก็อดทนดุจแผ่นดิน การเลือกวิถีชาแมนแสดงว่าเจ้ามีปัญญาก่อนจะได้พิสูจน์ตนเสียอีก\n\nธาตุดินจะนำทางชะตาและเป็นส่วนหนึ่งของเจ้าหากพร้อม แต่เจ้าต้องยืนต่อหน้าแผ่นดินเอง หากพร้อม ก็จะเห็นสิ่งที่มีเพียงชาแมนเท่านั้นที่รู้\n\nไปหา Felstalker ทางเหนือ เก็บกีบของมันมาสองชิ้น แล้วกลับมา เราจะได้พูดถึงอนาคตของเจ้าต่อ" },
        progress = { "462:1268799530:448219279", "ความอดทนคือคุณธรรมสูงสุดของดิน แผ่นดินเฝ้ามองวัฏจักรทุกสิ่ง ภูเขากลายเป็นทะเลทราย แม่น้ำกลายเป็นหุบผา ดินดื้อดึงและมีปัญญาที่สุดในบรรดาธาตุ และไม่ยอมรับความใจร้อน\n\nตอนนี้ดินเรียกหาเจ้า เพราะยุคแห่งความขัดแย้งใกล้เข้ามา เมื่อกลับมาพร้อมความสำเร็จ เจ้าจะเข้าใกล้ความสมบูรณ์อีกขั้น\n\nผู้อื่นจะอิจฉาปัญญาของเจ้า และเกลียดเจ้าด้วยความเขลาของพวกเขาเอง" },
        completion = { "504:2099864557:1647822975", "ยอดเยี่ยม ความสำเร็จแสดงว่าเจ้าพร้อมแล้ว\n\nในบรรดาธาตุ ดินเป็นรากฐานของทุกสิ่ง เป็นกำลัง ความทนทาน และความอดทนของเจ้า ดินจะคุ้มครองก็ต่อเมื่อเจ้าให้ความเคารพอย่างเหมาะสม เช่นเดียวกับธาตุอื่น แม้แต่ดินก็เปลี่ยนใจได้ ดินคือรากฐานของชีวิต การสังเกตกฎของมันจะเพิ่มพูนปัญญา อย่าลืมความลับที่ดินแบ่งปัน\n\nข้าจะปรุง Sapta ให้ เมื่อรับมัน เจ้าจะตระหนักถึงเส้นทางของตน" },
        required = { [6640] = { "15:1092310331:2118891901", "กีบ Felstalker" } },
        steps = { { "15:1092310331:2118891901", "กีบ Felstalker" } },
    },
    [1517] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "43:1237838819:1842570737", "หา Spirit Rock แล้วดื่ม Earth Sapta" },
        description = { "497:678447682:1007709927", "Sapta คือเครื่องดื่มที่ผูกจิตวิญญาณของเรากับธาตุ น้ำยาที่ผสานเวทนี้ทำให้ผู้มีใจเด็ดเดี่ยวมองเห็นธาตุในแบบที่คนอื่นมองไม่เห็น จิตของเจ้าจะเชื่อมกับธาตุที่ใช้ปรุง Sapta มีชาแมนเพียงไม่กี่คนรู้สูตร\n\nต้องดื่ม Sapta ณ สถานที่ศักดิ์สิทธิ์เท่านั้น ห้ามที่อื่น จำไว้ให้ดี\n\nไปหา Spirit Rock ทางตะวันตกเฉียงใต้ อยู่สุด Hidden Path ดื่ม Sapta ที่นั่น แล้ว... เจ้าจะได้เห็นเอง" },
        completion = { "6:1572241333:73377271 N 494:48796717:699389557", "อา... {name}... แผ่นดินยินดีที่เจ้ามา\n\nเมื่อกายและจิตผูกพันกัน เจ้าจะก้าวต่อไปโดยรู้ว่าภูเขาคือกำลัง ทุ่งราบคือความอดทน และโลกคือแก่นแท้ของเจ้า\n\nเพียงยืนต่อหน้าดินด้วยความถ่อมตน เจ้าก็ผ่านพิธีนี้แล้ว แต่ธาตุอื่นไม่สงบเช่นนี้ อาจปั่นป่วนและมักรุนแรง ทว่านั่นคือธรรมชาติของธาตุ ธรรมชาติสองด้านที่ขัดแย้งกัน เจ้าต้องเรียนรู้ให้ลึกซึ้ง" },
    },
    [1518] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "69:1147210830:931239822", "นำ Rough Quartz ไปให้ Canaga Earthcaller ใน Valley of Trials" },
        description = { "311:833411082:1949499029 N 150:1751221446:451907108", "รับควอตซ์หยาบนี้ไปให้ Canaga Earthcaller เป็นหลักฐานว่าเราพบกัน เขาจะสร้างโทเทมให้ โดยใช้ก้อนหินนี้เป็นหัวใจ แม้ดูเล็ก เจ้าจะพบว่าขนาดไม่สำคัญ และสิ่งเล็กที่สุดก็อาจคงอยู่ได้นานกว่าสิ่งอื่นมากมาย\n\nจงอดทน {name} เข้มแข็งและแสวงหาปัญญา นี่คือสิ่งที่ดินขอ สุดท้ายเจ้าจะเป็นหนึ่งเดียวกับแผ่นดิน จงเคารพมันเช่นเดียวกับที่มันเคารพเจ้า" },
        progress = { "259:1713012490:1387923238", "ข้าขอเป็นคนแรกที่ต้อนรับเจ้าอย่างเต็มตัวสู่เส้นทางแรกจากสี่เส้น ซึ่งจะนำชะตาของเจ้าตลอดไป\n\nหากมีหินที่ดินมอบให้ ข้าจะมอบโทเทมตามที่มันสัญญา\n\nหากยังไม่มี ก็ไปจนกว่าจะพบทางของตน" },
        completion = { "85:346363627:1403491895 C 367:2022964021:434032575", "ยอดเยี่ยม!\n\nโทเทมที่ข้าจะสร้างเป็นมากกว่าเครื่องหมายฐานะในหมู่{class} มันมีพลังยิ่งกว่านั้น ประโยชน์หนึ่งคือใช้เป็นสื่อรวมพลังคาถาที่เชื่อมกับดิน เมื่อเจ้ามีปัญญามากขึ้น พลังของดินก็จะเปิดให้เจ้าใช้มากขึ้น\n\nครูฝึกจะรู้เมื่อเจ้าพร้อมรับความรู้ที่สูงกว่า\n\nแต่ตอนนี้ รับโทเทมดินกับม้วนคัมภีร์สำหรับเรียนความสามารถแรกไปก่อน", variants = { { "85:346363627:1403491895 C 323:686246046:216501294", "ยอดเยี่ยม!\n\nโทเทมที่ข้าจะสร้างเป็นมากกว่าเครื่องหมายฐานะในหมู่{class} มันมีพลังยิ่งกว่านั้น ประโยชน์หนึ่งคือใช้เป็นสื่อรวมพลังคาถาที่เชื่อมกับดิน เมื่อเจ้ามีปัญญามากขึ้น พลังของดินก็จะเปิดให้เจ้าใช้มากขึ้น\n\nครูฝึกจะรู้เมื่อเจ้าพร้อมรับความรู้ที่สูงกว่า\n\nแต่ตอนนี้ รับโทเทมดินนี้ไปก่อน..." } } },
        required = { [6656] = { "12:2047988926:1690463399", "ควอตซ์หยาบ" } },
        steps = { { "12:2047988926:1690463399", "ควอตซ์หยาบ" } },
    },
    [1519] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "74:437465845:1103269690", "นำ Ritual Salve 2 ชุดไปให้ Seer Ravenfeather ใน Camp Narache" },
        description = { "25:1256683703:602694497 C 463:488443749:2088907629", "ถึงเวลาแล้ว {class} น้อย ร่างกายเจ้าเติบโตแข็งแรง จิตวิญญาณอดทนดุจดิน ข้าเห็นว่าเจ้ามีปัญญาอยู่แล้ว\n\nแผ่นดินชี้ทางและพูดกับชนเผ่าเรา วันหนึ่งก็จะพูดกับเจ้า แต่เจ้าต้องผ่านการทดสอบ หากพร้อม เจ้าจะเห็นสิ่งที่มีเพียงพวกเราเท่านั้นที่รู้\n\nไปหา Bristleback Shaman ในหุบทางตะวันออก เก็บยาทาที่ใช้ในพิธีของพวกมัน กลับมาเมื่อมีพอปรุงน้ำยาของเจ้าเองเท่านั้น" },
        progress = { "476:1058042031:120778893", "แผ่นดินอดทนและจะรอจนเจ้าพร้อม เพราะนางรู้ว่าทุกสิ่งย่อมผุกร่อนและเกิดใหม่ นี่คือวัฏจักร ภูเขากลายเป็นทะเลทราย แม่น้ำกลายเป็นหุบผา ดินดื้อดึงและมีปัญญาที่สุดในบรรดาธาตุ\n\nเหนือสิ่งอื่นใด เจ้าต้องเรียนรู้ความอดทนและความทนทาน ดินเรียกหาเพราะรู้สึกว่าเจ้าพร้อม หากสำเร็จ จงถือว่านี่คือการเกิดใหม่ หลังจากนั้นเจ้าจะไม่มีวันหวนกลับสู่ความเขลาได้อีก" },
        completion = { "6:2014770050:1830635039 N 497:16381711:95701543", "ดีมาก {name} การกลับมาครั้งนี้แสดงว่าเจ้าพร้อมสำหรับก้าวต่อไปจริง ๆ\n\nในบรรดาธาตุ ดินเป็นรากฐานของทุกสิ่ง เป็นกำลัง ความทนทาน และความอดทนของเจ้า พระแม่ธรณีจะคุ้มครองก็ต่อเมื่อเจ้าให้ความเคารพอย่างเหมาะสม นางคือรากฐานของชีวิต การสังเกตกฎของนางจะเพิ่มพูนปัญญา อย่าลืมความลับที่นางแบ่งปัน\n\nข้าจะปรุง Sapta ให้ เมื่อรับมัน เส้นทางใหม่จะเปิดออกต่อหน้าเจ้า" },
        required = { [6634] = { "12:1396012313:1386331277", "ยาทาสำหรับพิธี" } },
        steps = { { "12:1396012313:1386331277", "ยาทาสำหรับพิธี" } },
    },
    [1520] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "41:1759423182:29990961", "หา Kodo Rock แล้วดื่ม Earth Sapta" },
        description = { "455:1628194861:1070456770", "Sapta คือเครื่องดื่มที่ผูกจิตวิญญาณของเรากับธาตุ น้ำยาที่ผสานเวททำให้ผู้เปิดใจมองเห็นธาตุอย่างที่ไม่เคยเห็นมาก่อน จิตของเจ้าจะผูกกับธาตุที่ใช้ปรุง Sapta ตลอดไป มีพวกเราเพียงไม่กี่คนรู้เคล็ดลับการปรุง\n\nต้องดื่ม Sapta ณ สถานที่ศักดิ์สิทธิ์เท่านั้น ห้ามที่อื่น\n\nไปหาศาลชาแมนทางตะวันออก แล้วดื่ม Sapta ที่นั่น" },
        completion = { "6:1572241333:73377271 N 494:48796717:699389557", "อา... {name}... แผ่นดินยินดีที่เจ้ามา\n\nเมื่อกายและจิตผูกพันกัน เจ้าจะก้าวต่อไปโดยรู้ว่าภูเขาคือกำลัง ทุ่งราบคือความอดทน และโลกคือแก่นแท้ของเจ้า\n\nเพียงยืนต่อหน้าดินด้วยความถ่อมตน เจ้าก็ผ่านพิธีนี้แล้ว แต่ธาตุอื่นไม่สงบเช่นนี้ อาจปั่นป่วนและมักรุนแรง ทว่านั่นคือธรรมชาติของธาตุ ธรรมชาติสองด้านที่ขัดแย้งกัน เจ้าต้องเรียนรู้ให้ลึกซึ้ง" },
    },
    [1521] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "60:1977801109:1401749785", "นำ Rough Quartz ไปให้ Seer Ravenfeather ใน Camp Narache" },
        description = { "309:2100270473:285496794 N 150:1751221446:451907108", "รับควอตซ์หยาบนี้ไปให้ Seer Ravenfeather เป็นหลักฐานว่าเราพบกัน นางจะสร้างโทเทมให้ โดยใช้ก้อนหินนี้เป็นหัวใจ แม้ดูเล็ก เจ้าจะพบว่าขนาดไม่สำคัญ และสิ่งเล็กที่สุดก็อาจคงอยู่ได้นานกว่าภูเขา\n\nจงอดทน {name} เข้มแข็งและแสวงหาปัญญา นี่คือสิ่งที่ดินขอ สุดท้ายเจ้าจะเป็นหนึ่งเดียวกับแผ่นดิน จงเคารพมันเช่นเดียวกับที่มันเคารพเจ้า" },
        progress = { "11:927657569:725753248 N 363:649412145:1605574824", "สวัสดี {name} เจ้าคงไม่กลับมาหากยังทำงานไม่สำเร็จ ข้าขอเป็นคนแรกที่ต้อนรับอย่างเต็มตัวสู่เส้นทางแรกจากสี่เส้น ซึ่งจะกำหนดการเดินทางของเจ้าตลอดไป\n\nหากมีหินที่ดินมอบให้ ข้าจะมอบโทเทมตามที่มันสัญญา หากไม่มี ข้าก็สงสารเจ้า การอุทิศตนให้ธาตุอย่างเต็มที่เป็นสิ่งน่าภาคภูมิใจยิ่ง" },
        completion = { "454:1725861456:848104823", "ยอดเยี่ยม\n\nโทเทมที่ข้าจะสร้างเป็นมากกว่าสัญลักษณ์ มันมีพลังยิ่งกว่านั้น ประโยชน์หนึ่งคือใช้รวมพลังคาถาที่เชื่อมกับดิน เมื่อเจ้ามีปัญญามากขึ้น พลังของดินก็จะเปิดให้ใช้มากขึ้น ครูฝึกทั่ว Kalimdor จะรู้ว่าเมื่อใดเจ้าพร้อมรับความรู้สูงกว่า และจะบอกเมื่อเจ้าไปพบ\n\nแต่ตอนนี้ รับโทเทมดินนี้ไปก่อน..." },
        required = { [6656] = { "12:2047988926:1690463399", "ควอตซ์หยาบ" } },
        steps = { { "12:2047988926:1690463399", "ควอตซ์หยาบ" } },
    },
    [1528] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "36:750142939:1970683728", "ไปหา Islen Waterseer ใน Barrens" },
        description = { "429:610836926:441026491", "น้ำอยู่ในอนาคตของเจ้า สหาย ข้าเห็นว่าเจ้าเข้มแข็งในวิถีไฟแล้ว คิดว่าพร้อมไปคุยกับ Islen\n\nนางอยู่ริมชายฝั่ง Barrens มุ่งใต้ตาม Southfury River ก็ไม่พลาด มองหาฉลามตัวใหญ่! นางเชี่ยวชาญวิถีธาตุและสอนวิถีน้ำให้ได้... หากเจ้าคิดว่าพร้อม\n\nหาไม่ยาก แต่อย่าลงใต้ไกลเกิน นางอยู่เลย Ratchet ไปเพียงนิดเดียว" },
        completion = { "336:558126454:994749019", "สายลมรุดจากขอบฟ้ามาหาเจ้า ดินใต้เท้ามั่นคง และไฟได้อบอุ่นจิตใจแล้ว ข้าว่าถึงเวลาเรียนรู้ความบริสุทธิ์ของน้ำ\n\nเส้นทางพาเจ้ามาถึงนี่ จิตวิญญาณจะให้กำลังก้าวต่อไปได้ไกลกว่าเดิม แต่ก้าวแรกนั้น เจ้าต้องก้าวเอง" },
    },
    [1529] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "36:750142939:1970683728", "ไปหา Islen Waterseer ใน Barrens" },
        description = { "45:400966455:117256069 N 336:1658958713:1540463413 N 1:46:46", "นานแล้วนับจากบททดสอบครั้งก่อน {name} เจ้าศึกษาอย่างอดทน แต่ถึงเวลาเรียนรู้เพิ่ม ถึงเวลาเรียนรู้ความบริสุทธิ์ของน้ำ\n\nไปหา Islen Waterseer ใน Barrens นางอยู่ริมฝั่งตะวันออก ทางใต้ของ Southfury River และ Ratchet ที่กระท่อมตกปลา ขอให้โชคดี {name}" },
        completion = { "336:558126454:994749019", "สายลมรุดจากขอบฟ้ามาหาเจ้า ดินใต้เท้ามั่นคง และไฟได้อบอุ่นจิตใจแล้ว ข้าว่าถึงเวลาเรียนรู้ความบริสุทธิ์ของน้ำ\n\nเส้นทางพาเจ้ามาถึงนี่ จิตวิญญาณจะให้กำลังก้าวต่อไปได้ไกลกว่าเดิม แต่ก้าวแรกนั้น เจ้าต้องก้าวเอง" },
    },
    [1530] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "31:257334455:303910404", "ไปหา Brine ใน Southern Barrens" },
        description = { "483:1539018193:374268149", "หากมีบทเรียนหนึ่งที่ต้องรู้เกี่ยวกับน้ำ ก็คือ น้ำหมายถึงการเกิดใหม่\n\nพลังของมันไหล กัดเซาะ และชำระทุกสิ่ง ความสามารถรักษาและฟื้นฟูของมันไม่มีสิ่งใดเทียบ แต่เฉพาะเมื่อบริสุทธิ์เท่านั้น\n\nเมื่อเข้าใจว่าน้ำปนเปื้อนทำลายทุกสิ่งที่สัมผัสได้ เจ้าจะเห็นว่ามันสำคัญเพียงใด\n\nหากต้องการ Water Sapta ไปหา Brine ลึกเข้าไปใน Southern Barrens บ้านของนางถูกควิลบอร์แถวนั้นรังควานไม่หยุด" },
        completion = { "306:1859734316:1896985924 R 163:2112914989:134691902", "ว่าอย่างไร?\n\nอืม ข้ารู้สึกว่ารู้แล้วว่าเจ้าจะถามอะไร อะไรทำให้คนมาอยู่ส่วนลึกที่สุดของ Barrens มีควิลบอร์คุกคามรอบตัวโดยไม่มีการป้องกัน? เราต่างมีเหตุผลรองรับการกระทำของตน คำถามจริงคือ อะไรพา{race}ต้อยต่ำมาถึงส่วนลึกของ Barrens เพื่อคุยกับหญิงที่เห็นชัดว่าไม่ห่วงความปลอดภัยของตัวเอง?\n\nข้าพนันว่าเราทั้งคู่รู้คำตอบ", variants = { { "306:814624818:435368859 R 163:2112914989:134691902", "ว่าอย่างไร?\n\nอืม ข้าพอเดาได้ว่าเจ้าจะถามอะไร อะไรดลใจให้คนมาอยู่ลึกถึงเพียงนี้ใน Barrens ทั้งที่มีควิลบอร์ล้อมรอบและไม่มีใครคุ้มกัน? คนเราต่างมีเหตุผลที่ทำอย่างที่ทำ แต่คำถามจริง ๆ คือ อะไรพา{race}ต้อยต่ำอย่างเจ้ามาถึงส่วนลึกของ Barrens เพื่อคุยกับหญิงที่เห็นได้ชัดว่าไม่ห่วงความปลอดภัยของตัวเอง?\n\nข้าพนันว่าเราทั้งคู่รู้คำตอบ" } } },
    },
    [1531] = { -- Call of Air
        title = { "11:1660965280:891392614", "เสียงเรียกแห่งลม" },
        objective = { "41:1471038336:1808319472", "ไปหา Prate Cloudseer ใน Thousand Needles" },
        description = { "440:108317601:1759608462", "เจ้าก้าวหน้าแล้ว สหาย พร้อมพิสูจน์ว่าคู่ควรกับโทเทมลม แต่ก่อนอื่นต้องหา Prate Cloudseer ใน Thousand Needles หากให้เกียรติมากพอ นางยินดีบอกวิธีได้โทเทม\n\nมุ่งใต้ผ่าน Barrens พอถึง Thousand Needles ให้ไปตะวันออก จะพบนางซ่อนในโพรงกับแฟน ฮ่า ๆ อย่าบอกว่าข้าแซวนางนะ นางคงไม่ชอบใจ" },
        completion = { "174:1989815040:1883468629", "ตอนนี้ข้าจะมอบสิ่งที่ใช้รวมพลังคาถาและเรียกวิญญาณลม รับโทเทมนี้ไป เมื่อพร้อมก็มาฝึกกับข้าต่อ" },
    },
    [1532] = { -- Call of Air
        title = { "11:1660965280:891392614", "เสียงเรียกแห่งลม" },
        objective = { "41:1471038336:1808319472", "ไปหา Prate Cloudseer ใน Thousand Needles" },
        description = { { "483:2009411119:516847703", "482:56948082:559972071" }, "สายลม Kalimdor รุดมาต้อนรับ เจ้าเข้าร่วมกลุ่มพี่น้องผู้ทรงพลังที่สุดของเราแล้ว ข้าภูมิใจที่เจ้ามาไกลถึงเพียงนี้และมีอนาคตสดใส\n\nธาตุลมควบคุมยาก แต่ข้าเชื่อว่าฝีมือเจ้าจะก้าวข้ามทุกอุปสรรค\n\nไปใต้สุดของ Barrens แล้วเข้า Thousand Needles ทางตะวันออกไกลจะพบ Prate Cloudseer นางจะสอนเพิ่มเติม" },
        completion = { "174:1989815040:1883468629", "ตอนนี้ข้าจะมอบสิ่งที่ใช้รวมพลังคาถาและเรียกวิญญาณลม รับโทเทมนี้ไป เมื่อพร้อมก็มาฝึกกับข้าต่อ" },
    },
    [1534] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "103:1458235798:954053380", "เติม Empty Blue Waterskin ที่ Ruins of Stardust ใน Ashenvale แล้วกลับไปหา Brine ใน Barrens" },
        description = { "483:1384811076:1300554446", "นำถุงน้ำนี้เข้าไปลึกในป่าเขียวชอุ่มที่ไนต์เอลฟ์เรียกว่า Ashenvale อยู่เหนือ Barrens ไปไกล\n\nเข้าป่าแล้วมุ่งตะวันตก ตามแนวเขาที่แบ่ง Stonetalon กับ Ashenvale เลย Lake Mystral ไป จะพบสถานที่ศักดิ์สิทธิ์ Ruins of Stardust กลางทะเลสาบมีน้ำพุเล็ก ๆ\n\nนำตัวอย่างน้ำพุนั้นมา เป็นส่วนประกอบสุดท้ายก่อนข้าส่งเจ้ากลับไปหา Islen" },
        progress = { "27:1449404961:602476901 N 190:1339997081:1437470634", "ได้น้ำหรือยัง {name}? มีเรื่องเล่าว่าซากโบราณได้รับการคุ้มครองจากสัตว์ธรรมชาติตัวใหญ่ที่ไม่ต้อนรับผู้มาเยือน แต่อาจเป็นนิทานไว้ขู่ศัตรูไนต์เอลฟ์\n\nอย่างไรก็ระวังตัวด้วย" },
        completion = { "11:2138623245:698779024 N 215:1589937369:1855990928 N 13:26814143:1408778288 C 72:1657055236:48516669", "ยอดเยี่ยม {name} เมื่อมีตัวอย่างทั้งสาม ข้าก็สร้างน้ำบริสุทธิ์ยิ่งกว่าที่สิ่งมีชีวิตใดจะหาได้ให้เจ้าได้แล้ว มันจะใช้ในขั้นถัดไปของพิธีผ่านวัย\n\nข้ายินดีที่มีเจ้าเป็นพวกเดียวกัน {name} เจ้าทำให้{class}ทุกคนภูมิใจ ข้ารอคอยข่าววีรกรรมของเจ้าในอนาคต" },
        required = { [7770] = { "21:1379996730:1232935133", "ถุงน้ำสีน้ำเงินที่เติมแล้ว" } },
        steps = { { "21:1379996730:1232935133", "ถุงน้ำสีน้ำเงินที่เติมแล้ว" } },
    },
    [1535] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "106:917432131:1521509081", "เติม Empty Brown Waterskin ที่แอ่งน้ำด้านล่างกระท่อม Brine แล้วนำกลับไปให้นางใน Barrens" },
        description = { "491:90359274:354730349", "หากจะเข้าใจและรับ Sapta จากข้า เจ้าต้องแสวงหาน้ำที่บริสุทธิ์ที่สุด ขณะเก็บตัวอย่าง จงสังเกตรอบตัว ดูสัตว์ที่พึ่งพาและปกป้องน้ำ ดูผลต่อป่าและทะเลทราย เห็นว่าสิ่งหล่อเลี้ยงชีวิตนี้กลับผลักดันให้สัตว์พรากชีวิตกันได้อย่างไร\n\nเริ่มจากงานง่าย ๆ ใต้กระท่อมข้ามีสระของเหลวล้ำค่านี้ เติมลงถุงแล้วกลับมา" },
        progress = { "344:21141154:1347982980", "ข้าใกล้เตรียมพร้อมส่งเจ้าไปทำงานอื่นแล้ว เติมถุงน้ำหรือยัง?\n\nข้ารู้ว่าควิลบอร์หวงแหนเพียงใด แม้แหล่งน้ำเล็กเท่านี้ก็เป็นขุมทรัพย์มหาศาล พวกมันจัดงานเลี้ยงใหญ่แม้มีฝนเพียงเล็กน้อยใน Barrens น้ำศักดิ์สิทธิ์สำหรับพวกมันเพราะหายาก เข้าใจไหม?" },
        completion = { "420:549124154:1787251955", "ข้าคิดไว้ว่าคงนองเลือดหากเจ้าพยายามตักน้ำ น่าเสียดายที่ควิลบอร์ไม่เข้าใจว่าทุกชีวิตผูกพันกัน ความโลภมีแต่ต่อความเจ็บปวดและความทุกข์ให้เผ่าพันธุ์ตน หากวางความแตกต่างและรวมเหล่าเผ่าเข้าด้วยกัน พวกมันจะทำอะไรได้มากเพียงใด\n\nน่าเสียดายจริง แต่คงเป็นผลดีต่อเผ่าอื่นใน Barrens" },
        required = { [7769] = { "22:353225670:1151953800", "ถุงน้ำหนังสีน้ำตาลที่เติมแล้ว" } },
        objectiveLabels = {
            item = { ["Filled Brown Waterskin"] = "ถุงน้ำหนังสีน้ำตาลที่เติมแล้ว" },
        },
    },
    [1536] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "91:1483692464:498002573", "เติม Empty Red Waterskin ที่บ่อน้ำใน Tarren Mill แล้วกลับไปหา Brine ใน Barrens" },
        description = { "496:661765554:1316204042", "นานมาแล้ว ข้าตามสหายไป Hillsbrad Foothills เราป้องกันตัวจากมนุษย์ดื้อดึงที่อยู่แถวนั้น แล้วไปถึงเมืองเล็กที่ Forsaken ยึดไว้ นั่นคือ Tarren Mill\n\nข้าพบสิ่งแปลกประหลาด กลางเมืองมีบ่อน้ำพุจืดเล็ก ๆ ไม่รู้ว่าชาวเมืองผู้ติดโรคตระหนักถึงค่าของมันหรือไม่ เป็นเศษเสี้ยวศักดิ์สิทธิ์ท่ามกลางทะเลอัปมงคล\n\nนำตัวอย่างน้ำใส่ถุงนี้กลับมา" },
        progress = { "93:1755922376:702938314 N 361:435967004:793131865", "บ่อน้ำที่ยังบริสุทธิ์กลางเมืองทำให้ข้านึกถึงเรื่องเล่าสมัยเด็ก {name} แม้ยามเจ็บปวดและโศกเศร้าหนัก ก็ยังพบประกายหวัง สัญลักษณ์เล็ก ๆ ให้รวมใจ ชาวออร์คมอง Thrall เช่นนี้ เขารอดจากอุปสรรคมหาศาลและลุกขึ้นนำผู้คนด้วยกำลังและแบบอย่างของตน\n\nข้าไม่แน่ใจว่ามีออร์คใดทุกข์ทรมานเท่าเขา แต่ก็ไม่แน่ใจว่ามีออร์คใดแข็งแกร่งเท่าเขาเช่นกัน" },
        completion = { "14:328000485:1627340455 N 199:1835107382:1538096579", "ดีมาก {name} เจ้าทุ่มเทต่องานตรงหน้าและมีความสามารถค้นหาสิ่งจำเป็น\n\nข้าต้องการอีกเพียงตัวอย่างเดียว ก็จะสร้างวัตถุดิบสำหรับ Sapta ได้ Islen คงยินดีเช่นกัน" },
        required = { [7771] = { "20:2017235666:1065053736", "ถุงน้ำสีแดงที่เติมแล้ว" } },
        steps = { { "20:2017235666:1065053736", "ถุงน้ำสีแดงที่เติมแล้ว" } },
    },
    [2985] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "36:750142939:1970683728", "ไปหา Islen Waterseer ใน Barrens" },
        description = { "35:1151800179:1639418907 N 323:621394019:69268493 N 1:46:46", "เจ้าดูพร้อมรับบททดสอบถัดไปแล้ว {name} เจ้าเรียนอย่างอดทน แต่ถึงเวลาเรียนรู้เพิ่ม ถึงเวลาเรียนรู้ความบริสุทธิ์ของน้ำ\n\nไปหา Islen Waterseer ใน Barrens นางอยู่ริมฝั่งตะวันออก ทางใต้ของ Southfury River และ Ratchet ที่กระท่อมตกปลา ขอให้โชคดี {name}" },
        completion = { "336:558126454:994749019", "สายลมรุดจากขอบฟ้ามาหาเจ้า ดินใต้เท้ามั่นคง และไฟได้อบอุ่นจิตใจแล้ว ข้าว่าถึงเวลาเรียนรู้ความบริสุทธิ์ของน้ำ\n\nเส้นทางพาเจ้ามาถึงนี่ จิตวิญญาณจะให้กำลังก้าวต่อไปได้ไกลกว่าเดิม แต่ก้าวแรกนั้น เจ้าต้องก้าวเอง" },
    },
    [2986] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "36:750142939:1970683728", "ไปหา Islen Waterseer ใน Barrens" },
        description = { "45:400966455:117256069 N 336:1658958713:1540463413 N 1:46:46", "นานแล้วนับจากบททดสอบครั้งก่อน {name} เจ้าศึกษาอย่างอดทน แต่ถึงเวลาเรียนรู้เพิ่ม ถึงเวลาเรียนรู้ความบริสุทธิ์ของน้ำ\n\nไปหา Islen Waterseer ใน Barrens นางอยู่ริมฝั่งตะวันออก ทางใต้ของ Southfury River และ Ratchet ที่กระท่อมตกปลา ขอให้โชคดี {name}" },
        completion = { "336:558126454:994749019", "สายลมรุดจากขอบฟ้ามาหาเจ้า ดินใต้เท้ามั่นคง และไฟได้อบอุ่นจิตใจแล้ว ข้าว่าถึงเวลาเรียนรู้ความบริสุทธิ์ของน้ำ\n\nเส้นทางพาเจ้ามาถึงนี่ จิตวิญญาณจะให้กำลังก้าวต่อไปได้ไกลกว่าเดิม แต่ก้าวแรกนั้น เจ้าต้องก้าวเอง" },
    },
    [3084] = { -- Rune-Inscribed Tablet
        title = { "21:1264577027:1548020645", "แผ่นจารึกอักษรรูน" },
        objective = { "41:606987699:1331954927", "คุยกับ Shikrik ใน Valley of Trials" },
        description = { "47:542172104:1998871674 N 140:1809256344:1471513406", "อา ระหว่างเจ้าไม่อยู่มีแผ่นจารึกส่งมาถึง {name}\n\nมีเวลาก็อ่านเสีย ถ้าข้าจำไม่ผิด มาจากครูฝึกชาแมน Shikrik นางอยากพูดด้วยเมื่อเจ้าพร้อม" },
        progress = { "13:1745531415:2053662583 N 246:1166220981:708093624", "อา ยินดีต้อนรับ {name} ข้ายินดีที่เจ้ามาถึง แต่ละวันยาวนานและวุ่นวายเพราะมีศิษย์มาก ทว่าการมาของคนเช่นเจ้าทำให้ข้ารู้สึกประสบความสำเร็จยิ่งนัก ข้าจำวันที่เคยเรียนกับชาแมนคนหนึ่งของพวกเจ้าได้" },
        completion = { "448:66173250:478715959", "เจ้าคงรู้แล้วว่าธาตุมอบพลังให้เรา ไฟ ดิน น้ำ และลม คือเครื่องมือของเรา\n\nกำลังของเรามาจากวิญญาณบรรพชน เราคือผู้นำผู้คน เช่นเดียวกับ Thrall ต่อ Horde เราจะเป็นเช่นนั้นต่อหมู่บ้านและเมืองที่ไปเยือน พวกเขาจะมาขอปัญญาและการคุ้มครอง เจ้าต้องฝึกบ่อยเพื่อเตรียมพร้อม เมื่อรู้สึกว่ามีพลังเพิ่มขึ้น มาหาข้า แล้วข้าจะสอนเท่าที่ทำได้" },
        required = { [9562] = { "21:1264577027:1548020645", "แผ่นจารึกสลักรูน" } },
        steps = { { "21:1264577027:1548020645", "แผ่นจารึกสลักรูน" } },
    },
    [3089] = { -- Rune-Inscribed Parchment
        title = { "24:2005379436:1921272263", "แผ่นหนังจารึกอักษรรูน" },
        objective = { "79:345792588:15003508", "อ่าน Rune-Inscribed Parchment แล้วคุยกับ Shikrik ใน Valley of Trials" },
        description = { "50:504738005:547472890 N 140:1809256344:1471513406", "อา ระหว่างเจ้าไม่อยู่มีแผ่นหนังส่งมาถึง {name}\n\nมีเวลาก็อ่านเสีย ถ้าข้าจำไม่ผิด มาจากครูฝึกชาแมน Shikrik นางอยากพูดด้วยเมื่อเจ้าพร้อม" },
        progress = { "258:353102439:1067838399", "เจ้ามาแล้ว ข้าเริ่มสงสัยว่าจะปรากฏตัวเมื่อใด ส่งแผ่นหนังไปพักหนึ่งแล้ว ไม่แน่ใจว่าส่งถึงหรือยัง\n\nแต่คุยเล่นพอแล้ว... เจ้ามาเพราะถูกเลือก ถูกเลือกให้นำชีวิตทางจิตวิญญาณของผู้คนเรา" },
        completion = { "402:267065701:1015755043", "เจ้าจะเป็นสื่อให้บรรพชนติดต่อ จะมีพลังธาตุพร้อมรับคำเรียก การฉีกศัตรูจะง่ายดาย การรักษาพวกพ้องจะง่ายดุจหายใจ จงจำไว้เมื่อเผชิญบททดสอบใหม่ และกลับมาได้บ่อยตามต้องการ ข้าจะอยู่ที่นี่ สอนคาถาใหม่และชี้ทางที่ถูกเมื่อเจ้าพร้อม" },
        required = { [9568] = { "24:2005379436:1921272263", "แผ่นหนังจารึกรูน" } },
        steps = { { "24:2005379436:1921272263", "แผ่นหนังจารึกรูน" } },
    },
    [3093] = { -- Rune-Inscribed Note
        title = { "19:922333006:1314427378", "สารจารึกอักษรรูน" },
        objective = { "76:133458482:1665150242", "อ่าน Rune-Inscribed Note แล้วคุยกับ Meela Dawnstrider ใน Camp Narache" },
        description = { "51:1119716052:1206024959 N 128:1203070977:1963275333", "เมื่อครู่มีผู้ส่งสารตามหาเจ้า {name} ข้าเชื่อว่าครูฝึกชาแมน Meela ส่งนางมา หากสารนี้มาจาก Meela ก็อย่ารอช้าที่จะอ่าน" },
        progress = { "296:1162513999:1136452107", "รวดเร็วดุจน้ำจากฟ้า เจ้าก็มายืนต่อหน้าแล้ว ข้าพอใจในความรีบเร่ง แสดงว่าเจ้ารู้ความสำคัญของการพบและการอยู่ที่นี่ ข้าไม่ใช่ผู้นำ แต่เข้าใจธาตุและพูดกับวิญญาณของผู้คนเราได้ ข้าจะสอนให้เจ้าทำเช่นเดียวกัน" },
        completion = { "211:35208411:232628841 N 61:804567525:2053477097", "เราจะพบกันอีกหลายครั้งในวันข้างหน้า หวังว่าทุกครั้งที่จากไป เจ้าจะแข็งแกร่งขึ้นอีกนิด... พร้อมขึ้นอีกหน่อย จิตของเจ้าจะสว่างร้อนดุจเปลวไฟนิรันดร์\n\nไปเถิด {name} ไปทดสอบตนเอง ข้าจะอยู่ที่นี่เมื่อเจ้าต้องการ" },
        required = { [9552] = { "19:922333006:1314427378", "บันทึกจารึกรูน" } },
        steps = { { "19:922333006:1314427378", "บันทึกจารึกรูน" } },
    },
    [7667] = { -- Material Assistance
        title = { "19:314173589:258658095", "ช่วยเหลือด้านวัสดุ" },
        objective = { "146:325120882:417669436", "หากสนใจช่วย Sagorne Crestrider ใน Valley of Wisdom แห่ง Orgrimmar ให้นำ Azerothian Diamond และ Pristine Black Diamond ไปให้เขา" },
        description = { "N 483:253491218:1926381257", "{name} มีเรื่องเร่งด่วนที่หวังให้เจ้าช่วย... ทั้งด้านวัตถุและจิตวิญญาณ ให้ข้าอธิบาย\n\nลึกใน Scholomance แห่ง Lordaeron มีห้องชื่อ Great Ossuary ข้าต้องสร้างอุปกรณ์ให้เสร็จเพื่อเจาะเงามืดในห้องน่าสยองนั้น ต้องใช้เพชรสองชนิด Azerothian กับ Pristine Black ข้ารู้ว่าไม่ใช่ของเล็กน้อย แต่ข้าไม่มีทรัพยากรเอง\n\nเจ้าหามาให้อย่างละเม็ดได้หรือไม่?" },
        progress = { "174:1009297119:1776750861", "ข้ากระดากใจที่ขอความช่วยเหลือด้านวัสดุ แต่ Divination Scryer ที่หวังสร้างให้เสร็จต้องใช้เพชรอย่างละเม็ด หากช่วยไม่ได้ ข้าก็เข้าใจ" },
        completion = { "30:1864871228:2067664195 N 342:963229723:1545416243", "น้ำใจเจ้าไม่มีผู้ใดเทียบ {name} ขอบคุณในความเมตตา\n\nตอนนี้ข้าสร้าง Divination Scryer ให้เสร็จได้แล้ว และน่าจะทำเพิ่มได้โดยไม่ต้องใช้เพชรอีก... เจ้าอาจสนใจช่วยข้าใช้มัน? ข้ารับรองว่าสำคัญยิ่ง หากไม่จัดการ อาจเป็นหายนะเต็มรูปแบบต่ออาณาจักรวิญญาณ!" },
        required = { [12800] = { "18:1398536143:412119698", "เพชรแห่ง Azeroth" }, [18335] = { "22:140138788:1102101996", "เพชรดำไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Azerothian Diamond"] = "เพชรแห่ง Azeroth", ["Pristine Black Diamond"] = "เพชรดำไร้ตำหนิ" },
        },
    },
    [7668] = { -- The Darkreaver Menace
        title = { "21:664490122:97049798", "ภัยร้าย Darkreaver" },
        objective = { "83:1234835644:1429704874", "นำ Darkreaver's Head ไปให้ Sagorne Creststrider ใน Valley of Wisdom แห่ง Orgrimmar", variants = { { "303:191942739:474814183", "ใช้ Divination Scryer ใจกลางชั้นใต้ดินของ Great Ossuary ใน Scholomance เพื่อเรียกเหล่าวิญญาณที่เจ้าต้องต่อสู้ออกมา เมื่อเอาชนะเหล่าวิญญาณได้ Death Knight Darkreaver จะปรากฏตัว จงปราบเขา\n\nนำ Darkreaver's Head ไปให้ Sagorne Creststrider ใน Valley of Wisdom แห่ง Orgrimmar" } } },
        description = { "392:32000152:147379226 N 86:1234649466:1199290735", "Death Knight Darkreaver ครอง Great Ossuary ใน Scholomance มันขู่ว่าจะบิดอาณาจักรวิญญาณให้รับใช้ตน ต้องหยุดมัน! นี่คือหน้าที่ของเครื่องพยากรณ์ที่เจ้าช่วยสร้าง\n\nใช้ Divination Scryer กลางห้องใต้ดิน Great Ossuary เพื่อเรียกสมุนวิญญาณของ Darkreaver ปราบวิญญาณแล้วเดธไนต์จะปรากฏ {name} นำหัวมันมา! มีเพียงความตายของมันจะแก้ความเสียหายต่ออาณาจักรวิญญาณได้!" },
        progress = { "18:1969305489:1635869431 N 67:1783637046:571217237", "เวลาเป็นสิ่งสำคัญ {name} เจ้าหยุดภัยจาก Death Knight Darkreaver สำเร็จหรือยัง?" },
        completion = { "28:1530693717:2033762498 N 208:717236739:1061445714 C 147:1621906542:17695703", "ชัยชนะนี้ควรค่าแก่การชื่นชม {name}! ความตายของ Darkreaver น่าจะฟื้นพันธะเปราะบางที่ยึดอาณาจักรวิญญาณไว้\n\nเจ้าทำเกินสิ่งที่ขอมาก ทั้งที่ไม่รู้ว่าจะมีรางวัลหรือสิ่งตอบแทน สหายเอ๋ย เจ้าคือ{class}ที่มีคุณค่าอย่างแท้จริง\n\nข้ารู้ว่าการรักษาอาณาจักรวิญญาณน่าจะเป็นคำขอบคุณเพียงพอแล้ว แต่โปรดรับของขวัญเล็กน้อยนี้พร้อมคำขอบคุณจากข้า" },
    },
    [8258] = { -- The Darkreaver Menace
        title = { "21:664490122:97049798", "ภัยร้าย Darkreaver" },
        objective = { "303:191942739:474814183", "ใช้ Divination Scryer กลางห้องใต้ดิน Great Ossuary ใน Scholomance เพื่อเรียกวิญญาณมาต่อสู้ ปราบพวกมันแล้ว Death Knight Darkreaver จะปรากฏ จงปราบเขา\n\nนำ Darkreaver's Head ไปให้ Sagorne Creststrider ใน Valley of Wisdom แห่ง Orgrimmar" },
        description = { "392:32000152:147379226 N 86:1109971076:1639479110", "Death Knight Darkreaver ครอง Great Ossuary ใน Scholomance มันขู่ว่าจะบิดอาณาจักรวิญญาณให้รับใช้ตน ต้องหยุดมัน! นี่คือหน้าที่ของเครื่องพยากรณ์ที่เจ้าช่วยสร้าง\n\nใช้ Divination Scryer กลางห้องใต้ดิน Great Ossuary เพื่อเรียกสมุนวิญญาณของ Darkreaver ปราบวิญญาณแล้วเดธไนต์จะปรากฏ {name} นำหัวมันมา! มีเพียงความตายของมันจะแก้ความเสียหายต่ออาณาจักรวิญญาณได้!" },
        progress = { "18:1969305489:1635869431 N 67:1783637046:571217237", "เวลาเป็นสิ่งสำคัญ {name} เจ้าหยุดภัยจาก Death Knight Darkreaver สำเร็จหรือยัง?" },
        completion = { "28:1530693717:2033762498 N 361:39754530:768585811", "ชัยชนะนี้ควรค่าแก่การชื่นชม {name}! ความตายของ Darkreaver น่าจะฟื้นพันธะเปราะบางที่ยึดอาณาจักรวิญญาณไว้\n\nเจ้าทำเกินสิ่งที่ขอมาก ทั้งที่ไม่รู้ว่าจะมีรางวัลหรือสิ่งตอบแทน สหายเอ๋ย เจ้าคือชาแมนที่มีคุณค่าอย่างแท้จริง\n\nข้ารู้ว่าการรักษาอาณาจักรวิญญาณน่าจะเป็นคำขอบคุณเพียงพอแล้ว แต่โปรดรับของขวัญเล็กน้อยนี้พร้อมคำขอบคุณจากข้า" },
        required = { [18880] = { "17:544043257:381451187", "ศีรษะของดาร์กรีฟเวอร์" } },
        objectiveLabels = {
            item = { ["Darkreaver's Head"] = "ศีรษะของดาร์กรีฟเวอร์" },
        },
    },
    [8410] = { -- Elemental Mastery
        title = { "17:922249953:35162934", "ความชำนาญแห่งธาตุ" },
        objective = { "76:402380344:191631832", "รวบรวมตัวอย่างธาตุลม ไฟ ดิน และน้ำให้ Bath'rah the Windwatcher" },
        description = { "288:1999744756:293637377", "Bath'rah the Windwatcher ส่งสารเรียกหาชาแมนผู้มีปัญญาเช่นเจ้า เขาขอให้นำตัวอย่างธาตุแต่ละชนิดไปแสดงว่าพร้อม\n\nไปแม่น้ำทางตะวันออกของ Tarren Mill ตามน้ำขึ้นเหนือจนพบซากโบราณที่ Bath'rah อาศัยอยู่" },
        progress = { "21:270315686:1480216727 C 1:63:63", "มีอะไรมาให้ข้า {class}?" },
        completion = { "34:2083580035:1420068513", "เยี่ยม สหาย ทีนี้ค่อยน่าคุยหน่อย" },
        required = { [7069] = { "13:595551382:218416816", "แก่นธาตุลม" }, [7068] = { "14:670239303:706556275", "แก่นธาตุไฟ" }, [7067] = { "15:249513219:2052077027", "แก่นธาตุดิน" }, [7070] = { "15:1464697398:910657085", "แก่นธาตุน้ำ" } },
        objectiveLabels = {
            item = { ["Elemental Air"] = "แก่นธาตุลม", ["Elemental Fire"] = "แก่นธาตุไฟ", ["Elemental Earth"] = "แก่นธาตุดิน", ["Elemental Water"] = "แก่นธาตุน้ำ" },
        },
    },
    [8411] = { -- Mastering the Elements
        title = { "22:1574818453:1835803926", "เรียนรู้ธาตุให้เชี่ยวชาญ" },
        objective = { "74:415812610:1368703598", "นำธาตุดิน ลม ไฟ และน้ำไปให้ Bath'rah the Windwatcher" },
        description = { "67:1678310744:2045990489", "ยินดีต้อนรับ สหาย เอาธาตุมาให้ก่อน แล้วค่อยคุยกัน" },
