    [8412] = { -- Spirit Totem
        title = { "12:1059627746:1708254923", "โทเทมวิญญาณ" },
        objective = { "66:2014266485:1887321662", "นำชิ้นส่วนสำหรับ Spirit Totem ไปให้ Bath'rah the Windwatcher" },
        description = { "388:1826898472:982969793", "วิญญาณธาตุที่นี่ไม่ชอบข้าอีกแล้ว\n\nเจ้ารู้เรื่องโทเทมดีกว่าใคร ข้าต้องการ Spirit Totem คุ้มครอง เรามีธาตุแล้ว แต่ต้องการสิ่งที่เป็นธรรมชาติมากขึ้น ดั้งเดิมยิ่งขึ้น\n\nใน Western Plaguelands เจ้าฆ่าหมีเอากรงเล็บและแมงมุมเอาตาได้ นกกินซากกินทุกอย่าง จึงอาจมีของอย่างใดอย่างหนึ่งเช่นกัน" },
        progress = { "93:1117011510:860884765", "วิญญาณรู้ว่าเราทำอะไรอยู่ และพยายามฆ่าข้า! หวังว่าเจ้ามีชิ้นส่วนแล้ว" },
        completion = { "32:127210648:1521511248", "เยี่ยม สหาย! ลองกันเลย..." },
        required = { [20610] = { "20:340236555:2097815894", "ดวงตาแมงมุมแดงก่ำ" }, [20611] = { "16:707888569:1965470896", "กรงเล็บดำหนา" } },
        steps = { { "20:340236555:2097815894", "ดวงตาแมงมุมแดงก่ำ" }, { "16:707888569:1965470896", "กรงเล็บดำหนา" } },
    },
    [8413] = { -- Da Voodoo
        title = { "9:1502975821:1853034900", "มนตร์วูดู" },
        objective = { "54:1958983516:1488961984", "นำ Voodoo Feathers ไปให้ Bath'rah the Windwatcher" },
        description = { "284:269303375:1014646653", "Spirit Totem อย่างเดียวยังไม่พอ ต้องมีเวทวูดูให้มันทำงานได้เหมาะเจาะ\n\nโทรลล์ใน Sunken Temple มีขนนกเปี่ยมเวทวูดู ไปฆ่า Gasher, Mijan, Zolo, Hukku, Zul'lor และ Loro แล้วเราจะมีเวทพอสำหรับโทเทมวิญญาณแท้จริง" },
        progress = { "26:359003279:1863726195", "ขนนกอยู่ไหน สหาย?" },
        completion = { "173:918728210:1643587064", "ได้เวลาที่โทรลล์คนนี้จะนอนเต็มคืนเสียที! Spirit Totem จะเฝ้าคุ้มครองข้า\n\nข้าสะสมของมานาน เจ้าคงอยากได้อะไรตอบแทนความลำบากบ้าง?" },
        required = { [20606] = { "20:116773895:110391659", "ขนนกวูดูสีอำพัน" }, [20607] = { "19:47936181:1879616036", "ขนนกวูดูสีน้ำเงิน" }, [20608] = { "20:1196264854:1089628285", "ขนนกวูดูสีเขียว" } },
        objectiveLabels = {
            item = { ["Amber Voodoo Feather"] = "ขนนกวูดูสีอำพัน", ["Blue Voodoo Feather"] = "ขนนกวูดูสีน้ำเงิน", ["Green Voodoo Feather"] = "ขนนกวูดูสีเขียว" },
        },
    },
    [79358] = { -- Storm, Earth, and Fire
        title = { "22:940476950:472117575", "พายุ ดิน และไฟ" },
        objective = { "147:819497814:182245966", "รวบรวม Twisted Fire Totems 5 ชิ้น, Twisted Earth Totems 5 ชิ้น, Twisted Air Totems 5 ชิ้น และ Twisted Water Totems 5 ชิ้นให้ Veyric Thunderhame ใน Arathi Highlands", amount = { "8:1089852795:1107240600 W1 22:1449430616:1721010504 W2 23:67107465:718983881 W3 25:1755691611:2042489244 W4 65:1240237911:1674168081", "รวบรวม Twisted Fire Totems {world1} ชิ้น, Twisted Earth Totems {world2} ชิ้น, Twisted Air Totems {world3} ชิ้น และ Twisted Water Totems {world4} ชิ้นให้ Veyric Thunderhame ใน Arathi Highlands" } },
        description = { "48:949997329:1086141818 N 447:816299801:459823517", "การท่วม Thousand Needles ไม่ใช่เรื่องเล็ก {name} ถ้าข้าไม่รู้สึกถึงความโกรธของธาตุเอง คงไม่เชื่อ แต่มันเกิดขึ้นแล้ว\n\nควิลบอร์ไม่ใช่พวกแรกที่ใช้ธาตุเป็นอาวุธอย่างไร้ความรับผิดชอบ และจะไม่ใช่พวกสุดท้าย หากจะเตรียมพิธีต้าน เราต้องเข้าใจธาตุบิดเบี้ยวเหล่านี้มากขึ้น รับหนังสือนี้ไป มันบันทึกผู้คนมากมายแห่ง Azeroth และวิธีปฏิบัติศาสตร์ชาแมนของพวกเขา\n\nหากเจ้าเรียนรู้จากพวกเขาได้ เราอาจหาทางแก้ได้" },
        progress = { "22:1583972829:1027382632", "เจ้าเอาอะไรมาให้ข้าล่ะ?" },
        completion = { "370:1192251790:1520286321", "<ฮึ่ม... ทอเรนร่างใหญ่พ่นลมหายใจขณะอ่านแผ่นหนัง>\n\nอย่างหนึ่งที่แน่ชัด คนที่เขียนข้อความนี้พูดถูก ไม่มีใครเห็นการเตรียมการของพวกมัน เรามัวแต่รับมือเซนทอร์กับฮาร์ปีจนไม่มีเวลาส่งผู้ขี่สัตว์บินไปลาดตระเวนตามหุบผาและหน้าผา\n\nขอบใจที่เตือนเราเรื่องภัยนี้ แต่เราอาจยังต้องขอแรงเจ้าอีก", variants = { { "123:2012269070:1513729735", "จะทำพิธีชำระล้างด้วยโทเท็มที่ศัตรูบิดเบือนเองอย่างนั้นรึ? ข้ารู้อยู่แล้วว่าคาดหวังเรื่องใหญ่จากเจ้าได้\n\nลงมือกันเถอะ" } } },
        required = { [274046] = { "19:2104709812:1270325850", "โทเทมน้ำบิดเบี้ยว" }, [274045] = { "19:1611559186:1610243542", "โทเทมดินบิดเบี้ยว" }, [274044] = { "18:799699539:828605915", "โทเทมไฟบิดเบี้ยว" }, [274047] = { "17:1031095786:25250458", "โทเทมลมบิดเบี้ยว" } },
        steps = { { "19:2104709812:1270325850", "โทเทมน้ำบิดเบี้ยว" }, { "19:1611559186:1610243542", "โทเทมดินบิดเบี้ยว" }, { "18:799699539:828605915", "โทเทมไฟบิดเบี้ยว" }, { "17:1031095786:25250458", "โทเทมลมบิดเบี้ยว" } },
    },
    [79360] = { -- Elemental Aid
        title = { "13:595551368:218416802", "ช่วยเหลือเหล่าธาตุ" },
        objective = { "92:1419008046:1244967140", "ปราบ Charlga Razorflank ใน Razorfen Kraul และรวบรวมข้อมูลแผนของควิลบอร์" },
        description = { "438:1273896364:741189431", "เมื่อเชี่ยวชาญธาตุแล้ว เจ้าก็มีหน้าที่ต่อพวกมัน และต่อ Azeroth ทั้งมวล เราร้องขอความช่วยเหลือ ไม่ใช่สั่งเอาพลัง ถึงเวลาตอบแทนความกรุณาที่ได้รับ ข้าคิดว่ารู้วิธี\n\nควิลบอร์บิดธาตุเพื่อเป้าหมายตน และดูจะขยายอิทธิพลภายในเขตแดนนี้ เข้าไปในรังของพวกมันและยุติแผนร้าย ไม่ว่าจะเป็นอะไร เราต้องปกป้องดินแดนนี้" },
        completion = { "337:1150759601:453381177", "<เจ้ายื่นจดหมายให้ Bath'rah เขาอ่านแล้วหัวเราะเบา ๆ อย่างไม่ค่อยเต็มใจ>\n\nอา เป็นเรื่องจริงสินะ สหาย ข้าก็สัมผัสถึงความปั่นป่วนในระนาบธาตุ นี่คงเป็นสาเหตุหนึ่ง\n\nจะท่วม Thousand Needles ทั้งหมดต้องใช้พายุใหญ่ และจะมีคนตายอีกมาก\n\nข้าว่ามีของที่เหมาะกับเจ้าอยู่ แต่จะเอามาได้คงไม่ง่าย", variants = { { "306:170559778:1838465135", "ฮึ่ม... อย่างหนึ่งที่แน่คือ คนเขียนจดหมายพูดถูกว่าพวกเขาเตรียมการกันโดยไม่มีใครเห็น พวกเรายุ่งอยู่กับการรับมือเซนทอร์และฮาร์ปีจนไม่มีเวลาส่งนักขี่ไวเวิร์นไปลาดตระเวนตามหุบผา\n\nขอบใจที่เตือนเราถึงภัยนี้ แต่เราอาจยังต้องการความช่วยเหลืออีก" } } },
        progress = { "134:1285552530:1693223485", "อันตรายหรือ? ไม่มีรายงานอะไรทำนองนั้นเลย แล้วพวกนักขี่วินด์ไรเดอร์ของเราก็งานล้นมือ ไม่มีเวลาไปวิ่งตามเรื่องผีหรอก" },
        logReady = { "63:1044234943:1081796285", "นำ Tattered Note ไปให้ Rau Cliffrunner ที่ Thousand Needles" },
        required = { [274463] = { "13:1549383970:1052927273", "ข้อความที่ฉีกขาด" } },
        steps = { { "13:1549383970:1052927273", "ข้อความที่ฉีกขาด" } },
    },
    [79361] = { -- Storm, Earth, and Fire
        title = { "22:940476950:472117575", "พายุ ดิน และไฟ" },
        objective = { "144:150254269:109391478", "รวบรวม Twisted Fire Totems 5 ชิ้น, Twisted Earth Totems 5 ชิ้น, Twisted Air Totems 5 ชิ้น และ Twisted Water Totems 5 ชิ้นให้ Prate Cloudseer ใน Thousand Needles", amount = { "8:1089852795:1107240600 W1 22:1449430616:1721010504 W2 23:67107465:718983881 W3 25:1755691611:2042489244 W4 62:1455801060:1860668661", "รวบรวม Twisted Fire Totems {world1} ชิ้น, Twisted Earth Totems {world2} ชิ้น, Twisted Air Totems {world3} ชิ้น และ Twisted Water Totems {world4} ชิ้นให้ Prate Cloudseer ใน Thousand Needles" } },
        description = { "503:900616429:795349746", "ควิลบอร์หมายจะใช้ศาสตร์ชาแมนบิดเบี้ยวท่วม Thousand Needles หรือ? แทบจินตนาการไม่ออก แต่เจ้าก็เห็นแล้วว่าดูเบาพวกมันไม่ได้\n\nข้าหวังจะฝึกเจ้าอย่างจริงจังต่อ แต่ตอนนี้ไม่มีเวลา แดนนี้เป็นบ้านของสัตว์หลากหลายทั้งมิตรและศัตรู ไม่มีใครสมควรพบชะตานั้น เราต้องลงมือ\n\nรับคัมภีร์นี้ไป เดิมมีไว้ศึกษา แต่ตอนนี้อาจเป็นกุญแจสลายพายุที่ใกล้มา" },
        completion = { "129:1360597137:168703943", "ข้ารู้สึกถึงความแปดเปื้อนจากที่นี่ ธาตุบิดเบี้ยวที่ควิลบอร์กำลังเรียกน่าจะถูกดึงดูดเข้าสู่พิธีชำระ" },
        progress = { "117:960956105:421970668", "โลกนี้มีผู้ปฏิบัติศาสตร์ชาแมนมากมาย เรามีหน้าที่ดูแลแผ่นดินให้พ้นจากการใช้พลังในทางผิด" },
        required = { [274046] = { "19:2104709812:1270325850", "โทเทมน้ำบิดเบี้ยว" }, [274045] = { "19:1611559186:1610243542", "โทเทมดินบิดเบี้ยว" }, [274044] = { "18:799699539:828605915", "โทเทมไฟบิดเบี้ยว" }, [274047] = { "17:1031095786:25250458", "โทเทมลมบิดเบี้ยว" } },
        steps = { { "19:2104709812:1270325850", "โทเทมน้ำบิดเบี้ยว" }, { "19:1611559186:1610243542", "โทเทมดินบิดเบี้ยว" }, { "18:799699539:828605915", "โทเทมไฟบิดเบี้ยว" }, { "17:1031095786:25250458", "โทเทมลมบิดเบี้ยว" } },
    },
    [79364] = { -- Eyes on the Sky
        title = { "15:1350340376:601353281", "จับตาท้องฟ้า" },
        objective = { "47:483238009:1303057349", "คุยกับ Prate Cloudseer ใน Thousand Needles" },
        description = { "504:2137192170:821032341", "สารที่เจ้าพบบอกว่า Razormane ขุดโพรงเข้า Thousand Needles เพื่อทำพิธีลับบางอย่าง พายุคลั่งและน้ำที่สูงขึ้น...\n\nควิลบอร์คงใช้มนตร์โหดร้ายที่เรียนจาก Hirzek ชาแมนผู้ทุ่มเทบิดธาตุ หากหมายจะท่วมหุบผา ก็ต้องใช้พลังธาตุร้ายแรง\n\nเราไม่พร้อมรับมือ แต่ชาแมนทรงพลังเช่นเจ้าคงมีความคิด กลับไปหาพวกพ้อง ดูว่าจะหาคำตอบได้หรือไม่" },
        completion = { "26:458761899:1067256412", "รู้อยู่แล้วว่าพึ่งเจ้าได้", variants = { { "96:635458215:1823427854", "เจ้ากลับมาแล้ว เห็นไหมว่าท้องฟ้ามืดลงทุกที? มีข่าวอะไรเรื่องภัยจากพวกควิลบอร์บ้าง?" } } },
        progress = { "75:2017714924:240618031", "เราต้องใช้ขวดที่ใหญ่กว่านี้และใสแจ๋ว ถึงจะเก็บพลังธาตุพวกนี้ไว้ได้" },
        logReady = { "47:483238009:1303057349", "คุยกับ Prate Cloudseer ใน Thousand Needles" },
    },
    [79366] = { -- Heed My Call
        title = { "12:1509510998:77389090", "จงฟังเสียงเรียกข้า" },
        objective = { "60:805079116:1760194086", "ใช้ Twisted Totems เพื่อยุติพิธีของควิลบอร์" },
        description = { "395:1791311578:1383263722 N 65:511178705:731100719", "เมื่อมีโทเทมบิดเบี้ยวแล้ว เราต้องใช้มันเรียกธาตุแปดเปื้อนที่ควิลบอร์วิงวอนหา ปราบพวกมันเพื่อชำระดินแดนและจบพิธีน่ารังเกียจของ Razormane แล้วรายงานความสำเร็จต่อ Rau Cliffrunner\n\nเริ่มชำระที่แอ่งไอน้ำทางตะวันตก บริเวณนั้นอุดมด้วยธาตุทุกชนิด แต่ระวัง {name} ควิลบอร์จะไม่อยู่นิ่งขณะเจ้าขัดแผน" },
        completion = { "97:913282642:1540152447 N 33:899651019:473491789", "แผ่นดินที่ครืนเงียบลง ข้ารู้ในใจว่าเจ้าช่วยเราไว้แล้ว ขอบคุณเจ้า {name} เจ้าทำให้ Earthen Ring ของเจ้าภูมิใจ" },
        progress = { "31:1508505917:480506988", "มีข่าวเรื่องพายุบ้างไหม?" },
        logReady = { "68:2109358545:1994295571", "กลับไปหา Rau Cliffrunner ที่ Freewind Post แล้วรายงานสิ่งที่เกิดขึ้น" },
        required = { [212792] = { "18:83088727:1445732554", "ดวงตาแห่งพายุ" }, [268582] = { "16:1068558102:67873513", "โทเทมที่ถูกทำให้แปดเปื้อน" } },
        steps = { { "18:83088727:1445732554", "ดวงตาแห่งพายุ" }, { "16:1068558102:67873513", "โทเทมที่ถูกทำให้แปดเปื้อน" } },
    },
    [79442] = { -- The Tempest's Weapons
        title = { "21:830669426:271184191", "อาวุธแห่งพายุ" },
        objective = { "80:1431185501:1670188825", "นำ Eye of the Tempest ไปให้ Bath'rah the Windwatcher ใน Alterac Mountains" },
        description = { "221:1643372156:853647812", "ผู้คนเราไม่รู้จะขอบคุณเจ้าอย่างไรให้พอ แต่ดวงตานี้ข้าไม่ได้ใช้ประโยชน์ ได้ยินว่ามีชาแมนชราใน Alterac Mountains ผู้รอบรู้เวทธาตุพายุ บางทีเขาอาจสร้างอะไรให้เจ้าได้" },
        completion = { "184:117815139:394306112", "อา นี่คือวัตถุทรงพลัง สหาย! ข้าไม่ได้สร้างของด้วยสิ่งเช่นนี้มานานแล้ว\n\nดูแลให้ดี เข้าใจไหม? ดูเหมือนเจ้าลำบากไม่น้อยกว่าจะได้มา!" },
        progress = { "134:1576420365:1783505722", "ศึกใหญ่กับธาตุหรือ อืม? ทุกอย่างลงเอยอย่างที่ควรเป็นเสมอ\n\nแต่ไหน ๆ ก็มาถึงแล้ว อะไรพาเจ้ามาหา Bath'rah คนนี้?" },
        required = { [212792] = { "18:83088727:1445732554", "ดวงตาแห่งพายุ" } },
        steps = { { "18:83088727:1445732554", "ดวงตาแห่งพายุ" } },
    },
    [92484] = { -- Embracing the Elements
        title = { "22:810976823:2068100930", "ยอมรับวิถีแห่งธาตุ" },
        objective = { "84:34313861:961716977", "ตรวจดู Humming Recall Crystal แล้วคุยกับ Windshaper Boro ใน Thendal Grove" },
        description = { "222:602341032:809675886", "ระหว่างเจ้าออกไปจัดการปัญหา Vuldren ครูฝึกชาแมนของเรา Windshaper Boro ฝาก Recall Crystal นี้ไว้ให้ โปรดตรวจดู แล้วคุยกับ Boro ที่อยู่ถัดไปใกล้ใจกลางหมู่บ้าน" },
        progress = { "24:966844349:2145163805", "ขอสายลมนำทาง สหาย", variants = { { "17:1082632394:367722637 N 1:46:46", "ขอสายลมนำทางเจ้า {name}" } } },
        completion = { "486:1213507050:2016801406", "ได้ยินไหม? เสียงกระซิบของสายลม? คงยาก เพราะวิญญาณหยุดพูดกับเราตั้งแต่จากไปหลายปีก่อน\n\nพวกเราผู้หวังเข้าพบวิญญาณแห่งลมทั้งสี่อีกครั้ง ฝึกความเข้าใจธาตุและโลกธรรมชาติ ด้วยความหวังแรงกล้าว่าจะรื้อฟื้นบทสนทนาที่จบลงกะทันหัน\n\nเจ้าจะเดินทางนี้และเรียนรู้ธาตุให้เชี่ยวชาญหรือไม่?\n\nหากต้องการก้าวต่อ มาคุยกับข้าอีก แล้วข้าจะฝึกให้" },
        required = { [282418] = { "22:1271839763:245221928", "ผลึกเรียกกลับที่ส่งเสียงหึ่ง" } },
        objectiveLabels = {
            item = { ["Humming Recall Crystal"] = "ผลึกเรียกกลับที่ส่งเสียงหึ่ง" },
        },
    },
    [94373] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "63:750124453:144195247", "นำ Frostmane Bear Pendants 2 ชิ้นไปให้ Teo Hammerstorm ใน Anvilmar" },
        description = { "464:541013900:1411019187", "ถึงเวลาแล้ว ชาแมนน้อย เจ้าเติบโตแข็งแกร่งมั่นคงดุจหินใต้รองเท้า การเลือกวิถีชาแมนแสดงว่ามีปัญญาแห่งภูเขาก่อนพิสูจน์ตน เจ้ามีความเด็ดเดี่ยวดุจหินพอจะเดินวิถีดิน\n\nแต่หากจะได้รับความโปรดปราน ต้องเผชิญมันอย่างเหมาะสม ทางใต้มีโทรลล์ Frostmane อาศัยในถ้ำ\n\nนำสร้อยที่ทำจากหมี Iceclaw ซึ่งพวกมันสวมมาสองเส้น แล้วเราจะคุยถึงอนาคตของเจ้าต่อ", variants = { { "28:1440120195:901376446 C 80:250230735:1582746720 C 347:1461535739:688111806", "เอาละ ถึงเวลาแล้ว {class}น้อย เจ้าเติบโตแข็งแกร่งมั่นคงดุจหินใต้รองเท้า การเลือกเดินวิถีของ{class}แสดงว่าเจ้ามีปัญญาดุจขุนเขาแม้ยังไม่ได้พิสูจน์ตน เจ้ามีใจแกร่งดั่งหินพอจะเดินตามวิถีแห่งผืนดิน\n\nแต่หากอยากให้ผืนดินโปรดปราน เจ้าต้องเผชิญบททดสอบให้สมควร ทางใต้ของที่นี่มีโทรลล์ Frostmane อาศัยอยู่ในถ้ำ\n\nนำสร้อยคอที่พวกมันสวมมาสองเส้น สร้อยพวกนั้นทำจากหมี Iceclaw แล้วเราค่อยมาคุยกันต่อเรื่องอนาคตของเจ้า" } } },
        completion = { "350:475775015:881892766", "ทำได้ดี เจ้าหนุ่ม เจ้าพิสูจน์แล้วว่าพร้อม ผืนดินเป็นรากฐานของทุกสิ่ง ทั้งพละกำลัง ความทรหด และความอดทน มันจะปกป้องเจ้าถ้าเจ้าให้ความเคารพอย่างที่ควร แม้แต่หินก็ยังเคลื่อนได้หากเจ้าดูแคลนมัน เรียนรู้วิถีของผืนดิน แล้วเจ้าจะมีปัญญาเหนือคนส่วนใหญ่ อย่าลืมความลับที่มันแบ่งปันให้เจ้า\n\nข้าจะทำ Sapta ให้ตอนนี้ รับไปเถอะ แล้วเจ้าจะได้เดินบนหนทางที่แท้จริง", variants = { { "349:729383481:754868713", "ทำได้ดี เจ้าหนุ่ม เจ้าพิสูจน์แล้วว่าพร้อม ผืนดินเป็นรากฐานของทุกสิ่ง ทั้งพละกำลัง ความทรหด และความอดทน มันจะปกป้องเจ้าถ้าเจ้าให้ความเคารพอย่างที่ควร แม้แต่หินก็ยังเคลื่อนได้หากเจ้าดูแคลนมัน เรียนรู้วิถีของผืนดิน แล้วเจ้าจะมีปัญญาเหนือคนส่วนใหญ่ อย่าลืมความลับที่มันแบ่งปันให้เจ้า\n\nข้าจะทำ Sapta ให้ตอนนี้ รับไปเถอะ แล้วเจ้าจะได้เดินบนหนทางที่แท้จริง" }, { "321:986776960:1294026721", "ทำได้ดี สาวน้อย เจ้าพิสูจน์แล้วว่าพร้อม ผืนดินเป็นรากฐานของทุกสิ่ง มันจะปกป้องเจ้าถ้าเจ้าให้ความเคารพอย่างที่ควร แม้แต่หินก็ยังเคลื่อนได้หากเจ้าดูแคลนมัน เรียนรู้วิถีของผืนดิน แล้วเจ้าจะมีปัญญาเหนือคนส่วนใหญ่ อย่าลืมความลับที่มันแบ่งปันให้เจ้า\n\nข้าจะทำ Sapta ให้ตอนนี้ รับไปเถอะ แล้วเจ้าจะได้เดินบนหนทางที่แท้จริง" }, { "320:24502739:977339032", "ทำได้ดี เจ้าหนุ่ม เจ้าพิสูจน์แล้วว่าพร้อม ผืนดินเป็นรากฐานของทุกสิ่ง มันจะปกป้องเจ้าถ้าเจ้าให้ความเคารพอย่างที่ควร แม้แต่หินก็ยังเคลื่อนได้หากเจ้าดูแคลนมัน เรียนรู้วิถีของผืนดิน แล้วเจ้าจะมีปัญญาเหนือคนส่วนใหญ่ อย่าลืมความลับที่มันแบ่งปันให้เจ้า\n\nข้าจะทำ Sapta ให้ตอนนี้ รับไปเถอะ แล้วเจ้าจะได้เดินบนหนทางที่แท้จริง" } } },
        progress = { "131:1347214358:1513199385 R 187:36220185:1248039085", "ความอดทนคือคุณธรรมสูงสุดของผืนดิน เจ้าหนุ่ม มันเห็นภูเขาพังทลายและสายน้ำกัดเซาะหุบเขามาแล้ว ค่อยเป็นค่อยไปแต่ดื้อรั้นเหมือน {race} แท้ ๆ ตอนนี้ผืนดินกำลังเรียกเจ้า เพราะภัยกำลังก่อตัวอยู่เบื้องหน้า จงกลับมาพร้อมความสำเร็จ แล้วเจ้าจะเข้าใกล้ความสมบูรณ์ไปอีกขั้น\n\nคนอื่นอาจอิจฉาปัญญาของเจ้า แต่นั่นเป็นภาระที่พวกเขาต้องแบกเอง", variants = { { "131:304480943:899930439 R 187:36220185:1248039085", "ความอดทนคือคุณธรรมสูงสุดของผืนดิน สาวน้อย มันเห็นภูเขาพังทลายและสายน้ำกัดเซาะหุบเขามาแล้ว ค่อยเป็นค่อยไปแต่ดื้อรั้นเหมือน {race} แท้ ๆ ตอนนี้ผืนดินเรียกหาเจ้า เพราะภัยกำลังก่อตัวอยู่เบื้องหน้า จงกลับมาพร้อมความสำเร็จ แล้วเจ้าจะเข้าใกล้ความสมบูรณ์ไปอีกขั้น\n\nคนอื่นอาจอิจฉาปัญญาของเจ้า แต่นั่นเป็นภาระที่พวกเขาต้องแบกเอง" }, { "130:1772525252:1918057205 R 187:36220185:1248039085", "ความอดทนคือคุณธรรมสูงสุดของผืนดิน เจ้าหนุ่ม มันเห็นภูเขาพังทลายและสายน้ำกัดเซาะหุบเขามาแล้ว ค่อยเป็นค่อยไปแต่ดื้อรั้นเหมือน {race} แท้ ๆ ตอนนี้ผืนดินกำลังเรียกเจ้า เพราะภัยกำลังก่อตัวอยู่เบื้องหน้า จงกลับมาพร้อมความสำเร็จ แล้วเจ้าจะเข้าใกล้ความสมบูรณ์ไปอีกขั้น\n\nคนอื่นอาจอิจฉาปัญญาของเจ้า แต่นั่นเป็นภาระที่พวกเขาต้องแบกเอง" } } },
        required = { [264356] = { "20:774898879:1242783396", "จี้หมี Iceclaw" } },
        steps = { { "20:774898879:1242783396", "จี้หมี Iceclaw" } },
    },
    [94374] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "48:497907780:1667681013", "หา Spirit Stone แล้วดื่ม Earth Sapta" },
        description = { "377:1085493376:2067964184", "Sapta เป็นเครื่องดื่มผสานเวทที่ผูกจิตของเรากับธาตุ มีชาแมนไม่กี่คนรู้สูตร และไม่เหมาะกับคนใจอ่อน ดื่มแล้วจะเห็นสิ่งที่คนอื่นไม่เห็น จงมั่นคง จำไว้ว่าต้องดื่มในสถานที่ศักดิ์สิทธิ์เท่านั้น\n\nขึ้นเหนือไป Spirit Stone ที่ซ่อนอยู่สุดทางลับบนเขา ดื่มที่นั่น... แล้วดูว่าแผ่นดินจะแสดงอะไร" },
        completion = { { "375:878015174:386694021", "6:1572241333:73377271 N 363:202514568:225407060", "6:1572241333:73377271 C 363:202514568:225407060", "6:1572241333:73377271 R 363:202514568:225407060" }, "อา... สหาย... แผ่นดินต้อนรับเจ้า แม้ในดินแดนเยือกแข็งนี้ เมื่อกายและจิตผูกกัน เจ้าจะก้าวต่อโดยรู้ว่าภูเขาคือกำลัง ทุ่งราบคือความอดทน และโลกคือแก่นแท้\n\nเพียงยืนต่อหน้าดินอย่างถ่อมตนก็ผ่านพิธี ธาตุอื่นไม่สงบนิ่ง พวกมันปะทะและคำราม จงเรียนรู้ธรรมชาติสองด้าน แม้อยู่ท่ามกลางหิมะและหิน", variants = { { "6:1572241333:73377271 N 363:1595044277:2098070465", "อา... {name}... ผืนดินต้อนรับเจ้า แม้ในแดนเยือกแข็งแห่งนี้ เมื่อกายและจิตเป็นหนึ่งเดียว เจ้าจะก้าวต่อไปโดยรู้ว่าภูเขาคือพละกำลังของเจ้า ทุ่งราบคือความอดทน และโลกคือแก่นแท้ของเจ้า\n\nเพื่อผ่านพิธีนี้ จงยืนต่อหน้าผืนดินอย่างถ่อมตน ธาตุอื่นปะทะและคำรามอยู่เสมอ จงเรียนรู้ธรรมชาติสองด้านของพวกมัน แม้ในที่ที่มีเพียงหิมะและหินแห่งนี้" }, { "6:1572241333:73377271 N 364:156771410:911246355", "อา... {name}... แผ่นดินต้อนรับเจ้า แม้ในดินแดนเยือกแข็งนี้ เมื่อกายและจิตผูกกัน เจ้าจะก้าวต่อโดยรู้ว่าภูเขาคือกำลัง ทุ่งราบคือความอดทน และโลกคือแก่นแท้\n\nเพียงยืนต่อหน้าดินอย่างถ่อมตนก็ผ่านพิธี ธาตุอื่นไม่สงบนิ่ง พวกมันปะทะและคำราม จงเรียนรู้ธรรมชาติสองด้าน แม้อยู่ท่ามกลางหิมะและหิน" } } },
    },
    [94375] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "54:451898819:404060253", "นำ Rough Quartz ไปให้ Teo Hammerstorm ใน Anvilmar" },
        description = { "306:1323086454:1863739915 N 147:1870412720:337466867", "รับควอตซ์หยาบนี้ไปให้ Teo Hammerstorm เป็นหลักฐานว่าเราพบกัน เขาจะสร้างโทเทมให้ โดยใช้ก้อนหินนี้เป็นหัวใจ แม้ดูเล็ก เจ้าจะพบว่าขนาดไม่สำคัญ และสิ่งเล็กที่สุดก็อาจคงอยู่ได้นานกว่าสิ่งอื่นมากมาย\n\nจงอดทน {name} เข้มแข็งและแสวงหาปัญญา นี่คือสิ่งที่ดินขอ สุดท้ายเจ้าจะเป็นหนึ่งเดียวกับแผ่นดิน จงเคารพมันเช่นเดียวกับที่มันเคารพเจ้า" },
        progress = { "210:1293110915:431403270", "อา กลับมาแล้ว หากมีหิน แสดงว่าภูเขาเลือกเจ้าจริง ข้าจะมอบโทเทมตามที่มันสัญญา แต่ถ้ามามือเปล่าก็กลับไป! เส้นทางนี้ไม่เหมาะกับคนลืมทางของตน" },
        completion = { "329:953686128:1701661499", "ทำได้ดี! จำไว้นะ โทเท็มมีความหมายมากกว่าเครื่องหมายบอกฐานะของเจ้าในหมู่ชาแมน มันเป็นเครื่องมือสำหรับรวมพลังเวทที่เชื่อมโยงกับหิน ดิน และธาตุอื่น ๆ เมื่อเจ้ามีปัญญามากขึ้น พลังของภูเขาจะเปิดรับเจ้ายิ่งขึ้น ครูฝึกจะรู้เองว่าเจ้าพร้อมเรียนต่อเมื่อไร ตอนนี้รับโทเท็มนี้ไป แล้วให้ผืนดินเอ่ยวาจาผ่านตัวเจ้า", variants = { { "328:823353094:644085619", "ทำได้ดี! จำไว้นะ โทเท็มมีความหมายมากกว่าเครื่องหมายบอกฐานะของเจ้าในหมู่ชาแมน มันเป็นเครื่องมือสำหรับรวมพลังเวทที่เชื่อมโยงกับหิน ดิน และธาตุอื่น ๆ เมื่อเจ้ามีปัญญามากขึ้น พลังของภูเขาจะเปิดรับเจ้ายิ่งขึ้น ครูฝึกจะรู้เองว่าเจ้าพร้อมเรียนต่อเมื่อไร ตอนนี้รับโทเท็มนี้ไป แล้วให้ผืนดินเอ่ยวาจาผ่านตัวเจ้า" } } },
        required = { [6656] = { "12:2047988926:1690463399", "ควอตซ์หยาบ" } },
        steps = { { "12:2047988926:1690463399", "ควอตซ์หยาบ" } },
    },
    [94472] = { -- Earth Sapta
        title = { "11:318297221:1784516132", "น้ำศักดิ์สิทธิ์แห่งธาตุดิน" },
        objective = { "49:215943359:169875050", "คุยกับ Teo Hammerstorm เพื่อขอ Earth Sapta อีกขวด" },
        completion = { "37:1177307499:328791381", "รับไป และจำไว้ว่านี่เป็นของศักดิ์สิทธิ์" },
        description = { "71:1538138461:1633980633", "เจ้ากลับมาหาข้าทั้งที่ไม่มีทั้งน้ำศักดิ์สิทธิ์และโทเท็มธาตุดิน น่าเสียดายจริง ๆ" },
    },
    [94473] = { -- Fire Sapta
        title = { "10:1894250526:440813189", "น้ำศักดิ์สิทธิ์แห่งธาตุไฟ" },
        objective = { "49:1367840813:1989901773", "คุยกับ Braldir Ashmantle เพื่อขอ Fire Sapta อีกขวด", variants = { { "50:1495254526:831613200", "คุยกับ Braldir Ashmantle เพื่อขอ Fire Sapta อีกขวด" } } },
        completion = { "33:1648711972:59103623 N 25:333232212:744061430", "ขอให้ไฟลุกโชนอยู่ในใจเจ้า {name}\n\nเหล่าธาตุรอเจ้าอยู่" },
        description = { "147:198011063:1791920892", "หากเจ้าแพ้ร่างอวตารในการต่อสู้ ก็มาคุยกับข้า ข้าจะให้น้ำศักดิ์สิทธิ์อีกขวด เพื่อให้เจ้ามองเห็นเหล่าวิญญาณที่ศาลเจ้าด้านบน" },
    },
    [94494] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "36:693736648:882516360", "ไปหา Norric Lochthane ใน Loch Modan" },
        description = { "44:245382568:1822071705 N 290:2116087423:1910452357 N 1:46:46", "นานแล้วนับจากบททดสอบก่อน {name} เจ้าศึกษาอย่างอดทน แต่ถึงเวลาเรียนรู้ความบริสุทธิ์ของน้ำ\n\nไปหา Norric Lochthane ใน Loch Modan เขาอยู่ริมทะเลสาบด้านตะวันตกเฉียงเหนือ ทางใต้ของ Stonewrought Dam ที่กระท่อมโพรงดิน ขอให้โชคดี {name}" },
        completion = { "305:1917655704:1977757503", "ลมพัดหนุนหลัง หินใต้รองเท้ามั่นคง และไฟในท้องลุกโชน ถึงเวลาเรียนรู้ความจริงแห่งน้ำบริสุทธิ์ เส้นทางเจ้ามายาวไกล แต่จิตเจ้าจะพาไปได้ไกลกว่าเดิม ไปเถิด ก้าวแรกได้แล้ว ภูเขาไม่รอใคร" },
    },
    [94495] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "39:2077772614:173191795", "ไปหา Hervdana Saegrund ใน Wetlands" },
        description = { "371:1124665175:350468599", "หากมีความจริงหนึ่งที่ต้องรู้เกี่ยวกับน้ำ ก็คือน้ำหมายถึงการเกิดใหม่ มันสลักหิน ชำระสิ่งสกปรก และรักษาผู้อ่อนล้า แต่เฉพาะเมื่อบริสุทธิ์ หากปนเปื้อน มันทำลายทุกสิ่งที่สัมผัส\n\nหากแสวงหา Water Sapta ไปหา Hervdana Saegrund ใน Wetlands ครอบครัวนางอยู่ถ้ำใต้น้ำตกทางใต้\n\nไปเถิด อย่าปล่อยให้แม่น้ำวิ่งนำเจ้า" },
        completion = { "426:436636592:1948990087", "ข้าเห็นในตาแล้ว คนแคระเอ๋ย เจ้าสงสัยว่าใครเลือกอยู่ลึกใน Wetlands มีพวก Dark Iron ต่ำช้าซุ่มรอบตัวและไร้ยามเฝ้า เราต่างมีเหตุผลของตน ที่รัก\n\nแต่คำถามจริงคือ อะไรพาเจ้ามาบ้านเรา? ที่ริมน้ำตกนี้ ข้าว่าเราทั้งคู่รู้คำตอบ\n\nHervdana เหยียดแขนออก ปลายนิ้วรับละอองน้ำตก", variants = { { "27:1979707564:19250043 R 314:872002949:297684210", "ใช่ ข้าเห็นแววตาเจ้าแล้ว {race} เอ๋ย เจ้าคงสงสัยว่าใครกันถึงเลือกมาอยู่ลึกถึงเพียงนี้ใน Wetlands มีพวก Dark Iron คอยซุ่มอยู่รอบ ๆ แถมไม่มีทหารยามสักคน เราต่างมีเหตุผลของตัวเองนะ\n\nแต่คำถามจริง ๆ คือ อะไรพาเจ้ามาถึงบ้านของเรา? ที่ริมน้ำตกแห่งนี้ ข้าว่าเราทั้งคู่รู้คำตอบอยู่แล้ว" }, { "428:347246771:923927811", "ข้าเห็นในตาแล้ว คนแคระเอ๋ย เจ้าสงสัยว่าใครเลือกอยู่ลึกใน Wetlands มีพวก Dark Iron ต่ำช้าซุ่มรอบตัวและไร้ยามเฝ้า เราต่างมีเหตุผลของตน ที่รัก\n\nแต่คำถามจริงคือ อะไรพาเจ้ามาบ้านเรา? ที่ริมน้ำตกนี้ ข้าว่าเราทั้งคู่รู้คำตอบ\n\n<Hervdana เหยียดแขนออก ปลายนิ้วรับละอองน้ำตก>" } } },
    },
    [94497] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "122:609540744:556537529", "เติม Empty Brown Waterskin ที่เชิงน้ำตกด้านล่างถ้ำของ Hervdana แล้วนำกลับไปให้นางใน Wetlands" },
        description = { "414:462663488:1283795883", "อา มาหา Sapta หรือ? ถ้าอย่างนั้นฟังให้ดี ที่รัก หากจะเข้าใจและได้รับ Sapta ต้องแสวงหาน้ำในรูปแบบต่าง ๆ ระหว่างเก็บตัวอย่างจงลืมตาดู สังเกตสัตว์ที่ปกป้อง ดินแดนที่มันหล่อเลี้ยง และวิธีที่มันเปลี่ยนชีวิต\n\nเริ่มง่าย ๆ เติมถุงนี้ที่เชิงน้ำตก จุดที่น้ำจืดพบกับน้ำกร่อย ไปเถิด ระวังบึงด้วย" },
        progress = { "296:333903397:2145097481", "ข้าเกือบพร้อมส่งเจ้าไปทำงานที่เหลือแล้ว แต่เติมถุงหรือยัง? มหาสมุทรนำชีวิตมา แต่ก็พัดตะกอน แร่ธาตุ และพลังที่ต่างจากหิมะละลายกับน้ำพุบนที่สูงมาก จุดที่ทะเลพบสายน้ำมีปัญญาให้เรียนรู้", variants = { { "298:951871746:1975234916", "ข้าเกือบพร้อมส่งเจ้าไปทำงานที่เหลือแล้ว แต่เจ้าเติมน้ำใส่ถุงหนังแล้วหรือยัง? มหาสมุทรนำชีวิตมา แต่ก็พัดตะกอน แร่ธาตุ และพลังที่ต่างจากหิมะละลายกับน้ำพุบนที่สูงมาก จุดที่น้ำทะเลกับน้ำพุมาบรรจบกันมีปัญญาให้เรียนรู้" } } },
        completion = { "429:246682285:1420018212", "ดีใจที่หลบ Dark Iron มาได้ น่าเสียดายที่พวกนั้นคืบขึ้นเหนือไกลนัก ทำให้สงสัยว่าคนแคระจะทำอะไรได้บ้าง หากเหล่าเผ่าหยุดทะเลาะและร่วมแรง\n\nถึงอย่างนั้น เมื่อพลังดวงจันทร์เข้มแข็ง น้ำขึ้นสูงและทะเลท่วมบึง ที่นี่คือที่เราศึกษาน้ำปากแม่น้ำ\n\nขอบคุณสำหรับเครื่องบูชาศักดิ์สิทธิ์ นี่คือจุดเริ่มต้นของช่วงที่เจ้าเป็นภาชนะ ผู้แสวงหาปัญญาแห่งน้ำ", variants = { { "429:540838340:1385584515", "ดีใจที่หลบ Dark Iron มาได้ น่าเสียดายที่พวกนั้นคืบขึ้นเหนือไกลนัก ทำให้สงสัยว่าคนแคระจะทำอะไรได้บ้าง หากแต่ละตระกูลหยุดทะเลาะกันแล้วร่วมแรงกัน\n\nถึงอย่างนั้น เมื่ออิทธิพลของดวงจันทร์แรงกล้า น้ำขึ้นสูงและทะเลท่วมบึง ที่นี่คือที่เราศึกษาน้ำปากแม่น้ำ\n\nขอบคุณสำหรับเครื่องบูชาศักดิ์สิทธิ์ นี่คือจุดเริ่มต้นของช่วงที่เจ้าเป็นภาชนะ ผู้แสวงหาปัญญาแห่งน้ำ" } } },
        required = { [265734] = { "20:62085021:257059252", "ถุงน้ำสีน้ำตาลที่เติมจนเต็ม" } },
        steps = { { "20:62085021:257059252", "ถุงน้ำสีน้ำตาลที่เติมจนเต็ม" } },
    },
    [94499] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "127:101919883:905967417", "เติม Empty Red Waterskin ที่ Stonewatch Falls ใกล้ Nightcrawler Murlocs แล้วกลับไปหา Hervdana Saegrund ใน Wetlands" },
        description = { "419:1595853337:1862989805", "Redridge ดื่มน้ำจาก Lake Everstill เต็มที่ แต่พอน้ำตกลง Stonewatch Falls ดูมีบางสิ่งซึมปน เมอร์ล็อกข้างล่างตัวใหญ่บิดเบี้ยว ไม่เหมือนที่นี่หรือใน Loch โชคดีที่พวกมันอยู่แค่เชิงน้ำตก\n\nนำตัวอย่างมา ข้าอยากรู้ว่าเวท พิษ หรือสิ่งเลวร้ายกว่า กำลังทำให้น้ำใกล้ป้อมเก่าแปดเปื้อน" },
        progress = { "282:276585241:1404746516", "ชาว Lakeshire ไม่รู้ว่าตนโชคดีเพียงใด น้ำจืดไหลถึงเท้า ทำให้อวนเต็ม พืชผลเขียว และถุงเงินกรุ๊งกริ๊ง แม้ยามอาณาจักรแทบส่งเด็กถือดาบมาช่วยไม่ได้ พวกเขาก็ยังมี Everstill ดูแล", variants = { { "284:36471597:1639758457", "ชาว Lakeshire ไม่รู้ว่าตนโชคดีเพียงใด น้ำจืดไหลถึงเท้า ทำให้อวนเต็ม พืชผลเขียว และถุงเงินกรุ๊งกริ๊ง แม้ยามอาณาจักรแทบส่งเด็กถือดาบมาช่วยไม่ได้ พวกเขาก็ยังมี Everstill ดูแล" } } },
        completion = { { "387:32664880:1362150793", "25:730507238:519748953 N 356:749061108:1064668575", "25:730507238:519748953 C 356:749061108:1064668575", "25:730507238:519748953 R 356:749061108:1064668575" }, "นี่เป็นน้ำดี สหาย คงเป็นเวทที่พวก Shadowseer ในพื้นที่ใช้เปลี่ยนเมอร์ล็อก น้ำนี้บริสุทธิ์ไม่มีสิ่งอื่น ความทุ่มเทต่องานและความสามารถค้นหาสิ่งจำเป็นพิสูจน์ว่าเจ้าพร้อมสำหรับช่วงถัดไป\n\nข้าต้องการอีกเพียงตัวอย่างเดียว ก็จะสร้างวัตถุดิบสำหรับ Sapta ได้ Norric คงยินดีเช่นกัน", variants = { { "25:730507238:519748953 N 357:1878327976:1635618219", "อืม น้ำดีทีเดียว {name} คงเป็นเวทที่พวก Shadowseer ในพื้นที่ใช้เปลี่ยนเมอร์ล็อก น้ำนี้บริสุทธิ์ไม่มีสิ่งอื่น ความทุ่มเทต่องานและความสามารถค้นหาสิ่งจำเป็นพิสูจน์ว่าเจ้าพร้อมสำหรับช่วงถัดไป\n\nข้าต้องการอีกเพียงตัวอย่างเดียว ก็จะสร้างวัตถุดิบสำหรับ Sapta ได้ Norric คงยินดีเช่นกัน" } } },
        required = { [265748] = { "18:2100920987:203680581", "ถุงน้ำหนังสีแดงที่เติมเต็มแล้ว" } },
        objectiveLabels = {
            item = { ["Full Red Waterskin"] = "ถุงน้ำหนังสีแดงที่เติมเต็มแล้ว" },
