    [94500] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "121:1209224341:1430441545", "เติม Unfilled Blue Waterskin ในน่านน้ำ Astranaar แห่ง Ashenvale แล้วกลับไปหา Hervdana Saegrund ใน Wetlands" },
        description = { "478:1637349145:734085553", "นำถุงน้ำนี้เข้าไปลึกในร่มเงามรกตแห่ง Ashenvale Astranaar โอบล้อมด้วยน้ำที่ไม่แปดเปื้อน ซากโบราณกระจายก้นทะเลสาบ บอกใบ้ยุคที่ล่วงไป นำตัวอย่างน้ำทะเลสาบกลับมา น้ำบริสุทธิ์ เก่าแก่ และอาจมีมนตร์\n\nเป็นน้ำอย่างสุดท้ายก่อนข้าส่งเจ้ากลับไปหา Norric\n\nขึ้นเรือที่ Menethil ไป Auberdine ระหว่างทางจะแวะ Southshore\n\nระวังตัวด้วย... ป่านี้มีดวงตา และไม่เคยกะพริบ", variants = { { "478:1414144471:963495720", "นำถุงน้ำนี้เข้าไปลึกในร่มเงามรกตแห่ง Ashenvale Astranaar โอบล้อมด้วยน้ำที่ไม่แปดเปื้อน ซากโบราณกระจายก้นทะเลสาบ บอกใบ้ยุคที่ล่วงไป นำตัวอย่างน้ำทะเลสาบกลับมา น้ำบริสุทธิ์ เก่าแก่ และอาจมีมนตร์\n\nเป็นน้ำอย่างสุดท้ายก่อนข้าส่งเจ้ากลับไปหา Norric\n\nขึ้นเรือที่ Menethil ไป Auberdine ระหว่างทางจะแวะ Southshore\n\nระวังตัวด้วย... ป่านี้มีดวงตา และไม่เคยกะพริบ" } } },
