    [94501] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "65:778397676:1665605384", "นำ Vial of Purest Water ไปให้ Norric Lochthane ใน Loch Modan" },
        description = { "208:83734894:460205216", "Norric จะมีงานอีกอย่างก่อนมอบพิธีโทเทมน้ำ ไม่ว่างานนั้นจะเป็นอะไร ก็ต้องใช้น้ำในขวดที่ข้าให้ ไปหาเขาเถิด สักวันเราจะพบกันอีก" },
        progress = { { "74:1236005462:388153132", "13:1366380142:1891123769 N 55:949245445:169572655", "13:1366380142:1891123769 C 55:949245445:169572655", "13:1366380142:1891123769 R 55:949245445:169572655" }, "สวัสดีอีกครั้ง สหาย ดูสบายดีนะ\n\nอะไรพากลับมาหาข้าเร็วนัก?" },
        completion = { "322:413967692:1609619083", "อา น้ำที่ Hervdana อวยพรเองและเจ้าเก็บด้วยมือ? เป็นของขวัญแท้จริง\n\nน้ำเหล่านี้จะให้กำเนิด Sapta ช่วยให้เห็นวิญญาณน้ำที่ Stendel's Pond ใกล้ Moonbrook หยดสุดท้ายก็มีหน้าที่สำคัญไม่แพ้กัน... อย่าทิ้งแม้จุกขวดที่ชุ่มน้ำศักดิ์สิทธิ์", variants = { { "322:1441184307:1460433423", "อา น้ำที่ Hervdana อวยพรเองและเจ้าเก็บด้วยมือ? เป็นของขวัญแท้จริง\n\nน้ำเหล่านี้จะให้กำเนิด Sapta ช่วยให้เห็นวิญญาณน้ำที่ Stendel's Pond ใกล้ Moonbrook หยดสุดท้ายก็มีหน้าที่สำคัญไม่แพ้กัน... อย่าทิ้งแม้จุกขวดที่ชุ่มน้ำศักดิ์สิทธิ์" } } },
        required = { [7810] = { "20:533830180:2011110999", "ขวดบรรจุน้ำบริสุทธิ์ที่สุด" } },
        steps = { { "20:533830180:2011110999", "ขวดบรรจุน้ำบริสุทธิ์ที่สุด" } },
    },
    [94502] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "99:1894219376:679443230", "ชำระความแปดเปื้อนที่ Stendel's Pond ใน Westfall\nเสร็จแล้วกลับไปหา Norric ใน Loch Modan", variants = { { "125:1366039310:1488106418", "ดื่ม Water Sapta แล้วชำระความแปดเปื้อนที่ Stendel's Pond ใน Westfall\nเสร็จแล้วกลับไปหา Norric ใน Loch Modan" } } },
        description = { "448:25209913:1313729743", "นอก Moonbrook ใน Westfall มี Stendel's Pond เคยเป็นน้ำพุบริสุทธิ์ แต่ตอนนี้ถูกอำนาจมืดแตะต้อง วิญญาณที่นั่นเงียบไปแล้ว\n\nเจ้าต้องดื่ม Water Sapta แล้วเผชิญความแปดเปื้อนที่ทำให้น้ำเสีย นำปลอกแขนของมันกับหยดน้ำยาของ Hervdana ที่เหลือวางบนศาล จะเรียกวิญญาณบริสุทธิ์แท้จริงออกมา คุยและเรียนรู้เท่าที่ทำได้\n\nนำหลักฐานกลับมา แล้วข้าจะมอบโทเทมให้", variants = { { "420:1156092044:909318807", "นอก Moonbrook ใน Westfall มี Stendel's Pond เคยเป็นน้ำพุบริสุทธิ์ แต่ตอนนี้ถูกอำนาจมืดแตะต้อง วิญญาณที่นั่นเงียบไปแล้ว\n\nเจ้าต้องเผชิญความแปดเปื้อนที่ทำให้น้ำเสีย นำปลอกแขนของมันกับหยดน้ำยาของ Hervdana ที่เหลือวางบนศาล จะเรียกวิญญาณบริสุทธิ์แท้จริงออกมา คุยและเรียนรู้เท่าที่ทำได้\n\nนำหลักฐานกลับมา แล้วข้าจะมอบโทเทมให้" } } },
        progress = { "351:907913011:1431306128", "ศาลเก่าแก่ถูกลืม คลุมด้วยฝุ่นและใยแมงมุม สระข้าง ๆ นิ่งสงัดน่าขนลุก ผิวน้ำไร้ลมหรือชีวิตแตะต้อง ริมฝั่งมีกระดูกสัตว์ที่ครั้งหนึ่งเคยแบกภาระงานกระจัดกระจาย เงาขุ่นบนผิวน้ำชวนสงสัย มันถูกความเสื่อมโทรมรอบข้างทำให้เป็นพิษ หรือเป็นต้นตอเสียเอง?" },
        completion = { "226:1269103921:1647055317", "เจ้าวางปลอกแขนบนศาล แล้วเทหยดน้ำยาของ Norric ที่เหลือลงบนหินแห้ง เริ่มกล่าวถ้อยคำเรียบง่ายที่ Norric สอน หยดน้ำบนหินภายในปลอกแขนระเหยเป็นไอ..." },
        required = { [7812] = { "31:747673525:172901740", "ปลอกรัดแขนของ Corrupt Manifestation" }, [7811] = { "31:954020276:1472835043", "หยดน้ำบริสุทธิ์ที่สุดที่เหลือ" } },
        steps = { { "31:747673525:172901740", "ปลอกรัดแขนของ Corrupt Manifestation" }, { "31:954020276:1472835043", "หยดน้ำบริสุทธิ์ที่สุดที่เหลือ" } },
    },
    [94503] = { -- Call of Water
