        description = { "212:1947011762:1205835193", "แสงพุ่งออกเมื่อคำสุดท้ายพ้นริมฝีปาก เสียงน้ำกลายเป็นไอค่อยเงียบลง ประสาทสัมผัสเจ้าสั่นสะท้าน ขณะวิญญาณแปดเปื้อนรอบตัวสลาย แก่นของมันกระจายดุจเถ้าในสายลม" },
        completion = { "112:2075202244:1814868866", "ขอบใจเจ้า ขอบใจเหล่าชาแมน\n\nความเสื่อมทรามถอยไปแล้ว แต่ชีวิตยังคงร่วงโรย หน้าที่ปกป้องชีวิตตกเป็นของเหล่าชาแมน" },
    },
    [94505] = { -- Call of Water
        title = { "13:95617857:681369801", "เสียงเรียกแห่งน้ำ" },
        objective = { "59:325326121:1029082779", "นำ Shard of Water ไปให้ Norric Lochthane ใน Loch Modan" },
        description = { "160:1701097664:1500739457", "รับเศษผลึกไป รับไปแล้วมอบชีวิต\n\nมอบชีวิตแล้วจงเข้าใจ เข้าใจว่าน้ำคือชีวิต... ความแปดเปื้อนขัดขวางชีวิต\n\nเจ้าปกป้องและมอบชีวิตด้วยพลังแห่งน้ำ" },
        progress = { "108:513052915:1475135242", "การเดินทางไป Westfall เป็นอย่างไร? ความสำเร็จที่นั่นวัดยาก แต่ชัยชนะเล็ก ๆ ก็มีน้ำหนัก" },
        completion = { { "314:1304882578:1023982132", "57:841910353:583963196 N 251:435156542:1996064778", "57:841910353:583963196 C 251:435156542:1996064778", "57:841910353:583963196 R 251:435156542:1996064778" }, "นี่คือหลักฐานที่ข้าขอ ทำได้ดี สหาย ข้าภูมิใจที่เป็นคนแรกที่แสดงความยินดีและมอบโทเทมน้ำ จงใช้อย่างมีปัญญา ขอให้โชคเดินเคียงข้าง\n\nบททดสอบถัดไปยังอีกนาน ใช้เวลานี้เรียนรู้ น้ำบริสุทธิ์รักษาได้จริง แต่ของขวัญจากมันมีมากกว่าการสมานแผล" },
        required = { [7813] = { "14:140666625:860039488", "เศษผลึกน้ำ" } },
        steps = { { "14:140666625:860039488", "เศษผลึกน้ำ" } },
    },
    [94616] = { -- Water Sapta
        title = { "11:811447847:1444598440", "น้ำศักดิ์สิทธิ์แห่งธาตุน้ำ" },
        completion = { "66:19036223:807978435 N 39:1259445020:559889539", "รับ Water Sapta แล้วไปหาน้ำบ่อที่ปนเปื้อนใน Westfall {name} ข้าเชื่อมั่นในฝีมือของเจ้า" },
        description = { "62:460331670:145263421", "ข้าเสียใจที่เจ้าต้องใช้น้ำศักดิ์สิทธิ์อีกขวด แต่เจ้าสมควรได้รับมันแล้ว" },
    },
    [94789] = { -- Call of Air
        title = { "11:1660965280:891392614", "เสียงเรียกแห่งลม" },
        objective = { "44:1905854203:1075300787", "ไปหา Veyric Thundervein ใน Arathi Highlands" },
        description = { "379:8481600:316489639", "สายลม Azeroth ต้อนรับเจ้า อีกไม่นานเจ้าจะยืนเคียงพี่น้องผู้ทรงพลังที่สุด ข้าภูมิใจที่เห็นเจ้ามาไกล อนาคตสดใสจริง ๆ\n\nธาตุลมเชี่ยวชาญยาก แต่ข้าเชื่อว่าฝีมือเจ้าจะผ่านทุกบททดสอบ\n\nมุ่งเหนือเข้า Arathi Highlands ในเนินเหนือจะพบ Veyric Thundervein เขาจะสอนเพิ่มเติม" },
        completion = { "157:898172114:375265085", "ใช่แล้ว ข้าจะมอบสิ่งที่เจ้าต้องใช้ในการควบคุมคาถาลมและเรียกเหล่าวิญญาณแห่งอากาศ รับโทเท็มนี้ไป พอพร้อมแล้วค่อยมาฝึกกับข้าต่อ" },
    },
    [96016] = { -- The Tempest's Weapons
        title = { "21:830669426:271184191", "อาวุธแห่งพายุ" },
        objective = { "80:1431185501:1670188825", "นำ Eye of the Tempest ไปให้ Bath'rah the Windwatcher ใน Alterac Mountains" },
        description = { "425:430031388:921688156", "ทำดีมาก ข้าเห็นว่าเจ้าอยากได้รางวัลแล้ว เสียใจด้วย ข้าไม่ใช่คนแคระที่มีข้าวของมากมาย\n\n<Veyric ผายมือกว้างชี้สถานที่ห่างไกลของเขา>\n\nแต่เอาอย่างนี้ ได้ยินว่าโทรลล์ชื่อ Windwatcher อยู่ใน Alterac Mountains เป็นชาแมนทรงพลังและผู้เชี่ยวชาญธาตุพายุ หากนำแก่นธาตุนั่นไป ข้าพนันว่าเขาจะทำอาวุธคู่ควรกับชัยชนะให้ได้" },
        completion = { "184:815397344:1818111632", "อา ของชิ้นนี้มีพลังมาก สหาย! ข้าไม่ได้ทำงานกับของแบบนี้มานานแล้ว\n\nดูแลมันให้ดีล่ะ ได้ยินไหม ดูท่าเจ้าจะลำบากไม่น้อยกว่าจะได้มา!" },
        progress = { "134:1576420365:1783505722", "ศึกกับเหล่าธาตุหนักเอาการเลยสินะ หืม? ทุกอย่างก็ลงเอยอย่างที่ควรเป็น\n\nไหน ๆ เจ้ามาถึงนี่แล้ว มีเรื่องอะไรถึงมาหาตาแก่ Bath'rah ล่ะ?" },
        required = { [212792] = { "18:83088727:1445732554", "ดวงตาแห่งพายุ" } },
        steps = { { "18:83088727:1445732554", "ดวงตาแห่งพายุ" } },
    },
    [96135] = { -- Heed My Call
        title = { "12:1509510998:77389090", "จงฟังเสียงเรียกข้า" },
        objective = { "60:805079116:1760194086", "ใช้ Twisted Totems เพื่อยุติพิธีของควิลบอร์" },
        description = { "438:1260439898:1411500148", "อี๋ แค่อยู่ใกล้โทเทมน่าชังพวกนี้ก็ขนลุก แต่ดีแล้ว ความแปดเปื้อนบิดเบี้ยวมากเท่านี้คือสิ่งที่ต้องใช้เรียกธาตุของควิลบอร์\n\nไป Thousand Needles เลือกจุดตั้งรับเหมาะ ๆ แอ่งไอน้ำน่าจะใช้ได้ อุดมด้วยไฟ ดิน น้ำ และลม วางโทเทมและเตรียมสู้ Razormane จะไม่พอใจที่เจ้าขัดขวาง" },
        completion = { "16:2030964395:60573826 N 114:1283418322:601234655 C 28:1330976475:1373753335", "เจ้าสัมผัสได้ไหม {name} สายลมขับขานถึงชัยชนะของเจ้า ถ้าเมื่อก่อนเหล่าธาตุยังไม่นับถือเจ้า ตอนนี้พวกเขานับถือแล้วแน่\n\nเชิดหน้าเข้าไว้ {class} เจ้าเป็นความภาคภูมิใจของคณะเรา" },
        progress = { "34:1021544539:1217662722 N 27:1358385340:356261503", "ข้ารู้สึกถึงพายุในท้อง {name} เจ้าสลายมันได้หรือยัง?" },
        required = { [212792] = { "18:83088727:1445732554", "ดวงตาแห่งพายุ" }, [268582] = { "16:1068558102:67873513", "โทเทมที่ถูกทำให้แปดเปื้อน" } },
        steps = { { "18:83088727:1445732554", "ดวงตาแห่งพายุ" }, { "16:1068558102:67873513", "โทเทมที่ถูกทำให้แปดเปื้อน" } },
    },
    [96136] = { -- Call of Air
        title = { "11:1660965280:891392614", "เสียงเรียกแห่งลม" },
        objective = { "41:1471038336:1808319472", "ไปหา Prate Cloudseer ใน Thousand Needles" },
        description = { "389:1092178057:16833133 N 1:63:63", "เจ้าคงประสบเองแล้วว่าธาตุแห่ง Azeroth ต่างจากที่ Zephras การนำพลังธรรมชาติในแดนธาตุมาใช้เป็นเรื่องหนึ่ง แต่ใช้ที่นี่ท่ามกลางโคลนตมเป็นคนละเรื่อง\n\nข้ามอบโทเทมลมให้ได้ แต่คิดว่าพบผู้ฝึกเหล่าศิษย์ที่ผูกกับแผ่นดินคนอื่นจะเป็นประโยชน์กว่า ว่าอย่างไร {name}?" },
        completion = { "174:1989815040:1883468629", "ตอนนี้ข้าจะมอบสิ่งที่เจ้าต้องใช้เพื่อรวมพลังเวทและเรียกหาวิญญาณแห่งลม รับโทเท็มนี้ไป แล้วเมื่อพร้อมก็กลับมาฝึกกับข้าต่อ" },
    },
    [96243] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "35:1433753667:2098112791", "ไปหา Teo Hammerstorm ใน Dun Morogh" },
        description = { "314:154950124:335005201", "ถึงเวลาฟังเสียงดินนานแล้ว ชาแมนผู้กล้า ธาตุสะกิดอยู่ใต้ผิวเจ้า แต่เมื่อพูดกับหิน พื้นดินจะมั่นคงทั้งใต้เท้า... และในจิตใจ\n\nไปหา Teo Hammerstorm ที่ Coldridge Valley เขาอยู่ใน Anvilmar ฐานมั่นที่สร้างด้วยค้อน ไฟ และเจตจำนง" },
        completion = { "159:505429827:1277854760", "แผ่นดินบอกข้าแล้วว่าเจ้ากำลังมา! บางครั้งไฟที่ลุกโชนภายในก็มีกำลังพาเราผ่านหิมะได้โดยไม่ต้องแตะพื้นเลย!" },
    },
    [96264] = { -- Elemental Aid
        title = { "13:595551368:218416802", "ช่วยเหลือเหล่าธาตุ" },
        objective = { "92:1419008046:1244967140", "ปราบ Charlga Razorflank ใน Razorfen Kraul และรวบรวมข้อมูลแผนของควิลบอร์" },
        description = { "331:881276964:290843143 N 170:135512984:1510532140", "ตอนนี้เป็นชาแมนคนสำคัญแล้วหรือ? เชี่ยวชาญธาตุและอยากใช้ประโยชน์? ข้าว่ามีงานเหมาะพอดี\n\nหากอยากให้ธาตุเคารพ ต้องชดใช้หนี้ พวกมันช่วยเจ้า เจ้าช่วยมัน ตอนนี้พวกมันต้องการความช่วยเหลืออย่างยิ่ง เพื่อรับมือผู้ที่ใช้พลังของมันในทางผิด\n\nแผ่นดินกำลังครืน {name} มันบอกว่าควิลบอร์รวมตัวทำพิธีพลังน่ากลัว เราต้องสำรวจรังว่าพวกมันทำอะไร นำทุกสิ่งที่พบกลับมา" },
        completion = { "247:828957578:1709941242 N 36:466026543:1142254228", "น่าสนใจ พวกควิลบอร์คิดจะท่วม Thousand Needles งั้นหรือ เจ้าพวกไร้ประโยชน์นั่นไม่เคยเคารพเหล่าธาตุ บิดเบือนพลังขนาดนี้ ถึงว่าสัมผัสได้ไกลมาถึงนี่\n\nเจ้าหาต้นตอภัยเจอ ทำได้ดี {name} แต่ตอนนี้เราต้องหยุดมัน" },
        progress = { "29:4975983:121026442", "กลับมาเร็วจัง เจออะไรบ้างล่ะ?" },
        logReady = { "66:1462696857:1947745905", "นำ Tattered Note ไปให้ Veyric Thunderhame ที่ Arathi Highlands" },
        required = { [274463] = { "13:1549383970:1052927273", "ข้อความที่ฉีกขาด" } },
        steps = { { "13:1549383970:1052927273", "ข้อความที่ฉีกขาด" } },
    },
    [92466] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "42:545174179:1693859989", "นำ Signet of Akir ไปให้ Windshaper Boro" },
        description = { "485:1338342964:124111941", "แม้ความรุ่งเรืองของเราพึ่งธาตุลมมาก วิถีที่เดินก็กำหนดให้ฟังเสียงธาตุหลักทั้งสี่และผ่านบททดสอบของแต่ละธาตุ แต่ก่อนเริ่มบทแรกอย่างจริงจัง ต้องพิสูจน์ความหนักแน่นก่อน\n\nไปแนวหินตั้งตะวันออก มีผู้พบกอง Al'Aketh Convert ที่นั่น ต้องขับไล่ จงเผชิญสาวกและนำตราของพวกมันมาหนึ่งชิ้นเป็นหลักฐาน" },
        progress = { "361:1440995918:578624295", "ลัทธิ Al'Aketh เป็นอันตรายตรงหน้าและเร่งด่วนที่สุดต่อบ้านเกิด การกระทำสุดโต่งขึ้นเรื่อย ๆ สั่นคลอนสังคมและทำลายสายสัมพันธ์กับวิญญาณลมทั้งสี่ที่อ่อนแออยู่แล้ว ธาตุเรียกร้องให้เราลงมือพิสูจน์ความทนทานและแน่วแน่ คุณลักษณะซึ่งเป็นแก่นของธาตุดิน" },
        completion = { { "149:2089347906:1187992686", "142:1573672665:800137850 N 1:46:46", "142:1573672665:800137850 C 1:46:46", "142:1573672665:800137850 R 1:46:46" }, "เจ้ากลับมาพร้อมสิ่งที่ขอ ความอดทนเด็ดเดี่ยวจึงไม่มีข้อกังขา พร้อมสำหรับก้าวต่อแล้ว สหาย" },
        required = { [251924] = { "14:66209946:1103661967", "แหวนตราแห่ง Akir" } },
        steps = { { "14:66209946:1103661967", "แหวนตราแห่ง Akir" } },
    },
    [92467] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "51:453994767:1466547588", "หา Rise of Spirits แล้วดื่ม Earth Sapta" },
        description = { "491:1185971101:989482796", "Sapta คือเครื่องดื่มผูกจิตของเรากับธาตุ น้ำยาผสานเวททำให้ผู้มีใจเด็ดเดี่ยวเห็นธาตุอย่างที่ผู้อื่นไม่เห็น จิตเจ้าจะเชื่อมกับธาตุที่ใช้ปรุง มีชาแมนเพียงไม่กี่คนรู้สูตร\n\nต้องดื่ม Sapta ในสถานที่ศักดิ์สิทธิ์เท่านั้น ห้ามที่อื่น จำไว้\n\nขึ้นทางผ่านตะวันออกไป Rise of Spirits ดื่มที่นั่น แล้ว... เจ้าจะเห็นสิ่งที่ต้องเห็นเอง", variants = { { "496:1923213115:1112704198", "Sapta คือเครื่องดื่มผูกจิตของเรากับธาตุ น้ำยาผสานเวททำให้ผู้มีใจเด็ดเดี่ยวเห็นธาตุอย่างที่ผู้อื่นไม่เห็น จิตเจ้าจะเชื่อมกับธาตุที่ใช้ปรุง มีชาแมนเพียงไม่กี่คนรู้สูตร\n\nต้องดื่ม Sapta ในสถานที่ศักดิ์สิทธิ์เท่านั้น ห้ามที่อื่น จำไว้\n\nขึ้นทางผ่านตะวันออกเฉียงเหนือไป Rise of Spirits ดื่มที่นั่น แล้ว... เจ้าจะเห็นสิ่งที่ต้องเห็นเอง" }, { "491:1156074173:1694953010", "Sapta คือเครื่องดื่มผูกจิตของเรากับธาตุ น้ำยาผสานเวททำให้ผู้มีใจเด็ดเดี่ยวเห็นธาตุอย่างที่ผู้อื่นไม่เห็น จิตเจ้าจะเชื่อมกับธาตุที่ใช้ปรุง มีชาแมนเพียงไม่กี่คนรู้สูตร\n\nต้องดื่ม Sapta ในสถานที่ศักดิ์สิทธิ์เท่านั้น ห้ามที่อื่น จำไว้\n\nขึ้นทางผ่านตะวันออกไป Rise of Spirits ดื่มที่นั่น แล้ว... เจ้าจะเห็นสิ่งที่ต้องเห็นเอง" }, { "256:658487093:1289766507 C 231:403098367:155954985", "Sapta คือเครื่องดื่มผูกจิตของเรากับธาตุ น้ำยาผสานเวททำให้ผู้มีใจเด็ดเดี่ยวเห็นธาตุอย่างที่ผู้อื่นไม่เห็น จิตเจ้าจะเชื่อมกับธาตุที่ใช้ปรุง มี{class}เพียงไม่กี่คนที่รู้สูตร\n\nต้องดื่ม Sapta ในสถานที่ศักดิ์สิทธิ์เท่านั้น ห้ามที่อื่น จำไว้\n\nขึ้นไปตามช่องเขาด้านตะวันออกเฉียงเหนือจนถึง Rise of Spirits ดื่มที่นั่น แล้ว... เจ้าจะเห็นสิ่งที่ต้องเห็นเอง" } } },
        completion = { { "509:329873250:831171303", "6:1572241333:73377271 N 497:947045941:474310399", "6:1572241333:73377271 C 497:947045941:474310399", "6:1572241333:73377271 R 497:947045941:474310399" }, "อา... สหาย... บุตรแห่งลมทั้งสี่... เจ้าแสวงหาความเข้าใจและคำตอบ ทำไมสายลมจากไป? จะนำกลับมาอย่างไร? ข้าตอบไม่ได้ เพราะไม่รู้แรงจูงใจหรือการเคลื่อนไหวของสายลม\n\nแต่สอนเรื่องดินได้มาก ทั้งกำลังและความแน่วแน่ แม้อยู่สูงกลางทะเลเมฆไม่สิ้นสุด เจ้าก็ยังเป็นชีวิตแห่งดิน หากหวังมีกำลังพอพูดกับวิญญาณลมทั้งสี่อีกครั้ง ต้องเดินเส้นทางนี้", variants = { { "6:1572241333:73377271 N 497:452269248:539902027", "อา... {name}... บุตรแห่งลมทั้งสี่... เจ้าแสวงหาความเข้าใจ เจ้าแสวงหาคำตอบ เหตุใดสายลมจึงทอดทิ้งเจ้า? เจ้าจะนำพวกมันกลับมาได้อย่างไร? ข้าตอบไม่ได้ เพราะข้าไม่รู้เจตนาหรือความเคลื่อนไหวของสายลม\n\nแต่ข้าสอนเจ้าเรื่องดินได้มาก ทั้งพละกำลังและความแน่วแน่ แม้อยู่สูงท่ามกลางทะเลเมฆไม่สิ้นสุด เจ้าก็ยังเป็นสิ่งมีชีวิตแห่งผืนดิน หากหวังจะมีกำลังพอสนทนากับวิญญาณแห่งลมทั้งสี่อีกครั้ง นี่คือทางที่เจ้าต้องเดิน" } } },
    },
    [92468] = { -- Call of Earth
        title = { "13:1027917325:1822789743", "เสียงเรียกแห่งดิน" },
        objective = { "60:122598469:541047794", "นำ Rough Quartz ไปให้ Windshaper Boros ใน Thendal Grove" },
        description = { "324:82895307:2078894289 N 156:1369451172:1657466587", "รับ Rough Quartz นี้ไปให้ผู้ที่เจ้าเรียก Windshaper Boro เป็นหลักฐานว่าเราพบกัน เขาจะสร้างโทเทมให้ โดยใช้เศษนี้เป็นหัวใจ แม้ดูเล็ก เจ้าจะพบว่าขนาดไม่สำคัญ และสิ่งเล็กที่สุดก็อาจอยู่ได้นานกว่าสิ่งอื่นมากมาย\n\nจงอดทน {name} เข้มแข็งและแสวงหาปัญญา นี่คือสิ่งที่ธาตุขอ สุดท้ายเจ้าจะเป็นหนึ่งเดียวกับดิน จงเคารพมันเช่นเดียวกับที่มันเคารพเจ้า" },
        progress = { "349:1785982466:762678737", "เจ้าจะได้เรียนรู้ว่าวิถีเราไม่เรียบง่ายอย่างที่ดู แม้แสวงหาเสียงไว้พูดกับวิญญาณลม ลมก็เป็นเพียงหนึ่งในพลังธาตุของโลก มีแต่ความเข้าใจและหวังว่าจะเชี่ยวชาญธาตุทั้งสี่เท่านั้น จึงจะได้เสียงคืนมาร้องเพลงแห่งลมอีกครั้ง" },
        completion = { { "413:203637184:1179081238", "80:539506798:1725146043 N 323:686246046:216501294", "80:539506798:1725146043 C 323:686246046:216501294", "80:539506798:1725146043 R 323:686246046:216501294" }, "ดีมาก!\n\nโทเทมที่ข้าจะสร้างเป็นมากกว่าเครื่องหมายฐานะในหมู่นักผจญภัย มันมีพลังยิ่งกว่านั้น ประโยชน์หนึ่งคือรวมพลังคาถาที่เชื่อมกับดิน เมื่อมีปัญญามากขึ้น พลังดินก็จะเปิดให้เจ้าใช้มากขึ้น\n\nครูฝึกจะรู้เมื่อเจ้าพร้อมรับความรู้ที่สูงกว่า\n\nแต่ตอนนี้ รับโทเทมดินนี้ไปก่อน..." },
        required = { [6656] = { "12:2047988926:1690463399", "ควอตซ์หยาบ" } },
        steps = { { "12:2047988926:1690463399", "ควอตซ์หยาบ" } },
    },
    [92460] = { -- Coming of Age
        title = { "13:516424323:1110052198", "ก้าวสู่วัยผู้ใหญ่" },
        objective = { "49:1504668469:1561524821", "คุยกับ Rorian the Dayseeker ใน Thendal Grove" },
        description = { "411:1050441679:902902761", "ดูเจ้าสิ ดวงตาสดใส พร้อมผจญภัย! Thendal Village ต้องการความช่วยเหลือทุกแรง การมาของเจ้าจึงน่ายินดี คงตื่นเต้นกังวลกับสิ่งข้างหน้าไม่น้อย เพราะชีวิตหนึ่งมีโอกาสก้าวสู่วัยผู้ใหญ่เพียงครั้งเดียว\n\nไปหา Rorian the Dayseeker ผู้นำหมู่บ้านที่ทางเข้าต้นบรรพพฤกษ์ใหญ่ทางตะวันตก เขาจะช่วยให้เจ้าเริ่มเดินทาง", variants = { { "461:205127353:1945121007", "ดูเจ้าสิ ตาเป็นประกาย พร้อมออกผจญภัยแล้ว! พวกเรารอเจ้ามาถึงและหวังจะได้แรงช่วยที่ Thendal Village ข้าคิดว่าเจ้าคงทั้งประหม่าและตื่นเต้นกับสิ่งที่รออยู่ ก็พิธีบรรลุนิติภาวะมีเพียงครั้งเดียวในชีวิตนี่นะ\n\n<Ailee ยิ้มให้อย่างอ่อนโยน>\n\nไปหา Rorian the Dayseeker ผู้นำหมู่บ้านของเราที่ทางเข้าต้นไม้บรรพชนใหญ่ทางตะวันตกจากตรงนี้ เขาจะช่วยให้เจ้าเริ่มออกเดินทาง" } } },
        completion = { "503:1858133600:633856186", "ขอสายลมทักทาย สหาย ข้าเป็นเกียรติที่มอบวัตถุมงคลแห่งการก้าวสู่วัยผู้ใหญ่ในวันนี้ เพื่อยอมรับศักยภาพที่เจ้าจะนำมาสู่ Shen'dorei ประวัติศาสตร์ซับซ้อนของเราเต็มด้วยความลำบากและการกดขี่\n\nวัตถุมงคลนี้เป็นหนึ่งในหลายชิ้นที่ผู้มาก่อนเคยถือครอง สักวันเมื่อเถ้าของเจ้ากระจายตามสายลม มันจะส่งต่อให้อีกคนสืบธรรมเนียม\n\nเมื่อพกมันไป จงรู้ว่าสายลมจากบ้านจะอยู่กับเจ้าไม่ว่าจะเดินทางที่ใด", variants = { { "18:299148129:1387303313 N 479:1594091485:1979377491", "ขอสายลมทักทาย {name} ข้าเป็นเกียรติที่มอบวัตถุมงคลแห่งการก้าวสู่วัยผู้ใหญ่ในวันนี้ เพื่อยอมรับศักยภาพที่เจ้าจะนำมาสู่ Shen'dorei ประวัติศาสตร์ซับซ้อนของเราเต็มด้วยความลำบากและการกดขี่\n\nวัตถุมงคลนี้เป็นหนึ่งในหลายชิ้นที่ผู้มาก่อนเคยถือครอง สักวันเมื่อเถ้าของเจ้ากระจายตามสายลม มันจะส่งต่อให้อีกคนสืบธรรมเนียม\n\nเมื่อพกมันไป จงรู้ว่าสายลมจากบ้านจะอยู่กับเจ้าไม่ว่าจะเดินทางที่ใด" } } },
    },
    [92461] = { -- Harmony in Balance
        title = { "18:1219737775:774296404", "สมดุลแห่งความกลมกลืน" },
        objective = { "42:759844471:155687045", "สังหาร Vuldren Juveniles 8 ตัวใน Thendal Grove" },
        description = { "480:1326564906:1268975771", "ชนเผ่าเราอยู่ในยุคไม่แน่นอนอย่างยิ่ง เผชิญความท้าทายที่ไม่เคยมีมาก่อน ซึ่งอาจต้องแก้ด้วยวิธีหาญกล้า แต่ก็ยังต้องจัดการเรื่องธรรมดาใน Thendal Grove เช่นจำนวน Vuldren ที่เพิ่มจนไม่ยั่งยืน\n\nVuldren สำคัญต่อระบบนิเวศ แต่ต้องแก้ความไม่สมดุลเพื่อรักษาความกลมกลืนอันเปราะบางของทุกชีวิตใน Thendal Grove\n\nมุ่งตะวันออกไปลดจำนวนพวกมันบางส่วน" },
        progress = { "188:1431821231:2018414749", "แม้การต้องลดจำนวนสิ่งมีชีวิตจะไม่น่าพอใจ การชี้นำเช่นนี้ก็จำเป็นเพื่อป้องกันหายนะในบ้านเกิด เป็นบทเรียนสำคัญที่คนเช่นเจ้าต้องเรียนรู้" },
        completion = { "266:979646430:1644572859", "ขอบคุณที่รับใช้ Zephras นักผจญภัยน้อย\n\nปกติ Vuldren เชื่องทีเดียว แต่สัตว์ที่อาศัยใน Zephras สัมผัสได้เมื่อเวทในสายลมเสียสมดุล หากปล่อยไว้ อาจมีพฤติกรรมอันตรายและคาดเดาไม่ได้", variants = { { "45:558705483:279846173 C 211:497756268:1836630003", "ขอบคุณที่รับใช้ Zephras {class}น้อย\n\nปกติ Vuldren เชื่องทีเดียว แต่สัตว์ที่อาศัยใน Zephras สัมผัสได้เมื่อเวทในสายลมเสียสมดุล หากปล่อยไว้ อาจมีพฤติกรรมอันตรายและคาดเดาไม่ได้" } } },
        objectiveLabels = {
            monster = { ["Juvenile Vuldren slain"] = "ปราบ Vuldren วัยอ่อน" },
        },
    },
    [92462] = { -- Infestation Investigation
        title = { "25:522495068:839073401", "สืบสวนการระบาด" },
        objective = { "42:1426389943:1409255467", "สังหาร Pesky Cirrusflies 8 ตัวใน Thendal Grove" },
        description = { "244:1538964118:468023547", "เรนเจอร์คนหนึ่งเพิ่งรายงานการระบาดของ Cirrusfly ใน Thendal Grove\n\nหากปล่อยให้ฝูงโตเกินไป มันจะเป็นอันตราย โปรดไปปลายตะวันออกของป่าและกำจัดให้มากเท่าที่ทำได้" },
        progress = { "125:1320987766:124401708", "ปล่อยให้แมลงรบกวนตั้งรกรากในป่าสงบของเราไม่ได้ หากไม่ควบคุม การระบาดจะอันตรายอย่างรวดเร็ว" },
        completion = { "87:1406668302:916836065", "ดูจากไส้แมลงที่เลอะตัวเจ้า การระบาดครั้งนี้คงหนักไม่น้อย" },
        objectiveLabels = {
            monster = { ["Pesky Cirrusfly slain"] = "ปราบ แมลง Cirrusfly จอมกวน" },
        },
    },
    [92463] = { -- The Cirrusfly Queen
        title = { "19:1317461255:509278853", "ราชินี Cirrusfly" },
        objective = { "45:1940490306:1142856682", "กำจัด Cirrusfly Queen ใน Thendal Grove" },
        description = { "347:43899883:364358791", "หากแมลงเต็มป่าอย่างที่ว่า ฆ่าแค่ตัวงานคงไม่พอ\n\nเข้าไปลึกกว่าเดิมเพื่อหาราชินี นางจะอยู่ใกล้รัง ล้อมด้วยทหารตัวใหญ่ก้าวร้าวกว่า ระวังด้วย\n\nกำจัดแล้วกลับมา จะได้มีเรื่องให้กังวลน้อยลงอีกอย่าง" },
        progress = { "151:803573850:945126448", "ดูเบา Cirrusfly ไม่ได้ อาจดูไม่อันตราย แต่ต้องระวังตัวใหญ่ ยิ่งใหญ่ยิ่งดุ!" },
        completion = { "107:1774828985:1289770851", "ทำดีมาก สหาย หากเส้นทางนักผจญภัยไม่รุ่ง เจ้าก็เป็นเรนเจอร์ชั้นเยี่ยมได้", variants = { { "16:1549935302:71513149 N 85:1917239843:1560637464", "ทำดีมาก {name} หากเส้นทางนักผจญภัยไม่รุ่ง เจ้าก็เป็นเรนเจอร์ชั้นเยี่ยมได้" } } },
        objectiveLabels = {
            monster = { ["Cirrusfly Queen slain"] = "ปราบ ราชินี Cirrusfly" },
        },
    },
    [92464] = { -- Elemental Unrest
        title = { "16:1124325993:863945662", "ธาตุไม่สงบ" },
        objective = { "47:1520921710:665144534", "คุยกับ Yala Windwatcher ใน Thendal Grove", variants = { { "43:305762195:934357052", "คุยกับ Yala Windwatcher ใน Thendal Grove" } } },
        description = { "504:341936392:1201888683", "ตั้งแต่ผู้เกื้อหนุนแห่งธาตุจากไป เราดูจะผ่านความไม่สงบอย่างหนึ่งไปเจออีกอย่าง ตอนนี้ร่างสำแดงสายลมใกล้แนวหินตั้งทางตะวันออกเฉียงเหนือกำลังปั่นป่วน\n\nภูตเล็กเหล่านี้ไม่ได้ตระหนักรู้ตนอย่างแท้จริงเหมือนวิญญาณลมมีสติที่เคยอยู่ที่นี่ พวกมันเพียงตอบสนองต่อพลัง อารมณ์ และเจตนาของชีวิตรอบตัว\n\nYala Windwatcher ศิษย์ข้าไปเฝ้าสังเกต จงไปหาและฟังว่านางรู้อะไรบ้าง" },
        completion = { "44:1009299193:1722619804", "Rorian ส่งมาหรือ? ดี ข้าต้องการความช่วยเหลือพอดี" },
        objectiveLabels = {
            event = { ["Learn more about the agitated winds."] = "สืบให้รู้เพิ่มว่าสายลมกำลังปั่นป่วนเพราะอะไร" },
        },
    },
    [92465] = { -- Agitators
        title = { "9:305939296:1947413377", "ผู้ปลุกปั่น" },
        objective = { "62:1389169425:1565331395", "สังหาร Roiling Winds 6 ตนและ Al'Aketh Converts 7 คนใน Thendal Grove", amount = { "5:1000000866:1065647852 W2 19:1701751943:1974838964 W1 36:1001170267:946373935", "สังหาร Roiling Winds {world2} ตนและ Al'Aketh Converts {world1} คนใน Thendal Grove" } },
        description = { "379:336408075:1289786499 C 1:63:63", "ลัทธิ Al'Aketh เป็นภัยร้ายต่อเกาะ สาวกพวกนี้ต้องเป็นผู้ปลุกปั่นภูตลมเล็กที่นี่ให้รุนแรงแน่นอน\n\nน่าเสียดาย เราต้องสลายสายลมปั่นป่วนก่อนมันทำร้ายใคร และส่งสารชัดเจนให้ลัทธิรู้ว่าป่าไม่ต้อนรับ\n\nเจ้าจะช่วยข้าหรือไม่ {class}?" },
        completion = { "79:2080358439:1679485613", "ข้าเจ็บปวดที่ต้องหลั่งเลือด Shen'dorei ในป่านี้ แต่เราทำสิ่งที่จำเป็น" },
        progress = { "11:1082766384:663732441", "เสร็จแล้วหรือ?" },
        steps = { { "23:1747062739:1974122328", "ทำลาย Roiling Winds" } },
        objectiveLabels = {
            monster = { ["Al'Aketh Convert slain"] = "ปราบ ผู้เปลี่ยนมานับถือ Al'Aketh" },
        },
    },
    [92469] = { -- Return to Rorian
        title = { "16:1664335143:1667646888", "กลับไปหา Rorian" },
        objective = { "68:2103088591:74276182", "นำข่าว Al'Aketh ไปบอก Rorian the Dayseeker ใน Thendal Grove" },
        description = { "25:1236945334:1541537319 C 143:2081451885:1815700786", "เจ้าช่วยที่นี่พอแล้ว {class} ข้าจะอยู่จัดการพวกที่ตกค้างข้างล่างเอง\n\nกลับหมู่บ้านไปบอก Rorian ว่าลัทธิมาอยู่ที่นี่ เขาคงไม่พอใจ" },
        completion = { "341:213509933:411691133", "น่ากังวลยิ่ง แต่น่าเสียดายที่ไม่น่าแปลก เรารู้การเคลื่อนไหวของลัทธิมาพักหนึ่ง แต่เลือกเฝ้าดูห่าง ๆ การปลุกปั่นวิญญาณลมใกล้แนวหินตั้งแสดงชัดว่าพวกมันยกระดับแล้ว\n\nเจ้าทำงานยากแต่จำเป็นให้ Thendal Grove ขอบคุณ สหาย", variants = { { "323:2078699646:2098564004 N 12:513407318:1685728707", "น่ากังวลยิ่ง แต่น่าเสียดายที่ไม่น่าแปลก เรารู้การเคลื่อนไหวของลัทธิมาพักหนึ่ง แต่เลือกเฝ้าดูห่าง ๆ การปลุกปั่นวิญญาณลมใกล้แนวหินตั้งแสดงชัดว่าพวกมันยกระดับแล้ว\n\nเจ้าทำงานยากแต่จำเป็นให้ Thendal Grove ขอบคุณ {name}" } } },
    },
    [92470] = { -- Foul Matriarch
        title = { "14:252247667:1307160729", "แม่ฝูงอันชั่วร้าย" },
        objective = { "91:212336789:2096871905", "สังหาร Ursera Scavengers 8 ตัว และเก็บหัวแม่ฝูง Urs'anah ใน Thendal Grove" },
        description = { "388:801685592:2035536743", "Rorian บอกแล้วว่าข้าจับตาดูเจ้า ข้าขอเสนอบททดสอบความเด็ดเดี่ยว แต่เตือนไว้ มันจะพาเข้าสู่อันตรายใหญ่หลวง\n\nไปถ้ำตะวันตก ลดจำนวน Ursera และหาแม่ฝูงที่เรนเจอร์เรียก Urs'anah กำจัดแล้วนำหลักฐานกลับมา เมื่อทำได้ เจ้าจะก้าวสำคัญบนเส้นทางของตน", variants = { { "389:497182363:764400170", "Rorian บอกแล้วว่าข้าจับตาดูเจ้า ข้าขอเสนอบททดสอบความเด็ดเดี่ยว แต่เตือนไว้ มันจะพาเข้าสู่อันตรายใหญ่หลวง\n\nไปถ้ำใต้ ลดจำนวน Ursera และหาแม่ฝูงที่เรนเจอร์เรียก Urs'anah กำจัดแล้วนำหลักฐานกลับมา เมื่อทำได้ เจ้าจะก้าวสำคัญบนเส้นทางของตน" } } },
        progress = { "151:172383079:822513132", "สิ่งที่ขอไม่ง่าย แต่เจ้าต้องพร้อมรับความท้าทายใหญ่กว่านี้อีกมาก หากจะอยู่รอดนานพอรับใช้ Zephras Isle" },
        completion = { "179:241298817:420992307", "ทำดีมาก เจ้าล้มสัตว์ร้ายและสาวกลัทธิผู้บุกรุก แสดงแววยอดเยี่ยม แต่ไม่นานเส้นทางต้องพาออกจากความปลอดภัยที่ยังพอมีใน Thendal Village" },
        required = { [252665] = { "16:1495659237:464880909", "หัวของ Urs'anah" } },
        steps = { { "16:1495659237:464880909", "หัวของ Urs'anah" } },
        objectiveLabels = {
            monster = { ["Ursera Scavenger slain"] = "ปราบ Ursera นักคุ้ยซาก" },
        },
    },
    [92471] = { -- Aetheen of the Gales
        title = { "20:1720674074:1542673298", "Aetheen แห่งสายลม" },
        objective = { "49:702361577:2031158394", "คุยกับ Aetheen of the Gales ใน Thendal Grove" },
        description = { "448:580546366:648998308", "เจ้าอาจไม่รู้ แต่ทุกสิ่งที่ทำเป็นบททดสอบ เตรียมรับสิ่งข้างหน้า เกาะนี้กว้างใหญ่ Zephras ต้องการนักผจญภัยหนุ่มสาวมีใจสู้เช่นเจ้า หากเราจะรอดจากความท้าทายของชนเผ่า\n\nAetheen of the Gales คือหนึ่งในผู้นำเราบน Zephras Isle นางเฝ้าดูและมีงานให้เจ้าทำ จงคุยกับนางเพื่อรู้เพิ่มเติม" },
        completion = { "356:871539908:305206200", "Rorian เล่าเรื่องเจ้าให้ฟังมาก เจ้าอาจไม่รู้จักข้า ข้าเป็นสมาชิก Council of Elders บน Zephras Isle มาที่ Thendal Grove เพื่ออ่านกระแสลม และประเมิน Shen'dorei หนุ่มสาวเช่นเจ้าที่กำลังก้าวสู่วัยผู้ใหญ่\n\nบอกข้าสิ พร้อมก้าวต่อหรือยัง? พร้อมรับใช้ Zephras Isle หรือไม่?" },
    },
    [92472] = { -- The Next Step
        title = { "13:1026032423:279467277", "ก้าวถัดไป" },
        objective = { "46:1827495514:917409935", "รายงานตัวต่อ Constable Aonda ใน Shen'dar Village" },
        description = { "486:1253495007:217488194", "ภัยที่แพร่หลายที่สุดอย่างหนึ่งบน Zephras Isle คือลัทธิ Al'Aketh พวกคลั่งศาสนาที่บูชาผู้ถูกอ้างว่าเป็นเจ้าแห่งธาตุผู้ปกครอง Skywall นั่นคือ Al'Akir the Windlord พวกมันโหดเหี้ยม มุ่งมั่นเพียงสิ่งเดียว พลังและความทะเยอทะยานอันตรายขึ้นทุกวัน\n\nเส้นทางจะพาเจ้าไป Shen'dar Village ทางใต้ เมื่อถึงให้รายงานตัวต่อ Constable Aonda ลัทธิคุกคามหมู่บ้านและพวกเขาต้องการความช่วยเหลือ บอกว่าข้าส่งไป", variants = { { "486:1616202169:2054215177", "ภัยที่แพร่หลายที่สุดอย่างหนึ่งบน Zephras Isle คือลัทธิ Al'Aketh พวกคลั่งศาสนาที่บูชาผู้ถูกอ้างว่าเป็นเจ้าแห่งธาตุผู้ปกครอง Skywall นั่นคือ Al'Akir the Windlord พวกมันโหดเหี้ยม มุ่งมั่นเพียงสิ่งเดียว พลังและความทะเยอทะยานอันตรายขึ้นทุกวัน\n\nเส้นทางจะพาเจ้าไป Shen'dar Village ทางใต้ เมื่อถึงให้รายงานตัวต่อ Constable Aonda ลัทธิคุกคามหมู่บ้านและพวกเขาต้องการความช่วยเหลือ บอกว่าข้าส่งไป" } } },
        completion = { "166:1604947759:1975253394", "Aetheen ส่งเจ้ามาหรือ? ยอมรับว่าเจ้าดูไม่เท่าไรในสายตาข้า แต่ Shen'dar Village ไม่ปฏิเสธคนเต็มใจช่วย ยิ่งเป็นคนที่ Elder Aetheen ส่งมาเองด้วย" },
    },
    [92473] = { -- Aggressive Encroachment
        title = { "23:590909251:605015306", "การรุกล้ำอันก้าวร้าว" },
        objective = { "68:2110967571:215080310", "รวบรวม Scrawny Ursera Claws 6 ชิ้นจาก Scrawny Ursera ใน Thendal Grove" },
        description = { "494:2070318167:860710437", "รัง Ursera ทางตะวันตกเฉียงใต้กลายเป็นปัญหาอย่างรวดเร็ว แค่สัปดาห์ก่อนเรนเจอร์ต้องฆ่าตัววัยรุ่นที่หลงใกล้หมู่บ้านและพยายามทำร้ายเด็กชายซึ่งเล่นอยู่ใต้ต้นไม้ผู้เฒ่ากลางหมู่บ้าน\n\nโชคดีที่เด็กรอด ความหิวสิ้นหวังทำให้สัตว์พวกนี้อันตรายเกินปล่อยไว้ ไปใต้แล้วกำจัดตัวผอมแห้งที่สุด นำกรงเล็บเป็นหลักฐานกลับมาเมื่อเสร็จ" },
        progress = { "109:1481219063:805262388", "ช่วงนี้ Ursera ก้าวร้าวขึ้นมาก สงสัยว่ามีอะไรเปลี่ยนไปจนพฤติกรรมเป็นเช่นนี้?" },
        completion = { "65:1767337364:1091883295", "ทำดีมาก นักผจญภัย Rangers of the Grove เป็นหนี้เจ้าแล้ว", variants = { { "11:534428891:784080240 C 44:236591250:22928355", "ทำดีมาก {class} Rangers of the Grove เป็นหนี้เจ้าแล้ว" } } },
        required = { [251918] = { "19:1621612561:817411254", "กรงเล็บ Ursera ผอมโซ" } },
        steps = { { "19:1621612561:817411254", "กรงเล็บ Ursera ผอมโซ" } },
    },
    [92474] = { -- Falling With Style
        title = { "18:1523841940:377777940", "ร่วงหล่นอย่างมีชั้นเชิง" },
        objective = { "104:2046820395:1658102965", "กระโดดจากยอดหอเฝ้าระวังใน Thendal Grove แล้วใช้ความสามารถ Walk on Air เพื่อชะลอการตก" },
        description = { "18:1476347543:1419582884 N 422:393088033:1094618782", "สวัสดี {name}! เล่นเกมกันไหม?\n\nแค่ขึ้นไปยืนบนขอบนั้น... แล้วกระโดด! ใช้พรสวรรค์เดินบนอากาศชะลอการตก ดูว่าจะลอยไปข้างหน้าได้ไกลเท่าไร\n\nกติกาตั้งกันเอง คะแนนก็ไม่สำคัญ แต่ได้คะแนนพิเศษหากลงตรงหน้า Rorian the Dayseeker ให้เขาตกใจ! เขาคงไม่ชอบ แต่ข้าจะหัวเราะสะใจถ้าเจ้าทำให้เขาหัวเสียได้! ฮ่า!" },
        progress = { "94:691408117:1266741793", "การเดินบนอากาศช่วยให้เจ้าพ้นปัญหา... และ เอ่อ... ก่อปัญหาได้สารพัด!", variants = { { "94:1733759649:711221523", "การเดินบนอากาศช่วยให้เจ้าพ้นปัญหา... และ เอ่อ... ก่อปัญหาได้สารพัด!" } } },
        completion = { "400:1199965747:917815964", "ข้าต้องบอก Myriaal อีกกี่ครั้งว่าอย่ายุให้คนอื่นใช้พรของ Skyborne อย่างบุ่มบ่าม!\n\nถึงอย่างนั้น ข้าว่าฝึกสักนิดในที่ค่อนข้างปลอดภัยอย่างหมู่บ้านก็... ยอมรับได้\n\nต่อไปขอให้ใช้ความสามารถอย่างรอบคอบ อย่าใช้เวทหมดโดยไม่คิด จนใช้ไม่ได้ในเวลาที่ต้องการจริง ๆ", variants = { { "400:1247382098:1947938247", "ข้าต้องบอก Myriaal อีกกี่ครั้งว่าอย่ายุให้คนอื่นใช้พรของ Skyborne อย่างบุ่มบ่าม!\n\nถึงอย่างนั้น ข้าว่าฝึกสักนิดในที่ค่อนข้างปลอดภัยอย่างหมู่บ้านก็... ยอมรับได้\n\nต่อไปขอให้ใช้ความสามารถอย่างรอบคอบ อย่าใช้เวทหมดโดยไม่คิด จนใช้ไม่ได้ในเวลาที่ต้องการจริง ๆ" }, { "400:1247382098:1947938247", "ข้าต้องบอก Myriaal อีกกี่ครั้งว่าอย่ายุให้คนอื่นใช้พรของ Skyborne อย่างบุ่มบ่าม!\n\nถึงอย่างนั้น ข้าว่าฝึกสักนิดในที่ค่อนข้างปลอดภัยอย่างหมู่บ้านก็... ยอมรับได้\n\nต่อไปขอให้ใช้ความสามารถอย่างรอบคอบ อย่าใช้เวทหมดโดยไม่คิด จนใช้ไม่ได้ในเวลาที่ต้องการจริง ๆ" }, { "95:3850744:934345530 R 297:640447948:1386538407", "ข้าต้องบอก Myriaal อีกกี่ครั้งว่าอย่ายุให้คนอื่นใช้พรของ {race} อย่างบุ่มบ่าม!\n\nถึงอย่างนั้น ข้าว่าฝึกสักนิดในที่ค่อนข้างปลอดภัยอย่างหมู่บ้านก็... ยอมรับได้\n\nต่อไปขอให้ใช้ความสามารถอย่างรอบคอบ อย่าใช้เวทหมดโดยไม่คิด จนใช้ไม่ได้ในเวลาที่ต้องการจริง ๆ" } } },
    },
    [92514] = { -- Welcome to Shen'dar Village
        title = { "27:760749961:1746885918", "ยินดีต้อนรับสู่ Shen'dar Village" },
        objective = { "72:824705538:1888274473", "คุยกับ Illaya Amberwind และ Coriella Calmbreeze ใน Shen'dar Village" },
        description = { "459:919826200:166596844", "เจ้ามีกลิ่นอาย Windshaper อยู่ เวลาอยู่ใกล้ผู้ถูกวิญญาณสัมผัส ข้ารู้สึกเหมือนไฟฟ้าสถิตนิด ๆ บนผิว นั่นทำให้รู้ ก่อนมอบงานจริงจัง ควรไปรายงานตัวต่อผู้อาวุโส Windshaper ของเรา Illaya Amberwind นางอยู่ข้างนอกใกล้ใจกลางเมือง\n\nอ้อ คุยกับ Coriella Calmbreeze ด้วย นางดูแลโรงเตี๊ยม จัดที่พักและเสบียงให้ได้หากต้องการ" },
        completion = { "405:801126999:10648089", "ไปหา Illaya แล้วหรือ? ดี ช่วงนี้ High Order กับ Windshaper ตึงเครียดมาก แต่ที่ Shen'dar ยังวางตัวสุภาพต่อกัน ทุกคนรู้ว่ามีปัญหาใหญ่กว่าเรื่องเถียงของพวกเขา\n\nเมื่อเรียบร้อย เจ้าดูเหมือนอยากหางานลงมือทำ ข้ามีปัญหาโจรที่หวังให้ช่วย" },
        progress = { "37:404659111:642332454", "ที่นี่อาจไม่มีอะไรนัก แต่ก็เป็นบ้านของเรา" },
        steps = { { "27:1748710551:1292939561", "คุยกับ Illaya Amberwind" }, { "24:1373067652:631297336", "คุยกับเจ้าของโรงเตี๊ยม" } },
    },
    [92515] = { -- The Problem With Prideclaws
        title = { "27:605443670:547731964", "ปัญหา Prideclaw" },
        objective = { "69:2044440386:628762313", "รวบรวม Prideclaw Pelts 10 ผืนจาก Prideclaw ใน Shen'dar Highlands" },
        description = { "459:2146465520:1967815687", "เหมือนแค่โจรกับสาวกคลั่งยังไม่พอ ตอนนี้ Prideclaw เต็มเนินเขา เริ่มรุกขอบหมู่บ้านและกล้าขึ้นทุกวัน อีกไม่นานคงมีสัตว์เลี้ยงหรือเด็กถูกคาบไป ลดจำนวนตอนนี้ย่อมเมตตากว่ารอเกิดโศกนาฏกรรม\n\nนำหนังมาสักโหล ข้าแปรเป็นของสารพัดที่ช่วยหมู่บ้านได้" },
        progress = { "146:1316745166:1918844672", "ถ้าถามข้า ข้าว่า Prideclaw ก็น่ารักอยู่... เมื่อดูห่าง ๆ อย่างปลอดภัย และแน่นอน ต้องยืนหลังคนถือดาบด้วย", variants = { { "146:164920271:389278057", "ถ้าถามข้า ข้าว่า Prideclaw ก็น่ารักอยู่... เมื่อดูห่าง ๆ อย่างปลอดภัย และแน่นอน ต้องยืนหลังคนถือดาบด้วย" } } },
        completion = { "47:466983242:362251906", "ข้าไม่ได้บอกว่าเป็นงานสะอาดเสียหน่อย จริงไหม?" },
        required = { [252670] = { "14:896144518:2077291067", "หนัง Prideclaw" } },
        steps = { { "14:896144518:2077291067", "หนัง Prideclaw" } },
    },
    [92516] = { -- Hippogryph Harrassment
        title = { "22:246049561:532713331", "ฮิปโปกริฟก่อกวน", variants = { { "21:800105391:1949523011", "ฮิปโปกริฟก่อกวน" } } },
        objective = { "103:1046179346:1092764643", "สังหาร Hippogryph Youths 8 ตัว, Hippogryph Protectors 6 ตัว และ Hippogryph Matriarch ใน Shen'dar Highlands" },
        description = { "211:283339037:100317864", "ฮิปโปกริฟฝูงหนึ่งเพิ่งทำรังทางตะวันออกเฉียงใต้ของ Shen'dar Village และก่อความวุ่นวายให้คนเดินถนน ข้าต้องการคนไปลดจำนวนให้เรา" },
        completion = { "47:1190054287:524666957", "ทำดีและรวดเร็วด้วย ไม่เลวเลย" },
        progress = { "218:531821448:440296125", "ฮิปโปกริฟเป็นสัตว์ที่หยิ่งทะนง เสียงจากขบวนเกวียนคงทำให้พวกมันตื่นจนเข้าโจมตี ไม่ว่าสาเหตุจะเป็นอะไร เราจะปล่อยผ่านเรื่องที่คนในขบวนถูกฆ่าไม่ได้" },
        objectiveLabels = {
            monster = { ["Hippogryph Youth slain"] = "ปราบ ฮิปโปกริฟวัยอ่อน", ["Hippogryph Protector slain"] = "ปราบ ฮิปโปกริฟผู้พิทักษ์", ["Hippogryph Matriarch slain"] = "ปราบ แม่ฝูงฮิปโปกริฟ" },
        },
    },
    [92517] = { -- The Criminal Element
        title = { "20:67042896:1995631602", "พวกนอกกฎหมาย" },
        objective = { "87:616667052:1843012778", "ฆ่า Highlands Bandits 10 คนและหัวหน้า Badwind Bennic ใน Shen'dar Highlands" },
        description = { "497:378408446:813299663", "มีถ้ำไม่ไกลทางเหนือซ่อนหลังน้ำตก ข้ารู้ดีว่ากลุ่มโจรใช้เป็นฐาน ก่อนลัทธิมาพวกมันก็เป็นปัญหา แต่ตอนนี้น่าหวาดกลัวจริง ๆ น่าเสียดายที่ข้าแบ่งคนไปกวาดล้างไม่ได้\n\nข้าต้องการให้เจ้าไปจัดการ ฆ่าให้มากเท่าที่ทำได้ หากเป็นไปได้ก็เก็บหัวหน้าที่เรียก Badwind Bennic ด้วย ถ้ำอันตราย ระวังให้ดี" },
        completion = { "297:47320902:177457227", "โจรกระจัดกระจายไปแล้ว เรามีปัญหาน้อยลงอีกอย่าง แต่ยอมรับว่าตอนนี้กังวลว่าผู้รอดอาจหันไปขอการคุ้มครองจากลัทธิ ยิ่งเพิ่มจำนวนที่น่าตกใจอยู่แล้ว\n\nถึงอย่างไร เราก็รับชัยชนะเท่าที่หาได้" },
        progress = { "177:975982975:1052360153", "น่าเศร้าที่ชาว Shen'dorei หันมาปล้นคนของตัวเองเพื่อเอาตัวรอด แต่ข้างนอกนั่นยิ่งสิ้นหวังขึ้นทุกทีตั้งแต่เสาค้ำพลังเริ่มใช้การไม่ได้" },
        objectiveLabels = {
            monster = { ["Highlands Bandit slain"] = "ปราบ โจรที่ราบสูง", ["\"Badwind\" Bennic slain"] = "ปราบ Bennic ฉายา “Badwind”" },
        },
    },
    [92528] = { -- Among the Faithful
        title = { "18:1235119393:1065047654", "ท่ามกลางผู้ศรัทธา" },
        objective = { "91:266188511:1090469366", "สำรวจ Falaath Village เพื่อเรียนรู้เจตนาของลัทธิใน Shen'dar Highlands" },
        description = { "464:635866585:914521740", "ผู้ศรัทธา Al'Akir แข็งแกร่งขึ้นทุกครั้งที่มีผู้สมัครกระตือรือร้นอย่างเจ้า เห็นไหม พลังของเราทำให้พายุก่อรูปร่างได้เอง!\n\nปกติข้าจะส่งไปให้ Skypriest Aanders ประเมินทันที แต่ตอนนี้เขารับแขกที่โรงเตี๊ยมฝั่งเหนือของเมือง อย่าไปที่นั่นก่อน ผู้สมัครหนวดเครารุงรังเช่นเจ้าไม่เหมาะปรากฏต่อแขกเช่นนั้น\n\nตอนนี้แค่อย่าไปเกะกะใครก็พอ" },
        completion = { "464:1289876135:548228774", "Lorthuna อยู่ที่นั่นเองหรือ? นางเป็นหัวหน้าลัทธิบัดซบทั้งหมด!\n\nถ้าพวกมันจะเล่นงาน Shen'dar Village กับหอเฝ้าระวังตะวันตก เราต้องพร้อม แต่ที่แปลกคือ... ทำไมหอ?\n\nหมู่บ้านข้าเข้าใจ แต่หอนั่น? แทบไม่มีคุณค่าทางยุทธศาสตร์ นอกจากเป็นจุดสังเกตเล็ก ๆ\n\nอย่างไรเราจะเตรียมพร้อม พวกมันจะรู้ว่าชาวที่สูงไม่ได้ถูกจู่โจมจนตั้งตัวไม่ทันง่ายอย่างที่คิด", variants = { { "464:869889295:1382545249", "Lorthuna อยู่ที่นั่นเองหรือ? นางเป็นหัวหน้าลัทธิบัดซบทั้งหมด!\n\nถ้าพวกมันจะเล่นงาน Shen'dar Village กับหอเฝ้าระวังตะวันตก เราต้องพร้อม แต่ที่แปลกคือ... ทำไมหอ?\n\nหมู่บ้านข้าเข้าใจ แต่หอนั่น? แทบไม่มีคุณค่าทางยุทธศาสตร์ นอกจากเป็นจุดสังเกตเล็ก ๆ\n\nอย่างไรเราจะเตรียมพร้อม พวกมันจะรู้ว่าชาวที่สูงไม่ได้ถูกจู่โจมจนตั้งตัวไม่ทันง่ายอย่างที่คิด" } } },
        progress = { "19:529702783:1789263789", "เจ้าได้รู้อะไรมาบ้าง?" },
        steps = { { "31:765957957:1310173899", "สืบแผนการของสาวกลัทธิ" } },
    },
    [92529] = { -- Falaath Village
        title = { "15:37317191:703402344", "หมู่บ้าน Falaath" },
        objective = { "168:1078228635:1182183099", "รายงานตัวต่อ Missionary Jasaan ใกล้ทางเข้า Falaath Village\n\nหากสูญเสีย Mark of Akir ให้คุยกับ Sania Silverstream ใน Shen'dar Village เพื่อรับผลนั้นคืน" },
        description = { "506:672949832:1182080847", "ข้ายินดีจากใจที่เจ้าอยากรับใช้ Al'Akir ความลำบากของชนเผ่าเราวันนี้เกิดจากความชะล่าใจ เราหยิ่งผยองและเห็นความอุดมจากลมเป็นของตาย ความหยุดนิ่งที่ตามมาทำให้วิญญาณลมทอดทิ้ง\n\nมีแต่การสำนึกผิดผ่านการกระทำ จึงจะรู้สึกถึงลมลูบไล้อีกครั้ง หากอยากร่วมกับ Shen'dorei ผู้คิดเหมือนกัน ไป Falaath Village หา Missionary Jasaan ข้าจะประทับเครื่องหมายให้ผู้ศรัทธารู้ว่าเจ้าเป็นผู้สมัคร" },
        completion = { "202:1101356448:379378021", "อะไรนี่? สาวกใหม่อยากรับใช้เจ้าแห่งลมที่ซิสเตอร์ Sania ส่งมาหรือ? วันนี้เราได้รับพรสัมผัสของลมทั้งสี่จริง ๆ!\n\nเราต้อนรับทุกคนที่แสวงหาความสุขในพรของ Al'Akir" },
        objectiveLabels = {
            event = { ["Speak with Missionary Jasaan at the entrance to Falaath Village"] = "คุยกับ Missionary Jasaan ตรงทางเข้า Falaath Village" },
        },
    },
    [92544] = { -- Al'Aketh Thugs
        title = { "14:504198433:1314709508", "อันธพาล Al'Aketh" },
        objective = { "86:2035161440:1987511466", "สังหาร Al'Aketh Brutes 6 คน, Al'Aketh Neophytes 4 คน และ Malduko Cloudcrush ใน Thendal Grove" },
        description = { "490:1541380846:2084922790", "อันธพาลลัทธิ Al'Aketh ตั้งหลักใกล้ซากวิหารทางตะวันตกเฉียงใต้ นำโดยอสุรกายชื่อ Malduko Cloudcrush แน่นอนว่าพวกนี้ถูก High Priestess Lorthuna ที่ Shrine of Akir ส่งมาโจมตีคนเดินทางและบังคับผู้คนเข้าลัทธิ\n\nข้าต้องเฝ้าที่นี่เตือนคนออกจากป่าถึงอันตราย แต่จะขอบคุณมากหากเจ้าจัดการสาวกกับหัวหน้าให้ได้" },
        progress = { "145:457800565:1715338947", "ข้าคิดว่าเห็นพวกเดียวกันสักสองสามคนนอนเลือดนองคงช่วยดับความทะเยอทะยานคลั่งของอันธพาลพวกนี้ได้ดีนัก" },
        completion = { "247:1871576309:1113555185", "ข้าต้องห้ามตัวเองสุดแรงไม่ให้ทิ้งตำแหน่งไปช่วยเจ้า หวังว่าเจ้าพวกนั้นคงเข้าใจและรีบไสหัวไป\n\nขอบคุณ นักผจญภัย Rangers of Thendal Grove ซาบซึ้งในบุญคุณเจ้า", variants = { { "180:188981518:1554093628 C 57:53318926:905251205", "ข้าต้องห้ามตัวเองสุดแรงไม่ให้ทิ้งตำแหน่งไปช่วยเจ้า หวังว่าเจ้าพวกนั้นคงเข้าใจและรีบไสหัวไป\n\nขอบคุณ {class} Rangers of Thendal Grove ซาบซึ้งในบุญคุณเจ้า" } } },
        objectiveLabels = {
            monster = { ["Al'Aketh Brute slain"] = "ปราบ นักเลงร่างใหญ่ Al'Aketh", ["Al'Aketh Neophyte slain"] = "ปราบ สาวกใหม่ Al'Aketh", ["Malduko Cloudcrush slain"] = "ปราบ Malduko Cloudcrush" },
        },
    },
    [92550] = { -- Havoc in the Highlands
        title = { "22:1538039272:1543131882", "ความโกลาหลบนที่สูง" },
        objective = { "130:1054966867:682823684", "ไปซาก Falaath Village สังหาร Al'Aketh Stormcallers 6 คน, Living Lightning 4 ตน และเก็บหัว Commander Cyclas" },
        description = { "478:1802154067:812516180", "การป้องกันที่ดีที่สุดตอนนี้อาจเป็นรุกหนัก เราได้เปรียบตรงรู้ว่าจะถูกโจมตี สิ่งที่พวกมันไม่คาดคือเราชิงลงมือก่อน\n\nข้าขอเจ้าไปมากแล้ว แต่โปรดกลับ Falaath Village ฆ่าสาวกให้มากเท่าที่ทำได้ หากเข้าใกล้พอก็ฆ่าผู้บัญชาการแล้วนำหัวมา ข้าจะจัดชาวบ้านกับผู้รักษาความสงบไม่กี่คนเตรียมป้องกัน... เผื่อเจ้าไม่กลับมา" },
        progress = { "50:1181238251:814009467", "ได้พลิกสถานการณ์ใส่พวกคลั่งแล้วรู้สึกดีจริง ๆ" },
        completion = { "381:658638784:899954594", "ขอบคุณสายลมที่เจ้ากลับมา!\n\nSania Silverstream แอบออกจากเมืองก่อนเจ้ามาถึง คงหนีเมื่อเห็นคนของเราจับอาวุธ\n\nเจ้าทำสิ่งยิ่งใหญ่ให้ชาว Shen'dar Village เราเป็นหนี้บุญคุณ หากลัทธิกลับมาที่สูง จะพบว่า Shen'dar ไม่ใช่เป้าง่ายอีกแล้ว\n\nขอสายลมนำทาง สหาย", variants = { { "374:758126751:1723077850 N 1:46:46", "ขอบคุณสายลมที่เจ้ากลับมา!\n\nSania Silverstream แอบออกจากเมืองก่อนเจ้ามาถึง คงหนีเมื่อเห็นคนของเราจับอาวุธ\n\nเจ้าทำสิ่งยิ่งใหญ่ให้ชาว Shen'dar Village เราเป็นหนี้บุญคุณ หากลัทธิกลับมาที่สูง จะพบว่า Shen'dar ไม่ใช่เป้าง่ายอีกแล้ว\n\nขอสายลมนำทาง {name}" } } },
        required = { [252661] = { "23:1056919018:1427326747", "หัวของ Commander Cyclas" } },
        steps = { { "23:1056919018:1427326747", "หัวของ Commander Cyclas" } },
        objectiveLabels = {
            monster = { ["Al'Aketh Stormcaller slain"] = "ปราบ ผู้เรียกพายุ Al'Aketh", ["Living Lightning slain"] = "ปราบ สายฟ้ามีชีวิต" },
        },
    },
    [92551] = { -- Stolen Supplies
        title = { "15:1561291513:154504613", "เสบียงที่ถูกขโมย" },
        objective = { "92:1894191671:148877874", "รวบรวม Stolen Shen'dar Supplies 10 ห่อจาก Falaath Village ใน Shen'dar Highlands" },
        description = { "458:930643889:2043012100", "ได้ยินว่าเจ้าจะไป Falaath Village หรือ? ระหว่างอยู่ที่นั่น โปรดมองหาคลังเสบียงที่ถูกขโมยด้วย\n\nหลายเดือนแล้วที่ Al'Aketh ปล้นคาราวานบรรทุกอาหาร Windstone และสินค้าต่าง ๆ ระหว่างที่นี่กับที่ลุ่ม แน่นอนว่าพวกมันโทษโจร แต่เรารู้ว่าท้ายที่สุดของไปอยู่ที่เดียวกัน หากยังเหลือใน Falaath ช่วยกู้คืนได้จะเป็นประโยชน์มหาศาล" },
        progress = { "76:1209578970:486256610", "มี Skyborne หิวโหยสิ้นหวังมากมายที่ต้องการเสบียงนี้", variants = { { "38:1846254692:470643472 R 30:1270617044:1328712336", "มี ชาว{race} หิวโหยสิ้นหวังมากมายที่ต้องการเสบียงนี้" } } },
        completion = { "205:1278179054:233712395", "เยี่ยมมาก! เราแทบประคองตัวไม่ไหวเมื่อเสบียงประจำขาดไป ข้าจะร่วมกับนายกองจัดแจกให้ชาวเมืองที่เดือดร้อนที่สุด" },
        required = { [252760] = { "24:102551701:691824526", "เสบียง Shen'dar ที่ถูกขโมย" } },
        objectiveLabels = {
            item = { ["Stolen Shen'dar Supplies"] = "เสบียง Shen'dar ที่ถูกขโมย" },
        },
    },
    [92553] = { -- Restocking the Larders
        title = { "22:1949451179:1109182586", "เติมคลังอาหาร" },
        objective = { "95:1973222318:908374643", "รวบรวม Small Eggs 3 ฟองและ Strider Meat 8 ชิ้นจากสัตว์ทั่ว Shen'dar Highlands", amount = { "8:1089852795:1107240600 W1 16:657687499:202790239 W2 69:1726635688:1538437251", "รวบรวม Small Eggs {world1} ฟองและ Strider Meat {world2} ชิ้นจากสัตว์ทั่ว Shen'dar Highlands" } },
        description = { "404:1870201556:930849004", "อยากทำงานหน่อยไหม? ข้าอยากพึ่งแรงนักผจญภัยแข็งแกร่งอย่างเจ้า ช่วงนี้อันตรายขึ้นจนไม่มีใครมีเวลาล่าหรือหาของป่า ต้องการคนไปหาไข่สดและเนื้อ Strider มาเลี้ยงหมู่บ้าน\n\nหากนำของที่ต้องการมา ข้ายินดีสอนสูตรขึ้นชื่อสักสูตร ว่าอย่างไร?" },
        progress = { "181:1671261899:1030089914", "ไม่ว่า Zephras จะเปลี่ยนไปและไม่แน่นอนเพียงใด ข้าพูดเสมอว่ากล้องยาที่ใส่ Peacebloom แห้งเต็มกับท้องอิ่ม ๆ ให้ความสบายใจไม่มีสิ่งใดเทียบ!" },
        completion = { "260:540936937:2135802369", "ไข่พวกนี้หาไม่ง่าย แต่สายลมช่วยข้าที ทอดกับไขมัน Ursera นิดหน่อยแล้วอร่อยเหลือเกิน\n\nหากมีเวลาว่างและชอบทำอาหาร ข้าสอนเคล็ดลับที่เรียนรู้มาให้ได้ บอกมาเลย ข้ายินดีฝึกให้" },
        required = { [6889] = { "9:1833036929:1897512203", "ไข่ขนาดเล็ก" }, [5469] = { "12:999970032:1255254832", "เนื้อสไตรเดอร์" } },
        steps = { { "9:1833036929:1897512203", "ไข่ขนาดเล็ก" }, { "12:999970032:1255254832", "เนื้อสไตรเดอร์" } },
    },
    [92579] = { -- To Valanaar
        title = { "11:143351137:736344242", "ไป Valanaar" },
        objective = { "65:2145836366:1867972722", "ส่ง Aonda's Written Report ให้ Valennia Stormfist ใน Valanaar" },
        description = { "490:2041328015:936351245 N 1:46:46", "ตอนนี้ดูว่าเสาไพลอนและหมู่บ้านปลอดภัยแล้ว ข้าอยากให้ส่งรายงานแก่ Valennia Stormfist ใน Valanaar ริมเกาะตะวันออกเฉียงใต้ นางนำผู้รักษาความสงบบนเกาะและต้องรู้ว่าเกิดอะไรขึ้น\n\nลัทธิขยายตัวรวดเร็ว ผู้รักษาความสงบหลีกเลี่ยงปะทะตรงมาตลอด แต่วันเหล่านั้นจบแล้ว Valanaar ต้องพร้อมสู้\n\nอย่างไรขอขอบคุณ เจ้าจะมีสหายใน Shen'dar เสมอ {name}", variants = { { "494:621019383:1653326123 N 1:46:46", "ตอนนี้ดูว่าเสาไพลอนและหมู่บ้านปลอดภัยแล้ว ข้าอยากให้ส่งรายงานแก่ Valennia Stormfist ใน Valanaar ริมเกาะตะวันออกเฉียงใต้ นางนำผู้รักษาความสงบบนเกาะและต้องรู้ว่าเกิดอะไรขึ้น\n\nลัทธิขยายตัวรวดเร็ว ผู้รักษาความสงบหลีกเลี่ยงปะทะตรงมาตลอด แต่วันเหล่านั้นจบแล้ว Valanaar ต้องพร้อมสู้\n\nอย่างไรขอขอบคุณ เจ้าจะมีสหายใน Shen'dar เสมอ {name}" } } },
        progress = { "62:33815804:1724575298", "จดหมายจาก Aonda ชาวที่สูงเจ้าเล่ห์คนนั้นทำอะไรอยู่อีก?" },
        completion = { "498:1155326451:1088344779", "<สีหน้า Valennia หม่นลงขณะอ่านจดหมาย>\n\nAonda ไว้ใจให้ส่งสิ่งนี้ และชมเจ้าในจดหมายมากพอ ข้าจะพยายามไว้ใจด้วย ก่อนคุยต่อ ต้องปรึกษา Peacekeeper ไม่กี่คนที่เหลือ วางแผนเผื่อลัทธิโจมตีที่นี่ต่อ ระหว่างนี้พักใน Valanaar ให้สบาย\n\nหากอยากหางาน ชาวเมืองมากมายคงพึ่งแรงนักผจญภัยหนุ่มสาวแข็งแกร่งเช่นเจ้าได้" },
        required = { [253152] = { "22:370421703:553780513", "รายงานลายลักษณ์อักษรของ Aonda" } },
        steps = { { "22:370421703:553780513", "รายงานลายลักษณ์อักษรของ Aonda" } },
    },
    [92595] = { -- The Windshapers
        title = { "15:697982905:665639242", "เหล่าผู้ปรับสายลม" },
        objective = { "43:1363316256:659282481", "ฟังสิ่งที่ Illaya Amberwind พูด" },
        description = { "407:617414379:522112898", "<Illaya ยิ้มให้อย่างอบอุ่น>\n\nยินดีที่กลับมาคุย บุตรแห่งสายลม ข้ารู้ตั้งแต่ก้าวมาเบื้องหน้าว่าเจ้ามีพลัง Skysight เข้มแข็ง แปลกใจหรือ? แม้คนไม่ได้ฝึกเป็นชาแมนก็มีพรนี้ได้\n\nมาเถิด คุยถึงหน้าที่ของ Windshaper ธรรมชาติการต่อสู้ดิ้นรนบน Zephras และความทุกข์ของชนเผ่าเรา", variants = { { "373:1352946702:972068179", "<Illaya ยิ้มให้เจ้าอย่างอบอุ่น>\n\nข้าดีใจที่เจ้ากลับมาคุยกับข้า บุตรแห่งสายลม ข้ารู้ตั้งแต่แรกที่เจ้าเดินเข้ามาหาข้าว่าพลัง Skysight ของเจ้าแข็งแกร่ง แม้เทียบกับชาแมนด้วยกัน เจ้าก็ยังมีพรสวรรค์โดดเด่นในการใช้พรของเรา\n\nมาเถิด มาคุยกันถึงหน้าที่ของเหล่า Windshaper การต่อสู้ที่เราเผชิญบน Zephras และความทุกข์ยากของชนเผ่าเรา" }, { "197:1323532816:1479314013 C 170:1032704539:834556408", "<Illaya ยิ้มให้อย่างอบอุ่น>\n\nยินดีที่กลับมาคุย บุตรแห่งสายลม ข้ารู้ตั้งแต่ก้าวมาเบื้องหน้าว่าเจ้ามีพลัง Skysight เข้มแข็ง แม้เทียบกับ{class}ด้วยกัน เจ้าก็ใช้พรของเราได้โดดเด่นเป็นพิเศษ\n\nมาเถิด คุยถึงหน้าที่ของ Windshaper ธรรมชาติการต่อสู้ดิ้นรนบน Zephras และความทุกข์ของชนเผ่าเรา" } } },
        completion = { "448:840399039:7033197", "ข้าว่าตอนนี้เจ้าเข้าใจความสำคัญภารกิจของ Windshaper แล้ว ทุกผู้ใช้ Skysight สำคัญยิ่ง หากหวังเปิดบทสนทนากับวิญญาณลมอีกครั้ง\n\nท่ามกลางภัยภายในเช่น Al'Aketh และความไม่แน่นอนของความปลอดภัยใน Skywall หน้าที่ Windshaper คือต้องใช้พรช่วยบ้านและทำให้ Shen'dorei ผ่านยุคทดสอบนี้ให้ได้" },
        progress = { "103:28969217:1595420367", "โลกกำลังเปลี่ยนไปและทางข้างหน้าจะยากลำบาก เรามีโอกาสช่วยตัวเองเพียงครั้งเดียว" },
        steps = { { "16:1635774911:78605092", "ฟังสิ่งที่ Illaya จะบอก" } },
    },
    [92596] = { -- The High Order
        title = { "14:1600949824:166535201", "คณะ High Order" },
        objective = { "45:1386308362:805604431", "นั่งลงแล้วคุยกับ Rathiril Sunlance" },
        description = { "427:1329166868:872107096", "รัศมีพลังอาร์เคนรอบตัวเจ้าเข้มแข็ง แม้ไม่ได้เริ่มฝึกเป็นเมจ ข้ามั่นใจว่าเจ้าจะเป็นนักผจญภัยสามารถ สายสัมพันธ์กับเวทโบราณของเราจะเป็นคุณเสมอ แม้ไม่เคยเอ่ยถ้อยคำพลังเพื่อร่ายคาถาสักคำ\n\nมานั่งคุยถึงคณะของข้า ธรรมชาติอาร์เคนบน Zephras และความทุกข์ของชนเผ่าเรา", variants = { { "181:1453419718:1846818818", "รัศมีพลังอาร์เคนรอบตัวเจ้าแข็งแกร่งมาก แม้จะเทียบกับเมจด้วยกันก็ตาม\n\nมานั่งคุยกันเถิด ทั้งเรื่องธรรมชาติของเวทอาร์เคนและความทุกข์ยากของบ้านเกิดเรา" }, { "67:893285372:1373534276 C 110:739554173:1060318888", "รัศมีพลังอาร์เคนรอบตัวเจ้าแรงกล้าทีเดียว แม้สำหรับ{class}อย่างเจ้าก็ตาม\r\n\r\nมาเถิด มานั่งคุยกันเรื่องธรรมชาติของเวทอาร์เคนและความลำบากที่บ้านเกิดของเรากำลังเผชิญ" } } },
        completion = { "448:1944612631:1957909227", "ภารกิจ High Order สำคัญต่อความอยู่รอดของชนเผ่า เราเคารพผู้เกื้อหนุนแห่งธาตุอย่างสูงสุด แต่ต้องเผชิญความจริง พวกเขาจากไปแล้ว เราต้องพึ่งตัวเอง\n\nท่ามกลางภัยภายในเช่น Al'Aketh และความไม่แน่นอนของความปลอดภัยในภพนี้ ในฐานะลูกหลาน Highborne จากบ้านบรรพชน Eldre'Thalas ชะตาเราคือต้องใช้พรให้ Shen'dorei ยืนได้ด้วยตนเองอีกครั้ง" },
        progress = { "82:1342596088:1265959674", "ดินแดนของเรากำลังเปลี่ยนไป แต่เราอาจได้เห็นสิ่งดี ๆ จากการเปลี่ยนแปลงนี้ก็ได้" },
        steps = { { "27:1177818075:1744096216", "ฟังสิ่งที่ Rathiril Sunlance จะบอก" } },
    },
    [92597] = { -- Reading the Ley Lines
        title = { "21:1287789802:2093432344", "อ่านเส้นพลังเวท", variants = { { "20:530697956:2119534715", "อ่านเส้นพลังเวท" } } },
        objective = { "71:845012779:486578851", "ใช้ความสามารถประจำเผ่า Read Ley Line ที่เส้นพลังเวทใน Thendal Grove", variants = { { "69:1463657484:1517882892", "ใช้ความสามารถประจำเผ่า Read Leyline ที่เส้นพลังเวทใน Thendal Grove" } } },
        description = { "385:705364239:1821393007", "ในแดนธาตุนี้ พลังอาร์เคนส่วนใหญ่ของเรามาจากเส้นพลังเวทที่ยังไหลใต้เท้า ช่วงหลังมันเริ่มทะลุผิวดิน ให้เราเข้าถึงพลังแฝงได้ตรงและแรงขึ้น\n\nไปแนวหินตั้งตะวันออกเฉียงเหนือ มีเส้นพลังเวทอยู่ จงใช้สิทธิ์แต่กำเนิดดึงพลังเข้าไป", variants = { { "382:1099393447:1251480080", "ในแดนธาตุนี้ พลังอาร์เคนส่วนใหญ่ของเรามาจากเส้นพลังเวทที่ยังไหลใต้เท้า ช่วงหลังมันเริ่มทะลุผิวดิน ให้เราเข้าถึงพลังแฝงได้ตรงและแรงขึ้น\n\nไปแนวหินตั้งตะวันออกเฉียงเหนือ มีเส้นพลังเวทอยู่ จงใช้สิทธิ์แต่กำเนิดดึงพลังเข้าไป" } } },
        progress = { "212:121478008:2139664781", "การตระหนักถึงศักยภาพแท้ในฐานะบุตรธิดา Highborne เป็นทางรอดเดียว Windshaper แทบดีกว่า Al'Aketh ไม่เท่าไร ต่างยอมสยบต่อสิ่งจากต่างภพที่ไม่สนใจเรา" },
        completion = { "455:494185519:2087062946", "รู้สึกไหม? ใช่หรือ? ดี! เจ้าได้ก้าวแรกแล้ว จะพบว่าความสามารถช่วยดึงเวทแฝงในหลายแห่ง ให้ประโยชน์หลากหลาย บางอย่างลึกซึ้ง บางอย่างละเอียดอ่อน ต้องลองจึงจะรู้ แต่นั่นคือส่วนดีที่สุดของพร... เปลี่ยนสิ่งไม่รู้ให้เป็นความรู้\n\nหากจะรอดยุคอันเลวร้าย เราต้องไม่หวั่นไหวในการแสวงหาความรู้... และพลัง", variants = { { "455:328994779:1815954077", "รู้สึกไหม? ใช่หรือ? ดี! เจ้าได้ก้าวแรกแล้ว จะพบว่าความสามารถช่วยดึงเวทแฝงในหลายแห่ง ให้ประโยชน์หลากหลาย บางอย่างลึกซึ้ง บางอย่างละเอียดอ่อน ต้องลองจึงจะรู้ แต่นั่นคือส่วนดีที่สุดของพร... เปลี่ยนสิ่งไม่รู้ให้เป็นความรู้\n\nหากจะรอดยุคอันเลวร้าย เราต้องไม่หวั่นไหวในการแสวงหาความรู้... และพลัง" }, { "455:1311181557:1359216056", "รู้สึกไหม? ใช่หรือ? ดี! เจ้าได้ก้าวแรกแล้ว จะพบว่าความสามารถช่วยดึงเวทแฝงในหลายแห่ง ให้ประโยชน์หลากหลาย บางอย่างลึกซึ้ง บางอย่างละเอียดอ่อน ต้องลองจึงจะรู้ แต่นั่นคือส่วนดีที่สุดของพร... เปลี่ยนสิ่งไม่รู้ให้เป็นความรู้\n\nหากจะรอดยุคอันเลวร้าย เราต้องไม่หวั่นไหวในการแสวงหาความรู้... และพลัง" } } },
        steps = { { "60:255029433:838929714", "ใช้ความสามารถ Read Leyline ใกล้เส้นพลังเวทที่ Thendal Grove" }, { "62:2048512224:224227169", "ใช้ความสามารถ Read Ley Line ใกล้เส้นพลังเวทที่ Thendal Grove" } },
    },
    [92598] = { -- The Gift of Skysight
        title = { "20:1364314010:721411474", "พรแห่ง Skysight" },
        objective = { "79:1756852075:1478105574", "ใช้ความสามารถประจำเผ่า Skysight ที่ Elemental Convergence ใน Thendal Grove" },
        description = { "485:1700308724:2142724268", "ในฐานะ Windshaper เจ้าใช้ Skysight ศักดิ์สิทธิ์ที่วิญญาณธาตุมอบได้ ไปแนวหินตั้งตะวันออกเฉียงเหนือของหมู่บ้าน หาจุดบรรจบธาตุแล้วใช้พร\n\nเจ้าเรียกใช้ Skysight ได้ทุกที่ แต่พรจะแรงกว่ามากเมื่ออยู่ใกล้ Elemental Convergence บางครั้งยังได้รับปัญญาอื่นจากวิญญาณที่ถูกดึงมาสู่สถานที่ทรงพลังเช่นนั้นด้วย" },
        progress = { "69:127731733:1501959763", "พร Skysight จะให้พลังเกื้อหนุนอันเข้มแข็ง จงใช้อย่างมีปัญญา", variants = { { "74:894230838:1490956340", "พร Skysight จะให้พลังเกื้อหนุนอันเข้มแข็ง จงใช้อย่างมีปัญญา" } } },
        completion = { "376:741367868:914359032", "Skysight ต้องฝึกดุจกล้ามเนื้อ หากหวังให้พรแข็งแกร่งขึ้น การใช้มันเชื่อมระยะระหว่างโลกมรรตัยกับจิตวิญญาณอาจมีค่ายิ่งในการผจญภัย\n\nจงจำสิ่งที่เรียนวันนี้ ความสามารถใช้พรฟังธาตุบอกเรา อาจเป็นกุญแจความอยู่รอด" },
        steps = { { "43:1631191761:1522166877", "ใช้ Skysight ใกล้ Elemental Convergence" } },
    },
    [92640] = { -- Desperate Times
        title = { "15:1519058729:2124277850", "ยามคับขัน" },
        objective = { "70:1520446029:872141670", "คุยกับ Valennia Stormfist ใน Valanaar แล้วทำตามคำสั่งของนาง" },
        description = { "416:1864488632:1800133593", "เมื่อปะทะลัทธิในที่เปิดไม่ได้ โอกาสดีที่สุดคือฉวยจังหวะโจมตีศาลโดยตรง เรากำจัด Lorthuna ได้ก่อนนางทำส่วนของตนในแผนสำเร็จ\n\nบังเอิญ Valennia เตรียมยุทธวิธีเผื่อบุกศาลมาพักหนึ่งแล้ว ปัญหาเดียวคือเราต้องการความช่วยเหลือ\n\nคุยรายละเอียดกับ Valennia" },
        completion = { "141:859336988:314368137", "ตอนนี้ Windshaper กับ High Order ตึงเครียด แต่จะทำแผนนี้สำเร็จไม่ได้เลยหากไม่ได้ทั้งสองกลุ่มร่วมมือ" },
        steps = { { "29:978092562:2058179152", "คุยกับ Valennia Stormfist" }, { "23:1097690632:1341429774", "ชวนเหล่า Windshaper เข้าร่วม" }, { "22:1535657367:696270061", "ชวนเหล่า High Order เข้าร่วม" } },
    },
    [92643] = { -- The Turncoat
        title = { "12:789020701:2088052912", "ผู้แปรพักตร์" },
        objective = { "87:327483095:197449199", "หาสาวกลัทธิผู้แปรพักตร์ที่บ้านในเขตที่สูง ถัดจาก Valanaar ไปทางตะวันตกเฉียงเหนือเล็กน้อย" },
        description = { "468:233959936:1080698701", "มีผู้แปรพักตร์ใน Al'Aketh อ้างว่ารู้เจตนาแท้ของลัทธิต่อเกาะและอยากมาหาเรา แต่ต้องรับรองการคุ้มครองก่อน\n\nเขาซ่อนในบ้านห่างไกลทางตะวันตกเฉียงเหนือของ Valanaar เข้าไปในที่สูง ข้าต้องการคนไปเงียบ ๆ หาคนทรยศแล้วคุ้มกันกลับมา อาจเป็นกับดัก แต่ถ้าข้อมูลสำคัญอย่างอ้าง ก็คุ้มเสี่ยงบ้าง", variants = { { "467:649768119:1246749006", "มีผู้แปรพักตร์ใน Al'Aketh อ้างว่ารู้เจตนาแท้ของลัทธิต่อเกาะและอยากมาหาเรา แต่ต้องรับรองการคุ้มครองก่อน\n\nเขาซ่อนในบ้านห่างไกลทางตะวันตกเฉียงเหนือของ Valanaar เข้าไปในที่สูง ข้าต้องการคนไปเงียบ ๆ หาคนทรยศแล้วคุ้มกันกลับมา อาจเป็นกับดัก แต่ถ้าข้อมูลสำคัญอย่างอ้าง ก็คุ้มเสี่ยงบ้าง" } } },
        completion = { "179:628920369:1920337280", "ชายนี้ตายแล้วอย่างชัดเจน ถูกมือสังหารที่เจ้าสู้หน้าบ้านฆ่า เมื่อคุกเข่าตรวจศพ ก็สังเกตแสงสะท้อนจากของแวววาวบางอย่าง...", variants = { { "181:1747978823:1112467048", "ชายนี้ตายแล้วอย่างชัดเจน ถูกมือสังหารที่เจ้าสู้หน้าบ้านฆ่า เมื่อคุกเข่าตรวจศพ ก็สังเกตแสงสะท้อนจากของแวววาวบางอย่าง..." } } },
        steps = { { "26:869404299:627992454", "ตามหาสาวกลัทธิ Al'Aketh ผู้แปรพักตร์" }, { "45:991147172:1376511294", "ตามหาบ้านที่อยู่ห่างไกลผู้คนใน Shen'dar Highlands" } },
    },
    [92644] = { -- Unfortunate News
        title = { "16:428190921:1425871517", "ข่าวร้าย" },
        objective = { "65:442749747:116478287", "ส่งผลึกเรืองแสงให้ Talanaanis Shadowsong ใน Valanaar" },
        description = { "212:1520038506:1541457576", "<เจ้าล้วงใต้ร่างที่ยังอุ่นของสาวกผู้แปรพักตร์ เก็บผลึกฟ้าเรืองแสงเล็ก ๆ ดูเสียหายแต่ยังอาจสำคัญ High Elder Shadowsong คงสนใจสิ่งนี้>" },
        progress = { "27:1347528967:1710697087", "กลับมาแล้วหรือ? และ... มาคนเดียว?", variants = { { "27:294816362:1451279244", "กลับมาแล้วหรือ? และ... มาคนเดียว?" } } },
        completion = { "161:1327609365:345893570", "ผู้แปรพักตร์ตายก่อนเจ้าถึงหรือ? ข่าวร้ายนัก\n\nเจ้าส่งผลึกที่พบบนศพสาวกให้\n\nน่าสนใจ...", variants = { { "163:159437560:954798110", "ผู้แปรพักตร์ตายก่อนเจ้าถึงหรือ? ข่าวร้ายนัก\n\nเจ้าส่งผลึกที่พบบนศพสาวกให้\n\nน่าสนใจ..." } } },
        required = { [273852] = { "15:1591700646:576608262", "ผลึกเรืองแสง" } },
        objectiveLabels = {
            item = { ["Glowing Crystal"] = "ผลึกเรืองแสง" },
        },
    },
    [92646] = { -- Confront Lorthuna
        title = { "17:1873207911:1945188641", "เผชิญหน้า Lorthuna" },
        objective = { "152:721916182:1853908049", "ผ่านประตูมิติขึ้น Rohashi Spires เหนือศีรษะ สมทบ Elaadrin Evengale และ Ayessa Dawnsinger ในการเผชิญ High Priestess Lorthuna" },
        description = { "379:1869128723:1985626554 C 1:46:46", "Lorthuna ใช้ประตูมิติบางอย่างหนีขึ้นยอดหอด้านบน Ayessa กับ Elaadrin ตามไป เพิ่งไม่กี่อึดใจ\n\nข้าคงโดนหนักไปหน่อย ต้องอยู่ตรงนี้ ผ่านประตูไปหา Ayessa แล้วช่วยหยุด Lorthuna\n\nหากความช่วยเหลือที่ Elaadrin กับ Ayessa บอกว่าส่งคนไปขอยังไม่มาถึง เจ้าต้องพึ่งตัวเองจากนี้ โชคดี {class}" },
        completion = { "405:35487745:1820213294", "ข้าส่งผู้รักษาไปให้แน่ใจว่า Valennia กับกำลังที่เหลือกลับมาครบ ตอนนี้นางคงพักอยู่บ้าน High Elder\n\nMuln กลับ Azeroth แล้ว แต่เราคุยถึงก้าวต่อของ Windshaper และภารกิจสู่ Azeroth น่าเสียดายตอนนี้เกาะเปราะบางยิ่งกว่าเดิม ต้องมีแผนปกป้อง Zephras จากสิ่งที่จะมา" },
        steps = { { "17:1873207911:1945188641", "ไปเผชิญหน้ากับ Lorthuna" } },
    },
    [92679] = { -- Blood Tithe
        title = { "11:997404251:1063484172", "บรรณาการโลหิต" },
        objective = { "97:1804188044:1735441897", "ฟังสิ่งที่ Alvarion Windfield พูด แล้วไปหา Aamelia Windfield ที่ Windfield Orchard" },
        description = { "374:1494497003:623675732", "สะ... สวัสดี คนแปลกหน้า เจ้าดูเป็นนักผจญภัยสามารถ ข้า...\n\n<ชาย Skyborne สะดุ้งเจ็บ เห็นชัดว่าทรมานอย่างหนัก>\n\n...อยากถามว่ากำลังหางานหรือไม่? ข้ามา Valanaar เพื่อหานักสู้ช่วยไร่ หากสนใจ ไปหาภรรยาข้า Aamelia Windfield ที่สวนของเราทางตะวันตกของ Valanaar ในที่ลุ่ม", variants = { { "83:192439318:886865970 R 283:1841181614:181744260", "สะ... สวัสดี คนแปลกหน้า เจ้าดูเป็นนักผจญภัยสามารถ ข้า...\n\n<ชาย {race} สะดุ้งเจ็บ เห็นชัดว่าทรมานอย่างหนัก>\n\n...อยากถามว่ากำลังหางานหรือไม่? ข้ามา Valanaar เพื่อหานักสู้ช่วยไร่ หากสนใจ ไปหาภรรยาข้า Aamelia Windfield ที่สวนของเราทางตะวันตกของ Valanaar ในที่ลุ่ม" } } },
        progress = { "24:600739628:1186326463", "อะไรนะ? Alvarion ยังมีชีวิตหรือ?" },
        completion = { "295:1763647632:1056517509", "<Aamelia ฟังขณะเจ้าเล่าชะตา Alvarion>\n\nอย่างน้อยก็รู้ว่าเขาจะปลอดภัยใน Valanaar\n\nคนแปลกหน้า ข้าไม่อยากพูด แต่สามีโง่ของข้าคงส่งเจ้ามาตายเปล่า หากมีสติอยู่บ้าง ควรไปตอนนี้ นี่ไม่ใช่ศึกของเจ้า" },
        steps = { { "22:363330351:1385791538", "ตามหา Aamelia Windfield" }, { "36:578746404:1933437194", "ฟังเรื่องราวของ Alvarion Windfield", variants = { { "47:396120474:1658670149", "ฟังเรื่องราวของ Alvarion Windfield (ไม่บังคับ)" } } } },
    },
    [92682] = { -- Make Yourself Useful
        title = { "20:1788674708:1609904882", "ทำตัวให้มีประโยชน์" },
        objective = { "78:1019826062:1805392709", "เก็บ Ripe Stormapples 10 ผล และสังหาร Hungry Bandits 5 คนที่ Windfield Orchard" },
        description = { "431:798882582:1865173810", "อ้อ กล้ามากกว่าฉลาดสินะ? ได้ ข้าไม่เถียง\n\nFerauu กับลูกน้องยังไม่ถึงเวลามารับส่วนแบ่งผลผลิต ข้าจะให้เจ้าทำงานแลกอาหารระหว่างรอ\n\nออกไปเก็บ Stormapple ชุดวันนี้ อ้อ โจรที่ซุ่มแถวต้นไม้ด้วย... พวกมันคิดว่าลับ ๆ ล่อ ๆ แล้ว ไม่มีทาง ฆ่าให้ข้าที\n\nมาดูว่าเจ้าสู้ได้แค่ไหน" },
        progress = { "236:1695158422:1747813401", "โจรพวกนี้หักหลังและขโมยกันเองบ่อยกว่าปล้นคนธรรมดา ข้าพนันว่าถ้า Ferauu รู้ว่าลูกน้องแหกคอกมาก่อนเวลาเพื่อยุ่งกับผลผลิต เขาคงฆ่าด้วยตัวเอง" },
        completion = { "63:810799194:1991214690", "ข้าดูจากหน้าต่างตอนเจ้าล้มโจรพวกนั้น ไม่เลว" },
        required = { [253591] = { "15:2085209737:1618304526", "สตอร์มแอปเปิลสุก" } },
        steps = { { "15:2085209737:1618304526", "สตอร์มแอปเปิลสุก" } },
        objectiveLabels = {
            monster = { ["Hungry Bandit slain"] = "ปราบ โจรหิวโหย" },
        },
    },
    [92683] = { -- Flutterfly Dust
        title = { "15:1461120268:628123345", "ผงปีก Flutterfly" },
        objective = { "77:1470375126:358813010", "รวบรวม Flutterfly Dust 5 กองจาก Flutterfly รอบ Gustberry Lowlands" },
        description = { "503:112249043:832661150", "คงเห็น Flutterfly ยักษ์ในทุ่งรอบนอกใกล้สวนแล้ว? มันดูงาม แต่มีประโยชน์อื่นด้วย นั่นคือผงปีก อาจเลอะเทอะ แต่ถ้าเก็บได้มากก็ใช้ประโยชน์ในบ้าน\n\nเอา Flutterfly Swatter นี้ไปตีแมลงใหญ่ให้ที ปกติมันแค่ตกใจหนี แต่บางครั้งก็โกรธ ไม่ว่าอย่างไร มันจะส่ายก้นทิ้งกองผงไว้" },
        progress = { "105:1356169881:2068556111", "ปกติ Flutterfly สงบเชื่อง แต่ทำให้ไม่พอใจ บางทีก็ทำให้เจ้าประหลาดใจได้" },
        completion = { "418:748388442:597080422", "ของนี้เลอะและกระจายทั่ว น่าเสียดายที่เจ้าอาจต้องสะบัดออกจากกางเกงไปอีกหลายสัปดาห์ แต่ข้าขอบคุณจริง งานนี้ค้างมาหลายสัปดาห์แล้ว ข้าอยู่คนเดียว มีโจรซุ่มทุกแห่ง ออกจากบ้านไกลก็เสี่ยงมาก\n\nไม่ต้องถามว่าใช้ทำอะไร เรื่องต่าง ๆ สารพัดเรื่องนั่นแหละ อย่าห่วงเลย" },
        required = { [253595] = { "15:1461120268:628123345", "ผง Flutterfly" }, [253666] = { "18:1758424952:1949137319", "ไม้ตี Flutterfly" } },
        steps = { { "15:1461120268:628123345", "ผง Flutterfly" }, { "18:1758424952:1949137319", "ไม้ตี Flutterfly" } },
    },
    [92684] = { -- Ornery Ornery Galestriders
        title = { "26:374448626:1606291056", "Galestrider ดุเหลือเกิน" },
        objective = { "111:384635818:375279493", "รวบรวม Lowlands Galestrider Tenderloins 7 ชิ้นจาก Ornery Galestrider ทั่ว Gustberry Lowlands" },
        description = { "495:279597576:1319761876", "เหมือนผลผลิตปีนี้ยังน้อยไม่พอ Galestrider แถวนี้ยังเข้าสวนมาขโมย Stormapple เจ้าช่วยออกไปลดจำนวนในทุ่งได้ไหม?\n\nระวัง คนแปลกหน้า พวกที่ลุ่มใหญ่และดุกว่าพวกที่สูง ระวังตัว หากเผลอ เตะเข้าจังหวะครั้งเดียวก็ทำให้เจ้าจบชีวิตได้\n\nนำเนื้อมาด้วย ข้าจะทำอาหารร้อนให้เรากิน", variants = { { "495:919290255:1000518920", "เหมือนผลผลิตปีนี้ยังน้อยไม่พอ Galestrider แถวนี้ยังเข้าสวนมาขโมย Stormapple เจ้าช่วยออกไปลดจำนวนในทุ่งได้ไหม?\n\nระวัง คนแปลกหน้า พวกที่ลุ่มใหญ่และดุกว่าพวกที่สูง ระวังตัว หากเผลอ เตะเข้าจังหวะครั้งเดียวก็ทำให้เจ้าจบชีวิตได้\n\nนำเนื้อมาด้วย ข้าจะทำอาหารร้อนให้เรากิน" } } },
        progress = { "65:1248683890:729572232", "ข้าว่าไม่ได้กินเนื้อจริง ๆ มื้อเย็นมา... นานเกินไปแล้ว", variants = { { "65:1073865431:1031853388", "ข้าว่าไม่ได้กินเนื้อจริง ๆ มื้อเย็นมา... นานเกินไปแล้ว" } } },
        completion = { "81:754146373:436650093", "เนื้อสันในชิ้นใหญ่! เจ้าคงล้มสัตว์ตัวมหึมามาไม่น้อย" },
        required = { [253597] = { "31:957011933:1119881230", "เนื้อสันใน Galestrider จากที่ราบต่ำ" } },
        steps = { { "31:957011933:1119881230", "เนื้อสันใน Galestrider จากที่ราบต่ำ" } },
    },
    [92685] = { -- The Hills Have Eyes
        title = { "19:1440101132:675039313", "เนินเขามีดวงตา" },
        objective = { "84:1357930968:2106574522", "เก็บ Blood-Stained Bandit Masks 7 ชิ้นจาก Highwayman Bandits ใน Gustberry Lowlands" },
        description = { "304:1588195783:2100197505", "โจรมีค่ายทั่ว มีค่ายเล็กบนเนินทางเหนือไม่ไกล ขึ้นไปทุบกะโหลกเสีย หากฉวยจังหวะกำจัดก่อนพวกมันมาหาเรา ก็อาจทำให้โอกาสสูสีพอจะสู้ได้\n\nนำหน้ากากมา ยิ่งเปื้อนเลือดยิ่งดี" },
        completion = { "448:334609862:1363494956", "ตอนข้าบอกว่ายิ่งเปื้อนเลือดยิ่งดี เจ้าเชื่อฟังจริง ๆ ดี จะได้รู้ว่าทำให้พวกมันเจ็บ\n\nพูดจริงจัง ขอบคุณสำหรับทุกสิ่งที่ผ่านมา หลายสัปดาห์ข้าล่องลอยไร้จุดหมายรอบไร่เหมือนรอจุดจบ ตอนนี้เริ่มมีหวังอีกครั้ง\n\nFerauu กับพวกจะมาได้ทุกเมื่อ เหลือแค่ออกไปเผชิญ ว่าอย่างไร จะอยู่จนจบกับข้าไหม?" },
        progress = { "134:2101148705:1030784422", "หากนำหน้ากากโจรมาได้พอ ข้าอาจเย็บเป็นผ้าห่มให้ Ferauu\n\n<Aamelia หัวเราะดัง>" },
        required = { [253596] = { "25:298954141:1785818252", "หน้ากากโจรเปื้อนเลือด" } },
        steps = { { "25:298954141:1785818252", "หน้ากากโจรเปื้อนเลือด" } },
    },
    [92693] = { -- Standing Our Ground
        title = { "19:420278447:1662364931", "ยืนหยัดรักษาที่มั่น" },
        objective = { "78:1833486022:797153311", "คุยกับ Aamelia Windfield เมื่อพร้อมเผชิญหัวหน้าโจร" },
        description = { "414:1446251818:291687399", "เจ้าช่วยมากจนเรามีโอกาสสู้ แม้ตายวันนี้ อย่างน้อยก็รู้ว่าพยายามเต็มที่แล้ว\n\nนี่คือโอกาสสุดท้าย คนแปลกหน้า หากอยากกลับ Valanaar เพื่อมีชีวิตต่อ ข้าไม่โทษ\n\nแต่ถ้าชอบสู้เรื่องสิ้นหวังจริง ๆ บอกเมื่อพร้อม เราจะเชิดหน้าเดินออกไป เกิดอะไรขึ้นก็ให้เกิด" },
        progress = { "64:30645264:1640134421", "ต่อให้ Stormapple ทั้ง Skywall ก็ไม่พอชดใช้บุญคุณนี้" },
        completion = { "105:1603883010:1962020230", "ข้า... ไม่อยากเชื่อว่าจบแล้ว ต้องหยุดสงบใจ ก่อนหัวใจจะกระโจนออกจากอก", variants = { { "105:1323155475:1701608342", "ข้า... ไม่อยากเชื่อว่าจบแล้ว ต้องหยุดสงบใจ ก่อนหัวใจจะกระโจนออกจากอก" } } },
        steps = { { "28:348284278:400520611", "คุยกับ Aamelia Windfield" }, { "40:1786478595:1622786591", "ตาม Aamelia ไปแล้วสู้จนถึงที่สุด" } },
    },
    [92698] = { -- What Is My Purpose?
        title = { "19:469466190:945978510", "จุดประสงค์ของข้าคืออะไร?" },
        objective = { "72:1577560593:39698429", "คุยกับ Aamelia Windfield เรื่อง Malfunctioning Cyclone Construct" },
        description = { "279:342429447:152348107", "<เจ้าโน้มเข้าใกล้ พยายามฟังคำใต้แผ่นเกราะของสิ่งสร้างยักษ์>\n\n...การทำงานผิดพลาด...\n\n...คำถาม...\n\n...อะไรคือ...\n\n...หน้าที่...\n\n<คำและประโยคกระจัดกระจายวนซ้ำ บางทีคนใกล้ ๆ อาจรู้เรื่องสิ่งสร้างนี้มากกว่า?>" },
        completion = { "497:486855899:1759438414", "สิ่งสร้างนั่นหรือ? เดินวนในทุ่งมาหลายสิบปีแล้ว ข้าว่าตั้งแต่ธาตุลมจากไป Alvarion คิดว่าเคยขนผลผลิตไปตลาด หรือดูแลปศุสัตว์ก่อนที่นี่เป็นสวน แต่นั่นอาจพันปีก่อน\n\nสมัยก่อน Windshaper ดูแลสิ่งสร้างพวกนี้ เราเคยคุยจะขอให้มาตรวจ แต่ไม่ใช่เรื่องเร่งด่วน ทุกวันนี้ส่วนใหญ่ก็ไม่สนใจมัน" },
    },
    [92699] = { -- The Supreme Magister
        title = { "20:1978604066:837123352", "จอมเวทสูงสุด" },
        objective = { "35:885814076:504071639", "ไปหา Elaadrin Evengale ใน Valanaar" },
        description = { "499:381974131:1339840657", "เมื่อมาถึง Valanaar คงอยากรายงานตัวต่อสมาชิก High Order คนอื่น Supreme Magister คนปัจจุบัน Elaadrin Evengale กับคนของเขาอยู่บ้านพักทางตะวันออกเฉียงใต้สุดของเมือง\n\nระวังด้วย High Order กับ Windshaper ไม่ถูกกันนัก ควรเว้นระยะจาก Windshaper ให้มาก เรามีลัทธิให้กังวลพอแล้ว ข้าจะไม่ยอมให้เกิดความรุนแรงระหว่างฝ่ายบนถนน Valanaar" },
        completion = { "415:293227558:969526175", "สวัสดี ยินดีต้อนรับ Rathiril ส่งสารเวทมาเล่าว่าเจ้ามีแวว\n\nเมื่อยืนตรงหน้า ข้าเข้าใจว่าทำไมเขาแนะนำให้มาหา เจ้ามีรัศมีอาร์เคนสดใสรอบตัว ตอนนี้มีพวกเราไม่กี่คนเหลือความสามารถ ไม่ต้องพูดถึงใจกล้าทำสิ่งจำเป็นเพื่อช่วยบ้าน เจ้ากล้าและแข็งแกร่งพอช่วย High Order หรือไม่?\n\nคงได้เห็นกัน", variants = { { "415:1104438736:165559224", "สวัสดี ยินดีต้อนรับ Rathiril ส่งสารเวทมาเล่าว่าเจ้ามีแวว\n\nเมื่อยืนตรงหน้า ข้าเข้าใจว่าทำไมเขาแนะนำให้มาหา เจ้ามีรัศมีอาร์เคนสดใสรอบตัว ตอนนี้มีพวกเราไม่กี่คนเหลือความสามารถ ไม่ต้องพูดถึงใจกล้าทำสิ่งจำเป็นเพื่อช่วยบ้าน เจ้ากล้าและแข็งแกร่งพอช่วย High Order หรือไม่?\n\nคงได้เห็นกัน" } } },
    },
    [92700] = { -- The Grand Skyseer
        title = { "17:1442850906:1781561139", "ผู้หยั่งรู้ฟ้าผู้ยิ่งใหญ่" },
        objective = { "35:996349689:1874728200", "ไปหา Ayessa Dawnsinger ใน Valanaar" },
        description = { "473:1053244094:1092028786", "เมื่อมาถึง Valanaar คงอยากรายงานตัวต่อ Windshaper คนอื่น Grand Skyseer คนปัจจุบันกับคนของนางอยู่บ้านพักใกล้ใจกลางเมือง\n\nควรรู้ด้วยว่า Windshaper กับ High Order ไม่ถูกกันนัก ควรเว้นระยะจาก High Order ให้มาก เรามีลัทธิให้กังวลพอแล้ว ข้าจะไม่ยอมให้เกิดความรุนแรงระหว่างฝ่ายบนถนน Valanaar" },
        completion = { "413:1008944586:1007541388", "Elder Amberwind ส่งสารเล่าวีรกรรมใน Shen'dar Village ยินดีต้อนรับอย่างยิ่ง สหาย\n\nเจ้ามีรัศมีเข้มแข็ง ชัดว่าประสานกับวิญญาณได้ ช่วงหลังมีผู้มี Skysight น้อยลงเรื่อย ๆ Zephras ต้องการผู้มีพรหากจะรอดยุคทดสอบนี้ ยินดีที่เจ้าหาทางมาถึงข้า\n\nข้ารอคอยจะรู้จักให้มากขึ้น" },
    },
    [92701] = { -- To Valanaar
        title = { "11:143351137:736344242", "ไป Valanaar" },
        objective = { "65:2145836366:1867972722", "ส่ง Aonda's Written Report ให้ Valennia Stormfist ใน Valanaar" },
        description = { "490:2041328015:936351245 N 1:46:46", "ตอนนี้ดูว่าเสาไพลอนและหมู่บ้านปลอดภัยแล้ว ข้าอยากให้ส่งรายงานแก่ Valennia Stormfist ใน Valanaar ริมเกาะตะวันออกเฉียงใต้ นางนำผู้รักษาความสงบบนเกาะและต้องรู้ว่าเกิดอะไรขึ้น\n\nลัทธิขยายตัวรวดเร็ว ผู้รักษาความสงบหลีกเลี่ยงปะทะตรงมาตลอด แต่วันเหล่านั้นจบแล้ว Valanaar ต้องพร้อมสู้\n\nอย่างไรขอขอบคุณ เจ้าจะมีสหายใน Shen'dar เสมอ {name}", variants = { { "494:621019383:1653326123 N 1:46:46", "ตอนนี้ดูว่าเสาไพลอนและหมู่บ้านปลอดภัยแล้ว ข้าอยากให้ส่งรายงานแก่ Valennia Stormfist ใน Valanaar ริมเกาะตะวันออกเฉียงใต้ นางนำผู้รักษาความสงบบนเกาะและต้องรู้ว่าเกิดอะไรขึ้น\n\nลัทธิขยายตัวรวดเร็ว ผู้รักษาความสงบหลีกเลี่ยงปะทะตรงมาตลอด แต่วันเหล่านั้นจบแล้ว Valanaar ต้องพร้อมสู้\n\nอย่างไรขอขอบคุณ เจ้าจะมีสหายใน Shen'dar เสมอ {name}" } } },
        progress = { "62:33815804:1724575298", "จดหมายจาก Aonda ชาวที่สูงเจ้าเล่ห์คนนั้นทำอะไรอยู่อีก?" },
        completion = { "497:1070735081:1610927837", "<สีหน้า Valennia หม่นลงขณะอ่านจดหมาย>\n\nAonda ไว้ใจให้ส่งสิ่งนี้ และชมเจ้าในจดหมายมากพอ ข้าจะพยายามไว้ใจด้วย ก่อนคุยต่อ ต้องปรึกษา Peacekeeper ไม่กี่คนที่ข้าเหลือ วางแผนเผื่อลัทธิโจมตีที่นี่ต่อ ระหว่างนี้พักใน Valanaar ให้สบาย\n\nหากอยากหางาน ชาวเมืองมากมายคงพึ่งแรงนักผจญภัยหนุ่มสาวแข็งแกร่งเช่นเจ้าได้" },
        required = { [253152] = { "22:370421703:553780513", "รายงานลายลักษณ์อักษรของ Aonda" } },
        steps = { { "22:370421703:553780513", "รายงานลายลักษณ์อักษรของ Aonda" } },
    },
    [92703] = { -- Deliver the News
        title = { "16:713564049:1682587148", "นำข่าวไปบอก" },
        objective = { "42:465123873:1280506816", "คุยกับ Alvarion Windfield ใน Valanaar" },
        description = { "100:283955673:1134124273 N 384:321587874:1348405435", "หลังเรื่องทั้งหมด คงไม่เหมาะจะเรียกคนแปลกหน้าอีกแล้ว... ขอบคุณ {name}\n\nหากไม่ลำบากและกลับทางนั้น โปรดบอก Alvarion ว่าเกิดอะไรขึ้น และเมื่อยืนไหวแล้ว ให้พา Windshaper มาดูสิ่งสร้าง ให้แน่ใจว่าปลอดภัยต่อ... ครอบครัวของเรา\n\n<Aamelia แตะท้องเบา ๆ>\n\nเขายังไม่รู้เรื่องส่วนนี้ เก็บไว้ระหว่างเราก่อนนะ" },
        completion = { "386:1263629744:489609129", "น้ำตาคลอ Alvarion เมื่อเจ้าเล่าเรื่องที่สวนจบ\n\nข้าไม่รู้จะขอบคุณอย่างไร สหาย ข้ามา Valanaar เพื่อหาความหวัง เกือบแน่ใจว่าหวังลม ๆ แล้ง ๆ แต่กลับพบวีรบุรุษ วีรบุรุษจริงดังเรื่องเล่าก่อนเรามา Skywall\n\nข้าจะไม่ลืมสิ่งที่ทำให้เรา บ้าน Windfield ยินดีต้อนรับเจ้าเสมอ", variants = { { "333:746299659:1158228516 N 49:1132293061:2124030304", "น้ำตาคลอ Alvarion เมื่อเจ้าเล่าเรื่องที่สวนจบ\n\nข้าไม่รู้จะขอบคุณอย่างไร สหาย ข้ามา Valanaar เพื่อหาความหวัง เกือบแน่ใจว่าหวังลม ๆ แล้ง ๆ แต่กลับพบวีรบุรุษ วีรบุรุษจริงดังเรื่องเล่าก่อนเรามา Skywall\n\nข้าจะไม่ลืมสิ่งที่ทำให้เรา {name} บ้าน Windfield ยินดีต้อนรับเจ้าเสมอ" } } },
    },
    [92708] = { -- A Grand Adventure
        title = { "17:557332716:960030546", "การผจญภัยครั้งยิ่งใหญ่" },
        objective = { "44:2000483623:1762622920", "ฟังสิ่งที่ Ayessa Dawnsinger พูด" },
        description = { "412:1540745107:1916200537", "Windshaper ทำงานหนักเพื่อรับวิกฤตบน Zephras Isle เราค้นพบเรื่องน่าประหลาดหลายอย่างระหว่างตามหาวิญญาณลมที่หายไป และกำลังวางแผนให้ได้วิธีช่วยเกาะ\n\nแต่ต้องการนักผจญภัยหนุ่มสาวเข้มแข็งเช่นเจ้า หากพอมีเวลา โปรดคุยรายละเอียดกันต่อ", variants = { { "413:346886942:922337636", "Windshaper ทำงานหนักเพื่อรับวิกฤตบน Zephras Isle เราค้นพบเรื่องน่าประหลาดหลายอย่างระหว่างตามหาวิญญาณลมที่หายไป และกำลังวางแผนให้ได้วิธีช่วยเกาะ\n\nแต่ต้องการนักผจญภัยหนุ่มสาวเข้มแข็งเช่นเจ้า หากพอมีเวลา โปรดคุยรายละเอียดกันต่อ" } } },
        completion = { "345:626178871:397154594", "เห็นแล้วหรือยัง? นอก Skywall มีโลกแห่งความรู้และศักยภาพที่ยังไม่ใช้ ที่นี่จะเป็นบ้านเสมอ แต่ข้าเชื่อแล้วว่าทางรอดอยู่ข้างล่าง ต้องไป Azeroth รับพลังและหนทางช่วย Zephras Isle นี่คือวิถี\n\nเมื่อถึงเวลา เจ้าจะกล้าร่วมไปกับเราไหม?" },
        steps = { { "16:1048245907:198433650", "ฟังสิ่งที่ Ayessa จะบอก" } },
    },
    [92709] = { -- A Grand Adventure
        title = { "17:557332716:960030546", "การผจญภัยครั้งยิ่งใหญ่" },
        objective = { "56:231134516:11568368", "ฟังสิ่งที่ Elaadrin Evengale ใน Valanaar พูด" },
        description = { "241:1408805754:712422642", "สายเลือด Highborne เปล่งในตาชัดดุจฟ้า เจ้าเป็นพวกเดียวกับเรา เยาวชนเช่นเจ้าจะช่วยบ้าน แต่ก่อนอื่น ให้ข้าเล่าภารกิจและแผนบน Zephras... และไกลกว่านั้น", variants = { { "239:1386474868:85082733", "สายเลือด Highborne เปล่งในตาชัดดุจฟ้า เจ้าเป็นพวกเดียวกับเรา เยาวชนเช่นเจ้าจะช่วยบ้าน แต่ก่อนอื่น ให้ข้าเล่าภารกิจและแผนบน Zephras... และไกลกว่านั้น" } } },
        completion = { "490:1901468933:858771439", "ตอนนี้เห็นแล้วหรือยัง? การค้นคืนเวทโบราณของบรรพชนคือกุญแจไขความลับ Zephras Isle และรักษาอนาคต แต่หากจะช่วยบ้าน ต้องค้นคืนสิ่งที่สูญในหลายพันปี\n\nAzeroth คือกุญแจ Kirin Tor จะชี้ทาง\n\nระหว่างเตรียมออกเดินทาง ควรไปหา High Order คนอื่นใน Valanaar ส่วนใหญ่มีงานที่ต้องพึ่งคนเช่นเจ้าช่วยให้สำเร็จ" },
        steps = { { "18:989490817:1656608880", "ฟังสิ่งที่ Elaadrin จะบอก" } },
    },
    [92727] = { -- The Missing Scholar
        title = { "19:1362464627:539499171", "นักปราชญ์ที่หายไป" },
        objective = { "44:1730606217:188493784", "สืบว่าเกิดอะไรขึ้นกับ Fillion Flamebreeze" },
        description = { "504:799990742:1988405981", "การแสวงหาความรู้คือหน้าที่หลักของ High Order แต่ไม่เคยอันตรายเท่าบน Zephras ในวันนี้\n\nนักปราชญ์ Fillion Flamebreeze เดินทางไป Shen'dar Highlands เพื่อเก็บข้อมูลเวทในสายลมซึ่งรวมตัวบางบริเวณ น่าเสียดายที่ยังไม่กลับ เรากลัวว่าอาจประสบเหตุบนถนน\n\nหากทำได้ โปรดตามหา มีผู้เห็นครั้งสุดท้ายบนถนนตะวันตกจาก Valanaar ไป Shen'dar Highlands", variants = { { "495:205016899:505010706", "การแสวงหาความรู้คือหน้าที่หลักของ High Order แต่ไม่เคยอันตรายเท่าบน Zephras ในวันนี้\n\nนักปราชญ์ Fillion Flamebreeze เดินทางไป Shen'dar Highlands เพื่อศึกษาเวทมนตร์ในสายลมซึ่งรวมตัวบางบริเวณ น่าเสียดายที่ยังไม่กลับ เรากลัวว่าอาจประสบเหตุบนถนน\n\nหากทำได้ โปรดตามหา มีผู้เห็นครั้งสุดท้ายบนถนนตะวันตกจาก Valanaar ไป Shen'dar Highlands" } } },
        completion = { "206:1601553659:1181380194", "กระเป๋าตรงหน้ามีจุดคล้ายเลือดแห้งบนฝาปิด เมื่อศึกษารอย เจ้าสังเกตชื่อปักบนฝาว่า Fillion Flamebreeze", variants = { { "208:998962968:1658446155", "กระเป๋าตรงหน้ามีจุดคล้ายเลือดแห้งบนฝาปิด เมื่อศึกษารอย เจ้าสังเกตชื่อปักบนฝาว่า Fillion Flamebreeze" }, { "212:410871229:901601145", "<บนฝากระเป๋าตรงหน้ามีจุดเล็ก ๆ คล้ายคราบเลือดแห้ง พอเพ่งดูคราบ เจ้าก็เห็นว่าบนฝามีชื่อปักไว้ด้วย อ่านว่า «Fillion Flamebreeze»>" } } },
    },
    [92741] = { -- Unwelcome Visitors
        title = { "18:927189553:1484234876", "ผู้มาเยือนที่ไม่ต้อนรับ" },
        objective = { "96:1193524451:1912597908", "ไป Shadowgale Forest แล้วรวบรวม Shriekling Talons 8 ชิ้นให้ Iaadaria Bitterwind ใน Valanaar" },
        description = { "499:586919522:1372859333", "Shadowgale Forest อันตรายยิ่ง ปกติห้ามนักผจญภัยทั่วไปเข้า ช่วงหลายเดือนจำนวน Shriekling พุ่งและเริ่มขยายอาณาเขตนอกป่า อาจเป็นปัญหา ข้าสนใจคุณสมบัติแปรธาตุของกรงเล็บ การลดจำนวนที่จำเป็นจึงเปิดโอกาสทางวิชาการด้วย\n\nไป Shadowgale Forest ล่าสัตว์พวกนั้น นำกรงเล็บมาให้มากเท่าที่ทำได้" },
        progress = { "219:1584392735:262291250", "High Order ไม่ชินกับการรับหน้าที่แค่พรานดักสัตว์หรือผู้ดูแลสัตว์ป่า แต่หากงานเช่นนี้ช่วยความก้าวหน้าทางวิชาการ เรายินดีรับใช้ชุมชน", variants = { { "221:237062962:1475813025", "High Order ไม่ชินกับการรับหน้าที่แค่พรานดักสัตว์หรือผู้ดูแลสัตว์ป่า แต่หากงานเช่นนี้ช่วยความก้าวหน้าทางวิชาการ เรายินดีรับใช้ชุมชน" } } },
        completion = { "141:770495337:1562744463", "กรงเล็บที่นำมาไม่น้อยเลย ข้าแทบรอศึกษาไม่ไหว!\n\nขอบคุณที่รับใช้ High Order นักผจญภัย", variants = { { "130:1326886932:1811020145 C 1:46:46", "กรงเล็บที่นำมาไม่น้อยเลย ข้าแทบรอศึกษาไม่ไหว!\n\nขอบคุณที่รับใช้ High Order {class}" } } },
        required = { [254378] = { "17:936986494:710789143", "กรงเล็บ Shriekling" } },
        steps = { { "17:936986494:710789143", "กรงเล็บ Shriekling" } },
    },
    [92834] = { -- Avenged Tenfold
        title = { "15:2117149667:1826645171", "ชำระแค้นสิบเท่า" },
        objective = { "126:2085877606:1501798504", "รวบรวม Al'Aketh Windstone Charms 10 ชิ้นจากสาวก Al'Aketh ทางเหนือของ Valanaar ที่ Gustberry Fields หรือ Shrine of Akir" },
        description = { "503:1022484079:300498159", "เมื่อลัทธิเริ่มใช้ความรุนแรง Peacekeeper กับ Windshaper ตอบด้วยการแสดงแสนยานุภาพ ข้าเห็นว่าเป็นการยกระดับโง่เขลา จึงเสนอเจรจาสงบ เมื่อวานส่งสหาย Belathaan Brightwish ไป Shrine of Akir เพื่อเปิดการพูดคุย\n\nกล่องเพิ่งมาถึง ข้างในเป็นลิ้น Belathaan จุ่มสีเงิน\n\nตอนนี้ชัดว่าใช้เหตุผลกับลัทธิไม่ได้ ฆ่าสาวกทุกคนที่เห็น แล้วนำเครื่องรางสวดมนต์ที่พกมาให้ข้า", variants = { { "502:633484080:1878538780", "เมื่อลัทธิเริ่มใช้ความรุนแรง Peacekeeper กับ Windshaper ตอบด้วยการแสดงแสนยานุภาพ ข้าเห็นว่าเป็นการยกระดับโง่เขลา จึงเสนอเจรจาสงบ เมื่อวานส่งสหาย Belathaan Brightwish ไป Shrine of Akir เพื่อเปิดการพูดคุย\n\nกล่องเพิ่งมาถึง ข้างในเป็นลิ้น Belathaan จุ่มสีเงิน\n\nตอนนี้ชัดว่าใช้เหตุผลกับลัทธิไม่ได้ ฆ่าสาวกทุกคนที่เห็น แล้วนำเครื่องรางสวดมนต์ที่พกมาให้ข้า" } } },
        progress = { "259:1753029789:1400684099", "ข้าไม่ค่อยเห็นด้วยกับ Windshaper แต่พวกเขาคิดถูกที่ปฏิเสธเจรจาสงบกับ Al'Aketh ความพยายามเลือกทางสูงส่งทำให้สหายรักเสียชีวิต เป็นความผิดที่ข้าต้องแบกตลอดวันเวลาที่เหลือ" },
        completion = { "354:528149958:972538986", "High Order ภูมิใจในความเป็นจริงและเหตุผล เหตุผลบอกว่าหลีกเลี่ยงความขัดแย้งและสูญชีวิตเป็นทางรอบคอบที่สุดในสถานการณ์ส่วนใหญ่\n\n<ดวงตา Elaadrin เริ่มเรืองและปะทุพลังอาร์เคน>\n\n...แต่ลัทธิกลับมองความรอบคอบเป็นความอ่อนแอ พวกมันยังไม่พร้อมจ่ายราคาที่เข้าใจผิดนั้นเลย" },
        required = { [255658] = { "24:1773871514:1765551057", "เครื่องรางหินลมของ Al'Aketh" } },
        steps = { { "24:1773871514:1765551057", "เครื่องรางหินลมของ Al'Aketh" } },
    },
    [92840] = { -- Catching Wind
        title = { "13:1275218299:1202747376", "จับกระแสลม" },
        objective = { "144:1490106666:759379819", "นำ Index Esoteria ไป Overlook Standing Stones ใน Shen'dar Highlands แล้วใช้กับ Windstone Formations บริเวณนั้นเพื่อเก็บข้อมูล" },
        description = { "448:676722556:1976773507", "Fillion ถูกส่งไป Overlook Standing Stones พร้อมเครื่องมือพิเศษวัดและศึกษาพลังธาตุที่นั่น\n\nรับ Index Esoteria นี้ไป ใช้ดึงข้อมูลจากกลุ่ม Windstone มหึมาซึ่งก่อตัวที่นั่น แต่ระวัง Windshaper น่าจะเฝ้าพื้นที่อย่างหวงแหนแล้ว\n\nหากมีใครขวาง... ก็ทำสิ่งจำเป็น ข้าไม่อดทนต่อการแทรกแซงอีกแล้ว" },
        progress = { "473:2136852583:1443723070", "ข้าแยก Windshaper กับ Al'Aketh ได้ยาก นอกจากฝ่ายหนึ่งใช้ความรุนแรงเปิดเผยกว่า ต่างตกเป็นทาสความเชื่อผิดที่ และอันตรายเท่ากันหากปล่อยตามใจ\n\nพวกเขามองความต้องการเข้าใจภพนี้และเวทให้ดีขึ้นว่าเป็นการลบหลู่ธรรมเนียม ความคับแคบนั้นทำให้ภารกิจเราสำคัญ หากไม่ใช่เรา ใครจะกล้าช่วย Zephras?" },
        completion = { "459:672978177:1611542944", "ข้าไม่ได้อยากหลั่งเลือด Windshaper แต่โทษของความขัดแย้งไร้ความหมายอยู่ที่พวกเขาเท่านั้น เราต้องการเก็บข้อมูลอย่างสงบ พวกเขาตอบด้วยความรุนแรง\n\nน่าเสียดาย ข่าวแพร่แล้ว Windshaper เรียกว่าเป็นการสังหารหมู่ พวกเขาไม่กล้าตอบโต้ใน Valanaar แต่ไม่ลืมแน่\n\nสหาย เจ้าช่วย High Order มาก ขอบคุณ", variants = { { "390:271265884:179586989 N 63:1598848298:1581022960", "ข้าไม่ได้อยากหลั่งเลือด Windshaper แต่โทษของความขัดแย้งไร้ความหมายอยู่ที่พวกเขาเท่านั้น เราต้องการเก็บข้อมูลอย่างสงบ พวกเขาตอบด้วยความรุนแรง\n\nน่าเสียดาย ข่าวแพร่แล้ว Windshaper เรียกว่าเป็นการสังหารหมู่ พวกเขาไม่กล้าตอบโต้ใน Valanaar แต่ไม่ลืมแน่\n\n{name} เจ้าช่วย High Order มาก ขอบคุณ" } } },
        required = { [254584] = { "14:588332556:1885993729", "สารบัญศาสตร์ลี้ลับ" } },
        steps = { { "33:774864856:744846127", "เก็บข้อมูลกระแสพลังธาตุ" }, { "14:588332556:1885993729", "สารบัญศาสตร์ลี้ลับ" } },
    },
    [92849] = { -- The Missing Scholar
        title = { "19:1362464627:539499171", "นักปราชญ์ที่หายไป" },
        objective = { "39:1585689567:2016290951", "ตามหา Fillion Flamebreeze ต่อ" },
        description = { "258:1581574509:248928671", "<จากสิ่งที่พบ เป็นไปได้มากว่า Fillion ประสบเคราะห์ที่นี่ เขาอาจยังอยู่ใกล้และต้องการความช่วยเหลือ เจ้าสังเกตถ้ำทางเหนือไม่ไกล ควรค้นหาต่อที่นั่น>", variants = { { "257:1218348002:1699993593", "<จากสิ่งที่พบ เป็นไปได้มากว่า Fillion ประสบเคราะห์ที่นี่ เขาอาจยังอยู่ใกล้และต้องการความช่วยเหลือ เจ้าสังเกตถ้ำทางเหนือไม่ไกล ควรค้นหาต่อที่นั่น>" } } },
        completion = { "473:1696710571:1541760604", "ขะ... ขอบคุณ คนแปลกหน้า ข้ากลับจากงานที่ Overlook Standing Stones แล้วถูก Windshaper ซุ่มโจมตี พวกเขาบังคับไปปากถ้ำและทิ้งไว้เลือดไหลแทบหมดสติ สิ่งสุดท้ายที่จำได้ก่อนดับวูบคือสัตว์มีปีกมหึมาออกจากถ้ำแล้วคว้าข้า\n\nพูดได้เต็มปากว่าถ้าเจ้าไม่มา ข้าคงเป็นมื้อเย็นของมันกับลูก ๆ", variants = { { "473:722136940:1194830343", "ขะ... ขอบคุณ คนแปลกหน้า ข้ากลับจากงานที่ Overlook Standing Stones แล้วถูก Windshaper ซุ่มโจมตี พวกเขาบังคับไปปากถ้ำและทิ้งไว้เลือดไหลแทบหมดสติ สิ่งสุดท้ายที่จำได้ก่อนดับวูบคือสัตว์มีปีกมหึมาออกจากถ้ำแล้วคว้าข้า\n\nพูดได้เต็มปากว่าถ้าเจ้าไม่มา ข้าคงเป็นมื้อเย็นของมันกับลูก ๆ" }, { "373:2106351584:1719380419", "ขะ... ขอบคุณนะ คนแปลกหน้า ข้ากำลังเดินมาตามถนนเพื่อกลับ Valanaar จู่ ๆ ก็มีเงาทะมึนปรากฏขึ้นเหนือหัว พอหันไปมองก็เห็นสัตว์ร้ายตัวมหึมาพุ่งลงมาจากฟ้าตรงมาที่ข้า ข้าพยายามวิ่งหนี แต่โดนกระแทกอย่างแรง แล้วทุกอย่างก็มืดดับไป\n\nถ้าเจ้าไม่มาช่วย ข้าคงกลายเป็นมื้อเย็นของเจ้าสัตว์ร้ายนั่นกับลูก ๆ ของมันไปแล้ว" } } },
        steps = { { "24:1895821653:536220595", "ตามหา Fillion Flamebreeze" }, { "58:689136375:791289889", "พา Fillion Flamebreeze ไปยังที่ปลอดภัยโดยหลบศัตรูระหว่างทาง" } },
    },
    [92850] = { -- The Missing Scholar
        title = { "19:1362464627:539499171", "นักปราชญ์ที่หายไป" },
        objective = { "108:1178360363:841412852", "สังหาร Shriekling Matriarch ใน Shriekling Den แล้วนำหัวกลับไปให้ Fillion Flamebreeze ใน Valanaar", variants = { { "111:1759323323:1157384760", "สังหาร Shriekling Matriarch ใน Shriekling Den แล้วนำหัวกลับไปให้ Dondallion Whisperwind ใน Valanaar" } } },
        description = { "487:22742583:1311965195", "ข้าดีขึ้นมากแล้ว มีทักษะอาร์เคนบ้างและอยู่ไม่ไกล Valanaar กลับเองได้ แต่สิ่งสำคัญกว่าความปลอดภัยข้าคือ Shriekling ทำรังใกล้เมืองเพียงใดและอันตรายที่ก่อ หากเมตตา โปรดกลับเข้าไปเก็บหัวสัตว์นั่น!\n\nเสร็จแล้วพบข้าใน Valanaar ต้องรายงาน Supreme Magister ถึงเหตุการณ์และสถานะภารกิจ", variants = { { "498:798569790:2022253214", "ข้ารู้สึกดีขึ้นมากแล้ว ข้าพอใช้เวทอาร์เคนได้อยู่บ้าง และที่นี่ก็อยู่ไม่ไกลจาก Valanaar ข้ากลับเองได้ แต่ที่น่าห่วงกว่าความปลอดภัยของข้าคือพวก Shriekling มาทำรังใกล้ Valanaar ขนาดนี้ พวกมันเป็นภัย หากเจ้าจะกรุณา ช่วยกลับเข้าไปแล้วเอาหัวของเจ้าสัตว์ร้ายนั่นมาที!\n\nเสร็จแล้วไปหาข้ากับ Dondallion ที่ Valanaar นะ ข้าต้องรีบกลับไปหาเขา ป่านนี้เขาคงร้อนใจแทบแย่แล้ว" }, { "485:862331100:309288315", "ข้าดีขึ้นมากแล้ว มีทักษะอาร์เคนบ้างและอยู่ไม่ไกล Valanaar กลับเองได้ แต่สิ่งสำคัญกว่าความปลอดภัยข้าคือ Shriekling ทำรังใกล้เมืองเพียงใดและอันตรายที่ก่อ หากเมตตา โปรดกลับเข้าไปเก็บหัวสัตว์นั่น!\n\nเสร็จแล้วพบข้าใน Valanaar ต้องรายงาน Supreme Magister ถึงเหตุการณ์และสถานะภารกิจ" } } },
        progress = { "125:2021211463:1811513702", "Shriekling อันตรายเกินปล่อยให้ทำรังใกล้ Valanaar แต่... มันเป็นปัญหาน้อยที่สุดของเรา", variants = { { "125:56731414:2118665342", "Shriekling อันตรายเกินปล่อยให้ทำรังใกล้ Valanaar แต่... มันเป็นปัญหาน้อยที่สุดของเรา" }, { "20:2067245654:91326814", "เจ้า Fillion ทึ่มเอ๊ย..." } } },
        completion = { "24:874093716:81197839", "ขอบคุณอีกครั้ง สหาย", variants = { { "17:689065638:2099367606 N 1:46:46", "ขอบคุณอีกครั้ง {name}" }, { "197:2031160902:444173086 C 1:46:46", "ข้ายอมรับว่าโล่งอกเหลือเกินที่ Fillion กลับมาหาพวกเราแล้ว เขาไม่ค่อยระวังตัวเอาเสียเลย เอาแต่เหม่อลอยหรือไม่ก็ก้มหน้าอ่านหนังสืออยู่ตลอด\n\nขอบคุณนะ {class}" } } },
        required = { [257107] = { "27:775813953:1363996410", "หัวของ Shriekling Matriarch" } },
        steps = { { "27:775813953:1363996410", "หัวของ Shriekling Matriarch" } },
    },
    [92860] = { -- In Service of Zephras
        title = { "21:1778381045:1500340020", "รับใช้ Zephras" },
        objective = { "111:813185309:1035364166", "รายงานต่อ Valennia Stormfist ว่า High Order จะร่วมต่อสู้ Al'Aketh กับพวกเขา", variants = { { "115:111819028:725246586", "รายงานต่อ Valennia Stormfist ว่า High Order จะร่วมต่อสู้ Al'Aketh กับพวกเขา" } } },
        description = { "493:763379008:506329546", "High Order พยายามหลีกเลี่ยงปะทะลัทธิโดยตรง แต่ชัดว่าไม่มีทางเลือกแล้ว ความเป็นศัตรูปรากฏชัด ตอนนี้มีข่าวลือการเคลื่อนไหวใหญ่ทั่วเกาะ พวกมันเตรียมอะไรบางอย่าง ซึ่งไม่ว่าจะเป็นอะไรย่อมไม่ดีต่อชาว Zephras\n\nรายงานต่อ Valennia Stormfist ว่า High Order พร้อมหนุนเต็มที่ในการต่อต้าน Al'Aketh ของ Valanaar เมื่อจำเป็น", variants = { { "490:532984530:805001245", "High Order พยายามหลีกเลี่ยงปะทะลัทธิโดยตรง แต่ชัดว่าไม่มีทางเลือกแล้ว ความเป็นศัตรูปรากฏชัด ตอนนี้มีข่าวลือการเคลื่อนไหวใหญ่ทั่วเกาะ พวกมันเตรียมอะไรบางอย่าง ซึ่งไม่ว่าจะเป็นอะไรย่อมไม่ดีต่อชาว Zephras\n\nรายงานต่อ Valennia Stormfist ว่า High Order พร้อมหนุนเต็มที่ในการต่อต้าน Al'Aketh ของ Valanaar เมื่อจำเป็น" } } },
        completion = { "226:1278113090:940501595", "เสียใจที่ได้ยินเรื่อง Belathaan เขาเป็นลูกพี่ลูกน้องข้า เป็นนักผจญภัยและผู้รับใช้ Zephras ที่ดี เราจะล้างแค้นให้\n\nเจ้าดูกระตือรือร้นจะช่วยทันที มาเถิด คุยสถานการณ์ปัจจุบันกันต่อ", variants = { { "220:942219932:2091628135", "เสียใจที่ได้ยินเรื่อง Belathaan เขาเป็นลูกพี่ลูกน้องข้า เป็นเมจและผู้รับใช้ Zephras ที่ดี เราจะล้างแค้นให้\n\nเจ้าดูกระตือรือร้นจะช่วยทันที มาเถิด คุยสถานการณ์ปัจจุบันกันต่อ" } } },
    },
    [92871] = { -- In Service of Zephras
        title = { "21:1778381045:1500340020", "รับใช้ Zephras" },
        objective = { "117:910906852:267584255", "รายงานต่อ Valennia Stormfist ว่า Windshaper จะร่วมต่อสู้ Al'Aketh กับพวกเขา" },
        description = { "398:1579051929:928783772", "Valennia Stormfist กับผู้รักษาความสงบเป็นผู้พิทักษ์ Zephras มาตลอด เราพยายามช่วยเท่าที่ทำได้ มีข่าวลือการเคลื่อนไหวใหญ่ของลัทธิทั่วเกาะ ชัดว่ากำลังเตรียมบางสิ่ง\n\nรายงานต่อ Valennia ย้ำว่า Windshaper พร้อมหนุนเต็มที่ในการต่อต้าน Al'Aketh ของ Valanaar เมื่อจำเป็น", variants = { { "396:1613328756:1976310053", "Valennia Stormfist กับผู้รักษาความสงบเป็นผู้พิทักษ์ Zephras มาตลอด เราพยายามช่วยเท่าที่ทำได้ มีข่าวลือการเคลื่อนไหวใหญ่ของลัทธิทั่วเกาะ ชัดว่ากำลังเตรียมบางสิ่ง\n\nรายงานต่อ Valennia ย้ำว่า Windshaper พร้อมหนุนเต็มที่ในการต่อต้าน Al'Aketh ของ Valanaar เมื่อจำเป็น" } } },
        completion = { "91:1299198271:1775879384", "เจ้าดูกระตือรือร้นจะช่วยทันที มาเถิด คุยสถานการณ์ปัจจุบันกันต่อ" },
    },
    [92880] = { -- Return to Valanaar
        title = { "18:874626813:1345910462", "กลับ Valanaar" },
        objective = { "55:1950224134:629041188", "นำ Yorna's Report ไปให้ Valennia Stormfist ใน Valanaar" },
        description = { "394:1537922465:1334431430 C 1:46:46", "คงต้องใช้เวลากวาดล้างผู้โจมตีที่เหลือ แต่ตอนนี้โอกาสดีกว่าเดิมมาก กลับ Valanaar บอกว่าที่นี่มั่นคงแล้ว\n\nขอบคุณเท่าไรก็ไม่พอ ไม่มีเจ้าเราคงแย่กว่านี้มาก ข้าขอกำลังเสริม กลับได้วีรบุรุษที่กำลังเติบโต ยอมรับได้เลย\n\nขอลมทั้งสี่อวยพร {class}" },
        completion = { "108:750642328:645828401", "Valennia โล่งใจอย่างเห็นได้ชัดเมื่อเจ้ารายงานหอเฝ้าระวังตะวันออก\n\nขอบคุณสายลม", variants = { { "110:1738774484:42062222", "Valennia โล่งใจอย่างเห็นได้ชัดเมื่อเจ้ารายงานหอเฝ้าระวังตะวันออก\n\nขอบคุณสายลม" } } },
    },
    [92881] = { -- The High Elder's Request
        title = { "24:449707744:45901061", "คำขอของ High Elder" },
        objective = { "43:702080654:753852318", "คุยกับ Talaanis Shadowsong ใน Valanaar" },
        description = { "356:463895837:478755078", "การโจมตีทั้งหอตะวันตกและตะวันออกไม่ใช่บังเอิญ จากที่เล่าเรื่อง Skypriest ที่หอตะวันตก เราคาดว่าลัทธิพยายามทำบางอย่างกับเสาไพลอนสมอ\n\nโปรดคุยกับ High Elder Shadowsong เขาจะบอกเบาะแสที่อาจมีหวัง", variants = { { "355:1407664448:106382349", "การโจมตีทั้งหอตะวันตกและตะวันออกไม่ใช่บังเอิญ จากที่เล่าเรื่อง Skypriest ที่หอตะวันตก เราคาดว่าลัทธิพยายามทำบางอย่างกับเสาไพลอนสมอ\n\nโปรดคุยกับ High Elder Shadowsong เขาจะบอกเบาะแสที่อาจมีหวัง" } } },
        completion = { "109:1918446525:791828600", "ข้ามีเรื่องเล็กน้อยที่ต้องพึ่งความช่วยเหลือแบบที่นักผจญภัยเช่นเจ้าให้ได้พอดี" },
    },
    [92947] = { -- Making Our Move
        title = { "15:705518947:326649172", "เริ่มลงมือ" },
        objective = { "138:1710166758:1076773691", "สังหาร Al'Aketh Guardians 7 คน, Al'Aketh Spiritcallers 7 คน และ Al'Aketh Blademasters 7 คน แล้วรายงานต่อ Hyusaa Quickbreeze ที่ Shrine of Akir", amount = { "5:1000000866:1065647852 W1 21:654910440:1431671492 W2 29:13836905:398753110 W3 80:1089766304:403175917", "สังหาร Al'Aketh Guardians {world1} คน, Al'Aketh Spiritcallers {world2} คน และ Al'Aketh Blademasters {world3} คน แล้วรายงานต่อ Hyusaa Quickbreeze ที่ Shrine of Akir" } },
        description = { "475:97475685:640834322 C 1:46:46", "มากันครบ ดี ข้าเพิ่งส่งนักสู้ฝีมือดีที่สุดบางคนเข้าหน้าศาลเพื่อก่อเรื่องดึงความสนใจ ระหว่างนำกำลังส่วนใหญ่เข้าด้านข้าง\n\nหากราบรื่น เราจะฝ่าอย่างรวดเร็วและกำจัด High Priestess ส่วนเจ้า เข้าไปจัดการศัตรู ก่อความวุ่นวายแล้วพบรองข้า Hyusaa Quickbreeze ใกล้บันไดศาล\n\nขอสายลมนำทาง {class}", variants = { { "479:77229127:510426303 C 1:46:46", "มากันครบ ดี ข้าเพิ่งส่งนักสู้ฝีมือดีที่สุดบางคนเข้าหน้าศาลเพื่อก่อเรื่องดึงความสนใจ ระหว่างนำ Windshaper กับ High Order เข้าด้านข้าง\n\nหากราบรื่น เราจะฝ่าอย่างรวดเร็วและกำจัด High Priestess ส่วนเจ้า เข้าไปจัดการศัตรู ก่อความวุ่นวายแล้วพบรองข้า Hyusaa Quickbreeze ใกล้บันไดศาล\n\nขอสายลมนำทาง {class}" } } },
        completion = { "53:1482382237:494157536", "เราสู้หนักกว่าจะมาถึงนี่ แต่ยังไม่จบ" },
        progress = { "21:1548041077:1284218522", "<Hyusaa พยักหน้าให้เจ้า>" },
        steps = { { "28:1147529407:1334473999", "ไปรายงานตัวกับ Hyusaa Quickbreeze" } },
        objectiveLabels = {
            monster = { ["Al'Aketh Guardian slain"] = "ปราบ ผู้พิทักษ์ Al'Aketh", ["Al'Aketh Spiritcaller slain"] = "ปราบ ผู้เรียกวิญญาณ Al'Aketh", ["Al'Aketh Blademaster slain"] = "ปราบ ปรมาจารย์ดาบ Al'Aketh" },
        },
    },
    [93036] = { -- Infiltrating the Cult
        title = { "21:1483960547:861368830", "แทรกซึมลัทธิ" },
        objective = { "50:1059807155:807488858", "คุยกับ Sania Silverstream ใน Shen'dar Village" },
        description = { "499:1488570120:1026642962", "เจ้าอาจรู้หรือไม่ว่า Sania Silverstream ตรงนั้นเป็นผู้เผยแผ่ของ Al'Aketh พวกมันทำทีเป็นคณะศาสนาปกติ ส่งทูตไม่คุกคามไปชักชวน เราทน Sania เพื่อเลี่ยงปะทะโดยตรง แต่ชัดว่าภาพลวงความสงบคงอยู่ไม่นาน\n\nเจ้ามาใหม่ คนส่วนใหญ่ไม่รู้จัก ข้าอยากดูว่าจะใช้ Sania เข้าใกล้ลัทธิและสืบแผนต่อหมู่บ้านได้ไหม", variants = { { "498:887633120:1781108998", "เจ้าอาจรู้หรือไม่ว่า Sania Silverstream ตรงนั้นเป็นผู้เผยแผ่ของ Al'Aketh พวกมันทำทีเป็นคณะศาสนาปกติ ส่งทูตไม่คุกคามไปชักชวน เราทน Sania เพื่อเลี่ยงปะทะโดยตรง แต่ชัดว่าภาพลวงความสงบคงอยู่ไม่นาน\n\nเจ้ามาใหม่ คนส่วนใหญ่ไม่รู้จัก ข้าอยากดูว่าจะใช้ Sania เข้าใกล้ลัทธิและสืบแผนต่อหมู่บ้านได้ไหม" } } },
        completion = { "252:1080155664:1568355300", "สวัสดีลูกเอ๋ย ข้าชื่อ Sania Silverstream นักบวชหญิงชั้นต้นใน Order of the Al'Aketh อยากรู้จักองค์อธิปัตย์ Windlord Al'Akir มากขึ้นหรือไม่?\n\nโต๊ะของเจ้าแห่งลมมีที่ให้ผู้ชอบธรรมและผู้สำนึกผิดเสมอ" },
    },
    [93065] = { -- Prepare for Battle
        title = { "18:1457548381:1643803015", "เตรียมพร้อมสู้ศึก" },
        objective = { "56:460391694:828414128", "คุยกับ Valennia Stormfist ใน Gustberry Lowlands" },
