    },
    [93089] = { -- What Comes Next
        title = { "15:1746088516:2040074014", "สิ่งที่จะตามมา" },
        objective = { "73:478710254:373106999", "คุยกับ Elaadrin Evengale เมื่อพร้อมออกจาก Zephras Isle" },
        description = { "499:270679369:1328071746 N 1:46:46", "โปรดขอบคุณ Elaadrin แทนข้า สำหรับสิ่งที่ High Order และสหายใหม่จาก Kirin Tor ทำให้ Zephras Isle ข้ารู้แผนออกจากเกาะ คณะเจ้ามีพรและคำอวยพรจากข้าในการเดินทางนี้\n\nหวังว่าวิธีอาร์เคนที่ High Order พบจะมอบความมั่นคงที่เราขาดมาหลายปีได้จริง หากเจ้าจะไปด้วย... ภารกิจคงแข็งแกร่งขึ้นมาก\n\nขอสายลมอยู่กับเจ้า {name}", variants = { { "498:832271548:351579486 N 1:46:46", "โปรดขอบคุณ Elaadrin แทนข้า สำหรับสิ่งที่ High Order และสหายใหม่จาก Kirin Tor ทำให้ Zephras Isle ข้ารู้แผนออกจากเกาะ คณะเจ้ามีพรและคำอวยพรจากข้าในการเดินทางนี้\n\nหวังว่าวิธีอาร์เคนที่ High Order พบจะมอบความมั่นคงที่เราขาดมาหลายปีได้จริง หากเจ้าจะไปด้วย... ภารกิจของเขาคงแข็งแกร่งขึ้นมาก\n\nขอสายลมอยู่กับเจ้า {name}" } } },
        completion = { "396:464236534:1293256329", "ยินดีที่ High Elder Shadowsong อวยพรการเดินทาง เมื่อลัทธิพ่ายและเตรียมพร้อมแล้ว ข้าว่าถึงเวลาในที่สุด\n\nAnsirem ทำงานหนักช่วยให้เราจัดเรือเหาะ Skycutter ที่มั่นคงระหว่าง Dalaran กับ Zephras Isle ทดสอบเท่าที่ทำได้แล้ว ถึงเวลากองหน้าจะออกเดินทาง" },
    },
    [93090] = { -- What Comes Next
        title = { "15:1746088516:2040074014", "สิ่งที่จะตามมา" },
        objective = { "73:1327210512:2044948003", "คุยกับ Ayessa Dawnsinger เมื่อพร้อมออกจาก Zephras Isle" },
        description = { "431:683744985:43606749 N 1:46:46", "โปรดขอบคุณ Ayessa แทนข้า สำหรับสิ่งที่ Windshaper และสหายใหม่จาก Earthen Ring ทำให้ Zephras Isle ข้ารู้แผนพาชาแมน Windshaper ออกจากเกาะ คณะเจ้ามีพรและคำอวยพรจากข้าในการเดินทางนี้\n\nหวังว่าวิธีที่ Windshaper พบจะมอบความมั่นคงที่เราขาดมาหลายปีได้จริง\n\nขอสายลมอยู่กับเจ้า {name}", variants = { { "430:1079948489:921208993 N 1:46:46", "โปรดขอบคุณ Ayessa แทนข้า สำหรับสิ่งที่ Windshaper และสหายใหม่จาก Earthen Ring ทำให้ Zephras Isle ข้ารู้แผนพาชาแมน Windshaper ออกจากเกาะ คณะเจ้ามีพรและคำอวยพรจากข้าในการเดินทางนี้\n\nหวังว่าวิธีที่ Windshaper พบจะมอบความมั่นคงที่เราขาดมาหลายปีได้จริง\n\nขอสายลมอยู่กับเจ้า {name}" } } },
        completion = { "437:1606660439:1673110789", "ยินดีที่ High Elder Shadowsong อวยพรการเดินทาง เมื่อลัทธิพ่ายและเตรียมพร้อมแล้ว ข้าว่าถึงเวลาในที่สุด\n\nMuln ทำงานหนักช่วยจัด Skycutter ที่มั่นคงระหว่าง Zephras Isle กับที่เรียก Mulgore ซึ่งเป็นบ้าน Earthen Ring เราทดลองเดินเรืออยู่ และคนของเราบางคนรออีกฝั่งแล้ว" },
    },
    [93159] = { -- The Strange Hermit
        title = { "18:1737508469:222197752", "ฤๅษีประหลาด" },
        objective = { "80:1685830042:46270098", "คุยกับ Strange Hermit ใน Shadowgale Forest และเรียนรู้เรื่องเขาเพิ่มเติม" },
        description = { "268:1592112905:1068672219", "เอ่อ อืม... สะ... สวัสดี หมายถึง หวัดดี! หรือยินดีที่พบ! ขอโทษ... คือ ไม่ได้พูดกับคนอื่นมานาน เกรงว่าฝืดไปหน่อย\n\n<ร่างคลุมฮู้ดประหลาดขยับอย่างอึดอัดตรงหน้า>\n\nเอ่อ อืม... วันนี้เป็นอย่างไรบ้าง?", variants = { { "267:287206974:1129329204", "เอ่อ อืม... สะ... สวัสดี หมายถึง หวัดดี! หรือยินดีที่พบ! ขอโทษ... คือ ไม่ได้พูดกับคนอื่นมานาน เกรงว่าฝืดไปหน่อย\n\n<ร่างคลุมฮู้ดประหลาดขยับอย่างอึดอัดตรงหน้า>\n\nเอ่อ อืม... วันนี้เป็นอย่างไรบ้าง?" } } },
        completion = { "429:1112225444:2013352564", "...ก็มีเรื่องจะพูดเท่านี้ ก่อนอยู่ที่นี่ ข้าเคย... เอ่อ... อยู่ที่อื่น ตอนนี้มีเพื่อนกับข้าวของ หะ... หมายถึงของที่สร้างเอง นั่นคือทั้งหมดที่ต้องการ ข้าคิดว่าเท่านั้นนะ\n\nแต่ต้องบอก ดีที่ได้คุยกับคนตอบกลับ วิญญาณป่าก็พยายาม แต่จบด้วยร้องเพลงให้ฟัง มันก็ดีในแบบของมัน แต่ไม่ใช่บทสนทนานะ... น่าตื่นเต้นนัก" },
        progress = { "22:1401648790:548882978", "เรื่องมันเป็นอย่างนี้เอง..." },
        steps = { { "35:498363788:880378418", "สืบเรื่อง Strange Hermit เพิ่มเติม" } },
    },
    [93160] = { -- The Forest's Bounty
        title = { "19:1919021115:1488098680", "ความอุดมแห่งป่า" },
        objective = { "48:2055749345:1641450059", "รวบรวม Shadowgale Acorns 8 ผลใน Shadowgale Forest", amount = { "7:451016854:1830523975 W1 40:162120235:1537242246", "รวบรวม Shadowgale Acorns {world1} ผลใน Shadowgale Forest" } },
        description = { "414:496594633:244756723", "ขอบคุณที่แวะคุย! ถะ... ถ้าอยากช่วย ข้าอยากให้ช่วยเก็บลูกโอ๊กบนพื้นป่า แถวใกล้ ๆ เก็บเกือบหมดแล้ว แต่ในป่ามีนกคล้ายนักล่ามาก อันตราย ข้าไม่อยากเป็นมื้อกลางวันของนกยักษ์!\n\nถ้าต้องการ ช่วยเก็บให้หน่อยได้ไหม? ข้าจะทำของอร่อยให้เรากิน!" },
        progress = { "72:486699410:1017041050", "อืม ข้าว่าเจ้าจะชอบอาหารจากลูกโอ๊กพวกนี้!" },
        completion = { "128:597425375:918936712", "ขอบคุณ คนแปลกหน้า! คั่วแล้วอร่อยมาก\n\nขอตัวก่อน ทำไม่นานหรอก" },
        required = { [257128] = { "10:233419911:1723498025", "เมล็ดเซเฟอร์" } },
        steps = { { "10:233419911:1723498025", "เมล็ดเซเฟอร์" } },
    },
    [93165] = { -- Mercy Falls on Deaf Ears
        title = { "24:274267956:1289506588", "เมตตาที่ไม่มีใครฟัง" },
        objective = { "125:842384617:243815481", "รวบรวม Al'Aketh Cultist's Ears 10 ชิ้นจากสาวก Al'Aketh ใน Shadowgale Forest, Shine of Akir หรือ Gustberry Lowlands", variants = { { "126:793466812:2078191648", "รวบรวม Al'Aketh Cultist's Ears 10 ชิ้นจากสาวก Al'Aketh ใน Shadowgale Forest, Shrine of Akir หรือ Gustberry Lowlands" } }, amount = { "8:1089852795:1107240600 W1 116:1401399599:1407475753", "รวบรวม Al'Aketh Cultist's Ears {world1} ชิ้นจากสาวกลัทธิ Al'Aketh ใน Shadowgale Forest, Shrine of Akir หรือ Gustberry Lowlands" } },
        description = { "377:1672304408:935298755", "Al'Aketh นำโศกนาฏกรรมใหญ่หลวงสู่ชุมชนเรา เลือดต้องชดใช้ด้วยเลือด\n\nข้ามีข้อเสนอ คนแปลกหน้า หากปะทะสาวกต้องสาป นำหูผู้ที่ฆ่ามา ข้าจะให้รางวัลเป็นเงิน และเมื่อเวลาผ่านไป อนุญาตเข้าถึงความลับ Nightclaw หากพิสูจน์เป็นสหายแท้" },
        progress = { "97:1448720836:2077425882", "ข้าจะไม่พักจนกว่าเขี้ยวจะทะลุคอสาวกทุกคนบนเกาะนี้" },
        completion = { "293:1973680936:584775087", "ทำดีมาก กำจัดลัทธิแล้วมีแต่ผลดี หวังว่าส่งสารให้รู้ว่าเล่นกับ Nightclaw ไม่ได้ และความแค้นเราฝังลึก\n\nข้าคิดว่าเจ้ามีงานหนักในการต่อต้านลัทธิ หากเก็บหูเพิ่ม ก็นำมาอีก", variants = { { "292:1892668234:218445218", "ทำดีมาก กำจัดลัทธิแล้วมีแต่ผลดี หวังว่าส่งสารให้รู้ว่าเล่นกับ Nightclaw ไม่ได้ และความแค้นเราฝังลึก\n\nข้าคิดว่าเจ้ามีงานหนักในการต่อต้านลัทธิ หากเก็บหูเพิ่ม ก็นำมาอีก" } } },
        required = { [258771] = { "22:70627987:624652110", "หูของสาวกลัทธิ Al'Aketh" } },
        steps = { { "22:70627987:624652110", "หูของสาวกลัทธิ Al'Aketh" } },
    },
    [93172] = { -- Free the Hollows
        title = { "16:620239324:658240598", "ปลดปล่อยเหล่า Hollow" },
        objective = { "45:116818946:1804091439", "ทำลาย Wind Hollows 10 ตนใน Shadowgale Forest" },
        description = { "504:1082631164:772372159", "เอลฟ์ส่วนใหญ่บนเกาะคิดว่าป่านี้มีผีสิง และไม่ได้คิดผิด\n\nที่ซากเก่าตะวันออกเฉียงเหนือ มีวิญญาณคล้ายผีประหลาดรวมตัว บางคืนแทบได้ยินร้องเพลง ไม่เหมือนเพลงที่เคยฟัง แต่เป็นเพลงแน่นอนและ... เศร้าเหลือเกิน\n\nไม่แน่ใจว่าทำไม แต่ข้าว่าเคยเกิดเรื่องเลวร้ายที่นั่น และวิญญาณติดอยู่ด้วยเหตุใดสักอย่าง หากกล้าพอ ช่วยปล่อยให้เป็นอิสระได้ไหม?", variants = { { "502:828032514:2064196271", "เอลฟ์ส่วนใหญ่บนเกาะคิดว่าป่านี้มีผีสิง และไม่ได้คิดผิด\n\nที่ซากเก่าตะวันออกเฉียงเหนือ มีวิญญาณคล้ายผีประหลาดรวมตัว บางคืนแทบได้ยินร้องเพลง ไม่เหมือนเพลงที่เคยฟัง แต่เป็นเพลงแน่นอนและ... เศร้าเหลือเกิน\n\nไม่แน่ใจว่าทำไม แต่ข้าว่าเคยเกิดเรื่องเลวร้ายที่นั่น และวิญญาณติดอยู่ด้วยเหตุใดสักอย่าง หากกล้าพอ ช่วยปล่อยให้เป็นอิสระได้ไหม?" } } },
        completion = { "20:1102876671:1552392539", "ขอบคุณ คนแปลกหน้า" },
        progress = { "98:1656911480:1694075223", "เราได้แต่หวังว่าวิญญาณน่าสงสารเหล่านั้นจะได้พบความสงบหลังเป็นอิสระจากที่นี่" },
        steps = { { "17:210177406:857863236", "ปลดปล่อย Wind Hollow" } },
    },
    [93317] = { -- Crab Season
        title = { "11:1651787544:1688285649", "ฤดูปู" },
        objective = { "42:14496853:1094327980", "รวบรวม Windsong Crawler Meat 6 ชิ้น" },
        description = { "502:1126538218:1655550648", "รู้จัก Windsong Crawler ไหม? ปูนี้มีถิ่นกำเนิดเฉพาะ Windsong Lake บน Zephras และจับได้เพียงไม่กี่สัปดาห์ต่อปี\n\nช่วงนี้ลัทธิเคลื่อนไหวมาก ข้าไปทะเลสาบจับไม่ได้ เวลากำลังหมด จะขอบคุณหากไปเก็บให้ ปกติพบตามฝั่งทะเลสาบและในแม่น้ำ\n\nระวังด้วย มันดุกว่าที่เห็น!" },
        progress = { "328:2141288413:1810117645", "เนื้อ Windsong Crawler ธรรมดาที่นี่ แต่เป็นอาหารเลิศรสบนเกาะ Anvilas กับ Siroccas สมัย Skystream เปิด ชาวบ้านรุมขอของนี้เมื่อข้าไป Shen'dramar หรือ New Eldre'naar\n\nไม่ได้ไปที่เหล่านั้นมา... อืม... นานมากแล้ว", variants = { { "328:2146719439:608155041", "เนื้อ Windsong Crawler ธรรมดาที่นี่ แต่เป็นอาหารเลิศรสบนเกาะ Anvilas กับ Siroccas สมัย Skystream เปิด ชาวบ้านรุมขอของนี้เมื่อข้าไป Shen'dramar หรือ New Eldre'naar\n\nไม่ได้ไปที่เหล่านั้นมา... อืม... นานมากแล้ว" } } },
        completion = { "73:1584332579:189751226", "สายลมอวยพร เนื้อนี้ดูวิเศษมาก!\n\nขอบคุณเหลือเกิน นักผจญภัย", variants = { { "62:218213690:306013553 C 1:46:46", "สายลมอวยพร เนื้อนี้ดูวิเศษมาก!\n\nขอบคุณเหลือเกิน {class}" }, { "61:1571947967:1428629009 C 1:46:46", "สายลมอวยพร เนื้อนี้ดูวิเศษมาก!\n\nขอบคุณเหลือเกิน {class}" } } },
        required = { [257941] = { "21:209096915:1301100160", "เนื้อปู Windsong" } },
        steps = { { "21:209096915:1301100160", "เนื้อปู Windsong" } },
    },
    [93319] = { -- Pilfered Windstones
        title = { "19:1446739820:18738687", "Windstone ที่ถูกลักไป" },
        objective = { "84:556302148:1615110284", "รวบรวม Pilfered Windstones 10 ชิ้นจาก Highlands Bandits ใน Shen'dar Highlands" },
        description = { "450:517513839:1761127967", "ชีวิตประจำวันบน Zephras พึ่ง Windstone มากขึ้นเรื่อย ๆ เราจึงพยายามสำรองเผื่อฉุกเฉิน ช่วงหลังข้าสังเกตของหายจากคลัง\n\nเราพบ Windstone บนโจรที่จับเมื่อไม่นาน ข้าสงสัยว่าพวกมันทำให้ขาดแคลน\n\nหากไปใกล้ถ้ำโจรทางเหนือ ช่วยทุบหัวสักหน่อยแล้วเอา Windstone ที่ถูกลักคืนให้ได้ไหม?", variants = { { "450:1850689854:824326952", "ชีวิตประจำวันบน Zephras พึ่ง Windstone มากขึ้นเรื่อย ๆ เราจึงพยายามสำรองเผื่อฉุกเฉิน ช่วงหลังข้าสังเกตของหายจากคลัง\n\nเราพบ Windstone บนโจรที่จับเมื่อไม่นาน ข้าสงสัยว่าพวกมันทำให้ขาดแคลน\n\nหากไปใกล้ถ้ำโจรทางเหนือ ช่วยทุบหัวสักหน่อยแล้วเอา Windstone ที่ถูกลักคืนให้ได้ไหม?" } } },
        progress = { "351:779335410:792450640", "โจรย่องเบาพวกนี้คงลักเสบียงมาหลายเดือน ข้าพยายามให้ Aonda จัดกำลังบุกกวาดถ้ำถาวร แต่นางไม่อยากดึง Peacekeeper ไม่กี่คนออกจากหมู่บ้าน\n\nเมื่อสาวกที่ Falaath Village ทางใต้เพิ่มจำนวน ข้าก็โทษนางไม่ได้" },
        completion = { "172:1441846883:654168165", "ขอบคุณ นักผจญภัย ช่วยให้พอประคองตอนนี้ แต่หากจัดเส้นทางเสบียงไม่ได้เร็ว ๆ Windstone ที่หายไม่กี่ชิ้นจะเป็นปัญหาเล็กที่สุด", variants = { { "7:531359820:773804707 C 155:1836102791:613494515", "ขอบคุณ {class} ช่วยให้พอประคองตอนนี้ แต่หากจัดเส้นทางเสบียงไม่ได้เร็ว ๆ Windstone ที่หายไม่กี่ชิ้นจะเป็นปัญหาเล็กที่สุด" } } },
        required = { [257945] = { "18:1609975097:705042249", "หินลมที่ถูกขโมย" } },
        steps = { { "18:1609975097:705042249", "หินลมที่ถูกขโมย" } },
    },
    [93320] = { -- Tower Defense
        title = { "13:1674672972:578879013", "ป้องกันหอคอย" },
        objective = { "79:1881335100:1704329430", "รายงานตัวต่อ Yorana Windyreed ที่หอเฝ้าระวังตะวันออกใน Gustberry Lowlands" },
        description = { "496:1451365100:1385178822", "เพิ่งได้ข่าวลัทธิโจมตีหอเฝ้าไพลอนนอกเมือง! ข้าส่ง Peacekeeper สำรองไม่กี่คนพยายามทะลุหลังแนวศัตรูช่วยผู้ป้องกัน แต่ความช่วยเหลือเพิ่มอาจตัดสินความเป็นตายของคนที่นั่น\n\nโปรดออกไปหอตะวันออกทันที ช่วยเท่าที่ทำได้\n\nรองข้า Yorana Windyreed นำกองช่วย หากยังมีชีวิต นางบอกวิธีช่วยดีที่สุดได้" },
        completion = { "170:610521819:1374557478", "ตอนนี้ยังต้านได้ แต่พวกมันมากกว่า นักสู้เราเริ่มเหนื่อย ต้องทำบางอย่างทำลายภาวะชะงักงัน และต้องเร็ว" },
    },
    [93459] = { -- More Al'Aketh Ears
        title = { "18:1266336672:733606913", "หู Al'Aketh เพิ่มเติม" },
        objective = { "170:814235006:668159173", "รวบรวม Al'Aketh Cultist's Ears 10 ชิ้นจาก Al'Aketh ใน Shadowgale Forest, Shine of Akir หรือ Gustberry Lowlands แล้วนำกลับไปให้ Vayn Moonclaw ใน Shadowgale Forest" },
        description = { "499:869917844:1975428276", "ปกติลัทธิ Al'Aketh เลี่ยงป่านี้ไกลเพราะข่าวลือผีสิง... ข่าวลือที่เรายินดีรักษาไว้ ดรูอิดในคณะข้าเพียงอยากอยู่สงบใน Shadowgale แต่พวกมันคุกคาม\n\nพวกเราหลายคนหวาดกลัว\n\nข้ามีข้อเสนอ สู้สาวกแทนเรา นำหูผู้ที่ฆ่ามา จะตอบแทนเป็นเงิน และเมื่อเวลาผ่านไป อนุญาตเข้าถึงความลับหากพิสูจน์เป็นสหายแท้" },
        progress = { "19:1724574479:1216284051", "<Vayn พยักหน้าให้เจ้า>" },
        completion = { "33:537739833:193770669", "นี่คือรางวัลของเจ้าตามที่สัญญาไว้" },
        required = { [258771] = { "22:70627987:624652110", "หูของสาวกลัทธิ Al'Aketh" } },
        objectiveLabels = {
            item = { ["Al'Aketh Cultist's Ear"] = "หูของสาวกลัทธิ Al'Aketh" },
        },
    },
    [93461] = { -- Welcome to Shen'dar Village
        title = { "27:760749961:1746885918", "ยินดีต้อนรับสู่ Shen'dar Village" },
        objective = { "73:1700040203:428728411", "คุยกับ Rathiril Sunlance และ Coriella Calmbreeze ใน Shen'dar Village" },
        description = { "470:447595790:213175359", "เจ้าดูเป็นพวก High Order ผู้มีเชื้อสาย Highborne มักมีประกายในตาที่ทำให้รู้ ก่อนมอบงานจริงจัง ควรรายงานตัวต่อผู้อาวุโส High Order ของเรา Rathiril Sunlance พบได้ในบ้านพักหลัก เลี้ยวมุมจากข้าไปนิดเดียว\n\nอ้อ คุยกับ Coriella Calmbreeze ด้วย นางดูแลโรงเตี๊ยม จัดที่พักและเสบียงให้ได้หากต้องการ" },
        progress = { "37:404659111:642332454", "ที่นี่ไม่ได้ดีนัก แต่เป็นบ้าน" },
        completion = { "418:992290912:1510352460", "ไปหา Rathiril แล้วหรือ? ดี ช่วงนี้ High Order กับ Windshaper ตึงเครียดมาก แต่ที่ Shen'dar ยังสุภาพต่อกัน อย่างน้อยก็ในหมู่บ้าน เรื่องที่เกิดในป่าก็ให้จบอยู่ในป่า\n\nเมื่อเรียบร้อย เจ้าดูเหมือนอยากหางานลงมือ ข้ามีหลายเรื่องต้องทำ หากพร้อมทำงานสักหน่อย?" },
        steps = { { "28:1239836773:94134068", "คุยกับ Rathiril Sunlance" }, { "24:1373067652:631297336", "คุยกับเจ้าของโรงเตี๊ยม" } },
    },
    [93552] = { -- Harvesting Windstones
        title = { "21:1902059104:1295513156", "เก็บเกี่ยว Windstone" },
        objective = { "67:817628398:71709198", "รวบรวม Windstone Clusters 15 ชิ้นจาก Raw Windstones ใน Thendal Grove" },
        description = { "485:1090920301:1790257909", "Windstone เป็นทรัพยากรสำคัญของ Zephras Isle เพราะมีพลังสายลมดิบเข้มข้น ธาตุลมที่เคยอยู่ร่วมเราหายไปหลายปีก่อน ตั้งแต่นั้นเวทหล่อเลี้ยงเกาะค่อยจาง แม้มีข้อจำกัด Windstone ก็ยังเป็นแหล่งพลังไว้ใจได้และมีค่ายิ่ง\n\nจะพบ Windstone ดิบกระจายรอบป่า ช่วยเก็บให้ได้ไหม?", variants = { { "485:782829551:873693023", "Windstone เป็นทรัพยากรสำคัญของ Zephras Isle เพราะมีพลังสายลมดิบเข้มข้น ธาตุลมที่เคยอยู่ร่วมเราหายไปเมื่อหลายศตวรรษก่อน ตั้งแต่นั้นเวทหล่อเลี้ยงเกาะค่อยจาง แม้มีข้อจำกัด Windstone ก็ยังเป็นแหล่งพลังไว้ใจได้และมีค่ายิ่ง\n\nจะพบ Windstone ดิบกระจายรอบป่า ช่วยเก็บให้ได้ไหม?" } } },
        progress = { "24:230142054:1549542649", "สวัสดี นักผจญภัย", variants = { { "13:1911146197:485773127 C 1:46:46", "สวัสดี {class}" } } },
        completion = { "328:351394805:973065136", "ขอบคุณมาก ในฐานะเอลฟ์ เราผูกพันลึกกับเวท Windstone ล้ำค่าขึ้นเรื่อย ๆ เมื่อเวทที่เสาไพลอนสมอใหญ่ใส่ในเกาะยังจางลง\n\nWindstone ไม่ใช่ของมีประโยชน์เพียงอย่างที่เก็บจากแผ่นดินได้ โปรดรับคู่มือสักเล่ม" },
        required = { [258772] = { "17:1624006082:1724824614", "กลุ่มผลึกหินลม" } },
        steps = { { "17:1624006082:1724824614", "กลุ่มผลึกหินลม" } },
    },
    [93735] = { -- The Broken Construct
        title = { "20:1725837837:1662048568", "สิ่งสร้างชำรุด" },
        objective = { "51:73363378:214684614", "ไปหา Riaani Nightwind ทางฝั่งตะวันตกของ Valanaar" },
        description = { "504:403662353:1182813661", "แต่เดิม Windshaper ดูแลเครื่องมือและอุปกรณ์เวทที่วิญญาณลมมอบ รวมถึงสิ่งสร้างเวทมากมายทั่วเกาะ ตั้งแต่วิญญาณจากไป มีเหลือทำงานเพียงน้อยนิด\n\nหนึ่งในสิ่งสร้างที่ยังทำงานใน Valanaar เสียหาย เราส่งช่างไปแล้ว แต่เขาอาจต้องการแรงช่วย ไปปลายตะวันตกเมืองและช่วยเท่าที่ทำได้" },
        completion = { "340:696433308:964198238", "Riaani มุดหน้าใต้แผ่นเกราะสิ่งสร้างที่ขยับขึ้นลง พยายามซ่อมกลไก ไม่สังเกตเจ้าเลย\n\nพายุสาปเถอะ แก่นอยู่ไหน?! ใครคิดว่าถอด Gyrozephyr ออกด้วยเป็นเรื่องดี? มหัศจรรย์ที่สายลมของสิ่งสร้างยังไม่สลายหมด!", variants = { { "342:1597089014:153684739", "Riaani มุดหน้าใต้แผ่นเกราะสิ่งสร้างที่ขยับขึ้นลง พยายามซ่อมกลไก ไม่สังเกตเจ้าเลย\n\nพายุสาปเถอะ แก่นอยู่ไหน?! ใครคิดว่าถอด Gyrozephyr ออกด้วยเป็นเรื่องดี? มหัศจรรย์ที่สายลมของสิ่งสร้างยังไม่สลายหมด!" }, { "341:928007068:666337997", "<Riaani มุดหน้าใต้แผ่นเกราะของสิ่งสร้างที่ขยับขึ้นลง พยายามซ่อมกลไกข้างใต้ เขาไม่ทันสังเกตเจ้าเลย>\n\nพายุสาปเถอะ แก่นอยู่ไหน?! ใครคิดว่าถอด Gyrozephyr ออกด้วยเป็นเรื่องดี? มหัศจรรย์ที่สายลมของสิ่งสร้างยังไม่สลายหมด!" } } },
    },
    [93737] = { -- The Broken Construct
        title = { "20:1725837837:1662048568", "สิ่งสร้างชำรุด" },
        objective = { "59:1533657830:817671532", "คุยกับ Rianni Nightwind แล้วฟังสิ่งที่เขาพูด", variants = { { "61:2013780894:132288620", "คุยกับ Riaani Nightwind แล้วฟังสิ่งที่เขาพูด" } } },
        description = { "241:1951512499:1433780903", "อ้อ สวัสดี Ayessa ส่งมาช่วยหรือ? ได้เลย\n\nไม่แน่ใจว่ามือใหม่ชัด ๆ เช่นเจ้าจะทำอะไรได้ แต่ให้ข้าเอาหัวออกจากเครื่องในสิ่งสร้างสักครู่ อาจคิดงานให้ช่วยได้" },
        progress = { "234:1105614618:81459813", "ข้านึกไม่ออกว่าใครอยากขโมยชิ้นส่วนพวกนี้ไปทำไม นอกจาก Gyrozephyr ของอื่นแทบใช้จริงไม่ได้ แม้แต่ตัวไจโรก็แทบไร้ประโยชน์นอกหน้าที่ที่ตั้งใจไว้" },
        completion = { "259:186801368:338546872", "ขอบคุณที่เก็บวัสดุมา บางอย่างคงหาไม่ง่ายนัก\n\nมีชิ้นส่วนแล้วจะทำให้สิ่งสร้างเดินได้อีก จากนั้นหวังว่าความจำยังดีพอบอกว่าใครเอาส่วนประกอบไป" },
        required = { [260881] = { "22:492793483:1613846148", "ผลึกสายฟ้า" }, [260883] = { "20:1083097349:637142362", "ไจโรเซเฟอร์ลงอาคม" }, [260880] = { "18:2017301761:614201377", "แกนสิ่งสร้างธาตุลม" } },
        steps = { { "42:800604165:1133918307", "ฟังสิ่งที่ Riaani Nightwind จะบอก" }, { "54:1611092129:1932595330", "เก็บ Crystallized Lightning จาก Shriekling Cave" }, { "46:1523952189:981586090", "เก็บ Enchanted Gyrozephyr จาก Windsong Lake" }, { "46:81910389:2133201419", "เก็บ Air Construct Core จากค่ายโจร" } },
        objectiveLabels = {
            item = { ["Crystallized Lightning"] = "ผลึกสายฟ้า", ["Enchanted Gyrozephyr"] = "ไจโรเซเฟอร์ลงอาคม", ["Air Construct Core"] = "แกนสิ่งสร้างธาตุลม" },
        },
    },
    [93738] = { -- The Broken Construct
        title = { "20:1725837837:1662048568", "สิ่งสร้างชำรุด" },
        objective = { "45:1262017934:1974320215", "กลับไปรายงาน Ayessa Dawnsinger ใน Valanaar" },
        description = { "487:1688500484:2098119486", "Brightwish หรือ? High Order อยากถอดชิ้นส่วนด้วยเหตุบางอย่าง แต่ทำไม?\n\nHigh Order ชอบยุ่งมาตลอด อยากทดลองเวทวิญญาณลมไม่หยุด กล้าเกินไปมาก เราห้ามแตะความรู้ในความดูแล Windshaper อย่างเข้มงวด แต่ช่วงหลังทดสอบความอดทนเรา\n\nข้าว่ารายงานสิ่งที่รู้ต่อ Ayessa Dawnsinger นางจะสั่งว่าทำอะไรต่อ", variants = { { "485:1347698501:1128341397", "Brightwish หรือ? High Order อยากถอดชิ้นส่วนด้วยเหตุบางอย่าง แต่ทำไม?\n\nHigh Order ชอบยุ่งมาตลอด อยากทดลองเวทวิญญาณลมไม่หยุด กล้าเกินไปมาก เราห้ามแตะความรู้ในความดูแล Windshaper อย่างเข้มงวด แต่ช่วงหลังทดสอบความอดทนเรา\n\nข้าว่ารายงานสิ่งที่รู้ต่อ Ayessa Dawnsinger นางจะสั่งว่าทำอะไรต่อ" } } },
        completion = { "278:1434632290:392859596", "น่าสนใจมาก High Order ทำให้สิ่งสร้างเสียนั่นเองหรือ?\n\nข้ารู้จัก Belathaan เป็นลูกพี่ลูกน้องของ Valennia Stormfist แม่เขาเป็น Windshaper ด้วย น่าผิดหวังที่มีส่วนเรื่องนี้\n\nข้าต้องคิดสักครู่" },
    },
    [93746] = { -- A Firm Response
        title = { "15:1702523853:1241078484", "ตอบโต้อย่างหนักแน่น" },
        objective = { "66:1601525821:618990868", "เผชิญหน้า Belthaan Brightwish ตามถนนไป Shrine of Akir", variants = { { "67:87584034:859495522", "เผชิญหน้า Belathaan Brightwish ตามถนนไป Shrine of Akir" } } },
        description = { "471:1326247416:1303099835", "High Order ถูกเตือนแล้วถึงผลของการยุ่งกิจการ Windshaper ข้าว่าต้องใช้ Belathaan เป็นตัวอย่าง ส่งกลับ High Order พร้อมรอยช้ำสักหน่อยและความเคารพต่อขอบเขตที่ตั้งไว้\n\nมีคนเห็นเขาออกเมือง มุ่งเหนือไป Shrine of Akir ไม่รู้ไปทำไม แต่เผชิญเขาคนเดียวบนถนนปลอดภัยที่สุด หาให้พบแล้วทำให้กลัวเสียบ้าง" },
        completion = { "308:791422207:905784236 N 142:348705671:945059331", "เดี๋ยว อะไรนะ?! Belathaan... ตายแล้ว?\n\n<Ayessa ฟังเจ้ารายงานเหตุการณ์>\n\nHigh Order นัด Al'Aketh เพื่อเจรจาสงบหรือ? ไม่มีสันติกับลัทธิ พวกมันคลั่งสังหาร Elaadrin คิดอะไรถึงส่ง Belathaan ไปคุยลำพัง?\n\nอย่ากังวล {name} เจ้าไม่ผิด ความหยิ่ง High Order ต่างหากน่าโทษอีกแล้ว เจ้าเพียงอยู่ถูกที่ผิดเวลา" },
        progress = { "276:259639520:413432257", "ข้าไม่ชอบใช้การข่มขู่หรือความรุนแรง แต่ต้องทำให้พวกเขาเข้าใจ High Order เหิมเกริมเร็วเกินไป เรารับผลของการปะทะกับพวกเขาตรง ๆ ไม่ไหว แต่ก็ทนใช้ชีวิตคอยกังวลว่าการแทรกแซงของพวกเขาจะเร่งให้บ้านของเราพังพินาศไม่ได้เหมือนกัน" },
        steps = { { "29:985287043:1109632465", "ไปเผชิญหน้ากับ Belathaan Brightwish" } },
    },
    [93835] = { -- Confront Lorthuna
        title = { "17:1873207911:1945188641", "เผชิญหน้า Lorthuna" },
        objective = { "148:1404514633:330404106", "ผ่านประตูมิติขึ้น Rohashi Spires เหนือศีรษะ สมทบ Elaadrin Evengale และ Ayessa Dawnsinger ในการเผชิญ High Priestess Lorthuna" },
        description = { "381:538758734:1444563089 C 1:46:46", "Lorthuna ใช้ประตูมิติบางอย่างหนีขึ้นยอดหอด้านบน Ayessa กับ Elaadrin ตามไป เพิ่งไม่กี่อึดใจ\n\nข้าคงโดนหนักไปหน่อย ต้องอยู่ตรงนี้ ผ่านประตูไปหา Elaadrin แล้วช่วยหยุด Lorthuna\n\nหากความช่วยเหลือที่ Elaadrin กับ Ayessa บอกว่าส่งคนไปขอยังไม่มาถึง เจ้าต้องพึ่งตัวเองจากนี้ โชคดี {class}" },
        completion = { "385:2129585472:696690495", "ข้าส่งเมจที่เหลือบางคนให้แน่ใจว่า Valennia กับกำลังหนีได้เช่นกัน ตอนนี้นางคงพักที่บ้าน High Elder Shadowsong\n\nAnsirem ต้องกลับ Azeroth แต่เราคุยถึงก้าวต่อของ High Order ก่อนเขาไป วันนี้รอดแล้ว แต่ Zephras เปราะบางอันตราย ต้องวางแผนรับสิ่งที่จะมา" },
        progress = { "67:872734412:373477102", "ข้าเกรงว่าสถานการณ์ของเราจะยิ่งคับขันกว่าเดิมเสียแล้ว" },
        steps = { { "17:1873207911:1945188641", "ไปเผชิญหน้ากับ Lorthuna" } },
    },
    [93836] = { -- The Fate of Zephras
        title = { "19:1535483682:1962792304", "ชะตาแห่ง Zephras" },
        objective = { "43:702080654:753852318", "คุยกับ Talaanis Shadowsong ใน Valanaar" },
        description = { "469:1804624378:2079317409", "Muln เล่าเรื่องเจ้าแห่งธาตุให้มาก ข้ากลัวว่าเรามีเหตุควรหวาด Al'Akir เมื่อเกราะคุ้มกันที่ซ่อน Zephras จากสายตาพังลง เราไร้การป้องกันสิ้นเชิง หากเขาโจมตี เราไม่มีหวังต่อสู้ในอาณาเขตเขาเอง\n\nHigh Elder Shadowsong ต้องรู้อันตราย และสำคัญกว่านั้น เจตนาภารกิจสู่ Azeroth เราจะหาวิธีช่วยบ้าน ข้าสาบาน", variants = { { "470:480958083:1062814824", "Muln เล่าเรื่องเจ้าแห่งธาตุให้มาก ข้ากลัวว่าเรามีเหตุควรหวาด Al'Akir เมื่อเกราะคุ้มกันที่ซ่อน Zephras จากสายตาพังลง เราไร้การป้องกันสิ้นเชิง หากเขาโจมตี เราไม่มีหวังต่อสู้ในอาณาเขตเขาเอง\n\nHigh Elder Shadowsong ต้องรู้อันตราย และสำคัญกว่านั้น เจตนาภารกิจสู่ Azeroth เราจะหาวิธีช่วยบ้าน ข้าสาบาน" } } },
        completion = { "493:1610043715:841095059", "Talaanis Shadowsong ตั้งใจฟังเรื่องที่เกิดเหนือ Shrine of Akir และแผน Ayessa จะออกจาก Zephras Isle\n\nข้าต้องคิดต่อ แต่ด้านดีคือกำจัด Lorthuna ตัดหัวหน้าลัทธิได้ บ้านยังไม่ถูกรุกราน ในมุมเวลาของเทพธาตุ อาจอีกหลายปี... หรือหลายสิบปี กว่า Al'Akir จะลดตัวสนใจเรา\n\nมีเรื่องให้กลัวมาก แต่ก็มีเรื่องให้ฉลองเช่นกัน", variants = { { "495:895938420:2016266774", "Talaanis Shadowsong ตั้งใจฟังเรื่องที่เกิดเหนือ Shrine of Akir และแผน Ayessa จะออกจาก Zephras Isle\n\nข้าต้องคิดต่อ แต่ด้านดีคือกำจัด Lorthuna ตัดหัวหน้าลัทธิได้ บ้านยังไม่ถูกรุกราน ในมุมเวลาของเทพธาตุ อาจอีกหลายปี... หรือหลายสิบปี กว่า Al'Akir จะลดตัวสนใจเรา\n\nมีเรื่องให้กลัวมาก แต่ก็มีเรื่องให้ฉลองเช่นกัน" } } },
        steps = { { "30:320836396:858980976", "คุยกับ Talaanis Shadowsong" } },
    },
    [93926] = { -- The Western Watch
        title = { "17:788565063:553062431", "หอเฝ้าระวังตะวันตก" },
        objective = { "51:1051133612:1333547610", "หา Peacekeeper Vaaniel ที่หอเฝ้าระวังตะวันตก" },
        description = { "479:1113947152:1013941704", "ไม่ว่าลัทธิโจมตีหอเพราะอะไร ก็ไม่คุ้มเสียผู้คน\n\nข้าอยากให้ไปตะวันตกเฉียงใต้ตรวจหอ หา Peacekeeper แล้วบอกให้กลับหมู่บ้าน ยึดหอไม่คุ้มชีวิตที่ต้องแลก ข้าอยากรวมผู้ป้องกันที่มีไว้คุ้มครองชาวบ้าน\n\nPeacekeeper Vaaniel เป็นหัวหน้า บอกให้กลับโดยเร็วที่สุด รีบเถิด!", variants = { { "479:32539230:1913130603", "ไม่ว่าลัทธิโจมตีหอเพราะอะไร ก็ไม่คุ้มเสียผู้คน\n\nข้าอยากให้ไปตะวันตกเฉียงใต้ตรวจหอ หา Peacekeeper แล้วบอกให้กลับหมู่บ้าน ยึดหอไม่คุ้มชีวิตที่ต้องแลก ข้าอยากรวมผู้ป้องกันที่มีไว้คุ้มครองชาวบ้าน\n\nPeacekeeper Vaaniel เป็นหัวหน้า บอกให้กลับโดยเร็วที่สุด รีบเถิด!" } } },
        completion = { "216:357797275:213499997", "ศพนี้ยังสด ดูเพิ่งถูกฆ่าไม่นาน รอยไหม้บนผิว Peacekeeper แสดงชัดว่าถูกผู้ใช้คาถาพายุของลัทธิฆ่า", variants = { { "218:273974430:561699368", "ศพนี้ยังสด ดูเพิ่งถูกฆ่าไม่นาน รอยไหม้บนผิว Peacekeeper แสดงชัดว่าถูกผู้ใช้คาถาพายุของลัทธิฆ่า" }, { "217:346690366:229935633", "<ศพนี้ยังสด ดูเพิ่งถูกฆ่าไม่นาน รอยไหม้บนผิว Peacekeeper แสดงชัดว่าถูกผู้ใช้คาถาพายุของลัทธิฆ่า>" } } },
        steps = { { "60:379577746:1118046985", "ไปตรวจดู Western Watchtower ใน Shen'dar Highlands" } },
    },
    [93927] = { -- A Last Request
        title = { "14:1439447978:1311314475", "คำขอสุดท้าย" },
        objective = { "94:575657142:870351416", "เก็บสารที่พบใกล้ Peacekeeper ผู้ตาย แล้วอ่านเพื่อกำหนดก้าวต่อไป" },
        description = { "170:148727444:1241827644", "<ขณะตรวจศพ Peacekeeper สารเปื้อนเลือดหลุดจากมือ เก็บอ่านอาจได้เบาะแสว่าจะทำอะไรต่อ>" },
        progress = { "33:72044997:1181218910", "มีข่าวจากหอตะวันตกอย่างไร?" },
        completion = { "470:947905499:1505504869", "ตายหมดแล้วหรือ พายุสาปไอ้ลัทธิสารเลวนั่น!\n\nแม้เจ้าจัดการนักบวชและหยุดสาวกที่หอ ข้ากังวลเป็นสองเท่ากับสิ่งที่บอกว่าพวกมันทำต่อไพลอน การมีคลัง Windstone ใหญ่มหึมาบ่งว่าต้องใช้พลังมหาศาล\n\nอดสงสัยไม่ได้ เป้าหมายปลายทางคืออะไร? ลบหลู่ไพลอน โจมตีหมู่บ้าน เพื่ออะไร?", variants = { { "473:777201842:563092866", "ตายหมดแล้วหรือ พายุสาปไอ้ลัทธิสารเลวนั่น!\n\nแม้เจ้าจัดการนักบวชและหยุดสาวกที่หอ ข้ากังวลเป็นสองเท่ากับสิ่งที่บอกว่าพวกมันทำต่อไพลอน การมีคลัง Windstone ใหญ่มหึมาบ่งว่าต้องใช้พลังมหาศาล\n\nอดสงสัยไม่ได้ เป้าหมายปลายทางคืออะไร? ลบหลู่ไพลอน โจมตีหมู่บ้าน เพื่ออะไร?" } } },
        required = { [254871] = { "11:1281393027:469347161", "สารเปื้อนเลือด" }, [263415] = { "21:112523060:1430306252", "ขนนกนำโชคของ Raani" }, [263418] = { "24:1795743811:1619522672", "แหวนตราตระกูล Shadowsong" } },
        steps = { { "25:2110844956:54198477", "เก็บบันทึกแล้วอ่าน" }, { "24:442965476:1785086360", "ขนนกชิ้นโปรดของ Raani" } },
        objectiveLabels = {
            item = { ["Bloody Note"] = "สารเปื้อนเลือด", ["Raani's Lucky Feather"] = "ขนนกนำโชคของ Raani", ["Shadowsong Family Signet"] = "แหวนตราตระกูล Shadowsong" },
        },
    },
    [93948] = { -- Deliver the Signet
        title = { "18:208533075:579050709", "ส่งตราประจำตระกูล" },
        objective = { "72:1726914350:1780629199", "ส่ง Shadowsong Family Signet ให้ Talaanis Shadowsong ใน Valanaar" },
        description = { "473:1501149497:1706738395", "ไหน ๆ ก็ไป Valanaar โปรดส่งแหวนตราที่กู้จากหอให้ Talaanis Shadowsong\n\nเขาต้องการมันคืน และสำคัญกว่านั้น ต้องรู้ชะตาหลานชาย Talaanis เป็น High Elder แห่ง Zephras Isle ที่สำคัญคือเป็นคนดีซึ่งผู้คนรักแม้กำลังยากลำบาก ข้าเจ็บปวดเมื่อนึกว่าจะรับข่าวอย่างไร โปรดแสดงความเสียใจแทนข้า" },
        progress = { "42:1726149312:925958836", "มีอะไรมาให้ข้า? อ้อ... โอ้ ไม่", variants = { { "42:673436707:666540993", "มีอะไรมาให้ข้า? อ้อ... โอ้ ไม่" } } },
        completion = { "344:1269057078:1162036862", "ข้า... เสียใจยิ่งที่รู้ว่าหลานตาย ขอบคุณจากใจที่กู้สิ่งนี้และนำมาให้\n\nShen'dorei หนุ่มสาวสามารถเช่นเจ้าไม่ค่อยลงจากที่สูง หากหางาน โปรดคุย Valennia Stormfist หัวหน้า Peacekeeper ใน Valanaar ยามนี้เราต้องการทุกแรงช่วย", variants = { { "344:1370047361:778007643", "ข้า... เสียใจยิ่งที่รู้ว่าหลานตาย ขอบคุณจากใจที่กู้สิ่งนี้และนำมาให้\n\nShen'dorei หนุ่มสาวสามารถเช่นเจ้าไม่ค่อยลงจากที่สูง หากหางาน โปรดคุย Valennia Stormfist หัวหน้า Peacekeeper ใน Valanaar ยามนี้เราต้องการทุกแรงช่วย" } } },
        required = { [263491] = { "24:1795743811:1619522672", "แหวนตราตระกูล Shadowsong" } },
        steps = { { "24:1795743811:1619522672", "แหวนตราตระกูล Shadowsong" } },
    },
    [93949] = { -- Bugged
        title = { "6:1442058197:1808303581", "แมลงดักฟัง" },
        objective = { "75:504333277:306449268", "ฆ่า Skyhopper ใน Valanaar จนกำจัด Enchanted Skyhoppers ได้ 8 ตัว", amount = { "52:751088775:1848827316 W1 22:868240522:1638947294", "ฆ่า Skyhopper ใน Valanaar จนกำจัด Enchanted Skyhoppers ได้ {world1} ตัว" } },
        description = { "499:569012061:1652763181", "เราถูกดักฟัง\n\nที่ลุ่มกำลังเป็นฤดู Skyhopper แมลงจึงเต็มไปหมด เมจ High Order รายงานว่าตัวที่ฆ่ามีมนตร์บางอย่าง เมื่อตรวจใกล้ ดูเป็นคาถาฟังเสียง\n\nเราสงสัยว่าลัทธิใช้แมลงลงมนตร์เป็นสายลับ ไปกำจัดให้ที มองภายนอกไม่รู้ว่าตัวไหนมีมนตร์ จึงต้องฆ่าทั้งหมด" },
        completion = { "139:512123933:1217356294", "แน่ใจว่ายังมีพวกนี้รอบ Valanaar แต่ Skyhopper ลงมนตร์ทุกตัวที่เหยียบตายทำให้เมืองปลอดภัยขึ้นนิดหนึ่ง" },
        progress = { "141:948332776:1725118481", "ข้าเป็นนักรบอาชีพมาสามร้อยกว่าปี เห็นมาหมดแล้วทั้งเรื่องที่เจ้าไม่มีวันเชื่อ แต่ข้าก็ยัง... เกลียดแมลง เข้ากระดูกดำ" },
        steps = { { "32:564760843:848613310", "กำจัด Enchanted Skyhopper" } },
    },
    [93951] = { -- A Little Beauty
        title = { "15:1238389383:2041627447", "ความงามเล็กน้อย" },
        objective = { "61:125452516:75198333", "รวบรวม Hippogryph Down 8 เส้นใน Shen'dar Highlands" },
        description = { "505:273678763:1340722024", "ฮิปโปกริฟที่ตั้งรังตะวันตกเฉียงใต้ของหมู่บ้านอาจก่อกวน แต่เป็นโอกาสพิเศษเก็บขน Skyborne มากมายชอบประดับผมด้วยขนนกสดใส ขนอ่อนฮิปโปกริฟสีงามเป็นพิเศษ และสำคัญกว่านั้น นุ่มดุจแพร\n\nหากไปทางนั้น พยายามเก็บขนที่ร่วงรอบรังให้มาก ระวัง ฮิปโปกริฟป่าไม่ทนรับแขก", variants = { { "510:1079796743:1003677114", "ฮิปโปกริฟที่ตั้งรังตะวันตกเฉียงใต้ของหมู่บ้านอาจก่อกวน แต่เป็นโอกาสพิเศษเก็บขน Skyborne มากมายชอบประดับผมด้วยขนนกสดใส ขนอ่อนฮิปโปกริฟสีงามเป็นพิเศษ และสำคัญกว่านั้น นุ่มดุจแพร\n\nหากไปทางนั้น พยายามเก็บขนที่ร่วงทั้งในบริเวณรังและรอบ ๆ ให้มากที่สุด ระวัง ฮิปโปกริฟป่าไม่ทนรับแขก" }, { "169:680471881:1132925911 R 333:4528806:376422313", "ฮิปโปกริฟที่ทำรังทางตะวันตกเฉียงใต้ของหมู่บ้านอาจก่อความรำคาญ แต่ก็เป็นโอกาสดีที่จะเก็บขนของพวกมัน ชาว{race}หลายคนชอบประดับผมด้วยขนนกสีสด ขนอ่อนของฮิปโปกริฟมีสีสดเป็นพิเศษ และที่สำคัญยิ่งกว่านั้นคือนุ่มดุจแพรไหม\n\nถ้าเจ้าจะไปทางนั้น ลองเก็บขนที่ร่วงอยู่ทั้งในและรอบบริเวณรังให้ได้มากที่สุด ระวังตัวด้วย ฮิปโปกริฟป่าไม่ต้อนรับแขก" }, { "170:710981354:1489448472 R 327:1634686830:1588797301", "ฮิปโปกริฟที่ทำรังทางตะวันตกเฉียงใต้ของหมู่บ้านอาจก่อความรำคาญ แต่ก็เป็นโอกาสดีที่จะเก็บขนของพวกมัน ชาว{race}หลายคนชอบประดับผมด้วยขนนกสีสด ขนอ่อนของฮิปโปกริฟมีสีสดเป็นพิเศษ และที่สำคัญยิ่งกว่านั้นคือนุ่มดุจแพรไหม\n\nถ้าเจ้าจะไปทางนั้น ลองเก็บขนที่ร่วงอยู่รอบบริเวณรังให้ได้มากที่สุด ระวังตัวด้วย ฮิปโปกริฟป่าไม่ต้อนรับแขก" } } },
        progress = { "39:1061186567:604991691", "นำของงามอะไรมาให้ข้า?" },
        completion = { "326:1882081585:585603587", "เก็บขนประดับผมอาจดูเป็นความฟุ้งเฟ้อเล็กน้อย แต่แม้ยามนี้ เราต้องรับความสุขเล็ก ๆ ให้มากที่สุด\n\nหากของที่ข้าสร้างสักชิ้นทำให้ใครยินดี ข้าถือว่าเป็นวันที่ดี ขอบคุณที่นำมาและช่วยนำความสุขสู่ Zephras" },
        required = { [263493] = { "15:1114892633:1140138301", "ขนอ่อนฮิปโปกริฟฟ์" } },
        steps = { { "15:1114892633:1140138301", "ขนอ่อนฮิปโปกริฟฟ์" } },
    },
    [93958] = { -- The Inner Sanctum
        title = { "17:194543589:1783645577", "เขตศักดิ์สิทธิ์ชั้นใน" },
        objective = { "77:1817280456:1253934", "คุยกับ Valennia Stormfist ในเขตศักดิ์สิทธิ์ชั้นในของ Shrine of Akir" },
        description = { "263:1935059607:111455164", "กำลัง Valennia เพิ่งฝ่าเขตชั้นใน ช่วงแรกสู้กันหนาแน่น แต่ตอนนี้... เงียบจนน่ากลัว เข้าไปพยายามสมทบนางกับกำลัง... หากยังเหลือใคร\n\nข้าจะอยู่ระวังหลังให้" },
        completion = { "33:130373808:1858135614", "<Valennia ดูบาดเจ็บสาหัส>" },
    },
    [94369] = { -- The Fate of Zephras
        title = { "19:1535483682:1962792304", "ชะตาแห่ง Zephras" },
        objective = { "43:702080654:753852318", "คุยกับ Talaanis Shadowsong ใน Valanaar" },
        description = { "456:1360347330:755027550", "Ansirem เล่าเรื่องเจ้าแห่งธาตุให้มาก ข้ากลัวว่าเรามีเหตุควรหวาด Al'Akir เมื่อเกราะที่ซ่อน Zephras พังลง หากเจ้าแห่งลมโจมตี เราไม่มีหวังป้องกันตัวในอาณาเขตเขา\n\nHigh Elder Shadowsong ต้องรู้อันตราย และสำคัญกว่านั้น เจตนาภารกิจสู่ Azeroth เราจะหาวิธีช่วยบ้าน ข้าสาบาน" },
        completion = { "500:33377347:576573927", "Talaanis Shadowsong ตั้งใจฟังเรื่องที่เกิดเหนือ Shrine of Akir และแผน Elaadrin จะออกจาก Zephras Isle\n\nข้าต้องคิดต่อ แต่ด้านดีคือกำจัด Lorthuna ตัดหัวหน้าลัทธิได้ บ้านยังไม่ถูกรุกราน ในมุมเวลาของกึ่งเทพธาตุ อาจอีกหลายปี... หรือหลายสิบปี กว่า Al'Akir จะลดตัวสนใจเรา\n\nมีเรื่องให้กลัวมาก แต่ก็มีเรื่องให้ฉลองเช่นกัน", variants = { { "502:1341974506:1909608029", "Talaanis Shadowsong ตั้งใจฟังเรื่องที่เกิดเหนือ Shrine of Akir และแผน Elaadrin จะออกจาก Zephras Isle\n\nข้าต้องคิดต่อ แต่ด้านดีคือกำจัด Lorthuna ตัดหัวหน้าลัทธิได้ บ้านยังไม่ถูกรุกราน ในมุมเวลาของกึ่งเทพธาตุ อาจอีกหลายปี... หรือหลายสิบปี กว่า Al'Akir จะลดตัวสนใจเรา\n\nมีเรื่องให้กลัวมาก แต่ก็มีเรื่องให้ฉลองเช่นกัน" } } },
        steps = { { "30:320836396:858980976", "คุยกับ Talaanis Shadowsong" } },
    },
    [94411] = { -- Meddlesome Mages
        title = { "16:1286475212:1927994118", "เมจจุ้นจ้าน" },
        objective = { "52:1018061657:822208190", "สังหาร High Order Apprentices 6 คนใน Shen'dar Highlands" },
        description = { "418:802344285:1829269491", "ระวัง มีคนเห็น High Order ใกล้แนวหินตั้งเหนือหมู่บ้าน เราเตือนซ้ำแล้วไม่ให้ยุ่งสถานที่ศักดิ์สิทธิ์ แต่ยิ่งกล้าผลักดันเรา พิสูจน์ความเด็ดเดี่ยวโดยไปแนวหินตั้งขับไล่พวกเขา\n\nข้าไม่อยากเห็นด้วยกับการนองเลือดโจ่งแจ้ง แต่ทำสิ่งจำเป็นเพื่อขับออก แล้วกลับมา", variants = { { "417:1437919077:162359020", "ระวัง มีคนเห็น High Order ใกล้แนวหินตั้งเหนือหมู่บ้าน เราเตือนซ้ำแล้วไม่ให้ยุ่งสถานที่ศักดิ์สิทธิ์ แต่ยิ่งกล้าผลักดันเรา พิสูจน์ความเด็ดเดี่ยวโดยไปแนวหินตั้งขับไล่พวกเขา\n\nข้าไม่อยากเห็นด้วยกับการนองเลือดโจ่งแจ้ง แต่ทำสิ่งจำเป็นเพื่อขับออก แล้วกลับมา" } } },
        progress = { { "33:1173856058:407336436", "22:149065985:636489980 N 1:46:46", "22:149065985:636489980 C 1:46:46", "22:149065985:636489980 R 1:46:46" }, "ทำสิ่งที่จำเป็น นักผจญภัย" },
        completion = { "377:1861793775:1038715651", "การปะทะพี่น้อง Shen'dorei โดยตรงเพียงทำให้เผ่าอ่อนแอ แต่บางครั้งต้องลงมือเด็ดขาดเพื่อกันโศกนาฏกรรมใหญ่กว่า\n\nเมจ High Order ไม่สนใจผลจากการยุ่งเวทเลย พลังที่ผูกเกาะเปราะบางและอ่อนแอ การทำโดยไม่คิดครั้งเดียวก็อาจทำลายบ้าน" },
        steps = { { "30:500655511:1977819252", "ปราบ High Order Apprentice" } },
    },
    [94413] = { -- A Magical Affront
        title = { "17:139679937:330784918", "การดูหมิ่นทางเวท" },
        objective = { "53:408850396:410809211", "สังหาร Windshaper Novice Seers 6 คนใน Shen'dar Highlands" },
        description = { "498:625190606:594501001", "เส้นพลังเวทที่เพิ่งปรากฏบนผิว Zephras มีความหมายลึกต่อคณะ เราเข้าถึงพลังที่แทรกทั่วที่นี่ได้ตรงและจับต้องยิ่งขึ้น ทำให้เข้าใจเวทมาก\n\nแต่ Windshaper มองจุดผุดเหล่านี้เป็นแผลบนดินที่ต้องรักษา นี่คือการดูหมิ่นคณะ เราทนไม่ได้\n\nไปเส้นพลังเวทในป่าตะวันตกเฉียงใต้ ขับไล่ Windshaper ที่พบ", variants = { { "500:1399539787:1754836044", "เส้นพลังเวทที่เพิ่งปรากฏบนผิว Zephras มีความหมายลึกต่อคณะ เราเข้าถึงพลังที่แทรกทั่วที่นี่ได้ตรงและจับต้องยิ่งขึ้น ทำให้เข้าใจเวทมาก\n\nแต่ Windshaper มองจุดผุดเหล่านี้เป็นแผลบนดินที่ต้องรักษา นี่คือการดูหมิ่นคณะ เราทนไม่ได้\n\nไปเส้นพลังเวทในป่าตะวันตกเฉียงใต้ ขับไล่ Windshaper ที่พบ" } } },
        completion = { "296:1049731481:1784098901", "บางครั้งข้าแยกความคลั่งมืดบอดของ Al'Aketh กับความดื้อไม่ยอมเปลี่ยนของ Windshaper ได้ยาก\n\nหากเชื่อจริงว่าสายลมนำทาง ก็ควรรู้ทิศที่ลมพัดและไหลตาม ไม่ใช่ต้าน" },
        progress = { "234:2007506055:1772538324", "พวกวินด์เชปเปอร์ยอมเห็นพวกเราทนทุกข์จนตาย ดีกว่าปล่อยให้เผ่าพันธุ์ของเราได้ใช้ศักยภาพเต็มที่ เรามีพลังจะทวงชะตาของเราคืนมาและกำหนดมันเอง พวกนั้นยึดติดกับวิถีเดิมเกินกว่าจะยอมให้เรื่องนี้เกิดขึ้น" },
        steps = { { "31:1386433530:272481538", "ปราบ Windshaper Novice Seer" } },
    },
    [94414] = { -- The Anchors of Zephras
        title = { "22:1529129554:1243823327", "สมอแห่ง Zephras" },
        objective = { "88:654873338:222404358", "คุยกับ Halaan Hawk-Eye แล้วยืมพรของเขามองเสาไพลอนสมอที่อยู่ไกลออกไป" },
        description = { "17:1545238973:664863442 N 333:162020148:1814857676", "สวัสดี {name} น้อย ข้ามาที่นี่บ่อยเพื่อมองเสาไพลอนสมอโบราณ ของขวัญจากวิญญาณลมซึ่งผูกและหล่อเลี้ยงเกาะ แต่ช่วงหลังเวทไม่มั่นคงและไม่สม่ำเสมอ\n\nข้าไม่เห็นร่องรอยเสียหาย ความงามยังไม่เปลี่ยน\n\nหากต้องการ ข้าให้ยืมพรเพื่อมองด้วยตนเองได้", variants = { { "17:1545238973:664863442 N 334:1569354081:1049346317", "สวัสดี {name} น้อย ข้ามาที่นี่บ่อยเพื่อมองเสาไพลอนสมอโบราณ ของขวัญจากวิญญาณลมซึ่งผูกและหล่อเลี้ยงเกาะ แต่ช่วงหลังเวทไม่มั่นคงและไม่สม่ำเสมอ\n\nข้าไม่เห็นร่องรอยเสียหาย ความงามยังไม่เปลี่ยน\n\nหากต้องการ ข้าให้ยืมพรเพื่อมองด้วยตนเองได้" } } },
        progress = { "357:1563567682:1058565274", "พรข้าเรียบง่ายธรรมดา มองระหว่างโลกเหมือนผู้มี Skysight ไม่ได้ ดึงเวทจากเส้นใต้ Zephras อย่างคนอื่นก็ไม่ได้ แต่ยังเป็นพร ข้าซาบซึ้งที่มี\n\nเห็นค่าของที่มีคือกุญแจความสุข โหยหาสิ่งที่อาจมีหรือสิ่งสูญไป นำสู่สิ้นหวังเท่านั้น", variants = { { "358:91919451:1951240171", "พรของข้าเรียบง่ายและธรรมดา ข้ามองข้ามระหว่างโลกอย่างผู้มี Skysight ไม่ได้ และดึงพลังเวทจากเส้นพลังใต้ Zephras อย่างคนอื่นก็ไม่ได้ ถึงอย่างนั้นก็ยังเป็นพร และข้าซาบซึ้งที่ได้รับมัน\n\nการเห็นค่าของสิ่งที่มีคือหนทางสู่ความสุข การโหยหาสิ่งที่อาจได้มาหรือสิ่งที่เสียไปแล้วมีแต่จะนำไปสู่ความสิ้นหวัง" } } },
        completion = { "134:31057314:1997722975", "ขอบคุณที่แบ่งเวลาร่วมมองกับข้า ข้าจะเฝ้าป่าต่อและใคร่ครวญสภาพบ้านเกิด" },
        steps = { { "21:639816241:1263061756", "ตรวจดูเสา Anchor Pylon" } },
    },
    [94484] = { -- Unnerving Silence
        title = { "17:346632000:2128026648", "ความเงียบน่าหวั่นใจ" },
        objective = { "83:1395276627:271411177", "หาและคุยกับ Elegael Thornpaw ทางตะวันออกเฉียงเหนือของ Shadowgale Forest" },
        description = { "22:1515503728:1393472052 N 356:493149929:1612642490", "ขอครู่หนึ่ง {name} เจ้าจะไป Shadowgale Forest หรือ? มีชุมนุมดรูอิดในถ้ำตะวันออกเฉียงเหนือ ข้ารอข่าวอยู่ แต่สารช้าเกินกำหนดมาก\n\nเมื่อ Ban'aethall พังและเกิดความไม่สงบ ข้ากลัวมีเหตุร้าย หากทำได้ โปรดหา Elegael Thornpaw ให้ข้าสบายใจ", variants = { { "22:742792788:1390761860 N 356:1844257435:1511190481", "ขอครู่หนึ่ง {name} เจ้าจะไป Shadowgale Forest หรือ? มีชุมนุมดรูอิดในถ้ำตะวันออกเฉียงเหนือ ข้ารอข่าวอยู่ แต่สารช้าเกินกำหนดมาก\n\nเมื่อ Ban'aethall พังและเกิดความไม่สงบ ข้ากลัวมีเหตุร้าย หากทำได้ โปรดหา Elegael Thornpaw ให้ข้าสบายใจ" } } },
        completion = { "329:135482731:1223839970", "ขอบคุณที่สารถึง Lotheluum เดี๋ยว กำลังเสริมที่เหลืออยู่ไหน? คงไม่ใช่ส่งแค่เจ้าหรอกนะ?\n\n<Elegael ซีดเมื่อเจ้าถ่ายทอดบทสนทนากับ Lotheluum>\n\nสารส่งไม่ถึงสินะ เราลำบากหนักจริง\n\nคงต้องจัดการเอง เวลาเป็นสิ่งสำคัญ", variants = { { "331:1812893854:44258355", "ขอบคุณที่สารถึง Lotheluum เดี๋ยว กำลังเสริมที่เหลืออยู่ไหน? คงไม่ใช่ส่งแค่เจ้าหรอกนะ?\n\n<Elegael ซีดเมื่อเจ้าถ่ายทอดบทสนทนากับ Lotheluum>\n\nสารส่งไม่ถึงสินะ เราลำบากหนักจริง\n\nคงต้องจัดการเอง เวลาเป็นสิ่งสำคัญ" } } },
    },
    [94488] = { -- The Ties That Bind
        title = { "18:1078767989:835069955", "สายสัมพันธ์ที่ผูกพัน" },
        objective = { "87:1862441511:1218298470", "ฆ่า Commander Haalien แล้วนำหัวไปให้ Elegael Thornpaw ใน Shadowgale Forest" },
        description = { "319:792807386:343697037", "เหตุที่สาวกมาที่นี่ยังทำข้าฉงน แต่เหนือกลิ่นคาวเลือด ข้าได้กลิ่นคุ้นเคย\n\nHaalien ดรูอิดในวงเราหายไปหลายเดือน ดูเหมือนเอาหนังน่าสมเพชไปร่วมลัทธิ\n\nแสดงให้รู้ว่าหลั่งเลือดพวกเดียวกันแล้วเป็นอย่างไร! เก็บหัวกลับมาให้ข้า", variants = { { "318:751364018:817230670", "เหตุที่สาวกมาที่นี่ยังทำข้าฉงน แต่เหนือกลิ่นคาวเลือด ข้าได้กลิ่นคุ้นเคย\n\nHaalien ดรูอิดในวงเราหายไปหลายเดือน ดูเหมือนเอาหนังน่าสมเพชไปร่วมลัทธิ\n\nแสดงให้รู้ว่าหลั่งเลือดพวกเดียวกันแล้วเป็นอย่างไร! เก็บหัวกลับมาให้ข้า" } } },
        progress = { "63:1532965087:344210699", "ชีวิตพี่น้องเรามีค่าน้อยนักหรือ Haalien?" },
        completion = { "68:750467071:386514131 N 185:1190872155:2114270994", "<Elegael หน้านิ่วเมื่อเห็นหัวที่ขาด แต่พยักหน้าสั้น ๆ>\n\nขอบคุณ {name} ไม่ว่าโกรธเพียงใด ลงมือฆ่าลูกพี่ลูกน้องของตัวเองก็คงยาก\n\nอย่าไว้ทุกข์ให้เขา ความเขลาและชั่วร้ายทำผู้บริสุทธิ์ตายมากมายวันนี้" },
        required = { [265475] = { "32:1529163976:473399565", "หัวที่ถูกตัดของ Commander Haalien" } },
        steps = { { "32:1529163976:473399565", "หัวที่ถูกตัดของ Commander Haalien" } },
    },
    [94489] = { -- The Wounds of Betrayal
        title = { "22:775257308:1542520208", "บาดแผลแห่งการทรยศ" },
        objective = { "89:212370081:1275449904", "เข้า Nightfang Den รักษาดรูอิด 7 คน และหา Jorel Windsinger ใน Shadowgale Forest", amount = { "33:270493466:647298030 W1 55:1332992192:1141574106", "เข้า Nightfang Den รักษาดรูอิด {world1} คน และหา Jorel Windsinger ใน Shadowgale Forest" } },
        description = { "438:207526087:154413718", "ข้าทำยาพอกเสร็จแล้ว รีบนำให้ดรูอิดในถ้ำทางเหนือข้ามลานไป พี่น้องสาหัสกว่าข้ามาก คงเจ็บจนรักษาตัวเองไม่ได้ ดรูอิด Shen'dorei มีน้อย ทุกชีวิตล้ำค่า\n\nก่อนไป ขอเรื่องเห็นแก่ตัวหน่อย Jorel Windsinger คู่ชีวิตข้าสาหัสเมื่อข้าจากมา โปรดดูบาดแผลหากเขายังอยู่" },
        completion = { "316:1642302896:40748254", "หน้า Elegael ซีดเมื่อเจ้าเล่าชะตา Jorel และอาการดรูอิดคนอื่น\n\nไม่... ไม่! เลวร้ายกว่าที่ข้า...\n\nElegael กลั้นสะอื้น กัดฟันคำรามเจ็บปวด\n\nพวกมันต้องชดใช้ ทุกคนต้องชดใช้! ใครร่วม Al'Aketh จะรับโทสะข้า! ข้าสาบาน", variants = { { "320:1163148468:879892855", "หน้า Elegael ซีดเมื่อเจ้าเล่าชะตา Jorel และอาการดรูอิดคนอื่น\n\nไม่... ไม่! เลวร้ายกว่าที่ข้า...\n\nElegael กลั้นสะอื้น กัดฟันคำรามเจ็บปวด\n\nพวกมันต้องชดใช้ ทุกคนต้องชดใช้! ใครร่วม Al'Aketh จะรับโทสะข้า! ข้าสาบาน" }, { "320:458256169:1503011850", "<ใบหน้าของ Elegael ซีดลงเมื่อเจ้าเล่าชะตาของ Jorel และอาการของดรูอิดคนอื่น>\n\nไม่... ไม่! เลวร้ายกว่าที่ข้า...\n\n<Elegael กลั้นสะอื้น กัดฟันแล้วส่งเสียงคำรามอย่างเจ็บปวด>\n\nพวกมันต้องชดใช้ ทุกคนต้องชดใช้! ใครเข้าพวกกับ Al'Aketh จะต้องรับโทสะของข้า ข้าขอสาบาน!" } } },
        progress = { "C 88:64375784:410249841", "{class}! เจ้ากลับมาแล้ว ได้พบพี่น้องของข้าไหม? เจอ Jorel หรือเปล่า?" },
        steps = { { "21:421855994:416306994", "รักษาดรูอิดที่บาดเจ็บ" }, { "21:1547445336:1136929261", "ตามหา Jorel Windsinger" } },
    },
    [94490] = { -- Ripped Missive
        title = { "14:1066865107:309292809", "สารฉีกขาด" },
        objective = { "70:1960623268:1109666067", "นำ Ripped Missive ไปให้ Elegael Thornpaw ใน Shadowgale Forest" },
        description = { "259:444140845:1269245258", "<หลังปลอกแขน Haalien มีสารฉีกนิดหน่อยและเปื้อนเลือดจากการต่อสู้ ดูมีข้อมูลสำคัญเกี่ยวกับแรงจูงใจลัทธิในการโจมตีรังดรูอิด Elegael คงสนใจ>", variants = { { "263:260357696:1583340514", "<หลังปลอกแขน Haalien มีสารฉีกนิดหน่อยและเปื้อนเลือดจากการต่อสู้ ดูมีข้อมูลสำคัญเกี่ยวกับแรงจูงใจลัทธิในการโจมตีรังดรูอิด Elegael คงสนใจ>" } } },
        completion = { "491:902033517:719175754", "พวกมันมาหาไพลอนหรือ? เพื่ออะไร? เดิมไม่ได้ตั้งใจโจมตีเรา?\n\n<Elegael พูดค้าง สั่นด้วยโกรธขณะอ่าน>\n\nพวกมันฆ่าคนของข้าเพราะเราเกะกะ! ข้าจะฉีกสาวกทุกคนด้วยเขี้ยว ไม่ให้ใครออกไปทั้งชีวิต\n\nไป เร็ว! หากคำสั่งมาจาก Valanaar จริง น่าจะมีคนทรยศซ่อนที่นั่น มอบสารให้ Lotheluum ใน Valanaar แล้วเล่าเหตุการณ์", variants = { { "491:1510214583:1570519252", "พวกมันมาหาไพลอนหรือ? เพื่ออะไร? เดิมไม่ได้ตั้งใจโจมตีเรา?\n\n<Elegael พูดค้าง สั่นด้วยโกรธขณะอ่าน>\n\nพวกมันฆ่าคนของข้าเพราะเราเกะกะ! ข้าจะฉีกสาวกทุกคนด้วยเขี้ยว ไม่ให้ใครออกไปทั้งชีวิต\n\nไป เร็ว! หากคำสั่งมาจาก Valanaar จริง น่าจะมีคนทรยศซ่อนที่นั่น มอบสารให้ Lotheluum ใน Valanaar แล้วเล่าเหตุการณ์" } } },
    },
    [94491] = { -- The Fate of the Den
        title = { "19:236334805:1995938404", "ชะตาของรัง" },
        objective = { "75:1032715033:1155915090", "มอบสารให้ Lotheluum ใน Valannar แล้วเล่าสิ่งที่เกิดขึ้น", variants = { { "75:424533967:304571592", "มอบสารให้ Lotheluum ใน Valanaar แล้วเล่าสิ่งที่เกิดขึ้น" } } },
        description = { "400:1449017510:193082247 N 81:1726563489:2113098256", "ดูเหมือนมีผู้ติดต่อซ่อนใน Valanaar คอยป้อนข้อมูลลัทธิ ข้าไม่อยู่ในสภาพเดินทาง แต่ Lotheluum ต้องรู้เหตุการณ์\n\nเขาควรรู้ชะตาผู้จากไปด้วย เพราะเจ้า เราน่าจะรับมือที่เหลือต่อได้ แม้ความเสียหายเกิดแล้ว\n\nรีบไป {name} หวังว่าวันหนึ่งพบกันอีก ระหว่างนี้ข้ามีสาวกต้องฆ่า", variants = { { "401:556883221:620545965 N 81:1726563489:2113098256", "ดูเหมือนมีผู้ติดต่อซ่อนใน Valanaar คอยป้อนข้อมูลลัทธิ ข้าไม่อยู่ในสภาพเดินทาง แต่ Lotheluum ต้องรู้เหตุการณ์\n\nเขาควรรู้ชะตาผู้จากไปด้วย เพราะเจ้า เราน่าจะรับมือที่เหลือต่อได้ แม้ความเสียหายเกิดแล้ว\n\nรีบไป {name} หวังว่าวันหนึ่งพบกันอีก ระหว่างนี้ข้ามีสาวกต้องฆ่า" } } },
        completion = { "429:573802604:1129805356", "Lotheluum หวาดกลัวจากใจเมื่อฟังเหตุการณ์รังดรูอิด\n\nขะ... ขอโทษ สหาย ขอเวลาครู่ ไม่มีถ้อยคำใดบรรยายความสูญเสียได้\n\nข่าวร้ายแรงจริง หากสารไม่ปลอม อย่างดีที่สุดเรามีผู้สมรู้ร่วมคิด อย่างแย่ที่สุดมีคนทรยศใน Valanaar ข้าจะนำไปให้ High Elder ทันที ไม่ปล่อยให้พี่น้องสละเปล่า!", variants = { { "103:589330259:1911229874 N 322:1372462028:959452401", "Lotheluum หวาดกลัวจากใจเมื่อฟังเหตุการณ์รังดรูอิด\n\nขะ... ขอโทษ {name} ขอเวลาครู่ ไม่มีถ้อยคำใดบรรยายความสูญเสียได้\n\nข่าวร้ายแรงจริง หากสารไม่ปลอม อย่างดีที่สุดเรามีผู้สมรู้ร่วมคิด อย่างแย่ที่สุดมีคนทรยศใน Valanaar ข้าจะนำไปให้ High Elder ทันที ไม่ปล่อยให้พี่น้องสละเปล่า!" }, { "77:649662141:1670151098 C 21:1630885168:1608458898 N 322:1372462028:959452401", "Lotheluum หวาดกลัวจากใจเมื่อฟังเหตุการณ์รัง{class}\n\nขะ... ขอโทษ {name} ขอเวลาครู่ ไม่มีถ้อยคำใดบรรยายความสูญเสียได้\n\nข่าวร้ายแรงจริง หากสารไม่ปลอม อย่างดีที่สุดเรามีผู้สมรู้ร่วมคิด อย่างแย่ที่สุดมีคนทรยศใน Valanaar ข้าจะนำไปให้ High Elder ทันที ไม่ปล่อยให้พี่น้องสละเปล่า!" }, { "103:589330259:1911229874 N 321:1251777406:73275881", "<สีหน้าของ Lotheluum ฉายแววหวาดกลัวขณะฟังเจ้าเล่าเหตุการณ์ในรังดรูอิด>\n\nขะ... ขอโทษ {name} ขอเวลาครู่ ไม่มีถ้อยคำใดบรรยายความสูญเสียได้\n\nข่าวร้ายแรงจริง หากสารไม่ปลอม อย่างดีที่สุดเรามีผู้สมรู้ร่วมคิด อย่างแย่ที่สุดมีคนทรยศใน Valanaar ข้าจะนำไปให้ High Elder ทันที จะไม่ยอมให้พวกพ้องต้องสละชีวิตไปโดยเปล่าประโยชน์!" } } },
    },
    [94493] = { -- A Sacrifice in Vain
        title = { "19:1591837982:755181883", "เสียสละสูญเปล่า" },
        objective = { "74:1222041060:1446954441", "คุยกับ Elegael Thornpaw ทางตะวันออกเฉียงเหนือของ Shadowgale Forest" },
        description = { "351:540424811:163060920", "ขอบคุณที่สารถึง Lotheluum เดี๋ยว กำลังเสริมที่เหลืออยู่ไหน? คงไม่ใช่ส่งแค่เจ้าหรอกนะ?\n\n<Elegael ซีดเมื่อเจ้าชี้แจง>\n\nสารไปไม่ถึง Valanaar สินะ เราลำบากหนักจริง\n\n<Elegael ถอนใจลึกแล้วกลับแน่วแน่>\n\nเราต้องจัดการเอง เวลาเป็นสิ่งสำคัญ", variants = { { "353:1904512369:1053241941", "ขอบคุณที่สารถึง Lotheluum เดี๋ยว กำลังเสริมที่เหลืออยู่ไหน? คงไม่ใช่ส่งแค่เจ้าหรอกนะ?\n\n<Elegael ซีดเมื่อเจ้าชี้แจง>\n\nสารไปไม่ถึง Valanaar สินะ เราลำบากหนักจริง\n\n<Elegael ถอนใจลึกแล้วกลับแน่วแน่>\n\nเราต้องจัดการเอง เวลาเป็นสิ่งสำคัญ" } } },
        completion = { "318:1275011336:67195005", "สาวก Al'Aketh ซุ่มโจมตีแทบไม่เตือน หลายคนในรังบาดเจ็บหรือใกล้ตาย ข้าพยายามส่งข่าว Valanaar แต่ดูสูญเปล่า\n\nหากเจ้ามาถึงนี่แล้ว ขอร้องให้ช่วย ไม่รู้พี่น้องจะทนการโจมตีได้อีกนานแค่ไหน", variants = { { "318:1696956784:99739345", "สาวก Al'Aketh ซุ่มโจมตีแทบไม่เตือน หลายคนในรังบาดเจ็บหรือใกล้ตาย ข้าพยายามส่งข่าว Valanaar แต่ดูสูญเปล่า\n\nหากเจ้ามาถึงนี่แล้ว ขอร้องให้ช่วย ไม่รู้พี่น้องจะทนการโจมตีได้อีกนานแค่ไหน" } } },
    },
    [94568] = { -- The Cult's True Plans
        title = { "21:701736548:346531745", "แผนแท้จริงของลัทธิ" },
        objective = { "60:1257496292:1323154869", "คุยกับ Talaanis Shadowsong แล้วสังเกตบทสนทนา" },
        description = { "240:255625102:1261915541", "ผู้แปรพักตร์กลัวแผนลัทธิชัดเจน ถึงยอมหนีมาขอช่วย น่าเสียดายจริงที่ตายและนำความลับลงหลุมด้วย\n\nเราต้องหารือต่อเพื่อกำหนดก้าวถัดไป", variants = { { "244:33143143:757939445", "ผู้แปรพักตร์กลัวแผนลัทธิชัดเจน ถึงยอมหนีมาขอช่วย น่าเสียดายจริงที่ตายและนำความลับลงหลุมด้วย\n\nเราต้องหารือต่อเพื่อกำหนดก้าวถัดไป" } } },
        completion = { "169:1550120012:1299093088", "เราอาจส่ง Peacekeeper ปะทะกำลังลัทธิตรง ๆ แต่คงสู้ไม่ดีในศึกเปิด\n\nต้องใช้วิธีอื่น" },
        progress = { "79:1972147685:1909795958", "คนที่แปรพักตร์นั่นยอมเสี่ยงทุกอย่างเพื่อหนีจากลัทธิแล้วเอาผลึกนี้มาให้เรา..." },
