            event = { ["Observe the conversation"] = "เฝ้าดูการสนทนา" },
        },
    },
    [94946] = { -- The Magical City of Dalaran
        title = { "27:1394002256:1583025257", "มหานครเวท Dalaran" },
        objective = { "107:639796477:494532664", "ขึ้นเรือเหาะ Skycutter จาก Zephras Isle ไป Dalaran City แล้วคุยกับ Danaaris Stargale เมื่อถึง" },
        description = { "508:864510225:858892896", "ข้าตั้งใจจะเป็นคนแรกของเราที่เหยียบ Azeroth แต่เรื่องลัทธิเปลี่ยนแผน จึงต้องอยู่ Valanaar อีกพัก อย่ากังวล เรามีเมจหลายคนรอต้อนรับที่ Dalaran ข้าอยากให้สำรวจ Azeroth ระหว่างเราจัดธุระ จะเรียกตัวผู้ปฏิบัติงานเช่นเจ้าเมื่อจำเป็น\n\nเมื่อพร้อม ไปท่าเรือนอกบ้านพักนี้แล้วขึ้น Skycutter" },
        completion = { "378:306724416:981340771", "อา มาถึงแล้ว วิเศษ ต้องใช้เวลาตั้งหลักที่นี่ เจ้าอาจสำรวจเมืองก่อน แต่ระวัง อย่าออกไกลจากความปลอดภัยในตัวเมืองนัก\n\nแม้แดนใหม่ดูสงบงาม การเดินนอก Dalaran โดยไม่เตรียมตัวและมีประสบการณ์พออันตรายอย่างยิ่ง" },
    },
    [95349] = { -- The Earthen Ring
        title = { "16:874859246:233549303", "คณะ Earthen Ring" },
        objective = { "102:1480643876:1591129416", "ขึ้นเรือเหาะ Skycutter จาก Zephras Isle ไป Mulgore แล้วคุยกับ Alana Stormwalker เมื่อถึง", variants = { { "103:1452061757:1658490371", "ขึ้นเรือเหาะ Skycutter จาก Zephras Isle ไป Mulgore แล้วคุยกับ Alaana Stormwalker เมื่อถึง" } } },
        description = { "495:1467494915:1665111652 N 1:46:46", "เหตุลัทธิช่วงนี้ทำแผนไป Azeroth ล่าช้า ข้าต้องอยู่ Valanaar อีกพัก เจ้าและ Windshaper อีกหยิบมือจะเป็นกองหน้าแทน Alaana Stormwalker รอต้อนรับใน Mulgore ข้าอยากให้สำรวจ Azeroth ระหว่างเราจบธุระ อีกไม่นานจะตามไป\n\nเมื่อพร้อม ไปท่าเรือนอกบ้านพักนี้แล้วขึ้น Skycutter\n\nBanu-Alah {name}", variants = { { "488:505030381:1840903806 N 1:46:46", "เหตุการณ์เกี่ยวกับลัทธิช่วงนี้ทำให้การเดินทางไป Azeroth ของข้าล่าช้า ข้าต้องอยู่ที่ Valanaar ต่ออีกสักพัก เจ้ากับ Windshapers อีกหยิบมือจะไปเป็นกองหน้าแทน Alaana Stormwalker จะรอต้อนรับเจ้าเมื่อไปถึง Mulgore ข้าอยากให้เจ้าสำรวจ Azeroth ระหว่างที่พวกเราสะสางธุระทางนี้ อีกไม่นานเราจะตามไปสมทบ\n\nเมื่อพร้อมแล้ว ไปที่ท่าเรือด้านนอกบ้านพักนี้แล้วขึ้นเรือเหาะ Skycutter ที่นั่น Banu-Alah, {name}" } } },
        completion = { "375:1823358418:801122426", "นักผจญภัยจาก Zephras เพิ่มอีกหรือ วิเศษ สายลมเข้าข้างเราแน่! ต้องใช้เวลาตั้งหลัก เจ้าอาจสำรวจดินแดนใหม่นี้ก่อน\n\nAzeroth น่าตื่นเต้นแต่ก็อันตราย ควรเตรียมรับการผจญภัยโดยทำความคุ้นเคยพื้นที่ใกล้ ๆ" },
    },
    [98512] = { -- Al'Aketh Assassins
        title = { "18:509161502:1777784104", "มือสังหาร Al'Aketh" },
        objective = { "53:1031726961:183836520", "ฆ่า Al'Aketh Assassins 10 คนใน Shen'dar Highlands" },
        description = { "376:297778878:801186962", "เจ้านั่น คนแปลกหน้า หมอบต่ำและเงียบไว้ เราไม่ได้อยู่ลำพัง\n\nข้าลาดตระเวนใกล้เขตแดน เห็น Al'Aketh หลายคนด้อมรอบบ้านบนเนินทางเหนือ ไม่รู้ทำอะไร แต่คงไม่ดี\n\nหากอยากช่วย เข้าไปกำจัด ข้าจะรอระวังหลังให้" },
        completion = { "174:400631734:472084253", "ยินดีที่กลับมา Al'Aketh กลุ่มนั้นดูเป็นนักฆ่าเลือดเย็น\n\nขอบคุณที่ช่วย ข้าจะใส่ความช่วยเหลือของเจ้าในรายงานเมื่อกลับ Valanaar" },
        progress = { "29:996487572:1897844468", "พวกนั้นกำลังตามหาอะไรอยู่นะ?" },
        objectiveLabels = {
            monster = { ["Al'Aketh Assassin slain"] = "ปราบ นักฆ่า Al'Aketh" },
        },
    },
    [99260] = { -- Fillion's Mission
        title = { "17:1537153142:1901256706", "ภารกิจของ Fillion" },
        objective = { "41:1449439189:1067667648", "คุยกับ Elaadrin Evengale ใน Valanaar" },
        description = { "495:2063895577:2106700795", "ข้าได้รับหน้าที่นำข้อมูลสำคัญเรื่องกระแสพลังธาตุจาก Overlook Standing Stones มันจำเป็นต่อแผนเดินทางปลอดภัยระหว่าง Skywall กับ Azeroth หากไม่มีช่วยคำนวณ ความพยายามบังคับ Skycutter ผ่านแดนธาตุจะล้มเหลว\n\nตอนนี้ข้อมูลคงหายแล้ว ข้าไม่อยู่ในสภาพไปเก็บใหม่ บอก Supreme Magister แล้วว่าเจ้าช่วยชีวิต เขาอยากคุยอีกครั้ง" },
        completion = { "478:1202095827:976256048", "ขอบคุณที่ช่วย Fillion สหาย เขาคงบอกแล้วว่าข้อมูลที่ถูกส่งไปเก็บสำคัญเพียงใด\n\nหากไร้ข้อมูล โอกาสเปิดเส้นทางปลอดภัยสู่ Azeroth ล่อแหลมหนัก สายลับบอกว่า Windshaper หาวิธีข้ามภพได้แล้ว และคงหวงความลับ\n\nเช่นเคย ความหยิ่งยึดถือหลักตนมาก่อนประโยชน์ผู้คน พวกเขาแทบดีกว่า Al'Aketh ไม่เท่าไร", variants = { { "30:2074177938:995298045 N 442:1886243236:1609165767", "ขอบคุณที่ช่วย Fillion {name} เขาคงบอกแล้วว่าข้อมูลที่ถูกส่งไปเก็บสำคัญเพียงใด\n\nหากไร้ข้อมูล โอกาสเปิดเส้นทางปลอดภัยสู่ Azeroth ล่อแหลมหนัก สายลับบอกว่า Windshaper หาวิธีข้ามภพได้แล้ว และคงหวงความลับ\n\nเช่นเคย ความหยิ่งยึดถือหลักตนมาก่อนประโยชน์ผู้คน พวกเขาแทบดีกว่า Al'Aketh ไม่เท่าไร" }, { "30:2074177938:995298045 N 440:1054606928:1612794742", "ขอบใจที่ช่วย Fillion นะ {name} เขาคงบอกเจ้าแล้วว่าข้อมูลที่เขาได้รับมอบหมายให้ไปเก็บสำคัญเพียงใด\n\nหากไร้ข้อมูล โอกาสเปิดเส้นทางปลอดภัยสู่ Azeroth ล่อแหลมหนัก สายลับบอกว่า Windshaper หาวิธีข้ามภพได้แล้ว และคงหวงความลับ\n\nเช่นเคย ความหยิ่งยึดถือหลักตนมาก่อนประโยชน์ผู้คน พวกเขาแทบดีกว่า Al'Aketh ไม่เท่าไร" } } },
    },
    [95998] = { -- The Great Outdoors
        title = { "18:382978171:1997271011", "โลกกลางแจ้งอันกว้างใหญ่" },
        objective = { "113:1627462719:223993326", "นั่งใกล้ Sam's Basic Campfire โดยพิมพ์ /sit ในช่องแชต แล้วรอจนได้รับบัฟ Boosted Rest", variants = { { "79:1321640269:1788934736", "นั่งใกล้ Sam's Basic Campfire แล้วรอจนได้รับบัฟ Boosted Rest" } } },
        description = { "18:1531307266:178199538 C 419:495822723:1838168471", "ว่าไง {class} ข้าเห็นแววนักผจญภัยในตัวเจ้า ดีแล้ว โลกต้องการคนอยู่ไม่สุขอย่างเรามากขึ้น ผู้แสวงหาโชคลาภและเกียรติยศ\n\nข้างนอกเป็นโลกกว้าง หากจะสำเร็จต้องเรียนรู้ให้อยู่กลางป่าได้ดี ไม่รู้ว่าทักษะกลางแจ้งเจ้าเป็นอย่างไร แต่ข้าคงสอนได้สักอย่างสองอย่าง หากพร้อมเรียน\n\nนั่งสบาย ๆ ใกล้ไฟ ข้าจะค่อย ๆ อธิบายให้ฟัง" },
        progress = { "158:876811060:784012330", "ทักษะอยู่รอดกลางแจ้งสำคัญยิ่ง นักผจญภัยที่พักเต็มที่และเตรียมพร้อมมีโอกาสรอดจากวิถีชีวิตนี้สูงกว่ามาก", variants = { { "159:1342539578:769632120", "ทักษะอยู่รอดกลางแจ้งสำคัญยิ่ง นักผจญภัยที่พักเต็มที่และเตรียมพร้อมมีโอกาสรอดจากวิถีชีวิตนี้สูงกว่ามาก" } } },
        completion = { "181:1485624651:1944828302", "เมื่อรู้พื้นฐานแล้ว ทำไมไม่ไปเรียนวิชาชีพสักอย่าง? ครูฝึกจะสอนสร้างอุปกรณ์แคมป์ที่เหมาะกับวิชาชีพใหม่ด้วย" },
        steps = { { "21:1525459521:992560528", "นั่งใกล้กองไฟ" }, { "26:1201320836:369744463", "รับบัฟ Boosted Rest" } },
    },
    [96031] = { -- Camping 101: Leatherworking
        title = { "27:1698130846:1506167115", "ตั้งแคมป์ 101: เครื่องหนัง" },
        objective = { "142:1489515405:939530696", "คุยกับ Gretta Finespindle ใน Ironforge เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "45:1200778187:1735425090 C 245:815205661:284337473", "เจ้าเป็นช่างหนังแล้ว ดีมาก {class} ข้าว่ารู้จักคนสอนทำเต็นท์ให้เย็นในวันร้อนและแห้งในวันฝนได้\n\nมีเต็นท์ดีคลุมหัว ก็มั่นใจได้ว่าจะพักเต็มที่พอให้ตื่นตัวระหว่างเดินทาง" },
        completion = { "470:577898743:1109976944", "เรียบร้อย เต็นท์แคมป์ของเจ้าเอง คนส่วนใหญ่ไม่ชอบให้กางเต็นท์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "37:614229450:1985955440", "เพิ่มทักษะการทำเครื่องหนังให้ถึง 20" } },
    },
    [96044] = { -- Camping 101: Blacksmithing
        title = { "26:1221764726:279206460", "ตั้งแคมป์ 101: ตีเหล็ก" },
        objective = { "139:691730532:1616498589", "คุยกับ Tognus Flintfire ใน Kharanos เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "320:202320231:852909869", "เป็นช่างตีเหล็กแล้วหรือ เป็นตัวเลือกดีหากอยากให้คมดาบไม่ทื่อ\n\nข้ารู้จักคนช่วยสอนสร้าง Sharpening Wheel ได้ ตั้งในแคมป์แล้วนักรบกับโจรแถวนั้นคงต่อแถวลับอาวุธกัน" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        completion = { "495:2117961607:447306361", "เรียบร้อย ตอนนี้เจ้าสร้าง Sharpening Wheel ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "36:482259371:1296802253", "เพิ่มทักษะการตีเหล็กให้ถึง 20" } },
    },
    [96045] = { -- Camping 101: Alchemy
        title = { "20:915921786:1716389149", "ตั้งแคมป์ 101: เล่นแร่แปรธาตุ" },
        objective = { "138:387689744:644330719", "คุยกับ Vosur Brakthel ใน Ironforge เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "229:1087886069:356824097", "เมื่อเริ่มเล่นแร่แปรธาตุแล้ว ข้าสอนสร้าง Mana Well สำหรับแคมป์ได้เมื่อเจ้ารู้มากขึ้นสักหน่อย สร้างแล้วผู้รักษากับผู้ใช้คาถาคงวิ่งมาชิมความสดชื่นกัน" },
        completion = { "488:892105979:1076061495", "เรียบร้อย ตอนนี้เจ้าสร้าง Mana Well ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        steps = { { "30:1831080184:1814656452", "เพิ่มทักษะการเล่นแร่แปรธาตุให้ถึง 20" } },
    },
    [96046] = { -- Camping 101: Mining
        title = { "19:2134334844:1251681605", "ตั้งแคมป์ 101: ขุดแร่" },
        objective = { "139:953835764:2136115525", "คุยกับ Yarr Hammerstone ใน Kharanos เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "361:1382345230:1652658988", "ขุดแร่อาจไม่เลิศหรู แต่เป็นงานสุจริตดีและวิชาชีพที่น่าศึกษา\n\nข้ารู้จักคนสอนสร้าง Lodestone สำหรับแคมป์ได้ ตั้งแล้วทุกคนที่อยากเหวี่ยงดาบคงมารวมรอบไฟ รับแรงฮึดเสริมฝีมือสู้จากมัน" },
        completion = { "488:837518116:1487918719", "เรียบร้อย ตอนนี้เจ้าสร้าง Lodestone ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        steps = { { "29:1326993482:1796014523", "เพิ่มทักษะการขุดแร่ให้ถึง 20" } },
    },
    [96047] = { -- Camping 101: First Aid
        title = { "22:1169076296:1627423262", "ตั้งแคมป์ 101: ปฐมพยาบาล" },
        objective = { "134:167203498:926656561", "คุยกับ Thamner Pol ใน Kharanos เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "80:1405944155:1276912498 C 213:1979165028:833800773", "เลือกปฐมพยาบาลหรือ? เป็นหนทางน่ายกย่อง... และเหมาะใช้จริงสำหรับ{class}\n\nข้ารู้จักคนสอนสร้าง First Aid Kit สำหรับแคมป์ได้ บาดเจ็บเป็นเรื่องจริงของโลกผจญภัย การมีการรักษาที่จำเป็นในแคมป์อาจช่วยชีวิตด้วยซ้ำ" },
        progress = { "67:1070716708:1493071004", "ข้าสอนได้เมื่อเจ้าเพิ่มทักษะวิชาชีพสักหน่อยแล้ว" },
        completion = { "492:1329339879:521834233", "เรียบร้อย ตอนนี้เจ้าสร้าง First Aid Kit ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "32:2128258987:594859909", "เพิ่มทักษะการปฐมพยาบาลให้ถึง 20" } },
    },
    [96050] = { -- Camping 101: Fishing
        title = { "20:1026779672:337511730", "ตั้งแคมป์ 101: ตกปลา" },
        objective = { "156:918756091:1746717183", "คุยกับ Paxton Ganter ใกล้ Iceflow Lake ใน Dun Morogh เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "366:2115126721:2001310912", "เจ้าอาจไม่คิดเช่นนั้น แต่ทักษะตกปลามีประโยชน์ในแคมป์จริง ๆ\n\nข้ารู้จักคนสอนสร้าง Fish Bowl ได้ ใช้อุปกรณ์นี้มอบความสุขเล็ก ๆ ให้ตนกับสหายนักผจญภัย คนมีความสุขย่อมเข้มแข็ง ข้ามั่นใจว่าความสามารถสู้จะสะท้อนเช่นนั้น" },
        progress = { "61:1928447902:874189049", "ข้าสอนได้เมื่อเจ้าเพิ่มทักษะตกปลาสักหน่อยแล้ว" },
        completion = { "488:1416066424:65558197", "เรียบร้อย ตอนนี้เจ้าสร้าง Fish Bowl ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "30:486045795:699998660", "เพิ่มทักษะการตกปลาให้ถึง 20" } },
    },
    [96055] = { -- Camping 101: Herbalism
        title = { "22:398153440:411836651", "ตั้งแคมป์ 101: สมุนไพร" },
        objective = { "141:1161629415:186730798", "คุยกับ Reyna Stonebranch ใน Ironforge เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "403:1734578767:1649451813", "ดูเหมือนมีทักษะสมุนไพรแล้ว เก็บดอกไม้ไม่ใช่แค่เดินเอ้อระเหยรู้ไหม มีทั้งประโยชน์... และกำไร\n\nข้ารู้จักคนสอนสร้าง Incense Candle สำหรับแคมป์ได้ ขวัญกำลังใจสูงสำคัญต่อการให้ผู้รักษากับผู้ร่ายคาถาสู้ต่อ เทียนหอมช่วยเสริมสิ่งที่ผู้ใช้เวทต้องชื่นชอบแน่" },
        completion = { "493:2089714052:1219300209", "เรียบร้อย ตอนนี้เจ้าสร้าง Incense Candle ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        steps = { { "32:185111467:616084806", "เพิ่มทักษะการเก็บสมุนไพรให้ถึง 20" } },
    },
    [96056] = { -- Camping 101: Skinning
        title = { "21:877856129:1615425789", "ตั้งแคมป์ 101: ถลกหนัง" },
        objective = { "143:71710170:510885463", "คุยกับ Balthus Stoneflayer ใน Ironforge เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "499:1267848069:485795793", "การเก็บหนังจากสัตว์ที่ล้มอย่างชำนาญเป็นทักษะมีค่ายิ่งอย่างหนึ่งของนักผจญภัย\n\nข้ารู้จักคนสอนสร้าง Camp Chair ได้ บางครั้งการปลดภาระพักสักหน่อยสำคัญ ใช้หนังที่เก็บมาทำเก้าอี้นุ่มนั่ง ผ่อนคลายบ้างจะช่วยให้อยู่ในสภาพดีและโจมตีถูกจุดเมื่อมีเรื่องครั้งหน้า" },
        completion = { "489:1841325329:1145743259", "เรียบร้อย ตอนนี้เจ้าสร้าง Camp Chair ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "24:1867712454:1532779711", "อ้อ ได้สิ ข้าสอนเจ้าได้" },
        steps = { { "31:830454515:1981975140", "เพิ่มทักษะการถลกหนังให้ถึง 20" } },
    },
    [96057] = { -- Camping 101: Tailoring
        title = { "22:1431642385:2057581804", "ตั้งแคมป์ 101: ตัดเย็บ" },
        objective = { "136:1068138919:2095425440", "คุยกับ Uthrar Threx ใน Ironforge เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "350:1427230788:143007988", "ตัดเย็บเป็นวิชาชีพทรงพลังเกินคาดที่ควรลงทุน ข้ามั่นใจว่าจะช่วยเจ้าได้ดี\n\nข้ารู้จักคนสอนสร้าง Faction Banner สำหรับแคมป์ได้ หากมีทักษะพอ แรงบันดาลใจกับขวัญสำคัญต่อชัยชนะทุกสนามรบ ธงเร้าใจช่วยคงพลังฮึกเหิมได้มาก" },
        completion = { "494:1045707758:1807747544", "เรียบร้อย ทีนี้เจ้าก็ทำ Rallying Banner ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "73:485067858:700703801", "กลับมาคุยกับข้าอีกทีเมื่อเจ้าชำนาญวิชาชีพของเจ้าขึ้นอีกหน่อย" },
        steps = { { "32:2138986334:1672550921", "เพิ่มทักษะการตัดเย็บให้ถึง 20" } },
    },
    [96058] = { -- Camping 101: Engineering
        title = { "24:1086805395:342974848", "ตั้งแคมป์ 101: วิศวกรรม" },
        objective = { "139:1119136943:306471678", "คุยกับ Bronk Guzzlegear ใน Kharanos เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "317:1777421338:1929417440", "วิศวกรเช่นเจ้าประดิษฐ์ชิ้นส่วน หุ่น และระเบิดสารพัดได้ทั้งสนุกและมีกำไร\n\nข้ารู้จักคนสอนสร้าง Reagent Bot สำหรับแคมป์ได้ หุ่นช่วยเหลือนี้ดูแลเสบียงให้พร้อม เพื่อเจ้าและพันธมิตรไม่ขาดวัตถุดิบร่ายคาถา" },
        completion = { "490:66550901:387364094", "เรียบร้อย ทีนี้เจ้าก็สร้าง Reagent Bot ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "34:796380127:1923393619", "เพิ่มทักษะวิศวกรรมให้ถึง 20" } },
        progress = { "67:1070716708:1493071004", "เมื่อเจ้าฝึกวิชาชีพจนมีความชำนาญขึ้นบ้างแล้ว ข้าก็จะสอนเจ้าได้" },
    },
    [96059] = { -- Camping 101: Enchanting
        title = { "23:1713173955:924427762", "ตั้งแคมป์ 101: ลงมนตร์" },
        objective = { "142:336241354:465033843", "คุยกับ Thonys Pillarstone ใน Ironforge เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "354:599125318:186671040", "เมื่อเริ่มเส้นทางผู้ลงมนตร์แล้ว ข้าสอนสร้าง Enchanted Lute สำหรับแคมป์ได้เมื่อเจ้ารู้พื้นฐาน\n\nความบันเทิงยามพักสำคัญมาก เวทเล็กน้อยนี้ช่วยให้พร้อมรับความท้าทายสารพัด เมื่อกลับออกสู่ทางฝุ่นอีกครั้ง" },
        completion = { "493:1415932902:592769654", "เรียบร้อย ทีนี้เจ้าก็ทำ Enchanted Lute ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        steps = { { "33:1774593141:15047791", "เพิ่มทักษะการเสริมมนตร์ให้ถึง 20" } },
    },
    [96101] = { -- The Great Outdoors
        title = { "18:382978171:1997271011", "โลกกลางแจ้งอันกว้างใหญ่" },
        objective = { "114:884120119:573316604", "นั่งใกล้ Raan's Basic Campfire โดยพิมพ์ /sit ในช่องแชต แล้วรอจนได้รับบัฟ Boosted Rest", variants = { { "80:532747162:175901738", "นั่งใกล้ Raan's Basic Campfire แล้วรอจนได้รับบัฟ Boosted Rest" } } },
        description = { "11:927657569:725753248 C 407:1628054456:1216167453", "สวัสดี {class} ข้าเห็นแววนักผจญภัยในตัวเจ้า ดีแล้ว โลกต้องการคนอยู่ไม่สุขอย่างเรามากขึ้น ผู้แสวงหาโชคลาภและเกียรติยศ\n\nหากจะสำเร็จในวิถีนี้ ต้องเรียนรู้ให้อยู่กลางป่าได้ดี ไม่รู้ว่าทักษะกลางแจ้งเป็นอย่างไร แต่ข้าคงสอนได้สักอย่างสองอย่าง หากพร้อมเรียน\n\nนั่งสบาย ๆ ใกล้ไฟ ข้าจะค่อย ๆ อธิบายให้ฟัง" },
        progress = { "158:876811060:784012330", "ทักษะอยู่รอดกลางแจ้งสำคัญยิ่ง นักผจญภัยที่พักเต็มที่และเตรียมพร้อมมีโอกาสรอดจากวิถีชีวิตนี้สูงกว่ามาก", variants = { { "159:1342539578:769632120", "ทักษะอยู่รอดกลางแจ้งสำคัญยิ่ง นักผจญภัยที่พักเต็มที่และเตรียมพร้อมมีโอกาสรอดจากวิถีชีวิตนี้สูงกว่ามาก" } } },
        completion = { "205:203867036:768639434", "เมื่อรู้พื้นฐานแล้ว ทำไมไม่ไปเรียนวิชาชีพจากครูในหมู่บ้านใกล้ ๆ? พวกเขาจะสอนสร้างอุปกรณ์แคมป์ที่เหมาะกับวิชาชีพใหม่ด้วย" },
        steps = { { "21:1525459521:992560528", "นั่งใกล้กองไฟ" }, { "26:1201320836:369744463", "รับบัฟ Boosted Rest" } },
    },
