        completion = { "494:1045707758:1807747544", "เรียบร้อย ทีนี้เจ้าก็ทำ Rallying Banner ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "73:485067858:700703801", "ไว้ฝึกวิชาชีพของเจ้าให้ชำนาญขึ้นสักหน่อย แล้วค่อยกลับมาคุยกับข้า" },
        steps = { { "32:2138986334:1672550921", "เพิ่มทักษะการตัดเย็บให้ถึง 20" } },
    },
    [96604] = { -- The Great Outdoors
        title = { "18:382978171:1997271011", "โลกกลางแจ้งอันกว้างใหญ่" },
        objective = { "115:1238429103:2003417500", "นั่งใกล้ Brakk's Basic Campfire โดยพิมพ์ /sit ในช่องแชต แล้วรอจนได้รับบัฟ Boosted Rest", variants = { { "81:1027822759:1554546099", "นั่งใกล้ Brakk's Basic Campfire แล้วรอจนได้รับบัฟ Boosted Rest" } } },
        description = { "9:1871511191:798375331 C 407:1628054456:1216167453", "Lok-tar {class} ข้าเห็นแววนักผจญภัยในตัวเจ้า ดีแล้ว โลกต้องการคนอยู่ไม่สุขอย่างเรามากขึ้น ผู้แสวงหาโชคลาภและเกียรติยศ\n\nหากจะสำเร็จในวิถีนี้ ต้องเรียนรู้ให้อยู่กลางป่าได้ดี ไม่รู้ว่าทักษะกลางแจ้งเป็นอย่างไร แต่ข้าคงสอนได้สักอย่างสองอย่าง หากพร้อมเรียน\n\nนั่งสบาย ๆ ใกล้ไฟ ข้าจะค่อย ๆ อธิบายให้ฟัง", variants = { { "11:927657569:725753248 C 407:1628054456:1216167453", "สวัสดี {class} ข้าเห็นแววนักผจญภัยในตัวเจ้า ดีแล้ว โลกต้องการคนอยู่ไม่สุขอย่างเรามากขึ้น ผู้แสวงหาโชคลาภและเกียรติยศ\n\nหากจะสำเร็จในวิถีนี้ ต้องเรียนรู้ให้อยู่กลางป่าได้ดี ไม่รู้ว่าทักษะกลางแจ้งเป็นอย่างไร แต่ข้าคงสอนได้สักอย่างสองอย่าง หากพร้อมเรียน\n\nนั่งสบาย ๆ ใกล้ไฟ ข้าจะค่อย ๆ อธิบายให้ฟัง" } } },
        completion = { "187:1816335971:51021557", "เมื่อรู้พื้นฐานแล้ว ไปเรียนวิชาชีพจากครูในหมู่บ้านใกล้ ๆ พวกเขาจะสอนสร้างอุปกรณ์แคมป์ที่เหมาะกับวิชาชีพใหม่ด้วย", variants = { { "205:203867036:768639434", "เมื่อรู้พื้นฐานแล้ว ลองไปเรียนวิชาชีพจากครูในหมู่บ้านใกล้ ๆ ดูไหม? พวกเขาจะสอนสร้างอุปกรณ์แคมป์ที่เหมาะกับวิชาชีพใหม่ด้วย" } } },
        progress = { "159:1342539578:769632120", "ทักษะอยู่รอดกลางแจ้งสำคัญยิ่ง นักผจญภัยที่พักเต็มที่และเตรียมพร้อมมีโอกาสรอดจากวิถีชีวิตนี้สูงกว่ามาก", variants = { { "158:876811060:784012330", "ทักษะอยู่รอดกลางแจ้งสำคัญยิ่ง นักผจญภัยที่พักเต็มที่และเตรียมพร้อมมีโอกาสรอดจากวิถีชีวิตนี้สูงกว่ามาก" } } },
        steps = { { "21:1525459521:992560528", "นั่งใกล้กองไฟ" }, { "26:1201320836:369744463", "รับบัฟ Boosted Rest" } },
    },
    [96605] = { -- The Great Outdoors
        title = { "18:382978171:1997271011", "โลกกลางแจ้งอันกว้างใหญ่" },
        objective = { "114:962068536:1692268525", "นั่งใกล้ Kaga's Basic Campfire โดยพิมพ์ /sit ในช่องแชต แล้วรอจนได้รับบัฟ Boosted Rest", variants = { { "80:1813142087:1253091734", "นั่งใกล้ Kaga's Basic Campfire แล้วรอจนได้รับบัฟ Boosted Rest" } } },
        description = { "11:927657569:725753248 C 407:1628054456:1216167453", "สวัสดี {class} ข้าเห็นแววนักผจญภัยในตัวเจ้า ดีแล้ว โลกต้องการคนอยู่ไม่สุขอย่างเรามากขึ้น ผู้แสวงหาโชคลาภและเกียรติยศ\n\nหากจะสำเร็จในวิถีนี้ ต้องเรียนรู้ให้อยู่กลางป่าได้ดี ไม่รู้ว่าทักษะกลางแจ้งเป็นอย่างไร แต่ข้าคงสอนได้สักอย่างสองอย่าง หากพร้อมเรียน\n\nนั่งสบาย ๆ ใกล้ไฟ ข้าจะค่อย ๆ อธิบายให้ฟัง" },
        completion = { "205:203867036:768639434", "เมื่อรู้พื้นฐานแล้ว ทำไมไม่ไปเรียนวิชาชีพจากครูในหมู่บ้านใกล้ ๆ? พวกเขาจะสอนสร้างอุปกรณ์แคมป์ที่เหมาะกับวิชาชีพใหม่ด้วย" },
        progress = { "159:1342539578:769632120", "ทักษะอยู่รอดกลางแจ้งสำคัญยิ่ง นักผจญภัยที่พักเต็มที่และเตรียมพร้อมมีโอกาสรอดจากวิถีชีวิตนี้สูงกว่ามาก", variants = { { "158:876811060:784012330", "ทักษะอยู่รอดกลางแจ้งสำคัญยิ่ง นักผจญภัยที่พักเต็มที่และเตรียมพร้อมมีโอกาสรอดจากวิถีชีวิตนี้สูงกว่ามาก" } } },
        steps = { { "21:1525459521:992560528", "นั่งใกล้กองไฟ" }, { "26:1201320836:369744463", "รับบัฟ Boosted Rest" } },
    },
