    [96626] = { -- Camping 101: Cooking
        title = { "20:808277748:357433819", "ตั้งแคมป์ 101: ทำอาหาร" },
        objective = { "56:1740598411:1937995018", "คุยกับ Tomas ใน Goldshire เพื่อเรียนทำอาหาร" },
        description = { "60:793692301:1899061681 C 184:861452696:492016087", "อยากเรียนเรื่องตั้งแคมป์เพิ่มหรือ? ดีมาก {class} ก้าวแรกของนักผจญภัยคือเป็นพ่อครัวและเรียนก่อไฟ\n\nทำอาหารไม่ใช่แค่ทำของอร่อย แต่เป็นรากฐานแคมป์ด้วย" },
        progress = { "51:829941131:405173494", "กองไฟดีคือรากฐานแคมป์ดี" },
        completion = { "387:704154097:895723253", "ด้วยสิ่งนี้ เจ้าจะตั้งแคมป์ได้ทุกที่ในป่า สิ่งที่เรียนเป็นเพียงพื้นฐาน จึงยังวางเครื่องเรือนได้ไม่มาก\n\nเพิ่มทักษะทำอาหาร แล้วอาจเรียนก่อไฟใหญ่ขึ้นได้\n\nหากชำนาญทักษะวิชาชีพอื่น ก็เรียนพื้นฐานเครื่องเรือนแคมป์จากครูเหล่านั้นได้ด้วย" },
        steps = { { "37:1918510491:1020499550", "เรียนทำอาหารกับ Tomas ที่ Goldshire" } },
    },
    [96627] = { -- The Adventurer
        title = { "14:1141602346:434160617", "นักผจญภัย" },
        objective = { "40:512549094:1363375713", "คุยกับ Sam Sarsparilla ใกล้ Goldshire" },
        description = { "N 203:925169845:1839373285", "{name} เจ้าพิสูจน์ความสามารถปกป้องมาถึงตอนนี้แล้ว ข้าจึงฝากงานไม่ธรรมดาให้\n\nได้ยินว่ามีนักผจญภัยใหม่ลงถนนไปใกล้ Goldshire ไปดูว่าเขาทำอะไรอยู่" },
        completion = { { "169:28666625:2067737323", "30:1625022212:1925150281 N 129:977067115:898824532", "30:1625022212:1925150281 C 129:977067115:898824532", "30:1625022212:1925150281 R 129:977067115:898824532" }, "ขอบคุณที่มาดูแล นักผจญภัย จอมพลนั่นแค่ขี้กังวล\n\nเฮ้ เจ้าก็ดูเป็นนักผจญภัย อยากเรียนเรื่องตั้งแคมป์ไหม?" },
    },
    [96628] = { -- The Adventurer
        title = { "14:1141602346:434160617", "นักผจญภัย" },
        objective = { "61:1393217370:981521130", "ส่ง Supply Bundle ให้ Eric Brighthammer ใกล้ Kharanos" },
        description = { "6:1516321299:785938697 N 185:561740822:260091306", "เดี๋ยว {name} ก่อนกล้าผ่านอุโมงค์ ข้าขออีกอย่าง\n\nเหล่า Mountaineer รายงานว่ามีนักผจญภัยปรากฏนอก Kharanos ช่วยส่งเสบียงนี้ให้เขาได้ไหม?" },
        progress = { "54:1549646360:72988903", "มาที่นี่เพื่อเรียนตั้งแคมป์ในป่าหรือ?" },
        completion = { "177:1808100985:967245118", "บอกว่ามาจากเหล่า Mountaineer หรือ? ใช่ ข้าใช้ประโยชน์ได้ ขอบคุณ นักบวช\n\nเฮ้ เจ้าก็ดูเป็นนักผจญภัย อยากเรียนเรื่องตั้งแคมป์ไหม?", variants = { { "178:1759526831:1403759819", "เจ้าว่านี่มาจากพวกทหารภูเขาหรือ? ใช่ ข้าเอาไปใช้ได้ ขอบใจนะ วอร์ล็อก\n\nว่าแต่ ท่าทางเจ้าก็เหมือนนักผจญภัยเหมือนกันนี่ อยากเรียนรู้เรื่องตั้งแคมป์ไหม?" }, { "176:61360306:743414242", "เจ้าว่านี่มาจากพวกทหารภูเขาหรือ? ดีเลย ข้าเอาไปใช้ได้ ขอบใจนะ ดรูอิด\n\nว่าแต่ ท่าทางเจ้าก็เหมือนนักผจญภัยเหมือนกันนี่ อยากเรียนรู้เรื่องตั้งแคมป์ไหม?" }, { "175:1189243399:2001325208", "เจ้าว่านี่มาจากพวกทหารภูเขาหรือ? ดีเลย ข้าเอาไปใช้ได้ ขอบใจนะ จอมเวท\n\nว่าแต่ ท่าทางเจ้าก็เหมือนนักผจญภัยเหมือนกันนี่ อยากเรียนรู้เรื่องตั้งแคมป์ไหม?" }, { "176:22401520:1372926779", "เจ้าว่านี่มาจากพวกทหารภูเขาหรือ? ดีเลย ข้าเอาไปใช้ได้ ขอบใจนะ โจร\n\nว่าแต่ ท่าทางเจ้าก็เหมือนนักผจญภัยเหมือนกันนี่ อยากเรียนรู้เรื่องตั้งแคมป์ไหม?" }, { "177:898429158:358115120", "เจ้าว่านี่มาจากพวกทหารภูเขาหรือ? ดีเลย ข้าเอาไปใช้ได้ ขอบใจนะ ชาแมน\n\nว่าแต่ ท่าทางเจ้าก็เหมือนนักผจญภัยเหมือนกันนี่ อยากเรียนรู้เรื่องตั้งแคมป์ไหม?" }, { "178:1641853740:376033689", "เจ้าว่านี่มาจากพวกทหารภูเขาหรือ? ดีเลย ข้าเอาไปใช้ได้ ขอบใจนะ นักรบ\n\nว่าแต่ ท่าทางเจ้าก็เหมือนนักผจญภัยเหมือนกันนี่ อยากเรียนรู้เรื่องตั้งแคมป์ไหม?" }, { "178:1575730648:1424559027", "บอกว่ามาจากเหล่า Mountaineer หรือ? ใช่ ข้าใช้ประโยชน์ได้ ขอบคุณ พาลาดิน\n\nเฮ้ เจ้าก็ดูเป็นนักผจญภัย อยากเรียนเรื่องตั้งแคมป์ไหม?" }, { "177:1982085353:1427399361", "เจ้าบอกว่าของพวกนี้มาจากเหล่า Mountaineer หรือ? ดีเลย ข้าได้ใช้แน่ ขอบใจนะ พราน\n\nดูท่าเจ้าจะเป็นนักผจญภัยเหมือนกัน สนใจเรียนวิธีตั้งแคมป์ไหม?" } } },
        required = { [275019] = { "13:1211053389:1436903058", "ห่อเสบียง" } },
        steps = { { "13:1211053389:1436903058", "ห่อเสบียง" } },
    },
    [96629] = { -- Camping 101: Cooking
        title = { "20:808277748:357433819", "ตั้งแคมป์ 101: ทำอาหาร" },
        objective = { "66:864990739:23520536", "คุยกับ Gremlock Pilsnor ใน Kharanos เพื่อเรียนทำอาหาร" },
        description = { "60:793692301:1899061681 C 184:861452696:492016087", "อยากเรียนเรื่องตั้งแคมป์เพิ่มหรือ? ดีมาก {class} ก้าวแรกของนักผจญภัยคือเป็นพ่อครัวและเรียนก่อไฟ\n\nทำอาหารไม่ใช่แค่ทำของอร่อย แต่เป็นรากฐานแคมป์ด้วย" },
        completion = { "387:704154097:895723253", "ด้วยสิ่งนี้ เจ้าจะตั้งแคมป์ได้ทุกที่ในป่า สิ่งที่เรียนเป็นเพียงพื้นฐาน จึงยังวางเครื่องเรือนได้ไม่มาก\n\nเพิ่มทักษะทำอาหาร แล้วอาจเรียนก่อไฟใหญ่ขึ้นได้\n\nหากชำนาญทักษะวิชาชีพอื่น ก็เรียนพื้นฐานเครื่องเรือนแคมป์จากครูเหล่านั้นได้ด้วย" },
        progress = { "51:829941131:405173494", "กองไฟดีคือรากฐานแคมป์ดี" },
        steps = { { "47:1989633389:1220034058", "เรียนทำอาหารกับ Gremlock Pilsnor ที่ Kharanos" } },
    },
    [96630] = { -- The Adventurer
        title = { "14:1141602346:434160617", "นักผจญภัย" },
        objective = { "53:33907532:606161231", "นำสมุดบันทึกไปให้ Lyreena Duskblade ใกล้ Dolanaar" },
        description = { "184:341205653:1050813866", "<สมุดดูธรรมดา บันทึกชีวิตและการผจญภัยของคนที่เจ้าไม่เคยรู้จัก\n\nหลายตอนกล่าวถึงตั้งแคมป์ ดูเหมือนจะ... สนุกทีเดียว>" },
        progress = { "54:1549646360:72988903", "มาที่นี่เพื่อเรียนตั้งแคมป์ในป่าหรือ?" },
        completion = { "169:1192729125:499250314", "สมุดข้าหรือ? หายไปพักหนึ่งแล้ว ขอบคุณ พราน\n\nเฮ้ เจ้าก็ดูเป็นนักผจญภัย อยากเรียนเรื่องตั้งแคมป์ไหม?", variants = { { "168:8153076:1047796226", "สมุดข้าหรือ? หายไปพักหนึ่งแล้ว ขอบคุณ ดรูอิด\n\nเฮ้ เจ้าก็ดูเป็นนักผจญภัย อยากเรียนเรื่องตั้งแคมป์ไหม?" }, { "170:640765962:1195075385", "นั่นสมุดบันทึกของข้าใช่ไหม? ข้าทำหายไปพักหนึ่งแล้ว ขอบใจนะ นักรบ\n\nดูท่าเจ้าจะเป็นนักผจญภัยเหมือนกัน สนใจเรียนวิธีตั้งแคมป์ไหม?" } } },
        required = { [275022] = { "12:2112861961:1127570904", "สมุดบันทึกที่หายไป" } },
        steps = { { "12:2112861961:1127570904", "สมุดบันทึกที่หายไป" } },
    },
