    [96659] = { -- The Adventurer
        title = { "14:1141602346:434160617", "นักผจญภัย" },
        objective = { "66:1564119685:845036477", "ส่ง Supply Bundle ให้ Kaga Wildhoof ใกล้ Bloodhoof Village" },
        description = { "6:1516321299:785938697 N 272:1785274596:2061911189", "เดี๋ยว {name} ก่อนจากไป ข้าขออีกอย่าง\n\nมีนักผจญภัยชื่อ Kaga Wildhoof ตั้งแคมป์นอก Bloodhoof Village นางเคยช่วยมาก ตอนนี้เห็นโอกาสตอบแทน ช่วยส่งเสบียงนี้ให้นางได้ไหม?" },
        progress = { "54:1549646360:72988903", "มาที่นี่เพื่อเรียนตั้งแคมป์ในป่าหรือ?" },
        completion = { { "222:781282228:847353012", "116:1483229011:410262249 N 96:1995472338:1480495551", "116:1483229011:410262249 C 96:1995472338:1480495551", "116:1483229011:410262249 R 96:1995472338:1480495551" }, "Chief Hawkwind ส่งมาหรือ? ตอนนั้นบอกแล้วว่าไม่ต้องตอบแทน แต่ดูไม่ฟัง ขอบคุณ นักผจญภัย\n\nเฮ้ เจ้าก็ดูเป็นนักผจญภัย อยากเรียนเรื่องตั้งแคมป์ไหม?" },
