    [97899] = { -- Camping 101: Alchemy
        title = { "20:915921786:1716389149", "ตั้งแคมป์ 101: เล่นแร่แปรธาตุ" },
        objective = { "129:964773969:146868979", "คุยกับ Whuut ใน Orgrimmar เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "299:410594040:787058671", "เลือกปรุงเครื่องดื่มกับน้ำยาเป็นนักเล่นแร่แปรธาตุหรือ มั่นใจว่ามีประโยชน์ในการเดินทาง\n\nข้ารู้จักคนสอนสร้าง Mana Well สำหรับแคมป์ได้ สร้างแล้วผู้รักษากับผู้ใช้คาถาคงวิ่งมาชิมความสดชื่นกัน" },
        completion = { "427:902470521:215580908", "เอาละ นี่คือวิธีทำ Mana Well ของเจ้าเอง คนส่วนใหญ่ไม่ชอบให้ตั้งค่ายกลางเมือง ถ้าอยากลองก็ต้องออกไปในป่า\n\nทุกค่ายต้องมีกองไฟ ต้องก่อไฟไว้เป็นจุดตั้งต้นของค่าย พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้ได้ ถ้ายังไม่รู้พื้นฐานก็ลองไปหาคนที่สอนทำอาหารดู" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        steps = { { "30:1831080184:1814656452", "เพิ่มทักษะการเล่นแร่แปรธาตุให้ถึง 20" } },
    },
    [97900] = { -- Camping 101: Blacksmithing
        title = { "26:1221764726:279206460", "ตั้งแคมป์ 101: ตีเหล็ก" },
        objective = { "130:800256586:617447451", "คุยกับ Dwukk ใน Razor Hill เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "320:202320231:852909869", "เป็นช่างตีเหล็กแล้วหรือ เป็นตัวเลือกดีหากอยากให้คมดาบไม่ทื่อ\n\nข้ารู้จักคนช่วยสอนสร้าง Sharpening Wheel ได้ ตั้งในแคมป์แล้วนักรบกับโจรแถวนั้นคงต่อแถวลับอาวุธกัน" },
        completion = { "495:2117961607:447306361", "เรียบร้อย ตอนนี้เจ้าสร้าง Sharpening Wheel ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้สิ ข้าสอนเจ้าได้" },
        steps = { { "36:482259371:1296802253", "เพิ่มทักษะการตีเหล็กให้ถึง 20" } },
    },
    [97901] = { -- Camping 101: Enchanting
        title = { "23:1713173955:924427762", "ตั้งแคมป์ 101: ลงมนตร์" },
        objective = { "128:1191517348:1825752355", "คุยกับ Jhag ใน Orgrimmar เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "369:1066151520:1036025452", "ผู้ลงมนตร์ทำทุกสิ่งดีขึ้นและเป็นที่ต้อนรับในทุกแคมป์กลางป่า\n\nข้ารู้จักคนสอนสร้าง Enchanted Lute ได้ ความบันเทิงยามพักสำคัญมาก เวทเล็กน้อยนี้ช่วยให้พร้อมรับความท้าทายสารพัด เมื่อกลับออกสู่ทางฝุ่นอีกครั้ง" },
        completion = { "432:1072450999:1308343145", "เรียบร้อย เจ้าสร้าง Enchanted Lute ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีเป็นรากฐาน พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้พื้นฐาน ไปหาผู้ฝึกทำอาหาร" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        steps = { { "33:1774593141:15047791", "เพิ่มทักษะการเสริมมนตร์ให้ถึง 20" } },
    },
    [97902] = { -- Camping 101: Engineering
        title = { "24:1086805395:342974848", "ตั้งแคมป์ 101: วิศวกรรม" },
        objective = { "132:1653018556:43752540", "คุยกับ Mukdrak ใน Razor Hill เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "317:1777421338:1929417440", "วิศวกรเช่นเจ้าประดิษฐ์ชิ้นส่วน หุ่น และระเบิดสารพัดได้ทั้งสนุกและมีกำไร\n\nข้ารู้จักคนสอนสร้าง Reagent Bot สำหรับแคมป์ได้ หุ่นช่วยเหลือนี้ดูแลเสบียงให้พร้อม เพื่อเจ้าและพันธมิตรไม่ขาดวัตถุดิบร่ายคาถา" },
        completion = { "490:66550901:387364094", "เรียบร้อย ทีนี้เจ้าก็สร้าง Reagent Bot ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "34:796380127:1923393619", "เพิ่มทักษะวิศวกรรมให้ถึง 20" } },
    },
    [97903] = { -- Camping 101: First Aid
        title = { "22:1169076296:1627423262", "ตั้งแคมป์ 101: ปฐมพยาบาล" },
        objective = { "130:972090399:933618032", "คุยกับ Rawrk ใน Razor Hill เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "80:1405944155:1276912498 C 213:1979165028:833800773", "เลือกปฐมพยาบาลหรือ? เป็นหนทางน่ายกย่อง... และเหมาะใช้จริงสำหรับ{class}\n\nข้ารู้จักคนสอนสร้าง First Aid Kit สำหรับแคมป์ได้ บาดเจ็บเป็นเรื่องจริงของโลกผจญภัย การมีการรักษาที่จำเป็นในแคมป์อาจช่วยชีวิตด้วยซ้ำ" },
        completion = { "492:1329339879:521834233", "เรียบร้อย ตอนนี้เจ้าสร้าง First Aid Kit ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "67:1070716708:1493071004", "ข้าสอนได้เมื่อเจ้าเพิ่มทักษะวิชาชีพสักหน่อยแล้ว" },
        steps = { { "32:2128258987:594859909", "เพิ่มทักษะการปฐมพยาบาลให้ถึง 20" } },
    },
    [97904] = { -- Camping 101: Fishing
        title = { "20:1026779672:337511730", "ตั้งแคมป์ 101: ตกปลา" },
        objective = { "140:782437139:2133528120", "คุยกับ Lau'Tiki ใกล้ Sen'jin Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "366:2115126721:2001310912", "เจ้าอาจไม่คิดเช่นนั้น แต่ทักษะตกปลามีประโยชน์ในแคมป์จริง ๆ\n\nข้ารู้จักคนสอนสร้าง Fish Bowl ได้ ใช้อุปกรณ์นี้มอบความสุขเล็ก ๆ ให้ตนกับสหายนักผจญภัย คนมีความสุขย่อมเข้มแข็ง ข้ามั่นใจว่าความสามารถสู้จะสะท้อนเช่นนั้น" },
        completion = { "457:864490144:867756186", "เรียบร้อย เจ้าเพิ่งทำ Fish Bowl ของตัวเองสำเร็จแล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งค่ายกันกลางเมือง ถ้าอยากลองใช้ดู เจ้าต้องออกไปนอกเมือง\n\nค่ายไหน ๆ ก็ต้องมีกองไฟ สหาย เจ้าต้องก่อไฟก่อนถึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟได้ ถ้ายังไม่เคยเรียนทำอาหารเบื้องต้น ลองไปหาคนที่ฝึกวิชานี้ให้เจ้าได้" },
        progress = { "61:1928447902:874189049", "ข้าสอนได้เมื่อเจ้าเพิ่มทักษะตกปลาสักหน่อยแล้ว" },
        steps = { { "30:486045795:699998660", "เพิ่มทักษะการตกปลาให้ถึง 20" } },
    },
    [97905] = { -- Camping 101: Herbalism
        title = { "22:398153440:411836651", "ตั้งแคมป์ 101: สมุนไพร" },
        objective = { "129:469256568:812411041", "คุยกับ Jandi ใน Orgrimmar เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "403:1734578767:1649451813", "ดูเหมือนมีทักษะสมุนไพรแล้ว เก็บดอกไม้ไม่ใช่แค่เดินเอ้อระเหยรู้ไหม มีทั้งประโยชน์... และกำไร\n\nข้ารู้จักคนสอนสร้าง Incense Candle สำหรับแคมป์ได้ ขวัญกำลังใจสูงสำคัญต่อการให้ผู้รักษากับผู้ร่ายคาถาสู้ต่อ เทียนหอมช่วยเสริมสิ่งที่ผู้ใช้เวทต้องชื่นชอบแน่" },
        completion = { "462:302325923:796421185", "เอาละ ทีนี้เจ้าก็ทำ Incense Candle ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งค่ายกลางเมือง ถ้าอยากลองก็ออกไปในป่าเถอะ\n\nค่ายต้องมีกองไฟนะพวก ต้องมีกองไฟสักกองก่อนตั้งค่าย พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้ได้ ถ้ายังไม่รู้พื้นฐานก็ไปหาคนที่สอนทำอาหารดู" },
        steps = { { "32:185111467:616084806", "เพิ่มทักษะการเก็บสมุนไพรให้ถึง 20" } },
    },
    [97906] = { -- Camping 101: Leatherworking
        title = { "27:1698130846:1506167115", "ตั้งแคมป์ 101: เครื่องหนัง" },
        objective = { "131:951114239:718654373", "คุยกับ Karolek ใน Orgrimmar เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "45:1200778187:1735425090 C 245:815205661:284337473", "เจ้าเป็นช่างหนังแล้ว ดีมาก {class} ข้าว่ารู้จักคนสอนทำเต็นท์ให้เย็นในวันร้อนและแห้งในวันฝนได้\n\nมีเต็นท์ดีคลุมหัว ก็มั่นใจได้ว่าจะพักเต็มที่พอให้ตื่นตัวระหว่างเดินทาง" },
        completion = { "470:577898743:1109976944", "เรียบร้อย เต็นท์แคมป์ของเจ้าเอง คนส่วนใหญ่ไม่ชอบให้กางเต็นท์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "37:614229450:1985955440", "เพิ่มทักษะการทำเครื่องหนังให้ถึง 20" } },
    },
    [97907] = { -- Camping 101: Mining
        title = { "19:2134334844:1251681605", "ตั้งแคมป์ 101: ขุดแร่" },
        objective = { "130:1569723541:718163790", "คุยกับ Krunn ใน Razor Hill เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "361:1382345230:1652658988", "ขุดแร่อาจไม่เลิศหรู แต่เป็นงานสุจริตดีและวิชาชีพที่น่าศึกษา\n\nข้ารู้จักคนสอนสร้าง Lodestone สำหรับแคมป์ได้ ตั้งแล้วทุกคนที่อยากเหวี่ยงดาบคงมารวมรอบไฟ รับแรงฮึดเสริมฝีมือสู้จากมัน" },
        completion = { "488:837518116:1487918719", "เรียบร้อย ตอนนี้เจ้าสร้าง Lodestone ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "39:241285775:67526017", "ข้าสอนให้เจ้าชำนาญขึ้นได้" },
        steps = { { "29:1326993482:1796014523", "เพิ่มทักษะการขุดแร่ให้ถึง 20" } },
    },
    [97908] = { -- Camping 101: Skinning
        title = { "21:877856129:1615425789", "ตั้งแคมป์ 101: ถลกหนัง" },
        objective = { "129:1454207372:902865411", "คุยกับ Thuwd ใน Orgrimmar เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "499:1267848069:485795793", "การเก็บหนังจากสัตว์ที่ล้มอย่างชำนาญเป็นทักษะมีค่ายิ่งอย่างหนึ่งของนักผจญภัย\n\nข้ารู้จักคนสอนสร้าง Camp Chair ได้ บางครั้งการปลดภาระพักสักหน่อยสำคัญ ใช้หนังที่เก็บมาทำเก้าอี้นุ่มนั่ง ผ่อนคลายบ้างจะช่วยให้อยู่ในสภาพดีและโจมตีถูกจุดเมื่อมีเรื่องครั้งหน้า" },
        completion = { "489:1841325329:1145743259", "เรียบร้อย ตอนนี้เจ้าสร้าง Camp Chair ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "39:1677459469:1082148760", "ถ้าเจ้ามีฝีมือพอ ข้าก็สอนเจ้าได้" },
        steps = { { "31:830454515:1981975140", "เพิ่มทักษะการถลกหนังให้ถึง 20" } },
    },
    [97915] = { -- Camping 101: Alchemy
        title = { "20:915921786:1716389149", "ตั้งแคมป์ 101: เล่นแร่แปรธาตุ" },
        objective = { "160:1049795875:1771637222", "คุยกับ Alchemist Mallory ใน Elwynn Forest ใกล้ Stormwind เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "299:410594040:787058671", "เลือกปรุงเครื่องดื่มกับน้ำยาเป็นนักเล่นแร่แปรธาตุหรือ มั่นใจว่ามีประโยชน์ในการเดินทาง\n\nข้ารู้จักคนสอนสร้าง Mana Well สำหรับแคมป์ได้ สร้างแล้วผู้รักษากับผู้ใช้คาถาคงวิ่งมาชิมความสดชื่นกัน" },
        completion = { "488:892105979:1076061495", "เรียบร้อย ตอนนี้เจ้าสร้าง Mana Well ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "30:1831080184:1814656452", "เพิ่มทักษะการเล่นแร่แปรธาตุให้ถึง 20" } },
        progress = { "21:597269750:1281937852", "ใช่ ข้าสอนเจ้าได้" },
    },
    [97916] = { -- Camping 101: Blacksmithing
        title = { "26:1221764726:279206460", "ตั้งแคมป์ 101: ตีเหล็ก" },
        objective = { "135:626371803:1222065275", "คุยกับ Smith Argus ใน Goldshire เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "320:202320231:852909869", "เป็นช่างตีเหล็กแล้วหรือ เป็นตัวเลือกดีหากอยากให้คมดาบไม่ทื่อ\n\nข้ารู้จักคนช่วยสอนสร้าง Sharpening Wheel ได้ ตั้งในแคมป์แล้วนักรบกับโจรแถวนั้นคงต่อแถวลับอาวุธกัน" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        completion = { "495:2117961607:447306361", "เรียบร้อย ตอนนี้เจ้าสร้าง Sharpening Wheel ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "36:482259371:1296802253", "เพิ่มทักษะการตีเหล็กให้ถึง 20" } },
    },
    [97917] = { -- Camping 101: Enchanting
        title = { "23:1713173955:924427762", "ตั้งแคมป์ 101: ลงมนตร์" },
        objective = { "134:2120213547:1228531409", "คุยกับ Betty Quin ใน Stormwind เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "369:1066151520:1036025452", "ผู้ลงมนตร์ทำทุกสิ่งดีขึ้นและเป็นที่ต้อนรับในทุกแคมป์กลางป่า\n\nข้ารู้จักคนสอนสร้าง Enchanted Lute ได้ ความบันเทิงยามพักสำคัญมาก เวทเล็กน้อยนี้ช่วยให้พร้อมรับความท้าทายสารพัด เมื่อกลับออกสู่ทางฝุ่นอีกครั้ง" },
        completion = { "493:1415932902:592769654", "เรียบร้อย ทีนี้เจ้าก็ทำ Enchanted Lute ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "21:597269750:1281937852", "ได้สิ ข้าสอนเจ้าได้" },
        steps = { { "33:1774593141:15047791", "เพิ่มทักษะการเสริมมนตร์ให้ถึง 20" } },
    },
    [97918] = { -- Camping 101: Engineering
        title = { "24:1086805395:342974848", "ตั้งแคมป์ 101: วิศวกรรม" },
        objective = { "143:1430348233:725135033", "คุยกับ Sprite Jumpsprocket ใน Stormwind เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "317:1777421338:1929417440", "วิศวกรเช่นเจ้าประดิษฐ์ชิ้นส่วน หุ่น และระเบิดสารพัดได้ทั้งสนุกและมีกำไร\n\nข้ารู้จักคนสอนสร้าง Reagent Bot สำหรับแคมป์ได้ หุ่นช่วยเหลือนี้ดูแลเสบียงให้พร้อม เพื่อเจ้าและพันธมิตรไม่ขาดวัตถุดิบร่ายคาถา" },
        completion = { "490:66550901:387364094", "เรียบร้อย ทีนี้เจ้าก็สร้าง Reagent Bot ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "34:796380127:1923393619", "เพิ่มทักษะวิศวกรรมให้ถึง 20" } },
    },
    [97919] = { -- Camping 101: First Aid
        title = { "22:1169076296:1627423262", "ตั้งแคมป์ 101: ปฐมพยาบาล" },
        objective = { "138:532090003:393870652", "คุยกับ Michelle Belle ใน Goldshire เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "80:1405944155:1276912498 C 213:1979165028:833800773", "เลือกปฐมพยาบาลหรือ? เป็นหนทางน่ายกย่อง... และเหมาะใช้จริงสำหรับ{class}\n\nข้ารู้จักคนสอนสร้าง First Aid Kit สำหรับแคมป์ได้ บาดเจ็บเป็นเรื่องจริงของโลกผจญภัย การมีการรักษาที่จำเป็นในแคมป์อาจช่วยชีวิตด้วยซ้ำ" },
        progress = { "67:1070716708:1493071004", "ข้าสอนได้เมื่อเจ้าเพิ่มทักษะวิชาชีพสักหน่อยแล้ว" },
        completion = { "492:1329339879:521834233", "เรียบร้อย ตอนนี้เจ้าสร้าง First Aid Kit ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "32:2128258987:594859909", "เพิ่มทักษะการปฐมพยาบาลให้ถึง 20" } },
    },
    [97920] = { -- Camping 101: Fishing
        title = { "20:1026779672:337511730", "ตั้งแคมป์ 101: ตกปลา" },
        objective = { "135:988558903:1521513775", "คุยกับ Lee Brown ใกล้ Goldshire เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "366:2115126721:2001310912", "เจ้าอาจไม่คิดเช่นนั้น แต่ทักษะตกปลามีประโยชน์ในแคมป์จริง ๆ\n\nข้ารู้จักคนสอนสร้าง Fish Bowl ได้ ใช้อุปกรณ์นี้มอบความสุขเล็ก ๆ ให้ตนกับสหายนักผจญภัย คนมีความสุขย่อมเข้มแข็ง ข้ามั่นใจว่าความสามารถสู้จะสะท้อนเช่นนั้น" },
        progress = { "61:1928447902:874189049", "ข้าสอนได้เมื่อเจ้าเพิ่มทักษะตกปลาสักหน่อยแล้ว" },
        completion = { "488:1416066424:65558197", "เรียบร้อย ตอนนี้เจ้าสร้าง Fish Bowl ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "30:486045795:699998660", "เพิ่มทักษะการตกปลาให้ถึง 20" } },
    },
    [97921] = { -- Camping 101: Herbalism
        title = { "22:398153440:411836651", "ตั้งแคมป์ 101: สมุนไพร" },
        objective = { "145:1904944394:1089309050", "คุยกับ Herbalist Pomeroy ใน Elwynn Forest เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "403:1734578767:1649451813", "ดูเหมือนมีทักษะสมุนไพรแล้ว เก็บดอกไม้ไม่ใช่แค่เดินเอ้อระเหยรู้ไหม มีทั้งประโยชน์... และกำไร\n\nข้ารู้จักคนสอนสร้าง Incense Candle สำหรับแคมป์ได้ ขวัญกำลังใจสูงสำคัญต่อการให้ผู้รักษากับผู้ร่ายคาถาสู้ต่อ เทียนหอมช่วยเสริมสิ่งที่ผู้ใช้เวทต้องชื่นชอบแน่" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        completion = { "493:2089714052:1219300209", "เรียบร้อย ทีนี้เจ้าก็ทำ Incense Candle ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "32:185111467:616084806", "เพิ่มทักษะการเก็บสมุนไพรให้ถึง 20" } },
    },
    [97922] = { -- Camping 101: Leatherworking
        title = { "27:1698130846:1506167115", "ตั้งแคมป์ 101: เครื่องหนัง" },
        objective = { "137:2086320244:1441460279", "คุยกับ Adele Fielder ใน Goldshire เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "45:1200778187:1735425090 C 245:815205661:284337473", "เจ้าเป็นช่างหนังแล้ว ดีมาก {class} ข้าว่ารู้จักคนสอนทำเต็นท์ให้เย็นในวันร้อนและแห้งในวันฝนได้\n\nมีเต็นท์ดีคลุมหัว ก็มั่นใจได้ว่าจะพักเต็มที่พอให้ตื่นตัวระหว่างเดินทาง" },
        completion = { "470:577898743:1109976944", "เรียบร้อย เต็นท์แคมป์ของเจ้าเอง คนส่วนใหญ่ไม่ชอบให้กางเต็นท์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้สิ ข้าสอนเจ้าได้" },
        steps = { { "37:614229450:1985955440", "เพิ่มทักษะการทำเครื่องหนังให้ถึง 20" } },
    },
    [97923] = { -- Camping 101: Mining
        title = { "19:2134334844:1251681605", "ตั้งแคมป์ 101: ขุดแร่" },
        objective = { "140:363859086:1295783646", "คุยกับ Gelman Stonehand ใน Stormwind เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "361:1382345230:1652658988", "ขุดแร่อาจไม่เลิศหรู แต่เป็นงานสุจริตดีและวิชาชีพที่น่าศึกษา\n\nข้ารู้จักคนสอนสร้าง Lodestone สำหรับแคมป์ได้ ตั้งแล้วทุกคนที่อยากเหวี่ยงดาบคงมารวมรอบไฟ รับแรงฮึดเสริมฝีมือสู้จากมัน" },
        progress = { "53:169474883:1012945664", "ข้าแสดงบางอย่างให้ดูได้ หากเจ้ามีความสามารถ" },
        completion = { "488:837518116:1487918719", "เรียบร้อย ตอนนี้เจ้าสร้าง Lodestone ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "29:1326993482:1796014523", "เพิ่มทักษะการขุดแร่ให้ถึง 20" } },
    },
    [97924] = { -- Camping 101: Skinning
        title = { "21:877856129:1615425789", "ตั้งแคมป์ 101: ถลกหนัง" },
        objective = { "142:1359350341:1273641565", "คุยกับ Helene Peltskinner ใน Goldshire เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "499:1267848069:485795793", "การเก็บหนังจากสัตว์ที่ล้มอย่างชำนาญเป็นทักษะมีค่ายิ่งอย่างหนึ่งของนักผจญภัย\n\nข้ารู้จักคนสอนสร้าง Camp Chair ได้ บางครั้งการปลดภาระพักสักหน่อยสำคัญ ใช้หนังที่เก็บมาทำเก้าอี้นุ่มนั่ง ผ่อนคลายบ้างจะช่วยให้อยู่ในสภาพดีและโจมตีถูกจุดเมื่อมีเรื่องครั้งหน้า" },
        completion = { "489:1841325329:1145743259", "เรียบร้อย ตอนนี้เจ้าสร้าง Camp Chair ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "57:457662099:311999033", "ถ้าเจ้าพอมีฝีมือ ข้าก็พอจะสอนอะไรให้ได้สักสองสามอย่าง" },
        steps = { { "31:830454515:1981975140", "เพิ่มทักษะการถลกหนังให้ถึง 20" } },
    },
    [97925] = { -- Camping 101: Tailoring
        title = { "22:1431642385:2057581804", "ตั้งแคมป์ 101: ตัดเย็บ" },
        objective = { "163:334177556:1103765895", "คุยกับ Eldrin ที่ Eastvale Logging Camp ใน Elwynn Forest เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "350:1427230788:143007988", "ตัดเย็บเป็นวิชาชีพทรงพลังเกินคาดที่ควรลงทุน ข้ามั่นใจว่าจะช่วยเจ้าได้ดี\n\nข้ารู้จักคนสอนสร้าง Faction Banner สำหรับแคมป์ได้ หากมีทักษะพอ แรงบันดาลใจกับขวัญสำคัญต่อชัยชนะทุกสนามรบ ธงเร้าใจช่วยคงพลังฮึกเหิมได้มาก" },
        completion = { "494:1045707758:1807747544", "เรียบร้อย ทีนี้เจ้าก็ทำ Rallying Banner ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "73:485067858:700703801", "กลับมาคุยกับข้าอีกทีเมื่อเจ้าชำนาญวิชาชีพของเจ้าขึ้นอีกหน่อย" },
        steps = { { "32:2138986334:1672550921", "เพิ่มทักษะการตัดเย็บให้ถึง 20" } },
    },
    [97927] = { -- Camping 101: Alchemy
        title = { "20:915921786:1716389149", "ตั้งแคมป์ 101: เล่นแร่แปรธาตุ" },
        objective = { "132:1955776298:2103020432", "คุยกับ Kray ใน Thunder Bluff เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "299:410594040:787058671", "เลือกปรุงเครื่องดื่มกับน้ำยาเป็นนักเล่นแร่แปรธาตุหรือ มั่นใจว่ามีประโยชน์ในการเดินทาง\n\nข้ารู้จักคนสอนสร้าง Mana Well สำหรับแคมป์ได้ สร้างแล้วผู้รักษากับผู้ใช้คาถาคงวิ่งมาชิมความสดชื่นกัน" },
        completion = { "488:892105979:1076061495", "เรียบร้อย ตอนนี้เจ้าสร้าง Mana Well ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "30:1831080184:1814656452", "เพิ่มทักษะการเล่นแร่แปรธาตุให้ถึง 20" } },
        progress = { "21:597269750:1281937852", "ใช่ ข้าสอนเจ้าได้" },
    },
    [97928] = { -- Camping 101: Blacksmithing
        title = { "26:1221764726:279206460", "ตั้งแคมป์ 101: ตีเหล็ก" },
        objective = { "143:1253604590:1277432649", "คุยกับ Thrag Stonehoof ใน Thunder Bluff เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "320:202320231:852909869", "เป็นช่างตีเหล็กแล้วหรือ เป็นตัวเลือกดีหากอยากให้คมดาบไม่ทื่อ\n\nข้ารู้จักคนช่วยสอนสร้าง Sharpening Wheel ได้ ตั้งในแคมป์แล้วนักรบกับโจรแถวนั้นคงต่อแถวลับอาวุธกัน" },
        completion = { "495:2117961607:447306361", "เรียบร้อย ตอนนี้เจ้าสร้าง Sharpening Wheel ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "36:482259371:1296802253", "เพิ่มทักษะการตีเหล็กให้ถึง 20" } },
    },
    [97929] = { -- Camping 101: Enchanting
        title = { "23:1713173955:924427762", "ตั้งแคมป์ 101: ลงมนตร์" },
        objective = { "143:2118174805:220606589", "คุยกับ Mot Dawnstrider ใน Thunder Bluff เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "369:1066151520:1036025452", "ผู้ลงมนตร์ทำทุกสิ่งดีขึ้นและเป็นที่ต้อนรับในทุกแคมป์กลางป่า\n\nข้ารู้จักคนสอนสร้าง Enchanted Lute ได้ ความบันเทิงยามพักสำคัญมาก เวทเล็กน้อยนี้ช่วยให้พร้อมรับความท้าทายสารพัด เมื่อกลับออกสู่ทางฝุ่นอีกครั้ง" },
        completion = { "493:1415932902:592769654", "เรียบร้อย ทีนี้เจ้าก็ทำ Enchanted Lute ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "33:1774593141:15047791", "เพิ่มทักษะการเสริมมนตร์ให้ถึง 20" } },
    },
    [97930] = { -- Camping 101: Engineering
        title = { "24:1086805395:342974848", "ตั้งแคมป์ 101: วิศวกรรม" },
        objective = { "168:911987683:337595903", "คุยกับ Twizwick Sprocketgrind ใน Venture Co. Mine แห่ง Mulgore เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "317:1777421338:1929417440", "วิศวกรเช่นเจ้าประดิษฐ์ชิ้นส่วน หุ่น และระเบิดสารพัดได้ทั้งสนุกและมีกำไร\n\nข้ารู้จักคนสอนสร้าง Reagent Bot สำหรับแคมป์ได้ หุ่นช่วยเหลือนี้ดูแลเสบียงให้พร้อม เพื่อเจ้าและพันธมิตรไม่ขาดวัตถุดิบร่ายคาถา" },
        completion = { "490:66550901:387364094", "เรียบร้อย ทีนี้เจ้าก็สร้าง Reagent Bot ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "34:796380127:1923393619", "เพิ่มทักษะวิศวกรรมให้ถึง 20" } },
    },
    [97931] = { -- Camping 101: First Aid
        title = { "22:1169076296:1627423262", "ตั้งแคมป์ 101: ปฐมพยาบาล" },
        objective = { "146:906514317:1289432532", "คุยกับ Vira Younghoof ใน Bloodhoof Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "80:1405944155:1276912498 C 213:1979165028:833800773", "เลือกปฐมพยาบาลหรือ? เป็นหนทางน่ายกย่อง... และเหมาะใช้จริงสำหรับ{class}\n\nข้ารู้จักคนสอนสร้าง First Aid Kit สำหรับแคมป์ได้ บาดเจ็บเป็นเรื่องจริงของโลกผจญภัย การมีการรักษาที่จำเป็นในแคมป์อาจช่วยชีวิตด้วยซ้ำ", variants = { { "300:2094795630:2100890258", "เลือกปฐมพยาบาลหรือ? เป็นหนทางน่ายกย่อง... และเหมาะใช้จริงสำหรับนักรบ\n\nข้ารู้จักคนสอนสร้าง First Aid Kit สำหรับแคมป์ได้ บาดเจ็บเป็นเรื่องจริงของโลกผจญภัย การมีการรักษาที่จำเป็นในแคมป์อาจช่วยชีวิตด้วยซ้ำ" } } },
        completion = { "492:1329339879:521834233", "เรียบร้อย ตอนนี้เจ้าสร้าง First Aid Kit ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "67:1070716708:1493071004", "เมื่อเจ้าชำนาญวิชาชีพของเจ้าขึ้นอีกสักหน่อย ข้าก็สอนเจ้าได้" },
        steps = { { "32:2128258987:594859909", "เพิ่มทักษะการปฐมพยาบาลให้ถึง 20" } },
    },
    [97932] = { -- Camping 101: Fishing
        title = { "20:1026779672:337511730", "ตั้งแคมป์ 101: ตกปลา" },
        objective = { "148:126416390:1520990617", "คุยกับ Uthan Stillwater ใน Bloodhoof Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "366:2115126721:2001310912", "เจ้าอาจไม่คิดเช่นนั้น แต่ทักษะตกปลามีประโยชน์ในแคมป์จริง ๆ\n\nข้ารู้จักคนสอนสร้าง Fish Bowl ได้ ใช้อุปกรณ์นี้มอบความสุขเล็ก ๆ ให้ตนกับสหายนักผจญภัย คนมีความสุขย่อมเข้มแข็ง ข้ามั่นใจว่าความสามารถสู้จะสะท้อนเช่นนั้น" },
        completion = { "488:1416066424:65558197", "เรียบร้อย ตอนนี้เจ้าสร้าง Fish Bowl ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "61:1928447902:874189049", "ข้าสอนเจ้าได้เมื่อเจ้าฝึกตกปลาจนมีทักษะขึ้นมาบ้าง" },
        steps = { { "30:486045795:699998660", "เพิ่มทักษะการตกปลาให้ถึง 20" } },
    },
    [97933] = { -- Camping 101: Herbalism
        title = { "22:398153440:411836651", "ตั้งแคมป์ 101: สมุนไพร" },
        objective = { "144:795381112:659391947", "คุยกับ Komin Winterhoof ใน Thunder Bluff เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "403:1734578767:1649451813", "ดูเหมือนมีทักษะสมุนไพรแล้ว เก็บดอกไม้ไม่ใช่แค่เดินเอ้อระเหยรู้ไหม มีทั้งประโยชน์... และกำไร\n\nข้ารู้จักคนสอนสร้าง Incense Candle สำหรับแคมป์ได้ ขวัญกำลังใจสูงสำคัญต่อการให้ผู้รักษากับผู้ร่ายคาถาสู้ต่อ เทียนหอมช่วยเสริมสิ่งที่ผู้ใช้เวทต้องชื่นชอบแน่" },
        completion = { "493:2089714052:1219300209", "เรียบร้อย ทีนี้เจ้าก็ทำ Incense Candle ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "21:597269750:1281937852", "ได้สิ ข้าสอนเจ้าได้" },
        steps = { { "32:185111467:616084806", "เพิ่มทักษะการเก็บสมุนไพรให้ถึง 20" } },
    },
    [97934] = { -- Camping 101: Leatherworking
        title = { "27:1698130846:1506167115", "ตั้งแคมป์ 101: เครื่องหนัง" },
        objective = { "147:2111199094:717881348", "คุยกับ Chaw Stronghide ใน Bloodhoof Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "45:1200778187:1735425090 C 245:815205661:284337473", "เจ้าเป็นช่างหนังแล้ว ดีมาก {class} ข้าว่ารู้จักคนสอนทำเต็นท์ให้เย็นในวันร้อนและแห้งในวันฝนได้\n\nมีเต็นท์ดีคลุมหัว ก็มั่นใจได้ว่าจะพักเต็มที่พอให้ตื่นตัวระหว่างเดินทาง" },
        completion = { "470:577898743:1109976944", "เรียบร้อย เต็นท์แคมป์ของเจ้าเอง คนส่วนใหญ่ไม่ชอบให้กางเต็นท์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้สิ ข้าสอนเจ้าได้" },
        steps = { { "37:614229450:1985955440", "เพิ่มทักษะการทำเครื่องหนังให้ถึง 20" } },
    },
    [97935] = { -- Camping 101: Mining
        title = { "19:2134334844:1251681605", "ตั้งแคมป์ 101: ขุดแร่" },
        objective = { "142:1330166905:2142084523", "คุยกับ Brek Stonehoof ใน Thunder Bluff เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "361:1382345230:1652658988", "ขุดแร่อาจไม่เลิศหรู แต่เป็นงานสุจริตดีและวิชาชีพที่น่าศึกษา\n\nข้ารู้จักคนสอนสร้าง Lodestone สำหรับแคมป์ได้ ตั้งแล้วทุกคนที่อยากเหวี่ยงดาบคงมารวมรอบไฟ รับแรงฮึดเสริมฝีมือสู้จากมัน" },
        completion = { "488:837518116:1487918719", "เรียบร้อย ตอนนี้เจ้าสร้าง Lodestone ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "29:1326993482:1796014523", "เพิ่มทักษะการขุดแร่ให้ถึง 20" } },
        progress = { "27:1589741062:9122832", "เจ้ามาเพื่อเรียนรู้สินะ?" },
    },
    [97936] = { -- Camping 101: Skinning
        title = { "21:877856129:1615425789", "ตั้งแคมป์ 101: ถลกหนัง" },
        objective = { "144:1311443612:1446810169", "คุยกับ Yonn Deepcut ใน Bloodhoof Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "499:1267848069:485795793", "การเก็บหนังจากสัตว์ที่ล้มอย่างชำนาญเป็นทักษะมีค่ายิ่งอย่างหนึ่งของนักผจญภัย\n\nข้ารู้จักคนสอนสร้าง Camp Chair ได้ บางครั้งการปลดภาระพักสักหน่อยสำคัญ ใช้หนังที่เก็บมาทำเก้าอี้นุ่มนั่ง ผ่อนคลายบ้างจะช่วยให้อยู่ในสภาพดีและโจมตีถูกจุดเมื่อมีเรื่องครั้งหน้า" },
        completion = { "489:1841325329:1145743259", "เรียบร้อย ตอนนี้เจ้าสร้าง Camp Chair ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "39:1156101743:2051367724", "ถ้าเจ้ามีฝีมือพอ ข้าก็ฝึกให้เจ้าได้" },
        steps = { { "31:830454515:1981975140", "เพิ่มทักษะการถลกหนังให้ถึง 20" } },
    },
    [97937] = { -- Camping 101: Tailoring
        title = { "22:1431642385:2057581804", "ตั้งแคมป์ 101: ตัดเย็บ" },
        objective = { "132:1581541403:1407149572", "คุยกับ Vhan ใน Thunder Bluff เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "350:1427230788:143007988", "ตัดเย็บเป็นวิชาชีพทรงพลังเกินคาดที่ควรลงทุน ข้ามั่นใจว่าจะช่วยเจ้าได้ดี\n\nข้ารู้จักคนสอนสร้าง Faction Banner สำหรับแคมป์ได้ หากมีทักษะพอ แรงบันดาลใจกับขวัญสำคัญต่อชัยชนะทุกสนามรบ ธงเร้าใจช่วยคงพลังฮึกเหิมได้มาก" },
        completion = { "494:1045707758:1807747544", "เรียบร้อย ทีนี้เจ้าก็ทำ Rallying Banner ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "32:2138986334:1672550921", "เพิ่มทักษะการตัดเย็บให้ถึง 20" } },
    },
    [97938] = { -- Camping 101: Alchemy
        title = { "20:915921786:1716389149", "ตั้งแคมป์ 101: เล่นแร่แปรธาตุ" },
        objective = { "141:1531197021:1975484839", "คุยกับ Cyndra Kindwhisper ใน Dolanaar เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "299:410594040:787058671", "เลือกปรุงเครื่องดื่มกับน้ำยาเป็นนักเล่นแร่แปรธาตุหรือ มั่นใจว่ามีประโยชน์ในการเดินทาง\n\nข้ารู้จักคนสอนสร้าง Mana Well สำหรับแคมป์ได้ สร้างแล้วผู้รักษากับผู้ใช้คาถาคงวิ่งมาชิมความสดชื่นกัน" },
        completion = { "488:892105979:1076061495", "เรียบร้อย ตอนนี้เจ้าสร้าง Mana Well ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้สิ ข้าสอนเจ้าได้" },
        steps = { { "30:1831080184:1814656452", "เพิ่มทักษะการเล่นแร่แปรธาตุให้ถึง 20" } },
    },
    [97939] = { -- Camping 101: Blacksmithing
        title = { "26:1221764726:279206460", "ตั้งแคมป์ 101: ตีเหล็ก" },
        objective = { "152:952771501:1531025571", "คุยกับ Elisa Steelhand ใน Auberdine แห่ง Darkshore เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "320:202320231:852909869", "เป็นช่างตีเหล็กแล้วหรือ เป็นตัวเลือกดีหากอยากให้คมดาบไม่ทื่อ\n\nข้ารู้จักคนช่วยสอนสร้าง Sharpening Wheel ได้ ตั้งในแคมป์แล้วนักรบกับโจรแถวนั้นคงต่อแถวลับอาวุธกัน" },
        completion = { "495:2117961607:447306361", "เรียบร้อย ทีนี้เจ้าก็ทำ Sharpening Wheel ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "36:482259371:1296802253", "เพิ่มทักษะการตีเหล็กให้ถึง 20" } },
    },
    [97940] = { -- Camping 101: Enchanting
        title = { "23:1713173955:924427762", "ตั้งแคมป์ 101: ลงมนตร์" },
        objective = { "160:624894862:780505495", "คุยกับ Alanna Raveneye ใน Oracle Glade แห่ง Teldrassil เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "369:1066151520:1036025452", "ผู้ลงมนตร์ทำทุกสิ่งดีขึ้นและเป็นที่ต้อนรับในทุกแคมป์กลางป่า\n\nข้ารู้จักคนสอนสร้าง Enchanted Lute ได้ ความบันเทิงยามพักสำคัญมาก เวทเล็กน้อยนี้ช่วยให้พร้อมรับความท้าทายสารพัด เมื่อกลับออกสู่ทางฝุ่นอีกครั้ง" },
        completion = { "493:1415932902:592769654", "เรียบร้อย ทีนี้เจ้าก็ทำ Enchanted Lute ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "33:1774593141:15047791", "เพิ่มทักษะการเสริมมนตร์ให้ถึง 20" } },
    },
    [97941] = { -- Camping 101: Engineering
        title = { "24:1086805395:342974848", "ตั้งแคมป์ 101: วิศวกรรม" },
        objective = { "153:652374533:206685060", "คุยกับ Jenna Lemkenilli ใน Auberdine แห่ง Darkshore เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "317:1777421338:1929417440", "วิศวกรเช่นเจ้าประดิษฐ์ชิ้นส่วน หุ่น และระเบิดสารพัดได้ทั้งสนุกและมีกำไร\n\nข้ารู้จักคนสอนสร้าง Reagent Bot สำหรับแคมป์ได้ หุ่นช่วยเหลือนี้ดูแลเสบียงให้พร้อม เพื่อเจ้าและพันธมิตรไม่ขาดวัตถุดิบร่ายคาถา" },
        completion = { "490:66550901:387364094", "เรียบร้อย ทีนี้เจ้าก็สร้าง Reagent Bot ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "34:796380127:1923393619", "เพิ่มทักษะวิศวกรรมให้ถึง 20" } },
    },
    [97942] = { -- Camping 101: First Aid
        title = { "22:1169076296:1627423262", "ตั้งแคมป์ 101: ปฐมพยาบาล" },
        objective = { "130:632641134:1670760750", "คุยกับ Byancie ใน Dolanaar เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "80:1405944155:1276912498 C 213:1979165028:833800773", "เลือกปฐมพยาบาลหรือ? เป็นหนทางน่ายกย่อง... และเหมาะใช้จริงสำหรับ{class}\n\nข้ารู้จักคนสอนสร้าง First Aid Kit สำหรับแคมป์ได้ บาดเจ็บเป็นเรื่องจริงของโลกผจญภัย การมีการรักษาที่จำเป็นในแคมป์อาจช่วยชีวิตด้วยซ้ำ" },
        completion = { "492:1329339879:521834233", "เรียบร้อย ตอนนี้เจ้าสร้าง First Aid Kit ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "67:1070716708:1493071004", "เมื่อเจ้าชำนาญวิชาชีพของเจ้าขึ้นอีกสักหน่อย ข้าก็สอนเจ้าได้" },
        steps = { { "32:2128258987:594859909", "เพิ่มทักษะการปฐมพยาบาลให้ถึง 20" } },
    },
    [97943] = { -- Camping 101: Fishing
        title = { "20:1026779672:337511730", "ตั้งแคมป์ 101: ตกปลา" },
        objective = { "130:2137641496:1037917177", "คุยกับ Astaia ใน Darnassus เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "366:2115126721:2001310912", "เจ้าอาจไม่คิดเช่นนั้น แต่ทักษะตกปลามีประโยชน์ในแคมป์จริง ๆ\n\nข้ารู้จักคนสอนสร้าง Fish Bowl ได้ ใช้อุปกรณ์นี้มอบความสุขเล็ก ๆ ให้ตนกับสหายนักผจญภัย คนมีความสุขย่อมเข้มแข็ง ข้ามั่นใจว่าความสามารถสู้จะสะท้อนเช่นนั้น" },
        completion = { "488:1416066424:65558197", "เรียบร้อย ตอนนี้เจ้าสร้าง Fish Bowl ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "61:1928447902:874189049", "ข้าสอนเจ้าได้เมื่อเจ้าฝึกตกปลาจนชำนาญขึ้นสักหน่อย" },
        steps = { { "30:486045795:699998660", "เพิ่มทักษะการตกปลาให้ถึง 20" } },
    },
    [97944] = { -- Camping 101: Herbalism
        title = { "22:398153440:411836651", "ตั้งแคมป์ 101: สมุนไพร" },
        objective = { "140:1072857563:2082050317", "คุยกับ Malorne Bladeleaf ใน Dolanaar เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "403:1734578767:1649451813", "ดูเหมือนมีทักษะสมุนไพรแล้ว เก็บดอกไม้ไม่ใช่แค่เดินเอ้อระเหยรู้ไหม มีทั้งประโยชน์... และกำไร\n\nข้ารู้จักคนสอนสร้าง Incense Candle สำหรับแคมป์ได้ ขวัญกำลังใจสูงสำคัญต่อการให้ผู้รักษากับผู้ร่ายคาถาสู้ต่อ เทียนหอมช่วยเสริมสิ่งที่ผู้ใช้เวทต้องชื่นชอบแน่" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        completion = { "493:2089714052:1219300209", "เรียบร้อย ทีนี้เจ้าก็ทำ Incense Candle ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "32:185111467:616084806", "เพิ่มทักษะการเก็บสมุนไพรให้ถึง 20" } },
    },
    [97946] = { -- Camping 101: Leatherworking
        title = { "27:1698130846:1506167115", "ตั้งแคมป์ 101: เครื่องหนัง" },
        objective = { "167:156759770:1583253567", "คุยกับ Nadyia Maneweaver บนถนนจาก Dolanaar ไป Darnassus เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "45:1200778187:1735425090 C 245:815205661:284337473", "เจ้าเป็นช่างหนังแล้ว ดีมาก {class} ข้าว่ารู้จักคนสอนทำเต็นท์ให้เย็นในวันร้อนและแห้งในวันฝนได้\n\nมีเต็นท์ดีคลุมหัว ก็มั่นใจได้ว่าจะพักเต็มที่พอให้ตื่นตัวระหว่างเดินทาง" },
        completion = { "470:577898743:1109976944", "เรียบร้อย เต็นท์แคมป์ของเจ้าเอง คนส่วนใหญ่ไม่ชอบให้กางเต็นท์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้สิ ข้าสอนเจ้าได้" },
        steps = { { "37:614229450:1985955440", "เพิ่มทักษะการทำเครื่องหนังให้ถึง 20" } },
    },
    [97948] = { -- Camping 101: Mining
        title = { "19:2134334844:1251681605", "ตั้งแคมป์ 101: ขุดแร่" },
        objective = { "143:796575387:1074931074", "คุยกับ Kurdram Stonehammer ใน Auberdine เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "361:1382345230:1652658988", "ขุดแร่อาจไม่เลิศหรู แต่เป็นงานสุจริตดีและวิชาชีพที่น่าศึกษา\n\nข้ารู้จักคนสอนสร้าง Lodestone สำหรับแคมป์ได้ ตั้งแล้วทุกคนที่อยากเหวี่ยงดาบคงมารวมรอบไฟ รับแรงฮึดเสริมฝีมือสู้จากมัน" },
        completion = { "488:837518116:1487918719", "เรียบร้อย ทีนี้เจ้าก็ทำ Lodestone ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "29:1326993482:1796014523", "เพิ่มทักษะการขุดแร่ให้ถึง 20" } },
    },
    [97949] = { -- Camping 101: Skinning
        title = { "21:877856129:1615425789", "ตั้งแคมป์ 101: ถลกหนัง" },
        objective = { "168:214449707:1446638440", "คุยกับ Radnaal Maneweaver บนถนนจาก Dolanaar ไป Darnassus เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "499:1267848069:485795793", "การเก็บหนังจากสัตว์ที่ล้มอย่างชำนาญเป็นทักษะมีค่ายิ่งอย่างหนึ่งของนักผจญภัย\n\nข้ารู้จักคนสอนสร้าง Camp Chair ได้ บางครั้งการปลดภาระพักสักหน่อยสำคัญ ใช้หนังที่เก็บมาทำเก้าอี้นุ่มนั่ง ผ่อนคลายบ้างจะช่วยให้อยู่ในสภาพดีและโจมตีถูกจุดเมื่อมีเรื่องครั้งหน้า" },
        completion = { "489:1841325329:1145743259", "เรียบร้อย ตอนนี้เจ้าสร้าง Camp Chair ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "42:604835422:1713165690", "ถ้าเจ้ามีทักษะนั้น ข้าก็ฝึกให้เจ้าได้" },
        steps = { { "31:830454515:1981975140", "เพิ่มทักษะการถลกหนังให้ถึง 20" } },
    },
    [97950] = { -- Camping 101: Tailoring
        title = { "22:1431642385:2057581804", "ตั้งแคมป์ 101: ตัดเย็บ" },
        objective = { "131:694821365:731631157", "คุยกับ Trianna ใน Darnassus เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "350:1427230788:143007988", "ตัดเย็บเป็นวิชาชีพทรงพลังเกินคาดที่ควรลงทุน ข้ามั่นใจว่าจะช่วยเจ้าได้ดี\n\nข้ารู้จักคนสอนสร้าง Faction Banner สำหรับแคมป์ได้ หากมีทักษะพอ แรงบันดาลใจกับขวัญสำคัญต่อชัยชนะทุกสนามรบ ธงเร้าใจช่วยคงพลังฮึกเหิมได้มาก" },
        completion = { "494:1045707758:1807747544", "เรียบร้อย ทีนี้เจ้าก็ทำ Rallying Banner ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "73:485067858:700703801", "กลับมาคุยกับข้าอีกทีเมื่อเจ้าชำนาญวิชาชีพของเจ้าขึ้นอีกหน่อย" },
        steps = { { "32:2138986334:1672550921", "เพิ่มทักษะการตัดเย็บให้ถึง 20" } },
    },
    [97951] = { -- Camping 101: Alchemy
        title = { "20:915921786:1716389149", "ตั้งแคมป์ 101: เล่นแร่แปรธาตุ" },
        objective = { "133:535982014:1004306699", "คุยกับ Carolai Anise ใน Brill เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "299:410594040:787058671", "เลือกปรุงเครื่องดื่มกับน้ำยาเป็นนักเล่นแร่แปรธาตุหรือ มั่นใจว่ามีประโยชน์ในการเดินทาง\n\nข้ารู้จักคนสอนสร้าง Mana Well สำหรับแคมป์ได้ สร้างแล้วผู้รักษากับผู้ใช้คาถาคงวิ่งมาชิมความสดชื่นกัน" },
        completion = { "488:892105979:1076061495", "เรียบร้อย ตอนนี้เจ้าสร้าง Mana Well ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้สิ ข้าสอนเจ้าได้" },
        steps = { { "30:1831080184:1814656452", "เพิ่มทักษะการเล่นแร่แปรธาตุให้ถึง 20" } },
    },
    [97952] = { -- Camping 101: Blacksmithing
        title = { "26:1221764726:279206460", "ตั้งแคมป์ 101: ตีเหล็ก" },
        objective = { "134:1564975575:1982377344", "คุยกับ Basil Frye ใน Undercity เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "320:202320231:852909869", "เป็นช่างตีเหล็กแล้วหรือ เป็นตัวเลือกดีหากอยากให้คมดาบไม่ทื่อ\n\nข้ารู้จักคนช่วยสอนสร้าง Sharpening Wheel ได้ ตั้งในแคมป์แล้วนักรบกับโจรแถวนั้นคงต่อแถวลับอาวุธกัน" },
        completion = { "495:2117961607:447306361", "เรียบร้อย ตอนนี้เจ้าสร้าง Sharpening Wheel ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        steps = { { "36:482259371:1296802253", "เพิ่มทักษะการตีเหล็กให้ถึง 20" } },
    },
    [97953] = { -- Camping 101: Enchanting
        title = { "23:1713173955:924427762", "ตั้งแคมป์ 101: ลงมนตร์" },
        objective = { "136:699261811:550946143", "คุยกับ Vance Undergloom ใน Brill เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "369:1066151520:1036025452", "ผู้ลงมนตร์ทำทุกสิ่งดีขึ้นและเป็นที่ต้อนรับในทุกแคมป์กลางป่า\n\nข้ารู้จักคนสอนสร้าง Enchanted Lute ได้ ความบันเทิงยามพักสำคัญมาก เวทเล็กน้อยนี้ช่วยให้พร้อมรับความท้าทายสารพัด เมื่อกลับออกสู่ทางฝุ่นอีกครั้ง" },
        completion = { "493:1415932902:592769654", "เรียบร้อย ทีนี้เจ้าก็ทำ Enchanted Lute ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "21:597269750:1281937852", "ได้สิ ข้าสอนเจ้าได้" },
        steps = { { "33:1774593141:15047791", "เพิ่มทักษะการเสริมมนตร์ให้ถึง 20" } },
    },
    [97954] = { -- Camping 101: Engineering
        title = { "24:1086805395:342974848", "ตั้งแคมป์ 101: วิศวกรรม" },
        objective = { "140:1713764447:1213529508", "คุยกับ Graham Van Talen ใน Undercity เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "317:1777421338:1929417440", "วิศวกรเช่นเจ้าประดิษฐ์ชิ้นส่วน หุ่น และระเบิดสารพัดได้ทั้งสนุกและมีกำไร\n\nข้ารู้จักคนสอนสร้าง Reagent Bot สำหรับแคมป์ได้ หุ่นช่วยเหลือนี้ดูแลเสบียงให้พร้อม เพื่อเจ้าและพันธมิตรไม่ขาดวัตถุดิบร่ายคาถา" },
        completion = { "490:66550901:387364094", "เรียบร้อย ทีนี้เจ้าก็สร้าง Reagent Bot ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "34:796380127:1923393619", "เพิ่มทักษะวิศวกรรมให้ถึง 20" } },
    },
    [97955] = { -- Camping 101: First Aid
        title = { "22:1169076296:1627423262", "ตั้งแคมป์ 101: ปฐมพยาบาล" },
        objective = { "131:695529979:1498649499", "คุยกับ Nurse Neela ใน Brill เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "80:1405944155:1276912498 C 213:1979165028:833800773", "เลือกปฐมพยาบาลหรือ? เป็นหนทางน่ายกย่อง... และเหมาะใช้จริงสำหรับ{class}\n\nข้ารู้จักคนสอนสร้าง First Aid Kit สำหรับแคมป์ได้ บาดเจ็บเป็นเรื่องจริงของโลกผจญภัย การมีการรักษาที่จำเป็นในแคมป์อาจช่วยชีวิตด้วยซ้ำ" },
        completion = { "492:1329339879:521834233", "เรียบร้อย ตอนนี้เจ้าสร้าง First Aid Kit ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "67:1070716708:1493071004", "ข้าสอนได้เมื่อเจ้าเพิ่มทักษะวิชาชีพสักหน่อยแล้ว" },
        steps = { { "32:2128258987:594859909", "เพิ่มทักษะการปฐมพยาบาลให้ถึง 20" } },
    },
    [97956] = { -- Camping 101: Fishing
        title = { "20:1026779672:337511730", "ตั้งแคมป์ 101: ตกปลา" },
        objective = { "132:1163769541:806172277", "คุยกับ Clyde Kellen ใน Brill เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "366:2115126721:2001310912", "เจ้าอาจไม่คิดเช่นนั้น แต่ทักษะตกปลามีประโยชน์ในแคมป์จริง ๆ\n\nข้ารู้จักคนสอนสร้าง Fish Bowl ได้ ใช้อุปกรณ์นี้มอบความสุขเล็ก ๆ ให้ตนกับสหายนักผจญภัย คนมีความสุขย่อมเข้มแข็ง ข้ามั่นใจว่าความสามารถสู้จะสะท้อนเช่นนั้น" },
        completion = { "488:1416066424:65558197", "เรียบร้อย ตอนนี้เจ้าสร้าง Fish Bowl ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "61:1928447902:874189049", "ข้าสอนได้เมื่อเจ้าเพิ่มทักษะตกปลาสักหน่อยแล้ว" },
        steps = { { "30:486045795:699998660", "เพิ่มทักษะการตกปลาให้ถึง 20" } },
    },
    [97957] = { -- Camping 101: Herbalism
        title = { "22:398153440:411836651", "ตั้งแคมป์ 101: สมุนไพร" },
        objective = { "126:1927781704:1058719959", "คุยกับ Faruza ใน Brill เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "403:1734578767:1649451813", "ดูเหมือนมีทักษะสมุนไพรแล้ว เก็บดอกไม้ไม่ใช่แค่เดินเอ้อระเหยรู้ไหม มีทั้งประโยชน์... และกำไร\n\nข้ารู้จักคนสอนสร้าง Incense Candle สำหรับแคมป์ได้ ขวัญกำลังใจสูงสำคัญต่อการให้ผู้รักษากับผู้ร่ายคาถาสู้ต่อ เทียนหอมช่วยเสริมสิ่งที่ผู้ใช้เวทต้องชื่นชอบแน่" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        completion = { "493:2089714052:1219300209", "เรียบร้อย ตอนนี้เจ้าสร้าง Incense Candle ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "32:185111467:616084806", "เพิ่มทักษะการเก็บสมุนไพรให้ถึง 20" } },
    },
    [97958] = { -- Camping 101: Leatherworking
        title = { "27:1698130846:1506167115", "ตั้งแคมป์ 101: เครื่องหนัง" },
        objective = { "162:355443477:1855090150", "คุยกับ Shelene Rhobart บนถนนจาก Brill ไป Undercity เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "45:1200778187:1735425090 C 245:815205661:284337473", "เจ้าเป็นช่างหนังแล้ว ดีมาก {class} ข้าว่ารู้จักคนสอนทำเต็นท์ให้เย็นในวันร้อนและแห้งในวันฝนได้\n\nมีเต็นท์ดีคลุมหัว ก็มั่นใจได้ว่าจะพักเต็มที่พอให้ตื่นตัวระหว่างเดินทาง" },
        completion = { "470:577898743:1109976944", "เรียบร้อย เต็นท์แคมป์ของเจ้าเอง คนส่วนใหญ่ไม่ชอบให้กางเต็นท์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "37:614229450:1985955440", "เพิ่มทักษะการทำเครื่องหนังให้ถึง 20" } },
    },
    [97959] = { -- Camping 101: Mining
        title = { "19:2134334844:1251681605", "ตั้งแคมป์ 101: ขุดแร่" },
        objective = { "136:1127936418:450331018", "คุยกับ Brom Killian ใน Undercity เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "361:1382345230:1652658988", "ขุดแร่อาจไม่เลิศหรู แต่เป็นงานสุจริตดีและวิชาชีพที่น่าศึกษา\n\nข้ารู้จักคนสอนสร้าง Lodestone สำหรับแคมป์ได้ ตั้งแล้วทุกคนที่อยากเหวี่ยงดาบคงมารวมรอบไฟ รับแรงฮึดเสริมฝีมือสู้จากมัน" },
        completion = { "488:837518116:1487918719", "เรียบร้อย ตอนนี้เจ้าสร้าง Lodestone ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "27:1589741062:9122832", "เจ้ามาเรียนสินะ?" },
        steps = { { "29:1326993482:1796014523", "เพิ่มทักษะการขุดแร่ให้ถึง 20" } },
    },
    [97960] = { -- Camping 101: Skinning
        title = { "21:877856129:1615425789", "ตั้งแคมป์ 101: ถลกหนัง" },
        objective = { "159:403837320:1605048208", "คุยกับ Rand Rhobart บนถนนจาก Brill ไป Undercity เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "499:1267848069:485795793", "การเก็บหนังจากสัตว์ที่ล้มอย่างชำนาญเป็นทักษะมีค่ายิ่งอย่างหนึ่งของนักผจญภัย\n\nข้ารู้จักคนสอนสร้าง Camp Chair ได้ บางครั้งการปลดภาระพักสักหน่อยสำคัญ ใช้หนังที่เก็บมาทำเก้าอี้นุ่มนั่ง ผ่อนคลายบ้างจะช่วยให้อยู่ในสภาพดีและโจมตีถูกจุดเมื่อมีเรื่องครั้งหน้า" },
        progress = { "24:1867712454:1532779711", "อา ได้ ข้าสอนเจ้าได้" },
        completion = { "489:1841325329:1145743259", "เรียบร้อย ตอนนี้เจ้าสร้าง Camp Chair ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "31:830454515:1981975140", "เพิ่มทักษะการถลกหนังให้ถึง 20" } },
    },
    [97961] = { -- Camping 101: Tailoring
        title = { "22:1431642385:2057581804", "ตั้งแคมป์ 101: ตัดเย็บ" },
        objective = { "163:543027209:582857146", "คุยกับ Bowen Brisboise บนถนนจาก Deathknell ไป Brill เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "350:1427230788:143007988", "ตัดเย็บเป็นวิชาชีพทรงพลังเกินคาดที่ควรลงทุน ข้ามั่นใจว่าจะช่วยเจ้าได้ดี\n\nข้ารู้จักคนสอนสร้าง Faction Banner สำหรับแคมป์ได้ หากมีทักษะพอ แรงบันดาลใจกับขวัญสำคัญต่อชัยชนะทุกสนามรบ ธงเร้าใจช่วยคงพลังฮึกเหิมได้มาก" },
        completion = { "494:1045707758:1807747544", "เรียบร้อย ทีนี้เจ้าก็ทำ Rallying Banner ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "73:485067858:700703801", "กลับมาคุยกับข้าอีกทีเมื่อเจ้าชำนาญวิชาชีพของเจ้าขึ้นอีกหน่อย" },
        steps = { { "32:2138986334:1672550921", "เพิ่มทักษะการตัดเย็บให้ถึง 20" } },
    },
    [97963] = { -- Camping 101: Alchemy
        title = { "20:915921786:1716389149", "ตั้งแคมป์ 101: เล่นแร่แปรธาตุ" },
        objective = { "150:1262649584:387523141", "คุยกับ Nyassa Swiftdraught ใน Shen'dar Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "299:410594040:787058671", "เลือกปรุงเครื่องดื่มกับน้ำยาเป็นนักเล่นแร่แปรธาตุหรือ มั่นใจว่ามีประโยชน์ในการเดินทาง\n\nข้ารู้จักคนสอนสร้าง Mana Well สำหรับแคมป์ได้ สร้างแล้วผู้รักษากับผู้ใช้คาถาคงวิ่งมาชิมความสดชื่นกัน" },
        completion = { "488:892105979:1076061495", "เรียบร้อย ตอนนี้เจ้าสร้าง Mana Well ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        steps = { { "30:1831080184:1814656452", "เพิ่มทักษะการเล่นแร่แปรธาตุให้ถึง 20" } },
    },
    [97964] = { -- Camping 101: Blacksmithing
        title = { "26:1221764726:279206460", "ตั้งแคมป์ 101: ตีเหล็ก" },
        objective = { "148:803714592:773609534", "คุยกับ Aedi Thriceforged ใน Shen'dar Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "320:202320231:852909869", "เป็นช่างตีเหล็กแล้วหรือ เป็นตัวเลือกดีหากอยากให้คมดาบไม่ทื่อ\n\nข้ารู้จักคนช่วยสอนสร้าง Sharpening Wheel ได้ ตั้งในแคมป์แล้วนักรบกับโจรแถวนั้นคงต่อแถวลับอาวุธกัน" },
        completion = { "495:2117961607:447306361", "เรียบร้อย ตอนนี้เจ้าสร้าง Sharpening Wheel ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "42:1537171067:1239081211", "ข้าสอนเจ้าได้ หากเจ้ามีแววทางนี้" },
        steps = { { "36:482259371:1296802253", "เพิ่มทักษะการตีเหล็กให้ถึง 20" } },
    },
    [97965] = { -- Camping 101: First Aid
        title = { "22:1169076296:1627423262", "ตั้งแคมป์ 101: ปฐมพยาบาล" },
        objective = { "149:605796156:888113418", "คุยกับ Naleeia Tattermend ใน Shen'dar Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "80:1405944155:1276912498 C 213:1979165028:833800773", "เลือกปฐมพยาบาลหรือ? เป็นหนทางน่ายกย่อง... และเหมาะใช้จริงสำหรับ{class}\n\nข้ารู้จักคนสอนสร้าง First Aid Kit สำหรับแคมป์ได้ บาดเจ็บเป็นเรื่องจริงของโลกผจญภัย การมีการรักษาที่จำเป็นในแคมป์อาจช่วยชีวิตด้วยซ้ำ" },
        completion = { "492:1329339879:521834233", "เรียบร้อย ตอนนี้เจ้าสร้าง First Aid Kit ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "67:1070716708:1493071004", "ข้าสอนเจ้าได้เมื่อเจ้าฝึกวิชาชีพของเจ้าจนมีทักษะขึ้นมาบ้าง" },
        steps = { { "32:2128258987:594859909", "เพิ่มทักษะการปฐมพยาบาลให้ถึง 20" } },
    },
    [97967] = { -- Camping 101: Fishing
        title = { "20:1026779672:337511730", "ตั้งแคมป์ 101: ตกปลา" },
        objective = { "147:955168375:11009643", "คุยกับ Fenn Fairweather ใน Shen'dar Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "366:2115126721:2001310912", "เจ้าอาจไม่คิดเช่นนั้น แต่ทักษะตกปลามีประโยชน์ในแคมป์จริง ๆ\n\nข้ารู้จักคนสอนสร้าง Fish Bowl ได้ ใช้อุปกรณ์นี้มอบความสุขเล็ก ๆ ให้ตนกับสหายนักผจญภัย คนมีความสุขย่อมเข้มแข็ง ข้ามั่นใจว่าความสามารถสู้จะสะท้อนเช่นนั้น" },
        progress = { "61:1928447902:874189049", "ข้าสอนได้เมื่อเจ้าเพิ่มทักษะตกปลาสักหน่อยแล้ว" },
        completion = { "488:1416066424:65558197", "เรียบร้อย ตอนนี้เจ้าสร้าง Fish Bowl ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        steps = { { "30:486045795:699998660", "เพิ่มทักษะการตกปลาให้ถึง 20" } },
    },
    [97968] = { -- Camping 101: Herbalism
        title = { "22:398153440:411836651", "ตั้งแคมป์ 101: สมุนไพร" },
        objective = { "139:1624210418:2127352713", "คุยกับ Syriel Nightrain ใน Valanaar เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "403:1734578767:1649451813", "ดูเหมือนมีทักษะสมุนไพรแล้ว เก็บดอกไม้ไม่ใช่แค่เดินเอ้อระเหยรู้ไหม มีทั้งประโยชน์... และกำไร\n\nข้ารู้จักคนสอนสร้าง Incense Candle สำหรับแคมป์ได้ ขวัญกำลังใจสูงสำคัญต่อการให้ผู้รักษากับผู้ร่ายคาถาสู้ต่อ เทียนหอมช่วยเสริมสิ่งที่ผู้ใช้เวทต้องชื่นชอบแน่" },
        completion = { "493:2089714052:1219300209", "เรียบร้อย ตอนนี้เจ้าสร้าง Incense Candle ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้สิ ข้าสอนเจ้าได้" },
        steps = { { "32:185111467:616084806", "เพิ่มทักษะการเก็บสมุนไพรให้ถึง 20" } },
    },
    [97969] = { -- Camping 101: Leatherworking
        title = { "27:1698130846:1506167115", "ตั้งแคมป์ 101: เครื่องหนัง" },
        objective = { "145:1844682736:1235843884", "คุยกับ Indari Sunseam ใน Shen'dar Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "45:1200778187:1735425090 C 245:815205661:284337473", "เจ้าเป็นช่างหนังแล้ว ดีมาก {class} ข้าว่ารู้จักคนสอนทำเต็นท์ให้เย็นในวันร้อนและแห้งในวันฝนได้\n\nมีเต็นท์ดีคลุมหัว ก็มั่นใจได้ว่าจะพักเต็มที่พอให้ตื่นตัวระหว่างเดินทาง" },
        completion = { "470:577898743:1109976944", "เรียบร้อย เต็นท์แคมป์ของเจ้าเอง คนส่วนใหญ่ไม่ชอบให้กางเต็นท์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        steps = { { "37:614229450:1985955440", "เพิ่มทักษะการทำเครื่องหนังให้ถึง 20" } },
    },
    [97970] = { -- Camping 101: Mining
        title = { "19:2134334844:1251681605", "ตั้งแคมป์ 101: ขุดแร่" },
        objective = { "148:2012380637:658875139", "คุยกับ Messana Crestwind ใน Shen'dar Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "361:1382345230:1652658988", "ขุดแร่อาจไม่เลิศหรู แต่เป็นงานสุจริตดีและวิชาชีพที่น่าศึกษา\n\nข้ารู้จักคนสอนสร้าง Lodestone สำหรับแคมป์ได้ ตั้งแล้วทุกคนที่อยากเหวี่ยงดาบคงมารวมรอบไฟ รับแรงฮึดเสริมฝีมือสู้จากมัน" },
        completion = { "488:837518116:1487918719", "เรียบร้อย ตอนนี้เจ้าสร้าง Lodestone ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "41:805160450:2099465933", "ข้าฝึกเจ้าได้ หากเจ้ามีแววทางนี้" },
        steps = { { "29:1326993482:1796014523", "เพิ่มทักษะการขุดแร่ให้ถึง 20" } },
    },
    [97971] = { -- Camping 101: Skinning
        title = { "21:877856129:1615425789", "ตั้งแคมป์ 101: ถลกหนัง" },
        objective = { "151:1073164527:2146814533", "คุยกับ Mendalass Tattermend ใน Shen'dar Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "499:1267848069:485795793", "การเก็บหนังจากสัตว์ที่ล้มอย่างชำนาญเป็นทักษะมีค่ายิ่งอย่างหนึ่งของนักผจญภัย\n\nข้ารู้จักคนสอนสร้าง Camp Chair ได้ บางครั้งการปลดภาระพักสักหน่อยสำคัญ ใช้หนังที่เก็บมาทำเก้าอี้นุ่มนั่ง ผ่อนคลายบ้างจะช่วยให้อยู่ในสภาพดีและโจมตีถูกจุดเมื่อมีเรื่องครั้งหน้า" },
        completion = { "489:1841325329:1145743259", "เรียบร้อย ตอนนี้เจ้าสร้าง Camp Chair ของตนได้แล้ว คนส่วนใหญ่ไม่ชอบให้ตั้งแคมป์กลางเมือง หากอยากลองต้องออกไปในป่า\n\nอ้อ จำไว้ ไม่มีแคมป์ใดสมบูรณ์หากไร้กองไฟ ต้องมีไฟก่อนเริ่มตั้งแคมป์ พ่อครัวส่วนใหญ่สอนก่อไฟได้ หากยังไม่รู้ ควรไปหาผู้ฝึกทำอาหารเพื่อเรียนพื้นฐาน" },
        progress = { "5:1287366450:669725923 C 18:1565526108:1219366998", "ได้สิ {class} ข้าสอนเจ้าได้" },
        steps = { { "31:830454515:1981975140", "เพิ่มทักษะการถลกหนังให้ถึง 20" } },
    },
    [97972] = { -- Camping 101: Tailoring
        title = { "22:1431642385:2057581804", "ตั้งแคมป์ 101: ตัดเย็บ" },
        objective = { "151:1160163635:626904950", "คุยกับ Taleen Shimmerthread ใน Shen'dar Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "350:1427230788:143007988", "ตัดเย็บเป็นวิชาชีพทรงพลังเกินคาดที่ควรลงทุน ข้ามั่นใจว่าจะช่วยเจ้าได้ดี\n\nข้ารู้จักคนสอนสร้าง Faction Banner สำหรับแคมป์ได้ หากมีทักษะพอ แรงบันดาลใจกับขวัญสำคัญต่อชัยชนะทุกสนามรบ ธงเร้าใจช่วยคงพลังฮึกเหิมได้มาก" },
        completion = { "494:1045707758:1807747544", "เรียบร้อย ทีนี้เจ้าก็ทำ Rallying Banner ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "73:485067858:700703801", "ไว้ฝึกวิชาชีพของเจ้าจนมีทักษะขึ้นมาบ้างแล้วค่อยมาคุยกับข้าอีกที" },
        steps = { { "32:2138986334:1672550921", "เพิ่มทักษะการตัดเย็บให้ถึง 20" } },
    },
    [97973] = { -- Camping 101: Tailoring
