    [98284] = { -- Camping 101: Enchanting
        title = { "23:1713173955:924427762", "ตั้งแคมป์ 101: ลงมนตร์" },
        objective = { "151:128358311:1965888635", "คุยกับ Nasalanna Windsinger ใน Shen'dar Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "369:1066151520:1036025452", "ผู้ลงมนตร์ทำทุกสิ่งดีขึ้นและเป็นที่ต้อนรับในทุกแคมป์กลางป่า\n\nข้ารู้จักคนสอนสร้าง Enchanted Lute ได้ ความบันเทิงยามพักสำคัญมาก เวทเล็กน้อยนี้ช่วยให้พร้อมรับความท้าทายสารพัด เมื่อกลับออกสู่ทางฝุ่นอีกครั้ง" },
        completion = { "493:1415932902:592769654", "เรียบร้อย ทีนี้เจ้าก็ทำ Enchanted Lute ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        steps = { { "33:1774593141:15047791", "เพิ่มทักษะการเสริมมนตร์ให้ถึง 20" } },
    },
    [98285] = { -- Camping 101: Engineering
        title = { "24:1086805395:342974848", "ตั้งแคมป์ 101: วิศวกรรม" },
        objective = { "150:489973273:462101520", "คุยกับ Strange Hermit ใน Shadowgale Forest เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "317:1103702309:194895978", "วิศวกรมีไหวพริบหาทางเสมอ หากอยู่ในป่าคนเดียว ใช้วิชาชีพได้ย่อมดี แคมป์ดีไม่มีทางสมบูรณ์หากไร้สิ่งสร้างช่วยสักสองสามตัว!\n\nใช่ เมื่อมีประสบการณ์วิศวกรรมสักหน่อย กลับมาหาข้า ข้าจะแสดงวิธีสร้างสิ่งพิเศษ!" },
        completion = { "490:66550901:387364094", "เรียบร้อย ทีนี้เจ้าก็สร้าง Reagent Bot ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "38:1247108789:1655877415", "ทำไปถึงไหนแล้วล่ะ คนแปลกหน้า?" },
        steps = { { "34:796380127:1923393619", "เพิ่มทักษะวิศวกรรมให้ถึง 20" } },
    },
    [98286] = { -- Camping 101: Enchanting
        title = { "23:1713173955:924427762", "ตั้งแคมป์ 101: ลงมนตร์" },
        objective = { "151:128358311:1965888635", "คุยกับ Nasalanna Windsinger ใน Shen'dar Village เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "369:1066151520:1036025452", "ผู้ลงมนตร์ทำทุกสิ่งดีขึ้นและเป็นที่ต้อนรับในทุกแคมป์กลางป่า\n\nข้ารู้จักคนสอนสร้าง Enchanted Lute ได้ ความบันเทิงยามพักสำคัญมาก เวทเล็กน้อยนี้ช่วยให้พร้อมรับความท้าทายสารพัด เมื่อกลับออกสู่ทางฝุ่นอีกครั้ง" },
        completion = { "493:1415932902:592769654", "เรียบร้อย ทีนี้เจ้าก็ทำ Enchanted Lute ของตัวเองได้แล้ว คนส่วนใหญ่ไม่ชอบให้มาตั้งค่ายกลางเมือง ถ้าอยากลองใช้ก็ต้องออกไปในป่า\n\nอ้อ อย่าลืมว่าทุกค่ายต้องมีกองไฟ ต้องก่อไฟก่อนจึงจะตั้งค่ายได้ พ่อครัวส่วนใหญ่สอนวิธีก่อไฟให้เจ้าได้ ถ้ายังไม่เคยเรียน ก็ลองไปหาครูสอนทำอาหารเพื่อเรียนพื้นฐานดู" },
        progress = { "21:597269750:1281937852", "ได้ ข้าสอนเจ้าได้" },
        steps = { { "33:1774593141:15047791", "เพิ่มทักษะการเสริมมนตร์ให้ถึง 20" } },
    },
    [98287] = { -- Camping 101: Engineering
        title = { "24:1086805395:342974848", "ตั้งแคมป์ 101: วิศวกรรม" },
        objective = { "143:1430348233:725135033", "คุยกับ Sprite Jumpsprocket ใน Stormwind เพื่อเรียนสร้างอุปกรณ์แคมป์สำหรับวิชาชีพ เมื่อแสดงความชำนาญในทักษะแล้ว" },
        description = { "317:1777421338:1929417440", "วิศวกรเช่นเจ้าประดิษฐ์ชิ้นส่วน หุ่น และระเบิดสารพัดได้ทั้งสนุกและมีกำไร\n\nข้ารู้จักคนสอนสร้าง Reagent Bot สำหรับแคมป์ได้ หุ่นช่วยเหลือนี้ดูแลเสบียงให้พร้อม เพื่อเจ้าและพันธมิตรไม่ขาดวัตถุดิบร่ายคาถา" },
        steps = { { "34:796380127:1923393619", "เพิ่มทักษะวิศวกรรมให้ถึง 20" } },
    },
    [901] = { -- Samophlange
        title = { "11:290836390:1634051779", "แซโมแฟลนจ์" },
        objective = { "73:1626022295:1347663652", "หา Console Key จาก Tinkerer Sniggles เพื่อนำมาใช้กับแผงควบคุม" },
        description = { "205:392634812:666919762", "เมื่อหยุดการทำงานของเครื่องแล้ว ก็เปิดแผงควบคุมและนำแซโมแฟลนจ์ออกมาได้ อย่างอื่นพร้อมหมดแล้ว เหลือเพียงหากุญแจมาไขแผงควบคุม" },
        progress = { "107:308167121:2140996847", "ไฟบนแผงควบคุมหรี่ลง มาตรวัดและหน้าปัดทั้งหมดอ่านค่าเป็นศูนย์ ทุกอย่างอยู่ในสภาพหยุดรอ" },
        completion = { "145:297455423:927050976", "เมื่อหมุนกุญแจในแม่กุญแจ แผงควบคุมก็ปลดล็อก ไฟสีแดงด้านบนดับลง และพลังงานทั้งหมดในเครื่องปลายทางก็หมดไป" },
        required = { [5089] = { "11:436254748:148639433", "กุญแจแผงควบคุม" } },
        steps = { { "11:436254748:148639433", "กุญแจแผงควบคุม" } },
    },
    [858] = { -- Ignition
        title = { "8:376808089:792931801", "สตาร์ตเครื่อง" },
        objective = { "49:782359578:183324472", "หา Ignition Key แล้วนำไปให้ Wizzlecrank" },
        description = { "502:219736421:1840835406", "Sputtervalve ส่งเจ้ามาหรือเปล่า? ข้ากำลังลำบากเลย กระโดดเข้ามาโดยไม่รู้ว่าต้องใช้กุญแจปลดล็อกชุดควบคุมการเคลื่อนที่ของเครื่องตัดไม้ คนขับเครื่องตัดไม้อีกคนถามว่าทุกอย่างเรียบร้อยไหม ข้าก็ตกใจ! แทนที่จะบอกว่าข้าไม่มีกุญแจ กลับบอกไปว่าเครื่องมีปัญหาทางกลไกอะไรสักอย่าง\n\nเราต้องรีบออกไปจากที่นี่! ขึ้นไปที่ห้องควบคุมบนยอดหอปั้นจั่น หัวหน้าคนงานน่าจะมีกุญแจของเครื่องตัดไม้เครื่องนี้\n\nช่วยข้าที!" },
        progress = { "65:339970321:556647706", "เร็วเข้า เราต้องออกไปก่อนจะมีใครสงสัย!" },
        completion = { "326:1603463309:1290561736", "ใช่ ดูเหมือนจะเป็นกุญแจที่ถูกต้อง ขอข้าแน่ใจก่อนว่าใช้เครื่องนี้เป็น...\n\nอืม... ตัวควบคุมการหมุน... อันนี้ปรับความเร็วและความมั่นคง... ตัวควบคุมการขยับแขนอย่างละเอียด ดูนี่สิ! ไม่น่าเชื่อว่า Venture Company จะออกแบบเครื่องที่ดีกว่าของเราได้ขนาดนี้ ข้าต้องเอามันกลับไป Ratchet!" },
        required = { [5050] = { "12:1860330336:1608648607", "กุญแจสตาร์ตเครื่อง" } },
        steps = { { "12:1860330336:1608648607", "กุญแจสตาร์ตเครื่อง" } },
    },
    [888] = { -- Stolen Booty
        title = { "12:200558781:131999266", "สินค้าที่ถูกปล้น" },
        objective = { "74:1760351157:1667884060", "นำ Shipment of Boots และ Telescopic Lens กลับมาให้ Gazlowe ใน Ratchet" },
        description = { "431:763749166:1494240659", "ถึงข้าจะอยากได้สินค้าคืนทั้งหมด แต่คงเป็นไปไม่ได้ กระนั้นก็ยังมีของบางอย่างที่ข้าต้องได้คืนจริง ๆ!\n\nอย่างที่เห็น หอดูดาวของข้าพร้อมใช้งานแล้ว แต่ยังขาดเลนส์ชิ้นเล็กจากทั้งหมดสองชิ้น เลนส์ชิ้นแรกมากับคาราวานจาก Durotar ส่วนชิ้นที่สองส่งมาทางเรือแล้วก็มาไม่ถึง ข้ายังไม่ได้รองเท้าที่ Drizzlik ใน Booty Bay ส่งมาอีกด้วย!\n\nลงไปที่ค่ายโจรสลัด แล้วดูว่าจะหาของพวกนั้นพบไหม" },
        progress = { "24:122131422:1675462809 N 1:63:63", "เจอของของข้าหรือยัง {name}?" },
        completion = { "67:299601056:1778705257 N 26:862856827:1644893090 R 132:1202968078:1478617273", "ได้ของพวกนี้คืนมาแล้วค่อยโล่งใจ ขอบใจที่ช่วยนะ {name} รู้ไหม ข้ากำลังต้องการคนเผ่า{race}อย่างเจ้ามาช่วยงานที่นี่ ถ้าหางานทำเมื่อไร ก็อย่าลืมว่า Gazlowe จ่ายค่าจ้างงามแค่ไหน!", variants = { { "67:299601056:1778705257 N 166:1597409996:975161701", "ได้ของพวกนี้คืนมาแล้วค่อยโล่งใจ ขอบใจที่ช่วยนะ {name} รู้ไหม ข้ากำลังต้องการคนเผ่าสกายบอร์นอย่างเจ้ามาช่วยงานที่นี่ ถ้าหางานทำเมื่อไร ก็อย่าลืมว่า Gazlowe จ่ายค่าจ้างงามแค่ไหน!" } } },
        required = { [5076] = { "17:2142413011:1883176540", "รองเท้าบูตที่จัดส่งมา" }, [5077] = { "15:1719334524:453790965", "เลนส์กล้องส่องทางไกล" } },
        steps = { { "17:2142413011:1883176540", "รองเท้าบูตที่จัดส่งมา" }, { "15:1719334524:453790965", "เลนส์กล้องส่องทางไกล" } },
    },
    [900] = { -- Samophlange
        title = { "11:290836390:1634051779", "แซโมแฟลนจ์" },
        objective = { "116:1324593371:1186747330", "ปิด Fuel Control Valve, Regulator Valve และ Main Control Valve แล้วกลับไปใช้แผงควบคุมอีกครั้ง" },
        description = { "173:1875313298:1091578840", "วาล์วควบคุมทั้งสามเปิดอยู่ ค่าต่าง ๆ บนแผงควบคุมทำให้เจ้าคาดว่าต้องปิดวาล์วเหล่านี้ก่อน จึงจะปิดเครื่องได้" },
        progress = { "102:2050039951:214074402", "ไฟกะพริบบนแผงควบคุมแสดงว่าวาล์วควบคุมหลักยังไม่ได้ปิด" },
        completion = { "214:985923038:558361881", "ไฟที่แสดงสถานะวาล์วควบคุมทั้งสามหรี่ลงเมื่อวาล์วถูกปิด ไฟสีเขียวค่อย ๆ เปลี่ยนเป็นสีเหลือง ตอนนี้โยกสวิตช์ควบคุมเครื่องได้แล้ว เมื่อปิดวาล์วครบ ก็สามารถปิดเครื่องได้" },
        steps = { { "27:1081593123:1035319617", "ปิดวาล์วควบคุมหลัก" }, { "27:1172014880:956910143", "ปิดวาล์วควบคุมเชื้อเพลิง" }, { "24:464725235:811803970", "ปิดวาล์วปรับแรงดัน" } },
    },
    [96339] = { -- Legacy Reward: Replica Ironforge Air Rifle
        title = { "42:1859339100:1599283721", "รางวัล Legacy: ปืนลม Ironforge จำลอง" },
        completion = { "35:422829074:1888412923 N 2:16223:8285 N 430:349230246:747845860", "เดี๋ยวก่อน เจ้าว่าชื่อ {name} ใช่ไหม?\n\n{name}! ดีใจจริง ๆ ที่ได้พบเจ้าเสียที มีคนเอาพัสดุที่จ่าหน้าถึงเจ้ามาส่งไว้ที่นี่ แล้วรับรองว่าในที่สุดเจ้าจะมารับ ข้าพยายามบอกแล้วว่าที่นี่ไม่รับฝากของแบบนั้น แต่ยังไม่ทันได้พูด เขาก็ไปเสียแล้ว!\n\nเจ้ามาถูกเวลาพอดีด้วย มันเกือบจะถูกรวมกับขยะอื่น ๆ ที่ข้าโยนลงทะเลทุกคืนแล้ว\n\nอะไร? ใคร ๆ ก็ทำกัน โธ่ เอาพัสดุของเจ้าไปแล้วก็ไปเสีย!" },
    },
    [894] = { -- Samophlange
        title = { "11:290836390:1634051779", "แซโมแฟลนจ์" },
        objective = { "64:907927897:2100028307", "เข้าใช้งานแผงควบคุมที่สถานีวิจัยของ Venture Company" },
        description = { "496:586594551:1370516852", "Venture Company ตั้งสถานีวิจัยเล็ก ๆ ไว้ไกลขึ้นไปทางเหนือ ทางตะวันตกเฉียงใต้ของ Sludge Fen ข้าไม่รู้รายละเอียดนักว่าพวกมันทำอะไร แต่สืบมาได้ว่ากำลังทดลองสิ่งที่เรียกว่า \"แซโมแฟลนจ์\"\n\nแล้วแซโมแฟลนจ์มันคืออะไรกันล่ะ? ไม่ว่าจะเป็นอะไร ข้าก็อยากตรวจดู จึงต้องหาคนไปเอามา\n\nข้าได้สำเนาคู่มือใช้งานระบบควบคุมของพวกมันมา เจ้าคงใช้คู่มือนี้หาวิธีถอดแซโมแฟลนจ์ออกได้" },
        completion = { "355:1852126481:432427897", "ปุ่ม คันโยก และไฟกะพริบหลากชนิดเรียงอยู่บนหน้าแผงควบคุมอย่างไม่ค่อยเป็นระเบียบ มาตรวัดเล็ก ๆ แสดงว่าเครื่องกำลังทำงานในระดับที่เหมาะสม และวาล์วควบคุมตัวที่หนึ่งถึงสามเปิดอยู่ มีรูกุญแจเล็ก ๆ อยู่ทางด้านขวาล่างของแผงควบคุม" },
    },
    [9267] = { -- Mending Old Wounds
        title = { "18:954320235:2051511908", "เยียวยาบาดแผลเก่า" },
        progress = { "57:991750050:1484382429 N 302:1159425663:1655296619", "คิดให้ดีก่อนเหยียบเข้ามาใน Ratchet นะ {name}! ข่าวเรื่องเลว ๆ ที่เจ้าทำเริ่มแพร่ไปทั่วแล้ว\n\nแต่เจ้าโชคดี มีเรือเพิ่งมาถึงพร้อมคนบาดเจ็บมากมายจากการปะทะกับ Bloodsail Buccaneers นี่เป็นโอกาสพิสูจน์ว่าเจ้ายังไม่เลวจนหมดทางแก้ ช่วยเราหาผ้าลินินมาทำผ้าพันแผล และขวดเปล่ามาใส่น้ำยาที" },
        completion = { { "48:482305501:745465016 N 82:1868804789:329284776", "48:482305501:745465016 N 80:1835609685:1017010973" }, "ข้าดีใจที่เจ้าเริ่มสำนึกผิดแล้ว {name} ส่งเสบียงมาอีกเรื่อย ๆ ล่ะ พวกเราไม่ลืมเรื่องของเจ้าง่าย ๆ หรอกนะ!" },
        description = { "57:991750050:1484382429 N 302:1159425663:1655296619", "คิดให้ดีก่อนเหยียบเข้ามาใน Ratchet นะ {name}! ข่าวเรื่องเลว ๆ ที่เจ้าทำเริ่มแพร่ไปทั่วแล้ว\n\nแต่เจ้าโชคดี มีเรือเพิ่งมาถึงพร้อมคนบาดเจ็บมากมายจากการปะทะกับ Bloodsail Buccaneers นี่เป็นโอกาสพิสูจน์ว่าเจ้ายังไม่เลวจนหมดทางแก้ ช่วยเราหาผ้าลินินมาทำผ้าพันแผล และขวดเปล่ามาใส่น้ำยาที" },
        required = { [2589] = { "11:1393025601:1453557725", "ผ้าลินิน" }, [3371] = { "10:2101862828:290474430", "ขวดเปล่า" } },
        objectiveLabels = {
            item = { ["Linen Cloth"] = "ผ้าลินิน", ["Empty Vial"] = "ขวดเปล่า" },
        },
    },
    [896] = { -- Miner's Fortune
        title = { "15:804076239:1018102201", "ลาภของคนเหมือง" },
        objective = { "117:851449600:1541737173", "นำ Cats Eye Emerald จาก Venture Co. Overseers หรือ Venture Co. Enforcers คนใดคนหนึ่ง มาให้ Wharfmaster Dizzywig ที่ Ratchet" },
        description = { "483:674435756:850584089", "ในฐานะนายท่าของเมืองท่าที่คึกคักอย่าง Ratchet ข้าติดตามข่าวสารอยู่เสมอ เรื่องการแลกเปลี่ยนสินค้าและเงินระหว่างที่นี่กับ Booty Bay ข้ารู้หมด\n\nข่าวล่าสุดที่ได้ยินมาเกี่ยวกับเหมือง Boulder Lode ของ Venture Company ทางตะวันออกเฉียงเหนือของ Sludge Fen คนเหมืองคนหนึ่งพบมรกตขนาดเท่ากำปั้นเจ้า ข้ารู้จักผู้ซื้ออยู่สองสามคนที่คงสนใจของแบบนั้น และข้ายินดีแบ่งเงินที่ขายได้คนละครึ่ง" },
        progress = { "92:204781743:302776070", "ถ้ารู้ว่าคนเหมืองคนไหนพบมรกต เรื่องนี้ก็คงง่ายเหมือนเดินเล่น..." },
        completion = { "32:553192176:1722504478 N 256:712354552:459586015 N 1:46:46", "ดูขนาดของมันสิ {name}! เราจะรวยแล้ว! ไหนดูซิ จากราคาอัญมณีที่ข้าเห็นส่งเข้า Undermine ข้าน่าจะคำนวณส่วนแบ่งของเจ้าได้... ห้าสิบเปอร์เซ็นต์ ไม่ต้องห่วง!\n\nเอาละ... ข้าว่าประมาณนี้กำลังดี ยินดีที่ได้ค้าขายด้วยนะ {name}" },
        required = { [5097] = { "16:500564779:167742222", "มรกตตาแมว" } },
        steps = { { "16:500564779:167742222", "มรกตตาแมว" } },
    },
    [1069] = { -- Deepmoss Spider Eggs
        title = { "20:1374782477:1579634514", "ไข่แมงมุม Deepmoss" },
        objective = { "52:2029578524:151211637", "นำ Deepmoss Eggs 15 ฟอง ไปให้ Mebok Mizzyrix ใน Ratchet" },
        description = { "455:399147246:1450097205", "ไข่เจียวไข่แมงมุมกำลังเป็นที่นิยมใน Booty Bay! ปัญหาคือ... Booty Bay ไม่มีไข่\n\nข้าได้กลิ่นโอกาสทำเงินแล้ว!\n\nแมงมุม Deepmoss อาศัยอยู่ใน Windshear Crag และ Sishir Canyon ใน Stonetalon Mountains ทางตะวันตกเฉียงเหนือ เอาไข่ของมันมาให้ข้า แล้วข้าจะจ่ายให้อย่างงาม!\n\nที่ Windshear Crag ไข่จะรวมกันเป็นกลุ่มอยู่ใต้ต้นไม้ที่ยังเหลืออยู่\n\nส่วนที่ Sishir Canyon... เอาเถอะ ถ้าเจ้าขวัญอ่อนคลื่นไส้ง่าย เก็บไข่แค่ที่ Windshear Crag ก็น่าจะดีกว่า..." },
        progress = { "22:1902895870:1181094597 N 59:12190972:1258543082", "ได้ไข่มาหรือยัง {name}? ข้าตกลงเรื่องขนส่งกับ Wharfmaster Dizzywig ไว้แล้วนะ!" },
        completion = { "144:189037161:37622420 N 45:2130744959:389262708", "ได้มาแล้ว! ขอบใจ!\n\nข้าจะส่งของพวกนี้ให้ Dizzywig นำลงเรือไป Booty Bay ข้าแทบจะลิ้มรสกำไรได้แล้ว!\n\nนี่ส่วนแบ่งของเจ้า {name} ถ้าไม่มีเจ้า ข้าคงทำข้อตกลงนี้ไม่ได้" },
        required = { [5570] = { "12:2112654447:1387458973", "ไข่ Deepmoss" } },
        steps = { { "12:2112654447:1387458973", "ไข่ Deepmoss" } },
    },
    [79192] = { -- Stepping Stones
        title = { "15:1723530357:1552776422", "เบาะแสทีละก้าว" },
        objective = { "63:1366128655:1883887137", "เจ้าฉีกกระดาษโน้ตออกจากแผ่นไม้ แล้วอ่านลายมือหวัด ๆ บนนั้น" },
        description = { "228:1144082326:51262805", "ข้อความเริ่มว่า \"ภารกิจระบุว่าทั้งคู่กำลังส่งของให้ New Plague แต่ข้าดูแล้วเหมือนอุบัติเหตุธรรมดาในงานปรุงยา ถ้าอยากคุยกันในที่ปลอดภัย ให้มาหามุมสบาย ๆ ของข้าบนภูเขาระหว่าง The Barrens กับ Desolace\"" },
        completion = { "156:2083546555:2110163247", "ทั้งนักผจญภัยที่เดินทางในถิ่นทุรกันดารและทหารรับจ้างคงตั้งค่ายกันที่นี่เป็นประจำ มุมกระดาษโน้ตที่กระพืออยู่ในลมสะดุดตาเจ้า เจ้าจึงเอื้อมมือไปหยิบ" },
    },
    [97005] = { -- Chol'aruk the Ravener
        title = { "21:1835209038:1427392402", "Chol'aruk จอมเขมือบ" },
        objective = { "49:595781706:568613087", "นำ Chol'aruk's Head ไปให้ Bainham ใน Barrens" },
        description = { "505:435332632:503034781", "มีข่าวลือถึงอสุรกายขนาดมหึมาที่ทำรังในถ้ำทางตะวันตกเฉียงเหนือของที่นี่ บนที่ราบสูงที่เรียกว่า Thorn Hill พวก Razormane เรียกมันว่า Chol'aruk หรือ \"จอมเขมือบ\" คนที่เคยเห็นบอกว่ามันใหญ่จนกลืนออร์คได้ทั้งตัว\n\nไม่กี่คนที่เชื่อเรื่องเล่าแบบนั้น แต่ข้าเชื่อ... เพราะข้าเคยสู้กับสิ่งที่คล้ายมันมาแล้ว เพื่อเป็นเกียรติแก่ผู้ที่ข้าสูญเสียให้สัตว์พวกนี้ เจ้าสัตว์ร้ายตัวนี้ต้องตาย\n\nรวบรวมพันธมิตรที่แข็งแกร่งแล้วหารังของ Chol'aruk สังหารอสุรกายตัวนั้น และนำศีรษะมันกลับมาให้ข้า", variants = { { "504:1208842997:1880350553", "มีข่าวลือถึงอสุรกายขนาดมหึมาที่ทำรังในถ้ำทางตะวันตกเฉียงเหนือของที่นี่ บนที่ราบสูงที่เรียกว่า Thorn Hill พวก Razormane เรียกมันว่า Chol'aruk หรือ \"จอมเขมือบ\" คนที่เคยเห็นบอกว่ามันใหญ่จนกลืนออร์คได้ทั้งตัว\n\nไม่กี่คนที่เชื่อเรื่องเล่าแบบนั้น แต่ข้าเชื่อ... เพราะข้าเคยสู้กับสิ่งที่คล้ายมันมาแล้ว เพื่อเป็นเกียรติแก่ผู้ที่ข้าสูญเสียให้สัตว์พวกนี้ เจ้าสัตว์ร้ายตัวนี้ต้องตาย\n\nรวบรวมพันธมิตรที่แข็งแกร่งแล้วหารังของ Chol'aruk สังหารอสุรกายตัวนั้น และนำศีรษะมันกลับมาให้ข้า" } } },
        progress = { "349:882877668:1258760856", "เราต้องใช้กำลังถึงหกคนสู้กับสัตว์พวกนี้เพียงตัวเดียว กว่าจะโค่นมันได้ มันก็ฆ่าพวกเราจนเหลือแค่ข้ากับอีกคน\n\nไกลจากดินแดน Alliance ขนาดนี้ ข้าควรปล่อยเรื่องนี้ไว้เสีย พระแสงรู้ดีว่าข้าคงไม่ต้องนอนไม่หลับเพราะพวกทอเรนป่าเถื่อนหรือออร์คอันธพาลไม่กี่คน แต่เกียรติของพี่น้องที่ล้มลงเรียกร้องให้ข้าลงมือ" },
        completion = { "190:736650743:1912823244 N 1:46:46", "คนของข้าที่ตายไปคงได้พักอย่างสงบขึ้นเมื่อรู้ว่าสัตว์ประหลาดพวกนี้หายไปจากโลกอีกตัว เจ้าทำได้ดีมาก สมเป็นผู้ปกป้อง Alliance ที่ซื่อสัตย์และมั่นคง ขอบใจนะ\n\nจงเดินทางอย่างมีเกียรติ {name}", variants = { { "190:949366291:330663726 N 1:46:46", "คนของข้าที่ตายไปคงได้พักอย่างสงบขึ้นเมื่อรู้ว่าสัตว์ประหลาดพวกนี้หายไปจากโลกอีกตัว เจ้าทำได้ดีมาก สมเป็นผู้ปกป้อง Alliance ที่ซื่อสัตย์และมั่นคง ขอบใจนะ\n\nจงเดินทางอย่างมีเกียรติ {name}" } } },
        required = { [276070] = { "16:1345004582:469073051", "ศีรษะของ Chol'aruk" } },
        steps = { { "16:1345004582:469073051", "ศีรษะของ Chol'aruk" } },
    },
    [890] = { -- The Missing Shipment
        title = { "20:2050060340:154891183", "สินค้าสูญหาย" },
        objective = { "47:226156773:2086426260", "นำ Gazlowe's Ledger ไปให้ Wharfmaster Dizzywig" },
        description = { "382:414545401:253727080", "ข้ารอสินค้าล็อตล่าสุดจาก Booty Bay มานานเหลือเกิน! ค่อนข้างแน่ใจว่าถูกพวก Freebooters ขโมยไป แต่เพื่อความชัวร์ เจ้าลงไปถาม Dizzywig แถวท่าเรือทีได้ไหม ว่าสินค้าถูกเก็บเข้าคลังของข้าไปแล้วโดยข้าไม่รู้หรือเปล่า?\n\nนี่ เอาสมุดบัญชีของข้าไปให้ Dizzywig ให้เขาตรวจรายการสินค้าของข้าเทียบกับบันทึกของเขาอีกที" },
        progress = { "32:719148483:1882623819 N 1:63:63", "มีสินค้าจะส่งไปกับเรือลำหน้าหรือ {name}?" },
        completion = { "212:915342233:1761168381", "อ้อ Gazlowe ส่งเจ้ามาสินะ? รอสักครู่ ให้ข้าตรวจบันทึกของตัวเองก่อน จะได้แน่ใจว่าไม่ได้ส่งสินค้าของ Gazlowe ไปผิดที่\n\nพนันได้เลยว่าเขากำลังรอรองเท้าจาก Drizzlek..." },
        required = { [5080] = { "16:1660973458:1906480195", "สมุดบัญชีของ Gazlowe" } },
        steps = { { "16:1660973458:1906480195", "สมุดบัญชีของ Gazlowe" } },
    },
    [96383] = { -- Legacy Reward: Spectral Bear Cub
        title = { "32:1362750299:1553990591", "รางวัล Legacy: ลูกหมีวิญญาณ" },
        completion = { "14:1961400442:804514564 N 469:1335341319:245972715", "อา {name} ผู้ยิ่งใหญ่กลับมาแล้ว เป็นอย่างที่ข้าคิดไว้เลย\nทำไม Wiley เจ้าของโรงเตี๊ยมธรรมดา ๆ อย่างข้าถึงรู้ว่าจะมีนักผจญภัยคนนี้มา? ก็เพราะคนที่แอบปลื้มเจ้ายังไม่เปลี่ยนที่อยู่จัดส่งให้น่ะสิ!\nไม่ ๆ ไม่ต้องพูดอะไรหรอก ใคร ๆ ก็ยุ่ง ข้าเข้าใจ แค่ไปบอกให้เขาจัดการให้เรียบร้อยก็พอ ตกลงไหม?\nนี่พัสดุของเจ้า ข้าค่อนข้างมั่นใจว่าสิ่งที่อยู่ในนั้นยังมีชีวิต หรือเคยมีชีวิตนะ? ถึงตอนนี้ข้าไม่สนจะหาคำตอบแล้ว ข้าจะจำไว้ว่ามันทั้งเป็นทั้งตายอยู่พร้อมกันตลอดไป" },
    },
    [895] = { -- WANTED: Baron Longshore
        title = { "23:554981093:2123675304", "ประกาศจับ: Baron Longshore" },
        objective = { "56:1450634617:1809420056", "นำศีรษะของ Baron Longshore ไปให้ Gazlowe ใน Ratchet" },
        description = { "210:405448866:1901330996", "ประกาศจับ!\n\nBaron Longshore กัปตันเรือ Heedless\n\nกัปตัน Longshore แห่ง Gilneas เป็นผู้นำกองเรือของ Southsea Freebooters และเป็นผู้ต้องหาคดีโจรสลัด ซากต้องอยู่ในสภาพที่ระบุตัวได้!\n\n-- Gazlowe" },
        progress = { "91:2025653996:71271088", "มีอะไรหรือ? ให้ข้าช่วยอะไรไหม? สินค้าที่จะส่ง หรืออาจเป็นงานวิศวกรรม?" },
        completion = { "283:91840702:623950633", "อ้อ! งานแบบนั้นเอง รู้ไหม ข้าเคยเห็น Heedless ในทะเลเปิดครั้งหนึ่ง เป็นเรือที่น่ากลัวทีเดียว หรือจะเรียกเรือเล็กดี... พวกลูกเรือเคร่งเรื่องคำเรียกนัก!\n\nอย่างไรก็เถอะ ตอนที่มันแล่นผ่านผืนน้ำเป็นภาพที่น่าดูจริง ๆ ข้าดีใจที่กัปตันชื่อฉาวของมันจะไม่มารังควานเรือข้าอีกแล้ว" },
        required = { [5084] = { "22:69024771:1983359766", "ศีรษะของบารอน Longshore" } },
        steps = { { "22:69024771:1983359766", "ศีรษะของบารอน Longshore" } },
    },
    [892] = { -- The Missing Shipment
        title = { "20:2050060340:154891183", "สินค้าสูญหาย" },
        objective = { "46:515552599:1196768837", "นำ Gazlowe's Ledger กลับไปให้ Gazlowe ใน Ratchet" },
        description = { "41:1857884426:1265723534 N 274:878752765:630494465", "เท่าที่ดูจากบันทึกของข้า ทุกอย่างถูกต้องนะ {name} กลับไปบอก Gazlowe ว่าเขาคงโชคร้ายแล้ว ข้าคงไม่แปลกใจถ้าโจรสลัดเป็นคนฉกของของเขาไป\n\nข้าช่วยอะไรเขาไม่ได้อีกแล้ว อ้อ... แต่บอกเขาด้วยก็ได้ว่าข้ามีของจาก Undermine รอให้เขามารับอยู่ ถ้าเขามีเวลา" },
        progress = { "34:954920690:1158741746", "แล้ว Dizzywig ว่าอย่างไรบ้าง?" },
        completion = { "206:38965045:58770364 N 18:132587924:179698754", "ไม่ได้เรื่องสินะ? ถ้าอย่างนั้นก็คงเป็นฝีมือพวก Freebooters... Dizzywig เป็นคนตรงไปตรงมา ข้ามั่นใจว่าเขาไม่โกงข้าแบบนั้นหรอก ยังไงเขาก็รับค่าจ้างข้าอยู่\n\nดูเหมือนข้าจะมีสินค้าที่ต้องเอาคืนเสียแล้ว {name} เจ้าคิดว่าอย่างไร?" },
        required = { [5080] = { "16:1660973458:1906480195", "สมุดบัญชีของ Gazlowe" } },
        steps = { { "16:1660973458:1906480195", "สมุดบัญชีของ Gazlowe" } },
    },
    [902] = { -- Samophlange
        title = { "11:290836390:1634051779", "แซโมแฟลนจ์" },
        objective = { "50:1615765104:1284858600", "นำ Samophlange กลับไปให้ Sputtervalve ใน Ratchet" },
        description = { "289:202261482:425045499", "เมื่อเปิดหน้าแผงควบคุมออก ก็เห็นสายไฟ ท่อ และชิ้นส่วนกลไกประหลาดพันกันแน่น ส่วนใหญ่ดูเหมือนไม่มีประโยชน์ในการใช้งานเสียด้วยซ้ำ เจ้าปัดพวกมันออกแล้วค้นลึกเข้าไปในแผงควบคุมจนพบแซโมแฟลนจ์ เพียงดึงก็หลุดออกจากตัวเรือน" },
        progress = { "17:894589826:134137161 N 30:835307787:1603255669", "อ้อ กลับมาแล้วหรือ {name}! ได้แซโมแฟลนจ์มาหรือยัง?" },
        completion = { "257:1581672200:1063229940", "นี่มัน... เอ่อ... น่าสนใจ... ใช่ ข้าจะส่งต่อไปยังสำนักงานใหญ่ของ Tinkers' Union ที่ Undermine ข้ามั่นใจว่าหลังจากถอดชิ้นส่วนและศึกษากันอย่างละเอียด พวกเขาคงเข้าใจว่ามันคืออะไร\n\nแต่บางที ข้าอาจขอดูเองก่อนสักหน่อย..." },
        required = { [5054] = { "11:290836390:1634051779", "เครื่อง Samophlange" } },
        steps = { { "11:290836390:1634051779", "เครื่อง Samophlange" } },
    },
    [887] = { -- Southsea Freebooters
        title = { "20:951804169:1588344129", "โจรสลัด Southsea" },
        objective = { "75:952233323:1451714192", "สังหาร Southsea Brigands 12 คน และ Southsea Cannoneers 6 คน ให้ Gazlowe ใน Ratchet" },
        description = { "471:191810299:1909466737", "ข้าอยากให้พลเรือโท Grezzlik ดูแลความปลอดภัยในทะเลให้เรือสินค้าของเราได้ดีกว่านี้จริง ๆ เจ้าชายการค้าทุ่มทองให้กองเรือการค้าไปตั้งเท่าไร แต่ยังมีโจรสลัดวิ่งพล่าน ปล้นเรือข้าแล้วขโมยสินค้าไป เห็นแล้วโมโห!\n\nได้ข่าวว่าพวก Southsea Freebooters ตั้งค่ายอยู่ทางใต้ใกล้ ๆ นี้ พวกมันเป็นหนามยอกอกข้ามานาน ถ้า Grezzlik ไม่จัดการ บางทีเจ้าอาจช่วยข้ากำจัดพวกมันได้" },
        progress = { "184:562674390:425525903", "ข้าไม่อยากคิดด้วยซ้ำว่าถูกโจรสลัดปล้นจนเสียกำไรไปเท่าไร แล้วตอนนี้ยังมาตั้งค่ายหน้าบ้านข้าอีก? ชักจะเกินไปแล้ว Undermine ต้องทำอะไรสักอย่าง" },
        completion = { "275:1908907685:713111562", "ทำได้ดี เจ้าหนู ถ้ามีคนช่วยแบบนี้อีกหน่อย ข้าก็คงมีเรื่องให้ห่วงน้อยลงไปอีกเรื่อง หวังว่าพวกมันจะยอมย้ายไปหากินที่อื่น\n\nระหว่างนี้ ยังมีเรื่องเล็กน้อยคือเอาสินค้าที่พวกมันขโมยไปกลับคืนมา!" },
        objectiveLabels = {
            monster = { ["Southsea Brigand slain"] = "ปราบ โจรปล้นทะเลใต้", ["Southsea Cannoneer slain"] = "ปราบ พลปืนใหญ่ทะเลใต้" },
        },
    },
    [97003] = { -- Chol'aruk the Ravener
        title = { "21:1835209038:1427392402", "Chol'aruk จอมเขมือบ" },
        objective = { "53:1007975468:414599324", "นำศีรษะของ Chol'aruk ไปให้ Gur'ak ใน Barrens" },
        description = { "11:832768296:1518065480 C 478:850628270:265288111 C 1:46:46", "เจ้าตรงนั้น {class} ข้าต้องการความช่วยเหลือ มีข่าวลือถึงสัตว์ร้ายที่ทำรังลึกในถ้ำที่ Thorn Hill ทางตะวันออกเฉียงเหนือของที่นี่ Razormane เรียกมันว่า Chol'aruk หรือ \"จอมเขมือบ\" ว่ากันว่าตัวใหญ่กว่าควิลบอร์ปกติห้าเท่า และกระหายเลือดไม่มีวันอิ่ม\n\nส่วนใหญ่ไม่เชื่อเรื่องเล่า แต่ข้าเชื่อ เพราะเคยสู้กับสิ่งที่คล้ายมันมาก่อน\n\nหารังแล้วฆ่า Chol'aruk นำศีรษะมาให้ข้า แต่ขอเตือน เตรียมตัวให้ดีและอย่าไปคนเดียว\n\nโลหิตและอัสนี {class}" },
        progress = { "288:1126548657:675868959", "ต้องใช้กำลังนักสู้ชำนาญหกคนจึงปราบสิ่งมีชีวิตแบบนี้ได้ แต่ก่อนเราจะล้มมัน มันก็ฆ่าพวกเราไปสี่คนแล้ว\n\nถ้าสัตว์ประหลาดพวกนี้มีมากขึ้น ความเสียหายที่ควิลบอร์ทำต่อแผ่นดินอาจเป็นหายนะ", variants = { { "288:484652711:930318257", "ต้องใช้กำลังนักสู้ชำนาญหกคนจึงปราบสิ่งมีชีวิตแบบนี้ได้ แต่ก่อนเราจะล้มมัน มันก็ฆ่าพวกเราไปสี่คนแล้ว\n\nถ้าสัตว์ประหลาดพวกนี้มีมากขึ้น ความเสียหายที่ควิลบอร์ทำต่อแผ่นดินอาจเป็นหายนะ" } } },
        completion = { "226:240256272:1356122870", "น่าประทับใจ นักผจญภัย เมื่อข้านำหลักฐานน่ากลัวที่ยืนยันการมีอยู่ของอสุรกายพวกนี้กลับ Orgrimmar คงไม่มีใครสงสัยเรื่องเล่าข้าอีก แต่จงมั่นใจว่าเกียรตินี้เป็นของเจ้า ข้าจะประกาศวีรกรรมเจ้าให้ก้อง\n\nLok-tar!", variants = { { "12:893490672:478301359 C 204:1555621516:760759871", "น่าประทับใจ {class} เมื่อข้านำหลักฐานน่ากลัวที่ยืนยันการมีอยู่ของอสุรกายพวกนี้กลับ Orgrimmar คงไม่มีใครสงสัยเรื่องเล่าข้าอีก แต่จงมั่นใจว่าเกียรตินี้เป็นของเจ้า ข้าจะประกาศวีรกรรมเจ้าให้ก้อง\n\nLok-tar!" } } },
        required = { [276070] = { "16:1345004582:469073051", "ศีรษะของ Chol'aruk" } },
        steps = { { "16:1345004582:469073051", "ศีรษะของ Chol'aruk" } },
    },
    [881] = { -- Echeyakee
        title = { "9:1101854426:1637325042", "Echeyakee" },
        objective = { "61:986552514:1105713405", "นำ Echeyakee's Hide ไปให้ Sergra Darkthorn ที่ Crossroads" },
        description = { "489:1169368781:1981757480", "หมอกขาว หรือ Echeyakee ในภาษาทอเรน คือราชาแมวใหญ่แห่งทุ่งหญ้า มันล่าอย่างเงียบเชียบจนกล่าวกันว่าเหมือนหมอกขาวบาง ๆ ลอยติดพื้น และฆ่าเร็วเสียจนเหยื่อไม่มีเวลากลัวหรือเจ็บ\n\nทอเรนกล่าวว่ามันเป็นทั้งความเมตตาและความตาย\n\nเจ้าจะได้รู้ว่าจริงไหม เพราะข้าจะส่งเจ้าออกล่า Echeyakee รังมันอยู่ทางตะวันออกเฉียงเหนือของ Crossroads ท่ามกลางกระดูกโคโดยักษ์\n\nไปเถอะ เป่าเขานี้เมื่อถึงรัง เป่าเขา แล้วมันจะมา" },
        progress = { "28:1448931821:472363370 N 1:46:46", "แมวใหญ่กำลังเรียกหาเจ้า {name}" },
        completion = { "190:334241789:518133396 C 32:413595933:1153946361", "เจ้าปราบ Echeyakee ได้แล้ว แม้วันเวลาการล่าของมันจะสิ้นสุด... แต่จิตวิญญาณมันอยู่กับเจ้า มันจะชี้ให้เจ้าเห็นพลังในความแนบเนียน และเกียรติในความเมตตา\n\nเส้นทางเจ้ายังยาวไกล {class} หวังว่าเจ้าจะก้าวไปอย่างดี" },
        required = { [5100] = { "16:36879098:1758272570", "หนังของ Echeyakee" } },
        steps = { { "16:36879098:1758272570", "หนังของ Echeyakee" } },
    },
    [4921] = { -- Lost in Battle
        title = { "14:82205331:1705948708", "หายไปในศึก" },
        objective = { "61:556094627:831654349", "ตามหาภรรยาของ Mankrik แล้วกลับไปหาเขาใน Crossroads" },
        description = { "404:121086454:1018216393 C 28:511833424:1802879827", "เรารบอยู่ในค่ายทอเรนเล็ก ๆ ตอนถูกแยกจากกัน นางยัน Bristleback ไว้สามตัวด้วยตนเอง แต่กำลังที่เสียเปรียบเริ่มทำให้เราแพ้ ข้าล่อบางตัวออกไป แล้วก็เห็นนางถูกพวกที่มาใหม่รุม ด้วยความโกรธ ข้าหันกลับไปเผชิญศัตรู แต่มันมีมากจนล้มข้าได้ง่ายดาย\n\nข้าตื่นขึ้นมาเห็นดรูอิดทอเรนกำลังรักษาแผล เขาพบข้าบน Gold Road ตอนที่ข้าล้มลง\n\nได้โปรด {class} หาร่องรอยภรรยาข้าที" },
        progress = { "147:1238633598:1604848604", "เจอร่องรอยนางบ้างหรือยัง? ความเจ็บในอกบอกว่าเรื่องเลวร้ายที่สุดเกิดขึ้นแล้ว แต่ข้ายังหวังว่าเจ้าจะพบนางปลอดภัยดี" },
        completion = { "25:2046289485:2136806712 C 1:46:46", "ข้าเข้าใจ ขอบใจ {class}" },
        steps = { { "19:74941210:792185930", "ตามหาภรรยาของ Mankrik" } },
    },
    [855] = { -- Centaur Bracers
        title = { "15:1751191362:299222508", "ปลอกแขนเซนทอร์" },
        objective = { "70:1725628606:442426771", "นำ Centaur Bracers 15 ชิ้น ไปให้ Regthar Deathgate ทางตะวันตกของ Crossroads" },
        description = { "296:1112904057:2086363937", "Kolkar เป็นภัยต่อดินแดนที่ Horde อ้างสิทธิ์ใน Barrens เราต้องลดจำนวนกองกำลังของมัน ข้าจึงมีงานล่าค่าหัวให้เจ้า\n\nเมื่ออยู่ในถิ่น Kolkar จงสังหารนักรบของพวกมันแล้วเก็บปลอกแขนเซนทอร์ กลับมาเมื่อได้กองใหญ่ แล้ว Horde จะตอบแทนเจ้าอย่างงาม" },
        progress = { "23:160415722:466461916 N 1:63:63", "การล่าเป็นอย่างไรบ้าง {name}?" },
        completion = { "70:688118089:87923867 N 152:533781694:415070972", "ทำได้ดี ข้ามั่นใจว่าเจ้าทำให้เซนทอร์ที่รอดหวาดกลัวแล้ว {name} ถ้าพวกมันมีสติ ก็คงสงบลงและหยุดรุกคืบ\n\nแต่ข้าไม่คิดว่าจะเป็นเช่นนั้น น่าเสียดาย\n\nน่าเสียดาย... สำหรับพวกมัน" },
        required = { [5030] = { "15:1751191362:299222508", "ปลอกรัดแขนเซนทอร์" } },
        steps = { { "15:1751191362:299222508", "ปลอกรัดแขนเซนทอร์" } },
    },
    [868] = { -- Egg Hunt
        title = { "8:1769151029:1750949366", "ล่าไข่" },
        objective = { "72:506904136:1920544539", "นำ Silithid Eggs 12 ฟอง พร้อม Digging Claw ไปให้ Korran ที่ Crossroads" },
        description = { "5:140209925:2105781119 N 494:1925853918:614102153", "เฮ้ {name} ข้าถูกส่งมาที่ Crossroads เพื่อเฝ้าดูผืนดินและบันทึกสิ่งที่เกิดขึ้นให้นายของข้าใน Orgrimmar\n\nสิ่งหนึ่งที่ข้าศึกษาคือสิ่งมีชีวิตคล้ายแมลงที่พบทางใต้ใน Field of Giants เรารู้เรื่องพวกมันน้อย ข้าจึงตั้งใจค้นให้มากขึ้น ดูเหมือนมันมีสติปัญญามากกว่าสัตว์ทั่วไป\n\nเอากรงเล็บขุดนี้ไปเก็บไข่จากเนินรังของพวกมัน ระวังด้วย ถ้ารู้ตัว มันจะโจมตีเจ้า" },
        progress = { "35:245347444:1757005314 N 39:1707417995:387131016", "ระวังไข่ที่เก็บมาด้วย {name} ถ้าแตกก็ไม่มีประโยชน์กับข้า" },
        completion = { "15:300361628:547864382 N 58:473722118:456647514", "เจ้าทำให้ข้าพอใจ {name} ได้ทั้งไข่และเครื่องมือคืน ทำได้ดี\n\nส่วนรางวัลของเจ้า..." },
        required = { [5058] = { "12:445287193:61861616", "ไข่ซิลิธิด" }, [5059] = { "12:141708701:2138802043", "กรงเล็บขุดดิน" } },
        steps = { { "12:445287193:61861616", "ไข่ซิลิธิด" } },
        objectiveLabels = {
            item = { ["Digging Claw"] = "กรงเล็บขุดดิน" },
        },
    },
    [845] = { -- The Zhevra
        title = { "10:255634738:943511414", "ซีฟรา" },
        objective = { "86:1238961834:355788588", "สังหาร Zhevra Runners เพื่อรวบรวม Zhevra Hooves 4 ชิ้น ให้ Sergra Darkthorn ใน Crossroads" },
        description = { "365:636709584:951819386", "ถึงซีฟราจะไม่ใช่สัตว์ดุร้ายที่สุดใน Barrens แต่มันก็รับมือยากกว่าเพลนสไตรเดอร์อยู่หน่อย ไม่ต้องห่วง ถึงเวลาข้าจะส่งเจ้าไปล่าเหยื่อที่ใหญ่กว่านี้ แต่ตอนนี้เจ้ายังต้องฝึกฝีมืออีกนิด\n\nล่าซีฟราทางเหนือและใต้ แล้วเก็บกีบของมันมาให้ข้า บางทีครั้งหน้าเราอาจส่งเจ้าไปเจอของที่ยากกว่าเดิม" },
        progress = { "31:1250215956:203110968", "เจ้าฆ่าซีฟราไปกี่ตัวแล้ว?" },
        completion = { "9:1775424254:365803329 N 201:1066575657:1012224772", "ไม่เลว {name} ขาของซีฟราแข็งแรงมาก เตะแรง ๆ ทีเดียวก็ทำให้ทอเรนหงายหลังได้!\n\nดูเหมือนเจ้าจะมีแรงอยู่ไม่น้อยเช่นกัน พร้อมสำหรับความท้าทายจริง ๆ หรือยัง?" },
        required = { [5086] = { "13:1463684254:464604100", "กีบ Zhevra" } },
        steps = { { "13:1463684254:464604100", "กีบ Zhevra" } },
    },
    [857] = { -- The Tear of the Moons
        title = { "21:567666733:747390032", "น้ำตาแห่งจันทรา" },
        objective = { "70:1239125399:1640018815", "Feegly the Exiled ต้องการให้เจ้านำ Tear of the Moons กลับมาให้เขา" },
        description = { "490:1651269041:1278385378", "พลังนั้นเคยเป็นของข้า! อยู่ในมือข้านี่เอง! และข้าจะเอาคืน! เอาคืน ได้ยินไหม!\n\nพวกคนขุดโสโครกพบมัน... ช่างงดงาม พวกเขาเรียกมันว่า Tear of the Moons มันเป็นการค้นพบครั้งยิ่งใหญ่ครั้งแรกของเราที่ Bael Modan\n\nมันควรเป็นของข้า! ของข้า ได้ยินไหม!\n\nนายพล Twinbraid อิจฉาพลังที่มันมอบให้ข้า เขาขังมันไว้ในป้อม บอกว่ามันต้องคำสาป! เจ้าโง่นั่น!\n\nคนอื่นอยากได้มัน จึงต้องหยุดพวกนั้น! เจ้าเลว Twinbraid เลยขับไล่ข้า\n\nตอนนี้ข้าจะเอามันคืน เอาคืน ได้ยินไหม!" },
        progress = { "58:40839028:1475086889", "Tear of the Moons อยู่ไหน? ข้าต้องการเดี๋ยวนี้! ต้องการ ได้ยินไหม!" },
        completion = { "45:1149780903:291090496", "ในที่สุด พลังนั้นก็เป็นของข้าอีกครั้ง! ของข้า ได้ยินไหม!" },
        required = { [5038] = { "17:1287716627:926814805", "หยาดน้ำตาแห่งดวงจันทร์" } },
        steps = { { "17:1287716627:926814805", "หยาดน้ำตาแห่งดวงจันทร์" } },
    },
    [98094] = { -- Scout Support
        title = { "13:584735878:1154200496", "สนับสนุนหน่วยสอดแนม" },
        objective = { "126:1379092091:1355462858", "High Executor Darthalia ต้องการให้เจ้าส่งคำสั่งฉบับปรับปรุงให้ Deathstalker Masoj ทางใต้ของ Tarren Mill นอก Dun Garok", variants = { { "125:1751763324:370993150", "High Executor Darthalia ต้องการให้เจ้าส่งคำสั่งฉบับปรับปรุงให้ Deathstalker Masoj ทางใต้ของ Tarren Mill นอก Dun Garok" } } },
        description = { "392:2014927939:1445473811", "ตอนนี้เราไว้ใจให้เจ้าส่งข้อมูลสำคัญแก่สายลับแนวหน้าได้แล้ว จึงมีงานเพิ่มให้\n\nนำของนี้ไปให้ Deathstalker Masoj ซึ่งอยู่เกือบตรงลงใต้จากเรา เมื่อไปถึงและส่งให้ เขาจะมีงานให้เจ้าทำอีก เขาประจำการบนที่สูงทางเหนือของไร่องุ่นเน่าเหม็นที่เรียกกันว่า Nethander Stead\n\nแผนเข้าควบคุมดินแดนเหล่านี้ของเรายังคืบหน้าอย่างมั่นคง" },
        progress = { "23:2084528440:856421611", "จังหวะเวลาคือทุกสิ่ง..." },
        completion = { "76:584701299:1855153798", "แปลกดี คนหน้าใหม่มาทำงานภาคสนาม\n\nเอาละ ดูสิว่าเจ้ามีอะไรมา" },
        required = { [279394] = { "18:1445206060:1901891774", "คำสั่งของ Darthalia" } },
        steps = { { "18:1445206060:1901891774", "คำสั่งของ Darthalia" } },
    },
    [5045] = { -- Rising Spirit
        title = { "13:1897808231:1482985756", "ปลุกพลังจิตวิญญาณ" },
        progress = { "349:1409526481:1510627772", "นักรบทุกรูปแบบ <พ่นลมทางจมูก> ต้องมีจิตวิญญาณแข็งแกร่ง มันผลักดันให้ทำสิ่งยิ่งใหญ่ได้เมื่อหมดความหวัง Razormane <พ่นลมทางจมูก> รู้เรื่องนี้ดี เราเป็นเผ่าที่ผูกพันกับวิญญาณ ภูมิใจในสายสัมพันธ์กับ Agamaggan มากกว่าฝีมือ <พ่นลมทางจมูก> ในศึกเสียอีก\n\nนำเศษโลหิต 4 ชิ้นมา แล้วข้าจะอวยพรจิตวิญญาณเจ้าเพื่อการรบ <พ่นลมทางจมูก>" },
        completion = { "78:1667819601:499578160 R 76:1998270659:1862809695", "นักรบและ <พ่นลมทางจมูก> ชาแมนผู้ยิ่งใหญ่ที่สุดของเราคงอิจฉาความมุ่งมั่นเจ้า {race}\n\nปราบ Bristleback เพิ่ม จงรู้ว่ามันหยุดเจ้าไม่ได้! <พ่นลมทางจมูก>" },
        description = { "349:1409526481:1510627772", "นักรบทุกรูปแบบ <พ่นลมทางจมูก> ต้องมีจิตวิญญาณแข็งแกร่ง มันผลักดันให้ทำสิ่งยิ่งใหญ่ได้เมื่อหมดความหวัง Razormane <พ่นลมทางจมูก> รู้เรื่องนี้ดี เราเป็นเผ่าที่ผูกพันกับวิญญาณ ภูมิใจในสายสัมพันธ์กับ Agamaggan มากกว่าฝีมือ <พ่นลมทางจมูก> ในศึกเสียอีก\n\nนำเศษโลหิต 4 ชิ้นมา แล้วข้าจะอวยพรจิตวิญญาณเจ้าเพื่อการรบ <พ่นลมทางจมูก>" },
        required = { [5075] = { "11:911674189:766411410", "เศษผลึกโลหิต" } },
        steps = { { "11:911674189:766411410", "เศษผลึกโลหิต" } },
    },
    [851] = { -- Verog the Dervish
        title = { "17:767172608:2032279982", "Verog จอมคลั่ง" },
        objective = { "64:1251674772:1717096895", "นำ Verog's Head ไปให้ Regthar Deathgate ทางตะวันตกของ Crossroads" },
        description = { "464:145144768:891252457", "เซนทอร์ Verog จอมคลั่งเดินทางไปทั่ว Barrens คงหาตัวได้ยาก แต่ฐานของมันอยู่ที่เต็นท์บัญชาการเซนทอร์ใน Stagnant Oasis ทางตะวันออกเฉียงใต้ เราอาจล่อให้มันมาหาเจ้าได้\n\nไปที่ Stagnant Oasis ทางตะวันออกเฉียงใต้ แล้วโจมตีเซนทอร์ใกล้เต็นท์บัญชาการ อันตรายแน่ แต่ถ้าฆ่าได้มากพอ พวกมันน่าจะส่งสัญญาณเตือน แล้ว Verog จะมา\n\nนำศีรษะมันมาให้ข้า ข้าจะวางไว้คู่กับศีรษะของ Barak Kodobane" },
        progress = { "20:82021135:1729491660 N 1:63:63", "เจอ Verog แล้วหรือ {name}?" },
        completion = { "176:99666423:1250655803 N 31:1552056730:1724414750", "ดีมาก เจ้าคงปั่นป่วนพวกเซนทอร์ได้ไม่น้อย ทหารยามของเราเห็นความเคลื่อนไหวแถว Stagnant Oasis ซึ่งคงเป็นฝีมือเจ้า\n\nจงภูมิใจในสิ่งที่ทำเถอะ {name} เจ้ามีความกล้าหาญมาก" },
        required = { [5023] = { "12:356929479:1747001914", "ศีรษะของ Verog" } },
        steps = { { "12:356929479:1747001914", "ศีรษะของ Verog" } },
    },
    [6363] = { -- Tal the Wind Rider Master
        title = { "25:1430761954:393301081", "Tal ผู้ดูแลวินด์ไรเดอร์" },
        objective = { "52:1187472634:947969543", "นำ Ahanu's Leather Goods ไปให้ Tal ใน Thunder Bluff" },
        description = { "373:2047498353:1772110162", "ข้าเตรียมเครื่องหนังให้ Jahan ขายที่ Crossroads แล้ว ช่วยนำไปให้เขาได้ไหม?\n\nถ้าเจ้าเคยไป Crossroads และคุยกับผู้ดูแลวินด์ไรเดอร์ที่นั่นแล้ว ก็ขึ้นวินด์ไรเดอร์ของ Thunder Bluff บินกลับไปหาเขาได้\n\nนำเครื่องหนังไปหา Tal ผู้ดูแลวินด์ไรเดอร์ของเราที่ Thunder Bluff แล้วคุยกับเขาเพื่อจัดการเดินทางไป Crossroads" },
        progress = { "11:927657569:725753248 C 24:44117753:590565424", "สวัสดี {class} มีอะไรให้ข้าช่วย?" },
        completion = { "170:1337825395:1027729969", "ต้องนำของนี่ไป Crossroads หรือ? ไม่มีปัญหา ถ้าเคยไปที่นั่นแล้วคุยกับ Devrak เจ้าก็ขึ้นวินด์ไรเดอร์ของข้ากลับไปหาเขาได้" },
        required = { [16283] = { "21:1061339069:2097447544", "เครื่องหนังของ Ahanu" } },
        steps = { { "21:1061339069:2097447544", "เครื่องหนังของ Ahanu" } },
    },
    [874] = { -- Mahren Skyseer
        title = { "14:1298238696:116624969", "Mahren Skyseer" },
        objective = { "26:627233536:880027246", "พูดคุยกับ Mahren Skyseer" },
        description = { { "397:455236698:1591272404", "397:727585034:812356174" }, "เจ้าล่าสัตว์ร้ายแห่ง Barrens มาแล้ว จิตวิญญาณเจ้าแข็งแกร่ง แต่นักล่าต้องพร้อมเสมอ นักล่าที่แท้จริงติดตามเหยื่อได้ทุกเส้นทาง ภูเขาและหนองน้ำไม่อาจทำให้หวั่นไหว\n\nแม้แต่ทะเลก็เช่นกัน\n\nไปหา Mahren พี่น้องของข้า นางล่าสัตว์น้ำขนาดใหญ่ตามชายฝั่ง และจะสอนให้เจ้ารู้จักพวกมัน\n\nแต่จงระวังระหว่างตามหานาง เพราะชายฝั่ง Barrens อยู่ในมือมนุษย์" },
        completion = { "200:923143403:811430650", "พี่น้องของข้าส่งเจ้ามาสินะ? ถ้าอย่างนั้นเจ้าคงพิสูจน์ตัวต่อเขาแล้ว หากเจ้าได้รับความนับถือจาก Jorn ข้าก็นับถือเจ้าเช่นกัน\n\nพร้อมจะเดินต่อไปบนเส้นทางนักล่าแล้วหรือ?" },
    },
    [5052] = { -- Blood Shards of Agamaggan
        title = { "25:1939954175:979075787", "เศษโลหิตแห่ง Agamaggan" },
        objective = { "145:189067904:201145532", "นำ Blood Shard ไปให้ Mangletooth ใน Camp Taurajo ที่ Barrens\n\nรวบรวม Blood Shards เพิ่ม หากต้องการให้เขาอวยพรด้วยพลังของ Agamaggan" },
        description = { "471:1209863218:1526373315", "นอกจากหนามแล้ว เลือดยังส่งผล <พ่นลมทางจมูก> ต่อผืนดินด้านอื่นด้วย หินสีแดงเลือดผสมอยู่กับแร่อื่น Bristleback ขุดเศษหินเหล่านี้และพกเป็นเครื่องราง <พ่นลมทางจมูก> เสริมพลังรบและเวทมนตร์ <พ่นลมทางจมูก>\n\nข้ารู้ความลับของเวทนั้น\n\nนำเศษโลหิตหนึ่งชิ้นมาให้ Mangletooth เพื่อแสดงว่าเจ้าเข้าใจ หากนำมามาก Mangletooth จะอวยพรด้วยเวทควิลบอร์ เวทของ Agamaggan! <พ่นลมทางจมูก>" },
        progress = { "502:667698458:1381906680", "เผ่าของเรารวมตัวตามพื้นที่หนามทั่ว Barrens <พ่นลมทางจมูก> เพราะเป็นสถานที่ศักดิ์สิทธิ์ แต่ไม่มีที่ไหนศักดิ์สิทธิ์เท่า Razorfen ร่างของ Agamaggan ประกอบเป็น Razorfen ทั้งหมด <พ่นลมทางจมูก> แต่ Downs ได้รับการคุ้มครองเป็นพิเศษ เพราะทางเข้าคือปากอันใหญ่โตของเขา! <พ่นลมทางจมูก> มันจะกลืนคนที่ไม่ภักดีทั้งตัว แล้วคายศพออกมาหลังเคี้ยวจนยับ! <พ่นลมทางจมูก>\n\nAgamaggan ทิ้งร่างไว้คุ้มครองเรา และมอบพลังวิญญาณให้เราปกป้องเขาได้ <พ่นลมทางจมูก>" },
        completion = { "68:547264915:1689320872 R 143:139809172:264375845 R 247:237607718:1359831328", "อ้า เจ้าเข้าใจแล้ว <พ่นลมทางจมูก> คำข้าไม่ได้ผ่านหูเจ้าไปเปล่า ๆ {race} แม้ Mangletooth ถูกขัง แต่ไม่มีกรงใดหยุดพลัง Agamaggan ได้! <พ่นลมทางจมูก>\n\nสัมผัสของเศษหิน ความรู้สึกนั้น... นานเหลือเกินแล้ว {race}\n\nเจ้ารู้ไหมว่าการถูกตัดขาดจากพลังของตนเป็นอย่างไร?\n\nแต่ไว้เล่าคราวหน้า ข้าสัญญาจะให้ข้อมูล สัญญาจะให้พลัง Agamaggan เผ่าพ้องหันหลังให้ Mangletooth บัดนี้ข้าจะปล่อยเจ้าไปจัดการพวกมัน <พ่นลมทางจมูก>", variants = { { "474:1812692711:1041874983", "อ้า เจ้าเข้าใจแล้ว <พ่นลมทางจมูก> คำข้าไม่ได้ผ่านหูเจ้าไปเปล่า ๆ สกายบอร์น แม้ Mangletooth ถูกขัง แต่ไม่มีกรงใดหยุดพลัง Agamaggan ได้! <พ่นลมทางจมูก>\n\nสัมผัสของเศษหิน ความรู้สึกนั้น... นานเหลือเกินแล้ว สกายบอร์น\n\nเจ้ารู้ไหมว่าการถูกตัดขาดจากพลังของตนเป็นอย่างไร?\n\nแต่ไว้เล่าคราวหน้า ข้าสัญญาจะให้ข้อมูล สัญญาจะให้พลัง Agamaggan เผ่าพ้องหันหลังให้ Mangletooth บัดนี้ข้าจะปล่อยเจ้าไปจัดการพวกมัน <พ่นลมทางจมูก>" } } },
        required = { [5075] = { "11:911674189:766411410", "เศษผลึกโลหิต" } },
        steps = { { "11:911674189:766411410", "เศษผลึกโลหิต" } },
    },
    [852] = { -- Hezrul Bloodmark
        title = { "16:1988190378:531556167", "Hezrul Bloodmark" },
        objective = { "65:1997220735:753037286", "นำ Hezrul's Head ไปให้ Regthar Deathgate ทางตะวันตกของ Crossroads" },
        description = { "316:882397889:811578679", "Hezrul Bloodmark เป็นผู้นำเซนทอร์ Kolkar ใน Barrens มันดุร้าย โหดเหี้ยม และเจ้าเล่ห์ การปราบมันจะทำให้ Kolkar ปั่นป่วนและแตกแยก ลดภัยคุกคามต่อเราได้มาก\n\nจงฆ่ามัน แล้วนำศีรษะของ Hezrul มาให้ข้าเช่นเดียวกับ Barak และ Verog\n\nมันนำพวกพ้องจาก Lushwater Oasis ทางใต้" },
        progress = { "20:1850164073:891539496 N 1:63:63", "ปราบ Hezrul แล้วหรือ {name}?" },
        completion = { "15:421406717:488920675 N 152:293915347:1143459568", "ข้าขอชื่นชมเจ้า {name} เซนทอร์พวกนี้ไร้วินัย ควบคุมความโกรธให้เป็นพลังไม่ได้อย่างออร์ค แต่ก็ยังดุร้าย การปราบพวกมันพิสูจน์ความกล้าหาญของเจ้าแล้ว" },
        required = { [5025] = { "13:1176003028:24424132", "ศีรษะของ Hezrul" } },
        steps = { { "13:1176003028:24424132", "ศีรษะของ Hezrul" } },
    },
    [875] = { -- Harpy Lieutenants
        title = { "17:1760820412:1155019087", "หัวหน้าหน่วยฮาร์ปี" },
        objective = { "112:1446332141:23205813", "รวบรวม Harpy Lieutenant Rings 6 วง จาก Witchwing Slayers แล้วนำกลับไปให้ Darsok Swiftdagger ที่ Crossroads" },
        description = { "8:273891991:137031649 N 402:357454438:1033081966 N 82:179292563:33516631", "ฮ่า ๆ {name} กลับมาเอาอีกหรือ? ดี ข้าชอบได้ยินแบบนั้น\n\nครั้งนี้ข้าต้องการให้เจ้าลอบสังหารหัวหน้าหน่วยฮาร์ปีใน Dry Hills มีแต่ Witchwing Slayers ที่เป็นหัวหน้าหน่วย แยกได้จากแหวนที่พวกมันพก พวกมันร้ายกาจและนำลูกน้องส่วนหนึ่งในพื้นที่นั้น กำจัด 6 ตัวได้ก็เป็นการโจมตีที่หนักหน่วงต่อระบอบแม่ผู้ปกครองของมัน\n\nให้แน่ใจว่าพวกมันตายอย่างเจ็บปวดนะ {name} เราอยากให้ฮาร์ปีชั่วพวกนั้นรู้ว่าการหาเรื่อง Horde โง่เขลาเพียงใด" },
        progress = { "111:550180040:1340936468", "ได้ Harpy Lieutenant Rings 6 วงแล้วหรือยัง? ต้องให้พวกมันชดใช้ที่โจมตี Horde อย่างโหดร้าย" },
        completion = { "65:455371595:745104408", "ผลงานยอดเยี่ยม สหาย ข้าคิดว่าเจ้าจะก้าวหน้าไปได้ไกลใน Horde" },
        required = { [5065] = { "21:1878089576:1887498841", "แหวนของนายทหารฮาร์ปี" } },
        steps = { { "21:1878089576:1887498841", "แหวนของนายทหารฮาร์ปี" } },
    },
    [903] = { -- Prowlers of the Barrens
        title = { "23:1553772686:1165735516", "นักย่องล่าแห่ง Barrens" },
        objective = { "86:256800206:494383285", "รวบรวม Prowler Claws 7 ชิ้น จาก Savannah Prowlers ให้ Sergra Darkthorn ใน Crossroads" },
        description = { "261:252870846:690621822 N 72:1644832903:31127030", "ถึงเวลาล่าสิ่งที่กัดได้จริงจังแล้ว พวกนักย่องล่าใน Barrens รับมือยาก แข็งแกร่ง พลิกแพลงเก่ง เจ้าเล่ห์... และอันตรายถึงตาย เจ้าพบมันได้ในหญ้าสูง มีมากทางตะวันตกเฉียงใต้ของ Crossroads\n\nระวังตอนล่าด้วย {name} ไม่เช่นนั้นเจ้าอาจเลิกเป็นผู้ล่า แล้วกลายเป็นเหยื่อแทน" },
        progress = { "20:840754824:1542473493 N 30:1168191029:47810670", "การล่าเป็นอย่างไร {name}? เจอพวกนักย่องล่าแล้วหรือยัง?" },
        completion = { "134:2100444828:1316769300", "อ้า ข้าเห็นว่าเจ้าขยันซุ่มในหญ้าเพื่อล่าพวกนักย่องล่า ถ้าอย่างนั้น คิดว่าถึงเวลาสู้กับยอดนักล่าในหมู่มันหรือยัง?" },
        required = { [5096] = { "13:2104675242:711216906", "กรงเล็บสัตว์นักล่า" } },
        steps = { { "13:2104675242:711216906", "กรงเล็บสัตว์นักล่า" } },
    },
    [884] = { -- Owatanka
        title = { "8:1290111401:1103567054", "Owatanka" },
        objective = { "51:1567086876:1981913708", "นำ Owatanka's Tailspike ไปให้ Jorn ที่ Camp Taurajo" },
        description = { "56:577200652:1338622046", "เมื่อสัมผัสหนามหางของ Owatanka ประกายไฟก็แลบออกมา" },
        progress = { "N 93:1982633646:1795796836", "{name} มีพลังใหม่ซ่อนอยู่ในดวงตาเจ้า! เจ้าได้พบ Owatanka ผู้ทรงพลังแล้วใช่ไหม?" },
        completion = { "274:1705681171:2016229486 N 38:1940028340:1153316239", "ทอเรนเรียกกิ้งก่าสายฟ้า Owatanka ว่า \"สายฟ้าคราม\" เพราะภายในร่างใหญ่นั้นมีความรวดเร็วเกินคาด เล่ากันว่าสายฟ้าผ่ามันเมื่อนานมาแล้ว เมื่อได้รับพลังจากความเกรี้ยวกราดของท้องฟ้า สัตว์ร้ายผู้ยิ่งใหญ่จึงมีพลังไร้ขีดจำกัด\n\nขอให้พลังมันไหลผ่านเจ้า {name} เพราะบัดนี้เจ้าก้าวทัน Owatanka แล้ว" },
        required = { [5102] = { "20:513330590:1922547112", "หนามหางของ Owatanka" } },
        steps = { { "20:513330590:1922547112", "หนามหางของ Owatanka" } },
    },
    [846] = { -- Revenge of Gann
        title = { "15:1908176202:1258581590", "การล้างแค้นของ Gann" },
        objective = { "121:379812296:2128194212", "Gann Stonespire ต้องการ Nitroglycerin 6 ขวด, Wood Pulp 6 มัด และ Sodium Nitrate 6 ตัวอย่าง" },
        description = { "503:1886608274:1527101002", "เห็นชัดว่านักสำรวจอาศัยระเบิดกับยานพาหนะเสียงดังพวกนั้นฉีกพื้นดิน อีกไม่นานคงมีหัวหน้าคนงานคนใหม่มารับช่วง\n\nข้าอยากให้คนแคระเจอดีบ้าง แผนงานนี้บอกว่าหากรวมไนโตรกลีเซอรีนกับเยื่อไม้และโซเดียมไนเตรต เราจะทำระเบิดได้ เป็นที่รู้กันว่าพลปืน ทหาร และนายทหารในป้อมมีของเหล่านี้\n\nเก็บของพวกนี้มาให้ข้า ข้าจะทำระเบิดที่คนแคระจะไม่มีวันลืม!" },
        progress = { "20:168162824:875123572 N 410:686411694:1174109324", "กลับมาแล้วสินะ {name}\n\nความตายของ Khazgorm อาจทำให้การขุดแผ่นดินบรรพชนของข้าช้าลงบ้าง แต่ไม่มีทางยุติการทำลายได้ทั้งหมด\n\nป้อมที่ Bael Modan เป็นภัยทางทหารมากขึ้นทุกที เดิมสร้างไว้ป้องกันแหล่งขุดค้น บัดนี้พร้อมใช้เป็นฐานรุกด้วย\n\nถ้าเจ้ามีส่วนผสมที่ข้าขอ ข้าจะทำระเบิดให้คนแคระหุนหันพวกนั้นต้องคิดใหม่เรื่องสิ่งที่ทำใน Barrens" },
        completion = { "33:952156438:1039937284 C 67:1524924647:1401825778", "ข้าเห็นแล้วว่าเจ้าขยันทีเดียว {class}\n\nอีกไม่นานเราคงมีของขวัญที่เหมาะสมให้คนแคระพวกนั้นแน่นอน" },
        required = { [5017] = { "13:1317310326:1317971042", "ไนโตรกลีเซอริน" }, [5018] = { "9:544258874:1373972601", "เยื่อไม้" }, [5019] = { "14:686362835:1451946638", "โซเดียมไนเตรต" } },
        steps = { { "13:1317310326:1317971042", "ไนโตรกลีเซอริน" }, { "9:544258874:1373972601", "เยื่อไม้" }, { "14:686362835:1451946638", "โซเดียมไนเตรต" } },
    },
    [876] = { -- Serena Bloodfeather
        title = { "19:2145230144:116950590", "Serena Bloodfeather" },
        objective = { "85:1284132624:1110109264", "สังหาร Serena Bloodfeather แล้วนำศีรษะกลับไปให้ Darsok Swiftdagger ที่ Crossroads" },
        description = { "446:832322875:2058828898", "เจ้าจัดการหัวหน้าหน่วยกับลูกน้องได้ดีมาก ข้าอยากให้ช่วยอีกอย่างเป็นอย่างสุดท้าย\n\nSerena Bloodfeather เป็นพี่น้องร่วมสายเลือดกับฮาร์ปีหญิงชื่อ Bloodfeather ที่ถูก Rexxar ฆ่าไปนานพอสมควรแล้ว ดูเหมือนการโจมตีคาราวาน Horde เหล่านี้จะเป็นการแก้แค้นให้นาง\n\nข้าต้องการให้เจ้าเชือดคอ Serena แล้วนำศีรษะกลับมา ข้าจะเอาขึ้นคาราวานขบวนต่อไปที่เราส่งออก... ให้พวกฮาร์ปีมีอะไรไว้คิดบ้าง" },
        progress = { "54:1476497437:1292335288", "เจ้าจะไม่ได้อะไรจนกว่าข้าจะเห็นศีรษะ Serena" },
        completion = { "15:2147106355:521977897 N 201:674212836:1662788545", "ฮ่า! ทำได้ดี {name}! ดีจริง ๆ... ข้าไม่แน่ใจว่าเจ้าจะทำไหว แต่เจ้าพิสูจน์แล้วว่าเชือดได้ไม่ไว้หน้า ขอบใจอีกครั้งที่ช่วยปราบภัยฮาร์ปี นี่รางวัล ใช้ให้ดีล่ะ" },
        required = { [5067] = { "13:1612969422:2042955030", "ศีรษะของ Serena" } },
        steps = { { "13:1612969422:2042955030", "ศีรษะของ Serena" } },
    },
    [883] = { -- Lakota'mani
        title = { "11:474004328:21790434", "Lakota'mani" },
        objective = { "54:660445596:1570383528", "นำ Hoof of Lakota'mani ไปให้ Jorn ที่ Camp Taurajo" },
        description = { "70:1973967957:546510660", "กีบของ Lakota'mani เป็นสัญลักษณ์แห่งพลังของโคโดผู้ยิ่งใหญ่" },
        progress = { "N 114:860538728:258183054", "{name} ตอนเจ้าเดินมา ข้าเห็นพลังใหม่ในย่างก้าว บอกข้าที จิตวิญญาณเจ้าได้พบ Lakota'mani ผู้ยิ่งใหญ่แล้วหรือ?" },
        completion = { "208:1627719648:903717238 N 25:1139307972:929362731", "Lakota'mani ในภาษาเราเรียกว่า \"ผู้สะเทือนแผ่นดิน\" ย่างก้าวของมันดุจเสียงฟ้าร้องรวมกำลัง บัดนี้มันอยู่กับเจ้า ความกล้ามันผสานกับความกล้าของเจ้า เมื่อรวมกัน ไม่มีการต่อสู้ใดที่เจ้าจะเผชิญไม่ได้\n\nเดินอย่างสง่าผ่าเผย {name} เดินอย่างสง่าผ่าเผย ผู้สะเทือนแผ่นดิน" },
        required = { [5099] = { "19:1550874803:1514815953", "กีบของ Lakota'mani" } },
        steps = { { "19:1550874803:1514815953", "กีบของ Lakota'mani" } },
    },
    [4021] = { -- Counterattack!
        title = { "14:1735970224:2125358430", "ตีโต้!" },
        objective = { "80:515977896:1638378707", "นำ Piece of Krom'zar's Banner ไปให้ Regthar Deathgate ทางตะวันตกของ Crossroads" },
        description = { "497:489766435:1139211918 N 1:46:46", "Horde ชื่นชมชัยชนะของเจ้าเหนือ Kolkar แต่พวก Kolkar เองเดือดดาล ข้าได้รายงานว่ากองกำลัง Kolkar เดินทางจากบ้านเกิดที่ Desolace มายัง Barrens เพื่อแก้แค้น รายงานล่าสุดบอกว่าขณะนี้พวกมันกำลังเคลื่อนจากตะวันตกเข้าโจมตีบังเกอร์เหล่านี้!\n\nเผชิญผู้รุกราน Kolkar แล้วยุติภัยใน Barrens ฆ่าพวกมันจนผู้นำ Warlord Krom'zar ปรากฏ ปราบเขาแล้วนำชิ้นส่วนธงมาเป็นหลักฐาน\n\nเราฝากความหวังไว้กับเจ้า {name}" },
        progress = { "23:1998130053:729827953", "ได้ธงมาหรือยัง?" },
        completion = { "106:489860124:510182940 N 52:1990381548:253817866", "เจ้าทำได้! ปราบ Kolkar ได้แล้ว!\n\nข้าจะให้แน่ใจว่า Thrall ได้ข่าววีรกรรมของเจ้าที่นี่ {name}\n\nจงยืนอย่างสง่า เจ้าทำให้ทั้งตนเองและ Horde ภูมิใจ" },
        required = { [11227] = { "26:901527665:1649304480", "เศษธงของ Krom'zar" } },
        steps = { { "26:901527665:1649304480", "เศษธงของ Krom'zar" } },
    },
    [98093] = { -- Field to Clear
        title = { "14:1801987463:968285252", "เปิดทางในทุ่ง" },
        objective = { "142:1384714495:597327505", "Sulhasa ใน Barrens ตอนใต้ ต้องการให้เจ้ากำจัดกิ้งก่า Stormhide 7 ตัว และ Hecklefang Stalkers 7 ตัว ในบริเวณนั้น เพื่อให้นางลงจากต้นไม้ได้อย่างปลอดภัย", amount = { "51:674401775:1996715493 W1 23:642418840:1054220762 W2 66:1250138880:703512869", "Sulhasa ใน Barrens ตอนใต้ ต้องการให้เจ้ากำจัดกิ้งก่า Stormhide {world1} ตัว และ Hecklefang Stalkers {world2} ตัว ในบริเวณนั้น เพื่อให้นางลงจากต้นไม้ได้อย่างปลอดภัย" } },
        description = { "444:1770506197:1272114117", "ดีใจจริง ๆ ที่เจ้ามองเห็นข้า!\n\nเช้านี้อากาศดี ข้าจึงเดินจาก Camp Taurajo ลงมาตาม Gold Road แต่พอจะกลับก็กลับไม่ได้ ฝูงไฮยีนาเริ่มล้อม และกิ้งก่า Stormhide ขวางทางหนีเดียวของข้า\n\nข้าเลยตะกายขึ้นต้นไม้นี้ ตอนนี้มีศัตรูมากเกินกว่าจะวิ่งข้ามทุ่งกลับบ้านได้\n\nช่วยกำจัด Stormhide กับ Hecklefang Stalkers ให้ข้าทีได้ไหม?" },
        completion = { "30:1334465027:252766739 N 239:1808722765:1029647983", "ขอบใจที่ช่วยข้า {name} ข้าจะบอกที่ Camp Taurajo ว่าเจ้าเป็นคนช่วยข้าไว้ โชคดีจริง ๆ ที่เจ้ามาช่วย ไม่อย่างนั้นข้าคงติดอยู่บนนั้นทั้งวัน!\n\nข้ามีของแบ่งให้ได้เท่านี้ แต่หวังว่าจะเป็นประโยชน์กับเจ้า\n\nข้าจะกลับออกไปเมื่อค่อย ๆ ปีนลงมาอย่างระมัดระวัง" },
        progress = { "68:1049072286:670314813", "อีกเดี๋ยวข้าอาจมีจังหวะปีนลงไปโดยพวกมันไม่ทันสังเกต..." },
        objectiveLabels = {
            monster = { ["Hecklefang Stalker slain"] = "ปราบ นักย่องตาม Hecklefang", ["Stormhide slain"] = "ปราบ Stormhide" },
        },
    },
    [6386] = { -- Return to the Crossroads.
        title = { "25:528440262:50788859", "กลับสู่ Crossroads", variants = { { "24:478346335:1475758133", "กลับสู่ Crossroads" } } },
        objective = { "124:1822470171:1617132131", "จ่ายค่าโดยสารวินด์ไรเดอร์ไป Crossroads ให้ Doras ผู้ดูแลวินด์ไรเดอร์ แล้วนำ Gryshka's Letter ไปให้ Zargh ที่ Crossroads" },
        description = { "389:41962529:2144575258", "วินด์ไรเดอร์ของข้าฝึกให้บินไปหลายแห่ง ตราบใดที่เจ้าเคยไปและคุยกับผู้ดูแลวินด์ไรเดอร์ที่นั่นแล้ว\n\nเจ้าเคยไป Crossroads และคุยกับ Devrak แล้ว ตอนนี้จึงบินตรงจากที่นี่ไปหาเขาได้ เมื่อถึง Crossroads ก็นำจดหมาย Gryshka ไปส่ง Zargh ได้\n\nคุยกับข้าเมื่อพร้อมไป" },
        progress = { "71:1716449464:1605453309", "กลับจาก Orgrimmar แล้วหรือ? Gryshka ชอบเนื้อที่ข้าส่งไปไหม?" },
        completion = { "101:806108902:1192082373 N 124:1662608675:691923845", "ฮ่า! ข้าว่านางชอบนะ! ไม่มีอะไรทำให้แก้มสาวแดงได้เท่าสเต๊กชิ้นใหญ่ฉ่ำ ๆ!\n\nขอบใจ {name} เจ้าช่วยข้าได้มาก นี่เงินตอบแทนที่ลำบาก และอย่าแปลกใจถ้าข้าเชิญเจ้าไปงานแต่ง!" },
        required = { [16307] = { "16:551568314:533917572", "จดหมายของ Gryshka" } },
        steps = { { "16:551568314:533917572", "จดหมายของ Gryshka" } },
    },
    [6384] = { -- Ride to Orgrimmar
        title = { "17:516096675:449323118", "บินสู่ Orgrimmar" },
        objective = { "114:782479544:1778664859", "จ่ายค่าโดยสารวินด์ไรเดอร์ไป Orgrimmar ให้ Devrak ผู้ดูแลวินด์ไรเดอร์ แล้วนำ Zargh's Meats ไปให้ Gryshka ใน Orgrimmar" },
        description = { "288:2072762244:105038483", "เพียงไม่กี่เหรียญ ข้าก็ให้วินด์ไรเดอร์พาเจ้าไป Orgrimmar ได้ เมื่อถึงแล้วนำ Zargh's Meats ไปให้ Gryshka โรงเตี๊ยมนางอยู่ใน Valley of Strength ไม่ไกลจาก Skytower ที่วินด์ไรเดอร์ของข้าจะส่งเจ้าลง\n\nคุยกับข้าอีกครั้งเมื่อพร้อมเดินทาง" },
        progress = { "62:750783481:415893467", "มีกลิ่นน่ากิน! เจ้าไม่ได้พกเนื้อดิบมาใช่ไหม?" },
        completion = { "208:1300655821:687855214", "โอ้ เยี่ยมเลย! เนื้อส่วนดีเสียด้วย! จาก Zargh หรือ? ออร์คนั่นรู้จริง ๆ ว่าจะเข้าถึงใจสาวได้อย่างไร...\n\nโอ้ ข้าแทบรอไม่ไหวที่จะทำอาหารแล้ว แต่ต้องไม่สุกเกิน! เนื้อกินแบบสุกน้อยถึงอร่อยที่สุด เจ้าคิดเหมือนกันไหม?" },
        required = { [16306] = { "13:1606492427:705831535", "เนื้อจากร้านของ Zargh" } },
        steps = { { "13:1606492427:705831535", "เนื้อจากร้านของ Zargh" } },
    },
    [95621] = { -- Trouble in the Valley
        title = { "21:327725205:1459100120", "ปัญหาในหุบเขา" },
        objective = { "79:1750775691:852883517", "เดินทางไปยังซากคาราวาน แล้วสืบเพิ่มเติมว่าทำไมชาว Kul Tiras ถึงมาอยู่ที่นี่" },
        description = { "389:1686570476:1286068145", "เช้านี้ข้าเห็นมนุษย์กลุ่มหนึ่งค้นหาอะไรในหุบเขาข้างล่าง ข้าใช้กล้องเล็งปืนดูใกล้ขึ้น จึงเห็นชัดว่าเป็นทหารในเครื่องแต่งกายของ Kul Tiras\n\nหากยอมรับงานจากข้า ให้ไปจุดที่ทหารเหล่านี้ตั้งค่ายใกล้ซากคาราวานทางใต้ ฆ่าคนที่พบ แล้วพยายามสืบว่าทำไมพวกเขามาที่นี่" },
        completion = { "95:2023832458:1264627798", "พวกเขากำลังตามหาทหารหนีทัพสินะ... เอาละ ดูเหมือนในที่สุดอดีตก็ตามข้าทันแล้ว" },
        progress = { "212:2028350387:402421411", "กองเรือที่เหลือของ Daelin Proudmoore ซึ่งยังชูธงของเขา เลวทรามและป่าเถื่อนไม่ต่างจากตัวท่านพลเรือเอกก่อนตาย\n\nข้าไม่รู้ว่าทำไมพวกเขามาไกลจาก Tiragarde ขนาดนี้ แต่คงไม่ใช่เรื่องดี" },
        required = { [270151] = { "17:1062661246:1291605853", "คำสั่งของ Benedict" } },
        steps = { { "33:1543109506:1941977914", "สืบว่าชาว Kul Tiras มาที่นี่ทำไม" } },
        objectiveLabels = {
            item = { ["Benedict's Orders"] = "คำสั่งของ Benedict" },
        },
    },
    [891] = { -- The Guns of Northwatch
        title = { "22:1169815186:1085344964", "ปืนใหญ่แห่ง Northwatch" },
        objective = { "148:408257988:1191437002", "Captain Thalo'thas Brightsun แห่ง Ratchet ต้องการให้เจ้ารวบรวม Theramore Medals 10 ชิ้น และสังหาร Captain Fairmount, Cannoneer Whessan และ Cannoneer Smythe" },
        description = { "459:1211717450:338059402", "กองเรือของข้าสูญเสียเรืออีกลำให้มนุษย์คลั่งหน้าที่แห่ง Northwatch Hold แล้ว!\n\nต้องจัดการพวกเลวนั่น ความหวาดระแวงทำให้มันบ้าคลั่ง พวกอันธพาลประมาท มือไวต่อไกปืน ยิงทุกอย่างที่เห็น\n\nเดินทางลงใต้เลียบ Merchant Coast ไปยังป้อม แล้วเข้าโจมตีกำลังของพวกมัน นำเหรียญตราทหารมาเป็นหลักฐาน และเห็นแก่กองเรือข้า ฆ่า Captain Fairmount กับพลปืนคลั่งหน้าที่ของนางด้วย!" },
        progress = { "253:636595147:242039380", "Captain Fairmount กับพลปืนบัดซบระดมยิงจาก Northwatch Hold จนกองเรือข้าตกอยู่ในภัย ข้าต้องการให้ทหารของนางชดใช้ด้วย เอาเหรียญตราจากศพพวกมันมาให้เต็มมือ แล้วข้าจะรู้ว่าได้แก้แค้นให้พวกลูกเรือรับจ้างปล้นที่ตายไปแล้ว" },
        completion = { "90:2056151927:1800756199 N 71:1679425545:1355982943", "ในที่สุด ปืนใหญ่ของ Alliance ผู้ถือว่าตนชอบธรรมก็เงียบลง เจ้าจะได้รับรางวัลที่ช่วยเหลือ {name}\n\nทีนี้ก็ต้องไปทำงานอันเศร้าสลด คือเก็บกู้ร่างผู้ตาย..." },
        required = { [5078] = { "15:457019477:1439267033", "เหรียญตรา Theramore" } },
        steps = { { "15:457019477:1439267033", "เหรียญตรา Theramore" } },
        objectiveLabels = {
            monster = { ["Captain Fairmount slain"] = "ปราบ กัปตัน Fairmount", ["Cannoneer Whessan slain"] = "ปราบ พลปืนใหญ่ Whessan", ["Cannoneer Smythe slain"] = "ปราบ พลปืนใหญ่ Smythe" },
        },
    },
    [889] = { -- Spirit of the Wind
        title = { "18:116210884:373816767", "วิญญาณแห่งสายลม" },
        progress = { "224:2027158927:2100986824", "นำเศษโลหิต 10 ชิ้นมาให้ Mangletooth แล้วข้าจะอวยพรให้เจ้ารวดเร็วยิ่งนัก เจ้าจะวิ่งเคียงซีฟราจนสายลมอิจฉา\n\nอยู่ได้ไม่นาน แต่ก็น่าจะพอช่วยให้เจ้าเดินทางทั่ว Barrens" },
        completion = { "48:1464575404:1356342187 R 56:524012760:960529825", "ดีแล้ว จงไปโดยมีจิตวิญญาณ Agamaggan นำทาง {race} กลับมาหาข้าหากต้องการเวทมนตร์ของ Agamaggan อีก", variants = { { "112:1154984001:1074717414", "ดีแล้ว จงไปโดยมีจิตวิญญาณ Agamaggan นำทาง สกายบอร์น กลับมาหาข้าหากต้องการเวทมนตร์ของ Agamaggan อีก" } } },
        description = { "224:2027158927:2100986824", "นำเศษโลหิต 10 ชิ้นมาให้ Mangletooth แล้วข้าจะอวยพรให้เจ้ารวดเร็วยิ่งนัก เจ้าจะวิ่งเคียงซีฟราจนสายลมอิจฉา\n\nอยู่ได้ไม่นาน แต่ก็น่าจะพอช่วยให้เจ้าเดินทางทั่ว Barrens" },
        required = { [5075] = { "11:911674189:766411410", "เศษผลึกโลหิต" } },
        steps = { { "11:911674189:766411410", "เศษผลึกโลหิต" } },
    },
    [95508] = { -- Unwelcome Guests
        title = { "16:2099336932:1602943142", "แขกที่ไม่ได้รับเชิญ" },
        objective = { "81:1407734874:368380841", "ช่วยให้ Walton รอดชีวิตจากการเผชิญหน้ากับ Terry Longdrink และนาวิกโยธิน Kul Tiras" },
        description = { "312:159660159:330376811", "ใช่ ข้าเคยอยู่ในกองทัพเรือ Kul Tiras หลังท่านจอมพลเรือเข้ายึด Theramore แล้วเริ่มการรบใน Durotar ข้าก็... \"ไม่เห็นด้วย\" กับวิธีของเขา โดยเฉพาะวิธีที่เกี่ยวกับการประหารพลเรือน\n\nเรื่องยังมีอีก แต่... เดี๋ยวก่อน... นั่นอะไร?\n\nมีคนกลุ่มหนึ่งกำลังขึ้นมาบนสันเขา!" },
        completion = { "204:1481209407:1475844082 C 1:46:46", "ดูเหมือนพวกเราจะรอดกันทุกคน ข้า... รู้อยู่แล้วว่าสักวันเรื่องนั้นจะย้อนกลับมาเล่นงานข้า ข้าเป็นหนี้บุญคุณเจ้าที่ช่วยวันนี้\n\nรับนี่ไปเถอะ ไม่ได้มีค่ามากมาย แต่นี่เป็นอย่างน้อยที่ข้าทำให้เจ้าได้\n\nขอให้เดินทางปลอดภัย {class}", variants = { { "205:167414340:1177469266 C 1:46:46", "ดูเหมือนพวกเราจะรอดกันทุกคน ข้า... รู้อยู่แล้วว่าสักวันเรื่องนั้นจะย้อนกลับมาเล่นงานข้า ข้าเป็นหนี้บุญคุณเจ้าที่ช่วยวันนี้\n\nรับนี่ไปเถอะ ไม่ได้มีค่ามากมาย แต่นี่เป็นอย่างน้อยที่ข้าทำให้เจ้าได้\n\nขอให้เดินทางปลอดภัย {class}" } } },
        steps = { { "13:692268787:1259360238", "ช่วย Walton" } },
    },
    [844] = { -- Plainstrider Menace
        title = { "19:461091131:1250080406", "ภัยจากเพลนสไตรเดอร์" },
        objective = { "83:71258342:938041199", "รวบรวม Plainstrider Beaks 7 ชิ้น แล้วนำกลับไปให้ Sergra Darkthorn ใน Crossroads" },
        description = { "187:1211190369:1393239801", "เหยื่อรายแรกของเจ้าจัดการได้ง่าย\n\nเพลนสไตรเดอร์ทางตะวันออกคอยรบกวนแหล่งเสบียงของเราจนเป็นปัญหา\n\nกำจัดพวกมันแล้วนำจะงอยปากกลับมาให้ข้า" },
        progress = { "42:49275075:865533650", "เก็บจะงอยปากเพลนสไตรเดอร์มาแล้วหรือยัง?" },
        completion = { "11:1776810664:1873330125 N 232:1068510395:1249543873", "ดีมาก {name} เมื่อไม่มีเพลนสไตรเดอร์ เราก็ดูแลเส้นทางลำเลียงเสบียงได้ง่ายขึ้น หวังว่าเจ้าจะได้เรียนรู้กลเม็ดจากการออกไปใน Barrens บ้าง เพราะเหยื่อรายต่อไปดุร้ายกว่าเพลนสไตรเดอร์อีกหน่อย..." },
        required = { [5087] = { "17:131167540:1012356125", "จะงอยปาก Plainstrider" } },
        steps = { { "17:131167540:1012356125", "จะงอยปาก Plainstrider" } },
    },
    [907] = { -- Enraged Thunder Lizards
        title = { "23:467293336:2079673178", "กิ้งก่าสายฟ้าคลุ้มคลั่ง" },
        objective = { "61:126858289:1534933372", "นำ Thunder Lizard Blood 3 ชิ้น ไปให้ Jorn Skyseer ที่ Camp Taurajo" },
        description = { "5:714842399:1747743604 N 373:474349203:1739797984", "เอาละ {name} เจ้าต้องเผชิญกิ้งก่าสายฟ้าใหญ่ พวกมันตัวใหญ่จนพื้นสั่นเมื่อเดินข้ามทุ่ง ระวังตอนสู้ เพราะก้าวพลาดเพียงครั้งเดียว เจ้าอาจไปอยู่ใต้เท้ามัน\n\nเจ้าพบกิ้งก่าสายฟ้าได้ใน Barrens ตอนใต้ พวกมันมีชื่อว่า Stormsnouts, Stormhides และ Thunderheads กลับมาหาข้าเมื่อปราบได้แล้ว" },
        progress = { "34:1530817704:968731262 N 1:63:63", "ปราบกิ้งก่าสายฟ้าแล้วหรือ {name}?" },
        completion = { "117:452523724:1429884267", "ดีที่เห็นเจ้ากลับมาพร้อมหลักฐานแห่งชัยชนะ และดีที่รู้ว่าเจ้าทำได้โดยกระดูกยังไม่หัก" },
        required = { [5143] = { "20:932784950:1948167265", "เลือดกิ้งก่าสายฟ้า" } },
        steps = { { "20:932784950:1948167265", "เลือดกิ้งก่าสายฟ้า" } },
    },
    [871] = { -- Disrupt the Attacks
        title = { "19:1222227587:83676722", "หยุดยั้งการโจมตี" },
        objective = { "119:1420788461:325944445", "สังหาร Water Seekers 8 คน, Thornweavers 8 คน และ Hunters 3 คน ของเผ่า Razormane แล้วกลับไปหา Thork ใน Crossroads" },
        description = { "35:730776721:954193436 N 442:456350758:1247866538", "ควิลบอร์ทุกเผ่าเป็นศัตรูของเรา {name} บางเผ่าก็แค่สร้างปัญหามากกว่าเผ่าอื่น\n\nRazormane โจมตีเส้นทางส่งเสบียงจาก Durotar จนเราปวดหัวไม่จบ ข้าส่งหน่วยสอดแนมไปหาผู้นำการปล้นแล้ว แต่ระหว่างนี้ เจ้าสร้างความเสียหายให้พวกมนุษย์หมูโสโครกได้เท่าไรก็ช่วยเราได้ทั้งนั้น\n\nเริ่มทางตะวันออกเฉียงเหนือไปทาง Durotar สังเกตเถาหนามมหึมาที่งอกจากพื้น ก็รู้ว่ารังของมันอยู่ไหน หาให้พบแล้วสังหารพวกมัน" },
        progress = { "118:1748795066:2139143674", "ยิ่งหยุดการโจมตีได้ช้าเท่าไร การส่งเสบียงให้ชาว Crossroads ก็ยิ่งยากขึ้นเท่านั้น" },
        completion = { "20:1921578502:569519135 N 95:817070546:422601413", "ทำได้ดี {name} ในที่สุดควิลบอร์อวดดีพวกนั้นก็จะได้รู้ว่าอำนาจของ Horde เป็นสิ่งที่มองข้ามไม่ได้" },
        objectiveLabels = {
            monster = { ["Razormane Water Seeker slain"] = "ปราบ นักหาน้ำ Razormane", ["Razormane Thornweaver slain"] = "ปราบ ผู้ถักหนาม Razormane", ["Razormane Hunter slain"] = "ปราบ นายพราน Razormane" },
        },
    },
    [95507] = { -- Vrang's Game
        title = { "12:1111125153:1425183812", "สัตว์ในกับดักของ Vrang" },
        objective = { "71:2042108715:1245609691", "รวบรวม Trapped Game 8 ตัว จากกับดักที่พบใน Sprung Traps ใน Barrens" },
        description = { "290:29338394:1649129682", "ระหว่างออกไปข้างนอก ถ้าเจ้าช่วยตรวจดูกับดักของข้าก็คงช่วยได้มาก ข้าวางกระจายไว้ทั่วหุบเขา\n\nนำสัตว์เล็กที่ข้าดักได้กลับมา ระวังสัตว์ป่าอื่นด้วย แถวนี้อันตรายถ้าไม่คอยดูให้ดี" },
        completion = { "24:699096832:1500611632 C 103:860056216:477581355", "ขอบใจที่ช่วย {class} ข้าเริ่มสงสัยแล้วว่าคืนนี้ต้องเข้านอนทั้งหิวเพราะแผลบัดซบที่ขานี่หรือเปล่า" },
        progress = { "38:388905457:1097958945", "<Vrang ส่งเสียงฮึ่มใส่เมื่อเจ้าเดินเข้าใกล้>" },
        required = { [269719] = { "12:1688535756:930231212", "สัตว์ที่ติดกับดัก" } },
        steps = { { "12:1688535756:930231212", "สัตว์ที่ติดกับดัก" } },
    },
    [893] = { -- Weapons of Choice
        title = { "17:1411695957:31912643", "อาวุธที่ต้องการ" },
        objective = { "139:1599991071:282956282", "นำ Razormane Backstabber, Charred Razormane Wand และ Razormane War Shield ไปให้ Tatternack Steelforge ที่ Camp Taurajo ใน Barrens" },
        description = { "471:1253164264:187957379", "ได้ยินว่าควิลบอร์ Razormane ทางใต้เลย Field of Giants ไม่มีช่างตีเหล็กชำนาญ แต่ดูเหมือนเริ่มทำอาวุธแข็งแรงขึ้นแล้ว ถ้าเป็นไปได้ ข้าอยากได้มาหลายชนิดเพื่อศึกษาเทคนิค\n\nถ้าเจ้าอยากช่วยนำเกียรติมาสู่ Horde ก็นำตัวอย่างอาวุธพวกมันมาให้ข้า หากริชจากพวก Stalkers ไม้กายสิทธิ์จากพวก Seers และโล่จากพวก Warfrenzy เท่านี้ก็น่าจะดี!" },
        progress = { "274:646850243:260950752", "ข้าเองก็สงสัยว่าควิลบอร์น่าสมเพชจะมีฝีมือเรื่องตีเหล็กได้สักแค่ไหน แต่ข้าทำตามคำสั่งจอมทัพ และจะเรียนรู้เรื่องเผ่า Razormane เท่าที่ทำได้\n\nข้าเคยทำงานต่ำต้อยกว่านี้มาแล้ว และยินดีทำหากมันช่วยชาวออร์ค", variants = { { "263:1580780504:218901635 R 8:304949674:1830260986", "ข้าเองก็สงสัยว่าควิลบอร์น่าสมเพชจะมีฝีมือเรื่องตีเหล็กได้สักแค่ไหน แต่ข้าทำตามคำสั่งจอมทัพ และจะเรียนรู้เรื่องเผ่า Razormane เท่าที่ทำได้\n\nข้าเคยทำงานต่ำต้อยกว่านี้มาแล้ว และยินดีทำหากมันช่วยชาว{race}" } } },
        completion = { "97:1670571297:1744998985 C 176:1854711764:1801677163", "เยี่ยม ตัวอย่างยอดเยี่ยมจริง ๆ\n\nควิลบอร์ก้าวหน้าไปไกลกว่าที่ข้าคิด\n\nนี่ {class} รับไปแล้วหลีกทางข้า ข้าควรตรวจอาวุธเหล่านี้ให้ละเอียด เราอาจประเมินศัตรูต่ำไป และเราไม่มีทางยอมให้เกิดความผิดพลาดแบบนั้นได้" },
        required = { [5093] = { "21:70868811:231285433", "มีดลอบแทงของ Razormane" }, [5092] = { "22:315428860:130881659", "ไม้กายสิทธิ์ Razormane ที่ไหม้เกรียม" }, [5094] = { "20:1858626530:997451258", "โล่ศึก Razormane" } },
        steps = { { "21:70868811:231285433", "มีดลอบแทงของ Razormane" }, { "22:315428860:130881659", "ไม้กายสิทธิ์ Razormane ที่ไหม้เกรียม" }, { "20:1858626530:997451258", "โล่ศึก Razormane" } },
    },
    [95495] = { -- The Hermit Tanner
        title = { "17:86624349:1535299248", "ช่างฟอกหนังผู้สันโดษ" },
        objective = { "94:755787376:538854494", "นำ Bundle of Hides ไปให้ผู้สันโดษบนสันเขาที่มองลงมาเห็น Dry Hills ใน Barrens" },
        description = { "408:670240551:191672194", "หนังพวกนี้ต้องส่งให้ช่างฟอกหนังที่ข้าค้าขายด้วยบ่อย ๆ เขาเป็นคนสันโดษ อยู่ลำพังบนยอดสันเขาด้านหลังข้า ตอนนี้ข้าปีนเนินชันได้ไม่ง่าย จึงจะเป็นหนี้บุญคุณหากเจ้าช่วยนำไปส่ง\n\nอ้อ เรื่อง... รูปร่างหน้าตาของช่างฟอกหนัง อย่าตกใจ แม้ดูแบบนั้น แต่เขาไม่เป็นภัย ข้าสาบานว่าเป็นความจริง" },
        progress = { "63:1205107494:1874262637", "สวัสดี นักผจญภัย วันนี้มีอะไรทำให้ขึ้นมาถึงที่ของข้าหรือ?", variants = { { "11:927657569:725753248 C 42:1549684120:1588414533", "สวัสดี {class} วันนี้มีอะไรทำให้ขึ้นมาถึงที่ของข้าหรือ?" } } },
        completion = { "191:2045264560:2038103241", "Vrang ส่งเจ้ามาสินะ? ดีแล้ว ขอบใจที่นำหนังพวกนี้มาส่ง น่าเสียดายที่ Vrang มาเองไม่ได้ ข้ามีเรื่องอยากคุยกับเขา" },
        required = { [269718] = { "15:261702089:1909027423", "มัดหนังสัตว์" } },
        steps = { { "15:261702089:1909027423", "มัดหนังสัตว์" } },
    },
    [6365] = { -- Meats to Orgrimmar
        title = { "18:1920863167:322590107", "ส่งเนื้อไป Orgrimmar" },
        objective = { "48:676039111:718567177", "นำ Zargh's Meats ไปให้ Devrak ใน Crossroads" },
        description = { "305:452280923:1924824044", "ข้ามีเนื้อส่วนดี ๆ อยากส่งให้สหาย นางชื่อ Gryshka เป็นเจ้าของโรงเตี๊ยมใน Orgrimmar เจ้าช่วยนำไปส่งแทนข้าได้ไหม?\n\nทางเร็วที่สุดไป Orgrimmar คือวินด์ไรเดอร์ นำเนื้อไปให้ Devrak ผู้ดูแลวินด์ไรเดอร์ที่ Crossroads แล้วคุยกับเขาเรื่องเดินทางไป Orgrimmar" },
        progress = { "69:2024970404:1696923560", "ต้องรีบไปไหนหรือ? ถ้าอย่างนั้นก็คุยถูกออร์คแล้ว!" },
        completion = { "110:850944664:1734263165", "ต้องนำเนื้อนี้ไป Orgrimmar หรือ? ไม่มีปัญหา จ่ายค่าธรรมเนียมเล็กน้อย วินด์ไรเดอร์ของข้าก็พาไปได้" },
        required = { [16306] = { "13:1606492427:705831535", "เนื้อจากร้านของ Zargh" } },
        steps = { { "13:1606492427:705831535", "เนื้อจากร้านของ Zargh" } },
    },
    [848] = { -- Fungal Spores
        title = { "13:258341441:419300390", "สปอร์เห็ดรา" },
        objective = { "62:860828362:419296772", "นำ Fungal Spores 4 ชิ้น ไปให้ Apothecary Helbrim ที่ Crossroads" },
        description = { "339:696466877:1596020963", "โอเอซิสแห่ง Barrens ซ่อนความลับไว้ พลังชีวิตไหลออกจากผืนน้ำ เติมกำลังให้พืชและสัตว์ที่ดื่มมัน\n\nทั้งเติมกำลัง และเปลี่ยนแปลงพวกมัน\n\nมีเห็ดชนิดหนึ่งขึ้นใกล้โอเอซิสเหล่านี้ สปอร์ของมันมีคุณสมบัติที่พวกเรานักปรุงยาแห่ง Lordaeron ใช้ประโยชน์ได้\n\nนำสปอร์มาให้ข้า แล้วเจ้าจะได้รับความขอบคุณจากเรา" },
        progress = { "24:1318972712:244584736 N 98:759246593:1617174397", "ได้สปอร์มาหรือยัง {name}? ข้าต้องส่งน้ำยาตำรับหนึ่งให้เพื่อนร่วมงานใน Thunder Bluff ซึ่งต้องใช้สปอร์พวกนั้น..." },
        completion = { "107:308987146:313455460 N 1:46:46", "อ้า ใช่ ตัวอย่างพวกนี้ดี มีฤทธิ์แรง\n\nข้าคือฟอร์เซเคน และพวกเรารักษาสัญญา นี่รางวัลของเจ้า {name}" },
        required = { [5012] = { "13:258341441:419300390", "สปอร์เห็ด" } },
        steps = { { "13:258341441:419300390", "สปอร์เห็ด" } },
    },
    [5044] = { -- Wisdom of Agamaggan
        title = { "19:1277774460:1886683715", "ปัญญาแห่ง Agamaggan" },
        progress = { "138:1555539150:1275123243 R 142:1301429187:363719895", "ชาแมนและนักเวทปฐพีแห่งเผ่าควิลบอร์ <พ่นลมทางจมูก> เรียกพลังของ Agamaggan มาช่วยทั้งต่อสู้และประกอบพิธี {race}\n\nหากเจ้าก็อยากให้พรของ Agamaggan เสริมพลังเวทมนตร์ นำเศษโลหิต 4 ชิ้นมา แล้ว Mangletooth จะช่วยเจ้า <พ่นลมทางจมูก>" },
        completion = { "40:1720070559:1472607311 R 118:1543934674:1477420790", "ศัตรูควรกลัวเจ้ายิ่งขึ้นอีก {race} <พ่นลมทางจมูก>\n\nเมื่อพบกันครั้งหน้า จงเล่าเล่ห์กลที่ใช้ในการต่อสู้ให้ Mangletooth ฟัง ไม่ว่าจะในชาตินี้หรือชาติหน้า <พ่นลมทางจมูก>" },
        description = { "138:1555539150:1275123243 R 142:1301429187:363719895", "ชาแมนและนักเวทปฐพีแห่งเผ่าควิลบอร์ <พ่นลมทางจมูก> เรียกพลังของ Agamaggan มาช่วยทั้งต่อสู้และประกอบพิธี {race}\n\nหากเจ้าก็อยากให้พรของ Agamaggan เสริมพลังเวทมนตร์ นำเศษโลหิต 4 ชิ้นมา แล้ว Mangletooth จะช่วยเจ้า <พ่นลมทางจมูก>" },
        required = { [5075] = { "11:911674189:766411410", "เศษผลึกโลหิต" } },
        steps = { { "11:911674189:766411410", "เศษผลึกโลหิต" } },
    },
    [872] = { -- The Disruption Ends
        title = { "19:641878718:10416793", "ยุติการก่อกวน" },
        objective = { "140:1852254114:1893926106", "สังหาร Razormane Geomancers 8 คน, Razormane Defenders 8 คน และ Kreenig Snarlsnout\n\nจากนั้นนำ Kreenig Snarlsnout's Tusk ไปให้ Thork ที่ Crossroads" },
        description = { "64:1616975400:137991900 N 418:620519251:721034518", "หน่วยสอดแนมคนหนึ่งเห็นการโจมตีคาราวานจาก Durotar {name} คนร้ายคือควิลบอร์เผ่า Razormane จริง ๆ มีตัวหนึ่งเป็นผู้นำการปล้น ชื่อ Kreenig Snarlsnout มีคนเห็นมันทางตะวันออกเฉียงเหนือ ใต้ถนนจาก Durotar ลงมาเล็กน้อย ถ้าจะยุติภัยนี้ Kreenig ต้องตาย\n\nแต่เพื่อให้แน่ใจว่าการโจมตีจะหยุด ข้าว่าต้องซ้ำเติมให้หนัก ฆ่า Kreenig กับพวกในเผ่ามันอีก แล้วนำงามันกลับมาหาข้า" },
        progress = { "52:130448111:1285855197 N 145:1123806671:2111427378", "ตัดหัวผู้นำ แล้วความวุ่นวายจะตามมา {name} จำบทเรียนนี้ไว้ให้ดี มันจะช่วยเจ้าในอนาคต\n\nเมื่อไร้ผู้นำ พวกหมูนั่นจะสะเปะสะปะ แล้วเราจะทวง Barrens กลับคืนได้" },
        completion = { "11:534428891:784080240 N 141:1948479764:2141694263", "ทำได้ดี {name} เมื่อ Kreenig ตาย การโจมตีคาราวานของเราต้องลดลงแน่\n\nเผ่าพันธุ์ของเจ้าควรภูมิใจที่มีเจ้าเป็นสมาชิก" },
        required = { [5063] = { "25:1992039096:1956788602", "งาของ Kreenig Snarlsnout" } },
        steps = { { "25:1992039096:1956788602", "งาของ Kreenig Snarlsnout" } },
        objectiveLabels = {
            monster = { ["Razormane Geomancer slain"] = "ปราบ ผู้ใช้เวทปฐพี Razormane", ["Razormane Defender slain"] = "ปราบ ผู้พิทักษ์ Razormane" },
        },
    },
    [879] = { -- Betrayal from Within
        title = { "20:958511388:1642172495", "การทรยศจากพวกเดียวกัน" },
        objective = { "100:224282051:1579830034", "สังหาร Nak, Kuz และ Lok Orcbane แล้วนำกะโหลกไปให้ Mangletooth ที่ Camp Taurajo ใน Barrens" },
        description = { "77:1074548949:1864716726 R 391:1998151704:1950413458 R 27:1609551187:999170462", "สามคนจากเผ่าข้าออกจาก Kraul มานำการปล้น Horde {race} <พ่นลมทางจมูก> พวกมันโหดเหี้ยมและเจ้าเล่ห์ ถ้าเจ้าปราบได้ Crossroads และ Barrens ส่วนใหญ่ก็จะรู้จักความสงบ... <พ่นลมทางจมูก> อย่างน้อยจากเผ่า Razormane <พ่นลมทางจมูก>\n\nNak, Kuz และ Lok Orcbane คือคนที่เจ้าต้องหา พวกมันอยู่ไกลไปทางใต้ของ Barrens คนหนึ่งร่ายเวท อีกคนแกะรอย และผู้นำที่ชื่อ Orcbane <พ่นลมทางจมูก> เป็นนักรบ ฆ่าพวกมันเสีย {race} เหมือนที่พวกมันฆ่าข้า", variants = { { "511:638490504:1271828484", "สามคนจากเผ่าข้าออกจาก Kraul มานำการปล้น Horde สกายบอร์น <พ่นลมทางจมูก> พวกมันโหดเหี้ยมและเจ้าเล่ห์ ถ้าเจ้าปราบได้ Crossroads และ Barrens ส่วนใหญ่ก็จะรู้จักความสงบ... <พ่นลมทางจมูก> อย่างน้อยจากเผ่า Razormane <พ่นลมทางจมูก>\n\nNak, Kuz และ Lok Orcbane คือคนที่เจ้าต้องหา พวกมันอยู่ไกลไปทางใต้ของ Barrens คนหนึ่งร่ายเวท อีกคนแกะรอย และผู้นำที่ชื่อ Orcbane <พ่นลมทางจมูก> เป็นนักรบ ฆ่าพวกมันเสีย สกายบอร์น เหมือนที่พวกมันฆ่าข้า" } } },
        progress = { "20:840754824:1542473493 R 264:80088077:1384775041", "การล่าไปถึงไหนแล้ว {race}? <พ่นลมทางจมูก>\n\nThork คิดว่ารู้ความจริงว่าใครนำการปล้นเผ่าพ้องของเขา <พ่นลมทางจมูก> แต่ถ้าเจ้าสำเร็จ เขาจะได้รู้ว่าตัวเองผิดเพียงใด\n\nข้าหนีความตายไม่พ้น แต่เจ้าทำให้ศัตรูข้าเจ็บหนักแล้ว Mangletooth จึงไม่เสียใจอะไร <พ่นลมทางจมูก>", variants = { { "292:514049372:2026444597", "การล่าไปถึงไหนแล้ว Skyborne? <พ่นลมทางจมูก>\n\nThork คิดว่ารู้ความจริงว่าใครนำการปล้นเผ่าพ้องของเขา <พ่นลมทางจมูก> แต่ถ้าเจ้าสำเร็จ เขาจะได้รู้ว่าตัวเองผิดเพียงใด\n\nข้าหนีความตายไม่พ้น แต่เจ้าทำให้ศัตรูข้าเจ็บหนักแล้ว Mangletooth จึงไม่เสียใจอะไร <พ่นลมทางจมูก>" } } },
        completion = { "253:1893803356:839037355 R 1:46:46", "จบแล้วสินะ จบแบบนี้ดีกว่า Mangletooth ว่าอย่างนั้น <พ่นลมทางจมูก> พวกมันควร <พ่นลมทางจมูก> ให้แน่ใจว่าข้าตายตอนหันหลังให้ แทนที่จะทิ้ง <พ่นลมทางจมูก> ข้าไว้ในกรงอัปมงคลนี่\n\nเหลืองานให้เจ้าทำอีกเพียงอย่างเดียว {race}", variants = { { "262:1734408917:1009615431", "จบแล้วสินะ จบแบบนี้ดีกว่า Mangletooth ว่าอย่างนั้น <พ่นลมทางจมูก> พวกมันควร <พ่นลมทางจมูก> ให้แน่ใจว่าข้าตายตอนหันหลังให้ แทนที่จะทิ้ง <พ่นลมทางจมูก> ข้าไว้ในกรงอัปมงคลนี่\n\nเหลืองานให้เจ้าทำอีกเพียงอย่างเดียว Skyborne" } } },
        required = { [5074] = { "11:1274381020:581376845", "กะโหลกของ Kuz" }, [5073] = { "11:209923260:619951988", "กะโหลกของ Nak" }, [5072] = { "11:1275814371:117742035", "กะโหลกของ Lok" } },
        steps = { { "11:1274381020:581376845", "กะโหลกของ Kuz" }, { "11:209923260:619951988", "กะโหลกของ Nak" }, { "11:1275814371:117742035", "กะโหลกของ Lok" } },
    },
    [905] = { -- The Angry Scytheclaws
        title = { "21:2082328226:1730383313", "Scytheclaw ผู้เกรี้ยวกราด" },
        objective = { "139:2041428355:1944207572", "สังหารแรปเตอร์ Sunscale แล้วเก็บขนของมัน นำขนไปใช้กับรัง Scytheclaw ทั้ง 3 แห่ง แล้วกลับไปหา Sergra Darkthorn ใน Crossroads" },
        description = { "5:714842399:1747743604 N 289:233873572:15306593", "เอาละ {name} การล่ากำลังลึกซึ้งขึ้น เจ้าต้องปราบเหยื่อแล้วตามไปถึงรังของมัน\n\nล่าแรปเตอร์ Sunscale ทางใต้ ฆ่าแล้วถอนขนที่พวกมันมี นำขนไปวางในรัง Scytheclaw ทางตะวันตกเฉียงใต้ของ Stagnant Oasis แสดงให้พวกเดียวกับมันเห็นว่าเจ้าไม่กลัว!" },
        progress = { "28:1666813238:415668088 N 1:63:63", "ไปถึงรังแล้วหรือ {name}?" },
        completion = { "164:922317561:1638605687 N 99:520623918:1785430340", "เจ้าไปรังแล้ววางขนของเหยื่อไว้ข้างในสินะ ต้องใช้ความกล้ามากทีเดียว ไม่ต้องสงสัยเลย\n\nรู้สึกแข็งแกร่งขึ้นบ้างไหม {name}? เพราะเจ้าดูแกร่งกว่าตอนมาที่นี่ครั้งแรก ข้าว่า Barrens กำลังทำหน้าที่ของมันได้ดี" },
        steps = { { "22:1262803183:1862073533", "ไปที่รังแรปเตอร์สีน้ำเงิน" }, { "24:960164694:1668340289", "ไปที่รังแรปเตอร์สีเหลือง" }, { "21:1584225080:774884972", "ไปที่รังแรปเตอร์สีแดง" } },
    },
    [5043] = { -- Agamaggan's Agility
        title = { "19:887456815:1697161927", "ความคล่องแคล่วแห่ง Agamaggan" },
        progress = { "221:849338217:220890284", "กล่าวกันว่าหน่วยสอดแนมชั้นยอดของเผ่าข้าแม่นยำไร้ผู้เทียบ และไม่มีโจรคนไหน <พ่นลมทางจมูก> เร็วเท่าพวกเขาในการต่อสู้\n\nนำเศษโลหิต 4 ชิ้นมา แล้วข้าจะทำให้เจ้าคล่องแคล่วยิ่งกว่าควิลบอร์ใดที่เคยเกิดมา" },
        completion = { "63:716894263:348629194 R 147:578534958:1312721298", "ขอให้เจ้าเล็งไม่พลาด และอาวุธเข้าเป้าหมายอย่างเที่ยงตรง {race}\n\nจิตวิญญาณ Agamaggan อยู่กับเจ้า กลับมา <พ่นลมทางจมูก> หาข้าได้หากต้องการ Mangletooth จะอวยพรอีก หากเทพหมูป่าผู้ยิ่งใหญ่เห็นว่าข้าคู่ควร <พ่นลมทางจมูก>", variants = { { "218:1785076773:1146580033", "ขอให้เจ้าเล็งไม่พลาด และอาวุธเข้าเป้าหมายอย่างเที่ยงตรง สกายบอร์น\n\nจิตวิญญาณ Agamaggan อยู่กับเจ้า กลับมา <พ่นลมทางจมูก> หาข้าได้หากต้องการ Mangletooth จะอวยพรอีก หากเทพหมูป่าผู้ยิ่งใหญ่เห็นว่าข้าคู่ควร <พ่นลมทางจมูก>" } } },
        description = { "221:849338217:220890284", "กล่าวกันว่าหน่วยสอดแนมชั้นยอดของเผ่าข้าแม่นยำไร้ผู้เทียบ และไม่มีโจรคนไหน <พ่นลมทางจมูก> เร็วเท่าพวกเขาในการต่อสู้\n\nนำเศษโลหิต 4 ชิ้นมา แล้วข้าจะทำให้เจ้าคล่องแคล่วยิ่งกว่าควิลบอร์ใดที่เคยเกิดมา" },
        required = { [5075] = { "11:911674189:766411410", "เศษผลึกโลหิต" } },
        steps = { { "11:911674189:766411410", "เศษผลึกโลหิต" } },
    },
    [92706] = { -- WANTED: Bruuz
        title = { "13:651111127:1452522178", "ประกาศจับ: Bruuz" },
        objective = { "47:795409110:1721150087", "นำ Bruuz's Dorsal Fin ไปให้ Gazlowe ใน Ratchet" },
        description = { "240:941946912:565094989", "เรียกนักตกปลาทุกคน!\n\nฉลามยักษ์วนเวียนในน่านน้ำใกล้ท่าเรือสินค้า โจมตีลูกเรือกับเรือเล็ก คนงานท่าเรือตั้งชื่อเล่นให้มันว่า \"Bruuz\" ใครนำครีบมันมาให้ข้า จะได้รับรางวัลงาม!\n\n-- Gazlowe" },
        completion = { "241:63278998:69763036", "ในที่สุดก็มีคนฆ่าเจ้าตัวนั้น! รู้ไหมว่าหาลูกเรือลงน้ำยากแค่ไหน ตอนคนทั้งเมืองร้องว่า \"ฉลาม!\" ตลอดเวลา?\n\nข้าอาจเอาครีบเจ้าสัตว์ประหลาดนั่นไปทำซุปมื้อเย็นเสียเลย จะได้เป็นฝ่ายหัวเราะทีหลัง", variants = { { "240:33561541:1777516318", "ในที่สุดก็มีคนฆ่าเจ้าตัวนั้น! รู้ไหมว่าหาลูกเรือลงน้ำยากแค่ไหน ตอนคนทั้งเมืองร้องว่า \"ฉลาม!\" ตลอดเวลา?\n\nข้าอาจเอาครีบเจ้าสัตว์ประหลาดนั่นไปทำซุปมื้อเย็นเสียเลย จะได้เป็นฝ่ายหัวเราะทีหลัง" } } },
        progress = { "31:1727213491:1740281097", "มีอะไรให้ข้าช่วย สกายบอร์น?", variants = { { "22:512060199:1103807044 R 1:63:63", "มีอะไรให้ข้าช่วย {race}?" } } },
        required = { [253710] = { "18:105671077:534199275", "ครีบหลังของ Bruuz" } },
        steps = { { "18:105671077:534199275", "ครีบหลังของ Bruuz" } },
    },
    [1153] = { -- A New Ore Sample
        title = { "16:895616595:1525038328", "ตัวอย่างแร่ชนิดใหม่" },
        objective = { "134:951902381:1794472128", "หา Unrefined Ore Sample จาก Gravelsnout Digger หรือ Gravelsnout Surveyor แล้วนำไปให้ Tatternack Steelforge ที่ Camp Taurajo ใน Barrens" },
        description = { "C 503:777067851:39551746", "{class} ที่ผ่านมาเจ้าช่วยข้าได้ดี จอมทัพพอใจกับผลงานของข้าจนถึงตอนนี้ และขอให้ข้าทำต่อด้วยความมุ่งมั่นใหม่ เกียรติของข้าบอกว่าต้องให้จอมทัพรับรู้ผลงานทุกอย่างของเจ้าอย่างเหมาะสม แต่ก่อนอื่น ข้าอยากขอให้ช่วยอีกครั้ง\n\nไม่นานมานี้มีนักเดินทางมาจากทางใต้ สถานที่ชื่อ Thousand Needles พวกเขาฆ่าโคโบลด์ที่มีตัวอย่างแร่ประหลาด แต่ไม่ยอมขายให้ข้า ข้าต้องการตัวอย่างแร่นั้นมาตรวจ" },
        progress = { "255:1560159950:501167715", "ข้าเจอนักเดินทางพวกนั้นอีกแล้ว พวกที่ไม่ยอมขายตัวอย่างแร่ให้ ข้าถ่มน้ำลายใส่เพราะมันไม่ช่วยจอมทัพ\n\nขอให้พวกมันตายในสนามรบอย่างคนขี้ขลาด มิใช่นักรบอย่างที่ควรเป็นสิทธิ์ของทุกคนที่ร่วมเป็นพันธมิตรกับ Horde" },
        completion = { "15:986576735:2026148614 N 312:733715874:1259179576 C 1:46:46", "ตัวอย่างที่ดี {name} ดีจริง ๆ\n\nเมื่อเจ้าทำสำเร็จ นักเดินทางพวกนั้นก็เอาแร่ที่พบมาข่มข้าไม่ได้อีกแล้ว\n\nข้าจะเริ่มทำงานทันที ถ้ามันแข็งแรงพอ จะส่งอาวุธที่ทำจากวัสดุนี้กลับไปให้จอมทัพเห็นความสำเร็จของเรา\n\nข้าจะไม่ลืมที่เจ้าช่วย {class}" },
        required = { [5842] = { "20:1574568722:1224740885", "ตัวอย่างแร่ที่ยังไม่ถลุง" } },
        steps = { { "20:1574568722:1224740885", "ตัวอย่างแร่ที่ยังไม่ถลุง" } },
    },
    [867] = { -- Harpy Raiders
        title = { "13:1087054237:2140595180", "ฮาร์ปีจอมปล้น" },
        objective = { "80:1485435429:886092417", "รวบรวม Witchwing talons 8 ชิ้น\n\nนำกลับไปให้ Darsok Swiftdagger ที่ Crossroads" },
        description = { "503:1045277887:881876249", "ฮาร์ปีบัดซบพวกนั้นทำลายเสบียงคาราวานของเรามานานเกินไป ถึงเวลาเชือดคอพวกมันสักหน่อยเพื่อลดจำนวนแล้ว\n\nข้าแอบสำรวจรังและรู้แล้วว่าใครอยู่ใต้คำสั่งใคร การโจมตีที่ได้ผลหนักที่สุดคือตัดสายบัญชาการระดับล่างออกไปให้มาก แล้วค่อยไล่ขึ้นไปถึงยอด\n\nข้าจะให้เจ้าเริ่มเบา ๆ กำจัด Witchwing Harpies และ Witchwing Roguefeathers ทางตะวันตกเฉียงเหนือ แล้วนำกรงเล็บ Witchwing 8 ชิ้นมาให้ข้า น่าจะเป็นจุดเริ่มต้นที่ดี..." },
        progress = { "87:1316097765:200841130", "เชือดพวกมันไปพอหรือยัง? เชือดต่อแล้วเก็บหลักฐานมา ข้าต้องการกรงเล็บ Witchwing 8 ชิ้น" },
        completion = { "43:1469832939:178613140 N 59:1334462434:754212044", "โอ้ ของดีนี่ ดีจริง ๆ... ทำได้ดี {name} ข้ารอดูผลงานของเจ้าอีกในวันหน้า" },
        required = { [5064] = { "15:1512506233:809138757", "กรงเล็บฮาร์ปี Witchwing" } },
        steps = { { "15:1512506233:809138757", "กรงเล็บฮาร์ปี Witchwing" } },
    },
    [885] = { -- Washte Pawne
        title = { "12:697613580:79013581", "Washte Pawne" },
        objective = { "61:838822940:1848132959", "นำ Washte Pawne's Feather ไปให้ Jorn Skyseer ที่ Camp Taurajo" },
        description = { "52:2112233900:1498820639", "ขนนกของ Washte Pawne ทำให้เจ็บเมื่อสัมผัส" },
        progress = { "33:234810077:378557714 N 78:1418094762:170180492", "เจ้ามีความมุ่งมั่นใหม่อยู่ภายใน {name} ความมุ่งมั่นที่เกิดจากความเจ็บปวด...\n\nความตายของ Washte Pawne ถ่วงใจเจ้าอยู่หรือ?" },
        completion = { "480:351762564:1811635719 N 1:46:46", "ธันเดอร์ฮอว์กเป็นสัตว์หายากใน Barrens ความตายของมันอาจเป็นลางแห่งโชคใหญ่หรือหายนะใหญ่\n\nแต่ Washte Pawne ที่ภาษา Taurahe เรียกว่า \"ผู้กัดกินวิญญาณ\" อาจนำมาซึ่งทั้งสองอย่าง... หรือไม่ใช่ทั้งคู่\n\nความเจ็บปวดที่เจ้ารู้สึกจากการล่าผู้กัดกินวิญญาณ คือความปวดร้าวที่ทุกคนได้รับเมื่อได้สิ่งยิ่งใหญ่มาด้วยราคาอันหนักหนา ความแปลบปลาบที่เจ้ารู้สึกคือความเจ็บจากความเสียใจ\n\nแต่ข้าเห็นว่าเจ้าผ่านมันแล้ว เจ้าเรียนรู้ว่าความเสียใจกลายเป็นปัญญา และความเจ็บปวดทำให้แข็งแกร่ง\n\nเจ้าเรียนรู้มามาก {name}" },
        required = { [5103] = { "22:538303960:1472223219", "ขนนกของ Washte Pawne" } },
        steps = { { "22:538303960:1472223219", "ขนนกของ Washte Pawne" } },
    },
    [869] = { -- Raptor Thieves
        title = { "14:592130479:1794062311", "แรปเตอร์จอมขโมย" },
        objective = { "50:1499931531:705777478", "นำ Raptor Heads 12 ชิ้น ไปให้ Gazrog ที่ Crossroads" },
        description = { "452:871014550:1753995942", "ไม่นานมานี้ เงินที่ส่งมาถูกขโมยจากหอทหารยามของเรา มันเป็นเงินค่าจ้างทหารยาม Crossroads เราต้องการเงินคืน\n\nเรื่องแปลกคือ... เราจับขโมยได้ตัวหนึ่งในคืนนั้น และ... มันเป็นแรปเตอร์! ไม่น่าเชื่อ!\n\nข้าไม่รู้ว่าแรปเตอร์อยากได้เงินไปทำอะไร แต่ข้าไม่สน ขอให้พวกมันตาย จะได้ไม่ขโมยของเราอีก!\n\nล่าแรปเตอร์ใน Barrens แล้วเก็บศีรษะมาให้ข้า!" },
        progress = { "25:668442405:1298953900 N 1:63:63", "ได้ศีรษะพวกนั้นมาหรือยัง {name}?" },
        completion = { "39:235006872:659298375 N 12:1131667476:323107827 C 10:561716389:92176261", "เจ้ากำจัดแรปเตอร์แล้ว!\n\nขอบใจ {name} เจ้าเป็น{class}ที่มีคุณค่า" },
        required = { [5062] = { "11:1063363491:38376024", "หัวแรปเตอร์" } },
        steps = { { "11:1063363491:38376024", "หัวแรปเตอร์" } },
    },
    [897] = { -- The Harvester
        title = { "13:1213038831:52939032", "ผู้เก็บเกี่ยว" },
        objective = { "43:1311688900:1486021110", "นำ Harvester's Head ไปให้ Jorn Skyseer" },
        description = { "115:1457048448:1231761176", "สิ่งมีชีวิตประหลาดคล้ายแมลงนี้ดูอยู่นอกวิถีธรรมชาติ ราวกับไม่ใช่สิ่งที่ควรอยู่ใน Barrens" },
        progress = { "21:996770706:1852707168 N 79:1126811422:1475793852", "เจ้าดูไม่สบายใจ {name} บทเรียนใน Barrens เป็นอย่างไรบ้าง? พบอะไรที่ทำให้กังวลหรือ?" },
        completion = { "276:1401239069:7173334", "ข้าบอกอะไรเกี่ยวกับธรรมชาติของสัตว์ตัวนี้ไม่ได้ เพราะจิตวิญญาณมันหนีไปแล้ว แต่เจ้าคาดถูก มันไม่ควรอยู่ใน Barrens ข้ากลัวว่ามันอาจเป็นลางบอกอนาคตอันมืดมนของเผ่าพ้องเรา...\n\nแต่ตอนนี้จงเตรียมตัวให้พร้อม และหวังว่าเวลาจะคลี่คลายปริศนาของสิ่งมีชีวิตนี้" },
        required = { [5138] = { "16:243895017:502146319", "ศีรษะของ Harvester" } },
        steps = { { "16:243895017:502146319", "ศีรษะของ Harvester" } },
    },
    [3924] = { -- Samophlange Manual
        title = { "18:527723844:189210612", "คู่มือแซโมแฟลนจ์" },
        objective = { "61:914953975:1319113183", "นำ Samophlange Manual ไปให้ Rilli Greasygob ใน Orgrimmar" },
        description = { "476:214944332:1361906771", "ข้าคิดว่าซ่อมแซโมแฟลนจ์ได้ แต่ต้องได้คู่มือผู้ใช้ก่อน ตอนอยู่ Venture Company ข้ามีคู่แข่งชื่อ Boss Copperplug เขากักความลับของแซโมแฟลนจ์ไว้ ค่อย ๆ แบ่งความรู้เกี่ยวกับเครื่องให้คนที่ไว้ใจ ข้าไม่ใช่หนึ่งในไม่กี่คนนั้น...\n\nBoss Copperplug เคยอยู่ที่ Boulder Lode Mine ทางตะวันออกเฉียงเหนือของ Barrens ไปเอาคู่มือจากเขา และถ้าเขาแจกหน้าในคู่มือให้ใคร เจ้าต้องรวบรวมหน้าเหล่านั้นด้วย" },
        progress = { "23:1525012953:1881378328", "ได้คู่มือมาหรือยัง?" },
        completion = { "276:1226311130:1401606686", "เจ้าได้คู่มือมาแล้ว! ข้าแทบรอไม่ไหวที่จะอ่านแล้วหาวิธีซ่อมแซโมแฟลนจ์! ข้าคุยกับ Sputtervalve ใน Ratchet แล้ว เขาฝากขอบใจที่เจ้าช่วย และอยากตอบแทนความพยายามของเจ้า\n\nข้าก็ขอบใจเช่นกัน ถ้าซ่อมเจ้านี่ได้เมื่อไร ข้าจะบอก..." },
        required = { [11149] = { "18:527723844:189210612", "คู่มือเครื่อง Samophlange" } },
        steps = { { "18:527723844:189210612", "คู่มือเครื่อง Samophlange" } },
    },
    [3261] = { -- Jorn Skyseer
        title = { "12:1252283673:704236046", "Jorn Skyseer" },
        objective = { "40:569845463:560414183", "พูดคุยกับ Jorn Skyseer ที่ Camp Taurajo" },
        description = { "27:985303443:1048873511 N 118:1530577635:1410814743", "เวลาฝึกกับข้าของเจ้าสิ้นสุดแล้ว {name} หากอยากเรียนรู้ต่อ ต้องไป Camp Taurajo ทางใต้ แล้วคุยกับ Jorn Skyseer เขาจะชี้ทางให้เจ้าต่อ" },
        completion = { "86:731294094:268314237", "สวัสดี ผู้เยาว์ เจ้ามาเดินบนเส้นทางพรานหรือ?\n\nดีมาก มาเริ่มกันเถอะ", variants = { { "47:986751525:746581949 C 33:624691594:409733253", "สวัสดี ผู้เยาว์ เจ้ามาเดินบนเส้นทาง{class}หรือ?\n\nดีมาก มาเริ่มกันเถอะ" } } },
    },
    [3513] = { -- The Runed Scroll
        title = { "16:935298234:247198814", "ม้วนสารอักขระรูน" },
        objective = { "65:1997189437:557602302", "นำ Runed Scroll ไปยังหอทหารยามทางเหนือใน Barrens" },
        description = { "298:35137784:104231064", "ม้วนสารที่ดูเป็นเอกสารทางการถูกมัดแน่นด้วยริบบิ้นสีเงิน เจ้าคิดว่าต้องมีคนสนใจดูแน่ แต่ใครล่ะ?\n\nมีด่านใกล้ชายแดน Ashenvale ทางเหนือ หากข้อมูลในม้วนสารเกี่ยวข้องกับไนต์เอลฟ์ ที่นั่นก็น่าจะเป็นจุดที่ควรนำไปให้" },
        progress = { "12:2001846775:2061548964", "มีอะไรมา?" },
        completion = { "36:1747144770:684427704", "เอาละ... เจ้าไปเจอนี่ที่ไหน?" },
        required = { [10621] = { "12:1663290509:821296079", "ม้วนคัมภีร์จารึกรูน" } },
        steps = { { "12:1663290509:821296079", "ม้วนคัมภีร์จารึกรูน" } },
    },
    [821] = { -- Chen's Empty Keg
        title = { "16:686886081:1969337172", "ถังเปล่าของ Chen" },
        objective = { "110:769778565:484437531", "นำ Savannah Lion Tusks 5 ชิ้น, Plainstrider Kidneys 5 ชิ้น และ Thunder Lizard Horn 1 ชิ้น ไปให้ Brewmaster Drohn ใน Ratchet" },
        description = { "487:1171594612:1811064232", "อยากชิมเหล้าที่ตั้งชื่อตาม Chen ไหม? อ้า สตอร์มสเตาต์นี่แรงได้ใจ Chen สอนสูตรให้อาจารย์ของข้า แล้วอาจารย์ก็ถ่ายทอดต่อให้ข้า เจ้าต้องหาของมาสักหน่อย แต่บอกได้เลยว่าแรงสะใจคุ้มค่าแน่\n\nนำงาสิงโตทุ่งหญ้า 5 ชิ้นจากสิงโตทุ่งหญ้าชนิดใดก็ได้ ไตเพลนสไตรเดอร์ 5 ชิ้นจากเพลนสไตรเดอร์ชนิดใดก็ได้ และเขากิ้งก่าสายฟ้า 1 ชิ้นจากกิ้งก่าสายฟ้าสายพันธุ์ใดก็ได้มาให้ข้า เท่านี้ก็น่าจะใช้ได้ดี\n\nหาส่วนผสมเหล่านี้ได้ทั่ว Barrens" },
        progress = { "23:1269341731:841707833", "หาไปถึงไหนแล้ว?" },
        completion = { "113:277592557:1815780854 N 108:2104305619:2006282700", "ฮ่า ๆ... ข้าไม่เคยคิดเลยว่าจะได้ทำเหล้านี่อีก\n\nเจ้าปลุกความทรงจำเก่า ๆ ในตัวข้าขึ้นมาเลย {name} ทำให้นึกถึงครั้งล่าสุดที่ข้าหมักเหล้าทร็อก ขอบใจนะ แค่นึกถึงก็อุ่นท้องแล้ว" },
        required = { [4893] = { "18:1832385820:1170070718", "เขี้ยวสิงโตทุ่งหญ้าสะวันนา" }, [4894] = { "19:225358154:408770268", "ไต Plainstrider" }, [4895] = { "19:256083403:1356245315", "เขากิ้งก่าสายฟ้า" } },
        steps = { { "18:1832385820:1170070718", "เขี้ยวสิงโตทุ่งหญ้าสะวันนา" }, { "19:225358154:408770268", "ไต Plainstrider" }, { "19:256083403:1356245315", "เขากิ้งก่าสายฟ้า" } },
    },
    [3281] = { -- Stolen Silver
        title = { "13:263998684:1354623682", "เงินที่ถูกขโมย" },
        objective = { "52:467628040:1123482002", "นำ Stolen Silver ไปให้ Gazrog ใน Crossroads" },
        description = { "336:1519611024:1598047093", "เจ้าอาจฆ่าแรปเตอร์แล้ว แต่ยังต้องเอาเงินที่มันขโมยไปคืน! ข้ามีรายงานว่าแรปเตอร์รวมรังกันมากทางใต้ของ Ratchet ในที่ที่เรียกว่า Raptor Grounds มันคงนำเงินที่ขโมยจากเราไปไว้ที่นั่น\n\nไปแหล่งพักพิงของแรปเตอร์แล้วหาเงินที่ถูกขโมย เมื่อพบก็นำกลับมาให้ข้า" },
        progress = { "23:479692786:1702994845", "ได้เงินมาหรือยัง?" },
        completion = { "219:76943859:536921184 N 125:2085603402:413967246", "อ้า! แรปเตอร์ซ่อนเงินไว้ในรังจริง ๆ ไม่น่าเชื่อว่าสัตว์พวกนี้อยากได้เงิน บางทีเรื่องเล่าถึงความฉลาดของมันอาจไม่ได้เกินจริงอย่างที่ข้าคิด!\n\nขอบใจ {name} รับนี่เป็นรางวัลที่ช่วยเรา และจงรู้ว่าทหารยาม Crossroads ได้ค่าจ้างเดือนหน้าก็เพราะเจ้า" },
        required = { [5061] = { "13:263998684:1354623682", "เครื่องเงินที่ถูกขโมย" } },
        steps = { { "13:263998684:1354623682", "เครื่องเงินที่ถูกขโมย" } },
    },
    [5041] = { -- Supplies for the Crossroads
        title = { "27:1482800861:2140590393", "เสบียงสำหรับ Crossroads" },
        objective = { "66:174152434:1596115611", "ค้นหา Crossroads' Supply Crates แล้วนำกลับไปให้ Thork ใน Barrens" },
        description = { "421:276510809:440924064", "คาราวานที่ถูกโจมตีขนเสบียงที่เราต้องการอย่างยิ่งมา\n\nที่ผ่านมามีความกล้าพอจะสู้เผ่า Razormane ข้าจะขอให้เจ้าทำอีกครั้ง แต่ครั้งนี้ช่วยมองหาเสบียงที่สูญหายของเราด้วยได้ไหม? น่าจะพบตามค่ายพวกมัน พวกควิลบอร์กำลังกินอิ่มหมีพีจากการกระทำไร้เกียรติของตัวเอง\n\nชาว Crossroads จะเป็นหนี้บุญคุณเจ้า" },
        progress = { "39:381883070:119508179 N 55:1581689384:15396341", "หาเสบียงไปถึงไหนแล้ว {name}? ข้าเชื่อว่าพวกควิลบอร์คงล้มลงต่อพลังเจ้าได้ง่ายดาย" },
        completion = { "17:1040512704:2131583955 N 138:768480395:1425327653", "ฮ่า ๆ! ขอบใจ {name}! นี่ช่วยเราได้มาก เจ้าเป็นคุณแก่ Crossroads และ Horde หากมีอะไรที่ข้าช่วยเจ้าได้ ก็บอกมาเถอะ" },
        required = { [12708] = { "25:1452392643:1004132666", "ลังเสบียงของ Crossroads" } },
        steps = { { "25:1452392643:1004132666", "ลังเสบียงของ Crossroads" } },
    },
    [6361] = { -- A Bundle of Hides
        title = { "17:1582892132:810361189", "มัดหนังสัตว์" },
        objective = { "76:1026801613:530128347", "นำ Bundle of Hides ไปให้ Devrak ผู้ดูแลวินด์ไรเดอร์ใน Crossroads" },
        description = { "397:368452973:404818067", "ข้ามีมัดหนังจากสัตว์ใน Barrens ต้องส่งไป Thunder Bluff เพื่อนร่วมงานชื่อ Ahanu จะใช้หนังทำเครื่องหนัง\n\nเจ้าช่วยนำไปให้เขาแทนข้าได้ไหม?\n\nทางเร็วที่สุดไป Thunder Bluff คือขี่วินด์ไรเดอร์ นำมัดหนังไปหา Devrak ผู้ดูแลวินด์ไรเดอร์ของเราที่ Crossroads แล้วคุยกับเขาเรื่องเดินทางไป Thunder Bluff" },
        progress = { "63:957675927:2037187733", "มาขอวินด์ไรเดอร์หรือ? มีของจะขนส่งหรือเปล่า?" },
        completion = { "86:860763631:1936305560", "ถ้าต้องนำหนังพวกนี้ไป Thunder Bluff เจ้าก็คุยถูกออร์คแล้ว!" },
        required = { [16282] = { "15:261702089:1909027423", "มัดหนังสัตว์" } },
        steps = { { "15:261702089:1909027423", "มัดหนังสัตว์" } },
    },
    [873] = { -- Isha Awak
        title = { "9:111026249:1814430742", "Isha Awak" },
        objective = { "47:1546138449:1802051450", "นำ Heart of Isha Awak ไปให้ Mahren Skyseer" },
        description = { "408:215545747:1656879436", "Isha Awak ผู้ยิ่งใหญ่เป็นเจ้าแห่งน่านน้ำนี้ มันแข็งแกร่งมหาศาลและทระนงอย่างสง่า มนุษย์ริมชายฝั่งกลัวมัน เพราะมันกินพวกเขาไปมากแล้ว\n\nแต่ข้าไม่กลัว ข้ายินดีที่มันอยู่ที่นี่ มันเป็นคู่ท้าทายที่คู่ควร เป็นเหยื่อที่มีเกียรติ\n\nหากพร้อมแล้ว จงว่ายออกไปค้นหา Isha Awak หายนะแห่งห้วงลึก\n\nจิตวิญญาณของมันสถิตในหัวใจ เมื่อได้ยินหัวใจนั้นเต้น เจ้าจะรู้ชะตาของตน" },
        progress = { "21:89721439:1961523622 R 1:46:46", "อย่ากลัวผืนน้ำเลย {race}", variants = { { "30:1836350677:1063805688", "อย่ากลัวผืนน้ำเลย สกายบอร์น" } } },
        completion = { "32:1648804335:1655220793 N 89:663311516:2043370760", "บัดนี้เจ้าเป็นหนึ่งเดียวกับ Isha Awak แล้ว {name} จิตวิญญาณมันอยู่กับเจ้า มันซ่อนอยู่ในดวงตาของเจ้า...\n\nดวงตาที่สักวันจะเรียนรู้วิธีมองเห็น" },
        required = { [5104] = { "18:1183727902:1160153992", "หัวใจของ Isha Awak" } },
        steps = { { "18:1183727902:1160153992", "หัวใจของ Isha Awak" } },
    },
    [6364] = { -- Return to Jahan
        title = { "15:523319283:1100401859", "กลับไปหา Jahan" },
        objective = { "118:1019731489:49879134", "จ่ายค่าโดยสารวินด์ไรเดอร์ไป Crossroads ให้ Tal ผู้ดูแลวินด์ไรเดอร์ แล้วนำ Ahanu's Leather Goods ไปให้ Jahan Hawkwing" },
        description = { "374:929077709:1749672333", "ก่อนบินไปเมืองใด เจ้าต้องเคยไปที่นั่นและคุยกับผู้ดูแลวินด์ไรเดอร์ของเมืองนั้นก่อน เจ้าเคยไป Crossroads และคุยกับ Devrak แล้ว จึงจ่ายค่าธรรมเนียมเล็กน้อยเพื่อขึ้นวินด์ไรเดอร์จากที่นี่ไปหาเขาได้\n\nคุยกับข้าอีกครั้งเมื่อพร้อม ถึง Crossroads แล้วก็นำเครื่องหนังไปส่ง Jahan Hawkwing ได้" },
        progress = { "N 70:784338832:1979946284", "{name} กลับจาก Thunder Bluff แล้วหรือ? ส่งหนังให้ Ahanu แล้วใช่ไหม?" },
        completion = { "204:974449642:1854709187 N 20:690179845:657224198", "Ahanu ส่งของที่ทำเสร็จมาให้หรือ? ดีมาก ตอนนี้มีนักล่าและนักผจญภัยมากใน Crossroads ค้าขายคึกคัก ข้ามั่นใจว่าขายของพวกนี้ได้เร็วแน่\n\nขอบใจที่พยายามช่วยทุกอย่าง {name} ข้าเป็นหนี้บุญคุณเจ้า" },
        required = { [16283] = { "21:1061339069:2097447544", "เครื่องหนังของ Ahanu" } },
        steps = { { "21:1061339069:2097447544", "เครื่องหนังของ Ahanu" } },
    },
    [3921] = { -- Wenikee Boltbucket
        title = { "18:698482911:68883349", "Wenikee Boltbucket" },
        objective = { "51:542182608:1551533936", "นำ Broken Samophlange ไปให้ Wenikee Boltbucket" },
        description = { "429:940286704:876486433", "ข้าคิดว่าอาจทำแซโมแฟลนจ์พังเสียแล้ว ไม่ดีเลย เพราะข้าบอกเพื่อนร่วมงานที่ Undermine ไปแล้ว พวกเขาสนใจมาก เราต้องหาทางซ่อม!\n\nนำแซโมแฟลนจ์ที่พังไปให้ Wenikee Boltbucket ทางใต้ของ Mor'shan Rampart เล็กน้อย ด่าน Horde ระหว่าง Barrens กับ Ashenvale นางฉลาดมากและชอบค้นคว้า ถ้าให้ดูแซโมแฟลนจ์ พนันได้เลยว่านางจะรีบคว้าโอกาสซ่อมมัน" },
        progress = { "28:2054559917:310585321 C 70:1358404602:1497943025", "ข้ายุ่งกับงานมาก {class} ถ้าไม่มีอะไรให้ข้า เจ้าควรไปต่อเถอะ..." },
        completion = { "225:1820565736:898893872", "โอ้ อะไรนี่? แซโมแฟลนจ์หรือ? แล้วแซโมแฟลนจ์คืออะไร??\n\nอ้า... แต่ดูตอนจับแล้วมันขยับสิ มีเสียงเฟืองซับซ้อนอยู่ข้างในด้วย โอ้! ข้าอยากซ่อมแล้วดูว่ามันทำอะไรได้ เจ้าไม่อยากหรือ??" },
        required = { [11142] = { "18:1036170638:662744000", "เครื่อง Samophlange ที่ชำรุด" } },
        steps = { { "18:1036170638:662744000", "เครื่อง Samophlange ที่ชำรุด" } },
    },
    [913] = { -- Cry of the Thunderhawk
        title = { "22:64756376:1803832555", "เสียงร้องธันเดอร์ฮอว์ก" },
        objective = { "78:1978642227:479837209", "ค้นหาและสังหาร Thunderhawk แล้วนำปีกกลับไปให้ Jorn Skyseer ที่ Camp Taurajo" },
        description = { "17:321682163:364280410 N 190:264949196:858866176", "ธันเดอร์ฮอว์กเป็นสัตว์ดุร้าย {name} ถึงเวลาที่เจ้าต้องเผชิญมันแล้ว เจ้าต้องหาถิ่นที่มันเดินทาง และนำปีกมาให้ข้าเป็นหลักฐานว่าล่าสำเร็จ\n\nทำได้แล้ว เวลาฝึกกับข้าของเจ้าก็ใกล้จบ" },
        progress = { "43:133560718:1579383587", "เสร็จแล้วหรือ? ฆ่าธันเดอร์ฮอว์กแล้วหรือยัง?" },
        completion = { "155:599896561:1959043585 N 160:1143259449:15494572", "เจ้าควรภูมิใจเหมือนธันเดอร์ฮอว์ก เจ้าปราบศัตรูทุกตัวที่เราส่งไปเผชิญ ด้วยพลัง ความกล้า และเกียรติ\n\nแต่เส้นทางของเจ้ายังดำเนินต่อ {name} ที่จริง เจ้าจะพบว่านักล่าที่แท้จริงเพียรพยายามเสมอ เดินตามเส้นทางอย่างภาคภูมิไม่ต่างจากที่เจ้าแสดงให้ข้าเห็น\n\nบัดนี้ถึงเวลาไปต่อแล้ว" },
        required = { [5164] = { "17:2050389429:2014191879", "ปีกเหยี่ยวสายฟ้า" } },
        steps = { { "17:2050389429:2014191879", "ปีกเหยี่ยวสายฟ้า" } },
    },
    [5046] = { -- Razorhide
        title = { "9:1546728510:409386846", "ผิวหนังคมกริบ" },
        progress = { "364:1965200593:1720805188", "ทุกคนที่ <พ่นลมทางจมูก> เข้ารบต้องการการป้องกัน กระดูกต้องแข็งแกร่ง ผิวหนังต้องทนทาน <พ่นลมทางจมูก> เผ่าข้ารู้เช่นกัน นอกจากการป้องกันตามธรรมชาติจากขนหนามและหนัง <พ่นลมทางจมูก> เรามักขอให้ Agamaggan คุ้มครองก่อนออกศึก\n\nนำเศษโลหิต 4 ชิ้นมา <พ่นลมทางจมูก> แล้วข้าจะให้เจ้ามีการคุ้มครองเช่นเดียวกัน" },
        completion = { "11:1814095675:1147964620 R 1:46:46", "จงออกศึก {race}" },
        description = { "364:1965200593:1720805188", "ทุกคนที่ <พ่นลมทางจมูก> เข้ารบต้องการการป้องกัน กระดูกต้องแข็งแกร่ง ผิวหนังต้องทนทาน <พ่นลมทางจมูก> เผ่าข้ารู้เช่นกัน นอกจากการป้องกันตามธรรมชาติจากขนหนามและหนัง <พ่นลมทางจมูก> เรามักขอให้ Agamaggan คุ้มครองก่อนออกศึก\n\nนำเศษโลหิต 4 ชิ้นมา <พ่นลมทางจมูก> แล้วข้าจะให้เจ้ามีการคุ้มครองเช่นเดียวกัน" },
        required = { [5075] = { "11:911674189:766411410", "เศษผลึกโลหิต" } },
        steps = { { "11:911674189:766411410", "เศษผลึกโลหิต" } },
    },
    [860] = { -- Sergra Darkthorn
        title = { "16:1042374992:300016696", "Sergra Darkthorn" },
        objective = { "46:1129522416:682586506", "พูดคุยกับ Sergra Darkthorn ที่ Crossroads" },
        description = { "475:2015006072:676204953", "หากอยากเดินบนเส้นทางนักล่า เจ้าต้องไป Barrens สัตว์ร้ายที่นั่นดื้อรั้นและดุร้าย เจ้าจะเรียนรู้ได้มากจากการล่าที่นั่น และจิตวิญญาณเจ้าจะเติบโต\n\nไปคุยกับ Sergra Darkthorn นางจะเป็นผู้นำทางคนแรกของเจ้าใน Barrens\n\nSergra อยู่ที่ Crossroads เดินทางจาก Bloodhoof Village ไปทางตะวันออกเข้าสู่ Barrens แล้วเลี้ยวเหนือเมื่อถึงทางแยก ระวังระหว่างทางด้วย Barrens มีภัยใหญ่หลวงสำหรับคนที่ไม่เตรียมพร้อมและประมาท" },
        completion = { "330:599925166:173362456", "อยากล่าสัตว์ใน Barrens หรือ?\n\nดวงตาเจ้าเต็มไปด้วยความกระตือรือร้นและความเยาว์วัย ยังไม่หรี่ลงจากการตามรอยเหยื่อข้ามทุ่งแห้งแล้งของดินแดนนี้\n\nแต่ไม่ต้องห่วง เราจะฝึกทั้งร่างกายและจิตใจเจ้าให้แข็งแกร่ง และสอนว่าการล่าไม่ได้มีแค่หาเหยื่อให้เจอแล้วฆ่า\n\nเตรียมตัวให้พร้อม การเดินทางของเจ้าเริ่มต้นแล้ว ตอนนี้เลย" },
    },
    [3514] = { -- Horde Presence
        title = { "14:880788911:1434805974", "ประกาศการมีอยู่ของ Horde" },
        objective = { "59:302093749:1631553364", "สังหาร Rynthariel the Keymaster ผู้นำแห่ง Talon Den" },
        description = { "267:766751299:1019405818 N 107:1577763978:1791937736 N 119:1623405117:1754617461", "ม้วนสารมาจากดรายแอดเจ้าแผนการ Rynthariel ผู้ถือกุญแจแห่ง Talon Den บน Stonetalon Peak\n\nนางคงไม่ได้ติดต่อคนส่งสารที่เจ้าค้นของมาจากศพอีกแล้ว หึ แต่เราต้องยืนหยัดที่นี่ Horde จะไม่ยอมให้หน่วยวิ่งส่งสารของนางเข้ามา\n\n{name} ไปที่ Talon Den ฆ่า Rynthariel แล้ววางสัญลักษณ์ให้ทุกคนเห็น เอาธง Horde นี้ไป {name} ปักไว้ใน Talon Den พวกนั้นจะได้ไม่ผลีผลามส่งคนผ่านดินแดนเราอีก" },
        progress = { "42:19705941:1455532464 N 18:1322070490:1475454975", "เรายอมให้ Alliance อยู่บนแผ่นดินเราไม่ได้ {name} ทำให้พวกมันรู้เสีย" },
        completion = { "67:76564484:976477167 N 158:27290340:774972773", "เจ้าแกร่งจริง! กำจัด Rynthariel จากถ้ำได้เป็นก้าวสำคัญ {name} พวกมันคงรวมตัวใหม่ได้ช้า เราจึงวางใจได้ว่าจะมีคนวิ่งส่งสาร Alliance ใน Barrens น้อยลง พวกมันต้องคิดใหม่ก่อนส่งอีกคนมาทางนี้\n\nขอบใจ" },
        objectiveLabels = {
            monster = { ["Rynthariel the Keymaster slain"] = "ปราบ Rynthariel ผู้ดูแลกุญแจ" },
        },
    },
    [6362] = { -- Ride to Thunder Bluff
        title = { "21:434710536:1259922144", "บินสู่ Thunder Bluff" },
        objective = { "126:2093088609:648715946", "จ่ายค่าโดยสารวินด์ไรเดอร์ไป Thunder Bluff ให้ Devrak ผู้ดูแลวินด์ไรเดอร์ แล้วนำ Bundle of Hides ไปให้ Ahanu ใน Thunder Bluff" },
        description = { "330:847131818:775567027", "เสียค่าธรรมเนียมเล็กน้อย ข้าก็จัดวินด์ไรเดอร์ไป Thunder Bluff ให้ได้ ไม่มีทางไปเมืองเร็วกว่านี้แล้ว!\n\nถ้าตกลง เมื่อพร้อมไปก็คุยกับข้าอีกครั้ง\n\nหากนำหนังพวกนั้นไปให้ Ahanu ข้าคิดว่าเขาอยู่ที่ Hewa's Armory เชิงหอวินด์ไรเดอร์ใน Thunder Bluff และนั่นก็คือจุดที่เจ้าจะลง!" },
        progress = { "100:476791937:521295614", "ฝุ่นบนบ่าเจ้าคงมาจาก Barrens เจ้าคุยกับ Jahan สหายข้ามาแล้วหรือ?" },
        completion = { { "180:253946874:1860287893", "179:1935781984:1073464457" }, "อ้า มัดหนังใหม่ ข้าจะเริ่มทำงานทันที!\n\nขอบใจ พี่น้อง เจ้าช่วยข้าได้มาก นี่เงินเล็กน้อยตอบแทนเวลาและค่าเดินทาง" },
        required = { [16282] = { "15:261702089:1909027423", "มัดหนังสัตว์" } },
        steps = { { "15:261702089:1909027423", "มัดหนังสัตว์" } },
    },
    [1060] = { -- Letter to Jin'Zil
        title = { "17:991664944:1539309863", "จดหมายถึง Jin'Zil" },
        objective = { "80:1610676751:1130858664", "ส่งจดหมายของ Darsok ให้ Jin'Zil ในถ้ำของเขาที่ Malaka'Jin ใน Stonetalon" },
        description = { "28:1284958024:381164809 N 469:1503286717:856957624", "เจ้าช่วยงานข้าได้ดีมาก {name} เป็นเหมือนเครื่องรางเท้ากระต่ายนำโชคเลย มีบางอย่างที่ข้าอยากให้เจ้าไปเห็น\n\nฮาร์ปีไม่ได้มาจากแถว Barrens แต่มาจากสถานที่ชื่อ Stonetalon ไกลขึ้นไปทางตะวันตกเฉียงเหนือ ถึงที่นั่นอาจอันตรายสำหรับเจ้า แต่ข้าต้องส่งจดหมายนี้ให้สหายเก่าที่อยู่ที่นั่น หมอผีชื่อ Jin'Zil\n\nเขาคงดีใจที่รู้ว่า Serena Bloodfeather ตายแล้ว และข้าคิดว่าเจ้าจะพบว่า Stonetalon น่าสนใจ" },
        progress = { "61:1466485103:1943242040", "เจ้าดูไม่น่าไว้ใจ มีอะไรให้ข้าดูหรือ?" },
        completion = { "261:1721371692:1854403722", "อ้า จดหมายจาก Darsok ข้าไม่ได้ข่าวเขามาหลายปีแล้ว\n\nBloodfeather คนสุดท้ายตายแล้วสินะ? ข่าวดี ข้ายังจำตอน Rokhan สหายข้าไปกับเจ้าม็อกนาธาลบ้าบิ่นนั่นเพื่อฆ่าพี่สาวของนางได้ อ้า อยากกลับไปหนุ่มเหมือนเจ้าอีกครั้งจริง ๆ" },
        required = { [5594] = { "17:991664944:1539309863", "จดหมายถึง Jin'Zil" } },
        steps = { { "17:991664944:1539309863", "จดหมายถึง Jin'Zil" } },
    },
    [3922] = { -- Nugget Slugs
        title = { "12:443860768:1556873453", "ชิ้นส่วน Nugget Slugs" },
        objective = { "59:1642049601:156533084", "นำ Nugget Slugs 15 ชิ้น ไปให้ Wenikee Boltbucket ใน Barrens" },
        description = { "440:1747300851:2114964729", "ข้าอยากซ่อมแซโมแฟลนจ์ แต่ต้องใช้ของบางอย่างก่อน Nugget Slugs ขนาดเกจสิบเจ็ดจุดห้าของข้าหมดแล้ว งานที่จะทำต้องใช้ของพวกนั้นมากทีเดียว\n\nแหล่งใกล้ที่สุดคือ Sludge Fen ทางตะวันออก ปกติ Venture Company เก็บไว้ในถังเครื่องมือ ไป Sludge Fen แล้วค้นถังเครื่องมือที่พบ กลับมาหาข้าเมื่อเก็บ Nugget Slugs ได้พอแล้ว" },
        progress = { "30:1152528239:671349060 N 71:274094333:173581073", "ได้ Nugget Slugs มาหรือยัง {name}? ข้าจ้องแซโมแฟลนจ์นี่อยู่ อยากเริ่มรื้อมันแทบแย่แล้ว" },
        completion = { "45:734193258:1253894111", "ดีมาก ได้มาแล้ว! ทีนี้ข้าก็เริ่มงานได้..." },
        required = { [11143] = { "11:1088002859:1110215851", "แท่งโลหะ Nugget Slug" } },
        steps = { { "11:1088002859:1110215851", "แท่งโลหะ Nugget Slug" } },
    },
    [882] = { -- Ishamuhale
        title = { "10:1808673951:218477959", "Ishamuhale" },
        objective = { "48:272446324:1300939333", "นำ Ishamuhale's Fang ไปให้ Jorn ที่ Camp Taurajo" },
        description = { "232:661550493:1887876649 N 251:1610768494:589055409", "Ishamuhale หรือเขี้ยวหอก เป็นแรปเตอร์ Sunscale ที่ดุร้ายที่สุดใน Barrens มันไม่ได้ล่าเพื่อความสนุกหรืออาหาร แต่มันล่าเพราะหลงใหลการล่า มันฆ่าเพราะธรรมชาติของมันคือการฆ่า\n\nและเจ้าจะได้เรียนรู้ธรรมชาตินั้น {name} เพราะเส้นทางเจ้าบัดนี้ตามไปบนรอยกรงเล็บของ Ishamuhale\n\nเริ่มล่าได้ ฆ่าซีฟราซึ่งเป็นเหยื่อโปรดของมัน แล้วนำซากไปที่ต้นไม้ตายทางตะวันตกเฉียงเหนือของ Ratchet Ishamuhale จะได้กลิ่นซากและถูกล่อมา\n\nเตรียมพร้อมเมื่อมันมาถึง" },
        progress = { "N 29:1146726225:1898204238", "{name} เจ้าปราบ Ishamuhale ได้แล้วหรือ?" },
        completion = { "98:1214262720:2141022966 N 74:2005726025:526884531", "เขี้ยวนี้เป็นเพียงสัญลักษณ์ แต่ความหมายของมันลึกซึ้ง\n\nพลังของ Ishamuhale อยู่ในตัวเจ้า {name} ขอให้เจ้าใช้มันอย่างยับยั้งชั่งใจ นั่นคือภาระของเจ้า\n\nนั่นคือเกียรติของเจ้า" },
        required = { [5101] = { "17:1775074422:482173248", "เขี้ยวของ Ishamuhale" } },
        steps = { { "17:1775074422:482173248", "เขี้ยวของ Ishamuhale" } },
    },
    [899] = { -- Consumed by Hatred
        title = { "18:2109082634:305115967", "ถูกความเกลียดชังกลืนกิน" },
        objective = { "65:776613850:65813555", "นำ Bristleback Quilboar Tusks 60 ชิ้น ไปให้ Mankrik ที่ Crossroads" },
        description = { "55:128561483:1848908338 C 321:179543920:23569880 C 123:2069659951:420062903", "บางทีเจ้าอาจรู้จักความเจ็บปวดจากการไม่รู้คำตอบ หรืออาจไม่รู้ {class} แต่จงรู้ไว้ว่าข้ายืนอยู่ตรงนี้ทุกวัน ตั้งแต่ตะวันขึ้นจนลับลง กวาดตามองขอบฟ้าหาสัตว์ประหลาดพวกนั้นเพิ่ม ตั้งแต่นั้นมาข้าฆ่ามนุษย์หมูทุกตัวที่เจอ แต่ความกระหายเลือดยังไม่จาง บางทีข้าควรมุ่งไป Taurajo แทนที่จะขึ้นเหนือไป Crossroads\n\nเจ้า {class} เจ้าช่วยข้าได้\n\nฆ่าพวกมัน ฆ่าให้มากที่สุด นำงามาให้ข้า แล้วเราจะฉลองความตายของพวกมันด้วยกัน" },
        progress = { "32:1370558776:1494673278 N 13:517490135:858288610", "ควิลบอร์ต้องชดใช้เรื่องนี้ {name} ข้าสาบาน" },
        completion = { "C 169:1279072166:1122295983", "{class} เจ้าจริงจังกับงานของข้า ข้าขอบใจ\n\nแม้ความอยากล้างแค้นยังอยู่ แต่อย่างน้อยข้าก็ยิ้มได้เมื่อเห็นว่าควิลบอร์เจ็บปวดบ้างแล้ว" },
        required = { [5085] = { "25:455007454:1019326150", "งาควิลบอร์ Bristleback" } },
        steps = { { "25:455007454:1019326150", "งาควิลบอร์ Bristleback" } },
    },
    [843] = { -- Gann's Reclamation
        title = { "18:360155886:1875567886", "ทวงคืนผืนดินให้ Gann" },
        objective = { "125:580868526:1303637455", "Gann Stonespire ต้องการให้เจ้าสังหาร Bael'dun Excavators 15 คน และ Bael'dun Foremen 5 คน\n\nนำ Khazgorm's Journal ไปให้ Gann Stonespire" },
        description = { "496:1013066042:1434213194", "ข้าเดินไปตามถนนเหล่านี้เพียงลำพัง\n\nคนแคระแห่ง Bael Modan ไม่เคารพแผ่นดินของข้า เสียงระเบิดน่าสะพรึงเจาะพื้นดินเป็นหลุมลึก ขณะที่เครื่องจักรเสียงดังฉีกทึ้งเนินเขา ผืนดินที่เคยเป็นบ้านและเลี้ยงดูเผ่าของข้า บัดนี้เต็มไปด้วยคนแคระที่มุ่งทำลาย\n\nความพยายามเจรจาหาทางออกร่วมกันล้มเหลว ถึงเวลาลงมืออย่างเด็ดขาดแล้ว\n\nใช้กำลังขับไล่คนแคระออกจากแหล่งขุดค้น Bael Modan และนำบันทึกของผู้นำพวกมัน Prospector Khazgorm มาให้ข้า" },
        progress = { "150:777705779:84770276", "เมื่อคนแคระแห่ง Bael Modan มาถึง ทอเรนผู้บริสุทธิ์มากมายต้องตายหรือถูกขับไล่จากถิ่นกำเนิดของบรรพชน ข้าต้องทวงแผ่นดินคืน!" },
        completion = { "243:1275316562:787394471", "Khazgorm ได้รับชะตากรรมที่สมควรแล้ว ข้าไม่เสียใจให้เจ้าคนโง่นั่น มันไม่เคารพสิ่งศักดิ์สิทธิ์ของแผ่นดินนี้\n\nขอให้ความตายของมันเตือนทุกคนที่คิดทำลายวิถีชีวิตของเรา\n\nเอาละ ขอเวลาข้าศึกษาบันทึกของคนแคระสักครู่..." },
        required = { [5006] = { "18:1243039523:1506293175", "บันทึกของ Khazgorm" } },
        steps = { { "18:1243039523:1506293175", "บันทึกของ Khazgorm" } },
        objectiveLabels = {
            monster = { ["Bael'dun Excavator slain"] = "ปราบ นักขุดค้น Bael'dun", ["Bael'dun Foreman slain"] = "ปราบ หัวหน้าคนงาน Bael'dun" },
        },
    },
    [6385] = { -- Doras the Wind Rider Master
        title = { "27:1689385397:727296012", "Doras ผู้ดูแลวินด์ไรเดอร์" },
        objective = { "45:2059861375:1898007950", "นำ Gryshka's Letter ไปให้ Doras ใน Orgrimmar" },
        description = { "308:800922370:330326621", "ข้าเขียนจดหมายขอบคุณ Zargh แล้ว ช่วยนำไปส่งให้ได้ไหม? ถ้าเจ้าเคยไป Crossroads และคุยกับผู้ดูแลวินด์ไรเดอร์แล้ว ก็ขึ้นวินด์ไรเดอร์บินกลับไปได้\n\nนำจดหมายข้าไปให้ Doras ผู้ดูแลวินด์ไรเดอร์ใน Orgrimmar แล้วคุยกับเขาเรื่องเดินทางไป Crossroads" },
        progress = { "34:935277953:248183643", "ต้องการวินด์ไรเดอร์ของข้าหรือ?" },
        completion = { "82:274871297:5040711", "ต้องนำของนี่ไป Crossroads ใน Barrens หรือ? ได้ ข้าพาไปได้..." },
        required = { [16307] = { "16:551568314:533917572", "จดหมายของ Gryshka" } },
        steps = { { "16:551568314:533917572", "จดหมายของ Gryshka" } },
    },
    [98095] = { -- Valuable Vantages
        title = { "17:71236265:27375182", "จุดสูงอันทรงค่า" },
        objective = { "119:142100881:730997370", "Deathstalker Masoj ต้องการให้เจ้าวาง Apothecary Vials ทั้งสามบนยอดเขารอบ Hillsbrad Foothills แล้วกลับไปหาเขา" },
        description = { "505:1107969263:1284777314", "กองบัญชาการของเราส่งกำลังพลเข้าจุดยุทธศาสตร์ด้วยผู้ขี่ค้างคาว จุดสำคัญรอบเชิงเขาสูญเสียสัญญาณนำทางไปแล้ว\n\nรับขวดเหล่านี้ไป เปิดจุกในสามแห่ง: เนินเขาชายเขต Dun Garok ที่ราบสูงซึ่งมองลงเห็น Dunholde Keep และแห่งสุดท้ายบนสันเขาของ Headland เหนือเมือง Hillsbrad ไอที่ออกมาจะเป็นดั่งแท่งนำสัญญาณแรงกล้าต่อประสาทสัมผัสค้างคาว ดึงพวกมันกลับไปยังจุดส่งกำลังที่ต้องการอีกครั้ง\n\nมองหาขวดเปล่าที่แตก แล้วเติมเครื่องหมายของเราให้ใหม่" },
        completion = { { "92:1443418913:434750322", "85:228147920:1621278083 N 1:46:46", "85:228147920:1621278083 C 1:46:46", "85:228147920:1621278083 R 1:46:46" }, "ทำได้ดี เราผลักดันแผนต่อไป\n\nเดธสตอล์กเกอร์กล้าเผชิญ\n\nให้จุดมุ่งหมายชี้นำทุกการจู่โจม สหาย" },
        progress = { "146:2074446110:486031929", "เครื่องหมายที่มองไม่เห็นกับอาวุธที่ซ่อนไว้พลิกผลการรบจากปากเหวแห่งความพ่ายแพ้ให้กลายเป็นชัยชนะเด็ดขาดได้\n\nต้องเตรียมตัวให้พร้อมและรู้จักอดทนรอ" },
        steps = { { "19:857277557:1439333036", "วางขวดยาทางตะวันตก" }, { "20:1711157421:1125916413", "วางขวดยาทางเหนือ" }, { "20:703367300:364428943", "วางขวดยาทางใต้" } },
    },
    [95774] = { -- Her Name Is Olgra
        title = { "17:1776616441:452219342", "นางชื่อ Olgra" },
        objective = { "74:851448508:752667766", "สังหารควิลบอร์แล้วรวบรวม Olgra's Adornments 4 ชิ้น สำหรับอนุสรณ์ของ Mankrik", amount = { "27:2143409881:1572894056 W1 46:1858555305:1889908647", "สังหารควิลบอร์แล้วรวบรวม Olgra's Adornments {world1} ชิ้น สำหรับอนุสรณ์ของ Mankrik" } },
        description = { "351:769552621:1155409696", "ผู้รักษาที่ช่วยข้าช่วยนางไม่ได้ นางจึงตายในศึก นางชื่อ Olgra และข้าจะไม่มีวันลืม\n\nเจ้าไม่พบเครื่องประดับบนร่างนางหรือ? นางสวมเครื่องประดับกระดูกขัดมันหลายชิ้น\n\nฆ่า Razormane Raiders ใกล้จุดที่นางล้มลง แล้วหาผลงานศิลป์ล้ำค่าของนาง!\n\nข้าจะวางไว้กับอนุสรณ์ที่สร้างขึ้นเพื่อรำลึกถึงนาง" },
        progress = { "86:1065414552:426709550", "ตอนนี้ข้าเหลือเพียงความทรงจำ แต่จะสร้างสิ่งรำลึกถึง Olgra เพื่อไม่ให้มันเลือนหาย" },
        completion = { "272:22885548:606324706 N 1:46:46", "ข้าจะวางเครื่องประดับเหล่านี้ไว้ที่อนุสรณ์ของ Olgra เพื่อไม่ให้ลืมนาง เลือดข้าจะร้อนด้วยความแค้นตั้งแต่วันนี้จนวันสุดท้ายของชีวิต ทุกครั้งที่แกว่งดาบและล้มศัตรู จะเป็นไปในนามนาง\n\nเจ้าให้เกียรติข้า... ให้เกียรติเรา... อย่างยิ่ง\n\nLok-tar, {name}", variants = { { "172:812542170:479261876 N 1:46:46", "ข้าจะวางเครื่องประดับเหล่านี้ไว้ที่อนุสรณ์ของภรรยาข้า เพื่อจะได้ไม่มีวันลืมนาง เลือดข้าจะเดือดพล่านด้วยความแค้นตลอดไป!\n\nเจ้าช่วยข้า... ช่วยเราทั้งสองไว้มากจริง ๆ {name}" } } },
        required = { [277277] = { "18:1183322101:970412288", "เครื่องประดับของ Olgra" } },
        steps = { { "18:1183322101:970412288", "เครื่องประดับของ Olgra" } },
    },
    [853] = { -- Apothecary Zamah
        title = { "16:382756561:2107410555", "นักปรุงยา Zamah" },
        objective = { "92:424599914:243074285", "นำ Rendered Spores ไปให้ Apothecary Zamah ใน Thunder Bluff ก่อนหมดเวลาที่กำหนด" },
        description = { "490:532532964:1621379674", "ข้าสกัดสปอร์ที่เจ้าให้มาเป็นของเหลวผสมแล้ว ตอนนี้ต้องส่งให้เพื่อนร่วมงาน Apothecary Zamah ถ้าเจ้าช่วยนำไปให้นาง นางจะมอบของจากคลังสิ่งปรุงทางเล่นแร่แปรธาตุของเราให้เจ้าได้\n\nนางอยู่ใน Pools of Vision ถ้ำใต้บริเวณที่เหล่าชาแมนแห่ง Thunder Bluff อยู่ ทางเข้าถ้ำซ่อนอยู่ดีทีเดียว แต่เจ้าหาได้บนเนิน Spirit Rise\n\nรีบหน่อย ของเหลวผสมนี้คงฤทธิ์ได้ไม่นาน ต้องนำไปปิดผนึกและแปรสภาพต่อให้ทันก่อนฤทธิ์เสื่อม" },
        progress = { "43:29988116:644780500", "มีของจาก Apothecary Helbrim มาหรือ?" },
        completion = { "201:1283138844:1971422058 C 1:46:46", "อ้า สปอร์จาก Barrens ที่ Helbrim รวบรวมอยู่ เขาขอให้เจ้าช่วยนำมาส่งสินะ? ดีแล้ว\n\nของเหลวผสมยังมีฤทธิ์แรง แสดงว่าเจ้าไม่เสียเวลาระหว่างส่ง ทำได้ดี {class}" },
        required = { [5027] = { "15:1750784884:57386290", "สปอร์ที่เคี่ยวเป็นของเหลว" } },
        steps = { { "15:1750784884:57386290", "สปอร์ที่เคี่ยวเป็นของเหลว" } },
    },
    [822] = { -- Chen's Empty Keg
        title = { "16:686886081:1969337172", "ถังเปล่าของ Chen" },
        objective = { "101:1566450379:1478144188", "นำ Lightning Glands 5 ชิ้น, Thunderhawk Saliva Gland 1 ชิ้น และ Kodo Liver 1 ชิ้น ไปให้ Brewmaster Drohn ใน Ratchet" },
        description = { "432:1204883043:261621026", "สตอร์มสเตาต์รสดีใช่ไหมล่ะ?\n\nข้ามีอีกสูตรที่เรียนมาจาก Chen สนใจไหม? ทำไม่นาน และอาจมีประโยชน์ถ้าเจ้าจะออกผจญภัยต่อ\n\nนำต่อมสายฟ้า 5 ชิ้นจาก Stormhide ตัวใดก็ได้ ต่อมน้ำลายธันเดอร์ฮอว์ก 1 ชิ้นจาก Greater Thunderhawks และตับโคโดจากโคโดตัวใดก็ได้ใน Barrens มาให้ข้า\n\nอย่างที่บอก เหล้านี่แรงได้ใจ นี่แหละเหล้าทร็อกที่ข้าเคยเล่าให้ฟัง" },
        progress = { "47:424014794:1346377712 N 1:63:63", "กำลังตั้งใจหาส่วนผสมพวกนั้นอยู่ใช่ไหม {name}?" },
        completion = { "96:1535243967:813179977 N 58:2125713155:1059347385", "ฮ่า ๆ! ข้ารู้ว่าเจ้าต้องอดใจไม่ไหว อยากได้อีกก็กลับมาได้เสมอนะ {name} แค่นำส่วนผสมแบบที่ข้าให้เจ้ารวบรวมมาเพิ่มก็พอ" },
        required = { [4898] = { "15:358472928:384847742", "ต่อมกำเนิดสายฟ้า" }, [4897] = { "24:278061290:80330932", "ต่อมน้ำลายของเหยี่ยวสายฟ้า" }, [4896] = { "10:1603664511:1966915594", "ตับโคโด" } },
        steps = { { "15:358472928:384847742", "ต่อมกำเนิดสายฟ้า" }, { "24:278061290:80330932", "ต่อมน้ำลายของเหยี่ยวสายฟ้า" }, { "10:1603664511:1966915594", "ตับโคโด" } },
    },
    [3923] = { -- Rilli Greasygob
        title = { "15:795785418:999376522", "Rilli Greasygob" },
        objective = { "74:264694926:227145456", "นำ Broken and Battered Samophlange ไปให้ Rilli Greasygob ใน Orgrimmar" },
        description = { "489:1091855602:626548887", "เอาละ ไม่สำเร็จ ข้าเพิ่มมาตรวัดให้แซโมแฟลนจ์เพื่อตรวจความสมบูรณ์ของโครงสร้าง และมันอ่านค่าได้ต่ำที่สุดเท่าที่เคยมี ข้าจะเพิ่มหน้าปัดกับคันโยกอีกสักอันสองอันเพื่อลองซ่อมก็ได้ แต่... ข้าคิดว่าอาจยิ่งแย่\n\nเจ้าน่าจะนำแซโมแฟลนจ์ไปให้ Rilli Greasygob เขาเคยทำงานให้ Venture Company ถ้าจะมีใครรู้วิธีซ่อม ก็ต้อง Rilli\n\nหาเขาได้ที่ Nogg's Machine Shop ใน Valley of Honor ของ Orgrimmar" },
        progress = { "61:584835073:1371801155", "ระวังหัวเจ้า! ข้าไม่อยากให้มันมาเกะกะงาน!" },
        completion = { "180:916414427:345559143", "อะไรนี่? อ้าว แซโมแฟลนจ์! เจ้าได้มาจากไหน? ไปยุ่มย่ามในเขต Venture Company ที่ Barrens มาหรือ?\n\nเจ้าต้องกล้ามาก หรือไม่ก็โง่มาก" },
        required = { [11146] = { "31:906591230:1429947936", "เครื่อง Samophlange ที่พังยับเยิน" } },
        steps = { { "31:906591230:1429947936", "เครื่อง Samophlange ที่พังยับเยิน" } },
    },
    [5042] = { -- Agamaggan's Strength
        title = { "20:2129865178:969230224", "พละกำลังแห่ง Agamaggan" },
        progress = { "61:853504959:879072222 R 150:813319812:1224089165", "ข้าต้องการเศษโลหิต 4 ชิ้น หากเจ้าอยากได้พละกำลังของ Agamaggan {race}\n\nเมื่อได้รับพรนี้ ศัตรูจะขลาดกลัวต่อพลังเจ้า <พ่นลมทางจมูก>\n\nนักรบที่ยิ่งใหญ่ที่สุดของ Razormane เปี่ยมด้วยพลังเช่นนี้!", variants = { { "219:2050305771:691982793", "ข้าต้องการเศษโลหิต 4 ชิ้น หากเจ้าอยากได้พละกำลังของ Agamaggan สกายบอร์น\n\nเมื่อได้รับพรนี้ ศัตรูจะขลาดกลัวต่อพลังเจ้า <พ่นลมทางจมูก>\n\nนักรบที่ยิ่งใหญ่ที่สุดของ Razormane เปี่ยมด้วยพลังเช่นนี้!" } } },
        completion = { "226:1522481347:806185029", "ถ้า Mangletooth เป็นอิสระได้เห็นเจ้าทำลายคนที่ทรยศเขาก็คงดี! <พ่นลมทางจมูก>\n\nขอบใจที่กำจัด Bristleback เพิ่มเพื่อนำเศษโลหิตเหล่านี้มา ทำต่อไปเถอะ แล้วข้าจะช่วยเจ้าต่อไป <พ่นลมทางจมูก>" },
        description = { "61:853504959:879072222 R 150:813319812:1224089165", "ข้าต้องการเศษโลหิต 4 ชิ้น หากเจ้าอยากได้พละกำลังของ Agamaggan {race}\n\nเมื่อได้รับพรนี้ ศัตรูจะขลาดกลัวต่อพลังเจ้า <พ่นลมทางจมูก>\n\nนักรบที่ยิ่งใหญ่ที่สุดของ Razormane เปี่ยมด้วยพลังเช่นนี้!" },
        required = { [5075] = { "11:911674189:766411410", "เศษผลึกโลหิต" } },
        steps = { { "11:911674189:766411410", "เศษผลึกโลหิต" } },
    },
    [97253] = { -- Parts and Pieces
        title = { "16:2087581128:1817707402", "ชิ้นส่วนกระจัดกระจาย" },
        objective = { "131:309487204:1630158666", "รวบรวม Handfuls of Complicated Parts 5 ชุด จากค่ายโจรสลัดด้านบนทางใต้ของ Ratchet แล้วกลับไปหา Wrenix the Wretched ใน Ratchet", amount = { "8:1089852795:1107240600 W1 122:851103953:1688397196", "รวบรวม Handfuls of Complicated Parts {world1} ชุด จากค่ายโจรสลัดด้านบนทางใต้ของ Ratchet แล้วกลับไปหา Wrenix the Wretched ใน Ratchet" } },
        description = { "489:594732555:1234592426", "เฮ้ มีเวลาสักครู่ไหม?\n\nดูเหมือนคนที่ข้าส่งไปแก้ปัญหาโจรสลัดช่วงนี้ไม่มีใครกลับมาทั้งเป็น หลังลองไปห้าหกครั้ง ข้าก็คิดว่า \"ส่งเครื่องจักรแทนดีไหม?\" ปรากฏว่าดาบโค้งใช้แทนไขควงยามจำเป็นได้ ข้ายังไม่ทันสั่งมันกลับบ้าน มันก็กลายเป็นชิ้นส่วนกระจายทั่วค่ายแล้ว!\n\nข้าต้องได้ชิ้นส่วนคืน และเพราะนี่เป็นแค่งานเก็บของเร็ว ๆ ข้าพนันว่าโอกาสรอดของเจ้าสูงกว่าคนอื่นมาก ว่าอย่างไร?" },
        progress = { "71:862562132:1489090076", "ไม่ต้องพูดอีกสักคำ จนกว่าในกระเป๋าเจ้าจะมีโลหะกระทบกันกรุ๊งกริ๊ง!" },
        completion = { "239:725792053:1248663224", "โอ้โฮ! เยี่ยมเลย สหาย! เจ้าช่วยข้าจากคำเทศนาทนไม่ไหวของ Gagsprocket เรื่องราคาโลหะไปอีกครั้ง ที่สำคัญกว่า ข้าลงมือสร้างเครื่องต้นแบบตัวต่อไปได้ทันที\n\nเอ่อ ข้ายังไม่ได้เตรียมรางวัลไว้... ชอบกล่องไหม?" },
        required = { [277331] = { "28:1860481888:311112485", "ชิ้นส่วนกลไกซับซ้อนหนึ่งกำมือ" } },
        steps = { { "28:1860481888:311112485", "ชิ้นส่วนกลไกซับซ้อนหนึ่งกำมือ" } },
    },
    [849] = { -- Revenge of Gann
        title = { "15:1908176202:1258581590", "การล้างแค้นของ Gann" },
        objective = { "71:600806699:1659590044", "ทำลายเครื่องบินที่ Bael Modan แล้วกลับไปหา Gann Stonespire" },
        description = { "104:2048340009:272136500 N 389:1345996800:1879591059", "ทำตามแผนของ Khazgorm ก็คงประกอบระเบิดได้ไม่ยาก\n\nอ้า เรียบร้อยแล้ว\n\nเอาละ {name} ข้าจะมอบภารกิจพิเศษให้เจ้า นำระเบิดแท่งนี้ไปใช้ระเบิดเครื่องบินที่ Bael Modan\n\nเครื่องบินไม่ได้เป็นแค่ส่วนสำคัญของระบบงานที่นั่น แต่ยังเป็นอาวุธสงคราม ที่สำคัญยิ่งกว่านั้น มันเป็นสัญลักษณ์แห่งอำนาจและเป็นการดูหมิ่นความทรงจำของเผ่าข้า\n\nทำภารกิจอันกล้าหาญนี้ให้สำเร็จ ให้ข้าภูมิใจ แล้วเจ้าจะได้รับรางวัล" },
        progress = { "97:1095106950:1803469268", "เมื่อเครื่องบินของคนแคระถูกทำลาย ข้าคงได้ลิ้มรสหวานของการล้างแค้นเสียที" },
        completion = { "20:1921578502:569519135 N 108:2045515524:1121362938", "ทำได้ดี {name}! ขอให้ Thunder Bluff ยกย่องเจ้าในฐานะผู้พิทักษ์แผ่นดินศักดิ์สิทธิ์ของทอเรน และวีรชนแห่งเผ่าที่สูญสิ้น" },
        steps = { { "35:203591835:460543288", "ทำลายเครื่องบินของ Bael Modan" } },
    },
    [878] = { -- Tribes at War
        title = { "13:1554899810:82032806", "สงครามระหว่างเผ่า" },
        objective = { "149:2046915838:1614397261", "สังหาร Bristleback Water Seekers 6 คน, Bristleback Thornweavers 12 คน และ Bristleback Geomancers 12 คน แล้วกลับไปหา Mangletooth ที่ Camp Taurajo ใน Barrens" },
        description = { "479:550996322:1687145426", "เจ้าต้องโจมตีศัตรูของข้า <พ่นลมทางจมูก> ต้องช่วย Mangletooth กับ Razormane ด้วยการทำให้ Bristleback อ่อนแอ ทั้งสองเผ่าผูกพันกับวิญญาณอย่างลึกซึ้ง ผูกกับผืนดินและพลังของมัน <พ่นลมทางจมูก> มันให้ความแข็งแกร่งแก่เราทุกด้าน... โดยเฉพาะสงคราม\n\nถ้าอยากรู้ว่าใครทำให้ Thork <พ่นลมทางจมูก> กับ Horde ทุกข์ใจจริง ๆ ก็ช่วย Mangletooth! โจมตีผู้นำทางจิตวิญญาณของ Bristleback ทางเหนือ ทำให้มันอ่อนแอเพื่อ Razormane จะได้ปราบและปกครอง Barrens" },
        progress = { "87:1530983021:937900868 R 55:594075753:1992330507", "ข้อมูลเพิ่ม <พ่นลมทางจมูก> ให้ Horde เมื่อเจ้าฆ่าผู้รู้ของ Bristleback แล้ว {race} <พ่นลมทางจมูก> ก่อนหน้านั้นไม่ให้! Mangletooth ไม่ใช่คนโง่" },
        completion = { "90:1896203640:515708291 R 301:1556561721:1962145530", "ใช่ ใช่... เปี่ยมด้วยความยินดี เพราะในที่สุด <พ่นลมทางจมูก> Bristleback ก็รู้ความเจ็บปวดของเผ่าข้า {race} ข้าควรรู้สึกแบบนั้น แต่ <พ่นลมทางจมูก> กลับไม่ใช่เลย\n\nเจ้าช่วยเผ่าพ้อง แล้วพวกเขายกย่องเจ้า Mangletooth ช่วยเผ่าพ้อง แล้วพวกมันทำอะไร? หันหลังให้ข้า ลืมข้า ปล่อยข้าเน่าตายในกรง!\n\nข้ายังช่วยพวกมันทั้งที่ถูกขังหลังลูกกรง แต่พวกมันไม่ส่งใครมาช่วยข้าเลย!", variants = { { "399:1898505999:459616420", "ใช่ ใช่... เปี่ยมด้วยความยินดี เพราะในที่สุด <พ่นลมทางจมูก> Bristleback ก็รู้ความเจ็บปวดของเผ่าข้า สกายบอร์น ข้าควรรู้สึกแบบนั้น แต่ <พ่นลมทางจมูก> กลับไม่ใช่เลย\n\nเจ้าช่วยเผ่าพ้อง แล้วพวกเขายกย่องเจ้า Mangletooth ช่วยเผ่าพ้อง แล้วพวกมันทำอะไร? หันหลังให้ข้า ลืมข้า ปล่อยข้าเน่าตายในกรง!\n\nข้ายังช่วยพวกมันทั้งที่ถูกขังหลังลูกกรง แต่พวกมันไม่ส่งใครมาช่วยข้าเลย!" } } },
        objectiveLabels = {
            monster = { ["Bristleback Water Seeker slain"] = "ปราบ นักหาน้ำ Bristleback", ["Bristleback Thornweaver slain"] = "ปราบ ผู้ถักหนาม Bristleback", ["Bristleback Geomancer slain"] = "ปราบ ผู้ใช้เวทปฐพี Bristleback" },
        },
    },
    [850] = { -- Kolkar Leaders
        title = { "14:22495419:2134667633", "ผู้นำ Kolkar" },
        objective = { "64:859319047:2043046161", "นำ Barak's Head ไปให้ Regthar Deathgate ทางตะวันตกของ Crossroads" },
        description = { "417:1971763165:4199544", "เซนทอร์รังควานทอเรนมาหลายปี และช่วงหลังเซนทอร์ Kolkar ใน Barrens ก็กลายเป็นภัยร้ายแรง เดิมพวกมันต่างคนต่างอยู่ในดินแดนนี้ แต่มีผู้นำคนใหม่ ๆ ปรากฏขึ้นมารวบรวมพวกมัน\n\nเพื่อรักษาดินแดนที่เราครอบครอง ต้องกำจัดผู้นำเซนทอร์เหล่านี้\n\nนำศีรษะของ Barak Kodobane มาให้ข้า มันตั้งค่ายใกล้ Forgotten Pools ทางเหนือ\n\nปราบมันแล้วกลับมาหาข้า" },
        progress = { "7:989913233:66981971 N 34:457111024:102754045", "สวัสดี {name} ได้ Barak's Head มาให้ข้าหรือยัง?" },
        completion = { "11:534428891:784080240 N 172:1654846002:1402982181", "ดีมาก {name} เซนทอร์เป็นสิ่งมีชีวิตต่ำช้าและป่าเถื่อน แต่บางตัวก็มีไหวพริบและวิสัยทัศน์พอจะเป็นผู้นำ และพวกนั้นอันตรายที่สุด\n\nBarak เป็นเซนทอร์แบบนั้น ดีแล้วที่มันตาย" },
        required = { [5022] = { "15:205714155:255875244", "ศีรษะของ Kodobane" } },
        steps = { { "15:205714155:255875244", "ศีรษะของ Kodobane" } },
    },
    [97250] = { -- Wrongly Blamed, Justly Corrected
        title = { "32:1471809087:939449289", "กล่าวโทษผิด ต้องจัดการให้ถูก" },
        objective = { "131:1350752044:922760251", "สังหารทหาร Alliance ที่รุกเข้ามาใน Barrens บริเวณชายแดน Dustwallow Marsh แล้วกลับไปหา Grunt Logmar ที่ Camp Taurajo" },
        description = { "492:1123896401:568494113", "นักเดินทาง มีแผนจะไปทาง Dustwallow Marsh หรือ? ข้าได้ยินเสียงลือว่าทหารมนุษย์ไม่กี่คนตั้งกำลังที่ชายแดน กำลังโค่นเครื่องหมายเส้นทางที่ผู้บุกเบิกทอเรนของเราทิ้งไว้\n\nข่าวลือบอกว่าโรงเตี๊ยมยอดนิยมถูกไฟเผาจนราบ และตามนิสัย Alliance พวกเขาก็โยนความผิดให้ Horde ทันที! ข้าไม่รู้ว่าข้อกล่าวหาจริงหรือไม่ แต่การรุกเข้ามาบนแผ่นดินของเรา ต้องไม่ปล่อยไว้\n\nฆ่าก่อน สืบทีหลัง!" },
        completion = { "484:1643680027:732410996", "ข่าวลือเป็นจริงสินะ! ข้าคิดอยู่แล้ว ความตึงเครียดริมชายฝั่งตะวันออกเพิ่มมาสักพัก รู้ว่าคงเป็นแค่เรื่องของเวลาก่อนความขัดแย้งจะลามมาถึงดินแดนเรา\n\nแต่ข้ายังสงสัยว่าเรามีส่วนทำลายโรงเตี๊ยมหรือ พลเรือน Horde มากมายใช้เส้นทางนั้นค้าขายและเดินทาง ถ้ามีเวลา เจ้าลองสืบต่อก็ได้\n\nอย่างไรก็เถอะ สิ่งที่ทำวันนี้คือชัยชนะของ Horde และคำเตือนหนักแน่นถึง Alliance!" },
        progress = { "25:1191826390:723965917", "มีข่าวอะไรจากชายแดนไหม?" },
        objectiveLabels = {
            monster = { ["Encroaching Soldier slain"] = "ปราบ ทหารผู้รุกล้ำ", ["Outraged Pillager slain"] = "ปราบ ผู้ปล้นสะดมเดือดดาล" },
        },
    },
    [861] = { -- The Hunter's Way
        title = { "16:818027401:1536562427", "วิถีแห่งนักล่า" },
        objective = { "67:488711716:1718440085", "นำ Flatland Prowler Claws 4 ชิ้น ไปให้ Melor Stonehoof ใน Thunder Bluff" },
        description = { "430:1555393020:46862492 C 22:277174352:1880776344", "ข้าดูออกว่าเจ้าอยากสำรวจ ข้าก็เคยกระหายการเดินทางเช่นกัน...\n\nเดินทาง และล่า เพราะการล่าคือเกียรติสูงสุดของทอเรน\n\nหากอยากเดินตามวิถีนักล่าจริง ๆ Melor Stonehoof ชี้ทางให้เจ้าได้ เขาอยู่ใน Thunder Bluff บน Hunter's Rise\n\nเพื่อแสดงฝีมือกับความมุ่งมั่น จงนำกรงเล็บของ Flatland Prowlers แห่ง Mulgore ไปให้เขา พวกมันแข็งแกร่งและเจ้าเล่ห์ เป็นเหยื่อที่เหมาะกับ{class}ผู้เยาว์บนเส้นทางนักล่า" },
        progress = { "88:1866843338:1080174425", "สวัสดี ท่าทีของเจ้าบอกข้าได้หลายอย่าง เราสองคนมีเรื่องต้องติดต่อกันหรือ?" },
        completion = { "334:1720721441:1313114565", "Skorn Whitecloud เป็นทอเรนผู้ทรงปัญญา เขาล่ามาหลายต่อหลายปี แม้ร่างกายชรา แต่จิตวิญญาณยังลุกโชน เรารู้สึกเป็นเกียรติที่มีเขาอยู่ด้วย\n\nหาก Skorn ส่งเจ้ามาหาข้า เจ้าก็คงมีจิตวิญญาณนักล่าเช่นกัน และการเก็บกรงเล็บเหล่านี้มาได้ แสดงถึงฝีมือที่กำลังเติบโต\n\nบางทีเจ้าพร้อมเดินบนเส้นทางนั้นแล้ว" },
        required = { [5203] = { "21:699324666:1548269319", "กรงเล็บนักล่าแห่งที่ราบ" } },
        steps = { { "21:699324666:1548269319", "กรงเล็บนักล่าแห่งที่ราบ" } },
    },
    [9033] = { -- Echoes of War
        title = { "13:1779672836:602981632", "เสียงสะท้อนแห่งสงคราม" },
        objective = { "188:690467742:1693001747", "Commander Eligor Dawnbringer ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการให้เจ้าสังหาร Living Monstrosities 5 ตัว, Stoneskin Gargoyles 5 ตัว, Deathknight Captains 8 คน และ Venom Stalkers 3 ตัว" },
        description = { "480:2142806888:324140357", "ห้าปีแล้วนับจากสงครามครั้งก่อน...\n\nผู้คนหลายหมื่นสูญเสียชีวิต แล้วได้อะไร? ภัยคุกคามไม่เคยถูกกำจัดจนสิ้น\n\nบัดนี้ Lich King เคลื่อนไหวอีกครั้ง... Kel'Thuzad ลูกสมุนที่คอยรับคำสั่ง กำลังรวบรวมกำลังเพื่อโจมตีแผ่นดินเราอีกหน\n\nเราจะไม่ยอม! พิสูจน์ความทุ่มเท พิสูจน์ว่าเจ้าพร้อมเสี่ยงชีวิตและร่างกายเพื่อหยุดความบ้าคลั่งนี้ แล้วกำลังร่วมของ Dawn กับ Crusade จะพร้อมช่วยตามคำเรียกของเจ้า\n\nเข้าสู่ Naxxramas แล้วทำลาย Scourge ที่อยู่ภายใน..." },
        progress = { "59:1002021989:135571051", "หน้าที่ เกียรติ ความทุ่มเท... คำเหล่านี้มีความหมายอย่างไรสำหรับเจ้า?" },
        completion = { "92:1653519535:1262310905", "ทำได้ดีมาก! เจ้าจะได้รับการตอบแทนผ่านความช่วยเหลือของเหล่าชายหญิงที่ Light's Hope" },
    },
    [9034] = { -- Dreadnaught Breastplate
        title = { "23:114512526:1015080380", "เกราะอก Dreadnaught" },
        objective = { "219:1201791090:1104964340", "นำ Desecrated Breastplate 1 ชิ้น, Wartorn Plate Scraps 25 ชิ้น, Arcanite Bars 4 แท่ง และ Nexus Crystals 2 ก้อน ไปให้ Korfax ที่ Light's Hope Chapel ใน Eastern Plaguelands เพื่อสร้าง Dreadnaught Breastplate" },
        description = { "199:1717982833:290730536", "ระหว่างต่อสู้กับ Scourge ใน Naxxramas หากเจ้าพบยุทโธปกรณ์แปดเปื้อนและเศษเกราะแผ่นที่ผ่านศึก จงนำกลับมาให้ข้า แล้วข้าจะสร้างเกราะแบบที่วีรชนสวมใส่ให้เจ้า" },
        progress = { "68:1941300067:1592408446", "ของที่ต้องใช้ในภารกิจยังไม่ครบ ไปหามาให้ครบก่อน!" },
        completion = { "9:660859213:320951857 N 85:1874655897:1801493319", "ยอดเยี่ยม {name}!\n\nเจ้านำของมาครบตามที่ข้าขอแล้ว ตอนนี้ข้าสร้าง Dreadnaught Breastplate ให้ได้" },
        required = { [12360] = { "12:582063918:1116898133", "แท่งอาร์คาไนต์" }, [20725] = { "13:108518413:119122757", "ผลึกเน็กซัส" }, [22349] = { "22:1452805252:991774707", "เกราะอกแผ่นแปดเปื้อน" }, [22375] = { "19:306861227:825772723", "เศษเกราะแผ่นชำรุดจากสงคราม" } },
        objectiveLabels = {
            item = { ["Arcanite Bar"] = "แท่งอาร์คาไนต์", ["Nexus Crystal"] = "ผลึกเน็กซัส", ["Desecrated Breastplate"] = "เกราะอกแผ่นแปดเปื้อน", ["Wartorn Plate Scrap"] = "เศษเกราะแผ่นชำรุดจากสงคราม" },
        },
    },
    [9036] = { -- Dreadnaught Legplates
        title = { "21:1052831180:1541767245", "สนับขาเกราะ Dreadnaught" },
        objective = { "217:600995979:1608587419", "นำ Desecrated Legplates 1 ชิ้น, Wartorn Plate Scraps 20 ชิ้น, Arcanite Bars 4 แท่ง และ Cured Rugged Hides 3 ผืน ไปให้ Korfax ที่ Light's Hope Chapel ใน Eastern Plaguelands เพื่อสร้าง Dreadnaught Legplates" },
        description = { "199:1717982833:290730536", "ระหว่างต่อสู้กับ Scourge ใน Naxxramas หากเจ้าพบยุทโธปกรณ์แปดเปื้อนและเศษเกราะแผ่นที่ผ่านศึก จงนำกลับมาให้ข้า แล้วข้าจะสร้างเกราะแบบที่วีรชนสวมใส่ให้เจ้า" },
