        completion = { "9:660859213:320951857 N 83:1285139774:309759225", "ยอดเยี่ยม {name}!\n\nเจ้านำของมาครบตามที่ข้าขอแล้ว ตอนนี้ข้าสร้าง Dreadnaught Legplates ให้ได้" },
        required = { [12360] = { "12:582063918:1116898133", "แท่งอาร์คาไนต์" }, [15407] = { "17:1544083521:956369053", "หนังหนาฟอกแล้ว" }, [22352] = { "20:404304813:894304766", "เกราะขาแผ่นแปดเปื้อน" }, [22375] = { "19:306861227:825772723", "เศษเกราะแผ่นชำรุดจากสงคราม" } },
