        objective = { "211:1220832187:967852567", "นำ Desecrated Circlet 1 ชิ้น, Wartorn Cloth Scraps 15 ชิ้น, Mooncloth 3 ผืน และ Nexus Crystals 3 ก้อน ไปให้ Father Inigo Montoy ที่ Light's Hope Chapel ใน Eastern Plaguelands เพื่อสร้าง Circlet of Faith" },
        description = { { "357:590099315:806103660", "358:838038070:253209522" }, "<บาทหลวง Montoy ทำท่าทางประหลาดกลางอากาศตรงหน้าเจ้า>\n\nผู้เยาว์ผู้ได้รับพร พบอาภรณ์ของผู้ล่วงลับหรือยัง? วิญญาณน่าสงสารที่สิ้นลมหายใจในสนามรบ ถูกพรากทุกสิ่งแม้แต่ศักดิ์ศรี\n\nนำสิ่งที่หลงเหลืออันแปดเปื้อนของผู้จากไปมาให้ข้า พร้อมวัตถุดิบชำระมลทิน แล้วเจ้าจะรู้จักศรัทธา" },
        progress = { "40:1507520833:2004243411", "นำวัตถุดิบมาให้ข้าหรือยัง ลูกเอ๋ย?" },
        completion = { "9:660859213:320951857 N 78:873227241:1715975783", "ยอดเยี่ยม {name}!\n\nเจ้านำของมาครบตามที่ข้าขอแล้ว ตอนนี้ข้าสร้าง Circlet of Faith ให้ได้" },
        required = { [14342] = { "9:1533651162:2094570343", "ผ้าแสงจันทร์" }, [20725] = { "13:108518413:119122757", "ผลึกเน็กซัส" }, [22367] = { "18:1458392680:1405815098", "วงรัดศีรษะแปดเปื้อน" }, [22376] = { "19:1664016980:129984276", "เศษผ้าชำรุดจากสงคราม" } },
        objectiveLabels = {
            item = { ["Mooncloth"] = "ผ้าแสงจันทร์", ["Nexus Crystal"] = "ผลึกเน็กซัส", ["Desecrated Circlet"] = "วงรัดศีรษะแปดเปื้อน", ["Wartorn Cloth Scrap"] = "เศษผ้าชำรุดจากสงคราม" },
        },
    },
    [9114] = { -- Shoulderpads of Faith
        title = { "21:941024025:1435825604", "แผ่นรองไหล่แห่งศรัทธา" },
        objective = { "223:1136992638:995675354", "นำ Desecrated Shoulderpads 1 ชิ้น, Wartorn Cloth Scraps 12 ชิ้น, Mooncloth 2 ผืน และ Cured Rugged Hides 3 ผืน ไปให้ Father Inigo Montoy ที่ Light's Hope Chapel ใน Eastern Plaguelands เพื่อสร้าง Shoulderpads of Faith" },
        description = { { "357:590099315:806103660", "358:838038070:253209522" }, "<บาทหลวง Montoy ทำท่าทางประหลาดกลางอากาศตรงหน้าเจ้า>\n\nผู้เยาว์ผู้ได้รับพร พบอาภรณ์ของผู้ล่วงลับหรือยัง? วิญญาณน่าสงสารที่สิ้นลมหายใจในสนามรบ ถูกพรากทุกสิ่งแม้แต่ศักดิ์ศรี\n\nนำสิ่งที่หลงเหลืออันแปดเปื้อนของผู้จากไปมาให้ข้า พร้อมวัตถุดิบชำระมลทิน แล้วเจ้าจะรู้จักศรัทธา" },
        progress = { "40:1507520833:2004243411", "นำวัตถุดิบมาให้ข้าหรือยัง ลูกเอ๋ย?" },
        completion = { "25:1047620912:620402240 N 63:343606006:1271896894", "อาภรณ์พร้อมแล้ว {name} จงใช้เปลวไฟอันชอบธรรมของเจ้าลงทัณฑ์ผู้ที่คิดทำร้ายโลกเรา" },
        required = { [14342] = { "9:1533651162:2094570343", "ผ้าแสงจันทร์" }, [15407] = { "17:1544083521:956369053", "หนังหนาฟอกแล้ว" }, [22368] = { "23:1474103193:2094480279", "แผ่นรองไหล่แปดเปื้อน" }, [22376] = { "19:1664016980:129984276", "เศษผ้าชำรุดจากสงคราม" } },
        objectiveLabels = {
            item = { ["Mooncloth"] = "ผ้าแสงจันทร์", ["Cured Rugged Hide"] = "หนังหนาฟอกแล้ว", ["Desecrated Shoulderpads"] = "แผ่นรองไหล่แปดเปื้อน", ["Wartorn Cloth Scrap"] = "เศษผ้าชำรุดจากสงคราม" },
        },
    },
