        progress = { "40:1507520833:2004243411", "นำวัตถุดิบมาให้ข้าหรือยัง ลูกเอ๋ย?" },
        completion = { "25:1047620912:620402240 N 63:343606006:1271896894", "อาภรณ์พร้อมแล้ว {name} จงใช้เปลวไฟอันชอบธรรมของเจ้าลงทัณฑ์ผู้ที่คิดทำร้ายโลกเรา" },
