    [9120] = { -- The Fall of Kel'Thuzad
        title = { "22:139421844:1427456498", "การล่มสลายของ Kel'Thuzad" },
        objective = { "84:980033046:1032429050", "นำ Phylactery of Kel'Thuzad ไปที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { "344:1465301956:1989759324", "ภาชนะผนึกวิญญาณคือสิ่งเดียวที่เหลืออยู่ของนายแห่ง Naxxramas วิจารณญาณที่ดีกว่าของเจ้าบอกให้ทำลายมัน เพื่อไม่ให้ลิชกลับคืนร่างได้อีก โชคดีที่เจ้าแทบไม่เคยฟังเสียงแห่งเหตุผลในใจ\n\nใครสักคนที่ Light's Hope คงจ่ายงามสำหรับวัตถุชิ้นนี้ ใครจะสนว่า Kel'Thuzad จะฟื้นพลังกลับมาจนเต็ม?" },
        progress = { "46:1270356979:449662699", "แสงสว่างโปรดช่วย! เจ้าเด็กน้อย เจ้าถือของอัปมงคลอะไรอยู่?" },
        completion = { "197:1708893687:1972135533", "ตลอดชีวิตของข้า ไม่เคยคิดเลยว่าจะได้เห็นสิ่งนี้...\n\n<Father Montoy ดูเหมือนกำลังน้ำลายสอ>\n\nโอ้ ใช่แล้ว เจ้าจะได้รับรางวัล เจ้าหนุ่มเอ๋ย เจ้าจะได้รับรางวัลอย่างงาม ส่งมันมาให้ข้า เดี๋ยวนี้!" },
    },
    [9229] = { -- The Fate of Ramaladni
        title = { "21:336192253:240250208", "ชะตาของ Ramaladni" },
        objective = { "50:1580860506:536397332", "เข้าสู่ Naxxramas แล้วค้นหาชะตากรรมของ Ramaladni" },
        description = { "192:194542721:310088346 N 303:1485228082:1818486940", "Ramaladni เป็นนักรบแห่งภราดรภาพ เป็นศิษย์ของ Highlord Mograine ตั้งแต่ก่อนมี Dawn เสียอีก! เมื่อข่าวความตายของ Mograine ไปถึง ความเกลียดชังและโทสะก็ครอบงำเขา\n\nจงเข้าใจ {name} เมื่อความโกรธและการล้างแค้นกุมบังเหียน คนคนหนึ่งก็เลิกเป็นตัวเอง กลับกลายเป็นตัวแทนของอารมณ์ที่ควบคุมตน และนั่นทำให้ Ramaladni ผู้เปี่ยมจิตวิญญาณแห่งการแก้แค้น เข้า Naxxramas เพื่อทวงแค้น... แล้วไม่กลับมาอีก\n\nเข้าสู่ Naxxramas แล้วค้นหาว่าเกิดอะไรกับ Ramaladni" },
        progress = { "22:2021486350:981259478", "มีข่าว Ramaladni บ้างไหม?" },
        completion = { "182:1121979828:1710051489", "แหวนของเขา! แต่มันพังแล้ว ไม่พบหลักฐานอื่นของ Ramaladni เลยหรือ?\n\n<Korfax ทำหน้าเคร่งเครียด>\n\nนี่ไม่ใช่ลางดีสำหรับ Ramaladni แต่แหวน... อาจยังกู้คืนได้" },
        required = { [22708] = { "17:1056242147:419674981", "ชะตากรรมของ Ramaladni" } },
        objectiveLabels = {
            item = { ["Fate of Ramaladni"] = "ชะตากรรมของ Ramaladni" },
        },
    },
    [9230] = { -- Ramaladni's Icy Grasp
        title = { "21:792534362:607147146", "เงื้อมมือเยือกแข็งของ Ramaladni" },
        objective = { "130:595409033:1066979359", "Korfax ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการ Frozen Rune 1 ชิ้น, Blue Sapphire 1 เม็ด และ Arcanite Bar 1 แท่ง" },
        description = { "52:487783716:1770652341 N 265:1430886184:2091991064", "ซ่อมแหวนวงนี้คงท้าทายไม่น้อย {name} เพราะมันทำจากอักขระรูนที่ก่อตัวในสิ่งก่อสร้างของ Scourge เช่น Naxxramas ต้องใช้วัสดุเพิ่มเติมด้วย แต่สิ่งที่ควรใส่ใจที่สุดคือหารูนเยือกแข็งเหล่านั้น นำของที่ข้าต้องการมา แล้วข้าจะคืนความรุ่งเรืองเดิมให้แหวน" },
        progress = { "54:365753228:2029918215", "น่าจะหารูนเยือกแข็งได้ภายใน Naxxramas" },
        completion = { "75:1855364899:899810307", "ต่อให้ Ramaladni ทำเองก็ไม่ดีกว่านี้แล้ว! นี่แหวน ตามที่สัญญา" },
        required = { [12360] = { "12:582063918:1116898133", "แท่งอาร์คาไนต์" }, [12361] = { "13:366433083:1620162146", "ไพลินสีน้ำเงิน" }, [22682] = { "11:1656972409:1237857504", "รูนเยือกแข็ง" } },
        objectiveLabels = {
            item = { ["Arcanite Bar"] = "แท่งอาร์คาไนต์", ["Blue Sapphire"] = "ไพลินสีน้ำเงิน", ["Frozen Rune"] = "รูนเยือกแข็ง" },
        },
    },
    [9232] = { -- The Only Song I Know...
        title = { "23:26224083:467105049", "เพลงเดียวที่ข้ารู้จัก..." },
        objective = { "163:231041588:928779379", "Craftsman Wilhelm ที่ Light's Hope Chapel ใน Eastern Plaguelands ต้องการ Frozen Runes 2 ชิ้น, Essence of Water 2 ชิ้น, Blue Sapphires 2 เม็ด และทอง 30 เหรียญ" },
        description = { "414:1032804602:1364285790", "คิดว่าตัวเองเป็นวีรชนของ Dawn สินะ? ข้าเห็นทหารที่เก่งที่สุดของเราถูกลูกกระจ๊อก Kel'Thuzad ถล่มมาแล้ว! คนไม่รู้เรื่องอย่างเจ้าจะไปได้สักแค่ไหนใน Naxxramas?\n\n<Wilhelm ถอนหายใจ>\n\nช่างเถอะ ข้ามีทางเลือกอะไร? เจ้าดีที่สุดที่หาได้แล้ว ข้าคงต้องช่วย\n\nOmarion ทิ้งสูตรไว้ให้ข้าสูตรเดียว เป็นเพลงเดียวที่ข้ารู้จัก... ข้าทำกางเกงนี้ได้หลายแบบ เจ้าแค่ต้องหาวัตถุดิบมา" },
        progress = { "39:1349318746:46814061", "เจ้าไม่ได้พบ Omarion บ้างหรือ?" },
        completion = { "81:1101732168:1717079769 C 42:20410449:33765749", "<Wilhelm ปาดเหงื่อจากหน้าผาก>\n\nงานหนักจริง! ใช้กางเกงให้คุ้มล่ะ {class} อย่างน้อยตอนนี้เจ้าจะได้ตายในกางเกงสะอาด" },
        required = { [7080] = { "16:634100106:1080169506", "แก่นธาตุน้ำ" }, [12361] = { "13:366433083:1620162146", "ไพลินสีน้ำเงิน" }, [22682] = { "11:1656972409:1237857504", "รูนเยือกแข็ง" } },
        objectiveLabels = {
            item = { ["Essence of Water"] = "แก่นธาตุน้ำ", ["Blue Sapphire"] = "ไพลินสีน้ำเงิน", ["Frozen Rune"] = "รูนเยือกแข็ง" },
        },
    },
    [9233] = { -- Omarion's Handbook
        title = { "18:59451055:1651735637", "คู่มือของ Omarion" },
        objective = { "95:970566855:483922929", "นำ Omarion's Handbook ไปให้ Craftsman Wilhelm ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { "487:1971371088:340281534", "Wilhelm\n\nถ้าเจ้าอ่านจดหมายนี้ ข้าคงตายแล้ว ในที่สุด ข้าอยากให้รู้ว่าความคิดสุดท้ายของข้าวนเวียนถึงเจ้าและความไม่เอาไหนด้านวิชาชีพ น่าเสียดายว่าคนถือคู่มือนี้มาฝีมืองานช่างแย่ยิ่งกว่าเจ้าเสียอีก\n\nเรื่องหนังสือ นี่คือสูตรที่เหลือของข้า สร้างสิ่งที่คนถือหนังสือขอให้เขาด้วย ข้ามั่นใจว่าเจ้าต้องคิดค่าบริการแพงลิบ เพราะถึงอย่างไรเจ้าก็เป็นไอ้ตัวแสบ\n\nด้วยความดูแคลน\n\nOmarion" },
        progress = { "61:1372133886:1960263893", "นั่นใช่สิ่งที่ข้าคิดหรือเปล่า?\n\n<Wilhelm ดูเหมือนกำลังน้ำลายสอ>" },
        completion = { "154:922912281:2056495964 N 86:526266252:2423908", "ตอนเขียนนี่เขาต้องเพี้ยนไปแล้วแน่ ๆ! ข้ากับ Omarion สนิทกันจะตาย!\n\nอย่างไรก็เถอะ นี่เปิดทางเลือกใหม่ให้จริง ๆ {name} ตอนนี้ข้าสร้างของเพิ่มได้อีก แน่นอนว่าต้องมีค่าธรรมเนียมเล็กน้อยกับค่าวัตถุดิบ" },
    },
