    [8544] = { -- Conqueror's Spaulders
        title = { "21:41612037:722989936", "เกราะไหล่ผู้พิชิต" },
        objective = { "207:1475123853:1166701957", "นำ Qiraji Bindings of Command, Idols of Night 2 ชิ้น, Stone Scarabs 5 ชิ้น และ Clay Scarabs 5 ชิ้นไปให้ Andorgos ใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Neutral ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "290:125012629:1426698254", "ในหมู่พวกเรามีคำกล่าวว่า เกราะไหล่อันวิจิตรที่เผ่าพันธุ์มรรตัยสวมใส่นั้น มีจุดเริ่มต้นจากความพยายามเลียนแบบปีกมังกร\n\nนำเครื่องพันธนาการที่ผู้นำระดับสูงสุดของคิราจิสวมใส่มาให้ข้า แล้วข้าจะดัดแปลงมันเป็นเกราะไหล่ที่น่าสะพรึงกลัวยิ่งกว่าปีกของเนฟาเรียนเสียอีก!" },
        progress = { "44:294661982:1846726943", "เจ้ารวบรวมส่วนประกอบที่ข้าต้องการมาแล้วหรือ?" },
        completion = { "209:1930867586:1664595477", "ข้าใช้วัตถุดิบที่เจ้านำมาและเกล็ดของศัตรูคิราจิที่พ่ายแพ้ สร้างเกราะไหล่นี้ให้เจ้า มรรตัยเอ๋ย ขอให้มันมอบการคุ้มครองที่เจ้าต้องการ และขอให้เพียงได้เห็นมัน ศัตรูของเราก็หวาดกลัว" },
        required = { [20858] = { "12:1980262597:1671036142", "แมลงปีกแข็งหิน" }, [20863] = { "11:63070098:517410384", "แมลงปีกแข็งดินเหนียว" }, [20875] = { "13:90065905:416965156", "รูปเคารพแห่งราตรี" }, [20928] = { "26:1677574703:2025389490", "ผ้าพันข้อมือบัญชาการแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Stone Scarab"] = "แมลงปีกแข็งหิน", ["Clay Scarab"] = "แมลงปีกแข็งดินเหนียว", ["Idol of Night"] = "รูปเคารพแห่งราตรี", ["Qiraji Bindings of Command"] = "ผ้าพันข้อมือบัญชาการแห่ง Qiraji" },
        },
    },
    [8556] = { -- Signet of Unyielding Strength
        title = { "29:2123551824:2133511526", "แหวนตราพลังอันไม่ย่อท้อ" },
        objective = { "208:1371070306:1634238587", "นำ Qiraji Magisterial Ring 1 วง, Lambent Idols 2 ชิ้น, Bronze Scarabs 5 ชิ้น และ Ivory Scarabs 5 ชิ้นไปให้ Windcaller Yessendra ใน Silithus คุณต้องมีชื่อเสียงกับ Cenarion Circle ถึงระดับ Honored ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "382:408874008:675528757 C 1:46:46", "ร่ำลือกันว่าแหวนที่นายทหารคิราจิสวมใส่มอบพลังอันน่าเกรงขามให้พวกมัน ตามทฤษฎีแล้ว เราน่าจะเปลี่ยนอัญมณีแปดเปื้อนที่ประดับแหวนเป็นวัตถุดิบที่บริสุทธิ์กว่า เพื่อสร้างแหวนแบบที่ไม่แปดเปื้อนขึ้นมาได้\n\nอัญมณีที่ประดับรูปเคารพคิราจิน่าจะใช้ได้ดี เพราะมีคุณภาพสูงกว่า\n\nนำแหวนกับรูปเคารพมาให้ข้า แล้วข้าจะสร้างแหวนอันทรงพลังให้เจ้า {class}" },
        progress = { "41:1554235813:2016111458 N 1:63:63", "เจ้านำแหวนกับวัตถุดิบมาให้ข้าแล้วหรือ {name}?" },
        completion = { "90:2093406466:1951758598", "ข้าจะเปลี่ยนอัญมณีบนแหวนให้เจ้า แล้วเจ้าจะพบว่าผลที่ได้... น่าพอใจกว่าเดิมมาก" },
        required = { [20861] = { "13:930087217:500728621", "แมลงปีกแข็งสำริด" }, [20865] = { "12:1202006906:852939774", "แมลงปีกแข็งงาช้าง" }, [20868] = { "12:2029827235:226101895", "รูปเคารพเรืองแสง" }, [20884] = { "23:137715739:8625816", "แหวนทรงอำนาจแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Bronze Scarab"] = "แมลงปีกแข็งสำริด", ["Ivory Scarab"] = "แมลงปีกแข็งงาช้าง", ["Lambent Idol"] = "รูปเคารพเรืองแสง", ["Qiraji Magisterial Ring"] = "แหวนทรงอำนาจแห่ง Qiraji" },
        },
    },
    [8557] = { -- Drape of Unyielding Strength
        title = { "28:417206866:568494724", "ผ้าคลุมพลังอันไม่ย่อท้อ" },
        objective = { "195:538680161:2079619763", "นำ Qiraji Martial Drape 1 ผืน, Onyx Idols 2 ชิ้น, Silver Scarabs 5 ชิ้น และ Bone Scarabs 5 ชิ้นไปให้ Keyl Swiftclaw ใน Silithus คุณต้องมีชื่อเสียงกับ Cenarion Circle ถึงระดับ Revered ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "62:1296950806:1567247921 N 92:378614025:798951733 C 180:1892738039:407571941", "ข้าดีใจที่ได้ยินว่าเจ้าช่วยพวกเราบุกอันคิราจ {name} ข้าสามารถทำเครื่องป้องกันที่จะช่วยเจ้าต่อสู้กับศัตรูของเราได้ {class}\n\nข้าต้องใช้ผ้าคลุมคิราจิ ซึ่งแน่นอนว่าข้าจะปรับขนาดให้เจ้า ข้าต้องใช้รูปเคารพกับสคารับด้วย เพื่อนำมาทำเข็มกลัดที่เหมาะสม\n\nข้ารับรองว่าเจ้าจะไม่ผิดหวัง" },
        progress = { "43:375608774:328096588 N 1:63:63", "เจ้านำวัตถุดิบสำหรับทำผ้าคลุมมาแล้วหรือ {name}?" },
        completion = { "53:1611837331:681358311 N 55:1116846262:1257260049", "อา ใช่แล้ว... ผ้าผืนนี้ไร้ที่ติ\n\nรับผ้าคลุมนี้ไป {name} ขอให้มันปกป้องเจ้าจากเวทมนตร์ชั่วร้ายของคิราจิ" },
        required = { [20860] = { "13:408277756:1351227957", "แมลงปีกแข็งเงิน" }, [20864] = { "11:903649135:528580122", "แมลงปีกแข็งกระดูก" }, [20867] = { "9:1123472226:1477929075", "รูปเคารพโอนิกซ์" }, [20885] = { "20:1525985970:1497237199", "ผ้าคลุมนักรบแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Silver Scarab"] = "แมลงปีกแข็งเงิน", ["Bone Scarab"] = "แมลงปีกแข็งกระดูก", ["Onyx Idol"] = "รูปเคารพโอนิกซ์", ["Qiraji Martial Drape"] = "ผ้าคลุมนักรบแห่ง Qiraji" },
        },
    },
    [8558] = { -- Sickle of Unyielding Strength
        title = { "29:487579426:1593390561", "เคียวพลังอันไม่ย่อท้อ" },
        objective = { "197:176590820:1013369602", "นำ Qiraji Spiked Hilt 1 ชิ้น, Alabaster Idols 2 ชิ้น, Crystal Scarabs 5 ชิ้น และ Stone Scarabs 5 ชิ้นไปให้ Warden Haro ใน Silithus คุณต้องมีชื่อเสียงกับ Cenarion Circle ถึงระดับ Exalted ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "341:377795636:5696811 N 73:768730098:865440484", "คิราจิและสมุนของมันใช้อาวุธและอุปกรณ์ที่ทำจากวัตถุดิบหายากชั้นเลิศ ทั้งกระดูกของสิ่งมีชีวิตโบราณขนาดมหึมา อัญมณีจากส่วนลึกของแผ่นดิน และโลหะบริสุทธิ์แข็งแกร่ง\n\nเพียงเห็นวัตถุของคิราจิ ข้าก็อยากนำมันมาทุบและหลอมเพื่อฝึกฝนงานช่างแล้ว จงพิสูจน์ความภักดีของเจ้าต่อสภา {name} แล้วข้าจะสร้างอาวุธอันทรงพลังให้เจ้าจากวัตถุดิบชั้นเลิศของคิราจิ" },
        progress = { "43:889427335:1508720839 N 1:63:63", "เจ้านำส่วนประกอบที่ข้าต้องการมาให้แล้วหรือ {name}?" },
        completion = { "18:366880880:1038443585 C 73:1248716374:313018554 N 58:673470490:406183982", "เจ้าทำได้ดี {class} ด้ามอาวุธนี้เป็นผลงานชั้นครู... สมดุลของมันสมบูรณ์แบบ\n\nรับอาวุธของเจ้าไป {name} จงใช้อย่างมั่นใจและปราบศัตรูของเราให้สิ้น!" },
        required = { [20858] = { "12:1980262597:1671036142", "แมลงปีกแข็งหิน" }, [20862] = { "14:574699288:1249937239", "แมลงปีกแข็งผลึก" }, [20873] = { "14:1552874940:1249896239", "รูปเคารพอะลาบาสเตอร์" }, [20886] = { "18:740788201:1620780867", "ด้ามอาวุธติดหนามแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Stone Scarab"] = "แมลงปีกแข็งหิน", ["Crystal Scarab"] = "แมลงปีกแข็งผลึก", ["Alabaster Idol"] = "รูปเคารพอะลาบาสเตอร์", ["Qiraji Spiked Hilt"] = "ด้ามอาวุธติดหนามแห่ง Qiraji" },
        },
    },
    [8559] = { -- Conqueror's Greaves
        title = { "19:1376920379:1809648782", "สนับเท้าผู้พิชิต" },
        objective = { "187:1827998873:1552488173", "นำ Qiraji Bindings of Command, Idols of War 2 ชิ้น, Ivory Scarabs 5 ชิ้น และ Gold Scarabs 5 ชิ้นไปให้ Kandrostrasz ใน Ahn'Qiraj เควสนี้กำหนดให้มีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Neutral ด้วย" },
        description = { "300:749657029:454758845", "เวทมนตร์คิราจิทรงพลังและเก่าแก่ คิราจิที่แข็งแกร่งที่สุดครอบครองอุปกรณ์ทรงอานุภาพจนแม้แต่มังกรยังต้องยั้งคิด\n\nนำเครื่องพันธนาการบัญชาการของคิราจิกับส่วนประกอบเล็กน้อยอื่น ๆ มาให้ข้า แล้วข้าจะสร้างรองเท้าอันทรงพลังให้เจ้า\n\nเจ้าจะพบว่ามันมีประโยชน์ในการต่อสู้กับศัตรู" },
        progress = { "39:1894342980:601594342 N 1:63:63", "เจ้าได้ของที่ข้าขอมาแล้วหรือ {name}?" },
        completion = { "18:366880880:1038443585 N 124:2105041201:105126420", "เจ้าทำได้ดี {name} เจ้าพิสูจน์แล้วว่าไม่ใช่มรรตัยธรรมดา\n\nข้ามอบสิ่งนี้ให้ด้วยความมั่นใจว่ามันจะช่วยเจ้าบดขยี้คิราจิอันชั่วร้าย" },
        required = { [20859] = { "11:289690320:1184940294", "แมลงปีกแข็งทอง" }, [20865] = { "12:1202006906:852939774", "แมลงปีกแข็งงาช้าง" }, [20882] = { "11:226887665:1472544842", "รูปเคารพแห่งสงคราม" }, [20928] = { "26:1677574703:2025389490", "ผ้าพันข้อมือบัญชาการแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Gold Scarab"] = "แมลงปีกแข็งทอง", ["Ivory Scarab"] = "แมลงปีกแข็งงาช้าง", ["Idol of War"] = "รูปเคารพแห่งสงคราม", ["Qiraji Bindings of Command"] = "ผ้าพันข้อมือบัญชาการแห่ง Qiraji" },
        },
    },
    [8560] = { -- Conqueror's Legguards
        title = { "21:2092743216:785258669", "เกราะขาผู้พิชิต" },
        objective = { "206:972195503:971857701", "นำ Ouro's Intact Hide, Idols of Death 2 ชิ้น, Bronze Scarabs 5 ชิ้น และ Ivory Scarabs 5 ชิ้นไปให้ Kandrostrasz ภายใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Friendly ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "495:154690919:1100952960", "เจ้าอยากพิสูจน์คุณค่าของตนต่อเผ่าพันธุ์ข้าหรือ มรรตัย? ได้สิ บางทีเราอาจช่วยเหลือกันได้\n\nอูโร หนอนทรายโบราณ เป็นสิ่งมีชีวิตที่มีพลังระดับตำนาน ว่ากันว่าเทพโบราณเป็นผู้สร้างมันขึ้นมาเอง เพื่อเย้ยหยันชีวิต\n\nหนังของมันผิดธรรมชาติ... หนาจนแทบไม่มีสิ่งใดเจาะผ่านได้ แต่ก็ยืดหยุ่นพอให้มันเคลื่อนไหวได้รวดเร็วและคล่องแคล่วราวกับสิ่งมีชีวิตที่ตัวเล็กกว่ามาก\n\nนำตัวอย่างหนังของมันกับส่วนประกอบเล็กน้อยอื่น ๆ มาให้ข้า แล้วข้าจะสร้างเกราะขาอันทรงพลังให้เจ้า" },
        progress = { "40:1457140512:689795344 N 1:63:63", "เจ้านำส่วนประกอบที่ข้าต้องการมาแล้วหรือ {name}?" },
        completion = { "268:799780:835810284", "ใช่แล้ว... หนังของหนอนจะเป็นชั้นป้องกันชั้นเยี่ยม เมื่อนำมารวมกับชิ้นส่วนที่แข็งแกร่งที่สุดของคิราจิที่เรากำจัดระหว่างทางมาที่นี่ ก็น่าจะได้เกราะอันยอดเยี่ยม ขอให้มันช่วยเจ้ารับมือความสยดสยองเกินบรรยายที่รออยู่ภายใน!" },
        required = { [20861] = { "13:930087217:500728621", "แมลงปีกแข็งสำริด" }, [20865] = { "12:1202006906:852939774", "แมลงปีกแข็งงาช้าง" }, [20876] = { "13:1494226888:1757839434", "รูปเคารพแห่งความตาย" }, [20927] = { "18:960421714:149426513", "หนังของ Ouro ที่ยังสมบูรณ์" } },
        objectiveLabels = {
            item = { ["Bronze Scarab"] = "แมลงปีกแข็งสำริด", ["Ivory Scarab"] = "แมลงปีกแข็งงาช้าง", ["Idol of Death"] = "รูปเคารพแห่งความตาย", ["Ouro's Intact Hide"] = "หนังของ Ouro ที่ยังสมบูรณ์" },
        },
    },
    [8561] = { -- Conqueror's Crown
        title = { "17:1751095474:2087616642", "มงกุฎผู้พิชิต" },
        objective = { "203:1427863094:485993477", "นำ Vek'nilash's Circlet, Idols of the Sun 2 ชิ้น, Stone Scarabs 5 ชิ้น และ Crystal Scarabs 5 ชิ้นไปให้ Andorgos ใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Friendly ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "392:2075715828:514145168 N 49:960988403:390814438", "จักรพรรดิแฝด... เสียงกระซิบที่ไม่หยุดหย่อนของพวกมันกำลังกัดกร่อนสติของข้าทีละน้อย พวกมันเยาะเย้ยข้า เพราะรู้ว่าข้าไม่อาจก้าวลึกเข้าไปในอาณาเขตของพวกมันเพื่อช่วยอารีกอส พี่น้องของข้าได้\n\nในนิมิต ข้าเห็นใบหน้าอัปลักษณ์ของพวกมันประดับด้วยมงกุฎอันทรงพลัง แต่ข้าจะต้องได้แก้แค้น... ข้าจะเปลี่ยนสัญลักษณ์แห่งอำนาจคิราจิเหล่านี้ให้เหมาะกับการใช้งานของเรา\n\nนำส่วนประกอบที่ข้าต้องการมา {name} แล้วข้าจะมอบเครื่องสวมศีรษะที่มีพลังหาสิ่งใดเทียบให้เจ้า" },
        progress = { "45:101434375:2078642228 N 1:63:63", "เจ้านำส่วนประกอบที่ข้าขอมาให้แล้วหรือ {name}?" },
        completion = { "237:1612642284:1195697987", "เจ้าทำสำเร็จแล้ว! เสียงกระซิบจากจักรพรรดิแฝดเงียบลงแล้ว\n\nรับสิ่งนี้เป็นรางวัล เพียงเห็นมัน เหล่าคิราจิก็จะหวาดผวา... มันจะเตือนให้พวกมันนึกถึงผู้นำที่ล้มตาย และมรรตัยผู้สังหารผู้นำเหล่านั้น" },
        required = { [20858] = { "12:1980262597:1671036142", "แมลงปีกแข็งหิน" }, [20862] = { "14:574699288:1249937239", "แมลงปีกแข็งผลึก" }, [20874] = { "15:761279947:833417526", "รูปเคารพแห่งดวงอาทิตย์" }, [20926] = { "20:1932141024:1278737560", "วงรัดศีรษะของ Vek'nilash" } },
        objectiveLabels = {
            item = { ["Stone Scarab"] = "แมลงปีกแข็งหิน", ["Crystal Scarab"] = "แมลงปีกแข็งผลึก", ["Idol of the Sun"] = "รูปเคารพแห่งดวงอาทิตย์", ["Vek'nilash's Circlet"] = "วงรัดศีรษะของ Vek'nilash" },
        },
    },
    [8562] = { -- Conqueror's Breastplate
        title = { "23:729712466:87419184", "เกราะอกผู้พิชิต" },
        objective = { "211:622396823:611408446", "นำ Carapace of the Old God, Idols of War 2 ชิ้น, Silver Scarabs 5 ชิ้น และ Bone Scarabs 5 ชิ้นไปให้ Vethsera ภายใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Honored ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "493:416792670:991550203", "เทพโบราณผู้มิอาจเอ่ยนามกำลังตื่นจากนิทราอย่างเชื่องช้าใต้อันคิราจ ชะตากรรมอันน่าสะพรึงกลัวที่รออาเซรอธอยู่อาจมาถึงในอีกไม่กี่วันหรือหลายปี สำหรับสิ่งมีชีวิตที่มีพลังเช่นเขา เวลาไม่มีความหมาย\n\nเมื่อดวงดาวเรียงตัวเป็นใจ เขาจะโถมความพิโรธอันน่ากลัวเข้าใส่ทุกชีวิต เจ้าต้องค้นหาเขาก่อนถึงเวลานั้น และหาหนทางยุติการดำรงอยู่ของเขา\n\nจงทำให้สำเร็จ แล้วนำเปลือกของเขามาให้ข้าชิ้นหนึ่ง ข้าจะมอบเกราะที่ไม่เคยมีมรรตัยผู้ใดสวมใส่... เกราะที่คู่ควรกับผู้สังหารเทพ!" },
        progress = { "61:955550694:1355576136", "ณ ที่พำนักในอันคิราจ คธูนผู้เป็นที่หวาดกลัวกำลังรออยู่ในนิทรา" },
        completion = { "50:1426956665:2011202163 N 378:1864307648:1911620990", "ข้าไม่คิดว่าเจ้าจะกลับมาจากความพยายามครั้งนี้ {name}\n\nเจ้าทำให้ชะตาลิขิตที่ยิ่งใหญ่กว่าของเหล่าผู้เป็นอมตะส่วนใหญ่เป็นจริง\n\nการสังหารคธูนไม่เพียงช่วยอาเซรอธทั้งหมดไว้ แต่ยังทำให้ดุลของเหตุการณ์ในจักรวาลเปลี่ยนไปเกินกว่าที่เจ้าจะเข้าใจ\n\nจงรับเกราะอกนี้เป็นสัญลักษณ์แห่งเกียรติยศและภาระที่จะตามมาจากการกระทำของเจ้า\n\nขอให้พลังของมันช่วยเจ้าฝ่าฟันสิ่งท้าทายที่รออยู่ ผู้สังหารเทพ!" },
        required = { [20860] = { "13:408277756:1351227957", "แมลงปีกแข็งเงิน" }, [20864] = { "11:903649135:528580122", "แมลงปีกแข็งกระดูก" }, [20882] = { "11:226887665:1472544842", "รูปเคารพแห่งสงคราม" }, [20929] = { "23:246221552:109555344", "กระดองของเทพโบราณ" } },
        objectiveLabels = {
            item = { ["Silver Scarab"] = "แมลงปีกแข็งเงิน", ["Bone Scarab"] = "แมลงปีกแข็งกระดูก", ["Idol of War"] = "รูปเคารพแห่งสงคราม", ["Carapace of the Old God"] = "กระดองของเทพโบราณ" },
        },
    },
    [8579] = { -- Mortal Champions
        title = { "16:580298747:693033655", "ยอดนักรบแห่งมรรตัย" },
        progress = { "136:1015301335:409745724 R 232:2018716644:354089220", "เราสัมผัสได้ถึงพี่น้องที่ถูกกดขี่เป็นทาสอยู่ลึกเข้าไปในอันคิราจ แต่ถึงมีกองทัพมังกรก็ยังไม่พอจะช่วยพวกเขาได้ {race}\n\nคาถาเดียวกับที่กักขังพวกเขาจะทำให้เราตกอยู่ใต้อำนาจคธูนโดยสิ้นเชิง หากเราเข้าใกล้เขากว่านี้\n\nเทพโบราณมองเห็นการมาถึงของเราแล้ว ความหวังสิ้นสูญ มรรตัยตัวเล็ก ๆ อย่างเจ้าจะเปลี่ยนอะไรได้กัน?" },
        completion = { "38:1795510994:1429091376 N 461:1093534632:1878402663", "ข้าเห็นแล้วว่าเจ้าไม่ใช่มรรตัยธรรมดา {name} แม้โอกาสชนะเทพโบราณของเจ้าจะน้อยเหลือเกิน แต่ตอนนี้ก็ยังมากกว่าของพวกเรา เพราะขณะที่เขาคอยระวังมังกรอยู่หน้าประตู เขากลับไม่ได้เตรียมรับมือคนอย่างเจ้า\n\nเช่นเดียวกับที่อนาโครนอสและสแต็กเฮล์มปราบคิราจิเมื่อพันปีก่อน ด้วยพันธมิตรระหว่างเผ่าพันธุ์มรรตัยกับมังกร เราก็จะทำพันธสัญญากันเช่นกัน จงได้รับความไว้วางใจจากเหล่ามังกรสำริด แล้วเจ้าจะได้รับความไว้วางใจจากเรา เมื่อนั้นเราจึงจะทำให้เจ้าเป็นยอดนักรบอย่างแท้จริง" },
        required = { [21229] = { "22:1498237282:1556153553", "ตราของเจ้าแห่งเผ่าคิราจิ" } },
        objectiveLabels = {
            item = { ["Qiraji Lord's Insignia"] = "ตราของเจ้าแห่งเผ่าคิราจิ" },
        },
    },
    [8592] = { -- Tiara of the Oracle
        title = { "19:1779786857:1221470335", "เทียร่าแห่งผู้พยากรณ์" },
        objective = { "202:2009377551:2092129373", "นำ Vek'nilash's Circlet, Idols of the Sage 2 ชิ้น, Silver Scarabs 5 ชิ้น และ Bone Scarabs 5 ชิ้นไปให้ Andorgos ใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Friendly ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "392:2075715828:514145168 N 49:960988403:390814438", "จักรพรรดิแฝด... เสียงกระซิบที่ไม่หยุดหย่อนของพวกมันกำลังกัดกร่อนสติของข้าทีละน้อย พวกมันเยาะเย้ยข้า เพราะรู้ว่าข้าไม่อาจก้าวลึกเข้าไปในอาณาเขตของพวกมันเพื่อช่วยอารีกอส พี่น้องของข้าได้\n\nในนิมิต ข้าเห็นใบหน้าอัปลักษณ์ของพวกมันประดับด้วยมงกุฎอันทรงพลัง แต่ข้าจะต้องได้แก้แค้น... ข้าจะเปลี่ยนสัญลักษณ์แห่งอำนาจคิราจิเหล่านี้ให้เหมาะกับการใช้งานของเรา\n\nนำส่วนประกอบที่ข้าต้องการมา {name} แล้วข้าจะมอบเครื่องสวมศีรษะที่มีพลังหาสิ่งใดเทียบให้เจ้า" },
        progress = { "45:101434375:2078642228 N 1:63:63", "เจ้านำส่วนประกอบที่ข้าขอมาให้แล้วหรือ {name}?" },
        completion = { "237:1612642284:1195697987", "เจ้าทำสำเร็จแล้ว! เสียงกระซิบจากจักรพรรดิแฝดเงียบลงแล้ว\n\nรับสิ่งนี้เป็นรางวัล เพียงเห็นมัน เหล่าคิราจิก็จะหวาดผวา... มันจะเตือนให้พวกมันนึกถึงผู้นำที่ล้มตาย และมรรตัยผู้สังหารผู้นำเหล่านั้น" },
        required = { [20860] = { "13:408277756:1351227957", "แมลงปีกแข็งเงิน" }, [20864] = { "11:903649135:528580122", "แมลงปีกแข็งกระดูก" }, [20877] = { "16:226611824:1803170420", "รูปเคารพแห่งปราชญ์" }, [20926] = { "20:1932141024:1278737560", "วงรัดศีรษะของ Vek'nilash" } },
        objectiveLabels = {
