    [8593] = { -- Trousers of the Oracle
        title = { "22:1886765732:999868108", "กางเกงแห่งผู้พยากรณ์" },
        objective = { "202:2130390725:1045429380", "นำ Ouro's Intact Hide, Idols of Life 2 ชิ้น, Gold Scarabs 5 ชิ้น และ Clay Scarabs 5 ชิ้นไปให้ Kandrostrasz ภายใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Friendly ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "495:154690919:1100952960", "เจ้าอยากพิสูจน์คุณค่าของตนต่อเผ่าพันธุ์ข้าหรือ มรรตัย? ได้สิ บางทีเราอาจช่วยเหลือกันได้\n\nอูโร หนอนทรายโบราณ เป็นสิ่งมีชีวิตที่มีพลังระดับตำนาน ว่ากันว่าเทพโบราณเป็นผู้สร้างมันขึ้นมาเอง เพื่อเย้ยหยันชีวิต\n\nหนังของมันผิดธรรมชาติ... หนาจนแทบไม่มีสิ่งใดเจาะผ่านได้ แต่ก็ยืดหยุ่นพอให้มันเคลื่อนไหวได้รวดเร็วและคล่องแคล่วราวกับสิ่งมีชีวิตที่ตัวเล็กกว่ามาก\n\nนำตัวอย่างหนังของมันกับส่วนประกอบเล็กน้อยอื่น ๆ มาให้ข้า แล้วข้าจะสร้างเกราะขาอันทรงพลังให้เจ้า" },
        progress = { "40:1457140512:689795344 N 1:63:63", "เจ้านำส่วนประกอบที่ข้าต้องการมาแล้วหรือ {name}?" },
        completion = { "268:1401294821:749463947", "ใช่แล้ว... หนังของหนอนจะเป็นชั้นป้องกันชั้นเยี่ยม เมื่อนำมารวมกับชิ้นส่วนที่แข็งแกร่งที่สุดของคิราจิที่เรากำจัดระหว่างทางมาที่นี่ ก็น่าจะได้เกราะอันยอดเยี่ยม ขอให้มันช่วยเจ้ารับมือความสยดสยองเกินบรรยายที่รออยู่ภายใน!" },
        required = { [20859] = { "11:289690320:1184940294", "แมลงปีกแข็งทอง" }, [20863] = { "11:63070098:517410384", "แมลงปีกแข็งดินเหนียว" }, [20879] = { "12:141876322:1752738137", "รูปเคารพแห่งชีวิต" }, [20927] = { "18:960421714:149426513", "หนังของ Ouro ที่ยังสมบูรณ์" } },
        objectiveLabels = {
            item = { ["Gold Scarab"] = "แมลงปีกแข็งทอง", ["Clay Scarab"] = "แมลงปีกแข็งดินเหนียว", ["Idol of Life"] = "รูปเคารพแห่งชีวิต", ["Ouro's Intact Hide"] = "หนังของ Ouro ที่ยังสมบูรณ์" },
        },
    },
    [8594] = { -- Mantle of the Oracle
        title = { "20:1945221644:2105394901", "ผ้าคลุมไหล่แห่งผู้พยากรณ์" },
        objective = { "211:159125585:1539643174", "นำ Qiraji Bindings of Command, Idols of Rebirth 2 ชิ้น, Silver Scarabs 5 ชิ้น และ Ivory Scarabs 5 ชิ้นไปให้ Andorgos ใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Neutral ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "290:125012629:1426698254", "ในหมู่พวกเรามีคำกล่าวว่า เกราะไหล่อันวิจิตรที่เผ่าพันธุ์มรรตัยสวมใส่นั้น มีจุดเริ่มต้นจากความพยายามเลียนแบบปีกมังกร\n\nนำเครื่องพันธนาการที่ผู้นำระดับสูงสุดของคิราจิสวมใส่มาให้ข้า แล้วข้าจะดัดแปลงมันเป็นเกราะไหล่ที่น่าสะพรึงกลัวยิ่งกว่าปีกของเนฟาเรียนเสียอีก!" },
        progress = { "44:294661982:1846726943", "เจ้ารวบรวมส่วนประกอบที่ข้าต้องการมาแล้วหรือ?" },
        completion = { "209:1930867586:1664595477", "ข้าใช้วัตถุดิบที่เจ้านำมาและเกล็ดของศัตรูคิราจิที่พ่ายแพ้ สร้างเกราะไหล่นี้ให้เจ้า มรรตัยเอ๋ย ขอให้มันมอบการคุ้มครองที่เจ้าต้องการ และขอให้เพียงได้เห็นมัน ศัตรูของเราก็หวาดกลัว" },
        required = { [20860] = { "13:408277756:1351227957", "แมลงปีกแข็งเงิน" }, [20865] = { "12:1202006906:852939774", "แมลงปีกแข็งงาช้าง" }, [20878] = { "15:585549023:343359783", "รูปเคารพแห่งการเกิดใหม่" }, [20928] = { "26:1677574703:2025389490", "ผ้าพันข้อมือบัญชาการแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Silver Scarab"] = "แมลงปีกแข็งเงิน", ["Ivory Scarab"] = "แมลงปีกแข็งงาช้าง", ["Idol of Rebirth"] = "รูปเคารพแห่งการเกิดใหม่", ["Qiraji Bindings of Command"] = "ผ้าพันข้อมือบัญชาการแห่ง Qiraji" },
        },
    },
    [8595] = { -- Mortal Champions
        title = { "16:580298747:693033655", "ยอดนักรบแห่งมรรตัย" },
        progress = { "66:1848436922:649391972 N 103:447614728:5092990", "การสังหารขุนนางคิราจิได้หนึ่งตนนับเป็นความสำเร็จที่น่าชื่นชมสำหรับมรรตัย {name} แต่พวกมันมีจำนวนมากและทรงพลัง จงปราบพวกมันต่อไปเพื่อพิสูจน์ว่าเจ้าคู่ควรจะเป็นยอดนักรบของเรา" },
