        },
    },
    [8603] = { -- Vestments of the Oracle
        title = { "23:895839026:780102415", "อาภรณ์แห่งผู้พยากรณ์" },
        objective = { "211:446320780:480834726", "นำ Husk of the Old God, Idols of Death 2 ชิ้น, Stone Scarabs 5 ชิ้น และ Crystal Scarabs 5 ชิ้นไปให้ Vethsera ภายใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Honored ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "493:416792670:991550203", "เทพโบราณผู้มิอาจเอ่ยนามกำลังตื่นจากนิทราอย่างเชื่องช้าใต้อันคิราจ ชะตากรรมอันน่าสะพรึงกลัวที่รออาเซรอธอยู่อาจมาถึงในอีกไม่กี่วันหรือหลายปี สำหรับสิ่งมีชีวิตที่มีพลังเช่นเขา เวลาไม่มีความหมาย\n\nเมื่อดวงดาวเรียงตัวเป็นใจ เขาจะโถมความพิโรธอันน่ากลัวเข้าใส่ทุกชีวิต เจ้าต้องค้นหาเขาก่อนถึงเวลานั้น และหาหนทางยุติการดำรงอยู่ของเขา\n\nจงทำให้สำเร็จ แล้วนำเปลือกของเขามาให้ข้าชิ้นหนึ่ง ข้าจะมอบเกราะที่ไม่เคยมีมรรตัยผู้ใดสวมใส่... เกราะที่คู่ควรกับผู้สังหารเทพ!" },
        progress = { "61:955550694:1355576136", "ณ ที่พำนักในอันคิราจ คธูนผู้เป็นที่หวาดกลัวกำลังรออยู่ในนิทรา" },
        completion = { "50:1426956665:2011202163 N 379:1138492635:534461831", "ข้าไม่คิดว่าเจ้าจะกลับมาจากความพยายามครั้งนี้ {name}\n\nเจ้าทำให้ชะตาลิขิตที่ยิ่งใหญ่กว่าของเหล่าผู้เป็นอมตะส่วนใหญ่เป็นจริง\n\nการสังหารคธูนไม่เพียงช่วยอาเซรอธทั้งหมดไว้ แต่ยังทำให้ดุลของเหตุการณ์ในจักรวาลเปลี่ยนไปเกินกว่าที่เจ้าจะเข้าใจ\n\nจงรับอาภรณ์นี้เป็นสัญลักษณ์แห่งเกียรติยศและภาระที่จะตามมาจากการกระทำของเจ้า\n\nขอให้พลังของมันช่วยเจ้าฝ่าฟันสิ่งท้าทายที่รออยู่ ผู้สังหารเทพ!" },
        required = { [20858] = { "12:1980262597:1671036142", "แมลงปีกแข็งหิน" }, [20862] = { "14:574699288:1249937239", "แมลงปีกแข็งผลึก" }, [20876] = { "13:1494226888:1757839434", "รูปเคารพแห่งความตาย" }, [20933] = { "19:2112736206:1916565646", "เปลือกของเทพโบราณ" } },
        objectiveLabels = {
            item = { ["Stone Scarab"] = "แมลงปีกแข็งหิน", ["Crystal Scarab"] = "แมลงปีกแข็งผลึก", ["Idol of Death"] = "รูปเคารพแห่งความตาย", ["Husk of the Old God"] = "เปลือกของเทพโบราณ" },
        },
    },
    [8621] = { -- Stormcaller's Footguards
        title = { "24:398049773:1819046050", "เกราะเท้าผู้เรียกพายุ" },
        objective = { "195:195837580:1425442423", "นำ Qiraji Bindings of Dominance, Idols of the Sage 2 ชิ้น, Bronze Scarabs 5 ชิ้น และ Clay Scarabs 5 ชิ้นไปให้ Kandrostrasz ใน Ahn'Qiraj เควสนี้กำหนดให้มีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Neutral ด้วย" },
        description = { "299:236168875:1162629908", "เวทมนตร์คิราจิทรงพลังและเก่าแก่ คิราจิที่แข็งแกร่งที่สุดครอบครองอุปกรณ์ทรงอานุภาพจนแม้แต่มังกรยังต้องยั้งคิด\n\nนำเครื่องพันธนาการครอบงำของคิราจิกับส่วนประกอบเล็กน้อยอื่น ๆ มาให้ข้า แล้วข้าจะสร้างรองเท้าอันทรงพลังให้เจ้า\n\nเจ้าจะพบว่ามันมีประโยชน์ในการต่อสู้กับศัตรู" },
        progress = { "39:1894342980:601594342 N 1:63:63", "เจ้าได้ของที่ข้าขอมาแล้วหรือ {name}?" },
        completion = { "18:366880880:1038443585 N 124:2105041201:105126420", "เจ้าทำได้ดี {name} เจ้าพิสูจน์แล้วว่าไม่ใช่มรรตัยธรรมดา\n\nข้ามอบสิ่งนี้ให้ด้วยความมั่นใจว่ามันจะช่วยเจ้าบดขยี้คิราจิอันชั่วร้าย" },
        required = { [20861] = { "13:930087217:500728621", "แมลงปีกแข็งสำริด" }, [20863] = { "11:63070098:517410384", "แมลงปีกแข็งดินเหนียว" }, [20877] = { "16:226611824:1803170420", "รูปเคารพแห่งปราชญ์" }, [20932] = { "28:1762642700:1679769820", "ผ้าพันข้อมือครองอำนาจแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Bronze Scarab"] = "แมลงปีกแข็งสำริด", ["Clay Scarab"] = "แมลงปีกแข็งดินเหนียว", ["Idol of the Sage"] = "รูปเคารพแห่งปราชญ์", ["Qiraji Bindings of Dominance"] = "ผ้าพันข้อมือครองอำนาจแห่ง Qiraji" },
        },
    },
    [8622] = { -- Stormcaller's Hauberk
        title = { "21:675377404:2039574941", "เสื้อเกราะผู้เรียกพายุ" },
        objective = { "212:326386215:110600657", "นำ Carapace of the Old God, Idols of the Sage 2 ชิ้น, Silver Scarabs 5 ชิ้น และ Bone Scarabs 5 ชิ้นไปให้ Vethsera ภายใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Honored ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "493:416792670:991550203", "เทพโบราณผู้มิอาจเอ่ยนามกำลังตื่นจากนิทราอย่างเชื่องช้าใต้อันคิราจ ชะตากรรมอันน่าสะพรึงกลัวที่รออาเซรอธอยู่อาจมาถึงในอีกไม่กี่วันหรือหลายปี สำหรับสิ่งมีชีวิตที่มีพลังเช่นเขา เวลาไม่มีความหมาย\n\nเมื่อดวงดาวเรียงตัวเป็นใจ เขาจะโถมความพิโรธอันน่ากลัวเข้าใส่ทุกชีวิต เจ้าต้องค้นหาเขาก่อนถึงเวลานั้น และหาหนทางยุติการดำรงอยู่ของเขา\n\nจงทำให้สำเร็จ แล้วนำเปลือกของเขามาให้ข้าชิ้นหนึ่ง ข้าจะมอบเกราะที่ไม่เคยมีมรรตัยผู้ใดสวมใส่... เกราะที่คู่ควรกับผู้สังหารเทพ!" },
        progress = { "39:1894342980:601594342 N 1:63:63", "เจ้าได้ของที่ข้าขอมาแล้วหรือ {name}?" },
        completion = { "50:1426956665:2011202163 N 378:1864307648:1911620990", "ข้าไม่คิดว่าเจ้าจะกลับมาจากความพยายามครั้งนี้ {name}\n\nเจ้าทำให้ชะตาลิขิตที่ยิ่งใหญ่กว่าของเหล่าผู้เป็นอมตะส่วนใหญ่เป็นจริง\n\nการสังหารคธูนไม่เพียงช่วยอาเซรอธทั้งหมดไว้ แต่ยังทำให้ดุลของเหตุการณ์ในจักรวาลเปลี่ยนไปเกินกว่าที่เจ้าจะเข้าใจ\n\nจงรับเกราะอกนี้เป็นสัญลักษณ์แห่งเกียรติยศและภาระที่จะตามมาจากการกระทำของเจ้า\n\nขอให้พลังของมันช่วยเจ้าฝ่าฟันสิ่งท้าทายที่รออยู่ ผู้สังหารเทพ!" },
        required = { [20860] = { "13:408277756:1351227957", "แมลงปีกแข็งเงิน" }, [20864] = { "11:903649135:528580122", "แมลงปีกแข็งกระดูก" }, [20877] = { "16:226611824:1803170420", "รูปเคารพแห่งปราชญ์" }, [20929] = { "23:246221552:109555344", "กระดองของเทพโบราณ" } },
        objectiveLabels = {
            item = { ["Silver Scarab"] = "แมลงปีกแข็งเงิน", ["Bone Scarab"] = "แมลงปีกแข็งกระดูก", ["Idol of the Sage"] = "รูปเคารพแห่งปราชญ์", ["Carapace of the Old God"] = "กระดองของเทพโบราณ" },
        },
    },
    [8623] = { -- Stormcaller's Diadem
        title = { "20:498867954:1102954376", "มงกุฎผู้เรียกพายุ" },
        objective = { "199:861506010:426649833", "นำ Vek'lor's Diadem, Idols of Rebirth 2 ชิ้น, Stone Scarabs 5 ชิ้น และ Crystal Scarabs 5 ชิ้นไปให้ Andorgos ใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Friendly ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "392:2075715828:514145168 N 49:960988403:390814438", "จักรพรรดิแฝด... เสียงกระซิบที่ไม่หยุดหย่อนของพวกมันกำลังกัดกร่อนสติของข้าทีละน้อย พวกมันเยาะเย้ยข้า เพราะรู้ว่าข้าไม่อาจก้าวลึกเข้าไปในอาณาเขตของพวกมันเพื่อช่วยอารีกอส พี่น้องของข้าได้\n\nในนิมิต ข้าเห็นใบหน้าอัปลักษณ์ของพวกมันประดับด้วยมงกุฎอันทรงพลัง แต่ข้าจะต้องได้แก้แค้น... ข้าจะเปลี่ยนสัญลักษณ์แห่งอำนาจคิราจิเหล่านี้ให้เหมาะกับการใช้งานของเรา\n\nนำส่วนประกอบที่ข้าต้องการมา {name} แล้วข้าจะมอบเครื่องสวมศีรษะที่มีพลังหาสิ่งใดเทียบให้เจ้า" },
        progress = { "39:1894342980:601594342 N 1:63:63", "เจ้าได้ของที่ข้าขอมาแล้วหรือ {name}?" },
        completion = { "237:1612642284:1195697987", "เจ้าทำสำเร็จแล้ว! เสียงกระซิบจากจักรพรรดิแฝดเงียบลงแล้ว\n\nรับสิ่งนี้เป็นรางวัล เพียงเห็นมัน เหล่าคิราจิก็จะหวาดผวา... มันจะเตือนให้พวกมันนึกถึงผู้นำที่ล้มตาย และมรรตัยผู้สังหารผู้นำเหล่านั้น" },
        required = { [20858] = { "12:1980262597:1671036142", "แมลงปีกแข็งหิน" }, [20862] = { "14:574699288:1249937239", "แมลงปีกแข็งผลึก" }, [20878] = { "15:585549023:343359783", "รูปเคารพแห่งการเกิดใหม่" }, [20930] = { "16:1781536211:457997836", "มงกุฎของ Vek'lor" } },
        objectiveLabels = {
            item = { ["Stone Scarab"] = "แมลงปีกแข็งหิน", ["Crystal Scarab"] = "แมลงปีกแข็งผลึก", ["Idol of Rebirth"] = "รูปเคารพแห่งการเกิดใหม่", ["Vek'lor's Diadem"] = "มงกุฎของ Vek'lor" },
        },
    },
    [8624] = { -- Stormcaller's Leggings
        title = { "22:1511861449:2118607295", "เกราะขาผู้เรียกพายุ" },
        objective = { "219:1257625384:2010050407", "นำ Skin of the Great Sandworm, Idols of Strife 2 ชิ้น, Bronze Scarabs 5 ชิ้น และ Ivory Scarabs 5 ชิ้นไปให้ Kandrostrasz ภายใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Friendly ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "495:154690919:1100952960", "เจ้าอยากพิสูจน์คุณค่าของตนต่อเผ่าพันธุ์ข้าหรือ มรรตัย? ได้สิ บางทีเราอาจช่วยเหลือกันได้\n\nอูโร หนอนทรายโบราณ เป็นสิ่งมีชีวิตที่มีพลังระดับตำนาน ว่ากันว่าเทพโบราณเป็นผู้สร้างมันขึ้นมาเอง เพื่อเย้ยหยันชีวิต\n\nหนังของมันผิดธรรมชาติ... หนาจนแทบไม่มีสิ่งใดเจาะผ่านได้ แต่ก็ยืดหยุ่นพอให้มันเคลื่อนไหวได้รวดเร็วและคล่องแคล่วราวกับสิ่งมีชีวิตที่ตัวเล็กกว่ามาก\n\nนำตัวอย่างหนังของมันกับส่วนประกอบเล็กน้อยอื่น ๆ มาให้ข้า แล้วข้าจะสร้างเกราะขาอันทรงพลังให้เจ้า" },
        progress = { "39:1894342980:601594342 N 1:63:63", "เจ้าได้ของที่ข้าขอมาแล้วหรือ {name}?" },
        completion = { "268:1401294821:749463947", "ใช่แล้ว... หนังของหนอนจะเป็นชั้นป้องกันชั้นเยี่ยม เมื่อนำมารวมกับชิ้นส่วนที่แข็งแกร่งที่สุดของคิราจิที่เรากำจัดระหว่างทางมาที่นี่ ก็น่าจะได้เกราะอันยอดเยี่ยม ขอให้มันช่วยเจ้ารับมือความสยดสยองเกินบรรยายที่รออยู่ภายใน!" },
        required = { [20861] = { "13:930087217:500728621", "แมลงปีกแข็งสำริด" }, [20865] = { "12:1202006906:852939774", "แมลงปีกแข็งงาช้าง" }, [20881] = { "14:1296081335:1676026287", "รูปเคารพแห่งความขัดแย้ง" }, [20931] = { "26:1469680205:390640488", "หนังหนอนทรายยักษ์" } },
        objectiveLabels = {
            item = { ["Bronze Scarab"] = "แมลงปีกแข็งสำริด", ["Ivory Scarab"] = "แมลงปีกแข็งงาช้าง", ["Idol of Strife"] = "รูปเคารพแห่งความขัดแย้ง", ["Skin of the Great Sandworm"] = "หนังหนอนทรายยักษ์" },
        },
    },
    [8625] = { -- Enigma Shoulderpads
        title = { "19:584387668:1937999644", "เกราะไหล่ปริศนา" },
        objective = { "211:497918099:1660472320", "นำ Qiraji Bindings of Dominance, Idols of Death 2 ชิ้น, Stone Scarabs 5 ชิ้น และ Bronze Scarabs 5 ชิ้นไปให้ Andorgos ใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Neutral ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "290:125012629:1426698254", "ในหมู่พวกเรามีคำกล่าวว่า เกราะไหล่อันวิจิตรที่เผ่าพันธุ์มรรตัยสวมใส่นั้น มีจุดเริ่มต้นจากความพยายามเลียนแบบปีกมังกร\n\nนำเครื่องพันธนาการที่ผู้นำระดับสูงสุดของคิราจิสวมใส่มาให้ข้า แล้วข้าจะดัดแปลงมันเป็นเกราะไหล่ที่น่าสะพรึงกลัวยิ่งกว่าปีกของเนฟาเรียนเสียอีก!" },
        progress = { "44:294661982:1846726943", "เจ้ารวบรวมส่วนประกอบที่ข้าต้องการมาแล้วหรือ?" },
        completion = { "209:1930867586:1664595477", "ข้าใช้วัตถุดิบที่เจ้านำมาและเกล็ดของศัตรูคิราจิที่พ่ายแพ้ สร้างเกราะไหล่นี้ให้เจ้า มรรตัยเอ๋ย ขอให้มันมอบการคุ้มครองที่เจ้าต้องการ และขอให้เพียงได้เห็นมัน ศัตรูของเราก็หวาดกลัว" },
        required = { [20858] = { "12:1980262597:1671036142", "แมลงปีกแข็งหิน" }, [20861] = { "13:930087217:500728621", "แมลงปีกแข็งสำริด" }, [20876] = { "13:1494226888:1757839434", "รูปเคารพแห่งความตาย" }, [20932] = { "28:1762642700:1679769820", "ผ้าพันข้อมือครองอำนาจแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Stone Scarab"] = "แมลงปีกแข็งหิน", ["Bronze Scarab"] = "แมลงปีกแข็งสำริด", ["Idol of Death"] = "รูปเคารพแห่งความตาย", ["Qiraji Bindings of Dominance"] = "ผ้าพันข้อมือครองอำนาจแห่ง Qiraji" },
        },
    },
    [8626] = { -- Striker's Footguards
        title = { "20:1582154098:772960647", "เกราะเท้าผู้จู่โจม" },
        objective = { "188:1508327755:120287724", "นำ Qiraji Bindings of Command, Idols of Life 2 ชิ้น, Stone Scarabs 5 ชิ้น และ Bone Scarabs 5 ชิ้นไปให้ Kandrostrasz ใน Ahn'Qiraj เควสนี้กำหนดให้มีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Neutral ด้วย" },
        description = { "300:749657029:454758845", "เวทมนตร์คิราจิทรงพลังและเก่าแก่ คิราจิที่แข็งแกร่งที่สุดครอบครองอุปกรณ์ทรงอานุภาพจนแม้แต่มังกรยังต้องยั้งคิด\n\nนำเครื่องพันธนาการบัญชาการของคิราจิกับส่วนประกอบเล็กน้อยอื่น ๆ มาให้ข้า แล้วข้าจะสร้างรองเท้าอันทรงพลังให้เจ้า\n\nเจ้าจะพบว่ามันมีประโยชน์ในการต่อสู้กับศัตรู" },
        progress = { "39:1894342980:601594342 N 1:63:63", "เจ้าได้ของที่ข้าขอมาแล้วหรือ {name}?" },
        completion = { "18:366880880:1038443585 N 124:2105041201:105126420", "เจ้าทำได้ดี {name} เจ้าพิสูจน์แล้วว่าไม่ใช่มรรตัยธรรมดา\n\nข้ามอบสิ่งนี้ให้ด้วยความมั่นใจว่ามันจะช่วยเจ้าบดขยี้คิราจิอันชั่วร้าย" },
        required = { [20858] = { "12:1980262597:1671036142", "แมลงปีกแข็งหิน" }, [20864] = { "11:903649135:528580122", "แมลงปีกแข็งกระดูก" }, [20879] = { "12:141876322:1752738137", "รูปเคารพแห่งชีวิต" }, [20928] = { "26:1677574703:2025389490", "ผ้าพันข้อมือบัญชาการแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Stone Scarab"] = "แมลงปีกแข็งหิน", ["Bone Scarab"] = "แมลงปีกแข็งกระดูก", ["Idol of Life"] = "รูปเคารพแห่งชีวิต", ["Qiraji Bindings of Command"] = "ผ้าพันข้อมือบัญชาการแห่ง Qiraji" },
        },
    },
    [8627] = { -- Avenger's Breastplate
        title = { "21:557495466:1846011235", "เกราะอกผู้ล้างแค้น" },
        objective = { "216:1525307632:1998110612", "นำ Carapace of the Old God, Idols of the Sage 2 ชิ้น, Silver Scarabs 5 ชิ้น และ Bone Scarabs 5 ชิ้นไปให้ Vethsera ภายใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Honored ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "493:416792670:991550203", "เทพโบราณผู้มิอาจเอ่ยนามกำลังตื่นจากนิทราอย่างเชื่องช้าใต้อันคิราจ ชะตากรรมอันน่าสะพรึงกลัวที่รออาเซรอธอยู่อาจมาถึงในอีกไม่กี่วันหรือหลายปี สำหรับสิ่งมีชีวิตที่มีพลังเช่นเขา เวลาไม่มีความหมาย\n\nเมื่อดวงดาวเรียงตัวเป็นใจ เขาจะโถมความพิโรธอันน่ากลัวเข้าใส่ทุกชีวิต เจ้าต้องค้นหาเขาก่อนถึงเวลานั้น และหาหนทางยุติการดำรงอยู่ของเขา\n\nจงทำให้สำเร็จ แล้วนำเปลือกของเขามาให้ข้าชิ้นหนึ่ง ข้าจะมอบเกราะที่ไม่เคยมีมรรตัยผู้ใดสวมใส่... เกราะที่คู่ควรกับผู้สังหารเทพ!" },
        progress = { "61:955550694:1355576136", "ณ ที่พำนักในอันคิราจ คธูนผู้เป็นที่หวาดกลัวกำลังรออยู่ในนิทรา" },
        completion = { "50:1426956665:2011202163 N 378:1864307648:1911620990", "ข้าไม่คิดว่าเจ้าจะกลับมาจากความพยายามครั้งนี้ {name}\n\nเจ้าทำให้ชะตาลิขิตที่ยิ่งใหญ่กว่าของเหล่าผู้เป็นอมตะส่วนใหญ่เป็นจริง\n\nการสังหารคธูนไม่เพียงช่วยอาเซรอธทั้งหมดไว้ แต่ยังทำให้ดุลของเหตุการณ์ในจักรวาลเปลี่ยนไปเกินกว่าที่เจ้าจะเข้าใจ\n\nจงรับเกราะอกนี้เป็นสัญลักษณ์แห่งเกียรติยศและภาระที่จะตามมาจากการกระทำของเจ้า\n\nขอให้พลังของมันช่วยเจ้าฝ่าฟันสิ่งท้าทายที่รออยู่ ผู้สังหารเทพ!" },
        required = { [20860] = { "13:408277756:1351227957", "แมลงปีกแข็งเงิน" }, [20864] = { "11:903649135:528580122", "แมลงปีกแข็งกระดูก" }, [20877] = { "16:226611824:1803170420", "รูปเคารพแห่งปราชญ์" }, [20929] = { "23:246221552:109555344", "กระดองของเทพโบราณ" } },
        objectiveLabels = {
            item = { ["Silver Scarab"] = "แมลงปีกแข็งเงิน", ["Bone Scarab"] = "แมลงปีกแข็งกระดูก", ["Idol of the Sage"] = "รูปเคารพแห่งปราชญ์", ["Carapace of the Old God"] = "กระดองของเทพโบราณ" },
        },
    },
    [8628] = { -- Avenger's Crown
        title = { "15:256172853:943413853", "มงกุฎผู้ล้างแค้น" },
        objective = { "199:861506010:426649833", "นำ Vek'lor's Diadem, Idols of Rebirth 2 ชิ้น, Stone Scarabs 5 ชิ้น และ Crystal Scarabs 5 ชิ้นไปให้ Andorgos ใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Friendly ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "392:2075715828:514145168 N 49:960988403:390814438", "จักรพรรดิแฝด... เสียงกระซิบที่ไม่หยุดหย่อนของพวกมันกำลังกัดกร่อนสติของข้าทีละน้อย พวกมันเยาะเย้ยข้า เพราะรู้ว่าข้าไม่อาจก้าวลึกเข้าไปในอาณาเขตของพวกมันเพื่อช่วยอารีกอส พี่น้องของข้าได้\n\nในนิมิต ข้าเห็นใบหน้าอัปลักษณ์ของพวกมันประดับด้วยมงกุฎอันทรงพลัง แต่ข้าจะต้องได้แก้แค้น... ข้าจะเปลี่ยนสัญลักษณ์แห่งอำนาจคิราจิเหล่านี้ให้เหมาะกับการใช้งานของเรา\n\nนำส่วนประกอบที่ข้าต้องการมา {name} แล้วข้าจะมอบเครื่องสวมศีรษะที่มีพลังหาสิ่งใดเทียบให้เจ้า" },
        progress = { "45:101434375:2078642228 N 1:63:63", "เจ้านำส่วนประกอบที่ข้าขอมาให้แล้วหรือ {name}?" },
        completion = { "209:1930867586:1664595477", "ข้าใช้วัตถุดิบที่เจ้านำมาและเกล็ดของศัตรูคิราจิที่พ่ายแพ้ สร้างเกราะไหล่นี้ให้เจ้า มรรตัยเอ๋ย ขอให้มันมอบการคุ้มครองที่เจ้าต้องการ และขอให้เพียงได้เห็นมัน ศัตรูของเราก็หวาดกลัว" },
        required = { [20858] = { "12:1980262597:1671036142", "แมลงปีกแข็งหิน" }, [20862] = { "14:574699288:1249937239", "แมลงปีกแข็งผลึก" }, [20878] = { "15:585549023:343359783", "รูปเคารพแห่งการเกิดใหม่" }, [20930] = { "16:1781536211:457997836", "มงกุฎของ Vek'lor" } },
        objectiveLabels = {
            item = { ["Stone Scarab"] = "แมลงปีกแข็งหิน", ["Crystal Scarab"] = "แมลงปีกแข็งผลึก", ["Idol of Rebirth"] = "รูปเคารพแห่งการเกิดใหม่", ["Vek'lor's Diadem"] = "มงกุฎของ Vek'lor" },
        },
    },
    [8629] = { -- Avenger's Legguards
        title = { "19:1323016194:342624878", "เกราะขาผู้ล้างแค้น" },
        objective = { "219:1257625384:2010050407", "นำ Skin of the Great Sandworm, Idols of Strife 2 ชิ้น, Bronze Scarabs 5 ชิ้น และ Ivory Scarabs 5 ชิ้นไปให้ Kandrostrasz ภายใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Friendly ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "495:154690919:1100952960", "เจ้าอยากพิสูจน์คุณค่าของตนต่อเผ่าพันธุ์ข้าหรือ มรรตัย? ได้สิ บางทีเราอาจช่วยเหลือกันได้\n\nอูโร หนอนทรายโบราณ เป็นสิ่งมีชีวิตที่มีพลังระดับตำนาน ว่ากันว่าเทพโบราณเป็นผู้สร้างมันขึ้นมาเอง เพื่อเย้ยหยันชีวิต\n\nหนังของมันผิดธรรมชาติ... หนาจนแทบไม่มีสิ่งใดเจาะผ่านได้ แต่ก็ยืดหยุ่นพอให้มันเคลื่อนไหวได้รวดเร็วและคล่องแคล่วราวกับสิ่งมีชีวิตที่ตัวเล็กกว่ามาก\n\nนำตัวอย่างหนังของมันกับส่วนประกอบเล็กน้อยอื่น ๆ มาให้ข้า แล้วข้าจะสร้างเกราะขาอันทรงพลังให้เจ้า" },
        progress = { "40:1457140512:689795344 N 1:63:63", "เจ้านำส่วนประกอบที่ข้าต้องการมาแล้วหรือ {name}?" },
        completion = { "268:1401294821:749463947", "ใช่แล้ว... หนังของหนอนจะเป็นชั้นป้องกันชั้นเยี่ยม เมื่อนำมารวมกับชิ้นส่วนที่แข็งแกร่งที่สุดของคิราจิที่เรากำจัดระหว่างทางมาที่นี่ ก็น่าจะได้เกราะอันยอดเยี่ยม ขอให้มันช่วยเจ้ารับมือความสยดสยองเกินบรรยายที่รออยู่ภายใน!" },
        required = { [20861] = { "13:930087217:500728621", "แมลงปีกแข็งสำริด" }, [20865] = { "12:1202006906:852939774", "แมลงปีกแข็งงาช้าง" }, [20881] = { "14:1296081335:1676026287", "รูปเคารพแห่งความขัดแย้ง" }, [20931] = { "26:1469680205:390640488", "หนังหนอนทรายยักษ์" } },
        objectiveLabels = {
            item = { ["Bronze Scarab"] = "แมลงปีกแข็งสำริด", ["Ivory Scarab"] = "แมลงปีกแข็งงาช้าง", ["Idol of Strife"] = "รูปเคารพแห่งความขัดแย้ง", ["Skin of the Great Sandworm"] = "หนังหนอนทรายยักษ์" },
        },
    },
    [8630] = { -- Avenger's Pauldrons
        title = { "19:1938542843:1944640115", "เกราะไหล่ผู้ล้างแค้น" },
        objective = { "210:967783129:1366774516", "นำ Qiraji Bindings of Dominance, Idols of Life 2 ชิ้น, Crystal Scarabs 5 ชิ้น และ Gold Scarabs 5 ชิ้นไปให้ Andorgos ใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Neutral ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "290:125012629:1426698254", "ในหมู่พวกเรามีคำกล่าวว่า เกราะไหล่อันวิจิตรที่เผ่าพันธุ์มรรตัยสวมใส่นั้น มีจุดเริ่มต้นจากความพยายามเลียนแบบปีกมังกร\n\nนำเครื่องพันธนาการที่ผู้นำระดับสูงสุดของคิราจิสวมใส่มาให้ข้า แล้วข้าจะดัดแปลงมันเป็นเกราะไหล่ที่น่าสะพรึงกลัวยิ่งกว่าปีกของเนฟาเรียนเสียอีก!" },
        progress = { "44:294661982:1846726943", "เจ้ารวบรวมส่วนประกอบที่ข้าต้องการมาแล้วหรือ?" },
        completion = { "209:1930867586:1664595477", "ข้าใช้วัตถุดิบที่เจ้านำมาและเกล็ดของศัตรูคิราจิที่พ่ายแพ้ สร้างเกราะไหล่นี้ให้เจ้า มรรตัยเอ๋ย ขอให้มันมอบการคุ้มครองที่เจ้าต้องการ และขอให้เพียงได้เห็นมัน ศัตรูของเราก็หวาดกลัว" },
        required = { [20859] = { "11:289690320:1184940294", "แมลงปีกแข็งทอง" }, [20862] = { "14:574699288:1249937239", "แมลงปีกแข็งผลึก" }, [20879] = { "12:141876322:1752738137", "รูปเคารพแห่งชีวิต" }, [20932] = { "28:1762642700:1679769820", "ผ้าพันข้อมือครองอำนาจแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Gold Scarab"] = "แมลงปีกแข็งทอง", ["Crystal Scarab"] = "แมลงปีกแข็งผลึก", ["Idol of Life"] = "รูปเคารพแห่งชีวิต", ["Qiraji Bindings of Dominance"] = "ผ้าพันข้อมือครองอำนาจแห่ง Qiraji" },
        },
