        progress = { "39:1894342980:601594342 N 1:63:63", "เจ้าได้ของที่ข้าขอมาแล้วหรือ {name}?" },
        completion = { "18:366880880:1038443585 N 124:2105041201:105126420", "เจ้าทำได้ดี {name} เจ้าพิสูจน์แล้วว่าไม่ใช่มรรตัยธรรมดา\n\nข้ามอบสิ่งนี้ให้ด้วยความมั่นใจว่ามันจะช่วยเจ้าบดขยี้คิราจิอันชั่วร้าย" },
        required = { [20862] = { "14:574699288:1249937239", "แมลงปีกแข็งผลึก" }, [20864] = { "11:903649135:528580122", "แมลงปีกแข็งกระดูก" }, [20881] = { "14:1296081335:1676026287", "รูปเคารพแห่งความขัดแย้ง" }, [20928] = { "26:1677574703:2025389490", "ผ้าพันข้อมือบัญชาการแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Crystal Scarab"] = "แมลงปีกแข็งผลึก", ["Bone Scarab"] = "แมลงปีกแข็งกระดูก", ["Idol of Strife"] = "รูปเคารพแห่งความขัดแย้ง", ["Qiraji Bindings of Command"] = "ผ้าพันข้อมือบัญชาการแห่ง Qiraji" },
        },
