    [8638] = { -- Deathdealer's Vest
        title = { "18:1170552270:754834329", "เสื้อเกราะผู้มอบความตาย" },
        objective = { "215:1653775644:2034147473", "นำ Carapace of the Old God, Idols of Strife 2 ชิ้น, Bronze Scarabs 5 ชิ้น และ Ivory Scarabs 5 ชิ้นไปให้ Vethsera ภายใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Honored ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "493:416792670:991550203", "เทพโบราณผู้มิอาจเอ่ยนามกำลังตื่นจากนิทราอย่างเชื่องช้าใต้อันคิราจ ชะตากรรมอันน่าสะพรึงกลัวที่รออาเซรอธอยู่อาจมาถึงในอีกไม่กี่วันหรือหลายปี สำหรับสิ่งมีชีวิตที่มีพลังเช่นเขา เวลาไม่มีความหมาย\n\nเมื่อดวงดาวเรียงตัวเป็นใจ เขาจะโถมความพิโรธอันน่ากลัวเข้าใส่ทุกชีวิต เจ้าต้องค้นหาเขาก่อนถึงเวลานั้น และหาหนทางยุติการดำรงอยู่ของเขา\n\nจงทำให้สำเร็จ แล้วนำเปลือกของเขามาให้ข้าชิ้นหนึ่ง ข้าจะมอบเกราะที่ไม่เคยมีมรรตัยผู้ใดสวมใส่... เกราะที่คู่ควรกับผู้สังหารเทพ!" },
        progress = { "61:955550694:1355576136", "ณ ที่พำนักในอันคิราจ คธูนผู้เป็นที่หวาดกลัวกำลังรออยู่ในนิทรา" },
        completion = { "50:1426956665:2011202163 N 378:1864307648:1911620990", "ข้าไม่คิดว่าเจ้าจะกลับมาจากความพยายามครั้งนี้ {name}\n\nเจ้าทำให้ชะตาลิขิตที่ยิ่งใหญ่กว่าของเหล่าผู้เป็นอมตะส่วนใหญ่เป็นจริง\n\nการสังหารคธูนไม่เพียงช่วยอาเซรอธทั้งหมดไว้ แต่ยังทำให้ดุลของเหตุการณ์ในจักรวาลเปลี่ยนไปเกินกว่าที่เจ้าจะเข้าใจ\n\nจงรับเกราะอกนี้เป็นสัญลักษณ์แห่งเกียรติยศและภาระที่จะตามมาจากการกระทำของเจ้า\n\nขอให้พลังของมันช่วยเจ้าฝ่าฟันสิ่งท้าทายที่รออยู่ ผู้สังหารเทพ!" },
        required = { [20861] = { "13:930087217:500728621", "แมลงปีกแข็งสำริด" }, [20865] = { "12:1202006906:852939774", "แมลงปีกแข็งงาช้าง" }, [20881] = { "14:1296081335:1676026287", "รูปเคารพแห่งความขัดแย้ง" }, [20929] = { "23:246221552:109555344", "กระดองของเทพโบราณ" } },
        objectiveLabels = {
            item = { ["Bronze Scarab"] = "แมลงปีกแข็งสำริด", ["Ivory Scarab"] = "แมลงปีกแข็งงาช้าง", ["Idol of Strife"] = "รูปเคารพแห่งความขัดแย้ง", ["Carapace of the Old God"] = "กระดองของเทพโบราณ" },
        },
    },
    [8639] = { -- Deathdealer's Helm
        title = { "18:932906162:723360131", "หมวกเกราะผู้มอบความตาย" },
        objective = { "195:656663046:270363180", "นำ Vek'lor's Diadem, Idols of the War 2 ชิ้น, Gold Scarabs 5 ชิ้น และ Clay Scarabs 5 ชิ้นไปให้ Andorgos ใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Friendly ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "392:2075715828:514145168 N 49:960988403:390814438", "จักรพรรดิแฝด... เสียงกระซิบที่ไม่หยุดหย่อนของพวกมันกำลังกัดกร่อนสติของข้าทีละน้อย พวกมันเยาะเย้ยข้า เพราะรู้ว่าข้าไม่อาจก้าวลึกเข้าไปในอาณาเขตของพวกมันเพื่อช่วยอารีกอส พี่น้องของข้าได้\n\nในนิมิต ข้าเห็นใบหน้าอัปลักษณ์ของพวกมันประดับด้วยมงกุฎอันทรงพลัง แต่ข้าจะต้องได้แก้แค้น... ข้าจะเปลี่ยนสัญลักษณ์แห่งอำนาจคิราจิเหล่านี้ให้เหมาะกับการใช้งานของเรา\n\nนำส่วนประกอบที่ข้าต้องการมา {name} แล้วข้าจะมอบเครื่องสวมศีรษะที่มีพลังหาสิ่งใดเทียบให้เจ้า" },
        progress = { "45:101434375:2078642228 N 1:63:63", "เจ้านำส่วนประกอบที่ข้าขอมาให้แล้วหรือ {name}?" },
        completion = { "237:1612642284:1195697987", "เจ้าทำสำเร็จแล้ว! เสียงกระซิบจากจักรพรรดิแฝดเงียบลงแล้ว\n\nรับสิ่งนี้เป็นรางวัล เพียงเห็นมัน เหล่าคิราจิก็จะหวาดผวา... มันจะเตือนให้พวกมันนึกถึงผู้นำที่ล้มตาย และมรรตัยผู้สังหารผู้นำเหล่านั้น" },
        required = { [20859] = { "11:289690320:1184940294", "แมลงปีกแข็งทอง" }, [20863] = { "11:63070098:517410384", "แมลงปีกแข็งดินเหนียว" }, [20882] = { "11:226887665:1472544842", "รูปเคารพแห่งสงคราม" }, [20930] = { "16:1781536211:457997836", "มงกุฎของ Vek'lor" } },
        objectiveLabels = {
            item = { ["Gold Scarab"] = "แมลงปีกแข็งทอง", ["Clay Scarab"] = "แมลงปีกแข็งดินเหนียว", ["Idol of War"] = "รูปเคารพแห่งสงคราม", ["Vek'lor's Diadem"] = "มงกุฎของ Vek'lor" },
        },
    },
    [8640] = { -- Deathdealer's Leggings
        title = { "22:766596291:2051207606", "เกราะขาผู้มอบความตาย" },
        objective = { "207:719143050:1251867863", "นำ Ouro's Intact Hide, Idols of Night 2 ชิ้น, Stone Scarabs 5 ชิ้น และ Crystal Scarabs 5 ชิ้นไปให้ Kandrostrasz ภายใน Ahn'Qiraj คุณต้องมีชื่อเสียงกับ Brood of Nozdormu ถึงระดับ Friendly ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "495:154690919:1100952960", "เจ้าอยากพิสูจน์คุณค่าของตนต่อเผ่าพันธุ์ข้าหรือ มรรตัย? ได้สิ บางทีเราอาจช่วยเหลือกันได้\n\nอูโร หนอนทรายโบราณ เป็นสิ่งมีชีวิตที่มีพลังระดับตำนาน ว่ากันว่าเทพโบราณเป็นผู้สร้างมันขึ้นมาเอง เพื่อเย้ยหยันชีวิต\n\nหนังของมันผิดธรรมชาติ... หนาจนแทบไม่มีสิ่งใดเจาะผ่านได้ แต่ก็ยืดหยุ่นพอให้มันเคลื่อนไหวได้รวดเร็วและคล่องแคล่วราวกับสิ่งมีชีวิตที่ตัวเล็กกว่ามาก\n\nนำตัวอย่างหนังของมันกับส่วนประกอบเล็กน้อยอื่น ๆ มาให้ข้า แล้วข้าจะสร้างเกราะขาอันทรงพลังให้เจ้า" },
        progress = { "39:1894342980:601594342 N 1:63:63", "เจ้าได้ของที่ข้าขอมาแล้วหรือ {name}?" },
        completion = { "268:1401294821:749463947", "ใช่แล้ว... หนังของหนอนจะเป็นชั้นป้องกันชั้นเยี่ยม เมื่อนำมารวมกับชิ้นส่วนที่แข็งแกร่งที่สุดของคิราจิที่เรากำจัดระหว่างทางมาที่นี่ ก็น่าจะได้เกราะอันยอดเยี่ยม ขอให้มันช่วยเจ้ารับมือความสยดสยองเกินบรรยายที่รออยู่ภายใน!" },
        required = { [20858] = { "12:1980262597:1671036142", "แมลงปีกแข็งหิน" }, [20862] = { "14:574699288:1249937239", "แมลงปีกแข็งผลึก" }, [20875] = { "13:90065905:416965156", "รูปเคารพแห่งราตรี" }, [20927] = { "18:960421714:149426513", "หนังของ Ouro ที่ยังสมบูรณ์" } },
        objectiveLabels = {
