        description = { "341:377795636:5696811 N 73:768730098:865440484", "คิราจิและสมุนของมันใช้อาวุธและอุปกรณ์ที่ทำจากวัตถุดิบหายากชั้นเลิศ ทั้งกระดูกของสิ่งมีชีวิตโบราณขนาดมหึมา อัญมณีจากส่วนลึกของแผ่นดิน และโลหะบริสุทธิ์แข็งแกร่ง\n\nเพียงเห็นวัตถุของคิราจิ ข้าก็อยากนำมันมาทุบและหลอมเพื่อฝึกฝนงานช่างแล้ว จงพิสูจน์ความภักดีของเจ้าต่อสภา {name} แล้วข้าจะสร้างอาวุธอันทรงพลังให้เจ้าจากวัตถุดิบชั้นเลิศของคิราจิ" },
        progress = { "43:889427335:1508720839 N 1:63:63", "เจ้านำส่วนประกอบที่ข้าต้องการมาให้แล้วหรือ {name}?" },
        completion = { "18:366880880:1038443585 C 73:1248716374:313018554 N 58:673470490:406183982", "เจ้าทำได้ดี {class} ด้ามอาวุธนี้เป็นผลงานชั้นครู... สมดุลของมันสมบูรณ์แบบ\n\nรับอาวุธของเจ้าไป {name} จงใช้อย่างมั่นใจและปราบศัตรูของเราให้สิ้น!" },
        required = { [20861] = { "13:930087217:500728621", "แมลงปีกแข็งสำริด" }, [20865] = { "12:1202006906:852939774", "แมลงปีกแข็งงาช้าง" }, [20869] = { "10:28615449:504811820", "รูปเคารพอำพัน" }, [20886] = { "18:740788201:1620780867", "ด้ามอาวุธติดหนามแห่ง Qiraji" } },
        objectiveLabels = {
            item = { ["Bronze Scarab"] = "แมลงปีกแข็งสำริด", ["Ivory Scarab"] = "แมลงปีกแข็งงาช้าง", ["Amber Idol"] = "รูปเคารพอำพัน", ["Qiraji Spiked Hilt"] = "ด้ามอาวุธติดหนามแห่ง Qiraji" },
        },
    },
    [8712] = { -- Scythe of the Unseen Path
        title = { "25:263316889:1265952024", "เคียวเส้นทางที่มองไม่เห็น" },
        objective = { "191:1255762088:1965458804", "นำ Qiraji Spiked Hilt 1 ชิ้น, Azure Idols 2 ชิ้น, Silver Scarabs 5 ชิ้น และ Bone Scarabs 5 ชิ้นไปให้ Warden Haro ใน Silithus คุณต้องมีชื่อเสียงกับ Cenarion Circle ถึงระดับ Exalted ด้วยจึงจะสำเร็จเควสนี้" },
        description = { "341:377795636:5696811 N 73:768730098:865440484", "คิราจิและสมุนของมันใช้อาวุธและอุปกรณ์ที่ทำจากวัตถุดิบหายากชั้นเลิศ ทั้งกระดูกของสิ่งมีชีวิตโบราณขนาดมหึมา อัญมณีจากส่วนลึกของแผ่นดิน และโลหะบริสุทธิ์แข็งแกร่ง\n\nเพียงเห็นวัตถุของคิราจิ ข้าก็อยากนำมันมาทุบและหลอมเพื่อฝึกฝนงานช่างแล้ว จงพิสูจน์ความภักดีของเจ้าต่อสภา {name} แล้วข้าจะสร้างอาวุธอันทรงพลังให้เจ้าจากวัตถุดิบชั้นเลิศของคิราจิ" },
        progress = { "43:889427335:1508720839 N 1:63:63", "เจ้านำส่วนประกอบที่ข้าต้องการมาให้แล้วหรือ {name}?" },
        completion = { "18:366880880:1038443585 C 73:1248716374:313018554 N 58:673470490:406183982", "เจ้าทำได้ดี {class} ด้ามอาวุธนี้เป็นผลงานชั้นครู... สมดุลของมันสมบูรณ์แบบ\n\nรับอาวุธของเจ้าไป {name} จงใช้อย่างมั่นใจและปราบศัตรูของเราให้สิ้น!" },
        required = { [20886] = { "18:740788201:1620780867", "ด้ามอาวุธติดหนามแห่ง Qiraji" }, [20866] = { "10:1912011468:18923316", "รูปเคารพสีฟ้าคราม" }, [20860] = { "13:408277756:1351227957", "แมลงปีกแข็งเงิน" }, [20864] = { "11:903649135:528580122", "แมลงปีกแข็งกระดูก" } },
        objectiveLabels = {
            item = { ["Qiraji Spiked Hilt"] = "ด้ามอาวุธติดหนามแห่ง Qiraji", ["Azure Idol"] = "รูปเคารพสีฟ้าคราม", ["Silver Scarab"] = "แมลงปีกแข็งเงิน", ["Bone Scarab"] = "แมลงปีกแข็งกระดูก" },
        },
    },
    [8784] = { -- Secrets of the Qiraji
        title = { "21:287479807:177063795", "ความลับของคิราจิ" },
        objective = { "87:218826897:321889065", "นำ Ancient Qiraji Artifact ไปให้เหล่ามังกรที่ซ่อนตัวอยู่ใกล้ทางเข้าวิหาร" },
        description = { "139:432612276:1888725360", "คุณค้นพบวัตถุโบราณของคิราจิ! บางทีเหล่ามังกรใกล้ทางเข้าวิหารอาจใช้ประโยชน์จากโบราณวัตถุชิ้นนี้ได้" },
        progress = { "41:478095264:1544572288", "เจ้ากำลังเปล่งแสง! ข้ารู้ว่ามันหมายความว่าอย่างไร..." },
        completion = { "21:1345763:1534016705 N 93:368048472:827330078", "เป็นการค้นพบที่ยอดเยี่ยม {name} ช่างน่าทึ่งจริง ๆ! สิ่งนี้จะช่วยให้เราเข้าใจจิตใจอันบิดเบี้ยวของศัตรูได้แน่นอน" },
    },
    [8789] = { -- Imperial Qiraji Armaments
        title = { "25:67244389:1027032258", "ยุทโธปกรณ์จักรวรรดิคิราจิ" },
        objective = { "151:40123318:1091234741", "Arygos ใน Temple of Ahn'Qiraj จะสร้าง Elementium Infused Armaments ให้คุณ หากนำ Imperial Qiraji Armaments และ Elementium Ore 3 ชิ้นไปให้เขา" },
        description = { "42:963111543:595751143 N 446:929411089:2124170484", "เราไม่ได้อยู่เฉย ๆ ตลอดพันปีที่ผ่านมา {name}\n\nเราเฝ้ามองสัตว์ร้ายเหล่านี้กินพวกเดียวกันเมื่อหมดประโยชน์ เราฟังพวกมันวางแผนร้ายเพื่อทำลายโลกของเรา และเราได้รู้ถึงการทรยศหักหลังภายในหมู่พวกมันเอง\n\nพวกมันมีจุดอ่อน และเรารู้ว่าจะใช้จุดอ่อนเหล่านั้นให้เป็นประโยชน์ได้อย่างไร\n\nจงค้นหาและนำยุทโธปกรณ์สำหรับพิธีกรรมของพวกมันมาให้ข้า เมื่อผสานกับธาตุที่เกิดจากความปั่นป่วนของเทพที่พวกมันบูชาเอง มันจะกลายเป็นอาวุธที่ใครก็ต้องเกรงขาม" },
        progress = { "88:884134659:1305286657", "จงค้นหาสิ่งที่ข้าขอมา แล้วพลังของเจ้าจะเหนือกว่าผลรวมของส่วนประกอบเหล่านี้ ยอดนักรบ" },
        completion = { "102:910907901:1299535617", "เมื่อผสานเอเลเมนเทียมเข้าไป อาวุธเหล่านี้จะฟันฝ่าคิราจิและเทพของพวกมันได้อย่างง่ายดายเหลือเชื่อ" },
        required = { [21232] = { "25:67244389:1027032258", "ยุทโธปกรณ์ราชสำนักคิราจิ" }, [18562] = { "14:840460621:1776270284", "แร่เอเลเมนเทียม" } },
        objectiveLabels = {
            item = { ["Imperial Qiraji Armaments"] = "ยุทโธปกรณ์ราชสำนักคิราจิ", ["Elementium Ore"] = "แร่เอเลเมนเทียม" },
        },
    },
    [8790] = { -- Imperial Qiraji Regalia
        title = { "23:1664168147:1715523811", "เครื่องราชกกุธภัณฑ์จักรวรรดิคิราจิ" },
        objective = { "164:259887256:599573241", "Merithra of the Dream ใน Temple of Ahn'Qiraj จะสร้าง Elementium Infused Armaments ให้คุณ หากนำ Imperial Qiraji Regalia และ Elementium Ore 3 ชิ้นไปให้เธอ" },
        description = { "298:1008004196:705265673", "อารีกอสตั้งทฤษฎีว่าธาตุที่เกิดจากความขัดแย้งระหว่างเหล่าเทพโบราณกับสมุนของตนเองนั้น เป็นอันตรายถึงตายต่อพวกมันอย่างยิ่งเช่นกัน หากอยู่ในสภาวะที่เหมาะสม ข้ากำลังพูดถึงเอเลเมนเทียม มรรตัยเอ๋ย\n\nจงค้นหาและนำเครื่องราชกกุธภัณฑ์จักรวรรดิคิราจิกับธาตุพิษนั้นมาให้ข้า แล้วข้าจะนำมันไปผสานในอาวุธให้มีพลังมหาศาล" },
        progress = { "53:500056991:1250441464", "เจ้าจะโค่นพวกมันลง และปลดปล่อยเราจากพันธนาการเหล่านี้" },
        completion = { "19:55085610:1431393562 N 73:1557836562:1430933795", "จงใช้สิ่งนี้ให้ดี {name} ให้พวกมันได้ลิ้มรสความเจ็บปวดที่พวกมันปรารถนาจะมอบแก่ผู้อื่นนัก" },
        required = { [21237] = { "23:1664168147:1715523811", "เครื่องราชกกุธภัณฑ์แห่งจักรวรรดิคิราจิ" }, [18562] = { "14:840460621:1776270284", "แร่เอเลเมนเทียม" } },
        objectiveLabels = {
            item = { ["Imperial Qiraji Regalia"] = "เครื่องราชกกุธภัณฑ์แห่งจักรวรรดิคิราจิ", ["Elementium Ore"] = "แร่เอเลเมนเทียม" },
        },
    },
    [8801] = { -- C'Thun's Legacy
        title = { "15:921629117:594271830", "มรดกของคธูน" },
        objective = { "65:1335103586:60066241", "นำ Eye of C'Thun ไปให้ Caelastrasz ใน Temple of Ahn'Qiraj", variants = { { "65:821108124:98460196", "นำ Eye of C'Thun ไปให้ Caelestrasz ใน Temple of Ahn'Qiraj" } } },
        description = { "426:877444648:959483001", "กำแพงอันคิราจสั่นสะเทือน พลังชั่วร้ายที่เก่าแก่ยิ่งกว่าโลกได้ถูกทำลายลงแล้ว\n\nเมื่อมองซากของสิ่งอัปลักษณ์ขนาดมหึมา หัวใจคุณแทบหยุดเต้น แม้มันจะตายไปแล้ว คุณก็ยังสัมผัสได้ถึงความชั่วร้ายที่คธูนทิ้งไว้รอบตัว\n\nคุณทำสิ่งที่ทุกคนเคยเชื่อว่าเป็นไปไม่ได้สำเร็จแล้ว\n\nคุณคว้าก้านตาของอสูร และเก็บไว้ในกระเป๋าอย่างปลอดภัย\n\nนำ Eye of C'Thun ไปให้เหล่ามังกรในห้องถัดไป" },
        progress = { { "5:579520332:1158665293 N 33:1107492741:1515256238", "5:340956741:1126954516 N 33:1107492741:1515256238" }, "ท่าน {name} ท่านปลดปล่อยเราจากเงื้อมมือของมันแล้ว" },
        completion = { { "42:1892254342:1248465081 N 114:1698914290:223882427", "42:1653690751:1216754304 N 114:1698914290:223882427" }, "เราจะออกจากที่นี่ด้วยตนเอง ท่าน {name} เมื่อเราแน่ใจว่าความชั่วร้ายภายในถูกทำลายจนหมดสิ้นแล้ว การเดินทางที่จะกลายเป็นตำนานของท่านใกล้ถึงจุดสิ้นสุดแล้ว" },
    },
    [8802] = { -- The Savior of Kalimdor
        title = { "22:1667534151:2121457228", "ผู้กอบกู้คาลิมดอร์" },
        objective = { "60:1769758846:1063630143", "นำ Eye of C'Thun ไปให้ Anachronos ที่ Caverns of Time" },
        description = { { "36:1149191810:2041238099 N 127:1960549371:1819018202", "36:910628219:2009527322 N 127:1960549371:1819018202" }, "จงไปยังถ้ำแห่งกาลเวลา ท่าน {name} อนาโครนอสกำลังรอท่านกลับมา จงมอบดวงตาคธูนให้เขา เพราะเขาย่อมต้องการนำมันไปไว้ในชุดสะสมของนายตนอย่างแน่นอน" },
        progress = { { "5:579520332:1158665293 N 15:509736025:559794490", "5:340956741:1126954516 N 15:509736025:559794490" }, "ท่าน {name}! มันจบลงแล้ว..." },
        completion = { "146:1237497896:1557033568", "นายท่านฝากสิ่งเหล่านี้ไว้ให้เจ้า ยอดนักรบ จากคลังสมบัติเหนือกาลเวลา คือโบราณวัตถุที่รวบรวมมาจากช่วงเวลาหลายพันปี... จงเลือกตามใจเจ้า" },
    },
    [1657] = { -- Stinking Up Southshore
        title = { "22:2121897170:293646764", "ทำให้เซาท์ชอร์เหม็นคลุ้ง" },
        objective = { "150:1729698683:109056996", "ขว้าง Forsaken Stink Bombs สามลูกเข้าไปใจกลาง Southshore ใน Hillsbrad แล้วกลับไปหา Darkcaller Yanka ที่งาน Wickerman Festival ใน Tirisfal Glade" },
        description = { "455:1322578571:576575824", "ฉลองฮอลโลว์สเอนด์ให้สมใจ... ด้วยการสร้างความทุกข์ให้ศัตรูของเราที่เซาท์ชอร์!\n\nเอาระเบิดเหม็นที่ทำขึ้นเป็นพิเศษนี้ไป มันบรรจุกลิ่นฉุนชวนอาเจียนที่ไม่มีมนุษย์ หรือสัตว์ใจเสาะตัวใดทนดมได้ เจ้าต้องขว้างมันเข้าไปใจกลางเซาท์ชอร์จึงจะได้ผล เตรียมสู้กับอัลไลแอนซ์ไว้ด้วย!\n\nเมื่อทำภารกิจนี้สำเร็จ... เมื่อได้แสดงความเคารพต่อการปลดปล่อยของเราแล้ว จงกลับมาหาข้า!" },
        progress = { "94:1530358269:508480816", "เจ้านำ\"ของขวัญ\"ของเราไปมอบให้ชาวเซาท์ชอร์แล้วหรือ?\n\n<ดาร์กคอลเลอร์ แยงกาหัวเราะอย่างชั่วร้าย>" },
        completion = { "198:1953929409:565176663 N 176:1246466718:703236464", "อา ทำได้ดี! หวังว่าอัลไลแอนซ์จะสำลักของขวัญเหม็นเน่าที่เรามอบให้ เช่นเดียวกับที่เราถูกบังคับให้ทนแอกทาสของสเคิร์จ!\n\nเจ้ารักษาเจตนารมณ์ของฮอลโลว์สเอนด์ไว้ได้อย่างแท้จริง {name} ข้าขอคารวะเจ้า และเป็นรางวัลพิเศษ ข้าจะแบ่งขนมฮอลโลว์สเอนด์ให้ด้วย ข้าคิดว่าเจ้าจะสนุกกับมันทีเดียว!" },
        steps = { { "31:2135736343:957404862", "โยนระเบิดเหม็นเข้าไปใน Southshore" } },
    },
    [1658] = { -- Crashing the Wickerman Festival
        title = { "31:1892825853:974147343", "บุกงานเทศกาลวิกเกอร์แมน" },
        objective = { "121:2017237965:454330225", "ค้นหางาน Wickerman Festival ของ Forsaken ใน Tirisfal Glade เมื่อพบแล้วให้กลับไปหา Sergeant Hartman ที่ Southshore" },
        description = { "488:2119775673:1194491022", "ข้าต้องการผู้กล้ามุ่งหน้าไปทิริสฟอลเกลดส์เพื่อสำรวจงานเทศกาลวิกเกอร์แมน ข้าไม่คิดปิดบังหรอกว่าที่นั่นอันตราย ยามในงานจะโหดเหี้ยมเป็นพิเศษ แต่เราต้องรู้ว่าปีนี้งานใหญ่แค่ไหน และฟอร์เซเคนจะสร้างปัญหาให้เราเพียงใดในช่วงฮอลโลว์สเอนด์\n\nถ้าเจ้าพร้อม ก็จงไปทิริสฟอลและสอดแนมงานเทศกาล กลับมารายงานข้า แล้วข้าจะให้ค่าตอบแทนอย่างงาม" },
        progress = { "115:1300190301:1094267032", "เจ้าไปสำรวจที่ทิริสฟอลเกลดส์แล้วหรือ? ปกติพวกมันจัดงานใกล้อันเดอร์ซิตี้..." },
        completion = { "11:534428891:784080240 N 413:1998218456:1401782429", "ทำได้ดี {name} งานเทศกาลวิกเกอร์แมนจะยังเป็นปัญหาตราบใดที่ปล่อยให้ฟอร์เซเคนอันน่าชิงชังหลอกหลอนซากลอร์แดรอน ข้าขอบอกเลยว่ามันไม่ใช่การให้เกียรติอาณาจักรที่ครั้งหนึ่งเคยรุ่งเรืองอย่างเหมาะสมแม้แต่น้อย...\n\nนี่เงินสำหรับค่าซ่อมที่เจ้าอาจต้องจ่าย และเพื่อให้เข้ากับเทศกาล ข้าแถมขนมที่เจ้าน่าจะชอบให้ด้วย สุขสันต์ฮอลโลว์สเอนด์ ขอให้เรารักษาเซาท์ชอร์ให้ปลอดภัยที่สุดเท่าที่ทำได้" },
        objectiveLabels = {
            event = { ["Scout out the Forsaken's Wickerman Festival."] = "ออกสำรวจเทศกาล Wickerman ของ Forsaken" },
        },
    },
    [6961] = { -- Great-father Winter is Here!
        title = { "28:508632369:1985196963", "คุณปู่วินเทอร์มาแล้ว!" },
        objective = { "98:202864100:1120181487", "พูดคุยกับ Greatfather Winter ซึ่งอยู่ใกล้บริเวณร้าน Smokywood Pastures ใน Orgrimmar" },
        description = { "434:1438697125:1670867547", "ขอให้มีวินเทอร์เวลอันแสนวิเศษ สหาย! อย่าลืมไปทักทายคุณปู่วินเทอร์ ถ้าปีนี้เป็นเด็กดี เจ้าจะได้รับขนมแสนวิเศษในวันฉลองวินเทอร์เวล อย่าลืมบอกเขาด้วยว่าปีนี้อยากได้อะไร!\n\nแล้วก็ซื้อขนมตุนไว้ให้คนที่ทำตัวดีมาตลอดปีด้วยนะ เรามีให้เลือกมากมาย สดจากไร่สู่จานของคุณ นี่คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส!" },
        completion = { "373:1465029421:951094603", "โฮ่ โฮ่ สวัสดี ข้าคือคุณปู่วินเทอร์ และข้า โดยความอนุเคราะห์ของผู้คนแสนดีแห่งสโมกีวูดพาสเจอร์ส... \"สดจากไร่สู่จานของคุณ คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส\" ขออวยพรให้เจ้ามีงานฉลองวินเทอร์เวลที่ยอดเยี่ยม\n\nถ้าปีนี้เจ้าเป็นเด็กดี บางทีเจ้าอาจได้รับขนมจากสโมกีวูดพาสเจอร์สเป็นของขวัญวันฉลองวินเทอร์เวล ไชโย" },
    },
    [6962] = { -- Treats for Great-father Winter
        title = { "30:1270560918:1619412476", "ขนมสำหรับคุณปู่วินเทอร์" },
        objective = { "84:304392324:1100392848", "นำ Gingerbread Cookies 5 ชิ้นและ Ice Cold Milk ไปให้ Greatfather Winter ใน Orgrimmar" },
        description = { { "362:399715929:714494100", "362:1576223459:303383907" }, "นี่ ช่วยคุณปู่วินเทอร์หน่อยได้ไหม เอ่อ เจ้าหนู?\n\nไม่ใช่ว่าอยากพูดถึงตัวเองเหมือนเป็นคนอื่นโดยไม่จำเป็นหรอกนะ แต่คุณปู่วินเทอร์ทำงานนี้มาทั้งวันแล้ว และอยากกินขนมบ้าง คุกกี้ขนมปังขิงกับนมเย็นจัดสักหน่อยคงชื่นใจทีเดียว เจ้าจะช่วยเป็นเพื่อนที่ดีของคุณปู่ ไปเอามาให้ข้าหน่อยได้ไหม?" },
        progress = { "105:737198908:905208367", "พูดเรื่องขนมเสียจนข้าอยากกินขึ้นมาเองเลย อืม... คุกกี้ขนมปังขิงกับนม..." },
        completion = { "57:558909705:1653350711 N 91:397914745:832817735", "เจ้าเป็นผู้ช่วยชั้นเยี่ยมของคุณปู่วินเทอร์จริง ๆ {name} ขอให้สนุกกับงานฉลองวินเทอร์เวล\n\nนี่ของเล็กน้อย... ก็นะ สำหรับน้ำพักน้ำแรงของเจ้า" },
        required = { [1179] = { "13:1179240682:844133818", "นมเย็นจัด" }, [17197] = { "18:2002481732:719337040", "คุกกี้ขิง" } },
        steps = { { "13:1179240682:844133818", "นมเย็นจัด" }, { "18:2002481732:719337040", "คุกกี้ขิง" } },
    },
    [6963] = { -- Stolen Winter Veil Treats
        title = { "25:1784239235:1438402853", "ขนมวินเทอร์เวลที่ถูกขโมย" },
        objective = { "111:1616362219:207606864", "ค้นหาผู้สืบสวนของ Smokywood Pastures ที่หายตัวไปในบริเวณหิมะของ Alterac Mountains" },
        description = { "491:1691809786:45065330", "ฟังนะ... ไม่ได้อยากทำลายมนตร์เสน่ห์ของเทศกาลหรอก แต่สโมกีวูดพาสเจอร์สต้องการความช่วยเหลือ แบบที่นักผจญภัยอย่างพวกเจ้าถนัด\n\nขนมชุดสำคัญที่จะมาสำรองไว้ขายช่วงเทศกาลหายไป และตอนนี้เจ้าหน้าที่สโมกีวูดพาสเจอร์สที่เราส่งออกไปตามหามันก็หายไปด้วย! ได้โปรด รายงานล่าสุดระบุว่าขนมอยู่ที่เทือกเขาอัลเทอแรค คนของเราจึงไปตามหาที่นั่น\n\nไปดูให้ทีว่าทั้งขนมและคนของเรายังอยู่ที่นั่นอย่างปลอดภัยหรือไม่!" },
        completion = { "320:1661035060:926462967", "จะ... เจ้าได้ยินข้าด้วย! ขอบคุณตัวเลขกำไรจริง ๆ!\n\nข้าไม่ใช่... มนุษย์หิมะจริง ๆ ขะ... ข้าชื่อแซ็กส์ ทำงานให้สโมกีวูดพาสเจอร์ส สะ... สาขาออร์กริมมาร์ ข้าถูกส่งมาตามหาพัสดุที่หายไป แต่โดน... สิ่งมีชีวิตที่ไม่เคยเห็นมาก่อนโจมตี!\n\nหนะ... หนาวเหลือเกิน..." },
    },
    [6964] = { -- The Reason for the Season
        title = { "25:1871923861:869846825", "ความหมายของเทศกาล" },
        objective = { "100:864644442:1622713219", "พูดคุยกับ Sagorne Creststrider ใน Valley of Wisdom ที่ Orgrimmar เกี่ยวกับงาน Feast of Winter Veil" },
        description = { "475:729965891:481924197", "ของขวัญ ขนม ของฝาก... เฮอะ!\n\nก็อบลินพวกนั้นทำให้ความหมายแท้จริงของเทศกาลวินเทอร์เวลมัวหมอง นี่คือช่วงเวลาแห่งการเริ่มต้นใหม่ แผ่นดินหลับใหลใต้ผ้าห่มหิมะที่คุณปู่วินเทอร์นำมา ผู้ซึ่งไม่ใช่เจ้าโง่จอมซุ่มซ่ามใส่ชุดแดงตรงนั้น!\n\nถ้าเจ้าอยากเรียนรู้ด้วยตัวเองว่างานฉลองนี้มีความหมายอย่างไร ก็ไปถามซากอร์น เครสต์สไตรเดอร์ ข้ามั่นใจว่าเขาคงประหลาดใจที่มีคนสนใจประวัติศาสตร์มากกว่าการรับของขวัญ" },
        completion = { "485:788347488:1024756487", "งานฉลองวินเทอร์เวลอย่างนั้นหรือ? อนิจจา ในอดีตมันเคยมีความหมายลึกซึ้งกว่านี้สำหรับพวกเราทอเรน ทุกวันนี้ดูเหมือนคนอื่นจะเปลี่ยนตำนานแห่งฤดูเริ่มต้นใหม่นี้ให้กลายเป็นเครื่องมือขายลูกอมกับของขวัญ\n\nไม่น่าแปลกที่เฟอร์มุนด์จะขมขื่นกับความเปลี่ยนแปลงเช่นนั้น เขากับทอเรนอื่นที่คิดเหมือนกันยึดมั่นอดีตราวกับธงรบ แม้ข้าจะคิดว่าการฉลองเล็กน้อยเป็นเรื่องดีเสมอ แต่เราก็ควรจดจำที่มาของงานฉลองนี้ไว้" },
    },
    [6983] = { -- You're a Mean One...
        title = { "20:1009091420:1229187780", "เจ้านี่มันตัวร้าย..." },
        objective = { "206:1118301674:1297160683", "ค้นหาและนำ Stolen Treats กลับไปให้ Kaymard Copperpinch ใน Orgrimmar ล่าสุดเชื่อว่าขนมอยู่กับ Abominable Greench ที่ใดสักแห่งในบริเวณหิมะของ Alterac Mountains" },
        description = { "100:1355986018:1878074514 N 250:1364991960:123854495 N 101:1360279451:756989383", "สิ่งมีชีวิตชื่อ\"อะบอมมิเนเบิล กรีนช์\"เป็นคน... ขโมยขนมที่เราขนส่งมา {name} แต่ระ... ระวังด้วย! มันเป็นตัวที่เปลี่ยนข้าให้กลายเป็นกองหิมะนี่!\n\nเจ้าต้อง... หาเพื่อนมาช่วยสู้กับมัน ข้าเห็นมันเดิน... วนอยู่ทั่วบริเวณที่มียะ... เยติ มันต้องอยู่แถวนี้ที่ไหนสักแห่งแน่! หา... ขนมให้พบ {name} เอากลับไปให้สโมกีวูดพาสเจอร์สที่ออร์กริมมาร์ แล้วบอกพวกเขาทีว่าข้า... อยากกลับคืนร่างเดิม!" },
        progress = { "N 187:1419998366:1697380057", "{name} งานฉลองวินเทอร์เวลของเราจะพังหมด ถ้าไม่มีขนมพวกนั้นมาเติมสต็อก! แม้แต่กรัคคูเองก็จะพลาดโอกาสแบ่งพายเนื้อแสนอร่อยให้เด็กดีทั้งหลายได้กินในเทศกาลนี้..." },
        completion = { "329:2073664166:76949363", "เจ้าพบมันแล้ว! เจ้าช่วยงานฉลองวินเทอร์เวลของสโมกีวูดพาสเจอร์สไว้!\n\nแซ็กส์ผู้น่าสงสาร... เราจะส่งทีมไปหาทางคลายมนตร์น้ำแข็งให้เขาแน่นอน หวังว่าเขาจะกลับมาทันวันฉลอง แต่ก็คงต้องทำงานชดเชยเวลาที่เสียไปด้วย ถึงอย่างไร เรื่องทั้งหมดนี้ก็คงเป็นไปไม่ได้ถ้าไม่มีเจ้า!" },
        required = { [17662] = { "13:919750646:1766328619", "ขนมที่ถูกขโมย" } },
        objectiveLabels = {
            item = { ["Stolen Treats"] = "ขนมที่ถูกขโมย" },
        },
    },
    [6984] = { -- A Smokywood Pastures' Thank You!
        title = { "32:1567009288:595068463", "คำขอบคุณจากสโมกีวูดพาสเจอร์ส!" },
        objective = { "44:1323115949:1922017586", "พูดคุยกับ Great-father Winter ใน Orgrimmar" },
        description = { "71:259629038:287673156 N 346:1133710801:924289289", "พวกเราที่สโมกีวูดพาสเจอร์สขอขอบคุณที่เจ้าตามขนมที่ถูกขโมยกลับมาได้ {name} เราจึงอยากมอบของขวัญพิเศษให้... โดยมีคุณปู่วินเทอร์เป็นผู้มอบด้วยตนเอง!\n\nโปรดไปคุยกับคุณปู่วินเทอร์ แล้วเขาจะมอบของขวัญวันฉลองวินเทอร์เวลจากพวกเราชาวสโมกีวูดพาสเจอร์สให้เจ้า สดจากไร่สู่จานของคุณ คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์สเสมอ... แน่นอนว่าครั้งนี้ต้องขอบคุณเจ้าด้วย!" },
        completion = { "225:276165417:711468589", "โฮ่ โฮ่ สวัสดี นักผจญภัย!\n\nพวกก็อบลินบอกข้าว่าเจ้าสมควรได้รับของขวัญพิเศษในเทศกาลนี้ และข้าก็ยินดีมอบให้ เอ้านี่ ขอให้เจ้ามีงานฉลองวินเทอร์เวลอันแสนวิเศษ ทั้งครั้งนี้และทุกครั้งต่อไป" },
    },
    [7021] = { -- Great-father Winter is Here!
        title = { "28:508632369:1985196963", "คุณปู่วินเทอร์มาแล้ว!" },
        objective = { "98:202864100:1120181487", "พูดคุยกับ Greatfather Winter ซึ่งอยู่ใกล้บริเวณร้าน Smokywood Pastures ใน Orgrimmar" },
        description = { "464:436343774:1271106112", "ขอให้มีวินเทอร์เวลอันแสนวิเศษ สหาย! อย่าลืมไปทักทายคุณปู่วินเทอร์ที่ตอนนี้อยู่ในออร์กริมมาร์ ถ้าปีนี้เป็นเด็กดี เจ้าจะได้รับขนมแสนวิเศษในวันฉลองวินเทอร์เวล อย่าลืมบอกเขาด้วยว่าปีนี้อยากได้อะไร!\n\nแล้วก็ซื้อขนมตุนไว้ให้คนที่ทำตัวดีมาตลอดปีด้วยนะ เรามีให้เลือกมากมาย สดจากไร่สู่จานของคุณ นี่คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส!" },
        completion = { "373:1465029421:951094603", "โฮ่ โฮ่ สวัสดี ข้าคือคุณปู่วินเทอร์ และข้า โดยความอนุเคราะห์ของผู้คนแสนดีแห่งสโมกีวูดพาสเจอร์ส... \"สดจากไร่สู่จานของคุณ คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส\" ขออวยพรให้เจ้ามีงานฉลองวินเทอร์เวลที่ยอดเยี่ยม\n\nถ้าปีนี้เจ้าเป็นเด็กดี บางทีเจ้าอาจได้รับขนมจากสโมกีวูดพาสเจอร์สเป็นของขวัญวันฉลองวินเทอร์เวล ไชโย" },
    },
    [7022] = { -- Greatfather Winter is Here!
        title = { "27:2055327681:48397039", "คุณปู่วินเทอร์มาแล้ว!" },
        objective = { "98:656505783:2052171327", "พูดคุยกับ Greatfather Winter ซึ่งอยู่ใกล้บริเวณร้าน Smokywood Pastures ใน Ironforge" },
        description = { "434:1438697125:1670867547", "ขอให้มีวินเทอร์เวลอันแสนวิเศษ สหาย! อย่าลืมไปทักทายคุณปู่วินเทอร์ ถ้าปีนี้เป็นเด็กดี เจ้าจะได้รับขนมแสนวิเศษในวันฉลองวินเทอร์เวล อย่าลืมบอกเขาด้วยว่าปีนี้อยากได้อะไร!\n\nแล้วก็ซื้อขนมตุนไว้ให้คนที่ทำตัวดีมาตลอดปีด้วยนะ เรามีให้เลือกมากมาย สดจากไร่สู่จานของคุณ นี่คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส!" },
        completion = { "373:1465029421:951094603", "โฮ่ โฮ่ สวัสดี ข้าคือคุณปู่วินเทอร์ และข้า โดยความอนุเคราะห์ของผู้คนแสนดีแห่งสโมกีวูดพาสเจอร์ส... \"สดจากไร่สู่จานของคุณ คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส\" ขออวยพรให้เจ้ามีงานฉลองวินเทอร์เวลที่ยอดเยี่ยม\n\nถ้าปีนี้เจ้าเป็นเด็กดี บางทีเจ้าอาจได้รับขนมจากสโมกีวูดพาสเจอร์สเป็นของขวัญวันฉลองวินเทอร์เวล ไชโย" },
    },
    [7023] = { -- Greatfather Winter is Here!
        title = { "27:2055327681:48397039", "คุณปู่วินเทอร์มาแล้ว!" },
        objective = { "98:656505783:2052171327", "พูดคุยกับ Greatfather Winter ซึ่งอยู่ใกล้บริเวณร้าน Smokywood Pastures ใน Ironforge" },
        description = { "464:1136186920:1979551569", "ขอให้มีวินเทอร์เวลอันแสนวิเศษ สหาย! อย่าลืมไปทักทายคุณปู่วินเทอร์ที่ตอนนี้อยู่ในไอรอนฟอร์จ ถ้าปีนี้เป็นเด็กดี เจ้าจะได้รับขนมแสนวิเศษในวันฉลองวินเทอร์เวล อย่าลืมบอกเขาด้วยว่าปีนี้อยากได้อะไร!\n\nแล้วก็ซื้อขนมตุนไว้ให้คนที่ทำตัวดีมาตลอดปีด้วยนะ เรามีให้เลือกมากมาย สดจากไร่สู่จานของคุณ นี่คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส!" },
        completion = { "373:1465029421:951094603", "โฮ่ โฮ่ สวัสดี ข้าคือคุณปู่วินเทอร์ และข้า โดยความอนุเคราะห์ของผู้คนแสนดีแห่งสโมกีวูดพาสเจอร์ส... \"สดจากไร่สู่จานของคุณ คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส\" ขออวยพรให้เจ้ามีงานฉลองวินเทอร์เวลที่ยอดเยี่ยม\n\nถ้าปีนี้เจ้าเป็นเด็กดี บางทีเจ้าอาจได้รับขนมจากสโมกีวูดพาสเจอร์สเป็นของขวัญวันฉลองวินเทอร์เวล ไชโย" },
    },
    [7024] = { -- Great-father Winter is Here!
        title = { "28:508632369:1985196963", "คุณปู่วินเทอร์มาแล้ว!" },
        objective = { "98:202864100:1120181487", "พูดคุยกับ Greatfather Winter ซึ่งอยู่ใกล้บริเวณร้าน Smokywood Pastures ใน Orgrimmar" },
        description = { "464:436343774:1271106112", "ขอให้มีวินเทอร์เวลอันแสนวิเศษ สหาย! อย่าลืมไปทักทายคุณปู่วินเทอร์ที่ตอนนี้อยู่ในออร์กริมมาร์ ถ้าปีนี้เป็นเด็กดี เจ้าจะได้รับขนมแสนวิเศษในวันฉลองวินเทอร์เวล อย่าลืมบอกเขาด้วยว่าปีนี้อยากได้อะไร!\n\nแล้วก็ซื้อขนมตุนไว้ให้คนที่ทำตัวดีมาตลอดปีด้วยนะ เรามีให้เลือกมากมาย สดจากไร่สู่จานของคุณ นี่คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส!" },
        completion = { "373:1465029421:951094603", "โฮ่ โฮ่ สวัสดี ข้าคือคุณปู่วินเทอร์ และข้า โดยความอนุเคราะห์ของผู้คนแสนดีแห่งสโมกีวูดพาสเจอร์ส... \"สดจากไร่สู่จานของคุณ คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส\" ขออวยพรให้เจ้ามีงานฉลองวินเทอร์เวลที่ยอดเยี่ยม\n\nถ้าปีนี้เจ้าเป็นเด็กดี บางทีเจ้าอาจได้รับขนมจากสโมกีวูดพาสเจอร์สเป็นของขวัญวันฉลองวินเทอร์เวล ไชโย" },
    },
    [7025] = { -- Treats for Greatfather Winter
        title = { "29:1834154700:7795749", "ขนมสำหรับคุณปู่วินเทอร์" },
        objective = { "84:758034007:2032382688", "นำ Gingerbread Cookies 5 ชิ้นและ Ice Cold Milk ไปให้ Greatfather Winter ใน Ironforge" },
        description = { { "362:399715929:714494100", "362:1576223459:303383907" }, "นี่ ช่วยคุณปู่วินเทอร์หน่อยได้ไหม เอ่อ เจ้าหนู?\n\nไม่ใช่ว่าอยากพูดถึงตัวเองเหมือนเป็นคนอื่นโดยไม่จำเป็นหรอกนะ แต่คุณปู่วินเทอร์ทำงานนี้มาทั้งวันแล้ว และอยากกินขนมบ้าง คุกกี้ขนมปังขิงกับนมเย็นจัดสักหน่อยคงชื่นใจทีเดียว เจ้าจะช่วยเป็นเพื่อนที่ดีของคุณปู่ ไปเอามาให้ข้าหน่อยได้ไหม?" },
        progress = { "105:737198908:905208367", "พูดเรื่องขนมเสียจนข้าอยากกินขึ้นมาเองเลย อืม... คุกกี้ขนมปังขิงกับนม..." },
        completion = { "57:558909705:1653350711 N 91:397914745:832817735", "เจ้าเป็นผู้ช่วยชั้นเยี่ยมของคุณปู่วินเทอร์จริง ๆ {name} ขอให้สนุกกับงานฉลองวินเทอร์เวล\n\nนี่ของเล็กน้อย... ก็นะ สำหรับน้ำพักน้ำแรงของเจ้า" },
        required = { [1179] = { "13:1179240682:844133818", "นมเย็นจัด" }, [17197] = { "18:2002481732:719337040", "คุกกี้ขิง" } },
        steps = { { "13:1179240682:844133818", "นมเย็นจัด" }, { "18:2002481732:719337040", "คุกกี้ขิง" } },
    },
    [7042] = { -- Stolen Winter Veil Treats
        title = { "25:1784239235:1438402853", "ขนมวินเทอร์เวลที่ถูกขโมย" },
        objective = { "111:1616362219:207606864", "ค้นหาผู้สืบสวนของ Smokywood Pastures ที่หายตัวไปในบริเวณหิมะของ Alterac Mountains" },
        description = { "491:1691809786:45065330", "ฟังนะ... ไม่ได้อยากทำลายมนตร์เสน่ห์ของเทศกาลหรอก แต่สโมกีวูดพาสเจอร์สต้องการความช่วยเหลือ แบบที่นักผจญภัยอย่างพวกเจ้าถนัด\n\nขนมชุดสำคัญที่จะมาสำรองไว้ขายช่วงเทศกาลหายไป และตอนนี้เจ้าหน้าที่สโมกีวูดพาสเจอร์สที่เราส่งออกไปตามหามันก็หายไปด้วย! ได้โปรด รายงานล่าสุดระบุว่าขนมอยู่ที่เทือกเขาอัลเทอแรค คนของเราจึงไปตามหาที่นั่น\n\nไปดูให้ทีว่าทั้งขนมและคนของเรายังอยู่ที่นั่นอย่างปลอดภัยหรือไม่!" },
        completion = { "320:1939609964:721326782", "จะ... เจ้าได้ยินข้าด้วย! ขอบคุณตัวเลขกำไรจริง ๆ!\n\nข้าไม่ใช่... มนุษย์หิมะจริง ๆ ขะ... ข้าชื่อแซ็กส์ ทำงานให้สโมกีวูดพาสเจอร์ส สะ... สาขาไอรอนฟอร์จ ข้าถูกส่งมาตามหาพัสดุที่หายไป แต่โดน... สิ่งมีชีวิตที่ไม่เคยเห็นมาก่อนโจมตี!\n\nหนะ... หนาวเหลือเกิน..." },
    },
    [7043] = { -- You're a Mean One...
        title = { "20:1009091420:1229187780", "เจ้านี่มันตัวร้าย..." },
        objective = { "207:1945515326:1012920518", "ค้นหาและนำ Stolen Treats กลับไปให้ Wulmort Jinglepocket ใน Ironforge ล่าสุดเชื่อว่าขนมอยู่กับ Abominable Greench ที่ใดสักแห่งในบริเวณหิมะของ Alterac Mountains" },
        description = { "100:1355986018:1878074514 N 250:1364991960:123854495 N 101:471471988:1347663083", "สิ่งมีชีวิตชื่อ\"อะบอมมิเนเบิล กรีนช์\"เป็นคน... ขโมยขนมที่เราขนส่งมา {name} แต่ระ... ระวังด้วย! มันเป็นตัวที่เปลี่ยนข้าให้กลายเป็นกองหิมะนี่!\n\nเจ้าต้อง... หาเพื่อนมาช่วยสู้กับมัน ข้าเห็นมันเดิน... วนอยู่ทั่วบริเวณที่มียะ... เยติ มันต้องอยู่แถวนี้ที่ไหนสักแห่งแน่! หา... ขนมให้พบ {name} เอากลับไปให้สโมกีวูดพาสเจอร์สที่ไอรอนฟอร์จ แล้วบอกพวกเขาทีว่าข้า... อยากกลับคืนร่างเดิม!" },
        progress = { "N 187:1419998366:1697380057", "{name} งานฉลองวินเทอร์เวลของเราจะพังหมด ถ้าไม่มีขนมพวกนั้นมาเติมสต็อก! แม้แต่กรัคคูเองก็จะพลาดโอกาสแบ่งพายเนื้อแสนอร่อยให้เด็กดีทั้งหลายได้กินในเทศกาลนี้..." },
        completion = { "329:2073664166:76949363", "เจ้าพบมันแล้ว! เจ้าช่วยงานฉลองวินเทอร์เวลของสโมกีวูดพาสเจอร์สไว้!\n\nแซ็กส์ผู้น่าสงสาร... เราจะส่งทีมไปหาทางคลายมนตร์น้ำแข็งให้เขาแน่นอน หวังว่าเขาจะกลับมาทันวันฉลอง แต่ก็คงต้องทำงานชดเชยเวลาที่เสียไปด้วย ถึงอย่างไร เรื่องทั้งหมดนี้ก็คงเป็นไปไม่ได้ถ้าไม่มีเจ้า!" },
        required = { [17662] = { "13:919750646:1766328619", "ขนมที่ถูกขโมย" } },
        objectiveLabels = {
            item = { ["Stolen Treats"] = "ขนมที่ถูกขโมย" },
        },
    },
    [7045] = { -- A Smokywood Pastures' Thank You!
        title = { "32:1567009288:595068463", "คำขอบคุณจากสโมกีวูดพาสเจอร์ส!" },
        objective = { "43:75361503:1674101438", "พูดคุยกับ Greatfather Winter ใน Ironforge" },
        description = { "71:259629038:287673156 N 344:1434817155:1991158971", "พวกเราที่สโมกีวูดพาสเจอร์สขอขอบคุณที่เจ้าตามขนมที่ถูกขโมยกลับมาได้ {name} เราจึงอยากมอบของขวัญพิเศษให้... โดยมีคุณปู่วินเทอร์เป็นผู้มอบด้วยตนเอง!\n\nโปรดไปคุยกับคุณปู่วินเทอร์ แล้วเขาจะมอบของขวัญวันฉลองวินเทอร์เวลจากพวกเราชาวสโมกีวูดพาสเจอร์สให้เจ้า สดจากไร่สู่จานของคุณ คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์สเสมอ... แน่นอนว่าครั้งนี้ต้องขอบคุณเจ้าด้วย!" },
        completion = { "225:276165417:711468589", "โฮ่ โฮ่ สวัสดี นักผจญภัย!\n\nพวกก็อบลินบอกข้าว่าเจ้าสมควรได้รับของขวัญพิเศษในเทศกาลนี้ และข้าก็ยินดีมอบให้ เอ้านี่ ขอให้เจ้ามีงานฉลองวินเทอร์เวลอันแสนวิเศษ ทั้งครั้งนี้และทุกครั้งต่อไป" },
    },
    [7061] = { -- The Feast of Winter Veil
        title = { "24:410283092:1562751487", "งานฉลองวินเทอร์เวล" },
        objective = { "174:1020199790:319617514", "อ่านหนังสือ \"The Feast of Winter Veil\" ได้ตามต้องการเพื่อเรียนรู้เกี่ยวกับเทศกาล เมื่ออ่านเสร็จแล้วให้นำหนังสือไปส่ง Cairne Bloodhoof ใน Thunder Bluff" },
        description = { "446:1327537235:1134030025", "เอ้านี่ ถ้าเจ้าสนใจเรียนรู้เรื่องงานฉลองวินเทอร์เวลเพิ่มเติม ก็อ่านหนังสือเล่มนี้ แม้ข้าจะคิดว่าความเข้าใจตำนานของเราเป็นแบบที่เหมาะสม แต่ข้าก็ศึกษาตำนานมามากพอจะเห็นคุณค่าของการรวบรวมข้อมูลทั้งหมดไว้ในแหล่งเดียว\n\nเมื่ออ่านเสร็จ ให้นำหนังสือไปให้แคร์น บลัดฮูฟในธันเดอร์บลัฟฟ์ ข้ารู้แน่ว่าเขาต้องสนใจเมื่อได้ยินว่าคนอื่นหันมาสนใจตำนานของพวกเรา" },
        progress = { "227:165235964:1599118306", "ขอต้อนรับสู่มัลกอร์และชุมชนอันเรียบง่ายของเราที่ธันเดอร์บลัฟฟ์ สหาย ข้าสนใจผู้ที่เลือกใส่ใจอาณาจักร ผู้คน และตำนานของที่นี่เสมอ นี่คือเหตุผลที่เจ้ามายืนอยู่ต่อหน้าข้าหรือ?" },
        completion = { "398:1362225885:1544224162 C 23:1416387488:836257036", "ตำนานและเรื่องเล่าเกี่ยวกับวินเทอร์เวลค่อย ๆ เลือนหายจากความสนใจของผู้คนตลอดหลายปี ใช่ ข้ารู้ว่าพวกก็อบลินช่วยฟื้นฟูเทศกาลเพื่อประโยชน์ของตนเอง แต่อย่างน้อยการที่ผู้คนของเรายังนึกถึงมันในรูปแบบใดรูปแบบหนึ่ง ก็ช่วยให้ตำนานเช่นนี้ยังคงอยู่\n\nความปรารถนาของเจ้าที่จะมองให้พ้นสิ่งของและเรียนรู้อดีตของเราเป็นคุณสมบัติที่น่าชื่นชม {class} รุ่นเยาว์ ข้าขอคารวะปัญญาของเจ้า" },
    },
    [7062] = { -- The Reason for the Season
        title = { "25:1871923861:869846825", "ความหมายของเทศกาล" },
        objective = { "97:454147439:1620837328", "พูดคุยกับ Historian Karnik ที่ Explorer's League ใน Ironforge เกี่ยวกับงาน Feast of Winter Veil" },
        description = { "496:1961832171:550739562", "ของขวัญ ขนม ของฝาก... เฮอะ!\n\nก็อบลินพวกนั้นทำให้ความหมายแท้จริงของเทศกาลวินเทอร์เวลมัวหมอง นี่คือช่วงเวลาแห่งการเริ่มต้นใหม่ แผ่นดินหลับใหลใต้ผ้าห่มหิมะที่คุณปู่วินเทอร์นำมา ผู้ซึ่งไม่ใช่เจ้าโง่จอมซุ่มซ่ามใส่ชุดแดงตรงนั้น!\n\nถ้าเจ้าอยากเรียนรู้ด้วยตัวเองว่างานฉลองนี้มีความหมายอย่างไร ก็ไปถามนักประวัติศาสตร์คาร์นิกที่สมาคมนักสำรวจ ข้ามั่นใจว่าเขาคงประหลาดใจที่มีคนสนใจประวัติศาสตร์มากกว่าการรับของขวัญ" },
        completion = { "480:517573331:1096953793", "งานฉลองวินเทอร์เวลอย่างนั้นหรือ? อนิจจา ในอดีตมันเคยมีความหมายลึกซึ้งกว่านี้สำหรับพวกเราคนแคระ ทุกวันนี้ดูเหมือนคนอื่นจะเปลี่ยนตำนานคุณปู่วินเทอร์ให้กลายเป็นเครื่องมือขายลูกอมกับของขวัญ\n\nไม่น่าแปลกที่โกลีจะขมขื่นกับความเปลี่ยนแปลงเช่นนั้น เขากับคนแคระอื่นที่คิดเหมือนกันยึดมั่นอดีตราวกับธงรบ แม้ข้าจะคิดว่าการฉลองเล็กน้อยเป็นเรื่องดีเสมอ แต่เราก็ควรจดจำที่มาของงานฉลองนี้ไว้" },
    },
    [7063] = { -- The Feast of Winter Veil
        title = { "24:410283092:1562751487", "งานฉลองวินเทอร์เวล" },
        objective = { "176:734686636:1846029171", "อ่านหนังสือ \"The Feast of Winter Veil\" ได้ตามต้องการเพื่อเรียนรู้เกี่ยวกับเทศกาล เมื่ออ่านเสร็จแล้วให้นำหนังสือไปส่ง King Magni Bronzebeard ใน Ironforge" },
        description = { "419:614662196:504573959", "เอ้านี่ ถ้าเจ้าสนใจเรียนรู้เรื่องงานฉลองวินเทอร์เวลเพิ่มเติม ก็อ่านหนังสือเล่มนี้ แม้ข้าจะคิดว่าความเข้าใจตำนานของเราเป็นแบบที่เหมาะสม แต่ในฐานะผู้ใฝ่รู้ ข้าเห็นคุณค่าของการรวบรวมข้อมูลทั้งหมดไว้ในแหล่งเดียว\n\nเมื่ออ่านเสร็จ ให้นำหนังสือไปให้กษัตริย์แม็กนี บรอนซ์เบียร์ด ข้ารู้แน่ว่าเขาต้องสนใจเมื่อได้ยินว่าคนอื่นหันมาสนใจตำนานเก่าแก่" },
        progress = { "202:1937022923:13826375", "ขอต้อนรับสู่อาณาจักรไอรอนฟอร์จ สหาย ข้าสนใจผู้ที่เลือกใส่ใจอาณาจักร ผู้คน และตำนานของที่นี่เสมอ นี่คือเหตุผลที่เจ้ามายืนอยู่ต่อหน้าข้าหรือ?" },
        completion = { "408:1269289660:1630130046 C 31:161900862:1500294037", "ตำนานและเรื่องเล่าเกี่ยวกับวินเทอร์เวลค่อย ๆ เลือนหายจากความสนใจของผู้คนตลอดหลายปี แม้ข้าจะยอมรับว่าพวกก็อบลินช่วยฟื้นฟูเทศกาลเพื่อประโยชน์ของตนเอง แต่อย่างน้อยการที่ประชาชนยังนึกถึงมันในรูปแบบใดรูปแบบหนึ่ง ก็ช่วยให้ตำนานเช่นนี้ยังคงอยู่\n\nความปรารถนาของเจ้าที่จะมองให้พ้นสิ่งของและเรียนรู้อดีตของเราเป็นคุณสมบัติที่น่าชื่นชม {class} รุ่นเยาว์ ข้าขอคารวะความใฝ่รู้ของเจ้า" },
    },
    [8149] = { -- Honoring a Hero
        title = { "15:195543329:1858271989", "คารวะวีรชน" },
        objective = { "178:1250253067:284887232", "เดินทางไป Uther's Tomb ใน Western Plaguelands แล้วใช้ Uther's Tribute ที่รูปปั้นของเขา จากนั้นกลับไปหา Wagner Hammerstrike ด้านนอก Ironforge ก่อนงาน Harvest Festival สิ้นสุด" },
        description = { "486:836797187:1737150510", "ในเทศกาลเก็บเกี่ยวแห่งอาเซรอธ เราขอบคุณเหล่าวีรชนที่เสียสละเพื่อเรา บางคนถึงกับสละชีวิต อัลไลแอนซ์ยกย่องวีรชนมากมาย แต่ไม่มีเรื่องราวของใครน่าเศร้าเท่าอูเธอร์ ไลต์บริงเกอร์\n\nช่วยเราคารวะอูเธอร์ด้วยการนำเครื่องบูชานี้ไปยังสุสานของเขาในเวสเทิร์นเพลกแลนด์ วางไว้ที่รูปปั้น แล้วกลับมาหาข้า ข้าจะอยู่ที่นี่จนสิ้นสุดเทศกาลเท่านั้น อย่ารอช้าที่จะนำเครื่องคารวะไปมอบให้อูเธอร์" },
        progress = { "439:1586983741:2113941816", "เจ้าเดินทางไปสุสานอูเธอร์และวางเครื่องคารวะที่นั่นแล้วหรือ?\n\nการเดินทางนี้อาจอันตรายสำหรับนักผจญภัยที่ยังมีประสบการณ์น้อย เส้นทางที่ค่อนข้างปลอดภัยกว่าอาจเป็นการไปทางเหนือตามแม่น้ำที่ไหลผ่านฮิลส์แบรดเข้าสู่เพลกแลนด์ แม่น้ำไหลมาจากทะเลสาบข้างซอร์โรว์ฮิลล์ เดินขึ้นเนินไปทางตะวันตก โดยอยู่ห่างจากสุสานข้างเคียง... แห่งที่เต็มไปด้วยสเคิร์จ" },
        completion = { "382:1025699442:1580070459 N 104:337411702:918921839", "อูเธอร์เป็นวีรชนเหนือวีรชนทั้งปวง ข้าไม่อาจจินตนาการได้เลยว่าเขาเจ็บปวดเพียงใด เมื่ออาร์ธัส ศิษย์เอกที่เขารักเหมือนลูกชาย ทรยศต่อมนุษยชาติทั้งหมด ถึงกระนั้นเขาก็ยังลุกขึ้นพยายามหยุดอาร์ธัส และเพราะเหตุนั้น เขาจะได้รับการจดจำตลอดไปในฐานะพาลาดินที่แท้จริง เขาต่อสู้จนวาระสุดท้าย โดยคิดถึงแต่ผู้คนที่ตนอาจช่วยไว้ได้\n\nขอบคุณ {name} วันนี้เจ้าได้คารวะวีรชนผู้ยิ่งใหญ่ ให้เกียรติทั้งดวงวิญญาณของเขาและเจตนารมณ์แห่งเทศกาลเก็บเกี่ยว" },
    },
    [8150] = { -- Honoring a Hero
        title = { "15:195543329:1858271989", "คารวะวีรชน" },
        objective = { "194:1567489976:225793160", "เดินทางไป Grom's Monument ใน Demon Fall Canyon ที่ Ashenvale แล้วใช้ Grom's Tribute ที่ฐานอนุสาวรีย์ กลับไปหา Javnir Nashak ด้านนอก Orgrimmar ก่อนงาน Harvest Festival สิ้นสุด" },
        description = { "496:1298524891:1369948569", "ในเทศกาลเก็บเกี่ยวแห่งอาเซรอธ เราขอบคุณเหล่าวีรชนที่เสียสละเพื่อเรา บางคนถึงกับสละชีวิต ฮอร์ดยกย่องวีรชนมากมาย แต่ไม่มีใครเป็นแบบอย่างแห่งความแข็งแกร่งและการเสียสละยิ่งกว่ากรอม เฮลล์สครีม\n\nช่วยเราคารวะกรอมด้วยการนำเครื่องบูชานี้ไปยังอนุสาวรีย์ของเขาในเดมอนฟอลล์แคนยอนที่แอชเชนเวล วางไว้ที่ฐาน แล้วกลับมาหาข้า ข้าจะอยู่ที่นี่จนสิ้นสุดเทศกาลเท่านั้น อย่ารอช้าที่จะนำเครื่องคารวะไปมอบให้กรอม" },
        progress = { "261:14826680:817364606", "เจ้าเดินทางไปอนุสาวรีย์กรอมและวางเครื่องคารวะที่นั่นแล้วหรือ?\n\nบริเวณอนุสาวรีย์ยังคงแปดเปื้อนอำนาจของเบิร์นนิงลีเจียน หากเจ้ายังมีประสบการณ์ผจญภัยไม่มาก จงระมัดระวังเมื่อเข้าใกล้อนุสาวรีย์" },
        completion = { "327:2132959852:801744438 N 104:337411702:918921839", "ชื่อเต็มของกรอมคือกรอมแมช แปลว่า\"หัวใจของยักษ์\" การยืนหยัดสู้แมนโนรอธเพียงลำพังต้องใช้สิ่งนั้นและมากกว่านั้น ข้าคิดว่าคำกล่าวของวอร์ชีฟเหมาะที่สุดแล้ว คำสาปของออร์คเริ่มต้นและจบลงที่กรอม ช่างเหมาะสมที่การเสียสละ และอาจรวมถึงการไถ่บาปของกรอม จะเป็นต้นธารของฮอร์ดในวันนี้\n\nขอบคุณ {name} วันนี้เจ้าได้คารวะวีรชนผู้ยิ่งใหญ่ ให้เกียรติทั้งดวงวิญญาณของเขาและเจตนารมณ์แห่งเทศกาลเก็บเกี่ยว" },
    },
    [8311] = { -- Hallow's End Treats for Jesper!
        title = { "31:905552442:343103788", "ขนมฮอลโลว์สเอนด์ให้เจสเปอร์!" },
        objective = { "312:676235306:1884074094", "พูดคุยกับเจ้าของโรงแรมใน Stormwind, Ironforge และ Darnassus รวมทั้ง Talvash del Kissel ใน Ironforge แสดงท่าตามที่พวกเขาขอเพื่อแลกขนม\n\nนำ Darnassus Marzipan, Gnomeregan Gumdrop, Stormwind Nougat และ Ironforge Mint กลับไปให้ Jesper ที่ Stormwind Orphanage" },
        description = { "481:529052641:1503151138", "ข้าอยากไปทริกออร์ทรีต แต่ไปไม่ได้เพราะป่วย ถ้าเจ้าไปแทน ข้าจะเอาขนมที่มีอยู่แล้วมาแลกกับขนมที่เจ้าได้มา! ข้าว่าเจ้าต้องชอบขนมนี้แน่ มันทำให้กลายร่างเป็นอะไรต่อมิอะไร ทั้งตลกทั้งน่ากลัว!\n\nเจ้าของโรงแรมในเมืองใหญ่แต่ละแห่งมีขนมแจกช่วงฮอลโลว์สเอนด์ ไปคุยและแสดงท่าตามที่พวกเขาขอสิ! โนมตัวเล็กชื่อตัลวัชในไอรอนฟอร์จก็แจกขนมเหมือนกัน เมื่อได้ขนมครบแล้ว เอากลับมาให้ข้าที่นี่นะ!" },
        progress = { "138:640751720:1694481965", "เจ้าทริกออร์ทรีตเสร็จหรือยัง? ข้าเศร้าที่ไปไม่ได้เพราะป่วย แต่ที่เจ้าช่วยก็ทำให้รู้สึกดีขึ้นหน่อย..." },
        completion = { "165:947319009:1983976346 N 1:33:33", "ว้าว ได้มาครบเลย! เจ้ายอดเยี่ยมมาก!\n\nขอบคุณที่ไปทริกออร์ทรีตแทนข้า เอ้านี่ ขนมฟักทอง ข้าว่าเจ้าต้องชอบมากแน่!\n\nสุขสันต์ฮอลโลว์สเอนด์ {name}!" },
        required = { [20492] = { "16:637887032:1921468910", "นูกัต Stormwind" }, [20494] = { "18:95874674:1094730384", "เยลลีเคลือบน้ำตาล Gnomeregan" }, [20490] = { "14:1280436278:1728577708", "ลูกอมมิ้นต์ Ironforge" }, [20496] = { "18:1663235804:432308784", "มาร์ซิแพน Darnassus" } },
        steps = { { "16:637887032:1921468910", "นูกัต Stormwind" }, { "18:95874674:1094730384", "เยลลีเคลือบน้ำตาล Gnomeregan" }, { "14:1280436278:1728577708", "ลูกอมมิ้นต์ Ironforge" }, { "18:1663235804:432308784", "มาร์ซิแพน Darnassus" } },
    },
    [8312] = { -- Hallow's End Treats for Spoops!
        title = { "31:1207015115:1998192472", "ขนมฮอลโลว์สเอนด์ให้สปูปส์!" },
        objective = { "317:1803079995:1402637081", "พูดคุยกับเจ้าของโรงแรมใน Orgrimmar, Undercity และ Thunder Bluff รวมทั้ง Kali Remik ใน Sen'jin Village แสดงท่าตามที่พวกเขาขอเพื่อแลกขนม\n\nนำ Thunder Bluff Marzipan, Darkspear Gumdrop, Orgrimmar Nougat และ Undercity Mint กลับไปให้ Spoops ที่ Orgrimmar Orphanage" },
        description = { "483:292151869:1016332304", "ข้าอยากไปทริกออร์ทรีต แต่ไปไม่ได้เพราะป่วย ถ้าเจ้าไปแทน ข้าจะเอาขนมที่มีอยู่แล้วมาแลกกับขนมที่เจ้าได้มา! ข้าว่าเจ้าต้องชอบขนมนี้แน่ มันทำให้กลายร่างเป็นอะไรต่อมิอะไร ทั้งตลกทั้งน่ากลัว!\n\nเจ้าของโรงแรมในเมืองใหญ่แต่ละแห่งมีขนมแจกช่วงฮอลโลว์สเอนด์ ไปคุยและแสดงท่าตามที่พวกเขาขอสิ! โทรลล์ชื่อคาลี เรอมิกในหมู่บ้านเซนจินก็แจกขนมเหมือนกัน เมื่อได้ขนมครบแล้ว เอากลับมาให้ข้าที่นี่นะ!" },
        progress = { "138:640751720:1694481965", "เจ้าทริกออร์ทรีตเสร็จหรือยัง? ข้าเศร้าที่ไปไม่ได้เพราะป่วย แต่ที่เจ้าช่วยก็ทำให้รู้สึกดีขึ้นหน่อย..." },
        completion = { "165:947319009:1983976346 N 1:33:33", "ว้าว ได้มาครบเลย! เจ้ายอดเยี่ยมมาก!\n\nขอบคุณที่ไปทริกออร์ทรีตแทนข้า เอ้านี่ ขนมฟักทอง ข้าว่าเจ้าต้องชอบมากแน่!\n\nสุขสันต์ฮอลโลว์สเอนด์ {name}!" },
        required = { [20493] = { "16:598717273:2059132251", "นูกัต Orgrimmar" }, [20495] = { "17:706099468:1033610717", "เยลลีเคลือบน้ำตาล Darkspear" }, [20491] = { "14:1856315043:182361149", "ลูกอมมิ้นต์ Undercity" }, [20497] = { "22:1408655408:255807454", "มาร์ซิแพน Thunder Bluff" } },
        steps = { { "16:598717273:2059132251", "นูกัต Orgrimmar" }, { "17:706099468:1033610717", "เยลลีเคลือบน้ำตาล Darkspear" }, { "14:1856315043:182361149", "ลูกอมมิ้นต์ Undercity" }, { "22:1408655408:255807454", "มาร์ซิแพน Thunder Bluff" } },
    },
    [8322] = { -- Rotten Eggs
        title = { "11:1065849:1622271932", "ไข่เน่า" },
        objective = { "77:1895216284:1869506699", "ใส่ Rotten Eggs ลงในถังหมักหลักภายใน Southshore Inn" },
        description = { "493:1834267975:177851400", "มนุษย์เซาท์ชอร์ชอบเอล พวกมันจึงหวงแหนเอลที่เสิร์ฟในโรงแรมเซาท์ชอร์ เมื่อความโกลาหลแห่งฮอลโลว์สเอนด์มาถึง เราก็ใช้โอกาสนี้ทำให้เครื่องดื่มชุดใหม่ของพวกมันเสียไปได้หลายสัปดาห์ หรืออาจถึงหลายเดือน!\n\nเอาไข่เน่าเหล่านี้ไปใส่ในถังหมักหลักภายในโรงแรมเซาท์ชอร์ แค่เจ้าไปปรากฏตัวก็จะมีเรื่องแล้ว เตรียมป้องกันตัวไว้ด้วย!\n\nเมื่อมอบรสชาติที่เซาท์ชอร์จะไม่มีวันลืมได้แล้ว กลับมาหาข้าที่งานเทศกาลนี่!" },
        progress = { "27:1695604339:1048629750", "ถังบรรจุเอลอยู่เต็ม" },
        completion = { "140:2112706904:1098262794", "หลังฝ่าการต่อสู้เข้ามาในโรงแรมได้สำเร็จ คุณใส่ไข่ลงในถัง กลิ่นเหม็นเริ่มฟุ้งกระจายไปในอากาศ..." },
        required = { [20605] = { "11:1065849:1622271932", "ไข่เน่า" } },
        objectiveLabels = {
            item = { ["Rotten Eggs"] = "ไข่เน่า" },
        },
    },
    [8353] = { -- Chicken Clucking for a Mint
        title = { "27:250932889:357783868", "ขันเหมือนไก่แลกมินต์" },
        objective = { "91:734598848:207871402", "แสดงท่า chicken ให้ Innkeeper Firebrew เพื่อรับ Ironforge Mint เป็นการแลกเปลี่ยน!" },
        description = { "341:132999547:1885772604 C 63:1111003327:505419005", "อ้อ ไปทริกออร์ทรีตแทนเด็กป่วยอยู่หรือ? ข้ากำลังจะบอกเลยว่าเจ้าดูโตเกินกว่าจะเที่ยวขอขนมแล้ว...\n\nเอาละ ถ้าอยากได้ขนมของข้า ไอรอนฟอร์จมินต์ เจ้าต้อง... ขันเหมือนไก่! ใช่ ไก่ชอบมินต์... เอ่อ ก็ได้ มันอาจไม่ได้ชอบนักหรอก... แต่ข้าจะไม่ให้มินต์จนกว่าเจ้าจะขันเหมือนไก่ให้ข้าดู!\n\nว่าไง {class} เจ้ารับคำท้าหรือไม่?! ถึงเวลาทำอะไรแลกขนมแล้ว!" },
        progress = { "14:494711727:168104643", "ข้ารออยู่นะ..." },
        completion = { "22:107194788:71758426 N 40:2026660454:1262182311", "ตลกเหลือเกิน! ทำได้ดี {name}! นี่ขนมของเจ้า\n\nสุขสันต์ฮอลโลว์สเอนด์!" },
    },
    [8354] = { -- Chicken Clucking for a Mint
        title = { "27:250932889:357783868", "ขันเหมือนไก่แลกมินต์" },
        objective = { "89:1264302145:57644462", "แสดงท่า chicken ให้ Innkeeper Norman เพื่อรับ Undercity Mint เป็นการแลกเปลี่ยน!" },
        description = { "341:1906171754:601468091 C 63:1111003327:505419005", "อ้อ ไปทริกออร์ทรีตแทนเด็กป่วยอยู่หรือ? ข้ากำลังจะบอกเลยว่าเจ้าดูโตเกินกว่าจะเที่ยวขอขนมแล้ว...\n\nเอาละ ถ้าอยากได้ขนมของข้า อันเดอร์ซิตี้มินต์ เจ้าต้อง... ขันเหมือนไก่! ใช่ ไก่ชอบมินต์... เอ่อ ก็ได้ มันอาจไม่ได้ชอบนักหรอก... แต่ข้าจะไม่ให้มินต์จนกว่าเจ้าจะขันเหมือนไก่ให้ข้าดู!\n\nว่าไง {class} เจ้ารับคำท้าหรือไม่?! ถึงเวลาทำอะไรแลกขนมแล้ว!" },
        progress = { "14:494711727:168104643", "ข้ารออยู่นะ..." },
        completion = { "22:107194788:71758426 N 40:2026660454:1262182311", "ตลกเหลือเกิน! ทำได้ดี {name}! นี่ขนมของเจ้า\n\nสุขสันต์ฮอลโลว์สเอนด์!" },
    },
    [8355] = { -- Incoming Gumdrop
        title = { "16:126459984:1159929717", "กัมดร็อปมาแล้ว" },
        objective = { "92:1342708573:852930946", "แสดงท่า train ให้ Talvash del Kissel เพื่อรับ Gnomeregan Gumdrop เป็นการแลกเปลี่ยน!" },
        description = { "353:1366023810:1685230821 C 1:33:33", "คนมาทริกออร์ทรีต! ไชโย!\n\nถึงเจ้าจะทำความดีเก็บขนมให้เด็กป่วย ข้าก็ปล่อยให้เจ้ารอดไปง่าย ๆ ไม่ได้หรอก ข้ามีกัมดร็อปโนเมอเรแกนแสนอร่อยให้เด็กคนนั้น... ถ้าเจ้าทำเสียงรถไฟให้ข้าฟัง! ฮ่า ๆ ใช่แล้ว นั่นละท่าที่ต้องทำ! ราคาของกัมดร็อปชิ้นนี้คือเสียงรถไฟหนึ่งครั้ง!\n\nฉึกฉัก ฉึกฉัก {class}!" },
        progress = { "21:1821405279:1723465479", "เอาละ ลงมือได้เลย..." },
        completion = { "20:1295804344:1184488038 N 40:2026660454:1262182311", "ปู๊น ปู๊น! ทำได้ดี {name}! นี่ขนมของเจ้า\n\nสุขสันต์ฮอลโลว์สเอนด์!" },
    },
    [8356] = { -- Flexing for Nougat
        title = { "18:1878276553:662685565", "เบ่งกล้ามแลกนูกัต" },
        objective = { "86:962625643:1006731556", "แสดงท่า flex ให้ Innkeeper Allison เพื่อรับ Stormwind Nougat เป็นการแลกเปลี่ยน!" },
        description = { { "423:1920888358:993789153", "424:2143052348:1928985765" }, "ชุดแฟนซีที่เจ้าใส่... น่าสนใจดีนะ แม้เจ้าจะใจดีช่วยเด็กป่วยทริกออร์ทรีตในปีนี้ แต่ข้าคงต้องขอให้เจ้าแสดงท่าสักอย่างให้ดูก่อน!\n\nขอดูหน่อย... เจ้าใน... ชุดนั้น... ดูแข็งแรงกำยำมาก เบ่งกล้ามให้ดูสิ! ใช่ เอาเลย เบ่งกล้ามให้ข้าดูหน่อย คนแข็งแรง!\n\nต่อเมื่อเจ้าเบ่งกล้ามให้ดูเท่านั้น ข้าจึงจะให้นูกัตสตอร์มวินด์แสนอร่อย เป็นขนมฮอลโลว์สเอนด์ที่ยอดเยี่ยมเลยละ", variants = { { "422:1292262450:929440276", "ชุดแฟนซีที่เจ้าใส่... น่าสนใจดีนะ แม้เจ้าจะใจดีช่วยเด็กป่วยทริกออร์ทรีตในปีนี้ แต่ข้าคงต้องขอให้เจ้าแสดงท่าสักอย่างให้ดูก่อน!\n\nขอดูหน่อย... เจ้าใน... ชุดนั้น... ดูแข็งแรงกำยำมาก เบ่งกล้ามให้ดูสิ! ใช่ เอาเลย เบ่งกล้ามให้ข้าดูหน่อย พ่อหนุ่มจอมพลัง!\n\nต่อเมื่อเจ้าเบ่งกล้ามให้ดูเท่านั้น ข้าจึงจะให้นูกัตสตอร์มวินด์แสนอร่อย เป็นขนมฮอลโลว์สเอนด์ที่ยอดเยี่ยมเลยละ" } } },
        progress = { "32:891341963:1217669678 N 3:3050122:795478", "ไม่มีขนมจนกว่าเจ้าจะเบ่งกล้ามให้ข้าดู {name}..." },
        completion = { "118:1491201499:1372434459 N 1:33:33", "เจ้าแข็งแรงจริง ๆ ฮ่า ๆ! ทำได้ดี ขอบคุณที่ร่วมสนุกด้วย นี่ขนมของเจ้า\n\nสุขสันต์ฮอลโลว์สเอนด์ {name}!" },
    },
    [8357] = { -- Dancing for Marzipan
        title = { "20:1605323903:531905459", "เต้นแลกมาร์ซิแพน" },
        objective = { "91:2056551768:1099370229", "แสดงท่า dance ให้ Innkeeper Saelienne เพื่อรับ Darnassus Marzipan เป็นการแลกเปลี่ยน!" },
        description = { "325:904208238:534747320", "ถึงจะทริกออร์ทรีตแทนเด็กป่วย เจ้าก็ยังต้องแสดงท่าแลกขนมอยู่ดี! เราจะเปลี่ยนธรรมเนียมง่าย ๆ ไม่ได้ จริงไหม...\n\nข้าเชื่อว่าราคาของมาร์ซิแพนหนึ่งชิ้นในทุกวันนี้ คือการออกมาเต้น! ใช่แล้ว ขอดูลีลาหน่อย! เต้นให้ข้าดู แล้วข้าจะให้มาร์ซิแพนแสนอร่อย!" },
        progress = { "142:1841537596:759308462", "เจ้ารู้วิธีเต้นใช่ไหม? ลองยื่นเท้าขวาเข้าไป... แล้วดึงเท้าขวาออกมา... ยื่นเท้าขวาเข้าไป... ส่ายไปมา..." },
        completion = { "34:1262281299:254421029 N 142:1955589814:1887571966", "เจ้าเป็นนักเต้นตัวยงจริง ๆ {name}!\n\nนี่ขนมสำหรับการร่วมสนุก สุขสันต์ฮอลโลว์สเอนด์ และฝากความปรารถนาดีไปถึงสหายตัวน้อยที่ป่วยด้วยนะ! หวังว่าจะหายเร็ว ๆ" },
    },
    [8358] = { -- Incoming Gumdrop
        title = { "16:126459984:1159929717", "กัมดร็อปมาแล้ว" },
        objective = { "83:1550555109:915638917", "แสดงท่า train ให้ Kali Remik เพื่อรับ Darkspear Gumdrop เป็นการแลกเปลี่ยน!" },
        description = { "354:1847424148:479146784 C 1:33:33", "คนมาทริกออร์ทรีต! เยี่ยมเลย สหาย!\n\nถึงเจ้าจะทำความดีเก็บขนมให้เด็กป่วย ข้าก็ปล่อยให้เจ้ารอดไปง่าย ๆ ไม่ได้หรอก ข้ามีกัมดร็อปดาร์กสเปียร์แสนอร่อยให้เด็กคนนั้น... ถ้าเจ้าทำเสียงรถไฟให้ข้าฟัง! ฮ่า ๆ ใช่แล้ว นั่นละท่าที่ต้องทำ! ราคาของกัมดร็อปชิ้นนี้คือเสียงรถไฟหนึ่งครั้ง!\n\nฉึกฉัก ฉึกฉัก {class}!" },
        progress = { "21:1821405279:1723465479", "เอาละ ลงมือได้เลย..." },
        completion = { "20:1295804344:1184488038 N 40:2026660454:1262182311", "ปู๊น ปู๊น! ทำได้ดี {name}! นี่ขนมของเจ้า\n\nสุขสันต์ฮอลโลว์สเอนด์!" },
    },
    [8359] = { -- Flexing for Nougat
        title = { "18:1878276553:662685565", "เบ่งกล้ามแลกนูกัต" },
        objective = { "86:2047641108:326925700", "แสดงท่า flex ให้ Innkeeper Gryshka เพื่อรับ Orgrimmar Nougat เป็นการแลกเปลี่ยน!" },
        description = { { "423:416199996:1998710500", "424:638363986:786423483" }, "ชุดแฟนซีที่เจ้าใส่... น่าสนใจดีนะ แม้เจ้าจะใจดีช่วยเด็กป่วยทริกออร์ทรีตในปีนี้ แต่ข้าคงต้องขอให้เจ้าแสดงท่าสักอย่างให้ดูก่อน!\n\nขอดูหน่อย... เจ้าใน... ชุดนั้น... ดูแข็งแรงกำยำมาก เบ่งกล้ามให้ดูสิ! ใช่ เอาเลย เบ่งกล้ามให้ข้าดูหน่อย คนแข็งแรง!\n\nต่อเมื่อเจ้าเบ่งกล้ามให้ดูเท่านั้น ข้าจึงจะให้นูกัตออร์กริมมาร์แสนอร่อย เป็นขนมฮอลโลว์สเอนด์ที่ยอดเยี่ยมเลยละ", variants = { { "422:1935057735:1934361623", "ชุดแฟนซีที่เจ้าใส่... น่าสนใจดีนะ แม้เจ้าจะใจดีช่วยเด็กป่วยทริกออร์ทรีตในปีนี้ แต่ข้าคงต้องขอให้เจ้าแสดงท่าสักอย่างให้ดูก่อน!\n\nขอดูหน่อย... เจ้าใน... ชุดนั้น... ดูแข็งแรงกำยำมาก เบ่งกล้ามให้ดูสิ! ใช่ เอาเลย เบ่งกล้ามให้ข้าดูหน่อย พ่อหนุ่มจอมพลัง!\n\nต่อเมื่อเจ้าเบ่งกล้ามให้ดูเท่านั้น ข้าจึงจะให้นูกัตออร์กริมมาร์แสนอร่อย เป็นขนมฮอลโลว์สเอนด์ที่ยอดเยี่ยมเลยละ" } } },
        progress = { "32:891341963:1217669678 N 3:3050122:795478", "ไม่มีขนมจนกว่าเจ้าจะเบ่งกล้ามให้ข้าดู {name}..." },
        completion = { "118:1491201499:1372434459 N 1:33:33", "เจ้าแข็งแรงจริง ๆ ฮ่า ๆ! ทำได้ดี ขอบคุณที่ร่วมสนุกด้วย นี่ขนมของเจ้า\n\nสุขสันต์ฮอลโลว์สเอนด์ {name}!" },
    },
    [8360] = { -- Dancing for Marzipan
        title = { "20:1605323903:531905459", "เต้นแลกมาร์ซิแพน" },
        objective = { "90:1085950522:1339255971", "แสดงท่า dance ให้ Innkeeper Pala เพื่อรับ Thunder Bluff Marzipan เป็นการแลกเปลี่ยน!" },
        description = { "325:904208238:534747320", "ถึงจะทริกออร์ทรีตแทนเด็กป่วย เจ้าก็ยังต้องแสดงท่าแลกขนมอยู่ดี! เราจะเปลี่ยนธรรมเนียมง่าย ๆ ไม่ได้ จริงไหม...\n\nข้าเชื่อว่าราคาของมาร์ซิแพนหนึ่งชิ้นในทุกวันนี้ คือการออกมาเต้น! ใช่แล้ว ขอดูลีลาหน่อย! เต้นให้ข้าดู แล้วข้าจะให้มาร์ซิแพนแสนอร่อย!" },
        progress = { "142:1841537596:759308462", "เจ้ารู้วิธีเต้นใช่ไหม? ลองยื่นเท้าขวาเข้าไป... แล้วดึงเท้าขวาออกมา... ยื่นเท้าขวาเข้าไป... ส่ายไปมา..." },
        completion = { "34:1262281299:254421029 N 142:1955589814:1887571966", "เจ้าเป็นนักเต้นตัวยงจริง ๆ {name}!\n\nนี่ขนมสำหรับการร่วมสนุก สุขสันต์ฮอลโลว์สเอนด์ และฝากความปรารถนาดีไปถึงสหายตัวน้อยที่ป่วยด้วยนะ! หวังว่าจะหายเร็ว ๆ" },
    },
    [8373] = { -- The Power of Pine
        title = { "17:2079665327:948698231", "พลังแห่งสน" },
        objective = { "152:673094456:90980198", "ใช้ Stink Bomb Cleaner กำจัด Forsaken Stink Bomb ที่ถูกทิ้งไว้ใน Southshore เมื่อเสร็จแล้วให้กลับไปหา Sergeant Hartman ใน Southshore" },
        description = { "455:2134395008:1291781977", "สิ่งที่ข้าเกลียดที่สุดในช่วงฮอลโลว์สเอนด์คือระเบิดเหม็นที่ฟอร์เซเคนใช้กับเซาท์ชอร์ ใครจะคิดว่าการฉลองอิสรภาพต้องมาพร้อมกับความเหม็นเละเทะขนาดนี้?\n\nช่วงฮอลโลว์สเอนด์ จงใช้น้ำยานี้กำจัดระเบิดเหม็นที่ฮอร์ดอาจนำมาทิ้งในหมู่บ้าน มันใช้พลังแห่งสนต่อสู้กับกลิ่นเหม็น\n\nช่วยรักษาเซาท์ชอร์ให้สะอาด แล้วข้าจะให้ขนมฮอลโลว์สเอนด์ที่เจ้าต้องชอบ ตกลงไหม?" },
        progress = { "142:1397042917:1120801002", "ฟอร์เซเคนบัดซบนั่น... แค่เป็นอันเดดก็แย่พออยู่แล้ว ยังจะมาฮึกเหิมสร้างเรื่องในหมู่บ้านของข้าอีก!" },
        completion = { "72:1500598126:1810993930 N 258:1331299329:478867056", "อา กลิ่นแถวนี้แทบจะดีขึ้นแล้ว แทบจะนะ\n\nเพราะเจ้า {name} เซาท์ชอร์อาจผ่านฮอลโลว์สเอนด์ไปได้อีกปี นี่ขนมพร้อมคำขอบคุณของข้า! ถ้าขนมหมด ข้าคิดว่ามีโนมชื่อแคทรีนา ชิมเมอร์สตาร์ในไอรอนฟอร์จขายเพิ่มให้ได้ เชื่อว่าเธอจะมาเฉพาะช่วงฮอลโลว์สเอนด์" },
        objectiveLabels = {
            event = { ["Clean up a stink bomb that's been dropped on Southshore!"] = "เก็บกวาดระเบิดเหม็นที่มีคนทิ้งไว้ใน Southshore!" },
        },
    },
    [8409] = { -- Ruined Kegs
        title = { "11:1410724334:433620633", "ถังเอลที่เสียหาย" },
        objective = { "71:1975244804:1412568252", "กลับไปหา Darkcaller Yanka ที่งาน Wickerman Festival ใน Tirisfal Glade" },
        description = { "246:1819378532:2040388522", "ใส่ไข่เน่าลงในถังได้สำเร็จแล้ว เอลชุดต่อ ๆ ไปจากโรงแรมเซาท์ชอร์ต้องเสียแน่!\n\nคุณควรกลับไปรายงานความสำเร็จแก่ดาร์กคอลเลอร์ แยงกาที่งานเทศกาลวิกเกอร์แมนในทิริสฟอลเกลดส์" },
        completion = { "289:212455672:1419562338", "อา สำเร็จ! เจ้าแสดงจิตวิญญาณแห่งฮอลโลว์สเอนด์ได้อย่างแท้จริง ต้องบอกว่าจิตวิญญาณแห่งฟอร์เซเคนต่างหาก!\n\n<ดาร์กคอลเลอร์ แยงกาหัวเราะและถูมือเข้าด้วยกัน>\n\nข้าชื่นใจจริง ๆ ที่เซาท์ชอร์ต้องดื่มเอลเสีย หรือไม่ก็อดดื่มไปเลย! ส่วนเจ้า รับขนมเหล่านี้ไป ข้าเชื่อว่าเจ้าจะใช้ประโยชน์จากมันได้ดี!" },
    },
    [8744] = { -- A Carefully Wrapped Present
        title = { "27:49239525:941134782", "ของขวัญที่ห่ออย่างประณีต" },
        completion = { "34:1836288824:412756225 N 53:1168276273:1734239679", "ป้ายบนของขวัญเขียนว่า:\n\nถึง {name}\n\nขอให้งานฉลองมหาเหมันต์ของเจ้ารื่นเริงและสดใส!" },
    },
    [8746] = { -- Metzen the Reindeer
        title = { "19:1466468117:1988868869", "เม็ตเซน กวางเรนเดียร์" },
        objective = { "358:593256711:1444361398", "ค้นหา Metzen the Reindeer โดยใช้บันทึกที่ได้รับเป็นเบาะแสว่าเขาถูกขังไว้ที่ใด\n\nเมื่อพบ Metzen ต้องมี Pouch of Reindeer Dust อยู่กับตัว เพื่อโรยผงบางส่วนบนเขา ผงนี้น่าจะปลดปล่อย Metzen จากพันธนาการได้\n\nเมื่อปล่อย Metzen แล้ว ให้นำ Pouch of Reindeer Dust กลับไปคืน Kaymard Copperpinch ใน Orgrimmar" },
        description = { "491:1558747823:754100000", "หายนะมาเยือนแล้ว! เม็ตเซน กวางเรนเดียร์ถูกลักพาตัว!\n\nเม็ตเซนเป็นหนึ่งในกวางเรนเดียร์แปดตัวของคุณปู่วินเทอร์ และเป็นทรัพย์สินของสโมกีวูดพาสเจอร์ส เราได้รับจดหมายเรียกค่าไถ่จากกลุ่มที่อ้างว่าจับเม็ตเซนไว้ ไม่ใช่แค่ฉบับเดียว แต่ถึงสองฉบับ! เทศกาลกำลังดำเนินอยู่ เงินของเราก็ตึงมือเต็มที! ได้โปรด หาเม็ตเซนแล้วพากลับมาให้เรา!\n\nอ่านจดหมายเรียกค่าไถ่หาเบาะแส แล้วโรยผงเรนเดียร์นี้บนตัวเขา มันจะปลดปล่อยเขาจากพันธนาการใด ๆ!\n\nได้โปรด รีบหน่อย!" },
        progress = { "N 225:1937100417:694144245", "{name}! เจ้าพบเขาหรือยัง? บันทึกในย่ามที่ข้าให้ไปมีข้อมูลพอจะหาเม็ตเซนพบไหม? ข้าไม่อยากคิดเลยว่าเจ้าพวกอันธพาลใจร้ายจะทำอะไรเขา... แต่เราไม่มีทางจ่ายค่าไถ่มหาศาลขนาดนั้นไหว!" },
        completion = { "268:1393140085:783644177 N 176:2038675749:2082343559", "เจ้าทำสำเร็จ! ไชโย!\n\nเม็ตเซนบินกลับมาที่คอกของคุณปู่วินเทอร์เมื่อครู่นี้เอง ใช่แล้ว เม็ตเซนบินได้จริง ๆ! ผงได้ผลอย่างยอดเยี่ยม ข้ารู้อยู่แล้ว เจ้าช่วยทั้งงานฉลองวินเทอร์เวลและสโมกีวูดพาสเจอร์สให้พ้นหายนะ ขอบคุณ {name}\n\nฟังนะ... เพราะสิ่งที่เจ้าทำ ข้าอยากให้เจ้ารับสิ่งนี้ไว้ มันพิเศษมาก ถ้าเจ้ามีสัตว์ขี่ ข้าว่าเจ้าจะสนุกกับมันแน่ สุขสันต์วินเทอร์เวล!" },
        required = { [21211] = { "22:280601440:828300374", "ถุงผงสำหรับกวางเรนเดียร์" } },
        objectiveLabels = {
            item = { ["Pouch of Reindeer Dust"] = "ถุงผงสำหรับกวางเรนเดียร์" },
        },
    },
    [8762] = { -- Metzen the Reindeer
        title = { "19:1466468117:1988868869", "เม็ตเซน กวางเรนเดียร์" },
        objective = { "359:1845077598:1275646107", "ค้นหา Metzen the Reindeer โดยใช้บันทึกที่ได้รับเป็นเบาะแสว่าเขาถูกขังไว้ที่ใด\n\nเมื่อพบ Metzen ต้องมี Pouch of Reindeer Dust อยู่กับตัว เพื่อโรยผงบางส่วนบนเขา ผงนี้น่าจะปลดปล่อย Metzen จากพันธนาการได้\n\nเมื่อปล่อย Metzen แล้ว ให้นำ Pouch of Reindeer Dust กลับไปคืน Wulmort Jinglepocket ใน Ironforge" },
        description = { "490:1058123884:1948197030", "หายนะมาเยือนแล้ว! เม็ตเซน กวางเรนเดียร์ถูกลักพาตัว!\n\nเม็ตเซนเป็นหนึ่งในกวางเรนเดียร์แปดตัวของคุณปู่วินเทอร์ และเป็นทรัพย์สินของสโมกีวูดพาสเจอร์ส เราได้รับจดหมายเรียกค่าไถ่จากกลุ่มที่อ้างว่าจับเม็ตเซนไว้ ไม่ใช่แค่ฉบับเดียว แต่ถึงสองฉบับ! เทศกาลกำลังดำเนินอยู่ เงินของเราก็ตึงมือเต็มที! ได้โปรด หาเม็ตเซนแล้วพากลับมาให้เรา!\n\nอ่านจดหมายเรียกค่าไถ่หาเบาะแส แล้วโรยผงเรนเดียร์นี้บนตัวเขา มันจะปลดปล่อยเขาจากพันธนาการใด ๆ!\n\nได้โปรด รีบหน่อย!" },
        progress = { "N 207:2008145133:1218415728", "{name}! บันทึกในย่ามที่ข้าให้ไปมีข้อมูลพอจะหาเม็ตเซนพบไหม? ข้าไม่อยากคิดเลยว่าเจ้าพวกอันธพาลใจร้ายจะทำอะไรเขา... แต่เราไม่มีทางจ่ายค่าไถ่มหาศาลขนาดนั้นไหว!" },
        completion = { "267:327060906:1625140896 N 176:2038675749:2082343559", "เจ้าทำสำเร็จ! ไชโย!\n\nเม็ตเซนบินกลับมาที่คอกของคุณปู่วินเทอร์เมื่อครู่นี้เอง ใช่แล้ว เม็ตเซนบินได้จริง ๆ! ผงได้ผลอย่างยอดเยี่ยม ข้ารู้อยู่แล้ว เจ้าช่วยทั้งงานฉลองวินเทอร์เวลและสโมกีวูดพาสเจอร์สให้พ้นหายนะ ขอบคุณ {name}\n\nฟังนะ... เพราะสิ่งที่เจ้าทำ ข้าอยากให้เจ้ารับสิ่งนี้ไว้ มันพิเศษมาก ถ้าเจ้ามีสัตว์ขี่ ข้าว่าเจ้าจะสนุกกับมันแน่ สุขสันต์วินเทอร์เวล!" },
        required = { [21211] = { "22:280601440:828300374", "ถุงผงสำหรับกวางเรนเดียร์" } },
        objectiveLabels = {
            item = { ["Pouch of Reindeer Dust"] = "ถุงผงสำหรับกวางเรนเดียร์" },
        },
    },
    [8763] = { -- The Hero of the Day
        title = { "19:2005465588:1538567001", "วีรชนประจำวัน" },
        objective = { "117:1120106564:1821171895", "นำ Deeprock Salt 1 ชิ้นและทอง 5 เหรียญไปให้เครื่อง Holly Preserver เครื่องใดก็ได้ แล้วคุณจะได้รับ Preserved Holly 5 ชิ้น" },
        description = { "495:1282249124:1504496027", "ฟังนะ... ที่จริงข้าไม่ควรบอกเรื่องนี้กับเจ้า แต่ในเมื่อเจ้าเป็นวีรชนประจำวัน...\n\nช่วงนี้มีฮอลลี่สดอยู่ทุกที่ แต่มันเก็บไว้ได้ไม่นาน เรามีเครื่องที่ถนอมฮอลลี่ได้ ทำให้มันไม่มีวันเสีย! เราใช้มันเพิ่มสีสันให้เทศกาล... และเพิ่มกำไรในฤดูร้อน!\n\nข้าจะให้เจ้าใช้เครื่องถนอม แต่เฉพาะถ้าเจ้าเป็นพ่อครัวชั้นครูเท่านั้น ต้องใช้เกลือดีปร็อกกับทองสอง สาม... เอาเป็นว่าห้าเหรียญก็แล้วกัน แล้วเจ้าจะได้ฮอลลี่ชุดงามไว้เก็บเอง" },
        progress = { "367:1900700892:1700565151", "มองครั้งแรก เครื่อง\"ถนอมฮอลลี่\"ดูเหมือนหม้อกลั่นชนิดหนึ่ง แต่เมื่อพิจารณาดี ๆ ก็เห็นว่าถูกดัดแปลงตามแบบก็อบลิน ทักษะทำอาหารของคุณช่วยให้เข้าใจการทำงานของมันได้\n\nในเครื่องมีฮอลลี่สดอยู่แล้ว เพียงเติมเกลือดีปร็อกกับทองห้าเหรียญ ก็เริ่มเดินเครื่องได้" },
        completion = { "247:1538372290:708383647", "เครื่องส่งเสียงครืนเบา ๆ พร้อมไอน้ำเล็กน้อยเมื่อเริ่มทำงาน ไม่นานมันก็หยุด โดยมีไอน้ำพุ่งออกมาอีกครั้งเป็นสัญญาณ ฝาเปิดออก เผยให้เห็นฮอลลี่ที่ถนอมแล้วชุดหนึ่ง!" },
        required = { [8150] = { "13:1356996729:236971052", "เกลือจากหินลึก" } },
        objectiveLabels = {
            item = { ["Deeprock Salt"] = "เกลือจากหินลึก" },
        },
    },
    [8767] = { -- A Gently Shaken Gift
        title = { "20:794616694:1907433467", "ของขวัญที่ถูกเขย่าเบา ๆ" },
        completion = { "95:1064216264:748630100 R 1:32:32 C 1:46:46", "ของขวัญชิ้นนี้ดูเหมือนถูกเขย่ามาสองสามครั้ง ป้ายเขียนว่า:\n\nถึง {class} ชาว{race}ผู้แสนพิเศษ" },
    },
    [8768] = { -- A Gaily Wrapped Present
        title = { "23:2046950662:450683020", "ของขวัญที่ห่ออย่างรื่นเริง" },
        completion = { "75:1912837497:1324944370", "ของขวัญที่ห่อเข้ากับเทศกาลชิ้นนี้มีชื่อคุณอยู่\n\nเดี๋ยวนะ เมื่อกี้มันขยับหรือเปล่า?" },
    },
    [8769] = { -- A Ticking Present
        title = { "17:775475589:1502882257", "ของขวัญที่ส่งเสียงติ๊กต็อก" },
        completion = { "77:357235255:1818371511", "ขอให้มีงานฉลองมหาเหมันต์อันรื่นเริง จากเพื่อน ๆ ที่สโมกีวูดพาสเจอร์ส" },
