        completion = { "95:1064216264:748630100 R 1:32:32 C 1:46:46", "ของขวัญชิ้นนี้ดูเหมือนถูกเขย่ามาสองสามครั้ง ป้ายเขียนว่า:\n\nถึง {class} ชาว{race}ผู้แสนพิเศษ" },
    },
    [8799] = { -- The Hero of the Day
        title = { "19:2005465588:1538567001", "วีรชนประจำวัน" },
        objective = { "117:46065486:1959887881", "นำ Deeprock Salt 1 ชิ้นและทอง 5 เหรียญไปให้เครื่อง Holly Preserver แล้วคุณจะได้รับ Preserved Holly 5 ชิ้น" },
        description = { "495:1282249124:1504496027", "ฟังนะ... ที่จริงข้าไม่ควรบอกเรื่องนี้กับเจ้า แต่ในเมื่อเจ้าเป็นวีรชนประจำวัน...\n\nช่วงนี้มีฮอลลี่สดอยู่ทุกที่ แต่มันเก็บไว้ได้ไม่นาน เรามีเครื่องที่ถนอมฮอลลี่ได้ ทำให้มันไม่มีวันเสีย! เราใช้มันเพิ่มสีสันให้เทศกาล... และเพิ่มกำไรในฤดูร้อน!\n\nข้าจะให้เจ้าใช้เครื่องถนอม แต่เฉพาะถ้าเจ้าเป็นพ่อครัวชั้นครูเท่านั้น ต้องใช้เกลือดีปร็อกกับทองสอง สาม... เอาเป็นว่าห้าเหรียญก็แล้วกัน แล้วเจ้าจะได้ฮอลลี่ชุดงามไว้เก็บเอง" },
        progress = { "367:1900700892:1700565151", "มองครั้งแรก เครื่อง\"ถนอมฮอลลี่\"ดูเหมือนหม้อกลั่นชนิดหนึ่ง แต่เมื่อพิจารณาดี ๆ ก็เห็นว่าถูกดัดแปลงตามแบบก็อบลิน ทักษะทำอาหารของคุณช่วยให้เข้าใจการทำงานของมันได้\n\nในเครื่องมีฮอลลี่สดอยู่แล้ว เพียงเติมเกลือดีปร็อกกับทองห้าเหรียญ ก็เริ่มเดินเครื่องได้" },
        completion = { "247:1538372290:708383647", "เครื่องส่งเสียงครืนเบา ๆ พร้อมไอน้ำเล็กน้อยเมื่อเริ่มทำงาน ไม่นานมันก็หยุด โดยมีไอน้ำพุ่งออกมาอีกครั้งเป็นสัญญาณ ฝาเปิดออก เผยให้เห็นฮอลลี่ที่ถนอมแล้วชุดหนึ่ง!" },
        required = { [8150] = { "13:1356996729:236971052", "เกลือจากหินลึก" } },
        objectiveLabels = {
            item = { ["Deeprock Salt"] = "เกลือจากหินลึก" },
        },
    },
    [8803] = { -- A Festive Gift
        title = { "14:1813348741:1334729694", "ของขวัญแห่งเทศกาล" },
        completion = { "35:1150527137:2134295277 N 111:604671662:1961820529", "ข้อความบนของขวัญเขียนว่า:\n\nถึง {name}\n\nหวังว่าสิ่งนี้จะช่วยให้เจ้าเผยแพร่คำอวยพรอันอบอุ่นและความรื่นเริงของเทศกาลไปทั่วอาเซรอธ\n\nจากคุณปู่วินเทอร์" },
    },
    [8827] = { -- Winter's Presents
        title = { "17:961101746:1969244836", "ของขวัญแห่งฤดูหนาว" },
        objective = { "98:1822567358:1408575026", "พูดคุยกับ Greatfather Winter ซึ่งอยู่ใกล้บริเวณร้าน Smokywood Pastures ใน Ironforge" },
        description = { "323:1849814973:1755489096", "ข้าได้ยินว่าคุณปู่วินเทอร์ได้รับการสนับสนุนอย่างใจกว้างจากสโมกีวูดพาสเจอร์ส และวางของขวัญสำหรับทุกคนไว้ใต้ต้นไม้ในไอรอนฟอร์จ ข้าก็อยากไป แต่ต้องเฝ้าเครื่อง PX-238 Winter Wondervolt\n\nแต่เจ้าควรไปดูให้ได้นะ ข้ามั่นใจว่าคุณปู่วินเทอร์มีของขวัญที่ติดชื่อเจ้าไว้บ้างแน่" },
        completion = { "169:1469504222:1320344651 R 1:32:32 C 176:1618388834:1757151249", "โอ้ โฮ่ สวัสดี! เจ้ามาที่นี่ได้ด้วยเหตุผลเดียวเท่านั้น คือมาเปิดของขวัญวินเทอร์เวล\n\nไม่ต้องห่วง คุณปู่วินเทอร์ไม่ลืม{class}ชาว{race}คนโปรดหรอก ลองดูใต้ต้นไม้ แล้วเจ้าจะพบของขวัญของตน\n\nในฤดูกาลแห่งการให้นี้ บางทีเพื่อน ๆ ของเจ้าอาจชอบรับผลิตภัณฑ์ชั้นเยี่ยมของสโมกีวูดพาสเจอร์สบ้างก็ได้นะ?" },
    },
    [8828] = { -- Winter's Presents
        title = { "17:961101746:1969244836", "ของขวัญแห่งฤดูหนาว" },
        objective = { "99:1903692998:2112933222", "พูดคุยกับ Great-father Winter ซึ่งอยู่ใกล้บริเวณร้าน Smokywood Pastures ใน Orgrimmar" },
        description = { "325:589331072:1778564967", "ข้าได้ยินว่าคุณปู่วินเทอร์ได้รับการสนับสนุนอย่างใจกว้างจากสโมกีวูดพาสเจอร์ส และวางของขวัญสำหรับทุกคนไว้ใต้ต้นไม้ในออร์กริมมาร์ ข้าก็อยากไป แต่ต้องเฝ้าเครื่อง PX-238 Winter Wondervolt\n\nแต่เจ้าควรไปดูให้ได้นะ ข้ามั่นใจว่าคุณปู่วินเทอร์มีของขวัญที่ติดชื่อเจ้าไว้บ้างแน่" },
        completion = { "170:263461834:1785136072 R 1:32:32 C 176:1618388834:1757151249", "โอ้ โฮ่ สวัสดี! เจ้ามาที่นี่ได้ด้วยเหตุผลเดียวเท่านั้น คือมาเปิดของขวัญวินเทอร์เวล\n\nไม่ต้องห่วง คุณปู่วินเทอร์ไม่ลืม{class}ชาว{race}คนโปรดหรอก ลองดูใต้ต้นไม้ แล้วเจ้าจะพบของขวัญของตน\n\nในฤดูกาลแห่งการให้นี้ บางทีเพื่อน ๆ ของเจ้าอาจชอบรับผลิตภัณฑ์ชั้นเยี่ยมของสโมกีวูดพาสเจอร์สบ้างก็ได้นะ?" },
    },
    [8860] = { -- New Year Celebrations!
        title = { "22:958029654:530370958", "ฉลองปีใหม่!" },
        objective = { "63:943175093:558273911", "นำ Smokywood Supplies ไปให้ Innkeeper Allison ใน Stormwind" },
        description = { "407:924581949:1718083067 N 78:1651638369:232348865", "สตอร์มวินด์กำลังจัดงานฉลองปีใหม่! วันนี้มีเหล้าให้ดื่มฟรีตลอดวัน และตอนกลางคืนจะมีการแสดงดอกไม้ไฟ! น่าจะดีทีเดียว... แต่บูตตีเบย์ก็มีงานเลี้ยงวันนี้เหมือนกัน ข้าพนันว่าที่นั่นต้องดีกว่าอีก!\n\nเอาเถอะ เจ้าของโรงแรมแอลลิสันในสตอร์มวินด์ต้องการเสบียงจากสโมกีวูดพาสเจอร์สไปเลี้ยงผู้ร่วมงาน เจ้าช่วยนำไปส่งให้หน่อยได้ไหม!\n\nขอบคุณ {name}! เจ้าของโรงแรมแอลลิสันอยู่ที่กิลเด็ดโรส ในย่านการค้าของสตอร์มวินด์" },
        progress = { "100:1152645026:1669669248", "สวัสดี! มาร่วมงานเลี้ยงหรือ! หรือเพียงอยากพักเท้าที่เมื่อยล้า..." },
        completion = { "116:265169903:2001809214 N 93:1835452652:40741076", "โอ้ เสบียงสโมกีวูดของข้า! ยอดเยี่ยม! ข้าต้องใช้เลี้ยงทุกคนที่เข้ามาร่วมงานฉลองในเมือง!\n\nขอบคุณ {name} รับสิ่งนี้เป็นค่าจ้าง และอย่าลืมไปดื่มกับเต้นรำกับผู้ร่วมงานข้างนอกด้วย!" },
        required = { [21545] = { "18:1977825882:1669481679", "เสบียงของ Smokywood" } },
        steps = { { "18:1977825882:1669481679", "เสบียงของ Smokywood" } },
    },
    [8861] = { -- New Year Celebrations!
        title = { "22:958029654:530370958", "ฉลองปีใหม่!" },
        objective = { "64:315788803:987822841", "นำ Smokywood Supplies ไปให้ Innkeeper Pala ใน Thunder Bluff" },
        description = { "407:1777410973:645104503 N 64:1208326642:1695731106", "ธันเดอร์บลัฟฟ์กำลังจัดงานฉลองปีใหม่! ที่นั่นมีเหล้าให้ดื่มฟรีตลอดวัน และตอนกลางคืนจะมีการแสดงดอกไม้ไฟ!\n\nน่าจะดีทีเดียว... แต่บูตตีเบย์ก็มีงานเลี้ยงวันนี้เหมือนกัน ข้าพนันว่าที่นั่นต้องดีกว่าอีก!\n\nเอาเถอะ เจ้าของโรงแรมพาลาในธันเดอร์บลัฟฟ์ต้องการเสบียงจากสโมกีวูดพาสเจอร์สไปเลี้ยงผู้ร่วมงาน เจ้าช่วยนำไปส่งให้หน่อยได้ไหม!\n\nขอบคุณ {name}! เจ้าของโรงแรมพาลาอยู่ในโรงแรมใกล้สะพานไปฮันเตอร์สไรส์" },
        progress = { "10:10763625:219111161 C 105:1298235003:385351502", "สวัสดี {class}! เจ้ามาธันเดอร์บลัฟฟ์เพื่อร่วมงานฉลองของเราหรือ? หรือมาแวะพักกีบที่อ่อนล้าระหว่างการล่า?" },
        completion = { "106:2019876415:824554278 N 157:345113719:957542953", "โอ้ ดีมาก! เสบียงเหล่านี้จะช่วยเลี้ยงผู้คนของเราที่มาร่วมฉลองปีใหม่!\n\nข้าขอบใจเจ้า {name} เจ้าติดหนี้ข้าแล้วนะ รับเหรียญเหล่านี้ไป... และฟังคำแนะนำของข้า ดื่มจากถังข้างนอกให้เต็มที่ แล้วร่วมเต้นรำฉลองกับผู้คนของเรา!" },
        required = { [21545] = { "18:1977825882:1669481679", "เสบียงของ Smokywood" } },
        steps = { { "18:1977825882:1669481679", "เสบียงของ Smokywood" } },
    },
    [8897] = { -- Dearest Colara,
        title = { "15:496371931:777418800", "ถึงโคลาราที่รัก" },
        objective = { "96:1056901267:1098388569", "นำ Lieutenant Heldric's Carefully Penned Note ไปให้ Colara Dean ด้านนอกธนาคารใน Stormwind" },
        description = { "455:1922710675:1131732479", "ข้าต้องเฝ้ายามอยู่ที่ประตูนี้ แต่ก็คอยห่วงโคลารา คนรักของข้าเสมอ ถ้าโชคดีถึงจะได้พบเธอสักสองสามชั่วโมง แล้วก็ดูข้าสิ ได้เงินเดือนแค่นายทหารชั้นผู้น้อย และอาจถูกเรียกไปแนวหน้าเมื่อไรก็ได้\n\nเธอจะลืมข้าไปหรือเปล่า? ในเมืองมีผู้ชายตั้งมากมาย คนรวยก็เยอะ\n\nเอาเถอะ ข้าเขียนอะไรไว้นิดหน่อย... ไม่ได้สำคัญอะไรนัก แต่ถ้าเจ้านำไปให้เธอแทนข้าได้ก็คงดีมาก" },
        progress = { { "53:886291734:808168715", "37:1894485113:486097917" }, "สวัสดี! มีอะไรให้ข้าช่วยหรือ?" },
        completion = { "205:1212693810:846180963", "โอ้ หวานจัง! นี่เป็นครั้งแรกที่เขาส่งอะไรมาให้ข้า เจ้าคิดว่าเขาเริ่มจริงจังแล้วหรือ?\n\nโคลารา เฮลดริกหรือ? ข้าว่าฟังดูเข้าท่าดีนะ อ๊ะ แต่ข้าคิดไปไกลแล้ว ขอบคุณนะ" },
        required = { [21921] = { "21:468228190:1361161608", "ข้อความที่เขียนอย่างประณีต" } },
        steps = { { "21:468228190:1361161608", "ข้อความที่เขียนอย่างประณีต" } },
    },
    [8898] = { -- Dearest Colara,
        title = { "15:496371931:777418800", "ถึงโคลาราที่รัก" },
        objective = { "72:1323139732:264559791", "นำ Creased Letter ไปให้ Colara Dean ด้านนอกธนาคารใน Stormwind" },
        description = { "313:1823252717:699797886", "ข้าพบหญิงสาวคนหนึ่งในสตอร์มวินด์ คราวก่อนที่ไปทำธุระของธนาคาร เธอขโมยหัวใจข้าไป ตอนนี้ข้าหยุดคิดถึงเธอไม่ได้เลย! ข้าอยากส่งข้อความนี้ให้เธอ เขียนใหม่มาตั้งสิบสองรอบแล้ว!\n\nตอนนี้จดหมายมีมากเหลือเกิน และข้าอยากแน่ใจว่ามันจะไปถึง\n\nถ้าเจ้าจะไปทางนั้น ช่วยข้าหน่อยได้ไหม?" },
        progress = { "53:886291734:808168715", "สวัสดี รูปหล่อ มีอะไรให้ข้าช่วยหรือ?" },
        completion = { "120:219306974:968837951", "ทอร์เม็กหรือ? อ้อ ใช่ ข้าจำเขาได้ เขามีเครางามกับรอยยิ้มที่ซ่อนอยู่ข้างใต้\n\nอา ไม่อยากเชื่อเลยว่าเขาจะจำข้าได้!" },
        required = { [21920] = { "14:1296423608:1392073141", "จดหมายมีรอยพับ" } },
        steps = { { "14:1296423608:1392073141", "จดหมายมีรอยพับ" } },
    },
    [8899] = { -- Dearest Colara,
        title = { "15:496371931:777418800", "ถึงโคลาราที่รัก" },
        objective = { "75:249650741:1106590941", "นำ Immaculate Letter ไปให้ Colara Dean ด้านนอกธนาคารใน Stormwind" },
        description = { "297:1205642730:1173100490", "จะบรรยายความงามของเธออย่างไรดี? ถ้อยคำที่สั่งสมมาหลายพันปี กลับไม่อาจช่วยให้ข้าหาคำพูดได้\n\nเหล่ามรรตัยทำให้จิตใจเราสับสน จนกลายเป็นคนโง่พูดจาไม่เป็นภาษา\n\nข้าจ้องข้อความเหล่านี้นานเกินไปแล้ว ไม่อาจขัดเกลาความหมายให้งดงามกว่านี้ได้อีก ไม่ได้ เธอต้องได้รับมันเดี๋ยวนี้ ไม่เช่นนั้นชายอื่นที่มาจีบคงแย่งความสนใจเธอไปแน่" },
        progress = { "53:886291734:808168715", "สวัสดี รูปหล่อ มีอะไรให้ข้าช่วยหรือ?" },
        completion = { "59:790497571:2030970116", "ข้าไม่เคยได้รับอะไรแบบนี้มาก่อน งดงามเหลือเกิน!" },
        required = { [21925] = { "17:924002630:378760349", "จดหมายไร้ตำหนิ" } },
        steps = { { "17:924002630:378760349", "จดหมายไร้ตำหนิ" } },
    },
    [8900] = { -- Dearest Elenia,
        title = { "15:411963623:738967588", "ถึงเอเลเนียที่รัก" },
        objective = { "82:1672781171:815132069", "นำ Slightly Creased Note ไปให้ Elenia Haydon ใกล้ธนาคารใน Undercity" },
        description = { "395:281578417:96317528", "เธอเศร้ามาก ข้ามองออกเมื่อมองข้ามสภาพของเธอไปได้ ข้าหมายถึง เธอดูเศร้า เป็นเจ้าก็คงเศร้าเหมือนกันใช่ไหม?\n\nแต่พอได้คุยกัน เราก็รู้สึกผูกพัน ข้าไม่คิดว่าจะมีใครเข้าใจสิ่งที่ข้าคิดได้ แต่เธอเข้าใจ\n\nพอข้าบอกคนอื่น พวกเขากลับหัวเราะเยาะ ข้าจึงไม่เคยคุยกับเธออีกเลย แต่ข้าคิดถึงเธอ เจ้านำจดหมายนี้ไปให้เธอแทนข้าได้ไหม? ข้าอยากแน่ใจว่ามันถึงมือเธอ" },
        progress = { "39:1643827442:919163172", "โอ้ มีเหตุใดให้ข้าได้รับเกียรติจากการมาเยือนครั้งนี้หรือ?" },
        completion = { "145:918465:1889912746", "คงคาดไม่ถึงว่าออร์คจะใช้ถ้อยคำได้งดงามขนาดนี้ แน่นอนว่าเราไม่เคยมีโอกาสรู้จักพวกเขาจริง ๆ จนกระทั่งตอนนี้ ขอบคุณที่นำสิ่งนี้มาให้ข้า" },
        required = { [21926] = { "21:1844975110:641912053", "ข้อความที่มีรอยพับเล็กน้อย" } },
        steps = { { "21:1844975110:641912053", "ข้อความที่มีรอยพับเล็กน้อย" } },
    },
    [8901] = { -- Dearest Elenia,
        title = { "15:411963623:738967588", "ถึงเอเลเนียที่รัก" },
        objective = { "85:857061227:1250577733", "นำ Carefully Written Letter ไปให้ Elenia Haydon ใกล้ธนาคารใน Undercity" },
        description = { "392:481212103:847683235", "เจ้าเคยรู้จักความรักหรือไม่ คนหนุ่มสาว? มันเคยเป็นเรื่องแปลกสำหรับข้า จนเมื่อไม่นานมานี้ข้าได้พบหญิงสาวจากอันเดอร์ซิตี้ชื่อเอเลเนีย แค่คนเผ่าพันธุ์ข้าจะมองคนนอกเผ่าก็หายากแล้ว ไม่ต้องพูดถึงฟอร์เซเคนเลย\n\nแต่ตอนนี้ข้าคิดถึงเธอทั้งวันทั้งคืน\n\nถ้าทำได้ เจ้านำจดหมายนี้ไปให้เธอหน่อยได้ไหม? ข้าอยากให้เธอมาที่มัลกอร์ หวังว่าเธอจะตอบตกลง" },
        progress = { "39:1643827442:919163172", "โอ้ มีเหตุใดให้ข้าได้รับเกียรติจากการมาเยือนครั้งนี้หรือ?" },
        completion = { "266:1845387098:2048803355", "เท็มมาเขียนถ้อยคำอ่อนโยนให้ข้าเหลือเกิน แต่ถึงคำพูดของเขาจะทำให้ข้าซาบซึ้ง ข้าก็ไม่อาจคิดรักกับทอเรนได้ เราต่างกันเกินไปทั้งความคิด ร่างกาย และจิตใจ\n\nดีแล้วที่ข้าไม่ต้องฟังความรู้สึกเหล่านี้จากเขาต่อหน้า ข้าคงทนทำให้เขาใจสลายไม่ได้" },
        required = { [22264] = { "24:30858461:364575579", "จดหมายที่บรรจงเขียน" } },
        steps = { { "24:30858461:364575579", "จดหมายที่บรรจงเขียน" } },
    },
    [8902] = { -- Dearest Elenia,
        title = { "15:411963623:738967588", "ถึงเอเลเนียที่รัก" },
        objective = { "85:704029517:418068051", "นำ Lovingly Composed Letter ไปให้ Elenia Haydon ใกล้ธนาคารใน Undercity" },
        description = { "391:1505185823:730977482", "เมื่อนานมาแล้ว ราวกับเป็นอีกชีวิตหนึ่ง ข้าเคยหมั้นหมายกับเอเลเนีย คนรักตั้งแต่วัยเยาว์ ข้าไม่ได้คิดถึงเธอมาหลายปี แต่ระยะหลังเธอมักวนเวียนอยู่ในความคิดของข้า\n\nบางที แม้ทุกอย่างจะผ่านพ้นไปมากมายแล้ว เราอาจยังเหลือที่ว่างในชีวิตให้ความรักของกันและกัน\n\nข้ามั่นใจว่าเธอก็คงเปลี่ยนไปเช่นกัน เจ้านำจดหมายนี้ไปให้เธอแทนข้าได้ไหม? ข้าประหม่าเกินกว่าจะมอบให้เอง" },
        progress = { "39:1643827442:919163172", "โอ้ มีเหตุใดให้ข้าได้รับเกียรติจากการมาเยือนครั้งนี้หรือ?" },
        completion = { "47:13413955:739920571 N 282:1352349083:1552417895", "สิ่งนี้ทำให้ข้านึกถึงความทรงจำเมื่อนานมาแล้ว ราวกับเป็นอีกชีวิตหนึ่ง {name} เอเลเนีย ทอร์ นั่นคงจะเป็นชื่อของข้า รู้ไหม เราจะจัดพิธีอันงดงามริมทะเลสาบ เมื่อเขาปลดประจำการ เราก็จะหาฟาร์มสักแห่งไปใช้ชีวิตบั้นปลาย\n\nตอนนั้นเป็นเพียงความฝันเรียบง่าย\n\nแต่ถ้าเขาเห็นข้าตอนนี้ ข้าสงสัยว่าเขาจะยังเห็นเอเลเนียในตัวข้าหรือไม่ คงเห็นเพียงเนื้อหนังเย็นเฉียบกับหัวใจที่ตายแล้ว..." },
        required = { [22265] = { "24:1719423023:1940431986", "จดหมายที่เรียบเรียงด้วยความรัก" } },
        steps = { { "24:1719423023:1940431986", "จดหมายที่เรียบเรียงด้วยความรัก" } },
    },
    [8903] = { -- Dangerous Love
        title = { "14:2031691166:2048690403", "รักอันตราย" },
        objective = { "74:2096747358:1727488058", "หา Stormwind Guard's Card แล้วนำกลับไปให้ Aristan Mottar ใน Stormwind" },
        description = { "366:909940644:1138791861", "การระบาดของความรักครั้งนี้มีบางอย่างผิดธรรมชาติ มันไม่เหมาะสม ขัดหูขัดตา และในกรณีเลวร้ายที่สุดอาจคุกคามความปลอดภัยของอัลไลแอนซ์เอง\n\nลองคิดดูสิ ถ้าทหารยามถูกอาการประหลาดนี้ครอบงำด้วยล่ะ? ต้องทำอะไรสักอย่าง\n\nไปหาทหารยามสักคนที่นี่ในสตอร์มวินด์ แล้วดูว่าเขาหลงไปกับเรื่องไร้สาระนี้หรือไม่" },
        progress = { "70:794269450:366147490", "ข้ากังวลถูกแล้วใช่ไหม? ทหารยามเป็นโรคคลั่งรักนี้ด้วยหรือ?" },
        completion = { "129:1571212189:220171474", "เป็นเรื่องจริงสินะ เหลือเชื่อจริง ๆ มันเกิดขึ้นได้อย่างไร? ขอข้าคิดสักครู่ ต้องมีเหตุผลอยู่เบื้องหลังเรื่องนี้แน่" },
        required = { [22143] = { "22:612383733:967035650", "การ์ดของทหารยาม Stormwind" } },
        steps = { { "22:612383733:967035650", "การ์ดของทหารยาม Stormwind" } },
    },
    [8904] = { -- Dangerous Love
        title = { "14:2031691166:2048690403", "รักอันตราย" },
        objective = { "76:815978193:556419283", "หา Guardian's Moldy Card แล้วนำไปให้ Fenstad Argyle ใน Undercity" },
        description = { "401:1141163282:1727446246", "การระบาดของความรักครั้งนี้มีบางอย่างผิดธรรมชาติ น่าขยะแขยง และเมื่อมันลดความพร้อมในการป้องกันตัวของเรา ก็อาจคุกคามพวกเราทั้งหมดได้\n\nแค่ผู้คนของเรามากมายหลงไปกับพฤติกรรมไร้สาระนี้ก็แย่พอแล้ว แต่ข้าคิดว่ามันลามไปถึงผู้พิทักษ์ของเรา ซึ่งควรจะไม่หวั่นไหวกับเรื่องเช่นนี้\n\nจงหาผู้พิทักษ์สักคน แล้วดูว่าเขาหลงไปกับเรื่องไร้สาระนี้ด้วยหรือไม่" },
        progress = { "61:1535682264:908118095", "ข้ากังวลถูกแล้วใช่ไหม? ผู้พิทักษ์โง่เง่าของเราถูกครอบงำแล้วหรือ?" },
        completion = { "129:1571212189:220171474", "เป็นเรื่องจริงสินะ เหลือเชื่อจริง ๆ มันเกิดขึ้นได้อย่างไร? ขอข้าคิดสักครู่ ต้องมีเหตุผลอยู่เบื้องหลังเรื่องนี้แน่" },
        required = { [22145] = { "21:1168395692:57722800", "การ์ดขึ้นราของผู้พิทักษ์" } },
        steps = { { "21:1168395692:57722800", "การ์ดขึ้นราของผู้พิทักษ์" } },
    },
    [8979] = { -- Fenstad's Hunch
        title = { "15:1516617445:89911067", "ลางสังหรณ์ของเฟนสตัด" },
        objective = { "96:557513081:49151887", "นำ Cologne Bottle 1 ขวดและ Perfume Bottle 1 ขวดไปให้ Apothecary Zinge ที่ Apothecarium ใน Undercity" },
        description = { "452:1835195150:605971485", "ข้าเชื่อว่ารู้ต้นเหตุของพฤติกรรมช่วงนี้แล้ว เจ้าได้กลิ่นหอมใหม่ที่ลอยมาตามลม กลบกลิ่นเหม็นของคลองไหม? โคโลญกับน้ำหอมแบบใหม่ที่กำลังเป็นที่นิยมนั่นไง\n\nความคิดของเราถูกการเล่นแร่แปรธาตุชั่วร้ายทำให้มัวหมอง\n\nมีวิธีเดียวที่จะรู้แน่ นำโคโลญกับน้ำหอมอย่างละขวดไปให้สหายข้า หมอยาซิงจ์ ราชสมาคมหมอยาจะค้นหาความจริงได้\n\nเมื่อเจ้ากลับมา ข้าจะคืนเงินค่าซื้อของให้" },
        progress = { "20:217097346:571694164", "มีอะไรให้ข้ารับใช้หรือ?" },
        completion = { "199:1208802726:2078385866", "อีกเรื่องที่เฟนสตัดหมกมุ่นสินะ เขาคิดว่าราชสมาคมหมอยาไม่มีอะไรดีกว่าการสืบสวนเล็ก ๆ น้อย ๆ ของเขาให้ทำหรือ?\n\nก็ได้ ข้าจะตามใจเขาอีกครั้ง" },
        required = { [21833] = { "14:718714730:1761811256", "ขวดโคโลญ" }, [21829] = { "14:691313061:434016561", "ขวดน้ำหอม" } },
        objectiveLabels = {
            item = { ["Cologne Bottle"] = "ขวดโคโลญ", ["Perfume Bottle"] = "ขวดน้ำหอม" },
        },
    },
    [8980] = { -- Zinge's Assessment
        title = { "18:24246117:888029724", "ผลวิเคราะห์ของซิงจ์" },
        objective = { "59:555770181:1290874819", "กลับไปหา Fenstad Argyle ด้านนอกธนาคารใน Undercity" },
        description = { "324:2083656230:1430330514", "คาดไม่ถึงจริง ๆ ดูเหมือนเฟนสตัดอาจพบเบาะแสเข้าจริง ๆ ข้าพบร่องรอยของสารที่ใช้ในยาควบคุมจิตใจ\n\nไม่ใช่เรื่องไม่เคยได้ยินที่น้ำหอมจะมีสารพวกนี้อยู่บ้าง แต่ส่วนผสมบางอย่างที่ข้าตรวจพบ... นี่เป็นการเล่นแร่แปรธาตุขั้นสูง ระดับความสามารถของสมาชิกราชสมาคมหมอยาเลยทีเดียว" },
        completion = { "161:873494927:436562818", "ข้าคิดถูกสินะ เราจะเสียเวลาไม่ได้ ต้องหาต้นตอของเครื่องหอมแปดเปื้อนเหล่านี้\n\nเอ้านี่ คืนเงินที่เจ้าจ่ายซื้อโคโลญกับน้ำหอม" },
    },
    [8981] = { -- Gift Giving
        title = { "11:965760185:1456498504", "มอบของขวัญ" },
        progress = { "81:1412003019:360824888", "เจ้ามามอบของขวัญแห่งความรักและความชื่นชมให้ผู้นำคนโปรดหรือ?" },
        completion = { "170:1703003722:1476069668", "ยอดเยี่ยม! ยอดเยี่ยม! ข้าจะเพิ่มมันเข้ากับกองของขวัญอื่น ๆ\n\nไม่คิดเลยว่าจะมากขนาดนี้! พวกเจ้าต้องรักผู้นำของตนจริง ๆ\n\nทีนี้ ขอข้าเพิ่มยอดนับอีกหนึ่ง..." },
        description = { "81:1412003019:360824888", "เจ้ามามอบของขวัญแห่งความรักและความชื่นชมให้ผู้นำคนโปรดหรือ?" },
    },
    [8982] = { -- Tracing the Source
        title = { "18:1664029525:951817353", "ตามหาต้นตอ" },
        objective = { "45:631933639:1789647829", "พูดคุยกับ Innkeeper Norman ใน Undercity" },
        description = { "173:842602637:291251274", "เราต้องรู้ว่าใครเป็นผู้จัดหา ข้าเห็นหมอยาแคทรีนามีน้ำหอมขวดหนึ่งเก็บอยู่ในกระเป๋า เธอบอกว่าซื้อจากนอร์แมน เจ้าของโรงแรม" },
        completion = { "208:2027532932:1192435602", "อา ใช่ ข้าเพิ่งได้รับน้ำหอมกับโคโลญมาขายเมื่อไม่นานนี้ ไม่รู้ว่าจะเก็บไว้บนชั้นได้นานแค่ไหน ดูเหมือนทุกคนจะซื้อเท่าไรก็ไม่พอ\n\nถ้าถามข้า ข้าก็ไม่เห็นว่ามันวิเศษตรงไหน" },
    },
    [8983] = { -- Tracing the Source
        title = { "18:1664029525:951817353", "ตามหาต้นตอ" },
        objective = { "77:727883480:1606442803", "พูดคุยกับ Mara Rennick ที่ร้านตัดเสื้อใน Mage Quarter ของ Undercity" },
        description = { "260:1145808367:1664781037", "สินค้าข้ามีอะไรผิดปกติหรือ? ข้าไม่เคยเห็นผู้คนอยากได้อะไรมากขนาดนี้มาก่อน\n\nข้าซื้อมาจากพ่อค้าชื่อมารา เรนนิก เธอเพิ่งเข้ามาในเมือง\n\nเธอพูดว่ามีสินค้าบางอย่างต้องนำไปส่งช่างตัดเสื้อในย่านเมจ" },
        completion = { { "241:1215813120:250925805", "241:1097240525:51298848" }, "เกรงว่าข้าขายน้ำหอมกับโคโลญทั้งหมดให้นอร์แมน เจ้าของโรงแรมไปแล้ว ถ้าเจ้าอยากได้ ก็ควรไปคุยกับเขา ถ้าเขายังมีเหลือนะ\n\nแต่อย่าเสียเวลาเลย ข้าคิดว่าเจ้าจะพบว่ากลิ่นหอมนี้ชวนหลงใหลจนห้ามใจไม่อยู่" },
    },
    [8984] = { -- The Source Revealed
        title = { "19:835791166:731958188", "เปิดเผยต้นตอ" },
        objective = { "81:1357411168:1384901560", "ค้นหา Apothecary Staffron Lerent ใน Hillsbrad Foothills เลย Ravenholdt Manor ไป" },
        description = { "401:62662922:1242454650", "ฟังนะ การกระทำของหมอยานอกคอกไม่ใช่เรื่องของข้า ถ้าเขากำลังบ่อนทำลายพวกเรา ก็ให้ข้าเป็นคนแรกที่ชี้ทางที่ถูกต้องแก่เจ้าแล้วกัน\n\nถ้าเขาบริสุทธิ์ เขาก็ไม่มีอะไรต้องปิดบัง จริงไหม?\n\nข้าซื้อสินค้ามาจากหมอยาสตัฟฟรอน เลอเรนต์ เขาทำงานในที่เปลี่ยวเลยคฤหาสน์เรเวนโฮลด์ไป บนเนินเขาเหนือฮิลส์แบรด พูดตามตรง ข้าก็คิดว่าเขาแปลกอยู่หน่อย ๆ" },
        completion = { "488:636788258:824866544", "ใช่ ข้าเป็นคนทำเครื่องหอมเหล่านั้น กลิ่นวิเศษใช่ไหม? ชวนหลงใหลจนห้ามใจไม่อยู่\n\nเมื่อนักรบทั้งอัลไลแอนซ์และฮอร์ดตกอยู่ในห้วงแห่งความรัก พวกเขาก็จะไร้พลังหยุดยั้งการผงาดของสภาเงา\n\nพวกเขาจะอ่อนแอ ไม่ทันเตรียมตัว เมื่อมัวกังวลถึงคนที่รัก ก็จะสูญเสียความเฉียบคม\n\nคำตอบช่างง่ายดายนัก ทำไมข้าต้องใช้เวลานานเหลือเกินกว่าจะคิดได้? จุดอ่อนของทุกคนอยู่ที่หัวใจ และเจ้าไม่อาจทำอะไรหยุดสิ่งที่จะต้องเกิดขึ้นได้" },
    },
    [8993] = { -- Gift Giving
        title = { "11:965760185:1456498504", "มอบของขวัญ" },
        progress = { "81:1412003019:360824888", "เจ้ามามอบของขวัญแห่งความรักและความชื่นชมให้ผู้นำคนโปรดหรือ?" },
        completion = { "170:1703003722:1476069668", "ยอดเยี่ยม! ยอดเยี่ยม! ข้าจะเพิ่มมันเข้ากับกองของขวัญอื่น ๆ\n\nไม่คิดเลยว่าจะมากขนาดนี้! พวกเจ้าต้องรักผู้นำของตนจริง ๆ\n\nทีนี้ ขอข้าเพิ่มยอดนับอีกหนึ่ง..." },
        description = { "81:1412003019:360824888", "เจ้ามามอบของขวัญแห่งความรักและความชื่นชมให้ผู้นำคนโปรดหรือ?" },
    },
    [9025] = { -- Morgan's Discovery
        title = { "18:1222524734:978326370", "การค้นพบของมอร์แกน" },
        objective = { "72:1307800016:1019747868", "กลับไปหา Aristan Mottar ด้านนอกธนาคารใน Trade District ของ Stormwind" },
        description = { "272:258253568:923541526", "ให้ตายสิ ดูเหมือนอาริสตันอาจพบเบาะแสเข้าจริง ๆ ข้าพบร่องรอยของสารที่ใช้ในยาเสน่ห์และยาดัดแปลงจิตใจอันร้ายกาจ\n\nไม่ใช่เรื่องไม่เคยได้ยินที่น้ำหอมจะมีสารพวกนี้อยู่บ้าง แต่ส่วนผสมบางอย่างที่ข้าตรวจพบ... ชักได้กลิ่นแปลก ๆ แล้วสิ" },
        completion = { "210:46078602:1498563704", "แม้ข้าจะคาดไว้แล้ว แต่พอรู้ว่าข้อสงสัยเป็นจริงก็ยังน่าหนักใจ เราต้องพิจารณาก้าวต่อไปอย่างรอบคอบ\n\nเอ้านี่ คืนเงินที่เจ้าจ่ายซื้อโคโลญกับน้ำหอม" },
    },
    [9026] = { -- Tracing the Source
        title = { "18:1664029525:951817353", "ตามหาต้นตอ" },
        objective = { "78:1692918112:1785669512", "พูดคุยกับ Innkeeper Allison ที่ The Gilded Rose ใน Trade District ของ Stormwind" },
        description = { "204:961540887:1563468954", "เราต้องหาต้นตอให้พบ ข้าเห็นคนเข้าออกกิลเด็ดโรสมากกว่าปกติ รวมทั้งทหารยามด้วย ไปคุยกับแอลลิสัน ถ้าเธอเป็นคนขาย เธอก็บอกได้ว่าของมาจากไหน" },
        completion = { "232:1723674400:1721504849", "อ้อ ใช่ ข้าเพิ่งได้น้ำหอมกับโคโลญมาขายเมื่อไม่นานนี้ มันขายดีเสียจนไม่รู้ว่าจะมีของบนชั้นได้นานแค่ไหน\n\nถ้าถามข้า มันก็น่าเบื่ออยู่นะ ทุกคนมีกลิ่นเหมือนกันหมดหรือ? กลิ่นหอมมากก็จริง แต่ถึงอย่างนั้นก็เถอะ" },
    },
    [9027] = { -- Tracing the Source
        title = { "18:1664029525:951817353", "ตามหาต้นตอ" },
        objective = { "71:1259584828:1642788457", "พูดคุยกับ Evert Sorisam ที่ The Finest Thread ริม Canals ของ Stormwind" },
        description = { "323:1272234636:71959985", "โคโลญมีอะไรแปลกหรือ? ก็เป็นไปได้ ข้าไม่เคยเห็นผู้คนอยากได้สินค้าชิ้นเดียวกันมากขนาดนี้มาก่อน\n\nฟังนะ ถ้ามันมีอะไรผิดปกติ ข้าก็อยากรู้เหมือนกัน ข้าซื้อมาจากพ่อค้าชื่อเอเวิร์ต โซริแซม เขาเพิ่งเข้ามาในเมือง\n\nเขาพูดว่ามีสินค้าบางอย่างจะนำไปส่งที่เดอะไฟเนสต์เธรด" },
        completion = { { "356:1074210579:2090110018", "356:1100749493:1965158362" }, "ใช่ แน่นอน เครื่องหอมเหล่านั้นเป็นสินค้าขายดีที่สุดของเทศกาลนี้ เจ้าคงเป็นคนที่ห้าหรือหกในชั่วโมงนี้ที่มาถามถึงมัน\n\nเกรงว่าของข้าจะขายหมดแล้ว ถ้าเจ้าอยากได้ ควรไปคุยกับแอลลิสัน เจ้าของโรงแรมกิลเด็ดโรส\n\nแต่อย่าเสียเวลาเลย ข้าคิดว่าเจ้าจะพบว่ากลิ่นหอมนี้ชวนหลงใหลจนห้ามใจไม่อยู่" },
    },
    [9028] = { -- The Source Revealed
        title = { "19:835791166:731958188", "เปิดเผยต้นตอ" },
        objective = { "83:1541500473:3144616", "ค้นหา Apothecary Staffron Lerent ใน Hillsbrad Foothills ด้านหลัง Ravenholdt Manor" },
        description = { "487:647221636:1967347389", "อะไรนะ? กบฏหรือ? ไม่ ไม่ ข้ารับรองว่าไม่มีเจตนาร้ายเลย\n\nการช่วยคนที่อยากให้พิธีเกี้ยวพาราสีอันแสนทรมานง่ายขึ้นมันผิดนักหรือ? เอาน่า นั่นไม่ใช่อาชญากรรม\n\nเพื่อพิสูจน์ว่าข้าไม่คิดร้าย ข้าจะบอกแหล่งสินค้าของข้าด้วยซ้ำ\n\nคนชื่อสตัฟฟรอน เลอเรนต์ส่งมันมาให้ข้า เป็นหมอยาอะไรสักอย่าง ข้าไม่เคยพูดกับเขา\n\nก็อบลินคนกลางของเราบอกว่าเขาทำงานอยู่บนเชิงเขาเหนือฮิลส์แบรด เลยคฤหาสน์เรเวนโฮลด์ลึกลับแห่งนั้นไป ขอให้เจ้าโชคดีในการตามหาเขา" },
        completion = { "488:636788258:824866544", "ใช่ ข้าเป็นคนทำเครื่องหอมเหล่านั้น กลิ่นวิเศษใช่ไหม? ชวนหลงใหลจนห้ามใจไม่อยู่\n\nเมื่อนักรบทั้งอัลไลแอนซ์และฮอร์ดตกอยู่ในห้วงแห่งความรัก พวกเขาก็จะไร้พลังหยุดยั้งการผงาดของสภาเงา\n\nพวกเขาจะอ่อนแอ ไม่ทันเตรียมตัว เมื่อมัวกังวลถึงคนที่รัก ก็จะสูญเสียความเฉียบคม\n\nคำตอบช่างง่ายดายนัก ทำไมข้าต้องใช้เวลานานเหลือเกินกว่าจะคิดได้? จุดอ่อนของทุกคนอยู่ที่หัวใจ และเจ้าไม่อาจทำอะไรหยุดสิ่งที่จะต้องเกิดขึ้นได้" },
    },
    [9029] = { -- A Bubbling Cauldron
        title = { "19:1063503600:1012645679", "หม้อยาเดือดปุด" },
        completion = { "44:1630486851:194034621", "กลิ่นหอมชวนพึงใจลอยขึ้นมาจากหม้อยา" },
    },
    [8492] = { -- The Alliance Needs Copper Bars!
        title = { "31:1657926414:689758466", "อัลไลแอนซ์ต้องการแท่งทองแดง!" },
        objective = { "77:278644128:1291797657", "นำ Copper Bars 20 แท่งไปให้ Sergeant Stonebrow ที่ Military Ward ใน Ironforge" },
        description = { "11:732468223:1055626852 C 318:1482160455:1772966741", "สวัสดี {class} ดูแข็งแรงพอจะช่วยงานระดมเสบียงสงครามได้นะ! เราต้องการความช่วยเหลือทุกอย่างเพื่อจัดเตรียมยุทโธปกรณ์สำหรับสงครามอันคิราจ และวันนี้เป็นวันโชคดีของเจ้า\n\nข้ากำลังรวบรวมแท่งทองแดงเป็นกองละยี่สิบแท่ง เพื่อเป้าหมายที่คู่ควร ว่าอย่างไร? เจ้าคิดว่าจะช่วยอัลไลแอนซ์ได้ไหม?" },
        progress = { "60:940854292:2073442132", "เจ้ารวบรวมทองแดงยี่สิบแท่งมาแล้วหรือ ทหาร?" },
        completion = { { "318:703936145:1173185258", "318:674804277:918415009" }, "เจ้าทำได้แล้ว สหาย! เราจะนำทองแดงเหล่านี้ไปเข้ากองและใช้ผลิตยุทโธปกรณ์ทันที ความทุ่มเทของคนอย่างเจ้าทำให้ข้าภูมิใจที่ได้รับใช้อัลไลแอนซ์ ทำได้ดี ทหาร!\n\nถ้าเจ้าพบทองแดงอีก ก็อย่าลืมนำมาให้ข้า" },
        required = { [2840] = { "10:1315783122:1190376755", "แท่งทองแดง" } },
        steps = { { "10:1315783122:1190376755", "แท่งทองแดง" } },
    },
    [8493] = { -- The Alliance Needs More Copper Bars!
        title = { "36:11060119:676839254", "อัลไลแอนซ์ต้องการแท่งทองแดงเพิ่ม!" },
        objective = { "73:823286133:547476707", "นำ copper bars 20 แท่งไปให้ Sergeant Stonebrow ที่สนามบินใน Dun Morogh" },
        description = { "11:41119844:703157642 C 131:426642907:37357065", "กลับมาอีกแล้วหรือ {class}? เยี่ยมมาก! เรายังต้องการแท่งทองแดงอีกหลายกอง ถ้าเจ้าหามาช่วยงานระดมเสบียงสงครามอันคิราจได้ จะช่วยเราไหม?" },
        progress = { "12:1977868436:1919340288 C 467:2073075160:1217685136", "กลับมาอีกแล้วหรือ {class}? เยี่ยมมาก! ทองแดงที่เจ้านำมาจนถึงตอนนี้จะช่วยผลิตสิ่งของสำหรับสงครามได้มากมาย อย่างที่ข้ารู้ ทองแดงจะใช้ทำชิ้นส่วนรถถังไอน้ำที่กำลังสร้าง รวมทั้งฝูงไจโรคอปเตอร์ขนาดเล็กที่เราวางแผนส่งไป หากมีเวลาพอ\n\nแต่อย่าให้กองเสบียงตรงนี้หลอกตา เรายังต้องการแท่งทองแดงอีก ถ้าเจ้าหามาช่วยงานระดมเสบียงสงครามอันคิราจได้ จะช่วยเราไหม?" },
        completion = { "237:980080148:1160961030 C 74:1318429929:1040858208", "ยอดเยี่ยม! การขุดหาทองแดงและหลอมมันคงเป็นการผจญภัยไม่น้อย เว้นแต่เจ้าจะซื้อจากลานประมูล จะวิธีไหนข้าก็รับทั้งนั้น เจ้าสมควรได้รับคำชมที่ช่วยงานระดมเสบียงสงคราม {class} และถ้ามีทองแดงอีก ก็อย่าลังเลที่จะนำมาให้ข้า" },
        required = { [2840] = { "10:1315783122:1190376755", "แท่งทองแดง" } },
        objectiveLabels = {
            item = { ["Copper Bar"] = "แท่งทองแดง" },
        },
    },
    [8494] = { -- The Alliance Needs Iron Bars!
        title = { "29:1639107469:699617797", "อัลไลแอนซ์ต้องการแท่งเหล็ก!" },
        objective = { "72:85731951:787219768", "นำ Iron Bars 20 แท่งไปให้ Corporal Carnes ที่ Military Ward ใน Ironforge" },
        description = { { "307:356975088:388773458 C 1:63:63", "307:289759223:605915681 C 1:63:63" }, "อ้าว สวัสดีคุณคนแต่งหรู เห็นเจ้าแล้วชื่นใจเสียจริง เผื่อเจ้ายังไม่ได้ยินข่าวระหว่างออกไป\"ผจญภัย\" อัลไลแอนซ์กำลังเตรียมทำสงครามในอันคิราจและต้องการแท่งเหล็ก... จำนวนมหาศาล นำมาให้ข้าเป็นกองละยี่สิบแท่ง เราพึ่งเจ้าได้ใช่ไหม {class}?" },
        progress = { "87:135928697:1821316708", "ถ้ามีเหล็กยี่สิบแท่งนั่นแล้ว ข้าก็ไม่อยากรู้หรอกว่าเจ้าซ่อนไว้ที่ไหน!" },
        completion = { "24:1401507440:213919404 N 243:1841520163:1324594666", "อ้าว ๆ นั่น {name} ไม่ใช่หรือ แล้วเจ้าก็ทำสำเร็จเสียด้วย สงสัยจากนี้ข้าต้องคอยจับตาดูเจ้า พูดแล้วก็เจ็บปวดใจ แต่ขอบคุณที่อุตส่าห์ช่วย อัลไลแอนซ์จะไม่ลืม ข้าก็เช่นกัน ทีนี้ออกไปทุ่มแรงรวบรวมของอื่นที่ยังต้องการต่อได้แล้ว" },
        required = { [3575] = { "8:1010117764:989104521", "แท่งเหล็ก" } },
        steps = { { "8:1010117764:989104521", "แท่งเหล็ก" } },
    },
    [8495] = { -- The Alliance Needs More Iron Bars!
        title = { "34:459915713:1481475777", "อัลไลแอนซ์ต้องการแท่งเหล็กเพิ่ม!" },
        objective = { "68:1476594145:768084950", "นำ iron bars 20 แท่งไปให้ Corporal Carnes ที่สนามบินใน Dun Morogh" },
        description = { "63:1503886623:967684645 C 360:1088255632:996299616", "กลับมาเร็วขนาดนี้เลยหรือ? เลิกทำให้ข้าต้องเปลี่ยนความเห็นแย่ ๆ ที่มีต่อเจ้าได้แล้ว {class} ข้าเริ่มใจอ่อนยวบไปหมด เห็นอยู่ว่าเหล็กยังไม่พอสำหรับอาวุธ เกราะ รถถังไอน้ำ และอะไรต่อมิอะไรที่ต้องสร้างเพื่อล่าแมลง คิดว่าจะเจียดเวลาระหว่างเที่ยวซุลกูรับ หรือที่ไหนก็ตามที่พวกวัยรุ่นอย่างเจ้าไปกันสมัยนี้ เอาเหล็กกลับมาอีกยี่สิบแท่งได้ไหม?" },
        progress = { "64:2099292414:65155988 C 360:1088255632:996299616", "กลับมาเร็วขนาดนี้เลยหรือ? เลิกทำให้ข้าต้องเปลี่ยนความเห็นแย่ ๆ ที่มีต่อเจ้าได้แล้ว {class} ข้าเริ่มใจอ่อนยวบไปหมด เห็นอยู่ว่าเหล็กยังไม่พอสำหรับอาวุธ เกราะ รถถังไอน้ำ และอะไรต่อมิอะไรที่ต้องสร้างเพื่อล่าแมลง คิดว่าจะเจียดเวลาระหว่างเที่ยวซุลกูรับ หรือที่ไหนก็ตามที่พวกวัยรุ่นอย่างเจ้าไปกันสมัยนี้ เอาเหล็กกลับมาอีกยี่สิบแท่งได้ไหม?" },
        completion = { { "59:249088242:640249676 N 113:1775920657:1946535750 N 114:1495885004:1531057403", "59:249088242:640249676 N 114:52913366:2094666741 N 114:1495885004:1531057403" }, "สงสัยเบิร์นนิงสเตปส์จะหนาวขึ้นมาแล้ว ดูนั่นสิ {name} เอาของขวัญมาให้ข้า เหล็กยี่สิบแท่ง! ของที่ข้าอยากได้มาตลอดเลย\n\nแต่พูดจริง ๆ นะ ขอบคุณ {name} เจ้าทำให้ทั้งตนเองและอัลไลแอนซ์ภาคภูมิใจ ทีนี้ออกไปนำของมาช่วยงานระดมเสบียงสงครามเพิ่มได้แล้ว!" },
        required = { [3575] = { "8:1010117764:989104521", "แท่งเหล็ก" } },
        objectiveLabels = {
            item = { ["Iron Bar"] = "แท่งเหล็ก" },
        },
    },
    [8500] = { -- The Alliance Needs More Thorium Bars!
        title = { "37:1979209475:1164604762", "อัลไลแอนซ์ต้องการแท่งทอเรียมเพิ่ม!" },
        objective = { "70:972514873:979824327", "นำ thorium bars 20 แท่งไปให้ Dame Twinbraid ที่สนามบินใน Dun Morogh" },
        description = { "31:236023937:597148462 N 167:805309510:1089648729", "ดีใจที่ได้พบเจ้าอีก {name} หวังว่าคงสบายดี เป็นความจริงที่เรายังต้องการแท่งทอเรียม หากเจ้ามีเหลือ ข้ากำลังรวบรวมเพื่อช่วยงานระดมเสบียงสงครามอันคิราจ" },
        progress = { "32:528612809:917039482 N 167:805309510:1089648729", "ดีใจที่ได้พบเจ้าอีก {name} หวังว่าคงสบายดี เป็นความจริงที่เรายังต้องการแท่งทอเรียม หากเจ้ามีเหลือ ข้ากำลังรวบรวมเพื่อช่วยงานระดมเสบียงสงครามอันคิราจ" },
        completion = { "11:1614239848:1406166483 C 260:933115526:1153520001", "ยอดเยี่ยม {class}! ทำได้ดีมาก ข้าจะจัดการนำแท่งโลหะเหล่านั้นขึ้นแท่นบรรทุก ส่งถึงมือช่างตีเหล็กและวิศวกรที่กำลังทำงานหนักเพื่อสะสมเสบียงให้กองทัพ ขอบคุณอีกครั้ง และถ้าเจ้าพบทอเรียมเพิ่มก็อย่าลืมแวะมา" },
        required = { [12359] = { "11:2096858940:1132233669", "แท่งทอเรียม" } },
        objectiveLabels = {
            item = { ["Thorium Bar"] = "แท่งทอเรียม" },
        },
    },
    [8503] = { -- The Alliance Needs Stranglekelp!
        title = { "32:1211146204:1921385134", "อัลไลแอนซ์ต้องการสแตรงเกิลเคลป์!" },
        objective = { "79:1907232221:879669317", "นำ Stranglekelp 20 ชิ้นไปให้ Private Draxlegauge ที่ Military Ward ใน Ironforge" },
        description = { "4:1416233998:188502220 C 320:435910635:802955132", "ว่าไง {class} ข้าเล่าเรื่องประโยชน์สารพัดของสแตรงเกิลเคลป์ให้ฟังแล้วหรือยัง? เล่าแล้วหรือ? เอาเถอะ... อย่างไรเราก็ต้องการอีกมาก และที่ว่ามากน่ะ มากจริง ๆ! เจ้าคิดว่าจะช่วยเราได้ไหม? ข้ารู้ว่านั่นหมายถึงเจ้าต้องอดทำของดี ๆ มากมายจากมัน แต่ก็เพื่อเป้าหมายที่คู่ควรนะ!" },
        progress = { "253:680510703:1489083019", "ไม่จริง! ข้าไม่มีวันแอบหยิบสแตรงเกิลเคลป์จากยอดกองพวกนี้หรอก ถึงจะชวนให้ใจอ่อนได้อยู่ เพราะมันแทบเป็นยาครอบจักรวาลด้านการใช้งาน *กระแอม* เจ้าบังเอิญมีสแตรงเกิลเคลป์ที่เราคุยกันก่อนหน้านี้มาหรือเปล่า?" },
        completion = { "175:213277441:1574130863 C 1:33:33", "ไชโย! ได้เพิ่มอีกยี่สิบแล้ว เจ้าดีที่สุดเลย ข้าว่าควรรีบเก็บให้เรียบร้อยก่อนมันเหี่ยว สแตรงเกิลเคลป์มากเหลือเกิน แต่เวลาน้อยเหลือเกิน!\n\nขอบคุณอีกครั้ง {class}!" },
        required = { [3820] = { "12:204861727:89919076", "สาหร่าย Stranglekelp" } },
        steps = { { "12:204861727:89919076", "สาหร่าย Stranglekelp" } },
    },
    [8504] = { -- The Alliance Needs More Stranglekelp!
        title = { "37:1020786848:228968362", "อัลไลแอนซ์ต้องการสแตรงเกิลเคลป์เพิ่ม!" },
        objective = { "75:799327238:419972004", "นำ stranglekelp 20 ชิ้นไปให้ Private Draxlegauge ที่สนามบินใน Dun Morogh" },
        description = { "47:97745410:489521361 N 201:740810035:1988053421", "สวัสดีอีกครั้ง เจ้า... ชื่ออะไรนะ? อ้อ ใช่ {name}! มาดูว่าข้ายังต้องการสแตรงเกิลเคลป์เพิ่มหรือ? เป็นวันโชคดีของเจ้าแล้ว เพราะคำตอบสำหรับคำถามสำคัญนั้นคือ ต้องการอย่างยิ่ง! คิดว่าจะหาเพิ่มอีกยี่สิบได้ไหม?" },
        progress = { "47:97745410:489521361 N 201:740810035:1988053421", "สวัสดีอีกครั้ง เจ้า... ชื่ออะไรนะ? อ้อ ใช่ {name}! มาดูว่าข้ายังต้องการสแตรงเกิลเคลป์เพิ่มหรือ? เป็นวันโชคดีของเจ้าแล้ว เพราะคำตอบสำหรับคำถามสำคัญนั้นคือ ต้องการอย่างยิ่ง! คิดว่าจะหาเพิ่มอีกยี่สิบได้ไหม?" },
        completion = { "255:339156277:990218949 N 99:752015061:441661665", "โอ้โฮ เจ้ามีสแตรงเกิลเคลป์มาเยอะทีเดียว เร็วเข้า เอาใส่กล่องรักษาความสด เจ้าช่วยข้า... ช่วยพวกเรา ช่วยอัลไลแอนซ์อย่างมากที่นำชุดนี้มา ข้าจะบอกให้ทุกคนรู้ว่าเป็นเจ้า {name} ผู้ยิ่งใหญ่ ที่ช่วยพลิกดุลของงานระดมเสบียงสงครามอันคิราจด้วยสแตรงเกิลเคลป์ที่บริจาค!" },
        required = { [3820] = { "12:204861727:89919076", "สาหร่าย Stranglekelp" } },
        objectiveLabels = {
            item = { ["Stranglekelp"] = "สาหร่าย Stranglekelp" },
        },
    },
    [8505] = { -- The Alliance Needs Purple Lotus!
        title = { "32:1072137753:1180748731", "อัลไลแอนซ์ต้องการเพอร์เพิลโลตัส!" },
        objective = { "76:1656147574:990211737", "นำ Purple Lotus 20 ชิ้นไปให้ Master Nightsong ที่ Military Ward ใน Ironforge" },
        description = { "C 411:178696944:1467835617", "{class} เพอร์เพิลโลตัสเป็นดอกไม้ที่ใช้ประโยชน์ได้หลากหลาย อัลไลแอนซ์ขอให้ข้ามาที่นี่ในฐานะผู้เชี่ยวชาญการใช้งานเหล่านั้น เพื่อเก็บรักษาสมุนไพรที่รวบรวมมา และดูแลให้งานระดมเสบียงสงครามได้รับเพอร์เพิลโลตัสเพียงพอสำหรับทุกสิ่งที่วางแผนจะใช้\n\nข้าอยากให้เจ้าออกเดินทางไปในโลก และนำดอกไม้เหล่านี้กลับมา เจ้าทำได้ไหม?" },
        progress = { "52:670203438:1556194751", "เจ้ามีเพอร์เพิลโลตัสที่ข้าขอแล้วหรือ?" },
        completion = { "42:1329581148:286805511 C 278:1452785951:1212274688", "ข้าซาบซึ้งในความช่วยเหลือของเจ้า {class} มีแต่การร่วมแรงของทุกคนเท่านั้นที่จะผลักดันการรุกคืบอย่างเหี้ยมโหดของซิลิธิด และอำนาจใดก็ตามที่ขับเคลื่อนพวกมันกลับไปได้ แม้แต่ฮอร์ดก็กำลังสะสมเพอร์เพิลโลตัสของตนเอง หากเจ้าพบอีก โปรดกลับมาหาข้าที่นี่" },
        required = { [8831] = { "12:571983408:84265363", "ดอกบัวสีม่วง" } },
        steps = { { "12:571983408:84265363", "ดอกบัวสีม่วง" } },
    },
    [8506] = { -- The Alliance Needs More Purple Lotus!
        title = { "37:881778397:1635815588", "อัลไลแอนซ์ต้องการเพอร์เพิลโลตัสเพิ่ม!" },
        objective = { "72:209498453:364593446", "นำ purple lotus 20 ชิ้นไปให้ Master Nightsong ที่สนามบินใน Dun Morogh" },
        description = { "13:23130796:2039583150 C 192:1318977021:1424274497", "ยินดีต้อนรับกลับ {class} ของที่เราสะสมเพิ่มขึ้น แต่ถึงตอนนี้ก็ยังต้องการเพอร์เพิลโลตัสเพิ่ม หากเจ้ายังพอรวบรวมสมุนไพรชนิดนี้ได้ ข้าขอร้องให้ทำเช่นนั้นแล้วนำกลับมาให้ข้าที่นี่" },
        progress = { "14:1649650394:897424258 C 192:1318977021:1424274497", "ยินดีต้อนรับกลับ {class} ของที่เราสะสมเพิ่มขึ้น แต่ถึงตอนนี้ก็ยังต้องการเพอร์เพิลโลตัสเพิ่ม หากเจ้ายังพอรวบรวมสมุนไพรชนิดนี้ได้ ข้าขอร้องให้ทำเช่นนั้นแล้วนำกลับมาให้ข้าที่นี่" },
        completion = { "61:1394006654:117965740 N 196:1669404009:1080362991", "ข้ายินดีรับสิ่งที่เจ้าบริจาคในนามอัลไลแอนซ์ {name} ความทุ่มเทของเจ้าจะนำไปสู่การผลิตยาและน้ำมันหลายชนิดโดยตรง เพื่อสนับสนุนทหารของเราในสนามรบ ขอบคุณ และถ้าพบอีก โปรดนึกถึงการกลับมาหาข้าด้วย" },
        required = { [8831] = { "12:571983408:84265363", "ดอกบัวสีม่วง" } },
        objectiveLabels = {
            item = { ["Purple Lotus"] = "ดอกบัวสีม่วง" },
        },
    },
    [8509] = { -- The Alliance Needs Arthas' Tears!
        title = { "33:1112897968:1077811713", "อัลไลแอนซ์ต้องการน้ำตาอาร์ธัส!" },
        objective = { "84:173891534:16075865", "นำ Arthas' Tears 20 ชิ้นไปให้ Sergeant Major Germaine ที่ Military Ward ใน Ironforge" },
        description = { "38:884759355:1861828593 C 267:1045681916:1082148478", "ข้าจะพูดสั้น ๆ ให้ตรงประเด็น {class} อัลไลแอนซ์ต้องรวบรวมน้ำตาอาร์ธัสจำนวนมากเพื่อระดมเสบียงสงครามอันคิราจ อย่าถามข้าว่าเอาไปทำอะไร ข้าแค่ทำตามคำสั่ง แต่อยากให้เจ้ารวบรวมสมุนไพรให้มากที่สุดเท่าที่ทำได้ แล้วนำกลับมาให้ข้าที่นี่ เจ้ายินดีทำหรือไม่?" },
        progress = { "23:609715652:1335452976 C 58:691965690:800758461", "อะไรนะ? พูดดัง ๆ สิ {class}! เจ้ามีน้ำตาอาร์ธัสชุดที่ข้าขอมาแล้วหรือ?" },
        completion = { "11:354343371:1318038540 C 286:1256995885:601605351", "ทำได้ดี {class} ต้องบอกว่าข้าประหลาดใจอย่างยินดี เจ้าไม่เชื่อแน่ว่ามีคนผ่านมาขอช่วยมากเพียงใด แต่ไม่เคยกลับมาเลย ขอข้าเอาของใส่ลังและลงบัญชีพร้อมชื่อเจ้าก่อน แล้วเราค่อยคุยกันอีกว่าข้ายังต้องการพืชพวกนี้เพิ่มหรือไม่" },
        required = { [8836] = { "13:588229817:456656669", "หยาดน้ำตาของ Arthas" } },
        steps = { { "13:588229817:456656669", "หยาดน้ำตาของ Arthas" } },
    },
    [8510] = { -- The Alliance Needs More Arthas' Tears!
        title = { "38:1582667357:562028368", "อัลไลแอนซ์ต้องการน้ำตาอาร์ธัสเพิ่ม!" },
        objective = { "80:210007039:1257374991", "นำ Arthas' Tears 20 ชิ้นไปให้ Sergeant Major Germaine ที่สนามบินใน Dun Morogh" },
        description = { "301:2017260779:1993651706 C 1:63:63", "เอาละ ดูเหมือนข้ายังต้องการน้ำตาอาร์ธัสอีก ข้าคิดว่าเจ้าคงหาได้ในแถบเดียวกับที่รวบรวมมาให้ข้าครั้งก่อน ยิ่งเราได้ของเร็วเท่าไร ก็ยิ่งเริ่มรุกกองกำลังที่อันคิราจได้เร็วเท่านั้น\n\nเจ้าจะช่วยเราอีกไหม {class}?" },
        progress = { "54:1061191809:1276232925 C 286:2024283195:268370006 N 1:63:63", "เอาละ ดูเหมือนข้ายังต้องการน้ำตาอาร์ธัสอีก {class} ข้าคิดว่าเจ้าคงหาได้ในแถบเดียวกับที่รวบรวมมาครั้งก่อน งานระดมเสบียงสงครามกำลังไปได้ดี แต่ยิ่งเราได้ของเร็วเท่าไร ก็ยิ่งเริ่มรุกกองกำลังที่อันคิราจได้เร็วเท่านั้น\n\nเจ้าจะช่วยเราอีกไหม {name}?" },
        completion = { "20:602760363:1997637423 N 242:1146528021:1790017556", "ยอดเยี่ยมจริง ๆ {name}! เจ้าทำให้อัลไลแอนซ์ภาคภูมิใจ ข้าจะจัดเก็บสมุนไพรเหล่านี้ไว้ จนกว่าจะมีคนนำไปแปรรูปเป็นของที่มีประโยชน์ต่อสงคราม แวะมาได้ทุกเมื่อ โดยเฉพาะถ้ามีน้ำตาอาร์ธัสมาให้ข้าอีก" },
        required = { [8836] = { "13:588229817:456656669", "หยาดน้ำตาของ Arthas" } },
        objectiveLabels = {
            item = { ["Arthas' Tears"] = "หยาดน้ำตาของ Arthas" },
        },
    },
    [8511] = { -- The Alliance Needs Light Leather!
        title = { "33:999087184:280125147", "อัลไลแอนซ์ต้องการหนังเบา!" },
        objective = { "79:1222646051:192053607", "นำ Light Leather 10 ชิ้นไปให้ Bonnie Stoneflayer ที่ Military Ward ใน Ironforge" },
        description = { { "55:1641619251:239488003 C 404:109828501:886591676", "55:1641619251:239488003 C 404:1094937973:1284334051" }, "ตระกูลสโตนเฟลเยอร์ของเรามีประวัติเป็นช่างถลกหนังมายาวนาน {class} อัลไลแอนซ์จึงขอให้ครอบครัวข้าช่วยรวบรวมหนังเบาสำหรับงานระดมเสบียงสงครามอันคิราจ ข้ามาดูแลให้ฟอกหนังอย่างถูกต้อง ไม่ว่าพวกเขาจะนำไปใช้อะไร แต่เราต้องการความช่วยเหลือจากเจ้า\n\nเพราะข้าต้องอยู่ทำงานตรงนี้ จึงอยากให้เจ้าออกไปรวบรวมหนัง แล้วนำกลับมาให้ข้า ว่าอย่างไร สหาย จะลองช่วยไหม?" },
        progress = { "C 53:262115917:1045101986", "{class} ข้าหวังจริง ๆ ว่านั่นคือหนังเบาที่เจ้าสัญญาไว้" },
        completion = { "72:529779158:904503060 C 152:547031636:1869623841", "ข้ากล้าพูดเลยว่าอัลไลแอนซ์ต้องพอใจกับหนังของเจ้ามาก {class} ข้าจะดูแลไม่ให้เสียเปล่าแม้แต่ชิ้นเดียว ขอบคุณ และเมื่อนับเสร็จแล้ว อย่าลืมกลับมาถามข้าว่าเราต้องการเพิ่มอีกหรือไม่" },
        required = { [2318] = { "13:512583266:745641545", "หนังบาง" } },
        steps = { { "13:512583266:745641545", "หนังบาง" } },
    },
    [8512] = { -- The Alliance Needs Light Leather!
        title = { "33:999087184:280125147", "อัลไลแอนซ์ต้องการหนังเบา!" },
        objective = { "75:499059964:1716233820", "นำ light leather 10 ชิ้นไปให้ Bonnie Stoneflayer ที่สนามบินใน Dun Morogh" },
        description = { "22:827788161:376657840 N 159:697448105:351158607", "ดีใจที่ได้พบเจ้าอีก {name} ดูเหมือนเรายังต้องการหนังเบาเพื่อผลิตยุทโธปกรณ์ชนิดต่าง ๆ ถ้าเจ้านำมาได้สักกองละสิบชิ้นก็จะพอดีมาก" },
        progress = { "23:140679440:2097538806 N 161:512496137:1915279336", "ดีใจที่ได้พบเจ้าอีก {name} ดูเหมือนเรายังต้องการหนังเบาเพื่อผลิตยุทโธปกรณ์ชนิดต่าง ๆ ถ้าเจ้านำมาได้สักกองละสิบชิ้นก็จะพอดีมาก" },
        completion = { "38:1815175713:904719164 N 278:489084354:565920134", "ขอบคุณสำหรับการบริจาคอย่างใจกว้าง {name} ข้าจะนำไปเข้ากองเดี๋ยวนี้ และอีกไม่นานมันคงกลายเป็นชุดเกราะงาม ๆ แผ่นหนังเสริม หรือถูกใช้เตรียมการอย่างอื่น ดูเหมือนเราจะต้องการหนังเบาเพิ่มอยู่เสมอ กลับมาเยี่ยมข้าเร็ว ๆ นะ" },
        required = { [2318] = { "13:512583266:745641545", "หนังบาง" } },
        objectiveLabels = {
            item = { ["Light Leather"] = "หนังบาง" },
        },
    },
    [8513] = { -- The Alliance Needs Medium Leather!
        title = { "34:1472294837:2040636498", "อัลไลแอนซ์ต้องการหนังกลาง!" },
        objective = { "76:1021512998:939094267", "นำ Medium Leather 10 ชิ้นไปให้ Private Porter ที่ Military Ward ใน Ironforge" },
        description = { { "292:134320448:1137422968", "293:1483499637:1458378535" }, "ได้เลยท่าน ข้าได้รับหน้าที่รวบรวมและบันทึกหนังกลางทั้งหมดที่ได้มาเพื่องานระดมเสบียงสงคราม หากเจ้าพอจะหาหนังกลางมาได้ ไม่ว่าจากแหล่งใด โปรดนำมาให้ข้าที่นี่ ข้าจะขอบคุณมากหากเจ้าสละเวลาช่วยงานนี้ได้" },
        progress = { { "77:725505365:97418372", "78:704277355:850823582" }, "ได้เลยท่าน ข้าจำเจ้าได้ นั่นหนังกลางที่เจ้าพกมาใช่ไหม?" },
        completion = { "189:1077069339:699874381", "ว้าว! รู้สึกเหมือนเจ้าเพิ่งมาขออาสาช่วยเมื่อครู่นี้เอง ขอบคุณมากสำหรับการบริจาค ข้าจะเก็บทั้งหมดให้เรียบร้อยแล้วนับจำนวน เจ้ารู้วิธีทำให้คนอื่นมีวันที่ดีจริง ๆ" },
        required = { [2319] = { "14:2133845222:826910368", "หนังหนาปานกลาง" } },
        steps = { { "14:2133845222:826910368", "หนังหนาปานกลาง" } },
    },
    [8514] = { -- The Alliance Needs More Medium Leather!
        title = { "39:1943943578:1045010802", "อัลไลแอนซ์ต้องการหนังกลางเพิ่ม!" },
        objective = { "72:285671559:1078467656", "นำ medium leather 10 ชิ้นไปให้ Private Porter ที่สนามบินใน Dun Morogh" },
        description = { { "37:261668438:1090250372 W2063 164:291581553:1481100202", "38:1550912730:1402505311 W2063 164:291581553:1481100202" }, "ได้เลยท่าน ดูเหมือนจนถึงตอนนี้เรารวบรวมหนังกลางได้ {world2063} ชิ้นแล้ว ข้ารู้ว่าขอมากอยู่ แต่ถ้าเจ้ายังยินดี ข้าก็อยากให้ช่วยลดจำนวนที่ยังขาดจากโควตาของข้า" },
        progress = { { "300:1101158341:1002809072", "301:366755765:2052287643" }, "ได้เลยท่าน ดูเหมือนเรารวบรวมหนังกลางได้หลายชิ้นแล้ว แต่ยังต้องการเพิ่ม ข้ารับรองว่าทุกชิ้นจะถูกใช้ให้เกิดประโยชน์ ไม่มีเสียเปล่าแม้แต่ชิ้นเดียว ข้ารู้ว่าขอมากอยู่ แต่ถ้าเจ้ายังยินดี ข้าก็อยากให้ช่วยลดจำนวนที่ยังขาดจากโควตาของข้า" },
        completion = { { "237:465498606:334747921 N 1:33:33", "238:1810799254:977850688 N 1:33:33" }, "โอ้โฮ ท่านนำหนังกลางมาเยอะจริง ๆ! ข้าจะดูแลให้ทุกชิ้นถูกใช้อย่างเหมาะสม แน่นอน ด้วยความช่วยเหลือของเจ้า อีกไม่นานเราคงรวบรวมหนังกลางได้ครบตามที่คำนวณไว้!\n\nขอบคุณ {name}!" },
        required = { [2319] = { "14:2133845222:826910368", "หนังหนาปานกลาง" } },
        objectiveLabels = {
            item = { ["Medium Leather"] = "หนังหนาปานกลาง" },
        },
    },
    [8515] = { -- The Alliance Needs Thick Leather!
        title = { "33:1723483603:1655289283", "อัลไลแอนซ์ต้องการหนังหนา!" },
        objective = { "78:1640790296:281769358", "นำ Thick Leather 10 ชิ้นไปให้ Marta Finespindle ที่ Military Ward ใน Ironforge" },
        description = { "35:581474288:1409285410 C 367:333658862:1505916623", "โอ้โฮ ต้องยอดเยี่ยมแน่! {class} งานระดมเสบียงสงครามอันคิราจกำลังดำเนินเต็มที่ และข้าได้รับมอบหมายให้บันทึกหนังหนาทั้งหมดที่ส่งเข้ามา เราจะใช้มันผลิตของเป็นตัน ๆ แต่ก่อนอื่นก็ต้องได้หนังมาเป็นตัน ๆ ก่อน และข้าหมายถึงเป็นตันจริง ๆ! ตรงนี้ละที่ต้องพึ่งเจ้า\n\nเจ้าคิดว่าจะออกไปนำหนังหนากองโตกลับมาให้ข้าได้ไหม? ได้ไหม ได้ไหม?!" },
        progress = { "55:501396059:452543114 C 106:2107326738:1693548504", "ในกระเป๋าเจ้านั่นหนังหนาใช่ไหม {class}? ใช่หรือเปล่า? ข้ารอให้เจ้าส่งมาแทบไม่ไหวแล้ว! ทุกคนต้องพอใจพวกเรามากแน่ เจ้าคิดอย่างนั้นไหม?" },
        completion = { "28:1518786304:1689311250 C 313:1198139305:1089316281", "โอ้ ข้ารู้อยู่แล้วว่าเจ้าทำได้ {class} รู้อยู่แล้วจริง ๆ! ข้าจะส่งของเหล่านี้ให้ถึงมือผู้ใช้โดยเร็วที่สุด ทีนี้ขอดูหน่อย อืม ยอดนับดูคืบหน้าไปได้ดีทีเดียว เจ้าควรกลับมาถามอีกสักครู่เมื่อนับเสร็จแล้ว ว่าเราต้องการเพิ่มหรือไม่ เพราะถ้าต้องการ เจ้านี่ละคือคนที่ข้าอยากให้ออกไปรวบรวมมาให้!" },
        required = { [4304] = { "13:983336109:1264322130", "หนังหนา" } },
        steps = { { "13:983336109:1264322130", "หนังหนา" } },
    },
    [8516] = { -- The Alliance Needs More Thick Leather!
        title = { "38:45769345:1139505938", "อัลไลแอนซ์ต้องการหนังหนาเพิ่ม!" },
        objective = { "74:1767441770:2142310900", "นำ thick leather 10 ชิ้นไปให้ Marta Finespindle ที่สนามบินใน Dun Morogh" },
        description = { "40:1096439302:525068980 N 39:1770165175:319189448 W2071 346:1853744715:1491044409", "ใช่ กองยังสูงไม่พอ {name} เรายังไม่ได้หนังหนาครบเป้าหมาย {world2071} ชิ้น ลองนึกถึงของที่เราทำได้จากหนังทั้งหมดสิ! ทั้งเกราะและอาวุธสารพัด ของใช้ภายในรถถังไอน้ำกับกล้องเล็งปืน! แว่นวิศวกรรมด้วย และข้าพนันว่าถ้าสุดท้ายเรารวบรวมได้มากเกินไป ก็ยกที่เหลือให้ฮอร์ดทำเรือเหาะได้!\n\nเจ้าจะนำหนังหนากลับมาให้ข้าเพิ่มไหม?" },
        progress = { "40:1096439302:525068980 N 301:1556102717:1646743569", "ใช่ กองยังสูงไม่พอ {name} เรายังรวบรวมหนังหนาไม่ถึงเป้าหมาย ลองนึกถึงของที่เราทำได้จากหนังทั้งหมดสิ! ทั้งเกราะและอาวุธสารพัด ของใช้ภายในรถถังไอน้ำกับกล้องเล็งปืน! แล้วก็แว่นวิศวกรรม ของพวกนั้นสนุกเสมอ!\n\nเจ้าจะนำหนังหนากลับมาให้ข้าเพิ่มไหม?" },
        completion = { "372:2108617724:509818476 N 1:46:46", "เจ้าทำได้อีกแล้ว! น่าทึ่งจริง ๆ ที่เจ้าออกไปรวบรวมของทั้งหมด แล้วนำกลับมาส่งให้ที่นี่ ข้าขอบอกเลยว่า พอผู้คนรู้ว่าเจ้าช่วยงานมากเพียงใด เจ้าจะเดินตามถนนไม่ได้โดยไม่มีคนมาขอลายเซ็น!\n\nขอบคุณอีกครั้งที่บริจาคหนังหนาอย่างใจกว้าง {name}" },
        required = { [4304] = { "13:983336109:1264322130", "หนังหนา" } },
        objectiveLabels = {
            item = { ["Thick Leather"] = "หนังหนา" },
        },
    },
    [8517] = { -- The Alliance Needs Linen Bandages!
        title = { "34:1280881238:181002408", "อัลไลแอนซ์ต้องการผ้าพันแผลลินิน!" },
        objective = { "80:691516304:1152135859", "นำ Linen Bandages 20 ชิ้นไปให้ Sentinel Silversky ที่ Military Ward ใน Ironforge" },
        description = { "490:275222543:128291758 C 1:63:63", "สงครามที่อันคิราจจะยาวนานและนองเลือด อัลไลแอนซ์ทำอย่างชาญฉลาดที่ขอแรงเจ้าและคนเช่นเจ้ามาสะสมยุทโธปกรณ์ที่จำเป็น ก่อนถลำเข้าสู่ความขัดแย้ง\n\nข้าได้รับหน้าที่นำการรวบรวมผ้าพันแผลลินินสำหรับสงคราม และหวังว่าเจ้าจะช่วยสะสมให้ครบตามที่เราต้องการ นี่ไม่ใช่เรื่องเล็กน้อย แต่อย่างน้อยผ้าพันแผลลินินก็ทำได้ง่ายที่สุด เจ้าจะร่วมมือกับเราไหม {class}?" },
        progress = { "54:897442582:1507055370 C 1:63:63", "เจ้ามีผ้าพันแผลลินินยี่สิบชิ้นที่ข้าต้องการแล้วหรือ {class}?" },
        completion = { "75:427401351:1335728616 C 262:808633205:1103226262 R 1:33:33", "ทหารมากมายจะได้รับประโยชน์จากสิ่งที่เจ้าบริจาคในวันนี้ {class} ข้าจะดูแลด้วยตนเองให้อัลไลแอนซ์รับรู้ถึงความพยายามของเจ้า ขอเวลาข้าเก็บผ้าพันแผลให้ถูกวิธีและปรับยอดนับสักครู่ แล้วเจ้าค่อยมาถามว่าข้ายังต้องการเพิ่มหรือไม่\n\nขอให้แสงแห่งอีลูนส่องถึงเจ้า {race}!" },
        required = { [1251] = { "13:777114038:1094399117", "ผ้าพันแผลลินิน" } },
        steps = { { "13:777114038:1094399117", "ผ้าพันแผลลินิน" } },
    },
    [8518] = { -- The Alliance Needs More Linen Bandages!
        title = { "39:1752529979:1332860341", "อัลไลแอนซ์ต้องการผ้าพันแผลลินินเพิ่ม!" },
        objective = { "76:1277196528:2114547994", "นำ linen bandages 20 ชิ้นไปให้ Sentinel Silversky ที่สนามบินใน Dun Morogh" },
        description = { "103:1398438620:1838333926 C 153:19586673:733836497", "ข้าประทับใจในความเสียสละเสมอ ในยามที่หลายคนคงเลือกเห็นแก่ตนเอง {class} ข้ายังต้องการผ้าพันแผลลินินอีกจำนวนหนึ่งก่อนงานที่ได้รับมอบหมายที่นี่จะเสร็จสิ้น เจ้าจะช่วยรวบรวมผ้าพันแผลเหล่านั้นอีกครั้งไหม?" },
        progress = { "103:1398438620:1838333926 C 153:19586673:733836497", "ข้าประทับใจในความเสียสละเสมอ ในยามที่หลายคนคงเลือกเห็นแก่ตนเอง {class} ข้ายังต้องการผ้าพันแผลลินินอีกจำนวนหนึ่งก่อนงานที่ได้รับมอบหมายที่นี่จะเสร็จสิ้น เจ้าจะช่วยรวบรวมผ้าพันแผลเหล่านั้นอีกครั้งไหม?" },
        completion = { "25:1450046495:820949271 N 278:631553800:98231543", "เจ้าสมควรได้รับคำชม {name} ขณะที่บางคนฉวยโอกาสจากภาวะสงคราม กอบโกยเงินเข้ากระเป๋าด้วยความโลภ เจ้าได้พิสูจน์ครั้งแล้วครั้งเล่าว่าความภักดีต่ออัลไลแอนซ์ และต่ออาเซรอธทั้งหมดมาก่อน\n\nขอให้พรแห่งอีลูนอยู่กับเจ้าเสมอ!" },
        required = { [1251] = { "13:777114038:1094399117", "ผ้าพันแผลลินิน" } },
        objectiveLabels = {
            item = { ["Linen Bandage"] = "ผ้าพันแผลลินิน" },
        },
    },
    [8520] = { -- The Alliance Needs Silk Bandages!
        title = { "33:689049567:1661179179", "อัลไลแอนซ์ต้องการผ้าพันแผลไหม!" },
        objective = { "77:1589939697:1107564044", "นำ Silk Bandages 20 ชิ้นไปให้ Nurse Stonefield ที่ Military Ward ใน Ironforge" },
        description = { "292:1923214905:23573684 C 1:63:63", "เมื่อสงครามอันคิราจใกล้เข้ามา เราต้องทำทุกอย่างเพื่อให้ทหารมีสิ่งจำเป็นครบถ้วน และเรากำลังทำสิ่งนั้นอยู่ที่นี่ ส่วนข้าได้รับหน้าที่ดูแลให้รวบรวมผ้าพันแผลไหมได้เพียงพอ\n\nเจ้าคิดว่าจะช่วยข้าได้ไหม {class}?" },
        progress = { "7:989913233:66981971 C 59:772058388:1185937500", "สวัสดี {class} เจ้าหาผ้าพันแผลไหมยี่สิบชิ้นมาได้หรือยัง?" },
        completion = { "C 162:1467463045:1495358030", "{class} เจ้าทำได้แล้ว! เพราะเจ้า เราจึงเข้าใกล้เป้าหมายผ้าพันแผลไหมไปอีกก้าว ข้าจะนำไปเก็บให้เรียบร้อย แล้วเราค่อยคุยกันต่อหากเจ้าต้องการ" },
        required = { [6450] = { "12:502502492:1350749614", "ผ้าพันแผลไหม" } },
        steps = { { "12:502502492:1350749614", "ผ้าพันแผลไหม" } },
    },
    [8521] = { -- The Alliance Needs More Silk Bandages!
        title = { "38:1158818956:1145395834", "อัลไลแอนซ์ต้องการผ้าพันแผลไหมเพิ่ม!" },
        objective = { "73:604585810:1508485292", "นำ silk bandages 20 ชิ้นไปให้ Nurse Stonefield ที่สนามบินใน Dun Morogh" },
        description = { "49:90610905:1245718187 C 32:1336443174:371573674 W2082 35:1518598917:604224178", "ใจดีเหลือเกินที่เสนอช่วยข้าอีกครั้ง {class} ดูเหมือนเรารวบรวมผ้าพันแผลไหมได้ {world2082} ชิ้นแล้ว แต่ยังต้องการเพิ่ม" },
        progress = { "50:1812169231:2127811926 C 117:794614085:1500224110 N 142:630181486:1171679592", "ใจดีเหลือเกินที่เสนอช่วยข้าอีกครั้ง {class} ดูเหมือนเรารวบรวมผ้าพันแผลไหมตามที่ได้รับมอบหมายได้มากพอสมควร แต่ยังต้องการเพิ่ม {name} เจ้าพอจะจัดมาอีกมัดแล้วนำกลับมาให้ข้าที่นี่ได้ไหม? ทั้งอัลไลแอนซ์และข้าจะขอบคุณมาก" },
        completion = { "253:497219229:285752970 N 1:46:46", "เจ้าเป็นคนเสียสละจริง ๆ ขอบคุณมากที่ช่วยงานระดมเสบียงสงคราม คนอย่างเจ้าจะเป็นผู้กำหนดความแตกต่างระหว่างความสำเร็จกับความล้มเหลวที่อันคิราจ ข้าเพียงหวังว่าทั้งหมดนี้จะเพียงพอ\n\nขอบคุณอีกครั้ง {name}" },
        required = { [6450] = { "12:502502492:1350749614", "ผ้าพันแผลไหม" } },
        objectiveLabels = {
            item = { ["Silk Bandage"] = "ผ้าพันแผลไหม" },
        },
    },
    [8522] = { -- The Alliance Needs Runecloth Bandages!
        title = { "38:487048446:1147917937", "อัลไลแอนซ์ต้องการผ้าพันแผลรูนคลอธ!" },
        objective = { "82:54113473:1880643399", "นำ Runecloth Bandages 20 ชิ้นไปให้ Keeper Moonshade ที่ Military Ward ใน Ironforge" },
        description = { "41:120294423:782879726 C 344:1627562582:1166829965", "เจ้าจะถกเถียงความเหมาะสมของสงครามก็ได้ {class} แต่มันเริ่มเดินหน้าแล้ว ลองมองครอบครัวและเพื่อนรอบตัว แล้วถามตนเองว่าเจ้าทำอะไรได้บ้าง เพื่อให้หากพวกเขาต้องเข้าไปเกี่ยวข้อง พวกเขาจะมีโอกาสรอดจากไฟสงครามมากที่สุด\n\nด้วยเหตุนี้ ข้าจึงรวบรวมผ้าพันแผลรูนคลอธจากทุกแหล่งที่นี่ เจ้าอยากบริจาคไหม?" },
        progress = { "55:1292857036:1112435337 C 36:176017593:1054089399", "วันเวลาผ่านไปทีละวัน แต่เรายังคงดำเนินต่อ {class} เจ้ามีผ้าพันแผลรูนคลอธนั่นแล้วหรือ?" },
        completion = { "25:1450046495:820949271 C 185:221339400:954255512", "เจ้าสมควรได้รับคำชม {class} สำหรับความมุ่งมั่นในภารกิจนี้ ข้าจะเก็บผ้าพันแผลเหล่านี้ให้เรียบร้อย แล้วอยากคุยกับเจ้าอีกเรื่องโอกาสที่จะรวบรวมผ้าพันแผลรูนคลอธเพิ่ม" },
        required = { [14529] = { "17:1741836445:919676731", "ผ้าพันแผลผ้ารูน" } },
        steps = { { "17:1741836445:919676731", "ผ้าพันแผลผ้ารูน" } },
    },
    [8523] = { -- The Alliance Needs More Runecloth Bandages!
        title = { "43:885387063:1842653007", "อัลไลแอนซ์ต้องการผ้าพันแผลรูนคลอธเพิ่ม!" },
        objective = { "78:569887189:2029470400", "นำ runecloth bandages 20 ชิ้นไปให้ Keeper Moonshade ที่สนามบินใน Dun Morogh" },
        description = { "60:1941125517:1886852935 C 136:1629234122:1562065240 N 75:1205717003:209709822", "เรากลับมาพูดถึงเรื่องเร่งด่วนกันอีกแล้ว {class} ข้าขอบคุณสำหรับความพยายามครั้งก่อนอีกครั้ง ไม่ใช่ทุกคนที่จะให้โดยไม่เห็นแก่ตนเช่นนี้ แต่ยังมีงานต้องทำอีก\n\n{name} เจ้าจะรวบรวมผ้าพันแผลรูนคลอธแล้วนำกลับมาให้ข้าที่นี่อีกครั้งไหม?" },
        progress = { "61:653054881:217118754 C 136:1629234122:1562065240 N 75:1205717003:209709822", "เรากลับมาพูดถึงเรื่องเร่งด่วนกันอีกแล้ว {class} ข้าขอบคุณสำหรับความพยายามครั้งก่อนอีกครั้ง ไม่ใช่ทุกคนที่จะให้โดยไม่เห็นแก่ตนเช่นนี้ แต่ยังมีงานต้องทำอีก\n\n{name} เจ้าจะรวบรวมผ้าพันแผลรูนคลอธแล้วนำกลับมาให้ข้าที่นี่อีกครั้งไหม?" },
        completion = { "47:1050936077:318468575 N 161:337947334:753540224", "เส้นทางที่เราเดินร่วมกันช่างงดงาม {name} เจ้าเป็นผู้ร่วมงานที่ยอดเยี่ยม ข้าขอขอบคุณความพยายามของเจ้าในนามอัลไลแอนซ์ทั้งหมดอีกครั้ง กลับมาคุยกันเร็ว ๆ นะ" },
        required = { [14529] = { "17:1741836445:919676731", "ผ้าพันแผลผ้ารูน" } },
        objectiveLabels = {
            item = { ["Runecloth Bandage"] = "ผ้าพันแผลผ้ารูน" },
        },
    },
    [8524] = { -- The Alliance Needs Rainbow Fin Albacore!
        title = { "40:1474753326:1138228033", "อัลไลแอนซ์ต้องการเรนโบว์ฟินอัลบาคอร์!" },
        objective = { "85:1404467155:437185849", "นำ Rainbow Fin Albacore 20 ชิ้นไปให้ Slicky Gastronome ที่ Military Ward ใน Ironforge" },
        description = { "393:1768742661:1813254033", "สวัสดี สหาย! ถ้าข้าถามเจ้าว่า 'ไม่คิดหรือว่าทหารควรมีอาหารกินเหมือนคนอื่น?' แน่นอนว่าเจ้าคงตอบว่า 'คิดสิ' ข้าเห็นด้วยกับเจ้า 110%! ดีใจที่เราเห็นตรงกัน ข้าขอเพียงให้เจ้าออกไปตกปลาเรนโบว์ฟินอัลบาคอร์ดิบมาเยอะ ๆ ปรุงให้สุกทั้งหมด แล้วนำกลับมาให้ข้าที่นี่ อืม อืม แค่คิดก็ลิ้มรสได้แล้ว" },
        progress = { "120:2055590168:1135689234 C 1:63:63", "ข้าพนันได้เลยว่าเจ้ากลับมาพร้อมเรนโบว์ฟินอัลบาคอร์ทั้งหมดที่เราคุยกันไว้ ใช่ไหม {class}?" },
        completion = { "324:313411849:1972020861", "สองชิ้นให้อัลไลแอนซ์ หนึ่งชิ้นให้ข้า สองชิ้นให้อัลไลแอนซ์ หนึ่งชิ้นให้ข้า สวัสดี คนส่งปลา ทำได้ยอดเยี่ยม ข้าเห็นแล้วว่าเจ้าจะทำให้พวกเราภาคภูมิใจจริง ๆ แต่ดูเหมือนยังต้องการปลาอัลบาคอร์เพิ่ม ทำไมไม่ออกไปหาอีกหน่อยล่ะ ข้าได้ยินท้องตัวเองร้องแล้ว" },
        required = { [5095] = { "20:1942141617:1748129237", "ปลาอัลบาคอร์ครีบรุ้ง" } },
        steps = { { "20:1942141617:1748129237", "ปลาอัลบาคอร์ครีบรุ้ง" } },
    },
    [8525] = { -- The Alliance Needs More Rainbow Fin Albacore!
        title = { "45:372424515:657656095", "อัลไลแอนซ์ต้องการเรนโบว์ฟินอัลบาคอร์เพิ่ม!" },
        objective = { "81:1902847048:371709232", "นำ rainbow fin albacore 20 ชิ้นไปให้ Slicky Gastronome ที่สนามบินใน Dun Morogh" },
        description = { "314:623033167:88693832", "อะไรนะ! เจ้าอีกแล้วหรือ? ให้ตายเถอะ... แต่ข้าเป็นโนมนี่นา สลิกกี แกสโทรโนมต่างหาก! กลับมาช่วยอีกสินะ? ข้าก็โทษเจ้าไม่ได้หรอก เจ้าไม่ชอบกลิ่นอาหารทั้งหมดนี่หรือ? <น้ำลายไหล>\n\nเลิกอ้อยอิ่งได้แล้ว! ออกไปนำเรนโบว์ฟินอัลบาคอร์กลับมาให้ข้าเพิ่ม!" },
        progress = { "315:621758350:664391323", "อะไรนะ! เจ้าอีกแล้วหรือ? ให้ตายเถอะ... แต่ข้าเป็นโนมนี่นา สลิกกี แกสโทรโนมต่างหาก! กลับมาช่วยอีกสินะ? ข้าก็โทษเจ้าไม่ได้หรอก เจ้าไม่ชอบกลิ่นอาหารทั้งหมดนี่หรือ? <น้ำลายไหล>\n\nเลิกอ้อยอิ่งได้แล้ว! ออกไปนำเรนโบว์ฟินอัลบาคอร์กลับมาให้ข้าเพิ่ม!" },
        completion = { { "337:396620187:1364882706", "338:1440939540:188428691" }, "ข้ารู้อยู่แล้วว่าเจ้าทำได้ เจ้าหนู เจ้ามีแววของคนที่รู้ว่าตนเองชอบอะไร โดยเฉพาะชอบทำให้ข้ากับผู้มีอำนาจพอใจ และเจ้าก็ทำได้แล้ว ข้ารับรอง\n\nฮ่า ๆ เอาละ ข้าจะเก็บปลาเหล่านี้ให้ถูกวิธีก่อน แล้วเราค่อยมาคุยกันเรื่องที่เจ้าจะไปหาปลาอัลบาคอร์มาอีกยี่สิบชิ้น" },
        required = { [5095] = { "20:1942141617:1748129237", "ปลาอัลบาคอร์ครีบรุ้ง" } },
        objectiveLabels = {
            item = { ["Rainbow Fin Albacore"] = "ปลาอัลบาคอร์ครีบรุ้ง" },
        },
    },
    [8526] = { -- The Alliance Needs Roast Raptor!
        title = { "32:341213693:1128943011", "อัลไลแอนซ์ต้องการแรปเตอร์ย่าง!" },
        objective = { "76:231058931:226413322", "นำ Roast Raptor 20 ชิ้นไปให้ Sarah Sadwhistle ที่ Military Ward ใน Ironforge" },
        description = { "20:1915803497:1747441962 C 387:1598472699:2042343399", "อ้อ เป็นอย่างไรบ้าง {class}? ดูเหมือนเจ้าจะสนใจรวบรวมอาหารสำหรับสงครามอันคิราจที่ใกล้เข้ามาหรือ? ไม่รู้พ่อคิดอย่างไรถึงเห็นว่าการอาสาช่วยที่นี่จะเป็นประสบการณ์เรียนรู้ที่ดีสำหรับข้า คิดผิดมหันต์เลย ข้าไม่ชอบกินเนื้อด้วยซ้ำ\n\nเอาเถอะ ถ้าอยากทำ เจ้าอาจนำแรปเตอร์ย่างกลับมาให้ข้าเยอะ ๆ ดูเหมือนทหารทุกคนจะอยากกินมัน" },
        progress = { "44:2080758203:2031420573", "เจ้ามีแรปเตอร์ย่างทั้งหมดนั่นแล้วหรือยัง?" },
        completion = { "74:1730847697:104981079 C 172:1777160536:950483630", "โอ้ เยี่ยมเลย ขอบคุณที่นำเนื้อสัตว์ไหม้ทั้งหมดนี่มาให้ {class} ข้าจะเอาไปไว้บนกองตรงนั้น คงมีใครสักคนจัดการเอง ข้าว่าถ้าเจ้ามีเวลาว่าง อาจอยากนำมาให้ข้าเพิ่มอีกไหม?" },
        required = { [12210] = { "12:610919183:1280559250", "เนื้อแรปเตอร์ย่าง" } },
        steps = { { "12:610919183:1280559250", "เนื้อแรปเตอร์ย่าง" } },
    },
    [8527] = { -- The Alliance Needs More Roast Raptor!
        title = { "37:150854337:1584009868", "อัลไลแอนซ์ต้องการแรปเตอร์ย่างเพิ่ม!" },
        objective = { "72:1634893822:994652418", "นำ roast raptor 20 ชิ้นไปให้ Sarah Sadwhistle ที่สนามบินใน Dun Morogh" },
        description = { "9:1679429590:134693423 C 179:369047174:597778048", "สวัสดีอีกครั้ง {class} ดูออกเลยว่าเจ้าตื่นเต้นกับเรื่องทั้งหมดนี้มาก ข้าเดาว่าคงอยากนำแรปเตอร์ย่างมาอีกยี่สิบชิ้น เยี่ยม ไปทำเถอะ แล้วคงได้พบกันเมื่อเจ้ากลับมา" },
        progress = { "10:2116678346:464970985 C 179:1280200126:976011568", "สวัสดีอีกครั้ง {class} ดูออกเลยว่าเจ้าตื่นเต้นกับเรื่องทั้งหมดนี้มาก ข้าเดาว่าคงอยากนำแรปเตอร์ย่างมาอีกยี่สิบชิ้นหรือ? เยี่ยม ไปทำเถอะ แล้วคงได้พบกันเมื่อเจ้ากลับมา" },
        completion = { "312:1079684862:209323592", "ว้าว เจ้าไฟแรงจริง ๆ แค่มองก็ทำให้ข้าเหนื่อยแล้ว เอาเถอะ ขอบคุณจากอัลไลแอนซ์และอะไรทำนองนั้น ข้าจะดูแลให้เก็บซากเนื้อทั้งหมดให้เรียบร้อย เจ้าค่อยมาถามทีหลังได้ว่ายังต้องการอีกไหม แต่ถ้าถามข้า มันเริ่มส่งกลิ่นเหม็นไปทั่วแล้ว" },
        required = { [12210] = { "12:610919183:1280559250", "เนื้อแรปเตอร์ย่าง" } },
        objectiveLabels = {
            item = { ["Roast Raptor"] = "เนื้อแรปเตอร์ย่าง" },
        },
    },
    [8528] = { -- The Alliance Needs Spotted Yellowtail!
        title = { "38:922718588:62804437", "อัลไลแอนซ์ต้องการสปอตเต็ดเยลโลว์เทล!" },
        objective = { "85:731477709:556268989", "นำ Spotted Yellowtail 20 ชิ้นไปให้ Huntress Swiftriver ที่ Military Ward ใน Ironforge" },
        description = { "106:1284818172:806911348 C 391:786934287:1166504395", "การรวบรวมปลาปรุงสุกอาจดูไม่ใช่งานวีรชน แต่อย่าดูเบาคุณค่าของการเตรียมพร้อม {class} รุ่นเยาว์ ทหารต้องกินอาหารเหมือนคนอื่น และเรามาทำหน้าที่ของตนเพื่อให้พวกเขามีสิ่งที่ต้องการเมื่อสงครามอันคิราจเริ่มขึ้น\n\nข้าจึงสะสมสปอตเต็ดเยลโลว์เทล แหล่งอาหารสารพัดประโยชน์ที่เก็บได้ดีและใช้ทำอาหารได้หลายชนิด อีกทั้งไม่มีกลิ่นแรงเหมือนปลาน้ำเค็มบางชนิด เจ้ายินดีช่วยข้าในงานนี้หรือไม่?" },
        progress = { "87:1351035566:2106041903", "ข้ามั่นใจว่าเจ้ากลับมาเร็วขนาดนี้พร้อมสปอตเต็ดเยลโลว์เทลที่เราคุยกันไว้" },
        completion = { "25:2046005701:63887199 C 206:1294635806:525993797", "ขอบคุณสำหรับของที่นำมา {class} และยังนำมาได้ทันเวลาอีกด้วย ทหารของเราต้องไม่ขาดอาหารแน่นอน ขอข้าเก็บปลาเหล่านี้ให้ถูกวิธีก่อน แล้วเราค่อยมาคุยกันเรื่องขนรอบที่สอง หากเจ้ายินดี" },
        required = { [6887] = { "18:1236098111:1931550847", "ปลาหางเหลืองลายจุด" } },
        steps = { { "18:1236098111:1931550847", "ปลาหางเหลืองลายจุด" } },
    },
    [8529] = { -- The Alliance Needs More Spotted Yellowtail!
        title = { "43:1321057205:757539507", "อัลไลแอนซ์ต้องการสปอตเต็ดเยลโลว์เทลเพิ่ม!" },
        objective = { "81:893698730:1609300451", "นำ spotted yellowtail 20 ชิ้นไปให้ Huntress Swiftriver ที่สนามบินใน Dun Morogh" },
        description = { "102:1368322097:1606197429 N 126:1001948020:694932369", "หากเจ้ายังยินดี ข้าอยากส่งเจ้าออกไปนำสปอตเต็ดเยลโลว์เทลกลับมาอีกชุด {name} ด้วยความชำนาญที่ได้จากครั้งแรก ข้าคิดว่ารอบนี้น่าจะจับได้รวดเร็วและง่ายกว่ามาก เจ้าสนไหม?" },
        progress = { "102:1368322097:1606197429 N 126:1001948020:694932369", "หากเจ้ายังยินดี ข้าอยากส่งเจ้าออกไปนำสปอตเต็ดเยลโลว์เทลกลับมาอีกชุด {name} ด้วยความชำนาญที่ได้จากครั้งแรก ข้าคิดว่ารอบนี้น่าจะจับได้รวดเร็วและง่ายกว่ามาก เจ้าสนไหม?" },
        completion = { "39:1784388534:254284016 N 254:1126542235:61807832", "เจ้าเป็นชาวอัลไลแอนซ์ที่แท้จริง {name} ความพยายามของเจ้าจะไม่ถูกมองข้ามหรือไร้คำขอบคุณ และขอบคุณที่ปรุงปลามาให้ด้วย ข้าจะดูแลให้เก็บอย่างถูกวิธี แล้วปรับยอดนับ ปลาแต่ละชิ้นทำให้เราใกล้ถึงเป้าหมายขึ้นอีกนิด" },
        required = { [6887] = { "18:1236098111:1931550847", "ปลาหางเหลืองลายจุด" } },
        objectiveLabels = {
            item = { ["Spotted Yellowtail"] = "ปลาหางเหลืองลายจุด" },
        },
    },
    [8532] = { -- The Horde Needs Copper Bars!
        title = { "28:144877612:963062238", "ฮอร์ดต้องการแท่งทองแดง!" },
        objective = { "77:2140353577:138323257", "นำ Copper Bars 20 แท่งไปให้ Miner Cromwell ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "351:1798644310:1822357221 C 1:63:63", "ดีใจมากที่เจ้าตัดสินใจช่วยงานที่นี่ ไม่ใช่ทุกคนจะทำเช่นนั้น ข้าจึงต้องแน่ใจว่าเจ้าเข้าใจสิ่งที่ข้าต้องการ แท่งทองแดง ไม่ใช่แร่ทองแดง เราไม่มีเวลาหรือคนมาหลอมเองทั้งหมด หากเจ้ากรุณาจัดการให้ ความพยายามของเจ้าจะได้รับการบันทึกไว้อย่างสมควร เจ้ารับงานนี้ไหวไหม {class}?" },
        progress = { "62:897601630:1110496213 C 1:46:46", "ข้าหวังว่านั่นคือทองแดงยี่สิบแท่งที่เจ้าพกมา {class}" },
        completion = { "337:2121574694:1102849752", "แท่งพวกนี้ใช้ได้ และขอบใจที่ไม่ขัดเงามัน ไม่มีประโยชน์จะทำให้สวยในเมื่อจะถูกดัดแปลงเป็นยุทโธปกรณ์ที่ต้องสร้างสำหรับสงคราม ข้าจะนำไปวางเข้ากอง และดูแลให้ถูกใช้อย่างเหมาะสม คุยกับข้าอีกครั้งหากเจ้าสนใจนำมาเพิ่มอีกยี่สิบแท่ง" },
        required = { [2840] = { "10:1315783122:1190376755", "แท่งทองแดง" } },
        steps = { { "10:1315783122:1190376755", "แท่งทองแดง" } },
    },
    [8533] = { -- The Horde Needs More Copper Bars!
        title = { "33:229481311:988089130", "ฮอร์ดต้องการแท่งทองแดงเพิ่ม!" },
        objective = { "50:1219032247:1153258208", "นำ copper bars 20 แท่งไปให้ Miner Cromwell ใน Durotar" },
        description = { "48:2118356325:160529265 C 211:2033247904:175159387", "กลับมาเร็วขนาดนี้เลยหรือ? อีกไม่นานเจ้าคงเป็นคนขุดแร่ตัวจริง {class} เจ้ารู้ขั้นตอนแล้ว ข้าต้องการให้เจ้าออกไปขุดแร่ทองแดงมาเยอะ ๆ หลอมเป็นแท่ง แล้วนำกลับมาให้ข้าที่นี่ ข้ารู้ว่าเจ้าทำได้ คำถามคือเจ้ายินดีทำหรือไม่?" },
        progress = { "49:1104215950:1701982658 C 211:2033247904:175159387", "กลับมาเร็วขนาดนี้เลยหรือ? อีกไม่นานเจ้าคงเป็นคนขุดแร่ตัวจริง {class} เจ้ารู้ขั้นตอนแล้ว ข้าต้องการให้เจ้าออกไปขุดแร่ทองแดงมาเยอะ ๆ หลอมเป็นแท่ง แล้วนำกลับมาให้ข้าที่นี่ ข้ารู้ว่าเจ้าทำได้ คำถามคือเจ้ายินดีทำหรือไม่?" },
        completion = { "40:1099069987:2040108152 C 228:287484471:1231762027", "เจ้าพิสูจน์ตัวเองให้ข้าเห็นอีกครั้ง {class} ข้าจะดูแลให้ทองแดงถูกนำไปใช้เมื่อถึงเวลา แต่ตอนนี้ต้องนำแท่งทองแดงขึ้นแท่นบรรทุกและนับจำนวนก่อน หากเจ้ายังอยากช่วย ข้าก็คงต้องการแรงเจ้ารวบรวมแท่งทองแดงเพิ่มอีก" },
        required = { [2840] = { "10:1315783122:1190376755", "แท่งทองแดง" } },
        objectiveLabels = {
            item = { ["Copper Bar"] = "แท่งทองแดง" },
        },
    },
    [8542] = { -- The Horde Needs Tin Bars!
        title = { "25:859444919:680385125", "ฮอร์ดต้องการแท่งดีบุก!" },
        objective = { "70:579288566:1997204895", "นำ Tin Bars 20 แท่งไปให้ Grunt Maug ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "9:860935253:1249669357 R 477:2001711319:572880881", "ล็อกทาร์ {race} ข้ามั่นใจว่าเจ้ารู้อยู่แล้วว่าเรากำลังจะทำสงครามกับพวกแมลงที่อันคิราจ แต่ก่อนอื่น วอร์ชีฟตัดสินใจว่าเราต้องทำสิ่งที่เรียกว่า 'เตรียมพร้อม' แม้ข้าอยากลับอาวุธและตีเกราะให้เข้ารูปมากกว่า แต่ก็ภูมิใจที่ได้รับเลือกให้ดูแลการรวบรวมแท่งดีบุกที่นี่ ทว่าข้าทำไม่ได้หากไม่มีเจ้าช่วย\n\nข้าจึงต้องการให้เจ้าออกไปทำแท่งดีบุก แล้วนำกลับมาให้ข้า ข้าคิดว่าคงต้องการมากเกินกว่าที่ตัวเองจะนับไหว" },
        progress = { "37:720262810:1531284368 C 75:1560977484:1620865660", "เจ้ามีดีบุกมากี่แท่ง {class}? หลังสงครามข้าคงต้องหาคนมาสอนนับเลข" },
        completion = { "82:406884655:1499614307 C 123:2089168606:869775907", "เอาละ ข้าว่าดีบุกดูมีจำนวนถูกต้อง อย่าคิดหลอกข้านะ {class}! นับเลขแล้วปวดกะโหลก ทีนี้ข้าจะเอาแท่งพวกนี้ไปเข้ากอง ส่วนเจ้าก็ออกไปนำแบบเดียวกันมาเพิ่ม" },
        required = { [3576] = { "7:250598727:56063776", "แท่งดีบุก" } },
        steps = { { "7:250598727:56063776", "แท่งดีบุก" } },
    },
    [8543] = { -- The Horde Needs More Tin Bars!
        title = { "30:2076637730:2124860949", "ฮอร์ดต้องการแท่งดีบุกเพิ่ม!" },
        objective = { "43:44315108:396070879", "นำ tin bars 20 แท่งไปให้ Grunt Maug ใน Durotar" },
        description = { "292:127690792:1819989193", "ดีมาก เห็นแล้วว่าเจ้าจริงจังกับสงคราม แต่ข้าหงุดหงิดนิดหน่อยที่ต้องรอให้มันเริ่ม หมายความว่าข้าจะโมโหถ้าเจ้าไม่เริ่มนำของมาให้เร็วขึ้น บางทีข้าอาจซ้อมกับเจ้าแทน\n\nฮ่า! คงไม่ดีกว่า เพราะถ้าอย่างนั้นใครจะเอาแท่งดีบุกกลับมาให้ข้า?" },
        progress = { "132:1665916230:2121877588 C 311:1359771161:1377674806", "ดีมาก เห็นแล้วว่าเจ้าจริงจังกับสงคราม แต่ข้าหงุดหงิดนิดหน่อยที่ต้องรอให้มันเริ่ม ข้ามั่นใจว่าเจ้าก็เช่นกัน {class} เมื่อเริ่มขึ้นคงรุ่งโรจน์ ฮอร์ดจะวิ่งข้ามผืนทรายทะเลทรายซิลิธัส ถืออาวุธพุ่งเข้าใส่ฝูงแมลง วันนั้นทุกคนจะได้รับเกียรติยศอันยิ่งใหญ่!\n\nฮ่า! แต่ก่อนอื่นเราต้องการแท่งดีบุกเพิ่ม น่าขันที่ของเล็กน้อยเช่นนี้อาจสร้างความแตกต่างมหาศาล เจ้าคิดอย่างนั้นไหม?" },
        completion = { "10:1652484069:1189355142 N 260:2147326609:364497043", "ธรอมคา {name} แท่งดีบุกของเจ้าให้เกียรติทั้งข้าและฮอร์ด ข้าจะวางมันเข้ากอง แล้วพวกเขาจะนำไปผลิตของ เมื่อทั้งหมดเสร็จ เราจะออกสงครามและแสดงให้อัลไลแอนซ์อ่อนแอเห็นว่าต้องสู้แมลงอย่างไร\n\nทีนี้นำแท่งดีบุกกลับมาให้ข้าเพิ่ม!" },
        required = { [3576] = { "7:250598727:56063776", "แท่งดีบุก" } },
        objectiveLabels = {
            item = { ["Tin Bar"] = "แท่งดีบุก" },
        },
    },
    [8545] = { -- The Horde Needs Mithril Bars!
        title = { "29:58369818:1510018672", "ฮอร์ดต้องการแท่งมิธริล!" },
        objective = { "87:1468933161:1890933568", "นำ Mithril Bars 20 แท่งไปให้ Senior Sergeant T'kelah ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "C 406:193419860:357680354", "{class} สงครามใกล้เข้ามาแล้ว สิ่งเดียวที่เราทำได้คือเตรียมพร้อม ตรงนี้ละที่เจ้ากับข้าช่วยกันได้ สหาย พวกเขาให้ข้ารวบรวมแท่งมิธริลทั้งหมดที่ต้องใช้สร้างของจำเป็น และข้ายังต้องการอีก!\n\nข้าจึงหวังว่าเจ้าจะออกไปขุดมิธริลมาให้เรา แล้วหลอมเป็นแท่ง ฟังดูเป็นงานที่เจ้าทำให้เราได้ไหม?" },
        progress = { "154:71308015:1975217750", "คงดีจริง ๆ ถ้าได้แท่งมิธริลครบตามที่ต้องการเพื่องานระดมเสบียงสงครามอันคิราจ นั่นคือเหตุผลที่เจ้ากลับมาหรือ สหาย? เจ้าหาแท่งของข้าได้แล้วหรือ?" },
        completion = { "36:602668619:1815553926 C 285:1775618456:1250469222", "เป็นการเริ่มต้นที่ดีสำหรับเจ้ากับข้า {class} ได้มิธริลเพิ่มอีกยี่สิบแท่งไว้เข้ากองและขีดออกจากรายการ ทุกแท่งจะนำไปผลิตยุทโธปกรณ์อย่างคุ้มค่า\n\nอย่าลืมกลับมาถามข้า เพราะดูเหมือนเราจะต้องการแท่งมิธริลเพิ่มอีกแน่ ๆ" },
        required = { [3860] = { "11:1665667963:654296337", "แท่งมิธริล" } },
        steps = { { "11:1665667963:654296337", "แท่งมิธริล" } },
    },
    [8546] = { -- The Horde Needs More Mithril Bars!
        title = { "34:326683991:493574266", "ฮอร์ดต้องการแท่งมิธริลเพิ่ม!" },
        objective = { "87:1468933161:1890933568", "นำ Mithril Bars 20 แท่งไปให้ Senior Sergeant T'kelah ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "383:593888829:2029929416", "ใช่ ดีใจที่เจ้ามา สหาย เจ้าเคยช่วยข้าแล้ว และตอนนี้ข้าต้องการความช่วยเหลืออีก เรายังรวบรวมแท่งมิธริลเพิ่มเพื่องานสงคราม จะสร้างเกราะ อาวุธ และสิ่งต่าง ๆ ไว้บดขยี้แมลงที่อันคิราจ\n\nถ้าเจ้าเป็นเพื่อนแท้ ก็นำแท่งมิธริลกลับมาอีกหลายกอง ข้าจะรับทุกแท่งจนกว่าจะครบโควตา ตอนนี้เจ้ามีมาให้ข้าหรือไม่?" },
        completion = { "18:1403743048:1737996753 N 215:1246869786:1404849532", "ทำได้ดี {name}! เพิ่มอีกยี่สิบแท่งก็ทำให้ใกล้เป้าหมายขึ้นอีก และได้ยุทโธปกรณ์เพิ่ม ข้าจะดูแลให้เก็บเรียบร้อย และถ้าเจ้าได้แท่งมิธริลมาอีกกอง สหาย อย่าลืมนำมาให้ข้าที่นี่" },
        required = { [3860] = { "11:1665667963:654296337", "แท่งมิธริล" } },
        objectiveLabels = {
            item = { ["Mithril Bar"] = "แท่งมิธริล" },
        },
    },
    [8549] = { -- The Horde Needs Peacebloom!
        title = { "27:1542995799:1725934288", "ฮอร์ดต้องการพีซบลูม!" },
        objective = { "84:844348661:60887685", "นำ Peacebloom 20 ชิ้นไปให้ Herbalist Proudfeather ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "464:1582669560:1591048358 C 1:63:63", "ว่ากันว่าทุกยุคสมัยต้องเผชิญบททดสอบที่กำหนดตัวตน ข้าเกรงว่าสงครามอันคิราจจะเป็นเบ้าหลอมทดสอบความกล้าของเรา เราจึงเตรียมพร้อม และค้นพบว่าแท้จริงเราเป็นเช่นไร\n\nข้าอาสาช่วยฮอร์ดรวบรวมพีซบลูมให้มากที่สุด เพื่อใช้ทำยาสำหรับสงคราม หวังว่าเจ้ามาที่นี่เพื่อช่วยข้า ถ้าใช่ ข้าต้องการให้เจ้านำสมุนไพรชนิดนี้กลับมาในปริมาณมาก เจ้าจะช่วยข้าไหม {class}?" },
        progress = { "34:1184586639:719973377 C 1:63:63", "กลับมาเร็วขนาดนี้พร้อมพีซบลูมแล้วหรือ {class}?" },
        completion = { "110:1321611699:1778539946 C 86:1705589937:1992580128 N 131:1805298733:506712272", "ความพยายามของเราจึงผลักเราเข้าใกล้สงครามอีกนิด ขอบคุณที่ทุ่มแรงรวบรวมพีซบลูมนี้ {class} ข้ารับรองว่าจะใช้ให้คุ้มค่า และบันทึกความช่วยเหลือของเจ้าไว้แล้ว {name} หากยังเต็มใจ โปรดนำดอกไม้กลับมาให้ข้าอีก จนกว่าจะถึงตอนนั้น ขอให้พระแม่ธรณีนำทางเจ้า" },
        required = { [2447] = { "10:1280200047:1210503404", "สมุนไพร Peacebloom" } },
        objectiveLabels = {
            item = { ["Peacebloom"] = "สมุนไพร Peacebloom" },
        },
    },
    [8550] = { -- The Horde Needs Peacebloom!
        title = { "27:1542995799:1725934288", "ฮอร์ดต้องการพีซบลูม!", variants = { { "32:565676799:1972020405", "ฮอร์ดต้องการพีซบลูมเพิ่ม!" } } },
        objective = { "84:844348661:60887685", "นำ Peacebloom 20 ชิ้นไปให้ Herbalist Proudfeather ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "251:1456214392:1428574854 C 238:266870152:1166961359", "สวัสดีอีกครั้ง Abyssmal ข้าดีใจที่เจ้าอยากคุยกับข้าอีกเรื่องความต้องการพีซบลูมที่ไม่สิ้นสุด งานระดมเสบียงสงครามยังดำเนินต่อ เช่นเดียวกับการผลิตยาและน้ำยาเสริมพลังไว้ช่วยในการรบที่กำลังจะมา เจ้าจะช่วยเราอีกไหม {class}? ข้าต้องการพีซบลูมจำนวนเท่าครั้งก่อน หากเจ้ารวบรวมแล้วนำกลับมาให้ข้าที่นี่ได้ ข้าจะขอบคุณมาก แน่นอนว่าถ้าเจ้ามีติดตัวอยู่แล้ว ข้าก็ยินดีรับเดี๋ยวนี้", variants = { { "13:1366380142:1891123769 N 230:1174480825:1036620698 C 239:2013636053:400600416", "สวัสดีอีกครั้ง {name} ข้าดีใจที่เจ้ากลับมาคุยเรื่องพีซบลูมที่เรายังต้องการอยู่เสมอ งานระดมเสบียงสงครามยังดำเนินต่อ เราจึงต้องผลิตยาและน้ำยาเสริมพลังไว้ใช้ในการรบที่กำลังจะมาถึง\n\nเจ้าจะช่วยเราอีกครั้งไหม {class}? ข้าต้องการพีซบลูมจำนวนเท่าครั้งก่อน หากเจ้ารวบรวมแล้วนำกลับมาให้ข้าที่นี่ ข้าจะขอบคุณมาก แน่นอนว่าถ้ามีติดตัวอยู่แล้ว ข้าก็ยินดีรับตอนนี้เลย" } } },
        completion = { "38:1961757061:1700682873 N 318:2143758930:559241423", "ขอบคุณที่ช่วยอย่างต่อเนื่อง {name} การให้โดยไม่เห็นแก่ตนของเจ้าสร้างเกียรติยศยิ่งใหญ่แก่ตนเองและบรรพบุรุษ ทุกคนจะได้รับรู้! ข้าจะเก็บสมุนไพรให้สดไว้จนกว่าจะต้องใช้ เจ้าเผยจิตวิญญาณที่แท้จริงของฮอร์ดอีกครั้ง ทั้งการดิ้นรนเอาชนะอุปสรรคและคำมั่นว่าเราจะร่วมแรงกันทำให้สำเร็จได้" },
        required = { [2447] = { "10:1280200047:1210503404", "สมุนไพร Peacebloom" } },
        objectiveLabels = {
            item = { ["Peacebloom"] = "สมุนไพร Peacebloom" },
        },
    },
    [8580] = { -- The Horde Needs Firebloom!
        title = { "26:1102524587:1148627573", "ฮอร์ดต้องการไฟร์บลูม!" },
        objective = { "80:152751848:1005992924", "นำ Firebloom 20 ชิ้นไปให้ Batrider Pele'keiki ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "5:140209925:2105781119 C 361:869059204:87073130", "เฮ้ {class} ใช่ เจ้านั่นแหละ สหาย! ฮอร์ดคิดว่าต้องการไฟร์บลูมมากมายเพื่องานระดมเสบียงสงครามอันคิราจ บางทีพวกเขาอาจใส่มันในของดี ๆ ที่ระเบิดตูม? บางทีอาจให้อัลไลแอนซ์เป็นเชื้อเพลิงรถถังไอน้ำ? ใครจะรู้? เพเลเคกิไม่รู้!\n\nแต่เพเลเคกิรู้สิ่งนี้... รู้ว่าเจ้าจะช่วยเขาและนำไฟร์บลูมกลับมาเยอะ ๆ ใช่ไหม สหาย?" },
        progress = { "108:1306882174:1956833342", "เจ้าไม่อยากทำให้เพเลเคกิโกรธหรอก เจ้าทำให้เพเลเคกิมีความสุขได้ ด้วยการนำไฟร์บลูมมาเยอะ ๆ เร็ว ๆ นี้" },
        completion = { "C 284:1145310721:1311987011", "{class}! ตอนนี้เพเลเคกิมีความสุข เพเลเคกิเอาไฟร์บลูมทั้งหมดใส่กล่องรักษาความสด เพเลเคกิจะดูแลให้ไฟร์บลูมทั้งหมดกลายเป็นของดีสำหรับสงคราม และถ้าเจ้าได้มาอีก รีบมาหาเพเลเคกิ เพเลเคกิอาจต้องการเพิ่ม" },
        required = { [4625] = { "9:1612325674:1939894020", "ดอกไฟ" } },
        objectiveLabels = {
            item = { ["Firebloom"] = "ดอกไฟ" },
        },
    },
    [8581] = { -- The Horde Needs More Firebloom!
        title = { "31:388464552:1396401165", "ฮอร์ดต้องการไฟร์บลูมเพิ่ม!" },
        objective = { "80:152751848:1005992924", "นำ Firebloom 20 ชิ้นไปให้ Batrider Pele'keiki ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "228:442737390:586272590 C 133:1353941019:159630703", "เพเลเคกิรู้ว่าเจ้ามาช่วย นำไฟร์บลูมมาเยอะ ๆ แล้วทำให้เขามีความสุขมาก เพเลเคกิอาจทำระเบิดลูกใหญ่จากไฟร์บลูม ทิ้งใส่แมลงจากหลังค้างคาวเหนืออันคิราจเมื่อสงครามมาถึง แต่เพเลเคกิต้องการไฟร์บลูมเพิ่ม {class}!\n\nเจ้าจะนำไฟร์บลูมมาให้เพเลเคกิ เร็ว ๆ เลย กลับมาพร้อมของอย่างน้อยเท่าครั้งก่อน แล้วเพเลเคกิจะพอใจ" },
        completion = { "14:45712574:1443710355 C 141:952201327:28906121 N 134:1550776641:225339814", "นี่ไม่ได้ล้อเล่นใช่ไหม {class}? เจ้านำไฟร์บลูมมาให้เพเลเคกิเร็วขนาดนี้เลยหรือ? เพเลเคกิจะนับเดี๋ยวนี้ สหาย! เจ้าทำให้เพเลเคกิมีความสุขมาก เขาจะบอกทุกคนว่า {name} เป็นคนรวบรวมไฟร์บลูมเก่งที่สุด! เพเลเคกิรอให้สงครามเริ่มแทบไม่ไหว ทีนี้เราจะทำให้ท้องฟ้าเหนือซิลิธัสสว่างไสวจริง ๆ ใช่ไหม พี่น้อง?!" },
        required = { [4625] = { "9:1612325674:1939894020", "ดอกไฟ" } },
        objectiveLabels = {
            item = { ["Firebloom"] = "ดอกไฟ" },
        },
    },
    [8582] = { -- The Horde Needs Purple Lotus!
        title = { "29:913135746:476321170", "ฮอร์ดต้องการเพอร์เพิลโลตัส!" },
        objective = { "80:1756236173:1676225487", "นำ Purple Lotus 20 ชิ้นไปให้ Apothecary Jezel ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "18:1721548067:263294788 C 483:1165736154:1774729912", "เพอร์เพิลโลตัส {class} เป็นส่วนผสมของยา น้ำยาเสริมพลัง และน้ำมันมากมาย บางชนิดจะเป็นประโยชน์แก่เราที่อันคิราจ เราต้องผลิตยาเหล่านั้นจำนวนมหาศาลเพื่องานสงคราม และข้าจะทดลองหาประโยชน์อื่นจากดอกบัวด้วย แต่เพื่อทำทั้งหมดนั้น ข้าต้องการดอกไม้ปริมาณมาก\n\nตรงนี้ละที่ต้องพึ่งเจ้า ออกไปข้างนอกและรวบรวมเพอร์เพิลโลตัสให้มากที่สุด เจ้าจะยินดีทำเพื่อเราหรือไม่?" },
        progress = { "62:1466057516:2011692926 C 118:631264545:2101841540", "กลับมาพร้อมเพอร์เพิลโลตัสที่ข้าขอแล้วหรือ {class}? เจ้าต้องทำให้เร็วที่สุดเท่าที่เป็นไปได้ ไม่เช่นนั้นสิ่งที่ข้าพยายามทำที่นี่ทั้งหมดอาจสูญเปล่า" },
        completion = { "22:55365095:2098636215 C 304:1001549976:728604574", "เป็นความพยายามที่น่าชื่นชม {class} ข้าจะชั่งตวงตัวอย่างเหล่านี้เพื่อใช้ให้เหมาะสม และบันทึกความช่วยเหลือของเจ้า จากนั้นต้องเก็บเพอร์เพิลโลตัสให้ถูกวิธีจนกว่าข้าจะพร้อมใช้ ส่วนเจ้า หากยังว่าง ข้าคิดว่าคงต้องการเพอร์เพิลโลตัสเพิ่ม โปรดกลับมาถามข้าอีกสักครู่" },
        required = { [8831] = { "12:571983408:84265363", "ดอกบัวสีม่วง" } },
        steps = { { "12:571983408:84265363", "ดอกบัวสีม่วง" } },
    },
    [8583] = { -- The Horde Needs More Purple Lotus!
        title = { "34:1181449919:1607360393", "ฮอร์ดต้องการเพอร์เพิลโลตัสเพิ่ม!" },
        objective = { "80:1756236173:1676225487", "นำ Purple Lotus 20 ชิ้นไปให้ Apothecary Jezel ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "70:738651773:1977889286 C 263:1391713726:1224365428", "ดูเหมือนเราต้องการเพอร์เพิลโลตัสเพิ่มอีกจริง ๆ {class} แม้งานศึกษาของข้ายังไม่ค้นพบวิธีใช้สมุนไพรแบบใหม่ที่เป็นประโยชน์ แต่ก็ยังมีวิธีที่พิสูจน์แล้วว่าได้ผลรอให้ใช้อยู่\n\nข้าต้องการให้เจ้าออกไปรวบรวมตัวอย่างเพอร์เพิลโลตัสอย่างน้อยยี่สิบชิ้นอีกครั้ง แล้วนำกลับมาให้ข้าที่นี่" },
        completion = { "28:1095484231:124323925 N 243:2125183037:627139982", "ทำงานได้ยอดเยี่ยมและแม่นยำ {name} ทั้งความพากเพียรและความรวดเร็วของเจ้าสมควรได้รับคำชม ข้าจะดูแลด้วยตนเองไม่ให้เพอร์เพิลโลตัสเหล่านี้เสียเปล่าแม้แต่ชิ้นเดียว\n\nขอบคุณอีกครั้ง และถ้าเจ้าได้เพอร์เพิลโลตัสมาเพิ่ม อย่าลังเลที่จะนำมาให้ข้าโดยเร็วที่สุด" },
        required = { [8831] = { "12:571983408:84265363", "ดอกบัวสีม่วง" } },
        objectiveLabels = {
            item = { ["Purple Lotus"] = "ดอกบัวสีม่วง" },
        },
    },
    [8588] = { -- The Horde Needs Heavy Leather!
        title = { "30:945357449:994292286", "ฮอร์ดต้องการหนังหนัก!" },
        objective = { "79:1025301395:1348356383", "นำ Heavy Leather 10 ชิ้นไปให้ Skinner Jamani ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "356:1019317881:1493628795 C 73:453536612:1598284609", "ในเมื่อเรากำลังเตรียมสงคราม ก็ควรรวบรวมของจำเป็นให้ครบก่อน จริงไหม สหาย? หนังหนักเป็นวัตถุดิบหลักอย่างหนึ่งของยุทโธปกรณ์ที่เรากำลังผลิต ใช้ได้แทบทุกอย่าง ตั้งแต่งานเสริมความแข็งแรง เกราะ ไปจนถึงผ้าใบคลุมธรรมดา\n\nแต่ก่อนอื่นต้องหามาเพิ่ม นั่นคืองานของเจ้า {class} ลับมีดให้คมแล้วนำกลับมาสักมัด จากนั้นเราค่อยคุยกันต่อ" },
        progress = { "65:751678142:300800350 C 107:198277737:1685198652", "ข้าไม่มีเวลาเล่นด้วยหากเจ้ามาแค่พูดพร่ำ {class} ยังมีหนังหนักต้องฟอกอีกหลายกอง กลับมาเมื่อมีให้ข้าอย่างน้อยสิบชิ้น" },
        completion = { "75:1226861516:347603314 C 212:1961160196:680601420", "อ้อ เจ้ามีหนังหนักที่ข้าต้องการจริง ๆ มีดเจ้าคมทีเดียว {class} หนังพวกนี้ดีมาก! เมื่อเราเริ่มต้นกันด้วยดีแล้ว ข้าจะดูแลให้สิ่งที่เจ้าบริจาคถูกใช้ประโยชน์ และถ้าเจ้าได้หนังหนักมาอีก ก็นำมาให้ข้า" },
        required = { [4234] = { "13:170018158:1996489922", "หนังชนิดหนัก" } },
        steps = { { "13:170018158:1996489922", "หนังชนิดหนัก" } },
    },
    [8589] = { -- The Horde Needs More Heavy Leather!
        title = { "35:1182623206:984060098", "ฮอร์ดต้องการหนังหนักเพิ่ม!" },
        objective = { "79:1025301395:1348356383", "นำ Heavy Leather 10 ชิ้นไปให้ Skinner Jamani ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "11:1058231119:860074956 C 226:46307792:1093139745 N 59:444634425:1966395769", "จริงสิ {class} ข้ายังต้องการหนังหนักเพิ่ม คำขอจากเหล่าแม่ทัพและนายกองเสบียงดูไม่มีที่สิ้นสุด และนั่นยังน้อยเมื่อเทียบกับสิ่งที่เหล่านายเรือเหาะขอ!\n\nข้าต้องรวบรวมให้ครบโควตาโดยเร็ว {name} นำหนังหนักกลับมาเพิ่มอีกหลายกองทันทีที่ทำได้!" },
        completion = { "205:1489367658:1580764624 N 86:169487650:1263221984", "เจ้ายอดเยี่ยมจริง ๆ สหาย! ขอบคุณมากสำหรับหนังหนัก ทุกชิ้นทำให้เราใกล้เป้าหมายขึ้นอีกนิด ข้าจะนำไปไว้บนกอง เพื่อให้ช่างเครื่องหนังคนอื่นเริ่มทำงานได้\n\nขอบคุณอีกครั้ง {name} ถ้าเจ้าได้หนังหนักมาอีกหลายกอง ก็รู้แล้วว่าจะมาหาข้าได้ที่ไหน" },
        required = { [4234] = { "13:170018158:1996489922", "หนังชนิดหนัก" } },
        objectiveLabels = {
            item = { ["Heavy Leather"] = "หนังชนิดหนัก" },
        },
    },
    [8590] = { -- The Horde Needs Thick Leather!
        title = { "30:1662157097:1717074839", "ฮอร์ดต้องการหนังหนา!" },
        objective = { "79:751997007:813946934", "นำ Thick Leather 10 ชิ้นไปให้ Sergeant Umala ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "53:114907911:1012599023 C 399:1136327497:139217076", "ข้าดีใจที่เจ้าตัดสินใจคุยกับข้าเรื่องนี้ {class} ดูเหมือนการเตรียมสงครามอันคิราจของฮอร์ดกำลังดำเนินเต็มที่ แต่เจ้ากับข้ายังต้องทำหน้าที่ของเรา\n\nข้าได้รับคำขอให้รวบรวมหนังหนาจำนวนมากสำหรับยุทโธปกรณ์ทุกชนิด และต้องการให้เจ้าช่วยออกไปรวบรวม หากตัดสินใจช่วย เจ้าจะได้รับเกียรติยศกับคำขอบคุณจากฮอร์ด เจ้าจะช่วยไหม?" },
        progress = { "C 73:5632239:1527646912", "{class} เจ้ากลับมาเร็วขนาดนี้พร้อมหนังหนาสิบชิ้นที่เราคุยกันไว้แล้วหรือ?" },
        completion = { "11:354343371:1318038540 C 263:585677561:1552065302", "ทำได้ดี {class} ข้ามั่นใจว่าหนังหนาเหล่านี้จะถูกใช้เสริมความแข็งแรงเรือเหาะ และผลิตเกราะกับอาวุธทุกชนิด เจ้ารับคำขอบคุณจากข้าและฮอร์ดไปได้เลย กลับมาอีกหากพบหนังหนาเพิ่มระหว่างเดินทาง ขอให้โชคดี" },
        required = { [4304] = { "13:983336109:1264322130", "หนังหนา" } },
        steps = { { "13:983336109:1264322130", "หนังหนา" } },
    },
    [8591] = { -- The Horde Needs More Thick Leather!
        title = { "35:1899422854:1706842651", "ฮอร์ดต้องการหนังหนาเพิ่ม!" },
        objective = { "79:751997007:813946934", "นำ Thick Leather 10 ชิ้นไปให้ Sergeant Umala ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { { "C 304:807308944:1668783589", "C 306:1173744298:1466423418" }, "{class} อย่างที่เจ้าเห็น ข้ายังต้องรวบรวมหนังหนาเพิ่ม ข้าขอความช่วยเหลือในงานนี้อีกครั้ง และสัญญาว่าหากเจ้าทำสำเร็จ ความพยายามของเจ้าจะได้รับการยอมรับ\n\nเวลาสำคัญยิ่ง! นำหนังหนากลับมาให้ข้า เพื่อให้เราเตรียมพร้อมเสร็จและออกสงคราม วีรชน!", variants = { { "C 303:1331740113:324205898", "{class} อย่างที่เจ้าเห็น ข้ายังต้องรวบรวมหนังหนาเพิ่ม ข้าขอความช่วยเหลือในงานนี้อีกครั้ง และสัญญาว่าหากเจ้าทำสำเร็จ ความพยายามของเจ้าจะได้รับการยอมรับ\n\nเวลาสำคัญยิ่ง! นำหนังหนากลับมาให้ข้า เพื่อให้เราเตรียมพร้อมเสร็จและออกสงคราม วีรชน!" } } },
        completion = { "12:1189578666:1809041287 N 249:2101925963:972074988 C 1:33:33", "เจ้าทำได้แล้ว {name} ข้ารู้อยู่แล้วว่าเจ้าจะทำได้! ขอขอบคุณในนามฮอร์ดทั้งหมดอีกครั้ง เราบันทึกความพยายามของเจ้าไว้และซาบซึ้งอย่างยิ่ง ถ้าเจ้ามีหนังหนาเพิ่มและอยากบริจาค ก็นำมาให้ข้าที่นี่\n\nล็อกทาร์ โอการ์ {class}!" },
        required = { [4304] = { "13:983336109:1264322130", "หนังหนา" } },
        objectiveLabels = {
            item = { ["Thick Leather"] = "หนังหนา" },
        },
    },
    [8600] = { -- The Horde Needs Rugged Leather!
        title = { "31:1038007738:1619023723", "ฮอร์ดต้องการหนังหยาบ!" },
        objective = { "81:129660219:939539169", "นำ Rugged Leather 10 ชิ้นไปให้ Doctor Serratus ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "197:182943445:181011978 C 304:1371309321:1383663992", "ข้าพบว่าการจับมีดให้พอดีมือสำคัญกว่าความคมของมัน ต่อให้คมมีดทื่อที่สุดก็ยังตัดได้ หากออกแรงผ่านมันอย่างถูกต้อง เจ้าคงเห็นด้วยใช่ไหม {class}? แต่เจ้ากับข้าไม่มีปัญหาเช่นนั้น เพราะเรารักษาคมมีดให้คมที่สุดอยู่เสมอ จริงไหม?\n\nเอาเถอะ ข้ามีงานให้เจ้า เพื่อรับใช้ฮอร์ดและทำหน้าที่ของตนในงานระดมเสบียงสงครามอันคิราจ ข้าต้องการให้เจ้านำหนังหยาบกลับมาให้จำนวนหนึ่ง เจ้าจะทำให้ใช่ไหม?" },
        progress = { "196:851548643:1709068250", "เจ้าไม่น่าใช้เวลานานขนาดนี้เพื่อถลกหนังหยาบสิบชิ้นให้ข้า! บางทีควรลับมีดถลกหนังหน่อยไหม? หรือข้าอาจเข้าใจผิด และเจ้ามีมันอยู่ในกระเป๋าแล้ว?" },
        completion = { "284:1124438797:688227969", "ดีมาก ดูเหมือนเจ้าทำได้ค่อนข้างดี แม้หนังบางชิ้นจะมีขอบรุ่ยไปบ้าง ไม่เป็นไร งานเสร็จแล้ว เจ้าสมควรได้รับรางวัล หากได้หนังหยาบมาอีกกอง อย่าลืมนำมาให้ข้าโดยเร็ว" },
        required = { [8170] = { "14:1892667065:7828173", "หนังเหนียวทนทาน" } },
        steps = { { "14:1892667065:7828173", "หนังเหนียวทนทาน" } },
    },
    [8601] = { -- The Horde Needs More Rugged Leather!
        title = { "36:1885765171:278607095", "ฮอร์ดต้องการหนังหยาบเพิ่ม!" },
        objective = { "81:129660219:939539169", "นำ Rugged Leather 10 ชิ้นไปให้ Doctor Serratus ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "64:418879771:1428509867 C 242:2036717595:1402940056 N 1:46:46", "การเตรียมสงครามอันคิราจที่ใกล้เข้ามากำลังดำเนินต่อ {class} แต่เพื่อให้แน่ใจว่าเราไม่ล่าช้า หรืออย่างน้อยข้าไม่ใช่คนทำให้ช้า ข้าอยากให้เจ้านำหนังหยาบกลับมาอีกกอง ข้าจะขอบคุณอย่างยิ่งหากเจ้าใส่ใจจัดการเรื่องนี้โดยเร็ว {name}" },
        completion = { "105:831713880:437115680 N 343:810501723:1080038747", "ฝึกฝน ฝึกฝน และฝึกฝน มีดที่ลับคมอย่างดีและทักษะการใช้จะพาเจ้าไปได้ไกลในโลกนี้ {name} ดูเหมือนขอบหนังพวกนี้จะดีกว่าครั้งก่อน เจ้าซื้อมีดใหม่หรือ?\n\nอย่างไรเราก็ขอขอบคุณความพยายามของเจ้า เราบันทึกการบริจาคไว้แล้ว และข้ารับรองว่าจะใช้ให้เกิดประโยชน์ หากเจ้ามีหนังหยาบเพิ่ม อย่าลืมกลับมาคุยกับข้า เพราะข้าคงต้องการมันอีก" },
        required = { [8170] = { "14:1892667065:7828173", "หนังเหนียวทนทาน" } },
        objectiveLabels = {
            item = { ["Rugged Leather"] = "หนังเหนียวทนทาน" },
        },
    },
    [8604] = { -- The Horde Needs Wool Bandages!
        title = { "30:782238515:168598688", "ฮอร์ดต้องการผ้าพันแผลขนสัตว์!" },
        objective = { "82:485942938:589796162", "นำ Wool Bandages 20 ชิ้นไปให้ Healer Longrunner ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "11:927657569:725753248 C 452:1120559555:620353527", "สวัสดี {class} เพื่อเตรียมสงครามอันคิราจ ข้ามาประสานงานการรวบรวมผ้าพันแผลขนสัตว์ของฮอร์ดที่นี่ น่าเสียดายที่ในสนามรบ ทหารของเราไม่อาจหวังพึ่งว่าจะมีผู้รักษาอยู่ข้างกายเพื่อให้รอดชีวิต เชื่อข้าเถอะ ข้ารู้จากประสบการณ์ตรง เราจึงกำลังจัดชุดปฐมพยาบาลทั้งหมดนี้ให้พวกเขา\n\nหากเจ้ามีเวลา ข้าต้องการผ้าพันแผลขนสัตว์จำนวนมาก นำกลับมาให้ข้าที่นี่ แล้วข้าจะดูแลให้เจ้าได้รับรางวัลอย่างเหมาะสม" },
        progress = { "4:1110228981:147916455 C 54:504067286:322479069", "อา {class} เจ้ากลับมาเร็วขนาดนี้พร้อมผ้าพันแผลขนสัตว์แล้วหรือ?" },
        completion = { "20:1503247963:581696387 C 197:1115123980:1780321076", "เจ้ารับคำขอบคุณจากข้าและความซาบซึ้งจากฮอร์ดไปได้เลย {class} หากเจ้าพบผ้าพันแผลขนสัตว์เพิ่ม และอยากช่วยงานระดมเสบียงสงครามต่อ ก็นำมาให้ข้าที่นี่ จนกว่าจะถึงตอนนั้น ขอให้บรรพบุรุษเฝ้าคุ้มครองเจ้า!" },
        required = { [3530] = { "12:1002985017:881143359", "ผ้าพันแผลขนสัตว์" } },
        steps = { { "12:1002985017:881143359", "ผ้าพันแผลขนสัตว์" } },
    },
    [8605] = { -- The Horde Needs More Wool Bandages!
        title = { "35:1019504272:158366500", "ฮอร์ดต้องการผ้าพันแผลขนสัตว์เพิ่ม!" },
        objective = { "82:485942938:589796162", "นำ Wool Bandages 20 ชิ้นไปให้ Healer Longrunner ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "23:140679440:2097538806 C 387:1437455272:780841816", "ดีใจที่ได้พบเจ้าอีก {class} เรายังเตรียมงานระดมเสบียงสงครามกันอยู่ และข้ายังต้องการความช่วยเหลือทุกอย่างที่เจ้าให้ได้ในการรวบรวมผ้าพันแผลขนสัตว์ ความช่วยเหลือใด ๆ ล้วนมีค่าอย่างยิ่ง ข้าเพียงหวังว่าความพยายามของเราจะเพียงพอ ข้าสูญเสียดวงวิญญาณสูงส่งในสนามรบครั้งก่อน ๆ มากเกินไป จนไม่อาจละเว้นการทำทุกอย่างที่ทำได้เพื่อไม่ให้เกิดขึ้นอีก" },
        completion = { "21:1171303273:1869415295 C 2:11340:5796 N 245:1999803332:1255919419", "เจ้าเป็น{class}ผู้มีเกียรติ {name}! ข้าจะดูแลให้ผ้าพันแผลเหล่านี้ถึงมือผู้ใช้ เจ้ารับคำขอบคุณจากข้าและฮอร์ดไปได้เลย\n\nจงเดินทางโดยสงบ และกลับมาหาข้าอีกหากมีผ้าพันแผลขนสัตว์เหลือ เราต้องการความช่วยเหลือทุกอย่างที่หาได้ที่นี่" },
        required = { [3530] = { "12:1002985017:881143359", "ผ้าพันแผลขนสัตว์" } },
        objectiveLabels = {
            item = { ["Wool Bandage"] = "ผ้าพันแผลขนสัตว์" },
        },
    },
    [8607] = { -- The Horde Needs Mageweave Bandages!
        title = { "35:1968798894:227689441", "ฮอร์ดต้องการผ้าพันแผลเมจวีฟ!" },
        objective = { "81:2121333527:38662977", "นำ Mageweave Bandages 20 ชิ้นไปให้ Lady Callow ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "301:29473875:348777989 C 65:693709438:417115363", "ข้าเชื่อว่าเจ้ามาคุยเพราะจะช่วยรวบรวมของที่ข้าได้รับมอบหมายใช่ไหม? ดี! ไม่ว่าจะใช้วิธีใด และข้าหมายถึงวิธีใดก็ได้ ข้าต้องการให้เจ้ารวบรวมผ้าพันแผลเมจวีฟมามากพอสมควร ถ้าใหม่สะอาดก็ดี แต่ไม่จำเป็นเสมอไป นำกลับมาให้ข้าที่นี่ {class} แล้วข้าจะดูแลด้วยตนเองให้เจ้าได้รับรางวัลอย่างเหมาะสม" },
        progress = { "34:281611394:554362603 C 78:2127820216:846893963", "อย่าล้มเหลวให้ข้าขายหน้า {class}! กลับมาที่นี่ให้เร็วที่สุดพร้อมผ้าพันแผลเมจวีฟที่เราคุยกันไว้" },
        completion = { "71:835000937:1084118771 C 250:1975440498:879964132", "น่าประหลาดใจ แต่ก็ยอมรับได้ บางทีข้าอาจประเมิน'ความสามารถ'ของเจ้าต่ำไป {class} อาจจะนะ เจ้าทำงานง่าย ๆ สำเร็จ และจะได้รับรางวัลมากเกินงานที่ทำ แต่อย่าเหลิง หากอยากพิสูจน์ตนจริง ๆ ก็ควรออกไปนำผ้าพันแผลเมจวีฟกลับมาอีกมัด" },
        required = { [8544] = { "17:778846202:1018824039", "ผ้าพันแผล Mageweave" } },
        steps = { { "17:778846202:1018824039", "ผ้าพันแผล Mageweave" } },
    },
    [8608] = { -- The Horde Needs More Mageweave Bandages!
        title = { "40:341786640:1635979311", "ฮอร์ดต้องการผ้าพันแผลเมจวีฟเพิ่ม!" },
        objective = { "81:2121333527:38662977", "นำ Mageweave Bandages 20 ชิ้นไปให้ Lady Callow ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "226:1447123426:202508246 C 1:46:46", "เจ้ากลับมาหรือ? น่าสนใจ อย่างที่เห็น ข้ายังรวบรวมของเพื่องาน'ระดมเสบียงสงคราม'อันคิราจ หมายความว่าต้องให้เจ้าออกไปรวบรวมผ้าพันแผลเมจวีฟมาให้ข้าอีกกอง ข้าจะรอการกลับมาของเจ้า {class}" },
        completion = { "12:295197084:1784880872 C 357:1557889196:807943600", "น่าทึ่ง {class} เจ้าทำได้อีกครั้งจริง ๆ! ก็อย่างที่พวกเขาว่ากัน ข้ามีสายตาดีในการเลือกคนมารับใช้ เอาละ เราบันทึกการบริจาคของเจ้าไว้แล้ว และเจ้าจะได้รับประโยชน์ทางสังคมตามความพยายามนั้น แต่ข้าแนะนำว่า หากต้องการพิสูจน์คุณค่าของตนจริง ๆ ก็ควรออกไปรวบรวมผ้าพันแผลเมจวีฟมาอีกมัด" },
        required = { [8544] = { "17:778846202:1018824039", "ผ้าพันแผล Mageweave" } },
        objectiveLabels = {
            item = { ["Mageweave Bandage"] = "ผ้าพันแผล Mageweave" },
        },
    },
    [8609] = { -- The Horde Needs Runecloth Bandages!
        title = { "35:193218308:1715254650", "ฮอร์ดต้องการผ้าพันแผลรูนคลอธ!" },
        objective = { "89:1663819850:818019071", "นำ Runecloth Bandages 20 ชิ้นไปให้ Stoneguard Clayhoof ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "493:1880913063:1510856430 C 1:63:63", "ดูเหมือนหลีกเลี่ยงไม่ได้ที่ฮอร์ดกับอัลไลแอนซ์จะมุ่งเข้าสู่สงครามที่อันคิราจ น่าประหลาดใจที่ไม่ได้รบกันเอง แต่รบกับซิลิธิดและอำนาจใดก็ตามที่ควบคุมมัน ที่น่าประหลาดใจอีกอย่างคือทั้งสองฝ่ายต่างทำหน้าที่รวบรวมทรัพยากรที่จำเป็นต่อชัยชนะ\n\nข้ากำลังรวบรวมผ้าพันแผลรูนคลอธเพื่อแจกจ่ายให้ทหาร แต่คงไม่สำเร็จหากไม่มีความช่วยเหลือ หวังว่าจะเป็นจากเจ้า เจ้าช่วยข้าเรื่องนี้ได้ไหม {class}?" },
        progress = { "29:671751106:666316907 C 171:1359385690:1184891458", "ข้าคิดว่าสงครามใกล้มาแล้ว {class} ขอบคุณที่อุทิศเวลาและแรงช่วยงานรวบรวมของ เจ้ากลับมาเพราะได้ผ้าพันแผลรูนคลอธที่เราคุยกันไว้แล้วหรือ?" },
        completion = { "31:1582662716:2146582268 C 242:1151792168:122591834", "เจ้าทำให้ฮอร์ดภาคภูมิใจ {class} ขอบคุณสำหรับความพยายาม เราซาบซึ้งมาก! ข้าต้องเก็บผ้าพันแผลใหม่เหล่านี้ให้เรียบร้อย แล้วนับอีกครั้งว่าเข้าใกล้เป้าหมายเพียงใด หากเจ้าอยากทำ ก็รวบรวมผ้าพันแผลรูนคลอธเพิ่มแล้วนำกลับมาให้ข้าที่นี่ได้" },
        required = { [14529] = { "17:1741836445:919676731", "ผ้าพันแผลผ้ารูน" } },
        steps = { { "17:1741836445:919676731", "ผ้าพันแผลผ้ารูน" } },
    },
    [8610] = { -- The Horde Needs More Runecloth Bandages!
        title = { "40:713689701:976060891", "ฮอร์ดต้องการผ้าพันแผลรูนคลอธเพิ่ม!" },
        objective = { "89:1663819850:818019071", "นำ Runecloth Bandages 20 ชิ้นไปให้ Stoneguard Clayhoof ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "410:284224155:2073184448", "เวลาที่เราจะโถมเข้าสู่ไฟสงครามที่อันคิราจใกล้เข้ามาทุกที นักบวช แต่ก่อนอื่นต้องรวบรวมกำลังและเตรียมพร้อม เพื่อให้รอดจากการจู่โจมของแมลงกับนายของพวกมัน\n\nหากเจ้ามาที่นี่อีกครั้ง ก็คงอยากบริจาคผ้าพันแผลรูนคลอธเพื่องานระดมเสบียงสงครามอีกใช่ไหม? โปรดทำให้เร็วที่สุดเท่าที่ทำได้ แล้วกลับมาหาข้าอีกครั้ง", variants = { { "108:1386510411:1501984395 C 296:634890663:958727637", "เวลาที่เราจะโถมเข้าสู่ไฟสงครามที่อันคิราจใกล้เข้ามาทุกที {class} แต่ก่อนอื่นต้องรวบรวมกำลังและเตรียมพร้อม เพื่อให้รอดจากการจู่โจมของแมลงกับนายของพวกมัน\n\nหากเจ้ามาที่นี่อีกครั้ง ก็คงอยากบริจาคผ้าพันแผลรูนคลอธเพื่องานระดมเสบียงสงครามอีกใช่ไหม? โปรดทำให้เร็วที่สุดเท่าที่ทำได้ แล้วกลับมาหาข้าอีกครั้ง" } } },
        completion = { "54:1056778438:367267044 N 255:1138229068:1413156708", "สิ่งที่เจ้าทำเป็นการให้ที่เสียสละอย่างแท้จริง {name} และอาจช่วยชีวิตนักรบมากมายที่อันคิราจ ขอบคุณ และขอให้รู้ว่าฮอร์ดซาบซึ้งในการบริจาคของเจ้า หากเจ้าทำหรือพบผ้าพันแผลรูนคลอธเพิ่ม โปรดคิดถึงการนำมาให้ข้าที่นี่" },
        required = { [14529] = { "17:1741836445:919676731", "ผ้าพันแผลผ้ารูน" } },
        objectiveLabels = {
            item = { ["Runecloth Bandage"] = "ผ้าพันแผลผ้ารูน" },
        },
    },
    [8611] = { -- The Horde Needs Lean Wolf Steaks!
        title = { "33:854527691:1991991272", "ฮอร์ดต้องการสเต๊กหมาป่าเนื้อไม่ติดมัน!" },
        objective = { "85:52403252:627007560", "นำ Lean Wolf Steaks 20 ชิ้นไปให้ Bloodguard Rawtar ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "46:1034615973:625573442 C 417:1574110311:1449743364", "ข้าไม่ได้ยืนอยู่ตรงนี้เพียงเพื่ออาบแดดให้ผิวสวย {class} ยังมีงานเตรียมสงครามต้องทำ หากจะบดขยี้แมลงที่อันคิราจ เราต้องพร้อม และนั่นรวมถึงอาหารด้วย!\n\nพวกเขาให้ข้ารวบรวมและหมักเกลือสเต๊กหมาป่าเนื้อไม่ติดมันไว้สำหรับสงครามที่จะมา แต่เพราะข้าต้องอยู่จัดการทั้งหมดนี้ จึงต้องให้เจ้าออกไปฆ่าหมาป่า แล้วนำเนื้อไปปรุงเป็นสเต๊กหมาป่าเนื้อไม่ติดมัน ก่อนนำกลับมาให้ข้าที่นี่ เข้าใจครบแล้วใช่ไหม?" },
        progress = { "42:1809931939:578205146 C 102:143924482:1845737334", "กลับมาเร็วขนาดนี้พร้อมสเต๊กหมาป่าเนื้อไม่ติดมันแล้วหรือ {class}? ข้าไม่สนว่าจะสุกเกินไปหรือดิบ ขอแค่อร่อยและรีบเอามาให้ข้า!" },
        completion = { "184:730819137:405025974 C 47:716332019:988676388", "เอาละ กองเนื้อนี้ดูดีสำหรับข้า ข้าจะหมักเกลือแล้วเก็บไว้ หวังว่ามันจะสดพอให้กินได้เมื่อถึงเวลา\n\nขอบคุณที่ช่วยบริจาค {class} เจ้าคิดว่าจะนำมาให้อีกชุดได้ไหม?" },
        required = { [12209] = { "15:2048935322:1882552461", "สเต๊กหมาป่าไร้มัน" } },
        steps = { { "15:2048935322:1882552461", "สเต๊กหมาป่าไร้มัน" } },
    },
    [8612] = { -- The Horde Needs More Lean Wolf Steaks!
        title = { "38:896608030:799388383", "ฮอร์ดต้องการสเต๊กหมาป่าเนื้อไม่ติดมันเพิ่ม!" },
        objective = { "85:52403252:627007560", "นำ Lean Wolf Steaks 20 ชิ้นไปให้ Bloodguard Rawtar ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "16:1674991282:289885126 C 339:235196951:1236335157", "อย่างที่เห็น {class} เรายังต้องเก็บอาหารให้ทหารเพิ่ม ข้าไม่รู้ว่าเจ้าเคยผ่านสงครามหรือไม่ แต่พอพ้นความตกใจช่วงแรกของสนามรบไปแล้ว เจ้าจะหิวมากทีเดียว ครั้งก่อนเจ้าทำได้ดี ข้าจึงหวังว่ารอบนี้จะทำได้ดีพอกัน หรือเร็วขึ้นอีกหน่อย ในการนำสเต๊กหมาป่าเนื้อไม่ติดมันมาให้อีกกอง" },
        completion = { "58:1208415989:1875201807 N 250:839865073:302358524", "กลิ่นบอกว่าเจ้าหรือคนที่เจ้ารู้จักทำอาหารเก่งทีเดียว {name} สเต๊กหมาป่าเนื้อไม่ติดมันพวกนี้ทำข้าน้ำลายไหล ข้าว่าหายไปสักสองสามชิ้นคงไม่มีใครสังเกต เอาเถอะ ทำได้ดี ข้าจะให้ใครสักคนเก็บอย่างถูกวิธี จะได้ไม่เสียมากนัก\n\nถ้าได้มาอีก เจ้าก็รู้ว่าจะหาข้าได้ที่ไหน" },
        required = { [12209] = { "15:2048935322:1882552461", "สเต๊กหมาป่าไร้มัน" } },
        objectiveLabels = {
            item = { ["Lean Wolf Steak"] = "สเต๊กหมาป่าไร้มัน" },
        },
    },
    [8613] = { -- The Horde Needs Spotted Yellowtail!
        title = { "35:628888450:630141150", "ฮอร์ดต้องการสปอตเต็ดเยลโลว์เทล!" },
        objective = { "86:1006042453:1768679976", "นำ Spotted Yellowtail 20 ชิ้นไปให้ Fisherman Lin'do ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "378:45471132:977081511 C 1:63:63", "วันนี้เหมาะแก่การตกปลา ว่าไหมสหาย? ก็ดีแล้ว เพราะดูเหมือนข้าต้องการปลาเยอะมาก ฮอร์ดขอให้ข้ารับผิดชอบรวบรวมสปอตเต็ดเยลโลว์เทลเป็นตัน ๆ ให้พวกเขา บอกว่าต้องใช้ในสงครามอันคิราจที่กำลังเตรียมกัน ข้าบอกว่าจะทำให้ดีที่สุด จึงต้องหาแรงช่วย เจ้าจะช่วยข้าไหม {class}?" },
        progress = { "42:2073007340:738168813 C 113:1410093661:246137637", "กลับมาเร็วขนาดนี้พร้อมสปอตเต็ดเยลโลว์เทลแล้วหรือ {class}? จำได้ไหมว่าต้องปรุงให้น่ากิน? เราจะไม่เสิร์ฟปลาดิบให้ทหารกลางแดดร้อนของทะเลทรายแน่นอน" },
        completion = { "307:669683201:1333493763", "โอ้ ใช่ นี่ละของดี ข้าจะเก็บอย่างดีไม่ให้เสียเปล่า ขอบคุณที่ช่วยข้าอย่างนี้ ข้าว่าเจ้าเป็นนักตกปลาอันดับหนึ่งเลยที่นำสปอตเต็ดเยลโลว์เทลมาได้มากมาย ถ้าตกและปรุงมาได้อีก ก็นำมาให้ข้าที่นี่ ข้าจะบอกให้ทุกคนรู้ว่าเจ้าทำ!" },
        required = { [6887] = { "18:1236098111:1931550847", "ปลาหางเหลืองลายจุด" } },
        steps = { { "18:1236098111:1931550847", "ปลาหางเหลืองลายจุด" } },
    },
    [8614] = { -- The Horde Needs More Spotted Yellowtail!
        title = { "40:1149359843:2038431020", "ฮอร์ดต้องการสปอตเต็ดเยลโลว์เทลเพิ่ม!" },
        objective = { "86:1006042453:1768679976", "นำ Spotted Yellowtail 20 ชิ้นไปให้ Fisherman Lin'do ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "311:1531321758:740640016", "อย่างที่เห็น เรายังต้องการปลาอีกมาก ผู้ร่วมรบในสงครามอันคิราจที่ใกล้มาถึงต้องกินเยอะ ข้าจึงต้องหาสปอตเต็ดเยลโลว์เทลให้มากที่สุด เจ้าจับมา ปรุง แล้วนำกลับมาให้ข้าที่นี่ แล้วข้าจะขอบคุณ พร้อมคำขอบคุณจากฮอร์ดด้วย" },
        completion = { "28:1218790250:2105547900 N 156:1951867403:50790878", "นี่เป็นปลาชุดดีที่สุดแล้ว {name}! งานสุจริตที่ทำได้ดีจริง ๆ ไม่มีก้างด้วย! ขอบคุณสำหรับสปอตเต็ดเยลโลว์เทลชุดนี้ สหาย ถ้าปรุงมาเพิ่มก็กลับมาเร็ว ๆ นะ!" },
        required = { [6887] = { "18:1236098111:1931550847", "ปลาหางเหลืองลายจุด" } },
        objectiveLabels = {
            item = { ["Spotted Yellowtail"] = "ปลาหางเหลืองลายจุด" },
        },
    },
    [8616] = { -- The Horde Needs More Baked Salmon!
        title = { "34:1253776023:1808200559", "ฮอร์ดต้องการแซลมอนอบเพิ่ม!" },
        objective = { "79:644481857:1517800768", "นำ Baked Salmon 20 ชิ้นไปให้ Chief Sharpclaw ที่ Valley of Spirits ใน Orgrimmar" },
        progress = { "89:789163340:1213844462 C 202:1422962545:925406469", "แซลมอนอบชุดก่อนที่เจ้าบริจาคเพื่องานสงครามดูน่ากินมาก {class} ข้ายอมรับว่าอยากหยิบไว้เองสักสองสามชิ้น อย่างที่เห็น เรายังรวบรวมไม่ครบโควตา ข้าหวังว่าเจ้ากลับมาเพราะมีแซลมอนอบอีกกองติดตัวอยู่", variants = { { "89:789163340:1213844462 C 203:629154121:969164261", "แซลมอนอบชุดก่อนที่เจ้าบริจาคเพื่องานสงครามดูน่ากินมาก {class} ข้ายอมรับว่าอยากหยิบไว้เองสักสองสามชิ้น อย่างที่เห็น เรายังรวบรวมไม่ครบโควตา ข้าหวังว่าเจ้ากลับมาเพราะมีแซลมอนอบอีกกองติดตัวอยู่" } } },
        completion = { "74:1362998033:451799258 N 168:1517001225:1893083288", "เจ้าบริจาคทั้งเวลาและแรงกายเพื่องานสงครามเกินกว่าหน้าที่จริง ๆ {name} ข้ารับรองว่าแรงงานของเจ้าไม่ได้ถูกมองข้าม เจ้ารับคำขอบคุณจากข้าและความซาบซึ้งจากฮอร์ดไปได้เลย โปรดกลับมาหาข้าอีกหากอบมาได้อีกชุด" },
        required = { [13935] = { "12:697604345:1823457003", "ปลาแซลมอนอบ" } },
        objectiveLabels = {
            item = { ["Baked Salmon"] = "ปลาแซลมอนอบ" },
        },
    },
    [8792] = { -- The Horde Needs Your Help!
        title = { "26:1503773111:441145467", "ฮอร์ดต้องการความช่วยเหลือจากเจ้า!" },
        objective = { "60:2050953789:851989614", "พูดคุยกับ Warlord Gorchuk ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "339:472636693:2110117216 N 80:999823929:582528416 C 48:2003637816:726148589", "สวัสดี ข้าดีใจที่เจ้าตัดสินใจฟัง ฮอร์ดต้องการความช่วยเหลือทุกอย่างเพื่อเตรียมสงครามอันคิราจ นั่นหมายความว่าเราต้องการเจ้า! แม้ตอนที่เราคุยกัน ผู้รวบรวมอย่างเป็นทางการก็กำลังรวบรวมวัตถุดิบจำเป็นสำหรับสงครามที่จะมา แต่เราจะไม่ถึงเป้าหมายหากไม่มีเจ้าช่วย {name}!\n\nเจ้าควรไปคุยกับผู้รับผิดชอบ วอร์ลอร์ดกอร์ชุก ว่าอย่างไร {class}? จะช่วยงานเตรียมพร้อมอันสำคัญนี้ไหม?" },
        completion = { "10:1652484069:1189355142 C 54:750957729:120540077 N 365:1895979047:1473445031", "ธรอมคา {class}! ดีใจที่ชาวฮอร์ดมากมายเช่นเจ้า {name} ออกมาช่วยวางรากฐานสำหรับสงครามอันคิราจที่ใกล้มาถึง งานที่นี่จะทำให้เรามีชัยเหนือซิลิธิดและนายชั่วร้ายของพวกมันที่ซ่อนอยู่ภายในอันคิราจ\n\nเมื่อเจ้ามาถึงแล้ว อย่าลืมคุยกับผู้รวบรวมแต่ละคน และเสนอช่วยเก็บวัตถุดิบที่เจ้าเหมาะจะหา" },
    },
    [8793] = { -- The Horde Needs Your Help!
        title = { "26:1503773111:441145467", "ฮอร์ดต้องการความช่วยเหลือจากเจ้า!" },
        objective = { "60:2050953789:851989614", "พูดคุยกับ Warlord Gorchuk ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "339:472636693:2110117216 N 80:999823929:582528416 C 48:2003637816:726148589", "สวัสดี ข้าดีใจที่เจ้าตัดสินใจฟัง ฮอร์ดต้องการความช่วยเหลือทุกอย่างเพื่อเตรียมสงครามอันคิราจ นั่นหมายความว่าเราต้องการเจ้า! แม้ตอนที่เราคุยกัน ผู้รวบรวมอย่างเป็นทางการก็กำลังรวบรวมวัตถุดิบจำเป็นสำหรับสงครามที่จะมา แต่เราจะไม่ถึงเป้าหมายหากไม่มีเจ้าช่วย {name}!\n\nเจ้าควรไปคุยกับผู้รับผิดชอบ วอร์ลอร์ดกอร์ชุก ว่าอย่างไร {class}? จะช่วยงานเตรียมพร้อมอันสำคัญนี้ไหม?" },
        completion = { "10:1652484069:1189355142 C 54:750957729:120540077 N 365:1895979047:1473445031", "ธรอมคา {class}! ดีใจที่ชาวฮอร์ดมากมายเช่นเจ้า {name} ออกมาช่วยวางรากฐานสำหรับสงครามอันคิราจที่ใกล้มาถึง งานที่นี่จะทำให้เรามีชัยเหนือซิลิธิดและนายชั่วร้ายของพวกมันที่ซ่อนอยู่ภายในอันคิราจ\n\nเมื่อเจ้ามาถึงแล้ว อย่าลืมคุยกับผู้รวบรวมแต่ละคน และเสนอช่วยเก็บวัตถุดิบที่เจ้าเหมาะจะหา" },
    },
    [8794] = { -- The Horde Needs Your Help!
        title = { "26:1503773111:441145467", "ฮอร์ดต้องการความช่วยเหลือจากเจ้า!" },
        objective = { "60:2050953789:851989614", "พูดคุยกับ Warlord Gorchuk ที่ Valley of Spirits ใน Orgrimmar" },
        description = { "339:472636693:2110117216 N 80:999823929:582528416 C 48:2003637816:726148589", "สวัสดี ข้าดีใจที่เจ้าตัดสินใจฟัง ฮอร์ดต้องการความช่วยเหลือทุกอย่างเพื่อเตรียมสงครามอันคิราจ นั่นหมายความว่าเราต้องการเจ้า! แม้ตอนที่เราคุยกัน ผู้รวบรวมอย่างเป็นทางการก็กำลังรวบรวมวัตถุดิบจำเป็นสำหรับสงครามที่จะมา แต่เราจะไม่ถึงเป้าหมายหากไม่มีเจ้าช่วย {name}!\n\nเจ้าควรไปคุยกับผู้รับผิดชอบ วอร์ลอร์ดกอร์ชุก ว่าอย่างไร {class}? จะช่วยงานเตรียมพร้อมอันสำคัญนี้ไหม?" },
        completion = { "10:1652484069:1189355142 C 54:750957729:120540077 N 365:1895979047:1473445031", "ธรอมคา {class}! ดีใจที่ชาวฮอร์ดมากมายเช่นเจ้า {name} ออกมาช่วยวางรากฐานสำหรับสงครามอันคิราจที่ใกล้มาถึง งานที่นี่จะทำให้เรามีชัยเหนือซิลิธิดและนายชั่วร้ายของพวกมันที่ซ่อนอยู่ภายในอันคิราจ\n\nเมื่อเจ้ามาถึงแล้ว อย่าลืมคุยกับผู้รวบรวมแต่ละคน และเสนอช่วยเก็บวัตถุดิบที่เจ้าเหมาะจะหา" },
    },
    [8795] = { -- The Alliance Needs Your Help!
        title = { "29:549947698:403087759", "อัลไลแอนซ์ต้องการความช่วยเหลือจากเจ้า!" },
        objective = { "63:499067611:1373714453", "พูดคุยกับ Field Marshal Snowfall ที่ Military Ward ใน Ironforge" },
        description = { "342:1619897110:2038037048 N 87:922721024:99400810 C 48:2003637816:726148589", "สวัสดี ข้าดีใจที่เจ้าตัดสินใจฟัง อัลไลแอนซ์ต้องการความช่วยเหลือทุกอย่างเพื่อเตรียมสงครามอันคิราจ นั่นหมายความว่าเราต้องการเจ้า! แม้ตอนที่เราคุยกัน ผู้รวบรวมอย่างเป็นทางการก็กำลังรวบรวมวัตถุดิบจำเป็นสำหรับสงครามที่จะมา แต่เราจะไม่ถึงเป้าหมายหากไม่มีเจ้าช่วย {name}!\n\nเจ้าควรไปคุยกับผู้รับผิดชอบ จอมพลสโนว์ฟอลล์ ว่าอย่างไร {class}? จะช่วยงานเตรียมพร้อมอันสำคัญนี้ไหม?" },
        completion = { { "79:73265555:806453610 N 365:1895979047:1473445031", "79:1724261478:2016835877 N 365:1895979047:1473445031" }, "สวัสดี ยินดีที่ได้พบ สหาย! ดีใจที่ชาวอัลไลแอนซ์มากมายเช่นเจ้า {name} ออกมาช่วยวางรากฐานสำหรับสงครามอันคิราจที่ใกล้มาถึง งานที่นี่จะทำให้เรามีชัยเหนือซิลิธิดและนายชั่วร้ายของพวกมันที่ซ่อนอยู่ภายในอันคิราจ\n\nเมื่อเจ้ามาถึงแล้ว อย่าลืมคุยกับผู้รวบรวมแต่ละคน และเสนอช่วยเก็บวัตถุดิบที่เจ้าเหมาะจะหา" },
    },
    [8796] = { -- The Alliance Needs Your Help!
        title = { "29:549947698:403087759", "อัลไลแอนซ์ต้องการความช่วยเหลือจากเจ้า!" },
        objective = { "63:499067611:1373714453", "พูดคุยกับ Field Marshal Snowfall ที่ Military Ward ใน Ironforge" },
        description = { "342:1619897110:2038037048 N 87:922721024:99400810 C 48:2003637816:726148589", "สวัสดี ข้าดีใจที่เจ้าตัดสินใจฟัง อัลไลแอนซ์ต้องการความช่วยเหลือทุกอย่างเพื่อเตรียมสงครามอันคิราจ นั่นหมายความว่าเราต้องการเจ้า! แม้ตอนที่เราคุยกัน ผู้รวบรวมอย่างเป็นทางการก็กำลังรวบรวมวัตถุดิบจำเป็นสำหรับสงครามที่จะมา แต่เราจะไม่ถึงเป้าหมายหากไม่มีเจ้าช่วย {name}!\n\nเจ้าควรไปคุยกับผู้รับผิดชอบ จอมพลสโนว์ฟอลล์ ว่าอย่างไร {class}? จะช่วยงานเตรียมพร้อมอันสำคัญนี้ไหม?" },
        completion = { { "79:73265555:806453610 N 365:1895979047:1473445031", "79:1724261478:2016835877 N 365:1895979047:1473445031" }, "สวัสดี ยินดีที่ได้พบ สหาย! ดีใจที่ชาวอัลไลแอนซ์มากมายเช่นเจ้า {name} ออกมาช่วยวางรากฐานสำหรับสงครามอันคิราจที่ใกล้มาถึง งานที่นี่จะทำให้เรามีชัยเหนือซิลิธิดและนายชั่วร้ายของพวกมันที่ซ่อนอยู่ภายในอันคิราจ\n\nเมื่อเจ้ามาถึงแล้ว อย่าลืมคุยกับผู้รวบรวมแต่ละคน และเสนอช่วยเก็บวัตถุดิบที่เจ้าเหมาะจะหา" },
    },
    [8797] = { -- The Alliance Needs Your Help!
        title = { "29:549947698:403087759", "อัลไลแอนซ์ต้องการความช่วยเหลือจากเจ้า!" },
        objective = { "63:499067611:1373714453", "พูดคุยกับ Field Marshal Snowfall ที่ Military Ward ใน Ironforge" },
        description = { "342:1619897110:2038037048 N 87:922721024:99400810 C 48:2003637816:726148589", "สวัสดี ข้าดีใจที่เจ้าตัดสินใจฟัง อัลไลแอนซ์ต้องการความช่วยเหลือทุกอย่างเพื่อเตรียมสงครามอันคิราจ นั่นหมายความว่าเราต้องการเจ้า! แม้ตอนที่เราคุยกัน ผู้รวบรวมอย่างเป็นทางการก็กำลังรวบรวมวัตถุดิบจำเป็นสำหรับสงครามที่จะมา แต่เราจะไม่ถึงเป้าหมายหากไม่มีเจ้าช่วย {name}!\n\nเจ้าควรไปคุยกับผู้รับผิดชอบ จอมพลสโนว์ฟอลล์ ว่าอย่างไร {class}? จะช่วยงานเตรียมพร้อมอันสำคัญนี้ไหม?" },
        completion = { { "79:73265555:806453610 N 365:1895979047:1473445031", "79:1724261478:2016835877 N 365:1895979047:1473445031" }, "สวัสดี ยินดีที่ได้พบ สหาย! ดีใจที่ชาวอัลไลแอนซ์มากมายเช่นเจ้า {name} ออกมาช่วยวางรากฐานสำหรับสงครามอันคิราจที่ใกล้มาถึง งานที่นี่จะทำให้เรามีชัยเหนือซิลิธิดและนายชั่วร้ายของพวกมันที่ซ่อนอยู่ภายในอันคิราจ\n\nเมื่อเจ้ามาถึงแล้ว อย่าลืมคุยกับผู้รวบรวมแต่ละคน และเสนอช่วยเก็บวัตถุดิบที่เจ้าเหมาะจะหา", variants = { { "78:1352459418:1954818855 N 365:1895979047:1473445031", "สวัสดี ยินดีที่ได้พบ สหาย! ดีใจที่ชาวอัลไลแอนซ์มากมายเช่นเจ้า {name} ออกมาช่วยวางรากฐานสำหรับสงครามอันคิราจที่ใกล้มาถึง งานที่นี่จะทำให้เรามีชัยเหนือซิลิธิดและนายชั่วร้ายของพวกมันที่ซ่อนอยู่ภายในอันคิราจ\n\nเมื่อเจ้ามาถึงแล้ว อย่าลืมคุยกับผู้รวบรวมแต่ละคน และเสนอช่วยเก็บวัตถุดิบที่เจ้าเหมาะจะหา" } } },
    },
    [8846] = { -- Five Signets for War Supplies
        title = { "29:568053927:1973406071", "ตราห้าชิ้นแลกเสบียงสงคราม" },
        progress = { "475:993301904:347582751", "อ้อ มาเอาเสบียงเพิ่มให้ตนเองหรือ? ข้าเข้าใจความต้องการยุทโธปกรณ์เพิ่มเติมดี... ถ้าอยากได้หลักฐานก็ลองมองรอบตัวสิ\n\nข้าจะเบิกเสบียงเพิ่มให้ แต่เจ้าต้องนำตรายกย่องจำนวนที่เหมาะสมมาแลก การมอบตราในลักษณะนี้จะไม่ได้รับการยกย่อง แต่เจ้าอาจพบของมีประโยชน์ที่ช่วยให้รอดชีวิตเมื่อการต่อสู้มาถึงในที่สุด" },
        completion = { "49:1194553521:129811062 C 150:882375429:1706774845 N 140:1401927953:300802020", "เอาละ ตกลงตามนั้น นี่เสบียงของเจ้า {class} หากต้องการแลกอีก ข้าก็พร้อมอนุมัติ เพียงบอกมาแล้วข้าจะจัดการให้\n\nทำงานให้ดีต่อไป {name} เราต้องการยุทโธปกรณ์ทุกอย่างที่รวบรวมได้หากจะชนะเรื่องนี้ ถ้าทุกคนทำหน้าที่ของตน ชัยชนะก็จะเป็นของเรา!" },
        description = { "475:993301904:347582751", "อ้อ มาเอาเสบียงเพิ่มให้ตนเองหรือ? ข้าเข้าใจความต้องการยุทโธปกรณ์เพิ่มเติมดี... ถ้าอยากได้หลักฐานก็ลองมองรอบตัวสิ\n\nข้าจะเบิกเสบียงเพิ่มให้ แต่เจ้าต้องนำตรายกย่องจำนวนที่เหมาะสมมาแลก การมอบตราในลักษณะนี้จะไม่ได้รับการยกย่อง แต่เจ้าอาจพบของมีประโยชน์ที่ช่วยให้รอดชีวิตเมื่อการต่อสู้มาถึงในที่สุด" },
        required = { [21436] = { "28:763609816:1802454029", "ตราเชิดชูเกียรติฝ่ายพันธมิตร" } },
        objectiveLabels = {
            item = { ["Alliance Commendation Signet"] = "ตราเชิดชูเกียรติฝ่ายพันธมิตร" },
        },
    },
