        required = { [21438] = { "25:1809053717:555421203", "ตราเชิดชูเกียรติฝ่ายฮอร์ด" } },
        objectiveLabels = {
            item = { ["Horde Commendation Signet"] = "ตราเชิดชูเกียรติฝ่ายฮอร์ด" },
        },
    },
