    [5893] = { -- Coldtooth Supplies
        title = { "18:377566642:521682516", "เสบียงโคลด์ทูธ" },
        objective = { "72:1476933006:725682550", "นำ Coldtooth Supplies 10 ชิ้นไปให้ Horde Quatermaster ใน Frostwolf Keep" },
        description = { "340:164811246:866265764 N 140:2082506869:953903698", "เหมืองโคลด์ทูธทางเหนือเคยเหมาะสำหรับเก็บเสบียงส่วนเกิน แต่ตอนนี้การรบกับสตอร์มไพก์ดุเดือดขึ้น เราจึงไม่มีกำลังเหลือประจำการและป้องกันเหมืองเสมอไป การควบคุมเหมืองจึงมักตกไปอยู่กับอัลไลแอนซ์ หรือพวกที่อาศัยอยู่ใต้ดิน...\n\nแต่เรายังต้องการเสบียง {name}! ไปเหมืองโคลด์ทูธแล้วนำเสบียงกลับมาให้ข้า ระวังศัตรูระหว่างทางด้วย กระแสการรบที่นั่นเปลี่ยนรวดเร็ว..." },
        progress = { "37:1399088248:404135592 N 39:807874089:1909621391", "เจ้าไปเหมืองโคลด์ทูธมาแล้วหรือ {name}? มีเสบียงที่ข้าขอมาหรือไม่?" },
        completion = { "29:998583521:1081075095 N 131:1125165936:771301399 N 65:1489580870:1306271025", "อา เจ้าได้มาแล้ว ทำได้ดี {name}! เสบียงพวกนี้อับชื้นนิดหน่อยเพราะอยู่ในเหมืองมืดมานาน แต่เราจะใช้ประโยชน์จากมันอยู่ดี\n\nขอบคุณ {name} สิ่งที่เจ้าทำสำคัญต่อการรักษากำลังรบของเรา" },
        required = { [17542] = { "18:377566642:521682516", "เสบียงโคลด์ทูธ" } },
        objectiveLabels = {
            item = { ["Coldtooth Supplies"] = "เสบียงโคลด์ทูธ" },
        },
    },
