    [6801] = { -- Lokholar the Ice Lord
        title = { "21:1046798098:335347529", "โลคโฮลาร์ จ้าวน้ำแข็ง" },
        progress = { "27:1659730320:2010641149 R 338:1234991040:342281373", "ข้ามาจากธันเดอร์บลัฟฟ์ {race} แคร์นดูแลด้วยตนเองให้ข้ามาช่วยเผ่าฟรอสต์วูล์ฟในยามคับขันนี้\n\nแต่อย่าเสียเวลาอีกเลย เจ้าต้องโค่นศัตรูของเราและนำเลือดมาให้ข้า เมื่อรวบรวมเลือดได้พอ พิธีอัญเชิญจึงจะเริ่มได้\n\nชัยชนะจะเป็นของเราเมื่อจ้าวธาตุถูกปล่อยเข้าใส่กองทัพสตอร์มไพก์" },
        completion = { "214:705518469:1266480827", "เลือดของศัตรูหลั่งไหลแล้ว ข้าจะผสมเลือดนี้เข้ากับส่วนที่รวบรวมไว้ เมื่อเครื่องบูชาครบถ้วน จ้าวน้ำแข็งจะแสดงความพิโรธทั้งหมดของเผ่าฟรอสต์วูล์ฟให้เจ้าพวกสุนัขสตอร์มไพก์เห็น!" },
        description = { "27:1659730320:2010641149 R 338:1234991040:342281373", "ข้ามาจากธันเดอร์บลัฟฟ์ {race} แคร์นดูแลด้วยตนเองให้ข้ามาช่วยเผ่าฟรอสต์วูล์ฟในยามคับขันนี้\n\nแต่อย่าเสียเวลาอีกเลย เจ้าต้องโค่นศัตรูของเราและนำเลือดมาให้ข้า เมื่อรวบรวมเลือดได้พอ พิธีอัญเชิญจึงจะเริ่มได้\n\nชัยชนะจะเป็นของเราเมื่อจ้าวธาตุถูกปล่อยเข้าใส่กองทัพสตอร์มไพก์" },
        required = { [17306] = { "25:1075847306:1748124349", "เลือดทหารสตอร์มไพก์" } },
        objectiveLabels = {
            item = { ["Stormpike Soldier's Blood"] = "เลือดทหารสตอร์มไพก์" },
        },
    },
    [6825] = { -- Call of Air - Guse's Fleet
        title = { "26:444374547:2086635766", "เรียกกำลังทางอากาศ — ฝูงบินของกูส" },
        progress = { "45:1623087448:1092337542 R 255:913382243:742848873", "เราต้องเตรียมหน่วยขี่รบฝูงใหม่ {race}! นักขี่ของข้าพร้อมโจมตีใจกลางสนามรบ แต่ก่อนอื่นต้องกระตุ้นความหิวของพวกมัน เพื่อเตรียมพร้อมบุก\n\nข้าต้องการเนื้อทหารสตอร์มไพก์มากพอเลี้ยงทั้งฝูง! หลายร้อยปอนด์! เจ้าย่อมจัดการได้ใช่ไหม? ไปได้แล้ว!" },
        completion = { "74:1996070320:1914309209", "ฝูงบินกินเนื้อพวกมันเป็นอาหาร กลืนกินศัตรู\n\nใกล้ได้บินแล้ว!" },
        description = { "45:1623087448:1092337542 R 255:913382243:742848873", "เราต้องเตรียมหน่วยขี่รบฝูงใหม่ {race}! นักขี่ของข้าพร้อมโจมตีใจกลางสนามรบ แต่ก่อนอื่นต้องกระตุ้นความหิวของพวกมัน เพื่อเตรียมพร้อมบุก\n\nข้าต้องการเนื้อทหารสตอร์มไพก์มากพอเลี้ยงทั้งฝูง! หลายร้อยปอนด์! เจ้าย่อมจัดการได้ใช่ไหม? ไปได้แล้ว!" },
        required = { [17326] = { "25:1345200276:778469322", "เนื้อทหารสตอร์มไพก์" } },
        objectiveLabels = {
            item = { ["Stormpike Soldier's Flesh"] = "เนื้อทหารสตอร์มไพก์" },
        },
    },
    [6826] = { -- Call of Air - Jeztor's Fleet
        title = { "28:1076739936:616806044", "เรียกกำลังทางอากาศ — ฝูงบินของเจซทอร์" },
        progress = { "20:744749058:404294006 N 352:2094718931:1222052252", "เจ้าทำงานหนักแล้ว {name} แต่เราเพิ่งเริ่มเท่านั้น!\n\nหน่วยขี่รบของข้าต้องลิ้มรสเนื้อของเป้าหมาย วิธีนี้จะทำให้โจมตีศัตรูได้อย่างแม่นยำ!\n\nฝูงบินของข้าทรงพลังเป็นอันดับสองในกองบัญชาการทางอากาศ จึงต้องโจมตีคู่ต่อสู้ที่แข็งแกร่งกว่า ด้วยเหตุนี้ พวกมันจึงต้องการเนื้อของนายทหารสตอร์มไพก์\n\nรีบเข้า ทหาร!" },
        completion = { "53:180218143:1946709339", "อีก! เอามาอีก! นำมาเพิ่ม พวกมันใกล้พร้อมแล้ว!" },
        description = { "20:744749058:404294006 N 352:2094718931:1222052252", "เจ้าทำงานหนักแล้ว {name} แต่เราเพิ่งเริ่มเท่านั้น!\n\nหน่วยขี่รบของข้าต้องลิ้มรสเนื้อของเป้าหมาย วิธีนี้จะทำให้โจมตีศัตรูได้อย่างแม่นยำ!\n\nฝูงบินของข้าทรงพลังเป็นอันดับสองในกองบัญชาการทางอากาศ จึงต้องโจมตีคู่ต่อสู้ที่แข็งแกร่งกว่า ด้วยเหตุนี้ พวกมันจึงต้องการเนื้อของนายทหารสตอร์มไพก์\n\nรีบเข้า ทหาร!" },
        required = { [17327] = { "28:323969112:1169118086", "เนื้อนายร้อยสตอร์มไพก์" } },
        objectiveLabels = {
            item = { ["Stormpike Lieutenant's Flesh"] = "เนื้อนายร้อยสตอร์มไพก์" },
        },
    },
    [6827] = { -- Call of Air - Mulverick's Fleet
        title = { "31:10567408:1200166772", "เรียกกำลังทางอากาศ — ฝูงบินของมัลเวอริก" },
        progress = { "367:1210503135:1924723330", "ข้าถูกขังในรูนรกของคนแคระอยู่หลายวัน เชื่อได้เลยว่าข้าอยากแก้แค้น!\n\nเราต้องวางแผนให้รอบคอบ\n\nก่อนอื่น หน่วยขี่รบของข้าต้องมีเป้าหมายให้ไล่ล่า เป้าหมายสำคัญ ข้าต้องป้อนเนื้อผู้บัญชาการสตอร์มไพก์ให้พวกมัน น่าเสียดายที่เจ้าพวกตัวเล็กนั่นตั้งมั่นอยู่ลึกหลังแนวศัตรู! เจ้ามีงานหนักรออยู่แน่" },
        completion = { "73:2071273253:1169399720 N 49:1524676007:606917810", "ยังไม่พอ! ข้าคงคาดหวังงานระดับนี้จากผู้เริ่มต้น แต่กับเจ้า {name} หรือ? เอาหน่อย ทหาร! เร่งมือ! ต้องการเนื้อเพิ่ม!" },
        description = { "367:1210503135:1924723330", "ข้าถูกขังในรูนรกของคนแคระอยู่หลายวัน เชื่อได้เลยว่าข้าอยากแก้แค้น!\n\nเราต้องวางแผนให้รอบคอบ\n\nก่อนอื่น หน่วยขี่รบของข้าต้องมีเป้าหมายให้ไล่ล่า เป้าหมายสำคัญ ข้าต้องป้อนเนื้อผู้บัญชาการสตอร์มไพก์ให้พวกมัน น่าเสียดายที่เจ้าพวกตัวเล็กนั่นตั้งมั่นอยู่ลึกหลังแนวศัตรู! เจ้ามีงานหนักรออยู่แน่" },
        required = { [17328] = { "27:1049825618:90043885", "เนื้อผู้บัญชาการสตอร์มไพก์" } },
        objectiveLabels = {
            item = { ["Stormpike Commander's Flesh"] = "เนื้อผู้บัญชาการสตอร์มไพก์" },
        },
    },
    [6846] = { -- Begin the Attack!
        title = { "17:1350593974:1922836572", "เริ่มการโจมตี!" },
        progress = { "119:1310226456:1920421203", "ทหารของข้ามีเสบียงและพร้อมบุกแล้ว เราขาดเพียงคำสั่งจากโนเรก สตอร์มไพก์ แล้วข้าจะส่งพวกเขาเข้ารบ!" },
        completion = { "73:1372230628:828474205", "อา คำสั่ง! ระบุให้ข้าโจมตีได้ตามเห็นควร และข้าเห็นควรว่า... เดี๋ยวนี้!" },
        description = { "119:787867001:1752897165", "ทหารของข้ามีเสบียงและพร้อมบุกแล้ว เราขาดเพียงคำสั่งจากโนเรก สตอร์มไพก์ แล้วข้าจะส่งพวกเขาเข้ารบ!" },
        required = { [17353] = { "24:1912390415:1879210187", "คำสั่งโจมตีของสตอร์มไพก์" } },
        objectiveLabels = {
            item = { ["Stormpike Assault Orders"] = "คำสั่งโจมตีของสตอร์มไพก์" },
        },
    },
    [6847] = { -- Master Ryson's All Seeing Eye
        title = { "29:1662089892:284599139", "ดวงตาเห็นทุกสิ่งของมาสเตอร์ไรสัน" },
        objective = { "183:1649811703:1128703924", "นำ Master Ryson's All Seeing Eye กลับคืนมาจากถ้ำ Winterax แล้วส่งคืน Master Ryson\n\nคำเตือน:ว่ากันว่า Master Ryson's All Seeing Eye มีคำสาปอันน่ากลัวติดอยู่!" },
        description = { "65:262468792:405332578 C 427:745032443:1677863947", "สงครามของพวกเจ้าใจกลางอัลเทอแรคไม่มีความหมายต่อซินดิเคต {class} เราจะทำอย่างที่เคยทำ รอจนผู้ชนะที่ชัดเจนลุกขึ้นจากเถ้าถ่านและซากปรักหักพังของความบ้าคลั่งนี้ แล้วจึงโจมตี\n\nแต่ตอนนี้เราไม่ได้มาที่นี่เพราะเรื่องนั้น ดวงตาเห็นทุกสิ่งหายไป ถูกโทรลล์วินเทอร์แอกซ์ในแถบนี้เอาไป\n\nนำดวงตากลับมา แล้วบริการของเราจะเป็นของเจ้า ตราบเท่าที่ฝ่ายเจ้ายังเหลือเวลา\n\nกลับมาหาข้าเมื่อได้ดวงตา เพื่อให้ข้าตรวจเจ้า\n\n<มาสเตอร์ไรสันยิ้มกว้าง>" },
    },
    [6848] = { -- Master Ryson's All Seeing Eye
        title = { "29:1662089892:284599139", "ดวงตาเห็นทุกสิ่งของมาสเตอร์ไรสัน" },
        objective = { "183:1649811703:1128703924", "นำ Master Ryson's All Seeing Eye กลับคืนมาจากถ้ำ Winterax แล้วส่งคืน Master Ryson\n\nคำเตือน:ว่ากันว่า Master Ryson's All Seeing Eye มีคำสาปอันน่ากลัวติดอยู่!" },
        description = { "65:262468792:405332578 C 427:745032443:1677863947", "สงครามของพวกเจ้าใจกลางอัลเทอแรคไม่มีความหมายต่อซินดิเคต {class} เราจะทำอย่างที่เคยทำ รอจนผู้ชนะที่ชัดเจนลุกขึ้นจากเถ้าถ่านและซากปรักหักพังของความบ้าคลั่งนี้ แล้วจึงโจมตี\n\nแต่ตอนนี้เราไม่ได้มาที่นี่เพราะเรื่องนั้น ดวงตาเห็นทุกสิ่งหายไป ถูกโทรลล์วินเทอร์แอกซ์ในแถบนี้เอาไป\n\nนำดวงตากลับมา แล้วบริการของเราจะเป็นของเจ้า ตราบเท่าที่ฝ่ายเจ้ายังเหลือเวลา\n\nกลับมาหาข้าเมื่อได้ดวงตา เพื่อให้ข้าตรวจเจ้า\n\n<มาสเตอร์ไรสันยิ้มกว้าง>" },
    },
    [6861] = { -- Zinfizzlex's Portable Shredder Unit
        title = { "35:1863596423:790266148", "ชุดเครื่องตัดไม้พกพาของซินฟิซเล็กซ์" },
        description = { "64:208290372:408130124 R 352:1584248290:1995169485", "ข้าก็อยากลองเครื่องตัดไม้พกพาของตัวเองไม่แพ้เจ้า {race} แต่ก่อนทำชุดเครื่องมือได้ ข้าต้องใช้วัตถุดิบมากมาย!\n\nพูดให้ชัด ข้าต้องการทอเรียม มิธริล และเหล็กเป็นภูเขา อีกทั้งต้องใช้เลื่อยไอน้ำหนึ่งชิ้นต่อเครื่อง เจ้าต้องไปหาเลื่อยที่โรงเลื่อย\n\nตอนที่ข้าสอดส่องแถวนี้ก่อนถูกจับ ข้าเห็นเลื่อยไอน้ำกองหนึ่งที่ค่ายตัดไม้สตอร์มไพก์" },
        progress = { "64:208290372:408130124 R 417:1155329060:1442018537", "ข้าก็อยากลองเครื่องตัดไม้พกพาของตัวเองไม่แพ้เจ้า {race} แต่ก่อนทำชุดเครื่องมือได้ ข้าต้องใช้วัตถุดิบมากมาย!\n\nพูดให้ชัด ข้าต้องการทอเรียม มิธริล และเหล็กเป็นภูเขา อีกทั้งต้องใช้เลื่อยไอน้ำหนึ่งชิ้นต่อเครื่อง เจ้าต้องไปหาเลื่อยที่โรงเลื่อย\n\nตอนที่ข้าสอดส่องแถวนี้ก่อนถูกจับ ข้าเห็นเลื่อยไอน้ำกองหนึ่งที่ค่ายตัดไม้สตอร์มไพก์\n\nMaster Engineer Zinfizzlex ต้องการให้เจ้านำสิ่งต่อไปนี้มาให้:" },
        objective = { "128:2116732760:1242471016", "หัวหน้าวิศวกร Zinfizzlex ต้องการให้เจ้านำสิ่งต่อไปนี้มาให้:\n*Thorium Bar 30 แท่ง\n*Mithril Bar 50 แท่ง\n*Iron Bar 75 แท่ง\n*Steamsaw 1 อัน" },
    },
    [6862] = { -- Zinfizzlex's Portable Shredder Unit
        title = { "35:1863596423:790266148", "ชุดเครื่องตัดไม้พกพาของซินฟิซเล็กซ์" },
        description = { "64:208290372:408130124 R 352:2126617691:362689427", "ข้าก็อยากลองเครื่องตัดไม้พกพาของตัวเองไม่แพ้เจ้า {race} แต่ก่อนทำชุดเครื่องมือได้ ข้าต้องใช้วัตถุดิบมากมาย!\n\nพูดให้ชัด ข้าต้องการทอเรียม มิธริล และเหล็กเป็นภูเขา อีกทั้งต้องใช้เลื่อยไอน้ำหนึ่งชิ้นต่อเครื่อง เจ้าต้องไปหาเลื่อยที่โรงเลื่อย\n\nตอนที่ข้าสอดส่องแถวนี้ก่อนถูกจับ ข้าเห็นเลื่อยไอน้ำกองหนึ่งที่ค่ายตัดไม้ฟรอสต์วูล์ฟ" },
        progress = { "64:208290372:408130124 R 417:1155329060:1442018537", "ข้าก็อยากลองเครื่องตัดไม้พกพาของตัวเองไม่แพ้เจ้า {race} แต่ก่อนทำชุดเครื่องมือได้ ข้าต้องใช้วัตถุดิบมากมาย!\n\nพูดให้ชัด ข้าต้องการทอเรียม มิธริล และเหล็กเป็นภูเขา อีกทั้งต้องใช้เลื่อยไอน้ำหนึ่งชิ้นต่อเครื่อง เจ้าต้องไปหาเลื่อยที่โรงเลื่อย\n\nตอนที่ข้าสอดส่องแถวนี้ก่อนถูกจับ ข้าเห็นเลื่อยไอน้ำกองหนึ่งที่ค่ายตัดไม้สตอร์มไพก์\n\nMaster Engineer Zinfizzlex ต้องการให้เจ้านำสิ่งต่อไปนี้มาให้:" },
        objective = { "128:2116732760:1242471016", "หัวหน้าวิศวกร Zinfizzlex ต้องการให้เจ้านำสิ่งต่อไปนี้มาให้:\n*Thorium Bar 30 แท่ง\n*Mithril Bar 50 แท่ง\n*Iron Bar 75 แท่ง\n*Steamsaw 1 อัน" },
    },
    [6881] = { -- Ivus the Forest Lord
        title = { "20:842836546:315670373", "ไอวัส จ้าวพงไพร" },
        progress = { "381:1923575833:1193640345 N 1:33:33", "เผ่าฟรอสต์วูล์ฟได้รับการปกป้องด้วยพลังธาตุอันแปดเปื้อน ชาแมนของพวกมันข้องแวะกับพลังที่หากปล่อยไว้ จะทำลายพวกเราทั้งหมดแน่\n\nความเสียหายรุนแรงเกินกว่าสภาจะควบคุมได้แล้ว! ต้องอัญเชิญไอวัสมาช่วยเรา\n\nทหารฟรอสต์วูล์ฟพกเครื่องรางธาตุที่เรียกว่าคริสตัลพายุ เราใช้เครื่องรางเหล่านั้นอัญเชิญไอวัสได้ ออกไปชิงคริสตัลมา {name}!" },
        completion = { "11:534428891:784080240 N 210:959379023:1473886860", "ทำได้ดี {name} ข้าจะใช้พลังเครื่องรางนี้เสริมเวทมนตร์ที่รวบรวมไว้แล้ว เมื่อสะสมพลังได้พอ ข้าจะรวมพลังงานทั้งหมดและเรียกจ้าวพงไพรมาช่วยภารกิจของเรา" },
        description = { "381:1923575833:1193640345 N 1:33:33", "เผ่าฟรอสต์วูล์ฟได้รับการปกป้องด้วยพลังธาตุอันแปดเปื้อน ชาแมนของพวกมันข้องแวะกับพลังที่หากปล่อยไว้ จะทำลายพวกเราทั้งหมดแน่\n\nความเสียหายรุนแรงเกินกว่าสภาจะควบคุมได้แล้ว! ต้องอัญเชิญไอวัสมาช่วยเรา\n\nทหารฟรอสต์วูล์ฟพกเครื่องรางธาตุที่เรียกว่าคริสตัลพายุ เราใช้เครื่องรางเหล่านั้นอัญเชิญไอวัสได้ ออกไปชิงคริสตัลมา {name}!" },
        required = { [17423] = { "13:1802824770:857773564", "ผลึกพายุ" } },
        objectiveLabels = {
            item = { ["Storm Crystal"] = "ผลึกพายุ" },
        },
    },
    [6901] = { -- Launch the Attack!
        title = { "18:60039966:635680241", "ปล่อยกำลังโจมตี!" },
        progress = { "127:822791113:37482203", "ทหารของข้ามีเสบียงและพร้อมบุกแล้ว เราขาดเพียงคำสั่งจากฝ่ายเสบียงฟรอสต์วูล์ฟ แล้วข้าจะส่งพวกเขาเข้ารบ!" },
        completion = { "86:2058892053:623015198", "ถึงเวลาเสียที! ทีนี้เราจะแสดงให้อัลไลแอนซ์เห็นความโง่เขลาที่เข้ามาในหุบเขาอัลเทอแรค!" },
        description = { "69:276672242:738730969", "นักรบของข้ากระหายจะบุกแล้ว! ข้าขาดแค่คำสั่งให้เข้าโจมตี..." },
    },
    [6941] = { -- Call of Air - Vipore's Fleet
        title = { "28:608918594:1483600958", "เรียกกำลังทางอากาศ — ฝูงบินของไวพอร์" },
        progress = { "287:61585372:56009612", "ต้องจัดการหน่วยฟรอสต์วูล์ฟชั้นยอดที่คุมแนวอยู่ ทหาร! ข้ามอบหมายให้เจ้าลดจำนวนฝูงคนเถื่อนพวกนั้น นำเหรียญของนายทหารกับลีเจียนแนร์กลับมาให้ข้า เมื่อข้าเห็นว่าจัดการเจ้าพวกสวะไปมากพอแล้ว ข้าจะส่งการโจมตีทางอากาศ" },
        completion = { "53:655393715:547195778", "ฝูงบินจะพร้อมในไม่ช้า จงพยายามต่อไป!" },
        description = { "287:61585372:56009612", "ต้องจัดการหน่วยฟรอสต์วูล์ฟชั้นยอดที่คุมแนวอยู่ ทหาร! ข้ามอบหมายให้เจ้าลดจำนวนฝูงคนเถื่อนพวกนั้น นำเหรียญของนายทหารกับลีเจียนแนร์กลับมาให้ข้า เมื่อข้าเห็นว่าจัดการเจ้าพวกสวะไปมากพอแล้ว ข้าจะส่งการโจมตีทางอากาศ" },
        required = { [17503] = { "28:1071327673:801511594", "เหรียญนายร้อยฟรอสต์วูล์ฟ" } },
        objectiveLabels = {
            item = { ["Frostwolf Lieutenant's Medal"] = "เหรียญนายร้อยฟรอสต์วูล์ฟ" },
        },
    },
    [6942] = { -- Call of Air - Slidore's Fleet
        title = { "29:597025266:610844356", "เรียกกำลังทางอากาศ — ฝูงบินของสไลดอร์" },
        progress = { "385:461267222:1970723017", "กริฟฟินของข้าพร้อมโจมตีแนวหน้า แต่ยังบุกไม่ได้จนกว่าจะลดกำลังที่แนวนั้นลง\n\nนักรบฟรอสต์วูล์ฟที่รักษาแนวหน้าสวมเหรียญรับใช้อย่างภาคภูมิบนอก กระชากเหรียญเหล่านั้นจากศพเน่า ๆ ของพวกมัน แล้วนำกลับมาที่นี่\n\nเมื่อลดกำลังแนวหน้าได้พอ ข้าจะเรียกกำลังทางอากาศ ความตายจากเบื้องบน!" },
        completion = { "86:396956598:853149757", "นำมาเรื่อย ๆ ทหาร! กริฟฟินแห่งแอรีจะพร้อมโจมตีในไม่ช้า!" },
        description = { "385:461267222:1970723017", "กริฟฟินของข้าพร้อมโจมตีแนวหน้า แต่ยังบุกไม่ได้จนกว่าจะลดกำลังที่แนวนั้นลง\n\nนักรบฟรอสต์วูล์ฟที่รักษาแนวหน้าสวมเหรียญรับใช้อย่างภาคภูมิบนอก กระชากเหรียญเหล่านั้นจากศพเน่า ๆ ของพวกมัน แล้วนำกลับมาที่นี่\n\nเมื่อลดกำลังแนวหน้าได้พอ ข้าจะเรียกกำลังทางอากาศ ความตายจากเบื้องบน!" },
        required = { [17502] = { "25:771084179:573275550", "เหรียญทหารฟรอสต์วูล์ฟ" } },
        objectiveLabels = {
            item = { ["Frostwolf Soldier's Medal"] = "เหรียญทหารฟรอสต์วูล์ฟ" },
        },
    },
    [6943] = { -- Call of Air - Ichman's Fleet
        title = { "28:992521411:1181682856", "เรียกกำลังทางอากาศ — ฝูงบินของอิคแมน" },
        progress = { "449:1208340572:1596433359", "ขวัญของพวกมันตกต่ำ ทหาร หลังการโจมตีทางอากาศใส่ฮอร์ดครั้งล่าสุดล้มเหลว พวกมันก็ไม่ยอมบิน! เจ้าต้องช่วยปลุกขวัญกำลังใจ\n\nกลับไปสนามรบแล้วโจมตีใจกลางกองบัญชาการฟรอสต์วูล์ฟ โค่นผู้บัญชาการและผู้พิทักษ์ของพวกมัน นำเหรียญกลับมาให้มากที่สุดเท่าที่จะยัดใส่กระเป๋าได้! ข้าสัญญาว่าเมื่อกริฟฟินของข้าเห็นของที่ได้มาและได้กลิ่นเลือดศัตรู พวกมันจะบินอีกครั้ง! ไปได้แล้ว!" },
        completion = { "167:1146404436:1963845221", "เจ้าเห็นไหม? ดูพวกมันสิ ทหาร! เริ่มกลับมาฮึกเหิมแล้ว... อีกไม่นานฝูงบินอิคแมนจะโจมตีใจกลางหุบเขาอีกครั้ง! สตอร์มไพก์จะครองท้องฟ้า!" },
        description = { "449:1208340572:1596433359", "ขวัญของพวกมันตกต่ำ ทหาร หลังการโจมตีทางอากาศใส่ฮอร์ดครั้งล่าสุดล้มเหลว พวกมันก็ไม่ยอมบิน! เจ้าต้องช่วยปลุกขวัญกำลังใจ\n\nกลับไปสนามรบแล้วโจมตีใจกลางกองบัญชาการฟรอสต์วูล์ฟ โค่นผู้บัญชาการและผู้พิทักษ์ของพวกมัน นำเหรียญกลับมาให้มากที่สุดเท่าที่จะยัดใส่กระเป๋าได้! ข้าสัญญาว่าเมื่อกริฟฟินของข้าเห็นของที่ได้มาและได้กลิ่นเลือดศัตรู พวกมันจะบินอีกครั้ง! ไปได้แล้ว!" },
        required = { [17504] = { "27:1070747867:592815216", "เหรียญผู้บัญชาการฟรอสต์วูล์ฟ" } },
        objectiveLabels = {
            item = { ["Frostwolf Commander's Medal"] = "เหรียญผู้บัญชาการฟรอสต์วูล์ฟ" },
        },
    },
    [6982] = { -- Coldtooth Supplies
        title = { "18:377566642:521682516", "เสบียงโคลด์ทูธ" },
        objective = { "72:869671732:284608135", "นำ Coldtooth Supplies 10 ชิ้นไปให้ Alliance Quartermaster ใน Dun Baldar" },
        description = { "422:445386063:1951621082 N 60:1847598728:2099695728", "เหมืองโคลด์ทูธเป็นคลังเสบียงของฮอร์ด ข้ากินอาหารที่พวกมันเลี้ยงทหารไม่ลงเลย แถมอาวุธกับเกราะก็อยู่ในสภาพย่ำแย่! แต่... ในยามที่เสบียงสำคัญเช่นนี้ เราก็ใช้ของที่พวกมันมีได้\n\nเข้าเหมืองโคลด์ทูธแล้วนำเสบียงของพวกมันกลับมาให้ข้า นั่นจะช่วยให้อัลไลแอนซ์พร้อมรบ และแย่งอุปกรณ์จำเป็นไปจากนักรบฮอร์ด\n\nขอให้โชคดี {name} เหมืองอยู่ไกลลงใต้ ลึกเข้าไปในดินแดนฮอร์ด" },
        progress = { "53:1062155954:1265117688 N 30:1337406974:2140040923", "เจ้าเข้าเหมืองโคลด์ทูธในดินแดนฮอร์ดแล้วหรือ {name}? ได้ปล้นเสบียงมาหรือไม่?" },
        completion = { "29:998583521:1081075095 N 131:1125165936:771301399 N 65:1489580870:1306271025", "อา เจ้าได้มาแล้ว ทำได้ดี {name}! เสบียงพวกนี้อับชื้นนิดหน่อยเพราะอยู่ในเหมืองมืดมานาน แต่เราจะใช้ประโยชน์จากมันอยู่ดี\n\nขอบคุณ {name} สิ่งที่เจ้าทำสำคัญต่อการรักษากำลังรบของเรา" },
        required = { [17542] = { "18:377566642:521682516", "เสบียงโคลด์ทูธ" } },
        objectiveLabels = {
            item = { ["Coldtooth Supplies"] = "เสบียงโคลด์ทูธ" },
        },
    },
    [6985] = { -- Irondeep Supplies
        title = { "17:300012395:1534940952", "เสบียงไอรอนดีป" },
        objective = { "72:243610930:1676247872", "นำ Irondeep Supplies 10 ชิ้นไปให้ Horde Quartermaster ใน Frostwolf Keep" },
        description = { "239:218758803:828012171 N 114:576488661:252343152", "คนแคระสตอร์มไพก์ใช้เหมืองไอรอนดีปเป็นคลังเสบียง ข้าต้องการให้เจ้าบุกเหมืองแล้วนำเสบียงมาให้ นั่นจะขัดขวางความพยายามของสตอร์มไพก์ในหุบเขาอัลเทอแรค และทำให้เรามีอุปกรณ์ที่ต้องการ!\n\nระวังตัวด้วย {name} เหมืองไอรอนดีปอยู่ลึกในดินแดนอัลไลแอนซ์ และผู้ควบคุมเหมืองเปลี่ยนไปมาไม่ต่างจากหิมะแห่งอัลเทอแรค" },
        progress = { "33:72685418:749345243 N 28:1129530555:519409545", "เจ้าเข้าเหมืองไอรอนดีปแล้วหรือ {name}? ได้ปล้นเสบียงมาหรือไม่?" },
        completion = { "27:2105830793:1296022391 N 94:159359194:1322133890", "เจ้าได้มาแล้ว! ทำได้ดี {name}! หวังว่าเจ้าจะพบคนแคระบ้างระหว่างบุก และหลั่งเลือดพวกมันเพื่อฟรอสต์วูล์ฟ!" },
        required = { [17522] = { "17:300012395:1534940952", "เสบียงไอรอนดีป" } },
        objectiveLabels = {
            item = { ["Irondeep Supplies"] = "เสบียงไอรอนดีป" },
        },
    },
    [7001] = { -- Empty Stables
        title = { "13:1333305189:481940892", "คอกสัตว์ว่างเปล่า" },
        objective = { "265:854537651:2080833959", "ค้นหา Frostwolf ใน Alterac Valley เมื่ออยู่ใกล้ให้ใช้ Frostwolf Muzzle เพื่อ'ทำให้เชื่อง' จากนั้น Frostwolf จะเดินตามคุณกลับไปหา Frostwolf Stable Master พูดคุยกับ Frostwolf Stable Master เพื่อให้การจับสัตว์ครั้งนี้ถูกนับ" },
        description = { "500:1723706471:432501762", "สงครามในหุบเขาทำให้ทหารของเราสูญเสียมาก เราต้องฟื้นฟูกองกำลัง!\n\nหากเติมสัตว์ให้เต็มคอก หน่วยขี่หมาป่าจะออกสู่สนามรบได้อีกครั้ง\n\nนำตะกร้อครอบปากนี้ไปตามหาฟรอสต์วูล์ฟในป่าใกล้ ๆ เมื่อพบหมาป่า ให้ใช้ตะกร้อทำให้มันเชื่อง แล้วนำสัตว์ที่เชื่องกลับมาให้ข้า เพื่อนำเข้าคอก\n\nเมื่อเรามีหมาป่าในคอกพอ หน่วยขี่หมาป่าฟรอสต์วูล์ฟจะกลับไปลาดตระเวนแนวหน้า" },
        progress = { "114:407153551:1474219374", "หากไม่มีเจ้าช่วย หน่วยขี่หมาป่าฟรอสต์วูล์ฟคงไม่มีสัตว์ขี่ออกรบ เจ้าช่วยเราอย่างมาก!" },
        completion = { "87:27058422:72579901 N 67:700159396:1280457274", "ข้าได้แต่หวังว่าผู้รับผิดชอบรวบรวมหนังแกะจะมุ่งมั่นเท่าเจ้า {name}\n\nถ้าทำได้อย่างนี้ เราคงมีสัตว์เต็มคอกในอีกไม่กี่ชั่วโมง!" },
    },
    [7002] = { -- Ram Hide Harnesses
        title = { "18:919072465:1643854564", "สายรัดจากหนังแกะ" },
        progress = { "476:1819875953:2055188189", "ขณะที่ทหารบางคนจับหมาป่าให้ผู้ดูแลคอก คนอื่นต้องจัดหาของจำเป็นพื้นฐานสำหรับการขี่ แน่นอนว่าข้าหมายถึงสายรัด\n\nเจ้าต้องโจมตีแกะพื้นถิ่นในแถบนี้ แกะแบบเดียวกับที่ทหารม้าสตอร์มไพก์ใช้ขี่นั่นละ!\n\nฆ่าพวกมันแล้วนำหนังกลับมาให้ข้า เมื่อได้หนังพอ เราจะทำสายรัดให้ผู้ขี่ หน่วยขี่หมาป่าฟรอสต์วูล์ฟจะออกศึกอีกครั้ง!" },
        completion = { "91:440776139:1991123369", "ทำได้ดี ทหาร ข้าจะแจ้งให้เจ้ารู้เมื่อสะสมหนังได้เพียงพอแล้ว\n\nทำหน้าที่ต่อไป!" },
        description = { "476:1819875953:2055188189", "ขณะที่ทหารบางคนจับหมาป่าให้ผู้ดูแลคอก คนอื่นต้องจัดหาของจำเป็นพื้นฐานสำหรับการขี่ แน่นอนว่าข้าหมายถึงสายรัด\n\nเจ้าต้องโจมตีแกะพื้นถิ่นในแถบนี้ แกะแบบเดียวกับที่ทหารม้าสตอร์มไพก์ใช้ขี่นั่นละ!\n\nฆ่าพวกมันแล้วนำหนังกลับมาให้ข้า เมื่อได้หนังพอ เราจะทำสายรัดให้ผู้ขี่ หน่วยขี่หมาป่าฟรอสต์วูล์ฟจะออกศึกอีกครั้ง!" },
        required = { [17642] = { "16:1458253643:568672499", "หนังแกะเขาโค้งอัลเทอแร็ก" } },
        objectiveLabels = {
            item = { ["Alterac Ram Hide"] = "หนังแกะเขาโค้งอัลเทอแร็ก" },
        },
    },
    [7026] = { -- Ram Riding Harnesses
        title = { "20:45741724:1663160784", "สายรัดสำหรับขี่แกะ" },
        progress = { "470:2028917611:1379246627", "กองพลสตอร์มไพก์จะขี่สัตว์หลังเปล่าออกรบไม่ได้! เราต้องใช้สายรัดกับสัตว์ขี่ เพราะเราไม่ใช่คนเถื่อน\n\nแม้จะฆ่าแกะที่เดินอยู่ใกล้ฐานเพื่อเอาหนังมาทำสายรัดได้ง่าย ๆ แต่นั่นโง่เขลามาก เราต้องการแกะพวกนั้นไว้ขี่\n\nเจ้าต้องบุกฐานศัตรู ฆ่าฟรอสต์วูล์ฟที่พวกมันใช้ขี่แล้วเอาหนังมา นำหนังกลับมาให้ข้า เพื่อทำสายรัดให้ทหารม้า ไปได้แล้ว!" },
        completion = { "91:440776139:1991123369", "ทำได้ดี ทหาร ข้าจะแจ้งให้เจ้ารู้เมื่อสะสมหนังได้เพียงพอแล้ว\n\nทำหน้าที่ต่อไป!" },
        description = { "470:2028917611:1379246627", "กองพลสตอร์มไพก์จะขี่สัตว์หลังเปล่าออกรบไม่ได้! เราต้องใช้สายรัดกับสัตว์ขี่ เพราะเราไม่ใช่คนเถื่อน\n\nแม้จะฆ่าแกะที่เดินอยู่ใกล้ฐานเพื่อเอาหนังมาทำสายรัดได้ง่าย ๆ แต่นั่นโง่เขลามาก เราต้องการแกะพวกนั้นไว้ขี่\n\nเจ้าต้องบุกฐานศัตรู ฆ่าฟรอสต์วูล์ฟที่พวกมันใช้ขี่แล้วเอาหนังมา นำหนังกลับมาให้ข้า เพื่อทำสายรัดให้ทหารม้า ไปได้แล้ว!" },
        required = { [17643] = { "14:1014796656:237102374", "หนังหมาป่าฟรอสต์วูล์ฟ" } },
        objectiveLabels = {
            item = { ["Frostwolf Hide"] = "หนังหมาป่าฟรอสต์วูล์ฟ" },
        },
    },
    [7027] = { -- Empty Stables
        title = { "13:1333305189:481940892", "คอกสัตว์ว่างเปล่า" },
        objective = { "261:633942241:2131273397", "ค้นหา Alterac Ram ใน Alterac Valley เมื่ออยู่ใกล้ให้ใช้ Stormpike Training Collar เพื่อ'ทำให้เชื่อง' จากนั้น Alterac Ram จะเดินตามคุณกลับไปหา Stable Master พูดคุยกับ Stable Master เพื่อให้การจับสัตว์ครั้งนี้ถูกนับ" },
        description = { "26:161318645:1718593594 N 445:375430458:1800529613", "ดูคอกสัตว์สิ {name}! ว่างเปล่า! กองพลสตอร์มไพก์ไม่มีแกะให้ขี่ หน่วยทหารม้าใช้งานไม่ได้แล้ว\n\nเจ้าต้องช่วยเรา ทหาร นำปลอกคอฝึกนี้ออกไปในป่าของหุบเขา หาแกะอัลเทอแรคที่เดินอยู่ทั่วบริเวณ แล้วใช้ปลอกคอจับสักตัว เมื่อจับได้แล้ว นำมันกลับมาให้ข้า แล้วข้าจะนำเข้าคอก\n\nเมื่อมีแกะพอ เราจะแจ้งผู้บัญชาการหน่วยขี่แกะ ด้วยความช่วยเหลือของเจ้า หน่วยทหารม้าจะกลับมาอีกครั้ง!" },
        progress = { "113:1235748010:220538789", "หากไม่มีเจ้าช่วย หน่วยขี่แกะสตอร์มไพก์คงไม่มีสัตว์ขี่ออกรบ เจ้าช่วยเราอย่างมาก!" },
        completion = { "66:1633391163:2041698533", "อีกไม่นานคอกก็จะเต็ม ทำงานให้ดีต่อไป!" },
    },
    [7081] = { -- Alterac Valley Graveyards
        title = { "25:56274379:548253977", "สุสานในหุบเขาอัลเทอแรค" },
        objective = { "87:566644593:1072992805", "บุกสุสานแห่งหนึ่ง แล้วกลับไปหา Sergeant Durgen Stormpike ใน Alterac Mountains" },
        description = { "139:1885832558:1053298830 N 298:884391444:1324197713", "สุสานในหุบเขาอัลเทอแรคเป็นพื้นที่ล้ำค่า ทั้งฮอร์ดและอัลไลแอนซ์ต่อสู้อย่างดุเดือดเพื่อดินแดนศักดิ์สิทธิ์เหล่านี้ {name} เจ้าพร้อมเข้าร่วมการรบนั้นหรือไม่?\n\nข้าต้องการให้เจ้าบุกสุสานของศัตรู หาสุสานที่มีธงฮอร์ดอยู่ตรงกลาง แล้วถอนมันออกจากพื้น! ทำได้เท่านี้งานของเจ้าก็สำเร็จ...\n\nแต่ถ้ายังยึดสุสานไว้ได้อีกไม่กี่นาที ทหารของเราก็จะมารับช่วงต่อในไม่ช้า" },
        progress = { "N 82:62278987:295256906", "{name} เจ้ายังไม่ได้บุกสุสาน กลับมาหาข้าเมื่อทำงานนี้สำเร็จแล้ว!" },
        completion = { "145:384259808:1429153966 N 98:2067526868:2016724865", "ทำได้ดี! สุสานสำคัญต่อการควบคุมหุบเขาอัลเทอแรค เมื่อยึดได้สักแห่ง เจ้าก็ช่วยให้อัลไลแอนซ์มีอำนาจเหนือที่นี่\n\nไปได้แล้ว {name} กลับเข้าสู่การรบ และถ้าเห็นสุสานที่ฮอร์ดควบคุมอยู่... เจ้ารู้ว่าต้องทำอะไร!" },
    },
    [7082] = { -- The Graveyards of Alterac
        title = { "25:61489813:408825828", "สุสานแห่งอัลเทอแรค" },
        objective = { "87:1135734640:2006989774", "บุกสุสานแห่งหนึ่ง แล้วกลับไปหา Corporal Teeka Bloodsnarl ใน Alterac Mountains" },
        description = { "146:176863659:219896199 N 327:1394802145:947090526", "แนวรบในหุบเขาอัลเทอแรคเปลี่ยนอยู่เสมอ ดินแดนผลัดกันอยู่ในมือแต่ละฝ่าย ขณะเราเข้าปะทะศัตรูถึงตาย และสุสานนี่ละ {name} คือจุดที่การรบดุเดือดที่สุด\n\nข้าต้องการให้เจ้าโจมตีสุสานที่อัลไลแอนซ์ยึดอยู่! หาสุสานที่มีธงอัลไลแอนซ์ตรงกลาง แล้วถอนมันออกจากพื้น\n\nทำได้เท่านี้งานที่ข้าให้ก็สำเร็จ แต่... หากยึดสุสานไว้ได้อีกไม่กี่นาที มันจะเป็นของเรา และทหารจะมารับช่วงต่อ" },
        progress = { "40:1372630333:1660051822", "โจมตีสุสานที่อัลไลแอนซ์ยึดอยู่!" },
        completion = { "11:534428891:784080240 N 102:1554862751:823394312", "ทำได้ดี {name}! ทุกสุสานที่เราควบคุมได้จะทำให้วิญญาณศัตรูเร่ร่อนหลงทางและไร้จุดหมายยิ่งขึ้น" },
    },
    [7101] = { -- Towers and Bunkers
        title = { "18:9522105:716197417", "หอคอยและบังเกอร์" },
        objective = { "90:769103460:1067265190", "ยึดหอคอยศัตรู แล้วกลับไปหา Corporal Teeka Bloodsnarl ใน Alterac Mountains" },
        description = { "485:2072436085:1392810844", "หอคอยและบังเกอร์เป็นจุดสำคัญ เราต้องยึดและรักษาไว้ทั้งหมด! ด้วยเหตุนี้ ข้าต้องการให้เจ้าโจมตีบังเกอร์ที่ศัตรูควบคุมอยู่\n\nเข้าไปในบังเกอร์ที่มีธงอัลไลแอนซ์ แล้วเจ้าจะเห็นอีกธงอยู่ด้านใน ถอนธงนั้นออก แล้วธงฮอร์ดสีขาวจะปรากฏแทน ทำได้ดี!\n\nถึงตรงนั้นงานที่ข้าให้ก็เสร็จ แต่หากยึดที่นั่นไว้นานพอ และอัลไลแอนซ์ยึดคืนไม่ได้ มันก็จะถูกทำลาย!" },
        progress = { "36:484572715:2099085995 N 49:1282714001:1966011382", "เจ้ายังไม่ได้บุกบังเกอร์ {name}! จะรอให้คนอื่นชิงเกียรติยศของเจ้าไปหรือ?" },
        completion = { "166:78582662:610726312", "ข้าได้ยินว่าภารกิจของเจ้าสำเร็จแล้ว! น่ายินดี...\n\nทีนี้ทหารของเราจะรุกไปข้างหน้าได้โดยไม่ต้องเกรงภัย และแสดงให้อัลไลแอนซ์เห็นว่าหุบเขาอัลเทอแรคไม่ใช่ที่สำหรับพวกมัน!" },
    },
    [7102] = { -- Towers and Bunkers
        title = { "18:9522105:716197417", "หอคอยและบังเกอร์" },
        objective = { "114:1676049393:628511502", "ทำลายธงที่หอคอยหรือบังเกอร์ของศัตรู แล้วกลับไปหา Sergeant Durgen Stormpike ใน Alterac Mountains" },
        description = { "481:7819510:356202652", "หอคอยและบังเกอร์เป็นจุดป้องกันสำคัญ เราจึงต้องยึดไว้ให้มากที่สุด! ข้าต้องการให้เจ้าโจมตีหอคอยหรือบังเกอร์ในหุบเขาอัลเทอแรค\n\nเข้าไปในหอคอยที่มีธงฮอร์ดอยู่ด้านบน แล้วเจ้าจะเห็นอีกธงของศัตรูอยู่ด้านใน ถอนธงนั้นออก แล้วธงอัลไลแอนซ์สีขาวจะปรากฏแทน ทำได้ดี!\n\nถึงตรงนั้นภารกิจที่ข้าให้ก็เสร็จ แต่หากยึดพื้นที่ไว้นานพอ และฮอร์ดยึดคืนไม่ได้ มันก็จะถูกทำลาย!" },
        progress = { "35:494049573:20024064 N 27:775046671:1794464392", "เจ้ายังไม่ได้บุกหอคอย {name}! รออะไรอยู่?" },
        completion = { "80:1709812948:979996039 N 82:61142177:410859145", "ข้าได้รับรายงานจากสนามรบว่าเจ้าช่วยยึดธงศัตรู ทำได้ดี {name}! เมื่อหน่วยโจมตีระยะไกลของพวกมันเสียตำแหน่ง เราก็ขยับแนวรบไปข้างหน้าได้!" },
    },
    [7121] = { -- The Quartermaster
        title = { "17:1662772563:1805057367", "ฝ่ายเสบียง" },
        objective = { "39:402547041:1095937977", "พูดคุยกับ Stormpike Quartermaster" },
        description = { "N 224:69705445:2040534617", "{name} ฝ่ายเสบียงของเรามอบหมายให้ข้าส่งทหารใหม่ไปหา เขาต้องการเสบียงจากคลังที่เก็บในเหมืองอัลเทอแรค และคงส่งเจ้าไปเอา\n\nเดินตามถนนไป เจ้าจะพบฝ่ายเสบียงของเราทางตะวันตก" },
        completion = { "36:754458288:1763243139 N 143:76285928:1148842138", "ดีที่ได้เห็นทหารใหม่มาที่นี่ {name} แต่ถ้าโชคดี เจ้าคงได้ออกรบและไม่เป็นมือใหม่อีกนาน!\n\nคุยกับข้าอีกครั้ง ข้ามีงานที่ต้องหารือกับเจ้า..." },
    },
    [7122] = { -- Capture a Mine
        title = { "14:114831003:112423640", "ยึดเหมือง" },
        objective = { "118:48087650:1401161796", "ยึดเหมืองที่ Stormpike ไม่ได้ควบคุม แล้วกลับไปหา Sergeant Durgen Stormpike ใน Alterac Mountains" },
        description = { "409:1025235775:1899721576", "เหมืองในหุบเขาอัลเทอแรคมีมากกว่าแร่ ทั้งฟรอสต์วูล์ฟและสตอร์มไพก์เก็บเสบียงส่วนเกินไว้ในเหมืองไอรอนดีปกับโคลด์ทูธ... เป็นความคิดที่ดี ถ้าเพียงเรารักษาการควบคุมพวกมันไว้ได้!\n\nยึดเหมืองแล้วกลับมาหาข้า วิธียึดเหมืองคือเข้าไปในแห่งที่เราไม่ได้ควบคุม แล้วฆ่าผู้นำของมัน เมื่อทำเช่นนั้น เหมืองจะเป็นของเรา และเราจะส่งทหารไปป้องกัน!" },
        progress = { "35:434297317:1699442952 N 90:1355926599:1874368523", "เจ้ายังไม่ได้ยึดเหมือง {name}!\n\nเมื่อเราควบคุมเหมืองแล้ว การรวบรวมแร่และเสบียงจากที่นั่นจะง่ายขึ้นมาก" },
        completion = { "23:393189426:1327401299 N 115:914448460:1039466306", "เจ้าทำได้แล้ว! ทำได้ดี {name}!\n\nเมื่อเราควบคุมเหมืองและมีทหารประจำอยู่ การรวบรวมแร่และเสบียงจากที่นั่นก็ง่ายขึ้นมาก" },
    },
    [7123] = { -- Speak with our Quartermaster
        title = { "28:693582715:1993907097", "พูดคุยกับฝ่ายเสบียงของเรา" },
        objective = { "39:1184398083:29602944", "พูดคุยกับ Frostwolf Quartermaster" },
        description = { "N 244:1663582298:882934677", "{name} ฝ่ายเสบียงฟรอสต์วูล์ฟกำลังหาทหารใหม่สำหรับงานที่ต้องเข้าเหมืองในหุบเขาอัลเทอแรค ไปคุยกับเขา เขาจะอธิบายเพิ่ม\n\nเดินตามถนนไปทางตะวันตกเข้าบังเกอร์ แล้วออกทางประตูตะวันตก เจ้าจะพบฝ่ายเสบียงของเรา" },
        completion = { { "6:1136836709:1914036474 N 22:2088947473:1586456381 C 106:62231882:633525537", "6:1136836709:1914036474 N 22:2088947473:1586456381 C 106:848364144:409331909" }, "สวัสดี {name}! ดีใจที่ได้เห็น{class}เช่นเจ้า กระตือรือร้นจะทำหน้าที่เพื่อฮอร์ด คุยกับข้าอีกครั้ง ข้ามีงานสำคัญให้เจ้า..." },
    },
    [7124] = { -- Capture a Mine
        title = { "14:114831003:112423640", "ยึดเหมือง" },
        objective = { "82:630554125:1630449207", "ยึดเหมืองแห่งหนึ่ง แล้วกลับไปหา Corporal Teeka Bloodsnarl ใน Alterac Mountains" },
        description = { "250:1852374048:2003662316 N 192:1592575236:1785137954", "ขณะที่การรบโหมทั่วหุบเขาอัลเทอแรค มันก็ดุเดือดในเหมืองโคลด์ทูธและไอรอนดีปเช่นกัน ทั้งสองแห่งอุดมด้วยแร่และใช้เก็บเสบียง ไม่น่าแปลกที่มีค่าสูงนัก!\n\nช่วยงานสงครามของเรา {name}! ยึดเหมืองแห่งหนึ่งให้ฮอร์ด! วิธียึดเหมืองคือเข้าไปในแห่งที่เราไม่ได้ควบคุม แล้วฆ่าผู้นำของมัน เมื่อทำสำเร็จ เหมืองจะเป็นของเรา และเราจะส่งทหารไปป้องกัน!" },
        progress = { "33:1566207991:595100922 N 57:1873358686:856922955", "เจ้ายังไม่ได้ยึดเหมือง {name}! หาแห่งที่เราไม่ได้ควบคุม แล้วปราบผู้นำของมัน!" },
        completion = { "178:2077938829:14141454 N 64:498320502:1005244431", "เจ้ายึดเหมืองได้แล้ว! เมื่อมีนักรบของเราคอยป้องกัน การขุดแร่จากส่วนลึกหรือรวบรวมเสบียงที่เก็บไว้ก็ง่ายขึ้นมาก\n\nทำได้ดี {name} สิ่งที่เจ้าทำช่วยการรบของเราอย่างมาก" },
    },
    [7141] = { -- The Battle of Alterac
        title = { "21:519672105:1009511458", "ศึกแห่งอัลเทอแรค" },
        objective = { "124:772204874:1824726410", "เข้าสู่ Alterac Valley ปราบนายพลฝ่าย Horde ชื่อ Drek'thar แล้วกลับไปหา Prospector Stonehewer ใน Alterac Mountains" },
        description = { "359:881173197:1072283854", "สมาคมนักสำรวจเชื่อว่ามีโบราณวัตถุในหุบเขาอัลเทอแรค แต่ออร์คฟรอสต์วูล์ฟไม่ยอมให้เราเข้าสำรวจ เราจะปล่อยให้ฮอร์ดขัดขวางการค้นคว้าทางวิชาการไม่ได้! ปราบนายพลฟรอสต์วูล์ฟ เดร็กธาร์ เมื่อเขาตาย ออร์คจะเสียความได้เปรียบ\n\nเดร็กธาร์อยู่ในป้อมฟรอสต์วูล์ฟ ทางใต้ของหุบเขาอัลเทอแรค จงโค่นเขาแล้วกลับมาหาข้า" },
        progress = { "4:1212538882:161525128 N 50:888488450:109923938", "ไป {name} ไปหุบเขาอัลเทอแรคแล้วปราบนายพลออร์ค!" },
        completion = { "11:534428891:784080240 N 116:1839511414:1308349751", "ทำได้ดี {name}! เมื่อฮอร์ดเสียหน้าเพราะนายพลตาย เราก็จะมีช่วงหายใจหายคอเพื่อเข้าสำรวจ!" },
    },
    [7142] = { -- The Battle for Alterac
        title = { "22:1154137294:97437144", "ศึกชิงอัลเทอแรค" },
        objective = { "130:353915424:747119445", "เข้าสู่ Alterac Valley แล้วปราบนายพลคนแคระ Vanndar Stormpike จากนั้นกลับไปหา Voggah Deathgrip ใน Alterac Mountains" },
        description = { "258:858286101:1697315069 N 24:331499303:1754454138", "คนแคระสตอร์มไพก์กับพันธมิตรบุกหุบเขาอัลเทอแรค เราต้องขับไล่พวกมัน! หากจะชนะศึกชิงอัลเทอแรค ต้องปราบนายพลของพวกมัน แวนดาร์ สตอร์มไพก์!\n\nเจ้าจะพบแวนดาร์ในดันบัลดาร์ ทางเหนือของหุบเขาอัลเทอแรค\n\nจงทำลายเขา {name} แล้วกลับมาหาข้า" },
        progress = { "106:1518465807:41111836", "เราจะไม่ยอมให้คนแคระอยู่ในบ้านของเรา! บุกเข้าใส่ศัตรูแล้วปราบผู้นำ นายพลสตอร์มไพก์!" },
        completion = { "11:534428891:784080240 N 110:350295152:1594217434", "ทำได้ดี {name}! สตอร์มไพก์ไม่มีหวังในการรุกรานโง่เขลาครั้งนี้\n\nฮ่า! จนถึงตอนนี้ สิ่งเดียวที่พวกมันทำได้คือทำให้นายพลของตนถูกฆ่า!" },
    },
    [7161] = { -- Proving Grounds
        title = { "15:1519008751:912407792", "บทพิสูจน์ฝีมือ" },
        objective = { "163:35438886:1681766214", "เดินทางไปถ้ำ Wildpaw ทางตะวันออกเฉียงใต้ของฐานหลักใน Alterac Valley แล้วหา Frostwolf Banner นำ Frostwolf Banner กลับไปให้ Warmaster Laggrond" },
        description = { "6:1136836709:1914036474 C 429:511944382:898990469", "สวัสดี {class} นานแล้วที่เราไม่ได้มีโอกาสตอบรับเสียงเรียกแห่งการรบ ความรู้สึกเดิมฟื้นขึ้นช้า แต่เมื่อตื่นแล้ว เลือดก็สูบฉีด ความเดือดดาลแห่งศึกกลับคืนมา...\n\nผู้มาใหม่ทุกคนในหุบเขาต้องผ่านพิธีแห่งการรบก่อน\n\nลึกเข้าไปในถ้ำโนลล์ไวลด์พอว์มีธงฟรอสต์วูล์ฟอยู่ จงออกไปนำธงกลับมา ส่งให้ข้า แล้วข้าจะมอบเครื่องหมายผู้เริ่มต้นแห่งฟรอสต์วูล์ฟให้" },
        progress = { "18:1120926464:1666111724 N 81:1514981608:1476575074", "ตื่น! ตื่นได้แล้ว {name}! นี่ไม่ใช่ความฝัน เจ้าฝังตัวอยู่กลางการรบที่กำลังเดือดดาลจริง ๆ!" },
        completion = { "138:1997741450:1036297625 N 300:595834433:1245868491", "ความร้อนผ่าวที่เจ้ารู้สึกคือดวงวิญญาณกำลังตื่นขึ้น จิตวิญญาณของเจ้ายอมรับเสียงเรียกสู่อาวุธแล้ว\n\nตอนนี้เจ้าเป็นหนึ่งในฟรอสต์วูล์ฟ {name} ยินดีด้วย\n\nพกเครื่องหมายนี้ติดตัวเสมอ เมื่อเจ้าเลื่อนชั้นในหมู่ฟรอสต์วูล์ฟ ข้าจะเปลี่ยนให้เป็นเครื่องหมายที่ทรงพลังกว่า\n\nบางทีสักวันเจ้าอาจได้รับการยกย่องสูงสุดในเผ่าฟรอสต์วูล์ฟ หากวันนั้นมาถึง เจ้าจะได้รับดวงตาแห่งบัญชาการ" },
        required = { [17850] = { "16:1959474922:1845273879", "ธงฟรอสต์วูล์ฟ" } },
        objectiveLabels = {
            item = { ["Frostwolf Banner"] = "ธงฟรอสต์วูล์ฟ" },
        },
    },
    [7162] = { -- Proving Grounds
        title = { "15:1519008751:912407792", "บทพิสูจน์ฝีมือ" },
        objective = { "191:1214919745:523604644", "เดินทางไป Icewing Caverns ทางตะวันตกเฉียงใต้ของ Dun Baldar ใน Alterac Valley แล้วนำ Stormpike Banner กลับคืนมา ส่ง Stormpike Banner ให้ Lieutenant Haggerdin ใน Alterac Mountains" },
        description = { "29:482153284:260368574 C 448:1251628193:253604883", "เจ้ามาทันเวลาพอดี {class} คนเถื่อนฟรอสต์วูล์ฟพวกนี้ไม่ยอมเลิกรา! เราต้องแสดงพลังสตอร์มไพก์ให้เห็น พวกมันต้องยอมก้มหัวต่อความเหนือกว่าของเรา\n\nก่อนเจ้าจะเข้าสนามรบ คงอยากเข้าร่วมสตอร์มไพก์เสียก่อน\n\nทางตะวันตกเฉียงใต้ของดันบัลดาร์ เจ้าจะพบถ้ำไอซ์วิง ลึกเข้าไปมีธงสตอร์มไพก์ปักอยู่ จงออกไปนำธงกลับมาให้ข้า แล้วเจ้าจะได้รับเครื่องหมายผู้เริ่มต้นแห่งสตอร์มไพก์" },
        progress = { "34:2094087242:646222917 C 49:1298132711:279519089", "ระวังฮาร์ปีในแถบนี้ {class} พวกมันไม่ลังเลที่จะฉีกคอเจ้า!" },
        completion = { "40:640132013:2133563837 N 322:473901600:1886001355", "รับเครื่องหมายนี้ไปและสวมอย่างภาคภูมิ {name} เมื่อฐานะของเจ้าในสตอร์มไพก์สูงขึ้น เครื่องหมายก็จะทรงพลังขึ้นด้วย กลับมาหาข้าเมื่อเจ้าได้รับเกียรติจากสตอร์มไพก์ แล้วข้าจะเปลี่ยนให้เป็นเครื่องหมายที่ทรงพลังกว่า\n\nบางทีสักวันเจ้าอาจกลายเป็นตำนานบนสนามรบแห่งนี้ หากวันนั้นมาถึง เจ้าจะได้รับดวงตาแห่งบัญชาการ" },
        required = { [17849] = { "16:1433297818:1239949145", "ธง Stormpike" } },
        objectiveLabels = {
            item = { ["Stormpike Banner"] = "ธง Stormpike" },
        },
    },
    [7163] = { -- Rise and Be Recognized
        title = { "22:1227479882:427732420", "ก้าวขึ้นรับการยอมรับ" },
        progress = { "51:484717318:642471922 N 177:1250304943:1340750069", "<วอร์มาสเตอร์ลากกรอนด์ทำวันทยหัตถ์ให้เจ้า>\n\nถึงเวลาของเจ้าแล้ว {name} เจ้าทำเพื่อเผ่าฟรอสต์วูล์ฟมากมาย จนได้ที่ยืนไม่เพียงในฐานะทหารฟรอสต์วูล์ฟ แต่ยังเป็นสหายด้วย\n\nทำได้ดี! ยื่นเครื่องหมายผู้เริ่มต้นของเจ้ามา" },
        completion = { "93:574978518:505845274 C 19:815562939:1173495373", "เครื่องหมายใหม่นี้สะท้อนฐานะของเจ้าในหมู่ฟรอสต์วูล์ฟ จงพกติดตัวเสมอ\n\nและ {class}... จงตายอย่างมีเกียรติ!" },
        description = { "51:484717318:642471922 N 177:1250304943:1340750069", "<วอร์มาสเตอร์ลากกรอนด์ทำวันทยหัตถ์ให้เจ้า>\n\nถึงเวลาของเจ้าแล้ว {name} เจ้าทำเพื่อเผ่าฟรอสต์วูล์ฟมากมาย จนได้ที่ยืนไม่เพียงในฐานะทหารฟรอสต์วูล์ฟ แต่ยังเป็นสหายด้วย\n\nทำได้ดี! ยื่นเครื่องหมายผู้เริ่มต้นของเจ้ามา" },
        required = { [17690] = { "25:442914295:137544726", "ตราฟรอสต์วูล์ฟ ขั้น 1" } },
        objectiveLabels = {
            item = { ["Frostwolf Insignia Rank 1"] = "ตราฟรอสต์วูล์ฟ ขั้น 1" },
        },
    },
    [7164] = { -- Honored Amongst the Clan
        title = { "24:303093676:319047442", "ผู้ได้รับเกียรติในเผ่า" },
        progress = { "29:1413554121:942060837 C 141:743485025:186840947 N 113:960055039:283934550", "ดีใจที่ได้พบเจ้าอีก {class} ข้าไม่ได้คาดว่าเจ้าจะกลับมา แต่เจ้าพิสูจน์แล้วว่าเป็นทหารฟรอสต์วูล์ฟที่กล้าหาญและมีเกียรติ\n\nถึงเวลาของเจ้าอีกครั้ง {name} เจ้าได้รับฐานะใหม่ จึงควรได้เครื่องหมายใหม่แสดงการเลื่อนชั้นนี้\n\nยื่นเครื่องหมายของเจ้ามา" },
        completion = { "34:910429239:1877629012 N 96:868048798:2084307434", "<วอร์มาสเตอร์ลากกรอนด์ทำวันทยหัตถ์>\n\nไป {name}! ปกป้องฟรอสต์วูล์ฟต่อไป ต้องชนะสงครามนี้! เพื่อเดร็กธาร์! เพื่อวอร์ชีฟ!" },
        description = { "29:1413554121:942060837 C 141:743485025:186840947 N 113:960055039:283934550", "ดีใจที่ได้พบเจ้าอีก {class} ข้าไม่ได้คาดว่าเจ้าจะกลับมา แต่เจ้าพิสูจน์แล้วว่าเป็นทหารฟรอสต์วูล์ฟที่กล้าหาญและมีเกียรติ\n\nถึงเวลาของเจ้าอีกครั้ง {name} เจ้าได้รับฐานะใหม่ จึงควรได้เครื่องหมายใหม่แสดงการเลื่อนชั้นนี้\n\nยื่นเครื่องหมายของเจ้ามา" },
        required = { [17905] = { "25:442914296:137544727", "ตราฟรอสต์วูล์ฟ ขั้น 2" } },
        objectiveLabels = {
            item = { ["Frostwolf Insignia Rank 2"] = "ตราฟรอสต์วูล์ฟ ขั้น 2" },
        },
    },
    [7165] = { -- Earned Reverence
        title = { "16:1297013104:2079528050", "ความเคารพที่ได้มา" },
        progress = { "200:549847765:505705587", "ล้มตายมากมาย เลือดชุ่มสนาม แต่... เจ้ายังมีชีวิต... เจ้าไม่ยอมแพ้ เจ้านำกองทัพของเราไปสู่ชัยชนะหลายครั้ง ด้วยเหตุนี้ ทหาร เจ้าจึงได้รับฐานะใหม่\n\nยื่นเครื่องหมายของเจ้ามา" },
        completion = { "155:793828602:1513494892", "<วอร์มาสเตอร์ลากกรอนด์คำราม>\n\nพวกเขาเริ่มเล่าขานวีรกรรมของเจ้าแล้ว ทหาร สตอร์มไพก์สั่นกลัวเมื่อได้ยินชื่อเจ้า ทำหน้าที่ต่อไป!" },
        description = { "200:549847765:505705587", "ล้มตายมากมาย เลือดชุ่มสนาม แต่... เจ้ายังมีชีวิต... เจ้าไม่ยอมแพ้ เจ้านำกองทัพของเราไปสู่ชัยชนะหลายครั้ง ด้วยเหตุนี้ ทหาร เจ้าจึงได้รับฐานะใหม่\n\nยื่นเครื่องหมายของเจ้ามา" },
        required = { [17906] = { "25:442914297:137544728", "ตราฟรอสต์วูล์ฟ ขั้น 3" } },
        objectiveLabels = {
            item = { ["Frostwolf Insignia Rank 3"] = "ตราฟรอสต์วูล์ฟ ขั้น 3" },
        },
    },
    [7166] = { -- Legendary Heroes
        title = { "16:81740682:1728407184", "วีรชนในตำนาน" },
        progress = { "32:121916598:611271505 C 151:321493937:1626992361", "เจ้าแผ่รัศมีแห่งอำนาจบัญชาการและพลัง {class} เป็นที่ยกย่องสูงสุดในสายตาฟรอสต์วูล์ฟ ศัตรูหวาดผวาเพียงได้ยินชื่อเจ้า\n\nจงลุกขึ้น วีรชนแห่งฟรอสต์วูล์ฟ ลุกขึ้นรับเกียรติยศ!\n\nยื่นเครื่องหมายของเจ้ามา" },
        completion = { "117:1383909553:1398745583", "อีกไม่นาน ทุกสิ่งบนสนามรบจะอยู่ใต้สายตาอันระแวดระวังของเจ้า อำนาจบัญชาการหุบเขาและเหล่าทหารจะเป็นของเจ้า!" },
        description = { "32:121916598:611271505 C 151:321493937:1626992361", "เจ้าแผ่รัศมีแห่งอำนาจบัญชาการและพลัง {class} เป็นที่ยกย่องสูงสุดในสายตาฟรอสต์วูล์ฟ ศัตรูหวาดผวาเพียงได้ยินชื่อเจ้า\n\nจงลุกขึ้น วีรชนแห่งฟรอสต์วูล์ฟ ลุกขึ้นรับเกียรติยศ!\n\nยื่นเครื่องหมายของเจ้ามา" },
        required = { [17907] = { "25:442914298:137544729", "ตราฟรอสต์วูล์ฟ ขั้น 4" } },
        objectiveLabels = {
            item = { ["Frostwolf Insignia Rank 4"] = "ตราฟรอสต์วูล์ฟ ขั้น 4" },
        },
    },
    [7167] = { -- The Eye of Command
        title = { "18:1622721094:969409740", "ดวงตาแห่งบัญชาการ" },
        progress = { "225:862920491:463015830 N 1:46:46", "เดร็กธาร์สรรเสริญเจ้า คาลิมดอร์เล่าลือถึงวีรกรรม วอร์ชีฟปลาบปลื้ม การปกป้องเผ่าอย่างไม่สั่นคลอนของเจ้าทำให้เขาพอใจยิ่ง\n\nเจ้าสมควรได้รับดวงตาแห่งบัญชาการ\n\nยื่นเครื่องหมายของเจ้ามา ผู้บัญชาการ {name}" },
        completion = { "107:1272769281:716506340", "ดึงพลังเครื่องหมายมาใช้ ให้ศัตรูได้ยินถ้อยคำของเจ้า อำนาจแห่งฮอร์ดไม่มีข้อกังขา!" },
        description = { "225:862920491:463015830 N 31:1588371474:884176091", "เดร็กธาร์สรรเสริญเจ้า คาลิมดอร์เล่าลือถึงวีรกรรม วอร์ชีฟปลาบปลื้ม การปกป้องเผ่าอย่างไม่สั่นคลอนของเจ้าทำให้เขาพอใจยิ่ง\n\nเจ้าสมควรได้รับดวงตาแห่งบัญชาการ\n\nยื่นเครื่องหมายของเจ้ามา ผู้บัญชาการ {name}\n\n<Warmaster Laggrond ทำความเคารพ>" },
        required = { [17908] = { "25:442914299:137544730", "ตราฟรอสต์วูล์ฟ ขั้น 5" } },
        objectiveLabels = {
            item = { ["Frostwolf Insignia Rank 5"] = "ตราฟรอสต์วูล์ฟ ขั้น 5" },
        },
    },
    [7168] = { -- Rise and Be Recognized
        title = { "22:1227479882:427732420", "ก้าวขึ้นรับการยอมรับ" },
        progress = { "118:1324198609:937483529 C 43:2015973516:983221100", "คนส่วนใหญ่มีชีวิตไม่ยืนยาวพอจะก้าวพ้นความธรรมดาของตน เจ้าพิสูจน์แล้วว่าเป็นทหารแบบอย่าง {class} ถึงเวลาแล้ว\n\nยื่นเครื่องหมายของเจ้ามา" },
        completion = { "98:534393046:834427128", "ให้ศัตรูเห็นว่าผู้โค่นพวกมันคือทหารผู้มีฐานะ! จงต่อสู้เพื่อเกียรติยศแห่งสตอร์มไพก์!" },
        description = { "118:1324198609:937483529 C 43:2015973516:983221100", "คนส่วนใหญ่มีชีวิตไม่ยืนยาวพอจะก้าวพ้นความธรรมดาของตน เจ้าพิสูจน์แล้วว่าเป็นทหารแบบอย่าง {class} ถึงเวลาแล้ว\n\nยื่นเครื่องหมายของเจ้ามา" },
