    [7169] = { -- Honored Amongst the Guard
        title = { "25:1008448333:43775449", "ผู้ได้รับเกียรติในกองรักษาการณ์" },
        progress = { "224:1632166516:1191526789", "ทั้งฐานพูดถึงวีรกรรมของเจ้าในทุ่งแห่งความขัดแย้ง! เจ้าสร้างความเสียหายรุนแรงแก่ศัตรู บดขยี้ขวัญของพวกมัน! ด้วยเหตุนี้ เจ้าจึงได้รับฐานะอันทรงเกียรติในหมู่สตอร์มไพก์\n\nยื่นเครื่องหมายของเจ้ามา" },
        completion = { "58:887270187:1372138579 C 59:1428374011:1407102938", "กษัตริย์ได้รับทราบวีรกรรมแนวหน้าของเจ้าแล้ว {class} จงปกป้องกองรักษาการณ์สตอร์มไพก์อย่างไม่สั่นคลอนต่อไป!" },
        description = { "224:1632166516:1191526789", "ทั้งฐานพูดถึงวีรกรรมของเจ้าในทุ่งแห่งความขัดแย้ง! เจ้าสร้างความเสียหายรุนแรงแก่ศัตรู บดขยี้ขวัญของพวกมัน! ด้วยเหตุนี้ เจ้าจึงได้รับฐานะอันทรงเกียรติในหมู่สตอร์มไพก์\n\nยื่นเครื่องหมายของเจ้ามา" },
