    [7170] = { -- Earned Reverence
        title = { "16:1297013104:2079528050", "ความเคารพที่ได้มา" },
        progress = { "13:405782790:1465082752 N 213:728023310:1315448317", "ข้าต้องรู้ {name} เมื่อเจ้าจ้องตาศัตรู เห็นความกลัวหรือไม่? ตอนนี้พวกมันหวาดผวาต่อหน้าเจ้าแล้วหรือ? พวกมันต้องตระหนักว่าพ่ายแพ้แล้ว!\n\nเจ้าได้รับความเคารพในกองรักษาการณ์ ยื่นเครื่องหมายมา!" },
        completion = { "95:17272776:515138525", "เมื่อแรกพบ ข้าไม่เคยนึกเลยว่าวีรชนกำลังก่อร่างขึ้น ทำหน้าที่ต่อไป ทหาร!" },
        description = { "13:405782790:1465082752 N 213:728023310:1315448317", "ข้าต้องรู้ {name} เมื่อเจ้าจ้องตาศัตรู เห็นความกลัวหรือไม่? ตอนนี้พวกมันหวาดผวาต่อหน้าเจ้าแล้วหรือ? พวกมันต้องตระหนักว่าพ่ายแพ้แล้ว!\n\nเจ้าได้รับความเคารพในกองรักษาการณ์ ยื่นเครื่องหมายมา!" },
        required = { [17901] = { "25:1370659321:240998166", "ตราสตอร์มไพก์ ขั้น 3" } },
        objectiveLabels = {
            item = { ["Stormpike Insignia Rank 3"] = "ตราสตอร์มไพก์ ขั้น 3" },
        },
    },
    [7171] = { -- Legendary Heroes
        title = { "16:81740682:1728407184", "วีรชนในตำนาน" },
        progress = { "318:1191721420:361681510", "ตรงหน้าข้าคือวีรชนผู้ได้รับการยกย่องสูงสุดแห่งอัลไลแอนซ์\n\n<ร้อยโทแฮกเกอร์ดินทำวันทยหัตถ์>\n\nน้อยคนนักจะได้ฐานะเช่นนี้ในหมู่สตอร์มไพก์ ข้าเห็นศัตรูล้มลงต่อหน้าเจ้า เห็นความมุ่งมั่นของพวกมันพังทลายเมื่อเจ้าอยู่ตรงนั้น เมื่อเข้าสู่การรบ เจ้ากลายเป็นแสงแห่งความหวังให้กองกำลังเรา!\n\nยื่นเครื่องหมายของเจ้ามา" },
        completion = { "53:1255585217:1106051409", "ต้องเป็นเจ้าแน่ที่จะครอบครองดวงตาแห่งบัญชาการ!" },
        description = { "318:1191721420:361681510", "ตรงหน้าข้าคือวีรชนผู้ได้รับการยกย่องสูงสุดแห่งอัลไลแอนซ์\n\n<ร้อยโทแฮกเกอร์ดินทำวันทยหัตถ์>\n\nน้อยคนนักจะได้ฐานะเช่นนี้ในหมู่สตอร์มไพก์ ข้าเห็นศัตรูล้มลงต่อหน้าเจ้า เห็นความมุ่งมั่นของพวกมันพังทลายเมื่อเจ้าอยู่ตรงนั้น เมื่อเข้าสู่การรบ เจ้ากลายเป็นแสงแห่งความหวังให้กองกำลังเรา!\n\nยื่นเครื่องหมายของเจ้ามา" },
        required = { [17902] = { "25:1370659322:240998167", "ตราสตอร์มไพก์ ขั้น 4" } },
        objectiveLabels = {
            item = { ["Stormpike Insignia Rank 4"] = "ตราสตอร์มไพก์ ขั้น 4" },
        },
    },
    [7172] = { -- The Eye of Command
        title = { "18:1622721094:969409740", "ดวงตาแห่งบัญชาการ" },
        progress = { "36:922360826:397207869 N 100:1268999083:1314076861", "ให้พวกมันได้ยินเสียงเจ้า ผู้บัญชาการ {name}! ให้พวกมันรู้จักความกลัว แสดงให้เห็นว่าพลังใดอยู่ในหมู่สตอร์มไพก์!\n\nยื่นเครื่องหมายของเจ้ามา" },
        completion = { "166:922738076:549157611", "เจ้าต้องเป็นผู้นำทหารเราไปสู่ชัยชนะ ผู้บัญชาการ! ทหารอยู่ใต้บัญชาเจ้า พวกเขาจะทำตามคำสั่งโดยตรง จงนำพวกเขา... บดขยี้ฟรอสต์วูล์ฟ" },
        description = { "36:922360826:397207869 N 100:1268999083:1314076861", "ให้พวกมันได้ยินเสียงเจ้า ผู้บัญชาการ {name}! ให้พวกมันรู้จักความกลัว แสดงให้เห็นว่าพลังใดอยู่ในหมู่สตอร์มไพก์!\n\nยื่นเครื่องหมายของเจ้ามา" },
        required = { [17903] = { "25:1370659323:240998168", "ตราสตอร์มไพก์ ขั้น 5" } },
        objectiveLabels = {
            item = { ["Stormpike Insignia Rank 5"] = "ตราสตอร์มไพก์ ขั้น 5" },
        },
    },
    [7181] = { -- The Legend of Korrak
        title = { "20:1358401097:456030855", "ตำนานของคอร์แร็ก" },
        objective = { "207:1152285133:1990790694", "ตามตำนาน ผู้นำโทรลล์ Winterax ผู้ทรงพลังจะปรากฏตัวตามใจเพื่อสร้างความหายนะแก่ผู้ที่อยู่ใน Alterac Valley\n\nหาก Korrak ปรากฏตัว จงสังหารเขาแล้วกลับไปหา Warmaster Laggrond" },
        description = { "345:930894172:283086314", "สตอร์มไพก์ผู้รุกรานไม่ใช่ภัยคุกคามเดียวในแถบนี้ ทหาร สงครามในหุบเขามีสองแนวรบ โทรลล์วินเทอร์แอกซ์กินคนก็แย่งชิงอำนาจเช่นกัน\n\nพวกมันนำโดยคอร์แร็กผู้คลั่งโลหิต อสูรที่โหดเหี้ยมและเจ้าเล่ห์\n\nการโจมตีคอร์แร็กอาจสร้างความเสียหายย่อยยับแก่เผ่าวินเทอร์แอกซ์ ฆ่าอสูรนั้นแล้วรับรางวัล!" },
    },
    [7202] = { -- Korrak the Bloodrager
        title = { "21:1352574965:1744555433", "คอร์แร็กผู้คลั่งโลหิต" },
        objective = { "234:1349902000:1045791374", "ตามตำนาน ผู้นำโทรลล์ Winterax ผู้ทรงพลังจะปรากฏตัวตามใจเพื่อสร้างความหายนะแก่ผู้ที่อยู่ใน Alterac Valley\n\nหาก Korrak ปรากฏตัว จงสังหารเขาแล้วกลับไปหา Lieutenant Haggerdin ใน Alterac Mountains" },
        description = { "462:501839119:127700736", "โทรลล์วินเทอร์แอกซ์พื้นถิ่นเป็นคนเถื่อนไร้เมตตา ไม่มีอะไรถูกใจพวกมันยิ่งกว่าการนำกระดูกเราไปใส่สตูเหม็นเน่า\n\nเราต้องแสดงพลังให้เห็น!\n\nเรากู้ตำราจากถ้ำพวกมันมาได้ ซึ่งแจกแจงลำดับผู้นำ โบราณวัตถุระบุว่าผู้นำของพวกมัน คอร์แร็กผู้คลั่งโลหิต มักซ่อนตัวจนกว่าจะมีเหตุให้เผยตน\n\nความตายของคอร์แร็กย่อมหมายถึงความตายของเผ่าวินเทอร์แอกซ์! จงฆ่าเขาแล้วกลับมา" },
    },
    [7221] = { -- Speak with Prospector Stonehewer
        title = { "32:2133240611:1687252966", "พูดคุยกับพรอสเพกเตอร์สโตนฮิวเวอร์" },
        objective = { "60:2026949570:953292420", "พูดคุยกับ Prospector Stonehewer ในกองรักษาการณ์ Dun Baldar" },
        description = { { "4:1110228981:147916455 N 345:1822895621:1000883877 C 41:1750755034:750003025", "4:1110228981:147916455 N 345:1822895621:1000883877 C 41:1231318579:222404753" }, "อา {name} มารายงานตัวปฏิบัติหน้าที่หรือ? เยี่ยม สตอร์มไพก์ต้องการทุกคนที่รวบรวมกำลังมาได้!\n\nคุยกับพรอสเพกเตอร์สโตนฮิวเวอร์ในดันบัลดาร์ เธอกำลังรับสมัครคนสำหรับภารกิจสำคัญในดินแดนศัตรู เจ้าจะพบสโตนฮิวเวอร์ที่ชั้นล่างของกองรักษาการณ์ดันบัลดาร์\n\nคอยสังเกตขณะผ่านดันบัลดาร์ด้วย มีงานมากมายสำหรับ{class}ขยันขันแข็งที่ไม่กลัวมือเปื้อน" },
    },
    [7222] = { -- Speak with Voggah Deathgrip
        title = { "27:937439551:495644931", "พูดคุยกับว็อกกาห์ เดธกริป" },
        objective = { "36:1828874296:794758713", "พูดคุยกับ Voggah ใน Frostwolf Keep" },
        description = { "2:16737:8547 C 43:313452854:92301908 N 293:827712939:204650455", "{class}หรือ? ดี! เรายินดีที่ได้เห็นเจ้าในอัลเทอแรค {name} คนแคระผู้บุกรุกกับพันธมิตรกำลังรุกรานหุบเขาของเรา เราขอต้อนรับชาวฮอร์ดทุกคนมาร่วมการสังหารอันชอบธรรม!\n\nคุยกับว็อกกาห์ เดธกริป เขากำลังหาคนทำภารกิจสำคัญในฐานที่มั่นอัลไลแอนซ์แห่งหุบเขาอัลเทอแรค!\n\nเจ้าจะพบว็อกกาห์ในป้อมฟรอสต์วูล์ฟ" },
    },
    [7223] = { -- Armor Scraps
        title = { "12:314606019:1213303122", "เศษเกราะ" },
        objective = { "56:78317629:672232430", "นำ Armor Scraps 20 ชิ้นไปให้ Murgot Deepforge ใน Dun Baldar" },
        description = { "226:640650356:288971229", "การรบโหมอยู่ตลอดในหุบเขาอัลเทอแรค และเสบียงที่ได้จากไอรอนฟอร์จไม่พอจัดอุปกรณ์ให้ทหารมากประสบการณ์ของเรา\n\nหากเจอเศษเกราะในสนามรบ ช่วยงานสงครามด้วยการนำมาให้ข้า!" },
        progress = { "32:786900313:1244255646 N 1:63:63", "เจ้านำเศษเกราะมาบ้างไหม {name}?" },
        completion = { "28:1461073525:1518293532 N 155:1731490950:764307950", "ชิ้นส่วนพวกนี้ดีมาก {name} ข้านำไปทำอุปกรณ์ใหม่ให้ทหารของเราได้\n\nหากระดับเสบียงของข้าสูงพอ บางทีหน่วยรบมากประสบการณ์ของเราอาจลงสนาม!" },
        required = { [17422] = { "12:314606019:1213303122", "เศษเกราะ" } },
        objectiveLabels = {
            item = { ["Armor Scraps"] = "เศษเกราะ" },
        },
    },
    [7224] = { -- Enemy Booty
        title = { "11:2013722605:1748598824", "ของที่ยึดจากศัตรู" },
        objective = { "59:216309386:2120967891", "นำ Armor Scraps 20 ชิ้นไปให้ Smith Regzar ใน Frostwolf Village" },
        description = { "136:1390693376:724285946", "เมื่อสู้กับศัตรู จงเก็บเศษเกราะของพวกมันแล้วนำมาให้ข้า ข้าจะนำไปทำเกราะให้ทหารของเราเอง!" },
        progress = { "22:1587245246:68769387 N 38:1447335120:300539492", "การล่าเป็นอย่างไร {name} มีเศษเกราะมาให้ข้าหรือไม่?" },
        completion = { "130:2132287273:59660525 N 45:2060002346:696117539", "พวกนี้ใช้ได้ดี ข้าจะหลอมแล้วซ่อมปะให้ เจ้าจะไม่มีทางรู้ว่ามันเคยเป็นของสตอร์มไพก์ขี้ขลาดพวกนั้น!\n\nขอบคุณ {name} ให้ข้าขัดเกราะของเจ้าหน่อย..." },
        required = { [17422] = { "12:314606019:1213303122", "เศษเกราะ" } },
        objectiveLabels = {
            item = { ["Armor Scraps"] = "เศษเกราะ" },
        },
    },
    [7241] = { -- In Defense of Frostwolf
        title = { "23:25606586:511389125", "ปกป้องฟรอสต์วูล์ฟ" },
        objective = { "278:1452233704:1290127623", "เดินทางไป Alterac Valley ใน Alterac Mountains หาและพูดคุยกับ Warmaster Laggrond ผู้ยืนอยู่นอกทางเข้าอุโมงค์ เพื่อเริ่มรับหน้าที่ทหาร Frostwolf คุณจะพบ Alterac Valley ทางเหนือของ Tarren Mill บริเวณเชิง Alterac Mountains" },
        description = { "46:201875692:1208230725 C 419:519736702:1365201977 C 28:1748859687:1133503700", "กลองศึกดังจากดินแดนไกลโพ้น {class} เผ่าที่วอร์ชีฟโปรดปรานกำลังถูกกองรักษาการณ์สตอร์มไพก์อันชั่วร้ายแห่งไอรอนฟอร์จโจมตี\n\nดูจากรูปร่าง ข้ารู้ได้ว่าเจ้าผ่านศึกและพร้อมรับภารกิจแห่งฟรอสต์วูล์ฟจริง ๆ\n\nเจ้าต้องเป็นผู้ก้าวต่อไปในเส้นทางพัฒนาตน\n\nเหนือทาร์เรนมิลล์ ในอัลเทอแรค เจ้าจะพบทางเข้าหุบเขาอัลเทอแรค วอร์มาสเตอร์ลากกรอนด์อยู่ที่นั่น รีบไป {class} การรบมาถึงแล้ว!" },
        completion = { "61:755541371:1623346325", "ผู้ที่จะเป็นทหารฟรอสต์วูล์ฟต้องผ่านการทดสอบก่อน..." },
    },
    [7261] = { -- The Sovereign Imperative
        title = { "24:1260874719:1917883780", "พันธกิจแห่งอธิปไตย" },
        objective = { "156:910405680:1988374043", "เดินทางไป Alterac Valley ใน Hillsbrad Foothills หาและพูดคุยกับ Lieutenant Haggerdin ด้านนอกอุโมงค์ทางเข้า\n\nเพื่อเกียรติยศแห่ง Bronzebeard!" },
        description = { "495:1357083225:1557297103", "เรากำลังสู้รบอย่างโหดร้ายในหุบเขาอัลเทอแรค โทรลล์วินเทอร์แอกซ์กินคนโจมตีจากด้านหนึ่ง เผ่าฟรอสต์วูล์ฟป่าเถื่อนจากอีกด้าน ต้องกำจัดทั้งคู่ในนามกษัตริย์แม็กนี บรอนซ์เบียร์ด! การยึด กวาดล้าง และแปรสภาพดินแดนนั้นเป็นพันธกิจด้านอธิปไตยและดินแดนของอาณาจักรไอรอนฟอร์จ\n\nแต่ทหารไม่ได้งอกบนต้นไม้! ไปรายงานตัวกับร้อยโทแฮกเกอร์ดินนอกหุบเขาอัลเทอแรค เพื่อเริ่มหน้าที่และเส้นทางเกียรติยศในหมู่สตอร์มไพก์" },
        completion = { "18:392214983:1804581835", "เริ่มงานกันเถอะ!" },
    },
    [7281] = { -- Brotherly Love
        title = { "14:670263503:1460449307", "ความรักระหว่างพี่น้อง" },
        objective = { "125:1301377643:972623005", "เดินทางเข้าเขต Stormpike แล้วสังหาร Commander Karl Philips เมื่อสำเร็จให้กลับไปหา Commander Louis Philips" },
        description = { "440:2929016:1826843509", "น่าเศร้า... พี่น้องของข้าเผชิญหน้าข้าในสนามรบ ในฐานะผู้บัญชาการสตอร์มไพก์\n\nในบรรดาผู้บัญชาการสตอร์มไพก์ทั้งสี่ เขาอันตรายที่สุดอย่างไม่ต้องสงสัย บางทีถ้าเขาถูกฆ่า ราชินีแบนชีอาจเปลี่ยนเขาเหมือนที่เปลี่ยนข้า แสดงให้เห็นว่าหนทางของตนผิดพลาด...\n\nเจ้าจะพบพี่น้องของข้าลึกในดินแดนศัตรู ฆ่าเขาแล้วกลับมาหาข้า ข้าเชื่อว่าเจ้าทำภารกิจนี้สำเร็จได้ ทหาร\n\nและทหาร อย่าไปคนเดียว" },
        progress = { "105:1672220058:589347902", "เขาคงเจ็บปวดนักที่ยังเป็นผู้มีชีวิต ขณะที่พี่น้องอันเป็นที่รักได้ก้าวสู่ความสมบูรณ์แบบแล้ว" },
        completion = { "36:1557589380:1835846960 N 72:564799117:728955871", "วีรกรรมของเจ้าจะไม่ถูกมองข้าม {name}\n\nข้าจะเสียเวลาไม่ได้หากจะช่วยเขาไว้ ต้องติดต่อซิลวานัส!" },
    },
    [7282] = { -- Brotherly Love
        title = { "14:670263503:1460449307", "ความรักระหว่างพี่น้อง" },
        objective = { "125:482721401:200242470", "เดินทางเข้าเขต Frostwolf แล้วสังหาร Commander Louis Philips เมื่อสำเร็จให้กลับไปหา Commander Karl Philips" },
        description = { "279:1506066642:966183872", "ต้องยุติความทุกข์ของเขา ทหาร! เขาไม่รู้ตัวว่ากำลังทำอะไร กลายเป็นข้ารับใช้ไร้จิตใจของราชินีแบนชีผู้เป็นที่หวาดกลัวแล้ว\n\nออกไป ข้ามทุ่งแห่งความขัดแย้ง เข้าสู่ส่วนลึกของดินแดนฟรอสต์วูล์ฟ หาพี่น้องของข้าแล้วทำลายเขา ต้องให้ความทรมานของเขาสิ้นสุดลง" },
        progress = { "58:654267434:1642259444", "ข้าสั่งเช่นนี้ด้วยหัวใจหนักอึ้ง ทหาร" },
        completion = { "48:485543432:1131714838", "เจ้าจำได้ว่าต้องเผาศพ ใช่ไหม?" },
    },
    [7301] = { -- Fallen Sky Lords
        title = { "16:1698671758:1473981632", "จ้าวเวหาที่ร่วงหล่น" },
        objective = { "178:2038796371:1148565677", "เดินทางเข้าเขต Frostwolf แล้วค้นหา Wing Commander Slidore, Wing Commander Vipore และ Wing Commander Ichman เมื่อทำภารกิจสำเร็จให้กลับไปหา Commander Duffy" },
        description = { "27:688108806:405173285 R 347:1594461313:1238085343", "เราจับพวกมันเป็นเชลยไว้ {race} ข้าหมายถึงผู้บัญชาการฝูงบินของพวกมัน ศึกกลางฟ้าดุเดือด แต่ในที่สุดพวกมันก็ตกลงมา! น่าเสียดายที่นักบินฝีมือดีที่สุดของเราถูกยิงตกในการโจมตีตอบโต้ป้อมฟรอสต์วูล์ฟ เจ้าต้องสืบให้รู้ว่าเกิดอะไรขึ้นกับพวกเขา\n\nค้นหาที่ทาวเวอร์พอยต์เวสต์และป้อมฟรอสต์วูล์ฟ นั่นคือจุดสุดท้ายที่ทราบว่าพวกเขาอยู่ จงค้นบริเวณเหล่านี้ให้ทั่ว" },
        progress = { "30:1073410746:1208316681", "มีอะไรที่ข้าอยากได้ยินบ้างไหม?" },
        completion = { "101:1796653094:1693577169", "เหลือเชื่อ! เจ้าปล่อยพวกเขาแล้วใช่ไหม? ใช่ไหม??? อย่างน้อยเราก็รู้แล้วว่าพวกเขาถูกขังที่ไหน" },
    },
    [7302] = { -- Fallen Sky Lords
        title = { "16:1698671758:1473981632", "จ้าวเวหาที่ร่วงหล่น" },
        objective = { "159:1870498513:1680536302", "สืบให้รู้ว่าเกิดอะไรขึ้นกับ Wing Commander Guse, Wing Commander Jeztor และ Wing Commander Mulverick เมื่อทำภารกิจสำเร็จให้กลับไปหา Commander Mulfort" },
        description = { "32:1381621425:1531486540 N 409:102156584:696179928", "กำลังสนับสนุนทางอากาศของเราพังยับ {name} ผู้บัญชาการฝูงบินถูกยิงตกเหนือดินแดนศัตรู เจ้าต้องสืบให้รู้ว่าเกิดอะไรขึ้นกับพวกเขา เราจะได้พยายามช่วยเหลือ!\n\nมีผู้เห็นกูสครั้งสุดท้ายกำลังบินเหนือบังเกอร์ไอซ์วิง หน่วยขี่รบของเจซทอร์ถูกพบใกล้โรงเลื่อยสตอร์มไพก์ ส่วนมัลเวอริก... เจ้าโง่บ้าบิ่นนั่นถูกเห็นตกใกล้บังเกอร์ดันบัลดาร์เหนือ\n\nนั่นคือข้อมูลทั้งหมดที่ข้ามี ออกไป! ค้นแต่ละบริเวณให้ทั่ว!" },
        progress = { "28:1821344956:1189046949", "สถานะการค้นหาเป็นอย่างไร ทหาร?" },
        completion = { "73:223265725:2133123100", "ทำได้ดี! ข้อมูลที่เจ้าได้มาจะมีค่ายิ่งต่อภารกิจของเรา" },
    },
    [7361] = { -- Favor Amongst the Darkspear
        title = { "27:1359361659:1129675282", "ความโปรดปรานในหมู่ดาร์กสเปียร์" },
        objective = { "172:145423390:2129650390", "คุณได้รับหน้าที่สังหารผู้เล่นฝ่ายตรงข้ามเผ่า Night Elf ใน Alterac Valley\n\nสังหาร Night Elf แล้วนำ Severed Night Elf Head กลับไปให้ Najak Hexxen ที่ Frostwolf Keep" },
        description = { "486:1114937740:897745862", "<นาจัคแยกเขี้ยว>\n\nก่อนไนต์เอลฟ์ถือกำเนิดก็มีโทรลล์อยู่แล้ว ไนต์เอลฟ์เกิดมาจากโทรลล์\n\nเราจะไม่ทนต่อการโจมตีกบฏของพวกมันต่อผู้คนข้า สแต็กเฮล์มมุ่งล้างเผ่าพันธุ์เรา ไม่ให้เหลือร่องรอยของผู้ให้กำเนิดเขากับพวก มันจะไม่มีวันเกิดขึ้น!\n\nทุกไนต์เอลฟ์ที่เจ้าฆ่าและตัดหัว นาจัคจะมอบความโปรดปรานในหมู่ดาร์กสเปียร์ให้ ข่าววีรกรรมของเจ้าจะกระจายไปทั่วคาลิมดอร์และอีสเทิร์นคิงดอมส์ ไปเดี๋ยวนี้ รับใช้ดาร์กสเปียร์!" },
        progress = { "66:1254453918:1025487727", "พวกมันคิดกำจัดเราหรือ? พวกมันต่างหากที่จะถูกกำจัด" },
        completion = { "N 58:1743191109:88152082", "{name} นี่เป็นเพียงหนึ่งในหลายพัน ถึงกระนั้นก็ทำได้ดี" },
        required = { [18142] = { "22:918739420:1119881530", "ศีรษะไนต์เอลฟ์ที่ถูกตัด" } },
        objectiveLabels = {
            item = { ["Severed Night Elf Head"] = "ศีรษะไนต์เอลฟ์ที่ถูกตัด" },
        },
    },
    [7362] = { -- Ally of the Tauren
        title = { "18:1050622639:1176521245", "พันธมิตรของทอเรน" },
        objective = { "163:999038687:737707869", "คุณได้รับหน้าที่สังหารผู้เล่นฝ่ายตรงข้ามเผ่า Gnome ใน Alterac Valley\n\nสังหาร Gnome แล้วนำ Tuft of Gnome Hair กลับไปให้ Ravak Grimtotem ที่ Frostwolf Keep" },
        description = { "442:1001590743:1921320438", "แม่เฒ่าอาวุโสส่งข้ามาเขตสงครามนี้เพื่อศึกษาเผ่าพันธุ์อื่น โดยเฉพาะรวบรวมตัวอย่างโนม มากาธาสนใจความอยู่รอดของพวกมันเป็นหลัก ใช่แล้ว แม้โนมจะอ่อนแอและตัวเล็กจนน่าสมเพช แต่ก็ทรหดอย่างยิ่งทั้งในและนอกการต่อสู้\n\nโชคดีสำหรับเจ้า ข้ากำลังหานักเลงมาทำตามประสงค์ของมากาธา นำกระจุกผมโนมกลับมาให้ข้า แล้วทอเรนจะรู้จักเจ้าในฐานะพันธมิตร" },
        progress = { "40:1368160795:1728677836 R 1:46:46", "ข้าไม่สนว่าผมมาจากไหน {race}" },
        completion = { "42:1263128838:1703235705 R 36:522838754:55023759", "ใช่ นี่เป็นโนมแน่นอน ทำได้ดี {race} แต่ยังมีงานต้องทำอีก" },
        required = { [18143] = { "18:766061693:753404973", "กระจุกผมของโนม" } },
        objectiveLabels = {
            item = { ["Tuft of Gnome Hair"] = "กระจุกผมของโนม" },
        },
    },
    [7363] = { -- The Human Condition
        title = { "19:1243118771:757941613", "ภาวะแห่งความเป็นมนุษย์" },
        objective = { "256:622018038:218754737", "คุณได้รับหน้าที่สังหารผู้เล่นฝ่ายตรงข้ามเผ่า Human ใน Alterac Valley\n\nสังหาร Human แล้วนำ Human Bone Chip กลับไปให้ Commander Louis Philips ผู้เดินอยู่ระหว่างแนวหน้ากับ Frostwolf Keep\n\nหนทางรักษาภาวะความเป็นมนุษย์ใกล้สำเร็จแล้ว!" },
        description = { "455:62131003:604278303", "มนุษย์น่ารังเกียจอย่างที่สุด\n\n<ผู้บัญชาการฟิลิปส์ทำหน้าบึ้ง>\n\nแม้ข้าจะเป็นทหารฟรอสต์วูล์ฟ แต่ก็ยังเป็นข้ารับใช้ซิลวานัส\n\nระหว่างประจำการ ข้ารับงานพิเศษให้หมอยามืดแห่งอันเดอร์ซิตี้\n\nข้าได้รับหน้าที่รวบรวมเศษกระดูกมนุษย์ เพื่อใช้รักษาภาวะความเป็นมนุษย์\n\nข้ามีอำนาจส่งต่องานนั้นให้ผู้ใต้บังคับบัญชา\n\nหาพวกมัน ฆ่า แล้วนำเศษกระดูกกลับมาให้ข้า" },
        progress = { "93:1324945866:1217363083", "ใช่ เป็นความจริง พี่น้องข้าเป็นมนุษย์ น่าอับอาย... เป็นรอยด่างบนประวัติที่แทบไร้ที่ติของข้า" },
        completion = { "172:445262230:188432307", "คงง่ายกว่าหากพวกมันยอมรับความเจ็บป่วย แล้วจำนนต่อสัมผัสเยียวยาของเจ้า แต่ก็คงสนุกน้อยลงด้วย ทำหน้าที่ต่อไป! เราจะรักษาพวกมัน ไม่ทางใดก็ทางหนึ่ง" },
        required = { [18144] = { "15:932108762:1774391343", "เศษกระดูกมนุษย์" } },
        objectiveLabels = {
            item = { ["Human Bone Chip"] = "เศษกระดูกมนุษย์" },
        },
    },
    [7364] = { -- Gnomeregan Bounty
        title = { "17:51145036:422429682", "ค่าหัวแห่งโนเมอเรแกน" },
        objective = { "151:832909495:1764291133", "คุณได้รับหน้าที่สังหารผู้เล่นฝ่ายตรงข้ามเผ่า Tauren ใน Alterac Valley\n\nสังหาร Tauren แล้วนำ Tauren Hoof กลับไปให้ Dirk Swindle ที่ Dun'Baldar" },
        description = { "351:828891158:1581520630 C 64:671052109:1482189551", "ไฮทิงเกอร์ส่งข้ามาสนามรบนี้ด้วยตนเอง เพื่อป้องกันพี่น้องโนมของเรา เราได้รับข่าวว่าทอเรนเจาะจงฆ่าโนม ที่เลวร้ายที่สุดคือพวกมันดึงกระจุกผมโนมอันงดงามจากศพผู้ล้มตาย ต้องหยุดความโหดร้ายเหล่านี้ เราต้องตอบโต้!\n\nข้าต้องการให้พวกมันเสียกีบ {class} นำกีบมาให้ข้า! แสดงตนว่าเป็นพันธมิตรของโนม" },
        progress = { "17:895650036:173032008 N 70:305553374:1321794671", "ทำให้พวกมันเดินกะเผลก {name} พวกมันต้องรู้ว่าชาวโนมไม่ยอมถูกข่มเหง!" },
        completion = { "44:960949620:244910363", "*เดิร์กโยนกีบไปบนกองด้านหลังตน*" },
    },
    [7365] = { -- Staghelm's Requiem
        title = { "18:1817353690:609333922", "บทไว้อาลัยของสแต็กเฮล์ม" },
        objective = { "154:1704589055:390853297", "คุณได้รับหน้าที่สังหารผู้เล่นฝ่ายตรงข้ามเผ่า Troll ใน Alterac Valley\n\nสังหาร Troll แล้วนำ Darkspear Troll Mojo กลับไปให้ Athramanis ที่ Dun'Baldar" },
        description = { "267:2028314453:328289729", "สแต็กเฮล์มออกคำสั่งแล้ว ต้องกำจัดโทรลล์ทั้งหมดในสนามรบ คำกล่าวอ้างเหลวไหลว่าพวกมันให้กำเนิดไนต์เอลฟ์ต้องได้รับการตอบโต้ด้วยกำลังและความชิงชังที่สมควร\n\nฆ่าพวกมันแล้วนำโมโจกลับมาให้ข้า ขอย้ำอีกครั้ง ข้าต้องการให้เจ้าขโมยโมโจของพวกมัน" },
        progress = { "38:87427737:673084835", "ข้ายังได้กลิ่นโทรลล์เหม็น ๆ อยู่เลย" },
        completion = { "11:1191658970:1224418299 N 32:26446050:372709877", "ขอบคุณ {name} อากาศบริสุทธิ์ขึ้นอีกนิดแล้ว" },
    },
    [7366] = { -- The Archbishop's Mercy
        title = { "22:1861203782:2108985953", "ความเมตตาของอาร์ชบิชอป" },
        objective = { "205:1868357739:560539447", "คุณได้รับหน้าที่สังหารผู้เล่นฝ่ายตรงข้ามเผ่า Forsaken ใน Alterac Valley\n\nสังหาร Forsaken แล้วนำ Forsaken Heart กลับไปให้ Commander Karl Philips ผู้เดินอยู่ระหว่างโรงเลื่อยกับเหมือง" },
        description = { "476:788755257:1280799667 N 1:33:33", "อาร์ชบิชอปเปี่ยมเมตตาไม่แพ้ปัญญา ช่างเป็นคนที่มองพวกน่าเวทนาเหล่านั้นด้วยความกรุณาได้...\n\n<ผู้บัญชาการฟิลิปส์ส่ายหน้าอย่างไม่เชื่อ>\n\nเมตตาเกินไป... มากเกินไปจริง ๆ\n\nอาร์ชบิชอปขอให้เราสงสารอันเดด และมอบความตายที่รวดเร็วถาวรให้พวกมัน เพื่อแสดงความเมตตายิ่งใหญ่นี้ เราต้องการเพียงหัวใจดำมืดที่เต็มไปด้วยโรค\n\nนำหัวใจฟอร์เซเคนมาให้ข้า เพื่อเผาตามพิธีที่มหาวิหารแห่งแสง รีบเข้า {name}!" },
        progress = { "71:1775358707:1646517613", "เบเนดิกตัส! ข้าเป็นเพียงจุดเล็ก ๆ ในเงาแห่งความยิ่งใหญ่ของท่าน จงสรรเสริญท่าน!" },
        completion = { "146:1572122247:125995201", "สรรเสริญเบเนดิกตัส! อีกดวงวิญญาณที่หลงทาง ใกล้ได้รับการช่วยให้รอดด้วยเปลวไฟร้อนขาวแห่งแสง!\n\nไปเถิด ทหารแห่งแสง! ยังมีอีกมากที่ต้องช่วย!" },
        required = { [18147] = { "14:1593498534:863261916", "หัวใจของฟอร์เซเคน" } },
        objectiveLabels = {
            item = { ["Forsaken Heart"] = "หัวใจของฟอร์เซเคน" },
        },
    },
    [7367] = { -- Defusing the Threat
        title = { "19:1165311718:680513070", "ขจัดภัยคุกคาม" },
        objective = { "119:553015932:2029299710", "ค้นหา Frostwolf Explosives Expert แล้วสังหารเขา เมื่อสำเร็จให้กลับไปหา Stormpike Explosives Expert" },
        description = { "62:65300437:33863645 C 399:1110153816:247835656", "ฟรอสต์วูล์ฟวางกับระเบิดไว้ทั้งแนวหน้าและฐาน {class} เจ้าต้องระวังทุกก้าวเมื่อบุกดินแดนศัตรู\n\nหากอยากโจมตีพวกมันอย่างได้ผล ต้องทำลายแหล่งผลิตอาวุธต่อต้านบุคคล ข้าหมายถึงผู้เชี่ยวชาญระเบิด หากฆ่าเขาได้ เจ้าจะปลดกับระเบิดอย่างปลอดภัย ตราบใดที่เขายังไม่กลับมา กับระเบิดก็จะไม่กลับมาเช่นกัน\n\nเจ้าคงพบเขาในหอคอยใกล้กองรักษาการณ์ไอซ์บลัด ขอให้โชคดี!" },
    },
    [7368] = { -- Defusing the Threat
        title = { "19:1165311718:680513070", "ขจัดภัยคุกคาม" },
        objective = { "119:1452817770:1764825007", "ค้นหา Stormpike Explosives Expert แล้วสังหารเขา เมื่อสำเร็จให้กลับไปหา Frostwolf Explosives Expert" },
        description = { "457:1932350426:603135457", "ข้ารู้เรื่องกับระเบิดทุกอย่าง เพราะข้าเป็นคนวางกับระเบิดทั้งหมดที่แนวหน้าของเรานี่เอง\n\nหากอยากจัดการทุ่นระเบิดสตอร์มไพก์ เพียงฆ่าผู้เชี่ยวชาญระเบิดของพวกมัน เจ้าคนแคระขี้ขลาดนั่นต้องซ่อนอยู่ในหอคอยแรกบนทุ่งแห่งความขัดแย้งแน่ กำจัดเขา แล้วกับระเบิดที่ถูกปลดจะไม่กลับมา\n\nหากฆ่าเขาได้ กลับมาบอกข้าที่นี่ด้วย ความดีไม่ควรไร้รางวัล" },
    },
    [7381] = { -- The Return of Korrak
        title = { "20:1433941951:1319165518", "การกลับมาของคอร์แร็ก" },
        objective = { "173:970751830:1171256295", "หาก Korrak the Bloodrager กลับมาที่ Field of Strife จงตามหาและสังหารเขา\n\nนำ Skull of Korrak กลับไปให้ Warmaster Laggrond ใน Hillsbrad Foothills" },
        description = { "459:1608410969:511555844", "แม้เป็นความจริงว่าคอร์แร็กถูกฆ่าแล้ว แต่ยังเหลือคำถามหนึ่ง เขาจะตายอยู่อย่างนั้นหรือไม่? โทรลล์ขึ้นชื่อเรื่องเวทเผ่าอันพิสดาร ข้าคงไม่แปลกใจหากผู้นำที่ล้มลงถูกปลุกจากความตายให้กลับมาปกครองเผ่าอีกครั้ง\n\nเจ้ารู้ว่าต้องทำอย่างไรหากเกิดเรื่องนั้น\n\n<วอร์มาสเตอร์ลากกรอนด์ใช้นิ้วชี้ปาดผ่านลำคอ>\n\nคราวนี้ข้าต้องการกะโหลกเขา คอยสังเกตให้ดี ทหาร\n\nเลิกแถว!" },
        required = { [18148] = { "15:1023743596:1692089412", "กะโหลกของคอร์แร็ก" } },
        objectiveLabels = {
            item = { ["Skull of Korrak"] = "กะโหลกของคอร์แร็ก" },
        },
    },
    [7382] = { -- Korrak the Everliving
        title = { "21:75572723:269528830", "คอร์แร็กผู้ไม่ยอมตาย" },
        objective = { "175:1505474288:895887876", "หาก Korrak the Bloodrager กลับมาที่ Field of Strife จงตามหาและสังหารเขา\n\nนำ Skull of Korrak กลับไปให้ Lieutenant Haggerdin ใน Hillsbrad Foothills" },
        description = { "232:553839443:2123629709 N 218:1058801391:1992181122", "เรื่องทั้งหมดนี้มีอะไรไม่ถูกต้องนัก... มีใครคิดเผาศพคอร์แร็กหรือยัง? โทรลล์พวกนั้นไม่หยุดทำทุกทางเพื่อฟื้นผู้นำที่ล้มลง อย่างที่อสูรคนเถื่อนผิวฟ้ามักทำ\n\nคอยสังเกตให้ดี {name} อย่าตกใจหากคอร์แร็กปรากฏตัวอย่างไม่คาดคิด หากเขากลับมา ข้าต้องการให้ประหาร และเผาศพให้เป็นเถ้า\n\nเพื่อให้แน่ใจ ตัดหัวแล้วนำกะโหลกมาให้ข้าก่อนจุดไฟเผาร่างไร้ชีวิตนั้น" },
        progress = { "37:1732783273:1198626219 C 68:1934094647:791254877", "เจ้าฆ่า Korra ผู้คลั่งโลหิตแล้วหรือ {class}? หน่วยสอดแนมรายงานว่าพบเขาแถวทุ่งแห่งความขัดแย้ง" },
        completion = { "11:534428891:784080240 N 121:1390471917:261084810", "ทำได้ดี {name} แม้เวทมนตร์ทรงพลังที่สุดก็ฟื้นคอร์แร็กไม่ได้แล้ว ทหาร เจ้ากำจัดภัยคุกคามใหญ่จากหุบเขาอัลเทอแรคได้" },
        required = { [18148] = { "15:1023743596:1692089412", "กะโหลกของคอร์แร็ก" } },
        objectiveLabels = {
            item = { ["Skull of Korrak"] = "กะโหลกของคอร์แร็ก" },
        },
    },
    [7385] = { -- A Gallon of Blood
        title = { "17:639877743:2127410916", "เลือดหนึ่งแกลลอน" },
        progress = { "136:859683467:1164464975 N 1:46:46", "เจ้ามีทางเลือกมอบเลือดจากศัตรูในปริมาณมากขึ้น ข้ายินดีรับเครื่องบูชาขนาดแกลลอน {name}" },
        completion = { "214:705518469:1266480827", "เลือดของศัตรูหลั่งไหลแล้ว ข้าจะผสมเลือดนี้เข้ากับส่วนที่รวบรวมไว้ เมื่อเครื่องบูชาครบถ้วน จ้าวน้ำแข็งจะแสดงความพิโรธทั้งหมดของเผ่าฟรอสต์วูล์ฟให้เจ้าพวกสุนัขสตอร์มไพก์เห็น!" },
        description = { "136:859683467:1164464975 N 1:46:46", "เจ้ามีทางเลือกมอบเลือดจากศัตรูในปริมาณมากขึ้น ข้ายินดีรับเครื่องบูชาขนาดแกลลอน {name}" },
        required = { [17306] = { "25:1075847306:1748124349", "เลือดทหารสตอร์มไพก์" } },
        objectiveLabels = {
            item = { ["Stormpike Soldier's Blood"] = "เลือดทหารสตอร์มไพก์" },
        },
    },
    [7386] = { -- Crystal Cluster
        title = { "15:1313859987:191945155", "กลุ่มคริสตัล" },
        progress = { "231:279627427:1222428419 N 1:46:46", "บางครั้งเจ้าอาจต้องตรึงกำลังรบอยู่นานหลายวันหรือหลายสัปดาห์ ระหว่างการปฏิบัติการยาวนานนั้น เจ้าอาจรวบรวมคริสตัลพายุของฟรอสต์วูล์ฟได้เป็นกลุ่มใหญ่\n\nสภารับเครื่องบูชาเช่นนั้น {name}" },
        completion = { "11:534428891:784080240 N 212:1375421088:1449340179", "ทำได้ดี {name} ข้าจะใช้พลังเครื่องรางเหล่านี้เสริมเวทมนตร์ที่รวบรวมไว้แล้ว เมื่อสะสมพลังได้พอ ข้าจะรวมพลังงานทั้งหมดและเรียกจ้าวพงไพรมาช่วยภารกิจของเรา" },
        description = { "231:279627427:1222428419 N 1:46:46", "บางครั้งเจ้าอาจต้องตรึงกำลังรบอยู่นานหลายวันหรือหลายสัปดาห์ ระหว่างการปฏิบัติการยาวนานนั้น เจ้าอาจรวบรวมคริสตัลพายุของฟรอสต์วูล์ฟได้เป็นกลุ่มใหญ่\n\nสภารับเครื่องบูชาเช่นนั้น {name}" },
        required = { [17423] = { "13:1802824770:857773564", "ผลึกพายุ" } },
        objectiveLabels = {
            item = { ["Storm Crystal"] = "ผลึกพายุ" },
        },
    },
    [7401] = { -- Wanted: DWARVES!
        title = { "16:1214861941:222029738", "ต้องการ:คนแคระ!" },
        objective = { "182:538685197:471021163", "คุณได้รับหน้าที่สังหารผู้เล่นฝ่ายตรงข้ามเผ่า Dwarf ใน Alterac Valley\n\nสังหาร Dwarf และดึงกระดูกสันหลังออก นำ Dwarf Spine ไปให้ Sergeant Yazra Bloodsnarl ที่ Frostwolf Keep" },
        description = { "344:1974366319:179281453", "ตามคำสั่งของจ่ายาซรา บลัดสนาร์ล ให้ฆ่าคนแคระทุกคนในสนามรบทันทีที่เห็น\n\nหากเจ้าสังหารคนแคระในการต่อสู้ จงดึงกระดูกสันหลังออก ทิ้งกองเหม็นเน่าไร้กระดูกสันหลังไว้เตือนทุกผู้ที่กล้าต่อต้านพลังฟรอสต์วูล์ฟ\n\nกลับไปหาจ่ายาซรา บลัดสนาร์ลพร้อมหลักฐานวีรกรรมของเจ้า" },
        progress = { "35:937912201:212231818", "ข้าค้าความย้อนแย้งแบบขายส่ง ทหาร" },
        completion = { "55:2071556172:1303385946 C 94:547563070:1083401980", "ตอนนี้เจ้ามีสิทธิ์ถล่มคนแคระทีละเป็นโหลแล้ว {class}!\n\n<ยาซรามองไกลออกไปครู่หนึ่ง>\n\nไม่มีวันลืมการดึงกระดูกสันหลังครั้งแรกหรอก..." },
    },
    [7402] = { -- Wanted: ORCS!
        title = { "13:1584892158:1489731001", "ต้องการ:ออร์ค!" },
        objective = { "158:1632594597:262940344", "คุณได้รับหน้าที่สังหารผู้เล่นฝ่ายตรงข้ามเผ่า Orc ใน Alterac Valley\n\nสังหาร Orc แล้วนำ Orc Tooth กลับไปให้ Corporal Noreg Stormpike ที่ Dun Baldar" },
        description = { "310:1539661336:1291914617", "ตามคำสั่งของสิบตรีโนเรก สตอร์มไพก์ ทหารสตอร์มไพก์ที่พร้อมรบทุกนายต้องสังหารออร์คฝ่ายตรงข้ามที่พบในสนามรบ\n\nทหารต้องถอนเขี้ยวหรือฟันจากปากศัตรู แล้วแสดงฟันดังกล่าวเป็นหลักฐานความสำเร็จ\n\nสวมถุงมือป้องกันด้วย" },
        progress = { "38:1739959746:186397926", "ต้องใช้ที่หนีบช่วยดึงฟันออกไหม?" },
        completion = { "6:2014770050:1830635039 N 27:381008729:1967483861", "ดี {name} ข้าคาดว่าจะมีหนูตัวเล็ก ๆ" },
    },
    [7421] = { -- Darkspear Defense
        title = { "17:840398046:1820213492", "ป้องกันดาร์กสเปียร์" },
        progress = { "66:1254453918:1025487727", "พวกมันคิดกำจัดเราหรือ? พวกมันต่างหากที่จะถูกกำจัด" },
        completion = { "N 58:1743191109:88152082", "{name} นี่เป็นเพียงหนึ่งในหลายพัน ถึงกระนั้นก็ทำได้ดี" },
        description = { "43:1539161457:155437642 N 44:1373429128:1432249540", "จงปกป้องเผ่า Darkspear ต่อไป {name} สังหารพวกมันให้หมดแล้วนำหัวของพวกมันไปให้ Najak" },
    },
    [7422] = { -- Tuft it Out
        title = { "11:496237371:1685708841", "กระจุกผมวัดใจ" },
        progress = { "40:1368160795:1728677836 R 1:46:46", "ข้าไม่สนว่าผมมาจากไหน {race}" },
        completion = { "42:1263128838:1703235705 R 36:522838754:55023759", "ใช่ นี่เป็นโนมแน่นอน ทำได้ดี {race} แต่ยังมีงานต้องทำอีก" },
        description = { "285:2096566616:1254325861", "ดูเหมือน High Tinkerer จะล่วงรู้ว่าเราเข้าไปมีส่วนใน Alterac Valley เขาสั่งให้คนของตัวเองไปตัดกีบชาวทอเรนเพื่อแก้แค้น พวกโนมเจ้าเล่ห์กว่าที่ข้าเคยคิดไว้เสียอีก เราต้องศึกษาเรื่องนี้ต่อ! ต้องใช้กระจุกขนเพิ่มอีก" },
    },
    [7423] = { -- I've Got A Fever For More Bone Chips
        title = { "36:819782523:179055254", "คลั่งอยากได้เศษกระดูกเพิ่ม" },
        progress = { "93:1324945866:1217363083", "ใช่ เป็นความจริง พี่น้องข้าเป็นมนุษย์ น่าอับอาย... เป็นรอยด่างบนประวัติที่แทบไร้ที่ติของข้า" },
        completion = { "172:445262230:188432307", "คงง่ายกว่าหากพวกมันยอมรับความเจ็บป่วย แล้วจำนนต่อสัมผัสเยียวยาของเจ้า แต่ก็คงสนุกน้อยลงด้วย ทำหน้าที่ต่อไป! เราจะรักษาพวกมัน ไม่ทางใดก็ทางหนึ่ง" },
        description = { "38:1071049002:223368870 N 220:1190830912:2016127536", "เจ้าทำสิ่งดี ๆ ให้มนุษย์พวกนี้แล้ว {name} จงใช้พลังเยียวยาของเจ้าช่วยเผ่าพันธุ์ที่ด้อยวาสนากว่าเราต่อไป\n\nเศษกระดูกมนุษย์แต่ละชิ้นอาจช่วยให้ดวงวิญญาณอีกดวงรอดพ้นจากชีวิตอันสิ้นหวังในหมู่คนโสมมที่ถูกกดขี่" },
    },
    [7424] = { -- What the Hoof?
        title = { "14:1814215910:1972526417", "กีบอะไรกันนี่?" },
        progress = { "17:895650036:173032008 N 70:305553374:1321794671", "ทำให้พวกมันเดินกะเผลก {name} พวกมันต้องรู้ว่าชาวโนมไม่ยอมถูกข่มเหง!" },
