    },
    [7425] = { -- Staghelm's Mojo Jamboree
        title = { "24:1761789825:565792038", "งานชุมนุมโมโจของสแต็กเฮล์ม" },
        progress = { "38:87427737:673084835", "ข้ายังได้กลิ่นโทรลล์เหม็น ๆ อยู่เลย" },
        completion = { "11:1191658970:1224418299 N 32:26446050:372709877", "ขอบคุณ {name} อากาศบริสุทธิ์ขึ้นอีกนิดแล้ว" },
        description = { "137:58668638:1100614036", "Staghelm จะยังไม่พอใจจนกว่าโทรลล์ทุกตัวจะ... เงียบเสียงลง จงเก็บ Mojo จากซากที่เต็มไปด้วยโรคของพวกมันต่อไป" },
    },
    [7426] = { -- One Man's Love
        title = { "14:1981535:1097405969", "รักของชายคนหนึ่ง" },
        progress = { "71:1775358707:1646517613", "เบเนดิกตัส! ข้าเป็นเพียงจุดเล็ก ๆ ในเงาแห่งความยิ่งใหญ่ของท่าน จงสรรเสริญท่าน!" },
        completion = { "146:1572122247:125995201", "สรรเสริญเบเนดิกตัส! อีกดวงวิญญาณที่หลงทาง ใกล้ได้รับการช่วยให้รอดด้วยเปลวไฟร้อนขาวแห่งแสง!\n\nไปเถิด ทหารแห่งแสง! ยังมีอีกมากที่ต้องช่วย!" },
        description = { "157:229273001:282509187 N 90:397746467:2068689558", "<ดูเหมือน Commander Philips กำลังร้องไห้>\n\nมนุษย์ส่วนใหญ่ไม่มีทางเมตตาได้ถึงเพียงนี้ Benedictus คือปาฏิหาริย์ที่มีชีวิต!\n\nจงเผยแผ่ความเมตตาของเขาต่อไป {name} ยังมีหัวใจเน่า ๆ ของพวก Forsaken ให้เผาอีกตั้งมากมาย อย่าทำให้เขาผิดหวัง แล้วก็อย่าทำให้ข้าผิดหวังด้วย" },
    },
    [7427] = { -- Wanted: MORE DWARVES!
        title = { "21:192674232:597906175", "ต้องการ:คนแคระเพิ่ม!" },
        progress = { "35:937912201:212231818", "ข้าค้าความย้อนแย้งแบบขายส่ง ทหาร" },
        completion = { "55:2071556172:1303385946 C 94:547563070:1083401980", "ตอนนี้เจ้ามีสิทธิ์ถล่มคนแคระทีละเป็นโหลแล้ว {class}!\n\n<ยาซรามองไกลออกไปครู่หนึ่ง>\n\nไม่มีวันลืมการดึงกระดูกสันหลังครั้งแรกหรอก..." },
        description = { "238:1816526578:244000449", "เมื่อได้กระดูกสันหลังมากพอ ข้าจะบรรทุกมันขึ้นเครื่องยิงหินของเราเครื่องหนึ่ง แล้วยิงพวกมันเข้าไปใน Dun Baldar\n\nพวก Stormpike จะถูกฝังอยู่ใต้กองซากชวนสยอง ทั้งความตายและชิ้นส่วนศพ ข้าแทบรอไม่ไหวแล้ว\n\nเราต้องการกระดูกสันหลังอีก" },
    },
    [7428] = { -- Wanted: MORE ORCS!
        title = { "18:701235093:1840379652", "ต้องการ:ออร์คเพิ่ม!" },
        progress = { "38:1739959746:186397926", "ต้องใช้ที่หนีบช่วยดึงฟันออกไหม?" },
        completion = { "6:2014770050:1830635039 N 27:381008729:1967483861", "ดี {name} ข้าคาดว่าจะมีหนูตัวเล็ก ๆ" },
        description = { "32:413363441:305206972 N 196:1610156897:227395757", "พวกป่าเถื่อนนี้ไม่มีวันเข็ด {name} จงฟันพวกออร์คฝ่ายตรงข้ามต่อไปให้เต็มที่ พวก Frostwolf จะได้รู้ซึ้งว่าความเจ็บปวดคืออะไร ส่วนพวกโนมก็จะมีผมหนาขึ้น\n\nเราเรียกว่าได้ประโยชน์ทั้งสองฝ่าย" },
    },
    [8271] = { -- Hero of the Stormpike
        title = { "21:2107402491:228728600", "วีรชนแห่งสตอร์มไพก์" },
        completion = { "104:755517564:66321416", "ในฐานะวีรชนแห่งสตอร์มไพก์ เจ้าเลือกของได้หนึ่งชิ้นจากสมบัติที่เพิ่งปล้... เอ่อ กู้คืนมาเหล่านี้" },
    },
    [8272] = { -- Hero of the Frostwolf
        title = { "21:878390328:2097301331", "วีรชนแห่งฟรอสต์วูล์ฟ" },
        completion = { "18:403721352:66196506 N 156:1461762294:905694841", "รู้สึกอย่างไร {name}? รู้สึกอย่างไรที่บดขยี้ศัตรูและเห็นแนวรบพวกมันแตกพ่าย? รู้สึกดีใช่ไหม?\n\nเจ้าควรได้รับรางวัลสำหรับวีรกรรมนี้ ทหาร" },
    },
    [8369] = { -- Invaders of Alterac Valley
        title = { "26:446500627:759365783", "ผู้รุกรานหุบเขาอัลเทอแรค" },
        objective = { "86:1971095831:1931924465", "นำ Alterac Valley Marks of Honor 3 ชิ้นไปให้ Horde Warbringer ด้านนอกสนามรบ" },
        description = { "11:1081862814:531876058 N 338:577389136:500360875", "ฟังให้ดี {name} ไม่ว่าเจ้าจะได้ยินอะไรเกี่ยวกับการรบที่โหมในหุบเขาอัลเทอแรค ความจริงหนึ่งยังคงอยู่ คณะสำรวจสตอร์มไพก์รุกรานดินแดนฟรอสต์วูล์ฟ วันที่เรายอมให้อัลไลแอนซ์บุกดินแดนฮอร์ดโดยไม่ตอบโต้อย่างแข็งกร้าว คือวันที่ข้าจะแขวนขวานและใช้ชีวิตที่เหลืออย่างอับอาย จงออกไปขับไล่ผู้รุกราน!" },
        progress = { "102:1176883524:903105477", "เจ้ามีข่าวใดจากดินแดนฟรอสต์วูล์ฟ? ศึกชิงหุบเขาอัลเทอแรคเป็นอย่างไร?" },
        completion = { "109:843524335:1198234555", "เจ้าแสดงความกล้าหาญอย่างยิ่งในการปกป้องดินแดนของเราที่หุบเขาอัลเทอแรค! ข้าจะรายงานวีรกรรมให้ผู้บังคับบัญชาทราบ" },
        required = { [20560] = { "28:1124473597:1604635920", "เหรียญเกียรติยศ Alterac Valley" } },
        objectiveLabels = {
            item = { ["Alterac Valley Mark of Honor"] = "เหรียญเกียรติยศ Alterac Valley" },
        },
    },
    [8375] = { -- Remember Alterac Valley!
        title = { "24:1959765703:1216220420", "จดจำหุบเขาอัลเทอแรค!" },
        objective = { "97:921531810:540502510", "นำ Alterac Valley Marks of Honor 3 ชิ้นไปให้ Alliance Brigadier General ด้านนอกสนามรบ" },
        description = { "26:1910118925:997802007 N 390:619706765:263925400 C 66:1554478062:690540415", "อย่าเข้าใจผิด {name} ฮอร์ดพูดถูกที่บอกว่าหุบเขาอัลเทอแรคเป็นดินแดนฟรอสต์วูล์ฟ\n\nคณะสำรวจสตอร์มไพก์มาถึงในฐานะผู้มาเยือนอย่างสันติ เพื่อค้นหาแร่และโบราณวัตถุ แต่ฟรอสต์วูล์ฟตอบโต้ด้วยการรุกรานที่โหดร้ายป่าเถื่อนที่สุดเท่าที่อัลไลแอนซ์เคยพบ\n\nอย่าให้เราลืมคนแคระผู้กล้าที่ตายในการจู่โจมขี้ขลาดโดยไม่ประกาศนั้น ไปได้แล้ว {class} ทำหน้าที่ของเจ้าในศึกชิงหุบเขาอัลเทอแรค เพื่ออัลไลแอนซ์!" },
        progress = { "24:404589780:2127106192 N 1:63:63", "เจ้ามีข่าวอะไรมาบ้าง {name}?" },
        completion = { "23:61033401:1246534213 N 74:807239492:1441113325", "เจ้าทำหน้าที่แล้ว {name} อัลไลแอนซ์จะไม่ปล่อยให้การกระทำป่าเถื่อนของฮอร์ดไร้การตอบโต้!" },
        required = { [20560] = { "28:1124473597:1604635920", "เหรียญเกียรติยศ Alterac Valley" } },
        objectiveLabels = {
            item = { ["Alterac Valley Mark of Honor"] = "เหรียญเกียรติยศ Alterac Valley" },
        },
    },
    [8383] = { -- Remember Alterac Valley!
        title = { "24:1959765703:1216220420", "จดจำหุบเขาอัลเทอแรค!" },
        progress = { "39:302573089:1620097286 N 38:482651401:1412628429 N 1:63:63", "การรบในหุบเขาอัลเทอแรคยังโหมอยู่ {name}! ช่วงนี้เจ้าทำหน้าที่ของตนแล้วหรือยัง {name}?" },
        completion = { "36:1596301678:761865481 N 66:1108689058:682984340", "เจ้ายังคงสร้างเกียรติแก่อัลไลแอนซ์ {name} หากเราทุ่มเทต่อไป ฮอร์ดจะถูกบดขยี้ในไม่ช้า" },
        description = { "39:302573089:1620097286 N 38:482651401:1412628429 N 1:63:63", "การรบในหุบเขาอัลเทอแรคยังโหมอยู่ {name}! ช่วงนี้เจ้าทำหน้าที่ของตนแล้วหรือยัง {name}?" },
        objective = { "97:921531810:540502510", "นำ Alterac Valley Mark of Honor 3 ชิ้นไปให้ Alliance Brigadier General ที่อยู่นอกสนามรบ" },
        required = { [20560] = { "28:1124473597:1604635920", "เหรียญเกียรติยศ Alterac Valley" } },
        objectiveLabels = {
            item = { ["Alterac Valley Mark of Honor"] = "เหรียญเกียรติยศ Alterac Valley" },
        },
    },
    [8387] = { -- Invaders of Alterac Valley
        title = { "26:446500627:759365783", "ผู้รุกรานหุบเขาอัลเทอแรค" },
        progress = { "128:1081266850:1225939963 N 1:33:33", "ศึกชิงอัลเทอแรคยังโหมอยู่! เจ้าต้องกลับหุบเขาอัลเทอแรค แล้วขับไล่ผู้รุกรานออกจากดินแดนฟรอสต์วูล์ฟอีกครั้ง {name}!" },
        completion = { "11:354343371:1318038540 N 87:302259167:374313296", "ทำได้ดี {name}! เจ้าควรภูมิใจในตนเอง ต้องขับผู้รุกรานอัลไลแอนซ์ออกจากอัลเทอแรค!" },
        description = { "128:1081266850:1225939963 N 1:33:33", "ศึกชิงอัลเทอแรคยังโหมอยู่! เจ้าต้องกลับหุบเขาอัลเทอแรค แล้วขับไล่ผู้รุกรานออกจากดินแดนฟรอสต์วูล์ฟอีกครั้ง {name}!" },
        objective = { "86:1971095831:1931924465", "นำ Alterac Valley Mark of Honor 3 ชิ้นไปให้ Horde Warbringer ที่อยู่นอกสนามรบ" },
        required = { [20560] = { "28:1124473597:1604635920", "เหรียญเกียรติยศ Alterac Valley" } },
        objectiveLabels = {
            item = { ["Alterac Valley Mark of Honor"] = "เหรียญเกียรติยศ Alterac Valley" },
        },
    },
    [99] = { -- Arugal's Folly
        title = { "14:411206350:1668572509", "ความเขลาของอารูกัล" },
        objective = { "63:2089412981:138965969", "นำ Pyrewood Shackles 6 ชิ้นไปให้ Dalar Dawnweaver ที่ Sepulcher" },
        description = { "494:143709150:1502627108 N 1:46:46", "ยิ่งข้าเข้าใจเวทมนตร์ของอารูกัลมากขึ้น ข้าก็ยิ่งดูแคลนเจ้าโง่ผู้น่าสมเพชนั่น ข้าใกล้จะวิจัยสิ่งที่มันเรียกว่ายารักษาสำเร็จแล้ว\n\nความรู้ของข้าจะสมบูรณ์เมื่อรู้ว่ามนตร์ชนิดใดทำให้เกิดพฤติกรรมประหลาดในหมู่บ้านไพร์วูด ยามกลางวัน ชาวบ้านดูเป็นมนุษย์ แต่เมื่ออาทิตย์ลับฟ้า พวกเขากลับกลายเป็นวอร์เกนมูนเรจ\n\nข้าต้องดึงพลังจากเครื่องพันธนาการลงอาคมที่อารูกัลใส่ไว้กับพวกเขา นำ Pyrewood Shackles ลงอาคมหกชิ้นมาให้ข้า {name}" },
        progress = { "44:2067367183:1163960613 N 1:63:63", "เจ้าได้ Pyrewood Shackles มาแล้วหรือยัง {name}?" },
        completion = { "146:1046244923:985158274 N 1:46:46", "ความมุ่งมั่นของเจ้าน่าชื่นชม ความรู้ที่เจ้าช่วยข้ารวบรวมจะทำให้อารูกัลพ่ายแพ้ และเวทมนตร์อันบุ่มบ่ามของมันจะถูกลบล้าง ขอชื่นชมเจ้า {name}" },
        required = { [3218] = { "16:781997927:1550845795", "โซ่ตรวน Pyrewood" } },
        steps = { { "16:781997927:1550845795", "โซ่ตรวน Pyrewood" } },
    },
    [421] = { -- Prove Your Worth
        title = { "16:2073724025:221506879", "พิสูจน์คุณค่าของเจ้า" },
        objective = { "75:9843748:919825591", "Dalar Dawnweaver ที่ Sepulcher ต้องการให้เจ้าฆ่า Moonrage Whitescalp 5 ตัว" },
        description = { "490:512406089:1900076626", "เลดี้ซิลวานัสมอบหมายให้วาริมาทรัสพิชิตดินแดนมนุษย์และคนแคระทางใต้\n\nแต่เจ้าโง่อารูกัล จอมลวงโลกแห่งดาลารันที่บัดนี้กลายเป็นสัตว์ต้องสาปแห่งปราสาทชาโดว์แฟง กลับปล่อยให้เวทมนตร์อันบุ่มบ่ามของมันทำลายป่าซิลเวอร์ไพน์ ซึ่งเป็นฐานยุทธศาสตร์สำคัญ\n\nข้าต้องการผู้ชำนาญการต่อสู้มาช่วยจัดการความวุ่นวายที่อารูกัลก่อไว้ พิสูจน์ตนด้วยการฆ่า Moonrage Whitescalp 5 ตัว สัตว์น่าสังเวชพวกนี้มักอยู่ข้างถนน ลงไปตามเนินด้านล่าง" },
        progress = { "163:1831702399:67978515", "หากอยากพิสูจน์ตนต่อข้า เจ้าต้องฆ่า Moonrage Whitescalp 5 ตัว ทำให้สำเร็จ แล้วข้าจะมอบหมายงานที่คู่ควรกับฝีมือเจ้ามากกว่านี้" },
        completion = { "25:48595661:1122251451 C 115:81849098:1329663174", "เจ้ารับใช้ข้าได้ดี {class} ข้าเห็นชัดว่าเจ้าจะเป็นผู้ช่วยที่มีค่าในการเตรียมกำจัดคำสาปของอารูกัลออกจากป่าซิลเวอร์ไพน์" },
        objectiveLabels = {
            monster = { ["Moonrage Whitescalp slain"] = "ปราบ Moonrage ขนหัวขาว" },
        },
    },
    [422] = { -- Arugal's Folly
        title = { "14:411206350:1668572509", "ความเขลาของอารูกัล" },
        objective = { "68:1650141652:1203009103", "นำ Remedy of Arugal กลับมาให้ Dalar Dawnweaver ที่ Sepulcher" },
        description = { "501:2050454407:1225926406", "ข้าไม่เข้าใจว่าอารูกัลได้รับการยอมรับจากคิรินทอร์ได้อย่างไร ความรู้ด้านการร่ายเวทของมันดูตื้นเขินจนมองทะลุได้ไม่ต่างจากลูกแก้วกลวง\n\nสิ่งสำคัญตอนนี้คือเรียนรู้ให้แน่ชัดว่าอารูกัลใช้เวทมนตร์ใด ข้าจะได้ใช้มันย้อนเล่นงานและยึดป่าซิลเวอร์ไพน์ให้เลดี้แห่งความมืด\n\nตอนแรกอารูกัลพักอยู่ที่ไร่ข้าวสาลีทางเหนือของสะพาน เดธสตอล์กเกอร์คนหนึ่งรายงานว่าเห็นตำราเวท แต่เอากลับมาไม่ได้ จงนำบทเวทที่เขียนชื่อว่า Remedy of Arugal ในตำราเหล่านั้นมาให้ข้า" },
        progress = { "45:952852355:908459363 C 127:1263977214:495507897", "ก่อนที่ข้าจะรู้ว่าเรากำลังรับมือกับอะไร {class} ข้าต้องศึกษาบทเวทที่เรียกว่า Remedy of Arugal นำมาให้ข้าเดี๋ยวนี้ มิฉะนั้นข้าคงต้องหาผู้รับใช้ที่คู่ควรกว่านี้" },
        completion = { "48:1836060546:336316952 C 124:1031099377:766647123", "นี่คือบทเวทที่ข้าตามหาพอดี {class} หากความทุ่มเทต่ออุดมการณ์ของเลดี้แห่งความมืดของเจ้าไม่สั่นคลอน เจ้าจะมีอนาคตอีกไกลในหมู่ฟอร์เซเคน" },
        required = { [3155] = { "16:322525632:2129197522", "ยารักษาของ Arugal" } },
        steps = { { "16:322525632:2129197522", "ยารักษาของ Arugal" } },
    },
    [423] = { -- Arugal's Folly
        title = { "14:411206350:1668572509", "ความเขลาของอารูกัล" },
        objective = { "86:1831465200:786262626", "นำ Glutton Shackles 6 ชิ้นและ Darksoul Shackles 3 ชิ้นไปให้ Dalar Dawnweaver ที่ Sepulcher" },
        description = { "489:1660169117:921615638", "หลังตรวจผลงานของอารูกัล ข้อสงสัยที่เลวร้ายที่สุดของข้าก็เป็นจริง เจ้านักเวทกระจอกนั่นไม่มีคุณสมบัติพอจะล้างกระโถนในดาลารันด้วยซ้ำ นับประสาอะไรกับการเป็นตัวแทนคิรินทอร์ในยามวิกฤต พวกโง่เอ๊ย!\n\nอารูกัลใช้สิ่งของลงอาคมเสริมเวทมนตร์อันอ่อนด้อยของตน ข้าต้องตรวจสิ่งของเหล่านี้ด้วยตัวเอง ออกไปฆ่า Moonrage Glutton และ Moonrage Darksoul จนเก็บเครื่องพันธนาการลงอาคมของพวกมันได้พอสำหรับงานวิจัย มีผู้พบสัตว์ชั่วร้ายเหล่านี้ทางเหนือและตะวันออก" },
        progress = { "228:1081527114:490492590", "ข้าต้องใช้ Glutton Shackles 6 ชิ้นและ Darksoul Shackles 3 ชิ้น จึงจะประเมินสถานการณ์และวางวิธีจัดการอารูกัลอย่างเด็ดขาดได้ จงทำตามคำสั่ง ฆ่า Moonrage Glutton และ Moonrage Darksoul จนได้สิ่งที่ข้าต้องการ" },
        completion = { "169:126659768:578597438 C 1:46:46", "หวังว่าข้าจะดึงพลังจากตัวอย่างเพียงเท่านี้ได้มากพอ บางทีข้าน่าจะให้เจ้าเก็บเครื่องพันธนาการมาอีก\n\nถึงอย่างไร เจ้าก็แสดงฝีมือได้ดีในการรวบรวมสิ่งเหล่านี้ {class}" },
        required = { [3156] = { "15:1180279926:1864039023", "โซ่ตรวนของ Glutton" }, [3157] = { "16:1498494338:1243825268", "โซ่ตรวนของ Darksoul" } },
        steps = { { "15:1180279926:1864039023", "โซ่ตรวนของ Glutton" }, { "16:1498494338:1243825268", "โซ่ตรวนของ Darksoul" } },
    },
    [424] = { -- Arugal's Folly
        title = { "14:411206350:1668572509", "ความเขลาของอารูกัล" },
        objective = { "78:1068949446:127400675", "ฆ่า Grimson the Pale แล้วนำศีรษะของเขาไปให้ Dalar Dawnweaver ที่ Sepulcher" },
        description = { "494:1739680656:2099973010", "การเปิดเผยความลับดำมืดของมนตร์ที่อารูกัลใช้คงใช้เวลานานกว่าที่ข้าคิดจริง ๆ\n\nระหว่างนี้ ข้าต้องการให้เจ้าจัดการปัญหาเล็กน้อยที่ดาร์กสตอล์กเกอร์ของเราพบ ดูเหมือนอารูกัลปล่อยให้เวทมนตร์แพร่ไปถึงเหมืองดีปเอเล็มบนเนินเขาทางตะวันออกเฉียงใต้\n\nเหมืองนั้นจะเป็นแหล่งทรัพยากรสำคัญสำหรับการรุกของวาริมาทรัส\n\nข้าต้องการให้เจ้าตัดศีรษะ Grimson the Pale หัวหน้าคนงานเหมืองที่แปดเปื้อน เมื่อเขาตาย เหมืองจะเป็นของเรา" },
        progress = { "90:1038305814:182427874", "Grimson the Pale ถูกสังหารแล้วหรือยัง? วาริมาทรัสคงไม่พอใจหากเราเพิกเฉยต่อคำสั่งของเขา" },
        completion = { "122:137310450:1360230022", "ยอดเยี่ยมที่สุด เหมืองจะให้ทรัพยากรชั้นดีแก่กองกำลังของเรา ขณะที่เราขยายอำนาจไปทั่วซิลเวอร์ไพน์และเข้าสู่อาเซรอธ" },
        required = { [3634] = { "15:1572533857:1640741416", "ศีรษะของ Grimson" } },
        steps = { { "15:1572533857:1640741416", "ศีรษะของ Grimson" } },
    },
    [425] = { -- Ivar the Foul
        title = { "13:884452109:1773757749", "ไอวาร์ผู้โสมม" },
        objective = { "75:1817837293:1422691546", "ฆ่า Ivar the Foul แล้วนำ Ivar's Head ไปให้ Rane Yorick ที่ Ivar Patch" },
        description = { "445:407792217:832441728", "ควินน์พี่น้องของข้ากับข้าได้รับหน้าที่ลาดตระเวนป่าซิลเวอร์ไพน์ แล้วรายงานต่อไฮเอ็กเซคิวเตอร์แฮเดร็ก แต่เราไปได้ไม่ไกล ระหว่างผ่านไร่นี้ เราถูกกูลไอวาร์ผู้โสมมโจมตี\n\nเราหนีไอวาร์มาได้ แต่ควินน์ถูกมันขย้ำอย่างหนัก เขากำลังฟื้นตัวด้วยยาที่เจ้าให้ แต่ไอวาร์อาจกลับมาก่อนเขาหายดี\n\nฆ่าไอวาร์เพื่อให้ควินน์มีเวลารักษาตัว ปกติมันอยู่ในโรงนาตรงโน้น คอยจังหวะที่ข้าเผลอ" },
        progress = { "101:1269662382:14889547", "เจ้าฆ่าไอวาร์ผู้โสมมแล้วหรือยัง? หากไม่ยอมทำเพื่อข้ากับพี่น้องของข้า ก็จงทำเพื่อฟอร์เซเคน" },
        completion = { "38:1280204461:875613732 N 62:1424923484:1430116916", "อา ขอบใจ เจ้าทำให้ข้าซาบซึ้ง {name}\n\nข้าจะกล่าวถึงเจ้าในรายงานที่ส่งให้ผู้บังคับบัญชาด้วย" },
        required = { [3621] = { "11:1101423721:220320110", "ศีรษะของ Ivar" } },
        steps = { { "11:1101423721:220320110", "ศีรษะของ Ivar" } },
    },
    [428] = { -- Lost Deathstalkers
        title = { "18:1369708849:232036725", "เดธสตอล์กเกอร์ที่หายไป" },
        objective = { "45:20666050:1591700559", "ตามหาเดธสตอล์กเกอร์ Quinn และ Rane Yorick" },
        description = { "387:2053719378:1224777327", "เมื่อสองสัปดาห์ก่อน เดธสตอล์กเกอร์ของเราสองคน เรนกับควินน์ ยอริก ถูกส่งไปลาดตระเวนทางเหนือของซิลเวอร์ไพน์ เราไม่ได้ข่าวจากพวกเขาอีกเลย\n\nพวกเขาอาจตกเป็นเหยื่อของสเคิร์จ หากเป็นเช่นนั้น ข้าก็ต้องการคำยืนยัน จงตามหาเดธสตอล์กเกอร์สองคนนี้\n\nเป้าหมายแรกของพวกเขาคือสอดแนมไร่ทางเหนือของซิลเวอร์ไพน์ เจ้าควรเริ่มค้นหาที่นั่น" },
        completion = { "42:58287019:695288501", "เจ้าพบเราแล้ว! มาทันเวลาพอดี..." },
    },
    [429] = { -- Wild Hearts
        title = { "11:461810032:720247925", "หัวใจแห่งพงไพร" },
        objective = { "88:483834319:1468472801", "รวบรวมหัวใจเวิร์กสีผิดปกติ 6 ดวง แล้วนำไปให้ Apothecary Renferrel ที่ Sepulcher", variants = { { "88:718938995:434740021", "รวบรวมหัวใจเวิร์กสีผิดปกติ 3 ดวง แล้วนำไปให้ Apothecary Renferrel ที่ Sepulcher" } } },
        description = { "448:777464026:272972310", "ควินน์พี่น้องของข้าบาดเจ็บสาหัสเพราะกูลไอวาร์ผู้โสมม ข้าไม่รู้ว่าเขาจะหายดีได้หรือไม่หากไม่มีเวทมนตร์ช่วย แม้ข้าไม่ใช่นักปรุงยา แต่ข้ารู้ว่านักปรุงยาของเราทำน้ำยารักษาจากหัวใจเวิร์กที่มีสีผิดปกติได้\n\nเก็บหัวใจเหล่านั้น แล้วนำไปให้นักปรุงยาเรนเฟอร์เรลที่เซพัลเชอร์ทางใต้ จากนั้นกลับมาที่นี่พร้อมยา\n\nเจ้าจะพบเวิร์กจำนวนมากระหว่างที่นี่กับสวนผลไม้ของมัลเดนทางตะวันออก", variants = { { "451:462318305:662557637", "ควินน์พี่น้องของข้าบาดเจ็บสาหัสเพราะกูลไอวาร์ผู้โสมม ข้าไม่รู้ว่าเขาจะหายดีได้หรือไม่หากไม่พึ่งยาปรุง แม้ข้าไม่ใช่นักปรุงยา แต่ข้ารู้ว่านักปรุงยาของเราทำน้ำยารักษาจากหัวใจเวิร์กที่มีสีผิดปกติได้\n\nเก็บหัวใจเหล่านั้น แล้วนำไปให้นักปรุงยาเรนเฟอร์เรลที่เซพัลเชอร์ทางใต้ จากนั้นกลับมาที่นี่พร้อมยา\n\nเจ้าจะพบเวิร์กจำนวนมากระหว่างที่นี่กับสวนผลไม้ของมัลเดนทางตะวันออก" } } },
        progress = { "18:398591324:461194467 C 53:1686600251:455455378", "ข้ามีเวลาไม่มาก {class} เพราะเลดี้แห่งความมืดมอบหมายงานสำคัญยิ่งให้ข้า" },
        completion = { "304:349668604:787347745", "<เรนเฟอร์เรลรับหัวใจไป>\n\nน่าหนักใจที่ได้ยินว่าเดธสตอล์กเกอร์ของเราทำภารกิจล้มเหลว\n\nหวังว่าความล้มเหลวเช่นนี้จะเกิดขึ้นไม่บ่อย\n\nอีกสักครู่ข้าจะให้ยาเจ้า แต่นี่คือสูตรยา หากเดธสตอล์กเกอร์เหล่านั้นต้องการความช่วยเหลืออีกในอนาคต บางทีเจ้าอาจช่วยพวกเขาได้เอง", variants = { { "178:798831380:1955071532", "<เรนเฟอร์เรลรับหัวใจไป>\n\nน่าหนักใจที่ได้ยินว่าเดธสตอล์กเกอร์ของเราทำภารกิจล้มเหลว\n\nหวังว่าความล้มเหลวเช่นนี้จะเกิดขึ้นไม่บ่อย\n\nอีกสักครู่ข้าจะให้ยาเจ้า" } } },
        required = { [3164] = { "21:1286356283:1908109597", "หัวใจวอร์กที่เปลี่ยนสี" } },
        steps = { { "21:1286356283:1908109597", "หัวใจวอร์กที่เปลี่ยนสี" } },
    },
    [430] = { -- Return to Quinn
        title = { "15:1335402282:1059398361", "กลับไปหาควินน์" },
        objective = { "79:1974766584:2114314160", "นำยาของ Quinn ไปให้ Quinn Yorick ที่ Ivar Patch ทางเหนือของ Sepulcher" },
        description = { "122:1817234313:1242089402", "นี่คือยาที่จะช่วยให้ควินน์ ยอริกฟื้นตัว\n\nตอนนี้ข้าขอตัว ข้ายังมีงานสำคัญมากที่ต้องทำต่อ..." },
        progress = { "56:322004134:1794714161", "พี่น้องของข้าบอกว่าเจ้ามาช่วยเรา จริงหรือ?" },
        completion = { "131:613973718:350311626 N 1:46:46", "<ควินน์รับยาแล้วดื่ม>\n\nใช่ ข้ารู้สึกได้ว่ายาเริ่มออกฤทธิ์ อีกไม่นานข้าจะเดินทางได้\n\nเจ้าช่วยข้าไว้มากจริง ๆ {name}", variants = { { "84:2116184210:573056585", "<ควินน์รับยาแล้วดื่ม>\n\n<เวลาผ่านไปครู่หนึ่งท่ามกลางความเงียบที่ชวนลุ้น>" } } },
        required = { [3165] = { "20:1754724314:1022701054", "ยาของ Quinn สูตรอ่อน" } },
        steps = { { "20:1754724314:1022701054", "ยาของ Quinn สูตรอ่อน" } },
    },
    [437] = { -- The Dead Fields
        title = { "15:1834744942:1811044186", "ทุ่งแห่งความตาย" },
        objective = { "147:78779824:1755385507", "ฆ่าพวกโนลล์รอตไฮด์ที่ Dead Fields\n\nเมื่อ Nightlash ปรากฏตัว จงฆ่านาง\n\nนำ Essence of Nightlash ไปให้ High Executor Hadrec ที่ Sepulcher" },
        description = { "485:1304164373:1940907141", "รายงานลาดตระเวนซิลเวอร์ไพน์เบื้องต้นระบุว่าพวกรอตไฮด์มีฐานอยู่ที่ไร่เก่าทางเหนือ ทุ่งเดดฟีลด์ส เราส่งกำลังเล็ก ๆ ไปโจมตี แต่ทุกครั้งแบนชีไนต์แลชจะมาช่วยพวกมัน ใช้เวทมนตร์ตีทัพเราแตก\n\nเราต้องการกำจัดไนต์แลช\n\nไปที่เดดฟีลด์สแล้วโจมตีรอตไฮด์ หากไม่เห็นไนต์แลช ให้ฆ่ารอตไฮด์จนกว่านางจะปรากฏ แล้วเอาชนะนาง\n\nแก่นพลังของนางจะกลายเป็นผง นำผงนั้นมาเป็นหลักฐานให้ข้า" },
        progress = { "29:606379549:112589940 N 63:1025405242:1767113060", "เจ้าเอาชนะไนต์แลชแล้วหรือยัง {name}? ความสำเร็จในการต่อสู้กับรอตไฮด์ขึ้นอยู่กับการกำจัดนาง!" },
        completion = { "55:707233047:128990010 N 122:739139531:1907642776", "ข้าได้ข่าวว่าเจ้าบุกรอตไฮด์สำเร็จ {name} และแก่นพลังนี้ก็ยืนยันการตายของไนต์แลช\n\nวันนี้สเคิร์จเสียพื้นที่ไปแล้ว คุณค่าของเจ้าต่อฟอร์เซเคนเพิ่มขึ้นอีก" },
        required = { [3622] = { "20:256512380:1370373365", "แก่นพลังของ Nightlash" } },
        steps = { { "20:256512380:1370373365", "แก่นพลังของ Nightlash" } },
        objectiveLabels = {
            event = { ["Enter the Dead Fields"] = "เข้าไปใน Dead Fields" },
        },
    },
    [438] = { -- The Decrepit Ferry
        title = { "18:2113814300:1513957449", "ท่าเรือข้ามฟากผุพัง" },
        objective = { "70:1288981902:1519387985", "ไปที่ Decrepit Ferry\n\nค้นหาว่าเหตุใดสเคิร์จจึงอยู่ที่นั่น" },
        description = { "N 290:1563023498:86812291", "{name} เราพบรังใหม่ของสเคิร์จที่ท่าเรือข้ามฟากเดเครพิต ท่าเรืออยู่ทางตะวันออกของเซพัลเชอร์ มีรอตไฮด์และอันเดดอื่น ๆ ลาดตระเวนหนาแน่น\n\nสเคิร์จต้องมีเหตุผลที่ยึดพื้นที่นี้ ไปที่ท่าเรือข้ามฟากเดเครพิตแล้วหาว่าเหตุใดพวกมันจึงอยู่ที่นั่น" },
        completion = { "187:1723388705:662176680", "ในเรือลำนี้มีศพห่อผ้าสุมเป็นกอง เมื่อมองข้ามทะเลสาบลอร์ดาเมียร์ไปทางตะวันออก จะเห็นท่าเรืออีกฟากบนเกาะเฟนริส\n\nชะตาของศพเหล่านี้ต้องเกี่ยวข้องกับเกาะเฟนริส" },
    },
    [439] = { -- Rot Hide Clues
        title = { "14:201773603:1583556797", "เบาะแสของรอตไฮด์" },
        objective = { "61:748830652:1105525702", "นำ Deliah's Ring ไปให้ High Executor Hadrec ที่ Sepulcher" },
        description = { "216:1290615412:332566847", "มือข้างหนึ่งยื่นออกมาจากกองศพโดยไม่มีผ้าห่อ เป็นมือของผู้หญิง มีรอยโรคระบาด แต่ยังค่อนข้างสด\n\nมีแหวนอยู่บนนิ้ว เมื่อถอดมาตรวจดู จะเห็นข้อความสลักว่า\n\n“แด่ดีไลอาห์”" },
        progress = { "N 57:165420633:1353276968", "{name} เจ้ากลับมาแล้ว แสดงว่าการสืบสวนคงได้ผลสินะ?" },
        completion = { "201:2019014369:359168226", "เจ้าบอกว่าหญิงที่เพิ่งตายเป็นผู้สวมแหวนนี้หรือ?\n\nแหล่งศพเช่นนั้นที่อยู่ใกล้มีเพียงหลุมศพรวมในทิริสฟัล พวกโนลล์รอตไฮด์ต้องกำลังขนศพเหล่านั้นไปเกาะเฟนริส!" },
        required = { [3234] = { "13:904641910:15766750", "แหวนของ Deliah" } },
        steps = { { "13:904641910:15766750", "แหวนของ Deliah" } },
    },
    [440] = { -- The Engraved Ring
        title = { "17:1936018653:1229524570", "แหวนสลักข้อความ" },
        objective = { "50:98579055:95924887", "นำ Deliah's Ring ไปให้ Magistrate Sevren ใน Brill" },
        description = { "323:192119873:335050642", "หากเจ้าอยากหาสามีหรือคนรักที่มอบแหวนให้ดีไลอาห์... จงคุยกับผู้พิพากษาเซฟเรนในบริลล์ เขาน่าจะมีบันทึกผู้เสียชีวิตล่าสุด หากโชคดี คงรู้ได้ว่าดีไลอาห์เป็นใคร\n\nแต่ข้าจะไม่ตั้งความหวัง คนที่ให้แหวนนางน่าจะตายแล้ว หรือหากเป็นอันเดด เขาก็คงไม่สนใจดีไลอาห์อีกต่อไป" },
        progress = { "7:989913233:66981971 N 32:827142055:770741335", "สวัสดี {name} อะไรทำให้เจ้ากลับมาบริลล์?" },
        completion = { "287:987694292:1243165095", "ไม่นานมานี้มีหญิงชื่อดีไลอาห์อาศัยอยู่ในบริลล์จริง นางถูกฝังในหลุมศพรวม แต่หากที่เจ้าพูดเป็นความจริง พวกโนลล์รอตไฮด์ต้องขโมยศพนางไปซิลเวอร์ไพน์แล้ว\n\nรอตไฮด์ต้องถูกกำจัดเช่นเดียวกับสเคิร์จทั้งหมด ข้าเชื่อว่าเจ้ากำลังลงมือทำให้เป็นเช่นนั้น" },
        required = { [3234] = { "13:904641910:15766750", "แหวนของ Deliah" } },
        steps = { { "13:904641910:15766750", "แหวนของ Deliah" } },
    },
    [442] = { -- Assault on Fenris Isle
        title = { "22:669631294:983804663", "บุกเกาะเฟนริส" },
        objective = { "60:297075726:1607822121", "นำ Thule's Head ไปให้ High Executor Hadrec ที่ Sepulcher" },
        description = { "208:347058554:486230609 N 20:1439804975:757449994", "ถึงเวลาบุกฐานที่มั่นของสเคิร์จในซิลเวอร์ไพน์ เกาะเฟนริส\n\nเจ้าต้องกลับไปที่เกาะและกำจัดธูล เรเวนคลอว์ ข้าต้องการศีรษะของมัน!\n\nภารกิจนี้อันตรายพอ ๆ กับความสำคัญของมัน {name} เจ้าจะล้มเหลวไม่ได้" },
        progress = { "55:203972974:955091290 N 55:1059390867:1772004927", "เราปล่อยให้สเคิร์จอยู่ในซิลเวอร์ไพน์ต่อไม่ได้ {name} กลับมาหาข้าเมื่อมีหลักฐานว่าธูลตายแล้ว" },
        completion = { "49:521879806:907738542 N 189:524773160:1214204748", "การตายของธูล เรเวนคลอว์ไม่ใช่เรื่องเล็ก {name} เรนเฟอร์เรลบอกว่าพลังที่ปลดปล่อยเมื่อเจ้ากำจัดธูลนั้น สัมผัสได้ไกลถึงเซพัลเชอร์\n\nการกระทำของเจ้าเป็นที่กล่าวขานไปทั่วฟอร์เซเคน คุณค่าของเจ้าต่อเราเพิ่มขึ้นอีก" },
        required = { [3623] = { "12:65541791:1023971500", "ศีรษะของ Thule" } },
        steps = { { "12:65541791:1023971500", "ศีรษะของ Thule" } },
    },
    [443] = { -- Rot Hide Ichor
        title = { "14:453164840:1182618091", "ของเหลวรอตไฮด์" },
        objective = { "75:1544033142:1381010561", "นำของเหลวรอตไฮด์ 8 ขวดไปให้ Apothecary Renferrel ที่ Sepulcher" },
        description = { "370:894571329:220065049", "ก่อนบุกเกาะเฟนริส เราต้องรู้ว่าใครอยู่เบื้องหลังพวกโนลล์รอตไฮด์ นักปรุงยาของเราเชื่อว่าต้นกำเนิดของมันซ่อนอยู่ในของเหลวประหลาดที่ไหลเวียนในร่าง\n\nไปเกาะเฟนริสทางตะวันออกของท่าเรือข้ามฟากเดเครพิต เก็บของเหลวรอตไฮด์จากโนลล์ที่นั่น แล้วนำไปให้นักปรุงยาเรนเฟอร์เรลซึ่งประจำอยู่ด้านนอกเซพัลเชอร์" },
        progress = { "32:1434043196:1366422138 N 1:63:63", "เจ้ามีของเหลวรอตไฮด์แล้วหรือยัง {name}?" },
        completion = { "129:1514318755:1730624686", "ดีมาก ของเหลวนี้จะช่วยให้เราเข้าใจธรรมชาติของรอตไฮด์ และอาจเผยจุดอ่อนของพวกมัน...\n\n...ถ้าพวกมันมีจุดอ่อน" },
        required = { [3236] = { "14:453164840:1182618091", "ของเหลวจาก Rot Hide" } },
        steps = { { "14:453164840:1182618091", "ของเหลวจาก Rot Hide" } },
    },
    [444] = { -- Rot Hide Origins
        title = { "16:1787520205:1346930011", "ต้นกำเนิดของรอตไฮด์" },
        objective = { "59:719451801:1546094786", "นำ Sample Ichor ไปให้ Bethor Iceshard ใน Undercity" },
        description = { "479:1416262243:2010088929", "ข้าเคี่ยวของเหลวที่เจ้านำมาให้จนเข้มข้น แล้วแยกออกเป็นส่วนประกอบพื้นฐาน ผลยังไม่แน่ชัด แต่ข้าพบว่ามีการใช้เวทวอร์ล็อกและเวทปลุกศพสร้างของเหลวนี้\n\nระหว่างที่ข้าศึกษาต่อ ข้าอยากให้เจ้านำตัวอย่างไปให้เบธอร์ ไอซ์ชาร์ดในอันเดอร์ซิตี เบธอร์ไม่ใช่นักปรุงยา แต่ความรู้ด้านเวทของเขาอาจไขปริศนาของพวกรอตไฮด์ได้\n\nไปเถิด เจ้าจะพบเบธอร์ในย่านเวทมนตร์ของอันเดอร์ซิตี" },
        progress = { "84:2041928067:1476145409", "งานศึกษาของข้าต้องใช้สมาธิมาก หวังว่าเจ้าคงไม่ได้มาด้วยเรื่องไร้สาระ" },
        completion = { "153:2095499141:491111852", "สารนี้เจือเวทมนตร์ทรงพลัง บางบทข้าไม่ได้เห็นมานานแสนนานแล้ว...\n\nรอสักครู่ ข้าต้องร่ายเวทหยั่งรู้..." },
        required = { [3237] = { "12:2014275262:1320363558", "ตัวอย่างของเหลว" } },
        steps = { { "12:2014275262:1320363558", "ตัวอย่างของเหลว" } },
    },
    [446] = { -- Thule Ravenclaw
        title = { "15:1061894590:1120356654", "ธูล เรเวนคลอว์" },
        objective = { "74:1414913632:1169942437", "นำ Bethor's Scroll ไปให้ Apothecary Renferrel ที่ Sepulcher ใน Silverpine" },
        description = { "475:746099075:2069383808", "ของเหลวนี้เป็นฝีมือเพื่อนร่วมงานเก่าของข้า ธูล เรเวนคลอว์ ก่อนสงครามใหญ่ เขาเป็นจอมเวทหนุ่มอนาคตไกล แต่เมื่อลิชคิงเรืองอำนาจ เขาก็ทรยศพวกพ้องแล้วเข้ากับสเคิร์จ\n\nข้าไม่รู้เลยว่าเขายังมีชีวิตอยู่ ซ้ำยังนำพวกรอตไฮด์ออกจู่โจมเรา!\n\nข้ารู้จักเวทของเขาหลายบท จึงช่วยคิดสูตรยาต้านได้ นำม้วนคัมภีร์นี้กลับไปให้นักปรุงยาเรนเฟอร์เรล ในนั้นมีคาถาที่จำเป็นต่อการปรุงยา" },
        progress = { "11:927657569:725753248 N 30:2030108480:1061901451", "สวัสดี {name} เบธอร์ว่าอย่างไรบ้าง?" },
        completion = { "200:714629059:578002413", "ม้วนคัมภีร์นี้เปี่ยมด้วยเวทมนตร์ทรงพลัง ข้าไม่เคยใช้พลังเช่นนี้ปรุงยามาก่อน... ยาที่ได้จะมีฤทธิ์แรงและน่าจะช่วยเจ้าได้มาก หากเจ้าบุกโจมตีธูลในฐานที่มั่นบนเกาะเฟนริส" },
        required = { [3250] = { "15:1721716228:14742847", "ม้วนจารึกของ Bethor" } },
        steps = { { "15:1721716228:14742847", "ม้วนจารึกของ Bethor" } },
    },
    [447] = { -- A Recipe For Death
        title = { "18:1782240686:725681792", "สูตรแห่งความตาย" },
        objective = { "129:1237248533:2044844264", "รวบรวม Grizzled Bear Heart 6 ดวงและตัวอย่าง Skittering Blood 6 ตัวอย่าง แล้วนำไปให้ Master Apothecary Faranell ใน Undercity" },
        description = { "500:263266290:1723883509", "กองทัพของอาร์ธัสมีจำนวนท่วมท้น แต่โรคระบาดสายพันธุ์ใหม่จะช่วยให้เรากำจัดทั้งกองทัพสเคิร์จและมนุษย์ที่แพร่เต็มไปหมดได้อย่างเด็ดขาด\n\nผลศึกษาของข้ายืนยันว่าเลือดแมงมุมผสมกับพิษที่สกัดจากหัวใจหมีกริซเซิลจะได้น้ำยามรณะ เก็บตัวอย่างจากแมงมุมในสกิตเทอริงดาร์กทางตะวันตกเฉียงเหนือ และจากหมีที่เดินเตร่อยู่ทั่วป่าซิลเวอร์ไพน์ นำวัตถุดิบไปให้หัวหน้านักปรุงยาฟาราเนลล์แห่งสมาคมนักปรุงยาหลวงในอันเดอร์ซิตี" },
        progress = { "6:1136836709:1914036474 C 62:1116048599:92742645", "สวัสดี {class} เจ้ามีธุระอะไรกับสมาคมนักปรุงยาหลวง?" },
        completion = { "52:829141449:900255603 N 125:1060336757:601772435", "ดีจริงที่นักปรุงยาเรนเฟอร์เรลส่งเจ้ามาหาข้า {name} ตัวอย่างเหล่านี้จะเป็นประโยชน์ต่องานของเรา ข้าจะเริ่มศึกษาคุณสมบัติด้านพิษและการปนเปื้อนทันที" },
        required = { [3253] = { "19:1208989636:1258062289", "หัวใจหมีขนหงอก" }, [3254] = { "16:69873823:326482225", "เลือดแมงมุม Skittering Blood" } },
        steps = { { "19:1208989636:1258062289", "หัวใจหมีขนหงอก" }, { "16:69873823:326482225", "เลือดแมงมุม Skittering Blood" } },
    },
    [448] = { -- Report to Hadrec
        title = { "16:1460748693:1536541576", "รายงานตัวกับแฮเดร็ก" },
        objective = { "48:2062105257:20507910", "ไปรายงานตัวกับ High Executor Hadrec ที่ Sepulcher" },
        description = { "137:46653656:2052535549", "ก่อนบุกเกาะเฟนริส ให้ไปรายงานตัวกับไฮเอ็กเซคิวเตอร์แฮเดร็ก เขาอาจมีข้อมูลเพิ่มเติมหรืออุปกรณ์ที่เจ้าต้องใช้" },
        completion = { "174:764603507:858287330", "หากที่เบธอร์พูดเป็นจริง ธูล เรเวนคลอว์คือภัยที่ต้องรีบจัดการ\n\nเพื่อช่วยให้เจ้าทำงานนี้สำเร็จ เลือกของจากคลังอาวุธของเราที่นี่ไปได้..." },
    },
    [450] = { -- A Recipe For Death
        title = { "18:1782240686:725681792", "สูตรแห่งความตาย" },
        objective = { "112:387538601:254615798", "นำบันทึกของ Apothecary Berard จาก Pyrewood Village ไปให้ Apothecary Renferrel ที่ Sepulcher" },
        description = { "63:266146355:405039768 N 425:979008029:1511621300", "เจ้าช่วยสมาคมนักปรุงยาหลวงได้อีก {name}\n\nเมื่ออารูกัลร่ายเวทชั่วร้ายใส่ป่า มันสาปนักปรุงยาเบราร์ด หนึ่งในสมาชิกที่มีอนาคตที่สุดของเรา ตอนนี้เบราร์ดเป็นเพียงข้ารับใช้ไร้สติของอารูกัล เขาช่วยอะไรเราไม่ได้แล้ว แต่ผลการศึกษาของเขาอาจยังมีค่า เขากำลังศึกษาโรคระบาดโบราณที่คร่าชีวิตสัตว์น้ำทั้งหมดในทะเลสาบลอร์ดาเมียร์เมื่อนานมาแล้ว\n\nไปเอา Berard's Journal จากห้องทำงานของเขาในโรงแรมหมู่บ้านไพร์วูด แล้วนำไปให้นักปรุงยาเรนเฟอร์เรล" },
        progress = { "20:168162824:875123572 N 1:46:46", "เจ้ากลับมาแล้วสินะ {name}" },
        completion = { "54:942733486:733247868 N 61:207561093:1620230350", "บันทึกของนักปรุงยาเบราร์ด! เจ้ากล้าหาญทีเดียว {name} มาดูกันว่าเบราร์ดกำลังทำอะไรอยู่ก่อนจะเสียสติ..." },
        required = { [3255] = { "16:1373005286:57664767", "บันทึกของ Berard" } },
        steps = { { "16:1373005286:57664767", "บันทึกของ Berard" } },
    },
    [451] = { -- A Recipe For Death
        title = { "18:1782240686:725681792", "สูตรแห่งความตาย" },
        objective = { "137:1027436896:42989347", "นำตัวอย่าง Lake Creeper Moss 6 ตัวอย่าง ตัวอย่าง Lake Skulker Moss 6 ตัวอย่าง และ Hardened Tumor หนึ่งชิ้นไปให้ Master Apothecary Faranell ใน Undercity" },
        description = { "468:1891590275:1444484607", "ตามบันทึกของเบราร์ด มอสจาก Lake Skulker และ Lake Creeper อาจใช้สร้างโรคระบาดสายพันธุ์ใหม่ได้ สัตว์พวกนั้นอาศัยตามเกาะในทะเลสาบลอร์ดาเมียร์ทางตะวันออก\n\nเขายังกล่าวถึง Hardened Tumor ที่หายากมาก ซึ่งพบในเมอร์ล็อกไวล์ฟิน ดูเหมือนจะหายากเสียจนเบราร์ดหาได้เพียงชิ้นเดียว\n\nเก็บตัวอย่างมอสและก้อนเนื้อแข็งหายากนั้นไปให้หัวหน้านักปรุงยาฟาราเนลล์ในอันเดอร์ซิตี" },
        progress = { "39:1722247745:451590210 N 1:63:63", "อะไรพาเจ้ากลับมาอันเดอร์ซิตี {name}?" },
        completion = { "241:2043014134:852440680 N 108:1654599691:1521074432", "การเสียเบราร์ดเป็นความสูญเสียครั้งใหญ่ของสมาคมนักปรุงยาหลวง แต่ด้วยความทุ่มเทของเจ้าและงานวิจัยอย่างขยันขันแข็งของนักปรุงยาเรนเฟอร์เรล ผลการศึกษาของเบราร์ดจะยังช่วยเลดี้แห่งความมืดฝ่าความลำบากไปได้\n\nเราใกล้จะทำสิ่งยิ่งใหญ่สำเร็จแล้ว {name} หากเจ้าไม่ชำนาญการต่อสู้ถึงเพียงนี้ ข้าคงชวนเจ้ามาเป็นสมาชิกสมาคม" },
        required = { [3256] = { "17:130111148:1894305452", "มอสจาก Lake Skulker" }, [3257] = { "17:1325077116:1869949146", "มอสจาก Lake Creeper" }, [3258] = { "14:1347246918:835463146", "เนื้องอกแข็ง" } },
        steps = { { "17:130111148:1894305452", "มอสจาก Lake Skulker" }, { "17:1325077116:1869949146", "มอสจาก Lake Creeper" }, { "14:1347246918:835463146", "เนื้องอกแข็ง" } },
    },
    [452] = { -- Pyrewood Ambush
        title = { "15:2039761710:1250656767", "ซุ่มโจมตีที่ไพร์วูด" },
        objective = { "53:1488236495:295574666", "ช่วย Deathstalker Faerleia สังหารสมาชิก Pyrewood Council" },
        description = { "39:2145143839:1482436753 N 432:1310140975:1074891971", "เจ้ามาทันเวลาพอดี {name}!\n\nสภาไพร์วูดจะกลับมาเมื่อไรก็ได้ อารูกัลมีเรื่องอื่นต้องจัดการในปราสาท มันใช้สภาเป็นหุ่นเชิดเพื่อควบคุมสมุนไร้สติในไพร์วูด แต่ข้าเชื่อว่าหากขาดสภาคอยชี้นำ เหล่าบุตรแห่งอารูกัลจะหันไปเล่นงานนายของมันเอง\n\nข้ารับมือทั้งหมดคนเดียวไม่ไหว ข้าต้องการให้เจ้าช่วย เราจะร่วมกันทำลายสภาเพื่อเลดี้ซิลวานัส" },
        completion = { "50:231160152:128420544 N 135:1489405646:1868967239", "เจ้าต่อสู้อย่างสาวกที่แท้จริงของเลดี้แห่งความมืด {name} เมื่อสภาถูกกำจัดแล้ว บางทีเราอาจยึดเมืองนี้ได้อย่างเด็ดขาดและขับอารูกัลออกจากปราสาทชาโดว์แฟง ขอคารวะเจ้า!" },
        objectiveLabels = {
            event = { ["Aid Faerleia in killing the Pyrewood Council"] = "ช่วย Faerleia กำจัดสภา Pyrewood" },
        },
    },
    [460] = { -- Resting in Pieces
        title = { "17:91157510:141711724", "พักสงบแบบแยกชิ้น" },
        objective = { "33:532292489:1165698433", "นำ Alaric's Head ไปที่หลุมศพของเขา" },
        description = { "490:101424012:297578497", "เจ้าดูไม่เหมือนรอตไฮด์ ดีจริง ข้าหมดหวังไปแล้ว...\n\nข้าชื่ออะลาริก เคยเป็นคนรับใช้คนสนิทและองครักษ์ของธูล เขาใช้เวทมนตร์เพื่อ “ปกป้อง” ข้าจากโรคระบาดอันเดด แต่กลับทำให้ข้าต้องอยู่ในสภาพกึ่งเป็นกึ่งตายที่หนีไม่พ้น แล้วหลังจากสร้างพวกโนลล์รอตไฮด์ต้องสาป ธูลก็ตัดหัวข้า... และโยนให้พวกโนลล์เอาไปเล่น!\n\nได้โปรด พาข้าไปหาร่างของข้า ข้าคิดว่าพวกโนลล์ฝังร่างไว้ที่นี่ ในหลุมไร้ป้ายใกล้คอกสัตว์ในปราสาทเฟนริส" },
        progress = { "27:75116028:1865367439", "หลุมศพนี้ถูกขุดอย่างรีบร้อน" },
        completion = { "11:1191658970:1224418299 N 77:1339824719:218600608", "ขอบใจ {name} ข้ากลัวว่าพวกโนลล์ทำลายร่างข้าไปแล้ว ดีจริงที่ร่างยังอยู่" },
        required = { [3317] = { "14:1927360934:450763828", "หัวพูดได้" } },
        objectiveLabels = {
            item = { ["A Talking Head"] = "หัวพูดได้" },
        },
    },
    [461] = { -- The Hidden Niche
        title = { "16:870384858:826980967", "ซอกลับ" },
        objective = { "33:2023992283:799874554", "พา Alaric ไปยังซอกลับ" },
        description = { "297:1456688143:2130186123", "ข้ารู้ว่ามีซอกลับในปราสาทที่เก็บของสำคัญของธูลและเพื่อนร่วมงานเก่าของเขา อีกทั้งยังมีของที่อาจเป็นประโยชน์กับเจ้า พาข้าไปที่นั่น!\n\nซอกนั้นอยู่หลังชั้นวางฝุ่นจับ ในหอคอยทางตะวันตกเฉียงใต้ของปราสาท\n\nเอาร่างข้าไป แต่ทิ้งรองเท้าบูตไว้เถิด ข้าใส่มันไม่พอดีสักที..." },
        progress = { "36:1678892837:441242276", "ตรงนี้แหละ! พาข้าเข้าไปใกล้อีก..." },
        completion = { "262:1449814037:350227175", "เรียบร้อย เปิดแล้ว ทิ้งข้าไว้ที่นี่เถิด ช่วงชีวิตที่ดีที่สุดของข้าอยู่ในปราสาทแห่งนี้ แค่คิดว่าจะได้พักในกำแพงนี้ข้าก็สบายใจแล้ว\n\nปิดซอกให้สนิทด้วย ข้าไม่อยากให้พวกรอตไฮด์พบข้า\n\nอ้อ เอานี่ไปด้วย เจ้าสมควรได้รับ" },
        required = { [3318] = { "16:735091760:11900546", "ร่างของ Alaric" } },
        steps = { { "16:735091760:11900546", "ร่างของ Alaric" } },
    },
    [477] = { -- Border Crossings
        title = { "16:1780152940:744485213", "ข้ามเขตแดน" },
        objective = { "105:73686884:708465989", "นำของจากลังใบหนึ่งของพ่อมด Dalaran กลับมา หมู่บ้าน Pyrewood อยู่ทางใต้" },
        description = { "486:1477784932:1119431590", "อย่างที่เจ้าอาจรู้ เมืองแอมเบอร์มิลล์ยังเป็นฐานต่อต้านของมนุษย์ ส่วนใหญ่เพราะได้แรงหนุนจากพ่อมดแห่งดาลารัน\n\nข้าไม่รู้ว่าพวกเขาวางแผนอะไร แต่การที่พวกเขาสนใจหมู่บ้านห่างไกลอย่างแอมเบอร์มิลล์แสดงว่าที่นั่นต้องมีความสำคัญกว่าที่เห็น\n\nพวกเขาขนลังจากฮิลส์แบรดมาทีละเกวียน เสบียงจำนวนมากไปลงที่ค่ายเล็ก ๆ ทางเหนือของหมู่บ้านไพร์วูด เอาของในลังสักใบกลับมาให้ข้า" },
        completion = { "293:623349617:220016761", "<เจ้างัดฝาลังออกและพบสิ่งของหลายอย่างที่จัดเก็บไว้อย่างดี ด้านบนสุดมีมัดแผนที่เก่าเหลือง ดูเหมือนเป็นแผนที่ป่าซิลเวอร์ไพน์และพื้นที่อื่นทางตะวันตกของลอร์แดรอน\n\nใต้แผนที่มีจี้เวทมนตร์หน้าตาลึกลับ>" },
    },
    [478] = { -- Maps and Runes
        title = { "14:1775682371:336263414", "แผนที่และอักขระรูน" },
        objective = { "69:1767119666:1056301929", "นำจี้ประหลาดไปให้ Shadow Priest Allister ที่ Sepulcher" },
        description = { "68:1283412978:805620447", "<เจ้ารีบหยิบจี้ออกจากลังแล้วปิดฝาตามเดิม>" },
        progress = { "34:346780008:159565826 N 1:63:63", "เจ้าได้เบาะแสที่ใช้ได้บ้างหรือไม่ {name}?" },
        completion = { "213:524189886:1382433248", "แผนที่กับ... จี้นี่หรือ? น่าสนใจ\n\nเห็นชัดว่าพ่อมดดาลารันสนใจแอมเบอร์มิลล์ด้วยเหตุผลบางอย่าง แต่ข้ายังไม่รู้ว่าพวกเขาหวังอะไร\n\nบางทีดาลาร์อาจรู้ว่าของเหล่านี้ใช้ทำอะไร" },
        required = { [3353] = { "22:1162476596:1879618800", "จี้สลักรูน" } },
        steps = { { "22:1162476596:1879618800", "จี้สลักรูน" } },
    },
    [479] = { -- Ambermill Investigations
        title = { "24:1497885732:195375583", "สืบเรื่องแอมเบอร์มิลล์" },
        objective = { "70:226720215:1129845813", "หา Dalaran Pendant 8 ชิ้นให้ Shadow Priest Allister ที่ Sepulcher" },
        description = { "294:758157514:1946993044", "ดาลาร์กำลังหาต้นตอของเวทที่พ่อมดพวกนั้นร่าย ระหว่างนี้เราต้องถ่วงงานของพวกเขาทุกวิถีทาง...\n\nพวกนักอัญเชิญ จอมเวท และผู้พิทักษ์ต้องพกจี้ไว้แน่ จงปลดจี้แล้วเอากลับมา\n\nลงใต้ตามถนนสายหลัก แล้วเลี้ยวเข้าทางแยกตะวันออกไปแอมเบอร์มิลล์" },
        progress = { "99:1765050431:1975887949", "เราต้องรีบ อย่าให้แผนของพวกเขาสำเร็จ ไม่เช่นนั้นเราอาจเสียการควบคุมป่าซิลเวอร์ไพน์" },
        completion = { "154:582755884:1100253201", "ดาลาร์พบว่าการถักทอเวทคืบหน้าไปไกลแล้ว แม้จะถูกขัดขวาง\n\nพ่อมดผู้ทรงพลังกำลังชักนำพลังเวทอยู่ ต้องรีบหยุดเขา" },
        required = { [3354] = { "15:1347589557:1667491404", "จี้แห่ง Dalaran" } },
        steps = { { "15:1347589557:1667491404", "จี้แห่ง Dalaran" } },
    },
    [480] = { -- The Weaver
        title = { "10:1627419399:276664614", "ผู้ถักทอเวท" },
        objective = { "95:34415438:813672808", "สังหารอัครจอมเวทแห่ง Dalaran แล้วนำไม้เท้าของเขาไปให้ Shadow Priest Allister ที่ Sepulcher" },
        description = { "345:864586956:291420609", "อัครจอมเวทผู้ทรงพลังกำลังควบคุมการปลุกจุดรวมพลังบนเส้นเวทให้ตื่นขึ้นอีกครั้ง พวกเขาทำงานคืบหน้าจนการฆ่าเขาเป็นความหวังเดียวที่จะหยุดแผนนี้ได้ งานคงยาก เพราะเขาต้องมีจอมเวทและผู้คุ้มกันมากมายปกป้องอยู่\n\nเจ้าไปจัดการเขาโดยเร็ว เมื่อเขาตายแล้ว นำไม้เท้ากลับมาให้ข้า ไปเดี๋ยวนี้" },
        progress = { "26:2012989528:763369968 N 1:33:33", "รีบเข้า เวลาเหลือน้อยแล้ว {name}!" },
        completion = { "111:1885347069:1063196747 N 211:1922949576:1033610983", "เวทของเหล่าพ่อมดสลายไป และพลังบนเส้นเวทก็กลับสู่ภาวะสงบนิ่ง ความพยายามของเจ้าได้ผล {name} เราเล่นงานศัตรูและพ่อมดดาลารันผู้วางอำนาจได้อย่างหนัก\n\nแต่เราต้องระวังตัวไว้ แหล่งพลังอยู่ใกล้เพียงนี้... เราต้องวางแผนรับมือในอนาคต" },
        required = { [3515] = { "15:407339341:669835988", "ไม้เท้าของ Ataeric" } },
        steps = { { "15:407339341:669835988", "ไม้เท้าของ Ataeric" } },
    },
    [481] = { -- Dalar's Analysis
        title = { "16:1974353195:1851814980", "การวิเคราะห์ของดาลาร์" },
        objective = { "69:525335698:1720718428", "นำจี้สลักอักขระรูนไปให้ Dalar Dawnweaver ที่ Sepulcher" },
        description = { "91:1492926277:151569167", "นำจี้ไปให้ดาลาร์ ดอว์นวีฟเวอร์ บางทีเขาอาจช่วยให้เราเข้าใจแผนของพ่อมดได้" },
        progress = { "5:1287366450:669725923 C 13:1978731323:1273461133", "ว่าอย่างไร {class}? มีอะไรหรือ?" },
        completion = { "364:1185057361:767242559", "น่าสนใจ ดูท่าจะเป็นอีกแผนการของคิรินทอร์ นี่เป็นวัตถุทรงพลัง พ่อมดฝีมือสูงของคิรินทอร์เคยใช้มันชักนำพลังเวทอยู่บ่อย ๆ\n\nการที่พวกเขาส่งของพวกนี้ไปแอมเบอร์มิลล์มากขนาดนี้ แสดงว่าคงกำลังทำงานใหญ่\n\nข้าจะลองเจาะผ่านเกราะเวทของพวกเขาเพื่อดูว่าคิดจะทำอะไร" },
        required = { [3353] = { "22:1162476596:1879618800", "จี้สลักรูน" } },
        objectiveLabels = {
            item = { ["Rune-inscribed Pendant"] = "จี้สลักรูน" },
        },
    },
    [482] = { -- Dalaran's Intentions
        title = { "20:455689144:2008428036", "เจตนาของดาลารัน" },
        objective = { "51:130129846:2033166305", "คุยกับ Shadow Priest Allister ที่ Sepulcher" },
        description = { "490:1084909172:118784994", "จริงด้วย! ข้าลืมไปได้อย่างไร?\n\nแอมเบอร์มิลล์เป็นหนึ่งในพื้นที่ที่คิรินทอร์หมายตา เพราะมีจุดรวมพลังบนเส้นเวทที่ยังสงบนิ่ง พ่อมดพวกนั้นต้องคิดปลุกจุดรวมพลังแล้วใช้พลังนั้นทำงานใหญ่บางอย่างแน่\n\nเราจะปล่อยให้เกิดขึ้นไม่ได้...\n\nการปลุกพลังเส้นเวทในบริเวณนี้ต้องใช้พลังมหาศาล เราถ่วงพวกเขาได้ด้วยการเอาจี้ไปจากพ่อมด\n\nเอาเรื่องนี้ไปบอกอัลลิสเตอร์ เขาจะตัดสินใจว่าควรทำอย่างไร" },
        completion = { "20:520232477:1291904255 N 189:69914774:1690334769", "เจ้านำข่าวร้ายมา {name} หากดาลาร์คิดถูก ซึ่งข้าก็ไม่มีเหตุให้สงสัยเขา เราต้องรีบลงมือ\n\nข้าต้องปรึกษาเขาเรื่องแผนโจมตี ระหว่างนี้เราต้องถ่วงงานของพวกพ่อมดไว้" },
    },
    [491] = { -- Wand to Bethor
        title = { "14:645120080:963430441", "นำคทาไปให้เบธอร์" },
        objective = { "77:1096111349:2013352635", "นำ Woven Wand ไปให้ Bethor Iceshard ใน Magic Quarter ของ Undercity" },
        description = { "441:214487181:2051989445", "ธูลเคยเล่าให้ข้าฟังว่า นานมาแล้ว เขากับเพื่อนร่วมงานอีกสองคนสร้างคทาเวทขึ้นโดยถักทอคทาฝึกหัดของจอมเวทแต่ละคนเข้าด้วยกัน คทานี้เป็นสัญลักษณ์ของมิตรภาพ แม้ภายหลังธูลจะรังเกียจมัน เขาก็ยังตัดใจทิ้งไม่ได้ และไม่ยอมให้คนอื่นเก็บไว้ เขาจึงขโมยคทาไปซ่อนในปราสาทเฟนริส\n\nนี่ เอาคทาไปให้เบธอร์ ไอซ์ชาร์ด หนึ่งในเพื่อนเก่าของธูล ข้ามั่นใจว่าเขาคงอยากได้คืน" },
        progress = { "N 36:643402596:1657771526", "{name} เจ้าเอาชนะธูล เรเวนคลอว์แล้วหรือยัง?" },
        completion = { "291:1143667337:1081215143 N 23:731561890:1450512792", "...นี่อะไร? ธูลเก็บ Woven Wand ของเราไว้หรือ? ข้านึกว่ามันหายไปตอนมิตรภาพของเราแตกหักและเขาเข้าข้างลิชคิง!\n\nเขาคงไม่ได้เรียกใช้พลังของมัน ถ้าใช้ ข้าต้องสัมผัสได้ ดีนักที่เขาไม่ได้ใช้มัน...\n\nเป็นการค้นพบที่วิเศษมาก ข้าซาบซึ้งใจ {name} เจ้าจะได้รับรางวัล" },
        required = { [3425] = { "10:1488671636:921054206", "ไม้กายสิทธิ์สาน" } },
        steps = { { "10:1488671636:921054206", "ไม้กายสิทธิ์สาน" } },
    },
    [516] = { -- Beren's Peril
        title = { "13:2067393361:1334368132", "ภัยแห่งเบเรน" },
        objective = { "135:1682546894:1495571239", "หา Beren's Peril แล้วฆ่า Ravenclaw Drudger 6 ตัวและ Ravenclaw Guardian 6 ตัว จากนั้นกลับไปหา Shadow Priest Allister ที่ Sepulcher" },
        description = { "496:1189901177:1120800642", "ข้าได้รับรายงานว่าอันเดดกลุ่มหนึ่งกำลังซ่อนตัวเตรียมโจมตีเรา เมื่อรู้เรื่องนี้ เราก็ชิงลงมือโจมตีก่อนและทำลายแผนของพวกมันเสียแต่ต้นได้\n\nน่าเสียดายที่ข้อมูลของข้ายังขาด ๆ หาย ๆ มีรายงานว่าพวกมันซ่อนอยู่ในที่ที่เรียกว่า Beren's Peril ยังไม่รู้ตำแหน่งแน่ชัด แต่ดูเหมือนจะเป็นถ้ำบนเนินเขาใกล้กลุ่มพ่อมดดาลารัน\n\nข้าเชื่อว่าเจ้าหาทางได้ ตามหาพวกมันแล้วกำจัดเสีย" },
        progress = { "33:1318288142:514268824 N 25:1036803700:440459870", "เจ้าพบฐานของพวกมันหรือยัง {name}? เราชักช้าไม่ได้!" },
        completion = { "152:1900238709:1407135719", "หากหน่วยลาดตระเวนและสายของเรายังหาข่าวสำคัญเช่นนี้ได้ เราจะขับไล่สเคิร์จของลิชคิงออกจากดินแดนเราได้ในไม่ช้า" },
        objectiveLabels = {
            monster = { ["Ravenclaw Drudger slain"] = "ปราบ กุลี Ravenclaw", ["Ravenclaw Guardian slain"] = "ปราบ ผู้พิทักษ์ Ravenclaw" },
        },
    },
    [530] = { -- A Husband's Revenge
        title = { "19:726410929:23581194", "การล้างแค้นของสามี" },
        objective = { "72:1823947468:902468102", "ฆ่า Valdred Moray\n\nนำมือทั้งสองของเขาไปให้ Raleigh Andrean ใน Undercity" },
        description = { "298:976908545:2070862100", "วัลเดร็ดเคยเป็นเพื่อนสนิทของข้า แต่เขาคือคนฆ่าภรรยาข้า ถึงข้าจะโศกเศร้าไม่เป็นแล้ว ข้าก็ยังโหยหาการล้างแค้น หากเจ้าฆ่าวัลเดร็ดและนำมือชั่วช้าของมันมาให้ ข้าจะให้รางวัลเจ้า\n\nครั้งสุดท้ายที่ได้ข่าว มันอยู่ที่กำแพงเกรย์เมนทางใต้ของซิลเวอร์ไพน์ พยายามหนีเข้าอาณาจักรกิลเนียส" },
        progress = { "25:872265504:1133348299 N 1:63:63", "เจ้าเอามือพวกนั้นมาแล้วหรือยัง {name}?" },
        completion = { "335:214128470:149062", "อา ดีมาก มือคู่นี้ฆ่าดีไลอาห์ ภรรยาของข้า สิ่งเดียวที่ข้าต้องการคือแก้แค้นให้การตายของนาง และเจ้าก็ลงมือแก้แค้นให้ข้า\n\nนี่ เอาแหวนที่เจ้าคืนให้ก่อนหน้านี้ไปเถิด ดีไลอาห์ตายจากข้าไปนานแล้ว แหวนของนางเป็นเพียงเครื่องประดับที่ข้าไม่อยากเก็บอีก ส่วนมือคู่นี้ข้าจะเก็บไว้เตือนใจว่าเพื่อนเคยทรยศข้าอย่างไร" },
        required = { [3613] = { "15:119505483:1732803399", "มือทั้งสองของ Valdred" } },
        steps = { { "15:119505483:1732803399", "มือทั้งสองของ Valdred" } },
    },
    [6321] = { -- Supplying the Sepulcher
        title = { "23:420567793:1628239303", "จัดหาเสบียงให้เซพัลเชอร์" },
        objective = { "36:2109707351:1437024666", "นำ Podrig's Order ไปให้ Karos Razok" },
        description = { "499:716776183:5645214", "เอ็กเซคิวเตอร์แฮเดร็กให้ข้าตรวจนับอุปกรณ์ที่เซพัลเชอร์ เมื่อสเคิร์จและสิ่งที่เลวร้ายยิ่งกว่ายังซ่อนอยู่ในป่า เขาไม่อยากให้เดธการ์ดขาดเครื่องมือที่อาจต้องใช้\n\nข้าพบว่าโดยรวมเรามีของเพียงพอ แต่ต้องหาอาวุธเพิ่มเพื่อทดแทนที่สูญไปในสนามรบ\n\nนี่คือใบเบิกของที่เราต้องการสำหรับกอร์ดอน เวนดัม พ่อค้าอาวุธในอันเดอร์ซิตี เอาใบเบิกไปให้คารอส ราซ็อก ผู้ดูแลค้างคาวของเรา แล้วคุยกับเขาเรื่องการเดินทางไปอันเดอร์ซิตี" },
        progress = { "40:62165657:1033170453", "ดูเหมือนเจ้าจะมาทำธุระทางการ..." },
        completion = { "144:1213445162:1282077626", "อา ใบเบิกเสบียง เจ้าคงต้องนำไปอันเดอร์ซิตี รีบไปเถิด เราปล่อยให้เซพัลเชอร์ขาดเสบียงไม่ได้" },
        required = { [16209] = { "14:1573809973:1476672375", "ใบสั่งซื้อของ Podrig" } },
        steps = { { "14:1573809973:1476672375", "ใบสั่งซื้อของ Podrig" } },
    },
    [6322] = { -- Michael Garrett
        title = { "15:2121577593:305750873", "ไมเคิล การ์เร็ตต์" },
        objective = { "40:819196371:1510685324", "นำ Gordon's Crate ไปให้ Michael Garrett" },
        description = { "272:270350622:1592817039", "ข้าบรรจุเสบียงของเซพัลเชอร์ลงในลังนี้แล้ว หากเจ้าเคยไปเซพัลเชอร์และคุยกับผู้ดูแลค้างคาวที่นั่น เจ้าก็ขี่ค้างคาวกลับไปหาเขาได้\n\nจงคุยกับไมเคิล การ์เร็ตต์ ผู้ดูแลค้างคาวของอันเดอร์ซิตี เขาจัดค้างคาวพาเจ้าไปเซพัลเชอร์ได้" },
        progress = { "67:1539592003:102426322", "ถ้าต้องเดินทางไกล ค้างคาวเป็นทางเลือกที่ดีที่สุด" },
        completion = { "97:1948818351:2143258089", "ลังนี้ต้องไปถึงเซพัลเชอร์ในซิลเวอร์ไพน์หรือ? ง่ายมาก ค้างคาวของเราบินไปที่นั่นทุกวัน" },
        required = { [16210] = { "14:1185882972:1366872764", "ลังของ Gordon" } },
        steps = { { "14:1185882972:1366872764", "ลังของ Gordon" } },
    },
    [6323] = { -- Ride to the Undercity
        title = { "21:746352878:1676327120", "ขี่ค้างคาวไปอันเดอร์ซิตี" },
        objective = { "125:2006794859:428094538", "ซื้อเที่ยวบินค้างคาวไป Undercity จาก Karos Razok ผู้ดูแลค้างคาว แล้วนำ Podrig's Order ไปให้ Gordon Wendham ใน Undercity" },
        description = { "257:747875412:1382758491", "ค้างคาวตัวหนึ่งของข้าพาเจ้าไปอันเดอร์ซิตีได้โดยเสียค่าโดยสารเล็กน้อย เมื่อพร้อมแล้วคุยกับข้าอีกครั้ง จะได้จัดการเดินทางให้\n\nเจ้าจะพบกอร์ดอน เวนดัมในย่านการค้าของอันเดอร์ซิตี ซึ่งเป็นย่านเดียวกับที่ค้างคาวของข้าจะลงจอด" },
        progress = { "71:815842356:994570866", "ข้าดูแลอาวุธให้มีสภาพดีที่สุด ทำความสะอาดและเตรียมพร้อมใช้งานแล้ว" },
        completion = { "94:109873929:1141555958", "ใบเบิกจากเซพัลเชอร์หรือ? ได้เลย เป็นเกียรติที่ได้ช่วยผู้รับใช้เลดี้แห่งความมืดของเรา" },
        required = { [16209] = { "14:1573809973:1476672375", "ใบสั่งซื้อของ Podrig" } },
        steps = { { "14:1573809973:1476672375", "ใบสั่งซื้อของ Podrig" } },
    },
    [6324] = { -- Return to Podrig
        title = { "16:1090428685:1786760446", "กลับไปหาโพดริก" },
        objective = { "133:707738852:352683236", "ซื้อเที่ยวบินค้างคาวไป Sepulcher จาก Michael Garrett ผู้ดูแลค้างคาว แล้วนำ Gordon's Crate ไปให้ Deathguard Podrig ที่ Sepulcher" },
        description = { "379:47912659:1672992128", "ผู้ดูแลค้างคาวที่เซพัลเชอร์คือคารอส ราซ็อก หากเจ้าเคยพบเขาแล้ว ข้าก็จัดค้างคาวพาเจ้าบินกลับไปหาเขาได้\n\nค้างคาวของเราบินไปอันเดอร์ซิตีได้เสมอ แต่หากจะไปพื้นที่ห่างไกล ผู้โดยสารต้องไปถึงพื้นที่นั้นและคุยกับผู้ดูแลค้างคาวก่อน\n\nเจ้าเคยพบคารอสที่เซพัลเชอร์แล้ว ตอนนี้จึงขี่ค้างคาวไปที่นั่นได้ คุยกับข้าอีกครั้งเมื่อพร้อม" },
        progress = { "N 58:1486621902:1567206011", "{name} เจ้ากลับมาแล้ว ได้เสบียงของเราจากอันเดอร์ซิตีมาหรือไม่?" },
        completion = { "11:354343371:1318038540 N 124:973711880:1850166986", "ทำได้ดี {name} อาวุธพวกนี้จะช่วยให้เดธการ์ดของเราพร้อมรับมือเหตุฉุกเฉิน\n\nเจ้าทำงานที่มีค่าให้เลดี้แห่งความมืดของเรา" },
        required = { [16210] = { "14:1185882972:1366872764", "ลังของ Gordon" } },
        steps = { { "14:1185882972:1366872764", "ลังของ Gordon" } },
    },
    [91920] = { -- Wild Eyes
        title = { "9:2051882277:1675113239", "ดวงตาแห่งพงไพร" },
        objective = { "77:1295509942:791546950", "รวบรวมดวงตาเมอร์ล็อก 3 ดวง แล้วนำไปให้ Apothecary Renferrel ที่ Sepulcher" },
        description = { "504:1287112407:1831251460", "ข้าไม่กล้าสงสัยประสิทธิภาพสูตรยาของนักปรุงยาเรนเฟอร์เรลหรอก แต่ถ้าบอกว่ากินยาแล้วเห็นผลอะไรชัดเจน ข้าก็คงพูดปด\n\nริมทะเลสาบลอร์ดาเมียร์มีเมอร์ล็อกอยู่เป็นฝูง และที่สำคัญคือเมอร์ล็อกมีตา ข้าสงสัยว่าช่วงนี้นักปรุงยาหมกมุ่นกับหัวใจจนไม่อยากลองอะไรใหม่ ๆ เอาตาไปให้เขาสักสองสามดวงสิ\n\nถ้าต้องเลือกระหว่างตายครั้งที่สองอย่างเลี่ยงไม่ได้กับถูกเรนเฟอร์เรลฆ่าเพราะสงสัยวิธีของเขา ข้าเลือกอย่างหลัง" },
        progress = { "16:606539186:1655479053", "อ้อ เจ้ากลับมาแล้วหรือ?" },
        completion = { "339:409079968:229258591", "ยาไม่ได้ผลหรือ? แน่ละว่ามันไม่ได้ผล เจ้าเอาหัวใจมาไม่พอ สูตรบอกชัด ๆ ว่าต้องใช้หกดวง เจ้าเอามาแค่สาม\n\nแต่ข้ายอมรับว่าไม่เคยคิดจะใช้ชิ้นส่วนเมอร์ล็อกมาก่อน...\n\n<เรนเฟอร์เรลรับดวงตาไป>\n\nข้าพอจะยอมสละหัวใจของข้าสักสองสามดวงเพื่อให้เดธสตอล์กเกอร์ของเจ้ากลับมามีเรี่ยวแรงได้" },
        required = { [730] = { "10:1115274483:723062552", "ดวงตาเมอร์ล็อก" } },
        steps = { { "10:1115274483:723062552", "ดวงตาเมอร์ล็อก" } },
    },
    [91921] = { -- Return to Quinn (Again)
        objective = { "79:1974766584:2114314160", "นำยาของ Quinn ไปให้ Quinn Yorick ที่ Ivar Patch ทางเหนือของ Sepulcher" },
        title = { "23:728170661:596114841", "กลับไปหาควินน์อีกครั้ง" },
        description = { "170:2128297612:1878488685", "นี่คือยาใหม่สำหรับช่วยให้ควินน์ฟื้นตัว ปรุงด้วยความรักที่สกัดจากหัวใจเต็ม ๆ หกดวง\n\nทีนี้ขอให้ข้าได้ทำงานต่อเถิด ก่อนที่การอยู่ของเจ้าจะทำให้ข้าต้องจัดการเอกสารเพิ่ม" },
        progress = { "73:1286096822:2014150952", "เจ้ากลับมาแล้ว! ข้ากำลังเริ่มทำใจว่าจะถอยกลับไปเป็นกูลเสียแล้ว" },
        completion = { "131:613973718:350311626 N 1:46:46", "<ควินน์รับยาแล้วดื่ม>\n\nใช่ ข้ารู้สึกได้ว่ายาเริ่มออกฤทธิ์ อีกไม่นานข้าจะเดินทางได้\n\nเจ้าช่วยข้าไว้มากจริง ๆ {name}" },
        required = { [248930] = { "14:1267128816:1712274192", "ยาของ Quinn" } },
        steps = { { "14:1267128816:1712274192", "ยาของ Quinn" } },
    },
    [95883] = { -- The Tortured Soul
        title = { "17:294080768:529462364", "วิญญาณที่ถูกทรมาน" },
        objective = { "85:2009051366:571763962", "เก็บ Tortured Soul จากอันเดดใกล้ ๆ ใน Beren's Peril ที่ Silverpine Forest" },
        description = { "295:1713842050:2053995006", "<ของที่เตรียมไว้สำหรับพิธีกรรมซึ่งจัดขึ้นอย่างเร่งรีบถูกวางระเกะระกะบนแท่นบูชา เศษบันทึกระบุว่ารวบรวมของครบแล้ว เหลือเพียงเลือดถวายกับ Tortured Soul\n\nอันเดดรอบตัวเจ้าดูทุกข์ทรมานพอสมควร พวกมันอาจมีสิ่งที่เจ้าตามหา>" },
        completion = { "131:320750809:2046829577", "วิญญาณที่ถูกทรมานปล่อยพลังชั่วร้ายออกมาเมื่ออยู่ใกล้ศิลาถวายเครื่องบูชา\n\nดูเหมือนเจ้าจะใกล้ทำพิธีสำเร็จแล้ว", variants = { { "133:859546358:418266064", "<วิญญาณที่ถูกทรมานปล่อยพลังชั่วร้ายออกมาเมื่ออยู่ใกล้ศิลาถวายเครื่องบูชา\n\nดูเหมือนเจ้าจะใกล้ทำพิธีสำเร็จแล้ว>" } } },
        progress = { "40:1156303518:1840714068", "<ศิลาถวายเครื่องบูชานิ่งเงียบเป็นลางร้าย>" },
        required = { [271350] = { "13:557018154:574277064", "วิญญาณที่ถูกทรมาน" } },
        steps = { { "13:557018154:574277064", "วิญญาณที่ถูกทรมาน" } },
    },
    [95884] = { -- The Offering Stone
        title = { "18:217148901:1887550729", "ศิลาถวายเครื่องบูชา" },
        objective = { "62:1557916492:102575633", "หา Offering Stone ใน Beren's Peril ที่ Silverpine Forest" },
        description = { "221:136752822:1193022987", "<เศษบันทึกนี้ส่วนใหญ่อ่านไม่ออก ส่วนที่ยังอ่านได้กล่าวถึงการเตรียมเครื่องบูชา\n\nมีการกล่าวถึงศิลาถวายเครื่องบูชาและพิธีกรรม\n\nบางทีเจ้าอาจพบศิลานี้แถว ๆ นี้>" },
        completion = { "132:1077212389:297428584", "เครื่องมือและสิ่งของประหลาดวางเกลื่อนผิวหินขรุขระ\n\nนี่ต้องเป็นศิลาถวายเครื่องบูชาที่กล่าวถึงในบันทึกแน่", variants = { { "134:1334253664:14059808", "<เครื่องมือและสิ่งของประหลาดวางเกลื่อนผิวหินขรุขระ\n\nนี่ต้องเป็นศิลาถวายเครื่องบูชาที่กล่าวถึงในบันทึกแน่>" } } },
    },
    [95885] = { -- The Offering of Blood
        title = { "21:1146305063:1473249000", "ถวายเลือด" },
        objective = { "90:1785109905:1999268310", "ใช้ Tortured Soul เพื่อถวายเลือดที่ Offering Stone ใน Beren's Peril" },
        description = { "138:1913618547:1206600481", "<ตอนนี้เหลือเพียงการถวายเลือด\n\nเศษบันทึกกล่าวถึง “ผู้ยอมสละตนโดยสมัครใจ”\n\nความหวาดผวาถาโถมเข้าใส่เจ้า>" },
        completion = { "233:2072923758:1212767844", "ศิลาถวายเครื่องบูชาไม่ตอบสนองแล้ว ดูเหมือนพิธีของเจ้าจะดูดพลังออกไปจนหมด เจ้าไม่รู้ว่าทำไปเพื่ออะไร แต่ทุกอย่างจบลงแล้ว\n\nหินขรุขระแตกร้าวและพังทลาย เมื่อไม่มีหน้าที่อีกต่อไป\n\nมีบางอย่างส่องประกายอยู่ในซากหิน...", variants = { { "235:1989890413:2069052083", "<ศิลาถวายเครื่องบูชาไม่ตอบสนองแล้ว ดูเหมือนพิธีของเจ้าจะดูดพลังออกไปจนหมด เจ้าไม่รู้ว่าทำไปเพื่ออะไร แต่ทุกอย่างจบลงแล้ว\n\nหินขรุขระแตกร้าวและพังทลาย เมื่อไม่มีหน้าที่อีกต่อไป\n\nมีบางอย่างส่องประกายอยู่ในซากหิน...>" } } },
        progress = { "40:1156303518:1840714068", "<ศิลาบูชานิ่งสงบจนน่าขนลุก>" },
        steps = { { "21:874326879:338343185", "ยอมมอบเลือดด้วยความสมัครใจ" }, { "21:850414343:1802329309", "ปล่อยวิญญาณที่ถูกทรมาน" } },
    },
    [95981] = { -- Watching the Roads
        title = { "18:1962718990:1355425550", "เฝ้าระวังเส้นทาง" },
        objective = { "90:1042485407:903201231", "สังหาร Dalaran Wizard 8 คนและ Dalaran Watcher 8 คนให้ Shadow Priest Allister ที่ Sepulcher", amount = { "5:1000000866:1065647852 W1 21:1606935529:597391727 W2 62:1997937797:752049629", "สังหาร Dalaran Wizard {world1} คนและ Dalaran Watcher {world2} คนให้ Shadow Priest Allister ที่ Sepulcher" } },
        description = { "426:1360084167:549089106", "การเอาจี้ไปจากพวกมันเป็นเพียงก้าวแรก หากคิรินทอร์ส่งวัตถุโบราณจากดาลารันมาไม่ขาดสายจริง เราต้องสกัดตั้งแต่ต้นทาง\n\nค้นหาพ่อมดและหน่วยเฝ้าระวังของดาลารันตามถนนรอบแอมเบอร์มิลล์ พวกมันเปิดทางให้คนข้ามเขตแดนเราได้ตามใจมานานเกินไป หากเราลดจำนวนพวกมันลงได้ ก็น่าจะหยุดจี้เหล่านี้ก่อนจะเข้ามาถึงป่าซิลเวอร์ไพน์" },
        progress = { { "90:1916529506:314494165", "79:556251320:563448974 N 1:33:33", "79:556251320:563448974 C 1:33:33", "79:556251320:563448974 R 1:33:33" }, "ทุกขณะที่เราชักช้า มีของอีกเที่ยวมาถึงหน้าประตูเรา กำจัดพวกมันเสีย นักผจญภัย!" },
        completion = { "202:972724553:843146117", "ตั้งแต่ม่านพลังรอบดาลารันหายไป คิรินทอร์ก็คุมถนนอย่างเข้มงวด พวกมันหวาดระแวงอะไรบางอย่างแน่ ๆ\n\nแต่ตอนนี้จะเพราะอะไรก็ไม่สำคัญ" },
        objectiveLabels = {
            monster = { ["Dalaran Watcher slain"] = "ปราบ ผู้เฝ้าระวังแห่ง Dalaran", ["Dalaran Wizard slain"] = "ปราบ พ่อมดแห่ง Dalaran" },
        },
    },
    [98298] = { -- Arugal's Folly
        title = { "14:411206350:1668572509", "ความเขลาของอารูกัล" },
        objective = { "57:638943209:1456446717", "นำ Worgen Bits 6 ชิ้นไปให้ Dalar Dawnweaver ที่ Sepulcher", amount = { "6:1273960851:929420321 W1 50:707279553:1114338811", "นำ Worgen Bits {world1} ชิ้นไปให้ Dalar Dawnweaver ที่ Sepulcher" } },
        description = { "505:1358798748:360819720", "อา เรื่องมันชัดเสียจนข้าน่าจะรู้ตั้งนานแล้ว! อารูกัลแทบไม่มีพลังเวท นับประสาอะไรกับพลังพอจะสร้างวอร์เกน “คำสาปอารูกัล” งั้นหรือ ถุย! ฤทธิ์ยังอยู่ได้ไม่กี่วินาทีด้วยซ้ำ\n\nเครื่องพันธนาการพวกนี้พิสูจน์ว่าเขาสะกดสัตว์พวกนั้นไว้ได้ ส่วนการสร้างพวกมันนั้นเกินความสามารถของเขา เห็นชัดว่าวอร์เกนแพร่คำสาปด้วยวิธีอื่น ข้าอยากรู้ว่าทำอย่างไร\n\nไปกำแพงเกรย์เมนทางใต้ ดูเหมือนวอร์เกนกำลังแพร่คำสาปไปสู่มนุษย์ใกล้ ๆ ฉีกพวกมันเป็นชิ้นแล้วนำสิ่งที่พบมาให้ข้า เรื่องนี้ต้องใช้วิธีตรงไปตรงมากว่านี้" },
        progress = { "117:471893965:297241824", "เขี้ยว กรงเล็บ กระเพาะบด ข้าเอาหมด วิธีศึกษาที่ง่ายที่สุดคือดูเครื่องในด้วยตาตัวเอง" },
        completion = { "357:509513015:61447267", "ดูเหมือนข้าจะเป็นฝ่ายได้หัวเราะทีหลัง ฮ่า ๆ! อารูกัลมันโง่จริง ๆ และข้า ดาลาร์ ดอว์นวีฟเวอร์ ก็เปิดโปงมันได้ว่าเป็นจอมลวงโลก\n\nชิ้นส่วนเหล่านี้เป็นหลักฐานมากพอแล้วว่าคำสาปไม่มีส่วนเกี่ยวข้องกับเจ้างั่งนั่น\n\nน่าเสียดายที่นั่นทำให้วิธีรักษาของมันไร้ค่าด้วย ดูท่าเราต้องหาทางแก้คำสาปวอร์เกนต่อไป" },
        required = { [280375] = { "11:449492878:1786068251", "ชิ้นส่วนจากวอร์เกน" } },
        steps = { { "11:449492878:1786068251", "ชิ้นส่วนจากวอร์เกน" } },
    },
    [98299] = { -- Stop the Spread
        title = { "15:879257870:374922591", "หยุดการแพร่คำสาป" },
        objective = { "84:1767711166:780156470", "สังหาร Sickly Refugee 5 คนและ Haggard Refugee 5 คนให้ Dalar Dawnweaver ที่ Sepulcher", amount = { "5:1000000866:1065647852 W1 21:27411763:9085755 W2 56:1307016000:1466887201", "สังหาร Sickly Refugee {world1} คนและ Haggard Refugee {world2} คนให้ Dalar Dawnweaver ที่ Sepulcher" } },
        description = { "494:2124048470:540005152 R 1:46:46", "เรื่องหนึ่งที่เรารู้แน่คืออารูกัลมีส่วนรับผิดชอบที่มีวอร์เกนอยู่ในซิลเวอร์ไพน์ จะด้วยแผนของมันเองหรือด้วยเหตุอื่นก็ตาม ส่วนวิธีที่คำสาปแพร่ไปนั้นเรายังไม่รู้\n\nระหว่างที่ข้าหาทางหยุดคำสาป สิ่งเร่งด่วนที่สุดคือจำกัดวงไว้ ดูเหมือนคำสาปนี้จะไม่ติดต่อถึงฟอร์เซเคน แต่มนุษย์กลุ่มใหญ่ไปรวมตัวกันที่กำแพงเกรย์เมน\n\nไปที่กำแพงแล้วกำจัดผู้ลี้ภัยพวกนั้นก่อนที่พวกเขาจะกลายเป็นสมุนอารูกัล แล้วระวังอย่าให้โดนกัดล่ะ {race}", variants = { { "487:902859977:542086662", "เรื่องหนึ่งที่เรารู้แน่คืออารูกัลมีส่วนรับผิดชอบที่มีวอร์เกนอยู่ในซิลเวอร์ไพน์ จะด้วยแผนของมันเองหรือด้วยเหตุอื่นก็ตาม ส่วนวิธีที่คำสาปแพร่ไปนั้นเรายังไม่รู้\n\nระหว่างที่ข้าหาทางหยุดคำสาป สิ่งเร่งด่วนที่สุดคือจำกัดวงไว้ ดูเหมือนคำสาปนี้จะไม่ติดต่อถึงฟอร์เซเคนอย่างพวกเรา แต่มนุษย์กลุ่มใหญ่ไปรวมตัวกันที่กำแพงเกรย์เมน\n\nไปที่กำแพงแล้วกำจัดผู้ลี้ภัยพวกนั้นก่อนที่พวกเขาจะกลายเป็นสมุนอารูกัล" }, { "503:1944200827:1833674849", "เรื่องหนึ่งที่เรารู้แน่คืออารูกัลมีส่วนรับผิดชอบที่มีวอร์เกนอยู่ในซิลเวอร์ไพน์ จะด้วยแผนของมันเองหรือด้วยเหตุอื่นก็ตาม ส่วนวิธีที่คำสาปแพร่ไปนั้นเรายังไม่รู้\n\nระหว่างที่ข้าหาทางหยุดคำสาป สิ่งเร่งด่วนที่สุดคือจำกัดวงไว้ ดูเหมือนคำสาปนี้จะไม่ติดต่อถึงฟอร์เซเคน แต่มนุษย์กลุ่มใหญ่ไปรวมตัวกันที่กำแพงเกรย์เมน\n\nไปที่กำแพงแล้วกำจัดผู้ลี้ภัยพวกนั้นก่อนที่พวกเขาจะกลายเป็นสมุนอารูกัล แล้วระวังอย่าให้โดนกัดล่ะ skyborne" } } },
        completion = { "251:1007553534:489304046", "ดูเหมือนชาวกิลเนียสจะไม่เต็มใจให้ใครผ่านกำแพงเข้าไป ข้าว่านั่นเป็นโชคดี เพราะคำสาปวอร์เกนคงไม่มีทางแพร่เข้าเมืองของพวกเขา\n\nนึกออกไหมว่าหากติดคำสาปกันทั้งอาณาจักรจะเสื่อมทรามกันขนาดไหน?" },
        progress = { "147:2047350268:371003633", "กองทัพผู้ลี้ภัยที่เจ็บป่วยน่ะไม่น่าห่วง แต่ถ้ามีอสูรวอร์เกนเพิ่มขึ้นอีกฝูงก็คนละเรื่อง ไปจัดการพวกมันเสียบ้าง ก่อนที่พวกเราจะถูกบุกจนตั้งตัวไม่ทัน" },
        objectiveLabels = {
            monster = { ["Haggard Refugee slain"] = "ปราบ ผู้ลี้ภัยซูบโทรม", ["Sickly Refugee slain"] = "ปราบ ผู้ลี้ภัยที่ป่วยไข้" },
        },
    },
    [784] = { -- Vanquish the Betrayers
        title = { "22:1234174266:1681247880", "ปราบผู้ทรยศ" },
        objective = { "108:76223333:1549343082", "สังหาร Kul Tiras Sailor 10 คน, Kul Tiras Marine 8 คน และ Lieutenant Benedict แล้วกลับไปหา Gar'Thok ที่ Razor Hill" },
        description = { "493:2023085510:208024200", "มนุษย์แห่งคูลทีราสภายใต้การนำของพลเรือเอกพราวด์มัวร์รุกล้ำดูโรทาร์ ละเมิดข้อตกลงที่ขุนศึกทำไว้กับเจน่า พราวด์มัวร์เมื่อหลายปีก่อนเพื่อเอาชนะอาร์คิมอนด์\n\nเราตีโต้การรุกรานของมนุษย์จนป้อมทิราการ์ดแตก แต่ไม่นานมานี้ กองหนุนของพลเรือเอกที่นำโดยร้อยโทเบเนดิกต์กลับมายึดป้อมคืน พวกมันเป็นภัยต่อบ้านเกิดของเราอีกครั้ง มนุษย์พวกนี้ไม่เห็นค่าการเจรจาเลย\n\nพิสูจน์เกียรติของเจ้า มุ่งลงใต้ไปยังป้อมทิราการ์ดและกำจัดมนุษย์ผู้รุกราน" },
        progress = { "22:732849797:587055223 N 153:322796518:1223100683", "เจ้ารู้คำสั่งแล้ว {name} ความปลอดภัยของดูโรทาร์กำลังสั่นคลอน จงทำงานตรงหน้าให้สำเร็จ มิฉะนั้นก็จงก้มหน้ารับความอับอาย\n\nแสดงเกียรติของเจ้าและเอาชนะมนุษย์แห่งป้อมทิราการ์ด" },
        completion = { "35:822338578:1751285312 C 72:2137469172:249876486", "ข่าวความกล้าของเจ้าแพร่ไปเร็วเหลือเกิน {class} ผู้คนในออร์กริมมาร์จะกล่าวขานถึงชัยชนะของเจ้าที่ป้อมทิราการ์ด" },
        objectiveLabels = {
            monster = { ["Kul Tiras Sailor slain"] = "ปราบ กะลาสีแห่ง Kul Tiras", ["Kul Tiras Marine slain"] = "ปราบ ทหารนาวิกโยธินแห่ง Kul Tiras", ["Lieutenant Benedict slain"] = "ปราบ นายร้อย Benedict" },
        },
    },
    [786] = { -- Thwarting Kolkar Aggression
        title = { "27:1055206600:441614212", "สกัดการรุกรานของโคลคาร์" },
        objective = { "113:1096096915:1103921069", "Lar Prowltusk ที่อยู่นอก Sen'jin Village ต้องการให้เจ้าทำลาย Attack Plans ทั้ง 3 ชุดใน Kolkar Crag" },
        description = { "18:570052052:1625568228 C 458:537878982:1172936235", "เบาเสียงหน่อย {class} เซนทอร์โคลคาร์อยู่เลยสันเขาไปทางตะวันตกที่โคลคาร์แคร็ก\n\nเมื่อคืนข้าแอบเข้าไปในหมู่บ้านของพวกมันตอนที่พวกมันออกปล้น แล้วพบว่าเจ้าสัตว์สกปรกพวกนั้นวางแผนโจมตีโทรลล์กับออร์คแห่งดูโรทาร์ไว้สามขั้น\n\nเราจะปล่อยให้การรุกรานเกิดขึ้นไม่ได้ เจ้าอาจรวบรวมกำลังพอจะแทรกเข้าโคลคาร์แคร็กแล้วทำลายแผนโจมตีของพวกมันได้\n\nครั้งสุดท้ายที่ข้าเห็น พวกมันแบ่งแผนไว้กับหัวหน้าสามคน" },
        progress = { "133:1448927292:820721873", "พวกเซนทอร์คอยก่อกวนฮอร์ดอยู่เรื่อย เราจะยอมให้พวกมันมาล้อมโจมตีบ้านเกิดเราไม่ได้" },
        completion = { "328:2096613247:1613550693 C 1:46:46", "หากเซนทอร์โคลคาร์บุกมา ฮอร์ดต้องชนะอยู่แล้ว แต่การสกัดการโจมตีครั้งนี้ช่วยให้นักรบกล้าของเราไม่ต้องเสียเลือดโดยเปล่าประโยชน์\n\nตราบใดที่ทะเลทรายทานาริสยังมีทราย ตราบนั้นเราก็รู้ว่าจะต้องมีการนองเลือดก่อนช่วงเวลาอันยากลำบากนี้จะผ่านพ้น\n\nเจ้ารับใช้พวกพ้องได้ดี {class}" },
        steps = { { "39:1202383148:1759971501", "ทำลายแผนโจมตี Valley of Trials" }, { "38:1471900444:1084171166", "ทำลายแผนโจมตี Sen'jin Village" }, { "32:1521896068:1267674959", "ทำลายแผนโจมตี Orgrimmar" } },
    },
    [791] = { -- Carry Your Weight
        title = { "17:431701859:1069198459", "แบกสัมภาระของเจ้า" },
        objective = { "66:1098846890:529828349", "Furl Scornbrow บนหอเฝ้าระวัง Razor Hill ต้องการ Canvas Scraps 8 ชิ้น" },
        description = { "457:1276703598:1788108129", "อายุทำให้ข้าลงสนามรบไม่ไหว ตอนนี้ข้าจึงช่วยด้วยวิธีอื่น\n\nข้าเฝ้าดูผู้รุกรานจากจุดนี้ ยิ่งกำลังของเราที่นี่แข็งแกร่งขึ้น ข้าก็ยิ่งได้เป่าแตรเตือนภัยน้อยลง\n\nยามว่างข้าทำข้าวของให้นักรบหนุ่มที่ยังมีกำลังใช้ปกป้องบ้านเกิดของเรา\n\nข้าทำกระเป๋าใส่ของให้เจ้าได้ หากคิดว่าจะได้ใช้ ก็เอาผ้าใบมาให้ข้าบ้าง มนุษย์กับเซนทอร์ใช้ผ้าชนิดนี้กันมาก" },
        progress = { "377:1325586965:522151768", "ข้าเคยต่อสู้เคียงข้างขุนศึกอย่างภาคภูมิเมื่อเราบุกเบิกดินแดนแห่งนี้ รอยแผลบนผิวข้ายังบอกเล่าการต่อสู้เหล่านั้น\n\nข้าช่วยรักษาเกียรติของฮอร์ดด้วยขวานและเสียงโห่รบในศึกโค่นอาร์คิมอนด์ ตอนนั้นเราจำต้องจับมือกับมนุษย์และเอลฟ์เป็นพันธมิตรที่ฝืนใจนัก\n\nแต่การได้เป็นคนเฝ้ายามและจัดหาของก็ทำให้ข้ารู้สึกว่าตนยังมีค่า" },
        completion = { "16:959884130:63492255 N 11:1029285398:1435652758 C 125:156120243:2066944900", "ยอดเยี่ยม {name} {class} ฝีมือดีอย่างเจ้าคงหาทางใช้กระเป๋านี้ในสนามรบได้\n\nข้าขอคารวะความมุ่งมั่นและใจที่พร้อมพลีชีพเพื่อฮอร์ดของเจ้า!" },
        required = { [4870] = { "13:807394880:981710584", "เศษผ้าใบ" } },
        steps = { { "13:807394880:981710584", "เศษผ้าใบ" } },
    },
    [806] = { -- Dark Storms
        title = { "11:1225385624:1399668663", "พายุทมิฬ" },
        objective = { "53:997276145:876615971", "นำ Fizzle's Claw ไปให้ Orgnil Soulscar ที่ Razor Hill" },
        description = { "361:1728541731:86693636", "เราจะปล่อยให้เบิร์นนิงเบลดตั้งหลักในดูโรทาร์ไม่ได้! ต้องทำลายพวกมันก่อนความชั่วจะลุกลาม!\n\nข้าสืบด้วยตัวเองจนพบว่าก็อบลินวอร์ล็อกของเบิร์นนิงเบลด ฟิซเซิล ดาร์กสตอร์ม ตั้งค่ายอยู่ในธันเดอร์ริดจ์ทางตะวันตกเฉียงเหนือ มันกับสมุนลัทธิคอยก่อความโกลาหลอยู่ที่นั่น\n\nตามหาและกำจัดฟิซเซิล แล้วเอากรงเล็บของมันมาให้ข้า!" },
        progress = { "21:1750777860:889850906 N 68:111997417:1108115858", "เจ้าพบฟิซเซิลหรือยัง {name}? ต้องกวาดล้างมันกับเบิร์นนิงเบลดที่เหลือออกจากดินแดนเรา!" },
        completion = { "42:1132115942:497371042 N 64:498437851:2042643038", "อาฮ่า! เจ้าจัดการมันได้แล้ว!\n\nเจ้าทำให้เผ่าภูมิใจ {name} เพราะเจ้าดูโรทาร์จึงพ้นจากสมุนชั่วไปอีกหนึ่ง" },
        required = { [4869] = { "13:327208261:1903418517", "กรงเล็บของ Fizzle" } },
        steps = { { "13:327208261:1903418517", "กรงเล็บของ Fizzle" } },
    },
    [808] = { -- Minshina's Skull
        title = { "16:1954619482:1190016816", "กะโหลกของมินชินา" },
        objective = { "115:746611493:659136", "นำกะโหลกของ Minshina ออกจากวงเวทบน Echo Isles\n\nนำไปให้ Master Gadrin ที่ Sen'jin Village" },
        description = { "422:1955904582:816863657 N 74:410963700:2052556582", "ข้าได้ยินเสียงมินชินา พี่น้องของข้า เรียกหาในฝัน\n\nซาลาซาน วอร์ล็อกบนเกาะเอคโคทางตะวันออก จับเขาไป เขาตายแล้ว\n\nแต่ความตายยังไม่ปลดปล่อยพี่น้องของข้า วิญญาณของมินชินาถูกเวทของซาลาซานขังไว้ในกะโหลกของตัวเอง ในฝันข้าเห็นกะโหลกของเขาอยู่กับกะโหลกอื่น ๆ ในวงเวทบนเกาะเอคโคที่ใหญ่ที่สุด ตราบใดที่กะโหลกยังอยู่ตรงนั้น วิญญาณเขาก็ต้องทนทุกข์\n\nขอร้องล่ะ {name} หาวงเวทและเอากะโหลกของมินชินากลับมาให้ข้า\n\nปลดปล่อยเขาที!" },
        progress = { "32:1772657149:1306284236 N 21:293526973:1809384402", "เจ้าได้กะโหลกพี่น้องของข้ามาหรือยัง {name}? ในที่สุดเขาเป็นอิสระแล้วหรือ?" },
        completion = { "11:1191658970:1224418299 N 75:105741038:664247413", "ขอบใจ {name} เจ้าช่วยมินชินาไว้ เจ้าปลดวิญญาณพี่น้องของข้าจากการเป็นทาส!" },
        required = { [4864] = { "16:1954619482:1190016816", "กะโหลกของ Minshina" } },
        steps = { { "16:1954619482:1190016816", "กะโหลกของ Minshina" } },
    },
    [809] = { -- Ak'Zeloth
        title = { "9:2103287631:1988828272", "อักเซล็อธ" },
        objective = { "36:1534490982:892140118", "คุยกับ Ak'Zeloth ใน Barrens" },
        description = { "493:102049924:1538948779", "นับตั้งแต่เบิร์นนิงลีเจียนพ่ายแพ้ในสงครามใหญ่ครั้งก่อน ข้าก็ตามหาต้นตออำนาจปีศาจที่กัดกร่อนสังคมออร์ค ปลอกคอที่เจ้านำมายืนยันสิ่งที่ข้ากลัว\n\nมันเป็นของเบิร์นนิงเบลด ลัทธิที่รวมตัวรอบวัตถุเปี่ยมพลังปีศาจ ชื่อว่า Demon Seed มันอยู่บนยอดเดรดมิสต์ในแบร์เรนส์ ต้องทำลายมัน!\n\nไปที่ฟาร์วอตช์โพสต์ ตรงชายแดนแบร์เรนส์ทางตะวันตก แล้วคุยกับอักเซล็อธ ผู้ช่วยของข้า เขาจะแนะนำว่าต้องทำอะไรต่อ" },
        completion = { "135:926236279:1860482719", "นีรูอยากให้ทำลาย Demon Seed งั้นหรือ? แปลกจริง...\n\nเอาเถิด หากเขาอยากกำจัดเมล็ดนั้น ข้าจะบอกวิธีให้เจ้า" },
        objectiveLabels = {
            event = { ["Destroy the Demon Seed"] = "ทำลาย Demon Seed" },
        },
    },
    [812] = { -- Need for a Cure
        title = { "15:1233551491:1905494080", "ต้องหายารักษา" },
        objective = { "133:421199213:1403617420", "ตามหา Kor'ghan ใน Orgrimmar เพื่อรับ Venomtail Antidote แล้วนำยาถอนพิษไปให้ Rhinag ใกล้พรมแดนด้านตะวันตกเฉียงเหนือของ Durotar" },
        description = { "N 393:13771220:1685098991 N 75:303118452:878167563", "{name}... เจ้ามาทันเวลาพอดี หวังว่าข้าจะได้ชมว่าเจ้าไปกลับเร็วด้วย\n\nข้าประมาทตอนสู้กับเวนอมเทลแถวนี้ ถูกตัวหนึ่งต่อยเข้าเต็ม ๆ พิษทำให้ข้าอ่อนแรงลงแม้แต่ตอนที่เราคุยกัน หากเป็นแบบนี้ ข้าคงอยู่ได้อีกสักชั่วโมง ต้องให้เจ้าช่วยแล้วล่ะ...\n\nคอร์กานในออร์กริมมาร์รู้วิธีปรุงยาถอนพิษ ตามหาเขา... แล้วรีบไป {name} ข้าคงทนได้อีกไม่นาน เขาน่าจะอยู่ในเคลฟต์ออฟชาโดว์" },
        progress = { "104:1635416201:115582175", "ข้าเกือบจะดีใจที่กลับเซนจินในสภาพนี้ไม่ได้ ความอ่อนแอกับความโง่ของข้าคงโดนล้อแน่" },
        completion = { "N 318:487617478:2058569370", "{name} เจ้าช่วยชีวิตข้าไว้ ขอบใจ\n\nรับนี่ไปเถอะ หวังว่าจะช่วยเจ้าเดินทางได้บ้าง หรืออย่างน้อยก็ขายได้สักหน่อย ฟังจากที่เจ้าบอก ข้าคงไม่ได้ใช้มันในเร็ว ๆ นี้ คอร์กานจะให้ข้าทำพิธีของเขาอีกจนกว่าจะพิสูจน์ตนได้ ฆ่าหมูป่าอีก เก็บหางสกอร์พิดอีก... <ถอนหายใจ>" },
        required = { [4904] = { "18:1175918672:981968904", "ยาแก้พิษ Venomtail" } },
        steps = { { "18:1175918672:981968904", "ยาแก้พิษ Venomtail" } },
    },
    [813] = { -- Finding the Antidote
        title = { "20:1306875707:276800676", "หายาถอนพิษ" },
        objective = { "55:782711279:835778463", "นำ Venomtail Poison Sac 4 ชิ้นไปให้ Kor'ghan ใน Orgrimmar" },
        description = { "338:524515255:314567994 N 33:41603641:709821039", "เวนอมเทลเป็นสกอร์พิดที่อันตรายที่สุดชนิดหนึ่งในดูโรทาร์ ไรนากไม่น่าไปล่าพวกมันโดยไม่พกยาถอนพิษเลย แต่ตอนนี้เขาต้องการความช่วยเหลือมากกว่าคำตำหนิ\n\nเอาถุงพิษจากเวนอมเทลแถวทางเข้าออร์กริมมาร์มาให้ข้าสักหน่อย ข้าจะปรุงยาถอนพิษให้เขา\n\nรีบหน่อย {name} พวกพ้องของเราคนหนึ่งกำลังต้องการความช่วยเหลือ" },
        progress = { "139:1054102105:452772059", "จำไว้ ไม่ว่าจะล่าสัตว์อะไร เจ้าควรศึกษาให้เข้าใจพฤติกรรมของมัน ความรู้นั้นอาจช่วยชีวิตเจ้าได้" },
        completion = { "22:519231318:1972086857 N 56:799588451:539945181", "นี่คือยาถอนพิษ {name} เอาไปให้ไรนากเร็วที่สุดเท่าที่ทำได้ แล้วระวังตัวด้วย" },
        required = { [4886] = { "20:1248950309:1851231400", "ถุงพิษของ Venomtail" } },
        steps = { { "20:1248950309:1851231400", "ถุงพิษของ Venomtail" } },
    },
    [815] = { -- Break a Few Eggs
        title = { "16:1523032313:1626194744", "ไปเอาไข่มาสักสองสามฟอง" },
        objective = { "52:1371714351:1363265595", "นำ Taillasher Egg 3 ฟองไปให้ Cook Torka ที่ Razor Hill" },
        description = { "52:1098779597:312972551 N 428:1265518477:114444", "เฮ้อ! ข้าเกือบลืมเตรียมอาหารเช้าเสียแล้ว\n\n{name} รีบออกไปหาไข่เทลแลชเชอร์มาให้ข้าหน่อย ข้าต้องใช้อย่างน้อยสามฟองถึงจะพอทำอาหารพรุ่งนี้\n\nพวกบลัดทาลอนเทลแลชเชอร์ดุเอาเรื่อง มักสู้จนตายเพื่อปกป้องไข่ บางทีพวกมันฝังไข่ลึกเกินกว่าจะขุดได้ปลอดภัย แต่ถ้าไปเกาะเอคโคทางตะวันออกเฉียงใต้ของหมู่บ้านเซนจิน เจ้าก็มักพบไข่ได้ทั่วเกาะ" },
        progress = { "102:526555217:805752979", "มื้อเช้า มื้อกลางวัน มื้อเย็น! จะมื้อไหนก็ช่างเถอะ ยังไงก็ต้องมีคนทำ แล้วคนนั้นก็คือข้า!" },
        completion = { "51:749357728:1973228285 N 63:633253579:566035662", "เจ้าอาจอ่อนแอ แต่อย่างน้อยก็ไม่ซุ่มซ่าม {name}\n\nเอานี่ไปแล้วหลบให้ข้า ข้ามีอาหารต้องทำ" },
        required = { [4890] = { "14:1708264429:766725253", "ไข่ Taillasher" } },
        steps = { { "14:1708264429:766725253", "ไข่ Taillasher" } },
    },
    [816] = { -- Lost But Not Forgotten
        title = { "22:1879134875:1310579624", "หายไปแต่ยังอยู่ในใจ" },
        objective = { "87:672775733:1639738202", "นำหลักฐานว่าเกิดอะไรขึ้นกับ Kron ไปให้ Misha Tor'kren ที่ไร่ทางตะวันตกเฉียงเหนือของ Razor Hill" },
        description = { "N 501:823312920:1627777059", "{name} ได้โปรดช่วยข้าที ลูกชายข้าชื่อครอนออกไปล่าสัตว์หลายวันแล้ว ยังไม่กลับเลย เขามุ่งไปทางตะวันตกฝั่งแบร์เรนส์เพื่อล่าโครโคลิสก์ตามแม่น้ำเซาท์ฟิวรี ข้ากลัวว่าจะเกิดเรื่องร้ายที่สุด\n\nถึงเขาจะแข็งแรง แต่ความดื้อและทิฐิก็พาเขาไปเจอเรื่องเดือดร้อนเสมอ ข้าเตือนแล้วว่าพวกโครโคลิสก์ทั้งแรงเยอะและดุร้าย เขากลับโกรธแล้วเดินกระแทกเท้าออกไป\n\nหากหาเขาไม่เจอ อย่างน้อยก็เอาหลักฐานว่าเกิดอะไรขึ้นกับเขามาให้ข้า... ต่อให้ต้องผ่าท้องโครโคลิสก์ทุกตัวตามริมฝั่งเซาท์ฟิวรีก็ตาม" },
        progress = { "83:155035524:655730284", "ข้าภาวนาให้ครอนกลับมา แต่ข้าแทบจะแน่ใจแล้วว่าเกิดอะไรขึ้นกับเขา" },
        completion = { "181:1987467787:1775054292 N 146:72883320:1621541223", "โอ้ ลูกข้า... ลูกที่รักของข้า\n\nข้าเฝ้าทรมานใจตั้งแต่เขาออกไป เพราะไม่รู้ว่าเกิดอะไรขึ้น เมื่อได้รู้แล้ว อย่างน้อยข้าคงเริ่มไว้ทุกข์ได้เสียที\n\nขอบใจ {name} รับนี่ไปเถอะ ข้าตั้งใจให้เป็นของขวัญแก่ครอนตอนเขากลับมาอย่างผู้ชนะ ตอนนี้รู้แล้วว่าเขาตาย ข้าทนมองมันไม่ไหว" },
        required = { [4891] = { "13:1017179806:1315562347", "เครื่องรางของ Kron" } },
        steps = { { "13:1017179806:1315562347", "เครื่องรางของ Kron" } },
    },
    [817] = { -- Practical Prey
        title = { "14:1758927912:253137077", "ล่าเสือมาใช้ประโยชน์" },
        objective = { "62:509906455:1205543732", "นำ Durotar Tiger Fur 4 ผืนไปให้ Vel'rin Fang ที่ Sen'jin Village" },
        description = { "51:58898428:1242862784 N 428:570171570:901591874", "หนังสัตว์ที่เราใช้หลายผืนมาจากเสือดูโรทาร์ {name} ทั้งผ้าห่ม ชุดเกราะ และกระโจม เรามีเหตุผลมากมายที่จะล่าพวกมัน และมีเหตุผลพอกันที่จะให้พวกมันอยู่รอด\n\nถึงเวลาลดจำนวนพวกมันลงบ้างแล้ว พวกเรามีมากขึ้นจนของที่เก็บไว้เริ่มไม่พอใช้ ข้าต้องการหนังเพิ่มเพื่อทำข้าวของให้คนของเรา\n\nนำหนังเสือดูโรทาร์มาให้ข้า 4 ผืน แล้วข้าจะให้รางวัล เจ้าจะพบพวกมันตามเกาะทางใต้ของที่นี่" },
        progress = { "32:260010004:557706405 N 277:592136803:343975346", "ข้าจำการล่าเสือครั้งแรกได้ {name} ข้าเลือกเกาะที่ใหญ่ที่สุดในหมู่เกาะเอคโค แล้วนั่งนิ่งใต้เงาใบไม้อยู่เกือบทั้งวัน... เฝ้ามอง... รอคอย\n\nกล้ามเนื้อข้าเกร็งพร้อมจู่โจม ตอนที่เสือตัวนั้นงับเหยื่อเสียที นั่นคือชัยชนะครั้งใหญ่ที่สุดครั้งหนึ่งของข้า" },
        completion = { "14:2128938491:860466914 N 103:1406282217:411127053", "ข้าพอใจมาก {name} เพราะเจ้าช่วยไว้ พวกเราจะมีเครื่องป้องกันและไม่ต้องทนหนาวเมื่อฤดูเปลี่ยน\n\nขอบใจ" },
        required = { [4892] = { "17:1147922986:1001160812", "ขนเสือ Durotar" } },
        steps = { { "17:1147922986:1001160812", "ขนเสือ Durotar" } },
    },
    [818] = { -- A Solvent Spirit
        title = { "16:1962368837:1956904173", "จิตวิญญาณแห่งการปรุงยา" },
        objective = { "93:1702627216:1413535487", "นำ Intact Makrura Eye 4 ดวงและ Crawler Mucus 8 ขวดไปให้ Master Vornal ที่ Sen'jin Village" },
        description = { "496:2067063312:341231918", "แม้สายตาข้าจะแย่ลง ข้าก็ยังเห็นชัดพอ เวทที่เคยร่ายได้ง่าย ๆ เดี๋ยวนี้มักต้องอาศัยวิชาปรุงยาช่วย แต่ข้าไม่ยอมรับศิษย์ เพราะยังไม่มีโทรลล์หรือออร์คที่คู่ควรเสนอตัวเข้ามา\n\nเจ้าคู่ควรหรือ? ใช่สิ เจ้าคู่ควร... อย่างน้อยเจ้าก็คิดอย่างนั้น\n\nข้าต้องการของสองสามอย่าง เจ้าจะหาให้ข้าไหม?\n\nข้าต้องการตาแมครูราที่ยังสมบูรณ์กับเมือกครอว์เลอร์บรรจุขวด หาได้จากแมครูราหรือครอว์เลอร์ในดูโรทาร์ เราคงได้คุยกันอีกเร็ว ๆ นี้" },
        progress = { "120:811564018:952334659", "เวลาคือบททดสอบกำลังและเจตจำนงที่แท้จริง หากหมดความอดทนหรือยอมแพ้แก่ความอ่อนแอ ตัวตนจริง ๆ ของเจ้าก็จะเผยออกมา" },
        completion = { "41:2015755638:288395960", "ทำได้ดี เจ้าหนุ่มสาว... ทำได้ดีจริง ๆ" },
        required = { [4887] = { "18:1385130576:494300372", "ดวงตา Makrura ที่สมบูรณ์" }, [4888] = { "13:1777291208:1100726208", "เมือกปู" } },
        steps = { { "18:1385130576:494300372", "ดวงตา Makrura ที่สมบูรณ์" }, { "13:1777291208:1100726208", "เมือกปู" } },
    },
    [823] = { -- Report to Orgnil
        title = { "16:1690483746:1728239440", "รายงานตัวกับออร์กนิล" },
        objective = { "41:542928067:1129963257", "คุยกับ Orgnil Soulscar ที่ Razor Hill" },
        description = { "438:2102073252:195637941", "พวกเราที่หมู่บ้านเซนจินก็มีปัญหาของตนเอง ขอบใจที่เจ้าช่วย แต่ข่าวเรื่องเบิร์นนิงเบลดที่เจ้านำมาอาจกลายเป็นปัญหาของทุกคน\n\nมีออร์คชื่อออร์กนิล โซลสการ์ประจำอยู่ที่เรเซอร์ฮิลล์ เขาคอยปกป้องดูโรทาร์จากพวกชั่วร้ายอย่างเบิร์นนิงเบลด! ไปบอกเขาเรื่องความเดือดร้อนของเราและข่าวจากหุบเขาแห่งบททดสอบ เขาคงอยากรู้\n\nเรเซอร์ฮิลล์อยู่ทางเหนือ" },
        completion = { "60:422154762:101575754", "ว่าอย่างไร? เจ้ามีเรื่องจะรายงานหรือ? งั้นก็ว่ามา!" },
    },
    [825] = { -- From The Wreckage....
        title = { "21:426788889:1376592415", "จากซากเรือ..." },
        objective = { "93:944398750:1572831107", "Gar'Thok ที่ Razor Hill ต้องการให้เจ้าค้นหา Gnomish Tools 3 ชิ้นจากซากเรือนอกชายฝั่ง" },
        description = { "450:1004193522:717554753 N 48:1076357441:2084213457", "หน่วยสอดแนมที่ช่างสังเกตที่สุดคนหนึ่งของข้ารายงานว่า ซากกองเรือของพราวด์มัวร์ยังอยู่นอกชายฝั่งดูโรทาร์ ทางตะวันออกของป้อมทิราการ์ด\n\nใคร ๆ ก็รู้ว่ามนุษย์จับมือกับตัวเล็กน่ารังเกียจที่เรียกว่าโนม และมีความรู้ด้านเครื่องกลล้ำหน้า เราต้องทำความเข้าใจทุกฝ่ายที่อาจเป็นศัตรูของเราให้ถ่องแท้ พวกเราจะได้ประโยชน์จากความรู้ใหม่นี้ด้วย\n\nว่ายน้ำไปค้นซากเรือ {name} แล้วเอาเครื่องมือของอัลไลแอนซ์มาให้ข้า" },
        progress = { "203:1921021149:451317187", "เมื่อรู้ว่ามนุษย์ใช้เครื่องจักรประหลาดของพวกมันอย่างไร เราจะมีโอกาสชนะในการรบครั้งต่อไปมากขึ้น\n\nความรู้ที่ได้ใหม่นี้จะทำให้ฮอร์ดยิ่งแข็งแกร่ง" },
        completion = { "37:890471133:1856614144 C 88:539918517:1868300299", "เจ้ากู้ของสำเร็จแล้ว {class} ข้าจะส่งเครื่องมือพวกนี้ไปออร์กริมมาร์กับขบวนคาราวานเที่ยวถัดไป\n\nทำได้ดี" },
        required = { [4863] = { "13:507167116:1182083773", "เครื่องมือของโนม" } },
        steps = { { "13:507167116:1182083773", "เครื่องมือของโนม" } },
    },
    [826] = { -- Zalazane
        title = { "8:1730891359:1679168540", "ซาลาซาน" },
        objective = { "90:1709863888:2044805577", "เอาชนะ Zalazane\n\nสังหาร Voodoo Troll 8 ตัวและ Hexed Troll 8 ตัว\n\nนำ Zalazane's Head ไปให้ Gadrin" },
        description = { "363:603283416:858613236", "หมอผีซาลาซานอยู่บนเกาะเอคโคทางตะวันออก ที่นั่นเคยเป็นบ้านของเรา\n\nมันส่งโทรลล์จากเกาะมาที่แผ่นดินใหญ่เพื่อสาปคนของเรา แล้วลากคนไปอยู่ใต้อำนาจมันมากขึ้น\n\nต้องหยุดมันเสีย\n\nกำจัดซาลาซานและสมุนของมัน โทรลล์พวกนั้นเคยเป็นดาร์กสเปียร์ แต่เราสูญเสียพวกเขาไปแล้ว นำหัวมันมาให้ข้า ข้าจะได้รู้ว่าการปกครองอันชั่วร้ายของมันสิ้นสุดลงแล้ว" },
        progress = { "22:932631885:1626022080 N 1:63:63", "เจ้ากำจัดซาลาซานแล้วหรือยัง {name}?" },
        completion = { "67:1678080553:502905240 N 130:1561242816:1266232993", "เมื่อซาลาซานไม่อยู่แล้ว เผ่าของเราก็กลับมานอนหลับได้อย่างสงบ\n\nขอบใจ {name} เผ่าดาร์กสเปียร์ติดหนี้เจ้าไม่น้อย หากเจ้าเจ็บป่วย ไปหาบอมเบย์ ผู้ช่วยของข้าที่อยู่ข้างหลังข้า วิชาวูดูของเขาแก่กล้า..." },
        required = { [4866] = { "15:1376337692:1145112502", "ศีรษะของ Zalazane" } },
        steps = { { "15:1376337692:1145112502", "ศีรษะของ Zalazane" } },
        objectiveLabels = {
            monster = { ["Hexed Troll slain"] = "ปราบ โทรลล์ต้องมนตร์", ["Voodoo Troll slain"] = "ปราบ โทรลล์วูดู" },
        },
    },
    [827] = { -- Skull Rock
        title = { "10:309627463:792603732", "ถ้ำสกัลร็อก" },
        objective = { "89:1231171576:2069060611", "เก็บ Searing Collars จากสมาชิกลัทธิใน Skull Rock\n\nนำไปให้ Margoz ที่ค่ายของเขา" },
        description = { "N 457:1501788415:315266221", "{name} เบิร์นนิงเบลดเข้าไปยึดถ้ำทางตะวันออกของออร์กริมมาร์ที่เรียกว่าสกัลร็อก ในถ้ำพวกมันทำพิธีชั่วร้ายและใช้ Searing Collars เผาเนื้อหนังตัวเอง\n\nข้าเชื่อว่าเมื่อสวมปลอกคอ พวกลัทธิจะปรับตัวให้รับพลังปีศาจได้ แต่ข้าต้องได้ปลอกคอมาศึกษาก่อนจึงจะยืนยันได้\n\nไปที่สกัลร็อก เก็บ Searing Collars จากพวกลัทธิที่เจอ แล้วนำมาให้ข้า ข้าจะไขความลับของมัน" },
        progress = { "33:1846837690:1130490227 N 34:1697107402:1069679793", "เจ้าเข้าไปในสกัลร็อกแล้วหรือยัง {name}? ได้ Searing Collars มาหรือไม่?" },
        completion = { "107:670263120:1172838558", "ดี ความลับของเบิร์นนิงเบลดซ่อนอยู่ในปลอกคอพวกนี้ แล้วข้าจะไขมันให้ได้..." },
        required = { [4871] = { "14:2042696701:541427471", "ปลอกคอแผดร้อน" } },
        steps = { { "14:2042696701:541427471", "ปลอกคอแผดร้อน" } },
    },
    [828] = { -- Margoz
        title = { "6:2131441725:1558114000", "มาร์กอซ" },
        objective = { "18:1185284153:1992117748", "คุยกับ Margoz" },
        description = { "411:201873184:1868036212 N 43:1330740531:639581137", "มาร์กอซ ชาแมนคนหนึ่งของเรา รู้เรื่องการแปดเปื้อนของเบิร์นนิงเบลดมากกว่าเรา เขาเล่าถึงถ้ำสกัลร็อกในภูเขานอกออร์กริมมาร์นิดเดียว! พวกลัทธิเบิร์นนิงเบลดกลุ่มใหญ่ซ่อนอยู่ที่นั่น\n\nก่อนเข้าสกัลร็อก ให้คุยกับมาร์กอซ เขาฉลาดและคนให้ค่าคำแนะนำของเขา\n\nเขาตั้งค่ายอยู่ทางตะวันออกเฉียงเหนือ ระหว่างชายฝั่งกับหุบเหวดรายกัลช์\n\nฟังคำแนะนำของเขา แต่ไม่ว่ามาร์กอซจะพูดอะไร {name} ข้าก็ยังต้องการให้เจ้าขยี้พวกลัทธินั่น!" },
        completion = { "9:1106625653:2036951628 N 77:39754063:1239487402 C 90:1081187326:1307753160", "ยินดีต้อนรับ {name} ข้าได้ข่าวว่าเจ้าจะมา และได้ยินถึงสิ่งที่เจ้าทำในดูโรทาร์\n\nเจ้าเป็น {class} ที่ฝีมือและชื่อเสียงกำลังเติบโต\n\nจงอยู่บนเส้นทางบริสุทธิ์ แล้วอนาคตของเจ้าจะรุ่งโรจน์" },
    },
    [829] = { -- Neeru Fireblade
        title = { "15:15275363:1169629152", "นีรู ไฟร์เบลด" },
        objective = { "56:343415007:1507078321", "นำ Example Collar ไปให้ Neeru Fireblade ใน Orgrimmar" },
        description = { "484:2014677238:1763274907", "Searing Collars ที่เจ้านำมาเป็นเครื่องมือปีศาจทรงพลัง ข้าเกรงว่าการหยั่งรู้ต้นกำเนิดมันจะเกินฝีมือชาแมนอย่างข้า เราต้องให้วอร์ล็อกมาศึกษา\n\nนำปลอกคอร้อนไปให้นีรู ไฟร์เบลด แม้เขาจะเป็นวอร์ล็อกฝีมือดี แต่เขาบอกว่าใช้พลังเพื่อสกัดปีศาจ และอ้างว่างานศึกษาศาสตร์ลี้ลับของเขาไม่เป็นภัย จะจริงหรือเท็จ เราก็อาจต้องพึ่งเขาในการต่อกรกับลัทธิปีศาจในดูโรทาร์\n\nเจ้าจะพบนีรูที่เคลฟต์ออฟชาโดว์ในออร์กริมมาร์", variants = { { "129:1447031317:227052775 C 349:1372436687:535499982", "Searing Collars ที่เจ้านำมาเป็นเครื่องมือปีศาจทรงพลัง ข้าเกรงว่าการหยั่งรู้ต้นกำเนิดมันจะเกินฝีมือ{class}อย่างข้า เราต้องให้วอร์ล็อกมาศึกษา\n\nนำปลอกคอร้อนไปให้นีรู ไฟร์เบลด แม้เขาจะเป็นวอร์ล็อกฝีมือดี แต่เขาบอกว่าใช้พลังเพื่อสกัดปีศาจ และอ้างว่างานศึกษาศาสตร์ลี้ลับของเขาไม่เป็นภัย จะจริงหรือเท็จ เราก็อาจต้องพึ่งเขาในการต่อกรกับลัทธิปีศาจในดูโรทาร์\n\nเจ้าจะพบนีรูที่เคลฟต์ออฟชาโดว์ในออร์กริมมาร์" } } },
        progress = { "26:1511177756:1102849722 C 22:981266335:571439908 R 15:1422324455:1852765575", "ขอคารวะด้วยความนอบน้อม {class} วันนี้ข้าจะช่วย พี่ชายชาว{race} ของข้าได้อย่างไร?", variants = { { "26:1511177756:1102849722 C 22:981266335:571439908 R 14:1544366648:885518718", "ขอคารวะด้วยความนอบน้อม {class} วันนี้ข้าจะช่วย พี่สาวชาว{race} ของข้าได้อย่างไร?" }, { "26:1511177756:1102849722 C 22:981266335:571439908 R 14:1544366648:885518718", "ขอคารวะด้วยความนอบน้อม {class} วันนี้ข้าจะช่วย พี่สาวชาว{race} ของข้าได้อย่างไร?" } } },
        completion = { "116:309201772:1841594422", "อา เจ้าได้สิ่งนี้มาจากไหน? มาร์กอซคนดีที่เรเซอร์ฮิลล์ส่งเจ้ามาหาข้าใช่ไหม?\n\nเอาละ ขอข้าดูใกล้ ๆ หน่อย..." },
        required = { [6658] = { "14:166201961:1706173635", "ปลอกคอตัวอย่าง" } },
        steps = { { "14:166201961:1706173635", "ปลอกคอตัวอย่าง" } },
    },
    [830] = { -- The Admiral's Orders
        title = { "20:1913321005:547342758", "คำสั่งของพลเรือเอก" },
        objective = { "59:1738341145:814536049", "นำ Admiral Proudmoore's Orders ไปให้ Gar'Thok ที่ Razor Hill" },
        description = { "246:1507312302:1271320887", "เจ้าเปิดซองจดหมายเก่าที่กรำแดดฝนจนพบเอกสารที่ดูเป็นทางการ เจ้าจำตราประทับของพลเรือเอกพราวด์มัวร์ได้\n\nเอกสารนี้ดูสำคัญ การ์ธ็อก ผู้บัญชาการเรเซอร์ฮิลล์ อาจอยากรู้ข้อมูลนี้" },
        progress = { "41:2060591827:1457555628 C 22:1389796743:831736378", "หน้าตาเจ้าดูกังวล {class} ถืออะไรอยู่หรือ?" },
        completion = { "88:471932326:526956289", "นี่เป็นลางร้ายทีเดียว เจ้าคิดถูกแล้วที่นำเรื่องนี้มาบอกข้า" },
        required = { [4883] = { "27:500562936:1687158604", "คำสั่งของ Admiral Proudmoore" } },
        steps = { { "27:500562936:1687158604", "คำสั่งของ Admiral Proudmoore" } },
    },
    [831] = { -- The Admiral's Orders
        title = { "20:1913321005:547342758", "คำสั่งของพลเรือเอก" },
        objective = { "80:1729529046:894905750", "ส่ง Admiral Proudmoore's Orders ให้ Nazgrel ในห้องของ Thrall ที่ Orgrimmar" },
        description = { "499:1344746117:748809848", "มนุษย์ไว้ใจไม่ได้ เราต่อสู้เคียงข้างพวกมันด้วยใจที่หนักอึ้ง เพราะรู้ว่าสักวันมันจะทรยศเรา\n\nแม้พลเรือเอกพราวด์มัวร์จะตายไป แผนลวงที่มันทิ้งไว้ก็ยังอยู่ เจ้าสวะมนุษย์นั่นวางแผนทุกอย่างไว้อย่างดีก่อนตายเสียอีก\n\nดูท่าว่าแม้เบเนดิกต์ตาย อำนาจของมันก็ยังไม่สิ้น ใครจะรู้ว่าทหารของพราวด์มัวร์ระลอกถัดไปจะยกพลขึ้นฝั่งเราเมื่อใด\n\nต้องส่งคำสั่งนี้ให้นาซเกรลในออร์กริมมาร์ทันที! เจ้าจะพบเขาในห้องของธรอลล์" },
        progress = { "63:1058937568:820979152", "ไม่เห็นหรือว่าข้ากำลังยุ่ง? ขอให้เป็นเรื่องด่วนจริง ๆ เถอะ..." },
        completion = { "154:467796623:842210601 C 67:266153120:1785791544", "ข้าเตือนขุนศึกนับครั้งไม่ถ้วนว่าอย่าไว้ใจมนุษย์ แต่เรื่องนี้สำคัญกว่าศักดิ์ศรีของข้าเอง\n\nเจ้ารับใช้ฮอร์ดอย่างมีเกียรติ {class} หนุ่มสาว\n\nข้าขอตัว ต้องไปปรึกษาธรอลล์เรื่องนี้ทันที..." },
        required = { [4883] = { "27:500562936:1687158604", "คำสั่งของ Admiral Proudmoore" } },
        steps = { { "27:500562936:1687158604", "คำสั่งของ Admiral Proudmoore" } },
    },
    [832] = { -- Burning Shadows
        title = { "15:1078764571:1733136255", "เงาเพลิง" },
        objective = { "33:835564375:471685438", "นำดวงตานี้ไปให้ Neeru Fireblade" },
        description = { "375:1633405108:1608429844", "<ถ้อยคำดังออกมาจากจี้เข้าสู่ห้วงความคิดของเจ้า>\n\nกัซอุซ?\n\nกัซอุซ... รายงานมา!\n\nมีข่าวว่ามีคนพบเจ้าที่สกัลร็อก เตรียมรับการโจมตีเสีย!\n\nกัซอุซ ข้าสั่งให้เจ้าพูด! ถ้าไม่พูด ข้าจะให้นีรู ไฟร์เบลดรู้ว่าเจ้าอยู่ที่ไหน แล้วมันจะลงมือกับเจ้าอย่างรวดเร็วและโหดเหี้ยม\n\nอย่าลองดีวัดฝีมือกับนีรู...\n\n...กัซอุซ เจ้ายังอยู่หรือเปล่า...?" },
        progress = { "68:186600658:272340804", "เจ้ามีเรื่องสำคัญจะรายงาน ข้าสัมผัสได้จากแววตาเจ้า" },
        completion = { "436:1759446982:1739830481 N 44:459699175:958968184", "<ตรวจดู Eye of Burning Shadow>\n\nน่าสนใจ เสียงที่เจ้าได้ยินเอ่ยชื่อข้าหรือ? ใคร ๆ รู้ว่าข้าตามล่าศัตรูของขุนศึก แต่... แปลกที่มันเจาะจงพูดถึงข้า ยิ่งแปลกเข้าไปอีกที่สมาชิกลัทธิเบิร์นนิงเบลดที่เจ้าได้จี้มาจากพวกมันใช้ชื่อคล้ายข้านัก\n\nข้าต้องศึกษาจี้นี้ ต้องศึกษา และ... และต้องคิดว่าข้อความนี้หมายถึงอะไร\n\nขอบใจที่นำเรื่องนี้มาบอกข้า {name} เจ้าช่วยพวกพ้องไว้มาก" },
        required = { [4903] = { "21:1644472733:226047086", "ดวงตาแห่งเงาลุกไหม้" } },
        objectiveLabels = {
            item = { ["Eye of Burning Shadow"] = "ดวงตาแห่งเงาลุกไหม้" },
        },
    },
    [834] = { -- Winds in the Desert
        title = { "19:313407843:133371753", "สายลมแห่งทะเลทราย" },
        objective = { "70:98222970:1024798903", "กู้ Sacks of Supplies 5 กระสอบแล้วนำกลับไปให้ Rezlak ใกล้ Orgrimmar" },
        description = { "503:1046689668:602401211", "ฉันเรซแล็ก ลูกน้องคนหนึ่งของแกซโลว์ เจ้านายส่งมาช่วยพวกออร์คที่ดูโรทาร์ ทุกอย่างไปได้สวย ยกเว้นคาราวาน คุ้มกันให้ปลอดภัยไม่ได้สักที! งานฉันก็ยากขึ้นไปอีกน่ะสิ\n\nของเที่ยวล่าสุด พวกนั้นรับปากว่าจะส่งถึงแท้ ๆ! ดันถูกฮาร์ปีดัสต์วินด์ฉกไป ที่ไหนนะ... หุบผาเรเซอร์วินด์หรือเปล่า?\n\nฉันต้องได้เสบียงพวกนั้นคืน ไม่งั้นงานจะไม่เดินเลย! ตามหุบผาใหญ่ลงใต้ จะเห็นร่องเขาเว้าเข้าไปในผนังทั้งด้านตะวันตกและตะวันออก" },
        progress = { "113:850849539:279537216", "อย่าเข้าใจผิดนะ ฉันเก่งเรื่องงานของฉัน แต่นี่มันเกินไป! จะให้ฉันทำอะไร สร้างปราสาททรายหรือไง?" },
        completion = { "182:817508932:1668087738", "เฮ้ นี่แหละที่ต้องการ! นายเอาเสบียงเรากลับมาได้ เยี่ยมเลย ฉันจะกลับไปทำงานต่อได้ทันทีที่หาคนมาขนกระสอบพวกนี้" },
        required = { [4918] = { "16:1390653316:1300058130", "กระสอบเสบียง" } },
        steps = { { "16:1390653316:1300058130", "กระสอบเสบียง" } },
    },
    [835] = { -- Securing the Lines
        title = { "18:1480248838:1290961979", "คุ้มกันเส้นทางขนส่ง" },
        objective = { "86:609750920:1069960185", "สังหาร Dustwind Savage 12 ตัวและ Dustwind Storm Witch 8 ตัวให้ Rezlak ใกล้ Drygulch Ravine" },
        description = { "497:23664842:1965214266 N 1:63:63", "แกซโลว์เคยบอกฉันว่า “เรซแล็ก มีเรื่องหนึ่งที่นายต้องรู้ไว้ในชีวิต ถ้าอยากให้งานออกมาดี ก็ลงมือทำเอง”\n\nฉันปล่อยให้คาราวานเราสูญไปหมดไม่ได้ เลยจะจัดการเอง หุบเหวดรายกัลช์อยู่ลึกเข้าไปทางตะวันออกของหุบผาเรเซอร์วินด์ ถ้าฆ่าฮาร์ปีที่นั่นให้หมด เส้นทางก็จะปลอดภัย\n\nแน่นอน แกซโลว์สอนฉันอีกอย่างว่า “อะไรก็ทำให้เสร็จได้ถ้าจ่ายพอ” ว่าไง จะช่วยฉันไหม {name}?" },
        progress = { "256:647904965:1841121968", "ดูเจ้านายฉันอย่างแกซโลว์แล้วนายอาจคิดไม่ถึง แต่เขาดูจะเข้าใจสถานการณ์เสมอ “อย่ากลัวที่จะก้าวครั้งใหญ่” เขาว่างั้น\n\nฮาร์ปีจะไม่เลิกก่อกวนเรา และคาราวานจะถูกโจมตีต่อไปถ้าเราไม่ลงมือทำอะไรสักอย่าง จริงไหม?" },
        completion = { "244:1020526444:1521651674 N 170:1341313264:850401936", "ทีนี้ฉันคงโล่งใจได้ ฮาร์ปีจะไม่มากวนคาราวานเสบียงของเราอีก ทันเวลาพอดีด้วย ได้ข่าวว่าของเที่ยวหน้าจะมีของเล่นสนุก ๆ ส่งมาให้ฉัน!\n\nนายทำงานเก่งทีเดียว {name} ลองไปหาเจ้านายฉันที่แรตเช็ตดูสิ พนันได้เลยว่าเขามีงานให้ทำ\n\nอ้อ ไม่ต้องห่วง ฉันไม่ลืมจ่ายค่าจ้างสำหรับงานที่นายช่วยหรอก" },
        objectiveLabels = {
            monster = { ["Dustwind Savage slain"] = "ปราบ นักรบเถื่อน Dustwind", ["Dustwind Storm Witch slain"] = "ปราบ แม่มดพายุ Dustwind" },
        },
    },
    [837] = { -- Encroachment
        title = { "12:17594178:1702081688", "การรุกล้ำ" },
        objective = { "128:1179902682:1594960178", "สังหาร Razormane Quilboar 4 ตัว, Razormane Scout 4 ตัว, Razormane Dustrunner 4 ตัว และ Razormane Battleguard 4 ตัวให้ Gar'Thok ที่ Razor Hill" },
        description = { "507:1348384271:451750603", "ตอนเรามาถึง ควิลบอร์เรเซอร์เมนยึดที่ดินไว้มากและคอยทิ่มแทงเราเหมือนหนาม เราขับไล่พวกมันส่วนใหญ่ไปได้ แต่บางพื้นที่พวกมันยังตั้งรับอย่างแข็งแรง\n\nเรื่องนี้ยืดเยื้อมานานพอแล้ว เพื่อความปลอดภัยของเรา จะปล่อยให้เรเซอร์เมนยึดพื้นที่ในดินแดนเราไม่ได้ ค่ายของพวกมันอยู่ทางตะวันตกของที่นี่ มองหาดงหนามแล้วจะพบ วันนี้เราจะขับพวกมันออกจากดูโรทาร์ พรุ่งนี้อาจเป็นทั้งคาลิมดอร์" },
        progress = { "241:1494606271:2006918101", "พวกควิลบอร์พอมีไหวพริบและรู้จักจัดระเบียบอยู่บ้าง แต่ข้ายังประหลาดใจที่พวกมันยึดและรักษาดินแดนไว้ได้มากขนาดนี้ในคาลิมดอร์ บางทีพวกมันอาจเจ้าเล่ห์กว่าที่ข้าคิด..." },
        completion = { "233:384628523:787322428", "ข้าจะส่งข่าวว่าควิลบอร์ถูกขับออกจากรังแล้ว และเผาสิ่งปลูกสร้างของพวกมันได้ การขับเรเซอร์เมนออกจากดูโรทาร์ช่วยให้เราเข้าใกล้วันที่พรมแดนบ้านเกิดใหม่จะปลอดภัยทั่วถึง" },
        objectiveLabels = {
            monster = { ["Razormane Quilboar slain"] = "ปราบ ควิลบอร์ Razormane", ["Razormane Scout slain"] = "ปราบ หน่วยสอดแนม Razormane", ["Razormane Dustrunner slain"] = "ปราบ นักวิ่งฝ่าฝุ่น Razormane", ["Razormane Battleguard slain"] = "ปราบ ผู้พิทักษ์แนวรบ Razormane" },
        },
    },
    [840] = { -- Conscript of the Horde
        title = { "22:958341339:726127800", "ทหารเกณฑ์แห่งฮอร์ด" },
        objective = { "183:1507122312:1469879555", "เดินตามถนนตะวันตกจาก Razor Hill ข้ามสะพานไป Barrens\n\nหยุดที่ด่านออร์คอีกฝั่งสะพาน\n\nยื่นจดหมายรับสมัครให้ Kargal Battlescar ที่ด่านใน Barrens" },
        description = { "242:981669627:2086827000", "อืม เจ้าดูแข็งแรงดี\n\nฟังนะ คาร์กัลเพื่อนสนิทของข้าต้องการทหารใหม่ไปประจำแบร์เรนส์ ข้ารู้ว่าเจ้าอยากทำสิ่งที่ถูกต้องเพื่อฮอร์ด นี่คือโอกาสของเจ้า\n\nเอาจดหมายรับสมัครนี้ไปให้คาร์กัล ดูว่าเขาจะลงชื่อให้ไหม" },
        progress = { "85:374086912:1147550624", "ต้องการอะไร เจ้าหนู? ถ้าไม่ได้มาสมัคร ข้าก็ไม่มีเวลาให้เจ้า" },
        completion = { "175:1237198723:2081903172", "อ้อ ทาครินส่งเจ้ามาหรือ? เขาเป็นหน่วยสอดแนมฝีมือเยี่ยม ข้าไม่รู้จะทำอย่างไรหากขาดเขา\n\nข้าจะลงชื่อในจดหมายรับสมัครให้ แต่ที่ต้องการคนจริง ๆ คือครอสโรดส์" },
        required = { [4992] = { "18:1050308809:1693553449", "จดหมายรับสมัคร" } },
        steps = { { "18:1050308809:1693553449", "จดหมายรับสมัคร" } },
    },
    [842] = { -- Crossroads Conscription
        title = { "23:481996347:960913557", "เข้าประจำการที่ครอสโรดส์" },
        objective = { "186:1651717685:1527769854", "เดินตามถนนตะวันตกจาก Far Watch Outpost ของ Kargal\n\nเมื่อถึงทางแยกรูปตัว T ให้เลี้ยวซ้ายแล้วเดินลงใต้ตามถนน\n\nตามหา Sergra Darkthorn ที่จุดตัดถนนใน Crossroads" },
        description = { "318:2075518610:1106654876", "เอาจดหมายรับสมัครที่ลงชื่อแล้วไปครอสโรดส์\n\nเซอร์กรา ดาร์กธอร์นเป็นคนคุมที่นั่น ให้ตายเถอะ นางเป็นชาแมนปากร้ายที่จะพูดจนเจ้าหัวหมุนก่อนยอมให้ทำอะไรเป็นชิ้นเป็นอัน ธรอลล์เชื่อว่านางมีอะไรพิเศษ แต่ข้าไม่แน่ใจนัก\n\nเจ้าคงต้องไปตัดสินเอง เจ้าหนู...", variants = { { "123:1737749:799924366 C 189:1542908396:2128200594", "เอาจดหมายรับสมัครที่ลงชื่อแล้วไปครอสโรดส์\n\nเซอร์กรา ดาร์กธอร์นเป็นคนคุมที่นั่น ให้ตายเถอะ นางเป็น {class} ปากร้ายที่จะพูดจนเจ้าหัวหมุนก่อนยอมให้ทำอะไรเป็นชิ้นเป็นอัน ธรอลล์เชื่อว่านางมีอะไรพิเศษ แต่ข้าไม่แน่ใจนัก\n\nเจ้าคงต้องไปตัดสินเอง เจ้าหนู..." } } },
        progress = { "85:1393637841:1820078345", "ไหนดูซิ ใครมากันนี่? คาร์กัลเห็นว่าข้าคู่ควรจะได้ทหารใหม่อีกคนแล้วหรือ?" },
        completion = { "9:505169621:1042608785 N 336:94012281:1271602674", "เอาละ {name} เจ้าอยากทำงานให้คุ้มที่ฮอร์ดเลี้ยงดูใช่ไหม? ที่นี่มีงานถมไป ฟังให้ดีแล้วทำตามคำสั่ง\n\nข้าเห็นแววตาเจ้านะ อย่าคิดว่าข้าจะยอมให้เจ้าลามปาม ธรอลล์ประกาศเองว่าหญิงแห่งฮอร์ดเท่าเทียมกับพวกผู้ชายอย่างเจ้า หากเจ้าดูหมิ่นข้าแม้แต่นิดเดียว เจ้าจะได้รู้ว่าความเจ็บปวดจริง ๆ เป็นอย่างไร", variants = { { "9:505169621:1042608785 N 263:17319754:2132834955", "เอาละ {name} เจ้าอยากทำงานให้คุ้มที่ฮอร์ดเลี้ยงดูใช่ไหม? ที่นี่มีงานถมไป ฟังให้ดีแล้วทำตามคำสั่ง\n\nยินดีที่ได้พบเจ้า ธรอลล์คงดีใจที่ได้รู้ว่ามีหญิงอย่างเจ้ากับข้าริเริ่มผลักดันงานในแบร์เรนส์กันมากขึ้น" }, { "9:505169621:1042608785 N 263:17319754:2132834955", "เอาละ {name} เจ้าอยากทำงานให้คุ้มที่ฮอร์ดเลี้ยงดูใช่ไหม? ที่นี่มีงานถมไป ฟังให้ดีแล้วทำตามคำสั่ง\n\nยินดีที่ได้พบเจ้า ธรอลล์คงดีใจที่ได้รู้ว่ามีหญิงอย่างเจ้ากับข้าริเริ่มผลักดันงานในแบร์เรนส์กันมากขึ้น" } } },
        required = { [4995] = { "25:415480879:1236995215", "จดหมายรับสมัครที่ลงนามแล้ว" } },
        steps = { { "25:415480879:1236995215", "จดหมายรับสมัครที่ลงนามแล้ว" } },
    },
    [924] = { -- The Demon Seed
        title = { "14:1757951900:626215997", "เมล็ดพันธุ์ปีศาจ" },
        objective = { "108:1758754120:1764989670", "หยิบ Flawed Power Stone แล้วนำไปที่ Altar of Fire ก่อนหินหมดพลัง จากนั้นกลับไปหา Ak'Zeloth" },
        description = { "499:1368147294:774097965", "Demon Seed เป็นเครื่องมือทรงพลังของเบิร์นนิงลีเจียน มันอยู่ในถ้ำบนยอดเดรดมิสต์ เหนือแท่นเพลิงปีศาจ\n\nข้าเตรียมศิลาพลังไว้ เมื่อวางใกล้เมล็ด มันจะตัดการเชื่อมโยงระหว่างเมล็ดกับลีเจียน\n\nหยิบศิลาจากโต๊ะแล้วนำไปที่แท่นเพลิงบนยอดเดรดมิสต์ มุ่งตะวันตก พอถึงทางแยกให้ขึ้นเหนือ ยอดเขาจะอยู่ซ้ายมือ ทางขึ้นที่ปลอดภัยที่สุดอยู่ด้านเหนือ\n\nรีบด้วย พลังของศิลาจะเผาผลาญตัวมันเองเมื่อเวลาผ่านไป" },
        progress = { "53:905045946:636648269", "Demon Seed ยังอยู่ ข้าสัมผัสพลังของมันได้..." },
        completion = { "428:1144066529:1276183378", "เจ้าทำงานเสร็จแล้ว ทำลาย Demon Seed ตามที่นีรูสั่ง แต่นี่ยังไม่จบ...\n\nเมื่อเมล็ดถูกทำลาย คลื่นพลังมหาศาลก็แผ่ออกไปในห้วงเวท ข้ารู้สึกได้และมั่นใจว่าผู้อื่นก็รู้สึกเช่นกัน พวกที่คงสงสัยว่าทำไมของเล่นของตนถึงพัง...\n\nไม่ว่าภายหน้าจะเกิดปัญหาอะไร ข้ามีของให้เจ้า นีรูฝากมาเป็นค่าตอบแทน และให้ข้าขอบใจเจ้า\n\nเช่นนั้นก็ขอบใจ" },
        steps = { { "22:645607442:530254169", "ทำลาย Demon Seed" } },
    },
    [926] = { -- Flawed Power Stone
        title = { "18:1308042980:179436576", "ศิลาพลังที่มีตำหนิ" },
        completion = { "163:1292882361:2051027792", "ศิลาเหล่านี้อัดพลังเวทไว้ แต่จงใจทำให้มีตำหนิ มันไม่เสถียรอย่างยิ่ง เมื่อหยิบออกจากโต๊ะ พลังจะเผาผลาญศิลาอย่างรวดเร็ว" },
    },
    [2161] = { -- A Peon's Burden
        title = { "15:1956211383:414717614", "สัมภาระของคนงาน" },
        objective = { "53:1351100693:706935919", "นำ Ukor's Burden ไปให้ Innkeeper Grosk ที่ Razor Hill" },
        description = { "482:1023198267:1829990369", "ขอโทษนะ ช่วยข้าได้ไหม?\n\nข้ามีอาหารกองใหญ่อยู่ตรงนี้ เดินตามถนนมาฝ่าทั้งสกอร์พิด แมงมุม และตัวที่แย่กว่านั้นอีก! ข้าเอาอาหารมาหุบเขาแห่งบททดสอบเพราะนึกว่าที่นี่ต้องใช้ ข้าชอบช่วยคน แต่ที่นี่ไม่ต้องการอาหารเลย! ตอนนี้ต้องขนกลับเรเซอร์ฮิลล์ ข้ากลัวสัตว์ตามทาง...\n\nช่วยเอาไปแทนข้าทีได้ไหม? ข้าเป็นแค่คนงาน แต่เจ้าเป็นวีรบุรุษ เจ้าไม่กลัวอะไรเลย!\n\nเอาไปให้กรอสก์ เจ้าของโรงแรมที่เรเซอร์ฮิลล์นะ ขอบใจ!" },
        progress = { "22:1184944180:2136060281", "ยินดีต้อนรับสู่เรเซอร์ฮิลล์!" },
        completion = { "347:472382224:1580723410 C 111:1567107041:1860583782", "อา นี่อาหารที่อูคอร์ขนไปหุบเขาแห่งบททดสอบนี่ พวกเขาไม่ต้องการหรือ? คงชอบปล่อยให้ว่าที่วีรบุรุษอย่างเจ้าอดอาหาร เห็นว่าช่วยฝึกใจให้แกร่ง!\n\nขอบใจที่เอาอาหารมาคืน ข้าจะเอาไปเก็บบนชั้น... แต่ก่อนอื่นมารับของกินแก้เหนื่อยสักหน่อย!\n\nแล้วอย่าลืมพักที่โรงแรมด้วย ถึงเจ้าจะเป็น {class} ผู้กล้าพร้อมเผชิญโลกกว้าง หากหมดแรงขึ้นมาก็ช่วยตัวเองหรือฮอร์ดได้ไม่มากนัก" },
        required = { [7629] = { "13:1029347548:1794657524", "ภาระของ Ukor" } },
        objectiveLabels = {
            item = { ["Ukor's Burden"] = "ภาระของ Ukor" },
        },
    },
    [7664] = { -- Ivory Raptor Replacement
        title = { "24:283482043:222253", "แลกแรปเตอร์สีงาช้าง" },
        completion = { "240:2102332915:795991372", "เจ้าเอาแรปเตอร์ตัวเก่ามาให้ข้า ข้าจะให้ตัวใหม่ที่เพิ่งลับกรงเล็บให้คม! ตัวใหม่จะเร็วพอ ๆ กับตัวเก่าของเจ้า แต่หน้าตาเปลี่ยนไป ลองดูแรปเตอร์ฝีเท้าไวที่นี่ได้ว่ามีตัวไหนให้เลือกบ้าง" },
        required = { [13317] = { "27:381839333:1522515336", "นกหวีดเรียกแรปเตอร์สีงาช้าง" } },
        objectiveLabels = {
            item = { ["Whistle of the Ivory Raptor"] = "นกหวีดเรียกแรปเตอร์สีงาช้าง" },
        },
    },
    [7665] = { -- Red Raptor Replacement
        completion = { "240:2102332915:795991372", "เจ้าเอาแรปเตอร์ตัวเก่ามาให้ข้า ข้าจะให้ตัวใหม่ที่เพิ่งลับกรงเล็บให้คม! ตัวใหม่จะเร็วพอ ๆ กับตัวเก่าของเจ้า แต่หน้าตาเปลี่ยนไป ลองดูแรปเตอร์ฝีเท้าไวที่นี่ได้ว่ามีตัวไหนให้เลือกบ้าง" },
        title = { "22:2012894374:1438467411", "แลกแรปเตอร์สีแดง" },
        required = { [8586] = { "33:1414209674:463370123", "นกหวีดเรียกแรปเตอร์แดงลายด่าง" } },
        objectiveLabels = {
            item = { ["Whistle of the Mottled Red Raptor"] = "นกหวีดเรียกแรปเตอร์แดงลายด่าง" },
        },
    },
    [96821] = { -- Legging It
        title = { "10:1531121132:998066038", "กำจัดแมงมุมตามทาง" },
        objective = { "111:1880392299:325906853", "สังหาร Ridgeshade Creeper 6 ตัวและ Ridgeshade Lurker 6 ตัวใน Durotar ตอนใต้ แล้วไปรายงานกับ Gar'thok ที่ Razor Hill" },
        description = { "293:1871737544:1951573614", "ช่วงนี้เราเห็นคนเดินทางมาจากเรเซอร์ฮิลล์น้อยลงเรื่อย ๆ เจอสกอร์พิดก็ไม่น่าสนุกอยู่แล้ว ตอนนี้ยังได้ยินว่ามีแมงมุมทำรังริมถนนอีก\n\nถ้าเจ้าต้องเดินทางขึ้นเหนือ ก็ฆ่าแมงมุมระหว่างทางสักหน่อย แล้วไปบอกคนที่เรเซอร์ฮิลล์ว่าถนนปลอดภัยขึ้นแล้ว" },
        completion = { "135:340106084:1746405943", "พักหนึ่งแล้วที่คนงานกลัวเดินทางลงใต้ สหาย ตอนนี้เจ้าช่วยให้เส้นทางโล่งขึ้น เราก็ให้พวกเขากลับไปทำงานได้", variants = { { "58:31862487:99170765 N 71:411608572:722030186", "พักหนึ่งแล้วที่คนงานกลัวเดินทางลงใต้ {name} ตอนนี้เจ้าช่วยให้เส้นทางโล่งขึ้น เราก็ให้พวกเขากลับไปทำงานได้" } } },
        progress = { "4:1517439344:201828488", "ว่าอย่างไร?" },
        objectiveLabels = {
            monster = { ["Ridgeshade Creeper slain"] = "ปราบ ตัวไต่คลาน Ridgeshade", ["Ridgeshade Lurker slain"] = "ปราบ ตัวซุ่มซ่อน Ridgeshade" },
        },
    },
    [96822] = { -- For Honor
        title = { "9:614794130:796174107", "เพื่อเกียรติของผู้ล่วงลับ" },
        objective = { "142:1809839871:657541336", "เก็บ Raider's Battleaxe, Raider's Bow และ Raider's Shield จากรอบนอก Tiragarde Keep แล้วนำกลับไปให้ Turroc ที่ Razor Hill" },
        description = { "313:1669891748:317151396", "เราสูญเสียนักรบกล้าของฮอร์ดไปมากตอนตีป้อมทิราการ์ด ตอนนี้มนุษย์เสริมกำลังในซากป้อมแล้ว เราจึงไปนำร่างพวกเขากลับมาให้เกียรติผู้ตายอย่างสมควรไม่ได้\n\nไปที่ซากปรักหักพังรอบป้อม หาอาวุธที่พวกพ้องผู้ล้มลงทิ้งไว้ เราจะนำไปจัดแสดงในที่อันสมเกียรติ" },
        progress = { "27:647970501:828264030", "เจ้าทำตามที่ข้าขอแล้วหรือยัง?" },
        completion = { "77:354962088:1287120994", "ผู้คนจะจดจำนักรบเหล่านี้เสมอ สหาย เจ้าช่วยให้เป็นเช่นนั้น", variants = { { "42:1716646419:631844592 N 29:1053643228:1342968639", "ผู้คนจะจดจำนักรบเหล่านี้เสมอ {name} เจ้าช่วยให้เป็นเช่นนั้น" } } },
        required = { [275713] = { "12:203187774:991769625", "ธนูของผู้จู่โจม" }, [275716] = { "18:2083270564:636379264", "ขวานศึกของผู้จู่โจม" }, [275717] = { "15:1390283467:922523957", "โล่ของผู้จู่โจม" } },
        steps = { { "12:203187774:991769625", "ธนูของผู้จู่โจม" }, { "18:2083270564:636379264", "ขวานศึกของผู้จู่โจม" }, { "15:1390283467:922523957", "โล่ของผู้จู่โจม" } },
    },
    [96825] = { -- This Fruit Could Bite Back
        title = { "26:1716244341:655597190", "ผลไม้นี้อาจกัดกลับ" },
        objective = { "107:1795965601:2134831193", "Cook Torka ที่ Razor Hill ต้องการให้เจ้าเก็บ Prickly Pear Fruit 8 ผลจาก Razormane Grounds ทางตะวันตกของเมือง" },
        description = { "391:1626861382:1708387593", "พรานกับคนหาปลาของเราเอาของคาวมาบำรุงกองทัพได้มาก แต่ทหารนาน ๆ ทีจะได้กินของหวาน\n\nข้าเคยเห็นกระบองเพชรที่ออกผลมีหนามแต่รสดี มันขึ้นเฉพาะบนเนินทางตะวันตก ตรงที่พวกควิลบอร์น่าชังตั้งค่าย ฝ่าพวกควิลบอร์เข้าไปแล้วเก็บผลมาให้ข้าสักหน่อย ระวังด้วย ผลไม้พวกนั้นมีหนามพอ ๆ กับควิลบอร์!" },
        progress = { "24:573438102:806780405", "เจ้าหาผลไม้เจอหรือยัง?" },
        completion = { "138:511369455:1707262478", "ข้าจะเอาไปทำของอร่อยและเก็บเมล็ดไว้ปลูก สักวันจะมีลูกแพร์หนามขึ้นรอบออร์กริมมาร์เลย!" },
        required = { [275718] = { "18:1496979708:1746050061", "ผลกระบองเพชรหนาม" } },
        steps = { { "18:1496979708:1746050061", "ผลกระบองเพชรหนาม" } },
    },
    [96873] = { -- A Pain in the Neck
        title = { "18:822538776:1381614034", "จี้เจ้าปัญหา" },
        objective = { "169:190391174:291931988", "Pa'zula ที่ Sen'jin Village ต้องการ Luminous Residue 3 ชิ้น ใช้การสลายเวทกับ Hexed Pendant ที่ดรอปจากโทรลล์ใน Echo Isles เพื่อให้ได้ Luminous Residue" },
        description = { "409:723313595:823951252", "โทรลล์ทางตะวันออกตกอยู่ใต้อำนาจหมอผีซาลาซาน มันใช้เวทโหดร้ายหลายอย่างครอบงำจิตใจเชลย กลเม็ดโปรดอย่างหนึ่งคือให้พวกเขาสวมจี้ที่ลงมนตร์พันธนาการชั่วร้ายไว้\n\nฝึกวิชาลงอาคมของเจ้าด้วยการสลายเวทจากจี้เหล่านั้น แล้วนำสิ่งที่ได้มาให้ข้า อย่าเผลอเอาจี้มาคล้องคอล่ะ หากยังเห็นค่าอิสรภาพของเจ้า!" },
        progress = { "25:789846518:812020936 N 1:63:63", "เจ้ามีอะไรมาให้ข้าหรือ {name}?" },
        completion = { "103:1946437264:1489060127", "ทำได้ดี น่าเสียดายที่พวกโทรลล์ต้องตาย แต่เมื่อคลายเวทพันธนาการแล้ว วิญญาณของพวกเขาก็จะได้พักอย่างสงบ" },
        required = { [247884] = { "16:477056569:1563801170", "เศษตกค้างเรืองแสง" } },
        steps = { { "16:477056569:1563801170", "เศษตกค้างเรืองแสง" } },
    },
    [96874] = { -- This Is Spinal Axe
        title = { "18:559995061:14402788", "ขวานจากหนามสันหลัง" },
        objective = { "126:1876415052:1744394471", "Ug'thok ใน Orgrimmar ต้องการ Weathered Spine 5 ชิ้นจากสัตว์ใน Thunder Ridge พร้อม Rough Grinding Stone 5 ชิ้น" },
        description = { "331:1264633123:67501179", "เจ้าเคยเห็นสัตว์ยักษ์ในธันเดอร์ริดจ์ไหม? ข้าคิดอยู่เรื่อยว่าหนามบนหลังพวกมันเหมาะจะเอามาทำหัวขวานชั้นยอด ซารูหัวเราะตอนข้าเล่าให้ฟัง... เขาจะไปรู้อะไร!?\n\nถือเป็นส่วนหนึ่งของการฝึกตีเหล็ก เจ้ามาช่วยข้าได้! เอาหนามพวกนั้นมาให้ข้า พร้อมหินเจียรสำหรับลับให้คม" },
        completion = { { "132:151890498:200047228", "42:596053788:830640002 N 84:1448189432:1044875294", "42:596053788:830640002 C 84:1448189432:1044875294", "42:596053788:830640002 R 84:1448189432:1044875294" }, "หนามพวกนี้แข็งกว่าที่คิด สหาย! ทำของจากมันอาจไม่ง่ายอย่างที่ข้านึก... แต่ข้าจะลองต่อไป!", variants = { { "42:596053788:830640002 N 84:897077281:1286163310", "หนามพวกนี้แข็งกว่าที่คิด {name}! ทำของจากมันอาจไม่ง่ายอย่างที่ข้านึก... แต่ข้าจะลองต่อไป!" } } },
        progress = { "4:1517439344:201828488", "ว่าอย่างไร?" },
        required = { [275719] = { "15:1496874591:1864262748", "กระดูกสันหลังที่ผุกร่อน" }, [3470] = { "20:1714560535:68140181", "หินลับหยาบ" } },
        steps = { { "15:1496874591:1864262748", "กระดูกสันหลังที่ผุกร่อน" }, { "20:1714560535:68140181", "หินลับหยาบ" } },
    },
    [96875] = { -- Beasts of Thunder Ridge
        title = { "23:1306073057:1593322184", "สัตว์แห่งธันเดอร์ริดจ์" },
        objective = { "122:114032052:435177937", "Kamari ใน Orgrimmar ต้องการ Rough Lizard Hide 5 ผืนจากสัตว์ใน Thunder Ridge พร้อม Cured Light Hide 2 ผืน" },
        description = { "31:1329589486:1058433313 C 321:1327328286:1570726030", "ออร์กริมมาร์ขยายตัวไม่หยุด {class} เมื่อคนงานต้องใช้หนังบุผนังและหลังคาอาคารใหม่ พวกเขาก็มาหาข้า!\n\nหนังสัตว์เลื้อยคลานในธันเดอร์ริดจ์มักหนาเกินทำเกราะ แต่ใช้ก่อสร้างได้ดี เอาหนังพวกนั้นมาให้ข้าบ้าง พร้อมหนังบางที่ฟอกแล้ว มาดูกันว่าเจ้าทำงานหนังได้ดีแค่ไหน!" },
        completion = { "71:594419514:373956283", "งานของเจ้าช่วยให้ Orgrimmar เติบโต จงจำไว้เวลาเดินไปตามถนนของเมืองนี้" },
        progress = { "4:1517439344:201828488", "ว่าอย่างไร?" },
        required = { [275720] = { "17:1941062819:166379621", "หนังจิ้งจกหยาบ" }, [4231] = { "16:1653512981:912525807", "หนังบางที่ฟอกแล้ว" } },
        steps = { { "17:1941062819:166379621", "หนังจิ้งจกหยาบ" }, { "16:1653512981:912525807", "หนังบางที่ฟอกแล้ว" } },
    },
    [96876] = { -- Ukor's Lost Pack
        title = { "16:1774787505:1366394809", "กระเป๋าที่อูคอร์ทำหาย" },
        objective = { "44:201377444:1365505245", "นำกระเป๋ากลับไปให้ Ukor ทางใต้ของ Durotar" },
        description = { "61:1340683084:939460949", "ชื่อ “Ukor” เย็บไว้อย่างหยาบ ๆ ตรงฝาพับกระเป๋า" },
        progress = { "21:2087569780:800069969", "มีอะไรให้ทำหรือ?" },
        completion = { "113:1227008540:4835188", "กระเป๋าข้า! ตอนทำตกเพราะหนีแมงมุมยักษ์นั่น ข้านึกว่าจะไม่ได้เห็นอีกแล้ว เจ้าเป็นวีรบุรุษจริง ๆ!" },
        required = { [275722] = { "16:1774787505:1366394809", "สัมภาระที่หายไปของ Ukor" } },
        steps = { { "16:1774787505:1366394809", "สัมภาระที่หายไปของ Ukor" } },
    },
    [96877] = { -- Halikor's Hoof
        title = { "14:768139592:1316945848", "กีบของฮาลิคอร์" },
        objective = { "36:1021117155:1338014239", "นำ Halikor's Hoof ไปส่งที่ Orgrimmar" },
        description = { "73:505536679:1713644404", "กีบมหึมานี้เป็นหลักฐานว่าเจ้าเอาชนะสัตว์เลื้อยคลานทรงพลังตัวนั้นได้" },
        completion = { "58:591629404:803279680", "ของที่ระลึกจากการล่าชิ้นใหญ่ทีเดียว นักผจญภัย! คงสู้กันดุเดือดน่าดู!", variants = { { "15:855162936:491727168 C 33:1101615489:166042721", "ของที่ระลึกจากการล่าชิ้นใหญ่ทีเดียว {class}! คงสู้กันดุเดือดน่าดู!" } } },
