    },
    [97223] = { -- Bloodtalon Matriarch
        title = { "20:986080788:1272314612", "แม่ฝูงบลัดทาลอน" },
        objective = { "68:1841706731:1580026554", "นำ Eggs of the Bloodtalon Matriarch ไปให้ Xar'Ti ที่ Sen'jin Village" },
        description = { "467:788929965:2057976492", "แรปเตอร์ทุกตัวที่เจ้าเห็นตรงหน้า ข้าฝึกด้วยตนเอง พวกมันมาจากทั่วคาลิมดอร์ แต่บางตัวที่ฝีเท้าดีที่สุดมาจากฝูงบลัดทาลอนบนเกาะนอกชายฝั่งเรา\n\nตัวหนึ่งในฝูงคือแม่ฝูงบลัดทาลอน ดุร้ายเป็นพิเศษและฆ่าคนจากหมู่บ้านเราไปหลายคน มันอันตรายเกินจะปล่อยไว้ตามชายเขต หากเจ้าโค่นมันได้ เอาไข่ของมันกลับมาด้วย เราจะได้เลี้ยงลูกที่ฟักออกมาให้เป็นพวกเราแทนที่จะเป็นศัตรู" },
        progress = { "372:980010969:1747971965", "บลัดทาลอนขึ้นชื่อเรื่องไหวพริบและความเร็ว เมื่อเลี้ยงตั้งแต่ยังอยู่ในไข่จนโตเต็มวัย พวกมันเป็นคู่หูที่ดี\n\nน่าเสียดายที่แรปเตอร์โตเต็มวัยฝึกยากมาก ข้าลองจับแม่ฝูงมาหลายครั้ง แต่พักหลังมันอันตรายเกินไป\n\nถึงอย่างนั้น ข้าก็หวังจะรักษาสายเลือดของมันไว้ด้วยการเลี้ยงลูกให้เป็นคู่หูของพวกเราที่เซนจิน" },
        completion = { "149:828385700:623526097", "ขอบใจ สหาย ข้าดีใจที่เราจะรักษาสายเลือดของมันไว้และเลี้ยงลูกให้เป็นพวกเรา เจ้าได้ช่วยเผ่าของเราอย่างมาก", variants = { { "11:1191658970:1224418299 N 132:1755173688:1904316515", "ขอบใจ {name} ข้าดีใจที่เราจะรักษาสายเลือดของมันไว้และเลี้ยงลูกให้เป็นพวกเรา เจ้าได้ช่วยเผ่าของเราอย่างมาก" } } },
        required = { [277128] = { "25:61706105:1005311311", "ไข่ของแม่พันธุ์ Bloodtalon" } },
        steps = { { "25:61706105:1005311311", "ไข่ของแม่พันธุ์ Bloodtalon", variants = { { "26:1607533985:1478990422", "ไข่ของแม่พันธุ์ Bloodtalon" } } } },
    },
    [97225] = { -- Forgotten Loa Idols
        title = { "19:1206691315:747414801", "รูปเคารพโลอาที่ถูกลืม" },
        objective = { "98:1661837467:1761104971", "เก็บ Forgotten Loa Idols 8 ชิ้นจาก Echo Isles แล้วนำไปให้ Master Gadrin ที่ Sen'jin Village", amount = { "8:1089852795:1107240600 W1 89:492995392:988830792", "เก็บ Forgotten Loa Idols {world1} ชิ้นจาก Echo Isles แล้วนำไปให้ Master Gadrin ที่ Sen'jin Village" } },
        description = { "502:1618398048:1836028704", "ตอนเราหนีจากหมู่เกาะที่ซาลาซานกับพวกยึดอยู่ เราทิ้งรูปเคารพล้ำค่าไว้มาก รูปเหล่านั้นช่วยให้เราติดต่อวิญญาณที่เคารพบูชา นั่นคือโลอาของเรา พวกมันสำคัญต่อเผ่าของเรายิ่งนัก\n\nสาวกซาลาซานไม่เคารพโลอาของเราและเอารูปเคารพไปทิ้งกระจัดกระจายทั่วเกาะใหญ่ที่สุด\n\nหากเราเก็บรูปเหล่านี้คืนไม่ได้ เรื่องนี้คงไม่พ้นสายตาของโลอา การทำให้โลอาขุ่นเคืองเป็นเรื่องร้ายแรง\n\nไปเถิด ตามหารูปเคารพโลอาให้มากที่สุดแล้วเอากลับมาให้ข้า" },
        progress = { "75:310407885:1379752915", "พบรูปเคารพโลอาของเราหรือยัง สหาย? เราต้องเริ่มพิธีอีกครั้งเร็ว ๆ นี้", variants = { { "30:692551954:44664084 N 39:1043773519:1494483724", "พบรูปเคารพโลอาของเราหรือยัง {name}? เราต้องเริ่มพิธีอีกครั้งเร็ว ๆ นี้" } } },
        completion = { "210:1022127338:1209955630", "วันนี้เจ้าทำคุณครั้งใหญ่ให้เผ่าของเรา\n\nต่างจากบางเผ่า ความสัมพันธ์ของเรากับโลอาตั้งอยู่บนความเคารพบูชา เราติดหนี้พวกท่านมาก\n\nข้าไม่อยากให้ดาร์กสเปียร์เสียความโปรดปรานจากพวกท่าน" },
        required = { [277135] = { "18:2143822976:1956473027", "เทวรูปโลอาที่ถูกลืม" } },
        objectiveLabels = {
            item = { ["Forgotten Loa Idol"] = "เทวรูปโลอาที่ถูกลืม" },
        },
    },
    [97279] = { -- Wayward Weapons
        title = { "15:1256937051:1297228533", "อาวุธฝึกที่ถูกทิ้ง" },
        objective = { "80:948073258:756238824", "เก็บ Abandoned Training Weapons 6 ชิ้น แล้วกลับไปหา Kzan Thornslash ใน The Den", amount = { "8:1089852795:1107240600 W1 71:1350078619:1746081930", "เก็บ Abandoned Training Weapons {world1} ชิ้น แล้วกลับไปหา Kzan Thornslash ใน The Den" } },
        description = { "504:757663044:23985321", "มีทหารใหม่อย่างเจ้าหลั่งไหลเข้ามา อาวุธเลยจัดหาให้ทันยาก ช่างอาวุธของเราชื่อคซานกำลังขาดอาวุธฝึก ส่วนข้าก็อยากรู้ว่าเจ้ามีฝีมือแค่ไหน จะได้รู้ว่าให้ทำอะไรได้บ้าง โชคดีที่ข้ามีวิธีแก้ทั้งสองเรื่อง\n\nระหว่างออกไปฝึกฝีมือกับหมูป่า เก็บอาวุธฝึกที่ถูกทิ้งมาหกชิ้น พวกทหารใหม่ที่สอบไม่ผ่านทิ้งไว้บนพื้น เมื่อได้แล้ว นำไปคืนคซาน ช่างอาวุธของเราที่อยู่ด้านหลังข้าในเดอะเดน" },
        progress = { "98:2057569402:1644086478", "ธรอมคา นักผจญภัย โกรักบอกให้ข้ารอเจ้า ดีใจที่เห็นเจ้ากลับมาครบสามสิบสอง!", variants = { { "10:1652484069:1189355142 C 137:1608819528:934755909", "ธรอมคา {class} โกรักบอกให้ข้ารอเจ้า ดีใจที่เห็นเจ้ากลับมาปลอดภัย!\n\nเจ้าเก็บอาวุธฝึกที่ข้าขอได้หรือไม่?" } } },
        completion = { "170:1976759131:497288590", "เจ้าเก็บอาวุธฝึกที่ข้าขอได้หรือไม่?\n\nขอบใจที่นำอาวุธกลับมา สหาย ข้าจะซ่อมให้ทหารใหม่รุ่นถัดไป", variants = { { "39:1371512746:2010123191 N 66:503601460:1991532927", "ขอบใจที่นำอาวุธกลับมา {name} ข้าจะซ่อมให้ทหารใหม่รุ่นถัดไป" } } },
        required = { [277653] = { "25:863416177:2043352183", "อาวุธฝึกซ้อมที่ถูกทิ้งไว้" } },
        steps = { { "25:863416177:2043352183", "อาวุธฝึกซ้อมที่ถูกทิ้งไว้" } },
    },
    [97281] = { -- A Simmering Storm
        title = { "17:1177880831:207468515", "พายุที่คุกรุ่น" },
        objective = { "57:704471140:1713976868", "นำ Dull Stormy Orb ไปให้ Rezlak ใกล้ Drygulch Ravine" },
        description = { "348:1965048587:538160597", "<ตรงหน้าเจ้าคือลูกแก้วประหลาดผิวด้าน เมื่อหยิบขึ้นมาเหมือนจะมีกระแสไฟอ่อน ๆ สั่นอยู่ข้างใน พอมองใกล้ ๆ เห็นหมอกดำหมุนวนและมีประกายไฟแลบวาบเป็นครั้งคราว\n\nฮาร์ปีคงใช้มันทำอะไรสักอย่าง บางทีเรซแล็กอาจสนใจของชิ้นนี้?>", variants = { { "352:1738942028:1819289332", "<ตรงหน้าเจ้าคือลูกแก้วประหลาดผิวด้าน เมื่อหยิบขึ้นมาเหมือนจะมีกระแสไฟอ่อน ๆ สั่นอยู่ข้างใน พอมองใกล้ ๆ เห็นหมอกดำหมุนวนและมีประกายไฟแลบวาบเป็นครั้งคราว\n\nฮาร์ปีคงใช้มันทำอะไรสักอย่าง บางทีเรซแล็กอาจสนใจของชิ้นนี้?>" } } },
        completion = { "131:1579934249:1528510376", "โว้! ไปเจอของเจ๋ง ๆ แบบนั้นที่ไหน? รู้ไหม มันทำให้ฉันนึกถึงอีกเรื่องที่แกซโลว์เจ้านายฉันชอบสอน..." },
    },
    [97282] = { -- Stormy Potential
        title = { "16:1498572124:108955647", "พลังที่ซ่อนในพายุ" },
        objective = { "69:188176000:1844862970", "นำ Charged Thunder Lizard Organs 5 ชิ้นไปให้ Rezlak ใกล้ Drygulch Ravine", amount = { "6:1273960851:929420321 W1 62:284482407:454171213", "นำ Charged Thunder Lizard Organs {world1} ชิ้นไปให้ Rezlak ใกล้ Drygulch Ravine" } },
        description = { "477:2000128714:1067324707", "“เรซแล็ก เมื่อโอกาสมาเคาะประตู นายต้องพร้อมคว้าไว้” นี่เป็นคำสอนเด็ดอีกข้อของแกซโลว์ และฉันตั้งใจจะทำอย่างนั้นเลย\n\nลูกแก้วนี่ดูไม่เสีย แค่พลังหมด ฉันคิดวิธีอัดพลังให้มันกลับมาเต็มได้แล้ว!\n\nมีธันเดอร์ลิซาร์ดอยู่ฝูงหนึ่งในหุบทางตะวันตก อวัยวะของพวกมันเก็บประจุไฟแรง ๆ ไว้ เหมาะกับงานนี้พอดี\n\nไปเก็บมาให้ฉันหน่อย!", variants = { { "478:803851845:1647226233", "“เรซแล็ก เมื่อโอกาสมาเคาะประตู นายต้องพร้อมคว้าไว้” นี่เป็นคำสอนเด็ดอีกข้อของแกซโลว์ และฉันตั้งใจจะทำอย่างนั้นเลย\n\nลูกแก้วนี่ดูไม่เสีย แค่พลังหมด ฉันคิดวิธีอัดพลังให้มันกลับมาเต็มได้แล้ว!\n\nมีธันเดอร์ลิซาร์ดอยู่ฝูงหนึ่งในหุบทางตะวันตก อวัยวะของพวกมันเก็บประจุไฟแรง ๆ ไว้ เหมาะกับงานนี้พอดี\n\nไปเก็บมาให้ฉันหน่อย!" } } },
        progress = { "226:1730349182:1009342108", "นายอาจแปลกใจที่ชื่อว่าธันเดอร์ลิซาร์ด แต่ดันยิงสายฟ้าแทนที่จะคำรามเหมือนฟ้าร้อง\n\nมันยิงสายฟ้าจริง ๆ นะ\n\nเชื่อฉันเถอะ ถ้าโชคดี นายจะมีโอกาสเรียนรู้บทนี้สักครั้ง" },
        completion = { "328:1754126476:544392885", "เฮ้ ขอบใจนะเพื่อน! นายช่วยฉันได้มากจริง ๆ ฉันซึ้งใจ\n\nหวังว่าจะใช้อวัยวะพวกนี้ชาร์จพลังให้เต็มได้ พนันว่าพวกฮาร์ปีตัวแสบจะคิดให้ดีก่อนมาโจมตีคาราวานฉันอีก หวังจริง ๆ ว่าจะได้ผล\n\nยังไงนายก็ทำตามข้อตกลงแล้ว รับนี่ไปเป็นค่าลำบาก" },
        required = { [277665] = { "28:381542876:1882413696", "อวัยวะกิ้งก่าสายฟ้าที่มีประจุ" } },
        steps = { { "28:381542876:1882413696", "อวัยวะกิ้งก่าสายฟ้าที่มีประจุ" } },
    },
    [99048] = { -- A Missing Hand
        title = { "14:113044414:1103025614", "สายลับที่หายตัว" },
        objective = { "45:178104671:989747947", "ตามหา Heglan Shadeeye ทางเหนือของ Tiragarde Keep" },
        description = { "314:703627145:879430268", "สมาชิกของแชตเทิร์ดแฮนด์ กลุ่มนักสู้ที่ใช้วิธี... แนบเนียนกว่า กำลังเฝ้าดูป้อมทิราการ์ดจากระยะไกล จู่ ๆ รายงานของนางก็ขาดหาย\n\nข้าไม่คิดว่ามนุษย์จะจับนางได้ จึงกังวลว่าอาจมีภัยที่ร้ายกว่านั้น ลองตามหานางดู หวังว่าแค่ส่งข่าวมาช้า" },
        completion = { "145:1221657027:647081737", "ร่างของเฮกแลนเย็นชืดอยู่ท่ามกลางซากกระท่อม\n\nสิ่งที่ฆ่านางดูจะไม่ใช่มนุษย์ อาจมีร่องรอยของเหตุการณ์อยู่ใกล้ ๆ" },
    },
    [99049] = { -- Threat from Below
        title = { "17:1106616463:110784093", "ภัยจากเบื้องล่าง" },
        objective = { "44:583684796:1004322456", "ค้นหาร่องรอยของสิ่งที่โจมตี Heglan Shadeeye" },
        description = { "234:74273542:1947399096", "พื้นที่แถวนั้นพังยับ มีรอยปะทะชัดเจน สิ่งที่ซุ่มโจมตีเฮกแลนคงไม่ได้หนีไปโดยไม่บาดเจ็บ น่าจะมีร่องรอยว่าเกิดอะไรขึ้นอยู่ใกล้ ๆ\n\nออร์กนิลคงอยากเห็นหลักฐานที่ผู้โจมตีทิ้งไว้" },
        progress = { "17:574738785:1099274309", "เจ้าพบนางหรือยัง?" },
        completion = { "212:2141722926:30804916", "ธงกับเศษใบดาบนี้เป็นของนากา! พวกมันต้องลงมาตามชายฝั่งจากทางเหนือแน่\n\nเราจะปล่อยให้พวกมันตั้งหลักที่นี่ไม่ได้ หากถูกกดดันจากสองด้าน เรเซอร์ฮิลล์คงรับไม่ไหว" },
        required = { [286012] = { "13:149939322:1490513808", "มีดสั้นแบบออร์ก" }, [286011] = { "12:1545942352:1664766864", "เศษธง" }, [286010] = { "19:1752718191:2065261521", "สามง่ามกระดูกหัก" } },
        steps = { { "13:149939322:1490513808", "มีดสั้นแบบออร์ก" }, { "12:1545942352:1664766864", "เศษธง" }, { "19:1752718191:2065261521", "สามง่ามกระดูกหัก" } },
    },
    [99051] = { -- Threat from Below
        title = { "17:1106616463:110784093", "ภัยจากเบื้องล่าง" },
        objective = { "25:1152692658:1524999072", "เก็บ Naga Spinefin 9 ชิ้น", amount = { "8:1089852795:1107240600 W1 16:887205547:1175618431", "เก็บ Naga Spinefin {world1} ชิ้น" } },
        description = { "270:441592115:2036154241", "นี่ไม่ใช่ครั้งแรกที่เจ้างูพวกนั้นมาก่อกวนเรา ต้องสั่งสอนให้รู้ว่าที่นี่ไม่ต้อนรับพวกมัน\n\nหาว่าหน่วยสอดแนมของมันตั้งค่ายอยู่ที่ไหน แล้วกำจัดเสีย เอาครีบพวกมันมาให้ข้าเป็นหลักฐาน ต้องรีบลงมือให้พวกมันเข้าใจ" },
        progress = { "53:1269040999:352409214", "หวังว่าเจ้าพวกงูโสโครกจะไม่ได้ทำให้เจ้าลำบากนะ?" },
        completion = { "128:2080732020:424812836", "หวังว่าคราวนี้พวกมันจะเผ่นกลับขึ้นเหนือ ข้าจะให้ทหารคอยจับตาดูพวกที่ตกค้างหรือสิ่งผิดปกติ" },
        required = { [286008] = { "13:535182958:1035025265", "ครีบหนามของนากา" } },
        steps = { { "13:535182958:1035025265", "ครีบหนามของนากา" } },
    },
    [99052] = { -- Threat from Below
        title = { "17:1106616463:110784093", "ภัยจากเบื้องล่าง" },
        objective = { "91:960112161:1791161859", "สังหารยักษ์ทะเลตามชายฝั่งด้านเหนือของ Durotar แล้วนำหลักฐานกลับมา" },
        description = { "327:1759304325:280617986", "หน่วยสอดแนมของข้ารายงานว่ามียักษ์ทะเลตามพวกนากาลงมาที่นี่ ไม่แน่ว่าพวกมันตั้งใจพามาหรืออย่างไร แต่ยังไงมันก็อันตราย\n\nมันยังหนุ่ม แต่ฉีกออร์คที่ไม่ทันระวังเป็นสองท่อนได้ในพริบตา ข้าต้องการให้กำจัดมัน ขอแนะนำให้หาคนไปช่วยด้วย" },
        progress = { "27:924035930:262340297", "จัดทั้งเลือดและสายฟ้าให้พวกมัน!" },
        completion = { "129:731458315:337367310", "ฮ่า! ข้าได้ยินเสียงร่างมันล้มจากตรงนี้เลย!\n\nจงภูมิใจในชัยชนะวันนี้ มีไม่กี่คนที่พูดได้ว่ารอดจากการสู้กับยักษ์ทะเล", variants = { { "129:1464967443:524700370", "ฮ่า! ข้าได้ยินเสียงร่างมันล้มจากตรงนี้เลย!\n\nจงภูมิใจในชัยชนะวันนี้ มีไม่กี่คนที่พูดได้ว่ารอดจากการสู้กับยักษ์ทะเล" } } },
        required = { [286009] = { "12:1766597701:1579320617", "เข็มขัดของ Aggor" } },
        steps = { { "12:1766597701:1579320617", "เข็มขัดของ Aggor" } },
    },
    [99123] = { -- Lost in the Shadows
        title = { "19:1744525205:347664339", "หลงอยู่ในเงามืด" },
        objective = { "99:2076597525:119919097", "ช่วย Pal'juh หนีจาก Kolkar Crag แล้วแจ้งผลสำเร็จให้ Master Vornal ที่ Sen'jin Village" },
        description = { "196:1574341182:1868626491", "ข้าตัดสินใจมาสอดแนมแถวโคลคาร์แคร็กคนเดียว น่าเสียดายที่พลังเวทดันหมดผิดจังหวะ ตั้งแต่นั้นข้าก็ต้องซ่อนอยู่ที่นี่\n\nถ้าช่วยข้าหนีออกไปได้ ข้าจะขอบใจมาก" },
        completion = { "215:603465534:235485051", "อา ปาลจูหาเรื่องใส่ตัวอีกแล้วหรือ?\n\nหวังว่าคราวนี้นางจะได้บทเรียนเรื่องออกไปคนเดียว ขอบใจที่ช่วยนาง นางเป็นพรานที่มีอนาคต เพียงแต่ชอบทำตัวเหมือนแรปเตอร์มากกว่าเสือ", variants = { { "157:1968851803:168955426 C 52:1772425133:1759899163", "อา ปาลจูหาเรื่องใส่ตัวอีกแล้วหรือ?\n\nหวังว่าคราวนี้นางจะได้บทเรียนเรื่องออกไปคนเดียว ขอบใจที่ช่วยนาง นางเป็น{class}ที่มีอนาคต เพียงแต่ชอบทำตัวเหมือนแรปเตอร์มากกว่าเสือ" } } },
        objectiveLabels = {
            event = { ["Escort Pal'juh out of Kolkar Crag."] = "คุ้มกัน Pal'juh ออกจาก Kolkar Crag" },
        },
    },
    [743] = { -- Dangers of the Windfury
        title = { "23:32885047:562136575", "ภัยจากวินด์ฟิวรี" },
        objective = { "64:1409576419:1805950267", "นำ Windfury Talon 8 ชิ้นไปให้ Ruul Eagletalon ที่ Bloodhoof Village" },
        description = { "46:1700829981:473210347 N 406:199525738:209846277", "ขอบใจที่สละเวลามาคุยกับข้า {name} ข้าคือรูอูล นักรบและครู\n\nเห็นได้ชัดว่าเจ้าถึงวัยต้องเตรียมตัวรับบททดสอบแล้ว หากคิดจะผจญภัยไกลออกไปจากมัลกอร์\n\nหากอยากทดสอบกำลัง เริ่มจากตามหาฮาร์ปีวินด์ฟิวรีทางตะวันออกเฉียงใต้ พวกมันทำรังอยู่ตามไหล่เขาห่างจากถนน\n\nพวกมันเป็นศัตรูตามธรรมชาติของเราที่นี่ และจะเป็นเครื่องวัดฝีมือเจ้าได้ดี" },
        progress = { "104:213331364:1822588108", "พวกวินด์ฟิวรีเป็นศัตรูร้ายกาจ มีเพียงความอยากกินเนื้อสดที่เทียบได้กับฝีมือรบของพวกมัน" },
        completion = { "20:1921578502:569519135 N 79:1240645580:1826739809", "ทำได้ดี {name} เจ้าดูพร้อมเดินทางต่อแล้ว ขอให้สายลมหนุนหลังเจ้าเสมอ" },
        required = { [4751] = { "14:798963637:1128516576", "กรงเล็บ Windfury" } },
        steps = { { "14:798963637:1128516576", "กรงเล็บ Windfury" } },
    },
    [745] = { -- Sharing the Land
        title = { "16:1288866363:1202053910", "อยู่ร่วมบนผืนดิน" },
        objective = { "124:1293290097:352079960", "สังหาร Palemane Tanner 10 ตัว, Palemane Skinner 8 ตัว และ Palemane Poacher 5 ตัว แล้วกลับไปหา Baine Bloodhoof ที่ Bloodhoof Village" },
        description = { "N 496:1038560660:559725050", "{name} ความขัดแย้งมากมายทิ้งบาดแผลไว้บนผืนดินนี้ ข้าหวังว่าเจ้าจะไม่ต้องเห็นมากเท่าข้า แต่มีเรื่องหนึ่งที่อยากให้เจ้าไปดู เจ้าจะได้รู้ว่าแม้ภัยเล็กน้อย หากปล่อยไว้ ก็ทำร้ายแผ่นดินได้ร้ายแรงเพียงใด\n\nโนลล์เพลเมนตั้งถิ่นทางใต้ของบลัดฮูฟและในถ้ำทางตะวันตก พวกมันไม่เคารพความพยายามของเราที่จะเจรจา และฆ่าสัตว์ป่าในมัลกอร์ตามอำเภอใจ\n\nการเจรจาช่วยอะไรไม่ได้แล้ว" },
        progress = { "106:2109766323:225076534", "หากพวกเพลเมนเคารพผืนดินกับผู้ที่อาศัยอยู่มากกว่านี้ ความขัดแย้งคงไม่เกิดขึ้น" },
        completion = { "N 233:76270112:1383174878", "{name} ดีแล้วที่เจ้าจริงจังกับงานที่ข้าฝาก การเคารพผืนดินและสิ่งมีชีวิตบนผืนดินนั้นสำคัญ ชีวิตกับความตายหมุนเวียนเป็นวงจร... ทั้งสองล้วนจำเป็น มีอย่างหนึ่งโดยปราศจากอีกอย่างไม่ได้ ลองตรองดูและจดจำไว้ให้ดี" },
        objectiveLabels = {
            monster = { ["Palemane Tanner slain"] = "ปราบ ช่างฟอกหนัง Palemane", ["Palemane Skinner slain"] = "ปราบ นักถลกหนัง Palemane", ["Palemane Poacher slain"] = "ปราบ นักล่าสัตว์เถื่อน Palemane" },
        },
    },
    [746] = { -- Dwarven Digging
        title = { "15:1311498461:788815937", "การขุดค้นของคนแคระ" },
        objective = { "156:227224923:1453623373", "รวบรวม Prospector's Pick 5 ชิ้น\n\nทุบ Prospector's Pick ที่เตาหลอมให้กลายเป็น Broken Tools\n\nนำ Broken Tools 5 ชิ้นไปให้ Baine Bloodhoof ที่ Bloodhoof Village" },
        description = { "418:1848469694:1044935062", "มีคนแคระกำลังเตรียมพื้นที่ขุดทางตะวันตกเฉียงเหนือ พวกเขาคิดว่ามีความลับฝังอยู่ในดิน นั่นก็จริง แต่การขุดแผ่นดินจนเป็นโพรงและทำให้แปดเปื้อนไม่ใช่วิธีเรียนรู้จากมัน\n\nเก็บเครื่องมือขุดของคนแคระมาทุบ แล้วนำเครื่องมือที่พังกลับมาให้ข้า\n\nเจ้าทุบเครื่องมือได้ที่เตาหลอม ในธันเดอร์บลัฟฟ์มีเตาหลอมอยู่ แต่จะใช้เตาไหนก็ได้ แม้แต่เตาที่ค่ายคนแคระ" },
        progress = { "7:989913233:66981971 N 119:1467897831:1440967751", "สวัสดี {name} เจ้าได้ Broken Tools มาแล้วหรือ? การขุดของคนแคระจะทำให้โคโดแห่งมัลกอร์คลุ้มคลั่ง ต้องหยุดการทำลายผืนดินนี้เสีย!" },
        completion = { "11:1191658970:1224418299 N 141:702163222:620228347", "ขอบใจ {name} นี่จะช่วยให้สัตว์แห่งมัลกอร์สงบลง หากเหล่าวิญญาณเป็นใจ คนแคระอาจได้เรียนรู้ด้วยว่าการขุดแผ่นดินเป็นโพรงไม่ใช่หนทางสู่ความรู้" },
        required = { [4703] = { "12:1730260084:1856797205", "เครื่องมือที่ชำรุด" } },
        steps = { { "12:1730260084:1856797205", "เครื่องมือที่ชำรุด" } },
    },
    [748] = { -- Poison Water
        title = { "12:1055912826:656651942", "น้ำปนพิษ" },
        objective = { "85:1188738985:544764566", "นำ Prairie Wolf Paw 6 ชิ้นและ Plainstrider Talon 4 ชิ้นไปให้ Mull Thunderhorn ที่ Bloodhoof" },
        description = { "469:226821858:383988055 N 1:46:46", "พวกก็อบลินกับสมุนทำให้บ่อน้ำศักดิ์สิทธิ์ของเราแปดเปื้อน! เราจะปล่อยไว้ไม่ได้\n\nการชำระบ่อแต่ละแห่งต้องเริ่มจากข้าสร้างโทเทมชำระล้าง แล้วเจ้าจึงนำโทเทมไปที่บ่อเพื่อทำพิธี\n\nเราจะเริ่มจากโทเทมสำหรับบ่อวินเทอร์ฮูฟ ต้องขอแรงจากผืนดิน ล่าหมาป่าทุ่งเอาอุ้งเท้า และล่าเพลนสไตรเดอร์โตเต็มวัยเอากรงเล็บ พวกมันอยู่ทางตะวันตกเฉียงใต้\n\nเอาอุ้งเท้ากับกรงเล็บกลับมาให้ข้า {name}" },
        progress = { "33:890207944:695101706 N 1:63:63", "เจ้าได้อุ้งเท้ากับกรงเล็บมาแล้วหรือ {name}?" },
        completion = { "20:1921578502:569519135 N 67:2105391441:2081509091", "ทำได้ดี {name} ข้าจะนำของเหล่านี้มาผูกพลังไว้ในโทเทมชำระล้าง" },
        required = { [4758] = { "16:1893226194:2147431981", "อุ้งเท้าหมาป่าทุ่งหญ้า" }, [4759] = { "18:498204659:471895738", "กรงเล็บ Plainstrider" } },
        steps = { { "16:1893226194:2147431981", "อุ้งเท้าหมาป่าทุ่งหญ้า" }, { "18:498204659:471895738", "กรงเล็บ Plainstrider" } },
    },
    [749] = { -- The Ravaged Caravan
        title = { "19:32690449:1494087244", "คาราวานที่ถูกทำลาย" },
        objective = { "94:951328527:1824237059", "Morin Cloudstalker ต้องการให้เจ้าตรวจของในลังเสบียงที่ Ravaged Caravan" },
        description = { "480:1398714499:900707891", "หลายวันก่อน เราพบคาราวานของเวนเจอร์โคเดินทางพร้อมยามคุ้มกันเลียบฝั่งเหนือของทะเลสาบสโตนบูล เราเสียพวกพ้องไปสองคนในการปะทะก่อนหน้านั้น จึงรีบเข้าตีจนคาราวานพังยับ\n\nเราทิ้งลังเสบียงไว้ คิดว่าคบเพลิงคงเผาของมีค่าหมด แต่มีคนเห็นคนงานเก็บกู้ของเวนเจอร์โคใกล้ซากเกวียนที่ไหม้ บางทีเราอาจคิดผิด\n\nเจ้าลองไปที่คาราวานแล้วตรวจดูของในลังได้ไหม" },
        completion = { "216:693173795:325024859", "ทุกด้านของลังประทับตราแผนกเหมืองของเวนเจอร์โค ข้อความที่พิมพ์ไว้อย่างเรียบร้อยด้านข้างระบุว่าของข้างในจะถูกส่งไปแปรรูปที่โรงงานกลางแห่งหนึ่งของบริษัท" },
    },
    [751] = { -- The Ravaged Caravan
        title = { "19:32690449:1494087244", "คาราวานที่ถูกทำลาย" },
        objective = { "78:610424043:2123085640", "นำ Venture Co. Documents กลับไปให้ Morin Cloudstalker ใกล้ Bloodhoof Village" },
        description = { "332:1040951247:720973620", "เมื่องัดฝาลังออก พบแร่หลายชนิดอัดแน่นอยู่ข้างใน เป็นหลักฐานอีกชิ้นว่าเวนเจอร์โคทำเหมืองในมัลกอร์ เจ้าหยิบปึกเอกสารที่มัดแน่นออกจากกองแร่ด้านบน\n\nจากเชิงเขาทางตะวันออก เจ้าได้ยินเสียงทำงานแว่ว ๆ และเห็นควันลอยจากกองไฟใหญ่" },
        progress = { "6:1136836709:1914036474 N 198:656792157:163894268", "สวัสดี {name} ได้เบาะแสใหม่เกี่ยวกับแผนหรืองานของเวนเจอร์โคในบ้านเราไหม?\n\nหากพวกมันคิดจะกอบโกยจากผืนดินเราเหมือนที่ทำกับที่อื่น หน่วยเอาต์รันเนอร์จะรีบหยุดพวกมัน" },
        completion = { "175:807058783:1901668309", "ดูเหมือนเวนเจอร์โคคิดจะปล้นทรัพยากรธรรมชาติของเราจริง ๆ ดีที่ได้รู้แน่ ตอนนี้เราคงต้องลงมือแล้ว" },
        required = { [4834] = { "21:1199154032:2011101834", "เอกสารของบริษัท Venture" } },
        steps = { { "21:1199154032:2011101834", "เอกสารของบริษัท Venture" } },
    },
    [754] = { -- Winterhoof Cleansing
        title = { "20:184427336:259803148", "ชำระบ่อวินเทอร์ฮูฟ" },
        objective = { "97:1964667646:619376926", "ใช้ Winterhoof Cleansing Totem ที่ Winterhoof Water Well แล้วกลับไปหา Mull Thunderhorn" },
        description = { "295:1331435843:379889079 N 1:46:46", "ข้าทำโทเทมชำระบ่อวินเทอร์ฮูฟเสร็จแล้ว ทีนี้เจ้าต้องนำไปที่บ่อเพื่อทำพิธีชำระล้าง บ่ออยู่ทางตะวันออกเฉียงใต้ มีพวกก็อบลินชั่วเฝ้าอยู่!\n\nงานนี้ไม่ง่าย แต่หากเราอยากใช้น้ำจากบ่ออีก เจ้าก็ต้องลงมือ\n\nขอให้โชคดี {name}" },
        progress = { "14:1857990048:1669172049 N 46:1507229661:2055611619", "อย่าชักช้า {name} ต้องชำระสิ่งแปดเปื้อนออกจากบ่อวินเทอร์ฮูฟ!" },
        completion = { "142:2135757024:1377766475 N 56:1021458431:715980895", "ข่าวสิ่งที่เจ้าทำเพิ่งมาถึงข้า ตอนนี้สัตว์แถวนั้นกลับไปดื่มน้ำจากบ่อกันแล้ว\n\nเจ้าทำคุณให้ผืนดินอย่างใหญ่หลวง {name} และทำคุณให้ชาวทอเรนด้วย" },
        objectiveLabels = {
            event = { ["Cleanse the Winterhoof Water Well"] = "ชำระล้างบ่อน้ำ Winterhoof" },
        },
    },
    [756] = { -- Thunderhorn Totem
        title = { "17:1801346463:1792559027", "โทเทมธันเดอร์ฮอร์น" },
        objective = { "61:279216440:212324205", "นำ Stalker Claw 6 ชิ้นและ Cougar Claw 6 ชิ้นไปให้ Mull Thunderhorn" },
        description = { "296:2118589260:197794171", "การสร้างโทเทมชำระล้างธันเดอร์ฮอร์นต้องใช้กรงเล็บจากสัตว์นักล่าในที่ราบมัลกอร์ ล่าแพรรีสตอล์กเกอร์เอากรงเล็บสตอล์กเกอร์ และล่าแฟลตแลนด์คูการ์เอากรงเล็บคูการ์ แล้วกลับมาหาข้า\n\nเจ้าจะพบสัตว์ทั้งสองชนิดทางตะวันออกและตะวันตก" },
        progress = { "N 115:1856628703:1053487305", "{name} เจ้าได้กรงเล็บที่ข้าให้ไปหาหรือยัง? บ่อน้ำธันเดอร์ฮอร์นยิ่งแปดเปื้อนขึ้นทุกชั่วโมง!" },
        completion = { "11:1191658970:1224418299 N 204:67169977:1409486548", "ขอบใจ {name} ความบริสุทธิ์ในวิธีล่าของสัตว์เหล่านี้สำคัญต่อการสร้างโทเทมชำระล้างชิ้นถัดไป\n\nพวกก็อบลินคงไม่มีวันเข้าใจว่าการต่อกรกับผืนดินต่างจากการอยู่ร่วมกับมันอย่างกลมกลืนเพียงใด" },
        required = { [4801] = { "13:2117381646:1488606671", "กรงเล็บนักสะกดรอย" }, [4802] = { "12:1784033085:656958976", "กรงเล็บคูการ์" } },
        objectiveLabels = {
            item = { ["Stalker Claws"] = "กรงเล็บนักสะกดรอย", ["Cougar Claws"] = "กรงเล็บคูการ์" },
        },
    },
    [758] = { -- Thunderhorn Cleansing
        title = { "21:1397256392:167151403", "ชำระบ่อธันเดอร์ฮอร์น" },
        objective = { "87:1485930634:786560618", "ใช้ Thunderhorn Cleansing Totem ที่ Thunderhorn Water Well แล้วกลับไปหา Mull" },
        description = { "20:867835031:113174174 N 236:2087074180:1280080767", "โทเทมพร้อมแล้ว {name} เจ้าต้องทำพิธีชำระล้างอีกครั้ง\n\nไปที่บ่อน้ำธันเดอร์ฮอร์นทางเหนือของหมู่บ้าน แล้วใช้โทเทมชำระล้างธันเดอร์ฮอร์นในพิธี เสร็จแล้วกลับมาหาข้า\n\nขอให้เหล่าวิญญาณนำทางเจ้า" },
        progress = { "45:810968089:1029718089 N 38:1097689862:1294008339", "บ่อน้ำธันเดอร์ฮอร์นยังแปดเปื้อนอยู่ {name} ได้โปรด เจ้าต้องทำพิธี!" },
        completion = { "155:1537247820:586708324", "บรรพชนตระกูลธันเดอร์ฮอร์นมาพูดกับข้าในฝัน ชื่นชมสิ่งที่เจ้าทำที่บ่อของพวกท่าน\n\nพวกท่านอยากมอบสิ่งนี้ให้แทนคำขอบคุณ..." },
        objectiveLabels = {
            event = { ["Cleanse the Thunderhorn Water Well"] = "ชำระล้างบ่อน้ำ Thunderhorn" },
        },
    },
    [759] = { -- Wildmane Totem
        title = { "14:954860389:2028024316", "โทเทมไวลด์เมน" },
        objective = { "69:2070736082:284265397", "นำ Prairie Alpha Teeth 8 ซี่ไปให้ Mull Thunderhorn ที่ Bloodhoof Village" },
        description = { "324:1168978916:1425175883", "เหลือบ่อน้ำที่ต้องชำระเพียงแห่งเดียว ตั้งชื่อตามตระกูลไวลด์เมน การทำให้บ่อนี้บริสุทธิ์ต้องขอเขี้ยวของนักล่าดุร้ายจากผืนดิน นั่นคือหมาป่าจ่าฝูงแห่งทุ่งหญ้า ออกตามหาจ่าฝูงทางเหนือ แล้วกลับมาหาข้าเมื่อล่าเสร็จ\n\nพวกจ่าฝูงมักเดินวนแถวเชิงผาของธันเดอร์บลัฟฟ์ เมืองอันยิ่งใหญ่ของเรา" },
        progress = { "N 36:1376837691:1133237289", "{name} เจ้าได้เขี้ยวที่ข้าขอหรือยัง?" },
        completion = { "11:1776810664:1873330125 N 102:1581503037:609621799", "ดีมาก {name} ข้าสัมผัสได้ถึงการเสียสละของผืนดินในของถวายนี้ ในใจข้าเอ่อล้นทั้งความเศร้าและความภูมิใจ" },
        required = { [4803] = { "19:1214827186:313443191", "เขี้ยวหมาป่าจ่าฝูงแห่งทุ่งหญ้า" } },
        steps = { { "19:1214827186:313443191", "เขี้ยวหมาป่าจ่าฝูงแห่งทุ่งหญ้า" } },
    },
    [760] = { -- Wildmane Cleansing
        title = { "18:1670412351:1495222235", "ชำระบ่อไวลด์เมน" },
        objective = { "93:576088049:1656377824", "ใช้ Wildmane Cleansing Totem ที่ Wildmane Water Well แล้วกลับไปหา Mull Thunderhorn" },
        description = { "90:994581090:256153813 N 205:819033289:194909594", "เหล่าวิญญาณกล่าวถึงการที่เจ้าชำระบ่อวินเทอร์ฮูฟและธันเดอร์ฮอร์น {name} โทเทมไวลด์เมนเสร็จแล้ว ภารกิจสุดท้ายรอเจ้าอยู่\n\nบ่อน้ำไวลด์เมนอยู่เหนือธันเดอร์บลัฟฟ์ จงทำพิธี! รักษาผืนดินจากพิษของก็อบลิน ให้น้ำสะอาดไหลอีกครั้ง!" },
        progress = { "49:1230573073:1708508521 N 21:646061621:1776698666", "บ่อสุดท้ายยังเน่าเหม็นและเป็นพิษ {name} เจ้าจะชักช้าไม่ได้!" },
        completion = { "96:33255517:1868387122 N 108:47328778:1976315405", "เจ้าทำสำเร็จแล้ว เจ้าชำระบ่อน้ำและรักษาผืนดินของเรา หมู่บ้านบลัดฮูฟขอบใจเจ้า {name}\n\nขอให้สายลมกระซิบบอกเล่าสิ่งที่เจ้าทำไปอีกร้อยฤดู และขอให้น้ำแห่งมัลกอร์สะอาดตลอดไป" },
        objectiveLabels = {
            event = { ["Cleanse the Wildmane Well"] = "ชำระล้างบ่อน้ำ Wildmane" },
        },
    },
    [761] = { -- Swoop Hunting
        title = { "13:138350009:1769223797", "ล่านกสวูป" },
        objective = { "69:2094767449:1491874347", "นำ Trophy Swoop Quill 8 ชิ้นไปให้ Harken Windtotem ที่ Bloodhoof Village" },
        description = { "414:701762832:1990516531", "สวูปเป็นนกเจ้าเล่ห์ ทั้งหาตัวและล่ายาก การรวบรวมขนสวูปได้เป็นเครื่องหมายแสดงไหวพริบและความมุ่งมั่นของพราน\n\nหากยินดีรับงานนี้ ก็ออกไปล่าสวูปในที่ราบ\n\nนำขนของพวกมันมาให้ข้า และนำเกียรติมาสู่ตระกูลเจ้า\n\nสวูปพบได้ทั่วมัลกอร์ แต่ตาเจ้าต้องไวถึงจะเห็น และกีบเจ้าต้องเร็วถึงจะจับได้" },
        progress = { "27:220237409:1833900634 N 27:305596327:1496041690", "เจ้าพบพวกสวูปหรือยัง {name}? ได้ขนพวกมันมาหรือไม่?" },
        completion = { "57:1713091793:1633552743 N 42:1071508604:1073341703 C 55:954109023:1714765345", "ข้ารู้ว่าการเก็บขนพวกนี้ไม่ง่าย {name} เจ้าพิสูจน์แล้วว่าเป็น {class} ที่มีฝีมือ ดีที่มีเจ้าอยู่ที่หมู่บ้านบลัดฮูฟ" },
        required = { [4769] = { "18:665451644:2005909863", "ขนนก Swoop ที่เก็บเป็นรางวัล" } },
        steps = { { "18:665451644:2005909863", "ขนนก Swoop ที่เก็บเป็นรางวัล" } },
    },
    [764] = { -- The Venture Co.
        title = { "15:1783456327:1047758648", "บริษัทเวนเจอร์โค" },
        objective = { "102:298950701:449480294", "สังหาร Venture Co. Worker 14 คนและ Venture Co. Supervisor 6 คนให้ Morin Cloudstalker ที่ Bloodhoof Village" },
        description = { "476:1934259777:842279555", "นี่อธิบายได้ว่าทำไมคนงานกับอุปกรณ์ของเวนเจอร์โคถึงเพิ่มขึ้นในมัลกอร์ ก็อบลินพวกนั้น... บริษัทขยายตัวเร็วเกินตัว อย่างที่เขาว่ากัน แค่เอาอะไรให้ก็อบลินดู ก็เหมือนได้ยินเสียงตาชั่งดังแว่วมาแล้ว\n\nเจ้าตัวเล็กละโมบ น่าเสียดายแทนกิจการของพวกมัน แต่เราทอเรนจะยอมให้มาดำเนินงานบนผืนดินเราไม่ได้ ไปที่เหมืองทางตะวันออกเฉียงเหนือของคาราวานที่พัง แล้วส่งสัญญาณให้พวกมันเข้าใจ" },
        progress = { "218:451738559:1801756354", "เวนเจอร์โคถูกปฏิเสธสิทธิ์ทำเหมืองในมัลกอร์ แต่ดูเหมือนพวกมันไม่ยอมรับคำปฏิเสธ พวกเราทอเรนพูดตรงอยู่แล้ว และมีวิธีอื่นให้พวกมันเข้าใจสิ่งที่เราบอก" },
        completion = { "256:2146364739:82529836", "สัญญาณขนาดนี้คงตีความผิดหรือทำเป็นมองไม่เห็นได้ยากแล้ว จริงไหม? เวนเจอร์โคจะได้รู้ว่าอย่าดูเบาทอเรน และอย่าทะนงว่าเราจะยอมให้ขโมยทรัพยากรรอบตัวไปโดยไม่ขัดขืน" },
        objectiveLabels = {
            monster = { ["Venture Co. Worker slain"] = "ปราบ คนงาน Venture Co.", ["Venture Co. Supervisor slain"] = "ปราบ หัวหน้าคนงาน Venture Co." },
        },
    },
    [765] = { -- Supervisor Fizsprocket
        title = { "22:1479117171:1302308199", "หัวหน้างานฟิซสปร็อกเก็ต" },
        objective = { "96:1420678287:971212594", "สังหาร Supervisor Fizsprocket แล้วนำกระดานหนีบเอกสารของเขากลับไปให้ Morin Cloudstalker ที่ Bloodhoof Village" },
        description = { "501:1519200307:581425448", "เอกสารที่เจ้ากู้จากคาราวานระบุว่าเวนเจอร์โควางแผนไว้หลายทางเพื่อขับเราออกจากที่ดิน จะได้ปล้นทรัพยากรของเราได้ตามใจ\n\nข้าทั้งขยะแขยงและตกใจที่พวกมันยอมทำเรื่องต่ำช้าได้ถึงเพียงนั้น ข้าต้องการให้กำจัดผู้บงการ ชื่อ Supervisor Fizsprocket เจ้าจะพบเขาที่เหมืองเวนเจอร์โคทางตะวันออกของซากคาราวาน เอากระดานหนีบเอกสารของเขามาให้ข้า เราจะดูว่ามีอะไรใช้ได้บ้าง" },
        progress = { "127:1977432105:1050311519", "ข้าเดือดดาลทุกครั้งที่คิดถึงเรื่องเลวร้ายที่เวนเจอร์โคยอมทำกับเราเพื่อกำไร" },
        completion = { "249:937653689:1237710104 N 1:46:46", "พอได้ข่าวว่าเจ้าวายร้ายฟิซสปร็อกเก็ตตายแล้ว ข้าก็คลายโกรธลงบ้าง ข้าจะค้นของส่วนตัวของเขา เผื่อมีเบาะแสเพิ่มว่าเวนเจอร์โควางแผนอะไรต่อ ขอบใจที่ช่วย {name}" },
        required = { [4819] = { "23:2108068979:582768908", "กระดานหนีบเอกสารของ Fizsprocket" } },
        steps = { { "23:2108068979:582768908", "กระดานหนีบเอกสารของ Fizsprocket" } },
    },
    [766] = { -- Mazzranache
        title = { "11:1156901088:791564818", "มาซรานาช" },
        objective = { "128:762982568:2049338899", "นำ Prairie Wolf Heart, Flatland Cougar Femur, Plainstrider Scale และ Swoop Gizzard ไปให้ Maur Raincaller ที่ Bloodhoof Village" },
        description = { "504:313501382:1830546459", "ปู่ข้าเล่าเรื่องที่เคยสู้กับสไตรเดอร์ชื่อมาซรานาชให้ฟัง มันมีตาแดงดุจปีศาจ กรงเล็บคมกริบ และเขี้ยวมีพิษ\n\nบังเอิญข้าเจอมันตอนเดินข้ามที่ราบ ถูกมันกัดไหล่เป็นแผลฉกรรจ์ มันร้ายอย่างที่ปู่เล่าจริง ๆ ข้าต้องใช้ชิ้นส่วนสัตว์ที่หายากมารักษาแผลติดเชื้อ หัวใจหมาป่า กระดูกต้นขาคูการ์ เกล็ดเพลนสไตรเดอร์ และกระเพาะบดของสวูป\n\nรีบเถิด เวลาเหลือน้อยแล้ว" },
        progress = { "295:1256281630:1368039805", "ไข้ข้าหนักขึ้นจนเริ่มเพ้อเหมือนฝันร้าย... ข้าน่าจะรู้ว่าตัวเองรับมือสัตว์ที่แม้แต่ปู่ยังเอาชนะไม่ได้ไม่ไหว...\n\nเจ้าได้ส่วนผสมของยามาหรือยัง? ข้ากลัวว่าหากไม่รีบรักษาแผลติดเชื้อ ข้าคงตาย" },
        completion = { "15:77186111:238310768 N 321:2081616540:2098193000", "อา ขอบใจ {name} ของที่เจ้านำมาจะช่วยให้ข้าปรุงยาหยุดแผลติดเชื้อไม่ให้ลาม แล้วในที่สุดก็รักษาให้หายขาดได้ ข้าติดหนี้ชีวิตเจ้า\n\nแต่ข้าคงไม่มีวันลืมเสียงร้องแหลมตอนมาซรานาชเข้าจู่โจม หรือสีสันวูบวาบตอนจะงอยปากมันจิกลงมา...\n\nเดินทางระวังตัวด้วย" },
        required = { [4804] = { "18:1545539842:1061266434", "หัวใจหมาป่าทุ่งหญ้า" }, [4805] = { "21:921877967:1018642354", "กระดูกต้นขาพูมาที่ราบ" }, [4806] = { "18:463923419:181702826", "เกล็ด Plainstrider" }, [4807] = { "13:839376184:1040030178", "กระเพาะบดของ Swoop" } },
        steps = { { "18:1545539842:1061266434", "หัวใจหมาป่าทุ่งหญ้า" }, { "21:921877967:1018642354", "กระดูกต้นขาพูมาที่ราบ" }, { "18:463923419:181702826", "เกล็ด Plainstrider" }, { "13:839376184:1040030178", "กระเพาะบดของ Swoop" } },
    },
    [767] = { -- Rite of Vision
        title = { "14:1231573692:1017034459", "พิธีนิมิต" },
        objective = { "50:553399967:1558830019", "คุยกับ Zarlman Two-Moons ที่ Bloodhoof Village" },
        description = { "325:25949876:2097189180", "พิธีนิมิตเป็นหนึ่งในพิธีแห่งพระแม่ธรณี จะนำทางให้เจ้าได้รับความเคารพจากผู้อาวุโสแห่งธันเดอร์บลัฟฟ์\n\nคนของเราเรียนรู้ว่าผืนดินคือผู้หล่อเลี้ยงอันศักดิ์สิทธิ์ที่สุด หากจะเข้าพิธีรับนิมิต เจ้าต้องคุยกับซาร์ลแมน ทูมูนส์ ผู้นำทางจิตวิญญาณของหมู่บ้าน" },
        completion = { "36:1186341172:1303564407 C 80:330039006:1783514416", "ข้ารู้สึกอยู่แล้วว่าเจ้าจะมาหา {class} ข้าดูออกเสมอว่าใครกำลังพยายามผ่านพิธีแห่งพระแม่ธรณี" },
    },
    [770] = { -- The Demon Scarred Cloak
        title = { "23:1170904283:1346647", "ผ้าคลุมรอยแผลปีศาจ" },
        objective = { "37:287372682:1066561559", "ตามหาคนที่รู้เรื่อง Ghost Howl" },
        description = { "194:1684552212:395158102", "หนังขาดวิ่นของโกสต์ฮาวล์ยังมีรอยแผลฉกรรจ์จากครั้งที่หมาป่าตัวนี้สู้กับเบิร์นนิงลีเจียน\n\nบางทีคนในหมู่บ้านบลัดฮูฟอาจควรรู้ว่าโกสต์ฮาวล์ตายแล้ว..." },
        completion = { "114:255770034:719683892 C 270:1667010574:705891798", "ข้าแทบไม่เชื่อสายตาตัวเอง! เจ้าโค่นโกสต์ฮาวล์ หมาป่าผู้ยิ่งใหญ่ได้หรือ? ข้าต้องมองเจ้าด้วยความนับถือใหม่แล้ว {class} รุ่นเยาว์ เจ้าเป็นนักล่าฝีมือยอดเยี่ยม!\n\nข้าอยากมอบของให้เจ้าสักอย่าง วันคืนแห่งการล่าของข้าจบลงแล้ว แต่จะเป็นเกียรติหากเจ้าใช้อาวุธของข้าสักชิ้นไปล่า\n\nขอให้มันโจมตีเข้าเป้าและนำชื่อเสียงมาให้เจ้า\n\nและหวังว่าวิญญาณโกสต์ฮาวล์จะพบความสงบในที่สุด" },
    },
    [771] = { -- Rite of Vision
        title = { "14:1231573692:1017034459", "พิธีนิมิต" },
        objective = { "100:1011555523:282552161", "เก็บ Well Stone 2 ก้อนและ Ambercorn 2 เมล็ด แล้วนำกลับไปให้ Zarlman Two-Moons ที่ Bloodhoof Village" },
        description = { "478:846365706:2094157176", "เพื่อผ่านพิธีนิมิต เจ้าต้องเก็บวัตถุดิบมาทำ Water of the Seers\n\nข้าต้องใช้หินจากรอบบ่อน้ำในมัลกอร์ ผสมกับแอมเบอร์คอร์นที่ร่วงอยู่ใต้ต้นไม้ใหญ่ในดินแดนเรา\n\nวัตถุดิบเหล่านี้มีพลังเวท เมื่อนำมาต้มและดื่มต่อหน้ากองไฟประจำเผ่า เจ้าจะเห็นนิมิต จงตามไป แล้วนิมิตจะพาเจ้าไปสู่ขั้นต่อไปของภารกิจศักดิ์สิทธิ์นี้" },
        progress = { "154:1987480072:1372122322", "เมื่อเจ้ารวบรวมหินรอบบ่อน้ำกับแอมเบอร์คอร์นใต้ต้นไม้ได้พอ ข้าจะเตรียม Water of the Seers ให้" },
        completion = { "55:672946019:1725351777 N 66:583902707:1160946427", "ข้าเห็นแล้วว่าเจ้าเรียนรู้วิธีเก็บสิ่งที่ผืนดินศักดิ์สิทธิ์มอบให้ {name} ข้าจะต้ม Water of the Seers ให้ในอีกครู่เดียว" },
        required = { [4808] = { "10:2047887964:387651115", "หินจากบ่อน้ำ" }, [4809] = { "9:20222889:1023958827", "เมล็ดแอมเบอร์คอร์น" } },
        steps = { { "10:2047887964:387651115", "หินจากบ่อน้ำ" }, { "9:20222889:1023958827", "เมล็ดแอมเบอร์คอร์น" } },
    },
    [772] = { -- Rite of Vision
        title = { "14:1231573692:1017034459", "พิธีนิมิต" },
        objective = { "118:755791613:1332533691", "ดื่ม Water of the Seers หน้ากองไฟประจำเผ่าที่ Bloodhoof Village แล้วตามนิมิตไปเมื่อปรากฏ" },
        description = { "286:2078851849:1200139482", "บัดนี้ข้าขอมอบ Water of the Seers ให้เจ้า\n\nเมื่อพร้อมแล้ว ให้ดื่มน้ำใกล้กองไฟประจำเผ่า หลังดื่มน้ำศักดิ์สิทธิ์ รอสักครู่แล้วนิมิตจะปรากฏหน้ากองไฟ\n\nจากนั้นเจ้าต้องตามนิมิตไปสู่ชะตาของเจ้าเอง..." },
        completion = { "15:878501725:346293967 N 50:369634800:157855537", "อย่ากลัวเลย {name} เจ้าผ่านพิธีนิมิตแล้ว" },
        required = { [4823] = { "18:70848846:2129229254", "น้ำแห่งผู้หยั่งรู้" } },
        steps = { { "18:70848846:2129229254", "น้ำแห่งผู้หยั่งรู้" } },
    },
    [773] = { -- Rite of Wisdom
        title = { "14:1399672769:941732982", "พิธีปัญญา" },
        objective = { "78:790974632:114776732", "เดินทางไป Red Rocks ทางตะวันออกของ Thunder Bluff แล้วคุยกับ Ancestral Spirit" },
        description = { "374:29087249:279358225 N 1:46:46", "หากจะให้ผู้อาวุโสแห่งธันเดอร์บลัฟฟ์ยอมรับ เจ้าต้องผ่านพิธีปัญญาเป็นขั้นต่อไป\n\nเมื่อผ่านพิธีนิมิตแล้ว ดวงวิญญาณที่เรดร็อกส์จะมอบพรจากบรรพชนให้เจ้า ผู้ที่ดื่ม Water of Seers แล้วเท่านั้นจึงจะได้รับพรนี้\n\nมุ่งไปทางตะวันออกของธันเดอร์บลัฟฟ์ ไปยังเรดร็อกส์แล้วตามหาดวงวิญญาณบรรพชน {name}" },
        completion = { "86:956419909:1024636348 N 237:1882540419:1464077627 C 33:634547767:1507196705", "เจ้าพากเพียรอย่างยิ่งเพื่อผ่านพิธีแห่งพระแม่ธรณี {name}\n\nพวกเราดวงวิญญาณบรรพชนเป็นตัวแทนของทอเรนผู้กล้าที่สละชีวิตอย่างกล้าหาญเพื่อก่อตั้งและปกป้องธันเดอร์บลัฟฟ์ เมืองอันยิ่งใหญ่ของเรา บัดนี้ข้าขอส่งต่อหน้าที่ปกป้องเมืองให้เจ้า\n\nเจ้าผ่านพิธีปัญญาแล้ว {class} รุ่นเยาว์ จงเข้าสู่ธันเดอร์บลัฟฟ์อย่างภาคภูมิ" },
    },
    [775] = { -- Journey into Thunder Bluff
        title = { "26:1702880295:173859105", "เดินทางสู่ธันเดอร์บลัฟฟ์" },
        objective = { "45:2086086906:1316212187", "คุยกับ Cairne Bloodhoof ที่ Thunder Bluff" },
        description = { "51:1427988858:1522630883 R 186:919108721:1449759535", "บัดนี้เจ้าจะได้รับความเคารพในเมืองอันยิ่งใหญ่ของเรา {race} ผู้คู่ควรและผ่านพิธีแห่งพระแม่ธรณีย่อมได้รับเกียรตินี้\n\nภารกิจสุดท้ายคือไปพบแคร์น บลัดฮูฟ ผู้นำผู้สูงส่งของเรา เขาอาศัยอยู่บนยอดที่ราบสูงลูกที่สูงที่สุดในธันเดอร์บลัฟฟ์" },
        completion = { "12:261722808:917055563 C 42:1094334221:391111907", "สวัสดี {class} รุ่นเยาว์ ดูสิ เจ้าเดินทางมาถึงประตูบ้านข้าจนได้" },
    },
    [776] = { -- Rites of the Earthmother
        title = { "24:895749709:360748221", "พิธีแห่งพระแม่ธรณี" },
        objective = { "79:1482822225:1208431229", "Cairne Bloodhoof ที่ Thunder Bluff ต้องการให้เจ้านำ Horn of Arra'chea มาให้เขา" },
        description = { "226:862267875:739475543 N 157:1961318258:1397903080", "เจ้าผ่านพิธีแห่งพระแม่ธรณีและได้ที่ทางในธันเดอร์บลัฟฟ์แล้ว\n\nแต่หากอยากรักษาสิ่งที่พากเพียรจนได้มา เจ้าต้องพิสูจน์คุณค่าของตนต่อพวกพ้องต่อไป\n\nพวกเราเป็นนักล่า {name} ที่มัลกอร์เบื้องล่างมีโคโดทรงพลังชื่ออาร์ราเชอา แสดงฝีมือตามรอยและล่าให้ข้าเห็นด้วยการนำ Horn of Arra'chea มาให้ข้า" },
        progress = { "36:1622661261:1224354444", "เจ้าตามรอยอาร์ราเชอาเจอหรือยัง?" },
        completion = { "168:951504883:2038034672 N 1:46:46", "ทำได้ดี! เป็นการล่าที่ยอดเยี่ยม\n\nข้าจะส่งคนไปเก็บซาก จะได้ใช้หนังกับเนื้อของมัน\n\nเจ้าทำสิ่งยิ่งใหญ่ให้พวกพ้อง {name}" },
        required = { [4841] = { "17:175827255:1352128145", "เขาของ Arra'chea" } },
        objectiveLabels = {
