    [833] = { -- A Sacred Burial
        title = { "15:313973596:1406044007", "สุสานศักดิ์สิทธิ์" },
        objective = { "78:1732160864:487825417", "Lorekeeper Raintotem ต้องการให้เจ้าสังหาร Bristleback Interloper 8 ตัวที่ Red Rocks" },
        description = { "484:104441695:1475040309 N 1:46:46", "มีเพียงทอเรนผู้กล้าที่สุดเท่านั้นที่ได้พัก ณ เรดร็อกส์ สุสานศักดิ์สิทธิ์ของเรา เป็นเกียรติที่มอบแก่นักรบผู้ยิ่งใหญ่ที่ช่วยก่อตั้งและปกป้องธันเดอร์บลัฟฟ์ และผู้ที่สละชีวิตเพื่อประโยชน์ส่วนรวมของเผ่ากับหัวหน้าเผ่า\n\nแต่ดูเหมือนภัยชั่วร้ายจะบุกเข้าดินแดนศักดิ์สิทธิ์ พวกบริสเซิลแบ็กผู้บุกรุกกำลังทำลายสุสาน ข้าแก่และพ้นวัยที่จะขับไล่พวกมันแล้ว\n\nต้องใช้กำลังขับพวกมันออกไป {name}" },
        progress = { "79:526513378:65930713 N 1:46:46", "ต้องขับพวกบริสเซิลแบ็กผู้บุกรุกออกจากสุสานศักดิ์สิทธิ์ของเรา {name}" },
        completion = { "140:1754047352:1273710079", "ทำได้ดี เจ้าส่งสารชัดเจนให้พวกบริสเซิลแบ็กชั่ว พวกมันคงคิดให้ดีก่อนกลับมาก่อกวนที่ศักดิ์สิทธิ์นี้" },
        objectiveLabels = {
            monster = { ["Bristleback Interloper slain"] = "ปราบ ผู้บุกรุก Bristleback" },
        },
    },
    [76156] = { -- Stalk With The Earthmother
        title = { "26:514266621:1156669393", "ย่องตามทางพระแม่ธรณี" },
        objective = { "191:1026002506:1983536320", "ลอบเข้าเหมือง Venture Company ทางตะวันออกเฉียงใต้ของ Thunder Bluff เก็บ Seaforium Mining Charge 5 ชิ้นจากรถเข็นอุปกรณ์ระเบิด แล้วนำกลับไปให้ Boarton Shadetotem ที่ Thunder Bluff" },
        description = { "52:1432612556:549194062 C 285:166742:939733166", "ข้าสัมผัสได้ว่าเจ้ามีพรสวรรค์ด้านงานลับ {class} ใช้หน้ากากนี้ลอบเข้าเหมืองเวนเจอร์คอมพานีใกล้ ๆ แล้วขโมยเสบียงมา การปลอมตัวอาจดูไม่น่าเชื่อนัก แต่โจรฝีมือดีผ่านยามได้ด้วยรอยยิ้มกับกลลวงให้ไขว้เขว ข้าเชื่อว่าเจ้าก็ทำได้" },
        completion = { "47:2132958122:246122908", "อืม... ดูท่าการปลอมตัวจะไม่ใช่ทางถนัดของเจ้า", variants = { { "47:15371403:1688136323", "อืม... ดูท่าการปลอมตัวจะไม่ใช่ทางถนัดของเจ้า" } } },
        progress = { "43:567391369:2024490207 C 62:48595397:717529911", "เจ้าคงต้องฝึกพรางตัวอีกหน่อยนะ {class} ข้าได้ยินเสียงเจ้ามาตั้งแต่ก้าวขึ้นที่ราบยอดเขาแล้ว" },
        required = { [206157] = { "23:1084005738:1496788427", "ระเบิดขุดแร่ Seaforium" }, [206159] = { "19:1119171707:1884171067", "ชุดปลอมตัวเป็นพนักงานบริษัท Venture" } },
        steps = { { "23:1084005738:1496788427", "ระเบิดขุดแร่ Seaforium" }, { "19:1119171707:1884171067", "ชุดปลอมตัวเป็นพนักงานบริษัท Venture" } },
    },
    [76160] = { -- Stalk With The Earthmother
        title = { "26:514266621:1156669393", "ย่องตามทางพระแม่ธรณี" },
        objective = { "152:1374241672:2087590460", "เก็บ Windfury Cone 8 ลูกทางเหนือของ Thunder Bluff ใช้ Mortar and Pestle บด แล้วนำสิ่งที่ได้กลับไปให้ Boarton Shadetotem ที่ Thunder Bluff" },
        description = { "320:1465299862:816809337", "บางทีเจ้าอาจถนัดเรื่องพิษมากกว่าการปลอมตัว ฮาร์ปีทางเหนือทำรังบนต้นไม้ที่ให้ยางพิษร้ายแรง เก็บลูกสนที่ร่วงรอบรัง แล้วบดให้เป็นยาทา เมื่อป้ายลงบนใบมีด ยานี้จะเผาแผลของศัตรูให้ลึกเข้าเนื้อและทำให้เลือดกลายเป็นเกลือ" },
        completion = { "278:1665586115:1398224130", "นี่ไม่ใช่ยาพิษสำหรับทาที่ข้าขอ สิ่งที่เจ้าเอามาให้ข้าคือเนยเมล็ดสน แน่ใจหรือว่าทำตามที่ข้าบอก?\n\nเอาไปทาขนมปังเครื่องเทศยังจะเข้าท่ากว่าทาคมกริช เว้นแต่ศัตรูของเจ้าจะแพ้ถั่ว แบบนั้นเจ้าคงรับมือได้สบาย", variants = { { "C 280:1825937126:1719179608", "{class} นี่ไม่ใช่ยาพิษสำหรับทาที่ข้าขอ สิ่งที่เจ้าเอามาให้ข้าคือเนยเมล็ดสน แน่ใจหรือว่าทำตามที่ข้าบอก?\n\nเอาไปทาขนมปังเครื่องเทศยังจะเข้าท่ากว่าทาคมกริช เว้นแต่ศัตรูของเจ้าจะแพ้ถั่ว แบบนั้นเจ้าคงรับมือได้สบาย" } } },
        progress = { "49:1125264571:537024374 C 43:805026792:881880979", "ทำยาทาเสร็จแล้วก็ระวังให้ดีนะ {class} แค่โดนผิวหนังก็อาจเจ็บแสบเอาการ" },
        required = { [206175] = { "10:2086244953:235542484", "ขี้ผึ้งทาจากต้นสน" } },
        steps = { { "10:2086244953:235542484", "ขี้ผึ้งทาจากต้นสน" } },
    },
    [76240] = { -- Stalk With The Earthmother
        title = { "26:514266621:1156669393", "ย่องตามทางพระแม่ธรณี" },
        objective = { "124:2079292231:557045213", "ซื้อหรือตก Raw Brilliant Smallfish แล้วใช้ Knife Set แล่ปลาต่อหน้า Boarton Shadetotem ที่ Thunder Bluff" },
        description = { "311:1841847035:1937049125", "ข้ามีความคิดสุดท้ายที่อาจช่วยให้เราสำเร็จ ข้ายังรู้สึกว่าเจ้ามีพรสวรรค์ซ่อนอยู่ ลองดึงออกมาด้วยวิธีที่อ้อมขึ้นอีกหน่อยเถิด\n\nไปหา Raw Brilliant Smallfish แล้วเอากลับมาที่นี่ ใช้กริชพวกนี้ทำความสะอาดแล้วแล่ปลา อย่าคิดให้หนัก ทำไปตามธรรมชาติของเจ้า" },
        progress = { "29:1641490094:1833668358", "เจ้ามีอะไรมาให้ข้าหรือ?" },
        completion = { "26:2123133837:823939337 C 232:1421929154:756899926 C 38:1236151487:130128757", "ทำได้ดีทีเดียว {class} ถึงจะไม่แม่นยำแบบโจรอย่างที่ข้าหวัง แต่เจ้าใช้มือได้คล่องทั้งสองข้างอย่างน่าทึ่ง\n\nตอนนี้ข้าเข้าใจแล้วว่าเจ้าคงไม่ใช่ผู้ที่จะฝึกคนของข้าในศาสตร์แห่งการลอบเร้น แต่มีอยู่อย่างหนึ่งที่ข้าสอนเจ้าได้ ขอให้เดินทางโดยสวัสดิภาพ {class} ฝ่ายฮอร์ดต้องการวีรชนอย่างเจ้า", variants = { { "26:2123133837:823939337 C 212:553473141:589677166 C 38:1236151487:130128757", "ทำได้ไม่เบาเลย {class} น่าเสียดายที่ยังไม่เฉียบคมแบบนักลอบเร้นอย่างที่ข้าหวังไว้\n\nตอนนี้ข้าเห็นแล้วว่าเจ้าคงไม่ใช่ผู้สืบทอดวิชาลอบเร้นของข้า แต่รับนี่ไว้เป็นของฝากก่อนจากกันเถอะ ขอให้เดินทางโดยสวัสดิภาพ {class} ฝ่ายฮอร์ดต้องการวีรชนอย่างเจ้า" } } },
        required = { [206345] = { "11:288414792:1665581637", "เนื้อปลาหั่นชิ้น" } },
        steps = { { "11:288414792:1665581637", "เนื้อปลาหั่นชิ้น" } },
    },
    [95805] = { -- Grace of An'she and Mu'sha
        title = { "26:1494322246:666776046", "พรแห่งอันเชกับมูชา" },
        objective = { "137:1617433367:2123866161", "นำ Smoldering Incense ไปยังศาลของ An'she และ Mu'sha บนเนินทางตะวันออกเฉียงใต้ ก่อนเครื่องหอมจะไหม้เป็นเถ้าในสิบนาที!" },
        description = { "478:2002686248:691730464", "ดวงอาทิตย์และดวงจันทร์ อันเชกับมูชา เป็นคนละส่วนกับธาตุในโลกของเรา แต่แสงของทั้งสองมอบชีวิต หนทาง และความหวังให้เรา\n\nเราเคารพเหล่าวิญญาณของโลก จึงเคารพเทพฝาแฝดทั้งสองด้วย\n\nหากอยากแสดงความเคารพ จงนำเครื่องหอมที่คุกรุ่นนี้ไปยังศาลบนเนินทางตะวันออกเฉียงใต้ ตรงจุดที่มองเห็นที่ราบสูง ทางใต้ของพวกควิลบอร์ รีบไปให้ถึงศาลก่อนเครื่องหอมไหม้หมด\n\nอย่าให้เปียกน้ำล่ะ!" },
        completion = { "140:1978909945:390481383", "เมื่อเจ้าเทเครื่องหอมลงในไฟ กลิ่นหอมก็ลอยอบอวลรอบกาย เหลือเพียงถุงเปล่าและความอิ่มใจบางเบา", variants = { { "142:574155688:1022394869", "<เมื่อเจ้าเทเครื่องหอมลงในไฟ กลิ่นหอมก็ลอยอบอวลรอบกาย เหลือเพียงถุงเปล่าและความอิ่มใจบางเบา>" } } },
        progress = { "50:46146416:546371520", "<ควันจากเครื่องหอมลอยขึ้นสู่ท้องฟ้า>" },
        required = { [277199] = { "27:129348279:813447003", "ถุงเครื่องหอมที่ยังคุกรุ่น" } },
        steps = { { "27:129348279:813447003", "ถุงเครื่องหอมที่ยังคุกรุ่น" } },
    },
    [96130] = { -- Chakuyak
        title = { "8:1380994690:1929751823", "ชาคูยัก" },
        objective = { "40:206189894:1212426577", "ปราบ Chakuyak แล้วนำหนังของมันกลับมา" },
        description = { "470:879108994:488188835", "ในหมู่หมาป่าทุ่งที่ล่าเหยื่อแถวเนินใกล้ ๆ มีตัวเมียตัวหนึ่งดุร้ายเป็นพิเศษ เราเรียกมันว่าชาคูยัก มันกลายเป็นภัยต่อนักเดินทางจากต่างถิ่น\n\nมันย่องล่าอยู่ในแนวไม้ทางตะวันตกของทะเลสาบสโตนบูล เคลื่อนจากดงหนึ่งไปอีกดง\n\nกำจัดภัยนี้แล้วเอาหนังของมันมาให้ข้า ข้าจะกล่าวชมเจ้ากับหัวหน้าเผ่า ระวังด้วย มันอันตราย! เจ้าอาจพบพรานคนอื่นกำลังตามล่ามันอยู่ ลองร่วมมือกันก็ได้" },
        progress = { { "30:285348056:1517407183", "23:1497491231:1033148216 N 1:63:63", "23:1497491231:1033148216 C 1:63:63", "23:1497491231:1033148216 R 1:63:63" }, "เจอเจ้าเพื่อนตัวโตหรือยัง?", variants = { { "28:920933724:1716538189", "เจ้าพบหมาป่าตัวโตหรือยัง?" } } },
        completion = { "178:2077920656:1165146804", "การพรากชีวิตสัตว์งดงามเช่นนี้เป็นเรื่องเศร้า แต่จำเป็นต่อความปลอดภัยของพวกเรา ข้าจะดูให้แน่ว่าหนังของมันไม่สูญเปล่า ขอบใจ" },
        required = { [270302] = { "15:874976533:175896088", "หนังของ Chakuyak" } },
        steps = { { "15:874976533:175896088", "หนังของ Chakuyak" } },
    },
    [96241] = { -- Talkin' bout Toxins, Mon
        title = { "24:421634026:132002358", "มาคุยเรื่องพิษกัน สหาย" },
        objective = { "97:755843382:1645641331", "ใช้ Toxin Extractor เก็บ Gloomrise Toxin Sample 5 ตัวอย่างจาก Gnawed Corpse ที่ Gloomrise", amount = { "34:1831389801:233592481 W1 62:1647247284:1757264401", "ใช้ Toxin Extractor เก็บ Gloomrise Toxin Sample {world1} ตัวอย่างจาก Gnawed Corpse ที่ Gloomrise" } },
        description = { "374:2036166589:60890521", "มีเรื่องประหลาดเกิดขึ้นที่กลูมไรส์ เจ้ามาซูคอนคนนี้ได้ยินมาว่ามีสัตว์ใหม่หน้าตาน่าเกลียดวิ่งยั้วเยี้ยอยู่แถวนั้น\n\nมีคนว่าพิษของเจ้าตัวพวกนั้นมีคุณสมบัติแปลก ๆ ข้าเลยชักอยากรู้ เอาเครื่องสกัดของข้าไป ใช้กับซากที่นอนเกลื่อนแถวนั้นเพื่อเก็บพิษมา ทำให้ข้าที แล้วข้าจะติดหนี้เจ้า สหาย" },
        progress = { "23:303574326:1110213985", "เจ้าได้ของที่ข้าต้องการหรือยัง?" },
        completion = { "131:384827186:280400784 C 25:1611175265:749746892", "หึ... ตอนข้าบอกว่าพิษมีคุณสมบัติแปลก ๆ ข้าไม่ได้ล้อเล่นนะ สหาย เจ้ายังดูสบายดีอยู่ งั้นก็ไม่มีปัญหา\n\nขอบใจที่ช่วย {class} ข้าซาบซึ้งมาก" },
        required = { [273001] = { "22:54540075:1222780309", "ตัวอย่างสารพิษ Gloomrise" }, [273015] = { "15:71673688:828815581", "เครื่องสกัดสารพิษ" } },
        steps = { { "22:54540075:1222780309", "ตัวอย่างสารพิษ Gloomrise" }, { "15:71673688:828815581", "เครื่องสกัดสารพิษ" } },
    },
    [96259] = { -- Defending the Dead
        title = { "18:1524469644:147528961", "คุ้มครองผู้ล่วงลับ" },
        objective = { "54:417634946:1658337326", "สังหาร Gloomrise Hatchling 10 ตัวและ Gloomrise Soldier 5 ตัว", amount = { "5:409775429:850574908 W1 26:1380432634:927641958 W2 20:662828275:1409031282", "สังหาร Gloomrise Hatchling {world1} ตัวและ Gloomrise Soldier {world2} ตัว" } },
        description = { "469:1729837855:1305647706", "ที่กลูมไรส์ทางตะวันตกเฉียงเหนือของค่ายนี้เป็นสุสานโบราณของทอเรน ช่วงหลังมีฝูงแมงมุมดุร้ายผิดปกติเข้ามายึด พวกมันเป็นภัยต่อชาวมัลกอร์และยังทำลายสถานที่ที่ทอเรนส่วนใหญ่ถือว่าศักดิ์สิทธิ์\n\nหากเจ้าไปกลูมไรส์แล้วกำจัดฝูงแมงมุมได้ จะเป็นคุณแก่พวกเรามาก บรรพชนคงยิ้มให้เจ้าแน่หากทำสำเร็จ" },
        completion = { "216:1187522912:2029797478", "ขอบใจที่ช่วยผู้คนบนผืนดินนี้ เราอาจต้องใช้เวลากว่าจะกำจัดฝูงแมงมุมหมด แต่สิ่งที่เจ้าทำช่วยให้เราตั้งหลักได้มั่นคงพอจะรับมือสัตว์ชั่วร้ายเหล่านี้" },
        objectiveLabels = {
            monster = { ["Gloomrise Hatchling slain"] = "ปราบ ลูกแมงมุม Gloomrise", ["Gloomrise Soldier slain"] = "ปราบ แมงมุมทหาร Gloomrise" },
        },
    },
    [96260] = { -- Stronger than Steel
        title = { "19:562884740:1242278874", "แกร่งกว่าเหล็กกล้า" },
        objective = { "61:1852480184:1931259371", "เก็บ Crystalline Silk 3 เส้นจาก Gloomrise Spinner", amount = { "7:451016854:1830523975 W1 53:714685058:1807286402", "เก็บ Crystalline Silk {world1} เส้นจาก Gloomrise Spinner" } },
        description = { "481:260565608:1407743002", "เจ้าได้ข่าวเรื่องที่เกิดกับสุสานกลูมไรส์หรือยัง? แมงมุมยักษ์ที่ลือกันว่ามีพิษแรงจนปลุกคนตายได้แพร่ไปเร็วเหมือนไฟลาม เรื่องน่าขนลุกทีเดียว\n\nหน่วยสอดแนมคนหนึ่งที่ถูกส่งไปสืบกลับมาในสภาพเกือบตาย ตัวเต็มไปด้วยใยแมงมุมผลึกที่เหนียวอย่างเหลือเชื่อ ข้าเก็บมาเท่าที่ทำได้ แต่ถ้าได้ตัวอย่างเพิ่มจะช่วยให้ศึกษาต่อได้มาก\n\nนำใยผลึกมาให้ข้าอีก แล้วข้าจะให้รางวัล" },
        progress = { "162:1204107502:1739425523", "คุณสมบัติพิเศษของใยนี้น่าจะใช้ทอผ้าที่เบา ทนทาน และป้องกันอันตรายได้ดี ข้าอยากได้มาทดลองอีก" },
        completion = { "290:1608314790:882004625 C 1:46:46", "ตัวอย่างชั้นเยี่ยม พอสำหรับงานของข้าเหลือเฟือ\n\nนี่ เอาไปเถิด ข้าทอใยที่มีอยู่เล็กน้อยจนทำเป็นผ้าคลุมที่มีลักษณะเฉพาะได้ หวังว่าเจ้าจะใช้ประโยชน์จากมันได้ระหว่างเดินทาง\n\nขอให้พระแม่ธรณีคุ้มครองเจ้า {class}" },
        required = { [273181] = { "16:850763477:571751507", "ใยไหมผลึก" } },
        steps = { { "16:850763477:571751507", "ใยไหมผลึก" } },
    },
    [96261] = { -- The Broodmother
        title = { "15:546700942:1394663230", "แม่ฝูง" },
        objective = { "38:2042500176:1750769955", "สังหาร Broodmother Valraxx ที่ Gloomrise" },
        description = { "443:325356259:184232561", "เวลามีฝูงแมงมุมระบาดอย่างที่กลูมไรส์ มักมีแม่ฝูงทรงพลังตัวเดียวอยู่เบื้องหลังการเพิ่มจำนวนอย่างรวดเร็ว\n\nหากอยากขับพวกมันไปให้พ้นเสียที เราต้องหาตัวต้นตอแล้วกำจัดมัน เมื่อไปถึงกลูมไรส์ ให้ตามหาและทำลายแม่ฝูงเสีย ข้าแนะนำให้พาพวกไปด้วยและเตรียมรับมือทุกอย่าง ดูเหมือนพวกนี้จะไม่ใช่แมงมุมธรรมดา" },
        completion = { "195:881436595:853250628 N 73:113760541:629486055", "คนตายฟื้นขึ้นมาอีกหรือ? แม่ฝูงอยู่ในร่างไนต์เอลฟ์งั้นหรือ? เป็นเรื่องที่ได้รู้แล้วน่าหนักใจ ชวนให้สงสัยว่าทั้งหมดหมายถึงอะไร... ข้าเกรงว่าคงต้องเก็บไว้คิดคราวหน้า\n\nขอบใจ {name} เจ้าช่วย Earthen Ring และชาวมัลกอร์ไว้มาก" },
        objectiveLabels = {
            monster = { ["Broodmother Valraxx slain"] = "ปราบ แม่พันธุ์ Valraxx" },
        },
    },
    [96294] = { -- A Darker Truth
        title = { "14:2116943031:205727338", "ความจริงที่มืดมนยิ่งกว่า" },
        objective = { "96:384608506:331609503", "นำจดหมายที่เก็บจาก Broodmother Valraxx ไปให้ Muln Earthfury ที่ Skywatcher Plateau" },
        description = { "358:579776278:370339444", "<แม่ฝูงที่เจ้าเพิ่งสังหารแท้จริงคือนักดรูอิดไนต์เอลฟ์ที่แปลงเป็นสัตว์รูปร่างบิดเบี้ยว คำถามมากมายผุดขึ้นในหัวว่าแมงมุมที่กลูมไรส์เป็นอะไรกันแน่ และอยู่ที่นั่นเพื่ออะไร\n\nเจ้าเห็นกระดาษแผ่นหนึ่งโผล่จากรอยพับของเสื้อคลุมเอลฟ์ที่ตายแล้ว เอกสารนี้อาจตอบคำถามในหัวเจ้าได้บ้าง>" },
        progress = { "13:597869732:1707424667", "นี่คืออะไร?" },
        completion = { "419:744881357:462960088", "เรื่องนี้... น่าหนักใจเหลือเกิน ทำไมดรูอิดถึงอยู่เบื้องหลังฝูงแมงมุมอันตราย? “Wild King” กับ “Pact” ที่เอ่ยถึงในจดหมายนี้เป็นใครหรืออะไรกัน?\n\nข้าจะปรึกษาดรูอิดแห่งวงเวทเซนาเรียน พวกเขาอาจรู้มากกว่านี้\n\nขอบใจอีกครั้งที่ช่วยเรา แม้ข้อมูลนี้จะทำให้กังวล เราก็พอจะสบายใจได้เมื่อรู้ว่าผู้ควบคุมสัตว์ชั่วร้ายเหล่านี้ถูกกำจัดแล้ว" },
        required = { [273659] = { "16:2087836245:1898777917", "แผ่นหนังเปื้อนเลือด" } },
        steps = { { "16:2087836245:1898777917", "แผ่นหนังเปื้อนเลือด" } },
    },
    [98424] = { -- Fizsprocket's Notes
        title = { "19:338650110:62588185", "บันทึกของฟิซสปร็อกเก็ต" },
        objective = { "139:863470332:241249059", "รวบรวมหน้าบันทึกที่เหลือของ Supervisor Fizsprocket ใน The Venture Co. Mine แล้วนำไปให้ Morin Cloudstalker ใกล้ Bloodhoof Village" },
        description = { "292:310333181:445875282", "กระดาษเก่าคร่ำคร่าชุดหนึ่งถูกพับเก็บแยกไว้ในกระเป๋าเสื้อด้านในตรงอกของฟิซสปร็อกเก็ต\n\nดูเหมือนในนั้นมีข้อมูลสำคัญที่ใช้เล่นงานเวนเจอร์โคกับกิจการของมันในพื้นที่นี้ได้ ควรหาหน้าอื่นให้ครบกว่านี้ก่อนกลับไปหาโมริน คลาวด์สตอล์กเกอร์" },
        completion = { "132:1867303279:1609425997", "อา นี่เป็นความรู้ที่มีค่ามาก ข้าขอบใจในความพยายามของเจ้า\n\n<Morin พลิกดูบันทึก>\n\nดูเหมือนเราจะรู้แล้วว่าต้องทำอะไรต่อ" },
        progress = { "25:1384059162:1362261962 C 1:63:63", "เจ้าเอาอะไรมาให้ข้าหรือ {class}?" },
        required = { [281035] = { "31:87974360:303769834", "คู่มือควบคุมเครื่องตัดไม้" }, [281036] = { "33:812816025:221147629", "แนวปฏิบัติที่แนะนำสำหรับงานใน Barrens" }, [281037] = { "28:1974245632:1242016384", "หนึ่ง “Gerenzo” แห่ง Stonetalon" } },
        steps = { { "31:87974360:303769834", "คู่มือควบคุมเครื่องตัดไม้" }, { "33:812816025:221147629", "แนวปฏิบัติที่แนะนำสำหรับงานใน Barrens" }, { "28:1974245632:1242016384", "หนึ่ง “Gerenzo” แห่ง Stonetalon" } },
    },
    [98427] = { -- Ceasing Operations
        title = { "18:2030756279:353297835", "ยุติการดำเนินงาน" },
        objective = { "74:859117081:1277350597", "นำ Clearcutter Key ไปให้ Morin Cloudstalker นอก Bloodhoof Village" },
        description = { "351:1037210714:690500234 N 118:1763711440:114604941", "เครื่องตัดไม้ที่หน้าบันทึกหนึ่งกล่าวถึง... ข้าเคยเห็นระหว่างเดินทาง มันกวาดป่าได้ในเวลาเพียงเศษเสี้ยวของการใช้แรงคนกับขวาน\n\nลานป่าทั้งลานที่เป็นบ้านของลูกหลานพระแม่ธรณีมานับพันปี ถูกลบหายในไม่กี่วัน\n\nเราจะยอมให้เรื่องนี้เกิดขึ้นในบ้านของเรา ห่างเพียงระยะขว้างหินจากที่ที่ลูกหลานเราหัดเดินไม่ได้\n\n{name} ข้าขอให้เจ้ารวมพวกกลับเข้าเหมืองทางตะวันออกเฉียงเหนือ แล้วดูให้แน่ว่าเครื่องนั่นจะโค่นต้นไม้อีกไม่ได้แม้แต่ต้นเดียว", variants = { { "350:884218223:1546115262 N 118:1763711440:114604941", "เครื่องตัดไม้ที่หน้าบันทึกหนึ่งกล่าวถึง... ข้าเคยเห็นระหว่างเดินทาง มันกวาดป่าได้ในเวลาเพียงเศษเสี้ยวของการใช้แรงคนกับขวาน\n\nลานป่าทั้งลานที่เป็นบ้านของลูกหลานพระแม่ธรณีมานับพันปี ถูกลบหายในไม่กี่วัน\n\nเราจะยอมให้เรื่องนี้เกิดขึ้นในบ้านของเรา ห่างเพียงระยะขว้างหินจากที่ที่ลูกหลานเราหัดเดินไม่ได้\n\n{name} ข้าขอให้เจ้ารวมพวกกลับเข้าเหมืองทางตะวันออกเฉียงเหนือ แล้วดูให้แน่ว่าเครื่องนั่นจะโค่นต้นไม้อีกไม่ได้แม้แต่ต้นเดียว" } } },
        completion = { "101:338459028:1883376553", "ทั้งหมู่บ้าน Bloodhoof เป็นหนี้บุญคุณเจ้าในวันนี้ ขอให้พระกรุณาของพระแม่ธรณีอยู่กับเจ้าตลอดไป" },
        progress = { "31:2123996788:583814925 N 1:63:63", "หยุดเครื่องตัดไม้ได้แล้วหรือยัง {name}?" },
        required = { [281048] = { "15:1355454519:1815408565", "กุญแจ Clearcutter" } },
        steps = { { "15:1355454519:1815408565", "กุญแจ Clearcutter" } },
    },
    [98430] = { -- The Longwalkers
        title = { "15:1791261877:1579028506", "เหล่าลองวอล์กเกอร์" },
        objective = { "103:2091294117:2030374460", "ช่วย Perith Stormhoof หนีจาก Palemane Rock แล้วรายงานว่าเขาปลอดภัยให้ Cairne Bloodhoof ที่ Thunder Bluff" },
        description = { "6:1136836709:1914036474 C 476:2094365694:1931923991", "สวัสดี {class} อะไรพาเจ้าลึกเข้ามาในที่มืดและอันตรายเช่นนี้?\n\nมหาหัวหน้าเผ่าแคร์น บลัดฮูฟส่งข้ามาเพื่อช่วยเจรจากับโนลล์ที่มาตั้งถิ่น ส่วนที่เหลือของภารกิจต้องเป็นความลับ เช่นเดียวกับเรื่องอื่นของเหล่าลองวอล์กเกอร์ หน่วยสอดแนมที่หัวหน้าเผ่าไว้วางใจ\n\nเจ้ารู้แค่ว่าพวกมันตอบการเจรจาด้วยความรุนแรงก็พอ หากเจ้าไม่ช่วยให้ข้าหนี ข้ากลัวว่าจะกลายเป็นอาหารมื้อค่ำของพวกโนลล์คืนนี้\n\nเจ้าพอจะช่วยได้ไหม?" },
        completion = { "445:557145999:2013350855", "ข้าโล่งใจที่ Longwalker Stormhoof ปลอดภัย เขาเป็นหน่วยสอดแนมที่ข้าไว้ใจที่สุด และภารกิจของเขาสำคัญอย่างยิ่ง\n\nโปรดรับคำขอบคุณและไมตรีของข้าที่เจ้าเสี่ยงชีวิตเพื่อช่วยเขา เจ้าได้ทำคุณแก่ชนของเรามากกว่าที่เจ้ารู้\n\nระหว่างที่อยู่ที่นี่ ลองเที่ยวชมเมืองใหญ่ของเราดู ที่นี่ปลอดภัยและบนผาสูงมีผู้คนมากมายที่อาจช่วยเจ้าในการเดินทาง\n\nIsh-ne-alo por-ah.", variants = { { "446:4887303:299336780", "ข้าโล่งใจที่ Longwalker Stormhoof ปลอดภัย เขาเป็นหน่วยสอดแนมที่ข้าไว้ใจที่สุด และภารกิจของเขาสำคัญอย่างยิ่ง\n\nโปรดรับคำขอบคุณและไมตรีของข้าที่เจ้าเสี่ยงชีวิตเพื่อช่วยเขา เจ้าได้ทำคุณแก่ชนของเรามากกว่าที่เจ้ารู้\n\nระหว่างที่อยู่ที่นี่ ลองเที่ยวชมเมืองใหญ่ของเราดู ที่นี่ปลอดภัยและบนผาสูงมีผู้คนมากมายที่อาจช่วยเจ้าในการเดินทาง\n\nIsh-ne-alo por-ah." } } },
        objectiveLabels = {
            event = { ["Escort Perith Stormhoof out of Palemane Rock"] = "คุ้มกัน Perith Stormhoof ออกจาก Palemane Rock" },
        },
    },
    [98435] = { -- Thunderhorn's Report
        title = { "20:899650804:198193759", "รายงานของธันเดอร์ฮอร์น" },
        objective = { "75:895498387:1509165947", "นำ Thunderhorn's Report ไปให้ Arch Druid Hamuul Runetotem ที่ Thunder Bluff" },
        description = { "316:1851597074:18554772", "เหล่าผู้อาวุโสในธันเดอร์บลัฟฟ์ต้องได้รู้ว่าเราทำงานคืบหน้าเพียงใดด้วยความช่วยเหลือของเจ้า\n\nโปรดนำสิ่งนี้ไปให้มหาดรูอิดฮามูล รูนโทเทมที่ธันเดอร์บลัฟฟ์ เขาอยู่บนเอลเดอร์ไรส์ ฝั่งตะวันออกของเมือง ต้องขึ้นลิฟต์ไปใจกลางเมือง แล้วข้ามสะพานจึงจะไปถึง" },
        completion = { "321:174687407:1488599426", "อา มิน่าเล่าจึงมีความยินดีไหลไปตามสายน้ำแห่ง Mulgore เจ้าทำคุณใหญ่หลวงในวันนี้ บ่อน้ำหล่อเลี้ยงทั้งคนของเราและสัตว์ป่าที่เราพึ่งพาเป็นอาหาร เครื่องนุ่งห่ม และเพื่อนร่วมทาง\n\nข้ายินดีอย่างยิ่งที่ได้ทำตามคำขอของ Mull โปรดรับสิ่งนี้แทนคำขอบคุณจากข้า" },
        objectiveLabels = {
            event = { ["Cleanse the Wildmane Well"] = "ชำระล้างบ่อน้ำ Wildmane" },
        },
    },
    [99079] = { -- Longwalker Malah
        title = { "16:1443340142:1147801662", "ลองวอล์กเกอร์มาลาห์" },
        objective = { "83:1270844635:2146258171", "ตามหา Longwalker Malah Longwind ทางตะวันออกของ Bloodhoof Village ใกล้ชายเขต Mulgore" },
        description = { "500:212904821:1577197250", "เหล่าลองวอล์กเกอร์คือหน่วยสอดแนมที่พวกเราไว้ใจที่สุด พวกเขาภักดีต่อมหาหัวหน้าเผ่าเพียงผู้เดียว แต่บางครั้งเบนหนุ่มก็ขอแรงพวกเขา\n\nครั้งนี้ก็เช่นกัน มาลาห์ถูกส่งไปใกล้พรมแดนด้านตะวันออก เมื่อคืนครบสามวันแล้วแต่นางยังไม่กลับ เมื่อเกิดเรื่องแบบนี้ เป็นหน้าที่เราที่ต้องตรวจว่าพวกเขาปลอดภัย\n\nข้าต้องคอยดูแลความปลอดภัยของหมู่บ้าน พิสูจน์ตัวเองด้วยการออกตามหามาลาห์ เจ้าจะจำนางได้จากผ้าคาดศีรษะกับไม้เท้าประดับขนที่เป็นเครื่องหมายของลองวอล์กเกอร์" },
        completion = { "90:523218659:2133644302", "เห็นได้ชัดว่า Malah ไม่ได้ตายตามธรรมชาติ ลูกธนูปักอยู่เต็มแผ่นหลังของนางและเกลื่อนพื้นใกล้ ๆ" },
    },
    [99080] = { -- Drive Them Out
        title = { "14:1457887538:833916734", "ขับพวกมันออกไป" },
        objective = { "103:1427056101:1884813340", "สังหาร Galak Centaur 6 ตัวและ Galak Outrunner 4 ตัว แล้วนำหัวของ Herak the Pillager ไปให้ Baine Bloodhoof", amount = { "5:409775429:850574908 W1 17:1503558496:1725260996 W2 79:1771572090:868276995", "สังหาร Galak Centaur {world1} ตัวและ Galak Outrunner {world2} ตัว แล้วนำหัวของ Herak the Pillager ไปให้ Baine Bloodhoof" } },
        description = { "408:59411867:35693265", "ฟังข้าให้ดี เราจะไม่ยกหญ้าแม้แต่ใบเดียวให้เซนทอร์\n\nไปที่ค่ายเดี๋ยวนี้ ก่อนพวกมันได้พักและมีโอกาสควบมาถึงหมู่บ้านเรา กำจัดให้หมด อย่าให้ตัวใดหนีไปแบร์เรนส์เพื่อรวบรวมพวกมาช่วย\n\nหากพบหัวหน้ากลุ่มที่คิดจะมาปล้น เอาหัวมันมาให้ข้า เป็นคำเตือนแก่พวกที่กล้าเหยียบแผ่นดินบรรพชนของเรา" },
        progress = { "17:1221794558:565060598", "จัดการเรียบร้อยแล้วหรือ?" },
        completion = { "339:1426185274:160782156 C 1:46:46", "ตัวเจ้าเปรอะไปด้วยเลือดเซนทอร์ จงจดจำความรู้สึกนี้ไว้ นี่เป็นเกียรติที่ไม่มีสิ่งใดเทียบได้ในหมู่ชนของเรา\n\nข้าได้ยินตอนตัวสุดท้ายล้มลง แล้วเสียงฝีเท้าดังกึกก้องของพวกมันก็เงียบไป ทำได้ดีมาก!\n\nวันนี้เป็นชัยชนะครั้งใหญ่ของหมู่บ้านเรา และช่วยให้ลูกหลานของเราปลอดภัยในยามที่พวกเขาต้องการมากที่สุด ข้าขอบใจเจ้าจากใจจริง {class} รุ่นเยาว์", variants = { { "348:605489292:1486820131 C 1:46:46", "ตัวเจ้าเปรอะไปด้วยเลือดเซนทอร์ จงจดจำความรู้สึกนี้ไว้ นี่เป็นเกียรติที่ไม่มีสิ่งใดเทียบได้ในหมู่ชนของเรา\n\nข้าได้ยินตอนตัวสุดท้ายล้มลง แล้วเสียงฝีเท้าดังกึกก้องของพวกมันก็เงียบไป ทำได้ดีมาก!\n\nวันนี้เป็นชัยชนะครั้งใหญ่ของหมู่บ้านเรา และทำให้ลูกหลานของเรารู้สึกปลอดภัยในยามที่พวกเขาต้องการความอุ่นใจยิ่งกว่าครั้งไหน ข้าขอบใจเจ้าจากใจจริง {class} รุ่นเยาว์" } } },
        required = { [286075] = { "12:654510677:324375964", "ศีรษะของ Herak" } },
        steps = { { "12:654510677:324375964", "ศีรษะของ Herak" } },
        objectiveLabels = {
            monster = { ["Galak Centaur slain"] = "ปราบ เซนทอร์ Galak", ["Galak Outrunner slain"] = "ปราบ หน่วยลาดตระเวน Galak" },
        },
    },
    [99081] = { -- Grim Tidings
        title = { "12:452924324:171753809", "ข่าวร้าย" },
        objective = { "73:1215368291:429958266", "นำ Longwalker Malah's Report ไปให้ Brave Wildrunner ที่ Bloodhoof Village" },
        description = { "333:54653189:1576083301", "มองไปตามทิศที่ลูกธนูบนหลังมาลาห์น่าจะพุ่งมา เจ้าเห็นสิ่งที่ดูเหมือนค่ายเซนทอร์ใหม่ ความเคลื่อนไหวที่นั่นบอกว่ากลุ่มปล้นขนาดเล็กน่าจะเข้ามาในมัลกอร์แล้ว\n\nมือที่ยังกำแน่นของลองวอล์กเกอร์มีรายงานอยู่ เบรฟ ไวลด์รันเนอร์คงอยากรู้ชะตาของมาลาห์และตัวคนฆ่านาง" },
        completion = { "60:957775028:1466232131", "ข่าวนี้ร้ายแรงนัก เราต้องแจ้ง Baine ทันที!" },
    },
    [99082] = { -- The High Chieftain
        title = { "18:2071309006:2068364516", "มหาหัวหน้าเผ่า" },
        objective = { "68:1683743121:449685956", "ขอเข้าพบ High Chieftain Cairne Bloodhoof ที่ Thunder Bluff" },
        description = { "503:248961277:1129805763", "ความกล้าหาญที่เจ้าปกป้องพวกพ้องสมควรได้รับการยกย่อง จงไปธันเดอร์บลัฟฟ์ทางตะวันตกเฉียงเหนือ เมืองอันยิ่งใหญ่ที่ทอดเงาให้เราหลบร้อน แล้วขอเข้าพบพ่อของข้า\n\nท่านเป็นผู้นำการบุกเคียงข้างขุนศึกธรอลล์ในวัยหนุ่ม เพื่อชิงที่ราบคืนและขับไล่เซนทอร์ออกไปให้พ้น ในฐานะมหาหัวหน้าเผ่า ท่านจะตอบแทนเจ้าอย่างงามที่ช่วยรักษาเกียรติแห่งความกล้าหาญของท่าน\n\nต้องขึ้นลิฟต์ไปหามหาหัวหน้าเผ่า ท่านนั่งอยู่บนที่สูงใจกลางเมือง" },
        completion = { "347:69657542:1018312667", "เซนทอร์ Galak กล้าโผล่มาใน Mulgore อย่างนั้นหรือ?!\n\nเจ้าทำให้บรรพชนภาคภูมิใจที่ขับไล่พวกมันไปได้ ทีนี้พวกมันคงจำได้ว่าหากกล้ากลับมาอีกจะต้องเจ็บปวดเพียงใด!\n\nโปรดรับของขวัญนี้เพื่อเป็นเกียรติแก่สิ่งที่เจ้าทำ ขอให้มันรับใช้เจ้าได้ดีเมื่อเจ้าออกเดินทางในอาณาจักรของพระแม่ธรณีไปจนสุดขอบโลก" },
    },
    [99101] = { -- Our Ancient Enemy
        title = { "17:1378813869:396442138", "ศัตรูแต่โบราณของเรา" },
        objective = { "51:1540171840:1571628895", "นำ Longwalker Malah's Report ไปให้ Baine Bloodhoof" },
        description = { "193:1273979709:907686300", "เบน บลัดฮูฟเป็นผู้นำหมู่บ้านเรา เขาต้องรู้เรื่องการบุกรุกนี้ทันที\n\nนำรายงานของลองวอล์กเกอร์มาลาห์ไปให้เขา เจ้าจะพบเขาที่ใจกลางหมู่บ้าน\n\nรีบไปเถิด เราเสียเวลาไม่ได้แล้ว!" },
        progress = { "25:1384059162:1362261962 C 1:63:63", "เจ้าเอาอะไรมาให้ข้าหรือ {class}?" },
        completion = { "102:1363391568:1383505342 N 1:46:46", "<เบนอ่านรายงาน สีหน้าเคร่งเครียดขึ้น>\n\nเราจะปล่อยเรื่องนี้ไปไม่ได้ ขอบใจที่นำรายงานมาส่งให้ข้า {name}" },
        required = { [286104] = { "25:1960194077:186617387", "รายงานของ Longwalker Malah" } },
        objectiveLabels = {
            item = { ["Longwalker Malah's Report"] = "รายงานของ Longwalker Malah" },
        },
    },
    [99108] = { -- Sparring Match
        title = { "14:650037916:214973239", "ประลองฝีมือ" },
        objective = { "70:1318615504:345119402", "เอาชนะคู่ต่อสู้ 3 รายให้ Tang Stonehoof โดยดวลกับผู้เล่นคนอื่นหรือสู้กับ Novice Warrior" },
        description = { "12:261722808:917055563 C 441:621448183:1729354071", "สวัสดี {class} รุ่นเยาว์ แม้เจ้าจะไม่ได้เป็นนักรบและข้าสอนวิถีนั้นให้เจ้าไม่ได้ เจ้าก็ยังได้ประโยชน์จากการฝึกกับข้า\n\nลานประลองอยู่เบื้องหน้า เมื่อเข้าไปแล้ว จะเรียกใครว่าแม่หรือถือดาบหรือธนูก็ไม่สำคัญ ทุกคนเท่าเทียมกัน และทุกคนได้เรียนรู้วิธีลับเขาให้คมด้วยการต่อสู้ซึ่งหน้า\n\nเจ้าจะเข้ามาเรียนรู้วิถีของเราด้วยตัวเองไหม? จะสู้กับมือใหม่คนไหนที่นี่หรือคู่ต่อสู้คนอื่นที่เต็มใจก็ได้ ข้าไม่ถือ", variants = { { "421:989360917:103277610", "สวัสดี นักรบรุ่นเยาว์ เส้นทางที่เราจะเดินร่วมกันยังอีกไกล แต่ก้าวนี้สำคัญพอ ๆ กับก้าวอื่น\n\nลานประลองอยู่เบื้องหน้า เมื่อเข้าไปแล้ว จะเรียกใครว่าแม่หรือถือดาบหรือกระบองก็ไม่สำคัญ ทุกคนเท่าเทียมกัน และทุกคนได้เรียนรู้วิธีลับเขาให้คมด้วยการต่อสู้ซึ่งหน้า\n\nเข้ามาในลานของเราแล้วเรียนรู้ผ่านการต่อสู้ จะสู้กับมือใหม่คนไหนที่นี่หรือคู่ต่อสู้คนอื่นที่เต็มใจก็ได้ ข้าไม่ถือ" } } },
        completion = { { "174:312214718:1894565607", "34:473664648:1580074850 N 130:1615953449:680861372", "34:473664648:1580074850 C 130:1615953449:680861372", "34:473664648:1580074850 R 130:1615953449:680861372" }, "ฝีมือเจ้าทำให้ข้าภูมิใจ นักผจญภัย ดูเหมือนคนรุ่นใหม่ยังมีหวัง\n\nเอาของพวกนี้ไปรักษาแผลเถิด โลกอันโหดร้ายนี้ยังมีการต่อสู้อีกมากรอเจ้าอยู่" },
        progress = { "85:1206892201:1004769973", "ไม่มีครูคนไหนสอนได้ดีเท่าคมอาวุธของคู่ต่อสู้ที่จ่ออยู่ตรงหัวใจเจ้า" },
        steps = { { "44:1143162744:397712716", "ชนะการประลองกับผู้เล่น หรือปราบ Novice Warrior" } },
    },
    [99411] = { -- Kyle's Gone Missing!
        title = { "20:86534107:1787267121", "ไคล์หายไป!" },
        objective = { "161:728212201:816140086", "Ahab Wheathoof ที่ Bloodhoof Village ใน Mulgore ขอให้เจ้าให้อาหารลูกหมาสุดรักของเขา Kyle the Frenzied\n\nให้ Tender Strider Meat กับ Kyle แล้วกลับไปหา Ahab Wheathoof" },
        description = { "6:1458037112:951365446 N 453:285154496:1370058543", "ช่วยด้วย {name}! ไคล์ ลูกหมาสุดรักของข้าวิ่งหนีไปแล้ว! ข้ามั่นใจว่ามันวิ่งหลงอยู่แถวหมู่บ้านบลัดฮูฟและคงหิวแย่\n\nช่วยตามหาและให้อาหารมันทีได้ไหม? พอกินแล้วมันจะสงบลงและกลับบ้าน\n\nเจ้าต้องหาอาหารไปให้มัน ของโปรดของมันคือเนื้อสไตรเดอร์นุ่ม ๆ ออกไปทางตะวันออกจะพบสไตรเดอร์มากมาย ล่ามาสักตัวแล้วเอาเนื้อฉ่ำ ๆ ไปให้ไคล์ เมื่อเจอมันในหมู่บ้าน ให้วางเนื้อลง แล้วมันจะวิ่งมาหาเจ้าเอง" },
        completion = { "16:940017130:880912851 N 85:1478475989:51811289", "ทำได้ยอดเยี่ยม {name}! Kyle กินเสร็จก็กลับถึงบ้านแล้วตรงไปนอนเลย ขอบใจที่ช่วยนะ" },
        progress = { "18:60495041:217832038", "เจอ Kyle แล้วหรือยัง?" },
        steps = { { "8:1352851626:181572845", "ให้อาหาร Kyle" } },
    },
    [755] = { -- Rites of the Earthmother
        title = { "24:895749709:360748221", "พิธีแห่งพระแม่ธรณี" },
        objective = { "80:1406302353:1098787513", "เดินทางไปหา Seer Graytongue ที่อาศัยอยู่บนเนินเขาทางใต้ของ Camp Narache" },
        description = { "114:2028811867:1819675873 N 63:351964851:428382939 C 305:517273764:902711117", "ความเต็มใจทำงานเล็ก ๆ ให้ชาวทอเรนแห่ง Narache และความใฝ่รู้เป็นคุณสมบัติอันประเสริฐ {name} ข้าเชื่อว่าสักวัน Thunder Bluff จะยกย่องท่านเป็น{class}ผู้ยิ่งใหญ่\n\nก่อนถึงวันนั้น ท่านต้องเข้าพิธีแห่งพระแม่ธรณี ซึ่งมีทั้งหมดสามขั้น\n\nบททดสอบแรกคือพิธีแห่งพละกำลัง ไปหา Seer Graytongue แล้วบอกเขาว่า Chief Hawkwind ส่งท่านมา\n\nที่พักของผู้หยั่งรู้อยู่ทางใต้ของ Camp Narache พอดี ซ่อนอยู่ตามเนินเขา" },
        completion = { "86:1205964701:1353109138", "Chief Hawkwind ส่งท่านมาหรือ? การเริ่มพิธีแห่งพระแม่ธรณีเป็นงานใหญ่ทีเดียว..." },
    },
    [763] = { -- Rites of the Earthmother
        title = { "24:895749709:360748221", "พิธีแห่งพระแม่ธรณี" },
        objective = { "104:715720759:886296057", "นำ Totem of Hawkwind ไปให้ Baine Bloodhoof ที่ Bloodhoof Village โดยเดินตามถนนออกจาก Camp Narache" },
        description = { "131:1866337730:2044917468 N 359:1822003817:1241186449", "ท่านต้องผ่านอีกสองบททดสอบเพื่อดำเนินพิธีแห่งพระแม่ธรณีต่อ ถึงเวลาออกไปเปิดหูเปิดตาแล้ว {name}\n\nเดินทางไป Bloodhoof Village แล้วไปหา Baine Bloodhoof หัวหน้าเผ่าผู้เป็นบุตรของแคร์น ที่นั่นท่านจะได้เดินทางต่อและได้รับการยอมรับจากผู้อาวุโสแห่ง Thunder Bluff\n\nนำโทเท็มนี้ไปให้เบน เขาจะจำรอยแกะสลักของข้าได้และช่วยชี้ทางให้ท่าน\n\nเดินตามถนนออกจาก Camp Narache แล้วรีบไป อย่าออกนอกทาง เดี๋ยวจะหลง" },
        progress = { "31:1075299140:678156645 C 1:63:63", "อะไรพาท่านมายังหมู่บ้านข้า ท่าน{class}?" },
        completion = { "99:893716454:2043567382", "ข่าวจาก Chief Hawkwind สหายรักของข้า! อา ดูจากรอยแกะสลักของเขา ท่านคงเป็นคนพิเศษทีเดียว" },
        required = { [4783] = { "17:312949938:1760299335", "โทเท็มแห่ง Hawkwind" } },
        steps = { { "17:312949938:1760299335", "โทเท็มแห่ง Hawkwind" } },
    },
    [354] = { -- Deaths in the Family
        title = { "20:44185616:1739990700", "ความตายในตระกูล" },
        objective = { "91:1035805248:1731806757", "นำ Gregor's Remains, Nissa's Remains และ Thurman's Remains ไปให้ Coleman Farthing ที่ Brill" },
        description = { "498:565904157:998778098", "ตระกูลอากามันด์เคยมั่งคั่งที่สุดในทิริสฟัลเกลดส์ ข้าเคยทำงานในโรงโม่ของพวกเขา... ก่อนโรคระบาด\n\nเมื่อสเคิร์จบุกมาครั้งแรก พวกอากามันด์เสริมแนวป้องกันบ้านและชักชวนคนงานให้อยู่ช่วยปกป้อง เราโง่เอง แต่อย่างน้อยเราก็เป็นคนโง่ที่ภักดี\n\nความหยิ่งของพวกอากามันด์ทำให้เราต้องกลายเป็นอันเดด บัดนี้พวกเขากลับเป็นสมุนสเคิร์จ!\n\nจงรับใช้ฟอร์เซเคนด้วยการกำจัดคนตระกูลอากามันด์ที่พ่ายแก่โรคระบาด และช่วยข้าด้วยการนำซากพวกเขากลับมา" },
        progress = { "83:51623564:9504645", "ได้ซากของพวกอากามันด์มาแล้วหรือ? ในที่สุดเจ้าพวกต้องสาปนั่นก็ถูกกำจัดแล้วใช่ไหม?" },
        completion = { "267:792729497:427474522", "การแก้แค้นหอมหวาน เจ้าคิดอย่างนั้นไหม? ตอนกำจัดพวกอากามันด์ เจ้าเห็นแววว่าพวกมันยังมีใจคิดเองได้บ้างไหม? ข้าหวังว่าจะมี หวังให้พวกมันได้รู้จักความกลัวก่อนถูกทุบจนไม่เหลือซาก\n\nข้ารู้ว่าเป็นความหวังโง่ ๆ แต่ก็ยังอดหวังไม่ได้" },
        required = { [2829] = { "16:746387498:1655066041", "ร่างของ Gregor" }, [2828] = { "15:104932233:1364397028", "ร่างของ Nissa" }, [2830] = { "17:790512688:1267782199", "ร่างของ Thurman" } },
        steps = { { "16:746387498:1655066041", "ร่างของ Gregor" }, { "15:104932233:1364397028", "ร่างของ Nissa" }, { "17:790512688:1267782199", "ร่างของ Thurman" } },
    },
    [355] = { -- Speak with Sevren
        title = { "17:994516093:1193703606", "ไปคุยกับเซฟเรน" },
        objective = { "38:1513809395:184095698", "คุยกับ Magistrate Sevren ที่ Brill" },
        description = { "263:1330998052:116590915", "เจ้านำซากอากามันด์มาให้และช่วยให้ข้าได้แก้แค้นสมใจแล้ว แต่โรงโม่อากามันด์เป็นภัยต่อฟอร์เซเคนทุกคน\n\nข้าเล่าผลงานที่เจ้าจัดการพวกอากามันด์ให้ผู้พิพากษาเซฟเรนฟังแล้ว เขาอยากคุยกับเจ้า" },
        completion = { "28:773313173:769164786 N 112:257701567:1916962806", "โคลแมนชมเจ้าให้ข้าฟัง {name} เขาเล่าว่าเจ้าบุกโรงโม่อากามันด์สำเร็จ\n\nฟอร์เซเคนต้องการฝีมือเจ้าอีกครั้ง..." },
    },
    [356] = { -- Rear Guard Patrol
        title = { "17:802947167:1265781536", "ลาดตระเวนแนวหลัง" },
        objective = { "88:249600957:73633000", "สังหาร Bleeding Horror 8 ตัวและ Wandering Spirit 8 ตน แล้วกลับไปรายงาน Linnea ที่ค่ายของนาง" },
        description = { "461:59900163:47497267", "กองกำลังที่เดอะบูลวาร์กคอยปกป้องทิริสฟัลจากเพลกแลนด์สและเฝ้าระวังตลอดเวลา แต่บางครั้งสเคิร์จก็เล็ดลอดผ่านมาได้\n\nความสำเร็จที่บูลวาร์กขึ้นอยู่กับการรบแนวเดียว เราจะปล่อยให้ถูกโจมตีจากด้านหลัง หรือให้สายส่งเสบียงของกองกำลังถูกตัดไม่ได้\n\nไปช่วยบูลวาร์ก ลาดตระเวนไปทางตะวันออกและสังหารสเคิร์จที่พบ เน้นบริเวณไร่บอลเนียร์ทางตะวันออกเป็นพิเศษ ที่นั่นกลายเป็นแหล่งหลบซ่อนของสเคิร์จที่เล็ดลอดเข้ามา" },
        progress = { "36:1327352194:2028314788", "ได้รายงานจากการลาดตระเวนหรือยัง?" },
        completion = { "120:1683054742:1755131427", "ดีมาก งานที่เจ้าทำช่วยสกัดสเคิร์จไว้ได้มาก ข้าจะส่งคำชมไปถึงเอ็กเซคิวเตอร์ไซแกนด์ ผู้บังคับบัญชาของข้า" },
        objectiveLabels = {
            monster = { ["Bleeding Horror slain"] = "ปราบ อสูรอาบเลือด", ["Wandering Spirit slain"] = "ปราบ วิญญาณพเนจร" },
        },
    },
    [362] = { -- The Haunted Mills
        title = { "17:1056278451:629757084", "โรงโม่ผีสิง" },
        objective = { "77:150033252:299485985", "สังหาร Devlin Agamand แล้วนำ Devlin's Remains ไปให้ Coleman Farthing ที่ Brill" },
        description = { "494:1524033942:1926818633", "เดฟลิน อากามันด์เป็นลูกชายคนเล็กจากสองคนในตระกูล ตอนยังมีชีวิต ทั้งสองต่างกันสุดขั้ว เธอร์แมนตัวสูงและอ่อนโยน ส่วนน้องชายอ่อนแอและปากร้าย\n\nเมื่อโรงโม่อากามันด์พ่ายแก่โรคระบาด ข้าไม่แปลกใจที่ได้ยินว่าเดฟลินล้มลงอย่างรวดเร็ว เสียงพูดพล่ามคลุ้มคลั่งของมันยังได้ยินใกล้ถนนไปโรงโม่\n\nข้ากำลังเก็บซากคนตระกูลอากามันด์ และอยากได้ซากเดฟลินผู้น่าสงสาร ตามหามัน กำจัดมัน แล้วเอากระดูกมาให้ข้า" },
        progress = { "20:683774538:2018201081", "เจ้าเจอเดฟลินหรือยัง?" },
        completion = { "246:1053354126:1748152364", "ขอบใจ กระดูกเดฟลินคงวางได้พอดีบนขอบเตาผิงข้า\n\nหากหัวใจเย็นชาของข้ายังอุ่นขึ้นได้ ก็เพราะได้รู้ว่าพวกอากามันด์ถูกกำจัดแล้ว พวกมันทอดทิ้งข้ากับครอบครัวเมื่อโรคระบาดมา บัดนี้ข้าขอสาบานว่าจะเหยียบซากมันให้แหลกใต้ส้นเท้า!" },
        required = { [2831] = { "16:1770641873:1130302947", "ร่างของ Devlin" } },
        steps = { { "16:1770641873:1130302947", "ร่างของ Devlin" } },
    },
    [365] = { -- Fields of Grief
        title = { "15:65862323:329086473", "ทุ่งแห่งความโศก" },
        objective = { "114:1028054016:1835827229", "ขโมยฟักทอง 10 ลูกจากไร่ทางตะวันตก เหนือ Deathknell ขึ้นไปเล็กน้อย แล้วนำไปให้ Apothecary Johaan ที่ Brill" },
        description = { "45:754501779:674603448 C 373:743316294:995690812", "ใครกันนี่? เจ้าดูเป็น {class} มือใหม่ หากหวังพิสูจน์ตัวเองต่อเลดี้แห่งความมืด เจ้าต้องเรียนรู้วิถีฟอร์เซเคน\n\nทางตะวันตกมีไร่อยู่แห่งหนึ่ง พวกมนุษย์ยั้วเยี้ยทั่วผืนดินเหมือนราบนศพเน่า ที่แย่กว่านั้น สการ์เล็ตครูเสดยังส่งคนจากหอคอยมาลาดตระเวนแถวนั้น สั่งสอนเจ้าพวกสวะแล้วขโมยฟักทองหวงแหนของมันมา 10 ลูก\n\nเมื่อได้ครบ 10 ลูก นำไปให้นักปรุงยาโยฮานที่บริลล์" },
        progress = { "135:412885579:1518357812 N 1:63:63", "เดธการ์ดซิมเมอร์ส่งข่าวว่าเจ้าจะนำวัตถุดิบที่ข้าต้องการมากมาให้ เจ้าได้ฟักทองครบ 10 ลูกหรือยัง {name}?" },
        completion = { "44:1530036066:2016747192 C 72:29745775:1603690987", "เจ้าทำตามคำสั่งได้ดี {class} รุ่นเยาว์ เจ้ากำลังพิสูจน์ว่าตัวเองมีค่าต่อกองทัพเลดี้แห่งความมืด" },
        required = { [2846] = { "16:2110780579:1626273129", "ฟักทอง Tirisfal" } },
        steps = { { "16:2110780579:1626273129", "ฟักทอง Tirisfal" } },
    },
    [367] = { -- A New Plague
        title = { "12:172900303:707360461", "โรคระบาดชนิดใหม่" },
        objective = { "87:209720846:1089580896", "Apothecary Johaan ที่เมือง Brill ต้องการให้เจ้าเก็บ Vial of Darkhound Blood 5 ขวด" },
        description = { "454:973589420:1545343459", "เลดี้ซิลวานัสเรียกสมาคมนักปรุงยาหลวงเข้าพบ พระนางเชื่อว่าความรู้ของเราควบคู่กับเวทมนตร์ที่เพิ่งค้นพบจะเป็นกุญแจสู่จุดจบของอาร์ธัส พระนางท้าให้เราปรุงโรคระบาดชนิดใหม่ ร้ายแรงยิ่งกว่าโรคใดในอาเซรอธ โรคนี้จะทำให้กองทัพสเคิร์จของอาร์ธัสพินาศ\n\nผลศึกษาของข้าชี้ว่าเลือดสัตว์อาจเป็นกุญแจสำคัญ นำเลือดดาร์กฮาวนด์ 5 ขวดมาให้ข้าทดสอบทฤษฎี" },
        progress = { "51:1854819061:1435301189 N 19:439695803:2112417931", "เจ้าเก็บเลือดดาร์กฮาวนด์ครบ 5 ขวดแล้วหรือยัง {name}? เวลาเหลือน้อย!" },
        completion = { "20:1921578502:569519135 N 34:2024321016:309523898", "ทำได้ดี {name} ขอบใจที่อุตส่าห์ช่วย", variants = { { "19:124460492:1414145875 N 35:665338228:731857403", "ทำได้ดี {name} ขอบใจที่อุตส่าห์ช่วย" } } },
        required = { [2858] = { "15:1699897514:1888602812", "เลือด Darkhound" } },
        steps = { { "15:1699897514:1888602812", "เลือด Darkhound" } },
    },
    [368] = { -- A New Plague
        title = { "12:172900303:707360461", "โรคระบาดชนิดใหม่" },
        objective = { "95:1856363824:265277985", "Apothecary Johaan ที่เมือง Brill ต้องการ Vile Fin Scale 5 ชิ้นจากเมอร์ล็อกใน Tirisfal Glades" },
        description = { "393:1483357521:770106035", "ตอนเจ้าไปเก็บตัวอย่างให้ข้า การทดลองทำให้รู้ว่าต้องใช้วัตถุดิบเพิ่มเพื่อให้โรคใหม่นี้แพร่ได้ตามที่ตั้งใจ วางยาพิษเหยื่อโชคร้ายสักคนเป็นเรื่องง่าย แต่ทำให้โรคระบาดไปทั้งโลกนั้นซับซ้อนกว่า\n\nข้าต้องการ Vile Fin Scale 5 ชิ้นจากเมอร์ล็อกแถวนี้ เจ้าจะพบพวกมันตามชายฝั่งทางเหนือหรือทางตะวันตก" },
        progress = { "N 61:1996962531:619293026", "{name} เจ้าได้ Vile Fin Scale 5 ชิ้นจากเมอร์ล็อกมาหรือยัง?" },
        completion = { "24:1961734491:2113888485 N 44:657772868:1105304057", "เกล็ดพวกนี้สมบูรณ์ดี {name} ตรงกับที่ข้าต้องใช้ปรุงยาพอดี" },
        required = { [2859] = { "14:1922394225:537101812", "เกล็ด Vile Fin" } },
        steps = { { "14:1922394225:537101812", "เกล็ด Vile Fin" } },
    },
    [369] = { -- A New Plague
        title = { "12:172900303:707360461", "โรคระบาดชนิดใหม่" },
        objective = { "113:626576964:476162799", "Apothecary Johaan ที่เมือง Brill ต้องการตัวอย่างพิษ 4 ตัวอย่างจาก Vicious Night Web Spider" },
        description = { "503:1250116932:1184431853", "ระหว่างเจ้าออกไปเก็บของ ข้าพบข้อความเก่าในตำราเล่มหนึ่งระบุว่าโรคระบาดโบราณคร่าชีวิตผู้บริสุทธิ์หลายพันคน ต่อมาพบว่าสารมรณะในโรคนั้นยังหลงเหลืออยู่ในพิษของแมงมุมไนต์เว็บ\n\nเอาพิษจาก Vicious Night Web Spider มาให้ข้าจบการทดลองนี้ ข้าอยากรู้ว่าส่วนที่ทำให้แพร่เชื้อในพิษจะเข้ากับยาที่เพิ่งปรุงได้ไหม เขาลือกันว่าพบแมงมุมพวกนี้ทางตะวันออกของทิริสฟัลเกลดส์" },
        progress = { "60:1727499622:479767139 N 65:799250850:423706769", "ได้พิษจาก Vicious Night Web Spider แล้วหรือยัง {name}? นี่คือส่วนผสมสุดท้ายที่ข้าต้องใช้ทดสอบ" },
        completion = { "34:1513997072:961631623 N 116:194891670:342308338", "อา พิษนี้เหมาะเลย {name} ข้าใส่ส่วนผสมอื่นลงไปและเคี่ยวแล้ว ในที่สุดก็พร้อมทดสอบสารมรณะชนิดใหม่นี้!" },
        required = { [2872] = { "30:2116798459:41358921", "พิษแมงมุม Vicious Night Web" } },
        steps = { { "30:2116798459:41358921", "พิษแมงมุม Vicious Night Web" } },
    },
    [370] = { -- At War With The Scarlet Crusade
        title = { "31:949648588:240979925", "ทำสงครามกับสการ์เล็ตครูเสด" },
        objective = { "105:160477870:1904601357", "Executor Zygand ที่ Brill ต้องการให้เจ้าสังหาร Captain Perrine, Scarlet Zealot 3 คน และ Scarlet Missionary 3 คน" },
        description = { "330:87104296:1896588876", "เอกสารยุทธศาสตร์จากเอ็กเซคิวเตอร์อาร์เรนมีรายละเอียดทั้งหมดที่เราต้องใช้กวาดล้างพวกมนุษย์ออกจากดินแดน ตามข้อมูล สการ์เล็ตครูเสดส่งกัปตันเพอร์รินกับกองกำลังไปประจำหอคอยร้างทางตะวันตกเฉียงใต้ของบริลล์\n\nสังหารเพอร์รินพร้อมซีล็อต 3 คนและมิชชันนารี 3 คน แล้วกลับมารายงานข้า" },
        progress = { "6:854053781:490420846 C 315:1501295081:1747086119", "{class} รุ่นเยาว์ เจ้าไม่ควรเสียเวลาอยู่ในบริลล์ ขณะที่พวกพ้องต้องการให้เจ้าออกสู้เพื่ออุดมการณ์ จับอาวุธแล้วมุ่งตะวันตกเฉียงใต้ไปหอคอยร้าง สังหาร Captain Perrine พร้อม Scarlet Zealot 3 คนและ Scarlet Missionary 3 คน เราจะต้อนสการ์เล็ตครูเสดไปสู่จุดจบเหมือนต้อนฝูงวัว" },
        completion = { "98:178519341:1649969649 C 1:46:46", "ข่าวกัปตันเพอร์รินตายคงทำให้เลดี้แห่งความมืดพอพระทัย เจ้าทำหน้าที่ได้ดี {class}" },
        objectiveLabels = {
            monster = { ["Scarlet Missionary slain"] = "ปราบ มิชชันนารี Scarlet", ["Captain Perrine slain"] = "ปราบ กัปตัน Perrine", ["Scarlet Zealot slain"] = "ปราบ สาวกคลั่ง Scarlet" },
        },
    },
    [371] = { -- At War With The Scarlet Crusade
        title = { "31:949648588:240979925", "ทำสงครามกับสการ์เล็ตครูเสด" },
        objective = { "90:656447683:2110302818", "Executor Zygand ที่ Brill มอบหมายให้เจ้าสังหาร Captain Vachon และ Scarlet Friar 5 คน" },
        description = { "350:33503727:523501626", "สงครามยังดำเนินอยู่และสการ์เล็ตครูเสดยิ่งแข็งแกร่ง รายงานที่เอ็กเซคิวเตอร์อาร์เรนส่งมาระบุว่าเหล่าครูเซเดอร์ใช้หอคอยร้างในทิริสฟัลตะวันออกเฉียงใต้ใกล้ไร่บอลเนียร์เป็นฐานออกปล้น โดยมีกัปตันวาชองเป็นผู้บัญชาการ\n\nสังหารวาชองพร้อมนักบวชไฟรเออร์ 5 คน น่าจะเป็นการโจมตีที่สร้างความเสียหายหนักแก่ครูเสด!" },
        progress = { "235:628728800:194734765", "เจ้ากลับมาแล้วแต่งานยังไม่เสร็จ หรือเจ้าพอใจให้มนุษย์พวกนั้นมาขัดแผนเลดี้แห่งความมืด? จงทำหน้าที่แล้วสังหาร Captain Vachon กับกลุ่ม Scarlet Friar ของมันเสีย!" },
        completion = { "120:810387826:1066660783", "การตายของกัปตันวาชองจะชะลอการรุกของสการ์เล็ตครูเสดในทิริสฟัลได้มาก แต่ยังมีภัยอื่นรออยู่" },
        objectiveLabels = {
            monster = { ["Captain Vachon slain"] = "ปราบ กัปตัน Vachon", ["Scarlet Friar slain"] = "ปราบ นักบวช Scarlet" },
        },
    },
    [372] = { -- At War With The Scarlet Crusade
        title = { "31:949648588:240979925", "ทำสงครามกับสการ์เล็ตครูเสด" },
        objective = { "102:1110593832:661798122", "Executor Zygand ที่เมือง Brill ต้องการให้เจ้าลอบสังหาร Captain Melrache กับองครักษ์ทั้งสอง" },
        description = { "341:733984653:1321851292", "เหล่าสการ์เล็ตครูเซเดอร์ออกปล้นจากหอคอยร้างทางเหนือของทิริสฟัล เลย Faol's Rest ไป ตามข้อมูลที่เรามี ผู้บัญชาการโหดเหี้ยมชื่อกัปตันเมลแรชคุมพวกชั่วร้ายกลุ่มนี้\n\nข้ามอบภารกิจพิเศษที่อันตรายให้เจ้า สังหารเมลแรชกับองครักษ์ทั้งสองในนามเลดี้แห่งความมืด" },
        progress = { "38:825365135:1496727399 C 161:1543971205:1354935469", "เจ้ายังทำหน้าที่ไม่สำเร็จ {class} เราจะทำตามแผนเลดี้แห่งความมืดไม่ได้หากสการ์เล็ตครูเสดยังคอยกวนทหารเรา จงสังหารพวกมันและทำหน้าที่ต่อซิลวานัส!" },
        completion = { "30:818506999:2113910126 C 180:1375415250:951594611", "เจ้าทำได้ยอดเยี่ยม {class} เมื่อนักสู้ไร้ปรานีอย่างเจ้ารบชนะในนามฟอร์เซเคน เผ่าของเราก็เข้าใกล้ชัยชนะเด็ดขาดเหนืออาร์ธัสอีกก้าว ข้ามั่นใจในตัวเจ้า สหาย" },
        objectiveLabels = {
            monster = { ["Scarlet Bodyguard slain"] = "ปราบ องครักษ์ Scarlet", ["Captain Melrache slain"] = "ปราบ กัปตัน Melrache" },
        },
    },
    [374] = { -- Proof of Demise
        title = { "15:1828053829:707225472", "หลักฐานการสังหาร" },
        objective = { "63:1173161954:476042035", "นำ Scarlet Insignia Ring 10 วงไปให้ Deathguard Burgess ที่ Brill" },
        description = { "398:1182096454:283699297 C 100:735578151:108175842", "เอ็กเซคิวเตอร์ไซแกนด์บอกว่าเจ้าออกไปสังหารพวกสการ์เล็ตครูเซเดอร์ ทิริสฟัลเกลดส์เต็มไปด้วยพวกมัน\n\nวาริมาทรัส ผู้ช่วยของเลดี้แห่งความมืด กำลังลงมือด้วยตนเองเพื่อกวาดล้างพวกมนุษย์ สวะของอาเซรอธ ให้สิ้นซาก ที่ทิริสฟัลเกลดส์เราต้องรับมือมนุษย์สายพันธุ์ที่น่ารำคาญเป็นพิเศษ นั่นคือสการ์เล็ตครูเสด\n\nออกไปเปิดฉากโจมตีสการ์เล็ตครูเสด {class} แล้วนำ Scarlet Insignia Ring 10 วงกลับมาเป็นหลักฐานว่าเจ้าภักดีต่อวาริมาทรัสและเลดี้แห่งความมืด" },
        progress = { "50:732661769:1874894596 C 1:63:63", "เจ้าเก็บ Scarlet Insignia Ring ครบ 10 วงหรือยัง {class}?" },
        completion = { "57:1319649814:1288793196 C 1:46:46", "วาริมาทรัสคงภูมิใจ เจ้ารับใช้ผู้นำได้ดี {class}" },
        required = { [2875] = { "21:1841644014:1290867714", "แหวนตรา Scarlet" } },
        steps = { { "21:1841644014:1290867714", "แหวนตรา Scarlet" } },
    },
    [375] = { -- The Chill of Death
        title = { "18:1935982384:322985010", "ไอเย็นแห่งความตาย" },
        objective = { "76:487902940:2040423111", "นำ Duskbat Pelt ห้าผืนและ Coarse Thread ไปให้ Gretchen Dedmar ที่ Brill" },
        description = { "420:590044733:971528984 N 44:539038871:510878684", "หนาวเหลือเกิน โรคระบาดแห่งอันเดดเลื้อยไปตามเส้นเลือดข้าเหมือนงูเย็นเฉียบ อีกไม่นานข้าคงเข้าสู่ภาวะไร้สติ แต่ชะตาที่เลี่ยงไม่ได้จะหยุดข้าจากการรับใช้เลดี้แห่งความมืดไม่ได้ เมื่อมีคำสั่ง ข้าเคยเย็บถุงใส่ศพให้ทหารที่ล้มลงในกองทัพซิลวานัส\n\nตอนนี้มือสั่นเพราะหนาว หากเจ้าเอาหนังค้างคาวดัสก์แบตห้าผืนกับด้ายหยาบมาให้ ข้าจะเย็บผ้าห่มให้ตัวเอง ช่วยข้าที {name} ข้าจะได้รับใช้ต่อไป" },
        progress = { "59:295136179:269174214 N 1:63:63", "เจ้าได้ Duskbat Pelt ห้าผืนกับ Coarse Thread มาแล้วหรือยัง {name}?" },
        completion = { "27:1364373518:951069433 N 52:1021267636:407268489", "ข้าซาบซึ้งในความช่วยเหลือ {name} ขอให้ซิลวานัสเห็นความกล้าของเจ้าในสักวัน..." },
        required = { [2320] = { "13:392152061:1000008462", "ด้ายหยาบ" }, [2876] = { "12:4520162:1880419099", "หนังค้างคาวสนธยา" } },
        objectiveLabels = {
            item = { ["Coarse Thread"] = "ด้ายหยาบ", ["Duskbat Pelt"] = "หนังค้างคาวสนธยา" },
        },
    },
    [404] = { -- A Putrid Task
        title = { "13:299605535:34409300", "ภารกิจเน่าเหม็น" },
        objective = { "54:132958876:1051003982", "นำ Putrid Claw 7 ชิ้นไปให้ Deathguard Dillinger ที่ Brill" },
        description = { "267:2147180614:2069742716", "พวกสเคิร์จเล็ดลอดเข้าทิริสฟัลเกลดส์และยึดบริเวณทางตะวันตกของบริลล์ใกล้สะพานเก่า\n\nไปที่นั่นแล้วตีโต้ซากศพเน่าและร่างยับเยินที่พบ ตีให้กระดูกกระจายแล้วนำกรงเล็บเน่าของมันกลับมา เดธการ์ดจะให้รางวัลเจ้า" },
        progress = { "90:1448366142:1588883533", "ทำงานที่ข้ามอบหมายเสร็จแล้วหรือ? เจ้าได้กรงเล็บเน่าพวกนั้นมาหรือยัง?" },
        completion = { "84:1319821053:1581152472", "ทำได้ดี เสียดายข้าไม่ได้ไปเห็นเจ้าทุบพวกอันเดดจนเละเป็นเนื้อเน่า!", variants = { { "59:1468309195:1047808671 R 19:5716963:1223218372", "ทำได้ดี เสียดายข้าไม่ได้ไปเห็นเจ้าทุบพวก{race}จนเละเป็นเนื้อเน่า!" } } },
        required = { [2855] = { "11:2026423566:1993701920", "กรงเล็บเน่า" } },
        steps = { { "11:2026423566:1993701920", "กรงเล็บเน่า" } },
    },
    [407] = { -- Fields of Grief
        title = { "15:65862323:329086473", "ทุ่งแห่งความโศก" },
        objective = { "113:1969567487:2059740393", "นำ Laced Pumpkin ไปให้ Captured Scarlet Zealot ที่ถูกขังในห้องใต้ดินของ Gallow's End Tavern" },
        description = { "499:1955054303:1033939187", "ฟักทองไม่มีพิษภัยใช่ไหม? ดูเผิน ๆ ก็อย่างนั้น หากเราจะสกัดการรุกของอาร์ธัสจากเหนือและพวกมนุษย์ที่ยั้วเยี้ยจากใต้ เราต้องใช้ศักยภาพของการเป็นอันเดดที่ได้รับมาให้เต็มที่\n\nใช้ไหวพริบหน่อย ฟักทองธรรมดาก็กลายเป็นเครื่องมือของเลดี้แห่งความมืดได้ ฟักทองลูกนี้ผสมยาสูตรล่าสุดของข้าไว้ คงเป็นของอร่อยทีเดียว\n\nมีสการ์เล็ตซีล็อตถูกจับมาอีกคน ตอนนี้ขังไว้ในห้องใต้ดินโรงเตี๊ยมแกลโลว์สเอนด์ นำฟักทองนี้ไปให้เจ้าโง่นั่น" },
        progress = { "168:2110243516:2044337072", "ถอยไป เจ้าตัวโสมมไร้ศรัทธา! ขอแสงศักดิ์สิทธิ์คุ้มครองข้า! สการ์เล็ตครูเสดจะกวาดล้างอาเซรอธให้พ้นจากพวกเจ้า...\n\n...โอ้ เดี๋ยวก่อน นั่นอาหารของข้าหรือ? ข้าหิวเหลือเกิน..." },
        completion = { "60:585550802:1443301088", "ด้วยแสงศักดิ์สิทธิ์! ในที่สุดก็ได้กินเสียที! ฟักทองหวาน ๆ..." },
        required = { [3035] = { "13:814330696:253772995", "ฟักทองผสมยา" } },
        steps = { { "13:814330696:253772995", "ฟักทองผสมยา" } },
    },
    [408] = { -- The Family Crypt
        title = { "16:228428551:315399109", "สุสานประจำตระกูล" },
        objective = { "121:1293985437:1994224763", "สังหาร Wailing Ancestor 8 ตนและ Rotting Ancestor 8 ตน\n\nสังหาร Captain Dargol แล้วนำกะโหลกของเขาไปให้ Magistrate Sevren ที่ Brill" },
        description = { "451:1199095911:67311804", "แถวโรงโม่อากามันด์กลายเป็นฐานของสเคิร์จ จุดที่พวกมันตั้งมั่นที่สุดคือสุสานตระกูลอากามันด์ ผู้บัญชาการท้องถิ่นเป็นโครงกระดูกชื่อกัปตันดาร์กอลและใช้ที่นั่นเป็นกองบัญชาการ มันใช้เวทปลุกศพปลุกบรรพชนอากามันด์และวางแผนใช้พวกเขามาเล่นงานเรา\n\nปล่อยไว้ไม่ได้ เจ้าต้องหยุดมัน ไปสุสานตระกูลอากามันด์แล้วกำจัดบรรพชนที่ถูกปลุกขึ้นมา\n\nแล้วนำกะโหลกกัปตันดาร์กอลมาให้ข้า" },
        progress = { "30:192320348:1418992998 N 80:471541354:1104588374", "เราไม่มีเวลาให้เสียแล้ว {name} ทุกชั่วโมงที่ผ่านไป สเคิร์จยิ่งยึดทิริสฟัลเกลดส์ไว้แน่นขึ้น" },
        completion = { "174:794185294:1728032092 N 63:1114984007:1683795532", "การลงมือของเจ้าสร้างความเสียหายหนักแก่สเคิร์จ ชัยชนะนี้ทั้งฟอร์เซเคนและศัตรูจะต้องรับรู้\n\nสู้ต่อไปเหมือนที่พวกเราทุกคนทำ {name} สักวันเราจะขับไล่ลิชคิงออกจากอาเซรอธได้!" },
        required = { [3082] = { "14:2088549155:1398883368", "กะโหลกของ Dargol" } },
        steps = { { "14:2088549155:1398883368", "กะโหลกของ Dargol" } },
        objectiveLabels = {
            monster = { ["Wailing Ancestor slain"] = "ปราบ บรรพชนคร่ำครวญ", ["Rotting Ancestor slain"] = "ปราบ บรรพชนร่างเน่า" },
        },
    },
    [426] = { -- The Mills Overrun
        title = { "17:75132134:1351055173", "โรงโม่ถูกยึด" },
        objective = { "91:72135087:1917534412", "เก็บ Notched Rib 5 ชิ้นและ Blackened Skull 3 ชิ้น แล้วกลับไปหา Deathguard Dillinger ที่ Brill" },
        description = { "490:617613405:1695277458", "สเคิร์จพยายามตั้งฐานที่โรงโม่อากามันด์ หากทำสำเร็จ พวกมันจะใช้เป็นฐานโจมตีลึกเข้ามาในทิริสฟัลได้\n\nมีคำสั่งแล้ว ต้องกำจัดสเคิร์จในโรงโม่\n\nไปที่โรงโม่ เก็บ Notched Rib จาก Rattlecage Soldier และ Cracked Skull Soldier แล้วเก็บ Blackened Skull จาก Darkeye Bonecaster\n\nเดินตามถนนตะวันตกไปโรงโม่ ข้ามสะพานแล้วเลี้ยวขึ้นเหนือที่ทางแยกถัดไป จากนั้นเดินขึ้นเหนือต่อ เมื่อเห็นกังหันลม การต่อสู้ก็จะเริ่ม" },
        progress = { "38:1756183193:1461080426 N 81:235168623:1589569284", "การรบกับสเคิร์จยังดำเนินอยู่ {name} ทำหน้าที่ของเจ้าแล้วขับพวกอันเดดต้องสาปไร้สติกลับไปเพลกแลนด์สเสีย!", variants = { { "38:1756183193:1461080426 N 48:440605979:374025452 R 27:1167626192:1648126369", "การรบกับสเคิร์จยังดำเนินอยู่ {name} ทำหน้าที่ของเจ้าแล้วขับพวก{race}ต้องสาปไร้สติกลับไปเพลกแลนด์สเสีย!" } } },
        completion = { "43:763431524:1279952334 N 108:30993086:64083811", "พวกเรารับรู้ถึงความพยายามของเจ้าในสงคราม {name} ข้าคงไม่ขอบใจที่เจ้าทำสิ่งจำเป็น แต่เดธการ์ดแห่งทิริสฟัลจะจำชื่อเจ้าไว้" },
        required = { [3162] = { "11:793427148:451849117", "ซี่โครงมีรอยบาก" }, [3163] = { "15:870026417:32019679", "กะโหลกดำคล้ำ" } },
        steps = { { "11:793427148:451849117", "ซี่โครงมีรอยบาก" }, { "15:870026417:32019679", "กะโหลกดำคล้ำ" } },
    },
    [427] = { -- At War With The Scarlet Crusade
        title = { "31:949648588:240979925", "ทำสงครามกับสการ์เล็ตครูเสด" },
        objective = { "63:9186963:2075254083", "Executor Zygand แห่ง Brill ต้องการให้เจ้าสังหาร Scarlet Warrior 10 คน" },
        description = { "500:795421427:1317033330", "เอกสารจากเอ็กเซคิวเตอร์อาร์เรนเป็นโอกาสที่เรารอในการรบกับสการ์เล็ตครูเสด ตอนนี้เรารู้ตำแหน่งแน่ชัดของพวกมันทั่วทิริสฟัลเกลดส์\n\nแต่เดธการ์ดมีเรื่องใหญ่กว่าต้องรับมือ กองทัพลิชคิงมีจำนวนเพิ่มทุกคืน เราต้องการคนที่ “รู้จักลงมือเอง” อย่างเจ้าไปส่งสการ์เล็ตครูเสดลงหลุม\n\nพิสูจน์ว่าเจ้ารับใช้เลดี้แห่งความมืดได้ มุ่งตะวันตกไปหอคอยที่เลยไร่ซอลลิเดน แล้วสังหาร Scarlet Warrior 10 คน" },
        progress = { "76:752508324:332666386 C 1:46:46", "หากอยากพิสูจน์คุณค่าต่อเลดี้แห่งความมืด จงสังหาร Scarlet Warrior 10 คน {class}" },
        completion = { "16:959884130:63492255 C 48:775760183:199576436", "ยอดเยี่ยม {class} ฝีมือรบของเจ้าปฏิเสธไม่ได้" },
        objectiveLabels = {
            monster = { ["Scarlet Warrior slain"] = "ปราบ นักรบ Scarlet" },
        },
    },
    [445] = { -- Delivery to Silverpine Forest
        title = { "29:229649271:1338011028", "ส่งของไปป่าซิลเวอร์ไพน์" },
        objective = { "79:774100776:1591044131", "นำผลการศึกษาของ Apothecary Johaan ไปให้ Apothecary Renferrel ใน Silverpine Forest" },
        description = { "499:2081982219:439793898", "เวลาเป็นสิ่งฟุ่มเฟือยที่ผู้รับใช้เลดี้ซิลวานัสอย่างเราไม่มี เจ้าคงรู้แล้ว\n\nในฐานะสมาชิกสมาคมนักปรุงยาหลวง ข้ามีหน้าที่แบ่งปันความรู้กับเพื่อนร่วมงาน ความพยายามร่วมกันอาจมอบโรคระบาดชนิดใหม่ที่เลดี้แห่งความมืดปรารถนาอย่างยิ่งได้ในสักวัน\n\nเอาผลศึกษานี้ไปให้นักปรุงยาเรนเฟอร์เรลที่เซพัลเชอร์ในป่าซิลเวอร์ไพน์ เดินตามถนนลงใต้จากบริลล์ พอถึงอันเดอร์ซิตีให้มุ่งตะวันตกเฉียงใต้" },
        progress = { "35:770796531:652650629 C 1:63:63", "เจ้ามีธุระอะไรกับข้า {class}?" },
        completion = { "325:806487159:810616580 N 30:1153962991:1246274331 C 22:901143214:2095524928", "อา ดีจริงที่นักปรุงยาโยฮานส่งงานวิจัยมา มีความคืบหน้าใหม่ในซิลเวอร์ไพน์เสียมากจนข้าเกือบลืมผลศึกษาจากลอร์แดรอนกับทิริสฟัลเกลดส์ พูดแล้วก็นึกขึ้นได้ ข้าต้องส่งตัวอย่างพวกนั้นไปเนโครโพลิสเร็ว ๆ นี้\n\nขอโทษที่พูดเรื่อยเปื่อย อยู่ซิลเวอร์ไพน์ต่ออีกสักหน่อยเถิด {name} แถวนี้ต้องการ {class} แข็งแรงอย่างเจ้า" },
        required = { [3238] = { "17:1500213859:1942061804", "ผลการค้นคว้าของ Johaan" } },
        steps = { { "17:1500213859:1942061804", "ผลการค้นคว้าของ Johaan" } },
    },
    [492] = { -- A New Plague
        title = { "12:172900303:707360461", "โรคระบาดชนิดใหม่" },
        objective = { "57:628782534:202582601", "นำ Johaan's Special Drink ไปให้ Captured Mountaineer" },
        description = { "408:1487237621:1085388976", "เดธการ์ดบอกว่าเพิ่งจับทหารภูเขาคนแคระโง่ ๆ มาได้อีกคน พวกเดธการ์ดชอบใช้ห้องใต้ดินของโรงเตี๊ยมแกลโลว์สเอนด์ขังนักโทษไว้ จนกว่าจะ “จัดการอย่างเหมาะสม” ได้\n\nลองไปดูสิว่าทหารภูเขาที่ถูกจับจะชอบเครื่องดื่มพิเศษที่ข้าทำให้แค่ไหน ในนั้นมีเค้าบาง ๆ ของสิ่งที่เลดี้แห่งความมืดวางแผนไว้ให้ส่วนที่เหลือของอาเซรอธ" },
        progress = { "56:5139898:631657119 C 62:1358497025:1772690222", "ถ้าข้ามีปืนคู่ใจ เจ้าตายแน่ {class} คอยดูเถอะ เดี๋ยวกองพลรถถังไอน้ำจะมาช่วยข้า!" },
        completion = { "113:1937638925:1910547566", "อา ในที่สุดก็ได้ดื่ม ข้าว่าคงไม่ใช่ Rhapsody Malt แต่ถึงตอนนี้ได้อะไรให้ชุ่มคอก็เอาทั้งนั้น" },
        required = { [3460] = { "22:1461302109:384022976", "เครื่องดื่มสูตรพิเศษของ Johaan" } },
        steps = { { "22:1461302109:384022976", "เครื่องดื่มสูตรพิเศษของ Johaan" } },
    },
    [5481] = { -- Gordo's Task
        title = { "12:34708143:764162091", "งานของกอร์โด" },
        objective = { "90:795480195:1279857842", "เก็บ Gloom Weed 3 ต้นแล้วนำไปให้ Junior Apothecary Holland ที่สุสาน Brill" },
        description = { "224:1275842767:1493544943", "นายอยากได้หญ้า มือพวกข้าใหญ่ เก็บไม่เก่ง เจ้าช่วย พวกข้าไม่ทำร้าย พวกข้าต้องการ Gloom Weed มีหญ้าเยอะแถวนี้กับริมถนน\n\nได้ Gloom Weed แล้วเอาไปให้นายฮอลแลนด์ที่สุสานบริลล์" },
        progress = { "102:656832719:56155139", "เจ้าก้อนเนื้อไร้ประโยชน์นั่นอยู่ไหน? ถ้ามีสิ่งที่ข้าต้องการก็เอามา ถ้าไม่มีก็รีบออกไปหา" },
        completion = { "384:718397848:18583743", "อะไรนี่? Gloom Weed งั้นหรือ?! ข้าไม่ต้องการ Gloom Weed! เจ้าก้อนเนื้อไร้สตินั่นออกไปเก็บดอกเดซี แถมยังชวนคนหลงเชื่ออย่างเจ้าให้ทำตามไม่รู้กี่คน ขออย่าถือสา\n\nเอาเถิด เจ้ามาถึงแล้วก็พอ ข้าจะไม่เสียเวลาอธิบายให้เจ้าตัวประหลาดนั่นฟัง เจ้าช่วยไปเก็บของที่ข้าต้องการจริง ๆ ให้ที Doom Weed นั่นแหละ!" },
        required = { [12737] = { "10:1838914544:2015607048", "วัชพืชมืดหม่น" } },
        steps = { { "10:1838914544:2015607048", "วัชพืชมืดหม่น" } },
    },
    [5482] = { -- Doom Weed
        title = { "9:596309428:1764458032", "หญ้าแห่งหายนะ" },
        objective = { "72:1958445201:784042745", "เก็บ Doom Weed 10 ต้นแล้วนำกลับไปให้ Junior Apothecary Holland" },
        description = { "44:1637593954:918577401 N 345:1301923232:575236800", "ตอนนี้เจ้าคงเห็นแล้วว่าข้าเจอปัญหาอะไร {name} เจ้านั่นไปเก็บหญ้าผิดชนิด! ข้าจะตอบแทนให้คุ้มถ้าเจ้าไปเก็บของที่ข้าต้องการ นำ Doom Weed กลับมาให้พอ แล้วข้าจะให้รางวัลที่เหมาะสม\n\nเท่าที่ข้ารู้ พวกมันชอบขึ้นแทรกต้นไม้อยู่แถวหลุมศพรวมเหนือสุสานบริลล์ รีบไปและระวังโนลล์แถวนั้นด้วย" },
        progress = { "78:1994187268:1178963080", "ขอให้เป็นเรื่องดีเถอะ เจ้าเอา Doom Weed ที่ข้าต้องการมาครบแล้วใช่ไหม?" },
        completion = { "175:1351604471:807009560 N 50:1175601634:1471880216", "อา Doom Weed ของข้า ยอดเยี่ยม!\n\n<นักปรุงยาฝึกหัดฮอลแลนด์ถูมือด้วยความละโมบ>\n\nพวกนี้มีประโยชน์มาก วันนี้เจ้าช่วยข้า เอ่อ ช่วยเลดี้ไว้มาก {name} นี่รางวัลที่เจ้าสมควรได้รับตามสัญญา" },
        required = { [13702] = { "9:596309428:1764458032", "วัชพืชวิบัติ" } },
        steps = { { "9:596309428:1764458032", "วัชพืชวิบัติ" } },
    },
    [86784] = { -- Sticks and Bones
        title = { "16:1931290377:2064294308", "กิ่งไม้กับกระดูก" },
        objective = { "60:867435908:127734435", "เก็บ Dry Branch 6 กิ่งแล้วนำไปให้ Eleanor Shackleton", amount = { "8:1089852795:1107240600 W1 51:612387631:730252959", "เก็บ Dry Branch {world1} กิ่งแล้วนำไปให้ Eleanor Shackleton" } },
        description = { "485:1681885061:984933252", "เอลีนอร์ แช็กเคิลตัน เพื่อนร่วมงานของข้าภูมิใจที่เดินทางผ่านป่าและเอาตัวรอดจากสภาพอากาศกับสัตว์ประหลาด ตอนนี้นางตั้งค่ายไม่ไกลจากที่นี่ บนเนินทางตะวันตก ข้าจำคำแนะนำที่นางเคยให้ได้ “เมื่อคิดว่าฟืนพอแล้ว ให้เก็บอีกห้าเท่า”\n\nหากพอมีเวลา ลองเก็บฟืนใส่ตะกร้านี้แล้วนำไปค่ายนาง ข้ามั่นใจว่านางมีเคล็ดลับการใช้ชีวิตของนักผจญภัยเร่ร่อนให้เจ้าบ้าง" },
        progress = { "29:1497063080:1967718620", "มาผิงไฟสิ นักเดินทาง" },
        completion = { "199:54761261:1773165619", "ฟืนเพิ่มหรือ? ยินดีรับเสมอ มันจะช่วยให้กระดูกแก่ ๆ พวกนี้อุ่นตลอดคืนหนาวในเกลดส์\n\nข้ามีสายสะพายขนฟืนของตัวเองอยู่แล้ว เจ้าเก็บตะกร้านั่นไว้เถิด" },
        required = { [279991] = { "10:800058960:976449001", "กิ่งไม้แห้ง" } },
        steps = { { "10:800058960:976449001", "กิ่งไม้แห้ง" } },
    },
    [95314] = { -- That Shadowvale Green Elixir
        title = { "28:1112509496:2140221323", "น้ำยาสีเขียวแห่งชาโดว์เวล" },
        objective = { "94:1545758162:1772769863", "เก็บ Bottle of Whispering Elixir 8 ขวดจาก Shadowvale แล้วกลับไปหา Carolai Anise ที่ Brill", amount = { "8:1089852795:1107240600 W1 85:291742842:1154408164", "เก็บ Bottle of Whispering Elixir {world1} ขวดจาก Shadowvale แล้วกลับไปหา Carolai Anise ที่ Brill" } },
        description = { "500:524486569:164247821", "ก่อนสเคิร์จรุกราน หมู่บ้านชาโดว์เวลที่อยู่สันโดษขึ้นชื่อเรื่อง Whispering Elixir น้ำยานี้กลั่นจากสมุนไพรที่พบเฉพาะใน Tyr's Fall นักปรุงยา ผู้ศึกษาศาสตร์ลี้ลับ และนักวางยาพิษล้วนตามหา แม้ทางเมืองจะสั่งห้ามน้ำยานี้แล้ว\n\nผู้ซื้อหลายรายขอให้ข้าหาน้ำยานี้ให้ ไปซากหมู่บ้านชาโดว์เวลลึกเข้าไปในป่าวิสเพอริงทางตะวันตก หากกู้น้ำยากลับมาได้บ้าง ข้าพร้อมจ่ายให้คุ้ม" },
        progress = { "29:2088449896:940973664", "หวังว่าเจ้าคงไม่หลงทางนะ?" },
        completion = { "297:563455124:685490242 N 56:1340770243:801001330", "เจ้าว่ามีสิ่งชั่วร้ายในชาโดว์เวลหรือ? ข้ายอมรับว่าไม่แปลกใจ คนในป่านั้นแปลกประหลาดและไม่ชอบผู้มาเยือน บางคนเชื่อว่าป่าวิสเพอริงต้องคำสาป และน้ำยาที่กลั่นจากรากไม้ในป่าก็ติดคำสาปเดียวกัน...\n\n...แต่พอเรื่องงมงายกับข่าวลือเถิด {name} ขอบใจสำหรับน้ำยา เอานี่ไปเป็นค่าตอบแทน" },
        required = { [268801] = { "27:1781099597:1266789282", "ยาอายุวัฒนะเสียงกระซิบหนึ่งขวด" } },
        steps = { { "27:1781099597:1266789282", "ยาอายุวัฒนะเสียงกระซิบหนึ่งขวด" } },
    },
    [95328] = { -- Whispering Horror Residue
        title = { "25:1267265633:407564826", "เศษซากของวิสเพอริงฮอร์เรอร์" },
        objective = { "86:837501825:1812453535", "นำ Whispering Horror Residue ไปให้ Father Lankester ใน War Quarter ของ Undercity" },
        description = { "139:211743465:174099775", "ทั้งที่สัญชาตญาณเตือนให้ปล่อยไว้ เจ้าก็ขูดเก็บซากที่ยังดิ้นยุกยิกของสัตว์ประหลาด บางคนในอันเดอร์ซิตีอาจใช้ประโยชน์จากมันได้" },
        progress = { "41:942262369:2019940410", "มีของมาให้ข้าหรือ นักผจญภัย?", variants = { { "30:956154495:1839869622 C 1:63:63", "มีของมาให้ข้าหรือ {class}?" } } },
        completion = { { "259:84378141:242113697", "195:1861336494:814604916 N 54:1964884994:1457402809", "195:1861336494:814604916 C 54:1964884994:1457402809", "195:1861336494:814604916 R 54:1964884994:1457402809" }, "ตัวอย่างน่าสนใจจริง เจ้าว่ามาจากใต้ป่าวิสเพอริงหรือ? ใคร ๆ ก็รู้ว่าที่ชั่วร้ายนั่นถูกวอยด์แตะต้อง\n\nข้ายินดีที่ได้ศึกษาความลี้ลับแห่งเงา นักผจญภัย ขอตอบแทนเจ้าสำหรับสิ่งที่พบ" },
        required = { [268812] = { "25:1267265633:407564826", "เศษตกค้างของ Whispering Horror" } },
        steps = { { "25:1267265633:407564826", "เศษตกค้างของ Whispering Horror" } },
    },
    [96895] = { -- The Argent Emissary
        title = { "19:1973715831:1095774230", "ทูตแห่งอาร์เจนต์ดอว์น" },
        objective = { "63:1857985014:2066145757", "ตามหาสมาชิก Argent Dawn ใกล้ทางเข้า Undercity" },
        description = { "488:5146249:1133520533", "ไม่รู้เจ้าได้ข่าวไหม ทูตอาร์เจนต์ดอว์นสองคนเพิ่งผ่านมาที่นี่ ข้าไม่ได้รังเกียจอาร์เจนต์ดอว์น แต่ไม่ชอบให้มาสอดส่องทิริสฟัลโดยไม่มีใครคุม ทั้งคู่เป็นฟอร์เซเคน... แต่ข้าก็ยังไม่สบายใจอยู่ดี\n\nคนหนึ่งเพิ่งผ่านไปทางตะวันออกเฉียงใต้ มีพวกลัทธิสเคิร์จกลุ่มหนึ่งด้อม ๆ มอง ๆ รอบนอกเมืองทางนั้น หากทูตทั้งสองได้ข่าว คงสนใจแน่นอน" },
        completion = { "87:1405818764:855093490", "หมอบต่ำไว้ พยายามอย่าให้ใครเห็น นักผจญภัย พวกลัทธินี้ไม่ใช่พวกที่ควรไปลองดีด้วย", variants = { { "33:1330562171:458020565 C 44:677483640:386558100", "หมอบต่ำไว้ พยายามอย่าให้ใครเห็น {class} พวกลัทธินี้ไม่ใช่พวกที่ควรไปลองดีด้วย" } } },
    },
    [96896] = { -- A Righteous Cause
        title = { "17:1653415231:22568915", "อุดมการณ์อันชอบธรรม" },
        objective = { "81:1792430394:43128123", "สังเกตบทสนทนาระหว่าง Danitha Morr กับ Leonid Barthalomew the Revered" },
        description = { "440:729109181:567828418", "ดานิธากับข้าสู้กับสเคิร์จเพื่อปกป้องอันเดอร์ซิตีตอนแน็กซ์รามัสโจมตี เราเสียเพื่อนดี ๆ ไปหลายคนในวันนั้น รวมถึงกาเร็ก บันดาเรียน วีรบุรุษที่ป้อมนี้ตั้งชื่อตาม\n\nเขาอาจเป็นฟอร์เซเคนคนแรกที่ค้นพบอีกครั้งว่าจะใช้แสงศักดิ์สิทธิ์ในฐานะพาลาดินได้อย่างไร ข้ามีกำลังใจที่เห็นดานิธากับพวกสืบทอดสิ่งที่เขาทิ้งไว้และทำให้ความหวังนั้นยังอยู่\n\nถ้าเพียงฟอร์เซเคนคนอื่นจะคิดเหมือนกัน...", variants = { { "440:729603015:1791244988", "ดานิธากับข้าสู้กับสเคิร์จเพื่อปกป้องอันเดอร์ซิตีตอนแน็กซ์รามัสโจมตี เราเสียเพื่อนดี ๆ ไปหลายคนในวันนั้น รวมถึงกาเร็ก บันดาเรียน วีรบุรุษที่ป้อมนี้ตั้งชื่อตาม\n\nเขาอาจเป็นฟอร์เซเคนคนแรกที่ค้นพบอีกครั้งว่าจะใช้แสงศักดิ์สิทธิ์ในฐานะพาลาดินได้อย่างไร ข้ามีกำลังใจที่เห็นดานิธากับพวกสืบทอดสิ่งที่เขาทิ้งไว้และทำให้ความหวังนั้นยังอยู่\n\nถ้าเพียงฟอร์เซเคนคนอื่นจะคิดเหมือนกัน..." } } },
        completion = { "267:210157813:1444729111", "ข้าตั้งใจอยู่ที่นี่สักพักเพื่อคุยกับเพื่อนอีกหลายคน แต่อีกไม่นานจะกลับไปวิหารไลต์สโฮปในเพลกแลนด์สตะวันออก หากเจ้าไปทางนั้น แวะทักทายกันด้วย เรายังต้องการแรงช่วยจากนักผจญภัยที่แข็งแรงอยู่เสมอ", variants = { { "271:1798852812:1954985188", "ข้าตั้งใจอยู่ที่นี่สักพักเพื่อคุยกับเพื่อนอีกหลายคน แต่อีกไม่นานจะกลับไปวิหารไลต์สโฮปในเพลกแลนด์สตะวันออก หากเจ้าไปทางนั้น แวะทักทายกันด้วย เรายังต้องการแรงช่วยจากนักผจญภัยที่แข็งแรงอยู่เสมอ" } } },
    },
    [96897] = { -- The Cult of the Damned
        title = { "22:1970212937:2013980259", "ลัทธิแห่งผู้ต้องสาป" },
        objective = { "62:1641612429:242840588", "สังหาร Dark Neophyte 8 คนและ Dark Enforcer 8 คนใน Tirisfal Glades", amount = { "5:409775429:850574908 W1 20:1393064412:174606212 W2 35:717573265:1192066956", "สังหาร Dark Neophyte {world1} คนและ Dark Enforcer {world2} คนใน Tirisfal Glades" } },
        description = { "248:1348749572:389912270", "สเคิร์จเป็นภัยต่อผืนดินเรา และสมุนที่ยังมีชีวิตของมันเลวร้ายที่สุด ชาวทิริสฟัลต้องรับมือทั้งซากศพไร้สติและสการ์เล็ตครูเสดมากพอแล้ว หากอยากช่วยทำเรื่องดี จงช่วยข้ากำจัดพวกสวะนี้", variants = { { "248:1201192654:1348933492", "สเคิร์จเป็นภัยต่อผืนดินเรา และสมุนที่ยังมีชีวิตของมันเลวร้ายที่สุด ชาวทิริสฟัลต้องรับมือทั้งซากศพไร้สติและสการ์เล็ตครูเสดมากพอแล้ว หากอยากช่วยทำเรื่องดี จงช่วยข้ากำจัดพวกสวะนี้" } } },
        completion = { "154:1144904880:1054323622", "ขอบใจที่ช่วย นักผจญภัย หากไม่อยากให้ประวัติศาสตร์ของลอร์แดรอนซ้ำรอย เราต้องเฝ้าระวังเมื่อภัยเช่นนี้โผล่ขึ้นมา", variants = { { "24:699096832:1500611632 C 120:130038562:1347560619", "ขอบใจที่ช่วย {class} หากไม่อยากให้ประวัติศาสตร์ของลอร์แดรอนซ้ำรอย เราต้องเฝ้าระวังเมื่อภัยเช่นนี้โผล่ขึ้นมา" } } },
        progress = { "191:1132162530:1075229919", "ข้าชิงชังพวกคนเป็นที่รับใช้ Scourge เป็นพิเศษ พวกมันมีอิสระจะเดินจากไป แต่คำมั่นว่าจะได้อำนาจและชีวิตอมตะทำให้พวกมันสูญเสียทั้งเหตุผลและสำนึกผิดชอบ" },
