        },
    },
    [96898] = { -- Remnants of War
        title = { "15:506987779:354034564", "เศษซากสงคราม" },
        objective = { "56:724138265:442224490", "เก็บ Necrotic Crystal Fragment 12 ชิ้นใน Tirisfal Glades", amount = { "7:451016854:1830523975 W1 47:37524133:2095132682", "เก็บ Necrotic Crystal Fragment {world1} ชิ้นใน Tirisfal Glades" } },
        description = { "470:712424161:2021358664", "ไม่นานมานี้ ป้อมแน็กซ์รามัสเคลื่อนเข้าบดขยี้เมืองนี้ หวังลบฟอร์เซเคนออกจากแผนที่ ทั้งฟอร์เซเคนและอาร์เจนต์ดอว์นสูญเสียมากมายในวันนั้นเพื่อรักษาอนาคตของฟอร์เซเคน\n\nระหว่างรบ ผลึกรวมพลังเนโครติกขนาดใหญ่ที่ติดตั้งอยู่บนยอดแน็กซ์รามัสแตก เศษของมันกระจายทั่วบริเวณนี้ ข้าสงสัยว่านั่นคือสิ่งที่พวกลัทธิมาตามหา ช่วยข้ากู้เศษผลึกแล้วกันไม่ให้สเคิร์จได้ไป", variants = { { "473:1539212964:290125898", "ไม่นานมานี้ ป้อมแน็กซ์รามัสเคลื่อนเข้าบดขยี้เมืองนี้ หวังลบฟอร์เซเคนออกจากแผนที่ ทั้งฟอร์เซเคนและอาร์เจนต์ดอว์นสูญเสียมากมายในวันนั้นเพื่อรักษาอนาคตของฟอร์เซเคน\n\nระหว่างรบ ผลึกรวมพลังเนโครติกขนาดใหญ่ที่ห้อยอยู่ใต้แน็กซ์รามัสแตก เศษของมันกระจายทั่วบริเวณนี้ ข้าสงสัยว่านั่นคือสิ่งที่พวกลัทธิมาตามหา ช่วยข้ากู้เศษผลึกแล้วกันไม่ให้สเคิร์จได้ไป" }, { "473:1708025588:1234252012", "ไม่นานมานี้ ป้อมแน็กซ์รามัสเคลื่อนเข้าบดขยี้เมืองนี้ หวังลบฟอร์เซเคนออกจากแผนที่ ทั้งฟอร์เซเคนและอาร์เจนต์ดอว์นสูญเสียมากมายในวันนั้นเพื่อรักษาอนาคตของฟอร์เซเคน\n\nระหว่างรบ ผลึกรวมพลังเนโครติกขนาดใหญ่ที่ห้อยอยู่ใต้แน็กซ์รามัสแตก เศษของมันกระจายทั่วบริเวณนี้ ข้าสงสัยว่านั่นคือสิ่งที่พวกลัทธิมาตามหา ช่วยข้ากู้เศษผลึกแล้วกันไม่ให้สเคิร์จได้ไป" } } },
        progress = { "169:1388324291:496840854", "ข้าแนะนำว่าอย่าสัมผัสผลึกพวกนั้นโดยตรงมากนัก แม้จะแตกและหมดพลังแล้ว เวทที่ค้างอยู่ในผลึกเนโครติกยังอันตรายมาก" },
        completion = { "220:1240467593:1638256911", "ขอบใจ นี่น่าจะชะลอการทำงานของสเคิร์จแถวนี้ได้ ข้าคิดว่าชาวทิริสฟัลคงต้องขุดผลึกพวกนี้จากดินไปอีกหลายปี แต่อย่างน้อยเอาชิ้นที่เห็นชัดออกไปก็ช่วยได้", variants = { { "220:561911481:1023869989", "ขอบใจ นี่น่าจะชะลอการทำงานของสเคิร์จแถวนี้ได้ ข้าคิดว่าชาวทิริสฟัลคงต้องขุดผลึกพวกนี้จากดินไปอีกหลายปี แต่อย่างน้อยเอาชิ้นที่เห็นชัดออกไปก็ช่วยได้" } } },
        required = { [275851] = { "25:1717878166:807584312", "เศษผลึกเนโครติก" } },
        steps = { { "25:1717878166:807584312", "เศษผลึกเนโครติก" } },
    },
    [96899] = { -- Bandarion Keep
        title = { "14:492815838:260407671", "ป้อมบันดาเรียน" },
        objective = { "61:820053499:1089578551", "พบ Leonid Barthalomew ที่ Bandarion Keep ใน Tirisfal Glades" },
        description = { "501:542947625:1476162035", "วันนี้เจ้าช่วยอุดมการณ์ของอาร์เจนต์ดอว์นไว้มาก ข้าขอบใจ ไม่รู้ว่าเจ้าคุ้นกับป้อมบันดาเรียนแค่ไหน ข้ากับผู้บัญชาการกำลังจะไปที่นั่นเพื่อพบพาลาดินที่อาศัยอยู่ ก่อนจะได้ข่าวว่าลัทธิแห่งผู้ต้องสาปอยู่แถวนี้\n\nหากอยากรู้เรื่องอาร์เจนต์ดอว์นกับภารกิจของเราเพิ่ม ไปพบผู้บัญชาการข้าที่ป้อมบันดาเรียน ทางตะวันตกเฉียงเหนือของที่นี่ ข้าจะอยู่เก็บกวาดเรื่องที่เหลือตรงนี้" },
        completion = { "455:105521793:1964034565", "ที่นี่มีความทรงจำมากมายสำหรับข้า อาร์เจนต์ดอว์นเคยครองที่นี่ เราใช้เป็นฐานเตรียมศึกและการปะทะกับสเคิร์จหลายครั้งเมื่อพวกมันรุกเข้าทิริสฟัลเกลดส์ครั้งล่าสุด\n\nตอนถอยไปเพลกแลนด์ส ข้ากลัวว่าที่นี่จะถูกทิ้งให้ทรุดโทรม ความกลัวนั้นมีมูล แต่ข้าดีใจที่ดานิธากับพาลาดินของนางเข้ามาดูแลแล้ว\n\nนางถึงกับตั้งชื่อป้อมตาม... เพื่อนของเราคนหนึ่ง", variants = { { "455:274334417:760677050", "ที่นี่มีความทรงจำมากมายสำหรับข้า อาร์เจนต์ดอว์นเคยครองที่นี่ เราใช้เป็นฐานเตรียมศึกและการปะทะกับสเคิร์จหลายครั้งเมื่อพวกมันรุกเข้าทิริสฟัลเกลดส์ครั้งล่าสุด\n\nตอนถอยไปเพลกแลนด์ส ข้ากลัวว่าที่นี่จะถูกทิ้งให้ทรุดโทรม ความกลัวนั้นมีมูล แต่ข้าดีใจที่ดานิธากับพาลาดินของนางเข้ามาดูแลแล้ว\n\nนางถึงกับตั้งชื่อป้อมตาม... เพื่อนของเราคนหนึ่ง" }, { "460:1071671470:1889592568", "ที่นี่มีความทรงจำมากมายสำหรับข้า อาร์เจนต์ดอว์นเคยครองที่นี่ เราใช้เป็นฐานเตรียมศึกและการปะทะกับสเคิร์จหลายครั้งเมื่อพวกมันรุกเข้าทิริสฟัลเกลดส์ครั้งล่าสุด\n\nตอนถอยไปเพลกแลนด์ส ข้ากลัวว่าที่นี่จะถูกทิ้งให้ทรุดโทรม ความกลัวนั้นมีมูล แต่ข้าดีใจที่ดานิธากับพาลาดินของนางเข้ามาดูแลแล้ว\n\nนางถึงกับตั้งชื่อป้อมตาม... เพื่อนของเราคนหนึ่ง" } } },
    },
    [97558] = { -- Hides for the Forsaken
        title = { "22:2103675319:316257572", "หนังสัตว์เพื่อฟอร์เซเคน" },
        objective = { "93:1085101344:151229388", "นำ Duskbat Wing Membrane 8 ชิ้น, Darkhound Hide 6 ผืน และ Vile Fin Murloc Skin 3 ชิ้นไปให้ Shelene Rhobart", amount = { "22:144309389:985522000 W1 25:1796924278:1109125187 W2 21:1007506891:8549117 W3 22:557391622:37373875", "นำ Duskbat Wing Membrane {world1} ชิ้น, Darkhound Hide {world2} ผืน และ Vile Fin Murloc Skin {world3} ชิ้นไปให้ Shelene Rhobart" } },
        description = { "158:765451201:1684727808 N 335:1782767349:223839396", "มีด้านหนึ่งของการเป็นอันเดดที่ไม่มีใครพูดถึง คือจะเกิดอะไรขึ้นเมื่อเราบาดเจ็บ ผิวของอันเดดรักษาตัวเองอย่างไร?\n\nคำตอบคือมันรักษาไม่ได้\n\nชีวิตเราเป็นชีวิตต้องสาป {name} เราต้องพรากจากสิ่งมีชีวิตเพื่อยืดการดำรงอยู่ของตน\n\nเมื่อบาดเจ็บ เราต้องเปลี่ยนผิวใหม่ ส่วนใหญ่ใช้หนังสัตว์ หนังหนาบางต่างกันเหมาะกับคนละส่วนของร่างกาย จึงต้องมีหลายแบบ!\n\nนำเยื่อปีกดัสก์แบต หนังดาร์กฮาวนด์ และผิวเมอร์ล็อกไวล์ฟินมาให้ข้า" },
        progress = { "342:465165086:30020280", "เจ้าได้หนังที่ขอหรือยัง? ของที่เก็บไว้ใกล้หมดแล้ว\n\nขอหนังเมอร์ล็อกอาจฟังแปลก แต่ใช้ทำเยื่อด้านในหรือบริเวณอย่างแก้มกับปากได้ดี\n\nส่วนเยื่อปีกดัสก์แบตเหมาะกับส่วนละเอียดอ่อนอย่างหน้าหรือนิ้ว ช่วยไม่ให้ผิว... หนาเกินไป", variants = { { "342:1559936128:1918086066", "เจ้าได้หนังที่ขอหรือยัง? ของที่เก็บไว้ใกล้หมดแล้ว\n\nขอหนังเมอร์ล็อกอาจฟังแปลก แต่ใช้ทำเยื่อด้านในหรือบริเวณอย่างแก้มกับปากได้ดี\n\nส่วนเยื่อปีกดัสก์แบตเหมาะกับส่วนละเอียดอ่อนอย่างหน้าหรือนิ้ว ช่วยไม่ให้ผิว... หนาเกินไป" } } },
        completion = { "89:52540265:91803375", "อา ยอดเยี่ยม! ขอบใจที่หามาให้ ข้ารับรองว่าจะเอาไปใช้อย่างคุ้มค่า" },
        required = { [278242] = { "21:1715305978:659543150", "เยื่อปีก Duskbat" }, [278243] = { "14:1503707533:77031441", "หนัง Darkhound" }, [278244] = { "20:261426804:286154358", "หนังเมอร์ล็อก Vile Fin" } },
        steps = { { "21:1715305978:659543150", "เยื่อปีก Duskbat" }, { "14:1503707533:77031441", "หนัง Darkhound" }, { "20:261426804:286154358", "หนังเมอร์ล็อก Vile Fin" } },
    },
    [98389] = { -- A Light in the Darkness
        title = { "23:1911413840:1925755003", "แสงในความมืด" },
        objective = { "80:81249677:330504113", "ปลดปล่อย Webbed Victim 6 รายใน Night's Web Hollow ให้ Aramis Hammerhand ที่ Deathknell", amount = { "5:224567089:1545670707 W1 74:1481415983:377347132", "ปลดปล่อย Webbed Victim {world1} รายใน Night's Web Hollow ให้ Aramis Hammerhand ที่ Deathknell" } },
        description = { "11:927657569:725753248 C 492:2028699148:715263452", "สวัสดี {class} ใช่ ข้าเป็นพาลาดิน แม้แต่ความตายก็หยุดแสงศักดิ์สิทธิ์ไม่ได้\n\nพวกข้ามีสิ่งหนึ่งร่วมกับฟอร์เซเคนทั้งปวง เราก้าวผ่านสิ่งที่คนเป็นมองว่าเป็นจุดจบ แต่แม้แต่พวกเดียวกันบางคนก็ยังกลัวเรา คิดว่าเราจะฟาดฟันพวกเขาราวกับเป็นสัตว์ประหลาด\n\nความจริงความสัมพันธ์ของเรากับการเป็นอันเดดนั้นซับซ้อน แต่ข้าไม่ได้มาทำร้ายพวกพ้อง ช่วยข้าแสดงให้คนอื่นเห็นที ไปถ้ำไนต์สเว็บฮอลโลว์ทางตะวันตกเฉียงเหนือแล้วปลดปล่อยเจ้าพวกซุ่มซ่ามที่เพิ่งถูกปลุกและติดใยแมงมุมอยู่ที่นั่น", variants = { { "526:233205632:1604148216", "หากเจ้าจะจำเพียงเรื่องเดียว จงจำไว้ว่าแม้แต่ความตายก็หยุดแสงศักดิ์สิทธิ์ไม่ได้\n\nนี่คือสิ่งที่เรามีร่วมกับฟอร์เซเคนทั้งปวง เราก้าวผ่านสิ่งที่คนเป็นมองว่าเป็นจุดจบ แต่แม้แต่พวกเดียวกันบางคนก็ยังกลัวเรา คิดว่าเราจะฟาดฟันพวกเขาราวกับเป็นสัตว์ประหลาด\n\nความจริงความสัมพันธ์ของเรากับการเป็นอันเดดนั้นซับซ้อน แต่พวกเราไม่ได้มาทำร้ายพวกพ้อง ช่วยข้าแสดงให้คนอื่นเห็นที ไปถ้ำไนต์สเว็บฮอลโลว์ทางตะวันตกเฉียงเหนือแล้วปลดปล่อยเจ้าพวกซุ่มซ่ามที่เพิ่งถูกปลุกและติดใยแมงมุมอยู่ที่นั่น\n\nแล้วพวกเขาจะเห็นตัวตนของเรา" }, { "11:927657569:725753248 C 479:132744951:361059495", "สวัสดี {class} ใช่ ข้าเป็นพาลาดิน แม้แต่ความตายก็หยุดแสงศักดิ์สิทธิ์ไม่ได้\n\nพวกข้ามีสิ่งหนึ่งร่วมกับฟอร์เซเคนทั้งปวง เราก้าวผ่านสิ่งที่คนเป็นมองว่าเป็นจุดจบ แต่แม้แต่พวกเดียวกันบางคนก็ยังกลัวเรา คิดว่าเราจะฟาดฟันพวกเขาราวกับเป็นสัตว์ประหลาด\n\nความจริงความสัมพันธ์ของเรากับการเป็นอันเดดนั้นซับซ้อน แต่ข้าไม่ได้มาทำร้ายพวกพ้อง ช่วยข้าแสดงให้คนอื่นเห็นที ไปถ้ำไนต์สเว็บฮอลโลว์ทางตะวันตกเฉียงเหนือแล้วปลดปล่อยเจ้าพวกซุ่มซ่ามที่เพิ่งถูกปลุกและติดใยแมงมุมอยู่ที่นั่น" } } },
        progress = { "64:810189938:446535812", "เจ้าช่วยผู้โชคร้ายที่ติดในถ้ำนั้นออกมาแล้วหรือยัง?" },
        completion = { "289:381405571:1095103927", "ขอให้เรื่องนี้ช่วยให้เอ็กเซคิวเตอร์อาร์เรนและคนอื่น ๆ เห็นตัวตนที่แท้จริงของเรา เช่นเดียวกับตอนมีชีวิต เราอยู่เพื่อรับใช้และปกป้องพวกพ้องด้วยพรที่แสงศักดิ์สิทธิ์มอบให้\n\nเมื่อเวลาผ่านไป พวกเขาจะเห็นว่าเรามีค่าต่อแผนเลดี้แห่งความมืดไม่แพ้คนอื่น\n\nขอแสงศักดิ์สิทธิ์อยู่กับเจ้า" },
        steps = { { "21:786570910:1506358020", "ช่วยชาว Forsaken ออกจากใยแมงมุม" } },
    },
    [98545] = { -- Leonid's Letter
        title = { "15:273127154:1520964151", "จดหมายของลีโอนิด" },
        objective = { "58:1209079808:771350671", "ส่ง Sealed Letter ให้ Glix Xizzix ใน Undercity" },
        description = { "450:1144068920:308818383", "ไหน ๆ เจ้าก็มาแล้ว ข้าอยากให้ส่งจดหมายนี้ให้เพื่อนเก่าในอันเดอร์ซิตี ข้าคงไปส่งเองถ้าไม่ได้มีเรื่องเก่า ๆ กับเลดี้แห่งความมืดอยู่บ้าง ให้คนกลางที่เป็นกลางไปส่งดีกว่า\n\nตามหาก็อบลินชื่อกลิกซ์ ซิซซิกซ์ในย่านการค้าของอันเดอร์ซิตี ข้ามั่นใจว่าเขายินดีตอบแทนที่เจ้าสละเวลา\n\n<ลีโอนิดหัวเราะเบา ๆ ขณะยื่นจดหมายให้เจ้า>" },
        progress = { "139:203128527:1058790714", "อะไรนะ? ลีโอนิดส่งนายมาหรือ? โอ้โห ไม่เจอทหารแก่หนังเหนียวนั่นตั้งแต่แน็กซ์รามัสถล่มพวกเราจากฟ้าแล้ว" },
        completion = { "351:2108676361:215393670", "ขอบใจที่เอามาส่งนะเพื่อน\n\nเดี๋ยวนะ... เขาบอกว่าฉันจะให้ทิปหรือ? ฉันไม่ได้ตกลงเรื่องนั้น!\n\nเอาก็เอา เลือกของเกะกะในกองของหายไปสักชิ้น นายคงแปลกใจว่าฟอร์เซเคนลืมของไว้หลังตัดผมกันเยอะขนาดไหน จะเล่นมุกว่าพวกนี้ไม่มีสมองก็ได้ แต่หลายรายฉันว่าน่าจะไม่มีจริง ๆ", variants = { { "351:313785160:1543475489", "ขอบใจที่เอามาส่งนะเพื่อน\n\nเดี๋ยวนะ... เขาบอกว่าฉันจะให้ทิปหรือ? ฉันไม่ได้ตกลงเรื่องนั้น!\n\nเอาก็เอา เลือกของเกะกะในกองของหายไปสักชิ้น นายคงแปลกใจว่าฟอร์เซเคนลืมของไว้หลังตัดผมกันเยอะขนาดไหน จะเล่นมุกว่าพวกนี้ไม่มีสมองก็ได้ แต่หลายรายฉันว่าน่าจะไม่มีจริง ๆ" } } },
        required = { [282065] = { "13:890948337:521983192", "จดหมายผนึก" } },
        objectiveLabels = {
            item = { ["Sealed Letter"] = "จดหมายผนึก" },
        },
    },
    [99134] = { -- Discipline
        title = { "10:284390502:1760191184", "ระเบียบวินัย" },
        objective = { "41:159693143:254045104", "ลงโทษ Deathguard 5 นายให้ Executor Zygand", amount = { "7:19998079:76734373 W1 33:337027938:1513750827", "ลงโทษ Deathguard {world1} นายให้ Executor Zygand" } },
        description = { "216:1964431594:1529886167 N 74:89593133:1847698591", "เจ้าไม่ใช่สมาชิกเดธการ์ด จึงยังไม่เคยทำให้ข้าผิดหวัง\n\nข้าจะให้รางวัลที่เจ้ายังไร้ฝีมือน้อยกว่าคนอื่น ด้วยการให้เจ้าลงโทษผู้ที่แสดงความไร้ฝีมือออกมาอย่างเหลือเฟือ\n\nรีบไปได้แล้ว ชื่อ {name} ใช่ไหม? มิฉะนั้นข้าจะจดชื่อเจ้าลงบัญชีไว้เป็นรางวัลให้คนอื่น", variants = { { "227:2003084808:1005131540 N 74:89593133:1847698591", "เจ้าไม่ใช่สมาชิกเดธการ์ด จึงยังไม่เคยทำให้ข้าผิดหวัง\n\nรางวัลสำหรับการที่เจ้าไม่ได้ไร้ฝีมือ คือสิทธิ์ลงโทษพวกที่แสดงความไร้ฝีมือออกมาอย่างเหลือเฟือ\n\nรีบไปได้แล้ว ชื่อ {name} ใช่ไหม? มิฉะนั้นข้าจะจดชื่อเจ้าลงบัญชีไว้เป็นรางวัลให้คนอื่น" } } },
        progress = { "24:2102457800:525833493", "ขอให้เป็นเรื่องดีเถอะ" },
        completion = { "193:1183004635:598709432", "ในความตายมีความสำราญให้เราน้อยนัก โชคดีที่ความเจ็บปวดเป็นความสำราญอันดับต้น ๆ\n\nวันนี้เจ้าทำให้ข้าพอใจ เท่ากับทำให้เลดี้แห่งความมืดพอพระทัย บางทีเจ้าอาจยังมีประโยชน์ต่อไป" },
        steps = { { "21:988803896:838136675", "กระตุ้นเหล่า Deathguard" } },
    },
    [99141] = { -- Patience
        title = { "8:1327073780:476177043", "ความอดทน" },
        objective = { "92:2128186648:1765798505", "ขอรายงานจาก Deathguard Dillinger, Deathguard Kristof และ Gordo ไปให้ Executor Zygand" },
        description = { "17:1512091216:997470409 C 484:1605100632:442688333", "เข้าใจให้ชัด {class} เลดี้แห่งความมืดต้องการให้ปฏิบัติตามพระประสงค์อย่างสมบูรณ์ ในฐานะเอ็กเซคิวเตอร์ ข้ามีหน้าที่ทำให้เป็นเช่นนั้น\n\nรายงานจากเดธการ์ดของข้าหลายคนเลยกำหนดแล้ว คงไม่ต้องบอกว่าข้าหมดความอดทน ไปเอารายงานของพวกเขามาให้ข้าในนามเลดี้แห่งความมืด\n\nเจ้าจะพบ Deathguard Dillinger ทางตะวันตกจากที่นี่นิดเดียว ข้างสุสาน Deathguard Kristof ประจำที่จุดพักทางตะวันออก ส่วนกอร์โด เจ้าตัวประหลาดนั่นเดินวนทางตะวันตกใกล้สระสติลวอเตอร์ ไปดูมันด้วย" },
        progress = { "61:2046128584:871205947", "ขอให้เจ้าถือรายงานพวกนั้นมาด้วย ไม่อย่างนั้นก็ไปให้พ้นหน้าข้า" },
        completion = { "220:994834987:1196994600", "ข้าน่าจะรู้ว่าเจ้าตัวประหลาดเย็บศพเขียนอะไรมีประโยชน์ไม่ได้ เก็บการตัดสินใจพลาดครั้งนี้ไว้ระหว่างเราก็แล้วกัน\n\nเจ้าทำให้ข้าพอใจ จึงทำให้เลดี้แห่งความมืดพอพระทัย บางทีเจ้าอาจยังมีหวัง" },
        required = { [286200] = { "18:2078356373:687698171", "รายงานของ Dillinger" }, [286201] = { "16:429855671:1809670428", "รายงานของ Kristof" }, [286202] = { "14:955609271:424891795", "รายงานของ Gordo" } },
        steps = { { "18:2078356373:687698171", "รายงานของ Dillinger" }, { "16:429855671:1809670428", "รายงานของ Kristof" }, { "14:955609271:424891795", "รายงานของ Gordo" } },
    },
    [99142] = { -- Tomb Weed
        title = { "9:306318613:502761648", "หญ้าสุสาน" },
        objective = { "71:285178020:2048599431", "เก็บ Tomb Weed 5 ต้นแล้วนำกลับไปให้ Junior Apothecary Holland", amount = { "8:1089852795:1107240600 W1 62:2072965923:112858721", "เก็บ Tomb Weed {world1} ต้นแล้วนำกลับไปให้ Junior Apothecary Holland" } },
        description = { "502:1145195810:449570336", "ถ้าเจ้ามุ่งตะวันออกไปทางไร่บอลเนียร์ ข้ามีงานเพิ่มให้ช่วย ช่วงนี้คนช่วยดี ๆ หายากเหลือเกิน เรื่องที่เจ้าพบกอร์โดก็แสดงให้เห็นชัดแล้ว\n\nเมื่อได้ Doom Weed มา ข้าจะปรับมันด้วยวิชาปรุงยาเล็กน้อยแล้วปลูกใหม่ที่ไร่นั้น เพื่อเพาะผลงานชั้นยอดของข้า ข้าเรียกมันว่า Tomb Weed และมันจะเป็นลางบอกชะตาอันรุ่งโรจน์ของข้า\n\nคอยระวังสเคิร์จแถวนั้นด้วย ดูเหมือนพวกมันจะ... ถูกดึงดูด... เข้าหาหญ้านี่ แปลกจริง" },
        progress = { "75:875827095:1322493279", "มาขัดอีกแล้ว! เดี๋ยว นี่เจ้าเอง ได้ Tomb Weed กลับมาหรือเปล่า?" },
        completion = { "249:1431513629:1353604963", "รุ่งโรจน์ยิ่งนัก!\n\n<นักปรุงยาฝึกหัดฮอลแลนด์ตรวจดูหญ้า>\n\nอืม ข้าหวังว่ามันจะเติบโตอย่างรุนแรงกว่านี้สักหน่อย แต่ถึงอย่างไรก็ถือว่าคืบหน้า!\n\nการกระทำของเจ้าในวันนี้จะทำให้คนตายอีกมาก เจ้าควรภูมิใจ" },
        required = { [286204] = { "9:306318613:502761648", "วัชพืชจากสุสาน" } },
        steps = { { "9:306318613:502761648", "วัชพืชจากสุสาน" } },
    },
    [99144] = { -- Seeking Refuge
        title = { "14:20858301:1889537316", "ตามหาที่พึ่ง" },
        objective = { "98:428065938:487204160", "ช่วย Bareth Dawnstone หนีจาก Crusader's Outpost แล้วรายงานว่าเขาปลอดภัยให้ Shari Stilwell ที่ Brill" },
        description = { "500:1738719263:1983669863", "ขอแสงศักดิ์สิทธิ์อวยพรที่เจ้าพบข้า ข้าเดินทางจากป้อมบันดาเรียนจะไปส่งข่าวให้ชารี สติลเวลล์ที่บริลล์ แต่ถูกเจ้าพวกสัตว์ประหลาดจับ พวกมันใช้แสงศักดิ์สิทธิ์ด้วยความเกลียดชังในใจจนเลือดที่เหลือในกายข้าเดือดพล่าน ขัดกับทุกสิ่งที่ข้าภาวนาและพยายามปกป้อง!\n\n<บาเรธ ดอว์นสโตนตั้งสติ>\n\nข้ารู้ว่าบางคนยังไม่ยอมรับพวกข้า แต่ข้ายืนยันว่าเรามีเจตนาบริสุทธิ์ หากช่วยให้ข้าหนีจากที่นี่ได้ ข้าจะซาบซึ้งตลอดไป", variants = { { "406:105372825:449339311", "ขอแสงศักดิ์สิทธิ์อวยพรที่เจ้าพบข้า ข้าเดินทางจากป้อมบันดาเรียนจะไปส่งข่าวให้ชารี สติลเวลล์ที่บริลล์ แต่ถูกเจ้าพวกสัตว์ประหลาดจับ พวกมันใช้แสงศักดิ์สิทธิ์ด้วยความเกลียดชังในใจจนเลือดที่เหลือในกายข้าเดือดพล่าน ขัดกับทุกสิ่งที่พวกเรายึดมั่น!\n\n<บาเรธ ดอว์นสโตนตั้งสติ>\n\nพวกเรามีคนน้อย หากช่วยให้ข้าหนีจากที่นี่ได้ ข้าจะซาบซึ้งตลอดไป" } } },
        completion = { "369:1832646493:1788753369", "ขอพรจงมีแก่เจ้าที่ช่วยดอว์นสโตน คณะของเราเพิ่งตั้งหลักที่นี่ หากเสียคนอนาคตไกลเช่นเขาก่อนเวลาอันควรคงเป็นความสูญเสียใหญ่หลวง\n\nโปรดรับสิ่งนี้แทนคำขอบคุณ หากวันใดสนใจวิถีของเรา อารามป้อมบันดาเรียนตั้งอยู่บนหน้าผาทางตะวันตกเฉียงเหนือของไร่ซอลลิเดน เรายินดีต้อนรับทุกคนที่แสวงหาหนทางในแสงศักดิ์สิทธิ์" },
        objectiveLabels = {
            event = { ["Escort Bareth Dawnstone out of Crusader's Outpost"] = "คุ้มกัน Bareth Dawnstone ออกจาก Crusader's Outpost" },
        },
    },
    [99152] = { -- As Above, So Below
        title = { "18:597627604:1113173313", "เบื้องบนเป็นฉันใด เบื้องล่างเป็นฉันนั้น" },
        objective = { "54:2086006358:81940372", "เก็บ Faintly Glowing Bone 6 ชิ้นให้ Hilda the Breaker", amount = { "8:1089852795:1107240600 W1 45:386863158:1296376462", "เก็บ Faintly Glowing Bone {world1} ชิ้นให้ Hilda the Breaker" } },
        description = { "505:511680236:1211997023", "แม้พวกทาร์นิชด์ในชาโดว์เวลทางตะวันตกเฉียงใต้จะเป็นปัญหาอยู่แล้ว แต่เราจะปล่อยให้ภัยในห้องใต้ดินของเมืองลุกลามเป็นการก่อการของสเคิร์จใส่ป้อมบันดาเรียนไม่ได้\n\nข้าต้องฝึกพวกมือใหม่ให้พร้อมเผื่อเกิดเรื่องนั้น ส่วนเจ้าจะได้รับสิ่งที่ข้าเรียกว่าบทเรียนเร่งรัด\n\nลงไปใต้ชาโดว์เวลแล้วนำกระดูกของพวกมันกลับมาให้เราศึกษา ข้าต้องการชิ้นที่ยังเหลือเวทปลุกชีพเดิมอยู่ คือชิ้นที่เรืองแสงนั่นแหละ" },
        progress = { "167:1599040788:393045771", "หวังว่าเจ้าจะไม่กลับมามือเปล่า ข้าต้องการกระดูกที่ขอ หรือไม่ก็ร่างเจ้าบนเปลหามเพื่อยืนยันว่าอย่างน้อยเจ้าพยายามสุดแรงแล้ว" },
        completion = { "131:28228105:1109223463", "ทำได้ดี นักผจญภัย กระดูกพวกนี้อาจช่วยให้เราเข้าใจว่าภัยเช่นนี้หลบสายตาเราได้นานขนาดนั้นอย่างไร", variants = { { "11:534428891:784080240 C 110:872606529:1314473927", "ทำได้ดี {class} กระดูกพวกนี้อาจช่วยให้เราเข้าใจว่าภัยเช่นนี้หลบสายตาเราได้นานขนาดนั้นอย่างไร" }, { "173:586121902:900307146", "ทำได้ดี พลฝึกหัด ดูท่าว่าเราคงฝึกเจ้าให้ได้เรื่องอยู่บ้าง\n\nกระดูกพวกนี้อาจช่วยให้เราเข้าใจว่าภัยขนาดนี้รอดสายตาเราไปได้นานขนาดนั้นอย่างไร" } } },
        required = { [286259] = { "20:1005354478:1158191985", "กระดูกเรืองแสงจาง ๆ" } },
        steps = { { "20:1005354478:1158191985", "กระดูกเรืองแสงจาง ๆ" } },
    },
    [99153] = { -- The One That Got Away
        title = { "21:1547083196:513271663", "ตัวที่หนีรอดไป" },
        objective = { "71:965572651:1409067924", "ค้นหา Hidden Crystal Fragment ใต้ Shadowvale ให้ Ephram Barbaro" },
        description = { "447:1967286893:1612711503", "เฮ้ เจ้าน่ะ! ข่าวในหมู่เราไปไว ข้าได้ยินเรื่องที่เจ้าจัดการพวกลัทธิแถวซากสนามรบกับแน็กซ์รามัสแล้ว\n\nปัญหาคือพวกลัทธิตัวหนึ่งหนีไปพร้อมเศษผลึกรวมพลัง ดูเหมือนยังมีพลังเหลือ คาดว่าน่าจะอยู่ที่ไหนสักแห่งใต้ชาโดว์เวล มันกำลังปลุกพวกนั้นขึ้นมา หรือไม่ก็ทำให้พวกมันแข็งแกร่งขึ้น ทั้งสองอย่างไม่ดีแน่\n\nหาเศษผลึกนั่นก่อนเรื่องจะบานปลาย" },
        progress = { "30:1189471608:1041523756", "เจอไอ้ของบ้านั่นหรือยัง?" },
        completion = { "55:1604675345:670146002", "ทำได้ดี แถมไวด้วย! ทีนี้ถึงส่วนที่ข้าชอบที่สุด..." },
        required = { [286269] = { "24:249637335:1742473791", "เศษผลึกเรืองแสง" } },
        steps = { { "24:249637335:1742473791", "เศษผลึกเรืองแสง" } },
    },
    [99156] = { -- Rear Guard Patrol
        title = { "17:802947167:1265781536", "ลาดตระเวนแนวหลัง" },
        objective = { "43:1741229661:1528779789", "นำ Riptear's Heart ไปให้ Deathguard Linnea" },
        description = { "497:2116468917:605553275", "ให้ตายเถอะ! มีรายงานใหม่เข้ามาตอนเจ้าออกลาดตระเวน มีคนเห็นตัวประหลาดเย็บศพที่หลุดจากการควบคุมเดินอยู่ในทิริสฟัลเกลดส์ตะวันออก ใกล้เวนอมเว็บเวล\n\nต้องมีอะไรผิดปกติ พวกตัวประหลาดแบบนี้เล็ดลอดผ่านบูลวาร์กโดยไม่มีใครเห็นไม่ได้ง่าย ๆ\n\nให้รู้เรื่องนี้เฉพาะคนที่จำเป็นเท่านั้น อีกอย่าง ตัวแบบนี้ล้มไม่ง่าย ต้องพาพวกไปด้วยถ้าไม่อยากกลายเป็นมื้อต่อไปของมัน\n\nจัดการให้สำเร็จแล้วเจ้าจะได้รับรางวัลตามสมควร เอาหัวใจมันมาเป็นหลักฐาน" },
        progress = { "39:52375475:203229872", "เจ้าจัดการปัญหาเล็ก ๆ ของเราแล้วหรือยัง?" },
        completion = { "186:361797740:1711265", "เจ้าเป็นหลักฐานว่าฟอร์เซเคนทุกคนมีไหวพริบและรู้จักร่วมมือกัน สิ่งที่สเคิร์จไร้สติไม่มีวันมี\n\nโปรดรับสิ่งนี้แทนคำขอบคุณสำหรับความพยายาม ตามที่ข้าสัญญา" },
        required = { [286326] = { "15:40619323:50324100", "หัวใจของ Riptear" } },
        steps = { { "15:40619323:50324100", "หัวใจของ Riptear" } },
    },
    [8080] = { -- Arathi Basin Resources!
        title = { "23:1607010962:2075543507", "ทรัพยากรแห่งอาราธีเบซิน!" },
        objective = { "114:1921065572:1911428284", "ชนะการรบที่ Arathi Basin รับ Arathi Resource Crate แล้วนำไปให้ Sergeant Maclear ที่ Refuge Pointe" },
        description = { "373:1273676569:386495157 N 113:360552461:671051154", "สงครามต้องอาศัยทหาร ถามทหารคนไหนก็ได้ และพวกเขาจะบอกด้วยว่าถ้ารบด้วยอุปกรณ์ไม่ดีหรือท้องว่าง ก็แพ้ตั้งแต่ยังไม่เริ่ม!\n\nนี่คือเหตุผลที่อาราธีเบซินสำคัญ พื้นที่ยุทธศาสตร์ในแอ่งนี้มีทรัพยากรจำเป็น ทั้งโลหะ อาวุธ อาหาร และไม้ เราต้องใช้ทั้งหมดและหาได้ที่นั่น\n\nนี่คือสิ่งที่ข้าต้องการจากเจ้า {name} เข้าสู่ Arathi Basin ชนะการรบด้วยการครองฐานมากกว่าศัตรู แล้วนำ Mark of Honor กลับมาให้ข้า", variants = { { "373:1273676569:386495157 N 118:1649747761:348632480", "สงครามต้องอาศัยทหาร ถามทหารคนไหนก็ได้ และพวกเขาจะบอกด้วยว่าถ้ารบด้วยอุปกรณ์ไม่ดีหรือท้องว่าง ก็แพ้ตั้งแต่ยังไม่เริ่ม!\n\nนี่คือเหตุผลที่อาราธีเบซินสำคัญ พื้นที่ยุทธศาสตร์ในแอ่งนี้มีทรัพยากรจำเป็น ทั้งโลหะ อาวุธ อาหาร และไม้ เราต้องใช้ทั้งหมดและหาได้ที่นั่น\n\nนี่คือสิ่งที่ข้าต้องการจากเจ้า {name} เข้าสู่ Arathi Basin ชนะการรบด้วยการครองฐานมากกว่าศัตรู แล้วนำ ทรัพยากรหนึ่งลัง กลับมาให้ข้า" } } },
        progress = { "32:119972586:1384428818 N 67:1794564808:1973746598", "เจ้าได้ Mark of Honor มาหรือยัง {name}? สันนิบาตอาราธอร์รบให้ดีไม่ได้หากขาดมัน..." },
        completion = { "133:1288952087:502684611 N 94:852723070:35116513", "เจ้าได้ตรามาแล้ว! ทำได้ดีมาก! ข้าจะส่งเสบียงไปให้นายคลังแจกจ่ายแก่กองทัพโดยเร็ว\n\nขอบใจ {name} ภารกิจที่สำเร็จอย่างที่เจ้าทำนี่แหละทำให้ชนะสงครามได้จริง" },
        required = { [20559] = { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" } },
        objectiveLabels = {
            item = { ["Arathi Basin Mark of Honor"] = "เหรียญเกียรติยศ Arathi Basin" },
        },
    },
    [8081] = { -- More Resource Crates
        objective = { "114:1921065572:1911428284", "ชนะการรบที่ Arathi Basin รับ Arathi Resource Crate แล้วนำไปให้ Sergeant Maclear ที่ Refuge Pointe" },
        title = { "20:608875181:1075323727", "ลังทรัพยากรเพิ่มเติม" },
        description = { "373:1273676569:386495157 N 118:1649747761:348632480", "สงครามต้องอาศัยทหาร ถามทหารคนไหนก็ได้ และพวกเขาจะบอกด้วยว่าถ้ารบด้วยอุปกรณ์ไม่ดีหรือท้องว่าง ก็แพ้ตั้งแต่ยังไม่เริ่ม!\n\nนี่คือเหตุผลที่อาราธีเบซินสำคัญ พื้นที่ยุทธศาสตร์ในแอ่งนี้มีทรัพยากรจำเป็น ทั้งโลหะ อาวุธ อาหาร และไม้ เราต้องใช้ทั้งหมดและหาได้ที่นั่น\n\nนี่คือสิ่งที่ข้าต้องการจากเจ้า {name} เข้าสู่ Arathi Basin ชนะการรบด้วยการครองฐานมากกว่าศัตรู แล้วนำลังทรัพยากรกลับมาให้ข้า" },
        progress = { "N 130:560960855:1214590122", "{name} สันนิบาตอาราธอร์มีภารกิจให้เจ้ากลับเข้า Arathi Basin เพื่อหาลังทรัพยากรเพิ่มแล้วนำมาให้ข้า" },
        completion = { "151:1306655787:186650910 N 85:1679441708:1464049148", "ดีมาก ข้าจะส่งของให้นายคลังทันที และส่งคำชมเรื่องที่เจ้าทำไปถึงผู้บังคับบัญชาของข้า\n\nขอบใจอีกครั้ง {name} ทุกคนเห็นว่าเจ้าช่วยเราต่อสู้เพียงใด ตั้งแต่ทหารราบไปจนถึงจอมพล" },
    },
    [8105] = { -- The Battle for Arathi Basin!
        title = { "28:1147254842:639956109", "ศึกชิงอาราธีเบซิน!" },
        objective = { "118:1952837946:1204639021", "บุกเหมือง โรงเลื่อย โรงตีเหล็ก และไร่นา แล้วกลับไปหา Field Marshal Oslight ที่ Refuge Pointe" },
        description = { "N 481:420151075:1266952067", "{name} ศึกอาราธีเบซินคือศึกชิงทรัพยากรและดินแดน เราต้องครองจุดสำคัญในพื้นที่และใช้มันจัดหาวัตถุดิบกับเสบียงที่กองทัพขาดอยู่ ข้ามอบหมายให้เจ้าบุกจุดที่ไกลจากฐานของเราในอาราธีเบซินที่สุด\n\nบุกไร่นา เหมือง โรงเลื่อย และโรงตีเหล็กตอนที่ศัตรูควบคุมอยู่ หาธงศัตรูแล้วกระชากลงจากเสา!\n\nเมื่อทำครบทั้งสี่จุดแล้ว กลับมาหาข้า" },
        progress = { "N 89:1889166019:1018321489", "{name} เจ้ายังบุกฐานไม่ครบทั้งสี่แห่ง กลับมาหาข้าเมื่อทำเป้าหมายสำเร็จ" },
        completion = { "53:348145860:578481848 N 116:1316049309:1803566188", "ข้าได้รับรายงานเรื่องที่เจ้าทำในอาราธีเบซินแล้ว {name} ทำได้ดี! เมื่อมีคนอย่างเจ้ามาร่วมต่อสู้ ข้าเชื่อว่าสักวันเราจะชิงบ้านเกิดคืนได้" },
    },
    [8114] = { -- Control Four Bases
        title = { "18:2109845691:999613431", "ควบคุมสี่ฐาน" },
        objective = { "127:1705330711:2146636999", "เข้าสู่ Arathi Basin ยึดและควบคุมสี่ฐานพร้อมกัน แล้วกลับไปหา Field Marshal Oslight ที่ Refuge Pointe" },
        description = { "N 142:74382418:1068434720 C 328:1241572916:718449580 N 19:1930218703:1992436776", "{name} เจ้านำการรบแห่งอาราธีเบซินไปถึงศัตรูและได้รับเกียรติอย่างมากในสนามรบนั้น เจ้าพิสูจน์ฝีมือในฐานะ {class} และแสดงให้ศัตรูเห็นว่าเราจะไม่ยอมจำนนต่อความชั่วร้ายของพวกมัน!\n\nเพราะเจ้าพิสูจน์แล้วว่ามีค่าแก่เรา ข้าจึงมีภารกิจยากให้ทำ ข้าต้องการให้เจ้ายึดและรักษาฐานในอาราธีเบซินไว้อย่างน้อยสี่แห่ง หากทำได้ เราจะได้ทั้งทรัพยากรสำคัญและแสดงให้ฮอร์ดเห็นว่าเราเหนือกว่า!\n\nไปเถิด {name} ขอให้โชคดี" },
        completion = { "16:1923836552:205017918 N 240:586698939:754440300", "ยอดเยี่ยม {name}! หน่วยสอดแนมมารายงานเรื่องที่เจ้าทำด้วยความตื่นเต้น พวกเราในสันนิบาตอาราธอร์ยินดีมาก!\n\nเจ้ากำลังเป็นวีรบุรุษในหมู่ทหารสันนิบาตอย่างรวดเร็ว สิ่งที่ทำวันนี้ยืนยันชื่อเสียงอันดีของเจ้าอีกครั้ง" },
        progress = { "35:65013830:1630751780 N 56:1479116927:522237059", "เจ้ายังยึดไม่ครบสี่ฐาน {name} กลับไปอาราธีเบซินแล้วทำภารกิจที่ได้รับมอบหมายให้สำเร็จ!" },
    },
    [8115] = { -- Control Five Bases
        title = { "18:1812734724:1566868524", "ควบคุมห้าฐาน" },
        objective = { "104:819602435:858282851", "ควบคุมฐาน 5 แห่งใน Arathi Basin พร้อมกัน แล้วกลับไปหา Field Marshal Oslight ที่ Refuge Pointe" },
        description = { "N 407:2027833227:1305324518", "{name} การชิงทรัพยากรแห่งอาราธีเบซินเป็นการรบที่นองเลือด สันนิบาตอาราธอร์ทั้งต้องการและซาบซึ้งในความช่วยเหลือของเจ้า\n\nเรามีอีกหนึ่งงานให้ทำ\n\nสันนิบาตจะเปิดฉากโจมตีครั้งใหญ่ต่อดีไฟเลอร์ที่ยึดอาราธีเบซินอยู่ เราต้องการขับพวกมันออกจากทุกจุดยุทธศาสตร์ในสนามรบ!\n\nไม่ง่ายเลย แต่ถ้ามีใครทำได้ คนนั้นคือเจ้า" },
        completion = { "50:1642653135:889335347 N 223:1898529306:1715666894", "เจ้าทำสำเร็จ! ยึดได้ครบทุกฐานเลย! ทำได้ดีมาก {name}!\n\nบางคนสงสัยว่าเจ้าจะทำได้ไหม แต่ข้ารู้ว่าเจ้าทำได้ ขอบใจเจ้า จงรู้ไว้ว่าสันนิบาตอาราธอร์ยกย่องเจ้าอย่างยิ่ง ส่วนพวกดีไฟเลอร์แห่งฟอร์เซเคนคงหวาดกลัวแม้เพียงได้ยินชื่อเจ้า!" },
        progress = { "41:1749424071:1279492643 N 49:760477344:1110832890", "ภารกิจของเจ้ายังไม่สำเร็จ {name} งานนี้ยาก แต่ข้าเชื่อมั่นในตัวเจ้า" },
    },
    [8120] = { -- The Battle for Arathi Basin!
        title = { "28:1147254842:639956109", "ศึกชิงอาราธีเบซิน!" },
        objective = { "118:1985551462:425017395", "บุกเหมือง โรงเลื่อย โรงตีเหล็ก และคอกม้าใน Arathi Basin แล้วกลับไปหา Deathmaster Dwire ที่ Hammerfall" },
        description = { "449:1520730654:1447006404 N 47:1906317599:1301523278", "เจ้าคงได้ข่าวแล้วว่าสันนิบาตอาราธอร์ส่งกำลังมากมายเข้าอาราธีเบซิน พวกอัลไลแอนซ์โง่เง่ากระหายอาหารและเสบียง คิดจะยึดทรัพยากรอุดมสมบูรณ์ที่นั่นมาครอง เราต้องแสดงให้พวกมันเห็นว่าอาราธีจะไม่เป็นบ้านของมนุษย์อีก!\n\nไปที่ Arathi Basin แล้วบุกเหมือง โรงเลื่อย โรงตีเหล็ก และคอกม้า ดึงธงศัตรูลงเพื่อประกาศว่าดินแดนเหล่านี้เป็นของฮอร์ด\n\nไปเถิด {name} ทำสำเร็จแล้วกลับมารายงานข้า" },
        completion = { "58:1107872830:209288698 N 180:1992863451:517211463", "หน่วยสอดแนมดีไฟเลอร์มารายงานว่าเจ้าทำสำเร็จ {name} ทำได้ดี\n\nเจ้าจะได้เรียนรู้ว่า หากจะชนะศึกอาราธีเบซิน เราต้องเฝ้าระวังอยู่เสมอและบดขยี้ทุกความพยายามที่อัลไลแอนซ์จะขยายอำนาจ ทำเช่นนี้แล้วชัยชนะที่นี่จะเป็นของเราแน่" },
    },
    [8121] = { -- Take Four Bases
        title = { "15:950513234:1302712067", "ยึดสี่ฐาน" },
        objective = { "101:1341170241:259466361", "รักษาสี่ฐานใน Arathi Basin ไว้พร้อมกัน แล้วกลับไปหา Deathmaster Dwire ที่ Hammerfall" },
        description = { "N 446:1669757554:529273467 N 44:1456044953:523187133", "{name} ขณะที่ศึกชิงอาราธีเบซินดุเดือด ข่าวเรื่องที่เจ้าทำแพร่ไปถึงหูคนมากมาย พวกเรานับถือเจ้ามาก ข้าจึงมั่นใจว่าเจ้าจะทำภารกิจที่ข้าจะมอบให้ตอนนี้ได้สำเร็จ\n\nถึงเวลาส่งสารถึงสันนิบาตอาราธอร์ เราต้องแสดงให้พวกมันเห็นว่าฐานที่ครองอยู่ในอาราธีเบซินไม่มั่นคงและเสียไปได้ในพริบตา เราจะแสดงให้เห็นด้วยการครองจุดยุทธศาสตร์สี่จุดในอาราธีเบซินพร้อมกัน\n\nทำให้สำเร็จ {name} แล้วเจ้าจะได้รับความนับถืออย่างสูงในหมู่ดีไฟเลอร์" },
        completion = { "11:354343371:1318038540 N 261:1722818986:33219287", "ทำได้ดี {name}! ภารกิจล่าสุดของเจ้าในอาราธีเบซินยากทีเดียว ความสำเร็จครั้งนี้จึงน่ายกย่องมาก สันนิบาตอาราธอร์คงยังตั้งหลักไม่ติดจากการปะทะครั้งล่าสุดในเบซิน พวกมันคงกำลังถอยไปรักษาแผล และหวังว่าจะคิดใหม่เรื่องมาสู้ที่นี่" },
        progress = { "24:502038937:1086128399 N 82:420431516:140007954", "กลับไปอาราธีเบซิน {name} แล้วทำภารกิจที่ข้าส่งเจ้าไปทำให้สำเร็จ! ยึดสี่ฐานแล้วรักษาไว้ให้ได้!" },
    },
    [8122] = { -- Take Five Bases
        title = { "15:653402267:1869967160", "ยึดห้าฐาน" },
        objective = { "97:1996870534:668585952", "รักษาห้าฐานใน Arathi Basin ไว้พร้อมกัน แล้วกลับไปหา Deathmaster Dwire ที่ Hammerfall" },
        description = { "480:1984116224:881761490", "เราจมอยู่กับการรบจนสังเกตได้ยาก แต่สายของเรารายงานว่าขวัญของสันนิบาตอาราธอร์กำลังอ่อนลง เราต้องฉวยโอกาสนี้โจมตีให้หนัก! กลับเข้า Arathi Basin แล้วโถมเข้าใส่ศัตรู สาปแช่งและสังหารพวกมัน แล้วครองฐานยุทธศาสตร์ทั้งห้าแห่ง! ส่งทหารพวกมันหนีจากแนวหน้าทั้งร้องโหยหวนและเลือดอาบ ให้ปากที่คร่ำครวญของมันเล่าถึงความโหดเหี้ยมของเจ้า\n\nทำเช่นนี้แล้วคว้าชัยครั้งใหญ่ให้ดีไฟเลอร์" },
        completion = { "99:1717192989:610259358 N 281:73864582:1365865706", "เสียงกรีดร้องของฝ่ายอะไลแอนส์ยามที่เจ้าและสหายบุกโจมตีดังมาถึงที่นี่เลย {name} ความเจ็บปวดและความหวาดกลัวที่เจ้าสร้างให้พวกมันทำให้ข้าเกือบจะสงสารอยู่แล้ว เกือบเท่านั้น ยังไม่ถึงกับสงสารหรอก\n\nคุณค่าของเจ้าต่อดีไฟเลอร์ นั้นไม่ต้องสงสัยเลย ผลงานของเจ้าใน Arathi Basin น่าประทับใจอย่างยิ่ง และวีรกรรมของเจ้าก็เลื่องลือไปถึงห้องโถงของ Varimathras... และองค์ Dark Lady เองด้วย" },
    },
    [8123] = { -- Cut Arathor Supply Lines
        title = { "24:282671723:1823308482", "ตัดเส้นทางเสบียงของอาราธอร์" },
        objective = { "114:827605890:314122326", "ชนะการรบที่ Arathi Basin รับ Arathi Resource Crate แล้วนำไปให้ Deathstalker Mortis ที่ Hammerfall" },
        description = { "298:158734770:280274083 N 189:521971321:80227811", "สันนิบาตอาราธอร์ทุ่มสุดตัวเพื่อชิงอาราธีคืน พวกมันและทุกเผ่าของอัลไลแอนซ์กำลังหลั่งไหลมายังดินแดนไกลแห่งนี้ หวังขยายพื้นที่จาก Refuge Pointe เราต้องหยุดพวกมัน และวิธีที่ดีที่สุดคือยึดเสบียงของมัน\n\nเจ้าช่วยเราได้ {name} เข้าสู่ Arathi Basin ที่ขึ้นชื่อเรื่องเหมืองอุดมสมบูรณ์ ผืนดินอุดม และช่างฝีมือ ยึดและครองทุกฐานที่ทำได้ ชนะการรบ แล้วนำ Mark of Honor ที่ได้กลับมาให้ข้า", variants = { { "298:158734770:280274083 N 185:139564079:2003354093", "สันนิบาตอาราธอร์ทุ่มสุดตัวเพื่อชิงอาราธีคืน พวกมันและทุกเผ่าของอัลไลแอนซ์กำลังหลั่งไหลมายังดินแดนไกลแห่งนี้ หวังขยายพื้นที่จาก Refuge Pointe เราต้องหยุดพวกมัน และวิธีที่ดีที่สุดคือยึดเสบียงของมัน\n\nเจ้าช่วยเราได้ {name} เข้าสู่ Arathi Basin ที่ขึ้นชื่อเรื่องเหมืองอุดมสมบูรณ์ ผืนดินอุดม และช่างฝีมือ ยึดและครองทุกฐานที่ทำได้ ชนะการรบ แล้วนำ ทรัพยากร ที่ได้กลับมาให้ข้า" } } },
        progress = { "12:351164566:2103200252 R 141:2147270865:803116902", "มีอะไร {race}? เจ้าได้ Mark of Honor มาหรือยัง? กลับเข้า Arathi Basin สังหารพวกสวะอัลไลแอนซ์ และยึดทรัพยากรที่นั่นให้เลดี้แห่งความมืด!" },
        completion = { "87:409670119:2120225246 N 81:973186240:497735540", "<เดธสตอล์กเกอร์มอร์ทิสยิ้ม>\n\nเราโจมตีศัตรูอย่างได้ผลอีกครั้งแล้ว {name} เพราะสิ่งที่เจ้าทำ อีกไม่นานอาราธีเบซินจะตกอยู่ในมือดีไฟเลอร์" },
        required = { [20559] = { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" } },
        objectiveLabels = {
            item = { ["Arathi Basin Mark of Honor"] = "เหรียญเกียรติยศ Arathi Basin" },
        },
    },
    [8124] = { -- More Resource Crates
        title = { "20:608875181:1075323727", "ลังทรัพยากรเพิ่มเติม" },
        objective = { "114:827605890:314122326", "ชนะการรบที่ Arathi Basin รับ Arathi Resource Crate แล้วนำไปให้ Deathstalker Mortis ที่ Hammerfall" },
        description = { "298:158734770:280274083 N 185:139564079:2003354093", "สันนิบาตอาราธอร์ทุ่มสุดตัวเพื่อชิงอาราธีคืน พวกมันและทุกเผ่าของอัลไลแอนซ์กำลังหลั่งไหลมายังดินแดนไกลแห่งนี้ หวังขยายพื้นที่จาก Refuge Pointe เราต้องหยุดพวกมัน และวิธีที่ดีที่สุดคือยึดเสบียงของมัน\n\nเจ้าช่วยเราได้ {name} เข้าสู่ Arathi Basin ที่ขึ้นชื่อเรื่องเหมืองอุดมสมบูรณ์ ผืนดินอุดม และช่างฝีมือ ยึดและครองทุกฐานที่ทำได้ ชนะการรบ แล้วนำทรัพยากรที่ได้กลับมาให้ข้า" },
        progress = { "N 121:462582600:1011294196", "{name} ดีไฟเลอร์มีภารกิจให้เจ้ากลับเข้า Arathi Basin เพื่อหาลังทรัพยากรเพิ่มแล้วนำมาให้ข้า" },
        completion = { "151:1306655787:186650910 N 82:105406399:216488210", "ดีมาก ข้าจะส่งของให้นายคลังทันที และส่งคำชมเรื่องที่เจ้าทำไปถึงผู้บังคับบัญชาของข้า\n\nขอบใจอีกครั้ง {name} ทุกคนเห็นว่าเจ้าช่วยเราต่อสู้เพียงใด ตั้งแต่ทหารกรันต์ไปจนถึงมหาขุนศึก" },
    },
    [8154] = { -- Arathi Basin Resources!
        title = { "23:1607010962:2075543507", "ทรัพยากรแห่งอาราธีเบซิน!" },
        objective = { "114:1921065572:1911428284", "ชนะการรบที่ Arathi Basin รับ Arathi Resource Crate แล้วนำไปให้ Sergeant Maclear ที่ Refuge Pointe" },
        description = { "373:1273676569:386495157 N 113:360552461:671051154", "สงครามต้องอาศัยทหาร ถามทหารคนไหนก็ได้ และพวกเขาจะบอกด้วยว่าถ้ารบด้วยอุปกรณ์ไม่ดีหรือท้องว่าง ก็แพ้ตั้งแต่ยังไม่เริ่ม!\n\nนี่คือเหตุผลที่อาราธีเบซินสำคัญ พื้นที่ยุทธศาสตร์ในแอ่งนี้มีทรัพยากรจำเป็น ทั้งโลหะ อาวุธ อาหาร และไม้ เราต้องใช้ทั้งหมดและหาได้ที่นั่น\n\nนี่คือสิ่งที่ข้าต้องการจากเจ้า {name} เข้าสู่ Arathi Basin ชนะการรบด้วยการครองฐานมากกว่าศัตรู แล้วนำ Mark of Honor กลับมาให้ข้า" },
        progress = { "32:119972586:1384428818 N 67:1794564808:1973746598", "เจ้าได้ Mark of Honor มาหรือยัง {name}? สันนิบาตอาราธอร์รบให้ดีไม่ได้หากขาดมัน..." },
        completion = { "133:1288952087:502684611 N 94:852723070:35116513", "เจ้าได้ตรามาแล้ว! ทำได้ดีมาก! ข้าจะส่งเสบียงไปให้นายคลังแจกจ่ายแก่กองทัพโดยเร็ว\n\nขอบใจ {name} ภารกิจที่สำเร็จอย่างที่เจ้าทำนี่แหละทำให้ชนะสงครามได้จริง" },
        required = { [20559] = { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" } },
        objectiveLabels = {
            item = { ["Arathi Basin Mark of Honor"] = "เหรียญเกียรติยศ Arathi Basin" },
        },
    },
    [8155] = { -- Arathi Basin Resources!
        title = { "23:1607010962:2075543507", "ทรัพยากรแห่งอาราธีเบซิน!" },
        objective = { "114:1921065572:1911428284", "ชนะการรบที่ Arathi Basin รับ Arathi Resource Crate แล้วนำไปให้ Sergeant Maclear ที่ Refuge Pointe" },
        description = { "373:1273676569:386495157 N 113:360552461:671051154", "สงครามต้องอาศัยทหาร ถามทหารคนไหนก็ได้ และพวกเขาจะบอกด้วยว่าถ้ารบด้วยอุปกรณ์ไม่ดีหรือท้องว่าง ก็แพ้ตั้งแต่ยังไม่เริ่ม!\n\nนี่คือเหตุผลที่อาราธีเบซินสำคัญ พื้นที่ยุทธศาสตร์ในแอ่งนี้มีทรัพยากรจำเป็น ทั้งโลหะ อาวุธ อาหาร และไม้ เราต้องใช้ทั้งหมดและหาได้ที่นั่น\n\nนี่คือสิ่งที่ข้าต้องการจากเจ้า {name} เข้าสู่ Arathi Basin ชนะการรบด้วยการครองฐานมากกว่าศัตรู แล้วนำ Mark of Honor กลับมาให้ข้า", variants = { { "373:1273676569:386495157 N 118:1649747761:348632480", "สงครามต้องอาศัยทหาร ถามทหารคนไหนก็ได้ และพวกเขาจะบอกด้วยว่าถ้ารบด้วยอุปกรณ์ไม่ดีหรือท้องว่าง ก็แพ้ตั้งแต่ยังไม่เริ่ม!\n\nนี่คือเหตุผลที่อาราธีเบซินสำคัญ พื้นที่ยุทธศาสตร์ในแอ่งนี้มีทรัพยากรจำเป็น ทั้งโลหะ อาวุธ อาหาร และไม้ เราต้องใช้ทั้งหมดและหาได้ที่นั่น\n\nนี่คือสิ่งที่ข้าต้องการจากเจ้า {name} เข้าสู่ Arathi Basin ชนะการรบด้วยการครองฐานมากกว่าศัตรู แล้วนำลังทรัพยากรกลับมาให้ข้า" } } },
        progress = { "32:119972586:1384428818 N 67:1794564808:1973746598", "เจ้าได้ Mark of Honor มาหรือยัง {name}? สันนิบาตอาราธอร์รบให้ดีไม่ได้หากขาดมัน..." },
        completion = { "133:1288952087:502684611 N 94:852723070:35116513", "เจ้าได้ตรามาแล้ว! ทำได้ดีมาก! ข้าจะส่งเสบียงไปให้นายคลังแจกจ่ายแก่กองทัพโดยเร็ว\n\nขอบใจ {name} ภารกิจที่สำเร็จอย่างที่เจ้าทำนี่แหละทำให้ชนะสงครามได้จริง" },
