        description = { "298:158734770:280274083 N 189:521971321:80227811", "สันนิบาตอาราธอร์ทุ่มสุดตัวเพื่อชิงอาราธีคืน พวกมันและทุกเผ่าของอัลไลแอนซ์กำลังหลั่งไหลมายังดินแดนไกลแห่งนี้ หวังขยายพื้นที่จาก Refuge Pointe เราต้องหยุดพวกมัน และวิธีที่ดีที่สุดคือยึดเสบียงของมัน\n\nเจ้าช่วยเราได้ {name} เข้าสู่ Arathi Basin ที่ขึ้นชื่อเรื่องเหมืองอุดมสมบูรณ์ ผืนดินอุดม และช่างฝีมือ ยึดและครองทุกฐานที่ทำได้ ชนะการรบ แล้วนำ Mark of Honor ที่ได้กลับมาให้ข้า", variants = { { "298:158734770:280274083 N 185:139564079:2003354093", "สันนิบาตอาราธอร์ทุ่มสุดตัวเพื่อชิงอาราธีคืน พวกมันและทุกเผ่าของอัลไลแอนซ์กำลังหลั่งไหลมายังดินแดนไกลแห่งนี้ หวังขยายพื้นที่จาก Refuge Pointe เราต้องหยุดพวกมัน และวิธีที่ดีที่สุดคือยึดเสบียงของมัน\n\nเจ้าช่วยเราได้ {name} เข้าสู่ Arathi Basin ที่ขึ้นชื่อเรื่องเหมืองอุดมสมบูรณ์ ผืนดินอุดม และช่างฝีมือ ยึดและครองทุกฐานที่ทำได้ ชนะการรบ แล้วนำทรัพยากรที่ได้กลับมาให้ข้า" } } },
        progress = { "12:351164566:2103200252 R 141:2147270865:803116902", "มีอะไร {race}? เจ้าได้ Mark of Honor มาหรือยัง? กลับเข้า Arathi Basin สังหารพวกสวะอัลไลแอนซ์ และยึดทรัพยากรที่นั่นให้เลดี้แห่งความมืด!" },
        completion = { "87:409670119:2120225246 N 81:973186240:497735540", "<เดธสตอล์กเกอร์มอร์ทิสยิ้ม>\n\nเราโจมตีศัตรูอย่างได้ผลอีกครั้งแล้ว {name} เพราะสิ่งที่เจ้าทำ อีกไม่นานอาราธีเบซินจะตกอยู่ในมือดีไฟเลอร์" },
        required = { [20559] = { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" } },
        steps = { { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" } },
    },
