    },
    [8169] = { -- The Battle for Arathi Basin!
        title = { "28:1147254842:639956109", "ศึกชิงอาราธีเบซิน!" },
        objective = { "118:1985551462:425017395", "บุกเหมือง โรงเลื่อย โรงตีเหล็ก และคอกม้าใน Arathi Basin แล้วกลับไปหา Deathmaster Dwire ที่ Hammerfall" },
        description = { "449:1520730654:1447006404 N 47:1906317599:1301523278", "เจ้าคงได้ข่าวแล้วว่าสันนิบาตอาราธอร์ส่งกำลังมากมายเข้าอาราธีเบซิน พวกอัลไลแอนซ์โง่เง่ากระหายอาหารและเสบียง คิดจะยึดทรัพยากรอุดมสมบูรณ์ที่นั่นมาครอง เราต้องแสดงให้พวกมันเห็นว่าอาราธีจะไม่เป็นบ้านของมนุษย์อีก!\n\nไปที่ Arathi Basin แล้วบุกเหมือง โรงเลื่อย โรงตีเหล็ก และคอกม้า ดึงธงศัตรูลงเพื่อประกาศว่าดินแดนเหล่านี้เป็นของฮอร์ด\n\nไปเถิด {name} ทำสำเร็จแล้วกลับมารายงานข้า" },
        completion = { "58:1107872830:209288698 N 180:1992863451:517211463", "หน่วยสอดแนมดีไฟเลอร์มารายงานว่าเจ้าทำสำเร็จ {name} ทำได้ดี\n\nเจ้าจะได้เรียนรู้ว่า หากจะชนะศึกอาราธีเบซิน เราต้องเฝ้าระวังอยู่เสมอและบดขยี้ทุกความพยายามที่อัลไลแอนซ์จะขยายอำนาจ ทำเช่นนี้แล้วชัยชนะที่นี่จะเป็นของเราแน่" },
        steps = { { "14:785596057:1180095562", "บุกเหมือง" }, { "21:740554802:1188731340", "บุกโรงเลื่อย" }, { "20:1340402712:65133973", "บุกโรงตีเหล็ก" }, { "16:1452396049:581388092", "บุกคอกม้า" } },
    },
    [8170] = { -- The Battle for Arathi Basin!
        title = { "28:1147254842:639956109", "ศึกชิงอาราธีเบซิน!" },
        objective = { "118:1985551462:425017395", "บุกเหมือง โรงเลื่อย โรงตีเหล็ก และคอกม้าใน Arathi Basin แล้วกลับไปหา Deathmaster Dwire ที่ Hammerfall" },
        description = { "449:1520730654:1447006404 N 47:1906317599:1301523278", "เจ้าคงได้ข่าวแล้วว่าสันนิบาตอาราธอร์ส่งกำลังมากมายเข้าอาราธีเบซิน พวกอัลไลแอนซ์โง่เง่ากระหายอาหารและเสบียง คิดจะยึดทรัพยากรอุดมสมบูรณ์ที่นั่นมาครอง เราต้องแสดงให้พวกมันเห็นว่าอาราธีจะไม่เป็นบ้านของมนุษย์อีก!\n\nไปที่ Arathi Basin แล้วบุกเหมือง โรงเลื่อย โรงตีเหล็ก และคอกม้า ดึงธงศัตรูลงเพื่อประกาศว่าดินแดนเหล่านี้เป็นของฮอร์ด\n\nไปเถิด {name} ทำสำเร็จแล้วกลับมารายงานข้า" },
        completion = { "58:1107872830:209288698 N 180:1992863451:517211463", "หน่วยสอดแนมดีไฟเลอร์มารายงานว่าเจ้าทำสำเร็จ {name} ทำได้ดี\n\nเจ้าจะได้เรียนรู้ว่า หากจะชนะศึกอาราธีเบซิน เราต้องเฝ้าระวังอยู่เสมอและบดขยี้ทุกความพยายามที่อัลไลแอนซ์จะขยายอำนาจ ทำเช่นนี้แล้วชัยชนะที่นี่จะเป็นของเราแน่" },
        progress = { "41:1363863599:1112692013 N 91:250762134:1787534845", "เจ้ายังทำภารกิจไม่สำเร็จ {name} จงบุกฐานทั้งสี่ที่ข้าบอก แล้วค่อยกลับมาหาข้า!" },
        steps = { { "14:785596057:1180095562", "บุกเหมือง" }, { "21:740554802:1188731340", "บุกโรงเลื่อย" }, { "20:1340402712:65133973", "บุกโรงตีเหล็ก" }, { "16:1452396049:581388092", "บุกคอกม้า" } },
    },
    [8171] = { -- The Battle for Arathi Basin!
        title = { "28:1147254842:639956109", "ศึกชิงอาราธีเบซิน!" },
        objective = { "118:1985551462:425017395", "บุกเหมือง โรงเลื่อย โรงตีเหล็ก และคอกม้าใน Arathi Basin แล้วกลับไปหา Deathmaster Dwire ที่ Hammerfall" },
        description = { "449:1520730654:1447006404 N 47:1906317599:1301523278", "เจ้าคงได้ข่าวแล้วว่าสันนิบาตอาราธอร์ส่งกำลังมากมายเข้าอาราธีเบซิน พวกอัลไลแอนซ์โง่เง่ากระหายอาหารและเสบียง คิดจะยึดทรัพยากรอุดมสมบูรณ์ที่นั่นมาครอง เราต้องแสดงให้พวกมันเห็นว่าอาราธีจะไม่เป็นบ้านของมนุษย์อีก!\n\nไปที่ Arathi Basin แล้วบุกเหมือง โรงเลื่อย โรงตีเหล็ก และคอกม้า ดึงธงศัตรูลงเพื่อประกาศว่าดินแดนเหล่านี้เป็นของฮอร์ด\n\nไปเถิด {name} ทำสำเร็จแล้วกลับมารายงานข้า" },
        completion = { "58:1107872830:209288698 N 180:1992863451:517211463", "หน่วยสอดแนมดีไฟเลอร์มารายงานว่าเจ้าทำสำเร็จ {name} ทำได้ดี\n\nเจ้าจะได้เรียนรู้ว่า หากจะชนะศึกอาราธีเบซิน เราต้องเฝ้าระวังอยู่เสมอและบดขยี้ทุกความพยายามที่อัลไลแอนซ์จะขยายอำนาจ ทำเช่นนี้แล้วชัยชนะที่นี่จะเป็นของเราแน่" },
        steps = { { "14:785596057:1180095562", "บุกเหมือง" }, { "21:740554802:1188731340", "บุกโรงเลื่อย" }, { "20:1340402712:65133973", "บุกโรงตีเหล็ก" }, { "16:1452396049:581388092", "บุกคอกม้า" } },
    },
    [8260] = { -- Arathor Basic Care Package
        title = { "26:1718912525:250818753", "ชุดเสบียงพื้นฐานของอาราธอร์" },
        completion = { "48:210844649:134717484 N 345:2132657580:1836019944", "เจ้าเริ่มพิสูจน์คุณค่าต่อเราแล้วจริง ๆ {name} รับชุดเสบียงนี้เป็นรางวัลเถิด ในนั้นมีอาหารปันส่วนกับผ้าพันแผลที่ใช้ได้เฉพาะใน Arathi Basin\n\nหากยังพิสูจน์ตัวเองในสนามรบต่อไป เจ้าจะซื้อของเหล่านี้ได้ เมื่อชื่อเสียงกับเราถึง Friendly จะซื้ออาหารปันส่วนได้ และเมื่อถึง Honored จะซื้อผ้าพันแผลได้" },
