    [8297] = { -- Arathi Basin Resources!
        title = { "23:1607010962:2075543507", "ทรัพยากรแห่งอาราธีเบซิน!" },
        objective = { "114:1921065572:1911428284", "ชนะการรบที่ Arathi Basin รับ Arathi Resource Crate แล้วนำไปให้ Sergeant Maclear ที่ Refuge Pointe" },
        description = { "373:1273676569:386495157 N 113:360552461:671051154", "สงครามต้องอาศัยทหาร ถามทหารคนไหนก็ได้ และพวกเขาจะบอกด้วยว่าถ้ารบด้วยอุปกรณ์ไม่ดีหรือท้องว่าง ก็แพ้ตั้งแต่ยังไม่เริ่ม!\n\nนี่คือเหตุผลที่อาราธีเบซินสำคัญ พื้นที่ยุทธศาสตร์ในแอ่งนี้มีทรัพยากรจำเป็น ทั้งโลหะ อาวุธ อาหาร และไม้ เราต้องใช้ทั้งหมดและหาได้ที่นั่น\n\nนี่คือสิ่งที่ข้าต้องการจากเจ้า {name} เข้าสู่ Arathi Basin ชนะการรบด้วยการครองฐานมากกว่าศัตรู แล้วนำ Mark of Honor กลับมาให้ข้า", variants = { { "373:1273676569:386495157 N 118:1649747761:348632480", "สงครามต้องอาศัยทหาร ถามทหารคนไหนก็ได้ และพวกเขาจะบอกด้วยว่าถ้ารบด้วยอุปกรณ์ไม่ดีหรือท้องว่าง ก็แพ้ตั้งแต่ยังไม่เริ่ม!\n\nนี่คือเหตุผลที่อาราธีเบซินสำคัญ พื้นที่ยุทธศาสตร์ในแอ่งนี้มีทรัพยากรจำเป็น ทั้งโลหะ อาวุธ อาหาร และไม้ เราต้องใช้ทั้งหมดและหาได้ที่นั่น\n\nนี่คือสิ่งที่ข้าต้องการจากเจ้า {name} เข้าสู่ Arathi Basin ชนะการรบด้วยการครองฐานมากกว่าศัตรู แล้วนำลังทรัพยากรกลับมาให้ข้า" } } },
        progress = { "32:119972586:1384428818 N 67:1794564808:1973746598", "เจ้าได้ Mark of Honor มาหรือยัง {name}? สันนิบาตอาราธอร์รบให้ดีไม่ได้หากขาดมัน..." },
        completion = { "133:1288952087:502684611 N 94:852723070:35116513", "เจ้าได้ตรามาแล้ว! ทำได้ดีมาก! ข้าจะส่งเสบียงไปให้นายคลังแจกจ่ายแก่กองทัพโดยเร็ว\n\nขอบใจ {name} ภารกิจที่สำเร็จอย่างที่เจ้าทำนี่แหละทำให้ชนะสงครามได้จริง" },
        required = { [20559] = { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" } },
        objectiveLabels = {
            item = { ["Arathi Basin Mark of Honor"] = "เหรียญเกียรติยศ Arathi Basin" },
        },
    },
    [8298] = { -- More Resource Crates
        objective = { "114:1921065572:1911428284", "ชนะการรบที่ Arathi Basin รับ Arathi Resource Crate แล้วนำไปให้ Sergeant Maclear ที่ Refuge Pointe" },
        title = { "20:608875181:1075323727", "ลังทรัพยากรเพิ่มเติม" },
        completion = { "151:1306655787:186650910 N 85:1679441708:1464049148", "ดีมาก ข้าจะส่งของให้นายคลังทันที และส่งคำชมเรื่องที่เจ้าทำไปถึงผู้บังคับบัญชาของข้า\n\nขอบใจอีกครั้ง {name} ทุกคนเห็นว่าเจ้าช่วยเราต่อสู้เพียงใด ตั้งแต่ทหารราบไปจนถึงจอมพล" },
        progress = { "N 129:2128129235:2015477572", "{name} สันนิบาตอาราธอร์มีภารกิจให้เจ้ากลับเข้า Arathi Basin เพื่อหา Mark of Honor เพิ่มแล้วนำมาให้ข้า" },
        description = { "N 130:560960855:1214590122", "{name} ภารกิจที่ League of Arathor มอบหมายให้เจ้ายังดำเนินอยู่ จงกลับเข้า Arathi Basin จัดหาลังเสบียงเพิ่มแล้วนำมาให้ข้า" },
    },
    [8299] = { -- Cut Arathor Supply Lines
        title = { "24:282671723:1823308482", "ตัดเส้นทางเสบียงของอาราธอร์" },
        objective = { "114:827605890:314122326", "ชนะการรบที่ Arathi Basin รับ Arathi Resource Crate แล้วนำไปให้ Deathstalker Mortis ที่ Hammerfall" },
        description = { "298:158734770:280274083 N 189:521971321:80227811", "สันนิบาตอาราธอร์ทุ่มสุดตัวเพื่อชิงอาราธีคืน พวกมันและทุกเผ่าของอัลไลแอนซ์กำลังหลั่งไหลมายังดินแดนไกลแห่งนี้ หวังขยายพื้นที่จาก Refuge Pointe เราต้องหยุดพวกมัน และวิธีที่ดีที่สุดคือยึดเสบียงของมัน\n\nเจ้าช่วยเราได้ {name} เข้าสู่ Arathi Basin ที่ขึ้นชื่อเรื่องเหมืองอุดมสมบูรณ์ ผืนดินอุดม และช่างฝีมือ ยึดและครองทุกฐานที่ทำได้ ชนะการรบ แล้วนำ Mark of Honor ที่ได้กลับมาให้ข้า", variants = { { "298:158734770:280274083 N 185:139564079:2003354093", "สันนิบาตอาราธอร์ทุ่มสุดตัวเพื่อชิงอาราธีคืน พวกมันและทุกเผ่าของอัลไลแอนซ์กำลังหลั่งไหลมายังดินแดนไกลแห่งนี้ หวังขยายพื้นที่จาก Refuge Pointe เราต้องหยุดพวกมัน และวิธีที่ดีที่สุดคือยึดเสบียงของมัน\n\nเจ้าช่วยเราได้ {name} เข้าสู่ Arathi Basin ที่ขึ้นชื่อเรื่องเหมืองอุดมสมบูรณ์ ผืนดินอุดม และช่างฝีมือ ยึดและครองทุกฐานที่ทำได้ ชนะการรบ แล้วนำทรัพยากรที่ได้กลับมาให้ข้า" } } },
        progress = { "12:351164566:2103200252 R 141:2147270865:803116902", "มีอะไร {race}? เจ้าได้ Mark of Honor มาหรือยัง? กลับเข้า Arathi Basin สังหารพวกสวะอัลไลแอนซ์ และยึดทรัพยากรที่นั่นให้เลดี้แห่งความมืด!" },
        completion = { "87:409670119:2120225246 N 81:973186240:497735540", "<เดธสตอล์กเกอร์มอร์ทิสยิ้ม>\n\nเราโจมตีศัตรูอย่างได้ผลอีกครั้งแล้ว {name} เพราะสิ่งที่เจ้าทำ อีกไม่นานอาราธีเบซินจะตกอยู่ในมือดีไฟเลอร์" },
        required = { [20559] = { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" } },
        objectiveLabels = {
            item = { ["Arathi Basin Mark of Honor"] = "เหรียญเกียรติยศ Arathi Basin" },
        },
    },
    [8300] = { -- More Resource Crates
        title = { "20:608875181:1075323727", "ลังทรัพยากรเพิ่มเติม" },
        objective = { "114:827605890:314122326", "ชนะการรบที่ Arathi Basin รับ Arathi Resource Crate แล้วนำไปให้ Deathstalker Mortis ที่ Hammerfall" },
        completion = { "151:1306655787:186650910 N 82:105406399:216488210", "ดีมาก ข้าจะส่งของให้นายคลังทันที และส่งคำชมเรื่องที่เจ้าทำไปถึงผู้บังคับบัญชาของข้า\n\nขอบใจอีกครั้ง {name} ทุกคนเห็นว่าเจ้าช่วยเราต่อสู้เพียงใด ตั้งแต่ทหารกรันต์ไปจนถึงมหาขุนศึก" },
        progress = { "N 120:1812614877:1942233621", "{name} ดีไฟเลอร์มีภารกิจให้เจ้ากลับเข้า Arathi Basin เพื่อหา Mark of Honor เพิ่มแล้วนำมาให้ข้า" },
        description = { "259:1498018340:895364474", "แม้พวก Defilers จะตัดเส้นทางส่งเสบียงของ League of Arathor ได้สำเร็จ แต่ฝ่าย Alliance ก็ยังดื้อดึงจะเอา Arathi Basin ให้ได้ เราต้องส่งทหารของเราเข้าไปในแอ่งนั้นต่อ และนำลังเสบียงของพวกเขากลับมาเพิ่ม" },
    },
    [8370] = { -- Conquering Arathi Basin
        title = { "23:1802933530:1002445345", "พิชิตอาราธีเบซิน" },
        objective = { "83:2018091711:1259223394", "นำ Arathi Basin Mark of Honor 3 ชิ้นไปให้ Horde Warbringer ที่อยู่นอกสนามรบ" },
        description = { "410:1898339034:126611783 N 1:33:33", "ความขัดแย้งกับอัลไลแอนซ์ลุกลามเป็นสงครามเต็มตัว ตอนนี้ทั้งสองฝ่ายต่างไม่ใช้หรือคาดหวังข้ออ้างบังหน้าเพื่อเข้ารบอีกแล้ว\n\nศึกอาราธีเบซินคือศึกชิงทรัพยากร เรื่องก็มีเพียงเท่านี้ หากอัลไลแอนซ์ได้ไป พวกมันจะใช้เล่นงานเรา หากเราได้ เราจะใช้เดินหน้าทำสงครามต่อ จงช่วยดีไฟเลอร์ให้มีทรัพยากรที่ต้องใช้ส่งมาไม่ขาด {name}!" },
        progress = { "40:991863340:952213534 C 1:63:63", "เจ้ากลับมาพร้อมข่าวจากอาราธีหรือ {class}?" },
        completion = { "73:2067755263:1954280850 N 1:46:46", "การรักษาทรัพยากรของเราในอาราธีเป็นงานสำคัญ! เจ้าทำได้ดี {name}" },
        required = { [20559] = { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" } },
        steps = { { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" } },
    },
