        description = { "410:1898339034:126611783 N 1:33:33", "ความขัดแย้งกับอัลไลแอนซ์ลุกลามเป็นสงครามเต็มตัว ตอนนี้ทั้งสองฝ่ายต่างไม่ใช้หรือคาดหวังข้ออ้างบังหน้าเพื่อเข้ารบอีกแล้ว\n\nศึกอาราธีเบซินคือศึกชิงทรัพยากร เรื่องก็มีเพียงเท่านี้ หากอัลไลแอนซ์ได้ไป พวกมันจะใช้เล่นงานเรา หากเราได้ เราจะใช้เดินหน้าทำสงครามต่อ จงช่วยดีไฟเลอร์ให้มีทรัพยากรที่ต้องใช้ส่งมาไม่ขาด {name}!" },
        progress = { "40:991863340:952213534 C 1:63:63", "เจ้ากลับมาพร้อมข่าวจากอาราธีหรือ {class}?" },
        completion = { "73:2067755263:1954280850 N 1:46:46", "การรักษาทรัพยากรของเราในอาราธีเป็นงานสำคัญ! เจ้าทำได้ดี {name}" },
        required = { [20559] = { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" } },
        steps = { { "26:1810744787:1947684480", "เหรียญเกียรติยศ Arathi Basin" } },
    },
