    [8041] = { -- Strength of Mount Mugamba
        title = { "25:1454782110:1838024776", "พลังแห่งภูเขามูกัมบา" },
        completion = { "6:1136836709:1914036474 C 187:640685400:246523591 C 105:1306585213:145874910", "สวัสดี {class} ข้าคือจินร็อกห์ผู้บดขยี้ โทรลล์แห่งมูกัมบา พวกเราเผ่าแซนดาลาร์รับรู้ถึงความสำเร็จของเจ้า ขอคารวะความทรหดและใจอันแน่วแน่\n\nสวมเครื่องรางนี้ไว้ที่คอ {class} ให้พลังแห่งภูเขามูกัมบาไหลผ่านตัวเจ้า จงใช้พลังนี้ฟาดฟันศัตรูของเรา!" },
    },
    [8042] = { -- Strength of Mount Mugamba
        title = { "25:1454782110:1838024776", "พลังแห่งภูเขามูกัมบา" },
        progress = { "38:2102680783:1908667958 N 293:144976137:380054852", "ดีที่เห็นเจ้ายังแข็งแรง {name} ศึกอันรุ่งโรจน์ที่เจ้าร่วมรบส่งผลต่อทุกชีวิตบนโลก ฮักการ์จะออกจากซุลกูรูบไม่ได้เด็ดขาด เพราะความหิวโหยมหาศาลของมันจะทำให้โลกล่มสลาย\n\nส่งเครื่องรางของเจ้ามา ข้าจะเสริมพลังให้ ใช้พลังแห่งมูกัมบาลงทัณฑ์ศัตรูของเรา!" },
        completion = { "28:697402118:160118663 C 1:46:46", "เราคงได้พบกันอีก {class}" },
        required = { [19574] = { "19:105048540:853052357", "พลังแห่ง Mugamba" } },
        objectiveLabels = {
            item = { ["Strength of Mugamba"] = "พลังแห่ง Mugamba" },
        },
    },
    [8043] = { -- Strength of Mount Mugamba
        title = { "25:1454782110:1838024776", "พลังแห่งภูเขามูกัมบา" },
        progress = { "7:459703642:425541723 N 146:1818066138:966347258 C 89:1279659826:1754111506", "ท่าน {name} กลับมาแล้ว! มอลธอร์ส่งข่าวเรื่องวีรกรรมของเจ้าไปถึงกษัตริย์ ชื่อของเจ้าเป็นที่รู้จักแม้แต่ในทะเลใต้ บางทีสักวันเจ้าอาจเป็น {class} ในตำนานที่คนเล่าขานไปอีกหลายยุค\n\nส่งเครื่องรางมาให้ข้า จะได้เสริมพลังให้อีกครั้ง" },
        completion = { "52:798146547:1507018937", "ใช้พลังที่เพิ่งได้รับทำลายกูรูบาชิเสีย!" },
        required = { [19575] = { "19:105048540:853052357", "พลังแห่ง Mugamba" } },
        objectiveLabels = {
            item = { ["Strength of Mugamba"] = "พลังแห่ง Mugamba" },
        },
    },
    [8044] = { -- The Rage of Mugamba
        title = { "19:1022835784:614066888", "โทสะแห่งมูกัมบา" },
        progress = { "41:674981150:1978186852 N 226:116542421:473719268", "กษัตริย์รัสตาคานฝากคำทักทายมา ท่าน {name} ผู้ที่อยู่นอกเผ่าแซนดาลาร์ไม่เคยได้รับเกียรติเช่นนี้มาก่อน\n\n<จินร็อกห์โค้งคำนับ>\n\nส่งเครื่องรางมาให้ข้า จะได้เพิ่มพลังอีกครั้ง จงรู้ไว้ว่าโทสะแห่งมูกัมบาผูกอยู่กับวิญญาณของเจ้าแล้ว" },
        completion = { "26:1350519619:1549944552 C 23:1916863588:1604408743", "ซุลจินคงอิจฉา {class} ออกไปคว้าชัยเถิด!" },
        required = { [19576] = { "19:105048540:853052357", "พลังแห่ง Mugamba" } },
        objectiveLabels = {
            item = { ["Strength of Mugamba"] = "พลังแห่ง Mugamba" },
        },
    },
    [8045] = { -- The Heathen's Brand
