    [8053] = { -- Paragons of Power: The Freethinker's Armguards
        title = { "46:290726082:1169821797", "เครื่องหมายแห่งพลัง — ปลอกแขนของผู้คิดอิสระ" },
        objective = { "211:1848449092:1568896525", "นำ Primal Hakkari Bindings ไปให้ Jin'rokh the Breaker และต้องมีชื่อเสียงกับ Zandalar Tribe ระดับ Friendly ขึ้นไป\n\nJin'rokh the Breaker อยู่ที่ Yojamba Isle ใน Stranglethorn Vale" },
        description = { "477:2008334515:724302249", "เจ้าเป็นคนนอกศรัทธา คนแบบเจ้ามีที่ทางในเผ่า พวกเขาคือผู้คิดอิสระแห่งแซนดาลาร์ ผู้คิดอิสระไม่กลัวการกดขี่ และยอมตายเพื่อสิ่งที่ตนเชื่อ เรารู้ว่าเจ้าก็ยอมตายเพื่อความเชื่อของเจ้า นั่นทำให้เรายอมรับ และให้โอกาสเจ้าพิสูจน์ตัวเองต่อ\n\nเราต้องได้เครื่องหมายแห่งพลัง ไปซุลกูรูบ สังหารสมุนฮักการ์ กลับมาเมื่อได้สิ่งที่ข้าตามหา แล้วรับอุปกรณ์รบชิ้นแรกของผู้คิดอิสระแห่งแซนดาลาร์\n\nไปเถิด" },
        progress = { "99:1270398635:27377427", "เจ้ากลับมาแล้วหรือ? ได้เครื่องหมายแห่งพลังมาหรือยัง? เจ้ากำลังทำให้ข้าเสียเวลาหรือเปล่า?\n\nหวังว่าจะไม่ คนนอกศรัทธา" },
        completion = { "203:576171305:1372774593", "เจ้าทำสิ่งที่ให้เกียรติเราไว้มาก มือเจ้าเปื้อนเลือดสมุนฮักการ์ เจ้าเป็นมิตรของเผ่าแล้ว\n\nสวมปลอกแขนนี้เถิด เป็นปลอกแขนของผู้คิดอิสระ นี่แหละพลังที่แท้จริงที่ข้าพูดถึง" },
        required = { [19716] = { "23:1694748537:1018002582", "ผ้าพันข้อมือ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Bindings"] = "ผ้าพันข้อมือ Hakkari บรรพกาล" },
        },
    },
    [8054] = { -- Paragons of Power: The Freethinker's Belt
        title = { "41:78041771:685715258", "เครื่องหมายแห่งพลัง — เข็มขัดของผู้คิดอิสระ" },
        objective = { "209:99924159:1909677533", "นำ Primal Hakkari Shawl ไปให้ Jin'rokh the Breaker และต้องมีชื่อเสียงกับ Zandalar Tribe ระดับ Honored ขึ้นไป\n\nJin'rokh the Breaker อยู่ที่ Yojamba Isle ใน Stranglethorn Vale" },
        description = { "476:1313737824:1347920683", "ความเชื่อของเจ้าแปลกสำหรับเรา คนนอกศรัทธา ในอดีตแซนดาลาร์ก็เคยถูกตราหน้าว่านอกรีต ตอนนั้นจักรวรรดิกูรูบาชิยังแข็งแกร่ง คนนอกศรัทธากล้าท้าทายนักบวชของฮักการ์ จึงถูกไล่ล่าและฆ่าเหมือนสัตว์รบกวน แต่พวกเขาไม่เคยหวั่นไหวในการต่อสู้กับเทพโลหิต เราให้เกียรติสิ่งที่พวกเขาต้องเสียสละ พวกเขาคือผู้คิดอิสระ\n\nกำจัดสมุนฮักการ์ในซุลกูรูบ นำเครื่องหมายแห่งพลังที่ข้าตามหามาให้ ทำสำเร็จจะได้รางวัลใหญ่\n\nไปเถิด" },
        progress = { "103:1570433395:1212742935", "การที่เจ้ามาที่นี่หมายถึงชัยชนะหรือ? ได้เครื่องหมายมาแล้วหรือยัง? ตัวเจ้าโชกด้วยซากศัตรูหรือเปล่า?" },
        completion = { "236:1427914563:1891719436", "เกียรติของเจ้ามั่นคงในเผ่าแล้ว เจ้าปลิดชีวิตไปมากในซุลกูรูบ ศัตรูล้มลงต่อหน้าความเชื่อมั่นของเจ้า ล้มลงต่อหน้าพลังของเจ้า\n\nนี่คือเข็มขัดผู้คิดอิสระ เป็นสัญลักษณ์แห่งเกียรติและมีพลังโมโจกล้าแข็ง บัดนี้เป็นของเจ้า" },
        required = { [19721] = { "20:1525955877:1237644666", "ผ้าคลุมไหล่ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Shawl"] = "ผ้าคลุมไหล่ Hakkari บรรพกาล" },
        },
    },
    [8055] = { -- Paragons of Power: The Freethinker's Breastplate
        title = { "48:961464880:798316209", "เครื่องหมายแห่งพลัง — เกราะอกของผู้คิดอิสระ" },
        objective = { "210:84142579:1208420220", "นำ Primal Hakkari Tabard ไปให้ Jin'rokh the Breaker และต้องมีชื่อเสียงกับ Zandalar Tribe ระดับ Revered ขึ้นไป\n\nJin'rokh the Breaker อยู่ที่ Yojamba Isle ใน Stranglethorn Vale" },
        description = { "469:1404910394:2091299283", "อุปกรณ์รบมอบอำนาจในเผ่า เราให้เกียรติผู้คิดอิสระด้วยวิธีนี้ พวกเขาศรัทธาแรงกล้าและอัดโมโจทรงพลังไว้ในเกราะอก หากความเชื่อของพวกเขาสั่นคลอนต่อหน้าศัตรู เกราะอกจะยังคงมั่นคง\n\nเจ้าต้องได้รับความเคารพอย่างสูงจากพวกเราจึงจะครองเกราะอกเช่นนี้ได้ ไปซุลกูรูบ เอาเครื่องหมายแห่งพลังที่ข้าต้องการมา ทำให้เจ้าพวกโง่ข้างในเจ็บปวดที่สุดตอนชิงของจากมัน เอากลับมาให้ข้า พิสูจน์คุณค่าของเจ้าในฐานะผู้คิดอิสระให้ชัดเสียที" },
        progress = { "89:196231916:1958234793", "ได้เครื่องหมายแล้วหรือยัง? มันมีโมโจอยู่ข้างใน เราต้องได้มัน เจ้าจะช่วยเรา" },
        completion = { "313:1215188669:1259471193", "เจ้าทำสิ่งที่น้อยคนจะทำได้ ทำให้สมุนฮักการ์คุกเข่า แสดงให้มันเห็นว่าผู้คิดอิสระทำอะไรได้ และให้เราเห็นว่าคนนอกรีตได้รับความเคารพอย่างสูงในเผ่าได้อย่างไร เจ้ามีมากกว่าพลังแท้จริง เจ้านั่นแหละคือพลังแท้จริง\n\nรับเกราะอกไป ผู้คิดอิสระ จงบดขยี้ผู้ที่ขวางเจ้า" },
        required = { [19722] = { "21:1040067366:1082819017", "เสื้อคลุมตรา Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Tabard"] = "เสื้อคลุมตรา Hakkari บรรพกาล" },
        },
    },
    [8056] = { -- Paragons of Power: The Augur's Bracers
        title = { "38:2087780160:864428371", "เครื่องหมายแห่งพลัง — ปลอกข้อมือของโหรพยากรณ์" },
        objective = { "212:1210168999:1078347579", "นำ Primal Hakkari Armsplint ไปให้ Maywiki of Zuldazar และต้องมีชื่อเสียงกับ Zandalar Tribe ระดับ Friendly ขึ้นไป\n\nMaywiki of Zuldazar อยู่ที่ Yojamba Isle ใน Stranglethorn Vale" },
        description = { "501:1187433730:1106054089", "โหรพยากรณ์ของเผ่าเราเป็นที่เคารพเพราะหยั่งรู้เรื่องศักดิ์สิทธิ์ได้ สหาย พวกเขาไม่ใช่หมอผี แต่ใช้เวลาโยนกระดูกหรืออ่านใบไม้เพื่อหยั่งรู้ แทนที่จะสาปคน เจ้าเป็นชาแมน คงรู้เรื่องพลังพยากรณ์อยู่บ้าง พวกเราแซนดาลาร์เห็นค่าคำชี้แนะที่พวกเขาให้แก่เผ่า\n\nนำเครื่องหมายแห่งพลังจากในซุลกูรูบมาถวายและพิสูจน์คุณค่าต่อเรา ทำได้แล้วข้าจะให้ปลอกข้อมือที่โหรของเราหวงแหนเหนือชิ้นอื่น!" },
        progress = { "116:545760324:1836717687", "ได้เครื่องหมายแห่งพลังจากซุลกูรูบที่ข้าต้องการหรือยัง? ปลอกข้อมือนี้คุ้มกับแรงที่เจ้าลงไปแน่!" },
        completion = { "275:1582115362:1434522138 N 31:1700533996:385881164", "ดูเหมือนเจ้ามีแววโหรแซนดาลาร์อยู่บ้าง เรารู้ว่าเจ้าทำอะไรเพื่อเราในซุลกูรูบ สหาย เครื่องหมายแห่งพลังพวกนี้จะช่วยเผ่าแซนดาลาร์ได้มาก และขอบอกไว้ว่าเจ้าพึ่งพาพวกเราในฐานะเพื่อนได้ รับปลอกข้อมือนี้ไป {name} เจ้าทำมากพอที่จะได้มันแล้ว!" },
        required = { [19717] = { "24:191297855:2119822824", "แผ่นประกับแขน Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Armsplint"] = "แผ่นประกับแขน Hakkari บรรพกาล" },
        },
    },
    [8057] = { -- Paragons of Power: The Haruspex's Bracers
        title = { "41:1013272686:773058301", "เครื่องหมายแห่งพลัง — ปลอกข้อมือของผู้ทำนายจากเครื่องใน" },
        objective = { "212:1167494874:1775068402", "นำ Primal Hakkari Stanchion ไปให้ Maywiki of Zuldazar และต้องมีชื่อเสียงกับ Zandalar Tribe ระดับ Friendly ขึ้นไป\n\nMaywiki of Zuldazar อยู่ที่ Yojamba Isle ใน Stranglethorn Vale" },
        description = { "488:993371024:745205486", "ผู้ทำนายจากเครื่องในเป็นคนสำคัญของเผ่า เจ้าควรฟังลางที่พวกเขาบอก พวกเขาสื่อสารกับสัตว์และถวายสัตว์แก่เหล่าวิญญาณเมื่อจำเป็น เพื่อขอคำชี้แนะจากสิ่งศักดิ์สิทธิ์ ครั้งก่อนความหยั่งรู้และปัญญาของพวกเขาทำให้เราได้เปรียบในสงครามกับเผ่าที่แตกออกจากกูรูบาชิ\n\nนำเครื่องหมายแห่งพลังจากในซุลกูรูบมาถวายและพิสูจน์คุณค่าต่อเรา ทำได้แล้วข้าจะให้ปลอกข้อมือที่ผู้ทำนายแซนดาลาร์คนไหนก็อยากได้" },
        progress = { "86:1109946024:1669180177 N 15:766490052:1922914157", "ได้เครื่องหมายแห่งพลังจากซุลกูรูบมาแล้วหรือยัง? ปลอกข้อมือนี้คุ้มแรงแน่ {name} เชื่อข้าสิ สหาย!" },
        completion = { "63:1109543342:976410329 N 79:851084350:933291715 N 47:2053020862:1140687227", "อา ข้าสัมผัสพลังจากเครื่องหมายพวกนี้ได้ {name} เจ้าพิสูจน์ว่าเป็นคนที่เผ่าเราเรียกว่า “เพื่อน” ได้ ข้อตกลงก็ต้องเป็นข้อตกลง {name} จงดูพลังของปลอกข้อมือผู้ทำนายจากเครื่องใน!" },
        required = { [19718] = { "24:272931372:563995701", "เสาค้ำ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Stanchion"] = "เสาค้ำ Hakkari บรรพกาล" },
        },
    },
    [8058] = { -- Paragons of Power: The Vindicator's Armguards
        title = { "45:986345206:1838103190", "เครื่องหมายแห่งพลัง — ปลอกแขนของผู้ลงทัณฑ์" },
        objective = { "214:478189335:2051056849", "นำ Primal Hakkari Armsplint ไปให้ Jin'rokh the Breaker และต้องมีชื่อเสียงกับ Zandalar Tribe ระดับ Friendly ขึ้นไป\n\nJin'rokh the Breaker อยู่ที่ Yojamba Isle ใน Stranglethorn Vale" },
        description = { "435:38132827:767826067", "การล้างแค้นคือพลัง ผู้ลงทัณฑ์แห่งแซนดาลาร์คือพลังนั้น เผ่ามีศัตรูมาก ผู้ลงทัณฑ์จะเอาคืนพวกมัน ไม่มีความผิดใดต่อเราที่รอดโทษ ผู้ลงทัณฑ์คือผู้มอบโทษนั้น ศัตรูกลัวการล้างแค้นของเรา สมควรแล้ว และมันจะกลัวตลอดไป\n\nมาเป็นผู้ลงทัณฑ์ของเรา ตามหาเครื่องหมายแห่งพลังในซุลกูรูบ สังหารสมุนฮักการ์และล้างแค้นในนามเผ่า เจ้าจะได้รับรางวัล" },
        progress = { "95:780126905:1738084920", "เอาเครื่องหมายแห่งพลังมาแล้วหรือ? เจ้าได้ล้างแค้นในนามแซนดาลาร์แล้วหรือยัง?" },
        completion = { "236:1853289179:1843857672", "วันนี้เจ้าล้างแค้นให้เรามาก เจ้าแสดงตัวตนของผู้ลงทัณฑ์แล้ว และทำให้สมุนเทพโลหิตคุกเข่า\n\nรับนี่ไป มันจะเติมพลังให้การล้างแค้นครั้งต่อไป บัดนี้เจ้าเป็นมิตรของแซนดาลาร์" },
        required = { [19717] = { "24:191297855:2119822824", "แผ่นประกับแขน Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Armsplint"] = "แผ่นประกับแขน Hakkari บรรพกาล" },
        },
    },
    [8059] = { -- Paragons of Power: The Demoniac's Wraps
        title = { "39:1621014390:1325216156", "เครื่องหมายแห่งพลัง — ผ้าพันแขนของผู้ครองปีศาจ" },
        objective = { "220:990609645:2122173382", "นำ Primal Hakkari Stanchion ไปให้ Al'tabim the All-Seeing และต้องมีชื่อเสียงกับ Zandalar Tribe ระดับ Friendly ขึ้นไป\n\nAl'tabim the All-Seeing อยู่ที่ Yojamba Isle ใน Stranglethorn Vale" },
        description = { "493:494202039:1419740436", "วอร์ล็อกเดินบนทางอันตรายเมื่อยุ่งเกี่ยวกับปีศาจ แต่ผู้ครองปีศาจของเราก้าวไปไกลกว่านั้น ด้วยพิธีลี้ลับโบราณ พวกเขายอมให้ปีศาจเข้าร่าง แล้วจับมันเป็นทาสจากข้างใน ดูดเอาพลังของมันมาใช้เอง มีน้อยคนที่ฝึกวิชานี้จนชำนาญ\n\nหากเจ้าจะเรียนพลังของผู้ครองปีศาจ ข้าต้องได้เครื่องหมายแห่งพลังจากซุลกูรูบ ไปเอาสิ่งที่เราตามหามา" },
        progress = { "195:1164233358:2144799374", "เจ้ากลับมาพร้อมเครื่องหมายแห่งพลังหรือยัง? การเอาชนะสมุนร้ายของฮักการ์จะพิสูจน์คุณค่าของเจ้า และแสดงว่าเจ้าพร้อมเรียนวิถีผู้ครองปีศาจ" },
        completion = { "256:1326260177:554288256", "ทำได้ดี... พวกมันคงต้องจ่ายด้วยความเจ็บปวดแสนสาหัสก่อนยอมเสียเครื่องหมายแห่งพลัง รับผ้าพันแขนผู้ครองปีศาจนี้ไป ทำจากโมโจทรงพลังที่ใช้เรียกเหยื่อของผู้ครองปีศาจ มันเป็นเครื่องมือสำคัญในการแสวงหาพลังของเจ้า" },
        required = { [19718] = { "24:272931372:563995701", "เสาค้ำ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Stanchion"] = "เสาค้ำ Hakkari บรรพกาล" },
        },
    },
    [8060] = { -- Paragons of Power: The Illusionist's Wraps
        title = { "42:32601162:902484349", "เครื่องหมายแห่งพลัง — ผ้าพันแขนของจอมเวทมายา" },
        objective = { "217:779225723:1402819511", "นำ Primal Hakkari Bindings ไปให้ Al'tabim the All-Seeing และต้องมีชื่อเสียงกับ Zandalar Tribe ระดับ Friendly ขึ้นไป\n\nAl'tabim the All-Seeing อยู่ที่ Yojamba Isle ใน Stranglethorn Vale" },
        description = { "485:615488971:1424895579", "เราเรียกจอมเวทในเผ่าว่าจอมเวทมายา พวกเขาใช้โมโจทรงพลังในคาถา ทำให้ศัตรูของเผ่ามึนงงและสับสน!\n\n<อัลทาบิมหัวเราะอย่างร้ายกาจ>\n\nภาพจอมเวทมายาฝีมือดีกำลังร่ายเวทน่าดูทีเดียว ศัตรูทรุดคุกเข่าด้วยความคลุ้มคลั่งของตัวเอง!\n\nหากจะเรียนวิถีจอมเวทมายาของเรา จงไปซุลกูรูบและนำเครื่องหมายแห่งพลังที่ข้าเลือกกลับมา แล้วข้าจะให้ผ้าพันแขนที่จอมเวทมายาของเราใช้ถักทอคาถา" },
        progress = { "N 78:1758520019:536236079", "{name} กลับมาแล้วหรือ? หาเครื่องหมายแห่งพลังที่ข้าต้องการได้ไหม?" },
        completion = { "400:1248084730:893714751", "น่าประทับใจ... เจ้าสัมผัสโมโจที่ไหลผ่านมันได้หรือเปล่า? เครื่องหมายแห่งพลังเคยใช้คล้ายเงินตราสมัยจักรวรรดิกูรูบาชิปกครองดินแดนนี้ ตอนนี้แซนดาลาร์จะใช้โมโจที่ซ่อนอยู่ในนั้นต่อต้านการผงาดขึ้นครั้งที่สองของฮักการ์เทพโลหิต!\n\nวันนี้เจ้าทำได้ดี ถือว่าเจ้ามีเพื่อนในหมู่แซนดาลาร์แล้ว นี่คือผ้าพันแขนจอมเวทมายาที่ข้าสัญญา!" },
        required = { [19716] = { "23:1694748537:1018002582", "ผ้าพันข้อมือ Hakkari บรรพกาล" } },
        objectiveLabels = {
