    [8061] = { -- Paragons of Power: The Confessor's Wraps
        objective = { "220:990609645:2122173382", "นำ Primal Hakkari Stanchion ไปให้ Al'tabim the All-Seeing และต้องมีชื่อเสียงกับ Zandalar Tribe ระดับ Friendly ขึ้นไป\n\nAl'tabim the All-Seeing อยู่ที่ Yojamba Isle ใน Stranglethorn Vale" },
        title = { "40:1193327770:1539342936", "เครื่องหมายแห่งพลัง — ผ้าพันแขนของผู้รับฟังคำสารภาพ" },
        description = { "491:385180323:2094125417", "พวกเราแซนดาลาร์มอบอำนาจแก่ผู้กล่าวด้วยสิทธิ์จากสิ่งศักดิ์สิทธิ์ นักบวชของเรามีหน้าที่มากกว่าการรักษา พวกเขาเป็นผู้รับฟังคำสารภาพ ความชั่วมาจากทั้งภัยภายนอกอย่างฮักการ์และจากภายในเผ่า ผู้รับฟังคำสารภาพตัดสินเรื่องในหมู่เราและปกป้องเราจากความชั่วแบบเดียวกับที่กัดกินกูรูบาชิจากข้างใน\n\nไปซุลกูรูบแล้วเอาเครื่องหมายแห่งพลังกลับมาจากกูรูบาชิ เรียนรู้ว่าการเป็นผู้รับฟังคำสารภาพหมายถึงอะไร แล้วปกป้องเราจากความชั่ว" },
        progress = { "112:603135600:656653084", "กลับจากซุลกูรูบแล้วหรือ? ชิงเครื่องหมายแห่งพลังจากสมุนฮักการ์สำเร็จไหม?" },
        completion = { "13:1029592715:2013062331 N 214:103869687:1116581443", "ยอดเยี่ยมมาก {name}! กว่าจะนำของเหล่านี้มาให้ข้าได้คงเหนื่อยไม่น้อย วันนี้ท่านได้ทำหน้าที่ผู้รับฟังคำสารภาพของเผ่า ช่วยปกป้องพวกเราจากภัยของฮักการ์ ผ้าพันข้อมือนี้เหมาะกับมิตรของเผ่าอย่างท่าน!" },
        required = { [19718] = { "24:272931372:563995701", "เสาค้ำ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Stanchion"] = "เสาค้ำ Hakkari บรรพกาล" },
        },
    },
    [8062] = { -- Paragons of Power: The Predator's Bracers
        title = { "41:1186036470:1516291630", "เครื่องหมายแห่งพลัง — ปลอกแขนนักล่า" },
        objective = { "266:162866609:1161140809", "นำเครื่องหมายแห่งพลังจากซุลกูรูบไปมอบให้ Falthir the Sightless ได้แก่ Primal Hakkari Bindings ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Friendly ขึ้นไป\n\nFalthir the Sightless อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "489:344374297:621401624", "ในยุคมืดหลังจักรวรรดิกูรูบาชิล่มสลาย เหล่านักล่าแซนดาลาร์ใช้ฝีมือหาอาหารมาหล่อเลี้ยงเผ่า พวกฮันเตอร์มักบอกว่าตัวเองคล้ายกับนักล่าของเผ่าเรา ก็จริงที่ใจรักการล่าคือแก่นแท้ของนักล่า แต่ฝีมือในซุลกูรูบจะบอกเองว่าท่านอยู่ระดับไหนเมื่อเทียบกับยอดนักล่าของเรา\n\nนำเครื่องหมายแห่งพลังจากซุลกูรูบมาให้ข้าสักชิ้น นั่นจะเป็นก้าวแรกบนเส้นทางสู่การเป็นยอดนักล่า" },
        progress = { "66:470154660:44991697 N 64:1815335062:1169223255", "จงล่าพวกที่ครอบครองเครื่องหมายแห่งพลังในซุลกูรูบ {name} พวกมันคือเหยื่อของท่านและถือสิ่งที่เราทั้งคู่ต้องการไว้" },
        completion = { "338:1037711190:1598054309 N 1:46:46", "ใช่แล้ว... ข้าไม่ต้องใช้ตาก็สัมผัสถึงเครื่องหมายแห่งพลังได้ ผลงานของท่านในซุลกูรูบทำให้คนในเผ่าหลายคนประทับใจ เรานับท่านเป็นมิตรของแซนดาลาร์และเห็นว่าท่านคู่ควรกับปลอกแขนนักล่า มันเปี่ยมพลังและเป็นสัญลักษณ์ของนักล่าที่แท้จริง ทำได้ดีมาก {name}" },
        required = { [19716] = { "23:1694748537:1018002582", "ผ้าพันข้อมือ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Bindings"] = "ผ้าพันข้อมือ Hakkari บรรพกาล" },
        },
    },
    [8063] = { -- Paragons of Power: The Madcap's Bracers
        title = { "39:1466650343:616327016", "เครื่องหมายแห่งพลัง — ปลอกแขนจอมคลั่ง" },
        objective = { "216:122535401:1203214010", "นำ Primal Hakkari Armsplint ไปมอบให้ Falthir the Sightless ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Friendly ขึ้นไป\n\nFalthir the Sightless อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "472:895192737:1906365905", "จอมคลั่งแห่งแซนดาลาร์คล้ายพวกโร้ก แต่สิ่งที่พวกเขาโอบรับเหนืออื่นใดคือความบ้าคลั่ง... ความโกลาหล... และความไม่แน่นอนของชีวิต ในยุคป่าเถื่อนหลังเผ่าต่าง ๆ แตกแยก พวกเขาน่าสะพรึงกลัวในสนามรบและทำให้ศัตรูของเราปั่นป่วนจนเสียกระบวน หากไร้พวกเขา เราคงไม่มีวันนี้\n\nนำเครื่องหมายแห่งพลังที่ข้าต้องการจากซุลกูรูบมาให้ข้า แล้วข้าจะมอบเกราะล้ำค่าชิ้นแรกของจอมคลั่งให้ จงโอบรับความบ้าคลั่ง!" },
        progress = { "72:626593987:852526911 N 94:1641157767:945967961", "จงเผชิญความบ้าคลั่งในซุลกูรูบ แล้วใช้ความคลั่งของตัวเองข่มมันให้มิด {name}! ทำได้ก็ชนะ และผู้ชนะย่อมได้รางวัล! อย่าให้เทพโลหิตกลับมาครองอำนาจอีก!" },
        completion = { "11:534428891:784080240 N 193:1955740281:972017036", "ทำได้ดี {name}... ผลงานในซุลกูรูบทำให้ท่านมีสิทธิ์เรียกเผ่าแซนดาลาร์ว่ามิตร ข้าจะจัดการกับเครื่องหมายแห่งพลังเอง โปรดรับรางวัลนี้ตอบแทนความพยายามของท่าน!" },
        required = { [19717] = { "24:191297855:2119822824", "แผ่นประกับแขน Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Armsplint"] = "แผ่นประกับแขน Hakkari บรรพกาล" },
        },
    },
    [8064] = { -- Paragons of Power: The Haruspex's Belt
        title = { "38:1744977611:1860868586", "เครื่องหมายแห่งพลัง — เข็มขัดผู้ทำนายจากเครื่องใน" },
        objective = { "156:777158447:640515259", "นำ Primal Hakkari Sash ไปมอบให้ Maywiki of Zuldazar ซึ่งอยู่บน Yojamba Isle ใน Stranglethorn Vale ท่านต้องมีชื่อเสียงกับแซนดาลาร์ระดับ Honored ด้วย" },
        description = { "493:1732580800:669436490", "พวกเราแซนดาลาร์ไม่รู้จักวิถีดรูอิด เราปรับธรรมชาติให้เข้ากับสิ่งที่เราต้องการ แต่ในหมู่พวกเรา ผู้ทำนายจากเครื่องในเข้าใจธรรมชาติดีที่สุด และก็สมควรแล้ว ผู้ที่ปลดปล่อยวิญญาณสัตว์ย่อมเข้าใจชีวิตของมัน นั่นละพลังแท้จริงของธรรมชาติ\n\nนำเครื่องหมายแห่งพลังจากซุลกูรูบมาถวายเพื่อพิสูจน์ตัวเองกับเรา แล้วข้าจะมอบของทรงพลังให้ เป็นเข็มขัดที่ผู้ทำนายจากเครื่องในของแซนดาลาร์ใช้กัน\n\nพลังโมโจแรงกล้าเลยล่ะ พวก!" },
        progress = { "99:2146713442:1189024978", "ได้เครื่องหมายแห่งพลังจากซุลกูรูบที่ข้าต้องการมาหรือยัง? ถ้าได้มาแล้ว เข็มขัดผู้ทำนายจากเครื่องในก็เป็นของท่าน" },
        completion = { "233:728155533:1259743702", "ขอบใจมาก พลังที่ซ่อนอยู่ในของพวกนี้มีค่าในตัวมันเองแน่นอน ท่านทำตามที่ข้าขอและพิสูจน์ให้คนในเผ่าเห็นว่าท่านควรได้รับเกียรติ นี่คือรางวัลตามที่สัญญาไว้!" },
        required = { [19720] = { "19:373142409:206045942", "ผ้าคาดเอว Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Sash"] = "ผ้าคาดเอว Hakkari บรรพกาล" },
        },
    },
    [8065] = { -- Paragons of Power: The Haruspex's Tunic
        title = { "39:1121942588:2684816", "เครื่องหมายแห่งพลัง — เสื้อผู้ทำนายจากเครื่องใน" },
        objective = { "158:758409609:286890925", "นำ Primal Hakkari Tabard ไปมอบให้ Maywiki of Zuldazar ซึ่งอยู่บน Yojamba Isle ใน Stranglethorn Vale ท่านต้องมีชื่อเสียงกับแซนดาลาร์ระดับ Revered ด้วย" },
        description = { "61:892121021:1134729511 N 399:1428424886:1242602672", "เสื้อผ้าที่สวมคือเครื่องหมายสูงสุดแห่งพลังของผู้ทำนายจากเครื่องใน {name} ในบรรดาเครื่องแต่งกาย เสื้อเป็นสัญลักษณ์ที่เชื่อมพวกเขากับปัญญาศักดิ์สิทธิ์ที่แสวงหา พวกเขามักถักทอชิ้นส่วนของสัตว์ที่บูชายัญลงในเสื้อ เพื่อเตือนใจว่าพรที่ตนได้รับเชื่อมโยงกับสิ่งใด\n\nนำเครื่องหมายแห่งพลังจากซุลกูรูบมาถวายเพื่อพิสูจน์ว่าท่านคู่ควร แล้วเสื้อที่อัดแน่นด้วยพลังแท้จริงของผู้ทำนายจากเครื่องในจะเป็นของท่าน" },
        progress = { "120:883173332:985853088", "ได้เครื่องหมายแห่งพลังจากซุลกูรูบครบตามที่ต้องการหรือยัง? เสื้อผู้ทำนายจากเครื่องในคุ้มกับแรงที่ท่านต้องลงไปแน่" },
        completion = { "76:472260773:904983971 N 145:519012190:1939359078 C 1:33:33", "น่าประทับใจ... ท่านรวบรวมเครื่องหมายแห่งพลังที่ต้องการได้แล้ว {name} สิ่งที่ท่านทำเพื่อแซนดาลาร์ในซุลกูรูบจะกลายเป็นตำนาน จากนี้เผ่าเราจะยกย่องท่าน รับเสื้อตัวนี้ไปเถิด ท่าน{class}ผู้เกรียงไกร!" },
        required = { [19722] = { "21:1040067366:1082819017", "เสื้อคลุมตรา Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Tabard"] = "เสื้อคลุมตรา Hakkari บรรพกาล" },
        },
    },
    [8066] = { -- Paragons of Power: The Predator's Belt
        title = { "38:68785014:12424607", "เครื่องหมายแห่งพลัง — เข็มขัดนักล่า" },
        objective = { "262:1549139814:985776762", "นำเครื่องหมายแห่งพลังจากซุลกูรูบไปมอบให้ Falthir the Sightless ได้แก่ Primal Hakkari Shawl ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Honored ขึ้นไป\n\nFalthir the Sightless อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "443:1978721749:1946750306", "นักล่ารู้วิธีสะกดรอยตามเหยื่อ นักล่าที่เก่งยังรู้ว่าต้องลงมืออย่างไรเมื่อเข้าใกล้พอ ท่านต้องชำนาญทั้งสองอย่างจึงจะมีโอกาสทำสำเร็จในซุลกูรูบและก้าวขึ้นมาเป็นอย่างนักล่าแซนดาลาร์\n\nนำเครื่องหมายแห่งพลังชิ้นที่ข้าต้องการจากซุลกูรูบมาให้ข้า ข้าจะได้พลังจากเครื่องราง ส่วนท่านจะได้เข็มขัดนักล่าแซนดาลาร์ อุปกรณ์ชิ้นนี้คุ้มกับของที่แลกมาแน่" },
        progress = { "105:1692786897:974061696 N 81:636540060:780861814", "จงจู่โจมสมุนคลุ้มคลั่งของฮักการ์ในซุลกูรูบ พวกมันถือเครื่องหมายแห่งพลังอยู่ {name} แสดงฝีมือให้พวกมันและเผ่าเราเห็นว่าท่านมีแววเป็นนักล่า" },
        completion = { "38:1932767873:988142861 N 431:1687113918:1576861809", "ข้าสัมผัสได้ว่าท่านมาถึงเมื่อครู่นี้ {name} แม้จะแทบจับสัญญาณไม่ได้ สิ่งที่ทำให้ข้ารู้คือเครื่องหมายแห่งพลังที่ท่านนำมา ข้าสัมผัสพลังของเครื่องรางได้แม้มองไม่เห็น โมโจหรือเวทมนตร์ดิบที่แฝงอยู่ในนั้นจะช่วยให้เราขัดขวางแผนชั่วร้ายของฮักการ์ เทพโลหิต ต่อไปได้\n\nผลงานของท่านสมควรได้รับคำชมและรางวัล เผ่าให้เกียรติท่านแล้ว และท่านคู่ควรกับเข็มขัดนักล่า" },
        required = { [19721] = { "20:1525955877:1237644666", "ผ้าคลุมไหล่ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Shawl"] = "ผ้าคลุมไหล่ Hakkari บรรพกาล" },
        },
    },
    [8067] = { -- Paragons of Power: The Predator's Mantle
        title = { "40:722679802:764423451", "เครื่องหมายแห่งพลัง — ผ้าคลุมไหล่นักล่า" },
        objective = { "262:573797171:395659567", "นำเครื่องหมายแห่งพลังจากซุลกูรูบไปมอบให้ Falthir the Sightless ได้แก่ Primal Hakkari Aegis ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Revered ขึ้นไป\n\nFalthir the Sightless อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "495:823864684:1014853694", "เราแซนดาลาร์ให้คุณค่ากับเครื่องแต่งกายในฐานะสัญลักษณ์ของความสำเร็จ แม้ไม่เห็นว่าใครสวมอะไร ก็สัมผัสได้ถึงพลังที่แผ่ออกมา พลังอยู่เหนือการมองเห็น เครื่องแต่งกายของนักล่าแซนดาลาร์ก็เช่นกัน สิ่งที่พวกเขาหวงแหนที่สุดคือผ้าคลุมไหล่ มันช่วยพรางกาย... และช่วยให้ผู้อื่นรู้ว่าพวกเขาอยู่ตรงนั้นเมื่อถึงคราวที่ต้องการเผยตัว\n\nเครื่องหมายแห่งพลังรอให้ท่านไปนำกลับมาจากซุลกูรูบ เอาสิ่งที่ข้าต้องการมา แล้วผ้าคลุมไหล่นักล่าจะเป็นของท่าน" },
        progress = { "50:2103696901:1834349984 N 144:112492375:114288318", "การจู่โจมซุลกูรูบได้ผลไหม {name}? เมื่อท่านนำสิ่งที่ข้าต้องการมาและพิสูจน์ตัวเองต่อเผ่าจนเป็นที่ประจักษ์ ท่านจึงจะได้ผ้าคลุมไหล่ที่ไม่มีชิ้นไหนในแซนดาลาร์เทียบได้" },
        completion = { "52:1742922215:1352049892 N 245:96624581:1299030888", "สำเร็จแล้ว... เผ่าจะยกย่องท่าน {name} การหาเครื่องหมายแห่งพลังสำหรับผ้าคลุมไหล่นี้เป็นงานหนัก แต่ท่านจัดการได้อย่างนักล่าที่ร้ายกาจที่สุดของเรา ท่านได้ที่ยืนในหมู่พวกเขาและมีสิทธิ์สวมผ้าคลุมไหล่ของพวกเขาแล้ว" },
        required = { [19724] = { "20:260368875:224970212", "โล่ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Aegis"] = "โล่ Hakkari บรรพกาล" },
        },
    },
    [8068] = { -- Paragons of Power: The Illusionist's Mantle
        title = { "43:1472617498:183768446", "เครื่องหมายแห่งพลัง — ผ้าคลุมไหล่จอมเวทมายา" },
        objective = { "215:1766429132:380612787", "นำ Primal Hakkari Shawl ไปมอบให้ Al'tabim the All-Seeing ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Honored ขึ้นไป\n\nAl'tabim the All-Seeing อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "498:1080707302:1679412110", "เวทมนตร์เป็นพลังดิบแต่ดั้งเดิม ผู้ที่แข็งแกร่งพอจึงจะควบคุมมันได้ พวกเราใช้พลังนี้ในรูปของโมโจ และวิธีหนึ่งที่ทรงอานุภาพคือการสร้างภาพลวงตา ใครจะหวังเอาชนะศัตรูที่ไม่มีตัวตนอยู่ตรงนั้นได้? เราแซนดาลาร์รู้ดีว่าสิ่งนี้ทรงพลังแค่ไหน จอมเวทมายาจึงมีที่ทางอันทรงเกียรติในเผ่า\n\nไปนำเครื่องหมายแห่งพลังที่ต้องการจากซุลกูรูบ แล้วท่านจะได้รับเกียรติจากเผ่าและผ้าคลุมไหล่ทรงพลังที่ยอดจอมเวทมายาของเราใช้!" },
        progress = { "209:738948829:315422068", "การบุกซุลกูรูบเป็นอย่างไรบ้าง? ใช้ภาพลวงตาปั่นหัวศัตรูจนคลั่งได้ไหม? ไม่ว่าจะใช้ภาพลวงตาหรือไม่ การตายของพวกมันและเครื่องหมายแห่งพลังที่ชิงมาจะช่วยหยุดการคืนอำนาจของฮักการ์" },
        completion = { "135:2123730155:1932079091 N 91:452974435:674324826", "สำเร็จแล้ว! จากนี้ท่านจะได้รับเกียรติในหมู่เผ่า วันนี้ซุลกูรูบได้ลิ้มรสพลังของแซนดาลาร์แล้ว เพราะท่านแท้ ๆ {name}\n\nรับผ้าคลุมไหล่จอมเวทมายาแซนดาลาร์พร้อมพรจากเผ่าไปเถิด ขอให้มันรับใช้ท่านเป็นอย่างดี" },
        required = { [19721] = { "20:1525955877:1237644666", "ผ้าคลุมไหล่ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Shawl"] = "ผ้าคลุมไหล่ Hakkari บรรพกาล" },
        },
    },
    [8069] = { -- Paragons of Power: The Illusionist's Robes
        title = { "42:1791708717:1570739820", "เครื่องหมายแห่งพลัง — เสื้อคลุมจอมเวทมายา" },
        objective = { "217:490876150:439792425", "นำ Primal Hakkari Kossack ไปมอบให้ Al'tabim the All-Seeing ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Revered ขึ้นไป\n\nAl'tabim the All-Seeing อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "381:118838466:1846334288 N 106:1735021752:703796411", "คนในเผ่ารู้ฐานะและพลังของกันและกันจากสิ่งที่สวม เครื่องแต่งกายของเราทำจากวัสดุชั้นดีและถักทอด้วยโมโจที่มอบพลังให้เรา จอมเวทมายาก็เช่นกัน ว่ากันว่ารูปลักษณ์ของเสื้อคลุมพวกเขารวบรวมแก่นแท้ของภาพลวงตาไว้ ตำนานเล่าว่าเสื้อคลุมโบราณของพวกเขาไม่เคยปรากฏในรูปลักษณ์เดิมซ้ำเลย\n\nข้าจะมอบเสื้อคลุมจอมเวทมายาให้ท่าน {name}... แต่ท่านต้องพิสูจน์ตัวเองจนได้รับการยกย่องจากเผ่าเสียก่อน นำเครื่องหมายแห่งพลังจากซุลกูรูบมาให้ข้า!" },
        progress = { "193:914853592:1730109200", "ท่านกลับมาพร้อมเครื่องหมายแห่งพลังที่เราต้องการหรือเปล่า? ข้ารู้ว่าไม่ง่าย... แต่ข้าทำนายมานานแล้วว่าคนนอกจะมาช่วยเราสู้กับฮักการ์ ขอให้เป็นท่านเถิด!" },
        completion = { "166:187414589:1864982475 N 1:33:33", "ในที่สุดก็มีคนคู่ควรกับเสื้อคลุมจอมเวทมายา! ชัยชนะของท่านในซุลกูรูบจะทำให้เผ่ายกย่องท่านไปอีกนาน จงสวมมันด้วยความภาคภูมิใจ {name}!" },
        required = { [19723] = { "22:1789356227:446504915", "เสื้อเกราะคอสแซ็ก Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Kossack"] = "เสื้อเกราะคอสแซ็ก Hakkari บรรพกาล" },
        },
    },
    [8070] = { -- Paragons of Power: The Confessor's Bindings
        title = { "43:29563963:186944460", "เครื่องหมายแห่งพลัง — ผ้าพันข้อมือผู้รับฟังคำสารภาพ" },
        objective = { "214:396464531:922449397", "นำ Primal Hakkari Sash ไปมอบให้ Al'tabim the All-Seeing ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Honored ขึ้นไป\n\nAl'tabim the All-Seeing อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "497:934716429:1441100672", "ไม่นานหลังการล่มสลายของกูรูบาชิ ภัยร้ายในเผ่าเกือบทำให้เราแซนดาลาร์พินาศ เวลานั้นเหล่าผู้รับฟังคำสารภาพลุกขึ้นปกป้องเผ่าด้วยการขับไล่ผู้ที่คิดทำลายพวกพ้อง พวกเขาช่วยให้เราใกล้ชิดกับเหล่าวิญญาณและปกปักรักษาร่างกายของเราด้วย\n\nจงไปซุลกูรูบและดูความชั่วช้าของฮักการ์กับพวกกูรูบาชิด้วยตาตัวเอง ชิงเครื่องหมายแห่งพลังที่เราต้องการมาจากพวกมัน แล้วท่านจะได้รับรางวัล!" },
        progress = { "203:1368747993:1439953029", "เครื่องหมายแห่งพลัง... ท่านได้มาหรือยัง? เราต้องได้ของเหล่านี้มาก่อน จึงจะดึงพลังที่ซ่อนอยู่ข้างในออกมาใช้ได้ ถึงเวลาพลิกสถานการณ์เล่นงานสมุนของเทพโลหิตเสียที..." },
        completion = { "232:1269599379:1582982475 N 67:1366589045:854686803", "สำเร็จแล้ว! ของเหล่านี้จะช่วยเสริมกำลังเราไว้ต้านการคืนอำนาจของฮักการ์ ความช่วยเหลือของท่านทำให้เราก้าวไปอีกขั้นในการป้องกันมิให้เทพโลหิตทำลายเราทั้งหมด\n\nวันนี้ท่านได้รับเกียรติจากเผ่าแล้ว {name} โปรดรับผ้าพันข้อมือผู้รับฟังคำสารภาพไว้แทนคำขอบคุณของเรา" },
        required = { [19720] = { "19:373142409:206045942", "ผ้าคาดเอว Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Sash"] = "ผ้าคาดเอว Hakkari บรรพกาล" },
        },
    },
    [8071] = { -- Paragons of Power: The Confessor's Mantle
        title = { "41:1279128821:2007865441", "เครื่องหมายแห่งพลัง — ผ้าคลุมไหล่ผู้รับฟังคำสารภาพ" },
        objective = { "215:1574644331:912223756", "นำ Primal Hakkari Aegis ไปมอบให้ Al'tabim the All-Seeing ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Revered ขึ้นไป\n\nAl'tabim the All-Seeing อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "495:1178787502:1534254385", "ผู้รับฟังคำสารภาพของแซนดาลาร์ล้วนสวมผ้าคลุมไหล่ที่เห็นแล้วรู้ได้ทันทีว่าพวกเขาคือผู้ปกปักรักษาเผ่า ผ้าคลุมไหล่เหล่านี้ทอด้วยโมโจทรงพลังที่ช่วยตัดสินผู้ที่เป็นภัยต่อเผ่า ในฐานะนักบวช ท่านก็ต้องพิจารณาอยู่เสมอว่าใครคู่ควร ผ้าคลุมไหล่เช่นนี้ย่อมเป็นพรแก่ท่าน\n\nไปต่อสู้กับสมุนฮักการ์ในซุลกูรูบและนำเครื่องหมายแห่งพลังที่ข้าต้องการมา แล้วข้าจะมอบผ้าคลุมไหล่ที่คู่ควรกับยอดผู้รับฟังคำสารภาพของเราให้ท่าน" },
        progress = { "49:1119752277:468347416", "ท่านได้เครื่องหมายแห่งพลังจากซุลกูรูบมาแล้วหรือยัง?" },
        completion = { "11:534428891:784080240 N 240:1757426468:1822101890", "ทำได้ดี {name} วันนี้สมุนของฮักการ์คงได้รู้ซึ้งถึงการเอาคืนของแซนดาลาร์ เพราะท่านแท้ ๆ เผ่าจะยกย่องท่านตลอดไปสำหรับสิ่งที่ท่านทำ โปรดรับผ้าคลุมไหล่ผู้รับฟังคำสารภาพพร้อมพรจากเรา!" },
        required = { [19724] = { "20:260368875:224970212", "โล่ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Aegis"] = "โล่ Hakkari บรรพกาล" },
        },
    },
    [8072] = { -- Paragons of Power: The Madcap's Mantle
        title = { "38:1901963102:1675561761", "เครื่องหมายแห่งพลัง — ผ้าคลุมไหล่จอมคลั่ง" },
        objective = { "212:1191700947:183475540", "นำ Primal Hakkari Girdle ไปมอบให้ Falthir the Sightless ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Honored ขึ้นไป\n\nFalthir the Sightless อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "501:1306297322:276273632", "Khar'vaxal the Cracked คือหนึ่งในจอมคลั่งในตำนานของแซนดาลาร์ ตำนานเล่าว่าเมื่อเผชิญหน้ากับศัตรูของเผ่าครั้งแรก Kar'xavan ใช้ผ้าคลุมไหล่ที่ทอเป็นพิเศษด้วย ‘ลายทอแห่งความบ้าคลั่ง’ ร่างของเขาถูกบดบังทั้งด้วยผ้าคลุมไหล่และด้วยมีดคู่ที่ฟาดฟันเร็วจนมองตามไม่ทัน จอมคลั่งในวันนี้หวงแหนผ้าคลุมไหล่ในฐานะสัญลักษณ์ของที่ทางในเผ่า\n\nนำเครื่องหมายแห่งพลังที่ข้าตามหามาให้ แล้วท่านจะได้ผ้าคลุมไหล่แบบนั้นไปถักทอความคลั่งให้ศัตรูของท่านเอง" },
        progress = { "328:896054597:1187900243", "กลับมาแล้วหรือ ท่านมีเครื่องหมายแห่งพลังที่ข้าต้องการไหม?\n\nตำนานของ Khar'vaxal the Cracked เตือนใจเราจนถึงวันนี้ว่าไม่ว่าศัตรูจะน่ากลัวเพียงใด ก็เอาชนะได้ทั้งนั้น ความโกลาหลจะทำให้ทุกคนต้องคุกเข่า เรื่องนั้นแน่นอน... และอาจเป็นสิ่งที่แน่นอนที่สุดในความโกลาหลแล้ว" },
        completion = { "236:97244895:1855506925", "วันนี้ชัยชนะเป็นของเรา เพราะท่านหว่านความบ้าคลั่งใส่ศัตรูของเราทั้งสอง! ท่านสมควรได้รับเกียรติในหมู่แซนดาลาร์ จะมีอะไรแทนคำขอบคุณสำหรับผลงานของท่านได้ดีไปกว่าผ้าคลุมไหล่จอมคลั่งอีกเล่า!" },
        required = { [19719] = { "21:1809784764:157675004", "สายคาดเอว Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Girdle"] = "สายคาดเอว Hakkari บรรพกาล" },
        },
    },
    [8073] = { -- Paragons of Power: The Madcap's Tunic
        title = { "37:1872263312:1873355292", "เครื่องหมายแห่งพลัง — เสื้อจอมคลั่ง" },
        objective = { "211:1040030055:932516202", "นำ Primal Hakkari Aegis ไปมอบให้ Falthir the Sightless ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Revered ขึ้นไป\n\nFalthir the Sightless อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "489:441748885:540030143", "ตาข้ามองไม่เห็นมานานแล้ว แต่ข้าไม่เสียดาย แม้แต่ในเผ่าเรา ที่เครื่องแต่งกายบอกฐานะและหน้าที่ได้ เสื้อผ้าที่ทรงพลังที่สุดยังแผ่พลังที่ตาเปล่ามองไม่เห็น เสื้ออันล้ำค่าของจอมคลั่งแซนดาลาร์ก็เช่นกัน มันแผ่พลังดิบจากความโกลาหลและความบ้าคลั่งที่พวกเขาควบคุมได้\n\nเครื่องหมายแห่งพลังที่ข้าต้องการอยู่ในซุลกูรูบ นำสิ่งที่ข้าตามหามาให้ แล้วข้าจะมอบเสื้อในตำนานที่คู่ควรกับผู้ถักทอความบ้าคลั่งให้ท่านสักตัว" },
        progress = { "26:60227416:1898246210 N 69:1663450781:42944813", "ยินดีต้อนรับกลับเกาะ {name}... ท่านคว้าชัยและนำเครื่องหมายแห่งพลังกลับมาด้วยหรือเปล่า?" },
        completion = { "128:480224650:1538652242 N 80:1486800904:1909178167", "น่าประทับใจ... วันนี้ท่านทำสิ่งที่น้อยคนนักคิดว่าจะทำได้ เผ่าจะยกย่องท่านไปชั่วชีวิต {name} ท่านได้สิทธิ์สวมเสื้อจอมคลั่งแล้ว จงสวมมันพร้อมพรจากเรา" },
        required = { [19724] = { "20:260368875:224970212", "โล่ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Aegis"] = "โล่ Hakkari บรรพกาล" },
        },
    },
    [8074] = { -- Paragons of Power: The Augur's Belt
        title = { "35:1713272718:883388550", "เครื่องหมายแห่งพลัง — เข็มขัดโหรพยากรณ์" },
        objective = { "208:713296712:197385829", "นำ Primal Hakkari Girdle ไปมอบให้ Maywiki of Zuldazar ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Honored ขึ้นไป\n\nMaywiki of Zuldazar อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "490:811672211:1620975819", "โหรพยากรณ์รู้จักโมโจของธาตุ พวกเขาใช้มันนำเผ่าไปสู่ความรุ่งโรจน์ ในวันอันมืดมนหลังจักรวรรดิกูรูบาชิฉีกตัวเองเป็นเสี่ยง ๆ โหรพยากรณ์ของเราพาพวกเราไปถึงที่หลบภัยใน South Seas และพาเรากลับมาที่หุบเขานี้อีกครั้ง ถึงใจกลางภัยร้ายที่กำลังก่อตัวในซุลกูรูบ\n\nนำเครื่องหมายแห่งพลังจากซุลกูรูบมาถวายเพื่อพิสูจน์ว่าท่านคู่ควร แล้วข้าจะมอบเข็มขัดของโหรพยากรณ์ให้ท่าน ข้างในมีโมโจทรงพลังด้วยนะ!" },
        progress = { "151:1188888181:919994770", "ข้าต้องการเครื่องหมายแห่งพลัง เราจะดึงพลังออกจากมันมาใช้สู้กับภัยร้ายจากซุลกูรูบ ท่านนำมาให้ข้าหรือยัง?" },
        completion = { "48:141666247:1583377918 N 298:1274522064:1668069631", "ข้าได้กลิ่นความชั่วร้ายที่พ่ายแพ้ติดตัวท่านมา {name} กลิ่นหอมหวานเชียว... คงเป็นกลิ่นที่ท่านคุ้นเคยดี\n\nข้ารู้ว่าการนำเครื่องหมายแห่งพลังที่ต้องใช้มาทำเข็มขัดมาให้ข้าไม่ใช่งานง่าย สิ่งที่ท่านทำสร้างเกียรติให้ทั้งเผ่าและตัวท่านเองในหมู่พวกเรา เอ้า รับเข็มขัดโหรพยากรณ์ไปสวมเถิด!" },
        required = { [19719] = { "21:1809784764:157675004", "สายคาดเอว Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Girdle"] = "สายคาดเอว Hakkari บรรพกาล" },
        },
    },
    [8075] = { -- Paragons of Power: The Augur's Hauberk
        title = { "38:430063987:450934789", "เครื่องหมายแห่งพลัง — เสื้อเกราะโซ่โหรพยากรณ์" },
        objective = { "208:1420511220:1993660561", "นำ Primal Hakkari Tabard ไปมอบให้ Maywiki of Zuldazar ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Revered ขึ้นไป\n\nMaywiki of Zuldazar อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "499:200201900:1885986849", "เหล่าโหรพยากรณ์ของแซนดาลาร์สวมเสื้อเกราะโซ่ที่เห็นแล้วจำได้ทันที ตัวเสื้อบุด้วยไหมและผ้าเนื้อดี สานเข้ากับโซ่แข็งแรง เป็นสัญลักษณ์ของทั้งความศักดิ์สิทธิ์และอำนาจของพวกเขา อย่าหาเรื่องคนที่อุทิศชีวิตให้การสนทนากับวิญญาณจะดีกว่า...\n\nนำเครื่องหมายแห่งพลังจากซุลกูรูบมาถวายเพื่อพิสูจน์ว่าท่านคู่ควร แล้วข้าจะมอบเสื้อเกราะโซ่ชั้นยอดที่โหรพยากรณ์ของเราต่างอยากสวมให้ท่าน!" },
        progress = { "243:599902656:170705284", "เครื่องหมายแห่งพลังเป็นแหล่งเวทมนตร์สำคัญ เป็นพลังแบบเดียวกับที่ใช้สร้างเสื้อเกราะโซ่โหรพยากรณ์ นำสิ่งที่ข้าต้องการมา แล้วข้าจะแบ่งเครื่องแต่งกายชั้นดีที่โหรพยากรณ์แซนดาลาร์ทุกคนอยากได้ให้ท่าน" },
        completion = { "68:1323561470:1313477471 N 262:227869439:225073383", "ข้ารู้ว่าท่านต้องผ่านอะไรมาบ้างกว่าจะได้เครื่องหมายแห่งพลังมา {name} การปราบภัยร้ายที่ไหลซึมออกจากซุลกูรูบราวกับเมือกโสโครกไม่ง่ายเลย แต่ตอนนี้เรื่องจบลงแล้ว ข้าบอกได้เต็มปากว่าแซนดาลาร์จะยกย่องท่านไปอีกนาน!\n\nนี่ รับเสื้อเกราะโซ่โหรพยากรณ์ไปสวมด้วยความภาคภูมิใจ!" },
        required = { [19722] = { "21:1040067366:1082819017", "เสื้อคลุมตรา Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Tabard"] = "เสื้อคลุมตรา Hakkari บรรพกาล" },
        },
    },
    [8076] = { -- Paragons of Power: The Demoniac's Mantle
        objective = { "214:396464531:922449397", "นำ Primal Hakkari Sash ไปมอบให้ Al'tabim the All-Seeing ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Honored ขึ้นไป\n\nAl'tabim the All-Seeing อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        title = { "40:1672924164:1874544438", "เครื่องหมายแห่งพลัง — ผ้าคลุมไหล่ผู้ครองปีศาจ" },
        description = { "492:173654871:318407885", "ผู้ครองปีศาจปรารถนาจะเป็นหนึ่งเดียวกับพลัง การครอบครองพลังเพียงอย่างเดียวไม่พอ ผู้ครองปีศาจของเราหลายคนพ่ายแพ้ให้ปีศาจ แต่เมื่อมีศัตรูคุกคามเรา โดยเฉพาะในซุลกูรูบ พลังที่ผู้ครองปีศาจปลดปล่อยใส่ศัตรูได้ก็คุ้มกับสิ่งที่ต้องเสีย เราจะอยู่รอดได้ด้วยการบดขยี้ผู้ที่คิดทำลายเรา การล่มสลายของจักรวรรดิกูรูบาชิสอนเราเช่นนี้\n\nเดินทางไปซุลกูรูบและนำเครื่องหมายแห่งพลังที่เราต้องการมา แล้วของล้ำค่าของผู้ครองปีศาจจะเป็นของท่าน" },
        progress = { "193:1267278381:1945985473", "นำเครื่องหมายแห่งพลังจากซุลกูรูบกลับมาแล้วหรือยัง? เราจะดึงพลังที่ซ่อนอยู่ในของเหล่านี้มาใช้เอง และหากท่านทำสำเร็จ เราก็จะมอบพลังตอบแทนให้ท่านด้วย..." },
        completion = { "11:534428891:784080240 N 378:1393413124:1966592107", "ทำได้ดี {name} เครื่องหมายแห่งพลังจากซุลกูรูบควรเตือนใจเราว่าพลังอาจสูญเปล่าได้อย่างไร ชาวกูรูบาชิเคยแข็งแกร่งในยุครุ่งเรือง แต่ปล่อยให้พลังกลืนกินตนเอง ผู้ครองปีศาจรู้ว่าตนก็เสี่ยงคล้ายกัน แต่บ่อยครั้งพลังที่ปลดปล่อยออกมาก็เป็นสิ่งที่จำเป็นต่อการอยู่รอด\n\nจงใช้ผ้าคลุมไหล่นี้ในฐานะพันธมิตรผู้ทรงเกียรติของแซนดาลาร์... มันจะรับใช้ท่านเป็นอย่างดี" },
        required = { [19720] = { "19:373142409:206045942", "ผ้าคาดเอว Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Sash"] = "ผ้าคาดเอว Hakkari บรรพกาล" },
        },
    },
    [8077] = { -- Paragons of Power: The Demoniac's Robes
        objective = { "217:490876150:439792425", "นำ Primal Hakkari Kossack ไปมอบให้ Al'tabim the All-Seeing ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Revered ขึ้นไป\n\nAl'tabim the All-Seeing อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        title = { "39:1232638298:1993471627", "เครื่องหมายแห่งพลัง — เสื้อคลุมผู้ครองปีศาจ" },
        description = { "496:1425166341:1651622878", "เครื่องแต่งกายที่เราสวมในสนามรบคือสัญลักษณ์แห่งพลังสูงสุดของเผ่า เสื้อคลุมผู้ครองปีศาจหลอมรวมผ้ารูนชั้นดีเข้ากับโมโจที่ทรงอานุภาพทำลายล้างจนเป็นผืนเดียวกัน ว่ากันว่ารูปลักษณ์ของเสื้อคลุมทำให้ผู้ที่เห็นหวาดกลัว โดยเฉพาะปีศาจที่ผู้ครองปีศาจจะสยบลงในที่สุด\n\nท่านต้องนำเครื่องหมายแห่งพลังตามที่ข้าระบุจากซุลกูรูบมาให้ข้า งานนี้ยาก... แต่ถ้าทำสำเร็จ ท่านจะได้เสื้อคลุมไว้สวมเอง" },
        progress = { "139:458192104:1671165460 N 1:46:46", "เครื่องหมายแห่งพลัง... ท่านนำกลับมาแล้วหรือ? เมื่อได้ของเหล่านั้นมา เราจึงจะมอบสัญลักษณ์สูงสุดแห่งพลังของผู้ครองปีศาจให้ท่าน {name}" },
        completion = { "342:1982613105:1753681706", "น่าประทับใจ ชัยชนะของท่านในซุลกูรูบทำให้ทั้งเราและคนทั้งโลกรู้ว่าฮักการ์จะไม่มีวันชนะ สักวันท่านอาจต้องเผชิญหน้ากับเทพโลหิตโดยตรง หากถึงวันนั้น ขอให้รู้ไว้ว่าเผ่าแซนดาลาร์ยกย่องท่านเสมอ\n\nอ้อ ข้าว่าเสื้อคลุมเรียบ ๆ ตัวนี้ก็คงช่วยได้เหมือนกัน\n\n<อัลทาบิมขยิบตาให้ท่านอย่างรู้กัน>" },
        required = { [19723] = { "22:1789356227:446504915", "เสื้อเกราะคอสแซ็ก Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Kossack"] = "เสื้อเกราะคอสแซ็ก Hakkari บรรพกาล" },
        },
    },
    [8078] = { -- Paragons of Power: The Vindicator's Belt
        title = { "40:1268613509:447297271", "เครื่องหมายแห่งพลัง — เข็มขัดผู้ลงทัณฑ์" },
        objective = { "210:866124018:2119629518", "นำ Primal Hakkari Girdle ไปมอบให้ Jin'rokh the Breaker ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Honored ขึ้นไป\n\nJin'rokh the Breaker อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "462:2142996463:1288274243", "การล้างแค้นครั้งใหญ่รออยู่ในซุลกูรูบ ฮักการ์ต้องไม่ฟื้นคืนอำนาจ มันทำลายจักรวรรดิกูรูบาชิจากภายใน สังเวยเท่าไรก็ไม่พอ พวกโทรลล์เหลือเพียงเงาของความรุ่งเรืองในอดีต ข้ารู้ว่าทั้งหมดเป็นเพราะฮักการ์\n\nจงเป็นผู้ลงทัณฑ์อย่างที่ท่านเกิดมาเพื่อเป็น ทำลายเหล่าสมุนชั่วร้าย ซุลกูรูบต้องลิ้มรสการล้างแค้นของแซนดาลาร์ นำเครื่องหมายแห่งพลังมาให้ข้าเป็นหลักฐาน ท่านจะได้เข็มขัดผู้ลงทัณฑ์ ท่านจะได้พลังที่แท้จริง\n\nไปเสีย" },
        progress = { "132:2076434694:420998949", "ท่านนำเครื่องหมายแห่งพลังมาหรือยัง? ท่านโค่นศัตรูของเผ่าลงหรือยัง? ฮักการ์ต้องรู้จักโทสะของผู้ลงทัณฑ์!" },
        completion = { "249:1383737495:1442498714", "บัดนี้ท่านรู้จักวิถีของผู้ลงทัณฑ์แล้ว ท่านนำเกียรติมาสู่เผ่า ท่านนำเกียรติมาสู่ตนเอง ท่านนำความเจ็บปวดมาสู่ศัตรูของเรา\n\nเข็มขัดผู้ลงทัณฑ์เป็นของท่านแล้ว ท่านกำลังหลอมรวมเป็นหนึ่งเดียวกับวิถีของผู้ลงทัณฑ์" },
        required = { [19719] = { "21:1809784764:157675004", "สายคาดเอว Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Girdle"] = "สายคาดเอว Hakkari บรรพกาล" },
        },
    },
    [8079] = { -- Paragons of Power: The Vindicator's Breastplate
        title = { "47:496358391:1612722622", "เครื่องหมายแห่งพลัง — เกราะอกผู้ลงทัณฑ์" },
        objective = { "211:752238847:810564158", "นำ Primal Hakkari Kossack ไปมอบให้ Jin'rokh the Breaker ท่านต้องมีชื่อเสียงกับเผ่าแซนดาลาร์ระดับ Revered ขึ้นไป\n\nJin'rokh the Breaker อยู่บน Yojamba Isle ใน Stranglethorn Vale" },
        description = { "435:798150807:663083599 N 1:46:46", "เกราะอกคือสัญลักษณ์แห่งพลังของผู้ลงทัณฑ์ มันตีขึ้นด้วยโมโจทรงพลัง เราฝากไว้กับผู้ที่เรายกย่องเท่านั้น มันคือสัญลักษณ์แห่งการล้างแค้นของแซนดาลาร์\n\nผู้ลงทัณฑ์ต้องเป็นการล้างแค้นเสียเอง ชิงเครื่องหมายแห่งพลังที่เราต้องการมาจากซุลกูรูบ นำมาให้เรา เราจะเอาโมโจที่ถูกขโมยไปคืนมา เราจะให้สมุนของฮักการ์ชดใช้ เราจะตอบแทนท่านด้วยเกราะอกผู้ลงทัณฑ์\n\nไปเถิด จงล้างแค้นแทนเรา {name}" },
        progress = { "112:521333638:1563305812", "ท่านมาที่นี่เพราะคว้าชัยมาแล้วหรือ? ท่านมีเครื่องหมายแห่งพลังไหม? เล่าให้ข้าฟังว่าวันนี้ท่านล้างแค้นอย่างไร!" },
        completion = { "277:774292750:2035992697", "ผลงานของท่านสมควรได้รับการยกย่อง เผ่าย่อมตอบแทนวีรชนของตน ซุลกูรูบได้ลิ้มรสการล้างแค้นของแซนดาลาร์อย่างที่ไม่เคยเจอมาก่อน\n\nผลงานของท่านจะเปิดทางให้คนอื่นทำตาม พวกเขาจะมองท่านเป็นสัญลักษณ์ของพลังที่แท้จริง พวกเขาจะเห็นการล้างแค้นในตัวท่าน!" },
        required = { [19723] = { "22:1789356227:446504915", "เสื้อเกราะคอสแซ็ก Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Primal Hakkari Kossack"] = "เสื้อเกราะคอสแซ็ก Hakkari บรรพกาล" },
        },
    },
    [8101] = { -- The Pebble of Kajaro
        title = { "20:446173160:254735363", "ก้อนกรวดแห่งคาจาโร" },
        completion = { "R 400:44388171:1837795364", "ท่าน{race} ก้อนกรวดที่อยู่ในกรอบเครื่องรางนี้มาจาก Mount Kajaro ใน South Seas ภูเขาแห่งนั้นปะทุรุนแรงอยู่บ่อยครั้ง และหลายครั้งก็มีเวทมนตร์ปะทุออกมาด้วย\n\nเมื่อสายสัมพันธ์ระหว่างท่านกับโทรลล์แซนดาลาร์แน่นแฟ้นขึ้น ก้อนกรวดนี้ก็จะทรงพลังขึ้นตาม จงใช้พลังของมันโค่นศัตรูของเรา ทำให้ได้อย่างภูเขาลูกนั้น รวดเร็ว ระเบิดพลัง และถึงตาย..." },
    },
    [8102] = { -- The Pebble of Kajaro
        title = { "20:446173160:254735363", "ก้อนกรวดแห่งคาจาโร" },
        progress = { "14:1649650394:897424258 C 205:1407414812:1535596590", "ยินดีต้อนรับกลับมา ท่าน{class} ดูก็รู้ว่าท่านใช้ก้อนกรวดมามาก ศัตรูของเราหลายคนล้มตายด้วยพลังเหนือธรรมชาติของท่าน พวกมันทุกข์ทรมานแสนสาหัส ถึงเวลาเสริมพลังให้ก้อนกรวดแล้ว ส่งมาให้ข้า" },
        completion = { "49:1293122373:929242695", "จงทะลวงไปให้ไม่มีใครหยุดได้ ดุจลาวาที่ไหลจากคาจาโร" },
