    },
    [8104] = { -- The Jewel of Kajaro
        title = { "19:684958335:1180253902", "อัญมณีแห่งคาจาโร" },
        progress = { "22:1195845207:409705336 N 28:452278798:1042413683", "ส่งเครื่องรางมาให้ข้า {name} ข้ามีอะไรจะให้ท่านดู" },
        completion = { "335:1063712997:753642381", "<อัลทาบิมทำให้ก้อนกรวดแตกด้วยพลังมหาศาลที่มองไม่เห็น>\n\nเห็นไหม? กรวดก้อนนี้เป็นหินโพรงผลึก ข้างในมีผลึกทรงพลังที่ดูดซับพลังแฝงจากโลกของเรา เมื่อผ่าหินออกเป็นสองซีก ข้าก็ปลดพลังของมันออกมาได้เต็มที่เสียที จงใช้มันทำลายศัตรูของเรา" },
        required = { [19600] = { "16:708009903:731502157", "ก้อนกรวดแห่ง Kajaro" } },
        objectiveLabels = {
            item = { ["Pebble of Kajaro"] = "ก้อนกรวดแห่ง Kajaro" },
        },
    },
    [8106] = { -- Kezan's Taint
        title = { "13:1269535217:934562018", "มลทินแห่งเคซาน" },
        completion = { "22:1680849158:1355702539 C 438:751345369:389476706", "รับเครื่องรางนี้ไว้ ท่าน{class} จงใช้พลังของมันโค่นศัตรูของเราทั้งสอง\n\nจงรู้ไว้ว่าเศษเสี้ยวประวัติศาสตร์ห้อยอยู่ที่คอของท่าน เคซานเคยเป็นดินแดนอันยิ่งใหญ่ของจักรวรรดิแซนดาลาร์ น่าเศร้าที่มลทินของเหล่าเจ้าพ่อการค้าก็อบลินขับไล่พี่น้องผู้ภาคภูมิของข้าออกไป\n\nบัดนี้เคซานเป็นที่ตั้งของ Undermine เมืองหลวงของพวกก็อบลิน แต่ก่อนแปดเปื้อนมลทิน ที่แห่งนั้นเคยรุ่งเรือง และจนถึงทุกวันนี้ ชนของข้ายังถือว่าเคซานเป็นแผ่นดินศักดิ์สิทธิ์" },
    },
    [8107] = { -- Kezan's Taint
        title = { "13:1269535217:934562018", "มลทินแห่งเคซาน" },
        progress = { "45:1919149826:2129251797 N 105:1983240415:1423242599", "ผู้ใดจะได้รับเกียรติในหมู่โทรลล์แซนดาลาร์ ผู้นั้นต้องพิสูจน์ตัวเอง {name} รางวัลที่มากับเกียรติมีทั้งมิตรภาพและพันธมิตร...\n\nส่งเครื่องรางมา ข้าจะเสริมพลังให้" },
        completion = { "24:1383570113:487316828 C 71:624215762:1140005367", "จงดึงพลังจากความมืด ท่าน{class} โอบรับเงามืด ให้มลทินแห่งเคซานช่วยเสริมวิชาอันมืดมนของท่าน" },
