    [8109] = { -- Kezan's Unstoppable Taint
        title = { "25:1793436735:1236002038", "มลทินแห่งเคซานอันไร้ผู้ต้าน" },
        progress = { "24:1870026286:334218344 C 200:696467891:17587493", "อัญเชิญปีศาจของท่านออกมา ท่าน{class} ให้พวกมันอาบพลังจากมลทินแห่งเคซาน บัญชาพวกมันในสนามรบ! บดขยี้ศัตรู!\n\nใช่แล้ว... ถึงเวลาเสริมพลังให้มลทินแห่งเคซานเป็นครั้งสุดท้าย ส่งเครื่องรางมาให้ข้า" },
        completion = { "105:826685074:1461927092 C 41:334031510:1088898431", "ถลกเนื้อออกจากศพพวกมัน ดูเงามืดกลืนกินพวกฮักคารี ดึงพลังจากความกลัวของพวกมัน ท่าน{class} ให้มลทินแห่งเคซานช่วยเสริมพลังนี้..." },
