    [8116] = { -- Vision of Voodress
        title = { "18:238516895:47370307", "นิมิตแห่งวูเดรส" },
        completion = { "334:2116169137:1865406240", "ท่านกับเมย์วิกีมีอะไรเหมือนกันนะ พวก เราเป็นชาแมนทั้งคู่! แต่เมย์วิกีน่ะเป็นผู้รู้เรื่องลี้ลับ ส่วนท่านยังเป็นมือใหม่ ถึงอย่างนั้นเราต่างก็รู้ว่าเหล่าวิญญาณผู้ยิ่งใหญ่มอบอะไรให้เรา\n\nข้ามอบลูกแก้วนี้ให้ท่านคล้องคอ ลองมองลึกเข้าไป จะเห็นหมู่บ้านวูเดรสใน South Seas! ขอให้ภาพนั้นทำให้ท่านชื่นใจ!" },
    },
    [8117] = { -- Vision of Voodress
        title = { "18:238516895:47370307", "นิมิตแห่งวูเดรส" },
        progress = { "11:396333398:1208841741 N 200:144478824:1503800313", "ข่าวดี {name} ช่วงนี้โมลธอร์เอ่ยปากชมท่านใหญ่ เขาว่าท่านกำลังจะเป็นวีรชนแซนดาลาร์ตัวจริง\n\nเขายังบอกให้เมย์วิกีขัดลูกแก้วของท่านอีกหน่อย! ส่งมานี่ เมย์วิกีจะทำให้นิมิตสว่างขึ้น", variants = { { "197:215274126:1125020160 N 1:46:46", "ชาแมนเอ๋ย! เมย์วิกีเล่นมุกนะ!\n\n<เมย์วิกีหัวเราะ>\n\nท่านใช้พลังของวิญญาณและธาตุเล่นงานศัตรูในซุลกูรูบอยู่สินะ? สรรเสริญเหล่าวิญญาณ!\n\nเมย์วิกีจะทำให้ลูกแก้วท่านสว่างขึ้น ส่งมานี่ {name}" } } },
        completion = { "63:732588300:417170441", "ระวังวิญญาณชั่วของพวกฮักคารีด้วยนะ พวก พูดจริง ๆ พวกมันน่าขนลุก", variants = { { "23:1456744248:1322716079 N 85:1747932246:816184857", "ลองดูตอนนี้สิ {name} เห็นวูเดรสชัดกว่าเดิมใช่ไหม? ให้พลังดั้งเดิมไหลผ่านตัวท่านเถิด พวก" } } },
        required = { [19606] = { "18:238516895:47370307", "นิมิตของ Voodress" } },
        objectiveLabels = {
            item = { ["Vision of Voodress"] = "นิมิตของ Voodress" },
        },
    },
    [8118] = { -- Vision of Voodress
        title = { "18:238516895:47370307", "นิมิตแห่งวูเดรส" },
        progress = { "197:215274126:1125020160 N 1:46:46", "ชาแมนเอ๋ย! เมย์วิกีเล่นมุกนะ!\n\n<เมย์วิกีหัวเราะ>\n\nท่านใช้พลังของวิญญาณและธาตุเล่นงานศัตรูในซุลกูรูบอยู่สินะ? สรรเสริญเหล่าวิญญาณ!\n\nเมย์วิกีจะทำให้ลูกแก้วท่านสว่างขึ้น ส่งมานี่ {name}", variants = { { "11:396333398:1208841741 N 200:144478824:1503800313", "ข่าวดี {name} ช่วงนี้โมลธอร์เอ่ยปากชมท่านใหญ่ เขาว่าท่านกำลังจะเป็นวีรชนแซนดาลาร์ตัวจริง\n\nเขายังบอกให้เมย์วิกีขัดลูกแก้วของท่านอีกหน่อย! ส่งมานี่ เมย์วิกีจะทำให้นิมิตสว่างขึ้น" } } },
        completion = { "23:1456744248:1322716079 N 85:1747932246:816184857", "ลองดูตอนนี้สิ {name} เห็นวูเดรสชัดกว่าเดิมใช่ไหม? ให้พลังดั้งเดิมไหลผ่านตัวท่านเถิด พวก", variants = { { "63:732588300:417170441", "ระวังวิญญาณชั่วของพวกฮักคารีด้วยนะ พวก พูดจริง ๆ พวกมันน่าขนลุก" } } },
        required = { [19607] = { "18:238516895:47370307", "นิมิตของ Voodress" } },
        objectiveLabels = {
            item = { ["Vision of Voodress"] = "นิมิตของ Voodress" },
        },
    },
    [8119] = { -- The Unmarred Vision of Voodress
        title = { "31:1011163846:1320458046", "นิมิตแห่งวูเดรสอันกระจ่าง" },
        progress = { "47:1587613698:28535175 N 108:646562461:1740265461", "<เมย์วิกีชี้ไปที่เครื่องรางของท่าน>\n\nดูสิ {name}! มันมีชีวิตแล้ว เหล่าวิญญาณร่ายรำอยู่รอบลูกแก้ว\n\nส่งให้เมย์วิกีปรับอีกเป็นครั้งสุดท้ายเถิด" },
        completion = { "9:1747270800:1903969067 N 196:615289290:1218725029", "สักวันหนึ่ง {name} ท่านจะใช้ลูกแก้วนี้คุยกับข้าโดยตรงได้ เมื่อศึกกับฮักการ์จบลงและเมย์วิกีได้กลับบ้าน เรามาวิงวอนเหล่าวิญญาณให้วันนั้นมาถึงไว ๆ กันเถิด" },
        required = { [19608] = { "18:238516895:47370307", "นิมิตของ Voodress" } },
        objectiveLabels = {
            item = { ["Vision of Voodress"] = "นิมิตของ Voodress" },
        },
    },
    [8141] = { -- Zandalarian Shadow Talisman
        title = { "27:695925060:1696064156", "เครื่องรางเงาแซนดาลาร์" },
        completion = { "28:1821171032:274366956 C 318:247128972:2110804585 R 154:651027296:231063149", "ท่านก้าวหน้าเร็วมาก ท่าน{class}หนุ่มสาว อาจถึงเวลารับท่านเข้า Shera Ali'kh แล้ว ในภาษาแซนดาลาร์แปลว่า ‘หัตถ์แห่งความตาย’ พวกเราเป็นนักลอบสังหารให้จักรวรรดิแซนดาลาร์มาหลายพันปี เรานิ่งดูดายนานเกินไป ปล่อยให้พวกฮักคารีแข็งแกร่งขึ้น เราต้องเผชิญหน้ากับฮักการ์อีกครั้ง แต่คราวนี้เหล่า{race}มิได้รวมตัวหนุนหลังเรา ท่านกับพันธมิตรจึงต้องช่วยกันโค่นเทพโลหิตและสมุนของมัน!\n\nสวมเครื่องรางนี้ไว้ ให้มันช่วยท่านระหว่างเดินทาง", variants = { { "28:1821171032:274366956 C 477:452986834:1180525674", "ท่านก้าวหน้าเร็วมาก ท่าน{class}หนุ่มสาว อาจถึงเวลารับท่านเข้า Shera Ali'kh แล้ว ในภาษาแซนดาลาร์แปลว่า ‘หัตถ์แห่งความตาย’ พวกเราเป็นนักลอบสังหารให้จักรวรรดิแซนดาลาร์มาหลายพันปี เรานิ่งดูดายนานเกินไป ปล่อยให้พวกฮักคารีแข็งแกร่งขึ้น เราต้องเผชิญหน้ากับฮักการ์อีกครั้ง แต่คราวนี้เหล่าโทรลล์มิได้รวมตัวหนุนหลังเรา ท่านกับพันธมิตรจึงต้องช่วยกันโค่นเทพโลหิตและสมุนของมัน!\n\nสวมเครื่องรางนี้ไว้ ให้มันช่วยท่านระหว่างเดินทาง" } } },
    },
    [8142] = { -- Zandalarian Shadow Talisman
        title = { "27:695925060:1696064156", "เครื่องรางเงาแซนดาลาร์" },
        progress = { "12:893490672:478301359 N 205:1825467518:2134913533", "น่าประทับใจ {name} ท่านมีพรสวรรค์ด้านการสังหารแบบที่ข้าไม่ได้สัมผัสจากใครมาหลายปี แม้แต่โมลธอร์ก็รู้ว่าท่านทำอะไรเพื่อแซนดาลาร์บ้าง ถึงเวลาเสริมพลังให้เครื่องรางของท่านขึ้นอีก ส่งมาให้ข้า", variants = { { "65:1788465868:1295269106 N 143:2086723479:299428176", "ข้าสัมผัสได้ว่าท่านปลิดชีพพวกฮักคารีไปนับไม่ถ้วน {name} กลิ่นเหม็นของโมโจพวกมันติดตัวท่านมาด้วย\n\nเครื่องรางเงาคงช่วยในการกวาดล้างสินะ? ส่งมาให้ข้า ข้าจะเสริมพลังให้" } } },
        completion = { "71:1570509447:1262181127 C 57:1351328006:449776811", "เหลืออีกเพียงอย่างเดียวที่ข้าเสริมให้เครื่องรางได้ ท่าน{class} เมื่อถึงเวลาที่เหมาะสมข้าจะจัดการให้", variants = { { "174:1402355561:1964308252", "นักลอบสังหารฝีมืออย่างท่าน ใครเห็นก็ควรหลีกทางให้ ศัตรูของท่านต้องรู้จักเกรงใจ! พวกมันจะรู้เมื่อเห็นประกายของหัตถ์แห่งความตาย ซึ่งตอนนั้นก็สายไปเสียแล้ว..." } } },
        required = { [19614] = { "27:695925060:1696064156", "เครื่องรางเงาแห่งแซนดาลาร์" } },
        objectiveLabels = {
            item = { ["Zandalarian Shadow Talisman"] = "เครื่องรางเงาแห่งแซนดาลาร์" },
        },
    },
