    [8145] = { -- The Maelstrom's Tendril
        title = { "23:790363176:1077859763", "หนวดแห่งมหาวังวน" },
        completion = { "460:652844983:888947297", "ชาวแซนดาลาร์ยกย่องวิชาชีพนักล่า ยอดนักล่าของเราจะเดินทางไปถึงขอบมหาวังวนเพื่อพิสูจน์ความมุ่งมั่น\n\nพวกเขาดึงสาหร่ายที่เรียกว่าหนวดแห่งมหาวังวนขึ้นมาจากใจกลางทะเล แล้วถักสาหร่ายเป็นเครื่องรางและลงเวทเพื่อเสริมความแม่นยำกับพลัง\n\nบัดนี้ข้ามอบหนวดแห่งมหาวังวนที่ถักไว้ชั้นหนึ่งให้ท่าน เมื่อสายสัมพันธ์ระหว่างท่านกับแซนดาลาร์แน่นแฟ้นขึ้น ข้าจะถักพลังเพิ่มลงในเครื่องราง" },
    },
    [8146] = { -- The Maelstrom's Tendril
        title = { "23:790363176:1077859763", "หนวดแห่งมหาวังวน" },
        progress = { "4:1110228981:147916455 N 315:1996479529:929909722", "อา {name} ดีใจที่ได้กลิ่นท่านอีกครั้ง\n\n<ฟัลเธียร์ยิ้มกว้าง>\n\nขออภัยเรื่องมุกของข้าด้วย บางทีก็เหม็นเอาเรื่อง\n\nข้าสัมผัสได้ว่าท่านทำให้ศัตรูของเราทุกข์ทรมานยิ่งนัก กองกำลังของฮักการ์ร้องชื่อท่านด้วยความโกรธ ยอดเยี่ยมจริง ๆ\n\nท่านสมควรได้ถักเครื่องรางเพิ่มอีกชั้น ส่งมาให้ข้า" },
        completion = { "53:1431890971:1196207750", "ให้พวกมันไปไถ่บาปที่ปลายกระสุนของท่านเถิด" },
        required = { [19618] = { "19:1192965520:694865230", "เกลียวแห่งมหาวังวน" } },
        objectiveLabels = {
            item = { ["Maelstrom's Tendril"] = "เกลียวแห่งมหาวังวน" },
        },
    },
    [8147] = { -- The Maelstrom's Tendril
        title = { "23:790363176:1077859763", "หนวดแห่งมหาวังวน" },
        completion = { "53:1431890971:1196207750", "ให้พวกมันไปไถ่บาปที่ปลายกระสุนของท่านเถิด", variants = { { "74:1107031202:708940919 C 1:46:46", "ข้าจะถักเสริมพลังให้เครื่องรางของท่านได้อีกเพียงชั้นเดียวเท่านั้น ท่าน{class}" } } },
        progress = { "4:1110228981:147916455 N 315:1996479529:929909722", "อา {name} ดีใจที่ได้กลิ่นท่านอีกครั้ง\n\n<ฟัลเธียร์ยิ้มกว้าง>\n\nขออภัยเรื่องมุกของข้าด้วย บางทีก็เหม็นเอาเรื่อง\n\nข้าสัมผัสได้ว่าท่านทำให้ศัตรูของเราทุกข์ทรมานยิ่งนัก กองกำลังของฮักการ์ร้องชื่อท่านด้วยความโกรธ ยอดเยี่ยมจริง ๆ\n\nท่านสมควรได้ถักเครื่องรางเพิ่มอีกชั้น ส่งมาให้ข้า", variants = { { "178:933465666:2048782407 N 100:1613895032:1392768033", "แม้จะอยู่ไกลถึงที่นี่ ข้าก็ยังได้ยินเสียงระดมยิงของท่านที่กำลังบดขยี้ศัตรู เสียงกรีดร้องของพวกมันก้องกังวานด้วยความทรมาน\n\nท่านสร้างชื่อเสียงไว้ไม่น้อยในหมู่โทรลล์แห่ง Zandalar {name} พวกเราซาบซึ้งในทุกสิ่งที่ท่านทำให้\n\nส่งเครื่องรางมาให้ข้า ข้าจะได้ถักเสริมพลังให้อีกชั้นหนึ่ง" } } },
        required = { [19619] = { "19:1192965520:694865230", "เกลียวแห่งมหาวังวน" } },
        objectiveLabels = {
            item = { ["Maelstrom's Tendril"] = "เกลียวแห่งมหาวังวน" },
        },
    },
    [8148] = { -- Maelstrom's Wrath
        title = { "17:1989297800:723336618", "โทสะแห่งมหาวังวน" },
        progress = { "43:599153658:1699387673 N 151:192597618:1849555011", "โมลธอร์นำพระดำรัสจากราชาราสตาคานมาบอก {name} ราชสำนักประทับใจมากที่ท่านบดขยี้กองกำลังฮักคารี ข้าได้รับมอบหมายให้ถักพลังชั้นสุดท้ายลงในเครื่องรางของท่าน ส่งมาให้ข้า" },
        completion = { "40:387723984:1425845981 C 118:154233574:255656924", "การเดินทางของท่านเพิ่งเริ่มต้น ท่าน{class}ผู้เยาว์ สักวันท่านอาจไปถึงมหาวังวนและได้มองเข้าไปในใจกลางโลก\n\nขอให้ท่านมีทั้งพลังและความทรหด!" },
        required = { [19620] = { "19:1192965520:694865230", "เกลียวแห่งมหาวังวน" } },
        objectiveLabels = {
            item = { ["Maelstrom's Tendril"] = "เกลียวแห่งมหาวังวน" },
        },
    },
    [8181] = { -- Confront Yeh'kinya
        title = { "18:28486092:1018302692", "เผชิญหน้าเยห์คินยา" },
        objective = { "21:1255619580:749834971", "ไปคุยกับ Yeh'kinya" },
        description = { "54:1586920095:1157734635 N 308:1196139091:1305635886", "การศึกษาศิลาจารึกโมชารูทำให้ข้าพบข่าวร้าย {name} ฮักการ์ในร่างที่แท้จริง ตัวเทพเอง สามารถถือกำเนิดใหม่จากไข่ใบเดียวกับที่ท่านใช้กักขังมัน เยห์คินยาบอกท่านว่าไข่จะกักความชั่วร้ายของมันไว้ แต่ไข่มีไว้ให้ความชั่วร้ายนั้นเกิดใหม่! เจ้าโทรลล์นั่นหลอกท่านแล้ว!\n\nไปหาเยห์คินยาและทวงไข่คืนจากเขา ภาวนาให้เรายังหยุดการกลับมาของฮักการ์ได้ทัน!" },
        completion = { "346:496755368:1161853768 N 50:622116351:91071500", "อ้อ เจ้าไปคุยกับไอรอนบูต คนแคระแก่คนนั้น แล้วพบศิลาจารึกโมชารูที่สาบสูญสินะ? เจ้านักสำรวจจอมสอดรู้...\n\nช่างเถอะ สายเกินจะช่วยโลกนี้แล้ว ฮักการ์ถือกำเนิดใหม่และกำลังสะสมพลังอยู่ในส่วนลึกของซุลกูรูบ อาณาจักรโทรลล์โบราณ! มันมาแล้ว! มันจะปกครองด้วยเลือดและความหวาดกลัว!\n\nขอบใจนะ {name} เจ้านี่แหละช่วยให้ผู้ถลกวิญญาณกลับมาได้เร็วขึ้น!" },
    },
    [8183] = { -- The Heart of Hakkar
        title = { "19:474927019:881127162", "หัวใจของฮักการ์" },
        objective = { "53:1020581045:1375769188", "นำ Heart of Hakkar ไปมอบให้ Molthor บน Yojamba Isle" },
        description = { "133:142840828:174997133", "หัวใจของฮักการ์ลุกไหม้จากภายใน แม้ผู้ถลกวิญญาณจะพ่ายแพ้ แต่แก่นพลังของมันยังคงอยู่ในอวัยวะต้องสาปชิ้นนี้" },
        progress = { "N 81:1077491994:1240109517", "{name} กลิ่นเหม็นของวิญญาณชั่วร้ายอบอวลรอบตัวท่าน ท่านถูกผู้ถลกวิญญาณสาปมาหรือ?" },
        completion = { "79:758798602:1860901910 N 78:140774634:1476415114", "อา หัวใจของฮักการ์ ผู้ถลกวิญญาณถูกสังหารแล้วสินะ! โลกของเรารอดแล้ว!\n\n{name} คุณความดีที่ท่านทำเพื่อเรานั้นยิ่งใหญ่เกินคำบรรยาย ท่านคือวีรชนของแผ่นดินนี้อย่างแท้จริง!" },
        required = { [19802] = { "15:526081644:1147054680", "หัวใจของ Hakkar" } },
        objectiveLabels = {
            item = { ["Heart of Hakkar"] = "หัวใจของ Hakkar" },
        },
    },
    [8184] = { -- Presence of Might
        title = { "17:19417307:788416422", "อำนาจแห่งพละกำลัง" },
        progress = { "424:1637845238:1489419261", "แซนซาสร้างมนตร์เสริมพลังโบราณของโทรลล์ได้เมื่อมีวัตถุดิบที่เหมาะสม\n\nอย่างแรกคือ Primal Hakkari Idol ซึ่งต้องชิงมาจากแม่ทัพฮักคารีที่ทรงพลังที่สุด ได้แก่ Jin'do และ Bloodlord\n\nอย่างที่สองคือ Punctured Voodoo Doll หาได้จากกองขยะที่เกลื่อนอยู่ทั่วที่โสโครกแห่งนี้ ลองค้นใน Jinxed Hoodoo Pile ดู\n\nนำของสองอย่างนี้มาให้ข้า แล้วข้าจะสร้างมนตร์เสริมพลังให้ท่าน!" },
        completion = { "13:32841776:1420137397 C 28:961695308:246032244", "จงใช้ให้ดี ท่าน{class} อย่าได้ปรานีพวกฮักคารี!" },
        objective = { "113:1557147926:1448162904", "นำของเหล่านี้มาให้ข้า แล้วข้าจะร่ายมนตร์เสริมพลังให้เจ้า!\nPrimal Hakkari Idol\nPunctured Voodoo Doll" },
        description = { "418:1912450736:1912885598", "แซนซาร่ายมนตร์เสริมพลังโบราณของโทรลล์ได้เมื่อมีวัตถุดิบที่เหมาะสม อย่างแรกคือ Primal Hakkari Idol ซึ่งต้องชิงมาจากแม่ทัพฮักคารีที่ทรงพลังที่สุด ได้แก่ Jin'do และ Bloodlord\n\nอย่างที่สองคือ Punctured Voodoo Doll หาได้จากกองเศษขยะที่กระจัดกระจายอยู่ทั่วสถานที่โสมมแห่งนี้ ลองค้นในกองฮูดูต้องคำสาป\n\nนำของเหล่านี้มาให้ข้า แล้วข้าจะร่ายมนตร์เสริมพลังให้เจ้า!" },
        required = { [19813] = { "21:497339407:987597280", "ตุ๊กตาวูดูมีรอยเจาะ" }, [22637] = { "19:203593602:183615995", "รูปเคารพ Hakkari บรรพกาล" } },
        objectiveLabels = {
            item = { ["Punctured Voodoo Doll"] = "ตุ๊กตาวูดูมีรอยเจาะ", ["Primal Hakkari Idol"] = "รูปเคารพ Hakkari บรรพกาล" },
        },
    },
