    [8195] = { -- Zulian, Razzashi, and Hakkari Coins
        title = { "35:326525383:1790473117", "เหรียญซูเลียน ราซซาชิ และฮักคารี" },
        progress = { "490:1287029549:42636749", "ข้าตามหาเครื่องหมายแห่งพลังที่เรียกว่าเหรียญประจำเผ่า ผู้คนหลายกลุ่มในซุลกูรูบใช้เหรียญเหล่านี้เป็นเงินตรา แต่ละเหรียญมีโมโจทรงพลังแฝงอยู่\n\nเหรียญมีอยู่เก้าชนิด พวกพ้องของข้าตามหาบางชนิดเพื่อนำไปใช้กับเกราะที่มอบให้วีรชนแซนดาลาร์ หากท่านมีเหลือ ข้าจะให้ Honor Token หนึ่งชิ้นแลกกับเหรียญหนึ่งชุด ชุดละสามเหรียญ ท่านนำโทเคนไปใช้กับ Rin'wosho the Trader ได้ เขามีของพิเศษสำหรับวีรชนของเรา" },
        completion = { "196:1800912828:1786760025 N 37:221474386:468392312", "ยอดเยี่ยม เหรียญชุดนี้เหมาะจะนำไปสมทบกับที่เราสะสมไว้ เราจะใช้มันป้องกันเผ่าจากการคืนอำนาจของเทพโลหิต ท่านได้ทั้ง Honor Token และคำขอบคุณจากเผ่า {name}!" },
        required = { [19698] = { "11:1311687694:288560058", "เหรียญ Zulian" }, [19699] = { "13:1647381820:728964713", "เหรียญ Razzashi" }, [19700] = { "12:227471526:1763400376", "เหรียญ Hakkari" } },
        objectiveLabels = {
            item = { ["Zulian Coin"] = "เหรียญ Zulian", ["Razzashi Coin"] = "เหรียญ Razzashi", ["Hakkari Coin"] = "เหรียญ Hakkari" },
        },
    },
    [8196] = { -- Essence Mangoes
        title = { "15:312325501:1083798495", "มะม่วงเปี่ยมพลัง" },
        progress = { "430:815296315:2104413590", "มะม่วงเปี่ยมพลังนี้ขึ้นตามเกาะหลายแห่งใน South Seas แค่กินลูกเดียวก็สดชื่นทั้งกายและใจ ถ้าไม่เคยลองถือว่าพลาดแล้ว!\n\nบนเกาะเรามีมากพอจะแบ่งให้ท่านสักหยิบมือแลกกับ Zandalar Honor Token หนึ่งชิ้น ถ้าอยากรู้ว่าจะหาโทเคนได้อย่างไร ไปถาม Vinchaxa ได้ ถ้ารู้อยู่แล้ว เรามาแลกกันเลยดีกว่า!" },
        completion = { "104:1191944102:2101711663", "แลกกันอย่างยุติธรรม สหาย ขอให้เอร็ดอร่อยกับผลไม้ฉ่ำหวานจาก South Seas พร้อมพรจากเผ่าเรา" },
        required = { [19858] = { "20:974177135:798191199", "เหรียญเกียรติยศแซนดาลาร์" } },
        objectiveLabels = {
            item = { ["Zandalar Honor Token"] = "เหรียญเกียรติยศแซนดาลาร์" },
        },
    },
    [8201] = { -- A Collection of Heads
        title = { "21:132906410:1471232198", "รวบรวมหัวโทรลล์" },
        objective = { "96:1713613767:1945256471", "ร้อย Channeler's Head 5 หัวเข้าด้วยกัน แล้วนำ Collection of Troll Heads กลับไปให้ Exzhal บน Yojamba Isle" },
        description = { "415:246320829:588171455", "เรื่องนั้นจริง ฮักการ์อยู่ในซุลกูรูบและกำลังอาบพลังของเหล่าเทพของเรา มหาปุโรหิตที่ถูกครอบงำกำลังถ่ายเทพลังของเทพศักดิ์สิทธิ์ที่สุดของเราให้ผู้ถลกวิญญาณ อีกไม่นานมันจะมีพลังเหนือสิ่งมีชีวิตใด ๆ ในอาเซรอธ เราต้องหยุดมัน!\n\nเอาเชือกศักดิ์สิทธิ์นี้ไป ร้อยหัวของมหาปุโรหิตที่ถ่ายเทพลังของเหล่าเทพของเราเข้าด้วยกัน\n\nเสร็จแล้วกลับมาหาข้า" },
        progress = { "37:1619920769:1673828978 N 46:874821080:1499902292", "รวบรวมหัวมาได้แล้วหรือยัง {name}? เราต้องหยุดฮักการ์ก่อนที่มันจะได้พลังเพิ่ม!" },
        completion = { "125:115723139:1392720728 N 92:1261930983:35028143", "ท่านได้หัวพวกมันมาแล้ว! ท่านหยุดการปล้นพลังของเหล่าเทพของเราและทำให้ฮักการ์อ่อนแอลง!\n\nสิ่งที่ท่านทำสมกับเป็นวีรชนจริง ๆ {name} ขอให้หัวของโทรลล์ทาสพวกนี้ร้องขอความเมตตาจากท่านไปอีกนาน แม้เลือดของพวกมันจะเย็นชืดแล้ว" },
        required = { [19880] = { "25:1123599806:1922834057", "ชุดศีรษะ Gurubashi" } },
        objectiveLabels = {
            item = { ["Gurubashi Head Collection"] = "ชุดศีรษะ Gurubashi" },
        },
    },
    [8227] = { -- Nat's Measuring Tape
        title = { "20:1491242474:1190841106", "สายวัดของแนต" },
        objective = { "61:945920805:1742648103", "นำ Nat's Measuring Tape กลับไปให้ Nat Pagle ใน Dustwallow Marsh" },
        description = { "157:1697743136:1468493168", "ท่ามกลางเหยื่อตกปลาและอุปกรณ์ที่แตกหัก มีสายวัดผ้าไหมม้วนอยู่ บนสายวัดมีป้ายเขียนไว้ว่า\n\n‘Nat Pagle, Dustwallow Marsh’" },
        progress = { "49:707740820:1674209293", "สวัสดีพ่อหนุ่ม มาตกปลาหรือ?", variants = { { "48:224826591:1581697611", "สวัสดีแม่หนู มาตกปลาหรือ?" } } },
        completion = { "254:1814647173:187274637", "โอ้ เจอสายวัดคู่ใจของข้าด้วย! ข้าชอบเส้นนี้มาก ปลาตัวโตที่สุดหลายตัวที่ข้าเคยตกได้ก็ใช้เส้นนี้วัด...\n\nแต่ว่าข้าทำสายวัดหายในซุลกูรูบ... ท่านไปซุลกูรูบมาแล้วหรือ? ได้เห็น Gahz'ranka ในตำนานไหม?\n\nแล้ว... อยากตกมันไหมล่ะ?" },
    },
