        },
    },
    [8239] = { -- Sandfury, Skullsplitter, and Bloodscalp Coins
        progress = { "490:1287029549:42636749", "ข้าตามหาเครื่องหมายแห่งพลังที่เรียกว่าเหรียญประจำเผ่า ผู้คนหลายกลุ่มในซุลกูรูบใช้เหรียญเหล่านี้เป็นเงินตรา แต่ละเหรียญมีโมโจทรงพลังแฝงอยู่\n\nเหรียญมีอยู่เก้าชนิด พวกพ้องของข้าตามหาบางชนิดเพื่อนำไปใช้กับเกราะที่มอบให้วีรชนแซนดาลาร์ หากท่านมีเหลือ ข้าจะให้ Honor Token หนึ่งชิ้นแลกกับเหรียญหนึ่งชุด ชุดละสามเหรียญ ท่านนำโทเคนไปใช้กับ Rin'wosho the Trader ได้ เขามีของพิเศษสำหรับวีรชนของเรา" },
        completion = { "196:1800912828:1786760025 N 37:221474386:468392312", "ยอดเยี่ยม เหรียญชุดนี้เหมาะจะนำไปสมทบกับที่เราสะสมไว้ เราจะใช้มันป้องกันเผ่าจากการคืนอำนาจของเทพโลหิต ท่านได้ทั้ง Honor Token และคำขอบคุณจากเผ่า {name}!" },
        title = { "45:955547031:431969618", "เหรียญแซนด์ฟิวรี สกัลล์สปลิตเตอร์ และบลัดสกัลป์" },
        required = { [19704] = { "13:1413461246:730929202", "เหรียญ Sandfury" }, [19705] = { "18:1151663686:1301214497", "เหรียญ Skullsplitter" }, [19706] = { "15:1271516996:867923390", "เหรียญ Bloodscalp" } },
        objectiveLabels = {
            item = { ["Sandfury Coin"] = "เหรียญ Sandfury", ["Skullsplitter Coin"] = "เหรียญ Skullsplitter", ["Bloodscalp Coin"] = "เหรียญ Bloodscalp" },
        },
    },
    [8240] = { -- A Bijou for Zanza
        title = { "17:1102647145:1331863853", "อัญมณีสำหรับแซนซา" },
        objective = { "134:887655679:1397219845", "นำ Hakkari Bijou จากซุลกูรูบชิ้นใดก็ได้หนึ่งชิ้นไปทำลายที่ Altar of Zanza บน Yojamba Isle เมื่อทำเสร็จแล้วให้คุยกับ Vinchaxa ที่อยู่ใกล้ ๆ" },
        description = { "428:130319199:1287200619", "การทำลายอัญมณีฮักคารีสำคัญยิ่งต่อพวกเรา เราจึงยินดีให้คนนอกเผ่าลงมือทำด้วยตัวเอง!\n\nนำอัญมณีชิ้นใดก็ได้หนึ่งชิ้นที่พบในซุลกูรูบไปทำลายที่ Altar of Zanza ครั้งนี้ครั้งเดียว ข้าจะมอบ Honor Token ของเผ่าให้เพิ่มอีกหนึ่งชิ้น นอกเหนือจากที่ท่านจะได้รับตามปกติ\n\nจงสัมผัสพรของแซนซาด้วยตัวท่านเอง!" },
        progress = { "104:1034428164:842324384", "ท่านทำลายอัญมณีที่ Altar of Zanza แล้วหรือยัง? ลงมือเถิด แล้วแซนซาจะประทานพรแก่ท่านสองเท่า!" },
        completion = { "227:1133690911:1692397802 N 230:2049661467:2140558556", "ยอดเยี่ยม... อัญมณีทุกชิ้นที่เราชิงจากสมุนเทพโลหิตทำให้พวกเราเข้าใกล้ชัยชนะเด็ดขาดเข้าไปอีกก้าว การกระทำอันสูงส่งของท่านนำเกียรติมาสู่ทั้งแซนดาลาร์และตัวท่านเอง\n\nจำไว้ {name} ท่านนำอัญมณีที่พบในซุลกูรูบมาทำลายที่แท่นบูชาได้เสมอ ทุกชิ้นที่ทำลายจะทำให้เผ่ายอมรับท่านมากขึ้นและได้รับ Honor Token หนึ่งชิ้น ถ้ายังไม่มีโทเคนติดตัว อย่าลืมเว้นช่องว่างในกระเป๋าไว้ด้วย" },
    },
    [8243] = { -- Zanza's Potent Potables
        title = { "23:1359018776:1326731734", "เครื่องดื่มทรงพลังของแซนซา" },
        progress = { "444:1629965470:904394906", "เมื่อฐานะในเผ่าสูงขึ้น ท่านก็มีสิทธิ์เข้าถึงเครื่องดื่มที่ทรงพลังขึ้นของเรา ดูนี่สิ... เครื่องดื่มพวกนี้มีโมโจเข้มข้น ได้รับพรจากแซนซา และเหมาะกับนักผจญภัยทุกวิถี!\n\nท่านเลือกได้หนึ่งอย่างจากสามอย่างที่ข้าเสนอ แลกกับ Zandalar Honor Token หนึ่งชิ้น จำไว้ว่าในเวลาเดียวกันท่านจะรับผลของเครื่องดื่มได้เพียงชนิดเดียว\n\nพร้อมแลกเมื่อไรก็บอกข้า!" },
        completion = { "83:2112213512:1242588013", "แลกกันอย่างยุติธรรม สหาย ขอให้มีความสุขกับพรของแซนซา รับไปด้วยความยินดีจากเรา!" },
        required = { [19858] = { "20:974177135:798191199", "เหรียญเกียรติยศแซนดาลาร์" } },
        objectiveLabels = {
            item = { ["Zandalar Honor Token"] = "เหรียญเกียรติยศแซนดาลาร์" },
        },
    },
    [8246] = { -- Signets of the Zandalar
        title = { "23:1118172027:505658762", "ตราประทับแห่งแซนดาลาร์" },
        progress = { "N 444:94963554:126999833", "{name} ข้ามีของพิเศษสำหรับผู้ที่แซนดาลาร์ยกย่องสูงส่งอย่างท่าน ส่งตรงจากบ้านของเราใน South Seas... ตราประทับแห่งแซนดาลาร์! ใช้ตราเหล่านี้เสริมพลังอุปกรณ์สวมไหล่ชิ้นใดก็ได้ที่ท่านมี ไม่ว่าท่านจะแสวงหาพละกำลัง โมโจ หรือความสงบ ข้ามีสิ่งที่ท่านต้องการ!\n\nข้าขอ Zandalar Honor Token สิบห้าชิ้นแลกกับตราประทับหนึ่งชิ้นที่ท่านเลือก ถ้าโทเคนพร้อมแล้ว ข้าก็พร้อมแลก!" },
        completion = { "83:1913717347:1142850134", "แลกกันอย่างยุติธรรม สหาย โปรดรับตราประทับพร้อมพรจากเผ่า!" },
        required = { [19858] = { "20:974177135:798191199", "เหรียญเกียรติยศแซนดาลาร์" } },
        objectiveLabels = {
            item = { ["Zandalar Honor Token"] = "เหรียญเกียรติยศแซนดาลาร์" },
        },
    },
    [9208] = { -- The Savage Guard - Arcanum of Protection
        title = { "40:584733252:1300444775", "เกราะคุ้มภัยเถื่อน — Arcanum of Protection" },
        objective = { "63:2010219141:1678180326", "Zanza the Restless ในซุลกูรูบต้องการ Arcanum of Protection" },
        description = { "306:1701138130:1841595858", "แซนซาสร้างมนตร์เสริมพลังโบราณของโทรลล์ได้หลายแบบเมื่อมีวัตถุดิบที่เหมาะสม! เคยได้ยินเรื่องเกราะคุ้มภัยเถื่อนไหม? แน่นอนว่าไม่เคย สมองท่านสับสนเพราะมนตร์ด้อยค่าของพวกเอลฟ์ไปหมดแล้ว\n\nนำ Arcanum ที่เอลฟ์สร้างขึ้นมาให้ข้า จะได้ทำลายของผิดเพี้ยนชิ้นนั้นเสีย แล้วเกราะคุ้มภัยเถื่อนจะเป็นของท่าน" },
        progress = { "24:646275606:421722342", "ท่านนำ Arcanum มาหรือยัง?" },
        completion = { "143:1436930126:290994922", "เวทไร้ค่าในมนตร์เสริมพลังพวกนี้กระพือโทสะของข้า โทสะมอบพลังให้ข้า\n\nนำมาให้อีก แล้วท่านจะได้เกราะคุ้มภัยเถื่อนอีกชิ้น" },
        required = { [18331] = { "21:2104482662:1940729733", "อาร์คานัมแห่งการคุ้มครอง" } },
        objectiveLabels = {
            item = { ["Arcanum of Protection"] = "อาร์คานัมแห่งการคุ้มครอง" },
        },
    },
    [9209] = { -- The Savage Guard - Arcanum of Rapidity
        description = { "306:1701138130:1841595858", "แซนซาสร้างมนตร์เสริมพลังโบราณของโทรลล์ได้หลายแบบเมื่อมีวัตถุดิบที่เหมาะสม! เคยได้ยินเรื่องเกราะคุ้มภัยเถื่อนไหม? แน่นอนว่าไม่เคย สมองท่านสับสนเพราะมนตร์ด้อยค่าของพวกเอลฟ์ไปหมดแล้ว\n\nนำ Arcanum ที่เอลฟ์สร้างขึ้นมาให้ข้า จะได้ทำลายของผิดเพี้ยนชิ้นนั้นเสีย แล้วเกราะคุ้มภัยเถื่อนจะเป็นของท่าน" },
