        completion = { "143:1436930126:290994922", "เวทไร้ค่าในมนตร์เสริมพลังพวกนี้กระพือโทสะของข้า โทสะมอบพลังให้ข้า\n\nนำมาให้อีก แล้วท่านจะได้เกราะคุ้มภัยเถื่อนอีกชิ้น" },
        title = { "38:2038654235:529756295", "เกราะคุ้มภัยเถื่อน — Arcanum of Rapidity" },
        objective = { "61:1561641777:530367284", "Zanza the Restless ในซุลกูรูบต้องการ Arcanum of Rapidity" },
        required = { [18329] = { "19:356266590:1379351694", "อาร์คานัมแห่งความรวดเร็ว" } },
