    [7788] = { -- Vanquish the Invaders!
        title = { "22:125214698:1898760490", "ปราบผู้รุกราน!" },
        objective = { "135:1576287999:588369186", "เข้าสู่ Warsong Gulch เอาชนะ Horde เพื่อรับ Warsong Gulch Mark of Honor แล้วกลับไปหา Sentinel Farsong ที่ Silverwing Grove" },
        description = { "70:997432280:396131818 C 255:655772676:80679124 N 25:1104414161:1239209061", "พ้นอุโมงค์นี้ไป ท่านจะพบสนามรบที่เต็มไปด้วยความโกลาหล ท่าน{class}ผู้เยาว์ พวก Horde ยังทำลายป่าศักดิ์สิทธิ์ของเราไม่หยุด โค่นไม้เขียวชอุ่มไปเป็นเชื้อเพลิงให้เครื่องจักรสงคราม\n\nเข้าสู่ Warsong Gulch และป้องกัน Silverwing Hold ผลักกองกำลัง Horde ที่รุกรานให้ถอยกลับไป!\n\nทำเช่นนี้เพื่อรับ Mark of Honor แล้วนำมาให้ข้า {name} ข้าจะมอบรางวัลให้", variants = { { "70:997432280:396131818 C 269:593226355:1085685269 N 25:1104414161:1239209061", "พ้นอุโมงค์นี้ไป ท่านจะพบสนามรบที่เต็มไปด้วยความโกลาหล ท่าน{class}ผู้เยาว์ พวก Horde ยังทำลายป่าศักดิ์สิทธิ์ของเราไม่หยุด โค่นไม้เขียวชอุ่มไปเป็นเชื้อเพลิงให้เครื่องจักรสงคราม\n\nเข้าสู่ Warsong Gulch และป้องกัน Silverwing Hold ผลักกองกำลัง Horde ที่รุกรานให้ถอยกลับไป!\n\nทำเช่นนี้เพื่อรับเครื่องรางเชิดชูความดี แล้วนำเครื่องรางมาให้ข้า {name} ข้าจะมอบรางวัลให้" } } },
        progress = { "62:1808583306:293605885", "ท่านได้เข้ารบใน Warsong Gulch และป้องกัน Silverwing Hold แล้วหรือยัง?" },
        completion = { "170:2083465973:2137246134", "ท่านพิสูจน์แล้วว่าช่วยการรบของเราใน Warsong Gulch ได้มาก จงช่วยเราต่อไปและนำ Marks of Honor มาให้ข้าอีก ท่านจะได้รับความไว้วางใจจากเรามากขึ้น" },
        required = { [20558] = { "27:1151639554:183227099", "เหรียญเกียรติยศ Warsong Gulch" } },
        steps = { { "27:1151639554:183227099", "เหรียญเกียรติยศ Warsong Gulch" } },
    },
    [7789] = { -- Quell the Silverwing Usurpers
        title = { "29:1008784215:1212206883", "ปราบพวกซิลเวอร์วิงผู้แย่งชิง" },
        objective = { "144:909025282:1759302336", "เข้าสู่ Warsong Gulch เอาชนะ Alliance เพื่อรับ Warsong Gulch Mark of Honor แล้วนำไปให้ Captain Shatterskull ที่ Mor'shan Base Camp" },
        description = { "74:1203270782:167766295 R 364:1399447218:283448246 N 27:333588092:1772472816", "ป่าอาเชนเวลจะต้องสยบต่อพลังของ Horde ท่าน{race} พวกซิลเวอร์วิงจะพูดหรือทำอะไรก็ขวางสิทธิ์ที่เราจะปกครองดินแดนนี้ไม่ได้ คาลิมดอร์เป็นของ Horde พวกมันกล้าดีอย่างไรมาขวางเราเก็บเกี่ยวสิ่งที่เป็นของเราโดยชอบ!\n\nจงภาคภูมิใจขณะบดขยี้ความพยายามอันอ่อนแอที่จะขัดขวางเรา ทำลายเหล่า Silverwing Sentinels เพื่อรับ Mark of Honor แล้วนำตรานั้นกลับมาให้ข้า {name} ท่านจะได้รับรางวัล", variants = { { "74:1203270782:167766295 R 372:1258915463:1772588027 N 27:333588092:1772472816", "ป่าอาเชนเวลจะต้องสยบต่อพลังของ Horde ท่าน{race} พวกซิลเวอร์วิงจะพูดหรือทำอะไรก็ขวางสิทธิ์ที่เราจะปกครองดินแดนนี้ไม่ได้ คาลิมดอร์เป็นของ Horde พวกมันกล้าดีอย่างไรมาขวางเราเก็บเกี่ยวสิ่งที่เป็นของเราโดยชอบ!\n\nจงภาคภูมิใจขณะบดขยี้ความพยายามอันอ่อนแอที่จะขัดขวางเรา ทำลายเหล่า Silverwing Sentinels เพื่อรับตราเกียรติยศวอร์ซอง แล้วนำตรานั้นกลับมาให้ข้า {name} ท่านจะได้รับรางวัล" } } },
        progress = { "69:609104542:1335462914", "เลือดของศัตรูคือตราแห่งเกียรติยศ ท่านมีตราเช่นนั้นไหม?" },
        completion = { "183:1321787676:1929223859 R 3:3050122:795478", "<กัปตันแชตเตอร์สกัลล์คำรามด้วยความยินดีที่ชนะ>\n\nพวกมันจะทนได้อีกเท่าไรกัน? พวก Alliance โสโครกต้องตายด้วยมือ Horde อีกกี่คนจึงจะยอมถอย? เวลาจะให้คำตอบเอง ท่าน{race}..." },
