    [7863] = { -- Sentinel Basic Care Package
        title = { "27:715152425:1270475501", "ชุดเสบียงเซนทิเนลขั้นพื้นฐาน" },
        completion = { "48:210844649:134717484 N 346:363386447:355652182", "ท่านเริ่มพิสูจน์ตัวเองให้เราเห็นแล้ว {name} โปรดรับชุดเสบียงนี้เป็นรางวัล! ข้างในมีเสบียงอาหารและผ้าพันแผลที่ใช้ได้เฉพาะใน Warsong Gulch\n\nเมื่อท่านพิสูจน์ฝีมือในสนามรบต่อไป ท่านจะซื้อของเหล่านี้ได้ เมื่อชื่อเสียงกับเราถึงระดับ Friendly จะซื้อเสบียงอาหารได้ และเมื่อถึง Honored จะซื้อผ้าพันแผลได้" },
    },
