    [7871] = { -- Vanquish the Invaders!
        title = { "22:125214698:1898760490", "ปราบผู้รุกราน!" },
        objective = { "135:1576287999:588369186", "เข้าสู่ Warsong Gulch เอาชนะ Horde เพื่อรับ Warsong Gulch Mark of Honor แล้วกลับไปหา Sentinel Farsong ที่ Silverwing Grove" },
        description = { "70:997432280:396131818 C 255:655772676:80679124 N 25:1104414161:1239209061", "พ้นอุโมงค์นี้ไป ท่านจะพบสนามรบที่เต็มไปด้วยความโกลาหล ท่าน{class}ผู้เยาว์ พวก Horde ยังทำลายป่าศักดิ์สิทธิ์ของเราไม่หยุด โค่นไม้เขียวชอุ่มไปเป็นเชื้อเพลิงให้เครื่องจักรสงคราม\n\nเข้าสู่ Warsong Gulch และป้องกัน Silverwing Hold ผลักกองกำลัง Horde ที่รุกรานให้ถอยกลับไป!\n\nทำเช่นนี้เพื่อรับ Mark of Honor แล้วนำมาให้ข้า {name} ข้าจะมอบรางวัลให้", variants = { { "70:997432280:396131818 C 269:593226355:1085685269 N 25:1104414161:1239209061", "พ้นอุโมงค์นี้ไป ท่านจะพบสนามรบที่เต็มไปด้วยความโกลาหล ท่าน{class}ผู้เยาว์ พวก Horde ยังทำลายป่าศักดิ์สิทธิ์ของเราไม่หยุด โค่นไม้เขียวชอุ่มไปเป็นเชื้อเพลิงให้เครื่องจักรสงคราม\n\nเข้าสู่ Warsong Gulch และป้องกัน Silverwing Hold ผลักกองกำลัง Horde ที่รุกรานให้ถอยกลับไป!\n\nทำเช่นนี้เพื่อรับเครื่องรางเชิดชูความดี แล้วนำเครื่องรางมาให้ข้า {name} ข้าจะมอบรางวัลให้" } } },
        progress = { "62:1808583306:293605885", "ท่านได้เข้ารบใน Warsong Gulch และป้องกัน Silverwing Hold แล้วหรือยัง?" },
        completion = { "170:2083465973:2137246134", "ท่านพิสูจน์แล้วว่าช่วยการรบของเราใน Warsong Gulch ได้มาก จงช่วยเราต่อไปและนำ Marks of Honor มาให้ข้าอีก ท่านจะได้รับความไว้วางใจจากเรามากขึ้น" },
