    [8266] = { -- Ribbons of Sacrifice
        title = { "20:65092404:1373316017", "ริบบิ้นเชิดชูการเสียสละ" },
        objective = { "117:1741489059:287011744", "นำ Ribbons of Sacrifice ไปให้ Captain Shatterskull เพื่อให้เหล่า Outriders ตอบแทนที่ท่านออกรบเพื่อพวกเรา" },
        progress = { "422:1752494292:236210955", "ข้าเข้าใจว่าบางครั้งชัยชนะใน Warsong Gulch ก็อยู่ไกลเกินเอื้อม ถึงอย่างนั้นความพยายามที่ท่านทำเพื่อเราก็มีค่า แม้จะคว้าชัยมาไม่ได้\n\nหากท่านเข้าร่วมการประลองใน Warsong Gulch จนจบ ถึงจะแพ้ก็ยังได้รับ Ribbons of Sacrifice นำมาให้ข้า เหล่า Sentinels จะได้ตอบแทนที่ท่านออกรบเพื่อเรา... แม้ครั้งนี้ท่านจะชนะไม่ได้ก็ตาม" },
        completion = { "69:1134244754:568767601 N 154:83203546:286419908", "เมื่อเผชิญความพ่ายแพ้ ท่านยังยืนหยัดอยู่กับที่ {name} เมื่อถึงคราวคับขัน นั่นแหละคือสิ่งที่ทำให้ท่านเป็นวีรชนตัวจริง คราวหน้าท่านต้องชนะอย่างแน่นอน... และเราขอบคุณสำหรับความพยายามครั้งนี้" },
        description = { "422:1752494292:236210955", "ข้าเข้าใจว่าบางครั้งชัยชนะใน Warsong Gulch ก็อยู่ไกลเกินเอื้อม ถึงอย่างนั้นความพยายามที่ท่านทำเพื่อเราก็มีค่า แม้จะคว้าชัยมาไม่ได้\n\nหากท่านเข้าร่วมการประลองใน Warsong Gulch จนจบ ถึงจะแพ้ก็ยังได้รับ Ribbons of Sacrifice นำมาให้ข้า เหล่า Sentinels จะได้ตอบแทนที่ท่านออกรบเพื่อเรา... แม้ครั้งนี้ท่านจะชนะไม่ได้ก็ตาม" },
        required = { [20256] = { "33:671745812:1223830633", "ริบบิ้นแห่งการเสียสละ Warsong Gulch" } },
        steps = { { "33:671745812:1223830633", "ริบบิ้นแห่งการเสียสละ Warsong Gulch" } },
    },
    [8267] = { -- Ribbons of Sacrifice
        title = { "20:65092404:1373316017", "ริบบิ้นเชิดชูการเสียสละ" },
        objective = { "117:1741489059:287011744", "นำ Ribbons of Sacrifice ไปให้ Captain Shatterskull เพื่อให้เหล่า Outriders ตอบแทนที่ท่านออกรบเพื่อพวกเรา" },
        completion = { "69:1134244754:568767601 N 154:83203546:286419908", "เมื่อเผชิญความพ่ายแพ้ ท่านยังยืนหยัดอยู่กับที่ {name} เมื่อถึงคราวคับขัน นั่นแหละคือสิ่งที่ทำให้ท่านเป็นวีรชนตัวจริง คราวหน้าท่านต้องชนะอย่างแน่นอน... และเราขอบคุณสำหรับความพยายามครั้งนี้" },
        description = { "422:247077953:931191355", "ข้าเข้าใจว่าบางครั้งชัยชนะใน Warsong Gulch ก็อยู่ไกลเกินเอื้อม ถึงอย่างนั้นความพยายามที่ท่านทำเพื่อเราก็มีค่า แม้จะคว้าชัยมาไม่ได้\n\nหากท่านเข้าร่วมการประลองใน Warsong Gulch จนจบ ถึงจะแพ้ก็ยังได้รับ Ribbons of Sacrifice นำมาให้ข้า เหล่า Outriders จะได้ตอบแทนที่ท่านออกรบเพื่อเรา... แม้ครั้งนี้ท่านจะชนะไม่ได้ก็ตาม" },
    },
    [8268] = { -- Ribbons of Sacrifice
        title = { "20:65092404:1373316017", "ริบบิ้นเชิดชูการเสียสละ" },
