    [8289] = { -- Talismans of Merit
        title = { "18:2029605368:2097503096", "เครื่องรางเชิดชูความดี" },
        description = { "174:1723346133:251296290", "เจ้าพิสูจน์แล้วว่าช่วยพวกเราใน Warsong Gulch ได้มาก จงช่วยฝ่ายเราต่อไปและนำ Talismans of Merit มาให้ข้าอีก ทำเช่นนี้แล้วเราจะยิ่งไว้วางใจเจ้า" },
    },
    [8290] = { -- Vanquish the Invaders
        objective = { "135:1576287999:588369186", "เข้าสู่ Warsong Gulch เอาชนะ Horde เพื่อรับ Warsong Gulch Mark of Honor แล้วกลับไปหา Sentinel Farsong ที่ Silverwing Grove" },
        title = { "21:409929624:1801331878", "ปราบผู้รุกราน" },
        description = { "70:997432280:396131818 C 269:593226355:1085685269 N 25:1104414161:1239209061", "พ้นอุโมงค์นี้ไป ท่านจะพบสนามรบที่เต็มไปด้วยความโกลาหล ท่าน{class}ผู้เยาว์ พวก Horde ยังทำลายป่าศักดิ์สิทธิ์ของเราไม่หยุด โค่นไม้เขียวชอุ่มไปเป็นเชื้อเพลิงให้เครื่องจักรสงคราม\n\nเข้าสู่ Warsong Gulch และป้องกัน Silverwing Hold ผลักกองกำลัง Horde ที่รุกรานให้ถอยกลับไป!\n\nทำเช่นนี้เพื่อรับเครื่องรางเชิดชูความดี แล้วนำเครื่องรางมาให้ข้า {name} ข้าจะมอบรางวัลให้" },
        required = { [20558] = { "27:1151639554:183227099", "เหรียญเกียรติยศ Warsong Gulch" } },
        steps = { { "27:1151639554:183227099", "เหรียญเกียรติยศ Warsong Gulch" } },
    },
    [8291] = { -- Vanquish the Invaders!
        title = { "22:125214698:1898760490", "ปราบผู้รุกราน!" },
        objective = { "135:1576287999:588369186", "เข้าสู่ Warsong Gulch เอาชนะ Horde เพื่อรับ Warsong Gulch Mark of Honor แล้วกลับไปหา Sentinel Farsong ที่ Silverwing Grove" },
        description = { "70:997432280:396131818 C 255:655772676:80679124 N 25:1104414161:1239209061", "พ้นอุโมงค์นี้ไป ท่านจะพบสนามรบที่เต็มไปด้วยความโกลาหล ท่าน{class}ผู้เยาว์ พวก Horde ยังทำลายป่าศักดิ์สิทธิ์ของเราไม่หยุด โค่นไม้เขียวชอุ่มไปเป็นเชื้อเพลิงให้เครื่องจักรสงคราม\n\nเข้าสู่ Warsong Gulch และป้องกัน Silverwing Hold ผลักกองกำลัง Horde ที่รุกรานให้ถอยกลับไป!\n\nทำเช่นนี้เพื่อรับ Mark of Honor แล้วนำมาให้ข้า {name} ข้าจะมอบรางวัลให้", variants = { { "70:997432280:396131818 C 269:593226355:1085685269 N 25:1104414161:1239209061", "พ้นอุโมงค์นี้ไป ท่านจะพบสนามรบที่เต็มไปด้วยความโกลาหล ท่าน{class}ผู้เยาว์ พวก Horde ยังทำลายป่าศักดิ์สิทธิ์ของเราไม่หยุด โค่นไม้เขียวชอุ่มไปเป็นเชื้อเพลิงให้เครื่องจักรสงคราม\n\nเข้าสู่ Warsong Gulch และป้องกัน Silverwing Hold ผลักกองกำลัง Horde ที่รุกรานให้ถอยกลับไป!\n\nทำเช่นนี้เพื่อรับเครื่องรางแห่งความดีความชอบ แล้วนำเครื่องรางนั้นมาให้ข้า {name} ข้าจะมอบรางวัลให้" } } },
        progress = { "62:1808583306:293605885", "ท่านได้เข้ารบใน Warsong Gulch และป้องกัน Silverwing Hold แล้วหรือยัง?" },
        completion = { "170:2083465973:2137246134", "ท่านพิสูจน์แล้วว่าช่วยการรบของเราใน Warsong Gulch ได้มาก จงช่วยเราต่อไปและนำ Marks of Honor มาให้ข้าอีก ท่านจะได้รับความไว้วางใจจากเรามากขึ้น" },
        required = { [20558] = { "27:1151639554:183227099", "เหรียญเกียรติยศ Warsong Gulch" } },
        objectiveLabels = {
            item = { ["Warsong Gulch Mark of Honor"] = "เหรียญเกียรติยศ Warsong Gulch" },
        },
    },
    [8292] = { -- Talismans of Merit
        title = { "18:2029605368:2097503096", "เครื่องรางเชิดชูความดี" },
        objective = { "107:2093629562:1400506636", "ท่านได้รับ Silverwing Talisman of Merit จากภารกิจครั้งก่อน มาคุยกับข้าอีกครั้งเพื่อรับรางวัล" },
        completion = { "11:1191658970:1224418299 N 66:2056119310:1409736187", "ขอบใจ {name} เรื่องวีรกรรมของท่านใน Warsong Gulch เลื่องลือไปทั่วป่าอาเชนเวล" },
        progress = { "84:13513187:1409889279", "ภารกิจครั้งก่อนของท่านได้รับการบันทึกแล้ว นำ Marks of Honor มาให้ข้าอีก แล้วท่านจะได้รางวัล" },
