    },
    [8293] = { -- Mark of Honor
        title = { "13:1664097305:1423584066", "ตราแห่งเกียรติยศ" },
        objective = { "100:1190089833:1564318919", "ท่านได้รับ Warsong Mark of Honor จากภารกิจครั้งก่อน มาคุยกับข้าอีกครั้งเพื่อรับรางวัล" },
        progress = { "84:13513187:1409889279", "ภารกิจครั้งก่อนของท่านได้รับการบันทึกแล้ว นำ Marks of Honor มาให้ข้าอีก แล้วท่านจะได้รางวัล" },
        completion = { "235:1864098263:1939029920", "พวกไนต์เอลฟ์กับพันธมิตรต้องตัวสั่นแม้ได้ยินเพียงเสียงกระซิบชื่อท่าน! เพื่อ Horde!\n\nท่านพิสูจน์แล้วว่าช่วยการรบของเราใน Warsong Gulch ได้มาก จงโหมโจมตีเหล่า Silverwing Sentinels ต่อไป! นำ Marks of Honor มาให้ข้าอีก!" },
        description = { "140:462019130:542923402", "เจ้าพิสูจน์แล้วว่าช่วยพวกเราใน Warsong Gulch ได้มาก จงถล่มพวก Silverwing Sentinels ต่อไป! นำ Marks of Honor มาให้ข้าอีก!" },
    },
    [8294] = { -- Quell the Silverwing Usurpers
        title = { "29:1008784215:1212206883", "ปราบพวกซิลเวอร์วิงผู้แย่งชิง" },
        objective = { "144:909025282:1759302336", "เข้าสู่ Warsong Gulch เอาชนะ Alliance เพื่อรับ Warsong Gulch Mark of Honor แล้วนำไปให้ Captain Shatterskull ที่ Mor'shan Base Camp" },
        description = { "74:1203270782:167766295 R 364:1399447218:283448246 N 27:333588092:1772472816", "ป่าอาเชนเวลจะต้องสยบต่อพลังของ Horde ท่าน{race} พวกซิลเวอร์วิงจะพูดหรือทำอะไรก็ขวางสิทธิ์ที่เราจะปกครองดินแดนนี้ไม่ได้ คาลิมดอร์เป็นของ Horde พวกมันกล้าดีอย่างไรมาขวางเราเก็บเกี่ยวสิ่งที่เป็นของเราโดยชอบ!\n\nจงภาคภูมิใจขณะบดขยี้ความพยายามอันอ่อนแอที่จะขัดขวางเรา ทำลายเหล่า Silverwing Sentinels เพื่อรับ Mark of Honor แล้วนำตรานั้นกลับมาให้ข้า {name} ท่านจะได้รับรางวัล", variants = { { "74:1203270782:167766295 R 372:1258915463:1772588027 N 27:333588092:1772472816", "ป่าอาเชนเวลจะต้องสยบต่อพลังของ Horde ท่าน{race} พวกซิลเวอร์วิงจะพูดหรือทำอะไรก็ขวางสิทธิ์ที่เราจะปกครองดินแดนนี้ไม่ได้ คาลิมดอร์เป็นของ Horde พวกมันกล้าดีอย่างไรมาขวางเราเก็บเกี่ยวสิ่งที่เป็นของเราโดยชอบ!\n\nจงภาคภูมิใจขณะบดขยี้ความพยายามอันอ่อนแอที่จะขัดขวางเรา ทำลายเหล่า Silverwing Sentinels เพื่อรับ Warsong Mark of Honor แล้วนำตรานั้นกลับมาให้ข้า {name} ท่านจะได้รับรางวัล" } } },
        progress = { "69:609104542:1335462914", "เลือดของศัตรูคือตราแห่งเกียรติยศ ท่านมีตราเช่นนั้นไหม?" },
        completion = { "183:1321787676:1929223859 R 3:3050122:795478", "<กัปตันแชตเตอร์สกัลล์คำรามด้วยความยินดีที่ชนะ>\n\nพวกมันจะทนได้อีกเท่าไรกัน? พวก Alliance โสโครกต้องตายด้วยมือ Horde อีกกี่คนจึงจะยอมถอย? เวลาจะให้คำตอบเอง ท่าน{race}..." },
        required = { [20558] = { "27:1151639554:183227099", "เหรียญเกียรติยศ Warsong Gulch" } },
        objectiveLabels = {
            item = { ["Warsong Gulch Mark of Honor"] = "เหรียญเกียรติยศ Warsong Gulch" },
        },
    },
