    [9094] = { -- Argent Dawn Gloves
        title = { "18:1252422634:1252458996", "ถุงมือแห่ง Argent Dawn" },
        progress = { "165:1346792557:266778086", "หากท่านนำ Necrotic Rune สามสิบชิ้นมาให้ข้า ข้าจะให้อุปกรณ์ป้องกันมือที่ท่านเลือกเป็นสิ่งแลกเปลี่ยน มันน่าจะมีประโยชน์ในการต่อสู้กับเหล่าอันเดด Scourge" },
        completion = { "18:366880880:1038443585 N 63:1904441611:121879177", "ทำได้ดี {name} เลือกอุปกรณ์ป้องกันมือที่ท่านต้องการได้เลย ถือเป็นคำขอบคุณสำหรับความพยายามของท่าน" },
        required = { [22484] = { "13:1813836045:1512122177", "รูนมรณะ" } },
