        },
    },
    [9153] = { -- Under the Shadow
        title = { "16:1095689660:928215987", "ใต้เงาป้อมลอยฟ้า" },
        objective = { "237:692182316:1848189251", "ดูแผนที่เพื่อหาพื้นที่ที่ถูก Scourge โจมตี ไปที่นั่นแล้วทำให้เนโครโพลิสเสียหายด้วยการกำจัด Scourge รอบบริเวณนั้น จากนั้นนำ Necrotic Rune ที่ได้จากพวกมัน 10 ชิ้นกลับไปให้ Commander Thomas Helleran ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { "468:2005299387:1721000881", "เนโครโพลิสลอยฟ้าของ Scourge คุกคามทั้งดินแดน Horde และ Alliance เงาของป้อมลอยฟ้าทอดปกคลุม Tanaris, Blasted Lands, Winterspring และ Burning Steppes\n\nเราต้องร่วมแรงกันจึงจะขับไล่พวกมันได้\n\nวงเวทตามจุดต่าง ๆ ในพื้นที่ถูกบุกช่วยค้ำจุนเนโครโพลิส เราพบว่าหากกำจัดฝูงอันเดดไร้สติที่ล้อมวงเวทอยู่ ก็จะทำลายแนวป้องกันของพวกมันได้" },
        progress = { "70:178589048:1827318871 N 1:63:63", "ต้องใช้เวลากว่าจะเอาชนะภัยครั้งนี้ได้ ท่านเป็นอย่างไรบ้าง {name}?" },
        completion = { "18:366880880:1038443585 N 327:1959933002:257361242", "ทำได้ดี {name} ชัยชนะทีละเล็กทีละน้อยเช่นนี้จะช่วยให้เราเอาชนะภัยจาก Scourge ที่หวนกลับมาได้\n\nพักให้หายเหนื่อย แล้วกลับไปแนวหน้าอีกครั้ง มิฉะนั้นเราอาจเสียพื้นที่ที่ยึดคืนมาได้ในวันนี้\n\nเพื่อช่วยท่านในศึกต่อไป เราจะนำของพิเศษบางอย่างมาให้ท่านแลกด้วย Necrotic Rune เพิ่มเติม" },
        required = { [22484] = { "13:1813836045:1512122177", "รูนมรณะ" } },
        objectiveLabels = {
            item = { ["Necrotic Rune"] = "รูนมรณะ" },
        },
    },
    [9154] = { -- Light's Hope Chapel
        title = { "19:1335488131:1416821021", "โบสถ์แสงแห่งความหวัง" },
        objective = { "115:113323694:1842441660", "นำ Call to Arms Announcement ไปมอบให้ Keeper of the Rolls ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { "282:963121910:639909241", "Scourge กลับมาแล้ว คราวนี้มีจำนวนมากกว่าที่เราเคยเห็น Argent Dawn กำลังรับสมัครทุกคนที่เต็มใจและพร้อมจะปกป้องแผ่นดินของเรา\n\nหากท่านมีจุดหมายเดียวกับเรา จงนำเอกสารนี้ไปให้ Keeper of the Rolls ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        progress = { "44:910298596:915094123", "ท่านมาร่วมกับภาคีของเราใช่ไหม?" },
        completion = { "235:865359492:1856070208", "Argent Dawn ส่งเสียงขอความช่วยเหลือ และท่านคือหนึ่งในผู้ที่ขานรับ เวลานี้เราไม่มีเวลาฝึกท่านแล้ว เราเชื่อในฝีมือของท่านและเชื่อว่าท่านจะร่วมขับไล่ Scourge ไปกับเรา" },
    },
    [9247] = { -- The Keeper's Call
        title = { "17:1883719822:2039385311", "คำเรียกตัวจากผู้รักษาทะเบียน" },
        objective = { "102:903229772:468648900", "นำ Letter from the Keeper of the Rolls ไปให้ Keeper of the Rolls ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { "N 177:2032960160:922936137 N 132:455248925:225813835", "ถึง {name}\n\nที่ผ่านมา ท่านรับใช้ Argent Dawn อย่างสุดความสามารถเสมอ บัดนี้ในยามที่เราต้องการความช่วยเหลือที่สุด เราขอส่งเสียงเรียกอีกครั้ง\n\n{name} หากท่านยินดีช่วยเราอีกครั้ง โปรดไปรายงานตัวกับ Keeper of the Rolls ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        progress = { "4:1110228981:147916455 N 24:1439135522:1445467228", "อา {name} ดีใจที่ได้พบเจ้า" },
        completion = { "51:2145426393:2140538003 N 169:462110257:1723555732", "เพียงเจ้าตอบรับคำเรียก เราก็เป็นหนี้บุญคุณเจ้าแล้ว {name} ฝ่าย Argent Dawn เชื่อมั่นว่าตัวอย่างอันเจิดจ้าของเจ้าจะช่วยให้คนอื่นที่มาช่วยเราเข้าใจว่าควรขับไล่การรุกรานของ Scourge อย่างไรให้ได้ผลที่สุด!" },
        required = { [22723] = { "37:1860889477:1452704957", "จดหมายจากผู้ดูแลทะเบียน" } },
        objectiveLabels = {
            item = { ["A Letter from the Keeper of the Rolls"] = "จดหมายจากผู้ดูแลทะเบียน" },
        },
    },
    [9260] = { -- Investigate the Scourge of Stormwind
        title = { "36:1719844401:341051498", "สืบการรุกรานของ Scourge ที่ Stormwind" },
        objective = { "133:1452511451:6232127", "เก็บ Dim Necrotic Stone สามชิ้นจาก Scourge นอก Stormwind และตรวจสอบวงอักขระเรืองแสงใกล้ค่ายของพวกมัน", variants = { { "135:750696260:1913328590", "เก็บ Dim Necrotic Stone สามชิ้นจาก Scourge นอก Stormwind และตรวจสอบวงอักขระเรืองแสงใกล้ค่ายของพวกมัน" } } },
        description = { "474:467578283:293043749", "Scourge ตั้งค่ายอยู่หน้าประตูเมืองแล้ว เราจะนิ่งดูดายไม่ได้! ท่านจะลุกขึ้นปกป้อง Stormwind จากผู้รุกรานต้องสาปพวกนี้ใช่ไหม?\n\nด้านนอกมีวงอักขระประหลาด เรืองแสงด้วยพลังแบบเดียวกับที่ล้อมรอบพวกอันเดดและเนโครโพลิสเหนือหัว มันต้องมีความหมายอะไรสักอย่าง ข้าอยากให้ท่านไปค้นหาว่าคืออะไร ระหว่างนั้นช่วยกำจัดเจ้าตัววิปริตพวกนั้นให้เหลือน้อยลงด้วย นำหลักฐานการตายของพวกมันกลับมาพร้อมผลที่สืบได้ แล้วข้าจะให้รางวัล ไปเถิด!" },
        progress = { "69:2098837675:639753628", "ท่านไปตรวจสอบการรุกรานแล้วหรือยัง? เราไม่มีเวลามัวชักช้า!" },
        completion = { "282:570564545:1233540752", "อืม จากที่ท่านเล่า เสียงในวงอักขระนั่น... วงพวกนั้นคงมีไว้สื่อสารบางอย่าง ข้าไม่อยากคิดเลยว่าเวทเช่นนี้ใช้ติดต่อจิตของสิ่งผิดธรรมชาติชนิดใด ถึงอย่างไรท่านก็ดูจะกลับมาโดยปลอดภัยทั้งกายและใจ Argent Dawn ขอบคุณที่ท่านช่วยเหลือ" },
        required = { [22892] = { "18:1586361688:1631674279", "ศิลาเนโครติกแสงริบหรี่" } },
        objectiveLabels = {
            event = { ["Investigate a circle"] = "ตรวจสอบวงพิธี" },
            item = { ["Dim Necrotic Stone"] = "ศิลาเนโครติกแสงริบหรี่" },
        },
    },
    [9261] = { -- Investigate the Scourge of Ironforge
        progress = { "69:2098837675:639753628", "ท่านไปตรวจสอบการรุกรานแล้วหรือยัง? เราไม่มีเวลามัวชักช้า!" },
