    [9292] = { -- Cracked Necrotic Crystal
        title = { "24:1762373274:1723185643", "ผลึกเนโครติกร้าว" },
        objective = { "86:382971852:2012450786", "นำ Cracked Necrotic Crystal ไปให้ Lieutenant Orrin ที่อยู่นอกประตู Stormwind" },
        description = { "109:1194736280:1472421523", "บนซากอาโบมิเนชันที่ล้มลง ท่านพบผลึกแตกร้าวที่กำลังปล่อยพลังเนโครติกเป็นจังหวะช้า ๆ" },
        progress = { "28:717264101:743564957", "ท่านต้องการอะไรหรือ?" },
        completion = { "258:1226844125:1636010185", "อืม ท่านเอาของนี้มาจากซากอาโบมิเนชันตัวหนึ่งที่บุกเข้ามาหรือ?\n\nเราได้รับข่าวว่า Scourge กำลังอัญเชิญเนโครโพลิสมาใช้เป็นฐาน ข้าสงสัยว่าพวกมันคิดจะสร้างฐานหนึ่งใน Stormwind โชคดีที่พวกมันทำไม่สำเร็จ" },
        required = { [22949] = { "24:1762373274:1723185643", "ผลึกเนโครติกที่แตกร้าว" } },
        steps = { { "24:1762373274:1723185643", "ผลึกเนโครติกที่แตกร้าว" } },
    },
    [9295] = { -- Letter from the Front
        title = { "21:996537829:1409787148", "จดหมายจากแนวหน้า" },
        objective = { "98:2106285716:486221811", "นำ Torn Letter ไปให้ Keeper of the Rolls ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        description = { "230:1610261054:909103937", "ท่านพบจดหมายฉบับนี้จากสมุน Scourge ตัวหนึ่งในบรรดาที่ท่านสังหาร ดูจากสภาพและกลิ่นแล้ว มันคงอยู่กับพวกอันเดดมาสักพัก บางทีอาจมีคนที่ Light's Hope Chapel สนใจตรวจดูให้ละเอียดกว่านี้..." },
        progress = { "28:1673347906:822209214", "ว่าอย่างไร? ท่านมีอะไรมาให้ดูหรือ?" },
        completion = { "488:896317961:695305021", "น่าเศร้าจริง ๆ ทหารผู้นี้เขียนถึงคนที่รัก แต่จดหมายไปไม่ถึง เรื่องที่เล่าเกิดขึ้นเมื่อหลายปีก่อน ข้าไม่แน่ใจว่าคนที่เขาตั้งใจส่งถึงยังมีชีวิตอยู่หรือเปล่า\n\nแต่ยังพอมีหวัง ชื่อกับข้อมูลที่เขาเขียนไว้อาจช่วยให้ข้าตามหาครอบครัวพบ! คงต้องค้นข้อมูลสักหน่อย แต่บรรณารักษ์ที่ Stormwind ติดค้างน้ำใจข้าอยู่...\n\nขอบคุณที่นำมาให้ข้า ความช่วยเหลือของท่านอาจทำให้ใครบางคนวางใจได้เสียที" },
    },
    [9299] = { -- Note from the Front
        description = { "230:1610261054:909103937", "ท่านพบจดหมายฉบับนี้จากสมุน Scourge ตัวหนึ่งในบรรดาที่ท่านสังหาร ดูจากสภาพและกลิ่นแล้ว มันคงอยู่กับพวกอันเดดมาสักพัก บางทีอาจมีคนที่ Light's Hope Chapel สนใจตรวจดูให้ละเอียดกว่านี้..." },
        progress = { "28:1673347906:822209214", "ว่าอย่างไร? ท่านมีอะไรมาให้ดูหรือ?" },
        completion = { "488:896317961:695305021", "น่าเศร้าจริง ๆ ทหารผู้นี้เขียนถึงคนที่รัก แต่จดหมายไปไม่ถึง เรื่องที่เล่าเกิดขึ้นเมื่อหลายปีก่อน ข้าไม่แน่ใจว่าคนที่เขาตั้งใจส่งถึงยังมีชีวิตอยู่หรือเปล่า\n\nแต่ยังพอมีหวัง ชื่อกับข้อมูลที่เขาเขียนไว้อาจช่วยให้ข้าตามหาครอบครัวพบ! คงต้องค้นข้อมูลสักหน่อย แต่บรรณารักษ์ที่ Stormwind ติดค้างน้ำใจข้าอยู่...\n\nขอบคุณที่นำมาให้ข้า ความช่วยเหลือของท่านอาจทำให้ใครบางคนวางใจได้เสียที" },
        title = { "19:812597430:941958890", "บันทึกจากแนวหน้า" },
        objective = { "100:196402487:191823908", "นำ Careworn Note ไปให้ Keeper of the Rolls ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
    },
