    [98471] = { -- Message from the Supreme Magister
        title = { "33:1197575382:569439445", "สารจากจอมเวทสูงสุด" },
        objective = { "82:478220331:1402353552", "ไปพบ Elaadrin Evengale ที่หน้าผาเหนือ The Uplands ใน Alterac Mountains" },
        description = { "11:927657569:725753248 N 246:545936021:225398244", "สวัสดี {name}\n\nข้ามีงานสำคัญยิ่งจะมอบหมายให้ท่าน โปรดมาพบข้าที่เทือกเขา Alterac ทางตะวันตกเฉียงเหนือของหมู่บ้าน Strahnbrad ข้าจะรอที่หน้าผาซึ่งมองลงไปเห็นหุบเขา The Uplands\n\nมาคนเดียว และอย่าบอกใคร" },
        required = { [281330] = { "33:1197575382:569439445", "สาส์นจากมหาจอมเวทสูงสุด" } },
        objectiveLabels = {
            item = { ["Message from the Supreme Magister"] = "สาส์นจากมหาจอมเวทสูงสุด" },
        },
    },
    [171] = { -- A Warden of the Alliance
        title = { "24:1941431081:1008723083", "ผู้ดูแลเด็กแห่ง Alliance" },
        objective = { "138:1066294400:9834889", "พาเด็กในความดูแลกลับสถานเลี้ยงเด็กกำพร้าที่ Stormwind โดยส่ง Human Orphan Whistle ให้ Orphan Matron Nightingale ใน Cathedral District" },
        description = { "34:2036025115:920009012 N 388:1670035541:1731819928", "พี่ใจดีกับผมมากเลย {name} ผมไม่เคยคิดว่าสัปดาห์เด็กจะสนุกขนาดนี้ ขอบคุณนะครับ ผมไม่อยากมัวเศร้ากับเรื่องที่เกิดขึ้น พ่อกับแม่เคยสอนให้ผมลุกขึ้นสู้ไม่ว่าจะเจอเรื่องร้ายแค่ไหน รู้ไหมครับ โตขึ้นผมอยากเป็นฮีโร่... เหมือนพี่เลย\n\nเสียดายจัง แต่ถึงเวลาที่ผมต้องกลับบ้านแล้ว เรากลับกันเถอะ ผมจะบอกคุณแม่บ้านว่าพี่เจ๋งแค่ไหน!" },
        progress = { "35:2085754745:1918631995 N 80:1172511899:1094489019", "ดีใจที่ได้พบท่านอีก {name} ท่านทำหน้าที่ที่อาสาไว้ในสัปดาห์เด็กเรียบร้อยหรือยัง?" },
        completion = { "27:808980923:164731325 N 280:688861998:1190624597 N 68:1187967566:528463714", "ขอให้สวรรค์อวยพรท่าน {name} ท่านทำเพื่อแรนดิสเกินกว่าที่คนส่วนใหญ่จะนึกทำให้เขาเสียอีก ขอบคุณนะ ท่านเป็นดาวส่องสว่างบนฟ้าของ Alliance\n\nถ้าพอมีเวลา โปรดกลับมาเยี่ยมพวกเราบ้างนะ ทั้งแรนดิสและข้าคงดีใจมาก\n\nแรนดิสสนุกกับท่านมาก {name} เขาอยากมอบสัตว์เลี้ยงตัวโปรดให้สักตัวเป็นที่ระลึกถึงเขา" },
        required = { [18598] = { "20:1555150496:1064321324", "นกหวีดเรียกเด็กกำพร้ามนุษย์" } },
        objectiveLabels = {
            item = { ["Human Orphan Whistle"] = "นกหวีดเรียกเด็กกำพร้ามนุษย์" },
        },
    },
    [172] = { -- Children's Week
        title = { "15:1618191835:1475970463", "สัปดาห์เด็ก" },
        objective = { "102:541871159:150465256", "ใช้ Orcish Orphan Whistle เพื่อคุยกับเด็กที่ท่านจะดูแลในสัปดาห์เด็ก" },
        description = { "388:39352507:826471272 N 89:1200014852:918066988", "ท่านยินดีช่วยพวกเราที่สถานเลี้ยงเด็กกำพร้าหรือ? ขอพรจงมีแก่ท่าน สหาย ความช่วยเหลือของท่านในสัปดาห์เด็กมีค่ามาก\n\nรับนกหวีดนี้ไป ท่านจะใช้มันได้เพียงช่วงสั้น ๆ โดยทั่วไปไม่เกินสัปดาห์เด็ก ใช้แล้วท่านจะได้คุยกับเด็กที่ตกลงรับดูแล หากใช้อีกครั้ง เด็กจะกลับไป\n\nเอาเลย {name} เป่านกหวีดแล้วพบเด็กที่ท่านจะดูแลเถิด! ข้ามั่นใจว่าเด็กอยากพบท่านมาก" },
        completion = { "367:205114099:1296380770", "ซุกซุก! ผมชื่อกรันธ์ พี่จะมาดูแลผมใช่ไหม? พี่เป็นนักผจญภัยเหมือนที่พ่อกับแม่ผมเคยเป็นเลย คุณแม่บ้านบอกว่าพวกเขาตายอย่างมีเกียรติในสนามรบ ยินดีที่ได้รู้จักครับ\n\nหวังว่าเราจะได้ทำอะไรด้วยกันเยอะ ๆ นะครับ ผมมีเรื่องที่อยากทำอยู่หลายอย่าง คุณแม่บ้านบอกว่าสัปดาห์นี้พี่จะเป็นเหมือนพี่ชายของผม ผมอยากให้เป็นแบบนั้นมากเลย", variants = { { "366:1600608434:244365699", "ซุกซุก! ผมชื่อกรันธ์ พี่จะมาดูแลผมใช่ไหม? พี่เป็นนักผจญภัยเหมือนที่พ่อกับแม่ผมเคยเป็นเลย คุณแม่บ้านบอกว่าพวกเขาตายอย่างมีเกียรติในสนามรบ ยินดีที่ได้รู้จักครับ\n\nหวังว่าเราจะได้ทำอะไรด้วยกันเยอะ ๆ นะครับ ผมมีเรื่องที่อยากทำอยู่หลายอย่าง คุณแม่บ้านบอกว่าสัปดาห์นี้พี่จะเป็นเหมือนพี่สาวของผม ผมอยากให้เป็นแบบนั้นมากเลย" } } },
    },
    [558] = { -- Jaina's Autograph
        title = { "17:701043794:816790969", "ลายเซ็นของเจนา" },
        objective = { "89:662640264:1011819746", "เดินทางไป Theramore เพื่อขอลายเซ็น Lady Jaina Proudmoore ให้เด็กในความดูแล" },
        description = { "180:1046333945:1032785597 N 245:1843524451:1390603981", "เขาว่ากันว่าท่านหญิงเจนา พราวด์มัวร์ที่เธรามอร์เป็นวีรชนที่ยิ่งใหญ่ที่สุดคนหนึ่งของ Alliance โตขึ้นผมก็อยากเป็นวีรชนของ Alliance เหมือนกัน!\n\nพี่รู้จักท่านหญิงเจนาไหม {name}? ช่วยผมหน่อยได้ไหมครับ? ขอลายเซ็นของท่านให้ผมที ผมไม่รู้จะไปขอยังไง ท่านคงยุ่งเกินกว่าจะมาสนใจเด็กอย่างผม... แต่พี่น่ะ! พี่เป็นนักผจญภัยเหมือนท่านเลย ผมว่าท่านต้องยอมเซ็นให้พี่แน่!\n\nนะครับ?" },
        progress = { "71:1248132612:382684763", "สักวันผมอยากเป็นฮีโร่เหมือนท่านหญิงเจนา... แบบเป็นฮีโร่ผู้ชายนะครับ" },
        completion = { "250:1145450620:1394252739 N 36:811113777:319183615", "ว้าว! พี่ขอลายเซ็นท่านหญิงเจนาให้ผมได้จริง ๆ ด้วย! ขอบคุณมากครับ! โอ้โห... ท่านเขียนข้อความถึงผมด้วย! ผมรู้อยู่แล้วว่าท่านต้องใจดีสุด ๆ สักวันผมอาจได้ไปขอบคุณท่านเอง... ตอนที่ผมเป็นวีรชนของ Alliance แล้ว!\n\nพี่สุดยอดเลย {name} ขอบคุณที่ใจดีกับผมนะครับ" },
        required = { [18642] = { "17:701043794:816790969", "ลายเซ็นของ Jaina" } },
        objectiveLabels = {
            item = { ["Jaina's Autograph"] = "ลายเซ็นของ Jaina" },
        },
    },
    [910] = { -- Down at the Docks
        title = { "17:1241974823:773519730", "เที่ยวท่าเรือ" },
        objective = { "54:62095288:1707390167", "พาเด็กในความดูแลไปยังท่าเรือ Ratchet ใน Barrens" },
        description = { "401:1690548750:1238535401", "ผมเคยได้ยินเรื่องเรือลำใหญ่ที่แล่นระหว่าง Ratchet กับ Booty Bay! ถ้าได้ออกทะเลไปสู้ในศึกทางเรือใหญ่ ๆ หลายครั้งคงเจ๋งน่าดู โตขึ้นผมอาจเป็นกะลาสีผู้เก่งกาจของ Horde ก็ได้! เย่!\n\nพาผมไปดูท่าเรือ Ratchet หน่อยได้ไหมครับ? สัญญาว่าจะไม่ลงน้ำหรือก่อเรื่อง ผมแค่อยากเห็นเรือลำใหญ่แล้วก็สูดกลิ่นเค็มของทะเล! เย่!" },
        progress = { "17:1770844137:1638023056", "ถึงหรือยังครับ?" },
        completion = { "207:595232012:82265802 N 22:2061638670:873111157", "ว้าว ทะเลกว้างใหญ่มาก! นกนางนวลก็เต็มไปหมด ทั้งเสียงดังทั้งคึกคักเหมือนที่ผมคิดเลย แถวนั้นยังมีโจรสลัดด้วย เจ๋งสุด ๆ!\n\nขอบคุณที่พาผมไป Ratchet นะ {name} สนุกมากเลย!" },
    },
    [911] = { -- Gateway to the Frontier
        progress = { "17:1770844137:1638023056", "ถึงหรือยังครับ?" },
        title = { "23:736525527:1793317885", "ประตูสู่พรมแดน" },
        objective = { "107:663903952:245642134", "พาเด็กในความดูแลไปยัง Mor'shan Rampart ทางเหนือของ Barrens ก่อนเข้า Ashenvale" },
        description = { "314:826157612:904067607 N 163:1393269999:233710243", "เขาว่า Ashenvale เป็นดินแดนชายขอบแห่งใหม่ และ Mor'shan Rampart ใน Barrens คือประตูสู่ที่นั่น ถ้าได้เป็นนักบุกเบิกแล้วหาทุกอย่างที่ต้องใช้จากป่าดงพงไพรเองคงเจ๋งมาก! เขาว่าที่นั่นจะเป็นที่ที่ Horde กับ Alliance ปะทะกันหนักที่สุดในอนาคต ผมอยากไปอยู่ตรงนั้นด้วย {name}!\n\nพาผมไป Mor'shan Rampart ให้เห็นว่าดินแดนชายขอบเป็นยังไงหน่อยได้ไหมครับ? ผมอยากเห็นที่ที่ Horde ไล่พวกไนต์เอลฟ์ตัวเหม็นออกไป!" },
        completion = { "83:1010875138:465175379 N 137:1829410410:135788490 N 18:889747860:1678808807", "ว้าว ที่ Ashenvale มีการผจญภัยจริง ๆ ด้วย! พี่เคยสู้ใน Ashenvale ไหม {name}? โตขึ้นพอผมเป็นวีรชน ผมอยากมาสู้ที่ Ashenvale เพื่อเกียรติยศของ Horde!\n\nขอบคุณที่พาผมมาถึงชายแดนนะ {name} พี่สุดยอดเลย!" },
    },
    [915] = { -- You Scream, I Scream...
        title = { "23:1159132763:331501798", "ร้องหาไอศกรีม" },
        objective = { "94:1882610781:1394379526", "หา Strawberry Ice Cream ให้เด็กในความดูแล ดูเหมือนเขาจะชอบไอศกรีมยี่ห้อ Tigule's เป็นพิเศษ", variants = { { "104:534628007:1946528216", "หาไอศกรีมสตรอว์เบอร์รีให้เด็กในความดูแล ดูเหมือนเจ้าหนูจะชอบไอศกรีมของทิกูลกับฟอรอร์เป็นพิเศษ" } } },
        description = { "470:1408316156:18228837", "ไอศกรีม! ขอไอศกรีมหน่อยนะครับ นะ ๆ ๆ?! สตรอว์เบอร์รีเป็นรสโปรดของผม และไม่มีไอศกรีมสตรอว์เบอร์รีไหนในโลกอร่อยเท่า Tigule and Foror's Strawberry Ice Cream! ผมชอบไอศกรีมนี้ที่สุดในโลกเลย!\n\nผมเคยกินครั้งหนึ่งนานมาแล้วที่สนามแข่ง Shimmering Flats แต่ได้ยินว่าตอนนี้ในเมืองอาจมีขายแล้ว! นะครับ? ขอร้องล่ะครับ? ขอไอศกรีมสตรอว์เบอร์รีของทิกูลกับฟอรอร์โปะหน้าอีกด้วยได้ไหม?!" },
        progress = { "121:551412110:1308234910", "ผมอยากให้เขาทำไอศกรีมรสอื่นบ้าง แต่ผมก็โชคดีนะที่ชอบรสสตรอว์เบอร์รีที่สุด!" },
        completion = { "137:1402707441:1204309266 N 31:1654538861:418373943", "อื้มมม! ผมชอบไอศกรีมสตรอว์เบอร์รีของเขาจัง! ทิกูลกับฟอรอร์ทำไอศกรีมเก่งที่สุดเลย!\n\nขอบคุณมากนะ {name} นี่เป็นของอร่อยที่สุดเลย!" },
        required = { [7228] = { "29:1514077453:525625662", "ไอศกรีมสตรอว์เบอร์รีของทิกูล", variants = { { "39:1235944503:756033279", "ไอศกรีมสตรอว์เบอร์รีของทิกูลกับฟอรอร์" } } } },
        objectiveLabels = {
            item = { ["Tigule's Strawberry Ice Cream"] = "ไอศกรีมสตรอว์เบอร์รีของทิกูล", ["Tigule and Foror's Strawberry Ice Cream"] = "ไอศกรีมสตรอว์เบอร์รีของทิกูลกับฟอรอร์" },
        },
    },
    [925] = { -- Cairne's Hoofprint
        title = { "18:678511684:317064832", "รอยกีบเท้าของแคร์น" },
        objective = { "88:453535420:625129", "เดินทางไป Thunder Bluff เพื่อขอรอยกีบเท้าของ Cairne Bloodhoof ให้เด็กในความดูแล" },
        description = { "158:765748687:1972974119 N 242:114565303:471310823", "เขาว่าแคร์น บลัดฮูฟเป็นหนึ่งในวีรชนที่ยิ่งใหญ่ที่สุดของ Horde โตขึ้นผมก็อยากเป็นวีรชนของ Horde เหมือนกัน!\n\nพี่รู้จักแคร์นไหม {name}? ช่วยผมหน่อยได้ไหมครับ? ขอรอยกีบเท้าของท่านให้ผมที ผมไม่รู้จะไปขออย่างไร ท่านคงยุ่งเกินกว่าจะมาสนใจเด็กอย่างผม... แต่พี่น่ะ! พี่เป็นนักผจญภัยเหมือนท่านเลย ผมว่าท่านต้องยอมประทับรอยกีบให้พี่แน่!\n\nนะครับ?" },
        progress = { "159:334187285:2126643939 N 1:46:46", "ตอนที่พวกออร์คอยู่อย่างโดดเดี่ยวไร้มิตร พวกทอเรนต้อนรับพวกเขาในดินแดนแปลกถิ่นและแบ่งปันทุกอย่างโดยไม่เรียกร้องสิ่งตอบแทน นั่นแหละคือเกียรติยศ {name}" },
        completion = { "249:1750321831:1815330182 N 36:811113777:319183615", "ว้าว! พี่ขอรอยกีบของแคร์นให้ผมได้จริง ๆ ด้วย! ขอบคุณมากครับ! โอ้โห... ท่านเขียนข้อความถึงผมด้วย! ผมรู้อยู่แล้วว่าท่านต้องใจดีสุด ๆ! สักวันผมอาจได้ไปขอบคุณท่านเอง... ตอนที่ผมเป็นวีรชนของ Horde แล้ว!\n\nพี่สุดยอดเลย {name} ขอบคุณที่ใจดีกับผมนะครับ" },
        required = { [18643] = { "18:678511684:317064832", "รอยกีบเท้าของ Cairne" } },
        objectiveLabels = {
            item = { ["Cairne's Hoofprint"] = "รอยกีบเท้าของ Cairne" },
        },
    },
    [1468] = { -- Children's Week
        title = { "15:1618191835:1475970463", "สัปดาห์เด็ก" },
        description = { "388:39352507:826471272 N 89:1200014852:918066988", "ท่านยินดีช่วยพวกเราที่สถานเลี้ยงเด็กกำพร้าหรือ? ขอพรจงมีแก่ท่าน สหาย ความช่วยเหลือของท่านในสัปดาห์เด็กมีค่ามาก\n\nรับนกหวีดนี้ไป ท่านจะใช้มันได้เพียงช่วงสั้น ๆ โดยทั่วไปไม่เกินสัปดาห์เด็ก ใช้แล้วท่านจะได้คุยกับเด็กที่ตกลงรับดูแล หากใช้อีกครั้ง เด็กจะกลับไป\n\nเอาเลย {name} เป่านกหวีดแล้วพบเด็กที่ท่านจะดูแลเถิด! ข้ามั่นใจว่าเด็กอยากพบท่านมาก" },
        objective = { "101:490682006:778293762", "ใช้ Human Orphan Whistle เพื่อคุยกับเด็กที่ท่านจะดูแลในสัปดาห์เด็ก" },
        completion = { "324:865933282:519917863", "เอ่อ... สวัสดีครับ ผมชื่อแรนดิส พี่จะมาดูแลผมใช่ไหม? พี่เป็นนักผจญภัยเหมือนที่พ่อกับแม่ผมเคยเป็นเลย ยินดีที่ได้รู้จักครับ\n\nหวังว่าเราจะสนุกด้วยกันนะครับ ผมมีเรื่องที่อยากทำอยู่หลายอย่าง คุณแม่บ้านบอกว่าสัปดาห์นี้พี่จะเป็นเหมือนพี่ชายของผม ผมอยากให้เป็นแบบนั้นมากเลย ครับคุณพี่", variants = { { "324:100805274:495432851", "เอ่อ... สวัสดีครับ ผมชื่อแรนดิส พี่จะมาดูแลผมใช่ไหม? พี่เป็นนักผจญภัยเหมือนที่พ่อกับแม่ผมเคยเป็นเลย ยินดีที่ได้รู้จักครับ\n\nหวังว่าเราจะสนุกด้วยกันนะครับ ผมมีเรื่องที่อยากทำอยู่หลายอย่าง คุณแม่บ้านบอกว่าสัปดาห์นี้พี่จะเป็นเหมือนพี่สาวของผม ผมอยากให้เป็นแบบนั้นมากเลย ครับคุณพี่สาว" } } },
    },
    [1479] = { -- The Bough of the Eternals
        progress = { "17:1770844137:1638023056", "ถึงหรือยังครับ?" },
        title = { "25:781753907:414750933", "กิ่งก้านแห่งผู้เป็นนิรันดร์" },
        objective = { "119:533237027:677301499", "พาเด็กกำพร้าไปที่ธนาคารใน Darnassus ตัวธนาคารอยู่ในโพรงของต้นไม้ชื่อ Bough of the Eternals" },
        description = { "372:659327603:1744017779", "ผมเคยได้ยินว่าไนต์เอลฟ์ทำธนาคารไว้ในต้นไม้ที่ดูเหมือนหมีด้วย เจ๋งมากเลย! ไนต์เอลฟ์ที่รักธรรมชาติก็เจ๋งดีนะ แต่หมีนี่สุดยอดกว่าอีก!\n\nพาผมไปดูต้นไม้รูปหมีที่ Darnassus หน่อยได้ไหมครับ? มีเรือไปลงใกล้ ๆ นั่นด้วย ใช้เวลาไม่นานหรอกครับ ขอร้องล่ะ นะครับ นะ!" },
        completion = { "241:1608816628:754697587 N 17:334331409:85053227", "ว้าว Bough of the Eternals เจ๋งกว่าที่ผมคิดอีก! ไม่คิดเลยว่าจะใหญ่ขนาดนั้น เห็นนกบนยอดด้วยไหมครับ?! ผมสงสัยจังว่าเขาทำให้กิ่งไม้ออกมาเป็นรูปแบบนั้นได้ยังไง!\n\nขอบคุณที่พาผมไป Darnassus นะ {name} พี่เจ๋งมาก!" },
    },
    [1558] = { -- The Stonewrought Dam
        progress = { "17:1770844137:1638023056", "ถึงหรือยังครับ?" },
        title = { "20:314218500:302622640", "เขื่อนสโตนรอต" },
        objective = { "143:1710510084:1113174428", "พาเด็กกำพร้าไปยัง Stonewrought Dam ใน Loch Modan พาเขาไปกลางเขื่อนเพื่อให้มองออกไปเห็นน้ำตกขนาดใหญ่" },
        description = { "434:337918258:1800206862", "พวกคนแคระกับโนมอยู่ที่ Ironforge กันหมด ใกล้ ๆ ที่นั่นมีที่ชื่อ Loch Modan พวกคนแคระสร้างเขื่อนใหญ่มหึมาไว้ด้วย เขาว่าเป็นสิ่งก่อสร้างที่ใหญ่ที่สุดอย่างหนึ่งที่เคยมีใครสร้างมาเลย ว้าว!\n\nพาผมไปดูเขื่อนที่ Loch Modan หน่อยได้ไหมครับ? ผมว่าชื่อสโตน... เอ่อ... เขื่อนสโตนเรนช์? สโตนรอต? แต่ใหญ่แน่ ๆ ล่ะครับ ผมอยากมองออกไปเห็นน้ำตกใหญ่ ผมสัญญาว่าจะไม่ชะโงกออกไปไกลเกิน!" },
        completion = { "345:1447742070:653514829", "ว้าว เขื่อนใหญ่กว่าที่ผมคิดไว้เยอะเลย! เสียงน้ำดังจนแทบไม่ได้ยินเสียงตัวเองพูด! พี่คิดว่าน้ำจะมีวันหมดไหมครับ? แล้วถ้าเขื่อนแตกจะเกิดอะไรขึ้นนะ! โห น่ากลัวจัง!\n\nขอบคุณที่พาผมไปดูเขื่อนนะครับ พี่ใจดีมากเลย เห็นไหม ผมบอกแล้วว่าจะไม่ชะโงกออกไปไกลเกิน!" },
    },
    [1687] = { -- Spooky Lighthouse
        progress = { "17:1770844137:1638023056", "ถึงหรือยังครับ?" },
        title = { "17:1994985570:1667631834", "ประภาคารผีสิง" },
        objective = { "64:512242188:2036988171", "พาเด็กกำพร้าไปดูประภาคารนอกชายฝั่ง Westfall" },
        description = { "414:407258798:69222341", "บางคืนดึก ๆ คุณแม่บ้านที่สถานเลี้ยงเด็กกำพร้าจะเล่าเรื่องผีให้ฟัง สนุกสุด ๆ เลย! เรื่องหนึ่งเป็นผีสิงประภาคารที่ Westfall เขาว่าผีนั่นเคยเป็นกัปตันโจรสลัดที่ถูกโจรสลัดพวกอื่นยึดเรือไป ว้าว!\n\nพาผมไปประภาคารที่ Westfall หน่อยได้ไหมครับ? ผมอยากรู้ว่าผีกัปตันยังอยู่ที่นั่นไหม ผมสัญญาว่าจะอยู่ใกล้ ๆ พี่ ไม่วิ่งหนีไปไหนหรอก!" },
        completion = { "237:2193594:23379845 N 123:1849385639:759899466", "ว้าว ผีตัวเป็น ๆ เลย! เจ๋งมาก ผมแทบอดใจรอไปเล่าให้ทุกคนที่สถานเลี้ยงเด็กกำพร้าฟังไม่ไหวแล้ว กัปตันเกรย์สัน... หน้าตาเหมือนโจรสลัดจริง ๆ ด้วย! โตขึ้นผมอยากเป็นผีโจรสลัดเหมือนกัน!\n\nขอบคุณที่พาผมไป Westfall นะ {name} ผมรู้ว่าแถวนอกเมืองมีอะไรน่ากลัวตั้งเยอะ หวังว่าผมคงไม่ทำให้พี่ลำบากมากนะ พี่เจ๋งที่สุดเลย!" },
    },
    [1800] = { -- Lordaeron Throne Room
        progress = { "17:1770844137:1638023056", "ถึงหรือยังครับ?" },
        title = { "21:1991195448:805183895", "ท้องพระโรงแห่งลอร์แดรอน" },
        objective = { "100:2039153032:1396438838", "พาเด็กในความดูแลไปยัง Lordaeron Throne Room เก่าก่อนทางลง Undercity" },
        description = { "243:1012221748:483550372 N 210:2101013493:392094717", "ถ้าพวกเราเป็นเด็กดีและทำงานที่ได้รับมอบหมาย คุณแม่บ้านจะเล่าเรื่องศึกกับตำนานสนุก ๆ ให้ฟังตอนกลางคืน เรื่องหนึ่งเล่าว่า Lordaeron ล่มสลายได้อย่างไร และอาร์ธัสผู้ชั่วร้ายฆ่าพ่อของตัวเองเพื่อขึ้นเป็นผู้ปกครองได้อย่างไร\n\nเขาไม่มีเกียรติเลย {name}! เมื่อผมโตขึ้นและเป็นนักรบผู้เก่งกาจของ Horde ผมจะใช้ดาบเพื่อเกียรติยศและจะไม่ทำเรื่องชั่วแบบนั้นเด็ดขาด!\n\nพาผมไปดูท้องพระโรงหน่อยได้ไหมครับ? อยู่ก่อนทางลงไป Undercity นั่นเอง" },
        completion = { "28:187174071:1129483790 N 249:2133168670:1723378757 N 18:173155512:392357215", "ท้องพระโรงนั้นน่ากลัวจัง {name}! ถึงจะว่างเปล่า แต่ผมรู้สึกว่าเคยเกิดเรื่องชั่วร้ายมาก ๆ ที่นั่น ผมทั้งโกรธ... แล้วก็เศร้าด้วย ตอนนี้ผมเข้าใจแล้วว่าทำไมคุณแม่บ้านถึงเล่าเรื่องพวกนี้ ผมจะไม่ทรยศพวกพ้องแบบนั้นเด็ดขาด!\n\nขอบคุณที่พาผมไปดูท้องพระโรงนะ {name} ผมได้เรียนรู้อะไรเยอะเลย" },
    },
    [3861] = { -- CLUCK!
        title = { "6:682416593:354922387", "กุ๊ก ๆ!" },
        objective = { "151:233306936:570859566", "หา Special Chicken Feed แล้วกลับไปหาไก่ที่ท่านผูกมิตรด้วย เมื่อเจอมัน ให้ใช้ /cheer ใส่มันก่อนลองให้ Special Chicken Feed" },
        description = { "314:1599197920:2122830950", "“กุ๊ก... กุ๊ก... กุ๊ก... กะต๊าก!\n\nกุ๊ก... กุ๊ก... กุ๊ก”\n\nไก่เงยหน้ามองท่านแล้วเริ่มใช้กรงเล็บเขี่ยพื้น ดูเหมือนมันกำลังสะกดคำอะไรสักอย่าง แต่ท่านไม่แน่ใจ หรือว่าจะเป็น... S-A-L-D-E-A-N? ก่อนจะทันถาม ไก่ก็หันไปทำธุระของมันต่อ" },
        progress = { "108:1153469099:1875618288", "ไก่จ้องท่านด้วยดวงตาดำขลับเย็นชา มันรอท่านอยู่อย่างหิวโหย\n\n“กะต๊ากกก!\n\nกุ๊ก... กุ๊ก... กุ๊ก”" },
        completion = { "227:1852616660:1326753439", "“กะต๊าก!!!”\n\nไก่เริ่มจิกกินอาหารที่ท่านวางลงอย่างตะกรุมตะกราม\n\nครู่หนึ่งต่อมา ไก่ก็หันมองรอบตัวอย่างตกใจ มันขยับไปมาอย่างอึดอัด หรือว่าไก่ตัวนี้กำลังจะออกไข่? ท่านคิดว่าน่าจะลองดูใต้ตัวมัน" },
        required = { [11109] = { "20:1921783211:471592995", "อาหารไก่สูตรพิเศษ" } },
        objectiveLabels = {
            item = { ["Special Chicken Feed"] = "อาหารไก่สูตรพิเศษ" },
        },
    },
    [4822] = { -- You Scream, I Scream...
        title = { "23:1159132763:331501798", "ร้องหาไอศกรีม" },
        objective = { "94:1882610781:1394379526", "หา Strawberry Ice Cream ให้เด็กในความดูแล ดูเหมือนเขาจะชอบไอศกรีมยี่ห้อ Tigule's เป็นพิเศษ", variants = { { "104:534628007:1946528216", "หาไอศกรีมสตรอว์เบอร์รีให้เด็กในความดูแล ดูเหมือนเจ้าหนูจะชอบไอศกรีมของทิกูลกับฟอรอร์เป็นพิเศษ" } } },
        description = { "470:1408316156:18228837", "ไอศกรีม! ขอไอศกรีมหน่อยนะครับ นะ ๆ ๆ?! สตรอว์เบอร์รีเป็นรสโปรดของผม และไม่มีไอศกรีมสตรอว์เบอร์รีไหนในโลกอร่อยเท่า Tigule and Foror's Strawberry Ice Cream! ผมชอบไอศกรีมนี้ที่สุดในโลกเลย!\n\nผมเคยกินครั้งหนึ่งนานมาแล้วที่สนามแข่ง Shimmering Flats แต่ได้ยินว่าตอนนี้ในเมืองอาจมีขายแล้ว! นะครับ? ขอร้องล่ะครับ? ขอไอศกรีมสตรอว์เบอร์รีของทิกูลกับฟอรอร์โปะหน้าอีกด้วยได้ไหม?!" },
        progress = { "121:551412110:1308234910", "ผมอยากให้เขาทำไอศกรีมรสอื่นบ้าง แต่ผมก็โชคดีนะที่ชอบรสสตรอว์เบอร์รีที่สุด!" },
        completion = { "137:1402707441:1204309266 N 31:1654538861:418373943", "อื้มมม! ผมชอบไอศกรีมสตรอว์เบอร์รีของเขาจัง! ทิกูลกับฟอรอร์ทำไอศกรีมเก่งที่สุดเลย!\n\nขอบคุณมากนะ {name} นี่เป็นของอร่อยที่สุดเลย!" },
        required = { [7228] = { "29:1514077453:525625662", "ไอศกรีมสตรอว์เบอร์รีของทิกูล", variants = { { "39:1235944503:756033279", "ไอศกรีมสตรอว์เบอร์รีของทิกูลกับฟอรอร์" } } } },
        objectiveLabels = {
            item = { ["Tigule's Strawberry Ice Cream"] = "ไอศกรีมสตรอว์เบอร์รีของทิกูล", ["Tigule and Foror's Strawberry Ice Cream"] = "ไอศกรีมสตรอว์เบอร์รีของทิกูลกับฟอรอร์" },
        },
    },
    [5502] = { -- A Warden of the Horde
        progress = { "35:2085754745:1918631995 N 80:1172511899:1094489019", "ดีใจที่ได้พบท่านอีก {name} ท่านทำหน้าที่ที่อาสาไว้ในสัปดาห์เด็กเรียบร้อยหรือยัง?" },
        title = { "21:713046281:866629664", "ผู้ดูแลเด็กแห่ง Horde" },
        objective = { "135:1313074846:1583418501", "พาเด็กในความดูแลกลับสถานเลี้ยงเด็กกำพร้าที่ Orgrimmar โดยส่ง Orcish Orphan Whistle ให้ Orphan Matron Battlewail ใน Valley of Honor" },
        description = { "34:2036025115:920009012 N 348:1352613959:183872163", "พี่ใจดีกับผมมากเลย {name} ผมไม่เคยคิดว่าสัปดาห์เด็กจะสนุกขนาดนี้ ขอบคุณนะครับ ผมจะไม่มัวเศร้ากับเรื่องที่เกิดขึ้น พ่อกับแม่เคยสอนให้ผมลุกขึ้นสู้ไม่ว่าจะเจอเรื่องร้ายแค่ไหน ผมจะเป็นฮีโร่... เหมือนพี่เลย\n\nเสียดายจัง แต่ถึงเวลาที่ผมต้องกลับบ้านแล้ว เรากลับกันเถอะ ผมจะบอกคุณแม่บ้านว่าพี่เจ๋งแค่ไหน!" },
        completion = { "27:669164294:1440974778 N 291:1764905854:88299849 N 68:1187967566:528463714", "ขอให้เหล่าวิญญาณอวยพรท่าน {name} ท่านทำเพื่อกรันธ์เกินกว่าที่คนส่วนใหญ่จะนึกทำให้เขาเสียอีก ขอบคุณนะ ท่านคือตัวอย่างของวีรชนแห่ง Horde อย่างแท้จริง\n\nถ้าพอมีเวลา โปรดกลับมาเยี่ยมพวกเราบ้างนะ ทั้งกรันธ์และข้าคงดีใจมาก\n\nกรันธ์สนุกกับท่านมาก {name} เขาอยากมอบสัตว์เลี้ยงตัวโปรดให้สักตัวเป็นที่ระลึกถึงเขา" },
        required = { [18597] = { "21:339318006:1203295014", "นกหวีดเรียกเด็กกำพร้าออร์ค" } },
        objectiveLabels = {
            item = { ["Orcish Orphan Whistle"] = "นกหวีดเรียกเด็กกำพร้าออร์ค" },
        },
    },
    [9319] = { -- A Light in Dark Places
        title = { "22:1245421756:755404503", "แสงในแดนมืด" },
        objective = { "140:1088031445:1260653921", "หาและแตะกองไฟใน Blackrock Spire, Dire Maul, Scholomance และ Stratholme แล้วกลับไปหา Festival Flamekeeper" },
        description = { "53:2063843659:554679062 N 330:1159500272:1191894342", "หลายเผ่าพันธุ์ร่วมฉลองเทศกาลนี้ด้วยเช่นกัน {name} เปลวไฟส่องถึงสิ่งมีชีวิตและวัฒนธรรมทั้งปวง แม้ในสถานที่มืดมิดที่สุดก็ยังมีคนจุดไฟ\n\nหากอยากเห็นด้วยตาตัวเอง จงลงไปยังส่วนลึก หากองไฟที่ลุกโชนใน Stratholme และ Scholomance ท่ามกลางเหล่าโอเกอร์ใน Dire Maul และในโถงของ Blackrock Spire ข้าจะรอท่านกลับมา" },
        progress = { "41:82453752:1530716790", "ท่านหาทางฝ่าความมืดไปได้หรือยัง?" },
        completion = { "60:379349179:894100007 N 270:898577430:121222165", "พลังของเปลวไฟที่ท่านพบก้องอยู่ในตัวท่าน {name} ไฟที่ท่านเจอทรงพลังยิ่ง หากรู้วิธีก็ดึงพลังนั้นมาใช้ได้...\n\n<ผู้ดูแลเปลวไฟพึมพำคาถาด้วยภาษาลี้ลับ แล้วหยิบขวดเรืองแสงออกมา>\n\nอา! นี่ไง ขอให้สิ่งนี้ส่องทางให้ท่านไม่ว่าจะไปแห่งใด" },
    },
    [9322] = { -- Wild Fires in Kalimdor
        title = { "22:1964404073:101932550", "ไฟแรงกล้าแห่งคาลิมดอร์" },
        objective = { "130:913865173:635464160", "ไปเยือนค่าย Midsummer ใน Azshara, Silithus, Un'Goro Crater และ Winterspring แล้วกลับไปหา Festival Flamekeeper" },
        description = { "466:1472766525:1466260786", "ผู้คนฉลอง Midsummer Fire Festival กันทั่วอาเซรอธ รวมถึงแผ่นดินคาลิมดอร์อันหลากหลาย ท่านดูพร้อมเดินทางดี ออกไปเที่ยวสักรอบดีไหม?\n\nจะซึมซับเทศกาลกลางฤดูร้อนได้เต็มที่ก็ต้องไปเห็นเปลวไฟสีฟ้าร้อนแรงตามที่ต่าง ๆ ผู้ร่วมงานจุดไฟไว้ทางตะวันตกของ Winterspring อันหนาวเย็น ทางตะวันออกเฉียงเหนือของ Azshara ใกล้ Valor's Rest ในแดนร้าง Silithus และตรงทางเข้า Un'Goro อันเขียวชอุ่ม เสร็จแล้วค่อยกลับมา" },
        progress = { "44:931851282:1618666715", "เปลวไฟในคาลิมดอร์ยังลุกสว่างดีไหม?" },
        completion = { "171:764906250:2096784279", "จิตวิญญาณของท่านเปล่งประกายด้วยความอบอุ่นจากไฟแห่งคาลิมดอร์ สหาย ไอร้อนนั้นทำให้กระปรี้กระเปร่าใช่ไหม?\n\nเมื่อพลังนั้นจางลง ของพวกนี้อาจช่วยให้ท่านรู้สึกเช่นนั้นอีกครั้ง" },
        steps = { { "16:1770782484:1459003768", "เปลวไฟแห่ง Azshara" }, { "17:231826207:523622947", "เปลวไฟแห่ง Silithus" }, { "16:793419027:1883923227", "เปลวไฟแห่ง Un'Goro" }, { "21:111774101:839272872", "เปลวไฟแห่ง Winterspring" } },
    },
    [9323] = { -- Wild Fires in the Eastern Kingdoms
        title = { "34:944738880:1985156081", "ไฟแรงกล้าแห่งอาณาจักรตะวันออก" },
        objective = { "153:1159039431:1379426190", "ไปเยือนค่าย Fire Festival ใน Blasted Lands, Eastern Plaguelands, Hinterlands และ Searing Gorge แล้วคุยกับ Festival Flamekeeper" },
        description = { "60:904317464:1497199057 C 416:739530497:1229400802", "การเฉลิมฉลองเปลวไฟของเรากระจายไปทั่วแผ่นดิน ท่าน{class} ทุกแห่งล้วนได้รับไออุ่นจากเทศกาล และไฟที่แรงที่สุดจะลุกเป็นสีฟ้าสดใส จงออกไปตามหา\n\nกองหนึ่งอยู่ทางเหนือของ Blackrock Spire ไปนิดเดียว ที่เหลืออยู่ลึกเข้าไปใน Eastern Plaguelands ใกล้เมืองทรุดโทรม ตามถนนที่มุ่งสู่หน้าผาในเขตภูเขาของ Hinterlands และบนทางไป Dark Portal ใน Blasted Lands\n\nเสร็จแล้วค่อยกลับมา" },
        progress = { "62:115740881:96050680", "ท่านเดินทางข้ามทวีปแล้วหรือยัง? ความกระจ่างรอท่านอยู่" },
        completion = { "336:2105361412:1294480318", "อา กลับมาแล้ว ดูเหนื่อยขึ้นหน่อย ฝุ่นเกาะขึ้นนิด แต่ได้ความกระจ่างแล้ว! ไอร้อนในเทศกาลนี้แผ่ถึงเราทุกคนและรวมเราไว้ด้วยกัน ตัวท่านเองเปล่งประกายด้วยพลังจากกองไฟที่ได้สัมผัส\n\nอา แต่สมัยนี้มีเพียงความกระจ่างคงเป็นรางวัลตอบแทนงานที่น้อยไปหน่อย เอาของเหล่านี้ไปเถิด ขอให้สนุกกับงานฉลอง" },
        steps = { { "26:1031892354:1084404049", "เปลวไฟแห่ง Blasted Lands" }, { "24:671477988:1598337403", "เปลวไฟแห่ง Plaguelands" }, { "24:1399474495:1512647487", "เปลวไฟแห่ง The Hinterlands" }, { "22:1381517401:2005883324", "เปลวไฟแห่ง Searing Gorge" } },
    },
    [9324] = { -- Stealing Orgrimmar's Flame
        title = { "26:1095361917:630498489", "ชิงเปลวไฟจาก Orgrimmar" },
        objective = { "57:443664115:433504572", "นำ Flame of Orgrimmar กลับไปให้ Festival Loremaster" },
        description = { "150:542985221:1121436656", "ไฟที่ชิงมาจากใจกลาง Orgrimmar แผ่ความอบอุ่นไปทั่วร่างท่าน พลังดิบนี้แปลกใหม่สำหรับท่าน แต่ Festival Loremaster อาจรู้เรื่องนี้มากกว่า..." },
        progress = { "28:621325095:1645692825 R 25:567160462:583925949", "ตัวท่านแทบจะเรืองแสงอยู่แล้ว ท่าน{race} ท่านถืออะไรอยู่หรือ?" },
        completion = { "291:1902287346:355694178", "นี่อะไร? ถ้าข้าดูไม่ผิด ท่านชิงไฟนี้มาจากใจกลาง Orgrimmar เลย! ไอร้อนแผดเผาสะท้อนจิตใจดุดันของพวกออร์คกับโทรลล์ เป็นไฟที่เหมาะจะเก็บรวมกับของเราเหลือเกิน ท่านกล้าจริง ๆ ที่ลอบเข้าไปในถิ่นศัตรูเพื่อชิงไฟศักดิ์สิทธิ์!" },
    },
    [9325] = { -- Stealing Thunder Bluff's Flame
        progress = { "28:621325095:1645692825 R 25:567160462:583925949", "ตัวท่านแทบจะเรืองแสงอยู่แล้ว ท่าน{race} ท่านถืออะไรอยู่หรือ?" },
        title = { "30:864558061:722278331", "ชิงเปลวไฟจาก Thunder Bluff" },
        objective = { "61:2088893749:431623984", "นำ Flame of Thunder Bluff กลับไปให้ Festival Loremaster" },
        description = { "148:154654006:49034192", "ไฟที่ชิงมาจากเหล่าชาแมนแห่ง Thunder Bluff แผ่ความอบอุ่นไปทั่วร่างท่าน พลังดิบนี้แปลกใหม่สำหรับท่าน แต่ Festival Loremaster อาจรู้เรื่องนี้มากกว่า..." },
        completion = { "152:1333124343:1509146836 N 97:1927477386:427771359", "ถ้าข้าเดาไม่ผิด ไฟนี้มาจากหน้าผา Thunder Bluff! พลังของเหล่าวิญญาณก้องอยู่ในไฟนี้! ท่านเป็นหัวขโมยฝีมือดีจริง ๆ {name} รับสิ่งนี้เป็นค่าตอบแทนฝีมือเถิด ทีนี้ถ้าเราได้ไฟจากทั้งสามเมืองมาครบก็คงดี..." },
    },
    [9326] = { -- Stealing the Undercity's Flame
        progress = { "28:621325095:1645692825 R 25:567160462:583925949", "ตัวท่านแทบจะเรืองแสงอยู่แล้ว ท่าน{race} ท่านถืออะไรอยู่หรือ?" },
        title = { "30:1763135835:1276828393", "ชิงเปลวไฟจาก Undercity" },
        objective = { "61:1174477851:54044405", "นำ Flame of the Undercity กลับไปให้ Festival Loremaster" },
        description = { "150:2041996352:1709306924", "ไฟที่ชิงมาจากซากเมืองเหนือ Undercity แผ่ความอบอุ่นไปทั่วร่างท่าน พลังดิบนี้แปลกใหม่สำหรับท่าน แต่ Festival Loremaster อาจรู้เรื่องนี้มากกว่า..." },
        completion = { "222:1668060078:37036601", "อืม... ไฟนี้แปลกจัง! มันดูริบหรี่แทบจะมอด แต่กลับร้อนจัด ท่านว่าชิงมาจาก Undercity หรือ? น่าสนใจจริง ๆ ถ้าได้ไฟจากทั้งสามเมืองมาครบ ใครจะรู้ว่าเราจะทำอะไรได้บ้าง?" },
    },
    [9330] = { -- Stealing Stormwind's Flame
        progress = { "28:621325095:1645692825 R 25:567160462:583925949", "ตัวท่านแทบจะเรืองแสงอยู่แล้ว ท่าน{race} ท่านถืออะไรอยู่หรือ?" },
        title = { "26:424571745:1923953479", "ชิงเปลวไฟจาก Stormwind" },
        objective = { "58:1045373617:286773264", "นำ Flame of Stormwind กลับไปให้ Festival Talespinner" },
        description = { "151:486358925:1344101257", "ไฟที่ชิงมาจากใจกลาง Stormwind แผ่ความอบอุ่นไปทั่วร่างท่าน พลังดิบนี้แปลกใหม่สำหรับท่าน แต่ Festival Talespinner อาจรู้เรื่องนี้มากกว่า..." },
        completion = { "220:1181172839:658797033", "แล้วไฟที่ลุกสว่างดวงนี้... ท่านว่ามาจาก Stormwind หรือ? ยอดเยี่ยม! คงเป็นการผจญภัยครั้งใหญ่ทีเดียว ข้าจะจ่ายค่าตอบแทนให้แน่นอน ถ้าเจออะไรแบบนี้อีก อย่าลืมมาคุยกับข้าล่ะ" },
    },
    [9331] = { -- Stealing Ironforge's Flame
        progress = { "28:621325095:1645692825 R 25:567160462:583925949", "ตัวท่านแทบจะเรืองแสงอยู่แล้ว ท่าน{race} ท่านถืออะไรอยู่หรือ?" },
        title = { "26:2128624343:1298914716", "ชิงเปลวไฟจาก Ironforge" },
        objective = { "58:1374001491:564264567", "นำ Flame of Ironforge กลับไปให้ Festival Talespinner" },
        description = { "151:1622924166:1251842073", "ไฟที่ชิงมาจากใจกลาง Ironforge แผ่ความอบอุ่นไปทั่วร่างท่าน พลังดิบนี้แปลกใหม่สำหรับท่าน แต่ Festival Talespinner อาจรู้เรื่องนี้มากกว่า..." },
        completion = { "113:970997265:2129984624 N 85:768813547:1948389642", "ไฟที่ลุกแรงเช่นนี้ต้องมาจากโถง Ironforge แน่ มันมั่นคงไม่แพ้พวกคนแคระเลย ได้ของดีมาทีเดียว {name} ถ้าข้าได้ไฟจากเมืองอื่น ๆ ด้วย... อา ช่างเถอะ นี่ค่าตอบแทนของท่าน" },
    },
    [9332] = { -- Stealing Darnassus's Flame
        progress = { "28:621325095:1645692825 R 25:567160462:583925949", "ตัวท่านแทบจะเรืองแสงอยู่แล้ว ท่าน{race} ท่านถืออะไรอยู่หรือ?" },
        title = { "26:1065356326:1994668908", "ชิงเปลวไฟจาก Darnassus" },
        objective = { "58:2099246390:660523342", "นำ Flame of Darnassus กลับไปให้ Festival Talespinner" },
        description = { "146:1841195100:1057999201", "ไฟที่ชิงมาจากชายฝั่ง Teldrassil แผ่ความอบอุ่นไปทั่วร่างท่าน พลังดิบนี้แปลกใหม่สำหรับท่าน แต่ Festival Talespinner อาจรู้เรื่องนี้มากกว่า..." },
        completion = { "35:1144295166:1677497604 N 181:641133705:1174611380", "ไฟนี้เจือความโศกเศร้าจากกาลก่อน {name} ท่านว่าชิงมาจากรากของ Teldrassil หรือ? น่าสนใจจริง ๆ นี่คือรางวัลสำหรับฝีมือของท่าน หากเจออะไรแบบนี้อีกก็กลับมาหาข้า ข้าอาจมีทางใช้ประโยชน์จากมัน" },
    },
    [9339] = { -- A Thief's Reward
        title = { "16:1528659523:1493321116", "รางวัลของหัวขโมย" },
        objective = { "40:1776682044:815963933", "นำ Flame of Stormwind กลับไปให้ (NAME)" },
        description = { "146:338284511:376171409", "ไฟที่ชิงมาจากใจกลาง Stormwind แผ่ความอบอุ่นไปทั่วร่างท่าน พลังดิบนี้แปลกใหม่สำหรับท่าน แต่ (NAME) อาจรู้เรื่องนี้มากกว่า..." },
        completion = { "30:1073906287:1599673703 N 116:286744325:465763968", "วันนี้ท่านพิสูจน์ตัวเองแล้ว {name}\n\nข้าแทบไม่มีสิ่งอื่นจะให้ท่าน แต่ข้ามีมงกุฎใบนี้ เป็นของขวัญที่คู่ควรกับผู้พิชิต ขอให้มันส่องทางให้ท่าน" },
    },
    [9365] = { -- A Thief's Reward
