        objective = { "40:1776682044:815963933", "นำ Flame of Stormwind กลับไปให้ (NAME)" },
        description = { "146:338284511:376171409", "ไฟที่ชิงมาจากใจกลาง Stormwind แผ่ความอบอุ่นไปทั่วร่างท่าน พลังดิบนี้แปลกใหม่สำหรับท่าน แต่ (NAME) อาจรู้เรื่องนี้มากกว่า..." },
        completion = { "30:1073906287:1599673703 N 116:286744325:465763968", "วันนี้ท่านพิสูจน์ตัวเองแล้ว {name}\n\nข้าแทบไม่มีสิ่งอื่นจะให้ท่าน แต่ข้ามีมงกุฎใบนี้ เป็นของขวัญที่คู่ควรกับผู้พิชิต ขอให้มันส่องทางให้ท่าน" },
    },
    [9367] = { -- The Festival of Fire
        title = { "20:1742339860:1249584203", "เทศกาลแห่งเปลวไฟ" },
        objective = { "125:1616867238:1697964904", "แตะกองไฟใน Stormwind, Ironforge และ Darnassus แล้วคุยกับ Festival Loremaster ในเมืองหลวง" },
        description = { "469:659790648:1644828921", "เทศกาลกลางฤดูร้อนเวียนมาถึงอีกครั้ง!\n\nตามธรรมเนียม ทุกปีเราจะเลือกผู้ดูแลเปลวไฟมาคอยรักษากองไฟในเมืองหลวงของเรา แม้จะจุดไฟกันทั่วอาเซรอธ แต่ไฟของเราต้องร้อนแรงและสว่างที่สุดจึงจะสมกับการเฉลิมฉลองฤดูกาลนี้\n\nข้ามีเรื่องให้ช่วย ถ้าท่านไม่ขัดข้อง ข้ายังไม่ได้ข่าวว่าไฟในเมืองหลวงทุกแห่งลุกดีหรือเปล่า ไปที่นั่นแล้วผิงไฟดูด้วยตัวเองเถิด ดูให้แน่ใจว่าไฟร้อนจริง ๆ!" },
        progress = { "22:1144220937:80615699", "กองไฟยังลุกอยู่ไหม?" },
        completion = { "198:1169259857:1597684608", "ยอดเยี่ยม! ถ้ากองไฟได้รับการดูแลดีอย่างที่ท่านว่า ปีนี้เราคงเลือกผู้ดูแลเปลวไฟได้ขยันขันแข็งทีเดียว ขอบคุณที่ไปตรวจให้ข้า รับสิ่งนี้ไว้แทนคำชื่นชมจากข้าเถิด" },
        steps = { { "18:20712025:447024660", "เปลวไฟแห่ง Stormwind" }, { "18:390573268:2098746119", "เปลวไฟแห่ง Ironforge" }, { "18:1651329711:1849643287", "เปลวไฟแห่ง Darnassus" } },
    },
    [9386] = { -- A Light in Dark Places
        title = { "22:1245421756:755404503", "แสงในแดนมืด" },
        progress = { "41:82453752:1530716790", "ท่านหาทางฝ่าความมืดไปได้หรือยัง?" },
        objective = { "141:178373039:670650961", "หาและแตะกองไฟใน Blackrock Spire, Dire Maul, Scholomance และ Stratholme แล้วคุยกับ Festival Flamekeeper" },
        description = { "244:310332922:48072182 N 1:46:46", "กระตือรือร้นดีนี่ หากท่านยินดีลงไปยังส่วนลึกอีกครั้ง ข้าก็ยินดีให้รางวัล\n\nหากองไฟที่ลุกอยู่ใน Stratholme, Scholomance, Dire Maul และในโถงของ Blackrock Spire ข้าจะรอท่านกลับมา {name}" },
        completion = { "58:427935737:527122638", "เจ้าพิสูจน์แล้วว่ายังพอมีประโยชน์อยู่บ้าง เจ้าผู้มีวันตาย" },
    },
    [9388] = { -- Flickering Flames in Kalimdor
        title = { "29:1756540887:14314972", "เปลวไฟไหวระริกแห่งคาลิมดอร์" },
        objective = { "128:140776507:516542106", "ไปเยือนกองไฟใน Ashenvale, Barrens, Darkshore และ Stonetalon Mountains แล้วคุยกับ Festival Flamekeeper" },
        description = { "58:1702147151:1025312778 N 420:1773740379:607314864", "วันนี้มีไฟลุกอยู่ทั่วโลก {name} ไฟสีเขียวดูแลยากที่สุด เพราะปล่อยไว้ไม่นานก็มอด ช่วยไปดูให้ผู้ดูแลเปลวไฟของเราหน่อยว่าไฟสีมรกตบนคาลิมดอร์ยังลุกดีอยู่ไหม\n\nท่านจะพบไฟใกล้ Ratchet ใน Barrens ใกล้ Master's Glaive ใน Darkshore ที่สะพานใกล้ Silverwing Outpost ในป่า Ashenvale และใกล้ทางแยกไป Windshear Crag บนถนนหลักใน Stonetalon Mountains" },
        progress = { "48:1040533251:541586043", "กองไฟจะมอดก่อนจบเทศกาลไม่ได้!" },
        completion = { "123:1391523786:120374491 N 29:1700038222:875316037", "อา ไฟยังลุกอยู่สินะ ดีใจจริง ๆ จะปล่อยให้ไฟพวกนั้นมอดก่อนเวลาไม่ได้ ท่านทำได้ดี {name} รับสิ่งนี้พร้อมพรจากข้าเถิด" },
        steps = { { "18:975795044:53617324", "เปลวไฟแห่ง Ashenvale" }, { "20:46168414:961475523", "เปลวไฟแห่ง Barrens" }, { "18:26628517:909039939", "เปลวไฟแห่ง Darkshore" }, { "19:142984684:1036686865", "เปลวไฟแห่ง Stonetalon" } },
    },
    [9389] = { -- Flickering Flames in the Eastern Kingdoms
        title = { "41:502112129:809826976", "เปลวไฟไหวระริกแห่งอาณาจักรตะวันออก" },
        objective = { "135:1512162691:2071922361", "ไปเยือนกองไฟใน Hillsbrad Foothills, Silverpine Forest, Westfall และ Wetlands แล้วคุยกับ Festival Flamekeeper" },
        description = { "467:1797256048:1129018213", "ตามธรรมเนียม Midsummer Fire Festival จะจุดเปลวไฟมากมายให้แผ่นดินสว่างไสว บางคนว่าไฟสีเขียวสวยที่สุด เพราะดูแลยากกว่าไฟแบบอื่นและมีสีโดดเด่น\n\nช่วยตรวจให้ผู้ดูแลเปลวไฟของเราด้วยว่าไฟเหล่านี้ยังลุกอยู่ใน Eastern Kingdoms ไฟอยู่ใกล้ Dun Modr ใน Wetlands ใกล้ Pyrewood Village ใน Silverpine Forest บนหน้าผาที่มองลงไปเห็นประภาคารใน Westfall และข้างหอคอยร้างใน Hillsbrad Foothills" },
        progress = { "27:1247083746:77041275", "ท่านจัดการงานเรียบร้อยแล้วหรือยัง?" },
        completion = { "249:1835035473:1920417061", "ท่านกลับมาแล้ว และตรวจเปลวไฟสีมรกตทั่วทวีปเรียบร้อยแล้ว คิดอย่างไรบ้าง หืม? เป็นภาพหาดูยากและงดงามแน่นอน แต่ข้ารู้ว่ารางวัลที่จับต้องได้คงถูกใจกว่า... โปรดรับสิ่งนี้ตอบแทนความเหนื่อยยากเถิด" },
        steps = { { "18:1469463392:1306778722", "เปลวไฟแห่ง Hillsbrad" }, { "19:622965450:1345489221", "เปลวไฟแห่ง Silverpine" }, { "17:913374217:1261964439", "เปลวไฟแห่ง Westfall" }, { "21:390399517:101629883", "เปลวไฟแห่ง Wetlands" } },
    },
