    [97583] = { -- WRIGGLE.
        title = { "8:1326931771:872498009", "ดุ๊กดิ๊ก" },
        objective = { "148:337676269:523805711", "ซื้อ Nutritious Slime Sludge แล้วกลับไปหาสไลม์จอมตื่นเต้นที่ท่านผูกมิตรด้วย หากมันดูเหนื่อย ลองเต้นกับมันอีกครั้งเพื่อเรียกความสนใจ" },
        description = { "338:540160151:1192450342", "เจ้าสไลม์ตัวน้อยดูดีใจและพยายามขยับตามจังหวะที่ท่านเต้น แต่ดูเหมือนมันจะเริ่มเหนื่อยแล้ว\n\nเจ้าสไลม์ตัวน้อยลอยอยู่เหนือกองเมือกเล็ก ๆ แล้วดูดซึมเข้าไป ดูมีเรี่ยวแรงขึ้นมานิดหน่อย\n\nดูท่าเต้นจนหมดแรงเสียแล้ว บางทีอาจมีใครสักคนในทางน้ำของ Undercity ขายเมือกบำรุงกำลังแบบนี้อีกก็ได้?", variants = { { "340:1996951480:412099067", "<เจ้าสไลม์ตัวน้อยดูดีใจและพยายามขยับตามจังหวะที่ท่านเต้น แต่ดูเหมือนมันจะเริ่มเหนื่อยแล้ว\n\nเจ้าสไลม์ตัวน้อยลอยอยู่เหนือกองเมือกเล็ก ๆ แล้วดูดซึมเข้าไป ดูมีเรี่ยวแรงขึ้นมานิดหน่อย\n\nดูท่าเต้นจนหมดแรงเสียแล้ว บางทีอาจมีใครสักคนในทางน้ำของ Undercity ขายเมือกบำรุงกำลังแบบนี้อีกก็ได้?>" } } },
        completion = { "114:420848820:984625168", "เจ้าสไลม์สั่นดุ๊กดิ๊กด้วยเรี่ยวแรงที่กลับคืนมา ดูเหมือนมันจะอยากตามท่านไปด้วย ตอนนี้มันจำได้แล้วว่าท่านเอาอาหารมาให้", variants = { { "116:466468126:475442643", "<เจ้าสไลม์สั่นดุ๊กดิ๊กด้วยเรี่ยวแรงที่กลับคืนมา ดูเหมือนมันจะอยากตามท่านไปด้วย ตอนนี้มันจำได้แล้วว่าท่านเอาอาหารมาให้>" } } },
        progress = { "46:1361680769:1667880480", "<เจ้าสไลม์ดูจะมองท่านอย่างสนใจ>" },
        required = { [278265] = { "23:1623786997:639518779", "โคลนสไลม์อุดมสารอาหาร" } },
        objectiveLabels = {
            item = { ["Nutritious Slime Sludge"] = "โคลนสไลม์อุดมสารอาหาร" },
        },
    },
    [95646] = { -- Horrors in the Highland
        title = { "23:2081581503:1064371407", "ภัยสยองในที่สูง" },
        objective = { "114:2126757108:1182975553", "สังหาร Highland Horror หนึ่งตัวใน Excavation Sites แล้วนำแกนรากของมันไปให้ Rethiel the Greenwarden ใน Wetlands" },
        description = { "406:510566174:108375109", "พื้นที่ชุ่มน้ำกร่อยแห่งนี้มีแหล่งน้ำจืดขนาดใหญ่จากทางใต้อยู่ด้วย ข้าเจ็บปวดที่สัมผัสได้ผ่านรากว่าความแปดเปื้อนกำลังซึมผ่านร่องเขาแห่งนั้น\n\nสิ่งมีชีวิตที่นั่นได้รับผลจากความแปดเปื้อนรุนแรง เช่นเดียวกับพวกที่อยู่ในที่ลุ่มของเรา พวกมันไม่ได้เติบโตมากับเกลือทะเลที่ช่วยให้แกร่งตั้งแต่แรกเริ่มของชีวิต จึงแทบไม่มีเรี่ยวแรงต้านภัยร้ายเช่นนี้\n\nจงขึ้นไปยังที่สูงแห่งนั้น และนำแกนรากของ Highland Horror มาให้ข้า" },
        progress = { "72:827944768:532082137", "น่านน้ำนี้เป็นบ้านของชีวิตที่ไม่เหมือนที่ใด น้ำกร่อยหล่อเลี้ยงและพรากชีวิตไปพอ ๆ กัน" },
        completion = { "159:1635684003:389075910", "เลวร้ายกว่าที่ข้ากลัวเสียอีก พลังโบราณกำลังตื่นขึ้น ทางที่ดีท่านควรไปบอกพวกนักขุดผู้กระตือรือร้นให้หยุดขุดเพื่อความปลอดภัยของพวกเขาเอง" },
        required = { [270180] = { "17:1466340170:1176656149", "แก่นรากของ Highland Horror" } },
        steps = { { "17:1466340170:1176656149", "แก่นรากของ Highland Horror" } },
    },
    [95647] = { -- Lost in the Thicket Things
        title = { "26:2014564023:923246531", "หลงในดงหญ้า" },
        objective = { "44:2081306767:2083573446", "ตามหา Ardin Grassman ใน Excavation Sites" },
        description = { "476:1876300953:1082013625", "อาร์ดิน สามีของข้า มีพรสวรรค์ด้านการสัมผัสธรรมชาติที่หาได้ยาก เขายอมปีนยอดเขาลูกไหนก็ได้เพื่อเก็บสมุนไพรกับดอกไม้ที่ข้าต้องใช้เล่นแร่แปรธาตุ ทำให้เรามีของเต็มทั้งชั้นวางและตู้เสบียง\n\nแต่ข้ากลัวว่าเขาจะเดินเข้าไปเจอเรื่องเข้าแล้ว มีคณะขุดค้นแวะมาหาเสบียง พวกเขาเล่าหลายเรื่อง รวมถึงเรื่องต้นหญ้าสูงตระหง่านอย่างที่ไม่เคยเห็น อาร์ดินบอกว่าต้องไปดูด้วยตาตัวเองให้ได้ เขาหายไปนานเกินแล้ว!\n\nถ้าท่านได้ข่าวอะไรเกี่ยวกับเขา ข้าจะขอบคุณมาก" },
        completion = { "154:723867681:113011369", "ข้านึกว่าพวกเราไม่รอดแล้ว! มีบางอย่างทำให้สัตว์ป่าแถวนี้แตกตื่นจนคณะขุดค้นของเรารับมือไม่ไหว ขอบคุณที่ช่วยจัดการแมงมุมพวกนั้น" },
        steps = { { "37:1404323046:851500802", "สืบว่าเกิดอะไรขึ้นกับ Ardin Grassman" } },
    },
    [95663] = { -- Dragonmaw Rumors
        title = { "16:1853715304:912100484", "ข่าวลือเรื่องเผ่า Dragonmaw" },
        objective = { "93:807152690:571288673", "เดินทางไป Wetlands และพบ Deathstalker Agent บนเนินเหนือค่าย Dragonmaw" },
        description = { "425:1759500310:828143234", "เผ่า Dragonmaw เป็นคู่ต่อสู้ที่น่ากลัว\n\nพวกมันขึ้นชื่อเรื่องเวทพันธนาการที่แข็งแกร่งพอจะบังคับให้มังกรรับใช้ มีข่าวลือว่าพวกมันกำลังเตรียมแสดงพลังนั้นใน Wetlands จะจริงหรือคุยโว พวก Deathstalkers ก็ดำเนินการจากข่าวลือเลือนรางไม่ได้ สัญลักษณ์ที่แตกหักบอกข้าได้เพียงเท่านี้\n\nสายลับ Deathstalker คนหนึ่งต้องการความช่วยเหลือบนเนินเหนือค่าย Dragonmaw ไปพบเธอที่นั่น เธอจะบอกว่าต้องทำอะไรต่อ", variants = { { "424:1367856916:1463082746", "เผ่า Dragonmaw เป็นคู่ต่อสู้ที่น่ากลัว\n\nพวกมันขึ้นชื่อเรื่องเวทพันธนาการที่แข็งแกร่งพอจะบังคับให้มังกรรับใช้ มีข่าวลือว่าพวกมันกำลังเตรียมแสดงพลังนั้นใน Wetlands จะจริงหรือคุยโว พวก Deathstalkers ก็ดำเนินการจากข่าวลือเลือนรางไม่ได้ กระแสลมอันทรงพลังพัดข่าวมาให้ข้าเพียงเท่านี้\n\nสายลับ Deathstalker คนหนึ่งต้องการความช่วยเหลือบนเนินเหนือค่าย Dragonmaw ไปพบเธอที่นั่น เธอจะบอกว่าต้องทำอะไรต่อ" } } },
        completion = { "47:270779551:166173804", "หนึ่งในคนกล้าไม่กี่คนที่มาถึงแล้วหรือ? เบาเสียงหน่อย", variants = { { "47:1885480583:136384977", "นี่คือเหล่าผู้กล้าที่มากันไม่กี่คนหรือ เบาเสียงหน่อย" } } },
    },
    [95664] = { -- Elder Knowledge
        title = { "15:1869726173:731340319", "ความรู้ของเหล่าผู้อาวุโส" },
        objective = { "108:1713020116:1429823916", "นำ Titan Relic ไปที่ Elder Rise ใน Thunder Bluff แล้วหาคนที่บอกเรื่องของมันเพิ่มเติมได้" },
        description = { "228:583354161:665139106", "เศษวัตถุที่ประกอบจากวัสดุหลายชนิดชิ้นนี้กระจายแสงราวกับปริซึมมีชีวิต ท่านยังไม่รู้แน่ว่ามันคืออะไร แต่พลังที่สัมผัสได้เก่าแก่ยิ่ง ผู้ที่รู้เรื่องวัตถุจากยุคที่ล่วงเลยมานานดีที่สุดคงอยู่ที่ Elder Rise ใน Thunder Bluff" },
        progress = { "50:957824688:1124404087", "เหล่าวิญญาณให้เกียรติท่าน ท่านมาที่นี่เพื่อแบ่งปันอะไรกับเราหรือ?" },
        completion = { "124:185740402:790736224", "การที่คนแปลกหน้ามาหาเราเช่นนี้ถือเป็นลางดี ข้าสัมผัสได้ถึงพลังบางอย่างรอบตัวท่าน... ท่านนำอะไรมา?" },
        required = { [270866] = { "11:1953589631:557206367", "โบราณวัตถุไททัน" } },
        steps = { { "11:1953589631:557206367", "โบราณวัตถุไททัน" } },
    },
    [95682] = { -- Open the Maw
        title = { "12:1454270945:1160759103", "เปิดทางฝ่าพวก Dragonmaw" },
        objective = { "124:660002020:1867225295", "สังหารกองกำลัง Dragonmaw ใน Excavation Site แล้วนำสิ่งที่พบกลับไปให้ Deathstalker Agent ด้านนอก" },
        description = { "447:681600921:487107296", "Dragonmaw <เธอแค่นเสียงอย่างขบขัน>\n\nพวกที่เหลือจากเผ่านักจับมังกรคิดว่าพบอะไรบางอย่างที่จะช่วยให้กลับมามีอำนาจเหมือนเดิม ในสายตาใครกัน... หัวหน้าเผ่าจอมปลอมของพวกมันหรือ?\n\nกวาดล้างพวกกระเซอะกระเซิงใน Excavation Sites เสีย พวก Deathstalkers ของเราจะได้เข้าไปโดยไม่มีใครรู้\n\nถ้า Dragonmaw พกอะไรที่น่าสนใจไว้กับตัว ให้นำมาให้ข้า เรื่องนี้ต้องรู้กันแค่พวกเรากับกองบัญชาการหลวง" },
        progress = { "68:578270712:1659371110", "เรามาที่นี่เพื่อทำงานสำคัญให้เสร็จ ถ้าท่านช่วยได้ก็พิสูจน์ให้เห็นสิ" },
        completion = { "314:965240290:1925643102", "ขอฉกของจากมือท่านเลยนะ\n\nข้าจำลายมือหวัด ๆ ของออร์คพวกนั้นได้ ที่แท้พวกมันหวังเอาใจเรนด์หรือ? เสียแรงเปล่า ไม่มีทางได้อะไร\n\nช่างเถอะ ข่าวนี้มีประโยชน์มากให้ท่านหญิงแห่งความมืดพิจารณา\n\nเอ้านี่ ข้าจะไม่เอาของพวกนี้ติดตัวไปด้วย และอย่าเอาเรื่องภารกิจไปพูดล่ะ เจ้าทหาร" },
        required = { [284844] = { "18:321124290:1419253970", "หนังสือราชการของ Dragonmaw" } },
        steps = { { "18:321124290:1419253970", "หนังสือราชการของ Dragonmaw" } },
        objectiveLabels = {
            monster = { ["Dragonmaw Saboteur slain"] = "ปราบ นักก่อวินาศกรรม Dragonmaw", ["Dragonmaw Warder slain"] = "ปราบ ผู้พิทักษ์ Dragonmaw" },
        },
    },
    [95697] = { -- Changing Tastes
        title = { "15:1571497087:1698366092", "เปลี่ยนรสชาติ" },
        objective = { "78:1762555539:907956398", "เข้าไปใน Excavation Sites ที่ Wetlands แล้วนำ Thicket Raptor Meat กลับมา" },
        description = { "460:810912505:67952134", "แซมจาบอกว่าเราควรมีอาหารรสมือบ้าน ๆ ให้มากขึ้น ถ้าเริ่มขายเนื้อแรปเตอร์ เธอคิดว่าจะดึงลูกค้าที่ไม่ค่อยแวะ Borstan's Firepit มาได้\n\nความคิดเธอก็เข้าท่า แต่ข้าอยากได้อะไรที่ไปไกลกว่ากลิ่นอาหารหมู่บ้านเกิด เราอยู่ใน Orgrimmar เชียวนะ! บอร์สตันควรเสิร์ฟอาหารโปรดที่คนคุ้นเคยในแบบที่เลิศขึ้นไปอีก\n\nไม่นานมานี้มีนักล่ากลับจาก Wetlands พร้อมกรงเล็บขนาดยักษ์ของ Thicket Raptor จาก Excavation Sites\n\nสนใจรับงานไหม?" },
        progress = { "73:1611586544:1699586907", "หมูป่าเลี้ยงในฟาร์ม ปูเลี้ยงในฟาร์ม... ต่อไปจะเป็นแรปเตอร์เลี้ยงในฟาร์มหรือไง?" },
        completion = { "191:2135274675:1335586362", "ดูไขมันที่แทรกเป็นลายหินอ่อนในเนื้อนี่สิ! พวกมันกินอะไรกันบนนั้นนะ? ขอบคุณที่อุตส่าห์เดินทางไปกลับเพื่อพวกเรา ถ้าไม่รังเกียจที่จะรอสักหน่อย เราจะปรุงให้ท่านชิมเดี๋ยวนี้ เลี้ยงเองอยู่แล้ว!" },
        required = { [271100] = { "19:1832168136:378046125", "เนื้อแรปเตอร์จากพงไม้" } },
        steps = { { "19:1832168136:378046125", "เนื้อแรปเตอร์จากพงไม้" } },
    },
    [95737] = { -- Seeking Caitlin
        title = { "15:1970269758:1373394970", "ไปหาเคตลิน" },
        objective = { "47:1679613053:396443071", "คุยกับ Caitlin Grassman ที่ Menethil Harbor" },
        description = { "440:1589258808:526322225", "บางครั้งข้าก็เขียนจดหมายถึงคนที่ทำงานสายเดียวกัน ทั้งนักสมุนไพรและคนแปลก ๆ ที่ศึกษาพืชหายากหรือของประหลาดในท้องถิ่น เราแลกเปลี่ยนสิ่งที่ค้นพบและบางครั้งก็เตือนกันถึงสิ่งที่อาจเกิดขึ้น\n\nนักเล่นแร่แปรธาตุคนหนึ่งใน Wetlands เขียนมาว่าคณะขุดค้นที่สามีเธอร่วมทางไปด้วยพบร่องรอยของหญ้าดึกดำบรรพ์ที่หายสาบสูญไปนาน... แต่เธอไม่ได้ส่งข่าวมาอีกว่ามันมีมากเพียงใดหรือเข้าถึงได้ไหม\n\nถ้าท่านพอช่วยได้ ไปถามข่าว Caitlin Grassman ที่ Menethil Harbor ให้หน่อย" },
        completion = { "229:594334227:221123258", "ลานาคงสงสัยว่าเมล็ดหญ้าที่ข้ารับปากว่าจะให้สามีนำกลับมาอยู่ที่ไหน! ข้าคลายใจที่รู้ว่าเธอเป็นห่วงเหมือนกัน เราทั้งคู่คงสัมผัสได้ว่ามีอะไรบางอย่างผิดปกติที่แหล่งขุดค้นนั่นเอง" },
    },
    [95772] = { -- Songblade Search
        title = { "16:187637924:1670444744", "ตามหาคนตระกูลซองเบลด" },
        objective = { "73:1949667407:861832095", "ตามหา Daewyn พี่น้องของ Dorin Songblade ใน Whelgar's Excavation Site" },
        description = { "442:562826221:549997708", "พี่น้องข้าพยายามลากข้าไป Wetlands กับคณะขุดค้นจาก Loch Modan บอกว่าจะไปขุดอะไรสักอย่างในเนินเขาที่คนแคระไม่เคยเหยียบ\n\nเออ ข้าคงไปด้วยถ้าไม่ติดเข็มขัดกองนี้ที่ยังแก้ขนาดไม่เสร็จ\n\nปกติเดวินจะเขียนมาหลังออกเดินทาง แต่คราวนี้ข้าไม่ได้ข่าวเลย รู้สึกแปลก ๆ ยังไงชอบกล\n\nถ้าท่านจะเดินไปทางนั้น ช่วยแวะดูให้ทีว่าพี่น้องข้าเป็นอย่างไรบ้าง" },
        completion = { "125:47407632:1300160390", "คนแคระผู้นี้หน้าตาคล้ายดอริน ซองเบลดอย่างเห็นได้ชัด ปืนในมือเขามีอักษร ‘DLS’ สลักไว้บนพานท้าย" },
    },
    [95795] = { -- Fallen in the Fen
        title = { "17:1101902198:1465180800", "ผู้ล้มลงในบึง" },
        objective = { "26:99112411:1111796586", "กลับไปหา Dorin Songblade" },
        description = { "158:1495990791:406529373", "<ท่านใช้ผ้าคลุมของคนแคระคลุมร่างของเขา>\n\nเดินทางไป Lakeshire แล้วบอก Dorin Songblade ด้วยตัวเองว่าเกิดอะไรขึ้นกับพี่น้องของเขาใน Excavation Sites" },
        completion = { "374:960428646:1533264474", "โอ้ ไม่...\n<เขาซบหน้าลงกับมือแล้วสะอื้น>\n\nข้าน่าจะไปกับพวกเขาด้วย\n\nของที่ข้าตีอยู่ส่วนใหญ่ทำให้เขา ตั้งใจจะให้เป็นของขวัญ แต่ยังทำไม่เสร็จตอนที่เขาแวะมาเอาของไปเดินทาง\n\nตอนนี้ทำเสร็จแล้ว ข้าก็ทำใจเอาไปตีใหม่หรือขายไม่ได้สักชิ้น\nเจ้าเอาชิ้นนี้ไปเถอะ อย่างน้อยข้าก็ทำได้เท่านี้ที่เจ้ามาบอกข่าวร้ายในวันนี้" },
    },
    [95809] = { -- Heartwoven
        title = { "10:17487640:816018438", "หัวใจสาน" },
        objective = { "46:1973310921:1603628767", "กลับไปหา Caitlin Grassman ที่ Menethil Harbor" },
        description = { "318:1387726382:794996098", "ข้าขอพักสักครู่ก่อนจะหาทางออกไปเอง\n\n<เขาหยิบต้นกกจากกระเป๋า แล้วรีบถักและดัดเป็นรูปหัวใจ>\n\nเอานี่กลับไปให้เคตลินที บอกเธอว่าข้าจะกลับบ้านเร็ว ๆ นี้! ตอนนี้ท่านช่วยเปิดทางไว้ให้แล้ว ข้าจะเก็บพืชที่รวบรวมไว้แล้วเดินตามทางที่ท่านมา\n\nขอบคุณนะ" },
        progress = { "32:903739554:402265324", "ข้าเป็นห่วงเขาจนแทบอยู่ไม่สุขแล้ว!" },
        completion = { "267:649664238:2001672622", "ตายจริง ฟังดูเลวร้ายมาก!\n\nขอบคุณพระแสง ข้าดีใจที่เขาเป็นหนึ่งในผู้รอดชีวิต\n\n<นางแนบหัวใจที่สานจากต้นกกไว้กับอก>\n\nข้าจะเริ่มทำอาหารให้อิ่มหนำไว้ให้เขา ขอบใจที่เอาของชิ้นนี้มาให้ ข้าอยากให้เจ้ารับบางอย่างไว้แทนคำขอบคุณจากเรา" },
        required = { [270901] = { "16:1380565540:784575483", "หัวใจสานจากต้นกก" } },
        steps = { { "16:1380565540:784575483", "หัวใจสานจากต้นกก" } },
    },
    [95810] = { -- Lost Relic Carry
        title = { "16:1420950534:2104848466", "นำวัตถุโบราณที่สาบสูญกลับมา" },
        objective = { "76:789897904:1824336959", "นำ Titan Relic ไปให้ Prospector Whelgar ที่แหล่งขุดค้นใน Wetlands" },
        description = { "316:1175430455:1396886104", "ท่านเก็บชิ้นส่วนที่แตกร้าวของหุ่นกลหินขึ้นมา พื้นผิวของมันไม่เหมือนอะไรที่ท่านเคยสัมผัส เป็นวัสดุผสมที่ไม่รู้ว่าทำจากอะไร ดูท่ามันจะเป็นชิ้นส่วนอุปกรณ์มากกว่าเศษซากธรรมดา\n\nตัว Prospector Whelgar ที่แหล่งขุดค้นของเขาอาจบอกอะไรที่เป็นประโยชน์เกี่ยวกับวัตถุโบราณนี้ได้" },
        progress = { "17:433024544:543556481", "มาช่วยขุดหรือ?" },
        completion = { "222:2116815371:600597667", "อ้าว ท่านบุกเข้าไปถึงข้างในแล้วยังรอดกลับมาเล่าได้หรือ?! ไหนขอดูของที่ท่านเอามาหน่อย\n\nพอรู้ว่าท่านต้องเจออะไรมาบ้างกว่าจะเอามาให้ข้าได้ ข้าว่าวัตถุชิ้นนี้ควรได้รับการปฏิบัติด้วยความเคารพอยู่บ้าง" },
        required = { [270865] = { "11:1953589631:557206367", "โบราณวัตถุไททัน" } },
        steps = { { "11:1953589631:557206367", "โบราณวัตถุไททัน" } },
    },
    [98815] = { -- Highland Hides
        title = { "14:2147050241:968775063", "หนังสัตว์จากที่สูง" },
        objective = { "80:762041285:1726274338", "นำ Thicket Raptor Hide 4 ผืนไปให้ James Halloran ช่างฟอกหนังใน Menethil Harbor", amount = { "7:754587951:547508582 W1 72:572017895:1795970739", "นำ Thicket Raptor Hide {world1} ผืนไปให้ James Halloran ช่างฟอกหนังใน Menethil Harbor" } },
        description = { "446:1001943293:1468126764", "บนที่สูงมีซากโบราณสถานอะไรสักอย่าง คณะสำรวจกำลังขุดค้นความลับของมันอยู่ ข้ารู้แค่ว่าแถบบึงบนเขานั้นมีสัตว์ป่าของมันเองซุ่มอยู่ ลองพาเพื่อนที่มีอุปกรณ์พร้อมบุกเข้าไปดู แล้วเรามาแลกของกันเป็นไง?\n\nพวกมันจะหลบซ่อนอยู่ไหนข้าไม่สน ข้าสนแต่หนังของมัน! เอาหนัง Thicket Raptor สี่ตัวมาให้ข้า แล้วข้าจะจัดของแลกให้คุ้มแรง" },
        progress = { { "66:1815380033:1854652366", "14:1649650394:897424258 N 42:1454993327:2079567529", "14:1649650394:897424258 C 42:1454993327:2079567529", "14:1649650394:897424258 R 42:1454993327:2079567529" }, "ยินดีต้อนรับกลับมา นักผจญภัย ต้องการน้ำมันดูแลเครื่องหนังสำหรับอุปกรณ์ของท่านไหม?" },
        completion = { { "187:356291549:855920937", "133:72188061:919386876 N 48:641709133:154775019", "133:72188061:919386876 C 48:641709133:154775019", "133:72188061:919386876 R 48:641709133:154775019" }, "นี่เป็นหนังสัตว์ที่งามที่สุดเท่าที่ข้าเคยจับมาเลย จะเอาไปตัดแต่งขอบงานชั้นดีของข้าได้งดงามแน่ ขอบคุณนะ สหาย\n\nลองสวมของพวกนี้ดู แล้วเลือกชิ้นที่ถูกใจไปแลกได้เลย" },
        required = { [284845] = { "19:1747560123:366874692", "หนังแรปเตอร์พุ่มไม้" } },
        objectiveLabels = {
            item = { ["Thicket Raptor Hide"] = "หนังแรปเตอร์พุ่มไม้" },
        },
    },
    [98823] = { -- Earthen Echo
        title = { "12:1381783984:778317641", "เสียงสะท้อนแห่งผืนดิน" },
        objective = { "87:1767758859:736279581", "นำ Titan Relic ไปให้ Muln Earthfury ที่ Skywatcher Plateau ทางตะวันตกเฉียงเหนือของ Mulgore" },
        description = { "467:1169707695:974760929", "ของชิ้นนี้น่าทึ่งจริง ๆ\n\nมันมีร่องรอยบ่งบอกว่าเป็นอะไรที่มากกว่างานแกะสลักหรือประติมากรรมธรรมดา\n\nแม้เหล่าผู้อาวุโสของเราอาจสนใจตรวจดูวัตถุชิ้นนี้ แต่คนที่รู้เรื่องซากที่ถูกฝังและดินแดนที่ถูกลืมมากที่สุดคือ Earthen Ring ไปหา Muln Earthfury เถิด เรื่องสำคัญอย่างนี้ควรไปพบเขาโดยตรง\n\nท่านจะพบเขากับผู้อาวุโสคนอื่น ๆ ของสภา Earthen Ring ที่ Skywatcher Plateau ทางตะวันตกเฉียงเหนือของ Mulgore" },
        progress = { "23:1591873072:959858329", "เข้ามาเถิด จงแสวงหาแล้วรับสิ่งที่พบ" },
        completion = { "407:862541921:25690791", "อา... เศษชิ้นนี้ก้องด้วยเสียงของโลกเอง แสงข้างในคือความทรงจำจากอดีต มีภาพประวัติศาสตร์วาบขึ้นเป็นระยะ เครื่องจักรไททันนี้คงรอให้ใครสักคนมาเข้าใจมันมาหลายชั่วอายุคนแล้ว\n\nท่านทำถูกแล้วที่นำมันมาให้เรา Earthen Ring จะเก็บรักษา ศึกษา และแบ่งปันความจริงที่มันซ่อนไว้เมื่อเราพร้อมรับฟังสิ่งที่มันบอก\n\nวันนี้ท่านได้ให้เกียรติเหล่าธาตุ นักเดินทาง" },
        required = { [287958] = { "11:1953589631:557206367", "โบราณวัตถุไททัน" } },
        steps = { { "11:1953589631:557206367", "โบราณวัตถุไททัน" } },
    },
    [98824] = { -- Prehistoric Prism
        title = { "17:839325992:202075594", "ปริซึมจากยุคดึกดำบรรพ์" },
        objective = { "81:1206066301:538186210", "นำ Titan Relic ไปให้ High Explorer Magellas ที่ Hall of Explorers ใน Ironforge" },
        description = { "229:818941270:348139363 N 260:1261984438:1648168980", "มีอักขระคล้ายของไททันอยู่ตามเหลี่ยมอย่างนี้ จะเอาไปที่ไหนเหมาะไปกว่า Hall of Explorers ใน Ironforge เล่า\n\nข้าชักอยากเห็นชื่อท่านถูกจารึกไว้ในบัญชีพิพิธภัณฑ์ให้คนรุ่นหลังได้อ่าน ‘ค้นพบโดย {name}! รับรองโดย Prospector Whelgar...’ อา ข้าชักเพลินไปหน่อยแล้ว\n\nHigh Explorer Magellas จะต้อนรับท่าน และด้วยความงดงามของสิ่งที่ท่านถือไป หากบริจาคให้พิพิธภัณฑ์ เขาต้องตอบแทนอย่างใจกว้างแน่นอน\n\nพบของดีเข้าแล้วล่ะ!" },
        progress = { "120:1779393491:214717998", "เชิญชมแกลเลอรีของเราได้ แต่โปรดอย่าแตะวัตถุโบราณ เว้นแต่เป็นชิ้นที่ท่านนำมาบริจาคให้หอสมุด" },
        completion = { "418:523623276:1406604875", "ท่านถืออะไรมานั่น...\n\nโห! ดูของมหัศจรรย์นี่สิ! แสงที่ลอดผ่านมันระยิบระยับอย่างที่ข้าไม่เคยเห็นอีกเลยนับแต่ไปขุดที่ Uldaman เก่าครั้งแรก รอยของเหล่าผู้พิทักษ์บนนี้ดูยังไงก็ไม่ผิดแน่\n\nท่านช่วยสมาคมนักสำรวจไว้มากที่นำของนี้กลับมา การค้นพบแบบนี้ทำให้ความรู้ของเราที่มีต่อโลกก้าวไกลขึ้นอีกขั้น\n\nเราจะบันทึกรายละเอียดสิ่งที่ท่านนำมามอบให้ไว้อย่างแน่นอน ทำได้ยอดเยี่ยมจริง ๆ นักผจญภัย" },
        required = { [287959] = { "11:1953589631:557206367", "โบราณวัตถุไททัน" } },
        objectiveLabels = {
            item = { ["Titan Relic"] = "โบราณวัตถุไททัน" },
        },
    },
    [98887] = { -- Conflict at Darkspear Islands
        title = { "29:1287698681:114040245", "ศึกปะทะที่หมู่เกาะดาร์กสเปียร์" },
        objective = { "89:1530182295:1719901698", "นำ Darkspear Islands Marks of Honor 3 ชิ้นไปให้ Horde Warbringer นอกสนามรบ" },
        description = { "267:266015407:1779124891", "กองกำลังสำรวจเธรามอร์สู้ไม่ถอย ยังส่งกำลังเสริมมายึดที่มั่นในหมู่เกาะดาร์กสเปียร์ให้แน่นหนาขึ้นเรื่อย ๆ\n\nไปเถิด แสดงให้พวกมันเห็นพลังของ Horde! นำหลักฐานชัยชนะในสนามรบสำคัญแห่งนี้กลับมาให้ข้า แล้วท่านจะได้รางวัลอย่างงาม" },
        completion = { "102:1764489567:494780260 N 16:2062511857:1389353873", "ผืนทรายของ Darkspear Islands ชุ่มไปด้วยเลือดของพวก Alliance ที่เจ้าสังหาร ทำได้ดี {name}\n\nเพื่อ Horde!" },
        progress = { "38:368978655:1623862441 N 1:63:63", "มีข่าวอะไรจาก Darkspear Islands บ้าง {name}?" },
        required = { [274895] = { "31:832704024:1368023717", "เหรียญเกียรติยศ Darkspear Islands" } },
