    [98895] = { -- Darkspear Islands Clash
        title = { "23:1858373989:1998541756", "การปะทะที่หมู่เกาะดาร์กสเปียร์" },
        objective = { "100:1160862624:1949772701", "นำ Darkspear Islands Marks of Honor 3 ชิ้นไปให้ Alliance Brigadier General นอกสนามรบ" },
        description = { "306:49046194:924241633", "การต่อสู้กับ Darkspear Raiders กำลังดุเดือดขึ้น ถ้าไม่ได้กำลังเสริมโดยเร็ว เราจะเสียหมู่เกาะดาร์กสเปียร์\n\nในฐานะสมาชิกผู้ภาคภูมิแห่ง Alliance ท่านมีหน้าที่ป้องกันไม่ให้เรื่องนั้นเกิดขึ้น นำหลักฐานว่าท่านช่วยรบในแนวหน้ามาให้ข้า แล้วท่านจะได้รับการยกย่องเป็นวีรชนของ Alliance!" },
        progress = { { "56:297768609:1243766816", "49:723586793:1392669733 N 1:63:63", "49:723586793:1392669733 C 1:63:63", "49:723586793:1392669733 R 1:63:63" }, "การรบของท่านที่หมู่เกาะดาร์กสเปียร์เป็นอย่างไรบ้าง สหาย?" },
        completion = { "238:69176630:395561951", "ท่านสร้างผลงานอย่างมีเกียรติในศึกที่หมู่เกาะดาร์กสเปียร์ ความพยายามของท่านเป็นที่ประจักษ์แล้ว\n\nยังมีอีกหลายศึกให้สู้ จงพิสูจน์ตัวเองในสนามรบต่อไป แล้วท่านจะได้รับรางวัลอย่างแน่นอน" },
        required = { [274895] = { "31:832704024:1368023717", "เหรียญเกียรติยศ Darkspear Islands" } },
        steps = { { "31:832704024:1368023717", "เหรียญเกียรติยศ Darkspear Islands" } },
    },
    [98896] = { -- Darkspear Islands Clash
        title = { "23:1858373989:1998541756", "การปะทะที่หมู่เกาะดาร์กสเปียร์" },
        progress = { "46:330561356:780518666 N 52:1002057759:1095990623", "การสู้รบใน Darkspear Islands ยังดำเนินต่อไป {name} รวมกำลังของเจ้าแล้วบดขยี้พวก Darkspear Raiders!" },
        description = { "46:330561356:780518666 N 52:1002057759:1095990623", "การสู้รบใน Darkspear Islands ยังดำเนินต่อไป {name} รวมกำลังของเจ้าแล้วบดขยี้พวก Darkspear Raiders!" },
        completion = { "16:1549935302:71513149 C 114:379608787:1214679720", "ยอดเยี่ยม {class}! ทุกครั้งที่เราโจมตี Darkspear Raider เราก็เข้าใกล้ชัยชนะเบ็ดเสร็จอีกก้าว\n\nเพื่อฝ่ายสัมพันธมิตร!" },
    },
    [98897] = { -- Darkspear Islands Clash
        title = { "23:1858373989:1998541756", "การปะทะที่หมู่เกาะดาร์กสเปียร์" },
        objective = { "100:1160862624:1949772701", "นำ Darkspear Islands Marks of Honor 3 ชิ้นไปให้ Alliance Brigadier General นอกสนามรบ" },
        description = { "306:49046194:924241633", "การต่อสู้กับ Darkspear Raiders กำลังดุเดือดขึ้น ถ้าไม่ได้กำลังเสริมโดยเร็ว เราจะเสียหมู่เกาะดาร์กสเปียร์\n\nในฐานะสมาชิกผู้ภาคภูมิแห่ง Alliance ท่านมีหน้าที่ป้องกันไม่ให้เรื่องนั้นเกิดขึ้น นำหลักฐานว่าท่านช่วยรบในแนวหน้ามาให้ข้า แล้วท่านจะได้รับการยกย่องเป็นวีรชนของ Alliance!" },
        required = { [274895] = { "31:832704024:1368023717", "เหรียญเกียรติยศ Darkspear Islands" } },
        steps = { { "31:832704024:1368023717", "เหรียญเกียรติยศ Darkspear Islands" } },
    },
