    [98903] = { -- The Battle for Darkspear Islands!
        title = { "33:1981489365:1201626569", "ศึกชิงหมู่เกาะดาร์กสเปียร์!" },
        objective = { "92:72873845:937742764", "ชนะการรบในสนามรบ Darkspear Islands หนึ่งครั้ง แล้วกลับไปหา Brelinda McFarry ที่ Northwatch Hold" },
