    [98906] = { -- The Battle for Darkspear Islands!
        title = { "33:1981489365:1201626569", "ศึกชิงหมู่เกาะดาร์กสเปียร์!" },
        objective = { "90:1235939061:444115374", "ชนะการรบในสนามรบ Darkspear Islands หนึ่งครั้ง แล้วกลับไปหา Nizook Boof ที่ The Merchant Coast" },
        description = { "62:718465142:612451094 C 183:1434777727:2112393908 C 1:33:33", "ศึกที่หมู่เกาะดาร์กสเปียร์ยังชะงักอยู่ ไม่มีฝ่ายไหนได้เปรียบ ท่าน{class} แสดงให้เจ้าพวก Alliance หน้าโง่เห็นว่าฝ่ายไหนเหนือกว่า\n\nจงเชิดหน้าอย่างภูมิใจที่ได้สู้เพื่อดาร์กสเปียร์ แล้วคว้าชัยในสนามรบ เหล่าโลอาจะประทานพรแก่ท่านแน่ ท่าน{class}!" },
        completion = { "115:918866339:1007094175", "เจ้าพิสูจน์ให้เห็นทั้งความแข็งแกร่งและความทุ่มเทที่ Darkspear Islands! ฝีมือรบของเจ้าน่าชื่นชมจริง ๆ เพื่อนเอ๋ย!" },
        steps = { { "24:90335663:1304546876", "ชนะการต่อสู้ใน Darkspear Islands" } },
