    [8] = { -- A Rogue's Deal
        title = { "14:1292733977:824354199", "ข้อตกลงของจอมเจ้าเล่ห์" },
        objective = { "69:488830320:1020016366", "นำ Nondescript Letter ไปให้ Innkeeper Renee ใน Tirisfal Glades" },
        description = { "490:879108845:977584768", "เฮ้ สหาย! ช่วยหนุ่มที่เพิ่งผ่านศึกกับซอมบี้ไร้สมองและแมงมุมมาหนักเกินพอหน่อยได้ไหม?\n\nข้ามีจดหมายที่ต้องส่งไป Brill ให้เจ้าของโรงเตี๊ยมชื่อเรอเนอะไรสักอย่าง นามสกุลนางไม่สำคัญหรอก\n\nที่นั่นเป็นเมืองเล็ก ๆ อบอุ่นดี มีพวกที่เคราะห์ร้ายจากโรคระบาดพยายามตั้งหลักกันอยู่เต็มไปหมด ถ้าท่านต้องการพัก ที่นั่นก็เหมาะเลย ลองไปดูสิ... ถ้าไป ข้าจ่ายให้งามแน่" },
        progress = { "173:1635465423:824288257", "ว่าไง? มีอะไรหรือ?\n\nพวก Forsaken นี่กินจุจริง ๆ ทำตัวตามสบายนะ... พักกระดูกที่ล้าเสียหน่อย ข้าชื่อเรอเน ถ้าต้องการอะไรก็บอก" },
        completion = { "450:1306708580:214070352", "โอ้ จดหมายหรือ? ข่าวดีจริง! ข้ารอข่าวจากแม่ที่ Deathknell อยู่พอดี นางใจบุญเหลือเกิน ไม่รู้ว่าตอนนี้เป็นอย่างไรบ้าง\n\nอะไรนะ? ข้าร่าเริงเกินไปหรือ? ไม่เชื่อสินะ?\n\nงั้นก็ไสหัวไป... จดหมายมาจากใครไม่ใช่เรื่องของท่าน ไปสิ! ไสหัวไป!\n\nมีเงินจะใช้เมื่อไรค่อยกลับมา... เจ้าคนขี้เกียจ\n\nเผลอ ๆ เดี๋ยวท่านก็กลับมาขอพักหลังผจญภัยเหนื่อยมาทั้งวัน หรือเรื่องงี่เง่าทำนองนั้น" },
        required = { [7628] = { "18:42562058:1932799750", "จดหมายหน้าตาธรรมดา" } },
        steps = { { "18:42562058:1932799750", "จดหมายหน้าตาธรรมดา" } },
    },
    [363] = { -- Rude Awakening
        title = { "14:1038488931:1070459933", "ตื่นขึ้นมาอย่างไม่ทันตั้งตัว" },
        objective = { "32:466516377:2071492290", "คุยกับ Shadow Priest Sarvis" },
        description = { "324:994161247:1557225408", "ตื่นเสียที พวกข้ากำลังจะโยนท่านเข้ากองไฟกับคนอื่น ๆ อยู่แล้ว แต่ดูเหมือนท่านจะรอดมาได้\n\nข้าชื่อมอร์โด ผู้ดูแลสุสานใต้ดินแห่ง Deathknell บัดนี้ท่านพ้นจากการเป็นทาสของ Lich King แล้ว\n\nไปคุยกับ Shadow Priest Sarvis ที่โบสถ์เชิงเขา เขาจะบอกเรื่องที่ท่านต้องรู้เพิ่มเติม" },
        completion = { "415:358411844:765646748", "ศพเดินได้อีกคนหรือ? คงตกใจไม่น้อยที่ตื่นในสุสานใต้ดินแล้วมีแค่ความหนาวกับมอร์โดรอต้อนรับ...\n\nข้าเห็นว่าท่านยังสับสน ให้ข้าอธิบาย... สถานการณ์ของพวกเรา... ให้ฟังเถิด\n\nผู้นำคนใหม่ของเรา เลดีซิลวานัส ปลดเราออกจากการควบคุมของ Lich King แล้ว ท่านหญิงแห่งความมืดนำเราทำสงครามกับ Scourge ที่เราชิงชังและพวกมนุษย์ที่ยังยืนกรานไล่ล่าเราทุกฝีก้าว" },
    },
    [364] = { -- The Mindless Ones
        title = { "17:1965642244:1626861409", "พวกไร้จิต" },
        objective = { "81:1543589044:1058402597", "Shadow Priest Sarvis ต้องการให้ท่านสังหาร Mindless Zombie 8 ตัว และ Wretched Zombie 8 ตัว" },
        description = { "398:1723573700:1677969425", "พวกเรา Forsaken ทำสงครามกับกองทัพ Scourge ของ Lich King ทั้งอันเดดที่ถูกปลุกด้วยมนตร์ชุบศพ สัตว์โสโครกจากแดนเหนือ และวิญญาณที่ถูกทรมาน\n\nตอนเหนือของหมู่บ้านถูกพวกไร้จิตยึดไปทั่วแล้ว ต้องกำจัดพวกมัน ลงมือเสีย อย่าปรานีแม้พวกมันเคยเป็นพี่น้องของเรา ผู้ที่ล้มตายไปแล้วเหล่านี้เป็นเพียงทาสของ Lich King", variants = { { "102:337103648:1957533461 R 290:731786666:656432177", "พวกเรา Forsaken ทำสงครามกับกองทัพ Scourge ของ Lich King ทั้งกองทัพ{race}ที่ถูกปลุกด้วยมนตร์ชุบศพ สัตว์โสโครกจากแดนเหนือ และวิญญาณที่ถูกทรมาน\n\nตอนเหนือของหมู่บ้านถูกพวกไร้จิตยึดไปทั่วแล้ว ต้องกำจัดพวกมัน ลงมือเสีย อย่าปรานีแม้พวกมันเคยเป็นพี่น้องของเรา ผู้ที่ล้มตายไปแล้วเหล่านี้เป็นเพียงทาสของ Lich King" } } },
        progress = { "92:332109148:76690577 N 49:116890043:1610550808", "ชีวิตใหม่นี้ท่านคงไปได้ไม่ไกลหากฆ่าแม้แต่ซอมบี้ที่อ่อนแอที่สุดยังไม่ได้ {name} ทำสำเร็จแล้วค่อยกลับมารายงาน" },
        completion = { "194:1317689161:203956688", "น่าเสียดายที่ชักชวน Scourge มาเข้าพวกไม่ได้ กำลังพลมากมายของพวกมันคงมีประโยชน์ในศึกข้างหน้า\n\nแต่พวกมันไม่เข้ากับเรา เราจึงต้องทำลายพวกมันเสีย" },
        objectiveLabels = {
            monster = { ["Mindless Zombie slain"] = "ปราบ ซอมบี้ไร้สติ", ["Wretched Zombie slain"] = "ปราบ ซอมบี้สภาพทรุดโทรม" },
        },
    },
    [376] = { -- The Damned
        title = { "10:507900191:554602469", "ผู้ถูกสาป" },
        objective = { "60:1263861109:1985455622", "Novice Elreth ต้องการ Scavenger Paw 6 ชิ้น และ Duskbat Wing 6 ชิ้น" },
        description = { "496:1285004825:1665149976", "หน้าที่ของข้าคือดูแลนักรบที่บาดเจ็บ ตัดเย็บเกราะกับเสื้อผ้า และช่วย Shadow Priest Sarvis ในเรื่องอื่น ๆ ที่เขาต้องการ\n\nดูท่าท่านคงถูกเรียกไปรับใช้เขาเหมือนกัน... ถ้าเดาใจเขาถูกก็คงให้ไปล่าพวกไร้จิต หากท่านอยากกลับมาโดยครบสามสิบสอง ข้าอาจช่วยได้ อุ้งเท้ากับปีกของข้าใกล้หมดแล้ว ถ้าท่านเอามาให้ ข้าจะหาเกราะให้สักชุด ทางใต้มีหมาป่ากับค้างคาวอยู่ไม่น้อย" },
        progress = { "70:722208748:1659976428", "ระหว่างรอข้าหาเกราะให้ พยายามอย่าให้ตัวเองบาดเจ็บล่ะ" },
        completion = { "11:1191658970:1224418299 N 103:241839756:98901189", "ขอบคุณ {name} เกราะชุดนี้น่าจะช่วยท่านได้\n\nหวังว่ามันจะช่วยท่านได้มากกว่าคนที่ใส่มันคนก่อนนะ..." },
        required = { [3265] = { "13:827961114:1046590569", "อุ้งเท้าสัตว์กินซาก" }, [3264] = { "12:123607010:1896224629", "ปีกค้างคาวรัตติกาล" } },
        steps = { { "13:827961114:1046590569", "อุ้งเท้าสัตว์กินซาก" }, { "12:123607010:1896224629", "ปีกค้างคาวรัตติกาล" } },
    },
    [380] = { -- Night Web's Hollow
        title = { "18:567905414:1199857418", "โพรงแห่งใยราตรี" },
        objective = { "84:783844365:1340542092", "Executor Arren ต้องการให้ท่านสังหาร Young Night Web Spider 10 ตัว และ Night Web Spider 8 ตัว" },
        description = { "462:819384396:519870124 N 1:46:46", "ปัญหาใหญ่ข้อหนึ่งของเราคือการหาทรัพยากรธรรมชาติที่จำเป็นต่อการอยู่รอด แม้แต่สมัย Alliance เรืองอำนาจสูงสุด ทองก็ยังหายาก\n\nมีเหมืองทองอยู่ทางตะวันตกเฉียงเหนือ แต่ตอนนี้มีแมงมุมเต็มไปหมด เราต้องการทองจากเหมือง แต่ลงไปเอาไม่ได้ตราบใดที่พวกมันยังยั้วเยี้ยอยู่ข้างใน ข้ามีคนให้ใช้ไม่มาก คงต้องค่อย ๆ จัดการทีละน้อย\n\nขึ้นไปดูทีว่าท่านพอทำอะไรให้เราได้บ้าง {name}" },
        progress = { "31:1211993102:1833812544 N 65:1331795104:2146312141", "ระวังพิษแมงมุม {name} ถ้ารู้สึกแสบร้อนจี๊ด ๆ ก็ควรให้ใครตรวจดู" },
        completion = { "207:1361230930:1106380400 N 51:1327229885:2100244519", "อืม อย่างน้อยก็เริ่มได้แล้ว คงต้องใช้เวลาหลายสัปดาห์หรือหลายเดือนกว่าจะกำจัดพวกมันหมด หลังจากนั้นเราต้องลงไปเอาคบไฟเผาใยแมงมุม\n\nท่านทำหน้าที่ได้ดี {name} ข้ามั่นใจว่ามีงานอื่นให้ท่านทำอีก" },
        objectiveLabels = {
            monster = { ["Young Night Web Spider slain"] = "ปราบ แมงมุม Night Web วัยอ่อน", ["Night Web Spider slain"] = "ปราบ แมงมุม Night Web" },
        },
    },
    [381] = { -- The Scarlet Crusade
        title = { "19:1195719321:434240248", "กองครูเสดสีชาด" },
        objective = { "85:797588086:1745544202", "นำ Scarlet Armband 12 ชิ้นจาก Scarlet Convert และ Scarlet Initiate ไปให้ Executor Arren" },
        description = { "492:1345224631:1857141727", "ท่านคงยินดีที่รู้ว่างานในเหมืองเริ่มคืบหน้า ความช่วยเหลือของท่านมีส่วนมาก ตอนนี้เราหันไปสนใจเรื่องอื่นได้แล้ว\n\nหน่วยสอดแนมรายงานว่ากองกำลังส่วนหนึ่งของ Scarlet Crusade กำลังตั้งค่ายทางตะวันออกเฉียงใต้ พวกมันเป็นองค์กรต่ำช้าที่ตามล่าเราและจะไม่หยุดจนกว่าอันเดดทุกตนจะถูกทำลาย ไม่ว่าจะเป็น Scourge ของ Lich King หรือไม่ เราต้องชิงลงมือก่อน!\n\nระวังตัวด้วย ความคลั่งศรัทธาของพวกมันทำให้มันเป็นศัตรูที่อันตราย", variants = { { "358:1039498030:645250044 R 128:196248786:122205845", "ท่านคงยินดีที่รู้ว่างานในเหมืองเริ่มคืบหน้า ความช่วยเหลือของท่านมีส่วนมาก ตอนนี้เราหันไปสนใจเรื่องอื่นได้แล้ว\n\nหน่วยสอดแนมรายงานว่ากองกำลังส่วนหนึ่งของ Scarlet Crusade กำลังตั้งค่ายทางตะวันออกเฉียงใต้ พวกมันเป็นองค์กรต่ำช้าที่ตามล่าเราและจะไม่หยุดจนกว่าจะกำจัด{race}ทุกตน ไม่ว่าจะเป็น Scourge ของ Lich King หรือไม่ เราต้องชิงลงมือก่อน!\n\nระวังตัวด้วย ความคลั่งศรัทธาของพวกมันทำให้มันเป็นศัตรูที่อันตราย" } } },
        progress = { "64:371973108:1208940843", "เจ้าพวกโง่... พวกมันเดินลงหลุมศพตัวเองอย่างร่าเริง" },
        completion = { "37:1648716633:2144714674 N 85:759618539:1610346741", "ถ้าพวกมันฟังเหตุผลบ้างก็ดีสิ {name} เราอาจเชิญมานั่งคุยกันอย่างมีเหตุผล... ฮ่า!\n\nเจ้าพวกโง่ที่แสงทำให้ตาบอด" },
        required = { [3266] = { "15:1892441083:832588930", "ปลอกแขน Scarlet" } },
        steps = { { "15:1892441083:832588930", "ปลอกแขน Scarlet" } },
    },
    [382] = { -- The Red Messenger
        title = { "17:1907500376:1102944099", "ผู้ส่งสารสีชาด" },
        objective = { "111:83985235:221254693", "สังหาร Meven Korgal ผู้ส่งสารที่ค่าย Crusader แล้วนำข้อมูลที่พบกลับไปให้ Executor Arren" },
        description = { "356:1344314067:799720529 N 69:964007613:1717514129", "ผู้บังคับบัญชาของข้าใน Brill รายงานว่าตัวแทน Scarlet Crusade ถูกส่งจาก Scarlet Monastery มาที่ Deathknell ตามรายงาน ผู้ส่งสารพกข้อมูลสำคัญติดตัว ข้าไม่รู้รายละเอียดมากกว่านี้ แต่ไม่ว่าข้อมูลนั้นคืออะไร เราต้องเอามาให้ได้!\n\nท่านเหมาะกับงานนี้ที่สุดในบรรดาคนที่ข้าส่งไปได้ {name} หาตัวผู้ส่งสารแล้วนำข้อมูลที่พบมาให้ข้า" },
        progress = { "23:283455491:1828648899 N 1:63:63", "ภารกิจเป็นอย่างไรบ้าง {name}?" },
        completion = { "372:897053396:1806690166", "อืม... ไหนดูสิว่าท่านได้อะไรมา...\n\n<เขาเริ่มพลิกค้นเอกสารที่ท่านนำกลับมา>\n\nข่าวผลงานที่พวกมันเล่นงานเรา... ไร้ค่า รายงานสอดแนม... คำสั่งใหม่ ‘ตั้งค่ายใกล้เมืองร้างต่อไป...’ มีแต่เรื่องที่รู้แล้ว... อา นี่อะไร? แผนที่ระบุตำแหน่งผู้บัญชาการภาคสนามและสายลับบางคนของพวกมัน! อันนี้เอาไปใช้ได้" },
        required = { [2885] = { "25:476719688:1650130119", "เอกสารของ Scarlet Crusade" } },
        steps = { { "25:476719688:1650130119", "เอกสารของ Scarlet Crusade" } },
    },
    [383] = { -- Vital Intelligence
        title = { "18:654711235:386275770", "ข่าวกรองสำคัญ" },
        objective = { "66:69473625:416848183", "นำ Scarlet Crusade Documents ไปส่งให้ Executor Zygand ที่ Brill" },
        description = { "505:1617498731:897331950", "ต้องนำเอกสารเหล่านี้ไปให้ผู้บังคับบัญชาของข้า Executor Zygand ที่ Brill ข้อมูลนี้จะช่วยให้เราโจมตี Scarlet Crusade ได้อย่างเด็ดขาด ท่านช่วยงานใน Deathknell ได้มาก แต่ข้าต้องการคนส่งของนี้ให้ซีกันด์ และเชื่อว่าเขาจะหางานที่เหมาะกับท่านได้\n\nใช้ถนนขึ้นเหนือออกจาก Deathknell พอเข้าเขต Tirisfal ไม่นานจะเจอทางแยก เลี้ยวเข้าทางตะวันออกแล้วเดินไปเรื่อย ๆ จะผ่าน Cold Hearth Manor ระหว่างทาง" },
        progress = { "22:686048163:1976836213", "ว่าอย่างไร ท่านต้องการอะไร?" },
        completion = { "72:202187347:18009843 N 179:699546265:1428070314", "ใช่ ดีมาก ท่านทำได้ดีที่หาข้อมูลนี้มา {name} อืม... รายชื่อนายทหารใน Tirisfal Glades...\n\nลองคิดดูว่าขวัญกำลังใจของพวกคลั่งศรัทธาเปื้อนเลือดจะเสียหายแค่ไหน หากเราจัดการผู้นำของพวกมันได้ในคราวเดียว" },
        required = { [2885] = { "25:476719688:1650130119", "เอกสารของ Scarlet Crusade" } },
        steps = { { "25:476719688:1650130119", "เอกสารของ Scarlet Crusade" } },
    },
    [590] = { -- A Rogue's Deal
        title = { "14:1292733977:824354199", "ข้อตกลงของจอมเจ้าเล่ห์" },
        objective = { "37:2038706341:2017669803", "เอาชนะ Calvin Montague ที่ Deathknell" },
        description = { "157:1990081615:1663087124", "อะไรนะ?\n\nอะไรนะ?!\n\nท่านจะเอาเงินหรือ? ข้าไม่ได้ติดเงินท่านสักหน่อย\n\nจดหมาย? จดหมายอะไร? อ้อ อยากสู้สินะ เอาสิ สหาย... มาลุยกัน! ติดเงินท่านงั้นเรอะ..." },
        completion = { "52:581174562:1012946815 N 144:1235786233:1222937132", "เหลือเชื่อ! ฝีมือดีจริง!\n\nข้านึกว่าท่านเป็นเหยื่อง่าย ๆ เสียอีก {name} เล่นงานข้าซะอยู่หมัดเลย\n\nนี่เงินที่ข้ารับปาก... น้อยกว่าที่บอกไว้หน่อย เพราะตอนแรกข้าโกหกท่านน่ะสิ" },
        progress = { "32:769684408:2091537805", "ไม่เลวนี่ สหาย... ไม่เลวเลยจริง ๆ" },
        objectiveLabels = {
            event = { ["Defeat Calvin Montague"] = "เอาชนะ Calvin Montague" },
        },
    },
    [747] = { -- The Hunt Begins
        title = { "15:701063595:1092780437", "การล่าเริ่มขึ้น" },
        objective = { "112:2065518118:1946782831", "นำ Plainstrider Feather 7 ชิ้น และ Plainstrider Meat 7 ชิ้น ไปให้ Grull Hawkwind ที่ Camp Narache" },
        description = { "494:673618844:680611414", "ท่านดูมีแววและจะพิสูจน์ตัวเองให้เผ่าเห็นได้ สักวันท่านอาจได้รับการต้อนรับเข้าสู่นคร Thunder Bluff แต่ก่อนจะถึงวันนั้น ท่านต้องแสดงฝีมือให้พ่อข้า Chief Hawkwind เห็น\n\nบน Red Cloud Mesa เราภูมิใจในฝีมือการล่าอันเฉียบคม ทอเรนล่าทั้งเพื่อเลี้ยงชีพและเพื่อกีฬา เนื้อสำรองของเราใกล้หมดแล้ว และเราต้องใช้ขนทำเสื้อผ้า ล่า Plainstrider แถวนี้แล้วพิสูจน์ตัวเองด้วยการเติมเสบียงให้หมู่บ้าน" },
        progress = { "109:950987461:477706658", "การหาเนื้อกับขนมาให้เผ่าคือก้าวแรกในการพิสูจน์ฝีมือนักล่าต่อหน้าหัวหน้าเผ่า" },
        completion = { "33:585298480:345476862 N 24:836721913:1614539714", "เหล่าทอเรนแห่ง Narache ขอบคุณท่าน {name} ท่านมีแววมาก", variants = { { "4:1432760897:190637651 R 23:1108730658:603386196 N 24:836721913:1614539714", "เหล่า{race}แห่ง Narache ขอบคุณท่าน {name} ท่านมีแววมาก" } } },
        required = { [4739] = { "17:317888072:1037085135", "เนื้อนกทุ่ง" }, [4740] = { "20:1772453114:1314339494", "ขนนกทุ่ง" } },
        objectiveLabels = {
            item = { ["Plainstrider Meat"] = "เนื้อนกทุ่ง", ["Plainstrider Feather"] = "ขนนกทุ่ง" },
        },
    },
    [750] = { -- The Hunt Continues
        title = { "18:1948733448:1669232063", "การล่ายังดำเนินต่อ" },
        objective = { "79:590313299:601422891", "นำ Mountain Cougar Pelt 10 ผืนไปให้ Grull Hawkwind ที่ Camp Narache" },
        description = { "372:718642502:817184789", "ทอเรนผู้ชำนาญการล่ารู้ดีว่าเหยื่อมีค่าเกินกว่าจะเป็นเพียงของอวดฝีมือ สัตว์ในทุ่งราบช่วยให้เราอยู่รอด หากนำหนัง Mountain Cougar อันมีค่ากลับมาได้ เหล่าผู้อาวุโสคงประทับใจมาก พวกมันซุ่มอยู่ตามเนินเขาทางใต้\n\nลูกหลานเราต้องการเสื้อผ้า และกระโจมของเราต้องซ่อม" },
        progress = { "115:427717993:1597223439", "หากท่านหาหนังมาให้เผ่าได้ ข้าจะเล่าความเอื้อเฟื้อของท่านให้พ่อข้า Chief Hawkwind ฟัง" },
        completion = { "54:526719796:469259350 N 94:2073338579:717015275", "เหล่าทอเรนแห่ง Narache ขอบคุณสำหรับเสบียงเหล่านี้ {name} ด้วยฝีมือล่าเช่นนี้ วันหนึ่งท่านจะเป็นที่ยกย่องใน Thunder Bluff แน่" },
        required = { [4742] = { "20:1796408064:1507648063", "หนังเสือคูการ์ภูเขา" } },
        steps = { { "20:1796408064:1507648063", "หนังเสือคูการ์ภูเขา" } },
    },
    [752] = { -- A Humble Task
        title = { "13:1021122617:901282093", "งานเล็ก ๆ ที่ขอให้ช่วย" },
        objective = { "103:572151712:651718156", "Chief Hawkwind ขอให้ไปตามหาแม่ของเขาใกล้บ่อน้ำทางตะวันออกเฉียงใต้ของ Camp Narache" },
        description = { "400:657696265:896656036", "ทุกคนในเผ่าอยู่ร่วมกันอย่างกลมเกลียว เราใช้ชีวิตและทำงานด้วยกัน\n\nความผูกพันที่เรามีต่อกันมาพร้อมความรับผิดชอบอย่างยิ่ง ตอนนี้ข้ามีงานเล็ก ๆ อยากขอให้ท่านช่วย\n\nแม่ของข้าออกไปตักน้ำที่บ่อทางตะวันออกเฉียงใต้ของ Narache ตั้งแต่เช้า นานพอสมควรแล้ว ท่านพอไปดูให้ข้าได้ไหม ข้าต้องอยู่จัดการเรื่องของเผ่าที่นี่" },
        completion = { "80:251150230:2094611908", "ท่านเดินมาตั้งไกลเพื่อช่วยหญิงแก่อย่างข้าหรือ? แหม คนดีอย่างท่านหายากนะ", variants = { { "184:1712705830:845062540", "ท่านเดินมาตั้งไกลเพื่อช่วยหญิงแก่อย่างข้าหรือ? แหม คนดีอย่างท่านหายากนะ เอาคู่มือฝึกเล่มหนึ่งติดตัวไปสิ จะได้รู้ว่าจะช่วยชุมชนของเราได้อย่างไร" } } },
    },
    [753] = { -- A Humble Task
        title = { "13:1021122617:901282093", "งานเล็ก ๆ ที่ขอให้ช่วย" },
        objective = { "134:1294943641:841089418", "หยิบ Water Pitcher จากบ่อน้ำ\n\nนำเหยือกกลับไปให้ Chief Hawkwind ที่ Camp Narache ทางตะวันตกเฉียงเหนือของบ่อน้ำ" },
        description = { "229:944584879:168798217 C 218:1891339963:285666305", "ข้าเดินมาหลายเส้นทางในชีวิต ขาแก่ ๆ คู่นี้ไม่มีแรงอย่างแต่ก่อนแล้ว ข้ายังทำหน้าที่ให้เผ่าได้ เพียงแต่บางครั้งหญิงแก่ก็ต้องใช้เวลานานขึ้นหน่อย\n\nแต่ท่านดูเป็น{class}ที่กระตือรือร้นดี มาลองใช้เรี่ยวแรงวัยหนุ่มสาวให้เป็นประโยชน์เถิด หยิบเหยือกน้ำจากบ่อแล้วเอาไปให้ลูกชายข้า หัวหน้าเผ่าที่ Camp Narache\n\nจำไว้ว่างานเล็กน้อยเพียงใดก็ทำให้ผู้อาวุโสเห็นคุณค่าของท่านได้" },
        progress = { "101:1604543592:1739916183", "ดูเหมือนท่านเพิ่งกลับมาจากทุ่งราบ มีข่าวจาก Greatmother Hawkwind หรือไม่?" },
        completion = { "218:1679942771:1636863446", "ท่านแบกเหยือกนี้กลับมาตามที่ท่านแม่ขอสินะ\n\nความเต็มใจช่วยคนอื่นและหาเสบียงให้ชาวทอเรนแห่ง Camp Narache ทำให้ข้าเชื่อว่าสักวันท่านจะสร้างความภูมิใจให้เผ่าที่ Thunder Bluff" },
        required = { [4755] = { "13:888846456:235993802", "เหยือกน้ำ" } },
        steps = { { "13:888846456:235993802", "เหยือกน้ำ" } },
    },
    [757] = { -- Rite of Strength
        title = { "16:1055973104:1175051259", "พิธีแห่งพละกำลัง" },
        objective = { "106:1401571499:1361600066", "สังหาร Bristleback ใน Brambleblade Ravine และนำ Bristleback Belt 12 เส้นไปให้ Chief Hawkwind ที่ Camp Narache" },
        description = { "497:2070079420:364582692", "พิธีแห่งพระแม่ธรณีเป็นขั้นตอนที่ทอเรนวัยเยาว์ต้องผ่านเพื่อให้ชาว Thunder Bluff ยอมรับ\n\nก่อนอื่นท่านต้องผ่านพิธีแห่งพละกำลัง บททดสอบนี้ให้ท่านพิสูจน์ความกล้าด้วยการสังหารศัตรูของเผ่า\n\nพวก Bristleback จาก Brambleblade Ravine ทางตะวันออกกำลังรุกล้ำแดนเผ่าเรา พวกมันซุ่มโจมตีคณะล่าสัตว์และลักของจากหมู่บ้านยามค่ำ\n\nแสดงความกล้าด้วยการกำจัดเจ้าวายร้าย แล้วนำเข็มขัดของพวกมันกลับไปให้หัวหน้าเผ่าที่ Camp Narache เป็นหลักฐาน" },
        progress = { "41:1078815117:1328997449 N 81:1494671740:1520195456", "ท่านผ่านพิธีแห่งพละกำลังแล้วหรือ {name}? ข้าต้องการหลักฐานว่าท่านกล้าสู้กับ Bristleback ศัตรูของเผ่าเรา" },
        completion = { "88:2048302770:869547005", "ท่านผ่านบททดสอบแรกของพิธีแห่งพระแม่ธรณีแล้ว เผ่าจะภูมิใจ" },
        required = { [4770] = { "16:45421857:976665311", "เข็มขัด Bristleback" } },
        steps = { { "16:45421857:976665311", "เข็มขัด Bristleback" } },
    },
    [780] = { -- The Battleboars
        title = { "15:1898100735:2103831523", "เหล่าหมูป่าศึก" },
        objective = { "120:1701553092:108567458", "Grull Hawkwind ที่ Camp Narache ต้องการให้ท่านสังหาร Battleboar แล้วนำ Battleboar Snout 8 ชิ้น และ Battleboar Flank 8 ชิ้นกลับมา" },
        description = { "293:1894343749:713122868", "Battleboar จาก Brambleblade Ravine ทางตะวันออกกำลังรุกล้ำเขตล่าสัตว์ของเผ่าเรา พวกมนุษย์หมูป่า Bristleback ที่ทำสงครามกับเราฝึกให้มันดุร้าย\n\nไปสังหารสัตว์ร้ายพวกนั้น แล้วเอาจมูกกับเนื้อสีข้างกลับมา เราจะได้ทำสตูให้ลูกหลานกิน" },
        progress = { "128:1229163412:1052491669", "พวก Battleboar ดุร้ายขึ้นทุกที ท่านได้สั่งสอนพวกมันและเอาจมูกกับเนื้อสีข้างกลับมาหรือยัง?" },
        completion = { "135:2105294614:943956679", "ยอดเยี่ยม วัตถุดิบพวกนี้จะทำสตูได้อร่อยทีเดียว การเสียหมูป่าไปคงเป็นบทเรียนให้ Bristleback ตัวร้ายได้บ้าง" },
        required = { [4848] = { "16:174417719:1710837410", "จมูกหมูป่าศึก" }, [4849] = { "16:1409485295:25084704", "เนื้อสีข้างหมูป่าศึก" } },
        steps = { { "16:174417719:1710837410", "จมูกหมูป่าศึก" }, { "16:1409485295:25084704", "เนื้อสีข้างหมูป่าศึก" } },
    },
    [781] = { -- Attack on Camp Narache
        title = { "22:1377378489:744582414", "แผนโจมตี Camp Narache" },
        objective = { "69:1054158327:776508677", "นำ Bristleback Attack Plans ไปให้ Chief Hawkwind ที่ Camp Narache" },
        description = { "208:1037435502:1521991882", "เมื่อพิจารณาแผนที่ถี่ถ้วน ท่านก็รู้ว่าสิ่งที่พบคือแผนของจอมศึก Bristleback ที่จะปิดล้อม Camp Narache เป็นเวลานาน\n\nข้อมูลนี้ต้องมีประโยชน์กับ Chief Hawkwind แน่!" },
        progress = { "38:2146976931:2107067492 N 25:509013137:1435545281", "ท่านดูเป็นกังวลนะ {name} มีข่าวอะไรมาหรือ?" },
        completion = { "176:47580412:1797589139 N 1:46:46", "น่าตกใจจริง ๆ! แต่พอรู้แผนนี้แล้ว เราก็เรียกพี่น้องจาก Bloodhoof Village มาช่วยสกัดการโจมตีได้ ท่านช่วยชีวิตทอเรนไว้มากมาย {name}" },
        required = { [4850] = { "24:1310178823:1102962485", "แผนโจมตีของ Bristleback" } },
        steps = { { "24:1310178823:1102962485", "แผนโจมตีของ Bristleback" } },
    },
    [787] = { -- The New Horde
        title = { "13:454004973:376458289", "Horde ยุคใหม่" },
        objective = { "28:2006377170:223864232", "ไปรายงานตัวกับ Gornek ใน The Den" },
        description = { "10:1652484069:1189355142 C 478:151849185:529264783", "ทรอมคา ท่าน{class} ข้าคือไอทริก ธรอลล์มอบหมายให้ดูแลการฝึกทหารใหม่\n\nHorde เปลี่ยนไปจากเดิมแล้ว ครั้งหนึ่งข้าเคยออกจาก Horde เพราะหมดศรัทธาเมื่อเห็นเหล่าหุ่นเชิดผู้กระหายอำนาจของ Burning Legion มีอิทธิพลมากขึ้น ระหว่างถูกเนรเทศ ข้าถูกมนุษย์จับเป็นเชลย แต่จอมทัพช่วยข้าไว้ เมื่อได้ฟังปณิธานของเขาที่จะให้ Horde พ้นอำนาจปีศาจและเดินตามคำชี้นำของเหล่าชาแมน ข้าก็กลับมา\n\nกอร์เน็กจะบอกว่าท่านต้องทำอะไรต่อ" },
        completion = { "233:750329055:862623340", "ทหารใหม่ของไอทริกอีกคนหรือ?\n\nน่าหนักใจเสียจริงถ้านี่คือคนที่ดีที่สุดที่ Horde หาได้ ช่างเถอะ เมื่อถึงวันที่เราเห็นว่าท่านพร้อมออกจากหุบเขา ท่านจะเป็นนักรบผู้ภาคภูมิแห่ง Horde" },
    },
    [789] = { -- Sting of the Scorpid
        title = { "20:1502179445:343872622", "เหล็กในแมงป่อง" },
        objective = { "50:681102936:916686933", "หา Scorpid Worker Tail 10 ชิ้นไปให้ Gornek ใน The Den" },
        description = { "460:1078555311:1781342265", "ทั้งนักรบเก่งกาจและมือใหม่งุ่มง่ามล้วนเคยล้มเพราะเหล็กในพิษของแมงป่อง ทางตะวันตกเฉียงเหนือมีแมงป่องอยู่มาก เอาหางพวกมันมาให้ข้าสิบหางเป็นหลักฐานฝีมือการรบ\n\nยาถอนพิษที่จริงทำจากพิษที่รีดจากเหล็กในของมันเอง เรามียาถอนพิษแมงป่องสำรองไว้มากเพื่อรักษามือใหม่อย่างท่าน...\n\nแต่ข้าว่าท่านคงไม่ต้องใช้หรอก จริงไหม?" },
        progress = { "176:285518991:1400527711", "กระดองแมงป่องไม่ได้หนาจนต้านแรงของนักรบที่มุ่งมั่นได้ ฟันให้หนักและอย่าลังเล แล้วแมงป่องจะเป็นเหยื่อที่จัดการง่าย" },
        completion = { "240:861702500:59780353 N 67:712352184:904215455", "การสู้กับแมงป่องมีบทเรียนสำคัญที่ท่านต้องจำ ศัตรูตัวเล็กที่สุดหรือตัวใหญ่ที่สุดต่างก็เอาชีวิตท่านได้ ในการต่อสู้ดุเดือด มีสารพัดอย่างที่อาจทำให้ท่านพลาดท่า\n\nข้าไม่มีอะไรจะสอนท่านแล้ว {name} ท่านทำได้ดี ข้าจะคอยติดตามความก้าวหน้าด้วยความสนใจ" },
        required = { [4862] = { "19:63750805:340307133", "หางแมงป่องงาน" } },
        steps = { { "19:63750805:340307133", "หางแมงป่องงาน" } },
    },
    [790] = { -- Sarkoth
        title = { "7:112585053:1121005133", "ซาร์คอธ" },
        objective = { "49:1079645511:351971906", "สังหาร Sarkoth แล้วนำก้ามของมันกลับไปให้ Hana'zua" },
        description = { "C 489:1892301626:758692774", "ท่าน{class}! ข้านึกว่าจะต้องตายตรงนี้โดยไม่มีใครรู้เสียแล้ว ตอนล่าแมงป่องในหุบเขา ข้าเจอตัวหนึ่งหน้าตาดุเป็นพิเศษ ข้าพุ่งเข้าใส่และฟันก้ามมันอย่างจังก่อนที่มันจะหนีบขาข้า\n\nแต่ข้าระวังเหล็กในไม่ทัน มันฟาดลงมาที่อก ฉีกเนื้อจนเลือดไหล โปรดช่วยฆ่าแมงป่องตัวนั้นให้ข้าที! ข้าต้องรักษาเกียรติไว้! ข้าสู้กับมันบนที่ราบสูงทางใต้" },
        progress = { "218:520410388:443851429", "อา... พ่อเคยบอกว่าข้าคงเอาดีอะไรไม่ได้ ตอนนี้ข้านอนอยู่ใต้ต้นไม้และชีวิตกำลังไหลออกไป ดูเหมือนพ่อจะพูดถูก\n\nอย่างน้อยข้าก็อยากตายโดยรู้ว่าศัตรูตัวสุดท้ายในชีวิตล้มลงแล้ว" },
        completion = { "261:263164824:1663467456", "ข้าฟันมันไม่ถึงตาย แต่พอเห็นบาดแผลที่ข้าฝากไว้ก็ยังพอภูมิใจอยู่บ้าง หากข้าต้องตาย ความภูมิใจเล็กน้อยนั้นคงเป็นสิ่งเดียวที่เหลือให้ยึดไว้ พอคิดเช่นนี้ ผลงานที่มีน้อยนิดทั้งชีวิตก็ทำให้ข้าโกรธนัก" },
        required = { [4905] = { "22:80882595:1704317771", "กรงเล็บฉีกขาดของ Sarkoth" } },
        steps = { { "22:80882595:1704317771", "กรงเล็บฉีกขาดของ Sarkoth" } },
    },
    [794] = { -- Burning Blade Medallion
        title = { "23:588332921:543633235", "เหรียญตรา Burning Blade" },
        objective = { "71:918037380:493435794", "นำ Burning Blade Medallion ไปให้ Zureetha Fargaze ด้านนอก The Den" },
        description = { "420:1263631343:1320443819 N 59:2052476671:372427476", "จากการทำนาย ข้าเห็นวัตถุทรงพลังซ่อนอยู่ลึกใน Burning Blade Coven มีสัตว์ร้ายและมนตร์ดำเฝ้าอยู่\n\nของนั้นเรียกว่า Burning Blade Medallion งานต่อไปของท่านคือตามหาและนำมันออกจากที่ชุมนุม\n\nแต่ระวังไว้ เหรียญตราอาจอยู่กับคนของ Burning Blade หากเป็นอย่างนั้น คนผู้นั้นย่อมมีพลังเหนือสัตว์รับใช้ที่ท่านเคยพบ\n\nไปเถิด {name} ท่านจะพบที่ชุมนุมในถ้ำทางเหนือค่อนไปตะวันตก" },
        progress = { "23:919371946:249700062 N 42:279264905:87320059", "งานเสร็จแล้วหรือ {name}? ท่านได้ Burning Blade Medallion มาหรือยัง?" },
        completion = { "211:104200820:1063297950", "ท่านนำมันกลับมาได้! ทำได้ดี!\n\nสิ่งที่ท่านทำใน Burning Blade Coven สำคัญต่อการถอนรากลัทธินี้ใน Valley of Trials แต่ข้าเกรงว่าพวกมันยังมีแผนอื่นในดินแดนเรา\n\nเรื่องนี้ยังไม่จบแน่" },
        required = { [4859] = { "23:588332921:543633235", "เหรียญตรา Burning Blade" } },
        steps = { { "23:588332921:543633235", "เหรียญตรา Burning Blade" } },
    },
    [804] = { -- Sarkoth
        title = { "7:112585053:1121005133", "ซาร์คอธ" },
        objective = { "57:1166048784:2097707936", "ไปบอก Gornek ที่ The Den ว่า Hana'zua กำลังเดือดร้อน" },
        description = { "173:1425640013:1265729458 N 76:961208537:728085393", "สิ่งที่ท่านทำเพื่อข้าทำให้ใจข้าเข้มแข็งขึ้น ข้าจะล้มง่าย ๆ อย่างนี้ไม่ได้! ต้องอดทนไว้!\n\nแต่ข้ายังเดินกลับ The Den เองไม่ไหว โปรดกลับไปที่นั่นแล้วบอกกอร์เน็กว่าข้าเป็นอย่างไร {name} เขาอาจช่วยข้าได้" },
        completion = { "335:133052941:1321194624 N 118:873503178:679793507", "จากที่ท่านเล่าถึงสัตว์ตัวนั้น ข้าว่าท่านพูดถึงซาร์คอธแน่! ไม่น่าแปลกที่ฮานาซัวพลาดท่า ข้าจะส่งคนไปช่วยเดี๋ยวนี้ ท่านไม่ต้องกังวลเรื่องเขาแล้ว\n\nแต่ข้าประทับใจมากที่ท่านฆ่าซาร์คอธได้ เป็นผลงานที่ควรภูมิใจ {name} แม้ท่านมีงานอื่นให้ทำ ยังยอมสู้เพื่อรักษาเกียรติของคนแปลกหน้า การกระทำนี้ยิ่งเสริมเกียรติของท่านเอง" },
    },
    [1656] = { -- A Task Unfinished
        title = { "17:1979964047:1165857101", "งานที่ยังทำไม่เสร็จ" },
        objective = { "65:72833766:1293884768", "นำ Bundle of Furs ไปให้ Innkeeper Kauth ที่ Bloodhoof Village" },
        description = { "N 425:1948162671:1819951801", "{name} ได้โปรด ช่วยข้าที งานบนที่ราบสูงของข้ายังไม่เสร็จ ข้ากำลังทำพิธีแห่งพละกำลังอยู่ และพ่อข้าขอให้เอาขนสัตว์พวกนี้ไปส่งที่โรงเตี๊ยมใน Bloodhoof\n\nข้าเหนื่อยเกินจะทำทั้งพิธีและงานของพ่อให้เสร็จ ท่านช่วยไปส่งแทนข้าได้ไหม?\n\nโรงเตี๊ยมน่าอยู่และเหมาะจะพักระหว่างเดินทางไกล พอเห็นแล้วท่านต้องเห็นด้วยแน่" },
        progress = { "173:114639509:1878869713", "ว่าอย่างไร เจ้าหนุ่มสาว เคาธ์ช่วยอะไรท่านได้?\n\nการเดินทางจากที่ราบสูงมาถึงนี่อาจหนักหนาสำหรับบางคน ขณะที่บางคนเห็นที่นี่แล้วชื่นใจ ข้าสงสัยว่าท่านเป็นแบบไหน?" },
        completion = { "356:865782536:514778776", "อา ขนสัตว์ที่ข้ารออยู่ ขอบคุณนะ\n\nมาถึงเร็วกว่าที่คิดไว้เสียอีก เอาไปทำผ้าห่มดี ๆ ให้คนที่มาพักได้เลย\n\nพักนานเท่าที่ต้องการได้เลย โรงเตี๊ยมข้าเปิดรับคนของเราเสมอ อย่าดูเบาการได้นอนเต็มอิ่มสักคืน มันช่วยให้การเดินทางต่างไปมากทีเดียว" },
        required = { [7626] = { "14:477579327:633218508", "มัดหนังสัตว์" } },
        steps = { { "14:477579327:633218508", "มัดหนังสัตว์" } },
    },
    [3376] = { -- Break Sharptusk!
        title = { "16:1261888964:1087688838", "โค่นชาร์ปทัสก์!" },
        objective = { "85:717778079:625791991", "นำหัวของ Chief Sharptusk Thornmantle ไปให้ Brave Windfeather ที่ Red Cloud Mesa" },
        description = { "N 434:573197363:1179433885", "{name} ข้าได้ยินเรื่องของท่านมา ผู้มาใหม่ บางทีท่านอาจช่วยเราได้ในเรื่องที่คนอื่นทำไม่สำเร็จ\n\nพวกเราทอเรนสร้างบ้านบนแผ่นดินนี้โดยต้องเสียอะไรไปไม่น้อย พวกมนุษย์หมูป่า Bristleback แห่ง Brambleblade Ravine ที่มี Chief Sharptusk Thornmantle เป็นผู้นำทำสงครามกับเราไม่หยุด จนพวกเราอยู่ลำบาก ข้าขอมอบหมายให้ท่านนำหัวของหัวหน้าเผ่ามาให้ข้า!\n\nเขาอยู่ในหมู่บ้านชั่วคราวของพวกมันในหุบผาทางตะวันออก" },
        progress = { "107:52492348:1069096427 N 208:1627866930:180125063", "ชาร์ปทัสก์จะสร้างปัญหาให้เราไม่ได้อีกเมื่อท่านนำหลักฐานการตายมา ข้าต้องการหัวของมัน {name}\n\nพวกเราทอเรนมีชีวิตเพื่อการล่า และไม่มีการล่าใดยิ่งใหญ่กว่าการล่าศัตรูที่เจ้าเล่ห์พอจะย้อนมาล่าเรา หากทำงานนี้สำเร็จ ท่านจะเริ่มเข้าใจว่าข้าหมายถึงอะไร เจ้าหนุ่มสาว" },
        completion = { "59:21343624:1598584648 N 134:1425818781:1389066062 C 1:46:46", "วันนี้ความยุติธรรมเกิดขึ้นด้วยการลงมืออย่างฉับไวของท่าน {name} ขอให้ผลงานนี้เป็นคำเตือนแก่ทุกคนที่คิดคุกคามบ้านของเรา\n\nท่านสมควรได้รับรางวัลนี้ไว้ช่วยระหว่างเดินทาง ท่าน{class}ผู้เยาว์" },
        required = { [10459] = { "34:1129237119:284368629", "หัวของ Chief Sharptusk Thornmantle" } },
        steps = { { "34:1129237119:284368629", "หัวของ Chief Sharptusk Thornmantle" } },
    },
    [3901] = { -- Rattling the Rattlecages
        title = { "24:161572497:2043400887", "เขย่ากระดูกพวกแรตเทิลเคจ" },
        objective = { "102:1419301312:501806322", "สังหาร Rattlecage Skeleton 12 ตัว เสร็จแล้วกลับไปหา Shadow Priest Sarvis ที่ Deathknell" },
        description = { "71:978769688:1202241681 N 277:761924186:900390287", "ท่านแสดงแววให้ Forsaken เห็นแล้วในยามปกติ {name} มาดูกันว่าพอถูกกดดันแล้วจะเป็นอย่างไร\n\nพวกโครงกระดูก Rattlecage เป็นสมุนไร้จิตอีกพวกของ Lich King มันรับมือยากกว่าซอมบี้ที่ท่านเจอมาจนถึงตอนนี้ จงลดจำนวนพวกมันและพิสูจน์ตัวเองต่อ Forsaken อีกครั้ง อย่าชักช้า ทำเสร็จแล้วกลับมาคุยกับข้า" },
        progress = { "176:1325395512:355502671", "ใครมัวโอ้เอ้กับงานนี้อาจลงเอยเดินเตร่ไร้จุดหมายเหมือนพี่น้องที่ล้มตายไปในหมู่บ้าน หวังว่าท่านจะทำได้ดีกว่าพวกนั้นนะ" },
        completion = { "24:1971196145:1054998433 N 299:1544699978:1062120156 C 1:46:46", "ข้าหมดงานให้ท่านแล้ว {name} ท่านพิสูจน์แล้วว่าคู่ควรกับอิสรภาพที่ได้รับ หลายคนจะต่อต้านท่านเพราะสิ่งที่ท่านกลายมาเป็น แต่ไม่ว่าพวกมันจะทำอะไรกับเรา ขอให้จำไว้ว่าเราเป็นอิสระและจะไม่ถูกล่ามโซ่อีก\n\nรับของเหล่านี้แล้วไปเถิด ท่านยังมีอีกมากให้ทำ ท่าน{class}" },
        objectiveLabels = {
            monster = { ["Rattlecage Skeleton slain"] = "ปราบ โครงกระดูก Rattlecage" },
        },
    },
    [3902] = { -- Scavenging Deathknell
        title = { "21:1073473822:1557724751", "เก็บของที่เหลือใน Deathknell" },
        objective = { "106:1857855276:1371878772", "ค้นหา Scavenged Goods 6 ชิ้นใน Deathknell และบริเวณใกล้เคียง แล้วนำกลับไปให้ Deathguard Saltain" },
        description = { "457:1311042028:1359700806", "ท่านตรงนั้น! ถ้าอยากทำตัวให้มีประโยชน์ก็ฟังให้ดี!\n\nเราต้องการทหารใหม่ที่เพิ่งขึ้นจากหลุมให้เข้า Deathknell ไปหาอุปกรณ์อะไรก็ได้ที่ยังใช้ได้ ส่วนใหญ่น่าจะอยู่ในกองลัง อีกไม่นานคงมีทหารใหม่ผุดขึ้นมาอีก ถ้าไม่อยากให้พวกนั้นเดินโซเซตัวเปล่าก็รีบไปเก็บของเถอะ!\n\nเอ้า ไปทำงานได้แล้ว เจ้ากองกระดูกน่าสมเพช! ใครไม่ขยันก็อย่าหวังรางวัล" },
        progress = { "199:456684641:1742189128", "หาอะไรที่ใช้ได้มาให้เราบ้างหรือยัง? เอาของที่คนอื่นทิ้งมาใช้ใหม่ไม่ใช่เรื่องน่าอาย ไม่มีใครยื่นของให้เราฟรี ๆ หรอก พวกเรา Forsaken ต้องดูแลตัวเอง!" },
        completion = { "11:1915723900:848913832 N 125:606784554:193920105", "ทำได้ดีมาก {name} ข้ารู้อยู่แล้วว่าท่านพึ่งได้ เอ้านี่ เลือกของชิ้นดี ๆ จากที่เก็บกันมาให้ท่านชิ้นหนึ่ง" },
        required = { [11127] = { "15:1691329440:1170087181", "ของที่เก็บกู้มาได้" } },
        steps = { { "15:1691329440:1170087181", "ของที่เก็บกู้มาได้" } },
    },
    [4402] = { -- Galgar's Cactus Apple Surprise
        title = { "30:1253537446:1047086435", "ของหวานแอปเปิลกระบองเพชรสูตรกัลการ์" },
        objective = { "94:667411195:1338586288", "นำ Cactus Apple 10 ผลไปให้ Galgar ท่านจำได้ว่าเขาบอกให้หาตามต้นกระบองเพชร" },
        description = { "243:1554721018:906443858 N 219:1853417485:1765424200", "Valley of Trials นี่ร้อนเอาเรื่องจริง ๆ\n\n<กัลการ์ปาดเหงื่อที่หน้าผาก>\n\nถ้ามีแอปเปิลกระบองเพชรสักหน่อย ข้าจะทำของหวานสูตรขึ้นชื่อได้! กินของอร่อยนี่สักชิ้น หายร้อนเร็วกว่าอะไรทั้งหมด\n\nเอาอย่างนี้ {name} ถ้าท่านนำแอปเปิลกระบองเพชร 10 ผลมาให้ ข้าจะทำของหวานให้หลายส่วนไว้พกไปผจญภัย ถ้าสนใจ หาแอปเปิลกระบองเพชรได้ใกล้ต้นกระบองเพชรแถวนี้", variants = { { "243:1554721018:906443858 N 252:236181807:873923451", "Valley of Trials นี่ร้อนเอาเรื่องจริง ๆ\n\n<กัลการ์ปาดเหงื่อที่หน้าผาก>\n\nถ้ามีแอปเปิลกระบองเพชรสักหน่อย ข้าจะทำของหวานสูตรขึ้นชื่อได้! กินของอร่อยนี่สักชิ้น หายร้อนเร็วกว่าอะไรทั้งหมด\n\nเอาอย่างนี้ {name} ถ้าท่านนำแอปเปิลกระบองเพชร 10 ผลมาให้ ข้าจะทำของหวานให้หลายส่วนไว้พกไปผจญภัย และแถมคู่มือฝึกให้อีกเล่ม ถ้าสนใจ หาแอปเปิลกระบองเพชรได้ใกล้ต้นกระบองเพชรแถวนี้" } } },
        progress = { "43:1782024227:2125104614", "ท่านเก็บแอปเปิลกระบองเพชรเสร็จแล้วหรือยัง?" },
        completion = { "11:2138623245:698779024 N 80:1971581107:540144505", "ยอดเยี่ยม {name}! นี่ของหวานแอปเปิลกระบองเพชรตามที่สัญญาไว้ พร้อมของแถมเล็กน้อย", variants = { { "11:2138623245:698779024 N 121:287301802:1190681089", "ยอดเยี่ยม {name}! นี่ของหวานแอปเปิลกระบองเพชรตามที่สัญญาไว้ เลือกคู่มือฝึกไปด้วยสักเล่มสิ ข้ามีอีกเยอะ" } } },
        required = { [11583] = { "12:1028730329:1744836832", "แอปเปิลกระบองเพชร" } },
        objectiveLabels = {
            item = { ["Cactus Apple"] = "แอปเปิลกระบองเพชร" },
        },
    },
    [5441] = { -- Lazy Peons
        title = { "10:226123023:1888119274", "คนงานขี้เกียจ" },
        objective = { "163:1480739214:1425951611", "ใช้ Foreman's Blackjack กับ Lazy Peon ขณะหลับ ปลุกคนงานให้ตื่น 5 คน แล้วนำ Foreman's Blackjack คืนให้ Foreman Thazz'ril ใน Valley of Trials" },
        description = { "179:666324485:1575203459 R 212:858326424:1627863986", "เจ้าพวกคนงานบ้าเอ๊ย! เวลาหาไม้จากต้นไม้ในหุบเขาก็ขยันอยู่หรอก แต่เอาแต่งีบตลอด! ข้าต้องการคนช่วยคุมคนงานให้อยู่ในระเบียบ\n\nท่านดูเป็น{race}ที่เหมาะกับงานนี้ เอ้านี่ รับกระบองไปใช้กับคนงานขี้เกียจที่แอบหลับในเวลางาน ตีสักทีให้ตื่นแล้วมันจะกลับไปทำงานทันที! เสร็จแล้วเอากระบองมาคืนด้วย\n\nเจ้าพวกคนงานอู้งานไม่ได้เรื่อง..." },
        progress = { "91:1474964021:1049539753", "เจ้าพวกขี้เกียจไม่ได้เรื่อง...\n\nหือ? กระบองข้าอยู่กับท่านไหม? จับคนงานที่แอบหลับในเวลางานได้บ้างหรือเปล่า?!" },
        completion = { "85:2112004100:1539951143", "ดี ดี คราวหน้าพวกมันคงคิดให้ดีก่อนอู้งาน! ขอบคุณที่ช่วย!" },
        required = { [16114] = { "19:1321085101:1796114396", "กระบองสั้นของหัวหน้าคนงาน" } },
        steps = { { "12:825612872:1090563135", "ปลุกคนงานออร์ค" }, { "19:1321085101:1796114396", "กระบองสั้นของหัวหน้าคนงาน" } },
    },
    [6394] = { -- Thazz'ril's Pick
        title = { "16:1411818740:791133754", "อีเต้อของแธซริล" },
        objective = { "44:120003516:58909686", "นำ Thazz'ril's Pick ไปให้ Foreman Thazz'ril" },
        description = { "N 23:239938559:1510898210 R 464:242473748:1643838504", "{name} ท่านเป็น{race}ที่พึ่งได้ ข้าฝากอีกงานได้ไหม?\n\nก่อนหน้านี้ข้าไปสำรวจหาแร่ในถ้ำทางเหนือแล้วลืมอีเต้ออันโปรดไว้ พอกลับไปเอาก็พบว่าสัตว์ร้ายอยู่เต็มถ้ำ! ท่านช่วยเข้าไปในถ้ำ Burning Blade Coven แล้วเอาอีเต้อมาให้ข้าได้ไหม?\n\nข้าทิ้งไว้ในโถงที่มีน้ำตก อีเต้อถูกลงมนตร์ไว้จึงมองเห็นได้ในความมืด ไม่ต้องห่วงว่าจะหาไม่เจอ... ห่วงแค่ตัวที่เฝ้ามันอยู่ก็พอ!" },
        progress = { "42:8475640:2074766553 N 23:1197655008:1589381528", "ท่านเข้า Burning Blade Coven แล้วหรือ {name}? เจออีเต้อข้าไหม?" },
        completion = { "33:1480653883:594565144 N 121:1139496650:1270967377", "ยอดเยี่ยม ได้มาจริง ๆ! ขอบคุณมาก {name} นี่อีเต้ออันโปรดของข้าเลย! ทีนี้ถ้าพวกคนงานตัดต้นไม้พวกนี้เสร็จสักที เราอาจหาถ้ำดี ๆ ทำเหมืองได้!" },
        required = { [16332] = { "16:1411818740:791133754", "อีเต้อของ Thazz'ril" } },
        steps = { { "16:1411818740:791133754", "อีเต้อของ Thazz'ril" } },
    },
    [6395] = { -- Marla's Last Wish
        title = { "17:114332667:2036351073", "คำขอสุดท้ายของมาร์ลา" },
        objective = { "75:930452551:1631111719", "นำ Samuel Fipps' Remains ไปที่ Marla's Grave แล้วกลับไปหา Novice Elreth" },
        description = { "495:190059413:1505525796", "มาร์ลา ฟิปส์ เพื่อนข้าอยู่กับซามูเอลสามีของนางก่อนเกิดโรคระบาด เมื่อโรคระบาดมาถึง ซามูเอลก็พ่ายให้โรคและกลายเป็นพวก Scourge\n\nมาร์ลารอดจากการกลายเป็นอันเดด แต่กลับต้องตายด้วยมือสามีที่สูญสิ้นสติ แม้กระนั้นนางก็รักเขามากจนคำขอสุดท้ายก่อนตายคืออยากถูกฝังเคียงข้างซามูเอลผู้เป็นที่รัก\n\nซามูเอล ฟิปส์เดินเตร่อยู่ในค่ายร้างริมถนนทางตะวันออกเฉียงเหนือของ Deathknell เอาชนะเขาแล้วทำตามคำขอของมาร์ลา ฝังเขาที่หลุมศพของนางในแถวแรกของสุสานเรา" },
        progress = { "26:277886529:1194991576 N 62:1228630626:1558221487", "เราต้องให้เกียรติผู้ตายของเรา {name} นั่นเป็นอย่างหนึ่งที่ทำให้เราต่างจาก Scourge..." },
        completion = { "33:1060117699:1022569595 N 143:1860372753:1865070769", "วันนี้ท่านทำความดีแล้ว {name} แม้การต่อสู้กับ Scourge ยังดำเนินต่อไป ขอให้มาร์ลากับซามูเอลได้พบความสงบด้วยกัน ณ ที่พักสุดท้ายของทั้งคู่", variants = { { "33:1060117699:1022569595 N 213:752506506:1746501880", "วันนี้ท่านทำความดีแล้ว {name} แม้การต่อสู้กับ Scourge ยังดำเนินต่อไป ขอให้มาร์ลากับซามูเอลได้พบความสงบด้วยกัน ณ ที่พักสุดท้ายของทั้งคู่ โปรดเลือกคู่มือที่ข้าพบไปสักเล่มแทนคำขอบคุณ" } } },
        steps = { { "23:1775154871:1688746834", "ฝังร่างของ Samuel" } },
    },
