    [8862] = { -- Elune's Candle
        title = { "14:1736165927:186769228", "เทียนแห่งเอลูน" },
        progress = { "271:513357902:396428844", "เทียนแห่งเอลูนเป็นวัตถุที่ผู้ร่วมเทศกาลจันทราเคารพบูชาอย่างยิ่ง ข้างในกักแสงจันทร์แท้ไว้ พร้อมปลดปล่อยออกมา!\n\nแสงนี้ไม่เป็นอันตรายต่อสิ่งมีชีวิตส่วนใหญ่ แต่เมื่อส่องใส่ Omen กับสมุน แสงจะแผดเผาและทำให้พวกมันตาพร่า" },
        completion = { "207:541698229:2038137952 N 94:1556154073:181567991", "ตกลง ข้ารับ Coins of Ancestry เหล่านี้ไว้ โปรดรับเทียนแห่งเอลูนพร้อมพรจากข้า และขอให้สนุกกับพลุที่ข้าแถมให้ด้วย\n\nขอให้เทศกาลจันทราของท่านเต็มไปด้วยความสุขและเสียงหัวเราะ {name}\n\nหากท่านเลือกเผชิญหน้ากับ Omen และสมุน เทียนแห่งเอลูนจะมีประโยชน์ทีเดียว..." },
        description = { "271:513357902:396428844", "เทียนแห่งเอลูนเป็นวัตถุที่ผู้ร่วมเทศกาลจันทราเคารพบูชาอย่างยิ่ง ข้างในกักแสงจันทร์แท้ไว้ พร้อมปลดปล่อยออกมา!\n\nแสงนี้ไม่เป็นอันตรายต่อสิ่งมีชีวิตส่วนใหญ่ แต่เมื่อส่องใส่ Omen กับสมุน แสงจะแผดเผาและทำให้พวกมันตาพร่า" },
        required = { [21100] = { "16:1072631395:1480057254", "เหรียญแห่งบรรพชน" } },
        steps = { { "16:1072631395:1480057254", "เหรียญแห่งบรรพชน" } },
    },
    [8863] = { -- Festival Dumplings
        title = { "18:1771478641:1115685108", "เกี๊ยวเทศกาล" },
        progress = { "373:1683122795:1630814466", "ถ้าหิวก็มาถูกที่แล้ว สหาย!\n\nเกี๊ยวเป็นอาหารตามธรรมเนียมของเทศกาลจันทรา มีให้กินตั้งแต่จัดเทศกาลครั้งแรก และข้ายินดีที่ได้เอามาให้ชิมในปีนี้ แลกด้วย Coin of Ancestry เพียงหนึ่งเหรียญ ข้าจะแบ่งอาหารที่อร่อยที่สุดอย่างหนึ่งที่ท่านเคยกินให้ลอง!" },
        completion = { "325:733081011:637316908", "ยอดเยี่ยม ขอให้เอร็ดอร่อยกับเกี๊ยวที่ข้ามอบให้ แม้มันเป็นเพียงของเล็กน้อยแทนคำชื่นชมในเกียรติที่ท่านสร้างด้วยการกระทำของตัวเอง ข้าก็ว่าท่านจะชอบ\n\nถ้ายังมี Coins of Ancestry อีก ข้ามีของให้เลือกแลกอีกมาก" },
    },
    [8864] = { -- Festive Lunar Dresses
        title = { "21:885715484:819114209", "ชุดกระโปรงเทศกาลจันทรา" },
        progress = { "411:1329410566:1607467113", "ข้ามีชุดกระโปรงหลายแบบที่ท่านอาจสนใจ คนสวมชุดแบบนี้ในเทศกาลจันทรามาแต่ก่อน และชุดที่ข้ามีวันนี้อาจงามที่สุดเท่าที่ข้าเคยเห็นมา แต่ละชุดตัดเย็บด้วยมือจากวัสดุชั้นดีและนุ่มที่สุด\n\nแลกด้วย Coins of Ancestry จำนวนหนึ่ง แล้วท่านเลือกเอาไปเป็นของตัวเองได้หนึ่งจากสามแบบ ตกลงไหม?" },
        completion = { "262:330125167:1021985529", "ตกลง ข้ารับ Coins of Ancestry เหล่านี้ไว้ โปรดรับชุดพร้อมพรจากข้า และขอให้สนุกกับพลุที่ข้าแถมให้ด้วย\n\nท่านให้เกียรติผู้อาวุโสมาแล้ว และเพียงท่านมาที่นี่ก็เป็นเกียรติแก่ข้า ขอบคุณ ขอให้มีความสุขกับเทศกาลจันทรา" },
    },
    [8865] = { -- Festive Lunar Pant Suits
        title = { "24:1869749267:647251682", "ชุดกางเกงเทศกาลจันทรา" },
        progress = { "431:843435670:1248392233", "ข้ายินดีบอกว่าข้ามีชุดกางเกงสำหรับงานฉลองงาม ๆ ให้ท่านเลือก แต่ต้องแลกด้วย Coins of Ancestry เท่านั้น ถ้าท่านชอบแต่งตัว ชุดพวกนี้ตรงใจแน่! รับรองว่าหาชุดแบบนี้ที่อื่นไม่ได้\n\nแลกด้วย Coins of Ancestry จำนวนหนึ่ง แล้วท่านเลือกเอาไปเป็นของตัวเองได้หนึ่งจากสามแบบ ตกลงไหม?", variants = { { "431:1038806184:306570841", "ข้ายินดีบอกว่าข้ามีชุดกางเกงสำหรับงานฉลองงาม ๆ ให้ท่านเลือก แต่ต้องแลกด้วย Coins of Ancestry เท่านั้น ถ้าท่านชอบแต่งตัว ชุดพวกนี้ตรงใจแน่! รับรองว่าหาชุดแบบนี้ที่อื่นไม่ได้\n\nแลกด้วย Coins of Ancestry จำนวนหนึ่ง แล้วท่านเลือกเอาไปเป็นของตัวเองได้หนึ่งจากสามแบบ ตกลงไหม?" } } },
        completion = { "300:2030382438:789552545", "ตกลง ข้ารับ Coins of Ancestry เหล่านี้ไว้ โปรดรับชุดกางเกงพร้อมพรจากข้า และขอให้สนุกกับพลุที่ข้าแถมให้ด้วย\n\nถ้ามี Coins of Ancestry มาแลกอีก ก็มาคุยกับข้าได้ ข้าจะนำของหลายอย่างมาให้แลกตลอดเทศกาลจันทรา" },
    },
    [8866] = { -- Bronzebeard the Elder
        completion = { "96:706180241:951112870 N 29:192134284:1515642937", "ดีใจที่ผู้คนในดินแดนนี้ยังแสดงความเคารพต่อชนเผ่าโบราณ ขอให้ท่านโชคดี {name} โปรดรับสิ่งนี้ไว้เป็นที่ระลึก..." },
        title = { "21:1937410603:200166015", "ผู้อาวุโสบรอนซ์เบียร์ด" },
    },
    [8867] = { -- Lunar Fireworks
        title = { "15:260492482:1092922589", "พลุเทศกาลจันทรา" },
        objective = { "110:1296307342:1294806230", "จุด Lunar Fireworks 8 นัด และ Cluster Fireworks 2 ชุด แล้วกลับไปหา Lunar Festival Harbinger ในเมืองหลวงแห่งใดก็ได้" },
        description = { "322:491848852:151176517 N 1:46:46", "ทุกปีเหล่าดรูอิดแห่ง Moonglade จัดงานฉลองชัยชนะครั้งใหญ่ของเมืองเราที่มีต่อภัยร้ายโบราณ\n\nเราเฉลิมฉลองภูมิปัญญาของผู้อาวุโส ร่วมงานเลี้ยงใหญ่ และแน่นอน... จุดพลุ!\n\nท่านบริจาคเพียงเล็กน้อยก็ซื้อพลุหลากสีจากพ่อค้าของเราได้ ลองใช้แท่นยิงแถวนี้ดูสิ {name}" },
        progress = { "28:1598038303:841637912 N 1:63:63", "ท่านหาแท่นยิงเจอหรือยัง {name}?" },
        completion = { "11:534428891:784080240 N 352:1128070269:1229826454", "ทำได้ดี {name}\n\nตอนนี้ท่านเริ่มสนุกกับเทศกาลแล้ว ลองรับบัตรเชิญไปงานที่ Moonglade ดูสิ\n\nถ้ามีเวลาว่าง งานนี้สนุกทีเดียว เราแบ่งอาหาร เครื่องดื่ม และเรื่องเล่ากัน และแน่นอน... ยังมีพลุอีก!\n\nเปิดบัตรเชิญขณะยืนอยู่ในวงแสงจันทร์ใหญ่ แล้วท่านจะถูกส่งไปยัง Moonglade" },
        steps = { { "21:1688146289:861190882", "จุดพลุจันทรา" }, { "29:1873988188:255234377", "จุดพลุจันทราแบบชุด" } },
    },
    [8868] = { -- Elune's Blessing
        title = { "16:1240074102:1043308171", "พรแห่งเอลูน" },
        objective = { "91:1690605467:302562706", "อัญเชิญ Omen เอาชนะมัน และรับ Elune's Blessing แล้วกลับไปหา Valadar Starsong ที่ Nighthaven" },
        description = { "428:1905415919:1675903984 N 67:996014686:773228959", "อสูร Omen เคยเป็นวีรชนของโลกนี้ มันเป็นหมาป่าที่แข็งแกร่งและมีโชค เคยต่อสู้เคียงข้างเหล่าวีรชนใน War of the Ancients จนพ่ายให้มนตร์ปีศาจ มันหันไปเล่นงานพวกพ้อง อาละวาดทั่วอาเซรอธ ทิ้งความตายและความหวาดกลัวไว้ทุกแห่งที่ผ่าน\n\nในที่สุดมันก็พ่ายแพ้ที่นี่ ใน Moonglade บัดนี้ Omen หลับใหลอยู่ในตะกอนก้นทะเลสาบ Elune'ara แต่ทุกปีใหม่เมื่อถึงเทศกาล มันจะเริ่มขยับตัว...\n\nรวบรวมสหาย {name} แล้วอัญเชิญและปราบอสูร Omen จงรับพรแห่งเอลูน!" },
        progress = { "43:1536168785:1516964818 N 3:3050122:795478", "Omen ยังขยับตัวอยู่ใต้ทะเลสาบ Elune'ara {name}..." },
        completion = { "16:2103922072:1818543247 N 204:1660519806:1271884860 N 123:1659451528:880153898", "ทำได้ดีมาก {name} เมื่อท่านปราบ Omen วิญญาณของมันก็กลับสู่ผืนน้ำแห่ง Elune'ara แม้อสูรจะได้รับพรจากเอลูนจึงไม่อาจตายได้ แต่ความโกรธของมันจะสงบลงอีกปี\n\nชัยชนะของท่านเป็นเหตุให้เราเฉลิมฉลอง {name} ทั้งเพื่อพลังของ Omen เพื่อท่านและพันธมิตร และเพื่อความสงบที่ท่านมอบให้วีรชนผู้อาภัพจากอดีตของเรา" },
    },
