        progress = { "197:1973943255:1532916390", "ข้ารู้เคล็ดลับการทำพลุจรวดเทศกาลจันทรา และยินดีแบ่งปันความรู้แก่ผู้ทรงเกียรติ\n\nแลกด้วย Coins of Ancestry แล้วข้าจะมอบสูตรทำพลุจรวดขนาดเล็กให้..." },
        completion = { "38:235494206:85201698 N 25:265730811:332428098", "อา ตกลง นี่สูตรของท่าน {name} ขอให้เอลูนอวยพร" },
    },
    [8877] = { -- Firework Launcher
        title = { "17:24268056:2128987276", "แท่นยิงพลุ" },
        progress = { "241:1059300018:953047976", "พลุจรวดช่วยให้งานฉลองสนุกขึ้นมาก แต่จะได้เห็นว่ามันงดงามเพียงใด... ก็ต้องยิงจากแท่นยิงก่อน\n\nเอา Coins of Ancestry มาให้ข้า แล้วข้าจะสอนทำแท่นยิงพลุจรวดอย่างที่เห็นใน Moonglade" },
        completion = { "14:510644690:581245021 N 142:1260262715:1786636171", "นี่ของท่าน {name} แบบแปลนสำหรับทำแท่นยิงพลุ วางแท่นในที่ที่อยากฉลอง แล้วชวนเพื่อนมาร่วมสนุก!" },
    },
    [8878] = { -- Festive Recipes
        title = { "15:102090837:318692685", "แบบตัดเย็บชุดเทศกาล" },
        progress = { "172:1908219969:2134713941 N 78:2048008509:982933620", "ชุดกระโปรงกับชุดกางเกงที่เห็นเป็นเครื่องแต่งกายตามธรรมเนียมจากหลายปีก่อน ผู้คนสวมเพื่อรำลึกถึงวิถีเดิมและคนรักที่จากไป\n\nหากนำ Coins of Ancestry มาให้ข้า {name} ข้าจะมอบแบบตัดเย็บชุดกระโปรงหรือชุดกางเกงสีแดงตามธรรมเนียมให้" },
        completion = { "23:1752714880:1431280950 N 72:657872565:790301175", "นี่แบบตัดเย็บ {name} ข้ามั่นใจว่าชุดที่ทำจากแบบเหล่านี้จะออกมางดงาม" },
    },
    [8879] = { -- Large Rockets
        title = { "13:615029602:644373444", "พลุจรวดขนาดใหญ่" },
        progress = { "133:1344824051:561791660 N 52:662509677:559397715", "พลุจรวดเทศกาลขนาดใหญ่ส่องฟ้าสว่างไสว มีเพียงพลุจรวดแบบชุดที่งดงามพอจะเทียบได้!\n\nนำ Coins of Ancestry มาให้ข้า {name} แล้วข้าจะแบ่งปันวิธีทำ" },
        completion = { "69:585696633:1656076846 N 43:1142242080:1541882114", "ตกลง ข้ารับ Coins of Ancestry เหล่านี้ไว้ นี่สูตรของท่าน {name} ขอให้ใช้มันเผยเกียรติแห่งเอลูน!" },
    },
    [8880] = { -- Cluster Rockets
        title = { "15:2051425558:1369994167", "พลุจรวดแบบชุด" },
        progress = { "170:1560791879:1594136969", "พลุจรวดแบบชุดรวมพลุจรวดหลายลูกเข้าด้วยกัน งดงามน่าทึ่งทีเดียว! นำ Coins of Ancestry มาให้ข้า แล้วข้าจะแบ่งปันวิธีทำให้..." },
        completion = { "14:510644690:581245021 N 121:119162168:1256298633", "นี่ของท่าน {name} รับสูตรเหล่านี้ไปเรียนรู้เคล็ดลับ ขอให้โชคดี ข้าตั้งตารอดูผลงานอันงดงามของท่าน" },
    },
    [8881] = { -- Large Cluster Rockets
        title = { "21:1370680555:255309411", "พลุจรวดแบบชุดขนาดใหญ่" },
        progress = { "200:948050035:1269052366", "พลุจรวดแบบชุดขนาดใหญ่ใช้ทั้งวัสดุและฝีมือมาก แต่ความสว่างไสวและความงามคุ้มแรงที่ลงไป! นำ Coins of Ancestry มาให้ข้า แล้วข้าจะถ่ายทอดวิธีทำให้ท่าน" },
        completion = { "11:1191658970:1224418299 N 115:1054662510:1428747255", "ขอบคุณ {name} นี่สูตรทำพลุจรวดแบบชุดขนาดใหญ่ ขอให้ผลงานของท่านนำความสุขและโชคดีมาสู่ทุกคนที่เงยหน้าขึ้นชม" },
    },
    [8882] = { -- Cluster Launcher
        title = { "16:125670866:2090410891", "แท่นยิงพลุแบบชุด" },
        progress = { "274:1449530638:647915827", "การแสดงพลุที่งดงามที่สุดต้องมีพลุจรวดแบบชุด และต้องยิงจากแท่นยิงพลุแบบชุดด้วย! อย่างนี้ท่านก็น่าเรียนเคล็ดลับทำแท่นยิงไว้ใช่ไหม? นำ Coins of Ancestry มาให้ข้า แล้วข้าจะถ่ายทอดความรู้นี้ให้" },
        completion = { "66:1014188661:1077569688 N 64:481514816:670790711", "นี่แบบแปลนของท่าน ศึกษาให้ถี่ถ้วนแล้วเรียนรู้เสีย...\n\nขอให้โชคดี {name} ขอให้งานฉลองของท่านงดงามทัดเทียมเทศกาลจันทรา!" },
    },
    [8883] = { -- Valadar Starsong
        title = { "16:1913037354:1968929328", "วาลาดาร์ สตาร์ซอง" },
        objective = { "134:612536425:218221113", "ใช้ Lunar Festival Invitation ขณะยืนในแสงจันทร์เพื่อเดินทางไป Moonglade เมื่อไปถึงแล้วให้คุยกับ Valadar Starsong ที่ Nighthaven" },
        description = { "373:800084834:613559374", "ตอนนี้ท่านมีบัตรเชิญเทศกาลจันทราแล้ว เดินทางไป Moonglade ได้เลย! ที่นั่นมีคนร่วมงานมากมาย และที่หมู่บ้าน Nighthaven วาลาดาร์ สตาร์ซองกับฟาเรียลผู้เป็นน้องสาวกำลังรอผู้ที่อยากร่วมฉลอง\n\nเดินทางผ่านวงแสงจันทร์ใหญ่ไป Moonglade แล้วคุยกับ Valadar Starsong ดูว่ามีรางวัลอะไรให้ท่านรับระหว่างเทศกาล!" },
        completion = { "N 224:1197409523:791196221 N 50:1949715096:72005235", "{name} ยินดีต้อนรับสู่ Nighthaven เจ้าภาพเทศกาลจันทรา! แม้ปกติหมู่บ้านของเราจะอยู่ห่างไกลและแยกจากผู้คนในอาเซรอธ แต่ในช่วงฉลองนี้เรายินดีต้อนรับทุกคนจากใจ\n\nขอให้เที่ยวให้สนุก {name} พร้อมเมื่อไรก็มาคุยกับข้าหรือฟาเรียลอีกครั้ง" },
    },
