    [7881] = { -- Carnival Boots
        title = { "14:1421570164:1727611528", "รองเท้าบูตคนงานคาร์นิวัล" },
        progress = { "416:652425233:107870384", "พวกเราที่ Darkmoon Faire เดินกันเยอะ เดินจากที่จัดงานแห่งหนึ่งไปอีกแห่ง อันที่จริงท่านไม่มีวันเห็นพวกเรานั่งอู้งานหรอก! รองเท้าเลยสึกไปหลายคู่ก็ไม่น่าแปลก เราต้องการรองเท้าบูตที่ทั้งทนและดูดี ซึ่ง Embossed Leather Boots ตรงตามที่ต้องการทีเดียว\n\nท่านนั่นแหละ! ท่านเป็นช่างทำเครื่องหนัง ทำ Embossed Leather Boots มาให้ข้า แล้วข้าจะให้ตั๋ว Darkmoon Faire ตอบแทน" },
        completion = { "11:1191658970:1224418299 N 107:1967230628:95043796", "ขอบคุณ {name} ทำมาดีทีเดียว ฝีมือชั้นยอดเลย! นี่ตั๋ว Darkmoon Faire ขอให้สนุกกับงานนะ ท่านสุภาพบุรุษ", variants = { { "11:1191658970:1224418299 N 111:1485627907:1715554869", "ขอบคุณ {name} ทำมาดีทีเดียว ฝีมือชั้นยอดเลย! นี่ตั๋ว Darkmoon Faire ขอให้สนุกกับงานนะ ท่านสุภาพสตรี" } } },
        description = { "416:652425233:107870384", "พวกเราที่ Darkmoon Faire เดินกันเยอะ เดินจากที่จัดงานแห่งหนึ่งไปอีกแห่ง อันที่จริงท่านไม่มีวันเห็นพวกเรานั่งอู้งานหรอก! รองเท้าเลยสึกไปหลายคู่ก็ไม่น่าแปลก เราต้องการรองเท้าบูตที่ทั้งทนและดูดี ซึ่ง Embossed Leather Boots ตรงตามที่ต้องการทีเดียว\n\nท่านนั่นแหละ! ท่านเป็นช่างทำเครื่องหนัง ทำ Embossed Leather Boots มาให้ข้า แล้วข้าจะให้ตั๋ว Darkmoon Faire ตอบแทน" },
    },
    [7882] = { -- Carnival Jerkins
        title = { "16:2065865119:1628587668", "เสื้อหนังคนงานคาร์นิวัล" },
        progress = { "339:120836567:52915435", "คนงานของเราไม่ได้มีหน้าที่แค่กวาดขยะกับตอกหมุด! พวกเขาช่วยคุ้มกันคณะระหว่างเดินทางด้วย จึงต้องการเสื้อเกราะแข็งแรงอยู่เสมอ\n\nถ้าท่านทำเกราะหนังทนทานมาให้ ข้าจะส่งต่อให้คนที่ต้องใช้ และจะหาตั๋ว Darkmoon Faire มาแลกกับท่านด้วย" },
        completion = { "240:650013368:1210689522 N 28:1672429917:1942428433", "อา เอาเสื้อหนังมาแล้ว ยอดเยี่ยม ขอถามหน่อยว่าท่านใช้หนังสัตว์อะไรทำ? เย็บได้เรียบร้อยมาก เนื้อหนังก็ดูสมบุกสมบัน เห็นได้ชัดว่าท่านมีฝีมือ!\n\nขอบคุณ {name} นี่ตั๋วของท่าน" },
        description = { "339:120836567:52915435", "คนงานของเราไม่ได้มีหน้าที่แค่กวาดขยะกับตอกหมุด! พวกเขาช่วยคุ้มกันคณะระหว่างเดินทางด้วย จึงต้องการเสื้อเกราะแข็งแรงอยู่เสมอ\n\nถ้าท่านทำเกราะหนังทนทานมาให้ ข้าจะส่งต่อให้คนที่ต้องใช้ และจะหาตั๋ว Darkmoon Faire มาแลกกับท่านด้วย" },
    },
    [7883] = { -- The World's Largest Gnome!
        title = { "26:712661403:1906737714", "โนมตัวใหญ่ที่สุดในโลก!" },
        progress = { "423:825320068:1144577701", "เย็บ เน็บเบิลเกียร์อยากเพิ่มนักแสดงให้โชว์ จึงออกตามหาโนมตัวใหญ่ที่สุดในโลกไปทั่ว ท่านรู้จักโนมตัวใหญ่เป็นพิเศษบ้างไหม?\n\nเขาอยากเตรียมชุดไว้ก่อนจะเจอตัว ข้าว่า Barbaric Harness น่าจะเอามาทำเป็นโครงชุดได้ ท่านทำมาให้ข้าหน่อยได้ไหม? ถ้าทำได้ ข้ามีตั๋ว Darkmoon Faire กองหนึ่งให้ท่าน..." },
        completion = { "210:1356725556:1044612908 N 38:892481317:1988107324", "โอ้โห ใหญ่เอาเรื่องเลย!! นึกไม่ออกว่าจะหาโนมตัวไหนมาใส่ได้พอดี แต่ไม่ต้องห่วง ถ้าโนมที่เราเจอตัวไม่ใหญ่พอ ข้าก็แก้ขนาดชุดได้\n\nขอบคุณมาก {name} นี่ตั๋วที่ข้ารับปากไว้" },
        description = { "423:825320068:1144577701", "เย็บ เน็บเบิลเกียร์อยากเพิ่มนักแสดงให้โชว์ จึงออกตามหาโนมตัวใหญ่ที่สุดในโลกไปทั่ว ท่านรู้จักโนมตัวใหญ่เป็นพิเศษบ้างไหม?\n\nเขาอยากเตรียมชุดไว้ก่อนจะเจอตัว ข้าว่า Barbaric Harness น่าจะเอามาทำเป็นโครงชุดได้ ท่านทำมาให้ข้าหน่อยได้ไหม? ถ้าทำได้ ข้ามีตั๋ว Darkmoon Faire กองหนึ่งให้ท่าน..." },
    },
    [7884] = { -- Crocolisk Boy and the Bearded Murloc
        title = { "36:2138367487:1879921062", "เด็กจระเข้กับเมอร์ล็อกมีเครา" },
        progress = { "299:209025096:1799712186 N 107:1560950017:526595264", "เย็บกำลังทำการแสดงใหม่ให้สวนสัตว์ของเขา รวมถึงที่อยู่แบบบึงแฉะ ๆ สำหรับเด็กชายที่โตมากับครอโคลิสก์ และอาจมีเมอร์ล็อกด้วย เราต้องใช้กางเกงรัดขากันน้ำดี ๆ จะได้ไม่เปียกชุ่มตอนจัดฉากและรื้อฉาก งานนี้ข้าว่า Turtlescale Leggings น่าจะเหมาะ\n\n{name} ท่านทำกางเกงแบบนั้นได้ไหม? ถ้าทำได้ ตั๋ว Darkmoon Faire กองโตจะเป็นของท่าน..." },
        completion = { "202:1736250619:1674639195 N 56:1719609000:1445474301", "เยี่ยม ทำมาจนได้! ใช้ได้ดีเลย... หวังว่าพอถึงเวลาจะไม่ใช่ข้าที่ต้องล้างกรงครอโคลิสก์ เจ้าสัตว์พวกนั้นดุเอาเรื่อง ท่านว่าไหม?\n\nนี่ตั๋วของท่าน {name} ขอให้ใช้ให้สนุกและเที่ยว Darkmoon Faire ให้เต็มที่!" },
        description = { "299:209025096:1799712186 N 107:1560950017:526595264", "เย็บกำลังทำการแสดงใหม่ให้สวนสัตว์ของเขา รวมถึงที่อยู่แบบบึงแฉะ ๆ สำหรับเด็กชายที่โตมากับครอโคลิสก์ และอาจมีเมอร์ล็อกด้วย เราต้องใช้กางเกงรัดขากันน้ำดี ๆ จะได้ไม่เปียกชุ่มตอนจัดฉากและรื้อฉาก งานนี้ข้าว่า Turtlescale Leggings น่าจะเหมาะ\n\n{name} ท่านทำกางเกงแบบนั้นได้ไหม? ถ้าทำได้ ตั๋ว Darkmoon Faire กองโตจะเป็นของท่าน..." },
        required = { [8185] = { "21:1973176345:937792150", "กางเกงเกล็ดเต่า" } },
        objectiveLabels = {
            item = { ["Turtle Scale Leggings"] = "กางเกงเกล็ดเต่า" },
        },
    },
    [7885] = { -- Armor Kits
        title = { "10:1318315595:882553108", "ชุดเสริมเกราะ" },
        progress = { "487:1138977280:515680354", "ท่านอาจไม่รู้ว่าการจัดคาร์นิวัลเร่ใช้เงินเยอะ! ของสึกเร็วเสียจนแปลกใจที่เรายังทำกำไรได้\n\nค่าใช้จ่ายจุกจิกพวกนี้ทำให้เราต้องหาทางดูแลอุปกรณ์ให้ประหยัดที่สุด อย่างเต็นท์เราขาดบ่อย แต่ข้าพบว่าชุดเสริมเกราะหนังใช้ปะได้ดี ท่านช่วยหามาให้ข้าหน่อยได้ไหม? จะประหยัดไปได้เยอะเลย ถ้าช่วยได้ ข้ามีตั๋ว Darkmoon Faire ให้ท่านกำหนึ่ง..." },
        completion = { "158:1297402463:230676581 N 96:1835118394:894710122", "ดีเลย! ใช้ได้พอดี! ข้าเพิ่งเห็นรอยขาดที่เต็นท์ตรงโน้น ชุดเสริมเกราะสักชุดเหมาะจะเอาไปปะเลย!\n\nขอบคุณมาก {name} ของพวกนี้จะช่วยประหยัดค่าซ่อมได้มหาศาล นี่ตั๋วของท่าน สมควรได้รับแล้ว!" },
        description = { "487:1138977280:515680354", "ท่านอาจไม่รู้ว่าการจัดคาร์นิวัลเร่ใช้เงินเยอะ! ของสึกเร็วเสียจนแปลกใจที่เรายังทำกำไรได้\n\nค่าใช้จ่ายจุกจิกพวกนี้ทำให้เราต้องหาทางดูแลอุปกรณ์ให้ประหยัดที่สุด อย่างเต็นท์เราขาดบ่อย แต่ข้าพบว่าชุดเสริมเกราะหนังใช้ปะได้ดี ท่านช่วยหามาให้ข้าหน่อยได้ไหม? จะประหยัดไปได้เยอะเลย ถ้าช่วยได้ ข้ามีตั๋ว Darkmoon Faire ให้ท่านกำหนึ่ง..." },
    },
    [7889] = { -- Coarse Weightstone
        title = { "18:1127651759:959093959", "หินถ่วงน้ำหนักเนื้อหยาบ" },
        progress = { "250:861281699:1451565157", "จะเป็นหญิงที่แข็งแรงที่สุดในโลกต้องฝึกหนักมาก! ตุ้มน้ำหนักชุดเดิมเริ่มเบาไปแล้ว ถ้าอยากรักษาร่างกายให้แข็งแรง ข้าก็ต้องมีตุ้มเพิ่ม!\n\nท่านหาหินถ่วงน้ำหนักมาให้ข้าได้ไหม? ถ้าหาได้ ข้าจะให้ตั๋ว Darkmoon Faire" },
        completion = { "134:216602417:693686923 N 36:1331107961:37905623", "เยี่ยม! ใช้ได้ดีเลย! หนักกำลังดี เบาไปก็ไม่ใช่ เหมาะกับการเพิ่มกล้ามเนื้อพอดี!\n\nขอบคุณมาก {name} นี่ตั๋ว Darkmoon Faire ของท่าน!" },
        description = { "250:861281699:1451565157", "จะเป็นหญิงที่แข็งแรงที่สุดในโลกต้องฝึกหนักมาก! ตุ้มน้ำหนักชุดเดิมเริ่มเบาไปแล้ว ถ้าอยากรักษาร่างกายให้แข็งแรง ข้าก็ต้องมีตุ้มเพิ่ม!\n\nท่านหาหินถ่วงน้ำหนักมาให้ข้าได้ไหม? ถ้าหาได้ ข้าจะให้ตั๋ว Darkmoon Faire" },
    },
    [7890] = { -- Heavy Grinding Stone
        title = { "20:1846515019:1792243186", "หินเจียรหนัก" },
        progress = { "320:2050872742:1026453680", "เวลาฝึก ข้าชอบเอาคานสอดระหว่างหินเจียรหนัก ๆ แล้วชูคานขึ้นเหนือหัว ไม่ง่ายเลย แต่จะเป็นหญิงที่แข็งแรงที่สุดในโลกอย่างข้า จะเอาแต่นั่งเฉย ๆ ได้ที่ไหน!\n\nช่วยข้าหน่อยได้ไหม? ข้าต้องการหินเจียรเพิ่ม นำมาให้แล้วข้าจะเอาตั๋ว Darkmoon Faire แลก" },
        completion = { { "96:1466095868:1524027745 N 107:1048025323:632844205 C 50:1715243285:592163912", "96:1466095868:1524027745 N 107:1048025323:632844205 C 50:1845048767:2104073410" }, "เอาหินมาแล้ว! หนักดีด้วย! ข้ารู้สึกว่ากล้ามโตขึ้นแล้ว ขอบคุณ {name}!\n\nเอ้า รับตั๋วไป แล้วอย่ากินของหวานในงานมากนักล่ะ {class}ตัวใหญ่แข็งแรงอย่างท่านต้องรักษาร่างกายให้พร้อมสู้!" },
        description = { "320:2050872742:1026453680", "เวลาฝึก ข้าชอบเอาคานสอดระหว่างหินเจียรหนัก ๆ แล้วชูคานขึ้นเหนือหัว ไม่ง่ายเลย แต่จะเป็นหญิงที่แข็งแรงที่สุดในโลกอย่างข้า จะเอาแต่นั่งเฉย ๆ ได้ที่ไหน!\n\nช่วยข้าหน่อยได้ไหม? ข้าต้องการหินเจียรเพิ่ม นำมาให้แล้วข้าจะเอาตั๋ว Darkmoon Faire แลก" },
        required = { [3486] = { "20:1846515019:1792243186", "หินเจียรหนัก" } },
        objectiveLabels = {
            item = { ["Heavy Grinding Stone"] = "หินเจียรหนัก" },
        },
    },
    [7891] = { -- Green Iron Bracers
        title = { "18:1431278195:1288411805", "ปลอกแขนเหล็กเขียว" },
        progress = { "283:428299855:1171798044 N 110:564515331:1536269", "ข้ากำลังทำชุดใหม่ไว้ใส่ตอนเปิดซุ้มแสดงตัวเป็นหญิงที่แข็งแรงที่สุดในโลก ตอนนี้อยากได้ปลอกแขนสักคู่ ต้องปิดแขนไม่มากเพราะคนอยากเห็นกล้ามข้า แต่ก็อยากให้มีสีสันสักหน่อย เข้าใจใช่ไหม?\n\nปลอกแขนเหล็กเขียวเป็นอย่างไร {name}? ทำ Green Iron Bracers ให้ข้าได้ไหม? ถ้าทำได้ ข้ามีตั๋ว Darkmoon Faire ให้ท่านกองใหญ่เลย" },
        completion = { "150:2041728497:1068808700 N 32:226666321:1000706647", "ใช่เลย! นี่แหละที่ข้าต้องการ! สีสวย แถมยังเห็นแขนข้าว่าแข็งแรงแค่ไหน! พอดีเป๊ะ!\n\nนี่ของท่าน {name} รับตั๋วไปเลย ขอให้สนุก!" },
        description = { "283:428299855:1171798044 N 110:564515331:1536269", "ข้ากำลังทำชุดใหม่ไว้ใส่ตอนเปิดซุ้มแสดงตัวเป็นหญิงที่แข็งแรงที่สุดในโลก ตอนนี้อยากได้ปลอกแขนสักคู่ ต้องปิดแขนไม่มากเพราะคนอยากเห็นกล้ามข้า แต่ก็อยากให้มีสีสันสักหน่อย เข้าใจใช่ไหม?\n\nปลอกแขนเหล็กเขียวเป็นอย่างไร {name}? ทำ Green Iron Bracers ให้ข้าได้ไหม? ถ้าทำได้ ข้ามีตั๋ว Darkmoon Faire ให้ท่านกองใหญ่เลย" },
    },
    [7892] = { -- Big Black Mace
        title = { "14:2024503114:714954748", "กระบองดำขนาดใหญ่" },
        progress = { "155:638350427:1248624294 N 1:63:63", "ในการแสดงหญิงที่แข็งแรงที่สุดในโลก ข้าจะรับสิ่งของจากคนดูมาทุบให้แหลกด้วยกระบองดำอันใหญ่!\n\nท่านทำ Big Black Mace ให้ข้าได้ไหม {name}?" },
        completion = { "193:56040214:588205678 N 31:743827139:825280970", "อา พอดีเลย! หัวกระบองใหญ่และหนัก ข้าว่าทุบได้แทบทุกอย่าง หวังแค่ว่ามันจะไม่พังไปพร้อมของที่ข้าฟาดใส่!\n\nนี่ตั๋วของท่าน {name} เที่ยวงานให้สนุกนะ!" },
        description = { "155:638350427:1248624294 N 1:63:63", "ในการแสดงหญิงที่แข็งแรงที่สุดในโลก ข้าจะรับสิ่งของจากคนดูมาทุบให้แหลกด้วยกระบองดำอันใหญ่!\n\nท่านทำ Big Black Mace ให้ข้าได้ไหม {name}?" },
    },
    [7893] = { -- Rituals of Strength
        title = { "19:382187719:1259243623", "พิธีเสริมพละกำลัง" },
        progress = { "N 359:1389339570:70469265 N 100:1650897737:544915431", "{name} เพื่อจะเป็นหญิงที่แข็งแรงที่สุดในโลก ข้าเดินทางไปทั่วเพื่อเรียนเคล็ดสร้างกล้ามเนื้อจากผู้เชี่ยวชาญการยกน้ำหนัก ปรมาจารย์ด้านพละกำลัง และตำราโบราณ ตอนนี้ข้ารู้ท่าฝึกต้องห้ามที่อาจฆ่าคนอ่อนแอและทำให้คนไร้ประสบการณ์พิการได้!\n\nการฝึกพละกำลังและความทนทานแบบนี้ต้องใช้หินเจียรเนื้อแน่นที่สุด {name} ท่านช่วยหาหรือทำหินเจียรมาให้ข้าได้ไหม? ถ้าได้ ข้าจะให้ตั๋วตอบแทน..." },
        completion = { "11:1191658970:1224418299 N 240:980018981:1241757383", "ขอบคุณ {name} ข้าจะใช้หินพวกนี้ในพิธีเสริมกำลังที่เรียนจากแผ่นจารึกโบราณในป่าลึกที่สุดของ Stranglethorn\n\nว่ากันว่าหญิงผู้ประกอบพิธีศักดิ์สิทธิ์นี้ได้ถูกต้องจะมีเรี่ยวแรงและความอึดเท่าทอเรนสิบคน!" },
        description = { "N 359:1389339570:70469265 N 100:1650897737:544915431", "{name} เพื่อจะเป็นหญิงที่แข็งแรงที่สุดในโลก ข้าเดินทางไปทั่วเพื่อเรียนเคล็ดสร้างกล้ามเนื้อจากผู้เชี่ยวชาญการยกน้ำหนัก ปรมาจารย์ด้านพละกำลัง และตำราโบราณ ตอนนี้ข้ารู้ท่าฝึกต้องห้ามที่อาจฆ่าคนอ่อนแอและทำให้คนไร้ประสบการณ์พิการได้!\n\nการฝึกพละกำลังและความทนทานแบบนี้ต้องใช้หินเจียรเนื้อแน่นที่สุด {name} ท่านช่วยหาหรือทำหินเจียรมาให้ข้าได้ไหม? ถ้าได้ ข้าจะให้ตั๋วตอบแทน..." },
    },
    [7894] = { -- Copper Modulator
        title = { "16:930122709:670957792", "ตัวปรับทองแดง" },
        progress = { "358:826859958:822745361", "เย็บกำลังทำการแสดงใหม่ให้ Zoo Bizarre ที่จะทำให้คนทึ่งและสนุกจนแทบบ้า! แต่ต้องลงแรงมากและใช้วัสดุอีกเยอะ...\n\nรวมถึงตัวปรับทองแดงด้วย เราต้องใช้หลายตัวกับชิ้นส่วนกลไกของการแสดง เอา Copper Modulator มาให้ข้า แล้วข้าจะเอาตั๋ว Darkmoon Faire แลก" },
        completion = { "145:2126728501:2031346147 N 76:1417462683:1201389450", "อ้า ตัวปรับมาแล้ว! เยี่ยม!\n\nข้าบอกไม่ได้ว่าเรากำลังสร้างอะไร แต่ของพวกนี้สำคัญกับงานมาก ข้าติดค้างท่านแล้ว {name} โปรดรับตั๋ว Darkmoon Faire ไว้แทนคำขอบคุณ" },
        description = { "358:826859958:822745361", "เย็บกำลังทำการแสดงใหม่ให้ Zoo Bizarre ที่จะทำให้คนทึ่งและสนุกจนแทบบ้า! แต่ต้องลงแรงมากและใช้วัสดุอีกเยอะ...\n\nรวมถึงตัวปรับทองแดงด้วย เราต้องใช้หลายตัวกับชิ้นส่วนกลไกของการแสดง เอา Copper Modulator มาให้ข้า แล้วข้าจะเอาตั๋ว Darkmoon Faire แลก" },
    },
    [7895] = { -- Whirring Bronze Gizmo
        title = { "21:298604570:702615924", "กลไกสำริดหมุนหึ่ง" },
        progress = { "318:765624260:612142455 N 78:293801749:79936903", "ซุ้มใหม่ของข้าจะเป็นของน่าดูแน่ รับรอง! น่าดู และ... คนโชคดีไม่กี่คนยังจะได้แตะด้วย!\n\nข้าแทบได้ยินเสียงกลไกสำริดหมุนหึ่งประสานกันอย่างไพเราะตอนแขกเข้ามาลองฝีมือที่ซุ้มแล้ว!\n\nอา... ตอนนี้ต้องหาตัวกลไกมาทำความฝันให้ใกล้จริงอีกนิด โปรดนำ Whirring Bronze Gizmo มาให้ข้า {name} แล้วตั๋ว Darkmoon Faire จะเป็นของท่าน!" },
        completion = { "194:677621978:1901942339 N 42:1070481778:1130756414", "ท่านเอากลไกมาแล้ว! ยอดเยี่ยม! ข้าได้ยินเสียงหึ่ง ๆ ของมันประสานกันในหัวแล้ว! โอ้ พอซุ้มเสร็จ มันจะเป็นสิ่งมหัศจรรย์ของโลกเลย คอยดูเถอะ!\n\nนี่ตั๋วของท่าน {name} เที่ยวงานให้สนุกนะ!" },
        description = { "318:765624260:612142455 N 78:293801749:79936903", "ซุ้มใหม่ของข้าจะเป็นของน่าดูแน่ รับรอง! น่าดู และ... คนโชคดีไม่กี่คนยังจะได้แตะด้วย!\n\nข้าแทบได้ยินเสียงกลไกสำริดหมุนหึ่งประสานกันอย่างไพเราะตอนแขกเข้ามาลองฝีมือที่ซุ้มแล้ว!\n\nอา... ตอนนี้ต้องหาตัวกลไกมาทำความฝันให้ใกล้จริงอีกนิด โปรดนำ Whirring Bronze Gizmo มาให้ข้า {name} แล้วตั๋ว Darkmoon Faire จะเป็นของท่าน!" },
    },
    [7896] = { -- Green Fireworks
        title = { "15:807753691:847681774", "พลุสีเขียว" },
        progress = { "351:329568029:1935617086 N 61:1320238432:1521406198", "พอข้าเปิดซุ้มได้เสียที ก็ต้องป่าวประกาศให้คนรู้! มีอะไรเรียกคนได้ดีกว่าพลุอีกเล่า?\n\nบางคนอาจว่ากลิ่นหม้อเดือดที่ต้มหัวศัตรูอยู่เรียกคนได้ดีกว่า แต่... แขกเรามาจากหลายเผ่า คงต้องใช้พลุนี่แหละ!\n\nเอา Green Fireworks มาให้ข้า {name} แล้วข้าจะให้ตั๋ว Darkmoon Faire กำใหญ่เลย" },
        completion = { "43:728216457:1790692404 N 192:82428639:2048162489 N 17:810868869:1716258583", "ท่านเอาพลุมาแล้ว ทำได้ดีมาก {name}! ข้าแทบอดใจรอจุดพลุประกาศให้โลกรู้ว่าซุ้มพร้อมเปิดไม่ไหว! ยังต้องรออีกนานทีเดียว แต่... พร้อมเมื่อไรก็พร้อมเมื่อนั้น จริงไหม?\n\nนี่ตั๋ว {name} ขอให้สนุก!" },
        description = { "351:329568029:1935617086 N 61:1320238432:1521406198", "พอข้าเปิดซุ้มได้เสียที ก็ต้องป่าวประกาศให้คนรู้! มีอะไรเรียกคนได้ดีกว่าพลุอีกเล่า?\n\nบางคนอาจว่ากลิ่นหม้อเดือดที่ต้มหัวศัตรูอยู่เรียกคนได้ดีกว่า แต่... แขกเรามาจากหลายเผ่า คงต้องใช้พลุนี่แหละ!\n\nเอา Green Fireworks มาให้ข้า {name} แล้วข้าจะให้ตั๋ว Darkmoon Faire กำใหญ่เลย" },
    },
    [7897] = { -- Mechanical Repair Kits
        title = { "22:1138649327:1666271922", "ชุดซ่อมกลไก" },
        progress = { "158:633534260:140082913 N 69:1023558777:1385392845", "เหตุผลใหญ่ที่สุดที่ข้ายังเปิดซุ้มไม่ได้ก็คือ... ของพังหมด! ข้าต้องใช้ชุดซ่อมกลไกซ่อมของพวกนี้!\n\nช่วยเอา Mechanical Repair Kit มาให้ข้าหน่อยได้ไหม {name}? ข้าจะเอาตั๋ว Darkmoon Faire แลกชุดซ่อม ว่าอย่างไร?" },
        completion = { "298:75873632:1536717153 N 15:1461771392:144482412", "ขอบคุณ! ทีนี้ก็เริ่มซ่อมได้เสียที\n\nคงต้องใช้ชุดซ่อมอีกเยอะและอดนอนหลายคืนกว่าของทุกอย่างจะใช้ได้ บางทีข้าก็คิดว่ากลับไปทำอาชีพล่าหัวอย่างแต่ก่อนน่าจะดีกว่า แต่... งานแฟร์ก็ดีกับข้ามาตลอด\n\nรับตั๋วไป {name} แล้วเที่ยวให้สนุก!" },
        description = { "158:633534260:140082913 N 69:1023558777:1385392845", "เหตุผลใหญ่ที่สุดที่ข้ายังเปิดซุ้มไม่ได้ก็คือ... ของพังหมด! ข้าต้องใช้ชุดซ่อมกลไกซ่อมของพวกนี้!\n\nช่วยเอา Mechanical Repair Kit มาให้ข้าหน่อยได้ไหม {name}? ข้าจะเอาตั๋ว Darkmoon Faire แลกชุดซ่อม ว่าอย่างไร?" },
    },
    [7898] = { -- Thorium Widget
        title = { "14:662888785:2114623579", "ชิ้นส่วนทอเรียม" },
        progress = { "306:1070246285:142131491 N 139:1562096954:1678550655", "เย็บ เน็บเบิลเกียร์ก็เตรียมการแสดงใหม่เหมือนข้า เน็บบอกว่ามันจะน่าทึ่งจนคนมาจากทั่วโลก... แล้วเราทุกคนจะรวยมหาศาล!\n\nเขาบอกว่าต้องใช้ชิ้นส่วนทอเรียมมาสร้าง และให้ข้าหามาให้ ว่าอย่างไร {name}? รู้ไหมว่าจะหา Thorium Widget จากไหน? ถ้าเป็นวิศวกร ท่านทำได้ไหม? อยากแลกกับตั๋ว Darkmoon Faire หรือเปล่า?", variants = { { "306:1070246285:142131491 N 139:198078419:1911062591", "เย็บ เน็บเบิลเกียร์ก็เตรียมการแสดงใหม่เหมือนข้า เน็บบอกว่ามันจะน่าทึ่งจนคนมาจากทั่วโลก... แล้วเราทุกคนจะรวยมหาศาล!\n\nเขาบอกว่าต้องใช้ชิ้นส่วนทอเรียมมาสร้าง และให้ข้าหามาให้ ว่าอย่างไร {name}? รู้ไหมว่าจะหา Thorium Widget จากไหน? ถ้าเป็นวิศวกร ท่านทำได้ไหม? อยากแลกกับตั๋ว Darkmoon Faire หรือเปล่า?" } } },
        completion = { "15:77186111:238310768 N 233:2055261013:42301176 N 47:1503203088:1311475048", "อา ขอบคุณ {name}! เย็บคงชอบชิ้นส่วนพวกนี้ ข้าไม่รู้ว่าเขาจะเอาไปทำอะไร แต่เจ้าโนมตัวน้อยนี่ฉลาดนัก ฉลาดและอาจเจ้าเล่ห์นิด ๆ...\n\nถ้าเพียงแต่เขาชอบรสเนื้อของพวกเผ่าคนละก็... คงเป็นโทรลล์ได้ดีเชียว!\n\nเอ้านี่ {name} ตกลงกันแล้วก็ต้องตามนั้น ตั๋วพวกนี้เป็นของท่าน" },
        description = { "306:1070246285:142131491 N 139:1562096954:1678550655", "เย็บ เน็บเบิลเกียร์ก็เตรียมการแสดงใหม่เหมือนข้า เน็บบอกว่ามันจะน่าทึ่งจนคนมาจากทั่วโลก... แล้วเราทุกคนจะรวยมหาศาล!\n\nเขาบอกว่าต้องใช้ชิ้นส่วนทอเรียมมาสร้าง และให้ข้าหามาให้ ว่าอย่างไร {name}? รู้ไหมว่าจะหา Thorium Widget จากไหน? ถ้าเป็นวิศวกร ท่านทำได้ไหม? อยากแลกกับตั๋ว Darkmoon Faire หรือเปล่า?" },
    },
    [7899] = { -- Small Furry Paws
        title = { "16:809316988:1723790470", "อุ้งเท้าเล็กขนฟู" },
        progress = { "271:200286714:1674003722", "บทแรกของการเรียกคนมาดูงานคือใช้ของเล่นกับของจุกจิกล่อใจ! ท่านช่วยข้าหน่อยได้ไหม?\n\nข้าต้องการ Small Furry Paw มาทำรางวัล หาได้จากพวกแมวใน Barrens หรือ Darkshore...\n\nเอาอุ้งเท้ามาให้ข้าหน่อย แล้วข้าจะเอาตั๋ว Darkmoon Faire แลก" },
        completion = { "133:175441335:463203157 N 16:747879388:37771744", "เยี่ยม ได้มาแล้ว! เราจะเอาไปทำของเล่นกับของประดับ แล้วของพวกนี้จะเรียกคนมางานได้มากขึ้น!\n\nนี่ตั๋วของท่าน {name} สมควรได้รับแล้ว!" },
        description = { "271:200286714:1674003722", "บทแรกของการเรียกคนมาดูงานคือใช้ของเล่นกับของจุกจิกล่อใจ! ท่านช่วยข้าหน่อยได้ไหม?\n\nข้าต้องการ Small Furry Paw มาทำรางวัล หาได้จากพวกแมวใน Barrens หรือ Darkshore...\n\nเอาอุ้งเท้ามาให้ข้าหน่อย แล้วข้าจะเอาตั๋ว Darkmoon Faire แลก" },
    },
    [7900] = { -- Torn Bear Pelts
        title = { "15:1415695481:14935225", "หนังหมีฉีกขาด" },
        progress = { "266:153699071:1183397481", "เด็ก ๆ ชอบของเล่น! ข้าพบว่าเด็กทุกเผ่าล้วนชอบตุ๊กตาขนนุ่มที่ทำจากหนังหมีฉีกขาด!\n\nหา Torn Bear Pelt ได้จากหมีใน Ashenvale หรือ Hillsbrad เอามาให้ข้ากองหนึ่ง แล้วรับตั๋ว Darkmoon Faire ไปกองหนึ่งเลย!" },
        completion = { "12:1864444722:318517622 N 200:1940849485:1948842071", "หนังสวยนี่ {name}! ข้าจะหาคนเย็บเป็นตุ๊กตานุ่ม ๆ หลายตัว ยัดไส้กับลงสีนิดหน่อย เด็กทั่วอาเซรอธคงอยากได้กันหมด!\n\nตั๋วหรือ? อ้อ ใช่ ค่าตอบแทนของท่าน! นี่ไง!" },
        description = { "266:153699071:1183397481", "เด็ก ๆ ชอบของเล่น! ข้าพบว่าเด็กทุกเผ่าล้วนชอบตุ๊กตาขนนุ่มที่ทำจากหนังหมีฉีกขาด!\n\nหา Torn Bear Pelt ได้จากหมีใน Ashenvale หรือ Hillsbrad เอามาให้ข้ากองหนึ่ง แล้วรับตั๋ว Darkmoon Faire ไปกองหนึ่งเลย!" },
    },
    [7901] = { -- Soft Bushy Tails
        title = { "16:98029316:583953566", "หางนุ่มขนฟู" },
        progress = { "452:1597895719:322630618", "ของที่คนให้ค่านี่น่าทึ่งจริง ๆ ลองคิดถึงไม้แท่งหนึ่งที่ติดหางขนนุ่มฟูไว้สิ ท่านกับข้าอาจมองว่าไม่ค่อยมีค่า... แต่ถ้าตั้งชื่อเท่ ๆ ให้เศษของชิ้นนั้นว่า ‘หางฟูจอมเถื่อน’ แล้วใส่กล่องสวย ๆ คนก็จะคิดว่ามันมีค่า ขยะกลายเป็นสมบัติได้เลย!\n\nหา Soft Bushy Tail จากหมาป่าใน Desolace กับ Badlands มาให้ข้า แล้วข้าจะให้ตั๋ว Darkmoon Faire" },
        completion = { "11:534428891:784080240 N 251:181826410:1141709434", "ทำได้ดี {name}! หางพวกนี้จะเป็นรางวัลชั้นดีสำหรับแขก แขกดีใจก็จะไปเล่าให้เพื่อนฟัง แล้วพาแขกมาอีก!\n\nนี่ตั๋วของท่าน! เที่ยว Darkmoon Faire ให้สนุก... แล้วอย่าลืมบอกเพื่อนเรื่องงานเราด้วย!" },
        description = { "452:1597895719:322630618", "ของที่คนให้ค่านี่น่าทึ่งจริง ๆ ลองคิดถึงไม้แท่งหนึ่งที่ติดหางขนนุ่มฟูไว้สิ ท่านกับข้าอาจมองว่าไม่ค่อยมีค่า... แต่ถ้าตั้งชื่อเท่ ๆ ให้เศษของชิ้นนั้นว่า ‘หางฟูจอมเถื่อน’ แล้วใส่กล่องสวย ๆ คนก็จะคิดว่ามันมีค่า ขยะกลายเป็นสมบัติได้เลย!\n\nหา Soft Bushy Tail จากหมาป่าใน Desolace กับ Badlands มาให้ข้า แล้วข้าจะให้ตั๋ว Darkmoon Faire" },
    },
    [7902] = { -- Vibrant Plumes
        title = { "14:967530182:1679791283", "ขนนกสีสด" },
        progress = { "496:1283228386:1825166353", "จินตนาการของคนเราน่าทึ่งนัก ทำให้เนินเล็กที่สุดดูเหมือนภูเขาใหญ่ที่สุดได้ ทำให้เงาที่ไม่มีพิษภัยดูราวกับเงาของฝันร้ายสุดสยองได้ด้วย!\n\nพวกเราที่ Darkmoon Faire เปิดโอกาสให้จินตนาการของแขกเบ่งบาน! แต่เพื่อให้จินตนาการไปได้ไกลขึ้น... บางทีก็ต้องใช้ลูกเล่นบ้าง\n\nข้าต้องการ Vibrant Plume สำหรับการแสดงอย่างหนึ่ง หาได้จากนกในถิ่นอันตรายของอาเซรอธ เอาขนมาให้ข้า แล้วท่านจะได้ตั๋วอีกหลายใบ!" },
        completion = { "145:655038968:774866565 N 124:335786148:1365223999", "อา ขนนกมาแล้ว! น่าทึ่งใช่ไหมล่ะ! ของสวยอย่างนี้จุดประกายจินตนาการได้ง่ายแน่!\n\nท่านมีน้ำใจจริง ๆ {name} รอยยิ้มของแขกตอนชมการแสดงคือค่าตอบแทนชั้นดี แต่โปรดรับตั๋วพวกนี้ไว้ด้วยเถิด" },
        description = { "496:1283228386:1825166353", "จินตนาการของคนเราน่าทึ่งนัก ทำให้เนินเล็กที่สุดดูเหมือนภูเขาใหญ่ที่สุดได้ ทำให้เงาที่ไม่มีพิษภัยดูราวกับเงาของฝันร้ายสุดสยองได้ด้วย!\n\nพวกเราที่ Darkmoon Faire เปิดโอกาสให้จินตนาการของแขกเบ่งบาน! แต่เพื่อให้จินตนาการไปได้ไกลขึ้น... บางทีก็ต้องใช้ลูกเล่นบ้าง\n\nข้าต้องการ Vibrant Plume สำหรับการแสดงอย่างหนึ่ง หาได้จากนกในถิ่นอันตรายของอาเซรอธ เอาขนมาให้ข้า แล้วท่านจะได้ตั๋วอีกหลายใบ!" },
    },
    [7903] = { -- Evil Bat Eyes
        title = { "13:213532216:2051573242", "ดวงตาค้างคาวชั่วร้าย" },
        progress = { "365:1090209622:1278849043 N 121:285773431:1380797767", "ท่านเคยเดินหาการผจญภัยในถ้ำตอนดึก ๆ ไหม? เคยหรือ? จริงสิ? งั้นท่านก็คงเคยเห็นดวงตาน่าขนลุกของค้างคาวจ้องลงมาจากที่สูง รอให้ท่านเผลอแล้วจะได้ลงมาดูดเลือด!\n\nแค่คิดก็น่ากลัวแล้วใช่ไหม? แน่อยู่แล้ว! ดวงตาค้างคาวน่ากลัวจริง ๆ!\n\nเอา Evil Bat Eye มาให้ข้าหน่อยได้ไหม {name}? ข้าอยากเอาไปใช้กับ... สิ่งที่กำลังออกแบบอยู่ สิ่งที่น่ากลัวน่ะ\n\nหาได้จากค้างคาวใน Eastern Plaguelands" },
        completion = { "105:756507669:681300890 C 93:116967016:952645576 N 33:546758846:647256804", "เยี่ยม! ได้ดวงตามาแล้ว! หวังว่าตอนล่าค้างคาวท่านจะกลัวอยู่บ้าง เพราะถ้า{class}ผู้กล้าอย่างท่านยังกลัว ดวงตาพวกนี้ต้องทำให้แขกงานเราขวัญผวาแน่\n\nรับตั๋วไปเถิด {name} ขอบคุณที่ช่วย" },
        description = { "365:1090209622:1278849043 N 121:285773431:1380797767", "ท่านเคยเดินหาการผจญภัยในถ้ำตอนดึก ๆ ไหม? เคยหรือ? จริงสิ? งั้นท่านก็คงเคยเห็นดวงตาน่าขนลุกของค้างคาวจ้องลงมาจากที่สูง รอให้ท่านเผลอแล้วจะได้ลงมาดูดเลือด!\n\nแค่คิดก็น่ากลัวแล้วใช่ไหม? แน่อยู่แล้ว! ดวงตาค้างคาวน่ากลัวจริง ๆ!\n\nเอา Evil Bat Eye มาให้ข้าหน่อยได้ไหม {name}? ข้าอยากเอาไปใช้กับ... สิ่งที่กำลังออกแบบอยู่ สิ่งที่น่ากลัวน่ะ\n\nหาได้จากค้างคาวใน Eastern Plaguelands" },
    },
