    [7937] = { -- Your Fortune Awaits You...
        title = { "26:1385334794:1803043807", "โชคของท่านรออยู่..." },
        objective = { "79:2071347884:651041843", "เดินทางไป Eastvale Logging Camp ใน Elwynn Forest เพื่อตามหาโชคของท่าน" },
        description = { "265:44088125:1634541898", "‘โชคของท่านรออยู่ที่ Eastvale’\n\nใบคำทำนายที่เซย์จยื่นให้อุ่นเล็กน้อยเมื่อสัมผัส พอกำไว้แน่น ท่านก็เห็นภาพ Eastvale Logging Camp ใน Elwynn Forest เมื่อเพ่งดูใกล้ขึ้น ท่านเห็นกองฟางอยู่ข้างคอกม้า" },
        progress = { "50:1839006439:2147091753", "กองฟางนี้ดูเหมือนกองที่เห็นในนิมิต" },
        completion = { "112:929586558:1775994536", "พอลองค้นกองฟางดูก็พบกล่องนิรภัยซ่อนอยู่ข้างใน! ดูเหมือนท่านจะพบโชคของตัวเองแล้ว!" },
    },
    [7938] = { -- Your Fortune Awaits You...
