    },
    [7946] = { -- Spawn of Jubjub
        title = { "15:270721647:1469454049", "ลูกของจั๊บจั๊บ" },
        progress = { "314:1459995314:646084180", "ดีใจจังที่จั๊บจั๊บไม่หายไปแล้ว มันชอบเบียร์ Dark Iron มาก พอข้าหมดเบียร์... มันก็หนีไปหาดื่มเพิ่ม!\n\nตอนนี้จั๊บจั๊บกลับมาแล้ว ข้าอยากได้เบียร์มากที่สุดเท่าที่จะหาได้! ไม่อยากให้มันหนีไปอีก!\n\nท่านมี Dark Iron Ale ไหม? ถ้ามี ข้าจะเอาไข่กบของจั๊บจั๊บหนึ่งฟองแลกเบียร์หนึ่งแก้ว..." },
        completion = { "11:1191658970:1224418299 N 108:695356256:300482011", "ขอบคุณ {name} นี่ไข่ของท่าน! ต้องรออีกสักพักกว่าจะฟัก แต่พอฟักแล้วท่านจะได้สัตว์เลี้ยงแสนดี!" },
        description = { "314:1459995314:646084180", "ดีใจจังที่จั๊บจั๊บไม่หายไปแล้ว มันชอบเบียร์ Dark Iron มาก พอข้าหมดเบียร์... มันก็หนีไปหาดื่มเพิ่ม!\n\nตอนนี้จั๊บจั๊บกลับมาแล้ว ข้าอยากได้เบียร์มากที่สุดเท่าที่จะหาได้! ไม่อยากให้มันหนีไปอีก!\n\nท่านมี Dark Iron Ale ไหม? ถ้ามี ข้าจะเอาไข่กบของจั๊บจั๊บหนึ่งฟองแลกเบียร์หนึ่งแก้ว..." },
        required = { [11325] = { "17:590281439:19822824", "แก้วเบียร์ Dark Iron" } },
        objectiveLabels = {
            item = { ["Dark Iron Ale Mug"] = "แก้วเบียร์ Dark Iron" },
        },
    },
    [7981] = { -- 1200 Tickets - Amulet of the Darkmoon
        progress = { "224:1745534925:883791072", "เข้ามาเลย เข้ามาเลย! ถ้ามีตั๋ว Darkmoon Faire ที่อยากแลกรางวัล ก็บอกได้เลย! ใช้ตั๋วได้หลายจำนวนแลกของรางวัลสุดมหัศจรรย์ อย่ามัวอาย มาลองกันเลย!" },
        completion = { "226:1454770123:1547663413", "นี่ไง นี่ไง! รางวัลคู่ควรกับพระราชา! ยินดีด้วย สหาย!\n\nถ้ามีตั๋วอยากแลกอีกก็บอกข้าได้เลย! ตราบใดที่ Darkmoon Faire ยังอยู่ที่นี่ ข้าก็จะรับแลกตั๋วให้ท่าน", variants = { { "227:746938668:1115942745", "นี่ไง นี่ไง! รางวัลคู่ควรกับพระราชินี! ยินดีด้วย สหาย!\n\nถ้ามีตั๋วอยากแลกอีกก็บอกข้าได้เลย! ตราบใดที่ Darkmoon Faire ยังอยู่ที่นี่ ข้าก็จะรับแลกตั๋วให้ท่าน" } } },
        title = { "37:574279089:2050680107", "ตั๋ว 1200 ใบ แลกเครื่องรางดาร์กมูน" },
    },
    [8222] = { -- Glowing Scorpid Blood
        title = { "21:1252766362:397699781", "เลือดแมงป่องเรืองแสง" },
        progress = { "295:1857568014:744466707 N 125:258658189:764110534", "ตลอดเวลาที่ทำงานในงานแฟร์ ข้าได้เรียนรู้เรื่องลูกค้ามาเยอะ นี่เกร็ดหนึ่ง ลูกค้าชอบของที่เรืองแสง! จะเป็นอะไรก็ได้ ต่อให้เป็นขาเก้าอี้หัก ถ้าทำให้เรืองแสงได้ เด็กจากไกลหลายไมล์ก็จะมากันหมดเพื่อเอาสักอัน!\n\nเพราะงั้น {name} ข้าต้องการ Glowing Scorpid Blood หาได้จากแมงป่องใน Sillithus, Blasted Lands หรือ Burning Steppes" },
        completion = { "11:1037110534:1315099288 N 152:1213804982:222000649", "ทำได้ดีมาก {name}! ขอบคุณจริง ๆ! ข้าจะเอาเลือดไปทำสี เปลี่ยนเศษของราคาถูกสารพัดให้เป็นสมบัติเรืองแสง!\n\nนี่ตั๋วของท่าน ขอบคุณอีกครั้ง!" },
        description = { "295:1857568014:744466707 N 125:258658189:764110534", "ตลอดเวลาที่ทำงานในงานแฟร์ ข้าได้เรียนรู้เรื่องลูกค้ามาเยอะ นี่เกร็ดหนึ่ง ลูกค้าชอบของที่เรืองแสง! จะเป็นอะไรก็ได้ ต่อให้เป็นขาเก้าอี้หัก ถ้าทำให้เรืองแสงได้ เด็กจากไกลหลายไมล์ก็จะมากันหมดเพื่อเอาสักอัน!\n\nเพราะงั้น {name} ข้าต้องการ Glowing Scorpid Blood หาได้จากแมงป่องใน Sillithus, Blasted Lands หรือ Burning Steppes" },
    },
    [8223] = { -- More Glowing Scorpid Blood
        completion = { "14:220978170:1597880858 N 24:639278506:328796418", "ขอบคุณอีกครั้ง {name} นี่ตั๋วของท่าน!" },
        title = { "26:218379665:1457750166", "เลือดแมงป่องเรืองแสงเพิ่มเติม" },
        progress = { "41:1064320607:2096374614 N 218:11220771:1183181644 N 133:1130737060:2129152895", "เลือดแมงป่องนั่นใช้ได้ดีมาก {name}! แค่ทำให้เป็นประกายนิดหน่อยก็เปลี่ยนของไร้ค่าให้กลายเป็นของจุกจิกล้ำค่าได้ น่าทึ่งจริง ๆ แขกชอบกันมาก และจะมีอะไรสำคัญไปกว่าความชอบล่ะ ท่านว่าไหม...\n\nท่านช่วยข้าไว้มาก {name} แม้ตอนนี้ข้าจะไม่ได้ต้องการ Glowing Scorpid Blood เพิ่มเท่าไร แต่ถ้าเอามาให้อีก ข้าก็ยังมีตั๋วให้แลก" },
        description = { "41:1064320607:2096374614 N 218:11220771:1183181644 N 133:1130737060:2129152895", "เลือดแมงป่องนั่นใช้ได้ดีมาก {name}! แค่ทำให้เป็นประกายนิดหน่อยก็เปลี่ยนของไร้ค่าให้กลายเป็นของจุกจิกล้ำค่าได้ น่าทึ่งจริง ๆ แขกชอบกันมาก และจะมีอะไรสำคัญไปกว่าความชอบล่ะ ท่านว่าไหม...\n\nท่านช่วยข้าไว้มาก {name} แม้ตอนนี้ข้าจะไม่ได้ต้องการ Glowing Scorpid Blood เพิ่มเท่าไร แต่ถ้าเอามาให้อีก ข้าก็ยังมีตั๋วให้แลก" },
    },
    [8791] = { -- The Fall of Ossirian
        title = { "20:1634956555:1415937061", "การล่มสลายของออสซิเรียน" },
        objective = { "95:1214447264:1175685061", "นำ Head of Ossirian the Unscarred ไปมอบให้ Commander Mar'alith ที่ Cenarion Hold ใน Silithus" },
        description = { "225:1309530513:1901781094", "ภัยร้ายอันน่าสะพรึงถูกปราบลงแล้ว ออสซิเรียนผู้โหดเหี้ยมพ่ายแพ้แล้ว\n\nผู้คนในคาลิมดอร์คงโล่งใจเมื่อรู้ข่าวชัยชนะนี้ นำหัวของออสซิเรียนไปมอบให้ Commander Mar'alith แห่ง Cenarion Hold" },
        progress = { "4:1110228981:147916455 N 90:1932772479:1248129849", "อา กลับมาแล้ว {name}! แถมยังครบทุกส่วนเสียด้วย มีข่าวอะไรจาก Ahn'Qiraj หรือ?" },
        completion = { "73:1590599986:377642706 N 55:1416903593:785330028", "ข้าขอมอบคำสดุดีสูงสุดแก่ท่าน และให้เลือกของทรงพลังหนึ่งชิ้น {name} ท่านทำคุณประโยชน์ใหญ่หลวงแก่ชาวคาลิมดอร์" },
    },
