    [78261] = { -- The Horn of Xelthos
        title = { "19:2054614043:1542055909", "เขาสัตว์แห่งเซลธอส" },
        objective = { "140:1304369703:1728411219", "หา The Horn of Xelthos ใน Shadowfang Keep แล้วนำไปคืนที่จุดฝากของลับของ C ใกล้ Pyrewood Village ท่านต้องทำงานนี้คนเดียว" },
        description = { "34:998696530:3822575 N 447:1650128320:1249785241", "<มีกระดาษโน้ตอยู่ในหีบ>\n\nสวัสดี {name}\n\nข้าต้องการสมบัติชื่อ The Horn of Xelthos ซึ่งอยู่ที่ไหนสักแห่งใน Shadowfang Keep\n\nปกติเข้าไปในปราสาทต้องพาคนไปช่วย แต่สำหรับงานนี้ การไม่เป็นที่สังเกตสำคัญที่สุด\n\nท่านต้องไปคนเดียว\n\nข้ามีคนรู้จักชื่อ Veenix อยู่ใน Stonetalon Mountains เขาน่าจะช่วยให้ท่านผ่านประตูลานด้านในได้ ที่เหลือขึ้นอยู่กับท่าน\n\nนำเขาสัตว์กลับมาที่นี่ แล้วค่าตอบแทนจะถูกส่งตามมาในไม่ช้า\n\n- C" },
        progress = { "24:1284825576:1651902609", "<หีบตั้งอยู่ตรงหน้า ภายในว่างเปล่า>" },
        completion = { "46:692428884:1135633055", "<เจ้าวาง The Horn of Xelthos ลงในหีบ>" },
        required = { [210183] = { "15:2105768668:1807983427", "เขาของ Xelthos" } },
        steps = { { "11:897188879:373774312", "ตามหา Veenix" } },
        objectiveLabels = {
            item = { ["Horn of Xelthos"] = "เขาของ Xelthos" },
        },
    },
    [78270] = { -- Goblin Lockpicks
        title = { "16:1994033171:324804552", "ชุดสะเดาะกุญแจของก็อบลิน" },
        objective = { "107:301310007:1808861059", "หา The Horn of Xelthos ใน Shadowfang Keep แล้วนำไปคืนที่จุดฝากของลับของ C ใกล้ Pyrewood Village" },
        description = { "40:1140430227:1645548352 N 447:1650128320:1249785241", "<มีกระดาษโน้ตอยู่ในหีบ>\n\nสวัสดีอีกครั้ง {name}\n\nข้าต้องการสมบัติชื่อ The Horn of Xelthos ซึ่งอยู่ที่ไหนสักแห่งใน Shadowfang Keep\n\nปกติเข้าไปในปราสาทต้องพาคนไปช่วย แต่สำหรับงานนี้ การไม่เป็นที่สังเกตสำคัญที่สุด\n\nท่านต้องไปคนเดียว\n\nข้ามีคนรู้จักชื่อ Veenix อยู่ใน Stonetalon Mountains เขาน่าจะช่วยให้ท่านผ่านประตูลานด้านในได้ ที่เหลือขึ้นอยู่กับท่าน\n\nนำเขาสัตว์กลับมาที่นี่ แล้วค่าตอบแทนจะถูกส่งตามมาในไม่ช้า\n\n- C" },
        progress = { "295:812097645:2133439783", "เจ้าบอกว่าจะบุกเข้า Shadowfang คนเดียวหรือ? ใจกล้าดีนี่!\n\nข้าหาวัตถุระเบิดให้เจ้าใช้ผ่านประตูได้ แต่ต้องมีใบสั่งงาน จะได้ลงบัญชีให้ดูถูกต้อง พนักงานแถวนี้น่าจะพกใบสั่งงานอยู่สักคน คงเป็นพวกที่คอยประกอบหรือซ่อมเครื่องกลอยู่บ่อย ๆ" },
        completion = { "10:350652352:125372741 N 95:2035362389:1657887882", "ทำได้ดีนี่ {name} งานแค่นี้คงง่ายสำหรับคนในวงการของเจ้า\n\nเอ้า ของที่ข้ารับปากไว้" },
        required = { [210187] = { "22:1865247295:232885642", "ใบสั่งงานของ Venture Co." } },
        objectiveLabels = {
            item = { ["Venture Co. Work Order"] = "ใบสั่งงานของ Venture Co." },
        },
    },
