    [95775] = { -- The Drowned City
        title = { "16:1749269099:427639071", "นครจมน้ำ" },
        objective = { "86:1240633558:1776800637", "ใช้หนังสัตว์กับถ่านถูเก็บลายจากแผ่นจารึกที่พบใน Drowned City" },
        description = { "45:682002014:1090812702 C 422:433728001:295583601", "สิ่งที่ข้ากำลังจะขอให้ท่านทำเป็นงานใหญ่ทีเดียว ท่าน{class} คงต้องมีพันธมิตรที่แข็งแกร่งมาช่วยจึงจะสำเร็จ\n\nข้าอยากรู้เรื่องซากเมืองอีกฟากของถ้ำที่พวกนากาเฝ้าอยู่ หากข้าคาดถูก ที่นั่นอาจเป็นนคร I'lalai ที่สาบสูญจริง ๆ เราอาจได้เข้าถึงความรู้ทางประวัติศาสตร์ที่สูญหายไปมากมายอย่างไม่เคยมีมาก่อน แต่ข้าแก่เกินจะไปเองแล้ว\n\nเข้าไปในซากเมือง เก็บลายจากแผ่นจารึกทุกแผ่นที่พบ แล้วกลับมาหาข้า" },
        completion = { "502:1050751043:679010590", "<มือของ Kin'weelay สั่นขณะรับสำเนาลายจารึกจากเจ้า>\nนี่เป็นภาษา Zandali โบราณ แต่ข้ายังอ่านได้ ศิลาจารึกสี่แผ่นนี้กล่าวถึงนครโบราณ ข้าไม่เคยได้ยินเรื่องราวในแบบนี้มาก่อน\nข้าก็ไม่เคยได้ยินเรื่องโลอาแห่งกระแสน้ำด้วย ข้าเคยคิดว่าอสรพิษทุกตัวตามขอบแผ่นจารึกคือโลอา Hethiss แต่เท่าที่ข้ารู้ ร่างอวตารของเขาไม่มีทั้งแม่เบี้ยอย่างงูเห่าและครีบ\nหรือว่านี่จะเป็นภาพของโลอาแห่งกระแสน้ำ? มันดูคล้ายอสรพิษทะเลเสียมากกว่า" },
        progress = { "N 138:2115215956:709056101", "{name}! เจ้ากลับมาโดยไม่บาดเจ็บ ดูท่าจะยังอยู่ครบเกือบทุกส่วนด้วย มานั่งก่อน เล่าให้ฟังหน่อยว่าเจ้าไปถึงซากนครจมน้ำแล้วหรือยัง?" },
        required = { [270308] = { "27:1768202320:1734852945", "แผ่นจารึกแผ่นที่ 1 แห่ง I'lalai" }, [270309] = { "28:1968463714:344933929", "แผ่นจารึกแผ่นที่ 2 แห่ง I'lalai" }, [270310] = { "27:446665557:402557681", "แผ่นจารึกแผ่นที่ 3 แห่ง I'lalai" }, [270311] = { "28:250272693:310408723", "แผ่นจารึกแผ่นที่ 4 แห่ง I'lalai" } },
        steps = { { "27:1768202320:1734852945", "แผ่นจารึกแผ่นที่ 1 แห่ง I'lalai" }, { "28:1968463714:344933929", "แผ่นจารึกแผ่นที่ 2 แห่ง I'lalai" }, { "27:446665557:402557681", "แผ่นจารึกแผ่นที่ 3 แห่ง I'lalai" }, { "28:250272693:310408723", "แผ่นจารึกแผ่นที่ 4 แห่ง I'lalai" } },
    },
    [95776] = { -- The Only Good Brinescale...
        title = { "27:1875761364:553214503", "บริเนสเกลที่ดีมีแต่..." },
        objective = { "34:952400661:1870069079", "สังหาร Var'Taka ใน Drowned City" },
        description = { "505:1422351043:210172727", "ท่านทำได้ดีที่กำจัดนากานอกชายฝั่งของเรา แต่ที่พวกมันเข้ามาในน่านน้ำเรามากขนาดนี้ แสดงว่ายังมีภัยใหญ่กว่ารออยู่\n\nข้าคุยกับคินวีเลย์แล้ว เขาคิดว่านากา Brinescale พวกนี้กำลังแทรกซึมเข้าไปในซากนครจมน้ำ ถ้าพวกมันอยู่ที่นั่นก็ต้องคิดทำเรื่องไม่ดีและคงกำลังหาอะไรอยู่\n\nเราจะปล่อยให้พวกมันได้อะไรที่อาจทำให้เราตกอยู่ในอันตรายไม่ได้ ถึงเวลาจบเรื่องนี้แล้ว สังหารผู้นำของพวกมันแล้วกลับมาหาข้า" },
        completion = { "141:913128050:275806568 C 1:46:46", "เจ้ากลับมาแล้วสินะ แปลว่าเจ้าฆ่าหัวหน้าของพวกมันได้แล้วใช่ไหม?\n\nดี เราจะได้หมดห่วงไปอีกเรื่อง ทำได้ดีมาก {class}" },
        objectiveLabels = {
            monster = { ["Var'Taka slain"] = "ปราบ Var'Taka" },
        },
    },
    [96395] = { -- An Ancient Grudge
        title = { "17:287385162:454062912", "ความแค้นแต่โบราณ" },
        objective = { "106:1536175376:1018357407", "ช่วยให้วิญญาณของ Faldrim Anvilmar ได้พักสงบ แล้วกลับไปหา Ghostly Attendant ที่ Hall of Thanes" },
        description = { "156:1562188469:2065080249", "ท่าน... เธน... ท่านเธนผู้เกรียงไกรของข้า... ท่านต้อง... พัก\n\nได้โปรด... ช่วยท่านที... ช่วยให้ท่าน... ได้พัก...\n\nถูกกลืนกิน... ด้วย... ความแค้น... แต่โบราณ... พัก... ไม่ได้..." },
        completion = { "71:1415527545:781491704", "ท่าน... เธนของข้า... ท่าน... ได้พักแล้ว... ใช่... พักแล้ว\n\nขอบ... คุณ...\n\nข้า... ได้พัก...", variants = { { "71:1418706969:1753007364", "ท่าน... เธนของข้า... ท่าน... ได้พักแล้ว... ใช่... พักแล้ว\n\nขอบ... คุณ...\n\nข้า... ได้พัก..." } } },
        progress = { "107:609584984:1026172873", "ร่างวิญญาณจ้องผ่านตัวเจ้าไปด้วยสายตาว่างเปล่า ปากของมันขยับ แต่มีเพียงเสียงแหบพร่าเบาจนฟังไม่รู้เรื่อง", variants = { { "109:726939417:293313259", "<ร่างวิญญาณมองเลยเจ้าไปด้วยสายตาว่างเปล่า ปากของมันขยับ แต่ได้ยินเพียงเสียงแหบพร่าเบาจนฟังไม่ออก>" }, { "108:1335283329:371373607", "<ร่างวิญญาณจ้องเลยตัวเจ้าไปด้วยสายตาว่างเปล่า ปากขยับ แต่มีเพียงเสียงแหบเบาจนฟังไม่รู้เรื่อง>" } } },
        objectiveLabels = {
            monster = { ["Faldrim Anvilmar slain"] = "ปราบ Faldrim Anvilmar" },
        },
    },
    [96774] = { -- Ancient Gurubashi Idol
        title = { "22:29983011:1102554127", "เทวรูปกูรูบาชิโบราณ" },
        objective = { "56:1220874033:712860366", "นำ Ancient Gurubashi Idol กลับมาจาก Drowned City" },
        description = { "492:2065065016:45051086", "พวกกูรูบาชิโบราณใน Stranglethorn Vale เชี่ยวชาญมนตร์โลหิตสายมืด ว่ากันว่าพวกมันใช้เทวรูปที่ทำจากทรูกซิลเวอร์บริสุทธิ์เป็นสื่อส่งพลังวูดูชั่วร้ายสุด ๆ\n\nมาซูคอนคนนี้อยากได้เทวรูปสักองค์... เอามาศึกษาน่ะ ลองชวนเพื่อนสักหน่อยแล้วบุกไปฉกของจากนครจมน้ำที่โผล่พ้นทะเลนอกชายฝั่ง Stranglethorn ดูไหม? ฆ่าปุโรหิตที่ดูเก่งที่สุดที่ท่านเจอในนั้น มันต้องมีของที่ข้าตามหาอยู่แน่" },
        progress = { "32:43074188:1568364334", "เป็นยังไงบ้าง เพื่อนเอ๋ย? งานเสร็จหรือยัง?" },
        completion = { "12:1370843665:1253744331 C 153:1550945730:1357347609", "ทำได้ดีมาก {class} นี่แหละของที่ข้าต้องการพอดี\n\nเรื่องซื้อขายเล็ก ๆ นี้เก็บไว้ระหว่างเรานะ Muln กับคนอื่นไม่รู้เรื่องก็ไม่มีใครเดือดร้อนหรอก!" },
        required = { [276894] = { "22:29983011:1102554127", "รูปเคารพโบราณแห่ง Gurubashi" } },
        steps = { { "22:29983011:1102554127", "รูปเคารพโบราณแห่ง Gurubashi" } },
    },
    [98072] = { -- Crocs of the Sky
        title = { "16:747194892:1508897773", "จระเข้แห่งท้องฟ้า" },
        objective = { "86:1600630289:1979815382", "เก็บ Pristine Crimson Scale 8 ชิ้น แล้วนำไปให้ James Halloran ที่ Menethil Harbor", variants = { { "87:1693352542:1536911445", "เก็บ Pristine Crimson Scale 10 ชิ้น แล้วนำไปให้ James Halloran ที่ Menethil Harbor" } } },
        description = { "478:664188258:1108016856", "ท่านนี่เอาจริงเอาจังดี! ข้ามีเรื่องอยากขออีกอย่าง ถ้าท่านพร้อมทำงานที่อันตรายขึ้นหน่อย\n\nการค้าครอโคลิสก์ทำเงินสม่ำเสมอก็จริง แต่กำไรเทียบกับเกล็ดลูกมังกรไม่ได้เลย คนยอมจ่ายแพงเพื่อให้ได้สักถุง\n\nข้าเรียกพวกมันว่าจระเข้แห่งท้องฟ้า! ลูกมือข้าไม่มีทางหามาได้หรอก แต่งานนี้ดูเหมาะกับท่านเลย!\n\nท่านจะพบลูกมังกรไกลออกไปทางตะวันออก ตามแนว Green Belt แต่ระวังไว้ มีออร์คดุร้ายอยู่ตามเนินเขา!" },
        progress = { { "37:1649411866:1583279156", "4:1110228981:147916455 N 27:1917851192:1871192342", "4:1110228981:147916455 C 27:1917851192:1871192342", "4:1110228981:147916455 R 27:1917851192:1871192342" }, "อา สหาย! ท่านได้เกล็ดพวกนั้นมาหรือยัง?" },
        completion = { "221:1305209063:1448369981", "ท่านมีพรสวรรค์จริง ๆ! ถ้าวันไหนคิดจะพักจากชีวิตนักผจญภัย ก็กลับมาหาเจมส์สหายของท่านได้เลย ข้าจะจัดงานให้ทันที!\n\nแต่ถึงตอนนั้นท่านคงอายุมากขึ้นอีก เอาเถอะ!" },
        required = { [279385] = { "22:631735908:547964271", "เกล็ดสีชาดไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Pristine Crimson Scale"] = "เกล็ดสีชาดไร้ตำหนิ" },
        },
    },
    [98372] = { -- An Unfortunate End
        title = { "18:1304833428:187455717", "จุดจบอันน่าเศร้า" },
        completion = { "357:727631728:1090574698", "ศพทหาร Night Watch ที่อยู่ตรงหน้าเจ้ามีรอยฉีกขาดและบาดแผลลึกเต็มตัว เห็นได้ชัดว่าเขาถูกสัตว์ตัวใหญ่บางอย่างขย้ำ\n\nเจ้าสังเกตเห็นคบเพลิงที่ยังไม่ได้จุดอยู่ในมือศพ จึงก้มลงงัดมันออกจากนิ้วที่แข็งทื่อ คบเพลิงนี้อาจช่วยเปิดเผยสิ่งที่ซ่อนอยู่ในความมืดระหว่างเดินทางใน Duskwood และที่อื่น" },
    },
    [99267] = { -- An Unfortunate End
        title = { "18:1304833428:187455717", "จุดจบอันน่าเศร้า" },
        completion = { "409:1158717622:1739455131", "ศพทหาร Night Watch ที่อยู่ตรงหน้าเจ้ามีรอยฉีกขาดและบาดแผลลึกเต็มตัว เห็นได้ชัดว่าเขาถูกสัตว์ตัวใหญ่บางอย่างขย้ำ\n\nเจ้าสังเกตเห็นว่าศพยังถือคบเพลิงที่ไม่ได้จุดอยู่ คงไม่ได้หยิบมันไปคราวก่อนสินะ\n\nเจ้าก้มลงงัดคบเพลิงออกจากนิ้วที่แข็งทื่อ มันอาจช่วยเผยสิ่งที่ซ่อนอยู่ในความมืดระหว่างเดินทางใน Duskwood และที่อื่น" },
    },
    [98447] = { -- The Valor Family
        title = { "16:150602505:467615853", "ตระกูลวาเลอร์" },
        objective = { "88:953873309:844442372", "หาสาเหตุที่วิญญาณตระกูล Valor ปรากฏตัวที่ Raven Hill ให้ Sirra Von'Indi ใน Darkshire" },
        description = { "497:259177272:1977129422", "ถึงเจ้าจะปราบวิญญาณตระกูล Valor ไปแล้ว แต่รายงานการโจมตียังไม่หยุด เป็นทางที่คุ้มจะลอง แต่บางทีเรื่องค้างคาของพวกเขาอาจยังไม่คลี่คลาย\n\nจากที่ข้าค้นมา ดูเหมือนคนทั้งครอบครัวจะหายตัวไปพร้อมกัน เหตุสะเทือนขวัญที่ผูกวิญญาณของพวกเขาไว้กับโลกนี้คงเกิดขึ้นในคราวเดียว\n\nเบาะแสเดียวของเราคือจุดที่เจ้าพบหนังสือ กลับไปที่ Raven Hill แล้วดูว่าจะพบอะไรบ้าง ลองนำอาวุธของพวกเขาไปด้วย อาจเกิดอะไรขึ้นก็ได้" },
        steps = { { "23:582942870:128446731", "สำรวจ Raven Hill" } },
    },
    [98096] = { -- Sisters In Duty
        title = { "15:330872531:328649796", "สองพี่น้องในหน้าที่" },
        objective = { "111:1565260011:1546211115", "ไปหา Commander Truesong ที่ Talrendis Point ใน Azshara เพื่อสอบถามว่า Keldara Sunblade อยู่ที่ไหน" },
        description = { "415:141669039:1365566330", "ข้าเข้าร่วมหน่วย Sentinels ตามพี่สาวของข้า Keldara นางประจำการอยู่ที่ Talrendis Point ใน Azshara น่าเสียดายที่ข้าไม่ได้พบนางมาพักใหญ่แล้ว\n\nถ้าพอจะไปได้ ช่วยไปดูให้นางทีได้ไหมว่ายังปลอดภัยดี? นางยังไม่ตอบจดหมายฉบับล่าสุดของข้าเลย... ข้ากลัวว่าจะเกิดเรื่องร้ายขึ้น\n\nนางอยู่ใต้บังคับบัญชาของ Commander Truesong ข้าว่าเริ่มจากไปถามเขาแล้วทำตามลำดับการบังคับบัญชาดีกว่า ข้าไม่อยากให้เจ้าต้องเดือดร้อนเพราะข้า!" },
    },
    [96109] = { -- A Hunter's Quiver
        title = { "17:694286853:698787895", "กระบอกลูกธนูของพราน" },
        objective = { "58:1312108062:589202011", "รวบรวม Prized Lion Hide 6 ผืนให้ Neza Bloodsnout ที่ Rog'mar" },
        description = { "430:908652058:999590513", "สำหรับพราน กระบอกลูกธนูสำคัญพอ ๆ กับอาวุธ กระบอกที่ดีต้องบรรจุลูกธนูได้มากโดยไม่ใหญ่จนทำให้เคลื่อนไหวช้าลง ต้องทนทานและแนบกระชับกับตัว\n\nแถวนี้ไม่มีวัสดุทำกระบอกลูกธนูที่ดีไปกว่าหนังสิงโต หนังพวกนี้เหมาะกับชีวิตพรานบนทุ่งราบอยู่แล้ว\n\nสิงโตอยู่รวมกันบนเนินทางใต้ มองเห็นได้จากตรงนี้เลย ช่วยนำหนังของพวกมันมาให้ข้าด้วย" },
        completion = { "178:1848667297:656936120", "ทั้งลูกธนู ทั้งพิษ ทั้งกระบอกใส่ลูกธนู เจ้าทำชุดอุปกรณ์ล่าสัตว์ไว้ครบเครื่องทีเดียว\nรับของตอบแทนค่าแรงเจ้าไปเถอะ ขอให้มันช่วยเจ้าได้เวลาออกไปล่า" },
        progress = { "89:796250690:2026406399", "สิงโตก็ล่าเป็นฝูงเหมือนพวกเรา ระวังตัวให้ดี อย่าปล่อยให้พวกมันล้อมเจ้าได้" },
        required = { [266888] = { "16:211034752:197613263", "หนังสิงโตชั้นดี" } },
        steps = { { "16:211034752:197613263", "หนังสิงโตชั้นดี" } },
    },
    [96108] = { -- Poison Tips
        title = { "11:1131903626:277086196", "หัวลูกธนูอาบพิษ" },
        objective = { "67:2611766:1407045210", "นำ Glade Viper Venom 4 ตัวอย่างไปให้ Neza Bloodsnout ที่ Rog'mar" },
        description = { "438:1886909069:559514449", "ลูกธนูจำเป็นเสมอ แต่บางครั้งเจ้าต้องใช้อะไรที่แรงกว่านั้นเพื่อโค่นเหยื่อ\n\nนี่แหละประโยชน์ของการเคลือบพิษ พิษทำให้เนื้อเสีย แต่ถ้าต้องการให้เหยื่อตาย มันทำงานได้ดี\n\nเจ้าจะปรุงพิษเองก็ได้ หรือถ้าใจกล้าพอก็ออกไปเก็บมา ข้าดูแล้วเจ้าน่าจะเลือกอย่างหลัง\n\nงูพิษแถวแอ่งน้ำทางใต้มีพิษร้ายแรง ถ้าข้าดูเจ้าไม่ผิด เจ้าคงเก็บพิษของมันมาได้บ้าง" },
        progress = { "84:1054580913:1096947579", "ระวังตอนเก็บพิษงูไวเปอร์ให้ดี อย่าให้ตัวเองต้องพิษเสียล่ะ" },
        completion = { "115:1939994258:1213186496", "พิษเท่านี้ฆ่าโคโดได้ในไม่กี่นาที หรือฆ่ามนุษย์ได้ในไม่กี่วินาที ไม่ว่าจะแบบไหน ข้าก็อยากลองใช้เต็มทีแล้ว" },
        required = { [271776] = { "17:1636513793:104270691", "พิษงู Glade Viper" } },
        steps = { { "17:1636513793:104270691", "พิษงู Glade Viper" } },
    },
    [96996] = { -- Your First Riding Galestrider
        title = { "29:1149880380:165489217", "เกลสไตรเดอร์ตัวแรกของเจ้า" },
        objective = { "55:1353062815:2071433127", "สำรวจเหล่าสไตรเดอร์สำหรับขี่เพื่อเลือกสัตว์ขี่ตัวแรกของเจ้า" },
        description = { "487:12106133:90665307", "เมื่อเจ้าฝึกเสร็จแล้ว ดูเหมือนสายลมจะปรารถนาให้เจ้าสร้างสายสัมพันธ์กับสไตรเดอร์ตัวแรก\n\nบรรพชนของเราขี่เกลสไตรเดอร์เหล่านี้มาหลายชั่วอายุคน แม้รูปร่างจะดูบางเบาและเพรียว แต่พวกมันเป็นสัตว์ขี่ที่ทรหดและดุดัน\n\nเจ้ากับสไตรเดอร์จะออกเดินทางไปทั่วโลกด้วยกัน นี่จึงเป็นการเลือกที่สำคัญ อย่ากังวลไป ตัวที่เจ้าเลือกจะเป็นตัวที่เหมาะกับเจ้าเอง\n\nไปดูเหล่าสไตรเดอร์แล้วกลับมาหาข้าเมื่อเลือกได้" },
        progress = { "348:88577562:1468850115", "เลือกได้หรือยัง? ว่ากันว่าสไตรเดอร์พวกนี้ได้รับพรจากสายลมเอง แต่ข้าเชื่อว่าพวกมันก็เหมือนสัตว์ส่วนใหญ่บน Zephras ที่ปรับตัวเข้ากับบ้านเกิดแห่งธาตุของเรา เพราะซึมซับพลังธาตุจาก Skywall\nแต่ใครจะรู้ บางทีอาจจริงทั้งสองอย่าง! อย่างไรเสีย เวลาขี่ตัวของข้า ข้าก็รู้สึกใกล้ชิดกับสายลมขึ้น" },
        completion = { "11:1614239848:1406166483 N 292:123230327:1121633561", "เยี่ยมมาก {name} ข้าเห็นจากแววตาว่าเจ้าเลือกได้แล้ว\n\nดูสิ ตัวที่เจ้าเลือกเหมือนจะชอบเจ้าแล้วด้วย เวลาผจญภัยไกลจาก Zephras เจ้าจะได้มีเพื่อนที่คอยเตือนให้นึกถึงบ้าน หวังว่าเจ้าจะดูแลมันดี ๆ และมันจะดูแลเจ้าเช่นกัน\n\nขอให้สายลมนำทางเจ้าทั้งคู่!" },
        steps = { { "20:320953893:695329436", "Galestrider แห่งฟากฟ้า" }, { "18:1705696334:500454801", "Galestrider แห่งพายุ" }, { "17:82649244:637755030", "Galestrider สีน้ำตาลเข้ม" } },
    },
    [96337] = { -- More Valuable Than Gold
        title = { "23:1392396067:412547960", "ล้ำค่ากว่าทอง" },
        objective = { "67:809397473:655060363", "ใช้บันทึกที่ Mason Connery มอบให้ตามหาสมบัติที่เขาซ่อนไว้" },
        description = { "365:1939371634:15024310", "ข้าบอกแล้วว่าจะตอบแทนให้คุ้มที่เจ้าช่วยปล่อยข้า ข้าไม่มีทองให้ แต่มีของที่ดีกว่านั้น\n\nเอานี่ไป มันจะช่วยเจ้าหาสมบัติที่ล้ำค่ากว่าทอง จะทำอะไรกับมันก็ตามใจ แต่ถ้ามีใครถามว่าได้มาจากไหน ให้บอกว่าคนที่ให้เจ้ามาตายไปแล้ว\n\nบอกว่าเขาโดนไฟมังกรเผาจนสลาย... แล้วถูกซัดออกทะเล" },
        steps = { { "29:724134273:840275988", "ตามหาสมบัติของ Mason Connery" } },
    },
    [97884] = { -- Armory of Sunnyglade
        title = { "20:595371533:2021957107", "คลังอาวุธแห่งซันนีเกลด" },
        objective = { "105:1171684683:649316832", "เดินทางไป Sunnyglade ใน Riverglades และนำตำรา Tremayne Family Blacksmithing Techniques กลับมา" },
        description = { "37:955090951:590545582 R 373:490801100:945072712", "เจ้าดูเป็น{race}ที่แข็งแรงและคล่องแคล่ว ข้ากำลังหาคนเดินทางไป Sunnyglade ใน Riverglades ทางเหนือของ Redridge Mountains พอดี\n\nครั้งหนึ่งครอบครัวข้าเคยมีคลังอาวุธอยู่ที่นั่น ตอนนี้คงเหลือแต่ซากไหม้เกรียม แต่ข้าอยากให้เจ้านำตำราวิธีตีเกราะที่สืบทอดกันมาในตระกูลกลับมา เดิมเก็บไว้ในห้องใต้ดิน หวังว่าลมฟ้าอากาศจะยังไม่ทำให้มันผุพัง", variants = { { "435:92832342:1492342560", "ถ้ามองตามสภาพแล้ว เจ้าดูเป็นฟอร์เซเคนที่ร่างยังอยู่ในสภาพดีทีเดียว ข้ากำลังหาคนเดินทางไป Sunnyglade ใน Riverglades ทางเหนือของ Redridge Mountains พอดี\n\nครั้งหนึ่งครอบครัวข้าเคยมีคลังอาวุธอยู่ที่นั่น ตอนนี้คงเหลือแต่ซากไหม้เกรียม แต่ข้าอยากให้เจ้านำตำราวิธีตีเกราะที่สืบทอดกันมาในตระกูลกลับมา เดิมเก็บไว้ในห้องใต้ดิน หวังว่าลมฟ้าอากาศจะยังไม่ทำให้มันผุพัง" } } },
        progress = { "392:1554761494:480514572", "อา เจ้ากลับมาแล้ว เอาตำราของครอบครัวข้าคืนมาได้ไหม? Sunnyglade เป็นอย่างไรบ้าง?\nครั้งสุดท้ายที่เห็นบ้านเกิด มันกำลังถูกเผาจนเป็นเถ้าถ่าน\nข้าเข้ากองทัพ Stormwind เดินทางขึ้นมาถึง Lordaeron แล้วก็ตายในสงครามครั้งที่สอง จึงไม่มีโอกาสกลับไปอีก ข้าได้ยินว่ามีคนพยายามสร้าง Sunnyglade ขึ้นใหม่ แต่ไม่รู้ว่าทำสำเร็จหรือเปล่า" },
        completion = { "11:1191658970:1224418299 C 324:933715938:997696507", "ขอบใจเจ้า {class} จากสภาพของ Sunnyglade ที่เจ้าเล่า ข้าไม่แน่ใจว่าตัวเองจะรอดทั้งระหว่างทางและเมื่อไปถึง\n\nตำรานี่แหละที่ข้าต้องการ ดีจริง ๆ ที่หน้าหนังสือยังอยู่ครบ\n\nบางทีข้าอาจหัดทำอาชีพใหม่ได้แม้ตายไปแล้ว อย่างน้อยก็มีฝีมือสักอย่างให้ฝึกไปตลอดชีวิตหลังความตาย" },
        required = { [278868] = { "40:1700927351:538416196", "เทคนิคตีเหล็กของตระกูล Tremayne" } },
        steps = { { "40:1700927351:538416196", "เทคนิคตีเหล็กของตระกูล Tremayne" } },
    },
    [96771] = { -- Vengeance of the Highborne
        title = { "26:159931328:1843082222", "การล้างแค้นของไฮบอร์น" },
        objective = { "57:94636863:718275836", "เดินทางไป Krol'dok Stronghold และสังหาร Zalfan Moonshadow" },
        description = { "483:69646121:245551763", "ในแถบ Riverglades ทางตะวันออกเฉียงใต้มีสถานที่ชื่อ Krol'dok Stronghold มีคนเห็นไฮบอร์นนาม Zalfan Moonshadow อยู่ที่นั่นกับพวก Twilight's Hammer\n\nข้ายินดีจ่ายงามหากเจ้าช่วยกำจัดเจ้าคนต่ำช้านี่ให้พ้นโลก มันทำให้สายเลือดอันทรงเกียรติของไฮบอร์นเสื่อมเสีย ด้วยการคบค้ากับพวกคลั่งลัทธิและใช้วิชาอาคมที่ขโมยมาเพื่อรับใช้พวกนั้น พวกเราเหลือกันน้อยพออยู่แล้ว ยังจะมีหนอนบ่อนไส้อย่างมันมาทำลายชื่อเสียงอีก" },
        completion = { "11:1191658970:1224418299 C 72:3823626:1323016008", "ขอบใจ {class} เจ้าช่วยข้าไว้มาก และกำจัดไอ้สารเลวทรยศให้พ้นโลกไปได้" },
        objectiveLabels = {
            monster = { ["Zalfan Moonshadow slain"] = "ปราบ Zalfan Moonshadow" },
        },
    },
    [96989] = { -- Your First Riding Raptor
        title = { "24:1175820950:1351206642", "แร็ปเตอร์ขี่ตัวแรกของเจ้า" },
        objective = { "54:983943018:2132642766", "สำรวจแร็ปเตอร์สำหรับขี่เพื่อเลือกสัตว์ขี่ตัวแรกของเจ้า" },
        description = { "500:1019791936:575135515", "ว่าไงพวก! วันนี้เป็นวันสำคัญของเจ้าเลยนี่ คิดว่าพร้อมจะจับบังเหียนสัตว์ดุพวกนี้แล้วหรือ?\n\nคนส่วนใหญ่ประเมินความฉลาดและความดุร้ายของสัตว์พวกนี้ต่ำไป เมื่อเจ้าผูกพันกับมันแล้ว จะหาคู่หูที่ดีกว่า เร็วกว่า หรือร้ายกาจกว่านี้ยากนัก\n\nเจ้ามีเรื่องสำคัญให้เลือก เจ้ากับแร็ปเตอร์จะเดินทางไปทั่วโลกด้วยกัน และมันเองก็ต้องเลือกเจ้าด้วย\n\nไปดูเถอะ แล้วกลับมาหาข้าเมื่อเลือกได้", variants = { { "556:1259257100:629165844", "ว่าไง วอร์ล็อก! ข้าแปลกใจนะที่คนมีฝีมืออย่างเจ้ามาถึงคอกสัตว์ของข้า\n\nถ้าเจ้ากำลังหาสัตว์ขี่ก็มาถูกที่แล้ว ถึงพวกมันจะต่างจากเฟลสตีดที่เจ้าคุ้นเคยกับการอัญเชิญก็เถอะ\n\nถ้าอยากได้สักตัว ก็เชิญไปดูแร็ปเตอร์ของเรา คนส่วนใหญ่ประเมินความฉลาดและความดุร้ายของสัตว์พวกนี้ต่ำไป เมื่อเจ้าผูกพันกับมันแล้ว จะหาคู่หูที่ดีกว่า เร็วกว่า หรือร้ายกาจกว่านี้ยากนัก\n\nไปดูซิว่ามีตัวไหนถูกใจ แล้วกลับมาหาข้าเมื่อเลือกได้" } } },
        completion = { "266:1035702516:1726854014", "อา ดี ข้าเห็นจากแววตาว่าเจ้าเลือกได้แล้ว และเลือกได้ดีด้วย\nตัวที่เจ้าเลือกดูจะชอบเจ้าเสียแล้ว ข้าก็ไม่แปลกใจหรอก หวังว่าเจ้าทั้งคู่จะดูแลกันให้ดีเมื่อออกไปผจญโลกกว้าง\nขอพรแห่ง Gonk จงติดตามเจ้าทั้งสองไป" },
        steps = { { "21:769420741:1248170812", "แร็ปเตอร์สำหรับขี่สีเขียวมรกต" }, { "23:1381044370:410510484", "แร็ปเตอร์สำหรับขี่สีฟ้าอมเขียว" }, { "20:1092361989:679161823", "แร็ปเตอร์สำหรับขี่สีม่วง" } },
    },
    [96997] = { -- A Steed in Death as They Were in Life
        title = { "37:1882861561:2031482809", "อาชาในความตาย ดั่งเมื่อยังมีชีวิต" },
        objective = { "60:1581656945:371550769", "สำรวจม้าอันเดดสำหรับขี่เพื่อเลือกสัตว์ขี่ตัวแรกของเจ้า" },
        description = { "11:927657569:725753248 C 462:977456203:1009283037", "สวัสดี {class} ข้าพอเดาได้ว่าอะไรพาเจ้ามาถึงคอกม้าของข้าวันนี้\n\nถ้ากำลังหาสัตว์ขี่ เจ้ามาถูกที่แล้ว แต่ขอเตือนไว้ก่อน การขี่อาชาอันเดดต้องใช้ความกล้า\n\nเจ้าจึงมีเรื่องสำคัญให้เลือก ไม่ว่าจะดีหรือร้าย เจ้ากับอาชาอันเดดจะเดินทางไปทั่วโลกด้วยกัน ไม่ต้องกลัว ไม่ว่าเจ้าจะเลือกตัวไหน นั่นก็เป็นตัวที่เหมาะกับเจ้า\n\nไปดูม้าอันเดดแล้วกลับมาหาข้าเมื่อเลือกได้", variants = { { "566:600576289:530052988", "สวัสดี พาลาดิน ข้าแปลกใจจริง ๆ ที่เห็นคนในคณะของเจ้ามาถึงคอกม้าของข้า\n\nถ้ากำลังหาสัตว์ขี่ เจ้ามาถูกที่แล้ว ถึงพวกมันอาจสู้ม้าศึกที่เจ้าคุ้นเคยไม่ได้\n\nอย่างไรก็ลองไปดูอาชาของเราหากอยากได้สักตัว พวกมันเป็นอาชาชั้นดีของดินแดนนี้ แม้เจ้าจะเปล่งพลังศักดิ์สิทธิ์ออกมา พวกมันก็น่าจะให้เจ้าขี่ได้อย่างซื่อสัตย์และไม่มีปัญหา\n\nไปดูม้าอันเดดว่ามีตัวไหนถูกใจ แล้วกลับมาหาข้าเมื่อเลือกได้" }, { "711:1728087743:1096834274", "สวัสดี วอร์ล็อก ข้าแปลกใจจริง ๆ ที่เห็นคนมีฝีมืออย่างเจ้ามาถึงคอกม้าของข้า\n\nถ้ากำลังหาสัตว์ขี่ เจ้ามาถูกที่แล้ว ถึงพวกมันอาจสู้เฟลสตีดที่เจ้าคุ้นเคยกับการอัญเชิญไม่ได้\n\nอย่างไรก็ลองไปดูอาชาของเราหากอยากได้สักตัว พวกมันเป็นอาชาชั้นดีของดินแดนนี้ และน่าจะให้เจ้าขี่อย่างซื่อสัตย์ไม่ต่างจากเฟลสตีดอเวจีที่เจ้าอัญเชิญมา\n\nแต่ข้าแนะนำว่าอย่าจุดไฟเผาม้าโครงกระดูกเลย เก็บรูปลักษณ์แบบนั้นไว้ให้สัตว์อัปมงคลที่เจ้ากับคณะเรียกมาจะดีกว่า\n\nไปดูม้าอันเดดว่ามีตัวไหนถูกใจ แล้วกลับมาหาข้าเมื่อเลือกได้" } } },
        progress = { "453:259399915:933086624", "เลือกได้หรือยัง? พวกนี้เคยเป็นม้าชั้นยอดของ Lordaeron ตอนนี้พวกมันรับใช้เราในความตายเช่นเดียวกับตอนยังมีชีวิต\nไม่มีชีวิตจริง ๆ เหลืออยู่ในตัวพวกมันแล้ว แต่พวกมันยังมีนิสัยเป็นของตัวเองเหมือนเจ้าและข้า\nมีเพียงเงาสะท้อนของชีวิตเหลืออยู่ พวกมันจึงไม่วิ่งหนีเมื่อเผชิญอันตราย และจะอยู่เคียงข้างเจ้าอย่างซื่อสัตย์จนกว่าจะตายอย่างแท้จริง\nเป็นคู่หูที่เหมาะกับพวกเราอย่างยิ่ง" },
        completion = { "11:1614239848:1406166483 C 403:1147451159:1391492348", "เยี่ยมมาก {class} ข้าเห็นว่าเจ้าเลือกได้แล้ว\n\nสัตว์มากมายย่อมตายและเหี่ยวเฉา แต่อาชาอัปมงคลตัวนี้เดินทางได้โดยไม่ต้องหยุดพักหรือกินอาหาร ถึงอย่างนั้นก็ช่วยดูแลมันดี ๆ ระหว่างเดินทาง หวังว่ามันจะดูแลเจ้าตอบแทน\n\nแม้มันจะตายแล้ว สายสัมพันธ์ของเจ้ากับมันก็เป็นของจริง ต่อให้เราตายไปแล้ว เราทุกคนก็ต้องค้นหาจุดหมายของตัวเอง\n\nขอให้การผจญภัยของเจ้าราบรื่น ขอ Dark Lady คุ้มครองเจ้าทั้งคู่" },
        steps = { { "18:179085096:1097652166", "ม้าโครงกระดูกสีแดง" }, { "20:1803384284:626098640", "ม้าโครงกระดูกสีน้ำตาล" }, { "19:1480940347:657905540", "ม้าโครงกระดูกสีน้ำเงิน" }, { "20:1843765555:236659115", "ม้าโครงกระดูกสีดำ" } },
    },
    [97017] = { -- Your First Riding Ram
        title = { "21:1059832630:402912590", "แกะเขาใหญ่ตัวแรกของเจ้า" },
        objective = { "51:988638883:176610738", "สำรวจแกะเขาใหญ่สำหรับขี่เพื่อเลือกสัตว์ขี่ตัวแรกของเจ้า" },
        description = { "489:1879239702:495418807", "อา วันนี้เป็นวันสำคัญสินะ มาหาแกะเขาใหญ่ตัวแรกของเจ้าหรือ?\n\nแกะพวกนี้มั่นคงและแข็งแกร่งที่สุดใน Azeroth พวกมันปกป้องคนขี่สุดกำลัง เชื่อเถอะ เจ้าจะหาคู่หูที่ทรหดกว่านี้มาเดินทางด้วยได้ยาก\n\nเจ้ามีเรื่องสำคัญให้เลือก เจ้ากับแกะจะเดินทางไปทั่วโลกด้วยกัน เลือกให้ดีล่ะ ไม่ต้องกังวลไอ้หนุ่ม ไม่ว่าเจ้าจะเลือกตัวไหน นั่นก็เป็นตัวที่เหมาะกับเจ้า\n\nไปดูเหล่าแกะแล้วกลับมาหาข้าเมื่อเลือกได้", variants = { { "595:95465225:2111960101", "หวัดดี พาลาดิน ข้าแปลกใจจริง ๆ ที่เห็นคนในคณะของเจ้ามาถึงคอกสัตว์ของข้า\n\nถ้ากำลังหาสัตว์ขี่ เจ้ามาถูกที่แล้ว ถึงพวกมันอาจสู้ม้าศึกที่เจ้าคุ้นเคยไม่ได้\n\nอย่างไรก็ลองไปดูแกะเขาใหญ่ชั้นดีของเราหากอยากได้สักตัว แกะพวกนี้มั่นคงและแข็งแกร่งที่สุดใน Azeroth พวกมันปกป้องคนขี่สุดกำลัง เชื่อเถอะ เจ้าจะหาคู่หูที่ทรหดกว่านี้มาเดินทางด้วยได้ยาก\n\nไปดูว่ามีตัวไหนถูกใจ แล้วกลับมาหาข้าเมื่อเลือกได้" } } },
        completion = { "55:883470682:748761563 N 262:1249296528:365673602", "อ้อ ตัวนั้นเป็นคู่หูที่ดีเลย มันจะช่วยเจ้าได้มากทีเดียว {name}\n\nข้าภูมิใจที่ได้ส่งเจ้าออกเดินทางพร้อมแกะเขาใหญ่ตัวนี้ ดูท่าตัวที่เจ้าเลือกจะชอบเจ้าแล้วด้วย หวังว่าเจ้าจะดูแลมันดี ๆ และมันจะดูแลเจ้าเช่นกัน\n\nอย่าลืมแวะมาบ้างล่ะ! ข้าอยากฟังเรื่องที่เจ้าทั้งคู่ได้ไปผจญภัยด้วยกัน" },
        steps = { { "9:698325421:1014412114", "แกะเขาโค้งสีขาว" }, { "9:1758218364:1740737116", "แกะเขาโค้งสีน้ำตาล" }, { "8:297055111:1263868363", "แกะเขาโค้งสีเทา" } },
    },
    [97046] = { -- Your First Mechanostrider
        title = { "25:1491676437:169787126", "เมคาโนสไตรเดอร์ตัวแรกของเจ้า" },
        objective = { "62:2131427462:793396267", "สำรวจเมคาโนสไตรเดอร์สำหรับขี่เพื่อเลือกสัตว์ขี่ตัวแรกของเจ้า" },
        description = { "489:1633802427:2082325100", "สวัสดี! ดูท่าวันนี้จะเป็นวันสำคัญจริง ๆ วันนี้เจ้าจะเชื่อมข้อมูลชีวมิติของตัวเองเข้ากับระบบตรวจจับผู้ขี่ของเมคาโนสไตรเดอร์ตัวแรก! ระบบนี้ช่วยให้มันแยกเจ้าออกจากคนอื่นที่อาจมาขี่ได้\n\nเจ้ามีเรื่องสำคัญให้เลือก เจ้ากับสไตรเดอร์จะเดินทางไปทั่วโลกด้วยกัน เลือกให้ดีล่ะ ไม่ต้องกังวล ไม่ว่าเจ้าจะเลือกตัวไหน นั่นก็เป็นตัวที่เหมาะกับเจ้า\n\nไปดูเหล่าเมคาโนสไตรเดอร์แล้วกลับมาหาข้าเมื่อเลือกได้", variants = { { "644:2098865895:2071569536", "สวัสดี วอร์ล็อก! ข้าแปลกใจจริง ๆ ที่เห็นคนมีฝีมืออย่างเจ้ามาที่นี่ แต่เงินของเจ้าก็ยินดีต้อนรับเสมอ\n\nถ้ากำลังหาสัตว์ขี่ เจ้ามาถูกที่แล้ว ถึงตอนขี่จะให้ความรู้สึกต่างจากเฟลสตีดที่เจ้าคุ้นเคยกับการอัญเชิญแน่นอน\n\nถ้าสนใจก็เชิญดูเมคาโนสไตรเดอร์รุ่นล่าสุดของเรา หากถูกใจตัวไหนก็บอกข้า เราจะเชื่อมข้อมูลชีวมิติของเจ้าเข้ากับระบบตรวจจับผู้ขี่ ระบบนี้จะช่วยให้มันแยกเจ้าออกจากคนอื่นที่อาจมาขี่ได้\n\nไปดูเหล่าเมคาโนสไตรเดอร์แล้วมาบอกข้าว่ามีตัวไหนถูกใจ!" } } },
        completion = { "11:1614239848:1406166483 N 271:1946260439:1461602613", "ยอดเยี่ยม {name} ยอดเยี่ยมจริง ๆ! เจ้าเลือกได้ดีมาก\n\nตั้งค่าระบบชีวมิติเรียบร้อยแล้ว ดูท่าว่าเมคาโนสไตรเดอร์จะอยากเริ่มเดินระบบเต็มที หวังว่าเจ้าทั้งคู่จะดูแลกันและกันเมื่อออกไปในโลกกว้าง!\n\nถ้าต้องปรับเครื่องเมื่อไร ก็กลับมาหาข้าได้!" },
        steps = { { "24:1218497498:1785193258", "Mechanostrider ที่ยังไม่ได้ทาสี" }, { "20:1406459808:246821509", "Mechanostrider สีเขียว" }, { "19:258131135:1036809260", "Mechanostrider สีน้ำเงิน" }, { "18:1103759531:1476555886", "Mechanostrider สีแดง" } },
    },
    [97074] = { -- Learning to Ride
        title = { "16:138327183:488009726", "หัดขี่สัตว์" },
        objective = { "47:585120719:880562881", "เรียนทักษะ Apprentice Riding จาก Jartsam" },
        description = { "7:989913233:66981971 C 493:453501595:211095140", "สวัสดี {class}! ดูเหมือนเจ้าจะผ่านการผจญภัยมามากพอแล้ว ข้าสอนเจ้าขี่เสือเซเบอร์ได้ มีค่าเรียนตามธรรมเนียมนะ\n\nเมื่อฝึกกับข้าแล้ว Lelanai จะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ โลกนี้มีสัตว์ขี่อีกหลายชนิด แต่ละชนิดต้องใช้ทักษะต่างกัน เจ้าต้องหาครูฝึกให้ตรงกับสัตว์ที่อยากขี่\n\nมาคุยกับข้าเมื่อมีเงินพอ แล้วข้าจะสอนทุกอย่างที่รู้เกี่ยวกับการขี่เสือเซเบอร์" },
        completion = { "11:927657569:725753248 C 92:1300683428:2073556263", "สวัสดี {class}! ดีใจที่เห็นเจ้าฝึกกับ Jartsam จนจบ ดีจริง ๆ ที่เขาส่งเจ้ามาหาข้า!" },
        progress = { "167:440382507:1455402468", "พอขี่เสือเซเบอร์เป็นแล้ว เจ้าจะออกเดินทางไปทั่วโลกพร้อมสัตว์ขี่ของเจ้าได้เลย!\nข้ารับรองว่าเร็วกว่าวิ่งไปทุกที่แน่นอน" },
        steps = { { "24:1857109559:1009967372", "เรียนทักษะขี่สัตว์ขั้นฝึกหัด (Apprentice Riding)" } },
    },
    [97018] = { -- Learning to Ride
        title = { "16:138327183:488009726", "หัดขี่สัตว์" },
        objective = { "55:1244595536:399417528", "เรียนทักษะ Apprentice Riding จาก Ultham Ironhorn" },
        description = { "7:989913233:66981971 C 474:1252416088:760039098", "สวัสดี {class}! ดูท่าเจ้าจะผจญภัยมามากพอให้ข้าสอนขี่แกะเขาใหญ่แล้วล่ะ มีค่าเรียนตามธรรมเนียมนะ\n\nฝึกกับข้าเสร็จแล้ว Veron จะให้สัตว์ขี่เจ้าฟรีหนึ่งตัว จากนั้นอยากซื้อเพิ่มก็ตามสบาย โลกนี้มีสัตว์ขี่อยู่หลายชนิด แต่ละชนิดใช้ทักษะต่างกัน เจ้าต้องไปหาครูฝึกของแต่ละชนิดเอง\n\nมีเงินพอเมื่อไรก็มาคุยกับข้า แล้วข้าจะสอนทุกอย่างที่รู้เกี่ยวกับการขี่แกะเขาใหญ่" },
        completion = { "10:1352482459:1892133479 C 95:1296949864:1107326508", "อ้าว ว่าไง {class}! ดีใจที่เห็นเจ้าฝึกกับตา Ultham จนจบ ดีจริง ๆ ที่เขาส่งเจ้ามาหาข้า!" },
        steps = { { "24:1857109559:1009967372", "เรียนทักษะขี่สัตว์ขั้นฝึกหัด (Apprentice Riding)" } },
    },
    [97170] = { -- Learning to Ride
        title = { "16:138327183:488009726", "หัดขี่สัตว์" },
        objective = { "53:1115154148:1837397965", "เรียนทักษะ Apprentice Riding จาก Randal Hunter" },
        description = { "7:989913233:66981971 C 492:231821224:1993056673", "สวัสดี {class}! ดูเหมือนเจ้าจะผ่านการผจญภัยมามากพอให้ข้าสอนขี่ม้าแล้ว แน่นอนว่ามีค่าเรียน\n\nเมื่อฝึกกับข้าแล้ว Katie จะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นหากอยากได้เพิ่มก็ซื้อได้ โลกนี้มีสัตว์ขี่อีกหลายชนิด แต่ละชนิดต้องใช้ทักษะเฉพาะ เจ้าต้องหาครูฝึกของแต่ละชนิดเอง\n\nเมื่อมีเงินพอแล้วมาคุยกับข้า ข้าจะสอนทุกอย่างที่รู้เกี่ยวกับการขี่ม้า" },
        completion = { "7:989913233:66981971 C 91:1579994926:1949453506", "สวัสดี {class}! ดีใจที่เห็นเจ้าฝึกกับ Randal จนจบ ดีจริง ๆ ที่เขาส่งเจ้ามาหาข้า!" },
        steps = { { "24:1857109559:1009967372", "เรียนทักษะขี่สัตว์ขั้นฝึกหัด (Apprentice Riding)" } },
    },
    [97188] = { -- Learning to Ride
        title = { "16:138327183:488009726", "หัดขี่สัตว์" },
        objective = { "60:1751312151:1844587399", "เรียนทักษะ Apprentice Riding จาก Binjy Featherwhistle" },
        description = { "11:927657569:725753248 C 487:1002926308:2062328420", "สวัสดี {class}! เจ้ามีประสบการณ์ผจญภัยมากพอให้ข้าสอนควบคุมเมคาโนสไตรเดอร์แล้ว แน่นอนว่ามีค่าฝึก\n\nเมื่อฝึกกับข้าแล้ว Milli จะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นจะซื้อเพิ่มก็ได้ตามใจ โลกนี้มีสัตว์ขี่อีกหลายชนิด แต่ละชนิดต้องใช้ทักษะต่างกัน เจ้าต้องหาครูฝึกให้ตรงกับชนิดที่อยากขี่\n\nมีทองพอแล้วมาคุยกับข้า แล้วข้าจะสอนวิธีขี่เมคาโนสไตรเดอร์ให้!" },
        completion = { "7:989913233:66981971 C 101:1273620543:1082247189", "สวัสดี {class}! ดีใจที่เห็นเจ้าฝึกกับ Binjy พี่น้องของข้าจนจบ ดีจริง ๆ ที่เขาส่งเจ้ามาหาข้า!" },
        steps = { { "24:1857109559:1009967372", "เรียนทักษะขี่สัตว์ขั้นฝึกหัด (Apprentice Riding)" } },
    },
    [97194] = { -- Learning to Ride
        title = { "16:138327183:488009726", "หัดขี่สัตว์" },
        objective = { "46:1593495408:1682521950", "เรียนทักษะ Apprentice Riding จาก Kildar" },
        description = { "8:567378219:981289421 C 478:1904965192:1208182521", "Mok'ra, {class} เจ้าผ่านการผจญภัยมามากพอให้ข้าสอนขี่หมาป่าของเราแล้ว แน่นอนว่ามีค่าเรียน\n\nเมื่อฝึกกับข้าแล้ว Ogunaro จะให้สัตว์ขี่เจ้าฟรีหนึ่งตัว ถ้าอยากได้เพิ่มก็ซื้อได้ โลกนี้มีสัตว์ขี่อยู่หลายชนิด แต่ละชนิดต้องใช้ทักษะต่างกัน เจ้าต้องหาครูฝึกของแต่ละชนิดเอง\n\nมีทองพอแล้วมาคุยกับข้า ข้าจะสอนวิธีขี่หมาป่าให้" },
        completion = { "10:1652484069:1189355142 C 228:302361846:1016071020", "Throm'ka {class} ข้าดีใจที่เจ้าฝึกกับ Kildar จนจบ\nเขาเชี่ยวชาญการดูแลหมาป่าพวกนี้ และสอนให้ผู้ขี่เข้าใจสายสัมพันธ์กับหมาป่าได้เป็นอย่างดี การขี่สัตว์งามสง่าพวกนี้ต้องอาศัยความกล้าทีเดียว" },
        steps = { { "24:1857109559:1009967372", "เรียนทักษะขี่สัตว์ขั้นฝึกหัด (Apprentice Riding)" } },
    },
    [94614] = { -- Freshwater Fiends
        title = { "17:667484746:351542258", "ตัวร้ายในลำน้ำ" },
        objective = { "82:1548351407:1263360856", "กำจัด Mudfin Oracle 8 ตัวและ Mudfin Warrior 8 ตัวตามลำน้ำใกล้ Wheeler's Grange" },
        description = { "365:1189949822:1719519384", "เห็นพวกเมอร์ล็อกริมแม่น้ำทางตะวันตกไหม? พวกมันร้ายเอาเรื่อง เป็นภัยทั้งกับสัตว์เลี้ยงของข้าและสัตว์ป่า แถมยังยึดที่ตกปลาประจำของข้าไปอีก!\n\nรับรองว่าไม่มีใครใน Riverglades ที่จะไม่ขอบใจเจ้า ถ้าเจ้าช่วยกำจัดพวกมันสักหน่อย\n\nเจอตัวไหนก็จัดการได้เลย ขอร้องล่ะ จะช่วยพวกเราได้มากทีเดียว" },
        completion = { "77:888758218:217615104", "กำจัดสัตว์รบกวนเป็นงานสำคัญของคนทำไร่ ข้าขอบใจที่เจ้ามาช่วย" },
        objectiveLabels = {
            monster = { ["Mudfin Warrior slain"] = "ปราบ นักรบ Mudfin", ["Mudfin Oracle slain"] = "ปราบ นักพยากรณ์ Mudfin" },
        },
    },
    [94617] = { -- Coyote Huntin'
        title = { "14:2140324868:1358900487", "ออกล่าโคโยตี" },
        objective = { "75:602159340:260442037", "ฆ่าโคโยตีชื่อ Sootfur แล้วนำหนังของมันกลับไปให้ Benjy Wheeler" },
        description = { "386:1028193408:87286169", "มีฝูงโคโยตีอยู่ในโพรงทางตะวันตก บางทีเราก็เห็นพวกมันจากอีกฝั่งของแม่น้ำ แต่ก่อนมันหาปลากินตามตลิ่ง ข้าว่าพวกเมอร์ล็อกคงไล่มันออกจากแหล่งหากินเดิม พวกมันเลยหันมากินม้า\n\nจ่าฝูงตัวใหญ่กว่าตัวอื่น ขนสีเข้ม เราเรียกมันว่า Sootfur ข้าว่าถ้าฆ่ามันได้ ที่เหลือคงแตกฝูงหนีไปเอง" },
        progress = { "61:1061195678:1029964925", "คอยดูเถอะ ข้าจะเอาเจ้าตัวแสบนั่นมาทำหมวก!" },
        completion = { "161:934265953:2031625272 N 79:1230924358:1384606564", "<Benjy จ้องตรงส่วนหัวของหนัง Sootfur>\n\nเอ้า ทีนี้ก็รู้แล้วสินะว่าไม่ควรมาคุ้ยเขี่ยในคอกม้าข้า!\n\n<Benjy หันกลับมามองเจ้า>\n\nทำได้ดีมาก {name} พอกลับมาเปิดกิจการอีกครั้ง ข้าจะได้อุ่นใจว่าม้าของเราปลอดภัย" },
        required = { [265738] = { "14:1503892682:845346587", "หนังของ Sootfur" } },
        steps = { { "14:1503892682:845346587", "หนังของ Sootfur" } },
    },
    [94679] = { -- Snargl's Snout
        title = { "14:52808542:164029571", "จมูกของสนาร์เกิล" },
        objective = { "101:1719579419:1594916779", "ตามหา Snargl ใน Bristle Hills ฆ่ามัน แล้วนำจมูกไปให้ Cedric Dalton ที่ Southern Watch" },
        description = { "340:299367575:519467877", "พวกนอลล์ให้ค่ากับพละกำลังเหนือสิ่งอื่นใด ถ้าเราฆ่าตัวที่แข็งแกร่งที่สุดได้ ภัยจากพวกมันก็จะลดลง ทั้งยังทำให้พวกมันหวาดกลัว\n\nในโพรงแห่งหนึ่งท่ามกลาง Bristle Hills มีนอลล์ตัวฉกาจชื่อ Snargl ถ้ามันตาย พวกนอลล์ Redridge ต้องแตกตื่นกันแน่\n\nเอาจมูกของมันมาให้ข้า รีบไปล่ะ" },
        completion = { "68:527671910:439764081", "ของที่ระลึกจากชัยชนะชิ้นนี้เลือดโชกทีเดียว อีกไม่นานเราจะได้ใช้มันให้เป็นประโยชน์ ทำได้ดีมาก" },
        progress = { "24:224204713:446956399", "ไอ้ตัวร้ายนั่นตายหรือยัง?" },
        required = { [265357] = { "14:52808542:164029571", "จมูกของ Snargl" } },
        steps = { { "14:52808542:164029571", "จมูกของ Snargl" } },
    },
    [94842] = { -- Unsavory Plant Food
        title = { "19:343914797:101069882", "ปุ๋ยกลิ่นชวนเบือนหน้า" },
        objective = { "104:1590501986:1245389160", "รวบรวม Jumbo Crawfish Shell 4 ชิ้น, Fresh Manure 4 กอง และ Mudfin Murloc Head 8 หัวให้ Halligan Turner" },
        description = { "451:1995092820:2121166737", "แถวนี้เราทำปุ๋ยใช้เอง เป็นสูตรเฉพาะของข้า กลิ่นเหม็นแทบตาย แต่ใส่แล้วต้นไม้โตไวอย่างกับวัชพืช\n\nใช้เปลือกกุ้งเครย์ฟิช มูลสัตว์ และหัวเมอร์ล็อกในอัตรา 1:1:2 ฟังดูน่ากินใช่ไหมล่ะ?\n\nมูลสัตว์หาไม่ยาก ไปเอาจากฟาร์มทางใต้ ส่วนหัวกับเปลือกน่ะ เจ้าต้องลงไปลุยแม่น้ำเอง\n\nถ้าอยากช่วย พวกเรากำลังขาดวัตถุดิบทำปุ๋ยอยู่พอดี" },
        progress = { "145:532083658:646518597", "บางคนคิดว่างานตัดไม้เป็นงานของคนสมองทึบ คิดผิดถนัด ถ้ารู้เรื่องอย่างพฤกษศาสตร์หรือเคมี เจ้าก็ไปได้ไกลในงานนี้" },
        completion = { "175:222173285:373245855", "ข้ารู้ว่าเจ้ากำลังมาทางนี้เพราะได้กลิ่นนั่นแหละ ขอบใจที่ยอมลงมือทำงานสกปรกเพื่อเรา ว่าอย่างนั้นเถอะ เอาล่ะ ไปชำระตัวในแม่น้ำก่อนที่เราจะเริ่มปลูกต้นไม้กัน" },
        required = { [266157] = { "20:745338910:868648814", "เปลือกกุ้งเครย์ฟิชขนาดใหญ่" }, [266156] = { "12:1461435095:340555282", "มูลสัตว์สด" }, [267266] = { "18:1555769300:225387409", "ศีรษะเมอร์ล็อก Mudfin" } },
        steps = { { "20:745338910:868648814", "เปลือกกุ้งเครย์ฟิชขนาดใหญ่" }, { "12:1461435095:340555282", "มูลสัตว์สด" }, { "18:1555769300:225387409", "ศีรษะเมอร์ล็อก Mudfin" } },
    },
    [94858] = { -- All That's Left
        title = { "15:1873393242:719529658", "สิ่งเดียวที่เหลืออยู่" },
        objective = { "84:1197314179:1609280434", "หาข้าวของของครอบครัว Farmer Elbrim ในโรงนาใกล้ ๆ แล้วนำกลับไปให้เขา" },
        description = { "433:2084760983:997804002", "ข้ามีอีกเรื่องที่อยากคุยกับเจ้า สหาย\n\nตอนที่กลุ่ม Twilight's Hammer บุก ข้าให้ทุกคนที่ป้องกันตัวเองไม่ได้ไปซ่อนในโรงนา ข้าคิดว่าพวกเขาจะปลอดภัย ข้าคิดว่า...\n\n<เสียงของ Elbrim สั่นเครือขณะเล่าถึงสิ่งที่เกิดขึ้น>\n\nขอให้เจ้าช่วยข้าเป็นครั้งสุดท้ายได้ไหม ไปดูให้ทีว่าครอบครัวข้าเหลืออะไรอยู่บ้าง พวกเขาควรได้ฝังที่บ้านตรงนี้ ใกล้ ๆ ข้า แต่ข้าทำใจไปดูเองไม่ได้จริง ๆ" },
        completion = { "11:1191658970:1224418299 N 201:1487238529:941948105", "ขอบใจ {name} ทีนี้เราทุกคนก็ได้พักด้วยกันเสียที\nถ้าเจ้าไม่ว่าอะไร ข้าขออยู่คนเดียวสักพัก คงมีครอบครัวอื่น ๆ ที่กำลังรอนักผจญภัยอย่างเจ้าอยู่ คราวหน้าเจ้าอาจไปถึงทันเวลาก็ได้" },
        progress = { "68:816322188:1260317273", "ข้าไม่ได้หวังว่าจะเหลืออะไรมาก แต่อย่างไรก็ต้องรู้ให้ได้" },
        required = { [266251] = { "14:1337255532:1044147001", "ตุ๊กตาที่ถูกทิ้ง" }, [266252] = { "14:1438759952:1090204461", "จี้ล็อกเกตที่ชำรุด" } },
        steps = { { "14:1337255532:1044147001", "ตุ๊กตาที่ถูกทิ้ง" }, { "14:1438759952:1090204461", "จี้ล็อกเกตที่ชำรุด" } },
    },
    [94861] = { -- Helping Hands
        title = { "13:643030054:1956644059", "ยื่นมือเข้าช่วย" },
        objective = { "29:69601483:17797515", "ไปกับ Hurley เพื่อช่วย Curly" },
        description = { "270:1321231565:88361102", "อ้อ ถึงว่า Curly ไม่กลับมาตอนพักเที่ยง ดูท่าข้าต้องไปช่วยเขาอีกแล้ว ตามเคย ทำให้ข้าเป็นห่วงแบบนี้ อีกปีเดียวข้าคงผมหงอกหมดหัว\n\nมาเถอะ เราต้องไปช่วยเขากันเอง ดูท่าจะเหลือเวลาไม่มากแล้ว" },
        completion = { "209:410965947:1521837177", "ไอ้เด็กบ้านั่น...\n\nถึง Curly จะหัวทึบ แต่ก็ขยันทำงาน หวังว่าเขาจะหายดีและรู้จักคิดเสียที ถ้าเจ้าไม่อยู่ตรงนั้น เรื่องอาจเลวร้ายกว่านี้มาก ขอบใจที่ช่วยดูแลเขา" },
    },
    [95329] = { -- Out in the Field
        title = { "16:304161525:386759175", "ออกไปตรวจแนวหน้า" },
        objective = { "67:1145940080:1409841550", "ไปที่ Terral's Watch เพื่อรับรายงานสถานการณ์จาก Watcher Cornelius" },
        description = { "403:685233652:1882682820", "ทางเหนือมีหอเฝ้าระวังที่มองลงไปเห็นทุ่งกว้าง เราใช้เป็นจุดสังเกตการณ์เพื่อติดตามความเคลื่อนไหวของกองกำลังฮอร์ด\n\nคนที่ประจำอยู่ที่นั่นชื่อ Cornelius ไปคุยกับเขาแล้วขอรายงานสถานการณ์ เขาอยู่คนเดียว ข้าเลยคอยถามข่าวเป็นระยะ ขอเตือนไว้ก่อน เขาค่อนข้าง...พูดน้อย นั่นแหละเหตุผลที่เขาได้ไปประจำจุดไกลผู้คนขนาดนั้น" },
        completion = { "170:155569809:870456085", "สถานการณ์ของข้ารึ? ไม่มีอะไรให้รายงานนักหรอก ที่ราบยังเต็มไปด้วยออร์คเหมือนเดิม ส่วน Demar ก็เห็นจะส่งมาแต่พวกมือใหม่อย่างเจ้านี่แหละ" },
    },
    [95330] = { -- Love Thy Neighbor
        title = { "17:197799697:2011609275", "แบ่งปันให้เพื่อนบ้าน" },
        objective = { "83:1078834024:1423393877", "นำผลผลิตส่วนเกินของ Cassandra ไปให้ Halligan Turner ที่ Turner's Logging Camp" },
        description = { "505:173000552:1311714788", "ข้ากับสามีทำไร่อยู่ทางเหนือ ทุกครั้งที่เก็บเกี่ยวเสร็จ ข้าจะมาขายผลผลิตที่ Farholde ปีไหนได้ผลดี ข้าชอบแบ่งของที่ขายไม่หมดไปให้คนที่กำลังลำบาก เพื่อนบ้านก็ต้องดูแลกันสิ\n\nเหนือไร่ของเรามีค่ายตัดไม้อยู่ติดแม่น้ำ พวกคนงานคงอยากได้ผักผลไม้ไปเปลี่ยนรสชาติอาหารบ้าง\n\nถ้าเจ้าจะไปทางนั้น ฝากเอาของนี่ไปให้หัวหน้าคนงานทีนะ เขาชื่อ Halligan Turner" },
        completion = { "210:842107479:1977733670", "ครอบครัว Wheeler ใจดีจริง ๆ!\nCassandra พูดถูก ที่นี่เราแทบไม่ได้กินอะไรนอกจากเนื้อกับขนมปัง ข้าจะแบ่งของพวกนี้ให้ทุกคน\nขอบใจสำหรับของฝากนะ ไว้ข้าต้องตอบแทนน้ำใจของนางบ้าง" },
        progress = { "40:236144508:57544087", "ดูเหมือนเจ้าจะมีของมาส่งให้ข้านะ" },
        required = { [268816] = { "13:1852774162:380487798", "ผลผลิตส่วนเกิน" } },
        steps = { { "13:1852774162:380487798", "ผลผลิตส่วนเกิน" } },
    },
    [95983] = { -- A Feast for Buzzards
        title = { "20:222064025:1112488482", "มื้อใหญ่ของแร้ง" },
        objective = { "62:509126505:2124817293", "นำ Gnawed Skull ไปให้ Watcher Cornelius ที่ Terral's Watch" },
        description = { "398:1796896938:1128853936", "โครงกระดูกแหลกเสียหาย ตามแขนขามีรอยลึกคล้ายรอยเขี้ยวและกรงเล็บ แดดจัดที่แผดเผามาหลายวันทำให้กระดูกซีดขาวและเปราะ ทั้งสภาพอากาศและการโจมตีที่รุนแรงทำให้ระบุไม่ได้ว่าผู้ตายเป็นใคร\n\nเจ้าคงเอาโครงกระดูกไปทั้งร่างไม่ได้ แต่ลองนำกะโหลกไปให้ยามแถวนี้ดู เผื่อเขาจะรู้อะไรบ้าง" },
        completion = { "191:1098468550:1009563961", "<Cornelius ลูบนิ้วไปตามรอยบนกะโหลก ยิ่งลูบ คิ้วของเขาก็ยิ่งขมวด>\nได้อย่างที่ข้าต้องการพอดี... งานเพิ่ม เจ้าเอาเรื่องยุ่งมาให้ข้าแล้วรู้ไหม?" },
        progress = { "15:2067485373:1691817709", "คราวนี้เรื่องอะไรอีก?" },
        required = { [271777] = { "12:81724327:1680425916", "กะโหลกที่มีรอยแทะ" } },
        steps = { { "12:81724327:1680425916", "กะโหลกที่มีรอยแทะ" } },
    },
    [95984] = { -- Song of the Strider
        title = { "19:675821598:940020754", "เสียงเรียกของทอลล์สไตรเดอร์" },
        objective = { "72:1315425468:1163064515", "นำ Intact Tallstrider Beak ไปให้ Watcher Cornelius ที่ Terral's Watch" },
        description = { "493:999389820:1477458598", "รอยพวกนี้มาจากสิงโต ดูแล้วตัวนี้ใหญ่เป็นพิเศษ น่าจะเป็นจ่าฝูงที่อยู่แถวนี้\n\nถ้าข่าวลือแพร่ออกไปว่ามีสิงโตกินคนเพ่นพ่านอยู่ในเขตที่ข้าเฝ้า Demar ต้องโกรธเป็นฟืนเป็นไฟแน่ โชคดีที่ข้ามีแผน\n\nข้าทำนกหวีดเลียนเสียงทอลล์สไตรเดอร์บาดเจ็บได้ เอาไว้ล่อเจ้าสิงโตออกมา ข้าขอแค่จะงอยปากของมันสักอันเพื่อให้เสียงเหมือนจริง มีทอลล์สไตรเดอร์อยู่ทั่วทุ่ง ไปเอาจะงอยปากมาให้ข้า เร็วเข้า!" },
        progress = { "75:26970074:1842252596", "ข้าว่าไม่ต้องบอกก็น่าจะรู้ แต่เจ้าต้องเป็นคนเป่านกหวีดอันนี้เองนะ" },
        completion = { "82:468806961:1734028440", "เอาล่ะ ขออยู่คนเดียวสักครู่ ข้าจะได้แกะให้ได้รูปที่ต้องการ" },
        required = { [271778] = { "23:1284813656:452081067", "จะงอยปาก Tallstrider สภาพสมบูรณ์" } },
        objectiveLabels = {
            item = { ["Intact Tallstrider Beak"] = "จะงอยปาก Tallstrider สภาพสมบูรณ์" },
        },
    },
    [94678] = { -- Gnoll Infestation
        title = { "17:1326934258:674836375", "ฝูงนอลล์ยึดเนินเขา" },
        objective = { "5:409775429:850574908 W1 19:693867940:1775384519 W2 24:1170222029:17687185 W3 53:275810958:2053793340", "กำจัด Redridge Mystic {world1} ตัว, Redridge Trapper {world2} ตัว และ Redridge Brute {world3} ตัวให้ Cedric Dalton ที่ Southern Watch" },
        description = { "416:2048335916:1854964671", "พวกนอลล์ก่อปัญหาให้เรามาตั้งแต่มาถึง ถึงจะเป็นภัยน้อยกว่ากลุ่ม Twilight's Hammer แต่พวกมันก้าวร้าว ตื๊อไม่เลิก และที่แย่ที่สุดคือมีจำนวนมาก\n\nพวกมันยึดเนินเขาเลยด่านนี้ไปจนการเดินทางขึ้นเหนือเป็นอันตราย คนที่อยู่นอกกำแพง Farholde Keep ก็พลอยตกอยู่ในอันตรายด้วย\n\nถ้าอยากให้ดินแดนนี้ปลอดภัย เราต้องกำจัดภัยจากพวกนอลล์ให้ได้" },
        completion = { "199:1294109161:1353284805", "นั่นน้ำลายโนลล์ติดตัวเจ้าหรือ? ช่างเถอะ ถ้าเป็นเวลาอื่นข้าคงถามแล้วว่าไปเปื้อนมาจากไหน แต่สภาพแบบนี้...\n\n<Cedric ผายมือไล่ตั้งแต่หัวจรดเท้าเจ้า>\n\nงานของพวกเราที่นี่ก็แบบนี้แหละ" },
        objectiveLabels = {
            monster = { ["Redridge Mystic slain"] = "ปราบ นักเวทลี้ลับ Redridge", ["Redridge Trapper slain"] = "ปราบ นายพรานวางกับดัก Redridge", ["Redridge Brute slain"] = "ปราบ อันธพาล Redridge" },
        },
    },
    [94843] = { -- From Seed to Sprout
        title = { "19:112655571:303795630", "จากเมล็ดสู่ต้นกล้า" },
        objective = { "6:943675681:238902005 W1 75:781634142:1904891602", "ใช้ชุดเพาะต้นกล้าของ Halligan Turner ปลูกต้นกล้า {world1} ต้นรอบค่ายตัดไม้" },
        description = { "345:1790591617:1543470764", "เจ้ายอมล้วงเครื่องในกับมูลสัตว์จนมือเปื้อนถึงข้อมือเพื่อพวกเรา จะให้เจ้าพลาดงานสนุก ๆ ก็คงไม่ยุติธรรม\n\nข้ากับพวกคนงานเก็บเมล็ดจากต้นไม้ระหว่างทำงาน ข้าเอาปุ๋ยที่เจ้าหามาทำชุดปลูก จะได้เอาเมล็ดลงดินให้โตเป็นต้นกล้ารุ่นใหม่\n\nเอาชุดนี้ไป แล้วหาจุดเหมาะ ๆ แถวพื้นที่ทำงานเพื่อปลูก" },
        completion = { "35:2138306492:344718459 N 30:1886335793:109205201", "ทำงานหนักมาทั้งวันนี่มันดีจริง ๆ ใช่ไหม {name}? ขอบใจที่มาช่วยนะ" },
        progress = { "81:50900684:1736622470", "เราปลูกให้มันโต ตัดลง แล้วก็ปลูกใหม่ วนกันไปแบบนี้แหละ งดงามดีออก" },
        required = { [266161] = { "18:953108014:1292870514", "ชุดเพาะกล้าไม้" } },
        steps = { { "15:916131060:1652863027", "ปลูกต้นกล้า" }, { "18:953108014:1292870514", "ชุดเพาะกล้าไม้" } },
    },
    [94877] = { -- Saving Sunnyglade
        title = { "17:1790298391:542197311", "กอบกู้ซันนีเกลด" },
        objective = { "7:1265997621:1189804897 W1 19:713120248:125579941 W2 29:1443263011:1600677091 W3 54:1492379797:2073458818", "กำจัด Twilight Raider {world1} คน, Twilight Shadowmancer {world2} คน และ Twilight Neophyte {world3} คนใน Sunnyglade ให้ Demar Brant" },
        description = { "486:776194053:1403607146", "มองไปรอบตัวแล้วเจ้าเห็นอะไร? บ้านที่พังยับกับผู้คนที่เหนื่อยล้า\n\nStormwind ปล่อยให้เราดูแลตัวเอง และสิ่งที่พอจะประทังชีวิตก็ร่อยหรอลงทุกวัน คนหลังกำแพงนี้หลายคนเป็นผู้ลี้ภัยที่รอดตายมาได้หวุดหวิด บางคนต้องพลัดพรากแม้แต่จากครอบครัวตัวเอง\n\nFarholde ไม่ใช่ Stormwind คนแปลกหน้า เราเสียชุมชนทางตะวันตกเฉียงเหนือให้กลุ่ม Twilight's Hammer แต่จะไม่ยอมให้มันยึดไว้ ถ้าอยากสู้ ก็ไป Sunnyglade แล้วขับไล่พวกป่าเถื่อนออกจากดินแดนของเรา" },
        progress = { "118:764729662:126815118", "เรายืนหยัดกันมาถึงขนาดนี้แล้ว จะไม่ถอยตอนนี้หรอก ให้พวกสาวกลัทธิ Twilight เห็นว่ามนุษย์เราทรหดแค่ไหน!" },
        completion = { "126:71540804:785208037", "เจ้าทำให้ฝ่ายอะไลแอนซ์ภาคภูมิใจนะ เจ้าโนม ถ้าพวกขุนนาง Stormwind มีความเด็ดเดี่ยวสักครึ่งหนึ่งของเจ้า สงครามนี้คงจบไปหลายปีแล้ว" },
        objectiveLabels = {
            monster = { ["Twilight Raider slain"] = "ปราบ ผู้จู่โจม Twilight", ["Twilight Shadowmancer slain"] = "ปราบ จอมเวทเงา Twilight", ["Twilight Neophyte slain"] = "ปราบ สาวกใหม่ Twilight" },
        },
    },
    [94881] = { -- Curious Trinkets
        title = { "16:492216757:719875954", "เครื่องรางน่าพิศวง" },
        objective = { "9:1866698604:257786470 W1 118:603129714:1859469893", "นำ Twilight Charm {world1} ชิ้นจาก Twilight Shadowmancer และ Twilight Neophyte ใน Sunnyglade ไปให้ Ashe Amberhall ที่ Farholde Keep" },
        description = { "35:1641685839:831423044 C 462:571630257:393821206", "อุ๊ย ใครมานี่เอ่ย? {class} ผู้กล้าคนใหม่ที่มาช่วยเราพ้นทุกข์หรือ? ช่างน่าเอ็นดูจริง! ถ้าอย่างนั้นช่วยข้าสักเรื่องได้ไหม? ข้าอยากรู้เรื่องลัทธิที่อยู่ใน Sunnyglade ให้มากกว่านี้\n\nเหมือนลัทธิอื่น ๆ พวกนี้แบ่งสมาชิกเป็นชนชั้น คนที่มีพรสวรรค์ด้านเวทมนตร์มักเป็นที่โปรดปรานและได้รับเครื่องหมายแสดงฐานะ จากนั้นพวกเขาก็ลงเวทไว้ในเครื่องรางเหล่านี้ จนมันเปี่ยมด้วยพลังเวทของสาวกลัทธิ\n\nข้าอยากเห็นเครื่องรางพวกนั้นกับตาตัวเอง ช่วยหามาให้ข้าสักหน่อยนะ?" },
        progress = { "130:910029431:1361080147", "เจ้าคงหาเครื่องรางจากพวกนักเวทของ Twilight's Hammer ได้ไม่ยาก ดูท่าพวกมันจะหวงของพวกนี้เสียด้วย" },
        completion = { "16:1549935302:71513149 C 68:559559161:1956162733", "ทำได้ยอดเยี่ยม {class} ข้าสัมผัสถึงพลังในตัวเจ้าได้ตั้งแต่ก่อนเจ้าเข้ามาในป้อมเสียอีก" },
        required = { [266425] = { "14:1423425154:381152451", "เครื่องรางทไวไลต์" } },
        steps = { { "14:1423425154:381152451", "เครื่องรางทไวไลต์" } },
    },
    [95561] = { -- Apple of My Eye
        title = { "15:432132085:880392558", "แอปเปิลให้แก้วตาดวงใจ" },
        objective = { "8:1089852795:1107240600 W1 52:1287168963:98055955", "เก็บ Fresh Apple {world1} ผลให้ Tessa Dawnbright ที่ Farholde Keep" },
        description = { "487:192790907:1789242506", "<เสียงทารกบ้าน Dawnbright ร้องดังไปทั่ว Farholde Keep เทสซามองเจ้าพร้อมยิ้มอย่างอ่อนล้า>\n\nอ้อ สวัสดี นักผจญภัย ขอโทษที่เสียงดังนะ วันนี้เอ็มมาตัวน้อยงอแงเป็นพิเศษ ข้าก็ไม่รู้ว่าทำไม ลองให้กินอะไรสักหน่อยอาจช่วยได้\n\nช่วยหาอะไรให้ลูกข้ากินได้ไหม? สามีข้าออกไปหาเสบียง ข้ากำลังมือเป็นระวิง ไปหาเองไม่ไหว ถ้าเจอแอปเปิลสักสองสามลูกแถวนี้ ข้าจะเอามาบดให้ลูกกิน" },
        progress = { "102:325140400:538216774", "ไม่มีใครบอกเราหรอกว่าครึ่งหนึ่งของการเลี้ยงลูกคือค่อย ๆ คิดเอาหน้างาน คนอื่นทำให้ดูเหมือนง่ายกันไปหมด" },
        completion = { "19:1061876233:111335988 N 71:1338162654:1570733163 C 16:1682963522:1546632861", "ขอบใจมากนะ {name} แอปเปิลพวกนี้ดูน่ากินจริง ๆ Emma ขอบคุณสิ ขอบคุณ{class}ใจดีคนนี้สิ\n\nอืม ดูท่าจะไม่พูดแฮะ" },
        required = { [271431] = { "11:1539389775:43244138", "แอปเปิลสด" } },
        steps = { { "11:1539389775:43244138", "แอปเปิลสด" } },
    },
    [95975] = { -- Her World
        title = { "9:2118928652:384323461", "โลกของลูก" },
        objective = { "7:451016854:1830523975 W1 67:649489606:238440780", "เก็บ Wildflower {world1} ดอกแล้วนำไปให้ Tessa Dawnbright ที่ Farholde Keep" },
        description = { "502:400285992:88089634", "เทสบอกว่าเอ็มน้อยนอนไม่หลับถ้าไม่มีข้าอยู่ด้วยหรือ? แล้วเจ้าช่วยสองแม่ลูกถึงขนาดนั้น ทั้งที่ไม่รู้จักกันเลยหรือ? ให้ตายสิ ข้ามัวคิดอะไรอยู่...\n\nถึงข้าจะรับประกันไม่ได้ว่าโลกของลูกจะสมบูรณ์แบบ ข้าก็ยังต้องอยู่ในโลกใบนั้นกับลูก ถ้าข้าหวังให้อนาคตดีขึ้นไม่ได้ แล้วข้าสู้ไปเพื่ออะไรกัน?\n\nขอบใจที่ช่วยครอบครัวข้าตอนที่ข้าไม่อยู่ สหาย แต่ถึงเวลาที่ข้าต้องกลับบ้านแล้ว ขอฝากอีกเรื่องได้ไหม ช่วยเก็บดอกไม้ไปให้เทสที บอกนางว่าข้าจะกลับถึงบ้านเร็ว ๆ นี้ ขอไปล้างเนื้อล้างตัวก่อน" },
        completion = { "335:2018176395:455356928 N 62:2052732023:706859380", "โอ้ สวยจัง! Gray หามาให้ข้าหรือ? เขาทำให้ข้ายิ้มได้เสมอ มิน่าล่ะ Emma ตัวน้อยของเราถึงคิดถึงเขาขนาดนี้ พอเขากลับมา นางต้องดีใจมากแน่\nใช่ไหมจ๊ะ Emma? พ่อจะกลับบ้านเร็ว ๆ นี้แล้ว พูดสิจ๊ะ พ่อ พ่อ\n<ทารกหยุดร้องแล้วแหวะนมใส่ผ้าห่ม>\nถือว่าเริ่มได้ดี ขอบใจสำหรับทุกอย่างนะ {name} เจ้าเป็นเหมือนพรสำหรับพวกเราจริง ๆ แวะมาเยี่ยมได้ทุกเมื่อเลย!" },
        progress = { "23:140679440:2097538806 N 26:1504329912:1039829182", "ดีใจที่ได้เจอเจ้าอีกนะ {name} เจอสามีข้าหรือยัง?" },
        required = { [271823] = { "10:421979396:152279481", "ดอกไม้ป่า" } },
        steps = { { "10:421979396:152279481", "ดอกไม้ป่า" } },
    },
    [94829] = { -- What We Lost
        title = { "12:30578243:60875969", "สิ่งที่เราสูญเสีย" },
        objective = { "8:1089852795:1107240600 W1 92:699516597:714749069", "เก็บ Farmers' Memento {world1} ชิ้นจาก Twilight Raider แล้วนำไปวางบนหลุมศพทางตะวันตกของ Elbrim's Farm" },
        description = { "503:1095344861:85544463", "ถ้ามาเรียกเอาผลผลิตเพิ่ม ก็สายไปแล้ว เจ้าคงเห็นไร่ข้าแล้วสินะ พังหมด ไม่เหลืออะไรเลย\n\nคนดี ๆ ทำงานหนักในไร่นี้มาหลายปีเพื่อเลี้ยงทั้งทหารและชาวบ้าน แต่พอพวกลัทธิบุกเข้ามา พวกทหารไปอยู่ไหนเสีย? พวกเขาเอาเสบียงเราไปตั้งมาก แล้วการคุ้มครองที่สัญญาไว้ล่ะ?\n\nถ้าเจ้ายังพอมีน้ำใจ ข้าขอร้อง อย่างน้อยก็ช่วยเอาข้าวของของพวกเขาคืนจากโจรพวกนั้น ให้คนของข้าได้พักสงบเคียงข้างญาติพี่น้องในสุสานทางตะวันตกเถอะ" },
        completion = { "95:456096822:1532098482", "มันพาคนเหล่านี้กลับมาไม่ได้ แต่ข้าก็สบายใจที่รู้ว่าดวงวิญญาณของพวกเขาได้พักอย่างสงบ" },
        required = { [266148] = { "17:1102063778:1047676675", "ของที่ระลึกของชาวไร่" } },
        steps = { { "15:581904807:114002819", "ฝังของที่ระลึก" }, { "17:1102063778:1047676675", "ของที่ระลึกของชาวไร่" } },
    },
    [94889] = { -- Carving a Path
        title = { "14:786865507:1472265577", "ตีฝ่าเปิดทาง" },
        objective = { "7:1265997621:1189804897 W1 20:842221735:1613607240 W2 26:406181726:835666367 W3 69:47950183:90746999", "กำจัด Twilight Fanatic {world1} คน, Twilight Corrupter {world2} คน และ Twilight Champion {world3} คนใน Twilight's Shroud ให้ Sergeant Riftan" },
        description = { "504:1691583058:1489214641", "ดูเหมือนกลุ่ม Twilight's Hammer จะดึงคนเข้าลัทธิเพิ่มทุกวัน ส่วน Stormwind ยังเงียบกริบ ไม่ช้าก็เร็ว พวกมันจะบุกจนเราต้านไม่ไหว\n\nข้าไม่สนว่าข้าราชการอย่าง Amberhall จะพูดยังไง ข้าจะไม่ทิ้งที่มั่นตอนที่พวกมันกำลังรวมพลอยู่ในบ้านเราเอง ถ้าถอยตอนนี้ เดี๋ยวก็ต้องสู้กับพวกลัทธิอีก คราวหน้ามันคงมาถึงหน้าประตูบ้านเรา\n\nไหน ๆ เจ้าก็ถูกสั่งมาคอยเฝ้าข้าอยู่แล้ว อย่างน้อยก็ช่วยข้าจัดการพวกคลั่งนี่หน่อยเถอะ" },
        completion = { "114:654604640:1671147894", "ถ้าข้าไม่ต้องอยู่ประจำตรงนี้ ข้าคงบุกเข้าไปในกับดักมรณะนั่นด้วยตัวเอง แต่เมื่อข้าต้องอยู่ที่นี่ เจ้าก็ทำหน้าที่แทนข้าได้ดี" },
        objectiveLabels = {
            monster = { ["Twilight Fanatic slain"] = "ปราบ สาวกคลั่ง Twilight", ["Twilight Corrupter slain"] = "ปราบ ผู้แพร่ความแปดเปื้อน Twilight", ["Twilight Champion slain"] = "ปราบ ยอดนักรบ Twilight" },
        },
    },
    [94931] = { -- Stolen Saws
        title = { "11:1967975301:1530749404", "ใบเลื่อยที่ถูกขโมย" },
        objective = { "8:1749550375:377180055 W1 89:734046735:1314580037", "เอา Saw Blade {world1} ใบคืนจากค่ายนอลล์ใน Bristle Hills แล้วนำไปให้ Halligan Turner ที่โรงเลื่อย" },
        description = { "422:2045412232:1323214479", "พวกที่ Southern Watch กันนอลล์ออกไปได้ดีเกือบตลอด แต่บางคืนก็มีสองสามตัวลอบเข้าค่ายมาป่วน พวกมันชอบขโมยใบเลื่อยเป็นพิเศษ คงเอาโลหะคม ๆ ไปทำอาวุธ\n\nถ้าช่วยเอาคืนมาได้สักหน่อยก็จะช่วยเรามาก พวกนอลล์น่าจะซ่อนไว้แถวค่ายของมันบนเนินเขาทางตะวันตก" },
        progress = { "113:737261273:261947876", "ใบเลื่อยพวกนั้นหาไม่ง่ายเลย ทุกใบที่เจ้าเอากลับมาได้จะช่วยเราประหยัดทั้งเวลาและทรัพยากรได้มาก" },
        completion = { "49:1876601704:1052246567", "ทำได้ดีนี่! ข้าน่าจะจ้างเจ้าเป็นยามเสียเลย" },
        required = { [266897] = { "9:303924594:1497119535", "ใบเลื่อย" } },
        steps = { { "9:303924594:1497119535", "ใบเลื่อย" } },
    },
    [95156] = { -- Stuff 'Em and Stick 'Em
        title = { "23:917023526:1526336779", "ยัดฟางตั้งหุ่น" },
        objective = { "8:1089852795:1107240600 W1 50:898092554:727738686", "เก็บ Bundle of Hay {world1} มัดให้ Ember ที่ลานฝึก" },
        description = { "420:1863252975:1189734236", "หุ่นฝึกของเราเริ่มสึกหรอหนักแล้ว ถ้าไม่รีบซ่อม ข้ากลัวว่าทหารใหม่จะยังไม่พร้อมออกรบ\n\nถ้าเจ้าไม่ทันเห็นตอนขามา มีฟาร์มเล็ก ๆ อยู่นอกป้อม เจ้าของชื่อ Wheeler เขาอาจมีฟางเหลือให้เราสักสองสามมัด\n\nถ้าเขาแบ่งของมาช่วยเราได้ ข้าจะจัดการให้เขาได้รับค่าตอบแทนเอง" },
        progress = { "31:1557412035:2054680248", "เจอของที่ตามหาหรือยัง?" },
        completion = { "48:1782648047:2086323651", "เราจะจัดการทำเป้าซ้อมชุดใหม่เดี๋ยวนี้เลย" },
        required = { [268536] = { "13:1597975042:103223466", "มัดหญ้าแห้ง" } },
        steps = { { "13:1597975042:103223466", "มัดหญ้าแห้ง" } },
    },
    [95184] = { -- The Sharpest of Blades
        title = { "22:1555449876:773299352", "คมดาบชั้นดี" },
        objective = { "6:1273960851:929420321 W1 80:451874584:818742827", "นำ Solid Sharpening Stone {world1} ก้อนไปให้ Ember Bladewhisper ที่ลานฝึก Farholde" },
        description = { "440:331766282:667992185", "การฝึกออกรบหนักหนาก็เรื่องหนึ่ง แต่ทหารใหม่พวกนี้ยังไม่รู้ว่าดาบฝึกต่างจากดาบที่ทหารผ่านศึกดูแลอย่างดีแค่ไหน\n\nถึงเวลาสอนให้พวกเขาเห็นแล้วว่าคมดาบอาจตัดสินได้เลยว่าใครจะชนะและใครจะตาย\n\nถ้าช่วยหาหินลับคมมาให้สักหน่อย พวกเราจะใช้ให้คุ้ม งานนี้มีช่างฝีมือบางคนที่เชี่ยวชาญ ลองไปถามพวกเขาดูก่อน" },
        completion = { "21:1392793311:773189738", "พวกนี้ใช้ได้ดีทีเดียว" },
        progress = { "30:1552533906:1724629317", "หาเจ้าหินพวกนั้นเจอบ้างหรือยัง?" },
        required = { [7964] = { "22:262441383:43897", "หินลับคมเนื้อแข็ง" } },
        objectiveLabels = {
            item = { ["Solid Sharpening Stone"] = "หินลับคมเนื้อแข็ง" },
        },
    },
    [95426] = { -- Rog'mar Supplies
        title = { "16:1339884319:1372705719", "เสบียงของร็อกมาร์" },
        objective = { "9:1866698604:257786470 W1 64:1826137650:1823696828", "ชิง Horde Supply Shipment {world1} ชุดจากค่ายฝึกทางเหนือของ Rog'mar" },
        description = { "499:312792930:545740925", "ส่งเสบียงมาถึงแถวนี้ไม่ง่ายเลย มีพวกไร้ศีลธรรมล้อมเราอยู่ทุกทิศ แต่ละพวกก็อยากได้ส่วนแบ่งของตัวเอง\n\nว่าแล้วนี่อาจเป็นโอกาสชะลอการขยายกำลังของ Rog'mar สนใจไปขัดแผนสหายออร์คของเราสักหน่อยไหม?\n\nไปที่ลานฝึกทางเหนือของ Rog'mar แล้วขโมยเสบียงของพวกมัน กว่าจะหาเสบียงมาทดแทนได้ กองกำลังเราก็ยังพร้อมรบ ส่วนฝั่งนั้น... เจ้าคงนึกออก" },
        progress = { "36:243064389:194457352", "ว่าไง...? หาเสบียงพวกนั้นได้บ้างไหม?" },
        completion = { "16:21510352:1129401082 N 81:1120699640:253529775", "ทำได้ดีมาก {name} กว่าพวกนั้นจะหาเสบียงมาทดแทนได้คงต้องใช้เวลา แถมยังต้องลุ้นให้ขบวนเสบียงเดินทางมาถึงโดยปลอดภัยด้วย" },
        required = { [274975] = { "20:869676900:1832756951", "ลังเสบียงของ Rog'mar" } },
        steps = { { "20:869676900:1832756951", "ลังเสบียงของ Rog'mar" } },
    },
    [95613] = { -- Keeping the Light On
        title = { "20:1341174895:517189788", "รักษาแสงเทียนไว้" },
        objective = { "6:1273960851:929420321 W1 49:25531504:2107405836", "นำ Holy Candle {world1} เล่มไปให้ Sister Rowland ที่ Farholde Keep" },
        description = { "503:1660424204:1055011730", "แม้เราจะเลิกประกอบพิธีที่โบสถ์แล้ว แต่ข้ายังเห็นว่าสำคัญที่จะจุดเทียนไว้บนหลุมศพของผู้ล่วงลับในห้องใต้โบสถ์ สำหรับข้า เปลวเทียนที่ยังสว่างหมายถึงเรายังจดจำพวกเขา และการเสียสละของพวกเขามีความหมาย\n\nช่วยนำเทียนมาให้ข้าหน่อยได้ไหม ข้าจะได้ทำพิธีนี้ต่อไป มันมีความหมายกับข้ามากจริง ๆ\n\nถ้าไม่รู้ว่าจะหาได้จากไหน ลองคุยกับ Marla ในบ้านนอกโบสถ์ นางเป็นเพื่อนข้า อาจมีเทียนพอแบ่งให้" },
        completion = { "61:1121308171:803771870 N 1:46:46", "พวกนี้ใช้ได้ดีทีเดียว ขอบใจที่ช่วยอีกครั้งนะ {name}" },
        progress = { "154:699048463:1945962104", "ข้ารู้ว่าเมื่อเทียบกับงานทั้งหมดที่เราทำกันอยู่ เทียนไม่กี่เล่มดูเป็นเรื่องเล็กน้อย แต่ข้าดูแลผู้ที่ยังมีชีวิตอย่างไร ก็ต้องดูแลผู้ล่วงลับอย่างนั้น" },
        required = { [17028] = { "11:1802184538:787762290", "เทียนศักดิ์สิทธิ์" } },
        steps = { { "11:1802184538:787762290", "เทียนศักดิ์สิทธิ์" } },
    },
    [95615] = { -- In Memoriam
        title = { "11:670651268:923635418", "แด่ผู้จากไป" },
        objective = { "6:942945287:238711269 W1 88:84946417:168605811", "วาง Memorial Candle {world1} เล่มบนหลุมศพในสุสานของโบสถ์ให้ Sister Rowland ที่ Farholde Keep" },
        description = { "440:1424878099:265977795", "ถ้าเจ้าไม่ขัดข้อง ข้าอยากให้เจ้าเป็นผู้จุดเทียนรำลึกเหล่านี้ ไปที่สุสานด้านนอก เห็นเทียนเล่มไหนดับแล้วก็วางเล่มใหม่แทน\n\nงานนี้คงห่างไกลจากการผจญภัยตื่นเต้นที่เจ้าคุ้นเคย ลองถือเสียว่าเป็นโอกาสได้ทำสิ่งดี ๆ และใช้เวลาสงบทบทวนถึงผู้ที่จากโลกนี้ไปก่อนเรา เพื่อให้เรามีกำลังเดินต่อและทำให้โลกนี้ดีขึ้น" },
        completion = { "119:438595323:1089114666 N 54:1241208797:300873047", "ดวงวิญญาณของผู้ล่วงลับมองเจ้าด้วยความอบอุ่นและซาบซึ้ง ข้าเองก็รู้สึกเช่นนั้น\nขอบใจที่ช่วยให้โบสถ์ยังดำรงอยู่ได้ {name} ขอให้แสงศักดิ์สิทธิ์นำทางและคุ้มครองเจ้าตลอดการเดินทาง" },
        progress = { "20:1227406943:2112033961 N 1:63:63", "เทียนหมดแล้วหรือ {name}?" },
        required = { [269997] = { "17:1987239219:80389194", "มัดเทียน" } },
        steps = { { "16:619711947:162011318", "เปลี่ยนเทียน" }, { "17:1987239219:80389194", "มัดเทียน" } },
    },
    [95643] = { -- Indiscriminate Purge
        title = { "20:705564655:574956867", "กวาดล้างให้สิ้น" },
        objective = { "5:409775429:850574908 W1 25:70350760:717457970 W1 57:1518770605:2012737625", "กำจัด Twilight Ritualist {world1} คนและ Empowered Brute {world1} ตัวในถ้ำใต้ Sunnyglade" },
        description = { "487:1924500965:22014329", "ข้าเป็นศิษย์วิชามืดของท่านหญิง Amberhall ถึงจะดูไม่เหมือน แต่ปกติข้าจัดการเรื่องต่าง ๆ เองได้ แค่ไม่คิดว่าจะเจอโอเกอร์ที่อาบพลังวอยด์อยู่เต็มถ้ำ\n\nถ้าเจ้าลงมาถึงนี่โดยไม่ถูกจับ ก็คงมีฝีมือไม่น้อย ข้าโชคไม่ดีอย่างเจ้าตอนพวกโอเกอร์กับนายของมันเดินเพ่นพ่านอยู่ ช่วยโลกสักอย่างเถอะ ฆ่าตัวอัปลักษณ์พวกนั้นเสีย พวกคลั่งที่มีจุดหมายก่อแต่เรื่องร้าย จะมีพลังเสริมหรือไม่ก็เถอะ" },
        completion = { "109:439862335:588758400", "เจ้าจัดการสัตว์พวกนั้นไปได้ตั้งหลายตัว วันนี้ Twilight's Hammer คงตั้งตัวไม่ติดกับความสูญเสียครั้งนี้" },
        objectiveLabels = {
            monster = { ["Empowered Brute slain"] = "ปราบ อันธพาลเสริมพลัง", ["Twilight Ritualist slain"] = "ปราบ ผู้ประกอบพิธี Twilight" },
        },
    },
    [95913] = { -- Fit for a Princess
        title = { "18:1935054381:1950621948", "สมกับเจ้าหญิง" },
        objective = { "8:1089852795:1107240600 W1 52:1399220892:2044474200", "เก็บ Coyote Pelt {world1} ผืนให้ Tessa Dawnbright ที่ Farholde Keep" },
        description = { "499:565172060:2057141937", "<เทสซาอุ้มลูกโยกเบา ๆ กล่อมให้หลับ>\n\nถ้าไม่หิวก็คงเหนื่อย ที่จริงการมีเอ็มมาเป็นเรื่องน่ายินดีที่เราไม่ทันตั้งตัว เลยเตรียมของไว้ไม่ค่อยพร้อม สามีข้าทำเปลน่ารักใบนี้ให้ลูก แต่ข้ากลัวว่าผ้าห่มจะเก่าเกินไป ลูกควรได้ของที่ดีที่สุดอยู่แล้ว\n\nถ้าเจ้ายังเต็มใจช่วย ข้าจะขอบคุณไม่รู้ลืมเลยถ้าช่วยหาหนังสัตว์มาปูเปลให้ลูกได้ ถ้าลูกหยุดร้อง คนทั้ง Farholde ก็คงขอบใจเจ้าด้วย" },
        completion = { "34:216493642:1490434320 N 67:167111923:83217862", "อ้าว เจ้ากลับมาแล้ว! เจ้านี่เป็นเหมือนปาฏิหาริย์เลย {name} ของพวกนี้ดูอบอุ่นน่าใช้... แถมนุ่มด้วย\nให้ Emma น่ะ แน่นอนอยู่แล้ว" },
        progress = { "109:1142004154:691377681 C 39:375912546:540507586", "<Tessa ไม่เงยหน้าขึ้น เธอพยายามทุกวิถีทางจะกล่อมลูกที่กำลังร้องไห้ให้หลับ>\nชู่ว์ ๆ คุณ{class} ใจดีและแข็งแรงคนนี้จะช่วยเราระหว่างที่พ่อไม่อยู่นะลูก" },
        required = { [271432] = { "11:1513095433:652243293", "หนังหมาป่าโคโยตี" } },
        steps = { { "11:1513095433:652243293", "หนังหมาป่าโคโยตี" } },
    },
    [95988] = { -- Goes Down Smooth
        title = { "16:220109971:979047851", "ดื่มคล่องคอ" },
        objective = { "7:451016854:1830523975 W1 109:957462679:1519411461", "รวบรวม Crawler Spittle {world1} ส่วน พร้อม Fresh Chum, Goblin Degreaser และ Expired Poison ให้ Innkeeper Zizplink ที่ Powderfuse Port" },
        description = { "499:332788025:483747728", "ไปคุยกับ Gray มาแล้วสิท่า? หมอนั่นตัวฮาเลยละ สิ่งสุดท้ายที่เขาต้องการคือให้เจ้าไปหาเหล้าเพิ่ม ที่นี่โรงแรม ไม่ใช่ร้านเหล้า โชคดีแค่ไหนที่ข้ายังไม่โยนเขาออกไป\n\nอยากพาเขาไปด้วยก็เชิญ แต่สภาพนั้นคงไปไหนไม่ไหว ต้องได้ยาปลุกให้สร่างแบบก็อบลินสักหน่อย\n\nช่วยหาส่วนผสมตามรายการนี้มาให้ข้าที ระหว่างนั้นข้าจะเตรียม ‘เครื่องดื่ม’ ให้เพื่อนเจ้า ไว้ลองค็อกเทลสูตรพิเศษของข้าแล้วค่อยดูว่าเขายังอยากดื่มเหล้าอีกไหม" },
        completion = { "109:263424282:1918371814", "พวกนี้กำลังดีเลย แถมเหลือให้ลูกค้าคนอื่นอีกเพียบ พวกโอกร์กินเท่าไรก็ไม่รู้จักพอ แปลกดีนะ" },
        progress = { "89:742253614:2091375035", "เวลาหดหู่ ไม่มีอะไรดีเท่าการระบายออกมาให้หมด ทั้งเรื่องในใจและของในท้อง" },
        required = { [271650] = { "15:1974370997:1299856581", "น้ำลายปู" }, [271657] = { "10:423786428:512872806", "เหยื่อสับสด" }, [271653] = { "16:588719720:549063105", "น้ำยาขจัดคราบไขมันสูตรก็อบลิน" }, [271654] = { "14:1265129826:1168779140", "ยาพิษหมดอายุ" } },
        steps = { { "15:1974370997:1299856581", "น้ำลายปู" }, { "10:423786428:512872806", "เหยื่อสับสด" }, { "16:588719720:549063105", "น้ำยาขจัดคราบไขมันสูตรก็อบลิน" }, { "14:1265129826:1168779140", "ยาพิษหมดอายุ" } },
    },
    [96009] = { -- High Stakes
        title = { "11:1033037541:2020557134", "ไม้ค้ำป้อม" },
        objective = { "8:1089852795:1107240600 W1 80:454029703:2093875674", "เก็บ Wood Bundle {world1} มัดจาก Turner's Logging Camp ให้ Bertrand Ironbrow ที่ Farholde Keep" },
        description = { "500:1755304695:380022410", "ความมุ่งมั่นของมนุษย์นี่ทำให้ข้าทึ่งได้ทุกที เห็นสนามรบรกร้างที่เต็มไปด้วยออร์คกับสาวกลัทธิ แล้วคิดว่าเหมาะจะมาตั้งรกรากเสียนี่! น่าทึ่งจริง ๆ\n\nแต่หน้าที่ข้าไม่ใช่บอกให้พวกเขาสร้างที่ไหน แค่สอนว่าสร้างยังไง ถ้าจะให้ป้อมใหญ่สมคำพูด เราต้องใช้ไม้อีกเยอะ\n\nถนนอันตรายขึ้นทุกที ไม้จากโรงเลื่อยทางตะวันตกเฉียงเหนือเลยมาถึงช้าเป็นเต่า ช่วยไปขนมาให้พวกเราสักสองสามมัดได้ไหม?" },
        progress = { "81:1092908400:52146419", "โรงเลื่อยอยู่ทางตะวันตกเฉียงเหนือจากที่นี่ไม่ไกล ถ้าเจ้าผ่านพวกจระเข้กับเมอร์ล็อกไปได้ล่ะนะ" },
        completion = { "134:1570622276:1933382624", "เออ ของพวกนี้ใช้ได้เลย ถ้าไปได้ดีแบบนี้เราอาจทำประตูเสร็จเสียที\n\nดีเหมือนกัน พวกออร์คชักจะดุขึ้นทุกวัน" },
        required = { [271877] = { "11:848259273:430883234", "มัดไม้" } },
        steps = { { "11:848259273:430883234", "มัดไม้" } },
    },
    [96015] = { -- A Miner Problem
        title = { "15:1628878121:965004775", "ปัญหาคนงานเหมือง" },
        objective = { "7:1265997621:1189804897 W1 17:2101447248:653902237 W2 81:362317246:1765161632", "กำจัด Ogre Miner {world1} ตัวและ Twilight Subjugator {world2} คนในถ้ำใกล้ Twilight's Shroud ให้ Sergeant Riftan" },
        description = { "496:1887217598:984337637", "เราควรขอบคุณที่ศัตรูโง่ มีกองทัพโอเกอร์อยู่ในมือแท้ ๆ แต่กลุ่ม Twilight's Hammer กลับส่งไปทำงานในเหมืองไกลจากสนามรบ ข้าไม่รู้ว่าเพราะคุมงานไม่เป็นหรือเพราะแย่งอำนาจกันเอง อย่างไรก็เถอะ ตอนนี้พวกมันป้องกันตัวไม่ไหว\n\nนั่นแหละจังหวะของเรา พวกลัทธิต้องแบ่งกำลังไปดูหลายทาง เราจึงมีโอกาสโจมตีตอนศัตรูอ่อนแอและทำให้พวกมันยิ่งแตกกัน ไปที่เหมืองแล้วก่อความวุ่นวายในหมู่พวกมันซะ" },
        completion = { "170:935883420:482525966", "ข้าไม่แน่ใจว่าเราเข้าไปพัวพันกับการเมืองแบบไหน แต่โอกร์ตายสักตัว ข้าก็นับเป็นชัยชนะเสมอ ถ้าเรากดดันจนพวกมันตั้งตัวไม่ได้ พวกมันก็จะไม่มีเวลาฟื้นกำลัง" },
        progress = { "161:1048435545:2051398719", "พวกโอกร์ในเหมืองมีอะไรแปลก ๆ ดูเชื่องผิดปกติ พวก Twilight's Hammer จะทำอะไรกับพวกมันก็ช่าง แต่ตอนนี้พวกมันเปิดช่องให้เราเล่นงานเต็มที่" },
        objectiveLabels = {
            monster = { ["Ogre Miner slain"] = "ปราบ คนขุดแร่เผ่าอ็อกเกอร์", ["Twilight Subjugator slain"] = "ปราบ ผู้กดขี่ Twilight" },
        },
    },
    [94884] = { -- An Unsettling Discovery
        title = { "23:196081688:765014200", "สิ่งที่พบชวนให้หวั่นใจ" },
        objective = { "69:338205300:880048045", "นำ Filled Crystal Catalyst ไปให้ Ashe Amberhall ที่ Farholde Keep" },
        description = { "337:1506741630:196755415", "ข้าอยู่ในถ้ำนี้มาพอแล้ว พอเจ้าเปิดทางออกไปได้ ข้าจะแอบหนีตามไปตอนที่พวกมันกำลังชุลมุน\n\nแต่เกรงว่าข้าจะอ่อนแรงเกินกว่าจะถือตัวอย่างพวกนั้น พลังจากมันรุนแรงเหลือเกิน แสงศักดิ์สิทธิ์เท่านั้นที่รู้ว่าข้าติดอยู่ข้างล่างนี้นานเท่าไร พอออกไปได้ ช่วยเอาตัวอย่างไปให้ท่านหญิง Amberhall ทันทีเถอะ ข้าต้องพัก" },
        completion = { "237:884911479:2082253232", "เจอ Claire แล้วสินะ ดีจริง ๆ\nนางสังหรณ์ถูกแล้ว ข้าดีใจที่เจ้าเอาสิ่งนี้มาให้ พวก Twilight's Hammer คงไม่คิดว่าเราจะตอบโต้กันตรง ๆ แบบนี้ ไว้ข้าคงต้องขอบใจพวกมันที่หาเครื่องปรุงเวทชั้นดีมาให้" },
        progress = { "84:1344958448:1101023150", "ดูเหมือนเจ้าจะเจอของอร่อยเป็นพิเศษ มาสิ เอามาให้ข้าดูหน่อย" },
        required = { [266426] = { "23:963523077:256245014", "ตัวเร่งปฏิกิริยาแบบผลึกที่เติมเต็มแล้ว" } },
        steps = { { "23:963523077:256245014", "ตัวเร่งปฏิกิริยาแบบผลึกที่เติมเต็มแล้ว" } },
    },
    [94887] = { -- Saving Marshal Ryan
        title = { "19:703612378:679275914", "ช่วยจอมพลไรอัน" },
        objective = { "47:109263592:337630412", "ตามหา Marshal Ryan ใน Twilight's Shroud" },
        description = { "312:176325877:404321808", "จอมพล Ryan เป็นคนเก่งที่สุดคนหนึ่งของเรา สายตาที่เฉียบคมและข่าวกรองที่เชื่อถือได้ของเขาสำคัญมากต่อการรบของเรา\n\nรายงานชุดสุดท้ายของเขาพูดถึงป้อมของกลุ่ม Twilight's Hammer ทางตะวันตก ตามหาเขาก่อนจะสายเกินไป เอาสมุดบันทึกของเขาไปด้วย ในนั้นอาจมีเบาะแสว่าจอมพลที่หายไปอยู่ที่ไหน" },
        completion = { "87:369327812:964492177", "<Marshal Ryan แทบไม่ตอบสนองเมื่อเจ้าเข้าใกล้ ดูเหมือนเขาจะล้มลงได้ทุกเมื่อ>" },
        steps = { { "18:1976291041:746909196", "พบ Marshal Ryan" } },
    },
    [94890] = { -- Bring Me His Head
        title = { "17:1935257681:154468978", "เอาหัวมันมาให้ข้า" },
        objective = { "90:1930626905:1093952584", "กำจัด Overlord Kilgar ใน Twilight's Shroud แล้วนำหัวของเขาไปให้ Sergeant Riftan" },
        description = { "479:109791762:3037329", "กำลังได้เปรียบขนาดนี้ เราหยุดไม่ได้แล้ว ทหารที่ช่วยออกมากระหายจะกลับไปสู้ ส่วนเจ้าก็พิสูจน์แล้วว่าฝ่าแนวข้าศึกได้ดีทีเดียว\n\nกลับไปที่ Twilight's Shroud แล้วสะสางงานที่เราเริ่มไว้ หัวหน้าของพวกมันคือออร์คชื่อ Overlord Kilgar มันซ่อนอยู่ลึกในป้อม ขณะที่ลูกน้องกำลังแตกตื่นจนทำอะไรไม่ถูก\n\nถ้าจะจบเรื่องนี้ เอาหัว Kilgar มาให้ข้า พวกขี้ขลาดที่เอาแต่กลัวเทพเจ้าพวกนี้ตัดสินใจเองไม่ได้สักอย่าง" },
        completion = { "98:124075615:1262551698", "ตอนเริ่มออกลาดตระเวน ข้าไม่ได้คิดว่าจะต้องเจอเรื่องแบบนี้ แต่ก็ดีที่เรามาถึงได้ทันเวลา" },
        progress = { "47:417185419:775149798", "มีรายงานอะไรจะดีไปกว่าชัยชนะอย่างเด็ดขาด?" },
        required = { [265837] = { "13:1232046453:611945813", "ศีรษะของ Kilgar" } },
        steps = { { "13:1232046453:611945813", "ศีรษะของ Kilgar" } },
    },
    [94893] = { -- Delivering Closure
        title = { "18:550117479:474843352", "ฝากข่าวเพื่อปิดเรื่องค้างใจ" },
        objective = { "89:647385066:2065601498", "นำ Marshal Ryan's Crest ไปให้ Abigail Lawson ที่ Cathedral Square ใน Stormwind City" },
        description = { "483:1223812300:2000115689", "อย่างนั้นคนสุดท้ายที่เขานึกถึงคือ Abigail หรือ?\n\nข้ารู้ว่าเรื่องนี้ไม่ได้เกี่ยวกับเจ้า สหาย แต่ข้าต้องขอให้เจ้าช่วยแจ้งข่าวการเสียชีวิตของจอมพลแทนข้า Abigail Lawson คู่หมั้นของ Ryan ไม่ได้มากับเราตอนตั้ง Farholde Keep ดูเหมือนทั้งสองจะมีเรื่องไม่ลงรอยกัน ข้าไม่รู้รายละเอียด แต่รู้ว่าตอนนี้นางอยู่ใน Stormwind City\n\nช่วยนำตราประจำตัวของจอมพลไปให้ Terry แทนข้าที ข้าว่าถ้าข้าไปเองคงไม่มีใครอยากเจอ" },
        completion = { "29:648836305:1342516865 C 233:1603177164:2121040632", "ขอบใจที่นำสิ่งนี้มาให้ข้า {class} ข้าเข้าใจแล้วว่าทำไมไอ้ขี้ขลาด Demar ถึงไม่กล้ามาสู้หน้าข้า\nถ้าเจ้าจะอยู่ช่วยพวกเขาต่อ ก็ระวังตัวด้วย Demar เป็นวีรบุรุษ แต่พวกวีรบุรุษก็อย่างนี้ เก่งนักเรื่องพาคนอื่นไปตาย\nไอ้โง่เอ๊ย..." },
        progress = { "426:1475645998:1075602877", "ข้าก็คิดอยู่แล้วว่าสักวันคงมีคนมาถามเรื่อง Ryan\nตอนครอบครัวของเขาถูกฆ่าระหว่างที่พวกออร์คบุก เขาก็เปลี่ยนไป จากที่เคยสู้กับ Horde ด้วยสำนึกในหน้าที่ เขากลับถูกความแค้นกลืนกิน ข้าพยายามชวนเขามาอยู่กับข้าและพ่อแม่ที่ Stormwind แต่เขาไม่ยอม เขาสาบานว่าจะอยู่ที่นั่นจนกว่าจะกำจัดพวกออร์คออกจากบ้านเกิดให้หมด\nตั้งแต่นั้นมาเราก็ไม่ได้คุยกันอีก" },
        logReady = { "89:991261094:385349486", "นำ Marshal Ryan's Crest ไปให้ Terry Lawrence ที่ Cathedral Square ใน Stormwind City" },
        required = { [266428] = { "20:115888066:1129862878", "ตราของจอมพล Ryan" } },
        steps = { { "20:115888066:1129862878", "ตราของจอมพล Ryan" } },
    },
    [94894] = { -- The Twilight Threat
        title = { "19:1700411283:1179730316", "ภัยจากกลุ่มทไวไลต์" },
        objective = { "82:656602262:1537990307", "นำ Kilgar's Head ไปให้ Bolvar Fordragon ที่ Stormwind Keep ใน Stormwind City" },
        description = { "505:1286587895:1374335611", "ท่านหญิง Amberhall เล่าเรื่องที่เจ้าจัดการกับกลุ่ม Twilight's Hammer ให้ข้าฟังแล้ว ข้าทึ่ง แต่ก็อดกังวลไม่ได้\n\nเดิมที Farholde เปิดศึกเพื่อขับไล่ฮอร์ดออกจากบ้านเกิดเรา นั่นยังเป็นเป้าหมายหลัก แต่เราจะมองข้ามการเคลื่อนไหวของพวกลัทธิที่เพิ่มขึ้นกะทันหันไม่ได้ หาก Stormwind ยังเพิกเฉยต่อคำขอของเรา เราจะรับมือศึกสองด้านตามลำพังไม่ไหว\n\nหลักฐานที่เจ้าถือไปอาจทำให้พวกเขายอมวางทิฐิแล้วฟังเราสักครั้ง ตอนนี้เรามีทางเลือกอยู่เท่านี้" },
        completion = { "435:1918306679:659079461", "ข่าวนี้น่าหนักใจจริง ๆ สหาย แต่แทบไม่เปลี่ยนอะไร เราอยู่ในสงครามที่ใหญ่กว่าหมู่บ้านเล็ก ๆ แห่งเดียวชายขอบดินแดน Alliance มาก เราไม่มีทรัพยากรจะหนุนการล้างแค้นส่วนตัว\nภัยจาก Horde เผาผลาญบ้านเรือนมาแล้วอีกมากนอกเหนือจาก Riverglades ถ้า Brant ยอมวางศักดิ์ศรีลงบ้าง เขากับกองทหารม้าคงทำประโยชน์ให้ Alliance ได้มาก แต่มาถึงตอนนี้ข้าคงหวังอะไรไม่ได้แล้ว" },
        progress = { "92:552164049:992771879", "ข่าวจาก Farholde รึ? ผ่านมาตั้งนาน ผู้บัญชาการอัศวินเพิ่งยอมฟังเหตุผลเสียทีหรือ?" },
        logReady = { "82:656602262:1537990307", "นำ Kilgar's Head ไปให้ Bolvar Fordragon ที่ Stormwind Keep ใน Stormwind City" },
        required = { [265837] = { "13:1232046453:611945813", "ศีรษะของ Kilgar" } },
        steps = { { "13:1232046453:611945813", "ศีรษะของ Kilgar" } },
    },
    [94907] = { -- A Small Favor
        title = { "13:1670050987:1344092488", "ขอให้ช่วยอีกนิด" },
        objective = { "111:158274339:1313763006", "อัญเชิญ Twilight's Thrall จากสื่อนำพลังใน Twilight Shroud แล้วจับด้วย Amberhall's Soulstone" },
        description = { "31:1777722625:1020948576 C 464:1726272054:853563170", "เจ้าเป็น{class}ตัวน้อยที่ช่วยข้ามาตลอด ขอให้ช่วยอะไรอีกสักอย่างได้ไหม?\n\nวัตถุดิบที่เจ้าเก็บมาประสานกับเวทของกลุ่ม Twilight's Hammer ได้ดี เหมาะมากกับพิธีอัญเชิญ แต่เราต้องนำมันไปที่ต้นกำเนิดพลัง\n\nถ้าระหว่างที่เจ้าเที่ยวไปทั่ว Twilight's Shroud แล้วเจอสื่อนำพลัง ลองเรียกทาสของลัทธิออกมาสักตนแล้วจับด้วยศิลาวิญญาณนี้ให้ข้าที เอาไว้สอบปากคำแน่นอนจ้ะ" },
        completion = { "243:1618026074:945411281", "ดูซิว่าเจ้าเอาอะไรมา! สภาพสะบักสะบอมไปหน่อย แต่ใช้เป็นคนรับใช้ได้ดีแน่! พวก Twilight's Hammer เชี่ยวชาญศาสตร์มืดจริง ๆ ว่าไหม?\nอ้อ อยากได้ข้อมูลหรือ? ได้สิ สั่งมาเมื่อไร เราก็สอบปากคำสัตว์เลี้ยงตัวใหม่ของข้าได้เลย!" },
        required = { [268646] = { "21:113828424:161529286", "ศิลาวิญญาณของ Amberhall" } },
        steps = { { "24:1266899973:2004780678", "จับ Twilight Thrall" } },
        objectiveLabels = {
            item = { ["Amberhall's Soulstone"] = "ศิลาวิญญาณของ Amberhall" },
        },
    },
    [94923] = { -- Hats Off
        title = { "8:139271544:78311135", "หมวกหาย" },
        objective = { "61:1698230504:1849895526", "ตามหา Robbie's Hat แถวริมแม่น้ำใกล้พวกเมอร์ล็อก" },
        description = { "384:945229383:704317336", "<Robbie โน้มตัวเข้ามากระซิบราวกับกำลังบอกความลับสำคัญ>\n\nชู่ว์! นี่ คุณผู้ชาย ช่วยผมหน่อยได้ไหม!\n\nพี่สาวซื้อหมวกให้ผมวันเกิด แต่ผมทำหายตอนลงไปเล่นในแม่น้ำ ผมถูกห้ามไปแถวนั้นเพราะมีพวกเมอร์ล็อก จะขอให้พ่อหรือ Ellie ช่วยก็ไม่ได้ เดี๋ยวเขารู้ว่าผมไปไหนมา!\n\nหมวกใบนั้นดีมากเลย ผมว่าต้องมีเมอร์ล็อกสักตัวเก็บเอาไปเป็นของตัวเองแน่ ๆ!", variants = { { "382:1577696293:768764920", "<Robbie โน้มตัวเข้ามากระซิบราวกับกำลังบอกความลับสำคัญ>\n\nชู่ว์! นี่ คุณผู้หญิง ช่วยผมหน่อยได้ไหม!\n\nพี่สาวซื้อหมวกให้ผมวันเกิด แต่ผมทำหายตอนลงไปเล่นในแม่น้ำ ผมถูกห้ามไปแถวนั้นเพราะมีพวกเมอร์ล็อก จะขอให้พ่อหรือ Ellie ช่วยก็ไม่ได้ เดี๋ยวเขารู้ว่าผมไปไหนมา!\n\nหมวกใบนั้นดีมากเลย ผมว่าต้องมีเมอร์ล็อกสักตัวเก็บเอาไปเป็นของตัวเองแน่ ๆ!" } } },
        progress = { "64:291983276:518864396", "โอย... Ellie ต้องโกรธมากแน่ ๆ ถ้ารู้ว่าข้าทำหมวกใบนั้นหาย" },
        completion = { "67:117066931:428981847", "หมวกของข้า! โอ้ ขอบคุณ ขอบคุณ ขอบคุณครับท่าน! ท่านสุดยอดเลย!" },
        required = { [266884] = { "12:189887150:1429487445", "หมวกของ Robbie" } },
        steps = { { "12:189887150:1429487445", "หมวกของ Robbie" } },
    },
    [94925] = { -- A Fur Trade
        title = { "11:805291736:40456463", "แลกเปลี่ยนขนสัตว์" },
        objective = { "44:658778989:1465002805", "นำ Prized Lion Hide 8 ผืนไปให้ Watcher Terral" },
        description = { "474:197741964:1636920210", "Farholde ภูมิใจที่พึ่งตัวเองได้ แต่ของบางอย่างเราต้องแลกมาจากคนอื่น\n\nเราตกลงกับแม่ค้าคนหนึ่งที่ Powderfuse Port เราหาของที่เสี่ยงอันตรายมาให้ นางก็จัดหายุทโธปกรณ์เฉพาะทางให้เรา\n\nตอนนี้นางกำลังหาขนสิงโต มีฝูงหนึ่งอยู่บนเนินใหญ่กลางทุ่ง ถ้าอยากช่วย ก็ไปหาหนังสิงโตมาให้ข้าสักหน่อย" },
        completion = { "69:1730854855:81131441", "ใช่ พวกนี้ใช้ได้ดี เดี๋ยวข้าห่อให้เจ้าถือไปส่ง" },
        progress = { "25:1701341780:1015225425 C 35:676945346:1159996800", "สิงโตล่าเป็นฝูงนะ {class} ระวังอย่าให้มันล้อมเจ้าได้" },
        required = { [266888] = { "16:211034752:197613263", "หนังสิงโตชั้นดี" } },
        steps = { { "16:211034752:197613263", "หนังสิงโตชั้นดี" } },
    },
    [94927] = { -- Dunston Checks Out
        title = { "18:1981171777:211811656", "ดันสตันแหกคุก" },
        objective = { "69:719913534:1274141209", "ช่วย Dunston หนีจาก Bolder'ok แล้วกลับไปหา Watcher Cornelius" },
        description = { "377:760139362:1863259221", "เมื่อเจ้าพร้อม ข้าจะไขตรวนแล้วเราค่อยหนี เราจะใช้ทางที่เร็วที่สุด ฝ่ากลางค่ายไปเลย เตรียมตัวสู้ไว้ด้วย\n\nพอออกไปได้ ข้าจะกลับ Farholde ไปรักษาตัว ขอฝากอีกอย่าง ช่วยไปบอก Cornelius ด้วยว่าข้าอยู่ไหน พูดตรง ๆ ผ่านมาขนาดนี้ สิ่งสุดท้ายที่อยากเจอคือโดนหมอนั่นบ่นใส่หู" },
        completion = { "162:1189490919:354771509", "Dunston กลับ Farholde ไปแล้วรึ? ในที่สุด! เจอกันคราวหน้า เขาต้องเลี้ยงเหล้าพวกเรา\nขอบใจที่ช่วยนะ ในที่สุดข้าอาจได้เห็นเตียงจริง ๆ สักที" },
        objectiveLabels = {
            event = { ["Help Dunston break out of Bolder'ok"] = "ช่วย Dunston แหกคุกออกจาก Bolder'ok" },
        },
    },
    [94928] = { -- A Few Furs for Friz
        title = { "19:138775023:134728901", "ขนสัตว์ส่งให้ฟริซ" },
        objective = { "73:2091436709:245978268", "นำ Bundle of Lion Hides ไปให้ Friz Frazzlespark ที่ Powderfuse Port" },
        description = { "275:275112538:149628634", "ต้องเอาหนังพวกนี้ไปส่งที่ Powderfuse Port เป็นท่าเรือของพวกก็อบลินทางตะวันออกเฉียงเหนือ\n\nไปถึงแล้วเอาหนังไปให้ Friz Frazzlespark บอกนางว่ามาจาก Cornelius เราตกลงรายละเอียดกันไว้แล้ว นางรู้เองว่าเอาไปทำอะไร" },
        progress = { "19:1569733373:570756051", "มีอะไรมาให้ข้าล่ะ?" },
        completion = { "203:680012654:404405980", "Cornelius ไม่มาส่งของพวกนี้เองแล้วหรือ? โล่งอกไปที! ข้าทนหมอนั่นไม่ไหวจริง ๆ\n\n<Friz ตรวจดูของในห่อ>\n\nดูใช้ได้นี่ บอกคนของเจ้าที่ Farholde ให้ส่งมาเรื่อย ๆ ล่ะ" },
        required = { [267263] = { "20:1896145760:1658211150", "มัดหนังสิงโต" } },
        objectiveLabels = {
            item = { ["Bundle of Lion Pelts"] = "มัดหนังสิงโต" },
        },
    },
    [94992] = { -- Rescue Roundup
        title = { "14:1228150923:1727058650", "พาม้าที่หลงกลับบ้าน" },
        objective = { "46:637532352:474094553", "พาม้าที่หลงกลับไปที่ Wheeler's Grange" },
        description = { "116:1816493416:859732986", "<ม้าก้มหัวเข้าหาเจ้า แล้วเอาจมูกมาดุนใต้แขนเบา ๆ ดูท่าว่าเจ้าไปไหนมันก็อาจเดินตามไปด้วย>" },
        completion = { "52:280501761:1971278907 N 202:1306847843:231684416", "ขอบใจที่ช่วย Biscuit ของข้า! เจ้าเป็นเพื่อนแท้เลย {name}\n\nดีใจที่ได้นางกลับมา แต่ก็อดใจหายไม่ได้ที่นางต้องอยู่ลำพังสักพัก หวังว่าเราจะหาเพื่อนร่วมคอกของนางเจออีกสักสองสามตัวในเร็ว ๆ นี้\n\nคราวหน้าเจอตา Demar ก็บอกเขาทีว่า Wheeler's Grange กลับมาเปิดแล้ว!" },
        objectiveLabels = {
            event = { ["Escort the lost horse to Wheeler's Grange."] = "พาม้าที่หลงทางไปยัง Wheeler's Grange" },
        },
    },
    [95957] = { -- Drink Up!
        title = { "9:447059518:752550727", "ดื่มให้หมด!" },
        objective = { "70:336950460:1484554545", "นำ Zizplink's Frothing Mug ไปให้ Gray Dawnbright ที่ Powderfuse Port" },
        description = { "185:2138798061:1018063919", "เอ้า คนเก่ง เครื่องดื่มแก้วนึงสำหรับตาขี้หงุดหงิดตรงโน้น ถ้านี่ไม่ทำให้สร่าง ก็ไม่มีอะไรทำได้แล้ว\n\nอ้อ แล้วก็... จับแล้วล้างมือด้วยนะ ระวังอย่าให้เข้าตา" },
        completion = { "198:1318125464:1932669372", "<Gray รับเครื่องดื่มไปกระดกอึกใหญ่ แล้วเริ่มไอสำลักของเหลวประหลาด>\nใส่อะไรลงไปเนี่ย? รสชาติแทบเอาชีวิตข้า! เออ ๆ ข้าฟังอยู่ ต้องการอะไร?" },
        progress = { "106:911166404:1969213358", "อ้าว เจ้าอีกแล้ว ข้าบอกแล้วว่าข้ากลับไป Farholde ไม่ได้ ยังไม่ใช่ตอนนี้\nแต่ถ้ามีเหล้าอีกแก้ว ข้าก็ไม่ปฏิเสธหรอก" },
        required = { [271822] = { "12:212634800:2145273157", "แก้วเครื่องดื่มฟองฟู" } },
        steps = { { "12:212634800:2145273157", "แก้วเครื่องดื่มฟองฟู" } },
    },
    [95961] = { -- Stepped Out
        title = { "11:383505518:84178296", "ออกไปข้างนอก" },
        objective = { "40:1051341048:759527812", "ตามหา Gray Dawnbright ที่ Powderfuse Port" },
        description = { "181:481482663:911289855 N 312:2137741014:1575842086", "<ลูกของ Tessa ยังร้องไห้เสียงดังไม่หยุด>\n\nดูท่าลูกคงไม่ได้เหนื่อย เฮ้อ... เห็นคนอื่นทำเหมือนง่ายกันหมด พ่อของลูกกล่อมให้หายงอแงได้ทุกที ถ้าเขากลับมาสักทีคงดี\n\n{name} ข้าไม่อยากรบกวนเลย แต่ช่วยไปดูได้ไหมว่าทำไมเขาถึงไปนานนัก เขาออกไปพักใหญ่แล้ว ป่านนี้น่าจะกลับถึงบ้าน เอ็มมายิ้มหน้าบานทุกทีที่เห็นพ่อ\n\nน่าจะหาเขาเจอที่ Powderfuse Port ช่วงนี้เขาไปที่นั่นบ่อย พอเห็นก็จะรู้เองว่าคนไหนคือ Gray ของข้า เขาสดใสอย่างกับดวงอาทิตย์เลย" },
        completion = { "333:219255452:1367678719", "Tess ส่งเจ้ามาหรือ? ไม่... ข้ากลับบ้านไม่ได้ ข้าสู้หน้าพวกเขาไม่ไหว\n\nเราคิดยังไงถึงได้ให้ลูกสาวตัวน้อยเกิดมาในโลกแบบนี้? เราปกป้องนางไม่ได้ ขนาดตัวเองยังแทบเอาไม่รอด เราจะรับปากเรื่องอนาคตแบบไหนกับนางได้? มีแต่สงครามอีกหรือ? ตอนนั้นเราคิดอะไรกันอยู่...\n\nขอร้อง อย่าบอก Tessa เลย เดี๋ยวข้าก็กลับเอง สักวันน่ะ\n\nตอนนี้ข้าขอดื่มอีกแก้วก็พอ" },
    },
    [96081] = { -- Wound Dressings
        title = { "15:413988438:123516391", "ผ้าพันแผล" },
        objective = { "62:635328542:311541319", "รวบรวม Mageweave Cloth 20 ผืนให้ Brother Lowley ที่ Farholde Keep" },
        description = { "419:385731682:2029887405", "สิ่งที่กองกำลังต้องใช้อยู่เสมอคือผ้าพันแผล น่าเสียดายที่ Farholde ผลิตผ้าเองได้ไม่แน่นอน เราเลยต้องซื้อจากพวกก็อบลิน หรือถ้าโชคดีก็ใช้ของที่ยึดมาจากพวกออร์คได้\n\nตอนนี้ผ้าเนื้อดีใกล้หมดแล้ว อีกไม่นานข้าคงต้องเอาเสื้อเก่ามาทำผ้าพันแผล ถ้าเจ้าพอช่วยได้ เจ้าจะช่วยชีวิตคนไว้ได้มากทีเดียว" },
        completion = { "11:1191658970:1224418299 N 47:2055039329:150492542", "ขอบใจ {name} อีกเดี๋ยวเจ้ากับข้าคงได้ใช้ของพวกนี้ให้เป็นประโยชน์" },
        progress = { "41:132628186:884356652", "หาเนื้อผ้าที่ข้าขอมาได้บ้างหรือยัง?" },
        required = { [4338] = { "15:1283357618:289024293", "ผ้า Mageweave" } },
        steps = { { "15:1283357618:289024293", "ผ้า Mageweave" } },
    },
    [96082] = { -- Doctor's Orderly
        title = { "16:826617416:383538536", "ผู้ช่วยหมอ" },
        objective = { "49:1685406723:72037930", "พันแผลให้ Wounded Soldier 3 นายตามที่ Brother Lowley ขอ" },
        description = { "316:482823865:1435407342", "ข้าจะเอาผ้าที่เจ้าให้มาทำผ้าพันแผล ระหว่างนั้นช่วยเอาผ้าพันแผลที่ข้าทำไว้แล้วไปปิดแผลให้ทหารที่ต้องการที แค่ปฐมพยาบาลเบื้องต้นก็พอ\n\nข้าขอบใจมากที่เจ้ามาช่วย งานนี้จำเป็นจริง ๆ ข้าไปดูแลทุกคนพร้อมกันไม่ได้" },
        completion = { "194:631111374:1143086695", "ทำได้ดี เท่านี้พอใช้ไปก่อน\nอย่างน้อยก็จนกว่าแผลของพวกเขาจะเปิดอีก หรือมีทหารคนใหม่ถูกหามเข้ามา...\n<Brother Lowley คลึงขมับอยู่ครู่หนึ่ง ก่อนกลับมาวางท่านิ่งขรึมดังเดิม>" },
        progress = { "22:781355040:8678100", "พวกทหารเป็นอย่างไรบ้าง?" },
        required = { [272126] = { "18:1127271614:1557964810", "ผ้าพันแผลทำขึ้นเฉพาะหน้า" } },
        steps = { { "23:1743941903:1228992517", "รักษาทหารที่บาดเจ็บ" }, { "18:1127271614:1557964810", "ผ้าพันแผลทำขึ้นเฉพาะหน้า" } },
    },
    [96084] = { -- Something's in the Water
        title = { "24:1668482984:568845182", "มีบางอย่างปนอยู่ในน้ำ" },
        objective = { "101:545972747:1634689756", "เก็บตัวอย่างน้ำดื่มจากทุ่งกว้างไปให้ Sister Rowland ที่โบสถ์ใน Farholde Keep" },
        description = { "487:2016099322:204405689", "ข้าจะละรายละเอียดไม่น่าดูไว้ก็แล้วกัน ทหารพวกนี้ป่วยหนักมาก จากลักษณะอาการ ข้าว่าต้องมีปัญหากับอาหารหรือน้ำที่ดื่มเข้าไป\n\nข้าตรวจพืชผลจากฟาร์มแถวนี้แล้ว เหลือแต่น้ำที่ตักจากแม่น้ำในละแวกนี้ จุดที่เหมาะจะเก็บตัวอย่างคือแอ่งน้ำในทุ่งทางเหนือ แม่น้ำแทบทุกสายไหลผ่านแถวนั้น ควรตรวจที่นั่นว่ามีอะไรปนเปื้อนหรือเปล่า" },
        completion = { "75:571814148:1687452635", "นี่มันดู... น่าขยะแขยง อะไรทำให้น้ำปนเปื้อนได้ขนาดนี้กัน?" },
        progress = { "93:1144165879:1563148902", "ตราบใดที่ยังไม่รู้ต้นเหตุที่ทำให้พวกเขาป่วย ข้าก็ช่วยรักษาคนเหล่านี้ได้เพียงเท่านี้" },
        required = { [281228] = { "23:1884877298:1517749644", "ขวดที่เติมน้ำจืดแล้ว" } },
        steps = { { "23:1884877298:1517749644", "ขวดที่เติมน้ำจืดแล้ว" } },
    },
    [96125] = { -- In Need of Relief
        title = { "17:1629575538:174456345", "ตามหาคนมาเปลี่ยนเวร" },
        objective = { "59:826579714:142713465", "ตามหา Dunston Willis ท่ามกลางพวกโอเกอร์ใน Bolder'ok" },
        description = { "496:922627602:2011253615", "พอเก็บหนังสิงโตครบและกำจัดพวกออร์คล่าสัตว์เถื่อนได้เสียที ในที่สุดข้าก็จะได้พัก\n\nอย่างน้อยข้าคงพูดแบบนั้นได้ ถ้าคนที่ควรมาเปลี่ยนเวรข้าไม่หายตัวไปเสียก่อน\n\nDunston Willis นักสำรวจมือฉมัง ออกไปสำรวจชุมชนโอเกอร์ทางเหนือเมื่อไม่กี่วันก่อน เขาบอกว่าจะมาเข้าเวรแทนข้าเมื่อกลับมา\n\nไปตามหาเขาที ถ้ายังมีชีวิตก็พากลับมา ถ้าถูกแขวนไว้กับตะขอเนื้อ ก็เอาหลักฐานมาให้ข้า Demar จะได้ส่งคนอื่นมาแทน" },
        completion = { "88:242248209:1313128013", "เจ้ามาจาก Terral's Watch หรือ? หึ ป่านนี้ Cornelius คงไม่ค่อยพอใจข้าเท่าไร" },
    },
    [96126] = { -- An Ogre's Captive
        title = { "17:932783510:1812814733", "เชลยของโอเกอร์" },
        objective = { "77:1736223527:497760756", "ตามหา Gronok the Butcher ฆ่ามัน แล้วนำกุญแจไขตรวนไปให้ Dunston" },
        description = { "453:1637144957:1114417265", "ข้าไม่รู้ว่าเจ้าเข้ามาถึงนี่ได้ยังไง แต่ขอให้ฟังข้าก่อน\n\nอย่างที่เจ้ารู้ ข้าเป็นยามของ Farholde Keep\n\nตอนออกลาดตระเวน พวกตัวโตนี่ซุ่มโจมตีแล้วจับข้ามาขัง ตอนนี้มันบังคับให้ข้าลงไปสู้ในลานประลองเพื่อความบันเทิงของพวกมัน\n\nข้าเหลือแรงไม่มากแล้ว ถ้าจะหนี ก็ต้องหนีตอนนี้\n\nโอเกอร์ที่จับข้ามาชื่อ Gronok the Butcher มันถือกุญแจไขตรวนของข้าอยู่ ช่วยเอากุญแจนั่นมาพาข้าออกไปทีได้ไหม?" },
        completion = { "51:332966652:1312359257 N 29:1155215128:1892186738", "เจ้าได้กุญแจมาแล้ว! ยอดเยี่ยม! ข้าไม่รู้จะขอบใจเจ้าอย่างไรดี {name}\nทีนี้พวกเราออกไปจากที่นี่กันเถอะ" },
        progress = { "89:1362679222:1336733643", "ดีใจจริง ๆ ที่ในที่สุดก็มีคนมาพบข้า ข้าไม่รู้ว่าจะทนอยู่ได้อีกกี่วัน" },
        required = { [272190] = { "12:793503417:190638567", "กุญแจของ Gronok" } },
        steps = { { "12:793503417:190638567", "กุญแจของ Gronok" } },
    },
    [95059] = { -- Frazzlespark's Crate
        title = { "20:1431114411:1506537522", "ลังของแฟรซเซิลสปาร์ก" },
        objective = { "78:463913484:1137224588", "นำ Frazzlespark's Crate ไปให้ Knight Commander Demar Brant ที่ Farholde Keep" },
        description = { "270:938161173:1387052986", "ถึงเวลาส่งของพิเศษแล้ว\n\nKnight Commander Demar Brant ที่ Farholde กำลังรอของชิ้นนี้อยู่ ไม่รู้ทำไมเขาต้องให้ข้าเรียกชื่อเต็มทุกที คนอะไรแปลกชะมัด\n\nเอาเถอะ หาเขาได้ในป้อมทางตะวันตกเฉียงใต้ เป็นป้อมหินใหญ่เบ้อเริ่ม มองยังไงก็ไม่พลาด" },
        completion = { "144:34443583:1864957607", "ก็อบลินนั่นเป็นแค่เครื่องมือให้เราไปถึงเป้าหมาย มีข้อตกลงบางอย่างที่เราจำเป็นต้องทำ เพื่อให้คนของเราปลอดภัยและบรรลุสิ่งที่ตั้งใจไว้" },
    },
    [95066] = { -- The Rog'mar Situation
        title = { "21:631775629:863908325", "สถานการณ์ที่ร็อกมาร์" },
        objective = { "51:865728287:1960741553", "นำรายงานไปให้ Demar Brant ที่ Farholde Keep" },
        description = { "142:846763317:447622685", "เราส่งสารไปชัดเจนแล้ว\n\nกลับไปหา Brant ในป้อมแล้วให้เขาดูรายงาน ข้ามั่นใจว่าเขาจะพอใจที่เราเดินหน้าไปได้ขนาดนี้" },
        completion = { "255:2067239538:907990345", "ดูเหมือน Cornelius จะทำหน้าที่ได้ดีทีเดียว แน่นอนว่าได้เจ้าช่วยด้วย\nน่าเสียดายที่การฉลองจะทำให้เราเสียสมาธิจากงานที่เหลือและเปิดช่องให้ศัตรูโดยไม่จำเป็น แต่... เราน่าจะหยุดทบทวนกันสักครู่ว่าเรามาได้ไกลแค่ไหนแล้ว" },
    },
    [95147] = { -- The Lost Scout
        title = { "14:872725530:2050822950", "หน่วยสอดแนมที่หายไป" },
        objective = { "61:772561496:795086081", "นำข้อความของ Bolain ไปให้ Captain Dalton ที่ Southern Watch" },
        description = { "407:1749268175:248840328", "เจ้า... มาจากไหนกัน? เจ้าไม่ควรมาอยู่ที่นี่!\n\n<Bolain ฝืนทนความเจ็บปวด ร่างฟกช้ำสะบักสะบอม ขามีแผลกัดติดเชื้อ>\n\nเอานี่ไปให้ Dalton ขึ้นเหนือตามถนนแล้วไปทางตะวันออก ตรงที่ทุ่งเปิดกว้างยิ่งกว่าแผลฉีกบ้า ๆ ที่ขาข้า ข้าอยากฝากบอกว่าเขาพูดถูก แต่จะไม่ยอมให้เขาได้ใจหรอก... อย่างน้อยก็จนกว่าข้าจะตาย\n\nข้าเกลียดเนินเขาบ้า ๆ นี่!" },
        completion = { "182:1420553592:1903751430", "Bolain ไปไหนนะ?! ไอ้หมอนั่นมัน... ข้าบอกแล้วว่าอย่าไปคนเดียว\n\nดูท่าคนของเราบางคนยังประเมินไอ้พวกโนลล์ต่ำไป ผู้บัญชาการอัศวินต้องอยากรู้เรื่องนี้เดี๋ยวนี้แน่" },
    },
    [95148] = { -- Southern Watch Gnoll Report
        title = { "27:1975706713:821801455", "รายงานเรื่องนอลล์จากเซาเทิร์นวอตช์" },
        objective = { "81:575433099:151814937", "นำ Southern Watch Gnoll Report ไปให้ผู้บัญชาการอัศวินที่ Farholde Keep" },
        description = { "267:91488412:909920454", "ใจจริงข้าอยากเอาข้อความเปื้อนเลือดไปให้ผู้บัญชาการอัศวินด้วยตัวเอง แต่ก็อยากรักษาตำแหน่งไว้ด้วย ข้าเช็ดมันไปบ้างแล้ว จะได้ดู... เอ่อ เลอะเลือดน้อยลง\n\nช่วงนี้พวกนอลล์ลุกฮือขึ้นมาอีก เกรงว่าต้องฝากเจ้านำข่าวไปส่งแทนข้า" },
        completion = { "430:1582860167:2061770763", "เป็นข่าวร้าย แต่ข้าไม่แปลกใจเลย พวกโนลล์เป็นภัยต่อดินแดนแถบนี้มาหลายปีแล้ว\n\nตอนเรามาถึงใหม่ ๆ การสู้รบย่อยปะทุขึ้นไม่หยุดทั่วเนินเขาและที่ราบเบื้องล่าง เราสูญเสียไปมากกว่าจะตั้งหลักและยืนหยัดรักษาพื้นที่ไว้ได้\n\nข้าจะจัดเสบียงกับอาวุธเพิ่มให้ Dalton และคนของเขา พร้อมส่งทหารราบไปช่วยชั่วคราว เราเสี่ยงให้พวกโนลล์ตีฝ่าเข้ามาในเขตของเราอีกไม่ได้" },
    },
    [95562] = { -- Cut Off the Heads
        title = { "17:578183614:968288707", "ตัดหัวพวกมัน" },
        objective = { "94:1333765609:1291299270", "ฆ่า Chogg'Zac ในถ้ำใต้ Sunnyglade แล้วนำหัวไปให้ Apprentice Claire" },
        description = { "502:627500740:2005244074", "ข้ามีเรื่องจะสารภาพ ท่านหญิง Amberhall ส่งข้ามาเก็บตัวอย่างจริง แต่ความจริงข้าเป็นคนอาสา Sunnyglade เคยเป็นบ้านของข้าก่อนที่สงครามจะพรากมันไป ข้าทำใจอยู่เฉยไม่ได้ทั้งที่ยังมีปีศาจย่ำยีบ้านข้า จะเป็นพวกฮอร์ดหรือสาวกทไวไลต์ก็เถอะ\n\nเราเอาชนะพวกมันด้วยการศึกษามันไม่ได้ ไม่มีอะไรให้เรียนรู้ทั้งนั้น พวกมันเป็นแค่สัตว์ร้าย และควรถูกกำจัดอย่างสัตว์ร้าย\n\nเราต้องฆ่าหัวหน้าของพวกมันที่ก้นถ้ำแล้วจบเรื่องนี้เสียที นายหญิงของข้าต้องเข้าใจแน่" },
        progress = { "50:284706260:1653727407 N 30:1855780783:1178257232", "วิญญาณในหมู่บ้านนี้ร้องขอให้ล้างแค้น {name} เราต้องล้างแค้นให้พวกเขา" },
        completion = { "62:357413401:959336484 N 28:1484983116:1803696089", "มันตายแล้วหรือ? เจ้าฆ่าพวกโอเกอร์แล้วหรือ?\n\nเจ้าทำถูกแล้ว {name} ทีนี้เราออกไปจากที่นี่กันเถอะ" },
        required = { [265750] = { "12:1719522912:904062116", "ศีรษะของ Chogg" }, [265751] = { "10:1070448462:1258694193", "ศีรษะของ Zac" } },
        steps = { { "12:1719522912:904062116", "ศีรษะของ Chogg" }, { "10:1070448462:1258694193", "ศีรษะของ Zac" } },
    },
    [95603] = { -- Bats in the Belfry
        title = { "18:831532605:2101216828", "ค้างคาวในหอระฆัง" },
        objective = { "70:441741042:1059847205", "กำจัด Roosting Duskbat 5 ตัวใน Farholde Cathedral ให้ Sister Rowland" },
        description = { "498:393893644:177390951", "ตั้งแต่ Brother Lowley กับข้าหันมารับใช้ Farholde ในงานทางโลกมากขึ้น โบสถ์ก็ถูกทิ้งร้าง ข้าอยากเชื่อว่าเมื่อการสู้รบจบลง เราจะนำแสงศักดิ์สิทธิ์กลับคืนมาที่นี่ได้ แต่เกรงว่าคงอีกนาน...\n\nถึงอย่างนั้นเราก็ต้องดูแลโบสถ์ให้พร้อมใช้ เผื่อวันนั้นมาถึง\n\nมีค้างคาวฝูงหนึ่งขึ้นไปเกาะอาศัยอยู่ชั้นบนของโบสถ์ ถ้าช่วยกำจัดพวกมันได้ก็จะเป็นพระคุณมาก" },
        completion = { "40:179322721:434332296", "เจ้าช่างมีน้ำใจนะ นักรบ ขอบใจมาก" },
        objectiveLabels = {
            monster = { ["Roosting Duskbat slain"] = "ปราบ ค้างคาวสนธยาที่เกาะพัก" },
        },
    },
    [95912] = { -- WANTED: Blademaster Kaijo
        title = { "25:1217122741:382250698", "ประกาศจับ ไคโจยอดนักดาบ" },
        objective = { "70:924962455:1941288437", "นำ Blademaster's Banner ไปให้ Ember Bladewhisper ที่ Farholde Keep" },
        description = { "503:1657572392:1072724796", "ทุกครั้งที่เราฆ่าออร์คได้ตัวหนึ่ง ก็มีอีกตัวมาแทน แถมเก่งกว่าตัวก่อนเสียอีก ต้องมีนักรบฝีมือดีฝึกพวกรุ่นใหม่อยู่ ถ้าอยากลดจำนวนพวกมันลงจริง ๆ เราต้องตัดโอกาสไม่ให้มันเสริมกำลังทดแทนได้\n\nหากมีทหารกล้าพอ เราจำเป็นต้องตามหายอดนักดาบผู้นี้และกำจัดเขา ตอนนี้เขาน่าจะอยู่ที่ค่ายฝึกทางเหนือของด่านฮอร์ด ฆ่าเขา เอาธงมา แล้วทำลายขวัญกำลังใจของพวกออร์ค\n\n— Ember Bladewhisper" },
        completion = { "153:1368502949:1225325059 N 1:46:46", "อาวุธกับเสบียงทำให้ชนะการรบ แต่ขวัญกำลังใจและความเชื่อมั่นทำให้ชนะสงคราม ธงผืนนี้จะทำให้ทหารฝึกหัดของเราเห็นว่า Horde ไม่มีอะไรน่ากลัว\nทำได้ดี {name}" },
        progress = { "172:1552600473:1894830489", "ภัยจากพวกออร์คดูเหมือนจะไม่มีวันจบ ทหารของเราเริ่มหมดกำลังใจ ถ้าเราไม่รีบจัดการพวกผู้นำของมัน ข้ากลัวว่าศึกนี้จะจบตั้งแต่ยังไม่ได้เริ่ม" },
        required = { [271425] = { "20:1869432079:1267866607", "ธงของปรมาจารย์ดาบ" } },
        objectiveLabels = {
            item = { ["Blademaster's Banner"] = "ธงของปรมาจารย์ดาบ" },
        },
    },
    [95935] = { -- Hail the Dragonslayer
        title = { "21:1831208003:262484333", "สดุดีผู้สังหารมังกร" },
        objective = { "66:665746243:1741622871", "นำ Head of Scaldaron ไปให้ Cedric Dalton ที่ Southern Watch" },
        description = { "304:1974448336:2113884085", "หัวมังกรเต็มไปด้วยเขี้ยว เกล็ด และเถ้าถ่าน เป็นของรางวัลน่าสยดสยองจากสัตว์ร้ายที่น่าสยดสยอง พอถือขึ้นมา เจ้ารู้สึกถึงความร้อนจากลมหายใจเพลิงครั้งสุดท้ายที่ยังแผ่ออกจากปากมัน\n\nแม้ภัยจาก Scaldaron จะหมดไปแล้ว แต่ยามที่ Southern Watch ควรรู้ว่าเกิดอะไรขึ้นที่นี่" },
        completion = { "245:1049698857:136358044", "ให้ตายสิ ข้านึกว่าบนเนินเขามีแค่พวกโนลล์ให้กังวลเสียอีก!\nแต่ตอนนี้คงเป็นอย่างนั้นจริง ๆ แล้วละ ในเมื่อเจ้าเอาหัวนี้มาให้ข้า ข้าคงต้องขอบใจเจ้าแล้ว\nทำได้ดี ทหาร เจ้าใจเด็ดจริง ๆ" },
        progress = { "56:1731424241:66602995", "ตัวเจ้ามีแต่รอยไหม้ ไปทำอะไรมาเนี่ย?" },
        required = { [271612] = { "17:199013013:1695613642", "ศีรษะของ Scaldaron" } },
        steps = { { "17:199013013:1695613642", "ศีรษะของ Scaldaron" } },
    },
    [92858] = { -- WANTED: Ohk'zi
        title = { "14:1171487655:1650190928", "ประกาศจับ โอคซี" },
        objective = { "76:561375128:1552466743", "นำ Staff of Ohk'zi ไปให้ Latronicus Moonspear ที่ Feathermoon Stronghold" },
        description = { "343:830717234:1880532620", "ตามคำสั่งของแม่ทัพ Feathermoon\n\nตั้งค่าหัวสำหรับผู้ที่สังหารโอเกอร์ชื่อ Ohk'zi แม้พวกโอเกอร์ Gordunni จะเป็นภัยเร่งด่วนน้อยกว่าพวกนากา แต่ก็ยังคุกคามดินแดน Feralas เช่นกัน\n\nมีผู้พบ Ohk'zi ครั้งสุดท้ายที่ด่าน Gordunni ทางตะวันออก ผู้ที่นำหลักฐานการตายของมันมามอบจะได้รับรางวัล\n\n— Latronicus Moonspear" },
        completion = { "106:202489117:1561188211", "เข้าใจแล้ว ทำได้ดีมาก\nข้ายินดีมอบรางวัลนี้ให้เจ้าตามสัญญา เจ้าได้ช่วยชาว Feralas ทั้งแคว้นไว้มากทีเดียว" },
        progress = { "38:612815771:446274294", "มารับเงินรางวัลค่าหัว Ohk'zi หรือ?" },
        required = { [254692] = { "15:938910261:683909516", "ไม้เท้าของ Ohk'zi" } },
        steps = { { "15:938910261:683909516", "ไม้เท้าของ Ohk'zi" } },
    },
    [92914] = { -- Strange Pylons
        title = { "14:1041238868:630324789", "เสาพลังปริศนา" },
        objective = { "77:764612559:1211614635", "สำรวจ Shen'dralas เพื่อหาเสาพลังต้นอื่นที่เหมือนต้นที่เจ้าพบ" },
        description = { "394:1473039800:1507684090", "<เจ้าเข้าไปใกล้ผลึกประหลาดที่เมื่อครู่ยังมีธาตุมานาร่างซูบผอมเฝ้าอยู่\n\nแท่นรองผลึกดูเก่าแก่ แต่ทรุดโทรมน้อยกว่าซากอารยธรรมเอลฟ์ที่อยู่ข้างใต้อย่างเห็นได้ชัด\n\nอัญมณีที่แตกร้าวส่งเสียงฮัมแผ่ว ๆ แต่เวทมนตร์ในนั้นแทบหมดแล้ว จึงยังบอกไม่ได้ว่ามันมีไว้ทำอะไร\n\nบางทีแถวนี้อาจมีอะไรให้ค้นพบอีก>" },
        completion = { "467:1779874326:1656643928", "ได้ยินว่าผลึกในวิหารยังส่องสว่าง ก็เหมือนยกภูเขาออกจากอก ข้ากังวลว่าพวกเซนทอร์จะบุกถึงเขตวิหารแล้วด้วย แต่ดูเหมือนสิ่งที่อยู่ข้างในยังทำให้พวกมันไม่กล้าเข้าไป\nส่วนเสาต้นอื่น ๆ ถ้าพวกวิญญาณธาตุยังยืนเฝ้าอยู่ เราก็น่าจะฟื้นสภาพเสาเหล่านั้นได้\nหวังว่าผู้อาศัยในวิหารจะไม่ได้ทำให้เจ้าตกใจ พวกเขาเป็นมิตรดี เพียงแต่ขมขื่น ซึ่งก็เข้าใจได้" },
        steps = { { "19:1241000:1905528608", "พบเสาพลังทางตะวันตก" }, { "19:113832948:1854913633", "พบเสาพลังทางตะวันออก" }, { "18:922066642:1069984003", "พบเสาพลังที่วิหาร" } },
    },
    [93362] = { -- What They've Done to My Peonies
        title = { "31:1523150982:1671322155", "พวกมันทำอะไรกับดอกโบตั๋นของข้า" },
        objective = { "76:698620236:1717805997", "กำจัดพืชบางส่วนใน Forlorn Garden แล้วกลับไปหา Mithera ที่ Shen'dralas" },
        description = { "163:1019199791:839374739 N 322:67907835:960274398", "อย่าเล่าเลยว่าชีวิตในสวนนั้นถูกบิดเบือนไปอย่างไร ข้าเสียใจเรื่องสร้อยคอที่หายไปมากพอแล้ว\n\nแต่ขณะที่ข้าร่ำไห้ ต้นไม้พวกนั้นกำลังทรมาน\n\n{name} ข้าอยากให้เจ้ากลับไปที่สวนแล้วกำจัดพืชที่เกรี้ยวกราดไปบ้าง ขอให้ลงมือเร็วและเมตตาพวกมัน พวกมันเจ็บเป็น และเจ็บมามากพอแล้ว ถ้าเจ้าจะตามหาสร้อยข้าด้วย ช่วยหาก่อนกลับไปที่สวน เผื่อว่าเจ้าจะโชคดีหาเจอ แม้โอกาสจะน้อยก็ตาม" },
        objectiveLabels = {
            monster = { ["Rowdy Rose slain"] = "ปราบ กุหลาบเกเร", ["Terrible Tulip slain"] = "ปราบ ทิวลิปตัวร้าย", ["Malevolent Marigold slain"] = "ปราบ ดาวเรืองอาฆาต" },
        },
    },
    [93394] = { -- Meeting the Magister
        title = { "20:689911754:805122422", "พบผู้ใช้เวท" },
        objective = { "58:1517283089:1850038157", "ตามหา Magister Kirandis ในวิหาร Shen'dralas" },
        description = { "361:688640425:1732919521", "ข้าเดาว่าเจ้าคงอยากรู้อยากเห็นจนอดไปดูอาคารใหญ่โตนั่นไม่ได้แล้วใช่ไหม? ดีเลย!\n\nพวก Shen'dralar ที่นั่นคงไม่ต้อนรับเจ้าอย่างอบอุ่น แต่ถ้าวางตัวให้สุภาพ ข้าว่าเจ้าคงไม่เจอปัญหาอะไร\n\nถ้าโชคดี เจ้าคงหา Kirandis สหายเก่าของข้าเจอไม่ยาก ในบรรดาคนที่นั่น เขาน่าจะเป็นมิตรกับเจ้ามากที่สุด" },
        completion = { "361:1156704885:294777585", "น่าทึ่งจริง ๆ พลังของเสาพลังกลับมาส่องสว่างอีกครั้ง ข้าแปลกใจที่ไม่ทันสังเกตก่อนเจ้ามาถึง ข้าเริ่มนึกว่าเสาต้นนี้คงลงเอยแบบเดียวกับต้นอื่น และพวกเราคงเลือนหายไปตามกาลเวลา\n\nขอบใจที่ช่วยยึดโยงพวกเรากับ Shen'dralas ไว้ได้อย่างสมบูรณ์อีกครั้ง ลองไปทำความรู้จักคนที่นี่ดูบ้าง พวกเขาอาจระแวงเจ้าในตอนแรก แต่เดี๋ยวก็หาย" },
    },
    [93450] = { -- Phantasmal Problems
        title = { "19:41011997:809322715", "ปัญหาของคนไร้ร่าง" },
        objective = { "143:1686163425:1514999032", "นำดาบที่ Vindael ตีค้างไว้ไปหาวิธีส่งเข้าสู่แดนวิญญาณ แล้วนำ Phantasmal Blade กลับไปให้เขาที่ Shen'dralas" },
        description = { "504:1258818777:1093377239", "อย่างที่เจ้ารู้ การมีร่างกายก็ลำบากอยู่บ้าง แต่พอไม่มีร่างแล้วเรื่องมันคนละอย่างเลย ข้าจะนั่งทะลุเก้าอี้ตัวนี้ไหม? แล้วจะสะดุดแมวตัวนั้นหรือเปล่า? แย่ที่สุดคือมันทำให้ข้าทำงานประจำวันไม่ได้เลย!\n\nเห็นดาบบนทั่งข้าไหม? ข้าเริ่มตีมันเมื่อหลายพันปีก่อน แต่ตายเสียก่อนจะเสร็จ ตอนนี้มันทั้งอยู่ให้ข้าเจ็บใจและกินพื้นที่ทำงานอันมีค่า! ข้าทำอะไรกับมันไม่ได้ ขยับมันยังไม่ได้เลย!\n\nข้าอยากให้เจ้าช่วย เอ่อ ‘พาข้าม’ ไปแดนวิญญาณหน่อย ว่าอย่างไร?" },
        required = { [258735] = { "16:51453414:859063343", "ดาบมายา" } },
        steps = { { "16:51453414:859063343", "ดาบมายา" } },
    },
    [93546] = { -- Spectral Iron Ore
        title = { "17:1852327515:127417217", "แร่เหล็กวิญญาณ" },
        objective = { "65:1896292621:794101467 W1 80:1215410114:412244083", "หา Spectral Iron Deposit รอบ Shen'dralas แล้วเก็บ Spectral Iron Ore {world1} ก้อน เมื่อได้พอแล้วให้กลับไปหา Vindael ที่ Shen'dralas" },
        description = { "502:2060656911:337139089", "ในที่สุด ในที่สุดข้าก็ได้ใช้ทั่งนี่ทำอย่างอื่นนอกจากตั้งเป็นโต๊ะหนักอึ้งเสียที ดีใจจริง ๆ ที่จะได้ฝึกฝีมืออีกครั้งหลังจากไม่ได้จับงานมาหลายศตวรรษ\n\nตอนนี้เจ้าคงคิดว่า ‘Vindael ฟังดูเหมือนเจ้ากำลังจะขออะไรอีกแล้ว’ คิดถูกเสียด้วย!\n\nข้าต้องหาเหล็กมาเติมคลัง แต่เหล็กของเจ้ามีปัญหาแบบเดียวกับดาบข้า โชคดีที่เรื่องนี้แก้ง่ายกว่ามาก\n\n<เขายื่นอีเต้อโปร่งแสงให้โดยไม่เปิดโอกาสให้เจ้าปฏิเสธ>" },
        completion = { "262:1028484785:265036446", "โห ได้มาตั้งเยอะ! เจ้าช่วยเหลือคนอื่นได้มากจริง ๆ สำหรับคนที่ต้องเสียเวลานอนถึงหนึ่งในสามของชีวิต เอาเวลาที่ไหนมาช่วยคนแปลกหน้ากันนี่?\nอ้อ รางวัลหรือ? เจ้าคาดว่าจะได้รางวัลหรือ?\nอืม ข้าว่าข้ายังไม่พร้อมจะให้รางวัลเจ้าตอนนี้หรอก" },
        progress = { "76:1860405230:1600878487", "เกรงว่าเหล็กธรรมดาจะใช้ไม่ได้ ถึงตอนนี้ข้ามั่นใจว่าเจ้าเข้าใจแล้วว่าทำไม" },
        required = { [259226] = { "17:1852327515:127417217", "แร่เหล็กวิญญาณ" } },
        steps = { { "17:1852327515:127417217", "แร่เหล็กวิญญาณ" } },
    },
    [93574] = { -- Corpsefeeder's Carapace
        title = { "23:630673037:531401113", "เปลือกของคอร์ปส์ฟีดเดอร์" },
        objective = { "51:2002852717:1694675167", "ตามหาคนที่สนใจ Corpsefeeder's Carapace" },
        description = { "440:1124994552:1702535553", "<พอหนอนตาย เจ้าก็หักเปลือกแข็งของมันออกมาชิ้นหนึ่งพร้อมเสียงกร๊อบน่าขนลุก\n\nแม้จะใหญ่โตและหนักเอาเรื่อง แต่มันกลับธรรมดาจนน่าผิดหวัง ดูเหมือนสัตว์ตัวนี้ไม่ได้เกิดจากการทดลองโหดร้ายหรือถูกเพาะพันธุ์มาให้กลืนกินทุกอย่าง\n\nเป็นแค่เปลือกที่ดูน่าทึ่ง น่าจะมีแต่นักสะสมที่อยากได้ บางทีอาจหาได้สักคน แต่ถ้าไม่นับพวกเซนทอร์แล้ว แถวนี้ยังมีใครมีชีวิตอยู่อีกหรือ?>" },
        required = { [259893] = { "23:630673037:531401113", "กระดองของ Corpsefeeder" } },
        steps = { { "23:630673037:531401113", "กระดองของ Corpsefeeder" } },
    },
    [93594] = { -- Word of the Woods
        title = { "17:358070307:1414693604", "ข่าวจากพงไพร" },
        objective = { "68:1546124204:321390701", "ตามหา Woodwyrd ใน Forlorn Gardens ที่ Shen'dralas ใน Desolace" },
        description = { "472:1586187790:1882704627", "ในบรรดาทรีแอนต์ที่ถือกำเนิดจากสร้อยคอ มีตนหนึ่งโดดเด่นกว่าใครในหมู่ผู้ได้รับชีวิตและความรู้คิด ถ้าตนอื่นล้มตายไปแล้ว เขาอาจเป็นเพียงตนเดียวที่เหลืออยู่\n\nกลางวันเขาคอยดูแลดอกไม้ทุกดอกและหน่ออ่อนทุกหน่อ พอตกเย็นก็หยั่งรากลงดินให้สัตว์ตัวเล็ก ๆ มาอาศัย\n\nถ้าเขายังมีชีวิต และข้าขอภาวนาให้เป็นเช่นนั้น เขาอาจรู้ว่าเกิดอะไรขึ้น\n\nข้ายังฝากความหวังไว้กับ Woodwyrd เพื่อนรักของข้า" },
    },
    [93644] = { -- Tattered Journal
        title = { "16:2029920167:695050730", "บันทึกขาดรุ่งริ่ง" },
        objective = { "77:1651770375:384794949", "ข้อความในบันทึกบ่งชี้ว่าผู้เขียนอาจอยู่ที่ไหนสักแห่งใน Shen'dralas" },
        description = { "308:2059319285:1775796487", "<หนังสือเก่าเปื้อนฝุ่นที่พบใกล้ Shen'dralas เล่มนี้สูญเสียเนื้อหาส่วนใหญ่ไปแล้ว\n\nข้อความที่เหลือเลือนรางจนแยกแทบไม่ออกว่าตรงไหนเป็นตัวอักษรเดี่ยว ตรงไหนเป็นคำ ตอนแรกอาจอ่านยาก แต่มีคำหนึ่งที่ดูเหมือนนามสกุล\n\nบางทีผู้เขียนชื่อ ‘Evenshade’ อาจอยู่แถวนี้>" },
        completion = { "431:1619629773:1714203504", "บันทึกของข้าหรือ? เป็นไปไม่ได้ มันหายไปหลายศตวรรษแล้ว\n<Mordent รับหนังสือเปรอะเปื้อนคืนมาตรวจดูปก เขาเลิกคิ้วด้วยความประหลาดใจ แต่พอเปิดปกออกสีหน้าก็สลดลง>\nเจ้าพบบันทึกของข้าจริง ๆ แต่เสียดายที่สิ่งที่ข้าเขียนไว้หายไปหมด ข้ายังจำเรื่องในนั้นได้ เพียงแต่ไม่อยากเอ่ยถึงมัน\nถ้าหน้าบันทึกยังรอดมาได้ด้วยเหตุใดก็ตาม ข้าอนุญาตให้เจ้าลองกู้มันคืนมา" },
        progress = { "28:717264101:743564957", "เจ้าต้องการอะไรหรือ?" },
        required = { [260347] = { "16:2029920167:695050730", "บันทึกขาดรุ่งริ่ง" } },
        steps = { { "16:2029920167:695050730", "บันทึกขาดรุ่งริ่ง" } },
    },
    [96010] = { -- Fragments of the Pylons
        title = { "23:408798497:1692406839", "เศษผลึกจากเสาพลัง" },
        objective = { "126:1266478623:880334526", "นำเศษเสาพลังที่มีคนเฝ้าอยู่ในหมู่บ้าน Magram และ Gelkis กลับไปให้ Mordent Evenshade" },
        description = { "502:1066102660:1541855221", "ข้ามั่นใจว่าความเสียหายของเสาพลังทั้งสองมาจากเซนทอร์ที่อาละวาดไปทั่ว แต่ข้าสงสัยว่าเศษผลึกกระจัดกระจายกันเพราะพวกมันอาละวาดคนละจังหวะ ข้าไม่ค่อยรู้เรื่องความขัดแย้งของพวกมัน รู้เพียงว่ามีอย่างน้อยสองกลุ่มใหญ่ที่บุกรุก Shen'dralas คือ Magram ที่ดุร้าย กับ Gelkis ที่เจ้าเล่ห์\n\nไม่มีใครเก็บของล้ำค่าไว้กลางสนามรบหรอก ป่านนี้พวกมันคงเอาของที่ชิงได้กลับไปเก็บที่หมู่บ้านของตัวเองแล้ว" },
        completion = { "142:913816537:1853516066 N 267:1267971713:2128433058", "ผลึกแตกเป็นชิ้นเล็กชิ้นน้อยกว่าที่ข้าคิด แต่ดูเหมือนจะอยู่ครบ ข้าจะเก็บไว้ก่อน ขอบใจ {name}\nขั้นต่อไป เจ้าต้องรวบรวมมานาที่ปรับรูปได้มากพอให้ใช้ประสานชิ้นส่วนที่แตก และเป็นตัวนำให้พลังจากเส้นพลังเวทไหลผ่านหลังจากนั้น\nเป็นกระบวนการที่น่าทึ่งทีเดียว แต่การรวบรวมมานาอาจยุ่งยากสักหน่อย" },
        progress = { "126:1303302827:1929752508", "ข้าไม่อยากให้พวกเซนทอร์หันมาสนใจข้าหรือพี่น้องผู้ล่วงลับของข้ามากกว่านี้ ไม่อย่างนั้นข้าคงไปหาผลึกเองแล้ว" },
        required = { [255656] = { "14:699278972:1281317561", "ชิ้นส่วนเสาพลัง" }, [255657] = { "11:1714571154:60281991", "เศษผลึกจากเสาพลัง" } },
        steps = { { "14:699278972:1281317561", "ชิ้นส่วนเสาพลัง" }, { "11:1714571154:60281991", "เศษผลึกจากเสาพลัง" } },
    },
    [96018] = { -- Powering the Pylons
        title = { "19:1944885983:492438865", "เติมพลังให้เสาผลึก" },
        objective = { "193:611073407:984711790", "หา Mana Sieve ในวิหาร Shen'dralas แล้วใช้เก็บ Ancient Mana Crystal เมื่อมีมานาพอให้เติมพลังเสาผลึก แล้วกลับไปหา Mordent Evenshade" },
        description = { "485:589836374:1780650087", "เจ้าอาจเห็นประกายมานาลอยอยู่ทั่ว Shen'dralas นี่เป็นปรากฏการณ์ที่เพิ่งเกิดขึ้น น่าจะเป็นผลจากความเสียหายของเสาพลัง\n\nเราต้องเก็บมานานี้กลับมาในรูปกึ่งผลึก ใช้ Mana Sieve ที่อยู่ในวิหารทำได้ ยืมตะแกรงนั่นมา แล้วเก็บลูกมานาลอยที่เจอ\n\nคนในวิหารคงไม่พอใจที่ของล้ำค่าถูกยืมไปโดยไม่ได้ขอ แต่พอถึงเวลาพวกเขาจะเข้าใจเอง" },
        completion = { "284:1862568777:1013295868", "เห็นแล้วว่าเจ้าซ่อมเสาเสร็จ จะให้ข้าไม่สังเกตได้อย่างไรล่ะ?\n<Mordent ชี้ขึ้นไปบนฟ้า พลางเงยหน้ามองไปทางนั้นชั่วครู่ พอหันกลับมาหาเจ้า เขาก็เลิกคิ้วเมื่อเห็นว่าเจ้าดูตื่นเต้นน้อยกว่าเขา>" },
        progress = { "29:1413554121:942060837 N 1:46:46", "ดีใจที่ได้พบเจ้าอีก {name}" },
        required = { [255662] = { "10:454783211:1399806006", "ตะแกรงกรองมานา" }, [271882] = { "19:1767125938:252557382", "กองชิ้นส่วนเสาพลัง" } },
        steps = { { "22:1166812859:1958456058", "ซ่อมเสาพลังทางตะวันออก" }, { "22:1138207226:313168960", "ซ่อมเสาพลังทางตะวันตก" } },
        objectiveLabels = {
            item = { ["Mana Sieve"] = "ตะแกรงกรองมานา", ["Pile of Pylon Parts"] = "กองชิ้นส่วนเสาพลัง" },
        },
    },
    [96060] = { -- Tempered Expectations
        title = { "21:504996877:728861728", "คมดาบกับความคาดหวัง" },
        objective = { "36:573842520:759311055 W1 63:319425375:2129138728", "ใช้ Phantasmal Blade สังหารสัตว์ป่า {world1} ตัวใน Shen'dralas แล้วกลับไปหา Vindael ที่วิหาร" },
        description = { "497:2140828130:1214591993", "ขอเล่าเองเลยว่า ตอนยังมีชีวิตข้าเป็นยอดนักดาบ กลางวันตีอาวุธ กลางคืนก็เอาอาวุธที่ตีไปใช้\n\nอย่างที่เจ้ารู้ดี ตอนนี้เรื่องระหว่างข้ากับดาบเล่มนี้ซับซ้อนเอามาก ๆ ข้าคงพอแกว่งมันได้ แต่ไม่แน่ใจว่าจะมีประโยชน์เว้นแต่ใช้สู้กับวิญญาณตนอื่น แล้วแบบนั้นจะช่วยอะไรข้าใน Shen'dralas ได้จริงหรือ?\n\nถึงอย่างนั้นข้าก็อยากทดสอบว่ามันทำอะไรได้บ้าง และคิดว่าน่าจะลดจำนวนสัตว์ในป่าลงสักหน่อย" },
        completion = { "498:578036984:1411309231", "ยอดเยี่ยม! ถึงขั้นน่าตื่นตาเลยทีเดียว! ผ่านมาหลายปี ในที่สุดก็ได้ยินว่าดาบเล่มนี้ได้ลิ้มเลือดสักครั้งนับแต่ตีมันขึ้นมา\nส่วนวิญญาณที่เจ้าเห็นนั่นก็แปลกและเหนือความคาดหมาย ข้าไม่ตื่นเต้นกับเรื่องนั้นเท่าไร ถ้าพวกมันเข้าไปพัวพันกับแดนวิญญาณของเราได้จริง เราอาจต้องกำจัดเจ้าพวกเดิมอีกเป็นครั้งที่สอง\nข้าไม่คิดจะรบกวนให้เจ้ารับงานนั้น อย่างน้อยก็ยังไม่ใช่วันนี้ ทำเรื่องที่เจ้ามาทำที่นี่ต่อเถอะ" },
        steps = { { "41:996011955:646705502", "ใช้ดาบสังหารสัตว์ป่าใน Shen'dralas" } },
    },
    [99257] = { -- A Heart of Crystal
        title = { "18:269527973:485734103", "หัวใจผลึก" },
        objective = { "132:1351909891:1042838018", "กำจัด Decrepit Pylon Protector เพื่อเอา Depleted Crystal Heart ไปให้ Historian Biraxas ในวิหาร Shen'dralas" },
        description = { "502:906070659:1564637916", "ข้าตกใจแทบแย่ที่เห็นเจ้าเที่ยวเล่นในป่าผีสิงพร้อมของล้ำค่าของข้า แต่การเข้าไปยุ่งของเจ้าก็ทำให้ข้าคิดอะไรออก\n\nรอยแยกไม่เสถียรที่เจ้าเจอเป็นต้นกำเนิดของผู้พิทักษ์เสาพลัง เราอัญเชิญเพิ่มไม่ได้มาหลายศตวรรษแล้ว ข้ากังวลว่าจะเกิดอะไรขึ้นเมื่อผู้พิทักษ์ที่เหลือดับสูญไปในที่สุด\n\nข้ารู้ว่าฟังดูย้อนแย้ง แต่ลองหาผู้พิทักษ์เสาพลังอีกตนที่จวนจะดับ แล้วเอาหัวใจผลึกของมันมา เดี๋ยวข้าจะอธิบายเพิ่ม" },
        progress = { "259:924607410:244818843", "ข้ารับรองว่าไม่ได้คิดจะทำลายหนึ่งในเครื่องป้องกันไม่กี่อย่างที่เรามี ถ้าผู้พิทักษ์ตัวไหนดูไม่กระฉับกระเฉงและไม่สมบูรณ์อย่างตัวที่อยู่ในวิหาร ก็แปลว่ามันเข้าสู่ราวร้อยปีสุดท้ายของวงจรชีวิตแล้ว จะว่าไป การปลิดชีพมันก็เป็นการช่วยให้พ้นทุกข์" },
        completion = { "331:79244114:1330060144", "เจ้าทำสำเร็จแล้วสินะ! ได้หัวใจชิ้นงามมาด้วย ข้าดีใจที่เวลาหลายศตวรรษแทบไม่ทำให้ความประณีตของอัญมณีชิ้นนี้เสื่อมลงเลย\n\nที่สำคัญ นี่เป็นการค้นพบที่มีแวว ดูเหมือนว่ามานาจะอยู่ได้เพียงชั่วคราว แต่อัญมณีคงอยู่ตลอดไปจริง ๆ\n\nอยากรู้แล้วใช่ไหมว่าต่อไปจะเป็นอะไร?" },
        required = { [286647] = { "22:902954389:1883016721", "หัวใจผลึกที่พลังหมดแล้ว" } },
        steps = { { "22:902954389:1883016721", "หัวใจผลึกที่พลังหมดแล้ว" } },
    },
    [99258] = { -- Mana Mania
        title = { "10:2062042568:1762458123", "มานาอลหม่าน" },
        objective = { "155:714463832:1224138441", "โยน Depleted Crystal Heart เข้าไปใน Unstable Mana Rift แล้วกลับไปหา Historian Biraxas ในวิหาร Shen'dralas พร้อมหลักฐานว่าสำเร็จหรือไม่" },
        description = { "494:1886087557:467300883", "หาอัญมณีมาอัญเชิญธาตุก็ยากอยู่แล้ว แต่ที่น่าห่วงกว่าคือ Shen'dralas ยังมีมานาอิสระพอสร้างพวกมันไหม หัวใจดวงนี้จะช่วยยืนยันเสียทีว่าเราต้องเริ่มค้นคว้าวิธีป้องกันแบบอื่นหรือเปล่า\n\nงานของเจ้าง่ายมาก แค่โยนอัญมณีนี้เข้ารอยแยกไม่เสถียรสักแห่ง ถ้าโชคดีเจ้าจะต้องสู้ ไม่ต้องออมมือ ถ้าทำสำเร็จครั้งหนึ่ง ก็ทำซ้ำได้" },
        completion = { "49:449210141:2038569177 N 369:1005924731:54918922", "สำเร็จแล้ว! สำเร็จจริง ๆ!!\nข้าแทบพูดไม่ออก {name}! ข้าไม่คิดว่ามันจะได้ผล ทุกสิบปีที่ผ่านไป ข้ายิ่งกังวลว่าโอกาสที่เราอาจเคยมีก็เลยผ่านไปแล้ว\nสำหรับเจ้าเรื่องนี้อาจดูไม่สำคัญหรือธรรมดามาก แต่ขอให้รู้ไว้เถอะว่าสิ่งนี้จะเปลี่ยนชีวิตหลังความตายของพวกเราไปเลย\nข้าจะเริ่มวางแผนขั้นต่อไป ข้าไม่มีงานให้เจ้าทำอีกแล้ว แต่คนอื่นอาจยังต้องการความช่วยเหลือจากเจ้า\nขอบใจนะ จากใจจริง" },
        objectiveLabels = {
            monster = { ["Nascent Pylon Protector slain"] = "ปราบ ผู้พิทักษ์เสาพลังที่เพิ่งถือกำเนิด" },
        },
    },
    [96772] = { -- The Dragon's Journal
        title = { "20:1758059153:1128589854", "บันทึกของมังกร" },
        objective = { "56:922812792:1471074415", "นำ Zarla's Journal กลับมาจากส่วนลึกของ Alcaz Prison" },
        description = { "490:1186109186:1936677118", "Timear กับข้าใช้เวทส่องดูบริเวณที่เรียกว่า Alcaz Island ใน Kalimdor เราแทบจะแน่ใจแล้วว่ามีผู้ใช้เวททรงพลังอยู่ที่นั่น จอมเวทคนนั้นสลายเวทสอดแนมของเราได้ แต่ก่อนหน้านั้นข้าเห็นภาพหนังสือเล่มหนึ่งแวบ ๆ ข้าคิดว่าเป็นบันทึกที่เขียนด้วยอักษรมังกรโบราณ\n\nข้าไม่รู้ว่าข้างในมีอะไร แต่อยากเอามาศึกษา เราอยากให้เจ้าไปยังคุกที่ซ่อนอยู่ใต้ Alcaz Island แล้วนำหนังสือกลับมาให้เรา" },
        steps = { { "19:1538704420:70759422", "นำสมุดบันทึกกลับมา" } },
    },
    [96776] = { -- An'she's Radiance
        title = { "17:53009747:2047584499", "รัศมีแห่งอันเช" },
        objective = { "61:883713453:600774750", "นำผลึก An'she's Radiance กลับมาจาก Maraudon" },
        description = { "378:1866990260:1069525705 C 111:1347714187:985024138", "ข้าเห็นนิมิต\n\nลึกเข้าไปใน Maraudon เลยน้ำตก Earth Song ไป มีห้องที่เต็มไปด้วยผลึกสีขาวสุกสว่างและมียักษ์ทรงพลังเฝ้าอยู่ ตรงจุดสูงสุดของห้องมีผลึกที่เจิดจ้าเป็นพิเศษ มันคือภาคหนึ่งของ An'she เทพแห่งดวงอาทิตย์ ผู้เป็นดวงตาขวาของพระแม่ธรณี\n\nข้าฝันเห็นรัศมีของมัน มันกำลังเรียกหาข้า {class} จงนำ An'she's Radiance ออกมาจากที่นั่นและพากลับมาที่ที่มันควรอยู่ ใต้ฟ้ากว้างแห่ง Mulgore" },
        required = { [277140] = { "17:53009747:2047584499", "รัศมีแห่ง An'she" } },
        steps = { { "17:53009747:2047584499", "รัศมีแห่ง An'she" } },
    },
    [96797] = { -- The Orphan
        title = { "10:1411218383:445402280", "เด็กกำพร้า" },
        objective = { "76:500155798:2038470764", "เดินทางไป Nethergarde Keep ใน Blasted Lands แล้วตามหา Sergeant Danneth" },
        description = { "469:998676092:1471506824", "เราพยายามตามหาญาติที่ยังมีชีวิตอยู่ให้เด็ก ๆ ที่เราดูแลเสมอ บางครั้งก็ได้ข่าวที่พอมีหวัง ข้าได้รับข่าวว่า Randal อาจยังมีญาติอยู่คนหนึ่ง ชายคนนั้นชื่อ Danneth เป็นทหารประจำ Nethergarde Keep ข้าต้องการคนไปตามหาเขา\n\nถ้าทำได้ ช่วยเกลี้ยกล่อมให้ Danneth มารับหลานชายด้วย ข้าไม่คิดว่าสองคนนี้เคยเจอกัน แต่ถึงอย่างไรก็เป็นครอบครัวเดียวกัน และ Randal ควรได้อยู่กับเขา" },
        completion = { "198:1505153392:273447895", "Danneth หรือ? ข้าเสียใจที่ต้องบอกว่าเขาหายตัวไปหลายวันแล้ว\n\nหน่วยของเขาถูกซุ่มโจมตีใกล้ Serpent's Spine เราหาศพไม่พบ แต่ข้าเกรงว่าโอกาสที่เขาจะยังมีชีวิตอยู่คงน้อยมาก" },
    },
    [97173] = { -- Blackmaw Magic
        title = { "14:1114340910:454459928", "มนตร์ดำของแบล็กมอว์" },
        objective = { "51:245136373:969265424", "นำ Blackmaw Ritual Totem กลับมาจาก Blackmaw Hold" },
        description = { "446:160153161:2004498445", "พวกเฟอร์โบลก Blackmaw บนภูเขาที่มองลงมาเห็น Azshara กำลังหันไปใช้มนตร์ดำ เรื่องที่ชนเผ่าดั้งเดิมถูกเวทปีศาจชักนำไม่ใช่เรื่องใหม่ใน Azeroth แต่ Lan'dalock กับข้าอยากศึกษาเครื่องรวมพลังเวทของพวกมัน\n\nเดินทางไปยังป้อม Blackmaw Hold แล้วนำ Blackmaw Ritual Totem กลับมาให้เราสักชิ้น มีเพียงชาแมนที่ทรงพลังที่สุดของ Blackmaw ที่จะพกของชิ้นนี้ พาสหายไปด้วยและระวังตัวให้ดี" },
        required = { [276893] = { "21:396060987:469829698", "โทเทมพิธีกรรมของ Blackmaw" } },
        steps = { { "21:396060987:469829698", "โทเทมพิธีกรรมของ Blackmaw" } },
    },
    [96438] = { -- Battle at the Mannoroc Coven
        title = { "28:1504185449:231783230", "ศึกที่แหล่งชุมนุมมานโนร็อก" },
        objective = { "57:317107697:695699314", "สืบเรื่องการสู้รบที่ Mannoroc Coven ใน Desolace" },
        description = { "N 442:928338592:1703756769", "{name} ข้าต้องการความช่วยเหลือ พี่น้องของเราคนหนึ่งเดินทางผ่าน Nigel's Point ใน Desolace และได้ยินเรื่องการสู้รบที่ Mannoroc Coven มีรายงานว่าฝ่ายหนึ่งใช้เวทศักดิ์สิทธิ์อันทรงพลังต่อสู้กับวอร์ล็อกที่นั่น ผู้ใช้พลังแห่งแสงต้องเกี่ยวข้องแน่\n\nข้าอยากรู้ว่าใครเข้าร่วมการปะทะครั้งนี้ ถ้ามีคนของเราไปรบ หรือล้มตายอยู่ที่นั่น... ข้าอยากรู้ให้ได้" },
    },
    [97022] = { -- Report to Danitha
        title = { "17:926859089:959332541", "ไปรายงานตัวกับดานิธา" },
        objective = { "42:2084813775:208360848", "คุยกับ Danitha Morr ที่ Bandarion Keep" },
        description = { "159:878637387:1777584609", "Danitha Morr สั่งให้เจ้ากลับไปรายงานตัวที่ Bandarion Keep เพื่อรับการฝึกเพิ่มเติม โปรดเดินทางกลับป้อมให้เร็วที่สุดเท่าที่จะทำได้" },
        completion = { "18:172576187:1665398560 N 98:927465524:77322714 C 1:46:46", "ดีใจที่เจ้ามาถึง {name} เจ้าเห็นอะไรมามากและเดินทางมาไกล ตอนนี้เจ้าพร้อมก้าวไปอีกขั้นบนเส้นทางของ{class}แล้ว" },
    },
    [97196] = { -- The Coldbringer's Eye
        title = { "21:1731848506:170715537", "ดวงตาแห่งโคลด์บริงเกอร์" },
        objective = { "50:629156591:276639930", "นำ The Coldbringer's Eye กลับมาจาก Razorfen Downs" },
        description = { "505:1024006514:1448460728", "บริวารของ Lich King ตนหนึ่งอาศัยอยู่ลึกในรังของควิลบอร์ Death's Head ที่เรียกว่า Razorfen Downs เรารู้ว่ามันใช้ลูกแก้วส่องดูและสั่งการสมุนในที่อื่น\n\nถ้าได้ของวิเศษชิ้นนี้มา เราจะตามล่าสายลับของ Scourge และกำจัดทั้งพวกมันกับภัยที่คุกคาม Kalimdor ให้สิ้นซาก\n\nเข้าไปใน Razorfen Downs ไปถึงรังของ Amnennar the Coldbringer แล้วนำลูกแก้วที่เรียกว่า Coldbringer's Eye มาให้ข้า" },
        completion = { "143:920634684:540618630", "สิ่งนี้ใช้ได้ดีทีเดียว เราชิงเครื่องมือสำคัญมาจากศัตรู และได้อาวุธทรงพลังไว้ใช้ต่อกรกับ Scourge" },
        progress = { "135:1135709331:1740582537", "พวกควิลโบร์ Death's Head เป็นเสี้ยนหนามของเรามาหลายปีแล้ว ส่วนหนึ่งก็เพราะแผนชั่วของลิชต้องสาปนั่น" },
        required = { [276916] = { "21:1731848506:170715537", "ดวงตาของ Coldbringer" } },
        steps = { { "21:1731848506:170715537", "ดวงตาของ Coldbringer" } },
    },
    [97332] = { -- Twice Misplaced Trust
        title = { "21:85574287:334870085", "ไว้ใจผิดคนถึงสองครั้ง" },
        objective = { "99:749926953:1202336547", "นำ Twice Reordered Package ไปให้ Wharfmaster Whizzbuzz ที่ Powderfuse Port ใน Riverglades" },
        description = { "490:883431168:144175869", "ถึงข้าจะไม่ชอบหมอนั่น แต่ก็เคยได้ยินว่าชนเผ่า Bloodscalp ทำอะไรกับเชลย ฟังแล้วไม่น่าดูเลย ดีใจที่ Zimmix รอดออกมาได้\n\nแต่ข้ามีของด่วนต้องส่งอีกชิ้น และข้าไม่ไว้ใจให้เขารับงานนี้เลย ปัญหาคือก่อนเขาจะมารับงาน ไม่มีใครว่างไปส่ง เจ้าเองทั้งกู้ของที่หายและช่วยก็อบลินที่ถูกจับมาแล้ว จากตรงนี้เจ้าดูน่าไว้ใจทีเดียว\n\nข้าพอจะขอให้เจ้าเอาของนี่ไปให้ Whizzbuzz ที่ Powderfuse Port ได้ไหม?" },
        completion = { "487:1892078156:1397352290", "หือ? มีอะไรมาให้ข้าล่ะ?\n<Whizzbuzz ชะโงกมองในลัง สีหน้าสว่างขึ้นด้วยความประหลาดใจทันที>\nดูนี่สิ! ในที่สุด Lozgil ก็ส่งของมาจนได้ ต้องทั้งส่งจดหมายด่ายับและจ่ายให้คนส่งของไปขู่ถึงจะเข้าใจ อยากรู้ว่าจะอ้างอะไร กัปตันเรือโดนจับรึ? เรือเหาะตกรึ?\nฮ่า ๆ นึกภาพออกไหม? แถวนี้ไม่มีหอเรือเหาะด้วยซ้ำ!\nดูท่าเจ้าจะลำบากไม่น้อยกว่าจะเอานี่มาส่ง เอารางวัลไปเถอะ" },
        progress = { "23:1704260772:762880180", "ไม่เห็นหรือว่าข้ากำลังยุ่ง?" },
        required = { [277974] = { "23:1737742137:1902741973", "พัสดุที่สั่งใหม่สองครั้ง" } },
        steps = { { "23:1737742137:1902741973", "พัสดุที่สั่งใหม่สองครั้ง" } },
    },
    [97405] = { -- Noise Complaints
        title = { "16:1661047918:2096855138", "ร้องเรียนเรื่องเสียงดัง" },
        objective = { "36:1221838145:2034168120 W1 25:109271512:80448655 W2 22:1896394976:275261308 W3 23:116228300:393954527 W4 44:1240999654:2061892704", "กำจัด Mosh'Ogg Spellcrafter {world1} ตัว, Mosh'Ogg Warmonger {world2} ตัว, Mosh'Ogg Mauler {world3} ตัว และ Mosh'Ogg Shaman {world4} ตัวที่ Mosh'Ogg Ogre Mount ให้ Knaz Blunderflame" },
        description = { "488:1768445395:586092507", "Gnaz ตรงโน้นกำลังสร้างไอ้เครื่องอันตรายนั่นเพื่อไปลงแข่งไกลถึง Kalimdor ข้าเตือนเขาแล้วว่าการง่วนกับเครื่องจนดึกทุกคืนเสียงดังมาก เมื่อคืนข้าเห็นโอเกอร์โผล่หัวอัปลักษณ์ออกมาจากหลังต้นไม้ด้วย!\n\nเขาหมกมุ่นกับฝันใหญ่โตว่าจะชนะ Mirage Raceway Championships ส่วนข้าคิดอย่างเดียวว่าจะทำยังไงไม่ให้โดนขย้ำตาย! ช่วยข้ามเนินทางเหนือไปจัดการให้พวกมันเลิกมาด้อม ๆ มอง ๆ แถวนี้ที" },
        objectiveLabels = {
            monster = { ["Mosh'Ogg Spellcrafter slain"] = "ปราบ ผู้รังสรรค์คาถา Mosh'Ogg", ["Mosh'Ogg Warmonger slain"] = "ปราบ นักกระหายสงคราม Mosh'Ogg", ["Mosh'Ogg Mauler slain"] = "ปราบ นักขย้ำ Mosh'Ogg", ["Mosh'Ogg Shaman slain"] = "ปราบ ชาแมน Mosh'Ogg" },
        },
    },
    [97534] = { -- Gritty Business
        title = { "15:978429383:1509257663", "กำไรกลางทะเลทราย" },
        objective = { "27:1302593963:2079011700 W1 56:1442358659:1073432904", "เก็บ Desert Debris {world1} ชิ้นแล้วกลับไปหา Quinn ที่ Gadgetzan" },
        description = { "500:1246467698:367520035", "ชู่ว์ อยากรู้อะไรไหม? ที่แบบนี้หากำไรง่ายกว่าที่คิด... ขอแค่รู้ว่าจะขายยังไง! ข้าเห็นมาแล้วว่าพวกบ้าเครื่องยนต์ทำอะไรกันเวลาได้ของที่คิดว่าจะเอาไปทำเซลล์เชื้อเพลิงได้\n\nถ้ามันยังเรืองแสงหรือพ่นไอเป็นพัก ๆ ยิ่งดี\n\nเรามาตกลงกันไหม? เอาชิ้นส่วนที่หลุดจากเครื่องของพวกนั้นในทะเลทรายกลับมา แล้วข้าจะแบ่งเงินที่ได้จากขายเศษชิ้นส่วนคืนให้พวกช่างเก็บของเก่า" },
        completion = { "151:981941253:2047965797", "ได้มาเยอะดีนี่ เจ้าตีนทราย ข้าจะเอาพวกนี้เข้าเครื่องบดกับเครื่องคัดให้รีบออกจากชั้นขายของเราไปเลย!\nเอ้านี่ เงินสักหน่อย เอาไปซื้ออะไรดื่มซะ" },
        progress = { "110:563337299:530365418", "อย่าไปกังวลกับป้ายที่เขียนว่าอันตรายหรือเป็นพิษ... ข้าจะฉีกทิ้งให้หมด พวกนั้นไม่มีทางรู้หรอก!" },
        required = { [278191] = { "13:1952818304:233408413", "เศษซากจากทะเลทราย" } },
        steps = { { "13:1952818304:233408413", "เศษซากจากทะเลทราย" } },
    },
    [97536] = { -- Gnomish Garbage
        title = { "15:1170340355:1766281835", "ขยะของพวกโนม" },
        objective = { "174:53357216:725925089", "นำ Crate of Radioactive Refuse ไปเททิ้งในทะเลทราย Tanaris ให้ห่างจาก Gadgetzan และกองขยะอื่นในระยะปลอดภัย แล้วกลับไปหา Jhordy Lapforge" },
        description = { "499:648558224:1598236009", "กว่าจะทำให้เครื่องส่งสสารทำงานได้ตามต้องการ เราต้องทดลองอยู่หลายครั้ง ใช้วัสดุสารพัดแบบ... ผลก็ออกมาต่างกันไป! ผลทดลองบางอย่างหายไปแล้ว ส่วนบางอย่างสะสมพลังจนเป็นอันตราย\n\nของที่เอาไปทดลองแผ่พลังงานออกมา ถ้าอยู่ใกล้นานเกินไปจะถูกลวก เหมือนมันเก็บพลังของแดดทะเลทรายไว้ทั้งปี\n\nเอา Crate of Radioactive Refuse นี่ไปเทลงบนทราย ให้ห่างจากเมืองและขยะกองอื่นพอที่จะปลอดภัย" },
        completion = { "153:1051246436:221643331 N 1:46:46", "มือเจ้าเป็นยังไงบ้าง? ยังรู้สึกที่นิ้วอยู่ไหม?\n\nข้าว่าไม่ต้องกังวลหรอก เดี๋ยวก็หาย ทีนี้เราสังเกตพวกมันได้จากระยะปลอดภัยแล้ว!\n\nขอบใจนะ {name}" },
        steps = { { "29:293945010:933909285", "ทิ้งของเสียจากการทดลอง" } },
    },
    [97617] = { -- Safety Checks
        title = { "13:1676992507:805280769", "ตรวจความปลอดภัย" },
        objective = { "8:1749550375:377180055 W1 153:1830433932:911288242", "นำ Unstudied Artifact {world1} ชิ้น, Explorers' League Mining Helmet และ Pristine Mattock ไปให้ Dorgaron ตรงพรมแดน Loch Modan กับ Badlands" },
        description = { "498:1842307877:1395315645", "สวัสดี เจ้าน่าจะเป็นคนชอบช่วยเหลือผู้อื่นนะ\n\nข้าชื่อ Dorgaron มาจาก Explorers' League เราขุดที่ Badlands กันไม่ค่อยราบรื่นนัก แต่ข้ามั่นใจว่าที่นั่นยังมีโบราณวัตถุให้ค้นหาและเก็บกลับมา!\n\nก่อนจะเกลี้ยกล่อมหัวหน้าให้ส่งคนงานอีกชุดมาที่นี่ได้ ข้าต้องพิสูจน์ว่าพื้นที่ขุดปลอดภัย และยังมีของเหลือให้ขุด\n\nถ้าเจ้าลงไปทางใต้ ช่วยเก็บโบราณวัตถุสภาพพอใช้มาสักสองสามชิ้น แล้วหาอุปกรณ์ที่ยังไม่พังติดมือกลับมาด้วย" },
        completion = { "412:1015667187:1098112028", "เยี่ยม! หลักฐานนี่มากพอจะชี้ให้เห็นว่าควรส่งคนกลับไป Badlands ข้ารู้ว่าทุกคนจับจ้องแต่ Uldaman แต่เราจะปล่อยให้เรื่องนั้นบังตาจนมองข้ามสิ่งที่รอให้ค้นพบอีกมากมายตามที่ราบไม่ได้\nเจ้าไล่คนหรือตัวอะไรก็ตามที่ยึดจุดพวกนั้นไปแล้วใช่ไหม? หวังว่าจะไล่แล้วนะ ไม่งั้นหัวหน้าด่าข้าหูชาแน่ที่โกหกว่าปลอดภัย..." },
        progress = { "5:1151914372:80614369", "ว่าไง?" },
        required = { [278402] = { "18:653688514:1625329261", "โบราณวัตถุที่ยังไม่ได้ศึกษา" }, [278403] = { "31:836371835:1733095292", "หมวกคนงานเหมืองของสมาคมนักสำรวจ" }, [278404] = { "16:513270028:1203697356", "จอบขุดสภาพสมบูรณ์" } },
        steps = { { "18:653688514:1625329261", "โบราณวัตถุที่ยังไม่ได้ศึกษา" }, { "31:836371835:1733095292", "หมวกคนงานเหมืองของสมาคมนักสำรวจ" }, { "16:513270028:1203697356", "จอบขุดสภาพสมบูรณ์" } },
    },
    [97821] = { -- Mirage Mirror
        title = { "13:910383534:649393339", "กระจกภาพลวง" },
        objective = { "72:1964391062:302672054", "ตามหาคนใน Badlands ที่อาจสนใจของที่ค้นพบ" },
        description = { "343:2067773179:1982005471", "<เมื่อธาตุตนนั้นตาย วัตถุโบราณชิ้นหนึ่งร่วงออกจากแกนกลางและส่องแสงระยิบบนทราย\n\nเมื่อเจ้าเอียงมันในมือ ภาพสะท้อนของบริเวณรอบตัวกลบตัววัตถุจนมองไม่เห็น พอเจอรอยร้าวที่ทำให้ภาพสะท้อนบิดเบี้ยว เจ้าจึงมองเห็นมันชัดอีกครั้ง\n\nบางทีอาจมีคนสนใจของที่เจ้าพบนี้>" },
        completion = { "485:2024238766:1744590184", "<ทอเรนสะดุ้งเมื่อร่างวูบไหวของเจ้าปรากฏออกมาจากหลังวัตถุโบราณ>\nของที่เจ้าพบแปลกจริง ๆ! ไปเจอแถว Badlands มาหรือ? ต้องใช่แน่ ข้านึกไม่ออกว่าจะมีที่ไหนอีกที่ลงมนตร์ให้วัตถุซ่อนตัวคนกลางที่รกร้างโล่ง ๆ แบบนี้ได้\nข้าอยากลองศึกษาดูเอง แต่ข้าบาดเจ็บเกินกว่าจะจับของเปราะบางขนาดนี้ พกมันไปผจญภัยด้วย แล้ววันหลังแวะกลับมาเล่าให้ฟังนะ!" },
        progress = { "19:114128627:1825235477", "หือ? อะไรน่ะ?" },
        required = { [278744] = { "13:910383534:649393339", "กระจกภาพลวงตา" } },
        steps = { { "13:910383534:649393339", "กระจกภาพลวงตา" } },
    },
    [98192] = { -- Skin Careful, Skin Sharp
        title = { "24:1370976742:2047777268", "ถลกหนังให้ดี ระวังคมมีด" },
        objective = { "6:1273960851:929420321 W1 52:112458055:1076492040", "นำ Intact Raptor Hide {world1} ผืนไปให้ Krak ที่ Brackenwall Village" },
        description = { "304:484319508:2052189178", "เจ้าตัวเล็ก! มาช่วย Krak ทุบไอ้ตัวแดงชอบกัด เอาหนังเกล็ดมา!\n\nKrak ทุบตัวแดงชอบกัดเอาหนัง แต่มือ Krak ใหญ่เกินไป พอตัดหนังทีไร ขาดเป็นรูทุกที\n\nแต่เจ้าตัวเล็ก! ไปเอาหนังจากตัวแดงชอบกัดที่ Dragonmurk ทางใต้ พวกมันดุแล้วก็ไว เจ้าตัวเล็ก อาจโดนกินเอา" },
        completion = { "151:234834490:1274253457 R 54:1301232930:1931395264", "พวกนี้ดี! เจ้าได้หนังเกล็ดดี ๆ มา เราไม่หมดเร็ว ๆ นี้แน่\nคราวก่อนหมด หนังไม่พอคลุมโอกร์สักตัว พวกเราหลายตัวไม่มีอะไรคลุม\nเพื่อน{race}ไม่ชอบแบบนั้น พวกเขาบอกเอง บอกเยอะ บอกหลายที" },
        progress = { "50:1887530451:1504377717", "Krak ต้องการหนังจากพวกชอบกัดอีก ดีที่เจ้ามาช่วย" },
        required = { [279601] = { "18:1113538361:1873568719", "หนังแรปเตอร์สภาพสมบูรณ์" } },
        steps = { { "18:1113538361:1873568719", "หนังแรปเตอร์สภาพสมบูรณ์" } },
    },
    [98205] = { -- Whelps are the Worst!
        title = { "21:955060000:1819978203", "ลูกมังกรนี่แย่ที่สุด!" },
        objective = { "5:1000000866:1065647852 W1 24:1844922224:903313770 W2 16:1943613067:2120352377", "กำจัด Searing Hatchling {world1} ตัวและ Searing Whelp {world2} ตัว" },
        description = { "403:273608868:628908176", "ข้ากับ Gizzix หุ้นส่วนของข้ากำลังหาที่ตั้งด่าน และข้าได้กลิ่นโอกาสแล้ว!\n\nหรืออาจเป็นแค่กลิ่นแก๊สจากบึงก็ได้ ยังไงก็เถอะ ข้าอยากให้ช่วยหน่อย\n\nมังกรดำตัวเล็กที่บินแถวนี้ไม่ค่อย ‘เป็นมิตร’ เท่าไร พวกมันถึงกับพ่นไฟลวกคุณ Melly ผู้น่าสงสาร!\n\nฟังนะ ข้ามีเงินให้ดีทีเดียวถ้าเจ้ายอมกำจัดลูกมังกรตัวร้ายพวกนี้สักหน่อย\n\nว่าไง เอาด้วยไหม?" },
        completion = { "287:847188645:1197571096", "เยี่ยมไปเลย! ดีใจที่เห็นเจ้ากลับมาครบสามสิบสอง แถมแทบไม่โดนลวกด้วย!\n\nรู้ไหม เจ้าเป็นคู่ค้าที่พึ่งพาได้จริง ๆ มีไม่กี่คนหรอกที่จะกระโจนเข้าไปช่วยคนอื่นโดยไม่ขอค่าจ้างล่วงหน้า\n\nเลือกของดี ๆ จากลังสักใบไปได้เลย ถือเป็นค่าตอบแทนที่เจ้าลงแรง" },
        objectiveLabels = {
            monster = { ["Searing Hatchling slain"] = "ปราบ ลูกมังกรเพลิงแรกฟัก", ["Searing Whelp slain"] = "ปราบ ลูกมังกรเพลิง" },
        },
    },
    [98215] = { -- Dragon Scales, Post Burnt Tails
        title = { "31:2138481070:2089639757", "หาเกล็ดมังกรหลังโดนไฟลวก" },
        objective = { "6:1273960851:929420321 W1 45:987792456:546074607", "นำ Shed Dark Dragonscale {world1} ชิ้นไปให้ Drazzit Dripvalve" },
        description = { "500:166903458:1504516359", "หลังฝ่าดงลูกมังกรอารมณ์ร้ายมาได้ ข้าว่าถึงเวลาแก้ปัญหาเล็ก ๆ ที่เกิดซ้ำไม่รู้จบแล้ว\n\nปัญหาที่ว่าคือพวกเราติดไฟง่าย\n\nข้าเฝ้าดูมังกรพวกนี้มาพักหนึ่ง ดูเหมือนพวกมันไม่เป็นอะไรเมื่อโดนไฟของตัวเอง อย่างน้อยเกล็ดมันก็ทนได้\n\nถ้ายอมทำงานเพิ่มสักหน่อย ข้ายินดีจ่ายค่าเกล็ดที่พวกมันทิ้งไว้และเจ้าเก็บได้ ถ้าโชคดี เราคงได้พอทำเครื่องป้องกันตัวให้พวกเรา อ้อ แล้วก็ให้ Melly ด้วยแน่นอน" },
        completion = { "204:201849323:1763919041", "โอ้โห! เจ้าเอามาได้มากกว่าที่ข้าคิดไว้เยอะเลย\nตกลงเจ้าเก็บจากพื้น หรือชกมังกรจนเกล็ดหลุดออกมา?\nไม่ว่าจะอย่างไร ข้าจะใช้ทุกชิ้นให้คุ้ม!\nเอ้านี่ เงินของเจ้าตามสัญญา" },
        progress = { "120:556765610:844915508", "เจอเกล็ดบ้างไหม? ยิ่งได้มาเร็ว ข้าก็อาจรู้สึกปลอดภัยขึ้นเร็วเท่านั้น เอ่อ ถ้าทฤษฎีนี้ใช้ได้จริงน่ะนะ" },
        required = { [279934] = { "21:230347023:1650486894", "เกล็ดมังกรสีคล้ำที่หลุดลอก" } },
        steps = { { "21:230347023:1650486894", "เกล็ดมังกรสีคล้ำที่หลุดลอก" } },
    },
    [98231] = { -- Active Ingredient
        title = { "17:299483079:301700522", "ตัวยาสำคัญ" },
        objective = { "6:1273960851:929420321 W1 32:1127638820:1600436666", "นำ Wyrmtail {world1} ต้นไปให้ Gizzix Grimegurgle" },
        description = { "480:943087026:784151367", "คุณ Melly ถูกลูกมังกรพ่นไฟใส่จนเจ็บหนัก ข้าว่ามันทำให้นางกลัว ข้ากล่อมให้นางขยับไปไหนไม่ได้เลย!\n\nฟังนะ ข้าคิดอะไรออกแล้ว\n\nข้าเคยซื้อยาน้ำมันงูมาขวดหนึ่ง แน่นอนว่ามันใช้ไม่ได้อย่างที่คนขายอ้าง แต่ดันรักษาแผลบาดของข้าได้ ได้ยินว่าตัวยาอย่างหนึ่งคือสมุนไพรชื่อ Wyrmtail ที่ขึ้นอยู่แถวนี้\n\nถ้าข้าเดาถูก มันอาจช่วยรักษาแผลไฟลวกของคุณ Melly ได้ ลองไปหาแล้วเอากลับมาให้ที อะไรที่พอลองได้ก็ต้องลอง!" },
        progress = { "235:670118850:1699614650", "ข้ายังไม่อยากเชื่อเลยว่าโดนพ่อค้าหน้าโง่นั่นหลอก!\nข้าจะไปรู้ได้ยังไงว่าเอาหางเวิร์ม โคลเวอร์สีทอง กับตีนกระต่ายยัดลงในน้ำยา แล้วแกว่งเหนือเกือกม้า จะไม่ได้น้ำยาเสริมโชค?\nฟังดูก็เข้าท่าดีนี่!" },
        completion = { "438:40263004:1078390268", "เฮ้ เจอแล้วนี่!\n\nโห ข้าได้กลิ่น Wyrmtail มาถึงตรงนี้เลย! กลิ่นสมุนไพรแรงจริง ๆ แต่ก็สดชื่นดีนะ คล้ายมินต์น่ะ รู้ไหม?\n\nบางทีอาจได้ผลก็ได้!\n\nเดี๋ยวข้าจะลองทาที่หางของคุณ Melly แค่จุดเล็ก ๆ ดู อย่างน้อยหวังว่ามันจะบรรเทาแผลไฟลวกได้บ้าง\n\nถ้าโชคดี มันอาจช่วยให้นางใจเย็นลงจนยอมขยับอีกครั้ง เราจะได้เริ่มสร้างด่านหน้าเสียที" },
        required = { [280092] = { "8:1070444760:613953686", "สมุนไพร Wyrmtail" } },
        steps = { { "8:1070444760:613953686", "สมุนไพร Wyrmtail" } },
    },
    [98233] = { -- Sword in the Slime
        title = { "18:520716185:1917688539", "ดาบในตัวสไลม์" },
        objective = { "63:899019516:1701990003", "เอา Jameson's Training Sword คืนมาแล้วนำไปให้ Guard Jameson" },
        description = { "495:1667906076:2133154588", "ไม่กี่คืนก่อน ข้าไปดื่มกับเพื่อน ๆ ที่โรงเหล้า พวกนั้นท้าให้ข้าไปสู้กับเจ้าตัวเมือกน่าขยะแขยงตามลำพัง\n\nเห็นข้าไม่มีดาบแบบนี้ เจ้าคงเดาได้ว่าเป็นยังไง\n\nพอเข้าไปฟัน ดาบข้าก็ติดคา เรื่องเลยไม่เป็นไปตามแผน\n\nข้าต้องเอาดาบคืนก่อนจ่าจะรู้ว่าข้าทำหาย มันน่าจะติดอยู่ในตัวเมือกสักตัวทางตะวันตก ข้ามอ่าวไป\n\nขอร้องล่ะ ถ้าจะไปทางนั้น ช่วยมองหาดาบให้ทีได้ไหม?" },
        progress = { "383:1595709975:1039645440", "ให้ตายสิ! ไม่น่าให้พวกเพื่อนยุเลย พวกนั้นบอกว่าข้าสู้กับไอ้ตัวเมือกน่าชังพวกนั้นคนเดียวไม่ได้ แน่ละ ในสภาพที่ข้า...\n<Jameson กระแอม>\n... ไม่เมาเลยสักนิด ข้าก็เลยคิดว่าจะพิสูจน์ให้พวกนั้นเห็นว่าคิดผิด\nเห็นชัดว่ามันไม่เป็นอย่างที่ข้าคิด ทีนี้คงจำได้เสียทีว่าอย่าดื่มแล้วไปหาเรื่องสู้ในคืนเดียวกัน" },
        completion = { "207:33421924:717012838 N 86:1623076779:1532974682", "ขอแสงสว่างช่วยด้วย เหม็นอะไรขนาดนี้! ข้าไม่รู้เลยว่าจะขจัดกลิ่นเน่านี้ออกจากดาบได้ยังไง\n\nเยี่ยมเลย ทีนี้เมือกเปื้อนตัวข้าไปหมดแล้วด้วย\n\nยังไงก็ขอบใจที่เอาดาบมาคืน {name} สักวันข้าจะตอบแทนเจ้าให้ได้\n\nขอเป็นตอนที่ตัวข้ากลิ่นดีกว่าตอนนี้แล้วกัน" },
        required = { [280203] = { "24:1342140120:353073992", "ดาบฝึกของ Jameson" } },
        steps = { { "24:1342140120:353073992", "ดาบฝึกของ Jameson" } },
    },
    [93443] = { -- Lost Shipping Crate
        title = { "19:1978489717:978668435", "ลังสินค้าที่หายไป" },
        objective = { "91:1820117850:836666892", "นำ Lost Shipping Crate ไปให้ Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades" },
        description = { "494:1869572930:1223022649", "<ด้านข้างลังมีป้ายเขียนด้วยมือ ทางขวาเป็นแผนที่ มีวงกลมสีแดงขนาดใหญ่ตรงชายฝั่งตะวันออกเฉียงใต้ อยู่เหนือวิหารที่วาดไว้แบบลวก ๆ โดยมีน้ำและสัตว์มีปีกอะไรสักอย่างล้อมอยู่ ส่วนทางซ้ายเขียนข้อความตัวโตมาก>\n\nทรัพย์สินของ FRIZ FRAZZLESPARK\n\nPOWDERFUSE PORT\n\nคำเตือน ห้ามแกะ ห้ามเปิดโดยไม่มีผู้ควบคุม\n\n<ด้านล่างของป้ายมีข้อความเขียนเพิ่ม>\n\nหากพบลังนี้ กรุณาส่งคืน Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades", variants = { { "494:1014799557:1447789506", "<ด้านข้างลังมีป้ายเขียนด้วยมือ ทางขวาเป็นแผนที่ มีวงกลมสีแดงขนาดใหญ่ตรงชายฝั่งตะวันออกเฉียงใต้ อยู่เหนือวิหารที่วาดไว้แบบลวก ๆ โดยมีน้ำและสัตว์มีปีกอะไรสักอย่างล้อมอยู่ ส่วนทางซ้ายเขียนข้อความตัวโตมาก>\n\nทรัพย์สินของ FRIZ FRAZZLESPARK\n\nPOWDERFUSE PORT\n\nคำเตือน ห้ามแกะ ห้ามเปิดโดยไม่มีผู้ควบคุม\n\n<ด้านล่างของป้ายมีข้อความเขียนเพิ่ม>\n\nหากพบลังนี้ กรุณาส่งคืน Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades" } } },
        completion = { "229:1100631496:2139433458", "เจ้าว่าไปเจอนี่ที่ไหนนะ? แปลกใจจริงที่เจ้ากลับมาได้ครบสามสิบสอง ขอบใจนะ เจ้าหนู\nนี่ ถ้าเจ้าชอบช่วยคนอื่น ข้าว่าคนแถวนี้อีกหลายคนมีงานให้ช่วย ลองอยู่แถวนี้อีกสักพักสิ" },
    },
    [93689] = { -- Friend of the Kirin Tor
        title = { "23:1776770402:15145086", "มิตรแห่งคิรินทอร์" },
        objective = { "52:901294394:1958399690", "คุยกับ Archmage Celindra ใน City of Dalaran" },
        description = { "243:1644021195:1480908000", "ข่าวดีจริง ๆ! เมื่อ Dalaran กลับมาสงบแล้ว ข้าก็ไม่เห็นเหตุผลที่คิรินทอร์จะไม่ต้อนรับเจ้าอย่างอบอุ่น\n\nรีบไปรายงานตัวต่อสภาเถอะ ข้ามั่นใจว่าพวกเขารอพบผู้กอบกู้เมืองอยู่" },
    },
    [94982] = { -- Eye of Mugg
        title = { "11:1411833122:1338288825", "ดวงตาของมักก์" },
        objective = { "97:1328114344:1223230069", "แทรกซึมเข้า Krol'dok Stronghold แล้วกลับไปหา Commander Brant พร้อมหลักฐานว่าผู้นำของพวกมันตายแล้ว" },
        description = { "482:2045586935:1738256961", "หน่วยสอดแนมรายงานว่ามีถ้ำเชื่อมถึงกันทางตะวันตกเฉียงเหนือตามแนวภูเขา ปากถ้ำถูกภูมิประเทศบังไว้ คนส่วนใหญ่ที่เข้าไปหาข่าวถึงข้างในยังไม่กลับมา ข้ากลัวว่าจะเสียพวกเขาไปแล้ว\n\nพวกที่เฝ้าดูจากระยะไกลบอกว่าเห็นคนของกลุ่มทไวไลต์เข้าออกถ้ำ ส่วนใหญ่อาศัยความมืด\n\nตามหาที่มั่นนี้ให้เจอ ถ้าเป็นอย่างที่ข้าคิด เราต้องสังหารผู้นำของพวกมันเสียก่อน ถึงจะเดินหน้าขับไล่พวกมันออกจากดินแดนนี้ได้" },
        completion = { "24:1184401455:408830673 N 45:1608207462:31440927", "สยองเอาเรื่องนะ {name} พันธมิตรของเราจะยินดีกับสิ่งที่เจ้าทำ" },
        progress = { "31:1072815616:48611292", "กำจัดภัยนั้นได้หรือยัง?" },
        required = { [267086] = { "11:1411833122:1338288825", "ดวงตาของ Mugg" } },
        steps = { { "11:1411833122:1338288825", "ดวงตาของ Mugg" } },
    },
    [94984] = { -- Tome of Twilight
        title = { "16:568130767:1224221991", "คัมภีร์ทไวไลต์" },
        objective = { "78:2094249198:1779469553", "ฆ่า Nar'gurk ใน Krol'dok Stronghold แล้วนำข้อมูลสำคัญที่พบกลับมา" },
        description = { "483:64977138:581353179", "เราพยายามเท่าไร พวกทไวไลต์ก็ยังไม่หมด เราคิดว่าพวกมันต้องมาจากที่อื่น\n\nสัตว์เลี้ยงตัวใหม่ที่เจ้าหามาให้เปิดโอกาสให้ข้าไต่ถามทาสทไวไลต์ที่รักของเราอย่างสุภาพ ว่ารู้อะไรเรื่องที่มาของนายเก่าบ้าง เรื่องน่าสนใจคือมันพูดถึงเวทเงาและโอเกอร์ชื่อ Nar'gurk ในที่มั่นลับทางเหนือของ Sunnyglade\n\nตามหามัน ฆ่ามันเสีย แล้วนำสิ่งที่หาได้กลับมา เรื่องนี้ต้องมีอะไรให้เราเรียนรู้บ้าง" },
        completion = { "151:916347417:1569928006 N 24:1106964085:363979702", "อย่างที่ข้าคิดไว้ มีทั้งมนตร์ผนึกและรหัสเงา อาจต้องใช้เวลาหลายสัปดาห์กว่าจะเข้าใจข้อความข้างใน\nแต่งานของเจ้าช่วยได้มากจริง ๆ {name} ข้าจะเริ่มทันที" },
        progress = { "26:9954805:1776161257", "เจออะไรน่าสนใจไหม?" },
        required = { [267104] = { "16:568130767:1224221991", "คัมภีร์แห่ง Twilight" } },
        steps = { { "16:568130767:1224221991", "คัมภีร์แห่ง Twilight" } },
    },
    [95141] = { -- Report to Rog'mar
        title = { "17:2109876299:1484697567", "ไปรายงานตัวที่ร็อกมาร์" },
        objective = { "62:722963210:1733612691", "ไปรายงานตัวกับ Krom'rosh ที่ด่าน Rog'mar ใน Riverglades" },
        description = { "492:1541204036:1104575375", "ไกลออกไปทางตะวันออกเฉียงเหนือเลย Stonard มีดินแดนริมชายฝั่งตะวันออกที่กำลังสู้รบกันอยู่ เรียกว่า Riverglades\n\nหลายคนพยายามยึดครองดินแดนนี้ แต่สำเร็จเพียงหยิบมือ อย่างไรก็ตาม มีคนหนึ่งใช้ประสบการณ์จากการรบกับศัตรูตั้งด่านเล็ก ๆ ชื่อ Rog'mar ขึ้นมา แม้ถูกโจมตีมานับครั้งไม่ถ้วน ด่านก็ยังอยู่\n\nKrom'rosh อาจโหดเหี้ยม แต่ความมุ่งมั่นของเขาช่วยพันธมิตรเราไว้มาก ถ้าเจ้ามองหาการรบ ก็ไปทางตะวันออกเฉียงเหนือเพื่อพบสหายเก่าของเราเถอะ" },
        completion = { "258:294232196:1986116482", "Aggro'gosh ส่งเจ้ามาหรือ? ข้านับถือที่เขาเต็มใจสนับสนุนเรา แม้เรื่องที่เขากังวลจะเป็นเรื่องของเขาเองก็ตาม\nเราจะเอาชนะทั้งพวกมนุษย์และ Twilight's Hammer ถ้าเจ้ามองหาการรบ ก็มีงานให้เจ้าทำอีกมากในนามของ Horde" },
    },
    [95143] = { -- Finding Tan'jani
        title = { "16:1412568339:1407867400", "ตามหาทันจานี" },
        objective = { "44:1730895825:934223404", "ตามหา Tan'jani ที่ Rog'mar ใน Riverglades" },
        description = { "24:2011504683:2064717297 N 479:73575568:1473781191", "ข้าคอยดูเจ้ามาสักพักแล้ว {name} เจ้าดูแลตัวเองได้ดีทีเดียวแถวนี้ บางทีเจ้าอาจสนใจช่วยข้าตามหา Tan'jani น้องชายของข้า\n\nเขาคอยตามหาอะไรสักอย่างอยู่เสมอ ข้าก็ไม่รู้ว่าอะไร ตั้งแต่เขาออกเดินทาง ข้าได้รับข่าวสองครั้ง ครั้งแรกมาจากนักเดินทางที่บังเอิญเจอ Tan'jani แถวทางใต้ของ Loch Modan ครั้งที่สองเป็นจดหมายเปื้อนเลือด พูดถึง Riverglades กับที่ชื่อ Rog'mar ซึ่งอยู่ลงไปทางใต้ยิ่งกว่าเดิม ส่วนที่เหลืออ่านไม่ออก\n\nเจ้าคิดว่าจะช่วยตามหาเขาให้ข้าได้ไหม?" },
        completion = { "409:1784685216:867321409", "Tor'gan ส่งเจ้ามาไกลถึงนี่เพื่อตามหาข้ารึ? เขาคอยดูแลข้าเสมอ หวังว่าจะได้เจอเขาเร็ว ๆ นี้\nแต่ข้าจะไม่ทิ้งหน้าที่จนกว่างานจะเสร็จ เข้าใจนะ? ข้ารู้จัก Krom'rosh มานาน เกือบจะพอ ๆ กับ Tor'gan เชียว เกือบน่ะ\nที่นี่เรียบร้อยดี สหาย ไม่มีอะไรให้ห่วง ยกเว้นพวก Twilight ที่ชอบก่อเรื่อง ตา Krom'rosh อยู่ข้างกองไฟใหญ่ เขาเล่าเรื่องนี้ให้เจ้าฟังได้อีก" },
    },
    [95315] = { -- The Riverglades Report
        title = { "22:624573580:668046618", "รายงานจากริเวอร์เกลดส์" },
        objective = { "118:122348987:1656195183", "นำ Captain Nials' Correspondence ไปให้ Demar Brant ที่ Farholde Keep ริมชายฝั่งตะวันออกเฉียงใต้ใน Riverglades" },
        description = { "443:1541007426:992961473", "หน่วยสอดแนมคนหนึ่งรายงานว่ามีกองกำลังศัตรูขนาดใหญ่รวมตัวกันอยู่ไกลลงไปทางใต้ เลย Wetlands ไปมาก\n\nที่น่าแปลกยิ่งกว่าคือดูเหมือนจะมีชุมชนฝ่าย Alliance อยู่ที่นั่นด้วย Farholde หรือ? ชื่อคุ้น ๆ นะ\n\nเราอย่ารอเลย ติดต่อกันไว้ก่อนจะสายเกินไป ทางนี้มีเรื่องให้รับมือมากพอแล้ว\n\nเอาจดหมายนี้ไปมอบให้คนที่เป็นผู้นำกองกำลังที่นั่นที" },
        completion = { "199:513115482:1940211336", "รายงานนี้มาจากทางเหนือไกลขนาดนั้นเลยหรือ? ไม่น่าเชื่อว่าในที่สุดจะมีคนติดต่อมา เราพยายามกันมานานจนแทบหมดหวังแล้ว\n\nข้าจะให้คนส่งสารรีบนำคำตอบกลับไปให้" },
    },
    [95599] = { -- The Old Key
        title = { "11:1009116194:1415661777", "กุญแจเก่า" },
        objective = { "61:1822176327:1473447882", "หาหีบเก่าที่ใช้กุญแจดอกนี้เปิดได้ แถวบริเวณใกล้เคียงใน Feralas" },
        description = { "306:307658780:1845850225", "<กุญแจมีสนิมเกาะหนา ดูเหมือนจะแช่อยู่ใต้น้ำมานาน\n\nแถวนี้คงมีแม่กุญแจที่ไขได้ด้วยกุญแจดอกนี้ เจ้าต้องลองหา บ่อน้ำทางตะวันตกเฉียงใต้ของค่ายอาจเป็นจุดเริ่มต้นที่ดี>" },
        required = { [287992] = { "7:545619394:1054680829", "กุญแจเก่า" } },
        steps = { { "7:545619394:1054680829", "กุญแจเก่า" } },
    },
    [95787] = { -- Take Two With Water
        title = { "19:444193308:306578738", "สำรวจซากเมืองใต้น้ำ" },
        objective = { "86:1240633558:1776800637", "ใช้แผ่นหนังกับถ่านถูคัดลอกลายจารึกบนแผ่นศิลาที่พบใน Drowned City" },
        description = { "490:527997674:1173272616", "<มือของ Loremaster Dibbs สั่นขณะอ่านรายงานจากหน่วยสอดแนมและตำนานของโทรลล์>\n\nจะเป็นไปได้หรือ? จากรายงานนี้ เมืองโทรลล์ I'lalai ที่สาบสูญไปดูเหมือนจะโผล่ขึ้นมานอกชายฝั่ง Stranglethorn! เราต้องรีบไปสำรวจ ถ้าข้าค้นคว้ามาถูกทาง นี่อาจเป็นการค้นพบทางโบราณคดีครั้งสำคัญที่สุดในรอบศตวรรษ!\n\nข้ารู้ว่าต้องเดินทางไกลกว่าจะกลับถึง Stranglethorn แต่ถ้าเจ้าไปถึง Drowned City ช่วยรวบรวมตำนานที่พบที่นั่นแล้วนำกลับมาให้ข้าที" },
        completion = { "249:1465285062:835290230 N 38:935069432:1658191496", "ศิลาจารึกใหม่สี่แผ่น! เป็นข่าวดีจริง ๆ\nภาษา Zandali โบราณของข้าขึ้นสนิมไปบ้าง แต่ตำนานพวกนี้ดูเหมือนจะกล่าวถึง... สิ่งที่เรียกว่าโลอาแห่ง...\n<Loremaster Dibbs หรี่ตามองแผ่นหนัง>\nกระแสน้ำหรือ? ขะ... ข้าไม่รู้จักฉายานั้นเลย! ยอดเยี่ยม {name}! เราอาจบังเอิญพบโลอาที่ไม่เคยรู้จักมาก่อน!" },
        progress = { "92:2105630401:716199082 N 79:470207830:426051857", "ไม่รู้ว่าเพื่อน ๆ ใน Explorer's League ได้ข่าวเกาะที่โผล่ขึ้นมานี้หรือยัง...\nโอ้ {name} เจ้ากลับมาแล้ว ไปถึงซากเมืองโทรลล์หรือยัง? เจอตำนานใหม่บ้างไหม?" },
        required = { [270308] = { "27:1768202320:1734852945", "แผ่นจารึกแผ่นที่ 1 แห่ง I'lalai" }, [270309] = { "28:1968463714:344933929", "แผ่นจารึกแผ่นที่ 2 แห่ง I'lalai" }, [270310] = { "27:446665557:402557681", "แผ่นจารึกแผ่นที่ 3 แห่ง I'lalai" }, [270311] = { "28:250272693:310408723", "แผ่นจารึกแผ่นที่ 4 แห่ง I'lalai" } },
        steps = { { "27:1768202320:1734852945", "แผ่นจารึกแผ่นที่ 1 แห่ง I'lalai" }, { "28:1968463714:344933929", "แผ่นจารึกแผ่นที่ 2 แห่ง I'lalai" }, { "27:446665557:402557681", "แผ่นจารึกแผ่นที่ 3 แห่ง I'lalai" }, { "28:250272693:310408723", "แผ่นจารึกแผ่นที่ 4 แห่ง I'lalai" } },
    },
    [95788] = { -- Magics of the Drowned City
        title = { "26:2092221841:156862809", "เวทมนตร์แห่งนครจมน้ำ" },
        objective = { "8:1089852795:1107240600 W1 50:228790185:1336547455", "เก็บ I'lalai Fetish {world1} ชิ้นจากโทรลล์ใน Drowned City" },
        description = { "490:1483322116:1471717088", "เครื่องรางของพวก Skullsplitter ที่ Brother Nimetz ฝากเจ้ามานั้นทรงพลังจริง แต่ข้าไม่คิดว่ามันทำให้ Kurzen เป็นแบบนั้น อย่างน้อยก็ไม่ใช่โดยตรง\n\nถึงอย่างนั้น ถ้าข่าวลือเป็นจริงและเมืองโทรลล์ I'lalai ที่สาบสูญโผล่พ้นหลุมศพใต้น้ำขึ้นมาได้ เวทมืดที่ใช้ยกเมืองเคราะห์ร้ายแห่งนั้นขึ้นมาก็อาจเกี่ยวข้อง\n\nถ้าเจ้ากล้าลงไปใน Drowned City แห่ง I'lalai ช่วยเก็บเครื่องรางโทรลล์ที่พบกลับมาให้ข้าศึกษาต่อด้วย" },
        completion = { "501:691797570:2085197622", "ข้าไม่ใช่นักเวท แต่ยังดูออกว่าเครื่องรางพวกนี้ต่างจากที่เคยตรวจดูมาก บางส่วนทำซับซ้อนกว่า บางส่วนก็เรียบง่ายกว่า และดูเหมือนมีรูปอสรพิษทะเลยักษ์อยู่ด้วย\nน่าสนใจจริง ๆ\nจากที่เจ้าเล่า ทั้งอันเดดที่เดินเพ่นพ่าน โจรสลัดที่บุกเข้ามา พิธีกรรมโลหิต และกองกำลังนากาต่างมารวมกันที่ซากเมือง ดูเหมือนตอนนี้ I'lalai จะเป็นแหล่งที่เวทมนตร์หลายแขนงปะปนกันไปหมด\nเรื่องนี้ต้องศึกษาต่ออย่างแน่นอน" },
        progress = { "143:1261567895:662660228", "เจ้าไปถึงนครจมน้ำในตำนานแล้วหรือ? พบอะไรบ้าง?\nมาสิ ถ้าเจ้ามีเวลา ข้าอยากฟังทุกอย่างที่เห็นอย่างละเอียด" },
        required = { [270343] = { "14:1937757510:2829458", "เครื่องราง I'lalai" } },
        objectiveLabels = {
            item = { ["I'lalai Fetish"] = "เครื่องราง I'lalai" },
        },
    },
    [95789] = { -- Shady Saltseers
        title = { "15:969194444:1341526259", "พวกซอลต์เซียร์ไม่น่าไว้ใจ" },
        objective = { "8:1089852795:1107240600 W1 68:562232251:229362832", "เก็บ Voodoo Infused Artifact {world1} ชิ้นจากโจรสลัด Saltseer ใน Drowned City" },
        description = { "500:3718676:820729184", "ว่าไงสหาย ดูท่าเจ้าจะสู้เอาตัวรอดได้ดีนะ\n\nBaron Revilgaz ให้ข้าคอยฟังข่าวของวิเศษ ได้ยินมาว่าซากเมืองโทรลล์ที่จมน้ำจู่ ๆ ก็... เลิกจมอย่างลึกลับ แปลว่ามีของที่ยังไม่มีเจ้าของอยู่เพียบ เข้าใจที่ข้าหมายถึงใช่ไหม\n\nปัญหาคือโจรสลัดก็สนใจด้วย! ไม่ใช่โจรสลัดธรรมดา พวก Saltseer เจาะจงสะสมของวิเศษ ข้าต้องการให้เจ้าเข้าไปใน Drowned City กำจัดพวกมันแล้วเอาของที่มันขโมยมากลับมา" },
        completion = { "92:2010082241:1225338878", "เยี่ยม! ข้าจะไปบอกท่านบารอนเดี๋ยวนี้\nนี่ส่วนแบ่งรางวัลของเจ้าตามสัญญา" },
        progress = { "141:283229570:1489847303", "ว่าไง! ได้จัดการโจรสลัดตัวแสบพวกนั้นหรือยัง? ลูกเรือข้าพร้อมออกไปปล้น... เอ่อ สำรวจซากเมืองโทรลล์แล้ว" },
        required = { [270333] = { "23:1804281132:541693707", "โบราณวัตถุอาบมนตร์วูดู" } },
        steps = { { "23:1804281132:541693707", "โบราณวัตถุอาบมนตร์วูดู" } },
    },
    [95791] = { -- The Saltseer Captain
        title = { "20:514903913:1291449812", "กัปตันแห่งซอลต์เซียร์" },
        objective = { "67:206558932:1837767325", "กำจัด Saltseer Coroner 3 คนและ Captain Dreadrise ใน Drowned City" },
        description = { "466:962034556:272371313", "โจรสลัด Saltseer ทำข้าปวดหัวมาพักหนึ่งแล้ว พอรู้ว่าพวกมันอยู่ใน Drowned City ยิ่งแย่เข้าไปใหญ่ พวกมันก่อเรื่องเสมอ แต่มีอยู่กัปตันหนึ่งที่ข้าอยากให้หายไปให้พ้น ไอ้กัปตัน Dreadrise นั่นแหละ!\n\nมันกับลูกเรือเก่งเรื่องกวาดของวิเศษที่ข้าตามหา ข้าเบื่อแข่งกับพวกมันเต็มที\n\nข้าอยากให้เจ้าจัดการ Captain Dreadrise กับพวก Saltseer Coroner ของมันให้พ้นทาง อย่างถาวร" },
        completion = { "175:2086875834:323694561", "ข้าไม่รู้จะขอบใจเจ้าอย่างไรเลย! คืนนี้คงหลับสบายขึ้นเมื่อรู้ว่าพวก Saltseers เหลือน้อยลง\nท่านบารอนก็ซาบซึ้งในสิ่งที่เจ้าทำเช่นกัน นี่เงินค่าหัวของเจ้า" },
        objectiveLabels = {
            monster = { ["Captain Dreadrise slain"] = "ปราบ กัปตัน Dreadrise", ["Saltseer Coroner slain"] = "ปราบ ผู้ชันสูตรศพ Saltseer" },
        },
    },
    [97130] = { -- Ancient Gurubashi Secrets
        title = { "25:765355353:178168302", "ความลับโบราณของกูรูบาชิ" },
        objective = { "56:1220874033:712860366", "นำ Ancient Gurubashi Idol กลับมาจาก Drowned City" },
        description = { "454:1391040180:1429992441", "Lan'dalock กับข้ากำลังคุยกันถึงเรื่องที่เพิ่งเกิดขึ้นในทะเลใต้ ซากเมืองกูรูบาชิโบราณโผล่ขึ้นมาอย่างกะทันหันนอกชายฝั่ง Stranglethorn Vale\n\nสถานที่แบบนี้มีคุณค่าทางโบราณคดีสูง เราอยากได้รูปเคารพสักชิ้น พวกหมอผีบางคนในหมู่กูรูบาชิโบราณใช้มันเป็นสื่อรวมพลังในพิธีเวทโลหิต\n\nเข้าไปใน ‘Drowned City’ แห่งนี้แล้วนำรูปเคารพกลับมาให้เราสักชิ้น" },
        completion = { "199:449516675:1559083437", "ขอบใจที่นำสิ่งนี้กลับมา Lan'dalock กับข้าถกกันมานานเรื่องธรรมชาติของเวทโลหิต Gurubashi วัตถุโบราณอย่างนี้จะมีค่ามากในการช่วยให้เราเข้าใจเวทดึกดำบรรพ์แขนงนี้ดีขึ้น" },
        progress = { "491:737074772:327596330", "เวทโลหิต Gurubashi น่ารังเกียจเหลือเกิน แต่ก็น่าสนใจยิ่งนัก เจ้ารู้หรือไม่ว่าจักรวรรดิโทรลล์โบราณจะจัดพิธีที่เรียกว่า “จันทร์โลหิต” ขึ้นเป็นระยะ เพื่อจงใจปลุกความคลุ้มคลั่งและความกระหายเลือดไม่รู้สิ้นในหมู่ประชากรทั้งหมดของตน?\nทำไมถึงจงใจให้ผู้คนของตนต้องผ่านช่วงแห่งความโกลาหลและการเข่นฆ่าไร้ปรานี? ทำไปเพื่ออะไร? ในทางวิชาการมันน่าศึกษามาก แต่ข้าขนลุกเมื่อนึกว่าชีวิตในวัฒนธรรมเช่นนั้นคงโหดร้ายเพียงใด" },
        required = { [276894] = { "22:29983011:1102554127", "รูปเคารพโบราณแห่ง Gurubashi" } },
        steps = { { "22:29983011:1102554127", "รูปเคารพโบราณแห่ง Gurubashi" } },
    },
    [94841] = { -- Lost Shipping Crate
        title = { "19:1978489717:978668435", "ลังสินค้าที่หายไป" },
        objective = { "91:1820117850:836666892", "นำ Lost Shipping Crate ไปให้ Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades" },
        description = { "494:1869572930:1223022649", "<ด้านข้างลังมีป้ายเขียนด้วยมือ ทางขวาเป็นแผนที่ มีวงกลมสีแดงขนาดใหญ่ตรงชายฝั่งตะวันออกเฉียงใต้ อยู่เหนือวิหารที่วาดไว้แบบลวก ๆ โดยมีน้ำและสัตว์มีปีกอะไรสักอย่างล้อมอยู่ ส่วนทางซ้ายเขียนข้อความตัวโตมาก>\n\nทรัพย์สินของ FRIZ FRAZZLESPARK\n\nPOWDERFUSE PORT\n\nคำเตือน ห้ามแกะ ห้ามเปิดโดยไม่มีผู้ควบคุม\n\n<ด้านล่างของป้ายมีข้อความเขียนเพิ่ม>\n\nหากพบลังนี้ กรุณาส่งคืน Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades", variants = { { "494:1014799557:1447789506", "<ด้านข้างลังมีป้ายเขียนด้วยมือ ทางขวาเป็นแผนที่ มีวงกลมสีแดงขนาดใหญ่ตรงชายฝั่งตะวันออกเฉียงใต้ อยู่เหนือวิหารที่วาดไว้แบบลวก ๆ โดยมีน้ำและสัตว์มีปีกอะไรสักอย่างล้อมอยู่ ส่วนทางซ้ายเขียนข้อความตัวโตมาก>\n\nทรัพย์สินของ FRIZ FRAZZLESPARK\n\nPOWDERFUSE PORT\n\nคำเตือน ห้ามแกะ ห้ามเปิดโดยไม่มีผู้ควบคุม\n\n<ด้านล่างของป้ายมีข้อความเขียนเพิ่ม>\n\nหากพบลังนี้ กรุณาส่งคืน Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades" } } },
        completion = { "229:1100631496:2139433458", "เจ้าบอกว่าไปเจอนี่ที่ไหนนะ? แปลกใจจริงที่เจ้ากลับมาครบสามสิบสอง ขอบใจนะ เจ้าหนู\n\nนี่ ถ้าเจ้าชอบช่วยเหลือคนอื่น แถวนี้คงมีอีกหลายคนที่อยากขอแรงเจ้า ทำไมไม่อยู่ต่ออีกสักพักล่ะ?" },
    },
    [94930] = { -- Lost Shipping Crate
        title = { "19:1978489717:978668435", "ลังสินค้าที่หายไป" },
        objective = { "91:1820117850:836666892", "นำ Lost Shipping Crate ไปให้ Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades" },
        description = { "494:1869572930:1223022649", "<ด้านข้างลังมีป้ายเขียนด้วยมือ ทางขวาเป็นแผนที่ มีวงกลมสีแดงขนาดใหญ่ตรงชายฝั่งตะวันออกเฉียงใต้ อยู่เหนือวิหารที่วาดไว้แบบลวก ๆ โดยมีน้ำและสัตว์มีปีกอะไรสักอย่างล้อมอยู่ ส่วนทางซ้ายเขียนข้อความตัวโตมาก>\n\nทรัพย์สินของ FRIZ FRAZZLESPARK\n\nPOWDERFUSE PORT\n\nคำเตือน ห้ามแกะ ห้ามเปิดโดยไม่มีผู้ควบคุม\n\n<ด้านล่างของป้ายมีข้อความเขียนเพิ่ม>\n\nหากพบลังนี้ กรุณาส่งคืน Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades", variants = { { "494:1014799557:1447789506", "<ด้านข้างลังมีป้ายเขียนด้วยมือ ทางขวาเป็นแผนที่ มีวงกลมสีแดงขนาดใหญ่ตรงชายฝั่งตะวันออกเฉียงใต้ อยู่เหนือวิหารที่วาดไว้แบบลวก ๆ โดยมีน้ำและสัตว์มีปีกอะไรสักอย่างล้อมอยู่ ส่วนทางซ้ายเขียนข้อความตัวโตมาก>\n\nทรัพย์สินของ FRIZ FRAZZLESPARK\n\nPOWDERFUSE PORT\n\nคำเตือน ห้ามแกะ ห้ามเปิดโดยไม่มีผู้ควบคุม\n\n<ด้านล่างของป้ายมีข้อความเขียนเพิ่ม>\n\nหากพบลังนี้ กรุณาส่งคืน Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades" } } },
        completion = { "229:1100631496:2139433458", "เจ้าว่าไปเจอนี่ที่ไหนนะ? แปลกใจจริงที่เจ้ากลับมาได้ครบสามสิบสอง ขอบใจนะ เจ้าหนู\nนี่ ถ้าเจ้าชอบช่วยคนอื่น ข้าว่าคนแถวนี้อีกหลายคนมีงานให้ช่วย ลองอยู่แถวนี้อีกสักพักสิ" },
    },
    [94961] = { -- Biting the Hand
        title = { "15:239056664:1476239966", "กัดมือผู้เลี้ยง" },
        objective = { "41:1818102616:440874611", "นำ Twilight Finger Bone 20 ชิ้นไปให้ Fuzzle" },
        description = { "69:781941667:151490370 R 94:405543232:662241929", "<นอลล์หยิบทองออกจากกระเป๋ามาชูให้เจ้าดู>\n\n{race} ข้ามีข้อแลกเปลี่ยน! ข้ายังมีทองอีก ช่วยข้าล้างแค้นแล้วข้าจะพาไปดู!" },
        progress = { "45:643041924:963945406", "เอานิ้วมาให้ข้า *แล้วข้าค่อย* พาเจ้าไปดูสมบัติ" },
        completion = { "62:897057548:856888082", "ใช่ ๆ ดีมาก! ทีนี้เราออกไปจากที่นี่แล้วไปหาสมบัติกัน" },
        required = { [267073] = { "20:1467216529:405951499", "กระดูกนิ้วของคนกลุ่ม Twilight" } },
        steps = { { "20:1467216529:405951499", "กระดูกนิ้วของคนกลุ่ม Twilight" } },
    },
    [94963] = { -- Biting the Hand
        title = { "15:239056664:1476239966", "กัดมือผู้เลี้ยง" },
        objective = { "16:733584959:989253000", "<Fuzzle คำราม>" },
        description = { "6:1307169621:2127018702 R 135:1192760058:461266619", "มาเถอะ {race} ถึงเวลาออกจากที่นี่แล้ว ถ้าใครมาขวาง เราจะฉีกมันเป็นชิ้น ๆ!\n\nพอปลอดภัยแล้ว ข้าจะพาเจ้าไปรับรางวัล" },
        completion = { "106:2066655150:318441024", "<ดูเหมือน Fuzzle จะสะสมทองไว้ไม่น้อย อย่างน้อยก็ถือว่ามากสำหรับพวกนอลล์ ตอนนี้มันคงเป็นของเจ้าแล้ว>" },
        objectiveLabels = {
            event = { ["Help Fuzzle escape Sunnyglade."] = "ช่วย Fuzzle หนีออกจาก Sunnyglade" },
        },
    },
    [95118] = { -- Saltwater Savages
        title = { "17:897685806:1621445188", "ตัวร้ายริมทะเล" },
        objective = { "69:578022141:704867264", "กำจัด Murloc Oracle 8 ตัวและ Murloc Warrior 8 ตัวตาม Eastwind Shore" },
        description = { "289:198765833:1555221632", "เมอร์ล็อก เมอร์ล็อก เมอร์ล็อก! วัน ๆ ข้าได้ยินอยู่เรื่องเดียว ทั้งจากลูกเรือ ชาวประมง แม้แต่ลูกข้าเอง! ทุกคนมารุมบ่นใส่ข้าเรื่องพวกมัน! ก็ยอมรับว่ามันกวนใจ แต่ข้ามีท่าเรือให้ดูแลนะ!\n\nช่วยข้าหน่อยได้ไหม? จัดการพวกมันสักหน่อย แล้วข้าจะตอบแทนให้คุ้มเวลา" },
        completion = { "109:137153109:1409891522", "จัดการพวกมันแล้วรึ? ดี! อีกไม่นานคงมีตัวอื่นกลับมา แต่ระหว่างนี้อย่างน้อยข้าก็ได้อยู่สงบ ๆ สักพัก" },
        objectiveLabels = {
            monster = { ["Murloc Warrior slain"] = "ปราบ นักรบเมอร์ล็อก", ["Murloc Oracle slain"] = "ปราบ ผู้พยากรณ์เมอร์ล็อก" },
        },
    },
    [95119] = { -- Unfriendly Competition
        title = { "22:499867091:1792709113", "คู่แข่งไม่น่าคบ" },
        objective = { "5:409775429:850574908 W1 24:719231754:1785084896 W2 71:1435293472:1212488548", "กำจัด Eastsea Buccaneer {world1} คนและ Eastsea Musketeer {world2} คนตาม Eastwind Shore ทางเหนือของ Powderfuse Port" },
        description = { "415:1982073645:875313563", "รู้จักพวกโจรสลัด Eastsea ไหม? พวกนั้นไม่น่าคบจริง ๆ ขนาดข้าซึ่งดูแลที่ที่ชื่อ Powderfuse Port ยังพูดแบบนี้เลย\n\nมันทั้งชอบทำลายข้าวของ กระหายเลือด และที่แย่ที่สุดคือทำกำไรข้าหด! มันทั้งขโมยสินค้าและจมเรือ แต่ละอย่างทำข้าเสียเงินเป็นกอบเป็นกำ!\n\nเราต้องทำลายกิจการมันให้หมด เริ่มจากพวกที่อยู่ใกล้ที่สุด หาได้ตามชายหาดทางเหนือ" },
        completion = { "13:96413020:153092913 R 33:2034098219:199616043", "ทำได้ดี {race} ทีนี้ไปจัดการปลาตัวใหญ่กัน" },
        objectiveLabels = {
            monster = { ["Eastsea Buccaneer slain"] = "ปราบโจรสลัด Eastsea", ["Eastsea Musketeer slain"] = "ปราบพลปืนคาบศิลา Eastsea" },
        },
    },
    [95120] = { -- WANTED: Old Rot-Chum
        title = { "20:880598971:404737742", "ประกาศจับ เจ้าร็อตชัมเฒ่า" },
        objective = { "62:894312329:980053585", "นำหลักฐานการตายของ Old Rot-Chum ไปให้ Wharfmaster Whizzbuzz" },
        description = { "336:2104372632:830953069", "ลูกเรือและผู้ลงเล่นน้ำโปรดระวัง! มีผู้พบเมอร์ล็อกดุร้ายผิดปกติที่ชาวประมงเรียกว่า Old Rot-Chum โจมตีเรือพายและเรือเล็กในน่านน้ำทางใต้ ใกล้หมู่เกาะที่มีเมอร์ล็อกชุกชุม\n\nWharfmaster Whizzbuzz จะมอบรางวัลให้ผู้ที่นำหลักฐานการตายของมันมาส่ง" },
        completion = { "123:116069990:1666136106", "เอาละ แถวนี้มีเรื่องให้กังวลน้อยลงอีกเรื่อง ข้าเป็นหนี้เจ้าแน่ ๆ เอ้านี่ อย่าเอาไปใช้หมดทีเดียวล่ะ" },
        progress = { "25:1458100126:56696273 R 16:1637208830:1605578375", "ข้ามีงานล้นมืออยู่ {race} รีบว่ามา" },
        required = { [268341] = { "19:1108893782:1627682261", "ฉมวกที่มีคราบเน่า" } },
        steps = { { "19:1108893782:1627682261", "ฉมวกที่มีคราบเน่า" } },
    },
    [95121] = { -- A Taste of the Sea
        title = { "18:1913689311:614929655", "รสชาติจากท้องทะเล" },
        objective = { "77:807194582:1104456476", "รวบรวม Murloc Eye 12 ลูกและ Sand Crawler Meat 6 ชิ้นให้ Fimbo Greasemitz" },
        description = { "370:1022896991:1431383353", "ยินดีต้อนรับสู่ร้านอาหารริมน้ำของ Fimbo! เมนูวันนี้มีหมูป่าย่างกับปลาย่าง... เหมือนทุกวันเลย...\n\nถึงเวลาเปลี่ยนเมนูจริงจังเสียที ข้าเล็งสูตรสตูว์ทะเลแบบใหม่ไว้ แต่ต้องมีเนื้อสด ใช้ลูกตาเมอร์ล็อกสักหน่อยกับเนื้อปูก็น่าจะได้\n\nหาได้ทั้งสองอย่างตามชายหาดใกล้ ๆ ไม่มีอะไรสู้วัตถุดิบพื้นบ้านสด ๆ ได้หรอก!" },
        progress = { "99:2031168370:1347495385", "เคล็ดลับของลูกตาเมอร์ล็อกคือต้องรีบปรุงให้สุก จะได้ยังลิ้มรสเค็มของน้ำทะเลอยู่!" },
        completion = { "71:1902043847:2123638880", "ชิ้นเนื้อน่ากินทีเดียว ผู้ช่วยพ่อครัวของข้า เดี๋ยวจะต้มสตูว์ทะเลให้หนึ่งหม้อ!" },
        required = { [268344] = { "20:1791874200:1347440012", "ดวงตาเมอร์ล็อกน้ำเค็ม" }, [268345] = { "17:1032816100:1445457648", "เนื้อปูทราย" } },
        steps = { { "20:1791874200:1347440012", "ดวงตาเมอร์ล็อกน้ำเค็ม" }, { "17:1032816100:1445457648", "เนื้อปูทราย" } },
    },
    [95122] = { -- Unchecked Expansion
        title = { "19:482206700:1374424392", "หยุดพวกมันก่อนรุกเข้ามา" },
        objective = { "5:409775429:850574908 W1 21:1437963547:2088086319 W2 47:412209488:27802276", "กำจัด Eastsea Raider {world1} คนและ Eastsea Bombardier {world2} คนให้ Wharfmaster Whizzbuzz" },
        description = { "339:140224107:1211527070", "โจรสลัด Eastsea ที่เจ้าจัดการไปถึงจะอันตราย แต่ก็แค่พวกปลายแถว ทางเหนือมีพวกตัวใหญ่และโหดกว่า พวกมันปล้น Windstead กวาดของไปเท่าที่ขนได้ แล้วเผาจนราบ\n\nต้องหยุดพวกมันก่อนที่อาณาเขตจะลึกเข้ามาบนแผ่นดินกว่านี้ ไปตัดกำลังมันเสีย" },
        completion = { "144:506766490:1973920703", "เห็นแล้วว่าเจ้ากล้าลงมือทำงานสกปรก ข้าชอบแบบนั้น\n\nด้วยฝีมือเจ้า ตอนนี้ทุกอย่างเริ่มเข้าทางแล้ว เราจะได้จัดการพวกวายร้ายนั่นให้สิ้นซากเสียที" },
        objectiveLabels = {
            monster = { ["Eastsea Raider slain"] = "ปราบผู้จู่โจม Eastsea", ["Eastsea Bombardier slain"] = "ปราบพลปืนใหญ่ Eastsea" },
        },
    },
    [95123] = { -- A Blast Ye Scurvy Dogs!
        title = { "23:222641822:819222953", "เตรียมระเบิดพวกโจรสลัด" },
        objective = { "6:2056026185:230538954 W1 47:1605420841:1754671747", "ขโมย Eastsea Powder Keg {world1} ถังให้ Wharfmaster Whizzbuzz" },
        description = { "377:1635627175:1318290985", "ข้าชอบเห็นพวก Eastsea โดนจัดการก็จริง แต่เราต้องจัดการเรือมันด้วย จะปล่อยให้หนีไปตามกำลังเสริมไม่ได้ จริงไหม?\n\nข้ามีแผน แต่เราต้องใช้ดินปืน เยอะมากด้วย\n\nโจรสลัดน่าจะเก็บดินปืนไว้ใกล้ Winstead ทางเหนือที่เพิ่งถูกถล่ม ลองไปหามาให้ได้ แล้วข้าจะเล่าส่วนที่เหลือให้ฟังทีหลัง" },
        completion = { "133:694559474:1902246362", "<Whizzbuzz ผิวปากด้วยความประหลาดใจ>\nโห ใหญ่เบ้อเริ่มเลย! อยากจุดของพวกนี้ให้พวกโจรสลัดกระเด็นขึ้นฟ้าจะแย่แล้ว!" },
        progress = { "23:2087251901:1139218239", "ได้ดินปืนมาแล้วหรือยัง?" },
        required = { [268346] = { "18:1904664431:1750648523", "ถังดินปืนของ Eastsea" } },
        steps = { { "18:1904664431:1750648523", "ถังดินปืนของ Eastsea" } },
    },
    [95124] = { -- Admiral Lamora
        title = { "14:398007454:307892389", "พลเรือเอกลาโมรา" },
        objective = { "86:2145638416:606733900", "สังหาร Admiral Lamora ตามหาของที่เขาซ่อนไว้ แล้วนำไปให้ Wharfmaster Whizzbuzz" },
        description = { "444:106651675:1843949710", "ถึงเวลาจัดการหัวหน้าใหญ่แล้ว พลเรือเอก Lamora นั่นแหละ แน่นอนว่าข้าอยากให้มันตาย แต่ยังอยากได้อะไรจากมันอีกนิดหน่อย\n\nมันปล้นจนข้าเสียเงินไปมหาศาล ข้าว่าสมควรจะเอาคืนมาบ้าง\n\nLamora อยู่บนเรือ Eastsea สักลำทางตะวันออกเฉียงเหนือ หาให้เจอว่าลำไหนและซ่อนของไว้ตรงไหน เอาที่มันมีมาให้ข้าหมด ถ้าล็อกไว้ กุญแจน่าจะอยู่กับตัวมัน" },
        completion = { "262:2004556661:1261359185", "พูดตรง ๆ นะ ข้าไม่แน่ใจว่าเจ้าจะรอดจากการปะทะกับ Lamora ดูท่าเจ้าจะเก่งจริงนี่หว่า!\nถ้าอยากให้ช่วยอะไรก็เรียกหา Whizzbuzz คนนี้ได้เลย เผลอ ๆ ข้าเองก็อาจต้องมาขอให้เจ้าช่วยเหมือนกัน!\n<นายท่า Whizzbuzz ขยิบตาให้เจ้าแล้วแสยะยิ้ม>" },
        progress = { "84:670889548:1063608122", "ฆ่า Lamora ก็เพื่อเอาคืน ชิงของที่เขาปล้นไปกลับมาก็เพื่อให้เราเสมอตัว" },
        required = { [268506] = { "13:813328179:1299373471", "สมบัติที่ Lamora ปล้นมา" } },
        steps = { { "13:813328179:1299373471", "สมบัติที่ Lamora ปล้นมา" } },
        objectiveLabels = {
            monster = { ["Admiral Lamora slain"] = "ปราบ พลเรือเอก Lamora" },
        },
    },
    [95165] = { -- See Ya, Scallywags!
        title = { "19:1373711146:1077965482", "ลาก่อน พวกโจรสลัด!" },
        objective = { "69:1693543754:652564003", "วางระเบิดจุดชนวนจากระยะไกลบนเรือ Eastsea ทั้งสามลำ ลำละชุด" },
        description = { "432:89391988:1348481065", "เอาล่ะ นี่คือวิธีที่เราจะจมเรือพวกนั้น\n\nข้าเอาดินปืนที่เจ้าขโมยมาทำระเบิดตั้งเวลาได้ เจ้าแค่ขึ้นเรือ Eastsea ทีละลำ แล้ววางระเบิดในท้องเรือลำละชุด หาจุดใกล้ปืนใหญ่ ดินปืนตรงนั้นจะทำให้ระเบิดของเรายิ่งแรง พอวางครบแล้วก็รีบออกมา ข้าจะกดจุดชนวนเอง!\n\nแผนดีตรงที่เรียบง่ายนี่แหละ ว่าไหม?" },
        completion = { "196:1846484076:1448711164", "ดูเจ้าสิ นิ้วยังอยู่ครบ คิ้วก็อยู่ทั้งสองข้าง! เอ่อ... แน่ละ ข้ามั่นใจในฝีมือตัวเองอยู่แล้ว\nข้าว่าจะลากเก้าอี้มานั่งดูดอกไม้ไฟ ทำได้ดีมาก" },
        progress = { "140:1262644941:2048532999", "เจ้าอาจสงสัยว่านายท่าตัวเล็ก ๆ อย่างข้าไปรู้เรื่องทำระเบิดเองได้ยังไง\nเอาเป็นว่า... เมื่อก่อนข้าเคยทำมาหากินแบบไม่ค่อยสุจริตเท่าไร" },
        required = { [268505] = { "23:1375835476:450160742", "วัตถุระเบิดจุดชนวนระยะไกล" } },
        steps = { { "25:250288861:1156627121", "วางระเบิดบนเรือลำแรก" }, { "26:1438839193:741726916", "วางระเบิดบนเรือลำที่สอง" }, { "25:688945436:1895799580", "วางระเบิดบนเรือลำที่สาม" }, { "23:1375835476:450160742", "วัตถุระเบิดจุดชนวนระยะไกล" } },
    },
    [95254] = { -- WANTED: Trapclaw
        title = { "16:350094132:343445568", "ประกาศจับ แทรปคลอว์" },
        objective = { "44:1661486346:1386595892", "นำ Trapclaw's Pincer ไปให้ Fimbo Greasemitz" },
        description = { "334:1020441439:2080516582", "ประกาศถึงนักตกปลาทุกคน!\n\nข้ากำลังหาเนื้อปู แต่ขอแบบทั้งก้าม ไม่เอาเศษเนื้อแบบเดิม ข้าเห็นตัวเบ้อเริ่มคลานอยู่ใต้ท่าเรือ คอยขโมยเหยื่อกับตัดสายเบ็ด\n\nใครเอาก้ามของมันมาให้ ข้าจะให้รางวัล แถมแบ่งอาหารที่ข้าทำจากมันให้ชิมด้วย\n\n— Fimbo Greasemitz" },
        completion = { "142:1851323805:315067008", "เจ้างัดนี่ออกมาจากตัวมันเลยหรือ? ใช้ได้นี่! ใส่เนยหน่อย โรยเครื่องเทศสูตรลับของข้าอีกนิด มื้อนี้ต้องอร่อยสุด ๆ แน่!" },
        progress = { "17:3320913:798207022 R 1:63:63", "เป็นยังไงบ้าง {race}?" },
        required = { [268586] = { "17:374162609:2063747421", "ก้ามของ Trapclaw" } },
        objectiveLabels = {
            item = { ["Trapclaw's Pincer"] = "ก้ามของ Trapclaw" },
        },
    },
    [95260] = { -- Terrors From the Deep
        title = { "21:48939242:1142766805", "สิ่งน่าสะพรึงจากใต้ทะเล" },
        objective = { "83:1602122235:2073638720", "หาคนที่ Powderfuse Port ที่รู้ว่าสัตว์ประหลาดบนแผ่นหนังคืออะไร" },
        description = { "304:768953475:69422342", "บนแผ่นหนังมีภาพวาดป้ายเป็นเส้นกว้างด้วยเครื่องในปลากับหมึกปลาหมึก ดูคล้ายสัตว์ทะเลคอยาวผุดขึ้นจากคลื่น เจ้าตัวนี้คืออะไรกัน?\n\nท่าเรือที่ใกล้ที่สุดคือ Powderfuse Port ถ้าสัตว์ประหลาดมีจริงและซ่อนอยู่ในน่านน้ำแถบนี้ ต้องมีลูกเรือสักคนที่นั่นเคยเห็นแน่" },
        completion = { "51:297063409:238074143", "สัตว์ประหลาดทะเล...? เดี๋ยวนะ! เจ้า <สะอึก> ก็เห็นมันด้วยเรอะ!?" },
    },
    [95261] = { -- It Takes Guts
        title = { "13:1402946329:798917389", "งานนี้ต้องใช้ไส้" },
        objective = { "8:1089852795:1107240600 W1 20:2144607980:1042108469 W2 42:1102522194:440040946", "รวบรวม Beast Entrails {world1} ชุดและ Rotflesh Mushroom {world2} ดอกให้ Argo Brinewhistle" },
        description = { "500:1170444463:729434272", "ไอ้สัตว์ประหลาดคอยาวที่เจ้าว่านั่น... ข้าเห็นมันแถวหมู่เกาะตอนออกเรือ ข้าลอง <สะอึก> บอกคนอื่นแล้ว แต่ไม่มีใครเชื่อ <สะอึก> อาร์โกแก่ ๆ อย่างข้าหรอก ว่าข้าเป็นแค่... แค่ชาวประมงขี้เมาที่แต่งเรื่องไปเรื่อย!\n\nเดี๋ยวได้เห็นกัน... ขอแค่ข้ามีเหยื่อก่อน...\n\nเฮ้! อย่ายืนเฉยสิ! ข้าต้องใช้เครื่องใน เยอะ ๆ เลย สัตว์อะไรก็ได้แถวนี้ ยิ่งเหม็น <สะอึก> ยิ่งดี แล้วข้าก็ต้องใช้เห็ด Rotflesh ด้วย มันขึ้นอยู่ในถ้ำข้าง Windstead" },
        progress = { "74:1100638693:2124076666", "พอเราจับเจ้าตัวนั้นได้... โฮ่ ๆ... จะไม่มีใครหัวเราะเยาะ Argo คนนี้อีก!" },
        completion = { "139:1928983423:942426625", "<อาร์โกรีบยกมือปิดปากเมื่อได้กลิ่น>\n\nอึ๋ย... ทำได้ดี กัปตัน ทีนี้ <สะอึก> เอาของพวกนั้นไปเก็บก่อนข้าจะอ้วกอีก..." },
        required = { [268632] = { "14:1569798591:1500365532", "เครื่องในสัตว์" }, [268664] = { "17:1970052191:1716522028", "เห็ด Rotflesh" } },
        steps = { { "14:1569798591:1500365532", "เครื่องในสัตว์" }, { "17:1970052191:1716522028", "เห็ด Rotflesh" } },
    },
    [95288] = { -- Smuggler's Paradise
        title = { "19:173433200:838405754", "สวรรค์ของนักลักลอบขนของ" },
        objective = { "8:1089852795:1107240600 W1 57:216040525:904299444", "รวบรวม Smuggled Goods {world1} ชุดให้ Friz Frazzlespark ที่ Powderfuse Port" },
        description = { "457:376697055:1946688348", "ดูท่าเจ้าจะชินกับการทำตามที่คนอื่นสั่ง ข้าชอบลูกน้องแบบนี้แหละ ฝึกอีกหน่อยเจ้าคงมีประโยชน์มาก มาลองดูกัน\n\nเมื่อไม่นานมานี้โจรสลัด Eastsea ฉกของที่ข้าขโมยมาไปทั้งเที่ยวเรือ เล่นไม่แฟร์เลย ข้าขโมยมาก่อนนะ!\n\nบทเรียนแรก เจ้าลูกน้อง อย่าหักหลังคนที่ถนัดหักหลังคนอื่น ไปสั่งสอนมันว่าเล่นผิดคนแล้ว เอาของข้าคืนมา ใช้กำลังด้วยจะยิ่งดี" },
        completion = { "223:1606577328:599560144", "ดูท่าเจ้าจะเรียนบทแรกได้ดีนะ ลูกน้อง ข้าจะไม่คิดเงินค่าเคล็ดลับที่สอนให้ด้วย! ข้าเป็นหัวหน้าที่ดีใช่ไหมล่ะ?\nใช้เวลาคิดทบทวนสิ่งที่เพิ่งเข้าใจสักหน่อย แล้วค่อยไปทำงานชิ้นต่อไป" },
        progress = { "86:323277646:353129733", "ฝึกไปถึงไหนแล้ว? ก็แค่เชือดคอไม่กี่คนเอง ข้าหวังในตัวเจ้าไว้สูงนะ เจ้าหนู" },
        required = { [268796] = { "14:1759670443:679045291", "สินค้าลักลอบขน" } },
        steps = { { "14:1759670443:679045291", "สินค้าลักลอบขน" } },
    },
    [95294] = { -- Smuggler's Bargain
        title = { "18:1664372840:1034608608", "ข้อตกลงของนักลักลอบ" },
        objective = { "47:975649745:1996231889", "กลับไปหา Friz Frazzlespark ที่ Powderfuse Port" },
        description = { "338:245988515:2091922075 C 105:896728818:1524655761", "Friz รู้วิธีทำให้คนเข้าใจที่นางต้องการจริง ๆ เอาล่ะ ข้าไม่คัดค้าน พวกโจรสลัด Eastsea จะไม่ก้าวก่ายธุรกิจนาง แลกกันแล้วบางทีเราอาจตกลงทำงานร่วมกันได้ เป็นโจรสลัดก็ลำบากพอแล้วถ้ามีก็อบลินที่ถูกหักหน้าคอยส่งนักผจญภัยมาไล่ล่าทั้งวัน\n\nกลับไปหาเจ้านายเถอะ {class} บอก Friz ว่ามีกัปตันคนใหม่คุมอยู่ และเขามองเห็นโอกาสทำกำไรร่วมกันในภายหน้า" },
        completion = { "118:1713399324:979228762", "กัปตันอะไรนะ? เอาเถอะ ไม่ว่าเขาจะเป็นใคร ฟังดูเหมือนเจ้าสองคนได้เรียนบทเรียนสำคัญข้อต่อไปของข้าแล้ว\n\nอย่าคิดหักหลังข้าเด็ดขาด" },
    },
    [95312] = { -- Coming to Collect
        title = { "17:900538642:503630449", "มาทวงเงิน" },
        objective = { "39:1377666237:1619359852", "คุยกับ Fizbuz Mithril ที่ Gadgetzan" },
        description = { { "444:1366195902:655148041", "445:279352451:1786759330" }, "ข้าไม่มีเงินของ Friz หรอก คือเคยมี แต่เอาไปแทงข้าง Slugjaw ตัวนี้หมดแล้ว ที่สนามประลองของ Fizbuz ใน Gadgetzan\n\nอย่ามองข้าแบบนั้นสิ ลงทุนเข้าท่านะ ข้าชนะได้เงินก้อนโต! แค่ยังไม่มีโอกาสไปเอาเงินรางวัล ถ้าเจ้าเป็นเด็กเดินเรื่องคนใหม่ของ Friz ก็ไปเอามาแทนข้าทีสิ ข้าปวดหลังอยู่ รู้ไหม\n\nเฮ้ เจ้าไม่อยากกลับไปมือเปล่าใช่ไหม? Gadgetzan อยู่ทางตะวันตกจากที่นี่ หาไม่ยากหรอก" },
        completion = { "82:2009590978:1328519208", "ยินดีต้อนรับ สหาย! เจ้าจะมาลงประลองในสังเวียน Gadgetzan ที่ขึ้นชื่อเรื่องอื้อฉาวใช่ไหม?" },
        logReady = { "38:1450942946:1766413039", "คุยกับ Fizbuz Mithril ที่ Gadgetzan" },
    },
    [95322] = { -- Get the Goods
        title = { "13:1329555204:1625892077", "ไปรับสินค้า" },
        objective = { "68:1532676160:1072961092", "หา Bloodsail Trunk นอก Booty Bay ใน Stranglethorn Vale" },
        description = { "496:899529958:1076793443", "มาถูกจังหวะพอดีเลยสหาย ข้ากำลังจะไปรับสินค้าจากโจรสลัด Bloodsail พวกนั้นเป็นเพื่อนดี ๆ ของข้า ยินดีหาให้เสมอถ้า Friz ยอมจ่าย\n\nแต่เอ่อ เผื่อไว้ก่อน ถ้าเจ้าไปติดต่อแทนข้าก็คงดี คนคุมกองสินค้าที่เก่งรู้ว่าอวดกำลังบ้างก็ไม่เสียหาย เอาไว้ปรามกันเท่านั้นแหละ\n\nพวกนั้นบอกว่าเก็บของไว้ในหีบบนเนินนอกเมืองให้ปลอดภัย ช่วยไปดูให้ข้าหน่อยสิ?" },
        completion = { "208:999325422:663002878", "Venture Co. งั้นเรอะ? แล้วหีบนั่นก็ว่างเปล่าด้วย?\nไอ้พวกต้มตุ๋นมันขโมยเงินข้า! ข้าว่าแล้วว่าค้าขายกับโจรสลัดไม่ได้เรื่องพวกนั้นมีแต่เจ๊ง! ใครกล้าเบี้ยวข้อตกลงกับ Ruzzgot อย่าหวังว่าจะลอยนวล" },
        steps = { { "24:973239285:2028481432", "ตรวจหีบ Bloodsail" } },
    },
    [95326] = { -- The Big Payback
        title = { "15:1896991957:1448434005", "เอาคืนให้สาสม" },
        objective = { "81:716437395:1277266621", "ฆ่า Venture Co. Agent แล้วนำ Ruzzgot's Shipment กลับไปให้เขาที่ Booty Bay" },
        description = { "200:948633515:1538641187", "<สมุดบัญชีบันทึกการส่งของของ Ruzzgot แต่ละครั้ง ข้อความสุดท้ายระบุว่าการปล้นสำเร็จ และเจ้าหน้าที่ Venture Co. ที่อยู่ใกล้ ๆ รับของมีค่าของ Ruzzgot ไป ของน่าจะยังอยู่กับเขา>" },
        completion = { "160:1662943309:1251238499", "ให้มันได้อย่างนี้สิ! ถ้าไว้ใจให้คนคุมคาราวานส่งของถึงมือไม่ได้ แล้วจะไว้ใจให้เขาทำอะไรได้อีก?\nนี่ เจ้าอยากให้ข้าช่วยส่งของนี่ไป Powderfuse Port ไหม?" },
        progress = { "37:1806468708:1322513374", "ว่าไง? รู้หรือยังว่าใครขโมยของข้าไป?" },
        required = { [268810] = { "18:603052886:188136537", "สินค้าของ Ruzzgot" } },
        steps = { { "18:603052886:188136537", "สินค้าของ Ruzzgot" } },
    },
    [95327] = { -- All's Well That Ends Well
        title = { "25:368380947:2027767115", "จบสวยก็เป็นอันดี" },
        objective = { "66:1641935490:495423396", "กลับไปหา Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades" },
        description = { "245:1566324131:216142172", "ข้อตกลงก็ต้องเป็นข้อตกลง Venture Co. ได้รับผลที่สมควร Friz ได้ของ ทุกคนพอใจ โดยรวมถือว่าซื้อขายกันราบรื่นดีนะ ข้าว่า\n\nทีนี้ไปได้แล้ว เดี๋ยวข้ามีของอีกเที่ยวจากโจรสลัด Southsea เข้ามา" },
        completion = { "238:1160937550:1483343890", "ดีใจที่เจ้ากลับมาถึงสักที ไปเสียนานเลย ข้าเคยลองเปิดเส้นทางค้าขายกับ Booty Bay แต่ทางนั้นไม่สนใจ คงไม่อยากทำธุรกิจกับเมืองที่ชื่อ Powderfuse Port ละมั้ง ใครจะไปรู้\nเอาเถอะ ทำได้ดี เจ้าหนู" },
        progress = { "93:1851653511:536877213", "ถ้าไม่มีเลือดติดมาสักหน่อยก็ไม่ใช่งานส่งของของ Ruzzgot แล้ว ดูท่าเจ้าคงสนุกน่าดูสิ?" },
        required = { [268810] = { "18:603052886:188136537", "สินค้าของ Ruzzgot" } },
        steps = { { "18:603052886:188136537", "สินค้าของ Ruzzgot" } },
    },
    [95383] = { -- Shipping and Handling
        title = { "21:2120821290:697834013", "จัดส่งสินค้า" },
        objective = { "59:1880743839:748848694", "นำ Friz's Secret Stash ไปให้ Tazzik ที่ Steamwheedle Port" },
        description = { "427:1060391113:1505026369", "<Wharfmaster Steamfizzle ตรวจดูเหรียญที่เจ้ายื่นให้>\n\nโฮ่! Friz สอนเด็กรุ่นใหม่มาดีจริง ๆ ให้รอนานไปหน่อยนะ คุณผู้ชาย เจ้ามาส่งลังให้ใครสักคนในเมืองใช่ไหม? ข้าไม่รู้อะไรเรื่องนั้นหรอก แต่ถ้ารู้ ข้าจะไปคุยกับ Tazzik ที่ท่าเรือ ดูเหมือนเขาจะสนใจของแบบนั้น\n\nแต่รีบหน่อยล่ะ เข้าใจนะ ไม่อยากให้ใครคิดผิดไป", variants = { { "429:357043915:43668049", "<Wharfmaster Steamfizzle ตรวจดูเหรียญที่เจ้ายื่นให้>\n\nโฮ่! Friz สอนเด็กรุ่นใหม่มาดีจริง ๆ ให้รอนานไปหน่อยนะ คุณผู้หญิง เจ้ามาส่งลังให้ใครสักคนในเมืองใช่ไหม? ข้าไม่รู้อะไรเรื่องนั้นหรอก แต่ถ้ารู้ ข้าจะไปคุยกับ Tazzik ที่ท่าเรือ ดูเหมือนเขาจะสนใจของแบบนั้น\n\nแต่รีบหน่อยล่ะ เข้าใจนะ ไม่อยากให้ใครคิดผิดไป" } } },
        completion = { "292:1174478027:2079996878", "โอ้โห ของงาม ๆ มาแล้ว! Friz จัดให้ได้จริง ๆ เห็นไหมว่าของพวกนี้คุณภาพดีแค่ไหน\nอะไรนะ? อย่ามามองข้าสิ ข้าไม่ได้บอกให้เจ้าเอาทองทั้งหมดไปใช้ทำเรื่องผิดกฎหมาย สำหรับข้า ของล็อตนี้ผ่านศุลกากรเรียบร้อยแล้ว ส่วนเงินของ Friz น่ะ... นั่นอาจเป็นปัญหา" },
        progress = { "91:608323509:1447850259", "อี๋ ไม่ต้องบอกก็รู้ว่ามาจากไหน กลิ่น Powderfuse Port ติดตัวเจ้ามาเต็ม ๆ" },
        required = { [268811] = { "19:2122966776:1524731936", "ของที่ Friz ซ่อนไว้" } },
        steps = { { "19:2122966776:1524731936", "ของที่ Friz ซ่อนไว้" } },
    },
    [95472] = { -- Consolation Prize
        title = { "17:1951434315:1335447989", "รางวัลปลอบใจ" },
        objective = { "68:612840778:2024980263", "นำ Tazzik's Sweaty Shirt ไปให้ Friz Frazzlespark ที่ Powderfuse Port" },
        description = { "123:919787286:760061388", "ข้าบอกแล้วไงว่าคืนเงินให้ Friz ไม่ได้! ข้าไม่เหลืออะไรนอกจากเสื้อติดตัวตัวนี้!\n\nทำไมเจ้ามองข้าแบบนั้นล่ะ..." },
        completion = { "253:291829533:856567970", "เขาทำอะไรนะ!? ไอ้ตัวแสบเอ๊ย!\n<Friz ขยำเสื้อเป็นก้อนแล้วเหยียบลงกับพื้น>\nบทเรียนใหม่ ลูกน้อง! อย่าเชื่อแค่คำสัญญา และเก็บเงินสดตอนส่งของด้วย\nเอ้า นี่ส่วนแบ่งกำไรของเจ้า ไม่ต้องหรอก เอาไปให้หมดเลย ข้ายืนยัน" },
        progress = { "37:14733:12009506", "ลูกน้อง? ทำไมเจ้าถึงเอานี่มาให้ข้า..." },
        required = { [268805] = { "21:1196979577:1642735024", "เสื้อชุ่มเหงื่อของ Tazzik" } },
        steps = { { "21:1196979577:1642735024", "เสื้อชุ่มเหงื่อของ Tazzik" } },
    },
    [95792] = { -- Clear 'em Out
        title = { "13:1064725552:244563374", "กวาดถ้ำให้โล่ง" },
        objective = { "5:409775429:850574908 W1 24:554910410:486272787 W2 46:85189988:1795177938", "กำจัด Cinderscale Whelp {world1} ตัวและ Cinderscale Warrior {world2} ตัวให้ Gelinda Coppergleam" },
        description = { "450:1696289292:1013951750", "ถ้าอยากได้กำไรก้อนโต ก็ต้องไปในที่ที่คนอื่นไม่กล้าไป! ถ้ำข้างหลังข้ามีแร่ที่ยังไม่มีใครแตะอยู่เพียบ ถ้าเอาคนงานเข้าไปได้ ข้าพูดถึงเงินก้อนใหญ่มากเลยนะ\n\nมีแค่ปัญหามังกร... นิดเดียว... ไม่มีอะไรจริง ๆ\n\nถ้ายอมเข้าไปจัดการมังกรให้ข้า จะมีรางวัลงาม ๆ ให้ แถมว่าที่เจ้าของกิจการเหมืองรายใหญ่จะจดจำความดีของเจ้าไว้ด้วย!" },
        completion = { "94:2145694322:1337980419", "ฝีมือยอดเยี่ยมเลย นักรบ พอกิจการเหมืองเล็ก ๆ ของข้าเริ่มทำกำไร ข้าสัญญาว่าจะแบ่งให้เจ้าด้วย!" },
        objectiveLabels = {
            monster = { ["Cinderscale Whelp slain"] = "ปราบ ลูกมังกร Cinderscale", ["Cinderscale Warrior slain"] = "ปราบ นักรบ Cinderscale" },
        },
    },
    [95934] = { -- Proof of Profit
        title = { "15:465527286:1490096168", "หลักฐานว่าขุดแล้วได้กำไร" },
        objective = { "55:27439021:672115920", "หา Cubic Draconia สักชิ้นให้ Gelinda Coppergleam" },
        description = { "491:588689630:1239558496", "เครื่องมือสำรวจของข้าชี้ว่าถ้ำพวกนี้มีแร่ที่ไม่เคยมีใครพบ ข้าเรียกมันว่า Cubic Draconia คงมีค่ามหาศาล\n\nน่าตื่นเต้นก็จริง แต่ไม่มีใครมาช่วยขุดถ้าข้าพิสูจน์ไม่ได้ว่ามันมีอยู่ ข้ามีค่าที่อ่านจากเครื่องมือก็จริง แต่คนอยากถือผลึกใหญ่ ๆ แวววาวในมือมากกว่าดูกราฟ\n\nข้ามั่นใจว่ามีผลึกโผล่จากดินในนั้นอยู่บ้าง ถ้ายอมหลบมังกรเข้าไปเอามาสักชิ้น จะช่วยข้าได้มากเลย" },
        progress = { "179:132979644:1880335865", "พูดตรง ๆ นะ ข้าไม่แน่ใจว่าจะใช้มือเปล่าดึง Cubic Draconia ออกจากดินได้หรือเปล่า ถ้าหามาลำบากก็กลับมาหาข้า เดี๋ยวข้าให้ยืมไดนาไมต์" },
        completion = { "131:1854890408:2025365095", "โอ้โฮ! แบบนี้คนต้องหันมามองแน่! ขุดของดีมาได้เยี่ยมเลย ถ้าเจ้าสนใจล่ะก็ ทีมขุดเหมืองของเรามีที่ให้เจ้าเสมอ" },
        required = { [271611] = { "14:1774568601:1049305146", "ผลึก Cubic Draconia" } },
        steps = { { "14:1774568601:1049305146", "ผลึก Cubic Draconia" } },
    },
    [96063] = { -- Gaseous Gold
        title = { "12:763962318:647383647", "แก๊สทำเงิน" },
        objective = { "48:1729049921:1520566167", "รวบรวม Marsh Gas Vial 5 ขวดให้ Sleebo Fizzlespout" },
        description = { "437:478384458:1039426058", "ถ่านหินกับน้ำมันหลบไป เชื้อเพลิงแห่งอนาคตคือแก๊ส เจ้าหนู! บึงทางตะวันตกเฉียงใต้พ่นออกมาเป็นตัน ๆ และข้าก็มีสิ่งประดิษฐ์ที่เหมาะจะใช้มันพอดี เป็นเครื่องยนต์ชนิดใหม่ที่ใช้แก๊ส แค่เก็บแก๊สนี่ลำบากชะมัด\n\nถ้าอยากช่วยสร้างอนาคตของวิทยาศาสตร์และอุตสาหกรรมสักนิด ไปเก็บแก๊สให้ข้าหน่อยสิ จะเห็นมันพุ่งขึ้นจากช่องระบายใกล้น้ำ" },
        progress = { "139:874578745:985266575", "หวังว่าเจ้าจะไม่ถือสาถ้าข้าบอกเรื่องสิ่งประดิษฐ์ของข้าแค่เท่าที่เจ้าจำเป็นต้องรู้ ความลับทางการค้าก็ต้องเก็บไว้ จริงไหม?" },
        completion = { "74:1140980125:1838649902", "เยี่ยม! ของพวกนี้ใช้ได้ดีเลย เอาล่ะ เจ้าจะช่วยข้าอีกสักเรื่องได้ไหม?" },
        required = { [272004] = { "14:473394404:2034844695", "ขวดบรรจุก๊าซจากบึง" } },
        steps = { { "14:473394404:2034844695", "ขวดบรรจุก๊าซจากบึง" } },
    },
    [96067] = { -- Rock 'em and Sock 'em
        title = { "21:212705551:2024198782", "ประลองกับหุ่นกล" },
        objective = { "30:623351316:1151161095", "ช่วย Sleebo ทดสอบสิ่งประดิษฐ์ของเขา" },
        description = { "369:2024239808:264268588", "เจ้าอาจสังเกตเห็นสหายจักรกลของข้า G45-B4G ข้างในอกที่หุ้มกระสอบของมันมีเครื่องยนต์แก๊สต้นแบบของข้าหมุนหึ่ง ๆ เป็นตัวเดียวที่ใช้งานได้จริง\n\nข้าว่าถึงเวลาทดสอบว่ามันทนแค่ไหน สนใจประลองกับมันไหม? ข้าใช้แก๊สที่เจ้าเก็บมาเติมพลังให้มันได้\n\nอ้อ ไม่ต้องห่วงว่าจะทำมันเจ็บ มันไม่รู้สึกอะไรหรอก!" },
        completion = { "279:1689808245:691424706", "โห เจ้าสองคนซัดกันเอาจริงเลยนี่! หาการประลองที่มันกว่านี้ไม่ได้แล้ว แถมข้ายังได้จดอะไรดี ๆ ไว้เพียบ\n\nเดี๋ยวข้าซ่อมเจ้า G45 แล้วปรับเครื่องยนต์สักหน่อย อีกไม่นานมันก็พร้อมลุยต่อ\n\nทดสอบ ปรับแต่ง ทดสอบ ปรับแต่ง ชีวิตนักประดิษฐ์ผู้ยิ่งใหญ่ก็แบบนี้แหละ" },
        objectiveLabels = {
            event = { ["Fight G45-B4G in a stress test of Sleebo's engine."] = "สู้กับ G45-B4G เพื่อทดสอบว่าเครื่องยนต์ของ Sleebo รับภาระหนักได้แค่ไหน" },
        },
    },
    [93786] = { -- A Message in Blood
        title = { "18:898040486:1729211749", "สารที่เขียนด้วยเลือด" },
        objective = { "5:1000000866:1065647852 W1 76:1978585057:520462890", "สังหาร Meadowsbrook Farmhand {world1} คน แล้วกลับไปรายงานผลกับ Krom'rosh" },
        description = { "40:400619764:1032690809 N 451:1186375040:129442614", "คมดาบเจ้ากระหายเลือดมนุษย์หรือยัง {name}?\n\nหลายปีก่อน มนุษย์ที่แปรพักตร์มายึดฟาร์มเล็ก ๆ ทางตะวันตกเฉียงใต้ข้ามแม่น้ำไป แถบนั้นมีไม้กับหินอุดมสมบูรณ์ ไม่ช้าพวกมันก็ขยายอาณาเขตไปถึงป้อมริมฝั่งตะวันออกที่เรียกว่า Farholde\n\nการปะทะช่วงแรกคงจบลงด้วยชัยชนะของเรา ถ้าเรามีคนพอ ถึงเวลาเตือนให้พวกมันจำได้ว่าเรายังอยู่\n\nทำให้ฟาร์มมันทำงานต่อไม่ได้ อย่าจับเชลย ส่งสารให้พวกมันเข้าใจชัด ๆ" },
        completion = { "39:1387248583:1428047445", "หึ ข้าได้กลิ่นเลือดพวกมันติดตัวเจ้ามา" },
        objectiveLabels = {
            monster = { ["Meadowsbrook Farmhand slain"] = "ปราบคนงานไร่ Meadowsbrook" },
        },
    },
    [93787] = { -- Food for the Taking
        title = { "19:1475475576:2122870740", "เสบียงที่ต้องชิงมา" },
        objective = { "6:2056026185:230538954 W1 79:1989293683:1297890141", "ขโมย Feed Satchel {world1} ถุงจากฟาร์ม Alliance ใน Meadowsbrook แล้วกลับไปหา Krom'rosh" },
        description = { "350:1494878341:1214349117", "มนุษย์ในดินแดนนี้เสวยสุขกับความอบอุ่น ความสบาย และอาหารที่หาได้จากแผ่นดินมานาน ถึงเวลาพรากความสุขเหล่านั้นไปเสียที\n\nไปหาเสบียงของศัตรูที่ฟาร์มทางตะวันตกเฉียงใต้ เจออะไรก็เอามาให้หมด\n\nงานนี้อาจไม่สะใจเท่าให้ดาบอาบเลือด แต่ถ้าพวกมันช้าลง เราก็มีเวลาวางแผนก้าวต่อไป" },
        completion = { "202:936882118:1663396514", "กลิ่นดินกับรากไม้เลยใช่ไหม? กลิ่นไม่ค่อยดี แต่เราต้องทำทุกอย่างเพื่อเอาชีวิตรอด\nโยนลงหม้อเดือดพร้อมปลากับหญ้าป่า แล้วความหิวจะหนีไปเหมือนพวกมนุษย์ขี้ขลาด" },
        progress = { "27:1446386131:620644173", "กลับมาพร้อมเสบียงของเราหรือยัง?" },
        required = { [262640] = { "12:1372109511:196373119", "ถุงอาหารสัตว์" } },
        steps = { { "12:1372109511:196373119", "ถุงอาหารสัตว์" } },
    },
    [93788] = { -- Borrowed Blades
        title = { "15:1510026184:1722478038", "ขอยืมคมขวาน" },
        objective = { "9:1866698604:257786470 W1 95:261683105:405640263", "เอา Woodworker's Axe {world1} เล่มจากคนตัดไม้ที่ Turner's Logging Camp ไปให้ Kreza Darkthorn ใน Rog'mar" },
        description = { "496:696367734:2089877916", "พอมีมนุษย์ทางใต้และพวกทไวไลต์ทางตะวันตก การแย่งชิงทรัพยากรก็ยิ่งลำบาก แต่จะไปหาแร่ท่ามกลางศัตรูทำไม ในเมื่อเอาคมขวานของพวกมันมาใช้ได้เลย?\n\nลงใต้ตามแม่น้ำไปถึงโรงเลื่อย เมื่อได้ยินเสียงคนตัดไม้ผิวปากอยู่ในป่า ให้ย่องเข้าไป พอมีจังหวะก็จู่โจมให้แรงและไว\n\nข้าจะอยู่เฝ้าให้เตาหลอมร้อนต่อ Gur'dok จะแยกเหล็กจากคมขวาน แล้วข้าจะตีอาวุธจากวัสดุของศัตรูเอง" },
        completion = { "163:488724581:1706164352", "เลือดบนคมดาบพวกนี้ยังสดอยู่เลย ใช้ได้นี่\nเจ้าว่าอีกนานแค่ไหนพวกมนุษย์ถึงจะรู้ว่าเราเอาอาวุธของพวกมันกลับมาเล่นงานพวกมันเอง?" },
        progress = { "37:1910793618:663561048", "เจ้าเอาของที่เราคุยกันไว้มาได้หรือยัง?" },
        required = { [263972] = { "16:803981291:953542604", "ขวานของช่างไม้" } },
        steps = { { "16:803981291:953542604", "ขวานของช่างไม้" } },
    },
    [94480] = { -- A Gift From Our Enemies
        title = { "23:1844319648:1263317837", "ของฝากจากศัตรู" },
        objective = { "43:884816982:1205142021", "นำ Stolen Feed ไปให้ Gorg ที่ Rog'mar" },
        description = { "379:583161679:143590346", "มนุษย์แถบนี้เป็นเพียงภัยอย่างหนึ่ง พวกทไวไลต์ก็รุกเข้ามา เสียงคำรามของนอลล์ก็ดังจากเนินใกล้ ๆ เราอาจต้องรบได้ทุกเมื่อ ถ้าคนของเรามีกำลังพอ Rog'mar ก็มีโอกาสอยู่รอด หากอ่อนแรงเราอาจถูกขับไล่ออกไป\n\nเอาของที่เจ้ารวบรวมมาไปให้ Gorg เขาจะจัดให้พวกเรามีกินทั่วถึง" },
        completion = { "98:911990099:677503121 N 46:1148516161:118207523", "กลิ่นฉุน กลิ่นดิน แล้วก็กลิ่นอะไรเหม็น ๆ อีกนิด ดูท่าเจ้าคงไปกวาดของมาจากไร่นั่นสินะ {name}\nอีกเดี๋ยวเราก็ได้สตูหม้อใหญ่กินกันแล้ว" },
    },
    [94481] = { -- A Serving of Strength
        title = { "21:1448052204:956809614", "สตูว์เพิ่มแรง" },
        objective = { "5:3897123:1516445393 W1 42:697316160:632341164", "ให้อาหาร Rog'mar Trainee {world1} คนที่ลานฝึก" },
        description = { "278:1663381129:1788820439", "สตูว์เข้มข้นหม้อนี้เลี้ยงพวกทหารฝึกหัดให้อิ่ม มีกำลังพอข่มศัตรูให้อยู่ห่าง ๆ\n\nเอาไปเลี้ยงทหารฝึกหัดทางตะวันตก อย่าไปฟังพวกมันบ่น ช่วงนี้คุ้มกันเส้นทางส่งเสบียงลำบากจะตาย มีสตูว์กินแทนดินก็บุญแล้ว" },
        completion = { "156:1148667757:1627572030", "ถ้ายังมีใครบ่นอีก ก็ให้มาพูดกับข้าโดยตรง\nข้าขอบใจที่เจ้าไปหาอาหารพวกนี้มาให้ พวกนักรบของเราก็ซาบซึ้งเหมือนกัน ถึงปากจะพูดอีกอย่างก็เถอะ" },
        steps = { { "19:248701083:126469626", "ให้อาหารผู้ฝึกหัด Rog'mar" } },
    },
    [94483] = { -- Show Them How It's Done
        title = { "23:2123091831:658118765", "ทำให้พวกมันดู" },
        objective = { "5:1000000866:1065647852 W1 22:876212365:2023446618 W2 36:1128624464:1915611895", "สังหาร Farholde Priest {world1} คนและ Farholde Scout {world2} คนทางใต้ของแม่น้ำ" },
        description = { "219:1817829882:337762390 N 126:1238756547:219751804", "หน่วยสอดแนมรายงานว่ามีค่ายฝึกริมแม่น้ำทางใต้ ถ้าข้าได้ข่าวเร็วกว่านี้ เราทั้งคู่คงไม่ต้องวุ่นตามหาและกำจัดพวกมนุษย์โสมมให้ทันเวลา\n\nทำงานต่อไป {name} ถ้ากดมนุษย์ให้ถอยกลับไปอยู่แต่ในป้อมเล็ก ๆ ที่มันรักนักหนาได้ เราจะมีเวลาจัดการเรื่องอื่นที่ค้างอยู่\n\nรีบลงมือเสีย" },
        completion = { "54:422738027:5353268", "ทำได้รวดเร็วดี ไปทำงานที่อื่นต่อกันเลย จะได้ไม่เสียจังหวะ" },
        objectiveLabels = {
            monster = { ["Farholde Priest slain"] = "ปราบนักบวช Farholde", ["Farholde Scout slain"] = "ปราบหน่วยสอดแนม Farholde" },
        },
    },
    [94532] = { -- Gnoll Infestation
        title = { "17:1326934258:674836375", "ฝูงนอลล์ยึดเนินเขา" },
        objective = { "5:409775429:850574908 W1 19:693867940:1775384519 W2 24:1170222029:17687185 W3 48:962429147:1325548297", "กำจัด Redridge Mystic {world1} ตัว, Redridge Trapper {world2} ตัว และ Redridge Brute {world3} ตัวให้ Neza Bloodsnout ที่ Rog'mar" },
        description = { "240:203285327:1696451259", "ถึงพวกนอลล์จะเหลือน้อยลงตั้งแต่ทไวไลต์รุกเข้ามา ภัยจากพวกมันก็ยังอยู่\n\nเนินทางตะวันตกเฉียงใต้มีนอลล์เต็มไปหมด ก่อกวนทั้งการค้าและคนเดินทาง\n\nกำจัดพวกมันเสีย จะได้เปิดทางให้พันธมิตรเรา" },
        completion = { "55:795830350:2059350026", "กลิ่นพวกโนลล์ล้างออกยากนัก" },
        objectiveLabels = {
            monster = { ["Redridge Mystic slain"] = "ปราบ นักเวทลี้ลับ Redridge", ["Redridge Trapper slain"] = "ปราบ นายพรานวางกับดัก Redridge", ["Redridge Brute slain"] = "ปราบ อันธพาล Redridge" },
        },
    },
    [94533] = { -- Snargl's Snout
        title = { "14:52808542:164029571", "จมูกของสนาร์เกิล" },
        objective = { "89:431403353:192876648", "ตามหา Snargl ใน Bristle Hills ฆ่ามัน แล้วนำจมูกไปให้ Neza Bloodsnout" },
        description = { "416:1036893868:420895910 N 1:46:46", "ในหมู่พวกตัวหัวเราะแหลมใน Bristle Hills ทางตะวันตกเฉียงใต้ มีนอลล์แก่ชื่อ Snargl เสียงของมันน่ารำคาญเหลือทน แค่มันอยู่ใกล้ ๆ ตัวอื่นก็ฮึกเหิม ทำให้พันธมิตรกับหน่วยสอดแนมที่เข้าไปเจอเรื่องลำบาก\n\nข้าอยากได้ของที่ระลึกจากวันที่เราจัดการเจ้าตัวน่ารังเกียจนี่ได้ คงเหมาะจะเอามาเข้าชุดของสะสมข้า\n\nรีบไปเถอะ {name}" },
        completion = { "58:190901945:1888242615", "หนักกว่าที่ข้าคิดแฮะ แต่เอาไปเพิ่มในของสะสมได้อย่างดีทีเดียว" },
        progress = { "24:78960210:329116140", "หาเจ้าของสะสมชิ้นใหม่ให้ข้าได้หรือยัง?" },
        required = { [265357] = { "14:52808542:164029571", "จมูกของ Snargl" } },
        objectiveLabels = {
            item = { ["Snargl's Snout"] = "จมูกของ Snargl" },
        },
    },
    [94535] = { -- Bristle Hills Bandits
        title = { "21:888271684:1483507277", "โจรแห่งบริสเซิลฮิลส์" },
        objective = { "7:451016854:1830523975 W1 65:232388359:413162667", "เก็บ Stolen Ore {world1} ก้อนจากนอลล์ใน Bristle Hills ให้ Kreza Darkthorn" },
        description = { "202:1954951201:1297188642", "พันธมิตรที่ขุดแร่อยู่ตามเนินทางใต้รายงานว่าถูกพวกนอลล์แถวนั้นโจมตีหลายครั้ง\n\nไปทางใต้ ตามหาค่ายของพวกมัน แล้วเอาแร่ที่ขโมยไปคืนมา ถ้าต้องค้นจากศพมันก็ทำเสีย" },
        completion = { "18:366880880:1038443585 N 83:1456275729:175425742", "ทำได้ดี {name} ความร้อนจากเปลวไฟของเราจะเผารอยกับกลิ่นที่ยังเหลืออยู่ให้หมด" },
        progress = { "32:131732403:929752836", "เจ้าเจอแร่ที่ถูกขโมยไปหรือยัง?" },
        required = { [265358] = { "10:2138169358:1339452063", "แร่ที่ถูกขโมย" } },
        steps = { { "10:2138169358:1339452063", "แร่ที่ถูกขโมย" } },
    },
    [94672] = { -- Encroaching Twilight
        title = { "20:271345611:1232130196", "ทไวไลต์รุกคืบ" },
        objective = { "7:1265997621:1189804897 W1 22:1186470082:1403818367 W2 62:1670680142:1961636217", "กำจัด Twilight Raider {world1} คนและ Twilight Neophyte {world2} คนใน Sunnyglade ให้ Tran'gul ที่ Rog'mar" },
        description = { "58:663137798:998453960 N 418:1835213261:1530192434", "ใน Riverglades เรามีศัตรูอีกนอกจากมนุษย์ {name} และภัยที่ร้ายที่สุดก็มาจากฝ่ายอื่น\n\nลัทธิที่เรียกตัวเองว่า Twilight's Hammer เริ่มไล่โจมตีคนที่พวกมันมองว่านอกรีตในสายตาเทพวิปริตของมัน ซากชุมชนมนุษย์ทางตะวันตกเป็นเพียงแห่งแรกที่ถูกทำลาย ไม่ต้องสงสัยเลยว่า Rog'mar จะเป็นรายต่อไป\n\nเราปล่อยให้พวกมันตั้งหลักใกล้บ้านขนาดนี้ไม่ได้ ไปที่ที่เรียกว่า Sunnyglade แล้วลดจำนวนพวกมันเสีย" },
        completion = { "16:1549935302:71513149 N 105:897579436:1088521499", "ยอดเยี่ยม {name} พอพวกมันเหลือน้อยลง เราก็ไปสืบได้แล้วว่าอะไรทำให้ Twilight's Hammer ขยายอิทธิพลได้มากอย่างที่ไม่เคยเป็นมาก่อน" },
        objectiveLabels = {
            monster = { ["Twilight Raider slain"] = "ปราบ ผู้จู่โจม Twilight", ["Twilight Neophyte slain"] = "ปราบ สาวกใหม่ Twilight" },
        },
    },
    [94680] = { -- Twilight Missives
        title = { "17:1457240839:680020056", "สารลับของทไวไลต์" },
        objective = { "9:1866698604:257786470 W1 85:80926819:1848621210", "เอา Twilight Missive {world1} ฉบับจาก Twilight Shadowmancer ใน Sunnyglade ไปให้ Tran'gul ที่ Rog'mar" },
        description = { "483:98632657:267851396", "สาวกลัทธิ Twilight's Hammer เคยรวมตัวกันเป็นกลุ่มเล็ก ๆ กระจัดกระจาย แต่ข้าไม่เคยเห็นมันมากขนาดนี้ ดูเหมือนมีใครหรืออะไรบางอย่างหนุนให้มันกล้าขยายอิทธิพล\n\nข้าอยากรู้จักพวกลัทธินี้และสิ่งที่มันตามหาให้มากขึ้น จอมเวทเงาของมันได้รับพรจากพลังมืด น่าจะเป็นคนที่ลัทธิไว้ใจที่สุดให้คุมการโจมตีขนาดนี้\n\nเจออะไรบนศพพวกมันก็เอามาให้ข้า เผื่อจะได้เบาะแสเรื่องแผนการของมัน" },
        completion = { "40:700775307:223142899 N 158:1999428143:392435412", "จดหมายพวกนี้มีข่าวชวนให้กังวล {name} พวกนี้ไม่ใช่กองกำลังที่พลัดหลงมาแล้วไล่กัดเราไปเรื่อยเหมือนสัตว์คลั่ง Twilight's Hammer มาที่นี่ด้วยเหตุผลบางอย่าง พวกมันกำลังตามหาอะไรอยู่" },
        progress = { "108:744226510:844610760", "สังหาร Twilight Shadowmancer แล้วค้นศพพวกมัน ถ้าโชคดี เราจะได้ข้อมูลที่กำลังตามหา" },
        required = { [265745] = { "16:1593304022:906806256", "สารจากกลุ่ม Twilight" } },
        steps = { { "16:1593304022:906806256", "สารจากกลุ่ม Twilight" } },
    },
    [94727] = { -- Digging for Answers
        title = { "19:907440811:664139302", "ขุดหาคำตอบ" },
        objective = { "74:646866890:855109495", "เกลี้ยกล่อมคนงานเหมืองของ Twilight's Hammer ใน Sunnyglade ให้ยอมเปิดเผยความลับ" },
        description = { "59:757490037:947494630 N 437:1079558243:220734515", "กลุ่ม Twilight's Hammer มาที่นี่ด้วยเหตุผลมากกว่าการก่อความวุ่นวาย {name} ดูเหมือนพวกมันกำลังขุดหาอะไรสักอย่างทั่ว Riverglades ข้าบอกไม่ได้ว่าหาอะไร คงเป็นแหล่งพลังแน่ แต่เป็นอะไรนั้นข้ายังคิดไม่ออก\n\nสาวกคลั่งของมันอาจไม่ยอมบอกความลับ แต่พวกมันต้องมีคนขุดให้ ไปสอบถามคนพวกนั้น กลับไป Sunnyglade แล้ว ‘เกลี้ยกล่อม’ คนงานเหมืองสักคนให้ยอมพูด เราต้องสืบให้ถึงต้นตอ" },
        completion = { "39:324690933:705697969", "โอ๊ย! โอ๊ย! อย่าตีอีก! อยากได้อะไร?" },
        progress = { "52:188578409:755167155", "อยากได้อะไร? เขาบอกข้าว่าห้ามคุยกับคนแปลกหน้า" },
        steps = { { "24:555983789:1562295107", "เกลี้ยกล่อมคนงานเหมืองของ Twilight" } },
    },
    [95033] = { -- On the Other Side
        title = { "17:1492999284:992105254", "อีกฟากของทุ่ง" },
        objective = { "80:425699380:536942477", "ไปคุยกับ Witch Doctor Uzer'i ที่ Camp Mojache ใน Feralas ตามที่ Tan'jani ขอ" },
        description = { "308:1060539937:1998884480", "ถ้าเจ้าเริ่มเบื่อทุ่งโล่งพวกนี้ สหายเก่า Uzer'i ของข้าหาคนช่วยอยู่ตลอด เขาชอบเล่นเวทพิสดาร แต่คนส่วนมากไม่รู้ว่าเขาล่าสัตว์เก่งเอาเรื่องด้วย\n\nถ้าสนใจ ก็ไปหาเขาที่ Camp Mojache ไกลถึง Feralas\n\nบอกเขาว่า Tan'jani คนเก่าส่งเจ้ามา" },
        completion = { "80:560032836:1872459216", "ฮึ ตา Tan'jani ส่งเจ้ามาเหรอ? ดีแล้วล่ะ\nพวกเราต้องการคนมาช่วยอยู่พอดี" },
    },
    [95062] = { -- Frazzlespark's Crate
        title = { "20:1431114411:1506537522", "ลังของแฟรซเซิลสปาร์ก" },
        objective = { "53:631484603:157494640", "นำ Frazzlespark's Crate ไปให้ Krom'rosh ที่ Rog'mar" },
        description = { "211:1988115714:1077544135", "ถึงเวลาส่งของพิเศษแล้ว\n\nKrom'rosh รอหีบนี้อยู่ที่ Rog'mar ทางตะวันตกไม่ไกล\n\nข้าว่ารีบส่งให้เขาเถอะ แต่ระวังหน่อยล่ะ ถ้าอยากรู้ว่าทำไม... เรื่องนี้อย่าถามจะดีกว่า" },
        completion = { "117:1761286018:967259085", "เราสานสัมพันธ์กับหลายฝ่ายเพราะนับถือกัน ส่วนกับบางฝ่ายก็เพราะจำเป็น\n\nการติดต่อกับคนเหล่านี้ช่วยให้เราบรรลุเป้าหมาย" },
    },
    [95162] = { -- Paletusk Harvesting
        title = { "19:832031724:946857481", "เก็บเนื้อหมูพาลทัสก์" },
        objective = { "7:451016854:1830523975 W1 47:2075863333:516923107", "รวบรวม Chunk of Boar Meat {world1} ชิ้นให้ Na'zok ใกล้ Bolder'ok" },
        description = { "504:1778708820:1939775593", "ที่ดินที่มนุษย์หรือ Twilight's Hammer ยังไม่ยึดเหลือน้อยมาก ฟาร์มนี้เลยเป็นหนึ่งในแหล่งอาหารไม่กี่แห่งของเรา พวกโอเกอร์ทำไร่ไม่เก่ง แต่ชอบหมูพาลทัสก์ย่างมาก พวกมันยอมให้ข้าอยู่ตราบใดที่ยังมีเนื้อส่งให้\n\nยิ่งรบไป ความต้องการอาหารก็ยิ่งเพิ่ม ตอนนี้ข้าแทบมีอาหารไม่พอให้โอเกอร์เลิกมองข้าเป็นมื้อต่อไปของพวกมัน\n\nถ้าอยากให้ Rog'mar มีเนื้อพอ ข้าต้องให้เจ้าช่วยหาเนื้อแล้วล่ะ" },
        completion = { "94:263987331:1275517970", "ไม่เลวนี่ น่าจะพอให้พวกโอกร์พอใจ แถมเหลือให้ Rog'mar อีกเยอะ" },
        progress = { "98:1115633359:1648540404 C 34:1564639485:625730268", "ไม่ต้องไปยุ่งกับตัวเล็ก ๆ พวกมันยังมีเนื้อไม่พอให้โอกร์กินอิ่ม\nรีบหน่อย {class} พวกนั้นเริ่มดูหิวแล้ว" },
        required = { [769] = { "18:403259379:436492272", "เนื้อหมูป่าชิ้นหนึ่ง" } },
        steps = { { "18:403259379:436492272", "เนื้อหมูป่าชิ้นหนึ่ง" } },
    },
    [95163] = { -- Drive Them Back
        title = { "15:792947737:1839340181", "ต้อนกลับเข้าคอก" },
        objective = { "7:754587951:547508582 W1 49:1151670573:236812082", "ต้อน Young Paletusk {world1} ตัวกลับไปที่ฟาร์มของ Na'zok ใกล้ Bolder'ok" },
        description = { "406:1091074102:6303732", "อย่างที่เห็น หมูวิ่งกระจายเต็มหุบเขา มากกว่าที่อยู่ในคอกเสียอีก Gorgegut ช่วยงานฟาร์มได้ไม่ดีนัก แต่ก็กันมนุษย์ไว้ได้\n\nตัวเล็กบางตัวหนีข้ามแม่น้ำไป มันยังเล็กเกินกว่าจะเชือดเอาเนื้อกลางทุ่ง ต้องต้อนกลับมาที่นี่ เอาไม้นี้ไปฟาดมันสักที พวกมันน่าจะวิ่งปรู๊ดกลับเข้าคอก!" },
        completion = { "155:1034822787:374780311", "นั่นคงเป็นตัวสุดท้ายแล้ว ข้าต้องซ่อมประตูรั้ว แต่เตะก้นสักทีคงสอนลูกหมูพวกนั้นให้เลิกวิ่งหนีได้" },
        progress = { "71:625675462:1380040532", "ถ้าพวกมันงับเอาบ้างก็อย่าถือสา หมูของข้ามีจิตวิญญาณนักรบนะ!" },
        required = { [268521] = { "17:1664398921:290917000", "ไม้เท้าคนเลี้ยงหมู" } },
        steps = { { "23:2086445367:809208849", "พา Young Paletusk กลับไป" }, { "17:1664398921:290917000", "ไม้เท้าคนเลี้ยงหมู" } },
    },
    [95417] = { -- The Purple Ones
        title = { "15:735436169:1101317291", "พวกตัวม่วง" },
        objective = { "63:187723103:141320077", "ตามหาโอเกอร์ที่หายไปในถ้ำใต้ Sunnyglade ให้ Clubtoe" },
        description = { "264:1280088652:1643424653", "Clubtoe เห็นเพื่อนไป บางตัวไม่กลับ บางตัวกลับมาเป็นสีม่วง แปลก พวกตัวม่วงไม่ทำตัวเหมือนเพื่อนแล้ว\n\nตัวอื่นไปไหน? ทำไมไม่กลับ? Clubtoe คิดอยู่\n\nเจ้าตีแรง บางทีเจ้าไปหาเพื่อนในถ้ำได้ บางทีเจ้าก็กลายเป็นสีม่วง แปลกอีกเหมือนกัน" },
        completion = { "140:811731475:1230867467", "<โอกร์นอนตายอยู่ท่ามกลางวงอักขระมืด ดูเหมือนจะทนพลังจากพิธีกรรมของ Twilight's Hammer ไม่ไหว>" },
    },
    [95427] = { -- Twilight No More!
        title = { "17:542015919:911866033", "พอกันที ทไวไลต์!" },
        objective = { "74:454430411:1492148843", "ฆ่า Chogg'Zac ในถ้ำ Sunnyglade แล้วนำหัวไปให้ Clubtoe" },
        description = { "183:1313565170:2127561944", "เพื่อน Clubtoe... ตาย? ทำไม?\n\nความผิด Chogg'Zac! พวกนั้นบอกจะทำให้โอเกอร์แข็งแรง! มันโกหก!!\n\nไม่ทุบหินแล้ว! เจ้าตัวจิ๋วช่วย Clubtoe ทุบหัวโง่ ๆ ของ Chogg'Zac แทน!" },
        completion = { "5:1017438831:1353626593 R 105:1350582606:1029250714", "{race} ตัวจิ๋วฆ่า Chogg'Zac ได้ไหม?\nClubtoe จะไม่ทุบหินให้พวกตัวจิ๋วอีกแล้ว! Clubtoe จะไม่ยอมเสียเพื่อนอีกแล้ว! ข้าเลิกเป็นพวก Twilight แล้ว!" },
        progress = { "42:1441518841:1491947474", "เลิกฆ่าเพื่อนข้าได้แล้ว! วันนี้ Chogg'Zac ต้องตาย!" },
        required = { [265750] = { "12:1719522912:904062116", "ศีรษะของ Chogg" }, [265751] = { "10:1070448462:1258694193", "ศีรษะของ Zac" } },
        steps = { { "12:1719522912:904062116", "ศีรษะของ Chogg" }, { "10:1070448462:1258694193", "ศีรษะของ Zac" } },
    },
    [95601] = { -- The Purple Ones
        title = { "15:735436169:1101317291", "พวกตัวม่วง" },
        objective = { "5:409775429:850574908 W1 22:1176574107:511485164 W2 58:359143349:1970699367", "กำจัด Empowered Brute {world1} ตัวและ Twilight Ritualist {world2} คน แล้วกลับไปหา Clubtoe ใน Sunnyglade" },
        description = { "249:527714738:967810946", "<โอเกอร์ที่ตายตัวนี้คงเป็นเพื่อนคนหนึ่งที่ Clubtoe ตามหา ดูเหมือนกลุ่ม Twilight's Hammer กำลังทำพิธีกับสมาชิกของตัวเอง บางคนได้พลังเพิ่ม แต่คนที่ตายมีมากกว่า\n\nต้องหยุดพวกทำพิธีและสัตว์ประหลาดของมันก่อนที่จะแพร่ไปมากกว่านี้>" },
        completion = { "5:1017438831:1353626593 R 47:1412342664:247867999", "{race} ตัวจิ๋วไม่กลายเป็นสีม่วง! เย้!\nแต่... เพื่อนอยู่ไหน?" },
        objectiveLabels = {
            monster = { ["Empowered Brute slain"] = "ปราบ อันธพาลเสริมพลัง", ["Twilight Ritualist slain"] = "ปราบ ผู้ประกอบพิธี Twilight" },
        },
    },
    [95602] = { -- Sickening Lights
        title = { "16:519760687:1543071717", "แสงที่ทำให้คลื่นไส้" },
        objective = { "8:286779151:428491486 W1 74:568233923:729765377", "ทำลาย Twilight Ritual Circle {world1} วงที่อยู่ตามถ้ำใต้ Sunnyglade" },
        description = { "493:1364451924:1421264421", "ข้าเกลียดทุบหิน ทุบทั้งวัน Chogg'Zac สั่ง มันหัวหน้าใหญ่ มันบอกให้ทุบพวกตัวจิ๋ว แต่ตอนนี้เราทำงานให้พวกตัวจิ๋ว งี่เง่า\n\nทุบหินทำไม? ข้าไม่รู้ เจอแสงวิบวับในหิน Chogg'Zac คงชอบของวิบวับ เจ้ามาหาแสงด้วยหรือ? พวกอื่นไม่ชอบแน่ พวกมันชอบแสงมาก เอาไปวาดรูปด้วย\n\nClubtoe ไม่เข้าใจ แสงทำ Clubtoe คลื่นไส้ ข้าเกลียดแสง อยากทุบรูปวิบวับให้พัง! แต่ Chogg'Zac จะโกรธ ขยี้ Clubtoe แย่แน่ แต่ควรมีใครสักคนทำ" },
        completion = { "79:1951329795:1304359172", "Clubtoe รู้สึกดีขึ้นแล้ว! เจ้าทุบรูปวิบวับไปเยอะไหม? คนอื่นโกรธหรือเปล่า?" },
        steps = { { "32:1707645570:1289017473", "ทำลายวงพิธีของ Twilight" } },
    },
    [95882] = { -- WANTED: Scoutmaster Vargas
        title = { "26:550149024:1473808995", "ประกาศจับ หัวหน้าหน่วยสอดแนมวาร์กัส" },
        objective = { "58:1828618053:1600876352", "นำ Scoutmaster's Eye ไปให้ Neza Bloodsnout ที่ Rog'mar" },
        description = { "503:1536350385:1366599674", "มีคนเห็นหน่วยสอดแนม Alliance บนเกาะเล็ก ๆ ทางตะวันออกเฉียงเหนือของ Rog'mar หัวหน้าพวกมันทำให้เราตามความเคลื่อนไหวของศัตรูยากขึ้นทุกที ไอ้เวรนั่นถึงกับตั้งชื่อสัตว์เลี้ยงโสโครกตามชื่อข้าเพื่อเยาะเย้ยกันซึ่ง ๆ หน้า มันรู้ว่าข้าตามล่ามันอยู่\n\nมนุษย์คนนี้มีหูตาอยู่ทุกแห่ง ต้องควักตาให้หมด ข้าเอามาแล้วข้างหนึ่งก่อนมันหนีไปได้ เอาอีกข้างมาให้ข้าเป็นหลักฐานว่าหัวหน้าหน่วยนั่นตายแล้ว ให้มันรู้ว่าใครก็แตะต้องมันได้\n\n— Neza Bloodsnout" },
        completion = { "157:1730443881:93607665 N 72:1633824401:2097709696", "หัวหน้าหน่วยสอดแนมตายแล้วรึ? น่าเสียดายอยู่หน่อยที่เจ้าต้องฆ่าเขา เห็นอะไรมามากขนาดนั้น เขาสมควรต้องตาบอดเร่ร่อนอยู่ในโลกไปตลอดชีวิต\nทำได้ดี {name} ทีนี้พวก Horde ก็เดินทางผ่าน Riverglades ได้ปลอดภัยขึ้น" },
        progress = { "53:885112673:595592977", "เบาเสียงหน่อย พวกมนุษย์คอยจับตาดูอยู่ตลอด" },
        required = { [268581] = { "17:623525226:948549440", "ดวงตาของหัวหน้าหน่วยลาดตระเวน" } },
        steps = { { "17:623525226:948549440", "ดวงตาของหัวหน้าหน่วยลาดตระเวน" } },
    },
    [95951] = { -- Fetch 'n' Fletch
        title = { "16:1476145309:1556822213", "หาไม้มาเหลาเป็นหอก" },
        objective = { "91:2088802973:841702026 W1 27:1100354416:1807713280", "เก็บ Wood Bundle จาก Peasant Woodpile ใน Turner's Logging Camp แล้วเหลาเป็น Makeshift Stickin' Spear {world1} เล่ม" },
        description = { "491:2113701607:249273515", "ว่าไง นายท่าน อยากให้ Tan'jani คนเก่าช่วยไหม? ไม่ต้องห่วง ข้าจัดให้\n\nพวกออร์คเก่งเรื่องเอาขวานฟันมนุษย์ แต่ถ้าอยากเสียบพวกมันก่อนมันจะเห็นเจ้า ต้องเรียกพวกนักล่าหัว อยากหัดเสียบบ้างไหม? ข้าเห็นอยู่ในแววตาเจ้าแล้ว ฮิ ๆ\n\nก่อนอื่นต้องหาหอกให้เจ้า เล่มนี้ของข้า ไปค่ายมนุษย์ทางตะวันตกแล้วเอาไม้ของมันมา เอามีดไปด้วย เหลาไม้ให้แหลมเป็นหอกดี ๆ เอาไว้แทง แล้วเอากลับมา", variants = { { "492:501089855:634428625", "ว่าไง นายหญิง อยากให้ Tan'jani คนเก่าช่วยไหม? ไม่ต้องห่วง ข้าจัดให้\n\nพวกออร์คเก่งเรื่องเอาขวานฟันมนุษย์ แต่ถ้าอยากเสียบพวกมันก่อนมันจะเห็นเจ้า ต้องเรียกพวกนักล่าหัว อยากหัดเสียบบ้างไหม? ข้าเห็นอยู่ในแววตาเจ้าแล้ว ฮิ ๆ\n\nก่อนอื่นต้องหาหอกให้เจ้า เล่มนี้ของข้า ไปค่ายมนุษย์ทางตะวันตกแล้วเอาไม้ของมันมา เอามีดไปด้วย เหลาไม้ให้แหลมเป็นหอกดี ๆ เอาไว้แทง แล้วเอากลับมา" } } },
        completion = { "37:687622478:582863991", "ดี คมใช้ได้ ยิงไปต้องปักแน่น" },
        progress = { "13:1567689600:1774344283", "เจออะไรมาบ้างล่ะ?" },
        required = { [271630] = { "24:1395057288:671249806", "หอกแทงแบบทำขึ้นเอง" } },
        steps = { { "24:1395057288:671249806", "หอกแทงแบบทำขึ้นเอง" } },
    },
    [95992] = { -- WANTED: Ghostmaw
        title = { "16:322728212:1760539747", "ประกาศจับ โกสต์มอว์" },
        objective = { "45:1787579735:692251742", "นำ Ghostmaw's Fang ไปให้ Tan'jani ที่ Rog'mar" },
        description = { "393:2059042274:1637714633", "น่านน้ำแถวนี้อันตราย นักล่าหัวของข้าคอยดูทางให้โล่งเท่าที่ทำได้ แต่มีเจ้าสัตว์ตัวหนึ่งซุ่มตามแม่น้ำ ขนาดพวกข้ายังจับมันไม่ได้ ตื่นเต้นดีใช่ไหม?\n\nหัวหน้าสั่งให้จัดการ เราเลยเปิดแข่งกันเล็ก ๆ ตามหาตัวสีขาวที่ว่ายวนตามแม่น้ำแล้วเอาเขี้ยวมันมาให้ข้า ใครแทงครอโคลิสก์ลื่นปรื๊ดนี่ได้ก็เอาเงินกองกลางไปหมด ระวังอย่าให้มันงับเอาเองล่ะ ฮิ ๆ\n\n— Tan'jani" },
        completion = { "61:1045427911:1214247788", "Taz'dingo! ถ้าจับเจ้า Ghostmaw ได้ เจ้าก็เป็นนักล่าที่เก่งเอาเรื่องนะ" },
        progress = { "43:599939767:743912998", "หน้าตาเจ้าเหมือนเพิ่งเจอผีมาเลย พวก ฮี่ ๆ ๆ" },
        required = { [271828] = { "15:984250107:202631672", "เขี้ยวของ Ghostmaw" } },
        steps = { { "15:984250107:202631672", "เขี้ยวของ Ghostmaw" } },
    },
    [96103] = { -- A Feast for Buzzards
        title = { "20:222064025:1112488482", "มื้อใหญ่ของแร้ง" },
        objective = { "53:1943767481:857326132", "นำ Gnawed Skull ไปให้ Neza Bloodsnout ที่ Rog'mar" },
        description = { "399:1242430788:1452181647", "โครงกระดูกแหลกเสียหาย ตามแขนขามีรอยลึกคล้ายรอยเขี้ยวและกรงเล็บ แดดจัดที่แผดเผามาหลายวันทำให้กระดูกซีดขาวและเปราะ ทั้งสภาพอากาศและการโจมตีที่รุนแรงทำให้ระบุไม่ได้ว่าผู้ตายเป็นใคร\n\nเจ้าคงเอาโครงกระดูกไปทั้งร่างไม่ได้ แต่ลองนำกะโหลกไปให้พรานที่ Rog'mar ดู เผื่อเขาจะรู้อะไรบ้าง" },
        completion = { "191:1735991686:1744961971", "<Neza ลูบนิ้วไปตามรอยบนกะโหลก ยิ่งลูบ รอยยิ้มของนางก็ยิ่งกว้างขึ้น>\nมีข่าวดีสองเรื่อง หนึ่ง นี่คือกะโหลกมนุษย์ สอง พวกเรามีการล่าครั้งใหญ่รออยู่" },
        progress = { "36:449607710:1465383821", "เจ้าเอาอะไรมาจากที่ราบหรือ?" },
        required = { [271777] = { "12:81724327:1680425916", "กะโหลกที่มีรอยแทะ" } },
        steps = { { "12:81724327:1680425916", "กะโหลกที่มีรอยแทะ" } },
    },
    [96104] = { -- Song of the Strider
        title = { "19:675821598:940020754", "เสียงเรียกของทอลล์สไตรเดอร์" },
        objective = { "63:1804036490:326666748", "นำ Intact Tallstrider Beak ไปให้ Neza Bloodsnout ที่ Rog'mar" },
        description = { "453:463822095:229123998", "รอยพวกนี้มาจากสิงโต ดูแล้วตัวนี้ใหญ่เป็นพิเศษ มันคือจ่าฝูงแถวนี้\n\nข้าเองก็อยากล่ามัน แต่เจ้าได้สิทธิ์ก่อน ข้าจะช่วยเจ้าแทน\n\nข้าทำนกหวีดเลียนเสียงทอลล์สไตรเดอร์บาดเจ็บได้ เจ้าใช้ล่อสิงโตออกมาได้ ข้าขอแค่จะงอยปากสักอันเพื่อให้เสียงเหมือนจริง\n\nมีทอลล์สไตรเดอร์อยู่ทั่วทุ่ง หาเอาจะงอยปากมาให้ข้า แล้วเราจะเริ่มล่ากันได้!" },
        completion = { "11:1312632817:820592930 C 64:1590104534:1260915467", "เจอของดีนี่ {class} ขอเวลาข้าสักครู่เพื่อแกะให้ได้รูปที่ต้องการ" },
        progress = { "111:692107017:1755139202", "ข้าทำเครื่องเป่าและอุปกรณ์เลียนเสียงสัตว์มาตั้งแต่ยังเด็ก เป็นทักษะที่มีประโยชน์ตอนล่าเหยื่อบางชนิด" },
        required = { [271778] = { "23:1284813656:452081067", "จะงอยปาก Tallstrider สภาพสมบูรณ์" } },
        steps = { { "23:1284813656:452081067", "จะงอยปาก Tallstrider สภาพสมบูรณ์" } },
    },
    [96105] = { -- King of the Wild Plains
        title = { "23:1236935095:1508155163", "ราชาแห่งทุ่งป่า" },
        objective = { "137:1879675805:1147287694", "ใช้ Tallstrider Call ล่อจ่าฝูงสิงโตออกมา ฆ่ามันแล้วนำหนังไปให้ Neza Bloodsnout ที่ Rog'mar" },
        description = { "21:1281239005:1254563180 N 209:1130994555:513846051", "นกหวีดเสร็จแล้ว {name}\n\nเอาไปที่ยอดเนินทางใต้ที่ฝูงสิงโตอาศัยอยู่\n\nพอพร้อมเผชิญหน้ากับเหยื่อ ก็เป่านกหวีด เจ้าสัตว์ร้ายน่าจะโผล่มา\n\nขอให้โชคดีในการล่า และกลับมาพร้อมเกียรติยศ" },
        completion = { "58:2040145481:133170783 N 45:1417205421:1763184805", "เจ้าเป็นอย่างนั้นจริง ๆ! ทำได้ดี!\nที่ราบแห่งนี้อยู่ยากนัก {name} แต่เจ้าพิสูจน์แล้วว่าเจ้าแกร่งยิ่งกว่ามัน" },
        progress = { "35:1887924591:1539522049", "มาบอกข่าวชัยชนะของเจ้าหรือ?" },
        required = { [271779] = { "16:673113683:1968674037", "เครื่องส่งเสียงเรียก Tallstrider" }, [281052] = { "14:1303281669:643637710", "หนังของ Ombassa" } },
        objectiveLabels = {
            item = { ["Tallstrider Call"] = "เครื่องส่งเสียงเรียก Tallstrider", ["Ombassa's Hide"] = "หนังของ Ombassa" },
        },
    },
    [96107] = { -- Feathers for Fletching
        title = { "22:937694235:1609701255", "ขนนกสำหรับทำลูกธนู" },
        objective = { "6:1273960851:929420321 W1 55:1313727454:248192839", "นำ Plains Buzzard Feather {world1} เส้นไปให้ Neza Bloodsnout ที่ Rog'mar" },
        description = { "252:112301309:1958234816", "พรานคนหนึ่งใช้ลูกธนูตลอดชีวิตมากกว่าดาวบนฟ้าเสียอีก\n\nส่วนข้าทำลูกธนูด้วยมือตัวเอง ข้าเชื่อฝีมือตัวเองเท่านั้น\n\nขนหยาบของแร้งแถวนี้เหมาะใช้ติดท้ายลูกธนูมาก ช่วยเก็บมาให้ข้าสักหน่อยได้ไหม?" },
        completion = { "70:819173740:1354121559 C 1:46:46", "ขนพวกนี้รับลมได้ดี ลูกธนูของข้าจะพุ่งตรงเป้า ขอบใจเจ้า {class}" },
        progress = { "71:900532853:175749016", "ปกตินกพวกนี้ชอบคุ้ยซาก แต่คราวนี้เรากลับต้องไปถอนขนจากซากมันเอง น่าขันดีนะ?" },
        required = { [271793] = { "22:1269430646:1732721235", "ขนแร้งทุ่งราบ" } },
        steps = { { "22:1269430646:1732721235", "ขนแร้งทุ่งราบ" } },
    },
    [3366] = { -- The Glowing Shard
        title = { "17:1402979252:286913873", "เศษผลึกเรืองแสง" },
        objective = { "65:2124726702:1767747844", "เดินทางไป Ratchet เพื่อสืบหาที่มาของ Nightmare Shard" },
        description = { "317:725708986:1608979938", "เศษผลึกเป็นสีเขียวสดใส แม้จะแข็งเป็นเนื้อเดียวกัน แต่ใต้ผิวดูเหมือนมีควันหมุนวนอยู่ เจ้าละสายตาจากส่วนลึกของผลึกไม่ได้ ทั้งที่รู้ว่ามีบางอย่างชวนให้ไม่สบายใจ\n\nบางทีน่าจะลองถามคนใน Ratchet ดูว่ามีใครบอกอะไรเกี่ยวกับเศษผลึกประหลาดนี้ได้อีกบ้าง" },
        required = { [10441] = { "13:1665916638:331728573", "เศษผลึกเรืองแสง" } },
        steps = { { "13:1665916638:331728573", "เศษผลึกเรืองแสง" } },
        objectiveLabels = {
            event = { ["Speak with someone about the Nightmare Shard"] = "คุยกับใครสักคนเรื่อง Nightmare Shard" },
        },
    },
    [78916] = { -- The Heart of the Void
        title = { "21:49955182:501385525", "หัวใจแห่งวอยด์" },
        objective = { "64:647905630:1805454474", "นำ Blackfathom Pearl ไปให้ Dawnwatcher Selgorm ใน Darnassus" },
        description = { "154:824050412:707139875", "อสูรร้าย Aku'mai นอนตายอยู่ ท่ามกลางเครื่องในและเลือดของซากที่บวมอืด มีไข่มุกสีเหลือบขนาดมหึมาซ่อนอยู่ข้างใน เปี่ยมด้วยพลังวอยด์ดิบ" },
        progress = { "N 41:1459247294:1471249347", "{name} เจ้าได้ข่าวอะไรมาจาก Blackfathom บ้าง?" },
        completion = { "250:520963563:768730454 N 1:46:46", "Aku'mai บริวารของเทพโบราณ ตายแล้ว ผลงานเช่นนี้มีเพียงวีรบุรุษตัวจริงที่ทำได้\n\nวัตถุชิ้นนี้อาจเป็นกุญแจให้เราเข้าใจธรรมชาติของวอยด์และผลที่มันมีต่อโลกของเรามากขึ้น ต้องนำไปศึกษาทันที ขอบใจ {name}" },
        required = { [209693] = { "25:277794056:1993152954", "ไข่มุก Blackfathom ไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Perfect Blackfathom Pearl"] = "ไข่มุก Blackfathom ไร้ตำหนิ" },
        },
    },
    [93045] = { -- Test Your Theory
        title = { "16:1393192077:1286026385", "ทดสอบข้อสันนิษฐาน" },
        objective = { "171:2135772657:2009789068", "รักษาชื่อเสียงกับ Gelkis และสลายคำสาปเนโครแมนซีบน Accursed Skull เมื่อทำสำเร็จแล้วให้กลับไปรายงานกับ Nerlokh ใกล้ Valley of Bones" },
        description = { "486:132344837:676592225", "ข้าวางกะโหลกที่เจ้าให้ไว้ข้างกระดูกหลายชิ้นที่หาได้ระหว่างรอเจ้ากลับมา ทันใดนั้น แสงสีหม่นแผ่จากกะโหลกไปยึดกระดูกเก่าเหล่านั้น ข้าเข้าใจแล้วว่าทำไมถึงยากจะต้านแรงเย้ายวนของเนโครแมนซี เจ้าจำผลึกนี่ได้ไหม? มันคือ Draenethyst ข้ายังไม่รู้ว่ามันทำอะไรได้อีกบ้าง แต่เชื่อว่ามันนำพลังของ Theradras ได้ บางทีเจ้าอาจใช้มันสลายคำสาป ลานพิธีอยู่ข้างสระทางตะวันออกของหมู่บ้าน" },
        progress = { "N 79:186507699:1443098002", "{name}! เจ้ากลับมาจาก Gelkis Village แล้วหรือ? ข้าหวังว่า Uthek จะให้เบาะแสกับเจ้าได้บ้าง" },
        completion = { "193:267733777:1610195396 R 210:1636128497:2083738469", "ไม้เท้านั่นดูเหมือนของ Uthek แต่ข้าไม่รู้จักอัญมณีที่ประดับอยู่ เจ้าบอกว่ามันชื่อ Draenethyst หรือ?\n\n<Nerlokh ฟังเจ้าทบทวนเรื่องที่เพิ่งเกิดขึ้น และมองท่าทางประกอบอันแสนชัดเจนของเจ้าในฐานะ{race}>\n\nอาวุธต้านเนโครแมนซีคือสิ่งที่เราต้องการพอดี ถ้า Uthek ยอมฝากไม้เท้าใหญ่ของนางไว้กับเจ้า นางก็ต้องมั่นใจในแผนนี้มาก\n\nข้าเองก็มีข่าวจะบอกเช่นกัน" },
        steps = { { "25:1604124622:948275795", "คทาดราเอเนธิสต์ของ Uthek" }, { "25:1607277872:711745553", "สลายคำสาปบน Accursed Skull" } },
        objectiveLabels = {
            reputation = { ["Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ", ["Hated / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเกลียดชัง / ได้รับเกียรติ", ["Hostile / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นศัตรู / ได้รับเกียรติ", ["Unfriendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับไม่เป็นมิตร / ได้รับเกียรติ", ["Neutral / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นกลาง / ได้รับเกียรติ", ["Friendly / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นมิตร / ได้รับเกียรติ", ["Honored / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับเกียรติ / ได้รับเกียรติ", ["Revered / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับเป็นที่นับถือ / ได้รับเกียรติ", ["Exalted / Honored Gelkis Clan Centaur"] = "ชื่อเสียงกับ Gelkis Clan Centaur ระดับได้รับการยกย่องสูงสุด / ได้รับเกียรติ" },
        },
    },
    [908] = { -- Amongst the Ruins
        title = { "17:1291732365:972914668", "ท่ามกลางซากโบราณ" },
        objective = { "72:1265015579:159257333", "นำ Fathom Core ไปให้ Je'neu Sancrea ที่ Zoram'gar Outpost ใน Ashenvale" },
        description = { "214:1838576823:884497578 N 282:1155049014:1893905453", "กลุ่ม Twilight's Hammer ย้ายเข้ามาใน Moonshrine Ruins ของ Blackfathom Deeps พวกมันอยู่ที่นั่นก็มีแต่จะบีบให้เหล่าธาตุหันมาเล่นงานเรา ถ้าปล่อยไว้ ภูมิภาคนี้จะตกเป็นของพวกมันถาวร\n\n{name} เข้าไปใน Blackfathom แล้วหาศิลาน้ำลึกของซากวิหาร น่าจะอยู่ใต้น้ำแถว ๆ นั้น ข้างในมีแกน Fathom Core ซึ่งถ้าอ่านเป็นก็จะรู้ประวัติความเคลื่อนไหวทั้งหมดของเหล่าธาตุ ถ้าได้แกนมา ข้ากับ Earthen Ring อาจหาทางหยุดพวกมันได้!" },
        required = { [16762] = { "11:1975522595:1589733162", "แก่นห้วงลึก" } },
        steps = { { "11:1975522595:1589733162", "แก่นห้วงลึก" } },
    },
    [3911] = { -- The Last Element
        title = { "16:1088110154:2000851402", "ธาตุสุดท้าย" },
        objective = { "202:2066834927:228508662", "เดินทางไป Blackrock Depths และนำ Essence of the Elements 10 ชิ้นกลับมา เบื้องต้นให้ลองค้นจากโกเล็มและคนสร้างโกเล็ม นึกดูแล้ว Vivian Lagrave เคยพึมพำถึงพวกธาตุด้วย" },
        description = { "61:1289345932:306027675 N 439:1904444464:1003409032", "มีงานให้คนที่กล้าลงไปในส่วนลึก {name}\n\nพวกคนแคระ Dark Iron เชี่ยวชาญการสร้างโกเล็มที่ทรงพลังอย่างยิ่ง\n\nรายงานเบื้องต้นจากสายลับบอกว่าพวกคนแคระใช้แหล่งพลังงานพิเศษ ทำให้สิ่งที่สร้างขึ้นมีอานุภาพสังหารหาใครเทียบ\n\nลองนึกดูสิว่าเราจะทำอะไรกับพวกอาโบมิเนชันของเราได้บ้าง ถ้าได้แก่นพลังธาตุนี้มา! ถ้าจำเป็นก็พลิกเมืองหาเสียให้ทั่ว อย่ากลับมาจนกว่าจะเจอแก่นพลัง ค่าจ้างคุ้มความเสี่ยงแน่" },
        required = { [11129] = { "23:89703305:1571491226", "แก่นพลังแห่งเหล่าธาตุ" } },
        steps = { { "23:89703305:1571491226", "แก่นพลังแห่งเหล่าธาตุ" } },
    },
    [7908] = { -- Arena Master
        title = { "12:695950883:704008688", "เจ้าแห่งลานประลอง" },
        objective = { "57:2093013813:572088683", "คุยกับ Short John Mithril ใน Stranglethorn Arena" },
        description = { "122:68402568:164108203", "การเป็นเจ้าแห่งลานประลองต้องมีอะไรมากกว่านี้สิ! บางทีโจรสลัดที่จัดงานประลองใน Gurubashi อาจรู้ก็ได้!" },
    },
    [79236] = { -- Cherry for Your Thoughts?
        title = { "25:1583057541:1965970268", "เล่าให้ฟังแลกเหล้าเชอร์รี" },
        objective = { "74:1675787229:1104973842", "นำ Cherry Grog ไปให้ Tokal ที่ Booty Bay เพื่อฟังเรื่องที่เหลือ" },
        description = { "263:232725860:88765516", "เจ้ามากับจอมพลหรือ? ดูท่าไม่น่าใช่\n\nข่าวลือที่ได้ยินจริงแค่ครึ่งเดียว ใช่ เราไปปล้นค่ายมนุษย์กับคนแคระ แต่เราไม่ได้ทำให้ฮอร์ด มีคนจ้างเรามาเป็นการส่วนตัว\n\nซื้อเหล้ากร็อกให้ข้าสิ แล้วข้าจะเล่าทั้งหมดให้ฟัง" },
        progress = { "24:109574137:1567891031", "เครื่องดื่มที่ข้าขอได้หรือยัง?" },
        completion = { "39:542258323:930773211", "อา อย่างนี้สิถึงจะใช่ เมื่อกี้ข้าเล่าถึงไหนแล้วนะ?" },
        required = { [4600] = { "11:1895648553:560815250", "เหล้าเชอร์รี" } },
        steps = { { "11:1895648553:560815250", "เหล้าเชอร์รี" } },
    },
    [79242] = { -- No Honor Among Thieves
        title = { "22:1773536255:471419205", "ในหมู่โจรไร้สัจจะ" },
        objective = { "101:938343782:615675141", "ตามหา Illari Duskfeather ที่ชายฝั่ง Arathi Highlands แล้วหาทางเข้าถึงที่ซ่อนของที่นางขโมยมา" },
        description = { "496:825317858:1139618092", "อย่างที่ข้ากำลังเล่า...\n\nหัวหน้าของเราไม่ได้อยู่กับฮอร์ด นางเป็นไนต์เอลฟ์ชื่อ Illari Duskfeather นางให้ข้อมูลเรื่องค่ายกับเรา แถมยอมให้เราเก็บของที่ปล้นมาได้ส่วนใหญ่ นางเอาไปแค่ของหายากไม่กี่ชิ้น\n\nแต่พอจอมพลตามทัน นางก็ทิ้งเราให้ตาย ข้าไม่รู้ว่านางคิดอะไร แต่ดูเหมือนเราถูกจัดฉากให้รับผิดแทน\n\nข้าไม่ใช่คนเจ้าคิดเจ้าแค้น แต่ก็ไม่ห้ามถ้าใครอยากตามล่านาง ถ้าเจ้าจะไปหา นางเคยพูดถึงที่หลบซ่อนริมชายฝั่ง Arathi" },
        progress = { "43:9301869:1164935962", "<เจ้าใช้กุญแจของ Illari ไขที่ซ่อนของ>" },
        completion = { "66:1982467917:1438295121", "<ในที่ซ่อน เจ้าเจอกล่องใบเล็กกับเหรียญอีกจำนวนหนึ่ง>" },
        required = { [212347] = { "12:2061377213:168357342", "กุญแจของ Illari" } },
        steps = { { "24:2146516795:1518276446", "พบ Illari Duskfeather" }, { "12:2061377213:168357342", "กุญแจของ Illari" } },
    },
    [79677] = { -- A Quick Grocery Run
        title = { "19:2080448782:1316151504", "ไปหาของมาทำกับข้าว" },
        objective = { "83:512579956:635687912", "รวบรวมวัตถุดิบสำหรับอาหารของ Skonk แล้วนำไปให้เขาที่ Arathi Highlands" },
        description = { "322:2132719075:1212473059", "โอเกอร์อื่นหัวเราะเยาะ Skonk เพราะ Skonk ตัวเล็กกว่า พวกมันบอกโอเกอร์ตัวเล็กอ่อนแอ Skonk เลยหัดทำอาหารแทนสู้รบ ยิ่งโดนล้อหนักเข้าไปอีก Skonk เลยหนีมาตามความฝัน\n\nSkonk ทำอาหารได้ แต่ต้องมีวัตถุดิบ เอารายการไป หาของตามนั้น Skonk สนใจแต่ทำอาหาร เรื่องหาของไม่ค่อยถนัด", variants = { { "318:71309026:1562324417", "โอเกอร์อื่นหัวเราะเยาะ Skonk เพราะ Skonk ตัวเล็กกว่า พวกมันบอกโอเกอร์ตัวเล็กอ่อนแอ Skonk เลยหัดทำอาหารแทนสู้รบ ยิ่งโดนล้อหนักเข้าไปอีก Skonk เลยหนีมาตามความฝัน\n\nSkonk ทำอาหารได้ แต่ต้องมีวัตถุดิบ Skonk ก็ไม่แน่ใจว่าจะไปหาจากไหน Skonk สนใจแต่ทำอาหาร เรื่องหาของไม่ค่อยถนัด" } } },
        progress = { "45:695313404:1494535583", "หาวัตถุดิบเจอหรือยัง? ใกล้ถึงเวลาอาหารเย็นแล้ว" },
        completion = { "11:354343371:1318038540 R 30:1305705418:1168893919", "ทำดีมาก เพื่อน{race} ทีนี้ก็ได้ทำอาหารกันจริง ๆ แล้ว!" },
        required = { [213526] = { "13:1477746220:1486981414", "เนื้อสะโพกสัตว์ลูกผสม" }, [213527] = { "22:1212184732:1971430317", "เครื่องเทศผสมของนักลักลอบขนของ" } },
        steps = { { "13:1477746220:1486981414", "เนื้อสะโพกสัตว์ลูกผสม" }, { "22:1212184732:1971430317", "เครื่องเทศผสมของนักลักลอบขนของ" } },
    },
    [79678] = { -- Taste Testing
        title = { "13:914637826:635591337", "ชิมรส" },
        objective = { "33:1874723281:960060259", "ชิมอาหารตามสูตรกับ Skonk" },
        description = { "3:5245402:1369768 R 224:1772943526:69763052", "เอาล่ะ เพื่อน{race} ถึงช่วงที่ Skonk ชอบที่สุดแล้ว ไฟร้อนพร้อม Skonk อยากแบ่งอาหารจานใหม่ให้เพื่อนใหม่ เจ้าอุตส่าห์ช่วย Skonk ตั้งเยอะ ก็ควรได้ชิมด้วย!\n\nพร้อมชิมเมื่อไรก็บอก Skonk" },
        completion = { "173:202012341:9599013", "อืม สูตรนี้อร่อย!\n\nSkonk เพลินไปหน่อย แต่เจ้าช่วยได้ดีมาก!\n\nเอ้า นี่ส่วนของเจ้า Skonk แถมให้อีกนิดหน่อยที่อุตส่าห์ช่วย" },
    },
    [79939] = { -- The Broken Hammer
        title = { "17:1179674572:1600044753", "ค้อนศึกหัก" },
        objective = { "124:780830638:2056385132", "หาเบาะแสการสู้รบที่เพิ่งเกิดขึ้นที่ Mannoroc Coven แล้วนำ Broken Warhammer กลับไปให้ Katherine the Pure ใน Stormwind" },
        description = { "435:1583906941:824573113", "<ค้อนศึกหักที่ประดับอย่างวิจิตรวางอยู่ท่ามกลางศพสาวกลัทธิ Burning Blade และนักรบ Scarlet Crusade เห็นชัดว่าเพิ่งมีการต่อสู้ที่นี่ เจ้าจำได้ด้วยว่านี่เป็นอาวุธของพาลาดินแห่ง Order of the Silver Hand\n\nแม้เคยเห็นค้อนคล้ายกันมาหลายด้าม แต่คุณภาพและฝีมือการตีด้ามนี้โดดเด่นเป็นพิเศษ เจ้าควรหาเบาะแสให้ทั่ว แล้วนำค้อนที่หักกลับไปให้ Katherine>" },
        completion = { "30:2126602706:1959127614 N 68:1978273244:77212971", "<Katherine ถอนหายใจเฮือกใหญ่> ใช่ {name} ข้ารู้จักอาวุธชิ้นนี้ ข้านึกว่าเจ้าของมันตายไปนานแล้ว" },
        progress = { "37:1734437189:1123099912", "เจ้าถืออะไรมาอย่างนั้นหรือ สหาย?" },
        required = { [215441] = { "13:1442611958:1644859453", "ค้อนหัก" } },
        steps = { { "20:126964174:1455099710", "เบาะแสที่ Mannoroc Coven" }, { "28:1514428708:16677047", "กลับไปหา Katherine the Pure" } },
        objectiveLabels = {
            item = { ["Broken Hammer"] = "ค้อนหัก" },
        },
    },
    [79940] = { -- A Lost Brother
        title = { "14:1475727161:999523211", "พี่น้องที่สูญหาย" },
        objective = { "69:1575250812:259790035", "คุยกับ Katherine the Pure เพื่อสืบเรื่องค้อนที่หัก" },
        description = { "196:1855970663:441310054", "<Katherine สีหน้าเจ็บปวดขณะประคองเศษค้อนที่แตกออกเป็นชิ้น ๆ>\n\nข้าคงเล่าถึงเจ้าของอาวุธนี้โดยละเอียดไม่ได้ เล่าแล้วคงละอายใจเหลือเกิน แต่ข้าจะบอกเท่าที่บอกได้" },
        completion = { "86:2005429107:589264043", "เจ้ามีเบาะแสอยู่ไม่มาก คงตามหา Aeonas ได้ยากหน่อย แต่เจ้าควรลองดู" },
        steps = { { "35:1091456096:1345181261", "คุยกับ Katherine เพื่อสอบถามเพิ่มเติม" } },
    },
    [81900] = { -- The Burning Beast
        title = { "17:954586274:100085522", "อสูรเพลิง" },
        objective = { "50:1516866296:814532500", "ตามหาผู้เชี่ยวชาญเรื่องสัตว์ใน Blasted Lands" },
        description = { "428:701307871:1220009344", "<ภาพสลักตรงหน้าเป็นอสูรสองหัวผุดออกจาก Dark Portal เพลิงเฟลพวยพุ่งออกจากปากมัน ป้ายใต้ภาพเขียนว่า ‘Calefactus the Unleashed’\n\nลางสังหรณ์บอกเจ้าว่าสาวกลัทธิทไวไลต์อาจวางแผนควบคุมพลังทำลายล้างของมันเพื่อใช้ตามจุดประสงค์ของตน\n\nเจ้าคิดว่าการตามล่าครั้งนี้ควรมุ่งไปที่ Blasted Lands เป็นลำดับถัดไป ที่นั่นอาจมีคนรู้เรื่องอสูรจากขุมนรกตัวนี้มากกว่าเจ้า>" },
        completion = { "28:1138811164:1952909708 R 31:373878892:1725798107", "เล่าเรื่องอสูรตัวนี้ให้ข้าฟังอีกหน่อย {race} เราอาจมีเป้าหมายตรงกัน" },
    },
    [82084] = { -- A Lesson in Literacy
        title = { "20:1943049917:1724603174", "บทเรียนการเขียนตำรา" },
        objective = { "74:853713320:67841489", "ตามหาและรวบรวมวัสดุทำตำราเวทตามที่บรรณารักษ์ขอ" },
        description = { "53:1648584204:1579152725 N 223:1212656102:803388067", "เจ้าก้าวหน้าในวิชาอาคมได้ดีเยี่ยม {name} ข้าว่าเจ้าพร้อมเขียนตำราเวทของตัวเองแล้ว\n\nดูซิ... ขนนกสำหรับทำปากกาจากพวก Owlbeast ใน Hinterlands กับหมึกที่ทำจากยางซิลิธิด... ใช่ เท่านี้ก็พอ ส่วนหน้ากระดาษก็ต้องใช้ Farraki Papyrus ชั้นดีที่สุด!" },
        progress = { "53:1648584204:1579152725 N 223:1212656102:803388067", "เจ้าก้าวหน้าในวิชาอาคมได้ดีเยี่ยม {name} ข้าว่าเจ้าพร้อมเขียนตำราเวทของตัวเองแล้ว\n\nดูซิ... ขนนกสำหรับทำปากกาจากพวก Owlbeast ใน Hinterlands กับหมึกที่ทำจากยางซิลิธิด... ใช่ เท่านี้ก็พอ ส่วนหน้ากระดาษก็ต้องใช้ Farraki Papyrus ชั้นดีที่สุด!" },
        completion = { "25:594964053:844347429 N 102:1172339203:805391649", "ตำราเวทของเจ้าพร้อมแล้ว {name} ขอให้เจ้าจารึกความลับแห่งอาคมลงไปจนเต็มทุกหน้า ให้ทัดเทียมกับหอสมุดโบราณแห่ง Elun'dris และ Zuldazar" },
        required = { [221359] = { "23:824144228:2107809153", "ขนนก Owlbeast สภาพสมบูรณ์" }, [221361] = { "14:130469141:2096005094", "ยางของ Zukk'ash" }, [221360] = { "15:141861672:484426733", "กระดาษปาปิรัส Farraki" } },
        steps = { { "23:824144228:2107809153", "ขนนก Owlbeast สภาพสมบูรณ์" }, { "14:130469141:2096005094", "ยางของ Zukk'ash" }, { "15:141861672:484426733", "กระดาษปาปิรัส Farraki" } },
    },
    [86615] = { -- Treaty Obligations
        title = { "18:1563943121:568221750", "หน้าที่ตามสนธิสัญญา" },
        objective = { "73:1820846408:492340103", "หากระเป๋าเอกสารทูตของ Ambassador Redstone ที่หายไปใน Wildhammer Keep" },
        description = { "388:365548481:825997793", "โธ่เอ๊ย! ข้าเป็นทูตประจำพวก Wildhammer แท้ ๆ แต่ดันลืมกระเป๋าจดหมายการทูตชุดล่าสุดไว้ที่ไหนสักแห่งใน Wildhammer Keep คงทิ้งไว้ในโรงเหล้า... หรืออาจวางแถวถังไอน้ำ... หรืออยู่ชั้นบนกันนะ? ข้าจำไม่ได้สักที!\n\nข้าต้องใช้เอกสารพวกนั้น ถ้าเจ้าตาดีกว่าข้าก็ช่วยมองหากระเป๋าเอกสารที่หายไปให้ที!" },
        completion = { "217:1465236930:247921971 C 1:46:46", "เจอแล้ว! ขอข้าดูหน่อยว่าอยู่ครบไหม... เรื่องการทูตระวังไว้มากแค่ไหนก็ไม่เกินไป!\nดูเหมือนจะไม่มีอะไรหาย เกือบกลายเป็นเรื่องใหญ่ทางการทูตแล้วสิ! ขอบใจที่ช่วยนะ {class}" },
        progress = { "20:2133308677:1103610044", "ข้าต้องได้เอกสารพวกนั้น!" },
        required = { [279171] = { "18:1929987134:1122002557", "กระเป๋าเอกสารทางการทูต" } },
        steps = { { "18:1929987134:1122002557", "กระเป๋าเอกสารทางการทูต" } },
    },
    [86620] = { -- Fledgling Rescue
        title = { "16:1027284242:591056910", "ช่วยลูกกริฟฟิน" },
        objective = { "8:1089852795:1107240600 W1 47:824263192:851582350", "เก็บ Lost Gryphon Egg {world1} ฟองให้ Gryphon Master Talonaxe" },
        description = { "374:310848619:1493439918", "ถึงเราจะมีกริฟฟินสายพันธุ์ดีอยู่ที่นี่ แต่ในป่ายังมีไข่บางรังที่เสี่ยงไม่รอด พ่อแม่กริฟฟินอาจแพ้หมาป่าหรือล้มป่วย ถ้าไม่มีใครช่วย ลูกกริฟฟินจะไม่รอดแน่\n\nโชคดีที่เรามีทางเลี้ยงและปกป้องลูกกริฟฟินที่กำพร้าแบบนี้ ถ้าเจอไข่ที่ถูกทิ้งไว้ในป่า เอามาให้ข้า" },
        completion = { "183:653660256:837706929 C 1:46:46", "อา ทำได้ดีมาก เจ้าตัวน้อยตั้งหลายตัวมีโอกาสได้ชีวิตที่ดีขึ้นแล้ว เราจะให้รังอุ่น ๆ กับอาหารมากพอ พอโตขึ้นพวกมันจะเป็นคู่หูที่ดี\nทำได้ดี {class}" },
        progress = { "29:2109440286:2128686028", "อย่าทำให้เจ้าตัวน้อยตกใจล่ะ!" },
        required = { [279229] = { "16:1469848358:678742445", "ไข่กริฟฟินที่พลัดจากรัง" } },
        objectiveLabels = {
            item = { ["Lost Gryphon Egg"] = "ไข่กริฟฟินที่พลัดจากรัง" },
        },
    },
    [78917] = { -- The Heart of the Void
        title = { "21:49955182:501385525", "หัวใจแห่งวอยด์" },
        objective = { "66:493805494:647174854", "นำ Blackfathom Pearl ไปให้ Bashana Runetotem ใน Thunder Bluff" },
        description = { "154:824050412:707139875", "อสูรร้าย Aku'mai นอนตายอยู่ ท่ามกลางเครื่องในและเลือดของซากที่บวมอืด มีไข่มุกสีเหลือบขนาดมหึมาซ่อนอยู่ข้างใน เปี่ยมด้วยพลังวอยด์ดิบ" },
        progress = { "N 41:1459247294:1471249347", "{name} เจ้าได้ข่าวอะไรมาจาก Blackfathom บ้าง?" },
        completion = { "294:1245352111:1980958802 N 1:46:46", "Aku'mai บริวารของเทพโบราณ ตายแล้ว การกระทำของเจ้าช่วยชาว Kalimdor ไว้มาก\n\nไข่มุกอาจเป็นกุญแจให้เราเข้าใจธรรมชาติของวอยด์และผลที่มันมีต่อโลกของเรามากขึ้น ต้องนำไปศึกษาทันที ขอให้พระแม่ธรณีอยู่เคียงข้างเจ้า {name}" },
        required = { [211452] = { "25:277794056:1993152954", "ไข่มุก Blackfathom ไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Perfect Blackfathom Pearl"] = "ไข่มุก Blackfathom ไร้ตำหนิ" },
        },
    },
    [785] = { -- A Strategic Alliance
        title = { "20:899747591:523046731", "พันธมิตรเชิงกลยุทธ์" },
        objective = { "63:1336978491:256721521", "ตามหา Lar Prowltusk ทางฝั่งตะวันตกของ Sen'jin Village" },
        description = { "499:1096771612:670295117", "Thrall เป็นผู้นำที่ทั้งฉลาดและสูงศักดิ์ ความเด็ดเดี่ยวในสนามรบของเขามีเพียงชั้นเชิงการทูตที่ทัดเทียม\n\nโทรลล์ Darkspear พิสูจน์แล้วว่าเป็นพันธมิตรล้ำค่าของเผ่าออร์ค ด้วยความภักดีและเกียรติยศ เราจึงให้คำมั่นว่าจะคุ้มครองพวกเขา\n\nจอมทัพส่งคำสั่งมาให้ตรวจดูว่าสหาย Darkspear ใน Sen'jin Village ไม่มีภัยคุกคามเฉพาะหน้า Lar Prowltusk หนึ่งในหน่วยสอดแนมที่พวกเขาไว้ใจที่สุด กำลังเฝ้าระวังทางฝั่งตะวันตกอย่างใกล้ชิด\n\nไปหา Lar แล้วช่วยเขาตามที่จำเป็น" },
    },
    [8530] = { -- The Alliance Needs Singed Corestones!
        title = { "37:1379739747:1498435970", "อะไลแอนซ์ต้องการหินแกนไหม้!" },
        objective = { "83:1587532781:192837398", "นำ Singed Corestone 50 ก้อนไปให้ Commander Stronghammer ที่ลานบินใน Dun Morogh" },
        description = { "C 423:686690909:1008434939", "{class} ข้าต้องการความช่วยเหลือ ใน Molten Core มีหินชนิดหนึ่ง ที่เรียกกันว่าหินแกนไหม้ เราต้องเก็บมันไว้ใช้ระดมเสบียงสงคราม Ahn'Qiraj ข้าได้ยินว่าช่างตีเหล็กกับวิศวกรของเราใช้มันได้ดี งานนี้ต้องพึ่งเจ้า เข้า Molten Core แล้วเก็บหินพวกนี้มาให้ได้มากที่สุด แน่นอนว่าเจ้าคงอยากชวนเพื่อนสนิทอีกสามสิบเก้าคนไปด้วย" },
        required = { [20737] = { "16:1201148298:487942602", "หินแกนไหม้เกรียม" } },
        steps = { { "16:1201148298:487942602", "หินแกนไหม้เกรียม" } },
    },
    [8617] = { -- The Horde Needs Singed Corestones!
        title = { "34:1679411269:1469980775", "ฮอร์ดต้องการหินแกนไหม้!" },
        objective = { "53:586316307:1320611312", "นำ Singed Corestone 50 ก้อนไปให้ General Zog ที่ Durotar" },
        description = { "69:365393872:2070275311 C 370:1607802876:1504487345", "ถึงเวลาแล้วที่เจ้าจะช่วยระดมเสบียงสงคราม Ahn'Qiraj {class} วันอันสุขสบายที่ปล่อยเวลาให้ผ่านไปจบลงแล้ว บัดนี้ถึงเวลารับใช้ข้ากับฮอร์ด และข้ารับรองได้ว่าข้าไม่ใจอ่อนเหมือนจอมทัพ\n\nรวบรวมกำลังพล ถ้ามีกิลด์ก็ระดมคนในกิลด์มาด้วย แล้วบุกเข้า Molten Core พวกที่อาศัยอยู่ข้างในมีหินแกนไหม้ เอาหินพวกนั้นกลับมาให้ข้ามาก ๆ" },
        required = { [20737] = { "16:1201148298:487942602", "หินแกนไหม้เกรียม" } },
        steps = { { "16:1201148298:487942602", "หินแกนไหม้เกรียม" } },
    },
    [92454] = { -- Welcome!
        title = { "8:1157429440:1900744790", "ยินดีต้อนรับ!" },
        objective = { "57:1369951927:154940", "นำ Thendal Grove Gift Voucher ไปให้ Dalia Windbreeze" },
        description = { "332:1667806864:389803137", "ยินดีต้อนรับสู่ World of Warcraft!\n\nเพื่อขอบคุณเป็นพิเศษที่ซื้อ World of Warcraft Collector's Edition โปรดนำบัตรรับของขวัญนี้ไปให้ Dalia Windbreeze ที่ Thendal Grove แล้วเจ้าจะได้รับของขวัญเป็นเพื่อนตัวน้อยที่จะร่วมเดินทางไปกับเจ้าเพื่อผจญภัยและแสวงหาเกียรติยศ\n\nขอขอบคุณอีกครั้ง ขอให้สนุกกับการเดินทางใน World of Warcraft!" },
        progress = { "132:1057634608:967750197", "สวัสดี! ยินดีที่ได้พบเจ้า!\n\nเห็นเจ้ามีคูปองพิเศษด้วย เอามาให้ข้าสิ ข้ามีของให้เจ้าแลก" },
        completion = { "31:844644996:1050364761 N 82:1617086532:2042110772", "เจ้าเป็นวีรบุรุษคนพิเศษจริง ๆ นะ {name} พวกเราขอต้อนรับเจ้าสู่โลก Azeroth และขอมอบของขวัญพิเศษเหล่านี้ให้เจ้าเลือกหนึ่งอย่าง!" },
        required = { [251900] = { "26:1301551947:1992929190", "บัตรแลกของขวัญ Thendal Grove" } },
        steps = { { "26:1301551947:1992929190", "บัตรแลกของขวัญ Thendal Grove" } },
    },
    [95771] = { -- A Taste of Darkness
        title = { "19:1261151391:1251800912", "ลิ้มรสความมืด" },
        description = { "24:710417610:1742740967", "พอแล้ว พอแล้ว ข้ายอมแพ้" },
        objectiveLabels = {
            event = { ["Scout through the Fargodeep Mine"] = "สำรวจภายในเหมือง Fargodeep" },
        },
    },
    [99145] = { -- A Winter Veil Gift
        title = { "18:491378921:2117191422", "ของขวัญวินเทอร์เวล" },
    },
    [92521] = { -- The Demon Tower
        title = { "15:1060510720:747207679", "หอคอยปีศาจ" },
        objective = { "54:1920609102:56512443", "แอบจับตาอิมป์ของ Hnaz ที่หอคอยซึ่งขังซาเทอร์ไว้" },
        description = { "438:1841701035:1558983888", "เจ้ารู้ใช่ไหมว่าข้าเป็นวอร์ล็อก? ตอนนี้ตกอับจนต้องมาหั่นเนื้อขาย แต่เมื่อก่อนข้าเคยเป็นจอมเวทผู้เก่งกาจ!\n\nอิมป์ของข้าชอบแอบออกไปเรื่อย ข้าจะเรียกมันกลับมาก็ได้ แต่ก็อยากรู้เหมือนกันว่ามันไปทำอะไร มันแอบไปคุยกับซาเทอร์ที่ถูกมัดอยู่ในหอคอยทางตะวันออกเฉียงใต้ของที่นี่ ถ้าเจ้าไม่ว่าอะไร ข้าอยากรู้ว่าพวกมันคุยอะไรกัน\n\nคงไม่มีอะไรต้องห่วงหรอก แต่เรื่องปีศาจนี่ไว้ใจได้ที่ไหน จริงไหม?" },
        logReady = { "28:1817519613:74946426", "คุยกับเซเทอร์ที่ถูกจับไว้" },
    },
    [94901] = { -- Hopping Helpers
        title = { "15:188088193:1489306492", "ผู้ช่วยจอมกระโดด" },
        objective = { "8:1089852795:1107240600 W1 18:1625252791:1504118548", "จับกบ Gustjumper {world1} ตัว" },
