        title = { "29:433267127:1181996058", "คนรู้จักใน Southshore" },
        objective = { "81:318127884:382463120", "ไปพบ Loremaster Dibbs ใน Southshore แล้วมอบชุดรายงานจาก Savage Coast ให้เขา (Savage Coast Report Bundle)" },
        description = { "N 490:987548972:1471487387", "{name} ข้ามีเพื่อนอยู่ที่ Hillsbrad Foothills เขากำลังศึกษาตำนานโทรลล์กับมนตร์ชั่วร้าย เขาอาจพอรู้ว่ามนตร์โสมมนั่นเข้าครอบงำจิตใจพันเอก Kurzen ได้อย่างไร\n\nข้ายังได้รายงานจากหน่วยสอดแนมด้วยว่าโทรลล์แถวนั้นดูตื่นตระหนกและเอ่ยถึงคำว่า ‘I'lalai’\n\nข้าต้องรู้ให้ได้ว่าเรื่องนี้เกี่ยวกับการครอบงำ Kurzen หรือเปล่า! เอาเครื่องราง ตำนาน และรายงานสอดแนมฉบับนี้ไปให้ Loremaster Dibbs ถ้าโชคดี เขาคงช่วยไขความลับของโทรลล์ได้บ้าง" },
        completion = { "192:143282325:630174848", "Brother Nimetz ส่งเจ้ามาไกลถึงนี่จาก Stranglethorn เลยหรือ? เดินทางมาไกลทีเดียว คงเป็นเรื่องสำคัญสินะ\nมาเถอะ เล่าให้ข้าฟังว่าเรื่องอะไรพาเจ้ามาถึง Southshore" },
    },
    [95818] = { -- A Quick Craft
        title = { "13:1537660893:1727114212", "งานช่างแบบเร่งด่วน" },
        objective = { "86:1373993964:1414643881", "นำวัสดุที่ขอไปให้ Rotgath Stonebeard ใกล้ Great Forge ใน Ironforge" },
        description = { "115:1451172792:1202450680 W1 18:2110399959:1499448201 W2 199:1394264160:1726562474 W3 114:2100944160:678198199", "ถ้าเจ้ามีวัสดุอยู่กับตัว ข้าจัดการให้เสร็จแล้วให้เจ้าไปต่อได้เลย! ต้องใช้ Mithril Bar {world1} แท่ง กับ Heavy Leather {world2} ชิ้น ปกติต้องใช้โลหะอื่นอีกนิดหน่อย แต่ข้ามีเศษโลหะวางเกะกะอยู่พอดี เอามาใช้แทนได้\n\nอ้อ ข้าขอฝากเป็นการส่วนตัวด้วยนะ เอา Goldthorn มาให้ {world3} ต้น เมียข้ามีสูตรชาอร่อย ๆ ข้าอยากทำให้เธอประหลาดใจ ถือว่านี่เป็นค่าจ้างของข้าละกัน!" },
        required = { [3860] = { "11:1665667963:654296337", "แท่งมิธริล" }, [4234] = { "13:170018158:1996489922", "หนังชนิดหนัก" }, [3821] = { "9:1227984600:211740593", "หนามทอง" } },
        objectiveLabels = {
            item = { ["Mithril Bar"] = "แท่งมิธริล", ["Heavy Leather"] = "หนังชนิดหนัก", ["Goldthorn"] = "หนามทอง" },
        },
    },
    [95820] = { -- Karolek
        title = { "7:1781944152:499072987", "Karolek" },
        objective = { "62:399601030:1877329384", "ไปพบ Karolek ที่ร้าน Kodohide Leatherworkers ใน Orgrimmar" },
        description = { "397:131284143:1056471785", "พวกเราสร้างความสัมพันธ์อันดีกับพ่อค้าแม่ค้าและช่างฝีมือใน Orgrimmar ไว้ได้หลายราย หนึ่งในนั้นคือออร์คชื่อ Karolek เขาเป็นช่างเครื่องหนังที่คอยจัดหาหนังสัตว์และอุปกรณ์มีประโยชน์อื่น ๆ ให้เราอย่างสม่ำเสมอ\n\nแถมเขายังทำป้ายเก่งด้วย!\n\nถ้าเจ้าอยากได้ป้ายเร็ว ๆ ข้าแนะนำให้ไปหาเขาเลย บอกเขาว่าข้าส่งเจ้ามา" },
    },
    [95821] = { -- A Quick Craft
        title = { "13:1537660893:1727114212", "งานช่างแบบเร่งด่วน" },
        objective = { "90:1733011399:298948411", "นำวัสดุที่ขอไปให้ Karolek ที่ร้าน Kodohide Leatherworkers ใน Orgrimmar" },
        description = { "115:1123664175:693622072 W1 19:1887406019:1111951232 W2 181:272436711:209078122 W3 111:1642618339:222987153", "ช่างฝีมืออย่างเจ้าน่าจะหาวัสดุทำป้ายได้ไม่ยาก เราใช้แค่ Heavy Leather {world1} ชิ้น กับ Mithril Bar {world2} แท่ง\n\nปกติถ้าเร่งงาน ข้าคิดเพิ่มสองสามเหรียญทอง แต่ช่วงนี้ข้าอยากดื่มชา Goldthorn แบบชงเอง ไม่ต้องห่วง ข้าชอบชงเองอยู่แล้ว ขอแค่ Goldthorn {world3} ต้นก็พอ\n\nถ้าเอาของพวกนี้มาให้ครบ ป้ายแรกของเจ้าจะเสร็จในพริบตา!" },
        required = { [4234] = { "13:170018158:1996489922", "หนังชนิดหนัก" }, [3860] = { "11:1665667963:654296337", "แท่งมิธริล" }, [3821] = { "9:1227984600:211740593", "หนามทอง" } },
        objectiveLabels = {
            item = { ["Heavy Leather"] = "หนังชนิดหนัก", ["Mithril Bar"] = "แท่งมิธริล", ["Goldthorn"] = "หนามทอง" },
        },
    },
    [96020] = { -- Playing with Fire
        title = { "17:1369163434:1779494676", "เล่นกับไฟ" },
        objective = { "83:787852137:306425241", "ทำพิธีของ Brimstone Carving ให้เสร็จ แล้วนำผลที่ได้ไปให้อาจารย์วอร์ล็อก" },
        description = { "314:966968087:1945273291", "<รูปสลักอุ่นจาง ๆ เมื่อสัมผัส แม้รอยไหม้บนร่างที่เจ้าเก็บมันมาจะเย็นมานานแล้ว\n\nดูเหมือนคนผู้น่าสงสารคนนั้นทำสิ่งที่ตั้งใจไว้ไม่สำเร็จ แม้เจ้าจะอ่านจารึกบนรูปเคารพไม่ออก แต่มันกำลังเรียกหาเวทไฟของเจ้า บางทีเจ้าอาจทำสำเร็จในจุดที่เขาพลาด>" },
        required = { [271880] = { "27:604098340:866642044", "รูปสลักกำมะถันที่เปิดใช้งานแล้ว" } },
        objectiveLabels = {
            item = { ["Activated Brimstone Carving"] = "รูปสลักกำมะถันที่เปิดใช้งานแล้ว" },
        },
    },
    [96377] = { -- State Secrets
        title = { "13:2107584286:1621611443", "ความลับของทางการ" },
        description = { "178:1663834445:886672754", "<เจ้าคิดขึ้นได้ว่าก็อบลินมือขวาของ Shaw อาจสนใจเอกสารที่เจ้าได้มาจาก Westfall ลองถามเขาดูว่าอ่านเอกสารเหล่านี้แล้วพอเข้าใจอะไรบ้างไหม>" },
        steps = { { "29:724134273:840275988", "ตามหาสมบัติของ Mason Connery" } },
    },
    [98911] = { -- Darkspear's Standard Care Package
        title = { "33:602310570:1347806948", "ชุดเสบียงมาตรฐานของดาร์กสเปียร์" },
