    [98915] = { -- Theramore Advanced Care Package
        title = { "31:69937673:981088865", "ชุดเสบียงขั้นสูงของเธรามอร์" },
    },
    [909] = { -- Baron Aquanis
        description = { "406:22535933:597261648", "ธาตุน้ำที่พ่ายแพ้ทิ้งลูกแก้วน้ำประหลาดไว้ เจ้าคาดว่าของชิ้นนี้คงส่งพลังให้มันด้วยวิธีใดวิธีหนึ่ง น้ำที่ดูเน่าเสียไหลกระฉอกอยู่ข้างใน ส่วนตัวลูกแก้วดูเหมือนจะทนต่อแรงกระแทกได้ทุกรูปแบบ\n\nถ้ามีใครพอจะเข้าใจว่าของชิ้นนี้คืออะไร ก็คงเป็น Je'neu Sancrea แห่ง Earthen Ring เขาอยู่ที่ Zoram'gar Outpost ของฮอร์ดใน Ashenvale" },
        title = { "13:1708984273:1608021478", "บารอน Aquanis" },
        objective = { "80:1033215325:1584426343", "นำ Strange Water Globe ไปให้ Je'neu Sancrea ที่ Zoram'gar Outpost ใน Ashenvale" },
        required = { [16782] = { "19:1953997721:2094638485", "ลูกแก้วน้ำประหลาด" } },
        steps = { { "19:1953997721:2094638485", "ลูกแก้วน้ำประหลาด" } },
    },
    [93156] = { -- The Haunted Forest
        description = { "437:1454641225:445085681", "อ้าว ไม่เชื่อข้ารึ? ข้าอาจเป็นคนขี้เมา แต่พูดจริงนะ ป่านั่นมีวิญญาณปิ๊กมีวิปริตสิงอยู่... ผี... ปีศาจ... อะไรสักอย่างนี่แหละ! *สะอึก* ตัวมันกระจิ๊ดเดียว แต่เวทมันฆ่าคนได้ง่าย ๆ เลย รังมันเต็มไปด้วยโทเท็มอาคมน่ากลัวที่ทำให้เจ้ากลายเป็นฝุ่นได้!\n\nพวกวิญญาณป่ารุมล้อมคุ้มกันมันอยู่ ถ้าเจ้าเห็นกับตาเดี๋ยวก็รู้ เจ้าจะรู้เอง! *สะอึก*" },
        title = { "18:208021097:1053194231", "ป่าผีสิง" },
    },
    [93174] = { -- The Malfunctioning Construct
        description = { "363:270978269:95831171", "หุ่นกลตรงหน้าส่งเสียงหึ่ง ๆ และกระตุก เห็นได้ชัดว่ามันทำงานผิดปกติ จากประสบการณ์ด้านวิศวกรรมที่เจ้ามีอยู่บ้าง เจ้าคิดว่ามันคงต้องได้รับการซ่อม\n\nมีช่างฝีมือใน Valanaar อยู่สองสามคนที่เคยดูแลหุ่นกลไซโคลนแบบนี้ ส่วนฤๅษีที่สอนวิศวกรรมให้เจ้าก็อาจรู้อะไรอยู่บ้าง" },
        title = { "28:197938709:1835998628", "หุ่นกลที่ทำงานผิดปกติ" },
        objective = { "152:741105746:208125776", "คุยกับ Riaani Nightwind ที่ Valanaar ก่อน แล้วไปคุยกับ Strange Hermit ใน Shadowgale Forest เพื่อหาข้อมูลเพิ่มเกี่ยวกับ Malfunctioning Cyclone Construct" },
        steps = { { "47:344583453:630469452", "คุยกับ Riaani Nightwind เรื่องสิ่งประดิษฐ์" }, { "49:804242281:2141391019", "คุยกับ Strange Hermit เรื่องสิ่งประดิษฐ์" } },
    },
    [93732] = { -- The Port of Valanaar
        description = { "505:1256561054:868170393", "ที่นี่เคยเป็นท่าเรือสมัยที่เรือเหาะเดินทางระหว่างแคว้นได้ แต่เราขาดการติดต่อกับเกาะอื่น ๆ มานานแล้ว ท่าเทียบเรือส่วนใหญ่จึงตั้งไว้ให้เห็นเท่านั้น ถึงอย่างนั้นเราก็ยังซ่อมบำรุงเรือไว้ เผื่อจำเป็นต้องใช้\n\nเจ้าเพิ่งมาถึง Valanaar ลองเดินทำความรู้จักคนแถวนี้ดูสักหน่อยก็คุ้ม ถ้าเจ้าลองถามดู นักผจญภัยที่รู้จักหาโอกาสอย่างเจ้าน่าจะมีงานให้ทำแน่ พอเสร็จแล้ว ช่วยเอาจดหมายนี้ไปให้ผู้อาวุโสสูงสุด Talaanis Shadowsong ที" },
        title = { "20:775175009:734239434", "ท่าเรือแห่ง Valanaar" },
    },
    [95511] = { -- Your First Feline Friend
        description = { "505:236163102:1228160502", "สวัสดี สหาย! วันนี้เป็นวันสำคัญจริง ๆ เจ้าจะได้ผูกสายสัมพันธ์กับเสือเซเบอร์ตัวแรกของเจ้า\n\nเจ้าอาจรู้อยู่แล้วว่าเสือเซเบอร์พวกนี้ฉลาดมาก และภักดีต่อผู้ขี่ที่มันผูกพันด้วยอย่างยิ่ง เจ้าจะหาสหายที่สง่างามและซื่อสัตย์ไปกว่านี้ไม่ได้แล้ว เจ้าจึงมีเรื่องสำคัญให้เลือก เจ้าและเสือเซเบอร์ของเจ้าจะออกเดินทางไปทั่วโลกด้วยกัน จงเลือกให้ดี! วางใจเถอะ ไม่ว่าเจ้าจะเลือกตัวไหน เจ้าก็เลือกถูกแล้ว\n\nไปดูเสือเซเบอร์แต่ละตัวเถอะ พอเลือกได้แล้วก็กลับมาหาข้า" },
        title = { "24:1421318495:597538137", "สหายเสือเซเบอร์ตัวแรกของเจ้า" },
        objective = { "53:1661078553:365088842", "สำรวจเสือเซเบอร์สำหรับขี่เพื่อเลือกสัตว์ขี่ตัวแรกของเจ้า" },
        progress = { "157:1471709164:1512656388", "เลือกได้หรือยัง? เสือเซเบอร์พวกนี้เป็นสายพันธุ์ชั้นดี เราเพาะเลี้ยงที่ Darnassus มาหลายชั่วรุ่นแล้ว\n\nเจ้าจะหาคู่หูที่ซื่อสัตย์กว่านี้ไม่ได้อีกแล้ว" },
        completion = { "11:1614239848:1406166483 N 286:1449474130:1868429425", "ดีมาก {name} ข้าเห็นจากแววตาว่าเจ้าเลือกได้แล้ว\n\nข้าดีใจที่ได้มอบเสือเซเบอร์ตัวหนึ่งของเราให้เจ้า ดูท่าตัวที่เจ้าเลือกจะถูกใจเจ้าเข้าแล้ว ข้าหวังว่าเจ้าจะดูแลมันให้ดี และมันก็จะดูแลเจ้าเช่นกัน\n\nขอพรแห่ง Elune จงคุ้มครองเจ้าทั้งคู่เมื่อออกเดินทางสู่โลกกว้าง" },
        steps = { { "30:2075405162:1462864827", "สำรวจ Frostsaber ลายทาง" }, { "30:1364127181:873668561", "สำรวจ Nightsaber ลายทาง" }, { "30:285038508:459698138", "สำรวจ Frostsaber ลายจุด" }, { "29:1452359882:595742551", "สำรวจ Dawnsaber ลายทาง" } },
    },
    [96376] = { -- State Secrets
        description = { "197:1775404166:1451456072", "<เจ้าคิดขึ้นได้ว่า Nazgrel ในฐานะที่ปรึกษาของจอมทัพ อาจสนใจเอกสารที่เจ้าได้มาจาก Westfall มาก ลองถามเขาดูว่าอ่านเอกสารเหล่านี้แล้วพอเข้าใจอะไรบ้างไหม>" },
        title = { "13:2107584286:1621611443", "ความลับของทางการ" },
    },
    [99205] = { -- Swift as the Wind
        description = { "17:1659610970:2055106361 N 449:1774107604:156503926", "กลับมาแล้วสินะ {name} ดีมาก ถึงเวลาเรียนขี่พาหนะคู่ใจของเจ้าจริง ๆ เสียที เจ้าเสือเซเบอร์หุ้มเกราะนั่นไง\n\nเมื่อเจ้าฝึกกับข้าแล้ว Lelanai จะมอบพาหนะให้เจ้าฟรีหนึ่งตัว หลังจากนั้นเจ้าจะซื้อเพิ่มกี่ตัวก็ได้ตามใจ โลกนี้มีสัตว์ให้ขี่หลายชนิด แต่ละชนิดต้องใช้ทักษะการขี่ต่างกัน เจ้าต้องไปหาอาจารย์ที่สอนขี่สัตว์ชนิดนั้น ๆ เอง\n\nเมื่อมีเงินพอแล้วมาคุยกับข้า ข้าจะสอนทุกอย่างที่รู้เรื่องการขี่เสือเซเบอร์ให้เจ้า" },
        title = { "17:1951865332:1269485614", "ว่องไวปานสายลม" },
        objective = { "47:1704156988:1787295408", "เรียนทักษะการขี่พาหนะขั้นชำนาญจาก Jartsam" },
    },
    [99214] = { -- An Epic Ride
        objective = { "60:201832732:1784425504", "สำรวจเสือเซเบอร์ขี่หุ้มเกราะเพื่อเลือกพาหนะระดับมหากาพย์ของเจ้า" },
        description = { "485:727954341:236877344", "สวัสดี สหาย! ดีใจที่ได้พบเจ้าอีกครั้ง วันนี้เจ้ามีทั้งประสบการณ์และฝีมือพอจะผูกสายสัมพันธ์กับเสือเซเบอร์ที่เร็วและดุที่สุดของเราแล้ว\n\nเสือพวกนี้ทั้งฉลาดมากและภักดีต่อผู้ขี่ที่มันผูกพันด้วยอย่างยิ่ง เจ้าจะหาสหายที่สง่างามและซื่อสัตย์ไปกว่านี้ไม่ได้แล้ว\n\nเจ้าจึงมีเรื่องสำคัญให้เลือก เจ้าและเสือเซเบอร์ของเจ้าจะออกเดินทางไปทั่วโลกด้วยกัน จงเลือกให้ดี!\n\nไปดูเสือเซเบอร์หุ้มเกราะแต่ละตัวเถอะ พอเลือกได้แล้วก็กลับมาหาข้า" },
        title = { "12:1160301614:1027353324", "ยอดพาหนะคู่ใจ" },
    },
    [99216] = { -- An Epic Ride
        description = { "17:1558164595:354322929 N 471:530833952:1582540374", "ขอให้สายลมทักทายเจ้า {name}! ไม่นึกว่าวันนี้จะมาถึงเร็วขนาดนี้ ข้าภูมิใจที่เจ้าชำนาญการขี่เกลสไตรเดอร์แล้ว บัดนี้ข้าจึงเสนอตัวที่ดีที่สุด เร็วที่สุด และกล้าหาญที่สุดของเราให้เจ้าได้\n\nเหมือนครั้งก่อน เจ้าและเกลสไตรเดอร์จะออกเดินทางไปทั่วโลกด้วยกัน เจ้าจึงมีเรื่องสำคัญให้เลือก พวกมันหลายตัวโตขึ้นมากระหว่างที่เจ้าจากไป แต่ข้าว่าพวกมันยังจำเจ้าได้แน่\n\nไปดูเกลสไตรเดอร์หุ้มเกราะแต่ละตัวเถอะ พอเลือกได้แล้วก็กลับมาหาข้า" },
        title = { "12:1160301614:1027353324", "ยอดพาหนะคู่ใจ" },
    },
    [97205] = { -- Learning to Ride
        description = { "7:989913233:66981971 C 489:1980057829:837095637", "สวัสดี {class}! ดูเหมือนเจ้าจะผ่านการผจญภัยมามากพอแล้ว ข้าสอนเจ้าขี่เกลสไตรเดอร์ได้ มีค่าเรียนตามธรรมเนียมนะ\n\nเมื่อฝึกกับข้าแล้ว ข้าจะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ โลกนี้มีสัตว์ขี่หลายชนิด แต่ละชนิดต้องใช้ทักษะต่างกัน เจ้าต้องหาครูฝึกให้ตรงกับสัตว์ที่อยากขี่\n\nมาคุยกับข้าเมื่อมีเงินพอ แล้วข้าจะสอนเจ้าขี่เกลสไตรเดอร์" },
        title = { "16:138327183:488009726", "หัดขี่สัตว์" },
        objective = { "56:430008942:347423286", "เรียนทักษะ Apprentice Riding จาก Genn Fairweather" },
        completion = { "271:869805580:1004847098", "สุดยอด! เจ้าทำได้ดีมาก การหัดขี่สไตรเดอร์พวกนี้มักต้องอาศัยทั้งความอดทนและมือที่นิ่ง\n\nตามธรรมชาติพวกมันไม่วิ่งหนี แต่ใครจะรู้ว่าเจ้ากับสัตว์ขี่จะต้องเจออะไรในโลกกว้าง? เตรียมตัวไว้ย่อมดีกว่า!" },
        steps = { { "24:1857109559:1009967372", "เรียนทักษะขี่สัตว์ขั้นฝึกหัด (Apprentice Riding)" } },
    },
    [99203] = { -- Swift as the Wind
        objective = { "56:1310288086:2025020553", "เรียนทักษะขี่พาหนะระดับ Journeyman จาก Genn Fairweather" },
        description = { "378:1273634877:497994010", "อ้อ กลับมาแล้วสินะ ดีมาก เจ้าพร้อมเรียนขี่เกลสไตรเดอร์หุ้มเกราะหรือยัง?\n\nเหมือนครั้งก่อน เมื่อเจ้าฝึกขั้นต่อไปกับข้า ข้าจะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นเจ้าจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ\n\nค่าเรียนไม่ถูกหรอกนะ แต่ถ้าเจ้ามีเงินพอแล้วก็มาคุยกับข้า ข้าจะสอนเจ้าขี่เกลสไตรเดอร์หุ้มเกราะ" },
        title = { "17:1951865332:1269485614", "ว่องไวปานสายลม" },
    },
    [96982] = { -- Your First Riding Kodo
        description = { "29:413620416:1030227199 C 468:1720234243:53545753", "อา ข้ารอเจ้าอยู่ {class} ดูเหมือนวันนี้สายลมจะพาเจ้ามาหาข้า เจ้ามาหาโคโดใช่ไหม?\n\nโคโดเป็นสัตว์สง่างามและใจเย็น เจ้าคงหาคู่หูที่พึ่งพาได้มากกว่านี้ยาก\n\nวันนี้เจ้ามีเรื่องสำคัญให้เลือก เจ้าและโคโดจะเดินทางไปทั่วโลกด้วยกัน ลองดูว่าตัวไหนถูกชะตากับเจ้า ไม่ต้องกังวล ไม่ว่าเจ้าจะเลือกตัวไหนก็เป็นตัวที่เหมาะกับเจ้า\n\nไปดูโคโดแต่ละตัวแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "22:1676146721:1226444743", "โคโดสำหรับขี่ตัวแรกของเจ้า" },
        objective = { "52:948222397:995837639", "สำรวจโคโดสำหรับขี่เพื่อเลือกสัตว์ขี่ตัวแรกของเจ้า" },
        progress = { "204:1223448861:1594213635", "เลือกได้หรือยัง? โคโดพวกนี้พาบรรพบุรุษของเราข้ามที่ราบมาหลายชั่วรุ่น พวกมันหนักแน่นและทรงพลัง\nเจ้าจะหาสัตว์ขี่ที่ซื่อสัตย์และสง่างามกว่านี้ไปเดินทางด้วยไม่ได้อีกแล้ว" },
        completion = { "11:1614239848:1406166483 N 268:965051857:348703203", "เยี่ยมมาก {name} ข้าเห็นจากแววตาว่าเจ้าเลือกได้แล้ว\n\nข้ายินดีมอบโคโดชั้นดีของเราให้เจ้าสักตัว ดูสิ ตัวที่เจ้าเลือกเหมือนจะชอบเจ้าแล้วด้วย หวังว่าเจ้าจะดูแลมันดี ๆ และมันจะดูแลเจ้าเช่นกัน\n\nขอให้ Earthmother นำทางเจ้าทั้งคู่" },
        steps = { { "16:1949073048:836201295", "โคโดสำหรับขี่สีเทา" }, { "17:250072512:690976272", "โคโดสำหรับขี่สีน้ำตาล" }, { "17:487124824:1684954465", "โคโดสำหรับขี่สีขาว" } },
    },
    [97446] = { -- Your First Riding Kodo
        description = { "28:1447191783:876693572 C 468:1720234243:53545753", "อา ข้ารอเจ้าอยู่ {class} ดูเหมือนวันนี้สายลมจะพาเจ้ามาหาข้า เจ้ามาหาโคโดใช่ไหม?\n\nโคโดเป็นสัตว์สง่างามและใจเย็น เจ้าคงหาคู่หูที่พึ่งพาได้มากกว่านี้ยาก\n\nวันนี้เจ้ามีเรื่องสำคัญให้เลือก เจ้าและโคโดจะเดินทางไปทั่วโลกด้วยกัน ลองดูว่าตัวไหนถูกชะตากับเจ้า ไม่ต้องกังวล ไม่ว่าเจ้าจะเลือกตัวไหนก็เป็นตัวที่เหมาะกับเจ้า\n\nไปดูโคโดแต่ละตัวแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "22:1676146721:1226444743", "โคโดสำหรับขี่ตัวแรกของเจ้า" },
        objective = { "52:948222397:995837639", "สำรวจโคโดสำหรับขี่แต่ละตัวเพื่อเลือกพาหนะตัวแรกของเจ้า" },
    },
    [97204] = { -- Learning to Ride
        description = { "11:927657569:725753248 C 487:1424932810:2086153218", "สวัสดี {class} ดูเหมือนเจ้าจะผ่านการผจญภัยมามากพอแล้ว ข้าสอนเจ้าขี่โคโดได้ มีค่าเรียนตามธรรมเนียมนะ\n\nเมื่อฝึกกับข้าแล้ว Harb จะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ โลกนี้มีสัตว์ขี่หลายชนิด แต่ละชนิดต้องใช้ทักษะต่างกัน เจ้าต้องหาครูฝึกให้ตรงกับสัตว์ที่อยากขี่\n\nมาคุยกับข้าเมื่อมีเงินพอ แล้วข้าจะสอนเจ้าขี่โคโดผู้สง่างาม" },
        title = { "16:138327183:488009726", "หัดขี่สัตว์" },
        objective = { "55:1252775188:2016759211", "เรียนทักษะ Apprentice Riding จาก Kar Stormsinger" },
        completion = { "10:334093107:1878068334 C 231:1432329816:1103248196", "อ้อ สวัสดี {class} ข้าดีใจที่เจ้าฝึกกับ Kar จนจบแล้ว\n\nเมื่อเจ้าฝึกกับเขามา Earthmother จะคอยนำทางเจ้า เขามีวิธีเข้าหาโคโดพวกนี้แบบที่น้อยคนนักจะทำได้ เขาเป็นครูสอนขี่สัตว์ที่ดีที่สุดใน Mulgore" },
        steps = { { "24:1857109559:1009967372", "เรียนทักษะขี่สัตว์ขั้นฝึกหัด (Apprentice Riding)" } },
    },
    [99202] = { -- Swift as the Wind
        objective = { "55:2016593441:1947600273", "เรียนทักษะขี่พาหนะระดับ Journeyman จาก Kar Stormsinger" },
        description = { "20:1364415476:1592384200 C 362:790294750:2097731596", "ยินดีที่ได้พบอีกครั้ง {class} ถึงเวลาเรียนขี่หนึ่งในสัตว์ขี่ที่สง่างามที่สุดของเราแล้ว โคโดหุ้มเกราะ\n\nเมื่อฝึกกับข้าจนจบ Harb จะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นเจ้าจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ เหมือนครั้งก่อน\n\nค่าเรียนแพงหน่อย แต่เมื่อมีเงินพอแล้วมาคุยกับข้า ข้าจะฝึกเจ้าให้จบ" },
        title = { "17:1951865332:1269485614", "ว่องไวปานสายลม" },
    },
    [99217] = { -- An Epic Ride
        description = { "28:1447191783:876693572 N 414:738062553:81225939", "อา ข้ารอเจ้าอยู่ {name} ดูเหมือนสายลมจะพาเจ้ากลับมาหาข้าอีกครั้ง เพื่อให้เจ้าได้ขี่โคโดที่เร็วและแข็งแกร่งที่สุดของเรา\n\nวันนี้ข้าภูมิใจที่จะพาเจ้ามาเลือกโคโดตัวต่อไป พวกมันแต่ละตัวแข็งแรงขึ้นและวิ่งเร็วขึ้นตั้งแต่ที่พบเจ้าครั้งก่อน เหมือนเจ้านั่นแหละ\n\nเจ้าและโคโดจะเดินทางไปทั่วโลกด้วยกันเหมือนก่อน ลองดูว่าตัวไหนถูกชะตากับเจ้า\n\nไปดูโคโดหุ้มเกราะแต่ละตัวแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "12:1160301614:1027353324", "ยอดพาหนะคู่ใจ" },
    },
    [99210] = { -- An Epic Ride
        description = { "9:753837115:1308818947 N 430:689563608:1028354743", "อา สวัสดี {name}! ดูสิ เจ้าโตขึ้นมากตั้งแต่ครั้งก่อนที่มาเยือนคอกสัตว์เล็ก ๆ ของข้า ว่าไหม?\n\nดูเหมือนเจ้าจะมีประสบการณ์พอจะขี่แกะเขาใหญ่ที่ดุและเร็วที่สุดของเราแล้ว! ข้าภูมิใจในตัวเจ้าจริง ๆ\n\nเจ้ามีเรื่องสำคัญให้เลือก เจ้าและแกะของเจ้าจะเดินทางไปทั่วโลกด้วยกัน เลือกให้ดีล่ะ ไม่ต้องห่วง ตัวที่เจ้าเลือกจะเป็นตัวที่เหมาะกับเจ้า\n\nไปดูแกะเขาใหญ่หุ้มเกราะแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "12:1160301614:1027353324", "ยอดพาหนะคู่ใจ" },
    },
    [99212] = { -- An Epic Ride
        description = { "423:1264806416:94222550", "ขอคารวะ! วันนี้เป็นวันสำคัญจริง ๆ เจ้าจะได้ซิงก์ข้อมูลชีวมิติของเจ้ากับระบบตรวจจับผู้ขี่ของเมคาโนสไตรเดอร์ที่เร็วและดุที่สุดของเรา! ระบบนี้จะช่วยให้มันแยกเจ้าออกจากคนอื่นที่อาจขึ้นขี่\n\nเห็นได้ชัดว่าเจ้ามีประสบการณ์ขี่สไตรเดอร์พอจะควบคุมรุ่นที่ดีที่สุดรุ่นหนึ่งของเราแล้ว\n\nไปดูเมคาโนสไตรเดอร์รุ่นอัปเกรดแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "12:1160301614:1027353324", "ยอดพาหนะคู่ใจ" },
    },
    [99207] = { -- Swift as the Wind
        description = { "436:1448392885:935211009", "ข้าดูออกว่าเจ้าฝึกมาไกลพอจะควบคุมเมคาโนสไตรเดอร์รุ่นเร็วที่ทรงพลังที่สุดรุ่นหนึ่งของเราได้แล้ว\n\nเมื่อฝึกช่วงสุดท้ายกับข้าจนจบ Milli จะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นเจ้าจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ เหมือนครั้งก่อน\n\nค่าเรียนไม่ถูกหรอกนะ แต่เมื่อมีทองพอแล้วมาคุยกับข้า ข้าจะสอนเจ้าขี่เมคาโนสไตรเดอร์แบบเพิ่มกำลังพิเศษของเรา!" },
        title = { "17:1951865332:1269485614", "ว่องไวปานสายลม" },
        objective = { "60:2111486343:1062279871", "เรียนทักษะการขี่พาหนะขั้นชำนาญจาก Binjy Featherwhistle" },
    },
    [99209] = { -- Swift as the Wind
        description = { "69:601632487:979445874 N 281:1323023589:1696461702", "กลับมาแล้ว! ดี ดี\n\nพร้อมมีสัตว์ขี่แบบชาวเขาตัวจริงหรือยัง {name}?\n\nเมื่อฝึกช่วงสุดท้ายกับข้าจนจบ Veron จะจัดแกะเขาใหญ่หุ้มเกราะให้เจ้าฟรีหนึ่งตัว หลังจากนั้นเจ้าจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ\n\nมาคุยกับข้าเมื่อมีเงินพอ แล้วข้าจะสอนทุกอย่างที่รู้เรื่องการขี่แกะเขาใหญ่หุ้มเกราะให้เจ้า" },
        title = { "17:1951865332:1269485614", "ว่องไวปานสายลม" },
        objective = { "55:2008413789:330258590", "เรียนทักษะ Journeyman Riding จาก Ultham Ironhorn" },
    },
    [97045] = { -- Your First Horse
        description = { "497:2110102704:940382642", "สวัสดี! เจ้ามาดูม้าของเราหรือ?\n\nม้าพวกนี้สืบสายมาจากทั้งม้าพันธุ์เก่าแก่ของ Lordaeron และม้าท้องถิ่นของเราเอง เจ้าจะหาคู่หูร่วมทางที่ไว้ใจได้กว่านี้ไม่ได้แล้ว\n\nอาจเลือกยากสักหน่อย เพราะทุกตัวดีเยี่ยมและฝึกมาให้สงบนิ่งแม้ตกอยู่ในอันตราย อย่าลืมว่าเจ้าและม้าจะเดินทางไปทั่วโลกด้วยกัน ข้ามั่นใจว่าไม่ว่าเจ้าจะเลือกตัวไหน มันก็จะเหมาะกับเจ้า\n\nไปดูม้าแต่ละตัวแล้วกลับมาหาข้าเมื่อเลือกได้", variants = { { "612:2003353289:895085822", "สวัสดี พาลาดิน! ยอมรับว่าข้าประหลาดใจที่เห็นคนจากคณะของเจ้ามาที่คอกม้าของข้า\n\nถ้าเจ้ากำลังหาพาหนะ เจ้ามาถูกที่แล้ว แม้ม้าของเราอาจสู้ม้าศึกที่เจ้าคุ้นเคยไม่ได้\n\nแต่ถ้าอยากได้สักตัว ข้าก็อยากให้เจ้าลองเดินดู ม้าของเรานับว่าดีที่สุดในแผ่นดิน พวกมันสืบสายพันธุ์จากทั้งม้าพันธุ์เก่าแก่ของ Lordaeron และม้าท้องถิ่นของเรา เจ้าคงหาเพื่อนร่วมทางที่ไว้ใจได้กว่านี้ยาก\n\nไปดูม้าเสียก่อนว่ามีตัวไหนถูกใจ แล้วกลับมาหาข้าเมื่อเลือกได้แล้ว" }, { "549:1327336741:199535678", "สวัสดี วอร์ล็อก ข้ายอมรับว่าประหลาดใจที่เห็นผู้มีฝีมืออย่างเจ้ามาที่คอกม้าของข้า\n\nถ้าเจ้ากำลังหาพาหนะ เจ้ามาถูกที่แล้ว แม้ม้าของเราอาจสู้ม้าเฟลที่เจ้าเคยอัญเชิญไม่ได้\n\nแต่ถ้าอยากได้สักตัว ข้าก็อยากให้เจ้าลองเดินดู ม้าของเรานับว่าดีที่สุดในแผ่นดิน และพวกมันก็พร้อมพาเจ้าเดินทางอย่างซื่อสัตย์ไม่แพ้ม้าเฟลจากนรกที่เจ้าอัญเชิญมา\n\nไปดูม้าเสียก่อนว่ามีตัวไหนถูกใจ แล้วกลับมาหาข้าเมื่อเลือกได้แล้ว" } } },
        title = { "16:1243290050:909912510", "ม้าตัวแรกของเจ้า" },
        objective = { "53:1077099865:1517975772", "สำรวจม้าขี่เพื่อเลือกสัตว์ขี่ตัวแรกของเจ้า" },
        completion = { "11:1614239848:1406166483 N 301:384400991:1387989666", "ยอดเยี่ยม {name}! ดูออกเลยว่าเจ้าเลือกได้แล้ว และเลือกได้ดีมากด้วย\nข้าภูมิใจที่ได้มอบม้าตัวหนึ่งของเราให้เจ้า ดูท่าว่าตัวที่เจ้าเลือกจะถูกใจเจ้าเข้าแล้ว! ข้าหวังว่าเจ้าจะดูแลมันให้ดี และมันก็จะดูแลเจ้าเช่นกัน\nถ้าต้องการเกือกม้าใหม่ก็กลับมาหาได้เลย ข้าให้ฟรี!" },
        steps = { { "11:1387244302:618983734", "ม้าด่าง" }, { "11:802001797:526426950", "ม้าสีน้ำตาล" }, { "13:1321818398:29916775", "แม่ม้าสีน้ำตาลแดง" } },
    },
    [97171] = { -- Your First Horse
        description = { "497:2110102704:940382642", "สวัสดี! เจ้ามาดูม้าของเราหรือ?\n\nม้าพวกนี้สืบสายมาจากทั้งม้าพันธุ์เก่าแก่ของ Lordaeron และม้าท้องถิ่นของเราเอง เจ้าจะหาคู่หูร่วมทางที่ไว้ใจได้กว่านี้ไม่ได้แล้ว\n\nอาจเลือกยากสักหน่อย เพราะทุกตัวดีเยี่ยมและฝึกมาให้สงบนิ่งแม้ตกอยู่ในอันตราย อย่าลืมว่าเจ้าและม้าจะเดินทางไปทั่วโลกด้วยกัน ข้ามั่นใจว่าไม่ว่าเจ้าจะเลือกตัวไหน มันก็จะเหมาะกับเจ้า\n\nไปดูม้าแต่ละตัวแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "16:1243290050:909912510", "ม้าตัวแรกของเจ้า" },
        objective = { "53:1077099865:1517975772", "สำรวจม้าขี่แต่ละตัวเพื่อเลือกพาหนะตัวแรกของเจ้า" },
    },
    [98166] = { -- Your First Horse
        description = { "497:2110102704:940382642", "สวัสดี! เจ้ามาดูม้าของเราหรือ?\n\nม้าพวกนี้สืบสายมาจากทั้งม้าพันธุ์เก่าแก่ของ Lordaeron และม้าท้องถิ่นของเราเอง เจ้าจะหาคู่หูร่วมทางที่ไว้ใจได้กว่านี้ไม่ได้แล้ว\n\nอาจเลือกยากสักหน่อย เพราะทุกตัวดีเยี่ยมและฝึกมาให้สงบนิ่งแม้ตกอยู่ในอันตราย อย่าลืมว่าเจ้าและม้าจะเดินทางไปทั่วโลกด้วยกัน ข้ามั่นใจว่าไม่ว่าเจ้าจะเลือกตัวไหน มันก็จะเหมาะกับเจ้า\n\nไปดูม้าแต่ละตัวแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "16:1243290050:909912510", "ม้าตัวแรกของเจ้า" },
        objective = { "53:1077099865:1517975772", "ดูม้าที่มีให้เลือก แล้วเลือกพาหนะตัวแรกของเจ้า" },
    },
    [99326] = { -- Your First Horse
        description = { "497:2110102704:940382642", "สวัสดี! เจ้ามาดูม้าของเราหรือ?\n\nม้าพวกนี้สืบสายมาจากทั้งม้าพันธุ์เก่าแก่ของ Lordaeron และม้าท้องถิ่นของเราเอง เจ้าจะหาคู่หูร่วมทางที่ไว้ใจได้กว่านี้ไม่ได้แล้ว\n\nอาจเลือกยากสักหน่อย เพราะทุกตัวดีเยี่ยมและฝึกมาให้สงบนิ่งแม้ตกอยู่ในอันตราย อย่าลืมว่าเจ้าและม้าจะเดินทางไปทั่วโลกด้วยกัน ข้ามั่นใจว่าไม่ว่าเจ้าจะเลือกตัวไหน มันก็จะเหมาะกับเจ้า\n\nไปดูม้าแต่ละตัวแล้วกลับมาหาข้าเมื่อเลือกได้", variants = { { "610:187717721:1888528808", "สวัสดี พาลาดิน! ยอมรับว่าข้าประหลาดใจที่เห็นคนจากคณะของเจ้ามาที่คอกม้าของข้า\n\nถ้าเจ้ากำลังหาพาหนะ เจ้ามาถูกที่แล้ว แม้ม้าของเราอาจสู้ม้าศึกที่เจ้าคุ้นเคยไม่ได้\n\nแต่ถ้าอยากได้สักตัว ข้าก็อยากให้เจ้าลองเดินดู ม้าของเรานับว่าดีที่สุดในแผ่นดิน พวกมันสืบสายพันธุ์จากทั้งม้าพันธุ์เก่าแก่ของ Lordaeron และม้าท้องถิ่นของเรา เจ้าคงหาเพื่อนร่วมทางที่ไว้ใจได้กว่านี้ยาก\n\nไปดูม้าเสียก่อนว่ามีตัวไหนถูกใจ แล้วกลับมาหาข้าเมื่อเลือกได้แล้ว" }, { "547:2136452709:931062766", "สวัสดี วอร์ล็อก ข้ายอมรับว่าประหลาดใจที่เห็นผู้มีฝีมืออย่างเจ้ามาที่คอกม้าของข้า\n\nถ้าเจ้ากำลังหาพาหนะ เจ้ามาถูกที่แล้ว แม้ม้าของเราอาจสู้ม้าเฟลที่เจ้าเคยอัญเชิญไม่ได้\n\nแต่ถ้าอยากได้สักตัว ข้าก็อยากให้เจ้าลองเดินดู ม้าของเรานับว่าดีที่สุดในแผ่นดิน และพวกมันก็พร้อมพาเจ้าเดินทางอย่างซื่อสัตย์ไม่แพ้ม้าเฟลจากนรกที่เจ้าอัญเชิญมา\n\nไปดูม้าเสียก่อนว่ามีตัวไหนถูกใจ แล้วกลับมาหาข้าเมื่อเลือกได้แล้ว" } } },
        title = { "16:1243290050:909912510", "ม้าตัวแรกของเจ้า" },
        objective = { "53:1077099865:1517975772", "สำรวจม้าขี่เพื่อเลือกสัตว์ขี่ตัวแรกของเจ้า" },
        steps = { { "11:1387244302:618983734", "ม้าด่าง" }, { "11:802001797:526426950", "ม้าสีน้ำตาล" }, { "13:1321818398:29916775", "แม่ม้าสีน้ำตาลแดง" } },
    },
    [99206] = { -- Swift as the Wind
        objective = { "53:1465433564:1265640966", "เรียนทักษะขี่พาหนะระดับ Journeyman จาก Randal Hunter" },
        description = { "475:1182869444:328803231", "ดีใจที่เจ้ากลับมาหาข้า รอยขีดข่วนบนตัวเจ้ากับคราบดินบนเกราะบอกข้าว่าเจ้าเห็นโลกมาไม่น้อยแล้ว ถึงเวลาหาม้าคู่ใจให้เจ้าสักตัว\n\nเมื่อฝึกช่วงสุดท้ายกับข้าจนจบ Katie จะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นเจ้าจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ เหมือนครั้งก่อน\n\nมาคุยกับข้าเมื่อมีเงินพอ แล้วข้าจะสอนทุกอย่างที่รู้เรื่องการขี่ม้าหุ้มเกราะให้เจ้า" },
        title = { "17:1951865332:1269485614", "ว่องไวปานสายลม" },
    },
    [99213] = { -- An Epic Ride
        objective = { "60:1854042006:1924370206", "สำรวจม้าขี่หุ้มเกราะเพื่อเลือกพาหนะระดับมหากาพย์ของเจ้า" },
        description = { "11:927657569:725753248 N 434:1854694704:1202614511", "สวัสดี {name}! ดีใจจริง ๆ ที่เจ้ากลับมาหาพวกเรา\n\nดูเหมือนเจ้าจะมีประสบการณ์พอจะขี่ม้าที่เร็วและดุที่สุดของเราแล้ว เจ้าจะหาคู่หูร่วมทางที่ไว้ใจได้กว่านี้ไม่ได้แล้ว\n\nอาจเลือกยากสักหน่อย เพราะทุกตัวดีเยี่ยมและฝึกมาให้สงบนิ่งแม้ตกอยู่ในอันตราย บางตัวอาจจำเจ้าได้จากครั้งก่อนที่เจ้ามาที่นี่ด้วยซ้ำ\n\nไปดูม้าหุ้มเกราะแต่ละตัวแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "12:1160301614:1027353324", "ยอดพาหนะคู่ใจ" },
    },
    [99366] = { -- An Epic Ride
        description = { "11:927657569:725753248 N 434:1854694704:1202614511", "สวัสดี {name}! ดีใจจริง ๆ ที่เจ้ากลับมาหาพวกเรา\n\nดูเหมือนเจ้าจะมีประสบการณ์พอจะขี่ม้าที่เร็วและดุที่สุดของเราแล้ว เจ้าจะหาคู่หูร่วมทางที่ไว้ใจได้กว่านี้ไม่ได้แล้ว\n\nอาจเลือกยากสักหน่อย เพราะทุกตัวดีเยี่ยมและฝึกมาให้สงบนิ่งแม้ตกอยู่ในอันตราย บางตัวอาจจำเจ้าได้จากครั้งก่อนที่เจ้ามาที่นี่ด้วยซ้ำ\n\nไปดูม้าหุ้มเกราะแต่ละตัวแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "12:1160301614:1027353324", "ยอดพาหนะคู่ใจ" },
    },
    [99367] = { -- An Epic Ride
        description = { "11:927657569:725753248 N 434:1854694704:1202614511", "สวัสดี {name}! ดีใจจริง ๆ ที่เจ้ากลับมาหาพวกเรา\n\nดูเหมือนเจ้าจะมีประสบการณ์พอจะขี่ม้าที่เร็วและดุที่สุดของเราแล้ว เจ้าจะหาคู่หูร่วมทางที่ไว้ใจได้กว่านี้ไม่ได้แล้ว\n\nอาจเลือกยากสักหน่อย เพราะทุกตัวดีเยี่ยมและฝึกมาให้สงบนิ่งแม้ตกอยู่ในอันตราย บางตัวอาจจำเจ้าได้จากครั้งก่อนที่เจ้ามาที่นี่ด้วยซ้ำ\n\nไปดูม้าหุ้มเกราะแต่ละตัวแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "12:1160301614:1027353324", "ยอดพาหนะคู่ใจ" },
    },
    [97203] = { -- Learning to Ride
        description = { "11:927657569:725753248 C 483:196611570:1425210523", "สวัสดี {class} ดูเหมือนเจ้าจะผ่านการผจญภัยมามากพอแล้ว ข้าสอนเจ้าขี่ม้าโครงกระดูกได้ โดยมีค่าเรียน\n\nเมื่อฝึกกับข้าแล้ว Zachariah จะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ โลกนี้มีสัตว์ขี่หลายชนิด แต่ละชนิดต้องใช้ทักษะต่างกัน เจ้าต้องหาครูฝึกให้ตรงกับสัตว์ที่อยากขี่\n\nมาคุยกับข้าเมื่อมีเงินพอ แล้วข้าจะสอนเจ้าขี่ม้าโครงกระดูก" },
        title = { "16:138327183:488009726", "หัดขี่สัตว์" },
        objective = { "52:51316209:1318497052", "เรียนทักษะ Apprentice Riding จาก Velma Warnam" },
        completion = { "10:334093107:1878068334 C 209:716445946:2118944450", "อ้อ สวัสดี {class} ข้ายินดีที่เห็นเจ้าฝึกกับ Velma จนจบแล้ว\n\nนางมีวิธีเข้าหาม้าพวกนี้แบบที่น้อยคนนักจะทำได้ ถ้าฝึกกับนางมา เจ้าก็ขี่อาชาตัวไหนของเราที่ Brill ได้สบาย" },
        steps = { { "24:1857109559:1009967372", "เรียนทักษะขี่สัตว์ขั้นฝึกหัด (Apprentice Riding)" } },
    },
    [99208] = { -- Swift as the Wind
        description = { "379:3756943:1587054052", "เจ้ากลับมาแล้ว ดี ถึงเวลาฝึกขี่พาหนะของชาว Forsaken ตัวจริงให้ชำนาญแล้ว ม้าศึกโครงกระดูก\n\nเมื่อฝึกช่วงสุดท้ายกับข้าจนจบ Zachariah จะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นเจ้าจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ\n\nมาคุยกับข้าเมื่อมีเงินพอ แล้วข้าจะสอนเจ้าขี่ม้าศึกโครงกระดูก" },
        title = { "17:1951865332:1269485614", "ว่องไวปานสายลม" },
        objective = { "52:1882636046:1789529634", "เรียนทักษะ Journeyman Riding จาก Velma Warnam" },
    },
    [99211] = { -- An Epic Ride
        description = { "11:927657569:725753248 N 439:532120743:470224727", "สวัสดี {name} ข้าไม่คิดว่าเจ้าจะกลับมาที่คอกสัตว์เล็ก ๆ ของข้าเร็วขนาดนี้\n\nเจ้าผ่านการเดินทางมาไม่น้อยเลยสินะ ข้าว่าพอเดาได้ว่าอะไรพาเจ้ามาที่นี่วันนี้\n\nตอนนี้เจ้ามีทั้งพลัง ประสบการณ์ และฝีมือพอจะขี่ม้าศึกที่ว่องไวและน่ากลัวที่สุดของเราแล้ว อสูรหุ้มเกราะพวกนี้จะพาเจ้าฝ่าทุกบททดสอบ แม้ต้องผ่านประตูแห่งความตาย\n\nไปดูม้าศึกอันเดดหุ้มเกราะแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "12:1160301614:1027353324", "ยอดพาหนะคู่ใจ" },
    },
    [96994] = { -- Your First Riding Wolf
        description = { "9:860935253:1249669357 C 455:1363252278:1783251942", "Lok'tar {class} มาผูกสายสัมพันธ์กับหมาป่าตัวแรกของเจ้ารึ? ดี\n\nไม่มีสายสัมพันธ์ใดแน่นแฟ้นไปกว่าสายสัมพันธ์ของออร์คกับหมาป่าของเขา มันเป็นทั้งคู่หูและสหายตลอดชีวิต\n\nเราเลือกกันด้วยสิ่งที่ลึกกว่าความอยากอวด ออร์คกับหมาป่าแต่ละคู่มีสายสัมพันธ์พิเศษที่เงินซื้อไม่ได้\n\nพวกมันจะเลือกเจ้าเหมือนที่เจ้าเลือกพวกมัน เจ้าจะเข้าใจเมื่อได้พบพวกมันเอง\n\nไปดูว่าหมาป่าตัวไหนถูกชะตากับเจ้า แล้วกลับมาหาข้าเมื่อได้คำตอบ", variants = { { "584:1140397140:1248657145", "<Ogunaro หรี่ตาลงขณะเจ้าเดินเข้าไปหา>\n\nLok'tar วอร์ล็อก ข้ายอมรับว่าประหลาดใจที่เห็นคนที่มี... พรสวรรค์แบบเจ้าอยู่ที่นี่\n\nหากเจ้ามาหาหมาป่าสำหรับขี่ ก็มาถูกที่แล้ว แต่จงรู้ไว้ว่าการขี่และผูกมิตรกับหมาป่าต่างจากการอัญเชิญอาชาเฟลอย่างที่เจ้าคุ้นเคย\n\nออร์คกับหมาป่าผูกพันกันด้วยสิ่งที่ลึกกว่าความอยากอวด ออร์คกับหมาป่าแต่ละคู่มีสายสัมพันธ์พิเศษที่มีค่ากว่าการซื้อขาย\n\nถ้าเจ้ามาเพื่อผูกสายสัมพันธ์กับหมาป่า ข้าแนะนำให้เดินไปดูทีละตัว หากรู้สึกถูกชะตากับตัวไหนก็กลับมาหาข้า" } } },
        title = { "22:1879843884:1253422874", "หมาป่าสำหรับขี่ตัวแรกของเจ้า" },
        objective = { "53:2134678028:157144480", "สำรวจหมาป่าสำหรับขี่เพื่อเลือกสัตว์ขี่ตัวแรกของเจ้า" },
        completion = { "158:787809593:1836854668 C 138:1905523234:1339406320", "<Ogunaro ส่งเสียงฮึมอย่างพอใจ>\nดูเหมือนเจ้าจะพบคู่หูแล้ว ข้าดีใจที่ในที่สุดมันก็ได้พบผู้ขี่ของมัน\nดูแลมันให้ดีนะ {class} แล้วมันจะดูแลเจ้าตอบ อย่าลืมมิตรภาพของเจ้าทั้งสอง\nขอให้เจ้าทั้งคู่โชคดีในการผจญภัย จงออกไปคว้าชัยชนะ!" },
        progress = { "48:835139696:1353524687 R 227:941566629:1061447011", "ดูพวกหมาป่าดีแล้วหรือยัง? สายสัมพันธ์ระหว่างชาว{race}กับหมาป่านั้นเก่าแก่ยิ่งกว่ากาลเวลา มันสืบต่อข้ามรุ่น และบัดนี้ยังข้ามโลกมาด้วย\nข้าเคยได้ยินด้วยซ้ำว่าผู้ขี่บางคนรู้ชื่อหมาป่าของตนทันทีที่เกิดสายสัมพันธ์\nเจ้าจะหาคู่หูที่ดุดันและซื่อสัตย์กว่านี้ไม่ได้อีกแล้ว" },
        steps = { { "17:453769675:717954403", "หมาป่าสำหรับขี่สีน้ำตาล" }, { "16:1187997955:166024746", "ไดร์วูล์ฟสำหรับขี่" }, { "18:1901651533:1924720097", "หมาป่าไพรสำหรับขี่" }, { "17:1926277654:1852951777", "หมาป่าสำหรับขี่สีดำ" } },
    },
    [97200] = { -- Learning to Ride
        description = { "12:1943510513:1232487388 C 474:360422498:1253016570", "เฮ้ ยินดีต้อนรับ {class}! เจ้าผ่านการผจญภัยมามากพอให้ข้าสอนขี่แร็ปเตอร์ของเราได้แล้ว มีค่าเรียนตามธรรมเนียมนะ\n\nเมื่อฝึกกับข้าแล้ว Zjolnir จะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ โลกนี้มีสัตว์ขี่หลายชนิด แต่ละชนิดต้องใช้ทักษะต่างกัน เจ้าต้องหาครูฝึกให้ตรงกับสัตว์ที่อยากขี่\n\nมาคุยกับข้าเมื่อมีทองพอ แล้วข้าจะสอนเจ้าขี่แร็ปเตอร์" },
        title = { "16:138327183:488009726", "หัดขี่สัตว์" },
        objective = { "46:1846018187:376200942", "เรียนทักษะ Apprentice Riding จาก Xar'ti" },
        completion = { "20:62727115:934352241 C 235:1462710283:1817882349", "ขอให้เหล่าวิญญาณอยู่เคียงข้างเจ้า {class} ข้าดีใจที่เจ้าฝึกกับ Xar'Ti จนจบแล้ว\n\nนางชำนาญเรื่องแร็ปเตอร์พวกนี้ และสอนให้ผู้ฝึกเข้าใจสายสัมพันธ์ระหว่างแร็ปเตอร์กับคนขี่ได้ดี การขี่สัตว์งามสง่าพวกนี้ต้องใจกล้าหน่อยล่ะ" },
        steps = { { "24:1857109559:1009967372", "เรียนทักษะขี่สัตว์ขั้นฝึกหัด (Apprentice Riding)" } },
    },
    [99201] = { -- Swift as the Wind
        objective = { "46:680536964:989663742", "เรียนทักษะขี่พาหนะระดับ Journeyman จาก Xar'ti" },
        description = { "17:1793796706:266785535 C 252:734951663:677705791", "เฮ้ ยินดีต้อนรับกลับมา {class}!\n\nเมื่อเจ้าฝึกขี่ระดับ Journeyman กับข้าแล้ว Zjolnir จะมอบสัตว์ขี่หุ้มเกราะให้เจ้าฟรีหนึ่งตัว หลังจากนั้นจะซื้อสัตว์ขี่หุ้มเกราะเพิ่มก็ได้\n\nมาคุยกับข้าเมื่อมีทองพอ แล้วข้าจะสอนเจ้าขี่แร็ปเตอร์ให้ชำนาญ" },
        title = { "17:1951865332:1269485614", "ว่องไวปานสายลม" },
    },
    [99204] = { -- Swift as the Wind
        objective = { "46:428014185:148501121", "เรียนทักษะขี่พาหนะระดับ Journeyman จาก Kildar" },
        description = { "322:1038795418:2084141495", "เจ้ากลับมาแล้ว ดี ถึงเวลาฝึกขั้นต่อไป\n\nเมื่อฝึกช่วงสุดท้ายกับข้าจนจบ Ogunaro จะมอบสัตว์ขี่ให้เจ้าฟรีหนึ่งตัว หลังจากนั้นเจ้าจะซื้อเพิ่มอีกกี่ตัวก็ได้ตามใจ เหมือนครั้งก่อน\n\nมาคุยกับข้าเมื่อมีทองพอ แล้วข้าจะฝึกเจ้าให้จบ" },
        title = { "17:1951865332:1269485614", "ว่องไวปานสายลม" },
    },
    [99215] = { -- An Epic Ride
        description = { "9:1871511191:798375331 N 456:769440730:302988457", "Lok-tar {name} ดีใจที่ได้พบเจ้าอีกครั้ง\n\nอย่างที่เจ้ารู้ ไม่มีสายสัมพันธ์ใดแน่นแฟ้นไปกว่าสายสัมพันธ์ของออร์คกับหมาป่าของเขา ตอนนี้เจ้ามีประสบการณ์พอจะควบคุมและขี่หมาป่าที่ดุและเร็วที่สุดของเราแล้ว\n\nหมาป่าฝีดีหลายตัวจำเจ้าได้จากครั้งก่อนที่เจ้ามาที่นี่ พวกมันโตขึ้นตั้งแต่พบเจ้าครั้งแรก ทั้งแข็งแรงขึ้น เร็วขึ้น และกล้าขึ้น เหมือนเจ้านั่นแหละ\n\nไปดูว่าหมาป่าหุ้มเกราะตัวไหนถูกชะตากับเจ้า แล้วกลับมาหาข้าเมื่อได้คำตอบ" },
        title = { "12:1160301614:1027353324", "ยอดพาหนะคู่ใจ" },
    },
    [99218] = { -- An Epic Ride
        description = { "4:1179250186:157200556 N 482:138374942:382717255", "เฮ้ {name}! วันนี้เป็นวันสำคัญของเจ้าสินะ ดูเหมือนเจ้าพร้อมจับบังเหียนแร็ปเตอร์ที่เร็วและดุที่สุดของเราแล้ว\n\nพอได้ขี่แร็ปเตอร์แล้ว เจ้าก็รู้ว่าพวกมันทั้งฉลาดและดุร้ายแค่ไหน ข้าว่าตอนนี้เจ้าพร้อมขี่แร็ปเตอร์ตัวจริงแล้ว แร็ปเตอร์หุ้มเกราะน่ะ\n\nเจ้ามีเรื่องสำคัญให้เลือก เจ้าและแร็ปเตอร์ของเจ้าจะเดินทางไปทั่วโลกด้วยกัน และมันก็ต้องเลือกเจ้าด้วยเหมือนกัน\n\nไปดูพวกมันแล้วกลับมาหาข้าเมื่อเลือกได้" },
        title = { "12:1160301614:1027353324", "ยอดพาหนะคู่ใจ" },
    },
    [96145] = { -- Past Wing and Claw
        description = { "375:1251361895:1795139838", "ระวังไว้ นักเดินทาง! วิหาร Shrine of Aviana อยู่ข้างหน้า แต่ตอนนี้ฮาร์ปีเผ่า Wormwing ยึดพื้นที่แถบนั้นไว้แล้ว\n\nข้าเป็นผู้ศรัทธาใน Aviana เช่นเดียวกับคนในตระกูล Highfeather แต่พวก Wormwing ไม่ได้ภักดีต่อนางเช่นเรา พวกมันเป็นภัยต่อทุกคนที่ผ่านอาณาเขตของมัน\n\nหากเจ้าฝ่าพวกมันไปได้ ญาติของข้าชื่อ Phoebe Highfeather กำลังช่วยคุ้มกันวิหารอยู่" },
        title = { "18:1119957710:1838991933", "ฝ่าปีกและกรงเล็บ" },
        objective = { "48:305272141:563816620", "ไปพบ Phoebe Highfeather ที่ Shrine of Aviana" },
    },
    [95982] = { -- Not My Circus
        description = { "486:851200625:1951317107", "คนชอบเอาเพื่อนขนฟูมาทิ้งไว้ที่นี่ เหมือนคิดว่าข้ารู้วิธีดูแล แล้วพอกลับมาเจอม้า หมาป่า หรืออะไรก็ตามที่ฝากไว้ตายหรือหนีไป ก็โทษข้า เห็นข้าเป็นคนทำการกุศลหรือไง?\n\nเจ้าดูจะรู้เรื่องอาหารสัตว์ ช่วยทำอะไรให้ข้าสักหน่อยได้ไหม จะได้คุมเจ้าพวกนี้อยู่\n\nถ้าทำเองไม่ได้ อาจมีคนขายให้ รีบด้วยล่ะ ขืนปล่อยให้สัตว์หิววิ่งแตกตื่นกันทั้งฝูง ข้าคงงานเข้าแน่" },
        title = { "13:775636182:873161052", "ข้าไม่ได้เปิดคณะละครสัตว์" },
        objective = { "6:1273960851:929420321 W1 60:745684118:290772057", "นำ Briny Seafood Stew {world1} ชามไปให้ Jasper Geartoggle ที่ Powderfuse Port" },
        completion = { "94:22239361:1772482320", "โห เจ้านี่ทำของที่หมากินได้เก่งจริง ๆ อย่าถือสาเลยนะ ขอบใจที่ช่วย สหาย" },
        progress = { "59:1712751940:129622266", "ได้ของกินมาหรือยัง? พวกหมาป่าเริ่มหิวแล้ว..." },
        required = { [274971] = { "18:1207393364:1786650312", "สตูว์ทะเลรสเค็ม" } },
        steps = { { "18:1207393364:1786650312", "สตูว์ทะเลรสเค็ม" } },
    },
    [96083] = { -- Clerical Quarantine
        description = { "261:1789082805:571047237", "ตอนนี้เจ้าทำทุกอย่างที่ช่วยได้ที่นี่แล้ว\n\nถ้าอยากช่วยต่อ ขึ้นเนินไปที่โบสถ์น้อย เป็นอาคารหลังเล็กที่อยู่ด้านนอกโบสถ์ใหญ่\n\nSister Rowland กำลังดูแลทหารที่ถูกกักตัวอยู่ที่นั่น พวกเขาป่วยด้วยโรคที่ยังไม่ทราบสาเหตุ" },
        title = { "19:974750380:2118510749", "กักโรคที่โบสถ์น้อย" },
        objective = { "55:677948503:2078626913", "คุยกับ Sister Rowland ที่โบสถ์น้อยใน Farholde Keep" },
        completion = { "120:1544623720:974496114", "อ้อ บาทหลวง Lowley ส่งเจ้ามาหรือ? ไม่น่าเชื่อว่าเขาจะปลีกคนมาช่วยได้ แสดงว่าเจ้าคงทำหน้าที่ได้ดี" },
    },
    [95986] = { -- King of the Wild Plains
        description = { "20:1804653063:217290830 N 339:1794075229:705234013", "นกหวีดเสร็จแล้ว {name}\n\nเอาไปที่ยอดเนินที่พวกสิงโตอยู่ น่าจะอยู่ทางเหนือของที่นี่เอง\n\nไปถึงแล้วก็เป่านกหวีด เจ้าสิงโตกินคนคงโผล่มา ข้าจะบอกว่าอย่ากลับมาถ้ายังฆ่ามันไม่ได้ แต่ถึงตอนนั้นเจ้าก็คงตายไปแล้วอยู่ดี\n\nเอาล่ะ ไปได้ มาดูกันว่าเจ้าจะทำได้ดีกว่าสหายโครงกระดูกของเราหรือเปล่า" },
        title = { "23:1236935095:1508155163", "ราชาแห่งทุ่งป่า" },
        objective = { "146:1133564745:290201467", "ใช้ Tallstrider Call ล่อจ่าฝูงสิงโต ฆ่ามันแล้วนำหนังไปให้ Watcher Cornelius ที่ Terral's Watch" },
        completion = { "244:725038708:850772993", "อ้อ อย่างนั้นเอง! ถ้างั้นก็ทำได้ดีมาก\nให้เข้าใจตรงกันนะ... เราตกลงกันว่าเรื่องนี้ไม่ต้องถึงหู Demar ใช่ไหม? ข้าว่าเราจัดการกันเองได้ดีอยู่แล้ว\nเขาส่งข้ามาประจำอยู่ไกลถึงนี่ ข้าไม่อยากให้เขาหันมาสนใจข้าเป็นพิเศษอีก" },
        progress = { "52:871687698:705740520", "มาคุยกับข้าแบบนี้ แปลว่าสิงโตตายแล้วใช่ไหม?" },
        required = { [281052] = { "14:1303281669:643637710", "หนังของ Ombassa" }, [271779] = { "16:673113683:1968674037", "เครื่องส่งเสียงเรียก Tallstrider" } },
        steps = { { "14:1303281669:643637710", "หนังของ Ombassa" }, { "16:673113683:1968674037", "เครื่องส่งเสียงเรียก Tallstrider" } },
    },
    [96026] = { -- Step Two: More Rock
        description = { "191:859963169:337834792", "หินนี่ดี ต้องแต่งขั้นสุดท้าย ใช้หินเพิ่ม\n\nมีแต่หินที่ทำให้หินแกร่งขึ้น หินมันเป็นแบบนี้\n\nข้าเห็นพวกตัวจิ๋วทำหินหนักพิเศษ เอาหินหนักมาให้ข้า แล้วข้าจะทำอาวุธ" },
        title = { "19:1803659282:457910721", "ขั้นที่สอง หินเพิ่ม" },
        objective = { "8:579959443:2019289147 W1 42:1728159886:253823956", "นำ Heavy Weightstone {world1} ก้อนไปให้ Hamur ที่ Bolder'ok" },
        completion = { "177:101679386:1323392793", "พวกนี้หนักมาก! ทีนี้ข้าเอาหินหนักทุบหินดีได้แล้ว!\n<Hamur บดหินที่เจ้ารวบรวมมาจนเป็นผง เหลือเพียงหินถ่วงน้ำหนัก>\nพวกนี้เอาไว้ทุบได้ดี เอ้า ให้เจ้า" },
        progress = { "72:480442203:371344125", "ช่างตัวจิ๋วทำหินให้กลายเป็นหินหนัก ฉลาดจัง เจ้าไปซื้อจากพวกนั้นดูไหม?" },
        required = { [3241] = { "17:2095404961:692230964", "หินถ่วงน้ำหนักแบบหนัก" } },
        steps = { { "17:2095404961:692230964", "หินถ่วงน้ำหนักแบบหนัก" } },
    },
    [96085] = { -- Upstream Contamination
        description = { "442:471525228:1101632749", "สิ่งเจือปนในตัวอย่างนี้ดูเหมือนมาจากสิ่งมีชีวิต ดูไม่ค่อยเหมือนของเสีย แต่เป็นพิษแน่นอน\n\nข้าไม่เชี่ยวชาญเรื่องสัตว์ป่า แต่เดาว่าคงมีอะไรสักอย่างอยู่ต้นน้ำที่ทำให้น้ำปนเปื้อน อาจเป็นสัตว์ หรืออย่างน้อยก็เป็นสิ่งมีชีวิตสักชนิด\n\nเลียบแม่น้ำขึ้นเหนือไปให้ไกลที่สุด ลองหาดูว่าอะไรเป็นต้นเหตุ ถ้าเป็นสัตว์ก็ต้องกำจัดมัน เพื่อความปลอดภัยของทุกคนใน Farholde" },
        title = { "22:1972636464:1004281220", "ต้นน้ำปนเปื้อน" },
        objective = { "147:1250257562:329041660", "ตามหาและกำจัดสิ่งมีชีวิตที่ทำให้น้ำดื่มปนเปื้อน แล้วกลับไปหา Sister Rowland ที่โบสถ์น้อยใน Farholde Keep" },
        completion = { "333:1719459357:1273551020", "เต่ายักษ์เน่า ๆ ตัวหนึ่งหรือ? แล้วที่พวกเราดื่มเข้าไปก็เป็น... ข้าไม่อยากคิดเลยว่าคืออะไร\n\nมิน่าทหารพวกนี้ถึงป่วยหนักกันขนาดนั้น\n\nการสืบสวนครั้งนี้ประหลาดเอาเรื่อง แต่เจ้าทำหน้าที่ด้วยความรับผิดชอบและกล้าหาญ ข้าขอชมเชยเจ้า\n\nไม่ว่าพวกเขาจะรู้หรือไม่ ทุกคนใน Farholde ปลอดภัยก็เพราะเจ้า" },
        steps = { { "22:505204926:1218052038", "กำจัดสิ่งมีชีวิตที่ทำให้น้ำปนเปื้อน" } },
    },
    [95991] = { -- WANTED: Ghostmaw
        description = { "495:1660232515:36596602", "ขนม้าผ่านแถบนี้ก็อันตรายพออยู่แล้ว ยังมีข่าวว่าโครโคลิสก์ผีลึกลับกำลังงาบม้าแสนรักของข้าอีก! เขาว่าตัวนี้ใหญ่กว่าโครโคลิสก์ทั่วไปอย่างน้อยสามเท่า แถมดุเป็นสองเท่า!\n\nข้าไม่ใช่คนชอบเสี่ยง ข้าจะไม่เอาม้าของข้าไปเสี่ยงจนกว่าจะมีคนกำจัดเจ้าสัตว์ประหลาดไร้ประโยชน์ตัวนี้ ถ้าใครเจอมันตามแม่น้ำ เอาเขี้ยวมันมาให้ข้า ข้าจะได้รู้ว่าเดินทางได้ปลอดภัยอีกครั้ง ระหว่างนี้ข้าจะอยู่กับที่!\n\n— Wheatley" },
        title = { "16:322728212:1760539747", "ประกาศจับ Ghostmaw" },
        objective = { "51:204716441:1031359763", "นำ Ghostmaw's Fang ไปให้ Wheatley ที่ Farholde Keep" },
        completion = { "125:1066040765:24980713", "ตายจริง! ดูขนาดเจ้าตัวนั้นสิ!\nคราวนี้มันคงไม่มากินม้าเล็กอีกแล้วแน่ ๆ ขอบใจมากเลย สหาย!" },
        progress = { "75:177487621:1444099744", "เจ้าเห็นมันชัด ๆ ไหม? ดูเหมือนมันจะซุ่มล่าอยู่ตามแม่น้ำทั่วแถบนี้เลย!" },
        required = { [271828] = { "15:984250107:202631672", "เขี้ยวของ Ghostmaw" } },
        steps = { { "15:984250107:202631672", "เขี้ยวของ Ghostmaw" } },
    },
    [96078] = { -- A Tale Spun Around the Fire
        description = { "N 501:1064262983:79050130", "{name} พวกเราชาว Darkspear สืบทอดธรรมเนียมมากมายผ่านการเล่าปากต่อปาก เราส่งต่อตำนานอย่างเรื่องนี้ให้คนรุ่นถัดไป ใช้สอนบทเรียนและเล่าเป็นอุทาหรณ์ให้ลูกหลาน\n\nต้องนำข้อความสลักนี้ไปให้ผู้นำทางจิตวิญญาณของเรา Master Gadrin ที่ Sen'jin Village เขาเป็นหนึ่งในชาว Darkspear ที่ปราดเปรื่องที่สุด และคงอยากฟังความจริงของเรื่องนี้\n\nข้าเตรียมสำเนาเรื่องนี้ไว้ให้เจ้าอีกชุดด้วย หากทำหาย ข้ายินดีทำให้ใหม่ คิดค่าทำเล็กน้อย", variants = { { "N 539:1427317678:44662556", "{name} เจ้าก็รู้ว่าเผ่าของเรารักษาธรรมเนียมไว้ด้วยการเล่าปากต่อปาก และส่งต่อตำนานเช่นนี้ให้คนรุ่นถัดไป เจ้าเองคงได้เรียนรู้และฟังเรื่องเล่าที่เป็นอุทาหรณ์มาตั้งแต่เด็ก\n\nต้องนำข้อความสลักนี้ไปให้ผู้นำทางจิตวิญญาณของเรา Master Gadrin ที่ Sen'jin Village ข้ามั่นใจว่าเขาจะดีใจที่ได้พบเจ้าอีก และคงอยากฟังความจริงของเรื่องนี้\n\nข้าเตรียมสำเนาเรื่องนี้ไว้ให้เจ้าอีกชุดด้วย หากทำหาย ข้ายินดีทำให้ใหม่โดยคิดค่าทำเล็กน้อย" } } },
        title = { "27:1474986838:209108716", "เรื่องเล่ารอบกองไฟ" },
        objective = { "72:69369428:1480287187", "นำข้อความสลักจากแผ่นศิลาไปให้ Master Gadrin ที่ Sen'jin Village ใน Durotar" },
        completion = { "496:1751331766:1421900517", "<Master Gadrin ตั้งใจฟังขณะที่เจ้าเล่าเรื่องการเดินทางและที่มาของสำเนาลายสลักบนศิลาจารึก I'lalai>\nดีแล้วที่ Kin'Weelay ส่งเจ้ามาที่นี่ ข้าดีใจที่เขาตั้งใจค้นหาและรักษามรดกของบรรพชนที่สูญหายไปตลอดหลายศตวรรษ หากมองประวัติศาสตร์ทั้งหมดแล้ว พวกเรา Darkspear เพิ่งแยกจาก Gurubashi มาได้ไม่นานนักหรอก\nเอาล่ะ Kin'Weelay ฝากให้ข้ามอบสิ่งนี้แก่เจ้า เพื่อตอบแทนสิ่งที่เจ้าทำมาทั้งวัน" },
    },
    [93016] = { -- A Brief History Lesson
        title = { "22:1883131228:380242500", "บทเรียนประวัติศาสตร์สั้น ๆ" },
        description = { "263:963318894:1035470999", "ยกโทษให้ข้าด้วยที่ส่งเจ้าไปทำงานตั้งหลายอย่างโดยไม่อธิบายที่มาที่ไป ข้าไม่ทันคิดว่ามันอาจดูน่าสงสัยเพียงใด ยิ่งตอนนี้ท้องฟ้าเปลี่ยนไปจนน่าตกใจด้วยแล้ว\n\nข้ายินดีตอบคำถามของเจ้า" },
        objective = { "92:452377940:2133738758", "คุยกับ Mordent Evenshade ใน Shen'dralas เพื่อสอบถามเรื่องผลึกที่เจ้าซ่อม" },
        completion = { "68:1608978062:865158492 N 387:599674919:414732374", "ข้าหวังว่าคำอธิบายจะช่วยคลายความกังวลของเจ้าได้บ้าง {name} อย่างที่เห็น ข้าไม่ได้คิดร้าย ที่อธิบายเรื่องทั้งหมดให้ชัดตั้งแต่แรกไม่ได้ ก็เพราะมัวแต่ตื่นเต้นว่าจะได้เห็นผลึกกลับมาส่องแสงอีกครั้ง\nข้าตื่นเต้นที่จะได้ไปเยือนวิหารแห่ง Shen'dralas อีก แต่คงต้องใช้เวลาสักพักกว่าจะรวบรวมความกล้าไปคุยกับพวก Shen'dralar ที่นั่น\nส่วนเจ้านั้น..." },
        steps = { { "28:1696722051:532443770", "คุยกับ Mordent Evenshade" } },
    },
    [93601] = { -- Passing the Blame
        title = { "17:1073323819:62307805", "โยนความผิด" },
        description = { "220:900641874:1820347640", "ถ้าอยากเอาของขวัญของนางคืน ก็เดินขึ้นเหนือไปที่ Valley of Bones\n\nของถูกขโมยไป พวกควิลโบร์เป็นคนทำ ข้าเห็นกับลูกตาของข้าเองทั้งสองข้าง\n\nเพราะพวกมัน สวนนี้จึงต้องตาย\n\nอย่าให้อภัยพวกมัน" },
        objective = { "63:836450369:1853904976", "ตามหาควิลบอร์คนสำคัญที่ Bristleback Retreat" },
    },
    [93451] = { -- Phantasmal Problems
        title = { "19:41011997:809322715", "ปัญหาของวิญญาณ" },
        description = { "503:900768753:1459196636", "อา เจ้าดูเป็นคนรู้เรื่องรู้ราว น่าจะมีหัวคิดกว่าเจ้าทึ่มคนก่อนที่ผ่านมาที่นี่ ข้ามีเรื่องเล็กน้อยจะขอให้ช่วย\n\nเรื่องมีอยู่ว่า ผลงานตีดาบชิ้นเอกของข้ายังทำไม่เสร็จก่อนข้าจะตาย ข้าต้องหาใครสักคนช่วยนำมันเข้ามาในโลกวิญญาณ จะได้ทำให้เสร็จ คนก่อนมีน้ำใจช่วยข้า และเขาก็ทำสำเร็จ!\n\nแต่ตอนนี้ข้ามีปัญหาใหม่ นักผจญภัยคนนั้นเอาดาบกลับมาคืนข้าไม่ได้แล้ว ทั้งหมดเป็นความผิดของเขาเอง" },
    },
    [93341] = { -- Forlorn Gardens
        title = { "15:557532881:1569919807", "สวนที่ถูกทอดทิ้ง" },
        description = { "423:1665361248:1367961671", "ในฐานะผู้ดูแลสวน ข้ามีหน้าที่ดูแลให้สวนแห่งนี้งอกงาม\n\nข้ารู้ว่าสักวันคงดูแลต่อไม่ไหว จึงลงมนตร์ใส่สร้อยคอที่ลูกสาวให้มา เพื่อให้ต้นกล้ารุ่นใหม่กลายเป็นทรีแอนต์และคอยดูแลสวนแทนข้า ข้าวางสร้อยไว้บนแท่นลงมนตร์ภายในศาลเล็ก ๆ\n\nข้าฝากสวนไว้กับผู้ดูแลที่ไว้ใจได้ ข้าต้องรู้ให้ได้ว่าเกิดอะไรขึ้น" },
        objective = { "97:1883494942:1067345846", "สำรวจ Forlorn Gardens ใกล้ Shen'dralas แล้วกลับไปหา Mithera ที่วิหารใกล้ ๆ" },
        completion = { "340:1517410714:1651854188 N 125:55485460:1898202654", "<Mithera ฟังเจ้าเล่าเรื่องที่เกิดขึ้นอย่างเงียบ ๆ>\n\nแท่นว่างเปล่าหรือ? สร้อยคอของข้า... หายไปแล้วหรือ?\n\n<สีหน้าของนางเศร้าลงอย่างเห็นได้ชัด>\n\nข้าน่าจะคิดไว้แล้ว พวกควิลบอร์กับเซนทอร์เพิ่งเข้ามาทำลายดินแดนแถบนี้ได้ไม่นาน แต่สร้างความเสียหายไว้มากจนประเมินไม่ได้\n\n{name} ต่อให้เวทมนตร์ในสร้อยจะหมดไป ข้าก็ยังหวังว่าจะได้สร้อยคืน เจ้าพอจะช่วยข้าได้ไหม?" },
        steps = { { "17:75647554:591472267", "ตรวจแท่น" } },
    },
    [93568] = { -- Partially Digested Collar
        title = { "25:1214349374:1623293454", "ปลอกคอที่ถูกย่อยไปบางส่วน" },
        description = { "496:1219311093:1480576527", "<เจ้าถือปลอกคอเปื้อนคราบที่เก็บมาจากท้องของสัตว์ที่ถูกฆ่า มันทำจากหนังคุณภาพดีและเห็นชัดว่าเย็บอย่างประณีต\n\nป้ายห้อยอยู่กับหัวเข็มขัดที่ผุกร่อน เจ้าปาดคราบออกจนเห็นอักษร Thalassian ลายเส้นประดิษฐ์จนอ่านไม่ออก แม้แต่คนที่รู้ภาษานี้ก็อาจอ่านไม่ออก\n\nตอนนี้เจ้าต้องเลือก จะทิ้งมันไปแล้วใช้ชีวิตต่อ หรือจะลองทำสิ่งที่แทบเป็นไปไม่ได้เพื่อให้เจ้าของได้คลายเรื่องค้างคาใจ?>" },
        objective = { "133:94586631:834073914", "นำ Partially Digested Collar ไปให้คนที่รู้เรื่องปลอกคอนี้ น่าจะหาได้ใน Shen'dralas หรือบริเวณใกล้เคียงใน Desolace" },
        completion = { "502:1959405999:562062481", "ปลอกคอนี้เป็นของ Dahlia เพื่อนรักและแมวตัวโปรดของข้า Dahlia... ข้าตั้งชื่อไม่เก่งเอาเสียเลย แต่ชื่อก็เหมาะกับนางนะ นางเหมือนดอกไม้เบ่งบานที่เติมสีสันให้ชีวิตข้า\nที่มาของชื่อก็ไม่ได้ตื่นเต้นอะไรนัก ข้าเดินผ่านดอกดาเลียในสวน แล้วเจ้าลูกแมวตัวน้อยก็กระโจนใส่ข้า! ทำท่าดุซะน่ารักเชียว นางเดินตามข้ากลับมาถึงวิหาร แล้วก็... อยู่ด้วยกันตั้งแต่นั้นมา!\nเจ้าไม่ต้องอยู่รอข้ารำลึกความหลังหรอก เอ้านี่ ของตอบแทนที่เจ้าลำบาก ขอบใจที่ทำให้ความทรงจำเก่า ๆ กลับมา" },
        progress = { "138:776673185:1835499288", "<Liranne รับปลอกคอไปตรวจดู นางประคองป้ายโลหะไว้ในมืออีกข้างอย่างทะนุถนอม แล้วเผยรอยยิ้มเพียงชั่วครู่เมื่ออ่านข้อความบนนั้น>" },
        required = { [259461] = { "25:1214349374:1623293454", "ปลอกคอที่ถูกย่อยไปบางส่วน" } },
        steps = { { "25:1214349374:1623293454", "ปลอกคอที่ถูกย่อยไปบางส่วน" } },
    },
    [93606] = { -- Not on Squealing Terms
        title = { "22:1121071910:250532061", "หมางใจกันจนไม่ส่งเสียง" },
        description = { "124:2047703918:12096674 R 271:539585011:1961988315 R 89:1226326111:1070212158", "Quolga ผู้ฉลาดเป็นคู่ชีวิตของ Kog'thug นางถักหนามเก่ง Kog'thug ชอบนางเพราะแบบนี้ Quolga มีสร้อยที่ {race} ตัวใหญ่ตามหาด้วย\n\nปัญหาน่ะหรือ? เราไม่คุยกันแล้ว นางโกรธที่พวกเราขโมยสร้อยมาตั้งแต่แรก แล้วนางใช้สร้อยทำไมล่ะ? Kog'thug อยากรู้นัก!\n\nแต่ว่า! Quolga ชอบดอกไม้พอ ๆ กับหนาม รู้ไหมจะหาดอกไม้ได้ที่ไหน? ที่เดียวกับที่เราได้สร้อยมาไง!\n\nถ้า {race} ตัวใหญ่เอาดอกไม้กับเลือดนี่ไปให้แทน Kog'thug นางอาจหายโกรธก็ได้ บางทีนางอาจยอมแลกสร้อย!\n\nบอกนางด้วยว่า Kog'thug ขอโทษ" },
        objective = { "211:662915037:401542435", "ช่วยให้พวกควิลบอร์คืนดีกันด้วยการนำช่อดอกไม้ผูกไมตรีกับเลือดพิษของ Agamaggan ไปให้ Quolga ดอกไม้สำหรับจัดช่อหาได้ที่ Forlorn Gardens ใกล้ Shen'dralas ใน Desolace" },
    },
    [93609] = { -- Forlorn Necklace
        title = { "16:1029199681:978723098", "สร้อยคอจากสวนร้าง" },
        description = { "303:111325707:1312477700", "<ในที่สุดสร้อยคอที่เจ้าตามหาก็มาอยู่ในมือ แต่น่าเสียดายที่พลังเวทในสร้อยหมดเกลี้ยง แม้จะไม่เป็นผลดีต่อสถานการณ์ตอนนี้ อย่างน้อยก็ทำให้เอาสร้อยมาจากพวกควิลโบร์ได้ค่อนข้างง่าย\n\nเอาสร้อยกลับไปให้ Mithera น่าจะดีที่สุด>" },
        objective = { "83:2140722557:1714102836", "นำสร้อยคอจากสวนร้างไปให้ Mithera ที่วิหาร Shen'dralas ใน Desolace" },
    },
    [93976] = { -- The Goblin Trader
        title = { "17:1759736855:1336315112", "แม่ค้าก็อบลิน" },
        description = { "335:92482031:901986556", "ระหว่างที่ Gur'dok กับข้ายังทำงานกันต่อ เราตีดาบเล่มหนึ่งให้เพื่อน อืม เรียกเพื่อนคงสนิทเกินไป เอาเป็นว่าคนรู้จักที่ท่าเรือ นางเป็นที่รู้จักดีและมีเส้นสายทั่วราชอาณาจักร แถมยังมีไปถึงแดนอื่นด้วย\n\nรับไป ตอนเอาไปส่ง บอกนางว่าข้าส่งเจ้ามา แล้วบอกด้วยว่าเราหายกันแล้ว" },
        objective = { "81:70997988:304435985", "นำดาบไปให้คนรู้จักของ Kreza Darkthorn ที่ท่าเรือทางตะวันออกของ Rog'mar" },
        completion = { "73:53851514:1297656468", "ว่าไง! ยินดีที่ได้รู้จักนะ!\nKreza บอกว่าเราหายกันแล้วจริง ๆ เหรอ? คิดได้น่ารักดีนี่" },
        progress = { "62:1526140685:1508046543", "มาส่งของในนาม Horde รึ? เจ้าคงเป็นคนของ Kreza สินะ" },
        required = { [263973] = { "16:1058073855:1197752735", "ดาบของผู้ล่อลวง" } },
        steps = { { "16:1058073855:1197752735", "ดาบของผู้ล่อลวง" } },
    },
    [94613] = { -- My Kingdom for a Horse
        title = { "22:75496529:1759962730", "ยอมแลกทั้งอาณาจักรเพื่อม้าสักตัว" },
        description = { "492:1664507959:473010535", "ม้าศึกของเรามาจากฟาร์มใกล้ ๆ สองแห่ง ฟาร์มหนึ่งเป็นของตระกูล Wheeler อยู่แยกจากถนนนอกเมืองไปนิดเดียว ดูเหมือนม้าของฟาร์มนั้นจะหายไปหมด ตอนนี้ยังไม่รู้ว่าเกิดอะไรขึ้น\n\nถ้าไม่มีม้าก็ไม่มีกองทหารม้า และถ้าไม่มีกองทหารม้า การรบกับฮอร์ดครั้งนี้ก็ไม่มีทางชนะ\n\nเห็นแล้วใช่ไหมว่าเราต้องจัดการเรื่องนี้ให้เร็วที่สุด ส่วนจะเริ่มตรงไหน ข้าเองก็ยังไม่แน่ใจ\n\nไปที่ Wheeler's Grange แล้วคุยกับ Benjy ดูว่าเขาจะว่าอย่างไร" },
        objective = { "59:699877258:1952292342", "ไปที่ Wheeler's Grange เพื่อสอบถามเรื่องม้าที่หายไป" },
        completion = { "104:306927019:1002610722", "คนใหญ่คนโตส่งเจ้ามาเองเลยรึ? มาช่วยงานจริง ๆ หรือจะมาคะยั้นคะยอเอาม้าเหมือนคนก่อนล่ะ?" },
    },
    [94857] = { -- If a Tree Falls, and No One Hears...
        title = { "36:449890617:51758909", "ถ้าต้นไม้ล้มแล้วไม่มีใครได้ยิน..." },
        description = { "264:1991815699:450736782", "คนแปลกหน้า ฟังข้าก่อน!\n\nข้าเป็นคนตัดไม้ของค่ายทำไม้ใกล้ ๆ อย่างที่เห็น ข้าประสบอุบัติเหตุและติดอยู่ตรงนี้ ถ้าออกไปไม่ทัน ข้าคงเลือดไหลจนตายหรือไม่ก็ถูกสัตว์ป่ากิน\n\nได้โปรด ไปที่ค่ายทำไม้แล้วตามคนมาช่วยที!" },
        objective = { "41:967890034:1431882975", "ไปขอความช่วยเหลือที่ Turner's Logging Camp" },
        completion = { "20:145829187:901813935", "พี่ชายข้าไปอยู่ที่ไหนนะ?!" },
    },
    [95295] = { -- I Know a Guy
        title = { "12:531086556:1263446212", "ข้ารู้จักคนอยู่คนหนึ่ง" },
        description = { "494:1366750765:1557094470", "จัดการพวกโจรสลัดได้ดีนี่ เจ้าลูกน้อง แต่จำบทเรียนนี้ไว้ คนหนึ่งเรียกพวกมันว่าโจรสลัด อีกคนเรียกว่าฟรีบูตเตอร์ ฟังสิ ฟรีบูตเตอร์ก็ต้องมีของปล้นฟรี แล้วจะไปหาของปล้นฟรีที่ไหนได้ดีไปกว่า Booty Bay!\n\n<Friz รอฟังคำตอบของเจ้า>\n\nตามให้ทันสิ เจ้าหนู ข้าจะให้เจ้าไปพบคนติดต่อของข้าที่ Booty Bay เขารับของจากโจรสลัดแถวนั้น เอ่อ พวกฟรีบูตเตอร์น่ะ เอาเถอะ ไปหา Ruzzgot เดี๋ยวเขาอธิบายที่เหลือเอง" },
        objective = { "37:750668479:1785669150", "คุยกับผู้ติดต่อของ Friz ใน Booty Bay" },
        completion = { "204:1481143349:1592798992", "ไม่ใช่ทุกวันที่เราจะมีแขกจาก Powderfuse Port มาเยือน เดินทางมาไกลเอาเรื่องนะ!\n\nถ้าเจ้ามาถึงนี่ได้ด้วยตัวเอง ก็คงไม่ต้องพึ่งขบวนคาราวานเท่าไรแล้วล่ะสิ? แล้วใครส่งเจ้ามา Friz เหรอ?" },
    },
    [95296] = { -- Shipping and Handling
        title = { "21:2120821290:697834013", "งานขนส่งสินค้า" },
        description = { "498:1447368084:1012748691", "ดูท่าเจ้าพร้อมเรียนบทต่อไปแล้ว เจ้าคนเก่ง ข้ามีเรื่องต้องเจรจาในเมือง เลยอยากให้เจ้าช่วยเดินงานสองสามอย่างระหว่างที่ข้ายุ่ง\n\nเจ้าขึ้นเรือเที่ยวถัดไปที่ท่าแล้วเอาลังนี้ไปให้คนของข้าที่ Steamwheedle Port เท่านั้นเอง\n\nอย่ามองข้าแบบนั้นสิ รับรองว่าตื่นเต้นแน่ จะให้ก็อบลินจ่ายเงินที่ค้างไว้ยากกว่าซ้อมพวกอันธพาลแถวนี้เยอะ ยังไม่นับว่าต้องผ่านศุลกากรอีก เจ้าหาทางได้อยู่แล้ว" },
        objective = { "67:1020742841:874787248", "คุยกับ Wharfmaster Steamfizzle ที่ Steamwheedle Port ใน Tanaris" },
        completion = { "177:1767176941:1477103300", "ข้าไม่มีทางให้เจ้าเข้าเมืองของข้าจนกว่าจะตรวจสินค้าของเจ้าก่อน\n<นายท่ากระแอมช้า ๆ โดยยังจ้องตาเจ้าอยู่>\nไม่ มี ทาง" },
        progress = { "158:584648331:824613254", "สินค้าจาก Powderfuse Port งั้นรึ? แถมส่งมาจาก Friz เสียด้วย ขอให้โชคดีนะ สหาย คิดจะตบตาข้าด้วยลูกไม้นั้นยังเร็วไป!" },
        logReady = { "66:1499689944:1072223077", "คุยกับ Wharfmaster Steamfizzle ที่ Steamwheedle Port ใน Tanaris" },
        required = { [268811] = { "19:2122966776:1524731936", "ของที่ Friz ซ่อนไว้" } },
        steps = { { "15:1461260454:985772717", "ผ่านพิธีการศุลกากร" }, { "19:2122966776:1524731936", "ของที่ Friz ซ่อนไว้" } },
    },
    [95418] = { -- Spread the Word
        title = { "15:1515181871:16831541", "ส่งข่าวต่อ" },
        description = { "408:1305821116:1958796508", "ข้าพอกับ Twilight แล้ว ตอนนี้ Clubtoe เป็นโอเกอร์อิสระ\n\nข้าจะไปหา Clugfist เขาเป็นโอเกอร์ตัวใหญ่ที่สุดที่ Clubtoe เคยเห็น เขาทิ้ง Twilight แล้วพาเพื่อนไปด้วยตั้งเยอะ ถึงตา Clubtoe แล้ว ข้าจะไปอยู่กับโอเกอร์อิสระ พวกเขาไปที่เนินเขา Clubtoe คิดถึงเนินเขา ไม่ต้องทุบหินแล้ว เจ้าจะมาเยี่ยมบ้างไหม?\n\nข้าจะอยู่ตรงนี้จนกว่าทางจะโล่ง เจ้าเอาหัวของ Chogg'Zac กลับไปให้เพื่อน ๆ เอ่อ เอาไปหัวเดียวก็พอ ข้าขอหัวหนึ่งด้วย แบบนี้ยุติธรรมดี" },
        objective = { "49:837850439:823968301", "นำหัวของ Chogg ไปให้ Tran'gul ใน Rog'mar" },
        completion = { "199:1465634416:1023484771", "เอาละ ดูเหมือนถ้ำนั่นจะมีเรื่องให้ประหลาดใจมากกว่าที่เราคิด\nเจ้าเกลี้ยกล่อมโอกร์ Twilight's Hammer ให้แปรพักตร์ได้คนหนึ่งรึ? แล้วเขายังพูดถึงโอกร์ตัวอื่น ๆ อีกหรือ? เราต้องรีบจัดการเรื่องนี้ทันที" },
        progress = { "92:89205563:2020128804 N 57:40351440:1156465436", "พวก Twilight's Hammer เจออะไรบางอย่างในดินรึ? เจ้าทำถูกแล้วที่ขับไล่สิ่งชั่วร้ายนี้ {name} ของที่พวกคลั่งลัทธินั่นสนใจ ไว้ใจไม่ได้หรอก" },
        required = { [265750] = { "12:1719522912:904062116", "ศีรษะของ Chogg" } },
        steps = { { "12:1719522912:904062116", "ศีรษะของ Chogg" } },
    },
    [95420] = { -- Land of Giants
        title = { "14:717369262:1305127614", "ดินแดนยักษ์" },
        description = { "508:595687407:574158190", "เห็นชัดว่าโอเกอร์ที่แยกตัวออกมาพวกนี้ไม่มีไมตรีกับ Twilight's Hammer พวกออร์คอย่างเราเคยสู้เคียงบ่าเคียงไหล่กับโอเกอร์อย่างมีเกียรติ อาจถึงเวลาเรียกหาพันธมิตรเก่าอีกครั้ง และหัวนี้อาจเป็นกุญแจสำคัญ\n\nมีรายงานว่าพบโอเกอร์แถวเนินเขาไกลออกไปทางเหนือ ถ้าเชื่อที่ Clubtoe บอก ที่นั่นคงเป็นบ้านของเผ่านี้ ไปที่ฐานมั่นของพวกเขาแล้วมอบของที่ระลึกจากการรบชิ้นนี้เป็นสัญลักษณ์แห่งไมตรี ถ้าโชคดี พวกเขาจะฟังข้อเสนอของเจ้าก่อนเหยียบเจ้าจมดิน" },
        objective = { "51:269976189:1471155146", "นำหัวของ Chogg ไปยังเมืองอ็อกเกอร์ทางเหนือ" },
        completion = { "75:110759128:1995152254", "เจ้าทุบ Chogg'Zac หรือ? เจ้าตัวเล็กมีพลัง\nเจ้าต้องการอะไรจาก Clugfist?" },
        progress = { "75:829153277:889818764", "<โอกร์ร่างยักษ์เรอใส่หน้าเจ้า>\nเจ้าตัวจิ๋วเอาอะไรมาให้ Clugfist?" },
        required = { [265750] = { "12:1719522912:904062116", "ศีรษะของ Chogg" } },
        steps = { { "12:1719522912:904062116", "ศีรษะของ Chogg" } },
    },
    [94668] = { -- Bloodmaster's Ring
        title = { "18:338070528:848099990", "สังเวียนของ Bloodmaster" },
        description = { "165:1288702581:871659261", "เจ้าทุบโอเกอร์ Twilight ได้ แต่พวกมันอ่อนแอ\n\nวันนี้แสดงให้ Bloodmaster กับเพื่อนก็อบลินตัวเล็กเห็นว่าเจ้าเหมาะกับที่นี่\n\nพรุ่งนี้อาจเจอกันอีก ถ้าเจ้ายังหายใจอยู่" },
        objective = { "42:1044314455:636553963", "ไปพบ Jezap ที่ Bloodmaster's Ring" },
        completion = { "174:2084357379:180940674", "เฮ้ เฮ้! ดูซิว่าใครมา เหยื่ออีกราย... เอ่อ ผู้เข้าแข่งขันอีกคนที่อยากพิสูจน์ตัวเองบนขอบเหวแห่งอำนาจ!\nเข้ามาเลย สหาย วันนี้เป็นวันโชคดีของเจ้า... หรืออาจไม่ใช่" },
    },
    [94669] = { -- Pay to Play
        title = { "11:360040516:1816267060", "จ่ายก่อนลงสนาม" },
        description = { "332:407545360:873181062", "ก่อนอื่นเลย ข้าต้องขอเงินมัดจำเพื่อ เอ่อ... ความปลอดภัยของเจ้า\n\nฟังนะ ข้าไม่ได้ตั้งกฎที่นี่ เขากำหนดว่าต้องจ่าย\n\nถ้าเจ้าเลือกไม่จ่าย ข้าก็คงต้องบอก Clugfist ว่าสหายใหม่ของเราไม่ค่อยอยากพิสูจน์ความแข็งแกร่งให้เพื่อนผู้แสนอบอุ่นของเราที่นี่เห็นเท่าไร\n\nคงน่าเสียดายแย่ เข้าใจที่ข้าพูดใช่ไหม เจ้าหนู?" },
        objective = { "61:1964841010:589877484", "จ่ายเงินประกันเพื่อให้มีสิทธิ์เข้าร่วม Bloodmaster's Ring" },
        completion = { "19:874568438:1470175514", "เลือกได้ฉลาดมาก" },
        progress = { "18:1829498046:309467328", "ว่าไง จะเอาแบบไหน?" },
        steps = { { "19:31424368:1218022382", "จ่ายเงินมัดจำ" } },
    },
    [94733] = { -- Our Ogre Friend
        title = { "15:2052378720:1093944913", "เพื่อนโอเกอร์ของเรา" },
        description = { "484:2146884608:1190100413", "เอาล่ะ เจ้าชนะมาสองสามครั้ง ข้าว่าเจ้าอาจมีฝีมือพอจะเอาตัวรอดที่นี่จริง ๆ\n\nก่อนข้าจะกล่อมคู่ต่อสู้คนถัดไปให้ลงสังเวียนกับเจ้า ข้าขอให้เจ้าช่วยหาอาหารให้ Snufflesnout หมูป่าเลี้ยงของ Chub'chob หน่อย\n\nข้ารับปากว่าจะดูแลมัน แต่งานนี้ทำให้ข้ายุ่งเอาเรื่อง เชื่อเถอะ เรื่องนี้เป็นประโยชน์กับเราทั้งคู่\n\nเดินไปทางตะวันออกของที่รวมพลของ Clugfist เจ้าจะเจอคนขี้อายชื่อ Gobam" },
        objective = { "26:1379867265:1051091512", "ตามหา Gobam ใน Bolder'ok" },
        completion = { "99:293860824:1779614606", "ก็อบลินส่งเจ้ามาเรอะ? ข้าไม่ชอบไอ้ก็อบลินตัวจ้อย มันพูดมาก\n\nแต่ข้าจะช่วย Chub'chob เขาเป็นเพื่อนที่ดี" },
    },
    [94737] = { -- A Treat for a Friend
        title = { "20:2126259660:1885284343", "ของกินเล่นสำหรับเพื่อน" },
        description = { "118:207613675:1691993878", "ตกลง สหาย เอาของกินเล่นไป Snufflesnout เห็นแล้วจะส่งเสียงฟึดฟัดอย่างดีใจ\n\nแล้วบอกก็อบลินด้วยว่าช่วยพูดให้น้อยลงหน่อย" },
        objective = { "65:1960257943:72972069", "นำห่อสินค้าไปให้ Jezap Jinglesprocket ใน Bolder'ok" },
        completion = { "156:224951726:889279321", "เขาพูดแบบนั้นรึ? พูดถึงข้าเนี่ยนะ? ช่างเถอะ\nมาสนใจเรื่องสำคัญกันดีกว่า ทำให้เจ้า Snufflesnout มีความสุขไง ที่ข้าเรียก Snufflesnout น่ะ หมายถึง Chub'chob" },
    },
    [95219] = { -- From Port to Port
        title = { "17:976545758:1907373512", "จากท่าเรือหนึ่งสู่อีกท่า" },
        description = { "464:540729956:1802176592", "มีงานอีกอย่างให้เจ้า เจ้าหนู อยากออกเดินทางไปดูโลกไหม?\n\nนี่คือไวน์พอร์ตชั้นเยี่ยมที่สุดอย่างหนึ่งที่เจ้าเคยเห็น ติดตรงที่ต้องเอาไปส่งลูกค้าของข้าไกลถึง Feathermoon Stronghold ใน Feralas พอเห็นต้นไม้สูงกว่าที่เจ้าเคยเห็น ก็รู้ว่ามาถูกที่แล้ว\n\nคนของข้าคนหนึ่งปิดผนึกไว้แน่น แต่อะไรจะทำให้มันปะทุขึ้นมาก็ไม่รู้ เพราะงั้นถือดี ๆ ล่ะ เจ้าหนู" },
        objective = { "95:170308846:1059161489", "นำ Cask of Powderfuse Port ไปให้ Mardrack Greenwell ที่ Feathermoon Stronghold ใน Feralas" },
        completion = { "291:518461334:181976907", "Friz ส่งของตรงเวลาจริง ๆ เจ้าเดินทางมาไกลน่าดูเลย ข้าต้องยอมรับว่าติดใจรสเฉพาะตัวที่พวกก็อบลินปรุงขึ้นมา สุราของชาวคัลโดไรมักจะ... พิถีพิถันกว่านี้\n\nเราจะหาที่เย็น ๆ เก็บไว้ ไหน ๆ ก็มาถึงแล้ว เจ้าอยากเดินดูรอบ ๆ ไหม?" },
    },
    [95428] = { -- Clugfist's Decree
        title = { "17:1064366582:1986522401", "คำประกาศของ Clugfist" },
        description = { "7:1538437264:1381753085 R 153:323450622:976056095", "{race} ตัวเล็กทุบพวก Twilight ได้ดี ฮอร์ดของเจ้าอาจแข็งแกร่งกว่าที่ Clugfist คิด\n\nเจ้าอยู่ใน Bolder'ok ได้ ตามสบาย... ตอนนี้นะ\n\nบอกพวกตัวจิ๋วที่เหลือด้วยว่าอีกไม่นานเราจะทำให้เลือดไหลอีกครั้ง" },
        objective = { "31:841989155:2007320302", "ไปพบ Krom'rosh ใน Rog'mar" },
        completion = { "245:709404324:116831039 N 79:1005164908:591988452", "พวกโอกร์ลุกฮือรึ? ทั้งที่เพิ่งสู้เพื่อเป็นอิสระจาก Twilight's Hammer มาได้ไม่นานเนี่ยนะ? ประวัติของนักรบพวกนี้แทบจะนองเลือดพอ ๆ กับของเรา ถ้าเราทำให้พวกเขาไว้ใจเราได้ต่อไป พวกเขาจะเป็นพันธมิตรที่แข็งแกร่ง\nทำได้ดี {name} ข้าว่านี่เพิ่งจะเป็นจุดเริ่มต้นของการติดต่อระหว่างเรากับเผ่า Bolder'ok" },
    },
    [95431] = { -- Rumblings of Discontent
        title = { "23:1772810965:470824168", "เสียงไม่พอใจที่เริ่มดังขึ้น" },
        description = { "379:1556963517:741583245", "ข้าแอบตามดูความเคลื่อนไหวของศัตรูจนพบจุดอ่อน โอเกอร์ที่ไม่ยอมอยู่ใต้อำนาจเริ่มลุกฮือ พวกเขาต้องการอิสรภาพแบบเดียวกับญาติพี่น้องใน Bolder'ok ข่าวการกระทำของเจ้าแพร่ออกไปแล้ว เราต้องใช้โอกาสนี้\n\nข้าเห็นนักรบจาก Bolder'ok มุ่งหน้าไปยังถ้ำทางตะวันตกของที่นี่เพื่อตามหาพี่น้องของเขา ไปหาเขาแล้วช่วยเขารวมกำลังคนของเขา" },
        objective = { "47:712854408:1394188665", "ตามหาอ็อกเกอร์จาก Bolder'ok ในถ้ำใกล้ ๆ" },
        completion = { "126:531850379:709152051", "<Crag'rog เงื้อกระบองเตรียมโจมตี ก่อนจะมองเจ้าให้ชัดอีกครั้ง>\nเดี๋ยว... Crag'rog รู้จักเจ้า เจ้าสู้ให้ Clugfist!" },
    },
    [95181] = { -- Twilight Scouting Report
        title = { "24:2094414663:615418524", "รายงานสอดแนมพวก Twilight" },
        description = { "455:765696563:521432057", "เงียบหน่อย!\n\n<Azka ตวาดพลางหันมองเจ้า>\n\nข้าจะตัดหัวเจ้าก่อนที่เจ้าจะทำให้พวกลัทธิรู้ว่าข้าอยู่ตรงไหน\n\nระวังฝีเท้าและพูดเบา ๆ ตอนผ่านเนินเขาแถบนี้ ไม่งั้นข้าคงต้องส่งรายงานให้ Krom'rosh ว่าคนของเราถูกจับไปอีกคน\n\nเอานี่ไปแล้วรีบออกไปจากตรงนี้... เงียบ ๆ ด้วย! Krom'rosh รอรายงานนี้อยู่ เจ้าจะพบเขากับคนอื่น ๆ ที่ด่านทางตะวันออก ลึกเข้าไปในแผ่นดิน" },
        objective = { "47:1160474904:478045397", "ส่งข้อความของ Azka ให้ Krom'rosh ที่ Rog'mar" },
    },
    [94744] = { -- The Wayward Warrior
        title = { "19:1713171101:2048088444", "นักรบผู้ไม่ยอมรอ" },
        description = { "410:543886221:1897110902", "เจ้าช่วยชะลอพวก Twilight's Hammer ได้ดี ฐานที่มั่นของพวกมันใน Sunnyglade อ่อนกำลังลง และเจ้าก็ทำให้นักรบโอเกอร์หันมาเล่นงานพวกมันเอง ถึงเวลาเป็นฝ่ายบุกแล้ว\n\nDag'rosh น้องชายของข้าล่วงหน้าไปกับหน่วยสอดแนมแล้ว ข้าอยากให้เขารอเจ้า แต่เขาใจร้อนและกระตือรือร้นเกินไป สมกับเป็นนักรบตัวจริง ข้าจะถือเป็นเกียรติถ้าเจ้าไปร่วมรบกับเขาที่ฐานมั่นของศัตรูทางตะวันตก" },
        objective = { "43:123411677:1458121996", "ตามหา Da'grosh บนเนินเขาทางตะวันตกของ Rog'mar" },
        completion = { "109:14490428:596825258", "Krom'rosh ส่งเจ้ามารึ? เจ้านั่นชอบออกคำสั่งยิ่งกว่าเด็กเลี้ยงหมูที่ฟันน้ำนมยังไม่หลุดเสียอีก\nแต่มีคนมาช่วยเพิ่ม ข้าก็ยินดีรับไว้" },
    },
    [94886] = { -- The Western Front
        title = { "17:2076736566:2027147856", "แนวรบด้านตะวันตก" },
        description = { "489:1429336595:714909135", "เจ้าช่วยเราไว้มากที่ Farholde แต่ข้าคิดว่าฝีมือของเจ้าน่าจะมีประโยชน์ยิ่งกว่าถ้าไปช่วยที่อื่น\n\nหน่วยลาดตระเวนของเราหายไปพักหนึ่งแล้ว พวกเขารับผิดชอบแนวชายแดนตะวันตก แต่จากข้อมูลที่คุณ Amberhall พบ ข้ากลัวว่าพวกเขาจะเดินตรงเข้าไปในค่ายหลักของ Twilight's Hammer\n\nพวกเราจัดการเก็บกวาดที่ Sunnyglade กันเองได้ ถ้าคุณ Amberhall คิดถูก เราต้องรีบไปดูว่าจ่าที่หายไปเป็นอย่างไรบ้าง เขาคงต้องการความช่วยเหลือเท่าที่จะหาได้" },
        objective = { "60:1753332362:1827949836", "ตามหา Sergeant Riftan ใกล้ Twilight's Shroud ทางตะวันตก" },
        completion = { "184:1345477970:428549126", "ถ้าเจ้ามาถึงนี่ Amberhall คงกำลังบ่นใส่ผู้บัญชาการอัศวินว่าเราไม่ส่งรายงาน อย่าให้คำหวานของนางหลอกเอาล่ะ ถ้านางเห็นว่าคุ้ม ต่อให้เป็นวิญญาณของเจ้านางก็ขายได้" },
        logReady = { "60:1753332362:1827949836", "ตามหา Sergeant Riftan ใกล้ Twilight's Shroud ทางตะวันตก" },
    },
    [95278] = { -- It Is Time, Brother...
        title = { "22:2015191939:152130407", "ถึงเวลาแล้ว พี่น้องข้า..." },
        description = { "99:869267840:1342947903", "ภัยครั้งนี้ใหญ่หลวงกว่าที่เราคิด ต้องเตือน Rog'mar\n\nอย่าหยุดให้ใครระหว่างทาง" },
        objective = { "44:729953240:291693407", "นำจดหมายไปให้ Krom'rosh ที่ Rog'mar" },
        completion = { "228:123633125:1512685965", "ตอนยังเด็ก Da'grosh คอยปลุกใจข้ากับพี่น้องคนอื่น ๆ ในหมู่บ้านว่าสักวันพวกเราจะเป็นนักรบผู้ยิ่งใหญ่ของ Horde และช่วยคนของเราให้รอดพ้นจากภัยที่กำลังเข้ามา\nดูเหมือนโอกาสนั้นจะมาถึงแล้ว" },
    },
    [93971] = { -- Farholde Scouting Report
        title = { "24:1352157622:1826232066", "รายงานสอดแนมของ Farholde" },
        description = { "111:1230827579:1310135044", "<รายงานฉบับนี้ประทับตราสัญลักษณ์ของ Farholde ข้อมูลข้างในอาจเป็นที่สนใจของ Krom'rosh ที่ Rog'mar>" },
        objective = { "41:1767961181:1636878228", "นำรายงานไปให้ Krom'rosh ที่ Rog'mar" },
    },
    [94556] = { -- Jom-jom's Escape
        title = { "16:154574853:78504695", "การหลบหนีของ Jom-jom" },
        description = { "61:1042440973:287502234", "Jom-jom มาตามหาเพื่อน ตอนนี้ Jom-jom อยากกลับบ้าน" },
        objective = { "40:1081040128:1311720857", "คุ้มกัน Jom-jom ไปหา Clugfist ที่ Bolder'ok" },
        completion = { "55:695700113:1695986431", "เจ้าตัวเล็กช่วย Jom-jom ไว้สินะ?\n\nเจ้าตัวเล็กเป็นเพื่อน" },
        objectiveLabels = {
            event = { ["Help Jom-jom reach Bolder'ok"] = "ช่วย Jom-jom ไปให้ถึง Bolder'ok" },
        },
    },
    [94615] = { -- Foal Play
        title = { "9:170710825:411504588", "คดีลูกม้าหาย" },
        description = { "314:1947670975:513051249", "ข้าไม่รู้เลยว่าเกิดอะไรขึ้นกับม้าของเรา เช้าวันหนึ่งข้าลุกขึ้นมาให้อาหาร แล้วก็พบว่าพวกมันหายไปหมด หายไปเฉย ๆ เลย\n\nชีวิตนอก Farholde ลำบากกว่าในเมืองหน่อย อะไรก็เล่นงานพวกมันได้ทั้งนั้น สัตว์ป่า เมอร์ล็อก ออร์ค มีสารพัด\n\nถ้าอยากรู้ว่าควรสงสัยใคร เราน่าจะลองหาร่องรอยแถวคอกม้าดู" },
        objective = { "92:265760429:631640645", "ค้นหาเบาะแสว่าม้าที่หายไปอยู่ที่ไหน บริเวณใกล้คอกม้าที่ Wheeler's Grange" },
        completion = { "35:1155267214:412986093", "ข้าว่าแล้ว! ฝีมือไอ้หมาป่าโคโยตีพวกนั้นแน่ ๆ!" },
        progress = { "119:957894274:1484004470", "ข้าอยากรู้พอ ๆ กับตา Demar นั่นแหละว่าเกิดอะไรขึ้นกับพวกม้า ก็ข้าหาเลี้ยงชีพด้วยม้าพวกนี้นี่นา" },
        steps = { { "10:319814853:1865788963", "หาเบาะแส" } },
    },
    [94618] = { -- Wheeler's Fleeing Steeds
        title = { "24:2023915253:378391078", "ม้าตระกูล Wheeler ที่หนีไป" },
        description = { "426:1124503133:470424451", "จากที่เจ้าพบ ดูเหมือนหมาป่าโคโยตีจะกินม้าไปเกือบหมด แต่ยังมีอีกบางตัวที่เราไม่รู้ชะตากรรม\n\nตัวที่รอดคงตกใจวิ่งหนีไปซ่อนที่ไหนสักแห่ง ข้าไม่รู้ว่าเหลือกี่ตัว แต่เราควรรีบหาให้เจอก่อนพวกโคโยตีจะกลับมา\n\n<Benjy ยื่นกระสอบใบหนึ่งมาตรงหน้าเจ้า>\n\nเอ้านี่ ถ้าเจอสักตัวก็ให้อาหารของเรากับมันหน่อย มันจะได้ไว้ใจเจ้า แล้วเจ้าก็จูงมันกลับมาที่นี่ได้" },
        objective = { "96:1457798127:769211288", "ตามหาม้าสักตัวที่หนีออกจาก Wheeler's Grange หลังถูกโคโยตีโจมตี แล้วให้อาหารมัน" },
        completion = { "54:1568072325:1602674882", "<ม้าดูจะชอบอาหารที่กำลังเคี้ยวอยู่เต็มปาก>" },
        progress = { "28:264975784:383586557", "<ม้ามองเจ้าด้วยสายตาระแวดระวัง>" },
        required = { [267178] = { "20:1936676361:1832457099", "อาหารม้าของ Wheeler" } },
        steps = { { "20:1936676361:1832457099", "อาหารม้าของ Wheeler" } },
    },
    [94670] = { -- Bloodmaster's Ring
        title = { "18:338070528:848099990", "สังเวียนของ Bloodmaster" },
        description = { "199:927551816:204667871", "การต่อสู้ในสังเวียนของ Bloodmaster เริ่มแล้ว!\n\nเราจะให้เจ้าเริ่มจากตัวง่าย ๆ ก่อนนะสหาย เจ้าตัวบินนี่จะเล่นงานเจ้าจนล้มแล้วจิกกินจนเกลี้ยง\n\nเลิกยืนเฉย ๆ แล้วก้าวเข้าสังเวียนเสียที ชื่อเสียงรอเจ้าอยู่!" },
        objective = { "42:2120330079:1376272815", "เอาชนะ Buzzbeak ใน Bloodmaster's Ring" },
        completion = { "57:203242286:247604079", "เห็นไหม? ข้าบอกแล้ว ที่นี่ไม่มีอะไรให้กังวลหรอก" },
        objectiveLabels = {
            event = { ["Buzzbeak defeated"] = "เอาชนะ Buzzbeak" },
        },
    },
    [94734] = { -- A Boar's Delight
        title = { "16:1701017121:268432500", "ของโปรดของหมูป่า" },
        description = { "230:41327431:491489202", "Gobam รู้ว่าสัตว์เลี้ยงของ Chub'chob ชอบกิน โดยเฉพาะของอร่อย!\n\nเบอร์รีอร่อย ๆ กับพืชจากแม่น้ำทำของกินเล่นให้ Snufflesnout ได้ เบอร์รีหวาน เบอร์รีดีที่สุดอยู่ที่ฟาร์มมนุษย์ใกล้ทะเล\n\nเจ้าไปหา เอากลับมา ข้าช่วยทำของกินเล่นชิ้นใหญ่ให้" },
        objective = { "7:451016854:1830523975 W1 16:210495260:1789590428 W2 21:787173745:908448321", "เก็บ Sweetberry {world1} ผล และ Riverweed {world2} ต้นให้ Gobam" },
        completion = { "45:1244558160:520973192", "เจ้าทำงานดี\nเบอร์รีกลิ่นหอม น่ากิน ๆ" },
        progress = { "13:588490874:952019024", "เจ้าได้ของกินมาไหม?" },
        required = { [265808] = { "10:81341727:2034661276", "ผล Sweetberry" }, [265806] = { "9:1607161240:845750673", "วัชพืชน้ำ Riverweed" } },
        steps = { { "10:81341727:2034661276", "ผล Sweetberry" }, { "9:1607161240:845750673", "วัชพืชน้ำ Riverweed" } },
    },
    [94739] = { -- Bloodmaster's Ring
        title = { "18:338070528:848099990", "สังเวียนของ Bloodmaster" },
        description = { "254:1168992132:402920916", "ดีใจที่เจ้าผ่านรอบแรกมาได้นะ คิดว่างั้น\n\nข้ารู้จักผู้เข้าแข่งคนถัดไปมานานแล้ว เขาไม่ค่อยฉลาดนัก แต่เรื่องทุบทุกอย่างที่ขวางทางน่ะเก่งจริง\n\nลงไปในลานประลองแล้วเตรียมตัวไว้ เดี๋ยวข้าประกาศเอง" },
        objective = { "39:1262627987:837739466", "เอาชนะ Kronk ใน Bloodmaster's Ring" },
        completion = { "82:585149940:303456767", "เฮ้ ๆ เบาเสียงหน่อย ข้าเข้าใจว่าตื่นเต้น แต่อย่าเอามาเยาะเย้ยกันสิ" },
        objectiveLabels = {
            event = { ["Kronk defeated"] = "เอาชนะ Kronk แล้ว" },
        },
    },
    [94745] = { -- Carving a Path
        title = { "14:786865507:1472265577", "ฝ่าเปิดทาง" },
        description = { "277:1588615285:1490963827", "เห็นป้อมทางตะวันตกของที่นี่ไหม? เขาเรียกว่า Twilight's Shroud ข้างในอัดแน่นไปด้วยพวกขี้ขลาดจาก Twilight's Hammer\n\nพวกมันอาจมีกำแพงและคนมาก แต่พวกมันอ่อนแอเพราะเอาแต่พึ่งมนตร์ชั่วกับเทพโบราณ แสดงให้เห็นว่าจริง ๆ แล้วพวกมันเปราะบางแค่ไหน!" },
        objective = { "7:1265997621:1189804897 W1 20:842221735:1613607240 W2 26:406181726:835666367 W3 62:181591303:616364224", "ปราบ Twilight Fanatic {world1} คน, Twilight Corrupter {world2} คน และ Twilight Champion {world3} คนใน Twilight's Shroud ให้ Da'grosh" },
        completion = { "102:1130629578:1073838580", "ฟังพวกมันร้องหาเทพของตัวเองสิ มีใครตอบเสียที่ไหน! พลังที่แท้จริงอยู่ในมือของเราเอง!" },
        objectiveLabels = {
            monster = { ["Twilight Fanatic slain"] = "ปราบ สาวกคลั่ง Twilight", ["Twilight Corrupter slain"] = "ปราบ ผู้แพร่ความแปดเปื้อน Twilight", ["Twilight Champion slain"] = "ปราบ ยอดนักรบ Twilight" },
        },
    },
    [94748] = { -- Break Their Chains
        title = { "18:1353072162:552664306", "ทำลายโซ่ตรวนของพวกเขา" },
        description = { "268:1226437313:1564194529 C 77:747564233:1744383137", "พวกสุนัข Twilight's Hammer จับเราได้ก่อนจะเริ่มบุกกันจริงจัง ข้าฝ่าออกมาได้ แต่นักรบของข้าไม่โชคดีอย่างนั้น เหล่ายอดนักรบของลัทธิลากพวกเขาไปขังไว้ในป้อมทางตะวันตก\n\nที่ของออร์คไม่ใช่ในกรง {class} ไปปล่อยพี่น้องของข้า แล้วเราจะให้พวกสารเลวเห็นว่าการสู้จริง ๆ เป็นอย่างไร" },
        objective = { "7:381738004:212593327 W1 58:922224554:372853837", "ช่วย Rog'mar Scout {world1} คนใน Twilight's Shroud ให้ Da'grosh" },
        completion = { "11:354343371:1318038540 C 109:1656134567:410364415", "ทำได้ดี {class}\nนักรบของข้าอยู่ในสภาพที่สู้ต่อไม่ไหว พวกเขากลับไป Rog'mar แล้ว แต่เจ้ากับข้ายังมีงานที่นี่" },
        steps = { { "21:1077508965:1827620580", "ช่วยหน่วยลาดตระเวน Rog'mar" } },
    },
    [94768] = { -- Bring Me His Head
        title = { "17:1935257681:154468978", "เอาหัวมันมาให้ข้า" },
        description = { "360:1430791690:939866541", "บันทึกของ Tran'gul ชี้ว่าผู้นำกองกำลัง Twilight's Hammer แถบนี้อยู่ที่ไหนสักแห่งในป้อมนั้น ตอนนี้นักรบของข้าเป็นอิสระแล้ว และกำลังพลของลัทธิก็กำลังสับสน ถึงเวลาแทงทะลุหัวใจของพวกมันเสียที\n\nกลับไปที่ Twilight's Shroud แล้วเข้าไปในฐานมั่นของพวกมัน เจ้าจะเจอ Overlord Kilgar ที่นั่น และเราจะแก้แค้นกันที่นั่น" },
        objective = { "83:351254574:130951363", "ปราบ Overlord Kilgar ใน Twilight's Shroud แล้วนำหัวของเขาไปให้ Da'grosh" },
        completion = { "177:1726696914:254479985", "ข้าอยากเห็นหน้า Kilgar ตอนเจ้าทำให้เขารู้ตัวว่าตัวเองไร้ทางป้องกันแค่ไหน\nทีนี้ข้าก็ได้เห็นแล้ว\n<Da'grosh หัวเราะขณะโยนหัวของ Kilgar ลงพื้นดิน>" },
        progress = { "116:1256567756:774874386", "เจ้าขี้ขลาดนั่นคงซ่อนอยู่ลึกในป้อมของมัน เอาหัวมันมาให้ข้า เราจะได้กำจัดภัยนี้ให้หมดเสียที" },
        required = { [265837] = { "13:1232046453:611945813", "ศีรษะของ Kilgar" } },
        steps = { { "13:1232046453:611945813", "ศีรษะของ Kilgar" } },
    },
    [94832] = { -- Belle's Ring
        title = { "12:990893598:900908453", "แหวนของ Belle" },
        description = { "248:2049073761:1673923852", "น่าเสียดายที่ข้ายังตามหาเจ้าของแหวนไม่เจอ จึงยังช่วยให้ครอบครัวของเจ้าของคลายความค้างคาใจไม่ได้\n\nบางที Daythor อาจช่วยได้ เขารู้จักคนอื่น ๆ ในกองทหารของเราดีทีเดียว\n\nข้าหวังเพียงว่ามันจะไม่รื้อฟื้นความทรงจำอันขมขื่นขึ้นมา..." },
        objective = { "33:2073652585:1693368652", "นำแหวนไปให้ Daythor Brellan ดู" },
    },
    [94879] = { -- Scraps of Knowledge
        title = { "19:1731993241:2088217439", "เศษเสี้ยวของความรู้" },
        description = { "496:1797313494:779421542", "เจ้าเห็นเมืองร้างทางเหนือแล้วใช่ไหม? Sunnyglade น่ะ Demar พยายามส่งทหารไป แต่เราก็ยังยึดเมืองคืนไม่ได้สักที ข้ามีวิธีที่ดีกว่า\n\nความจริงนี่ไม่ใช่ครั้งแรกที่ Twilight's Hammer โจมตี ดูเหมือนพวกมันจะประสานงานจากจุดบัญชาการแห่งหนึ่ง และข้าอยากรู้ว่าอยู่ที่ไหน ระหว่างที่เจ้าออกไปทำสิ่งที่นักผจญภัยถนัดที่สุด ช่วยมองหาเอกสารที่พวกมันอาจทำตกไว้ด้วย ถ้าได้มามากพอ ข้าน่าจะปะติดปะต่อได้ว่าพวกมันคิดจะทำอะไร" },
        objective = { "8:1089852795:1107240600 W1 74:147261817:1256425627", "เก็บ Twilight Page {world1} แผ่นใน Sunnyglade ให้ Ashe Amberall ที่ Farholde Keep" },
        progress = { "124:448505758:1373326176", "พวก Twilight's Hammer เคร่งลัทธิกันนัก แต่จัดการอะไรไม่ค่อยเป็นระเบียบ เจ้าคงพบหน้ากระดาษของพวกมันกระจัดกระจายอยู่ทั่ว Sunnyglade" },
        completion = { "192:888091391:1919651972", "นี่เป็นจุดเริ่มต้นที่ดี แต่ข้าเชื่อว่าของพวกนี้แค่ชี้ทางไปสู่สิ่งที่มีค่ากว่านี้\n\nที่จริง Demar มีข่าวที่เราอาจสนใจ เจ้าลองไปคุยกับท่านผู้บัญชาการอัศวินดูสิ" },
        required = { [266424] = { "13:1738177631:1507385821", "หน้ากระดาษของกลุ่ม Twilight" } },
        steps = { { "13:1738177631:1507385821", "หน้ากระดาษของกลุ่ม Twilight" } },
    },
    [94885] = { -- Field Marshal's Log
        title = { "19:795135306:567057009", "บันทึกของจอมพล" },
        description = { "263:1159332923:978372035", "บันทึกเล่มนี้จดการเข้าออกของกองกำลัง Twilight's Hammer ทั่ว Riverglades ไว้อย่างละเอียด\n\nไม่พบตัวผู้เขียน แต่ข้อมูลนี้อาจช่วยให้เข้าใจการเคลื่อนไหวของศัตรูมากขึ้น\n\nต้องมีคนที่ Farholde อยากเห็นบันทึกนี้แน่" },
        objective = { "64:1148117269:862763606", "นำ Field Marshal's Log ไปให้ Demar Brant ใน Farholde Keep" },
        completion = { "145:595400777:1262167605", "เกรงว่าบันทึกนี้จะมาช้าไป ตอนนี้เรารู้ดีแล้วว่าใน Sunnyglade มีภัยอะไรบ้าง เรื่องที่น่าห่วงกว่าคือเจ้าได้ไปเจอภัยพวกนั้นเข้าแล้ว" },
        progress = { "20:500077224:1375823196", "เจ้าเจออะไรมา?" },
        required = { [266427] = { "19:795135306:567057009", "บันทึกของจอมพลสนาม" } },
        steps = { { "19:795135306:567057009", "บันทึกของจอมพลสนาม" } },
    },
    [94888] = { -- No Soldier Left Behind
        title = { "22:1922962686:1155002400", "จะไม่ทิ้งทหารไว้ข้างหลัง" },
        description = { "95:2068295010:1503989510 C 407:1664969604:662907641", "ถ้า Amberhall รอรายงานแทบไม่ไหว นางน่าจะส่ง {class} มามากกว่าคนเดียว งานหลบอยู่ในหอคอยงาช้างคงหนักมากสินะ\n\nฟังนะ ทุกครั้งที่พยายามติดต่อ Farholde Keep คนส่งสารของเราก็ถูกหน่วยสอดแนม Twilight จับ ข้าเสี่ยงส่งทหารเข้าไปในป้อมนั้นเพิ่มไม่ได้ แต่จะทิ้งคนของข้าให้ถูกขังอยู่ข้างในก็ไม่ได้เหมือนกัน\n\nอยากให้พวกเรากลับไปหรือ? ช่วยทหารของข้าก่อน น่าจะหากุญแจกรงได้จากศพเหล่ายอดนักรบของพวกมัน" },
        objective = { "7:381738004:212593327 W1 66:1541538515:1132985287", "ช่วย Farholde Scout {world1} คนใน Twilight's Shroud ให้ Sergeant Riftan" },
        completion = { "151:827022963:1438473783", "ทหารเพียงคนเดียวอาจชี้ชะตาว่าเราจะรักษาที่มั่นนี้ไว้ได้ หรือปล่อยให้ศัตรูยึดทั้งหุบเขา ดูเหมือนทหารคนนั้นอาจเป็นเจ้า" },
        steps = { { "23:1473799769:1420037520", "ช่วยหน่วยลาดตระเวน Farholde" } },
    },
    [94891] = { -- News to Farholde
        title = { "16:1625293803:1838893121", "ส่งข่าวถึง Farholde" },
        description = { "261:1601425196:1893578138", "ดูเหมือนแถวนี้จะสงบลงบ้างแล้ว แต่ข้ายังอยากเฝ้าระวังไว้ อยากส่งรายงานให้ Amberhall หรือ? เอานี่ไปส่งนาง\n\n<จ่า Riftan โยนหัวของ Kilgar กลับมาให้เจ้า>\n\nอย่างน้อยคงทำให้นางเงียบไปได้สักพัก ทำได้ดีมาก" },
        objective = { "42:746226764:1197991066", "กลับไปหา Ashe Amberhall ใน Farholde Keep" },
        completion = { "232:32616807:1130488613", "เจ้าไปเสียนานจนข้าเริ่มสงสัยว่าประเมินฝีมือเจ้าผิดไปหรือเปล่า แต่ดูท่าเจ้าจะเหมาะกับงานนี้พอดี\nแล้วตา Riftan ล่ะ ยังโลดแล่นอยู่รึ? ข้าว่าแล้วว่าพวกเจ้าสองคนต้องเข้ากันได้ดี!" },
        progress = { "38:2062547721:1252490728", "งานที่เจ้าออกไปทำคงสำเร็จด้วยดีใช่ไหม?" },
        required = { [265837] = { "13:1232046453:611945813", "ศีรษะของ Kilgar" } },
        steps = { { "13:1232046453:611945813", "ศีรษะของ Kilgar" } },
    },
    [94892] = { -- Dying Wish
        title = { "10:341987063:1978090794", "คำขอสุดท้าย" },
        description = { "236:2064085172:1248150152", "สายเกินไปสำหรับข้าแล้ว คนแปลกหน้า ข้าคงรอดออกไปไม่ได้ เอาตราของข้าไปให้ผู้บัญชาการอัศวิน เตือนเขาด้วย...\n\n<สายตาของ Ryan เริ่มเลื่อนลอยขณะพึมพำกับตัวเอง>\n\nข้าขอโทษ ข้าน่าจะกลับบ้าน Abigail..." },
        objective = { "77:894581266:1833750771", "นำตราของ Marshal Ryan กลับไปให้ Knight Commander Demar Brant ใน Farholde Keep" },
        completion = { "62:322040645:890619214 C 1:46:46", "เขาทำหน้าที่จนถึงวาระสุดท้ายจริง ๆ ขอบใจที่นำสิ่งนี้มาให้ข้า {class}" },
        progress = { "25:1484555037:625751843", "เจ้าพบจอมพลหรือยัง?" },
        logReady = { "56:840059660:1802563119", "กลับไปหา Knight Commander Demar Brant ที่ Farholde Keep" },
        required = { [266428] = { "20:115888066:1129862878", "ตราของจอมพล Ryan" } },
        steps = { { "20:115888066:1129862878", "ตราของจอมพล Ryan" } },
    },
    [94924] = { -- Hunting the Hunters
        title = { "19:1215424375:1258523029", "ล่าพวกนักล่า" },
        description = { "259:1274621547:1930088869", "พวกออร์คลักลอบล่าสัตว์กระหายเลือด พวกมันฆ่าทุกอย่างที่ขยับได้ ทั้งคน สิงโต และม้า เป็นภัยต่อทุกชีวิตใน Riverglades เราต้องหยุดพวกมัน\n\nพวกมันเที่ยวไปตามทุ่งเป็นฝูงเหมือนสัตว์ติดพิษสุนัขบ้า ถ้าเจอก็กำจัดเสีย" },
        objective = { "47:1726978485:2088025532", "กำจัด Rog'mar Poacher 12 คนให้ Watcher Cornelius" },
        completion = { "141:570336035:1879389973", "โค่นพวกมันไปตั้งหลายตัวสินะ บางทีเจ้าอาจจะไม่ได้อ่อนหัดอย่างที่ข้าคิดแต่แรก\n\nข้าหวังว่าพวกแร้งจะได้กินพวกป่าเถื่อนนั่นจนอิ่ม" },
        objectiveLabels = {
            monster = { ["Rog'mar Poacher slain"] = "ปราบ พรานเถื่อน Rog'mar" },
        },
    },
    [94926] = { -- Drop the Hammer
        title = { "15:1022654511:752646600", "วางค้อนลง" },
        description = { "254:1685293138:505232754", "เหมือนอาวุธโอเกอร์ส่วนใหญ่ ค้อนนี้ทั้งใหญ่ เทอะทะ และสึกจากการใช้งาน สิ่งมีชีวิตเผ่าอื่นแทบจะเหวี่ยงมันไม่ได้เลย\n\nสำหรับเจ้า มันแทบไม่มีประโยชน์นอกจากเป็นของที่ระลึกจากการรบ แต่บางทีคนที่ Farholde อาจอยากรู้ว่า Komuk ตายแล้ว" },
        objective = { "65:174834698:1067398969", "นำ Komuk's Maul ไปที่ Farholde Keep เพื่อเป็นหลักฐานว่าอ็อกเกอร์ตายแล้ว" },
        completion = { "177:980217695:1190687677", "เจ้าว่าอาวุธนี้เป็นของ Komuk หรือ? ยอดเยี่ยม! มีโอกร์จอมโหดให้เราห่วงน้อยลงอีกตัว เจ้าทำให้ถนนปลอดภัยขึ้นสำหรับทหารม้าของเรา ข้าขอชมจากใจ" },
        progress = { "45:1586810432:1664046275 C 1:46:46", "ดูเหมือนเจ้าจะเพิ่งผ่านการต่อสู้มาไม่นานนะ {class}" },
        required = { [266889] = { "15:308255398:1040917782", "ค้อนศึกของ Komuk" } },
        steps = { { "15:308255398:1040917782", "ค้อนศึกของ Komuk" } },
    },
    [94962] = { -- Bloodmaster's Ring
        title = { "18:338070528:848099990", "สังเวียนของ Bloodmaster" },
        description = { "220:421510146:1485147479", "เอาล่ะ เจ้าชนะมาสองสามครั้ง แล้วไง?\n\nยังอีกไกลกว่าจะเป็นแชมป์ เจ้าหนู แต่ข้าจะบอกให้ การต่อสู้ครั้งถัดไปจะเป็นครั้งที่เจ้าลืมไม่ลงแน่\n\nหวังว่าจะพร้อมเจอเรื่องประหลาดใจนะ" },
        objective = { "42:518906679:164354453", "เอาชนะ Bonegnaw ใน Bloodmaster's Ring" },
        completion = { "164:429857054:189355351", "เจ้านี่ไม่ช่วยให้ข้าดูดีขึ้นเลยนะสหาย แต่คงไม่สำคัญเท่าไร ในเมื่อเพื่อนโอกร์ของเราดูจะสนุกกันมาก\nอย่าเพิ่งได้ใจไปล่ะ" },
        objectiveLabels = {
            event = { ["Bonegnaw defeated"] = "เอาชนะ Bonegnaw แล้ว" },
        },
    },
    [94964] = { -- Bloodmaster's Ring
        title = { "18:338070528:848099990", "สังเวียนของ Bloodmaster" },
        description = { "131:868467316:407349571", "มาดูกันว่าจะทำให้คนดูตื่นเต้นกันต่อได้ไหม\n\nคู่แข่งคนถัดไปนี่ไม่ใช่เล่น ๆ\n\nขอให้โชคดี! แล้วเจอกันในอีกเดี๋ยว ถ้าได้เจอกันนะ" },
        objective = { "42:1655464130:471144532", "เอาชนะ Mog'thar ใน Bloodmaster's Ring" },
        completion = { "107:379987111:684462592", "เอาละ พ่อคนเก่ง ตกลงเจ้าบอกว่ามาจากไหนนะ?\nเจ้าเริ่มทำให้ข้าขายหน้าแล้วสิ" },
        objectiveLabels = {
            event = { ["Mog'thar defeated"] = "เอาชนะ Mog'thar แล้ว" },
        },
    },
    [94965] = { -- Bloodmaster's Ring
        title = { "18:338070528:848099990", "สังเวียนของ Bloodmaster" },
        description = { "495:1004646462:2037316076", "เอาล่ะ ข้าจะวางของกินเล่นไว้ แล้วเจ้าลงสังเวียนไปเตรียมรับมือกับสิ่งที่จะตามมา\n\nอะไร? มองข้าอย่างนั้นทำไม? ข้าบอกแล้วว่าเราจะให้อาหารมัน ที่ข้าอาจลืมบอกคือเจ้า Snufflesnout ตื่นเต้นจนแทบคุมไม่อยู่เวลาเห็นของโปรด\n\nเจ้าอยู่ในสถานการณ์ลำบากหน่อยนะ เจ้าหนู การพิสูจน์ตัวเองให้เพื่อนโอเกอร์เห็นสำคัญที่สุด แต่ถ้าเป็นข้าละก็ คงหวั่นใจมากถ้าต้องทำร้ายสัตว์เลี้ยงสุดรักของ Chubchob\n\nเอ้า ไปได้แล้ว!" },
        objective = { "46:1921183915:532152029", "เอาชนะ Snufflesnout ใน Bloodmaster's Ring" },
        completion = { "111:1530238711:1817741446", "ถ้าข้าเป็นเจ้าจะระวังตัวเวลาอยู่แถวนี้ เจ้าอาจก่อเรื่องไว้ไม่น้อยที่เอาชนะเพื่อนของ Chub'chob" },
        objectiveLabels = {
            event = { ["Snufflesnout defeated"] = "เอาชนะ Snufflesnout แล้ว" },
        },
    },
    [94999] = { -- Eyes for the Watchman
        title = { "21:1463752030:1523763456", "ของฝากให้คนเฝ้าด่าน" },
        description = { "486:1957058453:1592951855", "โอ๊ะ! ขอโทษที ข้าไม่ทันเห็นเจ้า\n\nข้ากำลังเตรียมของเล็ก ๆ น้อย ๆ ให้เพื่อนคนหนึ่ง อืม เป็นคนรู้จักมากกว่า เจ้าเคยเจอ Watcher Fredericks หรือยัง? เขาประจำอยู่ที่ Southern Watch ทางตะวันตกของที่นี่\n\nเขาแวะมาที่ฟาร์มตอนลาดตระเวนเป็นครั้งคราว ข้าเลยคิดว่าน่าจะฝากของเล็ก ๆ น้อย ๆ ไปให้เขาแทนคำขอบคุณ\n\nข้าอยากเอาไปให้เอง แต่ต้องคอยดูน้องชายและดูแลฟาร์ม\n\nข้ามั่นใจว่าเจ้าเข้าใจ" },
        objective = { "71:1483979410:1583632038", "นำห่อของฝากจาก Eleanor ไปให้ Watcher Fredericks ที่ Southern Watch" },
        progress = { "20:1504781691:969857892", "มีอะไรจะรายงานไหม?" },
        completion = { "144:172128860:914629641", "โอ้! ของจาก Eleanor หรือ? นางช่างมีน้ำใจจริง ๆ!\n\n<แก้มของเขาแดงขึ้นเล็กน้อย>\n\nไว้ข้าต้องตอบแทนนางบ้างแล้ว ขอบใจที่นำของมาส่งให้" },
        required = { [267244] = { "12:764870275:2010076398", "ห่อของฝาก" } },
        objectiveLabels = {
            item = { ["Care Package"] = "ห่อของฝาก" },
        },
    },
    [95063] = { -- Bloodmaster's Ring
        title = { "18:338070528:848099990", "สังเวียนของ Bloodmaster" },
        description = { "359:1773291448:317284543", "เอาล่ะ ฟังให้ดี เจ้าแสดงฝีมือในสังเวียนได้ไม่เบา และทำให้ Chub'chob ขุ่นเคืองจนพูดไม่ออก ข้าดีใจจริง ๆ ที่ตอนนี้ไม่ได้อยู่ในสถานการณ์ของเจ้า\n\nเผื่อเจ้าสงสัย ข้าขอเตือนว่าค่าสมัครไม่ได้คุ้มครองการเสียชีวิตจากอุบัติเหตุ\n\nยินดีที่ได้รู้จักนะ แต่จากนี้ต้องเอาตัวรอดเองแล้ว เจ้าหนู\n\nขอให้โชคดี" },
        objective = { "183:573119510:1730970634", "เอาชนะ Chub'chob ผู้เป็น Bloodmaster แห่ง Bolder'ok ใน Bloodmaster's Ring แล้วไปบอก Clugfist ที่ Bolder'ok ว่าเจ้าได้เป็นแชมป์คนใหม่ของสังเวียนแล้ว" },
        completion = { "127:1376488042:1481949191", "เจ้าตัวเล็กโชว์พลังในลานประลอง พวกโอกร์ร้องเชียร์\nชัยชนะพาเพื่อนใหม่มาให้เผ่า ทีนี้เจ้าสู้และกินเลี้ยงกับโอกร์ได้แล้ว" },
        objectiveLabels = {
            event = { ["Chub'chob defeated"] = "เอาชนะ Chub'chob แล้ว" },
        },
    },
    [95064] = { -- Preventative Measures
        title = { "21:173027903:957739678", "มาตรการป้องกัน" },
        description = { "287:501109625:1707725476", "พวกออร์คค่อย ๆ รุกเข้ามาจนเป็นภัยตั้งแต่มาถึง ทีแรกยึดที่ดินริมแม่น้ำ ตอนนี้ก็มีพวกมันเพิ่มขึ้นตามทุ่ง...\n\nข้าคงไม่มีวันเข้าใจพวกมัน และพูดตรง ๆ ก็ไม่สนใจจะเข้าใจด้วย แต่ถ้าพวกมันคิดจะยึดที่เพิ่ม ข้าไม่มีวันยอมแน่" },
        objective = { "5:409775429:850574908 W1 58:672550420:1077310571", "ฆ่า Rog'mar Trainee {world1} คนให้ Watcher Cornelius ที่ Terral's Watch" },
        completion = { "93:434590839:1027929853", "พวกมันต้องใช้เวลาอีกพักกว่าจะรวบรวมกำลังได้เท่าเดิม ตอนนี้เราอาจยึดพื้นที่นี้กลับมาได้" },
        objectiveLabels = {
            monster = { ["Rog'mar Trainee slain"] = "ปราบ นักรบฝึกหัด Rog'mar" },
        },
    },
    [95183] = { -- Step One: Rock
        title = { "14:1873648369:918655172", "ขั้นแรก หาหิน" },
        description = { "265:31604041:804484689", "เจ้าอยากได้อาวุธโอเกอร์? ข้าว่าไม่ได้ เจ้าตัวเล็ก ถือไม่ไหว\n\nถ้าเอาหินมาให้ Hamur เพิ่ม ข้าจะทำอาวุธเล็ก ๆ ให้ เหมาะกับตัวเล็ก ๆ อย่างเจ้า\n\nหาหินดี ๆ จะได้อาวุธดี ๆ Hamur ตาถึง ไม่ใช่หินอะไรก็ใช้ได้ ไปหาหินแถวแม่น้ำนอก Bolder'ok" },
        objective = { "7:451016854:1830523975 W1 35:46778184:841088697", "เก็บ Good Rock {world1} ก้อนให้ Hamur ที่ Bolder'ok" },
        completion = { "55:1556834144:594486207", "หินพวกนี้ดี! Hamur จะทำอาวุธจิ๋วให้เจ้าตัวจิ๋ว" },
        progress = { "44:692948860:1408113469", "หินแต่ละก้อนไม่เหมือนกัน บางก้อนดี บางก้อนดีกว่า" },
        required = { [271892] = { "9:489235215:1699102910", "หินดี ๆ" } },
        objectiveLabels = {
            item = { ["Good Rock"] = "หินดี ๆ" },
        },
    },
    [95267] = { -- The Monster Surfaces
        title = { "20:1495778621:1276258039", "สัตว์ประหลาดโผล่พ้นน้ำ" },
        description = { "372:1857039360:1114396503", "ขั้นสุดท้าย <สะอึก> ง่ายนิดเดียว... เอาไส้พุงก้อนโตนั่นไป แล้วก็โยนลงน้ำ! เอ่อ... ไม่ใช่ตรงนี้นะ ไม่งั้นหายนะแน่\n\nไปที่ <สะอึก> เกาะพวกเมอร์ล็อก ที่ที่เจ้าเจอภาพวาด มองหาซากเรือที่เพิ่งแตกในน้ำ ตรงนั้นแหละที่ต้องโยนเหยื่อลงไป\n\nพอมันโผล่หัวขึ้นมาก็ตัดหัวมันทันที! เราจะเอาไปทำของประดับ... ไว้ติดเรือ!" },
        objective = { "96:1493017660:1823161112", "ใช้ Big Ball o' Bait ล่อสัตว์ประหลาดทะเลออกมา แล้วนำหัวของมันไปให้ Argo Brinewhistle" },
        completion = { "217:700870530:1733441728", "อะไรกัน... เจ้าได้มาจริง ๆ เรอะ!? ฮ่า ๆ ๆ!\n<Argo ตะครุบหัวของเจ้าสัตว์อย่างงุ่มง่าม แล้วจ้องเข้าไปในตาของมัน>\nโอ้โห <สะอึก> งามจริง ๆ! ข้าว่าจะเอาไปติดไว้ตรง <สะอึก> ท้ายเรือเลย! คืนนี้ข้าเลี้ยงเหล้าเอง สหาย!" },
        progress = { "36:1565953988:804150892", "มัน... เจ้าสัตว์ประหลาดนั่นตายหรือยัง...?" },
        required = { [268633] = { "18:54689793:1743884213", "ศีรษะอสูรทะเล" }, [268647] = { "16:771217713:1343460265", "เหยื่อก้อนโต" } },
        steps = { { "18:54689793:1743884213", "ศีรษะอสูรทะเล" }, { "16:771217713:1343460265", "เหยื่อก้อนโต" } },
    },
    [95293] = { -- Smuggler's Special
        title = { "18:379237875:362409447", "ของพิเศษสำหรับนักลักลอบค้า" },
        description = { "459:155935931:1655405729", "สินค้าที่เจ้าไปเอามาจากโจรสลัด Eastsea ควรส่งตรงมาถึงข้า แสดงว่าเจ้า Bentcoin คิดจะเข้ามาแย่งเขตทำกินของข้า ดูท่ามันจะหาเรื่องเปิดสงครามการค้า ส่วนพวกเราน่ะเป็นคนมีอารยะ\n\nบทเรียนที่สอง เจ้าลูกน้อง เราไม่ต้องลดตัวไปทำเหมือนพวกนั้น เอาลังที่ข้าจัดให้ท่านกัปตันโดยเฉพาะไป เขาอยู่บนเรือตามชายฝั่ง Eastwind Shore เขาสมควรได้รางวัลสำหรับชั้นเชิงเจรจาอันแยบยลของเขา" },
        objective = { "63:892180158:940913171", "นำ The Friz Special ไปให้ Captain Bentcoin ใน Eastwind Shore" },
        completion = { "90:2132220321:1880263721", "ของขวัญจาก Friz รึ? นางคงรู้ตัวว่าแพ้แล้ว ฮ่า ๆ ๆ!\nเสียงติ๊ก ๆ นั่นเสียงอะไร...?" },
        progress = { "132:592765953:1017338541", "เจ้าโชคดีที่ข้ายังไม่ผ่าร่างเจ้าตั้งแต่หัวจรดเท้าที่กล้าเหยียบเรือข้า ไอ้พวกอยู่แต่บนบก! ไหนหาเหตุผลมาสักข้อว่าทำไมข้าไม่ควรจับเจ้าลากลอดใต้ท้องเรือเดี๋ยวนี้!" },
        steps = { { "24:1214005564:18972166", "ส่งพัสดุของ Friz" } },
    },
    [95321] = { -- Tazzik's Dues
        title = { "13:1374318207:207664742", "เงินที่ต้องจ่ายให้ Tazzik" },
        description = { "374:1105962322:1519867583", "Tazzik ส่งเจ้ามารับเงินพนันที่ชนะหรือ? ล้อกันเล่นใช่ไหม? ยอดนักสู้หน้าเอ๋อของมันอยู่ในสังเวียนได้ไม่ถึงสองนาทีด้วยซ้ำ เจ้าขี้แพ้นั่นไม่ได้สักเหรียญทองแดง\n\nไม่ใช่ธุระของข้าหรอกนะสหาย แต่ถ้าเป็นเจ้า ข้าจะรีบกลับ Steamwheedle Port ระหว่างที่เจ้ายืนคุยกับข้าอยู่ตรงนี้ เจ้าหนูสกปรก Tazzik คงกำลังหาทางกระโดดขึ้นเรือเที่ยวถัดไปหนีแล้ว" },
        objective = { "48:2121087458:1074421866", "ไปเผชิญหน้ากับ Tazzik ที่ Steamwheedle Port ใน Tanaris" },
        completion = { "148:316502278:742522534", "เออ เจ้าเอาชนะข้าได้! ข้าเอาทุกอย่างที่มีไปลงพนันการประลองพวกนั้น หวังจะเอาเงินไปใช้หนี้ Friz แต่เสียหมดตัวเลย!\n\nแต่ข้าคืนของให้นางไม่ได้ เจ้าต้องช่วยข้าหน่อยแล้วล่ะ!" },
        steps = { { "17:576043731:1020876340", "เผชิญหน้ากับ Tazzik" } },
    },
    [95325] = { -- We've Been Robbed!
        title = { "18:1197298976:1536794542", "เราโดนปล้น!" },
        description = { "229:1931679050:1171797090 N 60:1185871277:469146348", "ข้าจ่ายเงินไปไม่น้อยกับลังใบนั้น จะปล่อยให้พวกมันเอาไปเฉย ๆ ไม่ได้!\n\nอยากได้สินค้าของเจ้าคืนไหม? ไปที่ค่าย Venture Co. ทางเหนือแล้วหาว่าใครอยู่เบื้องหลังการหักหลังครั้งนี้! เรื่องนี้เลยเรื่องเงินไปแล้ว {name} มันเป็นเรื่องความยุติธรรม! แล้วก็อาจเกี่ยวกับเงินอยู่นิดหน่อย" },
        objective = { "89:1756713814:1002314072", "ตามหา Venture Co. Ledger ในค่าย Venture Co. ใกล้ Lake Nezferiti ใน Stranglethorn" },
        completion = { "103:1704276139:747999222", "<ตำราเปื้อนคราบจาระบี ภายในเต็มไปด้วยบันทึกข้อตกลงทางธุรกิจระหว่าง Venture Co. กับบรรดาคู่ค้า>" },
    },
    [95424] = { -- Might Makes Right
        title = { "17:1075757421:1760243230", "ผู้แข็งแกร่งคือผู้ถูกต้อง" },
        description = { "190:553114729:905730464", "โอเกอร์ที่นี่เห็นค่าของความแข็งแกร่งกับเลือด\n\nพวกอ่อนแอออกจาก Bolder'ok กลับไปหา Twilight's Hammer\n\nเจ้าตัวไม่ใหญ่ แต่อาจแข็งแกร่ง แสดงพลังให้ Clugfist เห็นแล้วทุบพวกโอเกอร์อ่อนแอ ถ้าเจ้าตัวจิ๋วทำได้นะ" },
        objective = { "5:409775429:850574908 W1 22:501657084:286361937 W2 48:3348314:557697262", "ฆ่า Twilight Mauler {world1} คน และ Twilight Firecaller {world2} คนให้ Clugfist ใน Bolder'ok" },
        completion = { "5:1017438831:1353626593 R 67:461595954:2095676171", "{race} ตัวจิ๋วโชว์พลัง พวก Twilight ล้มตายจนพื้นสั่น ข้ารู้สึกได้จากตรงนี้!" },
        objectiveLabels = {
            monster = { ["Twilight Mauler slain"] = "ปราบ จอมขย้ำ Twilight", ["Twilight Firecaller slain"] = "ปราบ ผู้เรียกเพลิง Twilight" },
        },
    },
    [95425] = { -- Unworthy Champion
        title = { "17:568916144:1423604805", "ยอดนักสู้ผู้ไร้คุณค่า" },
        description = { "336:1516303860:210977208", "Klunk เคยเป็นยอดนักสู้ที่เก่งที่สุดของ Clugfist มันแข็งแรง ข้าให้อาวุธทรงพลังแก่ Klunk\n\nแต่ Clugfist คิดผิด Klunk อ่อนแอเหมือนตัวอื่น มันออกจาก Bolder'ok กลับไปหา Twilight's Hammer พาโอเกอร์ไปถ้ำทางตะวันออกติดน้ำ เอาอาวุธทรงพลังไปด้วย!\n\nนั่นอาวุธของ Clugfist! ทุบกะโหลก Klunk แล้วเอา Skullbasher คืนมา มันไม่ใช่ยอดนักสู้ของใครทั้งนั้น!" },
        objective = { "58:1835363876:2068889893", "นำ Skullthumper จาก Klunk ไปให้ Clugfist ใน Bolder'ok" },
        completion = { "68:120782379:1354754916", "Skullbasher เป็นของโอกร์ตัวจริง สักวัน Clugfist จะเลือกนักสู้เอกคนใหม่" },
        progress = { "37:1146963436:998036929", "อยากได้อะไร? เอา Skullbasher มาเดี๋ยวนี้!" },
        required = { [269257] = { "11:1577053929:214216726", "อาวุธทุบกะโหลก" } },
        steps = { { "11:1577053929:214216726", "อาวุธทุบกะโหลก" } },
    },
    [95432] = { -- Rise Up!
        title = { "8:1507684815:1719264051", "ลุกขึ้นสู้!" },
        description = { "19:1863659874:1065441917 R 57:737393040:345387382 C 113:1657959366:350684697", "พอ Crag'rog ได้ยินว่าเจ้า{race} ตัวน้อยปล่อยโอเกอร์เป็นอิสระ Crag'rog ก็อยากปล่อยโอเกอร์ด้วย\n\nมี {class} ตัวจิ๋วอยู่ด้วย เราจะทุบ Twilight ไปด้วยกัน หักกระดูกพวกมัน ให้พวกมันร้องลั่น ปล่อยโอเกอร์ให้เป็นอิสระ! แล้วกลับบ้านให้ทันกินสตู" },
        objective = { "8:1935349813:1258500633 W1 13:10595090:1773762656", "ชวน Ogre Miner {world1} คนเข้าร่วม" },
        completion = { "98:1463634964:9195237", "เราปล่อยโอกร์เป็นอิสระได้หลายตัว ดี เราฆ่าโอกร์อ่อนแอขี้ขลาด แบบนั้นดีกว่า\nเหลือโอกร์ขี้ขลาดอีกแค่ตัวเดียว" },
        steps = { { "21:619464860:257008883", "ชวนคนงานเหมืองโอเกอร์เข้าร่วม" } },
    },
    [95433] = { -- Death to the Executioner
        title = { "24:1926872619:1449232839", "สังหารเพชฌฆาต" },
        description = { "334:1166775617:758161677", "ตอน Clugfist ออกจาก Twilight มีโอเกอร์ตัวหนึ่งขวางทาง Morg\n\nMorg เป็นโอเกอร์ตัวมหึมา เกือบใหญ่เท่า Clugfist แต่ยังไม่ใหญ่ที่สุด มันต้องให้พวกตัวจิ๋วคอยคุ้มกัน Clugfist ไม่เคยได้สู้แบบยุติธรรม ตอนนี้พวกเราก็จะสู้แบบไม่ยุติธรรมบ้าง\n\nไปหา Morg พาพวกตัวจิ๋วไปเยอะ ๆ ฆ่ามันแล้วเอากระบองกลับมาให้ Clugfist จากนั้น Twilight จะรู้ว่าอย่ามาท้าทายเราอีก!" },
        objective = { "102:1527915193:754430946", "นำ Executioner's Mace จาก Executioner Morg ใน Twilight Shroud ไปให้ Clugfist ใน Bolder'ok" },
        completion = { "19:1978353836:1049668710 R 104:2119358703:1328787116", "Morg ตายแล้ว! {race} ตัวจิ๋วมีลูกเล่นเยอะ Clugfist ชอบเจ้า\nTwilight's Hammer พ่ายต่อพลังของ Bolder'ok เราปลดปล่อยพวกโอกร์แล้ว!" },
        progress = { "67:276327524:1595298258", "Crag'rog บอกว่าเจ้าไปร่วมสู้กับเขา เอาอะไรมาให้ Clugfist ผู้ยิ่งใหญ่?" },
        logReady = { "32:448163239:1354656882", "กลับไปหา Clugfist ที่ Bolder'ok" },
        required = { [269351] = { "18:1925002137:1379294889", "กระบองของเพชฌฆาต" } },
        steps = { { "18:1925002137:1379294889", "กระบองของเพชฌฆาต" } },
    },
    [95642] = { -- Abominable Magics
        title = { "17:1719372013:835760304", "มนตร์อันน่าชิงชัง" },
        description = { "351:1141500031:70334496 C 150:1897383786:208783040", "เจ้าตรงนั้น! ขอบคุณแสงศักดิ์สิทธิ์ที่เจ้ามาถึง Amberhall ส่งเจ้ามาหาข้าหรือ?\n\nเปล่าหรือ? นึกแล้วเชียว Ashe Amberhall ส่งข้าลงมาสืบเรื่อง Twilight's Hammer อย่างที่เห็น พวกมันกำลังขุดหาอะไรสักอย่างใน Riverglades แต่ข้าต้องได้ตัวอย่างเวทมนตร์ของพวกมันถึงจะรู้ว่าหาอะไร\n\nFarholde ต้องได้ตัวอย่างพวกนั้นให้ได้ ได้โปรด {class} เอาตัวเร่งเวทนี่ไป มันลงมนตร์ให้ดูดซับพลังของลัทธิได้ ทั้งรูนหรือพวกลัทธิก็ใช้ได้เหมือนกัน แค่ชูขึ้นสูง ๆ แล้วมันจะทำที่เหลือเอง" },
        objective = { "7:799124967:466741811 W1 151:1140504962:1723009611", "ใช้ Crystal Catalyst ดูดซับตัวอย่าง {world1} ตัวอย่างจากสาวกลัทธิ Twilight's Hammer และวงพิธี Twilight ในถ้ำใต้ Sunnyglade ให้ Apprentice Claire" },
        completion = { "151:383861126:801054257", "<Claire สะดุ้งเมื่อแตะผลึกที่มีเวทมนตร์ของลัทธิแลบเปรี๊ยะ>\nพลังของมันรุนแรงยิ่งกว่าที่ข้าเคยกลัวเสียอีก เราต้องจัดการอย่างระมัดระวัง" },
        progress = { "105:785102618:1521932374", "ระวังพวกตัวใหญ่ไว้ด้วย พวกมันอาจดูทึ่ม ๆ แต่เป็นจอมเวทที่มีพลังไม่เบาเลย" },
        required = { [269990] = { "16:1728280600:1585638937", "ตัวเร่งปฏิกิริยาแบบผลึก" } },
        steps = { { "23:1399419945:1337809327", "เติม Crystal Catalyst จนเต็ม" }, { "16:1728280600:1585638937", "ตัวเร่งปฏิกิริยาแบบผลึก" } },
    },
    [95936] = { -- Hail the Dragonslayer
        title = { "21:1831208003:262484333", "สดุดีผู้สังหารมังกร" },
        description = { "295:1662758975:68842127", "หัวมังกรเต็มไปด้วยฟัน เกล็ด และเถ้า เป็นรางวัลน่าสยดสยองจากสัตว์ร้ายน่าสะพรึงกลัว ขณะถือไว้ เจ้ายังรู้สึกถึงไอร้อนจากลมหายใจเพลิงครั้งสุดท้ายที่แผ่ออกจากปากมัน\n\nภัยจาก Scaldaron หมดไปแล้ว แต่นักรบแห่ง Rog'mar ควรรู้ว่าเกิดอะไรขึ้นที่นี่" },
        objective = { "51:1984947738:1782463248", "นำ Head of Scaldaron ไปให้ Krom'rosh ที่ Rog'mar" },
        completion = { "16:417300123:695607027 N 198:1562489399:1191175242", "อา ข้าอิจฉาเจ้า {name} ถ้าได้ลองคมดาบกับศัตรูอย่างนั้น คงตื่นเต้นน่าดู\nแต่ข้าขอคารวะชัยชนะของเจ้า! เจ้าแสดงทั้งความกล้าและพลัง แถมยังปกป้องพวกเราจากภัยน่ากลัวได้\nทำได้ดี สหายร่วมรบ!" },
        progress = { "38:694655803:849590776 C 34:52424742:1134636244", "ตัวเจ้ามีทั้งรอยไหม้และรอยฟันเต็มไปหมด {class} คงเป็นศึกหนักน่าดู!" },
        required = { [271613] = { "17:199013013:1695613642", "ศีรษะของ Scaldaron" } },
        steps = { { "17:199013013:1695613642", "ศีรษะของ Scaldaron" } },
    },
    [95943] = { -- Foreman's Plight
        title = { "16:105209369:1069033239", "หัวหน้าช่างตกที่นั่งลำบาก" },
        description = { "486:1532716164:1165183874", "สวัสดี ไอ้หนุ่ม ข้าชื่อ Bertrand, Bertrand Ironbrow! ยินดีรับใช้\n\n<Bertrand ยื่นมือที่เปื้อนคราบสกปรกออกมา>\n\nคนดี ๆ พวกนี้จ้างข้ามาคุมงานก่อสร้างป้อมนี้ ถึงประสบการณ์จะน้อย แต่ใจสู้เหลือเกิน! ปัญหาคือข้าทำเครื่องมือหาย\n\nข้าเจอพวก Twilight สองสามตัวในดงไม้เล็ก ๆ ทางตะวันตกเฉียงเหนือ ต้องเลือกระหว่างชีวิตกับเครื่องมือ ข้ารอดมาได้ ส่วนเครื่องมือ... เจ้าคงเดาออก\n\nพอจะช่วยหาเครื่องมือให้ข้าได้ไหม?", variants = { { "486:1532716164:1165183874", "สวัสดี ไอ้หนุ่ม ข้าชื่อ Bertrand, Bertrand Ironbrow! ยินดีรับใช้\n\n<Bertrand ยื่นมือที่เปื้อนคราบสกปรกออกมา>\n\nคนดี ๆ พวกนี้จ้างข้ามาคุมงานก่อสร้างป้อมนี้ ถึงประสบการณ์จะน้อย แต่ใจสู้เหลือเกิน! ปัญหาคือข้าทำเครื่องมือหาย\n\nข้าเจอพวก Twilight สองสามตัวในดงไม้เล็ก ๆ ทางตะวันตกเฉียงเหนือ ต้องเลือกระหว่างชีวิตกับเครื่องมือ ข้ารอดมาได้ ส่วนเครื่องมือ... เจ้าคงเดาออก\n\nพอจะช่วยหาเครื่องมือให้ข้าได้ไหม?", variants = { { "487:1665007502:1038139045", "สวัสดี แม่สาว ข้าชื่อ Bertrand, Bertrand Ironbrow! ยินดีรับใช้\n\n<Bertrand ยื่นมือที่เปื้อนคราบสกปรกออกมา>\n\nคนดี ๆ พวกนี้จ้างข้ามาคุมงานก่อสร้างป้อมนี้ ถึงประสบการณ์จะน้อย แต่ใจสู้เหลือเกิน! ปัญหาคือข้าทำเครื่องมือหาย\n\nข้าเจอพวก Twilight สองสามตัวในดงไม้เล็ก ๆ ทางตะวันตกเฉียงเหนือ ต้องเลือกระหว่างชีวิตกับเครื่องมือ ข้ารอดมาได้ ส่วนเครื่องมือ... เจ้าคงเดาออก\n\nพอจะช่วยหาเครื่องมือให้ข้าได้ไหม?" } } } } },
        objective = { "79:436599229:1759356533", "ตามหา Foreman's Crate แล้วนำกลับไปให้ Bertrand Ironbrow ใน Farholde Keep" },
        progress = { "22:1723569560:724330555", "เจอของของข้าไหม?" },
        completion = { "156:89642980:786080061", "<Bertrand เปิดฝาลังแล้วหยิบแก้วหูจับกับถังเบียร์เอลออกมา>\n\nแบบนี้สิถึงจะเข้าท่า! อีกเดี๋ยวป้อมนี้ก็จะเสร็จแล้ว เจ้าช่วยชีวิตข้าไว้จริง ๆ ไอ้หนุ่ม" },
        required = { [271620] = { "15:1480302712:586339830", "ลังของหัวหน้าคนงาน" } },
        steps = { { "15:1480302712:586339830", "ลังของหัวหน้าคนงาน" } },
    },
    [95955] = { -- Stick 'Em
        title = { "9:859976909:1941022094", "ปาหอกใส่มัน" },
        description = { "308:1969850228:1130175239", "ได้หอกมาแล้ว ทีนี้เจ้าจะได้ฝึกปา\n\nRiverglades มีโครโคลิสก์เต็มไปหมด ตัวแสบทั้งนั้น ถ้าไม่ไวพอมันจะงับเจ้าเข้าไป เหมาะจะใช้ฝึกปาหอกดีนัก ฮ่า ๆ\n\nไปปาหอกใส่พวกมันหลาย ๆ ตัว แล้วกลับมารับรางวัลจาก Tran'jani ถ้าเจ้าปาหอกโดนโครโคลิสก์ ก็ปาโดนได้ทุกอย่าง" },
        objective = { "68:1647661248:1274987454", "ปาหอกให้ปักคร็อกโคลิสก์น้ำจืด 10 ตัว แล้วกลับไปหา Tran'jani ที่ Rog'mar", amount = { "7:609635648:1502648514 W1 59:1737432901:715892619", "ปาหอกให้ปักคร็อกโคลิสก์น้ำจืด {world1} ตัว แล้วกลับไปหา Tran'jani ที่ Rog'mar" } },
        completion = { "121:239299438:1883065686", "ฝีมือไม่เบาเลยพวก! เจ้ามีแววเป็นนักล่าหัวตัวจริง วันไหนได้ดิบได้ดีก็อย่าลืมตา Tan'jani ล่ะ ฮ่า ๆ!" },
    },
    [96027] = { -- Might Over Magic
        title = { "16:1756711140:1515781152", "พลังเหนือเวทมนตร์" },
        description = { "224:1689455965:1424866224", "Bal ต้องติดอยู่กับหัวน่ารำคาญนี่ Bal ไปไหน Mog ก็ตามไปด้วย น่ารำคาญ!\n\nมันบอกว่าเวทมนตร์แกร่งที่สุด เฮอะ ถ้าไม่มี Bal, Mog ก็ไม่มีอะไรให้ร่ายเวทใส่!\n\nBal ไม่ต้องการ Mog! Bal จะแสดงให้เห็นว่ามีหมัดก็พอ เราจะฆ่าพวกตัวจิ๋วเยอะ ๆ ให้ Mog เห็นว่าหมัดดีที่สุด" },
    },
    [96028] = { -- Magic Over Might
        title = { "16:1186459053:1652409026", "เวทมนตร์เหนือพลัง" },
        description = { "156:1760453127:601598914", "Bal โง่ มันเอาแต่จะตีโน่นตีนี่\n\nMog ฉลาด Mog เรียนเวทมนตร์เพื่อทำให้ Bal'mog แข็งแกร่งขึ้น\n\nเราจะแสดงให้ Bal เห็นว่ามันโง่ เราจะใช้เวทมนตร์ ใช้เวทมนตร์ให้เห็นว่า Mog เก่งกว่า!" },
    },
    [97006] = { -- Notarized Claim
        title = { "15:565159438:302833537", "คำร้องที่รับรองแล้ว" },
        description = { "421:1949663095:109432444", "ข้าเขียนหมายเหตุและลงลายมือชื่อไว้ข้างชื่อของข้าในเอกสารฉบับเดิมแล้ว\n\nนำเอกสารไปให้ Royal Overseer Bauhaus ที่สำนักงานสำมะโนประชากรของ Undercity แล้วบอกเขาว่าพบมันที่ไหน เขาต้องรู้ว่าเอกสารมาถึงมือข้าได้อย่างไรในเมื่อข้าอยู่ที่ร้านตลอด\n\nบอกเขาตามตรงได้เลยว่า Abigail Sawyer ไปเล่าเรื่องน่าเวทนาของนางให้คนแปลกหน้าฟังอีกแล้ว และบังเอิญว่าคราวนี้เจ้าช่วยสืบเรื่องให้ได้จริง ๆ\n\nขอบใจอีกครั้งที่ช่วยครอบครัวของข้า" },
        objective = { "85:1176793551:393664528", "นำ Sawyer Family Ledger ไปให้ Royal Overseer Bauhaus ใน Trade Quarter ของ Undercity" },
    },
    [99670] = { -- Return to Jereman
        objective = { "47:1926282100:1995787786", "กลับไปหา Jereman ที่ Cradle of Tranquility" },
        title = { "17:235146479:1678393419", "กลับไปหา Jereman" },
        description = { "191:1687797345:1480619027", "Jereman โชคดีที่ยังมีชีวิตอยู่ ฟังดูเหมือนนางจะรีบเผ่นออกจากที่พักไปทันที คงดีใจมากที่หลุดพ้นจากเรื่องนั้นเสียที\n\nนางคงอยากคุยกับเจ้า ไปหานางเถิด" },
    },
    [93521] = { -- Challenger of the Gods
        objective = { "48:546301650:885922843", "นำ Ve'han's Research Notes ไปให้ Tiala Whitemane" },
        title = { "22:1711596863:649989588", "ผู้ท้าทายเหล่าเทพ" },
        description = { "386:1431857413:684938818", "บันทึกการค้นคว้าของ Ve'han กล่าวถึงความพยายามขโมยพลังของเหล่าเทพแห่งพงไพรตามความมักใหญ่ใฝ่สูงของราชาพงไพร ผู้นำของเขา ที่ทำสำเร็จมีน้อยครั้งและแทบไม่ได้ผลอะไร หากเขาเป็นดรูอิดที่ทรงพลังกว่านี้ เขาคงกลืนกินแก่นพลังของ Jereman ไปในเวลาไม่นาน และได้พลังเพิ่มขึ้นอีก\n\nเหล่าผู้พิทักษ์ Hyjal ที่ค่ายบนยอดเขาต้องอยากรู้เรื่องนี้แน่" },
    },
    [93547] = { -- A Thorny Solution
        title = { "17:1936703413:1995024451", "ใช้หนามแก้ปัญหา" },
        description = { "383:1411939672:812750769", "ที่นี่ถูกคุกคามอยู่ตลอด ทั้งจากกลุ่ม Blackthorne Pact และสัตว์ดุร้ายแห่ง Hyjal แต่เราใช้หนามให้เป็นประโยชน์ได้! อาศัยพลังธรรมชาติสักหน่อย เราก็ปลูกพุ่มหนามเพิ่มเพื่อป้องกันเขตของเราได้\n\nปลูกเมล็ดพุ่มหนามใกล้ถนนเพื่อทำแนวกั้นข้างโรงเตี๊ยม ข้างหอเก็บเสบียง และตรงกลุ่มต้นไม้ริมถนน" },
        objective = { "104:1207960046:2034695305", "ปลูกเมล็ดพุ่มหนามใกล้โรงเตี๊ยม หอเก็บเสบียง และกลุ่มต้นไม้ที่ค่ายของดรูอิดฝ่ายภักดี" },
    },
    [96301] = { -- Power Wash
        title = { "10:1550540577:2086819828", "ชะล้างมลทิน" },
        description = { "396:1814728912:1835946779", "นำหัวใจอาบพิษของคิเมรา Ghansurok ลงไปแช่ในน้ำโบราณแห่งWell of Eternity\n\nสังเกตให้ดีว่าน้ำตอบสนองต่อมลทินอย่างไร และธรรมชาติยังจดจำสิ่งที่มลทินซึ่งแผ่ซ่านไปทั่วพยายามทำลายได้อย่างไร\n\nนำหัวใจกลับมาให้ข้า เราจะอ่านร่องรอยบนนั้นด้วยกัน แล้วดูว่ายังฟื้นคืนสมดุลได้หรือไม่... หรือบาดแผลนั้นลึกเกินเยียวยา" },
        objective = { "79:28454463:371469008", "ลงไปใน Well of Eternity แล้วสังเกตว่าบ่อนี้ส่งผลอย่างไรต่อ Venom-dripping Heart" },
    },
    [96769] = { -- The Darkened Glaive
        title = { "19:1612681649:1850660523", "ดาบวงแหวนต้องมลทิน" },
        description = { "403:169857023:475019877", "Quel'Shalla นั่นคือชื่อที่มนตร์กระซิบกับข้า ข้าเดาว่าคงตีขึ้นให้Sentinel หรือ Warden คนสำคัญสักคน ข้าสงสัยว่าอาจเป็น...\n\n<Lydros เอื้อมมือออกไป นิ้วของเขาเผลอลูบใบดาบขณะพูด ทันทีที่ผิวแตะโลหะ เขาก็ชะงักนิ่ง>\n\nเดี๋ยว...\n\nไม่สิ... เดี๋ยวก่อน... มีอย่างอื่นอยู่ในนี้ ความมืด ข้า... ข้าทำต่อไม่ได้ ได้โปรด เอาดาบออกไปให้พ้นตาข้าเดี๋ยวนี้!" },
    },
    [97272] = { -- The Darkened Glaive
        title = { "19:1612681649:1850660523", "ดาบวงแหวนต้องมลทิน" },
        description = { "452:361547544:2119112995", "ข้าได้กลิ่นเหม็นของมลทินปีศาจจากดาบวงแหวนเล่มนี้ตั้งแต่แรก ปีศาจที่แผ่อิทธิพลใส่มันคงทรงพลังมาก ขนาดเอลฟ์ Shen'dralar เองยังไม่อยากยุ่งด้วย\n\nการอัดมลทินลงไปมากพอให้ของวิเศษที่เปี่ยมมนตร์อย่างหนึ่งใน «ศัสตราหลากสี» ในตำนานแปดเปื้อน ย่อมทิ้งสายสัมพันธ์กับต้นตอไว้ ถ้าเจ้ากล้าพอก็ใช้สายสัมพันธ์นั้นให้เป็นประโยชน์ได้\n\nข้าจะอธิบายว่าต้องทำอะไร" },
    },
    [92016] = { -- Rootwork
        title = { "8:1050032713:1201229308", "สำรวจรากไม้โลก" },
        description = { "503:1423134452:2006215227", "รากของ Nordrassil แผ่ออกไปไกลและหยั่งลึก หนายิ่งกว่าตลิ่งแม่น้ำและเก่าแก่เกินกว่าใครจะจำได้ ยิ่งใหญ่เพียงนี้ย่อมต้องกินมากเป็นธรรมดา ยามสมบูรณ์ดี รากเหล่านี้ดูดซับทั้งสิ่งที่ผุพังและสิ่งที่เกิดใหม่ รับพลังจากวัฏจักรธรรมชาติที่หมุนเวียนไม่สิ้นสุด\n\nแต่ Hyjal ได้รับบาดแผล ผืนดินแปดเปื้อนพิษปีศาจ\n\nลงไปยังส่วนที่ลึกที่สุดของWell of Eternityและตรวจดูรากให้ละเอียด เราต้องรู้ว่ารากดูดซับมลทินไปมากเกินไปหรือยัง... และไม้โลกยังยืนหยัดต่อไปได้หรือไม่" },
        objective = { "63:1842357001:2111777280", "ลงไปใน Well of Eternity แล้วตรวจดูรากของ Nordrassil" },
    },
    [96302] = { -- Arch Absolution
        title = { "15:1318421740:1097654821", "พิธีคลายความหวาดกลัว" },
        description = { "474:754554050:1423470976", "ข้าอัดยางไม้กลิ่นฉุนที่มีฤทธิ์แรงนี้ไว้แล้ว นำเครื่องหอมนี้ไปยืนต่อหน้าซากของ The Defiler\n\nเมื่อควันลอยขึ้น ให้กล่าวมนตร์เพื่อให้จิตใจสงบ โดยปล่อยสิ่งที่ยังหลงเหลือไว้ที่เดิม รูปลักษณ์ของเขายังเตือนให้นึกถึงความสยดสยอง แม้ตอนนี้ก็ยังทำให้คนที่อยู่ใกล้นานเกินไปหวาดกลัว\n\nให้ควันนำความสงบและความแน่วแน่มาคุ้มกันใจจากความหวาดหวั่น เพื่อให้ผู้ที่เดินผ่านที่นี่จดจำชัยชนะเหนือความสยดสยองนั้น" },
        objective = { "84:1519077192:746306969", "นำธูปของ Marn ไปให้ควันจากธูปคุ้มกันบริเวณรอบซากของ Archimonde" },
    },
    [96303] = { -- Memory Mist
        title = { "11:373366558:401896301", "หมอกแห่งความทรงจำ" },
        description = { "N 474:2088553350:2128065723", "{name} วิญญาณบรรพชนที่ถูกเรียกมายัง Hyjal ในมหาศึกครั้งนั้นยังอยู่กันบ้าง หลังการเสียสละครั้งใหญ่ บางดวงถูกดึงดูดมายัง Nordrassil วิสป์เหล่านี้ยังวนเวียนในหมู่รากไม้ที่แผ่คลุมบ่อ ติดค้างอยู่ระหว่างโลกนี้กับโลกหน้า\n\nใช้กิ่งไม้ลงมนตร์นี้นำความสงบมาสู่วิสป์ และฝากความทรงจำของพวกเขาไว้กับกาลนิรันดร์\n\nเจ้าไม่จำเป็นต้องปลดปล่อยทุกดวงด้วยตัวเอง รวบรวมเจตจำนงของวิสป์ห้าดวง แล้วนำกิ่งไม้กลับมาให้เรา" },
        objective = { "62:677729977:1994683870", "ใช้กิ่งไม้ลงมนตร์ (Enchanted Branch) ปลดปล่อยวิสป์ 5 ดวงรอบ Nordrassil", amount = { "36:307772620:1032705918 W1 25:431300715:1676578315", "ใช้กิ่งไม้ลงมนตร์ (Enchanted Branch) ปลดปล่อยวิสป์ {world1} ดวงรอบ Nordrassil" } },
    },
    [96561] = { -- Last Wishes
        title = { "11:775708039:2010270958", "ความปรารถนาครั้งสุดท้าย" },
        description = { "456:644815919:284563860", "<เจ้าคลี่แผ่นหนังเรียบ ๆ ออก>\n\nถึงพวกกบฏจอมโวยแห่ง Redridge ของข้า\n\nพวกคนตัดไม้ที่นี่บอกว่าปลาในบ่องับเหยื่อไวเหมือนแข่งกันกิน ตกก็สนุก เอามากินยิ่งอร่อย พอสงครามจบ เรามาแข่งตกปลากันในหมู่เพื่อนเถอะ\n\nกติกาง่าย ๆ เราไปยืนบนเกาะกลางบ่อ ตกกันจนตะวันลับยอดสูงสุดของ Hyjal\n\nใครตกได้มากที่สุด ไม่ต้องควักไส้ปลาเตรียมมื้อเย็น!\n\n-- Tobin --" },
        objective = { "90:1538489468:2063002365", "หาบ่อตกปลาใกล้โรงเลื่อยของ Alliance ที่ถูกทำลายใน Cradle of Tranquility" },
    },
    [90750] = { -- More Work?
        title = { "10:180504425:730252114", "ยังมีงานอีกหรือ?" },
        description = { "489:1347729698:1965368208", "การรบมักยืดเยื้อและยากลำบาก ผู้นำทัพต้องกล้ายืนขวางภัยที่กำลังประชิดและเผชิญหน้ากับความตาย\n\nความจริงแล้วมีคนเสียสละมากมายทั้งในสนามรบและที่อื่น เรามักมองข้ามคนที่ช่วยทำหน้าที่ในส่วนของตัวเอง\n\nตรงโน้นมีชาวบ้านคนหนึ่งชื่อ... เอ พอมานึกดูแล้วข้ายังไม่รู้ชื่อเขาเลย ข้านี่ใช้ได้ที่ไหนกัน เขาคอยดูแลให้พวกเราอยู่ดีกินอิ่มตลอดเวลาที่อยู่ที่นี่\n\nเจ้าไปคุยกับเขาหน่อยได้ไหม บอกเขาว่างานเสร็จแล้ว" },
        objective = { "54:264517848:1728593168", "ไปคุยกับชาวบ้านเพื่อบอกเขาว่างานเสร็จแล้ว" },
    },
    [93127] = { -- Summit Sentries
        title = { "15:2054081862:172732844", "ผู้เฝ้ายอดเขา" },
        description = { "500:872276968:605892504", "ราชาพงไพรอาจมีกำลังพลเหนือกว่า แต่เราเอาชนะเขาด้วยกลยุทธ์ได้\n\nเติมพลังให้ศิลาผู้เฝ้ายามที่มีชีวิตของเราตามเนินเขารอบ ๆ มันช่วยติดตามความเคลื่อนไหวของพวก Blackthorne ได้ ทั้งสันเขาด้านเหนือ ลาดเขาด้านใต้ และที่สูงทางตะวันตกต่างมีศิลาที่พลังหมดอยู่ เมื่อมันรู้ว่ามิตรเข้าใกล้ก็จะตื่นขึ้น\n\nระวังตัวระหว่างลงมือ หน่วยลาดตระเวน Blackthorne อยู่เต็มเส้นทาง พวกมันนี่แหละคือเหตุผลที่เราต้องเฝ้าพื้นที่นี้อย่างใกล้ชิด" },
        objective = { "86:139506991:919309317", "ปลุกศิลาผู้พิทักษ์ทางเหนือ ตะวันตก และใต้ของกลุ่มสาวก Blackthorne ให้ทำงานอีกครั้ง" },
    },
    [90487] = { -- Ancient Allies
        title = { "14:1456463929:566077815", "พันธมิตรแต่โบราณ" },
        description = { "N 388:321214084:1212325740", "{name} ข้าคงช่วยอะไรเจ้าได้อีกไม่มากนัก หากเจ้าจะเดินทางไกลขึ้นไปบนเขา ลองคุยกับผู้ดูแลภูเขาที่อยู่มานานดูสักคนเถิด\n\nตามถนนไปทางตะวันตก มองไปทางเหนือที่เชิงเขา เดี๋ยวเจ้าจะเห็นด่านที่เหล่าผู้พิทักษ์ซึ่งเคยเดินทั่วลาดเขาทิ้งไว้ ที่นั่นมีหนึ่งในเหล่า Ancient ชื่อ Fraxinus เขากับเพื่อน ๆ ช่วยเจ้าได้" },
        objective = { "112:1478265408:1580707465", "เดินทางไปทางตะวันตกจากถ้ำฤๅษี เพื่อหาด่านของเหล่า Ancient และดรายแอดบนลาดเขาช่วงล่างของ Mount Hyjal" },
    },
    [91770] = { -- Bark Bite
        title = { "9:500781809:1935501406", "เยียวยาเปลือกไม้" },
        description = { "366:76758158:834623770", "ข้าเอาของที่เจ้านำมาทำยาง่าย ๆ ได้ ยาพอกนี้น่าจะช่วย Fraxinus ได้ เจ้าก็รู้ว่าเขาอายุมากแล้ว และถูกไฟลวกสาหัสในช่วงสงคราม เปลือกของเขาเจ็บ กิ่งก้านก็ปวดระบม เขาเป็นเพื่อนรักที่สุดของข้า ข้าแค่อยากให้เขารู้สึกดีขึ้น!\n\nเอายาพอกนี้ไปทาหนา ๆ ให้ทั่วทุกจุดที่เปลือกปริและมีน้ำเลี้ยงไหลออกมา" },
        objective = { "31:1343186472:773200678", "ใช้ยาพอกกับ Fraxinus" },
    },
    [92064] = { -- Tree Free
        title = { "9:1847266319:1340325740", "ช่วยลงจากต้นไม้" },
        description = { "340:906996018:375899152", "ลองวิธีอื่นกัน เห็นกิ่งข้างบนนั่นไหม? ใช่ กิ่งนั้นแหละ! ช่วยหักมันให้หน่อย ข้ายังมีเชือกตั้งหลายเส้นพันอยู่ที่อื่น คงไม่ถึงขั้นเกิดหายนะหรอก... หวังว่านะ\n\nถอยไปยืนตรงที่ปลอดภัย แล้วหวดกิ่งนี้สักสองสามทีได้ไหม?\n\n<Fenwick ชี้ไปยังอะไรบางอย่างเหนือหัวเขา>\n\nระวังด้วยนะ!" },
        objective = { "51:909870894:1235364169", "หักกิ่งไม้เพื่อช่วย Fenwick Togglespring ให้หลุดออกมา" },
    },
    [92702] = { -- Branch Out
        title = { "10:2032701927:1270645360", "กิ่งไม้ช่วยชีวิต" },
        description = { "491:1284485638:1618203057", "<Fenwick พยายามโยกตัวไปมาเพื่อให้ตัวเองแกว่ง>\n\nเฮ้! เจ้าน่ะ! หากิ่งไม้สักอันมาลองยื่นให้ถึงข้าหน่อยได้ไหม? ข้าติดอยู่นี่นานจนสายเอี๊ยมเสียดสีตัวไปหมดแล้ว! ข้ามีเรื่องดี ๆ จะเล่าให้ฟัง เรื่องดีสุด ๆ เลย! Fenwick Togglespring ไม่เคยรับปากส่งเดช!\n\nเจ้าพี่น้องตัวขึ้นสนิมของข้าที่ฐานปล่อยต่างหาก เห็นชัดว่าคำนวณสมรรถนะจรวดของเราพลาดไปหลายอย่าง! เจ้านั่นแหละจอมรับปากส่งเดช!\n\n<Fenwick เอื้อมคว้าของที่อยู่ไกลเกินมือแต่ไม่ถึง>" },
        objective = { "64:1903281005:459065439", "หากิ่งไม้แข็งแรงที่ยื่นไปถึงตัว Fenwick Togglespring ได้" },
    },
    [94479] = { -- One Person's Trash
        title = { "18:723202725:1220571548", "ของทิ้งของใครคนหนึ่ง" },
        description = { "214:1266112728:1720995650", "เมื่อหยิบเศษโลหะที่กำลังขึ้นสนิมขึ้นมา เจ้าก็เห็นชิ้นส่วนเครื่องกลอีกชิ้นที่เงากว่า ดูเหมือนของอื่นที่ยังใช้ได้จะถูกเก็บไปหมดแล้ว\n\nบางทีคนแถวนี้อาจรู้จักชิ้นส่วนนี้ หรือรู้ว่าใครอยากเก็บไปใช้ต่อ" },
        objective = { "84:1413213467:1993330398", "ค้นหาใน Tainted Foothills ว่ามีใครสนใจชิ้นส่วนโลหะที่เจ้าเจอบ้าง" },
    },
    [95218] = { -- More of the Same
        title = { "16:2015827135:1626198365", "ก็ยังเหมือนเดิม" },
        description = { "496:504067714:1247683649", "แสงศักดิ์สิทธิ์ทอดทิ้งข้าแล้ว หน้าที่ก็ทำเสร็จแล้ว ตอนนี้ทุกอย่าง... สูญสิ้น...\n\nอีกไม่นานแสงก็จะกลายเป็นความมืด\n\nข้าสู้กับปีศาจและกองทัพ Scourge อย่างดุดันจนไม่เคยคิดว่าแสงศักดิ์สิทธิ์จะให้พลังข้าได้ถึงเพียงนั้น... แต่ข้ากลับมานั่งพูดกับเจ้าอยู่ตรงนี้ รู้สึก... ข้าก็อธิบายไม่ถูก บางคนผ่านความสูญเสียแล้วกลับมามีเป้าหมายอีกครั้ง ส่วนข้ายังทำใจไม่ได้... สุดท้ายข้าก็เป็นได้เท่าที่ข้าเป็น\n\nหากผู้บัญชาการไม่มีคำสั่งให้ลงมืออีกสักครั้ง ข้าก็จะรอดูว่าจะเกิดอะไรต่อไป" },
        objective = { "29:912864804:1096120623", "ไปคุยกับ Sefira Everbright" },
    },
    [95766] = { -- Fine Feathered Friend
        title = { "21:620408907:1353733497", "สหายขนปีก" },
        description = { "416:821752235:660718022", "วัฏจักรแห่งการฟื้นคืนเริ่มขึ้นเสียที เหล่า Ancient... จะยืนหยัดขึ้นอีกครั้ง พลังของธรรมชาติจะดำเนินไปตามทางของมัน... และผลิบาน\n\nเจ้า... ช่วยพลิกดุลกลับมาเข้าข้างธรรมชาติ บางที... เรายังอาจทำอะไรได้มากกว่านี้... ในที่ที่สถานการณ์เลวร้ายกว่าเดิม\n\nไปทางตะวันตก... ตรงที่ผืนดินกลายเป็นเถ้า เจ้าอาจพบผู้ที่ช่วยได้ นางดูเหมือนนกตัวเล็ก ๆ... แต่พลังของนางนั้นยิ่งใหญ่" },
        objective = { "68:160895124:1289405339", "ตามหานกประหลาดในดินแดนที่ถูกพลังชั่วร้ายครอบงำบริเวณลาดเขาด้านตะวันตกเฉียงใต้" },
    },
    [96796] = { -- Woods Workshop
        title = { "14:1893232027:337870572", "โรงช่างในป่า" },
        description = { "501:1525452426:345730382", "ดูเหมือนช่างประดิษฐ์บนเนินเขาที่ชื่อ Kaylaena จะใช้ของชิ้นนี้ได้ นางแทบไม่แวะมาที่นี่เลยตั้งแต่สูญเสีย Yaely ผู้เป็นอาจารย์\n\nหาโรงช่างของนางตามเนินเขาด้านเหนือ หลัง Archimonde พ่ายในมหาศึก ทั้งสองคนออกเก็บซากที่พอขนกลับมาเองได้ จนเครื่องจักรตามเชิงเขาหลายเครื่องแทบไม่เหลือชิ้นส่วน\n\nเอาเศษซากไปใช้ใหม่ย่อมดีกว่าปล่อยให้ขึ้นสนิมที่นี่ งานนี้ของเจ้าช่วยให้ชีวิตใหม่งอกขึ้นในที่ที่เคยถูกโลหะเบียดจนอยู่ไม่ได้" },
        objective = { "68:1925494906:1234835402", "นำอะไหล่ (Spare Part) ไปให้ช่างชื่อ Kaylaena บนลาดเขาช่วงล่างของ Hyjal" },
    },
    [96833] = { -- Venom Maws
        title = { "10:1946854082:193710275", "เขี้ยวพิษ" },
        description = { "479:542776769:260619908", "กะ... Ghan... Sur... Okk... Ghansurok นั่นคือชื่อคิเมราเฟล ข้าคิดว่าข้าเอาอยู่... อึก... คนเดียว ที่ไหนได้ มันโฉบยกข้าขึ้นไปกลางอากาศเลย\n\nข้าแทงมีดสั้นเข้าตาที่อยู่ใกล้มือที่สุด แล้วก็ร่วงลงมาจากที่สูงกว่ายอดไม้\n\nคราวนี้ไม่ได้มีข้าคนเดียวที่กัดคำใหญ่เกินจะกลืน ฮ่า ๆ... โอ๊ย... ไม่น่าหัวเราะเลย แค่นี้ก็เจ็บจะแย่แล้ว\n\nกระดูกหักยังรักษาได้ แต่... พิษมันร้ายเกินไป\n\nช่วยเตือนคนอื่นด้วย ข้าขอร้อง!" },
        objective = { "92:203799491:883972943", "เตือนคนอื่น ๆ บนภูเขาให้ระวังไคมีราดุร้ายชื่อ Ghansurok" },
    },
    [91697] = { -- Meet the Elders
        title = { "15:909365173:1901623168", "พบผู้อาวุโส" },
        description = { "204:226392975:1215610012", "ขอบใจที่ช่วยเก็บผล Bear Berries ความไว้ใจค่อย ๆ สร้างได้! พอได้กลิ่นยางเบอร์รีติดตัวเจ้า พวกผู้อาวุโสก็น่าจะเต็มใจต้อนรับเจ้ามากขึ้น\n\nไปคุยกับ Elder Mistpaw และ Elder Pinespeaker" },
        objective = { "79:1814676373:1080799153", "ตามหาและคุยกับ Elder Mistpaw และ Elder Pinespeaker ใน Barkskin Burrow" },
    },
    [91881] = { -- The Western Post
        title = { "16:503512236:1873920905", "ด่านตะวันตก" },
        description = { "352:2072822601:1416354341", "พอคุมพวกวอร์ล็อกได้แล้ว แถวนี้ก็อยู่ใต้ปีกเรียบร้อยดี\n\n<อีกาพยักหน้าอย่างผู้รู้ ดูพอใจ>\n\nงานของเราที่นี่เสร็จแล้ว แต่ที่อื่นยังต้องการคนช่วย ในฐานะที่เจ้าอยู่ใต้ปีกข้า ข้าอยากให้เจ้าไปดูว่าเกิดเรื่องอะไรขึ้น\n\nเดินตามถนนขึ้นไปทางตะวันตกเฉียงเหนือจนถึงด่านเก่าของพวกนกนางนวลแกลบ เพื่อนเก่ารออยู่!" },
        objective = { "38:1545931512:467676196", "ไปพบ Sefira Everbright ที่ด่านหน้า" },
    },
    [92094] = { -- Rocket Gnomes
        objective = { "131:1193281029:480205731", "Wennzut Togglespring มองไม่เห็น Fenwick พี่น้องของเขาที่ลอยด้วยร่มชูชีพเข้าไปใน Hyjal แล้ว จงตามหาว่าเขาอาจไปตกอยู่ที่ใด" },
        title = { "13:1890888701:1007716912", "โนมจรวด" },
        description = { "367:1954204996:520300530", "Fenwick พี่น้องของข้ากับข้าเพิ่งทดสอบจรวดสำเร็จ ปัญหามีอย่างเดียว เขายังไม่กลับมาเลย! พอร่มชูชีพของเขากางออก เขาก็ลอยลงไปทางใต้จนข้ามองไม่เห็น\n\nดูท่าว่าเขาอาจลงไปตกที่ Hyjal!\n\nถ้าเจ้าช่วยให้เขาออกมาจากจุดที่ตกได้ เขาต้องหาทางตอบแทนเจ้าแน่ ข้าเองก็จะซาบซึ้งที่ได้พี่น้องกลับมา!" },
    },
    [92111] = { -- Of Friend and Fur
        title = { "17:234189105:1222792457", "มิตรภาพในถ้ำหมี" },
        description = { "179:839857281:1872804480", "ข้าเห็นเจ้าพยายาม แค่พยายามก็ยิ่งกว่าที่คนส่วนใหญ่ทำแล้ว พอเวลาผ่านไปเราจะมีไมตรีให้เจ้า ถ้าเจ้ามีไมตรีให้เราเหมือนกัน\n\nเข้าถ้ำเราไปคุยกับ Osi นางยินดีอ้าอุ้งเท้าต้อนรับเจ้า และจะให้โอกาสเจ้าช่วยเราอีก" },
        objective = { "57:1785804162:1536373924", "เข้าไปใน Barkskin Burrow แล้วตามหาเฟอร์โบลกที่ชื่อ Osi" },
    },
    [94782] = { -- The Western Post
        title = { "16:503512236:1873920905", "ด่านตะวันตก" },
        description = { "347:2106159164:331961001", "พอคุมพวกวอร์ล็อกได้แล้ว แถวนี้ก็อยู่ใต้ปีกเรียบร้อยดี\n\n<อีกาพยักหน้าอย่างผู้รู้ ดูพอใจ>\n\nงานของเราที่นี่เสร็จแล้ว แต่ที่อื่นยังต้องการคนช่วย ในฐานะที่เจ้าอยู่ใต้ปีกข้า ข้าอยากให้เจ้าไปดูว่าเกิดเรื่องอะไรขึ้น\n\nเดินตามถนนขึ้นไปทางตะวันตกเฉียงเหนือจนถึงด่านเก่า เพื่อนเก่ารออยู่!" },
        objective = { "28:1504007450:1564300803", "ไปพบ Zet'gan ที่ด่านหน้า" },
    },
    [95320] = { -- A Curious Question
        title = { "18:1840756827:1242601015", "เรื่องที่ชวนสงสัย" },
        description = { "475:2087396374:2079059130", "เลยขึ้นไปตามถนน ใกล้ทางเข้าค่ายของพวกนักเวทผู้ใช้พลังปีศาจ มีปีศาจตัวหนึ่งถูกขังกรงและเอะอะโวยวายใหญ่\n\nมันพล่ามไม่หยุดเรื่องถูกขังกับเรื่องอิสรภาพ แถมพูดอะไรสักอย่างเรื่องเผากระดูกกับการแก้แค้นด้วย?\n\n<อีกาโน้มเข้ามามองเจ้าอย่างเจ้าเล่ห์ แล้วแกว่งกุญแจเหล็กในกรงเล็บข้างหนึ่งเหมือนจะย้ำให้เห็น>\n\nลองไปตกลงกับ «เพื่อน» ตัวน้อยของเราดู เผื่อจะรู้ว่ามันรู้อะไรเกี่ยวกับพวกนักเวทผู้ใช้พลังปีศาจจอมชั่วร้ายนี้บ้าง" },
        objective = { "26:789396845:940758399", "ตามหาปีศาจที่ถูกคุมขัง" },
    },
    [96978] = { -- Violent Venison
        title = { "15:324672860:644472557", "เมื่อกวางอยากเป็นนักล่า" },
        description = { "492:707957683:1468654650", "ตั้งแต่ดรูอิด Blackthorne พวกนั้นเรืองอำนาจ เหล่าเทพที่พลังไม่มากนักใน Hyjal หลายองค์ก็... พูดตรง ๆ ก็คือพยายามพลิกระเบียบธรรมชาติให้กลับตาลปัตร\n\nตัวต้นเรื่องที่หนักที่สุดคือ Kala'th\n\n<Jereman กลอกตา>\n\nกวางซื่อบื้อตัวนั้นคงคิดว่าตัวเองกับทั้งฝูงเป็นสัตว์นักล่า อีกแล้ว\n\nตอนแรกข้าก็ขำอยู่หรอก แต่ถึงเวลาจัดเรื่องนี้ให้เข้าที่เข้าทางเสียที\n\nช่วยไปคุยกับนางที ดูว่าจะทำให้นางได้สติไหม" },
        objective = { "31:645405530:1386842016", "ไปคุยกับ Kala'th เทพแห่งพงไพร" },
    },
    [92171] = { -- Taking to New Heights
        title = { "21:333585245:1942510195", "ขึ้นสู่ฟากฟ้า" },
        description = { "267:1785230075:1881119498", "หากจะเอาชนะ Ve'han เราต้องอาศัยสัมผัสจากฟากฟ้า พลังศักดิ์สิทธิ์สักนิดจากที่ที่ผู้แหงนมองต่างใฝ่ฝันจะโบยบิน\n\nไปยังศาลเจ้า Aviana แล้วตามหา Skylord Omnuron เขาเป็นผู้นำของเหล่าดรูอิดแห่งกรงเล็บและช่วยเติมพรของ Aviana ให้เราได้" },
        objective = { "83:505762295:1646091390", "เดินทางไปยัง Shrine of Aviana บน Mount Hyjal แล้วขอความช่วยเหลือจาก Skylord Omnuron" },
    },
    [92500] = { -- A Bit of the Sky
        title = { "16:520890079:238980682", "พลังส่วนหนึ่งจากฟากฟ้า" },
        description = { "429:439933652:667868919", "ตั้งแต่ศาลเจ้า Aviana ทรุดโทรม พวกฮาร์ปี Wormwing ก็ลอบเข้ามาขโมยวัตถุศักดิ์สิทธิ์ของดรูอิดที่เหลืออยู่ไปจนหมด หนึ่งในนั้นคือJewel of the Horizon อัญมณีสีน้ำเงินเปล่งประกายที่เทพีปักษาประทานพรด้วยพระองค์เอง สัมผัสของ Aviana อาจมีพลังเวทที่เจ้าต้องใช้ในงานนี้พอดี\n\nพวก Wormwing คงซ่อนมันไว้ในรังใดรังหนึ่งหรือใกล้ ๆ รัง พอหาเจอแล้วนำไปให้ Ketharas" },
        objective = { "98:1437212949:1256365870", "หา Jewel of the Horizon ในรังฮาร์ปี Wormwing บน Mount Hyjal แล้วนำไปให้ Ketharas" },
    },
    [93269] = { -- Top of the Post
        title = { "15:183982835:923666191", "ส่งจดหมายขึ้นเขา" },
        description = { "118:173252473:2046605226", "ตอนนี้เจ้าเอาจดหมายคืนมาได้ครบแล้ว ก็ขนทั้งหมดกลับไปยัง Mount Hyjal ได้เลย!\n\nไม่น่ามีปัญหาหรอก จริงไหม?" },
        objective = { "77:1781874731:46949562", "นำจดหมายจาก Everlook ขึ้นไปให้เจ้าของโรงเตี๊ยม Sebelia บนยอดเขา Hyjal" },
    },
    [96131] = { -- An Oldstone But An Old Friend
        title = { "29:1229317368:1428984642", "หินหัวเก่า แต่เป็นเพื่อนเก่า" },
        description = { "409:1392897601:883644158", "เจ้าเคยเจอตาแก่หัวโบราณที่อยู่ในถ้ำทางใต้ของที่นี่แล้วใช่ไหม?\n\nเอาคทานี้กับขนของข้าไปให้เขา เขาคงรู้ว่าหมายถึงอะไร หรืออาจไม่รู้ก็ได้! ยังไงก็เรียกความสนใจจากเขาได้แน่\n\nเขาอาจหัวแข็งเป็นหิน แต่ไว้ใจได้ เป็นหนึ่งในผู้มีวันตายไม่กี่คนที่ข้าไว้ใจให้ช่วยเรื่องหนักหนาขนาดนี้\n\nเร็วเข้า เจ้าพวกเดินดิน! ข้ากลัวว่าเงาที่เรามองไม่เห็นกำลังทอดคลุม Hyjal" },
        objective = { "44:2016274561:1488858673", "นำกิ่งไม้เรืองแสงจาง ๆ (Faintly Glowing Branch) ไปให้ Ketharas" },
    },
    [96321] = { -- The Dying God
        title = { "13:1363353704:56290303", "เทพที่กำลังสิ้นลม" },
        description = { "439:199012933:792562432", "ข้า... เหลือเวลาไม่มากแล้ว ผู้มีวันตาย เอาคทานี้ไป กิ่งจากไม้โลก... แปดเปื้อน... ผิดธรรมชาติ ข้านำมันมาถึงที่นี่...\n\nเหล่าเทพแห่งพงไพร... ต้องรู้เรื่องนี้ เอาไปให้นาง... อีกา...\n\n<เทพแห่งพงไพรที่กำลังสิ้นลมหยุดนิ่ง ดวงตาเหม่อไปเบื้องหน้า ร่างที่เหลืออยู่เพียงน้อยนิดดูเหมือนจะแตกสลายและลอยหายไป บนพื้นมีกิ่งไม้เรืองแสงจาง ๆ ปลายกิ่งติดผลึกสีเขียวหม่นชวนไม่สบายใจ>" },
        objective = { "79:2052125498:2092975431", "ตามหาคนบน Mount Hyjal ที่อาจสนใจคทาเรืองแสงจาง ๆ (Faintly Glowing Staff)" },
    },
    [96435] = { -- A Fitting End
        title = { "13:762598758:2035983367", "จุดจบที่สาสม" },
        description = { "499:657960506:1328185851", "<Felflick หัวเราะลั่นอย่างชอบใจขณะมองกระดูกเปื้อนเลือดของพวกผู้นำ Ashen Reign>\n\nโอ้ เยี่ยมไปเลย!\n\n<Felflick กระโดดไปมาในกรงพลางหัวเราะคิกคักไม่หยุด>\n\nถึงเวลามอบจุดจบที่พวกวอร์ล็อกสมควรได้รับแล้ว ตามถนนไปทางตะวันตกจะเจอกองกระดูกมหึมา เชื่อข้าเถอะ ไม่มีทางมองข้ามได้หรอก พวกมันเอาผลงานทดลองที่ «ล้มเหลว» ไปทิ้งที่นั่นหมด\n\nข้าอยากให้เอาซากพวกโง่นี่ไปโยนทิ้งที่นั่น ให้ทั้งโลกรู้ว่าพวกมันล้มเหลวแค่ไหน!" },
        objective = { "64:221401581:825513084", "โยนกระดูกของวอร์ล็อกลงบนกองกระดูกใกล้บ่อเมือก" },
    },
    [96930] = { -- The Capricious Corvid
        title = { "21:769381995:1622455689", "อีกาผู้เอาแน่เอานอนไม่ได้" },
        description = { "468:840074376:1785377919", "เราต้องใช้เวทที่ทรงพลังมากจึงจะต้านพลังที่ Ve'han Talongrasp ครอบครองอยู่ได้ คทาที่ Velician ชิงมาอาจเป็นกุญแจสำคัญ\n\nพลังดรูอิดของข้าไม่เหมือนเมื่อก่อนแล้ว เราต้องอาศัยความช่วยเหลือจากเหล่าเทพบนภูเขาจึงจะหยุดความชั่วร้ายนี้ได้\n\nกลับไปหาอีกาที่เจ้าพบบนเขา นางฉลาด แต่พวกวิญญาณแห่งพงไพรเอาแน่เอานอนไม่ได้ แม้จะเผชิญภัยร้ายแรงก็ตาม รับมือนางอาจยากหน่อย แต่เราจำเป็นต้องให้นางช่วย" },
        objective = { "27:1725137483:1139994692", "กลับไปหา Curious Crow" },
    },
    [96931] = { -- Heading Up the Mountain
        title = { "23:1865314009:582397439", "มุ่งหน้าขึ้นเขา" },
        description = { "482:1024918001:801728597", "ฟังนะ เจ้าพวกเดินดิน ใคร ๆ ก็รู้ว่าข้าฉลาดและไหวพริบดี แต่มีอยู่ตนหนึ่งที่สง่างามและทรงพลังยิ่งกว่าข้า\n\nแน่นอนว่าข้าหมายถึง Jereman เทพแห่งพงไพรผู้ฉลาด เจ้าเล่ห์ และงดงามที่สุด! นกทุกตัวรู้จักชื่อนาง ปีกนางกว้างเท่าไร ปัญญาก็ยังกว้างไกลกว่า นางต้องรู้แน่ว่าเวทของตาแก่หินนั่นขาดอะไร\n\nนางทำรังอยู่ข้างบนในที่ที่พวกเจ้าเรียกว่า Cradle of Tranquility ลองแตะรูปอีกาบนสะพานเก่า นางอาจปรากฏตัว!" },
        objective = { "104:1396225079:1182363810", "แตะรูปอีกา (Crow Effigy) บนสะพานที่มองลงไปเห็น Cradle of Tranquility เพื่อเรียก Jereman เทพแห่งพงไพร" },
    },
    [96939] = { -- The Balance of Life and Death
        title = { "29:1144863165:1426638165", "สมดุลแห่งชีวิตและความตาย" },
        description = { "430:892069300:1176330281", "ข้าคิดว่าเพื่อนคนหนึ่งของข้าอาจรู้ว่าจะหาพลังมาเสริมแผนของ Ketharas จากไหน\n\nแน่นอนว่าเขาเป็นเพื่อนสนิทของข้า และคงยินดีออกแรงช่วยคนที่มาทำธุระแทนข้าอย่างเจ้า!\n\nเจ้าจะเจอตาขนเหม็นนั่นทางใต้ของที่นี่ แถวนั้นเต็มไปด้วยอันเดด พวกเจ้าที่มีวันตายเรียกที่นั่นว่า Mourning's Rest ใช่ไหมนะ?\n\nอย่าลืมบอกด้วยว่าข้าส่งเจ้ามา! เขาต้องชอบใจมากแน่ ๆ... แน่นอนอยู่แล้ว!" },
        objective = { "32:1929162894:974316405", "ไปคุยกับ Marrosis เทพแห่งพงไพร" },
    },
    [96998] = { -- Tribal Colors
        title = { "13:1125639748:1549869015", "สีประจำเผ่า" },
        description = { "348:741929877:1892531793", "โครงกระดูกที่ยังกำหอกซัดอยู่มีลักษณะของนักล่าหัวโทรลล์ชัดเจน\n\nในมือกระดูกข้างหนึ่งกำห่อหนังที่มีอักษรโทรลล์และคราบสีทาหน้าเป็นสีประจำเผ่า Darkspear คงเป็นถุงใส่สีที่ใช้แต่งหน้าก่อนออกรบ\n\nคนเผ่า Darkspear อาจอ่านอักษรบนแผ่นหนังศักดิ์สิทธิ์นี้ออก" },
        objective = { "56:2040135622:1496004182", "นำห่อสีทาหน้าสำหรับออกรบ (War Paint Wrap) ไปให้คนที่อาจรู้จักมัน" },
    },
    [91688] = { -- To the Summit of Eternity
        title = { "25:1546868940:218578163", "สู่ยอดเขาแห่งนิรันดร์" },
        description = { "483:1961242295:866225371", "เจ้าฝ่าพวกอันเดดที่ขังเราไว้ที่นี่มาหลายปีจนเปิดทางให้เราได้ เราไม่มีวันตอบแทนบุญคุณนี้หมด\n\nข้าขออีกอย่างในนามของพวกเราทุกคน เรารู้ว่ามีดรูอิดอยู่บนยอดเขา พวกเขาปกป้อง Nordrassil กับ Well of Eternity\n\nทำไมพวกเขาไม่เคยมาช่วยให้เราหนีออกไปเลย?\n\nเราติดอยู่ที่นี่มาห้าปี ในที่สุดก็เริ่มมีหวัง... แต่ทำไมดรูอิดถึงไม่มารับเรา?\n\nช่วยไปบอกใครสักคนว่าพวกเรายังมีชีวิตอยู่!" },
        objective = { "86:538495168:312773341", "เดินทางไปยัง Summit of Eternity แล้วคุยกับเหล่าดรูอิดเรื่องหมู่บ้านผู้รอดชีวิต" },
    },
    [95248] = { -- To the Summit of Eternity
        title = { "25:1546868940:218578163", "สู่ยอดเขาแห่งนิรันดร์" },
        description = { "359:418084473:2027069475", "เจ้าจัดการพวก Scourge ไปตั้งเยอะ พวกเราถึงได้ปลอดภัยขึ้นบ้าง ขอบใจเจ้าจริง ๆ\n\nขออีกเรื่องนะ เรารู้ว่ามีพวกดรูอิดอยู่บนยอดเขา พวกนั้นเฝ้าต้นไม้ใหญ่กับบ่อน้ำอยู่\n\nทำไมพวกนั้นไม่เคยมาช่วยเราเลยล่ะ?\n\nพวกเราอยู่ที่นี่มาห้าปีแล้วนะ! ทำไมถึงไม่เคยส่งข่าวเรื่องพวกเราให้ใครรู้เลย? ช่วยไปบอกใครสักคนทีว่าเรายังอยู่ที่นี่ เรายังไม่ตาย!" },
        objective = { "86:538495168:312773341", "เดินทางไปยัง Summit of Eternity แล้วคุยกับเหล่าดรูอิดเรื่องหมู่บ้านผู้รอดชีวิต" },
    },
    [96025] = { -- As the Crow Flies
        title = { "17:756324810:607835904", "ตามทางที่อีกาบิน" },
        description = { "25:328543501:1621241081 N 100:1576977044:420715184", "ขอบใจที่ช่วยข้า {name} เพื่อนรักของข้าคนหนึ่งรอเจ้าอยู่บนยอดเขา\n\nเดินขึ้นไปตามถนนทางตะวันออกก็จะพบนาง" },
        objective = { "44:1176460784:1592940234", "ไปพบเพื่อนของ Elaena ที่ยอดเขาใน Hyjal" },
    },
    [96494] = { -- Gathering Storm
        title = { "15:604154678:2049208131", "พายุกำลังก่อตัว" },
        description = { "482:1258523056:1028637593", "เจ้าออกสำรวจรอบพื้นที่เรียบร้อยแล้ว พิสูจน์ว่าเจ้าช่วยงานได้และไว้ใจให้เข้าร่วมกับเราได้\n\nข้ามาที่นี่ในนาม SI:7 เพื่อหาข่าวกรองสำคัญให้ฝ่ายพันธมิตร เรื่องนี้มีคนรู้ไม่กี่คน เก็บเป็นความลับด้วย\n\nลัทธิดรูอิดที่เรียกว่า Blackthorne Pact มาตั้งหลักอยู่ใกล้ ๆ พวกมันรับใช้สิ่งที่เรียกว่าราชาพงไพร\n\nหาที่ตั้งอาณาเขตของ «ราชาพงไพร» แล้วทำเครื่องหมายไว้ เราจะได้รายงานกลับไปที่ Stormwind อย่างมั่นใจ" },
        objective = { "73:465820713:1893519439", "หาจุดรวมกำลังเสริมของ Blackthorne ตรงทางเข้าสู่ Hyjal Summit" },
    },
    [96964] = { -- A Clever Creature
        title = { "17:230775836:138216682", "สัตว์ผู้หลักแหลม" },
        description = { "468:1150208222:1779975764", "ถ้าฤๅษีนั่นอยากให้แผนน้อย ๆ ของเขาออกจากรังแล้วบินได้จริง ก็คงต้องมีแหล่งพลังงานแรง ๆ ที่จ่ายพลังต่อเนื่องโดยไม่พังไปเสียก่อน\n\n<Jereman เงยหน้ามองฟ้าแล้วขบจะงอยปากเบา ๆ ขณะครุ่นคิด>\n\nอ้อ ใช่ ข้ารู้ว่าควรไปปรึกษาใคร ไปทางเหนือยังที่ที่พวกเจ้าที่มีวันตายเรียกว่า Dae'gun ตรงที่มีปีศาจนั่นแหละ แล้วตามหา Renalard เทพจิ้งจอกแห่งพงไพร ข้าเชื่อว่าเขาช่วยไขปัญหาเล็ก ๆ ของเราได้" },
        objective = { "31:810328028:770142646", "ไปพูดคุยกับ Renalard เทพแห่งพงไพร" },
    },
    [92533] = { -- Twisted Tools
        title = { "13:1470514624:1346886783", "เครื่องมือผิดทาง" },
        description = { "490:27540806:327993924", "ข้าตีเหล็กมาทั้งชีวิต ย่อมรู้สึกได้เมื่ออาวุธถูกบิดให้ผิดจากจุดประสงค์เดิม ลัทธิ Blackthorne ตีอาวุธให้ทำร้ายผืนดินได้พอ ๆ กับทำร้ายเนื้อหนัง ฆ่าสาวกของพวกมันแล้วเอาของที่พกมาหาข้า ขอคทาหนึ่งด้ามกับกริชประกอบพิธีหนึ่งเล่ม\n\nคมอาวุธพวกนั้นคร่าชีวิตได้ และพวกมันยังจงใจอาบพิษให้อาวุธด้วย\n\nถ้าศึกษารอยที่มลทินทิ้งไว้ เราจะรู้ว่าอิทธิพลของพวกมันแผ่ไปอย่างไร บางทีอาจรู้วิธีหยุดมัน หรือกระทั่งย้อนผลของมันได้" },
        objective = { "93:783367210:1210101235", "ชิง Wicked Ritualist's Kris และ Recoiling Gnarlybark Staff จากสาวก Blackthorne" },
    },
    [93407] = { -- A Thorn in the Paw
        title = { "18:278283018:1887094377", "หนามตำอุ้งเท้า" },
        description = { "268:210714755:1724406335", "เราต้องเสริมแนวป้องกันที่นี่ แต่ทรัพยากรไม่พอจะสร้างป้อม ยังดีที่ธรรมชาติมีสิ่งที่เราต้องใช้ให้เหลือเฟือ\n\nค้นหาพุ่มหนามในป่าแล้วนำเมล็ดกลับมาให้ข้า เราจะใช้พลังธรรมชาติปลูกแนวป้องกันของเราเอง" },
        objective = { "100:938761258:1271153267", "หาเมล็ดพุ่มหนามในป่าบนยอด Mount Hyjal แล้วนำกลับไปให้ Tiala Whitemane" },
    },
    [93584] = { -- Cult Closure
        title = { "12:613426842:1615067854", "ยุติลัทธิราชาพงไพร" },
        description = { "502:1407705761:1382005988", "พื้นที่รอบ Well of Eternity เต็มไปด้วยสาวกของราชาพงไพร หลายคนเคยยืนเคียงข้างเราและถือคำสัตย์เดียวกัน แต่ความศรัทธาของพวกเขากลับกลายเป็นความคลั่งที่ไม่คิดหน้าคิดหลัง ตอนนี้พวกเขาคอยขัดขวางการดูแล Nordrassil และการปกป้องบ่อน้ำของเรา\n\nข้ารู้ว่าเรื่องนี้ทำใจยาก และมือข้าเองก็ย่อมเปื้อนเลือด แต่เราจะปล่อยให้พวกเขาทำร้ายผืนดินหรือโจมตีเราจากด้านข้างเมื่อการบุกรุกครั้งใหญ่เริ่มขึ้นไม่ได้\n\nรีบลดกำลังของพวกเขา และขอให้ Elune อภัยในสิ่งที่จำเป็นต้องทำ" },
        objective = { "56:8758979:23601379", "สังหาร Blackthorne Adept 10 คน และ Wild-branded Cultist 10 คน", amount = { "5:409775429:850574908 W1 24:169406741:573264668 W2 23:1634452034:865251579", "สังหาร Blackthorne Adept {world1} คน และ Wild-branded Cultist {world2} คน" } },
    },
    [93848] = { -- Work Well Done
        objective = { "77:1148716141:1983580749", "กลับไปหา Ketharas แล้วรายงานสิ่งที่เกิดขึ้นที่ Summit of Eternity" },
        title = { "14:2124709640:1186446710", "ภารกิจลุล่วง" },
        description = { "486:1667920209:1033162851", "เวทที่ Ketharas สร้างขึ้นเพื่อต้านภัยนี้มีส่วนสำคัญอย่างยิ่งต่อชัยชนะ ดรูอิดของเราน่าจะสร้างเวทนี้ขึ้นใหม่และใช้สลายอาคมคุ้มกันที่เสริมพลังให้ Blackthorne Pact ได้ทั่วพื้นที่\n\nกลับไปหา Ketharas แล้วบอกเขาว่าเกิดอะไรขึ้นที่นี่ ฝากคำขอบคุณจากผู้พิทักษ์ Hyjal และ Cenarion Circle ด้วย ให้เขารู้ว่าเรายินดีต้อนรับเสมอ หากเขาอยากกลับมายืนเคียงข้างเพื่อนดรูอิดอีกครั้ง" },
    },
    [96003] = { -- Drawing Down the Malevolent
        title = { "27:1992188539:1396118316", "สยบพลังชั่วร้าย" },
        description = { "487:808003419:2100729087", "เป็นอย่างที่คิด ภาชนะหลอมรวมเป็นสิ่งใหม่ที่ทรงพลัง\n\nถ้าภาชนะกักเก็บพลังไว้ได้ ก็น่าจะมีทางใช้พลังนั้นให้เป็นประโยชน์กับเรา วัตถุอาคมเฟลหาได้ยากและไม่ค่อยปลอดภัย ไหน ๆ ก็มีแล้ว ลองเอามาใช้ดูไหมล่ะ?\n\nถึงเวลาทดสอบในสนามจริง\n\nเอาผลึกไปใช้กับ Bethra'zel และ Mazzogore สองปีศาจที่ทรงพลังที่สุดของพวกมัน แค่มีสองตัวนี้อยู่ค่ายก็ป้องกันแน่นหนาแล้ว มาดูซิว่าเราจะเปลี่ยนเรื่องนั้นได้ไหม" },
        objective = { "114:2027621474:1803600266", "ใช้ Eye of Endless Influence กับ Bethra'zel และ Mazzogore เพื่อดูดพลังของทั้งคู่ แล้วจึงลงมือสังหาร" },
    },
    [97490] = { -- Halt the Hail
        title = { "13:1655873940:1863635983", "หยุดเจ้ายักษ์ลูกเห็บ" },
        description = { "484:2114708018:11618670", "นี่พวก ข้ากำลังย่อยเศษของเก่าเอาชิ้นส่วนไปทำเครื่อง แต่เครื่องเริ่มร้อนเกินไปแล้ว\n\nรู้ว่าคิดอะไรอยู่ Winterspring เนี่ยนะร้อน? อย่างที่เห็น เครื่องบดกับเครื่องประกอบใหม่ยังเดินอยู่ แต่กระตุกหนักมาก ต้องหาอะไรสักอย่างมาช่วยระบายความร้อน เอาแบบที่ไม่ละลาย ไม่ไถลหลุด และไม่ไหม้ไปเสียก่อน\n\nตามเนินเขาด้านใต้มีเจ้ายักษ์ตัวร้ายที่เราเรียกว่า Hailspite เดินเพ่นพ่านอยู่ จัดการ Hailspite แล้วเอาตะไคร่เย็นจัดที่เกาะตามซอกหินบนตัวมันมาให้ข้า\n\nเผื่อใช้ได้!" },
        objective = { "122:1007681607:384298616", "ตามหายักษ์ Hailspite ในเนินเขาทางใต้ของ Winterspring แล้วเก็บมอสเยือกแข็งที่ขึ้นตามตัวมัน" },
    },
    [92329] = { -- Drum Up Trouble
        title = { "15:1375831873:1623226876", "ตีกลองเรียกภัย" },
        description = { "451:1052614277:1220122330", "มีคิเมราเฟลออกอาละวาดใส่สัตว์กับคนเดินทางตามเนินเขา Cenarion Circle เรียกมันว่า Ghansurok ข้าจะเล็งและยิงเครื่องยิงดาบวงแหวนเอง เจ้าไปที่กลองริมหน้าผานั่น เราจะได้กำจัดภัยนี้ให้พ้นภูเขาเสียที\n\nข้าจะมีโอกาสยิงมันร่วงก็ต่อเมื่อเจ้าล่อมันมาได้ พอมันมาถึงสันเขาแล้ว หาที่หลบด้วย!\n\nใช่ ข้ารับปากเลยว่าเมล็ดเมเปิลมีเต็มถุง!" },
        objective = { "154:1322029557:1425951954", "เดินไปที่สันเขาทางใต้ของโรงช่าง Kaylaena แล้วหาทางส่งเสียงดังล่อคิเมรา Ghansurok ให้เข้ามาในระยะโจมตี" },
    },
    [92446] = { -- Head Scratcher
        title = { "14:1993168774:1846073125", "เจ้าหมีตะปบหัว" },
        description = { "494:649704074:101909886", "ในป่าทางใต้ที่ข้าไปล่าสัตว์เป็นบางครั้ง มีหมีตัวใหญ่เจ้าเล่ห์อยู่ตัวหนึ่ง เราเรียกมันว่า Head Scratcher เพราะอุ้งเท้ามันเล่นงานชาวบ้านที่ไม่ทันระวังมาหลายคน มันดักนักล่าที่กำลังหอบเหยื่อกลับบ้าน ตะปบหัวจนสลบ แล้วชิงเหยื่อหนีกลับเข้าป่า\n\nมันรู้ทันข้า รู้ว่าข้าแกะรอยมันอยู่ แต่คงยังไม่คุ้นกลิ่นเจ้า\n\nเอาซากสัตว์นี้ไปล่อมันออกมา จัดการมันแล้วเอากรงเล็บกลับมา" },
        objective = { "126:787148826:1970222119", "นำซากกระต่ายไปในป่าทางใต้ ล่อ Head Scratcher ออกมาจัดการ แล้วนำกรงเล็บของมันกลับไปให้ Zet'gan" },
    },
    [92833] = { -- Ve'han's Fall
        title = { "13:916036266:1056791054", "จุดจบของ Ve'han" },
        description = { "256:948749095:1219140127", "ตอนนี้ Ve'han ยึด Nordrassil Lodge ใต้กิ่งก้านไม้ใหญ่เป็นรังของมัน ถึงเวลาทดสอบเวทนี้กับศัตรูตัวจริงเสียที\n\nเอาคทาไปใช้กับ Ve'han สลายเวทที่คุ้มกันมันอยู่ แล้วให้มันชดใช้สิ่งที่ทำลงไป!" },
        objective = { "95:63877758:291223167", "ใช้ Staff of the Mountain ริบพลังที่ Ve'han Talongrasp ขโมยมา แล้วจึงกำจัดเขา" },
    },
    [93422] = { -- Blackthorne Blackout
        title = { "20:1698875289:1231787364", "ตัดข่าวของ Blackthorne" },
        description = { "484:754738674:1400603135", "ราชาพงไพรเงี่ยหูฟังผ่านเงาที่เก่าแก่กว่า Hyjal เสียอีก ตอนนี้หน่วยสอดแนมของมันเคลื่อนไหวกันอย่างตั้งใจ เพราะทั้งฝ่ายฮอร์ดและฝ่ายพันธมิตรกลับมารุกคืบในดินแดนศักดิ์สิทธิ์นี้ Blackthorne Pact ถูกการต่อต้านของเรากดดันจนคลุ้มคลั่งขึ้นทุกวัน\n\nตามล่าคนส่งสารของ Blackthorne แล้วหยุดนางก่อนจะนำข่าวสำคัญกลับไปให้นายของนาง\n\nนางเดินทางระหว่างค่าย เฝ้าดูเส้นทาง ลงมือจัดการ แล้วนำของที่นางพกกลับมาให้เรา" },
        objective = { "56:56543168:2145013058", "สังหาร Blackthorne Courier แล้วชิงสารที่นางถือมา" },
    },
    [93444] = { -- Bait the Beast
        title = { "14:1553273296:1685137887", "วางเหยื่อล่อสัตว์ร้าย" },
        description = { "495:1553148916:1833931013", "คิเมราเฟลที่ดุที่สุดใน Hyjal ชื่อ Ghansurok มันชอบโฉบจับสัตว์ที่ออกมานอกโพรง แถมทำให้การเข้าออก Hyjal ด้วยฮิปโปกริฟตึงเครียดกว่าเดิม!\n\nเริ่มจากล่า Nightsaber สักตัวที่ซ่อนอยู่ตามเงามืดบนยอดเขา จากนั้นเอาเนื้อของมันไปวางบนสันเขาทางเหนือ ตรงบริเวณที่คิเมราหากิน\n\nล่อ Ghansurok เข้ามา ฆ่ามันแล้วนำหัวใจกลับมา Marn จะศึกษามันเพื่อช่วยเยียวยา Hyjal" },
        objective = { "173:1459449161:1096060343", "สังหาร Nightsaber Guardian แล้วนำเนื้อส่วนสะโพกของมันไปวางล่อ Ghansurok บนสันเขาทางเหนือของยอดเขา เมื่อมันออกมาให้สังหารมัน\n\nนำหัวใจของคิเมรากลับมาด้วย" },
    },
    [96558] = { -- Soldier's Solace
        title = { "16:1743877237:1740840858", "สิ่งปลอบใจของทหาร" },
        description = { "436:1606539916:291823165", "ใต้หินแตกของหอสังเกตการณ์นั่นมีข้าวของที่เราฝังไว้ลวก ๆ ตอนโลกเริ่มลุกเป็นไฟ ของไม่กี่ชิ้นที่เราหอบมาจาก Hyjal ยังอยู่ตรงนั้น เอาไปเถอะ เจ้าสมควรได้แล้ว\n\nแรงดึงรั้งมากขึ้นเรื่อย ๆ... ภูเขายึดข้าไว้เหมือนเดิมไม่ได้แล้ว ข้าไม่รู้ว่าเราจะได้คุยกันอีกไหม\n\nเพราะเจ้า ข้าถึงจำได้ว่าข้าเคยเป็นใคร และพวกเราเคยเป็นใคร ไปเถิด ขอบใจเจ้า ขอให้วิญญาณดวงนี้ได้สงบเสียที" },
        objective = { "47:1472882657:2102957631", "ขุดเอา Battle Cache ที่ฝังอยู่บน Mount Hyjal กลับมา" },
    },
    [96983] = { -- Yashiro's Windwalk
        title = { "18:794168837:1055205280", "ย่างก้าวสายลมของ Yashiro" },
        description = { "378:44812362:1120993673", "เจ้าทั้งเก่ง ว่องไว และไม่กลัวอะไร ไฟจะล่อปีศาจออกจากที่ซ่อน พวกขุนศึกของมันจะออกมาด้วย พวกมันหวังมาชิงอำนาจ แต่สิ่งที่รออยู่คือการล้างแค้น ถึงเวลาที่เจตจำนงของภูเขาจะเปล่งเสียงผ่านเรา\n\nมาเถิด เราจะฟันฝ่าพวกสัตว์นรกนี้และจบการครองอำนาจของพวกมัน ดาบของข้ารอฟันทะลวงกองทัพพวกมันอยู่" },
        objective = { "44:591735604:2147062104", "ต่อสู้ฝ่า Dae'gun ไปพร้อมกับ Yashiro" },
    },
    [92015] = { -- Area Denial Skunks
        title = { "18:1865632695:1421534855", "สกังก์ยึดพื้นที่" },
        description = { "473:771931083:1147927220", "อยากช่วยเหรอ? ดีเลย ข้ามีงานให้ทำ\n\nเคยโดนสกังก์พ่นใส่กลางวันร้อน ๆ ไหม? บอกเลยว่าไม่มีอะไรแย่กว่านี้แล้ว เจ้าพวกนั้นทำเอาของทุกอย่างรอบตัวเหม็นคลุ้งติดทน!\n\nสกังก์ครอบครัวหนึ่งมาอยู่หลังลังอุปกรณ์ข้า ช่วยไล่พวกมันออกไปดี ๆ หน่อย แล้วข้าจะคิดดูว่าจะแบ่งอุปกรณ์ให้เจ้าได้ไหม พอเข้าไปหยิบได้แล้วน่ะนะ...\n\nข้าย้ำเลยว่าอย่าโจมตีมัน โดนพ่นใส่แน่!" },
        objective = { "73:1722547203:205605589", "ไล่สกังก์ออกจากบริเวณรอบอุปกรณ์ของ Johun โดยไม่ฆ่าพวกมัน" },
    },
    [92328] = { -- Siegecraft
        title = { "10:853691567:1508772807", "ประกอบเครื่องยิง" },
        description = { "491:1698590575:2020361549", "พอได้เสบียงเพิ่มจากที่เจ้าขนกลับมา ข้าก็มีวัสดุพอทำเครื่องยิงดาบวงแหวนตามแบบเดิมของ Yaely ให้เสร็จ ข้าซ่อมเจ้าเครื่องนี่มานาน... นานจนเหมือนจะไม่มีวันเสร็จ!\n\nถ้าเจ้ามาช่วยออกแรงอีกคน งานจะเร็วขึ้นเยอะเลย ข้าจะบอกทีละขั้น ส่วนยาก ๆ น่าจะผ่านไปเกือบหมดแล้ว...\n\n<Kaylaena ไขว้นิ้วขอให้โชคดี>\n\nระบบขับเคลื่อนกับเซลล์พลังงานที่จ่ายไฟให้มันติดตั้งเกือบเสร็จแล้ว" },
        objective = { "100:678444410:830632299", "หมุนเฟืองทั้งสองตัวและต่อขั้วแบตเตอรี่ทั้งสองจุดที่อยู่สองข้างของเครื่องยิงใบมีดของ Kaylaena" },
    },
    [93747] = { -- Violence Into Verdure
        title = { "21:4539834:1168244669", "คืนสีเขียวให้ซากสงคราม" },
        description = { "375:995837927:2045149169", "ซากเครื่องจักรจากสงครามกำลังผุและขึ้นสนิม แต่เราช่วยให้ธรรมชาติทวงพื้นที่คืนได้เร็วขึ้น\n\nเอาถุงเมล็ดที่เจ้าเก็บมาก่อนหน้านี้ไป ข้าเติมมนตร์ลงไปนิดหน่อยให้โตไวขึ้น วางเมล็ดไว้ใกล้เครื่องจักรสงครามเก่าแล้วปล่อยให้ต้นไม้โตขึ้นมาคลุมซากไว้ ความทรงจำของสงครามจะเลือนหายไปตามกาลเวลา และธรรมชาติจะกลับมาอยู่ในพื้นที่ของมันอีกครั้ง" },
        objective = { "103:683798895:544338487", "ปลูกเมล็ดพันธุ์ลงมนตร์ (Enchanted Seeds) ใกล้ซาก Ruined Ballista, Ruined Catapult และ Ruined Flying Machine" },
    },
    [95611] = { -- Rites of Respect
        title = { "16:462175553:1040597080", "พิธีแสดงความเคารพ" },
        description = { "89:1532673082:1418739460 N 335:540351135:1116169036", "เมื่อรับมาก็ต้องคืนให้ นี่คือวัฏจักรชีวิต\n\nเจ้าทำได้ดี {name} ด้วยแรงของเจ้า สัตว์ป่าบนภูเขาจะยังเติบโตและมีชีวิตต่อไป\n\nถึงเวลาแสดงความเคารพต่อผืนดินนี้ด้วยการนำซากส่วนที่ไม่ได้ใช้คืนสู่ดิน\n\nนำห่อนี้ไปที่ศาลทางตะวันตก เจ้าจะจำได้จากหินตั้งเรียบ ๆ สองแท่ง เสร็จพิธีแล้วกลับมาหาข้า" },
        objective = { "37:1286109017:554770189", "ฝังซากที่ศาลของ Ketharas" },
    },
    [93383] = { -- Contents Under Pressure
        title = { "23:684023711:1712023192", "สัมภาระอัดแรงดัน" },
        description = { "462:1958611099:52197742", "เป้แข็งแรงใบหนึ่งอัดแน่นด้วยอุปกรณ์ยังชีพและเครื่องรับวิทยุ วางอยู่ระหว่างพุ่มหนาม วิทยุเครื่องหนึ่งมีไฟกะพริบ\n\nพอเจ้าเอื้อมมือไปหยิบ วิทยุที่รัดติดกับเป้ก็ส่งเสียงหึ่งขึ้นมา\n\n«ตรวจพบผู้ขับ! ระบบระบุพิกัดโนมกำลังเชื่อมสัญญาณ!\n\nยืนยันของที่จะจ่าย ชุดยังชีพนักบินแบบสามวัน ขนาดเดียว จำนวนหนึ่งชุด\n\nโปรดรอให้กลไกนิรภัยคายแรงดันจนปลอดภัยก่อนเปิด»" },
        objective = { "58:160040330:338756023", "รอจนกว่าจะเปิด Personal Survival Pack ได้อย่างปลอดภัย" },
    },
    [96979] = { -- Sacred Refreshment
        title = { "18:1778817010:95727504", "น้ำศักดิ์สิทธิ์สำหรับพิธี" },
        description = { "485:1155493947:1803785545", "ข้าเป็นดรูอิดแห่ง Cenarion Circle เดินทางไกลมาเพื่อคารวะไม้โลก ข้าประเมินต่ำไปว่าการปีนขึ้นมาจะกินแรงแค่ไหน แถมพวกนักล่ามีปีกที่วนเวียนตามลาดเขายังทำให้ต้องระวังตัว ซากปรักหักพังเก่า ๆ นี้พอใช้หลบภัยได้ ข้าจึงเข้ามาพัก\n\nที่นี่เหมาะจะวางเครื่องบูชาเล็ก ๆ แต่พิธีต้องใช้น้ำจากแหล่งธรรมชาติ ถ้าเจ้ายินดี ช่วยเอาน้ำจากน้ำตกข้างหน้าใส่กระบอกน้ำเต้าของข้าให้เต็ม\n\nกลับมาแล้วเล่าให้ข้าฟังด้วยว่าเดินผ่านทางไหนและพบอะไรเคลื่อนไหวอยู่แถวนั้น" },
        objective = { "65:2106724296:1616193200", "เติมน้ำใส่กระบอกน้ำเต้าของ Galvinquam Leafsyre ที่น้ำตกข้างหน้า" },
    },
    [96550] = { -- Battle Recall
        title = { "13:797862061:1207716541", "หวนระลึกถึงศึก" },
        description = { "307:864567849:203940567", "ฝักดาบเก่ามีลวดลายและเครื่องหมายสลักอยู่ ตรงกับที่ทหารผ่านศึกบอกไว้ ทิวทัศน์เบื้องล่างมองแล้วงดงามจนแทบลืมหายใจ\n\nบางทีเพียงถือฝักดาบไว้ในมือแล้วนึกถึงคำของทหารผ่านศึก ก็อาจเรียกวิญญาณกลับมายังความทรงจำนี้ได้" },
        objective = { "107:1847128201:1347588825", "ใช้ Embroidered Scabbard เพื่อพูดคุยกับทหารผ่านศึกและฟังเรื่องราวของเขาที่จุดชมวิวใน Elderwild" },
    },
    [92335] = { -- Ashes of the Legion Ascent
        title = { "26:1200529312:283028693", "เถ้าถ่านแห่งคราวที่ Legion บุกขึ้นเขา" },
        description = { "504:2125754012:250067227", "เวทที่เจ้าตามหาทั้งซับซ้อนและควบคุมยาก ต้องใช้วัตถุดิบที่จ่ายพลังได้อย่างต่อเนื่องและสม่ำเสมอ ข้ารู้ว่าควรใช้อะไร\n\nคราวที่ Archimonde พบจุดจบที่สาสมที่นี่ สมุนชั้นผู้น้อยของมันก็ถูกฆ่าไปมาก Azgalor มือขวาของมันก็ถูกสังหาร ฝีมือคนที่มีวันตายอย่างเจ้าด้วยซ้ำ!\n\nเจ้าจะพบเศษร่างสุดท้ายของ Azgalor กลางซากปรักหักพังที่นี่ ไม่ต้องหอบเถ้ากลับไปให้ Ketharas ทั้งหมด หยิบมือเดียวก็มากพอแล้ว" },
        objective = { "74:213677623:976111048", "เก็บเถ้าของ Azgalor (Azgalor's Ashes) หนึ่งหยิบมือจากซากปรักหักพัง Dae'gun บน Mount Hyjal" },
    },
    [91754] = { -- Rub Some Dirt In It
        title = { "19:1406810822:839051087", "เอาดินมาทาหน่อย" },
        description = { "17:1132361649:325545280 R 256:735161675:1245898105", "ข้าไม่ได้เจอชาว{race} อย่างเจ้ามาหลายปีแล้ว!\n\nโธ่ ข้าไม่รู้จะทำอย่างไรดี! Fraxinus เพื่อนข้าป่วย ข้าทิ้งเขาไว้ลำพังไม่ได้!\n\nช่วยไปเอา Untainted Soil จากผืนดินที่ยังไม่แปดเปื้อนทางตะวันออกเฉียงใต้ของที่นี่ให้ข้าหน่อยได้ไหม? ข้าจะทำยาพอกเผื่อช่วยให้เขาดีขึ้น" },
        objective = { "77:1037860760:1701066221", "เก็บดินที่ไม่ปนเปื้อน (Untainted Soil) 6 ตัวอย่างตามเชิงเขา Mount Hyjal", amount = { "8:1089852795:1107240600 W1 68:1366975003:454544907", "เก็บดินที่ไม่ปนเปื้อน (Untainted Soil) {world1} ตัวอย่างตามเชิงเขา Mount Hyjal" } },
    },
    [92008] = { -- Premiere Parts
        title = { "14:98155978:103521317", "ชิ้นส่วนชั้นดี" },
        description = { "504:431507707:203185627", "หน้าใหม่อีกแล้วเหรอ?\n\nก็ไม่น่าแปลกใจกับสภาพอาคมที่เราเรียกกันว่าคุ้มกันได้ในช่วงนี้ พลังเฟลข้างล่างเป็นไงบ้าง? ข้าไม่ได้ออกจากโรงช่างนี้มาหลายสัปดาห์แล้ว ไหน ๆ เจ้าก็มาถึงนี่ ถ้าอยากวิ่งธุระ ข้ามีเรื่องให้ช่วยอยู่สองสามอย่าง\n\nเจ้านึกไม่ถึงหรอกว่าขนชิ้นส่วนดี ๆ ขึ้นมาถึงนี่ลำบากแค่ไหน ขนาดวัสดุพื้นฐานสำหรับงานช่างยังหายากเลย Nami ที่ Everlook เตรียมชิ้นส่วนที่ข้าสั่งไว้แล้ว อยากวิ่งฝ่าหนาวสักเที่ยวไหม?" },
        objective = { "65:1330438837:990013032", "ไปรับชิ้นส่วนที่ Kaylaena Springbolt สั่งไว้จาก Nami ใน Everlook" },
    },
    [91564] = { -- Itching for a Fixing
        objective = { "6:1273960851:929420321 W1 21:1546557573:1361386197 W2 44:1003161318:791723795", "นำ Mithril Casing {world1} ชิ้น และ Mechanical Repair Kit {world2} ชุดไปให้ Hnaz Blunderflame" },
        title = { "20:1007251205:1843138650", "คันมืออยากซ่อม" },
        description = { "383:1000453398:574985557", "พวกเราติดอยู่ที่นี่มาห้าปี ต้องสร้างทุกอย่างขึ้นมาเองตั้งแต่ต้น! เจ้ารู้ไหมว่าข้าต้องด้นสดแค่ไหนกว่าจะทำงานช่างได้สักอย่าง?\n\nนี่ ถ้าช่วยหาวัสดุให้ ข้าจะตอบแทนให้คุ้มเวลา ทำ Mithril Casing ให้ข้าสองชิ้นกับ Mechanical Repair Kit หนึ่งชุด จะได้ซ่อมของสักหน่อย แล้วข้าจะสอนเคล็ดที่ข้าคิดขึ้นเองให้" },
    },
    [92433] = { -- Now We're Cooking
        objective = { "6:1273960851:929420321 W1 55:946352740:1802132830", "นำ Savory Stag Slider {world1} ชิ้นไปให้ Hnaz Blunderflame ที่ Elderwild" },
        title = { "17:144117203:1993877072", "ได้เวลาทำกับข้าว" },
        description = { "432:1574985660:1923368238", "นี่! ข้ากำลังยุ่งกับการเอาเศษของเหลือมาทำให้กินได้ อยากช่วยไหม? มื้อนี้ข้าอยากได้อะไรหลากหลายขึ้นหน่อย มีเมนูแปลกใหม่บ้างคงดี!\n\nกอบลินที่ Everlook มีสูตร Savory Stag Sliders ขนาดพอดีกับมือเล็ก ๆ ของข้าเลย ถ้าเจ้าทำมาให้สักหน่อยคงดีมาก! หาเนื้อได้จากกวางตัวผู้บนภูเขานี้" },
    },
    [93617] = { -- Prey and Predator
        title = { "17:102063591:1635732465", "เหยื่อกับผู้ล่า" },
        description = { "311:1514617025:2090503550", "ลำดับชั้นของเหล่าเทพแห่งพงไพรถูกบิดเบือนไปแล้ว ทุกสิ่งกำลังเปลี่ยนไป และธรรมชาติของโลกก็ปั้นใหม่ได้เหมือนดินเหนียว!\n\nเผ่าพันธุ์ของข้าจะไม่ต้องทนคมเขี้ยวของผู้ล่าอีก จากนี้เราจะล่าทุกตัวที่เคยกินพวกเรา!\n\nสั่นกลัวเสียเถิด เจ้าตัวเปราะบาง เจ้าไม่มีทั้งกำลังและความเร็วพอจะหยุดเราได้!" },
        objective = { "40:1922397853:1328907072", "ขัดขวางไม่ให้กวางตัวผู้ทำตัวเป็นผู้ล่า" },
    },
    [93828] = { -- Herbs of the Hollow
        objective = { "8:1089852795:1107240600 W1 84:1980610478:1317445972", "เก็บ Dried Hanging Herbs {world1} ชุดจากบริเวณ Barkskin Burrow แล้วนำกลับไปให้ Fennar Mossmane" },
        title = { "19:1283623134:115184103", "สมุนไพรในโพรง" },
        description = { "360:69957156:20777419", "ลมหายใจของภูเขาแถวตาน้ำนี้ชื้นนัก อากาศอับแบบนี้สมุนไพรของข้าไม่แห้งเลย พอพวกเรากลับจากป่า แต่ละคนจะแขวนห่อของไว้ตามจุดที่ลมลอดรากไม้เข้ามาได้ กระจายไปทั่วโพรง\n\nไปเถิด หาพวงสมุนไพรแห้งที่แขวนรอบบ้านเราแล้วเอามาให้ข้า ข้าจะเอาไปถักเป็นผ้าพันและเครื่องคุ้มกันให้วิญญาณของเราเข้มแข็ง" },
    },
    [93830] = { -- Water of Hyjal
        objective = { "93:1344588819:1618410066", "นำถุงหนังใส่น้ำที่ Fennar Mossmane ให้มาไปเติมน้ำที่บ่อนอกโพรงของพวกเฟอร์โบลก์ Deadwood" },
        title = { "14:1276011171:900236708", "น้ำแห่ง Hyjal" },
        description = { "444:1924590103:810970469", "เผ่า Deadwood อยู่ข้างบ่อที่เกิดจากหิมะละลายจาก Mount Hyjal น้ำนั้นบริสุทธิ์และเปี่ยมด้วยลมหายใจของภูเขา พวกเราใช้ผสมน้ำยาและใช้รักษารากไม้ที่ใกล้ตาย\n\nตาน้ำที่นี่ไหลเอื่อย ต้องรักษาไว้และใช้อย่างประหยัด แต่น้ำในบ่อของพวกนั้นเปี่ยมชีวิต มากพอจะเติมโพรงเราได้ถึงสองรอบ เอาถุงหนังไปตักน้ำมาให้ข้าสักถุงนะสหาย เหล่าวิญญาณจะอวยพรให้เจ้าเดินทางปลอดภัย แล้วพวกเราในโพรงจะได้ดื่มของขวัญจากภูเขาให้ชื่นใจ" },
    },
    [93834] = { -- Burrow Beetles
        objective = { "7:451016854:1830523975 W1 37:86407496:638961952", "รวบรวม Burrow Beetle Bits {world1} ชิ้นให้ Dala Fairmaw" },
        title = { "14:163035146:975155075", "ด้วงขุดโพรง" },
        description = { "329:896672102:833690535", "ด้วงขุดโพรง! เจ้าพวกตัวปัญหา... เดี๋ยวนี้มันขุดโพรงเรายิ่งกว่าโพรงตัวเองเสียอีก เราคอยไล่และหวดด้วยกระบองเมื่อเห็นมันย่องผ่าน แต่มันไว และความมืดก็ช่วยให้มันซ่อนตัว\n\nถ้าเห็นตอนเดินขึ้นมาตามโพรง ก็ขยี้มันเลย! เราจะเอาเปลือกที่ถูกบดไปทำอาหาร อย่างน้อยก็ยังมีข้อดีอยู่บ้าง" },
    },
    [94504] = { -- Barkskin Beginnings
        title = { "19:1462886435:1618552976", "ก้าวแรกกับเผ่า Barkskin" },
        description = { "265:1887092901:1001066508", "ตอนนี้บางคนอาจคุยกับเจ้าแล้ว ส่วนคนอื่นยังต้องใช้เวลา ถ้าอยากให้คนในเผ่าเรายอมรับเจ้าเป็นเพื่อนมากขึ้น ก็อย่าเร่งนัก\n\nอยู่เคียงข้างเรา ช่วยทั้งเด็กและคนแก่ แล้วปกป้องเราจากคนที่คิดร้าย\n\nเมื่อเจ้ามีอะไรมาให้เรามากขึ้น เราก็จะมีอะไรแบ่งให้เจ้ามากขึ้น" },
        objective = { "58:1526981327:451707091", "เพิ่มชื่อเสียงกับเผ่า Barkskin Burrow ให้ถึงระดับเป็นกลาง (Neutral)" },
    },
    [95769] = { -- Threading a Solution
        objective = { "6:1273960851:929420321 W1 59:737563271:1774634728", "นำ Bolt of Runecloth {world1} ม้วนไปให้ Mez'dan ที่ Elderwild บน Mount Hyjal" },
        title = { "20:1748144124:1350693047", "ใช้ด้ายแก้ปัญหา" },
        description = { "325:1843603188:44302234", "อยู่กันลำบากอย่างพวกเรา แต่ละวันนี่ท้าทายเอาเรื่อง! ทั้งเครื่องมือ ทั้งเสื้อผ้า ทั้งชีวิตทรุดโทรมไปหมด ยังดีที่ใจพวกเรายังสู้!\n\nตอนนี้ลำบากเพราะเสื้อกับผ้าห่มขาดหมดแล้ว เจ้าตัดเย็บเป็นใช่ไหม? ช่วยเอา Bolt of Runecloth มาให้ข้าสักหน่อยได้ไหม ข้าจะได้ปะรูสักสองสามจุด" },
    },
    [96559] = { -- Supply Drop
        title = { "11:1522855073:2048523537", "สัมภาระตกจากฟ้า" },
        description = { "494:1592080161:559402530", "นักบินทดสอบโนมทุกคนรู้ดีว่าพอขึ้นไปบนฟ้ากว้าง ต้องเตรียมรับมือเรื่องเลวร้ายที่สุดไว้ก่อน!\n\nเราถึงไม่เคยออกจากโรงเก็บเครื่องบินโดยไม่มีชุดยังชีพนักบิน มันมีเครื่องส่งสัญญาณที่ทำงานเอง พอเปิดชุดปุ๊บก็ส่งพิกัดกลับฐานทันที แถมยังอัดแน่นด้วยของใช้จำเป็นอีกเพียบ\n\nถ้าเจ้าหาเป้เจอ ไม่ว่ามันจะตกที่ไหน เปิดได้เลย แล้วเอาของข้างในไปใช้ตามสบาย แค่นี้ก็ช่วยข้าแล้ว!" },
        objective = { "49:776710530:37805111", "ตามหา Pilot Survival Kit ของ Fenwick Togglespring" },
    },
    [96666] = { -- Burrow Bonding
        objective = { "59:1788506091:710009607", "เพิ่มชื่อเสียงกับ Barkskin Burrow ให้ถึงระดับเป็นมิตร" },
        title = { "14:35583358:689994253", "กระชับมิตรในโพรง" },
        description = { "180:1994101357:943466081", "ชาว Barkskin พูดถึงเจ้าดีขึ้นแล้ว สหาย แต่เจ้ายังมีเรื่องต้องทำอีก\n\nยกมือต่อสู้ศัตรูของเรา เคารพวิถีของเรา\n\nเราจะคอยดูให้ดี แล้วเราจะมีเรื่องคุยกับเจ้ามากกว่านี้" },
    },
    [96830] = { -- Farsight Guided
        title = { "15:1205646170:160294174", "ตามนิมิตผู้หยั่งรู้" },
        description = { "482:1288556764:903862772", "เลือดปีศาจยังหยดจากขวานข้าตอนที่ได้ยินมนุษย์ร้องจากที่สูงเหนือหัว\n\nข้าเงยหน้าขึ้นแล้วเห็นชายคนนี้ห้อยอยู่ในกรงเล็บของคิเมราตัวใหญ่ เขาสู้สุดแรงจนสัตว์ร้ายคลายกรงเล็บจนเขาร่วงลงมา\n\nตกจากสูงขนาดนั้น นักรบคนไหนก็ลุกเดินไม่ไหว แม้เป็นศัตรูก็ควรได้จากไปอย่างมีศักดิ์ศรี ข้าจึงลากเขาเข้าร่มให้สิ้นใจอย่างสงบ\n\nส่วนข้ากำลังตามนิมิตของเหล่าผู้หยั่งรู้ พวกพ้องยังอยู่ใน Hyjal ไกลออกไปทางตะวันตกเฉียงเหนือ\n\nไปหาชาวฮอร์ดที่เหลือแทนข้าที เกียรติของข้าผูกให้ต้องอยู่ที่นี่" },
        objective = { "56:2074568067:2021732231", "มองหาร่องรอยของฝ่ายฮอร์ดทางตะวันตกเฉียงเหนือของ Mount Hyjal" },
    },
    [96992] = { -- Resupply
        title = { "8:453348419:927428373", "เติมเสบียงช่าง" },
        description = { "407:1120235798:1493212752", "เขาใส่เครื่องมือมาพอเริ่มงานจำเป็นได้ แต่ของสำหรับยึดชิ้นส่วนยังไงก็ไม่พอ มือข้าพันเชือกได้แค่ไหนกันเชียว\n\nเตรียมตัวมาดีก็ดี แต่หาทางใช้ของที่มีให้เป็นยิ่งดีกว่า\n\nเอาถุงเปล่าไปที่ซากอาคารฝ่ายพันธมิตรที่ถูกไฟไหม้รอบ Cradle of Tranquility ทางตะวันตกเฉียงใต้ เก็บตะปูกับฉากยึดที่หาได้ในเถ้าถ่านใส่ถุงมาให้มากที่สุด" },
        objective = { "142:1569171460:883695436", "ค้นอาคารที่ถูกไฟไหม้ใน Cradle of Tranquility หา Metal Bracket 6 ชิ้น และตะปู (Nails) 30 ตัว แล้วนำกลับไปให้ Johun «Punchy» Dillas ใน Hyjal", amount = { "67:1769196724:1172831083 W2 20:1167232608:188918535 W1 52:1517631221:1930193378", "ค้นอาคารที่ถูกไฟไหม้ใน Cradle of Tranquility หา Metal Bracket {world2} ชิ้น และตะปู (Nails) {world1} ตัว แล้วนำกลับไปให้ Johun «Punchy» Dillas ใน Hyjal" } },
    },
    [97000] = { -- Grain of Memory
        title = { "15:524587290:1373771242", "ลายไม้แห่งความทรงจำ" },
        description = { "477:1050582108:2109219200", "ก่อนชีวิต... ครั้งที่สองนี้ ข้าฝึกอ่านลายไม้ในร้านของพ่อ\n\nเมื่อสงครามมาถึง Hyjal พ่ออยู่ต่อเพื่อทำอาวุธให้คนที่จะขึ้นไปบนยอดเขา ข้าหนีไป Lordaeron จดหมายฉบับสุดท้ายของพ่อส่งมาจากค่ายบนภูเขานั้น แล้วก็ไม่มีข่าวอีก\n\nความตายของข้าคงไม่อ่อนโยนไปกว่าของพ่อ พอฟื้นขึ้นมาที่ Undercity ข้ารู้สึกเหมือนเวลาผ่านไปหลายปี ทั้งที่จริงเพิ่งจะสองปี\n\nเจ้าดูมีกำลังพอจะปีนขึ้นไปได้ หากพบอะไรที่พ่อของข้า Lawrence Sawyer ทิ้งไว้ ก็จะช่วยปลอบใจข้าได้" },
        objective = { "87:249558377:1798689614", "ค้นค่าย Alliance ที่ถูกทำลายใน Hyjal เพื่อหาเบาะแสของ Lawrence พ่อของ Abigail Sawyer" },
    },
    [97119] = { -- Now We're Cooking
        title = { "17:144117203:1993877072", "ได้เวลาทำกับข้าว" },
        description = { "504:1008434207:1788646016", "ข้าดูแลจิตใจของคนที่นี่และทำอาหารเลี้ยงพวกเขาด้วย ข้าไม่ได้ร่ำเรียนวิชาทำครัวมาโดยตรง แต่ห้าปีมานี้ก็พอเรียนรู้วิธีทำอาหารอยู่บ้าง!\n\nคนที่นี่คงอยากลิ้มรสอะไรใหม่ ๆ ข้าจำได้ว่าก่อนเราจะรวมตัวกันบนภูเขา กอบลินจาก Everlook เคยยก Savory Stag Sliders ชิ้นเล็ก ๆ มาเสิร์ฟเป็นถาด ข้าอยากชิมอีกสักครั้ง บนนี้ก็มีกวางตัวผู้เยอะแยะ! เจ้าพอทำให้สักหน่อยได้ไหม?" },
        objective = { "57:1830485109:1680090372", "นำ Savory Stag Slider 6 ชิ้นไปให้ Ortak Lomgok ใน Elderwild", amount = { "6:1273960851:929420321 W1 50:1898821453:1337982466", "นำ Savory Stag Slider {world1} ชิ้นไปให้ Ortak Lomgok ใน Elderwild" } },
    },
    [93197] = { -- Mending Communications
        title = { "22:2000562375:712168553", "ฟื้นการติดต่อ" },
        description = { "365:1110420214:117022445", "ทั้งการต่อสู้และการถอยออกจาก Nordrassil Lodge ทำให้คนของเราที่นี่ขาดมืออย่างหนัก\n\nถ้าเจ้าเดินทางไปมาระหว่างที่นี่กับ Everlook ข้ามีจดหมายให้เอาไปส่งที่เมืองเพื่อกระจายต่อ และขอให้เอาจดหมายที่รออยู่กลับขึ้นมาด้วย ข้าเตรียมพัสดุที่จะส่งไว้กองหนึ่งแล้ว ถ้าเจ้ากรุณาช่วยขนไป" },
        objective = { "97:765875942:1845618223", "รับห่อจดหมายจาก Sebelia ที่ค่ายบนยอด Mount Hyjal แล้วนำไปส่งให้ Innkeeper Vizzie ใน Everlook" },
    },
    [93567] = { -- Ends Meet
        title = { "9:471761392:1481182345", "ปลายทางที่บรรจบ" },
        description = { "197:1130794658:201197861", "หน้าผาทางตะวันออกเฉียงใต้นั่น... ซากหอคอยนั่น เสียงกรีดร้องอันน่าสะพรึงของพวกเขาฝังลึกในใจข้า และยังสะท้อนอยู่ในความทรงจำไม่รู้จบ\n\nให้ข้าได้ปลดเปลื้องความหนักใจนี้และเล่าให้เจ้าฟังถึงความพ่ายแพ้ของข้าเถิด" },
        objective = { "93:702616900:1801559445", "ให้ทหารผ่านศึกสงครามครั้งที่สาม (Veteran of the Third War) เล่าเรื่องของเขาที่ปืนใหญ่พังใน Mourning's Rest" },
    },
    [93773] = { -- The Pact
        title = { "8:511960661:726150989", "พันธสัญญา" },
        description = { "190:1402156155:543083138 N 243:1208784724:1911152928", "ดูเหมือน Ve'han จะขโมยพลังของเทพแห่งพงไพรไปได้อย่างน้อยส่วนหนึ่ง ข้าแทบไม่อยากเชื่อว่าเป็นไปได้ แต่เรื่องมันก็เกิดขึ้นแล้ว\n\nแล้ว «พันธสัญญา» ที่ Ve'han พูดถึงคืออะไร? {name} เจ้าต้องกลับไปหา Ketharas แล้วบอกเขาว่าได้รู้อะไรมาบ้าง\n\nข้าเสียใจที่ต้องบอกว่าศัตรูอย่าง Ve'han คงเกินกำลังที่เจ้าจะล้มได้ มีเพียงพลังของ... อืม เหล่าเทพแห่งพงไพรเองเท่านั้นที่อาจต้านเวทนี้ได้" },
        objective = { "36:964316685:1218755786", "กลับไปรายงานกับ Ketharas บน Mount Hyjal" },
    },
    [96252] = { -- Tarnished Treasures
        title = { "19:573427331:411416301", "สมบัติที่แปดเปื้อน" },
        description = { "C 449:142380125:84320875", "{class} ข้าอยากขอให้เจ้าช่วยเรื่องหนึ่ง เป็นเรื่องส่วนตัวของข้าจริง ๆ\n\nตอนพวก Wormwing ซุ่มโจมตีและสังหารพี่น้องหญิงของข้า มันเอาเครื่องประดับของพวกนางไปอ้างว่าเป็นของที่ชิงได้จากการรบ ที่แย่กว่านั้นคือมันซ่อนสมบัติของเราไว้ในรังกับลูกที่ยังไม่ฟัก ยิ่งเห็นชัดว่าพวกมันเลวทรามแค่ไหน\n\nโปรดเก็บสมบัติของพี่น้องที่ตายไปกลับมา ถ้าเลี่ยงได้ก็อย่าทำไข่ที่ยังไม่ฟักเสียหาย แต่ถ้าไข่ศัตรูแตกไปบ้าง ข้าก็ไม่ถึงกับนอนไม่หลับ" },
        objective = { "66:2056567688:279913804", "เก็บ Tarnished Highfeather Bangle 8 ชิ้นจากรังฮาร์ปี Wormwing", amount = { "8:1089852795:1107240600 W1 57:1790649684:1322961952", "เก็บ Tarnished Highfeather Bangle {world1} ชิ้นจากรังฮาร์ปี Wormwing" } },
    },
    [92593] = { -- Avalanche of Corruption
        title = { "23:292048178:1324079453", "มลทินถาโถม" },
        description = { "455:1715593884:849987348", "เอาละ เจ้าพิสูจน์แล้วว่าจัดการงานจุกจิกได้ ทีนี้มาดูว่าจะไว้ใจให้รับมือภัยที่ใหญ่กว่านี้ได้ไหม\n\nการตั้งจุดรวบรวมข่าวกรองที่นี่เป็นแค่ขั้นแรก ถ้าอยากช่วยปูทางให้งานขั้นต่อไป ก็ลอบเข้าไปใน Dae'gun ซากฐานของฝ่ายฮอร์ดอย่างระวัง\n\nหาจุดสูงที่เหมาะจะตั้งหอสังเกตการณ์ กลับมารายงานรายละเอียดของพื้นที่ แล้วเราจะดูว่าจะบอกข้อมูลภารกิจให้เจ้าครบถ้วนได้อย่างไร" },
        objective = { "76:660804362:1752909375", "เข้าไปใน Dae'gun แล้วหาจุดสูงที่มองเห็นพื้นที่โดยรอบ จากนั้นกลับไปรายงานรายละเอียดให้ Johun ฟัง" },
    },
    [96959] = { -- Blademaster's Bonfires
        title = { "22:198349600:996098941", "กองไฟของจอมดาบ" },
        description = { "495:2101395664:243116257", "สงคราม\n\nกว่าข้าจะตอบรับเสียงเรียกของเหล่าเผ่า ศึกก็ผ่านไปแล้ว ดาบของข้าพบเพียงเถ้าถ่าน\n\nข้าตีเป้าหมายของตนขึ้นใหม่\n\nภูเขานี้จดจำความเข้มแข็ง พลังโบราณล่องไปกับสายลมและกักเก็บน้ำไว้ในภูเขา ข้าจะพิสูจน์ว่าคู่ควรจะเดินตามสันเขาไปยังป้อมที่ล่มสลายบนถนนขึ้นยอดเขา\n\nปีศาจกำลังเหยียบย่ำหลุมศพเหล่านี้ ก่อนข้าจะสู้เคียงข้างเจ้า ข้าต้องรู้ว่าเจ้ารับมือไหว จุดกองไฟสองกองแล้วกลับมาหาข้า เปลวไฟจะล่อศัตรูของเราออกมา" },
        objective = { "56:719431031:1363804121", "จุดกองไฟทั้งสองกองใน Dae'gun แล้วกลับไปหา Yashiro" },
    },
    [97010] = { -- Blind Vengeance
        title = { "15:50897222:720936297", "การล้างแค้นในเงามืด" },
        description = { "357:1412745423:39773367", "เตรียมเศษผลึกสลักรูนไว้แล้ว ถ้าปล่อยจากที่สูงพอ มันจะแตกเมื่อกระแทก ฉีกทะลุเกราะและเนื้อปีศาจ\n\nมีหอคอยมองลงมาเห็นแดนร้างนี้ สูงพอสำหรับที่เราต้องการ\n\nเราจะปีนขึ้นไป ข้าจะแฝงตัวในเงาและระวังด้านข้างให้เจ้า\n\nเมื่อถึงยอด ส่งสัญญาณด้วยการโยนลงไปก่อน ข้าจะถล่มพวกมันตาม" },
        objective = { "144:444952468:1191199562", "ปีนขึ้นไปบนยอด Horde Mage Tower แล้วขว้าง Explosive Runeshard เพื่อส่งสัญญาณให้ Maerion Thaelemaches เริ่มโจมตีเหล่าปีศาจ" },
    },
    [92594] = { -- Kindling, Kinda
        title = { "15:1368880215:1330340383", "ใช้เป็นเชื้อไฟได้มั้ง" },
        description = { "449:1938999747:1436803320", "ไหน ๆ เจ้าก็เดินทางไปทั่วภูเขา ข้าอดขอให้ช่วยอีกเรื่องเล็ก ๆ ไม่ได้...\n\nเห็นพุ่มไม้กับพืชปนเปื้อนเฟลเกลื่อนเนินเขาด้านล่างไหม? ปรากฏว่ามันติดไฟดีเอาเรื่อง มีทั้งข้อดีและข้อเสีย เอาไปป้อนเตาเล็ก ๆ ได้สะดวก แต่ก็เสี่ยงพันกันแล้วติดเฟือง... หรือติดเชือกรองเท้า!\n\nขากลับลงเขาช่วยถางให้บางลงหน่อย พอวัชพืชแห้งแล้วข้าจะลงไปเก็บเอง" },
        objective = { "97:1138569814:260134744", "ทำลายพุ่มไม้ปนเปื้อน (Tainted Shrubbery) 15 พุ่มให้ Kaylaena Springwhisper ที่โรงช่างใน Tainted Foothills", amount = { "8:286779151:428491486 W1 87:1503776494:11690334", "ทำลายพุ่มไม้ปนเปื้อน (Tainted Shrubbery) {world1} พุ่มให้ Kaylaena Springwhisper ที่โรงช่างใน Tainted Foothills" } },
    },
    [93406] = { -- Unfrozen Deliveries
        title = { "19:1487929368:773789196", "จดหมายฝ่าหนาว" },
        description = { "411:806572054:1642421817", "เจ้าต้องขนจดหมายขากลับขึ้น Mount Hyjal ใช่ไหม? มีปัญหานิดหน่อย...\n\nเมื่อไม่กี่วันก่อน มีคนมารื้อจดหมายที่จะส่งออก! คงหาเงินที่คนใส่มาในซองนั่นแหละ มันหนีไปตามเนินเขาที่ไหนสักแห่งทางเหนือแล้วก็ไม่กลับมาอีก คงโดนเยติฉีกเป็นชิ้น ๆ หรืออะไรสักอย่าง!\n\nยังไงก็เถอะ ถ้าอยากขนจดหมายกลับ เจ้าก็ต้องไปตามเอามาก่อน!" },
        objective = { "99:181252276:1106347206", "หาจดหมายที่หายไป (Missing Mail) 4 ฉบับตามเนินเขาทางเหนือของ Everlook แล้วนำกลับไปให้ Innkeeper Vizzie", amount = { "5:72389936:1525592206 W1 93:707369643:2122779802", "หาจดหมายที่หายไป (Missing Mail) {world1} ฉบับตามเนินเขาทางเหนือของ Everlook แล้วนำกลับไปให้ Innkeeper Vizzie" } },
    },
    [93759] = { -- The Bounty of Nature
        title = { "20:2075722718:46676508", "ของขวัญจากธรรมชาติ" },
        description = { "470:1912868106:568398823", "เจ้าทำได้ดี ช่วยทั้งข้าและภูเขาไว้มาก\n\nข้ากำลังจะทำสตู ยินดีแบ่งให้เจ้าชิมถ้าเจ้าช่วยหาวัตถุดิบมาสักหน่อย\n\nแม้ข้าไม่อยากฆ่าสัตว์ป่าเลย แต่วัฏจักรชีวิตต้องอาศัยอาหาร เราควรใช้วัตถุดิบให้สมดุล เนื้อ Hyjal Venison Cuts จากกวาง Hyjal Stag สักสองสามชิ้นน่าจะเข้ากับหัวที่อุดมด้วยแป้งของต้น Scarlet Dart Tuber ที่ขึ้นตามพื้นที่สีเขียวแถวนี้" },
        objective = { "104:1813276328:1113656672", "เก็บเนื้อกวาง Hyjal (Hyjal Venison Cuts) 2 ชิ้นจากกวาง Hyjal Stag ที่ไม่ปนเปื้อน และหัว Scarlet Dart Tuber 6 หัวสำหรับทำสตูของฤๅษี", amount = { "8:1089852795:1107240600 W1 51:1345691313:623630425 W2 43:85520111:1505359911", "เก็บเนื้อกวาง Hyjal (Hyjal Venison Cuts) {world1} ชิ้นจากกวาง Hyjal Stag ที่ไม่ปนเปื้อน และหัว Scarlet Dart Tuber {world2} หัวสำหรับทำสตูของฤๅษี" } },
    },
    [95568] = { -- Seeds for a New Season
        title = { "22:1630462176:1960571850", "เมล็ดพันธุ์สำหรับฤดูใหม่" },
        description = { "389:1877105594:1598546580", "เจ้ามาถึง Mount Hyjal ในช่วงที่หลายสิ่งกำลังเปลี่ยนไป คนแปลกหน้า\n\nเจ้าอาจเห็นแล้วว่าผืนดินมีแผลจากสงครามเก่าและแปดเปื้อนพลังเฟล หาก Hyjal จะอยู่รอด ธรรมชาติต้องผลิบานอีกครั้ง\n\nถ้าเจ้าช่วยเก็บเมล็ดจากพืชที่ยังไม่แปดเปื้อนได้ ข้าจะขอบใจมาก ทางตะวันออกมีดอกไม้ป่าขึ้นอยู่เยอะ มองหาดอกเล็ก ๆ สีแดงหรือสีเหลือง" },
        objective = { "40:1452865522:2019351564", "เก็บเมล็ดพันธุ์ที่ไม่ปนเปื้อน (Untainted Seeds) 10 เมล็ดให้ Ketharas", amount = { "8:1089852795:1107240600 W1 30:1420365304:1624139305", "เก็บเมล็ดพันธุ์ที่ไม่ปนเปื้อน (Untainted Seeds) {world1} เมล็ดให้ Ketharas" } },
    },
    [90854] = { -- Leather for Inclement Weather
        objective = { "6:1273960851:929420321 W1 23:1023567136:2089974552 W2 58:1492997520:162776456", "นำ Rugged Armor Kit {world1} ชุด และ Cured Rugged Hide {world2} ผืนไปให้ Zet'gan ที่ Elderwild บน Mount Hyjal" },
        title = { "29:1976732074:2005156508", "เครื่องหนังรับมืออากาศร้าย" },
        description = { "337:1420384450:1160965052", "อยู่กลางป่ามาห้าปี ของที่มีสึกหรอไปเยอะ พวกเราต้องสร้างที่นี่เองตั้งแต่ต้น! เราอยากได้ฝีมือช่างหนังอย่างเจ้ามาช่วย\n\nข้าต้องซ่อมเต็นท์กับอาคารสองสามหลัง แล้วก็ปะเกราะ ถ้าเจ้าเอา Rugged Armor Kit มาสองชุดกับ Cured Rugged Hide หนึ่งผืน ข้าจะช่วยทำให้เป็นของพิเศษ" },
    },
    [92189] = { -- Back to the Grind
        objective = { "6:1273960851:929420321 W1 29:315249015:1940076383 W2 69:941103846:720977298", "นำ Dense Sharpening Stone {world1} ชิ้น และ Dense Grinding Stone {world2} ชิ้นไปให้ Trigg Ironhand ที่ Elderwild บน Mount Hyjal" },
        title = { "17:2062183408:633268219", "กลับมาลับคม" },
        description = { "347:1328145774:1452603508", "เฮ้อ พวกเราต้องสร้างหมู่บ้านนี้ขึ้นเองจากของเท่าที่หาได้หลังสงคราม สู้อยู่เรื่อย ๆ จนอาวุธสึกหมด ไหนจะต้องใช้เครื่องมืออีก!\n\nข้าดูออกเสมอว่าใครเป็นช่างตีเหล็กเหมือนกัน เจ้าพอเจียดเวลาและวัสดุมาทำ Dense Sharpening Stone กับ Dense Grinding Stone ให้ข้าสักหน่อยได้ไหม? เราต้องใช้จริง ๆ!" },
    },
    [93615] = { -- Kits and Cats
        title = { "13:302980180:1523701243", "ลูกจิ้งจอกกับแมว" },
        description = { "486:1156907657:2041145645", "โอ้ ของกินน่าอร่อย...\n\nอย่ากลัวเลย ข้าล้อเล่น ถึงข้าจะหักกระดูกสันหลังเจ้าได้เหมือนหักกิ่งไม้แห้งก็เถอะ ข้าเป็นกึ่งเทพแห่งพงไพรนี่นะ\n\nถ้าอยากให้ข้าโปรดปรานและรอดจากการเป็นอาหารของข้า ข้าฝากงานให้ทำสักอย่างได้ไหม?\n\nลูก ๆ ของข้าเตร็ดเตร่ออกไปหาอะไรเล่น บนภูเขานี้แทบไม่มีอะไรทำร้ายพวกมันได้ตรง ๆ แต่ใกล้ยอดเขากำลังมีเรื่องมืดมน ข้าไม่อยากฝากชะตาของลูกไว้กับโชค\n\nช่วยไปดูให้หน่อยได้ไหม? แลกกับที่ข้าไม่กินเจ้า แน่นอน" },
        objective = { "54:1610370074:342464423", "ตามหาลูกแมวของ Shalla'kal ในป่าบน Mount Hyjal" },
    },
    [93831] = { -- Sweetpaw Jam
        title = { "12:370243528:1967470243", "แยม Sweetpaw" },
        description = { "358:1422810190:204009506", "เจ้ามีกลิ่นเหมือนลมภูเขา แข็งแรงและเป็นอิสระ! ข้ามีงานให้ ถ้าอุ้งเท้าเจ้ายังว่าง\n\nเราชอบผล Bear Berries ผลกลมสีแดง พอผ่านน้ำค้างแข็งแล้วหวานเหมือนน้ำผึ้ง หาดูตามร่มไม้ มีทั้งหินคมและสัตว์ปีกคลุ้มคลั่งมากเกินกว่าพวกเราจะไปถึงพุ่มที่ลูกสุกที่สุด\n\nเอามาให้ข้าสักกอง ข้าจะทำ Sweetpaw Jam! ของกินเล่นอย่างดีที่สุดของข้า แล้วจะแบ่งให้เจ้าชิม\n\nตกลงไหม?" },
        objective = { "60:1804939869:505228678", "เก็บเบอร์รีหมี 30 ลูกใน Hyjal แล้วกลับไปหา Osi Mistpaw", amount = { "7:451016854:1830523975 W1 51:1984949950:419811938", "เก็บเบอร์รีหมี {world1} ลูกใน Hyjal แล้วกลับไปหา Osi Mistpaw" } },
    },
    [2000] = { -- Rokar Bladeshadow
        title = { "17:1521332015:535489184", "โรคาร์ เบลดแชโดว์" },
        description = { "28:711453027:1470049276 N 472:183489711:793977750", "เจ้าว่างมือมานานเกินไปแล้ว {name} ถึงเวลาเรียนวิชาชีพของเราให้ลึกขึ้น เมื่อคืนนี้คนของเราห้าคนถูกพบเป็นศพในร่องหินแห่งหนึ่งใน Orgrimmar แทบไม่เหลือเบาะแส มีคนที่ต่อต้านเราและใช้วิธีของเราย้อนมาเล่นงานเราเอง\n\nข้าจึงตัดสินใจให้เจ้าเรียนวิชาสะเดาะกุญแจ\n\nเสียดายที่มือข้าไม่ถนัดงานนี้ ไปหา Rokar ที่อยู่ตามเนินเขาใกล้ Durotar เถอะ ถึงเขาจะแก่แล้ว ข้าว่าฝีมือยังไม่ตกหรอก" },
    },
    [2018] = { -- Rokar's Test
        title = { "12:437084152:424540693", "บททดสอบของ Rokar" },
        description = { "267:761847389:396178892 N 227:1234281069:103503580", "อ้อ ทีนี้ Therzok ส่งศิษย์มือใหม่มาหาข้าแล้วหรือ? เอาเถอะ ข้าคงพอสอนเจ้าได้สักอย่างสองอย่าง ธุระของเจ้าไม่ใช่เรื่องที่ข้าใส่ใจนัก แต่ข้าไม่อยากติดค้างใจว่าปล่อยให้เจ้าไปตาย\n\nแต่เจ้าต้องพิสูจน์ก่อนว่าคู่ควร\n\nข้าจะบอกอะไรให้ {name} ข้าไม่ชอบ Venture Company เอาเสียเลย ผืนดินนี้ทำให้ข้านึกถึง Draenor ข้าไม่อยากเห็นพวกกอบลินนั่นทำลายมัน ถ้าผู้คุมงานของพวกมันที่ Sludge Fen ถูกฆ่า กิจการของพวกมันคงสะดุดหนัก" },
    },
    [2019] = { -- Tools of the Trade
        title = { "18:2016515751:456482828", "เครื่องมือประจำอาชีพ" },
        description = { "13:939218444:1640774044 N 354:1686820813:990884788", "เอาไปสิ {name} ของพวกนี้น่าจะช่วยเจ้าได้ดี ข้าทำด้วยมือตัวเอง รับรองว่าหาดีกว่านี้ไม่ได้\n\nส่วนธุระของเจ้าไม่ต้องเล่าให้ข้าฟังหรอก ข้าไม่สนแผนการของ Therzok ขอแค่ได้ใช้ชีวิตหลังวางมืออย่างสงบก็พอ\n\nถ้าต้องใช้เครื่องมือชุดใหม่ ก็กลับมาหาข้า ข้าจะจัดให้ แต่ใช้ให้ระวังด้วย!" },
    },
    [5383] = { -- Krastinov's Bag of Horrors
        title = { "26:1527705856:1674333906", "ถุงสยองขวัญของ Krastinov" },
        description = { "230:1575816845:357975208", "เจ้าเปิดถุงแล้วพบเครื่องทรมานนานาชนิด ท่ามกลางของเหล่านั้น มีของประหลาดชิ้นหนึ่งสะดุดตา ขวดแก้วบรรจุเลือดที่ยังอุ่นเมื่อแตะ\n\nเจ้าคิดว่าคนตระกูล Sarkhoff อาจสนใจสิ่งที่เจ้าพบ" },
    },
    [9030] = { -- Anthion's Parting Words
        title = { "23:573656928:1309079977", "คำลาของ Anthion" },
        description = { "397:1005612802:1633102748", "วิญญาณของ Valthalak ถูกเก็บไว้ในเครื่องรางนี้ ด้วยความโลภ เราโง่เขลาแยกมันออกเป็นสามชิ้น โดยไม่รู้เลยว่าคำสาปอะไรรอเราอยู่\n\nทางเดียวที่จะหยุดมนตร์ของ Valthalak ได้คือประกอบเหรียญเครื่องรางกลับให้ครบ กลับไปหา Deliana แล้วบอกนางว่า Bodley คือความหวังเดียวที่จะหาชิ้นส่วนที่เหลือเจอ\n\nในที่สุดข้าจะได้พักอย่างสงบเสียที ขอให้เจ้าโชคดี เจ้าต้องพึ่งโชคแน่!" },
    },
    [93833] = { -- Wicked Wisdom
        title = { "13:2142002564:324296275", "ปัญญาจากนกฮูก" },
        description = { "428:502745916:881776970", "นกฮูกแห่ง Hyjal มีดีมากกว่าขนปีกและการบิน กรงเล็บ ขน หรือแม้แต่กระดูกของพวกมันล้วนกระซิบเสียงแห่งพงไพร เราใช้ของเหล่านี้ทำเครื่องรางผูกวิญญาณและคุ้มกันคนของเรา\n\nแต่นกฮูกไม่ยอมมอบให้เปล่า เจ้าต้องเอาสิ่งที่ภูเขามีให้ ฆ่านกฮูกแล้วเอาซากมาให้ข้า\n\nใช่ เราขอให้เจ้าเอากลับมาทั้งตัว เราไม่ทิ้งสิ่งใดที่ได้จากสัตว์สง่างามเช่นนี้", variants = { { "427:1145072594:1223512059", "นกฮูกแห่ง Hyjal มีดีมากกว่าขนปีกและการบิน กรงเล็บ ขน หรือแม้แต่กระดูกของพวกมันล้วนกระซิบเสียงแห่งพงไพร เราใช้ของเหล่านี้ทำเครื่องรางผูกวิญญาณและคุ้มกันคนของเรา\n\nแต่นกฮูกไม่ยอมมอบให้เปล่า เจ้าต้องเอาสิ่งที่ภูเขามีให้ ฆ่านกฮูก 5 ตัวแล้วเอาซากมาให้ข้า\n\nใช่ เราขอให้เจ้าเอากลับมาทั้งตัว เราไม่ทิ้งสิ่งใดที่ได้จากสัตว์สง่างามเช่นนี้" } }, amount = { "283:1905259624:1573383620 W1 143:1338168456:1258911672", "นกฮูกแห่ง Hyjal มีดีมากกว่าขนปีกและการบิน กรงเล็บ ขน หรือแม้แต่กระดูกของพวกมันล้วนกระซิบเสียงแห่งพงไพร เราใช้ของเหล่านี้ทำเครื่องรางผูกวิญญาณและคุ้มกันคนของเรา\n\nแต่นกฮูกไม่ยอมมอบให้เปล่า เจ้าต้องเอาสิ่งที่ภูเขามีให้ ฆ่านกฮูก {world1} ตัวแล้วเอาซากมาให้ข้า\n\nใช่ เราขอให้เจ้าเอากลับมาทั้งตัว เราไม่ทิ้งสิ่งใดที่ได้จากสัตว์สง่างามเช่นนี้" } },
        objective = { "68:2076027108:1250194929", "นำซากนกฮูก 5 ตัวไปให้ Elder Pinespeaker ที่ Barkskin Burrow ใน Hyjal", amount = { "6:1273960851:929420321 W1 61:363428504:1354329995", "นำซากนกฮูก {world1} ตัวไปให้ Elder Pinespeaker ที่ Barkskin Burrow ใน Hyjal" } },
    },
    [93952] = { -- Balance Through Strength
        title = { "24:1690720338:1156865467", "คืนสมดุลด้วยกำลัง" },
        description = { "372:1369995540:590649413", "เผ่า Barkskin ยืนอยู่บนรากที่อ่อนแอ พวก Deadwood ตะกุยแผ่นดินเรา ความเน่าของมันชอนไชลึกขึ้นทุกวัน เราต้านตามลำพังไม่ไหว\n\nผู้เฝ้าโพรง Deadwood คือกำลังหลักของพวกมัน ถ้าอยากให้เราไว้ใจ จงจัดการพวกที่ทำให้ป่าแปดเปื้อน เมื่อผู้พิทักษ์ล้ม คนที่เหลือในเผ่าก็จะอ่อนกำลัง พวกเราจึงจะพอสู้ได้\n\nโค่นพวกมันเพื่อคืนสมดุลและช่วยรักษา Hyjal ไว้" },
        objective = { "54:1297624463:393274358", "กำจัดผู้พิทักษ์รัง Deadwood 9 ตัว แล้วกลับไปหา Brerufa", amount = { "7:1265997621:1189804897 W1 46:256393804:564742459", "กำจัดผู้พิทักษ์รัง Deadwood {world1} ตัว แล้วกลับไปหา Brerufa" } },
    },
    [96262] = { -- Prickly Pinecones
        title = { "17:519763699:247644992", "ลูกสนหนามแหลม" },
        description = { "459:1193549992:1532945461", "ข้ารู้จักเนินเขาแถวนี้ตั้งแต่เพิ่งฟักจากไข่ ถ้ามีเรื่องหนึ่งที่รู้แน่ ก็คือลูกสนแก้ปัญหาได้ตั้งหลายอย่าง\n\nคงนึกไม่ถึงล่ะสิ?\n\n<อีกาขยิบตาให้เจ้าอย่างรู้กัน>\n\nไปเก็บมาให้ข้าหน่อย เป็นส่วนหนึ่งของแผนเล็ก ๆ ที่ข้ากำลังฟักอยู่ รับรองว่าคุ้มแรง\n\nน่าจะหาได้ใต้ต้นไม้ที่ยังแข็งแรงหรือมีชีวิตแถวนี้ อยู่ให้ห่างต้นที่แปดเปื้อนนะ ลูกสนจากต้นพวกนั้นใช้ไม่ได้!" },
        objective = { "49:1885205699:1011141123", "เก็บลูกสนหนาม 10 ลูกจากใต้ต้นไม้ที่ยังสมบูรณ์", amount = { "8:1089852795:1107240600 W1 39:431720445:2091205256", "เก็บลูกสนหนาม {world1} ลูกจากใต้ต้นไม้ที่ยังสมบูรณ์" } },
    },
    [96616] = { -- Herbs for the Bruised and Weary
        title = { "31:1398220929:48337870", "สมุนไพรสำหรับผู้บาดเจ็บและอ่อนล้า" },
        description = { "270:745933947:1319004072 C 194:1411693627:1417302877", "จริงหรือเนี่ย? นักเดินทางกลับมาที่ Hyjal แล้ว!\n\nข้าแทบไม่อยากเชื่อ! ถ้าเจ้าช่วย บางทีเราอาจออกจากที่นี่ได้เสียที พวก Scourge ที่ยังเหลือทางตะวันออกบุกเราตลอด หลายคนตกเป็นเหยื่อมลทินของมัน\n\nได้โปรด {class} ข้ามีเรื่องอยากขอให้ช่วย ในหุบเขาทางเหนือมีสมุนไพรดอกสีฟ้าที่ช่วยบรรเทาความเจ็บจากการติดเชื้อ เก็บมาให้ข้าหน่อย ข้าจะได้ช่วยคนเจ็บ" },
        objective = { "26:125158384:629569969", "เก็บ Hyjal Silphium 12 ต้น", amount = { "8:1089852795:1107240600 W1 16:1587581778:1168817513", "เก็บ Hyjal Silphium {world1} ต้น" } },
    },
    [97007] = { -- Wood Remains
        title = { "12:1532418530:627544154", "ทรัพย์สินที่ยังเหลือ" },
        description = { "458:724347155:2039310593", "ข้าประทับตราหน้าที่เกี่ยวข้องในเอกสารของ Abigail และแก้ไขบันทึกของทางเราแล้ว\n\nหาก Abigail จะขนทรัพย์สินส่วนใดเข้าเขตของ Forsaken นางต้องแจ้งสำนักงานสำมะโนหลวงเพิ่มเติม\n\nเอาสมุดบัญชีกลับไปให้นางได้ ฝากเตือนด้วยว่านางยังทำตามสัญญากับฝ่ายเสบียงของ War Quarter ไม่ครบ ทางที่ดีควรรอก่อนใช้สิทธิเรียกร้องทรัพย์สินก่อนสงคราม" },
        objective = { "79:793257023:795581920", "นำ Sawyer Family Ledger ที่รับรองแล้วกลับไปให้ Abigail Sawyer ใน War Quarter" },
    },
    [91698] = { -- Barkskin Breakout
        title = { "17:970010256:1777957126", "ช่วยเผ่า Barkskin แหกกรง" },
        description = { "231:2080572469:716600290", "<แม่เฒ่าเฟอร์โบลก์พูดกับเจ้าจากในกรง>\n\n«Deadwood ขังข้ากับลูกในกรงแข็งแรง กุญแจห้อยที่เข็มขัด Deadwood Warden เจ้าตามล่ามัน เอากุญแจ เปิดสลัก ปล่อยเรา ทำอย่างนี้แล้ว Barkskin จะรู้ว่าเจ้าจริงใจ»" },
        objective = { "78:1543754074:1135513200", "นำ Deadwood Key จาก Deadwood Warden กลับไปที่ Barkskin Cage" },
    },
    [92100] = { -- Anywhere But Here
        title = { "17:554550067:756393728", "ที่ไหนก็ได้ที่พ้นจากตรงนี้" },
        description = { "483:729348954:92741106", "<วิญญาณปรากฏตรงหน้าเจ้า หลังหาวเสียจนตัวโยน>\n\nเจ้าไม่ได้พาทหารมาด้วย... แล้วก็ไม่ได้แต่งตัวเหมือนทหาร แปลว่าเราขับไล่ Archimonde ไปได้แล้วหรือ?\n\nนานเหลือเกิน ข้าเกือบลืมแล้วว่าเคยเป็นอะไร แต่เจ้า... คงเป็นคนกลุ่มแรกที่เดินผ่านหลุมพวกนี้ในรอบหลายปี\n\n<ทหารผ่านศึกกวาดตามองรอบตัว>\n\nไปคุยกันต่อที่จุดชมวิวทางตะวันตกของที่นี่เถอะ ข้าจำภาพจากตรงนั้นได้ชัดเจน นานมาแล้วข้าทิ้งฝักดาบไว้ที่นั่น" },
        objective = { "60:498891127:2003713822", "ตามหาฝักดาบของทหารผ่านศึกสงครามครั้งที่สามใกล้ Elderwild" },
    },
    [92317] = { -- Stolen Life
        title = { "11:1849677159:1515147814", "ชีวิตที่ถูกขโมย" },
        description = { "490:53443361:817294067", "งั้นดรูอิดฤๅษีกำลังหาพลังมาถ่วง «ชีวิต» ในเวทของเขาหรือ? คำตอบก็ต้องเป็นความตายอยู่แล้ว เจ้ามาถูกที่แล้วละ\n\nคงเห็นพวกอันเดดเพ่นพ่านทั่วเขตของข้าแล้ว พวกมันใช้พลังที่ขโมยมาเคลื่อนไหวได้แม้ตายไปแล้ว\n\nพลังที่ขโมยมานั่นแหละคือสิ่งที่เวทของเจ้าต้องใช้ ฆ่าพวกอันเดดแล้วค้นกะโหลกของมันหา Drop of Stolen Life ที่จับตัวเป็นหยด พอได้แล้วนำกลับไปให้ Ketharas" },
        objective = { "100:216323730:254311422", "หา Drop of Stolen Life จากพวก Scourge ในซากปรักหักพังบน Mount Hyjal แล้วกลับไปหา Ketharas" },
    },
    [93832] = { -- Shatter the Stonewatchers
        objective = { "8:286779151:428491486 W1 100:1429632364:2141842074", "ทำลายการ์กอยล์ Eternal Sentry {world1} ตนที่ฐานของฝ่ายสัมพันธมิตรซึ่งถูกทำลายในเขต Hyjal ตอนบน แล้วกลับไปหา Elder Mistpaw" },
        title = { "25:378625274:1578054206", "ทุบผู้เฝ้าหินให้แหลก" },
        description = { "344:1460422270:1270592162", "ลาดเขาสูงมีปีกหิน สัตว์หิน กึ่งเป็นกึ่งตาย มือชั่วร้ายแกะสลักพวกมันขึ้นมา อย่าไว้ใจที่มันนิ่ง ดวงตาคู่นั้นรอให้ใครก้าวพลาดอยู่\n\nลูกหลานเราไม่รู้ว่ามันอันตราย พออุ้งเท้าเข้าใกล้ หินก็ตื่นมาพร้อมกรงเล็บและเขี้ยว\n\nไปทุบร่างต้องสาปพวกนี้ หักปีก บดเศษหิน แล้วให้ภูเขาได้หายใจอย่างอิสระ" },
    },
    [95107] = { -- Deeproar Down
        objective = { "85:1317643492:1133645316", "สังหาร Chieftain Deeproar แล้วนำคทาของเขากลับไปให้ Elder Pinespeaker ที่ Barkskin Burrow" },
        title = { "13:1608984460:56134820", "โค่น Deeproar" },
        description = { "304:135972317:1383829083", "Deeproar หัวหน้าคนหนึ่งของ Deadwood คำรามอยู่ลึกในโพรง ครั้งหนึ่งเขาไม่สังกัดโพรงไหน แล้วคืนหนึ่งที่มีเรื่องบาดหมาง เขาก็ตกอยู่ใต้อาคมของพวกนั้น\n\nตอนนี้เขากินน้ำเลี้ยงไม้รสเปรี้ยวของพวกมัน เสียงคำรามต้องสาปจึงรุนแรงขึ้นเป็นเท่าตัว\n\nไปหยุดเรื่องชั่วร้ายที่เขาทำ เอาคทากลับมาให้ข้าดู จะได้รู้ว่ามันไม่อยู่ในมือเขาแล้ว" },
    },
    [95108] = { -- Mystic Mix
        objective = { "87:831640672:751551291", "สังหาร Deadwood Death Mystic สองตน และทำลาย Deadwood Cauldron สองใบภายใน Deadwood Den" },
        title = { "10:1833121602:2123580190", "ของผสมอาคม" },
        description = { "242:47945361:943383913", "เราใช้ญาณมองเห็นโพรงของพวกมันแล้ว พวก Deadwood ต้มของทำพิธีมืดในหม้อ เอาของผสมชั่วร้ายนี้ป้อนลูกหลานให้ความชั่วหยั่งราก แล้วสอนให้สู้ด้วยวิธีต่ำช้า\n\nไปหยุดไม่ให้มันลาม ฆ่าพวกที่ใช้อาคมมืดและทุบหม้อต้มของมันเสีย" },
    },
    [96296] = { -- Fetid Corruption
        title = { "16:600747617:635229704", "มลทินเน่าเหม็น" },
        description = { "483:906126549:765289534", "<ทันทีที่เจ้าเข้าใกล้ปุ่มไม้ที่เต้นตุบ ๆ มันก็หลุดจากต้น เผยให้เห็นน้ำเลี้ยงสีเขียวไหลซึม ดูเหมือนมลทินในเปลือกจะลามลึกเข้าไป แต่ต้นไม้ยังไม่ตาย\n\nมองไปรอบ ๆ จะเห็นว่ามลทินลามไปถึงต้นไม้ใกล้ ๆ บางต้นแล้ว แต่ละต้นมีอาการหนักเบาต่างกัน\n\nบางทีอาจยังไม่สายที่จะช่วยต้นไม้ที่ติดมลทินแถวนี้\n\nพวก Highfeather คงขอบใจถ้าเจ้าเอาปุ่มไม้ที่แปดเปื้อนออกให้มากที่สุดเท่าที่จะหาเจอ>" },
        objective = { "56:120861762:1376558905", "ค้นหาและแกะปุ่มปมที่แปดเปื้อน 6 ปุ่มออกจากต้นไม้ใกล้ ๆ", amount = { "16:2025424710:1027151333 W1 39:1217646959:2076089195", "ค้นหาและแกะปุ่มปมที่แปดเปื้อน {world1} ปุ่มออกจากต้นไม้ใกล้ ๆ" } },
    },
    [96957] = { -- Bone Sweet Bone
        title = { "15:217040006:1866663015", "กระดูกแสนรัก" },
        description = { "503:179641477:1876328726", "ฟังนะ ผู้มีวันตาย งานของพวกที่อยู่ใต้ปีกข้าอาจดูไม่ยิ่งใหญ่ แต่พวกเขาช่วยรักษาสมดุลธรรมชาติ เราคืนสารอาหารจำเป็นให้ดิน เพื่อให้ชีวิตใหม่เติบโตได้\n\nพวกอันเดดทำให้วัฏจักรที่นี่รวนและขับไล่พวกที่มาขออาศัยใต้ปีกข้า ไหน ๆ เจ้าก็จะออกไปฆ่าอะไรต่อมิอะไรอย่างที่ชอบ ช่วยเก็บกระดูกมาให้ข้าบ้างได้ไหม?\n\nข้าอยากสร้างรังของลูก ๆ และผู้ติดตามขึ้นใหม่ พอภัยนี้จบลง เราจะได้กินเลี้ยงกัน" },
        objective = { "30:1795399499:1920618675", "รวบรวม Sun-Bleached Bone 20 ชิ้น", amount = { "8:1089852795:1107240600 W1 20:2063730035:514959206", "รวบรวม Sun-Bleached Bone {world1} ชิ้น" } },
    },
    [91883] = { -- Spear of the Skylord
        title = { "20:1850994488:2104234329", "หอกของ Skylord" },
        description = { "477:887941404:726417301", "ข้ากำลังต้านฮาร์ปี Wormwing อยู่ก็ถูกฮาร์ปีชื่อ Zarrat ที่ลาดตระเวนแถวนี้ซุ่มโจมตีอย่างหนัก นางฉวยหอกแล้วบินหนีไปก่อนข้าตั้งตัวทัน ข้าไม่รู้ว่านางอยากได้ไปทำอะไร\n\nหอกนั้นอยู่กับตระกูลข้ามาหลายรุ่นและสำคัญกับข้ามาก ถ้าเห็น Zarrat ปะปนอยู่กับพวกฮาร์ปี จงสังหารนางแล้วเอาหอกมาคืน นางซ่อนตัวเก่ง คงหาได้ไม่ง่าย แต่ข้าจะขอบใจมากถ้าได้หอกคืน" },
        objective = { "48:1767753228:1683764642", "สังหาร Zarrat Wormwing แล้วนำหอกของ Omnuron กลับมาคืน" },
    },
    [92017] = { -- Cleansing Winds
        title = { "15:1463852271:2123969463", "สายลมชำระมลทิน" },
        description = { "430:2059380263:1484877850", "สัตว์ปีกบนยอดเขายังหายใจในกระแสลมสูงที่มลทินยังครอบงำไม่ทั่วถึง ขนฮิปโปกริฟกับขนคิเมราลอยตามลม ซึมซับความทรงจำของอากาศยามผืนดินยังบริสุทธิ์ ข้าต้องใช้ขนเหล่านี้เพื่อให้เครื่องหอมชำระมลทินจับพลังไว้ได้และออกฤทธิ์แรงขึ้น\n\nรวบรวมมาให้ข้า ข้าจะได้รวมความรู้ที่สายลมเก็บไว้ในควันชำระล้าง ก่อนเราเริ่มพิธี" },
        objective = { "70:1665629699:886077951", "เก็บขนฮิปโปกริฟฟ์ใหญ่ 5 ขนและขนไคมีรามันเยิ้ม 3 เส้นให้ Marn", amount = { "8:1089852795:1107240600 W1 31:412129462:2058705881 W2 29:1431126280:362602877", "เก็บขนฮิปโปกริฟฟ์ใหญ่ {world1} ขนและขนไคมีรามันเยิ้ม {world2} เส้นให้ Marn" } },
    },
    [96971] = { -- To Outfox a Demon
        title = { "17:1936078724:1924975709", "ใช้เล่ห์จิ้งจอกหลอกปีศาจ" },
        description = { "485:867843502:2075414450", "นี่ ไหน ๆ เจ้าก็เดินเที่ยวอยู่ในถิ่นของข้า ช่วยทำอะไรให้สักอย่างได้ไหม?\n\nพอชนะสงคราม กองทัพหลายกองก็ยกกลับไป ไม่รู้ทำไมถึงคิดว่าเสบียงบางส่วนไม่คุ้มจะขนไป หรืออาจตายกันหมดก็ได้ ใครจะรู้?\n\nอย่างไรก็เถอะ ของพวกนี้มีประโยชน์กับข้าและลูก ๆ เสียดายว่ามักอยู่ตรงที่มีปีศาจ เอากระจุกขนนี้ไปใช้เบี่ยงความสนใจของปีศาจระหว่างหยิบเครื่องมือ" },
        objective = { "29:692296315:76140207", "รวบรวม Abandoned Supplies 8 ชุด", amount = { "8:1089852795:1107240600 W1 20:86177217:718641492", "รวบรวม Abandoned Supplies {world1} ชุด" } },
    },
    [96991] = { -- Trail Assist
        title = { "12:139460624:138596563", "ช่วยแบ่งสัมภาระขึ้นเขา" },
        description = { "456:748228515:1428606948", "ทางจากนี้ชันขึ้นอย่างที่เจ้าว่า ขาเมื่อยจนแม้แต่เป้เปล่าก็หนัก นักเดินทางเอ๋ย ข้าขอความกรุณาอีกอย่าง ช่วยเอาของส่วนเกินขึ้นไปส่งที่ Summit ให้ Marn Euhron เขากำลังช่วยตั้งหลักกันใหม่ใกล้ Nordrassil\n\nเมื่อทำพิธีที่นี่เสร็จ ข้าจะค่อย ๆ ตามไป พอไปถึงจะรับของคืนจากเขาและช่วยพวกเขาทำงาน ด้วยวิธีนี้เราทั้งคู่จะได้ให้เกียรติการเดินทางและสิ่งที่ภูเขามอบให้" },
        objective = { "61:749016935:2117657226", "นำ Galvinquam's Belongings ไปให้ Marn Euhron ที่ยอดเขา" },
    },
    [91755] = { -- Leaves to Ligatures
        title = { "19:1581139420:1013041222", "ใบไม้ทำยาพอก" },
        description = { "285:2101758954:254277643", "เจ้าเห็นพุ่มไม้แปดเปื้อนที่เดินเพ่นพ่านในหุบเขานี้ไหม?\n\nต้นไม้พวกนั้นดุเอาเรื่อง แต่บางต้นก็ไม่ได้มีพิษไปทุกส่วน ใบของมันเอามาทำยาได้\n\nช่วยไปเอา Verdant Leaves มาให้ข้าหน่อยได้ไหม? แน่นอนว่าเจ้าต้องลงมือตัดแต่งกิ่งสักหน่อย" },
        objective = { "81:765890721:1345641803", "เก็บใบไม้เขียวสด 12 ใบจากพุ่มไม้แปดเปื้อนบริเวณเชิงเขา Mount Hyjal", amount = { "8:1089852795:1107240600 W1 71:817331594:337510757", "เก็บใบไม้เขียวสด {world1} ใบจากพุ่มไม้แปดเปื้อนบริเวณเชิงเขา Mount Hyjal" } },
    },
    [92009] = { -- Crate Expectations
        title = { "18:2076804946:1403010795", "ลังนี้ต้องระวัง" },
        description = { "497:1103480160:937825057", "มีเรื่องเกี่ยวกับของที่สั่งที่เจ้าควรรู้ ก้นลังมีเซลล์มานากลับขั้วอยู่สองสามชิ้น ข้ารองกันกระแทกไว้ดีที่สุดแล้ว เซลล์มักคายพลังเมื่อถูกกระแทกหรือไม่ปรับให้เสถียรทัน ของข้างในจะเสื่อมฤทธิ์ในราวสองชั่วโมง\n\nKaylaena รู้ว่าต้องทำอย่างไรเมื่อได้รับของ แต่ถ้าจะขี่สัตว์ขึ้น Mount Hyjal ข้าแนะนำให้ค่อย ๆ ไป\n\nถ้าต้องเติมใหม่ กลับมาหาข้า ข้าจะเติมกระบอกให้เต็ม ระวังตัวด้วยนะ" },
        objective = { "89:654936880:1467601143", "ขนลังอะไหล่กับของจุกจิกไปให้ Kaylaena Springwhisper ที่ Mount Hyjal อย่างระมัดระวัง" },
    },
    [95569] = { -- Hope for Hatchlings
        title = { "19:2126616903:266779208", "ความหวังของลูกนกฮูก" },
        description = { "466:1067651657:439269310", "พวกนกฮูกกำลังถูกคุกคามจากมลทินเฟลที่กัดกินลาดเขา และจากสัตว์ที่ถูกพลังนั้นทำให้เป็นพิษและคลุ้มคลั่ง นกฮูกหลายตัวทิ้งรังไปหาที่ปลอดภัยสูงขึ้นไป บางตัวตายขณะปกป้องลูก\n\nหากนกฮูกจะมีอนาคต เราต้องคุ้มครองไข่และเลี้ยงดูลูกนก นำไข่ที่ถูกทิ้งมาให้ข้า เจ้าคงพบได้ในรังร้างตรงโคนต้นไม้ทางเหนือและทางตะวันออกของที่นี่" },
        objective = { "52:2000251630:1637153424", "ช่วยไข่นกฮูก Hyjal (Hyjal Owl Egg) 12 ฟองให้พ้นอันตราย แล้วนำไปให้ Ketharas", amount = { "7:381738004:212593327 W1 43:1738541051:1923546587", "ช่วยไข่นกฮูก Hyjal (Hyjal Owl Egg) {world1} ฟองให้พ้นอันตราย แล้วนำไปให้ Ketharas" } },
    },
    [90647] = { -- The Staff of the Mountain
        title = { "25:926713853:1590123746", "คทาแห่งขุนเขา" },
        description = { "358:1538668030:2055429960", "ด้วยวัตถุดิบทั้งหมดที่เจ้ารวบรวม ข้าลงเวทใหม่ในคทาที่เจ้านำกลับมาได้แล้ว ตอนนี้เจ้าน่าจะใช้มันต้านเวทของเหล่าเทพแห่งพงไพรที่ Ve'han บังอาจขโมยไปได้\n\nแต่เราต้องลองทดสอบก่อน เอาคทานี้ไปให้ดรูอิด Tiala Whitemane ที่ Summit of Eternity นางอาจช่วยได้" },
        objective = { "77:1060172187:955728861", "นำคทาแห่งขุนเขาไปให้ Tiala Whitemane ที่ Summit of Eternity" },
    },
    [92014] = { -- Fox Hole
        title = { "8:1505969691:964581779", "โพรงจิ้งจอก" },
        description = { "485:529675340:427311956", "ทุกครั้งที่ข้าละสายตาจากเสบียงที่แบกขึ้นมานี่เกินสองสามนาที ยอดหัวขโมยตัวหนึ่งของธรรมชาติก็มารื้อค้นและขโมยของ\n\nดูเหมือนพวกจิ้งจอกตัวแสบจะขุดโพรงใต้ก้อนหินใหญ่แถวนี้ สงสัยเห็นข้าขุดหลุมแล้วได้ความคิดเอาไปทำตาม\n\nข้ากำลังหาทางแก้ เอางี้ เอาหางจิ้งจอกกลับมาให้ข้าสักหน่อย จะได้สั่งสอนมัน ข้าจะแขวนหางไว้รอบเขตให้ตัวที่เหลือกลัวจนไม่กล้าเข้ามา!" },
        objective = { "62:461048960:914379812", "นำ Rustleaf Fox Tail 9 ชิ้นกลับไปให้ Johun “Punchy” Dillas ใน Hyjal", amount = { "7:754587951:547508582 W1 54:1839628041:1020944824", "นำ Rustleaf Fox Tail {world1} ชิ้นกลับไปให้ Johun “Punchy” Dillas ใน Hyjal" } },
    },
    [92609] = { -- Feathers in Flight
        title = { "18:2112995787:934019286", "ขนปีกพาลูกธนูบิน" },
        description = { "308:1600949403:787009407", "เราพยายามออกไปหลายครั้งแล้ว แต่ต้องย้อนกลับมาปกป้องพี่น้องทุกที ของที่ใช้ป้องกันตัวร่อยหรอลง ถึงเวลาเก็บของเติมแล้ว\n\nวันนี้เราต้องการลูกธนู เยอะ ๆ เลย\n\nไปหานกตัวใหญ่สวย ๆ พวกนั้นแล้วเอาขนยาวของมันมาให้เรา จะได้ทำลูกธนูที่ยิงได้ตรง" },
        objective = { "40:1259533849:1960149911", "เก็บขนนกฮูก Hyjal (Hyjal Owl Feather) 9 เส้นให้ Zet'gan", amount = { "7:451016854:1830523975 W1 32:1902362336:1449908985", "เก็บขนนกฮูก Hyjal (Hyjal Owl Feather) {world1} เส้นให้ Zet'gan" } },
    },
    [93825] = { -- Barkbound Blessings
        title = { "19:376510707:617064257", "พรจากเปลือกไม้" },
        description = { "405:990973571:470205680", "เจ้าอยากเรียนรู้จากเราหรือ? ต้นไม้แห่ง Hyjal พูดกับเรา เปลือกไม้มีชีวิต มอสที่เราเรียกว่า Moonveil งอกอยู่บนเปลือก มันนุ่ม เขียว และเปี่ยมด้วยจิตวิญญาณของภูเขา เราใช้มอสนี้รักษาแผลและให้พรแก่รากไม้\n\nไปเถิด ผู้มีใจอ่อนโยน มองหาต้นไม้เก่าแก่ในที่ที่หมอกเกาะและแดดส่องไม่ถึง เก็บมอส Moonveil จากเปลือกมาให้ข้า เราจะใช้มันเยียวยาสิ่งที่ทำให้เราเจ็บปวด" },
        objective = { "62:875509861:584581853", "เก็บมอส Moonveil 12 กอ แล้วกลับไปหา Suma Mossmane", amount = { "7:451016854:1830523975 W1 53:858566421:2079625149", "เก็บมอส Moonveil {world1} กอ แล้วกลับไปหา Suma Mossmane" } },
    },
    [93826] = { -- Deal Dread to Deadwood
        title = { "22:2043171732:1777565417", "ให้ Deadwood ได้รู้จักความกลัว" },
        description = { "436:509809623:380209597", "พวก Deadwood ละทิ้งวิถีเก่า กรงเล็บมันฉีกต้นไม้ ใจลุกด้วยโทสะ มันโจมตีเรา พงไพรก็สั่นสะเทือน\n\nเจ้าที่เป็นมิตรของเฟอร์โบลก์ช่วยได้ ไปที่โพรงของมัน แสดงให้เห็นว่าพงไพรจะไม่ยอมก้มหัวให้ความโลภ ฆ่าพวกที่ทำให้รากไม้แปดเปื้อน แล้วกลับมาเมื่อเสียงร้องของมันเงียบจากหมู่ไม้ จัดการเหล่าปราชญ์ผู้ฉลาดแต่น่าเศร้าของมัน พวกนั้นใช้เฟลและบิดเถาวัลย์ให้แปดเปื้อน\n\nทำเช่นนี้แล้วเราจะเอ่ยชื่อเจ้าต่อเหล่าวิญญาณ" },
        objective = { "86:330362950:1729526639", "กำจัด Deadwood Totemic 8 ตัว และ Deadwood Fel-Tender 8 ตัว แล้วกลับไปหา Elder Pinespeaker", amount = { "7:1265997621:1189804897 W1 23:92400012:172991112 W2 54:23372215:1228028856", "กำจัด Deadwood Totemic {world1} ตัว และ Deadwood Fel-Tender {world2} ตัว แล้วกลับไปหา Elder Pinespeaker" } },
    },
    [95027] = { -- Feathers in Flight
        title = { "18:2112995787:934019286", "ขนปีกพาลูกธนูบิน" },
        description = { "424:135866282:1109694532", "เราต้องใช้ลูกธนูเพิ่มอยู่เสมอ ทั้งล่าสัตว์และสู้รบ ส่วนขนที่ใช้คือขนสีขาวของนกฮูก Hyjal มันฟูนุ่มตามธรรมชาติ แต่ข้ามีส่วนผสมที่ทำให้ขนแข็งพอดีสำหรับติดท้ายลูกธนู\n\nจะเก็บขนจากตัวนกก็ได้ หรือเก็บจากขนที่ร่วงในรัง ทางใต้ของที่นี่มีรังกระจายอยู่ทั่ว\n\nเอาขนมาฝากสักมัดนะ?" },
        objective = { "69:23194851:1456635441", "ลงใต้ไปยังหุบเขา แล้วเก็บขนนกฮูกจากรัง" },
    },
    [95316] = { -- The Experimental Method
        title = { "23:1183459272:1177776620", "วิธีทดลอง" },
        description = { "479:577717423:1518719338", "เอาละ เจ้าพวกเดินดิน คงสังเกตแล้วว่าลูกสนผสมเมือกเฟลน่าขยะแขยงมากในสายตาข้า แต่มันก็อันตรายมากด้วย นั่นแหละที่เราต้องการ!\n\nเอาลูกสนพวกนี้ไป ค่อย ๆ ไปที่ค่ายวอร์ล็อกใกล้ ๆ ข้าย้ำว่าค่อย ๆ ไป พอถึงแล้วก็ใช้มันทำลายโต๊ะทดลองสุดหวงของพวกนั้นให้วุ่นไปหมด\n\nข้าว่าเจ้าเห็นผลกับตาแล้วคงสนุกน่าดู! วิธีนี้จะถ่วงพวกมันได้แน่" },
        objective = { "58:1361570148:626060196", "ใช้ลูกสนทำลายจุดปฏิบัติงานของ Ashen Reign" },
    },
    [95317] = { -- Notation, Notation, Notation
        title = { "28:49829692:554191694", "จดไว้ จดไว้ จดไว้" },
        description = { "8:2102215530:680664386 C 475:1870377428:143211082", "ฟังนะ {class} ขึ้นไปบนเขานิดเดียวมีแขกส่งเสียงเอะอะ พวกนั้นทำให้ผืนดินแปดเปื้อนด้วยเวทปีศาจสกปรกและกำลังทดลองกับกองเถ้า ได้เวลาที่เราต้องไปสืบดูแล้ว\n\nที่ว่าเรา ข้าหมายถึงเจ้า\n\nข้าอยากให้เจ้าไปสอดส่องในค่าย! ลองเอาบันทึกที่บอกว่า «เพื่อน» เฟลลึกลับของเรากำลังทำอะไรมาฝากหน่อย พวกอวดดีขนาดนั้นต้องเขียนอะไรที่เอามาใช้ได้บ้าง อาจพกอะไรติดตัวอยู่ก็ได้" },
        objective = { "38:1012185200:857961477", "หาบันทึกการทดลองเถ้าเฟล 12 ฉบับ", amount = { "5:72389936:1525592206 W1 31:997526818:549721004", "หาบันทึกการทดลองเถ้าเฟล {world1} ฉบับ" } },
    },
    [95318] = { -- Taste of Ash
        title = { "12:1685610491:1507201189", "รสเถ้าถ่าน" },
        description = { "289:79604056:5724971 R 213:517881910:1239649916", "ถ้าจะทำให้งานที่นี่หยุดชะงักจริง ๆ และเอาข้าออกจากกรง เราต้องฆ่าผู้มีวันตายที่ทรงพลังมากสี่คน กรงมีอาคมปีศาจคุ้มอยู่ มันจะไม่คลายจนกว่าทั้งสี่จะตาย และต้องคลายอาคมก่อนถึงจะใช้กุญแจได้\n\nฟังนะ เจ้าดูเป็นชาว{race} ที่เอาตัวรอดได้ แต่ข้าขอให้พิสูจน์อีกหน่อยว่าเจ้ารับมือพวกวอร์ล็อกงี่เง่าได้จริง ก่อนข้าจะบอกอะไรที่มีประโยชน์\n\nเริ่มด้วยฆ่าวอร์ล็อกพวกนี้ให้เยอะ ๆ เป็นไง ง่ายใช่ไหม?" },
        objective = { "23:686587298:2047562350", "สังหารสาวกเถ้าถ่าน 12 คน", amount = { "5:1000000866:1065647852 W1 16:817327749:208105072", "สังหารสาวกเถ้าถ่าน {world1} คน" } },
    },
    [95319] = { -- Crystalline Collection
        title = { "22:344756372:711999651", "รวบรวมผลึก" },
        description = { "493:770156040:767199591", "ฟังนะ ข้ารู้ว่าเจ้าได้กลิ่นบ่อเลือดเฟลข้างหลังข้า และคงเห็นผลึกที่งอกขึ้นจากบ่อแล้ว ผลึกมีคุณสมบัติพิเศษจากเถ้าของ Archimonde ที่โปรยลงมาบนเขาด้านนี้\n\nอะไรบางอย่างในวิธีที่มันก่อตัวทำให้มันดูดพลังเฟลได้ดีเป็นพิเศษ นั่นเป็นปัญหาใหญ่สำหรับคนอย่างข้า แต่ผลึกก็ยังมีประโยชน์อยู่\n\nไปเก็บมาให้ข้าหน่อย ลองหามาหลาย ๆ แบบ ข้าเห็นแล้วจะรู้เองว่าต้องใช้แบบไหน" },
        objective = { "61:1031135532:30216751", "เก็บผลึกเมือกเฟล 8 ชิ้นและผลึกเมือกเฟลไร้ตำหนิ 1 ชิ้น", amount = { "7:451016854:1830523975 W1 24:574409986:1683979551 W2 28:1467765570:288159424", "เก็บผลึกเมือกเฟล {world1} ชิ้นและผลึกเมือกเฟลไร้ตำหนิ {world2} ชิ้น" } },
    },
    [95380] = { -- A Prolific Source
        title = { "17:1003527240:2078520046", "แหล่งเมือกชั้นดี" },
        description = { "13:994290110:763952584 C 478:1480218538:989878999", "ฟังทางนี้ {class} ดูเหมือนเราจะติดเรื่องเหนียวหนึบเข้าแล้ว ข้ารู้ว่าพวกนักเวทผู้ใช้พลังปีศาจนั่นคิดทำเรื่องชั่ว แต่เรื่องนี้แย่กว่าที่คิดไว้มาก\n\nยังดีที่ข้าคิดอะไรออก!\n\nงานนี้ต้องใช้เมือกเฟลจากพวกสัตว์เมือกในบ่อเลือดเฟลข้างหลังข้า เอาเฉพาะเมือก กระดูกหรือเศษอื่น ๆ ไม่ต้องเก็บ! เช็ดมือหลังจับด้วย ดูเหมือนมันจะกัดกร่อน\n\nไม่ต้องกลัว ข้ามั่นใจว่าเจ้าหาทางเอากลับมาให้ข้าได้" },
        objective = { "24:615452717:392204100", "เก็บเมือกเฟล 8 ก้อน", amount = { "7:451016854:1830523975 W1 16:989111548:242391807", "เก็บเมือกเฟล {world1} ก้อน" } },
    },
    [97001] = { -- Sawyer's Legacy
        title = { "15:655790577:259820112", "มรดกตระกูล Sawyer" },
        description = { "429:994157021:502928296", "ในตู้เสื้อผ้ามีสมุดบัญชีจดการค้าหญ้าแห้ง ไม้ สัตว์ใช้งาน และที่ดิน มีบันทึกส่วนตัวที่เขียนค้างสอดอยู่ระหว่างหน้า\n\nตัวเลขบอกเรื่องราวได้ด้วยตัวมันเอง ตระกูล Sawyer ชำนาญการแปรไม้เป็นทั้งอาวุธ เครื่องมือ เครื่องเรือน และเกวียน\n\nพอพลิกดูหน้าต่าง ๆ ก็พบชื่อญาติคนอื่น ในรายชื่อมี Abigail Sawyer อยู่ด้วย\n\nนางคงสนใจเรื่องนี้มาก" },
        objective = { "75:871538564:1953942583", "นำ Sawyer Family Ledger ไปให้ Abigail Sawyer ใน War Quarter ของ Undercity" },
    },
    [90702] = { -- Disturbed Grave
        title = { "15:420343213:1644774382", "หลุมศพถูกรื้อ" },
        description = { "222:1910326081:1061128686", "<ใครบางคนหรืออะไรบางอย่างคุ้ยดินจนเศษกระดูกกระจายไปทั่ว รอยยุบรูปร่างประหลาดทอดลึกลงไปในดินเย็นชื้น\n\nบางอย่างในบริเวณนี้อาจเป็นต้นเหตุ>" },
        objective = { "49:1387493980:1744221390", "ค้นบริเวณรอบ ๆ เพื่อหาสิ่งที่หายไปจากหลุมศพ" },
    },
    [90865] = { -- Eyes of the Watchers
        title = { "20:2047573270:134455292", "ดวงตาของผู้เฝ้าระวัง" },
        description = { "339:839128603:2088564454", "ขึ้นไปทางเหนือไม่ไกลมีซากจากการรบครั้งก่อน กำลังของ Scourge ที่เหลืออยู่กำลังร่อยหรอ\n\nพวกอันเดดไร้จิตใจก็เป็นภัยในตัวเองอยู่แล้ว พวกผู้เฝ้าระวังยังจับตามองทุกคนที่เข้ามา ทำให้กำจัดภัยจาก Scourge ได้ยากยิ่งขึ้น\n\nขจัดภัยนี้โดยชิงสิ่งที่ผู้เฝ้าระวังเหล่านั้นหวงที่สุดมา" },
        objective = { "38:877326312:113464195", "นำ Watcher's Eye 8 ดวงกลับไปให้ Eluneth", amount = { "9:1866698604:257786470 W1 28:386978272:467133438", "นำ Watcher's Eye {world1} ดวงกลับไปให้ Eluneth" } },
    },
    [91696] = { -- Open Season
        objective = { "80:2044688771:1323107194", "คุ้มกัน Barkskin Matriarch ออกจาก Deadwood Den แล้วกลับไปยัง Barkskin Burrow" },
        title = { "11:2112387263:1567128592", "เปิดฤดูล่า" },
        description = { "220:659367779:659592213", "Deadwood เล่นงานลูกข้ากับพ่อของมัน เขายืนหยัดสู้จนตายเพื่อคุ้มกันเรา เราต้องกลับบ้าน แต่ทางมืดและเต็มไปด้วยเขี้ยว\n\nอยู่ใกล้ ๆ คุ้มกันเราให้ดี ข้าจะนำทาง เจ้าคอยกันพวกมัน แล้วเราจะกลับถึงโพรงโดยปลอดภัย" },
    },
    [92011] = { -- Rubble Rummage
        title = { "14:1856828409:1049191487", "คุ้ยกองซาก" },
        description = { "495:439436704:1774775722", "ข้าต้องใช้เวลาคิดหน่อยว่าจะสร้างตามแบบไหนก่อน อีกเรื่องที่ตั้งใจจะทำคือเดินขึ้นไปที่ฐานเก่าของฮอร์ด ดูว่าขยะที่ทิ้งไว้แถวนั้นเอามาทำอะไรดี ๆ ได้บ้าง\n\nถ้าเจ้าจะขึ้นไปและยังมีที่ใส่ของ ช่วยสอดส่ายสายตาหาเศษโลหะ ลวด หรือก้อนขี้... ค้างคาว! ฟังก่อน มันมีประโยชน์นะ!\n\nซากค่ายฮอร์ดอยู่สูงขึ้นไปบนภูเขา เลยชุมชน Elderwild ไปอีก" },
        objective = { "118:1165251168:1795292926", "ค้นซากฐานฮอร์ด แล้วนำลวดเปื่อย 5 เส้น เศษโลหะ 5 ชิ้น และมูลสัตว์ที่แข็งเป็นหิน 5 ก้อนไปให้ Kaylaena", amount = { "50:330268696:322837727 W1 14:41421906:1015477557 W2 18:1174425431:1394189309 W3 33:696971179:2133647012", "ค้นซากฐานฮอร์ด แล้วนำลวดเปื่อย {world1} เส้น เศษโลหะ {world2} ชิ้น และมูลสัตว์ที่แข็งเป็นหิน {world3} ก้อนไปให้ Kaylaena" } },
    },
    [92101] = { -- Lifted by Legacy
        title = { "16:100672709:439041031", "กำลังใจจากร่องรอยเก่า" },
        description = { "494:1094476688:1307687903", "Hyjal เป็นที่ที่อยู่แล้วหนักใจ ฝันร้ายและความทรงจำถึงการเข่นฆ่ายังวนเวียนอยู่ในหลุมพวกนี้\n\nแต่เจ้าพกความอบอุ่นของ Kalimdor มาด้วย! Tobin เพื่อนข้าเข้ากองทัพมาด้วยกัน ข้ากลัวเหลือเกินว่าวิญญาณของเขาจะเป็นอย่างไร\n\nกองร้อยฝ่ายพันธมิตรให้ม้ากับพวกเรามาฝึกให้เชื่องและทำความคุ้นเคยก่อนออกประจำการ เราขี่เล่นกันผ่าน The Barrens แล้วสลักชื่อไว้ตรงฐานของ Great Lift ใน Thousand Needles\n\nช่วยดูหน่อยได้ไหมว่ารอยสลักยังอยู่หรือเปล่า วิญญาณที่อ่อนล้านี้จะได้สบายใจขึ้น" },
        objective = { "79:511510905:1547235335", "หารอยสลักบน Great Lift ที่มีความหมายต่อทหารผ่านศึกสงครามครั้งที่สาม" },
    },
    [92102] = { -- Praise
        title = { "6:1348363890:2005815664", "คำขอบคุณ" },
        description = { "85:1760622025:795067701 N 413:1710858666:1564332767", "เจ้าดั้นด้นไปไกลเพียงเพื่อทำตามความปรารถนาที่กำลังเลือนหายของวิญญาณหลงทาง ขอบใจนะ {name} เมื่อมีมือมาลูบรอยสลักและมีคนครุ่นคิดถึงมัน โดยรู้เรื่องราวเท่าที่เจ้ารู้มาจนถึงตอนนี้ ก็เพียงพอให้ข้ามาที่นี่ได้ ตอนนี้ข้าผูกอยู่กับสายสัมพันธ์ที่แน่นแฟ้นที่สุดกับผู้ยังมีชีวิต\n\nข้าไปถึงลานเกลือก่อน Tobin แต่พอลงสนามแข่ง เขาทิ้งข้าไม่เห็นฝุ่น\n\nข้าจำได้ชัดขึ้นแล้ว ไปพบข้าที่ Mourning's Rest ที่ที่เรารบครั้งสุดท้าย ข้างปืนใหญ่พังใกล้ซากหอคอยบนหน้าผา" },
        objective = { "123:547832773:1307842712", "ใช้ Embroidered Scabbard เพื่อพบ Veteran of the Third War ใกล้ปืนใหญ่ที่พังใน Mourning's Rest บน Mount Hyjal" },
    },
    [92147] = { -- Highfeather Helper
        title = { "18:395522601:979511318", "ผู้ช่วยเหล่า Highfeather" },
        description = { "381:1664799595:1189179304", "ข้าเป็นหนึ่งในเหล่า Highfeather ที่เหลืออยู่เพียงไม่กี่คน ผู้ติดตามที่แท้จริงของ Aviana เราเคารพและเทิดทูนมารดาแห่งฟากฟ้า และนับดรูอิดแห่งกรงเล็บเป็นพันธมิตร\n\nพวกฮาร์ปี Wormwing เข้ายึดที่ราบสูงนี้ไปมากแล้ว พวกมันปฏิเสธ Aviana ผู้คุ้มครองเรา และมุ่งแต่จะย่ำยีดินแดนรอบตัว\n\nเลือดหลั่งไปแล้วและต้องชดใช้ จงโปรยขนของพวกมันให้กระจายไปตามลม" },
        objective = { "87:372166398:1831406381", "สังหารฮาร์ปี Wormwing 18 ตัวบน Mount Hyjal แล้วนำขนของพวกมันไปให้ Phoebe Highfeather", amount = { "5:1000000866:1065647852 W1 80:122454593:1057694147", "สังหารฮาร์ปี Wormwing {world1} ตัวบน Mount Hyjal แล้วนำขนของพวกมันไปให้ Phoebe Highfeather" } },
    },
    [92449] = { -- Blight No More
        title = { "14:1089898872:1618783236", "ขจัดภัยให้พ้น" },
        description = { "484:1818575632:2039397647", "ตั้งแต่หนีรอดจากสงคราม เราดิ้นรนหาทางอยู่ให้ปลอดภัย ศัตรูล้อมทุกด้าน ภัยรุมเร้าไม่หยุด\n\nที่มั่นเก่าของเราทางตะวันออกเต็มไปด้วยอันเดด พวก Scourge เดินไปมาอย่างไร้จุดหมาย เป็นซากที่น่าเวทนาแต่ยังอันตราย พอไม่มีผู้บัญชาการ พวกมันก็หลงทาง... แต่ยังคร่าชีวิตได้\n\nเราพยายามกำจัดพวกมันแล้วแต่ยังไม่สำเร็จ อย่างน้อยถ้าเจ้าช่วย เราก็น่าจะผลักพวกมันออกไปให้พวกเราปลอดภัย... สักพัก" },
        objective = { "57:467251109:379560644", "กำจัดทหารที่ถูกลืม 3 นายและ Fleshflay Ravener 12 ตัว", amount = { "10:1223070807:902181099 W1 24:1505297700:407451765 W2 20:1083164469:198373251", "กำจัดทหารที่ถูกลืม {world1} นายและ Fleshflay Ravener {world2} ตัว" } },
    },
    [93510] = { -- Wake Memories
        title = { "13:556394466:1845430238", "ปลุกความทรงจำ" },
        description = { "504:2052773415:1467409469", "ยืนอยู่ใน Hyjal แล้วหนักใจนัก พวกพ้องหลายคนต้องจบชีวิตอย่างผิดธรรมชาติที่นี่ แม้แต่ผืนดินก็สะท้อนความโศกเศร้า หลุมเต็มไปด้วยเถ้า ความทรงจำขมขื่นเกินกว่าจะลืม\n\nแต่เจ้าพกประกายจาก Eastern Kingdoms มาด้วย เป็นไออุ่นที่สู้ความหม่นหมองนี้ได้! Tobin เพื่อนสมัยเด็กของข้าเข้ากองทัพพร้อมกัน ข้ายังมีหวัง แต่ก็กลัวว่าจะเหลืออะไรในวิญญาณเขาบ้าง\n\nตอนเด็กเราชอบใช้เวลาช่วงบ่ายขว้างหินให้กระดอนข้าม Lake Everstill ใน Redridge ช่วยหาสมอริมฝั่ง แล้วเล่นอย่างที่เราเคยเล่นเพื่อระลึกถึงเราหน่อยได้ไหม?" },
        objective = { "75:234412536:878485418", "หาสมอเรือที่ทะเลสาบ Everstill ซึ่งทหารผ่านศึกจำได้ตั้งแต่เด็ก" },
    },
    [93551] = { -- Praise
        title = { "6:1348363890:2005815664", "คำขอบคุณ" },
        description = { "74:1993869154:948018753 N 422:269230239:1979622049", "เจ้าอุตส่าห์เดินทางไกลเพื่อความปรารถนาที่กำลังเลือนหายของวิญญาณหลงทาง ขอบใจนะ {name} แค่เห็นอีกดวงวิญญาณอยู่ริมทะเลสาบ นึกถึงเพื่อนสองคนที่แข่งกันขว้างว่าใครได้ไกลกว่า ก็เพียงพอจะดึงข้ามาถึงขณะนี้ การคงอยู่ยึดกับสายสัมพันธ์ที่แน่นแฟ้นที่สุดกับผู้ยังมีชีวิต\n\nเราไม่เคยขว้างหินให้กระดอนถึงอีกฝั่งได้เลย...\n\n<วิญญาณทอดสายตามองข้ามทะเลสาบ>\n\nข้าจำได้แล้ว ไปพบข้าที่ Mourning's Rest ที่ที่เรารบครั้งสุดท้าย ข้างปืนใหญ่พังใกล้ซากหอคอยบนหน้าผา" },
        objective = { "123:547832773:1307842712", "ใช้ Embroidered Scabbard เพื่อพบ Veteran of the Third War ใกล้ปืนใหญ่ที่พังใน Mourning's Rest บน Mount Hyjal" },
    },
    [93827] = { -- Windswept Wards
        title = { "15:1175297624:1044427176", "เครื่องคุ้มกันกลางสายลม" },
        description = { "487:919500906:700640222", "ลมภูเขาหอบลางร้ายมา พวกฮาร์ปีทำรังสูงจนพวกเราขึ้นไปไม่ถึง อัญมณีที่มันสวมมีพลังแรง เมื่อผูกเข้ากับเครื่องรางของเรา มันจะคุ้มกันจากคำสาปและผูกวิญญาณไว้กับอาคมของเรา\n\nแต่ทางปีนขึ้นยาก ฮาร์ปีโจมตีด้วยกรงเล็บและพายุ ถ้าเจ้าเก่งอย่างที่เขาว่า จงไปยังโขดหินสูงที่ลมหวีดร้อง ถิ่นฮาร์ปีอยู่ช่วงกลางของ Hyjal เราเห็นมันบินเหนือหัวไปทางตะวันออกเฉียงเหนือ เอาเครื่องรางจากแม่มดฟ้าพวกนั้นมาให้ข้า" },
        objective = { "63:1473061252:900412422", "เก็บเครื่องรางฮาร์ปีลงมนตร์ 16 ชิ้น แล้วกลับไปหา Thobon Sapclaw", amount = { "8:1089852795:1107240600 W1 53:1970786859:59788036", "เก็บเครื่องรางฮาร์ปีลงมนตร์ {world1} ชิ้น แล้วกลับไปหา Thobon Sapclaw" } },
    },
    [95026] = { -- Blight No More
        title = { "14:1089898872:1618783236", "ขจัดภัยให้พ้น" },
        description = { "203:1944809460:2067284444", "หนีสงครามพ้นแล้วก็ใช่ว่าที่นี่จะปลอดภัย พวกตัวประหลาดทางตะวันออกก่อภัยให้แถวนี้มาตลอด\n\nบางทีเจ้าอาจพร้อมรับงานยาก ๆ แล้ว ว่าไง?\n\nจัดการพวกมันเลย ถึงยังไงก็ไม่มีใครคิดถึงมันหรอก" },
        objective = { "57:467251109:379560644", "กำจัด Forgotten Soldier 3 ตัว และ Fleshflay Ravener 12 ตัว", amount = { "10:1223070807:902181099 W1 24:1505297700:407451765 W2 20:1083164469:198373251", "กำจัด Forgotten Soldier {world1} ตัว และ Fleshflay Ravener {world2} ตัว" } },
    },
    [95378] = { -- The Hydra's Head
        title = { "16:125026481:1754823608", "ตัดหัวไฮดรา" },
        description = { "490:1896955722:1510692697", "ถึงเวลาตัดหัวไฮดราตัวนี้แล้ว ถ้าเจ้าเข้าใจว่าข้าหมายถึงอะไร\n\nต้องฆ่าหัวหน้าสามคนเพื่อถ่วงงานของพวกมันที่นี่ พอดีเลย ทั้งสามต้องตายถึงจะคลายอาคมที่กรงข้าได้ด้วย\n\nTyaeha อยู่ที่ House of Diseases ข้างต้นไม้น่าขนลุก Dazka อยู่ใน Alchemist Ward ที่มียาขวดเต็มไปหมด ส่วนเจ้าโง่ Frezzlie ต้องอยู่ข้างบ่อเมือกตามสันเขาทางเหนือของค่ายแน่\n\nไปฆ่าพวกมันแล้วเอากระดูกมาให้ข้า!" },
        objective = { "78:611586677:2065217574", "นำกระดูกของ Frezzlie Popwhiz, Tyaeha Darkoath และ Dazka Shadowsleep กลับมา" },
    },
    [95379] = { -- A Revenge So Sweet
        title = { "18:670414160:2007094366", "การล้างแค้นแสนหวาน" },
        description = { "479:877860591:2082517714", "Brashann Grimdark เจ้าแห่งภาชนะ\n\n<Felflick แยกเขี้ยวคำราม>\n\nมันคือคนที่จับข้ากดไว้ใต้อำนาจบนยอดเขา เพราะมันนั่นแหละข้าถึงต้องมาอยู่ที่นี่\n\nงานของมันกับผลึกเถ้าเฟลคือแกนของปฏิบัติการทั้งหมด มันหมกมุ่นกับการทดลองตรึงวิญญาณไว้ในผลึก พวก Blackthorne ตัวแสบก็จับตามองงานของมันอยู่\n\nใช้ผลึกไร้ตำหนินี้ดูดพลังของมัน จากนั้นจัดการมันแล้วเอาศิลาวิญญาณมาให้ข้า" },
        objective = { "61:338013197:748671867", "สังหาร Brashann Grimdark แล้วค้นร่างของเขาเพื่อหาศิลาวิญญาณ" },
    },
    [96077] = { -- Belle's Ring
        title = { "12:990893598:900908453", "แหวนของ Belle" },
        description = { "433:2114341884:1233474469", "ใช่ Thomas Belle\n\n<ท่าทีของ Daythor เปลี่ยนไปทันที ราวกับนึกถึงความทรงจำดี ๆ เกี่ยวกับเขา>\n\nThomas เป็นคนกลุ่มแรกที่ล้มลงตอน Scourge ล้อมด่านของเรา ข้าไม่รู้ว่าเขาตายจนกระทั่งศึกจบแล้ว น่าเศร้า... เขาเป็นหนุ่มที่มีอนาคตแท้ ๆ\n\nข้าว่าควรเอาของนี้ไปให้ Michelle คนรักของเขา ถ้าข้าจำไม่ผิด เขาพูดถึง Goldshire อยู่บ่อย ๆ" },
        objective = { "76:2011909431:1460258763", "นำแหวนไปให้ Michelle Belle ที่ Lion's Pride Inn ใน Elwynn Forest" },
    },
    [96999] = { -- Wrap Return
        title = { "11:945924408:705137463", "คืนห่อหนังให้เจ้าของ" },
        description = { "323:765223244:532636990", "ใครที่สวมของนี้คงสู้ด้วยใจมุ่งมั่น แล้ว Sen'jin ก็เป็นหมู่บ้านเล็ก ๆ คนที่นั่นรู้จักญาติพี่น้องกันดี\n\nที่บ้านต้องมีใครคิดถึงห่อหนังนี้ และคิดถึงนักรบที่พกมัน\n\nเมื่อเจ้าเดินทางไป Echo Isles เอาห่อหนังนี้ไปด้วย นำกลับบ้านที่ Sen'jin พวกเขาจะรู้ว่าเป็นของใคร และจะให้เกียรติเจ้าที่อุตส่าห์นำกลับมาคืน" },
        objective = { "54:474964060:981464213", "นำห่อสีทาหน้าสำหรับออกรบ (War Paint Wrap) ไปให้ใครสักคนใน Sen'jin Village" },
    },
    [92591] = { -- Final Death
        title = { "11:405848493:51641794", "ความตายครั้งสุดท้าย" },
        description = { "474:2108442514:1126230730", "เราพยายามหนีลงจากภูเขาแล้ว แต่ Scourge ขัดขวางเราทุกครั้ง มีลิชทรงพลังปลุกซากพวกที่เราทำลายแล้วส่งกลับมาเล่นงานเราอีก ตราบใดที่ลิชยังอยู่ เราก็ไม่มีวันปลอดภัย\n\nลิชใช้กระดูกจากกองหนึ่งมาประกอบร่างโครงกระดูก เอาคบเพลิงนี้ไปจุดไฟเผากองกระดูกในซากปรักหักพัง มันต้องออกมาตอบโต้แน่\n\nนำเครื่องรางของมันมาให้ข้า เราจะได้ทำลายเครื่องรางและกำจัดลิชให้สิ้นซาก" },
        objective = { "80:1502226872:817470208", "ใช้คบเพลิงของผู้รอดชีวิตกับกองกระดูก แล้วเก็บเครื่องรางของผู้ปลุกศพ" },
    },
    [92592] = { -- Final Death
        title = { "11:405848493:51641794", "ความตายครั้งสุดท้าย" },
        description = { "406:2024943820:84008226", "เราพยายามลงจากเขา แต่พวก Scourge ขวางทุกที ลิชตัวเก่งปลุกซากพวกที่เราจัดการไปแล้ว ส่งมันกลับมาเล่นงานเราอีก เพราะเจ้าลิชนี่แหละเราถึงชนะไม่ได้!\n\nลิชมีกองกระดูกไว้ประกอบพวกโครงกระดูกขึ้นใหม่ เอาคบเพลิงไปที่ซากปรักหักพังแล้วเผากองกระดูกนั่น มันต้องโผล่มาแน่\n\nเอาเครื่องรางมันมาให้ข้า เราจะทำลายเครื่องรางแล้วกำจัดมันให้จบเรื่อง!" },
        objective = { "80:1502226872:817470208", "ใช้คบเพลิงของผู้รอดชีวิตกับกองกระดูก แล้วเก็บเครื่องรางของผู้ปลุกศพ" },
    },
    [92960] = { -- Siphoned Ephemeral Essence
        title = { "26:1052508280:1955396958", "แก่นพลังชั่ววูบที่ถูกดูดไป" },
        description = { "318:2061492504:848271172", "ยังมีปีศาจตกค้างทางตะวันออก ในหมู่พวกมันมีสัตว์นรกที่ทำร้ายคนของเราและดูดพลังไปใช้เล่นงานพันธมิตรของเรา\n\nบุกเข้าไปในค่าย ตามหาสัตว์ร้ายพวกนั้นแล้วสังหาร เก็บตัวอย่างที่ยังเหลือกลับมา\n\nบางทีเราอาจเรียนรู้อะไรจากงานนี้ได้" },
        objective = { "53:1927140483:1695574043", "นำแก่นพลังชั่วครู่ 6 ชิ้นไปให้ Elaena Moonwhisper", amount = { "9:1866698604:257786470 W1 43:789239478:1770287331", "นำแก่นพลังชั่วครู่ {world1} ชิ้นไปให้ Elaena Moonwhisper" } },
    },
    [95273] = { -- Water of Hyjal
        objective = { "109:426029704:1247731725", "เท Barkskin Purification Tonic ที่ Fennar Mossmane ให้มาลงในน้ำที่ก้นโพรง Deadwood Den" },
        title = { "14:1276011171:900236708", "น้ำแห่ง Hyjal" },
        description = { "350:726973859:450464331", "ตอนนี้เรารู้แล้วว่าการอยู่ของ Deadwood ไม่ได้ทำให้น้ำเสียโดยตรง เราจึงใช้ตัวอย่างนี้ลงอาคมด้วยจิตใจที่มั่นคงได้ ได้ยินมาว่าในโพรงพวกมันมีแอ่งน้ำตาของภูเขาอยู่\n\nฝ่าเข้าไปแล้วเทน้ำนี้ลงในแอ่งลึกเข้าไปใน Deadwood Den\n\nเมื่อรู้ว่าความมืดเบื้องล่างเก็บความลับอะไรไว้ ก็กลับมาหาเรา" },
    },
    [95793] = { -- Stemming the Demon Tide
        title = { "23:2096132294:1362152870", "หยุดคลื่นปีศาจ" },
        description = { "6:1537380568:68647516 C 360:934808387:2087029675", "อา {class} ข้าเห็นทั้งกำลังและความมุ่งมั่นในตัวเจ้า คุณสมบัติที่ต้องมีเพื่อขจัดความชั่วร้ายจากผืนดินนี้\n\nปีศาจที่เดินอยู่บนแผ่นดินนี้ในมหาศึกครั้งนั้นพ่ายแพ้ไปแล้ว แต่ยังเหลืออยู่บางส่วน เราต้องกันไม่ให้มันหนีไปได้\n\nซากปรักหักพังทางตะวันออกอันตรายนัก จงนำกำลังของเจ้าเข้าไปในรังมัน กำจัดผู้บุกรุกก่อนแผ่นดินเราจะพินาศ" },
        objective = { "38:1264579931:1331257803", "สังหารทหารยามเฟลการ์ด 12 ตนใน Dae'gun", amount = { "5:1000000866:1065647852 W1 31:324064037:1503807921", "สังหารทหารยามเฟลการ์ด {world1} ตนใน Dae'gun" } },
    },
    [96529] = { -- A Shaw Deal
        title = { "11:235356300:1766351621", "ข้อตกลงกับ Shaw" },
        description = { "298:1043821961:1299366912", "ความช่วยเหลือของเจ้าสำคัญต่อการสอดแนมของเรามาก นำข่าวกรองนี้ไปให้ Master Mathias Shaw ที่ Stormwind\n\nจำไว้ ห้ามบอกใครเรื่องงานของเราที่นี่ เรื่องที่ข้าอยู่ที่นี่ หรือว่า SI:7 มีส่วนเกี่ยวข้อง ข้ายังมีงานอีกมากต้องเตรียม และต้องคอยให้แผนเดินต่อไปตามกำหนด\n\nแล้วเราจะติดต่อไป" },
        objective = { "70:1355393656:969851588", "นำ Blackthorne Information ไปให้ Master Mathias Shaw ใน Stormwind" },
    },
    [97009] = { -- Maerion's Misery
        title = { "16:1112943724:1967317908", "ความทุกข์ของ Maerion" },
        description = { "475:997878439:1042926167", "ข้าถูกทิ้งให้เลือดไหล ถูกโยนทิ้งเพื่อให้กองทัพหนี ข้าควรตายเพื่อซื้อเวลาให้พวกเขาอีกชั่วอึดใจ\n\nแต่กลับต้องคำสาปให้ทนอยู่ ถูกบังคับให้มองปีศาจที่ลุกไหม้ไม่รู้ดับทำสิ่งที่คมเหล็กทำไม่สำเร็จให้เสร็จสิ้น นี่คือชะตาของข้า\n\nแต่บางอย่างกำลังเปลี่ยนไป ฮอร์ดกับพันธมิตรกลับมายังภูเขาที่ถูกย่ำยี สงครามเริ่มขยับตัวอีกครั้ง\n\nโทสะของข้าตอบรับมัน\n\nถ้าโทสะเจ้าตอบรับเช่นกัน ก็พิสูจน์ให้เห็น เอาหนามหมาเฟลจากพวก Defiling Hound มาให้ข้าสองกำมือ\n\nความเจ็บปวดจะทำให้เรามีเจตจำนงเดียวกัน" },
        objective = { "60:501936808:539860619", "นำหนามเฟลฮาวด์ 12 ชิ้นไปให้ Maerion Thaelemaches ที่ Dae'gun", amount = { "6:1273960851:929420321 W1 52:1631233865:352917737", "นำหนามเฟลฮาวด์ {world1} ชิ้นไปให้ Maerion Thaelemaches ที่ Dae'gun" } },
    },
    [92959] = { -- The Dying Ancients
        title = { "18:1046330842:348551138", "เหล่า Ancient ที่กำลังสิ้นลม" },
        description = { "486:409137007:1176982905", "มลทินนี้... ซึมเข้ากิ่งก้าน เข้ารากของข้า ข้าไม่ได้เป็นเพียงตนเดียว เหล่า Ancient ตนอื่น... ก็สัมผัสถึงมลทินนี้เช่นกัน\n\nเพื่อนเก่าแก่ที่สุดคนหนึ่งของข้า... Sunderbark... มลทินทำลายเขาแล้ว เหลือเพียงสิ่งมีชีวิตที่เต็มไปด้วยโทสะและความเจ็บปวด ตอนนี้... สายเกินจะช่วยเขาแล้ว\n\nไปยังแอ่งที่แปดเปื้อนทางตะวันออก... โจมตีต้นไม้ที่แปดเปื้อน แล้วเขาจะมา\n\nเอาเมล็ดนี้ไป... เมื่อจบเรื่องแล้ว จงปลูกลงในซากของเขา หากดูแลให้ดี... สิ่งดี ๆ ยังงอกจากความเศร้านี้ได้" },
        objective = { "89:481473033:1934993997", "ตามล่าและทำลาย Sunderbark ผู้พิทักษ์โบราณที่ถูกความเสื่อมทรามครอบงำ แล้วปลูกเมล็ดลงในซากของเขา" },
    },
    [91923] = { -- Celastrus the Bitter
        title = { "20:1731721870:335886607", "Celastrus ผู้ขมขื่น" },
        description = { "403:418552031:1679345007", "พืชขึ้นรกไปทั่วภูเขา พลังเฟลที่โปรยลงมาเมื่อนานมาแล้วทำให้พวกมันคลุ้มคลั่ง ตอนนี้ทั้งวัชพืชและต้นไม้เกรี้ยวกราด แปดเปื้อนและอาบพิษ\n\nมีพุ่มหนามใหญ่ชื่อ Celastrus ซุ่มอยู่ตามลาดเขาด้านตะวันออก มันฆ่าสัตว์ ฟาดใส่ต้นไม้อื่น และกินร่างสิ่งที่ตายแล้ว ต้องทำลายมัน!\n\nต้องกำจัดวัชพืชให้หมดเพื่อให้พืชบนภูเขากลับมาเติบโตได้" },
        objective = { "83:1348837222:1581936366", "ตามหาและทำลาย Celastrus the Bitter แล้วนำใบที่หักของมันกลับไปให้ Thylaen" },
    },
    [96255] = { -- Amalgamated Marrow
        title = { "18:1854818790:994341665", "ไขกระดูกที่หลอมรวม" },
        description = { "111:1226482867:888313286", "<บางอย่างดิ้นอยู่ในกองกระดูกอย่างน่าหวั่นใจ ขณะที่เมือกสีเขียวซึมออกจากใต้กระดูกที่เพิ่งใส่เพิ่ม>" },
        objective = { "32:927754541:170642179", "สังหาร Awakened Fel Ash Slime" },
    },
    [96322] = { -- A Revenge Now Bitter
        title = { "20:1668334556:1308311812", "การล้างแค้นที่กลับขมขื่น" },
        description = { "396:1875270106:125350998", "รู้ไหม สำหรับผู้มีวันตาย ข้าทึ่งที่เจ้าทำตามคำสั่งง่ายขนาดนี้\n\nเจ้าเดินเข้าไปฆ่าคนพวกนั้นหมดโดยไม่กะพริบตาเลย!\n\nอา... แต่ตอนนี้ถึงตาเจ้าทำตามข้อตกลงแล้ว «เพื่อน» ข้าช่วยเจ้ารื้อกลุ่ม Ashen Reign งี่เง่า จัดการผู้นำและทำให้งานของพวกมันที่นี่เป็นอัมพาตแล้ว\n\nข้าว่าข้าสมควรได้อิสระแล้วละ\n\n<ตาของ Felflick เป็นประกายอย่างตั้งตารอ>" },
        objective = { "18:2092728138:1957674654", "ไปคุยกับ Felflick" },
    },
    [91794] = { -- Flags of Our Forebears
        title = { "22:1877246547:1395562855", "ธงของบรรพชน" },
        description = { "484:1688113168:1983089954", "เราติดอยู่บนนี้มาหลายปี สู้กับพวก Scourge ตลอด แต่เราไม่เคยสิ้นหวัง เราสู้เพื่ออยู่รอด เราสู้เพื่อฮอร์ด พันธมิตรก็สู้ศึกนี้กับเรา แต่เราไม่เคยลืมเรื่องที่ผ่านมาระหว่างกัน และเลือดที่เสียไป\n\nไกลออกไปทางตะวันออก ที่ Dae'gun มีธงฮอร์ดจากสงคราม ปีศาจเก็บเศษธงกับซากของไว้เป็นของที่ชิงได้ โดยเฉพาะพวกตัวเก่ง เอาธงกับตราประจำทัพมาให้ข้า ข้าจะได้ชูให้พันธมิตรเห็นว่าฮอร์ดยังแข็งแกร่ง!" },
        objective = { "80:663292826:584174082", "เก็บธงฮอร์ด 1 ผืนและเศษตราสัญลักษณ์ฮอร์ด 3 ชิ้นไปให้ Kal'tinzan ที่ Elderwild", amount = { "8:1089852795:1107240600 W1 16:549303383:252963458 W2 54:1543158932:1352209388", "เก็บธงฮอร์ด {world1} ผืนและเศษตราสัญลักษณ์ฮอร์ด {world2} ชิ้นไปให้ Kal'tinzan ที่ Elderwild" } },
    },
    [92169] = { -- Paying Back the Pact
        title = { "20:1976123697:1248274059", "เอาคืน Blackthorne Pact" },
        description = { "490:1738151236:882833227", "Blackthorne Pact นั่นคือชื่อที่พวกมันใช้เรียกตัวเอง พวกดรูอิดที่ละทิ้งคำสาบานและยึด Hyjal Summit ไว้ ทั้งรุนแรงและสุดโต่ง พวกมันโทษ Malfurion Stormrage ว่าพรากความเป็นอมตะไป และสาบานจะทวงพลังที่ถูกบังคับให้สละคืน เมื่อก่อนข้าไม่เข้าใจเวทที่เสริมพลังให้พวกมัน ตอนนี้เริ่มเห็นชัดแล้ว\n\nเอาคทาไปใช้กับดรูอิด Blackthorne รอบภูเขา คทาน่าจะตอบสนองต่ออาคมคุ้มกันของพวกมันและสลายอาคมได้" },
        objective = { "135:1428753507:2132957910", "ใช้คทาแห่งขุนเขากับสมาชิก Blackthorne Pact 10 คนที่ Summit of Eternity เพื่อสลายมนตร์คุ้มกัน แล้วจึงสังหารพวกมัน", amount = { "33:1086693682:376932133 W1 100:522409538:1080978592", "ใช้คทาแห่งขุนเขากับสมาชิก Blackthorne Pact {world1} คนที่ Summit of Eternity เพื่อสลายมนตร์คุ้มกัน แล้วจึงสังหารพวกมัน" } },
    },
    [96676] = { -- Unsealing Blackthorne Pact
        title = { "26:992042733:1782768851", "เปิดทางฝ่า Blackthorne Pact" },
        description = { "281:35072145:480266656 N 31:1747539935:1895182287", "เอาละ สายข่าว เจ้าได้เลื่อนขั้นแล้ว\n\nนำคำสั่งฉบับปรับปรุงไปให้ Johun ที่ค่ายฐานของเขาใน Hyjal ในนั้นมีอุปกรณ์เพิ่มเติมที่เขาต้องใช้ในปฏิบัติการบนยอดเขา\n\nความช่วยเหลือของเจ้าในเรื่องนี้สำคัญต่อยุทธศาสตร์โดยรวมของเราใน Kalimdor มาก {name} อย่าชักช้า\n\nไปได้" },
        objective = { "63:1567228573:1742165407", "นำ Alliance Equipment ไปให้ Johun “Punchy” Dillas ใน Hyjal" },
    },
    [92545] = { -- Ravenlock's Quest
        title = { "17:1267072838:727676601", "ภารกิจของ Ravenlock" },
        description = { "35:1597950854:276579098 N 438:262601614:1035530423", "เจ้าทำหน้าที่ของเจ้าได้ดี {name}\n\nข้ามีภารกิจของข้าเอง ที่นี่มีพลังอย่างหนึ่งที่มีต้นกำเนิดจากปีศาจ ความชั่วร้ายจากต่างภพนี้แทรกซึมภูเขามาช้านาน ข้าเห็นอิทธิพลที่ทำให้แปดเปื้อนของมันยื่นออกมาเหมือนหนวดดำที่ละโมบ เมื่อความชั่วร้ายนี้หลับ มันฝัน และความฝันของมันทำให้ผู้ที่สัมผัสมลทินเสียสติ\n\nมาเถิด เข้ามาใกล้ไฟกับข้า เราจะรู้ชื่อของสัตว์ร้ายตนนี้ และเมื่อรู้ชื่อก็จะได้หนทางทำลายมัน" },
    },
    [96351] = { -- Skill Issue
        title = { "11:49233153:1035552006", "เรื่องฝีมือ" },
        description = { "495:138846896:1544135741", "เจ้าได้คุยกับ Aisarra หรือยัง? ถ้าคุยแล้ว ข้าเดาว่าคงมีฝ่ายเดียวที่พูด นางฝึกมาให้เก็บความลับ จึงถนัดยืนเฝ้ามากกว่าพูดคุยตามมารยาท\n\nนางตามหาคนที่เชี่ยวชาญงานช่างหลายแขนง และมีคนเอ่ยชื่อเจ้าว่าเป็นคนที่นางหวังจะรับมาสอน\n\nเสียดายที่ข้าคิดว่าฝีมือเจ้ายังไม่ถึงมาตรฐานของนาง แต่ถ้าฝึกอีกสักหน่อย ข้าว่าพวกเจ้าคงเข้ากันได้" },
    },
    [96366] = { -- Honorable Mentions
        title = { "18:1472581603:2105627787", "คู่ควรแก่คำชม" },
        description = { "462:1021421197:66636648", "เจ้ายังพิสูจน์ให้เห็นว่าเป็นพันธมิตรที่คู่ควรของ Hyjal\n\nข้าอยากแบ่งความรู้ให้เจ้าอีก คราวนี้ข้าว่าเจ้ามีสิทธิ์เลือกทางของตัวเองแล้ว จากแบบที่เหลือที่ข้ายินดีแบ่งในงานนี้ เลือกเชี่ยวชาญได้หนึ่งอย่างระหว่างเกราะไหล่ ถุงมือ หรือรองเท้าบูต เช่นเคย ข้าจะให้แบบที่เจ้าเลือกฟรีหนึ่งแบบ\n\nเกราะชนิดใดที่เจ้ายังไม่เลือกวันนี้ ข้าอาจยังยินดีสอนในภายหลัง" },
    },
    [96367] = { -- A Crafter's Reverence
        title = { "21:377972132:1882833095", "การคารวะนายช่าง" },
        description = { "442:517855031:726862684", "นายช่างผู้เชี่ยวชาญกลับมาแล้ว ข้ายินดีต้อนรับ\n\nป่านนี้เจ้าคงจำข้อตกลงของเราได้โดยไม่ต้องเตือน แต่ข้าจะทวนให้อีกครั้ง จากตัวเลือกที่ยังเหลือ เจ้าฝึกเจาะจงเกราะเพิ่มได้อีกหนึ่งชนิด ข้าจะให้สูตรในชุดของข้าฟรีอีกหนึ่งสูตรด้วย\n\nส่วนอุปกรณ์ชนิดสุดท้ายที่เราข้ามวันนี้ เจ้าจะเรียนได้หลังจากมีชัยชนะเพิ่มขึ้นอีก" },
    },
    [92612] = { -- Aid from Moonglade
        title = { "18:906158119:1823298968", "ขอความช่วยเหลือจาก Moonglade" },
        description = { "424:759748653:518975158", "<Ketharas รับกิ่งไม้มาตรวจดู เขาเริ่มกระซิบมนตร์ดรูอิด กิ่งไม้ก็เรืองแสงจ้าขึ้น ผลึกสีเขียวหม่นตอบสนองด้วย ราวกับกำลังดูดแสงรอบตัวเข้าไป>\n\nน่าเสียดายที่ข้าไขความลับในกิ่งไม้นี้ไม่ไหว แต่ข้าสัมผัสได้ถึง... อะไรบางอย่าง\n\nนำกิ่งไม้ไปยังเมือง Nighthaven ใน Moonglade แล้วขอความช่วยเหลือจาก Dendrite Starblaze" },
        objective = { "98:856369024:1915501431", "เดินทางไป Nighthaven ใน Moonglade แล้วขอความช่วยเหลือจาก Dendrite Starblaze ในนามของ Ketharas" },
    },
    [95006] = { -- Stolen Power
        title = { "12:1146126809:2107649847", "พลังที่ถูกขโมย" },
        description = { "237:2005154774:1353223362", "<Orokai หลับตาและหยุดนิ่งขณะสื่อสารกับกิ่งไม้ ระหว่างนั้นเจ้ารู้สึกถึงมนตร์ที่แผ่มาจนผิวหนังยิบ ๆ>\n\nโอ้ ผู้มีวันตายตัวน้อย กิ่งไม้นี้มีเรื่องให้เล่ามากนัก...\n\nมาเถิด ข้าจะให้เจ้าดู" },
        objective = { "92:1483959998:1597794782", "เมื่อพร้อมจะฟังว่า Orokai รู้อะไรจากกิ่งไม้เรืองแสงจาง ๆ (Faintly Glowing Branch) ให้คุยกับเขา" },
    },
    [96209] = { -- The Ancient, Orokai
        title = { "19:1177541805:1915872206", "Orokai แห่งเหล่า Ancient" },
        description = { "327:447474741:1751150204", "Orokai หนึ่งในเหล่า Ancient ยืนเฝ้าอยู่นอกเมือง นำสิ่งนี้ไปให้เขา เหล่า Ancient ทั้งน่าอัศจรรย์และเปี่ยมปัญญา ถ้ากิ่งนี้ไม่ได้แยกจากต้นแม่นานเกินไป เขาจะ «คุย» กับมันได้และรู้ว่ามันมีเรื่องอะไรจะเล่า\n\nเจ้าจะพบ Orokai ทางตะวันตกเฉียงใต้ของเมือง อยู่ไม่ไกลนัก" },
        objective = { "29:896065914:1435161895", "ไปหา Orokai ใน Moonglade" },
    },
    [92859] = { -- Shroud of the Winter Wilds
        title = { "26:72209165:930436015", "พรางตัวในพงไพรเหมันต์" },
        description = { "427:1914307695:1443742116", "ผู้คนพยายามเข้า Mount Hyjal กันตั้งแต่สงครามจบ แต่มีปัญหาใหญ่อย่างหนึ่ง... ปีศาจเต็ม Darkwhisper Gorge ไปหมด!\n\nข้าคิดว่ามีทางแก้ ยาที่ผสมจากวัตถุดิบแถวนี้อาจทำให้คนดื่มกลมกลืนไปกับสภาพแวดล้อมของ Winterspring พวกสัตว์ที่นี่จะได้มองเห็นเจ้ายากขึ้น\n\nข้าอยากลองดูว่าที่คิดไว้จริงไหม ถ้าเจ้าพร้อมช่วยหาของเล็ก ๆ น้อย ๆ มาให้ข้า!" },
        objective = { "84:753648464:539790527", "นำขนไคมีราแห่ง Winterspring 5 ชิ้นและขนนกฮูกแห่ง Winterspring 5 ขนไปให้ Evie Whirlbrew", amount = { "6:1273960851:929420321 W1 31:265937012:1456749158 W2 45:1695960425:400809076", "นำขนไคมีราแห่ง Winterspring {world1} ชิ้นและขนนกฮูกแห่ง Winterspring {world2} ขนไปให้ Evie Whirlbrew" } },
    },
    [95570] = { -- Cleansing the Corruption
        title = { "24:721269449:1436289085", "ชำระมลทิน" },
        description = { "28:1427688165:199476475 N 133:1527634603:978756818", "เจ้าช่วยข้าไว้มากทีเดียว {name} ด้วยแรงของเจ้า มลทินจะแพร่ไปได้เร็วขึ้นอีกมาก\n\nน่าเสียดาย นี่เป็นครั้งสุดท้ายที่ข้าต้องใช้เจ้า" },
    },
    [96265] = { -- Secret of the Barrow Deeps
        objective = { "65:56640548:232448174", "นำ Corrupted Gemstone ไปให้ Thera Duskwhisper ที่ Winterspring" },
        title = { "26:1043792466:211466175", "ความลับแห่ง Barrow Deeps" },
        description = { "106:840624098:1463711828", "<เศษผลึกแปดเปื้อนรวมเป็นอัญมณีที่เดือดพล่านด้วยพลังมลทิน เหล่า Watcher ต้องอยากเห็นสิ่งนี้>" },
    },
    [96266] = { -- Secret of the Barrow Deeps
        title = { "26:1043792466:211466175", "ความลับแห่ง Barrow Deeps" },
        description = { "498:14249839:1323453984", "ถ้าเข้าเรือนจำได้โดยตรง ข้าคงลงไปอยู่ข้างล่างแล้ว แต่มลทินบิดเบือนอาคมคุ้มกันโบราณของเราจนปิดทางเข้า\n\nถ้าเจ้าทุ่มเทให้เรื่องของเราจริง ช่วยข้าใช้อัญมณีนี้เล่นงานศัตรูที เมื่อปรับเวทแปดเปื้อนของมันให้สอดคล้องกับพลังของพี่น้องหญิงที่ตกสู่ความมืด เราก็ใช้มันสร้างกุญแจเปิดทางสู่ส่วนลึกข้างใต้ได้\n\nข้าต้องใช้วัตถุดิบสักหน่อยก่อน Nelanna อาจยอมให้ลวดลายโลหะฉลุแก่คนที่พิสูจน์แล้วว่าเป็นพันธมิตร ส่วนที่เหลือเจ้าต้องจัดหาเอง" },
    },
    [97235] = { -- A Ring of Gems
        title = { "14:1238809854:486719410", "แหวนประดับอัญมณี" },
        description = { "N 482:1546818506:726325752", "{name} ขอเวลาสักครู่ได้ไหม?\n\nข้าได้ยินคนอื่นชื่นชมสิ่งที่เจ้าทำใน Barrow Deeps พอดีข้าเพิ่งได้รับมอบหมายให้ทำแหวนเสริมพลังให้พวกเรา ข้าอยากให้เจ้าได้เลือกแหวนที่ข้าทำก่อนใคร ข้ามีอัญมณีที่ต้องใช้แล้ว แต่หากขาดโลหะลงมนตร์ แหวนก็ใช้ประโยชน์ไม่ได้\n\nEnchanted Thorium Bar ใช้กับงานนี้ได้ ข้ากับเหล่า Watcher จะขอบใจมากถ้าเจ้าหามาให้เราได้" },
    },
    [97252] = { -- Secret of the Barrow Deeps
        title = { "26:1043792466:211466175", "ความลับแห่ง Barrow Deeps" },
        description = { "122:1241015064:1087232457 N 86:743713951:1324236490", "เสร็จแล้ว ด้วยสิ่งนี้เราจะเข้าเรือนจำ Vord'anaar และจัดการพี่น้องหญิงที่ตกสู่ความมืดได้\n\nอย่าได้สงสารพวกนางเลย {name} พวกนางตายไปตั้งแต่วินาทีที่มลทินเข้ายึดหัวใจแล้ว\n\nAshal thera'das!" },
    },
    [97264] = { -- Shardtooth Pulling
        title = { "18:1043245642:466663194", "ถอนเขี้ยว Shardtooth" },
        description = { "412:1110988979:2061961961", "พวก Shardtooth ดุร้ายขึ้นทุกฤดู พวกมันแย่งอาหารที่มีอยู่น้อยนิดทั้งกับพวกเดียวกันและกับสัตว์นักล่าในป่า\n\nพวกมันโจมตีเราบ่อยขึ้น ความหิวกลางอากาศหนาวจัดยิ่งทำให้มันก้าวร้าว\n\nหมีมีจำนวนมากและใจสู้ ถ้าลดจำนวนลง ครอบครัวที่เหลือจะยิ่งแข็งแกร่งขึ้นกว่าเดิม\n\nช่วยให้พวกมันอยู่รอดต่อไป คัดตัวที่แก่ที่สุดออก" },
        objective = { "77:1465955137:1071057078", "กำจัดหมี Shardtooth แก่ 12 ตัวในบริเวณใกล้เคียง แล้วกลับไปหา Sarna Brownhorn", amount = { "7:180480527:620071683 W1 68:628232801:615756687", "กำจัดหมี Shardtooth แก่ {world1} ตัวในบริเวณใกล้เคียง แล้วกลับไปหา Sarna Brownhorn" } },
    },
    [97266] = { -- First One's Free
        title = { "16:1487895368:1062069810", "ชิ้นแรกให้ฟรี" },
    },
    [97403] = { -- Two-Headed Ravagers
        title = { "19:992544032:377672594", "สัตว์ร้ายสองหัว" },
        description = { "495:2068353809:1318385487", "คิเมราพวกนี้เหมือนเรื่องตลกร้าย สองปากส่งเสียงคำรามด้วยไอหนาวและความหิว ราวกับแดนร้างนี้ยังมีเขี้ยวไม่พอ\n\nลานโล่งนี้เป็นที่เดียวที่เรามี พายุโถมเข้ามาทุกทีก่อนเราจะลงหลักได้มากกว่านี้ พวก Chillwind Ravager สองหัวบินวนรอบเรา ทดสอบความแน่วแน่และกินเวลาเราไปเรื่อย ๆ\n\nเราเสียเวลาขับไล่พวกมันมากกว่าสร้างอะไรเป็นชิ้นเป็นอัน\n\nลดจำนวนพวกมันลง ขับพวกมันออกจากที่นี่ให้ได้ ถ้าสัตว์ร้ายที่เพ่นพ่านเหลือน้อยลง เราอาจสร้างอะไรที่อยู่ได้นานในแดนร้างเยือกแข็งนี้" },
        objective = { "79:126530518:1853063152", "สังหาร Chillwind Ravager 15 ตัว แล้วกลับไปหา Rilan Howard ทางเหนือของ Winterspring", amount = { "5:409775429:850574908 W1 72:1432929490:811863033", "สังหาร Chillwind Ravager {world1} ตัว แล้วกลับไปหา Rilan Howard ทางเหนือของ Winterspring" } },
    },
    [97404] = { -- Too Bad to Bear
        title = { "15:1769492336:264245269", "ศึกกับแม่หมีเฒ่า" },
        description = { "495:135500649:413719086", "มีแม่หมีเฒ่าสองตัว พ้นวัยเลี้ยงลูกมานานแล้ว อาจเป็นพี่น้องกัน หรืออาจเป็นหมีสองตัวที่ผูกพันกันเพราะผ่านฤดูต่าง ๆ มาคล้ายกัน\n\nไม่ว่าอะไรจะทำให้มาอยู่ด้วยกัน พวกมันยังดุร้ายและมีใจสู้ที่จะอยู่รอดจนน่าเคารพ หมี Shardtooth แก่สองตัวนี้ทำให้เราตั้งค่ายอย่างที่เห็นได้ยาก\n\nนำหัวของ Kuroma และ Kamuro กลับมา พยายามจบชีวิตพวกมันให้ไว ใช้ฝีมือและให้มันทรมานน้อยที่สุด" },
        objective = { "97:128316324:1210765842", "สังหารแม่หมีเฒ่า Shardtooth ทั้ง Kuroma และ Kamuro แล้วนำหัวของทั้งคู่กลับไปให้ Sarna Brownhorn" },
    },
    [91952] = { -- The Source of the Corruption
        title = { "28:1664526876:393766580", "ต้นตอของมลทิน" },
        description = { "418:1156978780:1877631280", "มลทินมากมายไหลลงมาสู่ Felwood จากเบื้องบน ยามน้ำจาก Hyjal ไหลหลาก มันพามลทินเฟลมาด้วยจนเต็ม มลทินซึมลงดิน ทำให้ต้นไม้และพืชล้มป่วย\n\nเคยมีดรูอิดสันโดษชื่อ Ketharas อาศัยอยู่ในป่า เขารู้เรื่องภูเขานี้ลึกซึ้ง หากมีใครรู้ว่าเกิดอะไรขึ้นที่ Hyjal ก็ต้องเป็นเขา\n\nข้าคิดว่า Felwood จะฟื้นตัวได้ก็ต่อเมื่อแก้ปัญหาที่ Hyjal เสียก่อน" },
        objective = { "40:338845850:369221038", "ตามหาฤๅษี Ketharas บน Mount Hyjal" },
    },
    [95560] = { -- The Mysterious Scroll
        title = { "21:1718017376:658499904", "ม้วนหนังสือลึกลับ" },
        description = { "422:91724000:1598844460", "<ม้วนหนังสือลึกลับเขียนด้วยลายอักษรพลิ้วไหวคล้ายภาษา Darnassian แต่จังหวะของถ้อยคำผิดแปลกไปเล็กน้อยจากอักษรเอลฟ์แท้ ๆ เจ้าคล้ายจะสัมผัสพลังเวทจาง ๆ ได้ มันหายไปก่อนเจ้าจะแน่ใจ\n\nเจ้ารู้สึกเหมือนมีแรงดึงเบา ๆ ในใจ ชักให้มุ่งไปทางเหนือสุดของ Felwood ไม่รู้ว่ารู้ได้อย่างไร แต่มีใครบางคนที่นั่นต้องการความช่วยเหลือ>" },
    },
