    [3381] = { -- A Meeting with the Master
        title = { "25:312336147:1028493032", "เข้าพบนายท่าน" },
        description = { "12:129830482:819514767 R 490:118594940:231948873", "อา ชาว{race} รุ่นเยาว์มาคุยกับ Sanath ช่างเป็นวันที่วิเศษจริง ๆ! ข้ารู้สึกเป็นเกียรติเหลือเกินที่เจ้ากรุณาเสด็จมา ขอบใจนะ!\n\nขอที... อย่าหลงตัวเองจนคิดว่าที่ข้าพูดประชดคือคำชม เอาให้ชัดนะ ข้าไม่ชอบเจ้า แต่เรื่องที่คุยกันไม่ได้เกี่ยวกับเราสองคน เกี่ยวกับนายของข้า\n\nเอาขนฮิปโปกริฟมาสักสองเส้นให้ข้าทำลูกธนู แล้วข้าจะให้เจ้าเข้าพบเขา เขาสั่งให้ข้าส่งนักผจญภัยที่พิสูจน์แล้วว่าคู่ควรไปหา" },
        objective = { "101:670253899:487851302", "หากต้องการพบเจ้านายของ Sanath Lim-yo ให้นำขนฮิปโปกริฟสภาพสมบูรณ์ (Undamaged Hippogryph Feather) 2 เส้นไปให้เขาใน Azshara" },
        progress = { "383:1307508884:370026458", "ข้าอยู่ที่นี่ตามคำสั่งของนายท่าน ท่านอนุญาตให้ข้าเรียกราคาเท่าไรก็ได้สำหรับการส่งคนขึ้นไปบนหอคอย ตอนนี้ข้าขอเพียงขนนกสองเส้นจากนักเดินทางแต่ละคน จะได้ทำลูกธนูแบบฉบับของข้าต่อไป\n\nถ้าเจ้าไม่ระวังตัว ข้าจะขึ้นราคา หกเหรียญทองเป็นไง?\n\nว่าแล้วเชียว ทำตัวให้ดี แล้วข้าจะคิดราคาเท่าเดิม" },
        completion = { "240:1839303279:1481955013", "ขนนกสองเส้นตามที่ข้าขอ ใช้ได้ทีเดียว\n\nพร้อมแล้วหรือ? บอกมาได้เลย แล้วข้าจะส่งเจ้าขึ้นไป\n\nอ้อ ข้าเตือนอีกครั้งว่าทำตัวให้ดี... นายท่านของข้าไม่ชอบคนโง่ แต่ใจกว้างมากกับคนที่ทำให้ท่านพอใจ" },
    },
    [90116] = { -- Holy Threads
        title = { "12:51045381:769618834", "เส้นด้ายศักดิ์สิทธิ์" },
        description = { "486:26376097:1371510803", "กี่ทอผ้านี้พิเศษนะ เจ้ารู้หรือเปล่า? ช่างทุกคนของเราให้มหาปุโรหิตลงพรแก่เครื่องมือทำมาหากินของตน\n\nกี่ตัวนี้ดึงดูดเศษผ้ากับเส้นด้ายที่ถูกลิขิตมาให้ทอเป็นอาภรณ์ศักดิ์สิทธิ์ที่สุดสำหรับพิธีของเรา พอสะสมได้มากพอ เราก็จะทำเสื้อคลุมขึ้นใหม่ได้ วันอย่างนั้นควรค่าแก่การฉลอง อย่างน้อยสำหรับข้าละนะ\n\nถ้าอยากเห็นขั้นตอนด้วยตัวเอง ลองขึ้นด้ายจากผ้าสักสองสามพับใกล้ ๆ กี่ แล้วดูว่าแสงศักดิ์สิทธิ์จะทำอะไร" },
    },
    [90120] = { -- Red is Not Dead
        title = { "15:427041257:956322415", "สีแดงยังไม่ตาย" },
        description = { "507:558988526:1113227579", "อืม พูดถึงความลับ ข้ากำลังทำของอย่างหนึ่งอยู่ กระเป๋าหรูสำหรับทหารระดับสูงสุดของเรา ต้องใบใหญ่ ทำจากผ้าไหมอย่างดีที่สุด และที่สำคัญที่สุด ต้องแดงเท่าตราของ Scarlet Crusade\n\nวัสดุหาไม่ยาก ข้าจะใช้ด้ายทออรุณของเจ้า แต่การหาสีย้อมที่ได้เฉดพอดีนั้นเกินฝีมือข้า ออกตระเวนทั่วโลกหาสีแดงที่ลงตัวให้ที แล้วข้าจะถือว่าเจ้าร่วมทำงานนี้กับข้าและแบ่งแบบฉบับสุดท้ายให้" },
    },
    [90510] = { -- New Avalon
        title = { "10:1596842692:1337002497", "นิวอวาลอน" },
        description = { "482:1184264571:1473287759", "อย่างที่เจ้าเห็น New Avalon มีกำลังทหารอยู่มาก แต่ก็ให้ความปลอดภัยและความมั่นคงแก่ชาวเมืองด้วย\n\nถ้าหาทางทำเครื่องปลอมตัวที่ใช้ได้นานขึ้น ลองยื่นมือช่วยชาวเมืองดู การทำให้พวกเขาชอบเจ้าอาจช่วยให้เราทวงเขตที่มั่นคืนได้ แถมยังเปิดโอกาสให้เจ้า «หยิบยืม» วัสดุและทรัพยากรบางส่วนที่นั่น เพิ่มทรัพย์ให้ตัวเองไปพร้อมกับตัดเสบียงสำคัญของกองทัพพวกนั้น" },
    },
    [90518] = { -- An Apple a Day Keeps the Undead at Bay
        title = { "38:1255520617:813258719", "แอปเปิลวันละลูก อันเดดไม่กล้าเข้าใกล้" },
        description = { "497:197936894:436906249", "ดีใจที่ได้เจอเจ้าอีก ตั้งแต่เจ้าไม่อยู่ ข้าก็หาเสบียงเติมครัวได้ไม่มีปัญหา แต่เช้านี้เพิ่งเห็นว่าขาดแอปเปิลอีกนิดถึงจะทำพายได้ ข้าคิดว่าถึงเวลาให้รางวัลตัวเองสักหน่อยแล้ว\n\nถ้ามีเวลาสักครู่ แวะสวนผลไม้ไปเก็บมาให้หน่อยได้ไหม? เสียดายที่ข้ายังไม่ได้ทำพายให้ Johnny เหมือนกัน แต่ไม่มีแอปเปิลก็ทำพายไม่ได้ และข้าจะไม่เอาแอปเปิลไปเสียกับพายของ Johnny หรอก!\n\nแน่นอน ข้าจะแบ่งให้เจ้าชิ้นหนึ่ง" },
        completion = { "400:1850151053:949835943", "เยี่ยมเลย ข้าจะลงมือเดี๋ยวนี้! แอปเปิลพวกนี้ดูดีกว่าคราวก่อนที่เจ้าเอามาให้เสียอีก เหมือนเจ้าตั้งใจจะเอาใจข้าเลยนะ...\n\n<ระหว่างจัดที่เตรียมทำพาย Carrie จงใจออกท่าทางเกินจริงให้เห็นแหวนแต่งงานชัด ๆ>\n\nขอบใจที่แวะมาและช่วยให้มื้อเย็นของเราดีขึ้นนะ ข้ากับ Markus หวังว่าจะได้เจอเจ้าอีกเร็ว ๆ นี้!" },
        objective = { "269:146781438:1747886650", "ไปเก็บแอปเปิลที่สวนทางใต้ของ New Avalon แล้วกลับไปหา Carrie Hearthfire ที่โรงเตี๊ยมในเมือง ถ้าแอปเปิลแพงเกินไป ลองมองหาวิธีอื่นแถวนั้น" },
        progress = { "153:303866548:817215812", "จำไว้นะว่า Johnny อาจเรียกราคาแพงขึ้นสำหรับแอปเปิลลูกงาม ๆ แต่ถ้าเจ้าไม่อยากให้เขาได้กำไรเพิ่ม ข้าเชื่อว่าเจ้าคงหาทางอื่นได้" },
    },
    [90519] = { -- Fish On Demand
        title = { "14:1449469692:642468904", "ขอปลาเดี๋ยวนี้" },
        description = { "337:1440286136:399095205", "ข้าเกลียดปลา ทนกลิ่นมันไม่ได้ มันชวนขนลุกสุด ๆ แย่จริง ๆ\n\nนี่ครัวข้า ข้ามีสิทธิ์สั่งห้ามเอาปลาเข้า และข้าก็ห้ามจริง ๆ แต่บางครั้งทหารของเราก็คิดขึ้นมาเองว่าอยากกินปลามื้อใหญ่\n\nดูเหมือนคืนนี้จะเป็นคืนแบบนั้น ข้าต้องการปลา ด่วนเลย!" },
        objective = { "104:1024150206:1317218200", "ไปดูว่าเรือที่จอดทางใต้ของ New Avalon มีปลาที่ขนมาส่งหรือไม่ แล้วเอาปลาที่หาได้กลับไปให้ Carrie" },
    },
    [90520] = { -- Food Safety
        title = { "11:2103480388:155983123", "อาหารต้องปลอดภัย" },
        description = { "461:17640765:982319688", "ข้าจำได้คลับคล้ายคลับคลาว่าวัตถุดิบอย่างหนึ่งที่ให้เจ้าไปหาตอนเจอกันครั้งแรกคือเนื้อ แล้วข้าก็จำได้ราง ๆ ว่าคืนนั้นคนบ่นกันเยอะว่าอาหารทำให้พวกเขาป่วย เรื่องประหลาดจริง ๆ\n\nเอาเถอะ เนื้อในห้องเก็บเสบียงใกล้หมดอีกแล้ว จะดีมากถ้ามีคนที่ไว้ใจได้ช่วยหาเพิ่ม ข้าไม่อยากรอของอยู่ดี ๆ แล้วเพิ่งมารู้ทีหลังตั้งหนึ่งสัปดาห์ว่าคนส่งตายไปแล้ว!" },
        completion = { "371:559211798:1752316411", "เจ้ารักษาคุณภาพได้สม่ำเสมอจนน่าทึ่งเลย สหาย เนื้อแต่ละชิ้นหั่นมาอย่างชำนาญ สีและเนื้อสัมผัสก็เหมือนคราวที่แล้ว ถ้าวันไหนข้าต้องออกไปล่าหาอาหารเอง ข้าก็หวังว่าจะมีเจ้าไปด้วย\n\nแล้วก็ Markus ด้วยแน่นอน\n\nเดี๋ยวข้ารับเนื้อพวกนี้ไปลงมือทำเลย คืนนี้ชาว New Avalon จะได้กินของอร่อยกัน!" },
        objective = { "177:1738315764:1195165459", "หาเนื้อที่คนกินได้อย่างปลอดภัย ถ้าหาใน New Avalon ไม่เจอ ลองล่าสัตว์ใน Eastern Plaguelands สักพักก็น่าจะได้เนื้อพอ" },
        progress = { "57:1528363276:1664251020", "ถ้ายังเป็นแบบนี้ มื้อเย็นคงเลื่อนไปอีกหน่อย" },
    },
    [90560] = { -- Familiar Foulness
        title = { "17:1694891224:496078014", "ของเหม็นที่คุ้นเคย" },
        description = { "487:2018389732:604197258", "<เจ้าพบขวดแก้วใส่ของเหลวข้นหนืดกลิ่นเหม็นบนโต๊ะทดลอง รอบขวดมีวัตถุดิบหลายอย่างที่ตวงอย่างละเอียดและหั่นแบ่งเป็นส่วนอย่างประณีต สมุนไพรแยกไม่ออกว่าเป็นชนิดไหน แต่ใกล้ ๆ กันมีหัวใจสัตว์สีผิดปกติที่ยังสมบูรณ์อยู่หนึ่งดวง\n\nยาผสมนี้ดูคุ้นตา ชวนให้นึกถึงการทดลองเมื่อไม่นานมานี้ของ Royal Apothecary Society ถ้าเจ้าอยากรู้มากกว่ารังเกียจ สมาชิกสักคนของสมาคมอาจสนใจสิ่งที่เจ้าพบ>" },
        objective = { "188:282931303:1999192813", "เก็บ Discolored Beast Heart จากสัตว์ใน Plaguelands แล้วนำไปพร้อม Mishandled Healing Potion ให้สมาชิก Royal Apothecary Society ที่สนใจใน Undercity" },
        progress = { "33:376786454:941329695", "หืม เจ้าจะเอาอะไรมาให้ข้าหรือ" },
        completion = { "468:1478294151:2007524204", "อา หืม เป็นของฝากที่เอาใจใส่ดีละมั้ง ถ้าข้ามีเวลาและวัตถุดิบเพิ่มอีกหน่อย คงไขปริศนาเรื่องยาที่เจ้าอยากรู้ได้ แต่ตอนนี้ข้ามีเรื่องเร่งด่วนกว่าต้องจัดการ อีกอย่าง หัวใจสัตว์ป่วยเป็นงานถนัดของ Apothecary Renferrel มากกว่า\n\nโชคดีที่ข้ากำลังจะไปทำธุระให้ Renferrel พอดี สนใจฆ่ามนุษย์สองคนด้วยโรคระบาดเดียวไหม... ข้าพูดเปรียบเปรยหรอกนะ" },
    },
    [90566] = { -- Oh, My Bleeding Hearts!
        title = { "23:1146542576:1244839458", "โอ้ เจ้าหัวใจเลือดไหลของข้า!" },
        description = { "500:578511362:373865438", "ดูจากมลทินในตัวอย่างที่เจ้าเอามา ข้าเดาว่าเจ้าคงคุ้นกับ Plaguelands ดี ย่อมเข้าใจว่าการข้าม Bulwark ไปหาเสบียงเพียงลำพังลำบากแค่ไหนสำหรับสมาชิก Royal Apothecary Society\n\nRenferrel บอกว่านอกจากหัวใจที่เคยเต้นได้แล้ว เขายังสนใจดอกไม้ที่ชื่อ Bleeding Heart ด้วย ข้าไม่แน่ใจว่าเอาไปวิจัยการเล่นแร่แปรธาตุหรือแค่ชอบดู แต่ข้ารู้ว่าเขาต้องยินดีถ้าได้รับหัวใจหลาย ๆ แบบ" },
    },
    [90567] = { -- Unfamiliar Foulness
        title = { "19:1127705265:1419123353", "ของเหม็นที่ไม่คุ้นเคย" },
        description = { "506:820677390:430665646", "<เจ้าพบขวดแก้วใส่ของเหลวข้นหนืดกลิ่นเหม็นบนโต๊ะทดลอง รอบขวดมีวัตถุดิบหลายอย่างที่ตวงอย่างละเอียดและหั่นแบ่งเป็นส่วนอย่างประณีต สมุนไพรแยกไม่ออกว่าเป็นชนิดไหน แต่ใกล้ ๆ กันมีหัวใจสัตว์สีผิดปกติที่ยังสมบูรณ์อยู่หนึ่งดวง\n\nนักเล่นแร่แปรธาตุใน Darnassus อาจรู้ว่าจะดึงสรรพคุณฟื้นฟูออกจากยานี้ได้อย่างไร หากมันมีสรรพคุณนั้นอยู่จริง เอาดอกไม้ไปด้วยสักหน่อย จะได้ไม่พรวดพราดเข้าร้านไปพร้อมกองหัวใจอย่างเดียว>" },
        objective = { "158:1178434087:777999675", "เก็บ Discolored Beast Heart และ Bleeding Heart จาก Plaguelands แล้วนำไปพร้อม Mishandled Healing Potion ให้ผู้ปรุงยาที่สนใจใน Darnassus" },
    },
    [90626] = { -- Sinew of Light
        title = { "14:959405531:1384416805", "สายเอ็นแห่งแสง" },
        description = { "234:1750882915:2018633718", "Grok'lo จะนัดช่างฝีมือพิเศษให้เมื่อเจ้าหาสายที่เหมาะกับปีกค้างคาวยักษ์นั่นได้\n\nGrok'lo แนะนำให้หาสายดีที่สุดเท่าที่จะหาได้\n\n<Grok'lo ยิ้มอยู่ใต้หมวกเกราะ>\n\nDragon Sinew เป็นสายดีที่สุดแน่นอน" },
        objective = { "134:504392264:879552194", "โค่น Solistrasza แล้วเก็บเอ็นมังกรแสงโตเต็มวัยไปให้ Grok'lo ที่ Light's Hope Chapel ใน Eastern Plaguelands" },
        completion = { "156:35520309:249954843", "นี่สิถึงเรียกว่าสายธนู! Grok'lo ชอบของสว่าง ๆ!\n\n<Grok'lo พยักหน้า>\n\nอา Grok'lo มั่นใจเลยว่าพอทำเป็นธนูแล้ว เจ้าจะขายได้ทองตั้งเยอะ" },
        progress = { "49:720007:866496778", "เจ้าหาสายที่เข้ากับปีกค้างคาวของเจ้าได้หรือยัง?" },
    },
    [90813] = { -- Pay Dirt!
        title = { "9:1716941019:284259160", "ขุดเจอของดี!" },
        description = { "203:2059075011:464017755", "<ผลึกก้อนใหญ่นี้หนักกว่าที่เห็นเสียอีก ดูท่าจะเป็นของล้ำค่า แต่เจ้าไม่รู้ว่าจริง ๆ แล้วมันคืออะไร คนที่รู้เรื่องหินและแร่น่าจะบอกได้ว่าเจ้าเจออะไรเข้า>" },
        objective = { "47:1663301855:348367819", "หาคนประเมินมูลค่า Humongous Crystal" },
    },
    [91488] = { -- Home on the Range
        title = { "17:864255260:1741979195", "บ้านกลางทุ่ง" },
        description = { "336:2084811594:566979010", "เต็นท์ข้าเสียหายหนักในการปะทะกับพวกบลัดเอลฟ์ครั้งล่าสุด ข้าต้องนอนตากลมฟ้าอากาศมาสามคืนแล้ว\n\nใช้หนัง Mosshoof ไม่กี่ผืนก็ซ่อมได้ แต่ข้าอดนอนจนออกไปล่าเองไม่ไหว\n\nMosshoof ที่ล่าง่ายที่สุดอยู่ทางตะวันตกและทางใต้ของที่นี่ แต่หนังจากตัวไหนก็ใช้ได้" },
        objective = { "55:1394515677:1613417241", "นำหนัง Mosshoof 5 ผืนไปให้ Kurll ที่ Valormok ใน Azshara" },
    },
    [91497] = { -- Seals of the Sin'dorei
        title = { "22:451104797:1124343985", "ตราผนึกแห่ง Sin'dorei" },
        description = { "500:1163592652:1818629198", "<ตราผนึกของผลึกก้อนแรกมีรูปดาบ ต้องให้นักรบผู้ชำนาญเป็นคนชักนำพลังของมัน\n\nตราผนึกของผลึกก้อนกลางมีรูปดาบวงแหวน ต้องให้ผู้ชำนาญทั้งการต่อสู้และเวทมนตร์เป็นคนชักนำพลังของมัน\n\nตราผนึกของผลึกก้อนสุดท้ายมีรูปกรงเล็บ ต้องให้ผู้ที่คุ้นเคยกับพงไพรเป็นคนชักนำพลังของมัน\n\nนายทหารบางคนของ Rimtori น่าจะพกตราเหล่านี้ไว้ช่วยนางร่ายเวท หากชิงมาได้ นางคงลำบากแน่>" },
        objective = { "109:1538577954:1871681316", "นำ Seal of the Warden, Seal of the Warrior และ Seal of the Ranger ไปยัง Sin'dorei Tome of Summoning" },
        required = { [246725] = { "18:1718758530:72840890", "ตราผนึกผู้พิทักษ์" }, [246721] = { "19:1724703444:983764237", "ตราผนึกนักรบ" }, [246722] = { "18:808911694:439978368", "ตราผนึกนายพราน" } },
        objectiveLabels = {
            item = { ["Seal of the Warden"] = "ตราผนึกผู้พิทักษ์", ["Seal of the Warrior"] = "ตราผนึกนักรบ", ["Seal of the Ranger"] = "ตราผนึกนายพราน" },
        },
    },
    [91500] = { -- An Explosive Gambit
        title = { "19:1686642118:709587802", "เดิมพันด้วยแรงระเบิด" },
        description = { "325:2076675720:826290697", "<เมื่อเห็นว่าพลังของผลึกเชื่อมกับตราผนึก เจ้าก็คิดได้ว่าถ้าทำลายตราให้ปล่อยพลังออกมาพร้อมกันทีเดียว ผลึกอาจปล่อยพลังออกมาแบบเดียวกัน\n\nแรงระเบิดคงทำให้ Rimtori เดือดจัด และเปิดโอกาสเหมาะให้โจมตีนางตอนที่กำลังเสียขวัญ>" },
        objective = { "98:867246927:391841838", "ทำลายตราผนึกแห่ง Sin'dorei แล้วนำศีรษะของ Magus Rimtori ไปให้ Ag'tor Bloodfist ที่ Valormok" },
        required = { [10597] = { "21:2107486175:899796149", "ศีรษะของจอมเวท Rimtori" } },
        objectiveLabels = {
            item = { ["Head of Magus Rimtori"] = "ศีรษะของจอมเวท Rimtori" },
        },
    },
    [91538] = { -- Sin'dorei Tome of Summoning
        title = { "27:361391928:218590673", "คัมภีร์อัญเชิญแห่ง Sin'dorei" },
        description = { "175:494641628:1787310488", "คัมภีร์ของ Rimtori ยังวางอยู่บนแท่น ใครจะรู้ว่าข้างในซ่อนความลับอะไรไว้บ้าง?\n\nวัตถุทรงพลังขนาดนี้คงไม่ควรทิ้งไว้กลางป่า" },
        objective = { "65:226853028:1549043874", "นำ Sin'dorei Tome of Summoning กลับไปให้ Jediga ที่ Valormok" },
        required = { [246770] = { "27:361391928:218590673", "ตำราอัญเชิญของ Sin'dorei" } },
        objectiveLabels = {
            item = { ["Sin'dorei Tome of Summoning"] = "ตำราอัญเชิญของ Sin'dorei" },
        },
    },
    [91547] = { -- Sin'dorei Tome of Summoning
        title = { "27:361391928:218590673", "คัมภีร์อัญเชิญแห่ง Sin'dorei" },
        description = { "28:1274179145:2005517640 N 286:269815724:1686819057", "เจ้าคิดถูกแล้วที่เอามา {name} การเก็บคัมภีร์ให้พ้นมือบลัดเอลฟ์ช่วยตัดกำลังไม่ให้พวกมันตอบโต้เราได้ยิ่งกว่าการฆ่า Rimtori เสียอีก\n\nส่วนเรื่องถอดความในคัมภีร์ ข้ารู้จักคนใน Orgrimmar ที่สนใจเรื่องพรรค์นี้ วอร์ล็อกชื่อ Zevrost หาเขาได้ที่ Cleft of Shadow" },
        objective = { "62:209584983:1546295358", "นำ Sin'dorei Tome of Summoning ไปให้ Zevrost ใน Orgrimmar" },
    },
    [91568] = { -- Long Walks on the Beach
        title = { "23:1391934794:861274137", "เดินทอดน่องริมทะเล" },
        description = { "477:973438151:789787637", "ชายหาดแถวนี้อาจไม่สวย แต่ของที่ซ่อนอยู่มีราคานะ!\n\nซากปรักหักพังส่วนใหญ่โดนเก็บเกลี้ยงแล้ว แต่ใต้ทรายยังมีของดี ๆ เพียบ ปัญหาคือของกระจัดกระจาย แถมพวกนากาก็ทำให้เดินหานาน ๆ ไม่สะดวก แล้วข้าจะทำยังไงดีล่ะ?\n\nนี่เลย Treasure Trowel 3000! พลั่วตรวจหาสมบัติครบจบในอันเดียว ข้าประดิษฐ์เองกับมือ\n\nเอาเจ้านี่ลงไปที่ชายฝั่งตะวันออก หาอะไรเจอก็เอากลับมา แล้วเราแบ่งกำไรกัน!" },
        objective = { "99:491662794:1607142308", "ขุดชิ้นส่วนสมบัติ Highborne 10 ชิ้นด้วยเกรียงขุดสมบัติ 3000 ให้ Izvi Glidfizz ที่ Valormok", amount = { "7:837291055:1028666551 W1 90:819273746:370855688", "ขุดชิ้นส่วนสมบัติ Highborne {world1} ชิ้นด้วยเกรียงขุดสมบัติ 3000 ให้ Izvi Glidfizz ที่ Valormok" } },
    },
    [91569] = { -- Blue Gold
        title = { "9:996708382:1379990885", "ทองคำสีฟ้า" },
        description = { "490:735754574:838314597", "ฟังนะเจ้าหนู ทุกคนแถวนี้แย่งของอย่างเดียวกัน ทั้ง Belgrom พวกเอลฟ์ พวกนากา ต่างก็อยากได้ส่วนแบ่งจากเวทโบราณของพวกไฮบอร์น\n\nข้าน่ะหรือ? ไม่สนเวทหรอก แต่เห็นคนแย่งซื้อกันแบบนี้ ข้ารู้ทันทีว่าคนขายได้เปรียบ\n\nข้าเห็นนักเวทอาคมบลัดเอลฟ์พกไม้กายสิทธิ์พิเศษไว้ดึงพลังเวทจากวัตถุโบราณที่พวกมันหาเจอ นักเวทพวกนั้นอยู่ในค่ายตามหน้าผาทางตะวันออกของค่ายหลักเอลฟ์ เอาไม้กายสิทธิ์มาให้ข้าสักอัน แล้วข้าจะชี้ช่องทำเงินครั้งใหญ่ที่สุดในชีวิตให้!" },
        objective = { "57:1630739108:511310882", "นำคทาดูดมานาไปให้ Izvi Gildfizz ที่ Valormok" },
    },
    [91607] = { -- Pay Dirt!
        title = { "9:1716941019:284259160", "ขุดเจอของดี!" },
        description = { "203:670456162:1069208046", "<ผลึกก้อนใหญ่นี้หนักกว่าที่เห็นเสียอีก ดูท่าจะเป็นของล้ำค่า แต่เจ้าไม่รู้ว่าจริง ๆ แล้วมันคืออะไร คนที่ดูของมีค่าเป็นน่าจะบอกได้ว่าเจ้าเจออะไรเข้า>" },
        objective = { "47:1663301855:348367819", "หาคนประเมินราคาผลึกขนาดมหึมา" },
    },
    [91608] = { -- Gettin' Buzzed
        title = { "14:823108291:934431193", "จิบให้มึน" },
        description = { "438:1003099802:648907298", "ชายแดนแบบนี้แทบไม่มีของให้สำราญ ได้เหล้าดีสักถังคงช่วยให้คนในค่ายคึกคักขึ้น\n\nตอนหนุ่ม ๆ ข้าเอาสูตรหมักเหล้ารสเด็ดมาจากศพคนแคระที่ข้าฆ่า ขาดแค่น้ำผึ้ง โชคดีที่รังตัวต่อทางตะวันตกมีน้ำผึ้งล้นรัง\n\nเอาปืนยิงเม็ดของข้าไป ใช้มันยิงรังให้ตกจากต้นไม้ได้ แต่ขอเตือนไว้ก่อนว่ามันแทบใช้ทำอะไรตัวต่อไม่ได้เลย" },
        objective = { "7:451016854:1830523975 W1 53:614798413:1668209525", "ใช้ Kurll's Pellet Gun เก็บ Wild Honey {world1} หน่วยจาก Wasp Nest" },
        required = { [238503] = { "10:1233606029:1257675740", "น้ำผึ้งป่า" } },
        objectiveLabels = {
            item = { ["Wild Honey"] = "น้ำผึ้งป่า" },
        },
    },
    [91609] = { -- Summer Frontier Fishery
        title = { "23:889740086:939875682", "ตกปลาชายแดนในฤดูร้อน" },
        description = { "313:592392043:1138360712", "เนื้อก็ดีอยู่หรอก แต่กินให้หลากหลายจะทำให้ร่างกายแข็งแรงขึ้น\n\nตอนนี้เป็นฤดูของ Summer Bass ตกได้ตามชายฝั่ง Azshara ข้าเองไม่ถนัดตกปลา ชอบความปลอดภัยบนบกมากกว่า ถ้าเจ้าตกมาได้สักหน่อย หรือหามาด้วยวิธีอื่น ข้าจะขอบใจมาก" },
    },
    [91610] = { -- Winter Frontier Fishery
        title = { "23:1604172562:2071423432", "ตกปลาชายแดนในฤดูหนาว" },
        description = { "314:1087975478:1944909283", "เนื้อก็ดีอยู่หรอก แต่กินให้หลากหลายจะทำให้ร่างกายแข็งแรงขึ้น\n\nตอนนี้เป็นฤดูของ Winter Squid ตกได้ตามชายฝั่ง Azshara ข้าเองไม่ถนัดตกปลา ชอบความปลอดภัยบนบกมากกว่า ถ้าเจ้าตกมาได้สักหน่อย หรือหามาด้วยวิธีอื่น ข้าจะขอบใจมาก" },
        objective = { "46:353525428:1914392850", "ตกหมึกฤดูหนาว 10 ตัวไปให้ Kurll ที่ Valormok" },
    },
    [91611] = { -- Deadliest Catch
        title = { "15:988937811:1741994180", "เหยื่อที่อันตรายที่สุด" },
        description = { "383:2068635243:1434649858", "ถ้าอยากทดสอบฝีมือตกปลาจริง ๆ ก็มีปลาตัวใหญ่เกินกว่าจะใช้เบ็ดตกได้อยู่\n\nMammoth Shark ซุ่มอยู่ในน้ำลึกที่สุดนอกชายฝั่งทางเหนือและใต้ พวกมันว่ายอยู่ไกลออกไป ตรงก่อนที่พื้นทะเลจะดิ่งลงสู่มหาสมุทร\n\nมันตัวมหึมา ข้าแนะนำให้รวมกลุ่มออกล่า\n\nถ้าเจ้าออกล่าจริง ๆ เอาเนื้อกลับมาให้ข้าสักชิ้นด้วย" },
        objective = { "49:73866927:2025881713", "นำเนื้อฉลามแมมมอธหนึ่งชิ้นไปให้ Kurll ที่ Valormok" },
    },
    [91685] = { -- Ley of the Land
        title = { "15:801073126:605406478", "สายพลังใต้แผ่นดิน" },
        description = { "496:1393922911:1403826746", "ตอนมาถึงใหม่ ๆ ข้าออกสำรวจหาแหล่งทรัพยากรที่ยังไม่มีใครแตะ งานตามประสาคนสำรวจแร่แหละ\n\nไม่เห็นอะไรพิเศษจนไปค้นที่ Lake Mennar ทางใต้ ที่นั่นข้าเห็นรอยแยกขนาดใหญ่ลอยเหนือผิวน้ำ ข้าเข้าไปใกล้ไม่ได้ แต่คิดว่าเป็นสายพลังเวทที่เปิดออก\n\nถ้าคิดถูก เราก็ใช้ไม้กายสิทธิ์นี้ดูดเวทจากต้นทางได้เลย! เก็บใส่ขวด ขายให้คนที่ให้ราคาสูงสุด เท่านี้ข้าก็รวยแล้ว!\n\nถ้าเจ้าไปดูดพลังจากรอยแยกมาให้ ข้าจะแบ่งส่วนให้ด้วย" },
        objective = { "109:1381422451:1042524665", "ใช้คทาดูดมานากับรอยแยกเส้นพลังที่ทะเลสาบ Mennar แล้วนำหยาดน้ำตาแห่ง Mennar ไปให้ Izvi Gildfizz" },
    },
    [91734] = { -- Remote Contact
        title = { "14:1498202022:468610237", "ติดต่อคนที่อยู่ไกล" },
        description = { "161:781923885:1712943879", "<ชาว Forsaken โงนเงนไปมา>\n\nเฮ้! <สะอึก> ช่วยข้าหน่อย... ได้ไหม?\n\nไปที่ เอ่อ... Azshara แล้ว... บอก <สะอึก> Jediga...\n\nว่าข้ารอ... ของส่งสำคัญอยู่ <สะอึก>" },
        objective = { "27:4131316:725883089", "คุยกับ Jediga ใน Azshara" },
    },
    [91735] = { -- Remote Contact
        title = { "14:1498202022:468610237", "ติดต่อคนที่อยู่ไกล" },
        description = { "8:2102215530:680664386 C 275:1811477397:494125928", "ฟังนะ {class} เจ้าไม่ควรอยู่แถวนี้นานนัก แต่ไหน ๆ ก็อยู่แล้ว ช่วยทำอะไรให้ข้าสักอย่างได้ไหม?\n\nข้ารอของบางอย่างจาก Jediga ที่ Azshara นางตั้งค่ายอยู่ที่นั่นกับออร์คกลุ่มหนึ่ง ไปบอกนางว่า Jes'rimon ส่งเจ้ามา แล้วข้าจะติดหนี้บุญคุณเจ้าหนึ่งครั้ง" },
        objective = { "27:4131316:725883089", "คุยกับ Jediga ใน Azshara" },
    },
    [91737] = { -- Remote Contact
        title = { "14:1498202022:468610237", "ติดต่อคนที่อยู่ไกล" },
        description = { "345:712862649:456723965", "บางครั้งหน้าที่ของข้าต้องใช้วัตถุดิบจากดินแดนห่างไกลใน Azeroth แต่คนที่ Thunder Bluff ต้องการข้าอยู่เสมอ ข้าจึงต้องอาศัยผู้ช่วยที่ไว้ใจในฝีมือได้\n\nตอนนี้ข้ารอของจากออร์คชื่อ Jediga ที่ Azshara หากเจ้าอยากช่วย ไปหาค่ายของนางแล้วถามว่าข้าจะได้รับของเมื่อไร" },
        objective = { "27:4131316:725883089", "คุยกับ Jediga ใน Azshara" },
    },
    [91877] = { -- Demon Hunter's Hunter
        title = { "21:1802933012:572936681", "ตามหานักล่าปีศาจ" },
        description = { "421:103015714:1253429841", "ตอนนี้นักล่าปีศาจเหลืออยู่ไม่มากใน Azeroth แต่พวกเราบางคนยังตามล่าภัยที่ร้ายแรงที่สุดหรือที่หลบซ่อนอยู่\n\nMaerion Thaelemaches สหายร่วมงานของข้าเดินทางไป Hyjal เพื่อสืบข่าวเรื่องปีศาจที่นั่น ใน Darkwhisper Gorge อันตรายและมีปีศาจมากมาย แต่เราสงสัยว่าปีศาจที่บุกภูเขาเมื่อสงครามครั้งก่อนอาจยังไม่พ่ายแพ้หมด\n\nเรื่องนี้ต้องสืบดู" },
        objective = { "51:225442163:1237646147", "ตามหา Maerion Thaelemaches บน Mount Hyjal" },
    },
    [92065] = { -- Blackmaw Reclamation
        title = { "20:168616501:366881510", "ทวงคืน Blackmaw" },
        description = { "37:974318838:1441922686 R 460:307276132:1819203844", "เจ้าจะช่วยเราในศึกสุดท้ายและเป็นผู้กอบกู้ Blackmaw ไหม ชาว{race}?\n\nVarrox Bleakhoof คือภัยร้ายของ Blackmaw เป็นปีศาจที่กระหายการทำลายล้างไม่รู้จักอิ่ม มลทินของมันกลืนกินทุกสิ่งที่สัมผัส ถึงตอนนี้มันกับสมุนยังคงทำลายโพรงของเรา\n\nเราสู้กับพวก Legashi มาไกลแล้ว แต่หาก Blackmaw จะมีอนาคต Varrox ต้องล้มลง\n\nตามหามันใน Blackmaw Hold แล้วโค่นมันเสีย เมื่อนั้นชาว Blackmaw จึงจะได้อยู่อย่างสงบ" },
        objective = { "64:653387377:1232978844", "นำหัวของ Varrox Bleakhoof ไปให้ Gatekeeper Rageroar ที่ Ursolan" },
    },
    [92066] = { -- The Twin Bears
        title = { "14:786176753:2024322907", "เทพหมีคู่" },
        description = { "411:602952448:1857905711", "ตอนพวก Legashi บุก เราทิ้งของล้ำค่าไว้หลายอย่างท่ามกลางความวุ่นวาย ของสำคัญสำหรับข้าเป็นพิเศษคือเสาโทเทมสองต้น สลักตำนานของเทพคู่ของเรา Ursoc กับ Ursol\n\nข้ารู้ว่าตอนนี้การอยู่รอดสำคัญที่สุด แต่เราต้องคิดถึงการรักษาประวัติของชนเผ่าเราด้วย\n\nโทเทมน่าจะยังอยู่ในที่มั่นเก่าของเรา ถ้ายังอยู่ เจ้าจะช่วยเราได้มากหากนำกลับมาให้ข้า" },
        objective = { "116:568958448:514918228", "ตามหาโทเทมของ Ursoc และโทเทมของ Ursol ใน Blackmaw Hold แล้วนำทั้งสองชิ้นกลับไปให้ผู้รักษาตำนาน Nok ที่ Ursolan" },
    },
    [92069] = { -- Claws That Rend, Tusks that Gore
        title = { "32:2044907727:800326232", "กรงเล็บฉีก เขี้ยวแทง" },
        description = { "436:669885607:1940428322", "สัตว์มหึมาสองตัวเดินเฝ้าที่ที่ Blackmaw เคยเรียกว่าบ้าน Bonesnout ผู้ไม่เคยพ่าย และ Withermaw หมีใหญ่ นักล่าหลายชั่วคนพยายามโค่นพวกมันและล้มเหลวกันหมด\n\nข้าไม่ยินดีเลยที่ต้องขอให้เจ้าฆ่าสัตว์สง่างามเช่นนี้ แต่คนของข้าต้องได้กลับบ้าน อย่างน้อยข้าก็จะให้พวกมันตายอย่างมีความหมาย ถ้าเจ้านำซากกลับมา ข้าจะทำอาวุธไว้รำลึกถึงพลังของพวกมัน" },
        objective = { "86:1485698365:1139058277", "นำ Claws of the Great Bear และ Tusks of the Unbroken ไปให้ Ogtinc ที่ Azshara" },
        required = { [249697] = { "23:1854052487:246634363", "กรงเล็บของหมีมหึมา" }, [249696] = { "21:698695353:960264958", "เขี้ยวของผู้ไม่เคยพ่าย" } },
        objectiveLabels = {
            item = { ["Claws of the Great Bear"] = "กรงเล็บของหมีมหึมา", ["Tusks of the Unbroken"] = "เขี้ยวของผู้ไม่เคยพ่าย" },
        },
    },
    [92070] = { -- A Lost Memento
        title = { "14:452731133:343110194", "ของที่ระลึกที่หายไป" },
        description = { "386:833196015:845384712", "สร้อยคอประดับเครื่องรางหลายอย่าง ทั้งเศษขนนก เปลือกลูกโอ๊ก และกรวดหลากสี สายหนังขาดแล้ว เครื่องประดับชวนให้คิดว่าเป็นของเฟอร์โบลก์ ส่วนขนาดเล็กกับฝีมือหยาบ ๆ ดูจะเป็นงานของเด็ก\n\nสร้อยนี้อาจมีคุณค่าทางใจต่อใครสักคนในเผ่า Blackmaw ลองหาเจ้าของแล้วนำไปคืนเถอะ" },
        objective = { "47:1071003128:382995085", "ตามหาเจ้าของ Feathered Charm Necklace" },
    },
    [92343] = { -- Get to the Roots of It
        title = { "22:1733814797:543919291", "ลงไปให้ถึงราก" },
        description = { "501:1513252309:1115173964", "โพรงที่เจ้าพูดถึงเป็นอุโมงค์ไปยัง Blackmaw Hold แต่ก่อนพวกเฟอร์โบลก์เฝ้ามันอย่างเข้มงวด คนนอกจึงเข้าไม่ได้ แต่เรื่องพวกเซเทอร์เปิดทางให้เราเข้าไปได้แล้ว\n\nใกล้ Nordrassil ขนาดนั้นต้องมีรากที่กำลังเติบโตอยู่ รากเก่าเห็นได้บนผิวโลก แต่รากใหม่พบได้ลึกลงไปใต้ดินเท่านั้น เรายังรู้คุณสมบัติทางเวทของมันน้อยมาก\n\nถ้าเจ้านำตัวอย่างมาให้ข้าศึกษา ดรูอิดแห่ง Thunder Bluff จะเป็นหนี้บุญคุณเจ้า" },
        objective = { "87:336157757:715930046", "เก็บ Nordrassil Root Cap 10 ชิ้นใน Blackmaw Hold ให้ Nara Wildmane ใน Thunder Bluff" },
    },
    [92344] = { -- Get to the Roots of It
        title = { "22:1733814797:543919291", "ลงไปให้ถึงราก" },
        description = { "493:501562255:1609235918", "โพรงที่เจ้าพูดถึงเป็นอุโมงค์ไปยัง Blackmaw Hold แต่ก่อนพวกเฟอร์โบลก์เฝ้ามันอย่างเข้มงวด คนนอกจึงเข้าไม่ได้ แต่เรื่องพวกเซเทอร์เปิดทางให้เราเข้าไปได้แล้ว\n\nใกล้ Nordrassil ขนาดนั้นต้องมีรากที่กำลังเติบโตอยู่ รากเก่าเห็นได้บนผิวโลก แต่รากใหม่พบได้ลึกลงไปใต้ดินเท่านั้น เรายังรู้คุณสมบัติทางเวทของมันน้อยมาก\n\nถ้าเจ้านำตัวอย่างมาให้ข้าศึกษา Cenarion Circle จะเป็นหนี้บุญคุณเจ้า" },
        objective = { "91:1967284036:1031776831", "เก็บ Nordrassil Root Cap 10 ชิ้นใน Blackmaw Hold ไปให้ Mathrengyl Bearwalker ที่ Darnassus" },
        required = { [250773] = { "19:328059039:1985340139", "หมวกรากของ Nordrassil" } },
        objectiveLabels = {
            item = { ["Nordrassil Root Cap"] = "หมวกรากของ Nordrassil" },
        },
    },
    [92345] = { -- Beneath Nordrassil
        title = { "18:1889612662:128005780", "ใต้ Nordrassil" },
        description = { "462:664308762:1552224329", "เจ้าอาจเห็นพวกเฟอร์โบลก์กับเซเทอร์แย่งโพรงกันอยู่ทางเหนือของที่นี่ ข้าสนใจสิ่งที่อาจอยู่ข้างในมากกว่าการต่อสู้ โพรงนั้นดูเหมือนจะทอดลงไปใต้ Nordrassil\n\nคงไม่ต้องอธิบายว่าทำไมเรื่องนี้ถึงสำคัญกับชาว Kaldorei\n\nพวกเราที่นี่งานล้นมืออยู่แล้ว แต่ควรแจ้งให้ดรูอิดแห่ง Darnassus รู้ ไปหา Mathrengyl Bearwalker ที่ Cenarion Enclave ให้เขาตัดสินว่าคุ้มจะสืบต่อหรือไม่" },
        objective = { "68:1243867511:1585433933", "คุยกับ Mathrengyl Bearwalker ที่ Cenarion Enclave ใน Darnassus" },
    },
    [92346] = { -- Beneath Nordrassil
        title = { "18:1889612662:128005780", "ใต้ Nordrassil" },
        description = { "459:1770639639:349792568", "เจ้าอาจเห็นพวกเฟอร์โบลก์กับเซเทอร์แย่งโพรงกันอยู่ทางตะวันออกเฉียงเหนือของที่นี่ ข้าสนใจสิ่งที่อยู่ข้างในมากกว่าการต่อสู้ โพรงนั้นดูเหมือนจะทอดลงไปใต้ไม้โลก ใครจะรู้ว่ามีอะไรอยู่ในนั้น?\n\nคนของเรากระจายกันทำงานจนไม่เหลือกำลังไปตรวจเอง แต่ข้ารู้จักทอเรนที่อาจสนใจเบาะแสนี้ นางชื่อ Nara Wildmane เป็นดรูอิดใน Thunder Bluff บอกนางว่า Jediga ส่งเจ้ามา มีคนติดหนี้บุญคุณไว้ก็ดีเสมอ" },
        objective = { "54:385650327:1913156129", "คุยกับ Nara Wildmane ที่ Elder Rise ใน Thunder Bluff" },
    },
    [97198] = { -- Blackmaw Magic
        title = { "14:1114340910:454459928", "มนตร์แห่ง Blackmaw" },
        description = { "485:471513814:682647801", "เฟอร์โบลก์เผ่า Blackmaw ที่อยู่ตามภูเขาเหนือ Azshara ถูกเวทมืดชั่วร้ายทำให้แปดเปื้อน เรายังไม่รู้ว่ามลทินลามไปไกลแค่ไหนหรือมีผลต่อธาตุในพื้นที่อย่างไร แต่หวังว่าจะเข้าใจมันได้มากขึ้น\n\nเดินทางไปที่มั่น Blackmaw Hold แล้วนำ Blackmaw Ritual Totem กลับมาให้เราหนึ่งชิ้น มีเพียงชาแมนที่ทรงพลังที่สุดของ Blackmaw ที่พกมันอยู่ พาพันธมิตรไปด้วยและเตรียมรับศึกหนัก" },
        objective = { "51:245136373:969265424", "นำโทเทมพิธีกรรม Blackmaw ออกมาจาก Blackmaw Hold" },
    },
    [97327] = { -- Blackmaw Pouches
        title = { "16:312315657:740402459", "ถุงของชาว Blackmaw" },
        description = { "299:869974227:1099670234", "ข้าปวดใจที่ต้องยอมรับว่าพี่น้องของข้าใน Blackmaw Hold แปดเปื้อนเกินจะเยียวยา\n\nถ้าเจ้าเอาของใช้ส่วนตัวของพวกเขากลับมาได้ อย่างน้อยข้าก็ยังมอบของให้ครอบครัวเก็บไว้ระลึกถึงพวกเขา ทุกห่อที่เจ้านำกลับมาคือเครื่องหมายว่าเจ้าได้ช่วยคนของข้า" },
        objective = { "97:1176382816:1416903220", "เข้า Blackmaw Hold แล้วเก็บถุงของชาว Blackmaw 5 ใบไปให้ Ekkal ที่ซากเมือง Eldarath ใน Azshara", amount = { "32:49483545:1190608395 W1 64:1574367342:1577456805", "เข้า Blackmaw Hold แล้วเก็บถุงของชาว Blackmaw {world1} ใบไปให้ Ekkal ที่ซากเมือง Eldarath ใน Azshara" } },
    },
    [912] = { -- Stonesplinter Trogg Disguise
        title = { "28:545969580:182744431", "ปลอมตัวเป็นโทรก Stonesplinter" },
        description = { "5:814845730:1041320628 C 361:353649048:1809154421 N 1:63:63", "นี่ {class} ข้าลืมบอกไปก่อนหน้านี้ แต่ตัวแสบย่องเก่งอย่างเจ้าน่าจะเล่นงานค่าย Stonesplinter ได้หนักทีเดียว ถ้าแฝงตัวผ่านแนวของพวกมันเข้าไปได้ โชคดีของเจ้าเลย! ข้าศึกษาวิถีของพวกมันมาพักหนึ่งและรวบรวมสิ่งที่รู้ไว้ เผื่อคนใจกล้าจะใช้ฝ่าแนวพวกมันเข้าไปได้\n\nลองดูหน่อยไหม {name}?" },
    },
    [7961] = { -- Waskily Wabbits!
        title = { "16:57223912:791820153", "เจ้ากระต่ายตัวแสบ!" },
        description = { "75:1986679491:1870301587 N 23:18215821:1238388486", "กระต่ายพวกนี้ออกลูกออกหลานจนคุมไม่อยู่ ต้องทำอะไรสักอย่างแล้ว!\n\nช่วยพวกเราด้วย {name} เจ้าคือความหวังเดียวของเรา" },
        objective = { "73:1924858782:1005801456", "ฆ่ากระต่าย 5 ตัว แล้วกลับไปหา Jon LeCraft ที่เตาตีเหล็กบน Designer Island" },
    },
    [7962] = { -- Wabbit Pelts
        title = { "12:645540653:1520215730", "หนังกระต่าย" },
        description = { "83:1937733995:1818241551", "ข้าอยากได้หนังกระต่าย LeCrafty ไปหาจากพวก LeCrafty Rabbit มาให้ข้าหน่อย\n\nเรื่องนี้สำคัญนะ!" },
        objective = { "45:972471013:58702625", "นำ LeCrafty Rabbit Pelt 3 ผืนไปให้ Jon LeCraft" },
        required = { [19482] = { "19:547500665:3727827", "หนังแร็บบิต LeCraft" } },
        steps = { { "19:547500665:3727827", "หนังแร็บบิต LeCraft" } },
    },
    [94968] = { -- Eye of Mugg
        title = { "11:1411833122:1338288825", "ดวงตาของ Mugg" },
        description = { "262:260085145:118823864 N 97:36722596:114004664", "ในบรรดาคนไม่กี่คนที่แฝงเข้าไปในถ้ำได้ ส่วนใหญ่ตายกันหมด ดูเหมือนพวก Twilight จะตั้งหลักได้ใหญ่โตกว่าที่เราคิด เราจะยืนดูพวกสาวกลัทธิทำลายแผ่นดินและจับพันธมิตรของเราไปบูชายัญต่อไปไม่ได้ เราต้องจบเรื่องนี้เดี๋ยวนี้ {name}\n\nแทรกซึมเข้าไปในที่มั่น สังหารกองกำลังของมัน แล้วเอาหลักฐานว่าผู้นำของมันตายแล้วมาให้ข้า" },
        objective = { "91:843027451:939816938", "ลอบเข้า Krol'dok Stronghold แล้วกลับไปหา Krom'rosh พร้อมหลักฐานว่าผู้นำของพวกมันตายแล้ว" },
        completion = { "39:221186326:1689771091", "ให้สิ่งนี้เป็นสารจากเรา\nLok'tar!" },
        progress = { "28:1193975637:1668957885", "พบตัวผู้นำแล้วหรือยัง?" },
        required = { [267086] = { "11:1411833122:1338288825", "ดวงตาของ Mugg" } },
        steps = { { "11:1411833122:1338288825", "ดวงตาของ Mugg" } },
    },
    [94969] = { -- Krol'dok No More!
        title = { "17:806958884:64643546", "จบเรื่อง Krol'dok เสียที!" },
        description = { "125:1450880043:1773531934", "อย่าถามเลย ถึงเล่าไปเจ้าก็ไม่เชื่อ\n\nเอาเป็นว่าพาข้าออกไปจากที่นี่ก่อน! อ้อ เจ้าก็ต้องออกไปด้วยแน่นอน" },
        objective = { "32:912995515:983714990", "คุ้มกัน Marcus Tilwell ไปยังที่ปลอดภัย" },
    },
    [94972] = { -- Tome of Twilight
        title = { "16:568130767:1224221991", "คัมภีร์แห่ง Twilight" },
        description = { "285:2141265507:1418928160 N 22:2139730397:1771528607", "ตอนนี้เรารู้ที่ตั้งแล้ว ภายในที่มั่นนี้น่าจะมีความลับที่คนที่เราเจอมาจนถึงตอนนี้ไม่เคยล่วงรู้ ควรตามหาแล้วนำข้อมูลที่อาจช่วยให้เราสู้กับพวกสาวกลัทธิกลับมา\n\nลองดูว่าเจ้าสืบรู้อะไรได้บ้าง {name} ข้าจะรอเจ้ากลับมา" },
        objective = { "54:540299053:1202952054", "นำ Tome of Twilight กลับมาจาก Krol'dok Stronghold" },
        completion = { "148:874427558:217787632 N 31:970244170:1409527897", "อย่างที่ข้าคิด มีทั้งมนตร์ผนึกและรหัสเงา คงต้องใช้เวลากว่าจะไขความลับข้างในได้\nแต่สิ่งที่เจ้าทำช่วยข้ามากจริง ๆ {name} ข้าจะลงมือทันที" },
        progress = { "26:9954805:1776161257", "เจออะไรน่าสนใจไหม?" },
        required = { [267104] = { "16:568130767:1224221991", "คัมภีร์แห่ง Twilight" } },
        steps = { { "16:568130767:1224221991", "คัมภีร์แห่ง Twilight" } },
    },
    [94973] = { -- Krol'dok Moulding
        title = { "17:1373286179:766912234", "แม่พิมพ์ Krol'dok" },
        description = { "39:2033878506:1032303662", "<ดูเหมือนจะเป็นแม่พิมพ์สำหรับทำกุญแจ>" },
        objective = { "53:426317699:738406691", "ตามหาคนใน Rog'mar ที่อาจรู้เรื่องแม่พิมพ์นี้" },
        completion = { "16:1465897145:917542169 N 54:574146709:733846492", "สิ่งที่เจ้าพบน่าสนใจนะ {name} ถ้ามาจากป้อมนั่นก็คงสำคัญแน่" },
    },
    [94974] = { -- Key Ingredients
        title = { "15:176414716:1760166733", "วัสดุทำกุญแจ" },
        description = { "193:1934232470:820552653", "แม่พิมพ์ทำหยาบ ๆ แถมสึกไปมาก แต่เราอาจยังใช้ทำกุญแจได้\n\nการหาชิ้นส่วนที่ต้องใช้อาจกินเวลาหน่อย ข้าจะคอยเติมไฟให้ถ่านร้อนอยู่ ระหว่างที่เจ้าไปหาวัสดุ" },
        objective = { "6:1273960851:929420321 W1 19:1337872801:1782952380 W2 29:716763612:1296935822", "นำ Thick Leather {world1} ชิ้น และ Iron Bar {world2} แท่งไปให้ Kreza Darkthorn" },
        completion = { "51:814272387:157899986", "แม่พิมพ์น่าจะทนไหว มาดูกันว่าเราจะทำอะไรได้บ้าง" },
        progress = { "26:1390704574:2143299582", "ได้วัสดุมาแล้วหรือยัง?" },
        required = { [3575] = { "8:1010117764:989104521", "แท่งเหล็ก" }, [4304] = { "13:983336109:1264322130", "หนังหนา" } },
        steps = { { "8:1010117764:989104521", "แท่งเหล็ก" }, { "13:983336109:1264322130", "หนังหนา" } },
    },
    [94975] = { -- A Token of Vengeance
        title = { "20:347081575:1373598854", "หลักฐานแห่งการล้างแค้น" },
        description = { "31:1085948809:1967764875 N 407:483882146:2085670506", "งานของเราที่นี่ยังไม่จบ {name} พวกสาวกลัทธิทำให้พันธมิตรของเราเจ็บปวดเกินจะจินตนาการ ทั้งยังย่ำยีดินแดนนี้เพื่อยึดครอง\n\nเราจะไม่ทนให้มันทำแบบนี้อีกต่อไป\n\nทางเหนือมีเครือข่ายถ้ำซ่อนอยู่ในภูมิประเทศขรุขระ หน่วยสอดแนมของเราบอกว่าพวกสาวกเคลื่อนไหวกันในความมืด\n\nตามหาถ้ำนี้และหาที่ซ่อนของสาวก ได้เวลาฝากข้อความให้มันจำไปอีกนานแล้ว" },
        objective = { "8:1089852795:1107240600 W1 64:231278206:1750447813", "เก็บ Cultist Ear {world1} ชิ้นจากพวก Twilight's Hammer ใน Krol'dok Stronghold" },
        completion = { "43:347335074:1559476581", "นี่คือของขวัญจากศัตรูของเรา บัดนี้ข้ามอบให้เจ้า" },
        progress = { "32:675576954:1345005299", "การล้างแค้นที่สาสมต้องก่อกำเนิดจากเลือด" },
        required = { [267091] = { "11:1702700476:59758047", "หูของสมาชิกลัทธิ" } },
        objectiveLabels = {
            item = { ["Cultist Ear"] = "หูของสมาชิกลัทธิ" },
        },
    },
    [94980] = { -- Krol'dok Moulding
        title = { "17:1373286179:766912234", "แม่พิมพ์ Krol'dok" },
        description = { "39:2033878506:1032303662", "<ดูเหมือนจะเป็นแม่พิมพ์สำหรับทำกุญแจ>" },
        objective = { "59:1623909283:1405235972", "ตามหาคนใน Farholde Keep ที่อาจรู้เรื่องแม่พิมพ์นี้" },
        completion = { "53:461390892:287191468", "เจ้าเจอของดีเข้าแล้ว มาดูกันว่าเราจะทำอะไรได้บ้าง" },
    },
    [94981] = { -- Key Ingredients
        title = { "15:176414716:1760166733", "วัสดุทำกุญแจ" },
        description = { "167:769282258:1293422077", "แม่พิมพ์ค่อนข้างหยาบ แต่ถ้าได้วัสดุที่เหมาะ เราอาจใช้ทำกุญแจได้\n\nข้าจะคอยเติมไฟให้ถ่านร้อนอยู่ ระหว่างที่เจ้าไปหาชิ้นส่วนที่ต้องใช้" },
        objective = { "6:1273960851:929420321 W1 19:1337872801:1782952380 W2 29:274641971:1596515958", "นำ Thick Leather {world1} ชิ้น และ Iron Bar {world2} แท่งไปให้ Alphonse Dumas" },
        completion = { "20:179703407:953972437", "ตรงกับที่เราต้องการพอดี" },
        progress = { "32:1351907000:2000325655", "รวบรวมวัสดุได้แล้วหรือยัง?" },
        required = { [3575] = { "8:1010117764:989104521", "แท่งเหล็ก" }, [4304] = { "13:983336109:1264322130", "หนังหนา" } },
        steps = { { "8:1010117764:989104521", "แท่งเหล็ก" }, { "13:983336109:1264322130", "หนังหนา" } },
    },
    [94983] = { -- Twilight Mementos
        title = { "17:387196203:2072796171", "ของที่ระลึกจาก Twilight" },
        description = { "490:131832646:1330403575", "เรื่องที่หน่วยสอดแนมเล่ามาน่าสยดสยองทีเดียว ข้าจะละรายละเอียดโหด ๆ ไว้ สิ่งที่พบยืนยันรายงานก่อนหน้านี้ว่าพวกสาวกลัทธิมีที่ซ่อน\n\nทางเหนือมีถ้ำที่ซ่อนแนบเนียนกับภูมิประเทศ ถ้ำนั้นนำไปสู่... เอาเป็นว่าเป็นที่ที่เรายังแทรกซึมเข้าไปไม่ถึง เราคิดว่าเป็นฐานที่ตั้งอยู่ลึกเข้าไปในภูเขา\n\nถึงเวลาเอาคืนพวกสาวกลัทธิที่ทำร้ายพันธมิตรของเรา\n\nมุ่งหน้าไปทางเหนือ ตามหาศัตรู แล้วกลับมาพร้อมหลักฐานว่าพวกมันตายแล้ว" },
        objective = { "8:1089852795:1107240600 W1 67:1291900249:673533694", "เก็บ Cultist Bangle {world1} ชิ้นจากพวก Twilight's Hammer ใน Krol'dok Stronghold" },
        completion = { "216:385938935:1418161490", "สิ่งที่เจ้าพบน่าหนักใจ แล้วของพวกนี้... ลึกลับจริง ๆ... แปลกเหลือเกิน...\n<จ่า Riftan หยุดจ้องของที่ระลึกพวกนั้นอยู่ครู่หนึ่ง>\nมีบางอย่างมืดมนแฝงอยู่ในของพวกนี้ เป็นพลังอะไรสักอย่าง เจ้ารู้สึกไหม?" },
        progress = { "26:1502792828:1934603338", "ว่าไง? เจออะไรบ้าง?" },
        required = { [267234] = { "15:327036530:729083849", "กำไลของกลุ่ม Twilight" } },
        steps = { { "15:327036530:729083849", "กำไลของกลุ่ม Twilight" } },
    },
    [94997] = { -- Lingering Essence
        title = { "17:1154148634:820923494", "แก่นพลังที่ยังหลงเหลือ" },
        description = { "223:1817988296:1719297143", "เราเสียเวลาไม่ได้ เอาของพวกนี้ไปที่ป้อมเดี๋ยวนี้\n\nไปหา Ashe Amberhall นางอาจชวนปวดหัว แต่เป็นที่นับถือในสาขาที่ศึกษา นางอาจบอกได้บ้างว่าของพวกนี้กักพลังอะไรไว้" },
        objective = { "72:854144212:2056062058", "นำ Satchel of Cursed Mementos ไปให้ Ashe Amberhall ใน Farholde Keep" },
        completion = { "227:1143353594:1875691679", "Riftan ส่งเจ้ามารึ? ตาแก่นั่นสู้กับพวกลัทธิบ้า ๆ มานานจนข้ากังวลว่าความเหนื่อยล้าจะเริ่มกระทบความคิดเขาแล้ว\nอา ข้าพูดเรื่อยเปื่อยอีกแล้ว ขอโทษที สิ่งที่เขากังวลอาจมีมูลก็ได้\nขอดูหน่อยว่าเจ้าเอาอะไรมา" },
    },
    [94998] = { -- Curios of Curiosity
        title = { "19:296084856:74299862", "ของแปลกชวนสงสัย" },
        description = { "413:1505821768:1103527248", "จริง ๆ แล้วสลายเวทได้ง่ายทีเดียว มันเป็นเศษที่เหลือจากอะไรสักอย่างแน่ ๆ แต่อะไรกันแน่ ข้าก็ไม่รู้\n\nข้าคงทำได้เท่านี้ เสียดายถ้าเจ้าคาดหวังมากกว่านี้ แต่... คิดอีกที ฝีมือทำของพวกนี้มีเอกลักษณ์ทีเดียว อาจมีประโยชน์อยู่บ้าง\n\nเอาไปให้ Melanie Sable บอกนางว่าข้าส่งเจ้ามา แล้วบอกด้วยว่าของพวกนี้ปลอดภัย\n\nนางอาจยังเอาไปใช้ได้" },
        objective = { "47:1871438644:1797436853", "นำ Satchel of Mementos ไปให้ Melanie Sable" },
        completion = { "258:964047385:66653249", "งานฝีมือของพวกนี้ละเอียดน่าทึ่งจริง ๆ เสียดายถ้าจะปล่อยทิ้งไปเปล่า ๆ\nเอาอย่างนี้ ถ้าให้ข้าดูใกล้ ๆ ข้าอาจทำอะไรที่ใช้ประโยชน์ได้ ข้าขอแค่เก็บไว้ชิ้นหนึ่งเพื่อศึกษาต่อ" },
    },
    [95262] = { -- The Secret Prison
        title = { "17:1232245006:748609176", "เรือนจำลับ" },
        description = { "317:1510963039:938072299", "ข้าไม่เคยนึกถึง Alcaz เท่าไร จากที่รู้มันก็เป็นแค่ด่านร้างจากสงครามครั้งที่สาม ไม่ได้สำคัญอะไร ไม่เคยได้ยินด้วยว่ามีเรือนจำอยู่ที่นั่น\n\nเอาเถอะ คงต้องหาทางให้เจ้าเข้าไปดูเอง โดยเฉพาะถ้ามีโอกาสที่กษัตริย์จะอยู่ในนั้น" },
        objective = { "66:1610263986:1865054964", "เข้าไปใน Alcaz Prison แล้วสืบว่าเกิดอะไรขึ้นกับกษัตริย์แห่ง Stormwind" },
        steps = { { "20:1629210225:741411108", "สำรวจ Alcaz Prison" }, { "33:678719431:669397652", "สืบว่าเกิดอะไรขึ้นกับ Varian Wrynn" } },
    },
    [95263] = { -- Somber News
        title = { "11:73396250:1680859113", "ข่าวอันโศกเศร้า" },
        description = { "226:1729170444:521227131", "<กษัตริย์สิ้นพระชนม์แล้ว ถูกสังหารขณะพยายามหลบหนีก่อนพวกนากาบุกไม่นาน นี่เป็นข่าวร้ายแรงที่จะสั่นคลอน Stormwind ถึงรากฐาน เจ้าต้องกลับไปบอก Sully ว่าพบอะไรโดยเร็วที่สุด>" },
        objective = { "45:888717901:1817910710", "กลับไปหา Sully McCleary ที่ Dustwallow Marsh" },
    },
    [95264] = { -- Shaw Needs To Know
        title = { "18:84851098:646553332", "Shaw ต้องรู้เรื่องนี้" },
        description = { "198:587390968:2117009153", "Shaw ต้องรู้เรื่องนี้โดยเร็วที่สุด กลับไป Stormwind แล้วแจ้งข่าวให้เขา ข้าขอร้อง อย่าบอกใครอีก เรื่องนี้อาจเป็นภัยใหญ่หลวงต่อ Stormwind ต้องจัดการอย่างระมัดระวัง" },
        objective = { "45:1797752926:1063234452", "นำข่าวไปแจ้ง Matthias Shaw ที่ Stormwind" },
    },
    [95309] = { -- No Orc Left Behind
        title = { "18:647535450:1293088410", "จะไม่ทิ้งออร์คไว้ข้างหลัง" },
        description = { "314:1614067030:116843238", "คำสั่งมีแค่นี้ ลงไปในคุกใต้ป้อมแล้วตามหา Commander Folkar ถ้าเขายังมีชีวิตอยู่ก็ปล่อยเขาออกมา แล้วสืบให้ได้มากที่สุดว่ามันเกิดเรื่องบ้าอะไรขึ้นที่นี่\n\nมีกองทัพรอเจ้าอยู่ข้างล่าง ลงไปคนเดียวไม่รอดแน่ หวังว่าเจ้าจะมีพวกไปด้วย ยิ่งแข็งแกร่งยิ่งดี" },
        objective = { "49:369463512:1927435248", "เข้าไปใน Alcaz Prison แล้วตามหา Commander Folkar" },
    },
    [95454] = { -- The Honor of the Kor'kron
        title = { "25:1887195519:856215000", "เกียรติแห่ง Kor'kron" },
        description = { "492:67827817:882041548", "แขนข้างที่ข้าใช้เหวี่ยงขวานหัก ทหารชั้นยอดของข้าก็ตายไปเกือบหมด ตอนนี้เกียรติของ Kor'kron อยู่ในมือเจ้าแล้ว\n\nเราถูกส่งมาพานักโทษออกไป และเป็นนักโทษคนสำคัญ... เรามารับ Varian Wrynn กษัตริย์แห่ง Stormwind เราดักข่าวได้ว่าเขาถูกขังอยู่ที่นี่ จอมทัพของเราจึงสั่งให้พาเขากลับ Orgrimmar ทั้งเป็น การที่มังกรดำอยู่ที่นี่ทำให้เรื่อง... ยุ่งขึ้น\n\nข้าต้องให้เจ้ารุดหน้าไปตามหา Wrynn ข้าจะรอตรงนี้ระหว่างที่เจ้าค้นหา" },
        objective = { "43:1134791047:2128522776", "ตามหากษัตริย์ Varian Wrynn ใน Alcaz Prison" },
    },
    [95483] = { -- Thrall Needs to Know
        title = { "20:2094798945:2104221557", "Thrall ต้องรู้เรื่องนี้" },
        description = { "290:30642825:1754307115", "Thrall ต้องรู้ว่าเกิดอะไรขึ้นที่นี่ ข้าจะไปสมทบกับ Ulka และดูให้แน่ใจว่าเขาเดินทางไหวก่อนกลับ Orgrimmar ข้าจึงฝากเจ้านำข่าวนี้ไปแจ้งจอมทัพแทนข้า\n\nไปเถิด ทหารแห่งฮอร์ด บอกจอมทัพของเราว่า Varian Wrynn พบจุดจบอย่างไร" },
        objective = { "57:2101887999:1943164384", "นำข่าวชะตากรรมของ Varian Wrynn ไปแจ้ง Thrall ที่ Orgrimmar" },
    },
    [95790] = { -- Digestible Research
        title = { "19:1320273056:797380700", "งานวิจัยย่อยง่าย" },
        description = { "301:687168563:830553950", "<สมุดบันทึกเล่มนี้ดูเหมือนถูกฉีกเป็นชิ้น ๆ จากที่พออ่านได้ ดูจะเป็นบันทึกภาคสนามของนักผจญภัยผู้โชคร้ายคนหนึ่งจาก Explorers' League\n\nรอยกัดบนปกบอกว่าน่าจะเป็นฝีมือแรปเตอร์\n\nบางทีอาจตามหาหน้ากระดาษมาประกอบกันใหม่ได้>" },
        objective = { "70:95313774:1686590632", "รวบรวม Partially Digested Journal Page 15 แผ่นจาก Shaper's Terrace", amount = { "8:1089852795:1107240600 W1 60:1075877959:337755293", "รวบรวม Partially Digested Journal Page {world1} แผ่นจาก Shaper's Terrace" } },
    },
    [95799] = { -- Findings for the Explorer's League
        title = { "34:1822586999:2102394074", "ผลการค้นคว้าสำหรับ Explorers' League" },
        description = { "244:1222993506:1543048553", "ข้าต้องเขียนจดหมายถึงสหายที่ Explorers' League ใน Ironforge เดี๋ยวนี้ นี่เป็นการค้นพบครั้งประวัติศาสตร์\n\nเจ้าช่วยส่งจดหมายไป Ironforge ให้ข้าได้ไหม? ข้าจะคัดสำเนาคำแปลแผ่นจารึกให้เจ้าด้วย" },
        objective = { "78:57173545:804480748", "นำ I'lalai Translations ของ Loremaster Dibbs ไปให้ Historian Karnik ใน Ironforge" },
        completion = { "261:1191553081:885209054", "อา Loremaster Dibbs หาของน่าสนใจมาฝากข้าได้เสมอ ถึงข้าจะไม่ได้ศึกษาพวกโทรลล์โดยเฉพาะ แต่ก็เข้าใจดีว่าทำไมเขาถึงสนใจนัก\n\nนี่เป็นข่าวดีจริง ๆ ข้าจะรวบรวมคณะออกเดินทางไปยังนคร I'lalai ที่สาบสูญทันที!" },
    },
    [95924] = { -- Panic at the Digsite
        title = { "20:1936886290:1891735916", "โกลาหลที่แหล่งขุดค้น" },
        description = { "346:1072090660:379858958", "เจ้านั่นแหละ! ใช่ ข้าพูดกับเจ้า! เราเจอสิ่งที่ครั้งหนึ่งในชีวิตจะได้พบที่ Un'Goro เชื่อไหม?\n\nติดอยู่อย่างเดียว... แหล่งขุดของเราโดนสัตว์ตะกละที่ชอบไล่ฆ่าคนยึดไปแล้ว ไม่น่ารื่นรมย์เลยจริง ๆ\n\nถ้าเจ้าช่วย เราจะทวงค่ายคืนแล้วกลับไปทำงานได้ ว่าไงล่ะ? ข้าจะตอบแทนให้คุ้มเวลา" },
        objective = { "84:1648535271:1499705260", "สังหารแม่ฝูงราวาซอร์ 6 ตัว ราวาซอร์หนังเหล็ก 9 ตัว และ Venomridge ใน Shaper's Terrace" },
    },
    [95925] = { -- Mapping the Way Forward
        title = { "23:1901946533:381310857", "ทำแผนที่ทางข้างหน้า" },
        description = { "C 485:493236157:2084505746", "{class} เราค้นพบสิ่งที่ครั้งหนึ่งในชีวิตจะได้พบ! ข้าแทบไม่เชื่อเลย ซากโบราณใน Un'Goro เปิดแล้ว!\n\nเราส่งทีมเข้าไปแล้ว แต่พวกเขาเจอ... ปัญหา ถ้าเจ้าจะเข้าไปอยู่แล้ว ช่วยทำแผนที่นี้ให้เสร็จได้ไหม?\n\nได้ยินว่าข้างในมี Achromatic Crystal แล้วก็มีผู้เฝ้าที่เพิ่งขุดพบอยู่แถว Western Gate บานมหึมา ฟังดูน่าสนใจทีเดียว\n\nจุดสังเกตอื่นที่ควรลงไว้คือ Pillar of Assimilation, Western Gate และ Regrowth Vestibule" },
        objective = { "87:235542563:1500100367", "ตามหาจุดสำคัญใน Shaper's Terrace แล้วบันทึกแต่ละจุดลงในแผนที่นักสำรวจ" },
    },
    [95926] = { -- The Dark Crystal
        title = { "16:2074947278:2082443513", "ผลึกมืด" },
        description = { "482:914189259:713062151", "เจ้านั่น! ข้ามีงานให้คนที่มี... ฝีมืออย่างเจ้า\n\nสายข่าวบอกว่าพบผลึกใน Shaper's Terrace ที่ดูดพลังธาตุรอบตัวได้ หรืออาจดูดแก่นชีวิตได้ด้วย รายงานยังไม่ชัด\n\nข้าต้องได้เศษผลึกนั้นสักชิ้น! ลองคิดดูว่าวัตถุทรงพลังขนาดนั้นจะเอาไปใช้อะไรได้บ้าง\n\nไปที่ Shaper's Terrace แล้วเอาตัวอย่าง Achromatic Crystal ไร้สีนี้กลับมา ข้าจะให้รางวัลตอบแทน" },
        objective = { "96:213472402:201335219", "เก็บเศษผลึกไร้สีที่ถูกดูดพลังใกล้ผลึกไร้สีขนาดใหญ่ใน Shaper's Terrace" },
    },
    [95928] = { -- Crystalline Elements
        title = { "20:1507728250:580258939", "ธาตุในผลึก" },
        description = { "35:1597630814:67186622 C 454:1569840142:451822770", "อา ดีแล้วที่เจ้ามา {class}\n\nช่วงนี้ข้าศึกษาผลึกอยู่ และได้ข่าวว่ามีผลึกประหลาดชุดหนึ่งมาจาก Un'Goro Crater ข้ามีตัวอย่างแบบพื้นฐานแล้ว แต่ได้ยินว่ามีผลึกใหญ่กว่าและทรงพลังกว่าที่ Shaper's Terrace\n\nข้าไม่รู้เรื่องที่นั่นมากนัก รู้เพียงว่ามีผลึกที่ว่ากันว่าบรรจุธาตุอยู่จริง ๆ ถ้าเจ้าไปถึงที่นั่น ช่วยเอาตัวอย่างมาสีละชิ้น" },
        objective = { "121:2041145904:794576457", "นำผลึกชุ่มน้ำ ผลึกประจุไฟ ผลึกพิษ และผลึกเพลิงจาก Shaper's Terrace ไปให้ Mayena Earthseeker" },
    },
    [96332] = { -- A Little Payback
        title = { "16:1479386906:1542004541", "เอาคืนสักหน่อย" },
        description = { "426:1660206785:544921774", "ตอนเราถอย พวกนากากำลังยกมาที่ป้อมเป็นระลอกที่สอง ข้าคิดว่าข้างในคงยังรบกันอยู่\n\nพวกเรา Kor'kron ใช้เลือดล้างเลือด ถ้าเจ้าจะเข้าไปอยู่แล้ว ฆ่านากาทุกตัวที่เห็น ข้าเห็นแม่มดอยู่ตัวหนึ่งในหมู่พวกมัน นั่นต้องเป็นหัวหน้าแน่ เอาหัวของนางมาให้ข้า\n\nวันนี้เราเสียออร์คดี ๆ ไปมาก ข้าคงไม่สบายใจหากเราไม่ได้เอาคืนให้สาสม" },
        objective = { "32:1167003672:1195353156 W1 21:1309036862:1369772622 W2 85:386987626:875232456", "เข้าไปใน Alcaz Prison กำจัด Strashasz Soldier {world1} ตัวและ Strashaz Enchantress {world2} ตัว แล้วนำศีรษะของ Tidemistress Ca'zass ไปให้ Sergeant Ulka" },
        required = { [273883] = { "14:1144429707:1844731793", "ศีรษะของ Ca'zass" } },
        objectiveLabels = {
            item = { ["Ca'zass's Head"] = "ศีรษะของ Ca'zass" },
        },
    },
    [96334] = { -- Blood Red Bandanas
        title = { "18:359643079:1826444184", "ผ้าโพกสีเลือด" },
        description = { "402:728274308:609336536", "มนุษย์ส่วนใหญ่ที่เราสู้ด้วยสวมผ้าโพกสีแดงเลือด ข้าจำได้ว่าเคยได้ยินเรื่องกลุ่มอาชญากรใน Eastern Kingdoms ชื่อ Defias Brotherhood ที่ขึ้นชื่อเรื่องผ้าปิดหน้าสีแดง ข้าไม่รู้ว่าพวกมันมาทำอะไรใน Kalimdor แต่ถ้าเจอพวกมันก็ฆ่าเสีย แล้วนำผ้าปิดหน้าไปให้ Eitrigg ที่ Orgrimmar\n\nเขาจะตรวจได้ว่าเป็นของพวก Defias จริงหรือไม่" },
        objective = { "31:2087013145:417284440 W1 48:2142916727:540122506", "เข้าไปใน Alcaz Prison แล้วเก็บ Blood Red Bandana {world1} ผืนจากทหารยามมนุษย์ด้านใน" },
        required = { [274028] = { "17:1998475621:686055518", "ผ้าโพกหัวสีแดงเลือด" } },
        objectiveLabels = {
            item = { ["Blood Red Bandana"] = "ผ้าโพกหัวสีแดงเลือด" },
        },
    },
    [96335] = { -- The Man in the Iron Chains
        title = { "26:973969553:1226721574", "ชายในตรวนเหล็ก" },
        description = { "409:729460559:1181160568", "โห สุดยอดเลย! ที่เจ้าล้มมังกรนั่นได้ช่างน่าทึ่งจริง ๆ!\n\nไหน ๆ ก็อยู่ตรงนี้แล้ว... พอจะช่วยปลดลูกตุ้มกับโซ่นี่ให้ข้าได้ไหม?\n\nถ้ามันยังไม่หนีหรือถูกฆ่า คนทรมานที่พวกเขาเรียกว่า The Questioner น่าจะมีกุญแจปลดตรวน เอากุญแจจากเจ้าคนวิปริตนั่นมาให้ข้า\n\nถ้าทำได้ ข้ารับปากว่าจะตอบแทนให้คุ้มแรงแน่" },
        objective = { "66:583185736:372413368", "เอากุญแจไขตรวน Alcaz จาก The Questioner ใน Alcaz Prison" },
    },
    [96369] = { -- Bad News for Folkar
        title = { "19:347283649:1566501962", "ข่าวร้ายสำหรับ Folkar" },
        description = { "270:1554538680:685940459", "<กษัตริย์สิ้นพระชนม์แล้ว ถูกสังหารขณะพยายามหลบหนีก่อนพวกนากาบุกไม่นาน ทหาร Kor'kron หลายคนต้องตายเพื่อให้ได้ข่าวนี้ แต่มันอาจสั่นคลอนฝ่ายพันธมิตรถึงรากฐาน เจ้าต้องกลับไปบอก Commander Folkar ว่าพบอะไรโดยเร็วที่สุด>" },
        objective = { "32:2058505088:1902215516", "กลับไปรายงาน Commander Folkar" },
    },
    [96379] = { -- State Secrets
        title = { "13:2107584286:1621611443", "ความลับของรัฐ" },
        description = { "265:291930116:418846620", "<เจ้าคิดได้ว่ากอบลินที่ทำธุรกิจตามเอาทรัพย์สินคืนอาจอยากเห็นเอกสารที่เจ้าได้มาจาก Westfall ลองถามเขาว่าพอจะเข้าใจเอกสารพวกนี้บ้างไหม ที่สำคัญกว่านั้นคือเขายอมจ่ายเท่าไรถึงจะได้มันไป>" },
    },
    [96381] = { -- A Bit of Wet Work
        title = { "17:1420407230:1485628995", "งานเปื้อนเลือดริมฝั่ง" },
        description = { "442:1904739818:402793614", "ข้าใช้กล้องส่องทางไกลคู่ใจส่องชายฝั่ง Alcaz ตอนเจ้าไปแอบฟัง Lady Proudmoore ข้าว่าเกาะอาจกำลังถูกโจมตี ข้าเห็นนากาตั้งเยอะกรูกันขึ้นฝั่ง\n\nถ้าเป็นพวกนากาละก็ ศัตรูของศัตรูไม่ได้เป็นมิตรกับข้าแน่ ๆ ทำประโยชน์ให้โลกด้วยการจัดการพวกมันสักหน่อย ข้ายังเห็นตัวที่ดูเหมือนหัวหน้า เป็นพวกใช้เวทที่ตะโกนสั่งคนอื่น ถ้าทำได้ก็จัดการนางด้วย" },
        objective = { "142:1484893860:1503343415", "เข้า Alcaz Prison แล้วสังหารทหาร Strashaz 15 นายกับนางมนตรา Strashaz 8 ตน จากนั้นนำหัวของ Tidemistress Ca'zass ไปให้ Sully McCleary", amount = { "32:1167003672:1195353156 W1 21:1309036862:1369772622 W2 86:2140451502:952849555", "เข้า Alcaz Prison แล้วสังหารทหาร Strashaz {world1} นายกับนางมนตรา Strashaz {world2} ตน จากนั้นนำหัวของ Tidemistress Ca'zass ไปให้ Sully McCleary" } },
    },
    [96622] = { -- A Rest Without Pain
        title = { "19:788983825:1298007933", "พักอย่างไร้ความเจ็บปวด" },
        description = { "471:1813205728:2013002374", "สหาย ไหน ๆ เจ้าก็อยู่ตรงนี้ ข้าขออีกอย่างเป็นครั้งสุดท้ายได้ไหม ช่วยเอายาพอกที่ข้าทำไปให้เพื่อนข้าสองคนในค่ายที\n\nEnho อยู่ในเรือนพยาบาลทางซ้าย เขาอ่อนแรงมาก แต่ข้ายังหวังว่าเขาจะสู้กับการติดเชื้อไหว ข้าคอยป้อนน้ำซุปให้ทีละช้อนเพื่อช่วยให้เขามีแรงขึ้น\n\nอีกคนคือ Maruke\n\n<Ortak ก้มหน้าเงียบไปครู่หนึ่ง>\n\nเจ้าจะพบนางทางเหนือของที่นี่ ตรงที่เราเลี้ยงสัตว์ขี่ไม่กี่ตัวที่ยังเหลืออยู่" },
        objective = { "55:308830117:158360227", "นำ Hyjal Silphium Poultice ไปให้ Enho และ Maruke" },
    },
    [96674] = { -- Ewe Wandered Off
        title = { "16:1246866473:2111319917", "เจ้าแกะเดินหลง" },
        description = { "495:1751350879:1639191669", "<Mirt เบิกตากว้างเมื่อเจ้าเดินเข้าไปใกล้>\n\nโห เจ้าเป็นใครน่ะ? แม่ข้าบอกว่ามีคนใหม่มาที่นี่ บอกว่าเจ้าฆ่าพวก Scourge ไปตั้งเยอะและแข็งแรงสุด ๆ! เคยสู้กับหมีไหม? ฮ้า! แล้วมังกรล่ะ!? ข้า...\n\n<Mirt หันมองข้างหลัง แล้วทำท่ากระมิดกระเมี้ยน>\n\nบางที... เจ้าช่วยข้าได้ไหม? ข้าต้องเฝ้าแกะ แต่พวกมันออกไปตอนข้าปั้นมังกรดินโคลน มันอยู่ทางโน้น ข้าไปไม่ได้ แม่บอกว่าพวกมันอาจทำข้าเจ็บ เจ้าช่วยไปตามหาแกะได้ไหม?" },
        objective = { "35:1021738621:453715517", "จับ Escaped Sheep 6 ตัวแล้วพากลับมา", amount = { "19:1577080080:819124186 W1 15:312127102:1410026500", "จับ Escaped Sheep {world1} ตัวแล้วพากลับมา" } },
    },
    [1288] = { -- Vimes's Report
        title = { "14:1771829492:1168919294", "รายงานของ Vimes" },
        description = { "28:703784238:1100609437 N 342:2031370338:513156237", "เจ้าทำงานได้ดีทีเดียว {name} ดีที่สุดที่ข้าเคยเห็นจากมือสมัครเล่น\n\nLady Proudmoore ขอให้ข้ารายงานความคืบหน้าของเรื่องละเอียดอ่อนนี้ แต่ข้าไม่ได้คุยกับนางมาพักหนึ่งแล้ว\n\nเดิมทีข้าจะเอารายงานไปให้นางทีหลัง แต่ดูเหมาะกว่าถ้าเจ้าเป็นคนไปคุยเรื่องนี้ เจ้าน่าจะตอบคำถามของนางได้ดีกว่าข้า" },
        objective = { "59:1602121450:87236556", "นำรายงานของ Vimes (Vimes's Report) ไปให้ Lady Jaina Proudmoore ใน Theramore" },
    },
    [7702] = { -- Kill 'Em With Sleep Deprivation
        title = { "31:1521510455:1560318599", "เล่นงานพวกมันให้อดนอน" },
        description = { "315:488972743:142652769 N 93:524866589:1245494204", "ถ้าอยากให้กองกำลัง Dark Iron ที่ทำงานใน Slag Pit ทำงานได้น้อยลง เราก็ต้องเล่นงานจุดที่มันจะเจ็บที่สุด\n\nมีเรื่องหนึ่งที่ไม่ค่อยมีใครรู้ คนแคระต้องพักผ่อน โดยเฉพาะพวก Dark Iron! ต้องพักเยอะด้วย!\n\nข้าถามหน่อยเถอะ ไม่มีหมอนแล้วมันจะนอนกันยังไง? ใช่แล้ว {name} มันนอนไม่ได้ นั่นแหละเหตุผลที่เจ้าต้องแอบเข้า Slag Pit ไปขโมยหมอนพวกมัน" },
    },
    [90107] = { -- The Blade Reformed
        title = { "18:1153788879:1612062070", "ตีดาบขึ้นใหม่" },
        description = { "252:2103261719:1689330066", "ข้าว่าปรับโลหะผสมได้ที่แล้ว ตอนนี้เอาไปตีเป็นแท่งตั้งต้นสำหรับทำใบดาบได้อย่างมั่นใจ โชคดีที่วัตถุดิบมีเหลือเฟือจากที่เจ้าหามาให้ข้าจนถึงตอนนี้\n\nถอยไปหน่อย งานหน้าเตาตีเหล็กอาจ... หวือหวาเอาเรื่อง" },
        objective = { "94:457818700:1481798295", "ถอยออกมาขณะที่นายช่าง Omarion พยายามตีใบดาบ Ashbringer ขึ้นใหม่" },
        completion = { "458:746831939:111469989", "เสร็จแล้ว ถึงโลหะผสมที่ข้าหลอมด้วยแสงจะเกิดจากเวทศักดิ์สิทธิ์ ตอนนี้มันก็ยังเป็นเพียงใบดาบธรรมดา การนำชิ้นส่วนที่เหลือมาประกอบเข้าด้วยกันเป็นหน้าที่ของเจ้ากับสหายที่เป็นวิญญาณของเจ้า\n\nข้าไม่ได้รู้สึกภูมิใจในงานของตัวเองแบบนี้มานาน แต่ต้องยอมรับว่าข้าสังหรณ์ใจไม่ดี หรือบางทีเราควรปล่อยให้ Ashbringer แตกหักอยู่อย่างนั้น เรื่องนี้รู้สึกผิดแปลก ราวกับว่ามันไม่ควรเกิดขึ้นเลย" },
    },
    [90506] = { -- Take Their Breath Away
        title = { "22:1631668479:854984398", "ชิงลมหายใจ" },
        description = { "494:1506966260:1512604736", "ข้าติดต่อกับ Evie Whirlbrew เพื่อหาเสบียงสำคัญ แต่นางต่อรองหนักและไม่ยอมอ่อนข้อ ยืนกรานว่าจะแลกกับ Nivifacient Gland จากพวกมังกรสีน้ำเงินเท่านั้น ต่อมนี้ทำให้เผ่ามังกรสีน้ำเงินพ่นลมหายใจเยือกแข็งได้ และมีคุณสมบัติพิเศษทางการเล่นแร่แปรธาตุหลายอย่าง\n\nทางใต้ที่ Mazthoril มีมังกรสีน้ำเงินดุร้ายอยู่กลุ่มหนึ่ง ข้าอยากให้เจ้าช่วยไปหาต่อมมาให้หน่อย จะได้เอาไปแลกกับแม่ค้าหน้าเลือดนั่น" },
        objective = { "89:916012812:797164045", "เก็บต่อม Nivifacient 10 ชิ้นจากเผ่าพันธุ์มังกรสีน้ำเงินที่ Mazthoril ทางใต้ของ Everlook" },
    },
    [90507] = { -- Logistics Challenges
        title = { "20:15797292:36492124", "ปัญหาขนส่งเสบียง" },
        description = { "303:1763371825:1159661075", "ข้าตกลงกับ Azzleby มานานแล้ว ให้ใช้สัตว์บรรทุกของเขาขนเสบียงผ่านช่องเขา ช่วงนี้พวกเฟอร์โบลก์ Winterfall คอยปล้นกองคาราวานแล้วขโมยของเราไป!\n\nค้นค่าย Winterfall ที่นี่ใน Winterspring หาเสบียงที่หายไปของเรา" },
    },
    [90508] = { -- As The Crow Flies
        title = { "17:614953590:2113684856", "ตามทางที่อีกาบิน" },
        description = { "449:453069184:81593039", "ข้าควรไปปรึกษา Master Omnuron เรื่องนี้ก่อน แต่เจ้าช่วยดรูอิดแห่งกรงเล็บไว้มาก ข้าจะยอมเสี่ยงสักครั้ง เขาคงเข้าใจ\n\nยังไงขอให้ยกโทษทีหลังก็ง่ายกว่าขออนุญาตก่อนอยู่แล้ว!\n\nเราไปกันเดี๋ยวนี้ เจ้าดูเส้นทางที่เราใช้เลี่ยงอาคมคุ้มกันไม่ได้ ข้าจึงต้องบังสายตาเจ้า แค่นี้ก็ขาดความรับผิดชอบพอแล้ว ข้าเปิดเผยความลับของดรูอิดแห่งกรงเล็บไม่ได้เด็ดขาด" },
    },
    [90559] = { -- The Tempering
        title = { "13:523261939:1192121408", "ชุบใบดาบ" },
        description = { "399:2003628369:625110752", "<กิ่งของ Nordrassil ให้ไฟที่ต่างจากทุกอย่างที่เจ้าเคยเห็น ราวกับมันมีเจตจำนงและปัญญาของตนเอง เจ้าไม่แน่ใจนัก แต่สาบานได้ว่าเปลวไฟดูจะรู้ว่าเจ้าอยู่ตรงนี้ และกำลังมองเจ้าอย่างใคร่รู้>\n\n<แม้จะชวนให้ไม่สบายใจ แต่ที่เหลือก็แค่เผาใบดาบให้ร้อนแล้วจุ่มลงในน้ำของ Well of Eternity>" },
        objective = { "220:1735927331:1387374987", "เผาดาบ Ashbringer ที่ยังไร้พลังในกองไฟที่ค่ายดรูอิดร้างทางใต้ของ Nordrassil แล้วจุ่มใบดาบที่ร้อนลงในน้ำของ Well of Eternity เมื่อเสร็จแล้วให้คุยกับ The Will of the Ashbringer" },
    },
    [91548] = { -- Vek'zol
        title = { "7:170222743:1258456666", "Vek'zol" },
        description = { "499:92271383:646220215", "ข้าพูดภาษา Thalassian ไม่ได้ แต่คุ้นกับแผนภาพพวกนี้\n\nเมื่อรู้ว่าบลัดเอลฟ์เสพติดมานา ข้าว่าพวกมันคงพยายามอัญเชิญปีศาจเพื่อสูบเวทเฟลจากตัวมัน\n\nแค่เสพพลังแรงขนาดนั้นไปเปล่า ๆ น่าเสียดาย เราเอามาใช้ทำสิ่งที่ยิ่งใหญ่กว่านั้นได้\n\n<Zevrost คั่นหน้าไว้ในคัมภีร์>\n\nมี Altar of Storms อยู่ใน Blasted Lands ทำพิธีนี้ที่นั่นเพื่ออัญเชิญปีศาจ Vek'zol หัวใจมันจะเป็นวัตถุดิบชั้นดี ลองคิดดูว่าเราจะมีพลังมากเพียงใด!" },
        objective = { "150:1608383347:613913021", "ใช้ Sin'dorei Tome of Summoning อัญเชิญ Vek'zol ที่ Altar of Storms ใน Blasted Lands แล้วนำ Heart of Vek'zol ไปให้ Zevrost ที่ Orgrimmar" },
        required = { [246780] = { "16:1998407624:1127900189", "หัวใจของ Vek'zol" } },
        objectiveLabels = {
            item = { ["Heart of Vek'zol"] = "หัวใจของ Vek'zol" },
        },
    },
    [91882] = { -- The Grand Alliance
        title = { "18:519999951:709365662", "มหาพันธมิตร" },
        description = { "476:928844759:269332044", "หลายปีก่อน ฮอร์ดกับพันธมิตรวางความขัดแย้งไว้ชั่วคราวเพื่อต่อกรกับภัยที่ใหญ่กว่า นั่นคือ Legion กองกำลังมหาพันธมิตรสกัด Archimonde และสมุนไว้ได้ที่ Mount Hyjal\n\nแต่การถอยลงจากภูเขาอันตรายมาก นักสู้ผู้กล้าบางคนถูกทิ้งไว้ข้างหลัง\n\nตอนนี้ทางขึ้นภูเขาเปิดอีกครั้ง วีรชนบางคนอาจยังมีชีวิตอยู่ในป่า ไปที่ Mount Hyjal ฝ่าภัยที่นั่น แล้วสืบว่าเกิดอะไรขึ้นกับกองกำลังของเรา" },
        objective = { "54:781267119:1889665762", "ออกตามหากองกำลังมหาพันธมิตรที่ยังเหลืออยู่บน Mount Hyjal" },
    },
    [93163] = { -- Heart of the Obliterator
        title = { "24:1470784924:1102864082", "หัวใจของผู้ทำลายล้าง" },
        description = { "251:204978670:535538688", "ถูกสร้างขึ้นมาและพังลงอีกครั้ง ตอนนี้หัวใจของ Iodax the Obliterator อยู่ในมือเจ้า โกเลมตนนี้น่าจะเป็นสิ่งประดิษฐ์ของคนแคระ Dark Iron หรือของอะไรที่มาก่อนพวกเขา คนแคระที่ Thorium Point อาจสนใจสิ่งที่เจ้าพบ" },
        objective = { "52:1146384299:1228055266", "นำ Heart of the Obliterator ไปที่ Thorium Point" },
    },
    [93572] = { -- To Serve The Draenei
        title = { "20:1342849705:2119811435", "ช่วยเหล่าดราไน" },
        description = { "423:563465415:1546548009 R 1:63:63", "เจ้าอาจเอาลูกแก้ว Draenethyst มาให้ Kum'isha ได้ แต่นั่นแสดงแค่ว่าเจ้าโชคดี ถ้าอยากได้รางวัล จงช่วยพี่น้องของ Kum'isha กลับบ้าน\n\nKum'isha จะใช้ลูกแก้วนี้เปิดรอยแยกให้ดราไนคนอื่นผ่านไป ถ้ามีภัยอะไรโผล่ออกมา เจ้าต้องสู้กับมัน ถ้าพี่น้องของ Kum'isha เป็นอันตรายแม้แต่คนเดียว ก็ลืมเรื่องรางวัลได้เลย\n\nพร้อมหรือยัง ชาว{race}?" },
        objective = { "107:841847705:19295961", "คุ้มกันผู้ลี้ภัยดราไนขณะเดินผ่านรอยแยกของ Kum'isha ไปยัง Outland ห้ามให้ผู้ลี้ภัยเสียชีวิตแม้แต่คนเดียว" },
        objectiveLabels = {
            event = { ["Protect the draenei refugees as they pass through Kum'isha's rift"] = "คุ้มกันผู้ลี้ภัยชาวดราไนขณะผ่านรอยแยกของ Kum'isha" },
        },
    },
    [93684] = { -- The Found One
        title = { "13:1397686583:658525670", "ผู้ที่ถูกพบ" },
        description = { "372:967573012:1753169558 N 49:1596760110:1437353015", "ข้าไม่รู้จักชุมชนอื่นที่เหมือนของเรา แต่เคยเห็นพวก Lost One ทางใต้ใน Blasted Lands พวกนั้นเหมือนพวกที่ Fallow Sanctuary ทั้งดุร้ายและไร้สติ ข้าเคยคิดว่าชะตานั้นคงตกแก่เผ่าพันธุ์เราทุกคนที่อยู่ที่นั่น\n\nแต่ถ้านิมิตของ Onku ชี้ว่ามีดราไนคนหนึ่งเดินอยู่ตามแดนร้างเพียงลำพัง ข้าก็อาจคิดผิด\n\nข้าขอแรงเจ้าอีกครั้ง {name} ตามหาดราไนคนนั้นแล้วช่วยเท่าที่เจ้าทำได้" },
        objective = { "64:391937600:1779567356", "ตามหาดราไนที่กำลังค้นหา draenethyst ใน Blasted Lands" },
    },
    [93685] = { -- To Serve Kum'isha
        title = { "17:1824435120:2065874272", "รับใช้ Kum'isha" },
        description = { "84:1289597489:613653064 R 231:1365544384:1018466860 R 184:736043189:1067598493", "สมองอันน้อยนิดของเจ้าพอจะเข้าใจไหมว่าลูกแก้ว Draenethyst ไร้ตำหนิหายากเพียงใด ชาว{race}? ดราไนบางคนใช้เวลาทั้งชีวิตตามหาผลึกแบบนี้สักลูก สุดท้ายกลับพบจุดจบสยองโดยทำไม่สำเร็จ\n\nเจ้ารู้แล้วว่า Kum'isha ขออะไร แต่ยังมายืนตรงนี้และอยากช่วยอยู่หรือ? ก็ได้ ชาว{race}... หากเดินทางผ่านดินแดนนี้แล้วพบลูกแก้ว Draenethyst ไร้ตำหนิเมื่อใด จงเอากลับมาให้ข้า ข้าจะให้ทรัพย์สมบัติมากเกินกว่าที่เจ้ากล้าฝัน" },
        objective = { "241:1137939890:689406453", "หา Flawless Draenethyst Sphere ใน Blasted Lands แล้วนำไปให้ Kum'isha the Collector\n\nขอเตือนไว้ก่อนว่าผลึกนี้เป็นหนึ่งในผลึกที่หายากที่สุดใน Azeroth สิ่งมีชีวิตตัวไหนในดินแดนนี้ก็อาจมี Flawless Draenethyst Sphere อยู่กับตัว" },
        required = { [8244] = { "27:727213447:451364398", "ลูกแก้ว Draenethyst ไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Flawless Draenethyst Sphere"] = "ลูกแก้ว Draenethyst ไร้ตำหนิ" },
        },
    },
    [95194] = { -- Our Man in Theramore
        title = { "20:1991171846:2074575015", "สายของเราใน Theramore" },
        description = { "11:927657569:725753248 N 481:2134211789:717577737", "สวัสดี {name} SI:7 มีเรื่องอยากให้เจ้าช่วย คนของเราที่ Theramore Isle แจ้งว่านาวิกโยธินของ Jaina Proudmoore เพิ่งพาชายคนหนึ่งที่ถูกคลื่นซัดมาเกยฝั่งเข้ามา\n\nปกติเราไม่สนใจเรื่องแบบนี้นัก แต่ดูเหมือนชายคนนั้นจะบอกทหารว่าตนคือ Varian Wrynn กษัตริย์แห่ง Stormwind ไปที่ Theramore แล้วพบคนแคระชื่อ Sully ที่โรงเตี๊ยม เขารอเจ้าอยู่และจะบอกว่าต้องทำอะไรเมื่อไปถึง\n\nสืบให้รู้ว่าเกิดอะไรขึ้น" },
        objective = { "52:2064006847:910493975", "ตามหาสายลับ SI:7 ที่ประจำอยู่บน Theramore Isle" },
        steps = { { "30:659376340:2115539434", "ตามหาสายลับของ Shaw ใน Theramore" } },
    },
    [95196] = { -- Watch Yer Back
        title = { "14:1910325801:1342871907", "ระวังคนตาม" },
        description = { "184:189146083:751647579", "ฟังนะ ข้าจะเดินออกประตูด้านหลังเจ้า รอจนข้าไปลับตา แล้วไปพบข้าหลังสุสานนอกเมือง ดูให้แน่ใจว่าไม่มีใครตามมา" },
        objective = { "74:951285851:1726182325", "ไปพบ Sully McCleary ที่ Dustwallow Marsh เพื่อฟังรายละเอียดภารกิจของเจ้า" },
    },
    [95198] = { -- The Return of the King?
        title = { "23:543889164:1462291247", "กษัตริย์เสด็จกลับมาหรือ?" },
        description = { "463:46943327:2057679692", "รับนี่ไป พวกนักเวทที่บ้านทำมนตร์ลวงตานี้ไว้ให้ปลอมตัวได้ทันที มันจะทำให้เจ้าดูเหมือนนาวิกโยธิน Kul Tiras เหมาะกับงานนี้พอดี\n\nแอบเข้าไปในหอคอย แล้วตั้งใจฟังว่ามีใครพูดถึงชายที่ถูกซัดขึ้นชายหาดหรือไม่ แต่ขอเตือนว่าอย่าเข้าใกล้ Jaina มาก นางดูออกแน่ว่าเจ้าปลอมตัวมา\n\nถ้าการปลอมตัวหลุด กลับมาหาข้า ข้าจะจัดให้ใหม่" },
        objective = { "97:1221831886:693254904", "ใช้ชุดปลอมตัวของ SI:7 เพื่อแอบฟัง Jaina และคนสนิทของนางที่หอคอยนักเวทแห่ง Theramore" },
    },
    [95283] = { -- The Missing Kor'kron
        title = { "20:272208993:304477074", "Kor'kron ที่หายไป" },
        description = { "9:1871511191:798375331 N 433:139312330:150695158", "Lok-tar, {name} ข้าต้องการความช่วยเหลือเรื่องสำคัญ\n\nเมื่อไม่นานมานี้ เราส่งหน่วย Kor'kron Elite ไป Dustwallow Marsh เพื่อทำภารกิจพิเศษ เลยกำหนดรายงานตัวมานานแล้ว แต่ยังไม่ได้ข่าวจากพวกเขาเลย\n\nไป Brackenwall Village ใน Dustwallow Marsh แล้วคุยกับออร์คชื่อ Nazeer Bloodspike ไม่มีใครรู้ความเป็นไปใน Dustwallow ดีเท่าเขา สืบให้ได้มากที่สุด" },
        objective = { "52:810023447:1445652746", "ไปคุยกับ Nazeer Bloodspike ที่ Brackenwall Village" },
    },
    [95284] = { -- The Elite of the Elite
        title = { "22:7341237:1835915162", "ยอดฝีมือเหนือยอดฝีมือ" },
        description = { "492:317310649:1381291219", "ทหาร Kor'kron กลุ่มเล็ก ๆ ผ่านมาที่นี่เมื่อไม่กี่วันก่อน ไม่ได้บอกว่ามาทำไม ข้าก็ไม่ได้ถาม พวกเขาซื้อเสบียง พักสักหน่อย แล้วเดินทางต่อ\n\nKor'kron คือยอดฝีมือเหนือยอดฝีมือ ทนยิ่งกว่ากีบ elekk แต่ข้าอดคิดไม่ได้ว่าคงมีอะไรผิดพลาด\n\nข้าได้ยินคนหนึ่งพูดถึง «เกาะ» แล้วนอกชายฝั่งก็มีเกาะชื่อ Alcaz เป็นที่ที่อันตรายเอาเรื่อง ชวนเพื่อนไปสืบดูว่าเกิดอะไรขึ้นกับพวก Kor'kron" },
        objective = { "33:981291093:1432723568", "ตามหาทหาร Kor'kron Elite ที่หายตัวไป" },
    },
    [95285] = { -- Right Place, Wrong Time
        title = { "23:1619697779:700001526", "ถูกที่ผิดเวลา" },
        description = { "156:2036937548:1805484878", "<Sergeant Ulka พยายามลุกนั่งเพื่อคุยกับเจ้า เจ้าจะยื่นมือช่วย แต่นางปัดมือทิ้ง>\n\nเอาละ ทหารใหม่... ข้าจะเล่าให้ฟังว่าเกิดอะไรขึ้น" },
        objective = { "73:1429345890:738754972", "คุยกับจ่า Ulka เพื่อฟังว่าเกิดอะไรขึ้นบนเกาะ Alcaz" },
    },
    [95497] = { -- Burning Trail
        title = { "13:505763070:1180155407", "ตามรอยเรือเหาะในแดนเพลิง" },
        description = { "411:1725293914:324743741", "เราได้ข่าวว่าเรือเหาะลำหนึ่งใช้ภูเขาที่มีควันแถวนี้เป็นจุดสังเกตระหว่างขนส่ง แล้วพุ่งชนหน้าผา พวก Undermarket ขึ้นชื่อว่าใช้เนินเขาทางเหนือของ Burning Steppes ลักลอบขนของและค้าของเถื่อน\n\nไปตรวจเนินเขาพวกนั้น หาเบาะแสของสินค้าจากเรือเหาะที่สูญหาย เราอาจกู้เสบียงสำคัญของฝ่ายพันธมิตรกลับมาได้" },
    },
    [95498] = { -- Poachers Past Due
        title = { "17:1765190599:431393881", "ได้เวลาทวงคืนจากพรานเถื่อน" },
        description = { "402:117588326:1479353491", "พักก่อนข้าไปมีเรื่องกับพวกอันธพาล Shadowsilk ข้าต้องยอมเสียเงินติดตัวให้มันเลิกตามรังควาน แต่มันยังขโมยของของข้าไปอีก!\n\nอย่าเดินทางคนเดียวอย่างที่ข้าทำเลย พวกมันไปไหนเป็นกลุ่ม! ข้ายังจำชื่อที่มันเรียกกันตอนซุ่มเล่นงานข้าได้ Ranthor, Bonzo และ Liu\n\nจัดการพวกมันเสีย แล้วจะเอาอะไรจากข้าวของพวกมันก็เอาไป" },
    },
    [95499] = { -- Bad Lanterns
        title = { "12:1387187310:837935856", "โคมไฟต้องสงสัย" },
        description = { "444:1677156170:2118785265", "ทหารยาม Stormwind เพิ่งติดต่อข้ามา ดูเหมือนมีคนเที่ยวถามหาวัตถุดิบ... แปลก ๆ เขาว่ามีคนลักลอบนำสารตั้งต้นเข้าเมืองโดยซ่อนไว้ในลังที่ควรจะใส่โคมไฟ\n\nข้าไม่รู้ว่าเป็นสารอะไร รู้แค่ว่าถุงประทับตรา «CADRYA» และมีเถ้าจาก Blackrock Mountain ติดอยู่\n\nถ้าเจ้าจะไปทางนั้น ช่วยสังเกตให้ดี" },
    },
    [95500] = { -- Phial Play
        title = { "10:1185209732:1199009422", "ทดลองของในขวด" },
        description = { "401:465054150:290107220", "เราพบตัวอย่างสารผสม... ที่น่าสงสัย ถุงมีอักขระเวทอ่านว่า «Cadrya» และมีเขม่าจาก Burning Steppes ติดอยู่ ดูยังไงก็ไม่ผิด\n\nดูเหมือนมีคนพยายามสร้างเมือกที่คงตัวได้ทั้งในความร้อนและความเย็นจัด เราแช่ให้แข็งไม่ได้... เผาก็ไม่ได้ สารแบบนี้อาจใช้ปกป้องของบอบบางระหว่างขนส่งในสภาพที่โหดร้ายที่สุดได้\n\nเราต้องตามหาว่ามันมาจากไหน" },
    },
    [95501] = { -- Mojo No More
        title = { "12:653140110:930217773", "สิ้นอาคมของ Ka'ya" },
        description = { "348:1766142192:1448599712", "Ka'ya เคยเป็นพรานแห่งพงไพรที่เราไว้ใจ นางนำสัตว์ที่ดุร้ายและหายากที่สุดกลับมาให้หมู่บ้าน แต่ความโลภทำให้นางเปลี่ยนไป ทองซื้อใจนางได้ ตอนนี้นางใช้ความดุร้ายไปล่าหัวคน และฆ่าพี่น้องร่วมฮอร์ดของเราเอง\n\nนางทอดทิ้งฮอร์ด และต้องชดใช้การทรยศด้วยชีวิต\n\nไปที่ Burning Steppes แล้วเอาหัวของนางมาให้ข้า" },
    },
    [95502] = { -- Head Off The Headhunter
        title = { "23:1808846043:580717749", "หยุดนักล่าหัว" },
        description = { "421:538592896:1744965688", "มีโทรลล์นักล่าหัวคนหนึ่งเพ่นพ่านอยู่แถว Blackrock Mountain กับบริเวณรอบ ๆ รับค่าหัวทุกงานที่หาได้\n\nขวานของนางทำให้หลายครอบครัวต้องสูญเสียคนรัก Burning Steppes อันตรายพออยู่แล้ว ทั้งพวกโจรปล้นกองคาราวาน เผ่ามังกรดำ และโอเกอร์ เราปล่อยให้นักฆ่าโหดอย่างนางเดินตามถนนที่เราใช้ร่วมกันไม่ได้ นางชื่อ Ka'ya\n\nฆ่านางแล้วนำหลักฐานมาให้ข้า" },
    },
    [95503] = { -- Flare for the Dramatic
        title = { "22:1054423875:316196592", "ไฟสัญญาณลูกเล่นแพรวพราว" },
        description = { "255:1990994847:184843081", "<เจ้าหยิบคบเพลิงหน้าตาคล้ายพลุสัญญาณขึ้นมาแล้วพบกลไกแยบยล แค่ดีดสลักก็จุดแท่งให้ติดไฟเอง ใช้ก่อไฟได้ทุกเมื่อ ช่างวัตถุระเบิด ผู้เชี่ยวชาญดอกไม้ไฟ หรือพวกคลั่งไฟที่ชอบประกายไฟอาจสนใจสิ่งนี้>" },
    },
    [95504] = { -- Steamboiled or Scrambled
        title = { "24:2030151308:1013754425", "ต้มไอน้ำหรือปั่นกระจาย" },
        description = { "353:1727948767:1559698912", "มีเวลาแวะลานเศษเหล็กไหม?\n\nมีช่างเก็บเศษของชื่อ Frazzi ทำธุรกิจกู้ของมาขายอยู่ที่ Poacher's Den นางอยู่แก๊งเดียวกับที่รุมทำร้าย Yuka ผู้น่าสงสาร ถ้าจะไปทางนั้น เผื่อที่ไว้ใส่ชิ้นส่วนโลหะเงา ๆ ที่นางเหน็บไว้กับเข็มขัดเครื่องมือด้วย ข้ามีรายการของที่คิดว่าน่าจะหาได้ครบถ้าเจ้าช่วย" },
    },
    [95505] = { -- Box and Found
        title = { "13:310511764:1104741423", "กล่องที่เก็บได้" },
        description = { "421:2015262889:968020806", "นี่ เอ่อ ถ้าที่ค่ายที่เจ้าบอกว่าเจอยังไม่มีใครได้ข้อมูลนักบินหรือบัญชีรายการสินค้าไป เราอาจมีช่องทำเงินงาม ๆ รออยู่ก็ได้นะ\n\nให้ข้าส่งเจ้ากลับไปค่ายนั้น แล้วเจ้ายัดห่อกับกล่องพัสดุที่ยึดมาจากพวกนั้นได้ใส่เป้ให้เต็ม ดีไหม?\n\nข้าจะแบ่งผลประโยชน์ให้ด้วย ก็ข้าเป็นคนชี้เบาะแสเรื่องเรือเหาะที่หายไปตั้งแต่แรกนี่นา" },
    },
    [95506] = { -- Pilot Light
        title = { "11:1990654753:225681849", "ตามข่าวเรือเหาะ" },
        description = { "448:289258103:276787576", "นี่ ฟังนะ เขาลือกันว่าเรือเหาะใหม่ลำหนึ่งของเราบินลัดเหนือ Blackrock Mountain แล้วพุ่งเข้ากลุ่มเถ้ากับควันเต็ม ๆ ของที่ข้าสั่งไว้หลายเที่ยวเลยกำหนดมานานแล้ว ช่วยไปดูทีว่ามันสูญหายระหว่างทางหรือเปล่า\n\nถ้าคนคุมเรือยังอยู่แถวนั้น พวกเขาอาจคิดกลับไปบินต่อ แล้วทำสินค้าร่วงใส่บ้านคนอีก! เสียทั้งธุรกิจ... ทั้งลูกค้า\n\nไปดูให้ทั่วแล้วกลับมารายงานนะ" },
    },
    [95512] = { -- Wreck Recon
        title = { "11:105077113:833576023", "สำรวจซากเรือเหาะ" },
        description = { "392:842940639:1702019014", "เราได้ข่าวว่าเรือเหาะใช้ภูเขาที่มีควันแถวนี้เป็นจุดสังเกตระหว่างขนส่ง และลำหนึ่งพุ่งชนหน้าผา พวก Undermarket ขึ้นชื่อว่าใช้เนินเขาทางเหนือของ Burning Steppes ลักลอบขนของและค้าของเถื่อน\n\nไปตรวจเนินเขาพวกนั้น หาเบาะแสของสินค้าจากเรือเหาะที่สูญหาย เราอาจกู้ของสำคัญของฝ่ายฮอร์ดกลับมาได้" },
    },
    [95798] = { -- The Web of Magic
        title = { "16:845970444:1810407558", "ใยแห่งเวทมนตร์" },
        description = { "N 473:2103269530:1532973816", "{name} ข้าอยากให้เจ้าเอา I'lalai Fetish นี้ไปให้ Abra เพื่อนข้าที่ Dalaran ถ้านางมีเวลา ข้าอยากให้นางตรวจดู\n\nนางสนใจพิธีและเวทมนตร์ของโทรลล์เป็นพิเศษด้วย ข้าเชื่อว่านางคงตื่นเต้นที่จะได้ไขความลับของสิ่งนี้\n\nแต่ระวังหน่อย พวก Kirin Tor ค่อนข้างเลือกคนที่จะให้เข้าเมืองใหญ่ของตน ถ้าเจ้ายังเป็นแขกที่ไม่มีใครรู้จัก อาจต้องหาทางให้พวกเขาไว้ใจก่อน" },
        objective = { "52:972707091:1017215303", "นำ I'lalai Fetish ไปให้ Abra Cadabra ใน Dalaran" },
        completion = { "279:768239860:2036652519 C 52:873159869:2055964469", "โอ้โห! น่าทึ่งที่มีเวทมนตร์ต่างชนิดขัดแย้งกันอยู่มากมายและต่างดึงรั้งเครื่องรางนี้ ดีจริง ๆ ที่เจ้าเอามาให้ข้า\nถ้าไปอยู่ในมือคนผิดและจัดการไม่ระวังอย่างที่สุด อาจเป็นอันตรายมาก\nขอบใจที่นำมาถึงที่นี่ {class} ข้าจะรีบส่งผลที่พบให้ Loremaster Dibbs" },
    },
    [96603] = { -- Unstable Magic
        title = { "14:1304004259:385961613", "เวทมนตร์ไม่เสถียร" },
        description = { "495:677823872:50307244", "ตอนนี้ Archmage Rhonin ออกเดินทางไปสืบความผิดปกติของกระแสเวททั่ว Azeroth เขามอบหมายให้ข้าขอแรงนักผจญภัยฝีมือดีอย่างเจ้าเก็บข้อมูลภาคสนามที่สำคัญไปช่วยเขา\n\nเอา Arcane Censer นี้ไป ขณะที่มนตร์ของมันยังมีผล เจ้าจะดึงละอองเวทไม่เสถียรจากผู้ใช้เวทที่ชำนาญที่สุดและสิ่งทรงพลังเป็นพิเศษที่พบได้ นำละอองพวกนั้นมาให้ข้า แล้ว Kirin Tor จะเป็นหนี้บุญคุณเจ้า" },
        objective = { "6:1273960851:929420321 W1 57:1483015654:2057138409", "นำ Mote of Unstable Magic {world1} ชิ้นไปให้ Archmage Celindra ใน Dalaran" },
        completion = { "185:269536891:1135206986", "ขอบใจที่รับใช้ Kirin Tor ถ้าเจอเศษพลังเวทแบบนี้อีกระหว่างเดินทาง โปรดนำมาให้ข้าอีกนะ\nKirin Tor จะจดจำสิ่งที่เจ้าทำไว้" },
        progress = { "490:2086391672:1063588006", "ความปั่นป่วนของเวทมนตร์ครั้งนี้ทำให้เราทุกคนกังวลอย่างยิ่ง มันรุนแรงจนจู่ ๆ เราก็รักษาเกราะเวทอาร์เคนที่คุ้มครอง Dalaran ระหว่างการสร้างเมืองขึ้นใหม่ไว้ไม่ได้ เราสร้างมนตร์คุ้มกันที่อ่อนกำลังกว่าขึ้นมาแล้ว แต่เราก็ยังตกอยู่ในอันตราย\nเราหวังว่าจะหาสาเหตุของความปั่นป่วนนี้ได้ในเร็ววัน ทุกความช่วยเหลือที่เจ้ามอบให้ย่อมทำให้ Kirin Tor ยอมรับและนับถือเจ้ามากขึ้น" },
        required = { [274964] = { "22:1973487606:760368334", "ละอองเวทมนตร์ไม่เสถียร" } },
        steps = { { "22:1973487606:760368334", "ละอองเวทมนตร์ไม่เสถียร" } },
    },
    [96609] = { -- A Taste of Home
        title = { "15:1798058026:1951480276", "รสชาติจากบ้านเกิด" },
        description = { "490:876434345:1068412861", "เจ้ารู้จัก Silvermoon Shimmerwine ไหม? รสละมุนแบบนั้นมีเฉพาะในไวน์จากไร่องุ่น Eversong และเป็นสิ่งเดียวที่ข้าคิดถึงจริง ๆ จากบ้านเกิด\n\nเสียดายว่าฝั่งนี้ของ Thalassian Gate หายากเหลือเกิน\n\nลูกค้าคนหนึ่งเคยเอามาให้ข้าขวดหนึ่ง เขาอ้างว่าไป «ปลดปล่อย» มาจากพวกบลัดเอลฟ์ทางเหนือของ Azshara ถ้าเดินทางไปแถวนั้นแล้วหากลับมาให้ได้อีก ข้าจะตอบแทนเจ้าอย่างงาม" },
        objective = { "6:1273960851:929420321 W1 71:1458873090:1792968594", "นำ Silvermoon Shimmerwine {world1} ขวดไปให้ Arille Azuregaze ในเมือง Dalaran" },
        completion = { "171:466255870:1711747639", "หวังว่าเจ้าจะไม่ต้องฆ่าพี่น้องที่หลงผิดของข้ามากเกินไปกว่าจะได้ของพวกนี้กลับมา\nข้ารู้ว่าต้องเดินทางไกลและซาบซึ้งในความพยายามของเจ้า นี่รางวัลตามสัญญา" },
        progress = { "261:640359528:893871065", "คนของข้าที่หลงผิดกำลังเดินไปสู่ความพินาศ ข้าแทบไม่อยากกลับบ้านที่ Silvermoon ไปเห็นกับตาว่าเราตกต่ำไปถึงไหนแล้ว\nแต่ข้าต้องยอมรับว่าคิดถึงของดีบางอย่างจากบ้านเกิดอยู่เหมือนกัน" },
        required = { [274966] = { "22:730107852:1685971988", "ไวน์ประกายแห่ง Silvermoon" } },
        steps = { { "22:730107852:1685971988", "ไวน์ประกายแห่ง Silvermoon" } },
    },
    [96798] = { -- Into the Darkness
        title = { "17:564359573:113494058", "เข้าสู่ความมืด" },
        description = { "490:461531587:1147685456", "คนเห็น Sergeant Danneth ครั้งสุดท้ายตอนออกลาดตระเวนกับหน่วยแถว Serpent's Coil ทางใต้ของ Nethergarde Keep ไม่ไกล ทหารในหน่วยคนหนึ่งโซซัดโซเซกลับมาที่ป้อม บาดเจ็บสาหัส และบอกว่าคนทั้งหน่วยถูกฆ่าหรือจับตัวไป น่าเสียดายที่เขาตายหลังจากนั้นไม่กี่ชั่วโมง\n\nเรายังยืนยันไม่ได้ว่า Danneth ตายแล้ว แต่โอกาสรอดไม่ดีนัก ข้าแบ่งคนไปบุกที่ซ่อนของพวกสาวกลัทธิไม่ได้ ถ้าเจ้าอยากไปตามหาเขา ข้าก็ยินดีรับความช่วยเหลือ" },
        objective = { "92:576427918:362739164", "ตามหา Sergeant Danneth ในถ้ำ Serpent's Coil ทางตะวันออกเฉียงใต้ของ Nethergarde Keep" },
        completion = { "14:510454027:984900205 C 212:1976906187:502173744", "ขะ... ขอบใจ {class} ข้าคงอยู่ที่นี่ตามลำพังได้อีกไม่นาน\nข้ายังอ่อนแรงเกินกว่าจะสู้ แต่ถ้าเจ้ารับมือพวกมันไหว เราอาจตีฝ่าไอ้พวกสารเลวนี่กลับไปถึงป้อมได้" },
    },
    [96799] = { -- A Heavy Responsibility
        title = { "22:29172138:1347371166", "ภาระอันหนักอึ้ง" },
        description = { "364:770063944:1465171463", "<Lieutenant Connar ตั้งใจฟังขณะเจ้าเล่าว่ามาที่นี่ทำไม>\n\nงั้น Danneth มีหลานชายกำพร้าอยู่ที่ Dalaran หรือ? ถ้ายังไม่ได้คุยกับเขาเรื่องนี้ ข้าแนะนำให้คุย เขาดูไม่ค่อยเหมาะกับการเลี้ยงเด็ก แต่เขาอาจทำให้ข้าประหลาดใจก็ได้\n\nถ้าเขาอยากไปรับเด็กหลังจากหายดีแล้ว ข้าอนุญาตให้ลางานไปได้" },
        objective = { "48:801416201:1378318150", "คุยกับ Sergeant Danneth ที่ Nethergarde Keep" },
        completion = { "132:1074747085:1992599650", "ข้า... มีหลานชาย และเพราะอย่างนี้เจ้าถึงมาตามหาข้าหรือ?\nข้าไม่เคยรู้เลยว่า Denric พี่น้องของข้ามีลูก ขอเวลาข้าทำใจหน่อย..." },
        steps = { { "27:848540063:1443777074", "คุยกับ Sergeant Danneth" } },
    },
    [96811] = { -- Escaping the Shadows
        title = { "20:1759220928:1604835717", "หนีออกจากเงามืด" },
        description = { "58:729604800:2032953227", "ข้าว่าข้าพร้อมแล้ว ถ้าเจ้าพร้อมเมื่อไรก็ออกเดินทางกัน" },
        objective = { "85:933468906:1776228964", "คุ้มกัน Sergeant Danneth ออกจากถ้ำ Serpent's Coil และพาเขากลับไปที่ Nethergarde Keep" },
        completion = { "55:337309529:1777576917", "รู้ว่า Danneth รอดก็โล่งใจ เขาอึดจริง ๆ" },
        objectiveLabels = {
            event = { ["Escort Sergeant Danneth"] = "คุ้มกัน Sergeant Danneth" },
        },
    },
    [96812] = { -- Thicker Than Water
        title = { "18:983020069:1372164683", "สายเลือดผูกพัน" },
        description = { "336:966746171:608143072", "ใช่... ข้าจะรับเด็กมาเลี้ยง เขาเป็นครอบครัว และเขาเหลือแค่ข้า ข้าต้องพักฟื้นต่ออีกหน่อย แต่พอไหวเมื่อไรจะขอลางานไป Dalaran ทันที\n\nช่วยกลับไปบอก Matron ว่าข้ากำลังจะไป ข้าจะทำให้ดีที่สุดให้ลูกชายของพี่น้องชายของข้าปลอดภัยและเติบโตแข็งแรง\n\nข้าขอสาบาน" },
        objective = { "106:1746676905:1296133935", "กลับไปหา Orphan Matron Aria ใน Dalaran แล้วบอกนางว่า Sergeant Danneth ตั้งใจจะรับ Randal ไปเลี้ยง" },
        completion = { "313:2017453916:1742404435", "ดีใจที่ได้ยินว่าจ่า Danneth ยินดีรับเด็กคนนี้ไปดูแล เราทำดีที่สุดเพื่อเด็กกำพร้าของเรา แต่ครอบครัวแท้ ๆ ก็มีความหมายกับเขามาก\nขอบใจที่ช่วยจ่าและช่วยให้ครอบครัวได้กลับมาอยู่ด้วยกัน รับสิ่งนี้เป็นรางวัลสำหรับความพยายามของเจ้าด้วยเถอะ มันอาจไม่มาก แต่เป็นอย่างน้อยที่ข้าทำให้เจ้าได้" },
    },
    [96828] = { -- Special Access
        title = { "14:2082210243:1777123956", "สิทธิ์เข้าถึงพิเศษ" },
        description = { "257:1641534186:1665102255", "ตอนนี้เจ้าพิสูจน์แล้วว่าเป็นพันธมิตรที่ยืนหยัดและพึ่งพาได้ ข้าได้รับอนุญาตให้สอนวิธีเคลื่อนย้ายตัวเองมายังเมืองของเรา\n\nเราขอบใจที่เจ้าช่วย Dalaran และ Kirin Tor หวังว่าจะได้เห็นเจ้าชำนาญเวทมนตร์ยิ่งขึ้นต่อไป" },
    },
    [97049] = { -- Essence of Seeping Slimes
        title = { "25:2114847866:1312100599", "แก่นพลังจากเมือกไหลซึม" },
        description = { "302:1363152714:256657661", "ถ้าเจ้ากำลังจะเข้า Shaper's Terrace ข้ามีเรื่องอยากให้ช่วย\n\nมีรายงานว่าพวกสัตว์เมือกอาศัยอยู่ในแอ่งข้าง Achromatic Crystal ไร้สี ข้าคิดว่าแก่นพลังของพวกมันอาจใช้ในการทดลองของข้าได้ ช่วยนำตัวอย่างกลับมาให้ศึกษาสักหน่อย\n\nข้าจะตอบแทนให้คุ้มแรง" },
        objective = { "55:1641785367:1464895589", "เก็บแก่นพลังจากเมือกไหลซึม 8 ชิ้นใน Shaper's Terrace", amount = { "7:451016854:1830523975 W1 47:44491591:943006579", "เก็บแก่นพลังจากเมือกไหลซึม {world1} ชิ้นใน Shaper's Terrace" } },
    },
    [97486] = { -- To Feed an Army
        title = { "15:1278989199:787435130", "เลี้ยงคนทั้งกองทัพ" },
        description = { "497:1423768926:687232533", "ถ้าจะตุนของไว้ให้นักผจญภัยที่ผ่านทาง ข้าต้องมีอาหารเหลือเฟือ ฝ่ายพันธมิตรจะกินขนมปังกับชีสก็เรื่องของพวกเขา แต่ทหารฮอร์ดตัวจริงกินเนื้อ!\n\nตอนมาถึง ข้าเห็นฝูงวอร์กเดินอยู่ไกลออกไปทางตะวันออกเฉียงใต้ อีกฝั่งของหุบเหว เอาเนื้อมาให้พอบรรจุลังได้สักสองสามใบ\n\nไหน ๆ เจ้าก็จะออกไปแล้ว ข้าได้ยินเจ้าของโรงเตี๊ยมฝั่งพันธมิตรพึมพำว่าแมงมุมเป็นของอร่อย ข้าไม่ค่อยเชื่อแต่อยากลอง เอามาให้ชิมสักสองสามตัวด้วย" },
    },
    [97487] = { -- Inn and Out
        title = { "11:1694032497:434026784", "เข้าโรงเตี๊ยมแล้วออกทันที" },
        description = { "483:948516754:2036125809", "เก็บเป็นความลับนะ ข้าอายที่จะขอให้ช่วยเรื่อง Hearthstone นี่ แต่คิดว่าพอเข้าใจวิธีจนกล้าลองแล้ว เราน่าจะ... คิดให้ดีว่าจะให้ใครเป็นคนลองกลุ่มแรก\n\nข้าได้ยินคนพูดถึงการใช้แรงงานทาสใน Slag Pit ลึกลงไปใต้จุดที่เรายืน ลองดูว่าหินพวกนี้ช่วยให้พวกเขาหนีได้ไหม ถ้าไม่ได้ เราคงขอบคุณกันทั้งคู่ที่ข้ายังไม่ได้ผูก Hearthstone ของเจ้าไว้กับที่นี่" },
    },
    [97488] = { -- To Feed an Army
        title = { "15:1278989199:787435130", "เลี้ยงคนทั้งกองทัพ" },
        description = { "504:1846695297:406985329", "ข้าเพิ่งเห็นว่าอาหารที่ตุนไว้แทบไม่พอเลี้ยงคนของภราดรภาพ แล้วจะรับมือยังไงเมื่อพวกเรามากันเยอะขึ้น?\n\nข้าได้ยินออร์คอีกฟากเนินส่งพวกฮอร์ดไปหาวอร์กทางตะวันออกเฉียงใต้สุดของหุบเขา เจ้าฆ่าสักสองสามตัวแล้วเอาเนื้อกลับมาก็ได้ แต่เน้นไปที่แมงมุมลาวาทางตะวันตกดีกว่า จะได้ไม่ต้องแย่งกับศัตรูมากนัก\n\nไม่ต้องห่วง ข้ารู้วิธีปรุงแมงมุมให้อร่อย" },
    },
    [97489] = { -- Inn and Out
        title = { "11:1694032497:434026784", "เข้าโรงเตี๊ยมแล้วออกทันที" },
        description = { "493:579888133:2030236917", "ข้าได้ยินคนของภราดรภาพคุยกันเรื่องเหมืองที่ใช้แรงงานทาสใต้บริเวณที่เรียกว่า Cauldron ฟังดูพวกเขาอยากเล่นงานผู้นำของเหมืองมากกว่าจะปล่อยคนงาน\n\nข้าดูแลโรงเตี๊ยมกับโรงเหล้ามานาน แต่ยังไม่เคยมีโอกาสช่วยใครที่เดินมาถึงร้านเองไม่ได้ นี่ดูเป็นโอกาสดีที่จะลองใช้ Hearthstone ที่เพิ่งลงมนตร์ ใครจะรู้ พวกเขาอาจเป็นคนที่เหมาะจะชวนเข้าร่วมกับเราก็ได้" },
    },
    [99193] = { -- A Donation of Mageweave
        title = { "23:477706609:1703816279", "บริจาคผ้า Mageweave" },
        description = { "417:1150244688:1011716072", "นักเวทของเราหลงใหลการศึกษาคุณสมบัติของผ้า Mageweave ที่พบได้ทั่วไปใน Azeroth ถ้าเจ้าบริจาคผ้าชนิดนี้ได้หกสิบชิ้น ก็จะช่วยงานศึกษาของเราอย่างมาก High Order คงเห็นความเอื้อเฟื้อของเจ้าด้วยแน่!\n\nถ้ามีผ้า Mageweave หกสิบชิ้นติดตัวและพร้อมบริจาค ข้ารับไว้ได้เลย" },
        required = { [4338] = { "15:1283357618:289024293", "ผ้า Mageweave" } },
        objectiveLabels = {
            item = { ["Mageweave Cloth"] = "ผ้า Mageweave" },
        },
    },
    [99194] = { -- A Donation of Runecloth
        title = { "23:805424014:894170896", "บริจาคผ้า Runecloth" },
        description = { "N 391:1933503537:1189580907", "{name} ขอบใจที่เคยช่วยเหลือ High Order เราพยายามหาให้ทันความต้องการผ้าของผู้คน แต่ Runecloth ขาดแคลนเป็นพิเศษ เราหวังจริง ๆ ว่าเจ้าจะช่วยได้เหมือนที่ผ่านมา!\n\nถ้ายินดี โปรดนำ Runecloth ส่วนที่เจ้าแบ่งได้มาให้ข้า ครั้งแรกเราจะรับบริจาคหกสิบชิ้นหนึ่งครั้ง แล้วค่อยว่ากันต่อ" },
        required = { [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        steps = { { "9:897047003:553648234", "ผ้ารูน" } },
    },
    [8259] = { -- A More Fitting Reward
        title = { "21:1844317346:2020417597", "รางวัลที่เหมาะสมกว่า" },
        completion = { "4:1110228981:147916455 N 243:595998822:1464041311", "อา {name}... เจ้าทำได้ยอดเยี่ยมในการต่อสู้กับ Darkreaver ข้าขอเสริมว่าฝีมือเช่นนี้สมควรได้รับรางวัลที่ดีกว่าที่เจ้าได้ โปรดรับหมวกใบนี้เป็นของกำนัลเพิ่มเติมสำหรับสิ่งที่เจ้าทำสำเร็จใน Scholomance\n\nขอขอบใจเจ้าอีกครั้ง" },
    },
    [94971] = { -- A Paladin's Steed
        title = { "17:1492621957:110824190", "ม้าศึกของพาลาดิน" },
        description = { "347:2078166986:2066573776", "ม้าศึกเป็นกำลังสำคัญของพาลาดินมาแต่ไหนแต่ไร ม้าที่ผ่านพิธีอุทิศเป็นพิเศษเหล่านี้พาพาลาดินพร้อมอาวุธเข้าสู่สนามรบ มันห้าวหาญและไม่หวั่นกลัวพอ ๆ กับนักรบที่เก่งที่สุดของเรา\n\nแม้สถานการณ์ของเราจะเปลี่ยนไป แต่เรายังต้องใช้ม้าพาเข้าสู่สนามรบ ถึงเวลาที่เจ้าจะมีม้าแบบนั้นเป็นของตัวเองแล้ว" },
        objective = { "57:1248393254:756110302", "คุยกับ Danitha Morr เพื่อเรียนวิธีเรียก Warhorse" },
        completion = { "163:1948809336:1315739330 C 17:1991809155:1774211314", "การรับม้าคู่กายเป็นพิธีสำคัญในการก้าวสู่หนทางของพาลาดินทุกคน ข้ายินดีมอบม้าศึกตัวนี้ให้เป็นของเจ้าเอง\nขอให้ม้าศึกตัวนี้รับใช้เจ้าอย่างดี {class} แห่ง Forsaken" },
    },
    [95365] = { -- Where's The Squire?
        title = { "19:1616449938:166324511", "ผู้ติดตามอัศวินอยู่ที่ไหน?" },
        description = { "180:1467108479:2047121649", "<ไม่มีวี่แววของ Cuthbert ผู้ติดตามอัศวิน อยู่ใกล้ร่างของอัศวินที่ล้มลง อัศวินเพิ่งเสียชีวิตได้ไม่นาน ผู้ติดตามอาจยังอยู่แถวนี้>" },
    },
    [95739] = { -- Tainted Shrines
        title = { "15:1841487328:2065889485", "แท่นบูชาที่แปดเปื้อน" },
        description = { "90:368718027:2024288036", "แท่นบูชาสะอาดแล้ว ดี\nธรรมชาติจะฟื้น\n<ธาตุสั่นสะท้าน>\nไม่\nอันตราย!" },
    },
    [95751] = { -- Odd Totems
        title = { "10:667967191:329830266", "โทเทมประหลาด" },
        description = { "410:1297216612:1663873769", "เหล่าวิญญาณให้ข้าเห็นนิมิตของความร้อน แดด และเนินทรายที่ทอดตัวไม่สิ้นสุด โทเทมแกะสลักคู่หนึ่งตั้งอยู่โดดเดี่ยว มองลงไปเห็นกระดูกสัตว์ร้ายตัวใหญ่ที่ถูกทรายแห่งกาลเวลากลบไปครึ่งหนึ่ง ข้ามั่นใจว่าสิ่งที่เห็นคือเนินทะเลทราย Tanaris\n\nข้าไม่รู้ว่าโทเทมตั้งไว้ทำอะไร แต่ที่มันยืนเฝ้าอยู่โดดเดี่ยวคงมีเหตุผล ข้าอยากให้เจ้าไปหาที่แห่งนั้นและดูว่าจะไขปริศนาได้ไหม" },
        objective = { "38:877442805:1770224374", "สำรวจโทเทมประหลาดใน Tanaris" },
    },
    [95753] = { -- Challenge of the Desert Wolf
        title = { "28:1585110333:1914016596", "คำท้าของหมาป่าทะเลทราย" },
        description = { "283:2022018339:1920739973", "<โทเทมเต้นเป็นจังหวะด้วยเวทอันป่าเถื่อน ภาพหมาป่าวิญญาณผุดขึ้นในใจเจ้า มันกวักเรียกเจ้า\n\nดูเหมือนมันกำลังท้าให้เจ้ารับการทดสอบ\n\nโทเทมอีกต้นที่เหมือนต้นที่เจ้ากำลังแตะอยู่ปรากฏขึ้นไกลออกไป ถัดจากโครงกระดูกใหญ่ที่แดดฟอกจนซีด>" },
        objective = { "82:2095090717:916523756", "ไปให้ถึง Odd Totem อีกต้นที่ปลายโครงกระดูกขนาดมหึมาก่อนหมดเวลา" },
        completion = { "76:215495968:1586571219", "<พลังเวทธรรมชาติไหลเป็นจังหวะผ่านโทเท็ม มันเห็นว่าเจ้าคู่ควรกับรางวัล>" },
        steps = { { "15:97611727:1848955968", "ไปถึง Old Totem" } },
    },
    [96064] = { -- Bold Ogres
        title = { "10:851861555:211644035", "พวกโอเกอร์ใจกล้า" },
        description = { "140:1557738210:731125549", "พวกโอเกอร์ใน Arathi Highlands กำลังทำอะไรน่าสงสัย ดูเหมือนมันอยากควบคุมสายฟ้า ไปดูซิว่าพวกมันคิดจะทำอะไร" },
    },
    [96065] = { -- Lightning Rod
        title = { "13:1386262697:1454308659", "สายล่อฟ้า" },
        description = { "208:1421497313:1487469758", "<เวทแห่งธรรมชาติของเจ้าตื่นตัวเมื่อสัมผัสร่องรอยของสายฟ้าที่ฟาดลงพื้นเบื้องหน้าซ้ำแล้วซ้ำเล่า\n\nพวกโอเกอร์ต้องมีความลับเรื่องสายฟ้าอยู่บ้าง บางทีเจ้าอาจชิงความลับนั้นมาได้>" },
    },
    [96132] = { -- Offering to the Wind Spirit
        title = { "27:1290126785:1999551234", "เครื่องบูชาวิญญาณแห่งลม" },
        description = { "234:557915120:303836149", "<ลมสงบลงแล้ว แท่นบูชายอมรับว่าเจ้าคู่ควรกับคำท้าของมัน\n\nเศษแผ่นหนังปลิวอยู่รอบฐานแท่นบูชา บนนั้นมีรายการวัตถุดิบพร้อมชื่อและจำนวน\n\nนี่อาจเป็นการทดสอบอีกอย่างหรือ?>" },
    },
    [96133] = { -- Whispers of Wind Spirits
        title = { "24:708652596:346653047", "เสียงกระซิบของวิญญาณแห่งลม" },
        description = { "432:1344351821:1627629143", "เหล่าวิญญาณกระซิบบอกข้าว่าดินแดนที่เรียกว่า Thousand Needles กำลังปั่นป่วนมาก ลมแรงจัดกวาดผ่านทั่วบริเวณ ทำให้การเดินทางที่อันตรายอยู่แล้วยิ่งอันตรายขึ้น\n\nพวก Grimtotem แห่ง Darkcloud Pinnacle ขโมยแท่นบูชาใหญ่ของวิญญาณแห่งลมไป ทำให้เหล่าวิญญาณไม่พอใจอย่างยิ่ง สองเรื่องนี้ต้องเกี่ยวกันแน่ ข้าต้องให้เจ้าไปดูว่าอะไรทำให้เกิดความปั่นป่วน แล้วหยุดมันเสีย" },
    },
    [96134] = { -- Leap of Faith
        title = { "13:355372698:148954123", "ก้าวกระโดดแห่งศรัทธา" },
        description = { "253:1346597065:760921002", "<เครื่องบูชาปรากฏขึ้นตรงหน้าเจ้า เจ้ารู้สึกว่าการทดสอบถัดไปจะเป็นครั้งสุดท้ายและยากที่สุด ดูเหมือนมันต้องการทดสอบศรัทธาของเจ้า\n\nแท่นบูชามองเจ้าอยู่เงียบ ๆ รอให้เจ้าตัดสินใจ\n\nเจ้าจะรับการทดสอบหรือไม่?>" },
    },
    [96384] = { -- Legacy Reward: Spectral Bear Tabard
        title = { "35:2001057323:201905695", "รางวัล Legacy เสื้อคลุมตราหมีวิญญาณ" },
    },
    [96385] = { -- Legacy Reward: Reins of the Spectral Bear
        title = { "41:2132265118:1982793569", "รางวัล Legacy บังเหียนหมีวิญญาณ" },
    },
    [96449] = { -- Aeonas's Secret Refuge
        title = { "22:418471872:909539919", "ที่หลบภัยลับของ Aeonas" },
        description = { "471:802126593:1059918675", "มานึกดูแล้ว ข้ารู้จักที่เงียบ ๆ แห่งหนึ่งไกลลงไปทางใต้ มีคนเคยบอกว่าชื่อ Newman's Landing แต่อย่าถามนะว่า «Newman» เป็นใคร เจ้าควรเริ่มตามหา Aeonas เพื่อนเก่าของเราที่นั่น\n\nเอาเรือเล็กเก่าของข้าไปใช้ได้ ข้าผูกไว้เลยท่าเรือเหนือสุดไปนิดเดียว มันอาจไม่ดีเท่าไร แต่พาเจ้าไปถึงเร็วกว่าว่ายน้ำแน่\n\nข้าหวังจริง ๆ ว่าเขาจะไม่เป็นอะไร ถ้าเจ้าไปดูเพื่อนเราหน่อย ข้าคงสบายใจขึ้น" },
        objective = { "58:299004942:1296444132", "ใช้ Old Dingy ที่ Menethil Harbor เพื่อตามหา Aeonas" },
        steps = { { "19:2034791725:372299980", "ขึ้นเรือเล็ก Old Dinghy" } },
    },
    [96476] = { -- In Search of Aeonas
        title = { "19:385878199:316894138", "ตามหา Aeonas" },
        description = { "243:1615500458:190755524", "Aeonas พูดอะไรสักอย่างเรื่อง Felwood เขาอาจอยู่ที่นั่น ทางใต้ของป่ามีชุมชนเล็ก ๆ ชื่อ Emerald Sanctuary ข้าแนะนำให้ลองถามคนแถวนั้นว่ามีใครเห็นเขาบ้าง" },
        objective = { "78:744284467:1368457260", "ตามหาเบาะแสของ Aeonas the Vindicated ที่ Emerald Sanctuary ใน Felwood" },
        steps = { { "49:306662177:1272663807", "หาเบาะแสของ Aeonas ที่ Emerald Sanctuary" }, { "32:855468369:558359429", "ตามร่องรอยของ Aeonas ใน Felwood" }, { "28:10656612:21049703", "ใช้เชือกเพื่อไปหา Aeonas" } },
    },
    [97168] = { -- Material Assistance
        title = { "19:314173589:258658095", "ช่วยหาวัสดุ" },
        description = { "N 437:504884080:390886053", "{name} เรื่องของเหล่าวิญญาณหนักเอาการ ทั้งในโลกวัตถุและในแดนวิญญาณ ข้าต้องการแรงช่วย ลึกเข้าไปใน Scholomance ที่ Lordaeron มี Great Ossuary ที่เงามืดปกคลุมหนาทึบ ข้ากำลังทำเครื่องมือไว้ฝ่าความมืดนั้น แต่ยังขาดของที่จะทำให้เสร็จ\n\nเอาเพชรมาให้ข้าสองเม็ด Azerothian Diamond หนึ่งเม็ดและ Pristine Black Diamond อีกหนึ่งเม็ด ของพวกนี้หาไม่ง่าย ข้าเองก็ไม่มีทรัพยากรพอ เจ้าช่วยหาเพชรทั้งสองเม็ดมาให้ได้ไหม?" },
        objective = { "128:2087716718:1253327124", "ถ้าอยากช่วย Eldrun Stormbreaker ที่ Ironforge ให้นำ Azerothian Diamond และ Pristine Black Diamond อย่างละเม็ดไปให้เขา" },
        required = { [12800] = { "18:1398536143:412119698", "เพชรแห่ง Azeroth" }, [18335] = { "22:140138788:1102101996", "เพชรดำไร้ตำหนิ" } },
        objectiveLabels = {
            item = { ["Azerothian Diamond"] = "เพชรแห่ง Azeroth", ["Pristine Black Diamond"] = "เพชรดำไร้ตำหนิ" },
        },
    },
    [97169] = { -- The Darkreaver Menace
        title = { "21:664490122:97049798", "ภัยจาก Darkreaver" },
        description = { "392:32000152:147379226 N 86:1109971076:1639479110", "อัศวินมรณะ Darkreaver ครอง Great Ossuary ใน Scholomance มันคิดจะบิดเบือนแดนวิญญาณให้ทำตามบัญชา ต้องหยุดมันให้ได้ เครื่องหยั่งญาณที่เจ้าช่วยทำจะได้ใช้ก็คราวนี้\n\nใช้เครื่องหยั่งญาณตรงใจกลางชั้นใต้ดินของ Great Ossuary เพื่อเรียกสมุนวิญญาณของ Darkreaver ออกมา เมื่อโค่นวิญญาณพวกนั้นแล้ว ตัวอัศวินมรณะจะปรากฏ {name} เอาหัวมันมาให้ข้า! ต้องกำจัดมันเท่านั้นถึงจะคืนสภาพแดนวิญญาณได้" },
    },
    [97174] = { -- A Worthy Endeavor
        title = { "17:1964137885:1510445571", "ภารกิจอันคู่ควร" },
        description = { "19:1057308443:1361522860 N 372:824754245:691759859", "ถึงเวลาแล้ว {name} เช่นเดียวกับตอนยังมีชีวิต พาลาดินแห่ง Forsaken จะสมบูรณ์ก็ต่อเมื่อผูกสายสัมพันธ์กับม้าศึกได้ ม้านี้ต่างจากม้าทั่วไป มันเป็นวิญญาณแห่งการลงทัณฑ์ที่ทรงพลัง\n\nไปคุยกับ Danitha Morr ที่ Bandarion Keep นางจะอธิบายและชี้ทางว่าต้องทำอะไรต่อ หนทางเบื้องหน้าจะยากลำบาก แต่อย่างที่สหายออร์คชอบพูดกัน เลือดและสายฟ้า พี่น้องเอ๋ย!", variants = { { { "19:1057308443:1361522860 N 373:1508443335:426229013", "19:1057308443:1361522860 N 371:1722965727:153722717" }, "ถึงเวลาแล้ว {name} เช่นเดียวกับตอนยังมีชีวิต พาลาดินแห่ง Forsaken จะสมบูรณ์ก็ต่อเมื่อผูกสายสัมพันธ์กับม้าศึกได้ ม้านี้ต่างจากม้าทั่วไป มันเป็นวิญญาณแห่งการลงทัณฑ์ที่ทรงพลัง\n\nไปคุยกับ Danitha Morr ที่ Bandarion Keep นางจะอธิบายและชี้ทางว่าต้องทำอะไรต่อ หนทางเบื้องหน้าจะยากลำบาก แต่อย่างที่สหายออร์คชอบพูดกัน เลือดและสายฟ้า พี่น้องเอ๋ย!" } } },
        objective = { "61:1183149150:142823381", "ไปคุยกับ Danitha Morr ที่ Bandarion Keep ใน Tirisfal Glades" },
    },
    [97175] = { -- Due Sacrifice
        title = { "13:371114855:2034429244", "สิ่งที่ต้องสละ" },
        description = { "430:358621734:1327286465", "ภารกิจที่คู่ควรล้วนต้องแลกด้วยการเสียสละ และงานแรกนี้ก็เช่นกัน\n\nเจ้าต้องหากระถางกำยานขับไล่วิญญาณของ High Priest Zayus มาใช้ แม้เราจะใช้เพื่อจุดประสงค์ที่ดี แต่ก็ต้องให้ค่าตอบแทนที่เหมาะสม\n\nไป Orgrimmar แล้วคุยกับ High Priest Zayus ที่นั่น เขาจะขอ... «เงินบริจาค» แลกกับกระถางกำยาน เมื่อเรื่องจบลง เจ้าจะเห็นว่าคุ้มกับที่จ่ายไป" },
        objective = { "132:116121734:1294726066", "เดินทางไป Orgrimmar เพื่อขอกระถางธูปขับไล่วิญญาณ (Exorcism Censer) จาก High Priest Zayus เจ้าต้องบริจาค 150 ทองจึงจะได้มา" },
    },
    [97176] = { -- Exorcising Terrordale
        title = { "21:751479789:1111333091", "ขับไล่วิญญาณที่ Terrordale" },
        description = { "467:2090379023:1706110709", "ข้าใส่ดินจากพื้นแปดเปื้อนที่ Terrordale ใน Eastern Plaguelands ลงในกระถางกำยานแล้ว ไปที่นั่นแล้วใช้มันหาจุดที่มลทินรุนแรงที่สุด เจ้าจะสังเกตได้จากไอสีเขียวแห่งความตายที่ลอยขึ้นจากพื้นตรงที่เหล่าวิญญาณทรมานมารวมตัวกัน\n\nใช้กระถางกำยานเผยตัววิญญาณเหล่านี้ แล้วปลดปล่อยพวกเขาจากความทรมาน เมื่อวิญญาณสงบแล้วให้กลับมา เราจะคุยกันว่าต้องทำอะไรต่อ" },
        objective = { "181:517460313:726549281", "ใช้ Exorcism Censer ขับวิญญาณที่ถูกทรมานออกมาใน Terrordale เมื่อกำจัด Terrordale Spirits ครบ 25 ตนแล้ว ให้กลับไปหา Danitha Morr ที่ Bandarion Keep ใน Tirisfal Glades" },
    },
    [97177] = { -- Acts of Mercy
        title = { "13:1925524467:86116327", "การแสดงเมตตา" },
        description = { "209:911097787:536791885 N 30:215828219:480387644", "รับกระถางกำยานไปพร้อมพรของเหล่าโลอา ข้าใช้มันขับวิญญาณวูดูชั่วร้ายมาหลายครั้ง มันจะช่วยเจ้าได้ดีในการทดสอบข้างหน้า\n\nกลับไปหา Danitha เถิด {name} นางจะพาเจ้าทำภารกิจต่อ" },
        objective = { "80:955596479:2104070282", "นำ Exorcism Censer กลับไปให้ Danitha Morr ที่ Bandarion Keep ใน Tirisfal Glades" },
    },
    [97178] = { -- Ott of Tarren Mill
        title = { "18:471783818:844872002", "Ott แห่ง Tarren Mill" },
        description = { "469:270304549:1792964185", "ม้าศึกของพาลาดินต้องมีเกราะที่เหมาะสม ไม่อย่างนั้นก็แทบไม่ต่างจากสัตว์ที่ทำตามสัญชาตญาณ เกราะม้าของเจ้าต้องทำจากวัสดุชั้นดีที่สุดและเหมาะสำหรับปรับให้เชื่อมกับแดนวิญญาณด้วย\n\nนอก Tarren Mill มีช่างตีเหล็กที่เคยทำงานชั้นเยี่ยมให้พาลาดินของเรา เขาเป็นออร์คถ่อมตัวและไม่โอ้อวด แต่งานของเขายอดเยี่ยมและเหมาะกับที่เราต้องการ ไปหาเขาแล้วว่าจ้างให้ทำงานนี้" },
        objective = { "72:286851723:274332973", "คุยกับ Ott ที่หมู่บ้าน Tarren Mill ใน Hillsbrad Foothills" },
    },
    [97179] = { -- Collection of Goods
        title = { "19:615304804:1069074601", "รวบรวมวัสดุ" },
        description = { "443:254705022:1273269045", "เกราะม้าต้องใช้ของหลายอย่าง ผ้า Runecloth สำหรับซับใน แท่ง Arcanite สำหรับทำแผ่นเกราะ Arthas' Tears สำหรับปรับให้เชื่อมกับวิญญาณ และ Stratholme Holy Water สำหรับลงพลังวิญญาณ ส่วนค่าแรงกับค่าอานและโกลนที่จะใช้คู่กับเกราะ ข้าคิดเพียงเล็กน้อย\n\nเอาวัสดุมาให้ข้าแล้วข้าจะทำเกราะม้าให้เสร็จ ระหว่างที่เจ้าหาของ ข้าจะเริ่มทำอานรอ" },
        objective = { "129:1647964144:1981811836", "นำ Runecloth 40 ผืน, Arcanite Bar 6 แท่ง, Arthas' Tears 10 ดอก, Stratholme Holy Water 5 ขวด และเงิน 150 ทองไปให้ Ott ใน Hillsbrad Foothills" },
        required = { [8836] = { "13:588229817:456656669", "หยาดน้ำตาของ Arthas" }, [12360] = { "12:582063918:1116898133", "แท่งอาร์คาไนต์" }, [13180] = { "21:1808788802:870975348", "น้ำศักดิ์สิทธิ์แห่ง Stratholme" }, [14047] = { "9:897047003:553648234", "ผ้ารูน" } },
        objectiveLabels = {
            item = { ["Arthas' Tears"] = "หยาดน้ำตาของ Arthas", ["Arcanite Bar"] = "แท่งอาร์คาไนต์", ["Stratholme Holy Water"] = "น้ำศักดิ์สิทธิ์แห่ง Stratholme", ["Runecloth"] = "ผ้ารูน" },
        },
    },
    [97180] = { -- Ott's Finest Work
        objective = { "75:1405221489:2021016009", "นำ Arcanite Barding ไปให้ Danitha Morr ที่ Bandarion Keep ตรวจดู" },
        title = { "17:1237388129:1875445500", "ผลงานชั้นเยี่ยมของ Ott" },
        description = { "460:1056578794:1047357906 C 1:46:46", "<Ott เช็ดเหงื่อจากหน้าผากแล้วส่งเสียงในลำคออย่างพอใจเมื่อมองผลงาน>\n\nนี่ของเจ้า ปกติข้าทำอาวุธเป็นหลัก แต่นี่อาจเป็นหนึ่งในผลงานที่ดีที่สุดของข้า ขอบใจที่เจ้ากับเพื่อนพาลาดินไว้ใจข้า\n\nDanitha Morr คงอยากเห็นกับตา เอาเกราะม้าไปให้นาง แล้วฝากขอบคุณที่ให้งานนี้แก่ข้าด้วย\n\nLok-tar, {class}" },
    },
    [97182] = { -- An Offering of Vengeance
        objective = { "390:320073667:572402320", "หาอาหารม้าชนิดพิเศษสำหรับเลี้ยงม้าวิญญาณ Nathanos Blightcaller ที่ Eastern Plaguelands อาจหาอาหารชนิดนี้ให้ได้\n\nเดินทางไป Dire Maul ใน Feralas แล้วสังหาร Tendris Warpwood เพื่อปลดปล่อย Ancient Equine Spirit ให้อาหารม้าชนิดพิเศษแก่มันเพื่อให้มันสงบลง\n\nสุดท้าย มอบ Arcanite Barding ให้มัน แล้วหวังว่ามันจะยอมมอบพรที่ต้องการให้" },
        title = { "24:1729064433:520378783", "เครื่องบูชาแห่งการล้างแค้น" },
        description = { "504:1923121903:741664666", "เกราะม้าศึกของพาลาดินต้องรับพรจากวิญญาณม้าที่ทรงพลัง ในซาก Dire Maul มีทรีแอนต์แปดเปื้อนชื่อ Tendris Warpwood กักวิญญาณม้าแบบนี้ไว้ จงชำระแค้นแทนวิญญาณนั้นและปลดปล่อยให้เป็นอิสระ ถ้าโชคดี มันอาจยอมให้พรแก่เจ้า\n\nเพื่อเพิ่มโอกาสสำเร็จ ข้าแนะนำให้เอาอาหารสัตว์ชนิดพิเศษที่ปรับให้เชื่อมกับวิญญาณไปด้วย ไปที่ Eastern Plaguelands แล้วคุยเรื่องนี้กับพรานชื่อ Nathanos Blightcaller" },
    },
    [97183] = { -- Blessed Arcanite Barding
        objective = { "94:605858781:70601765", "นำ Blessed Arcanite Barding กลับไปให้ Danitha Morr ที่ Bandarion Keep ใน Tirisfal Glades" },
        title = { "24:946410299:225895454", "เกราะม้า Arcanite ที่รับพรแล้ว" },
        description = { "471:911880243:922533578", "เมื่อวางเกราะบนหลัง Ancient Equine Spirit เกราะก็ร้อนจนเรืองแสงขาว พลังอัดแน่นในอากาศชั่วขณะ จากนั้นเกราะก็หายจากหลังม้าและมาอยู่ในเป้ของเจ้าอย่างปลอดภัย\n\nแม้จะมีหนังกระเป๋ากั้นอยู่ เจ้าก็ยังสัมผัสความร้อนจากอานได้ ดูเหมือนเครื่องบูชาแห่งการล้างแค้นจะได้รับการยอมรับและเกราะก็ได้รับพรแล้ว ถึงเวลากลับไปหา Danitha Morr ที่ Bandarion Keep" },
    },
    [97184] = { -- The Divination Scryer
        title = { "21:498146847:74165471", "อุปกรณ์หยั่งญาณ" },
        description = { "473:1586964617:216335395", "ตอนนี้เราต้องประกอบ Divination Scryer ซึ่งจำเป็นต่อการทดสอบสุดท้าย กระถางกำยานที่เจ้าใช้ขับวิญญาณที่ Terrordale จะเป็นตัวกระตุ้น ข้าน่าจะทำเรือนอุปกรณ์ที่เหมาะกับมันได้\n\nเหลือชิ้นส่วนสุดท้ายคือเพชรสองเม็ด สีขาวหนึ่งเม็ดและสีดำหนึ่งเม็ด ทั้งสองแทนสองด้านในตัวเราผู้เป็นพาลาดินแห่ง Forsaken และจะเป็นดั่งแสงนำทางให้อุปกรณ์มองทะลุม่านระหว่างคนเป็นกับคนตาย" },
    },
    [97185] = { -- Justice and Retribution
        objective = { "368:1288322297:1344951134", "ใช้ Divination Scryer ใจกลางชั้นใต้ดินของ Great Ossuary ใน Scholomance เพื่อเรียกเหล่าวิญญาณที่เจ้าต้องพิพากษาออกมา เมื่อเอาชนะเหล่าวิญญาณได้ Death Knight Darkreaver จะปรากฏตัว จงปราบเขาแล้วนำดวงวิญญาณที่สูญหายของม้าศึกที่ล้มตายกลับคืนมา\n\nมอบ Spirit of Retribution และ Blessed Enchanted Barding ให้ Darkreaver's Fallen Charger" },
        title = { "23:1213088424:1842023633", "ความยุติธรรมและการลงทัณฑ์" },
        description = { "505:58899652:777721636", "ในกระเป๋านี้มีของที่ต้องใช้ในการทดสอบ ใช้ Divination Scryer ตรงใจกลางชั้นใต้ดินของ Great Ossuary เพื่อเรียกวิญญาณต้องสาปออกมารับการพิพากษา พลังจาก Judgement ของเจ้าจะมีค่ามากในการต่อสู้ครั้งนี้ จงใช้ให้เหมาะ\n\nเมื่อขับไล่วิญญาณเหล่านี้แล้ว Darkreaver จะปรากฏตัว โค่นเขาแล้วนำดวงวิญญาณที่หลงทางของม้าศึกกลับมา ให้มันเห็นหนทางแห่งความยุติธรรมและการลงทัณฑ์ที่เจ้าเดินอยู่ ถ้าโชคดี มันจะยอมมาอยู่เคียงข้างเจ้า" },
    },
    [97186] = { -- Manna-Enriched Horse Feed
        objective = { "216:135123128:1440051246", "หา Enriched Manna Biscuit 20 ชิ้นให้ Nathanos Blightcaller ที่ Eastern Plaguelands เป็นที่รู้กันว่า Argent Dawn เป็นผู้จัดจำหน่ายบิสกิตชนิดนี้เพียงรายเดียว เจ้าต้องจ่ายค่าตอบแทนให้ Blightcaller อีก 50 ทองด้วย" },
        title = { "25:1098678359:872946794", "อาหารม้าเสริม Manna" },
        description = { "433:1500644542:1902259499", "เจ้าต้องการอาหารให้วิญญาณม้าที่ไร้ร่างหรือ? น่าสนใจ\n\nได้ ข้าคงช่วยเจ้าได้ ข้าใช้เวลาเลี้ยงสัตว์ที่... เอาเป็นว่าไม่ได้เป็นของโลกนี้เต็มตัวอีกต่อไป มานานพอจะรู้วิธีประคองพวกมันอยู่บ้าง\n\nข้าต้องการเพียงบิสกิตเสริมพลังวิญญาณที่ Argent Dawn ขาย... กับทองอีกเล็กน้อย เป็นค่าตอบแทนเวลาของข้าน่ะ" },
    },
    [98465] = { -- The Errant Knight
        title = { "17:1771849643:779215552", "อัศวินพเนจร" },
        description = { "14:1649650394:897424258 N 451:11788341:1783087869", "ยินดีต้อนรับกลับมา {name} ข้ามีงานให้ทำ มีข่าวลือว่าคนเห็นพาลาดิน Forsaken ที่หน้าตาคล้าย Garek Bandarion เพื่อนเก่าของข้ามาก กำลังสู้กับพวก Scourge ใน Plaguelands\n\nปัญหาใหญ่คือ Garek Bandarion ตายไปแล้ว ไม่ว่าพาลาดินคนนั้นเป็นใคร เขาอาจต้องการความช่วยเหลือและกำลังใจจากคนอย่างเขา ไปที่ Bulwark ถามข่าวอัศวินคนนี้ ตามหาเขาแล้วพากลับมาหาพวกเรา" },
    },
    [98466] = { -- The Errant Knight
        title = { "17:1771849643:779215552", "อัศวินพเนจร" },
        description = { "300:1991131180:160862240", "ใช่ เขานั่นแหละ Bandarion\n\nข้าเคยเห็นเขาเหวี่ยงดาบในศึกชิง Undercity เมื่อสองสามปีก่อน เห็น Forsaken คนนั้นที่ไหนข้าก็จำได้ ข้าสาบาน แต่ไม่ต้องเชื่อคำข้าก็ได้ ไปหาเขาด้วยตัวเองเถอะ เขาควบม้ามุ่งไป Dalson's Tears ทางตะวันออกเมื่อไม่กี่ชั่วโมงก่อนนี่เอง" },
    },
    [98467] = { -- The Errant Knight
        title = { "17:1771849643:779215552", "อัศวินพเนจร" },
        description = { "121:684258182:1038905851", "เมื่อตรวจซากกูลต่อ เจ้าก็เห็นรอยเท้าหนัก ๆ ทอดออกไปจากจุดที่เกิดการต่อสู้" },
    },
    [98468] = { -- The Errant Knight
        title = { "17:1771849643:779215552", "อัศวินพเนจร" },
        description = { "281:2143637911:846443760", "กระดาษดูเหมือนเป็นคำสั่งที่กล่าวถึงเชลยคนหนึ่ง ลักษณะตรงกับ Forsaken ที่เจ้าตามหา ดูท่าคนพวกนี้จะซุ่มโจมตีและเอาชนะพาลาดินได้ เขายังไม่ถูกทำลาย และตอนนี้ถูกขังอยู่ในค่าย Scarlet Crusade ใกล้ ๆ" },
    },
    [98469] = { -- The Errant Knight
        title = { "17:1771849643:779215552", "อัศวินพเนจร" },
        description = { "416:268647687:1594147277", "แล้วก็ขอบอกไว้ก่อน ข้าไม่ใช่ Garek Bandarion ถ้าข้าเป็นวีรบุรุษอย่างเขา ข้าคงไม่ต้องเจอเรื่องแบบนี้ ข้าชื่อ Xander Salsbury เป็นผู้ติดตามอัศวินที่ฝึกเป็นพาลาดิน หรือเคยเป็น ก่อนที่ข้าจะ... เอาเป็นว่าก่อนกลายเป็นอย่างที่เราเป็นตอนนี้ เป็น Forsaken\n\nส่วนเครื่องแต่งกายกับอาวุธของข้า เรื่องมันยาว ตอนนี้เราควรออกจากที่นี่ก่อน ช่วยพาข้าหนี แล้วค่อยคุยกันต่อเมื่อถึงที่ปลอดภัย" },
    },
    [98470] = { -- The Errant Knight
        title = { "17:1771849643:779215552", "อัศวินพเนจร" },
        description = { "289:260731584:1597745591", "งั้นก็ไม่ใช่ Bandarion ข้าไม่แปลกใจหรอก แต่ยอมรับว่ายังแอบหวังลม ๆ แล้ง ๆ ว่าเขาจะมีชีวิตอยู่ ข้ารู้ว่าเป็นไปไม่ได้ แต่ก็อดหวังไม่ได้\n\nข้าแค่อยากให้ Forsaken ที่เจ้าเจอมาหาเราตั้งแต่แรก เขาคงจะ...\n\nเดี๋ยวก่อน ดูเหมือนเขามาถึงแล้ว" },
    },
    [99187] = { -- The Reliquary of Tyr
        title = { "20:494298045:997478091", "ผอบศักดิ์สิทธิ์ของ Tyr" },
        description = { "495:813023941:872611162", "เจ้าอาจไม่ได้เป็นอัศวินแห่ง Lordaeron แม้ในแง่หนึ่งอาจนับว่าเป็นก็ตาม ถึงอย่างไรเจ้าก็ยังเป็นพาลาดิน และรู้ว่าคำสัตย์มีพลังเพียงใด\n\nชาว Blackmaw ชำนาญวิชาโทเทมอย่างยิ่ง ย่อมรู้ถึงพลังของวัตถุศักดิ์สิทธิ์อย่างผอบนั้น พวกเขาต้องยังเก็บมันไว้แน่\n\nข้าจึงขอให้เจ้าทำภารกิจที่ข้าเริ่มไว้ให้เสร็จ นำ Reliquary of Tyr กลับมาที่ Tirisfal Glades ที่ที่มันควรอยู่ เมื่อนั้นข้าจึงจะพ้นจากคำสัตย์และวิญญาณจะได้จากโลกนี้ไป" },
        objective = { "70:1681940386:518265833", "เดินทางไป Blackmaw Hold ใน Kalimdor แล้วนำ Reliquary of Tyr กลับมา" },
    },
    [7790] = { -- River Ends
        title = { "10:750666668:1348199157", "ปลายทางของสายน้ำ" },
        description = { "336:981832013:334015607", "ภาพตรงหน้าชวนสยดสยอง เอลฟ์สองคนนี้ดูเหมือนสู้กันจนตายทั้งคู่ อะไรทำให้คนที่ปกติสุขุมอย่างพวกเขาลงมือกันดุเดือดขนาดนี้?\n\nกระเป๋ากับอุปกรณ์ของทั้งสองกระจัดกระจายตามตลิ่ง ตกลงกันไม่ลงตัวหรือ? หรือคู่แข่งซุ่มโจมตี?\n\nตามไปที่ต้นน้ำเพื่อหาเบาะแสว่าความตายที่ถูกน้ำพัดลงมานี้เริ่มจากอะไร" },
        objective = { "67:56326611:491916968", "สืบหาสาเหตุการต่อสู้ของชาวสกายบอร์นตามแนวแม่น้ำ Thondroril" },
    },
    [8152] = { -- Rapid Escape
        title = { "12:500753505:1724802793", "หนีฝ่ากระแสน้ำ" },
        description = { "439:539863537:522443745", "น้ำปริมาณมากที่ไหลผ่านโขดหินใต้น้ำตกทำให้ลื่นเสียหลักได้ง่าย ต้นทางน่าจะเป็นแก่งน้ำเชี่ยวที่ไหลทะลักลงสู่ Plaguelands\n\nเครื่องแต่งกายและอุปกรณ์ที่เห็นชัดว่าเป็นของเอลฟ์กระจัดกระจายอยู่ท่ามกลางร่องรอยโศกนาฏกรรมในน้ำ\n\nเจ้าเก็บเศษผ้าสีเข้มขลิบเงินกับด้ามอาวุธเอลฟ์ที่หักใส่กระเป๋า คนที่ Light's Hope Chapel อาจรู้เรื่องความเคลื่อนไหวของเอลฟ์ในดินแดนนี้มากกว่าเจ้า" },
        objective = { "85:1684875534:976691516", "เดินทางไปที่ Light's Hope Chapel แล้วสอบถามคนที่นั่นเรื่องเบาะแสที่เปียกชุ่มน้ำซึ่งเจ้าพบมา" },
    },
    [90625] = { -- On Dreaded Wings
        title = { "16:1916527883:1786202192", "บนปีกแห่งความหวาดกลัว" },
        description = { "140:1649740870:1753281288", "สิ่งเดียวที่เหลือจากจอมอสูร Nathrezim ที่ถูกโค่นคือปีกขาดวิ่นของ Dread Lord Balnazzar\n\nใครสักคนที่ Light's Hope อาจสนใจสิ่งนี้" },
    },
    [92842] = { -- A Cousin Abroad
        title = { "15:609649468:23095147", "ญาติที่อยู่ไกล" },
        description = { "355:396834079:949953059", "เมื่อก่อนญาติข้าคนหนึ่งเคยพูดว่าจะไป Mount Hyjal ดูว่าเกิดอะไรขึ้นที่นั่น เป็นความคิดโง่ ๆ\n\nHyjal อยู่ไกลเหมือนคนละโลก จดหมายอาจเดินทางเป็นเดือนกว่าจะถึงเขา ถ้าเขาหาตู้จดหมายเจอด้วยนะ\n\nถ้าบังเอิญเจ้าต้องไปอีกฟากโลกนั้นจริง ๆ ข้าจะขอบใจมากถ้าช่วยแวะดูญาติตัวดีของข้าหน่อย" },
        objective = { "49:1301305931:968527383", "ตามหาญาติที่หายตัวไปบน Mount Hyjal" },
    },
    [93123] = { -- Buried Bones
        title = { "12:1498241109:375955454", "กระดูกที่ถูกฝัง" },
        description = { "422:84239992:190701056", "โครงกระดูกนี้ดูต่างจากที่เจ้าเห็นในสุสานใต้ดินแห่งนี้ แม้มันจะไม่ขยับ แต่ดูเหมือนมีประกายริบหรี่ลุกอยู่ในเบ้าตากลวง\n\nเจ้าได้ยินเสียงหึ่งแผ่ว ๆ ในหัว ไม่มีถ้อยคำ แต่เหมือนมันกำลัง... วิงวอนขออะไรบางอย่าง ภาพหีบเล็ก ๆ ที่บรรจุโกศเรืองแสงจาง ๆ ปรากฏขึ้นในใจเจ้า\n\nสิ่งที่เจ้าเห็นคือผนึกวิญญาณของลิช" },
    },
    [93126] = { -- The Phylactery
        title = { "14:1229542756:421072932", "ผนึกวิญญาณ" },
        description = { "269:1618496418:663083399", "เห็นชัดว่าถ้าเอาผนึกวิญญาณนี้ให้โครงกระดูก จะปลุกอะไรบางอย่างขึ้นมา ส่วนจะเป็นอะไรก็ยากจะเดา ถ้าคิดจะทำต่อ ควรเตรียมตัวสู้ไว้\n\nถ้ารอดออกมาได้ ก็ควรเล่าให้ใครสักคนฟังว่าเจ้าเห็นอะไรข้างล่างนี้" },
    },
    [93314] = { -- The Gods of the Summit
        title = { "22:1655912912:1785230497", "เหล่าเทพแห่งยอดเขา" },
        description = { "407:85924690:1906085537", "<Jereman ขยับตัวถ่ายน้ำหนัก ขนตั้งชันด้วยความโกรธและขบจะงอยปากอย่างไม่พอใจ>\n\nข้าไม่รู้ว่าอะไรรอเราอยู่ แต่ความผิดปกติบนภูเขารุนแรงอย่างที่ข้าไม่เคยสัมผัสมาหลายศตวรรษ หลังได้เจอเวทของราชาพงไพรกับกรงเล็บตัวเอง ข้ารู้แล้วว่าต้องหยุดเขา\n\nข้าได้แต่ภาวนาว่าเรามาทันช่วยเทพแห่งพงไพรองค์อื่นที่อยู่ที่นี่" },
    },
    [95993] = { -- Useless Lump of Coal
        title = { "20:455576907:1991003881", "ถ่านก้อนที่ดูไร้ค่า" },
        description = { "117:745180342:1901737331", "<ในหีบมีเพียงถ่านก้อนหนึ่งที่ไม่แสดงปฏิกิริยาใด ๆ\n\nแม้เจ้าจะเห็นว่าไร้ประโยชน์ แต่บางคนอาจเห็นค่าของมัน>" },
    },
    [97197] = { -- Fragment of the Firelands
        title = { "25:1023128739:1281717265", "เศษเสี้ยวจาก Firelands" },
        description = { "493:382333656:2041700884", "Muln บอกข้าว่าลึกเข้าไปในที่ที่เรียกว่า Blackrock Mountain มีจุดที่ม่านกั้นระหว่าง Azeroth กับระนาบธาตุเสียหาย ทำให้สิ่งมีชีวิตธาตุจากอาณาจักร Firelands หลุดเข้ามาในโลกนี้มากมาย รวมถึงยักษ์ที่ตัวใหญ่พอ ๆ กับ Anchor Pylon!\n\nข้าอยากศึกษาเศษวัสดุที่เก็บได้จากสิ่งมีชีวิตพวกนั้นมาก เจ้าจะยอมฝ่า Blackrock Depths แล้วเอาตัวอย่างกลับมาให้ข้าไหม?" },
        objective = { "92:1247622291:255226267", "นำ Fragment of the Firelands จาก Blackrock Depths ไปให้ Alaana Stormwalker ใน Mulgore" },
    },
    [97273] = { -- The Darkened Glaive
        title = { "19:1612681649:1850660523", "ดาบวงแหวนต้องมลทิน" },
        description = { "421:828514413:1446101590", "กลับลงไปลึกใน Barrow Deeps ตามล่าปีศาจที่ทำให้ Quel'Shalla แปดเปื้อน อย่าผงะถอยจากพลังของมัน จงเผชิญหน้าตรง ๆ เข้ารับพลังนั้นแล้วปล่อยให้ดาบวงแหวนดื่มพลังของมัน... ดื่มแก่นแท้ของมัน\n\nคมดาบกระหายสิ่งนี้ มันจะบอกเจ้าเองเมื่อถึงเวลา พอ Quel'Shalla ดับความกระหายแล้ว จงใช้พลังของมันลบล้างปีศาจตนนั้นให้สิ้นไปตลอดกาล" },
    },
    [97319] = { -- A Cousin Abroad
        title = { "15:609649468:23095147", "ญาติที่อยู่ไกล" },
        description = { "310:932000600:78497939", "ญาติข้าคนหนึ่งที่ Kalimdor ตะลุยผ่านสถานที่อันตรายที่สุดแถวนั้นมาเรื่อย ๆ ข่าวล่าสุดบอกว่าเขากำลังไป Mount Hyjal\n\nข้าว่าช่างเสียเวลาอย่างน่าขัน\n\nถ้าบังเอิญเจ้าไปถึงส่วนนั้นของโลกก็คงดีถ้าช่วยดูให้หน่อยว่าเขายังไม่พาตัวเองไปตาย อย่างน้อยก็ยังไม่ตายตอนนี้" },
        objective = { "49:1301305931:968527383", "ตามหาญาติที่หายตัวไปบน Mount Hyjal" },
    },
    [97447] = { -- An Earnest Proposition
        title = { "22:1183475074:147978204", "ข้อเสนอที่จริงใจ" },
        description = { "10:1401179418:1568553899 C 483:1797862860:229612946", "ยินดีที่ได้พบ {class} ข้ามีของที่เจ้าอาจสนใจ\n\nข้ามีชุดเกราะที่คล้ายกับชุดของคนในอาชีพเจ้า แต่คุณภาพดีกว่ามาก ข้ายอมเอาปลอกแขนของชุดนี้มาแลกกับปลอกแขนธรรมดา ถ้าเจ้าช่วยอะไรเล็ก ๆ น้อย ๆ ให้\n\nเลือดของฟรอสต์เซเบอร์กับหมีใน Winterspring มีคุณสมบัติที่ข้าต้องการตอนนี้ เอาตัวอย่างเลือดมาให้มากพอ พร้อมปลอกแขนกับทองเล็กน้อย รับรองว่าคุ้มแรง" },
        objective = { "134:1342213076:2137695916", "รวบรวม Winterspring Blood Sample 15 ชิ้นและเงิน 20 ทอง แล้วนำไปพร้อมกับ Bindings of the Elements หนึ่งชุดให้ Deliana ใน Ironforge" },
    },
    [97448] = { -- Just Compensation
        title = { "17:479802657:1407557245", "ค่าตอบแทนที่เหมาะสม" },
        description = { "262:1424199253:1454299520", "เจ้ารักษาคำพูดและนำอุปกรณ์ที่ Mux สร้างมาให้ ข้าว่าควรมีรางวัลให้เจ้าสักหน่อย ถ้าข้ายังอยากให้เจ้าช่วยรักษาชีวิตข้าต่อ เอาเข็มขัดกับถุงมือเกราะคู่ที่อยากยกระดับมาให้ข้า รับรองว่าของที่ให้คืนจะดีกว่ามาก" },
    },
    [97449] = { -- Anthion's Parting Words
        title = { "23:573656928:1309079977", "คำลาของ Anthion" },
        description = { "458:1132217706:1938632134", "วิญญาณของ Valthalak ถูกเก็บไว้ในเครื่องรางนี้ ด้วยความโลภ เราโง่เขลาแยกมันออกเป็นสามชิ้น โดยไม่รู้เลยว่าคำสาปอะไรรอเราอยู่\n\nทางเดียวที่จะหยุดมนตร์ของ Valthalak ได้คือประกอบเหรียญเครื่องรางกลับให้ครบ กลับไปหา Deliana แล้วบอกนางว่า Bodley คือความหวังเดียวที่จะหาชิ้นส่วนที่เหลือเจอ คุยกับนางเรื่องรางวัลที่เจ้าตกลงไว้ด้วย\n\nในที่สุดข้าจะได้พักอย่างสงบเสียที ขอให้เจ้าโชคดีที่สุด เจ้าต้องใช้โชคทั้งหมดที่มี!" },
    },
    [97450] = { -- Saving the Best for Last
        title = { "24:1236774670:147360432", "เก็บสิ่งดีที่สุดไว้ท้ายสุด" },
        description = { "25:844643537:875693802 N 212:492088852:399430903", "เรื่องน่าทึ่งจริง ๆ {name}! เจ้าควรได้รับคำขอบคุณจากข้า และความซาบซึ้งใจจากทุกคนที่เกี่ยวข้อง ทีนี้ข้าอาจได้นอนหลับตาทั้งสองข้างเสียที\n\nส่วนรางวัลของเจ้า ข้าคิดว่ามีของอยู่สองสามอย่างที่เจ้าต้องชอบแน่" },
    },
    [97663] = { -- Supplies and Studies
        title = { "20:1125611222:452156832", "เสบียงและงานค้นคว้า" },
        description = { "492:1080237593:2043938871", "ข้าเห็นหินรูปร่างแปลกอยู่สองสามก้อนใน Dustbowl พอเข้าไปดูใกล้ ๆ ก็เห็นว่ามีรอยสลัก! ข้าอดลอกรอยสลักด้วยการถูทับไว้ศึกษาทีหลังไม่ได้\n\nพวกโอเกอร์แถวนั้นสังเกตเห็นข้า ยังไม่ทันได้ตั้งตัว ข้าก็ตื่นมาอยู่ในความดูแลของเจ้าของโรงเตี๊ยมแล้ว ปวดหัวแทบแตก\n\nตอนนี้ของใช้หายหมดและไม่มีอะไรให้ศึกษาระหว่างพักฟื้น เจ้าช่วยมุ่งหน้าไปทางตะวันออกตามหากระเป๋าข้า แล้วลอกรอยสลักด้วยการถูทับมาด้วยได้ไหม?" },
        objective = { "156:1700638562:1760083087", "ฆ่าอ็อกเกอร์ใน Dustbowl เพื่อชิง Mus'hale's Stolen Supplies แล้วใช้อุปกรณ์นั้นทำสำเนาลายสลักหินที่อยู่ใกล้ ๆ จากนั้นกลับไปหา Mus'hale ที่ Kargath" },
        completion = { "151:1715316629:713445825 N 179:2086876297:1325123709", "เสบียงของข้า! แล้วเจ้าหา...\n<Mus'hale พบแผ่นหนังที่มีลายมือหวัดทันทีที่เปิดถุงเสบียง>\nข้าซาบซึ้งที่เจ้าช่วย {name} ได้ของของข้าคืนกับเรื่องให้อ่านศึกษา ก็มีอะไรทำฆ่าเวลาเหลือเฟือระหว่างพักฟื้นแล้ว คืนนี้ข้ายังมีเงินพอนอนในกระท่อมด้วย\nลาก่อน สหาย" },
        progress = { "18:962179946:809732690", "มีโชคบ้างไหม?" },
        required = { [278515] = { "26:137705036:1976260531", "เสบียงของ Mus'hale ที่ถูกขโมย" } },
        steps = { { "18:1254610499:487271991", "ภาพถูรอยสลักหินแผ่นเล็ก" }, { "18:267910885:189774525", "ภาพถูรอยสลักหินแผ่นใหญ่" }, { "26:137705036:1976260531", "เสบียงของ Mus'hale ที่ถูกขโมย" } },
    },
    [97883] = { -- End of the Dark Horde
        objective = { "65:157456567:2083237078", "นำ Head of Rend Blackhand ไปให้ Major Mattingly ที่ Stormwind" },
        title = { "21:975000302:1906537021", "จุดจบของฮอร์ดทมิฬ" },
        description = { "230:899277676:1443735956 N 52:1313151998:324845440", "นำหัวของ Blackhand ไปให้ Major Mattingly ที่ประตูเมือง เขากับทหารจะประกาศชัยชนะครั้งใหญ่ที่เจ้าคว้ามาวันนี้ ให้คนอื่น ๆ ในฝ่ายพันธมิตรได้มีกำลังใจจากชัยชนะนี้\n\nวันนี้เจ้าผดุงความยุติธรรมครั้งใหญ่ {name} ทุกคนจะจดจำไว้ รวมถึงศัตรูของเราด้วย" },
    },
    [97986] = { -- Argent Arbiter
        title = { "14:574145939:1439723841", "ผู้ชี้ขาดแห่ง Argent" },
        description = { "425:1487830270:996513401", "Hailen หน่วยสอดแนมคนหนึ่งของ Argent ได้รับมอบหมายให้สำรวจรอบนอกและที่สูง ปกตินางกลับค่ายทุกสองสัปดาห์\n\nฟังจากที่เจ้าเล่า ซากที่พบอาจเป็นของนาง แต่เราไม่เห็นชาว Skyborne คนอื่นแบบที่เจ้าเห็นริมแม่น้ำ\n\nเรามีค่ายภาคสนามอีกแห่งทางตะวันตกเฉียงเหนือของ Blackwood Lake หมอสนามที่นั่นอาจรู้เรื่องนี้ด้วย แนวหน้ามีอะไรให้เห็นมากกว่าที่นี่เยอะ" },
        objective = { "108:631507148:240678607", "คุยกับเจ้าหน้าที่แพทย์ที่ค่ายภาคสนามอีกแห่งของ Argent Dawn ทางตะวันตกเฉียงเหนือของ Blackwood Lake ใน Eastern Plaguelands" },
    },
    [97987] = { -- Stormwind's High Order
        title = { "22:1688722672:2045802862", "High Order แห่ง Stormwind" },
        description = { "501:1433819202:1488317696", "ช่วงที่หน้าผาถล่ม ข้าได้ยินเสียงเครื่องยิงลูกศรของเอลฟ์ ลูกศรตกใกล้บ้านข้าตรงถนนไป Quel'Thalas อย่างอันตราย\n\nข้าหนีออกมา ทิ้งกองต้นไม้กับซากหินที่ถล่มไว้ข้างหลัง ข้าได้ยินเสียงตะโกนเป็นภาษา shen'dorei แน่ ๆ! เสียงบาดหูแม้แต่สำหรับข้า จับได้เพียงไม่กี่คำ «คนทรยศ» «เลือด» «ศัตรู»\n\nข้าแนะนำให้เอาข่าวนี้ไปบอก Saera Wirraway ชาว Skyborne ฝ่าย High Order ที่ Park ใน Stormwind แม้ไม่ได้มาจากสายเดียวกัน ครั้งหนึ่งเราก็ใฝ่หาคำตอบเหมือนกัน" },
        objective = { "51:1100305234:763665517", "คุยกับ Saera Wirraway ที่ The Park ใน Stormwind" },
    },
    [97988] = { -- Orgrimmar's Windshapers
        title = { "23:968738490:669393881", "Windshaper แห่ง Orgrimmar" },
        description = { "501:2006012768:642959446", "ช่วงที่หน้าผาถล่ม ข้าได้ยินเสียงเครื่องยิงลูกศรของเอลฟ์ ลูกศรตกใกล้บ้านข้าตรงถนนไป Quel'Thalas อย่างอันตราย\n\nข้าหนีออกมา ทิ้งกองต้นไม้กับซากหินที่ถล่มไว้ข้างหลัง ข้าได้ยินเสียงตะโกนเป็นภาษา shen'dorei แน่ ๆ! เสียงบาดหูแม้แต่สำหรับข้า จับได้เพียงไม่กี่คำ «คนทรยศ» «เลือด» «ศัตรู»\n\nเอาข่าวนี้ไปบอก Corswyn Aseril ชาว Skyborne ฝ่าย Windshaper ที่ Valley of Wisdom ใน Orgrimmar แม้ไม่ได้มาจากสายเดียวกัน ครั้งหนึ่งใจเราก็มุ่งหาความจริงเดียวกัน" },
        objective = { "58:1899015869:531650836", "ไปคุยกับ Corswyn Aseril ใน Valley of Wisdom ของ Orgrimmar" },
    },
    [98109] = { -- Bleeding Edge
        title = { "13:621722964:1501318305", "แนวหน้าที่เลือดหลั่ง" },
        description = { "490:261759299:1671693517", "ครั้งสุดท้าย Hailen บอกว่าจะไปสำรวจแค่พื้นที่ทางเหนือ ถ้าคนที่เจ้าพบคือนาง เรื่องนี้ต้องมีอะไรอีก รายงานฉบับสุดท้ายของนางมีข่าวกรองสำคัญเกี่ยวกับ Quel'Lithien Lodge ที่มั่นอันแข็งแกร่งของเหล่าพราน\n\nมีไฮเอลฟ์ชื่อ Adon อาศัยอยู่ทางตะวันตกเฉียงเหนือของซาก Northdale ใกล้ถนนไป Quel'Thalas เขาอาจเข้าใจความเคลื่อนไหวของเอลฟ์ในดินแดนแถบนี้ดีกว่าเรา\n\nข้าจะจัดพิธีฝังให้ดวงวิญญาณนี้เอง ไม่ว่าจะเป็นใครก็ตาม" },
        objective = { "93:1531227611:434709691", "คุยกับไฮเอลฟ์ชื่อ Adon ทางตะวันตกเฉียงเหนือของซากเมือง Northdale บนถนนที่มุ่งไป Quel'Thalas" },
    },
    [98203] = { -- Witch Doctor Ti'ik
        title = { "18:671342299:2070637248", "หมอผี Ti'ik" },
        description = { "495:1599186043:1644266152", "พวก Witherbark รู้ว่าเรากำลังล่ามันอย่างที่คนทรยศสมควรโดน มันกำลังวางแผนและหาที่ซ่อนให้เผ่าหลบอยู่ในเงา แม้หลังจากเราเอาไฟเผามันเพื่อตอบแทนการหลอกลวง\n\nหน่วยสอดแนมเจอถ้ำทางตะวันตกของ Hiri'watha หมอผีชื่อ Ti'ik เอาวูดูเข้าไปทำในนั้น ทั้งของเน่า ของผุ และตัวอ่อนยั้วเยี้ยสำหรับทำมนตร์ชั่วร้าย\n\nเราจะไม่ปล่อยให้ของโสโครกนั่นคลานผ่านบ้านตอนเราหลับ ไปเอาหัวมันมา แล้วบดขยี้สิ่งที่พวกมันเพาะอยู่\n\nมันเอาเรื่องอยู่ อย่าประเมินมันต่ำไปล่ะ" },
        objective = { "102:41963379:605938743", "ฆ่า Ti'ik หมอผีเผ่า Witherbark ในถ้ำทางตะวันตกของ Hiri'watha แล้วนำหัวของเขากลับมา" },
        completion = { "180:2027546575:2061223742", "นี่แหละตัวที่ว่า เห็นแล้วสยองจริง ๆ\nทั้งไข่แมงมุมทั้งหนอน เราไม่อยากให้มีของพวกนี้ในหมู่บ้าน\nไปเถอะ ขอให้เหล่าโลอานำทางเจ้า ชาว Revantusk ขอบใจที่เจ้าช่วยกำจัดตัวกวนพวกนี้" },
        progress = { "42:2019997588:2082660496", "ไปหา Ti'ik ในถ้ำที่เต็มไปด้วยตัวอ่อนมาแล้วหรือ?" },
        steps = { { "25:1549945387:1233655529", "ศีรษะของ Witch Doctor Ti'ik" } },
    },
    [98325] = { -- Blood and Thunder
        title = { "17:62125220:1460472560", "เลือดและสายฟ้า" },
        description = { "40:832402845:1218295943 C 175:1009933436:1130865336 R 106:558375973:789630158", "ข้าตามหายอดฝีมือที่สุดของฮอร์ด {class} ข้าต้องการเฉพาะคนที่เก่งที่สุดเท่านั้น\n\nงานบางอย่างต้องใช้ความกล้าอย่างที่มีเพียงไม่กี่คน และยิ่งมีน้อยกว่านั้นที่ยอมเสี่ยงชีวิตเมื่อถึงคราวสำคัญจริง ๆ\n\nเจ้าคู่ควรกับชื่อชาว{race} พอจะทำสิ่งที่ต้องทำหรือไม่? ถ้าคู่ควร เรามาคุยกัน\n\nถ้าไม่ ก็ไสหัวไป ข้าไม่มีเวลาให้ความขลาด" },
        objective = { "68:709024665:400679042", "คุยกับ Warlord Goretooth เพื่อเข้าช่วยกองกำลังสำรวจ Kargath" },
    },
    [99435] = { -- The Great Masquerade
        title = { "20:441805315:991062262", "มหาหน้ากากลวง" },
        description = { "72:885764080:2029960376 C 379:113713190:1247058904", "Windsor ออกไปเผชิญหน้ากับ Lady Prestor ที่ Stormwind Keep แล้ว {class} เขาชมความกล้าของเจ้าไว้มาก ข้าแนะนำให้รีบไปช่วยเขา!\n\nตอนนี้เขามั่นใจแล้วว่า Prestor คือ Onyxia ทายาทของ Deathwing ฝาแฝดของ Nefarian ทรราชแห่งยอดเขา\n\nเขาบอกว่าแม้แต่ Highlord ก็ยังถูกเล่ห์กลของนางควบคุม! จอมพลตั้งใจจะทำลายมนตร์และปลด Stormwind ทั้งเมืองจากเงามืดของพวกปีศาจนี้\n\nไปหาเขาแล้วดูให้งานสำเร็จ!" },
        objective = { "133:573745938:688458827", "ตาม Reginald Windsor ไปตามทางใน Stormwind และคุ้มกันเขาให้ปลอดภัย หากต้องการติดต่อ Reginald Windsor อีกครั้ง ให้ไปคุยกับ Squire Rowe" },
    },
    [99600] = { -- The Darkness Below
        title = { "18:216468770:1762399497", "ความมืดเบื้องล่าง" },
        description = { "318:1623532977:652571602", "เราช่วยพวกพ้องของข้าเท่าที่ทำได้แล้ว แต่เรื่องนี้ยังอีกไกลกว่าจะจบ มีบางอย่างผิดปกติหนักมากในความมืดข้างล่างนี้\n\nมีอะไรโบราณอยู่ข้างล่าง ใช่... โบราณมากจริง ๆ แล้วก็มี... ความเจ็บปวดและความสูญเสีย ไม่ว่าความรู้สึกนี้คืออะไร มันทำเอาข้าขนลุก\n\nไม่ว่าพวกดรูอิดกำลังทำอะไร เราต้องหยุดพวกมัน" },
    },
    [99602] = { -- The Wild King Must Die
        title = { "22:211664302:246714685", "ราชาพงไพรต้องตาย" },
        description = { "222:160782870:923107865 N 232:440802870:1253105105", "Valdrus Blackthorne «ราชาพงไพร»\n\n<Jereman ส่งเสียงขู่ต่ำ ๆ>\n\nเขาหันหลังให้คำสัตย์ของดรูอิดและต้องชดใช้ความผิดต่อระเบียบธรรมชาติ! มีเพียงเลือดที่จะชดใช้ความเสียหายที่เขาก่อไว้ที่นี่ได้\n\nไปเถิด {name}! เข้าไปในอาณาเขตของราชาพงไพรแล้วจบชีวิตเขา\n\nข้าจะอยู่ที่นี่กับ Nythus คอยคุ้มกันเขาจากกองกำลัง Blackthorne ที่อาจยังเหลืออยู่ และกันไม่ให้ใครมาขัดขวางตอนเจ้าลงโทษราชาพงไพร" },
    },
    [620] = { -- The Monogrammed Sash
        title = { "20:27727881:1276153568", "ผ้าคาดเอวปักอักษรย่อ" },
        description = { "62:853922211:1750635536", "ผ้าคาดเอวเนื้อดีผืนนี้มีตัวอักษร «HS» ปักอยู่ตามชายผ้า" },
        objective = { "41:1748443037:1255699605", "นำผ้าคาดเอวปักอักษรย่อ (Monogrammed Sash) ไปคืนเจ้าของ" },
    },
    [91760] = { -- Backup Plan
        title = { "11:333023166:94215512", "แผนสำรอง" },
        description = { "133:1665447088:329528577", "อุปกรณ์โรยตัวบ่งบอกว่ามีปฏิบัติการบางอย่างกำลังดำเนินอยู่บนกำแพงเขื่อนหรือบริเวณใกล้เคียง และเจ้าเพิ่งเข้าไปขัดจังหวะ" },
    },
    [92878] = { -- Lost for Words
        title = { "14:1004649864:1386871182", "พูดไม่ออก" },
        description = { "268:1820008435:931590686", "<ชาว Forsaken ชี้ไปที่ขากรรไกรล่างที่หายไป แล้วส่งกระดาษที่มีข้อความเขียนหวัด ๆ ให้เจ้า>\n\nพูดไม่ได้ เสียกรามตอนสู้ โดนพวก Grimtotem เล่นงาน ดรูอิดนำมา Namida ค่ายอยู่ทางตะวันตกเฉียงเหนือ\n\nนางต้องชดใช้\n\n<ประโยคสุดท้ายขีดเส้นใต้สองเส้น>" },
        objective = { "78:87562885:504506860", "นำหลักฐานว่า Namida Grimtotem ตายแล้วไปให้ Blaise Montgomery ที่ Camp Mojache" },
        completion = { "183:1560570651:1937842407", "<Blaise หัวเราะเสียงครืดคราดออกมาจากลำคอ เขาเก็บกีบของ Namida ลงกระเป๋า แล้วขีดเขียนอีกบรรทัดใต้ข้อความแรกที่เขาเขียนให้เจ้า>\nสมน้ำหน้า!" },
        progress = { "52:279335097:72443656", "<Blaise ชี้ไปที่โน้ตที่เขาให้เจ้า ย้ำให้เจ้าดูอีกครั้ง>" },
        required = { [254877] = { "13:337180097:2138457555", "กีบของ Namida" } },
        steps = { { "13:337180097:2138457555", "กีบของ Namida" } },
    },
    [95144] = { -- Overseas Delivery
        title = { "17:2133929208:540303009", "ส่งของข้ามทะเล" },
        description = { "488:1952066589:231661202", "นี่พวก มีพัสดุต้องส่งให้เพื่อนเก่าข้าคนหนึ่ง จะทำอะไรก็ทำ แต่...\n\nห้ามเปิดพัสดุเด็ดขาด!\n\nเอานี่ไปให้ Friz Frazzlespark ที่เมืองท่าพี่น้องของเราใน Riverglades อีกฟากทะเล ถือไปดี ๆ ล่ะ แล้วก่อนจะถาม ข้าไม่แนะนำให้ว่ายน้ำไป คนก่อนลองแล้วจบไม่ค่อยสวย อ้อ อย่าเอียง อย่าเขย่า และอย่าขยับพรวดพราด\n\nข้าแนะนำให้ไปทางตะวันออกยัง Steamwheedle Port เรือจากที่นั่นมักพาข้ามไปได้อย่างปลอดภัย\n\nขอให้โชคดีนะ!" },
        objective = { "98:919973012:120429278", "นำ Fizzgrimble's Mysterious Crate ไปให้ Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades" },
        completion = { "261:1141381174:2020212096", "พัสดุจาก Fizzgrimble สหายเก่าของข้าหรือ? นี่แหละที่ข้ารออยู่!\n\nระหว่างถือมา เจ้าไม่ได้เขย่า เอียง หรือขยับมันแรง ๆ ใช่ไหม?\n\nช่วยหันหลังให้ข้าดูข้างในหน่อยได้ไหม? เดี๋ยวเจ้าเห็นก่อนจะเสียเรื่องเซอร์ไพรส์" },
    },
    [95385] = { -- Torn Mystical Scroll
        title = { "20:1462662668:1200180220", "ม้วนคัมภีร์เวทที่ฉีกขาด" },
        description = { "229:724071823:2029271538", "<เวทจาง ๆ แผ่ออกมาจากเศษม้วนคัมภีร์ ภาษาในนั้นไม่คุ้นตา แต่เจ้ารู้สึกว่ามันไม่เป็นอันตราย คนส่วนใหญ่คงคิดว่าแผ่นหนังนี้ไร้ค่า แต่นักสะสมที่ชอบของแปลกสักคนอาจเอาไปใช้ประโยชน์ได้>" },
        objective = { "59:139561675:125664886", "นำชิ้นส่วนม้วนคัมภีร์ไปให้ Dudd Fizzlescroll ใน Booty Bay" },
        completion = { "269:1357255462:1856369394", "ม้วนคัมภีร์เวทมนตร์หรือ? วันนี้โชคเข้าข้างข้าจริง ๆ! ข้าจะคัดอักขระพวกนี้ไปใช้ในงานของข้า แล้วเจ้าจะได้เห็นกับตาว่าวิศวกรระดับตำนานถือกำเนิดขึ้นอย่างไร แต่อย่าเข้ามาใกล้เกินไปล่ะ ข้าไม่อยากต้องแบ่งค่าลิขสิทธิ์ให้เจ้า... เอ่อ ข้าหมายถึงไม่อยากให้เจ้าบาดเจ็บ" },
    },
    [95555] = { -- Corrupted Nature
        title = { "16:1261480368:691411120", "ธรรมชาติที่แปดเปื้อน" },
        description = { "286:1531895341:1871207606", "<พลังผิดธรรมชาติแผ่จากคทา บิดกระแสเวทตามธรรมชาติรอบตัวเจ้าจนผิดรูป แม้จะรบกวนขนาดนี้ เจ้าก็วางมันลงไม่ได้ จากที่ไกลออกไป เจ้าสัมผัสพลังชั่วร้ายคล้ายกันที่สั่นพ้องและดึงดูดเจ้า บางทีเจ้าอาจตามหาต้นตอของของต้องสาปชิ้นนี้ได้>" },
        objective = { "56:529569257:1455270496", "ตามหาต้นตอของพลังชั่วร้ายที่ตรวจพบจากไม้เท้าใน Feralas" },
    },
    [95556] = { -- Corrupted Nature
        title = { "16:1261480368:691411120", "ธรรมชาติที่แปดเปื้อน" },
        description = { "302:1161255463:1350517353", "<คทาแปดเปื้อนแตกเป็นผงขณะที่พลังธรรมชาติที่เสื่อมทรามทะลักออกมา ค้างหนาทึบอยู่ในอากาศครู่หนึ่ง ในที่สุดพลังนั้นก็จางหาย ถอยกลับเข้าไปในเนื้อไม้ที่กลายเป็นหิน แสงชวนหวั่นใจเปล่งจากร่างผู้เดินป่าที่ติดมลทิน เมื่อพลังไหลกลับเข้าร่าง มันก็ฟื้นขึ้นมาแพร่มลทินอีกครั้ง>" },
    },
    [95586] = { -- Coded Messages
        title = { "14:1983459935:255079552", "ข้อความเข้ารหัส" },
        description = { "437:326941809:1562074158", "ระหว่างทำสมาธิเพื่อหยั่งญาณ ข้าได้ยินพวกนักเวทเงา Wastewander ทางตะวันตกกระซิบเรื่องปีศาจตนใหม่ ข้าต้องรู้ให้มากกว่านี้!\n\nพวกมันติดต่อกันด้วยข้อความเข้ารหัส ข้าเคยเห็นแต่ถอดได้ไม่หมด ต้องใช้คู่มือถอดรหัสที่พวกโจรระดับล่างพกอยู่จึงจะแกะรหัสได้\n\nฆ่านักเวทเงา Wastewander ที่พบแล้วค้นหาข้อความใหม่จากตัวมัน จากนั้นค้นศพโจร Wastewander เพื่อหาคู่มือถอดรหัส" },
    },
    [95588] = { -- Party Crasher
        title = { "13:1158116743:1527651647", "ชิงตัดหน้าพิธี" },
        description = { "463:1119088691:708862444", "ข้าถอดรหัสได้แล้วว่าพวกโจร Wastewander กำลังทำอะไร ดูเหมือนมันพบคาถาอัญเชิญโบราณแล้วฟื้นคาถานั้นขึ้นมา ข้ารู้อยู่แล้วว่ามันมีเรื่องน่าสนใจในมือ\n\nข้อความที่เจ้าเอามาบอกว่ามันจะอัญเชิญปีศาจคืนนี้ ไปที่ลานพิธีในค่าย Wastewander ทางตะวันตก ร่ายคาถาอัญเชิญตัดหน้าพวกมันแล้วฆ่าปีศาจเสีย ข้าจะสัมผัสได้ทันทีที่แก่นพลังของมันสลาย และจะยินดีนัก" },
    },
    [96075] = { -- In Demand - Blackrock Legal Records
        title = { "35:339949126:748374031", "ของที่ต้องการ เอกสารสิทธิ์ Blackrock" },
        description = { "491:1775281209:1473915455", "นายจ้างของข้าอยากได้เอกสารทางกฎหมายเกี่ยวกับกรรมสิทธิ์ใน Blackrock Mountain คงมีข้อพิพาทเรื่องทรัพย์สินอะไรสักอย่าง ยังไงก็ตาม ถ้าเจ้าหาเอกสารสำคัญพวกนี้มาได้ ข้าจ่ายรางวัลให้ได้อย่างงาม\n\nนำ Nefarian's Remit จาก General Drakkisath ในส่วนบนของ Blackrock Spire, Overseer's License จาก Overlord Wyrmthalak ในส่วนล่าง และ Bronzebeard Wedding Contract จาก Emperor Thaurissan ใน Blackrock Depths กลับมา" },
    },
    [96076] = { -- In Demand - Ancient Elven Curiosities
        title = { "37:370984064:2001617182", "ของที่ต้องการ ของวิเศษเอลฟ์โบราณ" },
        description = { "463:1236595533:1175920699", "นายจ้างของข้าอยากได้ของวิเศษจากนครเอลฟ์ร้าง Eldre'Thalas ที่ตอนนี้เรียกว่า Dire Maul คงเอาไปวิจัยเวทอะไรสักอย่าง ยังไงก็ตาม ถ้าหาของพวกนี้มาได้ ข้าจ่ายรางวัลให้ได้อย่างงาม\n\nนำ Felvine Seed จาก Alzzin the Wildshaper ในปีกตะวันออก, Ancient Memento จาก Prince Tortheldrin ในปีกตะวันตก และ Earthstone Diamond Pinky Ring จาก King Gordok ในปีกเหนือกลับมา" },
        objective = { "215:530526725:592137258", "ไป Dire Maul เพื่อเอา Felvine Seed จาก Alzzin the Wildshaper, Ancient Memento จาก Prince Tortheldrin และ Earthstone Diamond Pinky Ring จาก King Gordok แล้วนำทั้งสามอย่างไปให้ Pix Xizzix ใน Booty Bay" },
    },
    [96087] = { -- In Demand - Plague Records
        title = { "26:1985748750:252457344", "ของที่ต้องการ บันทึกโรคระบาด" },
        description = { "461:320537299:1755288440", "นักประวัติศาสตร์กลุ่มหนึ่งจ้างข้าให้ตามหาบันทึกเรื่องโรคระบาดครั้งใหญ่ คงจะพิสูจน์ว่าใครผิดใครไม่ผิดอะไรทำนองนั้น หาเอกสารพวกนี้มาให้ข้า แล้วจะได้รางวัลอย่างงาม\n\nนำ Headmaster's Records จาก Darkmaster Gandling ใน Scholomance, Grain Shipment Orders จาก Baron Rivendare ในนคร Stratholme ที่ไฟลุกไม่ดับ และ Dathrohan's Correspondence จาก Grand Crusader Saidan Dathrohan ใน Scarlet Bastion ของ Stratholme กลับมา" },
    },
    [96088] = { -- In Demand - Titan Relics
        title = { "24:1849792662:872751910", "ของที่ต้องการ โบราณวัตถุแห่งไททัน" },
        description = { "439:1215202438:1720051587", "นักวิจัยจาก Dalaran กำลังตามหาของโบราณจากเหล่าไททัน ผู้ติดตามของพวกเขา และศัตรูของพวกเขาใน Burning Legion ของพวกนั้นอยู่ตามจุดเข้าถึงยากที่ข้าไปไม่ถึง เอากลับมาให้ข้าแล้วจะได้รางวัลอย่างงาม\n\nนำ Ysera's Tear จาก Shade of Eranikus ใน Temple of Atal'Hakkar, Mark of Xavius จาก Varrox Bleakhoof ใน Blackmaw Hold และ Freya's Sigil จาก Nanaya ใน Shaper's Terrace กลับมา" },
    },
    [96912] = { -- Field of Honor: Week 1
        title = { "22:1912183961:1232463557", "สนามเกียรติยศ สัปดาห์ที่ 1" },
        description = { "226:1866633858:1976730837", "เฮ้ เพื่อน เข้ามาเลย! ดูท่าเจ้าจะรู้ว่าต้องเอาดาบด้านไหนแทงนะ!\n\nพอดีข้ามีรายการคำท้ายาวเหยียดที่มีแต่นักสู้ชั้นยอดเท่านั้นจะทำสำเร็จ อยากลองสักตั้งไหม?" },
        objective = { "13:70468311:1354251791", "ชนะการดวล 10 ครั้ง" },
    },
    [96921] = { -- Field of Honor: Week 10
        title = { "23:1805006509:391453840", "สนามเกียรติยศ สัปดาห์ที่ 10" },
        description = { "180:1133277984:1544247358", "นี่คือคำท้าสุดท้ายของข้า ให้เจ้าเอาทุกอย่างที่ทุ่มเทฝึกมารวมกัน ข้าจะยอมรับอย่างเดียวคือต้องชนะให้ขาดลอย เจ้าทำได้... ละมั้ง" },
    },
    [97378] = { -- Mirrorscale
        title = { "11:1144604317:71964969", "Mirrorscale" },
        description = { "N 500:2068383156:1646067992", "{name} เจ้าพิสูจน์แล้วว่าเป็นพรานที่แข็งแกร่งและทำหน้าที่ดี ข้าประทับใจในความกล้าของเจ้า เพราะเหตุนี้ข้าจึงมอบการล่าครั้งนี้ให้เจ้า\n\nอสรพิษสายลมตัวหนึ่งล่าเหยื่อตามถนนใกล้ชายฝั่ง Feralas มันซุ่มโจมตีคนเดินทางแล้วทิ้งศพไว้เกลื่อนถนน เห็นชัดว่ามันล่าเกินความจำเป็น สัตว์ตนนี้ไม่ได้รับพรจากพระแม่ปฐพีอีกต่อไป\n\nอสรพิษสายลม Mirrorscale ทำรังอยู่ด้านล่างของน้ำตกตามชายฝั่ง Feralas" },
        objective = { "61:1409300826:463650144", "นำ Mirrorscale's Wing ไปให้ Melor Stonehoof ใน Thunder Bluff" },
        completion = { "20:1921578502:569519135 N 85:1366928291:665660527", "ทำได้ดี {name}\nข้ารู้ว่างานนี้ไม่ง่าย แต่เมื่อหนึ่งชีวิตดับลง ชีวิตอีกมากก็จะรอด" },
        progress = { "31:1439675293:867480419 N 140:781733621:1019995532", "เจ้าปราบ Mirrorscale แล้วหรือยัง {name}?\nระวังไว้ล่ะ เขาว่าท้องของมันมีเกล็ดส่องแสงจ้าจนเหยื่อชะงักไปชั่วขณะ เปิดโอกาสให้มันโจมตี" },
        required = { [277972] = { "18:955557521:401952760", "ปีกของ Mirrorscale" } },
        steps = { { "18:955557521:401952760", "ปีกของ Mirrorscale" } },
    },
    [97386] = { -- The Offense of Grom'gol
        title = { "23:534729739:27966702", "Grom'gol เปิดฉากบุก" },
        description = { "N 478:2946625:47668311", "{name}! เจ้ามาได้ทันเวลาทุกที\n\nเจ้าช่วยปกป้อง Grom'gol ไว้มาก พวกเราขอบใจ หลังเจ้ารุกไล่พวกโอเกอร์แถวนั้นครั้งล่าสุด เราส่งคนไปสอดแนมว่ามีตัวอื่นที่จะมาแก้แค้นอีกไหม ปรากฏว่าไกลออกไปทางตะวันออกมีถ้ำที่พวกมันยึดไว้เป็นรัง\n\nชวนเพื่อนไปสักคนสองคน แล้วทำให้มันเข้าใจชัด ๆ ว่าเราจะไม่ยอมให้ใครคุกคามที่ตั้งของเราอีก ทั้งตอนนี้และตลอดไป!" },
        objective = { "98:1383370406:564293597", "Commander Aggro'gosh ที่ค่าย Grom'gol ต้องการให้เจ้าฆ่าอ็อกเกอร์ที่ Mosh'Ogg Ogre Mount" },
        completion = { "145:815427894:1858340265", "ดูเผิน ๆ พวกมันอาจยังไม่พร้อมบุก Grom'gol แต่เรายอมเสี่ยงอย่างนั้นอีกไม่ได้\nเพื่อ Horde!" },
        objectiveLabels = {
            monster = { ["Mosh'Ogg Spellcrafter slain"] = "ปราบ ผู้รังสรรค์คาถา Mosh'Ogg", ["Mosh'Ogg Warmonger slain"] = "ปราบ นักกระหายสงคราม Mosh'Ogg", ["Mosh'Ogg Mauler slain"] = "ปราบ นักขย้ำ Mosh'Ogg", ["Mosh'Ogg Shaman slain"] = "ปราบ ชาแมน Mosh'Ogg" },
        },
    },
    [97453] = { -- Weed Whacked
        title = { "12:1830812026:559863276", "วัชพืชอาละวาด" },
        description = { "468:952264419:1560887925", "หวัดดี ช่วยข้าหน่อยได้ไหม?\n\nในที่สุดพ่อแม่ก็ยอมให้ข้าตามมาที่ป่าใหญ่นี่ แถมให้เก็บต้นไม้หน้าประตูได้ด้วย ข้ากำลังฝึกเก็บสมุนไพร จะได้เป็นนักเล่นแร่แปรธาตุสักวัน!\n\nข้าเก็บจนเกือบเต็มเป้แล้ว อยู่ดี ๆ วัชพืชยักษ์หัวเสียก็โผล่มาเป็นฝูงแล้วพ่นใส่ข้า!\n\nข้าวิ่งหนีมาได้ ไม่เป็นไร แต่ตอนนี้พ่อแม่ไม่ให้ข้าออกไปเล่นนอกค่ายแล้ว เจ้าช่วยทำให้แถวนั้นปลอดภัย แล้วไปบอกแม่ข้าได้ไหม?" },
        objective = { "5:1000000866:1065647852 W1 69:1280403633:1308631346", "ฆ่า Carnivorous Weed {world1} ต้นทางใต้ของ Grom'gol แล้วไปบอกแม่ของ Gemmil" },
        completion = { "478:1526584225:1923088841", "อา ข้าน่าจะเอะใจว่าเจ้าหนู Gemmy จะหาทางเกลี้ยกล่อมใครสักคนให้ช่วยเรื่องของเขา\nแต่คราวที่แล้วที่เขาออกไปก็หวุดหวิดเกินไป ข้ายังไม่รู้เลยว่าข้างนอกมีอะไรซุ่มอยู่อีกบ้าง\nอีกสักสิบปีเขาถึงจะได้ก้าวพ้นประตูนั่น ที่จริงพอพ่อเขากลับจาก Booty Bay เขาก็จะถูกส่งกลับ Durotar ทันที\nเจ้าไม่ต้องเอาข่าวไปบอกเขาหรอก ข้าจะบอกเอง" },
        progress = { "35:1764187317:1086183276", "สวัสดี ต้องการเสบียงหรือเปล่า?" },
        objectiveLabels = {
            monster = { ["Carnivorous Weed slain"] = "ปราบ วัชพืชกินเนื้อ" },
        },
    },
    [97530] = { -- Dunemaul Dues
        title = { "13:1332541358:1698222837", "ทวงของจาก Dunemaul" },
        description = { "443:1674549546:698784124", "กองคาราวานพ่อค้าเลี้ยวผิดทางในทะเลทราย เลยโดนพวกโอเกอร์ Dunemaul ซุ่มเล่นงาน ที่รอดมาได้ก็เพราะโยนสินค้าทิ้งไปล่อเจ้าพวกนั้น\n\nพ่อค้าคนนี้คงมีเส้นกับพวกใหญ่โตที่คุมเรือกับเรือเหาะ ตอนนี้เลยจะให้ข้าไปเก็บของที่หาย\n\nข้าติดงานอยู่ที่นี่ แต่ถ้าเจ้าเห็นกำไลแวววาวตอนกำลังซัดพวกโอเกอร์ เอามาให้ข้าแล้วจะได้ค่าตอบแทนคุ้มแรง" },
        objective = { "155:1173950290:1742813971", "Security Chief Bilgewhizzle ที่ Steamwheedle Port ใน Tanaris ต้องการให้เจ้าไปเอากำไลแวววาวที่หายไปใกล้ถิ่นอ็อกเกอร์ Dunemaul กลับมา" },
        completion = { "213:936939836:1935627848", "เออ ใช่ ดูเหมือนจะเป็นของที่ทำให้พวกนั้นแตกตื่น สภาพยังดีอยู่เลย ทีนี้พวกเคร่งระเบียบคงเลิกตามจี้ข้าเรื่องกำไรที่หายไปเสียที\nเอ้า นี่ของตอบแทนที่เจ้ายอมลำบาก" },
        progress = { "115:2127193546:479491160", "ข้าพอเข้าใจว่าโลหะวิบวับทำให้เจ้าทึ่มพวกนั้นเสียสมาธิได้ยังไง ของที่พวกมันทำออกมาน่ะฝีมือแค่โอกร์ ๆ" },
        required = { [278186] = { "27:68099795:279743497", "กำไลขัดเงาวาววับ" } },
        steps = { { "27:68099795:279743497", "กำไลขัดเงาวาววับ" } },
    },
    [97540] = { -- Oasis
        title = { "5:544452768:2010709681", "โอเอซิส" },
        description = { "104:434165507:1620494806", "โอ้ น้ำจืดนี่กลิ่นสดชื่นเหลือเกิน...\n\nข้าจะหยุดพักสักครู่ ลงไปว่ายน้ำเร็ว ๆ แล้วดื่มสักหน่อย" },
        objective = { "62:584478544:2002376230", "พา Tooga ที่เพิ่งหายกระหายน้ำกลับไปหา Torta ภรรยาของเขา" },
        completion = { "27:290646466:1831377329", "ไปหา Torta กันต่อเถอะ" },
    },
    [90627] = { -- Crafty the Crafter
        title = { "18:1230023931:1735852706", "ช่างฝีมือเจ้าเล่ห์" },
        description = { "323:714231755:1459665068", "เอาละ ช่างของข้าชื่อ Mizzle the Crafty\n\nชัดขนาดนี้ Grok'lo ยังดูออก! ทุกคนคิดว่าได้ชื่อนี้เพราะฉลาด เปล่า! มันเป็นโอเกอร์ มันไม่ฉลาด! ได้ชื่อเพราะทำของเก่งต่างหาก!\n\n<Grok'lo พยักหน้า>\n\nไปที่ Dire Maul ปีกเหนือแล้วพบเขา ตอนเจอกันให้แน่ใจว่าไม่มีเรื่องอื่นมาทำให้เขาเสียสมาธิ\n\nไปคนเดียว" },
        objective = { "233:1122765340:595522605", "ไปพบ Mizzle the Crafty ที่ Dire Maul ปีกเหนือ\n\nไปหาเขาตอนที่ไม่มีอะไรให้ต้องจัดการ ระหว่างทางอย่าฆ่าโอเกอร์ตัวสำคัญ เพราะเขาจะต้องเสียเวลาหาคนมาแทนและช่วยเจ้าไม่ได้\n\nไปคนเดียว" },
        completion = { "310:327334082:1128664955", "โอ๊ย แย่แล้ว! Mizzle เอาปีกค้างคาวกับสายสวย ๆ มาประกบกันแล้ว!\n\nทุบตั้งหลายที แต่มันยังขาดอะไรอีกอย่างที่ข้าทำให้ไม่ได้\n\nวิญญาณโอเกอร์บอกว่าเป็นเพราะแสงกับความมืดของสองสิ่งนี้เข้ากันไม่ได้ เขาว่าต้องเติมชะตากรรมที่หนีไม่พ้นลงไปสักหยิบมือ แต่ข้าไม่รู้ว่ามันคืออะไร" },
        progress = { "344:269108039:1576517195", "คุณ Mok'lo ส่งเจ้ามาเหรอ? ถ้าเจ้าเป็นหัวหน้าใหญ่ เขาก็เป็นหัวหน้ารอง แถมเป็นลูกค้าที่ดีที่สุดด้วย\n\nหีบบรรณาการเต็มไปด้วยของที่ยึดมาได้กับทองจากการทำของให้ Grok'lo เสมอ เราไม่ถามหรอกว่าเขาไปเอามาจากไหน แต่ตอนนี้มันเป็นของ Gordok แล้ว!\n\nอ้อ ตอนนี้เจ้าเป็นราชาองค์ใหม่แล้ว ข้าก็ไม่มีอะไรต้องซ่อม อยากให้ข้าทุบอะไรประกอบเข้าด้วยกันก็บอกมาได้เลย!" },
    },
    [90789] = { -- Scalebeard
        title = { "10:1065545648:1179754722", "Scalebeard" },
        description = { "23:993414638:1893318915 N 300:481112340:1066306046", "เวลาเหลือไม่มาก {name}! เวทหยั่งญาณของข้าพบแหล่งเวทอันทรงพลัง ข้าออกจากหอคอยไม่ได้ จึงอยากให้เจ้าสังหารสัตว์ชั่วร้ายที่ครอบครองวัตถุนี้\n\nมันชื่อ Scalebeard ซ่อนอยู่ในถ้ำแถบ Bay of Storms เผามันให้เป็นเถ้า แล้วเอาเปลือกสีรุ้งจากรังของมันมา" },
        objective = { "108:1223639484:1884188126", "นำ Prismatic Shell กลับมาให้ Archmage Xylem เขาอยู่ในหอคอยบนหน้าผาของ Azshara" },
    },
    [91531] = { -- Revenge Exacted
        title = { "15:2106749142:1302878208", "ชำระแค้นสำเร็จ" },
        description = { "130:1989424888:58315208 N 1:46:46", "กลับไปหา Belgrom ที่ Orgrimmar เขาคงอยากเห็นหัวของนางกับตา!\n\nอา วันนี้เป็นวันที่ดีจริง ๆ ขอบใจที่ช่วย {name}" },
        objective = { "65:1691607866:670279023", "นำหัวของ Magus Rimtori (Head of Magus Rimtori) ไปให้ Belgrom Rockmaul ใน Orgrimmar" },
    },
    [92020] = { -- Hol'anyee's Big Book of Big Lizards
        title = { "35:1656448610:478455935", "หนังสือเล่มโตว่าด้วยกิ้งก่ายักษ์ของ Hol'anyee" },
        description = { "446:1052490532:1404298790", "ข้าจดบันทึกและวาดรูปสัตว์ทุกชนิดที่อยู่ใน Un'Goro Crater ลงในสมุดภาพ แล้วทำสำเนาไว้ส่งให้คนที่อาจสนใจ!\n\nข้ามีสำเนาสมุดภาพอยู่เล่มหนึ่ง ตั้งใจจะส่งให้ดรูอิดบน Mount Hyjal เพราะรู้ว่าพวกเขาชอบศึกษาธรรมชาติ\n\nแต่ Hyjal เดินทางไกลอยู่ ถ้าเจ้าได้ไปที่นั่น ช่วยเอาติดตัวไปให้หน่อยได้ไหม?" },
        objective = { "81:436405017:541169806", "นำหนังสือเล่มโตว่าด้วยกิ้งก่ายักษ์ของ Hol'anyee ไปให้ดรูอิดบนยอด Mount Hyjal" },
    },
    [93030] = { -- The Knight of Mourning
        title = { "22:168009592:64822508", "อัศวินผู้โศกเศร้า" },
        description = { "287:1664467542:1767304282", "ครั้งหนึ่งข้าเคยเป็นอัศวินเหมือนเจ้า ผูกพันกับการรับใช้แสงศักดิ์สิทธิ์ แล้วข้าก็ตาย ดูเหมือนเราจะมีเรื่องนี้เหมือนกัน\n\nส่วนข้ายังถูกผูกไว้กับที่นี่ด้วยภารกิจที่ไม่เสร็จและคำสัตย์ที่ยังไม่ได้ทำตาม ถ้าเจ้ายอมฟัง ข้าจะเล่าเรื่องภารกิจของข้า... และความล้มเหลวของข้า" },
        objective = { "75:1669141128:1241638783", "คุยกับอัศวินผู้โศกเศร้าเพื่อฟังเรื่องภารกิจที่เขายังทำไม่สำเร็จ" },
    },
    [93404] = { -- Rot and Regret
        title = { "14:1456020342:1324813227", "ความผุพังและความเสียใจ" },
        description = { "406:1735795094:1745495959", "ข้าคือต้นไม้โบราณที่สูงตระหง่านเหนือเรา ต้นที่ยังลุกไหม้แม้ฝนตกมาหลายครั้ง ข้ายังรู้สึกถึงไฟแม้ตายแล้ว ต้องแบกความผิดพลาดครั้งสุดท้ายไปตลอดกาล\n\nข้าไม่รู้ว่าทำไมถึงถูกสาปให้วนเวียนอยู่ที่นี่ ไม่เข้าใจว่าทำไมความตายถึงยังไม่ใช่จุดจบ\n\nโปรดดับไฟให้ข้าที หาน้ำบริสุทธิ์จากหุบผาศักดิ์สิทธิ์ ที่แบบนั้นมีอยู่อีกฟากของ Mashan'she ข้าได้ยินเสียงกระซิบถึงที่แห่งนั้นในสายลม\n\nMaraudon" },
        objective = { "120:91680634:426281627", "เข้าไปใน Maraudon เพื่อนำ Vial of Earth Song Water กลับไปให้ Woodwyrd ที่ Forlorn Gardens ใน Desolace" },
        required = { [258296] = { "24:690260463:1685468550", "ขวดบรรจุน้ำจาก Earth Song" } },
        steps = { { "21:887187646:1159718460", "ดับไฟที่ Woodwyrd" }, { "24:690260463:1685468550", "ขวดบรรจุน้ำจาก Earth Song" } },
    },
    [93604] = { -- Agamaggan's Blood
        title = { "17:1604839130:1942490082", "เลือดของ Agamaggan" },
        description = { "4:1127284786:150189436 R 489:2113312275:754409601", "ชาว{race} ตัวใหญ่เคยได้ยินชื่อ Razorfen Downs ไหม? <พ่นลมหายใจ> ไม่เคยอยู่แล้ว! ที่ใหญ่ใน The Barrens หนามเยอะ มองข้ามไม่ได้หรอก\n\nAgamaggan ตายที่นั่น เป็นที่สำคัญของควิลบอร์ทุกตัว ตอนนี้ Bristleback เข้าไม่ได้ เป็นของพวก Razorfen ที่ชอบสูดจมูกฟืดฟาด พวกมันไม่เคารพประวัติของควิลบอร์!\n\nเลือด Agamaggan หล่อเลี้ยงหุบเขา ทำให้หนามงอก หนามใหญ่! ใหญ่กว่าที่สร้อยเอลฟ์กระจ้อยร่อยจะทำได้!\n\nไปที่ Razorfen Downs หาเลือดของ Kog'thug มา เลือดเก่าจาก Razorfen Kraul ใช้ไม่ได้ ต้องเป็นเลือดดี ๆ!\n\nเอาเลือดมา ได้สร้อยไป ชนะ" },
        objective = { "251:669222770:13317160", "ไปที่ Razorfen Downs แล้วนำ Virulent Blood of Agamaggan กลับไปให้ Kog'thug the Brave ที่ Bristleback Retreat ใน Desolace เขาฝากย้ำว่า Blood of Agamaggan จาก Razorfen Kraul ใช้แทนกันไม่ได้" },
        required = { [260237] = { "27:273978694:493757677", "โลหิตพิษร้ายของ Agamaggan" } },
        objectiveLabels = {
            item = { ["Virulent Blood of Agamaggan"] = "โลหิตพิษร้ายของ Agamaggan" },
        },
    },
    [93679] = { -- Visions of Another
        title = { "18:1996996890:817240350", "นิมิตถึงอีกผู้หนึ่ง" },
        description = { "29:1413554121:942060837 N 286:215057330:1152607849", "ดีใจที่ได้พบเจ้าอีก {name} ข้าอ่านบันทึกที่เจ้าเอามาให้และคุยเรื่องนี้กับ Onku ผู้หยั่งรู้ที่อาวุโสที่สุดของเราแล้ว\n\nไม่นานมานี้เขาเห็นนิมิตที่อาจนำเราไปถึงลูกแก้ว Draenethyst ถ้าเจ้ามีเวลาสักครู่ เราอยากเล่าให้ฟังว่านิมิตเผยอะไรบ้าง" },
        objective = { "33:807446136:305462475", "ชมนิมิตของ Onku พร้อมกับ Magtoor" },
        objectiveLabels = {
            event = { ["Watch Onku's vision with Magtoor"] = "ชมนิมิตของ Onku พร้อมกับ Magtoor" },
        },
    },
    [94895] = { -- Lost Shipping Crate
        title = { "19:1978489717:978668435", "ลังสินค้าที่หายไป" },
        description = { "494:1869572930:1223022649", "<ด้านข้างลังมีป้ายเขียนมือ ด้านขวาเป็นแผนที่ที่วงสีแดงใหญ่ไว้ตามชายฝั่งทางตะวันออกเฉียงใต้ ตรงเหนือวิหารที่วาดลวก ๆ มีน้ำล้อมรอบและมีสัตว์มีปีกอะไรสักอย่าง ด้านซ้ายมีข้อความตัวโต>\n\nทรัพย์สินของ FRIZ FRAZZLESPARK\n\nPOWDERFUSE PORT\n\nคำเตือน ห้ามแกะ ห้ามเปิดหากไม่มีผู้ควบคุม\n\n<ตรงขอบล่างของป้ายมีข้อความเพิ่ม>\n\nหากหาย ให้นำคืน Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades" },
        objective = { "91:1820117850:836666892", "นำ Lost Shipping Crate ไปให้ Friz Frazzlespark ที่ Powderfuse Port ใน Riverglades" },
        completion = { "229:1100631496:2139433458", "เจ้าบอกว่าไปเจอนี่ที่ไหนนะ? แปลกใจจริงที่เจ้ากลับมาครบสามสิบสอง ขอบใจนะ เจ้าหนู\n\nนี่ ถ้าเจ้าชอบช่วยเหลือคนอื่น แถวนี้คงมีอีกหลายคนที่อยากขอแรงเจ้า ทำไมไม่อยู่ต่ออีกสักพักล่ะ?" },
    },
    [94929] = { -- Deliver the Second Shipment
        title = { "27:777546785:1792494086", "ส่งสินค้าชุดที่สอง" },
        description = { "501:1388254793:94652312", "ข้ารู้ว่าบอกไปแล้วว่างานหมด แต่รับรองว่าถ้าไม่สำคัญข้าคงไม่ขอ นี่เป็นสินค้าที่ต้องส่งด่วนที่สุด\n\nคนรู้จักเก่าของข้าอยู่ในป้อมแห่งหนึ่งใน Riverglades ให้เดินทางไปทางตะวันออกเฉียงเหนือผ่านหนองน้ำ หลบสัตว์ร้ายที่อยู่ข้างใน ตามไหล่เขาด้านตะวันออกเฉียงเหนือจะเจอทางเก่า เดินตามทางนั้นข้ามเนินไปจนถึงทางแยก ให้ไปทางเหนือก่อนแล้วค่อยไปทางตะวันออก เจ้าจะเห็น Farholde ตามชายฝั่งตะวันออก\n\nขอบใจที่ช่วย" },
        objective = { "70:1226230869:297641078", "นำสินค้าไปให้ Demar Brant ที่ Farholde Keep ใน Riverglades" },
        required = { [266891] = { "25:1924057632:435962152", "สินค้าที่ส่งไปป้อม Farholde" } },
        steps = { { "25:1924057632:435962152", "สินค้าที่ส่งไปป้อม Farholde" } },
    },
    [95544] = { -- Keeping it Cool
        title = { "15:2132542141:93441109", "ช่วยให้เย็นไว้" },
        description = { "426:437260767:2041463414", "ช่วยข้าที นักเวท! ไอศกรีมของข้า ปากท้องของข้า กำลังตกอยู่ในอันตราย!\n\nข้าได้ข่าวว่าลูกค้าที่เคยพอใจกำลังเซ็งเพราะพวกสัตว์ต้องสาปที่เพ่นพ่านทางเหนือ เปลวไฟที่ไม่ยอมดับทำให้ของดี ๆ ของข้าละลาย แล้วตอนนี้ยอดขายก็ตก! ด้วยเวทน้ำแข็งอันชาญฉลาดของเจ้า ข้ามั่นใจว่าเจ้าหาทางแก้ได้แน่\n\nไปจัดการสัตว์น่าสงสารพวกนั้นที จะได้เรียกลูกค้ากลับมา!" },
    },
    [95557] = { -- Greater Fel Rites
        title = { "17:1178779048:254458977", "พิธีเฟลขั้นสูง" },
        description = { "51:1314226404:1588648587 N 410:817347844:1015892008", "กลับมาหาคำท้าที่ยากกว่าเดิมหรือ? เอาละ {name} ข้าอาจมีสิ่งที่เจ้าตามหา\n\nมีข่าวลือว่าพวก Shadowsworn ใน Blasted Lands ค้นพบพิธีที่ทรงพลังมาก เช่นเดียวกับพวกสาวกลัทธิก่อนหน้า ดูเหมือนพวกนี้จะคิดว่าตนเก่งกว่าที่เป็นจริง ถ้าอยากพิสูจน์ว่าชำนาญเวทเฟลจริง เจ้าต้องกล้าเข้าพิธีนี้และรอดกลับมาเหมือนคราวก่อน\n\nเตรียมตัวให้ดี เพราะครั้งนี้จะยากกว่าเดิม" },
    },
    [96062] = { -- Fel Rites
        title = { "9:1527693859:1954968613", "พิธีเฟล" },
        description = { "47:1432840015:1205982191 N 432:166938561:1686507751", "เจ้าพิสูจน์แล้วว่าเป็นวอร์ล็อกที่มีฝีมือ {name} แต่ฝีมืออย่างเดียวอาจไม่พอสำหรับบททดสอบถัดไป\n\nพวกสาวกลัทธิ Burning Blade ต้องสาปฝึกศาสตร์มืดที่ Shadowbreak Ravine มานานแล้ว พวกมันอัญเชิญปีศาจทรงพลังได้ แต่วิธีอัญเชิญของมันมักคร่าชีวิตผู้อัญเชิญเอง\n\nไปที่ Desolace แล้วเข้าร่วมพิธีของพวกมันสักครั้ง เตรียมอาคมป้องกันพลังเงาให้ดี และให้ปีศาจรับใช้ของเจ้าพร้อมออกมาคุ้มกัน" },
    },
    [96256] = { -- My Old Friend Olvek
        title = { "19:55600704:284308929", "Olvek เพื่อนเก่าของข้า" },
        description = { "500:1751607716:374018719", "ได้ข่าวว่าเจ้ากับผู้โชคดีไม่กี่คนได้รับเชิญไป Dalaran นครนักเวท! นับว่าเป็นเกียรติมาก ทุกครั้งที่ข้าเจอ Kirin Tor ลงเอยด้วยการต้องงอกอวัยวะขึ้นใหม่ ไม่ใช่ทุกวันที่ชาวฮอร์ดจะได้ไปเห็นเมืองเวทมนตร์โดยไม่ต้องเสี่ยงตายอย่างทรมาน!\n\nพอดีข้าต้องการของที่หาได้จากที่นั่นเท่านั้น หนังสือที่เพื่อนเก่า คนแคระชื่อ Olvek เขียนไว้ เรื่องเล็กน้อย แต่ถ้าเอามาให้ข้าได้ ข้าจะขอบใจมาก" },
    },
    [96257] = { -- A Good Trade
        title = { "12:237656121:1136086409", "การแลกเปลี่ยนที่คุ้มค่า" },
        description = { "438:1655451868:1496706763", "เขาส่งเจ้ามาเอาหนังสือข้าหรือ? อืม... บางทีเราอาจตกลงแลกกันได้\n\nพอดีข้ากำลังเขียนวิทยานิพนธ์เรื่องปรมาจารย์รูนโบราณแห่ง Grim Batol และต้องใช้คัมภีร์เล่มหนึ่งจึงจะทำงานวิจัยเสร็จ ได้ยินว่าหัวหน้านักเวทอาคมของ Scarlet Crusade เก็บสำเนาไว้ในห้องสมุดที่ Scarlet Monastery ใน Tirisfal Glades\n\nหาสำเนา The Lost Magic of the Runemasters มาให้ข้า แล้วข้าจะให้สำเนาหนังสือเรื่องพิษของข้า" },
    },
    [96258] = { -- Small Book, Big Effort
        title = { "22:1932922342:1964198234", "หนังสือเล่มเล็ก แต่งานใหญ่" },
        description = { "319:1137701535:905779774", "ข้าเป็นคนแคระที่รักษาคำพูด... นี่สำเนาหนังสือของข้า ข้าลงชื่อให้ด้วย ฮ่า!\n\nบอก Mazu'kon ว่าข้ายังไม่ลืมที่เจอกันครั้งก่อน ถ้าเห็นเขาอีกในสนาม ครั้งหน้าข้าจะให้เขาเสียนิ้วเท้ามากกว่าสองสามนิ้วแน่\n\nไปได้แล้ว ไสหัวไป ข้าไม่อยากเห็นหน้าเจ้าในห้องสมุดอีก" },
    },
    [96770] = { -- The Witch Doctor's Head
        title = { "23:1396311694:666499622", "หัวของหมอผี" },
        description = { "337:157621291:437988540", "มีหมอผีโทรลล์คนหนึ่งชื่อ Zum'rah ข้ากับมันมีเรื่องเก่ากันอยู่ และข้าอยากให้เจ้าฆ่ามันให้ข้า\n\nไปยังที่มั่น Sandfury ที่ Zul'Farrak ลึกเข้าไปในทะเลทราย Tanaris หา Zum'rah ข้างในแล้วสังหารมัน เอาหัวของมันมาให้ข้าแบบสมบูรณ์ แล้วข้าจะจ่ายให้คุ้มแรง" },
        objective = { "85:12277626:1696856328", "ฆ่า Witch Doctor Zum'rah แล้วนำ Zum'rah's Head ไปให้ Archmage Lan'dalock ใน Dalaran" },
        completion = { "45:1532366548:1745458760 N 117:294841126:654350666", "ขอบใจที่รับใช้ Kirin Tor {name} นี่รางวัลของเจ้า\nเจ้ากับข้ามีเรื่องต้องคุยกันยาวแล้วละ Zum'rah ข้าเกรงว่าเจ้าคงไม่สนุกด้วย" },
        progress = { "257:547777941:816148365", "มนตร์ปลุกศพของโทรลล์เป็นศาสตร์อันชั่วร้าย มีแต่พวกที่วิปริตเป็นพิเศษเท่านั้นที่ฝึกมัน Zum'rah ยังไม่รู้ว่าคนที่ทำให้คนตายขยับได้มีมากกว่าเขาคนเดียว และการเสียหัวเป็นแค่จุดเริ่มต้นของเรื่องร้ายที่จะตามมา" },
        required = { [277112] = { "14:109926880:1418741039", "ศีรษะของ Zum'rah" } },
        steps = { { "14:109926880:1418741039", "ศีรษะของ Zum'rah" } },
    },
    [96773] = { -- The Coldbringer's Eye
        title = { "21:1731848506:170715537", "ดวงตาของ Coldbringer" },
        description = { "323:1385930173:975105538 C 119:1119080733:987431558", "สมุนของ Lich King ตนหนึ่งอาศัยอยู่ลึกในรังควิลบอร์ที่เรียกว่า Razorfen Downs เรารู้ว่ามันใช้ลูกแก้วหยั่งญาณชื่อ Coldbringer's Eye เพื่อสั่งการความเคลื่อนไหวของสมุนระดับล่างในที่อื่น\n\nเข้าไปใน Razorfen Downs แล้วชิง Coldbringer's Eye มาให้เรา {class} Kirin Tor ยินดีจ่ายอย่างงามเพื่อให้ได้วัตถุชิ้นนี้มาศึกษาว่ามันทำงานอย่างไร" },
        objective = { "50:629156591:276639930", "นำ The Coldbringer's Eye กลับมาจาก Razorfen Downs" },
        completion = { "53:94598068:2006600929", "ทำได้ดี นี่รางวัลของเจ้าตามสัญญา" },
        progress = { "483:898446441:155286258", "วิธีการและพลังของพวก Scourge ลึกลับเข้าใจยาก แม้แต่นักเวทผู้มีความรู้ของ Kirin Tor ก็ยังไขไม่ออก บางคนสันนิษฐานว่าเวทของพวกมันคล้ายเวทธาตุในเนื้อแท้ อาจเป็นพลังที่อยู่ตรงข้ามกับแสงศักดิ์สิทธิ์\nบางคนก็คิดว่าพวกมันดึงเวทมาจากแดนวิญญาณโดยตรง ผ่านรอยแยกเล็ก ๆ ในม่านที่กั้นความเป็นกับความตาย ยิ่งเรานำวัตถุของ Scourge ที่ยังสมบูรณ์กลับมาศึกษาได้มากเท่าไร เราก็จะเข้าใจเรื่องนี้ได้ครบถ้วนขึ้นเท่านั้น" },
        required = { [276916] = { "21:1731848506:170715537", "ดวงตาของ Coldbringer" } },
        steps = { { "21:1731848506:170715537", "ดวงตาของ Coldbringer" } },
    },
    [96775] = { -- Zum'rah's Head
        title = { "14:109926880:1418741039", "หัวของ Zum'rah" },
        description = { "416:1571629236:2034963476", "Mazu'kon คนนี้มีเรื่องต้องสะสางกับหมอผีชื่อ Zum'rah ข้าว่าเจ้าช่วยได้\n\nZum'rah ทำวูดูชั่ว ๆ ทั้งหมดที่นคร Sandfury แห่ง Zul'Farrak ไกลลงไปทางใต้ในทะเลทราย Tanaris ไปที่นั่น ฆ่า Zum'rah แล้วเอาหัวมันมาให้ข้า\n\nเชื่อข้าเถอะ โลกจะดีขึ้นถ้าหัวมันเสียบอยู่บนหลักหน้ากระท่อมข้า แทนที่จะอยู่บนบ่ามัน" },
        objective = { "74:1000889592:1102639519", "ฆ่า Witch Doctor Zum'rah แล้วนำ Zum'rah's Head ไปให้ Mazu'kon ใน Mulgore" },
        completion = { "19:89968801:85651025 C 131:1152487282:1389029257", "ขอบใจเจ้า {class} เจ้าเอื้อเฟื้อกับ Maz คนนี้มาก\nโอ้ Zum'rah เพื่อนเก่า ข้าเคยเตือนแล้วว่าวันนี้จะมาถึง คราวนี้เจ้าจะเล่นมนตร์วูดูไม่ได้อีกแล้ว สหาย" },
        progress = { "45:2095418184:213663154", "มนตร์วูดูชั่ว ๆ ให้โทษกับเจ้าเอง จำไว้ล่ะ สหาย" },
        required = { [277112] = { "14:109926880:1418741039", "ศีรษะของ Zum'rah" } },
        steps = { { "14:109926880:1418741039", "ศีรษะของ Zum'rah" } },
    },
    [96913] = { -- Field of Honor: Week 2
        objective = { "33:1083397799:1814365198", "เข้าร่วมการต่อสู้ใน Warsong Gulch ให้จบ 3 ครั้ง" },
        title = { "22:1912183962:1232463558", "สนามเกียรติยศ สัปดาห์ที่ 2" },
        description = { "155:840018279:1386096120", "เจ้าอีกแล้วหรือ? พร้อมรับบททดสอบต่อไปไหม? หวังว่าจะไม่กลัวเลือด งานนี้อาจต้องเสียเลือดบ้าง... แต่ถ้าให้ดี ทำให้อีกฝ่ายเสียเลือดก่อน" },
    },
    [96914] = { -- Field of Honor: Week 3
        title = { "22:1912183963:1232463559", "สนามเกียรติยศ สัปดาห์ที่ 3" },
        description = { "123:1234463685:1133249278", "ข้าเริ่มเห็นแววในตัวเจ้าแล้ว คำท้าถัดไปต้องลงมือหนักจริง ๆ หวังว่าเจ้าจะพร้อม!" },
    },
    [96915] = { -- Field of Honor: Week 4
        title = { "22:1912183964:1232463560", "สนามเกียรติยศ สัปดาห์ที่ 4" },
        description = { "252:1473913799:1702008045", "นักสู้ไม่ได้วัดกันแค่ว่าฟันดาบหรือร่ายเวทได้แรงแค่ไหน การอ่านสนามรบและเปลี่ยนกลยุทธ์ทันทีสำคัญพอกัน\n\nคำท้าครั้งหน้าต้องใช้ทั้งสองอย่างนั้นและมากกว่านั้นอีก เจ้าทำได้ไหม?" },
    },
    [96916] = { -- Field of Honor: Week 5
        title = { "22:1912183965:1232463561", "สนามเกียรติยศ สัปดาห์ที่ 5" },
        description = { "68:32603485:42509761", "เปลี่ยนที่ แต่ยังเป็นงานเปื้อนเลือดแบบเดิม มาทดสอบความ... สม่ำเสมอของเจ้ากัน" },
    },
    [96917] = { -- Field of Honor: Week 6
        title = { "22:1912183966:1232463562", "สนามเกียรติยศ สัปดาห์ที่ 6" },
        description = { "151:562901407:2074839030", "โชคดีนะเพื่อน ข้าจะส่งเจ้าไปพักร้อนแบบไม่มีค่าจ้างที่ Darkspear Islands แดดดี เข้าไปทำงานของเจ้า แค่... พยายามอย่าตายก็พอ" },
    },
    [96918] = { -- Field of Honor: Week 7
        title = { "22:1912183967:1232463563", "สนามเกียรติยศ สัปดาห์ที่ 7" },
        description = { "126:1248482643:1032866250", "ข้าว่าเจ้าเข้าขั้นยอดฝีมือด้านความรุนแรงแล้วละเพื่อน แต่สัปดาห์นี้ขอเห็นความอึดของเจ้าเพิ่มอีกหน่อย" },
    },
    [96919] = { -- Field of Honor: Week 8
        title = { "22:1912183968:1232463564", "สนามเกียรติยศ สัปดาห์ที่ 8" },
        description = { "112:141517775:123576629", "คราวนี้ต่างคนต่างเอาตัวรอด! ไปที่ Gurubashi Arena แล้วทำให้ Kha'damu ภูมิใจ!" },
    },
    [96920] = { -- Field of Honor: Week 9
        title = { "22:1912183969:1232463565", "สนามเกียรติยศ สัปดาห์ที่ 9" },
        description = { "92:1014658517:554039558", "ข้าเคยได้ยินคำพูดหนึ่ง... ปริมาณสำคัญกว่าคุณภาพหรือไงนี่แหละ ใช่ คงอย่างนั้น ขอดูหน่อย!" },
    },
    [97269] = { -- The Darkened Glaive
        title = { "19:1612681649:1850660523", "ดาบวงแหวนต้องมลทิน" },
        description = { "174:533520129:1052908461", "ตอนนี้ข้ายุ่งจริง ๆ ถ้าไม่ว่าอะไร ช่วยเดินต่อไปเถอะ\n\nเดี๋ยวก่อน... ดาบวงแหวนที่เจ้าถือ... เป็นไปได้หรือ? เอาเข้ามาใกล้แสงหน่อย ข้าจะได้ตรวจดูให้ชัด!" },
    },
    [97270] = { -- Brawl at the Maul
        title = { "17:979044561:1103541043", "วิวาทที่ The Maul" },
        description = { "115:13438890:882602989", "The Maul ต้องมีอะไรมากกว่านี้แน่!\n\nผู้ชมเสียงดังที่คุมงานใน Dire Maul อาจรู้เรื่องก็ได้!" },
        objective = { "63:269316726:1694838008", "คุยกับ Griniblix the Spectator ที่อยู่เหนือสังเวียน Maul ใน Dire Maul" },
    },
    [97411] = { -- An Earnest Proposition
        title = { "22:1183475074:147978204", "ข้อเสนอที่จริงใจ" },
        description = { "6:1136836709:1914036474 C 423:287029186:1488951061", "คารวะ {class}! ดูท่าทางก็รู้ว่าเจ้าเห็นและทำอะไรมามากในโลกนี้ แต่ข้าพนันได้ว่าเจ้ายังไม่เคยเห็นเกราะอย่างชิ้นนี้\n\nทำอะไรให้ข้าสักหน่อย แล้วข้าจะยอมเอามันแลกกับปลอกแขนธรรมดาหนึ่งคู่\n\nข้าต้องใช้ตัวอย่างพิษปริมาณมากจากแมงมุมกับแมงป่องที่อยู่ใน Silithus เอามาให้ข้าพร้อมเหรียญทองอีกสองสามเหรียญ แล้วเราจะแลกกัน" },
        objective = { "123:937110448:866336055", "หา Silithus Venom Sample 15 ตัวอย่างและเงิน 20 ทอง แล้วนำไปให้ Mokvar ใน Orgrimmar พร้อม Lightforge Bracers หนึ่งชุด" },
    },
    [97412] = { -- Just Compensation
        title = { "17:479802657:1407557245", "ค่าตอบแทนที่เหมาะสม" },
        description = { "48:633264145:113946280 N 262:2026027207:1286935208", "เจ้าพิสูจน์แล้วว่าพึ่งพาได้มาก {name} ข้าเชื่อว่าเจ้าจะช่วยให้ข้าผ่านเรื่องลำบากนี้ไปได้ และข้าควรตอบแทนตามผลงานของเจ้า\n\nตอนนี้ข้าจะเปลี่ยนเข็มขัดกับถุงมือให้ ถ้าเราผ่านเรื่องนี้ไปด้วยกัน ข้าจะยอมให้เจ้าแลกชิ้นที่เหลือ" },
    },
    [97413] = { -- Anthion's Parting Words
        title = { "23:573656928:1309079977", "คำลาของ Anthion" },
        description = { "454:1366191329:981737942", "วิญญาณของ Valthalak ถูกเก็บไว้ในเครื่องรางนี้ ด้วยความโลภ เราโง่เขลาแยกมันออกเป็นสามชิ้น โดยไม่รู้เลยว่าคำสาปอะไรรอเราอยู่\n\nทางเดียวที่จะหยุดมนตร์ของ Valthalak ได้คือประกอบเครื่องรางกลับให้ครบ กลับไปหา Mokvar แล้วบอกเขาว่า Bodley คือความหวังเดียวที่จะหาชิ้นส่วนที่เหลือเจอ คุยกับเขาเรื่องรางวัลที่เจ้าตกลงไว้ด้วย\n\nในที่สุดข้าจะได้พักอย่างสงบเสียที ขอให้เจ้าโชคดีที่สุด เจ้าต้องใช้โชคทั้งหมดที่มี!" },
    },
    [97414] = { -- Saving the Best for Last
        title = { "24:1236774670:147360432", "เก็บสิ่งดีที่สุดไว้ท้ายสุด" },
        description = { "23:2147252303:46662951 N 265:448145215:46532724", "เรื่องน่าทึ่งจริง ๆ {name}! เจ้าควรได้รับคำขอบคุณจากข้า และความซาบซึ้งใจจากทุกคนที่เกี่ยวข้อง ข้ารับรอง ความพยายามของเจ้าช่วยให้เราหลุดพ้นจากความผิดพลาดในอดีต\n\nส่วนรางวัล ข้าคิดว่ามีของสองสามอย่างที่เจ้าสมควรได้รับและต้องชอบจริง ๆ" },
    },
    [98472] = { -- Ambushed
        title = { "8:479089059:902577668", "ถูกซุ่มโจมตี" },
        description = { "386:1908617473:2117531662", "เจ้าเพิ่งถูกซุ่มโจมตี ดูเหมือน Ayessa Dawnsinger ไม่ได้พูดเกินจริงตอนบอกว่าจะล้างแค้นแทนชาว Windshaper ที่เจ้าฆ่าบน Zephras Isle\n\nถ้าพวก Windshaper ส่งมือสังหารตามล่าสมาชิก High Order จริง Elaadrin Evengale ต้องอยากรู้เรื่องนี้ ตอนนี้เขาน่าจะถึง Dalaran แล้ว ไปพบเขาที่นั่น" },
    },
    [98477] = { -- Unstable Magic
        title = { "14:1304004259:385961613", "เวทมนตร์ไม่เสถียร" },
        description = { "496:537223702:1781409298", "ชาแมนที่มีประสบการณ์คนไหนลองหยั่งญาณไปยังระนาบธาตุก็บอกได้ว่ามีความผิดปกติบางอย่าง เหมือนกระแสบิดเบี้ยวที่รู้สึกได้ตอนข้ามไปยังภพอื่น\n\nเราต้องการนักผจญภัยอย่างเจ้ามาช่วยทำความเข้าใจความปั่นป่วนนี้ เอา Elemental Attractor ไป เจ้าใช้มันดึงละอองเวทไม่เสถียรจากผู้ใช้เวทที่ชำนาญที่สุดและสิ่งทรงพลังอื่น ๆ ที่พบได้ เอาละอองมาให้เราเพื่อศึกษา" },
        objective = { "53:617630492:1164196422", "นำ Mote of Unstable Magic 10 ชิ้นไปให้ Nuara Tremorhoof", amount = { "6:1273960851:929420321 W1 45:406756204:1150997641", "นำ Mote of Unstable Magic {world1} ชิ้นไปให้ Nuara Tremorhoof" } },
    },
    [98830] = { -- The Broken Glaive
        title = { "17:1549824470:592748775", "ดาบวงแหวนที่หัก" },
        description = { "449:224763713:1603946307", "อากาศมีกลิ่นโลหะฉุนขณะเจ้าก้มลงตรวจศพ Prince Tortheldrin เวททรงพลังยิ่งเพิ่งถูกสลายที่นี่\n\nศพเบื้องหน้าดูแก่และทรุดโทรม ขาดความมีชีวิตชีวาที่เจ้าชายเคยแผ่ออกมาก่อนล้มลง ยังมีรูปลักษณ์ส่วนอื่นที่ต่างไปด้วย\n\nดาบวงแหวนเล่มหนึ่งของ Tortheldrin วางอยู่ใกล้ร่าง หักเป็นสองท่อน เหล่าผู้อาวุโส Shen'dralar ต้องอยากรู้สิ่งที่เจ้าเห็นที่นี่" },
        objective = { "76:900884812:1975477949", "นำ Tortheldrin's Broken Glaive ไปให้ Shen'dralar Ancient ใน Dire Maul" },
    },
    [98916] = { -- Take Full Control
        title = { "17:400399266:467436285", "ยึดทุกด่าน" },
        description = { "227:2031158789:1606433671", "เรารบกันที่ Darkspear Islands มาหลายครั้ง แต่ยังสูสีกว่าที่เราอยากให้เป็น คราวนี้จงเอาชนะฝ่ายพันธมิตรโดยยึดด่านทั้งหมดไว้\n\nทำให้สำเร็จ แล้วแสดงว่า Darkspear Raiders เหนือกว่า" },
    },
    [98917] = { -- Darkspear Island Domination
        title = { "27:1174040295:48851574", "ครองสนามรบ Darkspear Islands" },
        description = { "309:907958634:2063979248", "เจ้าทำให้ฮอร์ดพ่ายแพ้เด็ดขาดที่ Darkspear Islands แล้ว ตอนนี้ถึงเวลาทำลายขวัญของพวกมันให้สิ้น คุมสนามรบให้หมด เอาชนะศัตรูโดยยึดด่านทั้งสี่ไว้\n\nทำให้สำเร็จแล้วแสดงให้ฮอร์ดเห็นว่า Theramore Expeditionary Force เหนือกว่าอย่างไร้ข้อกังขา" },
    },
    [98918] = { -- Conquering the Isles
        title = { "20:1280208215:392201332", "พิชิตหมู่เกาะ" },
        description = { "49:1983729673:1972579190 C 146:1047605476:152647564", "แค่ชนะฮอร์ดยังไม่พอ {class} เราต้องชนะเด็ดขาด กลับไป Darkspear Islands แล้วคว้าชัยชนะโดยยึดด่านอย่างน้อยสามแห่ง\n\nเพื่อฝ่ายพันธมิตร!" },
    },
    [98919] = { -- Conquering the Island
        title = { "21:448247883:1986181826", "พิชิตเกาะ" },
        description = { "306:190103118:378180459", "แค่เอาชนะฝ่ายพันธมิตรยังไม่พอ เราต้องทำลายขวัญจนขับพวกมันไปจาก Darkspear Islands ได้ตลอดกาล กลับไป Darkspear Islands แล้วอย่าปรานีพวกมัน ชนะการรบโดยยึดด่านอย่างน้อยสามแห่ง\n\nบดขยี้ฝ่ายพันธมิตรแล้วคว้าชัยชนะครั้งใหญ่ให้ Darkspear Raiders!" },
    },
    [99198] = { -- A Donation of Mageweave
        title = { "23:477706609:1703816279", "บริจาคผ้า Mageweave" },
        description = { "371:145177903:2049049468", "ผ้าที่เรียกว่า Mageweave มีคุณสมบัติแปลกที่พวก Windshaper สนใจมาก ถ้าเจ้าหาผ้า Mageweave มาบริจาคได้หกสิบผืน เราจะขอบใจมาก คณะของเราต้องเห็นความเอื้อเฟื้อของเจ้าด้วยแน่!\n\nถ้ามีผ้า Mageweave หกสิบผืนติดตัวและพร้อมบริจาค ข้ารับไว้ได้เลย" },
        required = { [4338] = { "15:1283357618:289024293", "ผ้า Mageweave" } },
        steps = { { "15:1283357618:289024293", "ผ้า Mageweave" } },
    },
    [99199] = { -- A Donation of Runecloth
        title = { "23:805424014:894170896", "บริจาคผ้า Runecloth" },
        description = { "N 381:828057585:1221866922", "{name} ขอบใจที่เคยช่วย Windshaper เราพยายามหาให้ทันความต้องการผ้า แต่ตอนนี้ต้องใช้ Runecloth มากเป็นพิเศษ หวังจริง ๆ ว่าเจ้าจะช่วยได้เหมือนที่ผ่านมา!\n\nถ้ายินดี โปรดนำ Runecloth ส่วนที่แบ่งได้มาให้ข้า ครั้งแรกเราจะรับบริจาคหกสิบชิ้นหนึ่งครั้ง แล้วค่อยว่ากันต่อ" },
    },
    [99233] = { -- Brawl at the Maul
        objective = { "63:269316726:1694838008", "คุยกับ Griniblix the Spectator ที่อยู่เหนือ Maul ใน Dire Maul" },
        title = { "17:979044561:1103541043", "วิวาทที่ The Maul" },
        description = { "115:13438890:882602989", "The Maul ต้องมีอะไรมากกว่านี้แน่!\n\nผู้ชมเสียงดังที่คุมงานใน Dire Maul อาจรู้เรื่องก็ได้!" },
    },
    [99234] = { -- Brawl at the Maul
        title = { "17:979044561:1103541043", "วิวาทที่ The Maul" },
        description = { "115:13438890:882602989", "The Maul ต้องมีอะไรมากกว่านี้แน่!\n\nผู้ชมเสียงดังที่คุมงานใน Dire Maul อาจรู้เรื่องก็ได้!" },
    },
    [402] = { -- Sirra is Busy
        description = { "153:1131906132:2137534241", "ข้าเสียใจด้วย แต่ตอนนี้สภาพเมืองเป็นแบบนี้ ข้าเกรงว่ายังมีหน้าที่อื่นต้องจัดการ ไว้ทีหลัง ถ้าเรารอดไปได้ ข้าอาจแปลเรื่องนี้ให้เสร็จ" },
        title = { "13:1724302340:1667554549", "Sirra ยังติดธุระ" },
    },
    [999] = { -- When Dreams Turn to Nightmares
        description = { "486:1931502794:1700758351", "Naralex หลับไปอีกแล้ว!\n\nนานมาแล้ว Naralex มาที่ถ้ำแห่งนี้ด้วยความตั้งใจอันสูงส่ง เขาหวังจะเข้าสู่ Emerald Dream และฟื้น The Barrens ให้เขียวชอุ่มเป็นป่าอีกครั้ง แต่สมาธิของเขาอ่อนลง ความคิดจึงแปดเปื้อนด้วยนิมิตของอสรพิษ\n\nตอนนี้สัตว์เลื้อยคลานรั่วไหลจากความฝันของเขาออกมาสู่ผืนดิน ต้องปลุกเขาจากฝันร้าย มิฉะนั้นเขาจะหลงอยู่ในนั้นตลอดกาล และความชั่วร้ายครั้งใหญ่จะหลุดออกมา\n\nข้าจะทำพิธีปลุกได้ก็ต่อเมื่อเหล่า Fanglord ผู้รับใช้ที่แปดเปื้อนของเขาถูกสังหารแล้วเท่านั้น" },
        title = { "30:631699430:1636376755", "เมื่อความฝันกลายเป็นฝันร้าย" },
    },
    [1099] = { -- Goblins Win!
        description = { "180:1287669858:1735303935", "เห็นไหม ข้าบอกแล้ว! ไม่มีทางที่พวกกอบลินจะแพ้การแข่งขันแบบนี้ให้โนมลานเศษเหล็กพวกนั้นหรอก เอาละ ถ้าเจ้ามีตั๋วที่ใช้ได้ ก็ส่งมาทางนี้" },
        title = { "12:752791500:2080978401", "กอบลินชนะ!" },
    },
    [1174] = { -- Gnomes Win!
        description = { "105:527081341:1643243572", "เจ้านั่น! บอกแล้วว่าคนฉลาดลงเงินข้างพวกโนม เจ้าวางเดิมพันก่อนเริ่มแข่งหรือเปล่า?" },
        title = { "11:768737690:548808477", "โนมชนะ!" },
    },
    [1500] = { -- Waking Naralex
        description = { "441:811925912:1799796639", "เหล่า Fanglord ตายแล้ว! เรายังมีหวัง!\n\nแต่พิธีปลุกซับซ้อนมาก ทำคนเดียวไม่ได้\n\nข้าจะเตรียมทุกอย่างที่จำเป็น ส่วนเจ้าต้องคุ้มกันข้า ฝันร้ายที่ถูกเรียกออกมาจากการเดินทางของ Naralex ผ่าน Emerald Dream รับมือยากทีเดียว ถ้าไม่มีเจ้าช่วย ภารกิจนี้ล้มเหลวแน่\n\nเมื่อพร้อมจะคุ้มกันข้า ก็บอกมา ข้าจะนำทางไปยังห้องของ Naralex" },
        title = { "14:206625947:1815073425", "ปลุก Naralex" },
    },
    [6131] = { -- Timbermaw Ally
        description = { "446:864666753:1605451229", "Timbermaw เป็นเผ่าเฟอร์โบลก์เผ่าเดียวที่รอดจากมลทิน แต่ตอนนี้เผ่าอื่นหลายเผ่าฆ่าเฟอร์โบลก์โดยไม่ดูว่าเป็นมิตรหรือศัตรู พวกเรา Timbermaw จึงไว้ใจคนน้อยมาก\n\nสนใจพิสูจน์ตัวเองไหม? ขับไล่เผ่า Deadwood ที่แปดเปื้อนใน Felwood แล้วสักวันเราอาจนับเจ้าเป็นพันธมิตร เจ้าจะพบกลุ่ม Deadwood กลุ่มแรกทางตะวันตกของข้า ทั้งนักรบ นักสำรวจทาง และคนดูแลพืช" },
        title = { "14:282996485:1724574680", "พันธมิตรของ Timbermaw" },
    },
    [6221] = { -- Deadwood of the North
        description = { "401:388270220:1904789565 N 83:1730861040:836406086", "ค่ายเฟอร์โบลก์ Deadwood อยู่ทางตะวันตกเฉียงใต้ของเราพอดี มลทินแทรกซึมไปทั่วค่าย ข้าอยากยุติเรื่องนี้ก่อนพวกเขาจะก่อปัญหา\n\nเผ่า Deadwood ทำเรื่องชั่วร้าย แต่เป็นพลังเฟลที่ทำให้จิตใจพวกเขาแปดเปื้อน ความก้าวร้าวนั้นไม่ได้ติดตัวมาแต่กำเนิด ทว่าตอนนี้ช่วยไม่ไหวแล้ว ข้าเสียใจนักที่ต้องสู้กับพี่น้องของตัวเอง\n\nได้โปรด {name} ทำสิ่งที่ต้องทำ และอย่าเล่ารายละเอียดให้ข้าฟังเลย มันทำให้ข้าสะเทือนใจเกินไป" },
        title = { "21:2138559600:752197475", "Deadwood ทางเหนือ" },
    },
    [6241] = { -- Winterfall Activity
        description = { "42:261326954:1081398306 N 412:1446552724:1374943959 N 1:46:46", "ชาว Timbermaw มักอยู่กันเงียบ ๆ {name} ถึงเราจะยอมให้ผู้ที่พิสูจน์แล้วว่าไว้ใจได้ผ่านไปอย่างปลอดภัย แต่ถ้าเลี่ยงได้ เราก็ไม่อยากยุ่งกับเฟอร์โบลก์เผ่าอื่น\n\nช่วงนี้ข้าสังเกตว่าเผ่า Winterfall เป็นศัตรูกับเราหนักขึ้น ดูเหมือนพวกเขาจะคลุ้มคลั่ง ถูกความกลัวและความเกลียดชังทุกสิ่งที่ไม่เข้าใจครอบงำไปหมด\n\nถ้าเจ้าช่วยลดจำนวนพวกเขาลงได้ จะช่วยเราได้มาก {name}" },
        title = { "19:1229852007:1805446750", "ความเคลื่อนไหวของ Winterfall" },
    },
    [7906] = { -- Darkmoon Cards - Beasts
        description = { "235:721210522:365619749", "พวกคนโกหกกับหัวขโมยเอาการ์ด Darkmoon ขั้นรองไปแล้วทำกระจัดกระจายทั่วโลก ข้าต้องการมันคืน! ถ้าเจ้ารวบรวมการ์ดขั้นรองมาคืนครบหนึ่งชุด ข้าให้การ์ด Greater Darkmoon ที่หายากและทรงพลังแก่เจ้าได้หนึ่งใบ" },
        title = { "23:798114462:7828015", "การ์ด Darkmoon ชุดสัตว์ร้าย" },
    },
    [92067] = { -- Feeding Time!
        description = { "42:1134552296:707745283 N 253:505499467:862365361", "เจ้าพิสูจน์ตัวเองให้ข้าเห็นแล้ว {name} แต่คนอื่นในเผ่าข้าเชื่อยากกว่าข้า เจ้าต้องสู้กับพวก Legashi ต่อไปเพื่อให้พวกเขายอมรับ\n\nเอาเขาของพวกเซเทอร์ Legashi ที่ถูกสังหารมาให้ข้า ทุกมัดที่เอามาจะเป็นเครื่องหมายว่าเจ้าได้ช่วยชาว Blackmaw" },
        title = { "13:387777408:2095254833", "ถึงเวลาให้อาหาร!" },
    },
    [93686] = { -- Kum'isha's Endeavors
        description = { "152:558221106:1954348222 R 163:188771380:746951037", "แม้การเปิดรอยแยกจะสำเร็จแค่บางส่วน Kum'isha ก็ต้องพยายามต่อไป\n\nความหวังของชาวดราไนแรงกล้าพอ ๆ กับความโลภของเจ้าที่อยากได้ของจุกจิก ชาว{race} กลับไปยังดินแดนต้องสาปนี้แล้วหาลูกแก้ว Draenethyst ไร้ตำหนิมาอีกลูก\n\nแน่นอน จะรับงานนี้หรือไม่ก็แล้วแต่เจ้า *ยิ้มกว้าง*" },
        title = { "20:1112748991:1396110387", "ภารกิจของ Kum'isha" },
    },
    [93925] = { -- Beads for Brerufa
        description = { "397:816218941:1138588695", "เจ้าแสดงให้เห็นว่ามีกำลัง แต่ความไว้ใจมาได้ช้า บางคนยังจับตามองเจ้าอย่างแข็งกร้าว ข้าช่วยให้พวกเขายอมรับเจ้าได้\n\nพวก Deadwood สวมเชือกร้อยลูกปัดงาม ๆ จากดินหายาก หินผิวเรียบ และของแข็งที่ภูเขามอบให้ ลูกปัดพวกนี้บอกฐานะในเผ่าของมัน เอาเครื่องหมายพวกนี้มาให้ข้าเป็นหลักฐานว่าเจ้าลงมือแล้ว\n\nทุกแปดเม็ดที่เอามา ชื่อของเจ้าจะมีน้ำหนักกับเรามากขึ้น\nไปเถิด ให้ป่าเห็นความมุ่งมั่นของเจ้า" },
        title = { "17:552022638:21089749", "ลูกปัดสำหรับ Brerufa" },
    },
    [94399] = { -- Ravasaur Provisions
        description = { "321:568758093:1856837367", "Ravasaur ใน Un'Goro เป็นสัตว์กินเนื้อล้วน หมายความว่ามันกินแต่เนื้อ ที่นี่อาจอุดมสมบูรณ์ แต่พอถึงคราวที่เหยื่อหายากขึ้นมาจริง ๆ ป่าก็กลายเป็นที่นองเลือดได้\n\nเจ้าจะพบ Diemetradon และ Pterrordax ทั่ว Un'Goro เอาเนื้อพวกมันมาให้ข้า!" },
        title = { "19:335758374:435516653", "เสบียงสำหรับ Ravasaur" },
        objective = { "80:1872787573:203695153", "รวบรวม Diemetradon Meat 5 ชิ้นและ Pterrordax Meat 5 ชิ้นให้ Mor'vek ใน Un'Goro Crater" },
    },
    [94400] = { -- Silithid Intrusion
        description = { "458:1631498582:1394757127", "ระบบนิเวศ Un'Goro มั่นคงพอจะอยู่รอดจากแทบทุกอย่างยกเว้นอุกกาบาตพุ่งชน แต่ภัยอย่างหนึ่งกำลังคืบเข้ามาคุกคามทุกชีวิตและทุกสิ่งในปล่อง นั่นคือ Silithid\n\nแมลงหลงมาเพียงตัวเดียวก็เริ่มรังได้แล้ว และตามภูเขาด้านใต้ก็มีพื้นแตกร้าวเปิดลงสู่อุโมงค์คดเคี้ยวอยู่จริง\n\nเจ้าพวกนี้ดุร้ายและแพร่ไปเหมือนโรคระบาด มันเข้ามาใกล้ถิ่น Ravasaur เกินไป ต้องลดจำนวนลง" },
        title = { "18:394429637:934379980", "Silithid รุกล้ำ" },
    },
    [94401] = { -- Stomping Giants
        description = { "501:1678493386:1911422765", "เจ้าอาจเคยได้ยินชื่อโคโด แต่เคยได้ยินชื่อสเตโกดอนไหม? โคโดสืบสายมาจากสเตโกดอนผู้ยิ่งใหญ่ แต่ตอนนี้แทบไม่เหลือสเตโกดอนนอกปล่องลึกแล้ว! ไกลออกไปทางตะวันตกเฉียงใต้มีที่ที่เรียกว่า Terror Run เป็นที่แห่งสุดท้ายที่สัตว์ยักษ์นี้ยังเดินเตร่ได้อย่างอิสระ\n\nพวกมันสร้างความรำคาญ ถึงมีแนวโน้มจะเป็นเหยื่อมากกว่าผู้ล่า แต่ขนาดตัวมหึมากับเสียงย่ำเท้าดังกึกก้องทำให้ไดโนเสาร์ส่วนใหญ่ไม่กล้าออกจากรัง\n\nจัดการสักสองสามตัว ให้แถวนั้นเงียบลงหน่อย" },
        title = { "15:507573553:1166146853", "ยักษ์เท้าหนัก" },
    },
    [96246] = { -- Blackmaw Pouches
        description = { "77:891216574:1985511908", "ทุกห่อที่เจ้านำกลับมาคือเครื่องหมายว่าเจ้าได้ช่วยคนของข้า" },
        title = { "16:312315657:740402459", "ถุงของชาว Blackmaw" },
    },
    [96601] = { -- CLUCK! CLUCK!
        description = { "312:728819006:940569229", "*กุ๊ก... กุ๊ก... กุ๊ก... กะต๊าก!*\n\n*กุ๊ก... กุ๊ก... กุ๊ก*\n\n<ไก่เงยหน้ามองเจ้าด้วยตาเล็ก ๆ ที่ดูไม่ประทับใจ ดูเหมือนมันอยากได้อะไรจากเจ้า\n\nมันจิกขนตัวเองออกหนึ่งเส้น ปล่อยให้ตกลงพื้น แล้วเงยหน้ามองเจ้าอย่างคาดหวัง ขนนั้นอาจเป็นเบาะแสว่ามันอยากได้อะไร?>" },
        title = { "13:282111376:1128270961", "กุ๊ก ๆ กุ๊ก ๆ!" },
    },
    [96602] = { -- More Unstable Magic
        description = { "157:1191613204:1088583638", "เอาละอองเวทไม่เสถียรที่พบระหว่างเดินทางมาให้ข้าเพิ่ม ข้อมูลใดก็ตามที่เราสกัดจากเศษพวกนี้ได้จะมีค่ายิ่งต่อ Kirin Tor" },
        title = { "19:962380120:822796252", "เวทมนตร์ไม่เสถียรเพิ่มเติม" },
    },
    [97267] = { -- Unsullied Owl Statuette
        description = { "345:350773088:666799361", "<เจ้าพบรูปสลักนกฮูกชวนสนใจขณะสำรวจ Barrow Deeps มันสลักจากหินชนิดแปลกที่ทนทาน มีไพลินสองเม็ดฝังเป็นดวงตา เสียงเวทหึ่งเบา ๆ ดังคลอแสงจาง ๆ ที่ใกล้ดับจากอัญมณีทั้งสอง\n\nเหล่า Watcher ที่ยืนเฝ้าอยู่นอกอุโมงค์น่าจะสนใจสิ่งที่เจ้าพบ>" },
        title = { "23:978628695:732556160", "รูปสลักนกฮูกไร้มลทิน" },
    },
    [98462] = { -- Shroud of the Winter Wilds
        description = { "243:10561973:811794752", "กลับมาขอเพิ่มหรือ? เจ้ารู้ว่าต้องทำอะไร! เอา Chillwind Chimaera Fur กับ Winterspring Owl Feathers มาให้ข้า แล้วข้าจะใช้ผสมยาพรางตัวให้สัตว์ที่อยู่แถวนี้มองเห็นเจ้ายากขึ้น" },
        title = { "26:72209165:930436015", "พรางตัวในพงไพรเหมันต์" },
    },
    [98476] = { -- More Unstable Magic
        description = { "184:380278258:2016419242", "เอาละอองเวทไม่เสถียรที่พบระหว่างเดินทางมาให้ข้าเพิ่ม ดูเหมือนโครงสร้างของความเป็นจริงเองกำลังปริออก และ Earthen Ring ต้องการวัตถุดิบมาศึกษาเพิ่ม" },
        title = { "19:962380120:822796252", "เวทมนตร์ไม่เสถียรเพิ่มเติม" },
    },
    [98529] = { -- Junkboxes Needed
        description = { "437:1724268570:791519982", "พวกโร้กของข้าต้องฝึกสะเดาะกุญแจ ข้าต้องการแม่กุญแจที่ยากพอ ของที่ Zan ทำให้เราเหมาะแค่มือใหม่หัดทำเท่านั้น\n\nเอา Heavy Junkbox มาให้ข้าห้ากล่อง แล้วข้าจะให้มีดขว้างชั้นยอดที่พวกโร้กรู้จักแก่เจ้า\n\nเจ้าสะเดาะเปิดกล่องแล้วค้นของข้างในได้ แต่ต้องเหลือเหรียญไว้สักสองสามเหรียญ โร้กฝึกหัดก็ต้องมีแรงจูงใจเหมือนกัน" },
        title = { "16:1184089809:1551674541", "ต้องการกล่องของจุกจิก" },
    },
    [98890] = { -- Conflict at Darkspear Islands
        description = { "42:1531169962:1566053560 N 81:267662352:433505481", "การต่อสู้ที่ Darkspear Islands ยังดำเนินต่อไป {name} ความช่วยเหลืออย่างต่อเนื่องของเจ้าจะช่วยให้เราขับไล่ Theramore Expeditionary Force!" },
        title = { "29:1287698681:114040245", "ศึกที่ Darkspear Islands" },
    },
    [98892] = { -- Conflict at Darkspear Islands
        description = { "41:1437134004:72077190 N 96:1014315857:2013442311", "การรบที่ Darkspear Islands ยังดุเดือด {name} สิ่งที่เจ้าทำช่วยให้เราเข้าใกล้ชัยชนะเหนือ Theramore Expeditionary Force ไปอีกก้าว!" },
        title = { "29:1287698681:114040245", "ศึกที่ Darkspear Islands" },
    },
    [98894] = { -- Conflict at Darkspear Islands
        description = { "41:1437134004:72077190 N 96:1014315857:2013442311", "การรบที่ Darkspear Islands ยังดุเดือด {name} สิ่งที่เจ้าทำช่วยให้เราเข้าใกล้ชัยชนะเหนือ Theramore Expeditionary Force ไปอีกก้าว!" },
        title = { "29:1287698681:114040245", "ศึกที่ Darkspear Islands" },
    },
    [98898] = { -- Darkspear Islands Clash
        description = { "46:330561356:780518666 N 52:1002057759:1095990623", "การต่อสู้ที่ Darkspear Islands ยังดำเนินต่อไป {name} รวมพลแล้วบดขยี้ Darkspear Raiders!" },
        title = { "23:1858373989:1998541756", "ปะทะที่ Darkspear Islands" },
    },
    [98900] = { -- Darkspear Islands Clash
        description = { "46:330561356:780518666 N 52:1002057759:1095990623", "การต่อสู้ที่ Darkspear Islands ยังดำเนินต่อไป {name} รวมพลแล้วบดขยี้ Darkspear Raiders!" },
        title = { "23:1858373989:1998541756", "ปะทะที่ Darkspear Islands" },
    },
    [98902] = { -- Darkspear Islands Clash
        description = { "46:330561356:780518666 N 52:1002057759:1095990623", "การต่อสู้ที่ Darkspear Islands ยังดำเนินต่อไป {name} รวมพลแล้วบดขยี้ Darkspear Raiders!" },
        title = { "23:1858373989:1998541756", "ปะทะที่ Darkspear Islands" },
