    [93799] = { -- The Eyes of the Spire
        title = { "21:1678657882:1090889272", "ดวงตาแห่ง Blackrock Spire" },
        description = { "495:1270067108:1389785375", "สิ่งนี้เคยเป็นหมวกเกราะชนิดหนึ่ง แต่ตอนนี้บิดเบี้ยวจนแทบดูไม่ออก ถึงอย่างนั้นเราก็ทำให้มันกลับคืนสภาพเดิมได้ แน่นอนว่าทุกอย่างล้วนมีราคาที่ต้องจ่าย\n\nไปยังป้อม Blackrock Spire แล้วชิงดวงตาข้างซ้ายของ Rend Blackhand หัวหน้าสงครามจอมปลอม จากนั้นขึ้นไปยังยอดป้อมเพื่อชิงดวงตาข้างขวาของแม่ทัพ Drakkisath มือขวาของเจ้าแห่ง Blackrock\n\nเมื่อทำสำเร็จ เจ้าจะกำจัดภัยร้ายใหญ่หลวงไปจากโลกได้ถึงสองราย แล้วข้าจะชำระล้างวัตถุโบราณที่เจ้านำมาด้วย" },
    },
    [98968] = { -- The Eyes of the Spire
        title = { "21:1678657882:1090889272", "ดวงตาแห่ง Blackrock Spire" },
        description = { "495:1270067108:1389785375", "สิ่งนี้เคยเป็นหมวกเกราะชนิดหนึ่ง แต่ตอนนี้บิดเบี้ยวจนแทบดูไม่ออก ถึงอย่างนั้นเราก็ทำให้มันกลับคืนสภาพเดิมได้ แน่นอนว่าทุกอย่างล้วนมีราคาที่ต้องจ่าย\n\nไปยังป้อม Blackrock Spire แล้วชิงดวงตาข้างซ้ายของ Rend Blackhand หัวหน้าสงครามจอมปลอม จากนั้นขึ้นไปยังยอดป้อมเพื่อชิงดวงตาข้างขวาของแม่ทัพ Drakkisath มือขวาของเจ้าแห่ง Blackrock\n\nเมื่อทำสำเร็จ เจ้าจะกำจัดภัยร้ายใหญ่หลวงไปจากโลกได้ถึงสองราย แล้วข้าจะชำระล้างวัตถุโบราณที่เจ้านำมาด้วย" },
    },
