    [98982] = { -- The Weight of the World
        title = { "23:754598762:573906209", "ภาระหนักแห่งโลก" },
        description = { "476:2078547719:902691187", "เจ้าฝ่าความตรากตรำและความทรมานเพื่อแสวงหาทรัพย์สมบัติและเกียรติยศ มุ่งไปข้างหน้าและไต่ขึ้นสูงไม่หยุด ชีวิตเช่นนี้เป็นภาระหนักสำหรับเราทุกคนที่เลือกเดินเส้นทางนี้ แล้วเราจะไม่ช่วยปลดสิ่งที่ถ่วงบ่าของศัตรูเราบ้างหรือ?\n\nนคร Stratholme เป็นที่อยู่ของผู้ชั่วร้ายสองคนที่เป็นศัตรูกัน เอาผ้าคลุมบ่าของ Dathrohan นักรบครูเสดจอมปลอมจากป้อมใหญ่ของเขามาให้ข้า พร้อมกับเกราะไหล่ของผู้ที่เรียกกันว่า Rivendare จากที่มั่นในโรงเชือดของเขา" },
    },
