    [99007] = { -- Blood Pact
        title = { "10:2082933476:1982539913", "พันธสัญญาโลหิต" },
        description = { "478:1128569156:1698365860", "ซากนครที่เรียกว่า Dire Maul เป็นสุสานอันเงียบขรึม ชาวคัลโดเรียนับไม่ถ้วนต้องสละชีวิตเพื่อชดใช้ข้อตกลงอันน่าสะพรึงที่ทำไว้กับสิ่งชั่วร้ายซึ่งไร้ความคิดและไร้ความรู้สึก ทั้งหมดก็เพื่อคงความโอ่อ่าและชีวิตอมตะของคนเพียงหยิบมือ\n\nจงไปที่นั่นและสังหารอสูรนาม Immol'thar ที่อยู่ใจกลางปีกตะวันตกของนคร นำเลือดต้องสาปของมันหนึ่งขวดมาให้ข้า แล้วตัดวงจรแห่งความตายในสถานที่อาถรรพ์แห่งนั้นเสีย จากนั้นข้าจะชำระล้างวัตถุโบราณที่เจ้าถือมา" },
    },
    [99008] = { -- Blood Pact
        title = { "10:2082933476:1982539913", "พันธสัญญาโลหิต" },
        description = { "478:1128569156:1698365860", "ซากนครที่เรียกว่า Dire Maul เป็นสุสานอันเงียบขรึม ชาวคัลโดเรียนับไม่ถ้วนต้องสละชีวิตเพื่อชดใช้ข้อตกลงอันน่าสะพรึงที่ทำไว้กับสิ่งชั่วร้ายซึ่งไร้ความคิดและไร้ความรู้สึก ทั้งหมดก็เพื่อคงความโอ่อ่าและชีวิตอมตะของคนเพียงหยิบมือ\n\nจงไปที่นั่นและสังหารอสูรนาม Immol'thar ที่อยู่ใจกลางปีกตะวันตกของนคร นำเลือดต้องสาปของมันหนึ่งขวดมาให้ข้า แล้วตัดวงจรแห่งความตายในสถานที่อาถรรพ์แห่งนั้นเสีย จากนั้นข้าจะชำระล้างวัตถุโบราณที่เจ้าถือมา" },
