    [99016] = { -- Heart of Flesh, Heart of Stone
        title = { "30:745843149:58401862", "หัวใจเนื้อ หัวใจหิน" },
        description = { "475:67941006:872608405", "หัวใจของสิ่งมีชีวิตมีพลังอยู่ในตัว มันคือแก่นของชีวิต เมื่อไร้หัวใจ ผู้มีชีวิตก็อยู่ต่อไปไม่ได้ บางครั้งข้าก็คิดถึงเสียงหัวใจของตัวเอง แต่ก็ยอมรับว่าการต้องมีชีพจรถึงจะมีชีวิตอยู่นั้น... เป็นภาระล้วน ๆ\n\nไปยัง Shaper's Terrace ซึ่งมองลงไปเห็น Un'Goro Crater แล้วนำหัวใจที่ยังเต้นอยู่ของ Direhorn Matriarch ตัวใหญ่มาให้ข้า พร้อมกับหัวใจที่แข็งเป็นหินของผู้พิทักษ์ Nanaya\n\nทำสำเร็จแล้วข้าจะชำระล้างชิ้นเกราะที่เจ้านำมาด้วย" },
    },
    [99017] = { -- A Kingly Tribute
        title = { "16:52687008:389561689", "เครื่องบรรณาการแด่ราชา" },
        description = { "493:209594360:1570163730", "ในซากนคร Dire Maul มีบัลลังก์ของราชาเหล่าโอเกอร์ Gordok ขุนศึกผู้นี้ปล้นสมบัติส่วนใหญ่ของอาณาจักรคัลโดเรที่ล่มสลายไป รวมถึงอัญมณีประจำราชวงศ์ผู้ปกครอง Eldre'Thalas โบราณ ข้าต้องการอัญมณีเหล่านี้ เจ้าจงไปนำมันมาให้ข้า\n\nสมบัติเหล่านี้คงถูกซ่อนไว้อย่างดี เจ้าอาจต้องใช้ไหวพริบทั้งในการโค่นราชาและทำให้เหล่าบริวารของเขายอมมอบเครื่องบรรณาการให้ นำอัญมณีกลับมาให้ข้า แล้วข้าจะชำระมลทินจากเกราะขาที่เจ้าถือมา" },
    },
    [99018] = { -- Heart of Flesh, Heart of Stone
        title = { "30:745843149:58401862", "หัวใจเนื้อ หัวใจหิน" },
        description = { "475:67941006:872608405", "หัวใจของสิ่งมีชีวิตมีพลังอยู่ในตัว มันคือแก่นของชีวิต เมื่อไร้หัวใจ ผู้มีชีวิตก็อยู่ต่อไปไม่ได้ บางครั้งข้าก็คิดถึงเสียงหัวใจของตัวเอง แต่ก็ยอมรับว่าการต้องมีชีพจรถึงจะมีชีวิตอยู่นั้น... เป็นภาระล้วน ๆ\n\nไปยัง Shaper's Terrace ซึ่งมองลงไปเห็น Un'Goro Crater แล้วนำหัวใจที่ยังเต้นอยู่ของ Direhorn Matriarch ตัวใหญ่มาให้ข้า พร้อมกับหัวใจที่แข็งเป็นหินของผู้พิทักษ์ Nanaya\n\nทำสำเร็จแล้วข้าจะชำระล้างชิ้นเกราะที่เจ้านำมาด้วย" },
    },
    [99019] = { -- Heart of Flesh, Heart of Stone
        title = { "30:745843149:58401862", "หัวใจเนื้อ หัวใจหิน" },
        description = { "475:67941006:872608405", "หัวใจของสิ่งมีชีวิตมีพลังอยู่ในตัว มันคือแก่นของชีวิต เมื่อไร้หัวใจ ผู้มีชีวิตก็อยู่ต่อไปไม่ได้ บางครั้งข้าก็คิดถึงเสียงหัวใจของตัวเอง แต่ก็ยอมรับว่าการต้องมีชีพจรถึงจะมีชีวิตอยู่นั้น... เป็นภาระล้วน ๆ\n\nไปยัง Shaper's Terrace ซึ่งมองลงไปเห็น Un'Goro Crater แล้วนำหัวใจที่ยังเต้นอยู่ของ Direhorn Matriarch ตัวใหญ่มาให้ข้า พร้อมกับหัวใจที่แข็งเป็นหินของผู้พิทักษ์ Nanaya\n\nทำสำเร็จแล้วข้าจะชำระล้างชิ้นเกราะที่เจ้านำมาด้วย" },
    },
