    [99032] = { -- A Kingly Tribute
        title = { "16:52687008:389561689", "เครื่องบรรณาการแด่ราชา" },
        description = { "493:209594360:1570163730", "ในซากนคร Dire Maul มีบัลลังก์ของราชาเหล่าโอเกอร์ Gordok ขุนศึกผู้นี้ปล้นสมบัติส่วนใหญ่ของอาณาจักรคัลโดเรที่ล่มสลายไป รวมถึงอัญมณีประจำราชวงศ์ผู้ปกครอง Eldre'Thalas โบราณ ข้าต้องการอัญมณีเหล่านี้ เจ้าจงไปนำมันมาให้ข้า\n\nสมบัติเหล่านี้คงถูกซ่อนไว้อย่างดี เจ้าอาจต้องใช้ไหวพริบทั้งในการโค่นราชาและทำให้เหล่าบริวารของเขายอมมอบเครื่องบรรณาการให้ นำอัญมณีกลับมาให้ข้า แล้วข้าจะชำระมลทินจากเกราะขาที่เจ้าถือมา" },
    },
    [99033] = { -- A Kingly Tribute
        title = { "16:52687008:389561689", "เครื่องบรรณาการแด่ราชา" },
        description = { "493:209594360:1570163730", "ในซากนคร Dire Maul มีบัลลังก์ของราชาเหล่าโอเกอร์ Gordok ขุนศึกผู้นี้ปล้นสมบัติส่วนใหญ่ของอาณาจักรคัลโดเรที่ล่มสลายไป รวมถึงอัญมณีประจำราชวงศ์ผู้ปกครอง Eldre'Thalas โบราณ ข้าต้องการอัญมณีเหล่านี้ เจ้าจงไปนำมันมาให้ข้า\n\nสมบัติเหล่านี้คงถูกซ่อนไว้อย่างดี เจ้าอาจต้องใช้ไหวพริบทั้งในการโค่นราชาและทำให้เหล่าบริวารของเขายอมมอบเครื่องบรรณาการให้ นำอัญมณีกลับมาให้ข้า แล้วข้าจะชำระมลทินจากเกราะขาที่เจ้าถือมา" },
    },
    [99034] = { -- The Path of Frost
        title = { "17:426535257:229077291", "เส้นทางแห่งเหมันต์" },
        description = { "436:667332693:1119184455", "ลิชนาม Ras Frostwhisper อาศัยอยู่บนเกาะ Caer Darrow ในสถานฝึกของ Cult of the Damned ที่เรียกว่า Scholomance มันมีวัตถุดิบเล่นแร่แปรธาตุล้ำค่าอยู่หลายอย่าง รวมถึงตัวอย่าง Everfrost จาก Frozen Throne โดยตรง\n\nข้าต้องการให้เจ้านำมันมาให้ข้า\n\nอ้อ ไหน ๆ ก็ไปแล้ว ข้าอยากให้เจ้ากำจัดอาจารย์ใหญ่ Gandling ด้วย นำตราประทับของเขามาให้ข้าเป็นหลักฐาน" },
    },
