    [78830] = { -- Terror of the Desert Skies
        title = { "26:80610504:2020814861", "ภัยสยองเหนือน่านฟ้าทะเลทราย" },
        objective = { "112:1392662151:677175430", "หา Crimson Trophy Quill จาก Gharrik ใน Badlands แล้วกลับไปหา Hemet Nesingwary ใน Stranglethorn Vale" },
        description = { "499:1954978449:2031714602", "ภาพวาดนี้ทำให้ข้านึกถึงเรื่องที่ได้ยินระหว่างออกสำรวจเมื่อไม่นานมานี้ เขาเล่าถึง Gharrik นกยักษ์ที่ครอง Badlands ในฐานะนักล่าบนสุดของห่วงโซ่อาหาร\n\nมีคนเห็นมันครั้งสุดท้ายทางตะวันออกเฉียงเหนือของ Camp Cagg รังของมันอาจอยู่แถวนั้นก็ได้\n\nเจ้าต้องใช้เหยื่อเป็นล่อมันออกมา ข้าจะให้ยืมกรงไว้จับเหยื่อ สัตว์เล็กใน Badlands หายาก เจ้าคงต้องไปหาเหยื่อที่อื่น\n\nขนปีกของ Gharrik คงเป็นของรางวัลชั้นดี รับรองว่าคนทั้งค่ายจะพูดถึงเจ้า" },
        progress = { "55:481156:432025593", "ล่าไปถึงไหนแล้ว? อย่าบอกนะว่าเจ้านกนั่นเล่นงานเจ้าจนไปต่อไม่ไหว!" },
        completion = { "49:177229274:1907555346 N 96:1472590008:1411785684", "ขนนกนี้คู่ควรกับหมวกเจ้าเลย! ทำได้ดีมาก {name}\n\nพักที่นี่สักหน่อยก็ได้ การเดินทางข้ามทะเลทรายคงเหนื่อยน่าดู" },
        required = { [211293] = { "20:437555506:1398823241", "ขนนกสีชาดที่ได้เป็นรางวัล" } },
        steps = { { "20:437555506:1398823241", "ขนนกสีชาดที่ได้เป็นรางวัล" } },
    },
    [79235] = { -- On the Lam
        title = { "10:2127829519:1061841593", "หลบหนีการตามล่า" },
        objective = { "35:1442389926:1873159476", "ตามหาหนึ่งในกลุ่มโจรจาก Desolace" },
        description = { "49:1592372622:726253026 N 424:1118845538:1371570049", "ข้าเคยเจอที่เกิดเหตุแบบที่เจ้าเล่ามาสองสามแห่ง {name} เป็นค่ายของมนุษย์กับคนแคระทั้งนั้น พวกคาราวานลือกันว่ากลุ่มโจรจาก Horde เป็นคนลงมือ ดูจะเป็นไปได้เมื่อดูจากเหยื่อและความโหดร้ายของการโจมตี\n\nดูเหมือนพวกโจรจะหนีออกจาก Desolace หลังนายทหารฝ่าย Alliance ตามรอยพวกมันจนใกล้จะจับได้\n\nถ้าจะตามหาพวกมันสักคน ข้าจะลองไปดูที่ Booty Bay เมืองท่ามีคนไม่น่าไว้ใจเข้าออกอยู่เสมอ เจ้าอาจเจอคนหนึ่งกำลังหาทางลงเรือไปที่ไหนสักแห่ง" },
        completion = { "34:385613805:689159951", "มีธุระอะไร? ว่ามาเร็ว ๆ" },
    },
    [79365] = { -- With Wind Beneath Your Wings
        title = { "28:1609713399:1177331811", "ลมหนุนใต้ปีก" },
        objective = { "63:1921559051:1419675746", "กลับไปหา Rau Cliffrunner ที่ Freewind Post ใน Thousand Needles" },
        description = { "251:1587744888:1382860019", "เอ้านี่ สหาย Squall-breakers Potion นี่แหละที่เจ้าต้องใช้ ดื่มแล้วมันจะคุ้มกันเจ้าจากธาตุที่ปั่นป่วนในพายุ แต่อย่าลืมว่าฤทธิ์ยาอยู่ได้ไม่นาน\n\nไปเถอะ กลับไปหาเพื่อนที่ต้องการความช่วยเหลือ ข้าช่วยเจ้าได้เท่านี้" },
        completion = { "159:406704480:1956926279", "ผู้ขี่สัตว์บินของเราพบบางอย่าง แต่เข้าไปใกล้พอจะประเมินสถานการณ์ไม่ได้ เจออะไรที่พอช่วยเราได้บ้างไหม" },
    },
    [79945] = { -- Orders from the Grand Crusader
        title = { "30:1167049474:1448935315", "คำสั่งจาก Grand Crusader" },
        objective = { "68:1419220778:1866809584", "นำ Orders from the Grand Crusader กลับไปให้ Katherine the Pure" },
        description = { "419:607740664:1235951278", "ดูเหมือนนี่จะเป็นคำสั่งจาก Dathrohan ผู้เป็น Grand Crusader แห่ง Scarlet Crusade ด้วยตัวเอง ดูท่าว่า Aeonas จะไปมีเรื่องกับพวกนั้น จากสภาพตรงหน้า ดูเหมือนพวกครูเสดจะตามรอย Aeonas มาถึงที่นี่และจับตัวเขาไป เขาคงต่อสู้ก่อนจะถูกจับ\n\nข้อกล่าวหาที่มีต่อ Aeonas นั้นร้ายแรง แต่ก็พออธิบายสิ่งที่เจ้าพบใน Desolace ได้บางส่วน" },
        completion = { "330:1825332458:802670892", "<Katherine ขมวดคิ้วขณะอ่านจดหมาย>\nตอนออกจากภาคี Aeonas มีความคิดที่ต่างจากคนอื่นไปมาก แต่ข้าแทบไม่เชื่อเลยว่าที่เขาไป Desolace จะเกี่ยวข้องกับการคบหาปีศาจ อันเดด หรืออะไรทำนองนั้น เราต้องตามหาเขาและฟังความจากปากเขา เรื่องนี้มีอะไรมากกว่าที่เห็น ข้ามั่นใจ" },
        progress = { "28:1279349890:1344485244", "มีข่าวของ Aeonas มาบอกหรือ?" },
        steps = { { "33:421031861:1768147215", "กลับไปรายงาน Katherine the Pure" }, { "30:1167049474:1448935315", "คำสั่งจาก Grand Crusader" } },
    },
    [79946] = { -- A Brother In Need
        title = { "17:1560732613:1965655665", "พี่น้องที่ต้องการความช่วยเหลือ" },
        objective = { "92:310750248:1209740440", "คุยกับ Katherine เพื่อฟังเรื่องของ Aeonas เพิ่มเติม แล้วไปตามหาเขาใน Scarlet Monastery" },
        description = { "423:245210921:1678913828", "เมื่อคิดถึงเหตุอัน... น่าเศร้าที่ทำให้เขาออกจากภาคี คงเป็นตลกร้ายหาก Aeonas ต้องมาตายด้วยน้ำมือของ Scarlet Crusade ตอนนี้ พวกครูเสดเป็นกลุ่มคนคลั่งศรัทธาและคนเสียสติ พวกมันยิ่งกล้าใช้ความรุนแรงกับใครก็ตามที่ทึกทักว่าเป็นศัตรูของแสงสว่าง ไปที่ Scarlet Monastery ใน Tirisfal Glades แล้วดูว่า Aeonas ยังมีชีวิตอยู่ไหม" },
        completion = { "117:417964582:768365004", "<Aeonas บาดเจ็บสาหัส เขาฝืนเค้นเสียงออกมาได้เพียงไม่กี่คำ> พวกมันไม่ได้แม้แต่... ถามอะไรข้าสักคำ..." },
        steps = { { "38:216316041:1059849704", "ถาม Katherine เรื่อง Aeonas เพิ่มเติม" }, { "36:778646272:1343180759", "ตามหา Aeonas ใน Scarlet Monastery" } },
    },
    [79970] = { -- Aeonas the Vindicated
        title = { "21:376046204:192044636", "Aeonas ผู้พ้นข้อครหา" },
        objective = { "51:1774545370:1714867499", "ไปพบ Aeonas ที่ Cathedral of Light ใน Stormwind" },
        description = { "25:2112727214:1834163064 C 297:26526101:382691043", "ขอบใจที่ช่วยข้าไว้ {class} ดูเหมือนข้าจะไม่ได้หนุ่มเหมือนเมื่อก่อนแล้ว และข้าคงต้องหาพันธมิตรไว้รับมือกับสิ่งที่จะเกิดขึ้น เมื่อเจ้าพร้อมแล้ว มาพบข้าที่ Cathedral of Light ใน Stormwind โดยเร็วเถอะ\n\nไม่ต้องห่วงข้า ข้าหาทางออกไปเองได้ ขอพักฟื้นแรงสักครู่ก็พอ" },
        completion = { "376:1272419781:1658118787", "ข้าไม่รู้จะขอบใจเจ้าอย่างไรที่ช่วยข้าออกมาจากที่ที่แสงศักดิ์สิทธิ์ทอดทิ้งนั้น น่าเสียดาย ข้าเกรงว่านี่เพิ่งเป็นจุดเริ่มต้นของการเดินทาง และหนทางข้างหน้าคงไม่ง่าย มาคุยกันเถอะว่าเราจะทำอะไรต่อไป\nอ้อ แต่ก่อนอื่น... ขอให้คนแก่คนนี้ถ่ายทอดความรู้สักหน่อยให้คนรุ่นหลัง รางวัลนี้อาจไม่มาก แต่ข้าหวังว่าเจ้าจะเอาไปใช้ให้เป็นประโยชน์" },
        steps = { { "50:516618863:1685177081", "พบ Aeonas ที่ Cathedral of Light ใน Stormwind" } },
    },
    [79098] = { -- Clear the Forest!
        title = { "17:980490753:1934719924", "กวาดล้างป่า!" },
        objective = { "93:1249482090:2122305225", "นำ Silverwing Sentinel Charm ไปให้ Kazragore, Far Seer ที่ฐาน Bonfire ใน Ashenvale" },
        description = { "90:59041494:1554819859", "เจ้านี่ตายแล้ว แต่พวก Alliance น่ารำคาญยังสู้ไม่เลิก... เครื่องรางนี่มันอะไรกัน?" },
        progress = { "N 39:822209033:1553478821", "{name} มีข่าวอะไรจากแนวหน้าบ้าง?" },
        completion = { "215:1498413527:570195474 N 1:33:33", "พวกหมา Alliance ยังขวางทางเราไม่ให้เก็บทรัพยากรที่ Orgrimmar ต้องการ ไล่พวกมันออกไปให้ได้!\n\nกลองศึก Warsong ใบนี้จะปลุกใจให้เจ้าฮึดสู้ยิ่งขึ้น Lok'tar Ogar, {name}!" },
        required = { [211813] = { "25:997957412:267685847", "เครื่องรางของทหารยาม Silverwing" } },
        steps = { { "25:997957412:267685847", "เครื่องรางของทหารยาม Silverwing" } },
    },
    [79963] = { -- By The Light's Grace
        title = { "20:728987550:74333949", "ด้วยพระกรุณาแห่งแสงสว่าง" },
        objective = { "12:1496336874:518500716", "รักษา Aeonas" },
        description = { "80:1987916732:1138155280", "ต้องรีบรักษา Aeonas เดี๋ยวนี้ ไม่อย่างนั้นเขาจะตาย จงเรียกพลังแห่งแสงสว่างมาช่วยชีวิตเขา", variants = { { "82:388750821:1324998772", "<ต้องรีบรักษา Aeonas เดี๋ยวนี้ ไม่อย่างนั้นเขาจะตาย จงเรียกพลังแห่งแสงสว่างมาช่วยชีวิตเขา>" } } },
        completion = { "191:1494295610:942090485 C 20:690179845:657224198", "<ดูเหมือน Aeonas จะหายใจได้คล่องขึ้น เขายังดูอ่อนแรงมาก แต่ก็พอหันหน้ามาพูดกับเจ้าได้>\n\nเจ้าว่า Katherine ส่งเจ้ามาหรือ? ขอให้นางได้รับพร ขอบใจเจ้า {class} ข้าเป็นหนี้บุญคุณเจ้า" },
    },
    [81917] = { -- Chains That Bind
        title = { "16:735307540:358530914", "โซ่ตรวนพันธนาการ" },
        objective = { "70:1432414725:1642291212", "นำ Infernal Chain Link 5 ข้อไปให้ Bloodmage Lynnore ใน Blasted Lands" },
        description = { "486:773114328:1992504881", "ข้าเคยเห็นสัตว์ที่เจ้าเรียกว่า “Calefactus” หลายครั้งระหว่างออกสำรวจ เท่าที่ทราบ มันน่าจะเป็นคอร์ฮาวนด์ที่ก่อตัวจากพลังเฟลและแทบไม่มีอะไรทำอันตรายมันได้\n\nแต่ถ้าที่เจ้าบอกเป็นจริง และพวก Twilight's Hammer วางแผนจับมันมาเป็นทาส ก็คงมีทางปราบมันให้เชื่องได้\n\nพวก Shadowsworn ทางตะวันออกเฉียงใต้ขึ้นชื่อเรื่องพิธีกรรมมืด รวมถึงการจับสิ่งมีชีวิตเฟลมาเป็นทาส บางทีสมาชิกกลุ่มนั้นอาจมีเบาะแสว่าจะทำให้ Calefactus อ่อนกำลังลงได้อย่างไร" },
        completion = { "41:1730807712:1351809379", "น่าสนใจ... ใช่ ข้าเอาสิ่งนี้ไปใช้ได้" },
        progress = { "44:2057233513:739235495 R 1:63:63", "เจอเครื่องมือที่จะทำให้ Calefactus อ่อนแรงลงหรือยัง {race}?" },
        required = { [220214] = { "19:1065891095:1878917964", "ข้อโซ่ของอินเฟอร์นัล" } },
        steps = { { "19:1065891095:1878917964", "ข้อโซ่ของอินเฟอร์นัล" } },
    },
    [81919] = { -- Brought to Heel
        title = { "15:794397904:1341635867", "ปราบให้อยู่หมัด" },
        objective = { "93:126135873:1343543605", "นำเลือดเฟลของ Calefactus the Unleashed ไปให้ Bloodmage Lynnore ใน Blasted Lands" },
        description = { "462:323776532:835214449 C 1:46:46", "ข้าเอาข้อโซ่ที่เจ้าหาได้มาทำเป็นเครื่องมือ จะเรียกมันว่าบ่วงคล้องก็ได้\n\nพลังในโซ่นี้เหมาะกับการพันธนาการปีศาจที่สุด แต่ Calefactus อาจมาจากอีกฟากของ Dark Portal ข้าจึงคิดว่าน่าจะใช้กับมันได้เหมือนกัน\n\nถ้าปราบมันลงได้ ให้นำเลือดเฟลของมันมาให้ข้าสักตัวอย่าง สิ่งมีชีวิตผิดธรรมชาติเช่นนี้ควรค่าแก่การศึกษาเพิ่มเติม\n\nตอนนี้ยังไม่รู้ว่า Calefactus อยู่ตรงไหนในดินแดนรกร้างนี้ แต่ข้าเชื่อว่าเจ้าจะตามหามันเจอ {class}" },
        completion = { "192:927106502:1123237478", "ช่างเป็นตัวอย่างที่ยอดเยี่ยม! ใครจะรู้ว่ามีความลับอะไรซ่อนอยู่ในแก่นพลังของสัตว์จากอีกฟากประตูมิติ\n\nข้ายกบ่วงให้เจ้าเป็นคำขอบคุณ ข้าเองคงไม่มีวันต้องใช้ของแบบนี้หรอก" },
        progress = { "30:1473673084:1338982060 N 47:1307904892:1234739631", "รีบตามหาเจ้าหมาล่าเนื้อลาวาตัวนั้นเถอะ {name} ก่อนที่ Twilight's Hammer จะเจอมันเสียก่อน" },
        required = { [220213] = { "13:1179192675:1806081702", "เลือดหล่อเลี้ยงพลังเฟล" }, [220216] = { "14:1196746266:1365034324", "บ่วงของอินเฟอร์นัล" } },
        steps = { { "13:1179192675:1806081702", "เลือดหล่อเลี้ยงพลังเฟล" }, { "14:1196746266:1365034324", "บ่วงของอินเฟอร์นัล" } },
    },
    [81924] = { -- Wisdom of the Guardians
        title = { "23:1165702776:296070042", "ภูมิปัญญาแห่งเหล่าผู้พิทักษ์" },
        objective = { "116:1073205198:774092285", "พิสูจน์ตนต่อวิญญาณผู้พิทักษ์แห่ง Feralas, Azshara และ The Hinterlands แล้วกลับไปหา Tyrisius ใน Feralas" },
        description = { "74:2070980023:1706925053 C 326:1167551978:1643316283", "ความรู้ของคัลโดไรที่เจ้าตามหาคงหาไม่ได้ในซากปรักหักพังนี้แล้ว {class}\n\nแม้สิ่งที่จับต้องได้จะพังทลาย แต่สิ่งที่อยู่ในโลกวิญญาณยังคงอยู่\n\nจงตามหาวิญญาณผู้พิทักษ์แห่ง Azshara, The Hinterlands และ Feralas เจ้าจะรู้ว่าเป็นพวกเขาเมื่อพบศาลของพวกเขา จงพิสูจน์ตนต่อพวกเขาและตั้งใจฟัง ภูมิปัญญาของพวกเขาจะสืบทอดมาถึงเจ้า เพื่อมิให้เลือนหายไปตามกาลเวลาเหมือนสิ่งอื่น ๆ มากมายที่นี่" },
        progress = { "48:1807754483:79669267", "เหล่าวิญญาณถ่ายทอดภูมิปัญญาให้เจ้าแล้วหรือยัง?" },
        completion = { "35:1149251021:588969698 N 215:1749346106:358225334", "เจ้าพิสูจน์แล้วว่าเป็นศิษย์ที่มุ่งมั่น {name} การรักษาความรู้โบราณมักเป็นงานที่หนักหนา แต่เจ้ารับหน้าที่นี้ได้อย่างน่าชื่นชม\n\nโลกนี้ยังมีปริศนาอีกมากให้เจ้าค้นพบ ข้าหวังว่าเครื่องมือเหล่านี้จะช่วยเจ้าในการเดินทางครั้งนั้น" },
        steps = { { "19:126290855:1055653252", "ผู้พิทักษ์แห่ง Feralas" }, { "27:1133838750:277319809", "ผู้พิทักษ์แห่ง The Hinterlands" }, { "19:18110706:1807798824", "ผู้พิทักษ์แห่ง Azshara" } },
    },
    [79483] = { -- Stolen Winter Veil Treats
        title = { "25:1784239235:1438402853", "ขนมวินเทอร์เวลที่ถูกขโมย" },
        objective = { "111:1616362219:207606864", "ค้นหาผู้สืบสวนของ Smokywood Pastures ที่หายตัวไปในบริเวณหิมะของ Alterac Mountains" },
        description = { "491:1691809786:45065330", "ฟังนะ... ไม่ได้อยากทำลายมนตร์เสน่ห์ของเทศกาลหรอก แต่สโมกีวูดพาสเจอร์สต้องการความช่วยเหลือ แบบที่นักผจญภัยอย่างพวกเจ้าถนัด\n\nขนมชุดสำคัญที่จะมาสำรองไว้ขายช่วงเทศกาลหายไป และตอนนี้เจ้าหน้าที่สโมกีวูดพาสเจอร์สที่เราส่งออกไปตามหามันก็หายไปด้วย! ได้โปรด รายงานล่าสุดระบุว่าขนมอยู่ที่เทือกเขาอัลเทอแรค คนของเราจึงไปตามหาที่นั่น\n\nไปดูให้ทีว่าทั้งขนมและคนของเรายังอยู่ที่นั่นอย่างปลอดภัยหรือไม่!" },
        completion = { "320:1661035060:926462967", "จ-จ-เจ้าได้ยินข้า! ข-ข-ขอบคุณกำไรสุทธิ!\n\nข้าไม่ใช่ม-ม-มนุษย์หิมะจริง ๆ ข-ข-ข้าชื่อ Sacks ทำงานให้ Smokywood Pastures สาขา Orgrimmar ข-ข-ข้าถูกส่งมาหาห่อของที่หายไป แล้วก-ก-ก็ถูกสัตว์ที่ไม่เคยเห็นมาก่อนเล่นงาน!\n\nหน-หน-หนาวเหลือเกิน..." },
    },
    [79637] = { -- A Ticking Present
        title = { "17:775475589:1502882257", "ของขวัญที่ส่งเสียงติ๊กต็อก" },
        completion = { "77:357235255:1818371511", "เหล่าสหายของเจ้าจาก Smokeywood Pastures ขอให้เจ้ามีความสุขในเทศกาล Great-Winter" },
    },
    [81731] = { -- Duskwood Mission II: Defeat Ogres
        title = { "33:1001589207:1297636957", "ภารกิจ Duskwood II: กำจัดอสูรโอเกอร์" },
        objective = { "151:472939679:322382958", "กำจัด Deranged Ogre 3 ตัว และ Demented Fire Weaver 3 ตัว ในเขตฝันร้ายที่รุกล้ำ Duskwood บริเวณ Vul'gol Ogre Mound แล้วกลับไปรายงาน Field Captain Palandar" },
        description = { "262:1304501504:759735644", "ระหว่างที่พวกปีศาจดึงความสนใจของเราไว้ที่นี่ Emerald Dream กำลังแปดเปื้อนจนกลายเป็นฝันร้าย รีบผ่านประตูสู่ Emerald Dream ที่ Twilight Grove ไปยังเขตฝันร้ายที่ Vul'gol Ogre Mound กำจัดพวกโอเกอร์ที่นั่นแล้วกลับมาหาข้า" },
        completion = { "73:2141186521:1645197437", "ทำได้ดีมาก! ความช่วยเหลือของเจ้าจะได้รับรางวัลอย่างงาม สนใจรับภารกิจอีกสักงานไหม?" },
        progress = { "28:1207853329:918663219", "เจ้าจัดการพวกโอเกอร์แล้วหรือ?" },
        objectiveLabels = {
            monster = { ["Deranged Ogre slain"] = "ปราบ อ็อกเกอร์เสียสติ", ["Demented Fire Weaver slain"] = "ปราบ ผู้ถักทอเพลิงเสียสติ" },
        },
    },
    [81736] = { -- Duskwood Mission VII: Recover Shadowscythe
        title = { "42:296176118:599251709", "ภารกิจ Duskwood VII: นำ Shadowscythe กลับมา" },
        objective = { "147:900123967:1546297989", "ไปเอา Shadowscythe ที่ชั้นบนของบ้านไร่ใน Rotting Orchard ภายในเขตฝันร้ายที่รุกล้ำ Duskwood แล้วกลับไปหา Field Captain Palandar" },
        description = { "299:106350882:447493327", "ระหว่างที่พวกปีศาจดึงความสนใจของเราไว้ที่นี่ Emerald Dream กำลังแปดเปื้อนจนกลายเป็นฝันร้าย รีบผ่านประตูสู่ Emerald Dream ที่ Twilight Grove ไปยังเขตฝันร้ายที่ Rotting Orchard นำวัตถุทรงพลังที่เรียกว่า Shadowscythe มาส่งให้ข้า" },
        completion = { "73:2141186521:1645197437", "ทำได้ดีมาก! ความช่วยเหลือของเจ้าจะได้รับรางวัลอย่างงาม สนใจรับภารกิจอีกสักงานไหม?" },
        progress = { "26:485812528:1337136595", "เจ้าได้ Shadowscythe มาแล้วหรือ?" },
        required = { [219404] = { "12:942103247:830391780", "เคียวเงา Shadowscythe" } },
        steps = { { "12:942103247:830391780", "เคียวเงา Shadowscythe" } },
    },
    [81737] = { -- Duskwood Mission VIII: Recover Ogre Magi text
        title = { "45:1805334271:1210448347", "ภารกิจ Duskwood VIII: นำตำราจอมเวทโอเกอร์กลับมา" },
        objective = { "129:1775996453:1572263393", "ไปเอา Ogre Magi Text ในเขตฝันร้ายที่รุกล้ำ Duskwood ด้านใน Vul'gol Ogre Mound แล้วกลับไปหา Field Captain Palandar" },
        description = { "274:1955308404:2145275859", "ระหว่างที่พวกปีศาจดึงความสนใจของเราไว้ที่นี่ Emerald Dream กำลังแปดเปื้อนจนกลายเป็นฝันร้าย รีบผ่านประตูสู่ Emerald Dream ที่ Twilight Grove ไปยังเขตฝันร้ายที่ Vul'gol Ogre Mound นำ Ogre Magi Text มาส่งให้ข้า" },
        completion = { "73:2141186521:1645197437", "ทำได้ดีมาก! ความช่วยเหลือของเจ้าจะได้รับรางวัลอย่างงาม สนใจรับภารกิจอีกสักงานไหม?" },
        progress = { "18:1240417715:737713234", "เจ้าได้ตำรามาแล้วหรือ?" },
        required = { [219405] = { "14:49916182:1270479792", "ตำราจอมเวทโอเกอร์" } },
        steps = { { "14:49916182:1270479792", "ตำราจอมเวทโอเกอร์" } },
    },
    [81738] = { -- Duskwood Mission IX: Recover Dragon Egg
        title = { "39:658010292:1230841307", "ภารกิจ Duskwood IX: นำไข่มังกรกลับมา" },
        objective = { "172:615418950:629603915", "ไปเอา Unhatched Green Dragon Egg ใกล้ตอไม้ใหญ่ในทุ่งของ Yorgen Farmstead ภายในเขตฝันร้ายที่รุกล้ำ Duskwood แล้วกลับไปหา Field Captain Palandar" },
        description = { "284:575190839:1192303247", "ระหว่างที่พวกปีศาจดึงความสนใจของเราไว้ที่นี่ Emerald Dream กำลังแปดเปื้อนจนกลายเป็นฝันร้าย รีบผ่านประตูสู่ Emerald Dream ที่ Twilight Grove ไปยังเขตฝันร้ายที่ Yorgen Farmstead นำ Unhatched Green Dragon Egg มาส่งให้ข้า" },
