    [83934] = { -- Show Me the Money!
        title = { "18:1778760533:454660056", "เอาเงินมาให้ข้าดูหน่อย!" },
        objective = { "60:1429221782:741752442", "นำ Tarnished Undermine Real หนึ่งเหรียญไปให้ Pix Xizzix ที่ Booty Bay" },
        description = { "468:140524745:325260779", "หวัดดี! เจ้าดูเป็นนักผจญภัยที่รู้จักหาทางออก ข้าว่าเจ้าคงช่วยข้าได้ เรื่องมีอยู่ว่าข้ากับพี่น้องเดินทางมาจาก Kezan เพื่อเริ่มธุรกิจใหม่ แต่ดันไปเจอโจรสลัดที่ขโมยเงินทุนของเราไปเสียก่อน คนที่ออกทุนให้เราทางบ้านไม่ใช่พวกที่เข้าใจอะไรง่าย ๆ ถ้าเจ้าหาเหรียญพวกนั้นเจอแล้วเอากลับมาให้เรา เราจะตอบแทนให้คุ้มแรง มันไม่ใช่เหรียญทองธรรมดา เห็นเมื่อไรก็รู้เอง" },
        completion = { "130:2013318116:663283755", "เฮ้! เยี่ยมเลย!\nถ้าเจอเหรียญของเราอีกก็มาหาข้านะ เรามีสินค้าดี ๆ ให้เลือกเยอะ ยินดีแลกกับเจ้า!" },
        progress = { "20:1811668327:993523532 R 1:63:63", "มีอะไรมาให้ข้าล่ะ {race}?" },
    },
    [86577] = { -- A Sampling of Putrescence
        title = { "25:1852856866:500354180", "ตัวอย่างเนื้อเน่าเปื่อย" },
        objective = { "6:1273960851:929420321 W1 28:1399491465:1616803954 W2 43:1166684886:1885869480", "นำ Putrescent Bear Organs {world1} ชิ้น และ Putrescent Wolf Organs {world2} ชิ้นไปให้ Kelek Skykeeper" },
        description = { "472:1891175442:233572181", "ความแปดเปื้อนที่ไหลลงมาจาก Hyjal ปนมากับสายน้ำจากภูเขาและซึมเข้าไปในทุกสิ่งในป่านี้ สัตว์ที่ดื่มน้ำนั้นรับความแปดเปื้อนเข้าไปด้วย มันทำให้พวกมันดุร้าย เจ็บป่วย และไม่กลัวอะไรอีก\n\nหากจะหาทางแก้ผลของมัน ข้าต้องเข้าใจก่อนว่ามันทำงานอย่างไร ข้าจึงต้องการตัวอย่างจากสัตว์ที่ได้รับผลกระทบ\n\nตัวอย่างอวัยวะที่เน่าเปื่อยจากหมาป่ากับหมีสักหน่อยก็น่าจะพอ ไม่ต้องรีบ สัตว์พวกนี้พบได้ทั่วไปใน Felwood" },
        required = { [277958] = { "22:1647397021:431151504", "อวัยวะหมีที่เน่าเปื่อย" }, [277959] = { "22:248852582:2073050677", "อวัยวะหมาป่าที่เน่าเปื่อย" } },
        steps = { { "22:1647397021:431151504", "อวัยวะหมีที่เน่าเปื่อย" }, { "22:248852582:2073050677", "อวัยวะหมาป่าที่เน่าเปื่อย" } },
    },
    [86616] = { -- Repurposed Totems
        title = { "17:1704608139:621438113", "นำโทเท็มมาใช้ใหม่" },
        objective = { "6:1273960851:929420321 W1 42:2131320884:1368967355", "นำ Vilebranch Totem {world1} อันกลับไปให้ Maret Firetend" },
        description = { "471:457457243:1417861758", "เรื่องยากอย่างหนึ่งของการสื่อสารกับธาตุในฐานะชาแมน คือมีชาแมนคนอื่นที่มีเป้าหมายขัดกับเรา เหล่าธาตุไม่สนหรอกว่าเราทำไปทำไม พวกเขาเพียงทำตามที่เราขอ!\n\nโทรลล์ที่ Jintha'alor ก็ใช้วิชาชาแมนเหมือนกัน พวกมันคอยขัดขวางและโจมตีเราอยู่เรื่อย\n\nหาโทเท็มของพวก Vilebranch แล้วนำกลับมาให้ข้า ข้าจะได้ลบล้างพลังของมัน พวกมันพกไว้บางอัน ส่วนที่เหลือวางเป็นเครื่องคุ้มกันรอบแท่นบูชา" },
        completion = { "199:654120813:480881474 C 1:46:46", "อา เยี่ยม ข้าจะสลายพลังที่สถิตอยู่ในโทเท็ม Vilebranch พวกนี้ แล้วปล่อยพลังคืนสู่ธรรมชาติ พวกวิญญาณธาตุจะได้เป็นอิสระมาช่วยเรา และอำนาจของพวกโทรลล์ก็จะลดลง\nทำได้ดี {class}" },
        progress = { "128:799630783:936160645", "ยิ่งพวกโทรลล์ Vilebranch รบกวนกระแสพลังธาตุน้อยลง เราก็จะยิ่งติดต่อกับพวกวิญญาณธาตุได้ง่ายขึ้น" },
        required = { [279225] = { "16:521895786:457486855", "โทเทม Vilebranch" } },
        steps = { { "16:521895786:457486855", "โทเทม Vilebranch" } },
    },
