    [81746] = { -- Duskwood Mission XVII: Rescue Alara Grovemender
        title = { "47:164606692:426866376", "ภารกิจ Duskwood XVII: ช่วย Alara Grovemender" },
        objective = { "136:779779044:1084947450", "ช่วย Alara Grovemender ที่คอกม้าใน Yorgen Farmstead ในเขตฝันร้ายที่รุกล้ำ Duskwood แล้วกลับไปหา Field Captain Palandar" },
        description = { "328:823482047:1747468822", "ระหว่างที่พวกปีศาจดึงความสนใจของเราไว้ที่นี่ Emerald Dream กำลังแปดเปื้อนจนกลายเป็นฝันร้าย รีบผ่านประตูสู่ Emerald Dream ที่ Twilight Grove ไปยังเขตฝันร้ายที่ Yorgen Farmstead ตามหา Alara Grovemender ดรูอิดแห่งกรงเล็บที่หลับอยู่ที่นั่น คุ้มกันนางไปยังที่ปลอดภัย แล้วกลับมาหาข้า" },
        completion = { "73:2141186521:1645197437", "ทำได้ดีมาก! ความช่วยเหลือของเจ้าจะได้รับรางวัลอย่างงาม สนใจรับภารกิจอีกสักงานไหม?" },
        steps = { { "24:1556899071:191230622", "ช่วย Alara Grovemender" } },
    },
    [79482] = { -- Stolen Winter Veil Treats
        objective = { "111:1616362219:207606864", "ค้นหาผู้สืบสวนของ Smokywood Pastures ที่หายตัวไปในบริเวณหิมะของ Alterac Mountains" },
        description = { "491:1691809786:45065330", "ฟังนะ... ไม่ได้อยากทำลายมนตร์เสน่ห์ของเทศกาลหรอก แต่สโมกีวูดพาสเจอร์สต้องการความช่วยเหลือ แบบที่นักผจญภัยอย่างพวกเจ้าถนัด\n\nขนมชุดสำคัญที่จะมาสำรองไว้ขายช่วงเทศกาลหายไป และตอนนี้เจ้าหน้าที่สโมกีวูดพาสเจอร์สที่เราส่งออกไปตามหามันก็หายไปด้วย! ได้โปรด รายงานล่าสุดระบุว่าขนมอยู่ที่เทือกเขาอัลเทอแรค คนของเราจึงไปตามหาที่นั่น\n\nไปดูให้ทีว่าทั้งขนมและคนของเรายังอยู่ที่นั่นอย่างปลอดภัยหรือไม่!" },
        title = { "25:1784239235:1438402853", "ขนมวินเทอร์เวลที่ถูกขโมย" },
        completion = { "320:1939609964:721326782", "จะ... เจ้าได้ยินข้าด้วย! ขอบคุณตัวเลขกำไรจริง ๆ!\n\nข้าไม่ใช่... มนุษย์หิมะจริง ๆ ขะ... ข้าชื่อแซ็กส์ ทำงานให้สโมกีวูดพาสเจอร์ส สะ... สาขาไอรอนฟอร์จ ข้าถูกส่งมาตามหาพัสดุที่หายไป แต่โดน... สิ่งมีชีวิตที่ไม่เคยเห็นมาก่อนโจมตี!\n\nหนะ... หนาวเหลือเกิน..." },
    },
    [79492] = { -- Metzen the Reindeer
        objective = { "359:1845077598:1275646107", "ค้นหา Metzen the Reindeer โดยใช้บันทึกที่ได้รับเป็นเบาะแสว่าเขาถูกขังไว้ที่ใด\n\nเมื่อพบ Metzen ต้องมี Pouch of Reindeer Dust อยู่กับตัว เพื่อโรยผงบางส่วนบนเขา ผงนี้น่าจะปลดปล่อย Metzen จากพันธนาการได้\n\nเมื่อปล่อย Metzen แล้ว ให้นำ Pouch of Reindeer Dust กลับไปคืน Wulmort Jinglepocket ใน Ironforge" },
        description = { "490:1058123884:1948197030", "หายนะมาเยือนแล้ว! เม็ตเซน กวางเรนเดียร์ถูกลักพาตัว!\n\nเม็ตเซนเป็นหนึ่งในกวางเรนเดียร์แปดตัวของคุณปู่วินเทอร์ และเป็นทรัพย์สินของสโมกีวูดพาสเจอร์ส เราได้รับจดหมายเรียกค่าไถ่จากกลุ่มที่อ้างว่าจับเม็ตเซนไว้ ไม่ใช่แค่ฉบับเดียว แต่ถึงสองฉบับ! เทศกาลกำลังดำเนินอยู่ เงินของเราก็ตึงมือเต็มที! ได้โปรด หาเม็ตเซนแล้วพากลับมาให้เรา!\n\nอ่านจดหมายเรียกค่าไถ่หาเบาะแส แล้วโรยผงเรนเดียร์นี้บนตัวเขา มันจะปลดปล่อยเขาจากพันธนาการใด ๆ!\n\nได้โปรด รีบหน่อย!" },
        title = { "19:1466468117:1988868869", "เม็ตเซน กวางเรนเดียร์" },
        progress = { "N 207:2008145133:1218415728", "{name}! บันทึกในย่ามที่ข้าให้ไปมีข้อมูลพอจะหาเม็ตเซนพบไหม? ข้าไม่อยากคิดเลยว่าเจ้าพวกอันธพาลใจร้ายจะทำอะไรเขา... แต่เราไม่มีทางจ่ายค่าไถ่มหาศาลขนาดนั้นไหว!" },
        completion = { "267:327060906:1625140896 N 176:2038675749:2082343559", "เจ้าทำสำเร็จ! ไชโย!\n\nเม็ตเซนบินกลับมาที่คอกของคุณปู่วินเทอร์เมื่อครู่นี้เอง ใช่แล้ว เม็ตเซนบินได้จริง ๆ! ผงได้ผลอย่างยอดเยี่ยม ข้ารู้อยู่แล้ว เจ้าช่วยทั้งงานฉลองวินเทอร์เวลและสโมกีวูดพาสเจอร์สให้พ้นหายนะ ขอบคุณ {name}\n\nฟังนะ... เพราะสิ่งที่เจ้าทำ ข้าอยากให้เจ้ารับสิ่งนี้ไว้ มันพิเศษมาก ถ้าเจ้ามีสัตว์ขี่ ข้าว่าเจ้าจะสนุกกับมันแน่ สุขสันต์วินเทอร์เวล!" },
        required = { [21211] = { "22:280601440:828300374", "ถุงผงเรนเดียร์" } },
        steps = { { "39:1482134528:1547138588", "ตามหาและช่วยเม็ตเซน กวางเรนเดียร์" } },
        objectiveLabels = {
            item = { ["Pouch of Reindeer Dust"] = "ถุงผงเรนเดียร์" },
        },
    },
    [79495] = { -- Metzen the Reindeer
        objective = { "358:593256711:1444361398", "ค้นหา Metzen the Reindeer โดยใช้บันทึกที่ได้รับเป็นเบาะแสว่าเขาถูกขังไว้ที่ใด\n\nเมื่อพบ Metzen ต้องมี Pouch of Reindeer Dust อยู่กับตัว เพื่อโรยผงบางส่วนบนเขา ผงนี้น่าจะปลดปล่อย Metzen จากพันธนาการได้\n\nเมื่อปล่อย Metzen แล้ว ให้นำ Pouch of Reindeer Dust กลับไปคืน Kaymard Copperpinch ใน Orgrimmar" },
        description = { "491:1558747823:754100000", "หายนะมาเยือนแล้ว! เม็ตเซน กวางเรนเดียร์ถูกลักพาตัว!\n\nเม็ตเซนเป็นหนึ่งในกวางเรนเดียร์แปดตัวของคุณปู่วินเทอร์ และเป็นทรัพย์สินของสโมกีวูดพาสเจอร์ส เราได้รับจดหมายเรียกค่าไถ่จากกลุ่มที่อ้างว่าจับเม็ตเซนไว้ ไม่ใช่แค่ฉบับเดียว แต่ถึงสองฉบับ! เทศกาลกำลังดำเนินอยู่ เงินของเราก็ตึงมือเต็มที! ได้โปรด หาเม็ตเซนแล้วพากลับมาให้เรา!\n\nอ่านจดหมายเรียกค่าไถ่หาเบาะแส แล้วโรยผงเรนเดียร์นี้บนตัวเขา มันจะปลดปล่อยเขาจากพันธนาการใด ๆ!\n\nได้โปรด รีบหน่อย!" },
        title = { "19:1466468117:1988868869", "เม็ตเซน กวางเรนเดียร์" },
        progress = { "N 225:1937100417:694144245", "{name}! เจ้าพบเขาหรือยัง? บันทึกในย่ามที่ข้าให้ไปมีข้อมูลพอจะหาเม็ตเซนพบไหม? ข้าไม่อยากคิดเลยว่าเจ้าพวกอันธพาลใจร้ายจะทำอะไรเขา... แต่เราไม่มีทางจ่ายค่าไถ่มหาศาลขนาดนั้นไหว!" },
        completion = { "268:1393140085:783644177 N 176:2038675749:2082343559", "เจ้าทำสำเร็จ! ไชโย!\n\nเม็ตเซนบินกลับมาที่คอกของคุณปู่วินเทอร์เมื่อครู่นี้เอง ใช่แล้ว เม็ตเซนบินได้จริง ๆ! ผงได้ผลอย่างยอดเยี่ยม ข้ารู้อยู่แล้ว เจ้าช่วยทั้งงานฉลองวินเทอร์เวลและสโมกีวูดพาสเจอร์สให้พ้นหายนะ ขอบคุณ {name}\n\nฟังนะ... เพราะสิ่งที่เจ้าทำ ข้าอยากให้เจ้ารับสิ่งนี้ไว้ มันพิเศษมาก ถ้าเจ้ามีสัตว์ขี่ ข้าว่าเจ้าจะสนุกกับมันแน่ สุขสันต์วินเทอร์เวล!" },
        required = { [21211] = { "22:280601440:828300374", "ถุงผงเรนเดียร์" } },
        steps = { { "39:1482134528:1547138588", "ตามหาและช่วยเม็ตเซน กวางเรนเดียร์" } },
        objectiveLabels = {
            item = { ["Pouch of Reindeer Dust"] = "ถุงผงเรนเดียร์" },
        },
    },
    [79731] = { -- The Troll Scroll
        title = { "16:1014427741:292470220", "ม้วนจารึกของโทรลล์" },
        objective = { "100:1316249797:807621068", "ไขปริศนาในม้วนจารึก เมื่อไขได้แล้ว Hemet Nesingwary อาจอยากฟังเรื่องนี้" },
        description = { "155:113621467:603935304", "<อักขระโบราณค่อย ๆ เรียงตัวเป็นถ้อยคำต่อหน้าต่อตาเจ้า>\n\nเมื่อสายน้ำจากบ่อน้ำพุศักดิ์สิทธิ์ไหลผ่านน้ำพุแห่ง Zul'Kunda เหล่าเทพจะประทานพร" },
        completion = { "53:2077210870:1043186274 N 101:369125197:52192163", "น้ำพุเวทมนตร์ซ่อนอยู่ในป่าดงดิบงั้นหรือ? เรื่องดีจริง ๆ {name}!\n\nข้าได้ไอเดียเขียนหนังสือเพิ่มอีกบทแล้ว! ไหนดูซิ ข้าเอาต้นฉบับไปไว้ที่ไหนนะ..." },
        objectiveLabels = {
            spell = { ["Solve the riddle"] = "ไขปริศนา" },
        },
    },
    [81570] = { -- Jarl Needs a Blade
        title = { "18:794750849:410351209", "Jarl ต้องการดาบ" },
        objective = { "57:1930373872:1625829395", "นำ Moonsteel Broadsword ไปให้ Jarl ที่ Dustwallow Marsh" },
        description = { "341:1168584477:1287347671", "ข้ามีของต้องตัด จะให้บอกว่าตัดอะไรก็คงไม่ได้ แต่ข้าต้องการดาบ ดาบแบบหนึ่งน่ะ...\n\nบางคนเรียกว่าดาบใหญ่เหล็กจันทรา ส่วนข้าเรียกว่าดาบเหวี่ยง\n\nช่วยข้าหน่อยได้ไหม? ลองหาในเมืองดู หรือไปคุยกับช่างตีเหล็ก ให้เขาตีให้เป็นพิเศษ\n\nแต่อย่าชักช้าล่ะ ของที่ข้าจะตัดเก็บไว้ได้ไม่นาน..." },
        progress = { "19:1919710602:1044239746", "ได้ดาบของข้ามาแล้วหรือ??" },
        completion = { "196:832549912:354045728", "ดาบดีนี่ เหวี่ยงถนัดดี เป็นดาบเหวี่ยงที่ดีจริง ๆ ขอบใจ ขอบใจ ขอบใจ ขอบใจมาก!!! ตอนนี้ข้าอยากลองแล้วสิ...\n\nไว้ทีหลัง ข้าค่อยลองทีหลัง แต่ก็อย่างที่บอก... ขอบใจนะ" },
    },
    [79090] = { -- Repelling Invaders
        title = { "18:844547394:784913677", "ขับไล่ผู้รุกราน" },
        objective = { "108:1414223623:1644247376", "นำตราของ Warsong Outrider ไปให้ Felore Moonray นักบวชหญิงแห่งจันทรา ที่ฐาน Moonwell ใน Ashenvale" },
        description = { "73:1177273488:1876744494", "นักรบ Warsong Outrider บางส่วนพ่ายแพ้ไปแล้ว แต่ศึกยังคงดุเดือด..." },
        progress = { "N 39:822209033:1553478821", "{name} เจ้าได้ข่าวอะไรมาจากแนวหน้าบ้าง?" },
        completion = { "204:219199526:2085471078 N 1:46:46", "ผู้รุกรานฝ่ายฮอร์ดพวกนี้ยังเหยียบย่ำแผ่นดินของเราและเก็บเกี่ยวทรัพยากรจากป่าศักดิ์สิทธิ์ของเรา จงขับไล่พวกมันต่อไป!\n\nบทเพลงศึกศักดิ์สิทธิ์นี้อาจปลุกใจให้เจ้าต่อสู้อย่างมุ่งมั่นยิ่งขึ้น ขอบใจนะ {name}" },
        required = { [211814] = { "21:1451365680:470724382", "ตราของ Warsong Outrider" } },
        objectiveLabels = {
            item = { ["Warsong Outrider Mark"] = "ตราของ Warsong Outrider" },
        },
    },
    [93161] = { -- The Ancient Hilt
        title = { "16:1001242141:899221801", "ด้ามดาบโบราณ" },
        objective = { "94:1074740957:2097349879", "ตามหาคนที่อาจสนใจ Ancient Hilt ที่เจ้าพบในซากปรักหักพัง Ban'aethal" },
        description = { "368:1750646979:1055429201", "ท่ามกลางแสงสลัวจากคบเพลิง เจ้าเห็นประกายโลหะเล็ก ๆ พอมองใกล้ ๆ ก็เห็นชัดว่านี่คือด้ามที่หักออกจากดาบโบราณ\n\nแม้จะไร้ใบดาบ แต่ฝีมือชั้นครูที่ฝากไว้บนด้ามนี้ยังเห็นได้ชัด นี่คือมรดกล้ำค่า และอาจมีคนอยากรู้เรื่องของมันมากขึ้น" },
        progress = { "49:1118843961:1785710858", "เดี๋ยวก่อน... นั่นเจ้าเอาอะไรมา หรือว่าจะเป็นสิ่งนั้น" },
        completion = { "502:1857588667:1354821823", "ของชิ้นนี้ล้ำค่าต่อชนของข้าเกินจะบรรยาย ดาบเล่มนี้ตีขึ้นโดย Luminarian ช่างตีดาบเวทในตำนาน\n\nLuminarian เดินทางมากับพวกเราครั้งที่เราหนีจาก Kalimdor แล้วทำงานต่อในหมู่เกาะ Skyborne นานหลายศตวรรษ อาวุธและชุดเกราะมากมายที่เจ้าเห็นคนใช้บน Zephras ทุกวันนี้ทำตามแบบผลงานชั้นครูของเขา\n\nใบดาบหักและพลังเวทก็หมดไปแล้ว แต่ยังซ่อมได้ เอาไปสิ ลองหาคนที่รู้เรื่องผลงานของ Luminarian มากกว่านี้ บางทีเขาอาจช่วยได้" },
    },
    [97029] = { -- Eluvi'ana
        title = { "9:1146690621:1469060082", "เอลูวีอานา" },
        objective = { "82:683785976:1305681765", "นำ Ancient Skyborne Blade ไปให้ Ealaane Nimbuswalker เพื่อสอบถามเรื่องดาบเล่มนี้" },
        progress = { "475:1869492697:1905746160", "ขอเสียมารยาทหน่อยนะ ดาบที่เจ้าถืออยู่นั่น ข้าขอดูได้ไหม ข้าคิดว่าดาบเล่มนี้เป็นฝีมือของ Luminarian ปรมาจารย์ช่างตีดาบเวทคนเดียวกับที่ทำด้ามดาบโบราณที่เจ้าเอามาให้ข้าคราวก่อน\n\nถ้าข้าจำไม่ผิด ดาบนี้ชื่อ Eluvi'ana เป็นดาบคู่กับ Eluvi'tor ดาบเล่มที่เจ้านำด้ามมาให้ข้า โอกาสที่ของล้ำค่าทั้งสองชิ้นจะมาตกอยู่ในมือเจ้ามีสักเท่าไรกัน คงเป็นโชคชะตาแน่\n\nให้ข้าตรวจดูให้แน่ใจก่อน...", variants = { { "474:2030343111:1522944376", "ขอเสียมารยาทหน่อยนะ ดาบที่เจ้าถืออยู่นั่น ข้าขอดูได้ไหม ข้าคิดว่าดาบเล่มนี้เป็นฝีมือของ Luminarian ปรมาจารย์ช่างตีดาบเวทคนเดียวกับที่ทำด้ามดาบโบราณที่เจ้าเอามาให้ข้าคราวก่อน\n\nถ้าข้าจำไม่ผิด ดาบนี้ชื่อ Eluvi'ana เป็นดาบคู่กับ Eluvi'tor ดาบเล่มที่เจ้านำด้ามมาให้ข้า โอกาสที่ของล้ำค่าทั้งสองชิ้นจะมาตกอยู่ในมือเจ้ามีสักเท่าไรกัน คงเป็นโชคชะตาแน่\n\nให้ข้าตรวจดูให้แน่ใจก่อน..." } } },
        completion = { "338:491411521:1137493664", "ใช่ นี่คือ Eluvi'ana จริง ๆ ดาบนี้หายไปหลายศตวรรษจนใคร ๆ คิดว่าคงสูญไปแล้ว พลังเวทของมันดูจะอ่อนลง แต่คมดาบยังสังหารได้ และจะช่วยเจ้าได้มากในสนามรบ\n\nข้าแนะให้เก็บดาบไว้ให้ดี มันเป็นวัตถุโบราณล้ำค่า ใครจะรู้ สักวันอาจมีทางคืนพลังให้ดาบทั้งคู่ดังเดิม" },
    },
    [60860] = { -- Your Reward has Arrived!
        title = { "24:334356619:47119540", "รางวัลของเจ้ามาถึงแล้ว!" },
        completion = { "10:1724938855:1235015449 C 405:826916665:1745870355", "สวัสดี {class} ข้ารอเจ้าอยู่ คนรู้จักของข้าฝากของมาให้เจ้าตอนที่เจ้าแวะมา เขาบอกว่าเป็นรางวัลจากการซื้อของกับเพื่อนที่เรารู้จักกัน\n\nเจ้าพอจะรู้ไหมว่าเขาหมายถึงอะไร\n\nเอาละ นี่รางวัลของเจ้า อ้อ อีกเรื่องหนึ่ง คนรู้จักของข้า Landro Longshot บอกว่า ถ้าเจ้าทำของชิ้นนี้หาย ไปหาเขาที่ท่าเรือ Booty Bay เพื่อรับชิ้นใหม่ได้" },
    },
    [81765] = { -- Elrick, Paladin of the Silver Hand
        title = { "34:56804768:1139044876", "Elrick พาลาดินแห่ง Silver Hand" },
        objective = { "32:2120715867:804598485", "คุยกับ Elrick เพื่อสอบถามเพิ่มเติม" },
        description = { "139:1013251027:582875176", "<เจ้าไม่รู้จักพาลาดินที่ยืนอยู่ตรงหน้า ลองคุยกับเขาว่ารู้อะไรเกี่ยวกับพ่อค้าและสถานการณ์ตอนนี้บ้าง>" },
        completion = { "25:646185287:785084661 C 63:1115389880:292249456", "ขอบคุณแสงสว่างที่เจ้ามาช่วย {class}! ข้ากลัวแทบแย่ นึกว่าพวกอันธพาลจะฆ่าพวกเราเสียแล้ว!" },
        steps = { { "32:955983448:864869408", "คุยกับ Elrick เพื่อสอบถามเพิ่มเติม" } },
    },
    [81766] = { -- The Bloody Missive
        title = { "18:1954710839:1137309722", "สารเปื้อนเลือด" },
        objective = { "79:1600748849:146273760", "นำสารไปให้ Katherine the Pure ที่ Cathedral of Light ใน Stormwind" },
        description = { "297:1011038147:1471129451", "<เจ้าพบสารฉบับหนึ่งบนร่างของ “พาลาดิน” กระดาษเปื้อนเลือดจนอ่านยาก แต่เจ้ายังพอจับใจความได้\n\nเมื่ออ่านแล้วก็เห็นชัดว่าการออกตามหา “พ่อค้า” ครั้งนี้เป็นกับดักตั้งแต่ต้น เจ้าควรกลับไปหา Katherine เพื่อรับคำสั่งต่อไป>", variants = { { "220:1378190260:282471305", "เจ้าพบจดหมายฉบับหนึ่งบนร่างของ ‘พาลาดิน’ จดหมายเปื้อนเลือดจนอ่านยาก แต่เจ้ายังพออ่านข้อความบนแผ่นหนังออก เจ้าควรอ่านให้ละเอียด แล้วกลับไปหา Katherine เพื่อรับคำสั่งต่อไป" } } },
        progress = { "43:1427418502:1646383385", "ที่แท้ก็เป็นกับดัก... เรื่องนี้น่ากังวลเหลือเกิน" },
        completion = { "35:501646540:1069121003 N 210:189528307:1064298451 N 123:760232259:1789169894", "ช่างเป็นพรที่เจ้าปลอดภัย {name} ไม่ว่า Aeonas จะไปอยู่ที่ไหน ข้าก็หวังว่าเขาจะไม่เจออันตรายแบบเดียวกัน เขาเอาตัวรอดเก่ง ข้าต้องเชื่อว่าเขาจะปลอดภัย ถ้าข้าได้ข่าวจากเขาเมื่อไร ข้าจะติดต่อเจ้าทันที ขอบใจนะ {name}\n\nอ้อ อีกเรื่องหนึ่ง เขาฝากสิ่งนี้ไว้กับข้า ให้มอบแก่เจ้าเมื่อเจ้ากลับมา ใช้มันให้ดี และขอให้แสงสว่างนำทางเจ้า" },
        steps = { { "46:568651659:1241751765", "นำ Bloody Missive ไปให้ Katherine the Pure" } },
    },
    [86746] = { -- The Legashi Threat
        title = { "18:1472627009:1536515915", "ภัยจากเผ่า Legashi" },
        objective = { "5:409775429:850574908 W1 16:1835404440:906765823 W2 21:1862499219:392076067 W3 55:1880614384:1342312707", "กำจัด Legashi Satyr {world1} ตัว, Legashi Rogue {world2} ตัว และ Legashi Hellcaller {world3} ตัวให้ Ekkal ที่ Ruins of Eldarath" },
        description = { "26:327785438:2114185191 N 400:1691936381:583363971", "คนของข้ากำลังลำบาก {name}\n\nเซเทอร์เผ่า Legashi บุกเข้ารังของเรา ทำให้พวก Blackmaw หลายคนถูกพลังชั่วร้ายครอบงำ และตัดขาดเราจากพันธมิตร Timbermaw พวกที่รอดจากการโจมตีต้องเบียดกันอยู่ในค่ายชั่วคราว ที่แย่กว่านั้นคือความแปดเปื้อนของพวกเซเทอร์กำลังลามไปทั่วดินแดน เป็นภัยต่อเผ่าของข้าที่อ่อนแออยู่แล้ว\n\nพวก Legashi ซ่อนอยู่ตามซากปรักหักพังทางตะวันออกเฉียงเหนือ ข้าต้องขอให้เจ้าช่วยปราบพวกมัน" },
        completion = { "237:2107808826:887106341", "ขอบใจ ถึงพวก Legashi จะมีมาก แต่ทุกตัวที่ถูกสังหารช่วยรักษาชีวิตของเฟอร์โบลก์ไว้หนึ่งชีวิต\nถ้าเจ้ายังไหว เรามีงานอีกมากในการต่อสู้กับพวกเซเทอร์ เจ้าจะได้พิสูจน์ด้วยว่าเป็นมิตรกับเฟอร์โบลก์ตนอื่น ๆ ใน Ursolan" },
        objectiveLabels = {
            monster = { ["Legashi Satyr slain"] = "ปราบ เซเทอร์ Legashi", ["Legashi Rogue slain"] = "ปราบ โจร Legashi", ["Legashi Hellcaller slain"] = "ปราบ ผู้อัญเชิญอเวจี Legashi" },
        },
    },
    [88809] = { -- Preserving Eldarath
        title = { "19:335161022:1854732704", "รักษามรดกแห่ง Eldarath" },
        objective = { "8:1089852795:1107240600 W1 149:1071582360:199808657", "เก็บ Eldarath Relic {world1} ชิ้นจาก Spitelash Serpent Guard, Spitelash Siren และ Spitelash Myrmidon พร้อมนำศีรษะของ Lord Sarthiss ไปให้ Commander Truesong ที่ Azshara" },
        description = { "492:1805117819:1620089679", "เมื่อหลายพันปีก่อน Eldarath งดงามน่าตื่นตา เป็นประจักษ์พยานถึงเกียรติยศและอำนาจของชาว Kaldorei เมื่อเทียบกับสมัยนั้น Eldarath วันนี้แทบไม่เหลืออะไรนอกจากกองซาก\n\nแต่สิ่งที่เหลืออยู่ก็ควรเก็บรักษาไว้ อย่างน้อยก็เพื่อรักษาประวัติศาสตร์ของเรา เราต้องขับไล่พวก Spitelash ก่อนที่ Eldarath จะถูกปล้นจนหมด\n\nไปตามถนนทางตะวันออกเฉียงเหนือจะถึงใจกลางซากเมือง ไปที่นั่นแล้วเอาโบราณวัตถุของเรากลับมาให้ได้มากที่สุด และเอาศีรษะของผู้บัญชาการพวกมันมาด้วย" },
        required = { [280610] = { "19:1137572220:1197099230", "ศีรษะของลอร์ด Sarthiss" } },
        steps = { { "14:889412705:587029542", "โบราณวัตถุแห่ง Eldarath" } },
        objectiveLabels = {
            item = { ["Lord Sarthiss' Head"] = "ศีรษะของลอร์ด Sarthiss" },
        },
    },
    [88813] = { -- The Head of the Serpent
        title = { "23:58011304:387157878", "หัวหน้าแห่งฝูงอสรพิษ" },
        objective = { "63:2064358150:2018372988", "นำศีรษะของ Warlord Krellian ไปให้ Commander Truesong ที่ Azshara" },
        description = { "291:2147034459:114495936", "เป้าหมายสุดท้ายของเจ้าคือ Warlord Krellian ผู้นำพวก Spitelash มันหลบอยู่หลังทหารยามใน Temple of Zin-Malor กลางซากเมือง Eldarath\n\nตัดหัว Krellian เสีย แล้วสมุนของมันจะเลื้อยกลับทะเลด้วยความกลัว เมื่อนั้น Azshara จะกลับมาเป็นของชาว Kaldorei อีกครั้ง" },
        required = { [238057] = { "15:693171843:1492113957", "ศีรษะของ Krellian" } },
        objectiveLabels = {
            item = { ["Krellian's Head"] = "ศีรษะของ Krellian" },
        },
    },
    [88884] = { -- Highborne Tablets
        title = { "17:440602804:221495554", "แผ่นจารึกของ Highborne" },
        objective = { "115:496752924:136555287", "หาแผ่นจารึก Highborne ทั้งสามแผ่นตามซากปรักหักพังใน Southridge Beach แล้วนำไปให้ Saria Fairmoon ที่ Azshara" },
        description = { "420:664103138:56477715", "ลงไปทางใต้จากที่นี่ตามแนวชายหาด จะพบแผ่นจารึกอักษร Highborne อยู่หลายแผ่น บันทึกว่าพวก Highborne ศึกษากฎและพลังของเวทอาร์เคนอย่างไร\n\nแผ่นจารึกอยู่ในอาคารคล้ายเจดีย์ที่พวกนากาคอยเฝ้า ข้าจึงไม่กล้าไปเอามาเอง\n\nโชคดีที่ข้าได้ผู้ช่วยคนใหม่แล้ว!\n\nว่าอย่างไรล่ะ คิดว่าจะช่วยข้าตามหาความรู้ต่อได้ไหม?" },
        required = { [238244] = { "18:1100306714:693890806", "แผ่นจารึกแห่งการสร้าง" }, [238245] = { "22:1662917746:314648286", "แผ่นจารึกแห่งการควบคุม" }, [238246] = { "15:1870589301:1749699563", "แผ่นจารึกแห่งพลัง" } },
        objectiveLabels = {
            item = { ["Tablet of Creation"] = "แผ่นจารึกแห่งการสร้าง", ["Tablet of Manipulation"] = "แผ่นจารึกแห่งการควบคุม", ["Tablet of Power"] = "แผ่นจารึกแห่งพลัง" },
        },
    },
    [89013] = { -- Gettin' Buzzed
        title = { "14:823108291:934431193", "จิบให้มึน" },
        objective = { "7:451016854:1830523975 W1 54:970047831:156785754", "ใช้ Berdun's Pellet Gun เก็บ Wild Honey {world1} หน่วยจาก Wasp Nest" },
        description = { "419:260661575:779759578", "ที่พักคนเดินทางจะเป็นที่พักได้อย่างไรถ้าไม่มีอะไรให้ดื่ม?\n\nข้าหมักเหล้าน้ำผึ้งได้รสดีทีเดียว แต่ก็แก่เกินกว่าจะไปหาน้ำผึ้งเองแล้ว มีรังตัวต่ออยู่บนต้นไม้ทางเหนือของค่าย Haldaar และทางตะวันตกของ Valormok ถ้าเห็นฮิปโปกริฟฟ์ก็แปลว่ามาถูกที่แล้ว\n\nเจ้าพวกนี้ดุเอาเรื่อง แต่น้ำผึ้งของมันอร่อยอย่างที่เจ้าไม่เคยชิมมาก่อน ข้าจะให้ยืมปืนยิงเม็ดไปยิงรังให้ตกลงมา ไม่อย่างนั้นเจ้าเอื้อมไม่ถึงหรอก" },
        completion = { "66:1267625355:326106685", "ฮ่า ๆ! คืนนี้ได้ดื่มของดีแน่ แก้วแรกข้าเลี้ยง!" },
        progress = { "96:1289912076:847276483", "ขอให้โชคดีตอนเก็บน้ำผึ้งนะ ถ้าพวกตัวต่อเริ่มรุมล้อม ข้าแนะนำให้กระโดดลงน้ำ!" },
        required = { [238503] = { "10:1233606029:1257675740", "น้ำผึ้งป่า" } },
        objectiveLabels = {
            item = { ["Wild Honey"] = "น้ำผึ้งป่า" },
        },
    },
    [89053] = { -- Your Final Reward
        title = { "17:1947977227:1051978742", "รางวัลสุดท้ายของเจ้า" },
        objective = { "31:390950861:1439920595", "ไปดูสิ่งที่ Saria อยากให้เจ้าดู" },
        description = { "55:883426916:754301496 N 251:1842215283:2041067044", "ข้ารู้ว่าตอนแรกเจ้าถูกส่งมาสอดแนม {name} แต่เจ้าช่วยงานโบราณคดีไว้มากทีเดียว\n\nหลังจากทุ่มแรงไปตั้งมาก เจ้าคงอยากรู้ว่างานศึกษาของข้าจะให้ผลอย่างไร\n\nก่อนเจ้ากลับค่าย ข้ามีบางอย่างอยากให้ดู จะช่วยตามข้ามาหน่อยได้ไหม?" },
        completion = { "70:652215035:295970266", "<วัตถุโบราณที่เจ้ารวบรวมให้ Saria อยู่ในกระเป๋าตรงหน้าเจ้า>" },
        steps = { { "30:1706138579:912607024", "ดูสิ่งที่ Saria อยากให้เจ้าดู" } },
    },
    [81762] = { -- Some Good News
        title = { "14:1636408277:2001338094", "ข่าวดี" },
        objective = { "69:1893756149:1694793589", "ไปคุยกับ Katherine the Pure ที่ Cathedral of Light ใน Stormwind" },
        description = { "11:927657569:725753248 N 313:1347986394:1136369015", "สวัสดี {name} ข้ามีข่าวดี ข้าติดต่อสหายของข้าได้แล้ว อีกไม่นานข้าจะออกไปพบเขา นอกจากนี้ยังมีลูกแก้วอีกลูกปรากฏขึ้นใน Kalimdor ข้าไปสองที่พร้อมกันไม่ได้ ถ้าเจ้ายินดี ข้าอยากให้เจ้าไปสืบเรื่องลูกแก้วลูกใหม่นี้แทนข้า ไปคุยกับ Katherine เพื่อรับคำสั่งต่อไป" },
        completion = { "23:140679440:2097538806 N 26:1688246304:1913143738", "ดีใจที่ได้พบเจ้าอีก {name} ข้าจะเล่าให้ฟังว่าเกิดอะไรขึ้นบ้าง" },
    },
    [84158] = { -- An Earnest Proposition
        title = { "22:1183475074:147978204", "ข้อเสนอที่จริงใจ" },
        objective = { "119:1765397344:504366285", "รวบรวม Silithus Venom Sample 15 ชิ้นและเงิน 20 เหรียญทอง แล้วนำไปให้ Mokvar ใน Orgrimmar พร้อม Devout Bracers หนึ่งชุด" },
        description = { "6:1136836709:1914036474 C 423:287029186:1488951061", "สวัสดี {class}! ดูจากท่าทางแล้ว เจ้าคงพบเห็นและผ่านเรื่องราวในโลกนี้มามาก แต่ข้ากล้าพนันว่าเจ้ายังไม่เคยเห็นเกราะแบบนี้\n\nช่วยข้าสักเรื่องสิ แล้วข้าจะยอมเอาเกราะชิ้นนี้แลกกับปลอกแขนธรรมดาของเจ้า\n\nข้าต้องการตัวอย่างพิษปริมาณมากจากแมงมุมและแมงป่องที่อาศัยอยู่ใน Silithus นำมาให้ข้าพร้อมเหรียญทองสักหน่อย แล้วเราค่อยแลกของกัน" },
        completion = { "208:344574223:2051793325", "อา ใช่ Mux คงจะดีใจมากเมื่อเห็นนี่\nปลอกแขนคู่นั้นเป็นส่วนหนึ่งของชุดเกราะทั้งชุด ถ้าเจ้าสนใจช่วยข้าต่อ ข้าก็ยินดีพิจารณายกชิ้นที่เหลือให้" },
        progress = { "39:292799259:1437363122 N 1:63:63", "ได้ของที่ข้าต้องการมาแล้วหรือยัง {name}?" },
    },
    [81764] = { -- The Mysterious Merchant
        title = { "23:645039369:1661459214", "พ่อค้าลึกลับ" },
        objective = { "53:471372063:372464503", "เดินทางไป Theramore แล้วตามหาพ่อค้าลึกลับ" },
        description = { "16:1944969959:1107291362 N 465:1619678418:1220438086", "ดีใจที่ได้พบเจ้าอีกครั้ง {name} Shaw กับสายลับของเขาแจ้งข่าวมาว่า พ่อค้าลึกลับคนหนึ่งเพิ่งมาถึง Kalimdor และกำลังหาทางขายวัตถุโบราณอันตรายหลายชิ้น เราเชื่อว่าหนึ่งในนั้นคือ Echoing Orb ตอนนี้เขาพักอยู่ที่ Theramore Inn ใน Dustwallow Marsh รีบไปเอาลูกแก้วกลับมา และอย่าบอกเรื่องนี้กับใคร เราให้เจ้าไปคนเดียวเพื่อไม่ให้ศัตรูจับตา\n\nขอให้เจ้าปลอดภัย และขอให้แสงสว่างนำทางเจ้า" },
        completion = { "111:2113656556:1372993374", "อ้อ เจ้ามาถึงแล้ว! Katherine ส่งข้ามาช่วยเจ้าในภารกิจนี้ แต่เราต้องรีบแล้ว เป้าหมายของเราหนีไปได้!" },
    },
    [84318] = { -- Oi!
        title = { "3:5244889:1369507", "เฮ้!" },
        objective = { "49:1610455709:886223543", "ตามหาค้อนที่หายไปของ Orthas ใน Corrin's Crossing" },
        description = { "4:1347936505:179405449 C 498:1528845892:631061798", "เฮ้! {class}! ใช่ เจ้านั่นแหละ! เจ้าช่วยข้าไว้เยอะที่ทุบร่างเนื้อโทรม ๆ ที่ข้าสิงมาหลายปีจนเละ แต่ข้ายังไม่รู้สึกอยากไปไหนนัก คงเพราะข้ายังมี ‘ธุระค้างคา’ ให้สะสางก่อนจะไปต่อ เอาล่ะ เจ้าทึ่ม ข้าเกณฑ์เจ้ามาช่วยแล้ว!\n\nไปเอาค้อนของข้ามาที น่าจะอยู่แถว Corrin's Crossing เห็นแล้วไม่น่าพลาดหรอก\n\nเฮ้ เอานี่ไปด้วย ฟันทองซี่โปรดของข้าเอง เจออาวุธของข้าแล้วก็ถูฟันซี่นี้ที" },
        progress = { "12:1629785660:601170998", "อยากได้อะไร?" },
        completion = { "137:160613373:2120531922", "เออ ขอบใจเจ้ามาก! เรื่องนี้เรียบร้อยแล้ว ทีนี้มาช่วยกันจัดการส่วนที่เหลือให้เข้าที่ เจ้าจะได้ส่งข้าไปต่อเสียที!" },
    },
    [84330] = { -- A Wee Bit O' Necromancy
        title = { "23:1845689111:2028274385", "วิชาเรียกคนตายนิดหน่อย" },
        objective = { "157:186376980:1393038713", "เอา Necrotic Runestone จาก Maleki the Pallid ใน Stratholme แล้วไปหา Rotting Dwarf Corpse ใกล้ Undercroft ทางตะวันตกเฉียงใต้ของ Eastern Plaguelands" },
        description = { "487:742069339:398213275", "ฟังนะ เราต้องหาศพคนแคระที่เหมาะ ๆ สักร่าง แล้วทำพิธีนิดหน่อยเพื่อยึดวิญญาณข้าไว้ ทีนี้ถึงจะส่งข้าไปต่อได้! เรื่องธรรมดาทั้งนั้นแหละ! เราต้องใช้ Necrotic Runestone จากพวกหมอผีเรียกคนตายด้วย ที่ Stratholme มีอยู่คนหนึ่งชื่อ Maleki the Pallid คงหวังให้เขายอมยกหินให้ดี ๆ ไม่ได้หรอก แต่เรื่องนั้นมีวิธีจัดการ!\n\nเอาหินมาให้ข้า แล้วไปที่ Undercroft ที่นั่นมีศพที่ใช้ได้อยู่ร่างหนึ่ง!" },
        completion = { "125:2120928990:1332455750", "<เจ้าก้มลงแตะศพ ขนที่ต้นคอก็ลุกชัน... เจ้ามีลางสังหรณ์ไม่ดีเกี่ยวกับเรื่องนี้>" },
        progress = { "3:3050122:795478", "…" },
    },
    [91906] = { -- A Sealed Crate
        title = { "14:1980566332:1496368079", "ลังปิดผนึก" },
        progress = { "90:572835964:31380712", "มีของมาส่งอีกลัง! ยอดเยี่ยม วางไว้ข้างกองนั้น แล้วเราค่อยมาคุยเรื่องค่าตอบแทน" },
        completion = { "30:1573550112:1663048353 N 201:1091463753:2101955530", "ขอบคุณที่ช่วยงาน {name} ช่วงหลังมานี้โจรกับขโมยดักปล้นตามเส้นทางการค้ากันมากขึ้น หากเจอลังอื่น ๆ ตกอยู่ โปรดนำมาที่นี่ แล้วเราจะจัดการที่เหลือเอง\n\nนี่ค่าตอบแทนของท่าน", variants = { { "30:1573550112:1663048353 N 200:643955126:1360953982", "ขอบคุณที่ช่วยงาน {name} ช่วงหลังมานี้โจรกับขโมยดักปล้นตามเส้นทางการค้ากันมากขึ้น หากเจอลังอื่น ๆ ตกอยู่ โปรดนำมาที่นี่ แล้วเราจะจัดการที่เหลือเอง\n\nนี่ค่าตอบแทนของท่าน" } } },
        required = { [248772] = { "19:1477002019:677821451", "ลังปิดผนึกระดับผู้เชี่ยวชาญ" } },
        objectiveLabels = {
            item = { ["Sealed Expert Crate"] = "ลังปิดผนึกระดับผู้เชี่ยวชาญ" },
        },
    },
    [86611] = { -- Stag Lord's Bauble
        title = { "18:1594580124:1566664499", "เครื่องประดับของราชากวาง" },
        description = { "288:502657265:1119489072", "<แอ่งน้ำเมือกเหม็นเน่ากัดเซาะรูปสลักกวางจนสึกกร่อน ไม่มีใครรู้ว่ามันมาอยู่ก้นทะเลสาบได้อย่างไร\n\nผลึกเม็ดหนึ่งที่ฝังอยู่ในจี้ห้อยคอของรูปสลักเปล่งแสงสีเขียวชวนขนลุก น่าจะนำไปให้คนที่อาจรู้ประวัติของรูปสลักนี้ดู>" },
        objective = { "82:736632516:2014427522", "นำเครื่องประดับของราชากวาง (Stag Lord's Bauble) ไปให้คนที่อาจรู้เรื่องของมันใน Talonbranch Glade" },
    },
    [86612] = { -- Stag Lord's Bauble
        title = { "18:1594580124:1566664499", "เครื่องประดับของราชากวาง" },
        description = { "288:502657265:1119489072", "<แอ่งน้ำเมือกเหม็นเน่ากัดเซาะรูปสลักกวางจนสึกกร่อน ไม่มีใครรู้ว่ามันมาอยู่ก้นทะเลสาบได้อย่างไร\n\nผลึกเม็ดหนึ่งที่ฝังอยู่ในจี้ห้อยคอของรูปสลักเปล่งแสงสีเขียวชวนขนลุก น่าจะนำไปให้คนที่อาจรู้ประวัติของรูปสลักนี้ดู>" },
        objective = { "80:1431625026:572097506", "นำเครื่องประดับของราชากวาง (Stag Lord's Bauble) ไปให้คนที่อาจรู้เรื่องของมันใน Bloodvenom Post" },
    },
    [7487] = { -- Attunement to the Core
        title = { "22:211700460:2017269968", "ปรับพลังสู่ Core" },
        objective = { "180:845374165:1541910096", "ไปยังประตูเข้า Molten Core ใน Blackrock Depths แล้วนำ Core Fragment คืนมา เมื่อได้แล้วให้กลับไปหา Lothos Riftwaker ที่ Blackrock Mountain" },
        description = { "46:579083181:600024226 R 454:1714797191:1565644299", "รอยแยกปั่นป่วน ฉีกออก และยุบตัวรอบเรา ชาว{race} ห่างจากที่ข้ายืนไม่ถึงสองก้าว มีรอยฉีกนำผ่านส่วนลึกของ Blackrock Mountain เข้าสู่ปากเหว Firelord\n\nแปลกใจหรือ? น่าสงสาร... เผ่าผู้มีอายุขัยไม่อาจเข้าใจสิ่งที่มองไม่เห็น สัมผัสไม่ได้ หรือไม่รู้สึก\n\nข้ารับรองว่าประตูอยู่ตรงนั้นและเข้าไปได้\n\nสนใจแล้วหรือ? ปรับพลังไม่ยาก เข้า Blackrock Depths แล้วนำ Core Fragment กลับมา ข้าจะปรับแก่นพลังเจ้าให้เชื่อมกับประตู" },
    },
    [87295] = { -- Deflective Surface
        title = { "18:1852056862:2011568951", "เกล็ดสะท้อนการโจมตี" },
        objective = { "52:661611836:1620296302", "นำเกล็ด Redstone Basilisk 10 ชิ้นไปให้ Bernie Heisten", amount = { "6:1273960851:929420321 W1 44:568875671:46467087", "นำเกล็ด Redstone Basilisk {world1} ชิ้นไปให้ Bernie Heisten" } },
        description = { "464:456816348:2078656204", "ระหว่างเดินทางมาที่ Nethergarde Keep เจ้าอาจเห็นบาซิลิสก์ Redstone เดินเพ่นพ่านในแดนร้างข้างนอก พวกมันอึดและปรับตัวเข้ากับ Blasted Lands ได้ดี จุดเด่นของมันคือเกล็ดแข็งที่สะท้อนความร้อน กันทรายกับลม แถมยังเบี่ยงคมอาวุธได้ด้วย!\n\nเกล็ดพวกนี้เหมาะเอามาทำโล่มาก ถ้าเจ้าหามาให้ข้าสักกอง ข้าจะตอบแทนอย่างงาม เอาเฉพาะเกล็ดสภาพดีมานะ!" },
    },
    [87451] = { -- Memories of Rockard
        title = { "19:1088211265:9890420", "ความทรงจำแห่ง Rockard" },
        objective = { "93:302384929:551183677", "นำเครื่องประดับหินแกะสลัก (Carved Stone Trinket) ไปให้ Dispatch Commander Ruag ที่ Stonard ใน Swamp of Sorrows" },
        description = { "279:260814325:1576634177", "เครื่องประดับที่โอเกอร์พกไว้นี้ดูเหมือนหินแกะสลักชิ้นเล็กเป็นรูปครอบครัวออร์ค มันอาจเป็นของที่ระลึกจากออร์คที่เคยอาศัยอยู่ที่นี่ สมัยที่ยังเป็นเมือง Rockard ก่อนโอเกอร์จะบุกเข้ามา\n\nมันคงมีคุณค่าทางใจหรือทางจิตวิญญาณต่อผู้รอดชีวิตที่ Stonard" },
    },
    [87492] = { -- Uncanny Crystal
        title = { "15:1830894775:1896667194", "ผลึกประหลาด" },
        objective = { "54:526491074:573533467", "นำ Damaged Blue Crystal 1 ชิ้นกลับไปให้ Torwa Pathfinder", amount = { "6:1273960851:929420321 W1 47:1336372349:1572180950", "นำ Damaged Blue Crystal {world1} ชิ้นกลับไปให้ Torwa Pathfinder" } },
        description = { "413:1030574548:509424278", "เจ้าอาจเคยเห็นกลุ่มผลึกประหลาดที่ผุดขึ้นทั่วแอ่งนี้ ข้าไม่ใช่คนงานเหมืองหรอก แต่ผลึกพวกนี้ดูไม่เข้ากับชั้นดินแถวนี้เลย\n\nตอนออกหาของป่า ข้าเหมือนจะเห็นผลึกที่เสียหายอยู่ไม่ไกลจากที่นี่ ข้าสงสัยว่ามันซ่อนเบาะแสเรื่องที่มาของกลุ่มผลึกประหลาดพวกนี้ไว้หรือเปล่า ถ้าเจ้าเห็นมัน ข้าอยากได้ตัวอย่างสักชิ้นมาศึกษา" },
        completion = { "408:1189953276:1914884349", "ไหน ขอดูหน่อยสิ!\nมีรอยร้าวเล็ก ๆ และมีผงร่อนออกมานิดหน่อย แต่ที่น่าสนใจกว่าคือริ้วพวกนี้ ผลึกนี้ไม่เหมือนหินธรรมชาติใต้ชั้นดินแถวนี้เลย การก่อตัวแบบนี้... มีอะไรผิดธรรมชาติ ข้าไม่รู้ว่าอะไร แต่เหมือนมีบางอย่างทำให้ผลึกพวกนี้งอกขึ้นทั่วทั้งแถบ\nน่ากังวลจริง ๆ แต่มันหมายความว่าอะไรกัน?" },
        progress = { "21:1881324534:757024925", "ออกไปข้างนอกก็ระวังตัวด้วย!" },
    },
    [87494] = { -- Microcrystal Contamination
        title = { "26:829989910:3914932", "เกล็ดปนผลึกจิ๋ว" },
        objective = { "51:1279656155:1565669611", "นำเกล็ดฝังผลึก (Crystal Infused Scale) ไปให้ Torwa Pathfinder" },
        description = { "180:1750363931:1341235174", "เกล็ดนี้สะท้อนแสงและเหลือบสีมากกว่าเกล็ดอื่นเล็กน้อย ราวกับมีเศษผลึกเม็ดเล็ก ๆ ฝังอยู่\n\nTorwa Pathfinder อาจรู้ว่าควรทำอย่างไรกับมัน" },
        completion = { "448:1617180250:1189895304", "เกล็ดที่เจ้าพบนี่แปลกจริง ๆ!\nดูเหมือนเจ้าสัตว์ตัวนี้จะกินฝุ่นผลึกเข้าไปมากจนผงเริ่มแทรกซึมเข้าไปในชั้นเกล็ด มันคงไปหากินใกล้ผลึกที่แตก ฝุ่นเลยปนอยู่ในพืชที่มันกินเข้าไป\nข้าสงสัยว่าถ้ากินเข้าไปมากกว่านี้ คงเกิดความเปลี่ยนแปลงรุนแรงจนเห็นได้ชัด เจ้าตัวนี้โชคดีที่กินเข้าไปไม่มากเกินไป\nข้าจะเก็บชิ้นนี้ไว้ในของสะสม" },
        progress = { "50:1153698192:1383632495", "Un'Goro คือธรรมชาติที่ดิบเถื่อนและไร้การควบคุมที่สุด" },
    },
    [88807] = { -- Slay the Spitelash
        title = { "18:1475709155:750777791", "กำจัดพวก Spitelash" },
        objective = { "86:1151186372:854223195", "สังหาร Spitelash Warrior 8 ตัว และ Spitelash Screamer 8 ตัว ให้ Commander Truesong ใน Azshara" },
        description = { "476:1165418073:1836991737", "Azshara อาจดูงดงาม แต่ที่นี่คือดินแดนต้องคำสาป ใต้ผืนน้ำลึกมีสิ่งน่าสะพรึงกลัวซ่อนอยู่ รอวันโผล่ขึ้นมาฉีกโลกให้เป็นเสี่ยง ๆ\n\nตอนนี้เราทำได้เพียงต่อกรกับพวกที่ขึ้นมาแล้ว\n\nพวกนากา Spitelash ยึดซากเมือง Eldarath ทางตะวันออกเฉียงเหนืออยู่ พวกที่อยู่ในซากเมืองตั้งรับกันแน่นหนา เราจึงต้องทยอยกำจัดพวกที่อ่อนแอกว่าตามรอบนอกก่อน\n\nเห็นแล้วใช่ไหมว่าที่นี่ต้องการคนช่วยสู้อีกสักคน ถ้าเจ้าพร้อมรับงานนี้" },
        completion = { "26:1546186372:1036361930 C 33:1187853373:1148698013", "เริ่มต้นได้ดีมาก {class} ทีนี้เราจะบุกเข้าไปในซากเมืองจริง ๆ เสียที" },
    },
    [88812] = { -- Reclaiming Ravencrest
        title = { "21:1233677849:878885393", "ทวงคืน Ravencrest" },
        objective = { "154:1036805539:443182682", "สังหาร Spitelash Battlemaster 5 ตัว และ Spitelash Enchantress 5 ตัว พร้อมสลายพลังของ Naga Power Stone 3 ก้อนใกล้ Ravencrest Monument ให้ Commander Truesong ใน Azshara" },
        description = { "505:397105827:369356826", "ข้ากลัวว่าอีกไม่นานตระกูล Ravencrest ของชาวคัลโดเรจะถูกลืมเลือน อนุสรณ์ที่กำลังผุพังแห่งนี้เป็นหลักฐานชิ้นเดียวที่เหลืออยู่ว่าพวกเขาเคยอยู่ที่นี่\n\nอนุสรณ์ตั้งอยู่บนยอดหน้าผาตรงปลายสุดของคาบสมุทรทางใต้ พวกนักเวท Spitelash ที่นั่นมีศิลาที่ใช้รวบรวมและส่งผ่านพลังเวท เอาเครื่องรางนี้ไปสลายพลังศิลาเสีย เวทของพวก Spitelash จะอ่อนกำลังลง และเราจะได้เปรียบในการขับไล่พวกมัน\n\nระหว่างนั้นอย่าลืมจัดการพวกนากาสักหน่อยด้วย" },
    },
    [88821] = { -- Making Contact
        title = { "14:479554699:35015483", "ติดต่อคนบนชายฝั่ง" },
        objective = { "58:131880521:620324988", "ตามหาหญิงชาวคัลโดเรที่มีคนพบเห็นครั้งสุดท้ายบน Shattered Strand" },
        description = { "492:1074893793:1325751456", "ตอนที่หน่วยยามของเราคนหนึ่งออกสำรวจตามหน้าผาของ Shattered Strand เขาเห็นหญิงชาวคัลโดเรอยู่บนชายหาด\n\nเห็นได้ชัดว่านางไม่ได้มากับคณะสำรวจของเรา และดูไม่เหมือนนักสู้ ข้าจึงสงสัยว่านางมาทำอะไรในที่อันตรายแบบนี้\n\nถ้าทำได้ ลองไปคุยกับนางดู ข้าอยากรู้ว่านางมาที่นี่ด้วยเหตุใด และเป้าหมายของเราพอจะตรงกันบ้างไหม\n\nมีคนเห็นนางครั้งสุดท้ายที่ชายฝั่งตะวันออก ทางเหนือของ Bay of Storms" },
        completion = { "60:86284494:145823263", "ที่นี่มีค่ายไนต์เอลฟ์กลุ่มอื่นด้วยหรือ? ข้าไม่เคยรู้มาก่อนเลย" },
    },
    [88857] = { -- Saving a Sentinel
        title = { "17:494170564:2016589089", "ช่วยหน่วยยามเฝ้าระวัง" },
        objective = { "105:916251692:792775648", "ช่วย Keldara Sunblade หนีออกจาก Haldarr Encampment แล้วไปคุยกับ Commander Truesong ที่ Talrendis Point" },
        description = { "47:900264987:1121731305 C 253:162784868:1858918339", "<หน่วยยามกระซิบเสียงเบา>\n\nฟังนะ {class} ก่อนที่พวกมันจะได้ยินเรา ข้าเป็นหน่วยยามจาก Talrendis Point พวกซาเทอร์ที่นี่คิดว่าข้าบาดเจ็บ แต่ข้าแกล้งทำเป็นเจ็บเพื่อรอจังหวะที่พวกมันเผลอ จะได้หนีออกไป\n\nบางทีการมาของเจ้าอาจเป็นโอกาสนั้น\n\nช่วยพาข้าออกไปทีได้ไหม?" },
        completion = { "74:1659719483:1950681437", "Keldara ยังมีชีวิตอยู่สินะ? โล่งใจจริง ๆ ข้าจะตั้งตารอนางกลับมา" },
    },
    [88917] = { -- Slithering Looters
        title = { "18:1118459915:282978845", "โจรปล้นซากเมือง" },
        objective = { "105:1903302592:385718201", "หา Staff of Archmage Selwyn ในซากเมือง Eldarath แล้วนำไปให้ Saria Fairmoon ใน Azshara" },
        description = { "447:1291660657:1206400951 R 45:1501233907:1832823712", "ข้ามาที่นี่เพื่อตามหาโบราณวัตถุของพวกไฮบอร์น จะเรียกข้าว่าเป็นนักโบราณคดีประเภทหนึ่งก็ได้\n\nซากเมือง Eldarath ทางตะวันตกมีของพวกนั้นอยู่มาก แต่ตอนนี้พวกนากากำลังปล้นซากเมืองอยู่\n\nนากาที่ชื่อ Lady Sesspira เป็นหัวหน้าพวกปล้น นางคงเก็บของล้ำค่าที่สุดไว้เองแน่\n\nถ้าที่ข้าศึกษามาถูกต้อง นางอาจมีคทาของมหาจอมเวท Selwyn จอมเวทไฮบอร์นผู้ล่วงลับอยู่ในมือ\n\nข้าต้องขอให้เจ้าช่วยเอาคทานั้นมา ชาว{race} นักวิชาการอย่างข้าไม่ถนัดการต่อสู้" },
        progress = { "84:1995609302:822087367", "Sesspira ไอ้ตัวละโมบนั่นรู้บ้างไหมว่าวัตถุโบราณที่มันกักตุนไว้มีค่าจนประเมินไม่ได้?" },
        completion = { "123:1625219761:358211583 C 38:327994701:1958630792", "คทา! แถมยังอยู่ในสภาพสมบูรณ์ด้วย เยี่ยมไปเลย!\n\nข้าชักชอบที่เราแบ่งกันใช้สมองกับใช้แรงแบบนี้นะ {class} เจ้าจะช่วยข้าต่ออีกสักหน่อยได้ไหม?" },
    },
    [89001] = { -- Home on the Range
        title = { "17:864255260:1741979195", "บ้านกลางทุ่ง" },
        objective = { "73:1347810874:676992566", "นำหนัง Mosshoof 5 ผืนไปให้ Berdun Cliffbrew ที่ Talrendis Point ใน Azshara" },
        description = { "408:658739846:1469191141", "สวัสดี นักเดินทาง!\n\nถ้าเจ้ากำลังหาที่พัก ก็มาโรงพักแรมของ Berdun นี่แหละ! ตอนนี้เต็นท์ทรุดโทรมนิดหน่อย แต่ซ่อมได้\n\nเอาอย่างนี้ ถ้าเจ้าหาของที่ข้าต้องใช้ซ่อมเต็นท์มาให้ ข้าจะให้เจ้าพักฟรี ว่าไงล่ะ?\n\nข้าต้องใช้หนัง Mosshoof สักหน่อย ตัวที่ล่าง่ายที่สุดอยู่ทางเหนือของที่นี่ แต่หนังจาก Mosshoof ตัวไหนก็ใช้ได้" },
        completion = { "93:368943572:1689872467", "ทำได้ดีมาก สหาย! ข้าจะซ่อมที่นี่เดี๋ยวนี้เลย นั่งเหยียดขาแล้วพักให้สบายเถอะ!" },
        progress = { "21:918458969:900221548", "ได้ของใช้มาแล้วหรือยัง?" },
    },
    [89037] = { -- Murloc Thieves
        title = { "14:1665079905:46366139", "เมอร์ล็อกหัวขโมย" },
        objective = { "107:1614634264:857234673", "เอา Memory Crystal จาก Razorgill ใกล้ Tower of Eldara แล้วนำไปให้ Saria Fairmoon ใน Azshara" },
        description = { "346:49729772:1119528535 R 140:1011362694:1438658442", "ข้าพบ Tower of Eldara บนชายหาดของคาบสมุทรทางเหนือ ทางตะวันออกของที่นี่ ตอนสำรวจพื้นที่ ข้าเห็นเมอร์ล็อกตัวใหญ่สีส้มถือกระบองหนามและพกผลึกเรืองแสงประหลาด ดูจากที่ที่พบแล้ว ผลึกนี้น่าจะเป็นชนิดที่พวกไฮบอร์นใช้บันทึกประวัติศาสตร์และความทรงจำ\n\nเราต้องเอาผลึกนั้นกลับมา ชาว{race} ใครจะรู้ว่ามันเก็บความลับอะไรไว้บ้าง?\n\nทางไปหอคอยที่ดีที่สุดคือเลียบหน้าผา ทางขึ้นที่ใกล้ที่สุดอยู่ทางตะวันตกของที่นี่เอง" },
        completion = { "139:642715344:172729148 C 1:46:46", "น่าทึ่ง ผลึกยังสมบูรณ์ทั้งชิ้น เสียงเซ็งแซ่ที่ออกมาจากมันชวนฉงน แถมยังชวนให้หลงใหลเสียด้วย\nเจ้าช่วยรักษาหลักฐานสำคัญทางประวัติศาสตร์ชิ้นหนึ่งไว้แล้ว {class}" },
        progress = { "183:662709080:1631933540", "ผลึกชิ้นนั้นอาจเป็นกุญแจสู่พลังเวทอาร์เคนที่ประเมินค่าไม่ได้ คิดดูสิ เมอร์ล็อกกระจอก ๆ ตัวหนึ่งดันบังเอิญเจอมัน ในสายตามันคงเป็นแค่ของกระจุกกระจิกวาว ๆ ชิ้นหนึ่ง" },
    },
    [89038] = { -- A Monumental Task
        title = { "17:874604244:45829800", "ภารกิจที่อนุสรณ์สถาน" },
        objective = { "119:242269628:978099055", "ค้นหา Mark of the Queen ในซาก Ravencrest Monument แล้วนำไปให้ Saria Fairmoon ใน Azshara" },
        description = { "501:1233570539:814995190", "เล่ากันว่าครั้งหนึ่งราชินี Azshara เคยประทานของขวัญแก่ชาวคัลโดเรแห่งตระกูล Ravencrest เป็นตราที่งดงามและเปี่ยมพลังเวท พระนางประทานตรานี้เพื่อตอบแทนความจงรักภักดีอันมั่นคงของตระกูล Ravencrest\n\nมีคนเห็นตราครั้งสุดท้ายใกล้ Ravencrest Monument บนยอดหน้าผาของคาบสมุทรทางใต้ ถ้าได้วัตถุโบราณชิ้นนั้นมา ก็จะเป็นการค้นพบครั้งสำคัญที่สุดในชีวิต\n\nแน่นอนว่าพวก Spitelash ยังเดินกันให้ขวักไขว่ตามซากอนุสรณ์ แต่ป่านนี้เจ้าคงรับมือพวกมันได้คล่องแล้ว" },
        completion = { "157:1631316895:1778065455", "ตราของราชินี Azshara เอง... ข้าแทบไม่อยากเชื่อเลย! เจ้าทำได้ดีมาก\nงานที่ต้องใช้ผู้ช่วยจบลงแล้ว แต่ข้ายังมีของชิ้นสุดท้ายให้เจ้า" },
        progress = { "26:1969129943:1436233360", "หาตรานั่นเจอบ้างหรือยัง?" },
    },
    [89228] = { -- Winter Frontier Fishery
        title = { "23:1604172562:2071423432", "ตกปลาชายแดนในฤดูหนาว" },
        objective = { "76:1738732214:1322044709", "ตกหมึกฤดูหนาว (Winter Squid) 10 ตัวให้ Berdun Cliffbrew ที่ Talrendis Point ใน Azshara" },
        description = { "335:1551891654:2057491744", "ที่พักแรมดี ๆ ก็ต้องมีอะไรให้กิน\n\nตอนนี้เป็นฤดูของหมึก ตกได้ตามชายฝั่ง Azshara นี่แหละ ข้าเองตกปลาไม่เก่งหรอก แต่ฝีมือทำอาหารของข้าเด็ดนะ!\n\nว่าไง อยากกินอาหารทะเลไหม?\n\nถ้าเจ้าไม่ถนัดตกปลา ลองผูกมิตรกับนักตกปลาสักคนสิ หรือจะจ่ายเงินซื้อมาจากพวกเขาก็ได้" },
    },
    [89470] = { -- Ill Tidings
        title = { "11:765516183:141488409", "ข่าวร้าย" },
        objective = { "69:750972174:607642750", "นำ Saria's Knapsack กลับไปให้ Commander Truesong ที่ Talrendis Point" },
        description = { "150:1884724708:1243611564", "<เมื่อเจตนาที่แท้จริงของ Saria ถูกเปิดเผย และเจ้ามีกระเป๋าที่เต็มไปด้วยโบราณวัตถุทรงพลังอยู่ในมือ บางทีตอนนี้อาจถึงเวลานำรายงานของนางไปให้ Commander Truesong>" },
    },
}

addon.npcs = {
    [197] = {
        name = "Marshal McBride",
        line = { "114:1975041302:1067093623", "เฮ้ พลเมือง! เจ้าดูแข็งแรงดีนี่ ทหารยามแถวนี้มีกันไม่ค่อยพอ ข้าอยากได้เจ้ามาช่วยสักหน่อย..." },
    },
    [658] = {
        name = "Sten Stoutarm",
        line = { "185:1307141536:1572180002", "โอ้ ดูแข็งแรงใช่เล่นนี่! บางทีเจ้าอาจช่วยข้าสักเรื่องสองเรื่องได้ แถวนี้มีแต่พวกเด็กฝึกหน้าใหม่ แถมพวกเขาก็มีเรื่องอื่นให้พะวงอยู่แล้ว" },
    },
    [2079] = {
        name = "Conservator Ilthalaine",
        line = { "63:781658065:771141267", "อา ไม่ว่าจะได้ชื่นชมกี่ครั้ง ความงามของ Shadowglen ก็ยังทำให้ข้าสุขใจเสมอ!" },
    },
    [3143] = {
        name = "Gornek",
        line = { "175:1229999869:68774788", "หุบเขาแห่งบททดสอบจะฝึกแม้กระทั่งผู้อ่อนแอที่สุดให้เป็นนักรบที่คู่ควรกับ Horde ส่วนผู้ที่ผ่านบททดสอบไปไม่ได้ ก็ต้องถูกทิ้งไว้ให้แดดทะเลทรายแผดเผา" },
    },
    [823] = {
        name = "Deputy Willem",
        line = { "13:1911146197:485773127 C 211:986039538:776846133", "สวัสดี {class} ปกติข้าคงกำลังออกเดินตรวจตราดูแลชาว Stormwind แต่ตอนนี้ทหารยามหลายคนไปรบต่างแดน ข้าเลยได้รับแต่งตั้งให้มาอยู่ตรงนี้ คอยตั้งค่าหัว ทั้งที่ใจอยากออกลาดตระเวนมากกว่า..." },
    },
    [3691] = {
        name = "Raene Wolfrunner",
        lines = {
            { "141:2012934149:2119254792", "ข้ารู้จักป่าเหล่านี้ราวกับเป็นส่วนหนึ่งของตัวเอง... แต่จงรู้ว่ายังมีสิ่งให้เรียนรู้อีกมาก และอันตรายอีกมากที่ซ่อนอยู่" },
            { "73:2138753566:1677256641 N 1:46:46", "เจ้าทำภารกิจของ Teronis สำเร็จแล้ว ข้าซาบซึ้งในทุกสิ่งที่เจ้าทำ {name}" },
            { "157:1137406378:379598167 N 80:72199486:2097908250", "ข้าคาดแล้วว่าเจ้าจะกลับมา ก่อนหน้านี้ส่ง Korra ออกไป นางพบคทาของ Dartol ถูกทิ้งอยู่ในป่า\n\nเราลำบากแค่ไหนกว่าจะได้มันมา {name} ต่อไปช่วยดูแลให้ดี อย่าสะเพร่าเช่นนี้อีก" },
            { "141:1235260351:98953684", "ข้ารู้จักป่าแถบนี้ราวกับเป็นส่วนหนึ่งของตัวข้า... แต่รู้ไว้เถอะว่ายังมีอีกมากให้เรียนรู้จากป่าเหล่านี้ และยังมีอันตรายซ่อนอยู่อีกไม่น้อย" },
        },
    },
    [3692] = {
        name = "Volcor",
        lines = {
            { "198:1308737461:684599122 C 47:2036773395:1121310902", "<Volcor ไม่มองเจ้าเลยขณะเข้าใกล้ ดูเหมือนกำลังตั้งใจประคองผ้าพันแผลไม่ให้หลุด ผ่านไปครู่หนึ่งเขาเงยหน้าขึ้นอย่างตกใจเล็กน้อย>\n\nอ้อ โทษที {class} ตอนนี้ไม่สะดวก หวังว่าเจ้าจะเข้าใจ" },
            { "24:461785591:650472571 N 321:1757630892:863323520", "เท่าที่ข้าเห็น {name} เรามีสองทางให้ออกจากถ้ำ\n\nจะลอบออกไป โดยข้าใช้เสื้อคลุมที่เจ้าให้ ส่วนเจ้าต้องหาวิธีเอง หรืออีกทางที่อาจยากกว่าเพราะข้าบาดเจ็บ คือสู้ฝ่ากันออกไปโดยคอยระวังหลังให้กัน\n\nให้เจ้าตัดสิน เพราะรู้ความสามารถของตัวเองดีกว่าข้า" },
        },
    },
    [3693] = {
        name = "Terenthis",
        lines = {
            { "N 285:1252706753:675517110", "{name} ข้ามาสืบว่า Fel Moss ส่งผลลุกลามทั่ว Darkshore เพียงใด ความแปดเปื้อนของ Teldrassil และดินแดนรอบข้างทำให้ดรูอิดแห่ง Cenarion Circle กับไนต์เอลฟ์ทุกคนเป็นห่วงมาก\n\nเป้าหมายข้าคือหาว่าทำไมจึงเกิดขึ้น และยุติมัน" },
        },
    },
    [3701] = {
        name = "Tharnariun Treetender",
        lines = {
            { "10:1724938855:1235015449 R 29:1389420132:1804999687", "สวัสดี ชาว{race} ข้าคือ Tharnariun Treetender" },
        },
    },
    [3838] = {
        name = "Vesprystus",
        lines = {
            { "117:2109913779:769992309", "เพื่อรักษาการติดต่อกับแผ่นดินใหญ่ เรามีฮิปโปกริฟฟ์บินระหว่าง Rut'theran Village กับ Darkshore ตลอดเวลา" },
        },
    },
    [3885] = {
        name = "Sentinel Velene Starstrike",
        lines = {
            { "57:1157935226:1919156601 N 237:1439273494:441602380", "เห็นวิญญาณธาตุน้ำที่แปดเปื้อนในทะเลสาบของเราหรือยัง {name}? น่าเศร้านัก แต่ข้าไม่รู้ว่ามันมาจากไหน\n\nเคยได้ยินคนพูดถึงชื่อเจ้า บางทีเจ้าอาจช่วยแก้ปัญหานี้ได้\n\nอย่างแรกต้องรู้ว่าใครควบคุมวิญญาณธาตุเหล่านี้" },
        },
    },
    [4200] = {
        name = "Laird",
        lines = {
            { "105:1218622827:2065464114", "แม้ชายฝั่ง Darkshore อันตรายกว่าที่ Teldrassil ชาวประมงหลายคนก็ยังหากำไรได้ที่นี่" },
        },
    },
    [6301] = {
        name = "Gorbold Steelhand",
        lines = {
            { { "130:1181354604:427637681", "130:1837956883:469413447" }, "สวัสดี สหาย ถ้ากำลังหาสินค้าราคาดีที่สุดนอก Ironforge ก็มาถูกที่แล้ว" },
            { "129:337509965:1604573580", "สวัสดี เจ้าหนุ่ม ถ้ามองหาของราคาดีที่สุดนอก Ironforge ละก็ เจ้ามาถูกที่แล้ว" },
        },
    },
    [10118] = {
        name = "Nessa Shadowsong",
        lines = {
            { "140:1433395170:919162891", "ปลานอกชายฝั่ง Teldrassil ตัวใหญ่และแข็งแรงมาก มีข่าวลือว่าเป็นเพราะต้นไม้โลกต้นใหม่ของเราโตอย่างรวดเร็ว" },
        },
    },
    [10216] = {
        name = "Gubber Blump",
        lines = {
            { "27:1743531632:1416933990", "สวัสดี ข้าชื่อ Gubber Blump" },
            { "43:925686134:262640608", "...ทอดกระทะ ทอดน้ำมันท่วม แล้วก็ผัด..." },
        },
    },
    [10219] = {
        name = "Gwennyth Bly'Leggonde",
        lines = {
            { "25:1553417442:1653822644 C 77:1392736230:906615244", "ขอ Elune เดินเคียงข้างเจ้า {class} Temple of the Moon มาช่วยชาว Auberdine ที่กำลังเดือดร้อน" },
        },
    },
    [2930] = {
        name = "Sentinel Glynda Nal'Shea",
        lines = {
            { "81:2029619568:700862228", "ความแปดเปื้อนแทรกสู่พงไพรแห่งธรรมชาติ เราต้องปกป้องป่าไม่ว่าจะต้องแลกด้วยสิ่งใด" },
        },
    },
    [3649] = {
        name = "Thundris Windweaver",
        lines = {
            { "181:1034878414:929305728", "พลังมืดรุกชายแดน ความชั่วร้ายโบราณผุดกลับมา และภัยใหม่ก็ก่อตัวเพื่อทำลายสมดุลอันเปราะบางของผืนดิน ในยามมืดมนเช่นนี้ เราทุกคนต้องระวังตัว" },
        },
    },
    [3845] = {
        name = "Shindrell Swiftfire",
        lines = {
            { "83:1980020328:1510563375", "ชาวเอลฟ์มีประวัติศาสตร์ยาวนาน หวังว่าอดีตจะไม่ย้อนกลับมาหลอกหลอนเรา" },
        },
    },
    [4077] = {
        name = "Gaxim Rustfizzle",
        lines = {
            { "245:1162770242:1656484786", "ถ้าได้ส่วนผสมที่เหมาะ เราจะสร้างระเบิดที่ทั้งทำลายกิจการ Venture Co. และเบี่ยงเบนความสนใจได้\n\nรู้ว่าเจ้าทึ่งแล้ว แต่ยังมีดีกว่านี้อีก... เดี๋ยวข้าจะเล่าให้ฟัง" },
        },
    },
    [3847] = {
        name = "Orendil Broadleaf",
        lines = {
            { "177:150028406:530432475", "Ashenvale เป็นป่าเขียวชอุ่มเปี่ยมชีวิต การเดินตามเส้นทางลับเพื่อหาสมุนไพรช่างรื่นรมย์ แต่ต้องระวัง ป่านี้ยังมีอันตราย" },
        },
    },
    [2786] = {
        name = "Gerrig Bonegrip",
        lines = {
            { "39:309432949:1854270171 C 96:2071457385:560397759", "ยินดีต้อนรับสู่ร้านอักษรรูนและคำสาปของ Bonegrip {class} มองได้ แต่ห้ามแตะ\n\nความรู้บางอย่างที่นี่ไม่ได้มีไว้สำหรับ... ผู้ที่ยังไม่ได้รับการถ่ายทอด" },
        },
    },
    [3663] = {
        name = "Delgren the Purifier",
        lines = {
            { { "88:1676158194:1720066524", "89:317063246:1597834255" }, "สวัสดี สหาย! บางทีเจ้าช่วยจัดการเรื่องที่ค้างอยู่ให้ข้าได้" },
            { "10:10763625:219111161 C 1:46:46", "สวัสดี {class}" },
        },
    },
    [3666] = {
        name = "Wizbang Cranktoggle",
        lines = {
            { "208:1722078211:294997450", "อืม... เสียบสายตรงนี้จะจ่ายพลังให้เฟืองฟิซเซิลแทน แต่ไฮโดรแฟลงจ์ก็ต้องมีแหล่งพลังงานอื่น... บางทีข้าอาจ... อ้อ สวัสดี! เฮ้ อยากช่วยทดสอบสิ่งประดิษฐ์ใหม่ไหม?" },
        },
    },
    [3848] = {
        name = "Kayneth Stillwind",
        lines = {
            { "102:1319199764:1494479870", "สมดุลธรรมชาติละเอียดอ่อนและสั่นคลอนได้ง่าย เจ้ากล้าพอทำให้สิ่งต่าง ๆ กลับเข้าที่หรือไม่?" },
        },
    },
    [3616] = {
        name = "Onu",
        lines = {
            { "56:1806382503:2041244601", "สายลมกระซิบแก่ผู้ที่ตั้งใจฟัง...\n\nเจ้าได้ยินหรือไม่?" },
            { "105:262888420:1551202871 R 1:46:46", "ได้สิ ที่ผ่านมาเจ้าก็พิสูจน์แล้วว่า... ไหวพริบดีทีเดียว\n\nข้าหวังว่าเจ้าจะพบสิ่งที่ตามหา เจ้า{race}วัยเยาว์" },
        },
    },
    [198] = {
        name = "Khelden Bremen",
        lines = {
            { "10:1401179418:1568553899 C 101:1577892042:528431778", "ยินดีที่ได้พบ {class} ข้าขอแนะนำไว้ว่า เมื่อเดินทางไปทั่วโลก จงระวังเวทมนตร์ เพราะมันจะเผาผู้ที่ไม่ผ่านการฝึก" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "81:2005475919:562754788", "สวัสดี จอมเวท ให้ข้าเพิ่มพูนความรู้เรื่องโลกแห่งเวทมนตร์ให้เจ้าไหม?" },
            { "10:1401179418:1568553899 C 101:1445025405:959899133", "ยินดีที่ได้พบ {class} ข้าขอแนะนำว่าเมื่อเจ้าออกเดินทาง จงระวังเวทมนตร์ไว้ เพราะมันจะแผดเผาคนที่ยังฝึกมาไม่พอ" },
            { "10:1724938855:1235015449 C 67:1895677853:1104183491", "สวัสดี {class} ให้ข้าช่วยให้เจ้าเข้าใจโลกแห่งเวทมนตร์มากขึ้นไหม?" },
        },
    },
    [277] = {
        name = "Roberto Pupellyverbos",
        lines = {
            { "80:823615287:721350807", "แวะดูสินค้าของข้าเฉย ๆ หรือวันนี้มีอะไรที่อยากให้ช่วยหาเป็นพิเศษ?" },
            { "95:1006349034:431655755", "ของราคาดีที่สุดใน Stormwind สหายเอ๋ย หาไม่ได้ถูกกว่านี้แล้ว ข้าช่วยอะไรเจ้าได้บ้าง?" },
        },
    },
    [295] = {
        name = "Innkeeper Farley",
        lines = {
            { "57:973460575:1995442186", "ยินดีต้อนรับโรงเตี๊ยมข้า นักเดินทางเหนื่อยล้า มีอะไรให้ช่วย?" },
            { "374:918067400:24586973", "ทำอะไรที่โรงเตี๊ยมได้หรือ?\n\nพักที่นี่สบายมาก จึงได้สถานะพักเต็มที่เร็วกว่ากลางป่า เมื่อพักเต็มที่จะเรียนรู้จากประสบการณ์มากขึ้น\n\nยังคุยเจ้าของโรงเตี๊ยมเพื่อรับ Hearthstone แล้วใช้กลับโรงเตี๊ยมนั้นอย่างรวดเร็วภายหลังได้" },
            { "143:297692507:1364973514", "ไม่ใช่ข้า แต่มีคนอื่นอีกมากที่กำลังมองหาความรัก เจ้าควรซื้อสื่อรักของข้า ใช้โคโลญหรือน้ำหอม แล้วนำไปแจกให้พวกเขา!" },
            { "271:1028484567:72113628", "ถ้าเจ้าใช้โคโลญหรือน้ำหอม ก็จะมองออกว่าใครกำลังมีใจ คนเหล่านั้นจะรับสื่อรัก... และมอบของขวัญตอบแทน\n\nแต่จำไว้ ถ้าจะมอบสื่อรักให้ใคร เจ้าต้องมีกลิ่นที่ถูกใจ! ผู้ชายชอบกลิ่นน้ำหอม ส่วนผู้หญิงชอบโคโลญ" },
            { "240:271214309:1448407633", "สื่อรักคือข้อความเล็ก ๆ แสดงความรู้สึกที่เจ้ามอบให้ชาวเมืองผู้กำลังมีใจได้ พวกเขาจะตอบแทนด้วยของขวัญแห่งความชื่นชม\n\nหรือหากมีใครชื่นชมเจ้าอยู่แล้ว อย่างน้อยก็จะได้รับของขวัญแห่งมิตรภาพ" },
            { "284:254841895:287193708", "เมื่อเจ้ามอบสื่อรักให้ชาวเมือง จะได้รับของขวัญหลายแบบตอบแทน บางชิ้นเจ้าคงอยากเก็บไว้ใช้ ส่วนชิ้นอื่นรวมเป็นชุดแล้วนำไปมอบให้วีรบุรุษคนโปรดของเจ้าได้! ไปหา Kwee Q. Peddlefeet เพื่อส่งของเหล่านั้น\n\nKwee อยู่ใกล้ Bolvar, Magni หรือ Tyrande" },
            { "286:1185563448:313386146", "เมื่อเจ้ามอบสื่อรักให้ชาวเมือง จะได้รับของขวัญหลายแบบตอบแทน บางชิ้นเจ้าคงอยากเก็บไว้ใช้ ส่วนชิ้นอื่นรวมเป็นชุดแล้วนำไปมอบให้วีรบุรุษคนโปรดของเจ้าได้! ไปหา Kwee Q. Peddlefeet เพื่อส่งของเหล่านั้น\n\nKwee อยู่ใกล้ Cairne, Sylvanas และ Thrall" },
        },
    },
    [328] = {
        name = "Zaldimar Wefhellt",
        lines = {
            { "10:1401179418:1568553899 C 101:1577892042:528431778", "ยินดีที่ได้พบ {class} ข้าขอแนะนำไว้ว่า เมื่อเดินทางไปทั่วโลก จงระวังเวทมนตร์ เพราะมันจะเผาผู้ที่ไม่ผ่านการฝึก" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "81:2005475919:562754788", "สวัสดี จอมเวท ให้ข้าเพิ่มพูนความรู้เรื่องโลกแห่งเวทมนตร์ให้เจ้าไหม?" },
            { "118:1402784989:1521109254", "ยินดีที่ได้พบ พาลาดิน ข้าขอแนะนำว่า เมื่อออกเดินทางไปทั่วโลก จงระวังเวทมนตร์ เพราะมันจะเผาผู้ที่ไม่ได้ฝึกฝน" },
            { "10:1401179418:1568553899 C 101:1445025405:959899133", "ยินดีที่ได้พบ {class} ข้าขอแนะนำว่าเมื่อเจ้าออกเดินทาง จงระวังเวทมนตร์ไว้ เพราะมันจะแผดเผาคนที่ยังฝึกมาไม่พอ" },
        },
    },
    [331] = {
        name = "Maginor Dumas",
        lines = {
            { "10:1401179418:1568553899 C 101:1577892042:528431778", "ยินดีที่ได้พบ {class} ข้าขอแนะนำไว้ว่า เมื่อเดินทางไปทั่วโลก จงระวังเวทมนตร์ เพราะมันจะเผาผู้ที่ไม่ผ่านการฝึก" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "81:2005475919:562754788", "สวัสดี จอมเวท ให้ข้าเพิ่มพูนความรู้เรื่องโลกแห่งเวทมนตร์ให้เจ้าไหม?" },
            { "10:1401179418:1568553899 C 101:1445025405:959899133", "ยินดีที่ได้พบ {class} ข้าขอแนะนำไว้ว่า เมื่อเดินทางไปทั่วโลก จงระวังเวทมนตร์ เพราะมันจะเผาผู้ที่ไม่ผ่านการฝึก" },
        },
    },
    [375] = {
        name = "Priestess Anetta",
        lines = {
            { "31:1231134424:2037752348 N 48:834079703:188127399", "ข้าเชื่อว่าแสงสว่างสถิตกับเจ้า {name} มีอะไรให้ข้าช่วยไหม?" },
            { "36:2046074590:925364487 C 50:520265182:163201457", "อย่าหันหลังให้แสงสว่าง {class} สักวันมันอาจเป็นสิ่งเดียวที่ช่วยชีวิตเจ้า" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [376] = {
        name = "High Priestess Laurena",
        lines = {
            { "31:1231134424:2037752348 N 48:834079703:188127399", "ข้าเชื่อว่าแสงสว่างสถิตกับเจ้า {name} มีอะไรให้ข้าช่วยไหม?" },
            { "36:2046074590:925364487 C 50:520265182:163201457", "อย่าหันหลังให้แสงสว่าง {class} สักวันมันอาจเป็นสิ่งเดียวที่ช่วยชีวิตเจ้า" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [377] = {
        name = "Priestess Josetta",
        lines = {
            { "31:1231134424:2037752348 N 48:834079703:188127399", "ข้าเชื่อว่าแสงสว่างสถิตกับเจ้า {name} มีอะไรให้ข้าช่วยไหม?" },
            { "36:2046074590:925364487 C 50:520265182:163201457", "อย่าหันหลังให้แสงสว่าง {class} สักวันมันอาจเป็นสิ่งเดียวที่ช่วยชีวิตเจ้า" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [459] = {
        name = "Drusilla La Salle",
        lines = {
            { "131:292506403:398178378", "อาร์เคนทำให้แปดเปื้อนเฉพาะผู้อ่อนแอ แม้ไม่ตามวิถีวอร์ล็อก ก็ควรจำ" },
            { "35:102842694:2146291588 C 64:242280109:1353430229", "ความมืดไม่โอบรับเจ้า {class} หยุดพล่ามแล้วไปให้พ้นสายตา! ไป!" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [460] = {
        name = "Alamar Grimm",
        lines = {
            { "102:1842107517:1165454838", "อาร์เคนทำให้แปดเปื้อนเฉพาะผู้อ่อนแอ ฝึกต่อให้ทัน มิฉะนั้นอาจพบชะตาคล้ายกัน" },
            { "121:1415751390:1730471397", "เกรงว่าระดับความมืดเจ้าไม่พอให้ข้าคุยต่อ ไปได้แล้ว" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [461] = {
        name = "Demisette Cloyce",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "102:1842107517:1165454838", "อาร์เคนทำให้แปดเปื้อนเฉพาะผู้อ่อนแอ ฝึกต่อให้ทัน มิฉะนั้นอาจพบชะตาคล้ายกัน" },
            { "35:102842694:2146291588 C 64:242280109:1353430229", "ความมืดไม่โอบรับเจ้า {class} หยุดพล่ามแล้วไปให้พ้นสายตา! ไป!" },
            { "255:967301392:2039283435", "นอกจากฝึกสอนแล้ว หากเจ้าต้องการ ข้ายังมีอำนาจลบความรู้เรื่องพรสวรรค์ออกจากจิตใจเจ้าได้ แต่จงรู้ไว้ว่า ยิ่งผ่านกระบวนการนี้บ่อยเท่าไร ก็ยิ่งทำได้ยากขึ้น และค่าใช้จ่ายจึงสูงขึ้นตามไปด้วย" },
        },
    },
    [483] = {
        name = "Elaine Trias",
        lines = {
            { "80:823615287:721350807", "แวะดูสินค้าของข้าเฉย ๆ หรือวันนี้มีอะไรที่อยากให้ช่วยหาเป็นพิเศษ?" },
            { "95:1006349034:431655755", "ของราคาดีที่สุดใน Stormwind สหายเอ๋ย หาไม่ได้ถูกกว่านี้แล้ว ข้าช่วยอะไรเจ้าได้บ้าง?" },
        },
    },
    [543] = {
        name = "Nalesette Wildbringer",
        lines = {
            { "61:250644815:1162909176", "เจ้ามาฝึกเพื่อจะนำไปสอนสัตว์เลี้ยงของเจ้าหรือ?" },
            { "46:1291027720:1211870466", "อา สหาย ข้าช่วยได้เฉพาะพรานและสัตว์เลี้ยงของพวกเขา" },
        },
    },
    [837] = {
        name = "Branstock Khalder",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "23:1576200947:2014128481 C 1:46:46", "ขอแสงสว่างคุ้มครอง {class}" },
            { "30:1779911861:267861627 N 43:517129309:1063884753", "หวังว่าแสงสว่างอยู่กับเจ้า {name} วันนี้ให้ช่วยอะไรไหม?" },
            { "22:1579844308:969115409 C 1:46:46", "จงรับใช้แสงให้ดี {class}" },
        },
    },
    [895] = {
        name = "Thorgas Grimson",
        lines = {
            { "20:1806402586:1551596819", "ให้ข้าช่วยอะไร?" },
            { "53:1945481929:1069095775 C 9:839995460:592385449", "ข้าฝึกให้ไม่ได้ ควรหาครูฝึก{class}" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [906] = {
        name = "Maximillian Crowe",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "102:1842107517:1165454838", "อาร์เคนทำให้แปดเปื้อนเฉพาะผู้อ่อนแอ ฝึกต่อให้ทัน มิฉะนั้นอาจพบชะตาคล้ายกัน" },
            { "35:102842694:2146291588 C 64:242280109:1353430229", "ความมืดไม่โอบรับเจ้า {class} หยุดพล่ามแล้วไปให้พ้นสายตา! ไป!" },
        },
    },
    [911] = {
        name = "Llane Beshere",
        lines = {
            { "110:968941883:497880469", "Stormwind คือเสาหลักของมนุษยชาติ ค้ำจุนด้วยพลังใจและคมดาบอันแข็งแกร่ง" },
            { "120:501679215:1919710548", "แค่ท่ายืนข้าก็ดูออกว่าเจ้าไม่ใช่นักรบ\n\nทำไมไม่ไปทำอะไรปลอดภัย อย่างอ่านหนังสือเสียล่ะ" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [912] = {
        name = "Thran Khorman",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "80:1032263186:1890174864", "สงครามใหญ่อาจจบแล้วในตอนนี้ แต่เรายังต้องฝึกฝีมือให้เฉียบคม!" },
            { { "79:873017008:421501123 C 31:2134870025:914883839", "79:873017008:421501123 C 32:537594318:1592024306" }, "เจ้าไม่ใช่นักรบ... ตารางฝึกข้าเจ้าคงทนไม่ได้แม้แต่วันเดียว!\n\n{class}ที่คิดว่าตัวเองเป็นนักรบ ฮ่า!" },
        },
    },
    [913] = {
        name = "Lyria Du Lac",
        lines = {
            { "110:968941883:497880469", "Stormwind คือเสาหลักของมนุษยชาติ ค้ำจุนด้วยพลังใจและคมดาบอันแข็งแกร่ง" },
            { "120:501679215:1919710548", "แค่ท่ายืนข้าก็ดูออกว่าเจ้าไม่ใช่นักรบ\n\nทำไมไม่ไปทำอะไรปลอดภัย อย่างอ่านหนังสือเสียล่ะ" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [914] = {
        name = "Ander Germaine",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "110:968941883:497880469", "Stormwind คือเสาหลักของมนุษยชาติ ค้ำจุนด้วยพลังใจและคมดาบอันแข็งแกร่ง" },
            { "120:501679215:1919710548", "แค่ท่ายืนข้าก็ดูออกว่าเจ้าไม่ใช่นักรบ\n\nทำไมไม่ไปทำอะไรปลอดภัย อย่างอ่านหนังสือเสียล่ะ" },
        },
    },
    [918] = {
        name = "Osborne the Night Man",
        lines = {
            { "90:748691251:391531667", "เจ้าดูเป็นคนที่ข้าควรระวังถุงเงินเมื่ออยู่ใกล้ มีอะไรให้ช่วยหรือ?" },
            { "75:2042450107:1761906752 C 25:1654355136:1742979888", "ข้าไม่คิดว่าเจ้าอยากเรียนสิ่งที่ข้าสอนได้ คงต้องหาครูฝึก{class}ช่วย" },
            { "25:1587218171:1392793728 N 18:670906540:2083204284", "มีของให้เจ้า {name} ดูสำคัญ" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [925] = {
        name = "Brother Sammuel",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "35:87739973:1151531961", "ขอแสงสว่างคุ้มครองเจ้าในวันนี้" },
        },
    },
    [926] = {
        name = "Bromos Grummner",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "22:1990256640:1107448062 C 20:931052451:317831623", "แสงอยู่กับเจ้า {class} ข้าช่วยอะไรได้?" },
            { "107:1108573917:1037022718", "แม้ไม่ตามวิถีแสงอย่างอัศวิน Silver Hand ก็ขอความช่วยเหลือจากเราได้เสมอ" },
        },
    },
    [927] = {
        name = "Brother Wilhelm",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "35:87739973:1151531961", "ขอแสงสว่างคุ้มครองเจ้าในวันนี้" },
        },
    },
    [928] = {
        name = "Lord Grayson Shadowbreaker",
        lines = {
            { "35:87739973:1151531961", "ขอแสงสว่างคุ้มครองเจ้าในวันนี้" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [931] = {
        name = "Ariena Stormfeather",
        lines = {
            { "31:808893464:1178195280", "เจ้าต้องการบินไปที่ใด?" },
        },
    },
    [944] = {
        name = "Marryk Nurribit",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "55:683661098:38972060", "สวัสดี ข้าเป็นครูฝึกจอมเวทโนม และเจ้าก็เป็นจอมเวท" },
            { "10:1401179418:1568553899 C 88:801536239:851538785", "ยินดีที่พบ {class} อยากได้คำแนะนำไหม? จงเป็นมิตรกับจอมเวท! พวกเรามีลูกเล่นซ่อนไว้อยู่เหมือนกันนะ..." },
        },
    },
    [985] = {
        name = "Malosh",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "74:915526637:1144923117", "มาฝึกฝนหรือ? หรือแค่มาเสียเวลานักรบ" },
            { "24:1952719577:438144002 C 44:1306153434:959587588", "ข้าไม่ฝึกคนอย่างเจ้า {class} ไปหาครูของตัวเองก่อนทำข้าโกรธ" },
        },
    },
    [986] = {
        name = "Haromm",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "59:498915724:1123836113", "เหล่าวิญญาณนำเจ้ามาหาข้า ให้ข้ารับใช้อะไร?" },
            { "28:1102434926:2067309120", "ขอวิญญาณทั้งหลายอยู่กับเจ้า" },
        },
    },
    [987] = {
        name = "Ogromm",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "5:1202113668:87170919", "อะไร?" },
            { "20:1893906897:1282479184", "อย่ามาทำให้ข้าเสียเวลา" },
        },
    },
    [988] = {
        name = "Kartosh",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "81:818972234:1432082645 N 1:46:46", "รู้พอเป็นอันตราย แต่ข้าว่ายังต้องฝึก {name}" },
            { "67:271584239:662855302 C 1:46:46", "เจตนายังไม่แข็งพอใช้กำลังที่เราควบคุม {class}" },
        },
    },
    [1226] = {
        name = "Maxan Anvol",
        lines = {
            { "23:1576200947:2014128481 C 1:46:46", "ขอแสงสว่างคุ้มครอง {class}" },
            { "30:1779911861:267861627 N 43:517129309:1063884753", "หวังว่าแสงสว่างอยู่กับเจ้า {name} วันนี้ให้ช่วยอะไรไหม?" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "22:1579844308:969115409 C 1:46:46", "จงรับใช้แสงสว่างให้ดี {class}" },
        },
    },
    [1228] = {
        name = "Magis Sparkmantle",
        lines = {
            { "49:1390826475:1781916849", "สวัสดี ข้าเป็นครูฝึกจอมเวท และเจ้าเป็นจอมเวท" },
            { "10:1401179418:1568553899 C 101:1577892042:528431778", "ยินดีที่ได้พบ {class} ข้าขอแนะนำไว้ว่า เมื่อเดินทางไปทั่วโลก จงระวังเวทมนตร์ เพราะมันจะเผาผู้ที่ไม่ผ่านการฝึก" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [1229] = {
        name = "Granis Swiftaxe",
        lines = {
            { "80:1032263186:1890174864", "สงครามใหญ่อาจจบแล้วในตอนนี้ แต่เรายังต้องฝึกฝีมือให้เฉียบคม!" },
            { { "79:873017008:421501123 C 31:2134870025:914883839", "79:873017008:421501123 C 32:537594318:1592024306" }, "เจ้าไม่ใช่นักรบ... ตารางฝึกข้าเจ้าคงทนไม่ได้แม้แต่วันเดียว!\n\n{class}ที่คิดว่าตัวเองเป็นนักรบ ฮ่า!" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [1231] = {
        name = "Grif Wildheart",
        lines = {
            { "20:1806402586:1551596819", "ให้ข้าช่วยอะไร?" },
            { "53:1945481929:1069095775 C 9:839995460:592385449", "ข้าฝึกให้ไม่ได้ ควรหาครูฝึก{class}" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "108:22665804:1563291310", "ก่อนออกล่า ควรถามให้รู้ก่อนว่าต้องตามหาอะไร แล้วค่อยออกไปหา" },
        },
    },
    [1232] = {
        name = "Azar Stronghammer",
        lines = {
            { "22:1990256640:1107448062 C 20:931052451:317831623", "แสงอยู่กับเจ้า {class} ข้าช่วยอะไรได้?" },
            { "107:1108573917:1037022718", "แม้ไม่ตามวิถีแสงอย่างอัศวิน Silver Hand ก็ขอความช่วยเหลือจากเราได้เสมอ" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [1247] = {
        name = "Innkeeper Belm",
        lines = {
            { "143:297692507:1364973514", "ไม่ใช่ข้า แต่มีคนอื่นอีกมากที่กำลังมองหาความรัก เจ้าควรซื้อสื่อรักของข้า ใช้โคโลญหรือน้ำหอม แล้วนำไปแจกให้พวกเขา!" },
            { "271:1028484567:72113628", "ถ้าเจ้าใช้โคโลญหรือน้ำหอม ก็จะมองออกว่าใครกำลังมีใจ คนเหล่านั้นจะรับสื่อรัก... และมอบของขวัญตอบแทน\n\nแต่จำไว้ ถ้าจะมอบสื่อรักให้ใคร เจ้าต้องมีกลิ่นที่ถูกใจ! ผู้ชายชอบกลิ่นน้ำหอม ส่วนผู้หญิงชอบโคโลญ" },
            { "240:271214309:1448407633", "สื่อรักคือข้อความเล็ก ๆ แสดงความรู้สึกที่เจ้ามอบให้ชาวเมืองผู้กำลังมีใจได้ พวกเขาจะตอบแทนด้วยของขวัญแห่งความชื่นชม\n\nหรือหากมีใครชื่นชมเจ้าอยู่แล้ว อย่างน้อยก็จะได้รับของขวัญแห่งมิตรภาพ" },
            { "284:254841895:287193708", "เมื่อเจ้ามอบสื่อรักให้ชาวเมือง จะได้รับของขวัญหลายแบบตอบแทน บางชิ้นเจ้าคงอยากเก็บไว้ใช้ ส่วนชิ้นอื่นรวมเป็นชุดแล้วนำไปมอบให้วีรบุรุษคนโปรดของเจ้าได้! ไปหา Kwee Q. Peddlefeet เพื่อส่งของเหล่านั้น\n\nKwee อยู่ใกล้ Bolvar, Magni หรือ Tyrande" },
            { "286:1185563448:313386146", "เมื่อเจ้ามอบสื่อรักให้ชาวเมือง จะได้รับของขวัญหลายแบบตอบแทน บางชิ้นเจ้าคงอยากเก็บไว้ใช้ ส่วนชิ้นอื่นรวมเป็นชุดแล้วนำไปมอบให้วีรบุรุษคนโปรดของเจ้าได้! ไปหา Kwee Q. Peddlefeet เพื่อส่งของเหล่านั้น\n\nKwee อยู่ใกล้ Cairne, Sylvanas และ Thrall" },
            { "374:918067400:24586973", "ทำอะไรที่โรงเตี๊ยมได้หรือ?\n\nพักที่นี่สบายมาก จึงได้สถานะพักเต็มที่เร็วกว่ากลางป่า เมื่อพักเต็มที่จะเรียนรู้จากประสบการณ์มากขึ้น\n\nยังคุยเจ้าของโรงเตี๊ยมเพื่อรับ Hearthstone แล้วใช้กลับโรงเตี๊ยมนั้นอย่างรวดเร็วภายหลังได้" },
            { "78:1593679094:1534366546", "เติมเบียร์ให้เต็มเหยือกแล้วลากเก้าอี้มานั่ง เรามีเรื่องเล่าให้ฟังและถังเบียร์ให้ดื่มจนหมด" },
            { "79:873017008:421501123 C 31:2134870025:914883839", "เจ้าไม่ใช่นักรบหรอก... แค่ฝึกตามแบบของข้าวันเดียวก็คงไม่รอด!\n\n{class} ที่คิดว่าตัวเองเป็นนักรบ ฮ่า!" },
        },
    },
    [1257] = {
        name = "Keldric Boucher",
