    [3030] = {
        name = "Siln Skychaser",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "59:498915724:1123836113", "เหล่าวิญญาณนำเจ้ามาหาข้า ให้ข้ารับใช้อะไร?" },
            { "28:1102434926:2067309120", "ขอวิญญาณทั้งหลายอยู่กับเจ้า" },
        },
    },
    [3031] = {
        name = "Tigor Skychaser",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "59:498915724:1123836113", "เหล่าวิญญาณนำเจ้ามาหาข้า ให้ข้ารับใช้อะไร?" },
            { "28:1102434926:2067309120", "ขอวิญญาณทั้งหลายอยู่กับเจ้า" },
        },
    },
    [3032] = {
        name = "Beram Skychaser",
        lines = {
            { "59:498915724:1123836113", "เหล่าวิญญาณนำเจ้ามาหาข้า ให้ข้ารับใช้อะไร?" },
            { "28:1102434926:2067309120", "ขอวิญญาณทั้งหลายอยู่กับเจ้า" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [3033] = {
        name = "Turak Runetotem",
        lines = {
            { "42:328851328:1706344136 C 34:1380867553:1208508022", "จงพยายามรักษาสมดุลในทุกสิ่ง {class} ความกลมกลืนที่แท้จริงอยู่ตรงนั้น" },
            { { "311:310329008:910423881", "309:1603505346:854993688" }, "ยินดีต้อนรับ สหาย หากเจ้ามาฝึก ข้ายินดีสอน\n\nการตอกย้ำจุดยืนของตนในสิ่งที่ข้าเรียกว่ามหาสมดุลย่อมเป็นเรื่องดี ในฐานะผู้รักษาสมดุลนี้ เราต้องพยายามรักษาจิตให้แจ่มใสและใจให้เข้มแข็งอยู่เสมอ การฝึกฝนช่วยเราในเรื่องนี้ได้" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "255:967301392:2039283435", "นอกจากฝึกสอนแล้ว หากเจ้าต้องการ ข้ายังมีอำนาจลบความรู้เรื่องพรสวรรค์ออกจากจิตใจเจ้าได้ แต่จงรู้ไว้ว่า ยิ่งผ่านกระบวนการนี้บ่อยเท่าไร ก็ยิ่งทำได้ยากขึ้น และค่าใช้จ่ายจึงสูงขึ้นตามไปด้วย" },
            { "310:304437283:366527631", "ยินดีต้อนรับ พี่น้องชายของข้า หากเจ้ามาฝึก ข้ายินดีสอน\n\nการตอกย้ำจุดยืนของตนในสิ่งที่ข้าเรียกว่ามหาสมดุลย่อมเป็นเรื่องดี ในฐานะผู้รักษาสมดุลนี้ เราต้องพยายามรักษาจิตให้แจ่มใสและใจให้เข้มแข็งอยู่เสมอ การฝึกฝนช่วยเราในเรื่องนี้ได้" },
        },
    },
    [3034] = {
        name = "Sheal Runetotem",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "N 66:1029666708:1413466842", "{name} ให้ข้าช่วยพัฒนาการฝึกของเจ้าต่อเบื้องพระพักตร์ Earth Mother อย่างไร?" },
