    [3038] = {
        name = "Kary Thunderhorn",
        lines = {
            { "60:649552708:2136905631", "ข้าฝึกพรานตามวิถีและธรรมเนียมบรรพบุรุษ" },
            { "37:1918892154:909336377", "ข้าไม่มีความรู้ที่เจ้าแสวงหา" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [3039] = {
        name = "Holt Thunderhorn",
        lines = {
            { "251:1481385190:1355189445", "จงจำไว้ว่าทุกสิ่งเชื่อมโยงกัน หากสัตว์ทั้งหลายหายไปจากแผ่นดิน เผ่าพันธุ์เราคงตายเพราะความโดดเดี่ยวอันยิ่งใหญ่ของวิญญาณ เพราะสิ่งที่เกิดกับสัตว์ย่อมเกิดกับทอเรนเช่นกัน สิ่งใดเกิดขึ้นกับ Azeroth ย่อมเกิดกับทุกชีวิตที่อาศัยอยู่บนโลกนี้" },
            { "31:24417229:1281078058", "ข้าฝึกให้ไม่ได้ ผู้เยาว์" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [3040] = {
        name = "Urek Thunderhorn",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "27:1849403570:397657998", "ชอบปืนหรือธนู?" },
            { "37:1918892154:909336377", "ข้าไม่มีความรู้ที่เจ้าแสวงหา" },
        },
    },
    [3041] = {
        name = "Torm Ragetotem",
        lines = {
            { "60:775174924:1026492281", "ไม่ว่าจะเรียนรู้มากเพียงใด ก็มีสิ่งให้รู้อีกเสมอ" },
            { "21:92055795:1694012179 C 1:46:46", "ข้าฝึกเจ้าไม่ได้ {class}" },
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
        },
    },
    [3042] = {
        name = "Sark Ragetotem",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
