            { "79:777052425:1386117273", "พวกข้าไม่แน่ใจว่าจับตัวพาลาดินแล้วจะปลอดภัยไหม แต่พวกนั้นอยู่ตึกใหญ่ใน War Quarter" },
        },
    },
    [14731] = {
        name = "Lard",
        lines = {
            { "53:721349190:937344034", "Lard รักษาสงบ Lard ขายปลาด้วย เอาปลาไหม?" },
            { "54:1509162388:1289344823", "เจ้าสนใจสำรวจดันเจียนแห่งใดในรายชื่อนี้หรือ?" },
            { "143:297692507:1364973514", "ไม่ใช่ข้า แต่มีคนอื่นอีกมากที่กำลังมองหาความรัก เจ้าควรซื้อสื่อรักของข้า ใช้โคโลญหรือน้ำหอม แล้วนำไปแจกให้พวกเขา!" },
            { "80:1744600844:53726915", "Ragefire Chasm อยู่ใต้ Shadow Cleft ใจกลาง Orgrimmar" },
            { "70:91351037:483952506", "Deadmines อยู่ใต้ Moonbrook ทางใต้ของ Westfall" },
            { "99:624379484:206162701", "ทางเข้า Wailing Caverns อยู่ที่ Lushwater Oasis ทางตะวันตกเฉียงใต้ของ Crossroads ใน Barrens" },
            { "73:1710673714:532784296", "Shadowfang Keep อยู่ทางใต้ของ Silverpine เหนือ Pyrewood Village ขึ้นไปเล็กน้อย" },
            { "93:557457715:93376673", "Blackfathom Deeps อยู่ปลายเหนือของ Zoram Strand ตามแนวชายฝั่ง Ashenvale" },
            { "69:2100294091:676668042", "Stormwind Stockades อยู่ใกล้เขตจอมเวทใน Stormwind" },
            { "97:608159800:429979032", "Razorfen Kraul อยู่ปลายใต้สุดของ Barrens ทางตะวันตกของถนน" },
            { "46:840647565:1863982599", "Gnomeregan อยู่ทางตะวันตกของ Dun Morogh" },
            { "65:1641066687:1445917648", "Scarlet Monastery อยู่บนเนินเขาทางตะวันออกเฉียงเหนือของ Tirisfal Glades" },
            { "97:68076030:13341371", "Razorfen Downs อยู่ปลายใต้สุดของ Barrens ทางตะวันออกของถนน" },
            { "92:2042236857:109229047", "Maraudon อยู่บริเวณกลางชายฝั่งตะวันตกของ Desolace ใน Valley of Spears" },
            { "62:364191016:1482250396", "Uldaman อยู่ปลายเหนือสุดของ Badlands" },
            { "85:75056393:811756123", "ซาก Zul'Farrak อยู่ทางตะวันตกเฉียงเหนือของทะเลทราย Tanaris" },
            { "92:1288185509:1519153586", "Blackrock Mountain อยู่ระหว่าง Searing Gorge ทางเหนือกับ Burning Steppes ทางใต้" },
            { "89:1114199693:1255737642", "Sunken Temple อยู่กลางทะเลสาบใหญ่ทางตะวันออกของ Swamp of Sorrows" },
            { "48:802522548:1506360249", "ซาก Dire Maul ตั้งอยู่กลาง Feralas" },
            { "93:1645431247:221121953", "ซากเมือง Stratholme อยู่ใน Eastern Plaguelands ทางเหนือของ Plaguewood" },
            { "113:2066984913:714701657", "โรงเรียนศาสตร์ปลุกคนตายที่เรียกว่า Scholomance อยู่บนเกาะซากปรักหักพัง Caer Darrow ใน Western Plaguelands" },
            { "271:1028484567:72113628", "ถ้าเจ้าใช้โคโลญหรือน้ำหอม ก็จะมองออกว่าใครกำลังมีใจ คนเหล่านั้นจะรับสื่อรัก... และมอบของขวัญตอบแทน\n\nแต่จำไว้ ถ้าจะมอบสื่อรักให้ใคร เจ้าต้องมีกลิ่นที่ถูกใจ! ผู้ชายชอบกลิ่นน้ำหอม ส่วนผู้หญิงชอบโคโลญ" },
            { "240:271214309:1448407633", "สื่อรักคือข้อความเล็ก ๆ แสดงความรู้สึกที่เจ้ามอบให้ชาวเมืองผู้กำลังมีใจได้ พวกเขาจะตอบแทนด้วยของขวัญแห่งความชื่นชม\n\nหรือหากมีใครชื่นชมเจ้าอยู่แล้ว อย่างน้อยก็จะได้รับของขวัญแห่งมิตรภาพ" },
            { "284:254841895:287193708", "เมื่อเจ้ามอบสื่อรักให้ชาวเมือง จะได้รับของขวัญหลายแบบตอบแทน บางชิ้นเจ้าคงอยากเก็บไว้ใช้ ส่วนชิ้นอื่นรวมเป็นชุดแล้วนำไปมอบให้วีรบุรุษคนโปรดของเจ้าได้! ไปหา Kwee Q. Peddlefeet เพื่อส่งของเหล่านั้น\n\nKwee อยู่ใกล้ Bolvar, Magni หรือ Tyrande" },
            { "286:1185563448:313386146", "เมื่อเจ้ามอบสื่อรักให้ชาวเมือง จะได้รับของขวัญหลายแบบตอบแทน บางชิ้นเจ้าคงอยากเก็บไว้ใช้ ส่วนชิ้นอื่นรวมเป็นชุดแล้วนำไปมอบให้วีรบุรุษคนโปรดของเจ้าได้! ไปหา Kwee Q. Peddlefeet เพื่อส่งของเหล่านั้น\n\nKwee อยู่ใกล้ Cairne, Sylvanas และ Thrall" },
            { "504:1664242573:2077168795", "Ragefire Chasm เป็นเครือข่ายถ้ำภูเขาไฟใต้ Orgrimmar เมืองหลวงแห่งใหม่ของออร์ค ไม่นานมานี้มีข่าวลือว่าลัทธิที่ภักดีต่อสภาเงาปีศาจ Shadow Council เข้ามาตั้งถิ่นฐานในส่วนลึกอันร้อนระอุ ลัทธินี้ชื่อ Burning Blade และคุกคามอำนาจปกครองของ Durotar หลายคนเชื่อว่า Thrall จอมทัพออร์ครู้ถึงการมีอยู่ของลัทธิ แต่เลือกไม่ทำลาย ด้วยหวังว่าสมาชิกจะนำเขาไปถึง Shadow Council โดยตรง" },
            { "458:626400020:669176375", "Dead Mines เคยเป็นแหล่งผลิตทองคำที่ใหญ่ที่สุดในดินแดนมนุษย์ แต่บัดนี้กลุ่มภราดร Defias ยึดครองอุโมงค์มืดเป็นฐานลับของตน มีข่าวลือว่าพวกโจรเกณฑ์กอบลินหัวใสมาช่วยสร้างสิ่งน่าสะพรึงกลัวบางอย่างที่ก้นเหมือง แต่ยังไม่มีใครรู้ว่าคืออะไร ว่ากันว่าทางเข้า Deadmines อยู่ในหมู่บ้าน Moonbrook ที่เงียบสงบและดูธรรมดา" },
            { "509:1334559053:1662815292", "ไม่นานมานี้ ดรูอิดไนต์เอลฟ์ชื่อ Naralex ค้นพบเครือข่ายถ้ำใต้ดินกลาง Barrens เขาเชื่อว่าน้ำพุในถ้ำจะฟื้นความเขียวชอุ่มให้ Barrens ได้ จึงเริ่มดึงพลังจาก Emerald Dream ในตำนาน แต่ภาพฝันของเขากลับกลายเป็นฝันร้ายด้วยเหตุบางอย่าง และไม่นาน Wailing Caverns ก็กลายเป็นรังของนักล่าดุร้ายอันตราย ว่ากันว่า Naralex ยังอยู่ที่ใดสักแห่งในเขาวงกต ติดอยู่พ้นขอบเขตของ Emerald Dream" },
            { "506:733088840:1922386598", "ในสงครามครั้งที่สาม อัครจอมเวท Arugal ไม่พอใจที่เหล่าจอมเวท Dalaran ต่อกรกับอันเดดได้ไม่คืบหน้า เขาจึงเลือกอัญเชิญวอร์เกนจากต่างมิติมาเสริมกำลังที่ร่อยหรอ มนุษย์หมาป่าฆ่ากองทัพ Scourge แล้วหันกลับมาโจมตีจอมเวทอย่างรวดเร็ว และล้อมป้อมของขุนนาง Baron Silverlaine ป้อมตกสู่ความมืดและความพินาศในเวลาไม่นาน Arugal เสียสติด้วยความรู้สึกผิด รับพวกวอร์เกนเป็นลูก และถอยเข้าไปในป้อมที่ถูกเรียกใหม่ว่า Shadowfang Keep" },
            { "451:1767201963:1216787998", "Blackfathom Deeps ริม Zoram Strand ใน Ashenvale เคยเป็นวิหารอันรุ่งเรืองที่อุทิศแด่ Elune เทพีจันทราของไนต์เอลฟ์ แต่มหาแผ่นดินแยกทำให้วิหารแตกพังและจมลงใต้คลื่นของ Veiled Sea ที่นั่นไม่ถูกรบกวนมาเนิ่นนาน จนพลังโบราณดึงดูดนากากับเซเทอร์ให้เข้ามาค้นความลับ ตำนานกล่าวว่าสัตว์ร้ายโบราณ Aku'mai เข้ามาอาศัยในซากวิหารแล้ว" },
            { "426:310551552:1030832871", "Stockades เป็นเรือนจำความมั่นคงสูงใต้เขตคลองของเมือง Stormwind อยู่ในการดูแลของ Warden Thelwater นักโทษมีตั้งแต่โจรกระจอก ผู้ก่อกบฏ ฆาตกร ไปจนถึงอาชญากรอันตรายที่สุดในดินแดน ไม่นานมานี้ นักโทษก่อจลาจลจน Stockades ตกอยู่ในความโกลาหล ยามถูกขับไล่ออกมา และพวกนักโทษเดินเพ่นพ่านได้อย่างเสรี" },
            { "501:963719863:170285089", "ระหว่างสงครามแห่งบรรพกาล กึ่งเทพ Agamaggan ออกต่อสู้กับ Burning Legion หมูป่าร่างมหึมาถูกสังหาร และเมื่อเวลาผ่านไป เถาวัลย์หนามขนาดใหญ่ก็งอกขึ้นในบริเวณที่เลือดของเขาหยดลง พวกควิลบอร์เข้ามาอาศัยและยกย่องดินแดนเหล่านี้เป็นสถานที่ศักดิ์สิทธิ์ ใจกลางของดงหนามอันมหึมาคือ Razorfen ส่วน Razorfen Kraul ถูกแม่เฒ่า Charlga Razorflank ยึดครอง บางคนคาดว่านางกำลังเจรจากับตัวแทนของ Scourge เพื่อจุดประสงค์ชั่วร้ายบางอย่าง" },
            { "501:87524731:659335229", "Gnomeregan ใน Dun Morogh เป็นเมืองหลวงของโนมมาหลายชั่วรุ่น แต่ไม่นานมานี้ถูกโทรกก์กลายพันธุ์รุกราน ในความพยายามตอบโต้อย่างสิ้นหวัง High Tinker Mekkatorque สั่งระบายถังกากกัมมันตรังสีของเมืองเป็นการฉุกเฉิน แม้โทรกก์จะได้รับรังสี แต่การปิดล้อมก็ไม่หยุด พวกโนมต้องลี้ภัยไปยังเมือง Ironforge ของคนแคระ บัดนี้ High Tinker กำลังขอให้ผู้กล้าช่วยชาวโนมทวงเมืองอันเป็นที่รักคืน" },
            { "411:1454562628:83254821", "อารามแห่งนี้เคยเป็นศูนย์กลางการเรียนรู้และปัญญา เมื่อกองทัพอันเดด Scourge ผงาดขึ้นในสงครามครั้งที่สาม อารามอันสงบก็ถูกเปลี่ยนเป็นป้อมของกลุ่ม Scarlet Crusade ผู้คลั่งศรัทธา พวกเขาไม่ยอมรับเผ่าพันธุ์อื่นนอกจากมนุษย์ ไม่ว่าจะสังกัดหรือเป็นพันธมิตรกับใคร พวกเขาเชื่อว่าคนนอกทุกคนอาจเป็นพาหะโรคระบาดอันเดด และต้องถูกกำจัด" },
            { "497:1797342455:785834952", "Razorfen Downs ก่อเกิดจากเถาวัลย์ชนิดเดียวกับ Razorfen Kraul และเป็นเมืองหลวงดั้งเดิมของเผ่าควิลบอร์ เขาวงกตหนามที่แผ่กว้างเป็นที่อยู่ของกองทัพควิลบอร์ผู้ภักดีและเหล่ามหาปุโรหิตจากเผ่า Death's Head แต่เมื่อไม่นานมานี้ เงามืดได้ปกคลุมถิ่นอาศัยอันหยาบง่ายแห่งนี้ สมุนของกองทัพอันเดด Scourge นำโดยลิช Amnennar the Coldbringer เข้าควบคุมเผ่าควิลบอร์ และเปลี่ยนเขาวงกตหนามให้เป็นฐานอำนาจของอันเดด" },
            { "510:1686150334:1773225400", "Maraudon เป็นหนึ่งในสถานที่ศักดิ์สิทธิ์ที่สุดของ Desolace วิหารในถ้ำอันยิ่งใหญ่นี้เป็นที่ฝังศพ Zaetar บุตรอมตะหนึ่งในสองคนของกึ่งเทพ Cenarius ตำนานกล่าวว่า Zaetar กับเจ้าหญิงธาตุดิน Theradras ให้กำเนิดเผ่าเซนทอร์อันวิปริต เมื่อถือกำเนิด พวกเซนทอร์ป่าเถื่อนกลับหันมาฆ่าบิดาของตน บางคนเชื่อว่า Theradras ผู้โศกเศร้ากักวิญญาณ Zaetar ไว้ในถ้ำอันคดเคี้ยว และใช้พลังของเขาเพื่อจุดประสงค์ชั่วร้ายบางอย่าง" },
            { "509:1316188170:1212635279", "Uldaman เป็นคลังโบราณของเหล่าไททันที่ฝังอยู่ใต้ดินมาตั้งแต่กำเนิดโลก การขุดค้นเมืองของคนแคระเมื่อไม่นานมานี้ปลดปล่อยผลงานสร้างที่ล้มเหลวครั้งแรกของไททัน นั่นคือโทรกก์ ตำนานกล่าวว่าเมื่อไททันเห็นว่าการทดลองโทรกก์ล้มเหลว พวกเขาก็ลองใหม่จนเกิดเผ่าคนแคระ ความลับเหล่านี้ถูกบันทึกบน Discs of Norgannon โบราณวัตถุขนาดมหึมาที่ก้นเมืองโบราณ มีสิ่งสร้างยักษ์จากหินมีชีวิตคอยปกป้อง" },
            { "410:2005894423:1859061392", "เมืองที่แผดเผาด้วยแสงอาทิตย์แห่งนี้เป็นบ้านของโทรลล์ Sandfury ผู้ขึ้นชื่อเรื่องความโหดเหี้ยมและศาสตร์ลี้ลับมืด ตำนานโทรลล์เล่าถึงดาบทรงพลังชื่อ Sul'thraze the Lasher อาวุธที่ทำให้แม้แต่ศัตรูที่น่าเกรงขามที่สุดหวาดกลัวและอ่อนแรง นานมาแล้วดาบถูกแยกเป็นสองส่วน แต่มีข่าวลือว่าทั้งสองส่วนยังอยู่ที่ใดสักแห่งภายในกำแพง Zul'Farrak" },
            { "416:140483117:106366345", "เขาวงกตภูเขาไฟแห่งนี้เคยเป็นเมืองหลวงของคนแคระ Dark Iron แต่ปัจจุบันเป็นศูนย์อำนาจของ Ragnaros เจ้าแห่งอัคคี Ragnaros ค้นพบความลับในการสร้างชีวิตจากหิน และวางแผนสร้างกองทัพโกเลมที่ไม่มีใครหยุดได้ เพื่อช่วยยึด Blackrock Mountain ทั้งหมด ด้วยความหมกมุ่นที่จะเอาชนะ Nefarian และลูกสมุนมังกรของมัน Ragnaros พร้อมทำทุกอย่างเพื่อชัยชนะครั้งสุดท้าย" },
            { "504:1292144803:1412676623", "กว่าหนึ่งพันปีก่อน กลุ่มนักบวชโทรลล์ชื่อ Atal'ai พยายามนำเทพโลหิตโบราณ Hakkar the Soulflayer กลับมา หลังสงครามกลางเมืองที่เกิดขึ้น พวกนักบวชพ่ายแพ้และถูกเนรเทศไป Swamp of Sorrows ที่นั่นพวกเขาสร้างวิหารให้ Hakkar เพื่อเตรียมรับการมาสู่โลกกายภาพ จอมมังกร Ysera รู้แผนของ Atal'ai ในเวลาต่อมา และทำลายวิหารให้จมลงใต้หนองบึง จนถึงวันนี้ ซากวิหารยังมีมังกรเขียวทรงพลังเฝ้าอยู่" },
            { "462:1000346273:1381161943", "ป้อมปราการยิ่งใหญ่ที่สลักขึ้นในห้วงลึกอันร้อนระอุของ Blackrock Mountain อยู่ในมือคนแคระ Dark Iron ผู้ชั่วร้ายมาหลายศตวรรษ จน Nefarian บุตรเจ้าเล่ห์ของมังกร Deathwing เข้ายึดยอดหอคอยส่วนบน และทำสงครามกับฐานที่มั่นของคนแคระในส่วนลึกภูเขาไฟ เมื่อรู้ว่าผู้นำคนแคระคือธาตุไฟผู้ทรงพลัง Ragnaros มันจึงสาบานจะบดขยี้ศัตรูและยึด Blackrock Mountain ทั้งหมดเป็นของตน" },
            { "442:772107906:1177469223", "เมืองโบราณ Eldre'Thalas สร้างขึ้นเมื่อหนึ่งหมื่นสองพันปีก่อนโดยกลุ่มจอมเวทไนต์เอลฟ์ที่ปิดบังตัวตน เพื่อปกป้องความลับอาคมที่ราชินี Azshara หวงแหนที่สุด แม้มหาแผ่นดินแยกจะทำลายเมือง แต่ส่วนใหญ่ของเมืองอันน่าอัศจรรย์ยังตั้งตระหง่านในชื่อ Dire Maul ซากเมืองทั้งสามเขตถูกสิ่งมีชีวิตนานาชนิดยึดครอง โดยเฉพาะวิญญาณไฮบอร์น เซเทอร์ชั่วร้าย และโอเกอร์ป่าเถื่อน" },
            { "506:48507321:909876192", "เมือง Stratholme ซึ่งเคยเป็นอัญมณีแห่ง Lordaeron ตอนเหนือ คือสถานที่ที่เจ้าชาย Arthas หันหลังให้อาจารย์ Uther Lightbringer และสังหารราษฎรของตนหลายร้อยคนที่เชื่อว่าติดโรคระบาดอันเดด ไม่นานต่อมา Arthas ก็ยอมสยบต่อ Lich King บัดนี้เมืองที่พังพินาศเป็นที่อยู่ของกองทัพอันเดด Scourge ซึ่งนำโดยลิชผู้ทรงพลัง Kel'Thuzad และกองกำลัง Scarlet Crusade ที่นำโดย Grand Crusader Dathrohan ทั้งสองฝ่ายปะทะกันอย่างรุนแรงไม่หยุดหย่อน" },
            { "510:1186392668:1491167180", "Scholomance ตั้งอยู่ในสุสานใต้ป้อม Caer Darrow ป้อมนี้เคยเป็นของตระกูลขุนนาง Barov ก่อนพังพินาศหลังสงครามครั้งที่สอง เมื่อจอมเวท Kel'Thuzad รวบรวมสาวกให้ Cult of the Damned เขามักสัญญาจะมอบความเป็นอมตะแก่ผู้รับใช้ Lich King ตระกูล Barov หลงเชื่อและยกป้อมให้ แต่พวกลัทธิฆ่าคนในตระกูล แล้วเปลี่ยนสุสานเป็นโรงเรียนศาสตร์ปลุกคนตาย แม้ Kel'Thuzad จะไม่อยู่ที่นั่นแล้ว พวกลัทธิกับอาจารย์ก็ยังคงอยู่" },
        },
    },
    [10583] = {
        name = "Gryfe",
        lines = {
            { "31:808893464:1178195280", "เจ้าต้องการบินไปที่ใด?" },
        },
    },
    [16227] = {
        name = "Bragok",
        lines = {
            { "31:808893464:1178195280", "เจ้าต้องการบินไปที่ใด?" },
        },
    },
    [3191] = {
        name = "Cook Torka",
        lines = {
            { "67:39305149:2116667824", "การทำอาหารเป็นสิ่งที่เรียนรู้ได้ตลอดชีวิต และข้าเห็นว่าเราหลงใหลในสิ่งเดียวกัน!" },
            { "28:736307832:563898616", "ข้าสอนทำอาหารให้ได้!" },
        },
    },
    [265944] = {
        name = "William Pickman",
        lines = {
            { "67:39305149:2116667824", "การทำอาหารเป็นสิ่งที่เรียนรู้ได้ตลอดชีวิต และข้าเห็นว่าเราหลงใหลในสิ่งเดียวกัน!" },
            { "28:736307832:563898616", "ข้าสอนทำอาหารให้ได้!" },
        },
    },
    [260093] = {
        name = "Garen Largo",
        lines = {
            { "360:578785383:920675082", "ในการฝึกใหม่อย่างเข้มงวด ข้าต้องให้ศิษย์หลายคนละทิ้งทุกสิ่งที่เคยเรียนรู้ เพื่อจะสอนพวกเขาใหม่ ยิ่งทำซ้ำ การฝึกเช่นนี้ก็ยิ่งยากขึ้น ด้วยเหตุนี้ ค่าใช้จ่ายจึงเพิ่มขึ้นทุกครั้ง เจ้าต้องการให้ข้าลบพรสวรรค์ที่เจ้าเรียนรู้มาแล้วหรือไม่?" },
            { "49:1796672903:1249897667", "เจ้าอยากฝึกวิถีแห่งพระแสงหรือ?" },
        },
    },
    [251001] = {
        name = "Deathguard Kristof",
        lines = {
            { "25:1423924806:454153562", "เจ้ากำลังมองหาอะไร?" },
            { "204:729705424:905224069", "ได้โปรดดูให้แน่ใจว่าเขาอ่านมันทันที ข้าเกรงว่าปัญหา Scourge ของเราเพิ่งเริ่มต้น\n\nกลับมาพบข้าอีกเมื่อถึงเวลา ข้าเชื่อว่าเกือบพบอะไรบางอย่างที่น่าจะใช้ดาบของผู้เต็มใจมาช่วยจัดการได้แล้ว" },
            { "216:1606543478:1051081740", "จริง ๆ ข้าชอบวิธีรักษาแบบดั้งเดิมมากกว่า... ปลิง หนอน เลื่อยตัดกระดูก อะไรทำนองนั้น แต่ก็แล้วแต่คนชอบ เจ้าไปหา Faruza ครูฝึกวิชาสมุนไพรของเราได้ นางยืนอยู่ข้างหน้าใกล้คอกม้าใน Brill" },
            { "106:1293876518:1645095020", "Clyde Kellen นักตกปลามือฉมังแถวนี้ มีจุดตกปลาประจำที่ Brightwater Lake ทางตะวันออกของ Brill" },
            { "17:1560454218:1354943701", "วิชาชีพอะไรล่ะ?" },
            { "206:771225178:1702252307", "Rand Rhobart ถลกหนังเฟลแบตกับสัตว์ทำนองนั้นได้เก่งทีเดียว เจ้าจะพบเขาที่ค่ายริมถนนทางตะวันออกเฉียงใต้ของ Brill ออกจากเมืองไปตามถนนด้านตะวันออกเฉียงใต้ แล้วเลี้ยวไปทางตะวันออกตรงทางแยก" },
            { "274:427701097:1468619138", "คิดจะเป็นช่างสตัฟฟ์สัตว์หรือ? ข้าไม่ชอบคนที่เห็นข้าตายแล้วก็คิดจะจับข้ายัดนุ่นตั้งโชว์ ไม่ใช่หรือ? ดี! ไปหา Rand Rhobart ที่ค่ายทางตะวันออกเฉียงใต้ของเมือง ตามถนนออกจาก Brill ไปทางตะวันออกเฉียงใต้ แล้วเลี้ยวซ้ายที่ทางแยก" },
            { "264:1197860315:1980326545", "ที่ Brill ไม่มีธนาคาร เจ้าต้องไปที่ Undercity ด้านหลังซากเมือง Lordaeron ทางใต้มีลิฟต์ลงไป พอถึงแล้วถามทางต่อกับยามประจำ Undercity ได้เลย" },
        },
    },
    [258930] = {
        name = "Isaac Chan",
        lines = {
            { "61:250644815:1162909176", "เจ้ามาฝึกเพื่อจะนำไปสอนสัตว์เลี้ยงของเจ้าหรือ?" },
            { "46:1291027720:1211870466", "อา สหาย ข้าช่วยเฉพาะพรานกับสัตว์คู่ใจของพวกเขาเท่านั้น" },
        },
    },
    [272101] = {
        name = "Deathguard Lizabetha",
        lines = {
            { "25:1423924806:454153562", "เจ้ากำลังมองหาอะไร?" },
            { "17:1560454218:1354943701", "วิชาชีพไหนล่ะ?" },
            { "288:569121407:1346930556", "สงสัยบทฝึกแรกของเจ้าคงต้องขุดทางลงไปถึง Undercity ฮะ เข้าใจไหม? ขุดไง... ช่างเถอะ ถ้าจะไป Undercity ให้ไปด้านหลัง Ruins of Lordaeron ทางใต้ของ Brill แล้วลงลิฟต์ไป ถึงแล้วก็ถาม Undercity Guardian สักคนให้ช่วยบอกทางต่อ" },
        },
    },
    [246848] = {
        name = "Kirin Tor Guard",
        lines = {
            { "25:1423924806:454153562", "เจ้ากำลังมองหาอะไร?" },
            { "39:1434636018:103319421", "มีอะไรให้ข้าช่วยไหม?" },
            { "35:1734407055:1915003365", "เจ้าอยากรู้อะไรหรือ?" },
        },
    },
    [253474] = {
        name = "Peacekeeper",
        lines = {
            { "17:1560454218:1354943701", "วิชาชีพใด?" },
            { "19:1454775137:823929483", "สวัสดี พลเมือง" },
            { "40:291002089:575715052", "เจ้าตามหาครูฝึกคลาสไหน?" },
            { "34:1716281137:1971836214", "เจ้าตามหาอะไรอยู่ พลเมือง?" },
            { "98:1517650264:848902985", "เจ้าจะพบ Lotheluum Starbreeze บนหน้าผาที่มองลงไปเห็นน้ำตกทางฝั่งตะวันออกของเมือง" },
            { "39:286685877:1539168161", "มีอะไรให้ข้าช่วยหาไหม?" },
            { "109:1879164160:457537301", "เรือของ High Order ที่เดินทางไป Azeroth อยู่ที่ท่าเรือสุดทางด้านตะวันออกเฉียงใต้ของ Valanaar" },
            { "41:663939535:1317221410", "ให้ข้าช่วยชี้ทางไหม พลเมือง?" },
            { "78:510728344:1495550646", "ครูฝึกคนนั้นอยู่ใน Crafter's Hall ทางฝั่งตะวันตกของ Valanaar" },
            { "110:1392435326:1394391341", "ธนาคารกับตลาดประมูลอยู่ฝั่งตะวันตกของ Valanaar ใกล้ท่าเรือ skycutter ของเหล่า Windshaper" },
            { "75:1974325048:1336153193", "ครูสอนทำอาหารอยู่ในบ้านหลังเล็กทางเหนือสุดของเมือง" },
            { "167:1042166630:1772513506", "ระวังตัวไว้ในที่ราบสูงนี้ พลเมือง มีทั้งสัตว์ร้ายที่เพ่นพ่านอยู่ในป่า โจรใจอำมหิต และภัยจากพวก Al'Aketh ที่ใกล้เข้ามา" },
            { "4:1432760897:190637651 C 87:1599609982:1056933149", "ครูฝึก{class}อยู่ในที่พักของ High Order ทางฝั่งตะวันออกเฉียงใต้ของเมือง" },
            { "75:241735990:272412348", "หมอประจำเมืองอยู่ในหอคอยตรงขอบเมืองด้านตะวันออกเฉียงเหนือ" },
            { "428:1977368644:1601077886", "ช่างวิศวกรรมหรือ? Skywall ช่วยที นั่นมันอะไร?\n\nพอเจ้าพูดถึง... ข้าว่าเคยได้ยิน Sirrocas ขี้เมาที่โรงเตี๊ยมเล่าว่าเขาเจอวิญญาณป่าตนหนึ่งที่เรียกตัวเองว่า “ช่างวิศวกรรม”\n\nข้าเพิ่งเคยได้ยินเรื่องแบบนั้นเป็นครั้งแรก\n\nถ้าจำไม่ผิด เขาว่าวิญญาณตนนั้นอยู่ที่ไหนสักแห่งใน Shadowgale Forest แต่ข้าไม่แนะนำให้เจ้าไปที่ต้องสาปนั่นหรอก!" },
            { "104:939106561:1205490898", "ครูฝึกตกปลาอยู่ใกล้บ่อน้ำตรงตีนธารน้ำตก ทางขอบเมืองด้านตะวันออก" },
            { "87:1518942212:1120232969", "ครูฝึกคนนั้นอยู่ตรงขอบเมืองด้านตะวันออกเฉียงใต้ ใกล้ท่าเรือของ High Order" },
            { "96:1173336265:36404638", "ครูฝึกคนนั้นอยู่ในบ้านหลังหนึ่งใกล้ท่าเรือของ High Order ตรงขอบเมืองด้านตะวันออกเฉียงใต้" },
            { "99:325146668:502841572", "ครูฝึกชาแมนอยู่ใกล้กลุ่มเสาหินของ Windshaper ทางขอบเมืองด้านตะวันตก" },
        },
    },
    [258098] = {
        name = "Eldrun Stormbreaker",
        lines = {
            { "255:967301392:2039283435", "นอกจากฝึกสอนแล้ว หากเจ้าต้องการ ข้ายังมีอำนาจลบความรู้เรื่องพรสวรรค์ออกจากจิตใจเจ้าได้ แต่จงรู้ไว้ว่า ยิ่งผ่านกระบวนการนี้บ่อยเท่าไร ก็ยิ่งทำได้ยากขึ้น และค่าใช้จ่ายจึงสูงขึ้นตามไปด้วย" },
            { "59:498915724:1123836113", "เหล่าวิญญาณนำเจ้ามาหาข้า ให้ข้ารับใช้อะไร?" },
        },
    },
    [252477] = {
        name = "Peacekeeper Elite",
        lines = {
            { "17:1560454218:1354943701", "วิชาชีพใด?" },
            { "19:1454775137:823929483", "สวัสดี พลเมือง" },
            { "40:291002089:575715052", "เจ้าตามหาครูฝึกคลาสไหน?" },
            { "34:1716281137:1971836214", "เจ้าตามหาอะไรอยู่ พลเมือง?" },
            { "98:1517650264:848902985", "เจ้าจะพบ Lotheluum Starbreeze บนหน้าผาที่มองลงไปเห็นน้ำตกทางฝั่งตะวันออกของเมือง" },
            { "39:286685877:1539168161", "มีอะไรให้ข้าช่วยหาไหม?" },
            { "109:1879164160:457537301", "เรือของ High Order ที่เดินทางไป Azeroth อยู่ที่ท่าเรือสุดทางด้านตะวันออกเฉียงใต้ของ Valanaar" },
            { "41:663939535:1317221410", "ให้ข้าช่วยชี้ทางไหม พลเมือง?" },
            { "78:510728344:1495550646", "ครูฝึกคนนั้นอยู่ใน Crafter's Hall ทางฝั่งตะวันตกของ Valanaar" },
            { "110:1392435326:1394391341", "ธนาคารกับตลาดประมูลอยู่ฝั่งตะวันตกของ Valanaar ใกล้ท่าเรือ skycutter ของเหล่า Windshaper" },
            { "75:1974325048:1336153193", "ครูสอนทำอาหารอยู่ในบ้านหลังเล็กทางเหนือสุดของเมือง" },
            { "75:241735990:272412348", "หมอประจำเมืองอยู่ในหอคอยทางฝั่งตะวันออกเฉียงเหนือของเมือง" },
            { "104:939106561:1205490898", "ครูสอนตกปลาอยู่ใกล้สระตรงเชิงน้ำตกทางฝั่งตะวันออกของเมือง" },
            { "96:1173336265:36404638", "ครูฝึกคนนั้นอยู่ในบ้านใกล้ท่าเรือของ High Order ทางฝั่งตะวันออกเฉียงใต้ของเมือง" },
            { "428:1977368644:1601077886", "วิศวกรรึ? ใน Skywall นี่มันตัวอะไรกัน?\n\nพอเจ้าพูดถึง ข้าว่าเคยได้ยินเจ้า Sirrocas ขี้เมาที่โรงเตี๊ยมเล่าว่าเขาเจอวิญญาณป่าตนหนึ่งที่เรียกตัวเองว่า ‘วิศวกร’\n\nนั่นเป็นครั้งแรกที่ข้าเคยได้ยินเรื่องแบบนั้น\n\nข้าว่าเขาบอกว่าวิญญาณตนนั้นอยู่ที่ไหนสักแห่งใน Shadowgale Forest แต่ข้าไม่แนะนำให้เจ้าเข้าไปในที่ต้องสาปนั่นหรอก!" },
            { "87:1518942212:1120232969", "ครูฝึกคนนั้นอยู่ทางฝั่งตะวันออกเฉียงใต้ของเมือง ใกล้ท่าเรือของ High Order" },
            { "99:325146668:502841572", "ครูฝึกชาแมนอยู่ใกล้กลุ่มหินตั้งของเหล่า Windshaper ทางฝั่งตะวันตกของเมือง" },
            { "95:1297275926:1835553757", "ครูฝึกจอมเวทอยู่ในที่พักของ High Order ทางฝั่งตะวันออกเฉียงใต้ของเมือง" },
            { "75:720874536:1311941252", "เจ้าต้องไปที่ Hall of Arms ทางฝั่งเหนือของ Valanaar" },
            { "90:1524524527:319277327", "มีตู้ไปรษณีย์อยู่หน้าโรงเตี๊ยม ใกล้ถนนที่มุ่งขึ้นเหนือออกจากเมือง" },
            { "80:1606893309:1883695005", "โรงเตี๊ยมอยู่ทางตะวันออกของถนนที่มุ่งขึ้นเหนือออกจากเมือง" },
        },
    },
    [254411] = {
        name = "Quel'dora Quickgale",
        lines = {
            { "61:250644815:1162909176", "เจ้ามาฝึกเพื่อจะนำไปสอนสัตว์เลี้ยงของเจ้าหรือ?" },
            { "46:1291027720:1211870466", "อา สหาย ข้าช่วยได้เฉพาะพรานและสัตว์เลี้ยงของพวกเขา" },
        },
    },
    [258568] = {
        name = "Antonio Bolero",
        lines = {
            { "80:823615287:721350807", "แวะดูสินค้าของข้าเฉย ๆ หรือวันนี้มีอะไรที่อยากให้ช่วยหาเป็นพิเศษ?" },
            { "95:1006349034:431655755", "ราคาดีที่สุดใน Stormwind แล้ว สหาย เจ้าหาที่ดีกว่านี้ไม่ได้หรอก เอาละ ให้ข้าช่วยอะไรดี?" },
        },
    },
    [255877] = {
        name = "Hunter Moore",
        lines = {
            { "31:361757421:2071720232", "ข้าสอนทักษะตกปลาให้เจ้าได้" },
        },
    },
    [5396] = {
        name = "Captain Pentigast",
        lines = {
            { "90:560511714:688698435", "Alliance มีผลประโยชน์มากมายใน Desolace และฐานที่มั่นของเราที่นี่ไม่มั่นคง\n\nเจ้าจะช่วยเราไหม?" },
        },
    },
    [5637] = {
        name = "Roetten Stonehammer",
        lines = {
            { "20:1192741363:1762228774 C 221:1527254147:1672284971", "ยินดีที่ได้รู้จัก {class} ข้าชื่อ Roetten เป็นผู้นำ Reclaimers Incorporated\n\nข้ากับกิลด์เชี่ยวชาญการตามหาของที่หายไป เรามักจ้างนักผจญภัยผู้กล้าไปทำงานให้ผู้ที่ทำเองไม่ได้หรือไม่มีเวลา" },
        },
    },
    [5638] = {
        name = "Kreldig Ungor",
        lines = {
            { "46:1426656227:314543395 N 170:324322909:1620563477", "ข้ามีงานมากมายที่นี่ใน Desolace นะ {name} ทั้งหาส่วนผสมให้ลูกค้าคนหนึ่งตามที่ Roetten ต้องการ และตามหาของที่หายไปพวกนี้ด้วย\n\nในเมื่อเจ้ามาช่วยแล้ว ทำไมเราไม่เริ่มกันเลยล่ะ?" },
        },
    },
    [11596] = {
        name = "Smeed Scrabblescrew",
        lines = {
            { "137:1117842848:1093342839", "แผนธุรกิจของข้าไม่เคยคิดเผื่อว่าจะต้องหาที่อยู่ให้โคโดยักษ์... บางทีข้าน่าจะไปทำธุรกิจสานตะกร้าใต้น้ำแทน" },
        },
    },
    [11625] = {
        name = "Cork Gizelton",
        lines = {
            { "287:2044237616:850284824", "อา... ลูกค้า! คุยกับสิ่งประดิษฐ์ที่ยิ่งใหญ่ที่สุดของข้า Vendor-Tron 1000 มันมีทุกอย่างที่เจ้าต้องการ... ของบางชิ้นหายากที่สุดเท่าที่จะพบในตลาดทั่ว Kalimdor... และอย่าลืมว่าโปรแกรมของมันไม่ยอมให้ต่อราคา ดังนั้นเห็นราคาเท่าไรก็จ่ายเท่านั้น" },
        },
    },
    [11626] = {
        name = "Rigger Gizelton",
        lines = {
            { "245:2107592551:71804262", "วันนี้เป็นวันโชคดีของเจ้า ข้าเพิ่งบำรุงรักษา Super-Seller 680 เสร็จ มีสินค้ามากมายขายในราคาถูกแสนถูก ไปดูเองได้เลย... Cork พี่น้องข้าคิดว่า Vendor-Tron 1000 ของเขาจะขายดีกว่าหุ่นของข้า" },
        },
    },
    [4048] = {
        name = "Falfindel Waywarder",
        lines = {
            { "48:1031808310:1304948724 R 1:46:46", "เจ้าดูเหมือนเดินทางมาจากแดนไกล {race}" },
        },
    },
    [7406] = {
        name = "Oglethorpe Obnoticus",
        lines = {
            { { "361:1081573336:1145257556", "362:731462363:157910162" }, "สวัสดี สหายรุ่นเยาว์... ข้าชื่อ Oglethorpe และอาจเป็นผู้สร้างอุปกรณ์โนมมหัศจรรย์ที่เจ้ามี! ถ้ามันระเบิด ไม่ใช่ข้าหรอก แต่ถ้าทำให้รวย เราก็คุยเรื่องค่าลิขสิทธิ์กันได้!\n\nอ้อ ถ้ามาจาก Gnomeregan ก็เอามุมเก้าสิบองศาสองมุมมาชนกัน แล้วเดินจากไปเสีย ข้าไม่มีอะไรจะพูดด้วย" },
            { "18:1980499155:1434006556 N 159:1104407389:893534792", "อ้าว {name} นี่เอง! ดีใจที่พบอีก ข้าขอบคุณไม่พอจริง ๆ สำหรับความช่วยเหลือข้ากับงานประดิษฐ์ที่ผ่านมา\n\nวันนี้มีอะไรให้ช่วย?" },
        },
    },
    [7763] = {
        name = "Curgle Cranklehop",
        lines = {
            { "441:1184038926:139773860", "สวัสดี! ข้ามีข้อเสนอให้นักผจญภัยอย่างเจ้า หากพร้อมรับความท้าทาย!\n\nข้ากับสิ่งประดิษฐ์ Super Egg-O-Matic กำลังช่วยดรูอิดในโครงการอนุรักษ์ฮิปโปกริฟฟ์ นกเหล่านี้ได้รับผลร้ายจากโอเกอร์ Gordunni ที่อยู่ในซากเมือง Feralas จำนวนจึงลดลงเรื่อย ๆ\n\nข้าเก็บไข่หลายชนิด เจ้าช่วยหามาให้ได้ไหม?" },
            { "387:567820702:164703919 N 62:1701450091:1776020226", "ที่ดินแดนชื่อ Feralas ทางตะวันตก ฮิปโปกริฟฟ์ สหายเก่าแก่ของไนต์เอลฟ์ กำลังมีภัย\n\nข้าต้องการให้เจ้าช่วยไข่จากซาก Isildien ทางใต้ในดินแดนนั้น Super Egg-O-Matic วิเคราะห์ไข่ที่นำมาได้ทุกชนิดและตัดสินว่าน่าจะฟักไหม จากนั้นข้าจะส่งให้ดรูอิด ปลอดภัยจากเวทมนตร์มืด Gordunni\n\nรู้ไว้ด้วย {name} ไข่บางใบที่ช่วยมาเสียแล้วและไม่มีวันฟัก" },
            { "365:920524098:1334904342", "Gordunni เป็นเผ่าโอเกอร์ใหญ่ที่ยึดป่า Feralas ไว้มาก เวทมนตร์มืดซึมเข้าสู่ธาตุรอบตัว ทำลายทั้งสิ่งแวดล้อมและสัตว์ที่อาศัย\n\nหากตัดสินใจไป Feralas โปรดระวังโอเกอร์เหล่านี้ มันร้ายกาจ และหลายตนใช้เวทมนตร์มืดทรงพลังได้" },
        },
    },
    [7771] = {
        name = "Marvon Rivetseeker",
        lines = {
            { "187:760548868:1402447714", "ข้ารู้ ข้ารู้ ว่ามาอยู่กลางที่กันดาร!\n\nบ้านจริงข้าอยู่ Ratchet แต่หลังเรือเหาะตกที่นี่ ข้าคิดว่าเริ่มงานวิจัยที่ตั้งใจมาทำเสียเลยก็ดี!" },
        },
    },
    [7852] = {
        name = "Pratt McGrubben",
        lines = {
            { "123:1829510957:1740980131", "ข้าสาบาน... ถ้า Quint แอบเอาหนอนเหยื่อตกปลามาใส่ข้าอีกตัว ข้าจะโค่นต้นไม้เขาด้วยดาบที่ไม่ได้ขึ้นสนิมนักของข้า" },
            { "10:1724938855:1235015449 C 115:912995768:1837615347", "สวัสดี {class} หากกำลังหาเครื่องหนังกับอุปกรณ์ทำเครื่องหนัง ก็มาหาพาลาดินกึ่งเกษียณถูกคนแล้ว" },
        },
    },
    [7879] = {
        name = "Quintis Jonespyre",
        lines = {
            { "11:927657569:725753248 C 78:929343907:1067738545", "สวัสดี {class} วันนี้ผู้รับใช้อันต่ำต้อยแห่ง Feathermoon Stronghold ช่วยอะไรได้บ้าง?" },
        },
    },
    [7900] = {
        name = "Angelas Moonbreeze",
        lines = {
            { "7:989913233:66981971 N 37:720433227:653851590", "สวัสดี {name} มีเวลาคุยกันสักหน่อยไหม?" },
        },
    },
    [7999] = {
        name = "Tyrande Whisperwind",
        lines = {
            { "635:241303614:1708724459", "ข้ายินดีมากที่ได้พบคนจากเผ่าพันธุ์ของเจ้าในที่สุด ได้ยินเรื่อง shen'dorei กับประวัติศาสตร์ยาวนานมามาก และดีใจที่ญาติของเราได้กลับบ้านสู่ Kalimdor เสียที\n\nยอมรับว่าชาวเรามีความสัมพันธ์ที่... ซับซ้อนกับไฮบอร์น ไนต์เอลฟ์บางคนไม่ไว้ใจผู้สืบเชื้อสายไฮบอร์นอย่างคนใน High Order ของเจ้าได้ง่าย แต่ข้ารับรองว่าในฐานะแขกของเมือง เจ้าจะได้รับความเคารพอย่างที่สุด\n\nโปรดทำตัวตามสบาย ข้าสนับสนุนให้สำรวจและทำความคุ้นเคยกับวัฒนธรรมเรา เพราะในแง่หนึ่ง ก็เป็นวัฒนธรรมของเจ้าเช่นกัน" },
            { "11:927657569:725753248 C 52:187909622:45146753", "สวัสดี {class} ข้าคือ Tyrande Whisperwind มหาปุโรหิตแห่ง Elune" },
            { "635:123871350:1946399230", "ข้ายินดีอย่างยิ่งที่ในที่สุดก็ได้พบคนจากเผ่าของเจ้า ข้าได้ยินเรื่องชาว shen'dorei และประวัติศาสตร์อันยาวนานของพวกเจ้ามามาก และดีใจที่ญาติของเราได้กลับบ้านที่ Kalimdor เสียที\n\nข้ายอมรับว่าความสัมพันธ์ระหว่างชนของเรากับ Highborne นั้น... ซับซ้อน ไนต์เอลฟ์บางคนไม่ค่อยไว้ใจผู้สืบเชื้อสาย Highborne อย่างเหล่าคนใน High Order ของเจ้า แต่ข้าขอรับรองว่า ตราบใดที่เจ้าเป็นแขกของเมืองเรา เจ้าจะได้รับความเคารพอย่างเต็มที่\n\nทำตัวตามสบายเถิด ข้าอยากให้เจ้าเดินสำรวจและทำความรู้จักวัฒนธรรมของเรา เพราะในแง่หนึ่ง นี่ก็เป็นวัฒนธรรมของเจ้าด้วย" },
        },
    },
    [14637] = {
        name = "Zorbin Fandazzle",
        lines = {
            { "56:469226672:224189457", "บางทีที่นี่อาจไม่ใช่ทำเลดีที่สุดสำหรับร้านจริง ๆ..." },
            { "18:931581488:677449897 N 203:1304934270:1227931430", "สวัสดีอีกครั้ง {name}! ไม่รู้ว่าข้าจะพยายามตั้งร้านกลางที่กันดารนี้อีกนานแค่ไหน แต่ในเมื่อเจ้าเคยช่วย ข้าจะให้ดูของบางอย่างที่อาจสนใจ!" },
        },
    },
    [715] = {
        name = "Hemet Nesingwary",
        lines = {
            { "242:1073325098:1859113755", "อีกวันที่ดีในป่า! วันนี้ต้องเป็นการล่าที่ยอดเยี่ยม ข้ารู้สึกได้ เมื่อ Barnil ล้างปืนเสร็จ ข้าจะพาคณะล่าเข้าไปลึกในเถาวัลย์คดเคี้ยว ไม่เลวสำหรับทหารผ่านศึกแก่ ๆ ที่ใช้ชีวิตเกษียณใช่ไหม?" },
        },
    },
    [773] = {
        name = "Krazek",
        lines = {
            { "C 236:2078442718:1607909925", "{class} หรือ? ข้าคือ Krazek เลขาของ Baron Revilgaz รู้ทุกความเคลื่อนไหวทั้งในป่านี้และไกลออกไป สนใจราคาน้ำมันที่ Ratchet ตอนนี้ไหม? ไม่หรือ? หางานทำล่ะ? เรื่องนั้นข้าช่วยได้" },
        },
    },
    [2092] = {
        name = "Pilot Longbeard",
        lines = {
            { "43:282110154:1537876336", "เครื่องจักรล้อมเมืองคือความภูมิใจของพลขับทุกคน!" },
        },
    },
    [2496] = {
        name = "Baron Revilgaz",
        lines = {
            { "320:367783931:955460630", "ยินดีต้อนรับสู่ Booty Bay สหาย หวังว่าอยู่ในเมืองข้าจะสนุกและไร้เหตุวุ่นวาย เน้นอย่างหลัง กระหายน้ำก็มีเหล้าเหลือเฟือ ถ้าคันไม้คันมือก็มียามคุมร้านมากพอ\n\nเอาล่ะ ผู้รับใช้อันต่ำต้อยแห่ง Steamwheedle Cartel ช่วยอะไรได้? หรือที่ดีกว่า เจ้าช่วยอะไรข้าได้บ้าง?" },
        },
    },
    [2498] = {
        name = "Crank Fizzlebub",
        lines = {
            { "79:1919199050:1860433370", "อะไร อะไร?!? เราทุกคนต้องทำกำไร... และยืนเฉย ๆ ไม่ได้กำไรหรอก" },
        },
    },
    [3391] = {
        name = "Gazlowe",
        lines = {
            { "184:1132328127:917258186", "Thrall จ่ายข้ากับลูกทีมงามที่ช่วยสร้าง Orgrimmar ข้าจึงตัดสินใจตั้งท่าเรือที่นี่ เราทำธุรกิจส่วนใหญ่ผ่าน Booty Bay กับ Baron Revilgaz" },
        },
    },
    [3453] = {
        name = "Wharfmaster Dizzywig",
        lines = {
            { "31:1749881165:1852961864 N 50:996187414:2049755239", "มีอะไรให้ช่วยหรือ {name}? ถ้าไม่มี ข้าต้องไปดูสินค้าที่ขนส่งอยู่" },
        },
    },
    [4452] = {
        name = "Kravel Koalbeard",
        lines = {
            { "121:6193386:1277024455", "เข้ามาใกล้อีกหน่อย เรามีเรื่องสำคัญคุยกัน เจ้ากับข้า\n\nและบางเรื่องก็ไม่อยากให้ทุกคนได้ยิน..." },
        },
    },
    [4453] = {
        name = "Wizzle Brassbolts",
        lines = {
            { { "102:1970093079:1101157713 R 1:46:46", "101:1525055066:743979132 R 1:46:46" }, "ระวังวางเท้าหน่อยท่าน ไม่ใช่ทุกคนจะโชคดีมีความสูงสง่าอย่าง {race}" },
        },
    },
    [4454] = {
        name = "Fizzle Brassbolts",
        lines = {
            { "117:1662193445:1885938509", "อาฮ้า! เห็นนั่นไหม! ข้าว่าประแจอัตโนมัติใหม่นี้จะใช้กับแบบท่อร่วมไหลเข้าตัวใหม่ได้พอดี" },
        },
    },
    [4630] = {
        name = "Pozzik",
        lines = {
            { "86:908219552:1495210459", "วันดีสำหรับการแข่ง! โอ้ ข้าหลอกใครอยู่? ทุกวันก็ดีสำหรับการแข่งทั้งนั้น!" },
        },
    },
    [4631] = {
        name = "Wharfmaster Lozgil",
        lines = {
            { "80:85481403:2030579852 N 89:291274950:1564936020", "ข้าเห็นคนแปลก ๆ ผ่านไปมาที่ท่านี่ ระวังตัว {name} เรื่องน่าสงสัยที่เกิดตลอดทำให้ไม่เคยรู้แน่ว่าไว้ใจใครได้..." },
        },
    },
    [6169] = {
        name = "Klockmort Spannerspan",
        lines = {
            { "99:576626155:1419820952", "ข้ากำลังทำภารกิจ ภารกิจ! ภารกิจค้นหาโลหะผสมใหม่และโลหะที่แข็งขึ้น สำหรับสุดยอดสิ่งประดิษฐ์เหนือทุกสิ่ง!!" },
        },
    },
    [4155] = {
        name = "Idriana",
        lines = {
            { { "151:1838140211:1855568293", "152:1431208982:489089322" }, "ยินดีต้อนรับสู่ Bank of Darnassus เรามีบัญชีการเงินและตู้เก็บของมีค่า ท่านมีบัญชีกับเราแล้วหรือยัง?" },
            { "152:1431208982:489089322", "ยินดีต้อนรับสู่ Bank of Darnassus เรามีบัญชีการเงินและตู้เก็บของมีค่า ท่านมีบัญชีกับเราแล้วหรือยัง?" },
            { "150:1277259387:260059746", "ยินดีต้อนรับสู่ธนาคาร Darnassus เรามีบริการบัญชีเงินฝากและตู้นิรภัยสำหรับเก็บของมีค่า ท่านมีบัญชีกับเราอยู่แล้วหรือยังครับ?" },
        },
    },
    [3964] = {
        name = "Kylanna",
        lines = {
            { "202:633812643:1228319882", "ข้าดีใจที่เจ้าเชื่อมั่น แต่การสอนเจ้าต่อเกินฝีมือข้า ต้องไป Craftsmen's Terrace ใน Darnassus คุยกับไนต์เอลฟ์ Ainethil นางช่วยได้" },
            { "16:1631956695:334056280 N 44:990324613:249353244", "Ishnu-dal-dieb, {name} เจ้ามาที่นี่เพื่อแสวงหาความรู้หรือ?" },
            { "35:1994355326:715513577 N 66:967156965:2000801313", "ทั้งศิษย์และอาจารย์ต่างได้เรียนรู้ {name} ยิ่งข้าสอนเจ้า ข้าก็ยิ่งได้เรียนรู้และเข้าใจวิชาลึกซึ้งขึ้น" },
            { "14:822240972:1100135422 N 159:1965156357:1806980453", "ขอโทษด้วย {name} ข้าไม่รับสอนผู้เริ่มต้น ลองไปคุยกับ Milla Fairancora ที่ Craftsmen's Terrace ใน Darnassus นางช่วยให้เจ้าเรียนตามทันได้" },
        },
    },
    [4262] = {
        name = "Darnassus Sentinel",
        lines = {
            { { "170:1787579964:222024793", "171:268940242:1108579034" }, "อีกคนที่หลงใหลสิ่งของสินะ? ถ้าหมกมุ่นกับของมีค่า คงอยากเก็บไว้ที่ Darnassus Bank ใจกลางเมืองเรา" },
            { "209:1606847596:780387495", "เจ้ากำลังหา Vesprystus เขาดูแลฮิปโปกริฟฟ์ที่เข้าออกฐาน Teldrassil ผ่านประตูมิติทางตะวันตกของ Darnassus ไป Rut'theran Village ก็จะพบ" },
            { "161:1295713722:1188308024", "Lysheana ให้เอกสารที่ถูกต้องได้ นางอยู่ Craftsmen's Terrace ทางตะวันออกเฉียงเหนือของ Darnassus ขอให้กลุ่มของเจ้านำเกียรติสู่ไนต์เอลฟ์!" },
            { "216:645396343:151715125", "อาทิตย์ขึ้นแล้วหรือ? กลางคืนไม่เคยมีชั่วโมงพอ! Saelienne จะดูแลเจ้าดี ไปหานางที่กำลังรับรองแขกใน Craftsmen's Terrace ทางตะวันออกเฉียงเหนือของ Darnassus" },
            { "167:384986739:170170968", "ตู้จดหมายหรือ? มีจดหมายส่ง หรือได้รับมาหรือ? หวังว่าเป็นข่าวดี! มีตู้นอกธนาคารใจกลาง Darnassus" },
            { "224:1857817383:1455542776", "Alassin ดูแลสัตว์ที่พรานเป็นมิตรมาหลายร้อยปี พรานแถวนี้ต่างต้องการการดูแลจากเขา หากเจ้าก็ตามหา ไปดูที่ Cenarion Enclave" },
            { "146:1269321112:301849705", "ในยามลำบาก ดรูอิดเป็นสหายรักของคนรอบตัวได้ ถามดรูอิดคนใดใน Cenarion Enclave ก็จะบอกเหมือนกัน" },
            { "175:2140633997:1680783065", "Jocaste เคยเป็นพรานยิ่งใหญ่ที่สุดในยุคของนาง วันนี้พบได้ที่ Cenarion Enclave สอนผู้เพิ่งเริ่มเส้นทาง Hunter" },
            { "172:1110258080:1982736976", "พลังแห่ง Elune บัญชาเจ้า! พลังแห่ง Elune บัญชาเจ้า!\n\nไปเดี๋ยวนี้! หา Jandria ในโถงกลาง Temple of the Moon ทางใต้ของ Darnassus!" },
            { "32:1488414384:939405517 C 195:1283520641:1897911317", "นักเล่นแร่แปรธาตุหรือ? ไม่ยากเลย {class} Ainethil ทุ่มเททำงานจนเชี่ยวชาญที่สุดใน Craftsmen's Terrace ถ้าเป็นข้าจะรีบไปทันที รีบเลย! ไปได้แล้ว!" },
            { "322:1108114175:483457036", "เราปลูกผัก กระต่ายกินผัก หมาป่ากินกระต่าย เราฆ่าหมาป่า แล้วเอาเนื้อกับหนังจากศพ มันคือวงจรมหัศจรรย์แห่งชีวิต หรือจะเรียกอะไรก็เถอะ\n\nทีนี้ไปหา Telonis ที่ Cenarion Enclave เพื่อเริ่ม แล้วปล่อยข้าทำหน้าที่ต่อ" },
            { "279:451589292:91780389", "วัฒนธรรมเราเชื่อว่าไม่ควรปล่อยสิ่งใดสูญเปล่า เมื่อจำเป็นต้องฆ่าสัตว์ เราใช้สิ่งที่ใช้ได้เพื่อให้การสละชีวิตไม่ไร้ค่า\n\nหากอยากเรียนวิธีถลกหนังสัตว์ที่ตายอย่างถูกต้อง ไปหา Eladriel ที่ Craftsmen's Terrace" },
            { "260:52144769:1598683686", "ชุดที่ Me'Lynn ตัดทำให้คิดว่าเข็มนางได้รับพรจาก Elune เอง หากเข็มเจ้าไม่มีพรเช่นนั้น ก็ควรไปฟังคำสอนนาง หาได้ที่ The Craftsmen's Terrace ทางตะวันออกเฉียงเหนือของ Darnassus" },
            { "83:1105721635:1815558108", "ในบรรดาสถานที่มหัศจรรย์ใน Darnassus อยากให้ข้าบอกทางไปที่ใด?" },
            { "116:1331683726:1387148695", "ฝากข้าวของของเจ้าได้ที่ธนาคาร Darnassus ซึ่งอยู่กลางเมืองมหัศจรรย์ของเรา" },
            { "169:1361358093:2031147613", "ฮิปโปกริฟฟ์ของ Vesprystus จะพาเจ้าไปถึงจุดหมายรวดเร็ว ไปหาเขาที่ Rut'theran Village ผ่านประตูมิติทางตะวันตกของ Darnassus" },
            { "179:1760292240:625704874", "หากต้องการตั้งกลุ่มร่วมอุดมการณ์ จงพบ Lysheana ผู้ดูแลกิลด์ นางอยู่ Craftsmen's Terrace ทางตะวันออกเฉียงเหนือของ Darnassus" },
            { "84:2088567522:976272486", "มีตู้จดหมายนอกธนาคารที่อยู่ใจกลาง Darnassus" },
            { "129:1811963291:1280270361", "ไว้วางใจ Alassin ให้ดูแลสัตว์เลี้ยงของเจ้าอย่างดีได้ เขาอยู่ Cenarion Enclave ที่เหล่าพรานรวมตัว" },
            { "232:912418607:1540266013", "ที่ Darnassus มีครูฝึกผู้ชำนาญอาชีพตนจนสมบูรณ์ ด้วยการฝึกและทุ่มเทเนิ่นนาน ข้าจะแนะนำอาจารย์ให้ เพียงบอกเส้นทางที่เจ้าเลือก" },
            { "168:2142793136:476843641", "ท่ามกลางช่างแห่ง Darnassus มีความรู้นับพันปีเป็นประโยชน์ต่อวิชาชีพที่เจ้าเลือก บอกสิว่าสนใจงานฝีมือใดที่สุด?" },
            { "230:910446756:1852259861", "เหล่าดรูอิดเฝ้าปกป้องธรรมชาติไม่คลาดสายตา มีอัครดรูอิด Fandral Staghelm แห่ง Cenarion Enclave นำทาง เจ้าเจอเขากับครูฝึก Druid คนอื่นได้ทางเหนือของ Darnassus" },
            { "202:1495901637:1005008387", "เจ้าโชคดีที่มา Darnassus ที่มีพรานเก่งอย่าง Jocaste ในหมู่ครูฝึก ข้าแนะนำให้ไปหาและขอคำสอนที่ Cenarion Enclave" },
            { "165:9145816:1994303971", "Temple of the Moon เป็นที่อยู่ของนักบวชแห่ง Elune ที่นั่นมี Jandria กับ Lariia ผู้จะแนะนำเส้นทางนักบวชต่อให้เจ้า" },
            { "154:40109239:1547129145", "หากเดินเส้นทางโจร คนที่เจ้าหาคือ Syurna นางอยู่ Cenarion Enclave ตามทางวนลงไปในต้นไม้ตะวันตกสุด" },
            { "177:94684151:251538277", "หากปรารถนาเรียนวิชาชีพนี้จริง ข้าจะแนะนำ Ainethil นักเล่นแร่แปรธาตุชำนาญที่ Craftsmen's Terrace ทางเหนือของ Darnassus" },
            { "228:732028005:1415972060", "Alegorn เป็นพ่อครัวชั้นยอด มีเวลาหลายศตวรรษฝึกจนสมบูรณ์แบบ หากยอมสอน เจ้าควรนับว่าเป็นพร ถ้าคิดว่าคู่ควร ไปหาเขาที่ Craftsmen's Terrace" },
            { "266:1451775883:1990112812", "คมดาบไม่มีวันคมเกินไป เกราะไม่มีวันแข็งเกินไป จึงต้องมีนักลงอาคมเก่งเสมอ Taladan เป็นคนเช่นนั้น เขาสอนถักทออาคมเพื่อเสริมอาวุธและเกราะได้ ไปหาที่ Craftsmen's Terrace" },
            { "185:2030104297:1746222863", "เมื่อไม่มีผู้รักษาคอยดูบาดแผล ความรู้ปฐมพยาบาลช่วยชีวิตได้ ข้าจะไปเรียนทักษะนี้กับ Dannelor ที่ Craftsmen's Terrace" },
            { "149:283822525:1011469316", "Firodren Mooncaller เชี่ยวชาญการเก็บและความรู้สมุนไพร ตามหาเขาที่ Temple Gardens ทางตะวันตกเฉียงใต้ของ Darnassus" },
            { "241:445025528:1300762990", "ฝีมือสร้างเกราะของ Telonis ไร้เทียมทาน เจ้าควรยินดีที่เขาไม่คิดค่าเผยแพร่ความรู้แพงกว่านี้ ไปหาเขาที่ Craftsmen's Terrace ทางตะวันออกเฉียงเหนือของ Darnassus" },
            { "279:306464140:1882726294", "เมื่อสิ้นชีวิต สัตว์มอบทั้งชีวิตและการปกป้องแก่เรา หากเจ้าให้ความเคารพการสละชีวิตอย่างเหมาะสม วิชาถลกหนังอาจเหมาะ คุยกับ Eladriel ที่ Craftsman's Terrace ทางเหนือของ Darnassus เพื่อเรียนรู้เพิ่มเติม" },
            { "157:1482899640:1971970401", "หากหวังเรียนตัดเย็บ คนที่เจ้าตามหาคือ Me'Lynn นางอยู่ Craftsmen's Terrace ทางตะวันออกเฉียงเหนือของ Darnassus" },
            { "143:1619069585:1885627934", "อ้อ ผู้คนยังหลงใหลทรัพย์สมบัติไม่เลิก โชคเข้าข้างเจ้าแล้ว ตลาดประมูลอยู่ที่ Tradesman's Terrace" },
            { "176:1750381466:1967098647", "ข้าเรียนวิชาใช้อาวุธส่วนใหญ่กับ Ilyenia Moonfire ที่ Warrior's Terrace ถ้าอยากหัดใช้อาวุธชนิดใหม่ ไปหานางเถอะ" },
            { "91:428349590:1072365700 N 126:1471228105:1636714503", "Stormpike Guard ต้องการความช่วยเหลือจากเจ้าในการสู้กับตระกูล Frostwolf {name} ไปคุยกับ Brogun Stoneshield ที่ Warrior's Terrace เขาจะช่วยให้เจ้าเดินทางไป Alterac Valley ได้ สรรเสริญ Elune!" },
            { "21:1915917439:746647335 C 163:177288814:1964431740", "ถ้าเจ้าปรารถนาเช่นนั้น {class} ไปคุยกับ Keras Wolfheart ที่ Warrior's Terrace เขาเป็นตัวแทนของ The League of Arathor และจะช่วยให้เจ้าเดินทางไป Arathi Basin ได้" },
            { "46:1258315051:240105600 N 170:1583051076:757020409", "สิ่งที่เจ้ากำลังจะทำนั้นไม่ใช่เรื่องเล็ก {name} ถ้าจะไป Warsong Gulch ให้คุยกับ Aethalas ผู้บัญชาการสนามรบของ Silverwing Sentinels นางจะชี้ทางให้ ขอพรแห่งเทพีจงอยู่กับเจ้า!" },
            { "197:1603093593:610129658", "มีคนพยายามเดินตามวิถีโจรอยู่เสมอ แต่ราตรีโอบรับเพียงชาวไนต์เอลฟ์เท่านั้น หากเจ้าจะเดินบนทางแห่งเงา ไปหา Syurna ที่ Cenarion Enclave" },
            { "201:1777701053:1420450821", "Sildinair ฝึก Sentinel ที่คอยปกป้องเมืองอันเป็นที่รักของเรามาหลายคน ข้ามั่นใจว่านางฝึกคนอย่างเจ้าให้เป็นนักรบได้ ไปหานางที่ Warrior's Terrace ใกล้ทางเข้าเมือง" },
            { "254:1766212430:1596145079", "อาหารฝีมือ Alegorn อร่อยจนยอมตายได้ เขาง่วนอยู่กับการคิดเมนูใหม่ ๆ ที่ Craftsman's Terrace ถ้ายังเหลือ อย่าลืมลอง Cenarion Green สูตรของเขาล่ะ\n\nทีนี้ขอตัวก่อน ข้าต้องไปสืบว่าทำไมพักนี้กวางถึงหายไปหลายตัว" },
            { "234:1076173530:1700910698", "เจ้าชมจนข้าเขินแล้ว แต่ข้าคงไม่สนใจจริง ๆ... อะไรนะ? เจ้าถามว่าจะไปเรียนวิชาเสริมมนตร์ที่ไหนหรือ? ตายจริง น่าอายชะมัด! เอ่อ เจ้าควร... ข้าว่าเจ้าไปหา... เอ่อ... Taladan! ใช่ ไปหา Taladan ที่ Craftsmen's Terrace!" },
            { "173:1831716294:1893423236", "ตลอดเวลาหลายชั่วอายุที่ตกปลา Astaia ตกได้ของประหลาดล้ำค่ามาหลายอย่าง ลองไปหานางที่ Tradesman's Terrace แล้วขอให้นางเอามาให้ดูสักหน่อยสิ" },
            { "159:238813733:1175367126", "กำลังหัดเป็นนักเก็บสมุนไพรหรือ? ถ้าอย่างนั้นไปหา Firodren Mooncaller ที่ Temple Gardens เถอะ เขาอาจถ่ายทอดเคล็ดลับให้เจ้าบ้าง" },
            { "126:1536500603:2129287764", "เพิ่งเปิดที่ Tradesman's Terrace ถ้าเดินตามทางที่มุ่งไปทางตะวันออกเฉียงใต้จากธนาคาร ก็น่าจะหาเจอได้ง่าย" },
            { "193:1755818435:62942334", "สำหรับข้า หญ้าเย็น ๆ ที่ปกคลุม Teldrassil นอนสบายพอ ๆ กับเตียงไหน ๆ แต่เตียงที่ Saelienne จัดไว้ที่โรงเตี๊ยมใน Craftsman's Terrace ก็เหมาะกับคนที่ชอบความหรูหรา" },
            { "179:1101196119:304493608", "ตลอดหลายพันปี Ilyenia Moonfire ฝึกใช้อาวุธมาหลายชนิดจนเชี่ยวชาญ บัดนี้นางเปิดสอนให้ผู้อื่นด้วย หากอยากฝึก ไปหานางที่ Warrior's Terrace" },
            { "93:1656546011:2037377634", "มีสนามรบให้เลือกหลายแห่ง เจ้าต้องการให้ข้าชี้ทางไปหาผู้บัญชาการสนามรบคนไหน?" },
            { "38:1546128090:1593739680 C 64:1069400018:1096556987", "ข้ารู้ว่าเจ้าหมายถึงใคร {class} ไปหา Brogun Stoneshield ที่ Warrior's Terrace" },
            { "175:2040266247:2006779212", "เหล่ามนุษย์ต้องการความช่วยเหลือจากพวกเราทุกคนที่ Arathi Basin คนที่เจ้าควรไปพบชื่อ Keras Wolfheart เขาพร้อมช่วยเจ้าอยู่ที่ Warrior's Terrace" },
            { "145:294362386:1244809310", "สรรเสริญ Elune! เจ้าตามหาผู้บัญชาการสนามรบ Warsong Gulch ของเราหรือ? นางชื่อ Aethalas และรอรับเจ้าอยู่ใกล้เหล่าครูฝึกนักรบ" },
            { "152:790565074:1183392688", "เจ้าจะพบ Sildinair อยู่กับเหล่ายามที่ Warrior's Terrace นางคอยใช้สายตาอันเฉียบคมจับตาดูผืนป่า เผื่อมีศัตรูกล้าบุกเข้ามาในเมืองงามของเรา" },
            { "124:976624985:113493337", "เป็นทักษะที่ใช้เวลามาก แต่ให้ผลคุ้มค่า ไปคุยกับ Astaia ที่ Tradesman's Terrace บางทีเจ้าอาจได้เรียนรู้อะไรที่มีประโยชน์" },
            { "130:50269575:1541619508", "ควรแต่งตัวให้เรียบร้อยก่อนเข้าวิหาร แวะหาช่างตัดผมเสียหน่อยสิ ร้านอยู่ที่ Tradesman's Terrace" },
            { "178:617850640:1141175406", "อ้อ เจ้าอยากเปลี่ยนลวดลายบนตัวหรือเตรียมตัวออกล่าหรือ? ไม่มีที่ไหนดีไปกว่าที่นี่แล้ว\n\nร้านตัดผมอยู่ที่ Tradesman's Terrace ใกล้โรงประมูล" },
        },
    },
    [4730] = {
        name = "Lelanai",
        lines = {
            { "5:1932427045:59615746 C 227:934333870:1150913128", "น่าเสียดาย {class} เจ้ายังไม่ได้รับชื่อเสียงระดับ Exalted กับ Darnassus และไนต์เอลฟ์แห่ง Teldrassil เมื่อพิสูจน์ด้วยการกระทำ ไม่ใช่เพียงคำพูด ข้าจึงจะเปิดให้เลือกดูพาหนะ" },
            { "314:1024133658:393797714", "ด้วยพระเมตตาของเอลูน ข้ายินดีเสนอสัตว์ขี่ที่ดีที่สุดใน Teldrassil และอาจดีที่สุดในโลกด้วย มันคือไนต์เซเบอร์ กองทัพ Sentinel พึ่งพาสหายเหล่านี้มาหลายปี\n\nค่อย ๆ ดูไปเถิด สหาย เลือกชมแต่ละตัวให้พอใจ ข้ามั่นใจว่าท่านจะไม่ผิดหวัง" },
            { "231:1446959981:1117402240", "สวัสดี สหาย! ข้ายินดีเสนอเซเบอร์สำหรับขี่ให้ท่าน แต่ก่อนอื่นควรไปฝึกกับ Jartsam ตรงโน้นก่อน สัตว์ผู้ไม่รู้จักกลัวเหล่านี้ขี่ไม่ง่าย แต่เมื่อขี่เป็นแล้ว ท่านจะหาสหายที่ดีกว่านี้ไม่ได้" },
            { "232:1535128095:993599", "สวัสดี สหาย! ข้ายินดีขายเสือเขี้ยวดาบสำหรับขี่ให้เจ้า แต่ต้องไปฝึกกับ Jartsam ตรงนั้นก่อน สัตว์ใจกล้าพวกนี้ขี่ยาก แต่พอขี่เป็นแล้ว เจ้าจะหาเพื่อนร่วมทางที่ดีกว่านี้ยาก" },
        },
    },
    [4753] = {
        name = "Jartsam",
        lines = {
            { "97:1013458240:720023738 C 1:46:46", "ต้องมีชื่อเสียงระดับ Exalted กับไนต์เอลฟ์แห่ง Darnassus ข้าจึงจะสอนทักษะขี่พาหนะให้ {class}" },
            { "100:119830790:401316364", "ข้าสอนเคล็ดลับการขี่เสือให้เจ้าได้ ขอแค่มีทองจ่ายค่าเรียนพอ!" },
        },
    },
    [15634] = {
        name = "Priestess of the Moon",
        lines = {
            { "77:373132693:260143269", "มหาปุโรหิตออกจาก Darnassus ไม่ได้ Fandral อารมณ์เสียมาก" },
            { "19:1270205541:1575435363 C 1:46:46", "ขอ Elune สถิตกับเจ้า {class}" },
            { "58:2009594351:416627694", "Tyrande ฝากคำอธิษฐานมาให้ พระแม่จันทราประทานพรแก่เราทุกคน" },
        },
    },
    [2501] = {
        name = "\"Sea Wolf\" MacKinley",
        lines = {
            { "36:1558804384:718078288", "เฮ้! มาเล่นเกม Knuckles กันสักตาหรือ?" },
        },
    },
    [5594] = {
        name = "Alchemist Pestlezugg",
        lines = {
            { "80:638348157:360000928", "ต้องการของใช้สำหรับเล่นแร่แปรธาตุสินะ? หรือว่ามีธุระอื่นกับข้า?" },
        },
    },
    [7407] = {
        name = "Chief Engineer Bilgewhizzle",
        lines = {
            { "112:299174824:2132868183", "ข้าชื่อ Bilgewhizzle เป็นหัวหน้าวิศวกรของบริษัทน้ำ Gadgetzan มีอะไรให้ข้าช่วยหรือ?" },
        },
    },
    [7564] = {
        name = "Marin Noggenfogger",
        lines = {
            { "87:815938341:1024784554", "ใช้ชีวิตกลางทะเลทรายนี่ลำบากจริง ๆ! ข้ายืนกลางความร้อนข้างนอกนี่จนกระหายน้ำเหลือเกิน" },
            { "464:2007580493:1341378975", "พอเจ้าพูดขึ้นมา ก็ใช่ ข้าเห็นอะไรที่คิดว่าแปลกอยู่หน่อยเมื่อบ่ายวานนี้!\n\nข้ากำลังวิ่งผ่านซากเมืองโทรลล์เก่า ๆ ทางตะวันออกเฉียงใต้ของที่นี่ ที่จริงก็ไม่ได้วิ่งหรอก ออกจะกระโดดมากกว่า... ทรายมันร้อนเหลือเกิน!\n\nเอาเถอะ ตอนที่ข้ากระโดดผ่านซากเมือง ข้าสังเกตว่ามีคนตั้งค่ายอยู่ตรงนั้น ถ้าถามข้า ข้าว่าเป็นที่ตั้งค่ายที่พิลึกทีเดียว... ข้าคงเข้าไปสำรวจมากกว่านี้แล้ว หากไม่โดนอีแร้งยักษ์บ้าตัวหนึ่งไล่ออกมาเสียก่อน" },
        },
    },
    [7876] = {
        name = "Tran'rek",
        lines = {
            { "127:123152555:418060084", "บางคนสงสัยว่าพวกเรามาทำอะไรกลางทะเลทรายนี่ เอ่อ... ถ้าข้าบอก เจ้าอาจอยู่ต่อแล้วพยายามแย่งกำไรของพวกเราน่ะสิ!" },
        },
    },
    [7882] = {
        name = "Security Chief Bilgewhizzle",
        lines = {
            { "84:1955162143:1907278157", "พวกเรามาที่นี่เพื่อทำกำไร และการปล่อยให้สินค้าถูกขโมยก็ไม่ใช่วิธีทำกำไรเลย" },
        },
    },
    [7916] = {
        name = "Erelas Ambersky",
        lines = {
            { "7:989913233:66981971 N 79:1346196382:1042296807", "สวัสดี {name} ข้าฝึกและดูแลฮิปโปกริฟน้อยอยู่ที่นี่ เชิญเดินชมรอบ ๆ ได้ตามสบาย" },
            { "354:1487413276:1182362684 N 62:1437173357:726364925", "ดรูอิดใส่ใจอย่างยิ่งต่อความทุกข์ยากของสิ่งมีชีวิตทั้งปวง เมื่อพบว่านกเหล่านี้ตกอยู่ในอันตราย พวกเราจึงจัดระบบช่วยพวกมันให้พ้นจากความเสื่อมทรามของ Feralas\n\nโนมชื่อ Curgle Cranklehop เป็นผู้ดูแลเรื่องนี้ นางรวบรวมไข่แล้วส่งมาที่นี่ โดยข้าเป็นผู้ดูแลต่อ\n\nภารกิจของเรายังต้องการความช่วยเหลือเพิ่มเสมอ {name} บางทีเจ้าควรไปที่ Gadgetzan แล้วตามหา Curgle" },
        },
    },
    [7918] = {
        name = "Stone Watcher of Norgannon",
        lines = {
            { "165:114187901:1063053680", "ขอต้อนรับ ข้าคือผู้พิทักษ์ทางเข้า ข้าจะไม่อนุญาตให้เข้าสู่เขต Uldum เว้นแต่เจ้าจะรวม Plates of Uldum เข้ากับชุดแผ่นบันทึกของเจ้าแล้ว" },
            { "336:1021237976:1393725529", "หน้าที่ของข้าคือควบคุมการเข้าถึงสถานที่ Uldum ให้เหล่าผู้สร้าง ข้าจะอนุญาตให้เข้าได้ต่อเมื่อผู้ขอเข้าถึงแสดงชุดแผ่นบันทึกลำดับที่ถูกต้อง\n\nชุดแผ่นบันทึกของเจ้าในขณะนี้ยังไม่มี Plates of Uldum ซึ่งเป็นเงื่อนไขสำคัญที่สุดในการเข้าใช้งาน หากไม่มี Plates of Uldum จะไม่ได้รับอนุญาตให้เข้า" },
            { "383:526190961:928050841", "Plates of Uldum คือแผ่นบันทึกที่เหล่าผู้สร้างสังเคราะห์ขึ้นเพื่อใช้เข้าถึงเขต Uldum แผ่นเหล่านี้เก็บรักษาข้อมูลเฉพาะเกี่ยวกับกิจกรรมของเหล่าผู้สร้าง ณ ที่แห่งนี้\n\nในทางกายภาพ เส้นรอบวงของมันแทบเท่ากับชุดแผ่นบันทึกที่เจ้ามีอยู่ แต่เครื่องหมายบนแผ่นเกี่ยวข้องโดยตรงกับข้อมูลของ Uldum ต่างจากข้อมูลของเขต Uldaman" },
            { "397:1839204917:781303001", "เหล่าผู้สร้างสังเคราะห์ Plates of Uldum ไว้หลายชุดเพื่อใช้งานตามวัตถุประสงค์ที่ระบุ พวกเขาควบคุมการแจกจ่ายแผ่นบันทึกดังกล่าวสำหรับสถานที่ทั้งหมดบนโลกนี้ ขณะนี้ Azeroth ได้รับการกำหนดการมาเยือนครั้งใหม่แล้ว ดังนั้นแผ่นบันทึกเพิ่มเติมอาจเริ่มหมุนเวียนในช่วงเวลานั้น\n\nแผ่นบันทึกที่มีอยู่ถูกแจกจ่ายครบแล้วแก่ผู้ที่ผ่านระดับการอนุญาตด้านความปลอดภัยที่เหมาะสม" },
            { "410:976369846:951917945", "เหล่าผู้สร้างใช้การมาเยือนเพื่อกลับเข้าควบคุมโลกที่ตนเพาะบ่มไว้ เมื่อพลังทั้งจากภายในและภายนอกรบกวนพลวัตของโครงข่ายที่เกี่ยวข้อง เมื่อเหล่าผู้สร้างใช้วิธีการเช่นนี้ มิใช่เรื่องที่จะมองข้ามได้\n\nหากต้องการข้อมูลเพิ่มเติมเกี่ยวกับกำหนดการมาเยือนโลกนี้ โปรดตรวจสอบคลังข้อมูลที่รับผิดชอบเรื่องตารางเวลาทั้งหมดของเหล่าผู้สร้าง" },
            { "428:956541373:1942531530", "Uldum เป็นสถานวิจัยของเหล่าผู้สร้าง ในความพยายามอย่างต่อเนื่องที่จะพัฒนาชีวมณฑลของ Azeroth ข้อมูลเฉพาะเกี่ยวกับงานของพวกเขาที่เกี่ยวข้องกับ Uldum จำกัดให้เฉพาะผู้ที่มี Plates of Uldum อยู่ในชุดแผ่นบันทึกเท่านั้น\n\nคลังข้อมูลภายในเขต Uldum ถูกตั้งโปรแกรมให้ตอบเรื่องการทดลองและข้อมูลรวบรวมเฉพาะด้าน โปรดศึกษาจากคลังเหล่านั้นหากต้องการรายละเอียด" },
        },
    },
    [8579] = {
        name = "Yeh'kinya",
        lines = {
            { "194:536010862:1705523037 N 264:1305116931:1905028855", "จากการศึกษา ข้าเห็นว่าการปราบร่างอวตารของเทพ Hakkar ทำให้เขาอ่อนแอลง แต่พลังส่วนใหญ่ของเขายังคงอยู่ ซ่อนเร้น ณ ปลายสุดของ Nether\n\nเจ้าเคยปราบร่างอวตารของเขามาแล้วครั้งหนึ่ง {name} บางทีหากเจ้าปราบมันได้อีกครั้ง ก็อาจทำให้เทพตนนี้อ่อนแอลงไปอีก จนสักวันพวกเราจะเผชิญหน้ากับตัวจริงของเขาได้\n\nข้าเตรียมเวทให้เจ้าใช้อัญเชิญร่างอวตารของ Hakkar อีกครั้งภายใน Sanctum of the Fallen God เจ้าอยากเผชิญหน้ากับมันอีกหรือไม่?" },
            { "11:927657569:725753248 C 81:1388994435:185096580", "สวัสดี {class} แม้กาลเวลาและสุราจะทำให้ประสาทสัมผัสภายนอกของข้าทื่อไป แต่ดวงตาภายในของข้ายังคงทรงพลัง" },
        },
    },
    [7775] = {
        name = "Gregan Brewspewer",
        lines = {
            { "50:325991744:292476762", "สวัสดี! ข้าชื่อ Gregan มีอะไรให้ช่วยไหม?" },
            { "12:914270194:424398464 N 271:916061623:828119097", "ได้เลย {name} เจ้าดูเป็นคนไว้ใจได้... น่าเชื่อถือ! ข้ามองออกแต่ไกล...\n\nเอาล่ะ กลับมาเรื่องเดิม ต้องใช้ต้น Evoroot หนึ่งต้นเพื่อทำ Videre Elixir ส่วนผสมที่เหลือหาได้ง่าย แต่ Evoroot นี่สิ อาจหายากอยู่หน่อย" },
            { "50:873444145:976316094 N 424:384420537:1783472152", "ฮึ ๆ... เจ้าช่างซักถามจริง ๆ ว่าไหม {name}? เอาล่ะ นี่คือสิ่งที่ต้องทำ\n\nทางเหนือของที่นี่ ในซากเมืองเก่า มีโนลล์อารมณ์ร้ายชื่อ Miblon Snarltooth อาศัยอยู่ มันเฝ้า Evoroot แห่งเดียวที่ข้ารู้จัก และเฝ้าทั้งกลางวันกลางคืน! ดูเหมือนไม่เคยหลับด้วยซ้ำ!\n\nสิ่งที่เจ้าทำได้คือติดสินบนมัน ข้าขายเหยื่อที่มันเห็นแล้วน้ำลายสอให้ได้ แค่วางใกล้ตัวมัน ก็จะเบี่ยงความสนใจได้นานพอให้เจ้าคว้า Evoroot ขอให้โชคดี!" },
        },
    },
    [8496] = {
        name = "Liv Rizzlefix",
        lines = {
            { "431:1399555720:406113215", "สวัสดี! โรงช่างนี้ไม่ใช่ของข้าหรอก ไม่ใช่! แต่สักวันเมื่อฝึกเสร็จ ข้าจะเป็นนักประดิษฐ์เหมือน Marvon Rivetseeker ผู้เป็นวีรบุรุษของข้า\n\nเจ้าไม่เคยได้ยินชื่อเขาหรือ? พอดีเขาออกไปนานพอสมควร เพื่อศึกษาซากเมืองโทรลล์โบราณที่พูดถึงอยู่เรื่อย เขานั่งเรือเหาะไป... ข้าไม่แน่ใจว่าไปที่ไหนกันแน่...\n\nTanarasin? Tenkeris? Taneranisany?\n\n<Liv ส่ายศีรษะ>\n\nไม่สิ ไม่ใช่ชื่อนั้น..." },
            { "274:387892912:385277637", "สวัสดี ไม่ Marvon ไม่อยู่ที่นี่แน่นอน และคงอีกนานกว่าจะกลับ ที่จริง ข้าเริ่มเป็นห่วงเขานิดหน่อยแล้ว...\n\nหวังว่าเขาจะกลับเร็ว ๆ นี้ มีหีบใหญ่ส่งมาถึงเขา และมันหนักเกินกว่าข้าจะลากเข้ามา! ข้าจึงต้องทิ้งไว้ข้างประตู..." },
        },
    },
    [8737] = {
        name = "Linken",
        lines = {
            { "143:120797768:985878337", "มันเป็นความลับสำหรับทุกคน... รวมถึงข้าด้วย!\n\nข้าดีใจที่เจ้าพบข้า โชคดีที่ข้าไม่ได้ซ่อนอยู่ในพุ่มไม้หรือใต้ก้อนหิน ว่าไหม?" },
            { "187:1951169221:601595918", "นานมาแล้ว ระหว่างเดินทาง ข้าพบชายคนหนึ่งที่บอกว่า \"ใช้มันให้ชำนาญ แล้วเจ้าจะได้สิ่งนี้\"\n\nเจ้าคิดว่าเขาหมายถึงอะไร? ตอนนั้นข้าไม่รู้ และที่จริงตอนนี้ก็ยังไม่รู้..." },
            { "200:1182314257:400205837 N 1:33:33", "ตอนที่ข้าเดินเตร่ในปล่องภูเขาไฟหลังมาตกที่นี่ ข้าจำบางอย่างที่เคยมีคนบอกได้... \"ขึ้นไป ขึ้นไปบนภูเขาข้างหน้า\" เสียงในหัวข้ากล่าว\n\nเพราะฟังเสียงนั้น ข้าจึงมาอยู่ที่นี่ไง {name}!" },
            { "34:1801379428:1331469459 N 109:877343888:861171454", "สวัสดี! ดีใจที่เจ้ากลับมา {name} บอกที เจ้าทำเควสแรกที่ข้าให้เสร็จหรือยัง? ถ้าเสร็จแล้ว ข้าอาจมีเควสที่สองให้เจ้า..." },
            { "124:378227300:915147938", "ชื่อของข้าฟังคุ้นหูเจ้าหรือไม่? บางทีเราอาจรู้จักกันเมื่อนานมาแล้ว...\n\nข้าคิดว่าตนถูกตั้งชื่อตามบุคคลสำคัญ..." },
            { "84:644654457:1870360356", "ข้า... ข้าไม่แน่ใจจริง ๆ ว่ามาที่นี่ได้อย่างไร...\n\nเหมือนจะจำได้ว่าเดินทาง... แพ..." },
            { "42:557356278:2122879658 N 25:526582488:138337262", "จ่ายมาก่อน แล้วข้าจะพูด...\n\nอ้อ เจ้านั่นเอง {name}! ลืมเรื่องเมื่อกี้ไปเถอะ..." },
        },
    },
    [9116] = {
        name = "Eridan Bluewind",
        lines = {
            { "213:1598997713:1750217103", "คณะ Emerald Circle มุ่งเยียวยาผืนดินที่บอบช้ำของ Felwood แม้ดินแดนจะได้ชื่อตามสิ่งที่ทำให้มันเสื่อมทราม เราหวังว่าสักวันจะกำจัดความเสื่อมทรามจากที่นี่ได้ทั้งหมด" },
        },
    },
    [9117] = {
        name = "J.D. Collie",
        lines = {
            { "279:1184561549:662522497", "เจ้าคงไม่คิดว่าจะพบข้าในถ้ำนี้ใช่ไหม?\n\nข้าชื่อ J.D. และบอกเรื่องที่มาถึงที่นี่ให้เจ้าได้ไม่มาก แต่บอกได้ว่าถ้ำนี้เป็นบ้านของข้าแล้ว!\n\nข้าใช้เวลาศึกษาผลึกประหลาดที่พบได้ทั่วปล่องภูเขาไฟ" },
            { "88:558737632:1485987639 N 80:1257629251:450390370", "เพราะเจ้า ตอนนี้เราจึงไขความลับของผลึกและเสาลึกลับได้แล้ว {name} หากต้องการข้อมูลเพิ่มเมื่อไร ก็กลับมาเยี่ยมข้าอีกนะ!" },
            { "459:384316785:286371709", "เสาผลึกทางตะวันออกรับผลึกสีน้ำเงิน เหลือง และเขียว\n\nมันมุ่งใช้พลังงานที่เกิดจากผลึกสีน้ำเงินเป็นแหล่งหลัก ผลลัพธ์มีสองแบบ แบบหนึ่งเพิ่มค่า Spirit อีกแบบสร้างโล่ที่ทำความเสียหาย\n\nCrystal Force ต้องใช้ผลึกสีน้ำเงินกับสีเขียว จะเพิ่มค่า Spirit ให้เจ้า\n\nCrystal Spire ต้องใช้ผลึกสีน้ำเงินกับสีเหลือง จะสร้างโล่ที่ทำความเสียหายแก่ผู้โจมตี" },
            { "453:2068214798:495879743", "เสาผลึกทางเหนือรับผลึกสีเหลือง แดง และเขียว\n\nมันมุ่งใช้พลังงานที่เกิดจากผลึกสีเหลืองเป็นแหล่งหลัก ผลลัพธ์มีสองแบบ แบบหนึ่งสร้างความเสียหาย อีกแบบป้องกันความเสียหาย\n\nCrystal Charge ต้องใช้ผลึกสีแดงกับสีเหลือง จะสร้างระเบิดขนาดใหญ่ทำให้ศัตรูตะลึง\n\nCrystal Restore ต้องใช้ผลึกสีเหลืองกับสีเขียว จะให้ออรารักษาแก่เจ้า" },
            { "466:511253765:297001771", "เสาผลึกทางตะวันตกรับผลึกสีแดง เขียว และน้ำเงิน\n\nมันมุ่งใช้พลังงานที่เกิดจากผลึกสีแดงเป็นแหล่งหลัก ผลลัพธ์มีสองแบบ แบบหนึ่งเพิ่มการป้องกันความเสียหาย อีกแบบลดทอนการป้องกันของศัตรู\n\nCrystal Ward ต้องใช้ผลึกสีแดงกับสีเขียว จะเพิ่มค่าเกราะให้เจ้า\n\nCrystal Yield ต้องใช้ผลึกสีน้ำเงินกับสีแดง ใช้ลดค่าเกราะของเป้าหมายที่เลือกได้" },
            { "12:914270194:424398464 N 25:917204473:1258388333", "ได้เลย {name} รับนี่ไปอีก" },
        },
    },
    [9118] = {
        name = "Larion",
        lines = {
            { "131:785458900:19530596", "เฮ้อ... พวกก่อกวนทำข้ายุ่งทั้งวันทั้งคืน! เจ้าไม่เห็นมันหรือ?\n\nข้าอยากกระโดดลงท่อหนีพวกมันไปเสียจริง..." },
        },
    },
    [9270] = {
        name = "Williden Marshal",
        lines = {
            { "316:1381760766:1195507746", "สวัสดี คนแปลกหน้า ยินดีต้อนรับสู่แดนป่าอันยิ่งใหญ่แห่ง Un'Goro Crater!\n\nข้าชื่อ Williden Marshal ข้า พี่น้องของข้า และเพื่อนร่วมทาง คือคณะสำรวจ Marshal เหล่านักวิทยาศาสตร์และนักสำรวจแดนป่าอันยิ่งใหญ่ที่ยังไม่รู้จักของ Azeroth\n\nเราพบอุปสรรคอยู่บ้างที่นี่ และกำลังมองหาความช่วยเหลือ หากเจ้ามีเวลา!" },
        },
    },
    [9271] = {
        name = "Hol'anyee Marshal",
        lines = {
            { "288:289210688:1552945170", "โอ้ สวัสดี! ข้าชื่อ Hol'anyee หัวหน้านักวิทยาศาสตร์และนักชีววิทยาของคณะสำรวจ Marshal ข้ากับพี่น้องและเพื่อนร่วมทางเดินทางทั่ว Azeroth เพื่อสำรวจแดนป่าอันยิ่งใหญ่ มันน่าตื่นเต้น... แต่ เอ่อ... ข้าคิดว่าครั้งนี้เราอาจเจอความตื่นเต้นมากเกินไปหน่อย!" },
        },
    },
    [9272] = {
        name = "Spark Nilminer",
        lines = {
            { "248:1970332954:1981766042", "เห็นแก่ทุกสิ่งศักดิ์สิทธิ์และเป็นที่รัก โปรดบอกทีว่าเจ้ามาช่วยเราออกจากดินแดนที่ถูกทอดทิ้งนี่ แม้ข้าอยู่กับคณะสำรวจ Marshal ข้าก็ยอมยกฟันทองในปากให้เจ้า เพื่อได้มุดเข้าไปในกระเป๋าของเจ้าแล้วออกจากที่นี่" },
            { "112:1596785755:618517766", "ใช่ ๆ ข้ารู้ว่า Dadanga ไม่ชอบควัน แต่จากกลิ่นนั่น ดูเหมือน Dadanga ก็ไม่ชอบอาบน้ำด้วย" },
        },
    },
    [9298] = {
        name = "Donova Snowden",
        lines = {
            { "121:1694515832:575276810", "สวัสดี! อะไรพาเจ้ามา Winterspring? ดินแดนหนาวเย็นและกว้างใหญ่แห่งนี้อาจดูหม่นหมอง แต่เป็นสถานที่ที่มีความลับมากมาย..." },
        },
    },
    [9299] = {
        name = "Gaeriyan",
        lines = {
            { "37:95687136:28943576", "ได้โปรด ปล่อยวิญญาณชราให้อยู่สงบเถิด" },
            { "46:1490271524:217329606", "น้อยคนนักที่มาตามหาข้า... มีอะไรให้ข้าช่วยหรือ?" },
        },
    },
    [9618] = {
        name = "Karna Remtravel",
        lines = {
            { "62:370250714:592598445 N 299:879230342:199648022", "เจ้าเห็นสิ่งวิเศษทั้งหมดใน Un'Goro Crater แล้วหรือ {name}? มันน่าทึ่งจริง ๆ แม้ไม่เทียบเท่าของบางอย่างที่ข้าสร้างด้วยทักษะวิศวกรรม แต่สำหรับสิ่งที่เกิดตามธรรมชาติทั้งหมดที่นี่... ก็ไม่เลวเลย\n\nลุง Remtravel ของข้าชอบของเก่าอย่างสถานที่แห่งนี้ ข้ากำลังเดินตามรอยเขาอยู่บ้าง ข้าอยากค้นพบสิ่งใหม่จากวัฒนธรรมที่สาบสูญเหมือนกัน!" },
        },
    },
    [9619] = {
        name = "Torwa Pathfinder",
        lines = {
            { "11:927657569:725753248 C 444:2004862614:732512709", "สวัสดี {class} สำหรับบางคน การเป็นพรานคือวิถีชีวิตและอาชีพที่เลือก สำหรับบางคน มันเป็นงานอดิเรก เครื่องหมายแห่งความกล้า หรือพิธีผ่านสู่อีกช่วงชีวิต แล้วแต่เผ่าของตน\n\nสำหรับข้า เผ่าพันธุ์และอาชีพไม่มีความหมาย สิ่งที่ข้าเคารพคือการทดสอบจิตวิญญาณและจิตใจ การยืนหยัดต่อพลังธรรมชาติแล้วทดสอบทุกทักษะของตน คือเครื่องหมายแห่งเกียรติที่แท้จริง\n\nหากเจ้าปรารถนาจะทดสอบตนและได้รับความเคารพจากข้า ก็พูดคุยกับข้าต่อ" },
            { "39:1176176982:1075861912 N 197:10135588:760702616", "เจ้าเริ่มก้าวบนเส้นทางอันทรงเกียรติแล้ว {name} บรรพบุรุษของข้าเคารพความตั้งใจของเจ้า แต่ข้าจะยังไม่ยอมรับ จนกว่าเจ้าทำงานที่มอบหมายจนสำเร็จ\n\nเจ้ารู้ว่าต้องทำอะไร หากอยากพิสูจน์ตนเป็นพรานด้วยจิตวิญญาณ" },
            { "448:687589894:1130616508", "ravasaur ที่นี่ใน Un'Goro ดูจะเกี่ยวข้องกับแรปเตอร์แห่ง Barrens พวกมันฉลาดมาก อารมณ์รุนแรง และมีสำนึกหรือกฎการประพฤติตน ตัวที่ยิ่งใหญ่ที่สุดที่ข้าพบคือ Lar'korwi มันเป็นหนึ่งในสัตว์ร้ายอันตรายที่สุดที่ข้าเคยเห็น ในภาษา Taurahe ชื่อ Lar'korwi หมายถึง \"กรงเล็บคม\" แต่ชื่อนั้นยังบรรยายมันได้ไม่สมศักดิ์ศรี\n\nอย่าประเมิน Lar'korwi ต่ำไปหากคิดจะล่ามัน แต่ถ้าเจ้าจะทำ ข้าก็จะช่วยทุกทางที่ทำได้" },
        },
    },
    [9997] = {
        name = "Spraggle Frock",
        lines = {
            { "23:14752719:1452870833 N 131:2043472571:1431584047", "ยินดีต้อนรับสู่ที่พักพิง {name} บางคนมาที่นี่ด้วยจุดมุ่งหมาย บางคนหลงมาถึงโดยบังเอิญ... แต่ทุกคนดูมีเรื่องราวเฉพาะตัวจะบอกเล่า" },
        },
    },
    [5901] = {
        name = "Islen Waterseer",
        lines = {
            { "31:1733892400:1425272722 N 75:323939732:250857006", "เจ้ามาไกลกว่าหลายคนแล้ว {name} เคารพธาตุรอบตัว แล้วเจ้าจะไปได้ดีกว่าคนส่วนใหญ่" },
        },
    },
    [9528] = {
        name = "Arathandris Silversky",
        lines = {
            { "227:698481570:755881602", "ป่าที่เคยงดงามแห่งนี้ทุกข์ทรมานใต้คำสาปร้ายแรง! พลังเสื่อมทรามบิดชีวิตให้เป็นเพียงเงาของตัวตนเดิม หากเจ้าไม่ใช่ตัวแทนของความเสื่อมทราม บางทีอาจช่วยข้าทวง Felwood คืนได้!" },
            { "349:1778075526:555312234", "\"Darnassae?\" ดรูอิดไนต์เอลฟ์มองเจ้าอย่างคาดหวัง แต่เห็นชัดว่าเจ้าพูดสื่อสารกับนางไม่ได้ นางไม่ย่อท้อ ชี้ตัวเองแล้วยิ้ม ชี้มาที่เจ้าแล้วยิ้มอีกครั้ง สุดท้ายนางโบกมือไปตามทางเหนือหลายครั้ง บางทีนางกำลังบอกว่ามีดรูอิดที่เจ้าคุยด้วยได้อยู่ถัดขึ้นไปตามถนน?" },
            { "418:150865330:1955409323", "มีพืชใน Felwood ที่ช่วยให้พ้นความเสื่อมทรามได้ด้วยยาทาพืช Cenarion ข้ารู้วิธีทำยาจากของหลายชนิด ตามทักษะที่เจ้ามี อาจมีหลายทางเลือกให้ช่วยข้า เจ้าจะต้องใช้ Cenarion Beacon สำหรับงานที่นี่ด้วย มันเป็นอุปกรณ์ที่ช่วยให้เห็นมลทินและความเสื่อมทรามในธรรมชาติซึ่งตาเปล่ามองไม่เห็น" },
            { "340:1079945712:1408189941", "ข้าสังเกตพบพืชสี่ชนิดที่ได้รับผลจากความเสื่อมทราม ได้แก่ Songflower, Windblossom, Whipper Root และ Night Dragon ส่วน Songflower กับ Windblossom พบได้ทั่วไปใน Felwood ขณะที่ Whipper Root และ Night Dragon พบน้อยกว่า ทุกชนิดเป็นส่วนสำคัญของระบบนิเวศ Felwood" },
        },
    },
    [9529] = {
        name = "Maybess Riverbreeze",
        lines = {
            { "227:698481570:755881602", "ป่าที่เคยงดงามแห่งนี้ทุกข์ทรมานใต้คำสาปร้ายแรง! พลังเสื่อมทรามบิดชีวิตให้เป็นเพียงเงาของตัวตนเดิม หากเจ้าไม่ใช่ตัวแทนของความเสื่อมทราม บางทีอาจช่วยข้าทวง Felwood คืนได้!" },
            { "346:1708407309:231471576", "\"Taurahe?\" ดรูอิดทอเรนมองเจ้าอย่างคาดหวัง แต่เห็นชัดว่าเจ้าพูดสื่อสารกับนางไม่ได้ นางไม่ย่อท้อ ชี้ตัวเองแล้วยิ้ม ชี้มาที่เจ้าแล้วยิ้มอีกครั้ง สุดท้ายนางโบกมือไปตามทางใต้หลายครั้ง บางทีนางกำลังบอกว่ามีดรูอิดที่เจ้าคุยด้วยได้อยู่ถัดลงไปตามถนน?" },
            { "418:150865330:1955409323", "มีพืชใน Felwood ที่ช่วยให้พ้นความเสื่อมทรามได้ด้วยยาทาพืช Cenarion ข้ารู้วิธีทำยาจากของหลายชนิด ตามทักษะที่เจ้ามี อาจมีหลายทางเลือกให้ช่วยข้า เจ้าจะต้องใช้ Cenarion Beacon สำหรับงานที่นี่ด้วย มันเป็นอุปกรณ์ที่ช่วยให้เห็นมลทินและความเสื่อมทรามในธรรมชาติซึ่งตาเปล่ามองไม่เห็น" },
        },
    },
    [9620] = {
        name = "Dreka'Sur",
        lines = {
            { "10:1514315735:736932127 C 90:1892864285:456663952", "Throm-Ka {class} วันนี้ข้าอารมณ์ไม่ดี หากช่วยอะไรไม่ได้ ข้าก็อยากอยู่ตามลำพัง" },
        },
    },
    [10922] = {
        name = "Greta Mosshoof",
        lines = {
            { "15:575026390:2035692530 N 272:1809817309:582715059", "ข้าต้อนรับเจ้า {name} และ Emerald Circle ก็ต้อนรับเช่นกัน หวังว่าเราจะร่วมกันฟื้นฟูและปกป้องป่าที่เคยยิ่งใหญ่แห่งนี้ได้ หลายพลังพยายามทำลายมัน ทั้งจากภายนอก... และภายใน อย่าหลงใหลพลังที่นี่ มันมีแต่จะทำให้เจ้าเสื่อมทราม เช่นเดียวกับทั้งดินแดน" },
        },
    },
    [11016] = {
        name = "Captured Arko'narin",
        lines = {
            { "369:888845018:527793023", "หนาวเหลือเกิน... และหิว สหายผู้น่าสงสาร หวังว่าเจ้าได้พบความสงบ ข้าทนคิดถึงสิ่งที่พวกมันอาจทำกับเจ้าไม่ได้ เจ้า! เจ้าตรงนั้น! ได้โปรด ต้องช่วยข้าหนี หนึ่งในพวกมันมีกุญแจ เจ้าหามันได้ไหม? ข้ารู้ว่ามันมี หากได้มา เจ้าก็ช่วยข้าออกไปได้ Trey คงตายแล้ว แต่ยังไม่สาย! ได้โปรด เจ้าช่วยข้าได้ไหม?" },
            { "40:2127279409:573314342 N 342:1238254808:797616162 N 88:324503135:1999969610", "เจ้าช่วยข้าไว้อย่างมากแล้ว {name} ขอบคุณ อย่างน้อยตอนนี้ข้าก็บอกได้ว่าอะไรพาข้ามาที่นี่ ข้ากับ Trey Lightforge สหายเก่าแก่ มายัง Jaedenar เพื่อสืบเรื่อง Shadow Council แต่พวกมันจับเราขณะไม่ทันตั้งตัว มันพา Trey ลึกเข้า Shadow Hold แล้วขังข้าที่นี่หลังยึดอุปกรณ์ทั้งหมด... ข้ายังได้ยินเสียงกรีดร้องของเขาจากข้างล่าง {name} มัน... ฟังไม่เหมือนเสียงคน ข้าไม่รู้ว่าพวกมันทำอะไรเขา แต่จะต้องชดใช้" },
        },
    },
    [11019] = {
        name = "Jessir Moonbow",
        lines = {
            { "7:989913233:66981971 C 421:1815326914:1692695202", "สวัสดี {class} ข้าคือ Jessir Moonbow มาจาก Darnassus เพื่อตามหาสหายสองคนที่มาสืบร่องรอย Shadow Council ใน Felwood ดูเหมือนพวกชั่วที่รับผิดชอบความทุกข์มากมายของเผ่าออร์คกำลังพยายามฟื้นอำนาจ สหายทั้งสองไปดูที่ Jaedenar เพื่อพิสูจน์ให้รู้ว่าเกิดอะไรขึ้น ข้าคาดว่าจะพบพวกเขาเมื่อมาถึง แต่ตอนนี้เลยเวลามาหลายวันแล้ว" },
        },
    },
    [11554] = {
        name = "Grazle",
        lines = {
            { "458:1438676695:1638538273", "พวกเราคือผู้เหลืออยู่กลุ่มสุดท้ายของเผ่าพันธุ์เฟอร์โบลก... เผ่า Timbermaw ยังไม่เสื่อมทราม แต่เรากลับเผชิญความเป็นศัตรูจากคนนอกเช่นเดียวกัน ส่วนใหญ่ไม่เชื่อว่าเป็นไปได้... ที่จะมีเฟอร์โบลกรอดจากความเสื่อมทรามจริง ๆ... พี่น้องของข้าโกรธผู้ที่รีบสร้างศัตรู จึงโจมตีทุกคนที่เข้าใกล้และไม่ไว้ใจใคร แต่บางที หากเจ้าพยายามแสดงว่าอยู่อย่างสงบกับพวกเขา พวกเขาอาจมองเจ้าเป็นพันธมิตร" },
        },
    },
    [11556] = {
        name = "Salfa",
        lines = {
            { "109:562064428:1244792242", "พวกเรา Timbermaw ให้เจ้าผ่านที่มั่นอย่างปลอดภัยได้ แต่เจ้าต้องพิสูจน์ก่อนว่าคู่ควรกับความช่วยเหลือ" },
            { "277:1766072653:2131003146", "เฟอร์โบลก Winterfall ที่อยู่ใน Winterspring เคยเป็นพันธมิตรของเรา... แต่วันหนึ่งทุกอย่างเปลี่ยนไป คำสั่งประหลาดของหัวหน้าใหญ่ผลักให้พวกมันโจมตีทุกคนที่พบ รวมถึงเผ่าเรา ตอนนี้พวกมันแยกตัวอยู่ตามลำพัง..." },
        },
    },
    [11558] = {
        name = "Kernda",
        lines = {
            { "18:121429331:542422495 C 1:63:63", "เจ้าแสวงหาอะไร {class}?" },
        },
    },
    [15395] = {
        name = "Nafien",
        lines = {
            { "187:1667226175:973819475", "มีเพียงผู้ที่พิสูจน์แล้วว่าไม่เป็นศัตรูกับ Timbermaw จึงผ่านที่มั่นโดยไม่ต้องกลัวถูกโจมตีได้ เจ้าพยายามสร้างความไว้ใจจากเราบ้างหรือยัง คนนอก?" },
        },
    },
    [3516] = {
        name = "Arch Druid Fandral Staghelm",
        lines = {
            { "180:223937332:340746354", "หากเจ้ามาเพื่อทำให้ข้าเสียเวลา ก็เท่ากับทำให้ Cenarion Circle ทั้งหมดเสียเวลา เพื่อประโยชน์ของเจ้าเอง หวังว่าเจ้าจะไม่โง่พอทำเช่นนั้น" },
            { "357:1972483139:555379664", "ใช่ แต่หากมีทักษะ Herbalism เจ้าจะได้รับผลตอบแทนมากกว่า! เจ้าต้องดูแลและเพาะเมล็ดพิเศษ ไม่ใช่เหวี่ยงขวานสุ่มสี่สุ่มห้าหรือร่ายท่าทางใส่เงาที่ผ่านไป แม้ Evergreen Pouch ที่เจ้าจะได้รับจะช่วยให้คนไร้ฝีมือที่สุดปลูกอะไรขึ้นมาได้ แต่ผู้มีความสามารถด้านนี้จะได้ผลผลิตอุดมสมบูรณ์กว่า" },
            { "15:337260961:905808926 C 100:451337571:1629977986", "ว่ามาเร็ว ๆ {class} ข้าต้องเฝ้าดูและชี้นำการเติบโตของ Teldrassil แทบไม่มีเวลาเหลือให้คุยเล่น" },
        },
    },
    [10267] = {
        name = "Tinkee Steamboil",
        lines = {
            { "112:939068171:390338494", "Burning Steppes เป็นที่อันตราย แต่นักวิชาการอย่างข้าทำแทบทุกอย่างได้เพื่อเพิ่มพูนความรู้" },
        },
    },
    [10300] = {
        name = "Ranshalla",
        lines = {
            { "307:1631960890:492370045", "สวัสดี! ข้าเพิ่งกลับจากสำรวจซาก Kel'Theril ทางตะวันตกเฉียงใต้ ตอนนี้ตั้งใจจะศึกษาไวลด์คินที่อยู่ขึ้นไปบนสันเขานี้ใน Owl Wing Thicket\n\nได้คุยกับ Erelas Ambersky ที่ Rut'theran Village หรือยัง? เขาขอให้ข้ามาที่นี่ และบางทีอาจมีงานให้เจ้าด้วย" },
            { "14:220978170:1597880858 N 56:23445676:1066825344", "ขอบใจอีกครั้ง {name}! ข้าพอใจกับสิ่งที่เราพบมาก\n\nขอให้โชคดี!" },
            { "42:988926208:1946377713 N 58:1098307310:44130518", "ข้ากำลังเตรียมขึ้นไปบนสันเขา {name} อยากได้คนช่วยสักหน่อย จะไปกับข้าไหม?" },
        },
    },
    [10301] = {
        name = "Jaron Stoneshaper",
        lines = {
            { "160:1206521767:1574466543", "ในฐานะสมาชิก Explorers' League ข้าตามหาวัตถุโบราณในแถบนี้ กล่าวกันว่า Winterspring มีของที่เปี่ยมเวทมนตร์... ส่วนใหญ่ได้รับการเฝ้าอย่างแน่นหนา" },
        },
    },
    [10305] = {
        name = "Umi Rumplesnicker",
        lines = {
            { "19:850516176:315943426 C 245:2055955236:1146201775", "การประดิษฐ์ {class} ที่รัก ประกอบด้วยแรงบันดาลใจบรรจุขวดสองเปอร์เซ็นต์ การรับแสงแดดสี่เปอร์เซ็นต์ โอกาสที่พายุฝนฟ้าคะนองจะผ่านพ้นก่อนบ่ายแก่ ๆ หกเปอร์เซ็นต์ และ Rumplesnicker เก้าสิบสามเปอร์เซ็นต์\n\nเดี๋ยวนะ รวมได้หนึ่งร้อยหรือเปล่า? ข้ามีบันทึกอยู่แถวนี้สักแห่ง" },
            { "47:2065120090:876092619 C 25:219811003:493524945", "ข้าจะได้หัวเราะทีหลัง... แล้วพวกเขาจะเห็น! อ้าว สวัสดี {class} ข้าไม่ทันเห็นเจ้า" },
            { "76:850376234:1670230957", "ทำไมเวลาต้องใช้ Gyrochronatom ถึงไม่เคยมีวางอยู่ใกล้มือเลยนะ?" },
            { "56:2005177384:613697774", "อากาศที่นี่ดีจริง ๆ ว่าไหม?" },
        },
    },
    [10307] = {
        name = "Witch Doctor Mau'ari",
        lines = {
            { "4:1110228981:147916455 R 82:1636721160:856797353", "อา ชาว{race}... ข้ารอบรู้เรื่องโลกและวิธีสร้างเครื่องรางอันทรงพลัง" },
            { "108:913073860:20214441", "Mau'ari รู้ว่าทำไมเจ้ามาหา...\n\nนำ E'ko ที่พบในโลกมาให้ข้า แล้วข้าจะแปลงมันให้เจ้า" },
            { "335:623295331:1572997115", "Cache of Mau'ari ซ่อนความลับยิ่งใหญ่... เศษผลึกที่ใช้ทำสะท้อนพลังได้ เจ้าจึงใช้พื้นผิวมันวาวดูดพลังจากสิ่งอื่นแล้วสะท้อนกลับสู่ตัวเองได้\n\nการพกเครื่องรางในกระเป๋าช่วยให้เก็บ E'ko พลังวิญญาณจากสัตว์ที่เจ้าต่อสู้ด้วย เมื่อพบ E'ko ก็นำมาให้ Mau'ari" },
            { "369:1153942015:2002874740", "E'ko คือพลังที่สิ่งมีชีวิตแต่ละชนิดมี เครื่องรางที่ข้าทำให้ช่วยจับพลังนั้นให้อยู่ในรูปร่างที่จับต้องได้\n\nข้ารู้คาถาที่แปลง E'ko ที่เจ้าพบให้เป็น Juju\n\nจากนั้นใช้ Cache of Mau'ari สะท้อนพลังของ Juju เข้าสู่ตัวเจ้า\n\nมาสิ ลองดู นำ E'ko มาให้ Mau'ari แล้วมาสนุกกัน" },
            { "169:1465953464:1904501758", "ข้าแปลกใจมากที่คนสะเพร่าเช่นเจ้ามาถึงขั้นนี้ได้...\n\nได้ เจ้ารับเครื่องรางใหม่ได้อีกชิ้น แต่ Mau'ari ไม่พอใจสิ่งที่เจ้าทำอย่างมาก!\n\nไปได้แล้ว" },
        },
    },
    [10431] = {
        name = "Gregor Greystone",
        lines = {
            { "73:612192218:53705654", "สวัสดี สหาย ขอ Dawn คุ้มครองเจ้าให้ปลอดภัยในยามยากลำบากนี้" },
        },
    },
    [10618] = {
        name = "Rivern Frostwind",
        lines = {
            { "402:405047489:1209758751", "สวัสดี นักเดินทาง ไม่ค่อยมีใครพบข้าไกลถึงที่นี่\n\nข้าชื่อ Rivern ฝึก Winterspring Frostsaber ให้เป็นสัตว์ขี่\n\nในบรรดาเสือเขี้ยวดาบทั้งหมด พวกนี้ดุร้ายและปราบยากที่สุด ผู้ที่ได้รับความไว้ใจและยกย่องสูงสุดเท่านั้นจึงจะลองขี่ได้\n\nข้าไม่ขายสัตว์ขี่เช่นนี้ให้ใครง่าย ๆ เจ้าต้องลงแรงเพื่อให้ได้รับการยอมรับ ทั้งจากข้าและจากเหล่าเสือเอง" },
        },
    },
    [10839] = {
        name = "Argent Officer Garush",
        lines = {
            { { "439:1622089430:1113191518", "437:932564452:400658919" }, "ยินดีที่ได้พบ สหาย ข้าคือ Officer Garush สมาชิกผู้ภาคภูมิใจขององค์กรระดับโลกชื่อ Argent Dawn เราต่อสู้อย่างรวดเร็วและไร้ปรานีต่อความชั่วร้ายทุกรูปแบบที่ปรากฏใน Azeroth เราไม่ใช่องค์กรการเมือง และไม่ปรารถนาจะเป็น เรามีจุดหมายเดียว จึงนับทั้ง Horde และ Alliance เป็นสหาย สหายในการขจัดความชั่วร้าย!\n\nเพื่อ Dawn สหายของข้า!" },
        },
    },
    [10840] = {
        name = "Argent Officer Pureheart",
        lines = {
            { { "429:1504572638:737734649", "427:468270004:1693181671" }, "ยินดีที่ได้พบ สหาย ข้าคือ Officer Pureheart สมาชิกผู้ภาคภูมิใจขององค์กรระดับโลกชื่อ Argent Dawn จุดหมายเราเรียบง่าย ต่อสู้อย่างรวดเร็วและไร้ปรานีต่อความชั่วร้ายทุกรูปแบบที่ปรากฏใน Azeroth เราไม่ใช่องค์กรการเมือง และไม่ปรารถนาจะเป็น เราจึงนับทั้ง Alliance และ Horde เป็นสหาย สหายในการขจัดความชั่วร้าย!\n\nเพื่อ Dawn สหายของข้า!" },
        },
    },
    [16416] = {
        name = "Bronn Fitzwrench",
        lines = {
            { "23:845437671:750047252 N 38:44311743:1537475875", "ให้ข้าช่วยอะไร {name}? รีบหน่อย ข้าไม่มีเวลาทั้งวัน!" },
        },
    },
    [10637] = {
        name = "Malyfous Darkhammer",
        lines = {
            { "61:438572602:2103337484", "Thorium Brotherhood ไม่เสียเวลากับมดปลวก ไปให้พ้น!" },
            { "291:1606471683:1196524437", "สำหรับช่างระดับข้า ขั้นตอนนั้นง่ายมาก\n\nส่วนยากที่สุดในการสร้างของจากหนังและกระดองสัตว์ คือการหาชิ้นส่วนเหล่านั้นมา หากเจ้านำหนังสมบูรณ์จาก The Beast มาให้ ข้าสร้างของทรงพลังได้หลายชนิดจากหนังนั้น" },
            { "271:1345456122:356904139", "ข้าว่าโอกาสได้หนังเช่นนั้นคงหนึ่งในล้าน! หนังที่พบสักครั้งในชีวิต! แม้ช่างที่ฝึกฝนเคร่งครัดที่สุดก็คงพลาดหลายร้อยครั้งระหว่างถลกหนัง The Beast ก่อนจะได้ตัวอย่างสมบูรณ์" },
            { "76:1602353818:504339704", "หากเจ้านำหนังของ The Beast มาให้ข้าจริงหรือ? เอาละ... ข้าจะแสดงให้ดู..." },
        },
    },
    [11039] = {
        name = "Duke Nicholas Zverenhoff",
        lines = {
            { "11:927657569:725753248 N 51:392592061:622791124", "สวัสดี {name} ข้าคือ Duke Nicholas Zverenhoff แห่ง Argent Dawn" },
        },
    },
    [5770] = {
        name = "Nara Wildmane",
        lines = {
            { "128:1790561430:1113379265", "หากจะปกป้องธรรมชาติ เราต้องน้อมรับพลังของมัน และต้องแสดงพลังนี้ต่อผู้ที่จะทำร้ายแผ่นดิน" },
        },
    },
    [12944] = {
        name = "Lokhtos Darkbargainer",
        lines = {
            { "61:438572602:2103337484", "Thorium Brotherhood ไม่เสียเวลากับมดปลวก ไปให้พ้น!" },
            { "351:1849555351:221604939 R 1:46:46", "Thorium Brotherhood มีความรู้สร้างอาวุธและยุทโธปกรณ์ศักดิ์สิทธิ์ของ Fire Lord แต่ขาดกำลังคนหาวัสดุที่ต้องใช้\n\nข้า Lokhtos Darkbargainer ได้รับอำนาจจาก Brotherhood ให้แลกสูตรชั้นสูงกับวัสดุที่เก็บจาก Molten Core\n\nเสนอของเจ้ามา ชาว{race}" },
            { "66:419663613:942529573 R 190:464378802:24756111", "Sulfuron Ingot หรือ?!??! เป็นไปไม่ได้! ข้าต้องได้มัน! ต้องได้! ต้องได้!\n\nชาว{race} ข้าได้รับอำนาจให้เสนอข้อตกลงยิ่งใหญ่แลกกับแท่งโลหะนั่น บางทีเจ้าอยากรู้ความลับของ Hand of Ragnaros ใช่ไหม? Sulfuras ไง เจ้าโง่! ค้อนในตำนานของ Firelord" },
            { { "384:554432538:545752844", "383:665548108:1889346570", "384:1207257724:752915981", "383:2046822921:1972892992" }, "เพื่อแลกกับ Sulfuron Ingot หนึ่งแท่ง ข้ามีอำนาจมอบแบบแปลนตี Sulfuron Hammer ให้หนึ่งชุด\n\nนักผจญภัยเช่นเจ้าคงคิดว่า “จะเอาค้อนแบบนั้นไปทำไม ในเมื่อของที่มีดีกว่ามาก?”\n\nข้าขอบอกไว้ ไม่มีอะไรเหนือกว่าสิ่งที่ Sulfuron Hammer สามารถกลายเป็นได้!" },
            { "431:146928430:1224083987", "เจ้าเพียงตี Sulfuron Hammer แล้วหา Eye of Sulfuras นำทั้งสองมารวมกันก็จะได้ Sulfuras! ข้าจะไม่ถ่วงด้วยรายละเอียดว่าจะหา Eye of Sulfuras ที่ไหน อย่างไร หรือเมื่อไร ข้ามั่นใจว่าเจ้าคิดออกเอง เพียงลงนามสัญญานี้ให้ข้อตกลงผูกพัน แล้วธุรกิจเราก็เสร็จ" },
        },
    },
    [332] = {
        name = "Master Mathias Shaw",
        lines = {
            { "30:1995335174:1299478526 N 1:46:46", "ยินดีต้อนรับสู่สำนักงานใหญ่ SI:7 {name}" },
        },
    },
    [11616] = {
        name = "Nathaniel Dumah",
        lines = {
            { "373:1504080979:145703685", "นานมาแล้ว ก่อนมหาสงครามครั้งล่าสุด พ่อข้าดูแล Northridge Lumber Mill ที่นั่นคือชีวิตและสิ่งที่พ่อทุ่มเทให้ เมื่อสงครามมาเยือน แม้จะเจ็บปวดเพียงใด เราก็ต้องหนีไป Stormwind\n\nเราสูญเพื่อนและครอบครัวหลายคนในวันนั้น และข้าเจ็บปวดที่รู้ว่า Scarlet Crusade ยึดโรงเลื่อยเพื่อประโยชน์ของมัน\n\nนั่นคือเหตุผลที่ข้ากลับมา" },
        },
    },
    [1855] = {
        name = "Tirion Fordring",
        lines = {
            { "29:1629839396:1702951454 R 332:1514104199:2014981961", "เผ่าพันธุ์ไม่ได้กำหนดเกียรติ ชาว{race} ระหว่างอยู่ในไร่ข้า ขอให้จดจำและเคารพหลักนี้\n\nข้ารู้จักออร์คที่มีเกียรติเทียบอัศวินสูงส่งที่สุด และมนุษย์ที่ชั่วร้ายเทียบ Scourge เหี้ยมโหดที่สุด\n\nแต่ข้าจะไม่ทำให้เจ้าเบื่อด้วยเรื่องวัยหนุ่ม! มีงานอีกมากให้ทำ หากนั่นเป็นสิ่งที่เจ้าต้องการ" },
            { "28:209981199:125790380 R 1:46:46", "นั่งฟังเรื่องของข้า ชาว{race}" },
            { "295:327567307:1078856126", "ข้าต้องขอโทษที่บอกตัวตนไม่ตรงความจริงทั้งหมด ต้องมั่นใจว่าไว้ใจเจ้าได้ มีน้อยคนที่จะช่วยฤๅษีชราซึ่งถูกลืมโดยไม่เห็นแก่ตน\n\nเจ้าพิสูจน์ว่าเป็นหนึ่งในคนเหล่านั้น เป็นผู้ซื่อตรงและมีเกียรติ" },
            { "391:536893805:909438416 R 1:46:46", "Taelan ลูกข้ายังเป็นเด็กเมื่อข้าถูกตัดสินว่าทรยศและขับจาก Alliance ให้ใช้ชีวิตเนรเทศ ข้าเลือกอยู่ที่นี่เพื่อเฝ้าดูเขา เพื่อให้แน่ใจไม่ทางใดก็ทางหนึ่งว่าเขาจะเติบโตเป็นคนมีเกียรติ\n\nเขารับตำแหน่ง Lord of Mardenholde แทนข้าตามที่หวัง แต่ชะตากลับโหดร้าย เขาเข้าร่วม Scarlet Crusade บัดนี้เป็น Highlord ของพวกมัน ชาว{race}" },
            { "100:99715156:965689195 R 218:400142880:959306981", "จริง Scarlet Crusade เป็นสิ่งบิดเบี้ยวจาก Order of the Silver Hand\n\nต้องเชื่อข้านะ ชาว{race} Taelan เป็นคนดี เขาต้องการการชี้นำ ต้องจดจำ... จำว่าความสูงส่งและเกียรติคืออะไร ข้ารู้ว่าลึกในใจเขารู้ว่าสิ่งที่ทำผิด เจ้าจะช่วยเขาหรือไม่? ช่วยให้เขาจำได้หรือไม่?" },
        },
    },
    [5411] = {
        name = "Krinkle Goodsteel",
        lines = {
            { "20:1567896681:1342633896 N 118:1506817014:494452917", "ยินดีต้อนรับสู่ Tanaris {name} วันนี้ให้ข้าช่วยอะไร? เจ้าไม่เหมือนช่างตีเหล็ก แต่ข้ารู้ว่ารูปลักษณ์อาจหลอกตา" },
        },
    },
    [8403] = {
        name = "Jeremiah Payson",
        lines = {
            { "22:797679466:679796205", "อยากซื้อแมลงสาบไหม?" },
        },
    },
    [10667] = {
        name = "Chromie",
        lines = {
            { "13:1911146197:485773127 N 471:403360870:2084138305", "สวัสดี {name} ข้ามีนาม Chronormu แต่เรียก Chromie ก็ได้ ข้าไม่ขัดข้องกับความสนิทสนมเช่นนั้น\n\nถามว่ารู้ชื่อเจ้าได้อย่างไรหรือ? ข้าเป็นหนึ่งในฝูงมังกรสีบรอนซ์ เชื่อมโยงกับการขึ้นลงของกระแสเวลาชั่วนิรันดร์ จะว่าเราเคยพบกันแล้วก็ได้ และเราจะพบกันอีกด้วย\n\nหวังว่ารูปลักษณ์ที่ข้าเลือกจะไม่รบกวนใจ แม้ได้รับหน้าที่เฝ้าสถานที่เศร้าหมอง ข้าก็เลือกไม่จมอยู่กับความเศร้าของที่นั้น" },
            { "18:395899233:276404090 N 298:1538255320:576086375", "สวัสดีอีกครั้ง {name} ข้าสัมผัสว่ากระแสเวลายังถูกคุกคามจากพลังแข็งแกร่ง ฝูงมังกรสีบรอนซ์ยินดีรับความช่วยเหลือต่อเนื่องของเจ้าเสมอ\n\nแม้อดีตถูกกำหนดไว้ อนาคตเปลี่ยนเสมอ การตัดสินใจของเจ้าในปัจจุบันช่วยชี้นำความเปลี่ยนแปลงนั้น" },
        },
    },
    [10739] = {
        name = "Mulgris Deepriver",
        lines = {
            { { "258:821993391:1719572723", "256:1389291405:690346375", "256:568588809:1879774500", "254:1697678042:1106062290" }, "ได้โปรด ช่วยข้า สหาย...\n\nอีกไม่นานข้าจะจากโลกนี้ แม้กำลังทุกข์ทรมาน ข้ารู้ว่ามันจะจบเมื่อจากไป แต่สัตว์ป่า สหาย... สัตว์ป่าก็ทุกข์ และไม่รู้หนทางหลุดพ้น ข้าขอความช่วยเหลือด้วยลมหายใจสุดท้าย" },
            { "39:1073167357:1920983885 R 364:1116354722:1153896614", "ใช่ ข้าพูดภาษาที่เจ้าเข้าใจ ชาว{race} เราไม่ใช่สัตว์ แต่พวกเจ้าส่วนมากยังปฏิบัติต่อเราเช่นนั้น! ทว่าความต่างของเราเล็กน้อยเมื่อเทียบโศกนาฏกรรมที่เกิดกับแผ่นดิน โปรดวางความต่างแล้วฟังคำขอสุดท้าย\n\nข้ามาเพื่อเยียวยาเท่าที่ทำได้ แต่ทุกอย่างจะสูญเปล่าหากเจ้าไม่ช่วย ข้าขอความช่วยเหลือด้วยลมหายใจสุดท้าย" },
            { "151:1070554804:1664932613", "\"...\"\n\nร่างดรูอิดทอเรนนิ่งไม่ไหวติง ดูเหมือนในที่สุดเขาจากโลกนี้ไปสู่ภพหน้าที่เฝ้ารอแล้ว" },
        },
    },
    [10778] = {
        name = "Janice Felstone",
        lines = {
            { "31:1823615133:592151499", "ชู่ว์... ได้กลิ่นอะไรไหม?" },
            { "48:694845988:1938412867", "เกิดอะไรขึ้นกับทุกคน? ข้ารู้สึก... หนาว..." },
            { "27:1242954736:363170345", "John ที่รัก เจ้าอยู่ไหน?" },
            { "58:1141890244:2121667457", "ข้ามีอีกมากต้องทำ... มากเหลือเกิน ก่อนโรคระบาดมา..." },
            { "43:1809646:1186484519", "เวลาข้าใกล้หมดแล้ว... เวลาของพวกเราทุกคน..." },
            { "273:488727512:113208937", "วิญญาณมองเจ้าด้วยความสมบูรณ์พร้อมและการรับรู้อย่างที่ไม่เคยมีมาก่อน\n\n\"ข้ารู้สึกเหมือนภาระหนักถูกยกจากวิญญาณ อีกไม่นานจะได้พักสงบชั่วนิรันดร์ บัดนี้ข้ารู้แล้ว และรอเวลานั้นอย่างอดทน\n\nขอบใจ คนแปลกหน้า\"" },
        },
    },
    [10781] = {
        name = "Royal Overseer Bauhaus",
        lines = {
            { "371:773613801:1252875630", "ข้าเป็นเจ้าหน้าที่เมือง ทำงานสำมะโน Undercity ตั้งแต่หลุดพ้น Scourge เราพยายามเก็บทะเบียนประชากรให้ถูกต้อง ด้วยวิธีอาร์เคนและการฝึกจิตอย่างเข้มงวด ข้าจึงเข้าถึงทะเบียนได้ หากมีธุระตามนั้นก็เชิญ ว่าไปเจ้าก็น่าจะรู้อยู่แล้วว่ามีหรือไม่" },
        },
    },
    [10782] = {
        name = "Royal Factor Bathrilor",
        lines = {
            { "341:1284450221:200391454", "ยินดีต้อนรับสู่ Stormwind! ข้าเป็นเจ้าหน้าที่เมือง ช่วยประชาชนผ่านสำนักสำมะโน หากกำลังหาคนเจาะจง ข้าอาจช่วยได้ ด้วยวิธีอาร์เคนและการฝึกจิตอย่างเข้มงวด ข้าจึงเข้าถึงทะเบียนเหล่านี้\n\nหากมีธุระกับข้าก็เชิญ!" },
        },
    },
    [10837] = {
        name = "High Executor Derrington",
        lines = {
            { "28:257258920:2091449038 C 418:405330890:1801017672", "ยินดีต้อนรับสู่แนวหน้า {class} นักการเมืองอาจวางอุบายกันเอง แต่ที่นี่ไม่มีความสบายเช่นนั้น นี่คือ Bulwark เราสู้เพื่ออยู่รอดทุกวัน\n\nหากมาหาโอกาสพิสูจน์ตนเป็นวีรชน ที่นี่มีมากมาย โดยเฉพาะเมื่อเรารุกเข้า Andorhal และเผชิญพลังมุ่งร้ายที่ควบคุม Scourge ที่นั่น" },
        },
    },
    [10838] = {
        name = "Commander Ashlam Valorfist",
        lines = {
            { "28:257258920:2091449038 C 418:131494116:496966342", "ยินดีต้อนรับสู่แนวหน้า {class} ราชอาณาจักร Stormwind พร้อมความช่วยเหลือจากพันธมิตร ส่งข้ามาต้านภัย Scourge ที่เพิ่มขึ้น ที่ Chillwind Point เราสู้เพื่ออยู่รอดทุกวัน\n\nหากมาหาโอกาสพิสูจน์ตนเป็นวีรชน ที่นี่มีมากมาย โดยเฉพาะเมื่อเรารุกเข้า Andorhal และเผชิญพลังมุ่งร้ายที่ควบคุม Scourge ที่นั่น" },
        },
    },
    [10856] = {
        name = "Argent Quartermaster Hasana",
        lines = {
            { "29:2004685490:638421467 C 466:1393795557:722405537", "Argent Dawn ขอคำนับเจ้า {class} ข้าคือ Hasana หนึ่งในเจ้าหน้าที่ไม่กี่คนที่ได้รับอนุญาตให้จัดหาอุปกรณ์และยุทโธปกรณ์แก่ Dawn\n\nขณะต่อสู้ความชั่วภายใต้ตราเราและสะสมความเคารพไว้ใจ เจ้าจะได้ Valor Token จาก Officer Garush เหรียญใช้สองอย่าง เพิ่มชื่อเสียงในหมู่เรา หรือใช้จ่ายเพื่อรับของพิเศษ\n\nเมื่อชื่อเสียงกับ Dawn สูงขึ้น จะมีของให้เจ้ามากขึ้น" },
        },
    },
    [10857] = {
        name = "Argent Quartermaster Lightspark",
        lines = {
            { "29:2004685490:638421467 C 471:280002067:1144506816", "Argent Dawn ขอคำนับเจ้า {class}! ข้าชื่อ Lightspark เป็นเจ้าหน้าที่เสบียงและยุทโธปกรณ์ที่ Dawn อนุญาต\n\nขณะต่อสู้ความชั่วภายใต้ตราเราและสะสมความเคารพไว้ใจ เจ้าจะได้ Valor Token จาก Officer Pureheart เหรียญใช้สองอย่าง เพิ่มชื่อเสียงในหมู่เรา หรือใช้จ่ายเพื่อรับของพิเศษ\n\nเมื่อชื่อเสียงกับ Dawn สูงขึ้น จะมีของให้เจ้ามากขึ้น" },
        },
    },
    [10879] = {
        name = "Harbinger Balthazad",
        lines = {
            { "118:635693023:854297845", "สวัสดีและยินดีต้อนรับ วีรชน! ข้ามีข่าวล่าสุดจากทั้งสองทวีปและดินแดนไกลโพ้นมาให้พิจารณา" },
        },
    },
    [10880] = {
        name = "Warcaller Gorlach",
        lines = {
            { "118:635693023:854297845", "สวัสดีและยินดีต้อนรับ วีรชน! ข้ามีข่าวล่าสุดจากทั้งสองทวีปและดินแดนไกลโพ้นมาให้พิจารณา" },
        },
    },
    [10881] = {
        name = "Bluff Runner Windstrider",
        lines = {
            { "118:635693023:854297845", "สวัสดีและยินดีต้อนรับ วีรชน! ข้ามีข่าวล่าสุดจากทั้งสองทวีปและดินแดนไกลโพ้นมาให้พิจารณา" },
        },
    },
    [11053] = {
        name = "High Priestess MacDonnell",
        lines = {
            { { "79:1274232257:212032397", "78:1794542519:506244199" }, "ถึงเวลาแล้ว สหายร่วมรบของข้า ที่จะชิงราตรีคืนจาก Scourge!" },
            { "384:399701779:262271890", "เมื่อเปิดหม้อต้มได้ เราก็ปล่อยสารต้านสู่สภาพแวดล้อมได้แล้ว ให้ Scourge ได้ลิ้มรสยาของตัวเองเสียบ้าง!\n\nถาม Alchemist Arbington เรื่องสารที่ต้องใช้ในหม้อ ส่วนข้าจะดูแลรายงานภาพรวมความคืบหน้าในการพลิกโรคระบาดต้าน Scourge!" },
            { "193:1532782804:919136196", "โรคระบาด Scourge ยังครอบงำพื้นที่ เรายังต้องทำอีกมากก่อนมันจะเปลี่ยนพอส่งผลต่อพวกมัน รวบรวมทรัพยากรที่ต้องใช้แล้วช่วยงานสงคราม!" },
            { "152:659273586:593058360", "โรคระบาด Scourge ใกล้ถึงจุดพลิกแล้ว บ่อนทำลายหม้ออีกไม่กี่ครั้งก็จะพาเราข้ามจุดนั้น! อย่าลืมช่วยทำส่วนของเจ้า!" },
            { "145:1531513827:1577290390", "เราเริ่มพลิกโรคระบาด Scourge ให้ต้านพวกมันแล้ว แต่การควบคุมยังเปราะบางมาก! ช่วยอุดมการณ์ด้วยการบ่อนทำลายหม้อของมัน!" },
            { "198:91244077:1317673211", "เรากำลังได้เปรียบ Scourge โรคระบาดที่เปลี่ยนแล้วจะส่งผลต่อพวกมันอย่างน้อยอีกหนึ่งวันเต็ม! แต่เราต้องรักษาความได้เปรียบ อย่าลืมทำลายแผนหม้อต้มเมื่อมีโอกาส" },
        },
    },
    [11055] = {
        name = "Shadow Priestess Vandis",
        lines = {
            { { "79:1274232257:212032397", "78:1794542519:506244199" }, "ถึงเวลาแล้ว สหายร่วมรบของข้า ที่จะชิงราตรีคืนจาก Scourge!" },
            { "383:1211431862:192504665", "เมื่อเปิดหม้อต้มได้ เราก็ปล่อยสารต้านสู่สภาพแวดล้อมได้แล้ว ให้ Scourge ได้ลิ้มรสยาของตัวเองเสียบ้าง!\n\nถาม Apothecary Dithers เรื่องสารที่ต้องใช้ในหม้อ ส่วนข้าจะดูแลรายงานภาพรวมความคืบหน้าในการพลิกโรคระบาดต้าน Scourge!" },
            { "193:1532782804:919136196", "โรคระบาด Scourge ยังครอบงำพื้นที่ เรายังต้องทำอีกมากก่อนมันจะเปลี่ยนพอส่งผลต่อพวกมัน รวบรวมทรัพยากรที่ต้องใช้แล้วช่วยงานสงคราม!" },
            { "152:659273586:593058360", "โรคระบาด Scourge ใกล้ถึงจุดพลิกแล้ว บ่อนทำลายหม้ออีกไม่กี่ครั้งก็จะพาเราข้ามจุดนั้น! อย่าลืมช่วยทำส่วนของเจ้า!" },
            { "145:1531513827:1577290390", "เราเริ่มพลิกโรคระบาด Scourge ให้ต้านพวกมันแล้ว แต่การควบคุมยังเปราะบางมาก! ช่วยอุดมการณ์ด้วยการบ่อนทำลายหม้อของมัน!" },
            { "198:91244077:1317673211", "เรากำลังได้เปรียบ Scourge โรคระบาดที่เปลี่ยนแล้วจะส่งผลต่อพวกมันอย่างน้อยอีกหนึ่งวันเต็ม! แต่เราต้องรักษาความได้เปรียบ อย่าลืมทำลายแผนหม้อต้มเมื่อมีโอกาส" },
        },
    },
    [11056] = {
        name = "Alchemist Arbington",
        lines = {
            { "53:1751527816:1883998355", "งานนี้ไม่คุ้มกับค่าจ้างปีละหนึ่งหมื่นหกพันห้าร้อยเลยจริง ๆ" },
            { "9:1602365759:1719266275 N 455:1173412475:2122064007", "เอาละ {name} มาจัดการหม้อต้มกัน! หากจะเก็บส่วนประกอบที่ต้องใช้ รับ Vitreous Focuser จากข้า เจ้าต้องพกไว้เพื่อมองเห็นทรัพยากรจาก Scourge ที่ใช้เปลี่ยนหม้อเหล่านั้น\n\nต้องใช้ Arcane Quickener อีกหนึ่งชุดด้วย มันไม่ถูกและไม่คงตัว เมื่อได้มาแล้วมีเวลาใช้เพียงสามสิบนาทีก่อนหมดอายุ คิดให้ดีก่อนซื้อ" },
            { "359:569892403:1176651755", "จากตัวอย่างพิษที่เจ้านำมา เราคิดว่าต้องใช้ Arcane Quickener หนึ่งชุด, Osseous Agitator หกชิ้น และ Runecloth สี่ผืน พก Vitreous Focuser แล้วเก็บ Agitator จากอันเดดโครงกระดูกใน Plaguelands!\n\nเมื่อมีครบ เจ้าก็น่าจะใส่สารต้านในหม้อนั้นได้" },
            { "377:741913543:1670503042", "จากตัวอย่างพิษที่เจ้านำมา เราคิดว่าต้องใช้ Arcane Quickener หนึ่งชุด, Somatic Intensifier ห้าชิ้น และ Runecloth สี่ผืน พก Vitreous Focuser แล้วเก็บ Intensifier จากอันเดดซอมบีหรือกูลใน Plaguelands!\n\nเมื่อมีครบ เจ้าก็น่าจะใส่สารต้านในหม้อนั้นได้" },
            { "376:1794570581:657481215", "จากตัวอย่างพิษที่เจ้านำมา เราคิดว่าต้องใช้ Arcane Quickener หนึ่งชุด, Ectoplasmic Resonator สี่ชิ้น และ Runecloth สี่ผืน พก Vitreous Focuser แล้วเก็บ Resonator จากอันเดดเรธและภูตผีใน Plaguelands!\n\nเมื่อมีครบ เจ้าก็น่าจะใส่สารต้านในหม้อนั้นได้" },
        },
    },
    [11057] = {
        name = "Apothecary Dithers",
        lines = {
            { "110:1233591697:916259889", "ลมแรงกำลังมา ข้ารู้ได้จากอาการปวดเข่าที่ไร้เนื้อหุ้ม หวังว่าเราจะไม่ติดอยู่ในนั้น" },
            { "9:1602365759:1719266275 N 455:1173412475:2122064007", "เอาละ {name} มาจัดการหม้อต้มกัน! หากจะเก็บส่วนประกอบที่ต้องใช้ รับ Vitreous Focuser จากข้า เจ้าต้องพกไว้เพื่อมองเห็นทรัพยากรจาก Scourge ที่ใช้เปลี่ยนหม้อเหล่านั้น\n\nต้องใช้ Arcane Quickener อีกหนึ่งชุดด้วย มันไม่ถูกและไม่คงตัว เมื่อได้มาแล้วมีเวลาใช้เพียงสามสิบนาทีก่อนหมดอายุ คิดให้ดีก่อนซื้อ" },
            { "359:569892403:1176651755", "จากตัวอย่างพิษที่เจ้านำมา เราคิดว่าต้องใช้ Arcane Quickener หนึ่งชุด, Osseous Agitator หกชิ้น และ Runecloth สี่ผืน พก Vitreous Focuser แล้วเก็บ Agitator จากอันเดดโครงกระดูกใน Plaguelands!\n\nเมื่อมีครบ เจ้าก็น่าจะใส่สารต้านในหม้อนั้นได้" },
            { "377:741913543:1670503042", "จากตัวอย่างพิษที่เจ้านำมา เราคิดว่าต้องใช้ Arcane Quickener หนึ่งชุด, Somatic Intensifier ห้าชิ้น และ Runecloth สี่ผืน พก Vitreous Focuser แล้วเก็บ Intensifier จากอันเดดซอมบีหรือกูลใน Plaguelands!\n\nเมื่อมีครบ เจ้าก็น่าจะใส่สารต้านในหม้อนั้นได้" },
            { "376:1794570581:657481215", "จากตัวอย่างพิษที่เจ้านำมา เราคิดว่าต้องใช้ Arcane Quickener หนึ่งชุด, Ectoplasmic Resonator สี่ชิ้น และ Runecloth สี่ผืน พก Vitreous Focuser แล้วเก็บ Resonator จากอันเดดเรธและภูตผีใน Plaguelands!\n\nเมื่อมีครบ เจ้าก็น่าจะใส่สารต้านในหม้อนั้นได้" },
        },
    },
    [11286] = {
        name = "Magistrate Marduke",
        lines = {
            { "51:1867675374:1240345231", "บางคนได้รับการละเว้นจากความปวดร้าวที่ความทรงจำมอบให้" },
            { "378:176584790:1558823255", "Cult of the Damned แผ่ขยายมากแล้ว แทบทุกเมือง ทั้งเมืองหลวง หมู่บ้านเล็กและกระท่อมของ Horde กับ Alliance ต่างมีสมาชิกลัทธิซ่อนในหมู่ประชาชน\n\nอย่าตกใจขนาดนั้น ลัทธิสวมเครื่องแบบเฉพาะพิธีกรรมและงานพิธี เป็นไปได้มากว่าเจ้าเคยพบคนหนึ่งระหว่างผจญภัยโดยไม่รู้ตัว" },
            { "313:1706198064:1491536278 R 38:49938260:1586794009", "อย่างนั้นหรือ? พวกมันทำเช่นนี้มาเสมอ อะไรมีค่ากับ Kel'Thuzad และกองทัพ Scourge ที่ขยายไม่หยุดมากกว่ากัน? สาวกมีชีวิตผู้คลั่งไคล้ที่แทรกซึมสังคมแล้วปล่อยโรคระบาดฆ่านับพัน หรือทหารอันเดดเพียงตัวเดียว? เจ้าคงไม่ทึบถึงเพียงนั้น\n\nใช่ ชาว{race} พวกมันใช้ชีวิต ทำงาน และวางแผนอยู่ท่ามกลางพวกเจ้า" },
            { "278:1613711080:446605124", "หยุดหรือ ไม่ ชะลอหรือ อาจได้\n\nScholomance เป็นแหล่งฝึกและศึกษาหลักของพวกมัน สมาชิกกระจายจากที่นั่น แล้วสุดท้ายเข้าสู่สังคมเรา\n\nนั่นคือเหตุที่ต้องโจมตีต้นตอ หัวใจของ Cult of the Damned!" },
            { "11:1019086642:213467837 R 299:1774403318:1874061725", "ใจเย็น ชาว{race} ผู้ที่เจ้าต้องฆ่าตายอยู่แล้ว ฆ่าซ้ำไม่มีประโยชน์ มีวิธีทำลายลิชจริง ๆ น้อยมาก และไม่มีวิธีใดที่เจ้าหรือข้าทำได้ นั่นคือเหตุที่ข้ามีแผน แผนที่จะส่งผลต่อลัทธิอย่างชัดเจนและแท้จริง" },
            { "134:247177739:200895413", "ง่ายมาก ชิงพลังจากลิช Ras Frostwhisper เปลี่ยนมันกลับเป็นผู้มีอายุขัย แล้วสังหารให้สิ้นซาก" },
            { "449:1085792454:1576916018", "อา ข้าคงรีบเล่าเกินไป Ras Frostwhisper คือผู้ดูแลโรงเรียนนี้ รับผิดชอบฝึก Dark Master ทุกคน เป็นนายทหารรองและศิษย์คนโปรดของ Kel'Thuzad เขาเคยเป็นจอมเวทพเนจรแห่ง Stromgarde ผู้ใช้เวทนอกสังกัดที่ไม่เคยฝึกอย่างเป็นทางการจาก Dalaran\n\nเมื่อ Kel'Thuzad เปิดลัทธิ Ras เป็นคนกลุ่มแรกที่เข้าร่วม เขารู้ว่าจะพบความเป็นอมตะผ่านเวทมืด" },
            { "186:1901095312:975503223", "และเขาก็พบมันจริง เมื่อเลื่อนตำแหน่งในลัทธิอย่างรวดเร็ว Lich King เองมอบความเป็นอมตะให้ จึงกำเนิด Ras Frostwhisper ผู้เป็นลิช\n\nตอนนี้เข้าใจหรือยัง?" },
            { "95:1674555437:1035792385", "ดี เพื่อทำตามแผน เราต้องสร้าง Lifestone ก่อน เจ้าพร้อมลงมือหรือไม่?" },
        },
    },
    [11610] = {
        name = "Kirsta Deepshadow",
        lines = {
            { "13:2145986266:1441534531 N 201:1913779978:1852754860", "สะ... สวัสดี {name} ขอโทษที ข้ากำลังฟื้นจากบาดแผล\n\nทหาร Scarlet Crusade พวกนั้นแกร่งกว่าที่ข้าคิด เกือบฆ่าข้าได้\n\nเจ้าก็ควรระวัง ข้าไม่อยากเห็นเจ้าถูกจู่โจมไม่ทันตั้งตัว" },
        },
    },
    [11615] = {
        name = "Mickey Levine",
        lines = {
            { "256:2072469465:1751767268", "ครอบครัวข้าทำงานที่ Northridge Lumber Mill ในดินแดนที่บัดนี้คือ Western Plaguelands พวกเขาทุ่มเทให้ตระกูล Dumah แต่ตอนนี้ Scarlet Crusade ยึดทั้งโรงเลื่อยและ Hearthglen!\n\nข้าจะไม่พักจนกว่าสาวกคลั่งพวกนั้นจะถูกกวาดจาก Azeroth" },
        },
    },
    [11872] = {
        name = "Myranda the Hag",
        lines = {
            { "52:348931402:820606805", "ยามนี้อันตราย นักผจญภัย จงย่างเท้าอย่างระวัง" },
            { "253:748323831:1361824685", "ต้องการภาพลวงหรือไม่?\n\nหากภาพลวงหมดฤทธิ์ระหว่างภารกิจ กลับมาหาข้า ข้าจะปลอมตัวให้ใหม่\n\nหากพลาดพลั้ง อย่ายอมแพ้! กลับมาหาข้า ข้าจะช่วยจนเจ้าทำเป้าหมายสำเร็จ" },
        },
    },
    [11036] = {
        name = "Leonid Barthalomew the Revered",
        lines = {
            { "41:1253658213:739670688", "ขอให้เราพบหนทางรอดผ่านความรู้" },
        },
    },
    [2198] = {
        name = "Crier Goodman",
        lines = {
            { "118:635693023:854297845", "สวัสดีและยินดีต้อนรับ วีรชน! ข้ามีข่าวล่าสุดจากทั้งสองทวีปและดินแดนไกลโพ้นมาให้พิจารณา" },
            { "26:1373816403:526297297 C 73:201257873:155743309", "เรื่องราวของเจ้ามาถึงก่อนตัวเสียอีก {class} หากต้องการ ข้าช่วยให้เจ้าเขียนเรื่องราวนั้นขึ้นใหม่ได้" },
        },
    },
    [10877] = {
        name = "Courier Hammerfall",
        lines = {
            { "118:635693023:854297845", "สวัสดีและยินดีต้อนรับ วีรชน! ข้ามีข่าวล่าสุดจากทั้งสองทวีปและดินแดนไกลโพ้นมาให้พิจารณา" },
        },
    },
    [10878] = {
        name = "Herald Moonstalker",
        lines = {
            { "118:635693023:854297845", "สวัสดีและยินดีต้อนรับ วีรชน! ข้ามีข่าวล่าสุดจากทั้งสองทวีปและดินแดนไกลโพ้นมาให้พิจารณา" },
        },
    },
    [11033] = {
        name = "Smokey LaRue",
        lines = {
            { "32:1109634237:795086363 R 1:46:46", "ข้าคือสิ่งที่เจ้าเรียกว่านายทุน ชาว{race}" },
        },
    },
    [11038] = {
        name = "Caretaker Alen",
        lines = {
            { "52:1159530406:201862356", "พวกเขาส่งศพให้ข้า ข้าก็โยนลงหลุม" },
        },
    },
    [11063] = {
        name = "Carlin Redpath",
        lines = {
            { "171:644430262:1463083689", "เราทุกคนเคยเห็นโศกนาฏกรรมเลวร้าย แต่ต้องไม่ปล่อยให้มันลากสู่ความสิ้นหวัง\n\nจงเก็บความทรงจำไว้ใกล้ใจ เพื่อสักวันจะได้ชำระสะสาง" },
        },
    },
    [11536] = {
        name = "Quartermaster Miranda Breechlock",
        lines = {
            { "11:927657569:725753248 C 479:1669791900:967320952", "สวัสดี {class} ข้าคือ Miranda Breechlock หนึ่งในเจ้าหน้าที่เสบียงและยุทโธปกรณ์ไม่กี่คนที่ Dawn อนุญาต\n\nขณะต่อสู้ความชั่วภายใต้ตราเราและสะสมความเคารพไว้ใจ เจ้าจะได้ Valor Token จาก Duke Zverenhoff เหรียญใช้สองอย่าง เพิ่มชื่อเสียงในหมู่เรา หรือใช้จ่ายเพื่อรับของพิเศษ\n\nเมื่อชื่อเสียงกับ Dawn สูงขึ้น จะมีของให้เจ้ามากขึ้น" },
            { "11:2058321537:485339272 N 72:210856164:1653110866", "ได้สิ {name} เพียงบอกว่าอยากรู้เรื่องชื่อเสียงระดับใด" },
            { "11:2058321537:485339272 N 293:1040060378:282010125", "ได้สิ {name}\n\nนักผจญภัยที่ Dawn มองว่าเป็น Friendly ต้องส่งตรารวม 60 อันเพื่อรับของชั้นเยี่ยม หากอยากได้ของทรงพลังยิ่งกว่า ต้องส่งรวม 220 อัน\n\nยอมรับว่าราคาสูงสำหรับผู้ที่ Dawn ยังไม่โปรดปราน" },
            { "11:2058321537:485339272 N 286:350619575:225647950", "ได้สิ {name}\n\nนักผจญภัยที่ Dawn มองว่าเป็น Honored ต้องส่งตรารวม 40 อันเพื่อรับของชั้นเยี่ยม หากอยากได้ของทรงพลังยิ่งกว่า ต้องส่งรวม 150 อัน\n\nยอมรับว่าราคายังสูง แม้เป็นผู้ได้รับเกียรติในหมู่ Dawn" },
            { "11:2058321537:485339272 N 354:1557946346:992300851", "ได้สิ {name}\n\nนักผจญภัยที่ Dawn มองว่าเป็น Revered ต้องส่งตรารวม 14 อันเพื่อรับของชั้นเยี่ยม หากอยากได้ของทรงพลังยิ่งกว่า ต้องส่งรวม 90 อัน\n\nผู้เป็น Revered กับ Dawn จะพบว่าของชั้นเยี่ยมราคาสมเหตุผล! ส่วนของทรงพลังยิ่งกว่ายังแพง" },
            { "11:2058321537:485339272 N 282:2035862270:1383769395", "ได้สิ {name}\n\nนักผจญภัยที่ Dawn มองว่าเป็น Exalted ต้องส่งตรารวม 12 อันเพื่อรับของชั้นเยี่ยม หากอยากได้ของทรงพลังยิ่งกว่า ต้องส่งรวม 54 อัน\n\nผู้เป็น Exalted ในสายตา Dawn ได้ส่วนลดสูงสุด" },
        },
    },
    [11878] = {
        name = "Nathanos Blightcaller",
        lines = {
            { "293:137737902:1538462348", "แน่นอน เจ้าคงเป็นคนทึบไร้ฝีมืออีกคนที่ Dark Lady ส่งมาฝึกกับยอดนักรบของนาง\n\n<Nathanos ถอนหายใจ>\n\nข้าส่งทุกคนกลับไปเป็นชิ้น ๆ ไม่เห็นว่าคราวนี้จะต่างตรงไหน\n\nแต่หน้าที่ข้าไม่ใช่ถามเหตุผล ต้องทำตามบัญชา Dark Lady" },
        },
    },
    [12384] = {
        name = "Augustus the Touched",
        lines = {
            { "157:1689688544:1243743137", "ก่อน Scourge มา ข้าค้าขายดี ซื้อขายทุกอย่าง ทุกอย่าง!\n\nและราคาข้าบ้าคลั่ง!\n\nถามใครก็ได้ ใครที่ยังไม่ตายน่ะ" },
            { "3:4782545:1249379 N 135:774877331:1941202678", "สวัสดี {name}! มาซื้อหรือขาย?\n\nไม่มีที่ไหนราคาดีกว่านี้ ไม่เช่นนั้นข้าคงไม่ใช่ Augustus the Touched!" },
        },
    },
    [16112] = {
        name = "Korfax, Champion of the Light",
        lines = {
            { "462:987890509:1750614828", "Brotherhood of the Light คืออะไรหรือ? เอาละ... แก่นแท้เราทุกคนเป็น Argent Dawn สมาชิกที่ไม่ถูกศีลธรรม ความรู้สึกผิด และอารมณ์มนุษย์ไร้ประโยชน์ยั้งไว้ คิดว่าเป็น Scarlet Crusade ที่ตัดความโง่ การไร้ผู้นำ และศรัทธาคลั่งไร้เหตุผลออก\n\nอย่าให้ Scarlet Commander บอกเป็นอื่น\n\nและอย่าให้ Tyrosus รู้ว่าข้าพูด... น่าเสียดายมากหากต้องทำให้เขาพิการอย่างโหดเหี้ยมเมื่อต่อยตีกัน" },
            { "401:274152678:806367234", "เกราะ Dreadnaught ชุดแรกทำเฉพาะให้ Scarlet Highlord Mograine เมื่อสวมครบ เขาดูดั่งปีศาจจากส่วนลึก Nether\n\nใช่ ภาพน่าตะลึงที่ Mograine ฝ่า Scourge ร้อยตัว ชู Ashbringer สูง แล้วออกอีกด้านท่ามกลางฝุ่นและไฟ ศัตรูเป็นเถ้าใต้เท้า" },
            { "346:1709234869:1627985226", "ถามจริงหรือ? ไม่รู้จริง?\n\nหากขี้ขลาดไม่อยากมือเปื้อนนัก จะพบ Dark Iron Scraps จากสัตว์ใน Burning Steppes กับ Searing Gorge\n\nหากเป็นนักผจญภัยกระหายเลือด ดันเจี้ยน Blackrock Spire กับ Blackrock Depths มีเศษเหล่านี้มาก" },
            { "324:1540537796:514702673", "หลังความตายที่มีข้อถกเถียงของเขาเท่านั้น อัศวินและนักรบ Lordaeron จึงสวมชุดรูปแบบคล้ายกันเพื่อให้เกียรติวีรชนผู้ล้ม แม้ Mograine ตายเป็นชัยชนะใหญ่ของ Kel'Thuzad การเสียสละกลับสร้างแรงกระเพื่อมไปจนสิ้นสงคราม\n\nเมื่อหนึ่งล้มลง อีกมากจะลุกขึ้น..." },
        },
    },
    [16116] = {
        name = "Archmage Angela Dosantos",
        lines = {
            { "123:218114312:1471808287", "กล่าวกันว่า Kel'Thuzad ตามหา Atiesh ในตำนาน มหาคทาของผู้พิทักษ์\n\nใช่ คทาที่ Medivh เคยถือ" },
            { "170:1650853164:162620252 C 1:46:46", "เช่น Kel'Thuzad ข้าก็เคยเป็นจอมเวท Kirin Tor และเช่นเขา ข้าตามหา Atiesh ในตำนาน มหาคทาของผู้พิทักษ์ ชะตาเราผูกกันเช่นนี้ {class}" },
            { "476:1582639944:428255769", "อา คำถามดี\n\nหากชอบล่ากลางแจ้ง มีธาตุใน Plaguelands, Azshara, Burning Steppes, Felwood, Silithus, Winterspring และแม้แต่ Un'Goro Crater\n\nหากเป็นพวกหัวเราะใส่อันตราย บางทีควรไป Dire Maul ได้ยินว่ามีธาตุผิดธรรมชาติมากในกำแพง และควรตามหาธาตุที่คนแคระ Dark Iron ใช้ใน Blackrock Depths ด้วย" },
            { "77:1323522715:1551208458", "บุตรของ Aegwynn ผู้กลายเป็นผู้พิทักษ์ Tirisfal คนสุดท้าย... Medivh" },
            { "232:1261435177:747122023", "เป็นตำนานที่ข้าไม่มีทั้งเวลาและใจจะเล่าใหม่ รู้เพียง Medivh คือผู้พิทักษ์คนสุดท้าย มหาคทา Atiesh เป็นศูนย์รวมพลังและความชั่วที่ครอบงำเขา" },
            { "169:804902490:804821310", "ความชั่วของไททันผู้ตกต่ำ ความชั่วของผู้ทำลาย เพราะคทาถูกสร้างจากเมล็ดแห่งความเกลียดชัง และนั่นคือสิ่งที่นำข้ามาที่นี่..." },
            { "236:1891055704:1612616364", "หลัง Karazhan ล่ม Kirin Tor ส่งกลุ่มจอมเวทค้นหอคอย ยึดของสำคัญทั้งหมดเพื่อการวิจัย... ตอนนั้นเองที่พบคทาเลื่องชื่อและนำกลับ Dalaran" },
            { "211:1258665559:1823014019", "จากนั้นเกิดโศกนาฏกรรมต่อเนื่อง จอมเวท Kirin Tor ทุกคนที่สัมผัส Atiesh ตาย\n\nเพราะมันเป็นวัตถุมีจิตรับรู้ จิตที่ Sargeras มอบให้..." },
            { "214:346563116:962602326", "<Angela พยักหน้า>\n\nหลังความตายเหล่านั้น สภาทั้งหกตัดสินว่าดีที่สุดคือผนึกคทาหลังม่านเวทที่ฝ่าไม่ได้ และตั้งผู้เฝ้าดู ผู้พิทักษ์คทา... ผู้เฝ้านั้นคือข้า" },
            { "239:1329152206:978978248", "ไม่มีอะไรเล่ามากกว่านี้ Dalaran ถูก Archimonde ทำลายเกือบหมด คทาสูญหาย คาดว่าแตกเพราะกลไกป้องกันภัยของม่านเวท\n\nบางคนเชื่อว่าคทาคือต้นเหตุการตอบโต้ของ Archimonde" },
            { "300:110992107:1315763553", "หลัง Dalaran ล่ม ข้าออกจาก Kirin Tor เฝ้า Atiesh หลายปี แล้วจุดหมายใน Kirin Tor ถูกพรากในพริบตา ข้าจะหาคทา แม้ใช้ทั้งชีวิต นั่นทำให้เข้าร่วม Argent Dawn และมาอยู่ที่นี่" },
            { "453:1329956119:1598643428", "ข้าตามชิ้นส่วนคทาทั่วโลก จนพบแผน Kel'Thuzad จะประกอบใหม่ เขารวบรวมได้หลายชิ้นแล้ว ให้นายทหารรองที่ไว้ใจที่สุดถือไว้\n\nข้าขอย้ำว่าต้องกันมหาคทาของผู้พิทักษ์ให้พ้นมือเขา พูดตรง ๆ ข้าไม่รู้ผลลัพธ์อื่น นอกจากหายนะยิ่งใหญ่" },
        },
    },
    [16131] = {
        name = "Rohan the Assassin",
        lines = {
            { "79:596907558:1455691150", "ตำแหน่งทำให้เข้าใจผิด จริง ๆ ข้าเป็นคนดีมากหากรู้จักกัน" },
            { "221:345809031:1854630867", "อย่างตำแหน่งบอก ข้าเป็นนักลอบสังหาร Scarlet Crusade กลางวันกำจัดเป้าหมายสำคัญ กลางคืนอยู่ดิสโก้ Gadgetzan การเต้นคือสิ่งที่ใจเรียกร้องจริง การลอบสังหารแค่จ่ายค่าใช้จ่าย" },
            { "415:2077360112:2057498229", "เจ้าโง่หรือ? ระหว่างมานี่ไม่เห็นพวกโครงกระดูกเต็มพื้นที่หรือ?\n\n<Rohan ถอนหายใจ>\n\nหากชอบกลางแจ้ง หาโครงกระดูกได้ทั่ว Western และ Eastern Plaguelands เชื่อข้า ไม่พลาดแน่ และพวกมันก็ไม่ปล่อยให้เจ้ารอดหากมีโอกาส\n\nหากชอบดันเจี้ยน Stratholme กับ Scholomance คือที่หา Bone Fragment แน่นอน" },
            { "15:778160998:2106597778 R 230:1653790258:962258698", "คำถามดี ชาว{race} สมัยหนุ่มข้าอิสระเสรีไม่ห่วงโลก ร้องประสานเสียงสี่คนสไตล์บาร์เบอร์ช็อปจาก Stormwind ชื่อ Four Dons ที่นั่นเองที่เรียนสร้างเกราะ Bonescythe" },
            { "355:2096493686:1262675171", "ใช่ Bonescythe นักร้องเทเนอร์ของเรา ผู้หงุดหงิดชื่อ Don Julio ทำให้ข้าเริ่มเรื่องทั้งหมด ระหว่างเดินทางทั่ว Lordaeron เขาเรียนทักษะน่าสนใจมาก หนึ่งคือใช้กระดูก Scourge ที่ล้มสร้างเกราะหนังอันร้ายกาจ เหมาะกับนักลอบสังหารที่สุด" },
            { { "217:418919800:1781383956", "216:541485310:197925467" }, "ข้าสติดีเหมือนคนทั่วไป สหาย จะเชื่ออย่างไรก็ตาม แต่ข้าสร้างเกราะนี้ได้จริง หากสนใจเราอาจตกลงกันได้ ยิ่งออกธุรกิจลอบสังหารเร็วเท่าไรยิ่งดี" },
            { "20:806328995:608275921", "เฉพาะสมาชิก เจ้ามือใหม่!" },
        },
    },
    [16132] = {
        name = "Huntsman Leopold",
        lines = {
            { "158:1845204131:1513162390", "พวกเขาเกือบส่ง Loksey พี่น้องชายของข้ามาร่วมประชุม ดูแลสุนัขตัวเองยังไม่ได้ อย่าพูดถึงเป็นตัวแทน Scarlet Crusade อย่างมีความสามารถเลย" },
            { "340:641058394:1482144535", "ความสามารถเหนือธรรมชาติของ Crypt Fiend ในการล่าและฆ่าศัตรู เป็นสิ่งที่คนสายอาชีพข้าศึกษาและยกย่อง ข้าเองฆ่ามันหลายพันตัวในการรณรงค์กำจัด Scourge จากโลก\n\nแม้เกลียดธรรมชาติไร้ปรานี แต่ต้องชื่นชมความสามารถ มันมีหน้าที่และทำได้ดีมาก" },
            { "418:1396556632:92840736", "สัตว์สกปรกพวกนั้นอยู่ทุกแห่ง\n\nหากชอบล่ากลางแจ้ง ส่วนใหญ่อยู่รอบ Plaguewood กับ Terrordale และหนาแน่นใน Terrorweb Tunnel ยังอาจพบแทบทุกค่าย Scourge ใน Eastern Plaguelands\n\nหากชอบลุยดันเจี้ยน พบมากใน Stratholme และชนิด Necrofiend บางตัวใน Scholomance" },
            { "245:1501118229:909616808", "ข้าพบวิธีใช้กระดองและส่วนต่าง ๆ ของ Crypt Fiend ประกอบกับเกราะเวทที่ถูกแปดเปื้อนซึ่งสูญใน Naxxramas เพื่อทำชุดเกราะเบามากและร้ายกาจอย่างยิ่ง" },
        },
    },
    [16133] = {
        name = "Mataus the Wrathcaster",
        lines = {
            { "109:136786222:852790243", "ต้องการอะไร เจ้าตัวเล็กไร้คิด? ไปให้พ้นก่อนรู้ว่าทำไมข้าได้ชื่อ Wrathcaster" },
            { "351:1010960735:950495455", "มันคือพลัง เจ้าโง่\n\n<ดวงตา Mataus มืดลง>\n\nพวกโง่นี้ส่งคนอย่างเจ้าเข้า Naxxramas นำเกราะแปดเปื้อนกลับมาชำระให้คืนรุ่งโรจน์เดิม\n\n<Mataus ถ่มน้ำลาย>\n\nแค่คิดถึงความโง่ขนาดนั้น น้ำดีก็ย้อนถึงคอ\n\nข้าก็หาเกราะนั้น แต่ต้องการในสภาพต่ำช้าแปดเปื้อนที่สุด" },
            { "358:885629830:1075753032", "ข้าไม่เสแสร้ง เจ้าหนอน ความมืดในของเช่นนี้อาจทำลายทั้งเรา นั่นคือเหตุที่ราคาแพง หากต้องตาย ก็จะตายอย่างคนรวย\n\nข้าไม่สนแม้น้ำลายโนลล์หยดเดียวว่าเจ้าจะตายอย่างไร สนแค่ทำตามคำขอ นำของมาแล้วได้ประโยชน์ทั้งคู่ หรืออาจตาย แต่ข้าอธิบายแล้ว..." },
        },
    },
    [16135] = {
        name = "Rayne",
        lines = {
            { "7:989913233:66981971 C 116:1334580540:1625842018", "สวัสดี {class} ขออภัย ข้ากำลังคุยกับ Rimblat เขาเชื่อว่าแม้แผ่นดินนี้ก็ยังช่วยได้" },
            { "45:1167330483:998379789 C 128:1757761715:1834300237", "เราต่างถูกดึงมาด้วยเหตุผลต่างกัน {class}\n\n<Rayne ยิ้ม>\n\nข้ามาพบ Rimblat แห่ง Earthen Ring เขามีทฤษฎีน่าสนใจเรื่องชำระแผ่นดินนี้" },
            { "279:2111876458:2080119614", "หากชอบล่ากลางแจ้ง ทั้งเทรแอนต์ Felwood และ Lasher ใน Un'Goro เป็นแหล่งใบพืชชั้นดี\n\nหากชอบเสี่ยง ปีกตะวันออกและตะวันตกของ Dire Maul จะให้ Savage Frond แทบไม่สิ้นสุด" },
            { "249:845745046:1672535356", "ข้าไม่คิดเช่นนั้น Rimblat พิสูจน์แล้วว่าชีวิตใหม่งอกจากดินแตกสลายได้ ทีนี้ต้องหาวิธีทำซ้ำ และสำคัญกว่านั้น รักษาการเติบโต\n\nระหว่างอยู่ ข้ายังให้บริการนักผจญภัยที่จะเข้า Naxxramas ด้วย" },
            { "31:1375727723:2068756615 C 185:836174853:220469414", "ข้าเป็นช่างมีชื่อพอควร {class} หากมีวัสดุถูกต้อง ข้าทำเกราะ Dreamwalker ได้ ดรูอิดและแม้ชาแมนบางคนสนใจเพราะคุณสมบัติเวท สนใจไหม?" },
        },
    },
    [16012] = {
        name = "Mokvar",
        lines = {
            { "195:709783494:2049571774", "Thrall เมตตามากที่ให้ข้าลี้ภัยในอาณาเขต อย่างไรก็ตาม ข้าไม่อยากอยู่นานเกินควร คงเสียเกียรติยิ่งหากนำปัญหามาสู่ผู้นำเรา" },
        },
    },
    [16013] = {
        name = "Deliana",
        lines = {
            { "157:170368499:1881682783", "อย่าดึงความสนใจนัก ข้ากำลังรอ King อนุญาตเข้าพบ ไม่ใช่ว่ารังเกียจการรอ ข้ารู้สึกปลอดภัยดีท่ามกลางยามล่ำสันเหล่านี้" },
        },
    },
    [16031] = {
        name = "Ysida Harmon",
        lines = {
            { "159:964553779:853695645 N 1:46:46", "ตอนนี้ข้าไม่เป็นไร อย่าห่วง จะหาทางออกหลังทำพิธีชำระห้องนี้ เวทชั่วแปดเปื้อนที่นี่ {name}" },
        },
    },
    [16212] = {
        name = "Dispatch Commander Metz",
        lines = {
            { "59:1214044956:1032586788 R 45:854392128:2075197360", "ข้ายุ่งเกินเล่นทายกลิ่นกับเจ้า ชาว{race} บอกธุระหรือไปให้พ้นหน้า!" },
        },
    },
    [16283] = {
        name = "Packmaster Stonebruiser",
        lines = {
            { "282:839441237:353356918", "คาราวานเราออกวันละราวสองครั้ง แต่ Scourge พยายามขวาง Didier กับล่อไม่ให้ส่งของถึงแนวหน้าอย่างสุดกำลัง บ้าที่สุดเท่าที่เคยเห็น หากมีนักผจญภัยวีรชนช่วยคุ้มกันของก็คงดี..." },
        },
    },
    [16226] = {
        name = "Guard Didier",
        lines = {
            { "68:1995108353:640068831", "อย่ากลัวดาบ เจ้ามือใหม่ เนื้อแกะต่างหากที่จะเล่นงาน!" },
        },
    },
    [1748] = {
        name = "Highlord Bolvar Fordragon",
        lines = {
            { "45:1079953101:140793662", "ข้าคือ Bolvar Fordragon ผู้เป็น Highlord แห่ง Stormwind" },
            { "34:1459525023:1066561076", "ยินดีต้อนรับสู่ Stormwind Keep พลเมือง" },
            { "35:148043678:546329339", "ยินดีต้อนรับสู่ Stormwind Keep พลเมือง" },
        },
    },
    [2425] = {
        name = "Varimathras",
        lines = {
            { "58:884308772:1027497651 C 245:1452403969:1443071999", "อย่าคิดพูดเสมือนเท่าเทียมข้า {class} Sylvanas คือราชินี และข้าทำตามบัญชา\n\nหากไม่แสดงความเคารพเหมาะสม ข้ารับรองว่าเราหาที่เหมาะยิ่งให้เจ้าใน Nether ได้\n\nแต่หากอยากช่วย Dark Lady ก็ไม่มีเหตุที่เราจะคุยกันไม่ได้..." },
        },
    },
    [10926] = {
        name = "Pamela Redpath",
        lines = {
            { "28:142106198:1675758502", "ข้าไม่รู้สึกอบอุ่นอีกเลย..." },
        },
    },
    [230317] = {
        name = "Mokvar",
        lines = {
            { "195:709783494:2049571774", "Thrall เมตตามากที่ให้ข้าลี้ภัยในอาณาเขต อย่างไรก็ตาม ข้าไม่อยากอยู่นานเกินควร คงเสียเกียรติยิ่งหากนำปัญหามาสู่ผู้นำเรา" },
        },
    },
    [230319] = {
        name = "Deliana",
        lines = {
            { "157:170368499:1881682783", "อย่าดึงความสนใจนัก ข้ากำลังรอ King อนุญาตเข้าพบ ไม่ใช่ว่ารังเกียจการรอ ข้ารู้สึกปลอดภัยดีท่ามกลางยามล่ำสันเหล่านี้" },
        },
    },
    [11939] = {
        name = "Umber",
        lines = {
            { "250:1408753542:435488446", "หากหาข้อมูลที่ Cenarion Circle อาจเก็บในหอจดหมายเหตุ ข้าคือคนที่ต้องคุย แต่เจ้าต้องรู้ก่อนว่าหาข้อมูลอะไร ข้าจึงช่วยจริงได้\n\nเห็นวิธีทำงานไหม? ฉลาดเป็นกรด!" },
        },
    },
    [13220] = {
        name = "Layo Starstrike",
        lines = {
            { "32:288305943:923444858 C 38:1968797894:1863099847", "อดีตยังมีชีวิตในแดนร้างนี้ {class} ต้องระวังอย่าปลุกมัน" },
        },
    },
    [15170] = {
        name = "Rutgar Glyphshaper",
        lines = {
            { "94:874208629:1872830668", "Bronzebeard หายอีกแล้ว! คนแคระนั่นไม่มีสติรอบคอบอย่างพี่น้องของเขาเลย" },
            { "312:365527389:1504294738", "นั่งก่อน เรื่องนี้ยาว\n\nตอนมาถึง Silithus แรก ๆ Mistress Mar'alith เป็นไนต์เอลฟ์คนแรกจาก Cenarion Hold ที่ร่วมสำรวจ งานปกติไม่มีอะไรพิเศษ รวมกลุ่มเข้ารังต่าง ๆ หาวัตถุโบราณที่สูญหาย" },
            { "411:2085052733:443569228", "ใช่เลย! รังแน่นด้วยซิลิธิดที่ไม่ดีใจเห็นเรา\n\nทุกอย่างปกติจนพบผลึกสลักอักขระใน Hive'Regal นางถูกดึงดูดดั่งแมลงเม่าหาไฟ! เอาแก้มแนบผลึกแล้วเข้าสภาพคล้ายภวังค์ทันที ลูกเรือกังวลแน่นอน เรารีบยกพาออก!" },
            { "404:1357997089:1332119028", "เราพาไปผู้บัญชาการ หวังว่าดรูอิด Circle จะรักษา และก็ปลุกนางได้ เราคิดว่าธุระกับ Circle จบ จะกลับทำงาน\n\nผ่านหลายสัปดาห์ทุกอย่างดี Brann ยังอยู่ งานจึงเป็นระเบียบพอควร แล้ววันหนึ่งนางก็โผล่ค่ายอีกโดยไม่คาด" },
            { "177:152916551:1274605103", "เจ้าโง่หรือ? จะพูดถึงใครอีก? ใช่ ผู้หญิง Mistress Mar'alith นั่นแหละ นางกลับมาอารมณ์ไม่ดี แล้วเริ่มเรียกร้อง" },
            { "350:1181155341:627062842", "นางต้องการให้กลับ Hive'Regal ทันที! Brann ไม่ยอม บอกว่าไม่มีทางเข้ารังอีกโดยไม่มีกองทัพหนุน อันตรายเกินไป แมลงเหม็นนั่นดูมีสามเท่าจากครั้งแรก\n\nนั่นตอน Natalia คุมตัวเองไม่อยู่!" },
            { "320:1566213078:1308106315", "ถามว่าหมายถึงอะไรหรือ? นางบ้า! คลั่งใส่เราจริง ๆ ปกติข้าไม่ตีผู้หญิง แต่พอฟื้นจากหมดสติ ข้าก็โกรธสุด ๆ Brann, Rutgar, ข้ากับลิงลุยใส่ราวออร์ค! ปาฏิหาริย์ที่ไล่ได้ นางเหมือนถูกสิง!" },
            { "494:761765913:1778068785", "ใครจะรู้? อย่างไรก็ตาม นั่นครั้งสุดท้ายที่เห็น บางที Frankal ให้ข้อมูลดีกว่า\n\nไม่ได้อยากนอกเรื่อง รู้ว่างานผู้บัญชาการสำคัญ แต่เราพบเรื่องใหญ่ ใหญ่มาก! ขอ Ironforge ส่งกองทัพแต่ไร้คำตอบ เห็นว่ากำลังปกป้องอาณาจักรไม่พอหรือเรื่องไร้สาระทำนองนั้น ส่งรายงานผู้บัญชาการแล้วกลับพร้อมเพื่อน เราต้องการความช่วยเหลือ!" },
        },
    },
    [15171] = {
        name = "Frankal Stonebridge",
        lines = {
            { "24:1838431865:960725349 C 123:1934727891:1379828454", "มองฟ้า {class} ไม่เห็นฝูงมังกรในแถบนี้พันปีแล้ว! Qiraji วางแผนอะไรแน่ ข้ารู้!" },
            { { "181:23190931:1080470239", "181:981272343:790976999" }, "โธ่ ไม่เอาอีกแล้ว... นั่งก่อนเจ้าหนู\n\nแน่ใจว่า Rutgar เล่าบ้างแล้ว ข้าจะข้ามส่วนเบื่อเข้าประเด็นสำคัญเลย" },
            { "260:225476561:1188786358", "ใช่แล้ว! Mistress กลับจะเข้ารังครั้งที่สอง แต่ Brann ไม่เอาด้วย! ก่อนต่อสู้ นางเริ่มพูดกับบางสิ่งหรือบางคน แปลกยิ่งกว่านั้นคือท่องภาษาที่เราไม่เคยได้ยิน" },
            { "332:923050680:510678324", "ใช่เลย! ยิ่งแปลกเมื่อรวม Brann, Rutgar, ข้าและลิง เรารู้ 38 ภาษา รวมภาษาไททันนิดหน่อย ทั้ง Vanir และ Aesir\n\nไม่ว่านางส่งเสียงกระทบอะไร คนที่คุยด้วยไม่ได้อยู่ตรงนั้นแน่ จากนั้นพยักหน้าแล้วบุกโจมตีเราเลย!" },
            { { "481:462263498:1619021009", "481:1677310511:918391179" }, "ฟังนะเจ้าหนู สิ่งที่โจมตีเราไม่ใช่นักบวชหญิงอะไรทั้งนั้น! ตาเรืองพลังชั่ว น้ำลายฟูมปาก! เข้ามากรีดร้องพิสดารจนเราวิ่งแยก แล้วเริ่มกรีดจิตทีละคน ข้าได้ยินคำมืดในหัว มองคนอื่นหมดสติสลับกัน ช่างคลั่ง! คงจบเห่ถ้าไม่มีลิงบัดซบนั่น" },
            { "234:339569426:2042378919", "มีอะไรต้องถาม? มันคือลิง เจ้าโง่ อย่างไรก็ดี ลิงคลั่งเมื่อเห็น Brann หน้าคว่ำทราย ไนต์เอลฟ์ทำอะไรก็หยุด Glibb ที่ทุบหัวนางไม่ได้" },
            { "235:59704195:904232818", "ข้าจะบอกว่าต่อมาอย่างไร นางวิ่งตรงเข้ารัง รู้ไหมอะไรบ้ากว่า? ไม่มีแมลงสักตัวขวางหรือหยุด วิ่งผ่านเหมือนเป็นเพื่อนสนิทกันหลายศตวรรษ" },
            { "4:1517438556:201828078", "ใช่" },
        },
    },
    [15176] = {
        name = "Vargus",
        lines = {
            { "20:81137105:1466717725 R 107:519215257:94521079", "ความชั่วใหญ่กำลังตื่น ชาว{race} สัมผัสได้ไหม?\n\nฮึ! แน่นอนว่าไม่ได้ ส่งเกราะกับอาวุธมา ข้าจะคืนความแข็งแรงให้" },
        },
    },
    [15180] = {
        name = "Baristolth of the Shifting Sands",
        lines = {
            { "17:1842881169:1590996998 R 197:136041371:462541367", "มองข้างหลัง ชาว{race} รังเคลื่อนไหวขณะแผ่นดินรอบสั่นสะเทือน\n\nถึงเวลาทำสัญญาที่ให้ไว้พันปีก่อน ผืนทรายเคลื่อนอีกครั้งขณะ Qiraji วางแผนสงคราม" },
        },
    },
    [15181] = {
        name = "Commander Mar'alith",
        lines = {
            { "9:330273291:685578878 R 57:1694153930:1233573647", "ทำไมตอนนี้ ชาว{race}? ข้าไม่เข้าใจ งานยังมาก..." },
        },
    },
    [15182] = {
        name = "Vish Kozus",
        lines = {
            { "257:1353114423:689473196", "ช่วงนี้ผู้บัญชาการไม่เป็นตัวเอง หญิงคนรักหายระหว่างขุดค้นโบราณคดีในทะเลทรายใต้ ไร้ร่องรอย! แปลกจริง\n\nข้าเดาว่าหางานหรือ? ต้องตีหัวให้ถึงจะเข้าใจเบาะแสไหม?" },
            { "27:359031996:82753563 N 110:1970305023:1022638101", "เจ้าล่า Deathclasp หรือ {name}? ข้าประทับใจ อาทิตย์นี้มันคร่าลูกน้องข้าสองคนแล้ว หวังว่าโชคเจ้าดีกว่าพวกเขา" },
        },
    },
    [15183] = {
        name = "Geologist Larksbane",
        lines = {
            { "134:753762495:643250418", "ได้ยินไหม คนแปลกหน้า? เสียงหึ่งดังขึ้นทุกวัน ผลึกเหล่านี้ต้องเป็นตัวทำแมลงคลั่ง" },
        },
    },
    [15190] = {
        name = "Noggle Ficklespragg",
        lines = {
            { "99:417221288:1209302493", "เฮ้! ขอบใจที่ช่วยชีวิต! ข้าคงนอนสักพักจนแรงกลับมา" },
            { "45:30008241:2013981022", "เจ้าเป็นใคร? ข้าอยู่ไหน? ข้ารู้สึก... อ่อนแรง..." },
        },
    },
    [15191] = {
        name = "Windcaller Proudhorn",
        lines = {
            { "11:927657569:725753248 C 142:138504870:1871573883", "สวัสดี {class} ยินดีต้อนรับ Cenarion Hold จากนี่เราจะโจมตีซิลิธิดถึงจุดแข็งแกร่งที่สุด หวังว่าเจ้ามาช่วย" },
            { "34:921316370:428429791 N 190:1476418571:444499439", "ยินดีที่พบอีก {name} ความช่วยเหลือทำให้เส้นทางเสบียงปลอดภัยขึ้นมาก หวังว่าเข้าใจความสำคัญของการส่งกำลังบำรุงในสงครามใหญ่เช่นนี้" },
        },
    },
    [15194] = {
        name = "Hermit Ortell",
        lines = {
            { "53:2085018036:1350450623", "ไปทันที คนแปลกหน้า! ข้าไม่มีธุระกับเจ้า" },
            { "47:819843918:1524448611", "กลับมาแล้ว! คราวนี้ให้ช่วยอะไร?" },
        },
    },
    [15270] = {
        name = "Huum Wildmane",
        lines = {
            { "40:800959945:255192386 N 54:1800250747:83874049", "วิญญาณ Silithus เรียกเรา {name} แผ่นดินร่ำไห้ เพราะมีเรื่องเศร้าต้องเล่า..." },
        },
    },
    [15282] = {
        name = "Aurel Goldleaf",
        lines = {
            { "132:1169896125:1499912220", "Cenarion Circle รอบรู้และค้นลึกในความลับแผ่นดินมาก ช่างทั้งหลายควรฟังคำดรูอิดเหล่านี้" },
        },
    },
    [15306] = {
        name = "Bor Wildmane",
        lines = {
            { "41:411485112:1781016306 N 141:1586276504:619351867", "เราไม่ได้มีศัตรูเดียวใน Silithus {name}\n\nขณะทุกคนจับตาซิลิธิด ข้ากับพี่ชายเฝ้าพวกคลั่ง Twilight's Hammer ใกล้ชิด" },
        },
    },
    [15443] = {
        name = "Janela Stouthammer",
        lines = {
            { "6:1136836709:1914036474 C 191:75659164:2123112125", "สวัสดี {class} Ironforge Brigade ประจำที่นี่เฝ้า Hive'Zora ดรูอิด Cenarion Circle ติดตามการเคลื่อนไหวซิลิธิด และคาดเรื่องใหญ่ในบริเวณนี้" },
        },
    },
    [15613] = {
        name = "Merok Longstride",
        lines = {
            { "95:1472754656:122609656", "แม้ซิลิธิดดูอันตราย แต่มันเชื่องเมื่อเทียบผู้บงการ Qiraji" },
        },
    },
    [15540] = {
        name = "Windcaller Kaldon",
        lines = {
            { "169:310134513:423064221", "เมื่อสงครามเต็มรูปแบบ เราไม่ขาดผู้พร้อมรบจาก Horde กับ Alliance\n\nหากเพียงกันไม่ให้พวกเขาฆ่ากันเองได้..." },
        },
    },
    [16091] = {
        name = "Dirk Thunderwood",
        lines = {
            { "64:526598225:1721782310", "สวัสดีและยินดีต้อนรับจากคฤหาสน์ Ravenholdt นักผจญภัย" },
        },
    },
    [15797] = {
        name = "Colossus Researcher Sophia",
        lines = {
            { "95:133897704:230992027", "ความลับพลัง Colossus อาจนำสู่นวัตกรรมวิทยาศาสตร์สารพัด!" },
        },
    },
    [15798] = {
        name = "Colossus Researcher Nestor",
        lines = {
            { "88:191386790:612235437", "ศึกษาเข้าใจ Colossus จะให้ความได้เปรียบ Qiraji ที่เราต้องใช้" },
        },
    },
    [15799] = {
        name = "Colossus Researcher Eazel",
        lines = {
            { "89:1974284154:301773960", "ต้องรู้ให้ได้ว่า Qiraji เลี้ยงอสูรพวกนี้ด้วยอะไร! ดูขนาดสิ!" },
        },
    },
    [15192] = {
        name = "Anachronos",
        lines = {
            { "99:74037854:1105519038", "เราต้องเป็นฝ่ายโจมตีก่อน จะปล่อยให้ทำผิดซ้ำอดีตไม่ได้..." },
        },
    },
    [2980] = {
        name = "Grull Hawkwind",
        lines = {
            { "11:927657569:725753248 N 83:2068509129:1440051217", "สวัสดี {name} ยินดีต้อนรับสู่ Camp Narache ข่าวการมาถึงของเจ้าแพร่ไปทั่วเผ่าอย่างรวดเร็ว" },
        },
    },
    [3448] = {
        name = "Tonga Runetotem",
        lines = {
            { "58:80596404:242323918 C 119:2146136468:842182411", "ยุคสมัยที่เราอยู่ผันผวนดั่งสายลม {class} เราต้องจดจำสิ่งที่แท้จริงและยั่งยืนในโลกนี้ แล้วรักษามันไว้ สิ่งอื่นล้วนสูญเปล่า" },
        },
    },
    [7783] = {
        name = "Loramus Thalipedes",
        lines = {
            { "114:94987654:203211706", "เจ้ามองเห็นพวกมันหรือไม่ ผู้มีอายุขัย? ไม่... ข้าก็คิดว่าเจ้าคงไม่เห็น มีดวงตาแต่กลับมองไม่เห็น นั่นเป็นทั้งพรและคำสาปของเจ้า" },
            { "436:551235377:2031527055", "ในยุคสงคราม Razelikh the Defiler เป็นหนึ่งในผู้ใต้บัญชาของ Lord Kazzak ที่น่าเกรงกลัวที่สุด เมื่อ Legion พ่ายแพ้และ Kazzak ถูกผลักกลับสู่ Tainted Scar เจ้านายก็มอบหมายให้ Razelikh ยึดครอง Blasted Lands ให้มั่นคง\n\nขณะที่ Alliance ต่อสู้กับ Horde ในศึกเล็กน้อยเพื่อแย่งดินแดนนอก Blasted Lands นั้น Razelikh กำลังรวมนิกาย Shadow Council ที่แตกต่างกันและเหล่าโอเกอร์ Dreadmaul อันป่าเถื่อนในพื้นที่เข้าด้วยกัน" },
            { "347:1228414500:595969048", "น่าเศร้าที่ในที่สุดภูมิปัญญาของ Thrall กลับเป็นสิ่งผูกพันจ้าวปีศาจกับลูกสมุน กองทหารของ Trebor เป็นตัวเร่งให้จ้าวปีศาจ นิกาย Shadowsworn และเหล่าโอเกอร์รวมตัวกัน อำนาจที่แทบไร้ขีดจำกัดและการมอบกองทหารจู่โจมอมตะให้ผู้นำแต่ละฝ่ายเป็นสิ่งล่อใจที่ทำให้ข้อตกลงนั้นผนึกด้วยเลือด" },
            { "309:922971795:1772880310", "สิ่งที่ Sevine, Allistarj และ Grol ไม่รู้คือ เช่นเดียวกับข้ารับใช้ที่ถูกผูกไว้กับแผ่นดิน พวกเขาเองก็จะเป็นเช่นนั้น... เจ้าเห็นหรือไม่ ราคาของความเป็นอมตะคือการถูกจองจำและเป็นทาสตลอดกาลภายใต้คำสั่งของ Razelikh ความเจ้าเล่ห์อันโหดร้ายของมันเป็นฝ่ายชนะอีกครั้ง" },
            { "29:2074601152:562788051 R 249:1770210034:1306062233", "บัดนี้จิตใจของพวกเขาแปดเปื้อนแล้ว ชาว{race} ใช่ ยิ่งกว่าแต่ก่อนเสียอีก พวกเขามีชีวิตอยู่เพียงเพื่อรับใช้และปกป้อง Razelikh เศษเครื่องรางที่แต่ละคนถือเป็นกุญแจเรียกจ้าวปีศาจ สิ่งที่เจ้ายังไม่เข้าใจคือ ไม่มีใครทำร้ายพวกเขาด้วยวิธีธรรมดาได้" },
            { "244:1804713871:1284265211", "สมมุติว่าเจ้าผ่านงานอันยาวนานและยากลำบากในการสร้างอาวุธที่จำเป็นต่อการฝ่าเวทปีศาจซึ่งคุ้มครองทั้งสามคนนั้นแล้ว เจ้าจะทำอะไรต่อ? เผชิญหน้ากับ Defiler ในรังของมันหรือ?\n\n<Loramus หัวเราะ>" },
        },
    },
    [8380] = {
        name = "Captain Vanessa Beltis",
        lines = {
            { "6:533059392:220789999 N 268:1280378553:774875510", "อาฮอย {name}! เป็นภาพที่ไม่น่าดูเลยใช่ไหม?\n\nHorizon Scout จมอยู่ก้นทะเล ลูกเรือแตกกระเจิง สินค้าและผู้โดยสารกระจัดกระจายราวกับเศษซาก ดูไม่ต่างจากคลอง Stormwind หลังเทศกาล\n\nและปัญหาก็ไม่ได้จบเพียงเท่านั้น..." },
            { "33:1618597783:853276575 C 87:2071203066:651616912", "รอข้าครู่ {class} นากากำลังโจมตี จะคุยทันทีที่ศึกจบ!" },
        },
    },
    [8399] = {
        name = "Nyrill",
        lines = {
            { { "221:390630890:398524985", "222:1761903647:1084738924" }, "สวัสดี ข้าคือ Nyrill ศิษย์ของ Master Xylem หากมีข้อกังวล เชิญคุยกับนายท่านเถิด\n\nเมื่อเจ้าพร้อมกลับลงไปที่เชิงเขา ข้าจะอยู่ที่นี่คอยรับใช้" },
        },
    },
    [8587] = {
        name = "Jediga",
        lines = {
            { "32:894913383:2025776196 N 404:2138891277:1978821545", "ข้าไม่ได้มาเพราะเกียรติ {name} แต่มาเพราะความหยิ่งออร์คคนหนึ่ง\n\nหากไม่ปฏิเสธข้อเสนอ Belgrom คงยังทำธุรกิจจริงใน Orgrimmar\n\nนักรบหญิง Durotar หลายคนรู้ความอยากได้ผู้หญิงของเขา แต่ไม่หยุดเขาทำตัวมีเสน่ห์\n\nโชคดีที่ไม่ตามตื๊อข้านานกว่านั้น ไม่เช่นนั้นคงเสียมากกว่าแค่นิ้วมือ" },
        },
    },
    [8659] = {
        name = "Jes'rimon",
        lines = {
            { "27:946193128:325694233 C 56:967659863:1230326655 N 308:1029448998:905517703", "ข้าและ Shattered Hand ขอต้อนรับเจ้าอย่างอบอุ่น {class}\n\nอย่าแปลกใจเลย {name} แม้แต่สถานที่สูงส่งที่สุดใน Orgrimmar ก็ยังมีเงา บางเรื่องจำเป็นต้องซ่อนไว้ และ Shattered Hand ยินดีรับบทบาทนั้น แม้แต่ Thrall ผู้มีเมตตาก็ยังยอมรับว่าจำเป็นต่อความปลอดภัยของเหล่าออร์คและโทรล\n\nแต่เจ้าไม่ได้มาคุยเรื่องธุรกิจของข้า เจ้ามาด้วยเรื่องอื่น" },
            { "244:989507518:546956915", "Un'Goro Crater อยู่ใต้ Kalimdor ไกล เลย Thousand Needles ใน Tanaris มองหาหินลอยใหญ่ มันบอกทางเข้าปล่อง แต่ระวัง ทางไม่ง่าย แรปเตอร์อยู่ไม่ไกลทางเข้า" },
        },
    },
    [11548] = {
        name = "Loh'atu",
        lines = {
            { "11:927657569:725753248 C 475:1051120065:1253306497", "สวัสดี {class}\n\nเซนทิเนลตรงนั้นยอมให้ข้าร่วมค่าย หากข้าสัญญาว่าจะไม่พาปัญหามา เจ้าคงเข้าใจความจำเป็นด้านการทูตใช่ไหม?\n\nข้ามาสืบสวนความผิดปกติของแผ่นดิน ซึ่งเป็นประโยชน์ต่อพวกเขาด้วย ข้าจึงเห็นว่าการอยู่ที่นี่ช่วยเสริมพันธมิตรอันเปราะบางระหว่างทุกเผ่าแห่ง Azeroth หากเจ้าอยากช่วย ข้าก็ซาบซึ้ง แต่ไม่ว่าอย่างไร โปรดอย่าก่อปัญหา" },
            { "211:1260425454:1528590518", "เพื่อตอบแทนความช่วยเหลือ ข้าจะบอกสิ่งที่รู้เกี่ยวกับดินแดนนี้และสถานที่น่าชม ความรู้ของข้ามีไม่มากนัก แต่อาจชี้สิ่งที่เจ้าสนใจได้" },
            { "359:938186453:796011277", "ข้ารู้ตำนานไนต์เอลฟ์ไม่มาก แต่กล่าวว่านานมาแล้ว เมื่อยังถือศาสตร์อาร์เคนศักดิ์สิทธิ์ Azshara คือผู้ยิ่งใหญ่ที่สุด หญิงงามที่ยกเป็นราชินี เสียดายการเสพติดอาร์เคนกลายเป็นตัวเร่งเหตุร้ายแรงที่สุดในประวัติโลก" },
            { "298:1083653741:299733657", "เคยเป็นเมืองใหญ่ไนต์เอลฟ์ ไฮบอร์นปกครองและใช้เวทอาร์เคนมหาศาล บัดนี้ถูกสาปหลอกหลอนแผ่นดิน เมืองซากตกเป็นเหยื่อนากา Spitelash เท่าที่รู้ นากาค้นหาวัตถุไฮบอร์นทรงพลัง" },
            { "259:1731550477:122872253", "มีข่าวว่าจอมเวทมนุษย์ทรงพลังอยู่เหนือ เฝ้าแผ่นดินไม่รู้เหตุ ข้ายังไม่เคยไป แต่กล่าวว่าต้อนรับผู้มาเยือน และให้ความโปรดปรานหากช่วยงานเล็กน้อย" },
            { "410:482174158:487702239", "หลายปีข้าเห็นเรื่องร้ายกับเฟอร์โบลก เป็นเหยื่อหลายด้าน แต่ไม่ชัดว่าเผ่านี้เป็นอะไร ถูกความแปดเปื้อนเดียวกับ Felwood หรือ? หรือเพียงโกรธสิ่งที่เกิดกับคนเคยสงบแล้วปกป้องตน? อย่างไร ส่วนมากดูเป็นศัตรูกับผู้เข้าพื้นที่" },
            { "295:1864783966:2036297205", "มังกรสีน้ำเงินจริงไม่อยู่ แต่ผู้ติดตาม Malygos อยู่ ข้าไม่รู้เหตุ แต่บอกได้ว่าที่ใดมีมังกรน้ำเงิน ให้คาดเวทอาร์เคน ไม่แปลกหากดรากอนสปอว์นปกป้องบางสิ่ง อาจเป็นของไฮบอร์นทิ้งไว้" },
        },
    },
    [11801] = {
        name = "Rabine Saturna",
        lines = {
            { "85:1699259729:1058846491", "อย่าฟังเสียงหัวใจของโลก คำตอบอยู่ภายในตัวเจ้า เจ้ารู้ความจริงอยู่แล้ว" },
            { "267:1674014304:849209395", "ใช่ แต่ข้ารู้จักที่นั่นในนามแท้ว่า Eldre'Thalas แหล่งพลังเวทของไนต์เอลฟ์เมื่อหลายปีก่อน\n\nเจ้ารู้จัก Eldre'Thalas หรือ เจ้าผู้เยาว์วัย? บางคนอาจว่ามันบังเอิญตรงกับปัญหาของข้า... แต่ข้าไม่เชื่อเรื่องบังเอิญ" },
            { "391:367161024:1805678473", "สายลับของ Cenarion Circle พบข้อมูลน่ากังวลเกี่ยวกับสถานการณ์ใน Eldre'Thalas ข้ายังคิดไม่ตกว่าจะจัดการอย่างไร คงต้องขอให้นักรบที่ดูแลตัวเองได้ช่วยในเร็ว ๆ นี้\n\nแต่หากจะลงมือให้ถูกต้อง เราต้องเข้าใจตำนานของวัตถุชื่อ Fruit of Fertility ก่อน" },
            { "487:1288483277:1242757533", "ในอดีต Eldre'Thalas เป็นศูนย์รวมแห่งเวทมนตร์ ผู้ที่เดินอยู่ในห้องโถงศักดิ์สิทธิ์ควบคุมพลังมหาศาล หนึ่งในนั้นคือ Millicent Serene นักธรรมชาติวิทยาที่ดึงพลังธรรมชาติมาไว้ในวัตถุทรงพลังที่นางสร้าง\n\nFruit of Fertility เป็นผลงานสูงสุดของนาง นางใช้ Moonwell ที่จัดเตรียมเป็นพิเศษปลูกเถาวัลย์แปลกตาอันมีชีวิตชีวา เติมออร่าแห่งการปกป้องและการเติบโตลงไป Eldre'Thalas ทั้งเมืองรุ่งเรืองได้ด้วยพลังของมัน" },
            { "384:1877926300:1673227888", "อนิจจา เรื่องมักเป็นเช่นนี้ ข้าและ Cenarion Circle เคยคิดว่าสิ่งที่ Milli สร้างถูกทำลายไปใน War of the Ancients แต่เพิ่งรู้ว่าเราเข้าใจผิดอย่างมาก\n\nFruit of Fertility รอดมาได้... แม้บัดนี้จะถูกเรียกว่า Felvine และกำลังถูก Alzzin the Wildshaper จ้าวปีศาจผู้คุมส่วนนั้นของ Eldre'Thalas ทำให้เสื่อมทราม" },
            { "30:331737859:830345762 N 241:971292379:396091685", "ข้า... ไม่อาจจินตนาการได้เลย {name} รู้เพียงว่าข้าจะไม่ยอมให้เกิดขึ้น มันต้องถูกทำลาย หากไม่ใช่เพื่อป้องกันภัยจากพิษปีศาจ ก็เพื่อความทรงจำของ Millicent Serene... Milli...\n\nสหาย นี่คือจุดที่ข้าหวังให้เจ้าช่วย" },
        },
    },
    [11811] = {
        name = "Narain Soothfancy",
        lines = {
            { "122:1404581146:1919895007", "Narain Soothfancy ยินดีรับใช้! วิศวกรเกษียณและยอดนักพยากรณ์! ข้าบอกอนาคตก่อนเกิดได้!" },
            { "110:1314882651:1726668377 R 1:63:63", "อย่าบอก! ชู่ว์! มาเรื่อง Ashbringer ใช่ไหม?!? ใช่... ใช่... ไม่! ข้าผิดเอง\n\nให้ช่วยอะไร ชาว{race}?" },
            { "18:260712765:33351978 N 311:432906530:1328907832", "มัน... มัว {name} ข้าไม่เห็น! เดี๋ยว... เห็นแล้ว... รัง Doctor Weavil มัน... ใช่! เชื่อว่าเขาถือหนังสือบทหนึ่ง!\n\nขอลองปรับภาพออกให้เห็นกว้างขึ้น\n\n<Narain ดูตาเหล่>\n\nAlcaz Island! ไอ้เจ้าเล่ห์อยู่ Alcaz Island!" },
            { "91:6192950:740260730", "<Narain ถือซองยังไม่เปิดแนบหน้าผาก>\n\nอะไรเอ่ย... อืม... กำมะหยี่!\n\nข้าทายถูกไหม?" },
        },
    },
    [4046] = {
        name = "Magatha Grimtotem",
        lines = {
            { "23:1243181546:429691765 C 93:959683570:1097434270", "ต้องฟัง {class}รุ่นเยาว์ ฟังเสียงกระซิบในความมืด มันชี้นำยามยากลำบากนี้" },
        },
    },
    [8379] = {
        name = "Archmage Xylem",
        lines = {
            { "155:1238796678:146240359", "หากมาขอสิทธิ์ทำงานให้ข้า ก็ยินดีต้อนรับ มิฉะนั้นโอกาสที่เจ้าจะมีประโยชน์น้อยมาก" },
        },
    },
    [7802] = {
        name = "Galvan the Ancient",
        lines = {
            { "77:1539034693:622741270 N 1:46:46", "น้อยคนมาไกลเพียงนี้ ยิ่งน้อยที่ผ่านได้ อย่ากลายเป็นตัวเลขสถิติ {name}" },
        },
    },
    [13278] = {
        name = "Duke Hydraxis",
        lines = {
            { "164:832623818:1838383908", "ข้าคือ Hydraxis ดยุกแห่งเหล่า Waterlord เจ้าไม่ใช่สิ่งมีชีวิตธาตุ จึงไม่เข้าใจการต่อสู้ของเรา แต่บางทีเราอาจทำข้อตกลงที่เป็นประโยชน์ต่อทั้งสองฝ่ายได้..." },
            { "N 116:800404311:1457536795", "{name} ดีใจที่พบ ศึกจ้าวธาตุอื่นยังเดือด แต่ความพยายามเจ้าช่วยให้มั่นใจชัยชนะ" },
            { "N 390:779620531:1514796450", "{name} เจ้าพร้อมสำหรับงานสูงสุดแล้ว รูนไฟบนพื้น Molten Core เป็นทางเชื่อมสู่แดนแห่งไฟ เป็นทั้งการลบหลู่พวกเราและแหล่งพลังของ Firelord เราต้องดับมัน!\n\nรับ Aqual Quintessence หนึ่งขวดไปเทบนรูน เปลวไฟจะดับ ทำให้รูนใช้การไม่ได้และศัตรูของเราอ่อนแอลง!" },
            { "44:1203729626:591499893 N 80:191500233:1079570733", "เจ้ารับใช้อย่างภักดีมาก {name} ขอให้ข้ามอบแหล่งแก่นธาตุของเราที่ไม่มีวันหมดให้เจ้า" },
            { "14:1649650394:897424258 N 92:1892778246:2124704410", "ยินดีต้อนรับกลับ {name} พิสูจน์ว่าเป็นพันธมิตรคู่ควรต้าน Ragnaros เรายินดีต้อนรับเสมอ" },
        },
    },
    [15481] = {
        name = "Spirit of Azuregos",
        lines = {
            { "28:65011670:1043884790", "การเฝ้าของข้านิรันดร์ ผู้มีอายุขัย" },
            { "106:512940716:391027808", "หาเศษคทาที่มอบให้ Blue Flight ปกป้องหรือ?\n\n<Azuregos ดูเหมือนยิ้ม>" },
            { "34:1337794304:1031685811", "เจ้าไม่ควรกำลังช่วยโลกอยู่หรือ?" },
            { "319:916008251:226050643", "แน่นอนว่าข้าไม่มีเศษคทาอยู่กับตัว นั่นคงโง่มาก ข้ากำลังเดินอยู่ท่ามกลางคนป่าในดินแดนต้องสาป! ไปได้ไม่ถึงห้าก้าวก็มีออร์คหรือมนุษย์คลั่งเอาไม้แหลมแทงหนังข้า เมื่อไรก็ได้เจ้าอาจต้องคุยกับวิญญาณข้าแทน\n\nอย่างไรก็ดี... ข้าซ่อนมันไว้แล้ว\n\nเอาสิ... ถามข้าว่าที่ไหน" },
            { "34:862009808:1379040708 R 414:1702840536:1979196170 R 17:883923506:980617120", "เจ้าต้องชอบเรื่องนี้ ชาว{race} ฟังนะ เมื่อ Malygos มอบหมายให้ข้าปกป้องเศษคทา ข้าก็รู้ทันทีว่าจะต้องปวดหัวและทนทุกข์ไปชั่วนิรันดร์\n\nข้าเพียงอยากศึกษาชายฝั่งที่เปี่ยมเวทมนตร์และเก็บวัตถุที่อาจหลงเหลือจากมหาวิบัติ ที่นี่เคยมีอารยธรรมไฮบอร์นอันรุ่งเรือง! ไม่ต้องบอกก็รู้ว่ามีวัตถุเวทชั้นดีอยู่ ชาว{race} ข้าได้กลิ่นมัน!" },
            { "293:1596229633:1661608748", "อย่างที่ข้าบอก ข้าเก็บเศษคทานั้นมาห้าร้อยปี มีแต่ปัญหา มันดึงดูดความสนใจที่ไม่พึงประสงค์ทุกรูปแบบ ข้าอยากอยู่กับงานศึกษา ไม่ใช่เป็นพี่เลี้ยงตั๋วสู่เกียรติยศของคนที่อยากเป็นวีรชน ดังนั้น... ข้าจึงมอบมันให้ปลา" },
            { "73:191544101:1745648004", "ไม่ใช่ปลาธรรมดา ผู้มีอายุขัย เป็นปลาซิว ปลาซิวพิเศษมาก" },
            { "8:1013427627:556088467", "ถูกต้อง!" },
            { "106:279987138:2098459080", "อัจฉริยะ ข้ารู้... ไม่มีใครหาพบแน่ แต่เผื่อว่ามีใครพบเข้า ข้าก็มอบพลังพิเศษให้ปลาซิวตัวนั้นไว้ด้วย" },
            { "266:2103285832:155755130", "ถูกต้อง เจ้าฟังอยู่สินะ! ที่จริงปลาซิวตัวนี้เป็นสัตว์ประหลาดน่าสะพรึงที่ข้าสร้างขึ้น เวลาพักผ่อน ข้าชอบคิดถึงชาวประมงอับโชคที่บังเอิญพบมันแล้วถูกกลืนทั้งตัว พนันว่าคงตกใจไม่น้อย!\n\n<Azuregos หัวเราะ>" },
            { "31:1492902953:1263536034 R 175:1339341155:1035250567", "อัจฉริยะมักถูกเข้าใจผิด ชาว{race} เอาละ เรื่องเศษคทา... หากเจ้าอยากได้มันโดยไม่ต้องใช้เวลาหมื่นปีตามหา จงฟังให้ละเอียด" },
            { "25:899723813:24578612", "สองคำ: Arcanite Buoy" },
            { "336:1128869978:258065617", "เอาละ... เจ้าต้องสร้าง Arcanite Buoy แล้ววางในทะเล ปลาซิวจะถูกดึงดูดด้วยพลังเวท พอมันเข้าใกล้ ตูม! ทุ่นจะระเบิดเป็นคลื่นอาร์เคนอันรุ่งโรจน์ เผยร่างที่แท้จริงของมัน อีกทั้งเจ้าอาจโดนหรือไม่โดนโทสะของ Neptulon ด้วย ข้าว่าโอกาสอยู่ที่ 50/50" },
            { "135:107588380:298597029", "หากไม่รู้ดีกว่า คงคิดว่าล้อข้า ผู้มีอายุขัย แต่ใช่ ส่วนใหญ่ถูก เจ้าสวมเสื้อผ้าครบได้" },
            { "209:1453890744:2092244876 N 38:1598489308:560221266", "นำบัญชีนี้ไปให้คนรู้จักเก่าของข้าใน Tanaris ชื่อ Narain Soothfancy เขาเป็นผู้มีพลังจิตที่แย่ แย่มาก แต่วิศวกรรมของเขายอดเยี่ยม! เขาน่าจะเข้าใจทั้งหมด\n\nไม่ต้องขอบใจ {name} อย่างน้อยข้าก็ช่วยได้เท่านี้\n\nขอให้เป็นวันที่ดี!" },
            { "16:565156791:1479085858", "ข้าบอกว่าขอให้เป็นวันที่ดี!" },
        },
    },
    [14524] = {
        name = "Vartrus the Ancient",
        lines = {
            { "11:927657569:725753248 N 1:46:46", "สวัสดี {name}" },
        },
    },
    [262560] = {
        name = "Hana Lighthoof",
        lines = {
            { "N 66:1029666708:1413466842", "{name} ให้ข้าช่วยพัฒนาการฝึกของเจ้าต่อเบื้องพระพักตร์ Earth Mother อย่างไร?" },
            { "171:100646597:1812089257", "มีหลายคนรับใช้ Earth Mother ด้วยวิธีที่ต่างกัน Earthen Ring กับ Cenarion Circle คล้ายกันมาก และมักมีเป้าหมายตรงกัน แม้วิธีการและประเพณีจะแตกต่างกัน" },
        },
    },
    [8256] = {
        name = "Curator Thorius",
        lines = {
            { "11:927657569:725753248 N 1:46:46", "สวัสดี {name}" },
        },
    },
    [248415] = {
        name = "Tordrin Sternblade",
        lines = {
            { "51:751065566:998424618", "ได้ยิน Marshal McBride บอกให้เจ้ามาหาข้า" },
            { "53:1945481929:1069095775 C 9:839995460:592385449", "ข้าฝึกให้ไม่ได้ ควรหาครูฝึก{class}" },
            { "20:1806402586:1551596819", "ให้ข้าช่วยอะไร?" },
        },
    },
    [3836] = {
        name = "Mountaineer Pebblebitty",
        lines = {
            { "25:344665964:499880925 N 469:325091845:26093595", "ข้าไม่อยากฟัง {name} ไม่ ไม่มีทางให้เจ้าเข้า Searing Gorge เป็นไปไม่ได้ ไม่มีวัน ต้องบอกอีกกี่ครั้งว่าข้าปล่อยเจ้าเข้าไปไม่ได้! เจ้าพูดภาษาสามัญไม่รู้เรื่องหรือ? หรือเป็นออร์คปลอมตัวมา? ไม่ ก็คือไม่!\n\nถ้าปล่อยเจ้าเข้าไป ข้าก็ต้องปล่อยทุกคนเข้า ไม่นานเพื่อนสนิทของเจ้าก็จะขอเข้า ตามด้วยญาติห่าง ๆ แล้วก็เพื่อนของพวกเขา ต่อกันไม่จบ ครั้งล่าสุดที่เกิดแบบนั้น... เอาเถอะ อย่าพูดถึงครั้งล่าสุดเลย" },
            { "306:592631482:455644208", "เจ้าบ้าหรือ? รู้ไหมว่าสัตว์แบบไหนอยู่ในนั้น? ร้ายที่สุดเราอาจต้องใช้พลั่วโกยซากเจ้า เราเสียคนแคระดี ๆ ให้สัตว์ประหลาดน่ากลัวพวกนั้นไปแล้ว\n\nดังนั้นคำตอบคือไม่ หากยังยืนกรานจะไป Searing Gorge เจ้าต้องหาทางอื่น" },
            { "344:2100518901:1349183355", "ข้าไม่ควรบอกเรื่องนี้ด้วยซ้ำ แต่หากเจ้าฝ่าสัตว์ทั้งเล็กใหญ่ใน Badlands ไปได้ ก็อาจไปถึง Searing Gorge\n\nใช่ Badlands พวกออร์คปูถนนลัดอะไรสักอย่างไว้ใกล้ Kargath เห็นไหมว่าเราต้องเจอกับพวกโง่แบบไหน! เปิดประตูหลังสู่นรกเนี่ยนะ? พวกมันคิดอะไรกันอยู่?" },
            { "13:873543391:1986713163", "คงกระพันหรือ?" },
            { "117:725256730:679511046", "เจ้าโง่เอ๋ย ควรฟังคำเตือนของข้า ไม่มีใครคงกระพัน จำคำแนะนำนี้ไว้ให้ดี" },
            { "354:799800015:86545575", "เอาอย่างนี้ ในเมื่อเจ้าคิดว่าตัวเองเป็นวีรชน หากเจ้าผ่าน Badlands ไป Searing Gorge แล้วนำของที่พิสูจน์ความกล้ากลับมาให้ข้า ข้าจะดูว่าพอหากุญแจให้เจ้าได้ไหม\n\nตรงมุมตะวันออกเฉียงใต้สุดของ Searing Gorge มีสาวที่แข็งแกร่งเกือบเท่าข้า ชื่อ Margol the Rager บางทีเจ้าควรไปดู" },
        },
    },
    [8436] = {
        name = "Zamael Lunthistle",
        lines = {
            { "63:975746804:1895734509", "สรรเสริญ Elune! หลายปีแล้วที่ข้าไม่มีผู้มาเยือน" },
            { "442:555721994:583103355", "ตอนเป็นไนต์เอลฟ์หนุ่มใน Darkshore ข้าพบคนไม่น่าไว้ใจกลุ่มหนึ่งที่เรียกว่า Twilight's Hammer พวกเขาบางคนผูกมิตรกับข้า และน่าละอายที่ท้ายที่สุดข้าทิ้งศรัทธาใน Elune แล้วหันไปรับความเกลียดชังของ Twilight's Hammer\n\nจนกระทั่ง Elune ส่งนิมิตมาหา ข้าจึงตื่นจากความมืดมัวที่ตกอยู่ในฐานะผู้ติดตามเหล่า Old God\n\nเพื่อสำนึกผิด ข้าจึงเริ่มเขียนคำอธิษฐานถึง Elune" },
            { "403:448881039:356601867", "บนแผ่นจารึกทองคำบริสุทธิ์ ข้าสลักความสำนึกผิด ความละอาย ความเสียใจ และความโศกเศร้าทั้งหมดลงไป โชคร้ายที่ Twilight's Hammer พบแผ่นจารึกแล้วตราหน้าว่าข้าลบหลู่ศาสนา ข้าถูกประหารทันที ทั้งที่คำอธิษฐานถึง Elune ยังไม่เสร็จ บัดนี้ข้าเป็นวิญญาณที่ถูกผูกไว้กับโลก ไม่อาจข้ามไป Nether ถูกขังในกรงนี้เพื่อเตือนผู้ที่คิดทรยศศรัทธาของ Twilight's Hammer" },
        },
    },
    [8479] = {
        name = "Kalaran Windblade",
        lines = {
            { "24:110682958:2130733570", "ข้าจะได้แก้แค้น" },
            { "284:685295419:1564542451 R 67:2053173442:1816999330", "บิดาข้าถูกพวกโสมมที่อาศัยใน Cauldron สังหาร คำวิงวอนขอความช่วยเหลือจากผู้ปกครอง Stormwind ไม่เคยได้รับการรับฟัง ไม่เลย พวกเขาไม่อยากยอมรับด้วยซ้ำว่าโลกส่วนนี้มีอยู่ อย่าว่าแต่จะส่งกองทัพอันล้ำค่ามาอำนวยความยุติธรรม\n\nข้าต้องการแก้แค้น ชาว{race} ง่าย ๆ แค่นั้น ในโลกนี้จะมีเหตุใดเร่าร้อนไปกว่านี้อีก?" },
            { "429:278953955:1381684650", "อย่างที่เห็น ข้ามีเพียงตัวคนเดียวกับผู้ติดตามงุ่มง่ามอีกคน กำลังของคนแคระดาร์กไอรอนและสัตว์ที่อยู่ใต้อำนาจ Ragnaros ย่อมเอาชนะข้าได้แน่หากลุยลำพัง แต่ข้ามั่นใจอย่างยิ่งว่านักผจญภัยที่กล้าและทะเยอทะยานเช่นเจ้าจะรับมือผู้อาศัยใน Cauldron ได้ไม่ยาก หากเลือกช่วยข้า ข้าจะตอบแทนด้วยทรัพย์สมบัติเกินกว่าที่เจ้าจะฝันถึง" },
        },
    },
    [8509] = {
        name = "Squire Maltrake",
        lines = {
            { "32:1940229697:54784571", "ข้ามีชีวิตอยู่เพียงเพื่อรับใช้นายท่าน" },
        },
    },
    [14624] = {
        name = "Master Smith Burninate",
        lines = {
            { "118:345184042:981971346", "ข้าชื่อ Burninate ถนัดงานตีเหล็ก... แล้วก็ เอ่อ... ขายอาหารกับน้ำเป็นงานเสริมนิดหน่อย สนใจเนื้อไหม?" },
            { "43:565821631:1748122497 N 215:1441107006:1467135694", "เจ้าทำทุกอย่างที่ข้าขอแล้ว {name} ที่นี่ไม่มีงานให้เจ้าต่อแล้วจริง ๆ หากอยากก้าวหน้าในฐานะเจ้าหน้าที่ Thorium Brotherhood จงไปคุยกับ Lokhtos Darkbargainer ที่ Grim Guzzler ใน Blackrock Depths\n\nลาก่อน!" },
        },
    },
    [14626] = {
        name = "Taskmaster Scrange",
        lines = {
            { "304:779291799:1562843986", "ในฐานะผู้ควบคุมงานประจำค่ายนี้ หน้าที่ของข้าคือทำให้แน่ใจว่าธุรกิจ งาน การพักผ่อน และการหย่อนใจทุกรูปแบบที่นี่มีความน่าเบื่อหน่ายอยู่ในระดับหนึ่ง\n\nหากงานที่เจ้าถูกสั่งให้ทำง่ายและไร้เรื่องจุกจิกเกินไป จงรายงานข้าทันที" },
        },
    },
    [14627] = {
        name = "Hansel Heavyhands",
        lines = {
            { "193:128211863:1659245187", "เวลา Lolo ไม่อยากให้เบียร์ล้ำค่าหกหรือชุดน้อย ๆ ของเขาเปื้อน ข้าก็ถูกเรียกมา ใช่แล้ว Hansel คนนี้คือคนแคระที่พวกเขาใช้มอบความยุติธรรมเล็กน้อย และความเจ็บปวดมหาศาล" },
        },
    },
    [14628] = {
        name = "Evonice Sootsmoker",
        lines = {
            { "128:395074332:1763804314", "เราเลือกทิ้งความคุ้มครองและความสะดวกสบายใน Depths เพื่อแสวงประโยชน์... เอ่อ หมายถึง... อืม ใช่แล้ว สำรวจโลกต่างหาก" },
        },
    },
    [14634] = {
        name = "Lookout Captain Lolo Longstriker",
        lines = {
            { "120:788719694:1255398559 R 177:1614016093:1967370818", "ใช่แล้ว ข้าตาบอดเหมือนค้างคาว! แถมเมาเหมือน... เอ่อ เมาเหมือนอะไรที่เมาได้นั่นแหละ\n\nข้าจะบอกให้ ชาว{race} เหล้านี่แหละที่ทำให้ประสาทสัมผัสข้าเฉียบคม ใคร ๆ ก็รู้ว่าเมื่อเสียประสาทสัมผัสหนึ่งไป ประสาทสัมผัสอื่นจะไวขึ้น ประสาทสัมผัสด้านความเมาของข้าตอนนี้ยอดเยี่ยมมาก" },
        },
    },
    [344] = {
        name = "Magistrate Solomon",
        lines = {
            { "12:1540116447:1834606614 C 110:2087613198:1543334332 R 87:2009393540:1789481575", "{class}ผู้มาอยู่ต่อหน้าศาลแห่ง Lakeshire ในอาณาจักร Stormwind ผู้นี้คือใคร? จงแจ้งธุระที่เจ้ามายังเมืองนี้ ชาว{race} ภัยจากออร์คที่คุกคามอาณาจักรใหญ่หลวงเกินกว่าจะเสียเวลาพูดคุยไร้สาระ" },
        },
    },
    [9536] = {
        name = "Maxwort Uberglint",
        lines = {
            { "108:1709736470:819598736", "การแสวงหาความมั่งคั่งคือเป้าหมายเดียวของก็อบลินที่น่าเคารพ\n\nเอาละ อาจเป็นความมั่งคั่ง... กับความตายที่ยิ่งใหญ่และอึกทึกด้วย!" },
        },
    },
    [9177] = {
        name = "Oralius",
        lines = {
            { "46:1960011236:1246399124", "ยืนตรง ทหาร!\n\nWinky! ขานรับ!" },
        },
    },
    [9562] = {
        name = "Helendis Riverhorn",
        lines = {
            { "11:927657569:725753248 R 1:46:46", "สวัสดี ชาว{race}" },
        },
    },
    [9459] = {
        name = "Cyrus Therepentous",
        lines = {
            { "45:1762653645:59244558", "มีแต่คนโง่เท่านั้นที่กล้ารบกวนข้าในรัง" },
            { "141:1115948835:1574051819 R 49:730662558:692352538", "<ดวงตาของ Cyrus ส่องสว่าง>\n\nข้าควรกลืนเจ้าทั้งตัว หรือปล่อยให้มีชีวิตต่อ?\n\nบางทีเจ้าอาจยังมีประโยชน์อยู่บ้าง...\n\nจงท้าสู้กับลูกสมุนของข้า ชาว{race} รอดให้ได้ แล้วนำหลักฐานชัยชนะกลับมาให้ข้า" },
        },
    },
    [9836] = {
        name = "Mathredis Firestar",
        lines = {
            { "15:1219643316:24870841 R 487:614234110:2133605625", "พวกมันสูญหายไปแล้ว ชาว{race} คัมภีร์ที่เหล่าปรมาจารย์เอลฟ์เขียน กระจัดกระจายไปทั่วโลกเมื่อ Scourge ถูกปล่อยเข้าโจมตี Quel'Thalas\n\nบัดนี้เราตามหาคัมภีร์เหล่านี้ เพื่อค้นความลับที่บรรจุไว้ และฟื้นพลังที่เคยมี\n\nข้ากำลังหาสิบเล่มที่อาจารย์ Kariel Winthalus เขียน หากเจ้าพบคัมภีร์ จงยอมให้ข้าดูดซับคุณสมบัติเวทมนตร์ของมัน แล้วข้าจะสร้างส่วนผสมแห่งพลังให้เจ้า... แน่นอนว่าทุกสิ่งมีราคา ราคาของข้าสูง แต่เจ้าก็ต้องจ่าย" },
            { "175:1679151772:1622356419", "อา เช่นนั้น... เจ้าพบมันแล้ว\n\n<Mathredis ชี้ไปยังหนังสือที่เจ้าถืออยู่>\n\nเก็บส่วนประกอบที่จำเป็นแล้วหรือยัง?\n\nสิ่งที่ระบุไว้ในคัมภีร์ไง เจ้าโง่!" },
        },
    },
    [11146] = {
        name = "Ironus Coldsteel",
        lines = {
            { "11:927657569:725753248 R 1:46:46", "สวัสดี ชาว{race}" },
        },
    },
    [4949] = {
        name = "Thrall",
        lines = {
            { "47:842523805:98237399 N 444:14572685:1943527086", "สมาชิก Horde ทุกคนเท่าเทียมกันในสายตาข้า {name} เราต่างแบกรับความทุกข์มามาก หากไร้ภูมิปัญญาและเกียรติ เราก็คงไม่ต่างจาก Scourge หรือเผ่าของข้าสมัยที่เลือดแปดเปื้อนด้วยปีศาจ Mannoroth\n\nหน้าที่เจ้าคือช่วย Horde และปกป้องวิถีชีวิตของเรา แต่ก็ต้องรู้ว่าเมื่อใดควรละเว้นชีวิตและเมตตา ทั้งต่อมิตรและศัตรู\n\nจงเข้าใจให้ดี นี่คือ Horde ยุคใหม่ มิใช่กองทัพที่ปีศาจสร้างขึ้นและไร้เจตจำนงเสรี" },
            { "195:1905721221:1075549777", "Shattered Hand ส่งสายลับแทรกซึมทั่วป้อมส่วนบนของ Blackrock ได้แล้ว แม้การรวบรวมข้อมูลจะช้า แต่สิ่งที่ค้นพบก็เป็นเรื่องที่มองข้ามไม่ได้" },
            { "206:1040213716:2015665526", "ดูเหมือนอิทธิพลของฝูงมังกรดำจะแผ่พ้น Burning Steppes เข้าไปถึงอาณาจักร Stormwind! แต่ตอนนี้ผู้ช่วงชิงอำนาจถูกเปิดโปงและขับไล่แล้ว" },
            { "475:1309520869:1389765472", "จริงแล้ว แม่พันธุ์แห่งฝูงมังกรดำใช้ภาพลวงตาและกลอุบายปลอมเป็นสมาชิกในราชสำนัก ร้ายกว่านั้น นางยังควบคุม Highlord คนปัจจุบันของ Stormwind คือ Bolvar Fordragon\n\nไม่แปลกเลยที่มีคำตัดสินทางทหารโง่เขลาเช่นนั้น การเคลื่อนทัพ Alliance ช่วงหลังทำเรางุนงงมาตลอด ตอนนี้เข้าใจแล้วว่ามังกรดำพยายามแบ่งแยกอาณาจักร ทำลายจากภายใน" },
            { "41:577682658:1743197560 R 453:1781586241:371837571", "<Thrall หัวเราะ>\n\nเจ้ายังต้องเรียนรู้อีกมาก ชาว{race}\n\nเจ้ายังเด็กเกินกว่าจะจำสงครามและการนองเลือดในอดีตได้ เด็กเกินกว่าจะจำภาระคำสาปที่เผ่าของเราแบกรับ\n\nความสัมพันธ์กับ Alliance ตอนนี้เปราะบาง มีการปะทะและศึกย่อยเกิดขึ้น แต่ก็ยังมีสันติภาพ สิ่งที่เผ่าของเราไม่เคยรู้จักมาหลายพันปี เจ้าจะยอมทิ้งมันแล้วพาเราสู่ปากเหวแห่งความโกลาหลอีกครั้ง แต่คราวนี้เจอศัตรูใหม่หรือ? ศัตรูที่จะไม่หยุดจนกว่าพวกเราจะถูกทำลายหมด?" },
            { "4:1331361033:177261765 N 222:1804307009:1555598715 R 54:607592897:190078", "ไม่ {name} เจ้าไม่ได้ทำ แต่ข้าไม่โทษ เพราะจิตใจเจ้าคล้ายข้าตอนหนุ่ม ใจร้อน ขบถ และมักไม่มีความคิดที่เป็นเรื่องเป็นราวสักอย่าง! คุณสมบัติที่ตอนนี้ข้าแสดงออกไม่ได้แล้ว\n\nพอเรื่องคร่ำครวญ ชาว{race} ข้ามีงานให้เจ้า งานที่เจ้าอาจไม่รอดกลับมา" },
            { "45:522811702:1593612071 N 302:216742515:752108190 N 1:46:46", "<Thrall หัวเราะ>\n\nรับรู้แล้ว... ทีนี้ตั้งใจฟัง {name} Onyxia แม่พันธุ์แห่งฝูงมังกรดำ ถูกขับจากตำแหน่งอำนาจใน Stormwind นางหนีไปยังรังใน Dustwallow Marsh\n\nเราปล่อยให้นางอยู่ใกล้เมืองหลวงของเราเช่นนั้นไม่ได้ ต้องโจมตีก่อนถูกโจมตี!\n\nข้าต้องการให้นางถูกทำลาย {name}" },
            { "47:842523805:98237399 N 444:14572685:1943527086", "สมาชิก Horde ทุกคนเท่าเทียมกันในสายตาข้า {name} เราต่างแบกรับความทุกข์มามาก หากไร้ภูมิปัญญาและเกียรติ เราก็คงไม่ต่างจาก Scourge หรือเผ่าของข้าสมัยที่เลือดแปดเปื้อนด้วยปีศาจ Mannoroth\n\nหน้าที่เจ้าคือช่วย Horde และปกป้องวิถีชีวิตของเรา แต่ก็ต้องรู้ว่าเมื่อใดควรละเว้นชีวิตและเมตตา ทั้งต่อมิตรและศัตรู\n\nจงเข้าใจให้ดี นี่คือ Horde ยุคใหม่ มิใช่กองทัพที่ปีศาจสร้างขึ้นและไร้เจตจำนงเสรี" },
            { "486:2048872706:426638668", "ควรอธิบายให้เจ้ารู้ว่าศัตรูของเราทำถึงเพียงใดเพื่อซ่อนตัวอยู่ใต้จมูกเรา\n\nก่อนอื่นจงรู้ไว้ ศัตรูของเราคือ Shadow Council ไม่ว่าข้าจะมอบงานใด หรือขอให้เจ้าต่อกรกับใคร จงจำข้อเท็จจริงนี้\n\nCouncil มีลัทธิมากมาย แต่ก็เพียงเพื่อปิดบังการกระทำจากคนโง่\n\nกลุ่มอย่าง Burning Blade, Argus Wake และ Searing Blade ล้วนเป็นเครื่องมือของ Council จงมองว่าเป็นพวกเดียวกัน" },
        },
    },
    [8888] = {
        name = "Franclorn Forgewright",
        lines = {
            { "11:927657569:725753248 R 82:67606778:1380570037", "สวัสดี ชาว{race} ข้าคือ Franclorn Forgewright เจ้ามาเรียนรู้เรื่อง Spire และดาร์กไอรอนหรือ?" },
            { "367:946621259:1242666986", "ข้าไม่มีทางเลือก อย่างน้อยก็คิดเช่นนั้น ข้าจะทนเห็น Thaurissan ถูกทำลาย และยืนเคียงข้างราชากับประชาชนของพระองค์\n\nภายใต้การควบคุมของ Ragnaros ราชา Dagran Thaurissan ควักหัวใจภูเขาแห่งนี้ออกแล้วสร้าง Blackrock Spire ขึ้น เราทำงานไม่รู้เหน็ดเหนื่อยเพื่อสร้างเมืองคนแคระที่ยิ่งใหญ่กว่าเมืองหรือป้อมใดทั้งก่อนหน้านั้น... และที่จะมีภายหลัง" },
            { "410:2025229979:1657967214", "ข้ายืนมองความเสื่อมทรามของ Ragnaros ซึมเข้าสู่หัวใจและจิตใจของชนชาติดาร์กไอรอน เผ่าที่เคยมีเกียรติกลับถูกผลักสู่ความบ้า... สู่ความชั่วร้าย\n\nเมื่อสร้าง Spire เสร็จ ความปรารถนาจะมีชีวิตท่ามกลางคนของข้าก็มลาย ข้าจากไปในฐานะวีรชนของชาติดาร์กไอรอนยุคใหม่ สุสานนี้ถูกตั้งไว้ตรงทางเข้าเมืองที่ข้าออกแบบและสร้าง เพื่อเป็นเกียรติแก่ความพยายามของข้า" },
            { "161:1903139210:1220487228 N 250:2005671282:1482933927", "ค้อนใหญ่ Ironfel ของข้าถูกส่งต่อให้หัวหน้าสถาปนิกคนใหม่ Fineous Darkvire คนที่มีเจตนาน่ารังเกียจและฝีมือเพียงน้อยนิด\n\nนี่คือส่วนที่เจ้าต้องช่วย {name} ข้าต้องการให้หยุดเขา เขาไร้ความสามารถเกินกว่าจะใช้พลังแท้จริงของ Ironfel แต่หากผู้สืบทอดมีฝีมือใช้มันได้เต็มศักยภาพ สิ่งสร้างของพวกเขาอาจสร้างหายนะให้โลกนี้" },
        },
    },
    [9021] = {
        name = "Kharan Mighthammer",
        lines = {
            { "28:280068448:1794041961 R 53:1327278406:1155384293", "จัดการให้จบเสีย ชาว{race}โสโครก\n\n<Kharan ก้มหน้าเผยลำคอสั้นป้อม>" },
            { "14:2091915250:1481885435", "ทุกอย่างสูญสิ้นแล้ว..." },
            { "25:936955220:1809662356 R 70:1058523424:1771882420", "เจ้าคิดว่าข้าโง่หรือ ชาว{race}? ทำเช่นนั้นก็เหมือนข้าลงนามประหารนางเอง! ทำไมข้าต้องไว้ใจเจ้า?" },
            { "18:679859303:1753642058 R 366:1705809136:1091210067", "ถ้าเช่นนั้นฟังให้ดี ชาว{race}\n\nหลายเดือนก่อน ผู้ปกครอง Lakeshire ส่งทูตไป Ironforge วิงวอนพระราชาให้ช่วยรับมือการรุกรานของ Blackrock จาก Redridge และ Burning Steppes\n\nองค์หญิง Moira อาสาช่วย แม้ข้าจะทัดทาน ข้าได้รับทหารยามชั้นยอดยี่สิบคนมาปกป้ององค์หญิงระหว่างการเดินทางอันตรายจาก Loch ไป Lakeshire" },
            { "196:914588628:1269681253", "<Kharan ถอนหายใจ>\n\nข้าคิดว่า... คิดว่าเจ้าพูดถูก\n\nGor'shak บอกว่าผู้นำสงครามของเจ้ามีแผนใหญ่ แผนที่อาจเปลี่ยนวิธีที่ Alliance กับ Horde ปฏิบัติต่อกัน เจ้ารู้อะไรบ้าง?" },
            { "408:1212796269:1769402187", "<Kharan กระแอม>\n\nเราผ่านอุโมงค์ Searing Gorge เข้าสู่แดนร้างที่ถูกทำลายของหุบผานั้น เมื่อมองย้อนกลับไป ทุกอย่างเงียบอย่างน่าขนลุก ภัยเดียวที่พบคือสัตว์ป่า ซึ่งคนของข้าจัดการได้ง่าย\n\nเราไปถึง Blackrock Mountain อย่างไม่ยากเย็น และผ่านสิ่งก่อสร้าง Stonewrought โดยไม่มีอุปสรรคเลย" },
            { "489:1223556435:1203108783", "ขณะข้าม Burning Steppes เราถูกซุ่มโจมตี ต้องมีราวร้อยตน... คนแคระดาร์กไอรอน! พวกมันปรากฏออกจากกำแพง จากหินใน Steppes จากทุกรอยแยกและซอกมุมที่เห็น กรูเข้ารุมจนทหารยามและวีรชนใจกล้าไม่กี่คนที่ยอมร่วมภารกิจรับมือไม่ไหว\n\nสิ่งหนึ่งชัดเจน นี่เป็นการซุ่มโจมตีที่วางแผนอย่างดี ราวกับรู้ทุกก้าวของเราก่อนจะลงมือเสียอีก..." },
            { "205:1987272107:130011422", "จะเกิดขึ้นได้อย่างไรอีก? ต้องมีคนบอกดาร์กไอรอนแน่\n\n<Kharan ชูกำปั้นใส่เจ้า>\n\nข้าสาบาน หากได้ออกไป ข้าจะใช้ชีวิตที่เหลือตามหาคนทรยศ" },
            { "466:172253708:170725592 R 1:46:46", "ข้าเล่าถึงไหนแล้ว? อ้อ เราถูกจับ ทหารยามชั้นยอดถูกประหารตรงนั้น พวกมันไว้ชีวิตข้าแล้วพาองค์หญิงไปบนหลังแกะ ข้าถูกนำไปห้องคุมขังใน Slag Pit ก่อนย้ายมาคุกนี้\n\nข้าเดาว่ายังมีชีวิตเพราะพวกมันอยากเรียกค่าไถ่ชีวิตอันน่าสมเพช หรืออาจเพราะความโหดร้าย อยากให้ข้าหวนคิดถึงเรื่องเดิมตลอดไป ความเสียใจคือผู้คุมที่โหดร้ายที่สุด ชาว{race}" },
            { "152:470944276:1339080260", "ตอนนี้นางอยู่เคียงข้างจักรพรรดิ Thaurissan เขาใช้เวททรงพลังบางอย่างเปลี่ยนความคิดนาง... ส่วนข้าก็นั่งอยู่นี่ ช่วยอะไรไม่ได้เลย" },
        },
    },
    [9077] = {
        name = "Warlord Goretooth",
        lines = {
            { "48:1136124116:2023477164 N 264:1761489526:587555954", "<Goretooth ถ่มน้ำลาย>\n\nข้าเป็นนักรบแห่ง Horde {name} รู้ว่าศัตรูอยู่ในป้อมที่เดินทางจาก Kargath ไม่ถึงวัน คอยวางแผนเล่นงานเรา ก็ทำให้ข้าเดือดดาล\n\nข้าอยากหลุดจากพันธะหน้าที่ แล้วทำลายพวกมันให้หมดในนามผู้นำสงครามเหลือเกิน\n\nอนิจจา เราทุกคนมีบทบาทที่ต้องทำ" },
            { "290:213748407:1645570086", "ข้าอิจฉาเจ้าจริง ๆ ได้รบในนาม Horde ณ แนวหน้าแห่งความขัดแย้ง ส่วนงานข้าคือบัญชาการ\n\nแน่นอนว่ายามหนุ่มข้าใช้ชีวิตตามฝัน จนความทรงจำทำให้ทนวัยชราได้ ตอนนี้ข้าดื่มด่ำเกียรติแห่งชัยชนะและรสขมของความพ่ายแพ้ ผ่านทหารใต้บัญชาทั้งสิ้น" },
            { "9:210796755:966998181 N 280:1799257122:224862004", "ข้าฝัน {name}... ใช่ ข้าฝัน ในฝันข้าตายพันครั้งด้วยวิธีต่างกันพันแบบ บางคนอาจเรียกว่าฝันร้าย แต่ไม่ใช่ข้า! ในฝันข้าตายกลางศึก ทุกครั้งที่ข้าตาย ศัตรู Horde หมื่นตนล้มลงต่อหน้า ช่างรุ่งโรจน์!" },
            { "42:770109841:166320463 N 152:624608788:569785178", "ใช่ ข้าดูออกเพียงมองเจ้า {name} เจ้าทำให้นึกถึงตัวข้าตอนเป็นนักรบหนุ่มแห่ง Horde\n\nเจ้าจะไปได้ไกลในชีวิต และไกลยิ่งกว่าในความตายแน่นอน\n\n<Goretooth ทำความเคารพ>" },
            { "49:1707738994:1641914241 N 135:1821925356:868367672", "แถมยังถ่อมตัว... บางทีถึงเวลาเจ้าแล้ว {name}\n\nพร้อมจะเข้าป้อมออร์ค Blackrock หรือยัง? ก่อความพินาศ? ฉีกฐานรากป้อมภูเขาให้ย่อยยับ?" },
            { "41:216056323:78719478 N 24:537925403:723161260 N 39:666187790:2082117677", "ข้าไม่เคยสงสัยเจ้าแม้แต่วินาทีเดียว {name}\n\nนี่คำสั่งของเจ้า {name} ข้ารู้ว่าเจ้าจะไม่ทำให้ผิดหวัง" },
        },
    },
    [9080] = {
        name = "Lexlort",
        lines = {
            { "33:1384746678:581384687", "ข้าไม่มีเวลาให้ใครรบกวน" },
        },
    },
    [9544] = {
        name = "Yuka Screwspigot",
        lines = {
            { "19:1340549959:112175745", "ต้องการเสบียงไหม?" },
        },
    },
    [16032] = {
        name = "Falrin Treeshaper",
        lines = {
            { "40:1657601088:116395732", "มีอะไรอีก? ไม่เห็นหรือว่าข้าค่อนข้างยุ่ง?" },
        },
    },
    [16033] = {
        name = "Bodley",
        lines = {
            { "398:1671359648:2015312886", "เจ้ามองเห็นข้าหรือ? รู้ไหมว่าข้าถูกเมินมากแค่ไหนเพราะไม่มีใครเห็น? ในที่สุดมีคนคุยด้วย ช่างสดชื่น!\n\nสมาชิกที่ยังมีชีวิตในกองทหารรับจ้างเก่าคงส่งเจ้ามา ข้าพูดถูกไหม? แน่นอนอยู่แล้ว!\n\nแต่พอเรื่องคุยเล่น เจ้ากับข้ามีงานอีกมาก หากจะแก้ความผิดและคืนวิญญาณให้ Lord Valthalak!" },
            { "N 409:1422429355:746147618", "{name}! กลับมาเพียงเพื่อคุยกับข้าหรือ? ช่างมีน้ำใจ แถมชุดนั้นก็ดูดีมาก!\n\nเจ้าไม่รู้หรอกว่าข้ารู้สึกดีเพียงใดที่ได้พบ ที่นี่เหงาเหลือเกิน เพราะคนทึ่มพวกนี้ส่วนใหญ่มองข้าไม่เห็น เจ้าทำสิ่งยิ่งใหญ่ให้พวกเรา ข้าจะไม่มีวันลืม!\n\nขอบใจที่แวะทัก อย่าห่างหายไปนานนักล่ะ" },
            { "27:1628891320:1366070256 N 455:2073356845:75931105", "เรื่องง่ายมาก {name} กองทหารรับจ้างเก่าของข้า The Veiled Blade รับผิดภารกิจและผิดเวลา\n\nคนจ้างคือก็อบลินนักลักลอบขนของจาก Booty Bay ชื่อ Gremnik Rizzlesprang ผู้โลภอยากได้ตำราเวท Lord Valthalak หรืออาจมีความแค้นเก่า? คงไม่มีวันรู้แล้ว เพราะไม่นานมานี้ Gremnik ถูกกลุ่มนักฆ่าวิญญาณของ Valthalak สังหาร พวกมันอันตรายมากจริง ๆ เมื่อมารวมกันมากพอ\n\nข้าเล่าถึงไหนแล้วนะ?" },
            { "497:702260912:257928255", "อ้อ ใช่แล้ว\n\nพวกเราบุกลึกเข้าไปในส่วนบนของ Blackrock Spire ต่อกรกับจ้าวผู้เป็นผู้นำของมัน นี่เป็นช่วงก่อน Drakkisath ถ้าถามข้าก็ไม่ฉลาดนัก แต่ Anthion Harmon หัวหน้าของเรา ซึ่งเจ้าเคยพบแล้ว ชอบความท้าทายเสมอ\n\nน่าแปลก ทุกอย่างเป็นไปตามแผน จนถึงตอนงัดตำราเวท Valthalak ออกจากนิ้วที่แข็งทื่อของเขา จากนั้นทุกอย่างก็พัง\n\nให้เล่าต่อไหม? ตาเจ้าเริ่มเหม่อแล้วนะ" },
            { "499:1816936989:1081529492", "<Bodley มองเจ้าอย่างสงสัยแต่เล่าต่อ...>\n\nเราถือตำราเวทอยู่ แล้วดวงตาทั้งสี่ของ Kormok โอเกอร์สองหัวผู้ใช้ศาสตร์ปลุกศพของเรา ก็มีแววประหลาด มันน่าขนลุก เพราะตาคู่ที่สองมักดูไร้ชีวิตเหมือนตาวัว เข้าใจไหม? จู่ ๆ เขาก็ยื่นมือกระชากเครื่องรางที่ Valthalak สวมอยู่\n\nทั้งกองวุ่นวาย บางคนบอกให้ปล่อยไว้ ส่วนคนอื่นอยากได้ไว้เอง" },
            { "495:1384229661:450337130", "โธ่ ไม่ต้องขอร้องหรอก! อย่างไรเรื่องก็เกือบจบแล้ว\n\nทั้งกองยืนทะเลาะแย่งเครื่องรางกลางห้องมหึมานั้น และเจ้าก็รู้ว่าเสียงสะท้อนแค่ไหน! สุดท้ายมันแตกเป็นสามชิ้น เราทอยลูกเต๋าแบ่งให้คนหรือกลุ่มต่าง ๆ\n\nหลังจากนั้นจำไม่ชัด เพราะราวเวลานั้นเองวิญญาณ Valthalak ก็ปรากฏแล้วเริ่มเรียกนักฆ่าวิญญาณออกมาทั้งฝูง" },
            { "469:1131517924:2020752836", "ใจเย็นก่อน!\n\n<Bodley พึมพำบ่นความใจร้อนของคนเป็น>\n\nอย่างที่เล่า วิญญาณ Lord Valthalak กับนักฆ่าวิญญาณที่เขาเรียกด้วยศาสตร์ปลุกศพเริ่มโจมตีเรา ตอนนั้นเราไม่อยู่ในสภาพสู้กลับ จึงหนี ข้ายังจำได้ว่าช่วงหนึ่ง Mor Grayhoof ดรูอิดคนหนึ่งของเราลื่นตกลงไปในส่วนล่างของ Spire\n\nที่เหลือก็อย่างที่ว่า กลายเป็นอดีตไปแล้ว" },
            { "416:765365661:1818964157 N 87:399380964:842232082", "หลังจากนั้นพวกเราแยกย้าย นั่นแหละที่เกิดขึ้น คงมีเรื่องบาดหมางมากไป... สะสมมาพักใหญ่ และเรื่องเครื่องรางก็เป็นฟางเส้นสุดท้ายที่ทำให้หลังโคโดหัก\n\nตั้งแต่นั้น ข้ารับใช้ Valthalak ก็ตามเก็บเราทีละคน ผู้ถือชิ้นส่วนส่วนใหญ่ตายแล้ว วิญญาณแปดเปื้อนด้วยเศษวิญญาณ Valthalak ที่อยู่ในนั้น\n\nจึงดีใจที่เจ้ามา {name} ด้วยความช่วยเหลือของเจ้า เราจะประกอบเครื่องรางแล้วคืนให้ Lord Valthalak ได้!" },
        },
    },
    [2921] = {
        name = "Lotwil Veriatus",
        lines = {
            { "31:2017460366:1250796404 C 216:1470006976:1894494031", "เหมาะเหม็งเหลือเกินที่เจ้าแวะมา {class}\n\nข้าชื่อ Lotwil Veriatus สมาชิกผู้ก่อตั้งสมัชชาผู้รู้แจ้งแห่งศาสตร์อาร์เคน การเล่นแร่แปรธาตุ และวิทยาศาสตร์วิศวกรรม เรามุ่งรวมศาสตร์แห่งปัญญาของ Azeroth ให้เป็นสำนักความรู้ที่ครอบคลุมหนึ่งเดียว" },
        },
    },
    [5204] = {
        name = "Apothecary Zinge",
        lines = {
            { "135:1037649446:874408516", "หากจะมีที่ยืนในโลกนี้ เราต้องทำด้วยการศึกษา และเจตจำนงที่จะเพิกเฉยต่อสัญชาตญาณมนุษย์ที่กำลังเลือนหาย" },
        },
    },
    [9078] = {
        name = "Shadowmage Vivian Lagrave",
        lines = {
            { { "82:1990371242:1263267834", "83:196524288:494098205" }, "เจ้าหนู เจ้ามาทันเวลาช่วยกองสำรวจ Kargath พอดี" },
        },
    },
    [1267] = {
        name = "Ragnar Thunderbrew",
        lines = {
            { "212:954752241:647225348", "ยินดีต้อนรับสู่ Thunderbrew Distillery ที่พ่อผู้เป็นที่รัก Arkilus Thunderbrew ก่อตั้ง ข้าดูแลต่อมาตั้งแต่ Grimbooze พี่ชายหายไปในความเมาเมื่อหลายฤดูเก็บเกี่ยวก่อน" },
        },
    },
    [9081] = {
        name = "Galamav the Marksman",
        lines = {
            { "15:734732691:2023458259", "ข้าไม่เคยพลาด..." },
        },
    },
    [2784] = {
        name = "King Magni Bronzebeard",
        lines = {
            { "22:103036130:210292086 C 1:46:46", "ยินดีต้อนรับสู่ Ironforge {class}" },
            { "52:462669584:851548609 C 362:673225972:1615923418 N 85:101690090:1220917831", "อา เจ้าเคยมาแล้วสินะ ยินดีต้อนรับสู่ Ironforge อย่างยิ่ง {class}\n\nเมืองนี้คือศูนย์กลางตระกูล Bronzebeard เราเป็นชนชาติอันเก่าแก่และภาคภูมิ ช่างฝีมือของเราไม่เป็นรองใคร ไม่มีงานโลหะหรือหินใดประณีตเท่าฝีมือคนแคระ\n\nเรายังเป็นหนึ่งในเหล่านักสำรวจผู้กล้าที่สุดแห่ง Azeroth หากเจ้ารักการผจญภัย ก็จะพบมิตรที่ดีในหมู่เรา\n\nขอบใจที่คุยกับข้า {name} ไปพร้อมพรแห่งตระกูล Bronzebeard เถิด\n\nขอให้เจ้าและคนของเจ้าอยู่ดีมีสุข" },
            { "52:462669584:851548609 C 375:532934412:1660418207 N 85:101690090:1220917831", "อา มาถึงแล้วสินะ ยินดีต้อนรับสู่ Ironforge นะ {class}\n\nเมืองนี้เป็นที่ตั้งของตระกูล Bronzebeard เราเป็นชนเก่าแก่ที่ภาคภูมิใจในตน และช่างของเราเป็นหนึ่งไม่มีสอง เจ้าจะหางานโลหะหรืองานหินที่ประณีตกว่าฝีมือคนแคระได้ยาก\n\nเรายังเป็นนักสำรวจที่กล้าที่สุดกลุ่มหนึ่งใน Azeroth ถ้าเจ้าชอบผจญภัย เจ้าจะพบเพื่อนร่วมทางในหมู่พวกเรา\n\nขอบใจที่มาคุยกับข้า {name} ไปเถอะ ขอพรจากตระกูล Bronzebeard คุ้มครองเจ้า\n\nขอให้เจ้าและชนของเจ้าอยู่ดีมีสุข" },
        },
    },
    [9563] = {
        name = "Ragged John",
        lines = {
            { "26:1841793931:1339753514", "เจ้าต้องการอะไร? <สะอึก>" },
            { "395:669087685:377226103", "วันนั้น Windsor อารมณ์เสียเป็นพิเศษ เชื่อข้าเถอะ สำหรับเขานั่นถือว่าสุดยอดแล้ว เขาพูดไม่หยุดว่า “รู้สึกมีอะไรผิดปกติ” ไม่ได้พูดเล่นเลย!\n\nเราอยู่กลาง Blackrock Mountain ตอนสัตว์โสโครกบุก ข้าหมายถึงออร์ค แน่นอน ตั้งใจฟังหน่อยสิ! มีแต่เสียงคำรามกับเหล็กกระทบกันตอนพวกมันกรูมา" },
            { "189:325279718:1683772118", "เอาละ <สะอึก>... ว่าแต่เจ้าดูคุ้นนะ <สะอึก> เคยเล่าหรือยังว่าข้ากับ Windsor สู้กับออร์คสามสิ... เอ่อ พัน... ล้านตนได้อย่างไร?\n\nใจเย็น สหาย เรื่องนี้เด็ด!" },
            { "67:1517704939:767173964", "ด้วยความยินดี... ขอข้าดื่มด่ำช่วงเวลานี้อีกนิด" },
            { "35:228561402:469167286 N 115:1682754889:1249902077", "ข้าคนเดียวสู้ห้าสิบออร์คหรือ? ข้าไม่โง่ {name} พ่อเคยสอนว่า “การเสียเครดิตคือส่วนที่ดีกว่าของแครกเกอร์” หรืออะไรทำนองนั้น และข้าก็รู้ว่าหมายถึงอะไร" },
            { "230:158610218:1887769124", "เอาละ เอาละ อย่างไรก็เถอะ ข้าเลยค่อย ๆ หลบเข้าความมืด\n\nWindsor ไม่พอใจนัก เพราะเดิมก็หงุดหงิดอยู่แล้ว เขาเริ่มเหวี่ยง Ironfoe แล้วตะโกนใส่ออร์คราวคนบ้า" },
            { "415:1930453314:1369192584", "ใช่แล้ว ไม่เคยได้ยิน Ironfoe หรือ? ค้อนสังหารออร์คในตำนานน่ะ? ใช่ ค้อนของ Windsor เขาบอกว่า Franclorn Forgewright สร้างให้ปู่เทียดของเขาด้วยตัวเอง Franclorn Forgewright คนนั้นเลย ดาร์กไอรอนผู้คิด Stonewrought สถาปัต... งานสร้างต่าง ๆ นั่นแหละ เขายังว่าค้อนมีแฝดที่ Franclorn เก็บไว้เอง คิดว่าชื่อ Ironfel หรืออะไรทำนองนั้น" },
            { "288:1109067002:62597354", "ข้าเล่าถึงไหนแล้ว? อ้อ พวกออร์คกรูใส่ Windsor แต่เขาไม่ขยับแม้แต่นิ้ว ยืนตระหง่านรับพวกมันทีละสิบ ข้าเห็นเพียงแสง Ironfoe กับเลือดมากมาย เป็นอย่างนี้หลายชั่วโมง หรืออาจหลายวัน จำไม่ได้ อย่างไรในที่สุดก็หยุด" },
            { { "23:1411798778:1937711080 N 20:1033506164:839908146 N 299:247698459:1850409405", "23:1411798778:1937711080 N 18:303138609:908171153 N 299:247698459:1850409405" }, "ตายหรือ? เจ้าบ้าหรือ {name}? ขอทีเถอะ คุณ {name}! Windsor ไม่ตายเพราะออร์คแค่ห้าสิบตนหรอก ข้ามั่นใจเท่าที่ไส้กรอกเลือด Thelsamar เป็นอาหารอร่อยที่สุดในโลก เขายืนอยู่นั่น มีชิ้นส่วนออร์คเต็มตัวตั้งแต่หัวจรดเท้า ชุ่มเลือดราวสิบแปดชั้น แต่ยังมีชีวิตแน่นอน... และโกรธมาก ๆ" },
            { "354:824342687:1968534353", "ทำไมพูดว่าเขาตายอยู่ได้? ใครบอก? ข้าไม่เคยบอกว่าเขาตาย\n\nแค่หายตัวไปเท่านั้น\n\nดูเหมือนเราไปอยู่กลางศึกใหญ่ระหว่างออร์คกับดาร์กไอรอน พวกออร์คเป็นสุนัขโสมมน่าสมเพช จึงออกมาแต่เช้า วางกับดักกับสิ่งชั่วร้ายอื่นที่เจ้าคงไม่เข้าใจ" },
            { { "176:1828828128:1390504335", "175:733281659:1974561259" }, "คนแคระไม่เมาหรอก ข้าแค่ซุ่มซ่ามหน่อย\n\nอย่างไร Windsor หรือ? ข้าว่าอยู่แถว Blackrock Depths เมืองดาร์กไอรอนน่ะ เผื่อพวกเจ้าไม่รู้หนังสือ" },
            { "332:1477146775:332167854", "ช้าก่อน! ข้ากำลังจะเล่าถึง!\n\nเขายืนอยู่ตรงนั้น เลือดกับเครื่องในหยดทั่วตัว แล้วใครมา?\n\nดาร์กไอรอน! เจ้าไม่ได้ฟังข้าเลยหรือ??\n\nพวกนี้ฉลาดกว่าออร์ค Blackrock หน่อย มันเตรียมพร้อมมา ที่ว่าพร้อมคือมีราว 300 ตน... <สะอึก> ขอโทษที" },
            { { "299:1344681882:1807911679", "298:1340611831:1403127022" }, "หากไม่รู้อะไรดีกว่านี้ ข้าคงคิดว่าเจ้าเป็นพวก “พิเศษ” ที่เราเรียกว่าโทรกก์\n\nWindsor ไม่ได้มีเรื่องกับดาร์กไอรอน สหายสนิทของปู่เทียดเขาก็เป็นดาร์กไอรอน นั่นคงเป็นเหตุที่กองทัพพวกนั้นไม่ฆ่าเขาทันทีที่เห็น" },
            { "334:1684642815:2056511650", "ในที่สุด! เอานิ้วอุดหูไว้ สมองเจ้าอาจโตขึ้นห้าเบอร์ ข้ากลัวมันไหลออกมา\n\nดาร์กไอรอนไว้ชีวิตแล้วจับเขาเป็นนักโทษ หัวหน้าที่สำคัญตัวจองหอง ชื่อ Thauris อะไรสักอย่าง ยึด Ironfoe ไป นั่นเป็นครั้งสุดท้ายที่ข้าเห็น Windsor... <สะอึก> ขอโทษที" },
        },
    },
    [10182] = {
        name = "Rexxar",
        lines = {
            { "11:927657569:725753248 C 91:737387914:1129038695", "สวัสดี {class} ข้าคือ Rexxar ยอดนักรบแห่ง Horde ผู้รับใช้ Thrall และนายแห่งสัตว์ป่า" },
        },
    },
    [10776] = {
        name = "Finkle Einhorn",
        lines = {
            { "244:1943811714:1367503400", "เฮ้อ... ข้าอยากสูบบุหรี่กับรับสัมผัสจากสาวโนมงาม ๆ ไม่จำเป็นต้องเรียงตามนั้นนะ!\n\nข้าติดในท้องเจ้านั่นมาหลายเดือน! นี่วันอะไรแล้ว? ช่างเถอะ สิ่งสำคัญคือออกมาได้แล้ว\n\nวู้ฮู้!" },
            { "30:139656726:2036201077", "ได้อย่างไรหรือ?? เรื่องยาวน่ะ" },
            { "414:1819324560:988961393", "เอาละ! ข้าลงไปบ่อลาวาแถว Molten Span เพื่อทดสอบชุดลาวา ทุกอย่างดีมาก ข้าว่ายในนั้นได้โดยไม่บาดเจ็บแม้แต่นิด!\n\nข้ากำลังว่ายท่ากรรเชียงสบาย ๆ จู่ ๆ เจ้านั่นก็โผล่มากลืนข้าทั้งตัว! หากไม่มีชุดลาวากับเครื่องจ่ายอาหารเม็ดในตัว ข้าคงไม่รอด!" },
            { "84:413808442:1697468251", "ข้าสัมผัสความไม่เชื่อในน้ำเสียงเจ้านะ แต่ใช่ มันเกิดแบบนั้นจริง" },
            { { "286:2087720143:234532616", "285:279001996:763570738" }, "ข้าออกจากท้องอสูรยังไม่ถึงสองนาที ก็มีคนถามเรื่องเข้าห้องน้ำแล้วหรือ??? หากเจ้าไม่ใช่ผู้ช่วยชีวิต ข้าคงตบให้หายโง่เพราะคำถามนั้นแล้ว!\n\nอย่างไรก็เถอะ ข้าซาบซึ้งความช่วยเหลือ บางทีอาจตอบแทนได้?" },
            { "430:569608399:1697779288", "คำว่า “จ่าย” อาจไม่เหมาะนัก ตอนติดในท้องมัน ข้าคิดได้ว่า:\n\nสัตว์ตัวนี้อยู่ในแมกมาร้อนลุกเป็นไฟ แต่ไม่บาดเจ็บจากไฟเลย!\n\nหากหาหนังไร้ตำหนิได้สักผืน ข้าจะนำกลับไปให้สหายรัก Malyfous Darkhammer ที่ Everlook หากมีใครใช้หนังสัตว์แบบนี้ทำอะไรได้ ก็ต้องเป็นเขา" },
            { "42:1782815793:547030800", "เจ้าช่วยส่งข้อความให้ข้าหน่อยได้ไหม?" },
        },
    },
    [14368] = {
        name = "Lorekeeper Lydros",
        lines = {
            { "186:268814170:2124793909", "เจ้าต้องเข้าใจว่า การจัดหมวดหมู่ประสบการณ์ที่สั่งสมมา 10,000 ปีทำให้ข้ามองชีวิตต่างออกไป ความทุกข์ยากของเจ้าในปัจจุบันไร้ความหมาย" },
            { "364:580291728:1700943897", "โอ้ นายหนุ่มตีโพยตีพายเสียใหญ่ ราวกับแบกชะตาโลกไว้บนบ่าคนเดียว มีแต่ผู้มีอายุขัยที่มองโลกบิดเบี้ยวเช่นนั้น\n\nอนิจจา เขาทิ้งความลับเวทเล็กน้อยไว้ให้ข้า... คัมภีร์หรือเรื่องไร้สาระทำนองนั้น ข้าไม่ต้องการเวทกระจ้อยร่อย แต่บางทีเจ้าอาจสนใจอาคมของมัน" },
        },
    },
    [14394] = {
        name = "Major Mattingly",
        lines = {
            { "30:1253169995:949284017", "ข้ามีชีวิตเพียงเพื่อรับใช้พระราชาของเรา" },
            { "119:1436341585:1144596363 N 1:46:46", "บางทีวันหนึ่ง ผลงานของเจ้าต่อ Alliance จะยิ่งใหญ่เท่าเหล่าวีรชนที่เห็นวันนี้ จงให้เกียรติพวกเขา {name}" },
        },
    },
    [2285] = {
        name = "Count Remington Ridgewell",
        lines = {
            { "173:1148030301:908546089", "ตระกูลข้ามีชุดสะสมเครื่องประดับและงานศิลป์งดงามที่สุดในหมู่ขุนนาง Stormwind!\n\nและเราก็อยากเพิ่มชุดสะสมอยู่เสมอ..." },
        },
    },
    [10260] = {
        name = "Kibler",
        lines = {
            { "60:1823232178:1205274057", "ยินดีต้อนรับสู่ Kibler's Exotic Pets! วันนี้เจ้าช่วยอะไรข้าได้บ้าง??" },
        },
    },
    [10740] = {
        name = "Awbee",
        lines = {
            { "26:1524024268:1311999257", "ข้า... บาดเจ็บหนัก..." },
            { "8:2102215530:680664386 R 339:298067335:1905789938", "ฟังนะ ชาว{race} ฟังให้ดี...\n\nผู้ขี่มังกรมาในยามค่ำบนหลังมังกรดำ โจมตีอย่างรวดเร็วและแม่นยำถึงตาย ชิงลูกมังกรอย่างข้า แล้วหลบหนีใต้ม่านมืด\n\nข้ามองอย่างหวาดผวาเมื่อพวกมันใช้พี่น้องของข้าทดลอง จากแก่นพลังของเราจะสร้างฝูงมังกรโครมาติกขึ้น" },
            { "409:1700276841:2477474", "Nefarian สั่งให้ทำลายตัวอย่างที่ไม่เหมาะทันที แต่อสูรน่ารังเกียจพวกนี้ไม่ยอมทำจนกว่าจะทรมาน “มากพอ” ก่อน\n\nเมื่อเรา “แตกสลาย” หมด มันจะรวบรวมผู้ที่เหลือโยนให้พวกอันธพาล ใช้ร่างเราเป็นเครื่องมือในเกมวิปริต โยนลงลาวา หรือเลวร้ายกว่านั้น สู่อ้อมแขนที่รออยู่ของกองทัพกระหายเลือดข้างล่าง" },
            { "190:52277979:140904683 R 89:123760877:439054774", "เจ้ามาถึงตอนพวกมันกำลังจะโยนข้าลงไปให้ปีศาจเบื้องล่าง ข้าขอบใจ บางทีข้า หรือพูดให้ถูก พวกเราฝูงมังกรน้ำเงิน อาจช่วยเจ้าต่อได้?\n\nเจ้ามาไกลและเสี่ยงมากแล้ว ชาว{race} จะไปต่อเพื่อสู้ Nefarian กับกองทัพ Blackrock ของเขาหรือไม่?" },
        },
    },
    [10918] = {
        name = "Lorax",
        lines = {
            { "29:266325493:13065531", "อย่าทดสอบความอดทนข้า ผู้มีอายุขัย" },
            { "18:1789104139:726295124 R 65:991359963:725471062", "หุบปาก ชาว{race} ไม่เช่นนั้นข้าจะดึงลิ้นจากกะโหลกมาใช้พันเขาให้อุ่น" },
            { "164:936632209:1961250528", "ถามว่าข้าทำอะไร แน่นอน ข้าครุ่นคิด คร่ำครวญ เกลียด วางแผน เมื่อครบวงจรก็ครุ่นคิดใหม่ เจ้าต้องการอะไรจากข้า? ข้ามีเรื่องในหัวมากนัก" },
            { "202:925189688:1570756562", "เจ้าหรือ?\n\n<Lorax หัวเราะ>\n\nน่าสงสัยนัก\n\nข้ายืนในซากนี้และฝันถึงวันที่จับโจรน่าสมเพช Goraluk Anvilcrack ได้\n\nเรามีข้อตกลง แต่เขาผิดสัญญา ทรยศ" },
            { "184:185493693:1339810326", "ข้าจะสอนการตีขึ้นรูปแบบปีศาจ แลกกับวิญญาณเขา วิญญาณออร์ค Blackrock มีค่าน้อยนัก แต่ยามลำบากเช่นนี้ วิญญาณใด ๆ ก็ยังดีกว่าไม่มี" },
            { "398:1039148258:407415485", "เขาเอา Unforged Rune Covered Breastplate ที่ใช้สร้าง Demon Forged Breastplate แล้วหนีไปไม่จ่าย แต่ข้าไม่โง่... เกราะที่ยังไม่ตีขึ้นรูปนั้นไร้ประโยชน์หากไม่มีความรู้หรือสูตรที่จะใช้ความรู้นั้น\n\nข้าสงสัย... เขานั่งปลอดภัยในเมือง Blackrock Spire พยายามสร้างของจากวัตถุดิบอยู่หรือ? ข้ารู้ว่าเขาไม่กล้าออกมา!" },
        },
    },
    [7776] = {
        name = "Talo Thornhoof",
        lines = {
            { "35:222759289:1744940837 N 28:189944634:725473947", "ฟังเรื่องจากผู้อาวุโสเถิด {name} ข้ามีอีกมากจะเล่า..." },
        },
    },
    [10917] = {
        name = "Aurius",
        lines = {
            { "457:2138135592:520638922", "ดีที่เห็นผู้อื่นสู้ Scourge ใน Stratholme เพราะพวกมันแข็งแกร่งที่สุดที่นี่\n\nสวัสดี ข้าคือ Aurius เคยเป็นพาลาดิน Silver Hand แต่เหมือนคนที่ศรัทธาสั่นคลอน... ข้าตกต่ำ Scourge ล่อลวงจนเกือบเปลี่ยนเป็นเดธไนต์!\n\nเมื่อรู้ถึงอันตราย ข้าหนีมาโบสถ์นี้ เป็นที่ศักดิ์สิทธิ์ที่พาลาดินคนแรก Uther the Lightbringer ได้รับการแต่งตั้งเข้าภาคี Silver Hand" },
            { "149:1079937384:1150596488", "ข้ามีเวลาในโลกไม่มาก แต่หากแสงสว่างประสงค์ ก็คงพอทำชะตาให้สำเร็จ เมื่อเจ้าเผชิญ Baron Rivendare ข้าจะอยู่ด้วย" },
            { "75:1888908172:325243987 N 59:173886075:1982232939", "ปล่อยข้าไว้ บาดแผลหนักนัก เกรงว่าจะทนไม่ไหว ขอบใจ {name} ข้าจะตายที่นี่ แต่เพราะเจ้า... จะตายอย่างสงบ" },
        },
    },
    [11035] = {
        name = "Betina Bigglezink",
        lines = {
            { "69:1512289620:1272132990", "Plaguelands เป็นที่เหมาะอย่างยิ่งสำหรับโจมตี Scourge!" },
        },
    },
    [11216] = {
        name = "Eva Sarkhoff",
        lines = {
            { { "113:1062201177:1719200306", "115:2145448056:26087026" }, "สวัสดี เจ้าน้อย ข้าคือ Eva Sarkhoff และนี่สามี Lucien ยินดีที่ได้รู้จัก" },
            { { "217:772909393:1273518658", "218:1744026749:505747896" }, "แน่นอน เราเคยเป็นคนรับใช้ตระกูล Barov ที่ตอนนี้เรียก Scholomance\n\nข้าเป็นหัวหน้าแม่บ้าน ส่วน Lucien เป็นพ่อบ้านนาย Barov\n\nเราทำงานให้หลายสิบปี จนกระทั่ง...\n\n<Eva ร้องไห้>" },
            { { "448:439063084:1799191773", "449:732583023:651239030" }, "โอ้ มันสยองเหลือเกิน ตระกูล Barov เคยเต็มด้วยชีวิตและความงาม คฤหาสน์เป็นบ้านหลักท่ามกลางอาณาเขตกว้างใหญ่\n\nLucien กับข้าสังเกตว่าวันผ่านไป พวก Barov ยิ่งหดหู่และสิ้นหวัง นายกับนายหญิงมักถูกความหวาดระแวงและโทสะครอบงำ กลางคืนได้ยินทะเลาะในห้อง เท่าที่เราเข้าใจ ความโลภของพวกเขาทะลักออกมาเหมือนเขื่อนแตก" },
            { "491:1246284971:1076543696", "เราสงสัยว่าเพื่อเก็บสมบัติและดินแดนให้ยาวเกินอายุขัย ตระกูล Barov ทำข้อตกลงกับจอมเวทมนุษย์ทรงพลัง Kel'Thuzad\n\n<Eva สั่นสะท้าน>\n\nข้อตกลงนั้นให้กำเนิดโรงเรียนศาสตร์ปลุกศพ สถานที่ที่ให้กำเนิด Cult of the Damned และจะกลายเป็นศูนย์กลาง\n\nแต่ละสัปดาห์ บ้าน Barov ทรุดโทรมลงเรื่อย ๆ...\n\nสิ่งมืดเริ่มอาศัยตามปีกคฤหาสน์ ดูแลรักษาไม่ไหว... และน่าขยะแขยง" },
            { "478:1264137086:232928841", "แล้วจะไปไหน? นั่นคือทุกสิ่งที่เรารู้ เคยรู้ และจะรู้\n\nท้ายที่สุดเราขาดการติดต่อกับ Barov แล้วถูกแยกจากครัวเรือน ไม่รู้เกิดอะไรกับคนรับใช้อื่น รู้เพียงว่ามีเสียงกรีดร้อง จากความทรมาน\n\nเมื่อไม่มีที่ไป Lucien กับข้าจำต้องซ่อนในห้อง กลางวันที่โรงเรียนค่อนข้างเงียบ เขาจะย่องออกหาอาหารกับน้ำ" },
            { "443:612613868:1437023377", "เราทำเช่นนี้ราวหกเดือน ดูบ้านเปลี่ยนไปอย่างสยอง สัตว์ประหลาดชั่วเดินทั่วคฤหาสน์ตามใจ นักลัทธิมืดเต็มทุกนิ้วพร้อมเครื่องประกอบพิธีและบูชายัญ เรารู้ว่าซ่อนได้อีกไม่นาน\n\nเป็นดังคิด เราถูกพบและจับ พวกมันถอดเสื้อผ้าทั้งหมดแล้ววางเราในวงเลือด เราอยู่ตรงนั้นหลายวัน เปลือยกายและหวาดกลัว" },
            { { "294:322109643:145111589", "296:1035238720:1992252018" }, "พันธนาการหรือ? ในโลกมีสิ่งที่จองจำได้มากกว่าซี่กรงกับตรวน เจ้าน้อย อันเดดล้อมเรา ทรมานไม่หยุดด้วยการกระทำวิปริตน่าสยอง\n\nในที่สุดเขาก็มา แนะนำตัวว่า Doctor Theolen Krastinov เราได้รู้จักในชื่อ “จอมเชือด”" },
            { "319:1873516805:1352767001", "ในที่สุดเราเข้าใจว่าเสียงกรีดร้องมาจากไหน จอมเชือดทำให้เจ็บในแบบที่ไม่เคยรู้ว่ามี ใช้เราทดลองนับครั้งไม่ถ้วนเพื่อสร้างโรคระบาด\n\nวันกลายเป็นสัปดาห์ เราคงตายตั้งแต่วันแรก หากเจ้าชั่วโหดร้ายไม่ใช้เวทคงชีวิตไว้" },
            { "485:1336196082:981173708", "จอมเชือดพูดถึง “เลือดผู้บริสุทธิ์” และนายมืด “Kirtonos” ว่าต้องเอาใจอย่างไร\n\nในที่สุดอสูรก็ทดลองเสร็จ ชีวิตเราถูกสูบหมด วิญญาณแตกสลาย อ้อมกอดแสนหวานของความตายมาถึง เราต้อนรับด้วยแขนเปิด แต่ด้วยความโหดร้ายไม่สิ้นสุด มันดึงเรากลับจากประตูมรณะ\n\nเราถูกคงชีวิตไว้แล้วโยนให้กูลหิวโหย เขาหัวเราะขณะดูปีศาจรุมกินร่างเรา" },
            { "126:312834582:49548565", "เราไม่รู้สึกอะไร วิญญาณค้างอยู่ที่นี่ ออกไปไม่ได้จนกว่าจะพบซากและให้วิญญาณพักสงบ" },
        },
    },
    [14358] = {
        name = "Shen'dralar Ancient",
        lines = {
            { "82:1431152451:166065294", "ออกจากที่นี่ คนแปลกหน้า ก่อนมันกลืนเจ้าเหมือนทุกสิ่งที่เคยแตะ" },
            { "46:523737936:1895504706", "เจ้ารู้จักไฮบอร์นหรือไม่? Shen'dralar?" },
            { "408:271865122:699388863", "Shen'dralar เป็นนักอาร์เคนที่ราชินี Azshara ยกย่องที่สุด ภายในกำแพงนี้เองที่จัดการคำสั่งสำคัญที่สุดของนาง มักเป็นความลับ\n\nหลังบ่อน้ำถูกทำลายและความเฉื่อยชาครอบงำไฮบอร์นกับกลุ่มไนต์เอลฟ์ชั้นรอง เจ้าชาย Tortheldrin แห่ง Eldre'Thalas เริ่มสร้างเสาพลังที่เห็นทั่วห้องโถงปีกตะวันตก" },
            { "251:448606275:822462266", "เจ้าชายวางแผนขังปีศาจพลังมหาศาลหลังสนามพลังใหญ่ เสาจะส่งพลังแฝงเข้ารักษาสนาม\n\nขณะถูกขัง Immol'thar จะเป็นแหล่งพลังให้ชาว Eldre'Thalas" },
            { "440:2086702621:1668211517", "พลังที่ดูดมาหล่อเลี้ยงเวทไฮบอร์น ให้ผู้ในกำแพง Eldre'Thalas สนองความหิวเวทที่เพิ่มไม่จบ\n\nหลายพันปีผ่านไป สมดุลพลังที่ใช้ขัง Immol'thar และหล่อเลี้ยงชีวิตเริ่มเปลี่ยน ต้นทุนพันธนาการสูงกว่าอัตราที่ดูดมาแจกจ่าย จากเคยได้สุทธิกลับขาดทุน" },
            { "170:1467561321:1246401835", "ผีไฮบอร์นที่เจ้าเห็นเดินในลานกับห้องโถง Eldre'Thalas ไม่ได้ตายเพราะโอเกอร์ Gordok หรือเซเทียร์บุก แต่ด้วยมือเจ้าชายเอง!" },
            { "433:1030143595:176595659", "ผู้คนถูกทำลายเพื่อรักษาชีวิตอมตะและพลังแทบไร้ขอบเขตของเจ้าชาย พลังที่เคยแบ่งให้คนนับพันตอนนี้ไหลเข้าเขากับผู้คลั่ง Shen'dralar ผู้รอดไม่กี่คนส่งพลังเข้าเสาโดยตรงเพื่อขัง Immol'thar ต่อ\n\nหากปีศาจหลุด มันคงทำลายเศษซากที่เหลือของฐานเวทซึ่งเคยยิ่งใหญ่แน่" },
        },
    },
    [14374] = {
        name = "Scholar Runethorn",
        lines = {
            { "89:1284079159:1240904321", "โอ้ สยอง! โศกนาฏกรรม! เราใกล้ค้นพบครั้งใหญ่ แต่ทุกอย่างอาจสูญสิ้น" },
        },
    },
    [14381] = {
        name = "Lorekeeper Javon",
        lines = {
            { "147:913707177:1635029312", "ความรู้ที่บันทึกมา 10,000 ปีมักดึงคนผิดประเภทสู่ Athenaeum หนังสือถูกขโมย ได้คืน แล้วถูกขโมยซ้ำทุกวัน" },
        },
    },
    [14382] = {
        name = "Lorekeeper Mykos",
        lines = {
            { "219:2139163271:1265391691", "Kildrath มักทำเรื่องให้ใหญ่เกินจริง ตัวอย่าง “Garona: A Study on Stealth and Treachery” ถูกขโมยกว่า 400 ครั้ง\n\nตรา Athenaeum คุ้มครองตำรา กันผู้ไม่มีสิทธิ์อ่าน" },
        },
    },
    [14383] = {
        name = "Lorekeeper Kildrath",
        lines = {
            { "21:469558140:220205195 R 103:832094459:1593223645", "มันถูกขโมย ชาว{race}! หนังสือมีค่าที่สุดสามเล่ม หากนำคืน เจ้าจะได้รางวัลแน่นอน" },
        },
    },
    [14322] = {
        name = "Stomper Kreeg",
        lines = {
            { "190:1461681456:1524800878", "เจ้าเป็นนายใหญ่แล้วใช่ไหม? ราชาใหม่จงเจริญ!\n\nKreeg ให้เจ้าดูเหล้า Gordok เหล้าโอเกอร์ดีที่สุดในเหล้าทั้งหมด แล้วเหล้า Gordok ก็ดีที่สุดในเหล้าโอเกอร์! นายใหญ่ซื้อจากข้าหน่อยไหม?!" },
        },
    },
    [14325] = {
        name = "Captain Kromcrush",
        lines = {
            { "79:577825805:2059563139", "มาเดินทำอะไรแถวนี้? ทำไมพวกตัวเล็กไม่อยู่ในตรวน?!" },
            { "60:102466573:118969401", "ตอนนี้เจ้าแข็งแกร่งที่สุด! สรรเสริญราชาใหม่แห่ง Gordok!" },
            { "71:1520758029:1214555312", "ข้ายังเห็นพวกมันถืออาวุธหรือ? ทำไมเจ้าปล่อยให้เก็บอาวุธไว้?!" },
        },
    },
    [4488] = {
        name = "Parqual Fintallas",
        lines = {
            { "78:1725064404:554685908 C 1:63:63", "ดีเสมอที่มีคนอยากคุยกับข้า เป็นอย่างไรบ้าง {class}?" },
            { "21:635942169:1946931071 N 83:1477188853:776835213", "ทีนี้ตอบข้า {name}:\nสิ่งมีชีวิตใดกลายเป็น Lich King ก่อนแพร่โรคระบาดทั่ว Lordaeron?" },
        },
    },
    [4967] = {
        name = "Archmage Tervosh",
        lines = {
            { "10:1401179418:1568553899 N 47:1851064743:444027059", "ยินดีที่พบ {name} เราต้องคุยให้กระชับ เพราะมีงานอีกมาก" },
        },
    },
    [6546] = {
        name = "Tabetha",
        lines = {
            { "28:291626483:1395108252 C 39:1240497713:1796478414", "ภารกิจเจ้าคงสำคัญมาก {class} จึงพาเข้ามาลึกในบึงเช่นนี้..." },
        },
    },
    [7804] = {
        name = "Trenton Lighthammer",
        lines = {
            { "402:1651981921:1992826686 R 90:1326289095:146675151", "Sul'thraze... ครั้งแรกที่ได้ยินชื่อนี้ ข้าอายุราวเจ้า ตอนนั้นมันไม่มีความหมายต่อข้า เช่นเดียวกับที่ไม่มีต่อเจ้าตอนนี้ จนกองโทรลล์จาก Zul'Farrak มาทำลายแผ่นดิน ข้าจึงเข้าใจ... และหวาดกลัว\n\nหลายคนจะบอกว่า Splitblade of Suffering ไม่มีจริง เป็นเพียงตำนานหรือข่าวลือไว้ขู่เด็กให้ว่าง่าย แต่เชื่อข้าเถิด {race} มันมีจริง\n\n<Trenton เหม่อลอยขณะลูบรอยแผลเป็นขรุขระบนใบหน้า>" },
            { "114:715642440:546929214", "แยกเป็นสองเพื่อรวมเป็นหนึ่ง ดาบคู่ผูกพันกับ Zul'Farrak\n\nเมื่อพบดาบทั้งคู่ Sul'thraze จะถือกำเนิดใหม่" },
        },
    },
    [8115] = {
        name = "Witch Doctor Uzer'i",
        lines = {
            { "220:1925086993:1990905325", "ในวิญญาณ หรือ “muisek” ของสิ่งมีชีวิตที่เราต่อสู้ มีพลังมหาศาลอยู่\n\nจงมองเข้าไปในตน เรียนรู้ใช้พลังวิญญาณของเจ้า แล้วจะแข็งแกร่งกว่าที่เคยจินตนาการ" },
            { "320:1784421592:1523062007 N 48:1601872451:1106721413", "แถบนี้มีสิ่งมีชีวิตมากมายที่เป็นพันธมิตรกับไนต์เอลฟ์ เอลฟ์เข้าถึงพลังภายในของพวกมันมานาน ถึงเวลาที่ Horde จะได้รับประโยชน์เช่นเดียวกัน ข้าคิดวิธีกักเก็บพลังนี้มาใช้เพื่อเราได้แล้ว\n\nอย่าสงสัยคำข้า {name} ช่วยข้า แล้วเจ้าจะเห็นว่าข้าพูดจริง" },
        },
    },
    [3188] = {
        name = "Master Gadrin",
        lines = {
            { "40:1994791632:1870492299 C 20:1583043552:52603427", "มีเรื่องอยากคุยหรือ {class}... มานั่งข้างข้าสิ" },
        },
    },
    [5598] = {
        name = "Atal'ai Exile",
        lines = {
            { "22:1282567420:1989914143", "เจ้าขอสิ่งใดจากข้า?" },
        },
    },
    [2055] = {
        name = "Master Apothecary Faranell",
        lines = {
            { "165:1141457973:1829040397", "Royal Apothecary Society จะทำตามคำเรียกของ Dark Lady เพื่อค้นพบ New Plague และขับ Arthas กับกองทัพ Scourge นอกรีตให้พ้นโลกอย่างถาวร" },
        },
    },
    [12238] = {
        name = "Zaetar's Spirit",
        lines = {
            { "13:1979262830:30371903 R 1:46:46", "ข้าขอทักทาย {race}" },
        },
    },
    [13698] = {
        name = "Keeper Marandis",
        lines = {
            { "24:800354995:1493858772 C 221:1983579699:2079860672", "ขอ Cenarius นำทางเจ้า {class}\n\nข้ากับพี่น้องหญิงมาถึงแดนแปดเปื้อนนี้ด้วยภารกิจสำคัญยิ่งต่อ Cenarion Circle แต่ข้าขอให้เฉพาะผู้แข็งแกร่งพอมาคุยเรื่องนี้ การส่งผู้ที่อ่อนกำลังไปย่อมโง่เขลา" },
        },
    },
    [13716] = {
        name = "Celebras the Redeemed",
        lines = {
            { "72:1249191061:1376688181", "ในที่สุดข้าก็พ้นจากความเสื่อมทรามที่เคยผูกมัดกับที่นี่..." },
            { "34:1726629938:745660685 N 102:1308805795:1273924285", "ขอบใจสำหรับสิ่งที่เจ้าทำ {name}\n\nรักษาคทาให้ดี ขอให้มันช่วยเจ้าต่อสู้กับความชั่วร้ายที่รุกรานที่นี่..." },
            { "138:855601363:83651035 N 93:1468424420:1553925597", "คทาของข้า... ผ่านมาหลายปีเหลือเกิน... เจ้านำมันกลับมาแล้ว! เจ้าจะเป็นผู้กอบกู้ที่นี่อย่างแท้จริง...\n\nฟังให้ดี {name} หัวคทากับแกนจะรวมเป็นหนึ่งได้เฉพาะที่ Stone of Maraudon" },
            { "25:13577292:1479839075 N 153:1807765869:1338273740", "เกิดเรื่องเช่นนี้ได้อย่างไร {name}? เจ้าคิดว่าสิ่งอย่าง Scepter of Celebras เป็นของเล็กน้อยหรือ?\n\nครั้งนี้ข้าช่วยได้ แต่อย่าสะเพร่ากับของมีค่านี้อีก..." },
            { "496:693780263:525591269", "เมื่อพิษใน Maraudon ซึมเข้าจิต ข้าเริ่มแยกความเป็นจริงไม่ออก พี่น้องดรายแอดกังวลว่าคทาจะถูกใช้ทำชั่ว จึงแอบนำไป แยกเป็นสองส่วนแล้วซ่อนในถ้ำ\n\nไม่นานพวกนางก็ตกเป็นเหยื่อความบ้าคลั่งเช่นกัน คทาทั้งสองส่วนไร้ผู้คุ้มกันและตกไปอยู่กับ Vyletongue เอง ซาเทอร์ผู้นั้นฝากส่วนหนึ่งกับ Noxxion อสูรธาตุชั่วร้าย ส่วนอีกชิ้นยังเก็บไว้จนวันนี้" },
            { "78:437923510:38745648", "ระหว่างสองสี มีเส้นทาง\n\nพริบตาข้ามผ่านในแสง\n\nเจ้าปรากฏขึ้นจากสายน้ำ" },
            { "400:84595848:1723836584", "นานมาแล้ว ข้ากับพี่น้องดรายแอดเข้าถ้ำเพื่อปลดปล่อยวิญญาณอาข้า Zaetar ที่ถูกทรมาน แต่ความเสื่อมทรามซึ่งแพร่ทั่วถ้ำครอบงำเราในไม่ช้า เราจึงล้มลงเช่นกัน\n\nเราถูกกำหนดให้หลงในทางเดินเหล่านี้ พิษกัดกินจิตใจ...\n\nแม้วิญญาณข้าอาจพักสงบแล้ว ข้ารู้ว่าตนทำภารกิจล้มเหลว เป็นความโศกเศร้าที่ข้าต้องแบกรับ..." },
            { "301:1298565187:1136943537", "Lord Vyletongue ไม่รู้คาถาที่ใช้รวมสองส่วน จึงใช้คทาไม่ได้ แต่ตอนนี้ข้าพ้นคำสาปความเสื่อมทรามของเขาแล้ว ข้าจะช่วยได้หากเจ้านำทั้งสองชิ้นมา ทั้งหัวคทาและแกน" },
            { "148:1322737451:245323947", "ใกล้ประตู Maraudon ระหว่างทางเดินสีส้มกับสีม่วง เจ้าจะพบเส้นทางที่สาม\n\nคทาในมือเจ้าคือกุญแจ" },
            { "436:1461092857:629715998", "อา Zaetar... <Celebras เบือนหน้า>\n\nRemulos บิดาข้าพยายามห้ามเขาแล้ว...\n\nZaetar หัวแข็ง เมื่อหลงรักเจ้าหญิงธาตุดิน บิดาข้ารู้ว่าความสัมพันธ์นั้นต้องคำสาป แต่ Zaetar ไม่ยอมฟัง\n\nเซนทอร์คือผลจากความผิดพลาดนั้น พวกมันเกิดมาผิดรูปและเต็มด้วยความชิงชัง อาข้า Zaetar ถูกฆ่าโดยลูกหลานตนเอง...\n\nเจ้าหญิงชั่วร้าย Theradras ยังเฝ้าซากเขาอยู่ที่นี่ ในถ้ำผลึก" },
            { "55:516328378:1981648373 N 337:1681107039:1596462280", "ข้าเริ่มเหนื่อยแล้ว...\n\nจากตรงนี้เจ้ามองเห็นน้ำตกได้ {name}... คทาให้พลังเดินทางมาที่นี่ หากเจ้าอยากเข้าทางประตูหน้า Maraudon อีก\n\nใกล้ทางเข้าจะมีทางเดินลงใต้ถ้ำ ใช้คทาที่สถานที่ประกอบพิธีโบราณเพื่อเปิดประตูมิติ แล้วเจ้าจะกลับมาที่นี่อีกครั้ง" },
            { "498:1451608069:1175241939", "เจ้าถามถึง Remulos กับ Zaetar บุตรแห่ง Cenarius\n\nRemulos บิดาข้าแข็งแกร่งและงามสง่า ส่วน Zaetar อาข้าเจ้าเล่ห์และร่างเล็ก แม้ทั้งคู่ได้รับความเคารพพอกัน Zaetar ก็รู้สึกเสมอว่าตนเทียบไม่ได้กับเกียรติยศและความสนใจที่เขาคิดว่า Remulos ได้รับ\n\nหลังข้ากับพี่น้องเกิด Zaetar ซึ่งถูกความริษยาบังตาก็ออกไปเพื่อทำให้เหนือกว่าพี่น้องตน... เขาสร้างจุดจบขึ้นเอง ความเศร้าที่เรื่องนี้นำมาสู่ข้าไม่เคยจาง แม้เวลาผ่านไป..." },
        },
    },
    [13717] = {
        name = "Centaur Pariah",
        lines = {
            { "59:2110696829:171927977 C 286:218614324:1672715167", "ข้าไม่ต้องมีบ้านก็รู้ว่ายังมีที่ทางในโลกนี้ {class} เผ่าต่าง ๆ จะได้เห็น... ทุกเผ่า พวกเขาสู้กันเองเพื่ออะไร? เศษที่แร้งเหลือทิ้ง... แผ่นดินที่ Legion รุกราน... เฮอะ!\n\nเซนทอร์ควรภูมิใจในชาติกำเนิด มันสูงศักดิ์ไม่แพ้ไนต์เอลฟ์หรือออร์ค ถึงเวลาที่เราต้องทำตัวให้สมกับมัน!" },
        },
    },
    [1470] = {
        name = "Ghak Healtouch",
        lines = {
            { "72:993381860:1821171436", "Kali สาวน้อยแสนรักส่งเจ้าลงมาหาข้าหรือ? นางคือแก้วตาดวงใจข้า" },
            { "133:1048723462:1683279520", "ข้าว่าเจ้าคงไม่ได้มาคุยเรื่อง Kali ที่น่ารัก เอาล่ะ เรื่องยาก็ได้ มีใครเคยบอกไหมว่าเจ้าคิดอยู่เรื่องเดียว?" },
            { "32:656994364:186333910 N 136:1652918132:596526972", "ฝีมือเจ้าเกินข้าจะสอนแล้ว {name} ไปกวน Tally Berryfizz โนมที่อยู่ Tinker Town ใน Ironforge สิ อ้อ ไหน ๆ ก็ขึ้นไปแล้ว ฝากความรักให้ Kali ด้วย" },
        },
    },
    [3412] = {
        name = "Nogg",
        lines = {
            { "47:30380554:1689894063", "ถ้าวันหนึ่งมีเวลาเพิ่มอีกสักไม่กี่ชั่วโมง..." },
            { "95:1176496810:1503236799", "เจ้ามีสิทธิ์ฝึกกับครูระดับสูงขึ้นแล้ว ไปหา Roxxik เพื่อนข้าตรงนั้น" },
            { "124:1716945932:823278773", "เจ้ายังไม่มีสิทธิ์ฝึกกับข้า ไปหา Thund ข้างโต๊ะก่อน เมื่อเขาว่าพร้อมแล้วค่อยกลับมา!" },
            { "69:1333200642:119171677", "ผ่านบททดสอบแล้ว ทำได้ดี! ฝึกต่อได้แล้ว" },
            { "110:1663621918:1415091720", "ทุกวันคือบททดสอบ วันนี้ก็เช่นกัน หากเจ้าผ่านการทดสอบนี้ ข้าจะแบ่งปันความรู้ให้เจ้าบ้าง..." },
        },
    },
    [3413] = {
        name = "Sovik",
        lines = {
            { "7:989913233:66981971 N 64:262191805:698352021", "สวัสดี {name}! ถ้าไม่มีในร้าน ข้าก็มักหามาให้ได้!" },
        },
    },
    [6826] = {
        name = "Talvash del Kissel",
        lines = {
            { "130:432654681:1316413644", "เอ่อ สวัสดี! หากมาทวงค่าธรรมเนียมหรือส่งหมายเรียก คงจำข้าผิดคน เสียใจด้วยจริง ๆ!" },
        },
    },
    [7853] = {
        name = "Scooty",
        lines = {
            { "7:989913233:66981971 N 31:1956855415:37649935", "สวัสดี {name}! ข้าคือ Scooty วิศวกรผู้เชี่ยวชาญ" },
        },
    },
    [7944] = {
        name = "Tinkmaster Overspark",
        lines = {
            { "136:1546350657:119447983", "สวัสดี! หากมาขอเข้าถึงแบบวิศวกรรมโนม โปรดเตรียมบัตรสมาชิกวิศวกรโนมให้ตรวจ" },
            { "381:380290815:2099083683", "ข้าคือ Tinkmaster Overspark ผู้วางรากฐานหลักวิศวกรรมโนมสมัยใหม่ของโลกปัจจุบัน หน้าที่ข้าคือให้พลังแห่งการประดิษฐ์ส่องจากประแจ Arclight ของเราเจิดจ้ายิ่งกว่าที่อื่น!\n\nอีกอย่าง หากรู้จักแบบดี ๆ สำหรับกำจัดรังสี พอดีเรากำลังอยากได้อยู่ตอนนี้..." },
        },
    },
    [234] = {
        name = "Gryan Stoutmantle",
        lines = {
            { "224:985167846:1853146548", "ความเสื่อมทรามเลวร้ายคืบเข้า Westfall ระหว่างข้าปฏิบัติหน้าที่ในสนามรบ Lordaeron ไร่สุจริตเหล่านี้ถูกยึดเป็นที่ซ่อนอันธพาลกับฆาตกร People's Militia ต้องการเจ้าช่วย" },
        },
    },
    [2817] = {
        name = "Rigglefuzz",
        lines = {
            { "52:1219965653:1497879393 C 77:1605103324:1020402334", "เจ้าคงอับจนจึงเร่ร่อน Badlands แบบนี้ {class} อับจนเหมือนข้า\n\nหรือบางทีมาเพราะบ้า บ้าเหมือนข้า" },
        },
    },
    [6986] = {
        name = "Dran Droffers",
        lines = {
            { "163:485310421:1004930489", "ข้าชื่อ Dran Droffers ส่วนตรงนี้ Malton ลูกชายหัวทึ่ม หากต้องการของกู้คืนหรืออยากขายของเช่นนั้น เจ้าต้องคุยกับเรา!" },
        },
    },
    [656] = {
        name = "Wilder Thistlenettle",
        lines = {
            { "148:1815906412:879367695", "โจรเต็มไปหมด!\n\nน่ากลัวเหลือเกิน ถ้ำถล่มใส่เรา ข้าคิดว่าคนของบริษัทเหมืองตายหมดแล้ว รวมทั้งพี่น้องข้าที่เป็นหัวหน้าคนงาน" },
        },
    },
    [1344] = {
        name = "Prospector Ironband",
        lines = {
            { "198:1221703324:1795348045", "แม้งานที่ซากเหล่านี้อืดอาด ข้ามั่นใจว่าไม่นานจะดีขึ้น แต่ระหว่างนี้ ข้าใช้คนอย่างเจ้าได้ อยากช่วย Dwarven Explorers' Guild ไหม?" },
        },
    },
    [1356] = {
        name = "Prospector Stormpike",
        lines = {
            { "162:1120493025:1374650882", "ข้ากำลังทำงานสำคัญมาก ธุระนักสำรวจ หากไม่มีเรื่องสำคัญพอกันจะพูด ซึ่งข้าสงสัยว่าจะมี ก็ขอตัวก่อน" },
        },
    },
    [1719] = {
        name = "Warden Thelwater",
        lines = {
            { "78:1634792759:1584463998", "ทางนี้ เจ้าไร้ค่า...! ถ้าอยากทำตัวมีประโยชน์ก็ฟังเร็ว!" },
        },
    },
    [2785] = {
        name = "Theldurin the Lost",
        lines = {
            { "160:733515476:1693529053", "ถอย! อยู่ห่าง ๆ! ข้ามีดินระเบิดเต็มถุงและไม่กลัวใช้! จะระเบิดเราทั้งหมด!\n\nอ้อ ช่างเถอะ ข้านึกว่าเป็นคนอื่น..." },
        },
    },
    [2910] = {
        name = "Prospector Ryedol",
        lines = {
            { "163:927666297:465909390", "พวกสารเลวจู่โจมกลางคืน ตอนเราดื่มไปแล้วหลายแก้ว ไม่อย่างนั้นรับรองเราสู้ได้\n\nทุกคนตายแล้ว... ยกเว้นพวกเราไม่กี่คน" },
        },
    },
    [6569] = {
        name = "Gnoarn",
        lines = {
            { "248:334629072:442054687", "ที่ที่โทรกก์กับโนมโรคเรื้อนเดินเพ่นพ่านคือบ้านเรา Gnomeregan\n\nครอบครัวสูญเสีย บ้านถูกพราก เรากระจัดกระจาย\n\nโอ้ ข้าโหยหาวันสบายใน Gnomeregan แต่วันนั้นไม่เหลือแล้ว เราต้องยืนหยัด! ต้องช่วย Gnomeregan!" },
        },
    },
    [6579] = {
        name = "Shoni the Shilent",
        lines = {
            { "15:514289856:1997845451", "เพื่อ Gnomeregan!" },
        },
    },
    [6868] = {
        name = "Jarkal Mossmeld",
        lines = {
            { "14:517582074:1480288853 C 88:1628346313:1688363714", "ต้องการอะไร {class}? ข้าเชื่อว่าเจ้ามาแดนร้างนี้ด้วยเหตุอื่นนอกจากคุยเล่น" },
        },
    },
    [6142] = {
        name = "Mathiel",
        lines = {
            { "132:447754877:501909629", "ฝีมือไนต์เอลฟ์ไม่ได้จำกัดแค่ป่ากับผู้อาศัย เรารู้มากเรื่องแผ่นดินเบื้องล่างและโลหะข้างใน" },
        },
    },
    [7937] = {
        name = "High Tinker Mekkatorque",
        lines = {
            { "13:1911146197:485773127 C 59:1286373386:2043895568", "สวัสดี {class} ข้าคือ High Tinker Mekkatorque แห่งผู้ลี้ภัย Gnomeregan" },
            { "539:305382087:1875868917 N 1:46:46", "โอ้ เยี่ยมจริง! ข้ารอทูตจากชนเผ่าเจ้ามานาน ยินดีมากที่ได้รู้จัก\n\nอยากต้อนรับที่บ้านเมือง Gnomeregan แต่พวกเราเพิ่งประสบเคราะห์หนัก และเวลานี้เสียบ้านเกิดไปแล้ว\n\nอย่างไรก็ดี King Bronzebeard เป็นมิตรกับโนมเสมอ จึงเมตตาเปิดเมืองให้ในยามลำบาก\n\nหวังว่าการผจญภัยบน Azeroth จะดีต่อเจ้า และข้าหวังมีโอกาสเรียนรู้เรื่องชนเผ่าเจ้าเพิ่ม\n\nลาก่อน {name}" },
            { "540:1778604762:1132522236 N 1:46:46", "โอ้ เยี่ยมเลย! ข้ารอทูตจากชนของเจ้าอยู่ ยินดีอย่างยิ่งที่ได้รู้จักเจ้า\n\nข้าอยากต้อนรับเจ้าที่ Gnomeregan บ้านของเรา แต่ช่วงนี้ชนของเราตกอยู่ในยามลำบาก และตอนนี้เราสูญเสียบ้านเกิดไปแล้ว\n\nถึงอย่างนั้น King Bronzebeard ก็เป็นมิตรกับพวกโนมเสมอ พระองค์มีน้ำพระทัยเปิดเมืองต้อนรับเราในยามยากนี้\n\nขอให้การผจญภัยใน Azeroth ราบรื่น ข้าหวังว่าจะมีโอกาสรู้จักชนของเจ้ามากขึ้น\n\nลาก่อน {name}" },
        },
    },
    [253092] = {
        name = "Alba Fairmoon",
        lines = {
            { "240:1430729030:1964063476", "ข้าได้ยินว่าครั้งหนึ่งไร่ Westfall ส่งผลผลิตอุดมสมบูรณ์ให้ Stormwind แต่ตอนนี้ดินแห้งแล้ง ชาวไร่ส่วนใหญ่หนีไปแล้ว\n\nในนาม Darnassus ข้าอยากช่วยฟื้นแผ่นดิน เจ้าจะช่วยไหม?" },
        },
    },
    [233] = {
        name = "Farmer Saldean",
        lines = {
            { "18:1203518543:1661688794 N 82:142725761:1832487622", "ช่วงนี้ลำบากนะ {name}? หันไปทางไหนก็มีคนต้องการความช่วยเหลือ ข้ากับภรรยาก็ไม่เว้น" },
            { "18:1203518543:1661688794 N 82:142725761:1832487622", "ช่วงนี้ลำบากนะ {name}? หันไปทางไหนก็มีคนต้องการความช่วยเหลือ ข้ากับภรรยาก็ไม่เว้น" },
        },
    },
    [352] = {
        name = "Dungar Longdrink",
        lines = {
            { "133:1875145365:976283120", "สัตว์ยิ่งใหญ่พวกนี้รู้เส้นทางที่เดินเท้าหาไม่พบ มันจะพาไปเร็ว และอาจให้เห็นอะไรใหม่ระหว่างทางด้วย" },
            { { "123:118894122:358064102", "123:2137401788:808317274" }, "อยากไปไหนหรือ? จ่ายไม่กี่เหรียญ กริฟฟอนข้าก็พาไปได้เร็วกว่าม้าเร็วที่สุดเสียอีก" },
            { "122:933591052:1739870371", "อยากไปไหนล่ะ เจ้าหนุ่ม? จ่ายแค่ไม่กี่เหรียญ กริฟฟอนของข้าจะพาเจ้าไปได้ไวกว่าม้าที่เร็วที่สุดเสียอีก" },
        },
    },
    [491] = {
        name = "Quartermaster Lewis",
        lines = {
            { "84:2097255440:1597621801", "ข้าพยายามให้ Sentinel Hill มีเสบียงพร้อม ซึ่งไม่ง่ายกับเหตุการณ์มากมายที่เราเจอ" },
        },
    },
    [523] = {
        name = "Thor",
        lines = {
            { "87:1523754588:513734422", "จะไปไหน? หากอยากถึงเร็วก็ไม่ต้องหาที่อื่นแล้ว!" },
        },
    },
    [1323] = {
        name = "Osric Strang",
        lines = {
            { "115:1072725403:354220891", "ข้าขายแต่อุปกรณ์ดีที่สุด ผ่านการทดสอบไว้ใจได้ ราคาตายตัว หากอยากต่อก็ไปหาก็อบลิน" },
        },
    },
    [1325] = {
        name = "Jasper Fel",
        lines = {
            { "125:1390211006:1187660573", "พูดเบาและระวังให้มาก คำผิดในแถบนี้อาจทำให้โดนเชือดคอ ทีนี้ต้องการอะไรจากข้า?" },
        },
    },
    [11026] = {
        name = "Sprite Jumpsprocket",
        lines = {
            { "46:1597353949:1908562699", "อา วันสวยเหมาะระเบิดอะไรสักอย่าง!" },
            { "155:882822634:1683801935", "เจ้าต้องเริ่มเรียนสิ่งที่เกินความเชี่ยวชาญข้าแล้ว! คุยกับ Lilliam Sparkspindle หน้าเต็นท์นั่น จะได้เริ่มถูกทาง!" },
            { "176:178947616:1765235749", "งานแบบนี้ไม่เหมาะคนขวัญอ่อน ลุงของข้าคนหนึ่งเสียมือ! Stumpy เฒ่าผู้น่าสงสาร... เอาเถอะ หากยังสนใจ ข้าอาจสอนบางอย่างได้" },
        },
    },
    [237] = {
        name = "Farmer Furlbrow",
        lines = {
            { "217:390557658:82310635", "แถวนี้มีแต่ปัญหา ข้าบอก Saldean เจ้าโง่ให้รีบออกตอนยังทำได้ แต่เขาไม่ฟัง ข้าไม่โง่ Verna กับข้าจะไปทันทีที่ซ่อมเกวียนเสร็จ" },
        },
    },
    [238] = {
        name = "Verna Furlbrow",
        lines = {
            { "216:1173166766:489092821", "บางครั้งข้าคิดว่ามีเมฆเทาใหญ่บนฟ้าคอยเทโชคร้ายลงใส่เรา แรกถูกขับจากแผ่นดิน ตอนนี้แม้จะออก Westfall ก็ยังไม่ได้ ทุกอย่างวุ่นวาย ต้องทำอะไรสักอย่าง" },
        },
    },
    [235] = {
        name = "Salma Saldean",
        lines = {
            { "245:1666647385:1896048650", "ยินดีต้อนรับบ้านเล็ก ๆ เรา! ดีเสมอที่เห็นหน้ามิตร และแขนเจ้าแข็งแรงจัง ข้ากับสามีหาคนช่วยไร่เสมอ เมื่อคนดีส่วนใหญ่จากไป ก็หาคนแข็งแรงมาช่วยยาก" },
        },
    },
    [239] = {
        name = "Grimbooze Thunderbrew",
        lines = {
            { "142:1100051238:227472401", "ผจญภัยจากแดนใกล้ไกล\nพบผู้คนแปลกหลากหลาย\nแต่หากถามข้าเมื่อไร\nต้องทำงานง่ายให้เสร็จก่อน!" },
        },
    },
    [392] = {
        name = "Captain Grayson",
        lines = {
            { "19:336900263:1033664071 R 182:1013919038:347772758", "อย่าตกใจ {race} ข้าจากแผ่นดินนี้นานแล้ว แต่ไม่คิดทำร้ายพวกเจ้า ข้าเห็นความตายมากเกินพอ บัดนี้ปรารถนาเพียงสันติ บางทีเจ้าช่วยอุดมการณ์ข้าได้" },
        },
    },
    [1319] = {
        name = "Bryan Cross",
        lines = {
            { "115:1072725403:354220891", "ข้าขายแต่อุปกรณ์ดีที่สุด ผ่านการทดสอบไว้ใจได้ ราคาตายตัว หากอยากต่อก็ไปหาก็อบลิน" },
