    [11833] = {
        name = "Rahauro",
        lines = {
            { "10:1401179418:1568553899 C 249:819124876:578079969", "ยินดีที่ได้พบ {class} เจ้าคุยกับข้าได้ เว้นแต่มีธุระโดยตรงกับนายหญิง Magatha\n\nข้าจัดการงานส่วนใหญ่แทนนาง เพื่อให้นางจดจ่อกับเรื่องสำคัญกว่า บางทีเราอาจมีเรื่องคุยกันก่อนเจ้าขอเข้าพบนาง?" },
            { "42:1683937269:895105086 N 79:962609874:1596455950", "เชิญคุยกับข้าได้ทุกเมื่อ {name} เจ้ารับใช้ Magatha ได้ดี ข้ามั่นใจว่านางจะเรียกใช้เจ้าอีกในภายหน้า" },
        },
    },
    [11835] = {
        name = "Theodore Griffs",
        lines = {
            { "7:989913233:66981971 N 1:46:46", "สวัสดี {name}" },
        },
    },
    [12866] = {
        name = "Myriam Moonsinger",
        lines = {
            { "381:1118392857:349007586", "ข้าไม่ได้คิดร้ายต่อเจ้า ข้ากำลังสอดแนมควิลบอร์และจดบันทึกกิจกรรมของพวกมัน ผู้คนของข้าสังเกตว่ามีสิ่งผิดปกติ เป็นพลังที่แผ่ออกมาหรือความมืด จากบริเวณนี้ ข้าจึงมาสืบ และสิ่งที่พบก็น่าหวั่นใจมาก\n\nดูเหมือนมีทูตอันเดดผู้ทรงพลังด้านอาร์เคนอยู่ ข้าไม่เชื่อว่าเขาเป็น Forsaken... ข้าคิดว่าเลวร้ายกว่านั้น" },
        },
    },
    [14450] = {
        name = "Orphan Matron Nightingale",
        lines = {
            { "26:1203380529:141839051 C 422:732240777:2004582149", "สงครามมีราคาที่ต้องจ่าย {class}... ราคาที่มักถูกมองข้าม นั่นคือเด็กกำพร้า เด็กที่เสียพ่อแม่ให้ความขัดแย้งมากมายเกินไปซึ่งโหมทั่ว Azeroth เด็กเหล่านี้เมื่อไม่มีใครให้พึ่ง ก็มักมาอยู่ที่นี่จนโตพอจะดูแลตนเอง\n\nปีละครั้งเป็นเวลาหนึ่งสัปดาห์ในฤดูใบไม้ผลิ Alliance จะสละเวลามอบบางสิ่งตอบแทนผู้บริสุทธิ์เหล่านี้ ช่วงเวลานี้เรียกว่า Children's Week" },
        },
    },
    [3419] = {
        name = "Apothecary Zamah",
        lines = {
            { "82:785779028:1538183973", "เพื่อให้ผู้คนเราอยู่รอด เราต้องศึกษาวิถีธรรมชาติและเรียนรู้ความลับของมัน" },
        },
    },
    [5767] = {
        name = "Nalpak",
        lines = {
            { "72:1749225005:10557110", "ความหวังเดียวของเราคือสร้างสิ่งดีจากสถานการณ์ที่เลวร้ายอยู่แล้ว" },
        },
    },
    [1938] = {
        name = "Dalar Dawnweaver",
        lines = {
            { "91:629172143:1229176008", "Kirin Tor ไม่ฟังคำเตือนข้า! Alliance เป็นเรื่องหลอกลวง Arugal เป็นคนโง่บ้าบิ่น" },
            { "90:1088690176:1368624713", "Kirin Tor ไม่ฟังคำเตือนข้า! Alliance เป็นเรื่องหลอกลวง Arugal เป็นคนโง่บ้าบิ่น" },
        },
    },
    [250686] = {
        name = "Tabitha Heartweaver",
        lines = {
            { "69:438490333:1289766195", "สรรเสริญ Banshee Queen นาน ๆ ทีข้าถึงจะมีคนมาเยือนข้างนอกนี่" },
        },
    },
    [266484] = {
        name = "Morbin Lightbane",
        lines = {
            { "449:45126434:1512965883", "พวกเราพาลาดินต้องพิสูจน์ตนทุกวันให้คู่ควรกับการอยู่ในหมู่พี่น้อง Forsaken มิฉะนั้นอาจถูกตัดสินว่าเป็นพวกคลั่งศรัทธาอย่าง Scarlet Crusade แสงสว่างไม่ได้เป็นเพียงเครื่องมือของศัตรู แต่เป็นสื่อแห่งโทสะอันชอบธรรมของเรา! ด้วยความภักดีต่อ Dark Lady และความรักบ้านเกิด เราจึงใช้แสงสว่างนำความยุติธรรมไปสู่ศัตรูได้\n\nBanshee Queen จับตามองเราอย่างใกล้ชิด ก็ให้นางมองไป นางจะเห็นว่าความแน่วแน่ของเราไม่เคยสั่นคลอน เราคือ Forsaken!" },
        },
    },
    [3494] = {
        name = "Tinkerwiz",
        lines = {
            { "25:698167890:221405272", "อะไร? เจ้าต้องการอะไร?" },
            { "178:1483189429:2052558119", "ข้าช่วยไม่ได้แล้ว! เจ้าพร้อมพบคนที่ทำมานานกว่าข้าแล้ว ไหนดูสิ... เจ้าเป็นพวก Alliance จึงต้องไปคุยกับ Lilliam Sparkspindle ใน Stormwind" },
            { "81:681547047:337977334", "ได้สิ ข้าจะสอนให้บ้าง แล้วดูว่าเจ้าทำได้แค่ไหน บางทีเจ้าอาจทำให้ข้าประหลาดใจ!" },
            { "114:1099106260:154405706", "เกรงว่าเจ้าเก่งเกินกว่าข้าจะสอนแล้ว เพื่อน! ไปหา Nogg ใน Orgrimmar เขาจะพาเจ้าไปอีกขั้น!" },
            { "133:1148489713:1311577028", "ข้าไม่มีอะไรจะสอนแล้ว! อย่างน้อยก็สำหรับคนที่รู้มากเท่าเจ้าน่ะ! พวกฝ่ายฮอร์ดอย่างเจ้าต้องไปคุยกับ Nogg ที่ Orgrimmar!" },
        },
    },
    [4586] = {
        name = "Graham Van Talen",
        lines = {
            { "78:1742223181:1316707637", "Dark Lady กล่าวว่า ความรู้จะเป็นอาวุธยิ่งใหญ่ที่สุดของเราในสงครามนี้" },
            { "97:1500212076:57423295", "เจ้าพร้อมสำหรับสิ่งที่ยิ่งใหญ่กว่าแล้ว! ไปหา Franklin Lloyd ทางขวามือข้า จากนี้เขาจะชี้ทางให้เจ้า" },
            { "110:246969608:369233900", "วิศวกรรมจะให้ทั้งทักษะและความรู้เพื่อแยกชิ้นส่วนคู่ต่อสู้! ให้ข้าแสดงวิธี..." },
        },
    },
    [5164] = {
        name = "Grumnus Steelshaper",
        lines = {
            { "149:297466484:1533186058", "เจ้ามารบกวนข้าเพราะของนั่นหรือ? เจ้าเอากระต่ายตายผูกหลังแล้ววิ่งผ่านรังโทรลล์ยังดีกว่าสวมขยะชิ้นนั้นอีก" },
            { "N 132:716182679:592932511", "{name} ใช่ไหม? ผลงานในมือเจ้างดงามมาก ข้าจะรับฝึก สอนเจ้าทำเกราะให้คู่ควรแม้แต่กับ King Magni เอง" },
            { "33:1202836986:731463323 N 91:1747262432:385854962", "ยินดีต้อนรับกลับ Great Forge {name} เจ้ามาเยี่ยมคนแคระแก่ ๆ หรือคิดว่าพร้อมก้าวต่อไปในการฝึกแล้ว?" },
            { "21:52129304:811683786", "มีอะไรให้ข้าช่วยไหม?" },
        },
    },
    [5174] = {
        name = "Springspindle Fizzlegear",
        lines = {
            { "64:264315105:1039306486", "หากการคำนวณข้าถูกต้อง อีกไม่นานล้อจะล้าสมัย!" },
            { "147:1766140873:1669787555", "เจ้าฝึกมาไกลมากแล้ว เหลือครูเพียงคนเดียวที่สอนต่อได้ ไปหา Buzzek Bracketswing ใน Gadgetzan!" },
            { "104:309727515:1596855125", "สิ่งที่ข้าจะสอนทำสมองเจ้าเละเป็นวุ้นแน่! กลับมาเมื่อเรียนรู้มากพอแล้ว!" },
            { "89:1838403269:530814568", "ยอดเยี่ยม เจ้าพิสูจน์ว่าคู่ควรแล้ว! ต่อไปเป็นการสอนขั้นถัดไป..." },
        },
    },
    [5518] = {
        name = "Lilliam Sparkspindle",
        lines = {
            { "59:1212077959:1960334418", "ไหนดูสิ... สิบสี่บวกเจ็ด ทดสอง... อ้อ ว่าอย่างไร?" },
            { "180:1566790483:1461070634", "เจ้าก้าวหน้าเร็วเหลือเกิน! ข้าสอนสิ่งที่เจ้ายังไม่รู้ไม่ได้แล้ว แต่ Springspindle Fizzlegear สอนได้แน่! พบเขาได้ที่ Ironforge โชคดี!" },
            { "181:493912740:1728497726", "เมื่อถึงเวลาเจ้าจะเรียนกับข้าได้... แต่ยังไม่ใช่ตอนนี้! ทำไมไม่เริ่มจากคุยกับ Sprite Jumpsprocket ทางขวามือข้านี่ พอได้ลองเรียนเบื้องต้นแล้วค่อยกลับมาหาข้า!" },
            { "104:526756938:886079152", "เจ้าไม่ทำให้ผิดหวังเลย! เมื่อผ่านเรื่องนั้นแล้ว ก็เริ่มการสอนได้!" },
            { "89:94984827:1566793729", "ต้องแลกกันหน่อย! ข้าจะสอนสิ่งที่ข้ารู้ แต่ก่อนอื่นอยากให้เจ้าช่วยทำงานเล็ก ๆ อย่างหนึ่ง..." },
        },
    },
    [6568] = {
        name = "Vizzklick",
        lines = {
            { "99:1153303859:1459839811 N 52:1031059453:961616834", "หากเจ้าสนใจตัดเย็บ Vizzklick มีอุปกรณ์ให้แน่นอน ลองดูรอบ ๆ {name} แล้วบอกหากอยากซื้ออะไร!" },
            { "18:837371938:1448498077 N 198:724716776:1150756883", "เก็บของเจ้า {name}! ข้าเพิ่งได้ข่าวจาก Nilith Lokrav ใน Searing Gorge ว่า Undermarket ตั้งฐานกลาง Cauldron แล้ว ไปหา Nilith Lokrav ใน Searing Gorge เพื่อฟังรายละเอียด!" },
        },
    },
    [8126] = {
        name = "Nixx Sprocketspring",
        lines = {
            { "138:1579502439:683883082", "สวัสดี! หากมาเพื่อเข้าถึงแบบวิศวกรรมก็อบลิน โปรดเตรียมบัตรสมาชิกวิศวกรก็อบลินไว้ตรวจสอบ" },
            { "154:1885254461:1618007675", "ให้ข้าอธิบายคณิตศาสตร์สักนิด: \"ก็อบลิน\" บวก \"วิศวกรรม\" เท่ากับรู้จริงทำเป็น ที่รัก ใครบอกเป็นอย่างอื่นก็แค่บวกเลขไม่เป็น" },
        },
    },
    [8738] = {
        name = "Vazario Linkgrease",
        lines = {
            { "138:1579502439:683883082", "สวัสดี! หากมาเพื่อเข้าถึงแบบวิศวกรรมก็อบลิน โปรดเตรียมบัตรสมาชิกวิศวกรก็อบลินไว้ตรวจสอบ" },
        },
    },
    [11177] = {
        name = "Okothos Ironrager",
        lines = {
