    [1318] = {
        name = "Jessara Cordell",
        lines = {
            { "97:126745299:1840797620", "ข้าขายเฉพาะอุปกรณ์อาร์เคนชั้นดีที่สุด ผลิตโดยช่างและจอมเวทที่นี่ใน Stormwind" },
            { "232:2017619563:1186102001", "ตั้งแต่ Dalaran ล่มกับ Quel'Thalas ถูกทำลาย สินค้าแบบนี้หายาก แต่ Lucan Cordell และช่างคนอื่นของเราทำได้ดี นำสินค้าคุณภาพมาส่งตามรายการ" },
            { "141:191733136:1487513879", "เจ้ายังไม่พร้อม ไปคุยกับ Betty Quinn ที่ยืนอยู่ข้างบันไดตรงโน้น เมื่อเจ้าเข้าใจวิชาลึกซึ้งขึ้นแล้วค่อยกลับมาหาข้า" },
        },
    },
    [1346] = {
        name = "Georgio Bolero",
        lines = {
            { "52:2041242308:846200164", "ดี! ข้าบอกได้ว่าความพยายามจะไม่สูญเปล่า!" },
            { "132:1850272445:450349580", "ใช่ ข้าเปิดร้านนี้มาพักใหญ่แล้ว ช่วงนี้ค้าขายดีทีเดียว มีนักผจญภัยหน้าใหม่แวะเวียนมามากมาย..." },
            { "174:1365756848:1323634370", "ข้ารู้จักอยู่คนเดียวที่เชี่ยวชาญการตัดเย็บยิ่งกว่าข้า ได้ข่าวล่าสุดว่าเขาอยู่ที่ Theramore Isle เจ้าควรไปตามหาเขา" },
            { "79:1359214925:2109308845", "ข้าเกรงว่าเจ้าต้องฝึกอีกหน่อย ข้าถึงจะถ่ายทอดวิชาให้ได้" },
        },
    },
    [1347] = {
        name = "Alexandra Bolero",
        lines = {
            { "97:126745299:1840797620", "ข้าขายเฉพาะอุปกรณ์อาร์เคนชั้นดีที่สุด ผลิตโดยช่างและจอมเวทที่นี่ใน Stormwind" },
