    [12997] = {
        name = "Monty",
        lines = {
            { "37:1936155669:423232325", "ข้าชื่อ Monty และหนูคืองานข้า" },
        },
    },
    [13018] = {
        name = "Nipsy",
        lines = {
            { "55:1748108945:1291380296", "เจ้าไม่มีทางพบหนูเสียบไม้ดีกว่านี้ในฝั่งนี้ของ Khaz Modan!" },
            { "176:1348489855:2024861817", "ดูเหมือนเจ้าต้องการงานนะ แม่หญิง ขึ้นรถรางไปหา Monty พี่น้องข้าที่สถานี Deeprun Tram ฝั่ง Ironforge เถอะ แน่ใจว่าเขามีงานให้ทำ" },
        },
    },
    [1500] = {
        name = "Coleman Farthing",
        lines = {
            { "140:446871869:1705472321", "หวังว่าเจ้าสบายดี เมื่อคำนึงถึงสถานการณ์ทั้งหมด\n\nนั่งพักสักครู่ ฟังเรื่องข้า แน่นอนว่าเป็นโศกนาฏกรรม แต่ข้าหวังว่าจะจบด้วยการแก้แค้น!" },
        },
    },
    [5878] = {
        name = "Thun'grim Firegaze",
        lines = {
            { "60:339680096:544886277", "สายตาข้ามืดมัวลง แต่การมองเห็นมีหลายรูปแบบ..." },
        },
    },
    [6166] = {
        name = "Yorus Barleybrew",
        lines = {
            { "67:922030922:2110777696", "คิดว่าใจถึงหรือ? ถ้าถึงจริง ข้ามีบางอย่างให้..." },
        },
    },
    [252377] = {
        name = "Seena Skybreaker",
        lines = {
            { "135:1602761158:99993835", "นักรบที่สะดุ้งกลัวคือนักรบที่ตาย หากเจ้าจะเผชิญความตายอย่างนักรบ ข้าจะสอนให้ไม่สะดุ้งกลัว" },
        },
    },
    [251964] = {
        name = "Blademaster Ren",
        lines = {
            { "135:1602761158:99993835", "นักรบที่สะดุ้งกลัวคือนักรบที่ตาย หากเจ้าจะเผชิญความตายอย่างนักรบ ข้าจะสอนให้ไม่สะดุ้งกลัว" },
            { "4:1432760897:190637651 C 21:231554700:1446550259 C 52:1958041630:363704508 C 37:859600874:1726458964", "{class}ที่สะดุ้งกลัวคือ{class}ที่ตาย หากเจ้าจะเผชิญความตายอย่าง{class} ข้าจะสอนให้ไม่สะดุ้งกลัว" },
        },
    },
    [254088] = {
        name = "Corsan Earthrazer",
        lines = {
            { "135:1602761158:99993835", "นักรบที่สะดุ้งกลัวคือนักรบที่ตาย หากเจ้าจะเผชิญความตายอย่างนักรบ ข้าจะสอนให้ไม่สะดุ้งกลัว" },
            { "4:1432760897:190637651 C 21:231554700:1446550259 C 52:1958041630:363704508 C 37:859600874:1726458964", "{class}ที่สะดุ้งกลัวคือ{class}ที่ตาย หากเจ้าจะเผชิญความตายอย่าง{class} ข้าจะสอนให้ไม่สะดุ้งกลัว" },
        },
    },
    [915] = {
        name = "Jorik Kerridan",
        lines = {
            { "90:748691251:391531667", "เจ้าดูเป็นคนที่ข้าควรระวังถุงเงินเมื่ออยู่ใกล้ มีอะไรให้ช่วยหรือ?" },
            { "75:2042450107:1761906752 C 25:1654355136:1742979888", "ข้าไม่คิดว่าเจ้าอยากเรียนสิ่งที่ข้าสอนได้ คงต้องหาครูฝึก{class}ช่วย" },
        },
    },
    [917] = {
        name = "Keryn Sylvius",
        lines = {
            { "68:1268237787:571648545 C 1:63:63", "อ้าว ๆ... ดูสิว่าแมวลากใครมา... ข้าช่วยอะไรได้ {class}?" },
            { "31:571619399:2131609704", "เสียใจ ข้าฝึกแต่โร้ก" },
        },
    },
    [1234] = {
        name = "Hogral Bakkan",
        lines = {
            { "43:963510880:2095817325 N 1:63:63", "อะไรนำเจ้ามาโลกแถบนี้ {name}?" },
            { "15:1522978243:239237571 N 22:1994609186:1377643676", "ช่วยไม่ได้ {name} ข้าฝึกแต่โร้ก" },
        },
    },
    [2122] = {
        name = "David Trias",
        lines = {
            { "135:1084425121:1430903258", "ด้วยความเห็นชอบจาก Lord Varimathras จำนวน Deathstalkers เพิ่มขึ้น มีคมดาบโจมตีศัตรูยามไม่ทันคาดมากขึ้น" },
            { "60:772817757:1068724953", "ข้าฝึกเจ้าไม่ได้ ต้องคุยกับครูฝึกอาชีพของเจ้า" },
        },
    },
    [2130] = {
        name = "Marion Call",
        lines = {
            { "135:1084425121:1430903258", "ด้วยความเห็นชอบจาก Lord Varimathras จำนวน Deathstalkers เพิ่มขึ้น มีคมดาบโจมตีศัตรูยามไม่ทันคาดมากขึ้น" },
            { "60:772817757:1068724953", "ข้าฝึกเจ้าไม่ได้ ต้องคุยกับครูฝึกอาชีพของเจ้า" },
        },
    },
    [2391] = {
        name = "Serge Hinott",
        lines = {
            { "188:1272836524:234345667", "มาขัดจังหวะอีกแล้ว อย่างนี้ข้าจะทำงานเสร็จได้อย่างไร? ไม่ต้องตอบ ดูเหมือนข้าสนสิ่งที่เจ้าพูดหรือ? ไปกวนเจ้าท่านผู้สูงส่งแทนสิ" },
            { "193:2021402602:56017474", "ให้ข้าฝึกเจ้าหรือ? เอาน่า เราก็รู้ว่าทำไม่ได้ การสอนนี่แหละทำฝีมือข้าถดถอย อยากฝึกก็ไปหา Doctor Herbert Halsey ชาว Forsaken ใน Apothecarium ของ Undercity" },
            { "196:1878123987:1076889885", "อย่าเสียเวลาข้า ข้ามีโครงการวิจัยเก่ากว่าอายุเจ้าอีก ไปคุยกับ Doctor Martin Felben ใน Apothecarium ของ Undercity เขาเป็น Forsaken ที่น่าจะพอสอนพื้นฐานเจ้าได้" },
            { "201:601489441:1180809885", "นักเรียนอีกคน วิเศษ นี่แหละเหตุผลที่ Lydon ได้อยู่ราชสมาคมคนถือตัวและทำวิจัย ส่วนข้าติดแหง็กเป็นผู้สอน ถ้าได้รางวัลการสอนอีก ข้าคงอับอายไปตลอด!" },
        },
    },
    [3155] = {
        name = "Rwag",
        lines = {
            { "105:1194686605:174777256", "Shattered Hand จะพา Horde กลับสู่เกียรติยศเดิม โดยไม่ให้ความขลาดของ Warchief ขัดขวาง" },
            { "24:1952719577:438144002 C 1:46:46", "ข้าไม่ฝึกคนอย่างเจ้า {class}" },
        },
    },
    [3170] = {
        name = "Kaplak",
        lines = {
            { "105:1194686605:174777256", "Shattered Hand จะพา Horde กลับสู่เกียรติยศเดิม โดยไม่ให้ความขลาดของ Warchief ขัดขวาง" },
            { "24:1952719577:438144002 C 1:46:46", "ข้าไม่ฝึกคนอย่างเจ้า {class}" },
        },
    },
    [3402] = {
        name = "Zando'zan",
        lines = {
            { "80:1308013212:613991817", "Zando'zan แห่ง Shattered Hand Zando'zan ช่วยอะไรเจ้าได้? ช่วยไม่ได้! ไม่ช่วย!" },
        },
    },
    [3594] = {
        name = "Frahun Shadewhisper",
        lines = {
            { "52:651295595:624041694", "เราเป็นเพียงความมืดและเงา นิรันดร์ ไร้ตัวตนให้เห็น" },
            { "40:1928856934:882660477", "สวัสดี โร้กรุ่นเยาว์ แสวงหาสิ่งใด?" },
        },
    },
    [3599] = {
        name = "Jannok Breezesong",
        lines = {
            { "141:1942409879:1754569860 N 24:2130274872:421549320", "เหมือนแมวถูกลากมาจากฝน เจ้าข่วนและตะกุย แล้วทำซ้ำอีก... ข้าจะกลับมาอีก...\n\nโอ้ ไม่เห็นเจ้าเข้ามา {name}! มีอะไรให้ข้าช่วย?" },
            { "52:651295595:624041694", "เราเป็นเพียงความมืดและเงา นิรันดร์ ไร้ตัวตนให้เห็น" },
        },
    },
    [6766] = {
        name = "Ravenholdt Guard",
        lines = {
            { "45:1528978140:1882329349", "หุนหัน Master Ravenholdt ไม่ชอบความหุนหัน" },
            { "83:1549751661:2122075471", "Syndicate มีแต่พวกไร้ฝีมือ ไม่เป็นระเบียบ ไม่ชำนาญ และขี้เกียจ..." },
            { "46:1304953805:706378636 N 31:261992646:1459238406", "ข้าว่า Simone ตามหาเจ้าก่อนหน้านี้ {name} คุยกับนางหรือยัง?" },
            { "41:1198662320:1755887726 C 1:46:46", "Ravenholdt Manor ไม่ยอมรับเจ้า {class}" },
            { "11:927657569:725753248 C 34:1321895167:1418225501", "สวัสดี {class} คุยกับ Fahrad หรือยัง?" },
            { "27:1764689259:1896718427 N 1:46:46", "เป็นเกียรติที่ได้พบอีกครั้ง {name}" },
            { "26:802377473:527088538", "ระวังหลัง คนแปลกหน้า" },
            { "29:1413554121:942060837 N 1:46:46", "ยินดีที่ได้พบอีกครั้ง {name}" },
            { "35:604474432:403113470 N 1:46:46", "เจ้ามีไหวพริบเพิ่มขึ้นจริง {name}" },
        },
    },
    [7207] = {
        name = "Doc Mixilpixil",
        lines = {
            { "15:1285031552:843897474", "มีอะไรให้ช่วยไหม?" },
        },
    },
    [15761] = {
        name = "Officer Vu'Shalay",
        lines = {
            { "11:927657569:725753248 C 434:1706292888:1528158602", "สวัสดี {class} ข้าเป็นเจ้าหน้าที่รับตรายกย่องแทนเผ่า Darkspear มีหน้าที่ช่วยนักผจญภัยที่ได้รับ Horde Commendation Signets\n\nข้ารับตราหลายจำนวน แต่แลกครั้งละสิบชิ้นเป็นประโยชน์ที่สุด เมื่อส่งตรา ข้าจะบันทึกวีรกรรม แล้วเจ้าจะได้รับการยอมรับจากเผ่า Darkspear สำหรับหน้าที่และการรับใช้" },
        },
    },
    [15762] = {
        name = "Officer Lunalight",
        lines = {
            { "11:927657569:725753248 C 417:1247347385:231447400", "สวัสดี {class} ข้าเป็นเจ้าหน้าที่รับตรายกย่องแทน Darnassus มีหน้าที่ช่วยนักผจญภัยที่ได้รับ Alliance Commendation Signets\n\nข้ารับตราหลายจำนวน แต่แลกครั้งละสิบชิ้นเป็นประโยชน์ที่สุด เมื่อส่งตรา ข้าจะบันทึกวีรกรรม แล้วเจ้าจะได้รับการยอมรับจาก Darnassus สำหรับหน้าที่และการรับใช้" },
