    [15735] = {
        name = "Stormwind Commendation Officer",
        lines = {
            { "11:927657569:725753248 C 417:177022685:818101364", "สวัสดี {class} ข้าเป็นเจ้าหน้าที่รับตรายกย่องแทน Stormwind มีหน้าที่ช่วยนักผจญภัยที่ได้รับ Alliance Commendation Signets\n\nข้ารับตราหลายจำนวน แต่แลกครั้งละสิบชิ้นเป็นประโยชน์ที่สุด เมื่อส่งตรา ข้าจะบันทึกวีรกรรม แล้วเจ้าจะได้รับการยอมรับจาก Stormwind สำหรับหน้าที่และการรับใช้" },
        },
    },
    [15736] = {
        name = "Orgrimmar Commendation Officer",
        lines = {
            { "11:927657569:725753248 C 414:1005461286:1239458699", "สวัสดี {class} ข้าเป็นเจ้าหน้าที่รับตรายกย่องแทน Orgrimmar มีหน้าที่ช่วยนักผจญภัยที่ได้รับ Horde Commendation Signets\n\nข้ารับตราหลายจำนวน แต่แลกครั้งละสิบชิ้นเป็นประโยชน์ที่สุด เมื่อส่งตรา ข้าจะบันทึกวีรกรรม แล้วเจ้าจะได้รับการยอมรับจาก Orgrimmar สำหรับหน้าที่และการรับใช้" },
        },
    },
    [15737] = {
        name = "Darkspear Commendation Officer",
        lines = {
            { "11:927657569:725753248 C 434:1706292888:1528158602", "สวัสดี {class} ข้าเป็นเจ้าหน้าที่รับตรายกย่องแทนเผ่า Darkspear มีหน้าที่ช่วยนักผจญภัยที่ได้รับ Horde Commendation Signets\n\nข้ารับตราหลายจำนวน แต่แลกครั้งละสิบชิ้นเป็นประโยชน์ที่สุด เมื่อส่งตรา ข้าจะบันทึกวีรกรรม แล้วเจ้าจะได้รับการยอมรับจากเผ่า Darkspear สำหรับหน้าที่และการรับใช้" },
        },
    },
    [15738] = {
        name = "Undercity Commendation Officer",
        lines = {
            { "11:927657569:725753248 C 422:46722404:178001665", "สวัสดี {class} ข้าเป็นเจ้าหน้าที่รับตรายกย่องแทน Undercity มีหน้าที่ช่วยนักผจญภัยที่ได้รับ Horde Commendation Signets\n\nข้ารับตราหลายจำนวน แต่แลกครั้งละสิบชิ้นเป็นประโยชน์ที่สุด เมื่อส่งตรา ข้าจะบันทึกวีรกรรม แล้วเจ้าจะได้รับการยอมรับจาก Undercity สำหรับหน้าที่และการรับใช้" },
        },
    },
    [6946] = {
        name = "Renzik \"The Shiv\"",
        lines = {
            { "120:2084988457:946193914", "Mathias พบข้าถูก Venture Co. ทิ้งให้ตายใน Barrens หากไม่ใช่เขา ข้าคงเป็นอาหาร Prowler" },
        },
    },
    [251389] = {
        name = "Akeri Duskblade",
        lines = {
            { "148:2076117624:1747032709", "สังหารศัตรูและทำให้คนรักใจอ่อนด้วยเคล็ดลับประหลาดเพียงอย่างเดียว\n\nหากเดินบนวิถีโร้ก ข้าสอนได้... แน่นอนว่ามีค่าตอบแทน" },
        },
    },
    [7233] = {
        name = "Taskmaster Fizzule",
        lines = {
            { "462:434830086:570148792", "ในที่สุด Grand Foreman Puzik Gallywix ก็เข้าจัดการ นำพิษส่วนเกินไปหอคอยที่ Sludge Fen เพื่อศึกษาความไม่เสถียรของสารพิษ ท้ายสุดตัดสินใจแบ่งความลับพิษให้ Defias Brotherhood แลกกับพิษเสถียรที่ใช้งานได้จำนวนมาก\n\nKlaven Mortwake แห่ง Defias Brotherhood ได้หน้าที่เปลี่ยนคุณสมบัติทางเคมีของส่วนผสม Zanzil" },
            { "485:469365486:904712392", "มีบางอย่างทำให้หอคอยนี้ป่วย ข้าล้มป่วย และพนักงาน Venture Co. ที่ทำงานใกล้หรือในหอคอยก็ป่วยด้วย\n\nเพิ่งสัปดาห์ก่อน หน่วยลาดตระเวนสองคนตาย แล้วฟื้นทันทีเป็นพวก Drone ไร้สติ!\n\nพลังชีวิตกำลังไหลออกจากกาย รู้สึกว่าควบคุมตัวเองไม่ได้ แรงกระตุ้นเข้าครอบงำ... แรงกระตุ้นชั่วร้าย... *Fizzule ตบหน้าตัวเอง* ยัง... ฟังนะ... ข้าอยู่ตำแหน่งมีอำนาจ ตำแหน่งนี้ทำให้รู้ข้อมูลอ่อนไหวบางอย่าง" },
            { "445:38158863:1227398539", "ราวห้าเดือนก่อน แผนก Stranglethorn ของ Venture Co. ได้พิษพิเศษจากพ่อค้าน่าสงสัยใน Booty Bay ชื่อ Crank Fizzlebub ดูเหมือน Fizzlebub ขโมยพิษจาก Zanzil!\n\nใช่ Zanzil the Outcast โทรลล์ที่ถูกเผ่าตนเองเนรเทศเพราะลักษณะ 'การทดลอง' วิชาปลุกศพ\n\nแน่นอน พอได้พิษก็ทดลองใส่กันเอง ผลลัพธ์หายนะ" },
        },
    },
    [916] = {
        name = "Solm Hargrin",
        lines = {
            { "15:1522978243:239237571 N 22:1994609186:1377643676", "ช่วยไม่ได้ {name} ข้าฝึกแต่โร้ก" },
            { "22:663320408:47783015 N 1:63:63", "มีอะไรให้ข้าช่วยหรือ {name}?" },
        },
    },
    [6566] = {
        name = "Estelle Gendry",
        lines = {
            { "135:1084425121:1430903258", "ด้วยความเห็นชอบจาก Lord Varimathras จำนวน Deathstalkers เพิ่มขึ้น มีคมดาบโจมตีศัตรูยามไม่ทันคาดมากขึ้น" },
        },
    },
    [254087] = {
        name = "Miriaan Mistblade",
        lines = {
            { "148:2076117624:1747032709", "สังหารศัตรูและทำให้คนรักใจอ่อนด้วยเคล็ดลับประหลาดเพียงอย่างเดียว\n\nหากเดินบนวิถีโร้ก ข้าสอนได้... แน่นอนว่ามีค่าตอบแทน" },
            { "100:1750164748:196709913 C 43:2122942070:319965478", "<ครูฝึกโจร> สังหารศัตรูแล้วทำให้คนรักใจละลายด้วยกลเม็ดพิสดารเพียงอย่างเดียว\n\nถ้าเจ้าเดินบนวิถีแห่ง {class} ข้าสอนให้ได้... แน่นอนว่ามีค่าเรียน" },
        },
    },
    [252379] = {
        name = "Eltheen Nightbreeze <Rogue Trainer>",
        lines = {
            { "148:2076117624:1747032709", "สังหารศัตรูและทำให้คนรักใจอ่อนด้วยเคล็ดลับประหลาดเพียงอย่างเดียว\n\nหากเดินบนวิถีโร้ก ข้าสอนได้... แน่นอนว่ามีค่าตอบแทน" },
            { "100:1750164748:196709913 C 43:2122942070:319965478", "<ครูฝึกโจร> สังหารศัตรูแล้วทำให้คนรักใจละลายด้วยกลเม็ดพิสดารเพียงอย่างเดียว\n\nถ้าเจ้าเดินบนวิถีแห่ง {class} ข้าสอนให้ได้... แน่นอนว่ามีค่าเรียน" },
        },
    },
    [6171] = {
        name = "Duthorian Rall",
        lines = {
            { "72:1263466413:1469796516 N 155:1583685426:343428491", "ความมืดรอบดินแดนจะทดสอบเจ้าหลายครั้ง {name} แต่เพื่อให้พร้อมเสมอ เราจะขอให้ทำงานบ่อย ๆ เพื่อให้พลังถึงขีดสูงสุด\n\nไปกับแสง และรักษาคุณธรรม" },
            { "72:1263466413:1469796516 U 155:1583685426:343428491", "ความมืดรอบดินแดนจะทดสอบเจ้าหลายครั้ง {name} แต่เพื่อให้พร้อมเสมอ เราจะขอให้ทำงานบ่อย ๆ เพื่อให้พลังถึงขีดสูงสุด\n\nไปกับแสง และรักษาคุณธรรม" },
        },
    },
    [6179] = {
        name = "Tiza Battleforge",
        lines = {
            { "41:848693179:416492569 N 126:1019891456:527821138", "บททดสอบมากมายรอพาลาดินแห่งแสง {name} มั่นใจได้ว่าจะพบกันอีกหลายครั้ง หากยังมุ่งมั่นยึดคุณธรรมที่เรายกย่อง" },
        },
    },
    [246378] = {
        name = "Danitha Morr",
        lines = {
            { "27:1508833779:1406784120 C 1:46:46", "ยินดีต้อนรับสู่ Bandarion Keep {class}" },
        },
    },
    [246393] = {
        name = "Jorin Croge",
        lines = {
            { "246:1940161029:60387912", "มีหลายสิ่งซ่อนในมืด แสงจำเป็นยิ่งกว่าเคย หากวิญญาณน่าสงสารเหล่านี้เห็นว่า แม้โลกเปลี่ยน เราก็ไม่จำเป็นต้องเป็นอสูรอย่างที่คนเป็นคิด" },
            { "286:760817515:1565666864", "ข้าดูแลให้มีเสบียง และแจกจ่ายทรัพยากรที่มีน้อยอย่างเหมาะสม\n\nหากเป็นภาคีสมบูรณ์ คงเป็นเจ้าหน้าที่พลาธิการ แต่ในสภาพนี้ ทำได้เพียงให้แน่ใจว่าอย่างน้อยมีอุปกรณ์พอรับมือภัยรอบตัวบ้าง" },
            { "240:1328830320:1080971980", "มีสิ่งมากมายซ่อนอยู่ในความมืด และเราต้องการพระแสงยิ่งกว่าครั้งไหน ๆ หากวิญญาณน่าสงสารเหล่านี้เข้าใจเสียทีว่า โลกของเราเปลี่ยนไปแล้วก็จริง แต่เรายังเลือกได้ว่าจะเป็นอย่างไร โดยไม่ต้องกลายเป็นปีศาจอย่างที่คนเป็นมองเรา" },
            { "292:907116014:1333356127", "ข้าคอยดูให้เรามีเสบียง และให้ทรัพยากรอันน้อยนิดที่เรามีถูกแบ่งอย่างเหมาะสม\n\nถ้าพวกเราเป็นคณะที่จัดตั้งกันเป็นเรื่องเป็นราว ข้าก็คงทำหน้าที่คล้ายเจ้าหน้าที่เสบียง แต่ในสภาพตอนนี้ ข้าทำได้เพียงหาอุปกรณ์ให้พวกเราพอรับมือกับภัยที่รายล้อม" },
        },
    },
    [257655] = {
        name = "Deathguard Billmuth",
        lines = {
            { "119:1914445126:1764767636", "<Deathguard Billmuth ขยุกขยิกอย่างเหม่อลอยขณะมองรอบอย่างประหม่า ชัดว่าไม่สบายใจมากที่อยู่ที่นี่>" },
        },
    },
    [244808] = {
        name = "Aramis Hammerhand",
        lines = {
            { "59:740874346:1204232935", "ยินดีต้อนรับกลับสู่แสง สหาย ต้องการฝึกไหม?" },
            { "86:516261351:951247759", "แม้ไม่ใช่พาลาดิน ก็ยังพบความสงบในแสงได้หากแสวงหา" },
            { "255:967301392:2039283435", "ถ้าเจ้าต้องการ นอกจากฝึกวิชาแล้ว ข้ายังลบความรู้เรื่องพรสวรรค์ออกจากใจเจ้าได้ด้วย ขอเตือนไว้ก่อนว่ายิ่งทำบ่อย กระบวนการก็ยิ่งยากและค่าบริการก็ยิ่งแพงขึ้น" },
        },
    },
    [246152] = {
        name = "Shari Stilwell",
        lines = {
            { "66:619532609:1065525263 C 1:63:63", "แสงคือประทีปส่องทุกคน ข้าช่วยอะไรได้ {class}?" },
            { "86:516261351:951247759", "แม้ไม่ใช่พาลาดิน ก็ยังพบความสงบในแสงได้หากแสวงหา" },
        },
    },
    [246349] = {
        name = "Breton Samuels",
        lines = {
            { "108:1933215406:490147969", "หากมาหามิตรภาพร่วมหมู่พาลาดิน มาถูกที่แล้ว\n\nยินดีต้อนรับกลับบ้าน" },
        },
    },
    [248840] = {
        name = "Trevan Rol",
        lines = {
            { "119:2100472141:817050985", "ในคืนมืดที่สุด จงไว้ใจแสงคุ้มครอง แน่นอน มีกระบองแข็งแรงดี ๆ ก็ไม่เสียหาย" },
            { "432:1425445507:475972530", "Son of Arugal ที่โจมตี Lumina มีชื่อว่า Old Fire-Eye มันขึ้นชื่อทั้งเรื่องความดุร้ายและเรื่องที่ฆ่าเท่าไรก็ไม่ยอมตาย ข้าศึกษาเรื่องนี้มาพอสมควรและคิดว่าเราน่าจะตีดาบที่ฆ่ามันให้ตายสนิทได้\n\nนี่ ข้าเตรียมรายการวัตถุดิบกับวิธีหาไว้ให้แล้ว เมื่อรวบรวมของที่ต้องใช้ครบก็กลับมาหาข้า แล้วเราจะเริ่มลงมือกัน" },
        },
    },
    [259620] = {
        name = "Lumina Windsinger",
        lines = {
            { "287:1434952160:1442139390", "อย่างที่บอก สัตว์ที่โจมตีหนีเมื่อข้าส่งสายฟ้าลวกก้น แต่กัด Banon ไปแล้ว ระหว่างกลับเมือง กนอลล์ล้อมจับเรา\n\nจนพวกมันเริ่มดึงเราลงเรือบน Fenris Isle นั่นแหละ... การเปลี่ยนแปลงเริ่มขึ้น" },
            { "287:2072776991:1469588277", "อย่างที่ข้าบอก เจ้าตัวที่โจมตีพวกเราหนีไปหลังข้าช็อตก้นมันด้วยสายฟ้า แต่มันกัด Banon ไปแล้ว ระหว่างทางกลับเมือง พวกนอลล์ล้อมจับเราไว้\n\nตอนที่พวกมันเริ่มลากเราขึ้นจากเรือที่ Fenris Isle นั่นแหละ... การเปลี่ยนร่างถึงเริ่มขึ้น" },
            { "282:1073529560:1135260422", "ข้าหาคำมาบรรยายสิ่งที่เกิดขึ้นไม่ได้ ร่างของ Banon บิดเบี้ยวจนน่ากลัว เสียงเหมือนกระดูกทุกชิ้นในร่างกำลังหัก ปากของเขาเต็มไปด้วยเขี้ยวคมกริบ มือกลายเป็นกรงเล็บสังหาร ต้องใช้นอลล์ยี่สิบตัวถึงจะล้มเขาได้ และก่อนจะล้มเขาก็ฆ่าพวกมันไปครึ่งหนึ่ง" },
            { "320:352588315:232920650", "พอทุกอย่างจบลง ข้าได้แต่ยืนนิ่งด้วยความตกใจ เขารู้ว่าจะเกิดอะไรขึ้น แต่ก็ยังพุ่งเข้าไปขวางสัตว์ตัวนั้นเพื่อปกป้องข้า\n\nพวกเรา Windshaper ใช้หนี้เสมอ และข้าติดหนี้เขา เราล้างแค้นให้การตายของเขาแล้ว แต่ยังเอาคืนเจ้าปีศาจที่ทำให้เขากลายเป็นแบบนั้นได้ ถ้าเจ้ายังเต็มใจช่วยข้า" },
            { "17:2034968675:327246869 C 1:46:46", "ขอให้สายลมอวยพรเจ้า {class}" },
        },
    },
    [3539] = {
        name = "Ott",
        lines = {
            { "238:1094585124:216092486", "ดาบข้าไม่วับวาว ระยิบระยับ หรือสุกสกาว และเมื่อข้าจากไป จะไม่มีเพลงมหากาพย์เล่าผลงาน\n\nแต่แน่ใจได้อย่างหนึ่ง อาวุธข้าจะโค่นอัศวินทุกคนใน Stormwind ได้ก่อนเสียคมที่ลับไว้" },
        },
    },
    [6251] = {
        name = "Strahad Farsan",
        lines = {
            { "102:1842107517:1165454838", "อาร์เคนทำให้แปดเปื้อนเฉพาะผู้อ่อนแอ ฝึกต่อให้ทัน มิฉะนั้นอาจพบชะตาคล้ายกัน" },
        },
    },
    [246344] = {
        name = "Alodan the Hopeful",
        lines = {
            { "59:740874346:1204232935", "ยินดีต้อนรับกลับสู่แสง สหาย ต้องการฝึกไหม?" },
        },
    },
    [2670] = {
        name = "Xizk Goodstitch",
        lines = {
            { "20:1582593661:1711519404 C 52:1511109495:2107749660", "ยินดีต้อนรับร้าน {class} พี่น้อง Goodstitch ช่วยอะไรได้?" },
            { "77:727432090:1671316998 N 307:1445536511:776014470", "อา ลูกค้าโปรดคนหนึ่ง ดูเป็นวอร์ล็อกพลังไม่น้อย {name} ยินดีพบ หากช่วยอะไรได้ โปรดถาม\n\nข้ากับพี่น้องเชื่อว่าพวกเจ้าจะนำสู่ยุคยิ่งใหญ่ถัดไป ผู้มีพลัง... ควบคุมได้ขนาดนั้น... แค่เรื่องเวลาก่อน Legion เองก้มตามเจตนา\n\nข้าอิจฉานิดหน่อย" },
        },
    },
    [3363] = {
        name = "Magar",
        lines = {
            { "113:1876267495:70514167", "ของหลายอย่างในร้านข้าทำเอง คิดอย่างไร? ตอบระวัง ชีวิตอาจขึ้นกับคำตอบ" },
            { "134:784480329:1960395409", "ต้องเรียนจากคนรู้มากกว่าข้า ไป Josef Gregorian ใน Undercity ยังยืนทำอะไร?" },
            { "150:678166165:700146353", "อะไร? มากวนทำไม? พนันว่าเสื้อคุณภาพสูงยังทำไม่ได้! ไปคุย Snang กลับเมื่อคู่ควรพรสวรรค์ข้า!" },
            { "65:1179341822:1037306728", "ในที่สุดแสดงผลงานแล้ว! ทีนี้ข้าจะแสดงผลงานให้ดู!" },
        },
    },
    [6252] = {
        name = "Acolyte Magaz",
        lines = {
            { "23:1745611030:2095954635 N 80:342322950:106182097", "ฟังผู้อาวุโส {name} หากใจแกร่งทุ่มเท ไม่มีพลังใดควบคุมไม่ได้" },
            { { "429:1413083698:718671938", "429:1465802048:1066065467" }, "Infernal เป็นหนึ่งในปีศาจทรงพลังที่สุดที่วอร์ล็อกหวังมีเคียงศึก แข็งแรง เกราะดี ตีศัตรูร้ายแรง หากเลือกใส่วิญญาณในอาวุธ จะได้ประโยชน์บางอย่าง เช่นพลังชีวิตและฟื้นฟูเพิ่ม\n\nอยากรู้ Felhound คุยกับ Wytula ฝั่งตรงข้ามข้า" },
        },
    },
    [6254] = {
        name = "Acolyte Wytula",
        lines = {
            { "47:859167770:50149672 N 67:232398150:861748341", "Forsaken ไม่ได้ขับด้วยเจตนา Sylvanas ทุกคน {name} บางคนขับด้วยพลังแท้ที่หาเอง" },
            { "501:2030266439:1477820634", "Felhound... ดุร้ายจริง แม้กายไม่แกร่งเท่า Infernal วอร์ล็อกฉลาดรู้ว่ากำลังไม่ใช่ทุกคำตอบ ไม่เช่นนั้นคงเลือกนักรบแทนใช่ไหม?\n\nFelhound ดูดมานาศัตรู ใช้กับความเร็วพิชิต พลังมาจากอาร์เคนและใช้พลังนั้นเพื่อจุดหมายตน\n\nอยากรู้ Infernal คุย Magaz ฝั่งตรงข้ามข้า" },
        },
    },
    [6266] = {
        name = "Menara Voidrender",
        lines = {
            { "10:160466953:223652662 N 26:240511512:1101691041 C 340:671139312:350589191", "Kar Aman {name} ดูเป็น{class}แกร่ง ควรระวังตัวแถวนี้ แตะของไม่รู้หรือไม่เคารพผู้อาวุโสเป็นเหตุควรลงโทษ\n\nอาจไม่เคารพข้ากับสหาย แต่หากโง่พอก็จะเรียนเคารพพลัง\n\nทักทายพอแล้ว มีอะไรให้ช่วย?" },
            { { "413:1746204454:1162425223", "413:2074923339:1371073413" }, "อา วอร์ล็อกร่วมทางที่พิสูจน์คุณค่ามาบ้าง\n\nยินดีรู้จัก ข้าชื่อ Menara Voidrender... มีเหตุสมชื่อ\n\nดูทรงพลังและรู้พอให้รับเครื่องมืออื่น... ทรงพลังกว่า... อย่างน่ายินดี ไม่ใช่มอบอย่างโง่ หากจริงก็คุยต่อ ไม่เช่นนั้นรู้ทางกลับท่าเรือแล้วลงทะเลเอง" },
            { "63:1371990592:850577444 N 103:296935245:641445951", "คุยกับศิษย์สักคนในหอคอยหรือยัง {name}? ทำลูกแก้วไม่เสร็จจนทำงานคนใดคนหนึ่ง ไปคุยหากพร้อม" },
        },
    },
    [14436] = {
        name = "Mor'zul Bloodbringer",
        lines = {
            { "143:571468131:234099270 N 40:1345984087:1232959013", "มีเวลาที่ชีวิตที่รู้จักไม่พอ เราติดกับ หาคำตอบ พบหวังลุกในมุมมืด\n\nเมื่อนั้นเท่านั้น {name} จึงก้าวแรกสู่อิสรภาพ" },
        },
    },
    [14437] = {
        name = "Gorzeeki Wildeyes",
        lines = {
            { "36:1154815989:879786931 C 77:2019077660:1607758442", "มีแมงมุมหรือด้วงไหม {class}? วิ่งเร็ว แต่หากเร็วกว่า จะพบว่าอร่อย!" },
        },
    },
    [14463] = {
        name = "Daio the Decrepit",
        lines = {
            { "40:698236330:2085053987 R 1:46:46", "ไกลจากบ้านมากทีเดียว ชาว{race}" },
        },
    },
    [14469] = {
        name = "Niby the Almighty",
        lines = {
            { "74:940344411:263643274", "คำนับต่อหน้าข้า เจ้าแมลง! คงสัมผัสพลังเหนือเจ้าได้" },
            { "229:827834420:922342031", "มาหา Niby เรียนความลับเรียก Infernal ผู้รับใช้จาก Nether\n\nเงียบ! Niby รู้ทุกอย่าง!\n\nNiby ไม่ปล่อยความรู้ง่าย ต้องช่วยงานสำคัญมากก่อน" },
            { "363:292542361:76810622", "มี Infernal ทรงพลังชื่อ Kroshius ตะวันออกเฉียงเหนือค่าย นั่นเหตุที่ Niby อยู่ มันเป็น Greater Infernal ที่อยู่นานเกินคาด ฟังนะมือใหม่ Infernal กระแทกโลกด้วยพลังรุนแรงรับใช้นาย แต่พลังจางเร็ว เมื่อเพลิงมอดมันจะร่วน" },
            { "336:2026682530:814664845", "อย่าขัด Niby คนโง่! ข้าจะฉีกเนื้อจากกระดูกแล้วใช้โครงแขวนเสื้อ พูดถึงไหน? อ้อ Kroshius อยู่นานแทบสิบเท่า Infernal ธรรมดา ไม่แน่ใจทำไม แต่ศึกษาพอคงรู้\n\nข้าต้องให้กู้ Kroshius' Infernal Core" },
            { "421:481470527:308841480", "หากจะสอนความลับเรียก Infernal ผู้รับใช้ เจ้าต้องทำลาย Kroshius นำแก่นจากซากไหม้มา แต่ไม่ง่าย Kroshius แทบมอดหมด ต้องจุดศพให้ลุกแล้วปลุกจากซาก จึงต้องเก็บวัสดุจากปีศาจอื่น\n\nImpsy อิมป์ข้าจะนำทาง" },
        },
    },
    [14470] = {
        name = "Impsy",
        lines = {
            { "22:2016876920:1705747385", "บางคนเรียกข้าว่า... Impsy?" },
