    [5888] = {
        name = "Seer Ravenfeather",
        lines = {
            { "24:661104911:1638611114 N 85:1015070047:21722652", "แผ่นดินเรียกหาเจ้า {name} ไปหาเถิด และจงรู้ว่าพี่น้องภูมิใจในตัวเจ้าและทุกสิ่งที่เจ้าจะทำสำเร็จ" },
            { "24:661104911:1638611114 U 85:1015070047:21722652", "แผ่นดินเรียกหาเจ้า {name} ไปหาเถิด และจงรู้ว่าพี่น้องภูมิใจในตัวเจ้าและทุกสิ่งที่เจ้าจะทำสำเร็จ" },
        },
    },
    [257446] = {
        name = "Teo Hammerstorm",
        lines = {
            { "136:544516154:1106906000 C 16:849330234:183190098", "หินและดินพูดจริงยิ่งกว่าลิ้นใด หากเจ้าสงบเสียงวุ่นวายในใจนานพอจะฟัง\n\nหากมีแววเป็น{class} ข้าจะสอนให้" },
            { "158:1567713712:2059012334", "หินและดินพูดจริงยิ่งกว่าลิ้นใด หากเจ้าสงบเสียงวุ่นวายในใจนานพอจะฟัง\n\nหากมีแววเป็นชาแมน ข้าจะสอนให้" },
        },
    },
    [251374] = {
        name = "Windshaper Boro",
        lines = {
            { "221:737115668:297886640", "วิญญาณลมอาจจากเราไป แต่พลังธาตุยังไม่พ้นเอื้อมเสียทีเดียว สำหรับผู้มีความอดทนแสวงหา\n\nหากเจ้าเริ่มเรียนวิถีชาแมนแล้ว ข้าช่วยให้เข้าใจพลังเหล่านั้นได้" },
        },
    },
    [254082] = {
        name = "Aarnor Galestrike <Shaman Trainer>",
        lines = {
            { "221:737115668:297886640", "วิญญาณลมอาจจากเราไป แต่พลังธาตุยังไม่พ้นเอื้อมเสียทีเดียว สำหรับผู้มีความอดทนแสวงหา\n\nหากเจ้าเริ่มเรียนวิถีชาแมนแล้ว ข้าช่วยให้เข้าใจพลังเหล่านั้นได้" },
        },
    },
    [257597] = {
        name = "Bruegs Kindleborn",
        lines = {
            { "29:1201010584:191584093", "ผู้ให้แสงสว่างต้องยอมเผาไหม้" },
            { "50:1485417442:884565302", "ไฟที่ร้อนที่สุดให้กำเนิดเหล็กกล้าที่แกร่งที่สุด" },
        },
    },
    [252382] = {
        name = "Sessaria Skystride",
        lines = {
            { "187:1959273015:1929731546 C 28:1113617869:1203299722", "วิญญาณลมอาจจากเราไป แต่พลังธาตุยังไม่พ้นเอื้อมเสียทีเดียว สำหรับผู้มีความอดทนแสวงหา\n\nหากเจ้าเริ่มเรียนวิถี{class}แล้ว ข้าช่วยให้เข้าใจพลังเหล่านั้นได้" },
        },
    },
    [258203] = {
        name = "Hervdana Saegrund",
        lines = {
            { "67:1240310903:1068854478", "ยินดีต้อนรับสู่บ้านเรียบง่ายของเรา หากอยากผึ่งตัวให้แห้งก็นั่งพักข้างไฟได้" },
        },
    },
    [251362] = {
        name = "Ailee Farheart",
        lines = {
            { "7:989913233:66981971 C 1:46:46", "สวัสดี {class}" },
            { "14:805923477:1276551343", "สวัสดี พราน" },
        },
    },
    [251487] = {
        name = "Ventaari Brightwish",
        lines = {
            { "41:1775627917:1124604238", "ให้ช่วยอะไร สหาย Windshaper?" },
            { "647:52795700:62987691", "Shen'dorei เป็นหนี้วิญญาณที่ช่วยเสมอ Windshaper สาบานชดใช้และคืนทุกสิ่งเหมือนเดิม น่าเสียดาย เมื่อไร้วิญญาณชี้ทาง เราแทบมืดบอดต่อสิ่งรอบตัวใน Skywall จนอันตราย\n\nHigh Order สายตาสั้นและหยิ่งเหมือนบรรพชน Highborne อยากเป็นนายควบคุมเวทของที่นี่ นี่คือเส้นทางที่ทำให้เราต้องหนี Kalimdor มาแต่แรก ข้ากลัวว่าเหมือนบรรพชน ความมั่นใจล้ำความสามารถไปไกล ผลอาจเป็นหายนะ" },
            { "616:1551356733:1857488366", "น่าเสียดาย Zephras กำลังเสื่อม ธาตุลมที่พาเรามา Skywall หลายพันปีก่อนหายไป ทำให้สูญเวทมากซึ่งพึ่งมาหลายพันปี\n\nเกาะเองก็ไม่มั่นคงจนอันตราย ขาดการติดต่อกับจังหวัดเกาะ Shen'dorei อื่น Windshaper ไม่กี่คนที่ยังมี Skysight พยายามติดต่อพี่น้องต่างเกาะ แต่ไร้คำตอบ\n\nหลายคนกลัวว่า Shen'dorei บน Zephras คือผู้คนทั้งหมดที่เหลือ" },
            { "460:1990653683:1073402115", "ข้าดูรัศมีแล้วรู้ว่ามีสายเลือด Highborne ใช่ไหม? ผู้เรียกตนว่า High Order แทบไม่เห็นพ้องกับคณะข้า Windshaper นอกความกลมกลืนที่พอมีใน Thendal Grove ความแตกต่างอาจลึกจนแบ่งแยกและรุนแรง\n\nระวังเมื่อเดินทางทั่ว Zephras Isle ข้าเตือนครั้งหนึ่ง... อย่าเป็นศัตรูกับ Windshaper" },
            { "651:1993971705:2144065455", "Shen'dorei เป็นหนี้วิญญาณที่ช่วยเสมอ Windshaper สาบานชดใช้และคืนทุกสิ่งเหมือนเดิม น่าเสียดาย เมื่อไร้วิญญาณชี้ทาง เราแทบมืดบอดต่อสิ่งรอบตัวใน Skywall จนอันตราย\n\nHigh Order สายตาสั้นและหยิ่งเหมือนบรรพชน Highborne อยากเป็นนายควบคุมเวทของที่นี่ นี่คือเส้นทางที่ทำให้เราต้องหนี Kalimdor มาแต่แรก ข้ากลัวว่าเหมือนบรรพชน ความมั่นใจล้ำความสามารถไปไกล ผลอาจเป็นหายนะ" },
            { "460:1848843184:219036186", "ข้าดูรัศมีแล้วรู้ว่ามีสายเลือด Highborne ใช่ไหม? ผู้เรียกตนว่า High Order แทบไม่เห็นพ้องกับคณะข้า Windshaper นอกความกลมกลืนที่พอมีใน Thendal Grove ความแตกต่างอาจลึกจนแบ่งแยกและรุนแรง\n\nระวังเมื่อเดินทางทั่ว Zephras Isle ข้าเตือนครั้งหนึ่ง... อย่าเป็นศัตรูกับ Windshaper" },
        },
    },
    [251906] = {
        name = "Teeri Wellwind",
        lines = {
            { "440:178897217:1560221593", "หากไม่ได้มาธุระ V.L.O. ข้าคงไม่มีเวลาคุยมาก แต่ถ้าจะช่วยเมือง ข้าจัดงานให้แน่\n\nอ้อ V.L.O. ย่ออะไร? Village Live Operations งานปฏิบัติการหมู่บ้านไง แม้เมืองชายแดนเช่นนี้ก็ไม่ได้ดูแลตัวเอง ทั้งเหตุใหญ่ พลังลมดับไม่คาด และแมลงระบาด ทำให้ที่นี่เดินต่อไม่ใช่เรื่องเล่น" },
            { "216:479409460:2066312674", "ข้าดูแลงาน Shen'dar Village มีเรื่องต้องติดตามมาก ทั้งโจร สาวกลัทธิ และเหตุสุ่มต่าง ๆ รักษาหมู่บ้านให้รอดใช้งานหนักไม่น้อย" },
        },
    },
    [251902] = {
        name = "Illaya Amberwind",
        lines = {
            { "304:1174946544:1759220113", "สวัสดีลูกเอ๋ย ข้า Illaya Amberwind ผู้เฒ่า Windshaper แห่ง Zephras Isle ยินดีเสมอที่เห็นใบหน้าหนุ่มสาวใหม่ลงจากป่า\n\nอย่าให้ชาแมนชราคนนี้ถ่วงเจ้า คงมีเรื่องผจญภัยมากมาย แวะมาทีหลังได้หากต้องการ" },
            { "402:1016538702:434964336", "เฮ้อ ข้าพูดมานานพอแล้ว หากไปท่า Valanaar จงหา Ayessa Dawnsinger ศิษย์ข้า นางยังได้ยินบทเพลง แม้เบาบาง ข้าแก่และเสียพลังไปมาก Ayessa คืออนาคตของเผ่าและเส้นทางที่ต้องเดินเพื่อรอด นางกับ Skyborne หนุ่มสาวเช่นเจ้าต้องพาความหวังของผู้คนต่อไป" },
            { "503:2141933261:2079041008", "ต้องจำว่าแม้ภพนี้เป็นบ้านมาหลายพันปี เราก็ยังแปลกถิ่นอยู่บ้าง ที่นี่ไม่ใช่โลกแผ่นดินที่ให้กำเนิดเผ่า เราอยู่ Skywall ส่วนหนึ่งของแดนธาตุ\n\nเรามาเป็นแขกของวิญญาณที่มีเป้าหมายร่วมเมื่ออดีตไกล ตอนนี้ Shen'dorei ไร้การอยู่ร่วมและอาจไร้การคุ้มครองจากพวกเขา จึงไม่รู้ชีวิตอื่นในภพจะมองเราอย่างไร" },
            { "546:1377291798:1239190945", "ตลอดที่ติดต่อวิญญาณลม ไม่เคยมีครั้งใดพูดถึง Windlord ด้วยความเคารพ พวกเขารับรู้สิ่งชื่อ Al'Akir แต่เลี่ยงเอ่ยชื่อ ราวหวาดกลัว\n\nแม้ Al'Akir จะเป็นเจ้าแห่งลมทรงอำนาจหรือผู้ปกครองธาตุลม หลายศตวรรษที่สื่อกับวิญญาณทำให้มั่นใจว่าอย่างน้อยไม่ใช่ทุกชีวิตใน Skywall รักเขา ข้ากลัวว่าเจรจากับ Al'Akir จะเร่งความพินาศเราเท่านั้น" },
            { "385:1683060438:448790468", "ลัทธิหรือ? พวกคลั่งและนักฆ่า เชื่อว่าเราถูกลงโทษจากบาปไม่ชัดเจนบางอย่าง ความจริงผู้นำเป็นพวกฉวยโอกาสที่เหลือจากคณะน่าสงสัยของผู้เรียกตนนักบวช Al'Akir เจ้าแห่งลม\n\nตอนนี้ใช้ความกลัวของผู้คนเป็นอาวุธรวบอำนาจได้... และรีบทำทันที" },
            { "457:1926580413:2133522911", "หลายคนไม่เห็นตรงกัน ข้าเชื่อว่าการสื่อสารเรียบง่ายคือกุญแจ เมื่อวิญญาณอยู่ เพลงลมชัดมาก ตั้งแต่จากไปก็เงียบลง พลัง Windshaper อ่อนแอ\n\nแต่บางคนยังได้ยินบางสิ่ง เสียงแผ่ว เศษทำนอง ผู้ที่ยังฟังและมองเข้าแดนธาตุได้ต้องแข็งแกร่งขึ้น ข้าเชื่อว่านั่นคือกุญแจทางรอด" },
            { "516:2142292267:1228232379", "ทำไมเกิดเรื่องนี้? พูดง่าย ๆ วิญญาณลมแค่... หายไป วันหนึ่งยังอยู่ วันต่อมาไม่แล้ว บรรยายความรู้สึก Windshaper ตอนนั้นยาก เหมือนความเงียบใหญ่คลุมทุกคน แล้ว... ความว่างเปล่าลึกล้ำ\n\nภูตผีเล็กที่เจ้าอาจพบเป็นเพียงเงาของความยิ่งใหญ่วิญญาณลมแท้ ไร้สติ ไร้จุดหมาย ห่างไกลจากวิญญาณเมตตาที่เราอยู่กลมกลืนมาหลายพันปี" },
            { "291:603443553:2114536701", "เริ่มตรงไหนดี? บ้านเรากำลังล้มเหลว เกราะคุ้มกันพัง สามจังหวัดเริ่มลอยห่าง ไม่นานมานี้ยังเห็นยอดหอ Shen'dramar จากหอตะวันตก ตอนนี้ไม่แล้ว เสาไพลอนสมออ่อนแรง หากโซ่ขาดในที่สุด..." },
            { "193:1444422319:291400124 C 105:1507205100:871983437", "สวัสดีลูกเอ๋ย ข้า Illaya Amberwind ผู้เฒ่า Windshaper แห่ง Zephras Isle ยินดีเสมอที่เห็นใบหน้าหนุ่มสาวใหม่ลงจากป่า\n\nอย่าให้{class}ชราคนนี้ถ่วงเจ้า คงมีเรื่องผจญภัยมากมาย แวะมาทีหลังได้หากต้องการ" },
            { "457:1625943590:895951706", "หลายคนไม่เห็นตรงกัน ข้าเชื่อว่าการสื่อสารเรียบง่ายคือกุญแจ เมื่อวิญญาณอยู่ เพลงลมชัดมาก ตั้งแต่จากไปก็เงียบลง พลัง Windshaper อ่อนแอ\n\nแต่บางคนยังได้ยินบางสิ่ง เสียงแผ่ว เศษทำนอง ผู้ที่ยังฟังและมองเข้าแดนธาตุได้ต้องแข็งแกร่งขึ้น ข้าเชื่อว่านั่นคือกุญแจทางรอด" },
            { "158:2147226951:105318313 C 234:166077618:706702080", "ข้าไม่ได้ติดใจอะไรกับสมาชิก High Order อย่างเจ้าเป็นการส่วนตัว แต่ข้าก็ไม่จำเป็นต้องสนทนากับเจ้า ไปโดยสงบเถอะ {class} ข้าขอเตือนจริง ๆ ว่าระหว่างที่เจ้าเดินทางใน Zephras Isle อย่าเข้ามายุ่งกับเรื่องของ Windshaper\n\nถ้าเจ้าทำ เรื่องจะจบไม่สวยสำหรับเจ้า ชาว Windshaper ไม่ให้อภัยง่าย ๆ เมื่อมีใครล่วงเกินสิ่งที่เราถือว่าศักดิ์สิทธิ์" },
        },
    },
    [251523] = {
        name = "Constable Aonda",
        lines = {
            { "374:1264034303:1194489675", "มากกว่าที่อยากให้มีเสียอีก โจรตั้งถ้ำทางเหนือรังควานเรา ลัทธิ Al'Aketh เพิ่งยึด Falaath Village ทางใต้ ข้าไว้ใจ Peacekeeper กับชาวบ้านทุกคน แต่มีน้อยเกินรักษาหมู่บ้าน\n\nหากลัทธิขยายต่อ เราหยุดแทบไม่ได้" },
            { "77:292951271:1242770910", "<Constable Aonda สีหน้าเคร่งเครียด เห็นชัดว่ากำลังครุ่นคิด>" },
        },
    },
    [251905] = {
        name = "Zerril Softbreeze",
        lines = {
            { "125:1150616574:873109746", "หากต้องการฝึกทำอาหาร ข้ามีเคล็ดลับส่งต่อ! โฮ่ ๆ! สวมผ้ากันเปื้อนแล้วเริ่มกัน!" },
            { "225:192894425:773699048", "เฮ้ นักเดินทาง! มาใหม่หรือ? ตั้งหลักแล้วมาหาข้าหากอยากทำงาน ข้าทำเกินเวลาเพื่อเตรียม Festival of Winds ต้องการทุกแรงช่วยเติมคลังอาหาร!" },
            { "226:1163442285:508011037", "เฮ้ นักเดินทาง! มาใหม่หรือ? ตั้งหลักแล้วมาหาข้าหากอยากทำงาน ข้าทำเกินเวลาเพื่อเตรียม Festival of Winds ต้องการทุกแรงช่วยเติมคลังอาหาร!" },
        },
    },
    [249363] = {
        name = "Yala Windwatcher",
        lines = {
            { "128:351830334:401733262", "วิญญาณลมจากเราไปแล้ว\n\nตอนนี้เหลือเพียงเสียงสะท้อนไร้สติ แต่ระวัง สายลมเหล่านี้ไม่เมตตาและไม่อ่อนโยน" },
            { "124:382430387:377306734", "วิญญาณลมจากเราไปแล้ว\n\nตอนนี้เหลือเพียงเสียงสะท้อนไร้สติ แต่ระวัง สายลมเหล่านี้ไม่เมตตาและไม่อ่อนโยน" },
        },
    },
    [251684] = {
        name = "Strange Hermit",
        lines = {
            { "100:1307012473:158267734", "อ้อ ไม่เป็นไร ขะ... ข้าจะอยู่ที่นี่หากอยากเรียนคราวหน้า ขะ... ขอบคุณที่คุยด้วย!" },
            { "367:789263364:618887608", "อ้อ ของพวกนี้หรือ? ข้าสร้างเอง เพื่อนตัวน้อยช่วย ข้าจำไม่ค่อยเก่ง แต่รู้ว่าครั้งหนึ่งเคยสร้างของมาก ของใหญ่! แล้วอย่างที่บอก... ข้าก็มาอยู่ที่นี่ ของที่สร้างไม่ใหญ่โตน่าทึ่งแล้ว แต่ยังทำให้ขะ... ข้ามีความสุข เฮะ\n\nตะ... แต่หากต้องการ ข้าสอนให้สร้างของได้!" },
            { "361:1047206979:726706002", "นั่น... เป็นคำถามดีมาก ข้าจำลำบาก แต่จำบางอย่างได้... วิศวกรหรือเปล่า? คิดว่านั่นคือสิ่งหรือคนที่ข้าเคยเป็น\n\nนอกจากนั้นจำได้เพียงบินทะยานบนฟ้า แล้วเห็นฟ้าแลบก่อนสั่นกระแทกหนัก จากนั้น... ตก\n\nแต่ผ่าน... มานาน นานมากแล้ว" },
            { "73:1691598304:806548666", "สะ... สวัสดี ขอโทษด้วย ข้าชินที่คนแบบเจ้าวิ่งหนี" },
            { "368:1132092392:1385648188", "อ้อ ของพวกนี้หรือ? ข้าสร้างเอง เพื่อนตัวน้อยช่วย ข้าจำไม่ค่อยเก่ง แต่รู้ว่าครั้งหนึ่งเคยสร้างของมาก ของใหญ่! แล้วอย่างที่บอก... ข้าก็มาอยู่ที่นี่ ของที่สร้างไม่ใหญ่โตน่าทึ่งแล้ว แต่ยังทำให้ขะ... ข้ามีความสุข เฮะ\n\nตะ... แต่หากต้องการ ข้าสอนให้สร้างของได้!" },
            { "362:1505982633:489824207", "นั่น... เป็นคำถามดีมาก ข้าจำลำบาก แต่จำบางอย่างได้... วิศวกรหรือเปล่า? คิดว่านั่นคือสิ่งหรือคนที่ข้าเคยเป็น\n\nนอกจากนั้นจำได้เพียงบินทะยานบนฟ้า แล้วเห็นฟ้าแลบก่อนสั่นกระแทกหนัก จากนั้น... ตก\n\nแต่ผ่าน... มานาน นานมากแล้ว" },
        },
    },
    [251991] = {
        name = "Taleen Shimmerthread",
        lines = {
            { "317:658188437:1681974482", "งานผ้า Shen'dorei เลียนกระแสลมอิสระไหลลื่นอย่างกลมกลืน แม้วิญญาณจากไปและไม่รู้เมื่อใดจะได้เห็นเต้นรำอีก... ศิลปะยังปลอบใจอย่างยิ่ง อย่างน้อยก็ช่วยเบี่ยงความคิด\n\nข้าสอนทำผ้าให้ได้ อยากเรียนไหม?" },
        },
    },
    [252359] = {
        name = "Lotheluum Starbreeze",
        lines = {
            { "100:1720354603:1672286541", "พวกเรามีน้อยในยามนี้ แต่ในหมู่ Shen'dorei ยังมีผู้ฝันกลางมรกต" },
            { "213:320318744:2098873535", "พวกเรามีน้อยในยามนี้ แต่ในหมู่ Shen'dorei ยังมีผู้ฝันกลางมรกต\n\nลืมตาให้ดีในป่า แสงที่เหมาะอาจเผยสิ่งซ่อนเร้นซึ่งลมเหนือคุ้มครอง" },
            { "255:967301392:2039283435", "นอกจากฝึกให้เจ้าแล้ว ข้ายังลบความรู้เรื่องพรสวรรค์ออกจากความทรงจำของเจ้าได้ด้วย หากเจ้าต้องการ ขอเตือนไว้ก่อนว่าแต่ละครั้งที่ทำ ขั้นตอนจะยากขึ้น และค่าใช้จ่ายก็สูงขึ้นตามไปด้วย" },
        },
    },
    [252475] = {
        name = "Elaadrin Evengale",
        lines = {
            { "102:224333219:1420782425", "สวัสดี ข้า Elaadrin Evengale ผู้ดำรงตำแหน่ง Supreme Magister แห่ง High Order ให้ช่วยอะไร?" },
            { "206:592425056:752621050", "เข้าใจ ดูอันตรายสุดขีด แต่สถานการณ์คงบังคับให้เสี่ยง\n\nได้ High Order จะช่วย โปรดบอก Valennia ว่านับเราเข้าร่วมศึกได้" },
            { "512:982611516:2062627254", "Windshaper แทบต้องรับผิดทุกสิ่งที่เกิด การไม่ยอมเปลี่ยนทำลายความสามารถช่วยตัวเองจากภัย พวกเขาพูดอย่างตายตัว ถือข้อสมมติและหวังงมงายเป็นจริง\n\nรู้ไหมใครยึดแต่ความตายตัวอีก? Al'Aketh\n\nข้าจะไม่ยอมให้ยึดความเชื่ออันตรายมืดบอดทำเผ่าพินาศ หากไม่ติดภัยลัทธิ ข้าจะพาเมจข้ามไปอีกฝั่ง Valnaar แล้วกวาด Windshaper ให้สิ้น" },
            { "516:758909053:1739246682", "Windshaper แทบต้องรับผิดทุกสิ่งที่เกิด การไม่ยอมเปลี่ยนทำลายความสามารถช่วยตัวเองจากภัย พวกเขาพูดอย่างตายตัว ถือข้อสมมติและหวังงมงายเป็นจริง\n\nรู้ไหมใครยึดแต่ความตายตัวอีก? Al'Aketh\n\nข้าจะไม่ยอมให้ยึดความเชื่ออันตรายมืดบอดทำเผ่าพินาศ หากไม่ติดภัยลัทธิ ข้าจะพาเมจข้ามไปอีกฝั่ง Valanaar แล้วกวาด Windshaper ให้สิ้น" },
            { "259:1726236621:1966044200", "<Elaadrin มองเจ้าด้วยความเกลียดที่แทบกลั้นไม่อยู่>\n\nกล้าเข้ามาเขตศักดิ์สิทธิ์เราหลังหลั่งเลือด High Order หรือ? เจ้ากล้ามากหรือโง่มาก High Order ไม่ให้อภัยและไม่ลืม\n\nสักวันเจ้าต้องชดใช้ความผิดด้วยเลือด" },
            { "28:465887617:2081143589 C 282:855907745:934967899", "อืม เข้าใจ ได้เลย {class} High Order จะช่วย Peacekeeper บอก Valennia ว่านับเราเข้าร่วมศึกได้\n\n<Elaadrin ลดเสียงอย่างน่ากลัว>\n\nอย่าเข้าใจว่าร่วมมือเต็มใจคือผ่อนโทษ เจ้าติดหนี้เลือด High Order และเราทวงหนี้เสมอ" },
        },
    },
    [251371] = {
        name = "Falorne Fallwind",
        lines = {
            { "45:231378001:174665364", "สวัสดี สหายผู้เริ่มฝึก High Order" },
            { "508:253632510:875504597", "เวททำได้แทบทุกอย่าง แต่ความหยุดนิ่งไม่ลงมือทำให้สูญเสียตัวเองมากตลอดหลายพันปีนับจากออก Kalimdor High Order มุ่งเรียกคืนมรดก Highborne ที่ทิ้งไว้ เพื่อเป็นนายชะตาอีกครั้ง\n\nWindshaper คิดว่าเราแค่บุ่มบ่ามหยิ่งผยอง ข้าว่าหน้าซื่อใจคดที่สุด เรื่องวิกฤตนี้พวกเขาไม่รับความคิดอื่นนอกจากตน ข้าสงสัยว่าใครหยิ่งกันแน่?" },
            { "436:346432164:920636866", "Zephras อันตรายหนัก ธาตุลมที่พาเรามา Skywall หลายพันปีก่อนทอดทิ้ง ทำให้เปราะบางในภพไม่มั่นคง สังคมแข็งแกร่งเดิมครอบคลุมเขตเกาะพักพิงหลายแห่งในมุม Skywall ของเรา แต่ตอนนี้ไม่แน่ใจว่ายังมี Shen'dorei นอกเกาะเล็กนี้หรือไม่\n\nสถานการณ์เลวร้าย แต่ High Order มุ่งรับความท้าทาย" },
            { "524:386136525:216383636", "สวัสดี... Windshaper\n\nผู้เรียกตน Windshaper แทบไม่มีเป้าหมายร่วมกับ High Order ส่วนใหญ่ อย่างที่คงรู้ นอกความกลมกลืนที่พอมีใน Thendal Grove ความแบ่งแยกลึกจนบางครั้งคู่แข่งใช้ความรุนแรงตรง ๆ\n\nข้าจะไม่พูดต่อ นอกจากดูธุระตนและอย่าขัดเป้า High Order เมื่อออกจากป่า นี่อาจเป็นคำเตือนเดียวที่จะได้" },
            { "524:184022469:1194859945", "สวัสดี... Windshaper\n\nผู้เรียกตน Windshaper แทบไม่มีเป้าหมายร่วมกับ High Order ส่วนใหญ่ อย่างที่คงรู้ นอกความกลมกลืนที่พอมีใน Thendal Grove ความแบ่งแยกลึกจนบางครั้งคู่แข่งใช้ความรุนแรงตรง ๆ\n\nข้าจะไม่พูดต่อ นอกจากดูธุระตนและอย่าขัดเป้า High Order เมื่อออกจากป่า นี่อาจเป็นคำเตือนเดียวที่จะได้" },
        },
    },
    [263113] = {
        name = "Myriaal Mistwake",
        lines = {
            { "114:947325020:920128925", "อยู่ข้างบนน่าเบื่อรู้ไหม แม้กวนเจ้าทึ่มเคร่ง Halaan ไปนานก็ยังเบื่อ" },
        },
