    [257006] = {
        name = "Nyalah Brightfire",
        lines = {
            { "113:1444860853:806791977", "ไม่ค่อยมีพ่อครัวมาหาฝึก แต่คงสอนบางอย่างให้ได้หากพร้อม" },
            { "343:1268981406:716044532", "ทำอาหารบน Zephras อาจดูยากสำหรับคนไม่รู้ แต่ข้าสนุกกับทุกจาน แม้บ้านที่ร่อยหรอขาดวัตถุดิบ Kaldorei ดั้งเดิมมากมาย ก็สนุกที่สร้างสูตรบรรพชนแบบใหม่\n\nหวังว่าไม่ว่าสายลมพาไปไหน สูตรเหล่านี้จะเตือนถึงบ้าน" },
            { "343:509645572:1752414989", "ทำอาหารบน Zephras อาจดูยากสำหรับคนไม่รู้ แต่ข้าสนุกกับทุกจาน แม้บ้านที่ร่อยหรอขาดวัตถุดิบ Kaldorei ดั้งเดิมมากมาย ก็สนุกที่สร้างสูตรบรรพชนแบบใหม่\n\nหวังว่าไม่ว่าสายลมพาไปไหน สูตรเหล่านี้จะเตือนถึงบ้าน" },
            { "130:381945842:441916250", "ดูเหมือนสายลมพามาหาข้า! ข้ายินดีฝึกวิถีทำอาหารให้ หากอยากเรียน" },
        },
    },
    [251904] = {
        name = "Sania Silverstream",
        lines = {
            { "11:927657569:725753248 C 52:1293047476:253489892", "สวัสดี {class} มาขอพรเจ้าแห่งลมหรือ?" },
            { "529:1076434274:286470627", "สวัสดี สหาย ข้า Sania Silverstream ผู้เผยแผ่รับใช้นายผู้ทรงอำนาจ Al'Akir the Windlord\n\nAl'Aketh ถูกเรียกอย่างดูหมิ่นว่าลัทธิรุนแรง แต่จริงเราแสวงหาสันติและการรู้แจ้ง องค์ Al'Akir เป็นพลังสูงสุดใน Skywall มีแต่กรุณาเขาที่ทำให้รอดบททดสอบวันนี้\n\nหากอยากฟังข่าวดีเพิ่ม เรียกข้าเมื่อใดก็ได้แล้วคุยต่อ ขอพรเจ้าแห่งลมอยู่กับเจ้า สหาย" },
            { "162:1718259359:1157959358", "<Sania ไม่พูดอะไร เอาแต่จ้องเจ้าด้วยความเกลียดชังที่แทบเก็บไว้ไม่อยู่ ข่าวเรื่องที่เจ้าทำใน Falaath Village คงมาถึงหูนางแล้ว>" },
        },
    },
    [257065] = {
        name = "Missionary Jasaan",
        lines = {
            { "42:1916228485:1591052830", "แสวงหาพรเจ้าแห่งลมหรือ?" },
        },
    },
    [252476] = {
        name = "Talaanis Shadowsong",
        lines = {
            { "21:1723102709:2117072945 C 1:46:46", "ยินดีต้อนรับ Valanaar {class}" },
            { "132:500022050:468950988", "เราต้องรู้แผนลัทธิเพิ่ม เมื่อผู้แปรพักตร์ตาย ข้อมูลก็อาจตายพร้อมเขา..." },
            { "133:1175557248:658097413", "เราต้องรู้แผนลัทธิเพิ่ม เมื่อผู้แปรพักตร์ตาย ข้อมูลก็อาจตายพร้อมเขา..." },
        },
    },
    [251903] = {
        name = "Rathiril Sunlance",
        lines = {
            { "336:1972738856:449479333", "เฮ้อ ข้าพูดมานานพอ หากไปท่า Valanaar จงหา Elaadrin Evengale เขาเคยเป็นศิษย์ แต่ตอนนี้เป็น Chief Magister แห่ง High Order ดื้อรั้นแต่สามารถ ถึงตาเขากับ Skyborne หนุ่มสาวเช่นเจ้าพาความหวังของผู้คนต่อไป" },
            { "495:16972234:1703453517", "ต้องจำว่าแม้ภพนี้เป็นบ้านมาหลายพันปี เราก็ยังแปลกถิ่นอยู่บ้าง ที่นี่ไม่ใช่โลกแผ่นดินที่ให้กำเนิดเผ่า เราอยู่ Skywall แดนธาตุลม\n\nเรามาเป็นแขกของวิญญาณที่ผูกพันเมื่ออดีตไกล ตอนนี้ Shen'dorei ไร้การอยู่ร่วมและอาจไร้การคุ้มครองจากพวกเขา จึงไม่รู้ชีวิตอื่นในภพจะมองเราอย่างไร" },
            { "406:690458651:1817600440", "แม้ Windshaper ก็คงบอกว่าวิญญาณไม่เคยยกย่องผู้สูงสุดในหมู่ตน รับรู้สิ่งชื่อ Al'Akir แต่เลี่ยงเอ่ยชื่อ ราวหวาดกลัว\n\nแม้ Al'Akir จะเป็นเจ้าแห่งลมทรงอำนาจหรือผู้ปกครองธาตุลม การพึ่งธาตุต่างหากพาเราสู่ความยุ่งนี้ ตอนนี้ต้องหาทางออกเอง" },
            { "385:1683060438:448790468", "ลัทธิหรือ? พวกคลั่งและนักฆ่า เชื่อว่าเราถูกลงโทษจากบาปไม่ชัดเจนบางอย่าง ความจริงผู้นำเป็นพวกฉวยโอกาสที่เหลือจากคณะน่าสงสัยของผู้เรียกตนนักบวช Al'Akir เจ้าแห่งลม\n\nตอนนี้ใช้ความกลัวของผู้คนเป็นอาวุธรวบอำนาจได้... และรีบทำทันที" },
            { "356:888216510:429788249", "หลายคนไม่เห็นตรงกัน Windshaper อยากให้เชื่อว่าจับมือหวังให้วิญญาณกลับก็พอ แต่พลังคณะอ่อนลง เส้นทางนั้นพากลับวงจรพึ่งพาที่ทำให้มาถึงจุดนี้ ส่วน High Order... เชื่อวิธีตรงกว่า" },
            { "317:1283857681:1467581257", "ทำไมเกิดเรื่องนี้? พูดง่าย ๆ วิญญาณลมแค่... หายไป\n\nภูตเล็กกับธาตุชั้นน้อยที่เจ้าอาจพบเป็นแบบจำลองซีดจางของวิญญาณลมแท้ ไร้สติ ไร้จุดหมาย ห่างไกลจากวิญญาณเมตตาที่เราอยู่กลมกลืนมาหลายพันปี" },
            { "295:884945764:386520432", "เริ่มตรงไหนดี? บ้านเรากำลังล้มเหลว เกราะคุ้มกันพัง สามจังหวัดเริ่มลอยห่าง ไม่นานมานี้ยังเห็นยอดหอ Shen'dramar จากหอตะวันตก ตอนนี้ไม่แล้ว ทุกวันไพลอนลมที่ยึดบ้านกับภพนี้อ่อนแรง..." },
            { "19:426998529:1881872225 C 224:685697544:1467616159 C 124:815242105:1449839134", "สวัสดี {class} น้อย ข้า Rathiril Sunlance จอมเวทอาวุโส High Order บน Zephras Isle ยินดีเสมอที่เห็น Shen'dorei หนุ่มสาวตาสดใสพร้อมทำหน้าที่รับใช้บ้าน\n\nแต่อย่าให้{class}ชราเขรอะฝุ่นนี้ถ่วง คงมีเรื่องผจญภัยมากมาย แวะทีหลังได้หากอยากคุยต่อ" },
            { "19:426998529:1881872225 C 352:1599853132:928166648", "สวัสดี {class} น้อย ข้า Rathiril Sunlance จอมเวทอาวุโส High Order บน Zephras Isle ยินดีเสมอที่เห็น Shen'dorei หนุ่มสาวตาสดใสพร้อมทำหน้าที่รับใช้บ้าน\n\nแต่อย่าให้จอมเวทชราเขรอะฝุ่นนี้ถ่วง คงมีเรื่องผจญภัยมากมาย แวะทีหลังได้หากอยากคุยต่อ" },
            { "418:1887774572:313301583", "ข้าไม่ได้มีเรื่องส่วนตัวกับ Windshaper อย่างเจ้า แต่ก็ไม่จำเป็นต้องคุยด้วย ไปทำธุระเถิด และขอแนะนำหนักแน่นให้เว้น High Order กับผู้ปฏิบัติงานของเราไกล ๆ ระหว่างเดินทางบน Zephras Isle\n\nHigh Order ไม่แสวงหาความขัดแย้ง... แต่หากมันมาหา เราจะจบอย่างเด็ดขาด อย่าขวางทาง Windshaper" },
            { "19:426998529:1881872225 C 353:1488068030:2078801871", "สวัสดี {class} น้อย ข้า Rathiril Sunlance จอมเวทอาวุโส High Order บน Zephras Isle ยินดีเสมอที่เห็น Shen'dorei หนุ่มสาวตาสดใสพร้อมทำหน้าที่รับใช้บ้าน\n\nแต่อย่าให้จอมเวทชราเขรอะฝุ่นนี้ถ่วง คงมีเรื่องผจญภัยมากมาย แวะทีหลังได้หากอยากคุยต่อ" },
            { "19:426998529:1881872225 C 224:685697544:1467616159 C 125:1706496909:1698421409", "สวัสดี {class} รุ่นเยาว์ ข้าชื่อ Rathiril Sunlance เป็นจอมเวทอาวุโสแห่ง High Order บน Zephras Isle ยินดีเสมอที่ได้เห็นชาว shen'dorei รุ่นใหม่ตาเป็นประกาย พร้อมทำหน้าที่เพื่อบ้านเกิด\n\nอย่าให้ {class} แก่คร่ำครึอย่างข้าถ่วงเวลาเจ้าเลย เจ้าคงมีเรื่องผจญภัยอีกมาก ไว้แวะมาคุยต่อได้ทุกเมื่อ" },
            { "495:1046760306:1237431963", "จงจำไว้ แม้เราจะอยู่ที่นี่มานับพันปี แต่ก็ยังเป็นคนนอกสำหรับดินแดนนี้อยู่บ้าง เราอยู่คนละโลกกับผืนแผ่นดินที่ให้กำเนิดชนของเรา ที่นี่คือ Skywall ระนาบธาตุแห่งลม\n\nเรามาที่นี่ในฐานะแขกของเหล่าวิญญาณที่ผูกพันกับเรามาแต่โบราณ ตอนนี้ชาว shen'dorei อย่างเราสูญเสียพวกเขาไป และอาจสูญเสียการคุ้มครองของพวกเขาด้วย ไม่มีใครบอกได้ว่าผู้อาศัยอื่นในระนาบนี้จะมองเราอย่างไร" },
            { "386:1716073353:537751518", "พวกลัทธินั่นหรือ พวกมันคลั่งและฆ่าคน พวกมันเชื่อว่าเราถูกลงโทษเพราะบาปบางอย่างที่บอกไม่ได้ว่าคืออะไร ความจริงผู้นำพวกมันเป็นพวกฉวยโอกาสที่เหลือจากคณะน่าสงสัยที่เรียกตัวเองว่า ‘นักบวช’ ของ Al'Akir เจ้าแห่งลม\n\nตอนนี้พวกมันสบช่องเอาความกลัวของชนเรามาใช้รวบอำนาจ... และรีบลงมือทันที" },
            { "358:1388639220:958974315", "หลายคนเห็นต่างในเรื่องนี้ พวก Windshapers อยากให้เจ้าเชื่อว่าแค่ร่วมมือกันแล้วหวังให้เหล่าวิญญาณกลับมาก็พอ แต่อำนาจของคณะนั้นเสื่อมลงแล้ว และวิธีของพวกเขาจะพาเรากลับไปพึ่งพาผู้อื่นเหมือนที่ทำให้เรามาถึงจุดนี้ ส่วน High Order อย่างเรา... เชื่อว่าควรลงมือแก้ปัญหาโดยตรงกว่านั้น" },
            { "268:1689495172:964267140 R 60:347452348:412087919", "เฮ้อ ข้าพูดเสียยืดยาวแล้ว หากเจ้าไปถึงท่าเรือ Valanaar จงไปหา Elaadrin Evengale เขาเคยเป็นศิษย์ข้า แต่ตอนนี้เป็นจอมเวทสูงสุดของ High Order เขาทั้งหัวแข็งและมีฝีมือ บัดนี้ความหวังของชนเราอยู่ในมือเขากับ{race}รุ่นเยาว์อย่างเจ้า" },
        },
    },
    [254151] = {
        name = "Vayn Moongaze",
        lines = {
            { "93:1359119010:744409984 C 1:46:46", "Nightclaw ไม่ต้อนรับผู้บุกรุกบุ่มบ่าม เดินระวังใน Shadowgale {class}" },
            { "55:281851953:542075682 C 425:533034785:17030683", "เจ้าได้รับความไว้ใจในหมู่ Nightclaw พอสมควร {class} เราไม่ค่อยมีรางวัลให้ แต่กู้แบบงานฝีมือจากซาก Ban'aethal ได้หลายชิ้น\n\nช่างเวท Ban'aethal ขึ้นชื่อว่าดีที่สุดทั่วหมู่เกาะ Skyborne ส่วน Nightclaw เป็นนักธรรมชาติ ไม่ใช่ช่าง บันทึกจึงมีประโยชน์น้อย\n\nพิสูจน์เป็นพันธมิตรมีค่าต่อ แล้วข้าจะเปิดความลับเหล่านี้ให้" },
            { "55:281851953:542075682 C 224:1012264501:1140996136 R 193:884066047:1159904383", "เจ้าได้รับความไว้วางใจจาก Nightclaw มาบ้างแล้ว {class} เราไม่มีของตอบแทนมากนัก แต่เก็บแบบงานช่างจำนวนหนึ่งมาจากซากเมือง Ban'aethal ได้\n\nช่างเวทแห่ง Ban'aethal ขึ้นชื่อว่าเป็นช่างฝีมือที่เก่งที่สุดในหมู่เกาะ{race} พวก Nightclaw เชี่ยวชาญเรื่องธรรมชาติ ส่วนงานช่างไม่ใช่ทางของเรา บันทึกเหล่านี้จึงแทบไม่มีประโยชน์กับพวกเรา\n\nจงพิสูจน์ต่อไปว่าเจ้าเป็นพันธมิตรที่พึ่งได้ แล้วข้าจะให้เจ้าเข้าถึงความลับเหล่านี้" },
        },
    },
    [252155] = {
        name = "Peacekeeper Vaaniel",
        lines = {
            { "116:247970414:1158215608", "<ศพตรงหน้าเต็มรอยไหม้ ดูเหมือนกำบางอย่างในมือ>" },
        },
    },
    [252378] = {
        name = "Yorana Windyreed",
        lines = {
            { "37:1767976590:411260545", "พายุสาปพวกคลั่ง Al'Aketh!" },
        },
    },
    [256083] = {
        name = "Riaani Nightwind",
        lines = {
            { "72:1598151413:1932254699", "<Riaani ดูมุ่งมั่นจดจ่อกับงานสิ่งสร้างลม>" },
            { "32:1332795645:979076370", "พบสิ่งที่ต้องการหรือยัง?" },
        },
    },
    [253844] = {
        name = "Valennia Stormfist",
        lines = {
            { "19:1454775137:823929483", "สวัสดี พลเมือง" },
        },
    },
    [253590] = {
        name = "Valennia Stormfist",
        lines = {
            { "73:1003755865:1787235214", "<Valennia บาดเจ็บสาหัส แทบประคองสติไว้ไม่อยู่>" },
        },
    },
    [253576] = {
        name = "Hyusaa Quickbreeze",
        lines = {
            { "397:1873113186:1788874890", "สาวกส่วนใหญ่ใน Sanctum of Storms ดูออกมารับการโจมตีเรา ไม่นึกจะราบรื่นอย่างนี้ ง่ายเกินไปแทบไม่น่าเชื่อ...\n\nข้าว่า Windshaper กับ High Order ฝ่าเข้าแล้ว Valennia คงอยู่ด้วย เจ้าเข้าไปหานาง เราจะเฝ้าที่นี่ระหว่างพวกนางทำงานที่มุ่งมาจบ" },
        },
    },
    [252448] = {
        name = "Alvarion Windfield",
        lines = {
            { "30:1183248319:1336516245 N 1:46:46", "ยินดีเสมอที่เห็นเจ้า {name}" },
            { "93:1405477430:1292071928", "<ชายที่นอนตรงหน้าขยับอึดอัด กำลังฟื้นจากบาดแผลเลวร้าย>" },
        },
    },
    [251968] = {
        name = "Ayessa Dawnsinger",
        lines = {
            { "28:465887617:2081143589 C 258:540056772:975997839", "อืม เข้าใจ ได้เลย {class} Windshaper จะช่วย บอก Valennia ว่านับเราเข้าร่วมศึกได้\n\n<Ayessa ลดเสียงลงอย่างน่ากลัว>\n\nอย่าเข้าใจว่าร่วมมือคือให้อภัย เจ้าติดหนี้เลือด Windshaper สักวันเราจะทวง" },
            { "329:1379850506:1742400582", "<Ayessa Dawnsinger มองเจ้าอย่างแทบกลั้นโกรธไม่อยู่>\n\nเจ้ากล้ามากหรือโง่มาก ที่เดินเข้าเขตเราโจ่งแจ้งหลังหลั่งเลือด Windshaper เราให้อภัยช้าและไม่เคยลืม\n\nออกไปทันที หากไม่ได้อยู่กลาง Zephras เจ้าตายแล้ว" },
            { "103:1481128031:349536155", "สวัสดี ข้า Ayessa Dawnsinger ผู้ดำรงตำแหน่ง Grand Skyseer แห่ง Windshaper ให้ช่วยอะไร?" },
            { "28:465887617:2081143589 C 99:1894751554:2021482356", "อืม เข้าใจ ได้เลย {class} Windshaper จะช่วย บอก Valennia ว่านับเราเข้าร่วมศึกได้" },
            { "588:812174042:1957406487", "ถ้า High Order สนใจแก้ปัญหาจริงและมัวหมกเวทเก่าน้อยลง ผู้คนคงอยู่ดีกว่านี้มาก เวท Highborne ทำ Kaldorei พินาศมาแต่แรก เจ้าพวกเห็นแก่ตัวกลับอยากทำผิดซ้ำ!\n\nแค่พยายามเจรจาสงบกับลัทธิก็เลวพอแล้ว แต่หลั่งเลือด Windshaper คือสิ่งให้อภัยไม่ได้จริง หากไม่ติดภัยลัทธิใกล้เข้ามา ข้าจะรวมกำลังจบ Elaadrin กับ High Order ให้สิ้นครั้งเดียว" },
        },
    },
    [253372] = {
        name = "Dead Cultist",
        lines = {
            { "146:2089843672:2072750108", "<สาวกนี้ตายแล้ว เมื่อตรวจใกล้ เจ้าพบว่าเขากำบางสิ่งแนบอก ราวพยายามปกป้องไว้>" },
        },
    },
    [257008] = {
        name = "Baelann Swiftcurrent",
        lines = {
            { "57:1072220098:1964748388", "อา สวัสดี ดูเหมือนมีคำถามจะถามข้า" },
            { "64:41659015:1701991556", "ขอสายลมทักทาย สหาย มีอะไรให้ช่วยไหม?" },
            { "106:328912871:1661237448", "อ้อ คนตกปลาเหมือนกันนี่เอง เจ้าพออยากฝึกเพิ่มไหม? ข้าอาจสอนอะไรให้สักสองอย่างได้" },
            { "40:1568060028:1528601313", "ขอให้สายลมนำข่าวดีมาให้ มีอะไรให้ข้าช่วยไหม?" },
            { "94:569651677:64472594", "หวังว่าที่เจ้ามาขัดจังหวะจะมีเหตุผลดี ๆ นะ ข้ากำลังทำงานสำคัญอยู่" },
            { "155:719259708:1230994282", "ฝีมือเจ้าเหนือกว่าข้าแล้ว แต่ได้ยินว่า Old Man Heming ที่ Booty Bay มีหนังสือ The Bass and You อยู่ นั่นน่าจะช่วยให้เจ้าพัฒนาฝีมือได้แน่" },
        },
    },
    [254345] = {
        name = "Syriel Nightrain",
        lines = {
            { "57:1072220098:1964748388", "อา สวัสดี ดูเหมือนมีคำถามจะถามข้า" },
            { "119:1215038821:314796156", "ผู้เก็บสมุนไพรอีกคนหรือ หืม ข้าสงสัยว่าทักษะยังไม่เท่าข้า บางทีฝึกวิธีที่เหมาะสมให้ได้สักหน่อย" },
            { "40:1568060028:1528601313", "ขอให้สายลมพัดพาข่าวดีมาให้ มีอะไรให้ข้าช่วยไหม?" },
            { "64:41659015:1701991556", "ขอให้สายลมทักทายเจ้า สหาย มีอะไรให้ข้าช่วยไหม?" },
        },
    },
    [257004] = {
        name = "Eaysaa Brightgust <Enchanter>",
        lines = {
            { "57:1072220098:1964748388", "อา สวัสดี ดูเหมือนมีคำถามจะถามข้า" },
            { "40:1568060028:1528601313", "ขอสายลมส่งข่าวดี ให้ช่วยอะไร?" },
            { "64:41659015:1701991556", "ขอสายลมทักทาย สหาย มีอะไรให้ช่วยไหม?" },
            { "107:473644984:1688949623", "<ช่างเสริมมนตร์> ยินดีต้อนรับสู่ร้านข้า ดีใจที่ได้พบช่างเสริมมนตร์อีกคนที่ Valanaar เจ้ามาเรียนวิชาหรือเปล่า?" },
            { "107:1414585332:1999320415", "ยินดีต้อนรับสู่ร้านของข้า ดีใจที่ได้เจอช่างลงมนตร์อีกคนที่ Valanaar เจ้ามาเรียนวิชาหรือเปล่า?" },
            { "94:569651677:64472594", "หวังว่าที่เจ้ามาขัดจังหวะจะมีเหตุผลดี ๆ นะ ข้ากำลังทำงานสำคัญอยู่" },
        },
    },
    [257007] = {
        name = "Melasa Fairmend",
        lines = {
            { "40:1568060028:1528601313", "ขอสายลมส่งข่าวดี ให้ช่วยอะไร?" },
            { "94:569651677:64472594", "หวังว่าที่เจ้ามาขัดจังหวะจะมีเหตุผลดี ๆ นะ ข้ากำลังทำงานสำคัญอยู่" },
            { "91:1382730561:88528379", "อ้อ เป็นผู้รักษาเหมือนกันนี่ ข้ายินดีสอนทุกอย่างที่จะเป็นประโยชน์กับการเดินทางของเจ้า" },
        },
    },
    [263930] = {
        name = "Peacekeeper",
        lines = {
            { "19:1454775137:823929483", "สวัสดี พลเมือง" },
            { "41:663939535:1317221410", "ให้ข้าช่วยชี้ทางไหม พลเมือง?" },
            { "17:1560454218:1354943701", "วิชาชีพไหนล่ะ?" },
            { "79:1078786319:969323662", "หมอประจำเมืองอยู่ในหอคอยตรงขอบ Valanaar ด้านตะวันออกเฉียงเหนือ" },
            { "34:1716281137:1971836214", "เจ้ากำลังหาอะไรอยู่ พลเมือง?" },
        },
    },
    [252479] = {
        name = "Daeann Steelwind",
        lines = {
            { "40:1568060028:1528601313", "ขอสายลมส่งข่าวดี ให้ช่วยอะไร?" },
            { "70:1681311106:704002457", "ไม่เลว แต่ขอแสดงเคล็ดลับสักหน่อยที่อาจมีประโยชน์" },
            { "64:41659015:1701991556", "ขอให้สายลมทักทายเจ้า สหาย มีอะไรให้ข้าช่วยไหม?" },
            { "94:569651677:64472594", "หวังว่าที่เจ้ามาขัดจังหวะจะมีเหตุผลดี ๆ นะ ข้ากำลังทำงานสำคัญอยู่" },
            { "186:785315577:604685664", "เขาเป็นช่างตีเหล็กที่เก่งกว่าข้ามาก เรื่องนั้นแน่นอน แต่ถ้าเจ้าไปบอกใครว่าข้าพูดอย่างนี้ ข้าจะปฏิเสธ ไปคุยกับ Therum Deepforge เถอะ ถ้ามีใครสอนเจ้าได้มากกว่านี้ ก็ต้องเป็นเขา" },
            { "57:1072220098:1964748388", "อ้อ สวัสดี ดูเหมือนเจ้าจะมีอะไรจะถามข้านะ" },
        },
    },
    [250929] = {
        name = "Malfunctioning Cyclone Construct",
        lines = {
            { "249:1647528085:288597166", "<เมื่อเข้าใกล้สิ่งสร้างไซโคลนมหึมา เจ้าได้ยินเสียงหึ่งแผ่วใต้แผ่นเกราะใหญ่ หากตั้งใจฟัง ดูเหมือนมีคำก่อตัว แต่บิดเบี้ยวเกินฟังออก>" },
        },
    },
    [257944] = {
        name = "Elegael Thornpaw",
        lines = {
            { "255:228212559:822689630", "ไม่อยากเชื่อว่า Al'Aketh จู่โจมเราจนไม่ทันตั้งตัว ก่อนนี้ไม่เคยเป็นศัตรู แต่การซุ่มทำญาติข้าบาดเจ็บมาก ข้าสาบานจะแก้แค้นให้ดรูอิดที่ล้มและเจ็บในรัง จำไว้ พวกมันต้องชดใช้" },
        },
    },
    [1103] = {
        name = "Eldrin",
        lines = {
            { "54:1930949921:1020424799", "ดูออกเลยว่าเสื้อผ้าเจ้าต้องการการดูแลอย่างหนัก" },
            { "218:184971353:324009796", "ข้าเป็นคนธรรมดาที่รู้ตัดเย็บบ้าง แต่เจ้าต้องการความช่วยเหลือเกินข้าให้ได้ ได้ยินว่ามีไนต์เอลฟ์ช่างตัดเย็บเก่งมาก อยู่ใน Magic District ของ Stormwind" },
            { "77:548682660:912618616", "อยากเรียนสักอย่างสองอย่างหรือ? ข้ายินดีช่วยเริ่มต้น!" },
        },
    },
    [1215] = {
        name = "Alchemist Mallory",
        lines = {
            { { "107:168393091:1329484168", "109:631232974:901628791" }, "สวัสดี ข้าอยากจับมือทัก แต่เห็นอยู่ว่ากำลังทำงาน มีอะไรให้ช่วยไหม?" },
            { "68:1811604697:543405861 N 1:46:46", "เริ่มได้ดี แต่ยังต้องเรียนอีกมาก {name}" },
            { "51:1528733228:2056349457 N 144:262203232:605166365", "เจ้าเรียนทุกอย่างที่ข้าสอนได้แล้ว {name} หากอยากศึกษาต่อ คุยกับไนต์เอลฟ์ Lilyssia Nightbreeze ใน Mage Quarter แห่ง Stormwind ได้ยินว่าเป็นครูดี" },
        },
    },
    [1246] = {
        name = "Vosur Brakthel",
        lines = {
            { "206:333914024:789404994", "อย่าให้ตาโตไร้เดียงสาหลอก Tally เชี่ยวชาญจริง ข้าเรียนของใหม่ทุกวัน คิดว่ามาทำอะไรใน Tinker Town? ข้าดูเหมือนวิศวกรหรือ? ใช่ ข้าก็ว่าไม่เหมือน" },
            { { "128:1370686791:1084469838", "129:2133360994:29685918" }, "ออกแรงเข้า คนหนุ่มสาว งานหนักกับความเด็ดเดี่ยวนั่นคือหนทาง! อย่าให้ใครบอกว่าเรียนหนังสืออย่างเดียวก็พอ" },
            { "37:796116066:1904523850 N 128:948289799:666379300", "โธ่ ไม่มีอะไรสอนได้แล้ว {name} คุยกับ Tally Berryfizz ตรงนั้น นางแทบเอื้อมโต๊ะไม่ถึง แต่เริ่มปรุงน้ำยาเมื่อไร ระวังไว้!" },
        },
    },
    [1466] = {
        name = "Gretta Finespindle",
        lines = {
            { "186:697942223:1208926446", "หนังนี้ยังทำงานไม่ได้ หวังว่าทำเครื่องหนังจะไม่ใช้เวลานานอย่างนี้ ต้องมีวิธีลดการรอ มันคงไม่ดีต่อสุขภาพข้าหรอก รู้ไหม?" },
            { "72:272727617:726906805 N 1:33:33", "โอ้ ดีจัง มีอะไรให้ทำระหว่างรอแล้ว! เจ้าช่วยชีวิตข้าแท้ ๆ {name}!" },
            { "191:397824621:618197240", "โธ่ โชคร้ายจริง! ฝีมือข้ายังไม่พอจะช่วยเจ้า เอาเถอะ ไปคุยกับ Fimble Finespindle ตรงกี่ทอผ้านั่น เขาทำงานหนังมานานกว่าข้า" },
        },
    },
    [1632] = {
        name = "Adele Fielder",
        lines = {
            { "193:662475652:78647606", "ตั้งแต่สามีไปแนวหน้า Helene คนนี้เป็นกำลังให้ข้า หัวใจเมตตากับดาบคมช่วยผ่านช่วงยากมากมาย ไม่รู้จะทำอย่างไรหากไม่มีนาง" },
            { "183:1203462886:1004654278", "โธ่ ขอโทษ ไม่มีของใหม่สอน ลองคุย Simon Tanner ใน Old Town แห่ง Stormwind ไหม? มนุษย์กล้ามใหญ่ ผมแดงชวนฝัน" },
            { "55:189395676:648742470", "เป็นอย่างไรบ้าง? ข้าชอบกลิ่นหนัง เจ้าล่ะ?" },
        },
    },
    [1702] = {
        name = "Bronk Guzzlegear",
        lines = {
            { "47:8176098:1676258386", "ปรับนิดหน่อยตรงนี้... อา เรียบร้อย!" },
            { "79:1230143866:1641488870", "อยากเป็นวิศวกรรึ? สาบานต่อ Muradin เลยว่าเจ้ามาถูกที่แล้ว!" },
            { "169:1937885088:985069350", "ถ้าสอนเจ้าได้ ข้าก็สอนให้แล้ว แต่เจ้าต้องไปหาคนที่... เขาเรียกว่าอะไรนะ? หัวดีไง! ไปหา Trixie Quickswitch ที่ Ironforge แล้วบอกนางว่า Bronk ส่งเจ้ามา!" },
        },
    },
    [1703] = {
        name = "Uthrar Threx",
        lines = {
            { "42:1684650133:1305913183", "ยินดีต้อนรับร้านข้า มีอะไรให้ช่วย?" },
            { "117:81154454:1238381974", "เดี๋ยวก่อน ข้าเป็นแค่ผู้ช่วย หากอยากเริ่มเรียนของซับซ้อน คุยกับเฒ่า Stonebrew ตรงนั้น" },
            { "87:1335404199:1037061193", "เยี่ยม! ข้าหวังมีศิษย์ใหม่อยู่ งั้นเริ่มทันทีเลย!" },
        },
    },
    [2132] = {
        name = "Carolai Anise",
        lines = {
            { "212:1071476343:1052215063", "ดีที่เห็นหน้ามิตร Apothecary Johaan ไม่ค่อยคุยเล่นนอกจากต้องการอะไร เขาออกจากหลุมนานเกิน ได้ยินว่าสักวันข้าจะเป็นเช่นนั้น น่าขนลุก ถึงตอนนั้นอาจไม่สนแล้วก็ได้" },
            { "110:1613704824:626617910", "มาเรียนน้ำยาหรือ? มีมากให้สอน ข้าอาจตาย แต่สมองยังไม่หาย ยังนะ" },
            { "198:1380947460:499671823", "ขอบคุณที่อยู่เป็นเพื่อน แต่ยอมรับเถอะ เจ้ามีประสบการณ์น้ำยามากกว่าข้า หากอยากฝึก คุย Doctor Marsh แทน เป็น Forsaken ใน Apothecarium แห่ง Undercity" },
        },
    },
    [2855] = {
        name = "Snang",
        lines = {
            { "52:1631333918:1458069020", "เราใช้หนังสัตว์หลายชนิดในงานสร้างสรรค์" },
            { "182:2083453619:1117677109", "ข้ารู้บ้างแต่ไม่ใช่ผู้เชี่ยวชาญ โชคดี Magar เป็น เขายืนหลังร้าน ลองขอช่วย แต่ระวังอย่าทำอารมณ์เสีย เขาหงุดหงิดได้ง่าย" },
            { "28:1105333554:25598326", "ข้าจะสอนเท่าที่ทำได้" },
        },
    },
    [3069] = {
        name = "Chaw Stronghide",
        lines = {
            { "207:375818364:1923733742", "เนื้อ หนัง กระดูก... พรานดีไม่ปล่อยของเสียเปล่า หนังทุกเศษนำกลับใช้ได้ อาจเสริมเกราะพันธมิตร เราจึงแข็งแกร่งคนเดียว แต่ร่วมกันแล้วไร้ผู้พิชิต" },
            { "200:557315198:1560691036", "เจ้าเติบโตเกินสิ่งข้าสอนได้แล้ว ไปพร้อมพรพระแม่ธรณี หา Tauren ชื่อ Tarn ในร้านตะวันตกเฉียงเหนือของที่ราบสูงกลาง Thunder Bluff ให้ปัญญาเขาชี้นำ" },
            { "104:583375735:657803345 N 100:369975545:1581373246", "เราอยู่แล้วตาย แต่แผ่นดินคงนิรันดร์ ไม่สะเทือนต่อการผ่านไป ดังนั้นแผ่นดินเป็นของเราไม่ได้ {name} เราต่างหากเป็นของมัน เราจึงปกป้อง เพราะหากไร้แผ่นดิน ก็ไม่มีหวังรอด" },
        },
    },
    [3174] = {
        name = "Dwukk",
        lines = {
            { "74:1472011491:631213561", "ข้าได้ยินความเห็นเรื่องนกน้ำอีกคำเดียว เจ้าจะต้องกินผ่านสายยาง" },
        },
    },
    [3365] = {
        name = "Karolek",
        lines = {
            { "150:2125745374:994902506", "ข้ายุ่งอยู่หรือ? หมายความว่าไง? คิดว่ายืนเล่นนิ้วทั้งวันหรือ? ถ้ามาซื้อของ คุยกับ Handor" },
            { "201:87962635:1331003630", "ไม่ได้ของใหม่จากข้าแล้ว เจ้ารู้มากเกิน หากอยากฝึกต่อ คุย Tauren ชื่อ Una ในร้านตะวันตกเฉียงเหนือของที่ราบสูงกลาง Thunder Bluff ฝากทักทายด้วยนะ?" },
            { "115:39039342:2057667787", "ยังศึกษาวิธีข้าไม่ได้จนเรียนพื้นฐานก่อน หากสนใจฝึก คุยกับ Kamari" },
            { "204:778234188:671249924", "ทางวกวนของ Orgrimmar ออกแบบขัดขวางผู้รุกราน นึกออกไหมว่าโนมจิ๋วพวกนั้นจะหลงเร็วแค่ไหน? ฮ่า! ถ้าโชคดี ข้าจะตามเจอแล้วเก็บไว้เป็นสัตว์เลี้ยง" },
        },
    },
    [3523] = {
        name = "Bowen Brisboise",
        lines = {
            { "49:357223290:1567467440", "ยินดีที่รู้จัก มีอะไรให้ช่วยไหม?" },
            { "132:1149546356:1690394874", "ข้ามีความรู้แต่ไม่ใช่ผู้เชี่ยวชาญ รู้ไหมควรคุยใคร? Rhiannon! อยู่ไม่ไกล ถามหานางใน Undercity" },
            { "78:1756002762:1830116037", "อืม... อยากเป็นช่างตัดเย็บหรือ? ได้ มาดูว่ามีคุณสมบัติพอไหม" },
            { "50:2089447985:1826854862", "ยินดีที่รู้จัก มีอะไรให้ช่วยไหม?" },
        },
    },
    [3549] = {
        name = "Shelene Rhobart",
        lines = {
            { "217:541224858:296035499", "ผิวหนัง ผิวหนังอันรุ่งโรจน์ มันรั้งข้างใน... ไว้ข้างใน คงเห็นว่าหนังข้าไม่ค่อยดี คิดดู เมื่อก่อนยังห่วงรูขุมขน ทุกวันนี้แทบไม่มีหนังให้ห่วงแล้ว มุมหนึ่งก็อิสระดี" },
            { "163:1777432323:1251840428", "เจ้าจับทางได้แล้ว ข้าสอนเพิ่มไม่ได้ แต่คุย Arthur Moore ชาว Forsaken ที่ทำงานใน Rogues' Quarter แห่ง Undercity บอกว่าข้าส่งไป" },
            { "136:2004623876:497163578", "ก่อนโรคระบาด ข้าไม่รู้เรื่องหนังเลย ตอนนี้รู้พอสอนคนอื่น ความตายทำให้มีเวลาว่างมาก" },
        },
    },
    [3603] = {
        name = "Cyndra Kindwhisper",
        lines = {
            { "181:496970225:242093283", "ดรูอิดบอกว่าอีกไม่นานธรรมชาติเองจะขับ Horde จาก Kalimdor แต่ความแปดเปื้อนยังแพร่ทั่วแดนเรา แม้บน Teldrassil นี้" },
            { "64:1145442789:1035296041", "ทำดีมาก! ความเข้าใจน้ำยาของเจ้าก้าวหน้าดี" },
            { "180:2047584789:466840259", "น่าเสียดาย ข้าสอนผู้มีประสบการณ์เช่นเจ้าได้น้อย สหาย ไปหาไนต์เอลฟ์ Sylvanna Forestmoon ที่ Craftsmen's Terrace แห่ง Darnassus" },
        },
    },
    [3605] = {
        name = "Nadyia Maneweaver",
        lines = {
            { "40:2132112007:1866833791 N 98:2104276311:258913971", "ต้องเย็บฝีเข็มเล็กลง {name} ของจะหลุดกระบอกลูกธนูกับถุงกระสุนน้อยลง อีกอย่าง ไม่มีใครชอบเสื้อเป็นก้อนนูน" },
            { "40:2132112007:1866833791 N 98:2104276311:258913971", "ต้องเย็บฝีเข็มเล็กลง {name} ของจะหลุดกระบอกลูกธนูกับถุงกระสุนน้อยลง อีกอย่าง ไม่มีใครชอบเสื้อเป็นก้อนนูน" },
            { "21:738231382:1415649755 N 93:1943294319:165581950", "ยินดีต้อนรับบ้านเรา {name} ข้ากับ Radnaal มีให้ไม่มาก แต่ยินดีต้อนรับเท่าที่ทำได้" },
        },
    },
    [3606] = {
        name = "Alanna Raveneye",
        lines = {
            { "73:912668609:1918757984", "ความลับ Elune มีมาก แต่ไม่ใช่แบ่งปันใครก็ได้" },
            { "164:266693754:158382422", "ความรู้ลงมนตร์ของเจ้ายอดเยี่ยมจริง ยังมีอีกมากหากพร้อม คุย Taladan ใน Craftsmen's Terrace แห่ง Darnassus" },
            { "45:1654334987:884858329", "เปิดใจ ผู้พเนจร แล้วเราจะเริ่ม" },
        },
    },
    [4605] = {
        name = "Basil Frye",
        lines = {
            { "71:201133950:1923561479", "หวังว่าสักวันจะตีอาวุธและเกราะจากกระดูกศัตรูได้" },
            { "154:1672694885:44644280", "เจ้าไม่ได้พยายามใช้ค้อนฆ่าทั่ง แต่สร้างอาวุธไว้ฆ่าศัตรู ให้ข้าแสดงว่าทำอะไรผิด" },
            { "101:1398722107:2070830765", "เจ้าเรียนรู้มามาก เกินกว่าที่ข้าจะสอนได้แล้ว ไปหา James Van Brunt เถอะ เขาสอนสิ่งที่ข้าสอนไม่ได้" },
        },
    },
    [5513] = {
        name = "Gelman Stonehand",
        lines = {
            { "163:2138455557:776120744", "ข้ามาจาก Ironforge ช่วยบูรณะที่นี่ หากสอนพวกเจ้าได้มากพอ ก็คงฝากงานไว้แล้วกลับบ้านเองได้" },
            { "74:705158496:496916444", "ว่าไง? ขัดจังหวะข้า ควรมีเหตุผลดีจริง ๆ นะ" },
        },
    },
    [5695] = {
        name = "Vance Undergloom",
        lines = {
            { "72:1785016067:1989195489", "สวัสดี นักเดินทาง! สนใจเจาะปริศนาอาร์เคนไหม? หืม?" },
            { "103:1604805789:1314074936", "แม้ข้าก็มีขีดจำกัด! หากอยากฝึกต่อ ไปคุย Lavinia Crowe ใน Undercity" },
            { "87:1443107968:838705112", "ไม่เลว... ข้าว่าฝึกเจ้าได้อยู่ ได้เลย! มาเริ่ม..." },
        },
    },
    [10278] = {
        name = "Thrag Stonehoof",
        lines = {
            { "73:1266666400:1845145594", "ข้าฟังแล้วฟังอีก แต่ไม่ได้ยินวิญญาณที่ Karn พูดถึง" },
            { "204:2909089:1035307332", "Karn บอกว่าต้องฟังวิญญาณเตาหลอมกับเหล็กกล้า พวกเขาจะชี้ทาง ข้าได้ยินเพียงเสียงก้องในหู เอ้า รับค้อนแล้วมาลองฟังวิญญาณด้วยกัน" },
            { "203:2018607749:512481337", "ข้าว่าวิญญาณชอบเจ้ามากกว่า ยังไม่ได้ยินเสียงเรียก แต่เจ้าดูเรียนบทเรียนได้ดี ไปคุย Karn เขาคงตื่นเต้นพบคนได้ยินเหมือนตน" },
        },
    },
    [11025] = {
        name = "Mukdrak",
        lines = {
            { "68:382775763:278848544", "ข้าชอบสร้างของ แน่นอนว่าชอบระเบิดของมากกว่าอีก!" },
            { "81:1073466262:24076572", "รู้ไหมใครแสดงของดีให้ดูได้จริง? Nogg! ไปหาเขาใน Orgrimmar" },
            { "45:1523560390:954798863", "ข้ารู้วิชาอยู่สองสามอย่าง อยากให้ข้าสอนให้ดูไหม?" },
        },
    },
    [11037] = {
        name = "Jenna Lemkenilli",
        lines = {
            { "38:1597294675:344258287", "สวัสดี! ข้าชื่อ Jenna! แล้วเจ้าล่ะ?" },
            { "211:597405707:739594576", "อ้อ ยังมีให้เรียนอีกเพียบ ข้าอยากสอนทั้งหมดหากทำได้ แต่ยังเรียนอยู่เหมือนกัน ทำไมไม่คุย Trixie Quickswitch ใน Ironforge? นางช่วยศึกษาต่อได้!" },
            { "171:551656132:1696704751", "อยากฝึกหรือ? กับข้า? วิเศษ! สิ่งเดียวที่ดีกว่าประกอบกระสุนกับอุปกรณ์ระเบิด คือแบ่งความรู้ให้คนอื่น เริ่มกัน!" },
        },
    },
    [11047] = {
        name = "Kray",
        lines = {
            { "207:478301570:1085314996", "Bena ทำงานเหมือนถูกสิง ข้าเห็นนางก้มเหนือน้ำยาทั้งกลางวันกลางคืน มักไม่กินไม่นอน รู้ว่าพันธมิตรอันเดดต้องการช่วย แต่เริ่มกลัวนางจะทำตัวเองบาดเจ็บ" },
            { "158:1022160974:985658982", "ตอนเริ่มปรุงน้ำยา ข้าคงทำขวดแตกหลายร้อย แก้วเปราะมากในมืองุ่มง่าม หวังว่าเจ้าจะระวังกว่าข้า" },
            { "193:217182086:936892705", "ความสามารถเรียนรู้ของเจ้าเกินข้าแล้ว ต้องคุย Bena Winterhoof ตรงนั้นเพื่อเรียนต่อ แต่อย่าใช้เวลานางมากนัก นางต้องพัก" },
        },
    },
    [11050] = {
        name = "Trianna",
        lines = {
            { "56:337274190:1427547591", "ไม่มีวิธีใดทำใจให้ปลอดโปร่งได้ยิ่งกว่าทอผ้า" },
            { "132:1322536744:723023627", "ข้ายังศึกษาอยู่ ความรู้เจ้าเกินข้า หากอยากเรียนเพิ่ม ต้องพูดกับ Me'lynn นางจะชี้นำ" },
            { "71:1346286394:1869391051", "เจ้าจะไม่ผิดหวัง นักเดินทาง ตัดเย็บเป็นงานเปี่ยมสุข" },
        },
    },
    [11051] = {
        name = "Vhan",
        lines = {
            { "41:928697214:1171007730", "ไม่มีส่วนใดของสัตว์ที่ล่าเสียเปล่า" },
            { "108:1925997461:1581377963", "เจ้าแสวงหาความรู้สูงกว่า Tepa ได้รับพรความรู้นั้น นางน่าจะยืนใกล้ ๆ..." },
            { "49:630456037:1738229719", "ด้วยพรพระแม่ธรณี เราจะเริ่ม" },
        },
    },
    [11065] = {
        name = "Thonys Pillarstone",
        lines = {
            { "99:122903425:716975165", "มีวิธีเสริมเหล็กกล้านอกเหนือค้อนกับเตา ผู้พเนจรน้อย สนใจเรียนเพิ่มไหม?" },
            { "201:631435640:800603978", "เจ้าเป็นผู้ลงมนตร์ชั้นดีจริง! ถึงเวลาก้าวต่อ ข้าอยากให้คุย Gimble Thistlefuzz ข้างบน เขาแปลกหน่อยแต่จะชี้ทางถูกจากนี้!" },
            { "127:285450909:1590693795", "อา ช่างสงสัยสินะ? เยี่ยม! ดูให้ดี สิ่งนี้อาจช่วยรักษาหนังเจ้าเมื่อเจอเรื่องหนัก!" },
        },
    },
    [11066] = {
        name = "Jhag",
        lines = {
            { "41:664170203:352079544", "Throm-ka! หาอะไรอยู่ คนแปลกหน้า?" },
            { "86:2138198766:68787463", "มาผิดที่ คุยผู้เชี่ยวชาญ Godan ตรงนั้น เจ้าจะเรียนจากเขาได้มากกว่า" },
            { "91:1758840344:218758268", "ตายในศึกมีเกียรติ! แต่สิ่งที่ข้าสอนอาจทำให้ไม่ตายเร็วขนาดนั้น หืม?" },
        },
    },
    [11068] = {
        name = "Betty Quin",
        lines = {
            { "47:2029224191:1069751422", "สวัสดี นักเดินทาง! อะไรพามาถึงประตูบ้านข้า?" },
            { "222:934984358:1660387047", "เกรงว่าไม่มีอะไรสอนคนมีประสบการณ์เช่นเจ้า แต่ยังไม่สุดทาง คุย Lucan Cordell หลังเคาน์เตอร์ เขาจะนำผ่านช่วงถัดไปของเส้นทาง" },
            { "196:1046576118:1901356578", "อืม... ดูสามารถพอ หากอยากเรียนจริง ไม่มีอะไรขวางได้! ข้าจะชี้ก้าวแรกบนเส้นทางที่หวังว่าจะยาวและเติมเต็ม" },
        },
    },
    [2981] = {
        name = "Chief Hawkwind",
        lines = {
            { "6:1136836709:1914036474 C 173:36701772:702245824", "สวัสดี {class} หลายปีข้าเห็น Tauren กระตือรือร้นมากมายอยากพิสูจน์คุณค่าต่อเผ่า อย่าลืมว่าความกระตือรือร้นแทนปัญญากับประสบการณ์ไม่ได้" },
        },
    },
    [263399] = {
        name = "Сэм Сарсапарилла",
        lines = {
            { "22:840239268:505290552", "ว่าไง นักเดินทาง!" },
        },
    },
    [251992] = {
        name = "Fenn Fairweather",
        lines = {
            { "149:47885966:554319406", "ยินดีต้อนรับ Shen'dar Village แหล่งตกปลาดีที่สุดแห่งหนึ่งฝั่งนี้ของแนวเขา หากอยากตกปลา ข้าสอนได้ แลกค่าจ้าง" },
            { "150:770097509:627851662", "ยินดีต้อนรับ Shen'dar Village แหล่งตกปลาดีที่สุดแห่งหนึ่งฝั่งนี้ของแนวเขา หากอยากตกปลา ข้าสอนได้ แลกค่าจ้าง" },
        },
    },
    [251913] = {
        name = "Aedi Thriceforged",
        lines = {
            { "76:1522442084:104348523", "ข้าสอนเหวี่ยงค้อนช่างเหล็กได้ หากพร้อมเรียน" },
            { "70:1681311106:704002457", "ไม่เลว แต่ขอแสดงเคล็ดลับสักหน่อยที่อาจมีประโยชน์" },
        },
    },
    [257022] = {
        name = "Messana Crestwind",
        lines = {
            { "413:151508173:493336867", "เจ้าอาจคิดว่าบนเกาะลอยฟ้าไม่ต้องมีคนขุดแร่เช่นข้า แต่หลายพันปีผ่าน เรายังขุดพบสิ่งน่าสนใจมาก\n\nแทบเหมือนมีพลังล่องหนคอยสร้างแหล่งแร่ใหม่เป็นระยะ เวทมนตร์ก็งี้ใช่ไหม?\n\nอย่างไร หากต้องการฝึกขุดแร่ ข้าคือ Shen'dorei ที่ช่วยเจ้าได้" },
            { "415:1209288810:456984794", "เจ้าอาจคิดว่าบนเกาะลอยฟ้าไม่ต้องมีคนขุดแร่เช่นข้า แต่หลายพันปีผ่าน เรายังขุดพบสิ่งน่าสนใจมาก\n\nแทบเหมือนมีพลังล่องหนคอยสร้างแหล่งแร่ใหม่เป็นระยะ เวทมนตร์ก็งี้ใช่ไหม?\n\nอย่างไร หากต้องการฝึกขุดแร่ ข้าคือ Shen'dorei ที่ช่วยเจ้าได้" },
        },
    },
    [957] = {
        name = "Dane Lindgren",
        lines = {
            { "70:1681311106:704002457", "ไม่เลว แต่ขอแสดงเคล็ดลับสักหน่อยที่อาจมีประโยชน์" },
            { "46:872287002:547758785", "หน้าข้าเหมือนคนมีเวลายืนคุยเล่นหรือไง?" },
            { "186:785315577:604685664", "เขาเป็นช่างตีเหล็กที่เก่งกว่าข้าเยอะ อันนี้แน่นอน แต่ถ้าเจ้าไปบอกใครว่าข้าพูดแบบนี้ ข้าจะปฏิเสธเสีย ไปคุยกับ Therum Deepforge เถอะ ถ้ามีใครสอนเจ้าได้มากกว่านี้ ก็ต้องเป็นเขานี่ละ" },
        },
    },
    [1292] = {
        name = "Maris Granger",
        lines = {
            { "116:1430925938:1346255485", "ไม่ค่อยมีคนถลกหนังมาหาฝึก แต่คงสอนบางอย่างให้ได้หากพร้อม" },
        },
    },
    [257003] = {
        name = "Ishlee Breezewhisper <Skinner>",
        lines = {
            { "116:1430925938:1346255485", "ไม่ค่อยมีคนถลกหนังมาหาฝึก แต่คงสอนบางอย่างให้ได้หากพร้อม" },
            { "40:1568060028:1528601313", "ขอให้สายลมพัดพาข่าวดีมาให้ มีอะไรให้ข้าช่วยไหม?" },
            { "57:1072220098:1964748388", "อ้อ สวัสดี ดูเหมือนเจ้าจะมีอะไรจะถามข้านะ" },
            { "94:569651677:64472594", "หวังว่าที่เจ้ามาขัดจังหวะจะมีเหตุผลดี ๆ นะ ข้ากำลังทำงานสำคัญอยู่" },
            { "64:41659015:1701991556", "ขอให้สายลมทักทายเจ้า สหาย มีอะไรให้ข้าช่วยไหม?" },
        },
    },
    [252388] = {
        name = "Halavuul Cragwind",
        lines = {
            { "413:151508173:493336867", "เจ้าอาจคิดว่าบนเกาะลอยฟ้าไม่ต้องมีคนขุดแร่เช่นข้า แต่หลายพันปีผ่าน เรายังขุดพบสิ่งน่าสนใจมาก\n\nแทบเหมือนมีพลังล่องหนคอยสร้างแหล่งแร่ใหม่เป็นระยะ เวทมนตร์ก็งี้ใช่ไหม?\n\nอย่างไร หากต้องการฝึกขุดแร่ ข้าคือ Shen'dorei ที่ช่วยเจ้าได้" },
            { "415:1209288810:456984794", "เจ้าอาจคิดว่าพอเราอยู่บนเกาะลอยฟ้าก็คงไม่ต้องมีคนขุดแร่อย่างข้า แต่ผ่านมาตั้งหลายพันปี พวกเราก็ยังขุดเจอของน่าสนใจอยู่มาก\n\nราวกับมีพลังที่มองไม่เห็นคอยสร้างแหล่งแร่ใหม่ขึ้นเป็นระยะ ก็คงเป็นเวทมนตร์นั่นแหละ ว่าไหม?\n\nเอาเป็นว่าถ้าเจ้าอยากฝึกขุดแร่ ข้านี่แหละคือ shen'dorei ที่เจ้าตามหา" },
        },
    },
    [3442] = {
        name = "Sputtervalve",
        lines = {
            { "97:298949460:381378314", "งานเยอะเหลือเกิน งานเยอะเหลือเกิน! สหภาพกำหนดเส้นตายมาแล้ว และไม่ใช่เส้นตายที่เจ้าจะอยากพลาดเสียด้วย!" },
            { "156:1065000375:1850308388 N 1:33:33", "ผู้อำนวยการ Riddlevox ให้ข้าดูแลโครงการพัฒนาเครื่องตัดไม้ของสหภาพ ทำงานได้ไม่กี่เดือน ข้าก็เดือดร้อนเสียแล้ว! ข้าต้องการความช่วยเหลือจากเจ้านะ {name}!" },
            { "369:968101305:676438603", "ดูสิ เครื่องตัดไม้รุ่นใหม่ของ Venture Company ดีกว่ารุ่นล่าสุดของข้า ตั้งแต่มือที่ถอดเปลี่ยนได้ไปจนถึงด้ามควบคุม! หัวหน้ากำหนดเส้นตายให้ข้าไว้ค่อนข้างเข้มงวด แต่ข้ากับลูกทีมยังคิดอะไรไม่ออกเลย\n\nทำอย่างไรก็ไม่สำเร็จ เราจึงตัดสินใจ \"ยืม\" เครื่องต้นแบบของพวกมันมาสักเครื่อง ข้าส่ง Wizzlecrank ไปขโมยมาที่ Sludge Fen แต่เขายังไม่กลับมาเลย!" },
            { "98:1640109775:1678416285 N 99:471311553:721364661", "น่าสนใจ น่าสนใจ... ข้ารู้จักดรูอิดคนหนึ่งที่อยู่บนยอดเขาเหนือ Wailing Caverns นะ {name} นางอาจบอกอะไรเจ้าเพิ่มเติมเกี่ยวกับเศษชิ้นส่วนที่เจ้าพบนี้ได้\n\nเอาละ ข้าต้องกลับไปทำงานแล้ว!" },
            { "156:1065000375:1850308388 N 1:33:33", "ผู้อำนวยการ Riddlevox ให้ข้าดูแลโครงการพัฒนาเครื่องตัดไม้ของสหภาพ ทำงานได้ไม่กี่เดือน ข้าก็เดือดร้อนเสียแล้ว! ข้าต้องการความช่วยเหลือจากเจ้านะ {name}!" },
        },
    },
    [16418] = {
        name = "Mupsi Shacklefridd",
        lines = {
            { "37:2029430076:911343480 N 1:33:33", "อย่าคิดก่อเรื่องเชียวนะ {name}!" },
        },
    },
    [9037] = {
        name = "Gloom'rel",
        lines = {
            { "98:1640109775:1678416285 N 99:471311553:721364661", "น่าสนใจ น่าสนใจ... ข้ารู้จักดรูอิดคนหนึ่งที่อยู่บนยอดเขาเหนือ Wailing Caverns นะ {name} นางอาจบอกอะไรเจ้าเพิ่มเติมเกี่ยวกับเศษชิ้นส่วนที่เจ้าพบนี้ได้\n\nเอาละ ข้าต้องกลับไปทำงานแล้ว!" },
            { "91:1377778682:231780221", "ข้าถูกพรากจากสัมผัสของหินไปตลอดกาล ข้าจะไม่มีวันได้สัมผัสความงดงามของเหล็กที่ตีขึ้นรูปอีก..." },
            { "72:1739944740:276018194", "เจ้าจิตใจแน่วแน่และมีเจตนาชัดเจน\n\nบางทีเจ้าอาจคู่ควร..." },
            { "74:1846411168:158023220 R 45:862289715:1289287599", "เจ้าอยากเรียนวิชาเก่าแก่หรือ? อยากหลอม Dark Iron หรือ?\n\nทำให้ข้าพอใจสิ {race} นำเครื่องสังเวยมาให้ดู แล้วข้าจะพิจารณา!" },
            { "86:531402623:792871397", "เจ้าแสดงความตั้งใจให้ข้าเห็น และจ่ายด้วยอัญมณีล้ำค่าแล้ว ข้าจะสอนเจ้า..." },
        },
    },
    [2995] = {
        name = "Tal",
        lines = {
            { "109:1009244946:621699825", "เมื่อนั่งบนหลังวินด์ไรเดอร์ เจ้าจะรู้ว่าชื่อเสียงเรื่องความแข็งแกร่งและรวดเร็วของมันไม่ได้มาเปล่า ๆ" },
        },
    },
    [3310] = {
        name = "Doras",
        lines = {
            { "86:565628133:16667728", "หากยังไม่เคยมองโลกเบื้องล่างจากหลังวินด์ไรเดอร์ ก็เหมือนเจ้ายังใช้ชีวิตไม่เต็มที่" },
        },
    },
    [3341] = {
        name = "Gann Stonespire",
        lines = {
            { "113:1642948704:221201611 N 1:63:63", "ข้าเดินถนนนี้เพียงลำพัง แสวงหาหนทางปกป้องเกียรติและกำจัดศัตรูจากแผ่นดิน\n\nมีอะไรให้ข้าช่วย {name}?" },
            { "316:915861869:1037687137", "ใช่ ข้าเห็นชาแมนที่เจ้าตามหา ครั้งสุดท้ายที่เห็น นางอยู่ทางตะวันตกจากที่นี่ ซ่อนตัวบนเนินเหนือเผ่า Razormane ถ้าเจ้าไหวพริบดี ก็คงหาทางขึ้นกระท่อมบนเนินของนางได้ ทางนั้นอยู่ขึ้นเหนือจากที่นี่ไม่ไกล น่าจะไปถึงได้โดยไม่ต้องฝ่าควิลบอร์เข้าไป" },
        },
    },
    [3432] = {
        name = "Mankrik",
        lines = {
            { "54:754380991:891501071 C 272:2122153061:1668925558", "ข้ามาขอความช่วยเหลือที่ Crossroads จากทางใต้ {class} แต่เจอแต่คนขี้ขลาดหันหลังให้ แม้แต่ Thork ผู้ยิ่งใหญ่ก็ยังดูหมิ่น เขาเป็นผู้นำที่ดี แต่การปัดคำขอของข้าทิ้งทำให้โกรธยิ่งขึ้น\n\nเขาว่าความโกรธทำให้ข้าหุนหัน บดบังวิจารณญาณ แต่ข้าจะไม่พักจนกว่าจะได้ล้างแค้น!" },
            { "13:775239909:370709306 N 237:1157409859:932443591", "ขอบใจ {name} ความทุ่มเทช่วยตามคำขอทำให้วิญญาณภรรยาผู้จากไปของข้าสงบลง เรื่องนี้ข้าคงไม่มีวันตอบแทนได้พอ\n\nข้าบอกไม่ได้ว่าความเกลียดชังควิลบอร์จะสิ้นสุดหรือไม่ แต่ตอนนี้มันสงบแล้ว\n\nบัดนี้ข้าต้องเริ่มสร้างชีวิตใหม่" },
        },
    },
    [3433] = {
        name = "Tatternack Steelforge",
        lines = {
            { "354:254073126:1083435579", "จอมทัพสั่งให้ข้าศึกษาอาวุธและเกราะทุกชนิด เขาส่งข้ามายังศูนย์กลางวัฒนธรรมทอเรนกับออร์คใน Barrens เพื่อพบนักเดินทางให้มากที่สุด และเรียนรู้วัฒนธรรมต่าง ๆ ของ Barrens\n\nเขาเห็นว่าแม้แต่วัฒนธรรมน่าสมเพชที่สุดก็มีสิ่งให้เรียนรู้... อย่างควิลบอร์หรือเซนทอร์" },
            { "126:1654984029:481137495 R 225:923765735:224708139", "จอมทัพสั่งให้ข้าศึกษาอาวุธและเกราะทุกชนิด เขาส่งข้ามายังศูนย์กลางวัฒนธรรมทอเรนกับ{race}ใน Barrens เพื่อพบนักเดินทางให้มากที่สุด และเรียนรู้วัฒนธรรมต่าง ๆ ของ Barrens\n\nเขาเห็นว่าแม้แต่วัฒนธรรมน่าสมเพชที่สุดก็มีสิ่งให้เรียนรู้... อย่างควิลบอร์หรือเซนทอร์" },
        },
    },
    [3483] = {
        name = "Jahan Hawkwing",
        lines = {
            { "109:39311788:572673170", "Barrens ซึ่งมีแดดร้อนและผู้อาศัยเป็นศัตรู คือสถานที่เหมาะที่สุดสำหรับทดสอบพลังและความทรหดของเจ้า" },
        },
    },
    [3489] = {
        name = "Zargh",
        lines = {
            { "110:1729538908:108467112", "ดูเนื้อของข้าสิ สหาย เจ้าคงไม่อยากออกไปใน Barrens โดยไม่มีเสบียงดี ๆ ตุนไว้หรอก" },
        },
    },
    [3615] = {
        name = "Devrak",
        lines = {
            { "70:1023492235:1444991952", "วินด์ไรเดอร์ของข้าฝึกให้บินได้รวดเร็วผ่านอากาศร้อนของ Barrens" },
        },
    },
    [8359] = {
        name = "Ahanu",
        lines = {
            { "87:3644163:237273240", "สวัสดี หากมาหาเครื่องหนัง เจ้าจะพบว่าสินค้าข้าทำมาอย่างประณีต" },
        },
    },
    [3338] = {
        name = "Sergra Darkthorn",
        lines = {
            { "149:274024670:890115506", "ผืนดิน ผืนน้ำ และท้องฟ้าล้วนเป็นหนึ่งเดียว ดวงตาเจ้าต่างหากที่หลอกให้เห็นว่าแยกจากกัน พระแม่ธรณีคือทุกสิ่งเหล่านั้น และยิ่งกว่านั้น" },
        },
    },
    [3430] = {
        name = "Mangletooth",
        lines = {
            { "5:1457241651:692239714 R 419:885251831:790862562", "เจ้า! {race}! มานี่ <พ่นลมทางจมูก>\n\nเวลาเหลือน้อย จุดจบข้า <พ่นลมทางจมูก> ใกล้แล้ว Mangletooth จะชนะ เจ้าคอยดู <พ่นลมทางจมูก>\n\nถึงข้าถูกจับก็ยังช่วย <พ่นลมทางจมูก> เผ่าพ้องได้ เผ่า Razormane แข็งแกร่งกว่า Bristleback!\n\nHorde อยากรู้ว่าใครนำการปล้นเผ่าพ้องของมัน เจ้า <พ่นลมทางจมูก> จะช่วย Mangletooth แลกกับข้อมูลที่ข้ารู้คนเดียว Mangletooth ช่วยเจ้าได้! <พ่นลมทางจมูก> แต่เจ้าต้องช่วย Mangletooth" },
            { "67:653281112:503400410 R 153:1603750215:813846073", "เจ้าช่วย <พ่นลมทางจมูก> Mangletooth มากเกินกว่าที่ฝันไว้ {race}\n\nขอบใจ\n\nตราบใดที่ข้ายังถูกขังที่นี่ เจ้านำเศษโลหิตจากควิลบอร์ Bristleback มาให้ได้ แล้วข้าจะอวยพรด้วยพลัง Agamaggan" },
            { "71:225029939:1045923620 R 332:166309394:1106326386", "ความเกลียดชังของข้ารุนแรง <พ่นลมทางจมูก> แต่ถึงเวลาเล่าเรื่องให้เจ้าฟังแล้ว {race}\n\nนานมาแล้ว เกิดศึกระหว่างเทพ Agamaggan เทพหมูป่าผู้ยิ่งใหญ่ของเรา พ่ายแพ้ในสงครามแห่งบรรพกาลแล้วตกลงสู่ผืนดิน เลือดหลั่งราวฝน กระดูกฉีกกระจัดกระจาย <พ่นลมทางจมูก>\n\nหนามมหึมางอกจากพื้นตรงที่เลือดเขาสัมผัสดิน และกะโหลกเขาประดับถ้ำแห่งหนึ่งทางใต้" },
            { "411:1440666807:1282879155", "ความเกลียดชังของข้ารุนแรง <พ่นลมทางจมูก> แต่ถึงเวลาเล่าเรื่องให้เจ้าฟังแล้ว สกายบอร์น\n\nนานมาแล้ว เกิดศึกระหว่างเทพ Agamaggan เทพหมูป่าผู้ยิ่งใหญ่ของเรา พ่ายแพ้ในสงครามแห่งบรรพกาลแล้วตกลงสู่ผืนดิน เลือดหลั่งราวฝน กระดูกฉีกกระจัดกระจาย <พ่นลมทางจมูก>\n\nหนามมหึมางอกจากพื้นตรงที่เลือดเขาสัมผัสดิน และกะโหลกเขาประดับถ้ำแห่งหนึ่งทางใต้" },
        },
    },
    [3682] = {
        name = "Vrang Wildgore",
        lines = {
            { "92:515447089:1427536900", "ต้องการอาวุธหรือ นักเดินทาง? ข้ารับรองว่าเจ้าหาคมดาบดีกว่านี้ที่ไหนไม่ได้อีกแล้ว" },
        },
    },
    [256388] = {
        name = "Jornah",
        lines = {
            { "656:2104159871:553273446", "ใช่! เอ่อ ก็ประมาณนั้น\n\nทองคือเงินตราสากลที่แท้จริง แต่พวกเรามีระบบค้าขายกันเองชื่อ Merchant's Favor มันแยกการค้าออกจากมูลค่าทองและเงินที่ผันผวนตลอดเวลา เพื่อให้สมาชิกองค์กรค้าขายกันอย่างเป็นธรรมและเท่าเทียม มันแลกกลับเป็นทองไม่ได้ เว้นแต่เจ้าจะทำอะไรลับลมคมใน ข้าว่านะ\n\nเรายังใช้ทองกับสิ่งจำเป็นทั่วไป เช่นวัตถุดิบสำหรับงานฝีมือพื้นฐาน แต่นอกนั้นพึ่ง Merchant's Favor สำหรับการค้าภายใน\n\nหากช่วยตามลังสินค้าที่ตกค้างกลับคืน และช่วยทำตามใบสั่งงานช่างฝีมือให้รวดเร็ว เจ้าจะได้รับมากมาย!" },
            { "24:256509429:1075474147 N 299:822821121:1385980762", "สวัสดี ยินดีที่พบ {name}! เจ้ามาได้เหมาะเวลา พวกเราบริษัท Durotar Supply and Logistics ต้องการผู้รับสัญญารายใหม่เสมอ\n\nหากเจ้ามีพรสวรรค์ด้านรวบรวมวัสดุที่มีประโยชน์ หรือฝีมือสร้างของจากศูนย์ ที่นี่มีที่ให้เจ้า\n\nหากสงสัยอะไร บอกข้าได้เลย" },
            { "67:1286013632:1183867202 N 604:1155286584:1878742700", "ดีใจที่เจ้าถาม! เราทำมากกว่างานส่งของมากนัก {name} เราจ้างงานและทำสัญญากับช่างฝีมือหลากหลายสาขา คอยฟังหาโอกาสใหม่ให้พวกเขามีงานและสินค้าหมุนเวียน เราไม่อาจทำนายความต้องการที่เพิ่งเกิดของลูกค้าทุกคนได้ จึงต้องรอคำสั่งผลิตส่งเข้ามา\n\nคงนึกออกว่ากระบวนการนี้... ไม่ได้ผลดีอย่างที่หวัง เราสนับสนุนให้ช่างฝีมือตอบสนองความต้องการเหล่านี้และส่งสินค้าตรงถึงลูกค้า ไม่ว่าพวกเขาอยู่ที่ใด ไม่ต้องห่วง เจ้าจะได้ค่าตอบแทนเป็นธรรมที่ลำบาก และได้รับความนับถือในองค์กรเรา" },
            { "550:1386211962:478674610", "ช่วงนี้คำสั่งซื้อที่สูญหายเพิ่มขึ้นมาก เราพยายามให้การส่งทุกครั้งมีประสิทธิภาพและปลอดภัย แต่เมื่อโจร สัตว์เกเร และ Alliance บัดซบเพิ่มขึ้น ย่อมมีการส่งของที่ไม่เป็นไปตามแผน\n\nหากพบสินค้าพวกนี้ ลองดูฉลากว่าควรบรรจุอะไร เจ้าไม่จำเป็นต้องแก้ความผิดพลาดของเรา แต่ถ้าจัดสินค้าให้ครบ เจ้าจะได้รับรางวัลตอบแทน\n\nDokimi ข้างเกวียนจัดการเรื่องขนส่งกับค่าตอบแทนเจ้าได้ ที่เหลือเราจะดูแลเอง" },
            { "67:1286013632:1183867202 N 604:692182945:615639042", "ดีใจที่เจ้าถามนะ {name} เราทำมากกว่าแค่ส่งของ เราจ้างและว่าจ้างช่างฝีมือหลายแขนง คอยฟังข่าวหางานใหม่ให้ช่างมีงานทำและมีสินค้าออกมาเรื่อย ๆ เราเดาไม่ได้ว่าลูกค้าจะต้องการอะไรขึ้นมา จึงต้องรอให้เขาส่งใบสั่งงานมาหาเรา\n\nอย่างที่เจ้าคงนึกออก วิธีนี้... ได้ผลน้อยกว่าที่เราหวัง เราจึงชวนช่างทุกคนรับงานเหล่านี้แล้วส่งของให้ลูกค้าเอง ไม่ว่าลูกค้าจะอยู่ที่ไหน วางใจเถอะ เจ้าจะได้ค่าตอบแทนสมกับที่ลงแรง และได้ความนับถือจากองค์กรของเรา" },
        },
    },
    [261366] = {
        name = "Walton",
        lines = {
            { "18:1426304020:918380723 R 1:63:63", "ต้องการอะไร {race}?" },
            { "27:139262438:1035912153", "ต้องการอะไร สกายบอร์น?" },
        },
    },
    [3052] = {
        name = "Skorn Whitecloud",
        lines = {
            { "37:996749268:1995614561", "เจ้าฆ่า Ghost Howl แล้ว เก่งจริง!" },
            { "142:35352838:1111256819", "เข้ามาใกล้หน่อย ผู้เยาว์ สมัยก่อนข้าได้ยินแม้แต่เสียงหัวใจเหยื่อเต้นระรัว แต่ตอนนี้เจ้าต้องพูดดังหน่อยหากอยากให้ข้าได้ยิน" },
            { "490:254289955:465819481", "ข้าวิ่งข้ามทุ่งเหล่านี้มาหลายต่อหลายฤดูกาล ล่าสัตว์ร้ายยิ่งใหญ่มามาก และไม่เคยพ่ายแพ้... จนกระทั่งเผชิญ Ghost Howl\n\nนานมาแล้ว หมาป่ามหึมาตัวนี้เป็นพันธมิตรของทอเรน ต่อสู้กับ Burning Legion อย่างกล้าหาญ แต่ถูกปีศาจทำร้ายสาหัส แผลฉีกในเนื้อไม่เคยหาย ในที่สุด... มันทำให้ Ghost Howl เสียสติ\n\nบัดนี้มันเดินทุรนทุรายทั่วทุ่ง แสวงหาจุดจบของความเจ็บปวด ข้าละอายที่ตอนต่อสู้กัน ข้าไม่มีกำลังพอจะฆ่ามัน..." },
        },
    },
    [267287] = {
        name = "Sylassa Moonglow",
        lines = {
            { "7:989913233:66981971 N 299:380939559:1830266871", "สวัสดี {name}! เคยคิดจะเรียนวิชาชีพบ้างไหม?\n\nข้ายินดีตอบข้อสงสัย หรือแนะนำให้เจ้ารู้จักครูฝึกในพื้นที่\n\nถ้ารู้สึกว่าข้อมูลมากจนสับสน ก็ไม่เป็นไร! เจ้ากลับมาที่นี่หรือไปหาครูฝึกในเมืองหลวง เพื่อเริ่มเส้นทางงานฝีมือเมื่อไรก็ได้" },
            { "54:567209770:2025214256", "เลือกได้ดี ข้าทำเครื่องหมายจุดนั้นบนแผนที่ให้แล้ว" },
            { "224:1537358019:1280525218", "ได้แน่นอน! อยากให้ข้าแนะนำครูฝึกวิชาชีพไหน?\n\nข้าจะทำเครื่องหมายตำแหน่งครูฝึกในพื้นที่ที่เจ้าเลือกบนแผนที่ จำไว้ว่าเจ้าไปหาครูฝึกในเมืองหลวงเพื่อเรียนให้ลึกซึ้งยิ่งขึ้นได้" },
            { "668:1255417751:2093788076", "วิชาชีพแบ่งเป็นสองกลุ่มหลัก คือวิชาชีพหลักและวิชาชีพรอง\n\nเจ้าเรียนวิชาชีพหลักพร้อมกันได้สูงสุดสองอย่าง และเลิกวิชาชีพหลักเมื่อไรก็ได้ แต่ความรู้ที่สะสมไว้จะสูญหาย หากกลับมาเรียนวิชาเดิม ต้องเริ่มฝึกจากพื้นฐานและหาสูตรที่เคยได้มา เพื่อทำความคุ้นเคยกับมันใหม่\n\nวิชาชีพรองไม่มีข้อจำกัดเช่นนั้น เป็นทักษะสำหรับพึ่งพาตัวเองและความจำเป็นพื้นฐานในการอยู่รอด จะเรียนอย่างใดอย่างหนึ่งหรือทั้งหมดก็ได้ แต่อาจมีโอกาสทำกำไรน้อยกว่า" },
            { "635:1799873657:1325596191", "ดีใจที่เจ้าถาม!\n\nวิชาชีพคือทักษะด้านการผลิต การเก็บทรัพยากร และการเอาตัวรอด มีให้เลือกหลายอย่าง แต่ละวิชามีประโยชน์และช่องทางทำรายได้ต่างกัน ไม่ว่าเจ้าจะอยากหาเงิน เติมของใช้ให้คลังกิลด์ หรือแค่ภูมิใจที่ได้สวมอุปกรณ์ที่ทำด้วยมือตัวเอง ก็มีวิชาชีพที่เหมาะกับเจ้า\n\nเจ้าเรียนสูตรผลิตได้จากอาจารย์ฝึกวิชาชีพอย่างคนแถวนี้ และจากแหล่งอื่น ๆ ทั่ว Azeroth พอเรียนแล้ว เจ้าจะทำของชิ้นนั้นกี่ชิ้นก็ได้ ขอแค่หาวัสดุที่ต้องใช้ได้ครบ" },
        },
    },
    [267333] = {
        name = "Terunne Bearshaper",
        lines = {
            { "85:1938448218:1122547814", "อยากเรียนวิธีเก็บหนังจากสัตว์ที่ตายแล้วหรือ? หรืออยากได้เครื่องมือใหม่?" },
        },
    },
    [267336] = {
        name = "Brighid Stormflayer",
        lines = {
            { "85:1938448218:1122547814", "อยากเรียนวิธีเก็บหนังจากสัตว์ที่ตายแล้วหรือ? หรืออยากได้เครื่องมือใหม่?" },
        },
    },
    [267323] = {
        name = "Clarence Gillian",
        lines = {
            { "7:989913233:66981971 N 299:380939559:1830266871", "สวัสดี {name}! เคยคิดจะเรียนวิชาชีพบ้างไหม?\n\nข้ายินดีตอบข้อสงสัย หรือแนะนำให้เจ้ารู้จักครูฝึกในพื้นที่\n\nถ้ารู้สึกว่าข้อมูลมากจนสับสน ก็ไม่เป็นไร! เจ้ากลับมาที่นี่หรือไปหาครูฝึกในเมืองหลวง เพื่อเริ่มเส้นทางงานฝีมือเมื่อไรก็ได้" },
            { "635:1799873657:1325596191", "ดีใจที่เจ้าถาม!\n\nวิชาชีพคือทักษะการสร้างของ การเก็บรวบรวมวัตถุดิบ และการเอาตัวรอดทั่วไป มีให้เลือกหลายวิชา แต่ละวิชามีประโยชน์และช่องทางหารายได้ต่างกัน ไม่ว่าเจ้าอยากมั่งมี อยากหาของที่มีประโยชน์มาเติมคลังกิลด์ หรือแค่พอใจที่ได้สวมอุปกรณ์ที่ทำด้วยมือตัวเอง ก็มีวิชาที่เหมาะกับเจ้า\n\nเจ้าหัดทำของตามสูตรได้จากครูฝึกอย่างที่อยู่แถวนี้ และจากแหล่งอื่นอีกมากทั่ว Azeroth เมื่อเรียนสูตรแล้ว เจ้าจะทำของชิ้นนั้นกี่ชิ้นก็ได้ ตราบใดที่หาวัตถุดิบที่จำเป็นมาได้" },
            { "671:908279100:1639923486", "วิชาชีพแบ่งเป็นสองประเภท คือวิชาชีพหลักกับวิชาชีพรอง\n\nเจ้าเรียนวิชาชีพหลักพร้อมกันได้สูงสุดสองวิชา จะเลิกวิชาไหนเมื่อไรก็ได้ แต่ความรู้ที่สะสมมาในวิชานั้นจะหายไป หากกลับมาเรียนวิชาเดิม เจ้าต้องเริ่มจากพื้นฐานและไปหาสูตรที่เคยเรียนมาทบทวนอีกครั้ง\n\nวิชาชีพรองไม่มีข้อจำกัดนี้ ส่วนใหญ่ช่วยให้เจ้าดูแลความต้องการพื้นฐานและเอาตัวรอดได้ด้วยตัวเอง เจ้าเลือกเรียนได้ตามใจ จะเรียนทั้งหมดก็ได้ แต่อาจหาโอกาสทำกำไรได้น้อยกว่า" },
            { "224:1537358019:1280525218", "ได้สิ อยากให้ข้าพาไปหาครูฝึกวิชาไหนล่ะ?\n\nข้าจะทำเครื่องหมายบนแผนที่ให้ว่าครูฝึกวิชาที่เจ้าเลือกอยู่ตรงไหนในแถบนี้ หากอยากเรียนให้ลึกขึ้น ก็ไปหาครูฝึกตามเมืองหลวงได้" },
            { "54:567209770:2025214256", "เลือกได้ดี ข้าทำเครื่องหมายจุดนั้นบนแผนที่ให้แล้ว" },
        },
    },
    [247227] = {
        name = "Riley Peltskinner",
        lines = {
            { "85:1938448218:1122547814", "อยากเรียนวิธีเก็บหนังจากสัตว์ที่ตายแล้วหรือ? หรืออยากได้เครื่องมือใหม่?" },
        },
    },
    [2082] = {
        name = "Gilshalan Windwalker",
        lines = {
            { "144:1797790058:1478695955", "พืชและสัตว์แห่ง Shadowglen เป็นเครื่องยืนยันความสามารถของเราในการทำงานร่วมกับธรรมชาติ เป็นเกียรติที่ได้เห็นความสำเร็จอันยิ่งใหญ่ของเรา" },
        },
    },
    [16113] = {
        name = "Father Inigo Montoy",
        lines = {
            { "103:149417150:326859377", "Lich King พยายามแสดงอำนาจให้โลกเรารับรู้ เราต้องไม่ยอมให้เกิดขึ้น" },
            { "312:910362919:2116127948", "ศรัทธา... บางคนสูญเสีย บางคนค้นพบ มันทำลายไม่ได้ และสร้างขึ้นไม่ได้\n\nหรือเจ้าหมายถึงอาภรณ์แห่งศรัทธา? เกราะที่นักบวชและนักรบผู้เคร่งศรัทธาที่สุดของเราสวมเข้าสู้ Scourge ในสงครามครั้งก่อน\n\nใช่ ส่วนใหญ่สูญหายแล้ว... ถูกเหล่าปีศาจแห่ง Naxxramas ขโมยไป" },
        },
    },
    [16115] = {
        name = "Commander Eligor Dawnbringer",
        lines = {
            { "17:1550163569:1281171417 R 311:1130937260:1541203221", "ระวังตัวด้วย {race} พวกเรา Brotherhood of the Light ไม่ผ่อนปรนเท่าพี่น้องของเรา เมื่อต้องลงทัณฑ์ผู้ที่คิดทำร้ายโลก\n\nวิบัติแก่ผู้ที่ทำให้ Korfax โกรธ\n\nถ้าไม่มีธุระกับข้าหรือสมาชิกภราดรภาพคนอื่น ก็ออกไปเถอะ เราจะได้ประชุมต่อ" },
            { "339:884415571:1639278475", "เหล่าอัศวินผู้เคร่งศรัทธาที่สุดเคยสวมเกราะ Redemption เป็นเกราะคู่ควรแม้แต่ Lightbringer เอง!\n\nหลายพันคนล้มลงในสงครามครั้งก่อน อาภรณ์ถูกถอดจากศพและนำไปยังป้อมปราการน่าสะพรึงแห่ง Naxxramas\n\nว่ากันว่าเดธไนต์แห่ง Naxxramas ทำเกราะแผ่น Redemption ให้มัวหมอง เพื่อนำมาใช้เอง\n\nช่างน่าเศร้า..." },
        },
    },
    [16134] = {
        name = "Rimblat Earthshatter",
        lines = {
            { "92:1203131596:652146777", "ข้าคาด...\n\n<Rimblat ไอ>\n\nขออภัย นิสัยเก่าน่ะ ข้าคือ Rimblat แห่ง Earthen Ring" },
            { "300:1914538360:947187491", "ในสงครามครั้งก่อน ทอเรนเข้าสู้รบ เหล่าชาแมนถูกส่งไปปกป้องโลกจากการรุกรานของ Scourge ส่วนใหญ่เสียชีวิต อีกหลายคนถูกฉีกแยกร่าง ชิ้นส่วนร่างกายถูกใช้ในการทดลองชั่วร้ายในป้อมต้องสาปนั้น ข้าโศกเศร้าต่อการจากไป แต่หัวใจพองด้วยความภูมิใจในความกล้าของพวกเขา" },
            { "183:249429782:1625086788", "ตอนนั้นข้าเป็นทอเรนหนุ่ม เพิ่งเข้าสู่วัยรุ่น แต่รู้ว่าผู้ที่กล้าฝ่าศึกเพื่ออิสรภาพของเรา ได้รับการปกป้องอย่างดีด้วยอาภรณ์ที่ใช้ชื่อเดียวกับข้า" },
            { "195:850462156:153390319", "นาม Earthshatter อยู่กับตระกูลข้ามาหลายร้อยปี เช่นเดียวกับบิดาและปู่ก่อนหน้า ข้าก็สืบทอดสิทธิ์สร้างอาภรณ์ที่ใช้ชื่อเดียวกับข้า" },
        },
    },
    [16376] = {
        name = "Craftsman Wilhelm",
        lines = {
            { "171:731660719:784735050", "ปรมาจารย์ช่างฝีมือ Omarion หายตัวไปคืนหนึ่ง เหมือนเสียงผายลมที่ปลิวหาย... ฟู่! หายไปแล้ว! ช่างเถอะ ตอนนี้เหลือข้าคนเดียวที่ทำของให้พวกทหารแนวหน้า" },
        },
    },
    [262492] = {
        name = "Rimblat Earthshatter",
        lines = {
            { "92:1203131596:652146777", "ข้าคาด...\n\n<Rimblat ไอ>\n\nขออภัย นิสัยเก่าน่ะ ข้าคือ Rimblat แห่ง Earthen Ring" },
        },
    },
    [15378] = {
        name = "Merithra of the Dream",
        lines = {
            { "72:1155173240:1047015339", "วีรชนแห่งเหล่าวงศ์มังกรหรือ? ต้องขับไล่คธูนออกไป! เราช่วยเจ้าได้ มรรตัย!" },
            { "195:745469248:1635733513", "ทุกคนจะรู้ถึงสิ่งที่เกิดขึ้นที่นี่ ในวิหารต้องสาปแห่งนี้ วีรชน มันจะถูกบันทึกในตำราประวัติศาสตร์ และเล่าขานเป็นตำนานตั้งแต่อาเซรอธไปจนถึงสุดขอบเนเธอร์!" },
        },
    },
    [15379] = {
        name = "Caelestrasz",
        lines = {
            { "175:1385740323:923661584", "ต่อให้เจ้าหาทางปลดปล่อยเราได้โดยไม่ปราบคธูน เราก็จะทุ่มพลังทั้งหมดเพื่อขับไล่อสูรนั้นกลับไปยังขุมนรกที่มันจากมา ไม่ว่าต้องแลกด้วยสิ่งใดก็ตาม" },
            { "98:513702541:30486795", "อิสรภาพของเราคงไร้ความหมาย หากคธูนยังมีชีวิตอยู่ เจ้าเป็นยอดนักรบตามคำพยากรณ์อย่างแท้จริง" },
        },
    },
    [15380] = {
        name = "Arygos",
        lines = {
            { "195:1758051145:1832106344", "ข้าได้ประจักษ์ปาฏิหาริย์ที่ยืนอยู่ตรงหน้า! ตลอดพันปีที่ถูกกักขัง ข้าไม่เคยเห็นสิ่งมีชีวิตที่ยังมีชีวิตอยู่แม้แต่ตัวเดียวเข้ามาในห้องเหล่านี้ นอกจากคิราจิกับซิลิธิดอันชั่วช้า" },
            { "46:1731100555:805244182 N 1:46:46", "โลกเป็นหนี้บุญคุณเจ้าและพันธมิตรของเจ้า {name}" },
        },
    },
    [15502] = {
        name = "Andorgos",
        lines = {
            { "75:54934792:211436234", "ก้าวอย่างระมัดระวัง มรรตัย เจ้ากำลังย่างเหยียบสถานที่ซึ่งผู้ทรงพลังยิ่งกว่าเจ้าต้องพบจุดจบ" },
            { "182:757670004:1454805134", "เมื่อจักรพรรดิทั้งสองถูกสังหาร เวทคุ้มกันที่ขัดขวางการเคลื่อนย้ายภายในวิหารก็อ่อนกำลังลงมาก หากเจ้าต้องการ ข้าสามารถย้ายเจ้าไปยังที่พำนักของจักรพรรดิได้" },
            { "103:1063245270:1706689434", "เมื่ออูโรถูกสังหาร เส้นทางสู่ห้องสุดท้ายก็เปิดแล้ว หากเจ้าต้องการ ข้าสามารถส่งเจ้าไปที่นั่นได้" },
        },
    },
    [15503] = {
        name = "Kandrostrasz",
        lines = {
            { "325:1191746380:1411834179", "พันปีก่อน เมื่อสงครามแห่งผืนทรายแปรผันสิ้นสุดลง พี่น้องของเราสามตนเสียสละตนเองเพื่อกักคิราจิไว้ในโถงเหล่านี้ ขณะที่อนาโครนอสกับสแต็กเฮล์มผนึกอันคิราจ\n\nพวกเราทุกตนสาบานว่าจะตามหาเมริธรา อารีกอส และคาเลสตราซ หากกำแพงสคารับพังลง\n\nและมันก็พังลงจริง ๆ... เราจึงมาที่นี่" },
        },
    },
    [15504] = {
        name = "Vethsera",
        lines = {
            { "386:1541776473:628698401", "ความสยดสยองเกินบรรยายอาศัยอยู่ที่นี่ มรรตัย คธูนกับเหล่าผู้บูชามันไม่เพียงลบหลู่ธรรมชาติ การดำรงอยู่ของพวกมันยังเป็นลางบอกถึงความพินาศของอาเซรอธที่เรารู้จัก\n\nเมริธราเสียสละตนเองเมื่อพันปีก่อน พร้อมกับคาเลสตราซและอารีกอส เพราะพวกเขาก็รู้เรื่องนี้ เรามาที่นี่ตามคำสัตย์ว่าจะกลับมาช่วยพวกเขา แต่เราก็มาที่นี่เพราะต้องหยุดคธูนให้ได้ด้วย!" },
        },
    },
    [15498] = {
        name = "Windcaller Yessendra",
        lines = {
            { "189:959820588:1712806164 N 123:1292416048:1707187219", "ความคืบหน้าอย่างต่อเนื่องในการต่อสู้กับคิราจิของเรา เกิดจากความช่วยเหลือหลากหลายที่ได้รับจากแทบทุกมุมของคาลิมดอร์\n\nการทำสงครามต้องใช้มากกว่าทหาร {name} วีรชนที่ไม่ถูกกล่าวขานหลายคนในสงครามนี้คือพ่อค้าและช่างฝีมือ ผู้คอยจัดหาทรัพยากรที่กองกำลังของเราต้องการ" },
        },
    },
    [15499] = {
        name = "Warden Haro",
        lines = {
            { "236:1249452679:404717820 N 1:46:46", "ข้ามาช่วยสหายดรูอิดเมื่อสงครามเริ่มต้น เช่นเดียวกับคนอื่นอีกมาก\n\nตอนนี้ประตูอันคิราจเปิดแล้ว ข้าตระหนักว่ายังมีงานต้องทำอีกมาก ข้าจึงตัดสินใจอยู่ในซิลิธัสต่อ และช่วยภารกิจนี้ให้ดีที่สุด {name}" },
        },
    },
    [15500] = {
        name = "Keyl Swiftclaw",
        lines = {
            { "122:1580179720:2018586783 N 48:757952636:1720682192", "สงครามนี้ยังไม่จบ มันเพิ่งเริ่มต้นเท่านั้น! เหล่านักรบผู้กล้าหาญทั้งชายหญิงกำลังต่อสู้กับศัตรูของเราภายในอันคิราจทั้งกลางวันและกลางคืน {name} อีกไม่นานนครคิราจิก็จะพ่ายแพ้" },
        },
    },
    [3057] = {
        name = "Cairne Bloodhoof",
        lines = {
            { "283:908689798:2038085085", "สวัสดี คนหนุ่มสาว ขอต้อนรับสู่ธันเดอร์บลัฟฟ์ ที่นี่เจ้าจะพบที่พักพิงอันปลอดภัยจากภาระของโลก ชาวฮอร์ดทุกคนได้รับการต้อนรับที่นี่\n\nวิญญาณแห่งปัจจุบันและอดีตมีชีวิตอยู่ในสถานที่ศักดิ์สิทธิ์แห่งนี้ สหาย จงให้เกียรติพวกเขา และด้วยการนั้น เจ้าก็ให้เกียรติตนเอง" },
            { "380:766577609:928888895", "อา เด็กน้อยที่จะเติบโตเป็นนักรบแน่นอน! ข้าเดาว่าเจ้ากำลังร่วมสัปดาห์เด็กอยู่ ใช่ไหม? กระดูกชราอันเหนื่อยล้าเหล่านี้รู้สึกอบอุ่นเมื่อได้ยินว่าเจ้ากำลังเป็นแบบอย่างให้ผู้อื่นทำตาม\n\nข้ายินดีช่วยเจ้าและเด็กน้อย อืม... ควรแนะนำอะไรเขาดี? ฟังเสียงวิญญาณ ใช่... บางทีควรบอกให้กินผักให้หมดด้วย..." },
            { "520:1824696989:34879498", "Muln Earthfury เล่าเรื่องเหล่า Windshaper ให้ข้าฟังมากมาย ข้าภูมิใจที่ได้เปิดทั้งผืนดินและท้องฟ้าของ Mulgore ต้อนรับชนของเจ้า\n\nชาวทอเรนกับชาวสกายบอร์นต่างก็เป็นลูกหลานของแผ่นดินนี้ แผ่นดิน Kalimdor\n\nข้าหวังว่าชนของเจ้าจะพบสิ่งที่กำลังตามหาและรักษาบ้านเกิดไว้ได้ ระหว่างนั้น ข้าก็หวังว่าเจ้าจะได้รู้จักแผ่นดินที่บรรพชนของเจ้าเคยเรียกว่าบ้านให้มากขึ้น\n\nขอให้ทำตัวตามสบายที่ Thunder Bluff และขอให้พระแม่ธรณีอวยพรการเดินทางของเจ้า" },
        },
    },
    [13418] = {
        name = "Kaymard Copperpinch",
        lines = {
            { "160:1909776839:1186011682", "อย่าลืมซื้อกระดาษห่อตุนไว้ช่วงเทศกาลนี้! ไม่มีอะไรสื่อถึง\"วินเทอร์เวลอันแสนวิเศษ\"ได้ดีเท่าเกราะกับอาวุธที่ห่อเป็นของขวัญให้เพื่อนและครอบครัว" },
            { "93:2137598849:2025781137", "ถ้าข้ามีเกาลัดละก็ เชื่อได้เลยว่าข้าจะเอามาคั่วบนกองไฟ อืม!" },
            { "139:2081685932:1422814978", "อย่าปล่อยให้เสียงกระดิ่งกลบเสียงเหรียญในกระเป๋าเจ้า! ซื้อขนมจากสโมกีวูดพาสเจอร์สไปฉลองวินเทอร์เวลกันเถอะ!" },
            { "91:1575089517:1632516345", "อย่าลืมบอกคุณปู่วินเทอร์นะว่า วินเทอร์เวลครั้งนี้เจ้าอยากได้ของขวัญลับสุดประหลาดใจอะไร!" },
            { "93:1024161885:109778401", "ขอให้มีงานฉลองวินเทอร์เวลอันแสนวิเศษ! เริ่มต้นให้ดีด้วยขนมจากสโมกีวูดพาสเจอร์ส!" },
            { "52:1848546306:1001609437", "ถึงฤดูกาลแห่งของราคาคุ้มแล้ว! ฟาลาลาลาลา!" },
            { "79:1137400884:1037700963", "สดจากไร่สู่จานของคุณ คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส!" },
            { "34:1730220616:85449265", "ขอให้เจ้าและคนที่เจ้ารักประหยัดได้มากมายในเทศกาลนี้!" },
        },
    },
    [13429] = {
        name = "Nardstrum Copperpinch",
        lines = {
            { "160:1909776839:1186011682", "อย่าลืมซื้อกระดาษห่อตุนไว้ช่วงเทศกาลนี้! ไม่มีอะไรสื่อถึง\"วินเทอร์เวลอันแสนวิเศษ\"ได้ดีเท่าเกราะกับอาวุธที่ห่อเป็นของขวัญให้เพื่อนและครอบครัว" },
            { "93:2137598849:2025781137", "ถ้าข้ามีเกาลัดละก็ เชื่อได้เลยว่าข้าจะเอามาคั่วบนกองไฟ อืม!" },
            { "139:2081685932:1422814978", "อย่าปล่อยให้เสียงกระดิ่งกลบเสียงเหรียญในกระเป๋าเจ้า! ซื้อขนมจากสโมกีวูดพาสเจอร์สไปฉลองวินเทอร์เวลกันเถอะ!" },
            { "91:1575089517:1632516345", "อย่าลืมบอกคุณปู่วินเทอร์นะว่า วินเทอร์เวลครั้งนี้เจ้าอยากได้ของขวัญลับสุดประหลาดใจอะไร!" },
            { "93:1024161885:109778401", "ขอให้มีงานฉลองวินเทอร์เวลอันแสนวิเศษ! เริ่มต้นให้ดีด้วยขนมจากสโมกีวูดพาสเจอร์ส!" },
            { "52:1848546306:1001609437", "ถึงฤดูกาลแห่งของราคาคุ้มแล้ว! ฟาลาลาลาลา!" },
            { "79:1137400884:1037700963", "สดจากไร่สู่จานของคุณ คือความอร่อยเปี่ยมคุณค่าจากสโมกีวูดพาสเจอร์ส!" },
            { "34:1730220616:85449265", "ขอให้เจ้าและคนที่เจ้ารักประหยัดได้มากมายในเทศกาลนี้!" },
        },
    },
