    [252389] = {
        name = "Quel'ana Quickgale",
        lines = {
            { "271:1430921000:1360417288 C 48:705031966:1717025531", "Zephras ต้องการนักล่าและเรนเจอร์ยิ่งกว่าครั้งไหน ลมแรงขึ้นเรื่อย ๆ และเวทที่ค้ำจุนเกาะของเรากำลังอ่อนกำลัง ป่าดงยิ่งดุร้ายกว่าเคย ต้องมีคนอย่างข้าคอยดูแลให้พวกเราปลอดภัย\n\nถ้าท่านมีแววเป็น{class} ข้ามีเครื่องมือช่วยให้ท่านเอาตัวรอดในป่าได้" },
            { "325:611214880:506499883", "Zephras ต้องการนักล่าและเรนเจอร์ยิ่งกว่าครั้งไหน ลมแรงขึ้นเรื่อย ๆ และเวทที่ค้ำจุนเกาะของเรากำลังอ่อนกำลัง ป่าดงยิ่งดุร้ายกว่าเคย ต้องมีคนอย่างข้าคอยดูแลให้พวกเราปลอดภัย\n\nถ้าท่านมีแววเป็นพราน ข้ามีเครื่องมือช่วยให้ท่านเอาตัวรอดในป่าได้" },
            { "272:80294259:1504222151 C 48:705031966:1717025531", "Zephras ต้องพึ่งพรานและเรนเจอร์มากกว่าที่เคย ลมยิ่งแรงขึ้นทุกที ส่วนเวทมนตร์ที่ค้ำจุนเกาะของเราก็อ่อนกำลังลง ป่าดุร้ายยิ่งกว่าแต่ก่อน และเราต้องอาศัยคนอย่างข้าเพื่อคุ้มครองผู้คนของเรา\n\nหากเจ้ามีแววเป็น{class} ข้าสอนทักษะที่จำเป็นต่อการเอาตัวรอดในป่าให้ได้" },
        },
    },
    [276171] = {
        name = "Oura Stormspinner",
        lines = {
            { "170:1542055806:778520082", "พวกเราเชนโดไรต้องการผ้าเพิ่มเพื่อเติมเสบียง ผ้าที่ท่านบริจาคจะได้ใช้ประโยชน์ และ Windshapers จะยกย่องท่านมากขึ้นแน่นอน" },
        },
    },
    [268925] = {
        name = "Night Elf Courier",
        lines = {
            { "4:1432760897:190637651 R 91:1730174826:1627866150", "{race}ผู้นี้นอนนิ่ง มีบาดแผลหลายแห่งและผิวเปลี่ยนสีอย่างคนที่ได้รับพิษ" },
            { "104:1252683384:1644861290", "ไนต์เอลฟ์ผู้นี้นอนนิ่ง มีบาดแผลหลายแห่งและผิวเปลี่ยนสีอย่างคนที่ได้รับพิษ" },
        },
    },
    [270459] = {
        name = "Alfina Nightgaze",
        lines = {
            { "141:457881724:679566367 C 140:492902100:1512396757", "ข้าได้รับเชิญให้มาเยือน Dalaran ในนาม Cenarion Circle ข้ารู้สึกว่าที่นี่น่าพิศวง... และชวนให้ไม่สบายใจพอ ๆ กัน\n\nส่วนท่าน{class}ผู้เยาว์ หากยังไม่เคยไป จงไปหา Sheldras Moontree ที่ Stormwind เขาจะสอนวิธีไปยังเขตของ Cenarion Circle ใน Moonglade" },
            { "152:2025196102:25828826", "เมืองนี้น่าอัศจรรย์ แต่ข้าก็รู้สึกไม่สบายใจ การรวมเวทมนตร์มากมายไว้ในที่เดียวมีอันตรายหลายอย่าง ชนเผ่าของข้ารู้เรื่องนี้ดี" },
            { "141:457881724:679566367 C 140:1005649529:423202068", "ข้าได้รับเชิญให้มาเยือน Dalaran ในนาม Cenarion Circle ข้ารู้สึกว่าที่นี่น่าพิศวง... และชวนให้ไม่สบายใจพอ ๆ กัน\n\nส่วนท่าน{class}ผู้เยาว์ หากยังไม่เคยไป จงไปหา Sheldras Moontree ที่ Stormwind เขาจะสอนวิธีไปยังเขตของ Cenarion Circle ใน Moonglade" },
        },
    },
    [3320] = {
        name = "Soran",
        lines = {
            { "48:1633997755:1863090767", "หรือท่านจะไว้ใจฝากของกับก็อบลินมากกว่า?" },
            { "80:760313433:1690742130", "ข้าเอาเลือดตัวเองเป็นประกันว่าธนาคารนี้ปลอดภัย พอให้ท่านเชื่อใจหรือยัง?" },
            { "132:558788186:1832907626", "นอกจากทหารยามที่อยู่ด้านนอก ข้ากับพี่น้องยังเคยรบที่ Hyjal มาแล้ว ใครคิดขโมยของจากธนาคารต้องผ่านพวกเราไปก่อน" },
        },
    },
    [3318] = {
        name = "Koma",
        lines = {
            { "48:1633997755:1863090767", "หรือท่านจะไว้ใจฝากของกับก็อบลินมากกว่า?" },
            { "80:760313433:1690742130", "ข้าเอาเลือดตัวเองเป็นประกันว่าธนาคารนี้ปลอดภัย พอให้ท่านเชื่อใจหรือยัง?" },
            { "132:558788186:1832907626", "นอกจากทหารยามที่อยู่ด้านนอก ข้ากับพี่น้องยังเคยรบที่ Hyjal มาแล้ว ใครคิดขโมยของจากธนาคารต้องผ่านพวกเราไปก่อน" },
        },
    },
    [254081] = {
        name = "Naeluna Swiftmend",
        lines = {
            { "63:1424696870:1216916609", "ถ้าท่านมีแววทางวิชาดรูอิด ข้าฝึกให้ท่านได้" },
        },
    },
    [10540] = {
        name = "Vol'jin",
        lines = {
            { "293:1268761258:512881239 C 126:893606792:1910947368", "อ้อ ใช่ ข้าเคยได้ยินเรื่องเหล่า Windshaper ยินดีที่ได้พบเจ้าเสียที\n\nรู้ไหม เผ่าข้าสู้กับพวกเอลฟ์มานับพันปี ถ้าเจ้าดุดันสักครึ่งหนึ่งของญาติพี่น้องที่ Darnassus หรือ Quel'Thalas เหล่า Darkspear ก็ยินดีจะนับเจ้าเป็นสหาย\n\nขอให้เดินทางโดยสวัสดิภาพ {class} พวกเรา Darkspear รู้ดีเหลือเกินว่าการไร้บ้านเกิดเป็นอย่างไร ข้าหวังว่าเจ้าจะพบสิ่งที่ชนของเจ้าต้องการเพื่อรักษาบ้านเกิดเอาไว้" },
            { "59:1900395329:2063735486", "ข้าคือ Vol'jin แห่งเผ่า Darkspear เจ้าจะมาเป็นมิตรหรือศัตรู?" },
        },
    },
    [10578] = {
        name = "Bom'bay",
        lines = {
            { "165:798677581:72563651", "ใช่แล้วสหาย ข้าเป็นผู้ช่วยของ Gadrin งานอาสานี่ช่วยให้ข้าได้เรียนที่โรงเรียนหมอผีจนจบ เจ้าช่วยเขา ข้าก็ช่วยเจ้าฟรี ๆ เจ้าอยากให้ข้ารักษาอะไรล่ะ?" },
            { "120:242026628:1582106951", "ว่าไงสหาย ไปคุยกับอาจารย์ Gadrin ของข้าตรงโน้นสิ ช่วยเขาจัดการเจ้า Zalazane บ้านั่น แล้วข้าจะรักษาเจ้าให้หายดี!" },
        },
    },
    [10668] = {
        name = "Beaten Corpse",
        lines = {
            { "121:647384699:602932953", "ตรงหน้าคือร่างของนักรบออร์คหญิง\n\nเห็นได้ชัดว่านางเสียชีวิตในการต่อสู้ อาจเป็นการต่อสู้กับพวกควิลโบร์แถวนี้" },
            { "311:819587365:1804101253", "คุณพลิกร่างของออร์คผู้เสียชีวิต เห็นร่องรอยจากคมอาวุธและเวทมนตร์ เกราะของนางแทบไม่เหลือสภาพ เส้นผมพันกันติดใบหน้า\n\nเมื่อเทียบกับที่ Mankrik บอกไว้ คุณมั่นใจว่านี่คือภรรยาของเขา\n\nข่าวนี้คงทำให้เขาเสียใจ แต่คุณแน่ใจว่าเขาควรได้รู้ความจริง" },
        },
    },
    [11084] = {
        name = "Tarn",
        lines = {
            { "88:1621888932:1032501932", "ข้าพอใจกับความก้าวหน้าของเจ้าจนถึงตอนนี้ พระแม่ธรณีคงดลใจให้เจ้าทำได้ดีถึงเพียงนี้" },
            { "180:1253181330:739761838", "ขวานของข้าผ่านศึกมามาก ข้าเลยชอบวางไว้ใกล้มือ กองกำลังศัตรูเคยบุกเข้ามาถึงเมืองหลวงของเราหลายครั้งแล้ว แต่ไม่ต้องกลัว เราขับไล่พวกมันกลับไปได้ทุกครั้ง" },
            { "169:385420459:1804819362", "ข้าช่วยฝึกเจ้าต่อไม่ได้แล้ว ฝีมือทำเครื่องหนังของเจ้าทัดเทียมกับข้า ไปคุยกับ Una ตรงนั้นเถอะ ถ้าจำเป็นข้าจะรับรองฝีมือให้" },
            { "156:844129913:1950498879", "ฝีมือเจ้ายังไม่พอจะเรียนวิชาของข้า ลองไปคุยกับ Mak ตรงนั้นดู เขาช่วยสอนเจ้าได้จนกว่าจะพร้อมเรียนขั้นสูง" },
        },
    },
    [11798] = {
        name = "Bunthen Plainswind",
        lines = {
            { "74:649772760:185654328", "อยากเดินทางไป Thunder Bluff ทางอากาศไหม? Cenarion Circle ยินดีออกค่าเดินทางให้" },
            { "19:286678481:748394578", "เจ้าไม่ใช่ดรูอิดนี่!" },
            { "128:1643523802:136374703", "ถ้าจะหาทางบินกลับ Rut'theran Village ให้ไปคุยกับ Silva Fil'naveth ไนต์เอลฟ์ที่ทำหน้าที่เดียวกับข้า" },
            { "344:1037567898:871876735 N 91:181963181:186810842", "เจ้าต้องค้นหาในน่านน้ำ Westfall จากจุดที่ Gold Coast Quarry จรดชายฝั่ง ให้มุ่งตรงไปทางตะวันตกค่อนไปทางเหนือ จะเห็นสมอเรือ ถัดจากสมอออกไปมีเรือจมอยู่ใต้น้ำลึก แรงดันน้ำที่นี่รุนแรงนัก ว่ายไกลเกินไป แม้แต่นักว่ายน้ำที่แข็งแรงที่สุดก็จะถูกแรงดันบดขยี้เมื่อหมดแรง\n\nมองหาสิ่งที่ธรรมชาติสร้างไว้ให้ช่วยได้ {name} แถวนี้มีรอยแยกที่ปล่อยฟองอากาศ นักดำน้ำลึกลงไปเติมลมหายใจตรงนั้นได้" },
            { "456:1016170689:653978511", "ตามขอบ North Tide's Run ใน Silverpine Forest มีเรือร้างเกยอยู่ริมฝั่ง สิ่งที่เจ้าตามหาอยู่ในทะเลทางตะวันตกจากจุดนั้น ถ้าว่ายไกลเกินไป เจ้าจะหมดแรงและถูกทะเลบดขยี้ ของอยู่ในกล่องล็อกที่ก้นทะเล รอให้เจ้าไปเอา\n\nดำน้ำลึกขนาดนั้นโดยไม่มีตัวช่วย รอดยากนัก แต่ไม่ต้องถอดใจ รอยแยกที่ปล่อยฟองอากาศช่วยเติมลมหายใจให้นักดำน้ำที่มาตามหาจี้ครึ่งนี้ได้ ใช้ให้เป็นประโยชน์ล่ะ" },
        },
    },
    [11832] = {
        name = "Keeper Remulos",
        lines = {
            { "20:1618358443:2005487917", "สวัสดี นักเดินทาง" },
        },
    },
    [11868] = {
        name = "Sayoc",
        lines = {
            { "66:1708532404:1900035822", "มาหัดใช้อาวุธชนิดใหม่ หรือมาให้ข้าเสียเวลา?" },
            { "413:1383463616:267779317", "Ansekhwa ครูอาวุธชาวทอเรนอยู่ที่ Lower Rise ใน Thunder Bluff เขาสอนใช้กระบองมือเดียวและสองมือ ไม้เท้า และปืน\n\nHanashi ที่ยืนข้างข้าตรงนี้ สอนใช้ธนู ขวานมือเดียวและสองมือ ไม้เท้า และอาวุธขว้างทุกชนิด\n\nArchibald ครูอาวุธชาวอันเดดใน War Quarter ของ Undercity สอนใช้หน้าไม้ มีดสั้น ดาบมือเดียวและสองมือ และอาวุธด้ามยาว" },
        },
    },
    [11869] = {
        name = "Ansekhwa",
        lines = {
            { "127:1217248859:1348941687", "หากเจ้ามีความสามารถจะเรียนรู้ ข้ายินดีเป็นเกียรติที่จะสอนวิธีใช้อาวุธที่ข้าชำนาญให้" },
            { "480:1532950774:1848684285", "Sayoc ครูอาวุธชาวออร์คอยู่ที่ Valley of Honor ใน Orgrimmar เขาสอนใช้ธนู มีดสั้น อาวุธสวมหมัด ขวานมือเดียวและสองมือ และอาวุธขว้าง\n\nHanashi ครูอาวุธชาวโทรลล์ใน Valley of Honor ของ Orgrimmar สอนใช้ธนู ขวานมือเดียวและสองมือ ไม้เท้า และอาวุธขว้าง\n\nArchibald ครูอาวุธชาวอันเดดใน War Quarter ของ Undercity สอนใช้หน้าไม้ มีดสั้น ดาบมือเดียวและสองมือ และอาวุธด้ามยาว" },
        },
    },
    [1385] = {
        name = "Brawn",
        lines = {
            { "159:1877261841:1563850133", "ที่นี่ห่างไกลจากที่ที่ข้าจะเรียกว่ามีความเจริญนัก อย่างน้อยก็จนกว่า Horde จะส่งกำลังเสริมมาได้ เจ้าคงชอบงานเครื่องหนังจริง ๆ ถึงมาถึงนี่" },
            { "189:1130043243:811094848", "ตอนนี้เราเพิ่งตั้งหลักบนทวีปนี้ได้แค่นิดเดียว แต่พวกมนุษย์ต้านเราไปตลอดไม่ได้หรอก แล้วพวกมันจะชดใช้ที่จับเราเป็นทาส เราจะตัดลิ้นโกหกของพวกมันให้สาสมกับการทรยศ" },
            { "184:828201072:201427672", "ข้าก็อยากสอนเจ้า แต่ฝีมือเจ้าสูงเกินที่ข้าจะสอนไหว เอาอย่างนี้ ไปคุยกับ Una ชาวทอเรนที่ร้านค้าฝั่งตะวันตกเฉียงเหนือของที่ราบสูงกลาง Thunder Bluff นางมีฝีมือจริง ๆ" },
            { "180:1683787142:35873293", "กล้ามากกว่าฉลาดนะเจ้าที่มาหาข้าทั้งที่ฝึกมายังไม่พอ ไปคุยกับคนที่ฝีมือใกล้เคียงเจ้ากว่านี้ อย่าง Kamari ออร์คที่อยู่ใน The Drag ของ Orgrimmar" },
        },
    },
    [2492] = {
        name = "Lexington Mortaim",
        lines = {
            { "142:549538284:83645834", "ในฐานะจอมเวท เจ้าเป็นหนึ่งในคนไม่กี่คนที่เปิดประตูมิติเพื่อเดินทางกลับมาที่นี่ได้ หากเจ้าพร้อม ข้าจะสอนให้" },
            { "83:493991169:2127562327", "ข้าไม่คิดว่าเจ้าจะเข้าใจธรรมชาติของเวทเปิดประตูมิติได้ ความคิดของเจ้ายังไม่เฉียบคมพอ" },
        },
    },
    [255853] = {
        name = "Urs'endris",
        lines = {
            { "148:263936611:1003252109", "จิตวิญญาณแห่งความแข็งแกร่งมีความหมายกว้างกว่าพละกำลัง การเผชิญความยากลำบากทั้งจากภายในใจและจากโลกภายนอก นั่นคือความหมายของการรับร่างของข้า" },
        },
    },
    [256635] = {
        name = "Peacekeeper",
        lines = {
            { "119:1339232862:756525630", "นักผจญภัย! สะพานสายลมที่ไปยอดผาอีกฝั่งยังไม่มั่นคง เจ้าอาจต้องรออยู่กับข้าที่นี่จนกว่าสะพานจะกลับมา" },
        },
    },
    [258130] = {
        name = "Jorel Windsinger",
        lines = {
            { "188:1561008074:195987728", "<ตรงหน้าคุณคือศพของ Jorel Windsinger\n\nขาทั้งสองข้างมีแผลฉีกลึก ขนไหม้เกรียมเป็นรอยจากสายฟ้า\n\nเห็นได้ชัดว่าเขาต่อสู้จนกระทั่งทนพิษบาดแผลไม่ไหว>" },
        },
    },
    [259013] = {
        name = "Resaan Nimbuswalker",
        lines = {
            { "265:705328580:1471176311", "<ตรงหน้าคุณคือร่างของชาวสกายบอร์น ร่างของเขาบอบช้ำและเสียรูป แต่ยังจำได้ว่าเป็นใคร เห็นได้ชัดว่าเขาเสียชีวิตอย่างน่าสยดสยองขณะพยายามหนี\n\nดูเหมือนข้าวของทั้งหมดของเขายังอยู่กับตัว ใกล้กันมีกล่องไม้ที่บรรจุของไว้ครึ่งหนึ่งล้มอยู่ ของข้างในหกกระจายบนพื้น>" },
            { "266:1778855831:1790762127", "<ชาว Skyborne นอนอยู่ตรงหน้าเจ้า ร่างบิดเบี้ยวและมีรอยช้ำ แต่ยังพอจำได้ว่าเป็นใคร เห็นได้ชัดว่าเขาพบจุดจบอันโหดร้ายขณะพยายามหนี\n\nดูเหมือนข้าวของทั้งหมดยังอยู่กับร่างเขา และมีลังที่ใส่ของไว้ครึ่งหนึ่งคว่ำจนของกระจายอยู่บนพื้นใกล้ ๆ>" },
        },
    },
    [267324] = {
        name = "Margaret Weaver",
        lines = {
            { "85:1938448218:1122547814", "อยากเรียนวิธีเก็บหนังจากสัตว์ที่ตายแล้วหรือ? หรืออยากได้เครื่องมือใหม่?" },
        },
    },
    [2704] = {
        name = "Hanashi",
        lines = {
            { "63:843416712:1142613072", "ว่าไงสหาย มาถูกที่แล้วถ้าอยากเรียนวิธีใช้อาวุธชนิดใหม่" },
            { "396:682012902:299548804", "Ansekhwa ครูฝึกอาวุธชาวทอเรนอยู่ที่ Lower Rise ใน Thunder Bluff เขาสอนใช้กระบองมือเดียวและสองมือ ไม้เท้า และปืน\n\nArchibald ครูฝึกอาวุธอันเดดใน War Quarter แห่ง Undercity สอนใช้หน้าไม้ มีดสั้น ดาบมือเดียวและสองมือ และอาวุธด้ามยาว\n\nส่วน Sayoc ออร์คหน้าตาน่าเกลียดที่อยู่ตรงนี้ สอนใช้ธนู มีดสั้น อาวุธสวมหมัด ขวานมือเดียวและสองมือ กับอาวุธขว้างได้ สหาย" },
            { "66:1708532404:1900035822", "มาเรียนวิธีใช้อาวุธชนิดใหม่ หรือแค่มาให้ข้าเสียเวลา?" },
        },
    },
    [270582] = {
        name = "Mon'ye",
        lines = {
            { "11:927657569:725753248 C 148:954006345:931009229", "สวัสดี {class}\n\nถ้าเจ้าสนใจ ข้าสอนวิธีร่ายเวทล้อมกายเพื่อเปลี่ยนรูปลักษณ์ของอุปกรณ์ให้ได้ เจ้าต้องการใช้บริการของข้าหรือไม่?" },
        },
    },
    [275270] = {
        name = "Windshapers Dockmaster",
        lines = {
            { "51:304435489:1488090449", "ผู้เดินทางไป Mulgore ทุกคนควรออกเดินทางจากที่นี่" },
            { "74:81511616:2011857126", "เรือเหาะ Skycutter ลำนี้จะพาเจ้าตรงไปยังทุ่งกว้างอันงดงามของ Mulgore" },
        },
    },
    [3008] = {
        name = "Mak",
        lines = {
            { "154:1271031236:1820751525", "ฝีมือเจ้าล้ำหน้าข้าไปแล้ว สหาย ไปคุยกับ Tarn ที่นี่เถอะ เขารู้เรื่องเครื่องหนังมากกว่าข้านัก ข้ามั่นใจว่าเขายินดีรับศิษย์เพิ่มอีกคน" },
            { "148:906033422:619226466", "เขาว่า Cairne อยู่ที่นี่ด้วยตัวเอง พอทำของขวัญที่คู่ควรเสร็จ ข้าจะไปพบท่าน บางทีท่านอาจให้คำแนะนำดี ๆ แก่ข้า" },
            { "129:366951177:1556330935", "ล้างมือให้สะอาดก่อนเริ่มงานทุกครั้ง ถ้าให้เลือดหรือดินเปื้อนหนัง ก็จะเสียความงามตามธรรมชาติไป" },
        },
    },
    [3703] = {
        name = "Krulmoo Fullmoon",
        lines = {
            { "149:578601827:2138824284", "ข้าไม่ได้ฝึกศิษย์ระดับต้น ไปหา Waldor ชาวทอเรนที่ Wailing Caverns ใน Barrens แถวนี้เถอะ เขาช่วยเจ้าได้ทุกอย่างที่ต้องการ" },
            { "93:1358281968:1068892832", "หนังที่ทนที่สุดมาจากโคโดที่มาสิ้นใจในแดนรกร้างแห่งนี้" },
            { "194:1974149983:1579881491", "ข้าสอนเจ้าต่อไม่ได้แล้ว ฝีมือเจ้าเหนือกว่าข้า ไปหา Una ชาวทอเรนที่ร้านค้าฝั่งตะวันตกเฉียงเหนือของที่ราบสูงกลาง Thunder Bluff นางสอนวิชาขั้นสูงกว่านี้" },
            { "112:999321371:23716799", "มาเรียนต่อหรือ? ถ้าอย่างนั้นปัดฝุ่นที่ติดเสื้อผ้ามาระหว่างทางเสีย แล้วมาลงมือกัน" },
            { "191:1909197838:2007016582", "ข้ารู้ว่าชุดหนังสีน้ำเงินนี่สะดุดตา เจ้าเห็นไหม แถวนี้มีทหารใหม่ไฟแรงวิ่งไปทั่ว ออกล่าออกฆ่าด้วยความฮึกเหิมมากกว่าความยั้งคิด ข้าก็ต้องระวังตัวไว้บ้าง" },
        },
    },
    [3704] = {
        name = "Mahani",
        lines = {
            { "38:1649982956:716461332", "ยินดีต้อนรับสู่กระโจมของเรา ให้ข้าช่วยอะไรไหม?" },
            { "170:990820656:1846826164", "เจ้ามีความรู้มากทีเดียว นักเดินทาง เจ้าต้องเรียนกับผู้รู้ที่ลึกซึ้งกว่าข้า มีผู้เล่าขานถึงปัญญาของ Josef Gregorian ไว้มาก ไปหาเขาได้ที่ Undercity" },
            { "61:1081999004:1804300442", "ทำได้อย่างชำนาญทีเดียว! เอาละ มาเรียนต่อกันเถอะ..." },
        },
    },
    [4609] = {
        name = "Doctor Marsh",
        lines = {
            { "169:133449629:27244305", "ตราบใดที่ Algernon ยังหาของมาให้ ข้าก็ทำงานทุกอย่างตรงนี้ได้โดยไม่ต้องออกไปหาสมุนไพรสักต้น ต่อให้ไม่ได้เห็นความมหัศจรรย์ของธรรมชาติอีกเลย ข้าก็ไม่เสียดาย" },
            { "199:1413297042:2037745869", "ข้าไม่มีความรู้จะถ่ายทอดให้เจ้าอีกแล้ว เดินผ่านซุ้มประตู ลงทางลาดไปทางตะวันออกเฉียงใต้ แล้วไปคุยกับ Doctor Herbert Halsey เขาเป็น Forsaken ที่สอนวิธีปรุงยาขั้นสูงกว่านี้ได้" },
            { "201:450479401:2021195888", "ข้าไม่ขำเลยที่เจ้าบังอาจมาขอเรียนกับข้า เดินผ่านซุ้มประตู ลงทางลาดไปทางตะวันออกเฉียงใต้ แล้วไปคุยกับ Doctor Martin Felben เขาเป็น Forsaken ที่สอนพื้นฐานให้เจ้าได้" },
            { "148:208204462:1029432798", "มาเรียนหรือ? เอาสิ ข้าสอนเจ้าแล้วเจ้าคงไม่ทำอันตรายพันธมิตรเรามากนัก ขอแค่เอาวิชาไปเล่นงานศัตรูเราจริง ๆ ก็พอ" },
        },
    },
    [5784] = {
        name = "Waldor",
        lines = {
            { "94:388298590:534105291", "แม้จะอยู่กลางป่า เจ้ายังแสวงหาความรู้ ความใฝ่รู้ของเจ้าน่าชื่นชมจริง ๆ" },
            { "122:429002673:941222754 N 51:482546857:1688437722", "ถ้ำใต้เท้าเรามีหนังสัตว์แปลก ๆ ล้ำค่าอยู่มาก แต่ถ้าคิดจะลงไปลึกก็จงระวังตัวไว้ {name} จำไว้ว่าหนังของเจ้ามีค่ากว่ามาก" },
            { "195:1024374545:1954728492", "เจ้าเข้าใจเรื่องหนังลึกซึ้งกว่าข้าแล้ว ลองไปหา Krulmoo Fullmoon ชาวทอเรนที่ Camp Taurajo ใน The Barrens ดูสิ เขามีความรู้อีกมากจะสอนศิษย์ฝีมืออย่างเจ้า" },
            { "201:2132058251:635644290", "เจ้ารู้เรื่องงานหนังลึกซึ้งกว่าข้าแล้ว ลองไปหา Aayndia Floralwind ที่เมือง Astranaar ในป่า Ashenvale ดูสิ นางมีความรู้อีกมากที่จะถ่ายทอดให้ศิษย์ฝีมืออย่างเจ้า" },
        },
    },
    [5958] = {
        name = "Thuul",
        lines = {
            { "142:549538284:83645834", "ในฐานะจอมเวท เจ้าเป็นหนึ่งในคนไม่กี่คนที่เปิดประตูมิติเพื่อเดินทางกลับมาที่นี่ได้ หากเจ้าพร้อม ข้าจะสอนให้" },
            { "83:493991169:2127562327", "ข้าไม่คิดว่าเจ้าจะเข้าใจธรรมชาติของเวทเปิดประตูมิติได้ ความคิดของเจ้ายังไม่เฉียบคมพอ" },
        },
    },
    [9564] = {
        name = "Frezza",
        lines = {
            { "332:1687541178:1409175073", "แน่นอนว่าไม่มีอันตรายเรื่องที่ทุกอย่างจะติดไฟแล้วระเบิดเหมือนระเบิดฮีเลียมลูกยักษ์หรอก เจ้าเครื่องนี้จะพาไปถึง Undercity เร็วกว่าและปลอดภัยกว่าเรือทุกลำ แถมวิวก็สวยจนแทบลืมหายใจ พูดถึงเรื่องลมหายใจ ห้ามสูบบุหรี่บนเรือเหาะ และห้ามร่ายเวทไฟระหว่างเดินทาง" },
        },
    },
    [9566] = {
        name = "Zapetta",
        lines = {
            { "333:668359571:470743584", "พี่น้องของข้าบอกว่าเส้นทางค้าขายสายนี้จะทำเงินให้เรามหาศาล แต่ไม่เห็นบอกว่าข้าต้องเป็นคนมาประจำฝั่งนี้ ถ้าเจ้านั่งเรือเหาะกลับมาทางนี้อีก ช่วยเอาอะไรมาให้ข้ากินหน่อยได้ไหม? ที่ Orgrimmar มีเนื้อชั้นดีขาย ข้าอยากได้เนื้อที่ไม่ได้ตายไปตั้งหลายสัปดาห์ก่อนจะหยุดดิ้นจริง ๆ" },
        },
    },
    [11956] = {
        name = "Great Bear Spirit",
        lines = {
            { "60:1419043069:834519933", "หมีมองคุณอย่างสงบและอดทนโดยไม่พูดอะไร" },
            { "307:597080973:707817720", "วิญญาณหมีมองคุณด้วยสายตาสงบนิ่ง คุณได้ยินเสียงพูดราวกับดังมาจากหมี แต่ตัวหมีไม่มีทีท่าว่ากำลังพูด\n\n“สวัสดี สหายรุ่นเยาว์ หากเจ้ามาขอคำชี้แนะ บางทีข้าอาจช่วยให้เจ้าพบสิ่งที่ตามหาได้”" },
            { "393:1837916641:467642749", "ข้าเป็นตัวแทนของความแข็งแกร่งที่ค้ำจุนดรูอิดรุ่นเยาว์อย่างเจ้า เจ้ามาเพื่อเรียนรู้ความแข็งแกร่งนี้ เด็กน้อย และข้าจะสอนให้ ข้าจะถ่ายทอดทุกสิ่งที่เป็นแก่นของวิญญาณหมี หากเจ้าตั้งใจฟังและทำความเข้าใจ\n\nหากอยากเข้าใจว่าการดึงพลังจากวิญญาณของข้าหมายถึงอะไร เจ้าต้องรู้ความสำคัญของทั้งพละกำลังกายและความเข้มแข็งของใจ" },
            { "416:1706808630:1011214279", "ความแข็งแกร่งของร่างกายคือพลังและความรวดเร็วในการลงมือ เจ้าต้องรักษาทั้งกายและใจให้พร้อมอยู่เสมอ ร่างอันใหญ่โตของหมีบ่งบอกถึงพละกำลังของมัน ในการต่อสู้ มันเป็นคู่ต่อสู้ที่ดุร้าย แต่ขนาดตัวนั้นยังซ่อนความปราดเปรียวและไหวพริบเอาไว้ เจ้าจะใช้สิ่งที่ศัตรูคาดไม่ถึงเหล่านี้ให้เป็นประโยชน์\n\nเจ้าต้องอาศัยความแข็งแกร่งของกายหมีจึงจะเชี่ยวชาญวิถีแห่งกรงเล็บ" },
            { "502:1741328470:1415073668", "ความเข้มแข็งของใจทำให้เจ้ากล้าตัดสินใจลงมือ... ด้วยเจตนาที่บริสุทธิ์และตรงไปตรงมา ผู้รักษาสมดุลจะนิ่งนอนใจหรือทำเพียงตามกิจวัตรไม่ได้\n\nเจ้าต้องยืนหยัดในสิ่งที่เชื่อและพร้อมต่อสู้เพื่อสิ่งนั้น แม่หมีมุ่งมั่นปกป้องลูกของมันอย่างไม่ลดละ เช่นเดียวกับหมีชราที่ปกป้องถ้ำของตน เจ้าต้องเข้าใจความมุ่งมั่นและความเข้มแข็งของใจเช่นนี้จึงจะเชี่ยวชาญวิถีแห่งกรงเล็บ" },
            { "445:1015382778:353450287", "ยังต้องดูกันต่อไปว่าเจ้าพร้อมหรือยัง เด็กน้อย แม้แต่ดรูอิดที่อาวุโสและรอบรู้ที่สุดก็ยังเตรียมตัวไม่เคยพอเมื่อถึงบททดสอบครั้งสำคัญที่สุด\n\nเจ้าได้ฟังคำของข้าแล้ว บัดนี้จงเดินหน้าต่อ จดจำสิ่งที่ข้าสอนไว้ วันหนึ่งความแข็งแกร่งของเจ้าจะถูกทดสอบ เจ้าต้องเผชิญศัตรูอย่างหมี ด้วยกำลังกายและความเข้มแข็งของใจ จงเรียนรู้จากการต่อสู้ เด็กน้อย ไปเถิด... พร้อมพรของข้า" },
        },
    },
    [11800] = {
        name = "Silva Fil'naveth",
        lines = {
            { "19:286678481:748394578", "เจ้าไม่ใช่ดรูอิดนี่!" },
            { "79:442964062:1574454037", "อยากเดินทางไป Rut'theran Village ทางอากาศไหม? Cenarion Circle ยินดีออกค่าเดินทางให้" },
            { "120:1525697279:1275223680", "ถ้าต้องการบินกลับไป Thunder Bluff ไปคุยกับ Bunthen Plainswind ชาวทอเรนที่ทำหน้าที่เดียวกับข้าเถอะ" },
            { "437:1251871291:1625677419", "ทางเหนือของ Darkshore มีแม่น้ำ Cliffspring River ไหลลงมาจากดินแดนที่ตอนนี้เรียกว่า Felwood จากปากแม่น้ำที่ไหลลงสู่ Mist's Edge ให้ไปทางเหนือจนถึงจุดที่น้ำทะเลเริ่มลึกมาก ตรงนั้นมีกลุ่มหินที่บางคนเรียกว่า Stone Claw เพราะมีรูปร่างเหมือนกรงเล็บ เจ้าอาจพบสิ่งที่ตามหาที่นั่น\n\nระวังไว้ พวก thresher ชุมนุมกันแถว Stone Claw และจะโจมตีผู้ที่รุกล้ำอาณาเขตของมัน" },
            { "260:954977555:1959416808 N 215:1666851854:181541601", "ทางตะวันออกเฉียงเหนือของ Barrens มีแอ่งน้ำที่ปนเปื้อนมลพิษ คนแถวนั้นเรียกว่า Sludge Fen บริษัท Venture ทำให้น้ำที่เคยใสเป็นสีฟ้ากลายเป็นปลักที่เต็มไปด้วยของเหลือและของเสียจากอุตสาหกรรม สิ่งที่เจ้าตามหาอยู่ใจกลางบึงนี้ {name}\n\nระวังไว้ บริษัท Venture ไม่ยอมให้ใครบุกรุก และถือว่าทุกคนที่ไม่ได้ทำงานให้เป็นผู้บุกรุก เจ้าจะตกเป็นเป้าเป็นพิเศษในฐานะผู้พิทักษ์ธรรมชาติ ซึ่งเป็นสิ่งที่พวกเขาต่อต้านอย่างแข็งขัน" },
        },
    },
    [2485] = {
        name = "Larimaine Purdue",
        lines = {
            { "142:549538284:83645834", "ในฐานะจอมเวท เจ้าเป็นหนึ่งในคนไม่กี่คนที่เปิดประตูมิติเพื่อเดินทางกลับมาที่นี่ได้ หากเจ้าพร้อม ข้าจะสอนให้" },
            { "83:493991169:2127562327", "ข้าไม่คิดว่าเจ้าจะเข้าใจธรรมชาติของเวทเปิดประตูมิติได้ ความคิดของเจ้ายังไม่เฉียบคมพอ" },
        },
    },
    [2489] = {
        name = "Milstaff Stormeye",
        lines = {
            { "142:549538284:83645834", "ในฐานะจอมเวท เจ้าเป็นหนึ่งในคนไม่กี่คนที่เปิดประตูมิติเพื่อเดินทางกลับมาที่นี่ได้ หากเจ้าพร้อม ข้าจะสอนให้" },
            { "83:493991169:2127562327", "ข้าไม่คิดว่าเจ้าจะเข้าใจธรรมชาติของเวทเปิดประตูมิติได้ ความคิดของเจ้ายังไม่เฉียบคมพอ" },
        },
    },
    [4165] = {
        name = "Elissa Dumas",
        lines = {
            { "142:549538284:83645834", "ในฐานะจอมเวท เจ้าเป็นหนึ่งในคนไม่กี่คนที่เปิดประตูมิติเพื่อเดินทางกลับมาที่นี่ได้ หากเจ้าพร้อม ข้าจะสอนให้" },
            { "83:493991169:2127562327", "ข้าไม่คิดว่าเจ้าจะเข้าใจธรรมชาติของเวทเปิดประตูมิติได้ ความคิดของเจ้ายังไม่เฉียบคมพอ" },
        },
    },
    [5957] = {
        name = "Birgitte Cranston",
        lines = {
            { "142:549538284:83645834", "ในฐานะจอมเวท เจ้าเป็นหนึ่งในคนไม่กี่คนที่เปิดประตูมิติเพื่อเดินทางกลับมาที่นี่ได้ หากเจ้าพร้อม ข้าจะสอนให้" },
            { "83:493991169:2127562327", "ข้าไม่คิดว่าเจ้าจะเข้าใจธรรมชาติของเวทเปิดประตูมิติได้ ความคิดของเจ้ายังไม่เฉียบคมพอ" },
        },
    },
    [270581] = {
        name = "Fyrenz Vishonar",
        lines = {
            { "11:927657569:725753248 C 148:954006345:931009229", "สวัสดี {class}\n\nถ้าเจ้าสนใจ ข้าสอนวิธีร่ายเวทล้อมกายเพื่อเปลี่ยนรูปลักษณ์ของอุปกรณ์ให้ได้ เจ้าต้องการใช้บริการของข้าหรือไม่?" },
        },
    },
    [68] = {
        name = "Stormwind City Guard",
        lines = {
            { "133:2058852606:1367999946", "ถ้าต้องการฝากสัตว์เลี้ยงไว้ระหว่างฝึกตัวอื่น ไปคุยกับ Jenova Stoneshield ที่ Dwarven District เถอะ" },
            { "31:332017592:1003306482", "ต้องการให้ข้าชี้ทางไปไหน?" },
            { "217:1202580182:1320917283", "Woo Ping อึดเหลือเชื่อ ข้าเคยดูเขาฝึกใช้อาวุธหลายชั่วโมงติดกัน จบแล้วนึกสงสารหุ่นซ้อมเสียจริง ข้านึกไม่ออกเลยว่าใครจะสอนการต่อสู้ด้วยอาวุธได้ดีกว่าเขา" },
            { "41:99630854:2128042192", "เจ้าสนใจสนามรบแห่งไหน?" },
            { "138:1007643925:717505216", "กริฟฟินหรือ? ข้าไม่ค่อยชอบเจ้าพวกนี้นัก แต่ก็แล้วแต่คนละนะ\n\nเจ้าจะพบ Dungar Longdrink บนกำแพงเมืองฝั่ง Trade District" },
            { "131:1579755382:872878809", "อยากลองขี่กริฟฟินหรือ? Dungar เลี้ยงพวกมันไว้บนกำแพงเมืองฝั่ง Trade District อย่าลืมเกาะแน่น ๆ ล่ะ!" },
            { "165:1579876993:482203853", "อ้อ เจ้าตามหา Stormwind Visitor's Center สินะ พอเดินจาก Valley of Heroes ผ่านประตูหน้าเข้ามา ก็อยู่ตึกแรกทางซ้ายมือ" },
            { "86:1755551096:412201569", "เจ้าเป็นลูกหลานแห่งธรรมชาติสินะ ถ้าอย่างนั้นไปที่บ่อน้ำจันทร์ในเขต The Park ได้เลย" },
            { "184:1019180285:891164179", "ฟังดูเหมือนเจ้าต้องการคุยกับ Maginor Dumas! ปกติเขาอยู่ที่ Wizard's Sanctum ใน Mage Quarter แต่เจ้าพวกจอมเวทจะเปิดประตูมิติไปไหนเมื่อไร ใครจะไปรู้" },
            { "70:1228897223:1390942212", "ข้าแนะนำให้ไปดูที่ Cathedral of Light ใน Cathedral Square" },
            { "102:2136878040:1064128300", "ถ้าอยากตามหาพวกโจร ต้องไป Old Town อยู่มุมตะวันออกเฉียงเหนือของ Stormwind" },
            { "178:329592739:528842321", "ลองไปดูที่ค่ายทหารหรือร้าน Pig and Whistle Tavern ใน Old Town ถ้าแวะร้านเหล้าก็ลองชิมเบียร์ดี ๆ ของเขาด้วยล่ะ ข้าบอกเลยว่าเบียร์คนแคระต้องอาย" },
            { "108:1419067024:2118252711", "พ่อค้าอีกคนสินะ ตลาดประมูลอยู่ใน Trade District ห่างจากธนาคารไม่ไกล" },
            { "185:1676239868:1072471262", "Stormwind Counting House อยู่ใกล้ประตูหน้าใน Trade District ของ Stormwind นับเงินจนเบื่อเมื่อไรก็อย่าลืมแวะไปดื่มที่ Gilded Rose ล่ะ" },
            { "209:1357814927:244224787", "เคยได้ยินเรื่องรถรางแล้วสินะ นั่งสนุกอย่าบอกใคร! มันอยู่ด้านในสุดของ Dwarven District อ้อ อย่ายื่นแขนขาออกนอกรถตอนรถกำลังวิ่งล่ะ" },
            { "267:773300528:1162973153", "อา The Gilded Rose... ที่นอนขนปุยนุ่ม ๆ กับน้ำอุ่น ๆ แค่นึกถึงโรงเตี๊ยมก็อยากจะ... ::หาว:: โชคดีจังถ้าเจ้าจะไปที่นั่น มันอยู่ฝั่งตะวันตกของ Trade District... หมอนนุ่ม ๆ ผ้าห่มอุ่น ๆ... ::หาว::" },
            { "163:1398345684:1617218404", "อ้อ เจ้าตามหา Dungar Longdrink นี่เอง กริฟฟินของเขาเร็วเป็นอันดับต้น ๆ ในแถบนี้ของ Khaz Modan ไปหาเขาบนกำแพงเมืองฝั่ง Trade District ได้เลย" },
            { "182:1305844100:1757609898", "จะตั้งกิลด์หรือ? ขอให้โชคดีนะ!\n\nไปคุยกับ Aldwin Laughlin ที่ Stormwind Visitor's Center ใน Trade District พอเดินเข้ามาจาก Valley of Heroes ก็ถึงเลย" },
            { "222:955836489:231068528", "ข้าไม่รู้จริง ๆ ว่าทำได้อย่างไร ตู้ไปรษณีย์นั่นต้องเป็นประตูมิติหรืออะไรทำนองนั้นแน่ ข้าเห็นคนล้อมตู้ข้างธนาคารทั้งวัน หยิบทั้งดาบ โล่ สารพัดชุดเกราะออกมาจากกล่องเล็กแค่นั้น!" },
            { "245:676400897:898711382", "อาจารย์ Woo Ping เชี่ยวชาญอาวุธแทบทุกชนิดที่มนุษย์รู้จัก ฝีมือดาบของเขายิ่งร้ายกาจเป็นพิเศษ ถ้าอยากฝึก เขามักอยู่ที่ Weller's Arsenal คอยอาวุธล็อตใหม่มาส่ง" },
            { "256:597383050:710360537", "โอ้โฮ ก้าวหน้าขึ้นแล้วหรือ? เจ้าตามหา Champions' Hall สินะ อยู่สุดด้านตะวันออกเฉียงใต้ของ Old Town ถ้าเป็นนายทหารก็เข้าไปได้ หากยังไม่ถึงยศนั้นก็คุยกับ Officer Areyn ที่ยืนอยู่ข้างนอกได้ ขอให้โชคดี!" },
            { "28:1270891746:2089357014 N 138:1145541993:125411986", "ข้าก็อยากไปกับเจ้าเหมือนกัน {name} ไปที่ Stormwind Keep เจ้าจะพบ Thelman Slatefist ในท้องพระโรง เขาจะช่วยให้เจ้าเดินทางไป Alterac Valley ได้" },
            { "288:178638223:1047665319", "สิ่งที่ The League of Arathor พยายามทำใน Arathi Basin น่าชื่นชม เสียดายที่พวกอันเดดน่ารังเกียจกับเพื่อนฝั่ง Horde คอยขวางอยู่ ไปที่ Stormwind Keep เถอะ Lady Hoteshem รออยู่ในท้องพระโรง นางช่วยให้เจ้าไป Arathi Basin ได้" },
            { "105:1658362743:951284668 N 74:1590963719:1742867184", "Silverwing Sentinels ต้องการความช่วยเหลือเท่าที่จะหาได้ในการต่อสู้กับ Warsong Outriders {name} หากอยากช่วยพวกเขา ให้ไปคุยกับ Elfarran ที่ Stormwind Keep" },
            { "160:1314473836:312487075", "ถ้าตามหาครูฝึกดรูอิด ให้ไปเขต The Park ปกติ Theridan กับ Maldryn อยู่แถวบ่อน้ำจันทร์กลางเขต" },
            { "262:161352486:95689920", "พรานหรือ? ถ้าอย่างนั้นไปคุยกับ Thorfin Stoneshield ที่ Dwarven District\n\nอ้อ ฝากบอกเขาด้วยว่าถ้าข้าเหยียบมูลสัตว์เลี้ยงของเขาอีกครั้ง เขาจะได้สอนพรานคนอื่นจากหลังลูกกรงใน Stockade แน่!" },
            { "114:1672241355:1411838590", "อ้อ อยากเรียนรู้ศาสตร์เวทมนตร์หรือ? ไม่มีที่ไหนเหมาะไปกว่า Wizard's Sanctum ใน Mage Quarter แล้ว" },
            { "106:394326412:1036438931", "Laurena เป็นมหาปุโรหิตหญิงแห่ง Stormwind เจ้าจะพบนางที่ Cathedral of Light ใน Cathedral Square" },
            { "165:294325831:1118556579", "เฮอะ พวกโจรมีแต่ทำให้งานของเราใน Stormwind ยากขึ้น ข้าอยากลากทั้ง Osborne กับ Mathias ออกจาก Old Town แล้วจับโยนเข้า Stockade เสียจริง" },
            { "151:434454227:975322660", "วอร์ล็อกหรือ เอาเป็นว่าเจ้าไม่ได้ยินจากข้าละกัน แต่มีข่าวลือว่าคนพวกนั้นรวมตัวกันที่ร้านเหล้า The Slaughtered Lamb ใน Mage Quarter" },
            { "245:197281860:1682669702", "อยากฝึกหรือ? ข้าสอนได้ดีกว่าใครใน Stormwind แต่หน่วยยามมีกฎห้ามไว้ เจ้าคงต้องไปพึ่งพวกอดีตมือดีแถวค่ายทหารหรือ Pig and Whistle Tavern ใน Old Town" },
            { "222:684749793:1929112562", "มีร้านเล็ก ๆ ชื่อ Alchemy Needs ซ่อนอยู่ใน Mage Quarter ระหว่างทางคงเห็นร้านแปลก ๆ เต็มไปหมด เดินเลียบขอบนอกของเขตไว้ รับรองว่าเจอ" },
            { "229:371566747:2031088401", "อยู่ตรงนี้ยังไม่ได้กลิ่นควันจากเตาหลอมของคนแคระอีกหรือ? ถ้าอยากเรียนตีเหล็ก ให้ไปหา Therum Deepforge เขาอยู่ใน Dwarven District ทางเหนือของ Cathedral Square" },
            { "257:314959780:631527562", "มีพ่อครัวฝีมือดีอยู่ที่ Pig and Whistle Tavern ใน Old Town ข้าเคยดูเขาจับมีดทำอาหาร บอกกันสองคนนะ ข้าว่าเขาไม่ได้เป็นพ่อครัวมาตลอด แต่อย่าเข้าใจผิด ถ้ายังอยากเรียน เขาฝีมือดีที่สุดที่เรามี" },
            { "117:997913863:350640145", "อ้อ เจ้าตามหา Lucan Cordell เขาเปิดร้านอยู่ริม Mage Quarter ตรงทางไป Stockade" },
            { "252:1596801085:1269229813", "อ้อ พูดแล้วนึกขึ้นได้ ข้าต้องเอารองเท้าจรวดไปซ่อม ฝากไว้เป็นบทเรียนสหาย รองเท้าจรวดกับกริฟฟินไปด้วยกันไม่ได้\n\nแต่เจ้ามาถามทางนี่ ไปที่ Dwarven District เถอะ เจ้าจะพบ Lilliam Sparkspindle ทางด้านในของเขต" },
            { "253:2132266512:1368680579", "ไม่มีที่ไหนเหมาะกับการเรียนปฐมพยาบาลไปกว่าการฝึกกับ Shaina Fuller ที่ Cathedral of Light\n\nมองหาหลังคาสีเหลือง หรือยอดสูงของมหาวิหารที่เห็นได้จากแทบทุกที่ในเมือง" },
            { "214:1323330601:1092735995", "เจ้า Leland ตัวขี้เกียจ เอาแต่นั่งตกปลาอยู่บนท่าน้ำด้านนอก Trade District ทั้งวัน ข้าหวังว่าจะตกเก่งสมกับเวลาที่เสียไป ถ้าเจ้าอยากเรียนก็ลองไปคุยกับเขาดูสิ" },
            { "245:747842596:1146855364", "ไม่มีอะไรเทียบการสื่อสารกับธรรมชาติได้... อย่างน้อยพวกไนต์เอลฟ์ก็ว่าอย่างนั้น ข้าไม่ถนัดคุยกับดอกไม้ใบหญ้า แต่ Tannysa ช่วยเจ้าได้แน่ นางอยู่หน้าร้าน Alchemy Needs ใน Mage Quarter" },
            { "135:1399470638:1130006792", "สนใจงานเครื่องหนังหรือ? ถ้าอย่างนั้นไปคุยกับ Simon Tanner ใน Old Town เขาเปิดร้านชื่อ Protective Hide อยู่ที่นั่น" },
            { "280:1903682265:1966974687", "ก็ต้องพวกคนแคระนี่แหละที่ส่งผู้เชี่ยวชาญจาก Ironforge มาสอนเราขุดแร่ ถืออีเต้อแล้วสกัดหินจะยากตรงไหนกัน? แต่ไหน ๆ เขาก็มาแล้ว เจ้าน่าจะไปคุยกับเขา เขาชื่อ Gelman และอยู่ใน Dwarven District" },
            { "265:542751608:1365675714", "รู้ไหม ข้าแทงออร์คทะลุได้ ฟันโทรลล์เป็นชิ้น ๆ ก็ได้ แม้แต่สลักชื่อย่อของข้าบนสีข้างโอเกอร์ก็ยังได้ แต่พอให้ถลกหนังสัตว์ ข้าทำใจไม่ได้เสียอย่างนั้น\n\nถ้าเจ้าทนไหว ก็ไปหา Maris Granger ที่ Protective Hide ใน Old Town เถอะ" },
            { "254:750457866:1580032409", "ช่างตัดเย็บหรือ? อยู่แถวนี้นานหน่อย เดี๋ยวก็ได้ยินคนพูดถึง Georgio Bolero เขานำแฟชั่นมาหลายเดือนแล้ว ถ้าอยากเรียนกับเขา ไปที่ขอบนอกของ Mage Quarter" },
            { "101:2132925014:412043935", "อยู่ใน Trade District พลเมืองเอ๋ย เข้ามาจากประตู Stormwind แล้วเดินเกือบตรงไปเลย" },
            { "123:1243500032:1951429288", "ธนาคาร Stormwind อยู่ใน Trade District ทางตะวันตกเฉียงเหนือของประตูเมืองนิดเดียว มานี่ ข้าจะชี้ให้ดูในแผนที่" },
            { "266:2144969310:1160546073", "ใจไม่ถึงจะขี่กริฟฟินสินะ โชคดีที่เรามีทางเลือกที่เท้ายังติดพื้น... ก็เกือบตลอดแหละ นั่นคือ Deeprun Tram รถรางขนคนของพวกโนม หาได้ง่าย ๆ ทางด้านในของ Dwarven District" },
            { "234:2061404294:1033043169", "Stormwind มีร้านให้ดื่มตั้งหลายแห่ง แต่มีแห่งเดียวที่ค้างคืนได้ ไปที่ Gilded Rose ใน Trade District เถอะ ได้ยินว่าค่าห้องไม่แพงและผ้าปูเตียงก็สะอาด" },
            { "90:2072230604:1781125224", "ผู้ดูแลกริฟฟินอยู่บนกำแพงเมืองฝั่งตะวันออกเฉียงเหนือ ตรงจุดที่มองลงไปเห็น Valley of Heroes" },
            { "84:1387121008:1574942124", "ไปหา Aldwin Laughlin ที่ Stormwind Visitor's Center ใน Trade District ได้เลย" },
            { "119:696483522:1305128446", "มีตู้ไปรษณีย์อยู่ระหว่างธนาคาร Stormwind กับโรงเตี๊ยม The Gilded Rose ใน Trade District พอดี" },
            { "147:2122183401:1183727715", "คนที่เจ้าตามหาคือ Jenova Stoneshield ที่ Dwarven District นางรับดูแลสัตว์เลี้ยงของพรานระหว่างที่เจ้าของไปฝึกกับพ่อของนาง" },
            { "293:1698629639:1486496547", "จู่ ๆ ก็เป็น ‘ผู้พิทักษ์ Alliance’ ขึ้นมาแล้วหรือ?! ถ้าอย่างนั้นเจ้าคงอยากไป Champions' Hall ที่ Old Town แต่ถ้ายังไม่ได้เป็นนายทหาร เขาไม่ให้เข้า เจ้าคงต้องคุยกับ Officer Areyn ข้างนอก ไปได้แล้ว" },
            { "40:291002089:575715052", "เจ้าตามหาครูฝึกคลาสไหน?" },
            { "45:1430177360:2076810446", "เจ้าตามหาครูฝึกวิชาชีพอะไร?" },
            { "119:1206233441:1835427672", "ถ้าอย่างนั้นเจ้าต้องคุยกับ Thelman Slatefist เขาเข้าเฝ้าพระราชาอยู่ที่ Stormwind Keep" },
            { "184:1476697466:165597423", "เจ้าจะพบ Lady Hoteshem ในท้องพระโรง นางจะช่วยให้เจ้าไป Arathi Basin ที่ The League of Arathor ต้องการกำลังเสริมต่อสู้กับ The Defilers" },
            { "117:1172354082:1314768841", "ใช่แล้ว Silverwing Hold ต้องการความช่วยเหลือจากเจ้า ไปคุยกับ Elfarran ในท้องพระโรงที่ Stormwind Keep" },
            { "173:2146741898:1728258613", "เจ้าจะพบ Theridan หรือ Maldryn แถวบ่อน้ำจันทร์ในเขต The Park ไปทางฝั่งตะวันตกของ Stormwind เขตนี้อยู่เหนือเขตจอมเวทและอยู่ทางตะวันตกของ Cathedral Square" },
            { "241:623658039:1340315603", "Thorfin Stoneshield เดินทางมาจาก Ironforge เพื่อถ่ายทอดวิชาล่าสัตว์ให้เรา ถ้าเจ้าไม่ติดเรื่องควันคลุ้งใน Dwarven District ไปหาเขาที่บ้านทางตะวันออกเฉียงเหนือของเขตได้เลย" },
            { "140:1941323016:718192502", "พวกจอมเวทรวมตัวกันที่ Wizard's Sanctum ใน Mage Quarter หอคอยพวกเขาใหญ่โตจริง ๆ เห็นแล้วค่ายทหารของเราดูเป็นกระท่อมชาวนาไปเลย" },
            { "169:1935641493:147201015", "หากอยากเป็นพาลาดินผู้เก่งกาจ ไม่มีใครสอนได้ดีกว่า Lord Grayson Shadowbreaker เขาอยู่ที่ Cathedral of Light ใน Cathedral Square" },
            { "123:393473416:755027545", "Cathedral of Light ใน Cathedral Square เป็นที่พำนักของนักบวชแห่ง Stormwind เจ้าจะพบมหาปุโรหิตหญิง Laurena ที่นั่น" },
            { "124:2141896765:1738871496", "ถ้าอย่างนั้นต้องคุยกับ Osborne ใน Stormwind ไม่มีใครสอนวิชาลอบเร้นได้ดีกว่าเขา ไปหาเขาที่ Old Town" },
            { "202:1944041720:366757506", "อะไรนะ? ข้าไม่รู้จักครูฝึกวอร์ล็อกใน Stormwind สักคน\n\nแต่ว่า... มีคนเห็นร่องรอยปีศาจแถว The Slaughtered Lamb ใน Mage Quarter ลองไปดูแถวนั้นก็ได้" },
            { "155:1527351320:2062904572", "มักเจอนักรบที่ Pig and Whistle Tavern หรือที่ค่ายทหารใน Old Town แต่ข้าว่าไปดูที่ร้านเหล้าก่อนจะมีโอกาสเจอมากกว่า" },
            { "168:1337046922:1029193692", "ถ้าอยากเรียนเล่นแร่แปรธาตุ ใน Stormwind มีที่เดียวที่เจ้าต้องไป... ร้าน Alchemy Needs อยู่ตามแนวร้านค้ารอบนอกของ Mage Quarter" },
            { "157:1023564973:412422912", "คนแคระที่เจ้าควรคุยด้วยคือ Therum Deepforge ข้าว่าเขาเป็นหนึ่งในช่างตีเหล็กที่เก่งที่สุดแถวนี้ ไปหาเขาใจกลาง Dwarven District ได้เลย" },
            { "295:1957066278:520189790", "ถ้าอยากทำอาหารเก่ง ๆ ไปที่ Pig and Whistle Tavern ใน Old Town แล้วคุยกับ Stephen Ryback ไม่มีใครปรุงซี่โครงได้อร่อยเท่าเขา\n\nให้ตาย พูดแล้วอยากกินซี่โครงขึ้นชื่อของเขาขึ้นมาเลย แต่อย่าหวังว่าเขาจะสอนสูตรนั้นให้ล่ะ!" },
            { "122:168991300:941297198", "Lucan Cordell มีร้านเล็ก ๆ ริมคลองข้าง Stockade ข้ามั่นใจว่าเขาสอนศิลปะการเสริมมนตร์ให้เจ้าได้" },
            { "149:628577913:1530794751", "ครูฝึกวิศวกรรมประจำ Stormwind เป็นโนมหัวไวชื่อ Lilliam Sparkspindle เขาอยู่ด้านในของ Dwarven District" },
            { "142:1608492526:493365065", "Cathedral of Light เป็นศูนย์กลางวิชารักษาทุกแขนงของ Stormwind ไปหา Shaina Fuller ที่นั่น นางจะช่วยสอนวิชานี้ให้เจ้า" },
            { "279:849298999:1166295712", "ไม่มีอะไรดีเท่าการใช้เวลาทั้งวันตกปลาที่ Crystal Lake คนที่สอนข้าคือ Arnold Leland ปกติเขาอยู่บนท่าน้ำใน Canal District ตกปลาไปได้ทั้งวัน\n\nอ้อ เรื่องสัตว์ประหลาดในคลองที่เขาเล่าน่ะ อย่าไปเชื่อสักเรื่องเชียว" },
            { "72:2090090915:1256783437", "เจ้าจะพบ Tannysa ยืนอยู่หน้าร้าน Alchemy Needs ใน Mage Quarter" },
            { "126:935112752:1708365029", "อยากเรียนทำเครื่องหนังหรือ? Simon Tanner สอนเจ้าได้ ไปหาเขาที่ Protective Hide ใน Old Town" },
            { "153:1302264292:1825211620", "คนที่ควรคุยด้วยคือ Gelman Stonehand ข้าว่าเขามีบ้านอยู่ใน Dwarven District แต่จำที่แน่นอนไม่ได้ ลองไปดูแถวนั้นก่อน" },
            { "113:377356405:970398512", "ถ้าอยากเรียนถลกหนัง ให้ไป Old Town แล้วแวะร้าน Protective Hide" },
            { "125:296498462:1842927869", "Duncan's Textiles มีช่างตัดเย็บฝีมือดีที่สุดคนหนึ่งของ Stormwind ชื่อ Georgio Bolero มองหาร้านนี้ใน Mage Quarter" },
            { "48:1751809060:1716052876", "วิชาชาแมนหรือ? ที่นี่เราไม่สอนวิชานั้น ลองไปที่ Ironforge ดูสิ" },
            { "185:1807498793:813666402", "Stormwind Counting House อยู่ใกล้ประตูหน้าในเขตการค้าของ Stormwind พอเบื่อนับเงินแล้ว อย่าลืมแวะไปดื่มที่ Gilded Rose ล่ะ" },
            { "87:1820943571:863964498", "ไปที่ Mage Quarter แล้วหา Fyrenz Stargazer เขาอยู่ทางตะวันตกเฉียงเหนือของหอคอยจอมเวท" },
        },
    },
    [1976] = {
        name = "Stormwind City Patroller",
        lines = {
            { "133:2058852606:1367999946", "ถ้าต้องการฝากสัตว์เลี้ยงไว้ระหว่างฝึกตัวอื่น ไปคุยกับ Jenova Stoneshield ที่ Dwarven District เถอะ" },
            { "31:332017592:1003306482", "ต้องการให้ข้าชี้ทางไปไหน?" },
            { "217:1202580182:1320917283", "Woo Ping อึดเหลือเชื่อ ข้าเคยดูเขาฝึกใช้อาวุธหลายชั่วโมงติดกัน จบแล้วนึกสงสารหุ่นซ้อมเสียจริง ข้านึกไม่ออกเลยว่าใครจะสอนการต่อสู้ด้วยอาวุธได้ดีกว่าเขา" },
            { "41:99630854:2128042192", "เจ้าสนใจสนามรบแห่งไหน?" },
            { "138:1007643925:717505216", "กริฟฟินหรือ? ข้าไม่ค่อยชอบเจ้าพวกนี้นัก แต่ก็แล้วแต่คนละนะ\n\nเจ้าจะพบ Dungar Longdrink บนกำแพงเมืองฝั่ง Trade District" },
            { "131:1579755382:872878809", "อยากลองขี่กริฟฟินหรือ? Dungar เลี้ยงพวกมันไว้บนกำแพงเมืองฝั่ง Trade District อย่าลืมเกาะแน่น ๆ ล่ะ!" },
            { "165:1579876993:482203853", "อ้อ เจ้าตามหา Stormwind Visitor's Center สินะ พอเดินจาก Valley of Heroes ผ่านประตูหน้าเข้ามา ก็อยู่ตึกแรกทางซ้ายมือ" },
            { "86:1755551096:412201569", "เจ้าเป็นลูกหลานแห่งธรรมชาติสินะ ถ้าอย่างนั้นไปที่บ่อน้ำจันทร์ในเขต The Park ได้เลย" },
            { "184:1019180285:891164179", "ฟังดูเหมือนเจ้าต้องการคุยกับ Maginor Dumas! ปกติเขาอยู่ที่ Wizard's Sanctum ใน Mage Quarter แต่เจ้าพวกจอมเวทจะเปิดประตูมิติไปไหนเมื่อไร ใครจะไปรู้" },
            { "70:1228897223:1390942212", "ข้าแนะนำให้ไปดูที่ Cathedral of Light ใน Cathedral Square" },
            { "102:2136878040:1064128300", "ถ้าอยากตามหาพวกโจร ต้องไป Old Town อยู่มุมตะวันออกเฉียงเหนือของ Stormwind" },
            { "178:329592739:528842321", "ลองไปดูที่ค่ายทหารหรือร้าน Pig and Whistle Tavern ใน Old Town ถ้าแวะร้านเหล้าก็ลองชิมเบียร์ดี ๆ ของเขาด้วยล่ะ ข้าบอกเลยว่าเบียร์คนแคระต้องอาย" },
            { "108:1419067024:2118252711", "พ่อค้าอีกคนสินะ ตลาดประมูลอยู่ใน Trade District ห่างจากธนาคารไม่ไกล" },
            { "185:1676239868:1072471262", "Stormwind Counting House อยู่ใกล้ประตูหน้าใน Trade District ของ Stormwind นับเงินจนเบื่อเมื่อไรก็อย่าลืมแวะไปดื่มที่ Gilded Rose ล่ะ" },
            { "209:1357814927:244224787", "เคยได้ยินเรื่องรถรางแล้วสินะ นั่งสนุกอย่าบอกใคร! มันอยู่ด้านในสุดของ Dwarven District อ้อ อย่ายื่นแขนขาออกนอกรถตอนรถกำลังวิ่งล่ะ" },
            { "267:773300528:1162973153", "อา The Gilded Rose... ที่นอนขนปุยนุ่ม ๆ กับน้ำอุ่น ๆ แค่นึกถึงโรงเตี๊ยมก็อยากจะ... ::หาว:: โชคดีจังถ้าเจ้าจะไปที่นั่น มันอยู่ฝั่งตะวันตกของ Trade District... หมอนนุ่ม ๆ ผ้าห่มอุ่น ๆ... ::หาว::" },
            { "163:1398345684:1617218404", "อ้อ เจ้าตามหา Dungar Longdrink นี่เอง กริฟฟินของเขาเร็วเป็นอันดับต้น ๆ ในแถบนี้ของ Khaz Modan ไปหาเขาบนกำแพงเมืองฝั่ง Trade District ได้เลย" },
            { "182:1305844100:1757609898", "จะตั้งกิลด์หรือ? ขอให้โชคดีนะ!\n\nไปคุยกับ Aldwin Laughlin ที่ Stormwind Visitor's Center ใน Trade District พอเดินเข้ามาจาก Valley of Heroes ก็ถึงเลย" },
            { "222:955836489:231068528", "ข้าไม่รู้จริง ๆ ว่าทำได้อย่างไร ตู้ไปรษณีย์นั่นต้องเป็นประตูมิติหรืออะไรทำนองนั้นแน่ ข้าเห็นคนล้อมตู้ข้างธนาคารทั้งวัน หยิบทั้งดาบ โล่ สารพัดชุดเกราะออกมาจากกล่องเล็กแค่นั้น!" },
            { "245:676400897:898711382", "อาจารย์ Woo Ping เชี่ยวชาญอาวุธแทบทุกชนิดที่มนุษย์รู้จัก ฝีมือดาบของเขายิ่งร้ายกาจเป็นพิเศษ ถ้าอยากฝึก เขามักอยู่ที่ Weller's Arsenal คอยอาวุธล็อตใหม่มาส่ง" },
            { "256:597383050:710360537", "โอ้โฮ ก้าวหน้าขึ้นแล้วหรือ? เจ้าตามหา Champions' Hall สินะ อยู่สุดด้านตะวันออกเฉียงใต้ของ Old Town ถ้าเป็นนายทหารก็เข้าไปได้ หากยังไม่ถึงยศนั้นก็คุยกับ Officer Areyn ที่ยืนอยู่ข้างนอกได้ ขอให้โชคดี!" },
            { "28:1270891746:2089357014 N 138:1145541993:125411986", "ข้าก็อยากไปกับเจ้าเหมือนกัน {name} ไปที่ Stormwind Keep เจ้าจะพบ Thelman Slatefist ในท้องพระโรง เขาจะช่วยให้เจ้าเดินทางไป Alterac Valley ได้" },
            { "288:178638223:1047665319", "สิ่งที่ The League of Arathor พยายามทำใน Arathi Basin น่าชื่นชม เสียดายที่พวกอันเดดน่ารังเกียจกับเพื่อนฝั่ง Horde คอยขวางอยู่ ไปที่ Stormwind Keep เถอะ Lady Hoteshem รออยู่ในท้องพระโรง นางช่วยให้เจ้าไป Arathi Basin ได้" },
            { "105:1658362743:951284668 N 74:1590963719:1742867184", "Silverwing Sentinels ต้องการความช่วยเหลือเท่าที่จะหาได้ในการต่อสู้กับ Warsong Outriders {name} หากอยากช่วยพวกเขา ให้ไปคุยกับ Elfarran ที่ Stormwind Keep" },
            { "160:1314473836:312487075", "ถ้าตามหาครูฝึกดรูอิด ให้ไปเขต The Park ปกติ Theridan กับ Maldryn อยู่แถวบ่อน้ำจันทร์กลางเขต" },
            { "262:161352486:95689920", "พรานหรือ? ถ้าอย่างนั้นไปคุยกับ Thorfin Stoneshield ที่ Dwarven District\n\nอ้อ ฝากบอกเขาด้วยว่าถ้าข้าเหยียบมูลสัตว์เลี้ยงของเขาอีกครั้ง เขาจะได้สอนพรานคนอื่นจากหลังลูกกรงใน Stockade แน่!" },
            { "114:1672241355:1411838590", "อ้อ อยากเรียนรู้ศาสตร์เวทมนตร์หรือ? ไม่มีที่ไหนเหมาะไปกว่า Wizard's Sanctum ใน Mage Quarter แล้ว" },
            { "106:394326412:1036438931", "Laurena เป็นมหาปุโรหิตหญิงแห่ง Stormwind เจ้าจะพบนางที่ Cathedral of Light ใน Cathedral Square" },
            { "165:294325831:1118556579", "เฮอะ พวกโจรมีแต่ทำให้งานของเราใน Stormwind ยากขึ้น ข้าอยากลากทั้ง Osborne กับ Mathias ออกจาก Old Town แล้วจับโยนเข้า Stockade เสียจริง" },
            { "151:434454227:975322660", "วอร์ล็อกหรือ เอาเป็นว่าเจ้าไม่ได้ยินจากข้าละกัน แต่มีข่าวลือว่าคนพวกนั้นรวมตัวกันที่ร้านเหล้า The Slaughtered Lamb ใน Mage Quarter" },
            { "245:197281860:1682669702", "อยากฝึกหรือ? ข้าสอนได้ดีกว่าใครใน Stormwind แต่หน่วยยามมีกฎห้ามไว้ เจ้าคงต้องไปพึ่งพวกอดีตมือดีแถวค่ายทหารหรือ Pig and Whistle Tavern ใน Old Town" },
            { "222:684749793:1929112562", "มีร้านเล็ก ๆ ชื่อ Alchemy Needs ซ่อนอยู่ใน Mage Quarter ระหว่างทางคงเห็นร้านแปลก ๆ เต็มไปหมด เดินเลียบขอบนอกของเขตไว้ รับรองว่าเจอ" },
            { "229:371566747:2031088401", "อยู่ตรงนี้ยังไม่ได้กลิ่นควันจากเตาหลอมของคนแคระอีกหรือ? ถ้าอยากเรียนตีเหล็ก ให้ไปหา Therum Deepforge เขาอยู่ใน Dwarven District ทางเหนือของ Cathedral Square" },
            { "257:314959780:631527562", "มีพ่อครัวฝีมือดีอยู่ที่ Pig and Whistle Tavern ใน Old Town ข้าเคยดูเขาจับมีดทำอาหาร บอกกันสองคนนะ ข้าว่าเขาไม่ได้เป็นพ่อครัวมาตลอด แต่อย่าเข้าใจผิด ถ้ายังอยากเรียน เขาฝีมือดีที่สุดที่เรามี" },
            { "117:997913863:350640145", "อ้อ เจ้าตามหา Lucan Cordell เขาเปิดร้านอยู่ริม Mage Quarter ตรงทางไป Stockade" },
            { "252:1596801085:1269229813", "อ้อ พูดแล้วนึกขึ้นได้ ข้าต้องเอารองเท้าจรวดไปซ่อม ฝากไว้เป็นบทเรียนสหาย รองเท้าจรวดกับกริฟฟินไปด้วยกันไม่ได้\n\nแต่เจ้ามาถามทางนี่ ไปที่ Dwarven District เถอะ เจ้าจะพบ Lilliam Sparkspindle ทางด้านในของเขต" },
            { "253:2132266512:1368680579", "ไม่มีที่ไหนเหมาะกับการเรียนปฐมพยาบาลไปกว่าการฝึกกับ Shaina Fuller ที่ Cathedral of Light\n\nมองหาหลังคาสีเหลือง หรือยอดสูงของมหาวิหารที่เห็นได้จากแทบทุกที่ในเมือง" },
            { "214:1323330601:1092735995", "เจ้า Leland ตัวขี้เกียจ เอาแต่นั่งตกปลาอยู่บนท่าน้ำด้านนอก Trade District ทั้งวัน ข้าหวังว่าจะตกเก่งสมกับเวลาที่เสียไป ถ้าเจ้าอยากเรียนก็ลองไปคุยกับเขาดูสิ" },
            { "245:747842596:1146855364", "ไม่มีอะไรเทียบการสื่อสารกับธรรมชาติได้... อย่างน้อยพวกไนต์เอลฟ์ก็ว่าอย่างนั้น ข้าไม่ถนัดคุยกับดอกไม้ใบหญ้า แต่ Tannysa ช่วยเจ้าได้แน่ นางอยู่หน้าร้าน Alchemy Needs ใน Mage Quarter" },
            { "135:1399470638:1130006792", "สนใจงานเครื่องหนังหรือ? ถ้าอย่างนั้นไปคุยกับ Simon Tanner ใน Old Town เขาเปิดร้านชื่อ Protective Hide อยู่ที่นั่น" },
            { "280:1903682265:1966974687", "ก็ต้องพวกคนแคระนี่แหละที่ส่งผู้เชี่ยวชาญจาก Ironforge มาสอนเราขุดแร่ ถืออีเต้อแล้วสกัดหินจะยากตรงไหนกัน? แต่ไหน ๆ เขาก็มาแล้ว เจ้าน่าจะไปคุยกับเขา เขาชื่อ Gelman และอยู่ใน Dwarven District" },
            { "265:542751608:1365675714", "รู้ไหม ข้าแทงออร์คทะลุได้ ฟันโทรลล์เป็นชิ้น ๆ ก็ได้ แม้แต่สลักชื่อย่อของข้าบนสีข้างโอเกอร์ก็ยังได้ แต่พอให้ถลกหนังสัตว์ ข้าทำใจไม่ได้เสียอย่างนั้น\n\nถ้าเจ้าทนไหว ก็ไปหา Maris Granger ที่ Protective Hide ใน Old Town เถอะ" },
            { "254:750457866:1580032409", "ช่างตัดเย็บหรือ? อยู่แถวนี้นานหน่อย เดี๋ยวก็ได้ยินคนพูดถึง Georgio Bolero เขานำแฟชั่นมาหลายเดือนแล้ว ถ้าอยากเรียนกับเขา ไปที่ขอบนอกของ Mage Quarter" },
            { "101:2132925014:412043935", "อยู่ใน Trade District พลเมืองเอ๋ย เข้ามาจากประตู Stormwind แล้วเดินเกือบตรงไปเลย" },
            { "123:1243500032:1951429288", "ธนาคาร Stormwind อยู่ใน Trade District ทางตะวันตกเฉียงเหนือของประตูเมืองนิดเดียว มานี่ ข้าจะชี้ให้ดูในแผนที่" },
            { "266:2144969310:1160546073", "ใจไม่ถึงจะขี่กริฟฟินสินะ โชคดีที่เรามีทางเลือกที่เท้ายังติดพื้น... ก็เกือบตลอดแหละ นั่นคือ Deeprun Tram รถรางขนคนของพวกโนม หาได้ง่าย ๆ ทางด้านในของ Dwarven District" },
            { "234:2061404294:1033043169", "Stormwind มีร้านให้ดื่มตั้งหลายแห่ง แต่มีแห่งเดียวที่ค้างคืนได้ ไปที่ Gilded Rose ใน Trade District เถอะ ได้ยินว่าค่าห้องไม่แพงและผ้าปูเตียงก็สะอาด" },
            { "90:2072230604:1781125224", "ผู้ดูแลกริฟฟินอยู่บนกำแพงเมืองฝั่งตะวันออกเฉียงเหนือ ตรงจุดที่มองลงไปเห็น Valley of Heroes" },
            { "84:1387121008:1574942124", "ไปหา Aldwin Laughlin ที่ Stormwind Visitor's Center ใน Trade District ได้เลย" },
            { "119:696483522:1305128446", "มีตู้ไปรษณีย์อยู่ระหว่างธนาคาร Stormwind กับโรงเตี๊ยม The Gilded Rose ใน Trade District พอดี" },
            { "147:2122183401:1183727715", "คนที่เจ้าตามหาคือ Jenova Stoneshield ที่ Dwarven District นางรับดูแลสัตว์เลี้ยงของพรานระหว่างที่เจ้าของไปฝึกกับพ่อของนาง" },
            { "293:1698629639:1486496547", "จู่ ๆ ก็เป็น ‘ผู้พิทักษ์ Alliance’ ขึ้นมาแล้วหรือ?! ถ้าอย่างนั้นเจ้าคงอยากไป Champions' Hall ที่ Old Town แต่ถ้ายังไม่ได้เป็นนายทหาร เขาไม่ให้เข้า เจ้าคงต้องคุยกับ Officer Areyn ข้างนอก ไปได้แล้ว" },
            { "40:291002089:575715052", "เจ้าตามหาครูฝึกคลาสไหน?" },
            { "45:1430177360:2076810446", "เจ้าตามหาครูฝึกวิชาชีพอะไร?" },
            { "119:1206233441:1835427672", "ถ้าอย่างนั้นเจ้าต้องคุยกับ Thelman Slatefist เขาเข้าเฝ้าพระราชาอยู่ที่ Stormwind Keep" },
            { "184:1476697466:165597423", "เจ้าจะพบ Lady Hoteshem ในท้องพระโรง นางจะช่วยให้เจ้าไป Arathi Basin ที่ The League of Arathor ต้องการกำลังเสริมต่อสู้กับ The Defilers" },
            { "117:1172354082:1314768841", "ใช่แล้ว Silverwing Hold ต้องการความช่วยเหลือจากเจ้า ไปคุยกับ Elfarran ในท้องพระโรงที่ Stormwind Keep" },
            { "173:2146741898:1728258613", "เจ้าจะพบ Theridan หรือ Maldryn แถวบ่อน้ำจันทร์ในเขต The Park ไปทางฝั่งตะวันตกของ Stormwind เขตนี้อยู่เหนือเขตจอมเวทและอยู่ทางตะวันตกของ Cathedral Square" },
            { "241:623658039:1340315603", "Thorfin Stoneshield เดินทางมาจาก Ironforge เพื่อถ่ายทอดวิชาล่าสัตว์ให้เรา ถ้าเจ้าไม่ติดเรื่องควันคลุ้งใน Dwarven District ไปหาเขาที่บ้านทางตะวันออกเฉียงเหนือของเขตได้เลย" },
            { "140:1941323016:718192502", "พวกจอมเวทรวมตัวกันที่ Wizard's Sanctum ใน Mage Quarter หอคอยพวกเขาใหญ่โตจริง ๆ เห็นแล้วค่ายทหารของเราดูเป็นกระท่อมชาวนาไปเลย" },
            { "169:1935641493:147201015", "หากอยากเป็นพาลาดินผู้เก่งกาจ ไม่มีใครสอนได้ดีกว่า Lord Grayson Shadowbreaker เขาอยู่ที่ Cathedral of Light ใน Cathedral Square" },
            { "123:393473416:755027545", "Cathedral of Light ใน Cathedral Square เป็นที่พำนักของนักบวชแห่ง Stormwind เจ้าจะพบมหาปุโรหิตหญิง Laurena ที่นั่น" },
            { "124:2141896765:1738871496", "ถ้าอย่างนั้นต้องคุยกับ Osborne ใน Stormwind ไม่มีใครสอนวิชาลอบเร้นได้ดีกว่าเขา ไปหาเขาที่ Old Town" },
            { "202:1944041720:366757506", "อะไรนะ? ข้าไม่รู้จักครูฝึกวอร์ล็อกใน Stormwind สักคน\n\nแต่ว่า... มีคนเห็นร่องรอยปีศาจแถว The Slaughtered Lamb ใน Mage Quarter ลองไปดูแถวนั้นก็ได้" },
            { "155:1527351320:2062904572", "มักเจอนักรบที่ Pig and Whistle Tavern หรือที่ค่ายทหารใน Old Town แต่ข้าว่าไปดูที่ร้านเหล้าก่อนจะมีโอกาสเจอมากกว่า" },
            { "168:1337046922:1029193692", "ถ้าอยากเรียนเล่นแร่แปรธาตุ ใน Stormwind มีที่เดียวที่เจ้าต้องไป... ร้าน Alchemy Needs อยู่ตามแนวร้านค้ารอบนอกของ Mage Quarter" },
            { "157:1023564973:412422912", "คนแคระที่เจ้าควรคุยด้วยคือ Therum Deepforge ข้าว่าเขาเป็นหนึ่งในช่างตีเหล็กที่เก่งที่สุดแถวนี้ ไปหาเขาใจกลาง Dwarven District ได้เลย" },
            { "295:1957066278:520189790", "ถ้าอยากทำอาหารเก่ง ๆ ไปที่ Pig and Whistle Tavern ใน Old Town แล้วคุยกับ Stephen Ryback ไม่มีใครปรุงซี่โครงได้อร่อยเท่าเขา\n\nให้ตาย พูดแล้วอยากกินซี่โครงขึ้นชื่อของเขาขึ้นมาเลย แต่อย่าหวังว่าเขาจะสอนสูตรนั้นให้ล่ะ!" },
            { "122:168991300:941297198", "Lucan Cordell มีร้านเล็ก ๆ ริมคลองข้าง Stockade ข้ามั่นใจว่าเขาสอนศิลปะการเสริมมนตร์ให้เจ้าได้" },
            { "149:628577913:1530794751", "ครูฝึกวิศวกรรมประจำ Stormwind เป็นโนมหัวไวชื่อ Lilliam Sparkspindle เขาอยู่ด้านในของ Dwarven District" },
            { "142:1608492526:493365065", "Cathedral of Light เป็นศูนย์กลางวิชารักษาทุกแขนงของ Stormwind ไปหา Shaina Fuller ที่นั่น นางจะช่วยสอนวิชานี้ให้เจ้า" },
            { "279:849298999:1166295712", "ไม่มีอะไรดีเท่าการใช้เวลาทั้งวันตกปลาที่ Crystal Lake คนที่สอนข้าคือ Arnold Leland ปกติเขาอยู่บนท่าน้ำใน Canal District ตกปลาไปได้ทั้งวัน\n\nอ้อ เรื่องสัตว์ประหลาดในคลองที่เขาเล่าน่ะ อย่าไปเชื่อสักเรื่องเชียว" },
            { "72:2090090915:1256783437", "เจ้าจะพบ Tannysa ยืนอยู่หน้าร้าน Alchemy Needs ใน Mage Quarter" },
            { "126:935112752:1708365029", "อยากเรียนทำเครื่องหนังหรือ? Simon Tanner สอนเจ้าได้ ไปหาเขาที่ Protective Hide ใน Old Town" },
            { "153:1302264292:1825211620", "คนที่ควรคุยด้วยคือ Gelman Stonehand ข้าว่าเขามีบ้านอยู่ใน Dwarven District แต่จำที่แน่นอนไม่ได้ ลองไปดูแถวนั้นก่อน" },
            { "113:377356405:970398512", "ถ้าอยากเรียนถลกหนัง ให้ไป Old Town แล้วแวะร้าน Protective Hide" },
            { "125:296498462:1842927869", "Duncan's Textiles มีช่างตัดเย็บฝีมือดีที่สุดคนหนึ่งของ Stormwind ชื่อ Georgio Bolero มองหาร้านนี้ใน Mage Quarter" },
            { "48:1751809060:1716052876", "วิถีชาแมนหรือ? ที่นี่เขาไม่ฝึกกันหรอก ลองไปที่ Ironforge ดูสิ" },
        },
    },
    [267007] = {
        name = "Stormwind Harbor Guard",
        lines = {
            { "133:2058852606:1367999946", "ถ้าต้องการฝากสัตว์เลี้ยงไว้ระหว่างฝึกตัวอื่น ไปคุยกับ Jenova Stoneshield ที่ Dwarven District เถอะ" },
            { "31:332017592:1003306482", "ต้องการให้ข้าชี้ทางไปไหน?" },
            { "217:1202580182:1320917283", "Woo Ping อึดเหลือเชื่อ ข้าเคยดูเขาฝึกใช้อาวุธหลายชั่วโมงติดกัน จบแล้วนึกสงสารหุ่นซ้อมเสียจริง ข้านึกไม่ออกเลยว่าใครจะสอนการต่อสู้ด้วยอาวุธได้ดีกว่าเขา" },
            { "41:99630854:2128042192", "เจ้าสนใจสนามรบแห่งไหน?" },
            { "193:1219935351:560476450", "กรรไกรคมที่สุดกับมือที่เบาที่สุดอยู่ที่ร้าน Curls and Furls ใน Trade District นี่เอง ถ้ามีเวลาว่างและอยากเล็มผมสักหน่อย ก็ลองแวะไปดู" },
            { "87:1820943571:863964498", "ไปที่ Mage Quarter แล้วหา Fyrenz Stargazer เขาอยู่ทางตะวันตกเฉียงเหนือของหอคอยจอมเวทนิดเดียว" },
            { "151:1814265845:89612410", "จะไป Stormwind Harbor ให้เดินผ่านเขตคลองตรงระหว่าง Cathedral District กับ The Park\n\nเจ้ากำลังมองหาที่ไหนเป็นพิเศษหรือ?" },
            { "147:1183066643:1084324071", "Stormwind Harbor เป็นที่จอดกองเรืออันเกรียงไกรของเรา ท่าเรืออยู่ระหว่าง Cathedral District กับ The Park\n\nเจ้ากำลังมองหาที่ไหนเป็นพิเศษหรือ?" },
            { "45:1430177360:2076810446", "เจ้ากำลังหาครูฝึกวิชาชีพไหนอยู่?" },
            { "122:168991300:941297198", "Lucan Cordell มีร้านเล็ก ๆ ริมคลองข้าง Stockade ข้าแน่ใจว่าเขาสอนวิชาลงมนตร์ให้เจ้าได้" },
            { "266:2144969310:1160546073", "นั่งกริฟฟอนไม่ไหวสินะ โชคดีที่เรามีทางเลือกให้เจ้าเดินทางโดยเท้ายังติดพื้น... ก็ประมาณนั้นแหละ นั่นคือ Deeprun Tram รถรางขนคนของพวกโนม อยู่ลึกเข้าไปด้านใน Dwarven District พอดี" },
            { "113:377356405:970398512", "ถ้าอยากเรียนถลกหนัง ให้ไปที่ Old Town แล้วแวะร้าน Protective Hide" },
            { "245:747842596:1146855364", "ไม่มีอะไรเทียบการสื่อสารกับธรรมชาติได้... อย่างน้อยพวกไนต์เอลฟ์ก็ว่าอย่างนั้น ข้าไม่ถนัดคุยกับดอกไม้ใบหญ้า แต่ Tannysa ช่วยเจ้าได้แน่ นางอยู่หน้าร้าน Alchemy Needs ใน Mage Quarter" },
        },
    },
    [727] = {
        name = "Ironforge Mountaineer",
        lines = {
            { "30:1477893500:205206133", "อยากให้ข้าชี้ทางไปไหนล่ะ?" },
            { "44:1424376088:1891953739", "เจ้าตามหาครูฝึกคลาสไหนหรือ?" },
            { "49:1817888502:555179477", "เจ้าตามหาครูฝึกวิชาชีพอะไรหรือ?" },
            { "69:646298601:1130014985", "The Vault ที่ Ironforge เป็นธนาคารที่ใกล้ที่สุดในแถบนี้" },
            { "147:1503719693:628785167", "ผู้ดูแลกริฟฟินที่ใกล้ที่สุดอยู่ใน Ironforge แถว The Great Forge ถ้าอยากเดินทางด้วยกริฟฟิน เจ้าต้องไป Ironforge" },
            { "134:1948010831:293214496", "ถ้าต้องการเอกสารตั้งกิลด์ เจ้าต้องไป Ironforge แล้วแวะที่ Ironforge Visitor's Center" },
            { "142:203863742:621945650", "โอ้ หาโรงเตี๊ยมรึ? ไม่มีที่ไหนสู้ Thunderbrew Distillery ได้ จะพักก็พักเถอะ แต่อย่าลืมดื่มเบียร์สักแก้วสองแก้วตอนอยู่ที่นั่น" },
            { "155:190603450:488864068", "Shelby Stoneflint รับฝากสัตว์เลี้ยงให้พรานแถวนี้หลายตัว ถ้าอยากให้นางช่วยดูแลสัตว์เลี้ยง ไปหานางแถว Thunderbrew Distillery" },
            { "182:968413512:1990242005", "ถ้าถามข้า Grif ใช้เวลาอยู่กับสัตว์มากไปหน่อย แต่ก็ไม่มีใครรู้วิถีพรานดีเท่าเขา มองหาเขาด้านนอกโรงตีเหล็กใน Kharanos" },
            { "201:23207271:2142450350", "แน่ใจนะว่าไม่อยากฝึกเป็นนักรบ? เอาเถอะ ชีวิตเจ้าทั้งนั้นเวลาอยู่ในสนามรบ ถ้าอยากฝึกกระดิกนิ้วร่ายเวทจริง ๆ ก็ไปหา Magis Sparkmantle ที่ Thunderbrew Distillery" },
            { "163:1256008133:938542493", "อยากฝึกรึ? Azar Stronghammer ยินดีสอนวิชาให้พาลาดินรุ่นน้องอยู่เสมอ ลองไปหาเขาที่ Thunderbrew Distillery สิ" },
            { "156:772039144:1454848786", "รับรองว่าเจอ Maxan Anvol ดื่มอยู่ที่ Thunderbrew Distillery ลองไปดื่มสักแก้วแล้วถามเขาดูว่าจะสอนอะไรใหม่ ๆ ให้เจ้าไหม" },
            { "162:581564600:562536520", "ตามหา Hogral รึ? ไปดูที่ร้านเหล้าหรือยัง? โธ่ ถ้าจะหาโจร แถมเป็นคนแคระด้วย ก็ต้องเริ่มที่โรงเตี๊ยมสิ ไปดูเสียทีเถอะ" },
            { "189:753867964:292928261", "เวทแบบนั้นมีแต่จะนำเรื่องร้ายมาให้ ข้าไม่รู้ว่าทำไมถึงปล่อยให้ Grimrizz มาตั้งร้านด้านนอก Thunderbrew Distillery ได้ ไปอยู่ให้ห่างเขาไว้ เข้าใจไหม!" },
            { "175:1558271636:1799623284", "Granis Swiftaxe ดื่มจนปลายังยอมแพ้ แต่พอเหวี่ยงขวานก็ยังแม่นเหมือนเดิม ถ้าอยากฝึกกับเขา รีบไปหาตอนที่ยังฟังเขาพูดรู้เรื่องเถอะ" },
            { "111:267696588:318289215", "ได้ยินว่ามีร้านของพวกโนมใน Ironforge ที่เชี่ยวชาญเรื่องเล่นแร่แปรธาตุ ลองไปดูสิ" },
            { "191:1723990407:385731786", "อยู่ใน Kharanos ก็น่าจะได้ยินเสียง Tognus ตีทั่ง แต่ถ้าช่วงนี้เจ้ายังไม่ได้แคะขี้หู ก็ลองไปดูที่โรงตีเหล็กเอาเถอะ" },
            { "186:1466690279:548868702", "Gremlock ทำอาหารออกมาดีบ้างพลาดบ้าง แต่เขาก็มีสูตรอร่อยที่น่าเรียนอยู่ ไปคุยกับเขาที่ Thunderbrew Distillery ดูว่าจะสอนอะไรให้เจ้า" },
            { "147:1580319786:1914825374", "ถ้าอยากเรียนวิชาเสริมมนตร์ ลองไปดูใน Ironforge เถอะ คราวก่อนที่ข้าไปเหมือนจะเห็นร้านอยู่แถวผู้ดูแลกริฟฟิน" },
            { "237:982324754:2067285569", "Bronk ขันสกรูให้แน่นมามากจนข้าว่าสกรูในหัวเขาคงหลวมไปบ้างแล้ว เข้าใจที่ข้าหมายถึงนะ แต่เขายังคิดสร้างเครื่องกลพิสดารได้เก่งอยู่ดี ลองไปเยี่ยมเขาที่ Steelgrill's Depot สิ" },
            { "188:1448141745:1521172673", "วันก่อนข้าไปเจอเจ้าทร็อกตัวร้ายเข้า Thamner เพื่อนเก่าช่วยพันแผลให้ ตอนนี้ข้าหายดีเป็นปลิดทิ้งเลย! ข้ามั่นใจว่าเขายินดีสอนเจ้าทำผ้าพันแผลดี ๆ สักผืน" },
            { "185:927319661:1001394930", "แถวนี้มีที่ตกปลาอยู่ไม่กี่แห่ง Paxton รู้จักทุกแห่ง แถมคงรู้จักอีกสองสามที่ที่ไม่ยอมบอกเจ้าด้วย ลองไปหาเขาที่ Iceflow Lake ดูสิว่าเขาจะยอมบอกอะไรบ้าง" },
            { "101:1190939970:734282148", "ไม่มีใครสอนเก็บสมุนไพรให้เจ้าที่นี่หรอก ข้าว่าไป Ironforge น่าจะมีโอกาสเจอมากกว่า" },
            { "139:2063990853:959061446", "ถ้าจะหาช่างเครื่องหนัง ไป Ironforge มีโอกาสดีที่สุด ถ้าจำไม่ผิด มีร้านอยู่แถว The Great Forge น่าจะช่วยเจ้าได้" },
            { "146:1690585584:525209651", "หาคนขุดแร่รึ? ไม่ต้องถามว่ามีไหม พ่อหนุ่ม ถามแค่ว่าอยู่ที่ไหนก็พอ! เจ้าตามหา Yarr อยู่ ข้าว่าเขาคงหลบอยู่ที่ Steelgrill's Depot", variants = { { "146:740326649:723793935", "หาคนขุดแร่รึ? ไม่ต้องถามว่ามีไหม แม่สาว ถามแค่ว่าอยู่ที่ไหนก็พอ! เจ้าตามหา Yarr อยู่ ข้าว่าเขาคงหลบอยู่ที่ Steelgrill's Depot" } } },
            { "134:2028003364:630568788", "พวกช่างถลกหนังมักเอาหนังทั้งหมดไปตากให้แห้งใน Ironforge ลองไปดูสิว่าจะหาใครฝึกให้เจ้าได้บ้าง" },
            { "156:1859139494:2114675006", "แถวนี้หาช่างตัดเย็บยากหน่อย แต่ใน Ironforge มีช่างฝีมือดีอยู่หลายคน ลองไปถามยามที่นั่นดูสิ" },
            { "60:743119864:492199439", "ธนาคารที่ใกล้ที่สุดคือ The Vault ที่ Ironforge พ่อหนุ่ม", variants = { { "60:744131930:492467727", "ธนาคารที่ใกล้ที่สุดคือ The Vault ที่ Ironforge แม่สาว" } } },
            { "148:1094935534:837450424", "ผู้ดูแลกริฟฟินหาไม่ได้ทั่วไปใน Dun Morogh หรอก พ่อหนุ่ม ถ้าอยากขี่กริฟฟินไปไหนก็ต้องไป Ironforge", variants = { { "148:1002681457:726075506", "ผู้ดูแลกริฟฟินหาไม่ได้ทั่วไปใน Dun Morogh หรอก แม่สาว ถ้าอยากขี่กริฟฟินไปไหนก็ต้องไป Ironforge" } } },
            { "133:599829795:27135327", "เจ้าหน้าที่พวกนั้นอยู่ที่ Ironforge กันหมด ถ้าต้องการเอกสารตั้งกิลด์ ให้ไปที่ Ironforge Visitor's Center" },
            { "105:800156729:534908675", "ครอบครัว Thunderbrew เปิดโรงเตี๊ยมดี ๆ ใน Kharanos ใช้ชื่อตระกูลของพวกเขาเอง แวะดื่มเบียร์สักแก้วแล้วพักสักหน่อยสิ" },
            { "143:260027074:1270314487", "เอาละ พ่อหนุ่ม เจ้าจะพบ Shelby Stoneflint อยู่ด้านนอก Thunderbrew Distillery ใน Kharanos นางจะดูแลสัตว์เลี้ยงของเจ้าให้อย่างดี", variants = { { "143:1431636558:367784611", "เอาละ แม่สาว เจ้าจะพบ Shelby Stoneflint อยู่ด้านนอก Thunderbrew Distillery ใน Kharanos นางจะดูแลสัตว์เลี้ยงของเจ้าให้อย่างดี" } } },
            { "155:1388849290:352744201", "แถวนี้มีพรานอยู่คนเดียวที่ข้าจะแนะนำให้เจ้าไปคุยด้วย นั่นคือ Grif Wildheart เขายืนอยู่ด้านนอกโรงตีเหล็กใน Kharanos" },
            { "133:2072180113:1415433958", "มีจอมเวทอยู่ที่ Thunderbrew Distillery ที่อาจสอนคาถาใหม่ ๆ ให้เจ้าได้ ข้าว่าเขาชื่อ Magis Sparkmantle" },
            { "151:1123263462:2003898897", "อ้อ... พาลาดินรึ? โชคดีของเจ้าเลย พ่อหนุ่ม Azar Stronghammer กลับจากฝึกแล้ว ตอนนี้พักอยู่ที่ Thunderbrew Distillery ใน Kharanos", variants = { { "151:626523113:1164654915", "อ้อ... พาลาดินรึ? โชคดีของเจ้าเลย แม่สาว Azar Stronghammer กลับจากฝึกแล้ว ตอนนี้พักอยู่ที่ Thunderbrew Distillery ใน Kharanos" } } },
            { "134:158527011:425573524", "อ้อ ตามหานักบวชรึ? ถ้าอยากฝึกสักหน่อย รับรองว่าเจอ Maxan เพื่อนเก่าของข้าดื่มอยู่ที่ Thunderbrew Distillery" },
            { "191:999620884:220876587", "ถ้าอย่างนั้นเราก็กำลังตามหา Hogral Bakkan เหมือนกัน เขาเป็นคนแคระแท้ ๆ ไม่ช้าก็เร็วต้องไปดื่มเบียร์ที่ Thunderbrew Distillery เผลอ ๆ ตอนนี้ก็อยู่ที่นั่นแล้ว" },
            { "181:1031912695:1693374001", "วอร์ล็อก... ข้าไม่ชอบคนพวกนั้นเลย อย่าง Grimrizz ที่มาตั้งร้านด้านนอก Thunderbrew Distillery นั่นแหละ เบียร์ที่นั่นคงเสียรสเพราะเขาแน่! วอร์ล็อก... เฮอะ!" },
            { "163:1914865146:1599987448", "โฮ่! อย่างนี้ค่อยเข้าท่าหน่อย! ข้าพนันว่า Granis Swiftaxe สอนวิธีเหวี่ยงอาวุธให้เจ้าได้สักอย่างสองอย่าง ตอนนี้เขาอยู่ที่ Thunderbrew Distillery ใน Kharanos" },
            { "119:82927425:525916013", "ไม่มีนักเล่นแร่แปรธาตุแถว Dun Morogh หรอก ไปหาใน Ironforge ดีกว่า... ลองถามพวกโนมที่ Tinker Town ดู" },
            { "151:534516531:1874493201", "โฮ่! วิชานี้น่าเรียนจริง ๆ Tognus ตีทั่งหนักมือชนิดที่ไม่ค่อยได้เห็น ลองไปคุยกับเขาดูสิว่าจะสอนอะไรเจ้าได้บ้าง" },
            { "150:1665461468:580176132", "เบียร์ Thunderbrew สักแก้วกับอาหารฝีมือ Gremlock สักหน่อย ก็เป็นมื้อดี ๆ ได้เลย ถ้าอยากเป็นพ่อครัว เจ้าควรลองขอให้เขาสอนดู" },
            { "153:772400352:152125785", "เท่าที่ข้ารู้ แถว Dun Morogh ไม่มีนักเสริมมนตร์ ถ้าอยากเรียนวิชานี้ เจ้าต้องไป Ironforge" },
            { "160:249695739:1595258250", "ลองไปหา Bronk ที่ Steelgrill's Depot ดูสิ ถ้าไม่ได้ง่วนกับเครื่องกลแปลก ๆ เขาก็มักคุยกับคนขับเรื่องรถถังไอน้ำของพวกนั้น" },
            { "163:291947915:104339835", "ปฐมพยาบาลอาจทดแทนการรักษาของนักบวชไม่ได้ แต่ช่วยได้ยามคับขัน ข้าแนะนำให้ไปคุยกับ Thamner ที่ Thunderbrew Distillery แล้วเรียนจากเขาให้มากที่สุด" },
            { "147:30002782:1792548543", "แถวนี้ไม่ค่อยมีที่ให้ตกปลานัก แต่เท่าที่มีก็เสร็จ Paxton หมดแน่ เจ้าจะพบเขาตกปลาอยู่ที่ Iceflow Lake" },
            { "180:841626796:1657215589", "น่าทึ่งนะที่ดอกไม้เล็ก ๆ ยังทนหนาวใน Dun Morogh ได้... แต่แถวนี้หานักเก็บสมุนไพรไม่ได้หรอก ถ้าอยากเรียนวิชานี้ เจ้าต้องไป Ironforge" },
            { "183:720879830:286693846", "ถ้าอยากเรียนทำเครื่องหนัง เจ้าต้องเดินทางไป Ironforge ได้ยินว่ามีร้านดี ๆ แถว The Great Forge ที่สอนวิชานี้ได้" },
            { "162:1054958111:857116784", "คงไม่คิดว่าเมืองนี้จะไม่มีคนขุดแร่ประจำอยู่สักคนหรอกนะ? ปกติเจ้าจะพบ Yarr ที่ Steelgrill's Depot นอก Kharanos นิดเดียว" },
            { "127:1412587544:1700032995", "ใน Dun Morogh แถวนี้หาช่างถลกหนังไม่ได้หรอก พ่อหนุ่ม ถ้าอยากเรียน พวกเขาส่วนมากอยู่ใน Ironforge", variants = { { "127:111821696:612422450", "ใน Dun Morogh แถวนี้หาช่างถลกหนังไม่ได้หรอก แม่สาว ถ้าอยากเรียน พวกเขาส่วนมากอยู่ใน Ironforge" } } },
            { "151:427218723:1655341990", "อ้อ ช่วงนี้ Stonebrow ไม่ค่อยออกจาก Ironforge ถ้าอยากเรียนตัดเย็บ เจ้าต้องไปหาเขาที่ Ironforge นั่นแหละ" },
            { "126:846976642:222934800", "ที่ Dun Morogh นี่ไม่มีคนถลกหนังหรอก เจ้าหนุ่ม ส่วนมากอยู่ที่ Ironforge ถ้าอยากฝึกก็ไปที่นั่น" },
        },
    },
    [5595] = {
        name = "Ironforge Guard",
        lines = {
            { "30:1477893500:205206133", "อยากให้ข้าชี้ทางไปไหนล่ะ?" },
            { "44:1424376088:1891953739", "เจ้าตามหาครูฝึกคลาสไหนหรือ?" },
            { "49:1817888502:555179477", "เจ้าตามหาครูฝึกวิชาชีพอะไรหรือ?" },
            { "145:234846013:1322964342", "ธนาคารรึ? อ้อ เจ้าหมายถึง The Vault! ไม่มีที่ไหนเก็บของมีค่าได้ปลอดภัยกว่าที่นั่นแล้ว เดินจากทางเข้า Ironforge ไปทางตะวันออกเฉียงเหนือไม่ไกลก็ถึง" },
            { "303:191981257:645152102", "โอย รถราง รถราง... ใคร ๆ ก็อยากนั่งรถราง สมัยดี ๆ ที่ขี่กริฟฟินแล้วต้องกำอานสุดชีวิตตอนทะยานขึ้นฟ้ามันหายไปไหนหมดนะ?\n\nเฮอะ อยากนั่งก็ไปเถอะ รถรางอยู่ใน Tinker Town กับเครื่องกลประหลาดอื่น ๆ ของพวกโนม" },
            { "286:1011213023:1313465270", "อา ไม่มีอะไรเทียบการขี่กริฟฟินได้จริงไหม? พวกไนต์เอลฟ์จะเก็บฮิปโปกริฟฟ์ไว้ขี่เองก็เชิญ ข้าขอแค่กริฟฟินกับลมที่พัดผ่านเส้นผมก็พอ!\n\nเอาละ ข้าไม่รั้งเจ้าแล้ว ไปหา Gryth Thurden ทางฝั่งตะวันออกของ The Great Forge เขาจะจัดเที่ยวบินให้" },
            { "194:509123590:1304835565", "เอาละ ถ้าจะตั้งกิลด์ก็ต้องมีเอกสาร Jondor Steelbrow ช่วยเจ้าเริ่มเรื่องได้ เมื่อพร้อมแล้วไปหาเขาที่ Ironforge Visitor's Center" },
            { "253:1306733988:222911011", "ถ้าต้องการโรงเตี๊ยม ให้ไป The Stonefire Inn เลย อยู่ทางซ้ายมือเมื่อเดินเข้า Ironforge และอยู่ทางขวามือถ้ากำลังเดินออก\n\nอ้อ ถ้าไปทางนั้น ฝากบอกให้เขาเตรียมเบียร์สักเหยือกไว้ให้ข้าด้วย" },
            { "317:1104431430:538640244", "เฮอะ ตู้ไปรษณีย์... พักนี้ข้าได้แต่จดหมายขยะ!\n\nเพิ่มขนาดนั่น... ลดขนาดนี่... รีบติดต่อเดี๋ยวนี้ รับ Sword of Dragonslaying ฟรี ข้าต้องเปลี่ยนหมายเลขตู้ทุกสองเดือน!\n\nเตือนแล้วนะ ถ้าจะหาตู้ไปรษณีย์ มันอยู่ด้านนอก Stonefire Tavern" },
            { "151:1355065028:663986092", "ไปที่ Hall of Arms จะพบ Ulbrek Firehand ผู้ดูแลคอกสัตว์ของเรา เขาจะให้อาหารและดูแลสัตว์เลี้ยงของเจ้าเป็นอย่างดี" },
            { "208:1330403221:213630588", "อยากเรียนใช้อาวุธชนิดใหม่รึ? ถ้าอย่างนั้นไปคุยกับ Bixi หรือ Buliwyf ที่ร้านอาวุธ Timberline Arms เถอะ พ่อหนุ่ม สองคนนั้นรู้เรื่องอาวุธตั้งแต่ขวานยัน... เอ่อ... ดาบสองมือ", variants = { { "208:1452090510:1105614162", "อยากเรียนใช้อาวุธชนิดใหม่รึ? ถ้าอย่างนั้นไปคุยกับ Bixi หรือ Buliwyf ที่ร้านอาวุธ Timberline Arms เถอะ แม่สาว สองคนนั้นรู้เรื่องอาวุธตั้งแต่ขวานยัน... เอ่อ... ดาบสองมือ" } } },
            { "217:1684113098:237635440", "อา Alterac Valley ข้ามีความทรงจำดี ๆ ที่นั่นเยอะเลยนะ <ถอนหายใจ> ข้าไปด้วยไม่ได้ แต่ทำให้ข้าภูมิใจด้วยล่ะ! ถ้าจะไปที่นั่น ให้คุยกับ Glordrum Steelbeard ที่ Hall of Arms ใน Ironforge นี่เอง" },
            { "125:1486560915:840025570 N 43:2140454593:725781", "The League of Arathor กำลังพยายามยึดดินแดนบรรพบุรุษใน Arathi Basin คืนจากพวก Forsaken ถ้าอยากช่วยพวกเขา {name} ไปคุยกับ Donal Osgood ที่ Hall of Arms" },
            { "234:955802418:131483330", "สำหรับข้า ได้สู้กับ Horde เมื่อไรก็สนุกเมื่อนั้น โดยเฉพาะถ้าเป็นพวกออร์ค ที่ Warsong Gulch มีศึกให้สู้เหลือเฟือแน่ ไปคุยกับ Lylandris ที่ Hall of Arms เถอะ นางจะจัดการให้เจ้าได้ไป" },
            { "195:2081097530:838248906", "เจ้ามีแววจะเป็นพรานฝีมือดีหรือเปล่า? เวลาจะเป็นเครื่องพิสูจน์เอง พ่อหนุ่ม แต่อย่าเพิ่งไปยิงแอปเปิลบนหัวใครจนกว่าจะได้คุยกับ Regnus ที่ Hall of Arms ล่ะ", variants = { { "194:1744689223:1033414917", "เจ้ามีแววจะเป็นพรานฝีมือดีหรือเปล่า? เวลาจะเป็นเครื่องพิสูจน์เอง แม่สาว แต่อย่าเพิ่งไปยิงแอปเปิลบนหัวใครจนกว่าจะได้คุยกับ Regnus ที่ Hall of Arms ล่ะ" } } },
            { "191:293313382:1357395099", "ถ้าอยากฝึกศาสตร์เวทมนตร์ ไปที่ Hall of Mysteries ทางเหนือของประตู Ironforge ได้เลย รับรองว่าเจอ Juli Stormkettle ก้มหน้าอ่านหนังสืออยู่ที่นั่น" },
            { "172:1528456817:1683807423", "อ้อ Brandur Ironhammer เพื่อนเก่าของข้า เขาให้คำแนะนำที่เจ้าตามหาได้แน่ พ่อหนุ่ม เจ้าจะพบเขาที่ Hall of Mysteries ทางเหนือของประตู Ironforge", variants = { { "172:91599166:940745542", "อ้อ Brandur Ironhammer เพื่อนเก่าของข้า เขาให้คำแนะนำที่เจ้าตามหาได้แน่ แม่สาว เจ้าจะพบเขาที่ Hall of Mysteries ทางเหนือของประตู Ironforge" } } },
            { "260:106309295:709975991", "อา ไม่มีใครรักษาอาการเจ็บป่วยได้ดีเท่านักบวชหรอก แน่นอนว่าเบียร์เต็มแก้วก็ช่วยได้หลายอาการ แต่ข้าว่า Braenna Flintcrag คงไม่สอนหมักเบียร์ เจ้าคงต้องไปเรียนวิชานักบวชที่ Hall of Mysteries แทน" },
            { "262:797884234:9215977", "พวกโจรทั้งหลายไปชุมนุมกันที่ The Forlorn Cavern ทางเหนือของประตู Ironforge ข้าพนันว่าเจ้าจะพบ Fenthwick ที่นั่น เขาคงกำลังนับเหรียญจากถุงเงินที่ล้วงมาอีกใบ สักวันข้าจะจับเขาให้ได้!\n\nระหว่างนี้ข้าจะจับตาดูเจ้าด้วย พ่อหนุ่ม", variants = { { "262:798896300:9484265", "พวกโจรทั้งหลายไปชุมนุมกันที่ The Forlorn Cavern ทางเหนือของประตู Ironforge ข้าพนันว่าเจ้าจะพบ Fenthwick ที่นั่น เขาคงกำลังนับเหรียญจากถุงเงินที่ล้วงมาอีกใบ สักวันข้าจะจับเขาให้ได้!\n\nระหว่างนี้ข้าจะจับตาดูเจ้าด้วย แม่สาว" } } },
            { "318:1201882980:547097948", "วอร์ล็อกรึ... ถ้าคิดจะทำเรื่องพรรค์นั้นแถวนี้ ก็ล่ามปีศาจของเจ้าไว้ให้ดี พ่อหนุ่ม ข้าไม่ชอบปีศาจ แต่ชอบเอาขวานฟันพวกมัน เข้าใจไหม?\n\nทีนี้อย่ามากวนข้า ไปที่ The Forlorn Cavern โน่น วอร์ล็อก Thistleheart อยู่ที่นั่น", variants = { { "319:794816785:1422513669", "วอร์ล็อกรึ... ถ้าคิดจะทำเรื่องพรรค์นั้นแถวนี้ ก็ล่ามปีศาจของเจ้าไว้ให้ดี แม่สาว ข้าไม่ชอบปีศาจ แต่ชอบเอาขวานฟันพวกมัน เข้าใจไหม?\n\nทีนี้อย่ามากวนข้า ไปที่ The Forlorn Cavern โน่น วอร์ล็อก Thistleheart อยู่ที่นั่น" } } },
            { "314:1974662035:1183656210", "Kelstrum ทั้งปากมากทั้งขี้โอ่ แถมยังเป็นนักรบฝีมือดีที่สุดคนหนึ่งที่เจ้าจะได้พบอีก!\n\nข้าบอกเลยว่าถ้าอยากฝึกวิถีนักรบ ก็ต้องคุยกับเขา ข้ามั่นใจว่าเขาอยู่ที่ Hall of Arms ทางตะวันออกของประตู Ironforge" },
            { "195:1996065930:885786210", "ตามหาครูสอนเล่นแร่แปรธาตุรึ? ข้าเพิ่งกลับมาจากที่นั่นเอง เจ้าจะพบคุณ Berryfizz ที่ Tinker Town ตรงที่พวกโนมมารวมตัวกัน\n\n::ถอนหายใจ:: ...ทำไมนะ ทำไมข้าไม่เลือกยาสีฟ้า" },
            { "289:1657042801:1375843734", "เจ้าถามจริง ๆ รึว่าช่างตีเหล็กอยู่ไหน? ไม่เคยได้ยินชื่อ The Great Forge หรือไง!? ช่างตีเหล็กฝีมือดีที่สุดของเรารวมตัวกันตีอาวุธกับชุดเกราะที่นั่น!\n\nอยู่ใจกลาง Ironforge พอดี และเป็นที่ที่เจ้าจะพบ Bengus Deepforge หนึ่งในช่างตีเหล็กที่เก่งที่สุดของเรา" },
            { "280:1454653902:1499919007", "โฮ่! Daryl Riknussun ทำอาหารเก่งจริง ๆ! เขาทำชิลีเผ็ดร้อนจนเอาไปอบเหล็กได้เลย ข้าว่าเขาไม่สอนสูตรนั้นหรอก แต่ช่วยให้เจ้าทำอาหารเก่งขึ้นได้แน่ ไปหาเขาที่ Bronze Kettle ทางฝั่งตะวันออกเฉียงเหนือของ The Great Forge" },
            { "271:561322280:895893295", "โอย! คิดให้ดีก่อนจะเอาอะไรไปเสริมมนตร์นะ พ่อหนุ่ม ข้าเคยให้ลงมนตร์เหยือกไม่ให้หกสักหยด ทีนี้ดื่มจากเหยือกไม่ได้เลย ช่างน่าเศร้า!\n\nจำคำข้าไว้ตอนไปหา Gimble เขาอยู่ที่ร้านติดกับผู้ดูแลกริฟฟินที่ The Great Forge", variants = { { "271:491539787:137484522", "โอย! คิดให้ดีก่อนจะเอาอะไรไปเสริมมนตร์นะ แม่สาว ข้าเคยให้ลงมนตร์เหยือกไม่ให้หกสักหยด ทีนี้ดื่มจากเหยือกไม่ได้เลย ช่างน่าเศร้า!\n\nจำคำข้าไว้ตอนไปหา Gimble เขาอยู่ที่ร้านติดกับผู้ดูแลกริฟฟินที่ The Great Forge" } } },
            { "288:1798750860:1841036363", "อ้อ เจ้าตามหา Springspindle Fizzlegear สินะ โนมตัวเล็กกับสิ่งประดิษฐ์ของเขานี่นะ... ข้าบอกไว้ก่อน ถ้าจะไปร้านเขาใน Tinker Town เก็บมือไว้กับตัว อย่าไปลูบแกะกลของเขาเด็ดขาด!\n\nแกะระเบิดได้... จะสร้างของแบบนั้นไปทำไมกัน!?" },
            { "209:385292726:748267937", "ปฐมพยาบาลรึ? ข้าว่าเจ้าดูไม่ได้บาดเจ็บอะไร แต่ถ้าอยากเรียนจริง ๆ ต้องเรียนจาก Nissa Firestone ไปหานางที่ร้าน The Ironforge Physician แถว The Great Forge" },
            { "247:1596793420:124407312", "ข้าเคยได้ยิน Grimnur เล่าว่าตกได้ดาบ หรือเป็นปลาดาบหว่า? ให้ตายเถอะ Grimnur เล่าเรื่องตกปลาไว้เยอะจนข้าจำสับสนไปหมด ไปหาเขาที่ The Forlorn Cavern แล้วให้เขาเล่าเองเถอะว่าตกได้อะไร" },
            { "233:946757197:934180834", "อ้อ อยากหัดเด็ดดอกเดซีรึ? ฮ่า! ข้าแค่หยอกเล่น พ่อหนุ่ม\n\nเป็นวิชาชีพที่ดีเชียวละ Reyna Stonebranch สอนวิธีให้เจ้าได้ นางทำงานที่ Ironforge Physician ฝั่งใต้ของ The Great Forge", variants = { { "230:1957756300:1137815005", "อ้อ อยากหัดเด็ดดอกเดซีรึ? ฮ่า! ข้าแค่หยอกเล่น แม่สาว\n\nเป็นวิชาชีพที่ดีเชียวละ Reyna Stonebranch สอนวิธีให้เจ้าได้ นางทำงานที่ Ironforge Physician ฝั่งใต้ของ The Great Forge" } } },
            { "183:466031541:1935945793", "แน่ใจนะว่าไม่อยากเป็นช่างตีเหล็ก? ถ้าใจเจ้าอยู่ที่งานเครื่องหนัง ก็ไปคุยกับ Fimble Finespindle ที่ร้านของเขาทางฝั่งตะวันตกเฉียงเหนือของ The Great Forge" },
            { "184:1364107509:1654391027", "โอ้โฮ! เจ้ามาถูกที่แล้วถ้าจะเรียนขุดแร่ พ่อหนุ่ม Geofram Bouldertoe อยู่ที่ Deepmountain Mining Guild จะหาครูที่ดีกว่าเขาไม่ได้แล้ว", variants = { { "185:1413118327:501017548", "โอ้โฮ! เจ้ามาถูกที่แล้วถ้าจะเรียนขุดแร่ แม่สาว Geofram Bouldertoe อยู่ที่ Deepmountain Mining Guild จะหาครูที่ดีกว่าเขาไม่ได้แล้ว" } } },
            { "260:1921001123:1457585915", "ถลกหนังรึ? ดูท่าเจ้าจะถลกได้แค่หนังหัวเข่าตัวเองล่ะมั้ง! ฮ่า! ไปหา Balthus Stoneflayer เถอะ เขาจะสอนวิธีถลกหนังสัตว์ให้ถูกต้อง อยู่ที่ Finespindle's Leather Goods ฝั่งเหนือของ The Great Forge" },
            { "320:176799151:1569781166", "เจ้าอาจยังไม่รู้ว่า Jormund นอกจากเย็บผ้าเก่งแล้วยังเป็นนักปราบยักษ์ด้วย! เขาคงบังเอิญได้ยินพวกข้านั่งเล่าเรื่องกัน เพราะจู่ ๆ เขาก็ตะโกนว่าเขาฆ่าได้เจ็ดตัวในการฟาดทีเดียว!\n\nลองแวะไปหาเขาที่ร้านฝั่งเหนือของ The Great Forge แล้วถามดูว่าเขาจะเล่าให้ฟังไหม" },
            { "138:435392349:1230944589", "ตลาดประมูลอยู่ไหนรึ? อยู่ติดประตู Ironforge ตอนเดินเข้ามาในเมืองของเรานี่เอง ตรงข้าม The Vault เลย" },
            { "222:1244055059:536033307", "มีสมบัติใหม่อยากเก็บให้ปลอดภัยรึ? เอาไปฝากกับครอบครัว Stonemantle ที่ The Vault เถอะ\n\nThe Vault อยู่ทางตะวันออกเฉียงเหนือของทางเข้า Ironforge แค่ระยะขว้างค้อนถึง" },
            { "171:317960761:975811901", "ใช่ ใคร ๆ ก็อยากนั่งรถราง สนุกสุดเหวี่ยงเชียวละ ถ้าจะไปขึ้นรถราง มันอยู่ใน Tinker Town ทางตะวันออกของประตู Ironforge นิดเดียว" },
            { "192:540591285:348172442", "อยากลองขี่กริฟฟินแล้วรึ? เรื่องนั้นต้องไปหา Gryth Thurden\n\nเขาอยู่ฝั่งตะวันออกของ The Great Forge กลาง Ironforge" },
            { "186:1319159323:680592146", "ถ้าคิดจะตั้งกิลด์ ต้องไปคุยกับ Jondor Steelbrow ที่ Ironforge Visitor's Center ก่อน เดินไปทางตะวันออกเฉียงใต้จากประตู Ironforge ก็เจอ" },
            { "239:983263532:1954385526", "โรงเตี๊ยมรึ? อ้อ อยากดื่มเบียร์ชั้นดีของ Ironforge สินะ ไปที่ The Stonefire Tavern เถอะ\n\nอยู่ทางซ้ายมือเมื่อเดินเข้า Ironforge และอยู่ทางขวามือถ้ากำลังเดินออก" },
            { "101:639486868:1784119801", "มีตู้ไปรษณีย์อยู่แถว The Stonefire Tavern ทางเหนือของประตู Ironforge นิดเดียว" },
            { "180:27583902:1134281077", "Ulbrek Firehand จริงจังกับการดูแลสัตว์มาก ถ้าอยากฝากสัตว์เลี้ยงสักตัวสองตัว เขามักอยู่กับพวกพรานที่ Hall of Arms" },
            { "208:1380211591:1664290492", "ถ้านับ Bixi กับ Buliwyf รวมกัน คงเหลืออาวุธไม่กี่ชนิดที่ทั้งคู่ยังไม่เคยใช้ฟันหรือทุบออร์ค ถ้าอยากฝึก ไปหาพวกเขาที่ร้านอาวุธ Timberline Arms" },
            { "46:65519046:850074971", "อือ แล้วเจ้าตามหาสนามรบไหนล่ะ?" },
            { "266:613306684:897731754", "ว่าไง พ่อหนุ่ม คิดว่าตัวเองพร้อมจะปกป้อง Alliance จาก Horde ใน Alterac Valley รึ? ถ้าอย่างนั้นไปคุยกับ Glordrum Steelbeard ของเราที่ Ironforge นี่เอง เขาคงกำลังวางแผนรบอยู่ที่โต๊ะยุทธการใน Hall of Arms", variants = { { "266:337385907:566232732", "ว่าไง แม่สาว คิดว่าตัวเองพร้อมจะปกป้อง Alliance จาก Horde ใน Alterac Valley รึ? ถ้าอย่างนั้นไปคุยกับ Glordrum Steelbeard ของเราที่ Ironforge นี่เอง เขาคงกำลังวางแผนรบอยู่ที่โต๊ะยุทธการใน Hall of Arms" } } },
            { "168:1400446869:1104045015", "พวกมนุษย์ต้องการความช่วยเหลือจากเจ้าในการสู้กับ Forsaken ที่ Arathi Basin ไปคุยกับ Donal Osgood ตัวแทนของพวกเขาที่ Hall of Arms" },
            { "106:1799610774:1270605003", "Warsong Gulch รึ? ถ้าอย่างนั้นไปคุยกับ Lylandris คนงามที่ Hall of Arms เถอะ" },
            { "185:157564223:1517733424", "วันก่อนข้าได้ยิน Regnus Thundergranite คุยโวใน Hall of Arms ว่าได้ของที่ระลึกจากการล่าชิ้นใหม่ไปประดับห้อง ถ้าอยากฝึกกับพรานฝีมือดี ก็ต้องไปหา Regnus นี่แหละ" },
            { "193:2041335891:656457457", "แม่หนูจอมเวทตัวเล็กชื่อ Bink ที่ Hall of Mysteries น่าจะช่วยเจ้าได้ทุกเรื่องที่เกี่ยวกับเวทมนตร์\n\nHall of Mysteries อยู่ทางเหนือของประตู Ironforge นิดเดียว" },
            { "127:405514485:341892872", "คนที่เจ้าควรไปหาคือ Brandur Ironhammer เขาอยู่ใน Hall of Mysteries ทางเหนือของประตู Ironforge" },
            { "213:1188244196:681488559", "อ้อ Braenna Flintcrag มือของนางราวกับมีมนตร์วิเศษ ถ้าเป็นเรื่องวิชานักบวชต้องไปหา Braenna\n\nจากประตู Ironforge เดินขึ้นเหนือไปที่ Hall of Mysteries เจ้าจะพบนางที่นั่น" },
            { "199:520191080:1814568095", "ทำไมเจ้าถึงอยากใช้บริการคนพวกนั้นล่ะ? แค่เจ้าโจร Hulfdan Blackbeard ที่ The Forlorn Cavern ก็สร้างเรื่องให้เราพอแล้ว ข้าต้องคอยจับตาดูเจ้าด้วยรึ?" },
            { "222:1195439602:1495544134", "จะไปหาพวกชอบเก็บตัวหม่น ๆ ที่ไหนได้ดีกว่ามุมมืดของ Ironforge ที่ชื่อ The Forlorn Cavern ล่ะ ชื่อนี้เหมาะจริง ๆ เจ้าจะเจอ Thistleheart ที่นั่นแน่ คงกำลังอัญเชิญสิ่งมีชีวิตชั่วร้ายสักอย่างมารับใช้เขาอยู่" },
            { "184:337299770:1559352459", "โฮ่! อยากฝึกวิถีนักรบรึ? Kelstrum Stonebreaker จะฝึกเจ้าจนรู้ว่าตัวเองมีฝีมือแค่ไหน! เดินไปที่ Hall of Arms ทางตะวันออกของประตู Ironforge ได้เลย" },
            { "143:149249744:650576770", "ตามหาครูสอนเล่นแร่แปรธาตุรึ? ข้าเพิ่งกลับมาจากที่นั่นเอง เจ้าจะพบคุณ Berryfizz ที่ Tinker Town ตรงที่พวกโนมมารวมตัวกัน" },
            { "218:1668031396:2137815707", "เจ้ามาถูกที่แล้ว พ่อหนุ่ม คนจากทั่วโลกมาฝึกเป็นช่างตีเหล็กที่นี่ เจ้าจะพบ Bengus Deepforge ตีเหล็กอยู่บนทั่งข้าง The Great Forge กลางเมืองของเรานี่เอง", variants = { { "218:294625006:491547364", "เจ้ามาถูกที่แล้ว แม่สาว คนจากทั่วโลกมาฝึกเป็นช่างตีเหล็กที่นี่ เจ้าจะพบ Bengus Deepforge ตีเหล็กอยู่บนทั่งข้าง The Great Forge กลางเมืองของเรานี่เอง" } } },
            { "215:856624436:321057998", "หาครูสอนทำอาหารรึ? งั้นไปที่ Bronze Kettle ทางฝั่งตะวันออกเฉียงเหนือของ The Great Forge เถอะ Daryl Riknussun จะสอนทำอาหารรสเยี่ยม กินแล้วมีเรี่ยวแรงขึ้นมาแน่!" },
            { "209:1997674332:56479577", "อ้อ ถ้าอยากเรียนวิชาเสริมมนตร์ คนที่เจ้าต้องการคือ Gimble Thistlefuzz เขาอยู่ที่ร้าน Thistlefuzz Arcanery ติดกับผู้ดูแลกริฟฟินที่ The Great Forge" },
            { "189:1504225687:173058025", "สนใจวิชาประดิษฐ์เครื่องกลรึ? ถ้าอย่างนั้นไปหา Springspindle Fizzlegear ที่ Tinker Town\n\nจากประตู Ironforge เดินไปทางตะวันออก หรือจะเดินตามเสียงระเบิดไปก็ได้" },
            { "177:1611838433:1103625106", "ปฐมพยาบาลเป็นทักษะที่มีค่ามาก ครูฝึกของเราชื่อ Nissa Firestone นางสอนวิธีให้เจ้าได้ มองหานางที่ Ironforge Physician ฝั่งใต้ของ The Great Forge" },
            { "200:1202358200:105279846", "Grimnur Stonebrand อาจเล่าเกินจริงเรื่องปลาตัวที่หลุดเบ็ด แต่เขาก็ยังเป็นนักตกปลาฝีมือดีที่สุดคนหนึ่งแถวนี้ เขาเปิดร้านชื่อ Traveling Fisherman อยู่ใน The Forlorn Cavern" },
            { "191:2024095083:599989838", "ดอกไม้ เมล็ดพืช อะไรทำนองนั้นรึ? เป็นเรื่องที่ Reyna Stonebranch เชี่ยวชาญ เจ้าจะพบนางดูแลต้นไม้อยู่ที่ Ironforge Physician ฝั่งใต้ของ The Great Forge" },
            { "132:1561362078:806640836", "Fimble Finespindle เปิดร้านอยู่ทางฝั่งตะวันตกเฉียงเหนือของ The Great Forge ข้าพนันว่าเขาสอนให้เจ้าทำชุดเกราะดี ๆ ได้" },
            { "253:914187484:1169688452", "ที่นี่มีครูฝึกขุดแร่ไหมรึ? เจ้าคิดว่าตัวเองอยู่ที่ไหนกัน!?\n\nเจ้าจะพบหนึ่งในนักขุดแร่ที่เก่งที่สุดใน Dun Morogh ที่ Deepmountain Mining Guild ฝั่งเหนือของ The Great Forge ที่นั่น Geofram Bouldertoe จะสอนศิลปะการขุดแร่ที่แท้จริงให้เจ้า" },
            { "191:1701704022:1487761627", "ถ้าอยากเรียนถลกหนังต้องไปหา Balthus Stoneflayer อะไรที่ถลกหนังได้ เขาสอนวิธีให้เจ้าได้หมด ไปที่ Finespindle's Leather Goods ฝั่งเหนือของ The Great Forge ได้เลย" },
            { "182:124632248:383962568", "Jormund Stonebrow มีพรสวรรค์เรื่องเข็มกับด้ายจริง ๆ ถ้าอยากฝึก เจ้าจะพบเขาที่ Stonebrow's Clothier ฝั่งเหนือของ The Great Forge" },
            { "119:1716560999:482921556 C 37:1862444015:1745222965", "พวกผู้หยั่งรู้ที่ยึดวิถีเก่าน่ะรึ? รู้จักสิ ไปแถวแอ่งน้ำใน The Forlorn Cavern เจ้าจะเจอ Eldrun Stormbreaker ครูฝึก{class}ของผู้ผูกพันกับเหล่าธาตุ" },
            { "270:775802937:1093086005", "โธ่! ระวังให้ดีว่าจะเอาอะไรไปเสริมมนตร์นะ เจ้าหนุ่ม ข้าให้เขาเสริมมนตร์แก้วเบียร์จะได้ไม่หกสักหยด แต่ทีนี้ดื่มจากแก้วไม่ได้เลย! น่าเศร้าจริง ๆ\n\nจำคำข้าไว้ตอนไปหา Gimble ล่ะ ร้านเขาอยู่ข้างครูฝึกกริฟฟอนที่ Great Forge" },
            { "232:855948924:1739242183", "อ้อ อยากหัดเก็บดอกเดซีหรือ? ฮ่า! ข้าแค่ล้อเล่นน่า เจ้าหนุ่ม\n\nเป็นวิชาชีพที่ดีทีเดียว Reyna Stonebranch สอนเจ้าได้ นางทำงานอยู่ที่ Ironforge Physician ด้านใต้ของ The Great Forge" },
            { "207:699697172:1077321303", "กำลังหาคนสอนใช้อาวุธชนิดใหม่หรือ? ไปคุยกับ Bixi หรือ Buliwyf ที่ร้านอาวุธ Timberline Arms เถอะ เจ้าหนุ่ม สองคนนั้นรู้อาวุธตั้งแต่ขวานไปจนถึง... เอ่อ... ดาบสองมือยาว" },
            { "117:1999701727:300011253", "ไม่ต้องห่วง ร้านตัดผมอยู่ทางตะวันตกเฉียงเหนือของทางเข้า Ironforge นิดเดียว\n\nประเดี๋ยวพวกเขาก็แต่งให้เจ้าดูเนี้ยบขึ้นเอง!" },
            { "317:1051063157:658874667", "วอร์ล็อกหรือ... ถ้าเจ้าคิดจะใช้วิชาแถวนี้ ก็ล่ามพวกปีศาจของเจ้าไว้ให้ดีล่ะ เจ้าหนุ่ม ข้าไม่ชอบปีศาจ แต่ชอบเอาขวานฟันพวกมัน เข้าใจไหม?\n\nทีนี้ก็เลิกกวนข้าแล้วไปที่ The Forlorn Cavern เสีย เจ้าจะพบ Thistleheart วอร์ล็อกคนนั้นที่นั่น" },
        },
    },
    [12996] = {
        name = "Mounted Ironforge Mountaineer",
        lines = {
            { "30:1477893500:205206133", "อยากให้ข้าชี้ทางไปไหนล่ะ?" },
            { "44:1424376088:1891953739", "เจ้าตามหาครูฝึกคลาสไหนหรือ?" },
            { "49:1817888502:555179477", "เจ้าตามหาครูฝึกวิชาชีพอะไรหรือ?" },
            { "145:234846013:1322964342", "ธนาคารรึ? อ้อ เจ้าหมายถึง The Vault! ไม่มีที่ไหนเก็บของมีค่าได้ปลอดภัยกว่าที่นั่นแล้ว เดินจากทางเข้า Ironforge ไปทางตะวันออกเฉียงเหนือไม่ไกลก็ถึง" },
            { "303:191981257:645152102", "โอย รถราง รถราง... ใคร ๆ ก็อยากนั่งรถราง สมัยดี ๆ ที่ขี่กริฟฟินแล้วต้องกำอานสุดชีวิตตอนทะยานขึ้นฟ้ามันหายไปไหนหมดนะ?\n\nเฮอะ อยากนั่งก็ไปเถอะ รถรางอยู่ใน Tinker Town กับเครื่องกลประหลาดอื่น ๆ ของพวกโนม" },
            { "286:1011213023:1313465270", "อา ไม่มีอะไรเทียบการขี่กริฟฟินได้จริงไหม? พวกไนต์เอลฟ์จะเก็บฮิปโปกริฟฟ์ไว้ขี่เองก็เชิญ ข้าขอแค่กริฟฟินกับลมที่พัดผ่านเส้นผมก็พอ!\n\nเอาละ ข้าไม่รั้งเจ้าแล้ว ไปหา Gryth Thurden ทางฝั่งตะวันออกของ The Great Forge เขาจะจัดเที่ยวบินให้" },
            { "194:509123590:1304835565", "เอาละ ถ้าจะตั้งกิลด์ก็ต้องมีเอกสาร Jondor Steelbrow ช่วยเจ้าเริ่มเรื่องได้ เมื่อพร้อมแล้วไปหาเขาที่ Ironforge Visitor's Center" },
            { "253:1306733988:222911011", "ถ้าต้องการโรงเตี๊ยม ให้ไป The Stonefire Inn เลย อยู่ทางซ้ายมือเมื่อเดินเข้า Ironforge และอยู่ทางขวามือถ้ากำลังเดินออก\n\nอ้อ ถ้าไปทางนั้น ฝากบอกให้เขาเตรียมเบียร์สักเหยือกไว้ให้ข้าด้วย" },
            { "317:1104431430:538640244", "เฮอะ ตู้ไปรษณีย์... พักนี้ข้าได้แต่จดหมายขยะ!\n\nเพิ่มขนาดนั่น... ลดขนาดนี่... รีบติดต่อเดี๋ยวนี้ รับ Sword of Dragonslaying ฟรี ข้าต้องเปลี่ยนหมายเลขตู้ทุกสองเดือน!\n\nเตือนแล้วนะ ถ้าจะหาตู้ไปรษณีย์ มันอยู่ด้านนอก Stonefire Tavern" },
            { "151:1355065028:663986092", "ไปที่ Hall of Arms จะพบ Ulbrek Firehand ผู้ดูแลคอกสัตว์ของเรา เขาจะให้อาหารและดูแลสัตว์เลี้ยงของเจ้าเป็นอย่างดี" },
            { "208:1330403221:213630588", "อยากเรียนใช้อาวุธชนิดใหม่รึ? ถ้าอย่างนั้นไปคุยกับ Bixi หรือ Buliwyf ที่ร้านอาวุธ Timberline Arms เถอะ พ่อหนุ่ม สองคนนั้นรู้เรื่องอาวุธตั้งแต่ขวานยัน... เอ่อ... ดาบสองมือ", variants = { { "208:1452090510:1105614162", "อยากเรียนใช้อาวุธชนิดใหม่รึ? ถ้าอย่างนั้นไปคุยกับ Bixi หรือ Buliwyf ที่ร้านอาวุธ Timberline Arms เถอะ แม่สาว สองคนนั้นรู้เรื่องอาวุธตั้งแต่ขวานยัน... เอ่อ... ดาบสองมือ" } } },
            { "217:1684113098:237635440", "อา Alterac Valley ข้ามีความทรงจำดี ๆ ที่นั่นเยอะเลยนะ <ถอนหายใจ> ข้าไปด้วยไม่ได้ แต่ทำให้ข้าภูมิใจด้วยล่ะ! ถ้าจะไปที่นั่น ให้คุยกับ Glordrum Steelbeard ที่ Hall of Arms ใน Ironforge นี่เอง" },
            { "125:1486560915:840025570 N 43:2140454593:725781", "The League of Arathor กำลังพยายามยึดดินแดนบรรพบุรุษใน Arathi Basin คืนจากพวก Forsaken ถ้าอยากช่วยพวกเขา {name} ไปคุยกับ Donal Osgood ที่ Hall of Arms" },
            { "234:955802418:131483330", "สำหรับข้า ได้สู้กับ Horde เมื่อไรก็สนุกเมื่อนั้น โดยเฉพาะถ้าเป็นพวกออร์ค ที่ Warsong Gulch มีศึกให้สู้เหลือเฟือแน่ ไปคุยกับ Lylandris ที่ Hall of Arms เถอะ นางจะจัดการให้เจ้าได้ไป" },
            { "195:2081097530:838248906", "เจ้ามีแววจะเป็นพรานฝีมือดีหรือเปล่า? เวลาจะเป็นเครื่องพิสูจน์เอง พ่อหนุ่ม แต่อย่าเพิ่งไปยิงแอปเปิลบนหัวใครจนกว่าจะได้คุยกับ Regnus ที่ Hall of Arms ล่ะ", variants = { { "194:1744689223:1033414917", "เจ้ามีแววจะเป็นพรานฝีมือดีหรือเปล่า? เวลาจะเป็นเครื่องพิสูจน์เอง แม่สาว แต่อย่าเพิ่งไปยิงแอปเปิลบนหัวใครจนกว่าจะได้คุยกับ Regnus ที่ Hall of Arms ล่ะ" } } },
            { "191:293313382:1357395099", "ถ้าอยากฝึกศาสตร์เวทมนตร์ ไปที่ Hall of Mysteries ทางเหนือของประตู Ironforge ได้เลย รับรองว่าเจอ Juli Stormkettle ก้มหน้าอ่านหนังสืออยู่ที่นั่น" },
            { "172:1528456817:1683807423", "อ้อ Brandur Ironhammer เพื่อนเก่าของข้า เขาให้คำแนะนำที่เจ้าตามหาได้แน่ พ่อหนุ่ม เจ้าจะพบเขาที่ Hall of Mysteries ทางเหนือของประตู Ironforge", variants = { { "172:91599166:940745542", "อ้อ Brandur Ironhammer เพื่อนเก่าของข้า เขาให้คำแนะนำที่เจ้าตามหาได้แน่ แม่สาว เจ้าจะพบเขาที่ Hall of Mysteries ทางเหนือของประตู Ironforge" } } },
            { "260:106309295:709975991", "อา ไม่มีใครรักษาอาการเจ็บป่วยได้ดีเท่านักบวชหรอก แน่นอนว่าเบียร์เต็มแก้วก็ช่วยได้หลายอาการ แต่ข้าว่า Braenna Flintcrag คงไม่สอนหมักเบียร์ เจ้าคงต้องไปเรียนวิชานักบวชที่ Hall of Mysteries แทน" },
            { "262:797884234:9215977", "พวกโจรทั้งหลายไปชุมนุมกันที่ The Forlorn Cavern ทางเหนือของประตู Ironforge ข้าพนันว่าเจ้าจะพบ Fenthwick ที่นั่น เขาคงกำลังนับเหรียญจากถุงเงินที่ล้วงมาอีกใบ สักวันข้าจะจับเขาให้ได้!\n\nระหว่างนี้ข้าจะจับตาดูเจ้าด้วย พ่อหนุ่ม", variants = { { "262:798896300:9484265", "พวกโจรทั้งหลายไปชุมนุมกันที่ The Forlorn Cavern ทางเหนือของประตู Ironforge ข้าพนันว่าเจ้าจะพบ Fenthwick ที่นั่น เขาคงกำลังนับเหรียญจากถุงเงินที่ล้วงมาอีกใบ สักวันข้าจะจับเขาให้ได้!\n\nระหว่างนี้ข้าจะจับตาดูเจ้าด้วย แม่สาว" } } },
            { "318:1201882980:547097948", "วอร์ล็อกรึ... ถ้าคิดจะทำเรื่องพรรค์นั้นแถวนี้ ก็ล่ามปีศาจของเจ้าไว้ให้ดี พ่อหนุ่ม ข้าไม่ชอบปีศาจ แต่ชอบเอาขวานฟันพวกมัน เข้าใจไหม?\n\nทีนี้อย่ามากวนข้า ไปที่ The Forlorn Cavern โน่น วอร์ล็อก Thistleheart อยู่ที่นั่น", variants = { { "319:794816785:1422513669", "วอร์ล็อกรึ... ถ้าคิดจะทำเรื่องพรรค์นั้นแถวนี้ ก็ล่ามปีศาจของเจ้าไว้ให้ดี แม่สาว ข้าไม่ชอบปีศาจ แต่ชอบเอาขวานฟันพวกมัน เข้าใจไหม?\n\nทีนี้อย่ามากวนข้า ไปที่ The Forlorn Cavern โน่น วอร์ล็อก Thistleheart อยู่ที่นั่น" } } },
            { "314:1974662035:1183656210", "Kelstrum ทั้งปากมากทั้งขี้โอ่ แถมยังเป็นนักรบฝีมือดีที่สุดคนหนึ่งที่เจ้าจะได้พบอีก!\n\nข้าบอกเลยว่าถ้าอยากฝึกวิถีนักรบ ก็ต้องคุยกับเขา ข้ามั่นใจว่าเขาอยู่ที่ Hall of Arms ทางตะวันออกของประตู Ironforge" },
            { "195:1996065930:885786210", "ตามหาครูสอนเล่นแร่แปรธาตุรึ? ข้าเพิ่งกลับมาจากที่นั่นเอง เจ้าจะพบคุณ Berryfizz ที่ Tinker Town ตรงที่พวกโนมมารวมตัวกัน\n\n::ถอนหายใจ:: ...ทำไมนะ ทำไมข้าไม่เลือกยาสีฟ้า" },
            { "289:1657042801:1375843734", "เจ้าถามจริง ๆ รึว่าช่างตีเหล็กอยู่ไหน? ไม่เคยได้ยินชื่อ The Great Forge หรือไง!? ช่างตีเหล็กฝีมือดีที่สุดของเรารวมตัวกันตีอาวุธกับชุดเกราะที่นั่น!\n\nอยู่ใจกลาง Ironforge พอดี และเป็นที่ที่เจ้าจะพบ Bengus Deepforge หนึ่งในช่างตีเหล็กที่เก่งที่สุดของเรา" },
            { "280:1454653902:1499919007", "โฮ่! Daryl Riknussun ทำอาหารเก่งจริง ๆ! เขาทำชิลีเผ็ดร้อนจนเอาไปอบเหล็กได้เลย ข้าว่าเขาไม่สอนสูตรนั้นหรอก แต่ช่วยให้เจ้าทำอาหารเก่งขึ้นได้แน่ ไปหาเขาที่ Bronze Kettle ทางฝั่งตะวันออกเฉียงเหนือของ The Great Forge" },
            { "271:561322280:895893295", "โอย! คิดให้ดีก่อนจะเอาอะไรไปเสริมมนตร์นะ พ่อหนุ่ม ข้าเคยให้ลงมนตร์เหยือกไม่ให้หกสักหยด ทีนี้ดื่มจากเหยือกไม่ได้เลย ช่างน่าเศร้า!\n\nจำคำข้าไว้ตอนไปหา Gimble เขาอยู่ที่ร้านติดกับผู้ดูแลกริฟฟินที่ The Great Forge", variants = { { "271:491539787:137484522", "โอย! คิดให้ดีก่อนจะเอาอะไรไปเสริมมนตร์นะ แม่สาว ข้าเคยให้ลงมนตร์เหยือกไม่ให้หกสักหยด ทีนี้ดื่มจากเหยือกไม่ได้เลย ช่างน่าเศร้า!\n\nจำคำข้าไว้ตอนไปหา Gimble เขาอยู่ที่ร้านติดกับผู้ดูแลกริฟฟินที่ The Great Forge" } } },
            { "288:1798750860:1841036363", "อ้อ เจ้าตามหา Springspindle Fizzlegear สินะ โนมตัวเล็กกับสิ่งประดิษฐ์ของเขานี่นะ... ข้าบอกไว้ก่อน ถ้าจะไปร้านเขาใน Tinker Town เก็บมือไว้กับตัว อย่าไปลูบแกะกลของเขาเด็ดขาด!\n\nแกะระเบิดได้... จะสร้างของแบบนั้นไปทำไมกัน!?" },
            { "209:385292726:748267937", "ปฐมพยาบาลรึ? ข้าว่าเจ้าดูไม่ได้บาดเจ็บอะไร แต่ถ้าอยากเรียนจริง ๆ ต้องเรียนจาก Nissa Firestone ไปหานางที่ร้าน The Ironforge Physician แถว The Great Forge" },
            { "247:1596793420:124407312", "ข้าเคยได้ยิน Grimnur เล่าว่าตกได้ดาบ หรือเป็นปลาดาบหว่า? ให้ตายเถอะ Grimnur เล่าเรื่องตกปลาไว้เยอะจนข้าจำสับสนไปหมด ไปหาเขาที่ The Forlorn Cavern แล้วให้เขาเล่าเองเถอะว่าตกได้อะไร" },
            { "233:946757197:934180834", "อ้อ อยากหัดเด็ดดอกเดซีรึ? ฮ่า! ข้าแค่หยอกเล่น พ่อหนุ่ม\n\nเป็นวิชาชีพที่ดีเชียวละ Reyna Stonebranch สอนวิธีให้เจ้าได้ นางทำงานที่ Ironforge Physician ฝั่งใต้ของ The Great Forge", variants = { { "230:1957756300:1137815005", "อ้อ อยากหัดเด็ดดอกเดซีรึ? ฮ่า! ข้าแค่หยอกเล่น แม่สาว\n\nเป็นวิชาชีพที่ดีเชียวละ Reyna Stonebranch สอนวิธีให้เจ้าได้ นางทำงานที่ Ironforge Physician ฝั่งใต้ของ The Great Forge" } } },
            { "183:466031541:1935945793", "แน่ใจนะว่าไม่อยากเป็นช่างตีเหล็ก? ถ้าใจเจ้าอยู่ที่งานเครื่องหนัง ก็ไปคุยกับ Fimble Finespindle ที่ร้านของเขาทางฝั่งตะวันตกเฉียงเหนือของ The Great Forge" },
            { "184:1364107509:1654391027", "โอ้โฮ! เจ้ามาถูกที่แล้วถ้าจะเรียนขุดแร่ พ่อหนุ่ม Geofram Bouldertoe อยู่ที่ Deepmountain Mining Guild จะหาครูที่ดีกว่าเขาไม่ได้แล้ว", variants = { { "185:1413118327:501017548", "โอ้โฮ! เจ้ามาถูกที่แล้วถ้าจะเรียนขุดแร่ แม่สาว Geofram Bouldertoe อยู่ที่ Deepmountain Mining Guild จะหาครูที่ดีกว่าเขาไม่ได้แล้ว" } } },
            { "260:1921001123:1457585915", "ถลกหนังรึ? ดูท่าเจ้าจะถลกได้แค่หนังหัวเข่าตัวเองล่ะมั้ง! ฮ่า! ไปหา Balthus Stoneflayer เถอะ เขาจะสอนวิธีถลกหนังสัตว์ให้ถูกต้อง อยู่ที่ Finespindle's Leather Goods ฝั่งเหนือของ The Great Forge" },
            { "320:176799151:1569781166", "เจ้าอาจยังไม่รู้ว่า Jormund นอกจากเย็บผ้าเก่งแล้วยังเป็นนักปราบยักษ์ด้วย! เขาคงบังเอิญได้ยินพวกข้านั่งเล่าเรื่องกัน เพราะจู่ ๆ เขาก็ตะโกนว่าเขาฆ่าได้เจ็ดตัวในการฟาดทีเดียว!\n\nลองแวะไปหาเขาที่ร้านฝั่งเหนือของ The Great Forge แล้วถามดูว่าเขาจะเล่าให้ฟังไหม" },
            { "138:435392349:1230944589", "ตลาดประมูลอยู่ไหนรึ? อยู่ติดประตู Ironforge ตอนเดินเข้ามาในเมืองของเรานี่เอง ตรงข้าม The Vault เลย" },
            { "222:1244055059:536033307", "มีสมบัติใหม่อยากเก็บให้ปลอดภัยรึ? เอาไปฝากกับครอบครัว Stonemantle ที่ The Vault เถอะ\n\nThe Vault อยู่ทางตะวันออกเฉียงเหนือของทางเข้า Ironforge แค่ระยะขว้างค้อนถึง" },
            { "171:317960761:975811901", "ใช่ ใคร ๆ ก็อยากนั่งรถราง สนุกสุดเหวี่ยงเชียวละ ถ้าจะไปขึ้นรถราง มันอยู่ใน Tinker Town ทางตะวันออกของประตู Ironforge นิดเดียว" },
            { "192:540591285:348172442", "อยากลองขี่กริฟฟินแล้วรึ? เรื่องนั้นต้องไปหา Gryth Thurden\n\nเขาอยู่ฝั่งตะวันออกของ The Great Forge กลาง Ironforge" },
            { "186:1319159323:680592146", "ถ้าคิดจะตั้งกิลด์ ต้องไปคุยกับ Jondor Steelbrow ที่ Ironforge Visitor's Center ก่อน เดินไปทางตะวันออกเฉียงใต้จากประตู Ironforge ก็เจอ" },
            { "239:983263532:1954385526", "โรงเตี๊ยมรึ? อ้อ อยากดื่มเบียร์ชั้นดีของ Ironforge สินะ ไปที่ The Stonefire Tavern เถอะ\n\nอยู่ทางซ้ายมือเมื่อเดินเข้า Ironforge และอยู่ทางขวามือถ้ากำลังเดินออก" },
            { "101:639486868:1784119801", "มีตู้ไปรษณีย์อยู่แถว The Stonefire Tavern ทางเหนือของประตู Ironforge นิดเดียว" },
            { "180:27583902:1134281077", "Ulbrek Firehand จริงจังกับการดูแลสัตว์มาก ถ้าอยากฝากสัตว์เลี้ยงสักตัวสองตัว เขามักอยู่กับพวกพรานที่ Hall of Arms" },
            { "208:1380211591:1664290492", "ถ้านับ Bixi กับ Buliwyf รวมกัน คงเหลืออาวุธไม่กี่ชนิดที่ทั้งคู่ยังไม่เคยใช้ฟันหรือทุบออร์ค ถ้าอยากฝึก ไปหาพวกเขาที่ร้านอาวุธ Timberline Arms" },
            { "46:65519046:850074971", "อือ แล้วเจ้าตามหาสนามรบไหนล่ะ?" },
            { "266:613306684:897731754", "ว่าไง พ่อหนุ่ม คิดว่าตัวเองพร้อมจะปกป้อง Alliance จาก Horde ใน Alterac Valley รึ? ถ้าอย่างนั้นไปคุยกับ Glordrum Steelbeard ของเราที่ Ironforge นี่เอง เขาคงกำลังวางแผนรบอยู่ที่โต๊ะยุทธการใน Hall of Arms", variants = { { "266:337385907:566232732", "ว่าไง แม่สาว คิดว่าตัวเองพร้อมจะปกป้อง Alliance จาก Horde ใน Alterac Valley รึ? ถ้าอย่างนั้นไปคุยกับ Glordrum Steelbeard ของเราที่ Ironforge นี่เอง เขาคงกำลังวางแผนรบอยู่ที่โต๊ะยุทธการใน Hall of Arms" } } },
            { "168:1400446869:1104045015", "พวกมนุษย์ต้องการความช่วยเหลือจากเจ้าในการสู้กับ Forsaken ที่ Arathi Basin ไปคุยกับ Donal Osgood ตัวแทนของพวกเขาที่ Hall of Arms" },
            { "106:1799610774:1270605003", "Warsong Gulch รึ? ถ้าอย่างนั้นไปคุยกับ Lylandris คนงามที่ Hall of Arms เถอะ" },
            { "185:157564223:1517733424", "วันก่อนข้าได้ยิน Regnus Thundergranite คุยโวใน Hall of Arms ว่าได้ของที่ระลึกจากการล่าชิ้นใหม่ไปประดับห้อง ถ้าอยากฝึกกับพรานฝีมือดี ก็ต้องไปหา Regnus นี่แหละ" },
            { "193:2041335891:656457457", "แม่หนูจอมเวทตัวเล็กชื่อ Bink ที่ Hall of Mysteries น่าจะช่วยเจ้าได้ทุกเรื่องที่เกี่ยวกับเวทมนตร์\n\nHall of Mysteries อยู่ทางเหนือของประตู Ironforge นิดเดียว" },
            { "127:405514485:341892872", "คนที่เจ้าควรไปหาคือ Brandur Ironhammer เขาอยู่ใน Hall of Mysteries ทางเหนือของประตู Ironforge" },
            { "213:1188244196:681488559", "อ้อ Braenna Flintcrag มือของนางราวกับมีมนตร์วิเศษ ถ้าเป็นเรื่องวิชานักบวชต้องไปหา Braenna\n\nจากประตู Ironforge เดินขึ้นเหนือไปที่ Hall of Mysteries เจ้าจะพบนางที่นั่น" },
            { "199:520191080:1814568095", "ทำไมเจ้าถึงอยากใช้บริการคนพวกนั้นล่ะ? แค่เจ้าโจร Hulfdan Blackbeard ที่ The Forlorn Cavern ก็สร้างเรื่องให้เราพอแล้ว ข้าต้องคอยจับตาดูเจ้าด้วยรึ?" },
            { "222:1195439602:1495544134", "จะไปหาพวกชอบเก็บตัวหม่น ๆ ที่ไหนได้ดีกว่ามุมมืดของ Ironforge ที่ชื่อ The Forlorn Cavern ล่ะ ชื่อนี้เหมาะจริง ๆ เจ้าจะเจอ Thistleheart ที่นั่นแน่ คงกำลังอัญเชิญสิ่งมีชีวิตชั่วร้ายสักอย่างมารับใช้เขาอยู่" },
            { "184:337299770:1559352459", "โฮ่! อยากฝึกวิถีนักรบรึ? Kelstrum Stonebreaker จะฝึกเจ้าจนรู้ว่าตัวเองมีฝีมือแค่ไหน! เดินไปที่ Hall of Arms ทางตะวันออกของประตู Ironforge ได้เลย" },
            { "143:149249744:650576770", "ตามหาครูสอนเล่นแร่แปรธาตุรึ? ข้าเพิ่งกลับมาจากที่นั่นเอง เจ้าจะพบคุณ Berryfizz ที่ Tinker Town ตรงที่พวกโนมมารวมตัวกัน" },
            { "218:1668031396:2137815707", "เจ้ามาถูกที่แล้ว พ่อหนุ่ม คนจากทั่วโลกมาฝึกเป็นช่างตีเหล็กที่นี่ เจ้าจะพบ Bengus Deepforge ตีเหล็กอยู่บนทั่งข้าง The Great Forge กลางเมืองของเรานี่เอง", variants = { { "218:294625006:491547364", "เจ้ามาถูกที่แล้ว แม่สาว คนจากทั่วโลกมาฝึกเป็นช่างตีเหล็กที่นี่ เจ้าจะพบ Bengus Deepforge ตีเหล็กอยู่บนทั่งข้าง The Great Forge กลางเมืองของเรานี่เอง" } } },
            { "215:856624436:321057998", "หาครูสอนทำอาหารรึ? งั้นไปที่ Bronze Kettle ทางฝั่งตะวันออกเฉียงเหนือของ The Great Forge เถอะ Daryl Riknussun จะสอนทำอาหารรสเยี่ยม กินแล้วมีเรี่ยวแรงขึ้นมาแน่!" },
            { "209:1997674332:56479577", "อ้อ ถ้าอยากเรียนวิชาเสริมมนตร์ คนที่เจ้าต้องการคือ Gimble Thistlefuzz เขาอยู่ที่ร้าน Thistlefuzz Arcanery ติดกับผู้ดูแลกริฟฟินที่ The Great Forge" },
            { "189:1504225687:173058025", "สนใจวิชาประดิษฐ์เครื่องกลรึ? ถ้าอย่างนั้นไปหา Springspindle Fizzlegear ที่ Tinker Town\n\nจากประตู Ironforge เดินไปทางตะวันออก หรือจะเดินตามเสียงระเบิดไปก็ได้" },
            { "177:1611838433:1103625106", "ปฐมพยาบาลเป็นทักษะที่มีค่ามาก ครูฝึกของเราชื่อ Nissa Firestone นางสอนวิธีให้เจ้าได้ มองหานางที่ Ironforge Physician ฝั่งใต้ของ The Great Forge" },
            { "200:1202358200:105279846", "Grimnur Stonebrand อาจเล่าเกินจริงเรื่องปลาตัวที่หลุดเบ็ด แต่เขาก็ยังเป็นนักตกปลาฝีมือดีที่สุดคนหนึ่งแถวนี้ เขาเปิดร้านชื่อ Traveling Fisherman อยู่ใน The Forlorn Cavern" },
            { "191:2024095083:599989838", "ดอกไม้ เมล็ดพืช อะไรทำนองนั้นรึ? เป็นเรื่องที่ Reyna Stonebranch เชี่ยวชาญ เจ้าจะพบนางดูแลต้นไม้อยู่ที่ Ironforge Physician ฝั่งใต้ของ The Great Forge" },
            { "132:1561362078:806640836", "Fimble Finespindle เปิดร้านอยู่ทางฝั่งตะวันตกเฉียงเหนือของ The Great Forge ข้าพนันว่าเขาสอนให้เจ้าทำชุดเกราะดี ๆ ได้" },
            { "253:914187484:1169688452", "ที่นี่มีครูฝึกขุดแร่ไหมรึ? เจ้าคิดว่าตัวเองอยู่ที่ไหนกัน!?\n\nเจ้าจะพบหนึ่งในนักขุดแร่ที่เก่งที่สุดใน Dun Morogh ที่ Deepmountain Mining Guild ฝั่งเหนือของ The Great Forge ที่นั่น Geofram Bouldertoe จะสอนศิลปะการขุดแร่ที่แท้จริงให้เจ้า" },
            { "191:1701704022:1487761627", "ถ้าอยากเรียนถลกหนังต้องไปหา Balthus Stoneflayer อะไรที่ถลกหนังได้ เขาสอนวิธีให้เจ้าได้หมด ไปที่ Finespindle's Leather Goods ฝั่งเหนือของ The Great Forge ได้เลย" },
            { "182:124632248:383962568", "Jormund Stonebrow มีพรสวรรค์เรื่องเข็มกับด้ายจริง ๆ ถ้าอยากฝึก เจ้าจะพบเขาที่ Stonebrow's Clothier ฝั่งเหนือของ The Great Forge" },
        },
    },
    [10378] = {
        name = "Omusa Thunderhorn",
        lines = {
            { "94:1567210919:17962716", "เส้นทางของพระแม่ธรณีมีมากมาย ไม่ว่าเจ้าจะเลือกเดินทางไปไหน ขอพระนางทรงคุ้มครองเจ้า" },
            { "27:1867159099:2038774738 C 1:63:63", "วันนี้ให้ข้าส่งเจ้าไปที่ไหน {class}?" },
            { "135:351345689:962984541", "ถึง Crossroads จะดูเป็นศูนย์กลางความคึกคักของ The Barrens แต่ข้าชอบความสงบของ Camp Taurajo มากกว่า ให้ข้าส่งเจ้าไปที่ไหน?" },
            { "97:416716092:419272396 N 1:46:46", "ดูแลวินด์ไรเดอร์ให้ดีระหว่างที่มันพาเจ้าไปถึงจุดหมาย ขอให้บรรพบุรุษคุ้มครองเจ้า {name}" },
        },
    },
    [11017] = {
        name = "Roxxik",
        lines = {
            { "93:764977202:1643878168", "พยายามได้ดี แต่เจ้าต้องมีประสบการณ์มากกว่านี้ก่อนจะมาฝึกกับข้า! กลับไปแนวหน้าได้แล้ว!" },
            { "33:1532552285:1646036658", "บางทีข้ายังทึ่งในตัวเองเลย!" },
            { "147:13458362:1175712381", "ข้าจะสอนสิ่งที่ข้าไม่รู้ได้อย่างไร! ถ้ามีใครรู้มากกว่าข้าก็ดีสิ... เดี๋ยวนะ มีนี่! ไปหา Buzzek Bracketswing ที่ Gadgetzan สิ!" },
            { "128:782837113:555049887", "ทำได้ดีนี่! ข้ารู้อยู่แล้วว่ามองเจ้าไม่ผิด ไม่ว่าใครจะพูดอะไร ฮ่า! ข้าล้อเล่น! เอาละ มาเรียนต่อกัน..." },
        },
    },
    [11067] = {
        name = "Malcomb Wynn",
        lines = {
            { "69:1619290176:1687936320", "ข้าไม่มีเวลาให้เสีย คนแปลกหน้า บอกธุระของเจ้ามา หรือไม่ก็ไปเสีย!" },
            { "155:1866979700:757630596", "เออ มาถึงขั้นนี้ได้แล้วสินะ ไปหา Lavinia Crowe ที่ชั้นหนังสืออีกฝั่งโน่น ถ้าเจ้าไม่ทำเรื่องพังต่อหน้านาง ก็อาจได้เรียนรู้อะไรเพิ่มบ้าง" },
            { "100:1765821588:781011488", "ดูเจ้าจะไม่ค่อยมีแววเท่าไร แต่ใครจะรู้ อาจมีนักเสริมมนตร์ซ่อนอยู่ข้างในก็ได้!" },
        },
    },
    [11870] = {
        name = "Archibald",
        lines = {
            { "93:543453884:847384995", "คงมาฝึกใช้อาวุธชนิดใหม่สินะ เร็วเข้า ข้ายุ่งมาก!" },
            { "468:1122961901:350034503", "Sayoc เป็นครูอาวุธชาวออร์ค เขาอยู่ที่ Valley of Honor ใน Orgrimmar และสอนใช้ธนู มีดสั้น อาวุธสวมหมัด ขวานมือเดียวและสองมือ และอาวุธขว้าง\n\nHanashi ครูอาวุธชาวโทรลล์ใน Valley of Honor ของ Orgrimmar สอนใช้ธนู ขวานมือเดียวและสองมือ ไม้เท้า และอาวุธขว้างทุกชนิด\n\nAnsekhwa ครูอาวุธชาวทอเรนอยู่ที่ Lower Rise ใน Thunder Bluff เขาสอนใช้กระบองมือเดียวและสองมือ ไม้เท้า และปืน" },
        },
    },
    [223] = {
        name = "Dan Golthas",
        lines = {
            { "191:198967575:822762114", "จำทุกคำที่ข้าพูดให้ขึ้นใจ จนกว่าศัตรูของเราจะถูกกำจัดสิ้น เราต้องคว้าทุกโอกาสที่จะเพิ่มพูนความรู้ เสริมเกราะให้แข็งแรงและอย่าลดการระวังตัว" },
            { "186:1515332404:1059781458", "ตอนที่ข้าตะกุยตัวเองขึ้นมาจากหลุมศพ ข้าคิดว่าครอบครัวจะอ้าแขนต้อนรับ แต่พวกเขากลับขับไล่ข้าออกจากหมู่บ้าน พลางกรีดร้องด้วยภาษาที่ข้าไม่เข้าใจอีกแล้ว" },
            { "130:1731164737:1920640262", "ข้าช่วยเจ้าไม่ได้แล้ว ฝีมือเจ้าเหนือกว่าข้า ไปคุยกับ Arthur Moore ตรงแถวโลงศพ เขาสอนเจ้าเพิ่มเติมได้" },
        },
    },
    [254089] = {
        name = "Coriella Calmbreeze",
        lines = {
            { "73:485057964:489264846", "ยินดีต้อนรับสู่ Calmbreeze Inn นักเดินทาง รับอะไรให้ชื่นใจสักหน่อยไหม?" },
        },
    },
    [254128] = {
        name = "Wardrobe",
        lines = {
            { "123:1377209264:1294435775", "<สาวกลัทธิสองคนแถวนี้กำลังคุยกัน ถ้าคุณหลบอยู่หลังตู้เสื้อผ้าแล้วแอบฟัง อาจได้รู้อะไรบางอย่าง>" },
        },
    },
    [255940] = {
        name = "Donaal Downbreeze",
        lines = {
            { "73:485057964:489264846", "ยินดีต้อนรับสู่ Calmbreeze Inn นักเดินทาง รับอะไรให้ชื่นใจสักหน่อยไหม?" },
        },
    },
    [263570] = {
        name = "Creeg Bothunk",
        lines = {
            { "310:330933952:1753537184", "สวัสดี นักเดินทาง! ข้าคือ Creeg Bothunk ผู้จัดหาเสบียงหลักของ Darkspear Raiders เมื่อเจ้าสนิทสนมกับ Darkspear Raiders มากขึ้น ข้าจะจัดหาสินค้าหลายอย่างให้เจ้าใช้ใน Darkspear Islands ได้ หากต้องการซ่อมอุปกรณ์ ข้าก็มีบริการให้" },
            { "320:899419086:370237512", "สวัสดี นักเดินทาง! ข้าคือ Creeg Bothunk ผู้จัดหาเสบียงหลักให้ Darkspear Raiders เมื่อเจ้ามีชื่อเสียงกับ Darkspear Raiders สูงขึ้น ข้าก็จะมีสินค้าหลายอย่างให้เลือกใช้ใน Darkspear Islands หากต้องซ่อมอุปกรณ์ ข้าก็รับซ่อมเช่นกัน" },
        },
    },
    [264078] = {
        name = "Sutara Plainstalker",
        lines = {
            { "197:611916449:1121154121", "ข้ารู้สึกเป็นเกียรติที่ได้ดูแลเสบียงและอุปกรณ์ให้ Earthen Ring\n\nตอนนี้ของในคลังมีจำกัด แต่ลองแวะมาบ่อย ๆ ข้าอาจมีอุปกรณ์กับเสบียงใหม่ ๆ ให้ซื้อ" },
        },
    },
    [267327] = {
        name = "Kagil",
        lines = {
            { "85:1938448218:1122547814", "อยากเรียนวิธีเก็บหนังจากสัตว์ที่ตายแล้วหรือ? หรืออยากได้เครื่องมือใหม่?" },
        },
    },
    [4596] = {
        name = "James Van Brunt",
        lines = {
            { "154:127703041:9581170", "อยากเป็นช่างตีเหล็กรึ? อยากตีดาบไว้คว้านไส้ศัตรู หรือทำค้อนทุบกะโหลกมันรึ? เออ ข้าช่วยได้ ยินดีเสียด้วยถ้ามีเลือดให้หลั่งจากงานนี้" },
            { "49:1156306295:828122960", "เจ้าทำข้าเสียเวลา ไปคุยกับ Basil ลูกศิษย์ข้าไป" },
            { "135:1868651844:1779102836", "คมเหล็กของเจ้าเป็นอย่างไรบ้าง? คมพอจะผ่าท้องศัตรูหรือยัง? มานี่ ข้าจะสอนวิธีลับให้คมขึ้นอีก" },
        },
    },
    [4604] = {
        name = "Abigail Sawyer",
        lines = {
            { "62:693481873:1556178978", "คำพูดก็เหมือนลูกธนู พอปล่อยไปแล้วก็เรียกกลับคืนไม่ได้" },
        },
    },
    [4612] = {
        name = "Boyle",
        lines = {
            { "22:1437024205:955966123", "สสสไลม์!! อ๊ากกก..." },
        },
    },
    [5819] = {
        name = "Mirelle Tremayne",
        lines = {
            { "203:1792753586:1358630902", "ถ้าตามหาเกราะแผ่นเหล็ก เกราะโซ่ถัก หรือโล่ ข้ามีของดีที่สุดใน Undercity ของส่วนใหญ่ผลิตและซ่อมกันที่นี่ บางชิ้นก็เก็บกู้มา\n\nเลือกดูได้ตามสบาย" },
            { "198:1761898827:1781025703", "ถ้ากำลังหาเกราะแผ่น เกราะโซ่ หรือโล่ ข้ามีของดีที่สุดใน Undercity ชิ้นส่วนใหญ่ทำและซ่อมกันที่นี่ แม้บางชิ้นจะเก็บกู้มาจากที่อื่น\n\nเลือกดูได้ตามสบาย" },
        },
    },
    [6491] = {
        name = "Spirit Healer",
        lines = {
            { "97:620609531:1907569420", "เวลาของเจ้ายังมาไม่ถึง ข้าจะช่วยให้เจ้ากลับสู่แดนคนเป็น... แต่เจ้าต้องจ่ายสิ่งตอบแทน" },
        },
    },
    [3339] = {
        name = "Captain Thalo'thas Brightsun",
        lines = {
            { "27:448163092:525618969", "ขอให้เป็นเรื่องสำคัญจริง ๆ เถอะ..." },
        },
    },
    [3345] = {
        name = "Godan",
        lines = {
            { "43:1946519041:297899864", "เจ้าอาจมีฝีมือพอ มาลองดูกัน!" },
            { "162:280344830:1311530893", "ฝีมือเจ้าล้ำหน้าข้าแล้ว คนแปลกหน้า ไปคุยกับ Hgarth ที่ Sun Rock Retreat ใน Stonetalon Mountains เถอะ เขาถ่ายทอดความรู้ให้เจ้าได้มากกว่าข้า" },
            { "115:1598129365:781529526", "นักผจญภัยบางคนคิดว่าวิชาเสริมมนตร์ไม่ได้ผล พอข้าท้าสู้ทีไร พวกนั้นก็เปลี่ยนคำพูดทุกที!" },
            { "92:1889036015:2141940015", "เจ้ายังไม่พร้อมฝึกกับข้า คนแปลกหน้า ไปฝึกกับ Jhag ผู้ช่วยของข้าที่อยู่ตรงนั้นสักพัก" },
            { "156:21885304:549634020", "ดีมาก! แววตาเจ้ามีประกายนั่น... ข้าจำได้ดี ข้าก็เคยตาเป็นประกายแบบนั้นตอนยังเด็ก! เอาละ มาดูกันว่าข้าพอจะสอนอะไรเจ้าได้บ้าง" },
        },
    },
    [11441] = {
        name = "Gordok Brute",
        lines = {
            { "29:1032535084:73514697", "ข้าไม่หาเรื่องท่านหรอก นายท่าน" },
            { "37:529214938:160767858", "ราชาองค์เก่าตายไปแล้วเรอะ? เป็นไปไม่ด้าย!" },
            { "23:737486772:1024757505", "ข้าฉลาดสุด ๆ! สะกดว่า ฉะ-หลาด!" },
            { "130:621474788:490225351", "อยู่กับพวกข้าที่นี่ ท่านก็เป็นราชา พอท่านไป โอเกอร์ตัวอื่นจะมาแทนที่ท่าน นี่แหละวิถี Gordok!" },
            { "117:1519900427:1474746835", "พวกข้าสะอาดกว่าพวกโอเกอร์ใน Tanaris เยอะ มองไปทั่วทะเลทรายไกลสุดตา มีแต่ขี้โอเกอร์ ที่นี่ไม่มีแบบนั้นหรอก นายท่าน!", variants = { { "118:1247970760:2141089320", "พวกข้าสะอาดกว่าพวกโอเกอร์ใน Tanaris เยอะ มองไปทั่วทะเลทรายไกลสุดตา มีแต่ขี้โอเกอร์ ที่นี่ไม่มีแบบนั้นหรอก นายหญิง!" } } },
            { "94:499520235:1564383616", "โอเกอร์ตัวอื่นโง่ที่ไปโจมตีท่าน นายท่าน! ข้าเลยยังไม่ตายไง ข้าฉลาดแล้วก็อะไรพวกนั้น!" },
            { "85:235051016:1392254635", "ที่ข้าเคยทำหน้าบึ้งใส่ท่านก่อนท่านจะเป็นราชาองค์ใหม่... เอ่อ... ข้าแค่ล้อเล่นเอง\n\nใช่!" },
            { "20:403347614:691377668", "ขอถวายพระพรแด่ราชาองค์ใหม่!" },
        },
    },
    [11444] = {
        name = "Gordok Mage-Lord",
        lines = {
            { "29:1032535084:73514697", "ข้าไม่หาเรื่องท่านหรอก นายท่าน" },
            { "37:529214938:160767858", "ราชาองค์เก่าตายไปแล้วเรอะ? เป็นไปไม่ด้าย!" },
            { "23:737486772:1024757505", "ข้าฉลาดสุด ๆ! สะกดว่า ฉะ-หลาด!" },
            { "130:621474788:490225351", "อยู่กับพวกข้าที่นี่ ท่านก็เป็นราชา พอท่านไป โอเกอร์ตัวอื่นจะมาแทนที่ท่าน นี่แหละวิถี Gordok!" },
            { "117:1519900427:1474746835", "พวกข้าสะอาดกว่าพวกโอเกอร์ใน Tanaris เยอะ มองไปทั่วทะเลทรายไกลสุดตา มีแต่ขี้โอเกอร์ ที่นี่ไม่มีแบบนั้นหรอก นายท่าน!", variants = { { "118:1247970760:2141089320", "พวกข้าสะอาดกว่าพวกโอเกอร์ใน Tanaris เยอะ มองไปทั่วทะเลทรายไกลสุดตา มีแต่ขี้โอเกอร์ ที่นี่ไม่มีแบบนั้นหรอก นายหญิง!" } } },
            { "94:499520235:1564383616", "โอเกอร์ตัวอื่นโง่ที่ไปโจมตีท่าน นายท่าน! ข้าเลยยังไม่ตายไง ข้าฉลาดแล้วก็อะไรพวกนั้น!" },
            { "85:235051016:1392254635", "ที่ข้าเคยทำหน้าบึ้งใส่ท่านก่อนท่านจะเป็นราชาองค์ใหม่... เอ่อ... ข้าแค่ล้อเล่นเอง\n\nใช่!" },
            { "20:403347614:691377668", "ขอถวายพระพรแด่ราชาองค์ใหม่!" },
        },
    },
    [11445] = {
        name = "Gordok Captain",
        lines = {
            { "29:1032535084:73514697", "ข้าไม่หาเรื่องท่านหรอก นายท่าน" },
