    [4700] = {
        name = "Aged Kodo",
        lines = {
            { "93:2120973710:313059819", "พวกก็อบลินผูกสัมภาระเข้ากับสัตว์พวกนี้ได้อย่างไรกัน? ตัวโคโดใหญ่กว่าตั้งสิบเท่า!" },
            { "91:1692709857:1054387802", "ทำไมพวกตัวเล็กอย่างก็อบลินถึงชอบสัตว์ตัวใหญ่กว่าตัวเองอยู่เรื่อย?" },
            { "111:302530123:1656250682", "โคโดตัวนี้ไม่เหมือนตัวที่ข้าล่อมาตอนแรกเลย! สงสัยว่า kombobulator จะใช้กับข้าได้ไหมนะ" },
        },
    },
    [4701] = {
        name = "Dying Kodo",
        lines = {
            { "93:2120973710:313059819", "พวกก็อบลินผูกสัมภาระเข้ากับสัตว์พวกนี้ได้อย่างไรกัน? ตัวโคโดใหญ่กว่าตั้งสิบเท่า!" },
