            { "46:1727109466:1982911608", "ใช่ ข้าต้องการล้างแต้มพรสวรรค์ของคลาส" },
            { "47:197780750:1115225935", "ใช่ ข้าต้องการล้างแต้มพรสวรรค์ Legacy" },
        },
    },
    [262558] = { name = "Palah Thunderhoof",
        lines = {
            { "45:1353433914:1143541879", "ข้าต้องการล้างแต้มพรสวรรค์ของคลาสหรือ Legacy" },
        },
    },
}

-- Reviewed captured NPC dialogue0.458.0;seeDev/NpcDialogue-0.458.0.json.
addon.npcs[1976].lines[79] = { "193:1219935351:560476450", "กรรไกรคมที่สุดกับมือที่เบาที่สุดอยู่ที่ร้าน Curls and Furls ใน Trade District นี่เอง ถ้ามีเวลาว่างและอยากเล็มผมสักหน่อย ก็ลองแวะไปดู" }
addon.npcs[68].lines[81] = { "193:1219935351:560476450", "กรรไกรคมที่สุดกับมือที่เบาที่สุดอยู่ที่ร้าน Curls and Furls ใน Trade District นี่เอง ถ้ามีเวลาว่างและอยากเล็มผมสักหน่อย ก็ลองแวะไปดู" }
addon.npcs[5504].lines[5] = { "255:967301392:2039283435", "นอกจากฝึกสอนแล้ว หากเจ้าต้องการ ข้ายังมีอำนาจลบความรู้เรื่องพรสวรรค์ออกจากจิตใจเจ้าได้ แต่จงรู้ไว้ว่า ยิ่งผ่านกระบวนการนี้บ่อยเท่าไร ก็ยิ่งทำได้ยากขึ้น และค่าใช้จ่ายจึงสูงขึ้นตามไปด้วย" }
addon.npcs[5504].lines[6] = { "309:2079136035:1169121454", "ยินดีต้อนรับ น้องชายร่วมวิถี หากเจ้ามาฝึกฝน ข้าก็ยินดีสอน\n\nอีกไม่นานเสียงเรียกของ Emerald Dream จะดึงดูดเจ้า เจ้าจะจำศีลอยู่หลายปี และท่องไปท่ามกลางรูปภาวะอันบริสุทธิ์ที่สุด ณ ที่นั้นและเวลานั้น การฝึกฝนขั้นสูงสุดของเจ้าจะเกิดขึ้น" }
addon.npcs[268313] = { name = "Black Stallion", lines = {} }
addon.npcs[268313].lines[1] = { "60:884149127:1921345985", "<มันดูเงียบกว่าม้าตัวอื่น ๆ แต่ก็ยังตื่นตัวไม่แพ้กัน>" }
addon.npcs[271481] = { name = "Captive Fire Elemental", lines = {} }
addon.npcs[271481].lines[1] = { "8:1146914818:1654390943", "ปล่อยข้า!" }
addon.npcs[2705] = { name = "Brewmeister Bilger", lines = {} }
addon.npcs[2705].lines[1] = { "52:797462038:2108658315", "Brewmeister Bilger หมักแต่เบียร์ชั้นยอดเท่านั้น!\n\nวู้ฮู้!" }
addon.npcs[3373].lines[3] = { "133:1659205192:837453589", "Balai Lok'Wein ที่ Brackenwall Village ใน Dustwallow Marsh ขายคู่มือที่ต้องศึกษาเพื่อเพิ่มทักษะ!" }
addon.npcs[8153].lines[2] = { "145:16290983:329521861", "ทักษะของเจ้าเหนือกว่าข้าแล้ว เจ้าหนู ไปหา Una ที่มีร้านอยู่บนที่ราบสูงใจกลาง Thunder Bluff นางจะชี้แนะแนวทางที่เจ้าต้องการได้" }
addon.npcs[5570] = { name = "Bruuk Barleybeard", lines = {} }
addon.npcs[5570].lines[1] = { "34:82628191:885997656", "สวัสดี รับอะไรดี?" }
addon.npcs[5595].lines[72] = { "183:26908671:1040392161", "เอาล่ะ! มาถูกที่แล้ว ถ้าอยากเรียนขุดแร่ เจ้าหนู! ที่ Deepmountain Mining Guild มี Geofram Bouldertoe สอนอยู่ด้วยตัวเอง เจ้าหาครูฝึกที่ดีกว่าเขาไม่ได้แล้ว" }
addon.npcs[6740].lines[45] = { "210:1138684758:1324523170", "อาณาจักรเก่าแห่ง Lordaeron เต็มไปด้วยอันตราย เราขอให้ทุกคนที่กล้าเข้าไปในดินแดน Tirisfal Glades ซึ่งกำลังผุพังระวังตัวไว้ ถ้าจำเป็นต้องไปจริง ๆ จงตามหา Undercity แล้วมุ่งไปยังลานด้านบน" }
addon.npcs[6740].lines[46] = { "569:133628415:1770757621", "ดินแดนเก่าแก่ของเราอยู่ทางตะวันออกเฉียงเหนือของ Eastern Kingdoms ตั้งชื่อตาม Lordain เอง ครั้งหนึ่งเคยเป็นอาณาจักรที่ทรงอำนาจและภาคภูมิ ประวัติศาสตร์ของที่นั่นมีเรื่องราวมากมายให้ชนชั้นสูงและราชาที่เพิ่งผงาดขึ้นได้เรียนรู้ เหตุการณ์สำคัญครั้งหนึ่งคือการช่วยก่อตั้ง Alliance ที่เรารู้จักในทุกวันนี้\n\nน่าเสียดายที่ประวัติศาสตร์ของมันมีด้านมืดด้วย และผู้ที่อาศัยอยู่ตอนนี้กำลังทำให้แผ่นดินแปดเปื้อนทุกวัน ซากเมืองที่อยู่เหนือ Undercity ยังมีสิ่งสำคัญอีกมาก แต่คงเป็นเรื่องเขลาที่จะเดินทางไปแล้วหวังว่าจะกลับมาได้ทั้งเป็น" }
addon.npcs[267007].lines[14] = { "214:1323330601:1092735995", "เจ้า Leland ตัวขี้เกียจ เอาแต่นั่งตกปลาอยู่บนท่าน้ำด้านนอก Trade District ทั้งวัน ข้าหวังว่าจะตกเก่งสมกับเวลาที่เสียไป ถ้าเจ้าอยากเรียนก็ลองไปคุยกับเขาดูสิ" }
addon.npcs[274757].lines[3] = { "232:912418607:1540266013", "ที่ Darnassus มีครูฝึกผู้ชำนาญอาชีพตนจนสมบูรณ์ ด้วยการฝึกและทุ่มเทเนิ่นนาน ข้าจะแนะนำอาจารย์ให้ เพียงบอกเส้นทางที่เจ้าเลือก" }
addon.npcs[261579] = { name = "Riding Spotted Frostsaber", lines = {} }
addon.npcs[261579].lines[1] = { "87:979766103:390342286", "<เมื่อเจ้าเข้าใกล้ เสือเขี้ยวดาบส่งเสียงคำรามต่ำ ๆ ก่อนจะพ่นลมหายใจแล้วกลับไปงีบต่อ>" }
addon.npcs[274757].lines[4] = { "126:1536500603:2129287764", "เพิ่งเปิดที่ Tradesman's Terrace ถ้าเดินตามทางที่มุ่งไปทางตะวันออกเฉียงใต้จากธนาคาร ก็น่าจะหาเจอได้ง่าย" }
addon.npcs[5510].lines[2] = { "231:839735773:1257729304", "อย่าให้พวกมนุษย์ใน Bazaar ต้มเอานะ เจ้าหนุ่ม ตั้งแต่พวกโนมสร้างรถไฟใต้ดิน ขนของจาก Ironforge ก็ง่ายกว่าที่เจ้าคิด ถ้าพวกนั้นจะคิดค่าขนส่งเพิ่ม ก็บอกไปว่าจะซื้อของจากข้าแทน" }
addon.npcs[8931].lines[45] = { "153:6842050:241154921", "ทางเข้า Whelgar's Excavation Site อยู่ในหุบเขาทางใต้ของ Wetlands โดยมีถ้ำตามแนวสันเขาด้านตะวันตกเป็นทางผ่าน" }
addon.npcs[8931].lines[46] = { "368:1809375208:660880304", "เราไม่ค่อยมีเรื่องเล่าหรือประวัติศาสตร์เกี่ยวกับ Wetlands Excavation Site มากนัก แต่เรารู้ว่าคนงานเหมืองกลุ่มหนึ่งที่โอหังจนไม่เกรงอันตรายพยายามระเบิดเปิดทางเข้าไปในเทือกเขาทางใต้ซึ่งทอดตัวเหนือ Dun Morogh ดินแดนชุ่มน้ำที่ถูกลืมนั้นอยู่ใต้เงาของผู้เฝ้ามองไททันที่สาบสูญ มีการส่งคนไปมากมายเพื่อค้นหาชะตากรรมของเหล่าคนงานเหมืองที่หายไป" }
addon.npcs[8931].lines[47] = { "166:1579432198:1271819732", "อาณาจักร Dalaran อยู่ทางตะวันตกของเทือกเขา Alterac มุ่งไปยัง Hillsbrad Fields แล้วเดินทางขึ้นเหนือ เจ้าจะได้เห็นยอดหอคอยสูงตระหง่านของ Kirin Tor แน่นอน" }
addon.npcs[8931].lines[48] = { "505:934267010:2070070631", "อาณาจักร Dalaran ที่เคยรุ่งเรืองและเปี่ยมศักดิ์ศรีต้องพบชะตากรรมอันเลวร้ายเมื่อ Burning Legion มาถึง เหล่า Kirin Tor ผู้ทรงพลังก็ไม่รอช้าที่จะฟื้นฟูเมืองแห่งจอมเวทให้กลับมารุ่งเรืองดังเดิม ยอดหอคอยที่สูงตระหง่านของเมืองทอดเงาทาบแม้กระทั่งยอดเขาที่สูงที่สุดใน Alterac\n\nม่านคุ้มครองอาคมที่ปกป้องเมืองและผู้คนได้ทำหน้าที่ของมันสำเร็จแล้ว แม้เมืองจะยังไม่เปิดพรมแดนต้อนรับพันธมิตรทุกคน แต่ก็ยื่นไมตรีต้อนรับผู้ที่เต็มใจช่วยให้ความยิ่งใหญ่ของเมืองเบ่งบานขึ้นอีกครั้ง" }
addon.npcs[5511].lines[5] = { "226:457780417:2072240298", "ข้าเคยบอกว่าเจ้ามีเลือดช่างตีเหล็กอยู่ในตัว และข้าก็คิดถูก ไป Ironforge ที่ The Great Forge แล้วตามหาช่างตีเหล็กชาวดวอร์ฟชื่อ Bengus Deepforge เขาเป็นอาจารย์ของข้า และเป็นหนึ่งในช่างตีเหล็กที่ยอดเยี่ยมที่สุดเท่าที่ข้าเคยรู้จัก" }

-- Captured readable pages0.459.0;seeDev/BookPages-0.459.0.json.
addon.books["Alliance Military Ranks"] = { title = "ยศทหารฝ่ายอะไลแอนส์" }
addon.books["Alliance Military Ranks"][1] = { "647:343794541:554363177", "ยศนายทหาร\nจอมพลสูงสุด (Grand Marshal)\nจอมพลสนาม (Field Marshal)\nจอมพล (Marshal)\nผู้บัญชาการ (Commander)\nรองผู้บัญชาการ (Lieutenant Commander)\nอัศวินยอดนักรบ (Knight-Champion)\nอัศวินผู้กอง (Knight-Captain)\nอัศวินผู้หมวด (Knight-Lieutenant)\nอัศวิน (Knight)\n\nยศพลทหารและนายสิบ\nจ่าสิบเอก (Sergeant Major)\nจ่าสิบโท (Master Sergeant)\nจ่า (Sergeant)\nสิบตรี (Corporal)\nพลทหาร (Private)" }
addon.books["Fossilized Egg"] = { title = "ไข่ที่กลายเป็นฟอสซิล" }
addon.books["Fossilized Egg"][1] = { "340:1455299497:573014313", "ไข่ประหลาดใบนี้ถูกพบในดินแดนรกร้างอันร้อนระอุของทะเลทราย Tanaris และยังคงเป็นปริศนาสำหรับนักนิเวศวิทยาในปัจจุบัน การทดสอบหาอายุบ่งชี้ว่าไข่อาจเก่าแก่ถึงหนึ่งพันปี แม้ลักษณะบางอย่างจะบ่งบอกถึงโครงสร้างแบบแมลง แต่ก็ยังไม่อาจระบุต้นกำเนิดที่แท้จริงของมันได้ เรายังไม่ค้นพบสายพันธุ์ที่วางไข่อันเป็นเอกลักษณ์เช่นนี้" }
addon.books["Roc Talon"] = { title = "กรงเล็บนกร็อค" }
addon.books["Roc Talon"][1] = { "301:1569251951:2056815381", "กรงเล็บที่กลายเป็นหินนี้พบได้นอกชายฝั่งทางใต้ของ Stranglethorn นักนิเวศวิทยาเชื่อว่าเป็นกรงเล็บของนกร็อคสุริยันในสมัยโบราณ แม้สัตว์ชนิดนี้จะมีบทบาทโดดเด่นในตำนานของชาวทอเรนยุคดึกดำบรรพ์ แต่การค้นพบกรงเล็บนี้ก็บ่งชี้ว่าพวกมันเคยมีอยู่จริงในช่วงเวลาหนึ่ง" }
addon.books["The Skull of Tyrannistrasz"] = { title = "กะโหลกของ Tyrannistrasz" }
addon.books["The Skull of Tyrannistrasz"][1] = { "196:2071835427:842643804", "ซากของมังกรแดงขนาดมหึมาถูกพบใน Wetlands ไม่นานหลังยุทธการแห่ง Grim Batol เล่าลือกันว่า Tyrannistrasz เคยเป็นคู่ครองอาวุโสของ Alexstrasza ราชินีมังกร" }
addon.books["Geru Strider"] = { title = "นก Geru Strider" }
addon.books["Geru Strider"][1] = { "89:796818840:1959180062", "ในบรรดานก plainstrider นั้น Geru มีขนาดใหญ่ที่สุด พวกมันมีจำนวนน้อยและพบเห็นได้ยาก" }
addon.books["Horde Catapult"] = { title = "เครื่องยิงของฮอร์ด" }
addon.books["Horde Catapult"][1] = { "140:993751291:923490501", "ซากจากสงครามครั้งที่สองชิ้นนี้เตือนใจได้อย่างชัดเจนว่า ฮอร์ดเคยเข้าใกล้การพิชิตภูเขา Ironforge อย่างน่าหวาดเสียวเพียงใด" }
addon.books["Uldaman Reliefs"] = { title = "ภาพสลักนูนแห่ง Uldaman" }
addon.books["Uldaman Reliefs"][1] = { "306:1636472519:709862934", "แถบภาพสลักนูนเหล่านี้อาจเป็นการค้นพบที่สำคัญที่สุดภายในห้องช่วงแรกของ Uldaman ลวดลายที่สลักไว้บ่งชี้อย่างชัดเจนถึงความเชื่อมโยงระหว่างชาวเอิร์ธเธนที่มีรูปร่างคล้ายโกเลมกับเผ่าดวอร์ฟ หากมีหลักฐานเพิ่มเติม ทฤษฎีที่ว่าพวกเราถูกสร้างขึ้นโดยเหล่าไททันในตำนานก็อาจได้รับการพิสูจน์ว่าเป็นความจริง" }
addon.books["Empires' Fall"] = { title = "การล่มสลายของจักรวรรดิ" }
addon.books["Empires' Fall"][1] = { "495:2077851399:2081868644", "แม้ต้นกำเนิดของพวกเขาจะยังคลุมเครือ แต่ก็เห็นได้ชัดว่าไนต์เอลฟ์ขึ้นสู่อำนาจไม่นานหลังค้นพบบ่อน้ำแห่งนิรันดร์ แม้เหล่าโทรลล์จะพยายามขัดขวางการขยายดินแดน ไนต์เอลฟ์ก็ยังสร้างจักรวรรดิอันยิ่งใหญ่ที่แผ่ขยายอย่างรวดเร็วไปทั่ว Kalimdor ในยุคดึกดำบรรพ์ ด้วยเวทมนตร์อันรุนแรงที่เหล่าโทรลล์ผู้เชื่องมงายไม่เคยแม้แต่จะจินตนาการถึง ไนต์เอลฟ์จึงทำสิ่งที่พวกอาคีร์ผู้ชั่วร้ายไม่เคยทำสำเร็จได้โดยไม่ยากเย็น นั่นคือโค่นล้มสองจักรวรรดิที่ยิ่งใหญ่ที่สุดในโลก" }
addon.books["The Scourge of Lordaeron"] = { title = "ภัยสเคิร์จแห่ง Lordaeron" }
addon.books["The Scourge of Lordaeron"][1] = { "366:147008000:606735515", "หลังเตรียมการอยู่นานหลายเดือน ในที่สุด Kel'Thuzad และลัทธิ Cult of the Damned ก็เปิดฉากโจมตีครั้งแรกด้วยการปล่อยโรคระบาดอันเดดลงสู่ Lordaeron Uther และเหล่าพาลาดินร่วมอุดมการณ์เข้าสำรวจพื้นที่ติดเชื้อ โดยหวังจะหาทางหยุดโรคระบาด แม้พวกเขาจะพยายามเพียงใด โรคระบาดก็ยังคงลุกลามและคุกคามที่จะฉีกอะไลแอนส์ให้แตกสลาย" }
addon.books["The Sentinels and the Long Vigil"] = { title = "เหล่าเซนทิเนลกับการเฝ้าระวังอันยาวนาน" }
addon.books["The Sentinels and the Long Vigil"][1] = { "271:555186963:1115357203", "เมื่อญาติพี่น้องผู้หลงผิดจากไป ไนต์เอลฟ์ก็หันกลับมาทุ่มเทให้กับการปกป้องบ้านเกิดอันเปี่ยมมนตร์ขลัง เหล่าดรูอิดรับรู้ว่าช่วงเวลาจำศีลใกล้เข้ามา จึงเตรียมเข้าสู่นิทราและจากคนรักกับครอบครัวไว้เบื้องหลัง" }
addon.books["Defias Docket"][3].variants = { { "391:789641390:812773295", "คาดว่าจะโจมตีเมื่ออยู่ห่างจากจุดหมายไม่กี่ไมล์ ตรงนั้นจะมีพวก…พันธมิตร…ของเราดักรออยู่ ข้าไม่แน่ใจว่าทำไมเราถึงต้องจับมือกับสัตว์พวกนั้น แต่อดรู้สึกไม่ได้ว่าเราเองก็ถูกบีบบังคับ ท้ายที่สุดเรื่องนี้ก็ไม่สำคัญ เมื่อจับเป้าหมายไว้ในมือ เราก็จะเข้าใกล้การทวง Stormwind คืนจากพวกที่ขโมยไปจากเรา!" } }
addon.books["Howin's Missive"] = { title = "สารของ Howin" }
addon.books["Howin's Missive"][1] = { "644:471223815:2027494459", "ถึงกษัตริย์ Magni\n\nนักผจญภัยผู้นี้นำข่าวคราวความยากลำบากล่าสุดของ Wetlands ดินแดนทางเหนือของพระองค์มาด้วย แม้ Menethil Harbor จะยังยืนหยัดอยู่ แต่ดินแดนแห่งนี้ก็เต็มไปด้วยศัตรูของทั้งชาว Wildhammer และ Bronzebeard\n\nพวก Dragonmaw เคลื่อนไหวถี่ขึ้นและมีจำนวนมากขึ้น จนน่าเกรงว่าพวกมันจะกลับมาเลี้ยงมังกรอีกครั้งภายใต้เงาของ Grim Batol ข้าไม่รู้ว่าพวกมันเป็นพันธมิตรกับใครหรือไม่ แต่พวกมันยังเป็นภัยร้ายแรงที่มีแผนการชัดเจนมุ่งร้ายต่อดินแดนของพระองค์หลายแห่ง รวมถึงนครอันยิ่งใหญ่แห่ง Ironforge\n\nยิ่งไปกว่านั้น ผืนดินเองก็ดูจะติดโรคบางอย่าง สัตว์พื้นเมืองดุร้ายขึ้น และมีสิ่งชวนวิตกผุดขึ้นมาจากน่านน้ำขุ่นมัว" }
addon.books["Howin's Missive"][2] = { "345:1101362667:327410819", "แม้ผู้คนแห่ง Menethil Harbor จะขยันขันแข็งและกล้าหาญในแบบของตน แต่พวกเขาก็ไม่มีทรัพยากรพอจะปราบดินแดนแห่งนี้ให้สงบ ยังอีกไกลกว่าจะเริ่มหารือเรื่องที่ชาวเผ่าของข้าจะกลับไป\n\nข้าขอเรียกร้องให้พระองค์พิจารณาลงมือจัดการปัญหาในภูมิภาคนี้ ขณะที่ยังมีโอกาส\n\nด้วยความปรารถนาดี\n\n— Howin Kindfeather แห่งเผ่า Wildhammer" }
addon.books["Brock's List"][1].variants = { { "225:832780406:773695225", "รายชื่อนักเรียนที่ได้ผลการเรียนระดับดาวแพลทินัมจากโรงเรียนทำเหมืองและสำรวจของ Brock และได้รับอีเต้อคนงานเหมืองกิตติมศักดิ์\n\nMelia Stoneshaker\nBardin Ironband\nUmi Togglevolt\nRumi Togglevolt\nVorel Steelspire" } }
addon.books["White Punch Card"] = { title = "บัตรเจาะรูสีขาว" }
addon.books["White Punch Card"][1] = { "480:1027726294:339210607", "บัตรข้อมูลสำคัญยิ่งยวดที่เข้ารหัสซ้อนสามชั้น\n\n01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111" }
addon.books["Horatio Montgomery, M.D."] = { title = "นายแพทย์ Horatio Montgomery" }
addon.books["Horatio Montgomery, M.D."][1] = { "448:1841569611:1787347229", "เพื่อรำลึกถึงอาจารย์ที่รักของข้า นายแพทย์ Horatio M. Montgomery ผู้รักษา ครู และมิตร\n\n50 BTFT - 25 ATFT\n\n\"โลกนี้เต็มไปด้วยคนเจ็บป่วยและอ่อนล้า หน้าที่ของพวกเราในฐานะผู้รักษา ไม่สิ ในฐานะบุรุษและสตรีแห่งวงการแพทย์ คือกำจัดโรค 'อักเสบ' ให้พวกเขาทุกคน\"\n\n— H.M.M., M.D., PhD, JD, ปรมาจารย์เกษตรกร นักเต้นผู้ยอดเยี่ยม มิตรแห่งสรรพสัตว์" }

-- Historical primary exact-match continuations0.461.0;current Forever full chains unconfirmed.
addon.books["Empires' Fall"][2] = { "389:134529600:592807978", "ไนต์เอลฟ์ทำลายแนวป้องกันและเส้นทางลำเลียงเสบียงของโทรลล์อย่างเป็นระบบ เหล่าโทรลล์ไม่อาจต้านทานเวทมนตร์ทำลายล้างของเอลฟ์ได้ จึงพ่ายแพ้ต่อการโจมตี ไนต์เอลฟ์แสดงให้เห็นว่าพวกตนเจ้าเล่ห์และกระหายเลือดไม่แพ้โทรลล์ผู้ป่าเถื่อน ทำให้ชาวโทรลล์เคียดแค้นและดูหมิ่นพวกเขาตลอดกาล จักรวรรดิ Gurubashi และ Amani แตกเป็นเสี่ยง ๆ ภายในเวลาเพียงไม่กี่ปี" }
addon.books["Empires' Fall"][3] = { "390:618170424:329432667", "ในที่สุด ไนต์เอลฟ์ก็ถูกไฟอาคมที่พยายามควบคุมเผาผลาญเสียเอง การใช้เวทมนตร์อย่างไม่ยั้งคิดของพวกเขาล่อ Burning Legion กองทัพปีศาจมาสู่โลก เหล่าปีศาจบดขยี้อารยธรรมของไนต์เอลฟ์ไปมาก แม้ไม่มีบันทึกใดระบุว่า Legion โจมตีอารยธรรมโทรลล์ทั้งสองแห่ง แต่ก็น่าจะมีการสู้รบเกิดขึ้นทั่วทั้งทวีป" }
addon.books["Empires' Fall"][4] = { "288:551247548:1769784829", "เมื่อความขัดแย้งอันน่าสะพรึงกลัวนี้สิ้นสุดลง ซึ่งรู้จักกันในชื่อสงครามแห่งบรรพกาล บ่อน้ำแห่งนิรันดร์ก็ระเบิดยุบตัว แรงกระแทกที่ตามมาทำให้แผ่นดินใหญ่ส่วนมากของ Kalimdor แตกสลาย ใจกลางทวีปถูกแรงระเบิดซัดจมลงใต้ทะเล เหลือเพียงทวีปที่แยกขาดและแตกกระจัดกระจายอยู่ไม่กี่แห่ง" }
addon.books["Empires' Fall"][5] = { "470:986038076:1466608423", "ด้วยเหตุนี้ ดินแดนส่วนใหญ่ของจักรวรรดิ Amani และ Gurubashi จึงยังคงหลงเหลืออยู่ในดินแดน Quel'Thalas และ Stranglethorn ในปัจจุบันตามลำดับ อาณาจักร Azjol-Nerub และ Ahn'Qiraj ของชาว Azj'Aqir ก็ยังดำรงอยู่ใน Northrend และ Tanaris ในปัจจุบันตามลำดับ อารยธรรมโทรลล์ทั้งสองต่างหวาดผวาต่อความพินาศมหาศาลที่เกิดขึ้นกับโลกดึกดำบรรพ์ที่พวกเขาเคยรู้จัก โทรลล์ผู้ไม่ย่อท้อสร้างนครที่ถูกทำลายขึ้นใหม่ แล้วเริ่มทวงอำนาจบางส่วนที่เคยมีคืนมา" }
addon.books["The Scourge of Lordaeron"][2] = { "446:1748711533:698697058", "ขณะที่กองทัพอันเดดกวาดผ่านไปทั่ว Lordaeron เจ้าชาย Arthas พระโอรสองค์เดียวของ Terenas ก็เข้าต่อสู้กับสเคิร์จ แม้ Arthas จะสังหาร Kel'Thuzad สำเร็จ แต่ทหารทุกนายที่ล้มลงปกป้องแผ่นดินกลับเพิ่มกำลังให้กองทัพอันเดด ความคับแค้นใจและอับจนหนทางต่อศัตรูที่ดูเหมือนไม่อาจหยุดยั้ง ทำให้ Arthas ใช้มาตรการรุนแรงขึ้นเรื่อย ๆ เพื่อเอาชนะพวกมัน ในที่สุดสหายของเขาก็เตือนว่าเขากำลังสูญเสียความเป็นมนุษย์" }
addon.books["The Scourge of Lordaeron"][3] = { "313:1234644521:1800762383", "ความกลัวและความมุ่งมั่นของ Arthas กลับกลายเป็นเหตุแห่งหายนะของเขาเอง เขาตามรอยต้นตอของโรคระบาดไปยัง Northrend โดยหมายจะกำจัดภัยนี้ให้สิ้นซาก แต่ท้ายที่สุดเจ้าชาย Arthas กลับตกอยู่ใต้อำนาจอันมหาศาลของลิชคิง ด้วยความเชื่อว่าจะช่วยประชาชนของตนได้ Arthas จึงหยิบ Frostmourne ดาบรูนต้องสาปขึ้นมา" }
addon.books["The Scourge of Lordaeron"][4] = { "357:1897838244:594595217", "แม้ดาบจะมอบพลังที่เหนือหยั่งถึงให้เขา แต่มันก็ช่วงชิงวิญญาณของเขาและเปลี่ยนเขาให้เป็นเดธไนต์ที่ยิ่งใหญ่ที่สุดของลิชคิง เมื่อไร้ซึ่งวิญญาณและสติแตกสลาย Arthas ก็นำสเคิร์จเข้าจู่โจมอาณาจักรของตนเอง ในที่สุดเขาสังหารกษัตริย์ Terenas พระบิดาของตน แล้วบดขยี้ Lordaeron ลงใต้ส้นเหล็กของลิชคิง" }
addon.books["The Sentinels and the Long Vigil"][2] = { "292:1229029819:2128207248", "Tyrande ผู้ขึ้นเป็นมหานักบวชแห่ง Elune ขอร้อง Malfurion คนรักของนางว่าอย่าจากนางไปสู่ความฝันมรกตของ Ysera แต่ Malfurion ผู้ผูกพันด้วยเกียรติที่จะต้องเข้าสู่เส้นทางแห่งความฝันอันแปรเปลี่ยน กล่าวอำลานักบวชหญิงและสาบานว่า พวกเขาจะไม่มีวันพรากจากกันตราบใดที่ยังซื่อตรงต่อความรัก" }
addon.books["The Sentinels and the Long Vigil"][3] = { "412:357214171:937680942", "เมื่อถูกทิ้งให้คอยปกป้อง Kalimdor จากอันตรายของโลกใหม่เพียงลำพัง Tyrande จึงรวบรวมกองกำลังรบอันแข็งแกร่งจากพี่น้องไนต์เอลฟ์หญิงของนาง เหล่านักรบหญิงผู้ไร้ความกลัวและผ่านการฝึกฝนอย่างดี ซึ่งปฏิญาณจะปกป้อง Kalimdor กลายเป็นที่รู้จักในนามเซนทิเนล แม้พวกนางจะชอบลาดตระเวนป่าอันร่มครึ้มของ Ashenvale ด้วยตนเอง แต่ก็มีพันธมิตรมากมายที่พร้อมให้เรียกขอความช่วยเหลือยามฉุกเฉิน" }
addon.books["The Sentinels and the Long Vigil"][4] = { "304:11231243:838482007", "Cenarius ผู้เป็นกึ่งเทพยังอยู่ใกล้ ๆ ใน Moonglades แห่ง Mount Hyjal เหล่าบุตรชายของเขาซึ่งรู้จักกันในนามผู้พิทักษ์พงไพร เฝ้าดูแลไนต์เอลฟ์อย่างใกล้ชิดและช่วยเซนทิเนลรักษาความสงบในดินแดนอยู่เสมอ แม้แต่เหล่าดรายแอด บุตรสาวผู้ขี้อายของ Cenarius ก็ปรากฏตัวให้เห็นบ่อยขึ้นเรื่อย ๆ" }
addon.books["The Sentinels and the Long Vigil"][5] = { "397:1342637371:724817981", "หน้าที่ดูแลความสงบใน Ashenvale ทำให้ Tyrande ยุ่งอยู่เสมอ แต่เมื่อไม่มี Malfurion เคียงข้าง นางแทบไม่รู้จักความสุข ขณะที่กาลเวลาหลายศตวรรษอันยาวนานผ่านไปและเหล่าดรูอิดยังคงหลับใหล ความกลัวว่าปีศาจจะบุกมาอีกครั้งก็เพิ่มขึ้น นางไม่อาจสลัดความรู้สึกไม่สบายใจว่า Burning Legion อาจยังอยู่ที่ใดสักแห่ง ไกลพ้นห้วง Great Dark บนฟากฟ้า คอยวางแผนแก้แค้นไนต์เอลฟ์และโลก Azeroth" }

